window.KNOWLEDGEWALK_SEARCH = [{"id": "venice-winged-lion", "title": "\ubca0\ub124\uce58\uc544\uc5d0\uc11c\ub294 \uc0ac\uc790\uc5d0\uac8c\ub3c4 \ub0a0\uac1c\uac00 \uc788\ub2e4", "summary": "\uad11\uc7a5\uc5d0\ub3c4, \uac74\ubb3c \ubcbd\uc5d0\ub3c4, \uae30\ub150\ud488 \uac00\uac8c\uc5d0\ub3c4. \ubca0\ub124\uce58\uc544\uc758 \uc0ac\uc790\ub294 \uc65c \ub0a0\uac1c\uc640 \ucc45\uc744 \ucc59\uacbc\uc744\uae4c\uc694?", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/venice-winged-lion/index.html", "image": "../media/venice-winged-lion.jpg", "alt": "\ud3bc\uce5c \ucc45\uc5d0 \uc55e\ubc1c\uc744 \uc5b9\uc740 \ub0a0\uac1c \ub2ec\ub9b0 \uc0ac\uc790\uc758 \uc218\ucc44\ud654\ud48d \uc0bd\ud654", "text": "\ubca0\ub124\uce58\uc544\uc5d0\uc11c\ub294 \uc0ac\uc790\uc5d0\uac8c\ub3c4 \ub0a0\uac1c\uac00 \uc788\ub2e4 \ub0a0\uac1c\uc640 \ucc45\uc744 \ucc59\uae34 \uc0ac\uc790\uac00 \ub3c4\uc2dc\uc758 \uc5bc\uad74\uc774 \ub41c \uc0ac\uc5f0 \uad11\uc7a5\uc5d0\ub3c4, \uac74\ubb3c \ubcbd\uc5d0\ub3c4, \uae30\ub150\ud488 \uac00\uac8c\uc5d0\ub3c4. \ubca0\ub124\uce58\uc544\uc758 \uc0ac\uc790\ub294 \uc65c \ub0a0\uac1c\uc640 \ucc45\uc744 \ucc59\uacbc\uc744\uae4c\uc694? \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ubca0\ub124\uce58\uc544\uc5d0\uc11c\ub294 \uc0ac\uc790\ub97c \ub9cc\ub0a0 \uc900\ube44\ub97c \uc870\uae08 \ud574\uc57c \ud55c\ub2e4. \ub3d9\ubb3c\uc6d0\uc774 \uc544\ub2c8\ub77c \uad11\uc7a5\uacfc \uac74\ubb3c \ubcbd\uc5d0\uc11c \ub9d0\uc774\ub2e4. \uae30\ub150\ud488 \uac00\uac8c\uae4c\uc9c0 \ub4e4\uc5b4\uac00\uba74 \uc0ac\uc790\ub97c \ud53c\ud558\uae30\uac00 \ub354 \uc5b4\ub824\uc6cc\uc9c4\ub2e4. \uadf8\ub7f0\ub370 \uc774 \ub3c4\uc2dc\uc758 \uc0ac\uc790\ub294 \uc900\ube44\ubb3c\uc774 \ub9ce\ub2e4. \ub4f1\uc5d0 \ub0a0\uac1c\ub97c \ub2ec\uc558\uace0, \uc55e\ubc1c\uc5d0\ub294 \ucc45\uae4c\uc9c0 \ucc59\uacbc\ub2e4. \uac08\uae30\ub9cc\uc73c\ub85c\ub3c4 \ucda9\ubd84\ud788 \ub208\uc5d0 \ub74c \ud150\ub370, \uad73\uc774 \uc774 \ub450 \uac00\uc9c0\ub97c \ub354\ud588\ub2e4. \uc65c \ud558\ud544 \ub0a0\uac1c\uc640 \ucc45\uc77c\uae4c? \uc0ac\uc5f0\uc758 \uc8fc\uc778\uacf5\uc740 \uc131 \ub9c8\ub974\ucf54\ub2e4. \uadf8\ub9ac\uc2a4\ub3c4\uad50\uc5d0\uc11c \ub9c8\ub974\ucf54\ub294 \ubcf5\uc74c\uc11c \uc800\uc790\ub85c \uc804\ud574\uc9c0\ub294 \uc778\ubb3c\uc774\uba70, \ub0a0\uac1c \ub2ec\ub9b0 \uc0ac\uc790\ub294 \uadf8\ub97c \ub098\ud0c0\ub0b4\ub294 \uc0c1\uc9d5\uc774\ub2e4. \uc61b \uc885\uad50 \uadf8\ub9bc\uc5d0\uc11c\ub294 \uc0ac\ub78c\uc758 \uc774\ub984\uc744 \ud06c\uac8c \uc368 \ubd99\uc774\ub294 \ub300\uc2e0, \ud2b9\uc815\ud55c \ub3d9\ubb3c\uc774\ub098 \ubb3c\uac74\uc73c\ub85c \ub204\uad6c\uc778\uc9c0 \uc54c\ub824\uc8fc\uace4 \ud588\ub2e4. \ub9c8\ub974\ucf54\uc758 \uacbd\uc6b0\uc5d0\ub294 \uc0ac\uc790\uac00 \uadf8\ub7f0 \uc5ed\ud560\uc744 \ud588\ub2e4. \ub0a0\uac1c\ub294 \uc774 \uc0ac\uc790\uac00 \ucd08\uc6d0\uc5d0\uc11c \uc0ac\ub0e5\ud558\ub294 \ubcf4\ud1b5 \uc0ac\uc790\uac00 \uc544\ub2c8\ub77c, \uc885\uad50\uc801 \uc0c1\uc9d5\uc774\ub77c\ub294 \uac83\uc744 \ubcf4\uc5ec\uc900\ub2e4. \uc870\uae08 \uba40\uac8c \ub290\uaef4\uc9c4\ub2e4\uba74 \uc774\ub984\ud45c\ub77c\uace0 \uc0dd\uac01\ud574\ub3c4 \uc88b\ub2e4. \uadf8\ub9bc \uc18d\uc5d0 \ub0a0\uac1c \ub2ec\ub9b0 \uc0ac\uc790\uac00 \ub4f1\uc7a5\ud558\uba74, \uadf8\ub9ac\uc2a4\ub3c4\uad50\uc758 \uc0c1\uc9d5\uc5d0 \uc775\uc219\ud55c \uc0ac\ub78c\uc740 \ub9c8\ub974\ucf54\ub97c \ub5a0\uc62c\ub9b4 \uc218 \uc788\uc5c8\ub2e4. \ubb3c\ub860 \ubaa8\ub4e0 \uc2dc\ub300\uc758 \ubaa8\ub4e0 \uc0ac\uc790\uac00 \uac19\uc740 \ub73b\uc778 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubca0\ub124\uce58\uc544\uc758 \uc774 \uc0ac\uc790\ub294 \uadf8 \uc804\ud1b5 \uc548\uc5d0 \uc788\ub2e4. \ubca0\ub124\uce58\uc544\ub294 \uc131 \ub9c8\ub974\ucf54\ub97c \ub3c4\uc2dc\uc758 \uc218\ud638\uc131\uc778\uc73c\ub85c \ubaa8\uc168\ub2e4. \uc0b0\ub9c8\ub974\ucf54 \uad11\uc7a5\uacfc \uc0b0\ub9c8\ub974\ucf54 \ub300\uc131\ub2f9\uc758 \u2018\ub9c8\ub974\ucf54\u2019\ub3c4 \uac19\uc740 \uc774\ub984\uc774\ub2e4. \uadf8\ub7ec\ub2c8 \uadf8\uc758 \uc0c1\uc9d5\uc778 \uc0ac\uc790\uac00 \ub3c4\uc2dc\uc758 \uc5bc\uad74\uc774 \ub41c \ub370\uc5d0\ub294 \ub098\ub984\uc758 \uc774\uc720\uac00 \uc788\uc5c8\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc131\uc778\uc744 \uac00\ub9ac\ud0a4\ub358 \uadf8\ub9bc\uc774, \ubca0\ub124\uce58\uc544\uc5d0\uc11c\ub294 \ub3c4\uc2dc\uc640 \uc61b \uacf5\ud654\uad6d\uc744 \uac00\ub9ac\ud0a4\ub294 \ud45c\uc9c0\uac00 \ub41c \uac83\uc774\ub2e4. \uc131 \ub9c8\ub974\ucf54\ub97c \ub530\ub77c\uc628 \uc0ac\uc790\uac00 \ub3c4\uc2dc \uc804\uccb4\uc758 \uac04\ud310\uae4c\uc9c0 \ub9e1\uac8c \ub41c \uc148\uc774\ub2e4. \ub0a0\uac1c\ubcf4\ub2e4 \ucc45\uc774 \ub354 \uad81\uae08\ud560 \uc218\ub3c4 \uc788\ub2e4. \uc0ac\uc790\ub294 \ucc45\uc744 \uc77d\ub294 \uc911\uc77c\uae4c, \uc544\ub2c8\uba74 \uc911\uc694\ud55c \ub0b4\uc6a9\uc744 \uc6b0\ub9ac\uc5d0\uac8c \ubcf4\uc5ec\uc8fc\ub294 \uc911\uc77c\uae4c? \ud3bc\uccd0\uc9c4 \ucc45\uc5d0\ub294 \ub9c8\ub974\ucf54\uc5d0\uac8c \ud3c9\ud654\ub97c \uc804\ud558\ub294 \ub73b\uc758 \ub77c\ud2f4\uc5b4 \ubb38\uad6c\uac00 \uc801\ud78c \uc608\uac00 \uc788\ub2e4. \uc0b0\ub9c8\ub974\ucf54 \ub300\uc131\ub2f9\uc758 \uacf5\uc2dd \uc124\uba85\uc5d0\uc11c\ub3c4 \uc774 \ubb38\uad6c\uc640 \ub0a0\uac1c \ub2ec\ub9b0 \uc0ac\uc790\ub97c \ud568\uaed8 \uc18c\uac1c\ud55c\ub2e4. \ub2e8\uc21c\ud788 \ubc15\uc2dd\ud55c \uc0ac\uc790\ub97c \ub9cc\ub4e4\ub824\uace0 \ucc45\uc744 \ubcf4\ud0e0 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc0ac\uc790\uc640 \ucc45\uc774 \ud568\uaed8 \uc788\uc5b4\uc57c \ub204\uad6c\uc758 \uc0c1\uc9d5\uc778\uc9c0 \ub354 \ubd84\uba85\ud574\uc9c4\ub2e4. \ucc45\uae4c\uc9c0 \uacc1\ub4e4\uc774\uba74 \uc0ac\uc790\uc758 \ubaa8\uc2b5\uc740 \uc870\uae08 \ub2ec\ub77c\uc9c4\ub2e4. \ud798\uc13c \ub3d9\ubb3c\uc5d0\uac8c \uc870\uc6a9\ud788 \uc77d\uc744\uac70\ub9ac\ub97c \uac74\ub128 \ub4ef \ubcf4\uc774\uc9c0\ub9cc, \uc0ac\uc2e4\uc740 \uc131\uc778\uc744 \uc54c\uc544\ubcf4\uac8c \ud558\ub294 \uc5ec\ub7ec \ud45c\uc2dc\uac00 \ud568\uaed8 \ub193\uc778 \uac83\uc774\ub2e4. \uc61b \uadf8\ub9bc\uacfc \uc870\uac01\uc5d0\uc11c\ub294 \uc774\ub7f0 \ubb3c\uac74 \ud558\ub098\uac00 \ub4f1\uc7a5\uc778\ubb3c\uc758 \uc774\ub984\uc744 \uc54c\ub824\uc8fc\uae30\ub3c4 \ud588\ub2e4. \ucc45\uc5d0 \uae00\uc528\uac00 \uc788\ub2e4\uba74 \ubb34\uc5c7\uc774 \uc801\ud614\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc544\ub3c4 \uc88b\ub2e4. \ub2e4\ub9cc \uae00\uc790\uac00 \ub0a1\uc544 \uc798 \ubcf4\uc774\uc9c0 \uc54a\uac70\ub098, \ub192\uc774 \uc788\uc5b4 \uc77d\uae30 \uc5b4\ub824\uc6b8 \uc218\ub3c4 \uc788\ub2e4. \uadf8\ub7f4 \ub54c\ub294 \uac00\uae4c\uc774 \ub2e4\uac00\uac00\ub824 \uc560\uc4f0\uae30\ubcf4\ub2e4 \ud604\uc7a5\uc758 \uc548\ub0b4\ub098 \uc18c\uc7a5 \uae30\uad00\uc758 \uc124\uba85\uc744 \ucc3e\uc544\ubcf4\uba74 \ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uac10\uc0c1\uc774 \ubcf5\uc7a1\ud574\uc9c8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ucc45\uc774 \uc788\ub294\uc9c0, \ub0a0\uac1c\ub294 \uc5b4\ub5a4 \ubaa8\uc591\uc778\uc9c0, \ud45c\uc815\uc740 \uc5b4\ub5a4\uc9c0\ub9cc \ubcf4\uc544\ub3c4 \uc0ac\uc790\ub9c8\ub2e4 \uc870\uae08\uc529 \ub2e4\ub974\ub2e4\ub294 \uac83\uc744 \ubc1c\uacac\ud558\uac8c \ub41c\ub2e4. \uc815\ub2f5\uc744 \ub9de\ud788\ub294 \ub300\uc2e0 \ucc28\uc774\ub97c \ucc3e\ub294 \uad6c\uacbd\uc774\ub2e4. \uac19\uc740 \ub0a0\uac1c\uc640 \ucc45\uc774 \uc788\uc5b4\ub3c4 \uc5b4\ub514\uc5d0 \ub193\uc600\ub294\uc9c0\uc5d0 \ub530\ub77c \ub9cc\ub098\uac8c \ub418\ub294 \uc774\uc57c\uae30\ub294 \uc870\uae08 \ub2ec\ub77c\uc9c4\ub2e4. \uc131\ub2f9\uc758 \uc815\uba74\uc5d0\uc11c\ub294 \uc131\uc778\uacfc \uc2e0\uc559\uc758 \uc804\ud1b5\uc744, \ub3c4\uc2dc\uc758 \uc7a5\uc2dd\uc5d0\uc11c\ub294 \ubca0\ub124\uce58\uc544\ub77c\ub294 \uc7a5\uc18c\uc758 \uc815\uccb4\uc131\uc744 \ud568\uaed8 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uc774\ubbf8\uc9c0\ub97c \uc54c\uc544\ubcf4\ub294 \uac83\uacfc \uadf8 \uc774\ubbf8\uc9c0\uac00 \ud2b9\uc815 \uc790\ub9ac\uc5d0 \ub193\uc778 \uc774\uc720\ub97c \uc77d\ub294 \uac83\uc740 \uc5f0\uacb0\ub418\uc9c0\ub9cc \uac19\uc740 \ub2e8\uacc4\ub294 \uc544\ub2c8\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uc0ac\uc790\ub97c \ucc3e\uc558\ub2e4\uba74 \uace7\ubc14\ub85c \ud45c\uc815\ub9cc \ud655\ub300\ud558\uae30 \uc804\uc5d0 \uc8fc\ubcc0\uc744 \uc870\uae08 \ub113\uac8c \ubcf4\uc790. \uac74\ubb3c\uc758 \uc911\uc2ec \uac00\uae4c\uc774\uc5d0 \uc788\ub294\uc9c0, \ubb38\uc774\ub098 \ub2e4\ub978 \uc7a5\uc2dd\uacfc \uc5b4\ub5a4 \uad00\uacc4\uc778\uc9c0 \uc0b4\ud3b4\ubcf4\uba74 \ub41c\ub2e4. \uc774\ub54c \ubaa8\ub4e0 \uc0ac\uc790\uc5d0\uac8c \ud558\ub098\uc758 \uc815\ub2f5\uc744 \uc801\uc6a9\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uac1c\ubcc4 \uc791\ud488\uc758 \uc81c\uc791 \uc2dc\uae30\uc640 \uc124\uba85\uc744 \ud655\uc778\ud560\uc218\ub85d \uc775\uc219\ud55c \uc0c1\uc9d5 \uc548\uc758 \ucc28\uc774\ub3c4 \ub354 \uc798 \ubcf4\uc778\ub2e4. \uc0b0\ub9c8\ub974\ucf54 \ub300\uc131\ub2f9\uc758 \uc815\uba74\uc744 \uc62c\ub824\ub2e4\ubcf4\uba74 \uc7a5\uc2dd \uc0ac\uc774\uc5d0 \uc790\ub9ac \uc7a1\uc740 \uc0ac\uc790\ub97c \ubc1c\uacac\ud560 \uc218 \uc788\ub2e4. \uc5ec\ub7ec \uc544\uce58 \uac00\uc6b4\ub370 \uc911\uc2ec\uc774 \ub418\ub294 \ubd80\ubd84 \uc704\ucabd\uc774\ub2e4. \uc131\uc778\uc744 \uc0c1\uc9d5\ud558\ub294 \uc0ac\uc790\uac00 \uadf8 \uc131\uc778\uc744 \ubaa8\uc2e0 \uac74\ubb3c\uc5d0\uc11c\ub3c4 \uc5bc\uad74\uc744 \ub0b4\ubc00\uace0 \uc788\ub294 \uc148\uc774\ub2e4. \ub2e4\ub978 \uc0ac\uc790\ub4e4\uc740 \uac74\ubb3c\uc758 \ubcbd\uc774\ub098 \uc7a5\uc2dd \uc18d\uc5d0 \ub4e4\uc5b4\uac00 \uc788\ub2e4. \uc5b4\ub5a4 \uac83\uc740 \uc704\uc5c4 \uc788\uac8c \uc55e\uc744 \ubcf4\uace0, \uc5b4\ub5a4 \uac83\uc740 \uc606\ubaa8\uc2b5\uc744 \ubcf4\uc5ec\uc900\ub2e4. \uae30\ub150\ud488 \uc18d\uc73c\ub85c \ub4e4\uc5b4\uac00\uba74 \ubd84\uc704\uae30\uac00 \ud55c\uacb0 \ubd80\ub4dc\ub7ec\uc6cc\uc9c4\ub2e4. \ub098\ub77c\ub97c \ub300\ud45c\ud558\ub358 \uc0c1\uc9d5\uc774 \uc190\ubc14\ub2e5\ub9cc \ud55c \ubb3c\uac74\uc774 \ub418\uc5b4 \uc5ec\ud589 \uac00\ubc29\uc5d0 \uc2e4\ub824 \uac00\uae30\ub3c4 \ud55c\ub2e4. \uc0ac\uc790\ub97c \uc54c\uc544\ubcf4\ub294 \ub370 \uc775\uc219\ud574\uc9c0\uba74 \uac74\ubb3c\uc758 \uc7a5\uc2dd\ub3c4 \uc804\uacfc \ub2e4\ub974\uac8c \ubcf4\uc778\ub2e4. \uc5b4\ub5a4 \ub3d9\ubb3c\uc740 \uc774\uc57c\uae30\ub97c \ub098\ud0c0\ub0b4\uace0, \uc5b4\ub5a4 \ub3d9\ubb3c\uc740 \ud2b9\uc815 \uc778\ubb3c\uc744 \uc54c\ub824\uc900\ub2e4. \ubaa8\uc591\uc774 \ube44\uc2b7\ud574\ub3c4 \ub298 \uac19\uc740 \ub73b\uc740 \uc544\ub2c8\ub2c8, \ud2b9\ubcc4\ud788 \uad81\uae08\ud55c \uc870\uac01\uc740 \uadf8 \uac74\ubb3c\uc758 \uc124\uba85\uacfc \ud568\uaed8 \ubcf4\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc774 \uc815\ub3c4\ub9cc \uc54c\uace0 \uac78\uc5b4\ub3c4 \uc5ec\ud589\uc758 \ud48d\uacbd\uc774 \uc870\uae08 \ub2ec\ub77c\uc9c4\ub2e4. \ubc29\uae08 \uc9c0\ub098\uce5c \ubcbd\uc758 \uc7a5\uc2dd\uc774 \ub2e8\uc21c\ud55c \ub3d9\ubb3c\uc774 \uc544\ub2c8\ub77c\ub294 \uac83\uc744 \uc54c\uc544\ubcf4\uac8c \ub41c\ub2e4. \uae00\uc790\ub97c \uc77d\uc9c0 \ubabb\ud574\ub3c4 \uc791\uc740 \uadf8\ub9bc \ud558\ub098\uac00 \ub3c4\uc2dc\uc758 \uc774\ub984\uc744 \uc54c\ub824\uc8fc\ub294 \uc148\uc774\ub2e4. \ubca0\ub124\uce58\uc544\uc5d0 \uac04\ub2e4\uba74 \uc0ac\uc790 \ud55c \ub9c8\ub9ac\ucbe4\uc740 \ucc3e\uc544\ubcf4\uc544\ub3c4 \uc88b\uaca0\ub2e4. \uc131\ub2f9\uc758 \ub192\uc740 \uacf3\uc5d0 \uc788\ub294 \uc0ac\uc790\uc5ec\ub3c4 \uc88b\uace0, \uac00\uac8c \uc9c4\uc5f4\uc7a5 \uc18d\uc758 \uc791\uc740 \uc0ac\uc790\uc5ec\ub3c4 \uc88b\ub2e4. \ub0a0\uac1c\uc640 \ucc45\uc744 \ud655\uc778\ud588\ub2e4\uba74, \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \uc5bc\uad74\uc744 \ud55c\ubc88 \ubcf4\uc790. \ub3c4\uc2dc\ub97c \ub300\ud45c\ud558\ub294 \uc77c\uc774 \uc81c\ubc95 \uadfc\uc5c4\ud55c \uc77c\uc778\uc9c0, \uc544\ub2c8\uba74 \uae30\ub150\ud488 \uac00\uac8c \uadfc\ubb34\uac00 \ub354 \ub9c8\uc74c\uc5d0 \ub4dc\ub294\uc9c0. \uadf8 \ud45c\uc815\ub9cc\ud07c\uc740 \ubcf4\ub294 \uc0ac\ub78c\uc774 \uc870\uae08 \uc790\uc720\ub86d\uac8c \uc77d\uc5b4\ub3c4 \uad1c\ucc2e\ub2e4."}, {"id": "alexandria-museion-and-books", "title": "\uc54c\ub809\uc0b0\ub4dc\ub9ac\uc544 \u2014 \ud56d\uad6c \ub3c4\uc2dc\ub294 \uc65c \ud559\uc790\ub4e4\uc744 \ubaa8\uc558\uc744\uae4c", "summary": "\ubb34\uc138\uc774\uc628\uacfc \ub3c4\uc11c\uad00\uc744 \ud1b5\ud574 \ud5ec\ub808\ub2c8\uc998 \ub3c4\uc2dc\uc758 \ud559\ubb38\u00b7\uc5b8\uc5b4\u00b7\uc815\uce58 \ud6c4\uc6d0\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/alexandria-museion-and-books/index.html", "image": "../media/alexandria-museion-and-books.png", "alt": "\ud56d\uad6c\uac00 \ubcf4\uc774\ub294 \uc0c1\uc0c1 \uc18d \ubc29\uc5d0\uc11c \ub450 \uc0ac\ub78c\uc774 \ub450\ub8e8\ub9c8\ub9ac\ub97c \uc0b4\ud53c\ub294 \uc0bd\ud654.", "text": "\uc54c\ub809\uc0b0\ub4dc\ub9ac\uc544 \u2014 \ud56d\uad6c \ub3c4\uc2dc\ub294 \uc65c \ud559\uc790\ub4e4\uc744 \ubaa8\uc558\uc744\uae4c \ubc15\ubb3c\uad00\uc774\ub77c\ub294 \ub9d0\uc758 \uba3c \ucd9c\ubc1c\uc810\uc5d0\uc11c \ub9cc\ub098\ub294 \uc5f0\uad6c\uc640 \ud6c4\uc6d0 \ubb34\uc138\uc774\uc628\uacfc \ub3c4\uc11c\uad00\uc744 \ud1b5\ud574 \ud5ec\ub808\ub2c8\uc998 \ub3c4\uc2dc\uc758 \ud559\ubb38\u00b7\uc5b8\uc5b4\u00b7\uc815\uce58 \ud6c4\uc6d0\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ud56d\uad6c\uc5d0\ub294 \ubc30\uc640 \ubb3c\uac74\uc774 \ubaa8\uc778\ub2e4. \uadf8\ub7f0\ub370 \uace0\ub300 \uc54c\ub809\uc0b0\ub4dc\ub9ac\uc544\uc5d0\ub294 \ud559\uc790\uc640 \ucc45\ub3c4 \ubaa8\uc600\ub2e4. \uc2dc\uc7a5\uc5d0\uc11c \uac70\ub798\ud558\ub294 \uc9d0\uacfc \uc5f0\uad6c\uc5d0 \uc4f0\ub294 \ub450\ub8e8\ub9c8\ub9ac\ub294 \ub2e4\ub974\uc9c0\ub9cc, \uba40\ub9ac \uc788\ub294 \uac83\uc744 \ud55c\uacf3\uc5d0 \ubaa8\uc740\ub2e4\ub294 \uc810\uc5d0\uc11c\ub294 \ub2ee\uc740 \ubaa8\uc2b5\uc774 \uc788\ub2e4. \uc774 \ub3c4\uc2dc\uc758 \ub3c4\uc11c\uad00\uc740 \ub108\ubb34 \uc720\uba85\ud574\uc11c \uc0ac\ub77c\uc9c4 \uc21c\uac04\uc758 \uc774\uc57c\uae30\ub9cc \uba3c\uc800 \ub5a0\uc62c\ub9ac\uae30\ub3c4 \ud55c\ub2e4. \uc624\ub298\uc740 \ubd88\uae38 \ub300\uc2e0 \uadf8\ubcf4\ub2e4 \uc55e\uc120 \uc9c8\ubb38\uc5d0\uc11c \uc2dc\uc791\ud574 \ubcf4\uc790. \ub204\uac00 \uc65c \uc774\ub7f0 \ub3c4\uc2dc\uc5d0\uc11c \ud559\ubb38\uc744 \ud6c4\uc6d0\ud588\uace0, \uc0ac\ub78c\ub4e4\uc774 \ub9d0\ud558\ub294 \ubb34\uc138\uc774\uc628\uc740 \uc5b4\ub5a4 \uacf5\uac04\uc774\uc5c8\uc744\uae4c. \uc54c\ub809\uc0b0\ub4dc\ub9ac\uc544\ub294 \uc54c\ub809\uc0b0\ub4dc\ub85c\uc2a4\uac00 \uae30\uc6d0\uc804 331\ub144\uc5d0 \uc138\uc6e0\ub2e4. \uadf8\uc758 \uc8fd\uc74c \ub4a4 \uc81c\uad6d\uc740 \uc5ec\ub7ec \ud6c4\uacc4\uc790\uc758 \uc655\uad6d\uc73c\ub85c \ub098\ub258\uc5c8\uace0, \uc774\uc9d1\ud2b8\ub294 \ud504\ud1a8\ub808\ub9c8\uc774\uc624\uc2a4 \uc655\uc870\uc758 \uc9c0\ubc30 \uc544\ub798 \ub4e4\uc5b4\uac14\ub2e4. \uc54c\ub809\uc0b0\ub4dc\ub9ac\uc544\ub294 \uadf8 \uc655\uad6d\uc758 \uc218\ub3c4\uac00 \ub418\uc5c8\ub2e4. \uc0c8 \ub3c4\uc2dc\ub294 \uc774\ub984\ub09c \uc815\ubcf5\uc790\uc758 \uae30\ub150\ube44\uc778 \ub3d9\uc2dc\uc5d0 \ud6c4\uacc4 \uc655\uc870\uac00 \ud1b5\uce58\ud558\ub294 \ud604\uc2e4\uc758 \uc911\uc2ec\uc774\uc5c8\ub2e4. \uac74\ubb3c\uc744 \uc138\uc6b0\uace0 \uc0ac\ub78c\uc744 \ubaa8\uc73c\uba70 \uadf8\uacf3\uc744 \uc911\uc694\ud55c \uc7a5\uc18c\ub85c \ub9cc\ub4dc\ub294 \uc120\ud0dd\uc774 \uc774\uc5b4\uc84c\ub2e4. \ub3c4\uc2dc\uc758 \ubb38\ud654\uc801 \uba85\uc131\uc744 \ucc3d\uac74\uc790 \ud55c \uc0ac\ub78c\uc758 \uad6c\uc0c1\uc73c\ub85c\ub9cc \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b4 \uc774\uc720\ub2e4. \ud504\ud1a8\ub808\ub9c8\uc774\uc624\uc2a4 \uc655\ub4e4\uc740 \ubb34\uc138\uc774\uc628\uc744 \uc138\uc6e0\ub2e4. \uc774\ub984\uc740 \ubb34\uc0ac\uc774, \uc989 \uc608\uc220\uacfc \ud559\ubb38\uc5d0 \uad00\ub828\ub41c \uc5ec\uc2e0\ub4e4\uc758 \uc9d1\uc774\ub77c\ub294 \ub73b\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc624\ub298\ub0a0 \ubc15\ubb3c\uad00\uc744 \uac00\ub9ac\ud0a4\ub294 museum\uc774\ub77c\ub294 \ub9d0\uc758 \uc5b4\uc6d0\ub3c4 \uc5ec\uae30\uc5d0\uc11c \ub098\uc628\ub2e4. \ud558\uc9c0\ub9cc \ub2f9\uc2dc\uc758 \ubb34\uc138\uc774\uc628\uc744 \uc624\ub298\ub0a0 \uad00\ub78c\uac1d\uc774 \uc804\uc2dc\ud488 \uc0ac\uc774\ub97c \uac77\ub294 \ubc15\ubb3c\uad00\uacfc \ub611\uac19\uc774 \uc0dd\uac01\ud558\uba74 \uace4\ub780\ud558\ub2e4. \uad50\uc7ac\ub294 \uc774\ub97c \uacfc\ud559 \uc5f0\uad6c\uc640 \ubb38\ud559 \uc5f0\uad6c\uc758 \uc911\uc2ec\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \uc775\uc219\ud55c \ub2e8\uc5b4\uc758 \uc5b4\uc6d0\uc744 \uc548\ub2e4\ub294 \uac83\uc740 \ud604\uc7ac\uc758 \uae30\ub2a5\uae4c\uc9c0 \uacfc\uac70\uc5d0 \uadf8\ub300\ub85c \uc788\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud559\uc790\uc758 \ub2a5\ub825\ub9cc\uc73c\ub85c \ud559\ubb38\uc758 \uc911\uc2ec\uc774 \uc800\uc808\ub85c \uc0dd\uae30\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud65c\ub3d9\uc744 \uc9c0\uc18d\ud560 \uacf5\uac04\uacfc \uc790\uc6d0, \ub2e4\ub978 \uc0ac\ub78c\uacfc \uc9c0\uc2dd\uc744 \ub098\ub20c \uc870\uac74\uc774 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uc655\ub4e4\uc774 \uc774\ub7f0 \uae30\uad00\uc744 \ud6c4\uc6d0\ud588\ub2e4\ub294 \uc810\uc740 \uc5f0\uad6c\uc758 \uc5ed\uc0ac\uc640 \uc815\uce58\uc758 \uc5ed\uc0ac\uac00 \ub9cc\ub098\ub294 \ubd80\ubd84\uc774\ub2e4. \uc774\ub97c \uc624\ub298\ub0a0\uc758 \ub300\ud559\uc774\ub098 \uc5f0\uad6c\uc18c \uc870\uc9c1\uacfc \uc77c\ub300\uc77c\ub85c \ub9de\ucd9c \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c \ud655\uc778\ud55c \uc0ac\uc2e4\uc740 \uc655\uc870\uac00 \ud559\ubb38 \uae30\uad00\uacfc \ucc45\uc758 \uc218\uc9d1\uc744 \uc9c0\uc6d0\ud588\ub2e4\ub294 \uc810\uc774\ub2e4. \uadf8 \uc9c0\uc6d0\uc740 \uc5b4\ub5a4 \uc9c0\uc2dd\uc774 \ud55c\uacf3\uc5d0 \ubaa8\uc774\uace0 \ub3c4\uc2dc\uc758 \uc704\uc0c1\uc744 \ub9cc\ub4dc\ub294\uc9c0\uc5d0 \uc601\ud5a5\uc744 \uc8fc\uc5c8\ub2e4. \uc54c\ub809\uc0b0\ub4dc\ub9ac\uc544\uc758 \ub3c4\uc11c\uad00\uc5d0\ub294 \ub9ce\uc740 \ucc45\uc774 \uc218\uc9d1\ub418\uc5c8\ub2e4. \ub2f9\uc2dc\uc758 \ucc45\uc740 \uc624\ub298\ub0a0 \uc11c\uc810\uc758 \uc81c\ubcf8 \ucc45\ub9cc\uc744 \ub5a0\uc62c\ub824\uc11c\ub294 \uc548 \ub41c\ub2e4. \ub450\ub8e8\ub9c8\ub9ac \uac19\uc740 \ub9e4\uccb4\ub85c \uae30\ub85d\ub41c \uc800\uc220\uc744 \ubaa8\uc544 \uc77d\uace0 \ube44\uad50\ud558\ub294 \ud65c\ub3d9\uc774\uc5c8\ub2e4. \uc774 \uae00\uc740 \ud2b9\uc815 \uc11c\uac00\uc758 \ubc30\uce58\ub098 \uc18c\uc7a5 \uc218\ub97c \ubcf5\uc6d0\ud558\uc9c0 \uc54a\ub294\ub2e4. \ucc45\uc774 \ub9ce\ub2e4\ub294 \uac83\uc740 \uc11c\ub85c \ub2e4\ub978 \uae00\uc744 \ub9cc\ub0a0 \uae30\ud68c\uac00 \ub298\uc5b4\ub09c\ub2e4\ub294 \ub73b\uc774\ub2e4. \uac19\uc740 \uc8fc\uc81c\uc758 \ub2e4\ub978 \uc124\uba85\uc744 \ube44\uad50\ud558\uace0 \uc55e\uc120 \uc0ac\ub78c\uc758 \uc9c0\uc2dd\uc744 \ub2e4\uc2dc \uc77d\uc744 \uc218 \uc788\ub2e4. \ud559\ubb38\uc758 \uc911\uc2ec\uc774\ub77c\ub294 \uba85\uc131\uc740 \ub6f0\uc5b4\ub09c \uac1c\uc778\ub9cc\uc758 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub77c \uadf8\uac00 \ub9cc\ub0a0 \uc218 \uc788\ub358 \uc790\ub8cc\uc758 \ud658\uacbd\uacfc\ub3c4 \uc5f0\uacb0\ub41c\ub2e4. \ud5ec\ub808\ub2c8\uc998 \uc2dc\ub300\uc758 \uc54c\ub809\uc0b0\ub4dc\ub9ac\uc544\uc5d0\ub294 \uadf8\ub9ac\uc2a4\uc5b4\ub97c \uc4f0\ub294 \uc0ac\ub78c\uacfc \uc774\uc9d1\ud2b8\uc758 \uae30\uc874 \uc8fc\ubbfc, \uc774\uc8fc\ud55c \uc5ec\ub7ec \uacf5\ub3d9\uccb4\uac00 \uc788\uc5c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc5b8\uc5b4\uc640 \uc804\ud1b5\uc774 \ud55c \ub3c4\uc2dc \uc548\uc5d0\uc11c \ub9cc\ub0ac\ub2e4. \uad8c\ub825\uc758 \uc911\uc2ec\uacfc \uc77c\uc0c1\uc758 \uc5b8\uc5b4\uac00 \uc5b8\uc81c\ub098 \ub611\uac19\uc740 \ud615\ud0dc\ub85c \uc815\ub9ac\ub418\ub294 \uacf5\uac04\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uadf8\ub9ac\uc2a4\uc5b4\ub85c \ud65c\ub3d9\ud558\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc99d\uac00\uc640 \uc815\uce58\uc801 \ud658\uacbd\uc740 \uc9c0\uc2dd\uc774 \uc774\ub3d9\ud558\ub294 \ubc29\uc2dd\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc8fc\uc5c8\ub2e4. \uc5b4\ub5a4 \uae00\uc744 \ub204\uad6c\uc758 \uc5b8\uc5b4\ub85c \uc77d\uac8c \ud560\uc9c0\uc758 \ubb38\uc81c\uac00 \uc0dd\uae34\ub2e4. \ub3c4\uc2dc\uc758 \ud559\ubb38\uc744 \ubb38\ud654\uac00 \uc11e\uc600\ub2e4\ub294 \ub9c9\uc5f0\ud55c \ub9d0\ub85c\ub9cc \uc124\uba85\ud558\uae30\ubcf4\ub2e4 \uc2e4\uc81c\ub85c \uc77d\uace0 \uac00\ub974\uce58\ub294 \uc5b8\uc5b4\ub97c \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 \ud504\ud1a8\ub808\ub9c8\uc774\uc624\uc2a4 \uc2dc\ub300\uc5d0 \ud788\ube0c\ub9ac \uacbd\uc804\uc774 \uadf8\ub9ac\uc2a4\uc5b4\ub85c \ubc88\uc5ed\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc54c\ub809\uc0b0\ub4dc\ub9ac\uc544\uc5d0 \uc774\uc8fc\ud55c \uc720\ub300\uc778 \uacf5\ub3d9\uccb4\uc758 \uc874\uc7ac\uc640\ub3c4 \uc5f0\uacb0\ub418\ub294 \ubcc0\ud654\ub2e4. \uc5b4\ub5a4 \uc804\ud1b5\uc758 \uae00\uc774 \ub2e4\ub978 \uc5b8\uc5b4\ub97c \uc0ac\uc6a9\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c \uc77d\ud790 \uc218 \uc788\uac8c \ub41c \uac83\uc774\ub2e4. \uc5ec\uae30\uc11c \ubc88\uc5ed\uc5d0 \uad00\ud55c \uc720\uba85\ud55c \uc22b\uc790\uc640 \uae30\uc801\uc758 \uc77c\ud654\ub97c \uc0ac\uc2e4\ub85c \ub367\ubd99\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \ud655\uc778\ud560 \uc218 \uc788\ub294 \ud575\uc2ec\ub9cc\uc73c\ub85c\ub3c4 \ud765\ubbf8\ub86d\ub2e4. \ucc45\uc744 \uc62e\uae34\ub2e4\ub294 \uac83\uc740 \uc885\uc774 \ubb49\uce58\ub97c \uc7a5\uc18c\ub9cc \ubc14\uafb8\ub294 \uc77c\ubfd0 \uc544\ub2c8\ub77c, \uadf8 \uae00\uc744 \uc77d\uc744 \uc218 \uc788\ub294 \uc0ac\ub78c\uc758 \ubc94\uc704\ub97c \ubc14\uafb8\ub294 \uc77c\uc774\uae30\ub3c4 \ud588\ub2e4. \uc54c\ub809\uc0b0\ub4dc\ub9ac\uc544\uc758 \ub3c4\uc11c\uad00\uc744 \ud55c \ubc88\uc758 \ud654\uc7ac\uc640 \ud55c \uba85\uc758 \ucc45\uc784\uc790\ub85c\ub9cc \uc124\uba85\ud558\ub294 \uc774\uc57c\uae30\ub294 \uc870\uc2ec\ud574\uc11c \uc77d\uc5b4\uc57c \ud55c\ub2e4. \uc774\ubc88\uc5d0 \ud655\uc778\ud55c \uad50\uc7ac\uc758 \ubc94\uc704\ub294 \ub3c4\uc2dc\uc758 \ud615\uc131\uacfc \ud559\ubb38 \uae30\uad00\uc5d0 \uad00\ud55c \ub0b4\uc6a9\uc774\ub2e4. \ub204\uac00 \ud55c\ub0a0\uc5d0 \ubaa8\ub4e0 \ucc45\uc744 \uc5c6\uc574\ub2e4\ub294 \uc7a5\uba74\uc744 \ub9cc\ub4e4\uc5b4 \ub0bc \uadfc\uac70\ub85c \uc4f0\uc9c0 \uc54a\ub294\ub2e4. \uc720\uba85\ud55c \uc0c1\uc2e4\uc758 \uc774\uc57c\uae30\ubcf4\ub2e4 \uc55e\uc5d0 \uc624\ub798 \uc313\uc740 \ud65c\ub3d9\uc774 \uc788\uc5c8\ub2e4\ub294 \uc810\uc744 \uae30\uc5b5\ud558\uba74 \ub41c\ub2e4. \uc5f0\uad6c\ub97c \ud6c4\uc6d0\ud558\uace0 \uc800\uc220\uc744 \ubaa8\uc73c\uba70 \ubc88\uc5ed\uacfc \uc77d\uae30\ub97c \uc774\uc5b4 \uac04 \uc2dc\uac04\uc774 \ub3c4\uc2dc\uc758 \uc131\uaca9\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \uc0ac\ub77c\uc84c\ub2e4\ub294 \uacb0\ub9d0\ub9cc\uc73c\ub85c\ub294 \uadf8\uacf3\uc5d0\uc11c \ubb34\uc5c7\uc774 \uac00\ub2a5\ud588\ub294\uc9c0 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \ubc14\ub2e4\uac00 \ubcf4\uc774\ub294 \uacf3\uc5d0\uc11c \ub450\ub8e8\ub9c8\ub9ac\ub97c \ube44\uad50\ud558\ub294 \uc0ac\ub78c\ub4e4\uc744 \ud45c\ud604\ud588\ub2e4. \ubb34\uc138\uc774\uc628\uacfc \uace0\ub300 \ub3c4\uc11c\uad00\uc758 \uac74\ucd95\uc744 \uace0\uc99d\ud574 \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ud2b9\uc815 \ud559\uc790\uc758 \uc5f0\uad6c\uc2e4\uc774\ub098 \uc2e4\uc81c \uc7a5\uba74\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uadf8\ub9bc\uc73c\ub85c \ubc1b\uc544\ub4e4\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uc54c\ub809\uc0b0\ub4dc\ub9ac\uc544\ub97c \ub5a0\uc62c\ub9b4 \ub54c\ub294 \ubc30\uac00 \ub2ff\ub294 \uc790\ub9ac\uc640 \ucc45\uc744 \uc77d\ub294 \uc790\ub9ac\ub97c \ud568\uaed8 \ub193\uc544 \ubcf4\uc790. \ub3c4\uc2dc\ub294 \ubb3c\uac74\ubfd0 \uc544\ub2c8\ub77c \uc9c0\uc2dd\uc758 \ub3c4\ucc29\uc9c0\uac00 \ub420 \uc218 \uc788\uc5c8\ub2e4. \uc624\ub298\uc758 \ubc15\ubb3c\uad00\uc774\ub77c\ub294 \ub9d0 \ub4a4\uc5d0 \uc774\ub7f0 \uba3c \uc2dc\uac04\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c\ub3c4, \uc775\uc219\ud55c \ub2e8\uc5b4\uc640 \uc7a5\uc18c\ub97c \ubcf4\ub294 \uc990\uac70\uc6c0\uc774 \uc870\uae08 \ucee4\uc9c4\ub2e4."}, {"id": "amarna-akhenaten-capital-sun-and-afterlife", "title": "\uc544\ub9c8\ub974\ub098 \u2014 \ud0dc\uc591\uc744 \uc704\ud55c \uc218\ub3c4\ub294 \uc65c \uc624\ub798\uac00\uc9c0 \ubabb\ud588\uc744\uae4c", "summary": "\uc544\ucf00\ub098\ud1a4\uc758 \uc774\ub984\uacfc \uc2e0\uc559, \uc0c8 \uc218\ub3c4\uc758 \uac74\ucd95\uacfc \uc0dd\ud65c, \uc774\ud6c4\uc758 \ubcc0\ud654\uc640 \ub0a8\uc740 \uc790\ub8cc\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/amarna-akhenaten-capital-sun-and-afterlife/index.html", "image": "../media/amarna-akhenaten-capital-sun-and-afterlife.jpg", "alt": "\uc544\ucf00\ub098\ud1a4\uacfc \uc655\ube44\uac00 \uace0\uc704 \uad00\ub9ac\ub97c \ubcf4\uc0c1\ud558\ub294 \uc2e4\uc81c \uc720\ubb3c \uc7a5\uba74\uc5d0 \uadfc\uac70\ud55c \uc5ed\uc0ac \ub3c4\ud310", "text": "\uc544\ub9c8\ub974\ub098 \u2014 \ud0dc\uc591\uc744 \uc704\ud55c \uc218\ub3c4\ub294 \uc65c \uc624\ub798\uac00\uc9c0 \ubabb\ud588\uc744\uae4c \uc0c8 \uc774\ub984\uacfc \uc218\ub3c4, \uc655\uc2e4 \ubd80\uc870\uc640 \ub3c4\uc2dc\uc758 \uc0dd\ud65c \uc544\ucf00\ub098\ud1a4\uc758 \uc774\ub984\uacfc \uc2e0\uc559, \uc0c8 \uc218\ub3c4\uc758 \uac74\ucd95\uacfc \uc0dd\ud65c, \uc774\ud6c4\uc758 \ubcc0\ud654\uc640 \ub0a8\uc740 \uc790\ub8cc\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc774\uc9d1\ud2b8\uc758 \ud30c\ub77c\uc624 \uc544\ucf00\ub098\ud1a4\uc740 \uc0c8\ub85c\uc6b4 \uc218\ub3c4\ub97c \uc138\uc6b0\uace0 \ud0dc\uc591 \uc6d0\ubc18 \uc544\ud1a4\uc744 \ud1b5\uce58\uc758 \uc911\uc2ec\uc5d0 \ub193\uc558\ub2e4. \uc624\ub298\ub0a0 \uc544\ub9c8\ub974\ub098\ub85c \ubd80\ub974\ub294 \uc720\uc801\uc5d0\ub294 \uc655\uc758 \ud070 \uad6c\uc0c1\uacfc \uc9e7\uc740 \uc9c0\uc18d, \ubc84\ub824\uc9c4 \ub4a4\uc5d0\ub3c4 \ub0a8\uc740 \uc0dd\ud65c\uc758 \ud754\uc801\uc774 \uacb9\uccd0 \uc788\ub2e4. \uc774\uc0c1\ud55c \uc5bc\uad74\uc758 \uc655\uc774\ub098 \ud55c \uc885\uad50\uc758 \ubc1c\uba85\uc790\ub77c\ub294 \ubcc4\uba85\ubcf4\ub2e4 \ub3c4\uc2dc\ub97c \ub9cc\ub4e4\uace0 \uc62e\uae34 \uc5ed\uc0ac\ub97c \uc0b4\ud3b4\ubcf4\uc790. \uae30\uc6d0\uc804 14\uc138\uae30\uc758 \uc655 \uc544\uba58\ud638\ud14c\ud504 4\uc138\ub294 \uc774\ud6c4 \uc544\ucf00\ub098\ud1a4\uc774\ub77c\ub294 \uc774\ub984\uc744 \uc0ac\uc6a9\ud588\ub2e4. \uc655\uc758 \uc774\ub984\uc740 \uac1c\uc778\uc758 \ucde8\ud5a5\ub9cc\uc774 \uc544\ub2c8\ub77c \uc5b4\ub5a4 \uc2e0\uacfc \uad8c\uc704\ub97c \uc55e\uc138\uc6b0\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \ud45c\uc9c0\uc600\ub2e4. \uc544\ud1a4\uc744 \uac15\uc870\ud558\ub294 \ubcc0\ud654\ub294 \uae30\uc874 \uc2e0\uc559\uacfc \uad81\uc815\uc758 \uad00\uacc4\ub97c \ud754\ub4e4\uc5c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \ud0dc\uc591 \uc22d\ubc30\uac00 \uc774 \uc655\uc5d0\uac8c\uc11c \ucc98\uc74c \uc2dc\uc791\ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774\uc9d1\ud2b8\uc5d0\ub294 \uc774\ubbf8 \uc624\ub798\ub41c \ud0dc\uc591\uc2e0\uc758 \uc804\ud1b5\uc774 \uc788\uc5c8\ub2e4. \uc544\ucf00\ub098\ud1a4\uc758 \ud2b9\ubcc4\ud568\uc740 \uc544\ubb34\uac83\ub3c4 \uc5c6\ub358 \uacf3\uc5d0 \ud0dc\uc591\uc744 \ubc1c\uacac\ud588\ub2e4\ub294 \ub370\ubcf4\ub2e4, \uc544\ud1a4\uc744 \uc911\uc2ec\uc73c\ub85c \uc885\uad50\uc640 \uc655\uad8c\uc758 \uc9c8\uc11c\ub97c \uac15\ud558\uac8c \uc7ac\ud3b8\ud588\ub2e4\ub294 \ub370 \uc788\ub2e4. \uad81\uc815\uc774 \uc790\ub9ac\ub97c \uc62e\uae30\uba74 \uadf8 \uacc1\uc5d0\uc11c \uc0b4\ub358 \uc0ac\ub78c\ub4e4\uc758 \uc0dd\uacc4\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uacf5\uae09\uc744 \ub9e1\uc740 \uc0ac\ub78c\uacfc \uac74\ucd95 \ud604\uc7a5\uc758 \ub178\ub3d9\uc790, \ubb38\uc11c\ub97c \ub2e4\ub8ec \uad00\ub9ac\uc5d0\uac8c \uc0c8 \uc218\ub3c4\ub294 \uc2e0\ud559\uc801 \uad6c\ud638\ubcf4\ub2e4 \uad6c\uccb4\uc801\uc778 \uc774\ub3d9\uacfc \uc77c\uc774\uc5c8\ub2e4. \uc218\ub3c4 \uc774\uc804\uc758 \uc5ed\uc0ac\ub97c \uc655\uc758 \uc120\ud0dd\ub9cc\uc73c\ub85c \uc4f8 \uc218 \uc5c6\ub294 \uc774\uc720\ub2e4. \uc655\uc740 \uae30\uc874\uc758 \uc911\uc694\ud55c \uc911\uc2ec\uc9c0\uc778 \ud14c\ubca0\uc5d0 \uba38\ubb34\ub974\ub294 \ub300\uc2e0 \uc0c8\ub85c\uc6b4 \ub3c4\uc2dc \uc544\ucf00\ud0c0\ud1a4\uc744 \uac74\uc124\ud588\ub2e4. \ub098\uc77c\uac15 \ub3d9\ucabd\uc758 \uc774 \uc7a5\uc18c\uc5d0\ub294 \uad81\uc804\uacfc \uc2e0\uc804, \uad00\uccad\uacfc \uc8fc\uac70\uc9c0\uac00 \ub4e4\uc5b4\uc130\ub2e4. \uc655\uc758 \uc2e0\uc559 \ubcc0\ud654\ub294 \uc758\uc2dd\uc758 \ubb38\uad6c\ub97c \uace0\uce58\ub294 \uc218\uc900\uc744 \ub118\uc5b4 \uad6d\uac00\uc758 \uacf5\uac04\uc744 \uc62e\uae30\ub294 \uc77c\uc774 \ub418\uc5c8\ub2e4. \uc0c8\ub85c\uc6b4 \uc218\ub3c4\ub97c \ub9cc\ub4dc\ub294 \ub370\uc5d0\ub294 \ub9ce\uc740 \uc0ac\ub78c\uacfc \ubb3c\uc790, \ub178\ub3d9\uacfc \ud589\uc815\uc774 \ud544\uc694\ud588\ub2e4. \uc655\uc774 \uc774\uc0c1\uc744 \uc120\uc5b8\ud558\ub294 \uc7a5\uba74\ub9cc \ubcf4\uba74 \uadf8 \uc77c\uc744 \uc218\ud589\ud55c \uad00\ub9ac\uc640 \uc7a5\uc778, \ub178\ub3d9\uc790\uc640 \uac00\uc871\uc758 \uc774\ub3d9\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \ub3c4\uc2dc\ub294 \uc774\ub984\uc744 \uc815\ud55c \uc21c\uac04\uc774 \uc544\ub2c8\ub77c \uc218\ub9ce\uc740 \uc77c\uc758 \uc5f0\uacb0\ub85c \uc791\ub3d9\ud55c\ub2e4. \uc544\ud1a4\uc744 \ud5a5\ud55c \uc608\ubc30 \uacf5\uac04\uc5d0\uc11c\ub294 \ud587\ube5b\uc744 \ubc1b\ub294 \uc5f4\ub9b0 \ub730\uacfc \uc81c\ub2e8\uc774 \uc911\uc694\ud55c \uc694\uc18c\uc600\ub2e4. \uc5b4\ub450\uc6b4 \uc548\ucabd\uc73c\ub85c \uae4a\uc774 \ub4e4\uc5b4\uac00\ub294 \uc2e0\uc804\uc758 \uacbd\ud5d8\uacfc\ub294 \ub2e4\ub978 \uacf5\uac04\uc758 \uad6c\uc131\uc774 \ub098\ud0c0\ub0ac\ub2e4. \uc5b4\ub5a4 \uc2e0\uc744 \uc5b4\ub5bb\uac8c \ub9cc\ub098\ub294\uac00\ub77c\ub294 \uc0dd\uac01\uc774 \uac74\ucd95\uc758 \ud615\ud0dc\uc640 \uc5f0\uacb0\ub41c \uac83\uc774\ub2e4. \ub2e4\ub9cc \uc655\uc774 \ud0dc\uc591\uc744 \uac15\uc870\ud588\ub2e4\uace0 \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ubbff\uace0 \uc0dd\ud65c\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc655\uc2e4\uc774 \uc138\uc6b4 \uacf5\uc2dd \uc81c\ub3c4\uc640 \uc9d1 \uc548\uc5d0\uc11c \uc774\uc5b4\uc9c0\ub294 \uad00\uc2b5\uc740 \uc11c\ub85c \ub2e4\ub978 \uc790\ub8cc\ub97c \ud1b5\ud574 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \ud1b5\uce58\uc790\uc758 \uc885\uad50 \uc815\ucc45\uc744 \uc8fc\ubbfc \uc804\uccb4\uc758 \ub9c8\uc74c\uc73c\ub85c \ubc14\uafb8\uc5b4 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc655\uc2e4\uc744 \ud06c\uac8c \ub4dc\ub7ec\ub0b4\ub294 \ubd80\uc870\ub294 \ub204\uac00 \uc2e0\uc758 \ucd95\ubcf5\uacfc \uc7ac\ud654\ub97c \ub098\ub204\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\uae30\ub3c4 \ud588\ub2e4. \uc2e0\uc559\uacfc \ubcf4\uc0c1, \uad00\ub9ac\uc758 \ucda9\uc131\uc774 \ud55c \uc7a5\uba74\uc5d0 \uc5f0\uacb0\ub41c\ub2e4. \uac00\uc871\uc801\uc778 \ubab8\uc9d3\uc774 \ub4f1\uc7a5\ud558\ub294 \ud654\uba74\ub3c4 \uad8c\ub825\uc758 \uc9c8\uc11c\ub97c \ud45c\ud604\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc544\ub9c8\ub974\ub098 \uc2dc\uae30\uc758 \uadf8\ub9bc\uacfc \ubd80\uc870\uc5d0\ub294 \uc655\uacfc \uc655\ube44 \ub124\ud398\ub974\ud2f0\ud2f0, \uc790\ub140\ub4e4\uc774 \ud568\uaed8 \ub4f1\uc7a5\ud558\ub294 \uc7a5\uba74\uc774 \ub208\uc5d0 \ub748\ub2e4. \ud0dc\uc591 \uc6d0\ubc18\uc5d0\uc11c \ubed7\uc740 \uad11\uc120 \ub05d\uc758 \uc190\uc740 \uc655\uc2e4\uacfc \uc2e0\uc758 \uad00\uacc4\ub97c \ubcf4\uc5ec \uc900\ub2e4. \uac00\uc871\uc758 \ubaa8\uc2b5\uc744 \ud1b5\ud574 \uc885\uad50\uc801\u00b7\uc815\uce58\uc801 \uc911\uc2ec\uc744 \uac15\uc870\ud558\ub294 \uc774\ubbf8\uc9c0\ub2e4. \uc790\ub140\ub97c \uac00\uae4c\uc774\ud558\ub294 \ubaa8\uc2b5\uc774 \ubcf4\uc778\ub2e4\uace0 \uc774\uac83\uc744 \uc0ac\uc801\uc778 \uac00\uc871\uc0ac\uc9c4\ucc98\ub7fc \uc77d\uc73c\uba74 \uace4\ub780\ud558\ub2e4. \ubcf4\uc774\ub294 \uc7a5\uba74\uc740 \uc120\ud0dd\ub418\uace0 \uad6c\uc131\ub41c \uc655\uc2e4\uc758 \ud45c\ud604\uc774\ub2e4. \uc774\uc804\uacfc \ub2e4\ub978 \uc778\uccb4\uc640 \uc5bc\uad74\uc758 \ud615\ud0dc\ub97c \ud2b9\uc815 \uc9c8\ubcd1\uc758 \ud655\uc2e4\ud55c \uc99d\uac70\ub85c \ub2e8\uc815\ud558\ub294 \uc77c\ub3c4 \ud53c\ud574\uc57c \ud55c\ub2e4. \uc544\ucf00\ud0c0\ud1a4\uc774 \uc2e0\uc559\uc744 \uc704\ud55c \ub3c4\uc2dc\uc600\ub2e4\uace0 \ud574\ub3c4 \uc0ac\ub78c\ub4e4\uc774 \uc758\ub840\ub9cc \ud558\uba70 \uc0b4 \uc218\ub294 \uc5c6\uc5c8\ub2e4. \ud589\uc815 \ubb38\uc11c\ub97c \uc8fc\uace0\ubc1b\uace0 \uc2dd\ub7c9\uacfc \ubb3c\uac74\uc744 \uc870\ub2ec\ud558\uba70 \uc9d1\uc744 \uc720\uc9c0\ud574\uc57c \ud588\ub2e4. \uc655\uc2e4\uc758 \ub300\uc678 \uad00\uacc4\uc640 \uad00\ub8cc\uc758 \uc77c \uc5ed\uc2dc \uc0c8 \uc218\ub3c4\uc758 \uc77c\uc0c1\uc5d0 \ud3ec\ud568\ub418\uc5c8\ub2e4. \uc544\ub9c8\ub974\ub098 \uc11c\uc2e0\uc73c\ub85c \uc54c\ub824\uc9c4 \ubb38\uc11c\ub4e4\uc740 \uc774\uc9d1\ud2b8 \uc655\uc2e4\uacfc \uc8fc\ubcc0 \ud1b5\uce58\uc790\ub4e4\uc758 \uad00\uacc4\ub97c \ubcf4\uc5ec \uc900\ub2e4. \uc2e0\uc804\uc758 \ubd80\uc870\uc640\ub294 \ub2e4\ub978 \uc885\ub958\uc758 \ubaa9\uc18c\ub9ac\uac00 \ub0a8\uc740 \uac83\uc774\ub2e4. \uc5ec\ub7ec \uc790\ub8cc\ub97c \ud568\uaed8 \ubcf4\uba74 \uc2e0\uc559 \uac1c\ud601\uc774\ub77c\ub294 \ud55c \uc774\ub984 \uc548\uc5d0 \uc678\uad50\uc640 \ubb3c\uc790, \uc704\uacc4\uc640 \uc0dd\ud65c\uc774 \ubaa8\ub450 \ub4e4\uc5b4 \uc788\uc5c8\uc74c\uc744 \uc54c \uc218 \uc788\ub2e4. \uc720\uc801\uc5d0 \ub0a8\uc740 \ubb3c\uac74\uacfc \ubb38\uc11c\ub294 \uc655\uc758 \uc774\ub984\uc744 \uc9c0\uc6b0\ub824 \ud55c \ud589\uc704\uc640 \ub2e4\ub978 \ubc29\ud5a5\uc73c\ub85c \uc2dc\uac04\uc744 \uac74\ub11c\ub2e4. \uae30\uc5b5\uc744 \uc5c6\uc560\ub824\ub294 \uad8c\ub825\uc758 \ub73b\uc774 \uc5b8\uc81c\ub098 \uc644\uc804\ud788 \uc774\ub8e8\uc5b4\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc624\ub298\uc758 \uc5f0\uad6c\ub294 \uadf8\ub7f0 \ub0a8\uc740 \uc870\uac01\ub4e4\uc744 \ubaa8\uc544 \uacf5\uc2dd \uae30\ub150\ubb3c\ub9cc\uc73c\ub85c\ub294 \uc54c\uae30 \uc5b4\ub824\uc6b4 \ub3c4\uc2dc\ub97c \uc77d\ub294\ub2e4. \uc544\ucf00\ub098\ud1a4 \uc0ac\ud6c4\uc5d0\ub294 \uc544\ud1a4 \uc911\uc2ec\uc758 \uc815\ucc45\uc774 \ub418\ub3cc\ub824\uc84c\uace0 \uc218\ub3c4\ub3c4 \uacc4\uc18d \uc911\uc2ec\uc9c0\ub85c \ub0a8\uc9c0 \ubabb\ud588\ub2e4. \ud22c\ud0d5\uce74\uba58 \uc2dc\ub300\uc758 \ubcc0\ud654\ub294 \uc655\uc2e4 \uc774\ub984\uacfc \uc2e0\uc559, \ud1b5\uce58\uc758 \ubc29\ud5a5\uc774 \ub2e4\uc2dc \ub2ec\ub77c\uc84c\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc774\ud6c4 \uc544\ucf00\ub098\ud1a4\uc758 \uae30\uc5b5\uacfc \ud615\uc0c1\uc744 \ud6fc\uc190\ud558\uac70\ub098 \uc9c0\uc6b0\ub824\ub294 \ud589\ub3d9\ub3c4 \uc774\uc5b4\uc84c\ub2e4. \uadf8\ub7ec\ub098 \uc774\ub97c \ub2e8\uc21c\ud788 \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \ud55c\uaebc\ubc88\uc5d0 \ub3c4\ub9dd\uce5c \uc720\ub839 \ub3c4\uc2dc \uc774\uc57c\uae30\ub85c \ub9cc\ub4e4 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc7a5\uc18c\uc758 \ucd95\uc18c\uc640 \uc7ac\uc0ac\uc6a9, \uac74\ucd95 \uc790\uc7ac\uc758 \uc774\ub3d9\uc740 \uc2dc\uac04 \uc18d\uc5d0\uc11c \uc77c\uc5b4\ub0ac\ub2e4. \uc655\uc758 \uacc4\ud68d\uc774 \ub05d\ub098\ub294 \uac83\uacfc \uc720\uc801\uc774 \uc624\ub298\uc758 \ubaa8\uc2b5\uc73c\ub85c \ub0a8\ub294 \uacfc\uc815\uc740 \uac19\uc9c0 \uc54a\ub2e4. \uc61b \uc774\uc9d1\ud2b8\uc0ac \ucc45\uc5d0\ub294 \uc544\ucf00\ub098\ud1a4\uc758 \uc2e0\uc559\uc774 \uc81c\uad6d\uc744 \uc57d\ud558\uac8c \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \uc2dd\uc758 \uac15\ud55c \ud3c9\uac00\uac00 \ub098\uc628\ub2e4. \uc678\uad50\uc640 \uad70\uc0ac, \uc885\uad50\uc758 \ubcf5\uc7a1\ud55c \ubcc0\ud654\ub97c \uc655 \ud55c \uc0ac\ub78c\uc758 \uc131\uaca9\uc73c\ub85c \uc124\uba85\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \uc544\ud1a4 \uc2e0\uc559\uc744 \uace7 \ud604\ub300\uc801 \uc758\ubbf8\uc758 \uc720\uc77c\uc2e0\uad50\uc640 \uac19\ub2e4\uace0 \ub2e8\uc815\ud558\ub294 \uac83\ub3c4 \ub17c\uc758\uc758 \uc5ec\uc9c0\ub97c \uc9c0\uc6b4\ub2e4. \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uc655\uacfc \uc655\ube44\uac00 \uace0\uc704 \uad00\ub9ac\ub97c \ubcf4\uc0c1\ud558\ub294 \uc7a5\uba74\uc758 \uc2e4\uc81c \uc720\ubb3c\uc5d0 \uadfc\uac70\ud55c \uc5ed\uc0ac \ub3c4\ud310\uc774\ub2e4. \ud604\uc7ac \ub3c4\uc2dc \uc804\uacbd\uc774\ub098 \uc655\uc758 \uc2e4\uc81c \uc678\ubaa8\ub97c \ucc0d\uc740 \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \uc544\ub9c8\ub974\ub098\ub294 \uac70\ub300\ud55c \uacc4\ud68d\uc774 \uc9e7\uac8c \ub05d\ub098\ub3c4 \uadf8\uacf3\uc5d0\uc11c \uc0b4\uace0 \uc77c\ud588\ub358 \uc0ac\ub78c\ub4e4\uc758 \ud754\uc801\uc740 \ub0a8\ub294\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "asoka-edicts-kalinga-and-public-morality", "title": "\uc544\uc18c\uce74\uc758 \uce59\ub839 \u2014 \uc815\ubcf5\ud55c \uc655\uc740 \uc65c \ud6c4\ud68c\ub97c \ub3cc\uc5d0 \uc0c8\uacbc\uc744\uae4c", "summary": "\uce7c\ub9c1\uac00 \uc804\uc7c1\uc744 \ub9d0\ud55c \ube44\ubb38\uacfc \ub2f4\ub9c8\uc758 \uc724\ub9ac, \uc655\uc758 \ud589\uc815\uacfc \uc790\uae30 \uc774\ubbf8\uc9c0\ub97c \uad6c\ubd84\ud574 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/asoka-edicts-kalinga-and-public-morality/index.html", "image": "../media/asoka-edicts-kalinga-and-public-morality.jpg", "alt": "\uc0ac\ub974\ub098\ud2b8 \uc0ac\uc790 \uae30\ub465\uba38\ub9ac\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc2e4\uc81c \uc720\ubb3c\uc5d0 \uadfc\uac70\ud55c \uc5ed\uc0ac \ucd9c\ud310 \ub3c4\ud310", "text": "\uc544\uc18c\uce74\uc758 \uce59\ub839 \u2014 \uc815\ubcf5\ud55c \uc655\uc740 \uc65c \ud6c4\ud68c\ub97c \ub3cc\uc5d0 \uc0c8\uacbc\uc744\uae4c \uce7c\ub9c1\uac00\uc758 \uace0\ud1b5\uacfc \ub2f4\ub9c8, \ube44\ubb38\uc73c\ub85c \ub9d0\ud55c \uc655\uc758 \ud1b5\uce58 \uce7c\ub9c1\uac00 \uc804\uc7c1\uc744 \ub9d0\ud55c \ube44\ubb38\uacfc \ub2f4\ub9c8\uc758 \uc724\ub9ac, \uc655\uc758 \ud589\uc815\uacfc \uc790\uae30 \uc774\ubbf8\uc9c0\ub97c \uad6c\ubd84\ud574 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc2b9\ub9ac\ub97c \uae30\ub150\ud558\ub294 \ube44\ubb38\uc740 \ud754\ud558\uc9c0\ub9cc \uc804\uc7c1\uc774 \ub0b3\uc740 \uace0\ud1b5\uc744 \ub9d0\ud558\ub294 \uc655\uc758 \uae30\ub85d\uc740 \ub208\uae38\uc744 \ub048\ub2e4. \uae30\uc6d0\uc804 3\uc138\uae30 \ub9c8\uc6b0\ub9ac\uc544 \uc655\uc870\uc758 \uc544\uc18c\uce74\ub294 \ubc14\uc704\uc640 \ub3cc\uae30\ub465\uc5d0 \ud1b5\uce58\uc758 \ub9d0\uc744 \ub0a8\uacbc\ub2e4. \uc774 \uae00\ub4e4\uc744 \uc77d\uc73c\uba74 \uc804\uc7c1 \ub4a4\uc758 \ud6c4\ud68c\uc640 \uc724\ub9ac, \ud589\uc815\uacfc \uc655\uc758 \uc790\uae30 \uc774\ubbf8\uc9c0\uac00 \ud55c \ubb38\uc11c \uc548\uc5d0 \uc788\uc74c\uc744 \uc54c \uc218 \uc788\ub2e4. \uc544\uc18c\uce74\ub294 \ucc2c\ub4dc\ub77c\uad7d\ud0c0 \ub9c8\uc6b0\ub9ac\uc544\uac00 \uc138\uc6b4 \uc655\uc870\uc758 \ud1b5\uce58\uc790\uc600\ub2e4. \uadf8\ub294 \uc774\ubbf8 \ub113\uc740 \uc601\uc5ed\uc744 \uac00\uc9c4 \uad6d\uac00\ub97c \ubb3c\ub824\ubc1b\uc558\uc73c\uba70 \uc815\ubcf5\uacfc \uad8c\ub825\uc758 \uc138\uacc4 \ubc14\uae65\uc5d0\uc11c \ucd9c\ubc1c\ud55c \uc778\ubb3c\uc774 \uc544\ub2c8\ub2e4. \uc790\ube44\ub85c\uc6b4 \uc655\uc774\ub77c\ub294 \ud6c4\ub300\uc758 \uc774\ubbf8\uc9c0\uc640 \uc9d1\uad8c \ub2f9\uc2dc\uc758 \uc870\uac74\uc744 \ub098\ub204\uc5b4 \ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \uadf8\uc758 \ud1b5\uce58\ub97c \uc624\ub298\ub0a0 \uc778\ub3c4\ub77c\ub294 \uad6d\uac00\uc758 \ubaa8\ub4e0 \uc601\ud1a0\uc640 \uc81c\ub3c4\uac00 \uadf8\ub300\ub85c \uc874\uc7ac\ud588\ub358 \uc2dc\ub300\ub85c \uc0dd\uac01\ud574\uc11c\ub3c4 \uc548 \ub41c\ub2e4. \ub2f9\uc2dc\uc758 \uc5ec\ub7ec \uc9c0\uc5ed\uacfc \uacf5\ub3d9\uccb4\ub97c \ub2e4\uc2a4\ub9ac\ub294 \uc77c\uc5d0\ub294 \uad50\ud1b5\uacfc \ubcf4\uace0, \uad00\ub9ac\uc640 \uc9c0\ubc29 \ud1b5\uce58\uc758 \ubb38\uc81c\uac00 \ub4a4\ub530\ub790\ub2e4. \ube44\ubb38\uc740 \uadf8\ub7f0 \ub113\uc740 \uacf5\uac04\uc744 \ud5a5\ud55c \ubaa9\uc18c\ub9ac\uc600\ub2e4. \uc655\uc774 \ud6c4\ud68c\ub97c \uc801\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uce7c\ub9c1\uac00\uc5d0\uc11c \uacaa\uc740 \uc0ac\ub78c\ub4e4\uc758 \ubaa9\uc18c\ub9ac\uac00 \ubaa8\ub450 \ub0a8\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ube44\ubb38\uc5d0\uc11c \uadf8\ub4e4\uc758 \uace0\ud1b5\uc740 \uc655\uc774 \ub9d0\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c \uc804\ub2ec\ub41c\ub2e4. \ud53c\ud574\ub97c \uc5b8\uae09\ud55c \uc810\uc740 \uc911\uc694\ud558\uc9c0\ub9cc \uc790\ub8cc\ub97c \ub0a8\uae38 \uc218 \uc788\uc5c8\ub358 \uad8c\ub825\uc758 \ube44\ub300\uce6d\ub3c4 \ud568\uaed8 \uae30\uc5b5\ud574\uc57c \ud55c\ub2e4. \uc544\uc18c\uce74\ub294 \uc778\ub3c4 \ub3d9\ucabd\uc758 \uce7c\ub9c1\uac00\ub97c \uc815\ubcf5\ud588\ub2e4. \uadf8\ub7ec\ub098 \ub110\ub9ac \uc54c\ub824\uc9c4 \uc81c13\ub300\uc554\uac01 \uce59\ub839\uc5d0\uc11c \uc655\uc740 \uc2b9\ub9ac\uc758 \uc601\uad11\ub9cc\uc774 \uc544\ub2c8\ub77c \uc8fd\uc74c\uacfc \uc774\uc8fc, \uac00\uc871\uacfc \uacf5\ub3d9\uccb4\uac00 \uacaa\uc740 \uace0\ud1b5\uc744 \ub9d0\ud55c\ub2e4. \uad70\uc0ac\uc801 \uc131\uacf5\uc744 \uae30\ub85d\ud558\uba74\uc11c \ub3d9\uc2dc\uc5d0 \uadf8 \ub300\uac00\ub97c \ub4dc\ub7ec\ub0b8 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \ub2e4\ub9cc \ube44\ubb38\uc5d0 \uc801\ud78c \ud76c\uc0dd\uc790 \uc218\ub97c \uc624\ub298\uc758 \ub3c5\ub9bd\uc801\uc778 \ud1b5\uacc4\ucc98\ub7fc \ub2e4\ub8f0 \uc218\ub294 \uc5c6\ub2e4. \uadf8\uac83\uc740 \uc655\uc774 \uc790\uc2e0\uc758 \ud589\ub3d9\uacfc \uc774\ud6c4\uc758 \ubc29\ud5a5\uc744 \uc124\uba85\ud558\ub294 \ubb38\uc11c\uc774\uae30\ub3c4 \ud558\ub2e4. \uc804\uc7c1 \ub4a4\uc758 \ub9c8\uc74c\uc744 \uc77d\uc744 \ub2e8\uc11c\ub294 \uc788\uc9c0\ub9cc \uadf8\uc758 \ub0b4\uba74 \uc804\uccb4\ub97c \uc9c1\uc811 \ub4e4\uc5ec\ub2e4\ubcf4\ub294 \ucc3d\uc740 \uc544\ub2c8\ub2e4. \uce59\ub839\uc5d0 \uc790\uc8fc \ub098\uc624\ub294 \ub2f4\ub9c8\ub294 \ud55c \ub2e8\uc5b4\ub85c \ubc88\uc5ed\ud558\uae30 \uc27d\uc9c0 \uc54a\ub2e4. \uc655\uc774 \uac15\uc870\ud55c \uac83\uc740 \ubd80\ubaa8\uc640 \uc5b4\ub978\uc5d0 \ub300\ud55c \uc874\uc911, \uc0dd\uba85\uc744 \ud568\ubd80\ub85c \ud574\uce58\uc9c0 \uc54a\ub294 \ud0dc\ub3c4, \uc9c4\uc2e4\ud55c \ub9d0\uacfc \uc62c\ubc14\ub978 \ud589\ub3d9 \ub4f1\uc774\ub2e4. \ud1b5\uce58 \uc544\ub798\uc758 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5a4 \uc0dd\ud65c\uc744 \ud574\uc57c \ud558\ub294\uac00\uc5d0 \uad00\ud55c \uacf5\uc801\uc778 \uc724\ub9ac\uc600\ub2e4. \uc544\uc18c\uce74\uac00 \ubd88\uad50\uc640 \uae4a\uc774 \uc5f0\uacb0\ub418\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ubaa8\ub4e0 \uce59\ub839\uc774 \ubd88\uad50 \uad50\ub9ac\ub9cc\uc744 \uac00\ub974\ucce4\ub2e4\ub294 \uc8fc\uc7a5\uc740 \ub2e4\ub974\ub2e4. \uc5ec\ub7ec \uc9d1\ub2e8\uc774 \uc0ac\ub294 \uc655\uad6d\uc5d0\uc11c \uacf5\ud1b5\uc758 \ud589\ub3d9 \uaddc\ubc94\uc744 \uc804\ud558\ub824\ub294 \ubaa9\uc801\ub3c4 \uc788\uc5c8\ub2e4. \ub2f4\ub9c8\ub97c \uc624\uc9c1 \ud2b9\uc815 \uc885\uad50\uc758 \uc774\ub984\uc774\ub098 \ud604\ub300\uc758 \ubc95\ub960\uacfc \ub3d9\uc77c\ud558\uac8c \ub193\uc73c\uba74 \uc758\ubbf8\uac00 \uc881\uc544\uc9c4\ub2e4. \uc655\uc740 \ub2e4\ub978 \uc9c0\uc5ed\uc758 \uc0ac\ub78c\uc5d0\uac8c \uc790\uae30 \ub73b\uc774 \uc804\ud574\uc9c0\uace0 \uc788\ub2e4\uace0 \uc8fc\uc7a5\ud588\ub2e4. \uadf8\ub7ec\ub098 \ud1b5\uce58\uc790\uac00 \uc804\ud30c\uc758 \ubc94\uc704\ub97c \ub113\uac8c \ub9d0\ud558\ub294 \uac83\uacfc \uc2e4\uc81c\ub85c \uc5b4\ub290 \uc815\ub3c4 \ubc1b\uc544\ub4e4\uc5ec\uc84c\ub294\uc9c0\ub97c \ud655\uc778\ud558\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uc774\uc6c3 \ub098\ub77c\uc758 \uc774\ub984\uc774 \ube44\ubb38\uc5d0 \ub098\uc628\ub2e4\uace0 \ubaa8\ub450 \uc815\uce58\uc801\uc73c\ub85c \uc9c0\ubc30\ud588\ub2e4\ub294 \ub73b\ub3c4 \uc544\ub2c8\ub2e4. \uce59\ub839\uc740 \ud55c\uacf3\uc758 \uad81\uc804 \ubb38\uc11c\ud568\uc5d0\ub9cc \ubcf4\uad00\ub418\uc9c0 \uc54a\uc558\ub2e4. \uc5ec\ub7ec \uc9c0\uc5ed\uc758 \ubc14\uc704\uc640 \ub3cc\uae30\ub465\uc5d0 \uc0c8\uaca8\uc84c\uc73c\uba70 \uc5b8\uc5b4\uc640 \ubb38\uc790\ub3c4 \uc9c0\uc5ed\uc5d0 \ub530\ub77c \ub2ec\ub790\ub2e4. \ub113\uc740 \ud1b5\uce58 \uacf5\uac04\uc5d0\uc11c \ub9d0\uc774 \uc804\ub2ec\ub418\ub3c4\ub85d \ud615\ud0dc\ub97c \uc870\uc815\ud55c \uac83\uc774\ub2e4. \ud55c \uc885\ub958\uc758 \uae00\uc744 \ub204\uad6c\ub098 \ub611\uac19\uc774 \uc77d\uc5c8\ub2e4\uace0 \ubcfc \uc218\ub294 \uc5c6\ub2e4. \ube44\ubb38\uc774 \uacf5\uac1c\ub418\uc5b4 \uc788\ub2e4\ub294 \uac83\uacfc \ubaa8\ub4e0 \uc8fc\ubbfc\uc774 \uae00\uc744 \uc77d\uc744 \uc218 \uc788\ub2e4\ub294 \uac83\ub3c4 \ub2e4\ub974\ub2e4. \uc18c\ub9ac \ub0b4\uc5b4 \uc804\ub2ec\ud558\uace0 \uc124\uba85\ud558\ub294 \uc0ac\ub78c\uacfc \uad00\ub9ac\uc758 \uc5ed\ud560\uc774 \ud544\uc694\ud588\uc744 \uac83\uc774\ub2e4. \ub3cc\uc5d0 \ub0a8\uc740 \ubb38\uc7a5\ub9cc \uc544\ub2c8\ub77c \uadf8 \ubb38\uc7a5\uc744 \uc0ac\ub78c\uc5d0\uac8c \uc774\uc5b4 \uc8fc\ub294 \ud589\uc815\uc744 \uc0dd\uac01\ud574\uc57c \uc2e4\uc81c\uc758 \uc18c\ud1b5\uc774 \ubcf4\uc778\ub2e4. \uc544\uc18c\uce74\uc758 \uce59\ub839\uc5d0\ub294 \uc0ac\ub78c\uacfc \ub3d9\ubb3c, \uc57d\uc6a9 \uc2dd\ubb3c\uacfc \uae38\uc744 \ub530\ub77c \uc2ec\uc740 \ub098\ubb34, \uc6b0\ubb3c \ub4f1 \uc0dd\ud65c\uacfc \uc5f0\uacb0\ub418\ub294 \ub0b4\uc6a9\uc774 \ub098\uc628\ub2e4. \uc724\ub9ac\ub294 \ub0b4\uba74\uc758 \uc88b\uc740 \ub9c8\uc74c\ub9cc\uc774 \uc544\ub2c8\ub77c \uc655\uc774 \uc5b4\ub5a4 \uc0ac\uc5c5\uacfc \uac10\ub3c5\uc744 \ud574\uc57c \ud558\ub294\uac00\uc758 \ubb38\uc81c\uc774\uae30\ub3c4 \ud588\ub2e4. \ub3d9\ubb3c\uc744 \uc8fd\uc774\ub294 \ud589\uc704\uc5d0 \ub300\ud55c \uc81c\ud55c\ub3c4 \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uace7\ubc14\ub85c \uc644\uc804\ud55c \ucc44\uc2dd\uc744 \ud588\ub2e4\ub294 \ub73b\uc73c\ub85c \ubc14\uafc0 \uc218\ub294 \uc5c6\ub2e4. \uc774\uc0c1\uacfc \uaddc\uc815, \uc2e4\uc81c \uc0dd\ud65c\uc740 \uad6c\ubd84\ud574\uc11c \uc77d\uc5b4\uc57c \ud55c\ub2e4. \uc88b\uc740 \uc815\ucc45\uc744 \uc120\uc5b8\ud55c \ube44\ubb38 \ud558\ub098\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc9c0\uc5ed\uc5d0\uc11c \ub611\uac19\uc774 \uc2dc\ud589\ub418\uc5c8\ub2e4\uace0 \uc785\uc99d\ud560 \uc218\ub294 \uc5c6\uae30 \ub54c\ubb38\uc774\ub2e4. \uae30\ub465\uc740 \ub9d0\uc774 \uc801\ud78c \ud45c\uba74\uc778 \ub3d9\uc2dc\uc5d0 \uba40\ub9ac\uc11c\ub3c4 \uc54c\uc544\ubcfc \uc218 \uc788\ub294 \uc655\uc758 \ud45c\uc9c0\uc600\ub2e4. \uae00\uc744 \uc77d\ub294 \ud589\uc704\uc640 \uae30\ub150\ubb3c\uc744 \ubcf4\ub294 \uacbd\ud5d8\uc774 \uacb9\uce5c\ub2e4. \uadf8\ub798\uc11c \uae00\uc790\uc758 \ub73b\uacfc \uae30\ub465\uc758 \ud615\ud0dc\ub97c \ub530\ub85c \ubcf4\ub294 \ub370\uc11c \uc2dc\uc791\ud574, \ub458\uc774 \uc5b4\ub5a4 \uad8c\uc704\ub97c \ud568\uaed8 \ub9cc\ub4e4\uc5c8\ub294\uc9c0 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ub2e4\ub978 \uc885\ud30c\ub97c \ud568\ubd80\ub85c \ub0ae\ucd94\uc9c0 \ub9d0\ub77c\ub294 \uac00\ub974\uce68\uc740 \uc544\uc18c\uce74 \uae30\ub85d\uc758 \uc911\uc694\ud55c \ubd80\ubd84\uc774\ub2e4. \uc790\uae30 \uc9d1\ub2e8\uc758 \uc6b0\uc6d4\ud568\uc744 \ub4dc\ub7ec\ub0b4\ub824\ub294 \ub9d0\uc774 \uc624\ud788\ub824 \uadf8 \uc9d1\ub2e8\uc744 \ud574\uce60 \uc218 \uc788\ub2e4\ub294 \uad00\ucc30\uc740 \uc9c0\uae08 \uc77d\uc5b4\ub3c4 \uc0dd\uac01\ud560 \uac70\ub9ac\ub97c \uc900\ub2e4. \uc5ec\ub7ec \uc2e0\uc559\uc744 \ub300\ud558\ub294 \ud0dc\ub3c4\uac00 \uacf5\uc801\uc778 \uad00\uc2ec\uc0ac\uc600\ub358 \uc148\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc624\ub298\ub0a0\uc758 \uc885\uad50 \uc790\uc720\ub098 \ubbfc\uc8fc\uc8fc\uc758\uac00 \uadf8\ub54c \uadf8\ub300\ub85c \uc2e4\ud604\ub418\uc5c8\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub9d0\ud558\ub294 \uc0ac\ub78c\uc740 \uc5ec\uc804\ud788 \uc655\uc774\uba70 \ub3c4\ub355\uc744 \uad8c\uc7a5\ud558\uace0 \uac10\ub3c5\ud558\ub294 \uad8c\ub825\ub3c4 \uc720\uc9c0\ub41c\ub2e4. \uad00\uc6a9\uc758 \uc5b8\uc5b4\uc640 \ud1b5\uce58\uc758 \uad8c\uc704\ub97c \ud55c\ucabd\ub9cc \uace8\ub77c \ubcf4\ub294 \uac83\ubcf4\ub2e4 \ud568\uaed8 \uc77d\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \ud6c4\ub300\uc758 \ubd88\uad50 \uc804\uc2b9\uc740 \uc544\uc18c\uce74\uc758 \uc0b6\uc5d0 \ub9ce\uc740 \uc774\uc57c\uae30\ub97c \ub354\ud588\ub2e4. \uc5ed\uc0ac \uc5f0\uad6c\uc5d0\uc11c\ub294 \uc774\ub7f0 \uc804\uc2b9\uacfc \ub2f9\ub300 \ube44\ubb38, \ud6c4\ub300\uc758 \ud574\ub3c5\uacfc \ud574\uc11d\uc744 \uad6c\ubd84\ud55c\ub2e4. \uc624\ub798\ub41c \uac1c\uc124\uc11c\uc758 \uc5f0\ub300\ub098 \ubaa8\ub4e0 \uc804\uc7c1\uc744 \uc601\uc6d0\ud788 \uc5c6\uc574\ub2e4\ub294 \ucc2c\uc591\uc744 \uadf8\ub300\ub85c \ubc18\ubcf5\ud560 \uc218 \uc5c6\ub294 \uc774\uc720\ub2e4. \uc5ec\uae30\uc5d0 \uc2e4\uc740 \uac83\uc740 \uc0ac\ub974\ub098\ud2b8\uc758 \uc0ac\uc790 \uae30\ub465\uba38\ub9ac\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc5ed\uc0ac \ucd9c\ud310 \ub3c4\ud310\uc774\ub2e4. \uce7c\ub9c1\uac00 \uce59\ub839\uc758 \uae00\uc790 \uc790\uccb4\ub97c \ucd2c\uc601\ud55c \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \uc655\uc758 \uc0c1\uc9d5\uacfc \uc655\uc774 \ub0a8\uae34 \ubb38\uc7a5\uc744 \ud568\uaed8 \ubcf4\ub418, \uc120\uc5b8\ub41c \uc774\uc0c1\uacfc \uc2e4\uc81c\uc758 \uc0b6 \uc0ac\uc774\uc5d0 \ubb34\uc5c7\uc744 \ub354 \uc54c\uc544\uc57c \ud558\ub294\uc9c0 \uc9c8\ubb38\ud574 \ubcf4\uc790."}, {"id": "athens-parthenon-and-tribute", "title": "\uc544\ud14c\ub124 \u2014 \ud30c\ub974\ud14c\ub17c\uc740 \ub204\uad6c\uc758 \ub3c8\uc73c\ub85c \uc9c0\uc5c8\uc744\uae4c", "summary": "\ud30c\ub974\ud14c\ub17c\uc758 \uc678\uad00\uacfc \uc544\ud14c\ub124\uc758 \ub3d9\ub9f9 \uad00\uacc4\ub97c \ud568\uaed8 \ubcf4\uba70 \ub3c4\uc2dc\uc758 \ubc88\uc601\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/athens-parthenon-and-tribute/index.html", "image": "../media/athens-parthenon-and-tribute.jpg", "alt": "\uc544\ud06c\ub85c\ud3f4\ub9ac\uc2a4 \uc704 \ud30c\ub974\ud14c\ub17c\uc758 \uae30\ub465\uacfc \ud604\uc7ac \ub0a8\uc544 \uc788\ub294 \uc11d\uc870 \uac74\ubb3c.", "text": "\uc544\ud14c\ub124 \u2014 \ud30c\ub974\ud14c\ub17c\uc740 \ub204\uad6c\uc758 \ub3c8\uc73c\ub85c \uc9c0\uc5c8\uc744\uae4c \uc544\ub984\ub2e4\uc6b4 \uc2e0\uc804 \uacc1\uc5d0\uc11c \ub3d9\ub9f9\uacfc \uad8c\ub825\uc744 \uc0dd\uac01\ud558\uae30 \ud30c\ub974\ud14c\ub17c\uc758 \uc678\uad00\uacfc \uc544\ud14c\ub124\uc758 \ub3d9\ub9f9 \uad00\uacc4\ub97c \ud568\uaed8 \ubcf4\uba70 \ub3c4\uc2dc\uc758 \ubc88\uc601\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc544\ud14c\ub124\uc758 \uc544\ud06c\ub85c\ud3f4\ub9ac\uc2a4 \uc704\uc5d0\ub294 \uc9c0\ubd95\uc744 \uc783\uc740 \ud30c\ub974\ud14c\ub17c\uc774 \uc11c \uc788\ub2e4. \uc0ac\uc9c4\uc73c\ub85c \ubcf4\uba74 \uae30\ub465\uacfc \ud558\ub298\uc774 \uba3c\uc800 \ub4e4\uc5b4\uc628\ub2e4. \uc628\uc804\ud55c \uac74\ubb3c\uc774 \uc544\ub2cc\ub370\ub3c4 \ub3c4\uc2dc\ub97c \ub300\ud45c\ud558\ub294 \ubaa8\uc2b5\uc774 \ub420 \ub9cc\ud07c \uc778\uc0c1\uc774 \uac15\ud558\ub2e4. \uadf8\ub7f0\ub370 \uc774 \uc2e0\uc804\uc744 \uc138\uc6b0\ub294 \ub370 \uc4f4 \ub3c8\uc740 \uc5b4\ub514\uc5d0\uc11c \uc654\uc744\uae4c. \uac74\ucd95\uc758 \uc544\ub984\ub2e4\uc6c0\uacfc \ub3c8\uc758 \ucd9c\ucc98\ub294 \uc11c\ub85c \ubb34\uad00\ud55c \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \ud30c\ub974\ud14c\ub17c\uc774 \ub9cc\ub4e4\uc5b4\uc9c4 \uc2dc\ub300\uc758 \uc544\ud14c\ub124\ub294 \uc608\uc220\uacfc \uc2dc\ubbfc\uc815\uce58\uc758 \ub3c4\uc2dc\uc774\uba74\uc11c \uac15\ub825\ud55c \ud574\uc0c1 \uc138\ub825\uc758 \uc911\uc2ec\uc774\uc5c8\ub2e4. \uc2e0\uc804\uc758 \uae30\ub465 \uc606\uc5d0 \ub2f9\uc2dc \ub3d9\ub9f9 \ub3c4\uc2dc\ub4e4\uc758 \uc790\ub9ac\ub3c4 \ub193\uc544 \ubcf4\uba74 \uc775\uc219\ud55c \uc720\uc801\uc774 \uc870\uae08 \ub2ec\ub9ac \ubcf4\uc778\ub2e4. \ud30c\ub974\ud14c\ub17c\uc740 \uae30\uc6d0\uc804 5\uc138\uae30\uc5d0 \uc544\ud14c\ub098\ub97c \uae30\ub9ac\uae30 \uc704\ud574 \uc138\uc6cc\uc84c\ub2e4. \uc544\ud14c\ub098\ub294 \uc544\ud14c\ub124\uc640 \ud2b9\ubcc4\ud55c \uad00\uacc4\ub97c \uac00\uc9c4 \uc5ec\uc2e0\uc774\uc5c8\ub2e4. \ub3c4\uc2dc\uc758 \ub192\uc740 \uacf3\uc5d0 \uc790\ub9ac\ud55c \ud070 \uc2e0\uc804\uc740 \uc885\uad50 \uacf5\uac04\uc774\uba74\uc11c \uc0ac\ub78c\ub4e4\uc774 \uc790\uc2e0\ub4e4\uc758 \ub3c4\uc2dc\ub97c \ubc14\ub77c\ubcf4\ub294 \uc0c1\uc9d5\uc774\uae30\ub3c4 \ud588\ub2e4. \uc624\ub298\uc758 \uc0ac\uc9c4\uc5d0\uc11c\ub294 \ub0a8\uc544 \uc788\ub294 \uae30\ub465\uacfc \uac74\ubb3c\uc758 \ubf08\ub300\ub97c \ubcfc \uc218 \uc788\ub2e4. \uc6d0\ub798\uc758 \uc0c9\uacfc \uc7a5\uc2dd, \uc9c0\ubd95\uc774 \ubaa8\ub450 \uadf8\ub300\ub85c \ub0a8\uc544 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc9c0\uae08 \ubcf4\uc774\ub294 \ud770 \ub3cc\uc758 \uc778\uc0c1\ub9cc\uc73c\ub85c \uace0\ub300\uc778\uc774 \ucc98\uc74c \ub9cc\ub09c \uc2e0\uc804\uc758 \uacbd\ud5d8\uc744 \uc644\uc804\ud788 \uc7ac\ud604\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud398\ub974\uc2dc\uc544\uc640\uc758 \uc804\uc7c1\uc740 \uc544\ud14c\ub124\uc5d0\ub3c4 \ud070 \uc190\uc0c1\uc744 \ub0a8\uacbc\ub2e4. \uad50\uc7ac\ub294 \uc774\uc804 \uc2e0\uc804\uc774 \ud30c\uad34\ub41c \ub4a4 \uc544\ud14c\ub124\uac00 \uc7ac\uac74\uc5d0 \ub098\uc130\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc0c8 \uac74\ucd95\uc740 \uc544\ub984\ub2e4\uc6b4 \ubb3c\uac74\uc744 \ucd94\uac00\ud558\ub294 \uc77c\ub9cc\uc774 \uc544\ub2c8\ub77c \uc804\uc7c1 \ub4a4 \ub3c4\uc2dc\uc758 \ud798\uacfc \uc815\uccb4\uc131\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc120\ud0dd\uc774\uc5c8\ub2e4. \uc804\uc7c1\uc758 \uae30\uc5b5\uacfc \uc7ac\uac74\uc758 \uc758\uc9c0\uac00 \ud070 \uacf5\uc0ac\uc5d0 \ub4e4\uc5b4\uac04 \uac83\uc774\ub2e4. \uadf8\ub7ec\ub098 \ub204\uac00 \uc65c \uc9c0\uc73c\ub824 \ud588\ub294\uc9c0\uc640 \uadf8\uac83\uc744 \uc5b4\ub5bb\uac8c \ub9c8\ub828\ud588\ub294\uc9c0\ub294 \ub2e4\ub978 \uc9c8\ubb38\uc774\ub2e4. \uc88b\uc740 \ubaa9\uc801\uc744 \ub0b4\uc138\uc6b4 \uac74\ubb3c\ub3c4 \uc790\uc6d0\uacfc \ub178\ub3d9\uc744 \ubaa8\uc73c\ub294 \uad6c\uccb4\uc801\uc778 \uacfc\uc815\uc744 \ud544\uc694\ub85c \ud55c\ub2e4. \uc544\ud14c\ub124\ub294 \ub2e4\ub978 \uadf8\ub9ac\uc2a4 \ub3c4\uc2dc\uad6d\uac00\ub4e4\uacfc \ud574\uc0c1 \ub3d9\ub9f9\uc744 \uc774\ub8e8\uc5c8\ub2e4. \ubc14\ub2e4\ub97c \ud1b5\ud55c \uad70\uc0ac\ub825\uacfc \uc7ac\uc6d0\uc774 \uc911\uc694\ud55c \uad00\uacc4\uc600\ub2e4. \uc5ec\ub7ec \ub3c4\uc2dc\uac00 \uc5f0\uacb0\ub418\uc5c8\ub2e4\ub294 \uc810\uc5d0\uc11c\ub294 \uacf5\ub3d9\uc758 \ubc29\uc5b4\ub97c \uc0dd\uac01\ud560 \uc218 \uc788\uc9c0\ub9cc \uadf8 \uad00\uacc4\uac00 \uacc4\uc18d \ub3d9\ub4f1\ud558\uac8c \uc720\uc9c0\ub41c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uad50\uc7ac\ub294 \uc544\ud14c\ub124\uac00 \ub3d9\ub9f9\uc5d0\uc11c \ub354 \uac15\ud55c \ud1b5\uc81c\ub825\uc744 \ud589\uc0ac\ud558\uac8c \ub418\ub294 \ud750\ub984\uc744 \uc124\uba85\ud55c\ub2e4. \ud568\uaed8 \ub300\ube44\ud558\uae30 \uc704\ud574 \ubaa8\uc740 \ud798\uc774 \ud55c \ub3c4\uc2dc\uc758 \uc601\ud5a5\ub825\uc73c\ub85c \uc9d1\uc911\ub420 \uc218 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4. \uc544\ud14c\ub124\uc758 \ubc88\uc601\uc744 \ub3c4\uc2dc \uc548\ucabd\uc5d0\uc11c\ub9cc \ubcf4\uba74 \uadf8 \ubc14\uae65\uc758 \ubd80\ub2f4\uc740 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ud30c\ub974\ud14c\ub17c \uc7ac\uac74\uc5d0\ub294 \ub3d9\ub9f9 \ub3c4\uc2dc\ub4e4\uc774 \ub0b8 \uacf5\ub0a9 \uc131\uaca9\uc758 \uc790\uae08\uc774 \uc0ac\uc6a9\ub418\uc5c8\ub2e4. \uad50\uc7ac\ub294 \uc774 \uc77c\ub85c \ub2e4\ub978 \ub3c4\uc2dc\uad6d\uac00\ub4e4\uc758 \ubd88\ub9cc\uc774 \ucee4\uc84c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc624\ub298\ub0a0 \uc138\uacc4\uc758 \uad00\uad11\uac1d\uc774 \uac10\ud0c4\ud558\ub294 \uac74\ubb3c\uc774 \ub2f9\uc2dc\uc758 \ubaa8\ub4e0 \uad00\uacc4\uc790\uc5d0\uac8c \uac19\uc740 \uae30\uc068\uc774\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub290 \ub3c4\uc2dc\uc758 \uc790\ub791\uc740 \ub2e4\ub978 \ub3c4\uc2dc\uc5d0\uac8c \uc790\uc2e0\ub4e4\uc758 \uc790\uc6d0\uc774 \ub2e4\ub978 \uacf3\uc5d0 \uc4f0\uc774\ub294 \uc7a5\uba74\uc77c \uc218\ub3c4 \uc788\ub2e4. \uac74\ubb3c\uc758 \uc608\uc220\uc801 \uac00\uce58\uac00 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc \uadf8 \uac00\uce58\ub9cc\uc73c\ub85c \uc790\uae08 \uc0ac\uc6a9\uc758 \uc815\uce58\uac00 \ub05d\ub098\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud55c \uac74\ubb3c\uc744 \ub193\uace0\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc2dc\uc120\uc774 \uc0dd\uae30\ub294 \uc774\uc720\ub2e4. \uc544\ud14c\ub124\ub294 \ubbfc\uc8fc\uc815\uc758 \uc5ed\uc0ac\uc5d0\uc11c \uc911\uc694\ud55c \ub3c4\uc2dc\ub2e4. \uadf8\ub7ec\ub098 \ub2f9\uc2dc\uc758 \uc815\uce58 \ucc38\uc5ec\ub294 \uc624\ub298\ub0a0 \uc131\uc778 \uc804\uccb4\uc758 \ubcf4\ud1b5\uc120\uac70\uc640 \uac19\uc9c0 \uc54a\uc558\ub2e4. \uc5ec\uc131\uacfc \ub178\uc608, \uac70\uc8fc \uc678\uad6d\uc778 \ub4f1\uc740 \uc2dc\ubbfc \ub0a8\uc131\uacfc \uac19\uc740 \uc815\uce58\uc801 \uc790\ub9ac\ub97c \uac16\uc9c0 \ubabb\ud588\ub2e4. \ub530\ub77c\uc11c \ubbfc\uc8fc\uc815\uc774\ub77c\ub294 \uc774\ub984\uc744 \ud604\ub300\uc758 \uc644\uc131\ub41c \uae30\uc900\uc73c\ub85c \uadf8\ub300\ub85c \uc77d\uc744 \uc218\ub294 \uc5c6\ub2e4. \ub3d9\uc2dc\uc5d0 \ubaa8\ub4e0 \uac83\uc774 \uc9c0\uae08\uacfc \ub2e4\ub974\ub2e4\ub294 \uc774\uc720\ub85c \uadf8 \uc81c\ub3c4\uc758 \uc758\ubbf8\ub97c \uc9c0\uc6cc \ubc84\ub9b4 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ubb34\uc5c7\uc744 \uac00\ub2a5\ud558\uac8c \ud588\uc73c\uba70 \ub204\uad6c\ub97c \ubc14\uae65\uc5d0 \ub450\uc5c8\ub294\uc9c0 \ub098\ub204\uc5b4 \ubcf4\ub294 \ud3b8\uc774 \ub3c4\uc2dc\ub97c \ub354 \uc815\ud655\ud558\uac8c \uc774\ud574\ud558\uac8c \ud55c\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uae30\ub465\ub4e4\uc774 \ubc18\ubcf5\ub418\ub294 \uac04\uaca9\uacfc \uc704\ucabd\uc758 \uc218\ud3c9\uc120\uc744 \ub530\ub77c\uac00 \ubcf4\uc790. \uc190\uc0c1\ub41c \uac74\ubb3c\uc5d0\uc11c\ub3c4 \uc804\uccb4\uc758 \uc9c8\uc11c\uac00 \ub290\uaef4\uc9c4\ub2e4. \uc774 \uc778\uc0c1\ub9cc\uc73c\ub85c \uc815\ubc00\ud55c \ube44\ub840\ub098 \uc61b \uc124\uacc4 \uc758\ub3c4\ub97c \ubaa8\ub450 \ud655\uc815\ud560 \uc218\ub294 \uc5c6\uc9c0\ub9cc \ub208\uc73c\ub85c \uac10\uc0c1\ud560 \uc218 \uc788\ub294 \ucd9c\ubc1c\uc810\uc740 \ub41c\ub2e4. \ud070 \uc2e0\uc804\uc744 \uc62c\ub824\ub2e4\ubcf4\ub294 \uacbd\ud5d8\uc5d0\ub294 \uaddc\ubaa8\uc758 \ud6a8\uacfc\uac00 \uc788\ub2e4. \uc0ac\ub78c\uc740 \uc790\uc2e0\ubcf4\ub2e4 \ud070 \uad6c\uc870\ubb3c \uc55e\uc5d0\uc11c \ub3c4\uc2dc\uc758 \uc790\uc6d0\uacfc \uae30\uc220\uc744 \uccb4\uac10\ud558\uac8c \ub41c\ub2e4. \ud30c\ub974\ud14c\ub17c\uc758 \ube44\uc6a9\uc744 \uc0dd\uac01\ud55c \ub4a4 \ub2e4\uc2dc \uae30\ub465\uc744 \ubcf4\uba74 \uadf8 \uc778\uc0c1 \ub4a4\uc758 \uc5ec\ub7ec \uacf5\ub3d9\uccb4\uc640 \ub178\ub3d9\ub3c4 \ud568\uaed8 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uc544\ud14c\ub124\uac00 \uc9c0\ub2cc \ud574\uc0c1 \uc138\ub825\uacfc \uc2a4\ud30c\ub974\ud0c0\ub97c \uc911\uc2ec\uc73c\ub85c \ud55c \uc721\uc0c1 \uc138\ub825\uc758 \uacbd\uc7c1\uc740 \uadf8\ub9ac\uc2a4 \uc138\uacc4\ub97c \uac08\ub77c\ub193\uc558\ub2e4. \uad50\uc7ac\ub294 \ud3a0\ub85c\ud3f0\ub124\uc18c\uc2a4 \uc804\uc7c1\uc744 \uc774\ub7f0 \uad00\uacc4 \uc18d\uc5d0\uc11c \uc124\uba85\ud55c\ub2e4. \ub2e4\ub9cc \uc2e0\uc804 \ud558\ub098\uc758 \uac74\ucd95\uc774 \uc804\uc7c1 \uc804\uccb4\ub97c \uc77c\uc73c\ucf30\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub3c4\uc2dc\ub4e4 \uc0ac\uc774\uc758 \uac08\ub4f1\uc5d0\ub294 \uad8c\ub825\uacfc \uc548\ubcf4, \ub3d9\ub9f9\uc758 \ubcc0\ud654\uac00 \ud568\uaed8 \uc788\uc5c8\ub2e4. \ud30c\ub974\ud14c\ub17c\uc758 \uc790\uae08 \ubb38\uc81c\ub294 \uadf8 \ud070 \uad00\uacc4\ub97c \uac00\uae4c\uc774\uc5d0\uc11c \uc0dd\uac01\ud558\uac8c \ud558\ub294 \uc0ac\ub840\ub2e4. \uc791\uc740 \uc0ac\uac74\uacfc \uae34 \uc804\uc7c1 \uc0ac\uc774\uc758 \uc778\uacfc\ub97c \ubb34\ub9ac\ud558\uac8c \ud55c \uc904\ub85c \uc5f0\uacb0\ud558\uc9c0 \uc54a\uc544\ub3c4 \ucda9\ubd84\ud788 \uc758\ubbf8\uac00 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \ud30c\ub974\ud14c\ub17c\uc758 \uc2e4\uc81c \uc720\uc801 \uc0ac\uc9c4\uc774\ub2e4. \uc9c0\uae08 \ub0a8\uc740 \ubaa8\uc2b5\uacfc \uace0\ub300\uc758 \uc644\uc131 \ubaa8\uc2b5\uc740 \uad6c\ubcc4\ud558\uba74\uc11c \uae30\ub465\uacfc \uc5b8\ub355\uc758 \uc778\uc0c1\uc744 \ubcfc \uc218 \uc788\ub2e4. \ud604\uc7ac\uc758 \uad00\ub78c \ub3d9\uc120\uc774\ub098 \ubcf4\uc874 \uc0c1\ud0dc\ub97c \uc2e4\uc2dc\uac04\uc73c\ub85c \uc548\ub0b4\ud558\ub294 \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ud30c\ub974\ud14c\ub17c\uc744 \uc88b\uc544\ud558\uba74\uc11c \uadf8 \ube44\uc6a9\uc744 \ubb3c\uc744 \uc218 \uc788\ub2e4. \uc608\uc220\uc744 \uac10\uc0c1\ud558\ub294 \uc77c\uacfc \uad8c\ub825\uc758 \uc791\ub3d9\uc744 \uc54c\uc544\ubcf4\ub294 \uc77c\uc740 \uc11c\ub85c\ub97c \uc5c6\uc560\uc9c0 \uc54a\ub294\ub2e4. \uc544\ud14c\ub124\uc758 \ub192\uc740 \uc5b8\ub355\uc740 \ud6cc\ub96d\ud55c \uac74\ucd95\uc774 \uc5b4\ub5bb\uac8c \ub9cc\ub4e4\uc5b4\uc84c\uace0 \uadf8 \ub4a4\uc5d0 \ub204\uad6c\uc758 \uc790\uc6d0\uc774 \uc788\uc5c8\ub294\uc9c0 \uc0dd\uac01\ud560 \ub54c \ub354 \uae4a\uc740 \ud48d\uacbd\uc774 \ub41c\ub2e4."}, {"id": "baghdad-round-city-and-books", "title": "\ubc14\uadf8\ub2e4\ub4dc \u2014 \ub465\uadfc \ub3c4\uc2dc \ubc14\uae65\uc73c\ub85c \uc774\uc57c\uae30\uac00 \uc790\ub77c\ub2e4", "summary": "\ud6c4\ub300\uc758 \uc61b \uc9c0\ub3c4\uc5d0\uc11c \ub465\uadfc \uc218\ub3c4\uc758 \uad6c\uc0c1\uacfc \uad50\uc5ed\u00b7\ubc88\uc5ed\uc774 \ud0a4\uc6b4 \ub3c4\uc2dc\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/baghdad-round-city-and-books/index.html", "image": "../media/baghdad-round-city-and-books.jpg", "alt": "1880\ub144\ub300 \ud6c4\ub300 \uc9c0\ub3c4\uc5d0 \ud45c\uc2dc\ub41c \ubc14\uadf8\ub2e4\ub4dc\uc758 \ub465\uadfc \uc911\uc2ec\ubd80\uc640 \ud2f0\uadf8\ub9ac\uc2a4\uac15, \uc218\ub85c \ubc0f \uc678\uacfd \uad6c\uc5ed.", "text": "\ubc14\uadf8\ub2e4\ub4dc \u2014 \ub465\uadfc \ub3c4\uc2dc \ubc14\uae65\uc73c\ub85c \uc774\uc57c\uae30\uac00 \uc790\ub77c\ub2e4 \uad81\uc804\uc5d0\uc11c \uc2dc\uc791\ud55c \uc6d0\uacfc \uac15\uc744 \ub530\ub77c \ubc88\uc9c4 \uc0dd\ud65c \ud6c4\ub300\uc758 \uc61b \uc9c0\ub3c4\uc5d0\uc11c \ub465\uadfc \uc218\ub3c4\uc758 \uad6c\uc0c1\uacfc \uad50\uc5ed\u00b7\ubc88\uc5ed\uc774 \ud0a4\uc6b4 \ub3c4\uc2dc\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ub3c4\uc2dc \uc9c0\ub3c4\ub97c \ud3bc\ucce4\ub294\ub370 \ud55c\uac00\uc6b4\ub370 \ucee4\ub2e4\ub780 \uc6d0\uc774 \ubcf4\uc778\ub2e4\uba74 \uc5b4\ub5a8\uae4c. \ub3c4\ub85c\uac00 \uc6b0\uc5f0\ud788 \ub465\uae00\uc5b4\uc9c4 \uc815\ub3c4\uac00 \uc544\ub2c8\ub2e4. \uc131\ubcbd\uacfc \uc911\uc2ec \uacf5\uac04\uc744 \uc6d0\uc73c\ub85c \uacc4\ud68d\ud55c \ub3c4\uc2dc\ub2e4. \uc624\ub298\ub0a0 \uc774\ub77c\ud06c\uc758 \uc218\ub3c4 \ubc14\uadf8\ub2e4\ub4dc\uc5d0\ub294 \ubc14\ub85c \uc774\ub7f0 \ucd9c\ubc1c\uc810\uc774 \uc788\uc5c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc9c0\ub3c4\uc5d0\uc11c \uba3c\uc800 \ub465\uadfc \ubd80\ubd84\uc744 \ucc3e\uc544\ubcf4\uc790. \uadf8\ub2e4\uc74c\uc5d0\ub294 \uc2dc\uc120\uc744 \uc870\uae08 \uc606\uc73c\ub85c \uc62e\uaca8 \uac15\uacfc \uc218\ub85c, \uc6d0 \ubc14\uae65\uc758 \uae38\uc744 \ub530\ub77c\uac00\uba74 \ub41c\ub2e4. \ub450 \ubc88 \ubcf4\ub294 \uc0ac\uc774\uc5d0 \uc774\uc57c\uae30\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uad8c\ub825\uc790\uac00 \uadf8\ub9b0 \uc218\ub3c4\uc758 \ubaa8\uc591\uacfc \uc0ac\ub78c\ub4e4\uc774 \uc0b4\uc544\uac00\uba70 \ub113\ud78c \ub3c4\uc2dc\uac00 \ud55c \uc7a5 \uc548\uc5d0 \ub4e4\uc5b4 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. 8\uc138\uae30\uc5d0 \ub4f1\uc7a5\ud55c \uc544\ubc14\uc2a4 \uc655\uc870\ub294 \ub2e4\ub9c8\uc2a4\ucfe0\uc2a4\uc5d0\uc11c \ub354 \ub3d9\ucabd\uc73c\ub85c \uc815\uce58\uc758 \ubb34\uac8c\uc911\uc2ec\uc744 \uc62e\uacbc\ub2e4. \uc0c8 \uc218\ub3c4 \ubc14\uadf8\ub2e4\ub4dc\ub294 \ud2f0\uadf8\ub9ac\uc2a4\uac15\uc744 \ub080 \uba54\uc18c\ud3ec\ud0c0\ubbf8\uc544\uc5d0 \uc790\ub9ac \uc7a1\uc558\ub2e4. \ube44\uc625\ud55c \ub18d\uacbd\uc9c0\uc640 \ubb3c\uae38\uc744 \uc774\uc6a9\ud560 \uc218 \uc788\uace0 \ub3d9\ucabd \uc9c0\uc5ed\uacfc\uc758 \uad00\uacc4\ub3c4 \uac15\ud654\ud560 \uc218 \uc788\ub294 \uacf3\uc774\uc5c8\ub2e4. \uc218\ub3c4 \uc774\uc804\uc740 \uad81\uc804\uc758 \uc8fc\uc18c\ub9cc \ubc14\uafb8\ub294 \uc77c\uc774 \uc544\ub2c8\ub2e4. \uad00\ub8cc\uc640 \uad70\uc778, \uc7a5\uc778\uacfc \uc0c1\uc778\ub3c4 \uc0c8\ub85c\uc6b4 \uc911\uc2ec\uc744 \ud5a5\ud574 \uc6c0\uc9c1\uc778\ub2e4. \uc655\uc870\uac00 \uc5b4\ub514\ub97c \uc911\uc694\ud558\uac8c \uc5ec\uae30\ub294\uc9c0 \ub3c4\uc2dc\uc758 \uc704\uce58\uac00 \ubcf4\uc5ec \uc8fc\ub294 \uc148\uc774\ub2e4. \ubc14\uadf8\ub2e4\ub4dc\uc758 \uc131\uc7a5\uc740 \uc774\ub7f0 \uc815\uce58\uc801 \uc120\ud0dd\uacfc \uc8fc\ubcc0\uc758 \uc0dd\uc0b0\u00b7\uad50\uc5ed \uc870\uac74\uc774 \ub9cc\ub09c \uacb0\uacfc\uc600\ub2e4. \ub465\uadfc \uc911\uc2ec\ubd80 \uc548\uc5d0\uc11c\ub294 \uce7c\ub9ac\ud504\uc758 \uad81\uc804\uc5d0 \uac00\uae4c\uc6b4 \uc790\ub9ac\uac00 \ud2b9\ubcc4\ud55c \uc704\uc2e0\uc744 \uac00\uc84c\ub2e4. \uac19\uc740 \ub3c4\uc2dc\uc758 \uc8fc\ubbfc\uc774\ub77c\ub3c4 \uad8c\ub825\uc758 \uc911\uc2ec\uc5d0 \uc5bc\ub9c8\ub098 \uac00\uae4c\uc6b4\uc9c0\uac00 \uc911\uc694\ud588\ub2e4. \uc6d0\uc740 \ubcf4\uae30 \uc88b\uc740 \ubb34\ub2ac\uc774\uba74\uc11c, \uc911\uc2ec\uacfc \uc8fc\ubcc0\uc744 \ub208\uc5d0 \ub744\uac8c \uad6c\ubd84\ud558\ub294 \ubc30\uce58\uc774\uae30\ub3c4 \ud588\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub3d9\uadf8\ub77c\ubbf8 \uc548\uc5d0 \ubc14\uadf8\ub2e4\ub4dc\uc758 \ubaa8\ub4e0 \uc0b6\uc774 \ub4e4\uc5b4 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc9c0\ub3c4\uc5d0\uc11c\ub3c4 \uac15\uac00\uc758 \uc5ec\ub7ec \uad6c\uc5ed\uacfc \uae38\uc774 \uc6d0\uc744 \ubc97\uc5b4\ub098 \uc774\uc5b4\uc9c4\ub2e4. \ucc98\uc74c \uacc4\ud68d\ud55c \uc911\uc2ec\ubd80\ub97c \ub3c4\uc2dc \uc804\uccb4\uc640 \ud63c\ub3d9\ud558\uc9c0 \uc54a\uc73c\uba74, \uc798 \uc815\ub3c8\ub41c \uc124\uacc4\ub3c4\uc640 \uc2e4\uc81c \ub3c4\uc2dc\uac00 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0 \ud6e8\uc52c \uc27d\uac8c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc544\ubc14\uc2a4 \uc655\uc870\uac00 \ubd80\uc720\ud574\uc9c0\uace0 \uc601\ud5a5\ub825\uc774 \ucee4\uc9c0\uba74\uc11c \ubc14\uadf8\ub2e4\ub4dc\ub294 \uad50\uc5ed\uacfc \ubb38\ud654\uc758 \uc911\uc694\ud55c \uc911\uc2ec\uc73c\ub85c \uc131\uc7a5\ud588\ub2e4. \uc2dc\uac00\uc9c0\ub294 \uac15\uc744 \ub530\ub77c \ud37c\uc9c0\uace0 \uc8fc\ubcc0 \ub18d\uacbd\uc9c0 \ucabd\uc73c\ub85c\ub3c4 \ub113\uc5b4\uc84c\ub2e4. \uc131\ubcbd \uc548\uc758 \uc911\uc2ec\uc774 \ubd84\uba85\ud574\ub3c4 \uc0dd\ud65c\uc758 \uacbd\uacc4\uae4c\uc9c0 \uac19\uc740 \ubaa8\uc591\uc73c\ub85c \uba48\ucd94\uc9c0\ub294 \uc54a\uc558\ub2e4. \uac15\uc740 \uc9c0\ub3c4\uc5d0\uc11c \ub3c4\uc2dc\ub97c \uc7a5\uc2dd\ud558\ub294 \ud30c\ub780 \uc120\uc774 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\uacfc \ubb3c\uc790\ub97c \uc62e\uae30\ub294 \ud1b5\ub85c\uc774\uc790 \uc8fc\ubcc0\uc758 \uc0dd\uc0b0\uacfc \ub3c4\uc2dc\uc758 \uc18c\ube44\ub97c \uc787\ub294 \uc870\uac74\uc774\uc5c8\ub2e4. \uc5b4\ub290 \uae38\uc774 \uac15\uc5d0 \ub2ff\ub294\uc9c0, \ubb3c\uae38 \uc606\uc73c\ub85c \uad6c\uc5ed\uc774 \uc5b4\ub5bb\uac8c \ubd99\uc5b4 \uc788\ub294\uc9c0 \uc0b4\ud53c\uba74 \uad81\uc804\ub9cc \ubcfc \ub54c\ub294 \ub193\ucce4\ub358 \ub3c4\uc2dc\uc758 \uc6c0\uc9c1\uc784\uc774 \ubcf4\uc778\ub2e4. \ubc14\uadf8\ub2e4\ub4dc\uc5d0\ub294 \uc5ec\ub7ec \uc5b8\uc5b4\ub97c \uc4f0\uace0 \uc11c\ub85c \ub2e4\ub978 \uc804\ud1b5\uc744 \ubc30\uc6b4 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc600\ub2e4. \uc544\ubc14\uc2a4 \uc9c0\ubc30\uce35\uc758 \ud6c4\uc6d0\uc744 \ubc1b\uc544 \uadf8\ub9ac\uc2a4\uc5b4\uc640 \ud398\ub974\uc2dc\uc544\uc5b4 \ub4f1\uc73c\ub85c \uc804\ud574\uc9c0\ub358 \uc800\uc220\uc744 \uc544\ub78d\uc5b4\ub85c \uc62e\uae30\ub294 \uc791\uc5c5\ub3c4 \ud65c\ubc1c\ud574\uc84c\ub2e4. \ud559\ubb38\uc5d0 \ub300\ud55c \uad00\uc2ec\uc740 \uad81\uc815\uc758 \uad8c\uc704\uc640 \ud589\uc815, \uc2e4\uc81c \uc9c0\uc2dd\uc758 \ud544\uc694\uc640\ub3c4 \uc774\uc5b4\uc838 \uc788\uc5c8\ub2e4. \uc774 \uacfc\uc815\uc5d0\ub294 \uadf8\ub9ac\uc2a4\uc5b4\uc640 \uc2dc\ub9ac\uc544\uc5b4\ub97c \ubaa8\uad6d\uc5b4\ub85c \uc4f0\ub294 \ube44\ubb34\uc2ac\ub9bc \ud559\uc790\ub4e4\ub3c4 \ucc38\uc5ec\ud588\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ubc30\uacbd\uc758 \uc0ac\ub78c\uc774 \ud568\uaed8 \uc77c\ud588\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \ubc88\uc5ed\uc740 \ud55c \uc0ac\ub78c\uc774 \uc0ac\uc804\uc744 \ud3bc\uce58\ub294 \uc7a5\uba74\ub9cc\uc73c\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc6d0\uace0\ub97c \uad6c\ud558\uace0 \uc5b8\uc5b4\ub97c \uc774\ud574\ud558\uace0 \uc791\uc5c5\uc744 \ud6c4\uc6d0\ud558\ub294 \uad00\uacc4\uac00 \uc788\uc5b4\uc57c \ucc45 \ud55c \uad8c\uc774 \uc0c8\ub85c\uc6b4 \ub3c5\uc790\uc5d0\uac8c \uac08 \uc218 \uc788\ub2e4. \ubc88\uc5ed\ud55c \ub0b4\uc6a9\uc740 \uc5b8\uc81c\ub098 \uc190\ub300\uc9c0 \ub9d0\uc544\uc57c \ud558\ub294 \uc644\uc131\ud488\uc73c\ub85c \ucde8\uae09\ub41c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ud559\uc790\ub4e4\uc740 \uacfc\uac70\uc758 \uacfc\ud559 \uc800\uc220\uc744 \uc77d\uc73c\uba70 \ub0b4\uc6a9\uc744 \ubc14\ub85c\uc7a1\uac70\ub098 \ubcf4\ucda9\ud558\uae30\ub3c4 \ud588\ub2e4. \uc55e\uc120 \uc2dc\ub300\uc758 \uc9c0\uc2dd\uc744 \uc874\uc911\ud558\ub294 \uc77c\uacfc \uc9c0\uae08\uc758 \uc9c8\ubb38\uc744 \ub367\ubd99\uc774\ub294 \uc77c\uc774 \ud568\uaed8 \uc774\ub8e8\uc5b4\uc9c4 \uac83\uc774\ub2e4. \uc81c\uc9c0 \uae30\uc220\uc758 \ud655\uc0b0\ub3c4 \uc774\ub7f0 \ubc30\uacbd\uc5d0\uc11c \uc911\uc694\ud588\ub2e4. \ucc45\uc744 \ub9cc\ub4dc\ub294 \ube44\uc6a9\uc744 \ub0ae\ucd9c \uc218 \uc788\ub294 \uc7ac\ub8cc\uc640 \uae30\uc220\uc740 \uc9c0\uc2dd\uc744 \uc62e\uae30\ub294 \uc77c\uc758 \uc870\uac74\uc744 \ubc14\uafb8\uc5c8\ub2e4. \ubb3c\ub860 \uadf8 \uc2dc\ub300 \uc0ac\ub78c \ubaa8\ub450\uac00 \ucc45\uc744 \uc77d\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uae00\uc744 \uc77d\ub294 \uc0ac\ub78c\uc740 \uc81c\ud55c\uc801\uc774\uc5c8\uc9c0\ub9cc, \ucc45\uc774 \ub9cc\ub4e4\uc5b4\uc9c0\uace0 \uc720\ud1b5\ub420 \uac00\ub2a5\uc131\uc774 \ub113\uc5b4\uc9c0\ub294 \ubcc0\ud654\ub294 \ub3c4\uc2dc\uc758 \uc131\uaca9\uc744 \ubc14\uafb8\uc5c8\ub2e4. \uc5ec\uae30 \uc2e4\uc740 \uac83\uc740 \uc911\uc138\uc778\uc774 \ubc14\ub85c \uadf8 \uc790\ub9ac\uc5d0\uc11c \uadf8\ub9b0 \ud604\uc7a5 \uae30\ub85d\uc774 \uc544\ub2c8\ub77c, \uad50\uc7ac\uac00 1880\ub144\ub300 \uc9c0\ub3c4\ub85c \uc18c\uac1c\ud55c \ud6c4\ub300\uc758 \uc790\ub8cc\ub2e4. \uc81c\ubaa9\uc5d0\ub294 \uc774\uc2ac\ub78c\ub825 150\ub144\uc5d0\uc11c 300\ub144 \uc0ac\uc774\uc758 \ubc14\uadf8\ub2e4\ub4dc\uac00 \ud45c\uc2dc\ub418\uc5b4 \uc788\ub2e4. \uacfc\uac70 \ub3c4\uc2dc\uc758 \ubc30\uce58\ub97c \uc774\ud574\ud558\ub3c4\ub85d \uad6c\uc131\ud55c \uadf8\ub9bc\uc774\uc9c0 \ud2b9\uc815 \ud558\ub8e8\uc758 \ud56d\uacf5\uc0ac\uc9c4\uc774 \uc544\ub2c8\ub2e4. \uadf8\ub798\uc11c \uac74\ubb3c \ud558\ub098\ud558\ub098\uc758 \uc2e4\uc81c \ub192\uc774\ub098 \uac70\ub9ac\ub97c \uc774 \uadf8\ub9bc\ub9cc\uc73c\ub85c \ud655\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub300\uc2e0 \ub465\uadfc \uc911\uc2ec, \ud2f0\uadf8\ub9ac\uc2a4\uac15, \ubc14\uae65\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uae38\uc758 \uad00\uacc4\ub97c \uc77d\uae30\uc5d0 \uc88b\ub2e4. \uc81c\uc791 \uc2dc\uae30\uc640 \uadf8\ub824\uc9c4 \uc2dc\ub300\ub97c \ub098\ub204\uc5b4 \ubcf4\ub294 \uac04\ub2e8\ud55c \uc2b5\uad00\ub9cc\uc73c\ub85c\ub3c4 \uc61b \uc9c0\ub3c4\ub294 \ud6e8\uc52c \ud765\ubbf8\ub85c\uc6b4 \uc77d\uc744\uac70\ub9ac\uac00 \ub41c\ub2e4. \ubc14\uadf8\ub2e4\ub4dc \uc774\uc57c\uae30\ub97c \ub5a0\uc62c\ub9b4 \ub54c \uba4b\uc9c4 \uc6d0 \ud558\ub098\ub9cc \uae30\uc5b5\ud574\ub3c4 \ucd9c\ubc1c\uc740 \ucda9\ubd84\ud558\ub2e4. \ub2e4\ub9cc \uac70\uae30\uc11c \uac15\uacfc \uc2dc\uc7a5, \ucc45\uacfc \ubc88\uc5ed\uc790\uc758 \uc790\ub9ac\ub85c \uc870\uae08 \ub354 \uac78\uc5b4\uac00 \ubcf4\uc790. \uc218\ub3c4\uc758 \uad8c\uc704\ub97c \ud45c\ud604\ud55c \ubaa8\uc591 \uacc1\uc5d0\uc11c \uc218\ub9ce\uc740 \uc0ac\ub78c\uc774 \ub2e4\ub978 \uc774\uc720\ub85c \ub3c4\uc2dc\ub97c \ud0a4\uc6b0\uace0 \uc788\uc5c8\ub2e4. \ud55c \ub3c4\uc2dc\ub294 \uc124\uacc4\uc790\uc758 \uc758\ub3c4\ub300\ub85c\ub9cc \ub0a8\uc544 \uc788\uc9c0 \uc54a\ub294\ub2e4. \ubb3c\uac74\uc744 \uc2e4\uc5b4 \ub098\ub974\ub294 \uae38\uacfc \uc0c8\ub85c\uc6b4 \ub9d0\ub85c \uc77d\ud788\ub294 \ucc45\uc774 \uadf8 \uc548\uc5d0 \uacc4\uc18d \ub2e4\ub978 \uad00\uacc4\ub97c \ub9cc\ub4e0\ub2e4. \uc9c0\ub3c4 \ud55c\uac00\uc6b4\ub370\uc758 \ub3d9\uadf8\ub77c\ubbf8\uac00 \uc7ac\ubbf8\uc788\ub294 \uae4c\ub2ed\uc740, \uacb0\uad6d \uadf8 \uc120\ub9cc\uc73c\ub85c\ub294 \ub2e4 \ub2f4\uc744 \uc218 \uc5c6\ub294 \ubc14\uadf8\ub2e4\ub4dc\uc758 \uc0dd\ud65c\uc744 \uc0dd\uac01\ud558\uac8c \ud558\uae30 \ub54c\ubb38\uc774\ub2e4."}, {"id": "bastille-1789-gunpowder-rumor-and-symbol", "title": "\ubc14\uc2a4\ud2f0\uc720 1789 \u2014 \uac10\uc625\ubcf4\ub2e4 \ud654\uc57d\uc774 \uba3c\uc800 \ud544\uc694\ud588\ub358 \ub0a0", "summary": "\ubb34\uc7a5\uacfc \ud611\uc0c1, \uc77c\uacf1 \uc218\uac10\uc790\uc640 \ud601\uba85\uc758 \uae30\uc5b5\uc758 \ubc30\uacbd\uacfc \uc804\uac1c, \uc774\ud6c4\uc758 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/bastille-1789-gunpowder-rumor-and-symbol/index.html", "image": "../media/bastille-1789-gunpowder-rumor-and-symbol.png", "alt": "\ubc14\uc2a4\ud2f0\uc720 \uc8fc\ubcc0\uc5d0\uc11c \ud654\uc57d\uacfc \ubb34\uae30\ub97c \uad6c\ud558\ub824\ub294 \uc0ac\ub78c\ub4e4\uc744 \uc5f0\uc0c1\ud55c \uc5ed\uc0ac \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ubc14\uc2a4\ud2f0\uc720 1789 \u2014 \uac10\uc625\ubcf4\ub2e4 \ud654\uc57d\uc774 \uba3c\uc800 \ud544\uc694\ud588\ub358 \ub0a0 \ubb34\uc7a5\uacfc \ud611\uc0c1, \uc77c\uacf1 \uc218\uac10\uc790\uc640 \ud601\uba85\uc758 \uae30\uc5b5 \ubb34\uc7a5\uacfc \ud611\uc0c1, \uc77c\uacf1 \uc218\uac10\uc790\uc640 \ud601\uba85\uc758 \uae30\uc5b5\uc758 \ubc30\uacbd\uacfc \uc804\uac1c, \uc774\ud6c4\uc758 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc 1789\ub144 7\uc6d4 14\uc77c \ud30c\ub9ac \uc0ac\ub78c\ub4e4\uc774 \ubc14\uc2a4\ud2f0\uc720\ub97c \uacf5\uaca9\ud588\ub2e4. \ud754\ud788 \uc218\ub9ce\uc740 \uc815\uce58\ubc94\uc744 \ud480\uc5b4 \uc900 \uc21c\uac04\ucc98\ub7fc \uae30\uc5b5\ud558\uc9c0\ub9cc, \uadf8\ub0a0\uc758 \uc0ac\uac74\uc5d0\ub294 \ubb34\uae30\ub97c \uad6c\ud558\ub824\ub294 \uc6c0\uc9c1\uc784\uacfc \uc655\uc758 \uad70\ub300\uc5d0 \ub300\ud55c \ub450\ub824\uc6c0\uc774 \uba3c\uc800 \uc788\uc5c8\ub2e4. \uc2e4\uc81c \uc694\uc0c8\uc758 \ud558\ub8e8\uc640 \ub4a4\uc5d0 \ub9cc\ub4e4\uc5b4\uc9c4 \ud601\uba85\uc758 \uc0c1\uc9d5\uc744 \ub098\ub204\uc5b4 \uc0b4\ud3b4\ubcf4\uc790. 1789\ub144 \uc5ec\ub984 \ud504\ub791\uc2a4\uc758 \uc815\uce58\uc801 \uc9c8\uc11c\ub294 \ud754\ub4e4\ub9ac\uace0 \uc788\uc5c8\ub2e4. \ub300\ud45c\ub4e4\uc774 \ubaa8\uc5ec \uad6d\uac00\uc758 \uad8c\ud55c\uc744 \ub17c\uc758\ud588\uc9c0\ub9cc, \ud30c\ub9ac \uc8fc\ubcc0\uc5d0 \ubaa8\uc778 \uad70\ub300\uc640 \uc655\uc758 \uc758\uc911\uc744 \ub458\ub7ec\uc2fc \ubd88\uc548\uc740 \ucef8\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \uc815\uce58\uc801 \ubcc0\ud654\uac00 \ubb34\ub825\uc73c\ub85c \ub418\ub3cc\ub824\uc9c8 \uc218 \uc788\ub2e4\uace0 \uac71\uc815\ud588\ub2e4. \uc7ac\uc815 \uc704\uae30\uc640 \uba39\uc744\uac70\ub9ac \ubb38\uc81c\ub3c4 \uc774\uc5b4\uc84c\ub2e4. \uc7a5\uad00 \ub124\ucf00\ub974\uc758 \ud574\uc784 \uc18c\uc2dd\uc740 \uae34\uc7a5\uc744 \ud0a4\uc6e0\uace0 \uac70\ub9ac\uc5d0\uc11c\ub294 \uc11c\ub85c \ub2e4\ub978 \uc18c\ubb38\uacfc \uc8fc\uc7a5\uc774 \uc624\uac14\ub2e4. 7\uc6d4 14\uc77c\uc744 \uace0\ub9bd\ub41c \uac10\uc625 \uc2b5\uaca9\uc73c\ub85c \ubcf4\uae30\ubcf4\ub2e4 \uba70\uce60 \ub3d9\uc548 \uc313\uc778 \ubd88\uc548\uacfc \ubb34\uc7a5 \uc6c0\uc9c1\uc784 \uc18d\uc5d0 \ub193\uc544\uc57c \ud55c\ub2e4. \uc2dd\ub7c9 \uac00\uaca9\uc758 \uc555\ubc15\uc740 \uc815\uce58 \uc18c\uc2dd\uc744 \ubc1b\uc544\ub4e4\uc774\ub294 \ubc29\uc2dd\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc8fc\uc5c8\ub2e4. \ud558\ub8e8\uc758 \uc0dd\uacc4\ub97c \uac71\uc815\ud558\ub294 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uad70\ub300\uc758 \uc9d1\uacb0\uc740 \uad81\uc815\uc758 \uc778\uc0ac \ubb38\uc81c\uac00 \uc544\ub2c8\uc5c8\ub2e4. \ub204\uac00 \ub3c4\uc2dc\ub97c \uc9c0\ud0a4\uace0 \uc9c8\uc11c\ub97c \uc720\uc9c0\ud560 \uac83\uc778\uc9c0\uac00 \uc9c1\uc811\uc801\uc778 \uc0dd\ud65c\uc758 \ubd88\uc548\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \uc575\ubc1c\ub9ac\ub4dc \ub4f1\uc5d0\uc11c \ubb34\uae30\ub97c \uad6c\ud588\ub2e4. \uadf8\ub7ec\ub098 \ucd1d\uc774 \uc788\ub2e4\ub294 \uac83\ub9cc\uc73c\ub85c \uadf8\uac83\uc744 \uc4f8 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud654\uc57d\uacfc \ud0c4\uc57d\uc774 \ud544\uc694\ud588\ub2e4. \ubc14\uc2a4\ud2f0\uc720\uc5d0\ub294 \ud654\uc57d\uc774 \ubcf4\uad00\ub418\uc5b4 \uc788\uc5c8\uace0 \uc694\uc0c8\uc758 \ubb34\uc7a5\ub3c4 \ud30c\ub9ac \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uc704\ud611\uc73c\ub85c \ub290\uaef4\uc84c\ub2e4. \ubc14\uc2a4\ud2f0\uc720\ub97c \ud5a5\ud55c \uc6c0\uc9c1\uc784\uc740 \uadf8\ub798\uc11c \uc0c1\uc9d5\ub9cc\uc744 \ucc3e\uc544\uac04 \ud589\uc9c4\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc624\ub298 \ub2f9\uc7a5 \ubb34\uc7a5\ud558\uace0 \ubc29\uc5b4\ud560 \uc870\uac74\uc744 \uc5bb\uc73c\ub824\ub294 \uc694\uad6c\uc600\ub2e4. \ud601\uba85\uc744 \uc0dd\uac01\ud558\ub294 \ud070 \uc815\uce58\uc801 \uc5b8\uc5b4\uc640 \ud654\uc57d\uc744 \ud655\ubcf4\ud558\ub824\ub294 \uad6c\uccb4\uc801\uc778 \ud544\uc694\uac00 \uac19\uc740 \uc7a5\uc18c\uc5d0\uc11c \ub9cc\ub0ac\ub2e4. \ubb34\uc7a5\uc740 \ub3c4\uad6c\uc640 \uc870\uc9c1\uc758 \ubb38\uc81c\uc774\uae30\ub3c4 \ud588\ub2e4. \ucd1d\uc744 \ub098\ub204\uc5b4 \uac00\uc9c4 \uc0ac\ub78c\ub4e4\uc774 \uc788\ub2e4\uace0 \ud574\uc11c \ubaa8\ub450 \uac19\uc740 \uba85\ub839\uc5d0 \ub530\ub974\ub294 \uad70\ub300\uac00 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\ub4e4\uc758 \uc694\uad6c\ub97c \ub300\ud45c\ud574 \ud611\uc0c1\ud558\ub294 \uc774\ub4e4\uacfc \ud604\uc7a5\uc5d0\uc11c \ud589\ub3d9\ud558\ub294 \uc774\ub4e4\uc774 \uc11c\ub85c \ub2e4\ub978 \uc18d\ub3c4\ub85c \uc6c0\uc9c1\uc600\ub2e4\ub294 \uc810\ub3c4 \uadf8\ub0a0\uc744 \uc774\ud574\ud558\ub294 \ub370 \uc911\uc694\ud558\ub2e4. \ubc14\uc2a4\ud2f0\uc720\ub294 \uc911\uc138\uc5d0 \uc138\uc6b4 \uc694\uc0c8\uc5d0\uc11c \uc655\uc2e4 \uac10\uc625\uc73c\ub85c \uc4f0\uc774\ub294 \uacf5\uac04\uc774 \ub418\uc5c8\ub2e4. \uc7ac\ud310\uacfc \uad8c\ub825, \uc784\uc758\uc801\uc778 \uad6c\uae08\uc5d0 \uad00\ud55c \uae30\uc5b5\uc774 \uc313\uc774\uba74\uc11c \uc655\uad8c\uc758 \uc5b5\uc555\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud588\ub2e4. \ub2f9\uc77c \uc548\uc5d0 \uac07\ud78c \uc0ac\ub78c\uc758 \uc218\uac00 \uc801\uc5c8\ub2e4\uace0 \uc774\ub7f0 \uc0c1\uc9d5\uae4c\uc9c0 \uc5c6\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub3d9\uc2dc\uc5d0 \uac10\uc625\uc758 \uc2e4\uc81c \uc6b4\uc601\uc744 \ud56d\uc0c1 \uac19\uc740 \uc0c1\ud0dc\ub85c \ubcfc \uc218\ub3c4 \uc5c6\ub2e4. \uc2dc\ub300\uc640 \uc218\uac10\uc790\uc5d0 \ub530\ub77c \uc870\uac74\uc740 \ub2ec\ub790\ub2e4. \uacf5\ud3ec\uc758 \uc7a5\uc18c\ub77c\ub294 \uba85\uc131\uacfc \ud2b9\uc815 \ub0a0\uc9dc\uc5d0 \uadf8 \uc548\uc5d0 \uc788\uc5c8\ub358 \ud604\uc2e4\uc740 \uc11c\ub85c \uad00\ub828\ub418\uba74\uc11c\ub3c4 \uad6c\ubd84\ud574\uc11c \uc77d\uc5b4\uc57c \ud55c\ub2e4. \uad70\uc911\uacfc \ub300\ud45c\ub4e4\uc740 \uc694\uc0c8 \ucc45\uc784\uc790 \ub4dc \ub85c\ub124\uc640 \uc811\ucd09\ud588\ub2e4. \ubb34\uc7a5\uc744 \uce58\uc6b0\uace0 \ud654\uc57d\uc744 \ub118\uae30\ub77c\ub294 \uc694\uad6c, \uc548\uc804\uc5d0 \uad00\ud55c \uc124\uba85\uacfc \uc57d\uc18d\uc774 \uc624\uac14\ub2e4. \uadf8\ub7ec\ub098 \uc694\uc0c8 \uc548\ud30e\uc758 \uc0ac\ub78c\ub4e4\uc740 \uc0c1\ub300\uac00 \ubb34\uc5c7\uc744 \ud560\uc9c0 \ud655\uc2e0\ud558\uc9c0 \ubabb\ud588\ub2e4. \ubb38\uacfc \ub2e4\ub9ac, \uc548\ub730\uacfc \ubcbd\uc740 \ub2e8\uc21c\ud55c \ubc30\uacbd\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub514\uae4c\uc9c0 \ub4e4\uc5b4\uac14\uace0 \ubb34\uc5c7\uc744 \ubcf4\uac70\ub098 \ub4e3\uc9c0 \ubabb\ud588\ub294\uc9c0\uac00 \uae34\uc7a5\uc5d0 \uc601\ud5a5\uc744 \uc8fc\uc5c8\ub2e4. \uba3c \uacf3\uc758 \uc57d\uc18d\uacfc \ud604\uc7a5\uc758 \ud589\ub3d9\uc774 \ub2e4\ub974\uac8c \ubc1b\uc544\ub4e4\uc5ec\uc9c0\uba74\uc11c \ud611\uc0c1\uacfc \ud3ed\ub825\uc774 \ub4a4\uc5c9\ucf30\ub2e4. \uc694\uc0c8 \uc548\uc758 \uc218\ube44\ub300\uc640 \ubc14\uae65\uc758 \uad70\uc911\uc740 \uc0c1\ub300\uc758 \uc758\ub3c4\ub97c \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc54c \uc218 \uc5c6\uc5c8\ub2e4. \uc131\ubb38\uacfc \ub3c4\uac1c\uad50, \ucd1d\uc548\uc740 \ubc29\uc5b4 \uc2dc\uc124\uc774\uba74\uc11c \uc815\ubcf4\uac00 \ub04a\uae30\ub294 \uacbd\uacc4\uc600\ub2e4. \ub204\uac00 \uba3c\uc800 \ubb34\uc5c7\uc744 \ubcf4\uc558\ub294\uc9c0\uc5d0 \ub530\ub77c \uac19\uc740 \uc6c0\uc9c1\uc784\ub3c4 \uc704\ud611\uc774\ub098 \ubc30\uc2e0\uc73c\ub85c \ud574\uc11d\ub420 \uc218 \uc788\ub294 \uae34\uc7a5\ub41c \uacf5\uac04\uc774\uc5c8\ub2e4. \uc694\uc0c8\ub97c \ud5a5\ud55c \uacf5\uaca9\uacfc \ucd1d\uaca9 \uc18d\uc5d0\uc11c \uc0ac\ub78c\uc774 \uc8fd\uc5c8\ub2e4. \uc77c\ubd80 \uad70\uc778\uacfc \ub300\ud3ec\uac00 \uacf5\uaca9 \uce21\uc5d0 \uac00\ub2f4\ud558\uba74\uc11c \ud798\uc758 \uad00\uacc4\ub3c4 \ub2ec\ub77c\uc84c\ub2e4. \ucee4\ub2e4\ub780 \uc131\ubcbd\uc774 \uc788\ub2e4\uace0 \ubc29\uc5b4\uac00 \ub05d\uc5c6\uc774 \uac00\ub2a5\ud558\uac70\ub098, \ubc18\ub300\ub85c \ub9ce\uc740 \uad70\uc911\uc774 \ubaa8\uc774\uba74 \uc800\uc808\ub85c \uc810\ub839\ub418\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uacb0\uad6d \uc694\uc0c8\ub294 \ud56d\ubcf5\ud588\uc9c0\ub9cc \uadf8 \ub4a4\uc5d0\ub3c4 \ud3ed\ub825\uc774 \uc774\uc5b4\uc84c\ub2e4. \ub4dc \ub85c\ub124\ub294 \uc0b4\ud574\ub418\uc5c8\ub2e4. \uc0ac\uac74\uc744 \uc2dc\ubbfc \ubaa8\ub450\uac00 \ud55c\ub9c8\uc74c\uc73c\ub85c \ud3c9\ud654\ub86d\uac8c \uc2b9\ub9ac\ud55c \ucd95\uc81c\ub85c\ub9cc \uadf8\ub9ac\uba74 \ub2f9\uc2dc\uc758 \ud63c\ub780\uacfc \uc8fd\uc74c\uc774 \uac00\ub824\uc9c4\ub2e4. \uc655\uad8c\uc5d0 \ub300\ud55c \uc800\ud56d\uacfc \uad70\uc911\uc758 \ud3ed\ub825\uc744 \ud568\uaed8 \uae30\ub85d\ud574\uc57c \ud55c\ub2e4. \uadf8\ub0a0 \ubc14\uc2a4\ud2f0\uc720 \uc548\uc5d0\uc11c \ud480\ub824\ub09c \uc218\uac10\uc790\ub294 \uc77c\uacf1 \uba85\uc774\uc5c8\ub2e4. \ubaa8\ub450\uac00 \ubbfc\uc8fc\uc8fc\uc758\ub97c \uc8fc\uc7a5\ud558\ub2e4 \uac07\ud78c \uc815\uce58 \uc0ac\uc0c1\uac00\uc600\ub358 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uc774 \uc22b\uc790\ub294 \uc775\uc219\ud55c \ud574\ubc29\uc758 \uc7a5\uba74\uacfc \uc2e4\uc81c \uac10\uc625\uc758 \uc0c1\ud0dc \uc0ac\uc774\uc5d0 \uac70\ub9ac\uac00 \uc788\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uadf8\ub7ec\ub098 \uc801\uc740 \uc218\ub97c \ub4e4\uc5b4 \uc0ac\uac74 \uc804\uccb4\ub97c \ubb34\uc758\ubbf8\ud55c \uc624\ud574\ub85c \ub3cc\ub9ac\ub294 \uac83\ub3c4 \ub9de\uc9c0 \uc54a\ub294\ub2e4. \uc694\uc0c8\uc758 \ud654\uc57d\uacfc \ubb34\uc7a5, \uc655\uad8c\uc5d0 \ub9de\uc120 \uc2dc\ubbfc\uc758 \ud589\ub3d9, \ub3c4\uc2dc\uc5d0\uc11c\uc758 \ud798\uc758 \ubcc0\ud654\uac00 \uc911\uc694\ud588\ub2e4. \uc0c1\uc9d5\uc740 \ube48 \uc774\uc57c\uae30\uc5d0\uc11c\ub9cc \uc0dd\uae30\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc2e4\uc81c \uc0ac\uac74\uc758 \uc77c\ubd80\ub97c \ud06c\uac8c \ubb36\uc5b4 \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4. \uac74\ubb3c\uc774 \ucca0\uac70\ub41c \ub4a4\uc5d0\ub3c4 \uadf8 \ub3cc\uacfc \ubaa8\ud615, \uadf8\ub9bc\uc740 \uc0ac\uac74\uc744 \uae30\uc5b5\ud558\uac8c \ud558\ub294 \ub9e4\uac1c\uac00 \ub418\uc5c8\ub2e4. \uc694\uc0c8\uac00 \uc0ac\ub77c\uc9c0\uc790 \uc0c1\uc9d5\uc774 \uc57d\ud574\uc9c4 \uac83\uc774 \uc544\ub2c8\ub77c \uc5ec\ub7ec \uc7a5\uc18c\ub85c \ud37c\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \ud601\uba85\uc758 \uae30\uc5b5\uc740 \ud604\uc7a5\uc5d0 \ub0a8\uc740 \ubcbd\ubfd0 \uc544\ub2c8\ub77c \uc0ac\ub78c\ub4e4\uc774 \uc62e\uae30\uace0 \ubcf4\uc5ec \uc900 \ubb3c\uac74\uc744 \ud1b5\ud574\uc11c\ub3c4 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4. \ubc14\uc2a4\ud2f0\uc720\ub294 \ub4a4\uc5d0 \ucca0\uac70\ub418\uc5c8\uace0 \uadf8 \uc870\uac01\uacfc \uc774\ubbf8\uc9c0\uac00 \ud601\uba85\uc758 \uae30\uc5b5\uc73c\ub85c \ud37c\uc84c\ub2e4. \uac10\uc625\uc744 \uc5c6\uc560\ub294 \ud589\uc704 \uc790\uccb4\uac00 \uc815\uce58\uc801 \uc758\ubbf8\ub97c \uac00\uc84c\ub2e4. \uc774\ud6c4 \uae30\ub150\ud589\uc0ac\uc640 \uad6d\uac00\uc758 \uae30\uc5b5 \uc18d\uc5d0\uc11c 7\uc6d4 14\uc77c\uc740 \uacc4\uc18d \uc0c8\ub86d\uac8c \uc77d\ud614\ub2e4. \uc624\ub298\uc758 \uad6d\uacbd\uc77c\uc744 \uc124\uba85\ud560 \ub54c\uc5d0\ub294 1789\ub144\uc758 \uc0ac\uac74\uacfc \uc774\ub4ec\ud574 \uc5f0\ub9f9\uc81c \ub4f1 \ub4a4\uc758 \uae30\ub150\ub3c4 \ud568\uaed8 \uad6c\ubd84\ud560 \ud544\uc694\uac00 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uc0ac\uac74\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc704\ud55c \uc0c1\uc0c1 \uc0bd\ud654\ub2e4. \uac10\uc625\uc758 \uc2e4\uc81c \uc218\uac10\uc790\ub098 \uacf5\uaca9\uc758 \uc815\ud655\ud55c \uc21c\uac04\uc744 \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub85c \uc4f0\uc9c0\ub294 \uc54a\uc558\ub2e4. 7\uc6d4 14\uc77c\uc758 \uae30\uc5b5\uc5d0\ub294 \ub2e4\uc74c \ud574\uc778 1790\ub144 \uc5f0\ub9f9\uc81c\uc758 \uc758\ubbf8\ub3c4 \uacb9\uce5c\ub2e4. \ud2b9\uc815 \ub0a0\uc9dc\uac00 \uad6d\uac00\uc758 \uae30\ub150\uc77c\uc774 \ub418\ub294 \uacfc\uc815\uc740 \ub2f9\uc77c\uc758 \uc804\ud22c\uc640\ub294 \ub610 \ub2e4\ub978 \uc5ed\uc0ac\ub2e4. \uc0ac\uac74\uc774 \uc77c\uc5b4\ub09c \uc774\uc720\uc640 \ud6c4\ub300\uac00 \uadf8 \uc0ac\uac74\uc5d0 \ubd80\uc5ec\ud55c \uc758\ubbf8\ub97c \uad6c\ubd84\ud558\uba74 \uc0c1\uc9d5\uc744 \ub354 \uae4a\uc774 \uc774\ud574\ud560 \uc218 \uc788\ub2e4."}, {"id": "beijing-forbidden-city-gates-and-distance", "title": "\uc790\uae08\uc131 \u2014 \ubb38\uc744 \uc9c0\ub098\uba74 \ud669\uc81c\uc5d0\uac8c \uac00\uae4c\uc6cc\uc84c\uc744\uae4c", "summary": "\uc790\uae08\uc131\uc758 \ucd9c\uc785\ubb38\uacfc \uc0dd\ud65c \uacf5\uac04\uc744 \ub530\ub77c\uac00\uba70 \uac74\ucd95\uc774 \uad8c\ub825\uc758 \uac70\ub9ac\ub97c \ub9cc\ub4dc\ub294 \ubc29\uc2dd\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/beijing-forbidden-city-gates-and-distance/index.html", "image": "../media/beijing-forbidden-city-gates-and-distance.png", "alt": "\ubd89\uc740 \uad81\uad90 \ubb38\uacfc \uae08\ube5b \uc9c0\ubd95\uc774 \uc548\ucabd\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uc790\uae08\uc131\uc758 \ubd84\uc704\uae30 \uc0bd\ud654", "text": "\uc790\uae08\uc131 \u2014 \ubb38\uc744 \uc9c0\ub098\uba74 \ud669\uc81c\uc5d0\uac8c \uac00\uae4c\uc6cc\uc84c\uc744\uae4c \ubca0\uc774\uc9d5\uc758 \uad81\uad90\uc744 \ubb38\uacfc \uac70\ub9ac\uc758 \uc21c\uc11c\ub85c \uc77d\uae30 \uc790\uae08\uc131\uc758 \ucd9c\uc785\ubb38\uacfc \uc0dd\ud65c \uacf5\uac04\uc744 \ub530\ub77c\uac00\uba70 \uac74\ucd95\uc774 \uad8c\ub825\uc758 \uac70\ub9ac\ub97c \ub9cc\ub4dc\ub294 \ubc29\uc2dd\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uad81\uad90\uc744 \ucc3e\uc544\uac14\ub294\ub370 \ubb38\uc744 \ud558\ub098 \uc9c0\ub098\ub3c4 \ub610 \ubb38\uc774 \ub098\uc628\ub2e4. \ub113\uc740 \ub9c8\ub2f9\uc744 \uac74\ub108\uba74 \uc804\uac01\uc774 \ubcf4\uc774\uace0, \uadf8 \ub4a4\ub85c\ub3c4 \uacf5\uac04\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ubca0\uc774\uc9d5 \uc790\uae08\uc131\uc744 \ubcfc \ub54c\ub294 \uac74\ubb3c \ud558\ub098\ub97c \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc774 \uc21c\uc11c\uc5d0 \uba3c\uc800 \uc8fc\ubaa9\ud574 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \ub204\uad70\uac00\uc5d0\uac8c \uac00\uae4c\uc6cc\uc9c0\ub294 \uae38\uc774 \uc774\ub807\uac8c \uae38\uac8c \ub9cc\ub4e4\uc5b4\uc838 \uc788\ub2e4. \uc9c0\uae08\uc740 \uad00\ub78c\uac1d\uc774 \uad81\uad90\uc744 \uad6c\uacbd\ud558\uc9c0\ub9cc, \uadf8\uacf3\uc774 \ud669\uc81c\uc758 \uc0dd\ud65c\uacfc \ud1b5\uce58\uac00 \uc774\ub8e8\uc5b4\uc9c0\ub358 \uacf5\uac04\uc774\uc5c8\uc744 \ub54c\ub294 \uc0ac\uc815\uc774 \ub2ec\ub790\ub2e4. \ub204\uad6c\ub098 \uac19\uc740 \uacf3\uc73c\ub85c \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ub4e4\uc5b4\uac08 \uc218 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb38\uc740 \ubc14\ub78c\uc744 \ub9c9\ub294 \uad6c\uc870\ubb3c\uc774\uba74\uc11c \uc0ac\ub78c\uc744 \uad6c\ubd84\ud558\ub294 \uc7a5\uce58\uc600\ub2e4. \uba85\ub098\ub77c \uc601\ub77d\uc81c\ub294 \uc218\ub3c4\ub97c \ub09c\uc9d5\uc5d0\uc11c \ubca0\uc774\uc9d5\uc73c\ub85c \uc62e\uacbc\uace0, \ubca0\uc774\uc9d5 \uc911\uc2ec\uc5d0 \uc0c8\ub85c\uc6b4 \uad81\uad90 \ub2e8\uc9c0\ub97c \uc870\uc131\ud588\ub2e4. \uc790\uae08\uc131\uc740 \uad81\uc804 \ud55c \ucc44\uac00 \uc544\ub2c8\ub77c \ub2f4\uc7a5 \uc548\uc5d0 \uc5ec\ub7ec \uc804\uac01\uacfc \uc815\uc6d0, \uc0dd\ud65c \uacf5\uac04\uc774 \ubaa8\uc778 \ubcf5\ud569 \uacf5\uac04\uc774\uc5c8\ub2e4. \ud669\uc81c\uc640 \uadf8 \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\uc774 \uc0b4\uc544\uac08 \ud558\ub098\uc758 \uc138\uacc4\uc5d0 \uac00\uae4c\uc6e0\ub2e4. \uc218\ub3c4\ub97c \uc62e\uae34\ub2e4\ub294 \uac83\uc740 \uc8fc\uc18c\ub97c \ubc14\uafb8\ub294 \uc815\ub3c4\uc758 \uc77c\uc774 \uc544\ub2c8\ub2e4. \uba85\ub839\uc744 \ub0b4\ub9ac\ub294 \uc790\ub9ac\uc640 \uc0ac\ub78c\uc774 \ubaa8\uc774\ub294 \ubc29\ud5a5\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc0c8 \uad81\uad90\uc758 \uaddc\ubaa8\uc640 \ubc30\uce58\ub294 \uc774\uacf3\uc774 \ud1b5\uce58\uc758 \uc911\uc2ec\uc774\ub77c\ub294 \uc0ac\uc2e4\uc744 \ub208\uc5d0 \ubcf4\uc774\uac8c \ud588\ub2e4. \ubca0\uc774\uc9d5\uc774\ub77c\ub294 \ub3c4\uc2dc\uc758 \uc5ed\uc0ac\uc640 \uc790\uae08\uc131\uc758 \uc5ed\uc0ac\ub97c \ud568\uaed8 \uc77d\uc5b4\uc57c \ud558\ub294 \uc774\uc720\ub2e4. \uc790\uae08\uc131\uc758 \uc8fc\uc694 \ucd9c\uc785\ubb38\uc778 \uc624\ubb38\uc5d0\ub294 \uc5ec\ub7ec \ud1b5\ub85c\uac00 \uc788\uc5c8\ub2e4. \uac00\uc6b4\ub370 \uae38\uc740 \ud669\uc81c\uc758 \uc9c0\uc704\ub97c \ub4dc\ub7ec\ub0b4\ub294 \ud2b9\ubcc4\ud55c \ud1b5\ub85c\uc600\ub2e4. \uac19\uc740 \ubcbd\uc5d0 \ub6ab\ub9b0 \ubb38\uc774\ub77c\ub3c4 \ub204\uac00 \uc5b4\ub290 \uacf3\uc744 \uc9c0\ub098\ub294\uc9c0\uc5d0 \uc758\ubbf8\uac00 \uc2e4\ub838\ub2e4. \uac74\ucd95\uc740 \ub9d0\uc5c6\uc774 \ucc28\uc774\ub97c \uc54c\ub824 \uc904 \uc218 \uc788\uc5c8\ub2e4. OpenStax\uc758 \uc124\uba85\uc5d0\ub294 \ud669\ud6c4\uc758 \ud63c\ub840\uc640 \uacfc\uac70 \ud569\uaca9\uc790\uc758 \ud1b5\ud589 \uac19\uc740 \uc608\uc678\ub3c4 \ub4f1\uc7a5\ud55c\ub2e4. \uc608\uc678\uac00 \uc788\ub2e4\ub294 \uac83\uc740 \uaddc\uce59\uc774 \uc5c6\uc5c8\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uc624\ud788\ub824 \ud2b9\ubcc4\ud55c \ub0a0\uc758 \ud5c8\uc6a9\uc774 \uadf8 \uae38\uc758 \ud3c9\uc18c \uc704\uc0c1\uc744 \ub354 \ubd84\uba85\ud558\uac8c \ub9cc\ub4e0\ub2e4. \ub2e4\ub9cc \ud55c \uc2dc\uae30\uc758 \uc124\uba85\uc744 \ubaa8\ub4e0 \uc2dc\ub300\uc640 \ubaa8\ub4e0 \uc758\uc2dd\uc5d0 \ub611\uac19\uc774 \uc801\uc6a9\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uad00\uad11 \uc0ac\uc9c4\uc5d0\uc11c \ub9c8\ub2f9\uc740 \uac74\ubb3c\uc744 \ucc0d\uae30 \uc704\ud574 \uc9c0\ub098\uac00\ub294 \ube48 \ubd80\ubd84\ucc98\ub7fc \ubcf4\uc774\uae30\ub3c4 \ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc804\uac01\uc5d0 \uc774\ub974\uae30\uae4c\uc9c0\uc758 \uac70\ub9ac\uac00 \uae38\uc5b4\uc9c0\uba74 \uc0ac\ub78c\uc740 \uc790\uae30 \ubab8\uc758 \ud06c\uae30\ub97c \ub290\ub07c\uac8c \ub41c\ub2e4. \ub113\uc740 \uacf5\uac04\uc744 \uac74\ub108 \ub192\uc740 \uac74\ubb3c\uc744 \ub9c8\uc8fc\ud558\ub294 \uacbd\ud5d8 \uc790\uccb4\uac00 \uad81\uad90\uc758 \uc778\uc0c1\uc744 \ub9cc\ub4e0\ub2e4. \uc774\uac83\uc740 \ubaa8\ub4e0 \uad00\ub78c\uac1d\uc774 \ub611\uac19\uc774 \ub290\ub080\ub2e4\ub294 \uc8fc\uc7a5\uc774 \uc544\ub2c8\ub2e4. \uac74\ucd95\uc744 \uac10\uc0c1\ud558\ub294 \ud558\ub098\uc758 \ubc29\ubc95\uc774\ub2e4. \uc9c0\ubd95 \uc7a5\uc2dd\uc744 \ud655\ub300\ud574\uc11c \ubcf4\uae30 \uc804\uc5d0 \uc0ac\ub78c\uc774 \uc5b4\ub514\uc11c \ub4e4\uc5b4\uc640 \uc5b4\ub290 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc774\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc7a5\uc2dd\uc774 \uc54c\ub824 \uc8fc\ub294 \uc774\uc57c\uae30\uc640 \uacf5\uac04\uc774 \uc54c\ub824 \uc8fc\ub294 \uc774\uc57c\uae30\ub294 \uc870\uae08 \ub2e4\ub974\ub2e4. \uad81\uad90\uc740 \uc758\ub840\uc640 \ud1b5\uce58\ub9cc\uc744 \uc704\ud55c \ubb34\ub300\uac00 \uc544\ub2c8\uc5c8\ub2e4. \uadf8 \uc548\uc5d0\ub294 \ud669\uc81c\uc640 \ud669\ud6c4, \uc5ec\ub7ec \uad6c\uc131\uc6d0\uc774 \uba38\ubb34\ub294 \uc0dd\ud65c \uacf5\uac04\ub3c4 \uc788\uc5c8\ub2e4. \uad50\uc7ac\ub294 \ud0dc\ud654\uc804\uacfc \uac74\uccad\uad81, \uace4\ub155\uad81 \ub4f1 \uc624\ub298\ub0a0 \uc54c\ub824\uc9c4 \uc774\ub984\uc758 \uac74\ubb3c\ub4e4\uc744 \uc11c\ub85c \ub2e4\ub978 \uc5ed\ud560\uc744 \uac00\uc9c4 \uacf5\uac04\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \uad81\uad90\uc744 \ud558\ub098\uc758 \uac70\ub300\ud55c \uc655\uc88c\ub85c \uc0dd\uac01\ud558\uba74 \uc774\ub7f0 \ucc28\uc774\ub97c \ub193\uce58\uae30 \uc27d\ub2e4. \uc774\ub984\uc774 \ub2e4\ub978 \uc804\uac01\uc740 \uc0ac\ub78c\uacfc \ud65c\ub3d9\uc774 \ub2ec\ub790\ub2e4\ub294 \uc2e4\ub9c8\ub9ac\ub2e4. \ub2e4\ub9cc \uc624\ub298\uc758 \uba85\uce6d\ub9cc \ubcf4\uace0 \uc218\ubc31 \ub144 \ub3d9\uc548 \uc6a9\ub3c4\uac00 \ud55c \ubc88\ub3c4 \ubc14\ub00c\uc9c0 \uc54a\uc558\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uad81\uad90\uc740 \uc624\ub798 \uc0ac\uc6a9\ub41c \uc7a5\uc18c\ub2e4. \uc5b4\ub290 \uc655\uc870, \uc5b4\ub290 \uc2dc\uae30\uc758 \uc124\uba85\uc778\uc9c0 \ud655\uc778\ud560\uc218\ub85d \uadf8 \uacf5\uac04\uc5d0 \uc0b4\uc558\ub358 \uc2dc\uac04\uc774 \ub354 \uc785\uccb4\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4. \ud669\uc81c\uac00 \uc704\uc5c4 \uc788\uac8c \ubcf4\uc774\uae30 \uc704\ud574\uc11c\ub294 \ubb38\uacfc \ub9c8\ub2f9\ub9cc\uc73c\ub85c \ucda9\ubd84\ud558\uc9c0 \uc54a\uc558\uc744 \uac83\uc774\ub2e4. \uacf5\uac04\uc744 \uad00\ub9ac\ud558\uace0 \uc758\ub840\ub97c \uc900\ube44\ud558\uba70 \ubb3c\uac74\uc744 \uc62e\uae30\ub294 \uc77c\ub3c4 \ud544\uc694\ud558\ub2e4. \uad81\uad90\uc758 \uc774\ub984\uc774 \ud1b5\uce58\uc790 \ud55c \uc0ac\ub78c\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub354\ub77c\ub3c4, \uadf8 \uacf5\uac04\uc740 \uc218\ub9ce\uc740 \uc77c\uc0c1\uc758 \ub178\ub3d9 \uc5c6\uc774 \uc6c0\uc9c1\uc77c \uc218 \uc5c6\ub2e4. \uc815\ud655\ud55c \uc7a5\uba74\uc744 \uc0c1\uc0c1\uc73c\ub85c \ub2e8\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub300\uc2e0 \uad81\uad90\uc744 \ubcf4\ub294 \uc9c8\ubb38\uc744 \uc870\uae08 \ub113\ud790 \uc218 \uc788\ub2e4. \uc774 \ud070 \uacf5\uac04\uc740 \uc5b4\ub5bb\uac8c \uc6b4\uc601\ub418\uc5c8\uc744\uae4c, \uc5b4\ub5a4 \uc77c\uc740 \uc55e\ub9c8\ub2f9\uc5d0\uc11c \ubcf4\uc774\uace0 \uc5b4\ub5a4 \uc77c\uc740 \ub4a4\ub85c \uc228\uc5c8\uc744\uae4c. \ud654\ub824\ud55c \uc911\uc2ec\uacfc \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc8fc\ubcc0\uc744 \ud568\uaed8 \uc0dd\uac01\ud558\uba74 \uad00\uad11\uc758 \ud48d\uacbd\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \ud0dc\ud654\uc804\uacfc \uac74\uccad\uad81, \uace4\ub155\uad81 \uac19\uc740 \uc774\ub984\uc740 \ub0af\uc124\uac8c \ub4e4\ub9ac\uc9c0\ub9cc \ubb34\uc791\uc704\ub85c \ubd99\uc778 \ud45c\uc9c0\uac00 \uc544\ub2c8\ub2e4. \uc870\ud654\uc640 \ud558\ub298, \ud3c9\uc548 \uac19\uc740 \ub73b\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uac74\ubb3c\uc758 \uae30\ub2a5\uc744 \ucc3e\ub294 \uc77c\uacfc \uadf8 \uc774\ub984\uc774 \uc5b4\ub5a4 \uc774\uc0c1\uc744 \ub0b4\uc138\uc6b0\ub294\uc9c0 \uc0dd\uac01\ud558\ub294 \uc77c\uc740 \uc11c\ub85c \uc5f0\uacb0\ub41c\ub2e4. \ub2f9\ub300 \ud1b5\uce58\uc790\uac00 \uc911\uc694\ud558\uac8c \ubcf4\uc774\ub824 \ud55c \uac00\uce58\uac00 \uacf5\uac04\uc758 \uba85\uce6d\uc5d0\ub3c4 \ub2f4\uae38 \uc218 \uc788\uc5c8\ub2e4. \ubb3c\ub860 \uc774\ub984\uc774 \ud3c9\uc548\uc744 \ub9d0\ud55c\ub2e4\uace0 \uc2e4\uc81c \uad81\uad90\uc758 \ubaa8\ub4e0 \uad00\uacc4\uac00 \ud3c9\uc548\ud588\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774\ub984\uc740 \ud604\uc2e4\uc744 \uadf8\ub300\ub85c \ubcf4\uace0\ud558\ub294 \ub9d0\uc774\uba74\uc11c \ub54c\ub85c\ub294 \ubc14\ub77c\ub294 \uc9c8\uc11c\ub97c \uc120\uc5b8\ud558\ub294 \ub9d0\uc774\uae30\ub3c4 \ud558\ub2e4. \uadf8\ub798\uc11c \uc544\ub984\ub2e4\uc6b4 \ub73b\uc744 \uc54c\uc544\ubcf4\ub294 \uc990\uac70\uc6c0\uacfc, \uadf8 \uc548\uc758 \uc0b6\uc744 \ub530\ub85c \ubb3b\ub294 \ud0dc\ub3c4\ub97c \ud568\uaed8 \uac00\uc9c0\uba74 \uc88b\ub2e4. \uad81\uad90\uc740 \uc790\uc2e0\uc744 \uc5b4\ub5bb\uac8c \ubcf4\uc774\uac8c \ud560\uc9c0 \uc120\ud0dd\ud55c \uc7a5\uc18c\uc774\uae30\ub3c4 \ud588\ub2e4. \uacfc\uac70\uc5d0 \ucd9c\uc785\uc744 \uc81c\ud55c\ud558\ub358 \uad81\uad90\uc740 \uc624\ub298\ub0a0 \uc5ed\uc0ac\uc640 \uc608\uc220\uc744 \uc0b4\ud3b4\ubcf4\ub294 \ubc15\ubb3c\uad00 \uacf5\uac04\uc774 \ub418\uc5c8\ub2e4. \ud55c\ub54c \ud1b5\uce58\uc790\uc758 \uac70\ub9ac\ub97c \ub4dc\ub7ec\ub0b4\ub358 \ubb38\uc744 \uc774\uc81c \uad00\ub78c\uac1d\uc774 \uc9c0\ub098\uac04\ub2e4. \uac74\ubb3c\uc758 \uc7ac\ub8cc\ub9cc\ud07c\uc774\ub098 \uc774 \uc0ac\uc6a9 \ubc29\uc2dd\uc758 \ubcc0\ud654\ub3c4 \uc790\uae08\uc131\uc758 \uc911\uc694\ud55c \uc774\uc57c\uae30\ub2e4. \ub2e4\uc74c\uc5d0 \uad81\uad90 \uc0ac\uc9c4\uc744 \ubcf4\uac8c \ub41c\ub2e4\uba74 \uac00\uc7a5 \ud070 \uc804\uac01\ub9cc \ucc3e\uc9c0 \ub9d0\uace0, \uadf8\uacf3\uc5d0 \uc774\ub974\ub294 \uae38\uc744 \uc190\uac00\ub77d\uc73c\ub85c \ub530\ub77c\uac00 \ubcf4\uc790. \uc5b4\ub514\uc11c \uba48\ucd94\uace0 \uc5b4\ub514\ub85c \ub3cc\uc544\uac00\uc57c \ud558\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\ub294 \uac83\uc774\ub2e4. \uc790\uae08\uc131\uc740 \ud669\uc81c\uac00 \uc0b4\ub358 \uc7a5\uc18c\uc774\uba74\uc11c, \uad8c\ub825\uacfc\uc758 \uac70\ub9ac\ub97c \uac74\ucd95\uc73c\ub85c \ud45c\ud604\ud55c \uc7a5\uc18c\ub85c \uc77d\ud788\uae30 \uc2dc\uc791\ud55c\ub2e4. \uc0ac\uc9c4\uacfc \uc2e4\uc81c \ub3d9\uc120\uc744 \ube44\uad50\ud560 \ub54c\ub294 \uc0bd\ud654\uc758 \ubd84\uc704\uae30\uc640 \uac74\ucd95\uc758 \uc815\ud655\ud55c \ubc30\uce58\ub97c \uad6c\ubd84\ud558\uba74 \ub41c\ub2e4. \ubaa8\ub4e0 \ubb38\uc744 \uc678\uc6b0\uae30\ubcf4\ub2e4 \ud558\ub098\uc758 \ubb38\uc774 \ub204\uad6c\uc5d0\uac8c \uc5f4\ub838\ub294\uc9c0 \ubb3b\ub294 \uac83\uc774 \uc774 \uacf5\uac04\uc744 \uc77d\ub294 \uccab\uac78\uc74c\uc774\ub2e4."}, {"id": "borobudur-stone-stories-and-steps", "title": "\ubcf4\ub85c\ubd80\ub450\ub974 \u2014 \ub3cc\uc5d0 \uc0c8\uae34 \uc774\uc57c\uae30\ub97c \ub530\ub77c \uac77\ub2e4", "summary": "1913\ub144\uc758 \uc2e4\uc81c \uc0ac\uc9c4\uc744 \ud1b5\ud574 \uc790\ubc14\uc758 \ubd88\uad50 \uae30\ub150\ubb3c\uacfc \uc21c\ub840, \ubc14\ub2e4 \uac74\ub108 \uad50\ub958\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/borobudur-stone-stories-and-steps/index.html", "image": "../media/borobudur-stone-stories-and-steps.jpg", "alt": "1913\ub144 \ubcf4\ub85c\ubd80\ub450\ub974 \uc0ac\uc9c4. \ub3cc\uacc4\ub2e8\uacfc \ubd80\uc870, \uc704\ucabd\uc758 \uad6c\uba4d \ub09c \uc2a4\ud22c\ud30c\uc640 \ub4a4\ud3b8\uc758 \uc0b0.", "text": "\ubcf4\ub85c\ubd80\ub450\ub974 \u2014 \ub3cc\uc5d0 \uc0c8\uae34 \uc774\uc57c\uae30\ub97c \ub530\ub77c \uac77\ub2e4 \ud070 \uae30\ub150\ubb3c\uc5d0\uc11c \uc791\uc740 \uc870\uac01\uc73c\ub85c \uc2dc\uc120\uc744 \uc62e\uae30\uba74 1913\ub144\uc758 \uc2e4\uc81c \uc0ac\uc9c4\uc744 \ud1b5\ud574 \uc790\ubc14\uc758 \ubd88\uad50 \uae30\ub150\ubb3c\uacfc \uc21c\ub840, \ubc14\ub2e4 \uac74\ub108 \uad50\ub958\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ub192\uc740 \ud0d1\uc774\ub098 \ud070 \uac74\ubb3c\uc744 \ub9cc\ub098\uba74 \uba3c\uc800 \uc804\uccb4\ub97c \uc0ac\uc9c4\uc5d0 \ub2f4\uace0 \uc2f6\uc5b4\uc9c4\ub2e4. \uadf8\ub7f0\ub370 \uc778\ub3c4\ub124\uc2dc\uc544 \uc790\ubc14\uc758 \ubcf4\ub85c\ubd80\ub450\ub974\uc5d0\uc11c\ub294 \uc870\uae08 \uac00\uae4c\uc774 \ub2e4\uac00\uac08 \uc774\uc720\ub3c4 \uc788\ub2e4. \uac70\ub300\ud55c \uad6c\uc870\ubb3c\uc758 \ubcbd\uc5d0 \uc791\uc740 \uc7a5\uba74\ub4e4\uc774 \uc0c8\uaca8\uc838 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uba40\ub9ac\uc11c \ubcf8 \ub369\uc5b4\ub9ac\uc640 \uac78\uc73c\uba70 \ub9cc\ub098\ub294 \ud45c\uba74\uc740 \uc11c\ub85c \ub2e4\ub978 \uacbd\ud5d8\uc744 \uc900\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 1913\ub144\uc758 \uc2e4\uc81c \uc0ac\uc9c4\uc774\ub2e4. \ub3cc\uae38\uacfc \uc870\uac01, \uc704\ucabd\uc758 \uc885 \ubaa8\uc591 \uad6c\uc870\ubb3c, \uba40\ub9ac \ubcf4\uc774\ub294 \uc0b0\uc774 \ud55c \ud654\uba74\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc624\ub298\uc758 \uad00\uad11 \uc548\ub0b4\ub3c4\ub294 \uc544\ub2c8\uc9c0\ub9cc, \uc0ac\ub78c\uc758 \ud06c\uae30\uc640 \uac74\ucd95\uc758 \ud06c\uae30\ub97c \ube44\uad50\ud558\uba70 \uc624\ub798\ub41c \uc7a5\uc18c\ub97c \uc77d\uae30\uc5d0 \uc88b\uc740 \ucd9c\ubc1c\uc810\uc774\ub2e4. \ubcf4\ub85c\ubd80\ub450\ub974\ub294 \uc624\ub298\ub0a0 \uc778\ub3c4\ub124\uc2dc\uc544 \uc911\ubd80 \uc790\ubc14\uc5d0 \uc788\ub2e4. \uad50\uc7ac\ub294 \ubd88\uad50\ub97c \ud6c4\uc6d0\ud55c \uc0e4\uc77c\ub80c\ub4dc\ub77c \uc655\ub4e4\uc758 \uc2dc\uae30\uc640 \uc774 \uae30\ub150\ubb3c\uc758 \uac74\uc124\uc744 \uc5f0\uacb0\ud55c\ub2e4. \uc9c0\uae08\uc758 \uad6d\uacbd\uc774\ub098 \uc885\uad50 \ubd84\ud3ec\ub9cc\uc73c\ub85c \uc61b \uc790\ubc14\uc758 \ubaa8\uc2b5\uc744 \uc9d0\uc791\ud558\uba74 \uc774\ub7f0 \ud070 \ubd88\uad50 \uac74\ucd95\uc758 \uc874\uc7ac\uac00 \ub73b\ubc16\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uacfc\uac70\uc758 \ub3d9\ub0a8\uc544\uc2dc\uc544\uc5d0\ub294 \uc11c\ub85c \ub2e4\ub978 \uc2e0\uc559\uacfc \uad8c\ub825\uc774 \uc790\ub9ac\ud588\ub2e4. \uac00\uae4c\uc6b4 \uc9c0\uc5ed\uc774\ub77c\uace0 \ubaa8\ub450 \uac19\uc740 \uae38\uc744 \uac78\uc740 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \ubcf4\ub85c\ubd80\ub450\ub974\ub294 \uadf8 \uac00\uc6b4\ub370 \ubd88\uad50\uac00 \uac74\ucd95\uacfc \ubbf8\uc220, \ud1b5\uce58\uc790\uc758 \ud6c4\uc6d0\uc73c\ub85c \ud45c\ud604\ub41c \uacbd\uc6b0\ub2e4. \ud558\ub098\uc758 \uc720\uc801\uc740 \ud55c \ub098\ub77c\uc758 \uc624\ub298\uacfc \ub2e4\ub978 \uc2dc\ub300\uc758 \ud48d\uacbd\uc744 \ud568\uaed8 \ubcf4\uc5ec \uc900\ub2e4. \uc0ac\uc9c4 \uc18d\uc758 \uc0ac\ub78c\uc744 \uae30\uc900\uc73c\ub85c \ub3cc\ubcbd\uc744 \ubcf4\uba74 \uc138\ubd80 \uc870\uac01\uc758 \ud06c\uae30\ub97c \uac00\ub2a0\ud560 \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc774\uacf3\uc5d0 2,600\uac1c\uac00 \ub118\ub294 \ubd80\uc870 \ud328\ub110\uc774 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubd80\uc870\ub294 \ub3cc\uc758 \ud45c\uba74\uc744 \uae4e\uc544 \uc7a5\uba74\uc774 \ub3c4\ub4dc\ub77c\uc838 \ubcf4\uc774\uac8c \ud55c \ud45c\ud604\uc774\ub2e4. \uc22b\uc790\ub97c \uc678\uc6b0\uae30\ubcf4\ub2e4 \uac74\ucd95\uc758 \ub9ce\uc740 \uba74\uc774 \uc774\uc57c\uae30\uc758 \uc790\ub9ac\uac00 \ub418\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uc88b\ub2e4. \uba40\ub9ac\uc11c \ubcfc \ub54c\ub294 \uce35\uacfc \uc724\uacfd\uc774 \uba3c\uc800 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uac00\uae4c\uc774\uc5d0\uc11c\ub294 \uc778\ubb3c\uacfc \uc7a5\uc2dd\uc758 \uc791\uc740 \ucc28\uc774\ub97c \uc0b4\ud53c\uac8c \ub41c\ub2e4. \uac19\uc740 \uac74\ucd95\ubb3c\uc774 \uc2dc\uc120\uc758 \uac70\ub9ac\uc5d0 \ub530\ub77c \ub2e4\ub974\uac8c \uc77d\ud788\ub294 \uac83\uc774\ub2e4. \uc0ac\uc9c4 \ud55c \uc7a5\uc73c\ub85c \ubaa8\ub4e0 \uc7a5\uba74\uc758 \ub0b4\uc6a9\uc744 \uc54c\uc544\ub0bc \uc218\ub294 \uc5c6\uc9c0\ub9cc, \ubcbd\uc774 \ub2e8\uc21c\ud55c \uacbd\uacc4 \uc774\uc0c1\uc774\ub77c\ub294 \uc810\uc740 \ub290\ub084 \uc218 \uc788\ub2e4. \uc0ac\uc9c4\uc758 \uc704\ucabd\uc5d0\ub294 \uc791\uc740 \uad6c\uba4d\uc774 \ub09c \uc885 \ubaa8\uc591\uc758 \uc2a4\ud22c\ud30c\ub4e4\uc774 \ubcf4\uc778\ub2e4. \uad50\uc7ac\ub294 \uc911\uc559\uc758 \ud070 \uad6c\uc870\ubb3c \uc8fc\uc704\uc5d0 72\uac1c\uc758 \uc774\ub7f0 \uc2a4\ud22c\ud30c\uac00 \uc788\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ucc98\uc74c \ubcf4\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ub3cc\ub85c \ub9cc\ub4e0 \ubc14\uad6c\ub2c8\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \ub0af\uc120 \uc774\ub984\uc744 \uc678\uc6b0\uae30 \uc804\uc5d0 \ubc18\ubcf5\ub418\ub294 \ubaa8\uc591\uc744 \uc0b4\ud3b4\ubcf4\uc790. \uc791\uc740 \ud615\ud0dc\ub4e4\uc774 \ud568\uaed8 \ub193\uc774\uba74 \uc804\uccb4\uc758 \uc9c8\uc11c\uac00 \uc0dd\uae34\ub2e4. \uac01\uac01\uc758 \uad6c\uba4d\uacfc \uace1\uba74, \uadf8 \ub108\uba38\uc758 \uc0b0\uc744 \ubc88\uac08\uc544 \ubcf4\uba74 \ub3cc \uac74\ucd95\uc774 \uc8fc\ubcc0 \ud48d\uacbd\uacfc \ub9cc\ub098\ub294 \ubc29\uc2dd\ub3c4 \ubcf4\uc778\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \ud655\uc778\ud55c \ud615\ud0dc\uc640 \uc885\uad50\uc801 \uc0c1\uc9d5\uc758 \uc138\ubd80 \ud574\uc11d\uc740 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ubcf4\uc774\ub294 \ubaa8\ub4e0 \uc7a5\uc2dd\uc744 \ub9c8\uc74c\ub300\ub85c \ud558\ub098\uc758 \ub73b\uc73c\ub85c \ud480 \ud544\uc694\ub294 \uc5c6\ub2e4. \uad50\uc7ac\ub294 \ub3d9\ub0a8\uc544\uc2dc\uc544 \uc5ec\ub7ec \uc9c0\uc5ed\uc758 \ubd88\uad50\ub3c4\ub4e4\uc774 \ubcf4\ub85c\ubd80\ub450\ub974\ub97c \uc21c\ub840\ud588\uace0, \ud759\uc73c\ub85c \ub9cc\ub4e0 \uc791\uc740 \ud310\uacfc \uadf8\ub987 \uac19\uc740 \ubd09\ud5cc\ubb3c\uc744 \ub0a8\uacbc\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud070 \ub3cc \uac74\ubb3c\ub9cc \uc788\uc5c8\ub358 \uac83\uc774 \uc544\ub2c8\ub77c \uadf8\uacf3\uc73c\ub85c \uc774\ub3d9\ud55c \uc0ac\ub78c\ub4e4\uc758 \uc791\uc740 \ubb3c\uac74\ub3c4 \uc788\uc5c8\ub2e4. \uae30\ub150\ubb3c\uc758 \uc5ed\uc0ac\ub294 \uac74\uc124\uc744 \ub05d\ub0b8 \ub0a0 \ub4a4\uc5d0\ub3c4 \uc774\uc5b4\uc84c\ub2e4. \uc21c\ub840\ub294 \uc2e0\uc559\uc744 \ud2b9\uc815 \uc7a5\uc18c\uc5d0\uc11c \uc2e4\ucc9c\ud558\ub294 \uc5ec\ud589\uc774\uc5c8\ub2e4. \ub204\uac00 \uc5b4\ub290 \ub0a0 \uc5b4\ub5a4 \ub9c8\uc74c\uc73c\ub85c \uc654\ub294\uc9c0\uae4c\uc9c0 \uae30\ub85d \uc5c6\uc774 \ubcf5\uc6d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \ucc3e\uc544\uc628 \uc0ac\ub78c\ub4e4\uc774 \ud754\uc801\uc744 \ub0a8\uacbc\ub2e4\ub294 \uc0ac\uc2e4\uc5d0\uc11c \uac74\ucd95\uc774 \ubc18\ubcf5\ub418\ub294 \ubc29\ubb38\uc758 \ubaa9\uc801\uc9c0\uac00 \ub418\uc5c8\uc74c\uc744 \uc54c \uc218 \uc788\ub2e4. \ud070 \uc720\uc801 \uc606\uc758 \uc791\uc740 \ubb3c\uac74\ub3c4 \uc911\uc694\ud55c \uc790\ub8cc\uac00 \ub41c\ub2e4. \uc790\ubc14\uac00 \uc12c\uc774\ub77c\ub294 \uc774\uc720\ub85c \uace0\ub9bd\ub41c \uc7a5\uc18c\uc600\ub2e4\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uad50\uc7ac\ub294 \uc774 \uc9c0\uc5ed\uc744 \uc778\ub3c4\uc591\uacfc \ud574\ud611\uc744 \ud1b5\ud55c \uad50\uc5ed\uc758 \ud750\ub984 \uc18d\uc5d0\uc11c \uc124\uba85\ud55c\ub2e4. \uc778\ub3c4\uc5d0\uc11c \uc804\ud574\uc9c4 \uc885\uad50\uc640 \ubbf8\uc220\uc758 \uc601\ud5a5\ub3c4 \uc788\uc5c8\ub2e4. \ubc14\ub2e4\ub294 \ub5a8\uc5b4\ub728\ub9ac\ub294 \uacbd\uacc4\uc774\uba74\uc11c \uc0ac\ub78c\uacfc \uc0dd\uac01\uc774 \uc624\uac00\ub294 \uae38\uc774\uae30\ub3c4 \ud588\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubcf4\ub85c\ubd80\ub450\ub974\ub97c \uc678\ubd80\uc758 \uc124\uacc4\ub97c \uadf8\ub300\ub85c \uc62e\uaca8 \ub193\uc740 \ubb3c\uac74\uc73c\ub85c\ub9cc \ubcfc \uc218\ub294 \uc5c6\ub2e4. \ubb34\uc5c7\uc744 \ubc1b\uc544\ub4e4\uc774\uace0 \uc5b4\ub5a4 \uaddc\ubaa8\ub85c \uc138\uc6b0\uba70 \uc5b4\ub5bb\uac8c \ud6c4\uc6d0\ud560\uc9c0\ub294 \ud604\uc9c0\uc758 \uc120\ud0dd\uacfc \uc5ed\ub7c9\uc5d0 \ub2ec\ub824 \uc788\uc5c8\ub2e4. \uc601\ud5a5\uc744 \uc8fc\uace0\ubc1b\ub294\ub2e4\ub294 \ub9d0\uc5d0\ub294 \ubc1b\ub294 \ucabd\uc758 \ud65c\ub3d9\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \ucee4\ub2e4\ub780 \ub3cc \uac74\ucd95 \uc790\uccb4\uac00 \uadf8 \ub178\ub825\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uad50\uc7ac\ub294 \uc774 \uc9c0\uc5ed\uc758 \ud1b5\uce58\uc790\ub4e4\uc774 \uc2e0\uc559\uc744 \ud6c4\uc6d0\ud558\uba70 \uc790\uc2e0\uc758 \uc815\ub2f9\uc131\uc744 \ub4dc\ub7ec\ub0c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc885\uad50 \uac74\ucd95\uc740 \uc2e0\uc559\uc758 \ud45c\ud604\uc774\uba74\uc11c \ub9ce\uc740 \uc790\uc6d0\uacfc \ub178\ub3d9\uc744 \ubaa8\uc744 \uc218 \uc788\ub294 \ud798\uc758 \ud45c\uc2dc\uc774\uae30\ub3c4 \ud588\ub2e4. \uc544\ub984\ub2e4\uc6c0\uacfc \uad8c\ub825\uc740 \uac19\uc740 \uc7a5\uc18c\uc5d0 \ud568\uaed8 \ub0a8\uc744 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc774\ub7f0 \uad00\uacc4\ub97c \uc548\ub2e4\uace0 \ubaa8\ub4e0 \ubc29\ubb38\uc790\uc758 \uacbd\ud5d8\uc774 \uac19\uc558\ub2e4\uace0 \ud560 \uc218\ub294 \uc5c6\ub2e4. \uc655\uc2e4\uc758 \ubaa9\uc801\uacfc \uc21c\ub840\uc790\uc758 \uae30\ub3c4, \ub3cc\uc744 \ub2e4\ub4ec\uc740 \uc0ac\ub78c\uc758 \uc77c\uc740 \uc11c\ub85c \ub2e4\ub978 \uc790\ub9ac\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc84c\ub2e4. \ud55c \uac74\ubb3c\uc5d0 \ucc38\uc5ec\ud55c \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc5ed\ud560\uc744 \uc0dd\uac01\ud558\uba74 \uae30\ub150\ubb3c\uc740 \uc774\ub984\ub09c \uc655 \ud55c \uba85\uc758 \uc5c5\uc801\uc73c\ub85c\ub9cc \uba38\ubb3c\uc9c0 \uc54a\ub294\ub2e4. \uc774 \uc0ac\uc9c4\uc740 \ud604\uc7ac\uc758 \ubcf4\uc874 \uc0c1\ud0dc\ub97c \uc2e4\uc2dc\uac04\uc73c\ub85c \ubcf4\uc5ec \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \ub610\ud55c \uc0ac\uc9c4\uc5d0 \uc0ac\ub78c\uc774 \ud55c \uba85 \ubcf4\uc778\ub2e4\uace0 \ub2f9\uc2dc \ubc29\ubb38\uc790\uac00 \ub298 \uc801\uc5c8\ub2e4\uace0 \uacb0\ub860 \ub0bc \uc218\ub3c4 \uc5c6\ub2e4. \ucd2c\uc601\ub41c \uc21c\uac04\uacfc \uc720\uc801 \uc804\uccb4\uc758 \uc624\ub79c \uc5ed\uc0ac\ub294 \ub2e4\ub978 \ubc94\uc704\uc758 \uc790\ub8cc\ub2e4. \uc0ac\uc9c4\uc758 \uc5f0\ub3c4\ub97c \uc544\ub294 \uc77c\uc740 \uc0c1\uc0c1\uc744 \ub9c9\uae30\ubcf4\ub2e4 \uac10\uc0c1\uc758 \uc790\ub9ac\ub97c \uc815\ud655\ud788 \uc7a1\uc544 \uc900\ub2e4. \ub300\uc2e0 \uc0ac\uc9c4\uc774 \uc798 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc744 \ucc28\ubd84\ud788 \uc77d\uc744 \uc218 \uc788\ub2e4. \ub3cc\uc758 \ubc18\ubcf5, \uae38\uacfc \ubcbd\uc758 \uad00\uacc4, \uc870\uac01 \uc606\uc5d0 \uc120 \uc0ac\ub78c\uc758 \ud06c\uae30\ub2e4. \uc624\ub798\ub41c \uc0ac\uc9c4\uc744 \ubcf4\ub294 \uc990\uac70\uc6c0\uc740 \ub2f9\uc2dc\uc758 \ubaa8\ub4e0 \uac83\uc744 \uc548\ub2e4\uace0 \ub290\ub07c\ub294 \ub370\ub9cc \uc788\uc9c0 \uc54a\ub2e4. \ubb34\uc5c7\uc774 \ub0a8\uc544 \uc788\uace0 \ubb34\uc5c7\uc740 \ud654\uba74 \ubc16\uc5d0 \uc788\ub294\uc9c0 \ucc3e\uc544\ubcf4\ub294 \ub370\uc5d0\ub3c4 \uc788\ub2e4. \ubcf4\ub85c\ubd80\ub450\ub974\ub97c \uae30\uc5b5\ud560 \ub54c\ub294 \uac70\ub300\ud55c \uae30\ub150\ubb3c\uc758 \uc724\uacfd\uacfc \uc791\uc740 \ub3cc\uc870\uac01\uc744 \ud568\uaed8 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uba40\ub9ac\uc11c \ubc14\ub77c\ubcf4\uace0 \uac00\uae4c\uc774\uc5d0\uc11c \uc0b4\ud53c\ub294 \ub450 \uc2dc\uc120\uc774 \ud55c \uc7a5\uc18c \uc548\uc5d0 \uc788\ub2e4. \uc5ec\uae30\uc5d0 \ubc14\ub2e4\ub97c \uac74\ub108\uc628 \uc2e0\uc559\uacfc \uc21c\ub840\uc790\uc758 \ubb3c\uac74\uae4c\uc9c0 \ub354\ud558\uba74 \ub3cc \uac74\ucd95\uc740 \ud6e8\uc52c \ub9ce\uc740 \uc6c0\uc9c1\uc784\uc744 \ud488\ub294\ub2e4. \ub2e4\uc74c\uc5d0 \uc720\uba85\ud55c \uac74\ucd95\uc744 \ub9cc\ub098\uba74 \uc804\uccb4 \uc0ac\uc9c4\uc744 \ucc0d\uc740 \ub4a4 \ubcbd \uac00\uae4c\uc774\uc5d0\uc11c\ub3c4 \uc7a0\uc2dc \uba48\ucdb0 \ubcf4\uba74 \uc5b4\ub5a8\uae4c. \ud558\ub098\uc758 \uc7a5\uba74\uacfc \ubc18\ubcf5\ub418\ub294 \ubaa8\uc591\uc774 \ub208\uc5d0 \ub4e4\uc5b4\uc62c \uc218 \uc788\ub2e4. \ubcf4\ub85c\ubd80\ub450\ub974\ub294 \ud070 \uc7a5\uc18c\ub97c \uc774\ud574\ud558\ub294 \ub610 \ud558\ub098\uc758 \ubc29\ubc95\uc774 \uc791\uc740 \ud45c\uba74\uc744 \uc77d\ub294 \uc77c\uc784\uc744 \uc54c\ub824 \uc900\ub2e4."}, {"id": "boston-tea-tax-and-harbor", "title": "\ubcf4\uc2a4\ud134 \u2014 \ucc28\ub97c \ubc14\ub2e4\uc5d0 \ub358\uc9c4 \ub0a0", "summary": "1773\ub144 \ucc28 \ubb34\uc5ed \ubb38\uc11c\uc640 \ud6c4\ub300\uc758 \ud3b8\ucc2c \uae30\ub85d\uc744 \ubc14\ud0d5\uc73c\ub85c \ucc28\ubc95\u00b7\ubc18\ubc1c\u00b7\ubcf4\uc2a4\ud134 \ud56d\uad6c\uc758 \uc0ac\uac74\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/boston-tea-tax-and-harbor/index.html", "image": "../media/boston-tea-tax-and-harbor.png", "alt": "\ubcf4\uc2a4\ud134 \ucc28 \uc0ac\uac74\uc744 \ub5a0\uc62c\ub9ac\ub294 \ubc24\uc758 \ubd80\ub450\uc640 \ucc28 \uc0c1\uc790\uc758 \uc0c1\uc0c1 \uc7a5\uba74", "text": "\ubcf4\uc2a4\ud134 \u2014 \ucc28\ub97c \ubc14\ub2e4\uc5d0 \ub358\uc9c4 \ub0a0 1773\ub144\uc758 \ucc3b\uc78e\uacfc \uc0c1\uc778, \uc758\ud68c\uc758 \uacfc\uc138 \uad8c\ud55c 1773\ub144 \ucc28 \ubb34\uc5ed \ubb38\uc11c\uc640 \ud6c4\ub300\uc758 \ud3b8\ucc2c \uae30\ub85d\uc744 \ubc14\ud0d5\uc73c\ub85c \ucc28\ubc95\u00b7\ubc18\ubc1c\u00b7\ubcf4\uc2a4\ud134 \ud56d\uad6c\uc758 \uc0ac\uac74\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ucc28\ub294 \ub9c8\uc2dc\ub824\uace0 \ubc30\uc5d0 \uc2e4\uc5c8\ub2e4. \uadf8\ub7f0\ub370 \ubcf4\uc2a4\ud134 \ud56d\uad6c\uc5d0\uc11c\ub294 \uadf8 \ucc28\uac00 \ucc3b\uc794\uc774 \uc544\ub2c8\ub77c \ubc14\ub2f7\ubb3c\ub85c \ub4e4\uc5b4\uac14\ub2e4. 1773\ub144 12\uc6d4 16\uc77c \ubc24\uc758 \uc77c\uc774\uc5c8\ub2e4. \uac12\ub098\uac00\ub294 \uc0c1\ud488\uc744 \uc77c\ubd80\ub7ec \ubc84\ub9ac\ub294 \ud589\ub3d9\uc740 \uc65c \ub9ce\uc740 \uc0ac\ub78c\uc5d0\uac8c \uc800\ud56d\uc758 \uc0c1\uc9d5\uc774 \ub418\uc5c8\uc744\uae4c. \ud754\ud788 \ucc28\uc5d0 \uc138\uae08\uc744 \ub9e4\uaca8\uc11c \uc0dd\uae34 \uc0ac\uac74\uc774\ub77c\uace0 \uae30\uc5b5\ud558\uc9c0\ub9cc \uadf8 \ub9d0\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud558\ub2e4. \ub204\uac00 \uc138\uae08\uc744 \uc815\ud560 \uc218 \uc788\ub294\uc9c0, \uc5b4\ub5a4 \ud68c\uc0ac\uac00 \ucc28\ub97c \ud314\uace0 \ub204\uad6c\uc758 \uac70\ub798\uac00 \ubc14\ub00c\ub294\uc9c0\uac00 \ud568\uaed8 \uac78\ub824 \uc788\uc5c8\ub2e4. \ucc3b\uc78e\uc744 \ub530\ub77c\uac00 \ubcf4\uba74 \uc81c\uad6d\uc758 \uad8c\ud55c\uacfc \uc0ac\ub78c\ub4e4\uc758 \uc0dd\ud65c\uc774 \ub9cc\ub098\ub294 \uc790\ub9ac\uac00 \ubcf4\uc778\ub2e4. \ucc28\ub294 \uc601\uad6d\uc758 \ubd81\uc544\uba54\ub9ac\uce74 \uc2dd\ubbfc\uc9c0\uc5d0\uc11c \ub0af\uc120 \ubb3c\uac74\uc774 \uc544\ub2c8\uc5c8\ub2e4. \u300eTea Leaves\u300f\uc5d0 \ubb36\uc778 \ub2f9\uc2dc\uc758 \ud3b8\uc9c0\ub4e4\uc740 \ucc28\uc758 \uc18c\ube44\uc640 \uac00\uaca9, \uc5b4\ub5a4 \uacbd\ub85c\ub85c \ub4e4\uc5ec\uc624\ub294\uc9c0\uc5d0 \uad00\uc2ec\uc744 \ubcf4\uc778\ub2e4. \uc815\uce58\uc801 \uc0c1\uc9d5\uc774 \ub418\uae30 \uc804\uc5d0 \uc2e4\uc81c\ub85c \uc0ac\ub78c\ub4e4\uc774 \uc0ac\uace0 \ub9c8\uc2dc\ub358 \uc0c1\ud488\uc774\uc5c8\ub2e4. \ubc00\uc218\ub85c \ub4e4\uc5b4\uc624\ub294 \ucc28\ub3c4 \uac70\ub798\uc758 \uc77c\ubd80\uc600\ub2e4. \uc601\uad6d \ub3d9\uc778\ub3c4\ud68c\uc0ac\ub97c \ud1b5\ud55c \uc815\uc2dd \uac70\ub798\uc640 \ub2e4\ub978 \uacbd\ub85c \uc0ac\uc774\uc5d0\ub294 \uac00\uaca9\uacfc \uc138\uae08\uc758 \ucc28\uc774\uac00 \uc788\uc5c8\ub2e4. \uac19\uc740 \ucc28\ub97c \uc0ac\ub294 \uc77c\uc5d0\ub3c4 \uad6d\uac00\uac00 \uc815\ud55c \uaddc\uce59\uacfc \uc0c1\uc778\ub4e4\uc758 \uc774\uc775\uc774 \uacb9\uccd0 \uc788\uc5c8\ub2e4. \ucc3b\uc794\uc740 \uba40\ub9ac \uc788\ub294 \uc81c\ub3c4\uc640 \ubb34\uad00\ud55c \uc0dd\ud65c\uc6a9\ud488\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc601\uad6d \ub3d9\uc778\ub3c4\ud68c\uc0ac\ub294 \uc313\uc778 \ucc28\uc640 \uc7ac\uc815 \ubb38\uc81c\ub97c \uc548\uace0 \uc788\uc5c8\ub2e4. 1773\ub144 \ucc28\ubc95\uc740 \ud68c\uc0ac\uac00 \uc544\uba54\ub9ac\uce74\ub85c \ubcf4\ub0b4\ub294 \ucc28\uc5d0 \ub300\ud574 \uc601\uad6d \ucabd \uad00\uc138\ub97c \ub3cc\ub824\ubc1b\ub3c4\ub85d \ud558\uace0, \uc2dd\ubbfc\uc9c0\uc5d0\uc11c \ub0b4\ub294 \ucc28 \uc138\uae08\uc740 \ub0a8\uaca8 \ub450\ub294 \uad6c\uc870\uc600\ub2e4. \ud68c\uc0ac\uac00 \uc815\uc2dd \ucc28\ub97c \ub354 \uacbd\uc7c1\ub825 \uc788\uac8c \ud314 \uc218 \uc788\ub3c4\ub85d \ud558\ub824\ub294 \uc120\ud0dd\uc774\uc5c8\ub2e4. \ub530\ub77c\uc11c \ucc28\uac12\uc744 \ubb34\uc870\uac74 \ub354 \ube44\uc2f8\uac8c \ub9cc\ub4e4\ub824\uace0 \uc0c8 \uc138\uae08\uc744 \uc5b9\uc5c8\ub2e4\ub294 \ud55c \ubb38\uc7a5\uc73c\ub85c \uc124\uba85\ud558\uae30 \uc5b4\ub835\ub2e4. \ubc95\uc744 \ucd94\uc9c4\ud55c \ucabd\uc740 \ud569\ubc95\uc801\uc778 \ucc28\uac00 \uac00\uaca9\uc5d0\uc11c\ub3c4 \uacbd\uc7c1\ud560 \uc218 \uc788\ub2e4\uace0 \uae30\ub300\ud588\ub2e4. \ud558\uc9c0\ub9cc \uc2fc \ubb3c\uac74\uc744 \uc81c\uacf5\ud558\uba74 \uc0ac\ub78c\ub4e4\uc758 \uc815\uce58\uc801 \ubc18\ubc1c\ub3c4 \uc0ac\ub77c\uc9c8 \uac83\uc774\ub77c\ub294 \ud310\ub2e8\uc740 \ub9de\uc9c0 \uc54a\uc558\ub2e4. \uc2dd\ubbfc\uc9c0\uc758 \ubc18\ub300\uc790\ub4e4\uc740 \uc790\uc2e0\ub4e4\uc774 \ub300\ud45c\ub97c \ubcf4\ub0b4\uc9c0 \ubabb\ud558\ub294 \uc601\uad6d \uc758\ud68c\uac00 \uc138\uae08\uc744 \uc815\ud558\ub294 \uad8c\ud55c\uc744 \ubb38\uc81c \uc0bc\uc558\ub2e4. \uc5bc\ub9c8\ub97c \ub0b4\ub294\uc9c0\uc640 \ub204\uac00 \ub3d9\uc758\ud588\ub294\uc9c0\ub294 \ub2e4\ub978 \uc9c8\ubb38\uc774\uc5c8\ub2e4. \ucc28\ub97c \uc0ac\ub294 \ud589\uc704\uac00 \uadf8 \uacfc\uc138 \uad8c\ud55c\uc744 \ubc1b\uc544\ub4e4\uc774\ub294 \ud589\ub3d9\uc73c\ub85c \ud574\uc11d\ub420 \uc218 \uc788\uc5c8\ub2e4. \uc0c1\uc778\ub4e4\uc5d0\uac8c\ub294 \uac70\ub798\uc758 \uad6c\uc870\ub3c4 \uc911\uc694\ud588\ub2e4. \ud68c\uc0ac\uac00 \uc9c0\uc815\ud55c \ud310\ub9e4 \uad00\uacc4\ub294 \uae30\uc874 \ucc28 \uc0c1\uc778\uc758 \uc774\ud574\uc640 \ucda9\ub3cc\ud560 \uc218 \uc788\uc5c8\ub2e4. \ub530\ub77c\uc11c \ubaa8\ub4e0 \ubc18\ubc1c\uc744 \uc21c\uc218\ud55c \uc6d0\uce59 \ud558\ub098\ub098 \uac1c\uc778\uc758 \ub3c8 \uc695\uc2ec \ud558\ub098\ub85c\ub9cc \uc124\uba85\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc815\uce58\uc801 \uc8fc\uc7a5\uacfc \uc0c1\uc5c5\uc801 \uc774\ud574\uac00 \uac19\uc740 \uc0ac\uac74 \uc548\uc5d0\uc11c \ud568\uaed8 \uc791\uc6a9\ud588\ub2e4. \ubcf4\uc2a4\ud134\uc5d0 \ub3c4\ucc29\ud55c \ucc28\ub97c \uc5b4\ub5bb\uac8c \ucc98\ub9ac\ud560\uc9c0\ub97c \ub450\uace0 \ud68c\uc758\uc640 \uc555\ubc15\uc774 \uc774\uc5b4\uc84c\ub2e4. \ubc18\ub300\uc790\ub4e4\uc740 \ucc28\ub97c \ub0b4\ub9ac\uc9c0 \uc54a\uace0 \ub3cc\ub824\ubcf4\ub0b4\ub824 \ud588\uace0, \ubc30\uc758 \uc18c\uc720\uc790\uc640 \uc120\uc7a5, \ucd1d\ub3c5\uacfc \uc138\uad00\uc740 \uac01\uae30 \ub2e4\ub978 \uaddc\uce59\uacfc \uc694\uad6c \uc0ac\uc774\uc5d0 \ub193\uc600\ub2e4. \ud654\ubb3c\uc744 \uc2e3\uace0 \ub3cc\uc544\uac00\ub294 \uc77c\ub3c4 \uac04\ub2e8\ud55c \uc120\ud0dd\uc740 \uc544\ub2c8\uc5c8\ub2e4. 1884\ub144 \ud3b8\ucc2c\ub41c \u300eTea Leaves\u300f\ub294 \ub2f9\uc2dc \ud3b8\uc9c0\uc640 \ubb38\uc11c, \ub4a4\uc5d0 \uc815\ub9ac\ub41c \uc778\ubb3c \uae30\ub85d\uc744 \ud568\uaed8 \ub2f4\uc558\ub2e4. \uc5ec\uae30\uc5d0\ub294 \uc7a5\uc0ac\uc640 \uc6b4\ud56d\uc744 \uac71\uc815\ud558\ub294 \ubaa9\uc18c\ub9ac\ub3c4 \ub098\uc628\ub2e4. \ub098\uc911\uc5d0 \uc0ac\uac74\uc758 \uacb0\ub9d0\uc744 \uc544\ub294 \ub3c5\uc790\uc640 \ub2ec\ub9ac \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc740 \uc544\uc9c1 \uc815\ud574\uc9c0\uc9c0 \uc54a\uc740 \uacb0\uacfc \uc55e\uc5d0\uc11c \ud310\ub2e8\ud574\uc57c \ud588\ub2e4. \uadf8\ub0a0 \ubc24 \uc0ac\ub78c\ub4e4\uc740 \ubc30\uc5d0 \uc62c\ub77c \ucc28 \uc0c1\uc790\ub97c \uae68\uace0 \ub0b4\uc6a9\ubb3c\uc744 \ubb3c\uc5d0 \ubc84\ub838\ub2e4. \ud3b8\ucc2c \uc790\ub8cc\uc5d0 \uc778\uc6a9\ub41c \uae30\ub85d\uc740 \uc138 \ubc30\uc758 \ucc28 \uc0c1\uc790 342\uac1c\ub97c \uc11c\uc220\ud55c\ub2e4. \uc0c1\uc9d5\uc801\uc778 \ubab8\uc9d3 \uba87 \ubc88\uc73c\ub85c \ub05d\ub09c \uac83\uc774 \uc544\ub2c8\ub77c \uc2e4\uc81c \ud654\ubb3c\uc744 \ud6fc\uc190\ud558\ub294 \uc9d1\ub2e8 \ud589\ub3d9\uc774\uc5c8\ub2e4. \uc77c\ubd80 \ucc38\uac00\uc790\uac00 \uc6d0\uc8fc\ubbfc \ucc28\ub9bc\uc744 \ud749\ub0b4 \ub0b8 \ubaa8\uc2b5\uc73c\ub85c \ubb18\uc0ac\ub418\uc9c0\ub9cc, \uc774\ub97c \uc6d0\uc8fc\ubbfc\uc774 \uc8fc\ub3c4\ud55c \uacf5\uaca9\uc73c\ub85c \uc77d\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc2dd\ubbfc\uc9c0 \uc800\ud56d\uc790\ub4e4\uc758 \ubcc0\uc7a5\uacfc \ud589\ub3d9\uc5d0 \uad00\ud55c \uc11c\uc220\uc774\ub2e4. \uc624\ub298 \uc775\uc219\ud55c \uc774\ub984\uc778 \ubcf4\uc2a4\ud134 \ucc28 \uc0ac\uac74 \ub4a4\uc5d0\ub294 \ub204\uac00 \uc5b4\ub5a4 \ubaa8\uc2b5\uc73c\ub85c \ud589\ub3d9\ud588\ub294\uc9c0\ub97c \uad6c\ubd84\ud560 \uc5ed\uc0ac\uc801 \ub9e5\ub77d\uc774 \uc788\ub2e4. \uc790\ub8cc\uc5d0\ub294 \ucc28\ub97c \uac1c\uc778\uc801\uc73c\ub85c \uac00\uc838\uac00\ub824\ub294 \ud589\ub3d9\uc744 \ub9c9\uc558\uace0 \ub2e4\ub978 \ud654\ubb3c\uc744 \ud568\ubd80\ub85c \ud6fc\uc190\ud558\uc9c0 \uc54a\uc73c\ub824 \ud588\ub2e4\ub294 \uc11c\uc220\ub3c4 \uc788\ub2e4. \uc800\ud56d\uc790\ub4e4\uc740 \uc790\uc2e0\uc758 \ud589\uc704\ub97c \ub2e8\uc21c\ud55c \uc57d\ud0c8\uacfc \ub2e4\ub974\uac8c \ubcf4\uc774\uac8c \ud558\ub824 \ud588\ub2e4. \ud589\ub3d9\uc758 \ub300\uc0c1\uacfc \uadf8\uac83\uc744 \uc124\uba85\ud558\ub294 \ubc29\uc2dd\uc774 \ud568\uaed8 \uc911\uc694\ud588\ub358 \uac83\uc774\ub2e4. \uadf8\ub7ec\ub098 \uc774 \uc124\uba85\uc744 \uc190\ud574\ub97c \ubcf8 \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \ub3d9\uc758\ud55c \uacf5\uc815\ud55c \ud3c9\uac00\ub85c \ubc1b\uc544\ub4e4\uc77c \uc218\ub294 \uc5c6\ub2e4. \uc120\ubc15\uacfc \ud654\ubb3c, \ud68c\uc0ac\uc640 \uc2dd\ubbfc\uc9c0\uc758 \uc774\ud574\ub294 \uac19\uc9c0 \uc54a\uc558\ub2e4. \uc0ac\uac74\uc758 \ub2f9\uc0ac\uc790\uc640 \ud6c4\ub300\uc758 \uae30\ub150 \uc11c\uc220\uc774 \ubb34\uc5c7\uc744 \uac15\uc870\ud558\ub294\uc9c0 \ub098\ub204\uc5b4 \uc77d\uc73c\uba74 \uac19\uc740 \ubc24\uc774 \uc5ec\ub7ec \uad00\uc810\uc5d0\uc11c \ubcf4\uc778\ub2e4. \ucc28\uc758 \ud30c\uad34 \ub4a4 \uc601\uad6d\uacfc \uc2dd\ubbfc\uc9c0\uc758 \uac08\ub4f1\uc740 \ub354 \ucee4\uc84c\uace0 1775\ub144\uc5d0\ub294 \ubb34\ub825 \ucda9\ub3cc\ub85c \uc774\uc5b4\uc84c\ub2e4. 1776\ub144 \ub3c5\ub9bd\uc120\uc5b8\ub3c4 \ub098\uc654\ub2e4. \ud558\uc9c0\ub9cc \ucc28 \uc0c1\uc790\ub97c \ubc84\ub9b0 \ud55c \ud589\ub3d9\uc774 \ubaa8\ub4e0 \uc6d0\uc778\uacfc \uacfc\uc815\uc744 \ub300\uc2e0\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc55e\uc120 \uacfc\uc138\uc640 \ub300\ud45c\uad8c\uc758 \uac08\ub4f1, \uc5ec\ub7ec \uc9c0\uc5ed\uc758 \uc120\ud0dd\uc774 \uc313\uc5ec \uc788\uc5c8\ub2e4. \uc790\uc720\ub97c \uc8fc\uc7a5\ud55c \uc2dd\ubbfc\uc9c0 \uc0ac\ud68c \uc548\uc5d0\ub3c4 \uad8c\ub9ac\uc758 \ucc28\uc774\uac00 \ub0a8\uc544 \uc788\uc5c8\ub2e4. \uad50\uc7ac\ub294 \ub178\uc608\uc81c\uc640 \uc5ec\uc131, \uc6d0\uc8fc\ubbfc\uc758 \ubc30\uc81c\ub97c \ud568\uaed8 \uc124\uba85\ud55c\ub2e4. \uc81c\uad6d\uc758 \uad8c\ud55c\uc5d0 \ubc18\ub300\ud55c \uc5ed\uc0ac\uc801 \uc758\ubbf8\ub97c \uc77d\uc73c\uba74\uc11c \uadf8\ub4e4\uc774 \uc8fc\uc7a5\ud55c \uc790\uc720\uac00 \uc2e4\uc81c\ub85c \ub204\uad6c\uc5d0\uac8c \uc801\uc6a9\ub418\uc5c8\ub294\uc9c0\ub3c4 \ubb3c\uc744 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 1770\ub144\ub300 \ud56d\uad6c\uc5d0\uc11c \ucc28 \uc0c1\uc790\ub97c \ub2e4\ub8e8\ub294 \uc0c1\ud669\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc0c1\uc0c1 \uc18d \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c \ucc38\uac00\uc790\uc640 \uc120\ubc15, \uadf8\ub0a0 \ubc24\uc758 \ubc30\uce58\ub97c \uace0\uc99d\ud574 \ubcf5\uc6d0\ud558\uc9c0 \uc54a\uc558\ub2e4. \uc778\ubb3c\uc758 \ucc28\ub9bc\uc774\ub098 \uc790\uc138\ub97c \uc0ac\ub8cc\ucc98\ub7fc \ud574\uc11d\ud560 \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ubcf4\uc2a4\ud134\uc758 \ucc28\ub97c \ub530\ub77c\uac00\uba74 \uc18c\ube44\uc790\uc758 \uac00\uaca9\ud45c\uc640 \ud68c\uc0ac\uc758 \uc7a5\ubd80, \uc758\ud68c\uc758 \uad8c\ud55c\uc774 \ud55c \ubb3c\uac74\uc5d0 \ubaa8\uc778\ub2e4. \ud3c9\ubc94\ud55c \uc74c\ub8cc\ub294 \uc5b4\ub5a4 \uc870\uac74\uc5d0\uc11c \uc815\uce58\uc801 \uc120\ud0dd\uc774 \ub418\ub294\uac00. \ubc14\ub2e4\uc5d0 \ubc84\ub824\uc9c4 \ucc3b\uc78e\uc740 \uc77c\uc0c1\uc758 \uc0c1\ud488\uc774 \uc138\uacc4\uc0ac\uc758 \ud070 \uac08\ub4f1\uc744 \ub4dc\ub7ec\ub0b4\ub294 \uc21c\uac04\uc744 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "brazil-1822-independence-crown-and-unequal-freedom", "title": "\ube0c\ub77c\uc9c8 1822 \u2014 \ub3c5\ub9bd\ud588\ub294\ub370 \uc65c \ud669\uc81c\uac00 \uc0dd\uacbc\uc744\uae4c", "summary": "1822\ub144 \ub3c5\ub9bd\uacfc \uad70\uc8fc\uc81c \uc720\uc9c0, \uc9c0\uc5ed \uac08\ub4f1\uacfc \ub178\uc608\uc81c\uc758 \uc9c0\uc18d\uc744 \ud1b5\ud574 \uc790\uc720\uc758 \uc11c\ub85c \ub2e4\ub978 \ubc94\uc704\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/brazil-1822-independence-crown-and-unequal-freedom/index.html", "image": "../media/brazil-1822-independence-crown-and-unequal-freedom.png", "alt": "1822\ub144 \ube0c\ub77c\uc9c8 \ub3c5\ub9bd\uc744 \ub458\ub7ec\uc2fc \uc18c\uc2dd\uacfc \ubb38\uc11c\uc758 \uc804\ub2ec\uc744 \uc5f0\uc0c1\ud558\ub294 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ube0c\ub77c\uc9c8 1822 \u2014 \ub3c5\ub9bd\ud588\ub294\ub370 \uc65c \ud669\uc81c\uac00 \uc0dd\uacbc\uc744\uae4c \uc655\uc790\uc758 \uc794\ub958\uc640 \ud669\uc81c\uc758 \ud0c4\uc0dd, \ub3c5\ub9bd \ub4a4\uc5d0\ub3c4 \ub0a8\uc740 \ubd88\ud3c9\ub4f1 1822\ub144 \ub3c5\ub9bd\uacfc \uad70\uc8fc\uc81c \uc720\uc9c0, \uc9c0\uc5ed \uac08\ub4f1\uacfc \ub178\uc608\uc81c\uc758 \uc9c0\uc18d\uc744 \ud1b5\ud574 \uc790\uc720\uc758 \uc11c\ub85c \ub2e4\ub978 \ubc94\uc704\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ub0a8\uc544\uba54\ub9ac\uce74\uc758 \ub3c5\ub9bd\uc744 \uacf5\ud654\uad6d\uc758 \ud0c4\uc0dd\uacfc \uac19\uc740 \ub9d0\ub85c \uc0dd\uac01\ud558\uba74 \ube0c\ub77c\uc9c8\uc758 \uae38\uc774 \ub0af\uc124\ub2e4. 1822\ub144 \ud3ec\ub974\ud22c\uac08\uc5d0\uc11c \ub3c5\ub9bd\ud55c \ube0c\ub77c\uc9c8\uc740 \ud669\uc81c\ub97c \ub454 \uc81c\uad6d\uc774 \ub418\uc5c8\ub2e4. \ub3c5\ub9bd\uc744 \uc120\uc5b8\ud55c \uc778\ubb3c\ub3c4 \ud3ec\ub974\ud22c\uac08 \uc655\uc2e4\uc758 \uc655\uc790\uc600\ub2e4. \uc655\uac00\uc640 \uad6d\uac00, \uc815\uce58\uc801 \ub3c5\ub9bd\uacfc \uc0ac\ub78c\ub4e4\uc758 \uc790\uc720\uac00 \uc5b4\ub5bb\uac8c \uc11c\ub85c \ub2e4\ub978 \uc18d\ub3c4\ub85c \uc6c0\uc9c1\uc600\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. 1808\ub144 \ud3ec\ub974\ud22c\uac08 \uc655\uc2e4\uc774 \ube0c\ub77c\uc9c8\ub85c \uc62e\uaca8 \uc628 \ub4a4 \ub9ac\uc6b0\ub370\uc790\ub124\uc774\ub8e8\uc5d0\ub294 \uc911\uc559 \ud1b5\uce58\uc758 \uae30\uad00\uacfc \uad81\uc815\uc774 \uc790\ub9ac\ud588\ub2e4. \uc774\ud6c4 \ube0c\ub77c\uc9c8\uc758 \uc704\uc0c1\ub3c4 \ub2ec\ub77c\uc84c\ub2e4. \uc720\ub7fd\uc758 \uba85\ub839\uc744 \uae30\ub2e4\ub9ac\ub294 \uc2dd\ubbfc\uc9c0\ub77c\ub294 \uc870\uac74\uc5d0\uc11c \ubc97\uc5b4\ub09c \uacbd\ud5d8\uc740 \uc27d\uac8c \ub418\ub3cc\ub9ac\uae30 \uc5b4\ub824\uc6e0\ub2e4. \uc655 \uc8fc\uc559 6\uc138\uac00 \ud3ec\ub974\ud22c\uac08\ub85c \ub3cc\uc544\uac04 \ub4a4 \uc544\ub4e4 \ud398\ub4dc\ub8e8\ub294 \ube0c\ub77c\uc9c8\uc5d0 \ub0a8\uc558\ub2e4. \ub450 \uc9c0\uc5ed\uc774 \uac19\uc740 \uc655\uac00\uc5d0 \uc5f0\uacb0\ub418\uc5b4 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc815\uce58\uc801 \uc774\ud574\uad00\uacc4\uae4c\uc9c0 \uac19\uc9c0\ub294 \uc54a\uc558\ub2e4. \uc774\ubbf8 \ucee4\uc9c4 \ube0c\ub77c\uc9c8\uc758 \uc5ed\ud560\uacfc \ud3ec\ub974\ud22c\uac08\uc5d0\uc11c \uc77c\uc5b4\ub09c \ubcc0\ud654\uac00 \ucda9\ub3cc\ud558\uae30 \uc2dc\uc791\ud588\ub2e4. 1808\ub144 \uc655\uc2e4\uc758 \uc774\ub3d9\uacfc 1822\ub144 \ub3c5\ub9bd\uc740 \uc774\uc5b4\uc9c0\uc9c0\ub9cc \uac19\uc740 \uc0ac\uac74\uc740 \uc544\ub2c8\ub2e4. \uc55e\uc758 \ubcc0\ud654\uac00 \ub3c5\ub9bd\uc758 \uc870\uac74\uc744 \ub9cc\ub4e4\uc5c8\ub2e4\uace0 \ud574\uc11c \ub4a4\uc758 \uacb0\uacfc\uac00 \ucc98\uc74c\ubd80\ud130 \uc815\ud574\uc838 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. 1820\ub144\ub300\uc5d0 \uc0c8\ub85c \uc0dd\uae34 \uc815\uce58\uc801 \uc694\uad6c\uc640 \uc5ec\ub7ec \uc120\ud0dd\uc774 \uc2e4\uc81c \ubd84\ub9ac\ub97c \ub9cc\ub4e4\uc5b4 \uac14\ub2e4. \ud3ec\ub974\ud22c\uac08\uc758 \uc758\ud68c\ub294 \ube0c\ub77c\uc9c8\uc744 \ub2e4\uc2dc \uac15\ud558\uac8c \ud1b5\uc81c\ud558\uace0 \uc655\uc790\uc758 \uadc0\ud658\uc744 \uc694\uad6c\ud558\ub824 \ud588\ub2e4. \ube0c\ub77c\uc9c8\uc5d0\uc11c \uc815\uce58\uc640 \uc0c1\uc5c5\uc758 \uc911\uc2ec\uc744 \uc720\uc9c0\ud558\ub824\ub294 \uc0ac\ub78c\ub4e4\uc5d0\uac8c\ub294 \ubc1b\uc544\ub4e4\uc774\uae30 \uc5b4\ub824\uc6b4 \ubc29\ud5a5\uc774\uc5c8\ub2e4. \ub204\uac00 \uc138\uae08\uacfc \ud589\uc815, \ubb34\uc5ed\uc758 \uc870\uac74\uc744 \uacb0\uc815\ud560\uc9c0\uac00 \uac78\ub824 \uc788\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \ube0c\ub77c\uc9c8 \uc0ac\ub78c \ubaa8\ub450\uac00 \ucc98\uc74c\ubd80\ud130 \ub3d9\uc77c\ud55c \ub3c5\ub9bd \uacc4\ud68d\uc744 \uac00\uc84c\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc9c0\uc5ed\uacfc \uc0ac\ud68c\uc9d1\ub2e8, \ud3ec\ub974\ud22c\uac08\uacfc \uc5f0\uacb0\ub41c \uc815\ub3c4\uc5d0 \ub530\ub77c \uae30\ub300\uac00 \ub2ec\ub790\ub2e4. \ub3c5\ub9bd\uc740 \uc774\ubbf8 \uc644\uc131\ub41c \uad6d\ubbfc \uc804\uccb4\uac00 \ud558\ub098\uc758 \uad6c\ud638\ub9cc \uc678\uce58\uba70 \uc6c0\uc9c1\uc778 \uc0ac\uac74\uc73c\ub85c \uc124\uba85\ud558\uae30 \uc5b4\ub835\ub2e4. \ud398\ub4dc\ub8e8\ub294 \ub3cc\uc544\uc624\ub77c\ub294 \uc694\uad6c\ub97c \ub530\ub974\uc9c0 \uc54a\uace0 \ube0c\ub77c\uc9c8\uc5d0 \ub0a8\ub294 \ucabd\uc744 \ud0dd\ud588\ub2e4. \uc774 \uc120\ud0dd\uc740 \ube0c\ub77c\uc9c8\uc758 \uc790\uc728\uc131\uc744 \uc6d0\ud558\ub294 \uc138\ub825\uc5d0\uac8c \uc911\uc694\ud55c \uad6c\uc2ec\uc810\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \uc655\uac00\uc758 \uc778\ubb3c\uc744 \uc911\uc2ec\uc5d0 \ub454\ub2e4\uba74 \uae09\uaca9\ud55c \uc0ac\ud68c\uc9c8\uc11c \ubcc0\ud654 \uc5c6\uc774 \ubd84\ub9ac\ub97c \ucd94\uc9c4\ud560 \uc218 \uc788\ub2e4\ub294 \uacc4\uc0b0\ub3c4 \uc788\uc5c8\ub2e4. \uc5ec\uae30\uc11c \uc655\uc790\uac00 \ubaa8\ub4e0 \uac83\uc744 \ud63c\uc790 \uacb0\uc815\ud55c \uc601\uc6c5\ucc98\ub7fc \ubcf4\uc774\uba74 \uc8fc\ubcc0\uc758 \ud65c\ub3d9\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \uace0\ubb38\uacfc \uc815\uce58\uac00, \uc9c0\uc5ed \uc9c0\ub3c4\uc790\uc640 \uc0c1\uc778, \ubb38\uc11c\uc640 \uc18c\uc2dd\uc758 \uc804\ub2ec\uc774 \uc120\ud0dd\uc744 \uac00\ub2a5\ud558\uac8c \ud588\ub2e4. \uac1c\uc778\uc758 \uacb0\ub2e8\uacfc \uadf8 \uacb0\ub2e8\uc744 \ub5a0\ubc1b\uce5c \uc138\ub825\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ub3c5\ub9bd\uc744 \uc9c0\uc9c0\ud558\ub294 \uc0ac\ub78c\ub4e4 \uac00\uc6b4\ub370\uc11c\ub3c4 \uc5b4\ub5a4 \uad6d\uac00\ub97c \ub9cc\ub4e4 \uac83\uc778\uc9c0\uc5d0 \ub300\ud55c \ub2f5\uc740 \ud558\ub098\uac00 \uc544\ub2c8\uc5c8\ub2e4. \uc911\uc559\uc758 \uad8c\ud55c\uacfc \uc9c0\ubc29\uc758 \uc790\uc728\uc131, \uad70\uc8fc\uc640 \ub300\ud45c\uae30\uad00\uc758 \uad00\uacc4\ub294 \uacc4\uc18d \ub17c\uc7c1\uac70\ub9ac\uac00 \ub418\uc5c8\ub2e4. \uacf5\ud1b5\uc758 \uc0c1\ub300\uc5d0\uc11c \ubc97\uc5b4\ub0ac\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub0b4\ubd80\uc758 \ucc28\uc774\ub97c \uc5c6\uc560 \uc8fc\uc9c0\ub294 \ubabb\ud588\ub2e4. 1822\ub144 9\uc6d4 7\uc77c \uc0c1\ud30c\uc6b8\ub8e8 \ubd80\uadfc \uc774\ud53c\ub791\uac00\uc5d0\uc11c \ub3c5\ub9bd\uc744 \uc120\uc5b8\ud55c \uc77c\uc774 \uae30\ub150\uc77c\uc758 \uc911\uc2ec\uc774 \ub418\uc5c8\ub2e4. \ub9d0 \ud0c4 \uc655\uc790\uc758 \ubaa8\uc2b5\uacfc \uadf9\uc801\uc778 \uc678\uce68\uc740 \ub4a4\uc5d0 \uadf8\ub9bc\uacfc \uae30\ub150\ud589\uc0ac\ub85c \uac15\ud558\uac8c \ub0a8\uc558\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \uc7a5\uba74 \ud558\ub098\uac00 \ub098\ub77c\uc758 \ubaa8\ub4e0 \uc815\uce58\uc801 \uacb0\ud569\uc744 \uc989\uc2dc \ubc14\uafbc \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \ub9d0\uc774 \uc815\ud655\ud788 \uc5b4\ub5bb\uac8c \uc624\uac14\ub294\uc9c0\uc5d0 \uad00\ud55c \ud6c4\ub300\uc758 \uc7ac\ud604\uacfc \ub2f9\ub300\uc758 \uc815\uce58 \uacfc\uc815\uc744 \uad6c\ubd84\ud560 \ud544\uc694\uac00 \uc788\ub2e4. \ub3c5\ub9bd\uc740 \uc120\uc5b8\ubb38\uacfc \uc2b9\uc778, \uac01 \uc9c0\uc5ed\uc758 \uc9c0\uc9c0\uc640 \uc800\ud56d\uc774 \uc774\uc5b4\uc838\uc57c \uc2e4\ud604\ub418\ub294 \uc77c\uc774\uc5c8\ub2e4. \uc0c1\uc9d5\uc801\uc778 \ub0a0\uc9dc\ub294 \uadf8 \ubcf5\uc7a1\ud55c \uc2dc\uac04\uc744 \ub300\ud45c\ud558\ub294 \ud45c\uc9c0\uac00 \ub41c\ub2e4. \ud398\ub4dc\ub8e8\ub294 \ube0c\ub77c\uc9c8 \ud669\uc81c \ud398\ub4dc\ub8e8 1\uc138\uac00 \ub418\uc5c8\ub2e4. \ub3c5\ub9bd\ud558\uba74\uc11c\ub3c4 \uad70\uc8fc\uc81c\ub97c \uc720\uc9c0\ud55c \uc77c\uc740 \ub2f9\uc2dc \uc9c0\ubc30 \uc138\ub825\uc774 \uc5f0\uc18d\uc131\uacfc \uc9c8\uc11c\ub97c \uc911\uc694\ud558\uac8c \uc5ec\uacbc\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ud3ec\ub974\ud22c\uac08 \uc655\uac00\uc640 \uac08\ub77c\uc11c\ub294 \uac83\uacfc \uc655\uc815 \uc790\uccb4\ub97c \uc5c6\uc560\ub294 \uac83\uc740 \ub2e4\ub978 \uc120\ud0dd\uc774\uc5c8\ub2e4. \ub4a4\uc774\uc5b4 \ud5cc\uc815 \uc9c8\uc11c\uc640 \ud669\uc81c\uc758 \uad8c\ud55c\uc744 \ub458\ub7ec\uc2fc \uac08\ub4f1\ub3c4 \ub098\ud0c0\ub0ac\ub2e4. \ub3c5\ub9bd\uc774 \uc774\ub8e8\uc5b4\uc84c\ub2e4\uace0 \ub204\uac00 \ucd5c\uc885 \uad8c\ub825\uc744 \uac16\ub294\uac00\ub77c\ub294 \uc9c8\ubb38\uc774 \ub05d\ub09c \uac83\uc740 \uc544\ub2c8\ub2e4. \uad6d\uacbd \ubc16\uc758 \uc9c0\ubc30\uc5d0\uc11c \ubc97\uc5b4\ub098\ub294 \uc77c\uacfc \uad6d\uacbd \uc548\uc5d0\uc11c \uad8c\ub825\uc744 \ub098\ub204\ub294 \uc77c\uc740 \ubcc4\ub3c4\uc758 \ud611\uc0c1\uacfc \ucda9\ub3cc\uc744 \ud544\uc694\ub85c \ud588\ub2e4. \ud6c4\ub300\uc758 \ub9d0 \ud0c4 \uc601\uc6c5 \uadf8\ub9bc\uc740 \uc120\uc5b8\uc744 \uae30\uc5b5\ud558\uae30 \uc27d\uac8c \ud574 \uc900\ub2e4. \uadf8\ub7ec\ub098 \uc778\uc1c4\ubb3c\uacfc \uc11c\uc2e0\uc744 \ub9cc\ub4e4\uace0 \uc18c\uc2dd\uc744 \uc804\ud55c \uc0ac\ub78c\ub4e4, \ud56d\uad6c\uc640 \uc9c0\ubc29\uc5d0\uc11c \uc6c0\uc9c1\uc778 \uc774\ub4e4\uae4c\uc9c0 \ud55c \ud654\uba74\uc5d0 \ub2f4\uc9c0\ub294 \ubabb\ud55c\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \ub300\uad00\uc2dd\uc758 \uc601\uad11\ubcf4\ub2e4 \uadf8 \ub4a4\uc5d0 \ub0a8\uc740 \uc815\uce58\uc801 \uacfc\uc81c\ub97c \ud568\uaed8 \uc77d\uc5c8\ub2e4. \ube0c\ub77c\uc9c8\uc758 \ub3c5\ub9bd\uc744 \ud53c \ud55c \ubc29\uc6b8 \uc5c6\uc774 \uc774\ub8e8\uc5b4\uc9c4 \uc77c\ub85c \uc124\uba85\ud558\ub294 \uac83\ub3c4 \ub9de\uc9c0 \uc54a\ub294\ub2e4. \ud3ec\ub974\ud22c\uac08\uc744 \uc9c0\uc9c0\ud558\ub294 \uc138\ub825\uacfc \ub3c5\ub9bd \uc138\ub825 \uc0ac\uc774\uc5d0 \uc5ec\ub7ec \uc9c0\uc5ed\uc5d0\uc11c \ubb34\ub825 \ucda9\ub3cc\uc774 \uc788\uc5c8\ub2e4. \ub9ac\uc6b0\uc758 \uacb0\uc815\uacfc \uba40\ub9ac \ub5a8\uc5b4\uc9c4 \uc9c0\uc5ed\uc758 \ud604\uc2e4\uc740 \uac19\uc740 \uc18d\ub3c4\ub85c \uc6c0\uc9c1\uc774\uc9c0 \uc54a\uc558\ub2e4. \uc0c8 \uad6d\uac00\uc758 \ud1b5\ud569 \uc5ed\uc2dc \uc800\uc808\ub85c \uc8fc\uc5b4\uc9c4 \uacb0\uacfc\uac00 \uc544\ub2c8\uc5c8\ub2e4. \uc911\uc559\uacfc \uc9c0\ubc29, \uc9c0\uc5ed\ubcc4 \uacbd\uc81c\uc640 \uad8c\ub825\uc758 \uad00\uacc4\ub97c \ub2e4\uc2dc \uc9dc\uc57c \ud588\ub2e4. \uc8fc\ubcc0\uc758 \uc804\uc7c1\uacfc \uac08\ub4f1\uc744 \uc9c0\uc6b0\uba74 \ube0c\ub77c\uc9c8\uc758 \ud070 \uc601\ud1a0\uac00 \ub2e8\uc9c0 \uc655\uc790\uc758 \ub9d0 \ud55c\ub9c8\ub514\ub85c \uc720\uc9c0\ub418\uc5c8\ub2e4\ub294 \uc624\ud574\uac00 \uc0dd\uae34\ub2e4. \ube0c\ub77c\uc9c8\uc774 \ub3c5\ub9bd\ud55c \ub4a4\uc5d0\ub3c4 \ub178\uc608\uc81c\ub294 \uacc4\uc18d\ub418\uc5c8\ub2e4. \uad6d\uac00\uac00 \ud3ec\ub974\ud22c\uac08\uc758 \ud1b5\uc81c\uc5d0\uc11c \ubc97\uc5b4\ub0ac\ub2e4\ub294 \ub9d0\uc774 \uadf8 \uc548\uc5d0 \uc0ac\ub294 \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \uc790\uc720\ub97c \ub73b\ud558\uc9c0\ub294 \uc54a\uc558\ub358 \uac83\uc774\ub2e4. \ub178\uc608\uc81c\uac00 \ud3d0\uc9c0\ub41c 1888\ub144\uae4c\uc9c0\ub294 \ud6e8\uc52c \ub354 \uae34 \ud22c\uc7c1\uacfc \ubcc0\ud654\uac00 \ud544\uc694\ud588\ub2e4. \uacfc\uac70 \uac1c\uc124\uc11c\uac00 \uad70\uc8fc\uc640 \uc720\ub7fd \uc774\ubbfc\uc790\uc758 \uc5ed\ud560\ub9cc \uac15\uc870\ud588\ub2e4\uba74 \uc624\ub298\uc758 \ud574\uc124\uc740 \uadf8 \uc2dc\uc57c\ub97c \ub113\ud600\uc57c \ud55c\ub2e4. \uc6d0\uc8fc\ubbfc\uacfc \uc544\ud504\ub9ac\uce74\uacc4 \uc8fc\ubbfc, \ub178\uc608 \uc0c1\ud0dc\uc5d0 \uc788\ub358 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \ub3c5\ub9bd\uc774 \ubb34\uc5c7\uc774\uc5c8\ub294\uc9c0 \ubb3c\uc5b4\uc57c \ud558\uae30 \ub54c\ubb38\uc774\ub2e4. 1822\ub144\uc740 \uad6d\uac00\uc758 \ud0c4\uc0dd\uc778 \ub3d9\uc2dc\uc5d0 \uc790\uc720\uc758 \ubc94\uc704\uac00 \uc5bc\ub9c8\ub098 \ub2ec\ub790\ub294\uc9c0 \ub4dc\ub7ec\ub0b4\ub294 \ud574\uc774\uae30\ub3c4 \ud558\ub2e4."}, {"id": "british-calendar-eleven-days", "title": "9\uc6d4 2\uc77c \ub2e4\uc74c \ub0a0\uc774 14\uc77c\uc774\uc5c8\ub358 \ub2ec\ub825", "summary": "1752\ub144 9\uc6d4 \ub2ec\ub825\uc758 \ub0a0\uc9dc\uac00 \uac74\ub108\ub6f0\ub294 \uc774\uc720\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/british-calendar-eleven-days/index.html", "image": "../media/british-calendar-eleven-days.jpg", "alt": "1752\ub144 9\uc6d4\uc758 \uc601\uad6d \ub2ec\ub825 \uaddc\uce59\uc744 \uc7ac\uad6c\uc131\ud55c \uc124\uba85\ub3c4. \ud654\uc694\uc77c 1\uc77c, \uc218\uc694\uc77c 2\uc77c \ub2e4\uc74c\uc774 \ubaa9\uc694\uc77c 14\uc77c\uc774\uba70 3\uc77c\ubd80\ud130 13\uc77c\uc740 \uc0dd\ub7b5\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.", "text": "9\uc6d4 2\uc77c \ub2e4\uc74c \ub0a0\uc774 14\uc77c\uc774\uc5c8\ub358 \ub2ec\ub825 \uc601\uad6d \ub2ec\ub825\uc5d0 \ub0a8\uc740 \uc5f4\ud558\ub8e8\uc758 \ube48\uc790\ub9ac 1752\ub144 9\uc6d4 \ub2ec\ub825\uc758 \ub0a0\uc9dc\uac00 \uac74\ub108\ub6f0\ub294 \uc774\uc720\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc 9\uc6d4 \ub2ec\ub825\uc744 \ud3bc\ucce4\ub294\ub370 2\uc77c \uc606\uc5d0 14\uc77c\uc774 \uc801\ud600 \uc788\ub2e4. 3\uc77c\ubd80\ud130 13\uc77c\uae4c\uc9c0\uac00 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc778\uc1c4\ub97c \uc798\ubabb\ud55c \uac83 \uac19\uc9c0\ub9cc, \ub2ec\ub825\uc744 \ubc14\uafb8\ub358 \uc2dc\uae30\uc758 \ub0a0\uc9dc\ub97c \ubcf4\uc5ec \uc8fc\ub294 \ubc29\ubc95\uc77c \uc218 \uc788\ub2e4. 1752\ub144 \uc601\uad6d \uc81c\uad6d\uc758 \uadf8\ub808\uace0\ub9ac\ub825 \uc804\ud658\uc744 \ubc18\uc601\ud55c \ub2ec\ub825\uc5d0\uc11c\ub294 9\uc6d4 2\uc77c \ub4a4\uc5d0 14\uc77c\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ub0a0\uc9dc \uc774\ub984 \uc5f4\ud55c \uac1c\ub97c \uac74\ub108\ub6f4 \uac83\uc774\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \uadf8\ub9cc\ud07c \uc7a0\ub4e4\uc5b4 \uc788\uc5c8\ub2e4\ub294 \uc774\uc57c\uae30\ub294 \ubb3c\ub860 \uc544\ub2c8\ub2e4. \ucef4\ud4e8\ud130 \ub2ec\ub825 \ud504\ub85c\uadf8\ub7a8 cal\uc758 \uacf5\uc2dd \uc124\uba85\uc11c\ub294 \uc728\ub9ac\uc6b0\uc2a4\ub825\uacfc \uadf8\ub808\uace0\ub9ac\ub825\uc774 \uc724\ub144\uc744 \ub450\ub294 \ube48\ub3c4\uc5d0\uc11c \uc791\uc740 \ucc28\uc774\ub97c \uac00\uc9c4\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\ub808\uace0\ub9ac\ub825\uc740 \ucd98\ubd84 \uac19\uc740 \ud0dc\uc591\uc758 \uc8fc\uae30\uc640 \ub2ec\ub825\uc744 \ub354 \uc798 \ub9de\ucd94\ub824\ub294 \uc870\uc815\uc774\ub2e4. \uc774\ub984\uc740 \uc5b4\ub824\uc6cc\ub3c4 \ucd9c\ubc1c\uc810\uc740 \uce5c\uc219\ud558\ub2e4. \uc6b0\ub9ac\uac00 \uc138\ub294 \ub2ec\ub825\uc758 \ub0a0\uc9dc\uc640 \uacc4\uc808\uc758 \ud750\ub984\uc774 \uacc4\uc18d \uc5b4\uae0b\ub098\uc9c0 \uc54a\ub3c4\ub85d \ub9de\ucd94\ub294 \ubb38\uc81c\ub2e4. \uc624\ub798 \uc4f0\ub358 \uaddc\uce59\uc744 \ubc14\uafb8\uba74\uc11c \uc313\uc778 \ucc28\uc774\ub97c \ud55c \ubc88\uc5d0 \uc870\uc815\ud560 \ud544\uc694\uac00 \uc0dd\uacbc\ub2e4. \uc774 \uc124\uba85\uc11c\uc758 \uae30\ubcf8 \ub2ec\ub825\uc740 1752\ub144\uc758 \uc804\ud658\uc744 \ubc18\uc601\ud574 3\uc77c\ubd80\ud130 13\uc77c\uae4c\uc9c0\ub97c \ud45c\uc2dc\ud558\uc9c0 \uc54a\ub294\ub2e4. \uadf8\ub798\uc11c \uadf8\ud574 9\uc6d4\uc744 \ucc3e\uc73c\uba74 \ubcf4\ud1b5 \ub2ec\uacfc \ub2e4\ub978 \ubc30\uc5f4\uc744 \ub9cc\ub098\uac8c \ub41c\ub2e4. \ubaa8\ub4e0 \ub098\ub77c\uac00 \uac19\uc740 \ub0a0 \ub2ec\ub825\uc744 \ubc14\uafbc \uac83\uc740 \uc544\ub2c8\ub2e4. \ub530\ub77c\uc11c 1752\ub144 9\uc6d4\uc740 \uc138\uacc4 \uc5b4\ub514\uc11c\ub098 \ub611\uac19\uc558\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uc548 \ub41c\ub2e4. \uc5b4\ub290 \uc9c0\uc5ed\uc758 \ub2ec\ub825 \uaddc\uce59\uc73c\ub85c \ub0a0\uc9dc\ub97c \ubcf4\uace0 \uc788\ub294\uc9c0\uac00 \ud568\uaed8 \ud544\uc694\ud558\ub2e4. 9\uc6d4 2\uc77c \ub2e4\uc74c\uc744 14\uc77c\ub85c \ubd80\ub978\ub2e4\uace0 \uc0ac\ub78c\ub4e4\uc774 \uc2e4\uc81c\ub85c 11\uc77c \ub3d9\uc548 \uc544\ubb34 \uc77c\ub3c4 \ud558\uc9c0 \uc54a\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud558\ub8e8\ub294 \uacc4\uc18d \uc774\uc5b4\uc84c\uc9c0\ub9cc \ub2ec\ub825\uc5d0\uc11c \ub0a0\uc9dc\ub97c \ubd99\uc774\ub294 \uaddc\uce59\uc744 \ubc14\uafbc \uac83\uc774\ub2e4. \uc774 \uad6c\ubd84\uc744 \uc54c\uba74 \ub0a0\uc9dc\uac00 \uc0ac\ub77c\uc84c\ub2e4\ub294 \ud45c\ud604\uc744 \uc870\uae08 \uc815\ud655\ud558\uac8c \uc77d\uc744 \uc218 \uc788\ub2e4. \ube44\uc5b4 \ubcf4\uc774\ub294 \uce78\uc740 \uc2dc\uac04\uc774 \uba48\ucd98 \ud754\uc801\uc774 \uc544\ub2c8\ub77c \ud45c\uae30\uc758 \uc804\ud658\uc774\ub2e4. 3\uc77c\ubd80\ud130 13\uc77c\uae4c\uc9c0\ub97c \uc138\uba74 \uc5f4\ud55c \uac1c\uc758 \ub0a0\uc9dc\uac00 \ub41c\ub2e4. \ucef4\ud4e8\ud130 \ub2ec\ub825\uc5d0 \uadf8 \uc22b\uc790\ub4e4\uc774 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uac83\uc740 \uace0\uc7a5\uc744 \ub73b\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud2b9\uc815\ud55c \uc9c0\uc5ed\uc758 \uc804\ud658 \uaddc\uce59\uc744 \ubc18\uc601\ud558\ub3c4\ub85d \ub9cc\ub4e0 \uacb0\uacfc\uc77c \uc218 \uc788\ub2e4. \ud654\uba74\uc5d0\uc11c \uc774\uc0c1\ud55c \ubc30\uc5f4\uc744 \ub9cc\ub0ac\uc744 \ub54c \uba3c\uc800 \uc5b4\ub5a4 \ub2ec\ub825\uacfc \uc5ed\uc0ac\uc801 \uae30\uc900\uc744 \uc0ac\uc6a9\ud558\ub294\uc9c0 \ubb3c\uc5b4\ubcfc \uc774\uc720\uac00 \uc0dd\uae34\ub2e4. \uc9c0\uad6c\uc758 \uacc4\uc808 \uc8fc\uae30\uc640 \ub2ec\ub825\uc758 \ud55c \ud574\ub97c \ub9de\ucd94\uae30 \uc704\ud574 \uc724\ub144\uc744 \ub450\uc9c0\ub9cc, \uc5b4\ub5a4 \uaddc\uce59\uc73c\ub85c \ub354\ud560\uc9c0\ub294 \ub2ec\ub825 \uccb4\uacc4\ub9c8\ub2e4 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc728\ub9ac\uc6b0\uc2a4\ub825\uacfc \uadf8\ub808\uace0\ub9ac\ub825\uc758 \ucc28\uc774\ub294 \uadf8\ub7f0 \uc57d\uc18d\uc758 \ucc28\uc774\ub2e4. \ub9e4\ub144 \ud06c\uac8c \uc5b4\uae0b\ub098\ub294 \uac83\ucc98\ub7fc \ubcf4\uc774\uc9c0 \uc54a\uc544\ub3c4 \uae34 \uae30\uac04\uc5d0\ub294 \uc870\uc815\ud560 \ucc28\uc774\uac00 \uc0dd\uae38 \uc218 \uc788\ub2e4. \uc791\uc740 \uc218\uc758 \ucc28\uc774\uac00 \uc2dc\uac04\uc774 \uc313\uc774\uba74\uc11c \ub2e4\ub978 \ubaa8\uc2b5\uc73c\ub85c \ub4dc\ub7ec\ub09c\ub2e4. \ub2ec\ub825\uc744 \ubc14\uafc0 \ub54c\uc5d0\ub294 \uc55e\uc73c\ub85c\uc758 \uaddc\uce59\uc744 \uc815\ud558\ub294 \uac83\uacfc \uc774\ubbf8 \ub204\uc801\ub41c \ucc28\uc774\ub97c \ucc98\ub9ac\ud558\ub294 \uc77c\uc744 \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \uc624\ub298\ubd80\ud130 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uacc4\uc0b0\ud558\uaca0\ub2e4\uace0 \ub9d0\ud558\ub294 \uac83\ub9cc\uc73c\ub85c \uacfc\uac70\uc758 \ucc28\uc774\uac00 \uc800\uc808\ub85c \uc0ac\ub77c\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. 1752\ub144\uc758 \ube48 \ub0a0\uc9dc\ub4e4\uc740 \uadf8 \ub450 \ubc88\uc9f8 \ubb38\uc81c\ub97c \ub208\uc5d0 \ubcf4\uc774\uac8c \ubcf4\uc5ec \uc8fc\ub294 \uc0ac\ub840\ub2e4. \uc77c\uc815\ud45c \uc548\uc5d0 \ucc9c\ubb38\ud559\uacfc \uc81c\ub3c4\uc758 \uc120\ud0dd\uc774 \ud568\uaed8 \uc788\ub2e4. \uc9c0\uc5ed\ub9c8\ub2e4 \ub2ec\ub825\uc744 \ubc14\uafbc \ub54c\uac00 \ub2e4\ub974\uba74 \uc11c\ub85c \ub2e4\ub978 \uacf3\uc758 \uae30\ub85d\uc774 \uac19\uc740 \uae30\uc900\uc73c\ub85c \ub0a0\uc9dc\ub97c \uc801\uc5c8\ub2e4\uace0 \uac00\uc815\ud560 \uc218 \uc5c6\ub2e4. \uc624\ub798\ub41c \ud3b8\uc9c0\ub098 \uc0ac\uac74 \uae30\ub85d\uc744 \ube44\uad50\ud560 \ub54c \ub0a0\uc9dc\uc758 \uc22b\uc790\ub9cc \uc62e\uaca8 \uc4f0\uba74 \ud63c\ub3d9\uc774 \uc0dd\uae38 \uc218 \uc788\ub2e4. \uc5b4\ub290 \uc9c0\uc5ed\uc5d0\uc11c \uc5b4\ub290 \ub2ec\ub825\uc744 \uc37c\ub294\uc9c0\uac00 \ub0b4\uc6a9\uc758 \ubb38\ub9e5\ucc98\ub7fc \uc911\uc694\ud574\uc9c0\ub294 \uac83\uc774\ub2e4. \uc774 \uae00\uc5d0\uc11c \ubaa8\ub4e0 \ub098\ub77c\uc758 \uc804\ud658\ud45c\ub97c \uc678\uc6b0\ub824\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc601\uad6d\uc758 1752\ub144 \uc0ac\ub840\ub97c \ub2e4\ub978 \uacf3\uc5d0 \uadf8\ub300\ub85c \uc801\uc6a9\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uccab\uac78\uc74c\uc774\ub2e4. \uac19\uc740 9\uc6d4\uc774\ub77c\ub294 \ub9d0\ub3c4 \uae30\ub85d\uc758 \uc81c\ub3c4 \uc548\uc5d0\uc11c \uc77d\uc5b4\uc57c \ud560 \ub54c\uac00 \uc788\ub2e4. \uc22b\uc790\ub97c \ubc88\uc5ed\ud558\ub294 \uc77c\uc5d0\ub294 \uc5b8\uc5b4\ubfd0 \uc544\ub2c8\ub77c \uadf8 \uc22b\uc790\ub97c \ubd99\uc774\ub358 \uaddc\uce59\uc758 \uc774\ud574\ub3c4 \ud544\uc694\ud558\ub2e4. \ud654\uba74\uc5d0 \ub2ec\uc744 \uadf8\ub9ac\ub294 \ud504\ub85c\uadf8\ub7a8\ub3c4 \uc5b4\ub5a4 \ub2ec\ub825 \uaddc\uce59\uc744 \uc0ac\uc6a9\ud560\uc9c0 \uc815\ud574\uc57c \ud55c\ub2e4. \uacfc\uac70\uc758 \ub2ec\uae4c\uc9c0 \ubcf4\uc5ec \uc904 \ub54c\uc5d0\ub294 \uc804\ud658\uc758 \ucc98\ub9ac \ubc29\uc2dd\uc774 \ud2b9\ud788 \ubb38\uc81c\uac00 \ub41c\ub2e4. \uacf5\uc2dd \uc124\uba85\uc11c\uac00 \uae30\ubcf8\uac12\uc758 \uc758\ubbf8\ub97c \uc54c\ub824 \uc8fc\ub294 \uc774\uc720\ub2e4. \ub0a0\uc9dc\ub97c \uc608\uc058\uac8c \ubc30\uc5f4\ud55c \ud45c\ucc98\ub7fc \ubcf4\uc774\ub294 \uacb0\uacfc \ub4a4\uc5d0 \uc5ed\uc0ac\uc801 \uac00\uc815\uc744 \uc120\ud0dd\ud55c \uc124\uacc4\uac00 \uc788\ub2e4. \ub530\ub77c\uc11c \ub2e4\ub978 \ub3c4\uad6c\uac00 \ub2e4\ub978 \ubc30\uc5f4\uc744 \ubcf4\uc5ec \uc900\ub2e4\uace0 \uace7\ubc14\ub85c \ud558\ub098\uac00 \uac70\uc9d3\uc774\ub77c\uace0 \ud310\ub2e8\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc124\uc815\uacfc \uae30\uc900\uc774 \uac19\uc740\uc9c0 \uba3c\uc800 \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uc774 \uc774\uc57c\uae30\ub294 \uba85\uc808\uc774\ub098 \uc57d\uc18d \ub0a0\uc9dc\ub97c \ubcf5\uc7a1\ud558\uac8c \ub9cc\ub4e4\uc790\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \ub108\ubb34 \uc775\uc219\ud574\uc11c \uc790\uc5f0 \uadf8\ub300\ub85c\uc758 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c0\ub294 \ub2ec\ub825\ub3c4 \uc0ac\ub78c\ub4e4\uc774 \uc2dc\uac04\uc5d0 \uc774\ub984\uc744 \ubd99\uc774\uace0 \ub9de\ucd94\uc5b4 \uc628 \uccb4\uacc4\ub77c\ub294 \uc810\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ud568\uaed8 \uc2e4\uc740 \ud45c\ub294 \uc804\ud658 \ub2f9\uc2dc\uc758 \ub0a0\uc9dc \ubc30\uc5f4\uc744 \uc774\ud574\ud558\ub3c4\ub85d \ub2e4\uc2dc \ub9cc\ub4e0 \uc124\uba85\ub3c4\ub2e4. \uc2e4\uc81c \uc61b \ub2ec\ub825\uc744 \ucd2c\uc601\ud55c \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. 2\uc77c\uacfc 14\uc77c \uc0ac\uc774\uc5d0 \ube48 \uc774\ub984\ub4e4\uc774 \uc788\ub2e4\ub294 \uc810\uc744 \ub208\uc73c\ub85c \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \ud758\ub7ec\uac04 \uc2dc\uac04 \uc790\uccb4\ub97c \uc5c6\uc568 \uc218\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c \ubc14\ub010 \uac83\uc740 \uadf8\ub2e4\uc74c \ub0a0\uc5d0 \ubd99\uc774\ub294 \ub0a0\uc9dc\uc600\ub2e4. \ub298 \ub2f9\uc5f0\ud558\uac8c \uc77d\ub294 \ub2ec\ub825\ub3c4 \uc0ac\ub78c\ub4e4\uc774 \uc815\ud55c \uaddc\uce59\uc774\ub77c\ub294 \uc0ac\uc2e4\uc744, \uc774 \uc774\uc0c1\ud55c 9\uc6d4\uc740 \uc9e7\uace0 \uc120\uba85\ud558\uac8c \uc54c\ub824 \uc900\ub2e4."}, {"id": "brooklyn-bridge-caissons-and-shared-work", "title": "\ube0c\ub8e8\ud074\ub9b0 \ub2e4\ub9ac \u2014 \ubb3c \uc704\uc758 \uae38\uc744 \ub9cc\ub4e4\uae30 \uc704\ud574 \ubb3c \uc544\ub798\ub85c \ub0b4\ub824\uac00\ub2e4", "summary": "1883\ub144 \uac1c\ud1b5 \uae30\ub85d\uacfc \ucf00\uc774\uc2a8\uc758 \uc704\ud5d8, \ub85c\ube14\ub9c1 \uac00\uc871\uc758 \ud611\uc5c5\uc73c\ub85c \ub2e4\ub9ac\uc758 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc5ed\uc0ac\ub97c \ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/brooklyn-bridge-caissons-and-shared-work/index.html", "image": "../media/brooklyn-bridge-caissons-and-shared-work.png", "alt": "\ube0c\ub8e8\ud074\ub9b0 \ub2e4\ub9ac\uc758 \ud0d1\uacfc \ucf00\uc774\ube14, \uac15\uc744 \uac74\ub108\ub294 \uad6c\uc870\ub97c \ubcf4\uc5ec \uc8fc\ub294 1883\ub144 \uc5ed\uc0ac \ub3c4\ud310", "text": "\ube0c\ub8e8\ud074\ub9b0 \ub2e4\ub9ac \u2014 \ubb3c \uc704\uc758 \uae38\uc744 \ub9cc\ub4e4\uae30 \uc704\ud574 \ubb3c \uc544\ub798\ub85c \ub0b4\ub824\uac00\ub2e4 \ub450 \ub3c4\uc2dc\uc758 \uc5f0\uacb0\uacfc \uc218\uc911 \uae30\ucd08, \uc5d0\ubc00\ub9ac\uc640 \uc6cc\uc2f1\ud134\uc758 \uc5ed\ud560 1883\ub144 \uac1c\ud1b5 \uae30\ub85d\uacfc \ucf00\uc774\uc2a8\uc758 \uc704\ud5d8, \ub85c\ube14\ub9c1 \uac00\uc871\uc758 \ud611\uc5c5\uc73c\ub85c \ub2e4\ub9ac\uc758 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc5ed\uc0ac\ub97c \ubd05\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ube0c\ub8e8\ud074\ub9b0 \ub2e4\ub9ac\uc758 \ub192\uc740 \ud0d1\uacfc \ucf00\uc774\ube14\uc740 \ub274\uc695\uc758 \uc775\uc219\ud55c \ud48d\uacbd\uc774\ub2e4. \uadf8\ub7ec\ub098 \ubb3c \uc704\uc758 \uae38\uc744 \ub9cc\ub4e4\uae30 \uc704\ud574\uc11c\ub294 \uba3c\uc800 \ubb3c \uc544\ub798\uc5d0\uc11c \uae30\ucd08\ub97c \uc900\ube44\ud574\uc57c \ud588\ub2e4. 1883\ub144 \uac1c\ud1b5\uc2dd \uae30\ub85d\uc744 \uc77d\uc73c\uba74 \uc544\ub984\ub2e4\uc6b4 \uad6c\uc870\ub97c \uce6d\ucc2c\ud558\ub294 \uc5f0\uc124 \uc0ac\uc774\ub85c \ubcd1\ub4e0 \uae30\uc220\uc790\uc640 \uc228\uc740 \ud611\uc5c5\uc758 \ud754\uc801\uc774 \ub098\ud0c0\ub09c\ub2e4. \ub2e4\ub9ac\uac00 \uc5f4\ub9b4 \ub2f9\uc2dc \ub274\uc695\uacfc \ube0c\ub8e8\ud074\ub9b0\uc740 \uc9c0\uae08\ucc98\ub7fc \uac19\uc740 \ub3c4\uc2dc \uc548\uc758 \ub450 \uad6c\uc5ed\uc73c\ub85c\ub9cc \uc774\ud574\ud560 \uc218 \uc788\ub294 \uad00\uacc4\uac00 \uc544\ub2c8\uc5c8\ub2e4. \ub450 \ub3c4\uc2dc\ub97c \uc787\ub294 \uc77c\uc740 \uc774\ub3d9 \uc2dc\uac04\uc744 \ubc14\uafb8\ub294 \ub3d9\uc2dc\uc5d0 \uc0dd\ud65c\uacfc \uacbd\uc81c\uc758 \uc5f0\uacb0\uc744 \ubc14\uafb8\ub294 \uc0ac\uc5c5\uc774\uc5c8\ub2e4. \uac74\ucd95\uc758 \uc758\ubbf8\ub294 \uac15\uc744 \uac74\ub10c\ub2e4\ub294 \ubb3c\ub9ac\uc801 \uae30\ub2a5\ubcf4\ub2e4 \ub113\uc5c8\ub2e4. \ubc30\ub97c \ud0c0\uace0 \uc624\uac00\ub294 \uae38\uacfc \ud56d\uc0c1 \uc774\uc5b4\uc9c4 \ub2e4\ub9ac\ub294 \ub2e4\ub978 \uacbd\ud5d8\uc744 \ub9cc\ub4e0\ub2e4. \ubb3c\uae38 \uc704\uc5d0 \uc0c8\ub85c\uc6b4 \uae38\uc774 \ub193\uc774\uba74 \uc0ac\ub78c\ub4e4\uc774 \uc77c\ud558\uace0 \uac70\ub798\ud558\uace0 \ubc29\ubb38\ud558\ub294 \ubc29\uc2dd\ub3c4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uac1c\ud1b5\uc2dd\uc758 \uae30\ub300\uc5d0\ub294 \uae30\uc220\uc801 \uc131\ucde8\ubfd0 \uc544\ub2c8\ub77c \uc55e\uc73c\ub85c \ub354 \uac00\uae4c\uc6cc\uc9c8 \ub450 \ub3c4\uc2dc\uc758 \ubbf8\ub798\uac00 \ub2f4\uacbc\ub2e4. \ud604\uc218\uad50\uc758 \uae38\uc740 \ucf00\uc774\ube14\uacfc \ud0d1, \uace0\uc815\ud558\ub294 \uad6c\uc870\uc758 \uad00\uacc4 \uc18d\uc5d0\uc11c \uc9c0\ud0f1\ub41c\ub2e4. \ub208\uc5d0 \ub744\ub294 \ubd80\ubd84 \ud558\ub098\ub9cc\uc73c\ub85c \ub2e4\ub9ac\uac00 \uc11c\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac15 \uc704\uc5d0\uc11c \ubcf4\uc774\uc9c0 \uc54a\ub294 \uae30\ucd08\ub3c4 \uac19\uc740 \uccb4\uacc4\uc758 \uc77c\ubd80\ub2e4. \uba4b\uc9c4 \uc724\uacfd\uacfc \uc2e4\uc81c\ub85c \ud558\uc911\uc744 \uc804\ub2ec\ud558\ub294 \uad6c\uc870\ub97c \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \ud0d1\uc774 \ucda9\ubd84\ud788 \uc548\uc815\ub418\uc9c0 \uc54a\uc73c\uba74 \uadf8 \uc704\uc5d0 \uac78\ub9b0 \uad6c\uc870\ub3c4 \uc548\uc804\ud560 \uc218 \uc5c6\ub2e4. \uadf8\ub798\uc11c \uac15 \uc544\ub798\uc758 \uae30\ucd08 \uacf5\uc0ac\ub294 \uc804\uccb4 \uc0ac\uc5c5\uc758 \ud575\uc2ec\uc774\uc5c8\ub2e4. \uc704\ub85c \ub192\uc774 \uc138\uc6b0\ub294 \uc77c\uc740 \uc544\ub798\ub85c \ub0b4\ub824\uac00 \ud655\uc2e4\ud55c \uc790\ub9ac\ub97c \ub9cc\ub4dc\ub294 \uc77c\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \ubb3c \uc544\ub798\uc758 \uae30\ucd08 \uc791\uc5c5\uc5d0\ub294 \ucf00\uc774\uc2a8\uc774\ub77c\ub294 \ud070 \uad6c\uc870\uac00 \uc4f0\uc600\ub2e4. \ub0b4\ubd80\uc5d0\uc11c \uc77c\ud560 \uacf5\uac04\uc744 \ud655\ubcf4\ud558\uace0 \ubc14\ub2e5\uc744 \ub2e4\ub8e8\uc5b4\uc57c \ud588\ub2e4. \uc555\ucd95\uacf5\uae30\ub97c \uc774\uc6a9\ud55c \ud658\uacbd\uc740 \ubb3c\uc744 \ub9c9\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub418\uc5c8\uc9c0\ub9cc \ub178\ub3d9\uc790\uc5d0\uac8c\ub294 \ud3c9\uc18c\uc640 \ub2e4\ub978 \uc870\uac74\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc740 \uc791\uc5c5 \ub4a4 \ub098\ud0c0\ub098\ub294 \uc2ec\uac01\ud55c \ubcd1\uc744 \uacaa\uc5c8\ub2e4. \uac1c\ud1b5\uc2dd \uae30\ub85d\ub3c4 \uadf8 \uc704\ud5d8\uacfc \uc0ac\ub9dd\ud55c \ub178\ub3d9\uc790\ub4e4\uc744 \uc5b8\uae09\ud55c\ub2e4. \uc704\ub300\ud55c \uacf5\uc0ac\uc758 \uc131\uacf5\uc744 \ub9d0\ud558\ub294 \ubb38\uc11c \uc548\uc5d0 \ubab8\uc774 \uce58\ub978 \ube44\uc6a9\uc774 \ub0a8\uc544 \uc788\ub294 \uac83\uc774\ub2e4. \uc624\ub298\uc758 \uac10\uc555\ubcd1 \uc9c0\uc2dd\uc744 \ub2f9\uc2dc \ubaa8\ub450\uac00 \uc774\ubbf8 \uc54c\uace0 \uc788\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uacc4\ud68d\uacfc \uc2dc\uacf5\uc5d0\ub294 \uc874 \ub85c\ube14\ub9c1\uacfc \uc6cc\uc2f1\ud134 \ub85c\ube14\ub9c1\uc774\ub77c\ub294 \ub450 \uc138\ub300\uac00 \uc5f0\uacb0\ub41c\ub2e4. \uc6cc\uc2f1\ud134\uc740 \ud604\uc7a5\uc744 \ub9e1\uc558\uc9c0\ub9cc \ucf00\uc774\uc2a8 \uc791\uc5c5\uacfc \uad00\ub828\ub41c \ubcd1\uc73c\ub85c \uc624\ub7ab\ub3d9\uc548 \uac74\uac15\uc744 \uc783\uc5c8\ub2e4. \uc5f0\uc124\uc740 \uc80a\uace0 \ud65c\uae30\ucc3c\ub358 \uae30\uc220\uc790\uac00 \uc9d1\uc5d0 \uba38\ubb34\ub294 \ucc98\uc9c0\uac00 \ub418\uc5c8\ub2e4\uace0 \ud68c\uace0\ud55c\ub2e4. \uae30\uc220\uc790\uac00 \ud604\uc7a5\uc5d0 \uc9c1\uc811 \uacc4\uc18d \ub098\uc62c \uc218 \uc5c6\uc744 \ub54c \uc815\ubcf4\uc640 \ud310\ub2e8\uc740 \ub2e4\ub978 \uacbd\ub85c\ub85c \uc804\ub2ec\ub418\uc5b4\uc57c \ud588\ub2e4. \uacf5\uc0ac\ub294 \ud55c \uac1c\uc778\uc758 \uac74\uac15 \uc0c1\ud0dc\uc640 \ubb34\uad00\ud558\uac8c \uc790\ub3d9\uc73c\ub85c \uad74\ub7ec\uac00\ub294 \uc77c\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc124\uacc4\uc790\uc758 \uc5ed\ud560\uacfc \uc2e4\uc81c \ud604\uc7a5\uc744 \uc787\ub294 \uad00\uacc4\uac00 \uc720\uc9c0\ub418\uc5b4\uc57c \ud588\ub2e4. \uac1c\ud1b5\uc2dd \uae30\ub85d\uc5d0\ub294 \uc5d0\ubc00\ub9ac \uc6cc\ub7f0 \ub85c\ube14\ub9c1\uc5d0 \ub300\ud55c \uacf5\uac1c\uc801\uc778 \ucc2c\uc0ac\uac00 \ub2f4\uaca8 \uc788\ub2e4. \ub0a8\ud3b8\uc758 \ub73b\uacfc \uacf5\uc0ac \ud604\uc7a5\uc744 \uc787\ub294 \uacfc\uc815\uc5d0\uc11c \uadf8\ub140\uac00 \ub9e1\uc740 \uc5ed\ud560\uc774 \uc778\uc815\ub41c \uac83\uc774\ub2e4. \ub2e8\uc21c\ud788 \ud6cc\ub96d\ud55c \ub0a8\ud3b8\uc744 \uc751\uc6d0\ud55c \uc544\ub0b4\ub77c\ub294 \uc124\uba85\uc73c\ub85c \uc904\uc774\uba74 \uad6c\uccb4\uc801\uc778 \ud611\uc5c5\uc758 \uc758\ubbf8\uac00 \uc0ac\ub77c\uc9c4\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc624\ub298\uc758 \uad00\uc2ec\uc744 \uc774\uc720\ub85c \ub2f9\uc2dc\uc758 \ubaa8\ub4e0 \uacf5\uc2dd \uc9c1\ucc45\uacfc \uacb0\uc815\uc744 \uadf8\ub140 \ud63c\uc790 \ub9e1\uc558\ub2e4\uace0 \ubc14\uafb8\uc5b4 \uc368\uc11c\ub3c4 \uc548 \ub41c\ub2e4. \uae30\ub85d\uc5d0 \ub0a8\uc740 \uc5ed\ud560\uc744 \uc0b4\ud53c\uba74\uc11c \uc5ec\ub7ec \uae30\uc220\uc790\uc640 \ub178\ub3d9\uc790\uac00 \ud568\uaed8\ud55c \uad00\uacc4\ub97c \ubcf4\uc544\uc57c \ud55c\ub2e4. \ub204\uad6c\uc758 \uc77c\uc774 \uc774\ub984\uc73c\ub85c \uae30\uc5b5\ub418\ub294\uac00 \ud558\ub294 \uc9c8\ubb38\ub3c4 \uc5ec\uae30\uc11c \uc0dd\uae34\ub2e4. \uacf5\uc0ac \ud604\uc7a5\uc758 \ud310\ub2e8\uc744 \uc9d1 \uc548\uc5d0 \uc788\ub294 \uae30\uc220\uc790\uc5d0\uac8c \uc804\ub2ec\ud558\uace0 \ub2e4\uc2dc \ud604\uc7a5\uc73c\ub85c \ub3cc\ub824\ubcf4\ub0b4\ub824\uba74 \ub9d0\uacfc \ubb38\uc11c\uac00 \uc815\ud655\ud574\uc57c \ud55c\ub2e4. \uc815\ubcf4\uc758 \uc804\ub2ec\uc740 \uac74\ucd95 \ubc14\uae65\uc758 \uc7a1\ubb34\uac00 \uc544\ub2c8\ub77c \uc2dc\uacf5\uc744 \uc774\uc5b4 \uac00\ub294 \uc870\uac74\uc774\uc5c8\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \ucca0\uacfc \ub3cc \uc0ac\uc774\uc5d0 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc758\uc0ac\uc18c\ud1b5\uc758 \uad6c\uc870\uac00 \ub193\uc5ec \uc788\uc5c8\ub2e4. \uac1c\ud1b5\uc2dd\uc5d0\uc11c \uc774\ub984\uc774 \uc5b8\uae09\ub418\ub294 \ubc29\uc2dd\ub3c4 \uc0b4\ud3b4\ubcfc \ub9cc\ud558\ub2e4. \ub204\uad70\uac00\ub294 \uc9c1\ucc45\uc73c\ub85c \uc18c\uac1c\ub418\uace0 \ub204\uad70\uac00\ub294 \uac10\uc0ac\uc758 \ub9d0\ub85c \ub0a8\ub294\ub2e4. \uadf8\ub7ec\ub098 \uc18c\uac1c \ud615\uc2dd\uc758 \ucc28\uc774\uac00 \uc2e4\uc81c \uae30\uc5ec\uc758 \ud06c\uae30\uc640 \uc5b8\uc81c\ub098 \uac19\uc9c0\ub294 \uc54a\ub2e4. \uc624\ub298\uc758 \ub3c5\uc790\ub294 \uae30\ub85d\ub41c \ucc2c\uc0ac\ub97c \uc77d\uc73c\uba70 \uc774\ub984 \uc5c6\uc774 \ud568\uaed8 \uc77c\ud55c \uc0ac\ub78c\ub4e4\uc758 \uc790\ub9ac\ub3c4 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. 1883\ub144 5\uc6d4 24\uc77c\uc758 \uac1c\ud1b5\uc2dd\uc740 \uc644\uc131\uc744 \ucd95\ud558\ud558\ub294 \ud589\uc0ac\uc600\ub2e4. \uc5f0\uc124\uacfc \uc74c\uc545, \ub3c4\uc2dc \ub300\ud45c\uc758 \ub9d0\uc740 \uc131\ucde8\uc640 \ubbf8\ub798\ub97c \uac15\uc870\ud55c\ub2e4. \uc774\ub7f0 \uc790\ub8cc\ub294 \ub2f9\uc2dc\uc758 \uae30\ub300\ub97c \uc0dd\uc0dd\ud558\uac8c \ubcf4\uc5ec \uc8fc\uc9c0\ub9cc \uacf5\uc0ac\uc5d0 \uad00\ud55c \ubaa8\ub4e0 \ubb38\uc81c\ub97c \uac19\uc740 \ubb34\uac8c\ub85c \uc124\uba85\ud558\ub294 \ubcf4\uace0\uc11c\ub294 \uc544\ub2c8\ub2e4. \ub530\ub77c\uc11c \uce6d\ucc2c\uc758 \ubb38\uc7a5\uc744 \uc77d\uc744 \ub54c\uc5d0\ub294 \ubb34\uc5c7\uc744 \uae30\ub150\ud558\ub824\ub294 \uc790\ub9ac\uc600\ub294\uc9c0 \uc54c\uc544\uc57c \ud55c\ub2e4. \uae30\ub150\uc2dd\uc758 \uc790\ubd80\uc2ec\uacfc \uc791\uc5c5\uc790\uac00 \uacaa\uc740 \uc704\ud5d8\uc744 \ud568\uaed8 \uc77d\uc73c\uba74 \ud55c\ucabd\ub9cc \ub0a8\uae34 \uc124\uba85\ubcf4\ub2e4 \uc5ed\uc0ac\uc5d0 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \uc790\ub8cc\uc758 \ubaa9\uc801\uc744 \uc544\ub294 \uc77c\uc740 \uadf8 \uc790\ub8cc\ub97c \ubc84\ub9ac\ub294 \ub300\uc2e0 \ub354 \uc815\ud655\ud558\uac8c \uc4f0\ub294 \ubc29\ubc95\uc774\ub2e4. \uc624\ub298 \ub2e4\ub9ac\uc758 \uc724\uacfd\uc744 \ubcfc \ub54c\uc5d0\ub294 \ucf00\uc774\ube14\uc774 \uc5b4\ub514\ub85c \ud798\uc744 \ubcf4\ub0b4\ub294\uc9c0, \ud0d1 \uc544\ub798\uc5d0\ub294 \ubb34\uc5c7\uc774 \uc788\ub294\uc9c0 \uc0c1\uc0c1\ud574 \ubcf4\uc790. \ub3d9\uc2dc\uc5d0 \uad6c\uc870\ub97c \uacc4\uc0b0\ud558\uace0 \uc815\ubcf4\ub97c \uc804\ud558\uba70 \uc704\ud5d8\ud55c \uacf3\uc5d0\uc11c \uc77c\ud55c \uc0ac\ub78c\ub4e4\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uc544\ub984\ub2e4\uc6c0\uacfc \ub178\ub3d9\uc740 \uac19\uc740 \ub2e4\ub9ac\uc758 \ub2e4\ub978 \uba74\uc774\ub2e4. \ube0c\ub8e8\ud074\ub9b0 \ub2e4\ub9ac\ub294 \ud55c \uba85\uc758 \uc601\uc6c5\uc774 \uc644\uc131\ud55c \ubb3c\uac74\ubcf4\ub2e4 \uc5ec\ub7ec \uc5ed\ud560\uc744 \uc5f0\uacb0\ud55c \uc0ac\uc5c5\uc73c\ub85c \uc77d\uc744 \ub54c \ub354 \ud48d\ubd80\ud558\ub2e4. \ubb3c \uc704\uc758 \uae38\uc740 \ubb3c \uc544\ub798\uc758 \uc791\uc5c5\uacfc \uc9d1 \uc548\uc5d0\uc11c \uc774\uc5b4\uc9c4 \ud310\ub2e8 \uc704\uc5d0 \ub193\uc600\ub2e4. \uac1c\ud1b5\uc744 \ucd95\ud558\ud55c \uae30\ub85d\uacfc \uc77c\ud558\ub294 \ubab8\uc758 \uae30\uc5b5\uc774 \uac19\uc740 \uad6c\uc870\ubb3c\uc5d0 \ub0a8\uc544 \uc788\ub294 \uc148\uc774\ub2e4. \ubcf4\uc774\ub294 \ud48d\uacbd\uc744 \uac00\ub2a5\ud558\uac8c \ud55c \ubcf4\uc774\uc9c0 \uc54a\ub294 \uad00\uacc4\uae4c\uc9c0 \uc0dd\uac01\ud558\uba74 \uc775\uc219\ud55c \ub3c4\uc2dc\uc758 \uc0c1\uc9d5\uc774 \uc0c8\ub86d\uac8c \ubcf4\uc778\ub2e4."}, {"id": "cahokia-mound-and-plaza", "title": "\uce74\ud638\ud0a4\uc544 \u2014 \ud3c9\ubc94\ud55c \uc5b8\ub355\uc778 \uc904 \uc54c\uc558\ub294\ub370", "summary": "\ubabd\ud06c\uc2a4 \ub9c8\uc6b4\ub4dc\uc640 \uad11\uc7a5\u00b7\uc8fc\uac70\uc9c0\uc758 \uad00\uacc4\ub97c \ud1b5\ud574 \ubd81\ubbf8 \uc6d0\uc8fc\ubbfc \ub3c4\uc2dc \uce74\ud638\ud0a4\uc544\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/cahokia-mound-and-plaza/index.html", "image": "../media/cahokia-mound-and-plaza.jpg", "alt": "\ud480\ub85c \ub36e\uc778 \uacc4\ub2e8\uc2dd \ud759 \uae30\ub2e8\uc778 \uce74\ud638\ud0a4\uc544 \ubabd\ud06c\uc2a4 \ub9c8\uc6b4\ub4dc\uc758 \uc2e4\uc81c \uc804\uacbd\uacfc \ud604\ub300 \ubc29\ubb38 \uacc4\ub2e8.", "text": "\uce74\ud638\ud0a4\uc544 \u2014 \ud3c9\ubc94\ud55c \uc5b8\ub355\uc778 \uc904 \uc54c\uc558\ub294\ub370 \uc794\ub514\uac00 \ub36e\uc778 \ud759\ubb34\ub354\uae30\uc5d0\uc11c \uac70\ub300\ud55c \ub3c4\uc2dc\ub97c \uc77d\ub294 \ubc29\ubc95 \ubabd\ud06c\uc2a4 \ub9c8\uc6b4\ub4dc\uc640 \uad11\uc7a5\u00b7\uc8fc\uac70\uc9c0\uc758 \uad00\uacc4\ub97c \ud1b5\ud574 \ubd81\ubbf8 \uc6d0\uc8fc\ubbfc \ub3c4\uc2dc \uce74\ud638\ud0a4\uc544\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc0ac\uc9c4\ub9cc \uba3c\uc800 \ubcf4\uba74 \uc794\ub514\uac00 \ub36e\uc778 \uc5b8\ub355\uc774\ub2e4. \uc67c\ucabd\uc73c\ub85c \uacc4\ub2e8 \uac19\uc740 \uc120\uc774 \uc62c\ub77c\uac00\uace0 \uc704\ucabd\uc740 \ub113\uace0 \ud3c9\ud3c9\ud558\ub2e4. \uc8fc\ubcc0\uc758 \ud48d\uacbd\uacfc \ud06c\uac8c \ub2e4\ub974\uc9c0 \uc54a\uc544 \ub208\uae38\uc744 \uc624\ub798 \ubd99\uc7a1\uc9c0 \uc54a\uc744 \uc218\ub3c4 \uc788\ub2e4. \uadf8\ub7f0\ub370 \uc774\uac83\uc774 \uc0ac\ub78c\ub4e4\uc774 \ud759\uc744 \uc313\uc544 \ub9cc\ub4e0 \uac70\ub300\ud55c \uad6c\uc870\ubb3c\uc774\ub77c\uace0 \uc54c\uba74 \uc2dc\uc120\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ubbf8\uad6d\uc758 \uc624\ub298\ub0a0 \uc138\uc778\ud2b8\ub8e8\uc774\uc2a4 \uadfc\ucc98\uc5d0 \ub0a8\uc544 \uc788\ub294 \uce74\ud638\ud0a4\uc544\uc758 \ubabd\ud06c\uc2a4 \ub9c8\uc6b4\ub4dc\ub2e4. \ud070 \ub3cc\uae30\ub465\uc774\ub098 \ub192\uc774 \ub0a8\uc740 \uc131\ubcbd\uc774 \uc5c6\uc5b4\ub3c4 \uc774\uacf3\uc740 \uc624\ub798\uc804 \ub3c4\uc2dc\ub97c \uc774\ub8e8\uc5c8\ub2e4. \ub545 \uc704\uc758 \ub192\ub0ae\uc774\ub97c \uac74\ubb3c\uc758 \ud754\uc801\uc73c\ub85c \uc77d\uc73c\uba74 \uc775\uc219\ud55c \ub3c4\uc2dc\uc758 \uc774\ubbf8\uc9c0\uac00 \uc870\uae08 \ub113\uc5b4\uc9c4\ub2e4. \uce74\ud638\ud0a4\uc544\ub294 \ubbf8\uc2dc\uc2dc\ud53c \ubb38\ud654\uad8c\uc758 \uc911\uc694\ud55c \uc911\uc2ec\uc774\uc5c8\ub2e4. \uc774 \ubb38\ud654\uad8c\uc758 \ud070 \uc815\ucc29\uc9c0\ub4e4\uc740 \uc625\uc218\uc218\ub97c \ube44\ub86f\ud55c \ub18d\uc5c5\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc131\uc7a5\ud588\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \uacbd\uc791\uc9c0\uc640 \uc9d1, \uc758\ub840\uc640 \uad8c\ub825\uc758 \uacf5\uac04\uc744 \uc77c\uc815\ud55c \uad00\uacc4 \uc548\uc5d0 \ubc30\uce58\ud558\uba70 \uc0b4\uc558\ub2e4. \uad50\uc7ac\ub294 \uce74\ud638\ud0a4\uc544\uac00 1050\ub144 \ubb34\ub835 \ud070 \ub3c4\uc2dc \uc911\uc2ec\uc9c0\ub85c \ubc1c\uc804\ud558\uae30 \uc2dc\uc791\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc804\uc131\uae30\uc5d0\ub294 \uc8fc\ubcc0 \uc815\ucc29\uc9c0\ub97c \ud3ec\ud568\ud574 \uc218\ub9ce\uc740 \uc8fc\ubbfc\uacfc \ubc31 \uac1c\uac00 \ub118\ub294 \ud759\ubb34\ub364\u00b7\uae30\ub2e8\ub4e4\uc774 \uc788\uc5c8\ub2e4. \uc624\ub298 \ub0a8\uc740 \ud48d\uacbd\uc774 \uc870\uc6a9\ud558\ub2e4\uace0 \ub2f9\uc2dc\uc5d0\ub3c4 \uc0ac\ub78c\uc774 \ub4dc\ubb38 \ube48 \ub545\uc774\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ubabd\ud06c\uc2a4 \ub9c8\uc6b4\ub4dc\ub294 \uc57d 100\ud53c\ud2b8, 30\ubbf8\ud130 \uc815\ub3c4 \ub192\uc774\uc5d0 \uc774\ub974\ub294 \uacc4\ub2e8\uc2dd \ud759 \uad6c\uc870\ubb3c\uc774\ub2e4. \ud55c \ubc88\uc5d0 \ud759\uc744 \ubd80\uc5b4 \ub05d\ub0b8 \uac83\uc774 \uc544\ub2c8\ub77c \uc5ec\ub7ec \ub2e8\uacc4\uc5d0 \uac78\uccd0 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4. \uaf2d\ub300\uae30\uc5d0\ub294 \ubaa9\uc870 \uad6c\uc870\ubb3c\uc774 \uc788\uc5c8\uace0 \uc8fc\ubcc0 \uad11\uc7a5\uc5d0\uc11c \uc62c\ub77c\uac00\ub294 \uacc4\ub2e8\uc774 \uc788\uc5c8\ub2e4\uace0 \uad50\uc7ac\ub294 \uc124\uba85\ud55c\ub2e4. \uc774\ub97c \uc54c\uba74 \uc0ac\uc9c4\uc758 \ud3c9\ud3c9\ud55c \uc717\ubd80\ubd84\uacfc \uce35\uc744 \uc774\ub8ec \uacbd\uc0ac\uac00 \ub2e4\ub974\uac8c \ubcf4\uc778\ub2e4. \ub545\uc744 \uc774\uc6a9\ud574 \uc911\uc694\ud55c \uc7a5\uc18c\uc758 \ub192\uc774\ub97c \ub9cc\ub4e0 \uac83\uc774\ub2e4. \ud759\uc774\ub77c\ub294 \uc7ac\ub8cc\ub97c \uc37c\ub2e4\uace0 \uc870\uc9c1\uacfc \uae30\uc220\uc774 \ub2e8\uc21c\ud588\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud759\uc744 \ubaa8\uc73c\uace0 \uc62e\uae30\uba70 \ud070 \ud615\ud0dc\ub97c \uc720\uc9c0\ud558\ub294 \ub370\ub3c4 \ub9ce\uc740 \uc0ac\ub78c\uc758 \ud611\ub825\uc774 \ud544\uc694\ud588\ub2e4. \ub192\uc740 \uad6c\uc870\ubb3c \ud558\ub098\ub97c \ub530\ub85c \ub5bc\uc5b4 \ub193\uc73c\uba74 \uac70\ub300\ud55c \uae30\ub150\ube44\ucc98\ub7fc\ub9cc \ubcf4\uc778\ub2e4. \uadf8\ub7ec\ub098 \uce74\ud638\ud0a4\uc544\uc758 \uc911\uc2ec\ubd80\uc5d0\uc11c\ub294 \uc5ec\ub7ec \ud759 \uae30\ub2e8\uacfc \ud070 \uad11\uc7a5\uc774 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc624\ub974\uace0 \ub0b4\ub824\uac00\ub294 \uc0ac\ub78c, \uc544\ub798\uc5d0\uc11c \ubc14\ub77c\ubcf4\ub294 \uc0ac\ub78c\uc758 \uc704\uce58\uac00 \uc11c\ub85c \ub2ec\ub790\uc744 \uac83\uc774\ub2e4. \ub3c4\uc2dc\uc758 \uc7a5\uc18c\ub294 \ub192\uc774\ubfd0 \uc544\ub2c8\ub77c \ub2e4\ub978 \uacf5\uac04\uacfc\uc758 \uad00\uacc4\ub85c \uc758\ubbf8\ub97c \uac16\ub294\ub2e4. \ub113\uc740 \uad11\uc7a5\uacfc \uadf8 \uc606\uc758 \ub192\uc740 \uae30\ub2e8\uc744 \uac19\uc774 \uc0dd\uac01\ud558\uba74 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub514\uc5d0 \ubaa8\uc774\uace0 \uc911\uc694\ud55c \uc758\ub840\uac00 \uc5b4\ub5a4 \ud658\uacbd\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc84c\ub294\uc9c0 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \ud2b9\uc815\ud55c \ud589\uc0ac \uc7a5\uba74\uc744 \ucc3d\uc791\ud558\uc9c0 \uc54a\uc544\ub3c4 \ubc30\uce58 \uc790\uccb4\uac00 \uc774\uc57c\uae30\ub97c \uac74\ub128\ub2e4. \uc911\uc2ec \uad11\uc7a5 \ubc14\uae65\uc73c\ub85c\ub294 \ubaa9\uc7ac\uc640 \uc774\uc5c9\uc744 \uc774\uc6a9\ud55c \uc9d1\ub4e4\uc774 \uc788\uc5c8\uace0 \uadf8 \uc8fc\ubcc0\uc73c\ub85c \uc625\uc218\uc218\ubc2d\uc774 \uc774\uc5b4\uc84c\ub2e4. \uc9c0\ubc30\uce35\uc758 \uac70\ucc98\uc640 \uc911\uc2ec \uae30\ub2e8\ub4e4\uc740 \ubc29\uc5b4\ubcbd\uc73c\ub85c \ub458\ub7ec\uc2f8\uc778 \uad6c\uc5ed\uacfc\ub3c4 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \ubaa8\ub450\uac00 \uac19\uc740 \uc704\uce58\uc640 \uc870\uac74\uc5d0\uc11c \uc0b4\uc558\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub3c4\uc2dc\ub97c \uc720\uc9c0\ud558\ub824\uba74 \uc758\ub840\ubfd0 \uc544\ub2c8\ub77c \ub9e4\uc77c \uba39\uace0 \uc790\uace0 \uc77c\ud558\ub294 \ud65c\ub3d9\uc774 \ud544\uc694\ud558\ub2e4. \uc9d1\uc5d0 \uc4f8 \uc7ac\ub8cc\uc640 \uc2dd\ub7c9\uc744 \ub9c8\ub828\ud558\uace0 \ubb3c\uac74\uc744 \ub9cc\ub4dc\ub294 \uc77c\uc774 \uc774\uc5b4\uc838\uc57c \ud588\ub2e4. \ub208\uc5d0 \ud06c\uac8c \ub0a8\uc740 \uae30\ub2e8\uc740 \uc624\ub7ab\ub3d9\uc548 \uc0dd\ud65c\uc744 \uc774\uc5b4 \uac04 \uc0ac\ub78c\ub4e4\uc758 \uc2dc\uac04 \uc704\uc5d0 \uc11c \uc788\ub294 \uc148\uc774\ub2e4. \uce74\ud638\ud0a4\uc544\uc758 \uc720\ub825\uc790\ub4e4\uc740 \ud574\uc591 \uc870\uac1c\uc640 \ud2b9\ubcc4\ud55c \ub3cc, \uad6c\ub9ac \uac19\uc740 \ubb3c\uac74\uc5d0 \uc811\uadfc\ud560 \uc218 \uc788\uc5c8\ub2e4. \uc774\ub7f0 \uc790\ub8cc\ub294 \ub3c4\uc2dc\uac00 \uac00\uae4c\uc6b4 \uacbd\uc791\uc9c0\ub9cc \ubc14\ub77c\ubcf4\ub358 \uacf3\uc774 \uc544\ub2c8\ub77c \uc7a5\uac70\ub9ac \uad50\uc5ed\ub9dd\uacfc\ub3c4 \uc5f0\uacb0\ub418\uc5c8\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ubc14\ub2e4\uc5d0\uc11c \ub098\uc628 \ubb3c\uac74\uc774 \ub0b4\ub959\uc758 \uc911\uc694\ud55c \uc790\ub9ac\ub85c \ub4e4\uc5b4\uc628 \uac83\uc774\ub2e4. \uadc0\ud55c \ubb3c\uac74\uc744 \uac00\uc84c\ub2e4\ub294 \uac83\uc740 \ub2e8\uc21c\ud788 \ucde8\ud5a5\uc774 \uc88b\uc558\ub2e4\ub294 \ub73b\ub9cc\uc740 \uc544\ub2c8\ub2e4. \ub204\uac00 \ub2e4\ub978 \uc9c0\uc5ed\uacfc \uad00\uacc4\ub97c \ub9fa\uace0 \ubb3c\uc790\ub97c \ubaa8\uc744 \uc218 \uc788\uc5c8\ub294\uc9c0\uac00 \uad8c\ub825\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uad50\uc7ac\ub294 \uacf5\ub0a9\uacfc \uad50\uc5ed\ub85c\uc5d0 \ub300\ud55c \ud1b5\uc81c\ub97c \uc774 \uc911\uc2ec\uc9c0\ub4e4\uc774 \ud798\uc744 \uc720\uc9c0\ud55c \ubc30\uacbd\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \ub3c4\uc2dc\uc758 \uc704\uc138\ub294 \ub192\uc740 \ud759 \uae30\ub2e8\ubfd0 \uc544\ub2c8\ub77c \uc0ac\ub78c \uc0ac\uc774\uc758 \uad00\uacc4\uc5d0\ub3c4 \uc788\uc5c8\ub2e4. \uce74\ud638\ud0a4\uc544\uc758 \uc5ec\ub7ec \ud759 \uad6c\uc870\ubb3c\uc5d0\ub294 \ub9e4\uc7a5\uc774\ub098 \uc758\ub840\ub97c \uc704\ud55c \uc7a5\uc18c\ub3c4 \uc788\uc5c8\ub2e4. \ud06c\uace0 \ub192\ub2e4\ub294 \uc678\ud615\ub9cc\uc73c\ub85c \ubaa8\ub450 \uac19\uc740 \uc885\ub958\uc758 \uac74\ubb3c \ubc1b\uce68\uc774\uc5c8\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc5b4\ub5a4 \uc7a5\uc18c\uc5d0\uc11c \ubb34\uc5c7\uc774 \ubc1c\uacac\ub418\uc5c8\ub294\uc9c0\uac00 \uac01\uac01\uc758 \ud574\uc11d\uc5d0 \uc911\uc694\ud558\ub2e4. \uc0ac\ub78c\uacfc \ubb3c\uac74\uc758 \ud754\uc801\uc744 \ud1b5\ud574 \uc9c0\uc704\uc758 \ucc28\uc774\ub97c \uc77d\uc744 \uc218\ub3c4 \uc788\uc9c0\ub9cc, \uc720\ubb3c\ub9cc\uc73c\ub85c \uc778\ubb3c\uc758 \uc774\ub984\uacfc \uc815\ud655\ud55c \uc9c1\ucc45\uae4c\uc9c0 \ubaa8\ub450 \ubcf5\uc6d0\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uace0\uace0\ud559 \uc124\uba85\uc5d0\ub294 \ud655\uc778\ub41c \ud615\ud0dc\uc640 \uadf8 \uc758\ubbf8\uc5d0 \ub300\ud55c \ud574\uc11d\uc774 \ud568\uaed8 \uc788\ub2e4. \ub458\uc744 \ub098\ub204\uc5b4 \uc77d\uc73c\uba74 \uc54c\ub824\uc9c4 \ub0b4\uc6a9\uc774 \uc904\uc5b4\ub4dc\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uadfc\uac70\uc758 \uc131\uaca9\uc774 \ub354 \uc798 \ubcf4\uc778\ub2e4. \uce74\ud638\ud0a4\uc544\ub294 \uc624\ub7ab\ub3d9\uc548 \uac19\uc740 \uaddc\ubaa8\ub85c \uc720\uc9c0\ub418\uc9c0 \uc54a\uc558\ub2e4. \uc2dc\uac04\uc774 \uc9c0\ub098\uba70 \uc1e0\ud1f4\ud588\uace0 \uacb0\uad6d \ud070 \uc911\uc2ec\uc9c0\ub85c\uc11c\uc758 \uc0dd\ud65c\uc740 \ub05d\ub0ac\ub2e4. \ud558\uc9c0\ub9cc \uadf8\uac83\uc744 \ubbf8\uc2dc\uc2dc\ud53c \ubb38\ud654\uad8c \uc804\uccb4\ub098 \uc6d0\uc8fc\ubbfc \uc0ac\ud68c\uac00 \ub3d9\uc2dc\uc5d0 \uc0ac\ub77c\uc9c4 \uc77c\ub85c \uc774\ud574\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ub2e4\ub978 \uc9c0\uc5ed\uc758 \uc911\uc2ec\uc9c0\ub4e4\uc774 \uc131\uc7a5\ud588\uace0 \uc0ac\ub78c\ub4e4\uc758 \uc0dd\ud65c\uacfc \ubb38\ud654\ub294 \ub2e4\ub978 \ud615\ud0dc\ub85c \uc774\uc5b4\uc84c\ub2e4. \uad50\uc7ac\ub294 \uc5d0\ud1a0\uc640\uc640 \ub9c8\uc6b4\ub4dc\ube4c \uac19\uc740 \uc0ac\ub840\ub97c \ud568\uaed8 \uc18c\uac1c\ud55c\ub2e4. \uc6b0\ub9ac\uac00 \ud55c \uc720\uc801\uc758 \ud765\ub9dd\uc744 \ub3c4\uc2dc\uc758 \uc774\uc57c\uae30\ub85c \uc77d\uc744 \ub54c, \uadf8\uacf3\uc744 \ub5a0\ub09c \uc0ac\ub78c\ub4e4\uc758 \uc774\ud6c4 \uc2dc\uac04\uae4c\uc9c0 \uc9c0\uc6cc \ubc84\ub9ac\uc9c0\ub294 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc0ac\uc9c4\uc758 \ud604\ub300 \uacc4\ub2e8\uc740 \ud604\uc7ac \ubc29\ubb38\uc790\uac00 \uc704\ub85c \uc62c\ub77c\uac00\uac8c \ud574 \uc8fc\ub294 \uc2dc\uc124\uc774\ub2e4. \uc774\uac83\uc744 \uc61b \ubaa9\uc870 \uacc4\ub2e8\uc758 \ubaa8\uc2b5 \uadf8\ub300\ub85c\ub77c\uace0 \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uc624\ub298 \ubcfc \uc218 \uc788\ub294 \uae38\uacfc \uacfc\uac70\uc5d0 \uc124\uba85\ub41c \uae38\uc744 \ub098\ub204\uc5b4 \ubcf4\uba74\uc11c\ub3c4, \uc544\ub798\uc640 \uc704\uc758 \ub192\uc774 \ucc28\uc774\ub294 \uc9c1\uc811 \ub208\uc73c\ub85c \ub290\ub084 \uc218 \uc788\ub2e4. \uce74\ud638\ud0a4\uc544\ub294 \ub3c4\uc2dc\uac00 \ubc18\ub4dc\uc2dc \ub3cc\uacfc \ubcbd\ub3cc\uc758 \uc232\uc73c\ub85c\ub9cc \ub0a8\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc0ac\uc2e4\uc744 \uc54c\ub824 \uc900\ub2e4. \uc794\ub514\uc5d0 \ub36e\uc778 \ud759\ub3c4 \uc0ac\ub78c\uc758 \uacc4\ud68d\uacfc \ud611\ub825\uc744 \uc624\ub798 \ubcf4\uad00\ud560 \uc218 \uc788\ub2e4. \ud3c9\ubc94\ud55c \uc5b8\ub355\ucc98\ub7fc \ubcf4\uc600\ub358 \ud48d\uacbd\uc774 \ub2ec\ub77c\uc9c0\ub294 \uc21c\uac04, \uc9c0\ud615\uc744 \ubc14\ub77c\ubcf4\ub294 \ub208\uc774 \ub3c4\uc2dc\ub97c \uc77d\ub294 \ub208\uc73c\ub85c \ubc14\ub010\ub2e4."}, {"id": "canada-1867-confederation-provinces-and-exclusions", "title": "\uce90\ub098\ub2e4 1867 \u2014 \ud558\ub098\uc758 \uad6d\uac00\uac00 \ub41c\ub2e4\ub294 \ub370\uc5d0\ub294 \ubb34\uc5c7\uc774 \ud544\uc694\ud588\uc744\uae4c", "summary": "\ub124 \uc8fc\uc758 \ucd9c\ubc1c\uacfc \uc9c0\uc5ed\uc758 \uad8c\ud55c, \ud611\uc0c1 \ubc16\uc5d0 \ub0a8\uc740 \uc0ac\ub78c\ub4e4\uc758 \ubc30\uacbd\uacfc \uc804\uac1c, \uc774\ud6c4\uc758 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/canada-1867-confederation-provinces-and-exclusions/index.html", "image": "../media/canada-1867-confederation-provinces-and-exclusions.jpg", "alt": "\ub85c\ubc84\ud2b8 \ud574\ub9ac\uc2a4\uc758 \uc5f0\ubc29 \uc9c0\ub3c4\uc790 \uadf8\ub9bc\uc744 \uc7ac\ud604\ud55c \uc5ed\uc0ac \ucd9c\ud310 \ub3c4\ud310", "text": "\uce90\ub098\ub2e4 1867 \u2014 \ud558\ub098\uc758 \uad6d\uac00\uac00 \ub41c\ub2e4\ub294 \ub370\uc5d0\ub294 \ubb34\uc5c7\uc774 \ud544\uc694\ud588\uc744\uae4c \ub124 \uc8fc\uc758 \ucd9c\ubc1c\uacfc \uc9c0\uc5ed\uc758 \uad8c\ud55c, \ud611\uc0c1 \ubc16\uc5d0 \ub0a8\uc740 \uc0ac\ub78c\ub4e4 \ub124 \uc8fc\uc758 \ucd9c\ubc1c\uacfc \uc9c0\uc5ed\uc758 \uad8c\ud55c, \ud611\uc0c1 \ubc16\uc5d0 \ub0a8\uc740 \uc0ac\ub78c\ub4e4\uc758 \ubc30\uacbd\uacfc \uc804\uac1c, \uc774\ud6c4\uc758 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uce90\ub098\ub2e4\uc758 \ud0c4\uc0dd\uc744 \ub9d0\ud560 \ub54c 1867\ub144\uc774\ub77c\ub294 \ud574\uac00 \ub4f1\uc7a5\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uadf8\ub54c \uc624\ub298\ub0a0\uc758 \ubaa8\ub4e0 \uc9c0\uc5ed\uc774 \ud55c\uaebc\ubc88\uc5d0 \ubaa8\uc5ec \uc644\uc804\ud788 \ub3c5\ub9bd\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc2dd\ubbfc\uc9c0\uc758 \uc815\uce58\uac00\ub4e4\uc740 \ubb34\uc5c7\uc744 \ud568\uaed8 \ud558\uace0 \ubb34\uc5c7\uc744 \uac01 \uc9c0\uc5ed\uc5d0 \ub0a8\uae38\uc9c0 \ud611\uc0c1\ud588\ub2e4. \uc5f0\ubc29\uc774\ub77c\ub294 \uc81c\ub3c4\uac00 \ub9cc\ub4e4\uc5b4\uc9c4 \uacfc\uc815\uc744 \ud68c\uc758\uc758 \ud0c1\uc790 \ub108\uba38\uae4c\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc601\uad6d\ub839 \ubd81\uc544\uba54\ub9ac\uce74\uc758 \uc5ec\ub7ec \uc9c0\uc5ed\uc740 \uc5b8\uc5b4\uc640 \uc885\uad50, \uacbd\uc81c\uc640 \uc815\uce58\uc758 \uc870\uac74\uc774 \ub2ec\ub790\ub2e4. \uc624\ub298\uc758 \uc628\ud0c0\ub9ac\uc624\uc640 \ud018\ubca1\uc5d0 \ud574\ub2f9\ud558\ub294 \uc9c0\uc5ed\ub3c4 \ub2f9\uc2dc\uc5d0\ub294 \ud558\ub098\uc758 \uce90\ub098\ub2e4\uc8fc\ub85c \ubb36\uc5ec \uc788\uc5c8\uc73c\uba70 \uadf8 \uc548\uc758 \uc815\uce58\uc801 \uad50\ucc29\uc774 \ubb38\uc81c\uc600\ub2e4. \ub3d9\ucabd\uc758 \ud574\uc591 \uc2dd\ubbfc\uc9c0\ub4e4\uc5d0\ub294 \uc790\uae30\ub4e4\ub07c\ub9ac \uacb0\ud569\ud558\ub824\ub294 \ub17c\uc758\uac00 \uc788\uc5c8\ub2e4. \ub0b4\ub959\uacfc \ud574\uc548\uc758 \uc774\ud574\uac00 \ucc98\uc74c\ubd80\ud130 \uac19\uc740 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uad50\ud1b5\uacfc \ubc29\uc704, \ubb34\uc5ed\uacfc \uc7ac\uc815\uc758 \ubb38\uc81c\ub97c \ud568\uaed8 \ud574\uacb0\ud558\ub824\ub294 \uae30\ub300\uc640 \uc790\uae30 \uc9c0\uc5ed\uc758 \uad8c\ud55c\uc744 \uc783\uc744 \uc218 \uc788\ub2e4\ub294 \uac71\uc815\uc774 \uacf5\uc874\ud588\ub2e4. \ubbf8\uad6d\uacfc\uc758 \uad00\uacc4 \uc5ed\uc2dc \ub17c\uc758\uc758 \ubc30\uacbd\uc774\uc5c8\ub2e4. \ub0a8\ubd81\uc804\uc7c1 \uc804\ud6c4\uc758 \uc815\uc138\uc640 \ubc29\uc704\uc5d0 \ub300\ud55c \uac71\uc815\uc740 \uc2dd\ubbfc\uc9c0\ub4e4\uc774 \ud611\ub825\ud560 \uc774\uc720\uac00 \ub418\uc5c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc678\ubd80\uc758 \uc704\ud611 \ud558\ub098\uac00 \ubaa8\ub4e0 \uacb0\uc815\uc744 \uc124\uba85\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uac01 \uc9c0\uc5ed\uc758 \uc815\uce58\uc801 \uad50\ucc29\uacfc \uacbd\uc81c\uc801 \uae30\ub300\uac00 \ub9cc\ub098\uc57c \uc2e4\uc81c \uacb0\ud569\uc758 \uc870\uac74\uc774 \ub9cc\ub4e4\uc5b4\uc9c8 \uc218 \uc788\uc5c8\ub2e4. 1864\ub144 \uc0ec\ub7ff\ud0c0\uc6b4 \ud68c\uc758\ub294 \ud574\uc591 \uc2dd\ubbfc\uc9c0\uc758 \uacb0\ud569 \ub17c\uc758\uc5d0\uc11c \ucd9c\ubc1c\ud588\ub2e4. \uce90\ub098\ub2e4\uc8fc\uc758 \ub300\ud45c\ub4e4\uc774 \ucc38\uc5ec\ud558\uba74\uc11c \ub354 \ud070 \uc5f0\ud569\uc744 \uac80\ud1a0\ud558\ub294 \ubc29\ud5a5\uc73c\ub85c \ub113\uc5b4\uc84c\ub2e4. \uc774\ubbf8 \uc644\uc131\ub41c \uad6d\uac00\ub97c \uc2b9\uc778\ud558\ub824\uace0 \ubaa8\uc778 \uc790\ub9ac\ub294 \uc544\ub2c8\uc5c8\ub358 \uac83\uc774\ub2e4. \ud68c\uc758\uac00 \uc5f4\ub9b0 \ud504\ub9b0\uc2a4\uc5d0\ub4dc\uc6cc\ub4dc\uc12c\uc774 \uace7\ubc14\ub85c 1867\ub144 \uc5f0\ubc29\uc758 \ucd9c\ubc94 \uad6c\uc131\uc6d0\uc774 \ub41c \uac83\ub3c4 \uc544\ub2c8\ub2e4. \ud68c\uc758 \uc7a5\uc18c\uc640 \uac00\uc785 \uc2dc\uc810\uc744 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc88b\uc740 \uad6c\uc0c1\uc744 \ub4e3\ub294 \uac83\uacfc \uc790\uae30 \uc9c0\uc5ed\uc774 \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \uc870\uac74\uc5d0 \ub3d9\uc758\ud560\uc9c0\ub294 \ub2e4\ub978 \ub2e8\uacc4\uc758 \uacb0\uc815\uc774\uc5c8\ub2e4. \ub4a4\uc774\uc740 \ud018\ubca1 \ud68c\uc758\uc5d0\uc11c\ub294 \uc911\uc559\uacfc \uc9c0\uc5ed\uc758 \uad8c\ud55c, \uc758\ud68c\uc758 \uad6c\uc131\uacfc \ub300\ud45c, \uc7ac\uc815 \ub4f1 \uad6c\uccb4\uc801\uc778 \ubb38\uc81c\uac00 \ub2e4\ub8e8\uc5b4\uc84c\ub2e4. \ub9e5\ub3c4\ub110\ub4dc\u00b7\uce74\ub974\ud2f0\uc5d0\u00b7\ube0c\ub77c\uc6b4\uc744 \ube44\ub86f\ud55c \uc778\ubb3c\ub4e4\uc740 \ub2e4\ub978 \ubc30\uacbd\uacfc \uc774\ud574\uad00\uacc4\ub97c \uac00\uc9c4 \uc138\ub825 \uc0ac\uc774\uc5d0\uc11c \ud0c0\ud611\ud574\uc57c \ud588\ub2e4. \uc911\uc559\uc744 \uac15\ud558\uac8c \ub9cc\ub4e4\uc5b4 \uacf5\ub3d9\uc758 \ubb38\uc81c\ub97c \ucc98\ub9ac\ud558\uba74\uc11c\ub3c4 \uc9c0\uc5ed\uc758 \ucc28\uc774\ub97c \ub0a8\uaca8 \ub450\ub824\uba74 \uc5ed\ud560\uc744 \ub098\ub204\ub294 \uaddc\uce59\uc774 \ud544\uc694\ud588\ub2e4. \uc5f0\ubc29\uc740 \ubaa8\ub450\uac00 \uc644\uc804\ud788 \uac19\uc544\uc838\uc57c\ub9cc \ud568\uaed8 \uc0b4 \uc218 \uc788\ub2e4\ub294 \uad6c\uc0c1\uacfc \ub2ec\ub790\ub2e4. \ub2e4\ub984\uc744 \uc5b4\ub5a4 \uc81c\ub3c4 \uc548\uc5d0 \ub450\ub294\uc9c0\uac00 \ud575\uc2ec\uc774\uc5c8\ub2e4. \uad50\uc721\uacfc \uc5b8\uc5b4, \uc885\uad50\ucc98\ub7fc \uc9c0\uc5ed\uc758 \uc0dd\ud65c\uacfc \uae4a\uac8c \uc5f0\uacb0\ub41c \ubb38\uc81c\ub294 \ub2e8\uc21c\ud788 \ud6a8\uc728\ub9cc\uc73c\ub85c \ud569\uce58\uae30 \uc5b4\ub824\uc6e0\ub2e4. \uc5b4\ub5a4 \uad8c\ud55c\uc744 \uc8fc\uc5d0 \ub0a8\uae30\uace0 \uc5b4\ub5a4 \uad8c\ud55c\uc744 \uc911\uc559\uc774 \ub9e1\uc744\uc9c0 \uc815\ud558\ub294 \uc77c\uc5d0\ub294 \uc11c\ub85c\uc758 \ubd88\uc548\uc744 \ub2e4\ub8e8\ub294 \ud611\uc0c1\uc774 \ud544\uc694\ud588\ub2e4. \uc5f0\ubc29\uc758 \uc124\uacc4\ub294 \ucc28\uc774\ub97c \uad00\ub9ac\ud558\ub294 \uc815\uce58\uc758 \uae30\uc220\uc774\uae30\ub3c4 \ud588\ub2e4. \uc5f0\ubc29 \uacb0\uc131\uc740 \ubaa8\ub4e0 \uc9c0\uc5ed\uc5d0\uc11c \ubc15\uc218\ub9cc \ubc1b\uc9c0 \uc54a\uc558\ub2e4. \ub274\ube0c\ub7f0\uc988\uc705\uacfc \ub178\ubc14\uc2a4\ucf54\uc0e4 \ub4f1\uc5d0\uc11c\ub294 \ucd94\uc9c4 \uacfc\uc815\uacfc \uc870\uac74\uc744 \ub458\ub7ec\uc2fc \ubc18\ub300\uac00 \ub098\ud0c0\ub0ac\ub2e4. \uc0c8\ub85c\uc6b4 \uad6d\uac00\uc758 \uc7a5\uc810\uc744 \uc8fc\uc7a5\ud558\ub294 \uc815\uce58\uac00\uc640 \ube44\uc6a9\uc774\ub098 \uc790\uc728\uc131\uc758 \uc190\uc2e4\uc744 \uac71\uc815\ud558\ub294 \uc8fc\ubbfc\uc758 \ud310\ub2e8\uc774 \uac19\uc9c0 \uc54a\uc744 \uc218 \uc788\uc5c8\ub2e4. \uc61b \uc5f0\ubc29 \ud0c4\uc0dd\uc0ac\uac00 \uc131\uacf5\ud55c \uc9c0\ub3c4\uc790\uc758 \ud611\uc0c1\uc5d0 \uc9d1\uc911\ud55c\ub2e4\uace0 \ud574\uc11c \uadf8 \ubc16\uc758 \ubd88\uc2e0\uc774 \uc911\uc694\ud558\uc9c0 \uc54a\uc558\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud569\uc758\uc758 \uacb0\uacfc\ubfd0 \uc544\ub2c8\ub77c \ub204\uac00 \uc5b8\uc81c \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \uc758\uacac\uc744 \ub0c8\ub294\uc9c0 \ubcf4\uc544\uc57c \uc81c\ub3c4\uac00 \ub9cc\ub4e4\uc5b4\uc9c0\ub294 \uacfc\uc815\uc744 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ubc18\ub300 \uc758\uacac\uc744 \ub4a4\ub2a6\uc740 \uc624\ud574\ub85c\ub9cc \ucc98\ub9ac\ud558\uba74 \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc774 \uac10\uc218\ud55c \ubd88\ud655\uc2e4\uc131\uc774 \uc9c0\uc6cc\uc9c4\ub2e4. \uba3c \uc911\uc559\uc815\ubd80\uac00 \uc790\uae30 \uc9c0\uc5ed\uc758 \uc774\uc775\uc744 \uc5bc\ub9c8\ub098 \ub300\ubcc0\ud560\uc9c0, \ubd80\ub2f4\uacfc \ud61c\ud0dd\uc774 \uc5b4\ub5bb\uac8c \ub098\ub260\uc9c0\ub294 \uc911\uc694\ud55c \uc9c8\ubb38\uc774\uc5c8\ub2e4. \uc0c8\ub85c\uc6b4 \uc81c\ub3c4\uc5d0 \ucc2c\uc131\ud558\ub294 \uc774\uc720\ub9cc\ud07c \ubc18\ub300\ud558\ub294 \uc774\uc720\ub3c4 \uc5ed\uc0ac\uc801 \ud310\ub2e8\uc758 \ub300\uc0c1\uc774\ub2e4. \uc601\uad6d \uc758\ud68c\uac00 \uc81c\uc815\ud55c \ubc95\uc744 \ubc14\ud0d5\uc73c\ub85c 1867\ub144 7\uc6d4 1\uc77c \uce90\ub098\ub2e4 \uc5f0\ubc29\uc774 \ucd9c\ubc94\ud588\ub2e4. \uc628\ud0c0\ub9ac\uc624\u00b7\ud018\ubca1\u00b7\ub178\ubc14\uc2a4\ucf54\uc0e4\u00b7\ub274\ube0c\ub7f0\uc988\uc705 \ub124 \uc8fc\uac00 \ucd9c\ubc1c\uc810\uc774\uc5c8\ub2e4. \uc624\ub298\uc758 \uc9c0\ub3c4\ub97c \uadf8\ub300\ub85c \uadf8 \uc704\uc5d0 \ub193\uc73c\uba74 \ub4a4\uc5d0 \ud569\ub958\ud55c \uc9c0\uc5ed\uc758 \uc2dc\uac04\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \ub610\ud55c \uc5f0\ubc29\uc758 \ucd9c\ubc94\uc774 \uc601\uad6d\uacfc\uc758 \ubaa8\ub4e0 \ubc95\uc801\u00b7\uc815\uce58\uc801 \uc5f0\uacb0\uc744 \uc989\uc2dc \ub04a\uc740 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ub354 \ub113\uc740 \uc790\uce58\uc640 \uc8fc\uad8c\uc758 \ubcc0\ud654\ub294 \uc774\ud6c4\uc5d0\ub3c4 \uc774\uc5b4\uc84c\ub2e4. \uac74\uad6d\uc774\ub77c\ub294 \ud55c \ub2e8\uc5b4 \uc548\uc5d0 \uc5ec\ub7ec \ub2e8\uacc4\uac00 \uc788\ub2e4\ub294 \uc810\uc744 \uad6c\ubd84\ud558\uba74 \uc5f0\ub300 \ud558\ub098\ub97c \uc678\uc6b0\ub294 \uac83\ubcf4\ub2e4 \uc5ed\uc0ac\ub97c \uc815\ud655\ud788 \uc77d\uc744 \uc218 \uc788\ub2e4. \uc774\ud6c4\uc758 \uc601\ud1a0 \ud655\ub300\uc640 \uc8fc\uc758 \uac00\uc785\uc740 \uc800\ub9c8\ub2e4 \ud611\uc0c1\uacfc \uac08\ub4f1\uc758 \uc2dc\uac04\uc744 \uac00\uc84c\ub2e4. \ub530\ub77c\uc11c 1867\ub144\uc744 \uc644\uc131\ub41c \ud604\uc7ac\uc758 \uc2dc\uc791\uc73c\ub85c\ub9cc \ubcf4\uae30\ubcf4\ub2e4 \uacc4\uc18d \ubc14\ub00c\ub294 \uc815\uce58\uc801 \ud2c0\uc758 \ucd9c\ubc1c\ub85c \ubcf4\ub294 \ud3b8\uc774 \ub0ab\ub2e4. \uc5f0\ubc29\uc740 \ud55c \ubc88\uc758 \uc11c\uba85 \ub4a4\uc5d0 \uba48\ucd98 \uc81c\ub3c4\uac00 \uc544\ub2c8\ub77c \ucd94\uac00\uc801\uc778 \uad00\uacc4\ub97c \ubc1b\uc544\ub4e4\uc774\uba70 \ub2ec\ub77c\uc84c\ub2e4. \ud68c\uc758\uc758 \ub300\ud45c\ub4e4\uc740 \ub2f9\uc2dc\uc758 \uc815\uce58 \uc5d8\ub9ac\ud2b8\ub4e4\uc774\uc5c8\ub2e4. \uc5ec\uc131\uacfc \uc6d0\uc8fc\ubbfc \uacf5\ub3d9\uccb4\uac00 \ub3d9\ub4f1\ud55c \ud611\uc0c1 \ub2f9\uc0ac\uc790\ub85c \ucc38\uc5ec\ud55c \uc790\ub9ac\ub77c\uace0 \ubcfc \uc218 \uc5c6\ub2e4. \uadf8 \uc704\uc5d0\uc11c \uacb0\uc815\ub41c \uad6d\uac00\uc758 \ud655\ub300\uc640 \ud1b5\uce58\ub294 \ud68c\uc758 \ubc16\uc5d0 \uc788\ub358 \uc0ac\ub78c\ub4e4\uc758 \uc0b6\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc8fc\uc5c8\ub2e4. \uc5f0\ubc29\uc758 \uc131\uacfc\ub97c \uc77d\uc73c\uba74\uc11c\ub3c4 \uc774 \ubc30\uc81c\ub97c \uc9c0\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774\ud6c4\uc758 \ud1a0\uc9c0\uc640 \uc870\uc57d, \ub3d9\ud654 \uc815\ucc45\uacfc \uad8c\ub9ac \ubb38\uc81c\ub97c \uc774\ud574\ud558\ub824\uba74 \uc0c8\ub85c\uc6b4 \uc81c\ub3c4\uac00 \ub204\uad6c\uc5d0\uac8c \uacb0\uc815\uad8c\uc744 \uc8fc\uc5c8\ub294\uc9c0 \ubb3c\uc5b4\uc57c \ud55c\ub2e4. \uad6d\uac00\uc758 \ucd9c\ubc1c\uc740 \ubaa8\ub4e0 \uc8fc\ubbfc\uc5d0\uac8c \ub611\uac19\uc740 \ucd9c\ubc1c\uc120\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc774 \uae00\uc5d0 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \ub85c\ubc84\ud2b8 \ud574\ub9ac\uc2a4\uc758 \uc791\ud488\uc744 \ubc14\ud0d5\uc73c\ub85c \ud55c \uc5ed\uc0ac \ub3c4\ud310\uc774\ub2e4. \uc778\ubb3c\ub4e4\uc744 \ud55c \uc7a5\uba74\uc5d0 \ubaa8\uc544 \uc5f0\ubc29\uc758 \ud0c4\uc0dd\uc744 \uae30\uc5b5\ud558\uac8c \ub9cc\ub4e0 \uadf8\ub9bc\uc774\uc9c0 \ud68c\uc758 \ub2f9\uc77c\uc744 \ucd2c\uc601\ud55c \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \ub204\uac00 \uc911\uc2ec\uc5d0 \uc788\uace0 \ub204\uac00 \ud654\uba74 \ubc16\uc5d0 \ub0a8\uc558\ub294\uc9c0 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uce90\ub098\ub2e4\uc758 \uc5f0\ubc29\uc740 \ubb38\uc11c\uc640 \ud68c\uc758, \ud0c0\ud611\uacfc \ubc18\ub300\uac00 \uc774\uc5b4\uc9c4 \uacb0\uacfc\uc600\ub2e4. \ud558\ub098\uc758 \uad6d\uac00\uac00 \ub418\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc774 \uc544\ub2c8\ub77c \ud568\uaed8 \uacb0\uc815\ud560 \uc77c\uacfc \ub098\ub204\uc5b4 \ub9e1\uc744 \uc77c\uc744 \uc5b4\ub5bb\uac8c \uc815\ud588\ub294\uc9c0\ub97c \uc77d\uc73c\uba74, 1867\ub144\uc740 \uc624\ub298\uc758 \uc81c\ub3c4\ub97c \uc0dd\uac01\ud558\uac8c \ud558\ub294 \uad6c\uccb4\uc801\uc778 \uc5ed\uc0ac\uac00 \ub41c\ub2e4."}, {"id": "canada-dog-travois", "title": "\ubc14\ud034 \uc5c6\uc774 \uc9d0\uc744 \uc62e\uae30\ub358 \uae34 \ub450 \uac1c\uc758 \ub9c9\ub300", "summary": "1910\ub144 \ubb34\ub835\uc758 \uc0ac\uc9c4\uc5d0 \ub0a8\uc740 \ud2b8\ub798\ubcf4\uc774\uc758 \ubaa8\uc591\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/canada-dog-travois/index.html", "image": "../media/canada-dog-travois.jpg", "alt": "1910\ub144 \ubb34\ub835 \uce90\ub098\ub2e4 \ub0a8\ubd80 \uc568\ubc84\ud0c0\uc758 \uce74\uc774\ub098\uc774 \uc0ac\ub78c\ub4e4\uacfc \uac1c\uac00 \ub044\ub294 \ud2b8\ub798\ubcf4\uc774\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc5ed\uc0ac \uc0ac\uc9c4.", "text": "\ubc14\ud034 \uc5c6\uc774 \uc9d0\uc744 \uc62e\uae30\ub358 \uae34 \ub450 \uac1c\uc758 \ub9c9\ub300 \uce90\ub098\ub2e4\uc758 \uc61b \uc0ac\uc9c4 \uc18d \uac1c\uc640 \uc6b4\ubc18 \ub3c4\uad6c 1910\ub144 \ubb34\ub835\uc758 \uc0ac\uc9c4\uc5d0 \ub0a8\uc740 \ud2b8\ub798\ubcf4\uc774\uc758 \ubaa8\uc591\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc0ac\uc9c4 \uc18d \uc0ac\ub78c\ub4e4 \uacc1\uc5d0 \uac1c\ub4e4\uc774 \uc11c \uc788\ub2e4. \ub208\uae38\uc744 \uc544\ub798\ub85c \uc62e\uae30\uba74 \uac1c\uc758 \ubab8\uc5d0\uc11c \ub4a4\ucabd\uc73c\ub85c \uae38\uac8c \uc774\uc5b4\uc9c0\ub294 \ub9c9\ub300\uac00 \ubcf4\uc778\ub2e4. \ubc14\ud034 \ub2ec\ub9b0 \uc218\ub808\ub3c4, \uaca8\uc6b8 \ub208 \uc704\uc758 \uc370\ub9e4\ub3c4 \uc544\ub2cc \ubaa8\uc591\uc774\ub2e4. OpenStax\ub294 \uc774\ub97c \uce74\uc774\ub098\uc774 \uc5ec\uc131\ub4e4\uacfc \uac1c\uac00 \ub044\ub294 \ud2b8\ub798\ubcf4\uc774\uc758 \ubaa8\uc2b5\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \uc0ac\uc9c4\uc740 \uc624\ub298\ub0a0 \uce90\ub098\ub2e4 \ub0a8\ubd80 \uc568\ubc84\ud0c0\uc5d0 \ud574\ub2f9\ud558\ub294 \uc9c0\uc5ed\uc5d0\uc11c 1910\ub144 \ubb34\ub835 \ucd2c\uc601\ub41c \uc790\ub8cc\ub2e4. \ud2b8\ub798\ubcf4\uc774\ub294 \ub450 \uac1c\uc758 \uae34 \ub9c9\ub300\ub97c \uc9d0\uc744 \uc5b9\ub294 \ubd80\ubd84\uacfc \uc5f0\uacb0\ud55c \uc6b4\ubc18 \ub3c4\uad6c\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c\ub3c4 \uae38\uac8c \ubed7\uc740 \uc120\ub4e4\uacfc \uadf8 \uc0ac\uc774\uc5d0 \ub193\uc778 \uc9d0\uc758 \uc790\ub9ac\ub97c \ucc3e\uc544\ubcfc \uc218 \uc788\ub2e4. \ubc14\ud034\uac00 \ubcf4\uc5ec\uc57c \uc6b4\ubc18 \ub3c4\uad6c\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \ucc98\uc74c\uc5d0\ub294 \uae30\ub2a5\uc744 \ub193\uce60 \uc218 \uc788\ub2e4. \uc5b4\ub5a4 \uac83\uc744 \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ud574 \ud568\uaed8 \uc6c0\uc9c1\uc774\uac8c \ud588\ub294\uc9c0\ub97c \ubcf4\uba74 \ubaa8\uc591\uc774 \ub2e4\uc2dc \uc77d\ud78c\ub2e4. \ubcf5\uc7a1\ud55c \uae30\uacc4 \ubd80\ud488\uc774 \uc788\uc5b4\uc57c\ub9cc \uc9d0\uc744 \uc62e\uae38 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc774 \uc0ac\uc9c4\uc758 \uac1c\ub294 \uc0ac\ub78c \uacc1\uc5d0\uc11c \uc774\ub3d9\uacfc \uc6b4\ubc18\uc5d0 \ucc38\uc5ec\ud558\ub294 \ub3d9\ubb3c\uc774\ub2e4. \ubc18\ub824\ub3d9\ubb3c\uc758 \ucd08\uc0c1\uc73c\ub85c\ub9cc \ubcf4\uc558\uc744 \ub54c\uc640\ub294 \ub2e4\ub978 \uad00\uacc4\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \uad50\uc7ac\ub294 \uac1c\uac00 \uc0ac\ub78c\uc758 \uc5ec\ub7ec \ud65c\ub3d9\uc5d0\uc11c \ub9e1\uc740 \uc5ed\ud560 \uac00\uc6b4\ub370 \uc6b4\ubc18\ub3c4 \ud568\uaed8 \uc18c\uac1c\ud55c\ub2e4. \ub2e4\ub9cc \uc774 \ud55c \uc7a5\uc744 \ubcf4\uace0 \uac1c\uac00 \uc5bc\ub9c8\ub098 \ubb34\uac70\uc6b4 \uc9d0\uc744 \uc5b4\ub5a4 \uac70\ub9ac\uae4c\uc9c0 \uc62e\uacbc\ub294\uc9c0 \uacc4\uc0b0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc2e4\uc81c \ubcf4\uc774\ub294 \uc7a5\uce58\uc640 \uae30\ub85d\ub41c \uc4f0\uc784\uc744 \uad6c\ubd84\ud574 \uc77d\ub294 \ud3b8\uc774 \uc88b\ub2e4. \ub113\uc740 \uac08\ub3cc\ucc98\ub7fc \ubcf4\uc774\ub294 \uc7a5\uce58\uac00 \uc544\ub2c8\ub77c \uae38\uac8c \ubed7\uc740 \ub450 \uc120\uacfc \uadf8 \uc0ac\uc774\uc758 \uc801\uc7ac \uacf5\uac04\uc744 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc55e\ucabd\uc5d0\uc11c \ub04c\uace0 \ub4a4\ucabd\uc774 \ub545\uc744 \ub530\ub77c \uc6c0\uc9c1\uc774\uba74 \uc9d0\uc744 \ub098\ub974\ub294 \uae38\uc774 \uc0dd\uae34\ub2e4. \ubc14\ud034\uc640 \ucd95\uc774 \uc5c6\ub294 \ud615\ud0dc\ub77c\ub3c4 \uc5f0\uacb0\ub41c \ub9c9\ub300\uc640 \uc9d0\uc758 \uc790\ub9ac\ub97c \ud1b5\ud574 \uc5ed\ud560\uc744 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc6b4\ubc18 \ub3c4\uad6c\ub97c \uc54c\uc544\ubcf4\ub294 \uae30\uc900\uc744 \uc870\uae08 \ub113\ud600 \uc8fc\ub294 \ubb3c\uac74\uc774\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4\ub9cc\uc73c\ub85c \uc5b4\ub5a4 \uc7ac\ub8cc\uac00 \uc5bc\ub9c8\ub098 \uac15\ud558\uace0 \uc5b4\ub290 \uc9c0\ud615\uc5d0 \uac00\uc7a5 \uc801\ud569\ud588\ub294\uc9c0 \uc218\uce58\ub85c \ud3c9\uac00\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc7a5\uce58\ub97c \uc774\ub8e8\ub294 \ud615\ud0dc\uc640 \uc790\ub8cc\uac00 \uc54c\ub824 \uc8fc\ub294 \uc4f0\uc784\uc744 \uba3c\uc800 \ubcf4\ub294 \uac83\uc774\ub2e4. \uc775\uc219\ud55c \uc218\ub808\uac00 \uc5c6\ub2e4\ub294 \uc774\uc720\ub85c \ubd80\uc871\ud55c \ub3c4\uad6c\ub77c\uace0 \uc815\ud558\uae30\ubcf4\ub2e4 \uc5b4\ub5a4 \ud589\ub3d9\uc744 \uac00\ub2a5\ud558\uac8c \ud588\ub294\uc9c0 \ubb3b\ub294 \ud3b8\uc774 \uc774\ud574\uc5d0 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uc0ac\uc9c4 \uc18d \uac1c\ub294 \ub2e8\uc21c\ud788 \uc0ac\ub78c \uacc1\uc5d0 \uc788\ub294 \ub3d9\ubb3c\uc774 \uc544\ub2c8\ub77c \uc6b4\ubc18 \ub3c4\uad6c\uc640 \uad00\uacc4\ub97c \ub9fa\uace0 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc774 \uc7a5\uba74\uc744 \uc0ac\ub78c\uacfc \uac1c\uac00 \ub098\ub204\uc5b4 \uc628 \ud65c\ub3d9\uc758 \uc0ac\ub840\ub85c \uc18c\uac1c\ud55c\ub2e4. \ub3d9\ubb3c\uc758 \uc5ed\ud560\uc744 \uc624\ub298\uc758 \ubc18\ub824 \uacbd\ud5d8 \ud558\ub098\ub85c\ub9cc \uc0dd\uac01\ud558\uba74 \ub193\uce60 \uad00\uacc4\ub2e4. \ud568\uaed8 \uc0b0\ub2e4\ub294 \ub9d0\uc5d0\ub294 \uc2dc\ub300\uc640 \uc7a5\uc18c\uc5d0 \ub530\ub77c \ub2e4\ub978 \uc77c\uc774 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc774 \uc0ac\uc9c4\uc744 \uac1c\uc640 \uc0ac\ub78c\uc758 \ubaa8\ub4e0 \uad00\uacc4\ub97c \ub300\ud45c\ud558\ub294 \uc7a5\uba74\uc73c\ub85c \ub113\ud790 \uc218\ub294 \uc5c6\ub2e4. \uc5bc\ub9c8\ub098 \uc790\uc8fc \uc5b4\ub5a4 \ubb34\uac8c\ub97c \ub098\ub974\uace0 \uc5b4\ub5bb\uac8c \uae38\ub800\ub294\uc9c0\ub294 \ubcc4\ub3c4 \uc815\ubcf4\uac00 \ud544\uc694\ud558\ub2e4. \ud558\ub098\uc758 \uc7a5\uce58\ub97c \ubcf8 \ub4a4 \uc5ec\ub7ec \uc9d1\ub2e8\uc758 \uc0dd\ud65c\uc744 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ubb36\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uad6c\uccb4\uc801\uc778 \uc0ac\ub78c\uacfc \uc7a5\uc18c\ub97c \uc790\ub8cc\uc758 \uc124\uba85\ub300\ub85c \ub0a8\uaca8 \ub450\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \uad50\uc7ac\ub294 \uc0ac\uc9c4\uc758 \uc778\ubb3c\uc744 \uce74\uc774\ub098\uc774 \uc5ec\uc131\uc73c\ub85c, \uc7a5\uc18c\ub97c \ud604\uc7ac \uce90\ub098\ub2e4 \ub0a8\ubd80 \uc568\ubc84\ud0c0\uc5d0 \ud574\ub2f9\ud558\ub294 \uc9c0\uc5ed\uc73c\ub85c \uc18c\uac1c\ud558\uba70 \ucd2c\uc601 \uc2dc\uae30\ub97c 1910\ub144 \ubb34\ub835\uc73c\ub85c \uc801\ub294\ub2e4. \uc774 \ub2e8\uc11c\ub4e4\uc740 \uc0ac\uc9c4\uc744 \uc774\ub984 \uc5c6\ub294 \uc61b \ubd81\ubbf8\uc758 \uc7a5\uba74\uc73c\ub85c \ub9cc\ub4e4\uc9c0 \uc54a\uac8c \ud55c\ub2e4. \uc0ac\ub78c\uacfc \ub3c4\uad6c\uc5d0\ub294 \uad6c\uccb4\uc801\uc778 \uacf5\ub3d9\uccb4\uc640 \uc2dc\uac04\uc758 \ub9e5\ub77d\uc774 \uc788\uc5c8\ub2e4. \ud604\uc7ac\uc758 \uad6d\uac00 \uc774\ub984\uc740 \uc704\uce58\ub97c \ucc3e\uac8c \ub3c4\uc640\uc8fc\uc9c0\ub9cc \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc758 \ubaa8\ub4e0 \uc815\uccb4\uc131\uc744 \uc124\uba85\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc9c0\ub3c4 \uc704\uc758 \uba85\uce6d\uacfc \uacf5\ub3d9\uccb4\uc758 \uc774\ub984\uc744 \ud568\uaed8 \uc77d\uc73c\uba74 \uc870\uae08 \ub354 \uc815\ud655\ud574\uc9c4\ub2e4. \uc624\ub798\ub41c \uc0ac\uc9c4\uc740 \uc2dc\ub300\uc758 \ubcf5\uc7a5\ub9cc \uad6c\uacbd\ud558\ub294 \uc774\ubbf8\uc9c0\uac00 \uc544\ub2c8\ub77c \ub204\uac00 \uc5b4\ub5a4 \ud658\uacbd\uc5d0\uc11c \ubb34\uc5c7\uc744 \ud588\ub294\uc9c0 \ubb3b\ub294 \uae30\ub85d\uc73c\ub85c \ub9cc\ub0a0 \uc218 \uc788\ub2e4. \uba3c\uc800 \ub9c9\ub300\uc758 \ub05d\uacfc \uc9d0\uc744 \ub193\ub294 \ubd80\ubd84\uc744 \uc0b4\ud53c\uace0, \ub2e4\uc74c\uc5d0 \uadf8 \uc7a5\uce58\uc640 \uac1c\uc758 \ubab8\uc774 \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ub418\ub294\uc9c0 \ub208\uc73c\ub85c \ub530\ub77c\uac00 \ubcf4\uc790. \ubb3c\uac74\uc758 \uc804\uccb4 \uae30\ub2a5\uc744 \ud55c\ub208\uc5d0 \uc54c\uae30 \uc5b4\ub824\uc6b8 \ub54c\uc5d0\ub294 \uc811\uc810\uc744 \ucc3e\ub294 \uac83\uc774 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uc0ac\ub78c\uc774 \uc11c \uc788\ub294 \uc790\ub9ac\uc640 \ub3c4\uad6c\uc758 \ubc29\ud5a5\uc744 \ud568\uaed8 \ubcf4\uba74 \uc774\ub3d9\uc758 \uac00\ub2a5\uc131\uc774 \uc870\uae08 \uad6c\uccb4\uc801\uc73c\ub85c \ub290\uaef4\uc9c4\ub2e4. \uc0ac\uc9c4\uc774 \uc815\uc9c0\ud55c \uc0c1\ud0dc\ub97c \ubcf4\uc5ec \uc900\ub2e4\uace0 \ud574\uc11c \uadf8 \ubb3c\uac74\ub3c4 \uc6d0\ub798 \uac00\ub9cc\ud788 \ub193\uc5ec \uc788\ub358 \uac83\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uc6b4\ubc18\uc774\ub77c\ub294 \ud589\ub3d9\uc744 \uc704\ud574 \ub9cc\ub4e4\uc5c8\uc73c\ub098 \ud654\uba74\uc5d0\ub294 \ud55c\uc21c\uac04\ub9cc \ub0a8\uc558\ub2e4. \uadf8 \uc55e\ub4a4\ub97c \uc0c1\uc0c1\ud558\ub418 \uae30\ub85d\ub418\uc9c0 \uc54a\uc740 \uac70\ub9ac\uc640 \ub178\ub3d9\ub7c9\uc744 \uc0ac\uc2e4\ucc98\ub7fc \uc4f0\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubc14\ud034 \uc5c6\uc774 \uc6c0\uc9c1\uc774\ub294 \uae34 \ub450 \ub9c9\ub300\ub294 \uc775\uc219\ud558\uc9c0 \uc54a\uc740 \uae30\uc220\uc744 \ub0ae\ucd94\uc5b4 \ubcf4\uc9c0 \uc54a\uace0 \uc77d\ub294 \uc5f0\uc2b5\uc774 \ub41c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc0ac\uc9c4\uc740 \ud2b9\uc815 \uc2dc\uae30\uc758 \uc790\ub8cc\ub2e4. \uc624\ub298\ub0a0 \uce74\uc774\ub098\uc774 \uacf5\ub3d9\uccb4\uc758 \uc0dd\ud65c \uc804\uccb4\ub97c \uc774 \ubaa8\uc2b5 \ud558\ub098\ub85c \ub300\uc2e0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc624\ub798\ub41c \uc0ac\uc9c4\uc744 \ubcfc \ub54c\ub294 \uadf8\ub54c\uc758 \uc7a5\uba74\uc774\ub77c\ub294 \uc790\ub9ac\ub97c \ud568\uaed8 \ub0a8\uaca8 \ub450\uc5b4\uc57c \ud55c\ub2e4. \uadf8 \uc548\uc5d0\uc11c\ub3c4 \uc791\uc740 \ubc1c\uacac\uc740 \uac00\ub2a5\ud558\ub2e4. \ub298 \ubcf4\ub358 \ubc14\ud034\uac00 \uc5c6\ub294\ub370\ub3c4 \uc9d0\uc744 \ub193\uc744 \uc790\ub9ac\uc640 \ub04c\uace0 \uac08 \ubc29\ubc95\uc774 \uc788\ub2e4. \uae34 \ub450 \uac1c\uc758 \ub9c9\ub300\ub97c \uc54c\uc544\ubcf4\ub294 \uc21c\uac04 \uc0ac\uc9c4 \uc18d \uc120\ub4e4\uc774 \ub2e8\uc21c\ud55c \ubc30\uacbd\uc5d0\uc11c \uc0dd\ud65c\uc758 \ub3c4\uad6c\ub85c \ubc14\ub010\ub2e4."}, {"id": "canadian-pacific-railway-workers-and-belonging", "title": "\uce90\ub098\ub2e4 \ucca0\ub3c4 \u2014 \ub098\ub77c\ub97c \uc787\ub358 \uc120\ub85c \uc704\uc5d0\ub294 \ub204\uac00 \uc788\uc5c8\uc744\uae4c", "summary": "\ud0dc\ud3c9\uc591 \ucca0\ub3c4\uc758 \uc644\uacf5\uacfc \uc774\uc8fc \ub178\ub3d9, \uba54\ud2f0\uc2a4 \uacf5\ub3d9\uccb4\uc640 \ucc28\ubcc4\uc758 \uc5ed\uc0ac\ub97c \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/canadian-pacific-railway-workers-and-belonging/index.html", "image": "../media/canadian-pacific-railway-workers-and-belonging.png", "alt": "\uc0b0\uc545 \uc9c0\ud615\uc5d0\uc11c \uc120\ub85c\ub97c \ub193\ub294 \uc911\uad6d\uacc4\uc640 \ub2e4\ub978 \ucca0\ub3c4 \ub178\ub3d9\uc790\ub4e4\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uce90\ub098\ub2e4 \ucca0\ub3c4 \u2014 \ub098\ub77c\ub97c \uc787\ub358 \uc120\ub85c \uc704\uc5d0\ub294 \ub204\uac00 \uc788\uc5c8\uc744\uae4c \ub450 \ubc14\ub2e4\ub97c \uc5f0\uacb0\ud55c \uc57d\uc18d\uacfc \uc911\uad6d\uc778 \ub178\ub3d9\uc790\ub4e4\uc758 \ub2e4\ub978 \ubbf8\ub798 \ud0dc\ud3c9\uc591 \ucca0\ub3c4\uc758 \uc644\uacf5\uacfc \uc774\uc8fc \ub178\ub3d9, \uba54\ud2f0\uc2a4 \uacf5\ub3d9\uccb4\uc640 \ucc28\ubcc4\uc758 \uc5ed\uc0ac\ub97c \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc9c0\ub3c4 \uc704\uc5d0 \uae34 \uc120\uc744 \uadf8\uc73c\uba74 \ub098\ub77c\uac00 \ud558\ub098\ub85c \uc774\uc5b4\uc9c4 \uac83\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uce90\ub098\ub2e4\uc758 \ub3d9\ucabd\uacfc \uc11c\ucabd\uc744 \uc787\ub294 \ucca0\ub3c4\ub3c4 \uadf8\ub807\uac8c \uae30\uc5b5\ud558\uae30 \uc27d\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \uc120\uc774 \ub193\uc778 \ub545\uc5d0\ub294 \uc774\ubbf8 \uc0ac\ub78c\uc774 \uc0b4\uc558\uace0, \uadf8 \uc120\uc744 \ub9cc\ub4e0 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uac19\uc740 \ubbf8\ub798\uac00 \uc57d\uc18d\ub41c \uac83\ub3c4 \uc544\ub2c8\uc5c8\ub2e4. \uce90\ub098\ub2e4 \ud0dc\ud3c9\uc591 \ucca0\ub3c4\ub294 \uac70\ub300\ud55c \uad6d\uac00 \uc0ac\uc5c5\uc778 \ub3d9\uc2dc\uc5d0 \uba3c \uacf3\uc5d0\uc11c \uc77c\ud558\ub7ec \uc628 \uc0ac\ub78c\ub4e4\uc758 \uc0dd\ud65c\uc774\uc5c8\ub2e4. \uc624\ud508\uc2a4\ud0dd\uc2a4\uc758 \uc0b0\uc5c5\ud654\uc640 \uc774\uc8fc \uc5ed\uc0ac \uc124\uba85\uc744 \ud568\uaed8 \uc77d\uc73c\uba70, \uc644\uacf5\uc774\ub77c\ub294 \ud55c \ub2e8\uc5b4 \uc548\uc5d0 \ub2f4\uae34 \uc11c\ub85c \ub2e4\ub978 \uc2dc\uac04\uc744 \uc0b4\ud3b4\ubcf8\ub2e4. 1867\ub144 \uce90\ub098\ub2e4 \uc790\uce58\ub839\uc774 \ub9cc\ub4e4\uc5b4\uc9c4 \ub4a4 \uc11c\ucabd\uacfc\uc758 \uc5f0\uacb0\uc740 \uc911\uc694\ud55c \uacfc\uc81c\uac00 \ub41c\ub2e4. 1871\ub144 \ube0c\ub9ac\ud2f0\uc2dc\uceec\ub7fc\ube44\uc544\uac00 \ud569\ub958\ud560 \ub54c\uc5d0\ub294 \ub3d9\ucabd\uacfc \uc11c\ucabd\uc744 \ucca0\ub3c4\ub85c \uc787\uaca0\ub2e4\ub294 \uc57d\uc18d\uc774 \ud3ec\ud568\ub41c\ub2e4. \ub113\uc740 \uc601\ud1a0\ub97c \ud589\uc815\uc801\uc778 \uc9c0\ub3c4\uc5d0 \ub123\ub294 \uc77c\uacfc \uc2e4\uc81c \uc0ac\ub78c\uc774 \uc624\uac08 \uc218 \uc788\uac8c \ub9cc\ub4dc\ub294 \uc77c\uc774 \uc5f0\uacb0\ub41c \uac83\uc774\ub2e4. \uc57d\uc18d\uc5d0\ub294 \uae30\ud55c\ub3c4 \uc788\uc5c8\uc9c0\ub9cc \uacf5\uc0ac\ub294 \uadf8 \uc2dc\uac04\ud45c\ub300\ub85c \uac04\ub2e8\ud788 \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc2e4\uc81c \uc5f0\uacb0\uc740 1885\ub144\uc5d0 \uc774\ub8e8\uc5b4\uc9c4\ub2e4. \ub2ec\ub825\uc5d0 \uc801\uc740 \ubaa9\ud45c\uc640 \uc0b0\uc744 \ud1b5\uacfc\ud558\ub294 \ud604\uc2e4 \uc0ac\uc774\uc5d0\ub294 \uac70\ub9ac\uac00 \uc788\uc5c8\ub2e4. \ucca0\ub3c4\ub294 \uae30\uc220\uc758 \ub2a5\ub825\ub9cc\uc774 \uc544\ub2c8\ub77c \uc790\uae08\uacfc \uc815\uce58\uc801\uc778 \uacb0\uc815\uc744 \uc624\ub798 \uc774\uc5b4 \uac00\uc57c \uac00\ub2a5\ud55c \uc0ac\uc5c5\uc774\uc5c8\ub2e4. \ub2f9\uc2dc\uc758 \uad6d\uac00 \uc0ac\uc5c5\uc744 \uc124\uba85\ud560 \ub54c \ub113\uc740 \ub545\uc744 \uc8fc\uc778 \uc5c6\ub294 \uacf5\uac04\ucc98\ub7fc \ud45c\ud604\ud558\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uad50\uc7ac\uac00 \uc18c\uac1c\ud558\ub294 \ub8e8\ud37c\uce20\ub79c\ub4dc\uc5d0\ub294 \uba54\ud2f0\uc2a4\ub97c \ube44\ub86f\ud55c \uacf5\ub3d9\uccb4\uac00 \uc0b4\uace0 \uc788\uc5c8\ub2e4. \uba54\ud2f0\uc2a4\ub294 \uc6d0\uc8fc\ubbfc\uacfc \uc720\ub7fd\uacc4\uc758 \uc5ed\uc0ac\uc801 \uad00\uacc4 \uc18d\uc5d0\uc11c \uace0\uc720\ud55c \uacf5\ub3d9\uccb4\ub97c \uc774\ub8e8\uc5b4 \uc628 \uc0ac\ub78c\ub4e4\uc774\ub2e4. \uc0c8 \uacbd\uacc4\uc640 \uce21\ub7c9\uc740 \uadf8\ub4e4\uc5d0\uac8c \uc0dd\ud65c\uacfc \ubb38\ud654\uc758 \ubb38\uc81c\uc600\ub2e4. \ub8e8\uc774 \ub9ac\uc5d8\uacfc \uba54\ud2f0\uc2a4\uac00 \uad8c\ub9ac\uc640 \ud559\uad50, \ud1a0\uc9c0\ub97c \ub450\uace0 \ud611\uc0c1\ud558\uace0 \uc800\ud56d\ud55c \uc0ac\uc815\ub3c4 \ud568\uaed8 \ub4f1\uc7a5\ud55c\ub2e4. \uc774\ub4e4\uc744 \ucca0\ub3c4\uc758 \uc9c4\ubcf4\ub97c \ubc29\ud574\ud55c \ubc30\uacbd \uc778\ubb3c\ub85c\ub9cc \ub193\uc73c\uba74 \ubb34\uc5c7\uc744 \uc783\uc744\uae4c \ub450\ub824\uc6cc\ud588\ub294\uc9c0 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ud558\ub098\uc758 \ub098\ub77c\uac00 \ub113\uc5b4\uc9c0\ub294 \uadf8\ub9bc\uacfc \uc774\ubbf8 \uc0b4\ub358 \uc0ac\ub78c\ub4e4\uc774 \uc790\uae30 \uc0b6\uc744 \uc9c0\ud0a4\ub824\ub294 \uadf8\ub9bc\uc740 \uac19\uc740 \uc9c0\ub3c4\ub97c \ub2e4\ub974\uac8c \uc77d\ub294\ub2e4. \uc11c\ubd80\uc758 \uacf5\uc0ac\uc5d0\ub294 \uc720\ub7fd\uacc4\uc640 \uc911\uad6d\uacc4 \uc774\uc8fc \ub178\ub3d9\uc790\ub4e4\uc774 \ucc38\uc5ec\ud588\ub2e4. \uc120\ub85c\ub77c\ub294 \ub9d0\uc740 \uace7\uac8c \ub193\uc778 \ub450 \uc904\uc758 \uc1e0\ub97c \ub5a0\uc62c\ub9ac\uac8c \ud558\uc9c0\ub9cc, \uadf8 \uc774\uc804\uc5d0 \ub545\uc744 \uace0\ub974\uace0 \uc790\uc7ac\ub97c \uc62e\uae30\uace0 \uae38\uc744 \ub0b4\ub294 \uc77c\uc774 \uc788\uc5c8\ub2e4. \uc5b4\ub5a4 \uc791\uc5c5\uc774 \uae30\uacc4\ub85c \uac00\ub2a5\ud574\uc838\ub3c4 \uadf8 \uae30\uacc4\ub97c \uc6c0\uc9c1\uc77c \uc0ac\ub78c\uacfc \uc790\uc7ac\ub97c \uacf5\uae09\ud560 \uc0ac\ub78c\uc740 \ud544\uc694\ud588\ub2e4. \uc644\uacf5 \uc0ac\uc9c4\uc5d0\ub294 \uc0c1\uc9d5\uc801\uc778 \uc778\ubb3c \uba87 \uba85\uc774 \uc911\uc2ec\uc5d0 \uc11c\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uc2e4\uc81c \uc791\uc5c5\uc740 \uadf8\ub7f0 \uc0ac\uc9c4 \ud55c \uc7a5\ubcf4\ub2e4 \uae34 \uc2dc\uac04\uacfc \ub9ce\uc740 \uc190\uc744 \uc694\uad6c\ud55c\ub2e4. \uc5ec\uae30\uc11c\ub294 \ucd9c\ucc98\uac00 \ucda9\ubd84\ud558\uc9c0 \uc54a\uc740 \uc0ac\ub9dd\uc790 \uc22b\uc790\ub098 \ud2b9\uc815 \ub178\ub3d9\uc790\uc758 \ub300\ud654\ub97c \ub367\ubd99\uc774\uc9c0 \uc54a\ub294\ub2e4. \uac70\ub300\ud55c \uc131\ucde8\ub97c \uae30\uc5b5\ud558\ub294 \ud2c0 \uc548\uc5d0\uc11c \ub204\uac00 \uc27d\uac8c \ube60\uc9c0\ub294\uc9c0 \uc0b4\ud53c\ub294 \uac83\uc774 \uba3c\uc800\ub2e4. 19\uc138\uae30 \uc911\uad6d\uc778\ub4e4\uc758 \ud574\uc678 \uc774\uc8fc\ub294 \ucca0\ub3c4\ud68c\uc0ac \ud558\ub098\uc758 \ud544\uc694\ub9cc\uc73c\ub85c \uc2dc\uc791\ub418\uc9c0 \uc54a\uc558\ub2e4. \uac00\ub09c\uacfc \uc804\uc7c1, \ub18d\uc5c5\uc758 \uc5b4\ub824\uc6c0 \uc18d\uc5d0\uc11c \ub2e4\ub978 \uc9c0\uc5ed\uc758 \uc77c\uc790\ub9ac\ub97c \ucc3e\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc788\uc5c8\ub2e4. \uc624\ud508\uc2a4\ud0dd\uc2a4\ub294 \uc911\uad6d \ub0a8\ubd80\uc5d0\uc11c \ud558\uc640\uc774\uc640 \ubd81\ubbf8, \ub3d9\ub0a8\uc544\uc2dc\uc544\uc640 \ub0a8\ubbf8 \ub4f1\uc73c\ub85c \ubed7\uc5b4 \uac04 \uc5ec\ub7ec \uae38\uc744 \uc124\uba85\ud55c\ub2e4. \uce90\ub098\ub2e4\uc758 \ube0c\ub9ac\ud2f0\uc2dc\uceec\ub7fc\ube44\uc544\ub3c4 \uadf8 \uac00\uc6b4\ub370 \ud558\ub098\uc600\ub2e4. \uc5b4\ub5a4 \uc0ac\ub78c\uc5d0\uac8c \ucca0\ub3c4\ub294 \uad6d\uac00\ub97c \uac74\uc124\ud558\ub294 \uc0ac\uba85\ubcf4\ub2e4 \uc0dd\uacc4\ub97c \uc704\ud55c \uc77c\uc774\uc5c8\uc744 \uc218 \uc788\ub2e4. \uc784\uae08\uc744 \ubc8c\uace0 \uac00\uc871\uc744 \ub3d5\uace0 \ub354 \ub098\uc740 \uc0dd\ud65c\uc744 \ucc3e\uc73c\ub824\ub294 \uae30\ub300\ub294 \uad6d\uac00\uc758 \ud64d\ubcf4 \ubb38\uad6c\uc640 \uac19\uc9c0 \uc54a\ub2e4. \uac19\uc740 \uc120\ub85c \uc704\uc5d0 \uc788\uc5c8\uc5b4\ub3c4 \uadf8 \uae38\uc744 \uc120\ud0dd\ud55c \uc774\uc720\ub294 \uc5ec\ub7ec \uac00\uc9c0\uc600\ub2e4. \ub178\ub3d9\ub825\uc774 \ud544\uc694\ud558\ub2e4\ub294 \ub9d0\uc774 \uadf8 \uc0ac\ub78c\uc744 \ub3d9\ub4f1\ud55c \uc774\uc6c3\uc73c\ub85c \ubc1b\uc544\ub4e4\uc774\uaca0\ub2e4\ub294 \ub9d0\uc740 \uc544\ub2c8\ub2e4. \ucca0\ub3c4\uac00 \uc644\uacf5\ub41c 1885\ub144 \uce90\ub098\ub2e4\ub294 \uc911\uad6d\uc778 \ub178\ub3d9 \uc774\uc8fc\uc790\uc5d0\uac8c \uc138\uae08\uc744 \ubd80\uacfc\ud588\ub2e4. \uad50\uc7ac\ub294 \ucc98\uc74c\uc758 \uae08\uc561\uc774 50\ub2ec\ub7ec\uc600\uace0, \uc77c\ubd80 \uc2e0\ubd84\uc5d0\ub294 \uc608\uc678\uac00 \uc788\uc5c8\uc73c\uba70 \ub4a4\uc5d0 \uc138\uae08\uc774 \ub354 \uc62c\ub77c\uac14\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uacf5\uc0ac\uc640 \uc138\uae08\uc774 \uac19\uc740 \ud574\ub77c\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc815\ucc45\uc758 \uc6d0\uc778\uc744 \ud55c \ubb38\uc7a5\uc73c\ub85c \uc815\ub9ac\ud560 \uc218\ub294 \uc5c6\ub2e4. \uadf8\ub798\ub3c4 \ub098\ub77c\ub97c \uc787\ub294 \ub370 \uae30\uc5ec\ud55c \uc0ac\ub78c\uc5d0\uac8c \ub4e4\uc5b4\uc624\ub294 \ube44\uc6a9\uc744 \ud2b9\ubcc4\ud788 \uc694\uad6c\ud588\ub2e4\ub294 \ub300\ube44\ub294 \ubd84\uba85\ud558\ub2e4. \uad6d\uac00\uc758 \ud544\uc694\uc5d0 \uc720\uc6a9\ud55c \uc0ac\ub78c\uc778 \uac83\uacfc \uc0ac\ud68c\uc5d0 \uc18d\ud560 \uc790\uaca9\uc744 \uc778\uc815\ubc1b\ub294 \uac83\uc740 \ub2e4\ub978 \ubb38\uc81c\ub85c \ucde8\uae09\ub418\uc5c8\ub2e4. \uc911\uad6d\uc778\ub4e4\uc774 \ubaa8\ub450 \uac19\uc740 \uacc4\uc57d\uacfc \uc9c1\uc5c5, \uac19\uc740 \ubaa9\uc801\uc744 \uac00\uc84c\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \ucca0\ub3c4 \uc678\uc5d0\ub3c4 \uad11\uc0b0\uacfc \ub18d\uc5c5, \uc11c\ube44\uc2a4\uc5c5 \ub4f1\uc5d0\uc11c \uc77c\ud588\ub2e4. \uc5b4\ub5a4 \uc9c0\uc5ed\uc758 \uace0\uc6a9\uc8fc\uac00 \ub0ae\uc740 \uc784\uae08\uc744 \uae30\ub300\ud588\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc774\uc8fc\ubbfc\uc758 \ud0c0\uace0\ub09c \uc131\ud5a5\uc73c\ub85c \uc124\uba85\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc870\uac74\uacfc \ud611\uc0c1\ub825\uc774 \ub2ec\ub790\ub358 \uc0ac\ud68c\uc758 \ubb38\uc81c\ub2e4. \ub610\ud55c \uc5ec\ub7ec \ub098\ub77c\uc758 \ucc28\ubcc4 \uc815\ucc45\uc744 \ud558\ub098\ub85c \uc11e\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \ubbf8\uad6d\uc758 \uc911\uad6d\uc778 \ubc30\uc81c\uc640 \uce90\ub098\ub2e4\uc758 \uc138\uae08\uc740 \uad00\ub828\ub41c \uc2dc\ub300\uc758 \ud604\uc0c1\uc774\uc9c0\ub9cc \uac19\uc740 \ubc95\uc740 \uc544\ub2c8\ub2e4. \ucd9c\ubc1c\uc9c0\uac00 \uac19\uc544\ub3c4 \ub3c4\ucc29\uc9c0\uc758 \uc81c\ub3c4\ub294 \ub2e4\ub974\uac8c \uc0b6\uc744 \ubc14\uafb8\uc5c8\ub2e4. \uc774\uc8fc\ub77c\ub294 \ud070 \ub9d0 \uc548\uc5d0\ub3c4 \uad6d\uacbd\ub9c8\ub2e4 \ub2e4\ub978 \ubb38\ud131\uc774 \uc788\uc5c8\ub2e4. \ucca0\ub3c4\ub294 \uc0ac\ub78c\uacfc \ubb3c\uac74\uc774 \uc6c0\uc9c1\uc77c \uae38\uc744 \ub113\ud788\uace0 \ub0b4\ub959 \uc815\ucc29\uacfc \uc0b0\uc5c5 \ubc1c\uc804\uc744 \ub3c4\uc654\ub2e4. \uc11c\ub85c \uba40\ub9ac \ub5a8\uc5b4\uc9c4 \uc9c0\uc5ed\uc744 \ud558\ub098\uc758 \uacbd\uc81c\uc801\uc778 \uad00\uacc4\ub85c \ubb36\ub294 \ud798\uc774 \uc788\uc5c8\ub2e4. \uc644\uacf5\uc744 \uc911\uc694\ud558\uac8c \uae30\uc5b5\ud558\ub294 \ub370\uc5d0\ub294 \uc774\uc720\uac00 \uc788\ub2e4. \uadf8 \uc131\uacfc\ub97c \uc778\uc815\ud55c\ub2e4\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc0c1\uc2e4\uacfc \ucc28\ubcc4\uc744 \ud568\uaed8 \ubcfc \uc218 \uc5c6\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ud788\ub824 \ub458\uc744 \ud568\uaed8 \ub193\uc744 \ub54c \uc5ed\uc0ac\ub294 \ub354 \uad6c\uccb4\uc801\uc774 \ub41c\ub2e4. \ub204\uad6c\uc5d0\uac8c \uc2dc\uac04\uc774 \uc904\uc5c8\uace0 \ub204\uad6c\uc5d0\uac8c \ube44\uc6a9\uc774 \uc0dd\uacbc\ub294\uc9c0, \ub204\uac00 \ub545\uc744 \uc5bb\uace0 \ub204\uac00 \uad8c\ub9ac\ub97c \uc9c0\ud0a4\ub824 \ud588\ub294\uc9c0 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \ubc1c\uc804\uc774\ub77c\ub294 \ub9d0\uc774 \ud55c \uc0ac\ub78c\uc5d0\uac8c \uc88b\uc740 \uc18c\uc2dd\uc774\uc5b4\ub3c4 \ubaa8\ub450\uc5d0\uac8c \uac19\uc740 \uc18c\uc2dd\uc774\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc0ac\uc2e4\uc774 \ubcf4\uc778\ub2e4. \uce90\ub098\ub2e4 \ud0dc\ud3c9\uc591 \ucca0\ub3c4\ub294 \ub450 \ubc14\ub2e4\ub97c \uc5f0\uacb0\ud55c \uae38\uc774\uba74\uc11c \uc11c\ub85c \ub2e4\ub978 \uc0b6\uc774 \ub9cc\ub09c \uc790\ub9ac\uc600\ub2e4. \uc720\ub7fd\uacc4\uc640 \uc911\uad6d\uacc4 \ub178\ub3d9\uc790, \uba54\ud2f0\uc2a4\uc640 \uc5ec\ub7ec \uc9c0\uc5ed\uc758 \uc8fc\ubbfc\ub4e4\uc744 \ud558\ub098\uc758 \uc644\uacf5 \uc7a5\uba74\uc73c\ub85c \ud3c9\ud3c9\ud558\uac8c \ub9cc\ub4e4\uc9c0 \uc54a\uc744 \ub54c \uadf8 \uae38\uc758 \uc5ed\uc0ac\ub3c4 \ud48d\ubd80\ud574\uc9c4\ub2e4. \uc9c0\ub3c4\uc5d0 \ub0a8\uc740 \uc120\ubcf4\ub2e4 \uae30\uc5b5\ud574\uc57c \ud560 \uad00\uacc4\uac00 \ub9ce\ub2e4. \ub2e4\uc74c\uc5d0 \ub300\ub959\uc744 \uac00\ub85c\uc9c0\ub974\ub294 \ucca0\ub3c4 \uc0ac\uc9c4\uc744 \ubcf4\uac8c \ub418\uba74 \ub9e8 \ub05d\uc758 \uae30\uad00\ucc28\ub9cc \ubc14\ub77c\ubcf4\uc9c0 \uc54a\uc544\ub3c4 \uc88b\uaca0\ub2e4. \uc0b0 \uc0ac\uc774\uc758 \uae34 \uc120\ub85c\ub97c \ub204\uac00 \ub193\uc558\ub294\uc9c0, \uadf8 \uc0ac\ub78c\ub4e4\uc774 \uc644\uacf5 \ub4a4 \uc5b4\ub290 \ubb38\ud131 \uc55e\uc5d0 \uc130\ub294\uc9c0\ub3c4 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ub098\ub77c\uac00 \uc774\uc5b4\uc84c\ub2e4\ub294 \ubb38\uc7a5\uc740 \uadf8 \uc548\uc758 \uc0ac\ub78c\ub4e4\ub3c4 \ubaa8\ub450 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc774\uc5b4\uc84c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\uc5c8\ub2e4."}, {"id": "canossa-1077-penance-princes-and-power", "title": "\uce74\ub178\uc0ac 1077 \u2014 \uc131\ubb38 \uc55e\uc758 \uc655\uc740 \uc815\ub9d0 \ubaa8\ub4e0 \uac83\uc744 \uc783\uc5c8\uc744\uae4c", "summary": "\ud558\uc778\ub9ac\ud7884\uc138\uc758 \ucc38\ud68c\ub97c \ub3c5\uc77c \uc81c\ud6c4\uc640 \uc11c\uc784\uad8c \uac08\ub4f1, \uc774\ud6c4\uc758 \uad8c\ub825 \ud22c\uc7c1 \uc18d\uc5d0\uc11c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/canossa-1077-penance-princes-and-power/index.html", "image": "../media/canossa-1077-penance-princes-and-power.png", "alt": "\uaca8\uc6b8 \uc131\ubb38 \uc55e\uc5d0\uc11c \uae30\ub2e4\ub9ac\ub294 \ucc38\ud68c\uc790 \ucc28\ub9bc\uc758 \uc655\uacfc \ub3d9\ud589\uc790\ub97c \uadf8\ub9b0 \uce74\ub178\uc0ac \uad00\ub828 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uce74\ub178\uc0ac 1077 \u2014 \uc131\ubb38 \uc55e\uc758 \uc655\uc740 \uc815\ub9d0 \ubaa8\ub4e0 \uac83\uc744 \uc783\uc5c8\uc744\uae4c \uc11c\uc784\uad8c\uacfc \uc81c\ud6c4\uc758 \uc774\ud574\uad00\uacc4, \ucc38\ud68c \ub4a4\uc5d0\ub3c4 \uc774\uc5b4\uc9c4 \uac08\ub4f1 \ud558\uc778\ub9ac\ud7884\uc138\uc758 \ucc38\ud68c\ub97c \ub3c5\uc77c \uc81c\ud6c4\uc640 \uc11c\uc784\uad8c \uac08\ub4f1, \uc774\ud6c4\uc758 \uad8c\ub825 \ud22c\uc7c1 \uc18d\uc5d0\uc11c \uc77d\uc2b5\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ub208 \ub36e\uc778 \uc131\ubb38 \uc55e\uc5d0\uc11c \uad50\ud669\uc758 \uc6a9\uc11c\ub97c \uae30\ub2e4\ub9ac\ub294 \uc655. \uce74\ub178\uc0ac \ud68c\ub3d9\uc740 \uc885\uad50\uac00 \uc655\uad8c\uc744 \uc644\uc804\ud788 \uaebe\uc740 \uc7a5\uba74\uc73c\ub85c \uc790\uc8fc \uc18c\uac1c\ub41c\ub2e4. \uadf8\ub7ec\ub098 1077\ub144\uc758 \uc0ac\uac74\uc744 \uc55e\ub4a4\uc758 \uc815\uce58\uc640 \ud568\uaed8 \ubcf4\uba74 \ub354 \ubcf5\uc7a1\ud558\ub2e4. \uc6a9\uc11c\ub97c \uad6c\ud55c \ub3c5\uc77c \uc655 \ud558\uc778\ub9ac\ud788 4\uc138\ub294 \uc2e0\uc559\uc758 \ubb38\uc81c\uc640 \ud1b5\uce58\uc758 \uc704\uae30\ub97c \ub3d9\uc2dc\uc5d0 \ud480\ub824 \ud588\ub2e4. \uc911\uc138 \uc11c\uc720\ub7fd\uc758 \uc8fc\uad50\ub294 \uc885\uad50 \uc758\uc2dd\ub9cc \ub2f4\ub2f9\ud558\ub294 \uc778\ubb3c\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ud1a0\uc9c0\uc640 \uc7ac\uc0b0\uc744 \uad00\ub9ac\ud558\uace0 \ud1b5\uce58\uc5d0\ub3c4 \ucc38\uc5ec\ud588\ub2e4. \uadf8\ub7ec\ubbc0\ub85c \ub204\uac00 \uc8fc\uad50\ub97c \uace0\ub974\uace0 \uad8c\uc704\uc758 \ud45c\uc9c0\ub97c \uc904 \uc218 \uc788\ub294\uac00\ub294 \uad50\ud68c \ub0b4\ubd80\uc758 \uc608\uc808 \ubb38\uc81c\ub97c \ub118\uc5b4\uc130\ub2e4. \uc655\uc740 \uc790\uc2e0\uc744 \uc9c0\uc9c0\ud560 \uc778\ubb3c\uc744 \uc138\uc6b0\ub824 \ud588\uace0 \uad50\ud68c \uac1c\ud601 \uc138\ub825\uc740 \uc138\uc18d \uad8c\ub825\uc758 \uac04\uc12d\uc744 \uc904\uc774\ub824 \ud588\ub2e4. \uc11c\uc784\uad8c\uc744 \ub458\ub7ec\uc2fc \uac08\ub4f1\uc740 \uc885\uad50\uc640 \uc815\uce58\uac00 \uc6d0\ub798 \uc644\uc804\ud788 \ubd84\ub9ac\ub418\uc5b4 \uc788\ub2e4\uac00 \ucda9\ub3cc\ud55c \uc0ac\uac74\uc774 \uc544\ub2c8\ub2e4. \uc11c\ub85c \uc5bd\ud78c \uad8c\ud55c\uc758 \uacbd\uacc4\ub97c \ub2e4\uc2dc \uc815\ud558\ub824\ub294 \ub2e4\ud23c\uc774\uc5c8\ub2e4. \uc8fc\uad50\uc5d0\uac8c \uc655\uc774 \uc8fc\ub294 \uc790\ub9ac\uc640 \uad50\ud68c\uac00 \uc778\uc815\ud558\ub294 \uc601\uc801 \uad8c\ud55c\uc774 \uacb9\uce58\uba74 \uc5b4\ub290 \ud55c\ucabd\uc758 \uc2b9\uc778\ub9cc\uc73c\ub85c \ucda9\ubd84\ud55c\uc9c0 \ubb38\uc81c\uac00 \uc0dd\uae34\ub2e4. \uc11c\uc784\uad8c \ub17c\uc7c1\uc740 \uc774 \ubcf5\ud569\uc801\uc778 \uc790\ub9ac\ub97c \ub458\ub7ec\uc2fc \uac08\ub4f1\uc774\uc5c8\ub2e4. \ubc18\uc9c0\uc640 \uc9c0\ud321\uc774 \uac19\uc740 \uc0c1\uc9d5\ubb3c\ub3c4 \uc2e4\uc81c \ud1b5\uce58\uc640 \uc7ac\uc0b0\uc758 \ubb38\uc81c\uc5d0\uc11c \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\uc558\ub2e4. \uad50\ud669 \uadf8\ub808\uace0\ub9ac\uc6b0\uc2a4 7\uc138\uc640 \ud558\uc778\ub9ac\ud788\uc758 \uac08\ub4f1\uc774 \uaca9\ud574\uc9c0\uc790, \uc591\ucabd\uc740 \uc0c1\ub300\ub97c \uc778\uc815\ud558\uc9c0 \uc54a\ub294 \ud589\ub3d9\uc73c\ub85c \ub098\uc544\uac14\ub2e4. \uc655\uc744 \uc9c0\uc9c0\ud558\ub294 \uc131\uc9c1\uc790\ub4e4\uc740 \uad50\ud669\uc744 \uacf5\uaca9\ud588\uace0 \uad50\ud669\uc740 \ud558\uc778\ub9ac\ud788\ub97c \ud30c\ubb38\ud588\ub2e4. \uc2e0\uc559 \uacf5\ub3d9\uccb4\uc5d0\uc11c \ubc30\uc81c\ud558\ub294 \uc870\uce58\ub294 \ub2f9\uc2dc \ud1b5\uce58\uc5d0\ub3c4 \uc2ec\uac01\ud55c \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \ud30c\ubb38\uc774 \uace7 \ubaa8\ub4e0 \uc2e0\ud558\uc758 \ud589\ub3d9\uc744 \uc790\ub3d9\uc73c\ub85c \uacb0\uc815\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \uadf8\uac83\uc744 \uc5b4\ub5bb\uac8c \ubc1b\uc544\ub4e4\uc774\uace0 \uc790\uae30 \uc774\ud574\uad00\uacc4\uc640 \uc5f0\uacb0\ud558\ub294\uc9c0\uac00 \uc911\uc694\ud588\ub2e4. \uad50\ud669\uc758 \ub9d0\uc774 \uc815\uce58\uc801 \ud798\uc744 \uac16\uac8c \ub41c \ub370\uc5d0\ub294 \ub3c5\uc77c \uc548\uc758 \uc655\uad8c \ubc18\ub300 \uc138\ub825\uc774 \uc788\uc5c8\ub2e4. \ud558\uc778\ub9ac\ud788\uc5d0 \ubc18\ub300\ud558\ub358 \uc81c\ud6c4\ub4e4\uc740 \uc774 \uae30\ud68c\ub97c \uc774\uc6a9\ud588\ub2e4. \uc655\uc774 \uad50\ud669\uacfc \ud654\ud574\ud558\uc9c0 \ubabb\ud558\uba74 \uc9c0\uc704\ub97c \uc783\uac8c \ub420 \uc218 \uc788\uc5c8\uace0 \ub2e4\ub978 \ud1b5\uce58\uc790\ub97c \uc138\uc6b0\ub294 \ub17c\uc758\ub3c4 \ub098\uc654\ub2e4. \uad50\ud669\uc774 \ub3c5\uc77c\ub85c \uc640\uc11c \ubb38\uc81c\ub97c \ub2e4\ub8e8\uae30 \uc804\uc5d0 \uc655\uc774 \uba3c\uc800 \ud589\ub3d9\ud560 \uc774\uc720\uac00 \uc0dd\uacbc\ub2e4. \uc774\ub54c \ud558\uc778\ub9ac\ud788\ub294 \uc544\uc9c1 \ud669\uc81c \ub300\uad00\uc744 \ubc1b\uc740 \uc0c1\ud0dc\uac00 \uc544\ub2c8\uc5c8\ub2e4. \ud754\ud788 \ud669\uc81c\uc758 \uad74\uc695\uc774\ub77c\uace0 \ubd80\ub974\uc9c0\ub9cc 1077\ub144\uc758 \uc2e0\ubd84\uc744 \uc815\ud655\ud788 \ub9d0\ud558\uba74 \ub3c5\uc77c \uc655\uc774\ub2e4. \ud6d7\ub0a0 \ud669\uc81c\uac00 \ub41c \uc778\ubb3c\uc758 \uce6d\ud638\ub97c \uacfc\uac70\uc758 \ubaa8\ub4e0 \uc21c\uac04\uc5d0 \uadf8\ub300\ub85c \ubd99\uc774\uba74 \uc0ac\uac74\uc758 \ub2e8\uacc4\uac00 \ud750\ub824\uc9c4\ub2e4. \uad50\ud669 \uc5ed\uc2dc \ubaa8\ub4e0 \uc815\uce58\uc801 \uc120\ud0dd\uc744 \uc790\uc720\ub86d\uac8c \ud560 \uc218 \uc788\ub294 \uad00\ucc30\uc790\ub294 \uc544\ub2c8\uc5c8\ub2e4. \ucc38\ud68c\ub97c \ubc1b\uc544\ub4e4\uc774\ub294 \uc885\uad50\uc801 \uc758\ubb34\uc640 \ud558\uc778\ub9ac\ud788\uc5d0 \ubc18\ub300\ud558\ub294 \uc138\ub825\uc758 \uae30\ub300 \uc0ac\uc774\uc5d0\uc11c \ud310\ub2e8\ud574\uc57c \ud588\ub2e4. \uc655\uc774 \uba3c\uc800 \ucc38\ud68c\uc790\ub85c \ucc3e\uc544\uc628 \uc77c\uc740 \uad50\ud669\uc5d0\uac8c\ub3c4 \uc5b4\ub824\uc6b4 \uc0c1\ud669\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \ud558\uc778\ub9ac\ud788\ub294 \uaca8\uc6b8\uc5d0 \uc54c\ud504\uc2a4\ub97c \ub118\uc5b4 \uc774\ud0c8\ub9ac\uc544\ub85c \ud5a5\ud588\ub2e4. \uad50\ud669\uc740 \ud1a0\uc2a4\uce74\ub098\uc758 \ub9c8\ud2f8\ub2e4\uac00 \uac00\uc9c4 \uce74\ub178\uc0ac \uc131\uc5d0 \uba38\ubb3c\uace0 \uc788\uc5c8\ub2e4. \uae30\ub2e4\ub9ac\uace0 \ud310\uc815\uc744 \ubc1b\uae30\ubcf4\ub2e4 \uba3c\uc800 \ub9cc\ub098 \ud654\ud574\ub97c \uc774\ub8e8\ub824\ub294 \uc2dc\ub3c4\ub294 \uc655\uc774 \ud0dd\ud55c \ub2a5\ub3d9\uc801\uc778 \uc815\uce58 \ud589\ub3d9\uc774\uae30\ub3c4 \ud588\ub2e4. \ub2f9\uc2dc \uae30\ub85d\uacfc \ud6c4\ub300\uc758 \uc11c\uc220\uc740 \uadf8\uac00 \ucc38\ud68c\uc790\uc758 \uc637\ucc28\ub9bc\uc73c\ub85c \uc131 \ubc16\uc5d0\uc11c \uc5ec\ub7ec \ub0a0 \uae30\ub2e4\ub838\ub2e4\uace0 \uc804\ud55c\ub2e4. \ub9e8\ubc1c\uacfc \ucd94\uc704\uc758 \uc774\ubbf8\uc9c0\ub294 \uc0ac\uac74\uc758 \uc0c1\uc9d5\uc774 \ub418\uc5c8\ub2e4. \ub2e4\ub9cc \uc624\ub298\uc758 \uc0bd\ud654\ucc98\ub7fc \ub9e4 \uc21c\uac04\uc758 \uc790\uc138\uc640 \ud45c\uc815\uc744 \uc9c1\uc811 \ud655\uc778\ud560 \uc218 \uc788\ub294 \uae30\ub85d \uc0ac\uc9c4\uc740 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4. \uad50\ud669\uc740 \uacb0\uad6d \ud558\uc778\ub9ac\ud788\ub97c \ubc1b\uc544\ub4e4\uc774\uace0 \ud30c\ubb38\uc744 \ud480\uc5c8\ub2e4. \uadf8\ub9ac\uc2a4\ub3c4\uad50 \uc2e0\uc790\uc5d0\uac8c \ucc38\ud68c\uc640 \uc6a9\uc11c\ub77c\ub294 \uc6d0\uce59\uc744 \uc801\uc6a9\ud558\ub294 \ubb38\uc81c\uc640, \ub3c5\uc77c\uc758 \uc655\uc73c\ub85c\uc11c \uc815\uce58\uc801 \uc2e0\ub8b0\ub97c \ud68c\ubcf5\uc2dc\ud0a4\ub294 \ubb38\uc81c\ub294 \uc644\uc804\ud788 \uac19\uc9c0 \uc54a\uc558\ub2e4. \ud68c\ub3d9 \ud558\ub098\ub85c \ubaa8\ub4e0 \uc7c1\uc810\uc774 \ud574\uacb0\ub418\uc9c0\ub294 \uc54a\uc558\ub2e4. \ud558\uc778\ub9ac\ud788\ub294 \uc2e0\uc559 \uacf5\ub3d9\uccb4\ub85c \ub3cc\uc544\uc62c \uae38\uc744 \uc5bb\uc5c8\uace0 \uc81c\ud6c4\ub4e4\uc774 \uc655\uc744 \uacf5\uaca9\ud558\ub358 \uc911\uc694\ud55c \uba85\ubd84 \ud558\ub098\ub97c \uc57d\ud558\uac8c \ub9cc\ub4e4\uc5c8\ub2e4. \uac89\uc73c\ub85c \uad74\ubcf5\ud55c \ubaa8\uc2b5\uc774 \ubcf4\uc778\ub2e4\uace0 \ud574\uc11c \uadf8 \ud589\ub3d9\uc774 \uc815\uce58\uc801\uc73c\ub85c \uc544\ubb34 \uc131\uacfc\ub3c4 \uc5c6\uc5c8\ub2e4\uace0 \ub9d0\ud560 \uc218 \uc5c6\ub294 \uc774\uc720\ub2e4. \uce74\ub178\uc0ac\uc758 \uc758\ubbf8\ub294 \uc0ac\uac74 \ub2f9\uc77c\uc758 \uac10\uc815\ub9cc\uc774 \uc544\ub2c8\ub77c \ub204\uac00 \uc5b4\ub5a4 \uc774\uc57c\uae30\ub85c \uc804\ud588\ub294\uc9c0\uc5d0 \ub530\ub77c\uc11c\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uad50\ud669\uc758 \uad8c\uc704\ub97c \uac15\uc870\ud558\uba74 \uc655\uc758 \uad74\uc695\uc774 \ucee4\uc9c0\uace0, \uc655\uc758 \uc0dd\uc874 \uc804\ub7b5\uc744 \ubcf4\uba74 \uc815\uce58\uc801 \uc131\uacfc\uac00 \ubcf4\uc778\ub2e4. \ub450 \uc124\uba85\uc774 \uc5b4\ub290 \uc0ac\uc2e4\uc744 \uac15\uc870\ud558\ub294\uc9c0 \ube44\uad50\ud558\ub294 \uac83\uc774 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uc81c\ud6c4\ub4e4\uc758 \ubc18\ubc1c\uc740 \uacc4\uc18d\ub418\uc5c8\uace0 \ub2e4\ub978 \uc655\uc774 \uc120\ucd9c\ub418\uba74\uc11c \ub0b4\uc804\uc774 \ubc8c\uc5b4\uc84c\ub2e4. \uad50\ud669\uacfc \ud558\uc778\ub9ac\ud788\uc758 \uad00\uacc4\ub3c4 \ub2e4\uc2dc \uc545\ud654\ub418\uc5b4 1080\ub144\uc5d0\ub294 \ub610 \ud30c\ubb38\uc774 \uc774\ub8e8\uc5b4\uc84c\ub2e4. \uce74\ub178\uc0ac\uc758 \uc6a9\uc11c\uac00 \ub450 \uc0ac\ub78c \uc0ac\uc774\uc758 \uc9c0\uc18d\uc801\uc778 \ud654\ud574\ub97c \ubcf4\uc7a5\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ud558\uc778\ub9ac\ud788\ub294 \ub4a4\uc5d0 \uc774\ud0c8\ub9ac\uc544\ub85c \uc9c4\uad70\ud588\uace0 \uc790\uc2e0\uc744 \uc9c0\uc9c0\ud558\ub294 \uad50\ud669\uc744 \ud1b5\ud574 1084\ub144 \ud669\uc81c \ub300\uad00\uc744 \ubc1b\uc558\ub2e4. \uadf8\ub808\uace0\ub9ac\uc6b0\uc2a4 \uc5ed\uc2dc \ub05d\uae4c\uc9c0 \uc548\uc815\ub41c \uc2b9\ub9ac\uc790\ub85c \ub0a8\uc9c0 \ubabb\ud588\ub2e4. \ud55c \uc7a5\uba74\uc758 \uad74\uc695\uacfc \uc774\ud6c4 \uc218\uc2ed \ub144\uc758 \uad8c\ub825 \ud750\ub984\uc744 \ub098\ub204\uc5b4 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc11c\uc784\uad8c \ubb38\uc81c\ub294 \ud558\uc778\ub9ac\ud788\uc640 \uadf8\ub808\uace0\ub9ac\uc6b0\uc2a4\uc758 \uc8fd\uc74c\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\uc558\ub2e4. \ub2e4\uc74c \uc138\ub300\uc758 \ud611\uc0c1\uacfc \uac08\ub4f1\uc744 \uac70\uccd0 1122\ub144 \ubcf4\ub984\uc2a4 \ud611\uc57d\uc5d0\uc11c \uad8c\ud55c\uc744 \uc870\uc815\ud558\ub294 \ud0c0\ud611\uc774 \uc774\ub8e8\uc5b4\uc84c\ub2e4. \uadf8\uac83\ub3c4 \uc885\uad50\uc640 \uc815\uce58\uac00 \uc624\ub298\uc758 \uae30\uc900\uc73c\ub85c \uc644\uc804\ud788 \ubd84\ub9ac\ub418\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uce74\ub178\uc0ac \uc131\uc740 \uc624\ub298\ub0a0 \uc774\ud0c8\ub9ac\uc544\uc5d0 \uc788\uc9c0\ub9cc \uc774 \uae00\uc740 \ub3c5\uc77c \uc655\uad8c\uacfc \uc81c\ud6c4 \uc815\uce58\uc758 \ub9e5\ub77d\uc73c\ub85c \ub3c5\uc77c\uc5d0 \ubc30\uce58\ud588\ub2e4. \uc131\ubb38 \uc55e\uc758 \uc778\ubb3c\uc744 \ubcf4\uace0 \ub204\uac00 \uc774\uacbc\ub294\uc9c0\ub9cc \ubb3b\uae30\ubcf4\ub2e4, \uadf8\uac00 \uc65c \uadf8\uacf3\uc5d0 \uac14\uace0 \uc6a9\uc11c\ub85c \ubb34\uc5c7\uc744 \uc5bb\uc73c\ub824 \ud588\ub294\uc9c0 \ubb3c\uc73c\uba74 \uc911\uc138 \uc815\uce58\uc758 \uc2e4\uc81c \uc120\ud0dd\uc774 \ubcf4\uc778\ub2e4. \uc774 \uae00\uc758 \uaca8\uc6b8 \uc131\ubb38 \uc7a5\uba74\uc740 \ub2f9\uc2dc \ubaa8\uc2b5\uc744 \uc0c1\uc0c1\ud55c \uc0bd\ud654\ub2e4. \uc131\uc758 \uc815\ud655\ud55c \uad6c\uc870\uc640 \ud558\uc778\ub9ac\ud788\uc758 \uc790\uc138\ub97c \uc785\uc99d\ud558\ub294 \uc790\ub8cc\ub85c \uc4f0\uc9c0 \uc54a\uc558\ub2e4. \uc2dc\uac01\uc801 \uc778\uc0c1\uc740 \uc0ac\uac74\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \ucd9c\ubc1c\uc810\uc774\uba70, \uc55e\ub4a4\uc758 \uc2dc\uac04\uacfc \ud589\ub3d9\uc758 \ubaa9\uc801\uc740 \ubcf8\ubb38\uc5d0\uc11c \ub530\ub85c \ud655\uc778\ud574\uc57c \ud55c\ub2e4."}, {"id": "changan-travelers-and-music", "title": "\uc7a5\uc548 \u2014 \uc218\ub3c4\uc758 \uac70\ub9ac\uc5d0\ub294 \uc5b4\ub5a4 \ub9d0\uacfc \uc74c\uc545\uc774 \ud758\ub800\uc744\uae4c", "summary": "\uc7a5\uc548\uc5d0 \ubaa8\uc778 \ud398\ub974\uc2dc\uc544 \uc774\uc8fc\ubbfc\uacfc \uc18c\uadf8\ub4dc \uc0c1\uc778\uc758 \ud65c\ub3d9\uc5d0\uc11c \uad6d\uc81c\ub3c4\uc2dc\uc758 \uc5ec\ub7ec \uc5bc\uad74\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/changan-travelers-and-music/index.html", "image": "../media/changan-travelers-and-music.png", "alt": "\uc5ec\ub7ec \uc0c1\uc778\uc774 \uc9c1\ubb3c\uacfc \uae08\uc18d \ubb3c\uac74\uc744 \uc0b4\ud3b4\ubcf4\ub294 \uc61b \ub3d9\uc544\uc2dc\uc544 \ub3c4\uc2dc \uc2dc\uc7a5\uc758 AI \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\uc7a5\uc548 \u2014 \uc218\ub3c4\uc758 \uac70\ub9ac\uc5d0\ub294 \uc5b4\ub5a4 \ub9d0\uacfc \uc74c\uc545\uc774 \ud758\ub800\uc744\uae4c \ub2f9\ub098\ub77c\uc758 \ub3c4\uc2dc\ub97c \ucc44\uc6b4 \uac83\uc740 \uad81\uc804\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4 \uc7a5\uc548\uc5d0 \ubaa8\uc778 \ud398\ub974\uc2dc\uc544 \uc774\uc8fc\ubbfc\uacfc \uc18c\uadf8\ub4dc \uc0c1\uc778\uc758 \ud65c\ub3d9\uc5d0\uc11c \uad6d\uc81c\ub3c4\uc2dc\uc758 \uc5ec\ub7ec \uc5bc\uad74\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc61b \uc911\uad6d\uc758 \uc218\ub3c4\ub77c\uace0 \ud558\uba74 \uac70\ub300\ud55c \uad81\uc804\uacfc \ud669\uc81c\uc758 \ud589\ub82c\ubd80\ud130 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7f0\ub370 \ub2f9\ub098\ub77c\uc758 \uc7a5\uc548\uc5d0\ub294 \uba3c \uc9c0\uc5ed\uc5d0\uc11c \uc628 \uc0ac\ub78c\uacfc \ubb3c\uac74\ub3c4 \ubaa8\uc600\ub2e4. \ub2e4\ub978 \ub9d0\ub85c \uac70\ub798\ud558\ub294 \uc0c1\uc778\uacfc \uc775\uc219\ud558\uc9c0 \uc54a\uc740 \uc74c\uc545\uc774 \uc218\ub3c4\uc758 \uc0dd\ud65c\uc5d0 \ub4e4\uc5b4\uc640 \uc788\uc5c8\ub2e4. \ub3c4\uc2dc\uc758 \uc911\uc2ec\uc5d0 \ub204\uac00 \uc0b4\uc558\ub294\uc9c0\ub97c \uc544\ub294 \uac83\ub9cc\ud07c \ub204\uac00 \ub4dc\ub098\ub4e4\uc5c8\ub294\uc9c0\ub3c4 \uc911\uc694\ud558\ub2e4. \uc7a5\uc548\uc744 \uc911\uad6d\uc774\ub77c\ub294 \uacbd\uacc4 \uc548\uc5d0\ub9cc \ub193\uc73c\uba74 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc788\ub2e4. \uc624\ub298\uc740 \uad81\uc804\uc758 \uc548\ucabd\ubcf4\ub2e4 \ub3c4\uc2dc\ub85c \uc774\uc5b4\uc9c4 \uae38\uacfc \uadf8 \uae38\uc5d0\uc11c \uc628 \uc0dd\ud65c\uc758 \ud754\uc801\uc744 \uc0b4\ud3b4\ubcf4\uc790. \uc7a5\uc548\uc740 \ub2f9\ub098\ub77c\uc758 \uc218\ub3c4\uc774\uc790 \uc2e4\ud06c\ub85c\ub4dc \uad50\uc5ed\ub9dd\uc758 \uc911\uc694\ud55c \ub3d9\ucabd \uac70\uc810\uc774\uc5c8\ub2e4. \uc2e4\ud06c\ub85c\ub4dc\ub77c\ub294 \uc774\ub984 \ub54c\ubb38\uc5d0 \ube44\ub2e8\uc744 \uc2e4\uc740 \ud589\ub82c \ud55c \uc904\uc744 \uc0c1\uc0c1\ud558\uae30 \uc27d\uc9c0\ub9cc, \uc2e4\uc81c\ub85c\ub294 \uc5ec\ub7ec \uc9c0\uc5ed\uacfc \ub3c4\uc2dc\ub97c \uc787\ub294 \uae38\ub4e4\uc774 \uc788\uc5c8\ub2e4. \ubaa8\ub4e0 \uc0c1\uc778\uc774 \ucc98\uc74c\ubd80\ud130 \ub05d\uae4c\uc9c0 \uac19\uc740 \uc5ec\ud589\uc744 \ud55c \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uc0ac\ub78c\uc740 \uad6c\uac04\uc744 \uc624\uac00\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc740 \ud55c \ub3c4\uc2dc\uc5d0 \uba38\ubb3c\uba70 \uac70\ub798\ub97c \uc774\uc5b4 \uac14\ub2e4. \uc7a5\uc548\uc758 \uad6d\uc81c\uc801\uc778 \uc131\uaca9\uc740 \uba3c \uc11c\ucabd\uc5d0\uc11c \ud55c \ubc88\uc5d0 \ub3c4\ucc29\ud55c \ud2b9\ubcc4\ud55c \uc190\ub2d8\ub4e4\ub9cc\uc73c\ub85c \uc0dd\uae34 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc774\ub7f0 \uc911\uac04\uc758 \uc5f0\uacb0\uacfc \ubc18\ubcf5\ub41c \uc655\ub798\uac00 \ub3c4\uc2dc\uc758 \uc0dd\ud65c\uc744 \ub113\ud600 \uac14\ub2e4. \uc624\ub298\ub0a0 \uc6b0\uc988\ubca0\ud0a4\uc2a4\ud0c4\uacfc \ud0c0\uc9c0\ud0a4\uc2a4\ud0c4 \uc77c\ub300\uc758 \uc18c\uadf8\ub4dc \uc9c0\uc5ed\uc740 \uc911\uc559\uc544\uc2dc\uc544 \uad50\uc5ed\uc758 \uc911\uc694\ud55c \ubc30\uacbd\uc774\uc5c8\ub2e4. \uc18c\uadf8\ub4dc \uc0c1\uc778\ub4e4\uc740 \uc11c\ucabd\uc758 \uc5ec\ub7ec \uc9c0\uc5ed\uacfc \ub3d9\ucabd \uc911\uad6d \uc0ac\uc774\uc5d0\uc11c \ud65c\ub3d9\ud588\ub2e4. \uad50\uc7ac\ub294 \uc7a5\uc548 \uac19\uc740 \uc911\uad6d \ub3c4\uc2dc\uc5d0\ub3c4 \uc774\ub4e4\uc758 \uad50\uc5ed \uacf5\ub3d9\uccb4\uac00 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc774\uc8fc \uc0c1\uc778\uc774 \uacf5\ub3d9\uccb4\ub97c \uc774\ub8ec\ub2e4\ub294 \uac83\uc740 \ub2e8\uc21c\ud788 \uc7a0\uae50 \ubb3c\uac74\uc744 \ud314\uace0 \ub5a0\ub098\ub294 \uc7a5\uba74\uacfc \ub2e4\ub974\ub2e4. \uac70\ub798\ub97c \uc774\uc5b4 \uac08 \uc0ac\ub78c\uacfc \ub9d0\uc744 \ub098\ub20c \uc0c1\ub300, \uc0dd\ud65c\uc744 \uc720\uc9c0\ud560 \uad00\uacc4\uac00 \uc0dd\uae34\ub2e4\ub294 \ub73b\uc774\ub2e4. \ub3c4\uc2dc\uc758 \ub0af\uc120 \ubb3c\uac74 \ub4a4\uc5d0\ub294 \uadf8\uac83\uc744 \ub2e4\ub8e8\uace0 \uc124\uba85\ud560 \uc218 \uc788\ub294 \uc0ac\ub78c\ub4e4\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. 7\uc138\uae30 \ud6c4\ubc18\uc5d0\ub294 \uc0ac\uc0b0 \uc655\uc870\uc758 \uc655\uc2e4 \uc778\ubb3c\ub4e4\uc774 \uc11c\ucabd\uc758 \uc815\uce58\uc801 \ubcc0\ud654 \uc18d\uc5d0\uc11c \ub2f9\ub098\ub77c \uad81\uc815\uc73c\ub85c \ud53c\uc2e0\ud588\ub2e4. \uad50\uc7ac\ub294 \uc774\uc640 \ud568\uaed8 \ud398\ub974\uc2dc\uc544\uacc4 \uc0c1\uc778 \uacf5\ub3d9\uccb4\uc758 \uc774\ub3d9\uc744 \uc124\uba85\ud55c\ub2e4. \ubb3c\uac74\uc744 \uc0ac\ub7ec \ub5a0\ub098\ub294 \uc5ec\ud589\ub9cc\uc774 \uc544\ub2c8\ub77c \uc548\uc804\uacfc \uc0c8\ub85c\uc6b4 \uc0dd\ud65c\uc744 \ucc3e\ub294 \uc774\ub3d9\ub3c4 \uc788\uc5c8\ub2e4. \ub3c4\uc2dc\ub85c \ub4e4\uc5b4\uc628 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ucd9c\ubc1c\uc9c0\uc5d0\uc11c \uacaa\uc740 \uc0c1\uc2e4\uacfc \uac08\ub4f1\uc774 \uc788\uc5c8\uc744 \uc218 \uc788\ub2e4. \ub3c4\ucc29\ud55c \uacf3\uc5d0\uc11c\ub294 \ub0af\uc120 \uae30\uc220\uacfc \ucde8\ud5a5\uc744 \uc804\ud558\ub294 \uc0ac\ub78c\uc774 \ub418\uae30\ub3c4 \ud588\ub2e4. \ubb38\ud654 \uad50\ub958\ub77c\ub294 \ubc1d\uc740 \ud45c\ud604 \ub4a4\uc5d0\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc0ac\uc815\uc758 \uc5ec\uc815\uc774 \uacb9\uccd0 \uc788\uc5c8\ub2e4\ub294 \uc810\uc744 \uae30\uc5b5\ud560 \ub9cc\ud558\ub2e4. \uc7a5\uc548\uc5d0 \uc804\ud574\uc9c4 \uac83\uc5d0\ub294 \uc0ac\uce58\ud488\uacfc \uc740\uc81c \uacf5\uc608\ud488\ubfd0 \uc544\ub2c8\ub77c \uc544\ub78d\u00b7\ud398\ub974\uc2dc\uc544\u00b7\uc911\uc559\uc544\uc2dc\uc544\uc758 \uc74c\uc545\uacfc \ucda4\ub3c4 \uc788\uc5c8\ub2e4. \uc774\uac83\uc740 \uad50\uc5ed\uc774 \uc0c1\ud488 \ubaa9\ub85d\uc744 \ub298\ub9ac\ub294 \ub370\uc11c \ub05d\ub098\uc9c0 \uc54a\uc558\ub2e4\ub294 \ub73b\uc774\ub2e4. \ubab8\uc73c\ub85c \uc775\ud78c \ud45c\ud604\uacfc \uadc0\ub85c \uc990\uae30\ub294 \ucde8\ud5a5\ub3c4 \uc0ac\ub78c\uc744 \ub530\ub77c \uc6c0\uc9c1\uc600\ub2e4. \uc5b4\ub5a4 \ubb3c\uac74\uc740 \uc0ac\uace0\ud314 \uc218 \uc788\uc9c0\ub9cc \uc74c\uc545\uacfc \ucda4\uc740 \ub4e3\uace0 \ubcf4\uace0 \ubc30\uc6b0\ub294 \uc2dc\uac04\uc774 \ud544\uc694\ud558\ub2e4. \ub0af\uc120 \ucde8\ud5a5\uc774 \ub3c4\uc2dc\uc5d0 \ub4e4\uc5b4\uc628\ub2e4\ub294 \uac83\uc740 \uc0ac\ub78c\ub4e4 \uc0ac\uc774\uc758 \ub9cc\ub0a8\uc774 \uacc4\uc18d\ub41c\ub2e4\ub294 \uc758\ubbf8\ub2e4. \uc218\ub3c4\uc758 \ud654\ub824\ud568\uc744 \uae08\uacfc \ube44\ub2e8\uc758 \uc591\uc73c\ub85c\ub9cc \uc0dd\uac01\ud558\uba74 \uc774\ub7f0 \uc6c0\uc9c1\uc774\ub294 \ubb38\ud654\ub294 \ub193\uce58\uae30 \uc27d\ub2e4. \uc5ec\ub7ec \uc9c0\uc5ed\uc758 \uc0ac\ub78c\uc774 \ubaa8\uc600\ub2e4\uace0 \uac01\uc790\uac00 \uac19\uc740 \uad8c\ub9ac\uc640 \uc601\ud5a5\ub825\uc744 \uac00\uc84c\ub2e4\uace0 \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uad81\uc815\uc758 \uc678\uad50\uc640 \uc0c1\uc778\uc758 \uac70\ub798, \uc774\uc8fc\ubbfc\uc758 \uc77c\uc0c1\uc740 \uc11c\ub85c \ub2e4\ub978 \uc870\uac74\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc84c\ub2e4. \uad6d\uc81c\ub3c4\uc2dc\ub77c\ub294 \ub9d0\uc740 \ub9ce\uc740 \ucc28\uc774\uac00 \uac00\uae4c\uc774 \uc788\uc5c8\ub2e4\ub294 \ucd9c\ubc1c\uc810\uc774\uc9c0 \ud3c9\ub4f1\uc744 \ubcf4\uc99d\ud558\ub294 \ud3c9\uac00\ud45c\ub294 \uc544\ub2c8\ub2e4. \ub610 \uc7a5\uc548\uc5d0\uc11c \ub9cc\ub09c \uc885\uad50\uc640 \ubb38\ud654\uac00 \uc911\uad6d \uc804\uccb4\uc5d0 \uac19\uc740 \uc18d\ub3c4\ub85c \ud37c\uc84c\ub2e4\uace0 \ub9d0\ud560 \uc218\ub3c4 \uc5c6\ub2e4. \uc218\ub3c4\uc758 \ud2b9\ubcc4\ud55c \ud658\uacbd\uacfc \uac01 \uc9c0\uc5ed\uc758 \uc0dd\ud65c\uc744 \ub098\ub204\uc5b4 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ud55c \ub3c4\uc2dc\uc758 \ud48d\uacbd\uc774 \ub113\uc740 \uc81c\uad6d \uc804\uccb4\uc758 \ubaa8\uc2b5\uc744 \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. 755\ub144\uc5d0 \uc2dc\uc791\ub41c \uc548\uc0ac\uc758 \ub09c\uc740 \ub2f9 \uc81c\uad6d\uc744 \ud06c\uac8c \ud754\ub4e4\uc5c8\ub2e4. \uad50\uc7ac\ub294 \uc624\ub79c \uc9c4\uc555 \uacfc\uc815\uacfc \uc774\ud6c4\uc758 \uc57d\ud654\ub97c \uc124\uba85\ud55c\ub2e4. \uc7a5\uc548\uc774 \uad6d\uc81c\uc801\uc774\uace0 \ud654\ub824\ud55c \uc218\ub3c4\uc600\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc815\uce58\uc640 \uad70\uc0ac\uc758 \uc704\uae30\ub97c \ub9c9\uc544 \uc8fc\uc9c0\ub294 \uc54a\uc558\ub2e4. \ub3c4\uc2dc\uc758 \ubb38\ud654\uc801 \ub9e4\ub825\uacfc \uad6d\uac00\uc758 \uc548\uc815\uc740 \uac19\uc740 \uc9c0\ud45c\uac00 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\uc774 \ubaa8\uc774\uace0 \ubb3c\uac74\uc774 \uc624\uac00\ub358 \uad00\uacc4\ub3c4 \uc804\uc7c1\uacfc \uad8c\ub825\uc758 \ubcc0\ud654\uc5d0 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4. \ubc88\uc131\ud558\ub358 \uac70\ub9ac\ub97c \uc0c1\uc0c1\ud560 \ub54c \uadf8 \ubaa8\uc2b5\uc744 \uc601\uc6d0\ud788 \uace0\uc815\ub41c \ud3c9\ud654\ub85c\uc6b4 \uc7a5\uba74\uc73c\ub85c \ub9cc\ub4e4\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc5ed\uc0ac\ub97c \ub354 \uc785\uccb4\uc801\uc73c\ub85c \ubcf4\uac8c \ud55c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \uc0c1\uc778\ub4e4\uc774 \uc9c1\ubb3c\uacfc \ubb3c\uac74\uc744 \uc0b4\ud53c\ub294 AI \ubd84\uc704\uae30 \uc0bd\ud654\ub2e4. \uc7a5\uc548\uc758 \ud2b9\uc815 \uc2dc\uc7a5 \ubc30\uce58\uc640 \ubcf5\uc2dd, \uc2e4\uc81c \uac70\ub798 \uc7a5\uba74\uc744 \uace0\uc99d\ud574 \ubcf5\uc6d0\ud55c \uc790\ub8cc\uac00 \uc544\ub2c8\ub2e4. \uadf8\ub9bc\uc5d0 \ubcf4\uc774\ub294 \uc778\ubb3c\uc744 \ud2b9\uc815 \ubbfc\uc871\uc758 \ub300\ud45c \ubaa8\uc2b5\uc73c\ub85c \ubc1b\uc544\ub4e4\uc77c \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ud655\uc778\ud55c \uc0ac\uc2e4\uc740 \uc5ec\ub7ec \uc9c0\uc5ed \ucd9c\uc2e0\uc758 \uc0ac\ub78c\ub4e4\uc774 \uad50\uc5ed \uacf5\ub3d9\uccb4\uc640 \uc774\uc8fc\ub97c \ud1b5\ud574 \uc7a5\uc548\uc5d0 \ubaa8\uc600\ub2e4\ub294 \uc810\uc774\ub2e4. \uc0bd\ud654\ub294 \uadf8\ub7f0 \ub9cc\ub0a8\uc744 \uac00\uae4c\uc774 \ub290\ub07c\uac8c \ud558\ub294 \uc5ed\ud560\uc744 \ud55c\ub2e4. \uc5ed\uc0ac\uc801 \uadfc\uac70\ub294 \uae00\uc758 \uc790\ub8cc\uc5d0\uc11c, \uc0c1\uc0c1\uc758 \uc7a5\uba74\uc740 \uc774\ubbf8\uc9c0\uc758 \uc548\ub0b4\ub97c \ub530\ub77c \ub098\ub204\uc5b4 \uc77d\uc73c\uba74 \ub41c\ub2e4. \uc7a5\uc548\uc758 \uc774\uc57c\uae30\ub97c \ub2e4 \uc77d\uace0 \ud669\uc81c\uc758 \uc774\ub984\uc744 \ub354 \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub300\uc2e0 \uba3c \uacf3\uc5d0\uc11c \uc628 \uc0c1\uc778\uc774 \uc790\uae30 \ub9d0\uc744 \ub2e4\ub978 \ub9d0\uacfc \ub9de\ucd94\uace0, \ub0af\uc120 \uc74c\uc545\uc774 \ub204\uad70\uac00\uc758 \uadc0\uc5d0 \ucc98\uc74c \ub2ff\ub294 \uc7a5\uba74\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ub3c4\uc2dc\uc758 \uc5ed\uc0ac\ub294 \uadf8\ub7f0 \ub9cc\ub0a8\ub3c4 \ud3ec\ud568\ud55c\ub2e4. \uac70\ub300\ud55c \uc218\ub3c4\uc758 \ud798\uc740 \ubaa8\ub4e0 \uac83\uc744 \ud63c\uc790 \ub9cc\ub4e4\uc5b4 \ub0c8\ub2e4\ub294 \ub370\ub9cc \uc788\uc9c0 \uc54a\uc558\ub2e4. \ub2e4\ub978 \uc9c0\uc5ed\uc5d0\uc11c \uc628 \uc0ac\ub78c\uacfc \ubb3c\uac74, \ud45c\ud604\uc744 \ub9cc\ub098\uba70 \uc0c8\ub85c\uc6b4 \uc0dd\ud65c\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \uc7a5\uc548\uc744 \uad6d\uc81c\ub3c4\uc2dc\ub85c \uae30\uc5b5\ud55c\ub2e4\ub294 \uac83\uc740 \uad81\uc804\uc758 \ub192\uc774 \uc606\uc5d0 \uc774\ub984\uc774 \uc798 \ub0a8\uc9c0 \uc54a\uc740 \uc774\ub3d9\uc758 \uc2dc\uac04\ub3c4 \ud568\uaed8 \ub193\ub294 \uc77c\uc774\ub2e4."}, {"id": "chicago-lion-sports-helmet", "title": "\uc2dc\uce74\uace0\uc758 \uc0ac\uc790\ub294 \uac00\ub054 \ud5ec\uba67\uc744 \uc4f4\ub2e4", "summary": "\uadfc\uc5c4\ud55c \uccad\ub3d9 \uc0ac\uc790\ub4e4\uc774 \uc2a4\ud3ec\uce20 \ud5ec\uba67\uc744 \uc4f0\uac8c \ub41c \uc0ac\uc5f0\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/chicago-lion-sports-helmet/index.html", "image": "../media/chicago-lion-sports-helmet.jpg", "alt": "\uc2dc\uce74\uace0\uc758 \uc0ac\uc790\ub294 \uac00\ub054 \ud5ec\uba67\uc744 \uc4f4\ub2e4\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\uc2dc\uce74\uace0\uc758 \uc0ac\uc790\ub294 \uac00\ub054 \ud5ec\uba67\uc744 \uc4f4\ub2e4 \ubbf8\uc220\uad00 \uc55e \uc870\uac01\uc0c1\uc774 \ub3c4\uc2dc\uc758 \uc751\uc6d0\ub2e8\uc774 \ub418\ub294 \ub0a0 \uadfc\uc5c4\ud55c \uccad\ub3d9 \uc0ac\uc790\ub4e4\uc774 \uc2a4\ud3ec\uce20 \ud5ec\uba67\uc744 \uc4f0\uac8c \ub41c \uc0ac\uc5f0\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ubbf8\uc220\uad00 \uc785\uad6c\uc758 \uc0ac\uc790\ub77c\uba74 \uadfc\uc5c4\ud55c \ud45c\uc815\uc744 \uae30\ub300\ud558\uac8c \ub41c\ub2e4. \uadf8\ub7f0\ub370 \ubbf8\uad6d \uc2dc\uce74\uace0\uc5d0\uc11c\ub294 \uadf8 \uc0ac\uc790\uc5d0\uac8c \ucee4\ub2e4\ub780 \uc2a4\ud3ec\uce20 \ud5ec\uba67\uc744 \uc50c\uc6b0\uae30\ub3c4 \ud55c\ub2e4. \uc870\uac01\uc0c1\uc774 \uac11\uc790\uae30 \ub3d9\ub124 \uc751\uc6d0\ub2e8\uc774 \ub41c \uac83 \uac19\uc740 \ubaa8\uc2b5\uc774\ub2e4. \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc740 \uc9c0\uc5ed \ud300\uc744 \uc751\uc6d0\ud558\ub294 \uc0ac\uc790\ub4e4\uc758 \uc774\uc57c\uae30\ub97c \uacf5\uc2dd \uae00\uc5d0 \ub0a8\uacbc\ub2e4. \uc791\ud488\uc758 \uc81c\uc791 \uc5f0\ub3c4\ub9cc \uc54c\uba74 \ub05d\ub098\ub294 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \ub3c4\uc2dc \uc0ac\ub78c\ub4e4\uc774 \uc870\uac01\uc0c1\uacfc \uc5b4\ub5bb\uac8c \uc9c0\ub0b4\ub294\uc9c0\ub3c4 \uc774 \uc0ac\uc790\ub4e4\uc758 \uc774\ub825\uc774 \ub41c\ub2e4. \ubbf8\uc220\uad00 \uc124\uba85\uc5d0 \ub530\ub974\uba74 \uc0ac\uc790\ub4e4\uc740 \uc5d0\ub4dc\uc6cc\ub4dc \ucf00\ubbf8\uc2a4\uac00 \ub9cc\ub4e4\uc5c8\uace0 1894\ub144 \ubbf8\uc220\uad00 \uc815\ubb38 \uc55e\uc5d0 \uc124\uce58\ub418\uc5c8\ub2e4. \uadf8\ub7f0\ub370 \ub458\uc740 \ub611\uac19\uc740 \uc870\uac01\uc774 \uc544\ub2c8\ub2e4. \uc790\uc138\ub3c4 \ub2e4\ub974\uace0 \ubab8\uc758 \ud06c\uae30\uc640 \uac08\uae30\uc758 \ubaa8\uc591\ub3c4 \ub2e4\ub974\ub2e4. \ubd81\ucabd \uc0ac\uc790\ub294 \uba39\uc787\uac10\uc744 \ucc3e\uc544 \uc6c0\uc9c1\uc774\ub294 \ub4ef\ud55c \uc790\uc138\uc774\uace0 \ub0a8\ucabd \uc0ac\uc790\ub294 \ub2f9\ub2f9\ud788 \ubc84\ud2f0\ub294 \uc790\uc138\ub85c \uc18c\uac1c\ub41c\ub2e4. \uac19\uc740 \uc0ac\uc790\ucc98\ub7fc \ubcf4\uace0 \uc9c0\ub098\ucce4\ub2e4\uba74 \ub2e4\uc74c\uc5d0\ub294 \ub2e4\ub9ac\uc640 \uace0\uac1c\ub97c \ube44\uad50\ud574 \ubcfc \ub9cc\ud558\ub2e4. \ubbf8\uc220\uad00\uc740 \uc0ac\uc790\ub4e4\uc774 \uc2a4\ud3ec\uce20 \uc751\uc6d0\uc5d0 \ucc38\uc5ec\ud55c \uc77c\uc744 1985\ub144 \uc2dc\uc98c \uc2dc\uce74\uace0 \ubca0\uc5b4\uc2a4\uc758 \uc288\ud37c\ubcfc \uc9c4\ucd9c\uc744 \uc751\uc6d0\ud558\ub358 \ub54c\ubd80\ud130 \uc124\uba85\ud55c\ub2e4. \ub2f9\uc2dc\uc758 \ud5ec\uba67\uc740 \ub4a4\uc9d1\uc740 \ubc14\ube44\ud050 \uadf8\ub9b4\uc5d0 \uac04\ub2e8\ud55c \uc548\uba74 \ubcf4\ud638\ub300\ub97c \ubd99\uc5ec \ub9cc\ub4e0 \uac83\uc774\uc5c8\ub2e4\uace0 \ud55c\ub2e4. \uac00\uac8c\uc5d0\uc11c \uc0ac \uc628 \uae30\uc131\ud488\uc774 \uc544\ub2c8\uc5c8\ub358 \uc148\uc774\ub2e4. \uc0ac\ub78c\ubcf4\ub2e4 \ud6e8\uc52c \ud070 \uba38\ub9ac\uc5d0 \ub9de\ucdb0\uc57c \ud558\ub2c8 \uc751\uc6d0 \ub3c4\uad6c\ub3c4 \ud2b9\ubcc4\ud55c \uc81c\uc791\uc774 \ud544\uc694\ud588\ub2e4. \ubbf8\uc220\uad00 \uc55e\uc5d0\uc11c\ub294 \uc791\ud488\uc744 \uac10\uc0c1\ud558\ub294 \uc77c\uacfc \uc2a4\ud3ec\uce20\ub97c \uc751\uc6d0\ud558\ub294 \uc77c\uc774 \uc774\ub807\uac8c \ub9cc\ub0ac\ub2e4. \ub450 \uc0ac\uc790\ub294 \ud06c\uae30\uc640 \uac08\uae30, \uc790\uc138\uac00 \uc11c\ub85c \ub2e4\ub974\ub2e4. \uacf5\uc2dd \uae00\uc740 \ubd81\ucabd \uc0ac\uc790\ub97c \uba39\uc787\uac10\uc744 \ucc3e\uc544 \uc6c0\uc9c1\uc774\ub294 \ub4ef\ud55c \uc774\ub984\uc73c\ub85c, \ub0a8\ucabd \uc0ac\uc790\ub97c \ub3c4\uc804\uc801\uc778 \uc790\uc138\ub85c \ubc84\ud2f0\ub294 \uc774\ub984\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \uac19\uc740 \ucd9c\uc785\ubb38\uc744 \uc0ac\uc774\uc5d0 \ub450\uace0 \uc788\uc5b4\ub3c4 \ud55c \ub9c8\ub9ac\ub97c \ubcf5\uc0ac\ud574 \ub193\uc740 \uad00\uacc4\uac00 \uc544\ub2c8\ub2e4. \uc791\ud488 \uc55e\uc5d0\uc11c\ub294 \uba3c\uc800 \uc55e\ub2e4\ub9ac\uac00 \uc5b4\ub514\uc5d0 \ub193\uc600\uace0 \uace0\uac1c\uac00 \uc5b4\ub290 \ucabd\uc73c\ub85c \ud5a5\ud558\ub294\uc9c0 \ube44\uad50\ud574 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc774 \ucc28\uc774\ub294 \ud5ec\uba67\uc744 \ub9cc\ub4e4 \ub54c \ub73b\ubc16\uc758 \uc2e4\ubb34 \ubb38\uc81c\uac00 \ub41c\ub2e4. \ud55c\ucabd\uc5d0 \ub9de\ub294 \uc7a5\uc2dd\uc774 \ub2e4\ub978 \ucabd\uc5d0\ub3c4 \uaf2d \ub9de\uc73c\ub9ac\ub77c\ub294 \ubcf4\uc7a5\uc774 \uc5c6\uae30 \ub54c\ubb38\uc774\ub2e4. \uc870\uac01\uc758 \uac1c\uc131\uc744 \uac10\uc0c1\ud558\ub294 \uc77c\uacfc \uc7a5\uc2dd\ud488\uc758 \uce58\uc218\ub97c \uc7ac\ub294 \uc77c\uc774 \uac19\uc740 \ud2b9\uc9d5\uc744 \ubc14\ub77c\ubcf8\ub2e4. \ub3c4\uc2dc\uc758 \ucd95\uc81c\ub3c4 \uacb0\uad6d \uc2e4\uc81c \ubb3c\uac74\uc758 \ud06c\uae30\uc640 \ubaa8\uc591\uc744 \ub2e4\ub8e8\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc190\uc744 \uac70\uccd0\uc57c \uc644\uc131\ub41c\ub2e4. \ubbf8\uc220\uad00\uc740 2007\ub144 \ubca0\uc5b4\uc2a4 \uc751\uc6d0 \ud589\uc0ac\ub97c \uc900\ube44\ud558\ub358 \uaca8\uc6b8\uc758 \uc77c\uc744 \uc804\ud55c\ub2e4. \uac70\ub300\ud55c \ud50c\ub77c\uc2a4\ud2f1 \ud5ec\uba67\uc744 \ubd81\ucabd \uc0ac\uc790\uc758 \uac08\uae30\uc5d0 \ub9de\ucd94\ub294 \uacfc\uc815\uc5d0\uc11c \uc77c\ubd80\uac00 \uae68\uc84c\ub2e4. \ucd94\uc6b4 \ub0a0 \uc7ac\ub8cc\uac00 \uc218\ucd95\ud55c \uc0c1\ud0dc\uc5d0\uc11c \uc7a5\uc2dd\uc744 \ub298\ub824 \ub07c\uc6b0\ub2e4 \ubb38\uc81c\uac00 \uc0dd\uacbc\ub2e4\ub294 \uc124\uba85\uc774\ub2e4. \uc0ac\uc790\uc758 \ubab8\uc774 \uc544\ub2c8\ub77c \ubcc4\ub3c4\ub85c \uc81c\uc791\ud55c \ud5ec\uba67\uc5d0\uc11c \uc77c\uc5b4\ub09c \uc0ac\uace0\uc600\ub2e4. \uc7a5\uc2dd\uc740 \ubc24\uc0ac\uc774\uc5d0 \uc218\ub9ac\ud574 \ub2e4\uc74c \ub0a0 \ub2e4\uc2dc \uc124\uce58\ud588\ub2e4. \uc774\ud6c4 \ud300\uc758 \ud328\ubc30\ub97c \uc0ac\uc790 \ud0d3\uc73c\ub85c \ub3cc\ub9ac\ub294 \ub18d\ub2f4\ub3c4 \uc788\uc5c8\uc9c0\ub9cc, \ubbf8\uc220\uad00\uc740 \uadf8 \ub9d0\uc744 \uc0ac\uc2e4\ub85c \ubc1b\uc544\ub4e4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc774 \uc77c\ud654\uc758 \uc7ac\ubbf8\ub294 \uc2b9\ud328\ub97c \uc810\uce58\ub294 \ub370\ubcf4\ub2e4 \uc870\uac01\uc0c1\ub3c4 \uacc4\uc808\uacfc \uc7ac\ub8cc\uc758 \uc601\ud5a5\uc744 \ubc1b\ub294 \ud589\uc0ac\uc758 \ubb34\ub300\uac00 \ub41c\ub2e4\ub294 \ub370 \uc788\ub2e4. \ub3c4\uc2dc\uc758 \uc775\uc0b4 \ub4a4\uc5d0\ub294 \uc81c\uc791\uacfc \uc218\uc120\uc758 \uc2dc\uac04\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \ubbf8\uc220\uad00\uc740 \uc791\ud488\uc744 \ubcf4\ub7ec \ucc3e\uc544\uac00\ub294 \uc7a5\uc18c\uc9c0\ub9cc \uc815\ubb38 \uc55e\uc740 \uac70\ub9ac\ub97c \uc9c0\ub098\ub358 \uc0ac\ub78c\ub3c4 \ub9cc\ub098\ub294 \uacf5\uac04\uc774\ub2e4. \ud5ec\uba67\uc744 \uc4f4 \uc0ac\uc790\ub294 \uc785\uc7a5\uad8c\uc744 \uc0ac\uc9c0 \uc54a\uc740 \uc2dc\ubbfc\uc5d0\uac8c\ub3c4 \uadf8\ub0a0\uc758 \uc774\uc57c\uae30\ub97c \uac74\ub128\ub2e4. \ud2b9\uc815 \uc791\ud488\uc744 \uc798 \uc544\ub294 \uc0ac\ub78c\ub9cc \ubc18\uc751\ud560 \uc218 \uc788\ub294 \ud45c\uc9c0\uac00 \uc544\ub2c8\ub77c \uc9c0\uc5ed \ud300\uc758 \uc18c\uc2dd\uc744 \uc544\ub294 \uc0ac\ub78c\uc774\ub77c\uba74 \ud568\uaed8 \uc54c\uc544\ubcfc \uc218 \uc788\ub294 \ubaa8\uc2b5\uc774 \ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc870\uac01\uc758 \uc6d0\ub798 \ub73b\uc774 \ubaa8\ub450 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadfc\uc5c4\ud55c \uc790\uc138\ub294 \uadf8\ub300\ub85c\uc778\ub370 \uc784\uc2dc \uc7a5\uc2dd\uc774 \uc5b9\ud788\uba74\uc11c \uc0c8\ub85c\uc6b4 \ud45c\uc815\uc774 \uc0dd\uae34\ub2e4. \ubc14\ub00c\uc9c0 \uc54a\ub294 \ubd80\ubd84\uacfc \uc7a0\uc2dc \ub2ec\ub77c\uc9c0\ub294 \ubd80\ubd84\uc774 \ud568\uaed8 \ubcf4\uc774\uae30\uc5d0 \ub354 \uc7ac\ubbf8\uc788\ub2e4. \uac19\uc740 \uc7a5\uc18c\ub97c \uc5ec\ub7ec \ubc88 \uc9c0\ub098\uac00\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc774\ub7f0 \uc791\uc740 \ubcc0\ud654\uac00 \uacc4\uc808\uc774\ub098 \ud589\uc0ac\uc758 \uae30\uc5b5\uc744 \ub0a8\uae38 \uc218 \uc788\ub2e4. 1894\ub144 \uc124\uce58\ub77c\ub294 \uc774\ub825\uc740 \uc0ac\uc790\uac00 \uc5b8\uc81c \uadf8\uacf3\uc5d0 \uc654\ub294\uc9c0 \uc54c\ub824 \uc900\ub2e4. \uc751\uc6d0 \ud5ec\uba67\uc758 \uc77c\ud654\ub294 \uadf8 \ub4a4\uc5d0 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5a4 \uad00\uacc4\ub97c \ub9cc\ub4e4\uc5b4 \uc654\ub294\uc9c0 \ubcf4\uc5ec \uc900\ub2e4. \uacf5\uacf5 \uc870\uac01\uc758 \uc0dd\uc560\ub97c \uc81c\uc791\uacfc \uc124\uce58\uc5d0\uc11c \ub05d\ub0b4\uc9c0 \uc54a\uc73c\uba74 \uc218\ub9ac\uc640 \ud589\uc0ac, \uc2dc\ubbfc\uc758 \uc0ac\uc9c4\ub3c4 \ud568\uaed8 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \uc791\ud488\uc740 \uc6c0\uc9c1\uc774\uc9c0 \uc54a\uc544\ub3c4 \uc8fc\ubcc0\uc758 \uc4f0\uc784\uacfc \uae30\uc5b5\uc740 \ub2ec\ub77c\uc9c4\ub2e4. \ubc29\ubb38\ud560 \ub54c \ud5ec\uba67\uc774 \uc5c6\ub354\ub77c\ub3c4 \uc774\uc57c\uae30\uac00 \ud2c0\ub9b0 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud589\uc0ac \ub54c\uc758 \ubcc0\ud654\uc640 \ub298 \ubcfc \uc218 \uc788\ub294 \ubaa8\uc2b5\uc744 \uad6c\ubd84\ud558\uba74 \ub41c\ub2e4. \uc0ac\uc790\ub97c \ub2e4\uc2dc \ubcf4\uac8c \ub41c\ub2e4\uba74 \uba3c\uc800 \ub450 \uc790\uc138\uc758 \ucc28\uc774\ub97c \ucc3e\uace0, \ub2e4\uc74c\uc5d0\ub294 \uc9c0\ub098\uac00\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub290 \ucabd\uc5d0\uc11c \uba48\ucd94\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \ud55c \uc870\uac01\uc0c1\uc744 \uac10\uc0c1\ud558\ub294 \uc77c\uc774 \ub3c4\uc2dc\uac00 \uc790\uae30 \uc0c1\uc9d5\uc744 \uc0ac\uc6a9\ud558\ub294 \ubc29\uc2dd\uc744 \uc77d\ub294 \uc77c\ub85c \uc774\uc5b4\uc9c4\ub2e4. \uc774\ud6c4 \uc0ac\uc790\ub4e4\uc740 \uc544\uc774\uc2a4\ud558\ud0a4 \ud300 \ube14\ub799\ud638\ud06c\uc2a4\ub97c \uc751\uc6d0\ud558\ub294 \ud5ec\uba67\ub3c4 \uc37c\ub2e4. \ub2e4\ub9cc \ubc29\ubb38\ud560 \ub54c\ub9c8\ub2e4 \ud5ec\uba67\uc744 \ubcfc \uc218 \uc788\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud2b9\uc815 \uc751\uc6d0 \ud589\uc0ac\uc5d0 \ub9de\ucdb0 \uc637\ucc28\ub9bc\uc774 \ub2ec\ub77c\uc9c0\ub294 \uc870\uac01\uc0c1\ub4e4\uc774\ub2e4. \uc624\ub798\ub41c \uacf5\uacf5 \uc870\uac01\uc740 \uac00\ub9cc\ud788 \uc11c \uc788\uae30\ub9cc \ud558\ub294 \ubb3c\uac74\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \ud558\uc9c0\ub9cc \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\uc774 \ubb34\uc5b8\uac00\ub97c \uc50c\uc6b0\uace0, \uc0ac\uc9c4\uc744 \ucc0d\uace0, \ucd94\uc5b5\uc744 \ubcf4\ud0dc\uba74 \uc0c8\ub85c\uc6b4 \uc774\uc57c\uae30\uac00 \ubd99\ub294\ub2e4. \uc2dc\uce74\uace0\uc758 \uc0ac\uc790\ub4e4\uc740 \ubbf8\uc220\uad00\uc744 \uc9c0\ud0a4\ub294 \ub3d9\uc2dc\uc5d0 \ub3c4\uc2dc\uc758 \uae30\ubd84\uc744 \ud568\uaed8 \ub098\ub204\uace0 \uc788\ub2e4."}, {"id": "chichen-itza-pyramid-cenote-and-plazas", "title": "\uce58\uccb8\uc774\ud2b8\uc0ac \u2014 \ud53c\ub77c\ubbf8\ub4dc \uc606\uc5d0\ub294 \uc6b0\ubb3c\uacfc \uae38\uc774 \uc788\uc5c8\ub2e4", "summary": "\ud070 \ud53c\ub77c\ubbf8\ub4dc\uc640 \uc8fc\ubcc0 \uad11\uc7a5\u00b7\uc5f4\uc8fc\u00b7\ubb3c \uacf5\uac04\uc744 \uc5f0\uacb0\ud574 \uce58\uccb8\uc774\ud2b8\uc0ac\ub97c \ud558\ub098\uc758 \ub3c4\uc2dc\ub85c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/chichen-itza-pyramid-cenote-and-plazas/index.html", "image": "../media/chichen-itza-pyramid-cenote-and-plazas.png", "alt": "\uce58\uccb8\uc774\ud2b8\uc0ac\uc758 \uc5d8 \uce74\uc2a4\ud2f0\uc694\uc640 \uc8fc\ubcc0\uc744 \ubcf4\uc5ec \uc8fc\ub294 1843\ub144 \uc720\uc801 \ub3c4\ud310", "text": "\uce58\uccb8\uc774\ud2b8\uc0ac \u2014 \ud53c\ub77c\ubbf8\ub4dc \uc606\uc5d0\ub294 \uc6b0\ubb3c\uacfc \uae38\uc774 \uc788\uc5c8\ub2e4 \uc2a4\ud2f0\ube10\uc2a4\uc640 \uce90\uc11c\uc6b0\ub4dc\uc758 \uae30\ub85d\uc5d0\uc11c \ub3c4\uc2dc\uc758 \uacf5\uac04\uc744 \ub113\uac8c \uc77d\uae30 \ud070 \ud53c\ub77c\ubbf8\ub4dc\uc640 \uc8fc\ubcc0 \uad11\uc7a5\u00b7\uc5f4\uc8fc\u00b7\ubb3c \uacf5\uac04\uc744 \uc5f0\uacb0\ud574 \uce58\uccb8\uc774\ud2b8\uc0ac\ub97c \ud558\ub098\uc758 \ub3c4\uc2dc\ub85c \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uba55\uc2dc\ucf54 \uc720\uce74\ud0c4\uc758 \uce58\uccb8\uc774\ud2b8\uc0ac\ub294 \uac70\ub300\ud55c \uacc4\ub2e8\uc2dd \uac74\ucd95\uc73c\ub85c \uc720\uba85\ud558\ub2e4. \uadf8\ub7ec\ub098 \ud53c\ub77c\ubbf8\ub4dc \ud558\ub098\ub9cc\uc73c\ub85c \uace0\ub300 \ub3c4\uc2dc\ub97c \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \uad11\uc7a5\uacfc \uae38, \ubb3c\uc744 \uc5bb\ub294 \uc7a5\uc18c\uc640 \uc5ec\ub7ec \uac74\ucd95\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. 19\uc138\uae30 \uc5ec\ud589 \uae30\ub85d\uacfc \ub3c4\ud310\uc744 \ub2e8\uc11c\ub85c \uc0bc\uc544 \uc720\uc801\uc744 \ud55c \uc7a5\uc758 \uae30\ub150\uc0ac\uc9c4\ubcf4\ub2e4 \ub113\uac8c \uc77d\uc5b4 \ubcf4\uc790. \uc624\ub298 \uc54c\ub824\uc9c4 \uac74\ubb3c \uc774\ub984 \uc911\uc5d0\ub294 \ud6c4\ub300\uc758 \ubc29\ubb38\uc790\uac00 \uc678\ud615\uacfc \uc778\uc0c1\uc5d0 \ub530\ub77c \ubd99\uc778 \uac83\ub3c4 \uc788\ub2e4. \uc131\uc774\ub77c\ub294 \ub73b\uc758 \uc5d8 \uce74\uc2a4\ud2f0\uc694\ub3c4 \uadf8 \ud55c \uc608\ub2e4. \uc774\ub984\uc774 \uc775\uc219\ud558\ub2e4\uace0 \uadf8 \uac74\ubb3c\uc758 \uc6d0\ub798 \uae30\ub2a5\uacfc \uc0ac\uc6a9 \uc2dc\uae30\ub97c \ubaa8\ub450 \uc54c\uac8c \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uce58\uccb8\uc774\ud2b8\uc0ac\uc758 \uc5ec\ub7ec \uac74\ucd95\ub3c4 \uac19\uc740 \ub0a0 \ud55c\uaebc\ubc88\uc5d0 \uc644\uc131\ub41c \ub3c4\uc2dc \ubaa8\ud615\uc774 \uc544\ub2c8\ub2e4. \ub2e4\ub978 \uc2dc\uae30\uc758 \uc791\uc5c5\uacfc \ubcc0\ud654\uac00 \uacb9\uccd0 \uc788\ub2e4. \ud604\uc7ac\uc758 \uc720\uc801\uc744 \ubcfc \ub54c \uac74\ubb3c\ub4e4\uc774 \ubaa8\ub450 \uac19\uc740 \uae30\ub2a5\uc744 \ud588\uace0 \uac19\uc740 \uc9d1\ub2e8\uc774 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc0ac\uc6a9\ud588\ub2e4\uace0 \ub2e8\uc815\ud558\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \uc5d8 \uce74\uc2a4\ud2f0\uc694\uc758 \uacc4\ub2e8\uacfc \uc704\ucabd \uacf5\uac04\uc740 \ub192\uc774\uc758 \ucc28\uc774\ub97c \ub9cc\ub4e0\ub2e4. \uc544\ub798\uc5d0\uc11c \uc62c\ub824\ub2e4\ubcf4\ub294 \uc0ac\ub78c\uacfc \ub192\uc740 \uacf3\uc5d0 \uc788\ub294 \uc0ac\ub78c\uc758 \uad00\uacc4\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \ud070 \uac74\ucd95\uc740 \uc7ac\ub8cc\uc758 \uc591\ubfd0 \uc544\ub2c8\ub77c \uc0ac\ub78c\uc758 \uc2dc\uc120\uacfc \uc774\ub3d9\uc744 \uc870\uc9c1\ud558\ub294 \ud798\uc744 \uac00\uc9c4\ub2e4. \ub3c4\ud310\uc5d0\uc11c\ub294 \uc678\ud615\uc758 \uc120\uc774 \uc798 \ubcf4\uc774\uc9c0\ub9cc \uc2e4\uc81c \uc0ac\uc6a9 \ub54c\uc5d0\ub294 \uc8fc\ubcc0\uc758 \uc18c\ub9ac\uc640 \ub9ce\uc740 \uc0ac\ub78c, \uc758\ub840\uc758 \uc2dc\uac04\uc774 \ub354\ud574\uc84c\uc744 \uac83\uc774\ub2e4. \uc9c0\uae08\uc758 \uc815\uc9c0\ub41c \uac74\ubb3c\uacfc \uacfc\uac70\uc758 \ud65c\ub3d9\uc740 \uac19\uc9c0 \uc54a\ub2e4. \uc720\uc801\uc758 \ud615\ud0dc\ub294 \uadf8 \ud65c\ub3d9\uc744 \uc9c8\ubb38\ud558\uae30 \uc704\ud55c \ucd9c\ubc1c\uc810\uc774\ub2e4. \ud070 \ud53c\ub77c\ubbf8\ub4dc \uc8fc\ubcc0\uc5d0\ub294 \ub113\uc740 \uacf5\uac04\uacfc \uc904\uc9c0\uc740 \uae30\ub465\ub4e4\uc774 \uc788\ub2e4. \uac01\uac01\uc758 \uac74\ubb3c\uc744 \ub530\ub85c \ub5bc\uc5b4 \ubcf4\ub294 \ub300\uc2e0 \uadf8 \uc0ac\uc774\ub97c \uac78\uc5b4\uac04\ub2e4\uace0 \uc0c1\uc0c1\ud558\uba74 \uad00\uacc4\uac00 \ubcf4\uc778\ub2e4. \uae38\uacfc \ube48 \uacf5\uac04\ub3c4 \uac74\ucd95\ub9cc\ud07c \ub3c4\uc2dc\ub97c \uc774\ub8e8\ub294 \uc694\uc18c\ub2e4. \uc0ac\ub78c\uc774 \ubaa8\uc774\uace0 \ud769\uc5b4\uc9c0\ub294 \ubc29\uc2dd, \uc2dc\uc120\uc774 \uc5b4\ub514\ub85c \uc774\uc5b4\uc9c0\ub294\uc9c0 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc9c0\ubd95\uacfc \ubcbd\uc774 \uc0ac\ub77c\uc9c4 \uacf3\uc5d0\uc11c\ub294 \uae30\ub465\ub9cc \ubcf4\uace0 \uc6d0\ub798 \uacf5\uac04\uc744 \ub108\ubb34 \uc27d\uac8c \uc644\uc131\ud574 \uadf8\ub824\uc11c\ub3c4 \uc548 \ub41c\ub2e4. \ub0a8\uc740 \ud754\uc801\uacfc \ubcf5\uc6d0\ud574 \uc0c1\uc0c1\ud55c \ubd80\ubd84\uc744 \ub098\ub204\uc5b4 \ubcf4\ub294 \ud0dc\ub3c4\uac00 \ud544\uc694\ud558\ub2e4. \uc720\uce74\ud0c4\uc758 \ubb3c\uc744 \uc0dd\uac01\ud560 \ub54c\uc5d0\ub294 \uc9c0\ud45c\uc758 \uac15\ub9cc \ub5a0\uc62c\ub9ac\uba74 \ubd80\uc871\ud558\ub2e4. \uc138\ub178\ud14c\ub77c\uace0 \ubd80\ub974\ub294 \uc790\uc5f0\uc801\uc73c\ub85c \ud615\uc131\ub41c \ubb3c \uacf5\uac04\ub4e4\uc774 \uc911\uc694\ud55c \ud48d\uacbd\uc744 \uc774\ub8ec\ub2e4. \uce58\uccb8\uc774\ud2b8\uc0ac\uc758 \uc6b0\ubb3c\ub3c4 \ub3c4\uc2dc\ub97c \uc774\ud574\ud558\ub294 \ub2e8\uc11c\ub2e4. \ubb3c\uc740 \uac70\ub300\ud55c \uac74\ucd95 \ub4a4\uc5d0\uc11c \uc0dd\ud65c\uc758 \uc870\uac74\uc744 \uc81c\uacf5\ud588\ub2e4. \ub2e4\ub9cc \uc720\uc801\uc758 \ubaa8\ub4e0 \ubb3c \uacf5\uac04\uc744 \uac19\uc740 \uc6a9\ub3c4\ub85c \uc0ac\uc6a9\ud588\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc5b4\ub5a4 \uc7a5\uc18c\uc758 \uc885\uad50\uc801 \uc758\ubbf8\uc640 \uc77c\uc0c1\uc801\uc778 \ubb3c \uacf5\uae09\uc744 \uad6c\ubd84\ud574 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc720\uba85\ud55c \uc758\ub840 \uc774\uc57c\uae30\ub9cc \ub0a8\uae30\uba74 \ubb3c\uc744 \uad6c\ud558\uace0 \uc774\ub3d9\ud558\ub358 \ud3c9\ubc94\ud55c \ud544\uc694\uac00 \uac00\ub824\uc9c8 \uc218 \uc788\ub2e4. \uc874 \ub85c\uc774\ub4dc \uc2a4\ud2f0\ube10\uc2a4\uc758 \uc5ec\ud589\uae30\uc5d0\ub294 \ud504\ub808\ub354\ub9ad \uce90\uc11c\uc6b0\ub4dc\uc758 \uad00\ucc30\uc744 \ubc14\ud0d5\uc73c\ub85c \ud55c \ub3c4\ud310\uacfc \uacc4\ud68d\uc774 \uc2e4\ub838\ub2e4. \uc0ac\uc9c4\uc774 \ub110\ub9ac \uc4f0\uc774\uae30 \uc804 \uc720\uc801\uc758 \ubaa8\uc2b5\uc744 \ub2e4\ub978 \ub3c5\uc790\uc5d0\uac8c \uc804\ud558\ub294 \ubc29\ubc95\uc774\uc5c8\ub2e4. \ub098\uc911\uc758 \ubcf5\uad6c \uc774\uc804 \uc0c1\ud0dc\ub97c \uc0dd\uac01\ud558\ub294 \ub370\uc5d0\ub3c4 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \uc120\uc774 \uc788\ub294 \uadf8\ub300\ub85c\uc758 \uc644\ubcbd\ud55c \uce21\uc815\uc774\ub77c\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uad00\ucc30\uc790\uc758 \uc704\uce58\uc640 \uc120\ud0dd\uc774 \uadf8\ub9bc\uc5d0 \ub4e4\uc5b4 \uc788\ub2e4. \ucd9c\ud310\ubb3c\uc758 \uc815\ub3c8\ub41c \uc120\uc740 \uc2e4\uc81c \ud604\uc7a5\uc758 \ubcf5\uc7a1\ud568\uc744 \uc904\uc5ec \ubcf4\uc5ec \uc904 \uc218\ub3c4 \uc788\ub2e4. \uc790\ub8cc\uac00 \ub9cc\ub4e4\uc5b4\uc9c4 \ubc29\ubc95\uc744 \uc544\ub294 \uc77c\ub3c4 \uc720\uc801\uc744 \uc77d\ub294 \uc77c\ubd80\ub2e4. \uacc4\ud68d\ub3c4\uc640 \uac74\ubb3c\uc758 \uc815\uba74 \uadf8\ub9bc\uc740 \uac19\uc740 \uc9c8\ubb38\uc5d0 \ub2f5\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc815\uba74\uc740 \uacc4\ub2e8\uacfc \uc7a5\uc2dd\uc758 \ub192\uc774\ub97c \uc798 \ubcf4\uc5ec \uc8fc\uc9c0\ub9cc, \uacc4\ud68d\ub3c4\ub294 \uc5ec\ub7ec \uacf5\uac04\uc774 \uc5bc\ub9c8\ub098 \ub5a8\uc5b4\uc838 \uc788\uace0 \uc5b4\ub290 \ubc29\ud5a5\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc790\ub8cc\uc758 \uc885\ub958\ub97c \ube44\uad50\ud558\uba74 \ub3c4\uc2dc\uc5d0 \uad00\ud55c \uc11c\ub85c \ub2e4\ub978 \ud06c\uae30\uc758 \uc815\ubcf4\ub97c \uc5bb\uc744 \uc218 \uc788\ub2e4. \ubc18\ub300\ub85c \uc120\uc774 \ub0a8\uc544 \uc788\uc9c0 \uc54a\uc740 \ubd80\ubd84\uc740 \uacc4\ud68d\ub9cc \ubcf4\uace0 \ub9c8\uc74c\ub300\ub85c \ucc44\uc6b0\uae30 \uc27d\ub2e4. \ub3c4\ud310\uc5d0 \uc815\ub3c8\ub41c \uc724\uacfd\uc774 \ubcf4\uc778\ub2e4\uace0 \uace0\ub300 \ub3c4\uc2dc\uc758 \ubaa8\ub4e0 \uae30\ub2a5\uc774 \ud655\uc778\ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. \uac74\ubb3c\uc774 \uc5b4\ub514 \uc788\uc5c8\ub294\uc9c0\uc640 \uadf8 \uc548\uc5d0\uc11c \ubb34\uc2a8 \uc77c\uc774 \uc5b8\uc81c \uc774\ub8e8\uc5b4\uc84c\ub294\uc9c0\ub294 \ub2e4\ub978 \uc9c8\ubb38\uc774\ub2e4. \uc2a4\ud2f0\ube10\uc2a4\uc758 \uae30\ub85d\uc744 \ud604\uc7ac\uc758 \uc644\uc131\ub41c \uc548\ub0b4\uc11c\ubcf4\ub2e4 \ub2f9\uc2dc\uc758 \uad00\ucc30\uacfc \ucd94\uc815\uc774 \ud568\uaed8 \ub2f4\uae34 \uc790\ub8cc\ub85c \uc77d\uc73c\uba74, \uc624\ub798\ub41c \ub3c4\ud310\uc744 \ub354 \uc815\ud655\ud558\uac8c \ud65c\uc6a9\ud560 \uc218 \uc788\ub2e4. \uc9c0\ub098\uce58\uac8c \ud655\uc2e0\ud558\ub294 \uc124\uba85\ubcf4\ub2e4 \ub0a8\uc740 \uc99d\uac70\ub97c \ub530\ub77c \uc9c8\ubb38\uc744 \ub098\ub204\ub294 \ud3b8\uc774 \uc720\uc801\uc758 \ubcf5\uc7a1\ud568\uc744 \uc9c0\ud0a8\ub2e4. \uc5ec\ud589\uae30\ub294 \uc678\ubd80\uc778\uc5d0\uac8c \uc0c8\ub85c\uc6b4 \uc7a5\uc18c\ub97c \uc18c\uac1c\ud558\uc9c0\ub9cc \uadf8\uacf3\uc744 \uc54c\ub358 \uc0ac\ub78c\uacfc \uae38\uc744 \uc548\ub0b4\ud55c \uc8fc\ubbfc\ub3c4 \uc788\uc5c8\ub2e4. \uc720\ub7fd\uacfc \ubd81\ubbf8\uc758 \ub3c5\uc790\uc5d0\uac8c \uc54c\ub824\uc9c4 \uc2dc\uc810\uacfc \uc9c0\uc5ed\uc758 \uc9c0\uc2dd\uc774 \uc874\uc7ac\ud55c \uc2dc\uac04\uc740 \ub2e4\ub974\ub2e4. \ubc1c\uacac\uc774\ub77c\ub294 \ub9d0\uc740 \ub204\uad6c\uc758 \uacbd\ud5d8\uc778\uc9c0 \ubc1d\ud600 \uc4f8 \ud544\uc694\uac00 \uc788\ub2e4. \ub610\ud55c \uc61b \uae00\uc5d0\ub294 \uc8fc\ubbfc\uacfc \uace0\ub300 \ubb38\uba85\uc744 \ud3c9\uac00\ud558\ub294 \ub2f9\uc2dc\uc758 \ud3b8\uacac\uc774 \uc11e\uc5ec \uc788\ub2e4. \uac74\ubb3c\uc758 \uad00\ucc30\uacfc \uc0ac\ub78c\uc5d0 \ub300\ud55c \ub2e8\uc815\uc740 \ub098\ub204\uc5b4 \uc77d\uc5b4\uc57c \ud55c\ub2e4. \ub9c8\uc57c\uc758 \uc720\uc801\uc744 \uc124\uba85\ud558\uba74\uc11c \uc9c0\uae08\uc758 \uc0ac\ub78c\ub4e4\uc774 \uc0ac\ub77c\uc9c4 \ubb38\uba85\uc758 \ubc30\uacbd \uc778\ubb3c\ucc98\ub7fc \ucde8\uae09\ub418\uc9c0 \uc54a\uac8c \ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \uce58\uccb8\uc774\ud2b8\uc0ac\ub97c \ubcfc \ub54c\uc5d0\ub294 \uac00\uc7a5 \uc720\uba85\ud55c \uac74\ubb3c\uc5d0\uc11c \uc2dc\uc120\uc744 \uc7a0\uc2dc \ub3cc\ub824 \ubcf4\uc790. \uc8fc\ubcc0\uc758 \uae38\uacfc \uae30\ub465, \ubb3c \uacf5\uac04\uc744 \ud568\uaed8 \ubcf4\uba74 \ud55c \uae30\ub150\ubb3c\uc5d0\uc11c \ub3c4\uc2dc\uc758 \uad00\uacc4\ub85c \uc9c8\ubb38\uc774 \ub113\uc5b4\uc9c4\ub2e4. \ubb34\uc5c7\uc744 \ub9cc\ub4e4\uc5c8\ub294\uc9c0\uc640 \uadf8 \uc0ac\uc774\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc600\ub294\uc9c0\ub97c \ud568\uaed8 \ubcfc \uc218 \uc788\ub2e4. \ub3c4\uc2dc\uc758 \uc5ed\uc0ac\ub294 \uac70\ub300\ud55c \ub3cc\uc744 \uc313\uc740 \ub2a5\ub825\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc774\uace0 \ubb3c\uc744 \uc5bb\uace0 \uc758\ubbf8\ub97c \ubd80\uc5ec\ud55c \uc7a5\uc18c\ub4e4\uc758 \uc5f0\uacb0\uc774\ub2e4. \uce58\uccb8\uc774\ud2b8\uc0ac\ub294 \ud53c\ub77c\ubbf8\ub4dc\uc758 \uc724\uacfd\uc744 \uae30\uc5b5\ud558\ub294 \uac83\uc5d0\uc11c \uc2dc\uc791\ud574, \ud070 \uac74\ucd95\uacfc \uc791\uc740 \uc774\ub3d9\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \uc0ac\ub78c\ub4e4\uc774 \uc774\uc6a9\ud55c \uacf5\uac04\uc774 \ub5a0\uc624\ub978\ub2e4. \uadf8 \uc724\uacfd\uc744 \ub458\ub7ec\uc2fc \uc0dd\ud65c\uacfc \uc758\ub840\uc758 \uc9c0\ub3c4\ub97c \uc0dd\uac01\ud558\uac8c \ud558\ub294 \uc720\uc801\uc774\ub2e4."}, {"id": "china-examinations-cells-books-and-office", "title": "\uc911\uad6d\uc758 \uacfc\uac70\uc81c \u2014 \uc791\uc740 \uce78\uc5d0\uc11c \uce58\ub978 \uc2dc\ud5d8\uc740 \ub204\uad6c\uc5d0\uac8c \uae38\uc744 \uc5f4\uc5c8\uc744\uae4c", "summary": "\uba85\uccad\ub300 \uacfc\uac70\uc758 \uacf5\ubd80\uc640 \ub2e8\uacc4, \uc2dc\ud5d8\uc7a5\uacfc \ube44\uc6a9,1905\ub144 \ud3d0\uc9c0\uae4c\uc9c0 \uae30\ud68c\uc640 \uc81c\ub3c4\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/china-examinations-cells-books-and-office/index.html", "image": "../media/china-examinations-cells-books-and-office.jpg", "alt": "\ubca0\uc774\uc9d5 \uacfc\uac70 \uc2dc\ud5d8\uc7a5\uc758 \uc904\uc9c0\uc740 \uc751\uc2dc \uce78\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc2e4\uc81c \uc5ed\uc0ac \ub3c4\ud310", "text": "\uc911\uad6d\uc758 \uacfc\uac70\uc81c \u2014 \uc791\uc740 \uce78\uc5d0\uc11c \uce58\ub978 \uc2dc\ud5d8\uc740 \ub204\uad6c\uc5d0\uac8c \uae38\uc744 \uc5f4\uc5c8\uc744\uae4c \uacbd\uc804\uacfc \uc751\uc2dc \uce78, \uad50\uc721\ube44\uc640 \uad00\uc9c1 \uc0ac\uc774\uc758 \uae34 \uc2dc\uac04 \uba85\uccad\ub300 \uacfc\uac70\uc758 \uacf5\ubd80\uc640 \ub2e8\uacc4, \uc2dc\ud5d8\uc7a5\uacfc \ube44\uc6a9,1905\ub144 \ud3d0\uc9c0\uae4c\uc9c0 \uae30\ud68c\uc640 \uc81c\ub3c4\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ub2f4\uc7a5 \uc548\uc5d0 \uc791\uc740 \uce78\ub4e4\uc774 \uc904\uc9c0\uc5b4 \uc788\uace0 \uc751\uc2dc\uc790\ub294 \ucc45\uc5d0\uc11c \uc775\ud78c \ubb38\uc7a5\uc744 \ub2f5\uc548\uc73c\ub85c \ubc14\uafbc\ub2e4. \uc911\uad6d\uc758 \uacfc\uac70\uc81c\ub294 \uc2dc\ud5d8\uc73c\ub85c \uad00\ub8cc\ub97c \ubf51\uc740 \uc81c\ub3c4\ub77c\ub294 \ud55c \uc904\ub85c \uc790\uc8fc \uc124\uba85\ub41c\ub2e4. \uadf8\ub7ec\ub098 \uacf5\ubd80\ud560 \uc218 \uc788\ub294 \uc0ac\ub78c\uacfc \ud569\uaca9 \ub4a4\uc758 \uae38, \uc2dc\ud5d8\uc7a5\uc758 \ud1b5\uc81c\uae4c\uc9c0 \uc0b4\ud3b4\ubcf4\uba74 \ub2a5\ub825\uacfc \uae30\ud68c\uc758 \uad00\uacc4\uac00 \ud6e8\uc52c \ubcf5\uc7a1\ud558\uac8c \ubcf4\uc778\ub2e4. \uad00\ub9ac\ub97c \ubf51\ub294 \ubc29\ubc95\uc740 \ud55c \uc2dc\ub300 \ub0b4\ub0b4 \uac19\uc9c0 \uc54a\uc558\ub2e4. \uacfc\uac70\uc81c \uc5ed\uc2dc \uc218\u00b7\ub2f9\ub300\uc758 \uc804\uac1c \uc774\ud6c4 \uc1a1\ub300\uc640 \uba85\u00b7\uccad\ub300\ub97c \uac70\uce58\uba70 \ud615\ud0dc\uc640 \uc911\uc694\uc131\uc774 \ub2ec\ub77c\uc84c\ub2e4. \uc624\ub298 \uc2dc\ud5d8\uc758 \uaddc\uce59\uc744 \ubaa8\ub4e0 \uc655\uc870\uc5d0 \uc18c\uae09\ud574\uc11c \uc801\uc6a9\ud560 \uc218 \uc5c6\ub294 \uac83\uacfc \uac19\ub2e4. \uc2dc\ud5d8\uc744 \ud1b5\ud574 \uacbd\uc804\uc744 \uc775\ud788\uace0 \uae00\uc744 \uc4f0\ub294 \ub2a5\ub825\uc744 \ud3c9\uac00\ud55c\ub2e4\ub294 \uc6d0\uce59\uc740 \uac00\ubb38\uacfc \ucd94\ucc9c\ub9cc\uc73c\ub85c \uc0ac\ub78c\uc744 \uace0\ub974\ub294 \ubc29\uc2dd\uacfc \ub2e4\ub978 \ud1b5\ub85c\ub97c \ub9cc\ub4e4\uc5c8\ub2e4. \ub2e4\ub9cc \uc61b \uadc0\uc871\uc774 \uc0ac\ub77c\uc9c0\uace0 \ub204\uad6c\ub098 \ucd9c\ubc1c\uc120\uc5d0 \uc120 \ud3c9\ub4f1\ud55c \uc0ac\ud68c\uac00 \ub418\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc6d0\uce59\uacfc \uc2e4\uc81c \uc774\uc6a9 \uc870\uac74\uc740 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ud558\ub098\uc758 \uc2dc\ud5d8\uc744 \uc5ec\ub7ec \uc9c0\uc5ed \uc0ac\ub78c\uc774 \uac19\uc740 \uad8c\uc704\uc758 \uae30\uc900\uc73c\ub85c \uc900\ube44\ud588\ub2e4\ub294 \uc810\uc740 \uad6d\uac00 \ud1b5\ud569\uacfc\ub3c4 \uc5f0\uacb0\ub41c\ub2e4. \ub2e4\ub9cc \uacf5\ud1b5\uc758 \uae00\uc744 \uacf5\ubd80\ud55c\ub2e4\uace0 \uc9c0\uc5ed\uc758 \ub9d0\uacfc \uc0dd\ud65c\uc774 \ubaa8\ub450 \uac19\uc544\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2dc\ud5d8\uc774 \ub9cc\ub4e0 \uc5f0\uacb0\uacfc \uadf8 \ubc16\uc5d0 \ub0a8\uc740 \ucc28\uc774\ub97c \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ud2b9\ud788 \uba85\u00b7\uccad\ub300 \uc2dc\ud5d8\uc5d0\uc11c\ub294 \uc720\uad50 \uacbd\uc804\uacfc \uadf8 \ud574\uc11d, \uc815\ud574\uc9c4 \ubc29\uc2dd\uc758 \uae00\uc4f0\uae30\uac00 \uc911\uc694\ud588\ub2e4. \uc751\uc2dc\uc790\ub294 \ub2e8\uc21c\ud788 \ub9ce\uc740 \ubb38\uc7a5\uc744 \uc678\uc6b0\ub294 \uac83\uc744 \ub118\uc5b4 \uad8c\uc704 \uc788\ub294 \uae00\uc744 \ud574\uc11d\ud558\uace0 \uaddc\ubc94\uc5d0 \ub9de\ucd94\uc5b4 \ub17c\uc9c0\ub97c \uad6c\uc131\ud574\uc57c \ud588\ub2e4. \uc2dc\ud5d8 \ud615\uc2dd \uc790\uccb4\ub97c \uc775\ud788\ub294 \uc77c\ub3c4 \ud070 \uacf5\ubd80\uc600\ub2e4. \uc774 \uacfc\uc815\uc740 \uc11c\ub85c \ub2e4\ub978 \uc9c0\uc5ed \ucd9c\uc2e0\uc758 \uc5d8\ub9ac\ud2b8\uac00 \uacf5\ud1b5\uc758 \uae00\uacfc \uac00\uce58\ub85c \uc774\uc57c\uae30\ud558\uac8c \ub9cc\ub4e4\uc5c8\ub2e4. \ubc18\uba74 \ubb34\uc5c7\uc774 \uc88b\uc740 \uc9c0\uc2dd\uc778\uc9c0\ub97c \uc881\uc740 \ubc94\uc704\ub85c \uc815\ud558\ub294 \ud6a8\uacfc\ub3c4 \uc788\uc5c8\ub2e4. \uacfc\uac70\uc758 \uc758\ubbf8\ub97c \uc624\ub298\ub0a0\uc758 \uc0c1\uc2dd \uc2dc\ud5d8\uc774\ub098 \ud2b9\uc815 \uc9c1\uc5c5\uc758 \uc2e4\ubb34 \uc2dc\ud5d8\uacfc \uc644\uc804\ud788 \uac19\ub2e4\uace0 \uc0dd\uac01\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \uc751\uc2dc\uc640 \ud559\uc704\uc758 \uccb4\uacc4\ub294 \uc5ec\ub7ec \ub2e8\uacc4\ub85c \uc774\ub8e8\uc5b4\uc84c\ub2e4. \uc9c0\ubc29\uc5d0\uc11c \uc790\uaca9\uc744 \uc5bb\uc740 \ub4a4 \ub354 \ub192\uc740 \uc9c0\uc5ed\uacfc \uc218\ub3c4\uc758 \uc2dc\ud5d8\uc73c\ub85c \ub098\uc544\uac00\ub294 \uae38\uc740 \uc18c\uc218\uc5d0\uac8c \uc5f4\ub838\ub2e4. \ud55c \ubc88 \uc2dc\ud5d8\uc744 \uc798 \ubcf4\uba74 \uc989\uc2dc \ub192\uc740 \uad00\ub9ac\uac00 \ub41c\ub2e4\ub294 \uc2dd\uc758 \ub2e8\uc21c\ud55c \uc0ac\ub2e4\ub9ac\ub294 \uc544\ub2c8\uc5c8\ub2e4. \ud559\uc704\uc640 \uc2e4\uc81c \uad00\uc9c1\uc758 \uc784\uba85\ub3c4 \uac19\uc740 \uc77c\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc2dc\ud5d8\uc744 \ud1b5\uacfc\ud55c \uc0ac\ub78c \uac00\uc6b4\ub370 \ub204\uac00 \uc5b8\uc81c \uc5b4\ub5a4 \uc790\ub9ac\ub97c \uc5bb\ub294\uc9c0\ub294 \ubcc4\ub3c4\uc758 \uc808\ucc28\uc640 \uc870\uac74\uc5d0 \ub2ec\ub838\ub2e4. \uc81c\ub3c4\ub97c \uc774\ud574\ud558\ub824\uba74 \ud569\uaca9\uc790\ub97c \ubf51\ub294 \uc21c\uac04\ubfd0 \uc544\ub2c8\ub77c \uacf5\ubd80\uc5d0\uc11c \uc784\uba85\uae4c\uc9c0 \uc774\uc5b4\uc9c0\ub294 \uae34 \uc2dc\uac04\uc744 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc791\uc740 \uce78\uacfc \ub2f4\uc7a5, \ucd9c\uc785 \uc808\ucc28\ub294 \uc751\uc2dc\uc790\uc758 \uc9d1\uc911\uc744 \ub3d5\ub294 \ub3d9\uc2dc\uc5d0 \uae34 \uc2dc\uac04\uc744 \uacac\ub38c\uc57c \ud558\ub294 \ud658\uacbd\uc774\uc5c8\ub2e4. \uc2dc\ud5d8\uc744 \uae00\uc758 \uc6b0\uc5f4\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uba74 \ubc24\uacfc \ub0a0\uc528, \uc74c\uc2dd\uacfc \ud53c\ub85c\uc758 \uc870\uac74\uc774 \ube60\uc9c4\ub2e4. \ub2f5\uc548\uc740 \uc0ac\ub78c\uc758 \ubab8\uacfc \uc0dd\ud65c\uc5d0\uc11c \ubd84\ub9ac\ub41c \uc0c1\ud0dc\ub85c \ub9cc\ub4e4\uc5b4\uc9c0\uc9c0 \uc54a\uc558\ub2e4. \uc0ac\ubb34\uc5d8 \uc6f0\uc2a4 \uc70c\ub9ac\uc5c4\uc2a4\uc758 \u300e\uc911\uad6d\u300f\uc5d0\ub294 \ubca0\uc774\uc9d5 \uacf5\uc6d0, \uace7 \uacfc\uac70 \uc2dc\ud5d8\uc7a5\uc758 \ub0b4\ubd80 \ub3c4\ud310\uc774 \uc2e4\ub824 \uc788\ub2e4. \uc904\uc9c0\uc740 \uc751\uc2dc \uce78\uc740 \ud55c \uc0ac\ub78c\uc774 \uc815\ud574\uc9c4 \uacf5\uac04\uc5d0\uc11c \ub2f5\uc548\uc744 \uc4f0\ub3c4\ub85d \ub098\ub204\ub294 \uad6c\uc870\ub2e4. \uc2dc\ud5d8\uc740 \uae00\uc758 \ub0b4\uc6a9\ub9cc \uc544\ub2c8\ub77c \ubab8\uacfc \ubb3c\uac74\uc758 \uc774\ub3d9\ub3c4 \uad00\ub9ac\ud588\ub2e4. \ubc18\uc785\ubb3c\uc744 \uc0b4\ud53c\uace0 \uc2e0\uc6d0\uc744 \ud655\uc778\ud558\uba70 \ub2f5\uc548\uc744 \ucc98\ub9ac\ud558\ub294 \uc808\ucc28\uc5d0\ub294 \ubd80\uc815\ud589\uc704\ub97c \ub9c9\uc73c\ub824\ub294 \ubaa9\uc801\uc774 \uc788\uc5c8\ub2e4. \uc77c\ubd80 \uc2dc\ub300\uc758 \uc774\ub984 \uac00\ub9ac\uae30\uc640 \ub2f5\uc548 \uc62e\uaca8 \uc4f0\uae30 \uac19\uc740 \ubc29\ubc95\ub3c4 \ud3c9\uac00\uc790\uc640 \uc751\uc2dc\uc790\uc758 \uc9c1\uc811\uc801\uc778 \uad00\uacc4\ub97c \uc904\uc774\ub824 \ud588\ub2e4. \uadf8\ub7ec\ub098 \uc7a5\uce58\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ubd80\uc815\uc774 \uc804\ud600 \uc5c6\uc5c8\ub2e4\ub294 \uc99d\uac70\ub294 \uc544\ub2c8\ub2e4. \ud615\uc2dd\uc0c1 \ud608\ud1b5\ub9cc\uc73c\ub85c \ub9c9\ud788\uc9c0 \uc54a\ub294\ub2e4\ub294 \uac83\uacfc \ub204\uad6c\ub098 \uc624\ub798 \uacf5\ubd80\ud560 \uc218 \uc788\ub2e4\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \ucc45\uacfc \uc2a4\uc2b9, \uc900\ube44\ud558\ub294 \ub3d9\uc548\uc758 \uc0dd\uacc4, \uc2dc\ud5d8\uc7a5\uae4c\uc9c0 \uc774\ub3d9\ud558\ub294 \ube44\uc6a9\uc774 \ud544\uc694\ud588\ub2e4. \uac00\uc871\uacfc \uc9c0\uc5ed\uc758 \uc9c0\uc6d0\uc740 \uc751\uc2dc\uc790\uc758 \ub2a5\ub825\uc774 \ub4dc\ub7ec\ub0a0 \uae30\ud68c \uc790\uccb4\ub97c \ubc14\uafb8\uc5c8\ub2e4. \ud569\uaca9\uc790 \ud55c \uba85\uc774 \uac00\ubb38\uc758 \uba85\uc608\ub97c \ub192\uc77c \uc218 \uc788\uc5c8\uc73c\ubbc0\ub85c \uacf5\ubd80\ub294 \uac1c\uc778\uc758 \ub178\ub825\uc778 \ub3d9\uc2dc\uc5d0 \uac00\uc871\uc758 \uc0ac\uc5c5\ucc98\ub7fc \ub418\uae30\ub3c4 \ud588\ub2e4. \uc5ec\uc131\uacfc \uc5ec\ub7ec \uc2e0\ubd84 \uc9d1\ub2e8\uc758 \ubc30\uc81c \uc5ed\uc2dc \uace0\ub824\ud574\uc57c \ud55c\ub2e4. \uacfc\uac70\ub97c \uacf5\uc815\ud55c \uacbd\uc7c1\uc758 \uc644\uc131\uc73c\ub85c \uce6d\ucc2c\ud558\uac70\ub098 \ubd80\ud328\ud55c \ud615\uc2dd\ubfd0\uc774\uc5c8\ub2e4\uace0 \ud3c4\ud558\ud558\uba74 \uc774\ub7f0 \uae34\uc7a5\uc744 \ub193\uce5c\ub2e4. \uacfc\uac70\uc758 \ud3d0\uc9c0\ub294 \uc0ac\ub78c\uc744 \uace0\ub974\ub294 \ubc29\uc2dd\uc758 \ubcc0\ud654\uc774\uc790 \ubb34\uc5c7\uc744 \ubc30\uc6b8 \uac83\uc778\uc9c0\uc5d0 \uad00\ud55c \uc2e0\ud638\uc600\ub2e4. \uc0c8 \ud559\uad50\uc5d0\uc11c \uc5b4\ub5a4 \uc9c0\uc2dd\uc744 \uac00\ub974\uce58\uace0 \uc878\uc5c5\uc744 \uc5b4\ub5bb\uac8c \uc778\uc815\ud560\uc9c0\uac00 \uc911\uc694\ud574\uc84c\ub2e4. \uc61b \uc2dc\ud5d8\uc744 \uc5c6\uc560\ub294 \uacb0\uc815\ub9cc\uc73c\ub85c \uc0c8 \uc778\uc7ac \uc591\uc131 \uccb4\uacc4\uac00 \uc989\uc2dc \uc644\uc131\ub418\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ubaa8\ub4e0 \uacf5\ubd80\uac00 \ub192\uc740 \uad00\ub9ac\uac00 \ub418\ub294 \uacb0\uacfc\ub85c \uc774\uc5b4\uc9c0\uc9c0\ub294 \uc54a\uc558\ub2e4. \ud559\uc704\ub97c \uc9c0\ub2cc \uc0ac\ub78c\ub4e4\uc740 \uace0\ud5a5\uc5d0\uc11c \uad50\uc721\uacfc \uc9c0\uc5ed \uc0ac\uc5c5, \ubb38\uc11c \uc791\uc131\uacfc \uc5ec\ub7ec \uacf5\uc801 \ud65c\ub3d9\uc5d0 \uad00\uc5ec\ud560 \uc218 \uc788\uc5c8\ub2e4. \uc2dc\ud5d8\uc740 \uad00\ub8cc\ub9cc\uc774 \uc544\ub2c8\ub77c \uc9c0\uc5ed \uc5d8\ub9ac\ud2b8\uc758 \uc9c0\uc704\uc640 \uc0dd\ud65c \ubc29\uc2dd\ub3c4 \ub9cc\ub4dc\ub294 \uc81c\ub3c4\uc600\ub2e4. \ubc18\ub300\ub85c \ubc18\ubcf5\ud574\uc11c \ub099\ubc29\ud55c \uc0ac\ub78c\uc774 \uacaa\ub294 \uc2dc\uac04\uacfc \ube44\uc6a9\uc758 \uc190\uc2e4\ub3c4 \uc788\uc5c8\ub2e4. \uc751\uc2dc\uc790\uc758 \uc0dd\uc560\ub97c \ub9c8\uc9c0\ub9c9 \ud569\uaca9 \uc5ec\ubd80 \ud558\ub098\ub85c\ub9cc \uc77d\uc73c\uba74 \uc81c\ub3c4\uac00 \uc218\ub9ce\uc740 \uac00\uc815\uc5d0 \ub0a8\uae34 \uc601\ud5a5\uc744 \uc124\uba85\ud558\uae30 \uc5b4\ub835\ub2e4. \uc2dc\ud5d8\uc7a5 \ubc16\uc5d0\uc11c \uc774\uc5b4\uc9c4 \uacf5\ubd80\uc640 \uae30\ub300 \uc5ed\uc2dc \uacfc\uac70\uc758 \uc5ed\uc0ac\uc5d0 \uc18d\ud55c\ub2e4. \uccad \ub9d0 \uac1c\ud601 \uacfc\uc815\uc5d0\uc11c 1905\ub144 \uacfc\uac70\uc81c\uac00 \ud3d0\uc9c0\ub418\uc5c8\ub2e4. \uc0c8 \ud559\uad50\uc640 \ub2e4\ub978 \ud559\ubb38\uc744 \ud1b5\ud574 \uc778\uc7ac\ub97c \uae30\ub974\ub824\ub294 \ubc29\ud5a5\uc740 \uc624\ub79c \uacbd\uc804 \uacf5\ubd80\uc640 \uad00\uc9c1\uc758 \uc5f0\uacb0\uc744 \ud754\ub4e4\uc5c8\ub2e4. \uc774\ubbf8 \uadf8 \uae38\uc5d0 \ub9ce\uc740 \uc2dc\uac04\uc744 \uc4f4 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc0b6\uc758 \uacc4\ud68d \uc790\uccb4\uac00 \ub2ec\ub77c\uc9c0\ub294 \uc77c\uc774\uc5c8\ub2e4. \uc774 \uae00\uc740 \uc8fc\ub85c \uba85\u00b7\uccad\ub300\uc758 \uc6b4\uc601\uacfc 19\uc138\uae30 \uae30\ub85d\uc744 \uc911\uc2ec\uc73c\ub85c \uc77d\uc5c8\uc73c\uba70 \uc61b \uc800\uc790\uc758 \ubbfc\uc871\ubcc4 \ub2a5\ub825\uc5d0 \uad00\ud55c \ud3b8\uacac\uc740 \ub530\ub974\uc9c0 \uc54a\uc558\ub2e4. \uc791\uc740 \uce78\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ub3c4\ud310 \ub4a4\uc5d0\ub294 \uc2dc\ud5d8 \ubb38\uc81c\ubfd0 \uc544\ub2c8\ub77c \ub204\uac00 \ubc30\uc6b0\uace0 \uc5b4\ub5a4 \uc9c0\uc2dd\uc73c\ub85c \uad6d\uac00\uc5d0 \ucc38\uc5ec\ud560 \uc218 \uc788\ub294\uac00\ub77c\ub294 \ud070 \uc9c8\ubb38\uc774 \ub4e4\uc5b4 \uc788\ub2e4."}, {"id": "china-wheelbarrows-chengdu-roads-and-loads", "title": "\uc911\uad6d\uc758 \uc678\ubc14\ud034\uc218\ub808 \u2014 \ubc14\ud034 \ud558\ub098\ub85c \uc881\uc740 \uae38\uc744 \uc787\ub2e4", "summary": "\uccad\ub450\uc640 \ubd81\ubd80\uc758 \uc678\ubc14\ud034\uc218\ub808 \uc0ac\uc9c4\uc744 \ubc14\ud0d5\uc73c\ub85c \uc881\uc740 \uae38\uacfc \uc6b4\uc1a1 \ub178\ub3d9\uc758 \uad00\uacc4\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/china-wheelbarrows-chengdu-roads-and-loads/index.html", "image": "../media/china-wheelbarrows-chengdu-roads-and-loads.jpg", "alt": "\ud070 \uc911\uc559 \ubc14\ud034\uc640 \uc591\uc606 \uc9d0\uc744 \uac16\ucd98 \uccad\ub450 \ud3c9\uc57c \uc678\ubc14\ud034\uc218\ub808\uc758 \uc2e4\uc81c \uc5ed\uc0ac \uc0ac\uc9c4", "text": "\uc911\uad6d\uc758 \uc678\ubc14\ud034\uc218\ub808 \u2014 \ubc14\ud034 \ud558\ub098\ub85c \uc881\uc740 \uae38\uc744 \uc787\ub2e4 \uccad\ub450\uc640 \ubd81\ubd80\uc758 \uc5ed\uc0ac \uc0ac\uc9c4\uc73c\ub85c \ubcf4\ub294 \uc911\uc559 \ubc14\ud034\uc640 \uc6b4\uc1a1\uc758 \uae30\uc220 \uccad\ub450\uc640 \ubd81\ubd80\uc758 \uc678\ubc14\ud034\uc218\ub808 \uc0ac\uc9c4\uc744 \ubc14\ud0d5\uc73c\ub85c \uc881\uc740 \uae38\uacfc \uc6b4\uc1a1 \ub178\ub3d9\uc758 \uad00\uacc4\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ud070 \ubc14\ud034 \ud558\ub098\ub97c \uac00\uc6b4\ub370 \ub450\uace0 \uc9d0\uc744 \uc591\uc606\uc5d0 \uc2e4\uc740 \uc218\ub808\uac00 \uae38\uc744 \uac04\ub2e4. \uc775\uc219\ud55c \uc190\uc218\ub808\uc640 \ub2ee\uc558\uc9c0\ub9cc \ubc14\ud034\uc758 \uc704\uce58\uc640 \uc9d0\uc758 \ubc30\uce58\uac00 \ub2e4\ub974\ub2e4. 20\uc138\uae30 \ucd08 \uc0ac\uc9c4\uc9d1 \u300e\uc911\uad6d\uc758 \ud48d\uacbd\u300f\uc5d0\ub294 \uccad\ub450 \ud3c9\uc57c\uc640 \uc911\uad6d \ubd81\ubd80\uc758 \uc678\ubc14\ud034\uc218\ub808\uac00 \ub530\ub85c \uc18c\uac1c\ub418\uc5b4 \uc788\ub2e4. \uc791\uc740 \uc6b4\uc1a1 \ub3c4\uad6c\ub97c \ud1b5\ud574 \ub2f9\uc2dc \uc9c0\uc5ed\uc758 \uae38\uacfc \uc0ac\ub78c, \ubb3c\uc790\uc758 \uc6c0\uc9c1\uc784\uc744 \uc77d\uc5b4 \ubcf4\uc790. \uc815\uc6d0\uc5d0\uc11c \uc4f0\ub294 \uc218\ub808\ub294 \ubc14\ud034\uac00 \uc55e\uc5d0 \uc788\uace0 \uc0ac\ub78c\uc774 \ub4a4\uc5d0\uc11c \uc9d0\uc758 \uc77c\ubd80 \ubb34\uac8c\ub97c \ub4e4\uc5b4 \uc62c\ub9ac\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4. \uc0ac\uc9c4\uc9d1\uc758 \uc911\uad6d \uc218\ub808\ub294 \ud070 \ubc14\ud034\ub97c \uac00\uc6b4\ub370 \ub450\uace0 \uadf8 \uc8fc\ubcc0\uc5d0 \uc9d0\uc744 \ub193\ub294\ub2e4. \ubb34\uac8c\ub97c \ubc14\ud034 \uac00\uae4c\uc774 \ubc30\uce58\ud558\ub294 \ubc29\uc2dd\uc774 \ub208\uc5d0 \ub748\ub2e4. \uc774\ub807\uac8c \ud558\uba74 \uc0ac\ub78c\uc774 \ubaa8\ub4e0 \ud558\uc911\uc744 \ud314\ub85c \ubc1b\uce60 \ud544\uc694\uac00 \uc904\uc5b4\ub4e0\ub2e4. \ubb3c\ub860 \uc218\ub808\uac00 \uc800\uc808\ub85c \uac00\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc00\uace0 \ub2f9\uae30\ub294 \ud798\uacfc \uade0\ud615 \uc870\uc808\uc774 \ud544\uc694\ud558\ub2e4. \uc5b4\ub290 \uc815\ub3c4\uc758 \uc9d0\uc744 \uc62e\uae38 \uc218 \uc788\ub294\uc9c0\ub294 \uae38\uc758 \uacbd\uc0ac\uc640 \ub178\uba74, \uc9d0\uc758 \uc885\ub958, \ud568\uaed8 \uc77c\ud558\ub294 \uc778\uc6d0\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c4\ub2e4. \uc218\ub808\uc758 \ubc14\ud034\uac00 \ud558\ub098\ub77c\ub294 \uc810\uc740 \uae38\uc758 \ud3ed\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc591\ucabd \ubc14\ud034\ub97c \uc704\ud55c \ub113\uace0 \uace0\ub978 \ub178\uba74\uc774 \uc5c6\uc5b4\ub3c4 \uc9c0\ub098\uac08 \uc5ec\uc9c0\uac00 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ub18d\uc9c0\uc640 \ub9c8\uc744 \uc0ac\uc774\uc758 \uc881\uc740 \uae38\uc5d0\uc11c \uc5b4\ub5a4 \uc6b4\uc1a1 \uc218\ub2e8\uc774 \uc720\ub9ac\ud55c\uc9c0\ub294 \ud070 \ub3c4\ub85c\uc758 \uae30\uc900\ub9cc\uc73c\ub85c \ud310\ub2e8\ud560 \uc218 \uc5c6\ub2e4. \uadf8 \ub300\uc2e0 \ud55c\ucabd\uc73c\ub85c \uae30\uc6b8\uc9c0 \uc54a\ub3c4\ub85d \uc9d0\uc744 \ub193\uace0 \uacc4\uc18d \uc790\uc138\ub97c \uace0\uccd0\uc57c \ud55c\ub2e4. \uc7a5\uc810\uc744 \uc5bb\ub294 \uc790\ub9ac\uc5d0 \ub2e4\ub978 \uae30\uc220\uacfc \uc218\uace0\uac00 \ud544\uc694\ud574\uc9c4\ub2e4. \uc0ac\uc9c4\uc744 \ubcf4\uba74 \ubc14\ud034\uc758 \ubaa8\uc591\ubfd0 \uc544\ub2c8\ub77c \uc190\uc7a1\uc774\ub97c \uc7a1\uc740 \uc0ac\ub78c\uacfc \ubab8\uc758 \ubc29\ud5a5\ub3c4 \ud568\uaed8 \ubcf4\uc544\uc57c \ud558\ub294 \uc774\uc720\ub2e4. \uc0ac\uc9c4 \uc18d \uc218\ub808\uac00 \ub3c4\uc2dc\uc758 \ud070\uae38\ubcf4\ub2e4 \ubc2d \uc0ac\uc774\uc5d0 \ub354 \uc5b4\uc6b8\ub824 \ubcf4\uc778\ub2e4\uace0 \ud574\uc11c \uadf8 \uc77c\uc744 \uc791\uace0 \ubd80\ucc28\uc801\uc778 \uac83\uc73c\ub85c \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uc7a5\uac70\ub9ac \ubc30\ub098 \ud070 \uc218\uc1a1\ub9dd\uc774 \uc788\uc5b4\ub3c4 \ub9c8\uc9c0\ub9c9\uc758 \uc881\uc740 \uad6c\uac04\uc774 \uc774\uc5b4\uc9c0\uc9c0 \uc54a\uc73c\uba74 \ubb3c\uac74\uc740 \ubaa9\uc801\uc9c0\uc5d0 \ub3c4\ucc29\ud558\uc9c0 \ubabb\ud55c\ub2e4. \uc0ac\uc9c4\uc9d1\uc740 \uccad\ub450 \ud3c9\uc57c\uc758 \ub18d\uc5c5 \uc0dd\uc0b0\uacfc \ub9ce\uc740 \ud1b5\ud589\uc744 \uc5f0\uacb0\ud574 \uc124\uba85\ud55c\ub2e4. \ub18d\uc0b0\ubb3c\uc774 \ub098\uc624\ub294 \uacf3\uacfc \uc18c\ube44\ud558\ub294 \uacf3\uc774 \ub2e4\ub974\uba74 \uc911\uac04\uc758 \uc6b4\uc1a1\uc774 \ud544\uc694\ud558\ub2e4. \uc218\ub85c\uac00 \ud48d\ubd80\ud55c \uc9c0\uc5ed\uc5d0\uc11c\ub3c4 \ubaa8\ub4e0 \uc9d1\uacfc \ubc2d, \uc2dc\uc7a5\uc744 \ubc30\uac00 \uc9c1\uc811 \uc774\uc5b4 \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb3c\uae38\uacfc \uc721\ub85c\uc758 \uc791\uc740 \uc5f0\uacb0\uc744 \uc218\ub808\uc640 \uc0ac\ub78c\uc774 \ub9e1\uc744 \uc218 \uc788\ub2e4. \uc774 \uc810\uc744 \uc0dd\uac01\ud558\uba74 \uc720\uba85\ud55c \uad00\uac1c \uc2dc\uc124\ub9cc\uc73c\ub85c \uc9c0\uc5ed \uacbd\uc81c\ub97c \ubaa8\ub450 \uc124\uba85\ud560 \uc218 \uc5c6\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ubcf4\uc778\ub2e4. \ubb3c\uc744 \ub098\ub204\ub294 \uae30\uc220\uacfc \ud568\uaed8 \uc0dd\uc0b0\ubb3c\uc744 \ubaa8\uc73c\uace0 \uc62e\uaca8 \uac70\ub798\ud558\ub294 \uc0dd\ud65c\uc758 \uc870\uc9c1\uc774 \uc788\uc5c8\ub2e4. \ucc45\uc758 \uc124\uba85\uc5d0\ub294 \ub4a4\uc5d0\uc11c \ubbf8\ub294 \uc0ac\ub78c \ub9d0\uace0 \uc55e\uc5d0\uc11c \ud568\uaed8 \ub2f9\uae30\ub294 \uc0ac\ub78c\uc774 \ubd99\uae30\ub3c4 \ud55c\ub2e4\uace0 \uc801\ud600 \uc788\ub2e4. \uc218\ub808\ub97c \uc5b8\uc81c\ub098 \ud63c\uc790 \uc6c0\uc9c1\uc774\ub294 \ub3c4\uad6c\ub85c\ub9cc \uc0c1\uc0c1\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4\ub294 \ub73b\uc774\ub2e4. \ubb34\uac70\uc6b4 \uc9d0\uc774\ub098 \ud798\ub4e0 \uae38\uc5d0\uc11c\ub294 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \ud638\ud761\uc774 \ud544\uc694\ud588\uc744 \uac83\uc774\ub2e4. \uc9d0\uc744 \uc62c\ub9ac\uace0 \ub0b4\ub9ac\ub294 \uc77c, \uade0\ud615\uc744 \ub9de\ucd94\ub294 \uc77c\ub3c4 \uc6b4\uc1a1\uc758 \uc77c\ubd80\ub2e4. \ubc14\ud034\uac00 \uc6c0\uc9c1\uc774\ub294 \uc21c\uac04\ub9cc \ubcf4\uba74 \uc774\ub7f0 \uc900\ube44\uac00 \ube60\uc9c4\ub2e4. \uc9c0\uae08\uc758 \ubc30\ub2ec\uc5d0\uc11c\ub3c4 \uc0c1\ud558\ucc28\uc640 \ubcf4\uad00\uc774 \uc911\uc694\ud558\ub4ef, \uc61b \uc6b4\uc1a1 \uc5ed\uc2dc \uc774\ub3d9\ud558\ub294 \ubb3c\uac74\uacfc \uadf8\uac83\uc744 \ub2e4\ub8e8\ub294 \uc190\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \uc774\ud574\ub41c\ub2e4. \uae38\uc758 \uc9c8\uacfc \ub3c4\uad6c\uc758 \ubaa8\uc591\uc740 \uc11c\ub85c \uad00\uacc4\ub97c \ub9fa\ub294\ub2e4. \ub113\uc740 \ub3c4\ub85c\ub97c \uc804\uc81c\ub85c \uace0\uc548\ud55c \uc7a5\uce58\ub97c \ub2e4\ub978 \uc9c0\uc5ed\uc5d0 \uadf8\ub300\ub85c \uc62e\uae34\ub2e4\uace0 \ub298 \ud6a8\uc728\uc801\uc774\uc9c0\ub294 \uc54a\ub2e4. \uc678\ubc14\ud034\uc218\ub808\ub294 \uae30\uc220\uc744 \ud3c9\uac00\ud560 \ub54c \uc0ac\uc6a9 \ud658\uacbd\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4\ub294 \uad6c\uccb4\uc801\uc778 \uc0ac\ub840\uac00 \ub41c\ub2e4. \uc0ac\uc9c4\uc9d1\uc740 \ubd81\ubd80\uc5d0\uc11c \uc4f0\ub294 \ub354 \ud070 \ud615\ud0dc\ub97c \ub530\ub85c \uc2e4\uc5c8\ub2e4. \uac19\uc740 \uc6d0\ub9ac\ub97c \uc4f0\ub354\ub77c\ub3c4 \uc9c0\uc5ed\uacfc \uc4f0\uc784\uc5d0 \ub530\ub77c \ub3c4\uad6c\uac00 \ub2ec\ub790\uc74c\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc790\ub8cc\ub2e4. \uc624\ub298\ub0a0 \uc9c0\uba85\uc73c\ub85c \uc911\uad6d \uc804\uccb4\ub97c \ubb36\uc744 \uc218 \uc788\uc5b4\ub3c4 \uc2e4\uc81c \uae38\uacfc \ub0a0\uc528, \uc0dd\uc0b0\ubb3c\uacfc \uc0dd\ud65c \uc870\uac74\uc740 \ud558\ub098\uac00 \uc544\ub2c8\uc5c8\ub2e4. \uc61b \uae00\uc740 \uc218\ubc31 \ud0ac\ub85c\uadf8\ub7a8\uc5d0 \uc774\ub974\ub294 \uc801\uc7ac\ub7c9\uc744 \uc790\uc2e0 \uc788\uac8c \uc124\uba85\ud558\uc9c0\ub9cc \uadf8 \uc218\uce58\ub97c \ubcf4\ud1b5 \ub178\ub3d9\uc790\uac00 \ud56d\uc0c1 \uc6b4\ubc18\ud55c \uc591\uc73c\ub85c \ubc1b\uc544\ub4e4\uc774\uba74 \uace4\ub780\ud558\ub2e4. \uce21\uc815 \uc870\uac74\uc774 \ucda9\ubd84\ud788 \uc81c\uc2dc\ub418\uc5b4 \uc788\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc774\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \ud655\uc778\ub418\ub294 \uad6c\uc870\uc640 \uc800\uc790\uac00 \uc8fc\uc7a5\ud55c \uc131\ub2a5\uc744 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \u300e\uc911\uad6d\uc758 \ud48d\uacbd\u300f\uc740 \uc774\uc800\ubca8\ub77c \ubc84\ub4dc\uc758 \uc0ac\uc9c4\uc744 \ubc14\ud0d5\uc73c\ub85c \ud55c \uc790\ub8cc\ub2e4. \uc0ac\uc9c4\uacfc \uacc1\ub4e4\uc778 \ud574\uc124\uc740 \uc678\uad6d\uc778 \ub3c5\uc790\ub97c \ud5a5\ud574 \uc911\uad6d\uc744 \uc124\uba85\ud558\uba70, \ub54c\ub85c\ub294 \uc9c0\uc5ed \uc0ac\ub78c\uacfc \ub178\ub3d9\uc744 \ub0a1\uc740 \ub9d0\uacfc \ud3b8\uacac\uc73c\ub85c \ubb18\uc0ac\ud55c\ub2e4. \uc624\ub798\ub418\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc124\uba85\uc774 \ubaa8\ub450 \uc815\ud655\ud574\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \ub178\ub3d9\uc790\ub97c \ub0ae\ucd94\uc5b4 \ubd80\ub974\ub294 \ud45c\ud604\uacfc \ub2e8\uc815\uc801\uc778 \uc801\uc7ac \ub2a5\ub825, \uacfc\uc7a5\ub41c \uc0dd\uc0b0 \ud1b5\uacc4\ub97c \ubc18\ubcf5\ud558\uc9c0 \uc54a\uc558\ub2e4. \ud55c \uc7a5\uba74\uc744 \ucd2c\uc601\ud55c \uc0ac\uc9c4\uc740 \uc18c\uc911\ud55c \uae30\ub85d\uc774\uc9c0\ub9cc \ud654\uba74 \ubc14\uae65\uc758 \uc784\uae08\uacfc \ud53c\ub85c, \uc0ac\ub78c\uc758 \uc774\ub984\uae4c\uc9c0 \uc790\ub3d9\uc73c\ub85c \uc54c\ub824 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4\ub294 \ud55c\uacc4\ub3c4 \ub0a8\ub294\ub2e4. \uc5ec\uae30\uc11c \ub2e4\ub8ec \uac83\uc740 \ud55c \ub3c4\uad6c\uc758 \ucd5c\ucd08 \ubc1c\uba85\uc790\ub97c \ucc3e\ub294 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \uae30\ub85d\uc5d0 \ub0a8\uc740 \uccad\ub450\uc640 \ubd81\ubd80\uc758 \uc0ac\uc6a9 \ubaa8\uc2b5\uc744 \uc77d\ub294 \uae00\uc774\ub2e4. \uc624\ub798 \uc4f0\uc778 \uae30\uc220\uc744 \ucd5c\ucd08\uc758 \ud55c \uc21c\uac04\uc73c\ub85c\ub9cc \uc815\ub9ac\ud558\uba74 \uc9c0\uc5ed\ub9c8\ub2e4 \uace0\uce58\uace0 \uc775\ud788\uba70 \uc774\uc5b4 \uc628 \uc0ac\ub78c\ub4e4\uc758 \uc2dc\uac04\uc774 \uc0ac\ub77c\uc9c0\uae30 \uc27d\ub2e4. \uc678\ubc14\ud034\uc218\ub808\ub97c \uc6d0\uc2dc\uc801\uc774\ub77c\ub294 \ud55c \ub2e8\uc5b4\ub85c \ud3c9\uac00\ud558\uba74 \ub2f9\uc2dc \ud658\uacbd\uc5d0 \ub9de\ucd98 \uc124\uacc4\uac00 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ubc18\ub300\ub85c \uac00\ubcbc\uc6b4 \uc7a5\uce58\uac00 \ubb34\uac70\uc6b4 \uc9d0\uc744 \uc62e\uae34\ub2e4\uace0 \ubb34\uc870\uac74 \uc774\uc0c1\uc801\uc778 \uae30\uc220\ub85c \uce6d\ucc2c\ud558\uba74 \uc77c\ud55c \uc0ac\ub78c\uc758 \ud798\ub4e0 \ub178\ub3d9\uc774 \uac00\ub824\uc9c4\ub2e4. \ub450 \uc2dc\uc120\uc744 \ud568\uaed8 \ud53c\ud560 \ud544\uc694\uac00 \uc788\ub2e4. \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uccad\ub450 \ud3c9\uc57c\uc758 \uc6b4\uc1a1\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc2e4\uc81c \uc5ed\uc0ac \uc0ac\uc9c4\uc774\ub2e4. \uac00\uc6b4\ub370 \ubc14\ud034\uc640 \uc591\uc606\uc758 \uc9d0, \uc55e\ub4a4 \uc0ac\ub78c\uc758 \uc790\ub9ac\ub97c \ucc28\ub840\ub85c \uc0b4\ud3b4\ubcf4\uc790. \uc774 \uc791\uc740 \uc7a5\uce58\uac00 \uc5f0\uacb0\ud55c \uac83\uc740 \ub450 \uc9c0\uc810\ub9cc\uc774 \uc544\ub2c8\ub77c \ubc2d\uacfc \uc2dc\uc7a5, \uc0ac\ub78c\uc758 \uc219\ub828\uacfc \ub9e4\uc77c\uc758 \uc0dd\uacc4\uc600\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc77d\uc744 \uc218 \uc788\ub2e4."}, {"id": "constantinople-1453-walls-sea-and-new-capital", "title": "\ucf58\uc2a4\ud0c4\ud2f0\ub178\ud3f4\ub9ac\uc2a4 1453 \u2014 \uc131\ubcbd\uc744 \ub118\uc740 \ub4a4\uc5d0\ub3c4 \ub3c4\uc2dc\ub294 \uc774\uc5b4\uc84c\ub2e4", "summary": "\uc721\uc9c0\uc640 \ubc14\ub2e4\uc758 \ud3ec\uc704\uc804, \ud568\ub77d\uc758 \ud53c\ud574\uc640 \uc0c8 \uc218\ub3c4\uc758 \uc6b4\uc601\uc744 \ud1b5\ud574 \ub3c4\uc2dc\uc758 \uc9c0\uc18d\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/constantinople-1453-walls-sea-and-new-capital/index.html", "image": "../media/constantinople-1453-walls-sea-and-new-capital.jpg", "alt": "20\uc138\uae30 \ucd08 \ucf58\uc2a4\ud0c4\ud2f0\ub178\ud3f4\ub9ac\uc2a4 \uc721\uc0c1 \uc131\ubcbd\uc758 \uc0c1\ud0dc\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc2e4\uc81c \uc5ed\uc0ac \uc0ac\uc9c4", "text": "\ucf58\uc2a4\ud0c4\ud2f0\ub178\ud3f4\ub9ac\uc2a4 1453 \u2014 \uc131\ubcbd\uc744 \ub118\uc740 \ub4a4\uc5d0\ub3c4 \ub3c4\uc2dc\ub294 \uc774\uc5b4\uc84c\ub2e4 \uc721\uc9c0\uc640 \ubc14\ub2e4\uc758 \ud3ec\uc704\uc804, \ud568\ub77d\uacfc \uc0c8 \uc218\ub3c4\uc758 \uc6b4\uc601 \uc721\uc9c0\uc640 \ubc14\ub2e4\uc758 \ud3ec\uc704\uc804, \ud568\ub77d\uc758 \ud53c\ud574\uc640 \uc0c8 \uc218\ub3c4\uc758 \uc6b4\uc601\uc744 \ud1b5\ud574 \ub3c4\uc2dc\uc758 \uc9c0\uc18d\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc 1453\ub144 \ucf58\uc2a4\ud0c4\ud2f0\ub178\ud3f4\ub9ac\uc2a4\uc758 \ud568\ub77d\uc740 \ub3d9\ub85c\ub9c8 \uc81c\uad6d\uc758 \ub05d\uc744 \uc0c1\uc9d5\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uadf8\ub0a0\uc744 \uc911\uc138 \uc804\uccb4\uac00 \uc885\ub8cc\ub418\uac70\ub098 \ub3d9\uc11c \ubb34\uc5ed\uc774 \uc644\uc804\ud788 \ub04a\uae34 \uc21c\uac04\uc73c\ub85c \ub9d0\ud558\uba74 \ub9ce\uc740 \uc5ed\uc0ac\uac00 \uc0ac\ub77c\uc9c4\ub2e4. \uba54\ud750\uba54\ud2b8 2\uc138\uc758 \ud3ec\uc704\uc640 \ub3c4\uc2dc\uc758 \ubc29\uc5b4, \ud568\ub77d \ub4a4 \uc0c8 \uc218\ub3c4\uac00 \ub9cc\ub4e4\uc5b4\uc9c4 \uacfc\uc815\uc744 \ub098\ub204\uc5b4 \uc0b4\ud3b4\ubcf4\uc790. \ud55c\ub54c \ub113\uc740 \uc9c0\uc911\ud574 \uc138\uacc4\ub97c \ub2e4\uc2a4\ub838\ub358 \ub3d9\ub85c\ub9c8 \uc81c\uad6d\uc740 15\uc138\uae30\uc5d0 \ud06c\uac8c \uc904\uc5b4\ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \uc218\ub3c4\uc758 \uc704\uc5c4\uacfc \uc2e4\uc81c\ub85c \ub3d9\uc6d0\ud560 \uc218 \uc788\ub294 \uc0ac\ub78c\uacfc \uc790\uc6d0 \uc0ac\uc774\uc5d0\ub294 \ucc28\uc774\uac00 \ucef8\ub2e4. \uc624\ub798\ub41c \uc131\ubcbd\uc774 \uc788\uc5b4\ub3c4 \uadf8\uac83\uc744 \uc9c0\ud0a4\uace0 \uace0\uce60 \ubcd1\ub825\uacfc \ubb3c\uc790\uac00 \ucda9\ubd84\ud574\uc57c \ud588\ub2e4. \ub3c4\uc2dc\ub294 \uc774\ubbf8 1204\ub144 \uc81c4\ucc28 \uc2ed\uc790\uad70\uc758 \uc810\ub839\uacfc \uc774\ud6c4\uc758 \ud68c\ubcf5\uc744 \uacaa\uc5c8\ub2e4. 1453\ub144\ub9cc\uc774 \ucc98\uc74c \ub9de\ub294 \ucda9\uaca9\uc740 \uc544\ub2c8\uc5c8\ub358 \uac83\uc774\ub2e4. \ub85c\ub9c8\uc758 \uacc4\uc2b9\uc744 \uc8fc\uc7a5\ud55c \uc81c\uad6d\uc758 \uae34 \uc5ed\uc0ac\uc640 \ub9c8\uc9c0\ub9c9 \ub2e8\uacc4\uc758 \uc57d\ud574\uc9c4 \ud1b5\uce58 \ubc94\uc704\ub97c \ud568\uaed8 \ubcf4\uc544\uc57c \ud3ec\uc704\uc804\uc758 \uc870\uac74\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \uc131\ubcbd\uc758 \uc720\uba85\ud568\uacfc \uc2e4\uc81c \ubc29\uc5b4\ub825\uc744 \uac19\uc740 \uac83\uc73c\ub85c \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uae34 \uad6c\uac04\uc744 \uac10\uc2dc\ud558\uace0 \uc801\uc758 \uc811\uadfc\uc744 \ub9c9\uc73c\ub824\uba74 \ucda9\ubd84\ud55c \uc778\uc6d0\uacfc \uc9c0\uc18d\uc801\uc778 \ubb3c\uc790\uac00 \ud544\uc694\ud588\ub2e4. \uc624\ub798\ub41c \uad6c\uc870\ubb3c\uc740 \uc911\uc694\ud55c \uc790\uc0b0\uc774\uc9c0\ub9cc \uadf8\uac83\uc744 \uc6c0\uc9c1\uc774\ub294 \uc870\uc9c1\uacfc \uc0ac\ub78c\uc744 \ub300\uc2e0\ud560 \uc218\ub294 \uc5c6\uc5c8\ub2e4. \uc624\uc2a4\ub9cc\uc758 \uc80a\uc740 \uc220\ud0c4 \uba54\ud750\uba54\ud2b8 2\uc138\ub294 \ub3c4\uc2dc\ub97c \uc815\ubcf5\ud558\ub824 \ud588\ub2e4. \uadf8\uc758 \uad70\ub300\ub294 \uc721\uc0c1 \uc131\ubcbd\uc744 \uacf5\uaca9\ud558\uace0 \ubc14\ub2e4 \ucabd\uc758 \uc811\uadfc\ub3c4 \ud1b5\uc81c\ud558\ub824 \ud588\ub2e4. \ud3ec\uc704\ub294 \uc131\ubcbd \uc55e\uc5d0\uc11c \ubc8c\uc5b4\uc9c4 \ub2e8\uc77c\ud55c \uacb0\ud22c\uac00 \uc544\ub2c8\ub77c \uc5ec\ub7ec \ubc29\ud5a5\uc758 \ubcf4\uae09\uacfc \uc774\ub3d9\uc744 \ub2e4\ud22c\ub294 \uc791\uc804\uc774\uc5c8\ub2e4. \ud574\ud611\uacfc \ud56d\uad6c\uc758 \uc704\uce58\ub294 \ub3c4\uc2dc\uc758 \ud798\uc774\uba74\uc11c \uc57d\uc810\uc774\uae30\ub3c4 \ud588\ub2e4. \ubc16\uc5d0\uc11c \ub3c4\uc6c0\uc774 \ub4e4\uc5b4\uc62c \uae38\uc744 \uc720\uc9c0\ud558\ub294\uc9c0, \uc624\uc2a4\ub9cc\uc774 \uadf8\uac83\uc744 \uc5b4\ub290 \uc815\ub3c4 \ub9c9\ub294\uc9c0\uc5d0 \ub530\ub77c \ubc29\uc5b4\uc758 \uc870\uac74\uc774 \ub2ec\ub77c\uc84c\ub2e4. \uc9c0\ub3c4\uc5d0\uc11c \uc131\ubcbd\uc758 \uc120\ub9cc \ubcf4\ub294 \uac83\ubcf4\ub2e4 \ubb3c\uae38\uacfc \ud56d\uad6c\ub97c \ud568\uaed8 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc624\uc2a4\ub9cc\uc740 \ub300\ud615 \ub300\ud3ec\ub85c \uc131\ubcbd\uc744 \ub450\ub4dc\ub838\ub2e4. \uc0c8\ub85c\uc6b4 \ud654\ub825\uc740 \uc911\uc694\ud55c \uc694\uc18c\uc600\uc9c0\ub9cc \ud55c \ubc88 \uc3d8\uc544 \uac70\ub300\ud55c \ubcbd\uc774 \uace7\ubc14\ub85c \ubb34\ub108\uc9c0\ub294 \uc7a5\uba74\uc73c\ub85c \uc0dd\uac01\ud558\uba74 \uace4\ub780\ud558\ub2e4. \ud3ec\uaca9\uacfc \uc218\ub9ac, \uc131\ubcbd \uc55e \uc9c0\ud615\uacfc \uacf5\uaca9, \ubc29\uc5b4\uc790\uc758 \ub178\ub3d9\uc774 \uc624\ub7ab\ub3d9\uc548 \ub9de\ubb3c\ub838\ub2e4. \ubd80\uc11c\uc9c4 \uacf3\uc744 \ubcf4\uac15\ud558\uace0 \uacf5\uaca9\uc744 \ub9c9\ub294 \uc77c\uc740 \uacc4\uc18d \ud544\uc694\ud588\ub2e4. \ub300\ud3ec\uc758 \uc131\ub2a5\ub9cc \uc54c\uba74 \uacb0\uacfc\ub97c \ubaa8\ub450 \uc124\uba85\ud560 \uc218 \uc788\ub294 \uc804\uc7c1\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc22b\uc790\ub85c \uc798 \ub0a8\uc9c0 \uc54a\ub294 \uc57c\uac04\uc758 \uc218\ub9ac\uc640 \ubcf4\uae09, \uc9c0\uce5c \ubcd1\ub825\uc758 \uad50\ub300\ub3c4 \ub3c4\uc2dc\uac00 \ubc84\ud2f0\ub294 \ub370 \uc911\uc694\ud55c \uc870\uac74\uc774\uc5c8\ub2e4. \ud56d\uad6c\uc5d0 \ub4e4\uc5b4\uc624\ub294 \ub3c4\uc6c0\uc740 \ubb3c\uc790\ubfd0 \uc544\ub2c8\ub77c \ubc29\uc5b4\uc790\ub4e4\uc758 \uae30\ub300\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc5c8\ub2e4. \ubc18\ub300\ub85c \ubd09\uc1c4\uac00 \uac15\ud574\uc9c0\uba74 \uc131\ubcbd \uc548\uc758 \uc2dc\uac04\ub3c4 \uc904\uc5b4\ub4e0\ub2e4. \ud3ec\uc704\uc804\uc744 \uacf5\uaca9\uacfc \uc218\ube44\uc758 \uc21c\uac04\ub9cc \ubaa8\uc544 \uc124\uba85\ud558\uae30\ubcf4\ub2e4 \uc5b4\ub290 \ucabd\uc774 \ub354 \uc624\ub798 \ubc84\ud2f8 \uc870\uac74\uc744 \uac00\uc84c\ub294\uc9c0 \ubb3c\uc744 \ud544\uc694\uac00 \uc788\ub2e4. \ub3c4\uc2dc \ucabd\uc740 \uae08\uac01\ub9cc \uc785\uad6c\uc758 \uc0ac\uc2ac \ub4f1\uc73c\ub85c \ud56d\uad6c \uc811\uadfc\uc744 \ub9c9\uc73c\ub824 \ud588\ub2e4. \uc5ed\uc0ac\uc11c\uac00 \uc804\ud558\ub294 \uc624\uc2a4\ub9cc \uc120\ubc15\uc758 \uc721\uc0c1 \uc774\ub3d9\uc740 \uadf8 \uc7a5\uc560\ubb3c\uc744 \uc6b0\ud68c\ud55c \ud589\ub3d9\uc73c\ub85c \uc720\uba85\ud558\ub2e4. \ubc30\ub97c \ubb3c\uc5d0\uc11c\ub9cc \uc6c0\uc9c1\uc774\ub294 \ubb3c\uac74\uc73c\ub85c \uc0dd\uac01\ud558\uc9c0 \uc54a\uc740 \uc791\uc804\uc774\ub77c\ub294 \uc810\uc5d0\uc11c \uac15\ud55c \uc778\uc0c1\uc744 \ub0a8\uae34\ub2e4. \uadf8\ub7ec\ub098 \uc774 \uc77c \ud558\ub098\uac00 \ud568\ub77d\uc758 \ubaa8\ub4e0 \uc6d0\uc778\uc744 \uc124\uba85\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc774\ub3d9\ud55c \uc120\ubc15\uacfc \uc0c8\ub85c\uc6b4 \uc555\ubc15\uc740 \uc721\uc9c0\uc640 \ubc14\ub2e4\uc758 \uc5ec\ub7ec \uc804\ud669 \uac00\uc6b4\ub370 \ud55c \uc694\uc18c\uc600\ub2e4. \uc720\uba85\ud55c \ubb18\ucc45\uc744 \ub098\uba38\uc9c0 \uc0c1\ud669\uc5d0\uc11c \ub5bc\uc5b4 \ub0b4\uba74 \uc9c0\ud718\uad00\uc758 \uc601\uac10\ub9cc\uc73c\ub85c \uc131\ubcbd\uacfc \uc0ac\ub78c\uc774 \uc0ac\ub77c\uc9c4 \uac83\ucc98\ub7fc \ubcf4\uc774\uac8c \ub41c\ub2e4. 1453\ub144 5\uc6d4 29\uc77c \ub3c4\uc2dc\ub294 \ud568\ub77d\ub418\uc5c8\uace0 \ub9c8\uc9c0\ub9c9 \ud669\uc81c \ucf58\uc2a4\ud0c4\ud2f0\ub178\uc2a4 11\uc138\ub3c4 \uc804\ud22c \uc18d\uc5d0\uc11c \uc8fd\uc5c8\ub2e4. \uc774\ud6c4\uc758 \uc57d\ud0c8\uacfc \ud3ec\ub85c\ud654\ub294 \uc8fc\ubbfc\ub4e4\uc5d0\uac8c \ud070 \uace0\ud1b5\uc744 \ub0a8\uacbc\ub2e4. \uc815\ubcf5\uc790\uc758 \uc2b9\ub9ac\ub77c\ub294 \ub9d0\ub9cc\uc73c\ub85c \uadf8\ub0a0\uc744 \uc124\uba85\ud558\uba74 \ub3c4\uc2dc \uc548\uc758 \uc0ac\ub78c\ub4e4\uc774 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \uac19\uc740 \uc0c1\ud669\uc5d0\uc11c\ub3c4 \uc7ac\uc0b0\uacfc \uc2e0\ubd84, \uba38\ubb3c\ub358 \uc7a5\uc18c\uc5d0 \ub530\ub77c \ub2e4\ub978 \uc77c\uc744 \uacaa\uc5c8\ub2e4. \uc885\uad50 \uac74\ucd95\uacfc \uc608\uc220\ud488, \uae30\ub85d\ub3c4 \ud0c0\uaca9\uc744 \ubc1b\uac70\ub098 \ub2e4\ub978 \uc6a9\ub3c4\ub85c \ubc14\ub00c\uc5c8\ub2e4. \uc804\uc7c1\uc758 \uacb0\uacfc\ub294 \uc655\uc870\uc758 \uc774\ub984\uc774 \ubc14\ub00c\ub294 \ud45c \ud55c \uce78\ubcf4\ub2e4 \ud6e8\uc52c \ub113\uc5c8\ub2e4. \uc61b \uc720\ub7fd \uc5ed\uc0ac\uc11c\ub294 \ud568\ub77d\uc744 \ubb38\uba85\uacfc \uc57c\ub9cc\uc758 \ub300\uacb0\ub85c \uadf8\ub9ac\ub294 \uacbd\uc6b0\uac00 \uc788\ub2e4. \uadf8\ub7f0 \uac00\uce58 \ud310\ub2e8\uc744 \ub530\ub974\uc9c0 \uc54a\uace0 \uc804\uc7c1\uc758 \ud53c\ud574\uc640 \uc815\ubcf5 \uc774\ud6c4\uc758 \ub3c4\uc2dc \uc6b4\uc601\uc744 \ub098\ub204\uc5b4 \uc0b4\ud3c8\ub2e4. \uc5b4\ub290 \uad6d\uac00\uc758 \uc2b9\ub9ac\ub85c \ubd84\ub958\ud558\ub354\ub77c\ub3c4 \uc8fc\ubbfc\uc774 \uacaa\uc740 \uc77c\uacfc \uc774\ud6c4 \uc0b6\uc758 \uc9c0\uc18d\uc744 \ud568\uaed8 \uc124\uba85\ud574\uc57c \ud55c\ub2e4. \uba54\ud750\uba54\ud2b8\ub294 \ub3c4\uc2dc\ub97c \uc624\uc2a4\ub9cc\uc758 \uc218\ub3c4\ub85c \ub9cc\ub4e4\uace0 \uc778\uad6c\uc640 \uc0c1\uc5c5, \ud589\uc815\uacfc \uc885\uad50 \uc870\uc9c1\uc744 \ub2e4\uc2dc \uc138\uc6cc\uc57c \ud588\ub2e4. \uc0ac\ub78c\uc744 \uc774\uc8fc\uc2dc\ucf1c \ucc44\uc6b0\ub294 \uc815\ucc45\uacfc \uae30\uc874 \uc8fc\ubbfc\u00b7\uacf5\ub3d9\uccb4\uc758 \uc7ac\ud3b8\uc774 \uc774\uc5b4\uc84c\ub2e4. \uc815\ubcf5\uc740 \ub3c4\uc2dc \uc6b4\uc601\uc758 \ub05d\uc774 \uc544\ub2c8\ub77c \ub610 \ub2e4\ub978 \ud1b5\uce58 \uacfc\uc81c\uc758 \uc2dc\uc791\uc774\uc5c8\ub2e4. \uc544\uc57c \uc18c\ud53c\uc544\uac00 \ubaa8\uc2a4\ud06c\ub85c \uc804\ud658\ub41c \uc77c\uc740 \ubcc0\ud654\uc758 \uac15\ud55c \uc0c1\uc9d5\uc774\uc9c0\ub9cc \uadf8 \uac74\ubb3c \ud558\ub098\ub85c \ub3c4\uc2dc \uc804\uccb4\ub97c \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc5ec\ub7ec \uc2e0\uc559 \uacf5\ub3d9\uccb4\uc640 \uc0c1\uc778, \uad00\ub9ac\uc640 \uc7a5\uc778\uc774 \ud568\uaed8\ud55c \ub3c4\uc2dc\uc758 \uc0c8\ub85c\uc6b4 \uc0dd\ud65c\uc744 \ubcf4\uc544\uc57c \ud568\ub77d \ub4a4\uc758 \uc2dc\uac04\uc744 \uc77d\uc744 \uc218 \uc788\ub2e4. 1453\ub144\uc740 \uc911\uc694\ud55c \uc5f0\ub300\uc774\uc9c0\ub9cc \uc720\ub7fd\uacfc \uc9c0\uc911\ud574\uc758 \uc911\uc138\uac00 \uadf8\ub0a0 \ub3d9\uc2dc\uc5d0 \ub05d\ub0ac\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ubb34\uc5ed\uacfc \uc815\ubcf4\uc758 \ud1b5\ub85c\ub3c4 \ubaa8\uc591\uc744 \ubc14\uafb8\uba70 \uc774\uc5b4\uc84c\ub2e4. \uc624\uc2a4\ub9cc\uc774 \uae38\uc744 \uc644\uc804\ud788 \ub9c9\uc544 \uc720\ub7fd\uc758 \ubc14\ub2f7\uae38 \ud0d0\ud5d8\uc774 \uc2dc\uc791\ub418\uc5c8\ub2e4\ub294 \ub2e8\uc21c\ud55c \uc778\uacfc \uc5ed\uc2dc \uc8fc\uc758\ud574\uc57c \ud55c\ub2e4. \uc5ec\uae30\uc5d0 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uc218\ubc31 \ub144 \ub4a4 \ucd2c\uc601\ud55c \uc721\uc0c1 \uc131\ubcbd\uc758 \uc5ed\uc0ac \uc0ac\uc9c4\uc774\uba70 \ud3ec\uc704\uc804 \ud604\uc7a5 \uc0ac\uc9c4\uc774 \uc544\ub2c8\ub2e4. \ubcbd\uc744 \ubc14\ub77c\ubcf4\uba70 \ubb34\uc5c7\uc774 \ubb34\ub108\uc84c\ub294\uc9c0\ubfd0 \uc544\ub2c8\ub77c \ub204\uac00 \ub2e4\uc2dc \ub4e4\uc5b4\uc640 \ubb34\uc5c7\uc744 \uc774\uc5b4 \uac14\ub294\uc9c0\ub3c4 \ubb3c\uc5b4\ubcf4\uc790. \uc81c\uad6d\uc758 \ub9c8\uc9c0\ub9c9 \ub0a0\uacfc \ub3c4\uc2dc\uc758 \ub9c8\uc9c0\ub9c9 \ub0a0\uc740 \uac19\uc740 \ub9d0\uc774 \uc544\ub2c8\uc5c8\ub2e4."}, {"id": "cordoba-oranges-and-connections", "title": "\ucf54\ub974\ub3c4\ubc14 \u2014 \uc624\ub80c\uc9c0\ub098\ubb34 \ub4a4\uc5d0\uc11c \uc9c0\uc911\ud574\ub97c \ub9cc\ub098\ub2e4", "summary": "\uc911\uc138 \ucf54\ub974\ub3c4\ubc14\uc758 \uac10\uade4 \uc7ac\ubc30\uc640 \uad50\uc5ed\u00b7\ud559\ubb38\uc744 \ud1b5\ud574 \ub3c4\uc2dc \ud48d\uacbd\uc5d0 \uacb9\uce5c \uc774\ub3d9\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/cordoba-oranges-and-connections/index.html", "image": "../media/cordoba-oranges-and-connections.png", "alt": "\uac10\uade4\ub098\ubb34\uc640 \uadf8\ub298, \ucc45\uacfc \uadf8\ub987\uc774 \ub193\uc778 \uc9c0\uc911\ud574\ud48d \ub730\uc758 AI \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ucf54\ub974\ub3c4\ubc14 \u2014 \uc624\ub80c\uc9c0\ub098\ubb34 \ub4a4\uc5d0\uc11c \uc9c0\uc911\ud574\ub97c \ub9cc\ub098\ub2e4 \ub3c4\uc2dc\uc758 \ud48d\uacbd\uc740 \uba3c \uacf3\uc5d0\uc11c \uc628 \uc5f0\uacb0\ub85c \uc790\ub77c\uae30\ub3c4 \ud55c\ub2e4 \uc911\uc138 \ucf54\ub974\ub3c4\ubc14\uc758 \uac10\uade4 \uc7ac\ubc30\uc640 \uad50\uc5ed\u00b7\ud559\ubb38\uc744 \ud1b5\ud574 \ub3c4\uc2dc \ud48d\uacbd\uc5d0 \uacb9\uce5c \uc774\ub3d9\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc2a4\ud398\uc778 \ub0a8\ubd80\uc758 \ucf54\ub974\ub3c4\ubc14\ub97c \ub5a0\uc62c\ub9ac\uba74 \ud587\ube5b\uacfc \uadf8\ub298, \ub098\ubb34\uac00 \uc788\ub294 \ub730\uc758 \ud48d\uacbd\uc774 \uc798 \uc5b4\uc6b8\ub9b0\ub2e4. \uc774\ub7f0 \uc774\ubbf8\uc9c0\ub294 \uadf8\uc800 \ub530\ub73b\ud55c \ub0a0\uc528\uc758 \uacb0\uacfc\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \ud55c \ub3c4\uc2dc\uc5d0\uc11c \ubb34\uc5c7\uc744 \uae30\ub974\uace0 \uc5b4\ub5a4 \ub9d0\uc744 \ub098\ub204\uc5c8\ub294\uc9c0\ub294 \uba3c \uc9c0\uc5ed\uacfc\uc758 \uc5f0\uacb0\uc5d0\ub3c4 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4. \uc911\uc138 \ucf54\ub974\ub3c4\ubc14\ub294 \uc9c0\uc911\ud574\uc758 \uc5ec\ub7ec \uacf3\uacfc \uc774\uc5b4\uc9c4 \ub3c4\uc2dc\uc600\ub2e4. \uad50\uc7ac\ub294 \uc774\uacf3\uc774 \uc624\ub80c\uc9c0\uc640 \ub77c\uc784, \ub808\ubaac\uc744 \uae30\ub974\ub294 \uacf3\uc73c\ub85c\ub3c4 \uc54c\ub824\uc84c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uacfc\uc77c \uc774\ub984 \uc138 \uac1c\uc5d0\uc11c \uc2dc\uc791\ud558\uba74 \uc655\uc870\uc758 \uc5f0\ud45c\uc640\ub294 \uc870\uae08 \ub2e4\ub978 \uae38\ub85c \ub3c4\uc2dc\uc758 \uc5ed\uc0ac\ub97c \uac78\uc5b4 \ubcfc \uc218 \uc788\ub2e4. 8\uc138\uae30 \uc774\ubca0\ub9ac\uc544\ubc18\ub3c4\uc758 \uc54c\uc548\ub2ec\ub8e8\uc2a4\uc5d0\uc11c\ub294 \uc6b0\ub9c8\uc774\uc57c \uac00\ubb38\uc758 \ud1b5\uce58\uac00 \uc790\ub9ac \uc7a1\uc558\ub2e4. \uc555\ub4dc \uc54c\ub77c\ud750\ub9cc 1\uc138\ub294 \ucf54\ub974\ub3c4\ubc14\ub97c \uc218\ub3c4\ub85c \uc0bc\uc558\ub2e4. \uc774 \ub3c4\uc2dc\ub294 \ubd81\uc544\ud504\ub9ac\uce74\uc640 \uc911\ub3d9 \ub4f1 \uc9c0\uc911\ud574 \uc138\uacc4\uc640 \uc0c1\uc5c5\uc801\u00b7\uc678\uad50\uc801 \uad00\uacc4\ub97c \uc774\uc5b4 \uac14\ub2e4. \ubc14\ub2e4\ub97c \uad6d\uacbd\ucc98\ub7fc\ub9cc \uc0dd\uac01\ud558\uba74 \uc800\ud3b8\uc758 \uc9c0\uc5ed\uc740 \uba40\ub9ac \ub5a8\uc5b4\uc9c4 \ub2e4\ub978 \uc138\uacc4\uac00 \ub41c\ub2e4. \uadf8\ub7ec\ub098 \ud56d\ud574\uc640 \uad50\uc5ed\uc758 \uae38\uc744 \uadf8\ub9ac\uba74 \ub3c4\uc2dc\ub97c \uc5f0\uacb0\ud558\ub294 \ud1b5\ub85c\ub3c4 \ub098\ud0c0\ub09c\ub2e4. \ucf54\ub974\ub3c4\ubc14\uc758 \uc131\uc7a5\uc740 \ubc18\ub3c4 \uc548\ucabd\uc758 \uc0ac\uc815\ub9cc\uc73c\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\uc558\uace0, \ubc14\uae65\uc5d0\uc11c \uc624\uac00\ub294 \ubb3c\uac74\uacfc \uc0ac\ub78c\uc774 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud588\ub2e4. \uad50\uc7ac\ub294 \uc774\ub7f0 \uc5f0\uacb0\uc744 \ud1b5\ud574 \uac10\uade4\ub958\uc640 \uc0ac\ud0d5\uc218\uc218, \uba74\ud654 \uac19\uc740 \ub18d\uc0b0\ubb3c\uc774 \ub354 \uba3c \uacf3\uc5d0\uc11c \uc774\ubca0\ub9ac\uc544\ubc18\ub3c4\ub85c \uc804\ud574\uc84c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc624\ub298 \ud48d\uacbd\uc5d0 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ub4e4\uc5b4 \uc788\ub294 \uc791\ubb3c\ub3c4 \uc5b8\uc81c\ub098 \uac19\uc740 \uc790\ub9ac\uc5d0\uc11c \uc7ac\ubc30\ub418\uc5c8\ub358 \uac83\uc740 \uc544\ub2d0 \uc218 \uc788\ub2e4. \ubb3c\ub860 \ud604\uc7ac \ucf54\ub974\ub3c4\ubc14\uc758 \ud2b9\uc815 \ub098\ubb34\uac00 \uc911\uc138\uc758 \uc5b4\ub290 \ud488\uc885\uc744 \uc9c1\uc811 \uc774\uc5b4 \uc654\ub2e4\uace0 \uc774 \uc790\ub8cc\ub9cc\uc73c\ub85c \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc774\ubc88 \uc774\uc57c\uae30\ub294 \uac1c\ubcc4 \uc218\ubaa9\uc758 \uc871\ubcf4\uac00 \uc544\ub2c8\ub77c \uc791\ubb3c\uacfc \uc7ac\ubc30 \ubb38\ud654\uc758 \uc774\ub3d9\uc744 \ub2e4\ub8ec\ub2e4. \uc775\uc219\ud55c \uacfc\uc77c\ub3c4 \uad50\uc5ed\uc758 \uc5ed\uc0ac\uc640 \ud568\uaed8 \ubcf4\uba74 \ub3c4\uc2dc\uc758 \ud48d\uacbd\uc744 \ub2e4\ub974\uac8c \uc77d\uac8c \ud55c\ub2e4. 10\uc138\uae30 \ucf54\ub974\ub3c4\ubc14\uac00 \ubc88\uc131\ud560 \ub54c\uc5d0\ub294 \uad50\uc5ed\uacfc \ud568\uaed8 \uc7a5\uc778\uacfc \uc0c1\uc778, \ud559\uc790\uc640 \uc774\uc8fc\ubbfc\uc774 \ubaa8\uc600\ub2e4. \ub3c4\uc2dc\uac00 \ud06c\ub2e4\ub294 \uac83\uc740 \uac74\ubb3c\uc774 \ub9ce\ub2e4\ub294 \ub73b\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uae30\uc220\uacfc \uacbd\ud5d8\uc744 \uac00\uc9c4 \uc0ac\ub78c\uc774 \uac00\uae4c\uc6b4 \uacf5\uac04\uc5d0\uc11c \ub9cc\ub0a0 \uc218 \uc788\ub2e4\ub294 \uc758\ubbf8\ub3c4 \uc788\ub2e4. \uc7a5\uc778\uc758 \ubb3c\uac74\uc5d0\ub294 \uc7ac\ub8cc\uac00 \ud544\uc694\ud558\uace0 \uc0c1\uc778\uc5d0\uac8c\ub294 \uac70\ub798\ud560 \uc0c1\ub300\uac00 \ud544\uc694\ud558\ub2e4. \uae00\uc744 \ubc30\uc6b0\uace0 \uac00\ub974\uce58\ub294 \ud65c\ub3d9\uc5d0\ub3c4 \uc0dd\ud65c\uc744 \uc720\uc9c0\ud560 \ud658\uacbd\uc774 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uc774\ub7f0 \ud65c\ub3d9\uc774 \ud55c \ub3c4\uc2dc\uc5d0 \uacb9\uce60 \ub54c \ub3c4\uc2dc\ub294 \ub2e8\uc21c\ud788 \uc778\uad6c\uac00 \ubaa8\uc778 \uc7a5\uc18c\ubcf4\ub2e4 \ubcf5\uc7a1\ud55c \uad00\uacc4\uc758 \uacf5\uac04\uc774 \ub41c\ub2e4. \ucf54\ub974\ub3c4\ubc14\ub294 \uad50\uc5ed\ubfd0 \uc544\ub2c8\ub77c \ud559\ubb38\uacfc \uc608\uc220\uc758 \uc911\uc2ec\uc73c\ub85c\ub3c4 \uc131\uc7a5\ud588\ub2e4. \uad50\uc7ac\ub294 \ucf58\uc2a4\ud0c4\ud2f0\ub178\ud3f4\ub9ac\uc2a4\uc640 \ubc14\uadf8\ub2e4\ub4dc\uc5d0 \uacac\uc904 \ub9cc\ud55c \ub3c4\uc2dc\ub85c \uc18c\uac1c\ud55c\ub2e4. \uc774\ub294 \uc138 \ub3c4\uc2dc\uac00 \ubaa8\ub4e0 \uc810\uc5d0\uc11c \uac19\uc558\ub2e4\ub294 \ub9d0\ubcf4\ub2e4 \ub2f9\uc2dc\uc758 \ub113\uc740 \uad50\ub958 \uc18d\uc5d0\uc11c \ucf54\ub974\ub3c4\ubc14\uc758 \uc704\uc0c1\uc744 \uc774\ud574\ud558\ub294 \ud45c\ud604\uc774\ub2e4. \ubc30\uc6c0\uc740 \ub3c4\uc2dc\ub97c \ub4dc\ub098\ub4dc\ub294 \uae38\uacfc \ubb34\uad00\ud558\uc9c0 \uc54a\uc558\ub2e4. \ubb3c\uac74\uacfc \ud568\uaed8 \ucc45\uacfc \uc9c0\uc2dd, \uac00\ub974\uce58\ub294 \uc0ac\ub78c\uc774 \uc774\ub3d9\ud560 \uc218 \uc788\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc0c1\uc5c5\uc774 \ud65c\ubc1c\ud558\uba74 \uc800\uc808\ub85c \ubaa8\ub450\uac00 \uad50\uc721\uc744 \ub204\ub9b0\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc5f0\uacb0\uc740 \uac00\ub2a5\uc131\uc744 \ub113\ud600 \uc8fc\uc9c0\ub9cc \uadf8 \uae30\ud68c\ub97c \ub204\ub9ac\ub294 \uc870\uac74\uae4c\uc9c0 \uac19\uac8c \ub9cc\ub4e4\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc54c\uc548\ub2ec\ub8e8\uc2a4\uc5d0\ub294 \uc5ec\ub7ec \uc885\uad50\uc640 \ubbfc\uc871\uc774 \ud568\uaed8 \uc0b4\uc544\uac00\uba70 \ub9cc\ub4e4\uc5b4 \ub0b8 \ubb38\ud654\uac00 \uc788\uc5c8\ub2e4. \uc774 \uc0ac\uc2e4\uc740 \uc911\uc694\ud558\uc9c0\ub9cc \uc5b8\uc81c\ub098 \ud3c9\ub4f1\ud558\uace0 \uac08\ub4f1 \uc5c6\ub294 \uc0ac\ud68c\uc600\ub2e4\ub294 \ub73b\uc73c\ub85c \ubc14\uafc0 \uc218\ub294 \uc5c6\ub2e4. \uacf5\uc874\uacfc \uad8c\ub825\uc758 \ucc28\uc774, \uc815\uce58\uc801 \uacbd\uc7c1\uc740 \uac19\uc740 \uc2dc\ub300\uc5d0 \ud568\uaed8 \uc874\uc7ac\ud560 \uc218 \uc788\ub2e4. \uad50\uc7ac\ub3c4 \uad00\uc6a9\uc744 \ubcf4\uc774\ub294 \ud1b5\uce58\uac00 \uc788\uc5c8\ub358 \ud55c\ud3b8 \ub2e4\ub978 \uc2e0\uc559\uc758 \uc9c0\ubc30\uc790\ub4e4\uacfc \uc804\uc7c1\uc774 \uc774\uc5b4\uc84c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud568\uaed8 \uc0b4\uc558\ub2e4\ub294 \ud55c \ubb38\uc7a5\uc744 \ub0ad\ub9cc\uc801\uc778 \ud48d\uacbd\uc73c\ub85c\ub9cc \ub9cc\ub4e4\uba74 \ub2f9\uc2dc \uc8fc\ubbfc\uc758 \ub2e4\ub978 \uc870\uac74\uc744 \ub193\uce5c\ub2e4. \ub3c4\uc2dc\uc758 \uc131\ucde8\ub97c \uc54c\uc544\ubcf4\ub294 \uc77c\uacfc \uadf8 \uc548\uc758 \uae34\uc7a5\uc744 \uc778\uc815\ud558\ub294 \uc77c\uc740 \ud568\uaed8 \ud560 \uc218 \uc788\ub2e4. \ucf54\ub974\ub3c4\ubc14\ub97c \uc911\uc2ec\uc73c\ub85c \ud55c \uc815\uce58\uc801 \ud1b5\ud569\uc740 \uacc4\uc18d \uc720\uc9c0\ub418\uc9c0 \uc54a\uc558\ub2e4. \uc9c0\ubc30\uce35 \ub0b4\ubd80\uc758 \uac08\ub4f1\uacfc \ubd84\uc5f4\uc774 \uc0dd\uacbc\uace0 \uc54c\uc548\ub2ec\ub8e8\uc2a4\uc5d0\ub294 \uc5ec\ub7ec \ud6c4\uacc4 \uad6d\uac00\uac00 \ub4f1\uc7a5\ud588\ub2e4. \ubb38\ud654\uc640 \uad50\uc5ed\uc774 \ubc88\uc131\ud588\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc815\uce58\uc801 \uc548\uc815\uae4c\uc9c0 \uc790\ub3d9\uc73c\ub85c \ubcf4\uc7a5\ub418\uc9c0\ub294 \uc54a\uc558\ub358 \uac83\uc774\ub2e4. \uc774\ud6c4\uc758 \uad00\uacc4\ub3c4 \ub2e8\uc21c\ud788 \uc885\uad50\uac00 \uac19\uc740 \uc0ac\ub78c\ub07c\ub9ac \ud55c\ud3b8\uc744 \uc774\ub8ec \ubaa8\uc2b5\ub9cc\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uad50\uc7ac\ub294 \ubb34\uc2ac\ub9bc \uad6d\uac00\ub4e4\ub07c\ub9ac \ub2e4\ud22c\uace0 \uae30\ub3c5\uad50 \uc138\ub825\uacfc \ub3d9\ub9f9\uc744 \ub9fa\uae30\ub3c4 \ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub3c4\uc2dc\uc758 \uc5ed\uc0ac\ub294 \uc544\ub984\ub2e4\uc6b4 \uc804\uc131\uae30\uc640 \uac11\uc791\uc2a4\ub7ec\uc6b4 \uc885\ub9d0 \ub450 \uc7a5\uba74\ubcf4\ub2e4 \ub9ce\uc740 \uc120\ud0dd\uc73c\ub85c \uc774\ub8e8\uc5b4\uc838 \uc788\uc5c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uac10\uade4\ub098\ubb34\uc640 \uadf8\ub298\uc9c4 \ub730\uc744 \ud45c\ud604\ud55c AI \uc0bd\ud654\ub2e4. \ucf54\ub974\ub3c4\ubc14\uc758 \ud2b9\uc815 \uc815\uc6d0\uc774\ub098 \uc911\uc138 \uc8fc\ud0dd\uc744 \uc815\ud655\ud788 \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc774 \uadf8\ub9bc\uc744 \uadfc\uac70\ub85c \ub2f9\uc2dc \uc9d1\uc758 \ubc30\uce58\uc640 \uc0dd\ud65c \ub3c4\uad6c\ub97c \ud655\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub300\uc2e0 \ub098\ubb34\uc640 \uadf8\ub298, \uc0ac\ub78c\ub4e4\uc774 \uc26c\uc5b4 \uac08 \uc218 \uc788\ub294 \uc791\uc740 \uacf5\uac04\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc785\uad6c\ub85c \ubcfc \uc218 \uc788\ub2e4. \uc2e4\uc81c\ub85c \ud655\uc778\ud55c \uc791\ubb3c\uc758 \uc774\ub3d9\uacfc \ub3c4\uc2dc\uc758 \uc131\uc7a5\uc740 \uadfc\uac70\uc790\ub8cc\uc5d0\uc11c \uc77d\uace0, \uadf8\ub9bc\uc740 \uae00\ub85c \ub4e4\uc5b4\uac00\ub294 \ubd84\uc704\uae30\ub97c \ub3d5\ub294\ub2e4. \uc790\ub8cc\uc640 \uc0c1\uc0c1\uc758 \uc5ed\ud560\uc744 \ub098\ub204\uba74 \ud48d\uacbd\uc744 \ud3b8\ud558\uac8c \uac10\uc0c1\ud560 \uc218 \uc788\ub2e4. \uc624\ub80c\uc9c0 \ud55c \uc54c\ub9cc\uc73c\ub85c \ucf54\ub974\ub3c4\ubc14\uc758 \uc5ed\uc0ac\ub97c \ubaa8\ub450 \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uba3c \uacf3\uc5d0\uc11c \uc628 \uc791\ubb3c\uc774 \ub3c4\uc2dc\uc758 \uc775\uc219\ud55c \ud48d\uacbd\uc774 \ub420 \uc218 \uc788\ub2e4\ub294 \uc810\uc740 \ubcf4\uc5ec \uc900\ub2e4. \uc0c1\uc778\uacfc \uc7a5\uc778, \ud559\uc790\uac00 \ub4dc\ub098\ub4e0 \uae38\ub3c4 \ube44\uc2b7\ud558\uac8c \ub3c4\uc2dc\uc758 \uc131\uaca9\uc744 \ubc14\uafb8\uc5c8\ub2e4. \ub2e4\uc74c\uc5d0 \uc5b4\ub290 \ub3c4\uc2dc\uc758 \ud2b9\ubcc4\ud55c \uba39\uc744\uac70\ub9ac\ub098 \ub098\ubb34\ub97c \ub9cc\ub098\uba74 \uc6d0\ub798\ubd80\ud130 \uac70\uae30 \uc788\uc5c8\ub294\uc9c0 \uad81\uae08\ud574\ud574 \ubcf4\uc790. \uadf8 \uc9c8\ubb38\uc740 \ub73b\ubc16\uc5d0 \ubc14\ub2e4\uc640 \ub2e4\ub978 \uc9c0\uc5ed\uc758 \uc0ac\ub78c\ub4e4\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\ub2e4. \ucf54\ub974\ub3c4\ubc14\uc758 \uac10\uade4 \uc774\uc57c\uae30\ub294 \ud55c \ub3c4\uc2dc \uc548\uc758 \ud48d\uacbd\uc5d0 \ub113\uc740 \uc138\uacc4\uac00 \ub4e4\uc5b4\uc624\ub294 \ubc29\uc2dd\uc774\ub2e4."}, {"id": "cusco-roads-and-empire", "title": "\ucfe0\uc2a4\ucf54 \u2014 \uc0b0\uae38\uc740 \uc5b4\ub5bb\uac8c \uc81c\uad6d\uc744 \ubb36\uc5c8\uc744\uae4c", "summary": "\uc548\ub370\uc2a4\uc758 \uc218\ub3c4 \ucfe0\uc2a4\ucf54\uc640 \uc778\uce74 \ub3c4\ub85c\ub9dd\uc744 \ud1b5\ud574 \uc774\ub3d9\u00b7\uc0dd\uc0b0\u00b7\ud1b5\uce58\uc758 \uc5f0\uacb0\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/cusco-roads-and-empire/index.html", "image": "../media/cusco-roads-and-empire.jpg", "alt": "\uc0b0 \uc0ac\uc774\ub85c \ub3cc\uacc4\ub2e8\uacfc \uae38\uc774 \uc774\uc5b4\uc9c0\ub294 \uc778\uce74 \ud2b8\ub808\uc77c\uc758 \uc2e4\uc81c \uc0ac\uc9c4.", "text": "\ucfe0\uc2a4\ucf54 \u2014 \uc0b0\uae38\uc740 \uc5b4\ub5bb\uac8c \uc81c\uad6d\uc744 \ubb36\uc5c8\uc744\uae4c \ub192\uc740 \uc218\ub3c4\uc5d0\uc11c \uc774\uc5b4\uc9c4 \uae38\uacfc \ub2e4\ub9ac\uc758 \uc774\uc57c\uae30 \uc548\ub370\uc2a4\uc758 \uc218\ub3c4 \ucfe0\uc2a4\ucf54\uc640 \uc778\uce74 \ub3c4\ub85c\ub9dd\uc744 \ud1b5\ud574 \uc774\ub3d9\u00b7\uc0dd\uc0b0\u00b7\ud1b5\uce58\uc758 \uc5f0\uacb0\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc0b0\uae38\uc744 \uc624\ub974\ub2e4\uac00 \ub3cc\uacc4\ub2e8\uc774 \ub2a5\uc120 \ub108\uba38\ub85c \uc774\uc5b4\uc9c0\ub294 \ubaa8\uc2b5\uc744 \ub9cc\ub09c\ub2e4. \ud48d\uacbd\uc740 \uba4b\uc9c0\uc9c0\ub9cc \ubb34\uac70\uc6b4 \uc9d0\uc744 \ub4e4\uace0 \uac78\uc5b4\uc57c \ud55c\ub2e4\uba74 \uc0dd\uac01\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uba40\ub9ac \uc788\ub294 \uc0ac\ub78c\uacfc \ubb3c\uac74\uc744 \uc5f0\uacb0\ud558\ub294 \uc77c\uc740 \ub192\uc740 \uc0b0\uc5d0\uc11c\ub294 \ub354\uc6b1 \uad6c\uccb4\uc801\uc778 \uc218\uace0\uac00 \ub41c\ub2e4. \uc778\uce74\uc758 \uc218\ub3c4 \ucfe0\uc2a4\ucf54\ub294 \uc548\ub370\uc2a4\uc0b0\ub9e5\uc758 \ub192\uc740 \uacf3\uc5d0 \uc788\uc5c8\ub2e4. \uc774\uacf3\uc744 \uc911\uc2ec\uc73c\ub85c \ub113\uc740 \uc601\uc5ed\uc744 \ub2e4\uc2a4\ub9ac\ub824\uba74 \uc88b\uc740 \ub3cc \uac74\ubb3c\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud588\ub2e4. \uacc4\uace1\uacfc \uc0b0, \uac74\uc870\ud55c \uc9c0\uc5ed\uc744 \uc9c0\ub098 \uc0ac\ub78c\uacfc \ubb3c\uc790\ub97c \uc774\uc5b4 \uc904 \uae38\uc774 \ud544\uc694\ud588\ub2e4. \ub3c4\uc2dc\ub97c \uc774\ud574\ud558\ub294 \uc2dc\uc120\uc744 \ub3c4\ub85c \ucabd\uc73c\ub85c \uc62e\uaca8 \ubcf4\uc790. \ucfe0\uc2a4\ucf54\uc758 \uc55e\uc120 \uacf5\ub3d9\uccb4\ub294 \uac10\uc790\uc640 \uc625\uc218\uc218\ub97c \uae30\ub974\uace0 \ub77c\ub9c8 \uac19\uc740 \ub3d9\ubb3c\uc744 \uae30\ub974\ub294 \ub18d\uacbd \uc0dd\ud65c\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uad50\uc7ac\ub294 1000\ub144 \ubb34\ub835 \uc774 \uc9c0\uc5ed\uc5d0 \ub18d\uacbd \ub9c8\uc744 \uc0ac\ub78c\ub4e4\uc774 \uc790\ub9ac\ud558\uace0 \uc788\uc5c8\uc74c\uc744 \uc124\uba85\ud55c\ub2e4. \ud6c4\ub300\uc758 \uac70\ub300\ud55c \uc81c\uad6d\uc774 \ucc98\uc74c\ubd80\ud130 \uc644\uc131\ub418\uc5b4 \uc788\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2dc\uac04\uc774 \ud750\ub974\uba70 \ucfe0\uc2a4\ucf54\uc758 \uc138\ub825\uc740 \uc8fc\ubcc0\uacfc \uacbd\uc7c1\ud558\uace0 \uad00\uacc4\ub97c \ub113\ud614\ub2e4. \ub3c4\uc2dc\uac00 \uc131\uc7a5\ud55c \ub4a4\uc5d0\ub294 \uadf8 \uc2dc\uc791\uc744 \uc124\uba85\ud558\ub294 \uc804\uc2b9\ub3c4 \uc911\uc694\ud574\uc84c\ub2e4. \ub3cc\uc774 \uc804\uc0ac\ub85c \ubcc0\ud588\ub2e4\ub294 \uc774\uc57c\uae30\ub098 \ud669\uae08 \uc9c0\ud321\uc774\uc758 \uc804\uc124\uc740 \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc774 \uc790\uc2e0\ub4e4\uc758 \uae30\uc6d0\uc744 \uc5b4\ub5bb\uac8c \uc774\ud574\ud588\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\uc9c0\ub9cc, \uc2e4\uc81c \uc0ac\uac74\uc758 \uae30\ub85d\uacfc \uadf8\ub300\ub85c \uac19\uc9c0\ub294 \uc54a\ub2e4. \ucfe0\uc2a4\ucf54\ub294 \ud574\ubc1c 3\ucc9c \ubbf8\ud130\uac00 \ub118\ub294 \uc548\ub370\uc2a4 \uace0\uc9c0\ub300\uc5d0 \uc790\ub9ac\ud55c\ub2e4. \uc778\uce74\uc758 \uc11d\uacf5\ub4e4\uc740 \ub3cc\uc744 \uc815\uad50\ud558\uac8c \ub2e4\ub8e8\uc5b4 \uac74\ubb3c\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \uc624\ub298\ub0a0 \uadfc\ucc98\uc758 \uc0ad\uc0ac\uc774\uc640\ub9cc\uc5d0 \ub0a8\uc740 \uc11d\ubcbd\ub3c4 \uc774\ub7f0 \uae30\uc220\uc744 \uc54c\ub824 \uc8fc\ub294 \uc790\ub8cc\ub2e4. \ud558\uc9c0\ub9cc \uc218\ub3c4\ub294 \uc8fc\ubcc0\uc5d0\uc11c \uba39\uc744\uac70\ub9ac\uc640 \uc790\uc6d0\uc774 \ub4e4\uc5b4\uc624\uc9c0 \uc54a\uc73c\uba74 \uc720\uc9c0\ub418\uae30 \uc5b4\ub835\ub2e4. \uc911\uc694\ud55c \uc0ac\ub78c\uc774 \ubaa8\uc774\ub294 \uc911\uc2ec\uc774 \uc788\ub2e4\ub294 \uac83\uc740 \uadf8\uacf3\uacfc \ub2e4\ub978 \uc9c0\uc5ed \uc0ac\uc774\uc5d0 \uc9c0\uc18d\uc801\uc778 \uc774\ub3d9\uc774 \ud544\uc694\ud558\ub2e4\ub294 \ub73b\uc774\uae30\ub3c4 \ud558\ub2e4. \uac74\ubb3c\uc758 \ud06c\uae30\uc640 \uae38\uc758 \uc874\uc7ac\ub97c \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ub3c4\uc2dc\uc758 \uc0dd\ud65c\uc774 \ubcf4\uc778\ub2e4. \uc778\uce74\uac00 \uc9c0\ubc30\ud55c \uc9c0\uc5ed\uc5d0\ub294 \ub192\uc740 \uc0b0\uacfc \uae4a\uc740 \uacc4\uace1, \uc0ac\ub9c9\uacfc \ud574\uc548\uc758 \uc881\uc740 \ud3c9\uc9c0\uac00 \uc788\uc5c8\ub2e4. \uace7\uc740 \uae38 \ud558\ub098\ub97c \ubaa8\ub4e0 \uacf3\uc5d0 \ub611\uac19\uc774 \ub193\uc744 \uc218 \uc788\ub294 \ud658\uacbd\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc774\ub3d9\uc740 \uc9c0\ud615\uc5d0 \ub9de\ucd94\uc5b4 \ub2e4\ub978 \ubc29\ubc95\uc744 \ud544\uc694\ub85c \ud588\ub2e4. \uad50\uc7ac\ub294 \ud3c9\uc9c0\uc758 \uc9c1\uc120 \uad6c\uac04\uacfc \uc0b0\uae38\uc758 \uad7d\uc774, \ub3cc\uacc4\ub2e8\uacfc \uc5ec\ub7ec \uc7ac\ub8cc\uc758 \ub2e4\ub9ac\ub97c \ud568\uaed8 \uc124\uba85\ud55c\ub2e4. \ub3c4\ub85c\ub9dd\uc774 \uc788\ub2e4\ub294 \ud55c\ub9c8\ub514 \ub4a4\uc5d0\ub294 \uc11c\ub85c \ub2e4\ub978 \ud615\ud0dc\uc758 \uae38\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uae38\uc774 \uc88b\ub2e4\ub294 \uac83\uc740 \uc5b8\uc81c\ub098 \ub113\uace0 \ud3c9\ud3c9\ud558\ub2e4\ub294 \ub73b\ub9cc\uc740 \uc544\ub2c8\uc5c8\ub358 \uc148\uc774\ub2e4. \ub3c4\ub85c\ub9dd\uc758 \uc77c\ubd80\ub294 \uc778\uce74 \uc774\uc804\ubd80\ud130 \uc874\uc7ac\ud588\ub2e4. \uc778\uce74\ub294 \uc774\ub97c \ub354 \ud06c\uac8c \uc5f0\uacb0\ud558\uace0 \ud655\ub300\ud558\uba70 \uac1c\uc120\ud588\ub2e4. \ud1b5\uce58\uc790\uac00 \ub113\uc740 \ub545\uc744 \ub2e4\uc2a4\ub9ac\ub824\ub294 \ubaa9\ud45c\uc640 \uc9c0\uc5ed\uc5d0 \ucd95\uc801\ub41c \uc774\ub3d9\uc758 \uae30\uc220\uc774 \ub9cc\ub09c \uac83\uc774\ub2e4. \uc774 \uc810\uc744 \uc54c\uba74 \uac70\ub300\ud55c \uae38\uc758 \ub9dd\uc744 \ud55c \uc0ac\ub78c\uc774 \ucc98\uc74c\ubd80\ud130 \ub05d\uae4c\uc9c0 \uc124\uacc4\ud574 \uc138\uc6b4 \uc791\ud488\ucc98\ub7fc \ubcf4\uae30 \uc5b4\ub835\ub2e4. \uc5ec\ub7ec \uc2dc\ub300\uc640 \uc9c0\uc5ed\uc758 \uacbd\ud5d8\uc774 \uc774\uc5b4\uc84c\ub2e4. \uc81c\uad6d\uc758 \uc774\ub984\uc73c\ub85c \uae30\uc5b5\ub418\ub294 \uae30\ubc18\uc2dc\uc124\uc5d0\ub3c4 \uadf8\ubcf4\ub2e4 \uc55e\uc120 \uc0ac\ub78c\ub4e4\uc758 \uae38\uc774 \ub4e4\uc5b4 \uc788\uc744 \uc218 \uc788\ub2e4. \uc778\uce74\uc758 \ub3c4\ub85c\ub294 \uad70\ub300\uac00 \uc774\ub3d9\ud558\ub294 \ub370 \uc4f0\uc600\uace0, \uc9c0\ubc29\uc5d0\uc11c \uc0dd\uc0b0\ud55c \ubb3c\uac74\uc744 \uc800\uc7a5\uace0\ub85c \uc62e\uae30\ub294 \ub370\ub3c4 \uc911\uc694\ud588\ub2e4. \uae38\uc740 \uc5ec\ud589\uc758 \uc990\uac70\uc6c0\ub9cc\uc744 \uc704\ud574 \uc874\uc7ac\ud55c \uc2dc\uc124\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ud1b5\uce58\uc640 \uc790\uc6d0\uc758 \ubc30\ubd84\uc744 \uac00\ub2a5\ud558\uac8c \ud558\ub294 \uc7a5\uce58\uc774\uae30\ub3c4 \ud588\ub2e4. \uc5b4\ub290 \uc9c0\uc5ed\uc5d0\uc11c \ubb3c\uac74\uc744 \uac70\ub450\uace0 \uc5b4\ub514\uc5d0 \ubaa8\uc744\uc9c0 \uc815\ud558\ub294 \ud798\uc740 \uc8fc\ubbfc\uc758 \uc0dd\ud65c\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uae38\uc774 \uc798 \uc774\uc5b4\uc84c\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8 \uae38\uc744 \uc774\uc6a9\ud55c \uc81c\ub3c4\uac00 \ubaa8\ub450\uc5d0\uac8c \uac19\uc740 \uc774\uc775\uc744 \uc8fc\uc5c8\ub2e4\ub294 \ud3c9\uac00\ub294 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \ud3b8\ub9ac\ud55c \uc774\ub3d9\uc758 \uc5ed\uc0ac\uc5d0\ub294 \ub3d9\uc6d0\uacfc \uc758\ubb34\uc758 \ubb38\uc81c\ub3c4 \ud568\uaed8 \uc788\ub2e4. \uc778\uce74\ub294 \uc815\ubcf5\ud55c \uc9c0\uc5ed\uc5d0 \uacf5\ub0a9\uacfc \ub178\ub3d9 \uc758\ubb34\ub97c \uc694\uad6c\ud588\ub2e4. \ub113\uc740 \uc601\uc5ed\uc758 \uc0dd\uc0b0\uacfc \ub178\ub3d9\uc774 \uc81c\uad6d\uc758 \ud65c\ub3d9\uc744 \ub4b7\ubc1b\uce68\ud55c \uac83\uc774\ub2e4. \ub3cc\ub85c \ub9cc\ub4e0 \uc218\ub3c4\uc758 \ubaa8\uc2b5\ub9cc \ubcf4\uba74 \uc774 \uad00\uacc4\uac00 \ud654\uba74 \ubc16\uc5d0 \ub0a8\uae30 \uc27d\ub2e4. \uadf8\ub798\uc11c \ucfe0\uc2a4\ucf54\ub97c \uac10\uc0c1\ud560 \ub54c\ub294 \uc911\uc694\ud55c \uac74\ubb3c\uc774 \uba87 \uac1c \uc788\uc5c8\ub294\uc9c0\ubfd0 \uc544\ub2c8\ub77c \uadf8\uac83\uc744 \uc720\uc9c0\ud55c \uba39\uc744\uac70\ub9ac\uc640 \uc77c\uc190\uc774 \uc5b4\ub514\uc11c \uc654\ub294\uc9c0\ub3c4 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ud55c \ub3c4\uc2dc\uc758 \uc704\uc0c1\uc740 \ub3c4\uc2dc \uc548\ucabd\uc758 \uc131\ucde8\uc640 \ubc14\uae65 \uc9c0\uc5ed\uc758 \ubd80\ub2f4\uc774 \uc5f0\uacb0\ub41c \uacb0\uacfc\uc77c \uc218 \uc788\ub2e4. \uc218\ub3c4\uc5d0\uc11c \uba40\uc5b4\uc9c4 \uae38\ub3c4 \ub3c4\uc2dc\uc0ac\uc758 \uc77c\ubd80\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \uc778\uce74 \ud2b8\ub808\uc77c\uc758 \uc2e4\uc81c \ub3cc\uacc4\ub2e8\uacfc \uc0b0 \ud48d\uacbd\uc774\ub2e4. \ucfe0\uc2a4\ucf54 \uc2dc\uac00\uc9c0 \uc790\uccb4\ub97c \ucd2c\uc601\ud55c \uc0ac\uc9c4\uc774\ub098 \uc804\uccb4 \ub3c4\ub85c\ub9dd\uc758 \ubaa8\uc2b5\uc740 \uc544\ub2c8\ub2e4. \uae38\uc758 \ud55c \uad6c\uac04\uc5d0\uc11c \uc0b0\uc545 \uc9c0\ud615\uacfc \uc0ac\ub78c\uc758 \uc774\ub3d9 \ud1b5\ub85c\uac00 \ub9cc\ub098\ub294 \ubc29\uc2dd\uc744 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uacc4\ub2e8\uc744 \ub9cc\ub4e0 \ub3cc\uacfc \uc8fc\ubcc0\uc758 \uacbd\uc0ac, \uae38\uc774 \uc0ac\ub77c\uc9c0\ub294 \ubc29\ud5a5\uc744 \ucc28\ub840\ub85c \ubcf4\uba74 \uc774\ub3d9\uc758 \uaddc\ubaa8\ub97c \ubab8\uc73c\ub85c \uc870\uae08 \uc0c1\uc0c1\ud558\uac8c \ub41c\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4\ub9cc\uc73c\ub85c \ub204\uac00 \uc5b4\ub290 \ub0a0 \uc774 \uad6c\uac04\uc744 \uc9c0\ub098\uac14\ub294\uc9c0 \ud655\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc2e4\uc81c \uad00\ucc30\uacfc \uc5ed\uc0ac\uc801 \uc124\uba85\uc758 \ubc94\uc704\ub97c \ub098\ub204\uc5b4 \ubcf4\uc544\ub3c4 \uae38\uc758 \uc778\uc0c1\uc740 \ucda9\ubd84\ud788 \uac15\ud558\ub2e4. \ucfe0\uc2a4\ucf54\ub97c \uae30\uc5b5\ud560 \ub54c \ub192\uc740 \ub3cc \uac74\ubb3c \uacc1\uc5d0 \uba3c \uacf3\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uae38\ub3c4 \ub0a8\uaca8 \ubcf4\uc790. \uc0b0\uacfc \uacc4\uace1\uc744 \uac74\ub108\uc624\ub294 \uc2dd\ub7c9\uacfc \ubb3c\uc790, \uc774\ub3d9\ud558\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc2dc\uac04\uc774 \uc218\ub3c4\ub97c \ub9cc\ub4e4\uc5c8\ub2e4. \ub3c4\uc2dc\uc758 \uc5ed\uc0ac\uc640 \ub3c4\ub85c\uc758 \uc5ed\uc0ac\ub294 \ub530\ub85c \ub5a8\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uc9c0\uae08 \uc6b0\ub9ac\uac00 \uc0ac\ub294 \ub3c4\uc2dc\ub3c4 \ub208\uc5d0 \ubcf4\uc774\ub294 \uac74\ubb3c\ub9cc\uc73c\ub85c \uc644\uc131\ub418\uc9c0 \uc54a\ub294\ub2e4. \ub2e4\ub978 \uc9c0\uc5ed\uacfc \uc5f0\uacb0\ub41c \uc774\ub3d9\uc774 \ub9e4\uc77c\uc758 \uc0dd\ud65c\uc744 \uac00\ub2a5\ud558\uac8c \ud55c\ub2e4. \uc778\uce74\uc758 \uc0b0\uae38\uc740 \uc624\ub798\ub41c \uc81c\uad6d\uc758 \uae30\uc220\uc744 \ubcf4\uc5ec \uc8fc\uba74\uc11c, \ub3c4\uc2dc\ub97c \uc5b4\ub514\uae4c\uc9c0 \ubcf4\uc544\uc57c \ud560\uc9c0 \ubb3b\ub294 \uc9c8\ubb38\ub3c4 \ub0a8\uae34\ub2e4."}, {"id": "domesday-1086-land-testimony-and-power", "title": "\ub460\uc988\ub370\uc774 \uc870\uc0ac \u2014 \uc655\uc740 \uc65c \ub545\uacfc \uc18c\uc758 \uc218\ub97c \ubb3c\uc5c8\uc744\uae4c", "summary": "1086\ub144 \ud1a0\uc9c0\uc640 \uc99d\uc5b8, \uc815\ubcf5 \uc774\ud6c4\uc758 \uad8c\ub825\uc744 \uc7a5\ubd80\ub85c \uc77d\uae30\uc758 \ubc30\uacbd\uacfc \uc804\uac1c, \uc774\ud6c4\uc758 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities", "ideas"], "url": "stories/domesday-1086-land-testimony-and-power/index.html", "image": "../media/domesday-1086-land-testimony-and-power.png", "alt": "\uc7a5\ubd80\ub97c \uc4f0\ub294 \uc870\uc0ac\uad00\uacfc \uc9c0\uc5ed \uc0ac\ub78c\ub4e4\uc758 \ub9cc\ub0a8\uc744 \uc0c1\uc0c1\ud55c \ub460\uc988\ub370\uc774 \uc870\uc0ac \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ub460\uc988\ub370\uc774 \uc870\uc0ac \u2014 \uc655\uc740 \uc65c \ub545\uacfc \uc18c\uc758 \uc218\ub97c \ubb3c\uc5c8\uc744\uae4c 1086\ub144 \ud1a0\uc9c0\uc640 \uc99d\uc5b8, \uc815\ubcf5 \uc774\ud6c4\uc758 \uad8c\ub825\uc744 \uc7a5\ubd80\ub85c \uc77d\uae30 1086\ub144 \ud1a0\uc9c0\uc640 \uc99d\uc5b8, \uc815\ubcf5 \uc774\ud6c4\uc758 \uad8c\ub825\uc744 \uc7a5\ubd80\ub85c \uc77d\uae30\uc758 \ubc30\uacbd\uacfc \uc804\uac1c, \uc774\ud6c4\uc758 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc655\uc774 \uc0c8\ub85c \ub2e4\uc2a4\ub9ac\uac8c \ub41c \ub545\uc744 \uc54c\uace0 \uc2f6\ub2e4\uba74 \ubb34\uc5c7\ubd80\ud130 \ubb3c\uc5b4\uc57c \ud560\uae4c. 1086\ub144 \uc789\uae00\ub79c\ub4dc\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c4 \uc870\uc0ac\ub294 \ub204\uac00 \ub545\uc744 \uac00\uc84c\uace0 \ubb34\uc5c7\uc744 \uc0dd\uc0b0\ud558\uba70 \uc5bc\ub9c8\ub9cc\ud07c\uc758 \ubd80\ub2f4\uc744 \uc9c8 \uc218 \uc788\ub294\uc9c0 \uae30\ub85d\ud588\ub2e4. \uc624\ub298\ub0a0 \ub460\uc988\ub370\uc774 \ubd81\uc73c\ub85c \uc54c\ub824\uc9c4 \ubb38\uc11c\ub294 \ub2e8\uc21c\ud788 \uc624\ub798\ub41c \uba85\ubd80\uac00 \uc544\ub2c8\ub77c \uc815\ubcf5 \ub4a4\uc758 \uad8c\ub825\uacfc \uc0dd\ud65c\uc774 \ub9cc\ub09c \uc7a5\ubd80\ub2e4. \ub178\ub974\ub9cc \uc815\ubcf5 \uc774\ud6c4 \uc70c\ub9ac\uc5c4 \uc655\uc740 \uc789\uae00\ub79c\ub4dc\ub97c \ud1b5\uce58\ud588\ub2e4. \uadf8\ub7ec\ub098 \uc655\uc774 \uad6d\uac00\ub97c \uc5bb\uc5c8\ub2e4\ub294 \ub9d0\uacfc \uadf8 \uc548\uc758 \ud1a0\uc9c0\u00b7\uc7ac\uc0b0\u00b7\uad8c\ub9ac \uad00\uacc4\ub97c \ubaa8\ub450 \ud30c\uc545\ud588\ub2e4\ub294 \ub9d0\uc740 \ub2e4\ub974\ub2e4. \uc9c0\uc5ed\ub9c8\ub2e4 \ub204\uac00 \ubb34\uc5c7\uc744 \ubcf4\uc720\ud558\uace0 \uc5b4\ub5a4 \uc758\ubb34\ub97c \uc9c0\ub294\uc9c0 \uc54c\uc544\uc57c \uc2e4\uc81c \ud1b5\uce58\uc640 \uc218\uc785\uc744 \uc870\uc9c1\ud560 \uc218 \uc788\uc5c8\ub2e4. 1085\ub144 \ub9d0\uc758 \ub17c\uc758\ub97c \uac70\uccd0 \uc870\uc0ac\uad00\ub4e4\uc774 \ud30c\uacac\ub418\uc5c8\ub2e4. \uc655\uc774 \ubaa8\ub4e0 \ub9c8\uc744\uc744 \uc9c1\uc811 \ub3cc\uc544\ub2e4\ub2cc \uac83\uc774 \uc544\ub2c8\ub77c \uc5ec\ub7ec \uc9c0\uc5ed\uc758 \uc99d\uc5b8\uacfc \uc790\ub8cc\ub97c \ubaa8\uc73c\ub294 \ubc29\uc2dd\uc774\uc5c8\ub2e4. \uc7a5\ubd80\uc758 \ub4a4\uc5d0\ub294 \uc0ac\ub78c\uc744 \ubcf4\ub0b4\uace0 \ub2f5\uc744 \ubc1b\uace0 \uc11c\ub85c \ub2e4\ub978 \uc8fc\uc7a5\uc744 \ube44\uad50\ud558\ub294 \ud589\uc815\uc758 \uacfc\uc815\uc774 \uc788\uc5c8\ub2e4. \uc870\uc0ac\ub294 \ud604\uc7ac\uc758 \ubcf4\uc720\uc790\ub9cc \ubb3b\uc9c0 \uc54a\uc558\ub2e4. \uc5d0\ub4dc\uc6cc\ub4dc \uc655 \uc2dc\ub300\uc758 \ubcf4\uc720\uc640 \uac00\uce58, \uc815\ubcf5 \uc774\ud6c4\uc758 \uc0c1\ud0dc\ub97c \ud568\uaed8 \uae30\ub85d\ud588\ub2e4. \uc804\uc7c1\uacfc \uad8c\ub825 \uad50\uccb4\uac00 \ud1a0\uc9c0\uc758 \uc18c\uc720\uc640 \uad8c\ub9ac\uc5d0 \uc5b4\ub5a4 \ubcc0\ud654\ub97c \ub9cc\ub4e4\uc5c8\ub294\uc9c0 \uc77d\uc744 \uc218 \uc788\ub294 \uc774\uc720\ub2e4. \ud2b9\ud788 \uc655\uc5d0\uac8c \uc9c1\uc811 \ub545\uc744 \ubc1b\uc740 \uc0ac\ub78c\uacfc \uadf8 \uc544\ub798\uc5d0\uc11c \ubcf4\uc720\ud55c \uc0ac\ub78c\uc758 \uad00\uacc4\uac00 \uc911\uc694\ud588\ub2e4. \ub545\uc740 \uc9c0\ub3c4 \uc704\uc758 \uba74\uc801\ub9cc\uc774 \uc544\ub2c8\ub77c \uc5ec\ub7ec \uc0ac\ub78c \uc0ac\uc774\uc758 \uad8c\ub9ac\uc640 \uc758\ubb34\uc600\ub2e4. \uac19\uc740 \uc7a5\uc18c\ub97c \uac00\ub9ac\ucf1c\ub3c4 \ub204\uac00 \uc5b4\ub5a4 \uc790\uaca9\uc73c\ub85c \uc9c0\ubc30\ud558\uace0 \uc0ac\uc6a9\ud558\ub294\uc9c0\uc5d0 \ub530\ub77c \uae30\ub85d\uc758 \uc758\ubbf8\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uc815\ubcf5 \uc804\ud6c4\ub97c \ud568\uaed8 \uc801\uc740 \ubc29\uc2dd\uc740 \ud604\uc7ac \ubcf4\uc720\uc790\uc758 \uc8fc\uc7a5\uc5d0 \uacfc\uac70\uc758 \uadfc\uac70\ub97c \ubd99\uc774\uac8c \ud588\ub2e4. \ub204\uac00 \uc815\ub2f9\ud558\uac8c \ub118\uaca8\ubc1b\uc558\uace0 \ub204\uac00 \ub2e4\ud22c\ub294 \ub545\uc744 \ucc28\uc9c0\ud588\ub294\uc9c0\ub294 \uc655\uc758 \uc9c8\uc11c\uc5d0\ub3c4 \uc911\uc694\ud588\ub2e4. \ub530\ub77c\uc11c \uc774\ub984\uacfc \uc22b\uc790\ub97c \ubaa8\uc73c\ub294 \uc77c\uc740 \uc911\ub9bd\uc801\uc778 \uad00\ucc30\ub9cc\uc774 \uc544\ub2c8\ub77c \uc815\ubcf5 \uc774\ud6c4 \uc7ac\uc0b0 \uad00\uacc4\ub97c \uc815\ub9ac\ud558\ub294 \uc815\uce58\uc801 \ud589\uc704\uc600\ub2e4. \uae30\ub85d\uc5d0\ub294 \uacbd\uc791\uc9c0\uc640 \ubaa9\ucd08\uc9c0, \uc232\uacfc \ubb3c, \uc7c1\uae30 \ud300\uacfc \ubc29\uc557\uac04, \uc0ac\ub78c\ub4e4\uc758 \uc9c0\uc704\uc640 \uc7ac\uc0b0 \uac00\uce58 \ub4f1\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \uacbd\uc791\ud560 \uc218 \uc788\ub294 \ub545\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc0dd\uc0b0\uc774 \uc774\ub8e8\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc77c\ud560 \uc0ac\ub78c\uacfc \uac00\ucd95, \ub3c4\uad6c\uc640 \uc124\ube44\uac00 \ud568\uaed8 \uc788\uc5b4\uc57c \ud588\ub2e4. \uc774\ub7f0 \ud56d\ubaa9\uc744 \ub098\ub780\ud788 \uc77d\uc73c\uba74 \uc911\uc138 \ub18d\ucd0c\uc758 \uc0dd\ud65c\uc774 \ubcf4\uc774\uae30 \uc2dc\uc791\ud55c\ub2e4. \ub2e4\ub9cc \uae30\ub85d\uc758 \ub2e8\uc704\uc640 \uc6a9\uc5b4\ub97c \uc624\ub298\ub0a0\uc758 \uba74\uc801\uc774\ub098 \uc9c1\uc5c5 \uc774\ub984\uc73c\ub85c \ubc14\ub85c \ubc14\uafb8\uba74 \uace4\ub780\ud558\ub2e4. \ub2f9\uc2dc\uc758 \ud1a0\uc9c0 \ud3c9\uac00\uc640 \ubd80\ub2f4 \uccb4\uacc4\ub97c \uc774\ud574\ud574\uc57c \uc22b\uc790\uac00 \ubb34\uc5c7\uc744 \uc758\ubbf8\ud558\ub294\uc9c0 \uc54c \uc218 \uc788\ub2e4. \ubc29\uc557\uac04\uc740 \ubb3c\uacfc \uc124\ube44\ub97c \uc774\uc6a9\ud574 \uace1\ubb3c\uc744 \uac00\uacf5\ud558\ub294 \uacf3\uc774\uc5c8\ub2e4. \uadf8 \uc874\uc7ac\ub97c \uae30\ub85d\ud558\uba74 \uc218\ud655\ud55c \uace1\uc2dd\uc774 \uba39\uc744\uac70\ub9ac\uac00 \ub418\uae30\uae4c\uc9c0 \ud544\uc694\ud55c \uc2dc\uc124\uacfc \uc218\uc785\uc758 \uacbd\ub85c\ub3c4 \ubcf4\uc778\ub2e4. \ub18d\ucd0c\uc744 \ubc2d\uc5d0\uc11c \uc77c\ud558\ub294 \uc0ac\ub78c\uc758 \ubaa8\uc2b5 \ud558\ub098\ub85c\ub9cc \uc0c1\uc0c1\ud558\uae30\ubcf4\ub2e4, \uac00\uacf5\uacfc \uc774\uc6a9 \uad8c\ud55c\uae4c\uc9c0 \ud3ec\ud568\ub41c \uacbd\uc81c\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \uc870\uc0ac\uc5d0\ub294 \uc9c0\uc5ed\uc758 \uc0ac\uc815\uc744 \uc544\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc99d\uc5b8\ud558\ub294 \uc808\ucc28\uac00 \uc4f0\uc600\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc0ac\ub78c\uacfc \uacf5\ub3d9\uccb4\uac00 \uc9c4\uc220\ud55c \ub0b4\uc6a9\uc744 \ud1b5\ud574 \ubcf4\uc720\uc640 \uad8c\ub9ac\uc758 \uc0c1\ud0dc\ub97c \ud655\uc778\ud558\ub824 \ud588\ub2e4. \uc655\uc774 \ubaa8\ub4e0 \uc815\ubcf4\ub97c \ub3c5\uc790\uc801\uc73c\ub85c \ub9cc\ub4e4\uc5b4 \ub0b4\ub824 \uc900 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ud558\uc9c0\ub9cc \ucd5c\uc885 \uae30\ub85d\uc740 \uc99d\uc5b8\ud55c \uc0ac\ub78c\ub4e4\uc758 \uc77c\uc0c1 \uc5b8\uc5b4\ub97c \uadf8\ub300\ub85c \ub179\uc74c\ud55c \uac83\uc774 \uc544\ub2c8\ub2e4. \uc9c8\ubb38\uc758 \ud2c0\uacfc \ud3b8\uc9d1, \ub77c\ud2f4\uc5b4\uc758 \ud589\uc815 \uae30\ub85d\uc744 \uac70\uce58\uba70 \uc815\ub9ac\ub418\uc5c8\ub2e4. \uc9c0\uc5ed \uc0ac\ub78c\uc758 \ubaa9\uc18c\ub9ac\uac00 \ub4e4\uc5b4 \uc788\uc73c\uba74\uc11c\ub3c4 \uc655\uc758 \uad00\uc2ec\uacfc \uc11c\uae30\uad00\uc758 \uc120\ud0dd\uc744 \ud1b5\uacfc\ud55c \uc790\ub8cc\ub77c\ub294 \ub450 \uc131\uaca9\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc5b4\ub5a4 \ud1a0\uc9c0\uc5d0 \uad00\ud574 \ub450 \uc8fc\uc7a5\uc774 \ucda9\ub3cc\ud588\ub2e4\uba74 \uc870\uc0ac\uad00\uc740 \uadf8 \uc9c0\uc5ed\uc758 \uae30\uc5b5\uacfc \uae30\uc874 \uad8c\ub9ac\ub97c \ub530\uc838\uc57c \ud588\ub2e4. \uc624\ub298\ub0a0 \ub0a8\uc740 \uc9e7\uc740 \ubb38\uc7a5\uc740 \uadf8\ub7f0 \ub17c\uc7c1\uc744 \uc555\ucd95\ud55c \uacb0\uacfc\uc77c \uc218 \uc788\ub2e4. \uae30\ub85d\uc774 \uac04\uacb0\ud558\ub2e4\ub294 \uc774\uc720\ub85c \uc2e4\uc81c \uc0ac\ud68c\uc758 \uad00\uacc4\uae4c\uc9c0 \ub2e8\uc21c\ud588\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ub460\uc988\ub370\uc774 \uae30\ub85d\uc740 \ud1b5\uc0c1 \ud070 \ub460\uc988\ub370\uc774\uc640 \uc791\uc740 \ub460\uc988\ub370\uc774\ub85c \uad6c\ubd84\ud558\ub294 \ub450 \uad8c\uc5d0 \ub0a8\uc544 \uc788\ub2e4. \uc791\uc740 \ub460\uc988\ub370\uc774\ub294 \uc5d0\uc2dd\uc2a4\u00b7\ub178\ud37d\u00b7\uc11c\ud37d \uc138 \uc9c0\uc5ed\uc744 \ub2e4\ub8e8\uba70, \ud070 \ucc45\uacfc \ubd84\ub7c9\uc744 \uc815\ub9ac\ud558\ub294 \ubc29\uc2dd\uc5d0\ub3c4 \ucc28\uc774\uac00 \uc788\ub2e4. \uc791\uc740 \ucc45\uc774\ub77c\uace0 \ub0b4\uc6a9\uc774 \ub35c \uc0c1\uc138\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc870\uc0ac \uacfc\uc815\uacfc \uad00\ub828\ub41c \ub2e4\ub978 \uae30\ub85d\ub3c4 \ub0a8\uc544 \uc788\uc5b4 \uc11c\ub85c \ub300\uc870\ud560 \uc218 \uc788\ub2e4. \uba54\uc774\ud2c0\ub79c\ub4dc\uac00 \uc774 \uc790\ub8cc\ub4e4\uc744 \ud568\uaed8 \uc77d\uc740 \uc774\uc720\ub3c4 \uc5ec\uae30\uc5d0 \uc788\ub2e4. \ud55c \uad8c\uc758 \uc720\uba85\ud55c \ucc45\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc9c8\ubb38\uc5d0 \ub2f5\ud558\uae30\ubcf4\ub2e4, \ubb34\uc5c7\uc774 \uc0dd\ub7b5\ub418\uac70\ub098 \ub2e4\ub974\uac8c \uc815\ub9ac\ub418\uc5c8\ub294\uc9c0 \ube44\uad50\ud574\uc57c \ud55c\ub2e4. \ub460\uc988\ub370\uc774\ub77c\ub294 \uc774\ub984\uc740 \ucd5c\ud6c4\uc758 \uc2ec\ud310\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uae30\ub85d\uc758 \ud310\ub2e8\uc744 \uc27d\uac8c \ub2e4\ud234 \uc218 \uc5c6\ub2e4\ub294 \uad8c\uc704\uc640 \uc5f0\uacb0\ub418\uc5b4 \uc124\uba85\ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc870\uc0ac\ub97c \uc2dc\uc791\ud560 \ub54c\ubd80\ud130 \uc655\uc774 \uc624\ub298\uc758 \uc815\uc2dd \ucc45 \uc81c\ubaa9\uc744 \uadf8\ub300\ub85c \ub0b4\uac78\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774 \uad8c\uc704\ub294 \uae30\ub85d\uc774 \uc7ac\uc0b0\uacfc \uc758\ubb34\ub97c \ud310\ub2e8\ud558\ub294 \uadfc\uac70\ub85c \uc4f0\uc600\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub3d9\uc2dc\uc5d0 \uac15\ub825\ud55c \ubb38\uc11c\ub77c\uace0 \uc624\ub958\ub098 \ubaa8\ud638\ud568\uc774 \uc804\ud600 \uc5c6\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc61b \ud559\uc790\uc758 \ud574\uc11d\uacfc \ubb38\uc11c\uc5d0 \uc2e4\uc81c \uc801\ud78c \ub0b4\uc6a9\uc744 \uad6c\ubd84\ud558\ub294 \uc77c\uc740 \uc5ec\uc804\ud788 \uc911\uc694\ud558\ub2e4. \ubb38\uc11c\uc758 \uad8c\uc704\ub294 \uae30\ub85d\uc744 \ubcf4\uad00\ud558\uace0 \ub2e4\uc2dc \ucc3e\uc544\ubcfc \uc218 \uc788\ub294 \uc870\uc9c1\uc5d0\ub3c4 \uae30\ub300\uc5c8\ub2e4. \ud55c \ubc88 \ubaa8\uc740 \uc815\ubcf4\uac00 \ub4a4\uc758 \ud310\ub2e8\uc5d0 \uc4f0\uc774\ub824\uba74 \uc704\uce58\uc640 \uc774\ub984, \ubcf4\uc720 \uad00\uacc4\ub97c \ub2e4\uc2dc \ud655\uc778\ud560 \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4. \ub460\uc988\ub370\uc774 \ubd81\uc740 \uc790\ub8cc\ub97c \uc218\uc9d1\ud55c \uc0ac\uac74\uc778 \ub3d9\uc2dc\uc5d0 \uadf8\uac83\uc744 \uc624\ub798 \uc720\uc9c0\ud558\ub294 \uad6d\uac00\uc758 \ub2a5\ub825\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub460\uc988\ub370\uc774 \ubd81\uc740 \uc789\uae00\ub79c\ub4dc\uc758 \ubaa8\ub4e0 \uc8fc\ubbfc\uc744 \ube60\uc9d0\uc5c6\uc774 \uc774\ub984\ubcc4\ub85c \ub4f1\ub85d\ud55c \ud604\ub300\uc2dd \uc778\uad6c\uc870\uc0ac\uac00 \uc544\ub2c8\ub2e4. \uae30\ub85d\uc774 \ube60\uc9c4 \uc9c0\uc5ed\uacfc \uc0ac\ub78c, \uc655\uc758 \uc870\uc0ac \ubaa9\uc801\uc5d0 \ub9de\uc9c0 \uc54a\uc544 \uc790\uc138\ud788 \uc801\ud788\uc9c0 \uc54a\uc740 \uc0dd\ud65c\uc774 \uc788\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc774\uc720\ub85c \uc874\uc7ac\ud558\uc9c0 \uc54a\uc558\ub2e4\uace0 \ud310\ub2e8\ud560 \uc218 \uc5c6\ub2e4. \uc774 \uae00\uc758 \uc0bd\ud654\ub294 \uc870\uc0ac\uad00\uacfc \uc9c0\uc5ed \uc0ac\ub78c\ub4e4\uc774 \ub9cc\ub098\ub294 \uc7a5\uba74\uc744 \uc0c1\uc0c1\ud55c \uadf8\ub9bc\uc774\ub2e4. \uc2e4\uc81c \ubb38\uc11c\uc758 \ud544\uccb4\ub098 \ud2b9\uc815 \ud68c\uc758\uc758 \ubcf5\uc6d0\uc774 \uc544\ub2c8\ub2e4. \uc7a5\ubd80\ub97c \ud3bc\uce5c\ub2e4\ub294 \uac83\uc740 \uc22b\uc790\ub97c \ucc3e\ub294 \uc77c\uc778 \ub3d9\uc2dc\uc5d0, \uad6d\uac00\uac00 \ubb34\uc5c7\uc744 \uc54c\uace0 \uc2f6\uc5b4 \ud588\uace0 \ubb34\uc5c7\uc744 \uae30\ub85d \ubc16\uc5d0 \ub0a8\uacbc\ub294\uc9c0 \ubb3b\ub294 \uc77c\uc774\uae30\ub3c4 \ud558\ub2e4."}, {"id": "dujiangyan-irrigation-and-maintenance", "title": "\ub450\uc7a5\uc60c \u2014 \uc624\ub798\ub41c \ubb3c\uae38\uc740 \ub204\uac00 \uacc4\uc18d \uc5f4\uc5b4 \ub450\uc5c8\uc744\uae4c", "summary": "\uc774\ube59\uc758 \uc804\uc2b9\uacfc \uccad\ub450 \ud3c9\uc6d0\uc758 \uad00\uac1c \uae30\ub85d\uc744 \ud1b5\ud574 \uc624\ub798\ub41c \uc2dc\uc124\uc744 \uc720\uc9c0\ud55c \uc0ac\ub78c\ub4e4\uc758 \uc77c\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/dujiangyan-irrigation-and-maintenance/index.html", "image": "../media/dujiangyan-irrigation-and-maintenance.png", "alt": "\uac15\uacfc \uc218\ub85c, \ub18d\uacbd\uc9c0\ub97c \uc5f0\uacb0\ud55c \uc4f0\ucd28 \uad00\uac1c \ud48d\uacbd\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ub450\uc7a5\uc60c \u2014 \uc624\ub798\ub41c \ubb3c\uae38\uc740 \ub204\uac00 \uacc4\uc18d \uc5f4\uc5b4 \ub450\uc5c8\uc744\uae4c \uccad\ub450 \ud3c9\uc6d0\uc758 \ubb3c\uae38\uacfc \uad00\uac1c \uc804\uc2b9, \uae34 \uad00\ub9ac\uc758 \uc2dc\uac04\uc744 \uc0b4\ud53c\uae30 \uc774\ube59\uc758 \uc804\uc2b9\uacfc \uccad\ub450 \ud3c9\uc6d0\uc758 \uad00\uac1c \uae30\ub85d\uc744 \ud1b5\ud574 \uc624\ub798\ub41c \uc2dc\uc124\uc744 \uc720\uc9c0\ud55c \uc0ac\ub78c\ub4e4\uc758 \uc77c\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uccad\ub450 \ud3c9\uc6d0\uc758 \ud48d\uc694\ub97c \uc124\uba85\ud560 \ub54c \ubb3c\uacfc \ube44\uc625\ud55c \ub545\uc774 \uc790\uc8fc \ub4f1\uc7a5\ud55c\ub2e4. \uadf8\ub7ec\ub098 \ubb3c\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ud544\uc694\ud55c \uacf3\uc5d0 \ud544\uc694\ud55c \ub9cc\ud07c \ub3c4\ucc29\ud55c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub974\ub2e4. \ub450\uc7a5\uc60c\uc73c\ub85c \uc54c\ub824\uc9c4 \uad00\uac1c \uc0ac\uc5c5\uc744 \uc0dd\uac01\ud558\uba74 \uc790\uc5f0\uc758 \uc870\uac74\uacfc \uc0ac\ub78c\uc758 \uae30\uc220, \uc624\ub7ab\ub3d9\uc548 \uc774\uc5b4\uc9c4 \uad00\ub9ac\uac00 \ud568\uaed8 \ubcf4\uc778\ub2e4. \uc624\ub798\ub41c \uc2dc\uc124\uc740 \ucc98\uc74c \ub9cc\ub4e0 \uc21c\uac04\ub9cc\uc73c\ub85c \uc0b4\uc544\ub0a8\uc9c0 \uc54a\ub294\ub2e4. \ubb3c\uc744 \uac00\uae4c\uc774 \ub450\uace0\ub3c4 \uc4f0\uae30 \uc5b4\ub824\uc6b4 \uacf3\uc774 \uc788\ub2e4. \ud750\ub974\ub294 \ub192\uc774\uc640 \uc18d\ub3c4, \ud759\uc774 \uc313\uc774\ub294 \uc704\uce58\uac00 \ub2e4\ub974\uba74 \ubc2d\uc5d0 \ub3c4\ucc29\ud558\ub294 \ubb3c\uc758 \uc591\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uad00\uac1c\ub294 \ub2e8\uc21c\ud788 \uac15\uc744 \uc18c\uc720\ud558\ub294 \uc77c\uc774 \uc544\ub2c8\ub77c \ubb3c\uc774 \uc9c0\ub098\uac08 \uae38\uc744 \ub9cc\ub4e4\uace0 \uc720\uc9c0\ud558\ub294 \uc77c\uc774\ub2e4. \uc0b0\uc5d0\uc11c \ub0b4\ub824\uc628 \ubb3c\uacfc \ub113\uc740 \ud3c9\uc6d0\uc758 \uad00\uacc4\ub97c \uc0dd\uac01\ud574 \ubcf4\uc790. \ud55c \uc9c0\uc810\uc758 \uad6c\uc870\uac00 \uc544\ub798\ucabd \uc5ec\ub7ec \uacf3\uc758 \uc0dd\ud65c\uc5d0 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\ub2e4. \uae30\uc220\uc758 \ud6a8\uacfc\ub294 \ub208\uc55e\uc758 \uc2dc\uc124\uc744 \ub118\uc5b4 \uc218\ub85c\uc640 \ubc2d\uc744 \ub530\ub77c \ud37c\uc9c4\ub2e4. \ubb3c\uae38\uc744 \uc124\uba85\ud558\ub824\uba74 \uac74\ucd95\ubb3c \ud55c \ucc44\ubcf4\ub2e4 \ub113\uc740 \uc9c0\ub3c4\ub97c \uba38\ub9bf\uc18d\uc5d0 \uadf8\ub824\uc57c \ud55c\ub2e4. \ub450\uc7a5\uc60c\uc758 \uc804\ud1b5\uc740 \uc9c4 \uc2dc\ub300\uc758 \uad00\ub9ac \uc774\ube59\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc624\ub798\ub41c \uae30\ub85d\uacfc \uc9c0\uc5ed\uc758 \uae30\uc5b5\uc740 \uc544\ub4e4\uc758 \uc5ed\ud560\ub3c4 \ud568\uaed8 \uc804\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc804\uc2b9\uc5d0 \ub4f1\uc7a5\ud558\ub294 \uc778\ubb3c\uacfc \uc138\ubd80\ub97c \uc624\ub298\uc758 \uacf5\uc0ac \ubcf4\uace0\uc11c\ucc98\ub7fc \uc815\ud655\ud788 \ud655\uc778\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5ed\uc0ac\uc801 \uc0ac\uc5c5\uacfc \uadf8 \uc0ac\uc5c5\uc744 \uae30\ub150\ud55c \uc774\uc57c\uae30\ub97c \ud568\uaed8 \uc77d\ub418 \uad6c\ubd84\ud560 \ud544\uc694\uac00 \uc788\ub2e4. 1913\ub144\uc5d0 \ucd9c\ud310\ub41c \uc5d8\ub9ac\uc790\ubca0\uc2a4 \ucf04\ub4e4\uc758 \uc911\uad6d \uc5ec\ud589\uae30\uc5d0\ub3c4 \uc774\ube59\uacfc \uc544\ub4e4\uc5d0 \ub300\ud55c \uc124\uba85\uc774 \ub098\uc628\ub2e4. \uc5ec\ud589\uc790\ub294 \uccad\ub450 \ud3c9\uc6d0\uc758 \ud48d\uc694\ub97c \uc774\ub4e4\uc774 \ub9cc\ub4e0 \uc218\ub9ac \uccb4\uacc4\uc640 \uc5f0\uacb0\ud55c\ub2e4. \uc774 \uae30\ub85d\uc740 \uace0\ub300 \uacf5\uc0ac\uc758 \uc9c1\uc811 \ubaa9\uaca9\ub2f4\uc774 \uc544\ub2c8\ub77c \ud6c4\ub300\uc5d0 \uadf8 \uc131\uacfc\ub97c \uc774\ud574\ud558\uace0 \uae30\uc5b5\ud55c \ubc29\uc2dd\uc758 \uc99d\uc5b8\uc774\ub2e4. \ud070 \ubb3c\uc744 \ub2e4\ub8ec\ub2e4\uace0 \ubc18\ub4dc\uc2dc \ub192\uc740 \ubcbd\uc73c\ub85c \uc804\ubd80 \ub9c9\uc544\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub450\uc7a5\uc60c\uc744 \uc774\ud574\ud560 \ub54c\uc5d0\ub294 \ud750\ub984\uc744 \ub098\ub204\uace0 \ubb3c\uae38\ub85c \uc774\ub044\ub294 \uad00\uc810\uc774 \uc911\uc694\ud558\ub2e4. \ubb3c\uc774 \uc9c0\ub098\uac00\ub294 \uc0c1\ud0dc\ub97c \uc774\uc6a9\ud558\ub294 \uae30\uc220\uacfc \uc800\uc7a5\ud558\ub294 \uae30\uc220\uc740 \uac19\uc740 \uc9c8\ubb38\uc5d0 \uc11c\ub85c \ub2e4\ub978 \ub2f5\uc744 \uc904 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc0c1\uc0c1 \uadf8\ub9bc \ud55c \uc7a5\uc73c\ub85c \uc2e4\uc81c \uc2dc\uc124\uc758 \ubaa8\ub4e0 \uc791\ub3d9\uc744 \uc774\ud574\ud588\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0\ub294 \ub9d0\uc790. \uacc4\uc808\uacfc \uc218\ub7c9, \uc5ec\ub7ec \uad6c\uc870\uc758 \uad00\uacc4\uac00 \ud568\uaed8 \uc791\uc6a9\ud55c\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc815\ud655\ud55c \uc124\uacc4\ub3c4\ubcf4\ub2e4 \ubb3c\uc744 \ud544\uc694\ud55c \uacf3\uc73c\ub85c \uc774\ub048\ub2e4\ub294 \uae30\ubcf8\uc801\uc778 \ubc1c\uc0c1\uacfc \uadf8 \uc774\ud6c4\uc758 \uad00\ub9ac\uc5d0 \ucd08\uc810\uc744 \ub454\ub2e4. \ucf04\ub4e4\uc758 \uae30\ub85d\uc5d0\ub294 \uc218\ub85c\ub97c \uae4a\uac8c \ud558\uace0 \ub451\uc744 \ub0ae\uac8c \ud558\ub77c\ub294 \ub73b\uc758 \ub9d0\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \uc624\ub298\uc758 \ubaa8\ub4e0 \uc0c1\ud669\uc5d0 \uadf8\ub300\ub85c \uc801\uc6a9\ud560 \uae30\uc220 \uc9c0\uce68\uc73c\ub85c \ubc1b\uc544\ub4e4\uc77c \uc218\ub294 \uc5c6\ub2e4. \uadf8\ub7ec\ub098 \uc624\ub798\ub41c \uc2dc\uc124\uc774 \uacc4\uc18d \uad00\ub9ac\ub418\uc5b4\uc57c \ud55c\ub2e4\ub294 \uc810\uc744 \uc555\ucd95\ud574\uc11c \ubcf4\uc5ec \uc900\ub2e4. \ubb3c\uc774 \ud750\ub974\uba74 \ud759\ub3c4 \uc774\ub3d9\ud55c\ub2e4. \uc218\ub85c\uc758 \uc0c1\ud0dc\ub294 \ucc98\uc74c \uacf5\uc0ac\ud55c \ubaa8\uc2b5\uc5d0 \uc601\uc6d0\ud788 \uba38\ubb3c\uc9c0 \uc54a\ub294\ub2e4. \uae38\uc744 \uc5f4\uc5c8\ub2e4\uace0 \uc774\ud6c4\uc758 \uc77c\uc774 \ub05d\ub098\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ubb3c\uc758 \uc6c0\uc9c1\uc784\uc5d0 \ub300\uc751\ud574 \ub2e4\uc2dc \uc190\ubcf4\ub294 \ub178\ub3d9\uc774 \ubc18\ubcf5\ub418\uc5b4\uc57c \ud3c9\uc6d0\uc758 \uc0dd\ud65c\uacfc \uc2dc\uc124\uc758 \uad00\uacc4\uac00 \uc774\uc5b4\uc9c8 \uc218 \uc788\ub2e4. \uc774\ube59\uc758 \uc774\ub984\uc740 \uae30\uc5b5\ud558\uae30 \uc27d\uc9c0\ub9cc \ud070 \uad00\uac1c \uccb4\uacc4\ub97c \ud55c \uc0ac\ub78c\uc758 \uc190\ub9cc\uc73c\ub85c \ub9cc\ub4e4\uace0 \uc720\uc9c0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ucc98\uc74c\uc758 \uacf5\uc0ac\uc5d0 \ucc38\uc5ec\ud55c \uc0ac\ub78c\uacfc \ud6c4\ub300\uc5d0 \uc218\ub85c\ub97c \uc190\ubcf8 \uc0ac\ub78c, \ub9e4\uc77c \ubb3c\uc744 \uc4f0\uba70 \ubcc0\ud654\ub97c \uc54c\uc544\ucc28\ub9b0 \uc0ac\ub78c\uc774 \ud544\uc694\ud558\ub2e4. \uc774\ub984\uc774 \ub0a8\uc740 \uc124\uacc4\uc790\uc640 \uc774\ub984\uc774 \ub0a8\uc9c0 \uc54a\uc740 \uad00\ub9ac\uc790\uc758 \uc2dc\uac04\uc774 \uacb9\uce5c\ub2e4. \uae30\ub150\ubb3c\uc774 \ud55c \uc778\ubb3c\uc744 \ub192\uc774\ub294 \ub3d9\uc548 \uc2e4\uc81c \ud6a8\uacfc\ub294 \ub113\uc740 \uc9c0\uc5ed\uc758 \ubc18\ubcf5\ub418\ub294 \uc791\uc5c5\uc5d0\uc11c \ub098\uc62c \uc218 \uc788\ub2e4. \uae30\uc220\uc0ac\ub97c \ubc1c\uba85\ud55c \ucc9c\uc7ac\uc758 \uc774\uc57c\uae30\ub85c\ub9cc \uc4f0\uba74 \uc720\uc9c0\uc758 \uc5ed\uc0ac\ub294 \uc0ac\ub77c\uc9c4\ub2e4. \ub450\uc7a5\uc60c\uc740 \uc0c8\ub85c\uc6b4 \uac83\uc744 \ub9cc\ub4e0 \uc0ac\ub78c\ub9cc\ud07c \uacc4\uc18d \uc4f8 \uc218 \uc788\uac8c \ud55c \uc0ac\ub78c\ub3c4 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc218\ub85c\ub294 \ud55c \uc9c0\uc810\ub9cc \uace0\uccd0\uc11c \uc5b8\uc81c\ub098 \ub05d\ub098\ub294 \uc2dc\uc124\uc774 \uc544\ub2c8\ub2e4. \uc704\ucabd\uc5d0\uc11c \uc0dd\uae34 \ubcc0\ud654\uac00 \uc544\ub798\ucabd\uc758 \uc0ac\uc6a9\uc5d0 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \ubc2d\uc5d0\uc11c \ubb3c\uc744 \uc5bb\ub294 \uc0ac\ub78c\uc758 \uacbd\ud5d8\uacfc \uc2dc\uc124\uc744 \uc190\ubcf4\ub294 \uc0ac\ub78c\uc758 \ud310\ub2e8\uc774 \uc774\uc5b4\uc838\uc57c \ud55c\ub2e4. \uae30\uc220\uc740 \uad6c\uc870\ubb3c\uc758 \ud615\ud0dc\uc640 \uc774\uc6a9\uc790\uc758 \uad00\uacc4\ub97c \ud568\uaed8 \ud3ec\ud568\ud55c\ub2e4. \uc774\ub7f0 \uc5ed\uc0ac\ub97c \uc77d\uc73c\uba74 \uc644\uacf5\uc774\ub77c\ub294 \ub2e8\uc5b4\uc758 \uc758\ubbf8\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \ucc98\uc74c \ubb3c\uc774 \ud758\ub800\uc744 \ub54c \ud558\ub098\uc758 \uc0ac\uc5c5\uc740 \ub05d\ub0ac\uc744 \uc218 \uc788\uc9c0\ub9cc \uadf8 \uae30\ub2a5\uc744 \uc720\uc9c0\ud558\ub294 \uc77c\uc740 \uacc4\uc18d\ub41c\ub2e4. \ub208\uc5d0 \ub744\ub294 \uc900\uacf5 \uc7a5\uba74\uc774 \uc5c6\ub294 \ud574\uc5d0\ub3c4 \uc911\uc694\ud55c \ub178\ub3d9\uc774 \uc774\ub8e8\uc5b4\uc84c\ub2e4\ub294 \uc810\uc744 \uae30\uc5b5\ud558\uba74, \uae34 \uc0ac\uc6a9\uc758 \uc2dc\uac04\uc744 \ube48 \uae30\uac04\uc73c\ub85c \ub0a8\uae30\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \ucf04\ub4e4\uc740 \uccad\ub450 \ud3c9\uc6d0\uc758 \uacbd\uc791\uacfc \ubb3c\uc758 \uacf5\uae09\uc744 \ub192\uc774 \ud3c9\uac00\ud588\ub2e4. \ud558\uc9c0\ub9cc \ud55c \uc5ec\ud589\uc790\uac00 \ubcf8 \uacc4\uc808\uacfc \uae38\uc774 \uc9c0\uc5ed \uc804\uccb4\uc758 \ubaa8\ub4e0 \uacbd\ud5d8\uc744 \ub300\ud45c\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ucc45\uc5d0 \ub098\ud0c0\ub098\ub294 \ub099\uc6d0 \uac19\uc740 \ud45c\ud604\uc740 \uac10\ud0c4\uc758 \uc5b8\uc5b4\uc774\uc9c0 \ub204\uad6c\ub3c4 \uc5b4\ub824\uc6c0 \uc5c6\uc774 \uc0b4\uc558\ub2e4\ub294 \ud1b5\uacc4\uac00 \uc544\ub2c8\ub2e4. \uc624\ub798\ub41c \uc5ec\ud589\uae30\uc5d0\ub294 \uc8fc\ubbfc\uc744 \ub113\uac8c \uc77c\ubc18\ud654\ud558\ub294 \ud45c\ud604\ub3c4 \uc11e\uc778\ub2e4. \ud48d\uacbd\uc5d0 \ub300\ud55c \uad00\ucc30\uacfc \uc0ac\ub78c\uc758 \uc131\uaca9\uc744 \ub2e8\uc815\ud558\ub294 \ub9d0\uc740 \uad6c\ubcc4\ud574\uc11c \uc77d\uc5b4\uc57c \ud55c\ub2e4. \uadf8\ub7ec\uba74 \uc790\ub8cc\uc758 \ud3b8\uacac\uc744 \ubc18\ubcf5\ud558\uc9c0 \uc54a\uc73c\uba74\uc11c\ub3c4 \ub2f9\uc2dc\uc758 \ub18d\uc5c5\uacfc \ubb3c\uae38\uc744 \uc0b4\ud53c\ub294 \ub2e8\uc11c\ub97c \uc5bb\uc744 \uc218 \uc788\ub2e4. \uc2dc\uc124\uc774 \uc624\ub798\ub418\uc5c8\ub2e4\ub294 \ub9d0\uc740 \ubaa8\ub4e0 \uc7ac\ub8cc\uac00 \ucc98\uc74c \uadf8\ub300\ub85c \ub0a8\uc558\ub2e4\ub294 \ub73b\uc77c \uc218\ub3c4 \uc788\uace0, \uac19\uc740 \uc77c\uc744 \uc624\ub7ab\ub3d9\uc548 \uc218\ud589\ud574 \uc654\ub2e4\ub294 \ub73b\uc77c \uc218\ub3c4 \uc788\ub2e4. \ub450\uc7a5\uc60c\uc5d0\uc11c\ub294 \ub450 \ubc88\uc9f8 \uc758\ubbf8\ub97c \ud2b9\ud788 \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub2e4. \uc218\ub9ac\uc640 \uc870\uc815\uc774 \uc788\uc5c8\ub2e4\uace0 \uc804\ud1b5\uc758 \uac00\uce58\uac00 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uad00\uac1c \uc0ac\uc5c5\uc758 \uc5ed\uc0ac\uc5d0\ub294 \uc2dc\uc791\ud55c \ud574\ubfd0 \uc544\ub2c8\ub77c \ub2e4\uc74c \ud574\uc5d0\ub3c4 \uc791\ub3d9\ud558\uac8c \ub9cc\ub4e0 \uc190\uae38\uc774 \ub4e4\uc5b4\uac04\ub2e4. \ubb3c\uae38\uc744 \ubcfc \ub54c \uc5bc\ub9c8\ub098 \uc61b\uac83\uc778\uc9c0 \ubb3b\ub294 \ub370\uc11c \ud55c \uac78\uc74c \ub354 \ub098\uc544\uac00 \ub204\uac00 \uacc4\uc18d \uc5f4\uc5b4 \ub450\uc5c8\ub294\uc9c0 \ubb3c\uc5b4\ubcf4\uc790. \ud48d\uc694\ub85c\uc6b4 \ud3c9\uc6d0\uc758 \ud48d\uacbd\uc740 \uadf8 \uc9c8\ubb38 \ub4a4\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc758 \ud611\uc5c5\uc774 \ub0a8\uc740 \uacb0\uacfc\ub85c \uc77d\ud78c\ub2e4."}, {"id": "edo-daimyo-road-and-residence", "title": "\uc5d0\ub3c4 \u2014 \uc601\uc8fc\ub4e4\uc740 \uc65c \uc790\uafb8 \uae38\uc744 \ub5a0\ub0ac\uc744\uae4c", "summary": "\uc601\uc8fc\ub4e4\uc758 \uc5d0\ub3c4 \uccb4\ub958\uc640 \uc774\ub3d9\uc744 \ud1b5\ud574 \uc624\ub298\ub0a0 \ub3c4\ucfc4\ub85c \uc774\uc5b4\uc9c0\ub294 \ub3c4\uc2dc\uc758 \uc5ed\uc0ac\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/edo-daimyo-road-and-residence/index.html", "image": "../media/edo-daimyo-road-and-residence.png", "alt": "\uc9d0\uacfc \uac00\ub9c8\ub97c \uac16\ucd98 \uc601\uc8fc\uc758 \uc218\ud589 \ud589\ub82c\uc774 \uc5d0\ub3c4\ub85c \ud5a5\ud558\ub294 \uae38\uc744 \uac77\ub294 \ud574\uc11d\uc801 \uc0bd\ud654", "text": "\uc5d0\ub3c4 \u2014 \uc601\uc8fc\ub4e4\uc740 \uc65c \uc790\uafb8 \uae38\uc744 \ub5a0\ub0ac\uc744\uae4c \ub2e4\uc774\ubb18\uc758 \uc655\ub798\uc5d0\uc11c \uc77d\ub294 \ud1b5\uce58\uc640 \ub3c4\uc2dc\uc758 \uc131\uc7a5 \uc601\uc8fc\ub4e4\uc758 \uc5d0\ub3c4 \uccb4\ub958\uc640 \uc774\ub3d9\uc744 \ud1b5\ud574 \uc624\ub298\ub0a0 \ub3c4\ucfc4\ub85c \uc774\uc5b4\uc9c0\ub294 \ub3c4\uc2dc\uc758 \uc5ed\uc0ac\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uba3c \uae38\uc5d0 \ub098\uc120 \ud589\ub82c\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc9d0\uc744 \ub4e0 \uc0ac\ub78c\uacfc \uc218\ud589\uc6d0, \uc774\ub3d9\uc744 \uc900\ube44\ud558\ub294 \uc5ec\ub7ec \uc190\uc774 \ud568\uaed8 \uc6c0\uc9c1\uc778\ub2e4. \ud589\ub82c\uc758 \uc8fc\uc778\uc774 \ud798 \uc788\ub294 \uc601\uc8fc\ub77c\uace0 \ud574\uc11c \uc5b8\uc81c \uc5b4\ub514\ub85c \uac08\uc9c0 \ubaa8\ub450 \ub9c8\uc74c\ub300\ub85c \uc815\ud560 \uc218 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub3c4\ucfe0\uac00\uc640 \uc2dc\ub300 \uc77c\ubcf8\uc758 \uc601\uc8fc\ub4e4\uc5d0\uac8c \uc5d0\ub3c4\ub294 \uac70\ub4ed \ud5a5\ud574\uc57c \ud558\ub294 \ud1b5\uce58\uc758 \uc911\uc2ec\uc774\uc5c8\ub2e4. \uc5d0\ub3c4\ub294 \uc624\ub298\ub0a0 \ub3c4\ucfc4\ub85c \uc774\uc5b4\uc9c0\ub294 \ub3c4\uc2dc\ub2e4. \uac70\ub300\ud55c \ud604\ub300 \ub3c4\uc2dc\ub97c \uc774\ud574\ud558\ub294 \uae38\uc740 \ub192\uc740 \uac74\ubb3c\uc5d0\uc11c\ub9cc \uc2dc\uc791\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc9c0\ubc29\uc758 \uc601\uc8fc\uac00 \uc65c \uc774\uacf3\uc5d0 \uba38\ubb3c\ub7ec\uc57c \ud588\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uba74, \uad8c\ub825\uc774 \uc0ac\ub78c\uc744 \uc6c0\uc9c1\uc774\uace0 \uadf8 \uc6c0\uc9c1\uc784\uc774 \ub3c4\uc2dc\uc758 \uc0dd\ud65c\uacfc \ub9cc\ub098\ub294 \ud48d\uacbd\uc774 \ubcf4\uc778\ub2e4. \uc77c\ubcf8\uc758 \uc624\ub79c \ub0b4\uc804\uc744 \uc815\ub9ac\ud558\ub294 \uacfc\uc815\uc5d0\uc11c \ub3c4\ucfe0\uac00\uc640 \uc774\uc5d0\uc57c\uc2a4\uac00 \uc911\uc2ec \uad8c\ub825\uc744 \uc7a1\uc558\ub2e4. 1600\ub144 \uc138\ud0a4\uac00\ud558\ub77c \uc804\ud22c\ub294 \uadf8 \uc804\ud658\uc744 \uc0c1\uc9d5\ud558\ub294 \uc0ac\uac74\uc774\ub2e4. \uadf8\ub7ec\ub098 \ud070 \uc804\ud22c\uc758 \uc2b9\ub9ac\ub9cc\uc73c\ub85c \uc804\uad6d\uc758 \uc720\ub825\ud55c \ubb34\uc0ac \uc9d1\ub2e8\uc774 \ubaa8\ub450 \uac19\uc740 \uc0dd\uac01\uc744 \ud558\uac8c \ub418\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc0c8\ub85c\uc6b4 \ud1b5\uce58\uc790\ub294 \uc9c0\ubc29\uc758 \uc601\uc8fc\uc778 \ub2e4\uc774\ubb18\ub97c \uc5b4\ub5bb\uac8c \uad00\ub9ac\ud560\uc9c0 \uace0\ubbfc\ud574\uc57c \ud588\ub2e4. \uc601\uc8fc\ub4e4\uc740 \uac01\uc790\uc758 \uae30\ubc18\uacfc \ubcd1\ub825\uc744 \uac00\uc9c0\uace0 \uc788\uc5c8\ub2e4. \uc804\uc7c1\uc758 \uc885\ub8cc \ub4a4\uc5d0\ub294 \uadf8 \ud798\uc744 \uc5c6\uc560\uae30\ubcf4\ub2e4 \uc9c8\uc11c \uc548\uc5d0 \ubb36\uc5b4 \ub450\ub294 \ubb38\uc81c\uac00 \ub0a8\uc558\ub2e4. \uc624\ub7ab\ub3d9\uc548 \uc774\uc5b4\uc9c8 \ud3c9\ud654\ub3c4 \uc6b4\uc601\ud560 \uc7a5\uce58\uac00 \ud544\uc694\ud588\ub358 \uac83\uc774\ub2e4. \ub3c4\ucfe0\uac00\uc640 \uccb4\uc81c\uc5d0\uc11c \ub2e4\uc774\ubb18\uac00 \uc790\uae30 \uc601\uc9c0\uc640 \uc5d0\ub3c4\ub97c \uc624\uac00\uba70 \uba38\ubb34\ub294 \uc81c\ub3c4\ub294 \ud1b5\uce58\uc758 \uc911\uc694\ud55c \ubd80\ubd84\uc774 \ub418\uc5c8\ub2e4. \ubcf4\ud1b5 \uc0b0\ud0a8\ucf54\ud0c0\uc774, \ud55c\uad6d\uc5b4\ub85c\ub294 \ucc38\uadfc\uad50\ub300\ub77c\uace0 \ubd80\ub978\ub2e4. \ub2e8\uc21c\ud55c \uc778\uc0ac \ubc29\ubb38\ubcf4\ub2e4 \uccb4\ub958\uc640 \uc774\ub3d9\uc744 \uaddc\uce59\uc73c\ub85c \ubb36\ub294 \ubc29\uc2dd\uc5d0 \uac00\uae4c\uc6e0\ub2e4. \uc911\uc559\uc5d0 \uac00\uae4c\uc774 \uba38\ubb34\ub974\uac8c \ud558\uba74 \uc601\uc8fc\ub4e4\uc774 \uc790\uae30 \uc9c0\uc5ed\uc5d0\uc11c\ub9cc \ud798\uc744 \ud0a4\uc6b0\ub294 \uac83\uc744 \uacac\uc81c\ud560 \uc218 \uc788\ub2e4. \uad70\ub300\ub97c \uc6c0\uc9c1\uc774\uc9c0 \uc54a\uc544\ub3c4 \uc0ac\ub78c\uc758 \uc2dc\uac04\uacfc \uac70\ucc98\ub97c \uc815\ud558\ub294 \uc77c\ub85c \uad00\uacc4\ub97c \ubc14\uafc0 \uc218 \uc788\ub294 \uc148\uc774\ub2e4. \ub2e4\ub9cc \uc81c\ub3c4\uc758 \uad6c\uccb4\uc801 \uaddc\uce59\uc740 \uc815\ube44\ub418\uace0 \ub2ec\ub77c\uc84c\uc73c\ubbc0\ub85c \ubaa8\ub4e0 \uc601\uc8fc\uc640 \uc2dc\uae30\uc5d0 \ud55c \uc77c\uc815\ud45c\ub97c \uc801\uc6a9\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ud070 \ud589\ub82c\uc774 \uc6c0\uc9c1\uc774\ub824\uba74 \uba39\uc744 \uac83\uacfc \uc7a0\uc790\ub9ac, \uc9d0\uacfc \uc0ac\ub78c\uc758 \uad00\ub9ac\uac00 \ud544\uc694\ud558\ub2e4. \uba4b\uc9c4 \uc637\uacfc \uc9c8\uc11c \uc788\ub294 \uc904\ub9cc \ubcf4\uba74 \uad6c\uacbd\uac70\ub9ac \uac19\uc9c0\ub9cc, \uadf8 \ub4a4\uc5d0\uc11c\ub294 \uc900\ube44\uc640 \uc9c0\ucd9c\uc774 \uc774\uc5b4\uc84c\uc744 \uac83\uc774\ub2e4. \ud589\ub82c\uc740 \uc601\uc8fc\uc758 \uc704\uc138\ub97c \ubcf4\uc774\ub294 \uc790\ub9ac\uc774\uba74\uc11c \ubd80\ub2f4\uc744 \uac10\ub2f9\ud574\uc57c \ud558\ub294 \uc77c\uc774\uae30\ub3c4 \ud588\ub2e4. \uc774\uac83\uc744 \ud604\ub300\uc758 \uc790\uc720\ub85c\uc6b4 \uc5ec\ud589\uacfc \uac19\uc740 \uacbd\ud5d8\uc73c\ub85c \uc0dd\uac01\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \ub5a0\ub098\ub294 \uc774\uc720\uc640 \uc77c\uc815\uc758 \uc870\uac74\ubd80\ud130 \ub2e4\ub974\uae30 \ub54c\ubb38\uc774\ub2e4. \uad8c\ub825\uc790\uc758 \uc774\ub3d9\uc774\ub77c\uace0 \uc5b8\uc81c\ub098 \uc790\uc720\uc758 \ud45c\ud604\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc774 \ud765\ubbf8\ub86d\ub2e4. \uae38\uc744 \ub5a0\ub098\ub294 \ud589\uc704 \uc790\uccb4\uac00 \ub204\uac00 \ub354 \ub192\uc740 \uc704\uce58\uc5d0 \uc788\ub294\uc9c0 \ubcf4\uc5ec \uc904 \uc218 \uc788\uc5c8\ub2e4. \uc601\uc8fc\uc640 \uadf8 \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc774\ub294 \ub3c4\uc2dc\ub294 \uac70\ucc98\ub9cc\uc73c\ub85c \uc720\uc9c0\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc74c\uc2dd\uacfc \uc0dd\ud65c\uc6a9\ud488, \uc11c\ube44\uc2a4\uc640 \uc5ec\ub7ec \uc77c\uc774 \ud544\uc694\ud558\ub2e4. \ud1b5\uce58\uc758 \uc911\uc2ec\uc740 \uc18c\ube44\uc640 \ub178\ub3d9\uc774 \ub9cc\ub098\ub294 \uc7a5\uc18c\uac00 \ub418\uae30\ub3c4 \ud55c\ub2e4. \uc5d0\ub3c4\uc758 \uc5ed\uc0ac\ub97c \uc131\uacfc \uad70\uc0ac\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uba74 \uadf8 \uc548\uc5d0\uc11c \uc0b4\uc544\uac00\ub294 \uc0ac\ub78c\ub4e4\uc744 \ub193\uce58\uac8c \ub41c\ub2e4. \ubb3c\ub860 \ub3c4\uc2dc\uc758 \uc131\uc7a5\uc744 \uc774 \uc81c\ub3c4 \ud558\ub098\uac00 \uc804\ubd80 \ub9cc\ub4e4\uc5c8\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uacbd\uc81c\uc640 \uad50\ud1b5, \uc778\uad6c\uc640 \uc5ec\ub7ec \uc815\ucc45\uc774 \ud568\uaed8 \uc791\uc6a9\ud55c\ub2e4. \ucc38\uadfc\uad50\ub300\ub294 \uadf8 \ubcf5\uc7a1\ud55c \ubcc0\ud654 \uc18d\uc5d0\uc11c \uad8c\ub825\uc774 \uc0ac\ub78c\uc744 \ubc18\ubcf5\ud574\uc11c \ubaa8\uc774\uac8c \ud55c \uc911\uc694\ud55c \uc2e4\ub9c8\ub9ac\ub85c \uc77d\ub294 \ud3b8\uc774 \uc801\uc808\ud558\ub2e4. OpenStax\ub294 \ub3c4\ucfe0\uac00\uc640 \uc2dc\ub300\uc758 \ubb38\ud654\uc640 \uc0c1\uc5c5\uc744 \uc124\uba85\ud558\uba70 \uad50\uc721\uacfc \ucd9c\ud310, \ub3c4\uc2dc\uc758 \uc5ec\uac00\ub97c \ud568\uaed8 \uc18c\uac1c\ud55c\ub2e4. \uc5d0\ub3c4\uc5d0\ub294 \uc18c\uc124\uacfc \uc5ec\ub7ec \ucc45\uc744 \uc0ac\uac70\ub098 \ube4c\ub9b4 \uc218 \uc788\ub294 \uac00\uac8c\ub4e4\uc774 \uc788\uc5c8\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \uc2dd\ub2f9\uacfc \uadf9\uc7a5\uc744 \ucc3e\uc558\uace0, \ud615\ud3b8\uc774 \ud5c8\ub77d\ud558\uba74 \uc0ac\ucc30\uacfc \uc2e0\uc0ac\ub85c \uc5ec\ud589\ud558\uae30\ub3c4 \ud588\ub2e4. \uac80\uc744 \ucc2c \ubb34\uc0ac\ub9cc \uac00\ub4dd\ud55c \uc2dc\ub300\ub97c \ub5a0\uc62c\ub838\ub2e4\uba74 \uc870\uae08 \ub73b\ubc16\uc758 \ud48d\uacbd\uc774\ub2e4. \ud1b5\uc81c\uac00 \uac15\ud55c \uc0ac\ud68c\uc5d0\uc11c\ub3c4 \uc0ac\ub78c\ub4e4\uc740 \uc77d\uace0 \uba39\uace0 \uad6c\uacbd\ud588\ub2e4. \uc815\uce58\uc758 \uc9c8\uc11c\uc640 \ub3c4\uc2dc\uc758 \uc990\uac70\uc6c0\uc774 \uc11c\ub85c \ub2e4\ub978 \uc138\uc0c1\ucc98\ub7fc \ub5a8\uc5b4\uc838 \uc788\uc9c0\ub294 \uc54a\uc558\ub2e4\ub294 \uc810\uc774 \uc5d0\ub3c4\ub97c \uc77d\ub294 \uc7ac\ubbf8\ub2e4. \uc774\uc5d0\uc57c\uc2a4\uac00 \uc601\ud1a0\ub97c \ubc30\ubd84\ud560 \ub54c\uc5d0\ub3c4 \uc815\uce58\uc801 \uad00\uacc4\ub294 \uc911\uc694\ud588\ub2e4. \uad50\uc7ac\ub294 \uc77c\ucc0d\ubd80\ud130 \ud611\ub825\ud588\ub358 \uc601\uc8fc\ub4e4\uacfc \ub4a4\ub2a6\uac8c \ubcf5\uc885\ud588\uac70\ub098 \ub9de\uc11c \uc2f8\uc6e0\ub358 \uc601\uc8fc\ub4e4\uc774 \uc11c\ub85c \ub2e4\ub978 \uc870\uac74\uc758 \ub545\uc744 \ubc1b\uc558\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub204\uac00 \uc911\uc2ec\uc5d0 \uac00\uae4c\uc6b4\uc9c0, \ub204\uac00 \ub354 \uba3c \uc790\ub9ac\uc5d0 \uc788\ub294\uc9c0\ub294 \ub2e8\uc21c\ud55c \uc9c0\ub3c4\uc758 \ubb38\uc81c\uac00 \uc544\ub2c8\uc5c8\ub2e4. \uc2e0\ub8b0\uc640 \uacac\uc81c\uac00 \uacf5\uac04\uc758 \ubc30\uce58\ub85c \ub4dc\ub7ec\ub09c \uac83\uc774\ub2e4. \ub610 \uc601\uc8fc\ub4e4\uc774 \ub9c8\uc74c\ub300\ub85c \ub3d9\ub9f9\uc744 \ub9cc\ub4e4\uac70\ub098 \ud63c\uc778\uc744 \ud1b5\ud574 \uc138\ub825\uc744 \uacb0\ud569\ud558\uc9c0 \ubabb\ud558\ub3c4\ub85d \uc81c\uc57d\ud588\ub2e4. \uc0ac\ub78c\uc744 \uc5b4\ub514\uc5d0 \uba38\ubb34\ub974\uac8c \ud558\ub294\uc9c0\uc640 \ub204\uad6c\uc640 \uad00\uacc4\ub97c \ub9fa\uac8c \ud558\ub294\uc9c0\uac00 \ud568\uaed8 \uad00\ub9ac\ub418\uc5c8\ub2e4. \ud589\ub82c\uc758 \uae38\uc744 \ub530\ub77c\uac00\ub2e4 \ubcf4\uba74 \uad50\ud1b5\uc758 \uc5ed\uc0ac \ub4a4\uc5d0 \uc815\uce58\uc758 \uc124\uacc4\uac00 \ubcf4\uc778\ub2e4. \uc5d0\ub3c4\ub85c \ud5a5\ud558\ub294 \ubc18\ubcf5\ub41c \uc5ec\ud589\ub3c4 \uc774\ub7f0 \uad00\uacc4\uc758 \uadf8\ubb3c \uc548\uc5d0 \ub193\uc5ec \uc788\uc5c8\ub2e4. \uc5d0\ub3c4\ub97c \uadf8\ub300\ub85c \ud604\ub300 \ub3c4\ucfc4\uc640 \uacb9\uccd0 \ub193\uc744 \uc218\ub294 \uc5c6\ub2e4. \ub3c4\uc2dc\ub294 \ubc14\ub00c\uc5c8\uace0 \uc81c\ub3c4\ub3c4 \uc0ac\ub77c\uc84c\ub2e4. \uadf8\ub798\ub3c4 \uc0ac\ub78c\uc774 \uc5b4\ub514\ub85c \ubaa8\uc774\uace0 \uc65c \uc624\uac00\ub294\uc9c0 \ubb3b\ub294 \uc9c8\ubb38\uc740 \uc9c0\uae08\uc758 \ub3c4\uc2dc\ub97c \ubcfc \ub54c\ub3c4 \uc720\ud6a8\ud558\ub2e4. \ud070 \ub3c4\uc2dc\ub294 \uac74\ubb3c\uc758 \uc218\ub9cc\uc774 \uc544\ub2c8\ub77c \ubc18\ubcf5\ub418\ub294 \uc774\ub3d9\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc9c0\uae30\ub3c4 \ud55c\ub2e4. \uc774 \uae00\uc758 \ud589\ub82c \uc0bd\ud654\ub294 \ud2b9\uc815 \uc601\uc8fc\uc758 \uc2e4\uc81c \ud589\ucc28\ub97c \ubcf5\uc6d0\ud55c \uadf8\ub9bc\uc774 \uc544\ub2c8\ub2e4. \uba3c \uae38\uc758 \uc778\uc0c1\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uadf8 \uc774\ub3d9\uc758 \uc870\uac74\uc744 \uc0dd\uac01\ud558\uae30 \uc704\ud55c \uc7a5\uba74\uc774\ub2e4. \ud654\ub824\ud55c \ud589\ub82c\uc744 \ubcf4\uace0 \uac10\ud0c4\ud55c \ub2e4\uc74c \ud55c \uac00\uc9c0\ub97c \ub354 \ubb3c\uc5b4\ubcf4\uc790. \uc774 \uc0ac\ub78c\ub4e4\uc740 \uac00\uace0 \uc2f6\uc5b4\uc11c \uac00\ub294 \uac78\uae4c, \uac00\uc57c \ud574\uc11c \uac00\ub294 \uac78\uae4c. \uac19\uc740 \uae38\ub3c4 \uac77\ub294 \uc0ac\ub78c\uc758 \uc9c0\uc704\uc5d0 \ub530\ub77c \ub2e4\ub978 \uc758\ubbf8\uac00 \uc0dd\uae34\ub2e4. \uae38\uac00\uc758 \uad6c\uacbd\uafbc\uc5d0\uac8c\ub294 \ubcfc\uac70\ub9ac\uc600\uc744 \ud589\ub82c\uc774 \uadf8 \uc548\uc758 \ub204\uad70\uac00\uc5d0\uac8c\ub294 \uc758\ubb34\uc600\uc744 \uc218 \uc788\ub2e4. \ud55c \uc7a5\uba74\uc5d0 \uc11c\ub85c \ub2e4\ub978 \uc2dc\uc120\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uae30\uc5b5\ud558\uba74 \uc61b \ub3c4\uc2dc\uac00 \ub354 \uc0b4\uc544 \uc788\ub294 \uacf3\uc73c\ub85c \ubcf4\uc778\ub2e4."}, {"id": "eiffel-tower-iron-and-exhibition", "title": "\uc5d0\ud3a0\ud0d1 \u2014 \ubc15\ub78c\ud68c\uc758 \ucca0\uace8\uc740 \uc5b4\ub5bb\uac8c \ud30c\ub9ac\uc758 \uc5bc\uad74\uc774 \ub418\uc5c8\uc744\uae4c", "summary": "1889\ub144 \ub9cc\uad6d\ubc15\ub78c\ud68c\uc640 \ucca0 \uad6c\uc870\uac00 \ub9cc\ub4e0 \uc0c8\ub85c\uc6b4 \ub3c4\uc2dc \ud48d\uacbd\uc744 \uc774\uc57c\uae30\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/eiffel-tower-iron-and-exhibition/index.html", "image": "../media/eiffel-tower-iron-and-exhibition.jpg", "alt": "\uac15\uacfc \ubc30 \ub108\uba38 \uc5d0\ud3a0\ud0d1\uc744 \ubcf4\uc5ec \uc8fc\ub294 1900\ub144 \uae30\uc220\uc0ac \ucc45\uc758 \uc5ed\uc0ac \uc774\ubbf8\uc9c0", "text": "\uc5d0\ud3a0\ud0d1 \u2014 \ubc15\ub78c\ud68c\uc758 \ucca0\uace8\uc740 \uc5b4\ub5bb\uac8c \ud30c\ub9ac\uc758 \uc5bc\uad74\uc774 \ub418\uc5c8\uc744\uae4c 1889\ub144 \ub9cc\uad6d\ubc15\ub78c\ud68c\uc640 \ucca0 \uad6c\uc870\uac00 \ub9cc\ub4e0 \uc0c8\ub85c\uc6b4 \ub3c4\uc2dc \ud48d\uacbd 1889\ub144 \ub9cc\uad6d\ubc15\ub78c\ud68c\uc640 \ucca0 \uad6c\uc870\uac00 \ub9cc\ub4e0 \uc0c8\ub85c\uc6b4 \ub3c4\uc2dc \ud48d\uacbd\uc744 \uc774\uc57c\uae30\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ud30c\ub9ac\uc758 \ud48d\uacbd\uc744 \uadf8\ub9ac\ub77c\uace0 \ud558\uba74 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uc5d0\ud3a0\ud0d1\ubd80\ud130 \uadf8\ub9b0\ub2e4. \ub3cc\ub85c \uc313\uc740 \ub300\uc131\ub2f9\uc774\ub098 \uc655\uad81\uacfc \ub2ec\ub9ac \uc18d\uc774 \ud6e4\ud788 \ubcf4\uc774\ub294 \ucca0\uc758 \uad6c\uc870\ubb3c\uc778\ub370\ub3c4, \ub3c4\uc2dc \uc804\uccb4\ub97c \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \ud45c\uc9c0\uac00 \ub418\uc5c8\ub2e4. \uc775\uc219\ud568 \ub54c\ubb38\uc5d0 \uc624\ud788\ub824 \ub193\uce58\uae30 \uc26c\uc6b4 \uc9c8\ubb38\uc774 \uc788\ub2e4. \uc65c \uc774\ub7f0 \ud0d1\uc744 \uc138\uc6e0\uc744\uae4c. \uc5d0\ud3a0\ud0d1\uc758 \ucd9c\ubc1c\uc810\uc740 1889\ub144 \ud30c\ub9ac \ub9cc\uad6d\ubc15\ub78c\ud68c\uc600\ub2e4. \uc624\ub798\ub41c \ub3c4\uc2dc\uac00 \uc0c8\ub85c\uc6b4 \uc0b0\uc5c5 \uae30\uc220\uc744 \uc138\uacc4\uc5d0 \ubcf4\uc5ec \uc8fc\ub294 \ubb34\ub300\uc5d0 \uac70\ub300\ud55c \ucca0\ud0d1\uc774 \ub4f1\uc7a5\ud588\ub2e4. \uc624\ub298\uc758 \uae30\ub150\uc0ac\uc9c4\uc744 \uc7a0\uc2dc \ub0b4\ub824\ub193\uace0, \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc774 \uc544\uc9c1 \ub0af\uc124\uc5c8\ub358 \ucca0\uc758 \ub192\uc774\ub97c \uc62c\ub824\ub2e4\ubcf4\ub294 \uc7a5\uba74\uc5d0\uc11c \uc774\uc57c\uae30\ub97c \uc2dc\uc791\ud574 \ubcf4\uc790. 19\uc138\uae30 \ub9cc\uad6d\ubc15\ub78c\ud68c\ub294 \uac01\uad6d\uc758 \uc81c\ud488\uacfc \uae30\uacc4, \uc0c8\ub85c\uc6b4 \uae30\uc220\uc744 \ud55c\uc790\ub9ac\uc5d0 \ubaa8\uc558\ub2e4. \uc804\uc2dc\ud488\uc740 \uc0b0\uc5c5\uc758 \uc131\uacfc\uc600\uace0 \uac1c\ucd5c \ub3c4\uc2dc\ub3c4 \uac70\ub300\ud55c \uc804\uc2dc\uc7a5\uc758 \uc77c\ubd80\uac00 \ub418\uc5c8\ub2e4. \uad00\ub78c\uac1d\uc740 \ubb3c\uac74\uc744 \uad6c\uacbd\ud558\uba74\uc11c \uadf8 \ubb3c\uac74\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub294 \uad6d\uac00\uc640 \uc0ac\ud68c\uc758 \ub2a5\ub825\uae4c\uc9c0 \ubcf4\uac8c \ub418\uc5c8\ub2e4. \uc774\ub7f0 \ubb34\ub300\uc5d0\uc11c \ud0d1\uc758 \ub192\uc774\ub294 \ub9d0\uc5c6\uc774 \uac15\ud55c \uc778\uc0c1\uc744 \ub0a8\uae34\ub2e4. \uc124\uba85\uc11c\ub97c \ubaa8\ub450 \uc77d\uc9c0 \uc54a\uc544\ub3c4 \ub208\uc55e\uc758 \uaddc\ubaa8\uac00 \uba3c\uc800 \ub2e4\uac00\uc624\uae30 \ub54c\ubb38\uc774\ub2e4. \uc5d0\ud3a0\ud0d1\uc740 \ub2e8\uc21c\ud788 \uc804\ub9dd\uc744 \uc704\ud55c \uc2dc\uc124\ub9cc\uc774 \uc544\ub2c8\ub77c, \ucca0\ub85c \uc5b4\ub514\uae4c\uc9c0 \ub9cc\ub4e4 \uc218 \uc788\ub294\uc9c0\ub97c \ubcf4\uc5ec \uc8fc\ub294 \ud558\ub098\uc758 \uac70\ub300\ud55c \uc804\uc2dc\ubb3c\uc774\uae30\ub3c4 \ud588\ub2e4. \uc804\ud1b5\uc801\uc778 \uae30\ub150 \uac74\ucd95\uc744 \ub5a0\uc62c\ub9ac\uba74 \ub450\uaebc\uc6b4 \ub3cc\ubcbd\uacfc \uadf8 \ud45c\uba74\uc758 \uc7a5\uc2dd\uc774 \uba3c\uc800 \ubcf4\uc778\ub2e4. \uc5d0\ud3a0\ud0d1\uc5d0\uc11c\ub294 \ub2e4\ub974\ub2e4. \uc5ec\ub7ec \ucca0 \ubd80\uc7ac\ub97c \uc5ee\uc740 \uaca9\uc790 \uad6c\uc870\uac00 \ub4dc\ub7ec\ub098 \uc788\uace0 \uadf8 \uc0ac\uc774\ub85c \ud558\ub298\uc774 \ubcf4\uc778\ub2e4. \uba40\ub9ac\uc11c \ubcf4\uba74 \ud558\ub098\uc758 \uc724\uacfd\uc774\uc9c0\ub9cc \uac00\uae4c\uc774\uc5d0\uc11c\ub294 \uc218\ub9ce\uc740 \uac00\ub294 \uc120\uc774 \ud798\uc744 \ub098\ub204\ub294 \ubaa8\uc2b5\uc774\ub2e4. \uc774\uac83\uc774 \uc7a5\uc2dd\uc774 \uc804\ud600 \uc5c6\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uc544\ub984\ub2e4\uc6c0\uc744 \ub290\ub07c\uac8c \ud558\ub294 \uc911\uc2ec\uc774 \ub3cc \ud45c\uba74\uc758 \uc774\uc57c\uae30\uc5d0\uc11c \uad6c\uc870\uc758 \ubc18\ubcf5\uacfc \uace1\uc120\uc73c\ub85c \uc62e\uaca8 \uac04\ub2e4. \uac74\ubb3c\uc774 \ubb34\uc5c7\uc73c\ub85c \uc11c \uc788\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \ud0dc\ub3c4 \uc790\uccb4\uac00 \ubbf8\uac10\uc774 \ub41c\ub2e4. \ucca0\ud0d1\uc740 \uae30\uc220\uacfc \uc608\uc220\uc744 \uc11c\ub85c \uc644\uc804\ud788 \ub098\ub20c \uc218 \uc5c6\uac8c \ub9cc\ub4e0\ub2e4. \ud0d1\uc740 \uc544\ub798\ucabd\uc758 \ub113\uac8c \ubc8c\uc5b4\uc9c4 \ub124 \ub2e4\ub9ac\uc5d0\uc11c \uc2dc\uc791\ud574 \uc704\ub85c \uac08\uc218\ub85d \uac00\ub298\uc5b4\uc9c4\ub2e4. \ub124 \uac1c\uc758 \ub3c5\ub9bd\ub41c \uc9c0\uc9c0\ubd80\uac00 \ub192\uc740 \uacf3\uc5d0\uc11c \ud558\ub098\uc758 \ud615\uc0c1\uc73c\ub85c \ubaa8\uc778\ub2e4. \uaf2d\ub300\uae30\ub9cc \uc62c\ub824\ub2e4\ubcf4\uba74 \ub193\uce58\uae30 \uc26c\uc6b4 \ubd80\ubd84\uc774\uc9c0\ub9cc, \uc544\ub798\uc758 \ud3ed\uacfc \uc704\uc758 \ub192\uc774\ub294 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. 1900\ub144\uc5d0 \ub098\uc628 \ubc1c\uba85\u00b7\uae30\uc220\uc0ac \ucc45\uc740 \uc774 \ud0d1\uc744 \ucca0 \uad6c\uc870\uac00 \uac00\uc9c4 \uac00\ub2a5\uc131\uc744 \ubcf4\uc5ec \uc900 \uc131\uacfc\ub85c \uc18c\uac1c\ud588\ub2e4. \ub2f9\uc2dc\uc758 \uae30\ub85d\uc5d0\uc11c \uc911\uc694\ud55c \uac83\uc740 \uc624\ub298\uc758 \uad00\uad11 \uc21c\uc704\uac00 \uc544\ub2c8\ub77c \uacf5\ud559\uc801 \uc131\ucde8\uc600\ub2e4. \uc5d0\ud3a0\ud0d1\uc744 \ub3d9\uc2dc\ub300 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5a4 \uc0c8\ub85c\uc6c0\uc73c\ub85c \uc77d\uc5c8\ub294\uc9c0 \uc54c\ub824 \uc8fc\ub294 \ub300\ubaa9\uc774\ub2e4. \uc5d0\ud3a0\ud0d1\uc744 \uc774\ub8e8\ub294 \uac83\uc740 \ud558\ub098\ub85c \ubd80\uc5b4 \ub9cc\ub4e0 \uac70\ub300\ud55c \ucca0 \ub369\uc5b4\ub9ac\uac00 \uc544\ub2c8\ub2e4. \uc5ec\ub7ec \ubd80\uc7ac\uac00 \uc5f0\uacb0\ub418\uba74\uc11c \uc804\uccb4\uac00 \ub41c\ub2e4. \ucca0\ud310\uacfc \ubd80\uc7ac\ub97c \uc787\ub294 \ub9ac\ubcb3\ub3c4 \uc774 \uad6c\uc870\uc758 \uc77c\ubd80\uc600\ub2e4. \uba40\ub9ac\uc11c \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc791\uc740 \uc811\ud569\uc774 \ud070 \ud615\ud0dc\ub97c \uac00\ub2a5\ud558\uac8c \ud588\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub192\uc740 \uac74\ubb3c\uc744 \ubcf4\ub294 \ub208\uc744 \ubc14\uafbc\ub2e4. \ub192\uc774\ub294 \uc885\uc885 \ud55c \uc0ac\ub78c\uc758 \uc57c\uc2ec\uc73c\ub85c \uc124\uba85\ub418\uc9c0\ub9cc, \uc2e4\uc81c \uac74\uc124\uc5d0\ub294 \uacc4\uc0b0\uacfc \uc81c\uc791, \uc870\ub9bd\uc758 \uc9c8\uc11c\uac00 \ud544\uc694\ud558\ub2e4. \ud070 \uc724\uacfd\uc744 \uc124\uacc4\ud558\ub294 \uc77c\uacfc \uc791\uc740 \ubd80\ud488\uc774 \ub9de\uc544 \ub4e4\uc5b4\uac00\uac8c \ud558\ub294 \uc77c \uc0ac\uc774\uc5d0\ub294 \uae34 \uac70\ub9ac\uac00 \uc788\ub2e4. \ud0d1\uc758 \uac00\ubcbc\uc6cc \ubcf4\uc774\ub294 \uc778\uc0c1 \ub4a4\uc5d0\ub294 \ubc18\ubcf5\ub418\ub294 \uc815\ubc00\ud55c \uc791\uc5c5\uc774 \uc788\uc5c8\ub2e4. \ub192\uc740 \uc804\ub9dd\ub300\ub294 \uc775\uc219\ud55c \uac70\ub9ac\uc758 \uacbd\ud5d8\uc744 \ubc14\uafbc\ub2e4. \uc9c0\uc0c1\uc5d0\uc11c\ub294 \uac74\ubb3c \uc0ac\uc774\ub97c \uac77\uc9c0\ub9cc \uc704\uc5d0\uc11c\ub294 \uae38\uacfc \uac15, \uac74\ubb3c\uc758 \ubc30\uce58\ub97c \ud558\ub098\uc758 \ubaa8\uc2b5\uc73c\ub85c \ubcf8\ub2e4. \ud0d1\uc740 \uad6c\uacbd\ud560 \ub300\uc0c1\uc774\uba74\uc11c \ub3c4\uc2dc\ub97c \uc0c8\ub86d\uac8c \uad6c\uacbd\ud558\uac8c \ud558\ub294 \ub3c4\uad6c\uc774\uae30\ub3c4 \ud558\ub2e4. \ubcf4\uc774\ub294 \uac83\uacfc \ubcf4\ub294 \uc790\ub9ac\uac00 \ud55c \uac74\ucd95\ubb3c \uc548\uc5d0\uc11c \ub9cc\ub09c\ub2e4. \ucd08\uae30\uc758 \ud0d1\uc5d0\ub3c4 \uacc4\ub2e8\uacfc \uc2b9\uac15 \uc7a5\uce58\uac00 \ub9c8\ub828\ub418\uc5c8\ub2e4. \uad00\ub78c\uac1d\uc744 \uc62c\ub824 \ubcf4\ub0b4\ub294 \ubb38\uc81c\ub294 \ud0d1\uc744 \uc138\uc6b0\ub294 \ubb38\uc81c\uc640 \ubcc4\uac1c\uac00 \uc544\ub2c8\ub2e4. \ub192\uc740 \uad6c\uc870\ubb3c\uc744 \uc548\uc804\ud558\uac8c \uc774\uc6a9\ud560 \uc218 \uc788\uc5b4\uc57c \uc804\ub9dd\uc774 \uacf5\uacf5\uc758 \uacbd\ud5d8\uc774 \ub41c\ub2e4. \ub192\uc774\uc758 \uc5ed\uc0ac\uc5d0\ub294 \uadf8 \ub192\uc774\uc5d0 \uc811\uadfc\ud558\ub294 \uae30\uc220\uc758 \uc5ed\uc0ac\ub3c4 \ud3ec\ud568\ub41c\ub2e4. \ucd08\uae30 \uc5d0\ud3a0\ud0d1\uc744 \uc18c\uac1c\ud55c \uae30\uc220\uc0ac \uae30\ub85d\uc5d0\ub294 \uc544\ub798\uce35 \ub458\ub808\uc5d0 \ud504\ub791\uc2a4\uc758 \uc800\uba85\ud55c \uc778\ubb3c\ub4e4 \uc774\ub984\uc744 \ud06c\uac8c \uc0c8\uacbc\ub2e4\ub294 \uc124\uba85\ub3c4 \ub098\uc628\ub2e4. \uc774\ub984\uc744 \uae30\ub150\ud558\ub294 \ubc29\uc2dd\uc774 \uc655\uacfc \uc7a5\uad70\uc758 \ub3d9\uc0c1\uc5d0\ub9cc \ud55c\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc774 \ud765\ubbf8\ub86d\ub2e4. \ud0d1\uc758 \uc7ac\ub8cc\ubfd0 \uc544\ub2c8\ub77c \uadf8 \ud45c\uba74\uc758 \uc774\ub984\ub3c4 \ud55c \uc2dc\ub300\uc758 \uc790\ubd80\uc2ec\uc744 \ub4dc\ub7ec\ub0b8\ub2e4. \uacfc\ud559\uacfc \uae30\uc220\uc758 \uc131\ucde8\ub97c \uad6d\uac00\uc758 \uc774\uc57c\uae30\ub85c \uc5ee\ub294 \uac83\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \ud0d1\uc744 \ud504\ub791\uc2a4\ub9cc\uc758 \ub3c5\ub9bd\ub41c \ubc1c\uba85 \uc815\uc2e0\uc73c\ub85c \uc124\uba85\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc0b0\uc5c5 \uae30\uc220\uc740 \uc5ec\ub7ec \uc9c0\uc5ed\uc758 \uacbd\ud5d8\uc774 \uc313\uc774\uba70 \ubc1c\uc804\ud588\ub2e4. \uae30\ub150\ubb3c\uc740 \uadf8 \ub113\uc740 \ud750\ub984 \uac00\uc6b4\ub370 \ubb34\uc5c7\uc744 \uc790\uae30 \ub3c4\uc2dc\uc758 \uae30\uc5b5\uc73c\ub85c \ub0b4\uc138\uc6b0\ub294\uc9c0 \ubcf4\uc5ec \uc900\ub2e4. \uc9c0\uae08\uc740 \uc5d0\ud3a0\ud0d1 \uc5c6\ub294 \ud30c\ub9ac\ub97c \uc0c1\uc0c1\ud558\uae30 \uc5b4\ub835\uc9c0\ub9cc, \uadf8 \ubaa8\uc2b5\uc774 \ub3c4\uc2dc\uc758 \ud48d\uacbd\uacfc \ud568\uaed8 \ud0dc\uc5b4\ub09c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0c8\ub85c\uc6b4 \ud589\uc0ac\ub97c \uc704\ud574 \uc0c8\ub85c\uc6b4 \uc7ac\ub8cc\uc758 \uac00\ub2a5\uc131\uc744 \ub0b4\uc138\uc6b4 \uad6c\uc870\ubb3c\uc774 \ub4e4\uc5b4\uc654\uace0, \uc2dc\uac04\uc774 \ud750\ub974\uba74\uc11c \ub3c4\uc2dc\ub97c \ub300\ud45c\ud558\ub294 \ud45c\uc9c0\uac00 \ub418\uc5c8\ub2e4. \uc624\ub798\ub41c \uac83\ucc98\ub7fc \ubcf4\uc774\ub294 \uc0c1\uc9d5\uc5d0\ub3c4 \uc2dc\uc791\uc758 \uc21c\uac04\uc774 \uc788\ub2e4. \ucd08\uae30\uc758 \uadf8\ub9bc\uc774\ub098 \uc0ac\uc9c4\uc744 \ud604\uc7ac\uc758 \ubaa8\uc2b5\uacfc \ube44\uad50\ud560 \ub54c\uc5d0\ub294 \ucd2c\uc601 \uc2dc\uae30\ub97c \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\ub2e4. \uc8fc\ubcc0 \uac74\ubb3c\uacfc \uac15 \uc704\uc758 \ubc30\uae4c\uc9c0 \ubcf4\uba74 \ud0d1 \ud558\ub098\ub9cc \uc624\ub798 \ub0a8\uc740 \uac83\uc774 \uc544\ub2c8\ub77c \uadf8\uac83\uc744 \ubc14\ub77c\ubcf4\ub294 \ub3c4\uc2dc\uc758 \ud658\uacbd\ub3c4 \uacc4\uc18d \ub2ec\ub77c\uc84c\uc74c\uc744 \ubc1c\uacac\ud560 \uc218 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \uc5d0\ud3a0\ud0d1 \uc0ac\uc9c4\uc744 \ubcfc \ub54c\uc5d0\ub294 \uaf2d\ub300\uae30\ub9cc \ubcf4\uc9c0 \ub9d0\uace0 \ub124 \ub2e4\ub9ac\uc640 \uaca9\uc790, \uadf8 \uc0ac\uc774\ub85c \ube44\uce58\ub294 \ud558\ub298\uc744 \ud568\uaed8 \ubcf4\uc790. \ud30c\ub9ac\uc758 \ub0ad\ub9cc\uc774\ub77c\ub294 \ub9d0 \ub4a4\uc5d0\uc11c \uc0b0\uc5c5 \uc2dc\ub300\uc758 \uacc4\uc0b0\uacfc \ub178\ub3d9\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \uadf8 \ub450 \ubaa8\uc2b5\uc744 \ub3d9\uc2dc\uc5d0 \uc77d\uc744 \ub54c \uc774 \ucca0\ud0d1\uc740 \ub354\uc6b1 \ud765\ubbf8\ub85c\uc6b4 \uac74\ucd95\ubb3c\uc774 \ub41c\ub2e4."}, {"id": "ellis-island-inspection-manifests-and-families", "title": "\uc5d8\ub9ac\uc2a4\uc12c \u2014 \uc790\uc720\uc758 \uc5ec\uc2e0\uc0c1 \ub2e4\uc74c\uc5d0\ub294 \uc9c8\ubb38\uc774 \uae30\ub2e4\ub838\ub2e4", "summary": "\ub274\uc695\ud56d \ub3c4\ucc29\uacfc \ubc95\uc801 \uc785\uad6d \uc0ac\uc774\uc758 \uba85\ubd80\u00b7\uc758\ub8cc\u00b7\uc0dd\uacc4 \uc2ec\uc0ac, \ub300\uae30\uc640 \uac00\uc871\uc758 \uacbd\ud5d8\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/ellis-island-inspection-manifests-and-families/index.html", "image": "../media/ellis-island-inspection-manifests-and-families.png", "alt": "\uc11c\ub958\uc640 \uc9d0\uc744 \ub4e0 \uac00\uc871\uc774 \uc2ec\uc0ac\uad00 \uc55e\uc5d0\uc11c \uae30\ub2e4\ub9ac\ub294 \uc5d8\ub9ac\uc2a4\uc12c \uad00\ub828 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uc5d8\ub9ac\uc2a4\uc12c \u2014 \uc790\uc720\uc758 \uc5ec\uc2e0\uc0c1 \ub2e4\uc74c\uc5d0\ub294 \uc9c8\ubb38\uc774 \uae30\ub2e4\ub838\ub2e4 \uc2b9\uac1d \uba85\ubd80\uc640 \uac74\uac15 \uac80\uc0ac, \ud5c8\uac00\ub97c \uae30\ub2e4\ub9b0 \uac00\uc871\ub4e4 \ub274\uc695\ud56d \ub3c4\ucc29\uacfc \ubc95\uc801 \uc785\uad6d \uc0ac\uc774\uc758 \uba85\ubd80\u00b7\uc758\ub8cc\u00b7\uc0dd\uacc4 \uc2ec\uc0ac, \ub300\uae30\uc640 \uac00\uc871\uc758 \uacbd\ud5d8\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ub274\uc695\ud56d\uc5d0 \ub3c4\ucc29\ud55c \uc774\ubbfc\uc790\uc5d0\uac8c \uc790\uc720\uc758 \uc5ec\uc2e0\uc0c1\uc740 \uae34 \ud56d\ud574\uc758 \ub05d\uc744 \uc54c\ub9ac\ub294 \ubaa8\uc2b5\uc774\uc5c8\uc744 \uac83\uc774\ub2e4. \uadf8\ub7ec\ub098 \ud56d\uad6c\uac00 \ubcf4\uc778\ub2e4\uace0 \ubbf8\uad6d \uc785\uad6d\uc774 \uc790\ub3d9\uc73c\ub85c \ud5c8\uac00\ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. 19\uc138\uae30 \ub9d0\ubd80\ud130 \ub9ce\uc740 \uc774\ubbfc\uc790\uac00 \uac70\uce5c \uc5d8\ub9ac\uc2a4\uc12c\uc5d0\uc11c\ub294 \uac74\uac15\uacfc \uc11c\ub958, \uc0dd\uacc4\uc640 \uac00\uc871\uc5d0 \uad00\ud55c \uc2ec\uc0ac\uac00 \uc774\uc5b4\uc84c\ub2e4. \ud658\uc601\uc758 \uc0c1\uc9d5 \ub4a4\uc5d0 \uc788\ub358 \uc808\ucc28\ub97c \uc0b4\ud3b4\ubcf4\uc790. \uc5d8\ub9ac\uc2a4\uc12c\uc740 1892\ub144 \uc5f0\ubc29 \uc774\ubbfc \uc2ec\uc0ac \uc2dc\uc124\ub85c \ubb38\uc744 \uc5f4\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \ub274\uc695\ud56d\uc5d0 \ub3c4\ucc29\ud55c \ubaa8\ub4e0 \uc2b9\uac1d\uc774 \uc5b8\uc81c\ub098 \uc774 \uc12c\uc73c\ub85c \uc62e\uaca8\uc9c4 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc120\uc2e4 \ub4f1\uae09\uacfc \uc2ec\uc0ac\uc0c1\uc758 \ud310\ub2e8\uc5d0 \ub530\ub77c \ubc30\uc5d0\uc11c \uc808\ucc28\ub97c \ub9c8\uce58\ub294 \uacbd\uc6b0\ub3c4 \uc788\uc5c8\uace0 \ucd94\uac00 \ud655\uc778\uc744 \uc704\ud574 \uc774\ub3d9\ud558\ub294 \uc0ac\ub78c\ub3c4 \uc788\uc5c8\ub2e4. \ub530\ub77c\uc11c \uc774\ubbfc\uc790\ub77c\ub294 \ud55c \uc774\ub984 \uc548\uc5d0\ub3c4 \uacbd\ud5d8\uc758 \ucc28\uc774\uac00 \uc788\uc5c8\ub2e4. \ub3c8\uacfc \uc5ec\ud589 \uc870\uac74\uc740 \ub3c4\ucc29 \uc774\ud6c4\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc8fc\uc5c8\ub2e4. \uc12c\uc758 \uacc4\ub2e8\uc744 \uc624\ub978 \uc0ac\ub78c\ub4e4\uc758 \uc774\uc57c\uae30\ub294 \uc774\ubbfc\uc758 \uc911\uc694\ud55c \ubd80\ubd84\uc774\uc9c0\ub9cc \ubbf8\uad6d\uc5d0 \ub4e4\uc5b4\uc628 \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \ub3d9\uc77c\ud55c \uacbd\ud5d8\uc73c\ub85c \ud655\ub300\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ubc30\uac00 \ud56d\uad6c\uc5d0 \ub3c4\ucc29\ud55c \uc21c\uac04, \uc12c\uc5d0 \ub0b4\ub9b0 \uc21c\uac04, \ubc95\uc801\uc73c\ub85c \uc785\uad6d\uc744 \uc778\uc815\ubc1b\ub294 \uc21c\uac04\uc740 \uac19\uc9c0 \uc54a\uc558\ub2e4. \ub2f9\uc2dc \uc81c\ub3c4\ub294 \uc774 \ucc28\uc774\ub97c \ud1b5\ud574 \ub300\uae30 \uc911\uc778 \uc0ac\ub78c\uacfc \uc120\ubc15 \ud68c\uc0ac\uc758 \ucc45\uc784\uc744 \ub098\ub204\uc5c8\ub2e4. \ubc14\ub2e4\ub97c \ub2e4 \uac74\ub11c\ub294\ub370\ub3c4 \uc544\uc9c1 \ub3c4\ucc29\ud558\uc9c0 \ubabb\ud55c \ub4ef\ud55c \uc0c1\ud0dc\uac00 \uc0dd\uae38 \uc218 \uc788\uc5c8\ub2e4. \uc120\ubc15 \ud68c\uc0ac\ub294 \uc2b9\uac1d\uc758 \uc774\ub984\uacfc \ub098\uc774, \ucd9c\uc2e0\uacfc \ubaa9\uc801\uc9c0 \ub4f1 \ubc95\uc5d0\uc11c \uc694\uad6c\ud558\ub294 \uc815\ubcf4\ub97c \uba85\ubd80\uc5d0 \uc801\uc5c8\ub2e4. \uc2ec\uc0ac\uad00\uc740 \ub3c4\ucc29\ud55c \uc0ac\ub78c\uc758 \ub300\ub2f5\uacfc \uae30\ub85d\uc744 \ube44\uad50\ud588\ub2e4. \uc774\ub984\ub9cc \ubb3b\uace0 \ubc14\ub85c \ub3c4\uc2dc\ub85c \ubcf4\ub0b4\ub294 \uac04\ub2e8\ud55c \uc778\uc0ac \uc808\ucc28\uac00 \uc544\ub2c8\uc5c8\ub358 \uac83\uc774\ub2e4. \uc774 \uc11c\ub958\ub294 \uc624\ub298\ub0a0 \uac00\uc871\uc758 \uc774\ub3d9 \uacbd\ub85c\ub97c \ucc3e\ub294 \uc790\ub8cc\uac00 \ub418\uae30\ub3c4 \ud55c\ub2e4. \ub2e4\ub9cc \ubb38\uc11c \ud55c \uc904\uc774 \ud55c \uc0ac\ub78c\uc758 \uc0dd\uc560 \uc804\uccb4\ub97c \ub2f4\uc9c0\ub294 \uc54a\ub294\ub2e4. \ucca0\uc790\uc640 \ub9d0\uc758 \uc804\ub2ec, \uae30\ub85d \uacfc\uc815\uc758 \uc624\ub958\uac00 \uc788\uc744 \uc218 \uc788\uc73c\ubbc0\ub85c \uc11c\ub85c \ub2e4\ub978 \ubb38\uc11c\ub97c \ud568\uaed8 \ube44\uad50\ud574\uc57c \ud55c\ub2e4. \ub3c4\ucc29\uc790\ub4e4\uc740 \uacf5\uc911\ubcf4\uac74 \ub2f4\ub2f9\uc790\uc758 \uac80\uc0ac\ub97c \ubc1b\uc558\ub2e4. \ub2f9\uc2dc \ubc95\uc774 \ubc30\uc81c \uc0ac\uc720\ub85c \uc815\ud55c \uc9c8\ubcd1\uc774\ub098 \uc0c1\ud0dc\uac00 \uc758\uc2ec\ub418\uba74 \ucd94\uac00 \uac80\uc0ac\ub97c \uc704\ud574 \uba48\ucdb0\uc57c \ud588\ub2e4. \uae34 \ud56d\ud574\ub85c \uc9c0\uce5c \ubab8\uc774 \uc0c8\ub85c\uc6b4 \uc0dd\ud65c\uc758 \ucd9c\ubc1c\uc810\uc5d0\uc11c \ub2e4\uc2dc \ud3c9\uac00 \ub300\uc0c1\uc774 \ub41c \uac83\uc774\ub2e4. \uc5ec\uae30\uc11c \uacfc\uac70\uc758 \uc758\ud559\uc801 \ubd84\ub958\ub97c \uc624\ub298\uc758 \uc0ac\ub78c\uc5d0 \ub300\ud55c \uc815\ub2f9\ud55c \ud310\ub2e8\uc73c\ub85c \uadf8\ub300\ub85c \uc2b9\uc778\ud560 \uc218\ub294 \uc5c6\ub2e4. \uac74\uac15\uacfc \uc7a5\uc560\ub97c \ubc14\ub77c\ubcf4\ub358 \uae30\uc900\uc5d0\ub294 \ub2f9\uc2dc \uc0ac\ud68c\uc758 \ud3b8\uacac\ub3c4 \uc788\uc5c8\ub2e4. \uac80\uc0ac \uc81c\ub3c4\ub97c \uc124\uba85\ud558\ub294 \uc77c\uacfc \uadf8 \uc81c\ub3c4\uac00 \ub0b4\ub9b0 \ud3c9\uac00\ub97c \uc0ac\uc2e4\uc0c1 \ub2f9\uc5f0\ud55c \uac83\uc73c\ub85c \ubc1b\uc544\ub4e4\uc774\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uc11c\ub958\uc5d0 \uc801\ud78c \uc9c8\ubb38\uc774 \uc9e7\ub2e4\uace0 \ub300\ub2f5\uc5d0 \ud544\uc694\ud55c \uc0ac\uc815\uae4c\uc9c0 \ub2e8\uc21c\ud55c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uba40\ub9ac \ub5a8\uc5b4\uc9c4 \uce5c\ucc99\uacfc\uc758 \uc57d\uc18d, \ub3c4\ucc29 \ub4a4 \uc77c\uc790\ub9ac\uc758 \ubd88\ud655\uc2e4\ud568, \ud568\uaed8 \uc628 \uc0ac\ub78c\uc758 \ub3cc\ubd04\uc774 \uc5bd\ud600 \uc788\uc5c8\ub2e4. \uc2ec\uc0ac\uad00\uc774 \ubd84\ub958\ud558\ub294 \ud56d\ubaa9\uacfc \ub2f9\uc0ac\uc790\uac00 \uc0b4\uc544\uc628 \uacbd\ud5d8 \uc0ac\uc774\uc5d0\ub294 \uac04\uaca9\uc774 \uc788\uc5c8\ub2e4. \uc2ec\uc0ac\uc5d0\uc11c\ub294 \ub204\uad6c\ub97c \ub9cc\ub098\ub7ec \uac00\ub294\uc9c0, \uc5b4\ub514\uc5d0\uc11c \uc9c0\ub0bc\uc9c0, \uc5b4\ub5a4 \uc77c\uc744 \ud560\uc9c0, \uc0dd\ud65c\ud560 \ub3c8\uc774 \uc788\ub294\uc9c0 \uac19\uc740 \ubb38\uc81c\uac00 \uc911\uc694\ud588\ub2e4. \uad6d\uac00\uac00 \uc785\uad6d\uc790\uc758 \ubbf8\ub798 \uc0dd\uacc4\uc640 \ubd80\uc591 \uac00\ub2a5\uc131\uc744 \ud310\ub2e8\ud558\ub824 \ud588\uae30 \ub54c\ubb38\uc774\ub2e4. \ub2f9\uc0ac\uc790\uc5d0\uac8c\ub294 \uc9e7\uc740 \ub300\ub2f5 \ud558\ub098\ub3c4 \ubd80\ub2f4\uc774 \ucef8\uc744 \uac83\uc774\ub2e4. \ud1b5\uc5ed\uc740 \uc774 \uacfc\uc815\uc744 \uac00\ub2a5\ud558\uac8c \ud558\ub294 \ud575\uc2ec\uc801\uc778 \uc77c\uc774\uc5c8\ub2e4. \uc9c8\ubb38\uc744 \uc774\ud574\ud558\uace0 \uc0ac\uc815\uc744 \uc804\ub2ec\ud558\ub294 \uc0ac\uc774\uc5d0\ub294 \uc5b8\uc5b4\uc640 \uae30\ub85d\uc758 \uac04\uaca9\uc774 \uc788\uc5c8\ub2e4. \uc774\ubbfc \uc2ec\uc0ac\ub97c \ubc95 \uc870\ubb38\uc758 \uc9d1\ud589\uc73c\ub85c\ub9cc \ubcf4\uba74 \uadf8\ub7f0 \ub9d0\uc744 \uc62e\uae30\ub294 \ub178\ub3d9\uacfc \uae34\uc7a5, \uc624\ud574\uc758 \uac00\ub2a5\uc131\uc774 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc27d\uac8c \uc785\uad6d \uc790\uaca9\uc744 \ud655\uc778\ud560 \uc218 \uc5c6\ub294 \uc0ac\ub78c\uc740 \ud2b9\ubcc4 \uc2ec\uc0ac\ub85c \ub118\uc5b4\uac08 \uc218 \uc788\uc5c8\ub2e4. \uc870\uc0ac\uc640 \uacb0\uc815, \uacbd\uc6b0\uc5d0 \ub530\ub77c \uc774\uc758 \uc81c\uae30\uac00 \uc774\uc5b4\uc84c\ub2e4. \uc12c\uc5d0\ub294 \ub300\uae30\uc640 \uc219\uc2dd, \ubcd1\uc6d0 \uc2dc\uc124\uc774 \ud544\uc694\ud588\ub2e4. \uc7a0\uae50\uc758 \ud1b5\uacfc \uc9c0\uc810\uc774 \ub204\uad70\uac00\uc5d0\uac8c\ub294 \uae38\uac8c \uba38\ubb34\ub294 \uc7a5\uc18c\uac00 \ub41c \uc148\uc774\ub2e4. \uac00\uc871 \uc911 \ud55c \uc0ac\ub78c\uc5d0\uac8c \ubb38\uc81c\uac00 \uc0dd\uae30\uba74 \ud568\uaed8 \uc628 \uc0ac\ub78c\ub4e4\uc758 \uc120\ud0dd\ub3c4 \uc5b4\ub824\uc6cc\uc84c\ub2e4. \ubaa8\ub450\uac00 \uac19\uc740 \uc2dc\uac04\uc5d0 \ub098\uac08 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ud589\uc815\uc801\uc73c\ub85c\ub294 \uac1c\uc778 \ud55c \uba85\uc758 \uc0ac\uac74\ucc98\ub7fc \ubd84\ub958\ud574\ub3c4 \ub2f9\uc0ac\uc790\ub4e4\uc5d0\uac8c\ub294 \uac00\uc871\uacfc \ub3cc\ubd04, \uc7ac\ud68c \uacc4\ud68d\uc774 \uac78\ub9b0 \uc77c\uc774\uc5c8\ub2e4. \ub2f9\uc2dc \uac1c\uc124\uc11c\uc758 \uc808\ucc28 \uc124\uba85\uc740 \uae30\uad00\uc774 \uc2a4\uc2a4\ub85c \uc815\ub2f9\ud558\ub2e4\uace0 \ubcf4\ub294 \uad00\uc810\uc5d0\ub3c4 \uae30\ub300\uc5b4 \uc788\ub2e4. \uc2e0\uc18d\ud558\uace0 \ud6a8\uc728\uc801\uc778 \uc2ec\uc0ac\ub97c \uce6d\ucc2c\ud55c \ubb38\uc7a5\uc744 \ub2f9\uc0ac\uc790\uc758 \ub9cc\uc871\uacfc \uac19\uc740 \ub73b\uc73c\ub85c \uc77d\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uacf5\uc2dd \uaddc\uce59\uacfc \uc2e4\uc81c \ub300\uc6b0\uac00 \uc77c\uce58\ud588\ub294\uc9c0\uc5d0\ub294 \ubcc4\ub3c4\uc758 \uc9c8\ubb38\uc774 \ud544\uc694\ud558\ub2e4. \uc5d8\ub9ac\uc2a4\uc12c\uc5d0\uc11c \uad00\ub9ac\uac00 \ub0af\uc120 \uc774\ub984\uc744 \uc804\ubd80 \uc0c8 \uc774\ub984\uc73c\ub85c \ubc14\uafb8\uc5c8\ub2e4\ub294 \uc774\uc57c\uae30\ub294 \ub110\ub9ac \ud37c\uc838 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc77c\ubc18\uc801\uc778 \uc808\ucc28\ub294 \uc774\ubbf8 \uc791\uc131\ub41c \uc2b9\uac1d \uba85\ubd80\ub97c \ucc38\uace0\ud574 \uc2e0\uc6d0\uacfc \uc785\uad6d \uc790\uaca9\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774\uc5c8\ub2e4. \uc12c\uc774 \uc77c\ub960\uc801\uc778 \uac1c\uba85 \uae30\uad00\uc774\uc5c8\ub2e4\uace0 \ub9d0\ud560 \uadfc\uac70\ub294 \uc5c6\ub2e4. \ubb3c\ub860 \uc774\ubbfc \uacfc\uc815\uc5d0\uc11c \uc774\ub984\uc758 \ucca0\uc790\ub098 \uc0ac\uc6a9 \ud615\ud0dc\uac00 \ubcc0\ud55c \uc0ac\ub840\ub294 \ub9ce\ub2e4. \uc120\ubc15 \uae30\ub85d \uc774\uc804\uc758 \uc804\uc0ac, \ub2e4\ub978 \uc11c\ub958, \uc785\uad6d \ub4a4 \ud559\uad50\uc640 \uc9c1\uc7a5, \ub2f9\uc0ac\uc790\uc758 \uc120\ud0dd \ub4f1 \uc2dc\uc810\uacfc \uc774\uc720\ub97c \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ubaa8\ub4e0 \ubcc0\ud654\ub97c \ud55c \uc2ec\uc0ac\uad00\uc758 \uc21c\uac04\uc801\uc778 \uacb0\uc815\uc73c\ub85c \uc124\uba85\ud558\uba74 \uc2e4\uc81c \uac00\uc871\uc758 \uc5ed\uc0ac\uac00 \ub2e8\uc21c\ud574\uc9c4\ub2e4. \uc5d8\ub9ac\uc2a4\uc12c\uc744 \ud1b5\uacfc\ud55c \uc0ac\ub78c\ub4e4 \uc911 \ub9ce\uc740 \uc774\uac00 \uc0c8\ub85c\uc6b4 \uc0dd\ud65c\uc744 \uc2dc\uc791\ud588\ub2e4. \ub3d9\uc2dc\uc5d0 \uc785\uad6d\uc744 \uac70\ubd80\ub2f9\ud558\uace0 \ub3cc\uc544\uac04 \uc0ac\ub78c\ub3c4 \uc788\uc5c8\ub2e4. \uc131\uacf5\uc801\uc778 \uc815\ucc29\uc758 \ucd94\uc5b5\ub9cc\uc73c\ub85c \uc804\uccb4 \uc81c\ub3c4\ub97c \uc124\uba85\ud560 \uc218 \uc5c6\uace0, \ubbf8\uad6d \uc774\ubbfc\uc758 \ubaa8\ub4e0 \ud1b5\ub85c\ub97c \ub274\uc695 \ud55c\uacf3\uc73c\ub85c \ubb36\uc744 \uc218\ub3c4 \uc5c6\ub2e4. \uc774 \uae00\uc740 \uc8fc\ub85c 20\uc138\uae30 \ucd08\uc758 \uc2ec\uc0ac \uae30\ub85d\uacfc \uc808\ucc28\ub97c \ub2e4\ub8ec\ub2e4. \ub2f9\uc2dc \uc774\ubbfc \uac1c\uc124\uc11c\uc5d0 \ub4e4\uc5b4 \uc788\ub294 \ubbfc\uc871\ubcc4 \uc6b0\uc5f4\uacfc \ubc30\uc81c\uc758 \uc815\ub2f9\ud654\ub294 \ub530\ub974\uc9c0 \uc54a\uc558\ub2e4. \uc790\uc720\uc758 \uc5ec\uc2e0\uc0c1\uc744 \ubcf8 \ub4a4 \uae30\ub2e4\ub9b0 \uc9c8\ubb38\uc744 \ub5a0\uc62c\ub9ac\uba74, \uc774\ubbfc\uc758 \uc5ed\uc0ac\ub294 \ud76c\ub9dd\uacfc \uad6d\uac00\uc758 \ud5c8\uac00\uac00 \ub9cc\ub098\ub294 \uad6c\uccb4\uc801\uc778 \uc790\ub9ac\ub85c \ubcf4\uc778\ub2e4."}, {"id": "erie-canal-1825-locks-tolls-and-new-york", "title": "\uc5d0\ub9ac \uc6b4\ud558 \u2014 \ub0b4\ub959\uc758 \uace1\ubb3c\uc774 \ub274\uc695\ud56d\uc73c\ub85c \uac00\ub294 \uae38", "summary": "\uac11\ubb38\uacfc \ud1b5\ud589\ub8cc, \ub178\ub3d9\uacfc \ud56d\uad6c\ub97c \uc5f0\uacb0\ud55c \uacf5\uacf5\uc0ac\uc5c5\uc758 \ubc30\uacbd\uacfc \uc804\uac1c, \uc774\ud6c4\uc758 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities", "everyday-inventions"], "url": "stories/erie-canal-1825-locks-tolls-and-new-york/index.html", "image": "../media/erie-canal-1825-locks-tolls-and-new-york.jpg", "alt": "\ub274\uc695\uc8fc \ub86c\uc5d0 \uc788\ub294 \uc6b4\ud558 \uac11\ubb38\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc2e4\uc81c \uc5ed\uc0ac \uc0ac\uc9c4", "text": "\uc5d0\ub9ac \uc6b4\ud558 \u2014 \ub0b4\ub959\uc758 \uace1\ubb3c\uc774 \ub274\uc695\ud56d\uc73c\ub85c \uac00\ub294 \uae38 \uac11\ubb38\uacfc \ud1b5\ud589\ub8cc, \ub178\ub3d9\uacfc \ud56d\uad6c\ub97c \uc5f0\uacb0\ud55c \uacf5\uacf5\uc0ac\uc5c5 \uac11\ubb38\uacfc \ud1b5\ud589\ub8cc, \ub178\ub3d9\uacfc \ud56d\uad6c\ub97c \uc5f0\uacb0\ud55c \uacf5\uacf5\uc0ac\uc5c5\uc758 \ubc30\uacbd\uacfc \uc804\uac1c, \uc774\ud6c4\uc758 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ub300\uc11c\uc591 \ud56d\uad6c\uac00 \ubc88\uc131\ud558\ub824\uba74 \ubc14\ub2e4 \ucabd \ud56d\ub85c\ub9cc \uc88b\uc544\uc11c\ub294 \ubd80\uc871\ud558\ub2e4. \ub0b4\ub959\uc5d0\uc11c \uc0dd\uc0b0\ud55c \ubb3c\uac74\uc774 \ud56d\uad6c\uae4c\uc9c0 \ub3c4\ucc29\ud560 \uae38\ub3c4 \ud544\uc694\ud558\ub2e4. 1825\ub144 \uc644\uc131\ub41c \uc5d0\ub9ac \uc6b4\ud558\ub294 \uc624\ub300\ud638\uc640 \ud5c8\ub4dc\uc2a8\uac15\uc744 \uc5f0\uacb0\ud574 \ub274\uc695\uc758 \ubc30\ud6c4\ub97c \ub113\ud614\ub2e4. \uae34 \ubb3c\uae38\uc744 \ud310\ub2e4\ub294 \uc77c\uc774 \ub3c4\uc2dc\uc640 \ub18d\uc7a5, \ub178\ub3d9\uacfc \uc7ac\uc815\uc744 \uc5b4\ub5bb\uac8c \ubc14\uafb8\uc5c8\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \ud5c8\ub4dc\uc2a8\uac15\uc744 \ub530\ub77c \uc62c\ub77c\uc624\uba74 \uc62c\ubc84\ub2c8\uc5d0 \ub2ff\uc9c0\ub9cc \uac70\uae30\uc11c \uc11c\ucabd \ub0b4\ub959\uae4c\uc9c0 \ubb3c\uae38\uc774 \uc800\uc808\ub85c \uc774\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc721\ub85c\ub85c \ubb34\uac70\uc6b4 \uc9d0\uc744 \ub098\ub974\ub294 \ub370\uc5d0\ub294 \ub9ce\uc740 \ube44\uc6a9\uacfc \uc2dc\uac04\uc774 \ub4e4\uc5c8\ub2e4. \uc624\ub300\ud638\uc640 \ub3d9\ucabd\uc758 \ud56d\uad6c\ub97c \uc787\uace0 \uc2f6\ub2e4\ub294 \uc0dd\uac01\uc774 \uc6b4\ud558 \uad6c\uc0c1\uc758 \ubc30\uacbd\uc774\uc5c8\ub2e4. \uc6b4\ud558\ub294 \uc790\uc5f0\uc758 \uac15\uc744 \uadf8\ub300\ub85c \ub530\ub77c\uac00\ub294 \uae38\uacfc \ub2e4\ub974\ub2e4. \ubb3c\uc744 \ub123\uace0 \uc720\uc9c0\ud560 \ud1b5\ub85c\ub97c \ub9cc\ub4e4\uba70 \uc9c0\ud615\uc758 \ub192\ub0ae\uc774\ub3c4 \ub118\uc5b4\uc57c \ud55c\ub2e4. \uc9c0\ub3c4\uc5d0\uc11c \ub450 \uc9c0\uc810\uc744 \uc120 \ud558\ub098\ub85c \uc787\ub294 \uac83\uacfc \uc2e4\uc81c \ubc30\uac00 \uadf8 \uc0ac\uc774\ub97c \uc9c0\ub098\uac00\ub294 \uc77c\uc758 \ucc28\uc774\uac00 \ud070 \uc0ac\uc5c5\uc774\uc5c8\ub2e4. \ubb3c\uae38\ub85c \uc2e4\uc744 \uc218 \uc788\ub294 \ubb34\uac8c\uc640 \uc721\uc0c1\uc73c\ub85c \uc62e\uae38 \ub54c\uc758 \ubd80\ub2f4\uc740 \uc0c1\ud488\uc758 \ud310\ub9e4 \ubc94\uc704\ub97c \ubc14\uafbc\ub2e4. \uae38\uc774 \uc5c6\uc5b4\uc11c\uac00 \uc544\ub2c8\ub77c \uc6b4\uc1a1\ube44\ub97c \uac10\ub2f9\ud558\uae30 \uc5b4\ub824\uc6cc \ub2ff\uc9c0 \ubabb\ud558\ub358 \uc2dc\uc7a5\uc774 \uc788\uc5c8\ub2e4. \uc6b4\ud558\ub294 \uac70\ub9ac \uc790\uccb4\ub97c \uc5c6\uc560\uc9c0\ub294 \uc54a\uc544\ub3c4 \uc0dd\uc0b0\uc790\uc640 \uad6c\ub9e4\uc790\uac00 \uacc4\uc0b0\ud558\ub294 \ube44\uc6a9\uc744 \ubc14\uafb8\ub824\ub294 \uc2dc\ub3c4\uc600\ub2e4. \ub4dc\uc717 \ud074\ub9b0\ud134\uc740 \uc6b4\ud558 \ucd94\uc9c4\uc758 \uc911\uc694\ud55c \uc778\ubb3c\uc774\uc5c8\uc9c0\ub9cc \ud63c\uc790 \uc0dd\uac01\ud574 \ub0b8 \ubc1c\uba85\uc73c\ub85c \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc55e\uc120 \uad6c\uc0c1\uacfc \uc870\uc0ac, \uc9c0\uc5ed\uc758 \uc694\uad6c\uc640 \uc5ec\ub7ec \uc815\uce58\uc778\uc758 \ud65c\ub3d9\uc774 \uc788\uc5c8\ub2e4. \ub3c8\uc744 \uc5b4\ub5bb\uac8c \ubaa8\uc73c\uace0 \uc704\ud5d8\uc744 \ub204\uac00 \uc9c8\uc9c0\uc5d0 \ub300\ud55c \ub17c\uc7c1\ub3c4 \uae38\uc5c8\ub2e4. \uc5f0\ubc29\uc758 \uc9c0\uc6d0\uc744 \uae30\ub300\ud558\uae30 \uc5b4\ub824\uc6b4 \uc0c1\ud669\uc5d0\uc11c \ub274\uc695\uc8fc\uac00 \uc911\uc2ec\uc774 \ub418\uc5c8\ub2e4. \uc131\uacf5\uc774 \ud655\uc2e4\ud55c \uc644\uc131\ud488\uc744 \uc0ac\ub294 \uc77c\uc774 \uc544\ub2c8\ub77c \uc55e\uc73c\ub85c\uc758 \ud1b5\ud589\uacfc \uc218\uc785\uc744 \uc608\uc0c1\ud558\uba70 \ub3c8\uc744 \ub4e4\uc774\ub294 \uc120\ud0dd\uc774\uc5c8\ub2e4. \uc9c0\uc5ed\uc758 \uc131\uc7a5\uacfc \uacf5\uacf5\uc0ac\uc5c5\uc758 \uc5ed\ud560\uc744 \ub458\ub7ec\uc2fc \uc815\uce58\uc801 \ud310\ub2e8\uc774 \ud544\uc694\ud588\ub2e4. \ud1b5\ud589\ub8cc\ub294 \ubc30\uac00 \uc9c0\ub098\uac00\ub294 \uc21c\uac04\uc5d0 \ub0b4\ub294 \ub3c8\uc774\uc9c0\ub9cc \uadf8 \ubc30\ud6c4\uc5d0\ub294 \uacf5\uc0ac\ube44\uc640 \uc720\uc9c0\ube44\uc758 \ubd80\ub2f4\uc774 \uc788\uc5c8\ub2e4. \uc5bc\ub9c8\ub098 \ub9ce\uc740 \ud654\ubb3c\uc774 \ub2e4\ub2d0\uc9c0, \uc218\uc785\uc73c\ub85c \uc758\ubb34\ub97c \uac10\ub2f9\ud560 \uc218 \uc788\uc744\uc9c0\ub294 \uac1c\ud1b5 \uc804\uc5d0 \ud655\uc2e4\ud558\uc9c0 \uc54a\uc558\ub2e4. \uc131\uacf5\ud55c \uacb0\uacfc\ub97c \uc54c\uace0 \uc77d\uc744\uc218\ub85d \ucc29\uacf5 \ub2f9\uc2dc\uc758 \ubd88\ud655\uc2e4\uc131\uc744 \ub193\uce58\uc9c0 \uc54a\uc544\uc57c \ud55c\ub2e4. \uc11c\ub85c \ub192\uc774\uac00 \ub2e4\ub978 \ubb3c\uae38\uc744 \uc5f0\uacb0\ud558\ub824\uba74 \uac11\ubb38\uc774 \ud544\uc694\ud588\ub2e4. \ubc30\uac00 \uad6c\ud68d \uc548\uc73c\ub85c \ub4e4\uc5b4\uc624\uba74 \ubb38\uc744 \ub2eb\uace0 \ubb3c\uc758 \ub192\uc774\ub97c \ubc14\uafb8\uc5b4 \ub2e4\uc74c \uad6c\uac04\uc73c\ub85c \uc774\ub3d9\ud558\uac8c \ud55c\ub2e4. \ubc30\ub97c \ud1b5\uc9f8\ub85c \uc0b0 \uc704\ub85c \ub04c\uc5b4 \uc62c\ub9ac\ub294 \ub300\uc2e0 \ubb3c\uc744 \uc870\uc808\ud574 \ub192\uc774 \ucc28\ub97c \ub118\ub294 \ubc29\uc2dd\uc774\ub2e4. \uac11\ubb38\uacfc \uc218\ub85c, \ubb3c\uc744 \uacf5\uae09\ud558\ub294 \uc2dc\uc124\uc740 \ud568\uaed8 \uc791\ub3d9\ud574\uc57c \ud588\ub2e4. \ubb3c\uc744 \ub108\ubb34 \uc801\uac8c \ud655\ubcf4\ud558\uac70\ub098 \uc0c8\ub294 \uacf3\uc744 \uad00\ub9ac\ud558\uc9c0 \ubabb\ud558\uba74 \uae34 \uc6b4\ud558\ub3c4 \uc4f8 \uc218 \uc5c6\ub2e4. \uc644\uacf5\ud55c \ub0a0\uc758 \uc9c0\ub3c4\ubcf4\ub2e4 \ubc18\ubcf5\ub418\ub294 \uc810\uac80\uacfc \uc218\uc120\uc774 \uc2e4\uc81c \uc6b4\uc1a1\uc744 \uac00\ub2a5\ud558\uac8c \ud588\ub358 \uc148\uc774\ub2e4. \uc218\ub85c\uc758 \ubb38\uc744 \uc5ec\ub2eb\ub294 \uc21c\uc11c\uc640 \uc218\uc704\ub97c \uad00\ub9ac\ud558\ub294 \uc77c\uc740 \ubc30 \ud55c \ucc99\uc758 \ud3b8\uc758\ub9cc\uc744 \uc704\ud55c \uac83\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ud55c \uad6c\uac04\uc5d0\uc11c \ubb3c\uc774 \ubd80\uc871\ud574\uc9c0\uba74 \ub4a4\uc758 \uc774\ub3d9\ub3c4 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4. \uae34 \uc6b4\ud558\ub97c \ud55c\uaebc\ubc88\uc5d0 \uc6c0\uc9c1\uc774\ub294 \uc870\uc9c1\uc740 \uc791\uc740 \uc2dc\uc124\ub9c8\ub2e4 \ubc18\ubcf5\ub418\ub294 \uc808\ucc28\uc5d0 \uc758\uc874\ud588\ub2e4. 1817\ub144 \uc2dc\uc791\ub41c \uacf5\uc0ac\ub294 \ub545\uc744 \ud30c\uace0 \ub098\ubb34\uc640 \ubfcc\ub9ac\ub97c \uc81c\uac70\ud558\uba70 \ud759\uacfc \ub3cc\uc744 \uc62e\uae30\ub294 \uc791\uc5c5\uc774\uc5c8\ub2e4. \uc9c0\uae08\uc758 \ub300\ud615 \uac74\uc124\uae30\uacc4\uac00 \uc788\ub294 \ud604\uc7a5\uc744 \uc0c1\uc0c1\ud558\uba74 \ub2f9\uc2dc\uc758 \uc18d\ub3c4\uc640 \uace0\uc0dd\uc744 \ub193\uce5c\ub2e4. \uce21\ub7c9\uacfc \uae30\uc220\uc801 \uace0\uc548\uc5d0 \ub354\ud574 \uc218\ub9ce\uc740 \ub178\ub3d9\uc774 \ud544\uc694\ud588\ub2e4. \ub178\ub3d9\uc790\uc758 \ucd9c\uc2e0\uacfc \uace0\uc6a9 \uc870\uac74, \ubcd1\uacfc \uc0ac\uace0\uc758 \uc704\ud5d8\ub3c4 \uacf5\uacf5\uc0ac\uc5c5\uc758 \uc5ed\uc0ac\ub2e4. \uc5b4\ub5a4 \uc9d1\ub2e8\uc774 \ubaa8\ub4e0 \uad6c\uac04\uc744 \ub9cc\ub4e4\uc5c8\ub2e4\uace0 \ud558\ub098\ub85c \ubb36\uc744 \uc218\ub294 \uc5c6\ub2e4. \ud2b9\uc815 \uc815\uce58\uc778\uc758 \uc774\ub984\uc73c\ub85c \ub0a8\uc740 \uc6b4\ud558 \ub4a4\uc5d0\uc11c \ub204\uac00 \uc5b4\ub5a4 \uc870\uac74\uc73c\ub85c \uc77c\ud588\ub294\uc9c0 \ubb3b\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \uc6b4\ud558\ub294 \ubc84\ud384\ub85c\uc5d0\uc11c \uc62c\ubc84\ub2c8\uae4c\uc9c0 \uc774\uc5b4\uc84c\uace0 \ud5c8\ub4dc\uc2a8\uac15\uacfc \ub274\uc695\ud56d\uc73c\ub85c \uc5f0\uacb0\ub418\uc5c8\ub2e4. 1825\ub144\uc758 \uac1c\ud1b5\uc740 \uc624\ub300\ud638 \uc5f0\uc548\uc758 \uc0dd\uc0b0\ubb3c\uacfc \ub300\uc11c\uc591\uc758 \uc2dc\uc7a5 \uc0ac\uc774\uc5d0 \uc0c8\ub85c\uc6b4 \uc6b4\uc1a1 \uacbd\ub85c\ub97c \ub9cc\ub4e4\uc5c8\ub2e4. \ub0b4\ub959\uacfc \ud56d\uad6c\uc758 \uad00\uacc4\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \ud55c \ubc88\uc758 \ud56d\ud574\uc640 \uae30\ub150\ud589\uc0ac\ub294 \uadf8 \uc5f0\uacb0\uc744 \ub208\uc5d0 \ubcf4\uc774\ub294 \uc0ac\uac74\uc73c\ub85c \ubcf4\uc5ec \uc8fc\uc5c8\ub2e4. \ud558\uc9c0\ub9cc \uac1c\ud1b5\uc2dd\uc744 \uce58\ub800\ub2e4\uace0 \ubaa8\ub4e0 \ubc30\uac00 \uac19\uc740 \uc2dc\uac04\uacfc \ube44\uc6a9\uc73c\ub85c \uc6c0\uc9c1\uc774\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uacc4\uc808\uacfc \ub0a0\uc528, \uc801\uc7ac\uc640 \ub300\uae30, \uad6c\uac04\ubcc4 \uc6b4\uc601 \uc870\uac74\ub3c4 \ub0a8\uc544 \uc788\uc5c8\ub2e4. \uc6b4\ud558\uc758 \ud1b5\ud589\uc740 \ub18d\uc0b0\ubb3c\uacfc \uc790\uc7ac\uac00 \uc62e\uaca8 \uac00\ub294 \uae38\uc744 \ub113\ud614\uace0 \uc8fc\ubcc0\uc758 \uc0c1\uc5c5\uacfc \uc815\ucc29\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc8fc\uc5c8\ub2e4. \ub274\uc695\ud56d\uc740 \ub354 \ub113\uc740 \ub0b4\ub959\uacfc \uc5f0\uacb0\ub418\ub294 \uc774\uc810\uc744 \uc5bb\uc5c8\ub2e4. \ud56d\uad6c\uc758 \ud798\uc740 \ub3c4\uc2dc \uc548\uc758 \uac74\ubb3c\ubfd0 \uc544\ub2c8\ub77c \uba3c \uacf3\uc5d0\uc11c \ub4e4\uc5b4\uc624\ub294 \uacbd\ub85c\uc5d0\uc11c \uc0dd\uae30\uae30\ub3c4 \ud55c\ub2e4. \uadf8 \ud61c\ud0dd\uc774 \ubaa8\ub4e0 \uc0ac\ub78c\uc5d0\uac8c \uac19\uc740 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc0c8\ub85c\uc6b4 \uc774\ub3d9\uacfc \uc815\ucc29\uc758 \ud655\ub300\ub294 \uc6d0\uc8fc\ubbfc \uacf5\ub3d9\uccb4\uc758 \ud1a0\uc9c0\uc640 \uc0dd\ud65c\uc5d0\ub3c4 \uc555\ubc15\uc744 \uc8fc\uc5c8\ub2e4. \uac1c\ucc99\uacfc \ubc88\uc601\uc774\ub77c\ub294 \ub9d0\ub9cc\uc73c\ub85c \ubcc0\ud654\ub97c \ud3c9\uac00\ud558\uba74 \ub204\uad6c\uc758 \uc774\ub3d9\uc774 \uc790\uc720\ub85c\uc6cc\uc84c\uace0 \ub204\uac00 \ubc00\ub824\ub0ac\ub294\uc9c0\uac00 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ud654\ubb3c\uc774 \uba38\ubb34\ub294 \uacf3\uc5d0\ub294 \ucc3d\uace0\uc640 \uc219\ubc15, \uc218\ub9ac\uc640 \uc911\uac1c\uc5c5\uc774 \ud544\uc694\ud588\ub2e4. \uc6b4\ud558 \uc8fc\ubcc0 \ub3c4\uc2dc\uc758 \uc131\uc7a5\uc740 \ubc30\uac00 \ub2e8\uc21c\ud788 \uc9c0\ub098\uac14\uae30 \ub54c\ubb38\ub9cc\uc774 \uc544\ub2c8\ub77c \uc774\ub7f0 \uc11c\ube44\uc2a4\uac00 \ubaa8\uc778 \uacb0\uacfc\uc600\ub2e4. \uc6b4\uc1a1\ub9dd\uc758 \ubcc0\ud654\ub294 \uc5b4\ub290 \uc7a5\uc18c\uc5d0\uc11c \uc0ac\ub78c\uc774 \uc77c\ud558\uace0 \ub3c8\uc744 \ubc84\ub294\uc9c0\ub3c4 \ub2e4\uc2dc \ubc30\uc5f4\ud588\ub2e4. \ucd08\uae30\uc758 \uc131\uacf5 \ub4a4\uc5d0\ub294 \ud655\ub300\uc640 \uac1c\uc120, \ucca0\ub3c4\uc640\uc758 \uacbd\uc7c1\uc774 \uc774\uc5b4\uc84c\ub2e4. 1825\ub144\uc758 \ubaa8\uc2b5\uc774 \uc624\ub298\uae4c\uc9c0 \uadf8\ub300\ub85c \uc720\uc9c0\ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. \ud55c \ubc88 \uc88b\uc740 \uae38\uc744 \ub9cc\ub4e4\uba74 \uc601\uc6d0\ud788 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc4f4\ub2e4\ub294 \uc0dd\uac01\uc740 \uad50\ud1b5\uc758 \uc5ed\uc0ac\uc640 \ub9de\uc9c0 \uc54a\ub294\ub2e4. \uc774 \uae00\uc5d0 \uc2e4\uc740 \uac83\uc740 \ub274\uc695\uc8fc \ub86c\uc758 \uc6b4\ud558 \uac11\ubb38\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc5ed\uc0ac \uc0ac\uc9c4\uc774\ub2e4. \uc804\uccb4 \uacf5\uc0ac \uacfc\uc815\uc774\ub098 \uac1c\ud1b5 \ub2f9\uc77c\uc758 \ubaa8\uc2b5\uc744 \ucc0d\uc740 \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \ubc30 \ud55c \ucc99\uc774 \uae30\ub2e4\ub9ac\ub294 \uac11\ubb38\uc744 \ubcf4\uba74 \uac70\ub300\ud55c \uc5f0\uacb0\ub9dd\uc774 \ubb3c\uacfc \ubb38, \uc0ac\ub78c\uc758 \ub9e4\uc77c\uc758 \uc791\uc5c5\uc5d0 \uae30\ub300\uace0 \uc788\uc5c8\uc74c\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4."}, {"id": "fez-markets-water-and-travelers-view", "title": "\ud398\uc2a4 \u2014 \uc2dc\uc7a5\uacfc \ubd84\uc218 \uc0ac\uc774\uc5d0\uc11c \uc624\ub798\ub41c \ub3c4\uc2dc\ub97c \uc77d\ub2e4", "summary": "\uc2dc\uc7a5\uacfc \ubd84\uc218, \ubc30\uc6c0\uc758 \uacf5\uac04\uc744 \uc0b4\ud53c\uba70 1917\ub144 \uc5ec\ud589 \uae30\ub85d\uc758 \uad00\uc810\uacfc \ud55c\uacc4\ub97c \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/fez-markets-water-and-travelers-view/index.html", "image": "../media/fez-markets-water-and-travelers-view.jpg", "alt": "\ud398\uc2a4 \uc2dc\uc7a5\uc758 \uc9c0\ubd95\uacfc \ub3c4\uc2dc \uac74\ubb3c, \ucca8\ud0d1\uc774 \ubcf4\uc774\ub294 \uc5ed\uc0ac \uc0ac\uc9c4", "text": "\ud398\uc2a4 \u2014 \uc2dc\uc7a5\uacfc \ubd84\uc218 \uc0ac\uc774\uc5d0\uc11c \uc624\ub798\ub41c \ub3c4\uc2dc\ub97c \uc77d\ub2e4 \uc624\ub798\ub41c \ub3c4\uc2dc \uc548\uc5d0\ub3c4 \uc5ec\ub7ec \uc2dc\uac04\uc774 \uc788\ub2e4\uc5d0\uc11c \uc2dc\uc791\ud558\ub294 \uc5ed\uc0ac\uc640 \uc791\ud488 \uc77d\uae30 \uc2dc\uc7a5\uacfc \ubd84\uc218, \ubc30\uc6c0\uc758 \uacf5\uac04\uc744 \uc0b4\ud53c\uba70 1917\ub144 \uc5ec\ud589 \uae30\ub85d\uc758 \uad00\uc810\uacfc \ud55c\uacc4\ub97c \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ubaa8\ub85c\ucf54\uc758 \ud398\uc2a4\ub97c \uc624\ub798\ub41c \uace8\ubaa9\uc758 \ubbf8\ub85c\ub77c\uace0\ub9cc \ubd80\ub974\uba74 \uadf8 \uc548\uc5d0\uc11c \uc0dd\ud65c\ud55c \uc0ac\ub78c\ub4e4\uc774 \ud750\ub824\uc9c4\ub2e4. \uc2dc\uc7a5\uacfc \ubb3c, \ubc30\uc6c0\uc758 \uacf5\uac04\uc740 \uad6c\uacbd\uac70\ub9ac\uac00 \ub418\uae30 \uc804\uc5d0 \ub3c4\uc2dc\ub97c \uc6c0\uc9c1\uc778 \uc2dc\uc124\uc774\uc5c8\ub2e4. 1917\ub144 \uc774\uacf3\uc744 \uc5ec\ud589\ud55c \uc774\ub514\uc2a4 \uc6cc\ud2bc\uc758 \uae30\ub85d\uc744 \ub2e8\uc11c\ub85c \uc0bc\ub418, \uc678\uad6d \uc5ec\ud589\uc790\uc758 \uc2dc\uc120\uc774 \ub3c4\uc2dc \uc804\uccb4\ub97c \ub300\uc2e0\ud558\uc9c0\ub294 \ubabb\ud55c\ub2e4\ub294 \uc810\ub3c4 \ud568\uaed8 \uc0b4\ud3b4\ubcf4\uc790. \ud398\uc2a4 \uc5d8\ubc1c\ub9ac\uc640 \ud398\uc2a4 \uc5d8\uc9c0\ub514\ub4dc\ub77c\ub294 \uad6c\ubd84\uc740 \ub3c4\uc2dc\uac00 \ud55c \ubc88\uc5d0 \uc644\uc131\ub418\uc9c0 \uc54a\uc558\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc61b \uc911\uc2ec\uc5d0 \uc0c8\ub85c\uc6b4 \uad8c\ub825\uacfc \uc0dd\ud65c\uc758 \uacf5\uac04\uc774 \ub354\ud574\uc84c\ub2e4. \uc624\ub298 \ubaa8\ub450 \uc624\ub798\ub418\uc5b4 \ubcf4\uc774\ub294 \uc7a5\uc18c\ub3c4 \ub9cc\ub4e4\uc5b4\uc9c4 \uc2dc\uc810\uacfc \ub9e1\uc558\ub358 \uc5ed\ud560\uc740 \uc11c\ub85c \ub2e4\ub97c \uc218 \uc788\ub2e4. \ub3c4\uc2dc \uc804\uccb4\ub97c \uc911\uc138\ub77c\ub294 \ud55c \ub2e8\uc5b4\ub85c \ubb36\uc73c\uba74 \uc774\ub7f0 \ucc28\uc774\uac00 \uc0ac\ub77c\uc9c4\ub2e4. \uc5b4\ub290 \uad6c\uc5ed\uc774 \uba3c\uc800 \ud615\uc131\ub418\uc5c8\uace0 \uc5b4\ub5a4 \uacf5\uac04\uc774 \ub098\uc911\uc5d0 \ub354\ud574\uc84c\ub294\uc9c0 \ubb3b\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc624\ub798\ub41c \ub3c4\uc2dc\ub294 \uac19\uc740 \uc2dc\ub300\uac00 \ub113\uac8c \ud3bc\uccd0\uc9c4 \uacf3\ubcf4\ub2e4 \uc5ec\ub7ec \uc2dc\ub300\uac00 \uac00\uae4c\uc774 \ubd99\uc5b4 \uc788\ub294 \uacf3\uc5d0 \uac00\uae5d\ub2e4. \uc6cc\ud2bc\uc758 \ucc45\uc5d0 \uc2e4\ub9b0 \uc0ac\uc9c4\uc5d0\ub294 \uc2dc\uc7a5 \uc704\ub97c \ub36e\uc740 \uc9c0\ubd95\uacfc \uadf8 \ub108\uba38\uc758 \ub3c4\uc2dc\uac00 \ubcf4\uc778\ub2e4. \ub2e4\ub978 \uc2dc\uc7a5 \ubb18\uc0ac\uc640 \ud568\uaed8 \ubcf4\uba74 \uc9c0\ubd95\uacfc \ucc28\uc591\uc774 \uae38\uc758 \ube5b\uc744 \uc5b4\ub5bb\uac8c \ub098\ub204\uc5c8\uc744\uc9c0 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uadf8\ub7ec\ub098 \uc774\ub97c \uc2e0\ube44\ub85c\uc6b4 \uc5b4\ub460\uc774\ub77c\uace0\ub9cc \ubb18\uc0ac\ud558\uba74 \ubb3c\uac74\uc744 \ubcf4\uace0 \uc0ac\uace0 \uc6b4\ubc18\ud558\ub294 \uc2e4\uc81c \ud65c\ub3d9\uc744 \ub193\uce5c\ub2e4. \uc2dc\uc7a5\uc740 \uc0c1\ud488\uc774 \ub193\uc778 \uc120\ubc18\ub9cc\uc73c\ub85c \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294\ub2e4. \uac70\ub798\ub97c \uc775\ud78c \uc0ac\ub78c\uacfc \uae38\uc744 \uc544\ub294 \uc6b4\ubc18\uc790, \uc77c\uc815\ud55c \uc7a5\uc18c\ub97c \ucc3e\uc544\uc624\ub294 \uc190\ub2d8\uc774 \ud544\uc694\ud558\ub2e4. \ub0af\uc120 \ubc29\ubb38\uac1d\uc5d0\uac8c \ubcf5\uc7a1\ud55c \uae38\ub3c4 \ubc18\ubcf5\ud574\uc11c \uc774\uc6a9\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc77c\uc758 \uc21c\uc11c\uc640 \uad00\uacc4\uac00 \ub2f4\uae34 \uc9c0\ub3c4\uac00 \ub420 \uc218 \uc788\ub2e4. \ub124\uc790\ub9b0 \ubd84\uc218\ucc98\ub7fc \ubb3c\uacfc \uc5f0\uacb0\ub418\ub294 \uc2dc\uc124\uc740 \uac74\ucd95 \uc7a5\uc2dd\uacfc \uc0dd\ud65c\uc758 \ud544\uc694\uac00 \ub9cc\ub098\ub294 \uc790\ub9ac\ub2e4. \ud0c0\uc77c\uacfc \ubaa9\uc7ac, \ub3cc\uc758 \uad6c\uc131\uc744 \uac10\uc0c1\ud558\uba74\uc11c\ub3c4 \uc65c \uc0ac\ub78c\ub4e4\uc774 \uc774\uacf3\uc5d0 \ubaa8\uc600\ub294\uc9c0 \ubb3c\uc5b4 \ubcfc \uc218 \uc788\ub2e4. \ub3c4\uc2dc\uc5d0\uc11c \ubb3c\uc740 \uc544\ub984\ub2e4\uc6b4 \ud48d\uacbd\uc778 \ub3d9\uc2dc\uc5d0 \ub9e4\uc77c \ud544\uc694\ud55c \uc790\uc6d0\uc774\ub2e4. \ubd84\uc218\ub97c \uc0ac\uc9c4 \uc18d \uc815\uba74 \uc7a5\uc2dd\uc73c\ub85c\ub9cc \ubcf4\uba74 \uc8fc\ubcc0\uc758 \uc774\ub3d9\uacfc \uc0ac\uc6a9\uc744 \uc0c1\uc0c1\ud558\uae30 \uc5b4\ub835\ub2e4. \ub204\uac00 \ubb3c\uc744 \uc5bb\uace0 \ub204\uac00 \uadfc\ucc98\ub97c \uc9c0\ub098\uba70 \uc5b4\ub5a4 \uc0c1\uc5c5 \uacf5\uac04\uacfc \uc774\uc5b4\uc84c\ub294\uc9c0 \uc0dd\uac01\ud558\uba74 \uc2dc\uc124\uc758 \uc0ac\ud68c\uc801\uc778 \uba74\uc774 \ubcf4\uc778\ub2e4. \ubcf4\uc874\ub41c \ud615\ud0dc\uc640 \uacfc\uac70\uc758 \uc0ac\uc6a9 \ubc29\uc2dd\uc740 \ud568\uaed8 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc6cc\ud2bc\uc740 \ud398\uc2a4\uc758 \ub9c8\ub4dc\ub77c\uc0ac\ub4e4\uc744 \uae30\ub85d\ud588\ub2e4. \ud0c0\uc77c\uacfc \uc870\uac01\ud55c \ud68c\ubcbd, \ubaa9\uc7ac\uac00 \uc5b4\uc6b0\ub7ec\uc9c0\ub294 \ub0b4\ubd80\ub294 \ub208\uc744 \ub04c\uc9c0\ub9cc \uc774\uacf3\uc740 \ubc30\uc6c0\uacfc \uc885\uad50\uc801 \uc0dd\ud65c\uc744 \uc704\ud55c \uacf5\uac04\uc774\uc5c8\ub2e4. \uc544\ub984\ub2e4\uc6b4 \ubcbd\uc744 \ub9cc\ub4e0 \uae30\uc220\uacfc \uadf8 \ubcbd \uc548\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c4 \ud65c\ub3d9\uc744 \ub098\ub204\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \ub730\uacfc \ubb3c, \ubc29\uacfc \ucd9c\uc785\uad6c\uc758 \uad00\uacc4\ub97c \ubcf4\uba74 \uac74\ucd95\uc774 \uc0ac\ub78c\uc758 \uc2dc\uac04\uc744 \uc5b4\ub5bb\uac8c \ubc30\uce58\ud588\ub294\uc9c0 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \ud2b9\uc815 \uae30\uad00\uc744 \ud604\ub300 \ub300\ud559\uacfc \ub611\uac19\uc774 \ubd80\ub974\uac70\ub098 \uac00\uc7a5 \uc624\ub798\ub418\uc5c8\ub2e4\ub294 \uacbd\uc7c1\uc73c\ub85c\ub9cc \uc124\uba85\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5b4\ub5a4 \ubc30\uc6c0\uc774 \uc5b4\ub5a4 \uc81c\ub3c4\uc640 \uacf5\uac04 \uc548\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc84c\ub294\uc9c0\uac00 \ub354 \uad6c\uccb4\uc801\uc778 \uc5ed\uc0ac\ub2e4. \uc5ed\uc0ac \uc0ac\uc9c4\uc5d0\ub294 \ucd2c\uc601 \uc21c\uac04\uc758 \uc120\ud0dd\ub3c4 \ub0a8\ub294\ub2e4. \uc0ac\ub78c\uc774 \uc801\uc740 \uae38\uc744 \uace8\ub790\ub294\uc9c0, \uac74\ucd95\uc744 \ud06c\uac8c \ubcf4\uc774\uac8c \ud588\ub294\uc9c0\uc5d0 \ub530\ub77c \uac19\uc740 \ub3c4\uc2dc\uac00 \ub2e4\ub974\uac8c \uc77d\ud790 \uc218 \uc788\ub2e4. \uc0ac\uc9c4\uc774 \uc2e4\uc81c \uc7a5\uba74\uc758 \uae30\ub85d\uc774\ub77c\ub294 \uc0ac\uc2e4\uacfc \ubaa8\ub4e0 \uc0dd\ud65c\uc744 \ub300\ud45c\ud55c\ub2e4\ub294 \ud310\ub2e8\uc740 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ucea1\uc158\uacfc \ucd9c\ud310 \uc2dc\uae30\ub97c \ud568\uaed8 \uc77d\ub294 \uc2b5\uad00\uc774 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uc0c1\uc5c5 \uacf5\uac04\uc758 \uc544\ub984\ub2e4\uc6c0\uc740 \ubb3c\uac74\uc744 \ub9cc\ub4e4\uace0 \ud30c\ub294 \ub178\ub3d9\uacfc \uc774\uc5b4\uc838 \uc788\ub2e4. \uc815\uad50\ud55c \uc7a5\uc2dd\uc774\ub098 \uc881\uc740 \uae38\uc774 \uc800\uc808\ub85c \uc720\uc9c0\ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc218\ub9ac\ud558\uace0 \uccad\uc18c\ud558\uace0 \uae30\uc220\uc744 \ubc30\uc6b0\ub294 \uc2dc\uac04\uc774 \ud544\uc694\ud588\ub2e4. \uac74\ucd95\ub9cc \uc624\ub798 \uc0b4\uc544\ub0a8\uc740 \uac83\uc774 \uc544\ub2c8\ub77c \uadf8\uac83\uc744 \uc774\uc6a9\ud560 \uc904 \uc544\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc9c0\uc2dd\ub3c4 \ub3c4\uc2dc\uc758 \uc911\uc694\ud55c \ubd80\ubd84\uc774\uc5c8\ub2e4. \ub3c4\uc2dc\uc758 \uc0b6\uc740 \uc5ec\ud589\uc790\uac00 \uac78\uc5b4\uac04 \uac70\ub9ac\uc5d0\uc11c \ubaa8\ub450 \ub4dc\ub7ec\ub098\uc9c0 \uc54a\ub294\ub2e4. \ubc14\uae65\uc5d0\uc11c \ub2eb\ud600 \ubcf4\uc774\ub294 \ubcbd \ub4a4\uc5d0\ub3c4 \uc0dd\ud65c \uacf5\uac04\uc774 \uc788\ub2e4. \uc5ec\ud589\uc790\ub294 \ub4e4\uc5b4\uac08 \uc218 \uc788\uc5c8\ub358 \uacf3\uacfc \ud5c8\ub77d\ubc1b\uc9c0 \ubabb\ud55c \uacf3 \uc0ac\uc774\uc5d0\uc11c \uc120\ud0dd\ub41c \uc7a5\uba74\uc744 \uae30\ub85d\ud55c\ub2e4. \ub530\ub77c\uc11c \uace8\ubaa9\uc758 \uc778\uc0c1\uc774 \uace7 \uc8fc\ubbfc\uc758 \uc0b6 \uc804\uccb4\ub77c\uace0 \ub9d0\ud560 \uc218 \uc5c6\ub2e4. \uae00\uacfc \uc0ac\uc9c4\uc5d0 \ubb34\uc5c7\uc774 \ub9ce\uc774 \ub4f1\uc7a5\ud558\uace0 \ubb34\uc5c7\uc774 \uac70\uc758 \ub4f1\uc7a5\ud558\uc9c0 \uc54a\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\ub294 \uac83\uc774 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uc0c1\uc778\uacfc \uc7a5\uc778, \uc9d1 \uc548\uc758 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uac19\uc740 \ube44\uc911\uc758 \ub9d0\ud560 \uae30\ud68c\uac00 \uc8fc\uc5b4\uc84c\ub294\uc9c0\ub3c4 \ud568\uaed8 \ubb3c\uc5b4\ubcfc \uc218 \uc788\ub2e4. \uc6cc\ud2bc\uc758 \ubc29\ubb38\uc740 \ud504\ub791\uc2a4 \ubcf4\ud638\ub839 \uc2dc\uae30\uc758 \uc77c\uc774\uc5c8\ub2e4. \uadf8\ub140\uac00 \uc774\ub3d9\ud558\uace0 \uc7a5\uc18c\ub97c \ubcfc \uc218 \uc788\uc5c8\ub358 \uc870\uac74\uc740 \ub2f9\uc2dc \uc2dd\ubbfc \uad8c\ub825\uacfc \ubb34\uad00\ud558\uc9c0 \uc54a\uc558\ub2e4. \uc5ec\ud589\uae30\uc758 \ubb18\uc0ac\uac00 \uc0dd\uc0dd\ud558\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8 \uc2dc\uc120\uc774 \uc911\ub9bd\uc801\uc774\ub77c\ub294 \ud310\ub2e8\uc740 \ub2e4\ub978 \ubb38\uc81c\ub2e4. \uadf8\ub140\uc758 \uae30\ub85d\uc5d0\ub294 \ubcf4\uc874\uacfc \ud1b5\uce58\uc5d0 \ub300\ud55c \ub2f9\uc2dc \uc720\ub7fd\uc778\uc758 \uac00\uce58 \ud310\ub2e8\ub3c4 \uc11e\uc5ec \uc788\ub2e4. \uc774\ub97c \uc624\ub298\uc758 \uac1d\uad00\uc801\uc778 \ud3c9\uac00\ub85c \uadf8\ub300\ub85c \uc62e\uae30\uc9c0 \uc54a\uc544\uc57c \ud55c\ub2e4. \uc624\ub798\ub41c \uc790\ub8cc\ub294 \uacfc\uac70 \ub3c4\uc2dc\ub97c \ubcf4\uc5ec \uc8fc\uba74\uc11c \ub3d9\uc2dc\uc5d0 \uadf8 \ub3c4\uc2dc\ub97c \ubc14\ub77c\ubcf4\ub358 \uc678\ubd80\uc778\uc758 \uc0dd\uac01\ub3c4 \ubcf4\uc5ec \uc8fc\ub294 \uc774\uc911\uc758 \uc99d\uac70\ub2e4. \uc61b \uc0ac\uc9c4\uc744 \ubcfc \ub54c \uc9c0\uae08\ub3c4 \ubaa8\ub4e0 \uac83\uc774 \uac19\uc744 \uac83\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uc9c0 \ub9d0\uc790. \uc0ac\uc9c4\uc774 \ucc0d\ud78c \ub4a4\uc5d0\ub3c4 \uc0ac\ub78c\uc740 \ud0dc\uc5b4\ub098\uace0 \uc774\uc8fc\ud558\uba70 \uc77c\ud558\ub294 \ubc29\uc2dd\uacfc \ub3c4\uc2dc\uc758 \uc870\uac74\uc740 \ub2ec\ub77c\uc84c\ub2e4. \uc624\ub798\ub41c \uac74\ucd95\uc774 \ub0a8\uc544 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uadf8 \uc548\uc758 \uc0b6\uc774 \uc815\uc9c0\ud588\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \ud398\uc2a4\ub97c \uc77d\ub294 \uc88b\uc740 \ucd9c\ubc1c\uc810\uc740 \uace8\ubaa9\uc758 \ubaa8\uc591\uc744 \uac10\ud0c4\ud55c \ub4a4 \uadf8 \uae38\uc774 \ubb34\uc5c7\uc744 \uc5f0\uacb0\ud588\ub294\uc9c0 \ubb3b\ub294 \uc77c\uc774\ub2e4. \uc2dc\uc7a5\uacfc \ubb3c, \ubc30\uc6c0\uacfc \uc9d1\uc774 \uc5f0\uacb0\ub418\ub294 \uad00\uacc4\ub97c \ub530\ub77c\uac00\uba74 \ub3c4\uc2dc\ub294 \uc774\uad6d\uc801\uc778 \ubc30\uacbd\uc5d0\uc11c \uad6c\uccb4\uc801\uc778 \uc0dd\ud65c\uc758 \uc7a5\uc18c\ub85c \ubc14\ub010\ub2e4. \uc624\ub798\ub41c \ub3c4\uc2dc\ub294 \ud604\uc7ac\uc758 \uc8fc\ubbfc\uc5d0\uac8c\ub3c4 \uacc4\uc18d \uc0ac\uc6a9\ud558\ub294 \uc0b6\uc758 \uc7a5\uc18c\ub77c\ub294 \uc0ac\uc2e4\uc744 \uc78a\uc9c0 \uc54a\uc544\uc57c \ud55c\ub2e4. \uc5ec\ud589\uc790\uc758 \uae30\ub85d\ub3c4 \uadf8\ub54c \ube44\ub85c\uc18c \ub354 \uc870\uc2ec\uc2a4\ub7fd\uace0 \ud48d\ubd80\ud558\uac8c \ud65c\uc6a9\ud560 \uc218 \uc788\ub2e4."}, {"id": "franklin-printer-club-and-library", "title": "\ubca4\uc800\ubbfc \ud504\ub7ad\ud074\ub9b0 \u2014 \uc778\uc1c4\uacf5\uc740 \uc65c \ud568\uaed8 \uc77d\uc744 \ucc45\uc744 \ubaa8\uc558\uc744\uae4c", "summary": "\ud504\ub7ad\ud074\ub9b0\uc758 \uc778\uc1c4\uc5c5\uacfc \uc900\ud1a0 \ubaa8\uc784, \uad6c\ub3c5 \ub3c4\uc11c\uad00\uacfc \ub355\ubaa9 \uae30\ub85d\uc744 \ud1b5\ud574 \ubc30\uc6c0\uc744 \uacf5\ub3d9\uc758 \uc77c\ub85c \ub9cc\ub4e0 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/franklin-printer-club-and-library/index.html", "image": "../media/franklin-printer-club-and-library.jpg", "alt": "\ub4a4\ud50c\ub808\uc2dc\uc758 \ucd08\uc0c1\uc744 \ubc14\ud0d5\uc73c\ub85c \ud55c \ud504\ub7ad\ud074\ub9b0\uc758 \ub178\ub144 \ud310\ud654", "text": "\ubca4\uc800\ubbfc \ud504\ub7ad\ud074\ub9b0 \u2014 \uc778\uc1c4\uacf5\uc740 \uc65c \ud568\uaed8 \uc77d\uc744 \ucc45\uc744 \ubaa8\uc558\uc744\uae4c \uc790\uc11c\uc804\uc5d0\uc11c \ub9cc\ub098\ub294 \ubc30\uc6c0\uc758 \ubaa8\uc784\uacfc \ub3c4\uc11c\uad00, \uc644\ubcbd\ud558\uc9c0 \ubabb\ud55c \uc2b5\uad00 \ud504\ub7ad\ud074\ub9b0\uc758 \uc778\uc1c4\uc5c5\uacfc \uc900\ud1a0 \ubaa8\uc784, \uad6c\ub3c5 \ub3c4\uc11c\uad00\uacfc \ub355\ubaa9 \uae30\ub85d\uc744 \ud1b5\ud574 \ubc30\uc6c0\uc744 \uacf5\ub3d9\uc758 \uc77c\ub85c \ub9cc\ub4e0 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc0ac\ub78c\ub4e4\uc774 \uac01\uc790 \uac00\uc9c4 \ucc45\uc744 \ud55c \ubc29\uc5d0 \ubaa8\uc544 \ub450\uba74 \ud1a0\ub860\ud560 \ub54c \ucc3e\uc544\ubcfc \uc218 \uc788\ub2e4. \ub2e4\ub978 \ud68c\uc6d0\uc758 \ucc45\ub3c4 \uc77d\uc744 \uc218 \uc788\uc73c\ub2c8 \uc801\uc740 \ucc45\uc73c\ub85c \ub354 \ub113\uac8c \ubc30\uc6b8 \uc218 \uc788\ub2e4. \ud504\ub7ad\ud074\ub9b0\uc758 \uc790\uc11c\uc804\uc5d0 \ub098\uc624\ub294 \ub3c4\uc11c\uad00\uc758 \ucd9c\ubc1c\uc740 \uc774\ub807\uac8c \uc18c\ubc15\ud558\ub2e4. \uadf8\ub294 \ub3c5\ub9bd\uacfc \uc678\uad50, \uacfc\ud559\uc73c\ub85c \ub110\ub9ac \uc54c\ub824\uc84c\uc9c0\ub9cc \ud55c\ub54c\ub294 \uc778\uc1c4 \uae30\uc220\ub85c \uc0b4\uc544\uac08 \uae38\uc744 \ucc3e\ub358 \uccad\ub144\uc774\uc5c8\ub2e4. \uadf8\uc758 \ucc45\uc744 \ub530\ub77c\uac00\uba74 \ud63c\uc790 \uc5f4\uc2ec\ud788 \uc77d\ub294 \uc0ac\ub78c\uc774 \ub2e4\ub978 \uc0ac\ub78c\uacfc \ud568\uaed8 \ubc30\uc6b8 \uc7a5\uce58\ub97c \ub9cc\ub4dc\ub294 \uacfc\uc815\uc774 \ubcf4\uc778\ub2e4. 1706\ub144 \ubcf4\uc2a4\ud134\uc5d0\uc11c \ud0dc\uc5b4\ub09c \ud504\ub7ad\ud074\ub9b0\uc740 \uc80a\uc5b4\uc11c \uc778\uc1c4 \uc77c\uc744 \ubc30\uc6e0\ub2e4. \uae00\uc790\ub97c \uc885\uc774 \uc704\uc5d0 \ub193\uace0 \ucc45\uacfc \uc2e0\ubb38\uc744 \ub9cc\ub4e4\uc5b4 \ub0b4\ub294 \uae30\uc220\uc740 \uc0dd\uacc4\uc758 \uc218\ub2e8\uc774\uc5c8\ub2e4. \uc77d\uace0 \uc4f0\uae30\ub97c \uc88b\uc544\ud55c \uadf8\uc5d0\uac8c\ub294 \uc0dd\uac01\uc774 \uc0ac\ub78c\uc5d0\uac8c \uc804\ub2ec\ub418\ub294 \uacfc\uc815\uc744 \ub9cc\ub098\ub294 \uc77c\uc774\uae30\ub3c4 \ud588\ub2e4. \uc790\uc11c\uc804\uc5d0\ub294 \ucc45\uc744 \uad6c\ud574 \uc77d\uace0 \ubb38\uc7a5\uc744 \uc5f0\uc2b5\ud55c \uc774\uc57c\uae30\uac00 \uc774\uc5b4\uc9c4\ub2e4. \ucc98\uc74c\ubd80\ud130 \ubaa8\ub4e0 \ubd84\uc57c\ub97c \uc544\ub294 \ud604\uc790\uac00 \ub4f1\uc7a5\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc77c\ud558\uace0 \ub3c8\uc744 \ub9c8\ub828\ud558\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc758 \ub3c4\uc6c0\uc744 \uc5bb\uc73c\uba70 \uc790\uae30 \ub2a5\ub825\uc744 \ub298\ub824 \uac00\ub294 \uc0ac\ub78c\uc774 \ub098\uc628\ub2e4. \uace0\ud5a5\uc744 \ub5a0\ub09c \ub4a4 \uadf8\ub294 \ud544\ub77c\ub378\ud53c\uc544\uc5d0 \ub3c4\ucc29\ud574 \uc77c\uc744 \ucc3e\uc558\ub2e4. \uc774\ud6c4 \uc601\uad6d \uc0dd\ud65c\uacfc \uadc0\ud658, \uc5ec\ub7ec \uc2dc\ud589\ucc29\uc624\ub97c \uac70\uccd0 \uc778\uc1c4\uc5c5\uc5d0\uc11c \uc790\ub9ac\ub97c \uc7a1\ub294\ub2e4. \uc790\uc11c\uc804\uc740 \ube75\uc744 \ub4e4\uace0 \ub0af\uc120 \uac70\ub9ac\ub97c \uac77\ub294 \ucd08\ub77c\ud55c \ubaa8\uc2b5\ub3c4 \ub0a8\uaca8 \ub193\ub294\ub2e4. \ub098\uc911\uc758 \uba85\uc131\uc744 \uba3c\uc800 \uc544\ub294 \ub3c5\uc790\uc5d0\uac8c\ub294 \uc774\ub7f0 \uc7a5\uba74\uc774 \ub354 \uc778\uc0c1\uc801\uc774\ub2e4. \uadf8\ub7ec\ub098 \uc131\uacf5\uc744 \ubaa8\ub450 \uc131\uc2e4\ud568 \ud558\ub098\uc758 \uacb0\uacfc\ub85c \uc77d\uae30\ubcf4\ub2e4\ub294 \uc77c\uc790\ub9ac\uc640 \uc2e0\uc6a9, \ub3d9\ub8cc\uc640 \ud6c4\uc6d0 \uad00\uacc4\uac00 \uc5b4\ub5bb\uac8c \uc5bd\ud614\ub294\uc9c0 \ud568\uaed8 \ubcf4\ub294 \ud3b8\uc774 \uadf8\uc758 \uc0dd\ud65c\uc744 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \uc774\ud574\ud558\uac8c \ud55c\ub2e4. \ud504\ub7ad\ud074\ub9b0\uc740 \uc9c0\uc778\ub4e4\uacfc \uc11c\ub85c\uc758 \ubc1c\uc804\uc744 \uc704\ud55c \uc900\ud1a0 \ubaa8\uc784\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \ud68c\uc6d0\ub4e4\uc740 \ub3c4\ub355\uacfc \uc815\uce58, \uc790\uc5f0\uc5d0 \uad00\ud55c \uc9c8\ubb38\uc744 \uac00\uc838\uc640 \ud1a0\ub860\ud558\uace0 \uc815\uae30\uc801\uc73c\ub85c \uae00\ub3c4 \uc77d\uc5c8\ub2e4. \uc218\uacf5\uc5c5\uc790\uc640 \uc5ec\ub7ec \uc9c1\uc5c5\uc758 \uc0ac\ub78c\ub4e4\uc774 \uc9c0\uc2dd\uc744 \ub098\ub204\ub294 \uc790\ub9ac\uc600\ub2e4. \uc790\uc11c\uc804\uc5d0\uc11c \uadf8\uac00 \uac15\uc870\ud558\ub294 \uac83\uc740 \uc0c1\ub300\ub97c \uaebe\ub294 \ub9d0\uc2f8\uc6c0\ubcf4\ub2e4 \ud568\uaed8 \uc9c4\uc2e4\uc744 \ucc3e\ub294 \ud0dc\ub3c4\ub2e4. \ud655\uc2e0\uc5d0 \ucc2c \ub2e8\uc815\uc774\ub098 \uc9c1\uc811\uc801\uc778 \ubc18\ubc15\uc73c\ub85c \uc5f4\uc744 \uc62c\ub9ac\uc9c0 \uc54a\ub3c4\ub85d \uaddc\uce59\ub3c4 \ub450\uc5c8\ub2e4. \uc88b\uc740 \ub300\ud654\ub294 \uc88b\uc740 \ub9c8\uc74c\ub9cc\uc73c\ub85c \uc720\uc9c0\ub418\uc9c0 \uc54a\ub294\ub2e4\uace0 \ubcf8 \uc148\uc774\ub2e4. \ubaa8\uc784\uc5d0\ub294 \ucc38\uace0\ud560 \ucc45\uc774 \ud544\uc694\ud588\ub2e4. \ud68c\uc6d0\ub4e4\uc774 \uac00\uc9c4 \ucc45\uc744 \ud55c\uacf3\uc5d0 \ubaa8\uc73c\uba74 \ud1a0\ub860 \uc911\uc5d0\ub3c4 \uc0b4\ud544 \uc218 \uc788\uace0 \uc11c\ub85c \ube4c\ub824 \uc77d\uc744 \uc218\ub3c4 \uc788\uc5c8\ub2e4. \uc9c0\uc2dd\uc758 \ubd80\uc871\uc744 \uac01\uc790 \ud63c\uc790 \uac10\ub2f9\ud558\uae30\ubcf4\ub2e4 \uac00\uc9c4 \uac83\uc744 \uc5f0\uacb0\ud558\ub824\ub294 \uad6c\uc0c1\uc774\uc5c8\ub2e4. \ud558\uc9c0\ub9cc \ucc45\uc744 \ud568\uaed8 \ub450\ub294 \ubc29\uc2dd\uc5d0\ub294 \uad00\ub9ac\uc640 \ubcf4\uad00\uc758 \ubb38\uc81c\uac00 \uc788\uc5c8\ub2e4. \uc88b\uc740 \uc758\ub3c4\ub9cc\uc73c\ub85c \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4\ub294 \uac83\uc744 \uacbd\ud5d8\ud55c \ub4a4 \ud504\ub7ad\ud074\ub9b0\uc740 \uad6c\ub3c5\uae08\uc744 \ubaa8\uc544 \ucc45\uc744 \uad6c\uc785\ud558\ub294 \ub354 \uc9c0\uc18d\uc801\uc778 \ubc29\ubc95\uc744 \uc0dd\uac01\ud55c\ub2e4. \ub3c4\uc11c\uad00\uc740 \uc0dd\uac01\ubcf4\ub2e4 \uc6b4\uc601\uc758 \ubb38\uc81c\uc5d0 \uac00\uae4c\uc6e0\ub2e4. \ud68c\uc6d0\ub4e4\uc774 \ucd08\uae30 \ube44\uc6a9\uacfc \uc815\uae30 \ud68c\ube44\ub97c \ub0b4\uba74 \uadf8 \ub3c8\uc73c\ub85c \ucc45\uc744 \uc0ac\uace0 \uaddc\uce59\uc5d0 \ub530\ub77c \uc774\uc6a9\ud560 \uc218 \uc788\uc5c8\ub2e4. \uc790\uc8fc \uc4f0\uc9c0 \uc54a\uc744 \ucc45\uae4c\uc9c0 \ud55c \uc0ac\ub78c\uc774 \ubaa8\ub450 \uc0b4 \ud544\uc694\uac00 \uc904\uc5b4\ub4e0\ub2e4. \uc77d\uace0 \uc2f6\uc740 \uc0ac\ub78c\uc774 \uc790\uc6d0\uc744 \ubaa8\uc544 \uc811\uadfc\uc758 \ud3ed\uc744 \ub113\ud78c \uac83\uc774\ub2e4. \ub2e4\ub9cc \uc774\uac83\uc744 \uc624\ub298\ub0a0 \ub204\uad6c\ub098 \ubb34\ub8cc\ub85c \uc774\uc6a9\ud558\ub294 \uacf5\uacf5\ub3c4\uc11c\uad00\uacfc \uadf8\ub300\ub85c \uac19\ub2e4\uace0 \ubcfc \uc218\ub294 \uc5c6\ub2e4. \ud68c\uc6d0\uacfc \ube44\uc6a9\uc758 \uc870\uac74\uc774 \uc788\uc5c8\ub2e4. \uacf5\ub3d9\uc758 \ubc30\uc6c0\uc774 \ub113\uc5b4\uc84c\ub2e4\ub294 \uc758\ubbf8\uc640 \uadf8 \ud61c\ud0dd\uc744 \ub204\ub9b4 \uc218 \uc788\uc5c8\ub358 \ubc94\uc704\ub294 \ud568\uaed8 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uad6c\ub3c5\uc744 \ubd80\ud0c1\ud558\ub358 \uadf8\ub294 \uc790\uae30 \uba85\uc131\uc744 \ub192\uc774\ub824\ub294 \uacc4\ud68d\uc73c\ub85c \ubcf4\uc774\uba74 \uc0ac\ub78c\ub4e4\uc774 \ud611\ub825\uc744 \uaebc\ub9b4 \uc218 \uc788\uc74c\uc744 \ub290\uaf08\ub2e4\uace0 \uc801\uc5c8\ub2e4. \uadf8\ub798\uc11c \uc5ec\ub7ec \uce5c\uad6c\uc758 \ub73b\uc744 \ub300\uc2e0 \uc804\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c \uc81c\uc548\ud588\ub2e4. \uc0ac\ub78c\ub4e4\uc758 \uc790\ubd80\uc2ec\uacfc \uad00\uacc4\ub3c4 \uc6b4\uc601\uc758 \uc870\uac74\uc774\uc5c8\ub2e4. \uc774 \ub300\ubaa9\uc758 \ud504\ub7ad\ud074\ub9b0\uc740 \uc774\uc0c1\ub9cc \ub9d0\ud558\ub294 \uc0ac\ub78c\uc774 \uc544\ub2c8\ub2e4. \uc88b\uc740 \uc81c\uc548\uc774 \uc2e4\uc81c\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc9c0\ub824\uba74 \uc5b4\ub5a4 \ub9d0\uacfc \uc808\ucc28\uac00 \ud544\uc694\ud55c\uc9c0 \uad00\ucc30\ud55c\ub2e4. \uc790\uae30 \uc774\ub984\uc744 \ub4dc\ub7ec\ub0b4\ub294 \ub9cc\uc871\ubcf4\ub2e4 \uc77c\uc744 \uc131\uc0ac\uc2dc\ud0a4\ub294 \uacb0\uacfc\ub97c \ud0dd\ud55c \uacbd\ud5d8\uc73c\ub85c \ud68c\uace0\ud55c\ub2e4. \uc790\uc2e0\uc758 \uc2b5\uad00\ub3c4 \uae30\ub85d\uc73c\ub85c \ub2e4\ub4ec\uc73c\ub824 \ud588\ub2e4. \uc808\uc81c\uc640 \uce68\ubb35, \uc9c8\uc11c \ub4f1 \uc5f4\uc138 \uac00\uc9c0 \ub355\ubaa9\uc744 \uc815\ud558\uace0 \uc798 \uc9c0\ud0a4\uc9c0 \ubabb\ud55c \uc77c\uc744 \ud45c\uc2dc\ud588\ub2e4. \ub9c8\uc74c\uba39\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ud589\ub3d9\uc774 \ubc14\ub00c\uc9c0\ub294 \uc54a\ub294\ub2e4\uace0 \ubcf8 \uac83\uc774\ub2e4. \ud558\uc9c0\ub9cc \uc644\ubcbd\ud55c \uc0ac\ub78c\uc774 \ub418\uc5c8\ub2e4\ub294 \uacb0\ub860\uc740 \ub098\uc624\uc9c0 \uc54a\ub294\ub2e4. \ud2b9\ud788 \uc9c8\uc11c \uc788\uac8c \uc0b4\ub824\ub294 \ub178\ub825\uc740 \ub73b\ub300\ub85c \ub418\uc9c0 \uc54a\uc558\ub2e4. \uc2e4\ud328\ud55c \uc790\ub9ac\ub97c \ub0a8\uae30\ub294 \uae30\ub85d\uc740 \uc601\uc6c5\uc758 \uc790\ub791\ubcf4\ub2e4 \uac00\uae4c\uc774 \ub290\uaef4\uc9c4\ub2e4. \uacc4\ud68d\uacfc \uc2e4\uc81c \uc0dd\ud65c \uc0ac\uc774\uc5d0\ub294 \uacc4\uc18d \uac04\uaca9\uc774 \uc788\uc5c8\ub2e4. \uc774 \ucc45\uc740 \ub2f9\uc2dc\uc758 \ub9e4\uc77c\uc744 \ube60\uc9d0\uc5c6\uc774 \uc801\uc740 \uc77c\uc9c0\uac00 \uc544\ub2c8\ub2e4. \ub098\uc911\uc758 \ud504\ub7ad\ud074\ub9b0\uc774 \uc790\uc2e0\uc758 \uacbd\ud5d8\uc744 \uace8\ub77c \ub3c5\uc790\uc5d0\uac8c \uc124\uba85\ud55c \uae00\uc774\ub2e4. \uadf8\uac00 \uc911\uc694\ud558\uac8c \uc5ec\uae34 \uc131\uc2e4\uacfc \uc2e4\uc6a9, \ud611\ub825\uc758 \uac00\uce58\uac00 \uc0ac\uac74\uc758 \ubc30\uce58\uc5d0\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \ub530\ub77c\uc11c \uc790\uc11c\uc804\uc758 \ud3c9\uac00\ub97c \uadf8 \uc2dc\ub300 \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \uacbd\ud5d8\uc73c\ub85c \ub113\ud788\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uadf8\uc758 \uc131\uacf5\uacfc \uc81c\ub3c4\uac00 \ub2f9\uc2dc\uc5d0 \uc874\uc7ac\ud55c \ucc28\ubcc4\uacfc \ubd88\ud3c9\ub4f1\uc744 \uc5c6\uc574\ub2e4\ub294 \ub73b\ub3c4 \uc544\ub2c8\ub2e4. \ud55c \uc0ac\ub78c\uc758 \ubc30\uc6c0\uacfc \uc0ac\ud68c \uc804\uccb4\uc758 \uae30\ud68c\ub97c \uad6c\ubd84\ud558\uba70 \uc77d\uc744 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \ucd08\uc0c1\uc740 \ub4a4\ud50c\ub808\uc2dc\uc758 \uadf8\ub9bc\uc744 \ubc14\ud0d5\uc73c\ub85c \ud55c \ud6c4\ub300 \ud310\ud654\ub2e4. \ub3c4\uc11c\uad00\uc744 \uad6c\uc0c1\ud558\ub358 \uccad\ub144\uc758 \ud604\uc7a5 \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \uc775\uc219\ud55c \ub178\ub144\uc758 \uc5bc\uad74 \ub4a4\uc5d0\uc11c \ucc45\uc744 \uad6c\ud558\uace0 \uc0ac\ub78c\uc744 \ubaa8\uc73c\ub358 \uc2dc\uac04\uc744 \uc0c1\uc0c1\ud574 \ubcfc \ucd9c\ubc1c\uc810\uc774\ub2e4. \ud504\ub7ad\ud074\ub9b0\uc758 \uc774\uc57c\uae30\uc5d0\uc11c \uac00\uc838\uac08 \uac83\uc740 \ub0a8\ubcf4\ub2e4 \ub354 \ub9ce\uc774 \uc77d\uc73c\ub77c\ub294 \uc555\ubc15\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uc9c8\ubb38\uc744 \ud568\uaed8 \ub098\ub20c \uc790\ub9ac, \ucc45\uc744 \ud568\uaed8 \uc4f8 \uaddc\uce59, \uc2e4\ud328\ub97c \ub3cc\uc544\ubcfc \uae30\ub85d\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4\ub294 \uc0dd\uac01\uc774\ub2e4. \uac1c\uc778\uc758 \ubc30\uc6c0\uc740 \uc8fc\ubcc0\uc758 \uc7a5\uce58\ub97c \ubc14\uafc0 \ub54c \ub354 \uba40\ub9ac \uc774\uc5b4\uc9c8 \uc218 \uc788\uc5c8\ub2e4."}, {"id": "garibaldi-1860-thousand-monarchy-and-unification", "title": "\uac00\ub9ac\ubc1c\ub514\uc758 \ucc9c\uc778\ub300 \u2014 \ubd89\uc740 \uc154\uce20\ub294 \uc5b4\ub5bb\uac8c \uc655\uad6d\uc758 \uc9c0\ub3c4\ub97c \ubc14\uafb8\uc5c8\uc744\uae4c", "summary": "\uc2dc\uce60\ub9ac\uc544\uc758 \ucc38\uc5ec\uc640 \uad70\uc8fc\uc758 \uc120\ud0dd, \ud1b5\uc77c \ub4a4\uc5d0 \ub0a8\uc740 \uacfc\uc81c\uc758 \ubc30\uacbd\uacfc \uc804\uac1c, \uc774\ud6c4\uc758 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/garibaldi-1860-thousand-monarchy-and-unification/index.html", "image": "../media/garibaldi-1860-thousand-monarchy-and-unification.jpg", "alt": "\uc5ed\uc0ac \ucd9c\ud310\ubb3c\uc5d0 \uc2e4\ub9b0 \uc8fc\uc138\ud398 \uac00\ub9ac\ubc1c\ub514\uc758 \ucd08\uc0c1 \ub3c4\ud310", "text": "\uac00\ub9ac\ubc1c\ub514\uc758 \ucc9c\uc778\ub300 \u2014 \ubd89\uc740 \uc154\uce20\ub294 \uc5b4\ub5bb\uac8c \uc655\uad6d\uc758 \uc9c0\ub3c4\ub97c \ubc14\uafb8\uc5c8\uc744\uae4c \uc2dc\uce60\ub9ac\uc544\uc758 \ucc38\uc5ec\uc640 \uad70\uc8fc\uc758 \uc120\ud0dd, \ud1b5\uc77c \ub4a4\uc5d0 \ub0a8\uc740 \uacfc\uc81c \uc2dc\uce60\ub9ac\uc544\uc758 \ucc38\uc5ec\uc640 \uad70\uc8fc\uc758 \uc120\ud0dd, \ud1b5\uc77c \ub4a4\uc5d0 \ub0a8\uc740 \uacfc\uc81c\uc758 \ubc30\uacbd\uacfc \uc804\uac1c, \uc774\ud6c4\uc758 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc57d \ucc9c \uba85\uc73c\ub85c \uc2dc\uc791\ud55c \uc6d0\uc815\ub300\uac00 \uc655\uad6d \ud558\ub098\uc758 \ubd95\uad34\uc640 \uc774\ud0c8\ub9ac\uc544 \ud1b5\uc77c\uc758 \uc18d\ub3c4\ub97c \ubc14\uafb8\uc5c8\ub2e4. 1860\ub144 \uac00\ub9ac\ubc1c\ub514\uc758 \uc2dc\uce60\ub9ac\uc544 \uc6d0\uc815\uc740 \uc774\ub7f0 \ubb38\uc7a5\uc73c\ub85c \uae30\uc5b5\ub41c\ub2e4. \ud558\uc9c0\ub9cc \uc22b\uc790\uac00 \uc791\uc740 \ubd80\ub300\uc758 \uc6a9\ub9f9\ub9cc\uc73c\ub85c \ub0a8\ubd80 \uc804\uccb4\uc758 \ubcc0\ud654\ub97c \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud604\uc9c0\uc758 \ubd88\ub9cc\uacfc \ucc38\uc5ec, \ubd81\ubd80 \uc655\uad6d\uc758 \uacc4\uc0b0, \uc720\ub7fd \uc5f4\uac15\uc758 \uad00\uc2ec\uc774 \ud568\uaed8 \uc6c0\uc9c1\uc600\ub2e4. \ubd89\uc740 \uc154\uce20\uc758 \ud589\uc9c4\uc740 \ud1b5\uc77c\uc758 \uc774\uc57c\uae30\uc778 \ub3d9\uc2dc\uc5d0 \ud1b5\uc77c \ub4a4 \ubb34\uc5c7\uc744 \ubc14\uafc0 \uac83\uc778\uac00\ub77c\ub294 \uc9c8\ubb38\uc758 \uc2dc\uc791\uc774\uc5c8\ub2e4. 19\uc138\uae30 \uc911\ubc18 \uc774\ud0c8\ub9ac\uc544\ubc18\ub3c4\uc5d0\ub294 \uc5ec\ub7ec \uc815\uce58 \uc138\ub825\uc774 \ub098\ub258\uc5b4 \uc788\uc5c8\ub2e4. \ub0a8\ubd80\uc640 \uc2dc\uce60\ub9ac\uc544\ub294 \ubd80\ub974\ubd09 \uc655\uc870\uc758 \uc591\uc2dc\uce60\ub9ac\uc544 \uc655\uad6d \uc544\ub798 \uc788\uc5c8\uace0, \ubd81\ubd80\uc758 \uc0ac\ub974\ub370\ub0d0 \uc655\uad6d\uc740 \ud1b5\uc77c \uacfc\uc815\uc5d0\uc11c \uc601\ud5a5\ub825\uc744 \ub113\ud788\uace0 \uc788\uc5c8\ub2e4. \uac19\uc740 \uc774\ud0c8\ub9ac\uc544\ub77c\ub294 \ub9d0\uc774 \uace7 \ud558\ub098\uc758 \uc815\ubd80\ub97c \ub73b\ud558\uc9c0\ub294 \uc54a\uc558\ub2e4. \ubd81\ubd80\uc758 \uc815\uce58\uac00 \uce74\ubcf4\uc6b0\ub974\ub294 \uc678\uad50\uc640 \uc804\uc7c1\uc744 \uc870\uc808\ud558\uba70 \uc655\uad6d\uc758 \ud655\ub300\ub97c \ucd94\uc9c4\ud588\ub2e4. \ubc18\uba74 \uac00\ub9ac\ubc1c\ub514\ub294 \ubbfc\uc911\uc801 \uba85\uc131\uacfc \uc790\uc6d0\ubcd1\uc758 \ud589\ub3d9\ub825\uc744 \uac00\uc9c4 \uc778\ubb3c\uc774\uc5c8\ub2e4. \ud1b5\uc77c\uc774\ub77c\ub294 \ud070 \ubc29\ud5a5\uc774 \uacb9\uccd0\ub3c4 \ubc29\ubc95\uacfc \ucd5c\uc885 \ubaa9\ud45c\uae4c\uc9c0 \ub298 \uac19\uc558\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. 1860\ub144 5\uc6d4 \uac00\ub9ac\ubc1c\ub514 \uc77c\ud589\uc740 \ubc14\ub2e4\ub97c \uac74\ub108 \uc2dc\uce60\ub9ac\uc544\uc758 \ub9c8\ub974\uc0b4\ub77c\uc5d0 \uc0c1\ub959\ud588\ub2e4. \ucc9c\uc778\ub300\ub77c\ub294 \uc774\ub984\uc740 \ucd9c\ubc1c\ud55c \uc790\uc6d0\ubcd1 \uc9d1\ub2e8\uc744 \uac00\ub9ac\ud0a4\ub294 \uc0c1\uc9d5\uc774 \ub418\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \uc774\ud6c4\uc758 \uc804\ud22c\uc640 \ud589\uc9c4\uc744 \ucc98\uc74c\uc758 \uc57d \ucc9c \uba85\uc774 \ub05d\uae4c\uc9c0 \ud63c\uc790 \uc218\ud589\ud55c \uac83\uc73c\ub85c \uc774\ud574\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ubcd1\ub825\uc740 \ud604\uc9c0 \ucc38\uc5ec\uc640 \uc9c0\uc6d0\uc744 \ud1b5\ud574 \ucee4\uc84c\ub2e4. \uc2dc\uce60\ub9ac\uc544\uc5d0\ub294 \ubd80\ub974\ubd09 \uc9c0\ubc30\uc5d0 \ub300\ud55c \ubc18\uac10\uacfc \uc9c0\uc5ed\uc758 \uc815\uce58\uc801 \uc694\uad6c\uac00 \uc774\ubbf8 \uc788\uc5c8\ub2e4. \uc678\ubd80\uc5d0\uc11c \uc628 \uc6d0\uc815\ub300\uac00 \ud589\ub3d9\ud560 \uc218 \uc788\uc5c8\ub358 \uc870\uac74\uc740 \ubc14\ub85c \uadf8 \ud604\uc9c0 \uc0ac\ud68c\uc5d0 \ub193\uc5ec \uc788\uc5c8\ub2e4. \ud1b5\uc77c\uc758 \uc601\uc6c5\ub2f4\uc740 \uc774 \ud611\ub825\uc790\ub4e4\uc744 \ubc30\uacbd\uc73c\ub85c \ubc00\uc5b4\ub0b4\uae30 \uc27d\ub2e4. \ub9c8\ub974\uc0b4\ub77c \ud56d\uad6c\uc5d0 \uc678\uad6d \ud568\uc120\uc774 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\ub3c4 \uc6d0\uc815\ub300\uc758 \uc131\uacf5\uc744 \uc124\uba85\ud560 \ub54c \uc790\uc8fc \ub4f1\uc7a5\ud55c\ub2e4. \ud558\uc9c0\ub9cc \uadf8\uac83\uc744 \uc5f4\uac15\uc774 \uc804\ud22c \uc804\uccb4\ub97c \ub300\uc2e0 \uc218\ud589\ud588\ub2e4\ub294 \ub73b\uc73c\ub85c \ubc14\uafb8\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uad6d\uc81c \uc815\uc138\uac00 \ud589\ub3d9\uc758 \uc5ec\uc9c0\ub97c \uc8fc\ub294 \uac83\uacfc \ud604\uc7a5\uc5d0\uc11c \ubcd1\ub825\uacfc \ubcf4\uae09\uc744 \ud655\ubcf4\ud558\ub294 \uc77c\uc740 \uc11c\ub85c \ub2e4\ub978 \uc870\uac74\uc774\uc5c8\ub2e4. \uce7c\ub77c\ud0c0\ud53c\ubbf8\uc758 \uc804\ud22c\ub97c \uac70\uccd0 \uac00\ub9ac\ubc1c\ub514\uc758 \uc138\ub825\uc740 \ud314\ub808\ub974\ubaa8\ub85c \uc9c4\uc785\ud588\ub2e4. \ub3c4\uc2dc \uc548\uc758 \uc800\ud56d\uacfc \uad70\ub300\uc758 \ud589\ub3d9, \ud611\uc0c1\uc740 \ud568\uaed8 \uc0ac\ud0dc\ub97c \uc6c0\uc9c1\uc600\ub2e4. \uc131\ubcbd\uc774\ub098 \uac70\ub9ac\ub97c \ucc28\uc9c0\ud558\ub294 \uc77c\uacfc \uc8fc\ubbfc\uc774 \uc0c8\ub85c\uc6b4 \uad8c\ub825\uc744 \ubc1b\uc544\ub4e4\uc774\ub294 \uc77c\uc740 \uac19\uc740 \ubb38\uc81c\uac00 \uc544\ub2c8\uc5c8\ub2e4. \uc2dc\uce60\ub9ac\uc544\uc5d0\uc11c \uac00\ub9ac\ubc1c\ub514\ub294 \ube44\ud1a0\ub9ac\uc624 \uc5d0\ub9c8\ub204\uc5d8\ub808\uc758 \uc774\ub984\uc73c\ub85c \uad8c\ub825\uc744 \ud589\uc0ac\ud588\ub2e4. \uacf5\ud654\uc8fc\uc758 \uacbd\ub825\uc744 \uac00\uc9c4 \uc778\ubb3c\uc774 \uad70\uc8fc\uc758 \uc774\ub984\uc744 \ub0b4\uc138\uc6b4 \ub370\uc5d0\ub294 \ud1b5\uc77c\uc774\ub77c\ub294 \ubaa9\ud45c\ub97c \uc6b0\uc120\ud558\ub294 \ud604\uc2e4\uc801 \uc120\ud0dd\uc774 \uc788\uc5c8\ub2e4. \ud601\uba85\uc801\uc778 \ub3d9\uc6d0\uacfc \uc655\uad8c\uc758 \uc5b8\uc5b4\uac00 \ud55c \ud589\uc9c4 \uc548\uc5d0\uc11c \uacf5\uc874\ud55c \uc148\uc774\ub2e4. \ud604\uc9c0 \uc8fc\ubbfc\ub4e4\uc774 \uae30\ub300\ud55c \ubcc0\ud654\ub294 \uc911\uc559 \uc815\uce58\uc758 \uc9c0\ub3c4\uc640 \uaf2d \uc77c\uce58\ud558\uc9c0 \uc54a\uc558\ub2e4. \ub18d\ubbfc\uc5d0\uac8c \uc911\uc694\ud55c \uac83\uc740 \ud1a0\uc9c0\uc640 \ubd80\ub2f4, \uc9c0\uc5ed\uc758 \uad8c\ub825 \uad00\uacc4\uc77c \uc218 \uc788\uc5c8\ub2e4. \uc655\uc870\ub97c \ubc14\uafbc\ub2e4\ub294 \uc18c\uc2dd\uc774 \uc0dd\uacc4\ub97c \ubc14\uafc0 \uac83\uc774\ub77c\ub294 \uae30\ub300\ub97c \ubd88\ub7ec\uc77c\uc73c\ucf1c\ub3c4 \uadf8 \uc57d\uc18d\uc774 \uc790\ub3d9\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\uc9c0\ub294 \uc54a\uc558\ub2e4. \uc0c8\ub85c\uc6b4 \uc9c0\ubc30 \uc138\ub825\uc740 \uc9c8\uc11c\ub97c \uc720\uc9c0\ud558\ub824 \ud588\uace0 \uc0ac\ud68c\uc801 \uac08\ub4f1\uc740 \uacc4\uc18d\ub418\uc5c8\ub2e4. \ub530\ub77c\uc11c \uc8fc\ubbfc\uc758 \ucc38\uc5ec\ub97c \ubaa8\ub450 \ubbfc\uc871 \ud1b5\uc77c\uc5d0 \ub300\ud55c \ub3d9\uc77c\ud55c \uc5f4\ub9dd\uc73c\ub85c \uc124\uba85\ud558\uae30 \uc5b4\ub835\ub2e4. \uac19\uc740 \ud3b8\uc5d0\uc11c \ubd80\ub974\ubd09 \uc655\uc870\uc5d0 \ubc18\ub300\ud574\ub3c4 \uadf8\ub2e4\uc74c\uc5d0 \uc6d0\ud558\ub294 \uc0ac\ud68c\uc758 \ubaa8\uc2b5\uc740 \uc11c\ub85c \ub2ec\ub790\ub2e4. \uc2dc\uce60\ub9ac\uc544\ub97c \uc7a5\uc545\ud55c \ub4a4 \uac00\ub9ac\ubc1c\ub514\ub294 \uc774\ud0c8\ub9ac\uc544 \ubcf8\ud1a0\ub85c \uac74\ub108\uac14\ub2e4. \ubd80\ub974\ubd09 \uc655\uc870\uc758 \ud1b5\uce58 \uae30\ubc18\uc740 \ud754\ub4e4\ub838\uace0 \uadf8\ub294 \ub098\ud3f4\ub9ac\ub85c \ub4e4\uc5b4\uac14\ub2e4. \uc791\uc740 \uc6d0\uc815\uc774 \ud070 \ubcc0\ud654\ub97c \ub0b3\uc740 \ub370\uc5d0\ub294 \uc0c1\ub300 \uad8c\ub825\uc758 \uc704\uae30\uc640 \uc9c0\uc9c0 \uae30\ubc18\uc758 \uc57d\ud654\ub3c4 \uc911\uc694\ud588\ub2e4. \uc131\uacf5\uc774 \ucee4\uc9c8\uc218\ub85d \ubd81\ubd80 \uc815\ubd80\uc758 \uac71\uc815\ub3c4 \ucee4\uc84c\ub2e4. \uac00\ub9ac\ubc1c\ub514\uac00 \ub85c\ub9c8\ub97c \ud5a5\ud574 \ub354 \uc9c4\uaca9\ud55c\ub2e4\uba74 \uad50\ud669\uc744 \ub458\ub7ec\uc2fc \uad6d\uc81c \uad00\uacc4\uc640 \ucda9\ub3cc\ud560 \uc218 \uc788\uc5c8\ub2e4. \uce74\ubcf4\uc6b0\ub974\uc5d0\uac8c\ub294 \ud1b5\uc77c\uc758 \uc18d\ub3c4\ub97c \ub192\uc774\ub294 \uc77c\ubfd0 \uc544\ub2c8\ub77c \uadf8 \ubc29\ud5a5\uc744 \uc655\uad6d\uc758 \ud1b5\uc81c \uc548\uc5d0 \ub450\ub294 \uc77c\ub3c4 \ud544\uc694\ud588\ub2e4. \uac00\ub9ac\ubc1c\ub514\uc640 \ube44\ud1a0\ub9ac\uc624 \uc5d0\ub9c8\ub204\uc5d8\ub808\uc758 \ud14c\uc544\ub178 \ub9cc\ub0a8\uc740 \ub450 \ud750\ub984\uc758 \uacb0\ud569\uc744 \uc0c1\uc9d5\ud55c\ub2e4. \uac00\ub9ac\ubc1c\ub514\ub294 \uc790\uc2e0\uc758 \uad70\uc0ac\uc801 \uc131\uacfc\ub97c \ubc14\ud0d5\uc73c\ub85c \ubcc4\ub3c4\uc758 \uad6d\uac00\ub97c \uc138\uc6b0\uae30\ubcf4\ub2e4 \uc655\uad6d \uc911\uc2ec\uc758 \ud1b5\uc77c\ub85c \uc774\uc5b4\uc9c0\ub294 \uae38\uc744 \ubc1b\uc544\ub4e4\uc600\ub2e4. \ub0a8\ubd80\uc758 \ud3b8\uc785\uc5d0\ub294 \uc8fc\ubbfc\ud22c\ud45c\ub3c4 \ud65c\uc6a9\ub418\uc5c8\ub2e4. \ub2e4\ub9cc \ub2f9\uc2dc\uc758 \ud22c\ud45c\ub97c \uc624\ub298\ub0a0\uc758 \ubcf4\ud1b5\uc120\uac70\uc640 \uac19\uc740 \uc870\uac74\uc73c\ub85c \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc120\ud0dd\uc758 \ubc94\uc704\uc640 \uc815\uce58\uc801 \ubd84\uc704\uae30, \ucc38\uc5ec\uc758 \uc870\uac74\uc744 \ud568\uaed8 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. 1861\ub144 \uc774\ud0c8\ub9ac\uc544 \uc655\uad6d\uc774 \ucd9c\ubc94\ud588\uc9c0\ub9cc \ubca0\ub124\uce58\uc544\uc640 \ub85c\ub9c8\uae4c\uc9c0 \uc774\ubbf8 \ubaa8\ub450 \ud3ec\ud568\ub41c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uac00\ub9ac\ubc1c\ub514\uac00 \ubb3c\ub7ec\ub09c \uc7a5\uba74\uc740 \uc601\uc6c5\uc758 \uacb8\uc190\ub9cc\uc73c\ub85c \uc77d\uc744 \uc218\ub3c4 \uc5c6\ub2e4. \uc5b4\ub290 \uc815\ubd80\uac00 \uad70\ub300\uc640 \uc7ac\uc815, \uad6d\uc81c\uc801 \uc2b9\uc778\uc744 \uc774\uc5b4\ubc1b\uc744 \uac83\uc778\uc9c0\uac00 \uac78\ub9b0 \uc815\uce58\uc801 \uacb0\uc815\uc774\uc5c8\ub2e4. \uc778\ubb3c\uc758 \uc131\uaca9\uacfc \uad6d\uac00\ub97c \uc6b4\uc601\ud560 \uad6c\uc870\ub97c \ud568\uaed8 \ubcf4\uc544\uc57c \ud1b5\uc77c\uc774 \uc655\uad6d\uc73c\ub85c \uadc0\uacb0\ub41c \uacfc\uc815\uc744 \uc124\uba85\ud560 \uc218 \uc788\ub2e4. \ud1b5\uc77c\uc740 \uad6d\uacbd\uacfc \uc815\ubd80\ub97c \ubc14\uafb8\uc5c8\uc9c0\ub9cc \uc9c0\uc5ed \uac04\uc758 \uaca9\ucc28\uc640 \uc0ac\ud68c\uc801 \uac08\ub4f1\uc744 \ub05d\ub0b4\uc9c0\ub294 \ubabb\ud588\ub2e4. \uac00\ub9ac\ubc1c\ub514\uc758 \uc6d0\uc815\uc744 \uc77d\ub294 \uc7ac\ubbf8\ub294 \uae30\uc801 \uac19\uc740 \uc2b9\ub9ac\uc5d0\uc11c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc790\uc6d0\ubcd1\uc758 \ub3d9\uc6d0\uacfc \ud604\uc9c0\uc758 \uae30\ub300\uac00 \uc5b4\ub5bb\uac8c \uc655\uad6d\uc758 \uc81c\ub3c4\ub85c \uc774\uc5b4\uc84c\ub294\uc9c0 \ub530\ub77c\uac08 \ub54c \ub354 \uae34 \uc5ed\uc0ac\uac00 \ubcf4\uc778\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uc5ed\uc0ac \ucd9c\ud310\ubb3c\uc5d0 \uc2e4\ub9b0 \uac00\ub9ac\ubc1c\ub514\uc758 \ucd08\uc0c1 \ub3c4\ud310\uc774\ub2e4. \ub9c8\ub974\uc0b4\ub77c \uc0c1\ub959\uc774\ub098 \ud14c\uc544\ub178 \ub9cc\ub0a8\uc744 \ud604\uc7a5\uc5d0\uc11c \ucd2c\uc601\ud55c \uc0ac\uc9c4\uc774 \uc544\ub2c8\ub2e4. \uc601\uc6c5\uc758 \uc5bc\uad74\uc744 \ubc14\ub77c\ubcf4\ub418, \uadf8\uac00 \uc6c0\uc9c1\uc77c \uc218 \uc788\uc5c8\ub358 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc120\ud0dd\uacfc \ud1b5\uc77c \ub4a4\uc5d0\ub3c4 \ub0a8\uc740 \uacfc\uc81c\ub97c \ud568\uaed8 \ub5a0\uc62c\ub824 \ubcfc \uc218 \uc788\ub2e4."}, {"id": "great-wall-gates-and-political-choices", "title": "\ub9cc\ub9ac\uc7a5\uc131 \u2014 \ubcbd\uc774 \uc788\uc5b4\ub3c4 \uc5ed\uc0ac\ub294 \ubb38\uc744 \ud1b5\ud574 \uc6c0\uc9c1\uc600\ub2e4", "summary": "\uc5ec\ub7ec \uc2dc\ub300\uc758 \ubc29\uc5b4\ubcbd\uacfc \uc0ac\ub78c\u00b7\uad00\ubb38, 1644\ub144\uc758 \uc815\uce58\uc801 \uc120\ud0dd\uc73c\ub85c \uc7a5\uc131\uc758 \uae30\ub2a5\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/great-wall-gates-and-political-choices/index.html", "image": "../media/great-wall-gates-and-political-choices.png", "alt": "\uc0b0 \ub2a5\uc120\uc758 \uc131\ubcbd\uacfc \uad00\ubb38\uc73c\ub85c \ud5a5\ud558\ub294 \uc0ac\ub78c\ub4e4\uc744 \uadf8\ub9b0 \ub9cc\ub9ac\uc7a5\uc131 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ub9cc\ub9ac\uc7a5\uc131 \u2014 \ubcbd\uc774 \uc788\uc5b4\ub3c4 \uc5ed\uc0ac\ub294 \ubb38\uc744 \ud1b5\ud574 \uc6c0\uc9c1\uc600\ub2e4 \ud558\ub098\uc758 \uac74\ubb3c\uc774 \uc544\ub2cc \uc5ec\ub7ec \uc2dc\ub300\uc758 \ud754\uc801\uc5d0\uc11c \uc2dc\uc791\ud558\ub294 \uc5ed\uc0ac\uc640 \uc791\ud488 \uc77d\uae30 \uc5ec\ub7ec \uc2dc\ub300\uc758 \ubc29\uc5b4\ubcbd\uacfc \uc0ac\ub78c\u00b7\uad00\ubb38, 1644\ub144\uc758 \uc815\uce58\uc801 \uc120\ud0dd\uc73c\ub85c \uc7a5\uc131\uc758 \uae30\ub2a5\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ub9cc\ub9ac\uc7a5\uc131\uc744 \ud55c \ud669\uc81c\uac00 \uc138\uc6b4 \ub05d\uc5c6\ub294 \ubcbd\uc73c\ub85c \uae30\uc5b5\ud558\uba74 \uc911\uc694\ud55c \uc5ed\uc0ac\uac00 \uc0ac\ub77c\uc9c4\ub2e4. \uc5ec\ub7ec \uc2dc\ub300\uc5d0 \ub2e4\ub978 \ubaa9\uc801\uacfc \uc7ac\ub8cc\ub85c \ub9cc\ub4e4\uc5b4\uc9c0\uace0 \uace0\uccd0\uc9c4 \ubc29\uc5b4 \uc2dc\uc124\uc744 \ud558\ub098\uc758 \uc774\ub984\uc73c\ub85c \ubd80\ub974\uae30 \ub54c\ubb38\uc774\ub2e4. \ubcbd\uc758 \uae38\uc774\ubfd0 \uc544\ub2c8\ub77c \ubb38\uc744 \uc9c0\ud0a8 \uc0ac\ub78c\uacfc \ubb38\uc744 \ud1b5\uacfc\ud55c \uad70\ub300, \uadf8\ub54c \ub0b4\ub824\uc9c4 \uacb0\uc815\uc744 \ubcf4\uba74 \uc7a5\uc131\uc758 \uc758\ubbf8\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uc911\uad6d\uc758 \uc5ec\ub7ec \uad6d\uac00\ub4e4\uc740 \uc9c4\uc758 \ud1b5\uc77c \uc774\uc804\uc5d0\ub3c4 \ubc29\uc5b4\ubcbd\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \uc9c4\uc2dc\ud669\uc758 \uc0ac\uc5c5\uc740 \uc774\ub7f0 \uc120\ud589 \uc2dc\uc124\uacfc \ubd81\ubc29 \ubc29\uc5b4\uc758 \ub9e5\ub77d \uc18d\uc5d0\uc11c \uc774\ud574\ud574\uc57c \ud55c\ub2e4. \uc9c0\uae08 \uc5ec\ud589 \uc0ac\uc9c4\uc5d0\uc11c \ud754\ud788 \ubcf4\ub294 \ubcbd\ub3cc \uc131\ubcbd\uc744 \ubaa8\ub450 \uc9c4\uc2dc\ud669 \uc2dc\ub300\uc758 \uc6d0\ud615\uc73c\ub85c \uc0dd\uac01\ud558\uba74 \uae34 \uc2dc\uac04\uc758 \ucc28\uc774\ub97c \ub193\uce5c\ub2e4. \ud6c4\ub300\uc5d0\ub3c4 \ubc29\uc5b4\uc120\uc740 \uc138\ub825\uacfc \ud658\uacbd\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc84c\ub2e4. \uc77c\ubd80 \uc2dc\uc124\uc740 \uc774\uc5b4 \uc4f0\uc774\uace0 \uc77c\ubd80\ub294 \ubc84\ub824\uc84c\uc73c\uba70 \uc0c8\ub85c\uc6b4 \uad6c\uac04\uc774 \uc0dd\uacbc\ub2e4. \uc9c0\ub3c4\uc5d0 \ud558\ub098\uc758 \uc120\uc744 \uae0b\ub294 \uc77c\uc740 \ud3b8\ub9ac\ud558\uc9c0\ub9cc, \uadf8 \uc120\uc774 \uc5ec\ub7ec \uc655\uc870\uc758 \uc11c\ub85c \ub2e4\ub978 \ud310\ub2e8\uc744 \ud3ec\uac1c \ub193\uc740 \uacb0\uacfc\ub77c\ub294 \uc0ac\uc2e4\uc744 \uae30\uc5b5\ud574\uc57c \ud55c\ub2e4. \ubcbd\uc740 \uc8fc\ubcc0\uc5d0\uc11c \uc5bb\uc744 \uc218 \uc788\ub294 \uc7ac\ub8cc\uc640 \uc9c0\ud615\uc758 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4. \ud759\uc744 \ub2e4\uc9c4 \uad6c\uc870\uc640 \ub3cc\uc774\ub098 \ubcbd\ub3cc\uc744 \uc0ac\uc6a9\ud55c \uad6c\uc870\ub294 \uac89\ubaa8\uc2b5\ub3c4 \ubcf4\uc874 \uc0c1\ud0dc\ub3c4 \ub2e4\ub974\ub2e4. \ub0a8\uc544 \uc788\ub294 \uad6c\uac04\uc774 \uc544\ub984\ub2f5\uace0 \ub2e8\ub2e8\ud558\ub2e4\uace0 \ud574\uc11c \ubaa8\ub4e0 \uc2dc\ub300\uc758 \ubaa8\ub4e0 \uc7a5\uc131\uc774 \uac19\uc740 \ubaa8\uc2b5\uc774\uc5c8\ub2e4\uace0 \ucd94\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2a5\uc120\uc744 \ub530\ub77c\uac00\ub294 \ubcbd\uc744 \ubcfc \ub54c\uc5d0\ub3c4 \uc0b0 \uc790\uccb4\uac00 \ubc29\uc5b4\uc5d0 \uc5b4\ub5a4 \uc5ed\ud560\uc744 \ud558\ub294\uc9c0 \uc0dd\uac01\ud574 \ubcf4\uc790. \uc7a5\uc131\uc740 \ud3c9\uc9c0 \uc704\uc5d0 \ub3c5\ub9bd\uc801\uc73c\ub85c \ub193\uc778 \ubb3c\uac74\uc774 \uc544\ub2c8\ub77c \uc9c0\ud615\uc744 \uc774\uc6a9\ud558\ub294 \uc2dc\uc124\uc774\ub2e4. \uc790\uc5f0\uc758 \ub192\ub0ae\uc774\uc640 \uc0ac\ub78c\uc774 \ub9cc\ub4e0 \uad6c\uc870\ub97c \ud568\uaed8 \uc77d\uc5b4\uc57c \uc65c \uadf8\uacf3\uc5d0 \ubcbd\uc744 \uc138\uc6e0\ub294\uc9c0 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \uc5b4\ub5a4 \ubcbd\ub3c4 \uc2a4\uc2a4\ub85c \uacbd\uacc4\ub97c \uc0b4\ud53c\uace0 \uc18c\uc2dd\uc744 \uc804\ud560 \uc218 \uc5c6\ub2e4. \ubcd1\uc0ac\uc640 \ubcf4\uae09, \ub9d0\uc744 \ub3cc\ubcf4\ub294 \uc77c\uacfc \uc2dc\uc124\uc744 \uc218\ub9ac\ud558\ub294 \ub178\ub3d9\uc774 \ud544\uc694\ud558\ub2e4. \uc6c5\uc7a5\ud55c \uc720\uc801\uc758 \uc0ac\uc9c4 \ubc14\uae65\uc5d0\ub294 \uba39\uc744 \uac83\uc744 \uc6b4\ubc18\ud558\uace0 \uadfc\ubb34\ub97c \uc774\uc5b4 \uac00\ub294 \uc0dd\ud65c\uc774 \uc788\uc5c8\ub2e4. \uc7a5\uc131\uc744 \uc9c0\ud0a8\ub2e4\ub294 \uac83\uc740 \ub3cc\uc744 \uc313\ub294 \uacf5\uc0ac\uc640 \ub2e4\ub978 \uc9c0\uc18d\uc801\uc778 \ube44\uc6a9\uc744 \uc694\uad6c\ud588\ub2e4. \uc2dc\uc124\uc774 \uc644\uc131\ub41c \ub4a4\uc5d0\ub3c4 \uad6d\uac00\uac00 \uc0ac\ub78c\uacfc \ubb3c\uc790\ub97c \ubc30\uce58\ud560 \uc218 \uc788\uc5b4\uc57c \ud588\ub2e4. \uac74\ucd95\uc758 \uaddc\ubaa8\ub9cc\uc73c\ub85c \ubc29\uc5b4 \ub2a5\ub825\uc744 \ud3c9\uac00\ud558\uae30\ubcf4\ub2e4 \uadf8 \uad6c\uc870\ub97c \uc791\ub3d9\uc2dc\ud0a8 \uc870\uc9c1\uae4c\uc9c0 \uc0dd\uac01\ud574\uc57c \ud558\ub294 \uc774\uc720\ub2e4. \uc0ac\ub78c\uc774 \uc804\ud600 \uc624\uac00\uc9c0 \uc54a\ub294 \ubcbd\ub9cc\uc73c\ub85c\ub294 \uad6d\uacbd\uc758 \uc0dd\ud65c\uc744 \uc124\uba85\ud560 \uc218 \uc5c6\ub2e4. \uae38\uacfc \ud1b5\ub85c\uac00 \ud544\uc694\ud588\uace0, \ubb38\uc5d0\uc11c\ub294 \uc774\ub3d9\uc744 \ud5c8\uc6a9\ud558\uac70\ub098 \ub9c9\ub294 \ud310\ub2e8\uc774 \uc774\ub8e8\uc5b4\uc84c\ub2e4. \ubc29\uc5b4\uc120\uc740 \uad50\ub958\uac00 \uc874\uc7ac\ud558\ub294 \uc138\uacc4\uc758 \ud55c\uac00\uc6b4\ub370\uc5d0 \ub193\uc5ec \uc788\uc5c8\ub2e4. \ubb38\uc744 \ud1b5\uc81c\ud558\ub294 \uad8c\ud55c\uc740 \uad70\uc0ac\uc801 \ud798\uacfc \uc815\uce58\uc801 \ucc45\uc784\uc744 \ud568\uaed8 \ub73b\ud588\ub2e4. \ub204\uac00 \ub4e4\uc5b4\uc624\ub294\uc9c0 \uc0b4\ud53c\ub294 \uc77c\uc740 \ub2f4\uc7a5\uc758 \ub192\uc774\ub85c \ub300\uc2e0\ud560 \uc218 \uc5c6\ub2e4. \uc7a5\uc131\uc744 \ubcbd\uacfc \ubb38\uc774 \uacb0\ud569\ud55c \uc2dc\uc124\ub85c \ubcf4\uba74, \ucc28\ub2e8\uacfc \ud1b5\uacfc\uac00 \uc11c\ub85c \ub5a8\uc5b4\uc9c4 \ubb38\uc81c\uac00 \uc544\ub2c8\uc5c8\uc74c\uc744 \uc54c \uc218 \uc788\ub2e4. \uc9c0\uae08 \ub0a8\uc544 \uc788\ub294 \uad6c\uac04\uc744 \uac77\ub294 \uc77c\uc740 \uacfc\uac70\uc758 \ubcd1\uc0ac\uac00 \ubcf4\uc558\ub358 \ud658\uacbd\uc744 \uadf8\ub300\ub85c \ub418\ud480\uc774\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubcf5\uad6c\ub41c \uacf3\uacfc \uc190\uc0c1\ub41c \uacf3, \uad00\uad11\uc744 \uc704\ud574 \uc815\ube44\ud55c \uae38\uc774 \ud568\uaed8 \uc874\uc7ac\ud560 \uc218 \uc788\ub2e4. \uc720\uc801\uc744 \ubcf4\ud638\ud558\ub294 \ud604\uc7ac\uc758 \uc120\ud0dd\ub3c4 \uc6b0\ub9ac\uac00 \ubcf4\ub294 \ubaa8\uc2b5\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4. \uc0ac\uc9c4\uc758 \ucd2c\uc601 \uc7a5\uc18c\uc640 \uc124\uba85\uc774 \uc911\uc694\ud574\uc9c0\ub294 \uc774\uc720\ub2e4. \uba85\ub300\uc758 \ubd81\ubc29 \ubc29\uc5b4\ub97c \uc77d\uc744 \ub54c\ub3c4 \uc7a5\uc131 \ud55c \uc904\ub9cc\uc73c\ub85c \uc9c0\ub3c4\ub97c \ub05d\ub0b4\uc9c0 \ub9d0\uc790. \uad00\ubb38\uacfc \uc694\uc0c8, \uc8fc\ubcc0\uc758 \uae38\uc744 \uc5f0\uacb0\ud558\uba74 \uad70\ub300\uac00 \uc5b4\ub290 \ubc29\ud5a5\uc73c\ub85c \uc774\ub3d9\ud558\uace0 \uc5b4\ub514\uc5d0\uc11c \uba38\ubb3c \uc218 \uc788\uc5c8\ub294\uc9c0 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ubc29\uc5b4 \uc2dc\uc124\uc740 \ub2e8\ub3c5\uc758 \ubcbd\ubcf4\ub2e4 \uc5ec\ub7ec \uac70\uc810\uc744 \uc774\uc5b4 \uc6b4\uc601\ud55c \uccb4\uacc4\ub85c \uc774\ud574\ud560 \ub54c \uc2e4\uc81c \uae30\ub2a5\uc5d0 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \uba85 \ub9d0\uae30\uc758 \uc704\uae30\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc911\uc694\ud55c \uc7a5\uc18c\uac00 \uc0b0\ud574\uad00\uc774\ub2e4. 1644\ub144 \uc774\uc790\uc131\uc758 \uad70\ub300\uac00 \ubca0\uc774\uc9d5\uc744 \ucc28\uc9c0\ud558\uace0 \uba85 \ud669\uc81c\uac00 \uc8fd\uc740 \ub4a4, \uc0b0\ud574\uad00\uc758 \uc624\uc0bc\uacc4\ub294 \uc0c8\ub85c \ud615\uc131\ub41c \uad8c\ub825 \uad00\uacc4 \uc18d\uc5d0\uc11c \uc120\ud0dd\uc744 \ud574\uc57c \ud588\ub2e4. \uc774\ud6c4 \uccad\uc758 \uad70\ub300\uac00 \uad00\ubb38\uc744 \ud1b5\uacfc\ud558\uba70 \uc911\uad6d \uc815\uce58\uc758 \uc911\uc2ec\uc774 \ubc14\ub00c\uc5c8\ub2e4. \uc774 \uacfc\uc815\uc744 \uc7a5\uc131\uc774 \uc4f8\ubaa8\uc5c6\uc5c8\ub2e4\ub294 \ud55c\ub9c8\ub514\ub85c \uc694\uc57d\ud558\uba74 \uc9c0\ub098\uce58\uac8c \ub2e8\uc21c\ud558\ub2e4. \uc655\uc870 \ub0b4\ubd80\uc758 \ubc18\ub780\uacfc \uc9c0\ud718\uad00\uc758 \uc774\ud574\uad00\uacc4, \uc678\ubd80 \uad70\ub300\uc758 \uc804\ub7b5\uc774 \ud568\uaed8 \uc791\uc6a9\ud588\ub2e4. \uc720\uba85\ud55c \uc0ac\uc801\uc778 \uc77c\ud654 \ud558\ub098\ub9cc\uc744 \uc720\uc77c\ud55c \uc6d0\uc778\uc73c\ub85c \uc0bc\ub294 \uc124\uba85\ub3c4 \ubcf5\uc7a1\ud55c \uc815\uce58\uc801 \uc0c1\ud669\uc744 \uac00\ub824 \ubc84\ub9b0\ub2e4. \uc7a5\uc131\uc744 \ubb38\uba85\uacfc \uc57c\ub9cc\uc744 \uc601\uc6d0\ud788 \ub098\ub204\ub294 \uc120\uc73c\ub85c \ubb18\uc0ac\ud55c \uc624\ub798\ub41c \uae00\ub3c4 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uadf8\ub7f0 \ud45c\ud604\uc5d0\ub294 \uae00\uc4f4\uc774 \uc2dc\ub300\uc758 \ud3b8\uacac\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uacf5\ub3d9\uccb4\uac00 \uc804\uc7c1\uc744 \ud588\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ud55c\ucabd\uc758 \uc0b6 \uc804\uccb4\ub97c \ub0ae\ucd94\uc5b4 \ubd80\ub97c \uadfc\uac70\ub294 \uc544\ub2c8\ub2e4. \uacbd\uacc4\ub294 \uace0\uc815\ub41c \ub450 \uc138\uacc4 \uc0ac\uc774\uc5d0\ub9cc \uc788\uc9c0 \uc54a\uc558\ub2e4. \uc815\uce58\uc801 \uc5f0\ud569\uacfc \uac08\ub4f1\uc740 \ubcc0\ud588\uace0, \uc0ac\ub78c\ub4e4\uc774 \uc7a5\uc131\uc744 \uc774\ud574\ud558\ub294 \ubc29\uc2dd\ub3c4 \ubc14\ub00c\uc5c8\ub2e4. \uacfc\uac70\uc758 \uc0ac\ub8cc\ub97c \uc77d\uc744 \ub54c\uc5d0\ub294 \uc0ac\uac74\uc758 \uae30\ub85d\uacfc \uc0ac\ub78c\uc744 \ud3c9\uac00\ud558\ub294 \uc5b8\uc5b4\ub97c \uad6c\ubcc4\ud574\uc57c \uc720\uc801\uc758 \uc5ed\uc0ac\ub97c \ub354 \uc815\ud655\ud788 \uc124\uba85\ud560 \uc218 \uc788\ub2e4. \uc7a5\uc131\uc5d0 \uad00\ud55c \uc22b\uc790\ub294 \uc5b4\ub5a4 \uc2dc\ub300\uc758 \uc5b4\ub5a4 \uc2dc\uc124\uc744 \ud3ec\ud568\ud558\ub294\uc9c0\uc5d0 \ub530\ub77c \uc758\ubbf8\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uae34 \uae38\uc774\ub97c \uc678\uc6b0\ub294 \uac83\ubcf4\ub2e4 \uc9c0\uae08 \ubcf4\ub294 \uad6c\uac04\uc758 \uc2dc\ub300\uc640 \uc7ac\ub8cc, \uc8fc\ubcc0 \ud1b5\ub85c\ub97c \ud655\uc778\ud558\ub294 \uc77c\uc774 \ud604\uc7a5\uc744 \uc774\ud574\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ud558\ub098\uc758 \uc22b\uc790\uac00 \ubaa8\ub4e0 \ubd80\ubd84\uc758 \uc5ed\uc0ac\ub97c \ub300\uc2e0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub9cc\ub9ac\uc7a5\uc131\uc740 \uacbd\uacc4\ub97c \uc138\uc6b0\ub824 \ud55c \uc758\uc9c0\uc758 \ud754\uc801\uc774\uba74\uc11c \uadf8 \uacbd\uacc4\ub97c \uc6b4\uc601\ud574\uc57c \ud588\ub358 \uc0ac\ub78c\ub4e4\uc758 \ud754\uc801\uc774\ub2e4. \ubcbd\uc774 \uc788\ub2e4\uace0 \uc815\uce58\uac00 \uba48\ucd94\uc9c0\ub294 \uc54a\uc558\uace0, \ubb38\uc774 \uc788\ub2e4\uace0 \ubc29\uc5b4\uac00 \ud3ec\uae30\ub41c \uac83\ub3c4 \uc544\ub2c8\uc5c8\ub2e4. \uc720\uc801\uc744 \ubcf8\ub2e4\ub294 \uac83\uc740 \uc0ac\ub77c\uc9c4 \uc870\uc9c1\uacfc \uc0dd\ud65c\uc744 \uc9c8\ubb38\ud558\ub294 \uc77c\uc774\uae30\ub3c4 \ud558\ub2e4. \ub3cc\uc758 \uacac\uace0\ud568\uacfc \uc778\uac04\uc758 \uc120\ud0dd\uc744 \ud568\uaed8 \ubcfc \ub54c \uac70\ub300\ud55c \uc720\uc801\uc774 \uc5ed\uc0ac \uc18d \uc2dc\uc124\ub85c \ub3cc\uc544\uc628\ub2e4."}, {"id": "great-zimbabwe-stone-and-trade", "title": "\uadf8\ub808\uc774\ud2b8 \uc9d0\ubc14\ube0c\uc6e8 \u2014 \ub3cc\uc744 \ubd99\uc774\uc9c0 \uc54a\uace0 \ubcbd\uc744 \uc138\uc6b0\ub2e4", "summary": "\ubaa8\ub974\ud0c0\ub974 \uc5c6\uc774 \uc313\uc740 \ubcbd\uacfc \uad50\uc5ed\ud488\uc744 \ud1b5\ud574 \ub0a8\ubd80 \uc544\ud504\ub9ac\uce74 \ub3c4\uc2dc\uc758 \uae30\uc220\uacfc \uc5f0\uacb0\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/great-zimbabwe-stone-and-trade/index.html", "image": "../media/great-zimbabwe-stone-and-trade.jpg", "alt": "\uadf8\ub808\uc774\ud2b8 \uc9d0\ubc14\ube0c\uc6e8 \uadf8\ub808\uc774\ud2b8 \uc778\ud074\ub85c\uc800 \uc548\uc5d0 \ub0a8\uc740 \ub3cc\ubcbd\uacfc \uc6d0\ubfd4\ud615 \uad6c\uc870\ubb3c, \ub098\ubb34\uc758 \uc2e4\uc81c \uc0ac\uc9c4.", "text": "\uadf8\ub808\uc774\ud2b8 \uc9d0\ubc14\ube0c\uc6e8 \u2014 \ub3cc\uc744 \ubd99\uc774\uc9c0 \uc54a\uace0 \ubcbd\uc744 \uc138\uc6b0\ub2e4 \ub0b4\ub959\uc758 \ub3cc\ub2f4\uc774 \ubc14\ub2e4 \uac74\ub108 \uc138\uacc4\uc640 \uc5f0\uacb0\ub418\ub294 \uc774\uc57c\uae30 \ubaa8\ub974\ud0c0\ub974 \uc5c6\uc774 \uc313\uc740 \ubcbd\uacfc \uad50\uc5ed\ud488\uc744 \ud1b5\ud574 \ub0a8\ubd80 \uc544\ud504\ub9ac\uce74 \ub3c4\uc2dc\uc758 \uae30\uc220\uacfc \uc5f0\uacb0\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ub3cc\ub2f4 \uac00\uae4c\uc774\uc5d0\uc11c \ub3cc\uacfc \ub3cc \uc0ac\uc774\ub97c \ubcf8\ub2e4. \uc811\ucc29 \uc7ac\ub8cc\ub97c \ubc1c\ub77c \ubd99\uc778 \ud754\uc801\uc774 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub370 \ubcbd\uc740 \ub192\uace0 \uae38\uac8c \uc774\uc5b4\uc9c4\ub2e4. \ub0a8\ubd80 \uc544\ud504\ub9ac\uce74\uc758 \uadf8\ub808\uc774\ud2b8 \uc9d0\ubc14\ube0c\uc6e8\uc5d0\ub294 \uc774\ub7f0 \ubc29\uc2dd\uc73c\ub85c \ub9cc\ub4e0 \ud070 \uc11d\uc870 \uc720\uc801\uc774 \ub0a8\uc544 \uc788\ub2e4. \uc0ac\uc9c4\uc758 \ub2f4\uc744 \ubcf4\uace0 \uac74\ucd95 \uae30\uc220\uc774 \uc2e0\uae30\ud558\ub2e4\uace0 \ub290\uaf08\ub2e4\uba74, \uac70\uae30\uc11c \ud55c \uac00\uc9c0\ub97c \ub354 \ubb3c\uc5b4\ubcfc \uc218 \uc788\ub2e4. \uc774 \uc548\ucabd\uc5d0\uc11c \uc0b4\ub358 \uc0ac\ub78c\ub4e4\uc740 \ubb34\uc5c7\uc744 \ub9cc\ub4e4\uace0 \uc5b4\ub514\uc640 \uac70\ub798\ud588\uc744\uae4c. \ub0b4\ub959\uc5d0 \uc790\ub9ac\ud55c \ub3c4\uc2dc\uc758 \uc774\uc57c\uae30\ub294 \ub73b\ubc16\uc5d0\ub3c4 \ub3d9\uc544\ud504\ub9ac\uce74 \ud574\uc548\uacfc \uc778\ub3c4\uc591 \ub108\uba38\uae4c\uc9c0 \uc774\uc5b4\uc9c4\ub2e4. \uc9d0\ubc14\ube0c\uc6e8\ub77c\ub294 \uc774\ub984\uc740 \uc1fc\ub098\uc5b4\uc758 \ub3cc\uc9d1\ub4e4\uc744 \ub73b\ud558\ub294 \ud45c\ud604\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uad50\uc7ac\ub3c4 \ub3cc \uac74\ubb3c\uc774\ub77c\ub294 \uc758\ubbf8\ub97c \uc124\uba85\ud55c\ub2e4. \uc624\ub298\ub0a0 \uad6d\uac00\uc758 \uc774\ub984\uc73c\ub85c \uc775\uc219\ud558\uc9c0\ub9cc, \uadf8\ub808\uc774\ud2b8 \uc9d0\ubc14\ube0c\uc6e8\ub294 \uc1fc\ub098\uc778\ub4e4\uc774 \uc131\uc7a5\uc2dc\ud0a8 \uc911\uc138\uc758 \uc911\uc694\ud55c \uc911\uc2ec\uc9c0\ub2e4. \ucc98\uc74c\ubd80\ud130 \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uac70\ub300\ud55c \ub3cc\uc9d1 \uc548\uc5d0 \uc0b0 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774 \uc9c0\uc5ed\uc758 \uacf5\ub3d9\uccb4\ub294 \uac00\ucd95\uc744 \uae30\ub974\uace0 \ub18d\uc0ac\ub97c \uc9c0\uc5c8\uc73c\uba70 \ud759\uacfc \ub098\ubb34 \uac19\uc740 \uc7ac\ub8cc\ub85c\ub3c4 \uc9d1\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \uc624\ub798 \ub0a8\uc740 \ub3cc \uac74\ubb3c\uc774 \ub208\uae38\uc744 \ub048\ub2e4\uace0 \ub3c4\uc2dc\uc758 \uc77c\uc0c1 \uc804\uccb4\ub97c \ub3cc \ud558\ub098\uc758 \uc774\ubbf8\uc9c0\ub85c \ubc14\uafb8\uc5b4 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub4dc\ub77c\uc774\uc2a4\ud1a4\uc740 \ubaa8\ub974\ud0c0\ub974 \uac19\uc740 \uc811\ucc29 \uc7ac\ub8cc\ub97c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uace0 \ub3cc\uc744 \ub9de\ucd94\uc5b4 \uc313\ub294 \ubc29\uc2dd\uc774\ub2e4. \ud070 \ubcbd\uc744 \ub9cc\ub4e4\ub824\uba74 \ub3cc\uc758 \uc704\uce58\uc640 \ub9de\ubb3c\ub9ac\ub294 \uad00\uacc4\ub97c \uace0\ub824\ud574\uc57c \ud55c\ub2e4. \ub2e8\ub2e8\ud55c \ub3cc\uc774 \ucda9\ubd84\ud788 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uae34 \uad6c\uc870\ubb3c\uc774 \uc800\uc808\ub85c \uc11c\uc9c0\ub294 \uc54a\ub294\ub2e4. \uad50\uc7ac\ub294 11\uc138\uae30 \ubb34\ub835\ubd80\ud130 \uc774 \uc9c0\uc5ed\uc5d0\uc11c \uc774\ub7f0 \uc11d\uc870 \uac74\ubb3c\uc774 \ub098\ud0c0\ub0ac\uace0 \uc8fc\uc694 \uad6c\uc870\ubb3c\uc774 \uc624\ub79c \uc2dc\uac04\uc5d0 \uac78\uccd0 \uac74\uc124\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc790\ub8cc\uc5d0 \ub530\ub77c \uc138\ubd80\uc758 \uc5f0\ub300\uc640 \ud574\uc11d\uc740 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc9c0\ub9cc, \ud604\uc9c0 \uacf5\ub3d9\uccb4\uac00 \ucd95\uc801\ud55c \uac74\ucd95 \uae30\uc220\uc774 \uc911\uc694\ud55c \ubc30\uacbd\uc774\ub77c\ub294 \uc810\uc744 \ub193\uccd0\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc720\uc801\uc740 \ud558\ub098\uc758 \uc131\ucc44\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uc5b8\ub355 \uc704\uc758 \ubcf5\ud569 \uacf5\uac04\uacfc \uac70\ub300\ud55c \ub2f4\uc744 \ub450\ub978 \uadf8\ub808\uc774\ud2b8 \uc778\ud074\ub85c\uc800, \uace8\uc9dc\uae30\uc5d0 \ub0a8\uc740 \uc5ec\ub7ec \uad6c\uc870\ubb3c\uc774 \ud568\uaed8 \uc788\ub2e4. \ud070 \ub2f4\uacfc \uc9d1\ub4e4\uc758 \ubc30\uce58\ub294 \uacf5\uac04 \uc0ac\uc774\uc758 \ucc28\uc774\ub97c \ub9cc\ub4e0\ub2e4. \ub2e4\ub9cc \uc774\uacf3\uc774 \uc815\ud655\ud788 \uc5b4\ub290 \uc758\ub840\ub97c \uc704\ud55c \uc790\ub9ac\uc600\ub294\uc9c0, \ub204\uac00 \uc5b4\ub5a4 \uac74\ubb3c\uc744 \uc0ac\uc6a9\ud588\ub294\uc9c0\uc5d0\ub294 \ub17c\uc7c1\uc774 \ub0a8\uc544 \uc788\ub2e4. \uc655\uad81\uc774\ub098 \uc885\uad50 \uacf5\uac04\uc774\ub77c\ub294 \ud574\uc11d\uc744 \ud55c \uac00\uc9c0 \ud655\uc815\ub41c \ud3c9\uba74\ub3c4\ucc98\ub7fc \uc18c\uac1c\ud558\uba74 \uadfc\uac70\ubcf4\ub2e4 \uc774\uc57c\uae30\uac00 \uc55e\uc120\ub2e4. \ud070 \uaddc\ubaa8\uac00 \uc870\uc9c1\uc801\uc778 \uc790\uc6d0\uacfc \ub178\ub3d9\uc744 \ud544\uc694\ub85c \ud588\ub2e4\ub294 \uc810\uacfc \uac01 \uc7a5\uc18c\uc758 \uad6c\uccb4\uc801 \uc6a9\ub3c4\ub294 \ub098\ub204\uc5b4 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc774 \uc9c0\uc5ed\uc758 \uc0dd\ud65c\uc5d0\ub294 \ubaa9\ucd95\uacfc \ub18d\uacbd, \ucca0\uc744 \ub2e4\ub8e8\ub294 \uae30\uc220\uc774 \uc911\uc694\ud588\ub2e4. \uac00\ucd95\uacfc \ub18d\uc0b0\ubb3c\uc740 \uc0ac\ub78c\ub4e4\uc758 \uc0dd\uacc4\ub97c \ub4b7\ubc1b\uce68\ud588\uace0, \ub3c4\uad6c\uc640 \uc7a5\uc2dd\ud488\uc744 \ub9cc\ub4dc\ub294 \ud65c\ub3d9\ub3c4 \uc774\ub8e8\uc5b4\uc84c\ub2e4. \uc720\uba85\ud55c \uac74\ubb3c\uc740 \uc774\ub7f0 \uc0dd\uc0b0\uc774 \uacc4\uc18d\ub420 \uc218 \uc788\ub294 \ud658\uacbd\uacfc \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\uc558\ub2e4. \uc74c\uc2dd\uacfc \uc77c\uc0c1\uc6a9\ud488\uc744 \uc0dd\uc0b0\ud558\ub294 \uc0ac\ub78c\uc774 \uc5c6\uc73c\uba74 \uad8c\ub825\uc758 \uc911\uc2ec\ub3c4 \uc720\uc9c0\ub420 \uc218 \uc5c6\ub2e4. \uc720\uc801\uc744 \uac10\uc0c1\ud560 \ub54c\ub294 \ud070 \ub2f4\uc744 \uc138\uc6b4 \uc0ac\ub78c\ubfd0 \uc544\ub2c8\ub77c \uadf8 \uacfc\uc815\uc5d0\uc11c \uba39\uc744\uac70\ub9ac\ub97c \ub9c8\ub828\ud558\uace0 \uc7ac\ub8cc\ub97c \ub2e4\ub8e8\uc5c8\ub358 \uc0ac\ub78c\ub3c4 \ud568\uaed8 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ub3c4\uc2dc\uc758 \uae30\uc220\uc740 \ub208\uc5d0 \ud06c\uac8c \ub0a8\uc740 \uac74\ucd95\ub9cc\uc744 \ub73b\ud558\uc9c0 \uc54a\ub294\ub2e4. \uadf8\ub808\uc774\ud2b8 \uc9d0\ubc14\ube0c\uc6e8\ub294 \uae08\uacfc \uad6c\ub9ac, \uc0c1\uc544 \ub4f1\uc744 \uad50\uc5ed\ud558\uba70 \uc131\uc7a5\ud588\ub2e4. \ub3d9\uc544\ud504\ub9ac\uce74\uc758 \uc2a4\uc640\ud790\ub9ac \ud574\uc548 \ub3c4\uc2dc\ub4e4\uacfc \uc5f0\uacb0\ub418\uba74\uc11c \ub0b4\ub959\uc758 \ubb3c\ud488\uc740 \uc18c\ud314\ub77c\uc640 \ud0ac\uc640 \uac19\uc740 \uad50\uc5ed \uac70\uc810\uc744 \uac70\uccd0 \ub354 \ub113\uc740 \uc138\uacc4\ub85c \ub098\uac08 \uc218 \uc788\uc5c8\ub2e4. \uc5ec\uae30\uc11c \uc9c0\ub3c4\ub97c \ub3c4\uc2dc \uc8fc\ubcc0\ub9cc \uc798\ub77c \ubcf4\uba74 \uc911\uc694\ud55c \uae38\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \ubc14\ub2e4\uc640 \ub5a8\uc5b4\uc838 \uc788\ub2e4\uace0 \ud574\uc591 \uad50\uc5ed\uacfc \ubb34\uad00\ud588\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub0b4\ub959\uacfc \ud574\uc548 \uc0ac\uc774\ub97c \uc624\uac00\ub294 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uad50\ud658\uc774 \uc9c0\uc5ed\uc744 \uc5f0\uacb0\ud588\ub2e4. \ud55c \ub3c4\uc2dc\uc758 \ubc88\uc601\uc774 \ubc18\ub4dc\uc2dc \uadf8 \ub3c4\uc2dc \uc8fc\ubbfc\uc758 \uc9c1\uc811\uc801\uc778 \uc7a5\uac70\ub9ac \ud56d\ud574\ub85c\ub9cc \ub9cc\ub4e4\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\ub3c4 \ubcf4\uc778\ub2e4. \uace0\uace0\ud559 \uc790\ub8cc\uc5d0\ub294 \uc911\uad6d \ub3c4\uc790\uae30\uc640 \ud398\ub974\uc2dc\uc544 \uc9c0\uc5ed\uc758 \ub3c4\uae30 \ub4f1 \uc678\ubd80\uc640\uc758 \uc5f0\uacb0\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ubb3c\uac74\uc774 \uc788\ub2e4. \uc774\ub7f0 \ubc1c\uacac\uc740 \uc11d\uc870 \uc720\uc801\uc774 \uc678\ubd80 \uc138\uacc4\uc640 \ub2e8\uc808\ub41c \uacf5\uac04\uc774\uc5c8\ub2e4\ub294 \uc778\uc0c1\uc744 \ubc14\uafb8\uc5b4 \uc900\ub2e4. \uc791\uc740 \ud30c\ud3b8\uc774 \ud070 \uae38\uc758 \uc874\uc7ac\ub97c \uc54c\ub824 \uc8fc\ub294 \uc148\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubb3c\uac74 \ud558\ub098\uac00 \ubc1c\uacac\ub418\uc5c8\ub2e4\uace0 \ud2b9\uc815 \uc0c1\uc778\uc774 \uc911\uad6d\uc5d0\uc11c \uc774 \ub3c4\uc2dc\uae4c\uc9c0 \uc9c1\uc811 \uc5ec\ud589\ud588\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc5ec\ub7ec \ubc88\uc758 \uad50\ud658\uc744 \uac70\uccd0 \uc62e\uaca8 \uc654\uc744 \uc218\ub3c4 \uc788\ub2e4. \ubb3c\uac74\uc758 \uc774\ub3d9\uacfc \uc0ac\ub78c \ud55c \uba85\uc758 \uc5ec\ud589 \uacbd\ub85c\ub294 \uac19\uc740 \uc99d\uac70\uac00 \uc544\ub2c8\ub2e4. \uc774 \uad6c\ubd84\uc744 \ud558\uba74 \uad50\uc5ed\ub9dd\uc758 \ub113\uc774\ub97c \uacfc\uc7a5 \uc5c6\uc774 \ub354 \ud765\ubbf8\ub86d\uac8c \uc77d\uc744 \uc218 \uc788\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c\ub294 \ub3cc\ub2f4\uc774 \uac15\ud558\uac8c \ubcf4\uc774\uc9c0\ub9cc, \ub2f9\uc2dc \uc0dd\ud65c\uc5d0 \uc4f0\uc778 \uc7ac\ub8cc\uac00 \ubaa8\ub450 \uac19\uc740 \uc0c1\ud0dc\ub85c \ubcf4\uc874\ub418\uc9c0\ub294 \uc54a\uc558\ub2e4. \ud759\uacfc \ub098\ubb34\ub85c \ub9cc\ub4e0 \uac70\ucc98\uc758 \ud754\uc801\ub3c4 \ud568\uaed8 \uc5f0\uad6c\ud574\uc57c \ud55c\ub2e4. \uc9c0\uae08 \ub208\uc5d0 \uc798 \ubcf4\uc774\ub294 \uac83\uacfc \uacfc\uac70\uc5d0 \uc911\uc694\ud588\ub358 \uac83\uc758 \ubaa9\ub85d\uc740 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \uc720\uc801 \uc0ac\uc9c4\uc740 \ub3c4\uc2dc\uc758 \uc804\uccb4 \ubaa8\uc2b5\uc744 \uc644\uc131\ud574 \uc8fc\ub294 \uc815\ub2f5\uc9c0\uac00 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc774 \uc624\ub798 \ubc84\ud17c\ub294\uc9c0\ub97c \ubcf4\uc5ec \uc8fc\ub294 \ucc3d\uc774\uae30\ub3c4 \ud558\ub2e4. \ub0a8\uc740 \ub2f4\uc758 \uae38\uc774\uc640 \ud615\ud0dc\ub97c \uc0b4\ud53c\ub294 \uac10\uc0c1\uc5d0 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc9d1\uacfc \uc791\uc5c5, \uc0dd\ud65c\uc758 \uad00\uacc4\ub97c \ub354\ud558\uba74 \uacfc\uac70\uc758 \uacf5\uac04\uc774 \uc870\uae08 \ub354 \ub113\uc5b4\uc9c4\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \uadf8\ub808\uc774\ud2b8 \uc778\ud074\ub85c\uc800 \uc548\ucabd\uc758 \uc2e4\uc81c \uc720\uc801 \uc0ac\uc9c4\uc774\ub2e4. \uad6c\uccb4\uc801\uc778 \ub3cc \ubc30\uce58\uc640 \ubcbd\uc758 \ub192\uc774 \ucc28\uc774\ub97c \ubcfc \uc218 \uc788\uc9c0\ub9cc, \uadf8\uac83\ub9cc\uc73c\ub85c \uc61b \uc758\ub840\ub098 \uac70\uc8fc\uc790\uc758 \uc77c\uacfc\uae4c\uc9c0 \ubcf5\uc6d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud655\uc778\ud55c \ubaa8\uc2b5\uc5d0\uc11c \uc774\uc57c\uae30\ub97c \uc2dc\uc791\ud558\uba74 \ub41c\ub2e4. \uadf8\ub808\uc774\ud2b8 \uc9d0\ubc14\ube0c\uc6e8\uc758 \ub3cc\ub4e4\uc740 \ubd99\uc774\ub294 \uc7ac\ub8cc \uc5c6\uc774 \ub9de\ubb3c\ub824 \uc11c \uc788\ub2e4. \ub3c4\uc2dc\uc758 \uc0b6\uc740 \ubc18\ub300\ub85c \uc218\ub9ce\uc740 \uc5f0\uacb0\uc744 \ud544\uc694\ub85c \ud588\ub2e4. \uacbd\uc791\uc9c0\uc640 \ubaa9\uc7a5, \uc7a5\uc778\uacfc \uad50\uc5ed\ub85c, \ub0b4\ub959\uacfc \ubc14\ub2e4\uac00 \uc774\uc5b4\uc84c\uae30 \ub54c\ubb38\uc774\ub2e4. \uac00\uae4c\uc774\uc5d0\uc11c \ubcf8 \ub3cc \uc0ac\uc774\uc758 \ud2c8\uc774 \uba40\ub9ac \ub5a8\uc5b4\uc9c4 \uc138\uacc4\uae4c\uc9c0 \uc0dd\uac01\ud558\uac8c \ud558\ub294 \uc720\uc801\uc774\ub2e4."}, {"id": "gyeonghoeru-pond-dragon", "title": "\uacbd\ud68c\ub8e8 \uc5f0\ubabb\uc5d0\uc11c\ub294 \uc65c \uccad\ub3d9 \uc6a9\uc774 \ub098\uc654\uc744\uae4c", "summary": "\uc5f0\ubabb\uc5d0\uc11c \ubc1c\uacac\ub41c \uc6a9\uc740 \uc7a5\uc2dd\uc5d0\uc11c \ub5a8\uc5b4\uc9c4 \ubb3c\uac74\uc774 \uc544\ub2c8\uc5c8\uc2b5\ub2c8\ub2e4. \uae30\ub85d\uc5d0\ub294 \ubb3c\uc5d0 \ub123\uc740 \uc774\uc720\uac00 \ub0a8\uc544 \uc788\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/gyeonghoeru-pond-dragon/index.html", "image": "../media/gyeonghoeru-pond-dragon.jpg", "alt": "\uad81\uad90 \uc5f0\ubabb\uc758 \uc815\uc790 \ubc18\uc601\uacfc \ubb3c \uc544\ub798 \uc791\uc740 \uc6a9\uc758 \ud615\uc0c1\uc744 \uadf8\ub9b0 \uc124\uba85\uc6a9 AI \uc0bd\ud654", "text": "\uacbd\ud68c\ub8e8 \uc5f0\ubabb\uc5d0\uc11c\ub294 \uc65c \uccad\ub3d9 \uc6a9\uc774 \ub098\uc654\uc744\uae4c \ubb3c\uc18d\uc5d0 \ub123\uc5b4 \ub454 \uad81\uad90\uc758 \ud654\uc7ac \uc608\ubc29 \uae30\uc6d0 \uc5f0\ubabb\uc5d0\uc11c \ubc1c\uacac\ub41c \uc6a9\uc740 \uc7a5\uc2dd\uc5d0\uc11c \ub5a8\uc5b4\uc9c4 \ubb3c\uac74\uc774 \uc544\ub2c8\uc5c8\uc2b5\ub2c8\ub2e4. \uae30\ub85d\uc5d0\ub294 \ubb3c\uc5d0 \ub123\uc740 \uc774\uc720\uac00 \ub0a8\uc544 \uc788\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uacbd\ubcf5\uad81\uc758 \uacbd\ud68c\ub8e8\ub97c \ubcf4\uba74 \uc5f0\ubabb\uc5d0 \ube44\uce5c \uac74\ubb3c\ubd80\ud130 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ubb3c \uc544\ub798\uc5d0 \ubb34\uc5c7\uc774 \uc788\uc5c8\ub294\uc9c0\uae4c\uc9c0 \uc0dd\uac01\ud558\uac8c \ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub7f0\ub370 1997\ub144, \uadf8 \uc5f0\ubabb\uc5d0\uc11c \uccad\ub3d9\uc73c\ub85c \ub9cc\ub4e0 \uc6a9\uc774 \ubc1c\uacac\ub418\uc5c8\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc18c\uac1c\ud558\ub294 \uc720\ubb3c\uc740 \uae38\uc774\uac00 1\ubbf8\ud130\ub97c \ud6cc\uca4d \ub118\uace0 \ubb34\uac8c\ub3c4 60\ud0ac\ub85c\uadf8\ub7a8\uc774 \ub118\ub294\ub2e4. \uc190\ubc14\ub2e5\uc5d0 \ub4e4\uc5b4\uc624\ub294 \uc791\uc740 \uc7a5\uc2dd\uc740 \uc544\ub2c8\ub2e4. \uc65c \uc774\ub7f0 \ubb3c\uac74\uc774 \ubb3c\uc18d\uc5d0 \uc788\uc5c8\uc744\uae4c. \ub204\uac00 \ub5a8\uc5b4\ub728\ub9b0 \uac83\uc774 \uc544\ub2c8\ub77c, \uad81\uad90\uc744 \ubd88\uc5d0\uc11c \uc9c0\ucf1c \ub2ec\ub77c\ub294 \ub73b\uc73c\ub85c \ub123\uc5b4 \ub454 \uc6a9\uc774\uc5c8\ub2e4. \ub098\ubb34\ub85c \uc9c0\uc740 \uac74\ubb3c\uc774 \ub9ce\uc558\ub358 \uad81\uad90\uc5d0\uc11c \ubd88\uc740 \ud070 \uac71\uc815\uac70\ub9ac\uc600\ub2e4. \uacbd\ubcf5\uad81\uc744 \ub2e4\uc2dc \uc9d3\ub294 \uacfc\uc815\uc5d0\uc11c\ub3c4 \ud654\uc7ac\ub97c \ud53c\ud558\ub824\ub294 \uc5ec\ub7ec \uc870\uce58\uac00 \uc774\ub8e8\uc5b4\uc84c\ub2e4\uace0 \ubc15\ubb3c\uad00\uc740 \uc124\uba85\ud55c\ub2e4. \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc740 \uc6a9\uc774 \ubb3c\uacfc \uad6c\ub984\uc744 \ub2e4\uc2a4\ub9b0\ub2e4\uace0 \uc5ec\uacbc\ub2e4. \ubb3c\uc744 \ub2e4\ub8e8\ub294 \uc874\uc7ac\uc5d0\uac8c \ubd88\uc744 \ub9c9\uc544 \ub2ec\ub77c\ub294 \ub73b\uc744 \ub2f4\uc544 \uc5f0\ubabb\uc5d0 \uccad\ub3d9 \uc6a9\uc744 \ub123\uc740 \uac83\uc774\ub2e4. \uc774\ub54c\uc758 \uc6a9\uc740 \uc18c\ud654 \uc7a5\uce58\ub77c\uae30\ubcf4\ub2e4 \ubc14\ub78c\uc744 \ub2f4\uc740 \uc0c1\uc9d5\uc774\uc5c8\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc740 \u300e\uacbd\ubcf5\uad81\uc601\uac74\uc77c\uae30\u300f\ub97c \uadfc\uac70\ub85c \uc81c\uc791\uacfc \ubc30\uce58 \uacfc\uc815\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc6a9\uc744 \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\ubfd0 \uc544\ub2c8\ub77c \ubb3c\uc5d0 \uac00\ub77c\uc549\ud78c \uae30\ub85d\uae4c\uc9c0 \ub0a8\uc544 \uc788\ub2e4. \ub2e8\uc21c\ud788 \uc0dd\uae40\uc0c8\ub97c \ubcf4\uace0 \uc624\ub298\uc758 \uad00\ub78c\uac1d\uc774 \ubd99\uc778 \ud574\uc11d\uc740 \uc544\ub2cc \uc148\uc774\ub2e4. \uccad\ub3d9 \uc6a9\uc740 1865\ub144\uc5d0 \ud55c \uc30d\uc73c\ub85c \uc81c\uc791\ub418\uc5c8\uace0, 1867\ub144\uc5d0 \uacbd\ud68c\ub8e8 \uc5f0\ubabb\uc5d0 \ub123\uc5c8\ub2e4\uace0 \uae30\ub85d\ub418\uc5b4 \uc788\ub2e4. \uadf8\ub7f0\ub370 1997\ub144 \ubc1c\uacac \ub2f9\uc2dc \ud655\uc778\ub41c \uac83\uc740 \ud55c \ub9c8\ub9ac\uc600\ub2e4. \ub458\uacfc \ud558\ub098\uc758 \ucc28\uc774\uac00 \uc791\uc740 \uad81\uae08\uc99d\uc744 \ub0a8\uae34\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub2e4\ub978 \ud55c \ub9c8\ub9ac\uc758 \ud589\ubc29\uc744 \uc0c1\uc0c1\uc73c\ub85c \ucc44\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub0a8\uc544 \uc788\ub294 \uae30\ub85d\uc774 \uc54c\ub824\uc8fc\ub294 \uc218\uc640 \uc2e4\uc81c \ubc1c\uacac\uc5d0\uc11c \ud655\uc778\ud55c \uc218\ub97c \ub098\ub204\uc5b4 \uae30\uc5b5\ud558\uba74 \ub41c\ub2e4. \ubc1c\uacac\ub41c \uc6a9\uc740 \ubc18\ucabd\uc529 \uc8fc\uc870\ud55c \ub4a4 \ubd99\uc5ec \ub9cc\ub4dc\ub294 \ubc29\uc2dd\uc73c\ub85c \uc81c\uc791\ub418\uc5c8\ub2e4\uace0 \ud55c\ub2e4. \ubb3c\uc18d\uc5d0 \ub123\uc744 \ubb3c\uac74\uc5d0\ub3c4 \uae08\uc18d\uc744 \ub2e4\ub8e8\ub294 \uc218\uace0\uac00 \ub4e4\uc5b4\uac14\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294 \uacf3\uc5d0 \ub454\ub2e4\uace0 \ub300\ucda9 \ub9c8\ub828\ud55c \ubb3c\uac74\uc740 \uc544\ub2c8\uc5c8\ub358 \uac83\uc774\ub2e4. \uace0\uc0ac\ubb38\uc5d0\ub294 \uad81\uad90\uc744 \uc624\ub798 \ubcf4\ud638\ud574 \ub2ec\ub77c\ub294 \uae30\uc6d0\uc774 \ub2f4\uaca8 \uc788\ub2e4. \uadf8 \uae00\uc744 \ud1b5\ud574 \uc6b0\ub9ac\ub294 \uc6a9\uc774 \uc2e4\uc81c\ub85c \ubd88\uc744 \ub9c9\uc558\ub294\uc9c0\uac00 \uc544\ub2c8\ub77c, \uc0ac\ub78c\ub4e4\uc774 \ubb34\uc5c7\uc744 \ub450\ub824\uc6cc\ud558\uace0 \ubb34\uc5c7\uc744 \ubc14\ub790\ub294\uc9c0 \uc77d\uac8c \ub41c\ub2e4. \uc5f0\ubabb\uc5d0\uc11c \uae08\uc18d \ubb3c\uac74\uc774 \ub098\uc654\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c\ub294 \ubb3c\uc5d0 \ube60\ub728\ub9b0 \uac83\uc778\uc9c0 \uc77c\ubd80\ub7ec \ub123\uc740 \uac83\uc778\uc9c0 \uc54c\uae30 \uc5b4\ub835\ub2e4. \uc774 \uc6a9\uc740 \uacf5\uc0ac \uae30\ub85d\uacfc \ud568\uaed8 \uc77d\uc744 \uc218 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c \ud2b9\ubcc4\ud558\ub2e4. \uc81c\uc791\uacfc \ubc30\uce58\uc758 \uc2dc\uac04\uc774 \uc801\ud600 \uc788\uc5b4, \ubc1c\uacac\ud55c \ubb3c\uac74\uc744 \uad81\uad90\uc744 \ub2e4\uc2dc \uc9d3\ub358 \uc0ac\ub78c\ub4e4\uc758 \uc120\ud0dd\uacfc \uc5f0\uacb0\ud560 \uc218 \uc788\ub2e4. \uc720\ubb3c\uc740 \ubaa8\uc591\uc744 \ubcf4\uc5ec \uc8fc\uace0 \uae30\ub85d\uc740 \uadf8 \ubb3c\uac74\uc774 \ub193\uc778 \uc774\uc720\ub97c \uc124\uba85\ud55c\ub2e4. \ub450 \uc790\ub8cc\uac00 \ub098\ub780\ud788 \uc788\uc744 \ub54c\uc5d0\ub3c4 \uac01\uac01 \uc54c\ub824 \uc8fc\ub294 \ubc94\uc704\ub294 \ub2e4\ub974\ub2e4. \ubb38\uc11c\uc758 \ud55c \uc30d\uacfc \ubc1c\uacac \ub2f9\uc2dc\uc758 \ud55c \uc810\uc744 \uac19\uac8c \ub9cc\ub4e4 \uc218\ub294 \uc5c6\ub2e4. \uc624\ud788\ub824 \ucc28\uc774\ub97c \ub0a8\uaca8 \ub450\uba74 \uc55e\uc73c\ub85c \ubb34\uc5c7\uc744 \ub354 \ud655\uc778\ud574\uc57c \ud558\ub294\uc9c0 \ubcf4\uc778\ub2e4. \ubb3c\uac74\uacfc \ubb38\uc11c\uac00 \uc11c\ub85c\ub97c \ubcf4\uc644\ud55c\ub2e4\ub294 \uac83\uc740 \uc5b8\uc81c\ub098 \ube48\uce78 \uc5c6\uc774 \uc77c\uce58\ud55c\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uae38\uc774 146.5\uc13c\ud2f0\ubbf8\ud130, \ubb34\uac8c 66.5\ud0ac\ub85c\uadf8\ub7a8\uc774\ub77c\ub294 \ud06c\uae30\ub97c \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc791\uc740 \ubd80\uc801\uc744 \ubab0\ub798 \ubb3c\uc5d0 \ub358\uc9c0\ub294 \uc7a5\uba74\uacfc\ub294 \ub2e4\ub974\ub2e4. \uae08\uc18d\uc744 \ub9c8\ub828\ud558\uace0 \ud615\uc0c1\uc744 \ub9cc\ub4e4\uace0 \uc62e\uae30\ub294 \uacfc\uc815\uc774 \ud544\uc694\ud55c \ubb3c\uac74\uc774\uc5c8\ub2e4. \ud55c \uc30d\uc744 \uc81c\uc791\ud588\ub2e4\ub294 \uae30\ub85d\uc744 \uc0dd\uac01\ud558\uba74 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uacf3\uc5d0 \ub450\ub294 \uc0c1\uc9d5\uc5d0\ub3c4 \uc801\uc9c0 \uc54a\uc740 \uc900\ube44\uac00 \ub4e4\uc5b4\uac14\uc74c\uc744 \uc9d0\uc791\ud560 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ub204\uac00 \uc5b4\ub5a4 \uc790\uc138\ub85c \uc6a9\uc744 \uc6b4\ubc18\ud588\ub294\uc9c0 \uac19\uc740 \uad6c\uccb4\uc801\uc778 \ud604\uc7a5\uc744 \uc0c1\uc0c1\uc73c\ub85c \ucc44\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud655\uc778\ub41c \ud06c\uae30\uc640 \uc81c\uc791 \ubc29\uc2dd\ub9cc\uc73c\ub85c\ub3c4 \ucda9\ubd84\ud788 \ud765\ubbf8\ub86d\ub2e4. \uac74\ucd95\uc744 \uc644\uc131\ud55c\ub2e4\ub294 \uc77c\uc5d0\ub294 \uc0ac\ub78c\ub4e4\uc774 \uac10\uc0c1\ud560 \uae30\ub465\uacfc \uc9c0\ubd95\ubfd0 \uc544\ub2c8\ub77c, \uc644\uc131\ud55c \ub4a4\uc5d0 \uc27d\uac8c \ubcf4\uc774\uc9c0 \uc54a\uc744 \ubb3c\uac74\uc744 \ub9c8\ub828\ud558\ub294 \uc77c\ub3c4 \ud3ec\ud568\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc6a9\uc744 \uc5f0\ubabb\uc5d0 \ub454 \uc774\uc720\ub294 \ubb3c\uacfc \uad6c\ub984\uc744 \ub2e4\uc2a4\ub9b0\ub2e4\uace0 \uc5ec\uae34 \uc874\uc7ac\uc5d0\uac8c \ud654\uc7ac\ub97c \ub9c9\uc544 \ub2ec\ub77c\uace0 \uae30\uc6d0\ud588\uae30 \ub54c\ubb38\uc774\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc0c1\uc9d5\uc758 \uc5f0\uacb0\uc774 \ubd84\uba85\ud558\ub2e4. \ubb3c\uacfc \ubd88\uc774\ub77c\ub294 \ub300\ube44\uac00 \uac74\ubb3c\uc758 \uc7ac\ub8cc\uc640 \uc704\ud5d8\uc5d0 \ub300\ud55c \uac71\uc815 \uc18d\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ub098\ubb34\ub85c \uc9c0\uc740 \uad81\uad90\uc758 \uc544\ub984\ub2e4\uc6b4 \ubaa8\uc2b5\uacfc \uadf8\uac83\uc744 \uc783\uc744 \uc218 \uc788\ub2e4\ub294 \ub450\ub824\uc6c0\uc774 \uac19\uc740 \uacf5\uac04\uc5d0 \uc788\uc5c8\ub2e4. \uc624\ub298\uc758 \uc18c\ubc29 \uc124\ube44\uc640 \uac19\uc740 \uae30\ub2a5\uc744 \ud588\ub2e4\uace0 \ud310\ub2e8\ud558\uae30\ubcf4\ub2e4, \uc0ac\ub78c\ub4e4\uc774 \uc704\ud5d8\uc5d0 \ub300\uc751\ud560 \ub54c \uae30\uc220\uc801\uc778 \uc870\uce58\uc640 \uae30\uc6d0\uc744 \uc5b4\ub5bb\uac8c \ud568\uaed8 \ub450\uc5c8\ub294\uc9c0 \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub2e4. \ubc14\ub78c\uc744 \ub2f4\uc740 \ubb3c\uac74\uc740 \uc2e4\uc81c \uc704\ud5d8\uc744 \uc5c6\uc574\ub2e4\ub294 \uc99d\uba85\ubcf4\ub2e4 \uadf8 \uc704\ud5d8\uc774 \uc5bc\ub9c8\ub098 \uc911\uc694\ud55c \ubb38\uc81c\uc600\ub294\uc9c0\ub97c \ubcf4\uc5ec \uc900\ub2e4. \uc7a5\uc2dd\uc758 \ub73b\uc744 \uc544\ub294 \uc77c\uc774 \uac74\ubb3c\uc744 \uc0ac\uc6a9\ud558\ub358 \uc0ac\ub78c\uc758 \uac71\uc815\uc5d0 \uac00\uae4c\uc774 \uac00\ub294 \uae38\uc774 \ub41c\ub2e4. \uacbd\ud68c\ub8e8\ub97c \ubcf4\uba74 \uc815\uc790\uc640 \ubb3c\uc5d0 \ube44\uce5c \uc9c0\ubd95\uc744 \ud55c \uc7a5\uc758 \ud48d\uacbd\ucc98\ub7fc \ubc14\ub77c\ubcf4\uac8c \ub41c\ub2e4. \uc6a9\uc758 \uc774\uc57c\uae30\ub294 \uc2dc\uc120\uc744 \uc218\uba74 \uc544\ub798\ub85c \uc62e\uae34\ub2e4. \uc5f0\ubabb\uc774 \uac74\ubb3c\uc744 \ub3cb\ubcf4\uc774\uac8c \ud558\ub294 \ubc30\uacbd\uc774\uba74\uc11c \uae30\uc6d0\uc744 \ub9e1\uae30\ub294 \uc790\ub9ac\uc600\ub2e4\ub294 \uc0ac\uc2e4\uc740, \uac74\ucd95\uc758 \ubc94\uc704\ub97c \ubcbd\uacfc \uae30\ub465 \ubc16\uc73c\ub85c \ub113\ud78c\ub2e4. \uac19\uc740 \uacbd\uce58\ub97c \ubcf4\ub354\ub77c\ub3c4 \ubb3b\uac8c \ub418\ub294 \uc9c8\ubb38\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc0bd\ud654\uc5d0\uc11c \uc6a9\uc758 \uc815\ud655\ud55c \ud615\ud0dc\ub098 \ucd9c\ud1a0 \uc704\uce58\ub97c \uc54c\uc544\ub0bc \uc218\ub294 \uc5c6\ub2e4. \uc2e4\uc81c \uc720\ubb3c\uc758 \ubaa8\uc2b5\uacfc \ucd9c\ud1a0 \uc774\ub825\uc740 \ubc15\ubb3c\uad00 \uc790\ub8cc\ub97c \ud1b5\ud574 \ud655\uc778\ud560 \ubd80\ubd84\uc774\ub2e4. \ub300\uc2e0 \uc774 \uc774\uc57c\uae30\uc758 \uc785\uad6c\uc5d0\uc11c\ub294 \ubb3c \uc544\ub798\uc5d0\ub3c4 \uc0ac\ub78c\uc774 \uc120\ud0dd\ud574 \ub193\uc740 \uac83\uc774 \uc788\uc5c8\ub2e4\ub294 \uc810\uc744 \uae30\uc5b5\ud558\uba74 \uc88b\ub2e4. \uc870\uc6a9\ud55c \ud48d\uacbd\uc5d0 \uc81c\uc791\uacfc \uae30\ub85d, \uc7ac\ubc1c\uacac\uc758 \uc2dc\uac04\uc774 \ud3ec\uac1c\uc9c4\ub2e4. \uad81\uad90\uc758 \uc0c1\uc9d5\uc740 \uc9c0\ubd95\uc774\ub098 \ubb38 \uc704\uc5d0\uc11c\ub9cc \ubc1c\uacac\ub418\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uacbd\ud68c\ub8e8\uc758 \uc6a9\uc740 \uc624\ub7ab\ub3d9\uc548 \ubb3c \uc544\ub798\uc5d0 \uc788\uc5c8\ub2e4. \ubc14\ub77c\ubcf4\ub294 \uc0ac\ub78c\uc5d0\uac8c \uc790\uc2e0\uc744 \ub4dc\ub7ec\ub0b4\ub294 \uc7a5\uc2dd\uacfc\ub294 \uc870\uae08 \ub2e4\ub978 \uc790\ub9ac\ub2e4. \uc774 \uc0ac\uc2e4\uc744 \uc548 \ub4a4 \uacbd\ud68c\ub8e8\ub97c \ubcf4\uba74 \uc5f0\ubabb\uc774 \ub2e8\uc21c\ud55c \ubc30\uacbd\ub9cc\uc73c\ub85c \ubcf4\uc774\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uac74\ubb3c\uc758 \uc544\ub984\ub2e4\uc6c0\uc744 \ube44\ucd94\ub358 \ubb3c\uc774, \ud55c\ub54c\ub294 \ubd88\uc744 \ub9c9\uc544 \uc8fc\uae30\ub97c \ubc14\ub77c\ub294 \ub9c8\uc74c\uc744 \ub9e1\uae34 \uacf3\uc774\uae30\ub3c4 \ud588\ub2e4. \ub2e4\uc74c\uc5d0 \uacbd\ud68c\ub8e8 \uc0ac\uc9c4\uc744 \ubcf4\uac8c \ub41c\ub2e4\uba74 \uc9c0\ubd95\uc5d0\uc11c \ubb3c\uac00\ub85c \uc2dc\uc120\uc744 \ub0b4\ub824 \ubcf4\uc790. \uc870\uc6a9\ud55c \uc218\uba74 \uc544\ub798\uc5d0\ub3c4 \uac74\ubb3c\uc744 \uc9c0\ud0a4\uace0 \uc2f6\uc5c8\ub358 \uc0ac\ub78c\ub4e4\uc758 \uc774\uc57c\uae30\uac00 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4."}, {"id": "hammurabi-stele-status-evidence-and-royal-justice", "title": "\ud568\ubb34\ub77c\ube44 \ubc95\uc804 \u2014 \ub3cc\uc5d0 \uc0c8\uae34 \uc815\uc758\ub294 \ub204\uad6c\uc5d0\uac8c \uac19\uc558\uc744\uae4c", "summary": "\uae30\uc6d0\uc80418\uc138\uae30\uc758 \uacc4\uc57d\uacfc \uc2e0\ubd84, \uc655\uc758 \uc815\uc758\uc640 \uc2e4\uc81c \uc7ac\ud310\uc758 \uac70\ub9ac\uc758 \ubc30\uacbd\uacfc \uc804\uac1c, \uc774\ud6c4\uc758 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities", "ideas"], "url": "stories/hammurabi-stele-status-evidence-and-royal-justice/index.html", "image": "../media/hammurabi-stele-status-evidence-and-royal-justice.jpg", "alt": "\ud568\ubb34\ub77c\ube44 \ubc95\uc804 \ube44\uc11d \uc704\ucabd\uc758 \uc0e4\ub9c8\uc2dc\uc640 \uc655 \ubd80\uc870\ub97c \uc7ac\ud604\ud55c \uc5ed\uc0ac \ub3c4\ud310", "text": "\ud568\ubb34\ub77c\ube44 \ubc95\uc804 \u2014 \ub3cc\uc5d0 \uc0c8\uae34 \uc815\uc758\ub294 \ub204\uad6c\uc5d0\uac8c \uac19\uc558\uc744\uae4c \uae30\uc6d0\uc80418\uc138\uae30\uc758 \uacc4\uc57d\uacfc \uc2e0\ubd84, \uc655\uc758 \uc815\uc758\uc640 \uc2e4\uc81c \uc7ac\ud310\uc758 \uac70\ub9ac \uae30\uc6d0\uc80418\uc138\uae30\uc758 \uacc4\uc57d\uacfc \uc2e0\ubd84, \uc655\uc758 \uc815\uc758\uc640 \uc2e4\uc81c \uc7ac\ud310\uc758 \uac70\ub9ac\uc758 \ubc30\uacbd\uacfc \uc804\uac1c, \uc774\ud6c4\uc758 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ub204\uad70\uac00 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc0c1\ucc98\ub97c \uc785\ud614\ub2e4. \uac19\uc740 \uc0c1\ucc98\ub77c\uba74 \ucc98\ubc8c\ub3c4 \uac19\uc744\uae4c. \ud568\ubb34\ub77c\ube44 \ubc95\uc804\uc5d0 \ub2f4\uae34 \uc870\ud56d\ub4e4\uc744 \uc77d\uc73c\uba74 \ud53c\ud574\uc790\uc640 \uac00\ud574\uc790\uc758 \uc9c0\uc704\uc5d0 \ub530\ub77c \ub2f5\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ub208\uc5d0\ub294 \ub208\uc774\ub77c\ub294 \uc9e7\uc740 \ub9d0\ub85c \uc720\uba85\ud55c \uc774 \ube44\uc11d\uc740 \uace0\ub300 \uc0ac\ud68c\uac00 \uac70\ub798\uc640 \uac00\uc871, \ub178\ub3d9\uacfc \ucc45\uc784\uc744 \uc5b4\ub5bb\uac8c \uad6c\ubd84\ud588\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \uae30\ub85d\uc774\ub2e4. \ub3d9\uc2dc\uc5d0 \uc815\uc758\ub85c\uc6b4 \uc655\uc774\ub77c\ub294 \uc774\ubbf8\uc9c0\ub97c \uc624\ub798 \ub0a8\uae30\ub824 \ud55c \uad8c\ub825\uc758 \uae30\ub150\ubb3c\uc774\uae30\ub3c4 \ud558\ub2e4. \ud568\ubb34\ub77c\ube44\ub294 \uae30\uc6d0\uc804 18\uc138\uae30 \ubc14\ube4c\ub85c\ub2c8\uc544\ub97c \ub2e4\uc2a4\ub9b0 \uc655\uc774\ub2e4. \uadf8\uc758 \ud1b5\uce58 \uc544\ub798 \ub0a8\ubd80 \uba54\uc18c\ud3ec\ud0c0\ubbf8\uc544\uc758 \uc5ec\ub7ec \uc9c0\uc5ed\uc774 \ud1b5\ud569\ub418\uc5c8\ub2e4. \uc624\ub298\ub0a0 \uc774\ub77c\ud06c\uc5d0 \ud574\ub2f9\ud558\ub294 \uc774 \uc9c0\uc5ed\uc5d0\uc11c\ub294 \ub3c4\uc2dc\uc640 \ub18d\uacbd\uc9c0, \uc6b4\ud558\ub97c \ub458\ub7ec\uc2fc \ubcf5\uc7a1\ud55c \uacbd\uc81c\uc0dd\ud65c\uc774 \uc624\ub798\uc804\ubd80\ud130 \uc774\ub8e8\uc5b4\uc9c0\uace0 \uc788\uc5c8\ub2e4. \uadf8\ub7ec\ubbc0\ub85c \ud568\ubb34\ub77c\ube44\uac00 \uc778\ub958 \ucd5c\ucd08\ub85c \ubc95\uc744 \ubc1c\uba85\ud588\ub2e4\uace0 \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \uadf8\ubcf4\ub2e4 \uc55e\uc120 \ubc95 \uad00\ub828 \uae30\ub85d\uacfc \uad00\uc2b5\uc774 \uc788\uc5c8\ub2e4. \uc774 \ube44\uc11d\uc758 \uc911\uc694\uc131\uc740 \ubb34\uc5d0\uc11c \ubc95\uc744 \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \ub370 \uc788\uc9c0 \uc54a\uace0 \uc655\uc758 \uc815\uc758\ub97c \ub0b4\uc138\uc6b4 \uae34 \uae00\uacfc \uc5ec\ub7ec \uad6c\uccb4\uc801 \ubd84\uc7c1\uc758 \uaddc\uc815\uc774 \ud568\uaed8 \uc804\ud574\uc9c4\ub2e4\ub294 \ub370 \uc788\ub2e4. \ube44\uc11d \uc717\ubd80\ubd84\uc758 \ubd80\uc870\uc5d0\ub294 \uc655\uc774 \uc549\uc544 \uc788\ub294 \uc2e0 \uc55e\uc5d0 \uc120 \uc7a5\uba74\uc774 \ud45c\ud604\ub418\uc5b4 \uc788\ub2e4. \uc2e0\uc740 \uc77c\ubc18\uc801\uc73c\ub85c \ud0dc\uc591\uacfc \uc815\uc758\uc758 \uc2e0 \uc0e4\ub9c8\uc2dc\ub85c \ud574\uc11d\ub41c\ub2e4. \uc774 \uc7a5\uba74\uc740 \uc544\ub798\uc758 \uae00\uc744 \uc77d\uae30 \uc804\ubd80\ud130 \uc655\uc758 \ud310\ub2e8\uc774 \uc2e0\uc131\ud55c \uad8c\uc704\uc640 \uc5f0\uacb0\ub41c\ub2e4\ub294 \uba54\uc2dc\uc9c0\ub97c \uc804\ud55c\ub2e4. \ubcf8\ubb38 \uc55e\ub4a4\uc758 \uae00\ub3c4 \uc815\uc758\ub85c\uc6b4 \ud1b5\uce58\uc790\ub77c\ub294 \uc655\uc758 \ubaa8\uc2b5\uc744 \uac15\uc870\ud55c\ub2e4. \uc57d\ud55c \uc0ac\ub78c\uc744 \ubcf4\ud638\ud558\uace0 \uc9c8\uc11c\ub97c \uc138\uc6b4\ub2e4\ub294 \uc8fc\uc7a5\uc740 \uc2e4\uc81c \ubc95 \uc870\ud56d\uc758 \ub0b4\uc6a9\uacfc \ud568\uaed8 \uc77d\uc5b4\uc57c \ud55c\ub2e4. \ud1b5\uce58\uc790\uac00 \uc790\uc2e0\uc744 \uc5b4\ub5bb\uac8c \uc124\uba85\ud558\ub294\uac00\uc640 \ud1b5\uce58 \uc544\ub798\uc758 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\ub450 \uac19\uc740 \ub300\uc6b0\ub97c \ubc1b\uc558\ub294\uac00\ub294 \ubcc4\uac1c\uc758 \uc9c8\ubb38\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \uc2e0\uccb4\uc5d0 \uac00\ud55c \uc190\uc0c1\uc744 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ub418\uac1a\ub294 \uaddc\uc815\uc740 \uc720\uba85\ud558\ub2e4. \uadf8\ub7ec\ub098 \ubaa8\ub4e0 \uacbd\uc6b0\uc5d0 \ub611\uac19\uc774 \uc801\uc6a9\ub41c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ub2f9\uc0ac\uc790\uc758 \uc9c0\uc704\uc5d0 \ub530\ub77c \uc2e0\uccb4\ud615\uacfc \uae08\uc804 \ubc30\uc0c1\uc774 \ub2ec\ub77c\uc9c0\ub294 \uc870\ud56d\ub4e4\uc774 \uc788\ub2e4. \ub178\uc608\uc758 \uc2e0\uccb4 \uc190\uc0c1\ub3c4 \uc790\uc720\uc778\uc758 \uacbd\uc6b0\uc640 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ucde8\uae09\ub418\uc9c0 \uc54a\uc558\ub2e4. \uc774 \ucc28\uc774\ub97c \ube7c\uace0 \ubcf5\uc218\uc758 \ubc95\uc774\ub77c\uace0\ub9cc \ubd80\ub974\uba74 \uc0ac\ud68c\uc758 \uad6c\uc870\uac00 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ubc95\uc740 \ubcf4\ubcf5\uc758 \uc815\ub3c4\ub97c \uaddc\uc815\ud558\ub294 \ub3d9\uc2dc\uc5d0 \uc0ac\ub78c\uc758 \uc9c0\uc704\ub97c \uad6c\ubd84\ud588\ub2e4. \uc624\ub298\ub0a0\uc758 \ubc95 \uc55e\uc758 \ud3c9\ub4f1\uc774\ub77c\ub294 \uc6d0\uce59\uc744 \uadf8\ub300\ub85c \uacfc\uac70\uc5d0 \ub300\uc785\ud558\uac70\ub098, \uc774 \ube44\uc11d\uc5d0 \uc774\ubbf8 \uc644\uc131\ub418\uc5b4 \uc788\uc5c8\ub2e4\uace0 \ub9d0\ud560 \uc218 \uc5c6\ub294 \uc774\uc720\ub2e4. \uc870\ud56d\ub4e4\uc740 \uc0b4\uc778\uc774\ub098 \uc0c1\ud574\ub9cc \ub2e4\ub8e8\uc9c0 \uc54a\ub294\ub2e4. \ube4c\ub9b0 \ub3c8\uacfc \ub9e1\uae34 \ubb3c\uac74, \ub9e4\ub9e4\uc640 \uc784\ub300, \ud63c\uc778\uacfc \uc0c1\uc18d \uac19\uc740 \uc0dd\ud65c\uc758 \ubb38\uc81c\ub3c4 \ub4f1\uc7a5\ud55c\ub2e4. \uc0ac\uac74\uc744 \uc785\uc99d\ud560 \uc99d\uc778\uacfc \uacc4\uc57d \uae30\ub85d\uc758 \uc5ed\ud560\uc740 \ub3c4\uc2dc \uc0ac\ud68c\uc5d0\uc11c \ub0af\uc120 \uc0ac\ub78c \uc0ac\uc774\uc758 \uac70\ub798\uac00 \uc5bc\ub9c8\ub098 \uc911\uc694\ud588\ub294\uc9c0 \ubcf4\uc5ec \uc900\ub2e4. \uc5b4\ub5a4 \uc8fc\uc7a5\uc774 \ucc38\uc778\uc9c0 \uac00\ub9ac\ub294 \ubb38\uc81c\ub294 \ud615\ubc8c\uc758 \ud06c\uae30\ub9cc\ud07c \uc911\uc694\ud588\ub2e4. \uace0\ubc1c\uacfc \uc99d\uac70, \ud310\ub2e8\uc744 \ub0b4\ub9ac\ub294 \uc0ac\ub78c\uc758 \ucc45\uc784\uc774 \uaddc\uc815\uc5d0 \ub4e4\uc5b4 \uc788\ub2e4. \uc624\ub798\ub41c \ubc95\ubb38\uc744 \uc77d\uc73c\uba70 \uc794\ud639\ud55c \ucc98\ubc8c\uc5d0\ub9cc \ub180\ub77c\uae30\ubcf4\ub2e4, \ub2e4\ud23c\uc774 \uc0dd\uacbc\uc744 \ub54c \ub204\uac00 \ubb34\uc5c7\uc744 \ubcf4\uc5ec \uc8fc\uc5b4\uc57c \ud588\ub294\uc9c0\ub3c4 \uc0b4\ud3b4\ubcfc \ub9cc\ud558\ub2e4. \ubb38\uc11c\ub97c \ub0a8\uae38 \uc218 \uc788\ub294 \uc0ac\ub78c\uacfc \uadf8\ub807\uc9c0 \ubabb\ud55c \uc0ac\ub78c\uc758 \ucc28\uc774\ub3c4 \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub2e4. \uac70\ub798\ub97c \uae00\ub85c \uc801\uc73c\ub824\uba74 \uc11c\uae30\uad00\uacfc \uc99d\uc778, \uae30\ub85d\uc744 \ubcf4\uad00\ud558\ub294 \ud658\uacbd\uc774 \ud544\uc694\ud588\ub2e4. \ubc95 \uc870\ud56d\uc5d0 \uacc4\uc57d\uc774 \ub4f1\uc7a5\ud55c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uac1c\uc778\uc758 \uc57d\uc18d\uc744 \uc0ac\ud68c\uc801\uc73c\ub85c \ud655\uc778\ud574 \uc8fc\ub294 \uc5ec\ub7ec \uc5ed\ud560\uc774 \uc774\ubbf8 \uc874\uc7ac\ud588\uc74c\uc744 \ub73b\ud55c\ub2e4. \ub18d\uacbd\uc744 \uc9c0\ud0f1\ud55c \ubb3c\uae38\uc740 \uc774\uc6c3\uc758 \uc0dd\uacc4\uc640 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc81c\ubc29\uacfc \uad00\uac1c \uc2dc\uc124\uc744 \uc81c\ub300\ub85c \uad00\ub9ac\ud558\uc9c0 \uc54a\uc544 \ud53c\ud574\uac00 \uc0dd\uae30\ub294 \uc0c1\ud669\ub3c4 \ubc95\uc774 \ub2e4\ub8e8\uc5c8\ub2e4. \uac1c\uc778\uc758 \ubd80\uc8fc\uc758\ub97c \uac1c\uc778\uc758 \uc0ac\uc815\uc73c\ub85c\ub9cc \ub458 \uc218 \uc5c6\ub294 \ud658\uacbd\uc774\uc5c8\ub2e4. \ubb3c\uc740 \uacf5\ub3d9\uc758 \uae30\ubc18\uc774\uba74\uc11c \ubd84\uc7c1\uc758 \uc6d0\uc778\uc774\uc5c8\ub2e4. \uc9d1\uc744 \uc9c0\uc740 \uc0ac\ub78c\uc758 \ucc45\uc784\uc5d0 \uad00\ud55c \uc5c4\uaca9\ud55c \uc870\ud56d\ub3c4 \ub110\ub9ac \uc54c\ub824\uc838 \uc788\ub2e4. \ub2e4\ub9cc \uace0\ub300\uc758 \ucc98\ubc8c\uc744 \uc624\ub298\ub0a0 \uac74\ucd95 \uc548\uc804\uc758 \ubaa8\ubc94\uc73c\ub85c \uace7\ubc14\ub85c \uce6d\ucc2c\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc704\ud5d8\uc744 \ub204\uac00 \ubd80\ub2f4\ud588\ub294\uc9c0\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc790\ub8cc\ub85c \uc77d\uace0, \uac00\uc871\uacfc \uc2e0\ubd84\uc5d0 \ub530\ub978 \ucc45\uc784 \uc804\uac00\uae4c\uc9c0 \ud568\uaed8 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \ube44\uc11d\uc758 \ubb38\uc7a5\ub4e4\uc774 \ubaa8\ub4e0 \uc7ac\ud310\uc5d0\uc11c \ube60\uc9d0\uc5c6\uc774 \ubb38\uc790 \uadf8\ub300\ub85c \uc9d1\ud589\ub418\uc5c8\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc655\uc758 \uaddc\ubc94 \uc120\uc5b8\uacfc \uc2e4\uc81c \ubd84\uc7c1 \ud574\uacb0\uc758 \uad00\uacc4\ub97c \ubc1d\ud788\ub824\uba74 \ub2f9\uc2dc\uc758 \uacc4\uc57d \ubb38\uc11c\uc640 \uc7ac\ud310 \uae30\ub85d \ub4f1\ub3c4 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ud558\ub098\uc758 \uc720\uba85\ud55c \uc720\ubb3c\uc774 \uc0dd\ud65c \uc804\uccb4\ub97c \ub300\uc2e0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc624\ub298\ub0a0 \uc870\ud56d\uc5d0 \ubd99\uc774\ub294 \ubc88\ud638 \uc5ed\uc2dc \ub0b4\uc6a9\uc744 \ucc3e\uae30 \uc704\ud55c \ud604\ub300 \uc5f0\uad6c\uc758 \uad6c\ubd84\uc774\ub2e4. \ub3cc\uc5d0 \uc0c8\uaca8\uc9c4 \uae00\uc744 \ud604\ub300\uc758 \ubc95\ub960\uc9d1\uacfc \uac19\uc740 \ud615\ud0dc\ub85c \uc0c1\uc0c1\ud558\uba74 \uc6d0\ub798 \uae30\ub150\ubb3c\uc758 \uc131\uaca9\uc744 \ub193\uce58\uac8c \ub41c\ub2e4. \uae00\uacfc \ubd80\uc870, \uc655\uc758 \uae34 \uc790\uae30 \uc124\uba85\uc774 \uacb0\ud569\ub41c \ubb3c\uac74\uc73c\ub85c \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc624\ub798\ub41c \ubc88\uc5ed\uc5d0\uc11c \uc5b4\ub5a4 \uc9c0\uc704\ub97c \uac00\ub09c\ud55c \uc0ac\ub78c\uc73c\ub85c \uc62e\uacbc\ub2e4\uace0 \ud574\uc11c \uc624\ub298\ub0a0\uc758 \uc18c\ub4dd \uacc4\uce35\uacfc \uadf8\ub300\ub85c \uac19\ub2e4\uace0 \ubcfc \uc218\ub294 \uc5c6\ub2e4. \ubc95\uc801 \uc9c0\uc704\uc640 \uacbd\uc81c\uc801 \ud615\ud3b8\uc740 \uad00\ub828\ub418\uc9c0\ub9cc \uac19\uc740 \uac1c\ub150\uc740 \uc544\ub2c8\ub2e4. \uc775\uc219\ud55c \ubc88\uc5ed\uc5b4 \ud558\ub098\uac00 \uace0\ub300 \uc0ac\ud68c\uc758 \ucc28\uc774\ub97c \uac00\ub9b4 \uc218 \uc788\ub2e4\ub294 \uc810\ub3c4 \uc8fc\uc758\ud574\uc11c \uc77d\uc5b4\uc57c \ud55c\ub2e4. \ube44\uc11d\uc740 20\uc138\uae30 \ucd08 \uc624\ub298\ub0a0 \uc774\ub780\uc758 \uc218\uc0ac\uc5d0\uc11c \ubc1c\uacac\ub418\uc5c8\ub2e4. \ubc14\ube4c\ub85c\ub2c8\uc544\uc758 \ubc95\uc774 \ub2f4\uae34 \uc720\ubb3c\uc774 \uc65c \ub2e4\ub978 \uc9c0\uc5ed\uc5d0\uc11c \ub098\uc654\ub294\uc9c0 \ubb3b\ub294 \uc21c\uac04, \ubb3c\uac74\uc774 \uc815\ubcf5\uacfc \uc774\ub3d9\uc744 \uacaa\uc5b4 \uc628 \uc5ed\uc0ac\ub3c4 \ub4dc\ub7ec\ub09c\ub2e4. \ubc1c\uacac \uc7a5\uc18c\uc640 \uadf8 \uae00\uc774 \ub2e4\ub8e8\ub294 \ud1b5\uce58 \uc601\uc5ed\uc740 \uac19\uc9c0 \uc54a\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \uc2e4\uc81c \ube44\uc11d \uc717\ubd80\ubd84\uc744 \uc7ac\ud604\ud55c \uc5ed\uc0ac \ucd9c\ud310 \ub3c4\ud310\uc774\ub2e4. \uc0c1\uc0c1\uc73c\ub85c \ub9cc\ub4e0 \uc655\uc758 \ucd08\uc0c1\uc774 \uc544\ub2c8\ub2e4. \uc624\ub798\ub41c \ubc88\uc5ed\uc11c\uc5d0 \uc2e4\ub9b0 \ud568\ubb34\ub77c\ube44\uc758 \uc5f0\ub300\ub294 \uc9c0\uae08\uc758 \uc5f0\uad6c\uc640 \ub2e4\ub974\ubbc0\ub85c \uadf8\ub300\ub85c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uc558\ub2e4. \ub3cc\uc5d0 \ub0a8\uc740 \uae00\uc744 \uc77d\ub294 \uc77c\ub3c4 \ud6c4\ub300\uc758 \ubc88\uc5ed\uacfc \ud574\uc11d\uc744 \ub2e4\uc2dc \uac80\ud1a0\ud558\ub294 \uc791\uc5c5\uc744 \ud544\uc694\ub85c \ud55c\ub2e4."}, {"id": "hanseatic-league-towns-kontors-and-privileges", "title": "\ud55c\uc790\ub3d9\ub9f9 \u2014 \uc655\uad6d\uc774 \uc544\ub2cc \ub3c4\uc2dc\ub4e4\uc740 \uc5b4\ub5bb\uac8c \ubc14\ub2e4\ub97c \uc5f0\uacb0\ud588\uc744\uae4c", "summary": "\ubc1c\ud2b8\ud574\uc640 \ubd81\ud574\uc758 \uc0c1\ud488, \ucf58\ud1a0\uc5b4\uc640 \ub3c4\uc2dc\ub4e4\uc758 \ub290\uc2a8\ud55c \ud611\ub825\uc758 \ubc30\uacbd\uacfc \uc804\uac1c, \uc774\ud6c4\uc758 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities", "industry"], "url": "stories/hanseatic-league-towns-kontors-and-privileges/index.html", "image": "../media/hanseatic-league-towns-kontors-and-privileges.jpg", "alt": "\ub93c\ubca0\ud06c \ud640\uc288\ud150 \ubb38\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc5ed\uc0ac \ucd9c\ud310 \ub3c4\ud310", "text": "\ud55c\uc790\ub3d9\ub9f9 \u2014 \uc655\uad6d\uc774 \uc544\ub2cc \ub3c4\uc2dc\ub4e4\uc740 \uc5b4\ub5bb\uac8c \ubc14\ub2e4\ub97c \uc5f0\uacb0\ud588\uc744\uae4c \ubc1c\ud2b8\ud574\uc640 \ubd81\ud574\uc758 \uc0c1\ud488, \ucf58\ud1a0\uc5b4\uc640 \ub3c4\uc2dc\ub4e4\uc758 \ub290\uc2a8\ud55c \ud611\ub825 \ubc1c\ud2b8\ud574\uc640 \ubd81\ud574\uc758 \uc0c1\ud488, \ucf58\ud1a0\uc5b4\uc640 \ub3c4\uc2dc\ub4e4\uc758 \ub290\uc2a8\ud55c \ud611\ub825\uc758 \ubc30\uacbd\uacfc \uc804\uac1c, \uc774\ud6c4\uc758 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ub93c\ubca0\ud06c\uc640 \ud568\ubd80\ub974\ud06c, \ubc1c\ud2b8\ud574\uc640 \ubd81\ud574\uc758 \ud56d\uad6c\ub4e4\uc740 \ud558\ub098\uc758 \uc655\uc774 \ub2e4\uc2a4\ub9b0 \uad6d\uac00\uac00 \uc544\ub2c8\uc5c8\ub2e4. \uadf8\ub7f0\ub370\ub3c4 \uc0c1\uc778\ub4e4\uc740 \uc5ec\ub7ec \ub3c4\uc2dc\ub97c \uc624\uac00\uba70 \uac70\ub798\ud558\uace0 \uacf5\ub3d9\uc758 \ud2b9\uad8c\uc744 \uc9c0\ud0a4\ub824 \ud588\ub2e4. \ud55c\uc790\ub3d9\ub9f9\uc740 \uadf8 \ub290\uc2a8\ud558\uace0 \ub048\uc9c8\uae34 \uc5f0\uacb0\uc758 \uc5ed\uc0ac\ub2e4. \ud604\ub300\uc758 \uad6d\uac00 \uc5f0\ud569\uc774\ub098 \uac70\ub300\ud55c \ud55c \ud68c\uc0ac\uc640 \ub2e4\ub978 \uc870\uc9c1\uc744 \uc5b4\ub5bb\uac8c \uc77d\uc5b4\uc57c \ud560\uae4c. \uba3c \uacf3\uc5d0\uc11c \uc7a5\uc0ac\ud558\ub824\uba74 \uc0c1\ud488\ub9cc \uc788\uc73c\uba74 \ub418\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \ubc30\ub97c \ub300\uace0 \ubb3c\uac74\uc744 \ubcf4\uad00\ud560 \uc7a5\uc18c, \uac70\ub798\ub97c \uc778\uc815\ubc1b\uc744 \uad8c\ub9ac\uc640 \ubd84\uc7c1\uc744 \ud574\uacb0\ud560 \ubc29\ubc95\uc774 \ud544\uc694\ud588\ub2e4. \uc678\uc9c0 \uc0c1\uc778\uc740 \ub0af\uc120 \ub3c4\uc2dc\uc758 \uaddc\uce59\uacfc \uc138\uae08, \uc704\ud5d8\uc744 \ud63c\uc790 \uc0c1\ub300\ud574\uc57c \ud560 \uc218 \uc788\uc5c8\ub2e4. \uc0c1\uc778\ub4e4\uc740 \uc9d1\ub2e8\uc73c\ub85c \uc6c0\uc9c1\uc774\uba70 \ubcf4\ud638\uc640 \ud2b9\uad8c\uc744 \uad6c\ud588\ub2e4. \uc774\ub7f0 \uacb0\ud569\uacfc \ub3c4\uc2dc \uc0ac\uc774\uc758 \ud611\ub825\uc774 \uc624\ub7ab\ub3d9\uc548 \uc313\uc5ec \ud55c\uc790\ub77c\ub294 \uc774\ub984 \uc544\ub798 \uc5f0\uacb0\ub418\uc5c8\ub2e4. \uc5b4\ub290 \ub0a0 \ub300\ud45c\ub4e4\uc774 \ud55c\uacf3\uc5d0\uc11c \uc644\uc131\ub41c \ud5cc\ubc95\uc5d0 \uc11c\uba85\ud574 \uad6d\uac00\ucc98\ub7fc \ucd9c\ubc94\ud55c \uc870\uc9c1\uc73c\ub85c \uc0c1\uc0c1\ud558\uba74 \uc2e4\uc81c\uc758 \ubcf5\uc7a1\ud55c \uc131\uaca9\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \ubc30 \ud55c \ucc99\uc774 \ub09c\ud30c\ud558\uac70\ub098 \ud1b5\uce58\uc790\uac00 \uc678\uad6d \uc0c1\uc778\uc758 \ubb3c\uac74\uc744 \uc555\uc218\ud558\uba74 \uc190\ud574\ub97c \ub418\ucc3e\uae30 \uc5b4\ub824\uc6e0\ub2e4. \uac19\uc740 \ucd9c\uc2e0\uc758 \uc0c1\uc778\ub4e4\uc774 \uc11c\ub85c \uc5f0\ub77d\ud558\uace0 \ub3c4\uc2dc\uac00 \ud611\uc0c1\uc744 \uc9c0\uc6d0\ud558\ub294 \uac83\uc740 \uc774\ub7f0 \uc704\ud5d8\uc744 \ub098\ub204\ub294 \ubc29\ubc95\uc774\uc5c8\ub2e4. \uad50\uc5ed\uc758 \uc5ed\uc0ac\ub294 \ubb3c\uac74\uc744 \uc2f8\uac8c \uc0ac\ub294 \uae30\uc220\ubfd0 \uc544\ub2c8\ub77c \ubd88\ud655\uc2e4\ud55c \uac70\ub798\ub97c \uc9c0\uc18d\ud560 \uc7a5\uce58\ub97c \ub9cc\ub4dc\ub294 \uc5ed\uc0ac\uc774\uae30\ub3c4 \ud558\ub2e4. \ub93c\ubca0\ud06c\ub294 \ubc1c\ud2b8\ud574 \ucabd \uad50\uc5ed\uc5d0\uc11c \uc911\uc694\ud55c \uc790\ub9ac\ub97c \ucc28\uc9c0\ud588\ub2e4. \ubd81\ud574\uc640 \uc774\uc5b4\uc9c0\ub294 \uae38, \uc8fc\ubcc0\uc758 \uc5ec\ub7ec \ud56d\uad6c\uc640 \ubc30\ud6c4 \uc9c0\uc5ed\uc744 \ud568\uaed8 \uc0dd\uac01\ud558\uba74 \uc704\uce58\uc758 \uc758\ubbf8\uac00 \ubcf4\uc778\ub2e4. \ud55c \ub3c4\uc2dc\uac00 \ubc14\ub2e4\uc640 \uc721\uc9c0\uc758 \ub2e4\ub978 \uacbd\ub85c\ub97c \uc5f0\uacb0\ud558\ub294 \uc5ed\ud560\uc744 \ud560 \uc218 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4. \ub3c4\uc2dc\uc758 \ubd80\ub294 \uc790\uae30 \uc548\uc5d0\uc11c \uc0dd\uc0b0\ud55c \uac83\uc5d0\ub9cc \ub2ec\ub9b0 \uac83\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ub2e4\ub978 \uacf3\uc758 \uc0c1\ud488\uc774 \uc9c0\ub098\uac00\uace0 \uacc4\uc57d\uacfc \ubcf4\uad00, \uc6b4\uc1a1\uc758 \uc77c\uc774 \ubaa8\uc600\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub93c\ubca0\ud06c\uac00 \ubaa8\ub4e0 \uac70\ub798\uc640 \ud68c\uc6d0 \ub3c4\uc2dc\ub97c \uc5b8\uc81c\ub098 \uba85\ub839\uc73c\ub85c \uc9c0\ubc30\ud55c \uc218\ub3c4\uc600\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud55c\uc790 \uad50\uc5ed\uc758 \uc8fc\uc778\uacf5\uc740 \uc655\uc2e4\uc758 \ubcf4\uc11d\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uccad\uc5b4\uc640 \ub9d0\ub9b0 \uc0dd\uc120, \uace1\ubb3c\uacfc \ubaa9\uc7ac, \uc18c\uae08\uacfc \ucc9c, \ubc00\ub78d\uacfc \ubaa8\ud53c\ucc98\ub7fc \uc2dd\ud0c1\uacfc \uc791\uc5c5\uc7a5\uc5d0 \ud544\uc694\ud55c \ubb3c\ud488\uc774 \ubc14\ub2e4\ub97c \uac74\ub11c\ub2e4. \uc5b4\ub514\uc5d0\uc11c \ub9ce\uc774 \uc0dd\uc0b0\ub418\uace0 \uc5b4\ub514\uc5d0\uc11c \ud544\uc694\ub85c \ud558\ub294\uc9c0\uac00 \ud56d\ub85c\ub97c \ub9cc\ub4e4\uc5c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc0dd\uc120\uc744 \uc624\ub798 \ubcf4\uad00\ud558\ub824\uba74 \uc18c\uae08\uacfc \uac00\uacf5, \uc6b4\uc1a1\uc774 \ud568\uaed8 \ud544\uc694\ud558\ub2e4. \uc0c1\ud488 \ud558\ub098\uc758 \uc774\ub984 \ub4a4\uc5d0\ub3c4 \uc5ec\ub7ec \uc9c0\uc5ed\uc758 \uc77c\uc774 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uad50\uc5ed\uc744 \ubc30\uac00 \ud56d\uad6c \ub450 \uacf3 \uc0ac\uc774\ub97c \ud55c \ubc88 \uc6c0\uc9c1\uc774\ub294 \uc7a5\uba74\uc73c\ub85c\ub9cc \ubcf4\uba74 \uc774\ub7f0 \uc0dd\uc0b0\uacfc \uc0dd\ud65c\uc758 \uc5f0\uacb0\uc744 \ub193\uce58\uae30 \uc27d\ub2e4. \uace1\ubb3c\uc744 \ub0b4\ubcf4\ub0b4\ub294 \uc9c0\uc5ed\uacfc \uc0dd\uc120\uc744 \uac00\uacf5\ud558\ub294 \uc9c0\uc5ed, \uc9c1\ubb3c\uc744 \uacf5\uae09\ud558\ub294 \uc9c0\uc5ed\uc740 \uc11c\ub85c \ub2e4\ub978 \uacc4\uc808\uacfc \uc0dd\uc0b0 \uc870\uac74\uc744 \uac00\uc84c\ub2e4. \ud56d\uad6c\uc758 \uac70\ub798\ub294 \uadf8 \ucc28\uc774\ub97c \uc774\uc6a9\ud588\ub2e4. \ud55c\uc790 \uc804\uccb4\ub97c \ud2b9\uc815 \uc0c1\ud488\uc758 \ub3c5\uc810\uc73c\ub85c\ub9cc \uc774\ud574\ud558\uba74 \uc5ec\ub7ec \uc2dc\uc7a5\uc744 \uc774\uc5b4 \uc8fc\uc5c8\ub358 \ub2e4\uc591\ud55c \uc6b4\uc1a1\uacfc \uc911\uac1c \ud65c\ub3d9\uc774 \uac00\ub824\uc9c4\ub2e4. \ud55c\uc790 \uc0c1\uc778\ub4e4\uc740 \ub7f0\ub358\u00b7\ube0c\ub93c\ud5c8\u00b7\ubca0\ub974\uac90\u00b7\ub178\ube0c\uace0\ub85c\ub4dc \uac19\uc740 \uacf3\uc5d0 \uc911\uc694\ud55c \ud574\uc678 \uac70\uc810\uc744 \ub450\uc5c8\ub2e4. \ucf58\ud1a0\uc5b4\ub85c \ubd80\ub974\ub294 \uc774\ub7f0 \uc7a5\uc18c\ub294 \uac70\ub798\uc640 \ubcf4\uad00, \uacf5\ub3d9\uc0dd\ud65c\uacfc \uaddc\uce59\uc744 \uac16\ucd98 \uc0c1\uc778 \uc9d1\ub2e8\uc758 \uae30\ubc18\uc774\uc5c8\ub2e4. \uc61b \uc601\uc5b4 \uc790\ub8cc\uc758 \ud329\ud1a0\ub9ac\ub77c\ub294 \ub9d0\uc744 \uc624\ub298\uc758 \uc81c\uc870 \uacf5\uc7a5\uc73c\ub85c \ubc88\uc5ed\ud558\uba74 \uc624\ud574\uac00 \uc0dd\uae34\ub2e4. \uc678\uad6d\uc758 \ud1b5\uce58\uc790\ub098 \ub3c4\uc2dc\uc5d0\uac8c \ubc1b\uc740 \ud2b9\uad8c\uc740 \uc601\uad6c\ud788 \ub2f9\uc5f0\ud55c \uac83\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ud611\uc0c1\uacfc \ubb38\uc11c, \ud604\uc9c0 \uc138\ub825\uacfc\uc758 \uac08\ub4f1 \uc18d\uc5d0\uc11c \uc9c0\ud0a4\uace0 \ubc14\uafb8\uc5b4\uc57c \ud588\ub2e4. \ud55c\uc790\uc758 \ub124\ud2b8\uc6cc\ud06c\ub294 \ubc14\ub2e4 \uc704 \ud56d\ub85c\uc640 \ud56d\uad6c \uc548\uc758 \ubc95\uc801 \uc790\ub9ac\ub97c \ud568\uaed8 \uac00\uc9c4 \uc870\uc9c1\uc774\uc5c8\ub2e4. \uac70\uc810\uc758 \uaddc\uce59\uc740 \uc0c1\uc778\ub4e4\uc758 \ud589\ub3d9\uacfc \uacf5\ub3d9\uc758 \uc774\uc775\uc744 \uad00\ub9ac\ud558\ub294 \uc5ed\ud560\uc744 \ud588\ub2e4. \uc678\uad6d \ub3c4\uc2dc \uc548\uc5d0\uc11c \uc9d1\ub2e8\uc758 \uc2e0\ub8b0\ub97c \uc9c0\ud0a4\ub824\uba74 \uac1c\uc778\uc758 \uac70\ub798\ub3c4 \uacf5\ub3d9\uccb4\uc758 \ud3c9\ud310\uacfc \uc5f0\uacb0\ub418\uc5c8\ub2e4. \ubcf4\ud638\ub97c \ubc1b\ub294 \ub300\uc2e0 \uc77c\uc815\ud55c \ud1b5\uc81c\ub97c \ubc1b\uc544\uc57c \ud55c\ub2e4\ub294 \uad00\uacc4\ub294 \ub290\uc2a8\ud55c \ub3c4\uc2dc \uc5f0\ud569 \uc548\uc5d0\uc11c\ub3c4 \uc874\uc7ac\ud560 \uc218 \uc788\uc5c8\ub2e4. \ub3c4\uc2dc \ub300\ud45c\ub4e4\uc758 \ud68c\uc758\ub294 \uacf5\ub3d9\uc758 \ubb38\uc81c\ub97c \ub2e4\ub8e8\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \ub3c4\uc2dc\ub9c8\ub2e4 \uac70\ub798 \uc0c1\ub300\uc640 \uc774\uc775, \uc8fc\ubcc0 \uad70\uc8fc\uc758 \uc555\ub825\uc774 \ub2ec\ub790\ub2e4. \uc5b4\ub5a4 \uc870\uce58\uc5d0 \uc801\uadf9 \ucc38\uc5ec\ud558\ub294 \ub3c4\uc2dc\uac00 \uc788\ub294\uac00 \ud558\uba74 \ubd80\ub2f4\uc744 \ud53c\ud558\uac70\ub098 \ub2e4\ub978 \uae38\uc744 \ucc3e\ub294 \ub3c4\uc2dc\ub3c4 \uc788\uc5c8\ub2e4. \uc774 \ub290\uc2a8\ud568\uc744 \uc870\uc9c1\uc774 \uc81c\ub300\ub85c \uc874\uc7ac\ud558\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc99d\uac70\ub85c\ub9cc \ubcfc \ud544\uc694\ub294 \uc5c6\ub2e4. \uc911\uc559\uc815\ubd80\uac00 \ubaa8\ub4e0 \uaddc\uce59\uc744 \uac15\uc81c\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc774\uc775\uacfc \uc2e0\ub8b0, \ubc18\ubcf5\ub418\ub294 \ud611\ub825\uc73c\ub85c \uc5f0\uacb0\uc744 \uc720\uc9c0\ud560 \uc218 \uc788\uc5c8\ub2e4. \ubc18\ub300\ub85c \uacf5\ud1b5\uc758 \uc774\ub984\uc774 \uc788\ub2e4\uace0 \ud68c\uc6d0\uc758 \uc774\ud574\uac00 \ud56d\uc0c1 \ud558\ub098\uc600\ub358 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uacf5\ub3d9 \ud589\ub3d9\uc5d0\ub294 \ub3c8\uacfc \uc120\ubc15, \uc2dc\uac04\uc774 \ub4e4\uc5c8\ub2e4. \uac19\uc740 \ud56d\ub85c\ub97c \ub35c \uc774\uc6a9\ud558\ub294 \ub3c4\uc2dc\ub77c\uba74 \ub2e4\ub978 \ub3c4\uc2dc\uac00 \uc6d0\ud558\ub294 \uc81c\uc7ac\ub098 \uc804\uc7c1\uc5d0 \uc18c\uadf9\uc801\uc77c \uc218 \uc788\uc5c8\ub2e4. \ud611\ub825\uc758 \uc131\uacfc\ub9cc \uc138\uba74 \uc774\ub7f0 \ubd80\ub2f4\uc758 \ucc28\uc774\uac00 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ud55c\uc790\uc758 \uae34 \uc5ed\uc0ac\ub294 \uc774\ud574\uad00\uacc4\uc758 \ucc28\uc774\ub97c \uc5c6\uc560\uc9c0 \uc54a\uace0 \uc870\uc815\ud558\ub824 \ud55c \uacfc\uc815\uc73c\ub85c\ub3c4 \uc77d\ud78c\ub2e4. \ud55c\uc790 \ub3c4\uc2dc\ub4e4\uc740 \uc678\uad50\uc640 \uac70\ub798 \uc911\ub2e8, \ub54c\ub85c\ub294 \ubb34\ub825\uc744 \ud1b5\ud574 \uc774\uc775\uc744 \uc9c0\ud0a4\ub824 \ud588\ub2e4. 1370\ub144 \uc288\ud2b8\ub784\uc900\ud2b8 \uc870\uc57d\uc740 \ub374\ub9c8\ud06c\uc640\uc758 \ucda9\ub3cc \uc18d\uc5d0\uc11c \ud55c\uc790\uc758 \ud798\uc774 \ub4dc\ub7ec\ub09c \uc0ac\ub840\ub2e4. \uc7a5\uc0ac\uc640 \uc815\uce58, \uad70\uc0ac\ub825\uc774 \uc644\uc804\ud788 \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\uc558\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc0c1\uc778\uc5d0\uac8c \ud3b8\ub9ac\ud55c \ud2b9\uad8c\uc774 \ud604\uc9c0\uc758 \ub2e4\ub978 \uc0c1\uc778\uacfc \uc8fc\ubbfc\uc5d0\uac8c\ub3c4 \uacf5\uc815\ud55c \uaddc\uce59\uc774\uc5c8\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uad50\uc5ed\uc758 \ud655\uc7a5\uc740 \ud611\ub825\ubfd0 \uc544\ub2c8\ub77c \uacbd\uc7c1\uacfc \ubc30\uc81c\ub97c \ub0b3\uc558\ub2e4. \uc131\uacf5\ud55c \uc0c1\uc5c5 \ub124\ud2b8\uc6cc\ud06c\ub77c\ub294 \ud3c9\uac00\uc640 \uadf8 \uc548\ud30e\uc758 \uad8c\ub825 \ucc28\uc774\ub97c \ud568\uaed8 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \ub300\uc11c\uc591 \ud56d\ub85c\uc758 \ud655\ub300\uc640 \uad70\uc8fc \uad6d\uac00\uc758 \uc131\uc7a5, \ub3c4\uc2dc\ubcc4 \uc774\ud574\uc758 \ubcc0\ud654 \uc18d\uc5d0\uc11c \ud55c\uc790\uc758 \uc601\ud5a5\ub825\uc740 \ub2ec\ub77c\uc84c\ub2e4. \ub9c8\uc9c0\ub9c9 \ud68c\uc758\ub77c\ub294 \uc5f0\ub300\ub97c \ucc3e\ub294 \uc77c\ub9cc\uc73c\ub85c \ub05d\uc744 \uc124\uba85\ud558\uae30 \uc5b4\ub835\ub2e4. \uc5b4\ub5a4 \uc5f0\uacb0\uacfc \ud2b9\uad8c\uc740 \uc57d\ud574\uc9c0\uace0 \ub2e4\ub978 \ud615\ud0dc\ub85c \ub0a8\uc558\ub2e4. \uc5ec\uae30 \uc2e4\uc740 \uac83\uc740 \ub93c\ubca0\ud06c\uc758 \ud640\uc288\ud150 \ubb38\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc5ed\uc0ac \ub3c4\ud310\uc774\ub2e4. \ud55c\uc790 \ud65c\ub3d9\uc774 \uc2dc\uc791\ub418\ub294 \uc21c\uac04\uc758 \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \uc5ec\ub7ec \ud604\ub300 \uad6d\uac00\uc5d0 \uac78\uce5c \uc5ed\uc0ac\ub97c \ub3c5\uc77c \ubd81\ubd80 \ub3c4\uc2dc\uc758 \ub9e5\ub77d\uc5d0\uc11c \uc77d\ub418, \ud55c\uc790\ub97c \uc624\ub298\ub0a0 \ub3c5\uc77c\uc774\ub77c\ub294 \uad6d\uac00\uc758 \uc61b \ud68c\uc0ac\ub85c \uc0dd\uac01\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \ucd9c\ubc1c\uc810\uc774\ub2e4."}, {"id": "harappa-seal-and-distant-trade", "title": "\ud558\ub77c\ud30c \u2014 \uc791\uc740 \uc778\uc7a5\uc740 \uc65c \uba3c \ub3c4\uc2dc\uc5d0\uc11c \ub098\uc654\uc744\uae4c", "summary": "\uc778\ub354\uc2a4 \ubb38\uba85\uc758 \uc2e4\uc81c \uc778\uc7a5\uacfc \ud604\ub300 \uc555\uc778 \uc0ac\uc9c4\uc744 \ubcf4\uba70 \ub3c4\uc2dc\uc758 \uad50\uc5ed, \ud45c\uc2dc\uc640 \ud574\ub3c5\uc758 \ucc28\uc774\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/harappa-seal-and-distant-trade/index.html", "image": "../media/harappa-seal-and-distant-trade.jpg", "alt": "\uc778\ub354\uc2a4 \ubb38\uba85\uc758 \ub3d9\ubb3c\uacfc \uae30\ud638\uac00 \uc0c8\uaca8\uc9c4 \uc2e4\uc81c \uc778\uc7a5 \uc67c\ucabd, \ud604\ub300\uc5d0 \ub9cc\ub4e0 \uc810\ud1a0 \uc555\uc778 \uc624\ub978\ucabd.", "text": "\ud558\ub77c\ud30c \u2014 \uc791\uc740 \uc778\uc7a5\uc740 \uc65c \uba3c \ub3c4\uc2dc\uc5d0\uc11c \ub098\uc654\uc744\uae4c \uc544\uc9c1 \uc77d\uc9c0 \ubabb\ud55c \uae00\uc790\uc640 \ubb3c\uac74\uc774 \uac74\ub108\uac04 \uae38 \uc778\ub354\uc2a4 \ubb38\uba85\uc758 \uc2e4\uc81c \uc778\uc7a5\uacfc \ud604\ub300 \uc555\uc778 \uc0ac\uc9c4\uc744 \ubcf4\uba70 \ub3c4\uc2dc\uc758 \uad50\uc5ed, \ud45c\uc2dc\uc640 \ud574\ub3c5\uc758 \ucc28\uc774\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc190\ubc14\ub2e5\ubcf4\ub2e4 \uc791\uc740 \uc778\uc7a5 \ud558\ub098\uc5d0\ub294 \ub3d9\ubb3c\uacfc \uc9e7\uc740 \uae30\ud638\ub4e4\uc774 \uc0c8\uaca8\uc838 \uc788\ub2e4. \ud070 \uad81\uc804\uc774\ub098 \uc655\uc758 \ubb34\ub364\ucc98\ub7fc \uc2dc\uc120\uc744 \uc555\ub3c4\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub7f0\ub370 \uc774\ub7f0 \uc791\uc740 \ubb3c\uac74\uc740 \uc624\ub798\ub41c \ub3c4\uc2dc\uac00 \ub2e4\ub978 \uc9c0\uc5ed\uacfc \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ub418\uc5c8\ub294\uc9c0 \ubb3b\ub294 \uc911\uc694\ud55c \ub2e8\uc11c\uac00 \ub41c\ub2e4. \uc778\ub354\uc2a4 \ubb38\uba85\uc758 \ud558\ub77c\ud30c\ub97c \ub9cc\ub0a0 \ub54c\ub3c4 \uadf8\ub807\ub2e4. \ub3c4\uc2dc\uc758 \uc774\ub984\uc740 \ub0af\uc124\uc5b4\ub3c4 \ubb3c\uac74\uc5d0 \ud45c\uc2dc\ub97c \ub0a8\uae30\uace0 \ub2e4\ub978 \uacf3\uc73c\ub85c \ubcf4\ub0b4\ub294 \uc77c\uc740 \uc775\uc219\ud558\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc2e4\uc81c \uc778\uc7a5 \uc0ac\uc9c4\uc5d0\uc11c \ucd9c\ubc1c\ud574, \uc61b \uc0ac\ub78c\ub4e4\uc740 \ubb34\uc5c7\uc744 \uad6c\ubcc4\ud558\ub824 \ud588\uace0 \uc6b0\ub9ac\ub294 \uc5b4\ub514\uae4c\uc9c0 \uc77d\uc744 \uc218 \uc788\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc778\ub354\uc2a4 \ubb38\uba85\uc740 \uc624\ub298\ub0a0 \ud30c\ud0a4\uc2a4\ud0c4\uacfc \uc778\ub3c4\uc5d0 \uac78\uce5c \ub113\uc740 \uc9c0\uc5ed\uc5d0\uc11c \ubc1c\uc804\ud588\ub2e4. \ud558\ub77c\ud30c\ub294 \uadf8 \ub300\ud45c\uc801\uc778 \uace0\uace0\ud559 \uc720\uc801 \uac00\uc6b4\ub370 \ud558\ub098\ub2e4. \uad50\uc7ac\ub294 \uadfc\ub300\uc758 \uc5f0\uad6c\uc5d0\uc11c \ud558\ub77c\ud30c\uac00 \uc77c\ucc0d \uc54c\ub824\uc9c4 \uc8fc\uc694 \uc720\uc801\uc774\uc5b4\uc11c \uc774 \ubb38\uba85\uc744 \ud558\ub77c\ud30c \ubb38\uba85\uc774\ub77c\uace0\ub3c4 \ubd80\ub978\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub3c4\uc2dc \ud558\ub098\uc758 \uc774\ub984\uc774 \ub113\uc740 \ubb38\ud654\ub97c \uac00\ub9ac\ud0a4\ub294 \ub9d0\uc774 \ub41c \uc148\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \uadf8 \ub113\uc740 \uc9c0\uc5ed\uc774 \uc5b8\uc81c\ub098 \ud55c \uc655\uc758 \uba85\ub839 \uc544\ub798 \uc6c0\uc9c1\uc600\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc815\uce58 \uc870\uc9c1\uc758 \ubaa8\uc2b5\uc5d0\ub294 \uc544\uc9c1 \ubd88\ud655\uc2e4\ud55c \ubd80\ubd84\uc774 \uc788\ub2e4. \uac19\uc740 \uc774\ub984\uc73c\ub85c \ubb36\ub294 \uc77c\uacfc \uc2e4\uc81c \ud1b5\uce58 \ubc29\uc2dd\uc744 \uc544\ub294 \uc77c\uc740 \uad6c\ubcc4\ud560 \ud544\uc694\uac00 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc778\ub354\uc2a4 \ub3c4\uc2dc\ub4e4\uc5d0\uc11c \uc798 \uc815\ub9ac\ub41c \uac70\ub9ac\uc640 \uc8fc\uac70 \uad6c\uc5ed, \uc791\uc5c5\uc7a5, \ubc30\uc218 \uc2dc\uc124\uc774 \ubc1c\uacac\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud558\ub77c\ud30c\uc5d0\ub3c4 \ubb3c\uac74\uc744 \ub9cc\ub4dc\ub294 \uad6c\uc5ed\uacfc \ub178\ub3d9\uc790\uc758 \uac70\uc8fc \ud754\uc801\uc774 \uc788\uc5c8\ub2e4. \ub3c4\uc2dc\uc758 \ud798\uc740 \ub208\uc5d0 \ub744\ub294 \uae30\ub150\ubb3c\ubfd0 \uc544\ub2c8\ub77c \uc77c\uc0c1\uc744 \uc870\uc9c1\ud558\ub294 \uc2dc\uc124\uc5d0\uc11c\ub3c4 \ub4dc\ub7ec\ub09c\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \uc720\uc801\uc758 \uc2dc\uc124\uc774 \ub611\uac19\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ubaa8\ud5e8\uc870\ub2e4\ub85c\uc5d0\uc11c \ud655\uc778\ub41c \ud2b9\uc815 \uac74\ubb3c\uc744 \uadf8\ub300\ub85c \ud558\ub77c\ud30c\uc758 \uac74\ubb3c\ub85c \uc62e\uaca8 \ub9d0\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc5ec\ub7ec \ub3c4\uc2dc\uac00 \uacf5\uc720\ud55c \ud2b9\uc9d5\uacfc \ud55c \uc7a5\uc18c\uc5d0\uc11c \uc9c1\uc811 \ud655\uc778\ud55c \uc0ac\uc2e4\uc744 \ub098\ub204\uba74, \ub2ee\uc740 \ubb38\uba85\uc774\ub77c\ub294 \ub9d0 \uc548\uc758 \ucc28\uc774\ub3c4 \ubcfc \uc218 \uc788\ub2e4. \uc778\ub354\uc2a4 \uc778\uc7a5\uc5d0\ub294 \ub3d9\ubb3c\uacfc \uc0ac\ub78c\uc758 \ubaa8\uc2b5, \uc9e7\uc740 \uae30\ud638\uac00 \uc0c8\uaca8\uc838 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc774\ub7f0 \uc778\uc7a5\uc73c\ub85c \ubd80\ub4dc\ub7ec\uc6b4 \uc810\ud1a0\uc5d0 \uc790\uad6d\uc744 \ub0a8\uaca8 \uadf8\ub987\uc774\ub098 \uc9d0\uacfc \uad00\ub828\ub41c \ud45c\uc2dc\ub97c \ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc0c8\uae34 \ubb3c\uac74\uacfc \uadf8\uac83\uc774 \ub0a8\uae34 \ud754\uc801\uc740 \uc11c\ub85c \uc5f0\uacb0\ub418\ub294 \ub450 \ubd80\ubd84\uc774\ub2e4. \uc624\ub298\uc758 \ud0dd\ubc30 \uc0c1\uc790\uc5d0 \ubd99\uc740 \uc815\ubcf4\ud45c\uc640 \uc644\uc804\ud788 \uac19\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uc5ec\ub7ec \uc0ac\ub78c\uc758 \ubb3c\uac74\uc774 \uc624\uac08 \ub54c \ubb34\uc5c7\uc744 \uad6c\ubcc4\ud558\uace0 \uc5b4\ub5bb\uac8c \ud655\uc778\ud560\uc9c0\ub77c\ub294 \uc9c8\ubb38\uc740 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uc774\ub984\uc778\uc9c0 \uc9c0\uc704\uc778\uc9c0, \uc18c\uc720\uc640 \uac70\ub798\uc758 \uc5b4\ub5a4 \ub0b4\uc6a9\uc744 \ud45c\uc2dc\ud588\ub294\uc9c0 \uc138\ubd80\ub294 \uc544\uc9c1 \ub2e8\uc815\ud560 \uc218 \uc5c6\ub2e4. \uae30\ub2a5\uc758 \ucd94\uc815\uacfc \uae30\ud638\uc758 \uc815\ud655\ud55c \ubc88\uc5ed\uc740 \ub2e4\ub974\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc0ac\uc9c4\uc758 \uc67c\ucabd\uc740 \uc778\ub354\uc2a4 \ubb38\uba85\uc758 \uc2e4\uc81c \uc778\uc7a5\uc774\uace0, \uc624\ub978\ucabd\uc740 \uadf8\uac83\uc744 \ub20c\ub7ec \ub9cc\ub4e0 \ud604\ub300\uc758 \uc810\ud1a0 \uc555\uc778\uc774\ub2e4. \ub450 \ubb3c\uac74\uc774 \ubaa8\ub450 \uace0\ub300\uc5d0 \uc81c\uc791\ub41c \ud55c \uc30d\uc740 \uc544\ub2c8\ub2e4. \uc6d0\ub798 \uc0c8\uae34 \uba74\uc774 \uc5b4\ub5a4 \ud754\uc801\uc744 \ub9cc\ub4dc\ub294\uc9c0 \ubcf4\uae30 \uc88b\uac8c \ud568\uaed8 \uc81c\uc2dc\ud55c \uac83\uc774\ub2e4. \uc774 \ucc28\uc774\ub97c \uc54c\uba74 \ub3d9\ubb3c\uc758 \ubc29\ud5a5\uacfc \uae30\ud638\uc758 \ubc30\uce58\ub3c4 \ube44\uad50\ud558\uac8c \ub41c\ub2e4. \uac70\uc6b8\ucc98\ub7fc \ub4a4\uc9d1\ud788\ub294 \uad00\uacc4\ub97c \ub208\uc73c\ub85c \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uc0ac\uc9c4\uc758 \uc124\uba85\uc744 \uc77d\ub294 \uc77c\uc740 \uac10\uc0c1\uc744 \ubc29\ud574\ud558\ub294 \ubd80\ub85d\uc774 \uc544\ub2c8\ub2e4. \ub208\uc55e\uc758 \uc790\ub8cc\uac00 \ubb34\uc5c7\uc774\uba70 \uc5b4\ub5a4 \uacfc\uc815\uc744 \ubcf4\uc5ec \uc8fc\ub294\uc9c0 \uc815\ud655\ud558\uac8c \ubcf4\ub294 \uccab \ub2e8\uacc4\ub2e4. \uad50\uc7ac\ub294 \uc778\ub354\uc2a4 \uacc4\ud1b5\uc758 \uc778\uc7a5\uc774 \uba54\uc18c\ud3ec\ud0c0\ubbf8\uc544\uc758 \uc6b0\ub974 \uac19\uc740 \ub3c4\uc2dc\uc5d0\uc11c\ub3c4 \ubc1c\uacac\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc778\ub354\uc2a4\uc640 \uba54\uc18c\ud3ec\ud0c0\ubbf8\uc544 \uc0ac\uc774\uc5d0\ub294 \ubc14\ub2e4\uc640 \uc721\uc9c0\ub97c \ud1b5\ud55c \uad50\uc5ed\uc774 \uc788\uc5c8\ub2e4. \uadc0\ud55c \ub3cc\uacfc \uc870\uac1c \uac19\uc740 \ubb3c\ud488\ub3c4 \uc624\uac14\ub2e4. \uc791\uc740 \uc778\uc7a5\uc774 \uc790\uae30 \uc9c0\uc5ed \ubc16\uc5d0\uc11c \ub098\uc628\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uadf8 \uc5f0\uacb0\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ud558\uc9c0\ub9cc \uc778\uc7a5 \ud55c \uac1c\uac00 \ubc1c\uacac\ub418\uc5c8\ub2e4\uace0 \ud2b9\uc815 \uc0c1\uc778\uc758 \uc804\uccb4 \uc5ec\ud589\uc744 \ubcf5\uc6d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ubb3c\uac74\uc740 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc190\uc744 \uac70\ucce4\uc744 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc790\ub8cc\uac00 \uc54c\ub824 \uc8fc\ub294 \uad50\ub958\uc758 \uc874\uc7ac\uc640 \uc6b0\ub9ac\uac00 \ubd99\uc774\uace0 \uc2f6\uc740 \ud55c \uc0ac\ub78c\uc758 \ubaa8\ud5d8\ub2f4\uc740 \ub2e4\ub978 \uac83\uc774\ub2e4. \uc815\ud655\ud788 \uc544\ub294 \ubc94\uc704 \uc548\uc5d0\uc11c\ub3c4 \uc774\ub3d9\uc758 \uaddc\ubaa8\ub294 \ucda9\ubd84\ud788 \ud765\ubbf8\ub86d\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \ub3d9\ubb3c\uc758 \ubaa8\uc591\uc744 \uc54c\uc544\ubcfc \uc218 \uc788\ub2e4\uace0 \uadf8 \uc704\uc758 \uae30\ud638\uae4c\uc9c0 \uc77d\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc778\ub354\uc2a4 \ubb38\uc790\ub294 \uc544\uc9c1 \ud574\ub3c5\ub418\uc9c0 \uc54a\uc558\ub2e4. \uc9e7\uc740 \ud45c\uc2dc\ub4e4\uc774 \uc5b4\ub5a4 \uc5b8\uc5b4\ub97c \ub2f4\uc558\ub294\uc9c0, \ubaa8\ub4e0 \uae30\ud638\uac00 \ubb34\uc5c7\uc744 \ub73b\ud588\ub294\uc9c0\ub294 \ud569\uc758\ub41c \ud574\ub2f5\uc774 \uc5c6\ub2e4. \uc775\uc219\ud55c \ubb38\uc790\ucc98\ub7fc \uc18c\ub9ac\ub97c \ubd99\uc5ec \uc77d\uc744 \uc218 \uc5c6\ub294 \uc0c1\ud0dc\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc544\ubb34\uac83\ub3c4 \uc5f0\uad6c\ud560 \uc218 \uc5c6\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uae30\ud638\uc758 \ubc18\ubcf5\uacfc \ubc30\uc5f4, \ubc1c\uacac\ub41c \uc7a5\uc18c\ub97c \ube44\uad50\ud560 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uaddc\uce59\uc744 \ucc3e\uc558\ub2e4\ub294 \ub9d0\uacfc \ubc88\uc5ed\uc5d0 \uc131\uacf5\ud588\ub2e4\ub294 \ub9d0\uc740 \ub2e4\ub974\ub2e4. \ubbf8\uc9c0\uc758 \uc790\ub8cc\uc5d0\uc11c \ud765\ubbf8\ub85c\uc6b4 \ud328\ud134\uc774 \ubcf4\uc77c\uc218\ub85d \uadf8 \ucc28\uc774\ub97c \uc9c0\ud0a4\ub294 \uc77c\uc774 \uc911\uc694\ud574\uc9c4\ub2e4. \uc655\uc758 \uc774\ub984\uc774 \uc801\ud78c \uae34 \uae30\ub85d\uc744 \uc77d\uc744 \uc218 \uc5c6\ub294 \uc0c1\ud669\uc5d0\uc11c\ub294 \uac74\ubb3c\uacfc \ub3c4\uad6c, \uc778\uc7a5 \uac19\uc740 \ubb3c\uac74\uc758 \ube44\uc911\uc774 \ucee4\uc9c4\ub2e4. \ub3c4\uc2dc\uc758 \uc8fc\ubbfc\uc774 \uae00\uc744 \ub0a8\uae30\uc9c0 \uc54a\uc558\ub2e4\ub294 \ub9d0\ubcf4\ub2e4\ub294 \uadf8\ub4e4\uc774 \ub0a8\uae34 \uae30\ud638\ub97c \uc6b0\ub9ac\uac00 \uc544\uc9c1 \uc77d\uc9c0 \ubabb\ud55c\ub2e4\uace0 \ud45c\ud604\ud558\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \uce68\ubb35\uc740 \ub54c\ub85c \uc790\ub8cc\ubcf4\ub2e4 \ub3c5\uc790\uc758 \ub2a5\ub825\uc5d0 \uc788\ub2e4. \ud558\ub77c\ud30c\ub97c \uc774\ud574\ud558\ub294 \uc77c\uc740 \ud769\uc5b4\uc9c4 \ub2e8\uc11c\ub97c \ud568\uaed8 \ub193\ub294 \uacfc\uc815\uc774\ub2e4. \uac70\ub9ac\uc758 \ubc30\uce58\uc640 \uc0dd\uc0b0\uc758 \ud754\uc801, \uba3c \uacf3\uc5d0\uc11c \ub098\uc628 \ubb3c\uac74\uc774 \uc11c\ub85c\ub97c \ubcf4\uc644\ud55c\ub2e4. \uc5b4\ub290 \ud55c \uc885\ub958\uc758 \uc720\ubb3c\ub9cc\uc73c\ub85c \uc0ac\ud68c \uc804\uccb4\ub97c \ub2e4 \uc124\uba85\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4. \uc9c8\ubb38\uc744 \uc5ec\ub7ec \uc790\ub8cc\uc5d0 \ub098\ub204\uc5b4 \ubb3b\ub294 \ubc29\uc2dd\uc774 \ud544\uc694\ud55c \uac83\uc774\ub2e4. \ud070 \ub3c4\uc2dc\uc758 \uc774\uc57c\uae30\ub97c \uc791\uc740 \uc778\uc7a5\uc73c\ub85c \uc2dc\uc791\ud558\uba74 \uc2dc\uc120\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc774\ub984\ub09c \ud1b5\uce58\uc790\uc758 \uc5c5\uc801\ubcf4\ub2e4 \ubb3c\uac74\uc744 \ub9cc\ub4e4\uace0 \ud45c\uc2dc\ud558\uace0 \uc6b4\ubc18\ud55c \uc0ac\ub78c\ub4e4\uc774 \ub5a0\uc624\ub978\ub2e4. \uc544\uc9c1 \uc77d\uc9c0 \ubabb\ud55c \uae30\ud638 \uc606\uc5d0\ub3c4 \ud655\uc2e4\ud788 \uad00\ucc30\ud560 \uc218 \uc788\ub294 \ub3cc\uc758 \ubaa8\uc591\uacfc \uc790\uad6d, \ubc1c\uacac \uc7a5\uc18c\uc758 \uc5f0\uacb0\uc774 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \ubc15\ubb3c\uad00\uc5d0\uc11c \uc791\uc740 \ud45c\uc9c0\uac00 \ubd99\uc740 \uc778\uc7a5\uc744 \ub9cc\ub098\uba74 \uc7a0\uae50 \uba48\ucdb0 \ubcf4\uc790. \ubb34\uc5c7\uc744 \uc0c8\uacbc\ub294\uc9c0\uc640 \uc5b4\ub514\uc5d0\uc11c \ub098\uc654\ub294\uc9c0\ub97c \ud568\uaed8 \uc77d\uc73c\uba74 \uc88b\ub2e4. \ud558\ub77c\ud30c\uc758 \uc791\uc740 \uc778\uc7a5\uc740 \uc54c\uc544\ub0b8 \uac83\uacfc \ub0a8\uc740 \uc218\uc218\uaed8\ub07c\ub97c \ub098\ub780\ud788 \ub193\uc744 \ub54c \uc624\ub798\ub41c \ub3c4\uc2dc\uc758 \uc138\uacc4\uac00 \ub354 \ub113\uc5b4\uc9c4\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "horn-bow-missing-string", "title": "\uc2dc\uc704 \uc5c6\ub294 \uc61b \ud65c\uc5d0\uc11c\ub294 \ubb34\uc5c7\uc744 \ubcfc \uc218 \uc788\uc744\uae4c", "summary": "\ud65c\uc2dc\uc704\uac00 \uc0ac\ub77c\uc838\ub3c4 \ub0a8\uc544 \uc788\ub294 \ub2e8\uc11c\ub294 \uc788\uc2b5\ub2c8\ub2e4. \uc791\uc740 \ud648\uacfc \uc190\uc7a1\uc774\ub97c \ub530\ub77c \uc61b \ubb3c\uac74\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/horn-bow-missing-string/index.html", "image": "../media/horn-bow-missing-string.jpg", "alt": "\ud65c\uc2dc\uc704 \uc5c6\uc774 \uad7d\uc740 \ubab8\uccb4\uc640 \uac00\uc6b4\ub370 \ubd89\uc740 \uc190\uc7a1\uc774\uac00 \ub0a8\uc544 \uc788\ub294 \uac01\uad81 \uc0ac\uc9c4", "text": "\uc2dc\uc704 \uc5c6\ub294 \uc61b \ud65c\uc5d0\uc11c\ub294 \ubb34\uc5c7\uc744 \ubcfc \uc218 \uc788\uc744\uae4c \uac01\uad81\uc758 \uad7d\uc740 \ubab8\uccb4\uc5d0 \ub0a8\uc544 \uc788\ub294 \uc7ac\ub8cc\uc640 \ud648 \ud65c\uc2dc\uc704\uac00 \uc0ac\ub77c\uc838\ub3c4 \ub0a8\uc544 \uc788\ub294 \ub2e8\uc11c\ub294 \uc788\uc2b5\ub2c8\ub2e4. \uc791\uc740 \ud648\uacfc \uc190\uc7a1\uc774\ub97c \ub530\ub77c \uc61b \ubb3c\uac74\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ud65c\uc744 \ub5a0\uc62c\ub9ac\uba74 \ud33d\ud33d\ud55c \uc904\uacfc \ud654\uc0b4\uc744 \ub2f9\uae30\ub294 \ubaa8\uc2b5\ubd80\ud130 \uc0dd\uac01\ub09c\ub2e4. \uadf8\ub7f0\ub370 \ubc15\ubb3c\uad00\uc5d0 \ub193\uc778 \ud65c\uc5d0 \uc904\uc774 \uc5c6\ub2e4\uba74 \uc5b4\ub514\ub97c \ubcf4\uc544\uc57c \ud560\uae4c. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \uac01\uad81 \ud55c \uc810\uc740 \ud65c\uc2dc\uc704 \uc5c6\uc774 \ub0a8\uc544 \uc788\ub2e4. \uc0ac\uc9c4 \uc18d\uc5d0\uc11c\ub294 \uad7d\uc740 \ubab8\uccb4\uac00 \uba3c\uc800 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc124\uba85\uc744 \uc77d\uc73c\uba74 \uadf8 \uace1\uc120\uc744 \ub530\ub77c \uc791\uc740 \ub2e8\uc11c\ub4e4\uc774 \ud558\ub098\uc529 \ubcf4\uc774\uae30 \uc2dc\uc791\ud55c\ub2e4. \uac01\uad81\uc758 \u2018\uac01\u2019\uc740 \ubfd4\uc744 \ub73b\ud55c\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc6b0\ub9ac\ub098\ub77c\uc758 \ub300\ud45c\uc801\uc778 \uc2e4\uc804\uc6a9 \ud65c\uc774\ub77c\uace0 \uc18c\uac1c\ud558\uba70, \ud0c4\uc131\uc744 \ub192\uc774\uae30 \uc704\ud574 \ubb3c\uc18c\uc758 \ubfd4\uc744 \uc8fc\uc7ac\ub8cc\ub85c \uc0ac\uc6a9\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uba40\ub9ac\uc11c\ub294 \uac00\ub298\uace0 \uad7d\uc740 \ubb3c\uac74 \ud558\ub098\uc9c0\ub9cc, \uadf8 \uc548\uc5d0\ub294 \uc7ac\ub8cc\ub97c \uace0\ub978 \uc774\uc720\uac00 \uc788\ub2e4. \uadf8\uc800 \ub2e8\ub2e8\ud558\uae30\ub9cc \ud55c \ubb3c\uac74\uc744 \ub9cc\ub4dc\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ud718\uc5b4\uc9c0\ub294 \uc131\uc9c8\ub3c4 \uc0dd\uac01\ud574\uc57c \ud588\ub358 \uac83\uc774\ub2e4. \uc774 \uc720\ubb3c\uc758 \uc2dc\ub300\ub294 \uc870\uc120\uc73c\ub85c \uc18c\uac1c\ub418\uc5b4 \uc788\ub2e4. \uc624\ub298 \uacbd\uae30\uc7a5\uc5d0\uc11c \ubcf4\ub294 \ud65c\uc758 \ubaa8\uc2b5\uacfc \uace7\ubc14\ub85c \uacb9\uccd0 \ub193\uae30\ubcf4\ub2e4, \ub2f9\uc2dc\uc758 \ubb3c\uac74\uc5d0 \uc5b4\ub5a4 \uc7ac\ub8cc\ub97c \uc37c\ub294\uc9c0\ubd80\ud130 \uc0b4\ud3b4\ubcf4\ub294 \ud3b8\uc774 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \ub0a8\uc544 \uc788\ub294 \ud65c\uc5d0\ub294 \uc2dc\uc704\uac00 \uc5c6\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc904\uacfc \uad00\uacc4\ub41c \ubd80\ubd84\uae4c\uc9c0 \ubaa8\ub450 \uc0ac\ub77c\uc9c4 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc591 \ub05d\uc5d0 \uc904\uc744 \ub9ec \uc218 \uc788\ub3c4\ub85d \ud648\uc774 \ud30c\uc5ec \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud65c\uc758 \uac00\uc6b4\ub370\uc5d0\ub294 \uc190\uc7a1\uc774 \ubd80\ubd84\ub3c4 \uc788\ub2e4. \uc591 \ub05d\uc758 \ud648\uacfc \uac00\uc6b4\ub370\uc758 \uc190\uc7a1\uc774\ub97c \ub098\ub204\uc5b4 \ubcf4\uba74, \uae38\uac8c \uad7d\uc740 \ubab8\uccb4\uac00 \uc5b4\ub514\uc5d0\uc11c \uc190\uc5d0 \uc7a1\ud788\uace0 \uc5b4\ub514\uc5d0\uc11c \uc904\uacfc \ub9cc\ub0ac\ub294\uc9c0 \uc870\uae08\uc529 \uc77d\ud78c\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uc644\uc131\ub41c \uc0ac\uc6a9 \uc7a5\uba74\uc774 \ubcf4\uc774\uc9c0 \uc54a\ub354\ub77c\ub3c4 \ud754\uc801\uc740 \uc5ed\ud560\uc744 \uc54c\ub824\uc900\ub2e4. \ube60\uc9c4 \ubd80\ubd84\uc744 \ub9c8\uc74c\ub300\ub85c \ucc44\uc6cc \ub123\uae30\ubcf4\ub2e4, \ub0a8\uc740 \uc790\ub9ac\ub97c \ucc28\ub840\ub85c \ubcf4\ub294 \uac83\ub9cc\uc73c\ub85c \ubb3c\uac74\uacfc \uac00\uae4c\uc6cc\uc9c8 \uc218 \uc788\ub2e4. \ud65c\uc744 \ub9cc\ub4dc\ub294 \uc7ac\ub8cc\ub294 \ubaa8\uc591\uc744 \uc720\uc9c0\ud558\uba74\uc11c\ub3c4 \ud718\uc5b4\uc84c\ub2e4 \ub3cc\uc544\uc624\ub294 \uc131\uc9c8\uc774 \ud544\uc694\ud558\ub2e4. \ub3cc\ucc98\ub7fc \ub2e8\ub2e8\ud558\uae30\ub9cc \ud558\uba74 \uc6d0\ud558\ub294 \ud589\ub3d9\uc744 \ub9cc\ub4e4\uae30 \uc5b4\ub835\ub2e4. \ubc15\ubb3c\uad00\uc774 \ubb3c\uc18c \ubfd4\uacfc \ud0c4\uc131\uc744 \ud568\uaed8 \uc124\uba85\ud558\ub294 \uac83\uc740 \uc7ac\ub8cc\ub97c \uadf8\uc800 \uadc0\ud558\uac70\ub098 \uc544\ub984\ub2f5\ub2e4\ub294 \uc774\uc720\ub85c\ub9cc \uace0\ub974\uc9c0 \uc54a\uc558\ub2e4\ub294 \ub2e8\uc11c\ub97c \uc900\ub2e4. \uc4f0\ub294 \ub3d9\uc791\uacfc \ubb3c\uc131\uc758 \uad00\uacc4\uac00 \uc81c\uc791\uc5d0 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \uc774 \ub9d0\uc774 \uac01\uad81\uc758 \ubaa8\ub4e0 \uad6c\uc870\uc640 \uc7ac\ub8cc\ub97c \ud55c \uac00\uc9c0\ub85c \uc694\uc57d\ud55c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc790\ub8cc\ub294 \uc8fc\uc7ac\ub8cc\uc758 \ud2b9\uc9d5\uc744 \uc54c\ub824 \uc8fc\uba70 \uc804\uccb4 \uc81c\uc791 \uae30\uc220\uc758 \uc138\ubd80\ub294 \ub2e4\ub978 \uc124\uba85\uc774 \ud544\uc694\ud558\ub2e4. \uc720\ubb3c\uc744 \ubcf4\uba74 \ubb34\uc5c7\uc73c\ub85c \ub9cc\ub4e4\uc5c8\ub294\uc9c0 \uc606\uc5d0 \uc65c \uadf8\ub7f0 \uc131\uc9c8\uc774 \ud544\uc694\ud588\ub294\uc9c0\ub97c \ubb3c\uc5b4\ubcfc \uc218 \uc788\ub2e4. \uc5ed\uc0ac \uc18d \ubb34\uae30\ub294 \uacf5\uaca9\uc758 \uc774\uc57c\uae30\ubfd0 \uc544\ub2c8\ub77c \uc7ac\ub8cc\ub97c \uc774\ud574\ud55c \uae30\uc220\uc758 \uc5ed\uc0ac\ub85c\ub3c4 \uc77d\ud78c\ub2e4. \uc591\ub05d\uc758 \ud648\uc740 \ud604\uc7ac \uc5c6\ub294 \uc2dc\uc704\uc640\uc758 \uad00\uacc4\ub97c \uc54c\ub824 \uc900\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \ud65c\ub9cc \ub0a8\uc544 \uc788\ub2e4\uace0 \ucc98\uc74c\ubd80\ud130 \uc904 \uc5c6\uc774 \uc644\uc131\ud55c \ubb3c\uac74\uc73c\ub85c \uc0dd\uac01\ud558\uc9c0 \uc54a\uac8c \ud55c\ub2e4. \uc5c6\uc5b4\uc9c4 \ubd80\ud488\uc774 \uc788\uc5b4\ub3c4 \uadf8\uac83\uacfc \ub9de\ub2ff\ub358 \ubd80\ubd84\uc740 \ub0a8\uc744 \uc218 \uc788\ub2e4. \uc644\uc804\ud558\uc9c0 \uc54a\uc740 \uc720\ubb3c\uc744 \uc77d\uc744 \ub54c \uc811\uc810\uc744 \uc0b4\ud53c\ub294 \ubc29\ubc95\uc774\ub2e4. \ub2e4\ub9cc \ud648\uc758 \uc704\uce58\ub97c \ubcf4\uc558\ub2e4\uace0 \uc6d0\ub798\uc758 \uae38\uc774\uc640 \uc7a5\ub825\uc744 \uc0c8\ub85c \uacc4\uc0b0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc2e4\uc81c \uc7ac\ub8cc\uc758 \uc0c1\ud0dc\uc640 \uc0ac\uc6a9 \uc870\uac74\uc744 \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \ubcf4\uc874\ub41c \uc61b \ud65c\uc744 \ub2f9\uaca8 \uc2dc\ud5d8\ud558\ub294 \uac83\uc740 \uad00\ub78c\uc790\uc758 \uc77c\uc774 \uc544\ub2c8\ub2e4. \ub0a8\uc740 \uad6c\uc870\ub97c \uc124\uba85\uacfc \ud568\uaed8 \uc77d\uace0, \uc5f0\uc8fc\ub098 \uc0ac\uaca9\uc758 \ubcf5\uc6d0\uc740 \uc801\uc808\ud55c \uc790\ub8cc\uc640 \uc804\ubb38\uc801\uc778 \uac80\ud1a0\uc758 \uc601\uc5ed\uc73c\ub85c \uad6c\ubd84\ud560 \ud544\uc694\uac00 \uc788\ub2e4. \ud65c\uc740 \uc804\uccb4\uac00 \uae38\uac8c \uad7d\uc5c8\uc5b4\ub3c4 \uc0ac\ub78c\uc774 \uc7a1\ub294 \uc790\ub9ac\uac00 \ub530\ub85c \uc788\ub2e4. \uac00\uc6b4\ub370\uc758 \uc190\uc7a1\uc774\uc640 \uc591 \ub05d\uc758 \ud648\uc744 \ub098\ub204\uc5b4 \ubcf4\uba74 \uc190\uacfc \uc904\uc774 \ub9cc\ub098\ub294 \uad00\uacc4\uac00 \ubcf4\uc778\ub2e4. \ubb3c\uac74\uc758 \uc724\uacfd\ub9cc \uac10\uc0c1\ud560 \ub54c\ubcf4\ub2e4 \uc5b4\ub5a4 \ud589\ub3d9\uc744 \uc704\ud574 \uae38\uc774\uc640 \uc790\ub9ac\ub97c \ub098\ub204\uc5c8\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \ud615\ud0dc\uac00 \uc0ac\ub78c\uc758 \ubab8\uacfc \uc774\uc5b4\uc9c0\ub294 \uac83\uc774\ub2e4. \uc624\ub298 \uacbd\uae30\uc5d0\uc11c \ubcf8 \uc790\uc138\ub97c \uc774 \uc720\ubb3c\uc758 \uc2e4\uc81c \uc0ac\uc6a9 \uc7a5\uba74\uacfc \uace7\ubc14\ub85c \uac19\uac8c \ub193\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc2dc\ub300\uc640 \uc885\ub958\uc5d0 \ub530\ub77c \ub2e4\ub978 \uc870\uac74\uc774 \uc788\uc744 \uc218 \uc788\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc870\uc120\uc758 \uac01\uad81\uc774\ub77c\uace0 \uc18c\uac1c\ub41c \ud55c \uc810\uc744 \ubc14\ud0d5\uc73c\ub85c \uc7ac\ub8cc\uc640 \uc5f0\uacb0 \ubd80\ubd84\uc744 \uc0b4\ud3b4\ubcf8\ub2e4. \uc775\uc219\ud55c \ud65c\uc774\ub77c\ub294 \uc774\ub984 \uc548\uc5d0\ub3c4 \ub530\ub85c \ud655\uc778\ud560 \uae30\uc220\uacfc \uc2dc\uac04\uc774 \uc788\ub2e4\ub294 \uc810\uc744 \uc54c \uc218 \uc788\ub2e4. \uc6d0\ub798\ub294 \uc0ac\uc6a9\uc790\uac00 \uc7a1\uace0 \uc6c0\uc9c1\uc774\ub358 \ubb3c\uac74\uc774 \uc804\uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc870\uc6a9\ud788 \ub193\uc778\ub2e4. \uc2dc\uc704\ub3c4 \uc5c6\uace0 \uc2e4\uc81c \ub3d9\uc791\ub3c4 \ubcf4\uc774\uc9c0 \uc54a\uc9c0\ub9cc, \uadf8 \uc0c1\ud0dc\uc5d0\uc11c \uc0c8\ub85c \ubcfc \uc218 \uc788\ub294 \uac83\uc774 \uc788\ub2e4. \uc5b4\ub514\uac00 \ubab8\uccb4\uc774\uace0 \uc5b4\ub290 \uacf3\uc774 \uc190\uc7a1\uc774\uc778\uc9c0, \ubd80\ud488\uc774 \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ub418\uc5c8\uc744\uc9c0 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294\ub2e4\uace0 \uc4f0\uc784\uc758 \ud754\uc801\uae4c\uc9c0 \ubaa8\ub450 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774 \uc9c8\ubb38\uc744 \ub530\ub77c\uac00\uba74 \uc804\ud22c \uc7a5\uba74\uc744 \uc0c8\ub85c \uafb8\ubbf8\uc9c0 \uc54a\uace0\ub3c4 \uc720\ubb3c\uacfc \uac00\uae4c\uc6cc\uc9c8 \uc218 \uc788\ub2e4. \ub204\uac00 \uc5b8\uc81c \uc5bc\ub9c8\ub098 \uba40\ub9ac \uc3d8\uc558\ub294\uc9c0\ub294 \ub0a8\uc740 \uc790\ub8cc\uc758 \ub2e4\ub978 \ubb38\uc81c\ub85c \ub450\uc5b4\ub3c4 \ub41c\ub2e4. \uc791\uc740 \ud648\uacfc \uc7ac\ub8cc\uc758 \uc774\ub984\uc774 \uc6b0\ub9ac\uc5d0\uac8c \uc804\ud558\ub294 \uac83\uc740 \ud55c \ud589\ub3d9\uc744 \uac00\ub2a5\ud558\uac8c \ud558\ub824\uace0 \ubb3c\uac74\uc744 \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc774\ub2e4. \uc2dc\uc704 \uc5c6\ub294 \uc61b \ud65c\ub3c4 \uadf8 \uc5f0\uacb0\uc758 \uc77c\ubd80\ub97c \ub9d0\ud574 \uc900\ub2e4. \ubc15\ubb3c\uad00\uc5d0\ub294 \ucc98\uc74c \ub9cc\ub4e4\uc5b4\uc9c4 \uc0c1\ud0dc \uadf8\ub300\ub85c\uc778 \ubb3c\uac74\ub9cc \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \ubd80\ubd84\uc740 \ub0a8\uace0 \uc5b4\ub5a4 \ubd80\ubd84\uc740 \uc5c6\uc5b4\uc9c0\uae30\ub3c4 \ud55c\ub2e4. \uc774\ub54c \uc5c6\ub294 \ubd80\ubd84\ub9cc \uc544\uc26c\uc6cc\ud558\uba74 \ub0a8\uc740 \ubd80\ubd84\uc758 \uc7ac\ubbf8\ub97c \ub193\uce58\uae30 \uc27d\ub2e4. \uac01\uad81\uc5d0\uc11c\ub294 \uace1\uc120\uacfc \uc7ac\ub8cc, \uc190\uc7a1\uc774\uc640 \ud648\uc744 \ubcfc \uc218 \uc788\ub2e4. \ub204\uac00 \uc5b8\uc81c \uc774 \ud55c \uc810\uc744 \ub2f9\uacbc\ub294\uc9c0\uae4c\uc9c0 \uc124\uba85\uc774 \uc54c\ub824\uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub300\uc2e0 \uc190\uc744 \ub300\ub358 \uc790\ub9ac\uc640 \uc904\uc774 \ub2ff\ub358 \uc790\ub9ac\ub77c\ub294 \uad6c\uccb4\uc801\uc778 \ub2e8\uc11c\uac00 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \uc61b \ub3c4\uad6c\ub97c \ub9cc\ub0ac\ub294\ub370 \ud55c \ubd80\ubd84\uc774 \ube44\uc5b4 \uc788\ub2e4\uba74, \ub0a8\uc544 \uc788\ub294 \uac83\ubd80\ud130 \ucc9c\ucc9c\ud788 \uc0b4\ud3b4\ubcf4\uc790. \uc904\uc774 \uc5c6\ub294 \ud65c\ub3c4 \uc544\ubb34 \ub9d0 \uc5c6\ub294 \uace1\uc120\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uc791\uc740 \ud648 \ud558\ub098\uac00 \uc6d0\ub798\uc758 \uc4f0\uc784\uc744 \uc0dd\uac01\ud558\uac8c \ud574 \uc900\ub2e4."}, {"id": "inca-quipu-knots-and-records", "title": "\ud0a4\ud478 \u2014 \uc789\uce74\ub294 \ub9e4\ub4ed\uc73c\ub85c \ubb34\uc5c7\uc744 \uae30\ub85d\ud588\uc744\uae4c", "summary": "\uc2e4\uc81c \ud0a4\ud478 \uc870\uac01\uacfc 16\uc138\uae30 \uae30\ub85d\uc744 \ud1b5\ud574 \uc789\uce74\uc758 \uc7a5\ubd80\u00b7\uc81c\uad6d \uc6b4\uc601\u00b7\ud574\ub3c5\uc758 \ud55c\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/inca-quipu-knots-and-records/index.html", "image": "../media/inca-quipu-knots-and-records.png", "alt": "1400~1600\ub144 \uc81c\uc791\uc73c\ub85c \uc18c\uac1c\ub418\ub294 \uc2e4\uc81c \ud0a4\ud478 \uc870\uac01. \uad75\uc740 \ub048 \uc544\ub798 \uc5ec\ub7ec \uac00\ub2e5\uacfc \ub9e4\ub4ed.", "text": "\ud0a4\ud478 \u2014 \uc789\uce74\ub294 \ub9e4\ub4ed\uc73c\ub85c \ubb34\uc5c7\uc744 \uae30\ub85d\ud588\uc744\uae4c \uc791\uc740 \ub048\ubb49\uce58\uc5d0 \ub0a8\uc740 \uc0ac\ub78c\uacfc \ubb3c\uc790\uc758 \uc218 \uc2e4\uc81c \ud0a4\ud478 \uc870\uac01\uacfc 16\uc138\uae30 \uae30\ub85d\uc744 \ud1b5\ud574 \uc789\uce74\uc758 \uc7a5\ubd80\u00b7\uc81c\uad6d \uc6b4\uc601\u00b7\ud574\ub3c5\uc758 \ud55c\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ubc15\ubb3c\uad00\uc5d0 \uc5ec\ub7ec \uac00\ub2e5\uc758 \ub048\uc774 \ub298\uc5b4\uc838 \uc788\ub2e4. \ub9e4\ub4ed\uc774 \ub4dc\ubb38\ub4dc\ubb38 \ubb36\uc600\uace0 \uae38\uc774\ub3c4 \uace0\ub974\uc9c0 \uc54a\ub2e4. \uc7a5\uc2dd\ud488\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\uc9c0\ub9cc \uc774 \ubb3c\uac74\uc740 \uc789\uce74\uc758 \uae30\ub85d\uacfc \uc5f0\uacb0\ub41c\ub2e4. \ud0a4\ud478\ub77c\uace0 \ubd80\ub974\ub294 \ub9e4\ub4ed \uae30\ub85d \uc7a5\uce58\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc2e4\uc81c \ud0a4\ud478 \uc870\uac01\uc740 1400\ub144\uc5d0\uc11c 1600\ub144 \uc0ac\uc774\uc5d0 \ub9cc\ub4e4\uc5b4\uc9c4 \uac83\uc73c\ub85c \uc18c\uac1c\ub41c\ub2e4. \uc885\uc774\uc758 \uae00\uc790 \ub300\uc2e0 \ub048\uacfc \ub9e4\ub4ed\uc5d0 \uc815\ubcf4\ub97c \ub0a8\uacbc\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub0af\uc124\uc9c0\ub9cc, \ub113\uc740 \uc9c0\uc5ed\uc5d0\uc11c \uc0ac\ub78c\uacfc \ubb3c\uc790\uc758 \uc218\ub97c \ud30c\uc545\ud558\ub824 \ud588\ub2e4\ub294 \ubaa9\uc801\uc740 \uc758\uc678\ub85c \uc775\uc219\ud558\ub2e4. \uc789\uce74\ub294 \uc548\ub370\uc2a4 \uc9c0\uc5ed\uc758 \ub113\uc740 \ub545\uacfc \uc5ec\ub7ec \uacf5\ub3d9\uccb4\ub97c \uc5f0\uacb0\ud588\ub2e4. \uc0ac\ub78c\uacfc \uc790\uc6d0, \uc870\uc138\uc640 \ub178\ub3d9\uc744 \ud30c\uc545\ud558\ub294 \uc77c\uc740 \uc81c\uad6d\uc744 \uc6b4\uc601\ud558\ub294 \uc911\uc694\ud55c \uc870\uac74\uc774\uc5c8\ub2e4. \ubaa8\ub450\uc758 \uc5bc\uad74\uc744 \uc544\ub294 \uc791\uc740 \ub9c8\uc744\uacfc\ub294 \ub2e4\ub978 \uaddc\ubaa8\uc758 \uae30\ub85d\uc774 \ud544\uc694\ud588\ub2e4. \uad50\uc7ac\ub294 \ud0a4\ud478\uac00 \uc778\uad6c\uc640 \uc138\uae08, \ub545\uc758 \ubc30\ubd84\uacfc \uad70\ub300\uc758 \uc774\ub3d9 \uac19\uc740 \uc815\ubcf4\ub97c \uae30\ub85d\ud560 \uc218 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub2e8\uc9c0 \uacc4\uc0b0\uc744 \ub3d5\ub294 \uac1c\uc778\uc758 \ubb3c\uac74\uc73c\ub85c\ub9cc \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uc5b4\ub5a4 \uc218\ub97c \uae30\uc5b5\ud558\uace0 \uc804\ub2ec\ud560\uc9c0\ub294 \uacf5\ub3d9\uccb4\ub97c \uad00\ub9ac\ud558\ub294 \ud798\uacfc\ub3c4 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc0ac\uc9c4\uc744 \ubcf4\uba74 \uc911\uc2ec\uc774 \ub418\ub294 \ub048\uc744 \ub530\ub77c \uc5ec\ub7ec \uac00\ub2e5\uc774 \ub2ec\ub824 \uc788\ub2e4. \ud45c\uba74\uc758 \ub0b1\ub9d0\uc744 \uc77d\ub4ef \uace7\ubc14\ub85c \ub73b\uc744 \uc54c \uc218\ub294 \uc5c6\uc9c0\ub9cc, \ubc18\ubcf5\uacfc \ucc28\uc774\uac00 \uc788\ub294 \uad6c\uc870\ub77c\ub294 \uc810\uc740 \ubcf4\uc778\ub2e4. \ub9e4\ub4ed\uc758 \uc704\uce58\uc640 \uc885\ub958, \ub048\uc758 \uc0c9 \ub4f1 \uc5ec\ub7ec \uc694\uc18c\uac00 \uc815\ubcf4\uc758 \uad6c\ubd84\uc5d0 \uad00\uc5ec\ud560 \uc218 \uc788\uc5c8\ub2e4. \uad50\uc7ac\ub294 \ubb36\uace0 \ud480\uace0 \ub2e4\uc2dc \ubb36\ub294 \uc5ec\ub7ec \uc870\ud569\uc774 \uac00\ub2a5\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub2e4\ub9cc \uc774 \uc0ac\uc9c4\ub9cc\uc73c\ub85c \uac01\uac01\uc758 \ub9e4\ub4ed\uc774 \uc815\ud655\ud788 \uc5b4\ub5a4 \uc218\uc640 \ub300\uc0c1\uc744 \ub73b\ud558\ub294\uc9c0 \ud574\ub3c5\ud560 \uc218\ub294 \uc5c6\ub2e4. \ubb34\uc5c7\uc774 \uad6c\ubcc4\ub418\ub294\uc9c0 \uad00\ucc30\ud558\ub294 \uc77c\uacfc \uadf8 \uad6c\ubcc4\uc744 \ubc88\uc5ed\ud558\ub294 \uc77c \uc0ac\uc774\uc5d0\ub294 \uc544\uc9c1 \uac70\ub9ac\uac00 \uc788\ub2e4. \uc775\uc219\ud55c \ubb38\uc790\ub85c \uc801\ud78c \uc7a5\ubd80\ub97c \uba3c\uc800 \ub5a0\uc62c\ub9ac\uba74 \uc789\uce74\uc5d0 \uae30\ub85d\uc774 \uc5c6\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \ud558\uc9c0\ub9cc \uc885\uc774\uc5d0 \uae00\uc790\ub97c \uc4f0\uc9c0 \uc54a\ub294 \uac83\uacfc \uc815\ubcf4\ub97c \ub0a8\uae30\uc9c0 \uc54a\ub294 \uac83\uc740 \ub2e4\ub978 \ub9d0\uc774\ub2e4. \ud0a4\ud478\ub294 \ud734\ub300\ud560 \uc218 \uc788\ub294 \ubb3c\uc9c8 \uc704\uc5d0 \uaddc\uce59\uc744 \ub2f4\uc740 \uc7a5\uce58\uc600\ub2e4. \uadf8\ub807\ub2e4\uace0 \ud0a4\ud478\ub97c \ud604\ub300\uc758 \ucc45\uc774\ub098 \ucef4\ud4e8\ud130 \ud30c\uc77c\uacfc \ubaa8\ub4e0 \uae30\ub2a5\uc774 \uac19\uc740 \ubb3c\uac74\uc73c\ub85c \uc124\uba85\ud560 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc774 \uc0ac\uc6a9\ud55c \uad6c\uc870\uc640 \uadf8\uac83\uc744 \uc77d\uc744 \uc904 \uc544\ub294 \uc9c0\uc2dd\uc774 \uc788\uc5c8\ub2e4. \uc775\uc219\ud55c \uae30\uc900\uc73c\ub85c \ubd80\uc871\ud55c \uc810\ub9cc \ucc3e\uae30\ubcf4\ub2e4 \uc5b4\ub5a4 \ubb38\uc81c\ub97c \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \ud480\uc5c8\ub294\uc9c0 \ubcf4\ub294 \ud3b8\uc774 \ud765\ubbf8\ub86d\ub2e4. \uad50\uc7ac\ub294 \uc2a4\ud398\uc778\uc758 \uae30\ub85d\uc790 \ud398\ub4dc\ub85c \ub370 \uc2dc\uc5d0\uc0ac \ub370 \ub808\uc628\uc774 \ud604\uc9c0 \uc601\uc8fc\uc5d0\uac8c \ud0a4\ud478\uc758 \uc815\ud655\uc131\uc744 \uc124\uba85\ud574 \ub2ec\ub77c\uace0 \uc694\uccad\ud55c \uc77c\ud654\ub97c \uc778\uc6a9\ud55c\ub2e4. \uc601\uc8fc\ub294 \ud0a4\ud478\ub97c \uac00\uc838\uc624\uac8c \ud588\uace0, \uc2a4\ud398\uc778\uc778\ub4e4\uc774 \ub3c4\ucc29\ud55c \uc774\ud6c4 \uc81c\uacf5\ud55c \ubb3c\ud488\uc758 \ub0b4\uc5ed\uc744 \uc124\uba85\ud588\ub2e4. \uc2dc\uc5d0\uc0ac \ub370 \ub808\uc628\uc740 \uae08\uacfc \uc740, \uc758\ubcf5\uacfc \uace1\ubb3c \ub4f1\uc758 \uacc4\uc815\uc774 \ub098\uc624\ub294 \uac83\uc744 \ubcf4\uace0 \ub180\ub790\ub2e4\uace0 \uc801\uc5c8\ub2e4. \uc774\ub294 \ubaa8\ub4e0 \ud0a4\ud478\uc758 \ub0b4\uc6a9\uc744 \uc624\ub298 \uc6b0\ub9ac\uac00 \uc644\uc804\ud788 \uc77d\uc744 \uc218 \uc788\ub2e4\ub294 \uc99d\uac70\uac00 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \ub2f9\uc2dc \uadf8\uac83\uc744 \uc77d\ub294 \uc0ac\ub78c\uc5d0\uac8c \ub048\uc758 \ubc30\uc5f4\uc774 \uc2e4\uc81c \uac70\ub798\uc640 \ubb3c\ud488\uc758 \uae30\ub85d\uc73c\ub85c \uc791\ub3d9\ud588\ub2e4\ub294 \uc911\uc694\ud55c \uc99d\uc5b8\uc774\ub2e4. \ud0a4\ud478\uac00 \uc774\ub3d9\ud560 \uc218 \uc788\ub294 \ubb3c\uac74\uc774\ub77c\uace0 \ud574\ub3c4 \ub73b\uc774 \uc800\uc808\ub85c \ub4e4\ub9ac\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uaddc\uce59\uc744 \uc0ac\uc6a9\ud588\uace0 \uae30\ub85d\ud55c \ub300\uc0c1\uc774 \ubb34\uc5c7\uc778\uc9c0 \uc544\ub294 \uc9c0\uc2dd\uc774 \ud544\uc694\ud588\ub2e4. \ubb3c\uac74\uacfc \uadf8\uac83\uc744 \ud574\uc11d\ud558\ub294 \uc0ac\ub78c\uc758 \uad00\uacc4\ub97c \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc6b0\ub9ac\ub3c4 \ucc98\uc74c \ubcf4\ub294 \uc57d\uc5b4\ub9cc \uac00\ub4dd\ud55c \uc7a5\ubd80\ub294 \uc124\uba85 \uc5c6\uc774 \uc77d\uae30 \uc5b4\ub835\ub2e4. \ud0a4\ud478 \uc5ed\uc2dc \ub0af\uc120 \uc0ac\ub78c\uc774 \ub048\uc744 \uc138\uc5b4 \ubcf4\uae30\ub9cc \ud558\uba74 \ubaa8\ub4e0 \uc0ac\ud68c\uc801 \ub9e5\ub77d\uae4c\uc9c0 \uc54c\uc544\ub0b4\ub294 \uc7a5\uce58\ub294 \uc544\ub2c8\uc5c8\ub2e4. \uc804\ub2ec\uacfc \ubcf4\uad00\uc758 \uc5ed\uc0ac\uc5d0\ub294 \uc815\ubcf4\ub97c \ub0a8\uae34 \uc7ac\ub8cc\ubfd0 \uc544\ub2c8\ub77c \uc77d\ub294 \ubc95\uc744 \uc774\uc5b4 \uc8fc\ub294 \uc0ac\ub78c\ub4e4\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \uad50\uc7ac\uc5d0\ub294 \uc789\uce74\uc640 \uc2a4\ud398\uc778 \uc591\ucabd \ubc30\uacbd\uc744 \uac00\uc9c4 \uac00\ub974\uc2e4\ub77c\uc18c \ub370 \ub77c \ubca0\uac00\uc758 \uae30\ub85d\ub3c4 \uc778\uc6a9\ub41c\ub2e4. \uadf8\ub294 \ub9e4\ub4ed\uacfc \uad6c\uc2ac\uc758 \uae30\ub85d\uc5d0\uc11c \uc2dc\uc640 \uc774\uc57c\uae30\uac00 \uc804\ud574\uc84c\ub2e4\ub294 \uc124\uba85\uc744 \ub0a8\uacbc\ub2e4. \uc774\ub7f0 \uc99d\uc5b8\uc740 \ud0a4\ud478\uc758 \uc5ed\ud560\uc774 \uc218\ub7c9 \uae30\ub85d\ubcf4\ub2e4 \ub113\uc5c8\uc744 \uac00\ub2a5\uc131\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ud558\uc9c0\ub9cc \uac00\ub2a5\uc131\uacfc \uc644\uc804\ud55c \ud574\ub3c5\uc740 \ub2e4\ub974\ub2e4. \uc624\ub298\ub0a0 \ubaa8\ub4e0 \ud0a4\ud478\uc5d0\uc11c \ubb38\uc7a5\uacfc \uc2dc\ub97c \uc77d\uc744 \uc218 \uc788\ub2e4\ub294 \ub73b\uc73c\ub85c \uc18c\uac1c\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc5b4\ub5a4 \uc815\ubcf4\uae4c\uc9c0 \ub2f4\uc558\ub294\uc9c0, \uc218\ub7c9\uacfc \ub2e4\ub978 \ub0b4\uc6a9\uc774 \uc5b4\ub5bb\uac8c \uad6c\ubcc4\ub418\uc5c8\ub294\uc9c0\uc5d0\ub294 \ub0a8\uc740 \uc9c8\ubb38\uc774 \uc788\ub2e4. \ud765\ubbf8\ub85c\uc6b4 \uc99d\uc5b8\uc77c\uc218\ub85d \uadf8 \ubc94\uc704\ub97c \uc9c0\ud0a4\uba70 \uc77d\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc5ec\ub7ec \ud0a4\ud478\uac00 \ud30c\uad34\ub418\uc5c8\uace0 \uc0ac\uc6a9\uacfc \ud574\ub3c5\uc5d0 \ud544\uc694\ud55c \uc9c0\uc2dd\ub3c4 \ub9ce\uc774 \uc783\uc5b4\ubc84\ub838\ub2e4. \uadf8\ub798\uc11c \ubc15\ubb3c\uad00\uc5d0 \ub048\uc774 \ub0a8\uc544 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8 \ub0b4\uc6a9\uc774 \ubaa8\ub450 \uc6b0\ub9ac\uc5d0\uac8c \uc5f4\ub824 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uac19\uc9c0 \uc54a\ub2e4. \uae30\ub85d\uc758 \ubcf4\uc874\uc5d0\ub294 \ubb3c\uc9c8\uacfc \uc9c0\uc2dd\uc774\ub77c\ub294 \ub450 \ubb38\uc81c\uac00 \uc788\ub2e4. \uc0ac\uc9c4 \uc18d\uc758 \ud0a4\ud478\ub3c4 \ub113\uc740 \uae30\ub85d \uc804\ud1b5\uc758 \ud55c \uc870\uac01\uc774\ub2e4. \uc81c\uc791 \uc2dc\uae30\uac00 1400~1600\ub144\uc73c\ub85c \uc81c\uc2dc\ub41c\ub2e4\ub294 \uc810\uc740 \uae30\uc5b5\ud558\ub418, \uadf8\uac83\ub9cc\uc73c\ub85c \uc5b4\ub290 \uad00\ub9ac\uac00 \uc5b4\ub290 \ud574\uc758 \uc138\uae08\uc744 \uc801\uc5c8\ub294\uc9c0 \uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc720\ubb3c\uc758 \uc124\uba85\uc774 \uc54c\ub824 \uc8fc\ub294 \ubc94\uc704\uc640 \uc6b0\ub9ac\uac00 \uae30\ub300\ud558\ub294 \uad6c\uccb4\uc801\uc778 \uc774\uc57c\uae30\ub294 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ud0a4\ud478\ub294 \uae30\ub85d\uc744 \ub0a8\uae30\ub824\ub294 \uc778\uac04\uc758 \ud544\uc694\uac00 \ubc18\ub4dc\uc2dc \uac19\uc740 \ubaa8\uc591\uc758 \ubb3c\uac74\uc744 \ub9cc\ub4e4\uc9c0\ub294 \uc54a\uc558\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub113\uc740 \ub545\uc758 \uc0ac\ub78c\uacfc \uc790\uc6d0\uc744 \ud30c\uc545\ud558\ub824\ub294 \uc77c\uc740 \uc775\uc219\ud558\uc9c0\ub9cc \uadf8 \uc77c\uc744 \uc218\ud589\ud55c \ub048\uacfc \ub9e4\ub4ed\uc758 \uad6c\uc870\ub294 \uc0c8\ub86d\ub2e4. \uc775\uc219\ud568\uacfc \ub0af\uc126\uc774 \ud55c \ubb3c\uac74 \uc548\uc5d0 \ub193\uc5ec \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \uc774\ub7f0 \ub048\ubb49\uce58\ub97c \ub9cc\ub098\uba74 \uc7a5\uc2dd\ucc98\ub7fc \ud6d1\uace0 \uc9c0\ub098\uac00\uae30\ubcf4\ub2e4 \uc5b4\ub514\uc5d0 \ucc28\uc774\uac00 \uc788\ub294\uc9c0 \uc7a0\uae50 \uc0b4\ud3b4\ubcf4\uc790. \uadf8\uac83\uc744 \uc77d\uc5c8\ub358 \uc0ac\ub78c\uc758 \uc190\uacfc \ubaa9\uc18c\ub9ac\ub3c4 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uc789\uce74\uc758 \ub9e4\ub4ed\uc740 \uae00\uc790\uc758 \uc5ed\uc0ac \ubc16\uc73c\ub85c \ubc00\uc5b4 \ub450\uc5c8\ub358 \uae30\ub85d\uc758 \uc138\uacc4\ub97c \ub2e4\uc2dc \ud3bc\uccd0 \uc8fc\ub294 \uc791\uc740 \uc7a5\ubd80\ub2e4."}, {"id": "india-1857-rebellion-company-and-crown", "title": "\uc778\ub3c4 1857 \u2014 \ubcd1\uc0ac\ub4e4\uc758 \ubd09\uae30\ub294 \uc65c \ud1b5\uce58\uc790\ub97c \ubc14\uafb8\uc5c8\uc744\uae4c", "summary": "\ud0c4\uc57d\uc758 \ub450\ub824\uc6c0\uacfc \uc9c0\uc5ed\uc758 \ubd88\ub9cc,1858\ub144 \ud1b5\uce58 \uc774\uad00\uc758 \uc758\ubbf8\uc758 \ubc30\uacbd\uacfc \uc804\uac1c, \uc774\ud6c4\uc758 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/india-1857-rebellion-company-and-crown/index.html", "image": "../media/india-1857-rebellion-company-and-crown.png", "alt": "\uad70\uc601\uc5d0 \uc18c\uc2dd\uc774 \uc804\ud574\uc9c0\ub294 \ubaa8\uc2b5\uc744 \uc0c1\uc0c1\ud55c1857\ub144 \uc778\ub3c4 \ubd09\uae30 \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\uc778\ub3c4 1857 \u2014 \ubcd1\uc0ac\ub4e4\uc758 \ubd09\uae30\ub294 \uc65c \ud1b5\uce58\uc790\ub97c \ubc14\uafb8\uc5c8\uc744\uae4c \ud0c4\uc57d\uc758 \ub450\ub824\uc6c0\uacfc \uc9c0\uc5ed\uc758 \ubd88\ub9cc,1858\ub144 \ud1b5\uce58 \uc774\uad00\uc758 \uc758\ubbf8 \ud0c4\uc57d\uc758 \ub450\ub824\uc6c0\uacfc \uc9c0\uc5ed\uc758 \ubd88\ub9cc,1858\ub144 \ud1b5\uce58 \uc774\uad00\uc758 \uc758\ubbf8\uc758 \ubc30\uacbd\uacfc \uc804\uac1c, \uc774\ud6c4\uc758 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uad70\ub300 \uc548\uc5d0\uc11c \uc2dc\uc791\ub41c \ubd88\ub9cc\uc774 \ud68c\uc0ac\ub97c \ub118\uc5b4 \uc81c\uad6d\uc758 \ud1b5\uce58 \ubc29\uc2dd\uc744 \ubc14\uafb8\uc5c8\ub2e4. 1857\ub144 \uc778\ub3c4\uc5d0\uc11c \uc77c\uc5b4\ub09c \ubd09\uae30\ub294 \uc601\uad6d \ub3d9\uc778\ub3c4\ud68c\uc0ac\uc758 \uc9c0\ubc30\uac00 \uc5bc\ub9c8\ub098 \ub9ce\uc740 \uae34\uc7a5\uc744 \ud488\uace0 \uc788\uc5c8\ub294\uc9c0 \ub4dc\ub7ec\ub0c8\ub2e4. \uadf8\ub7ec\ub098 \uc9c0\uc5ed\ub9c8\ub2e4 \ucc38\uc5ec\uc790\uc640 \ubaa9\uc801\uc740 \ub2ec\ub790\uace0 \ubaa8\ub4e0 \uc778\ub3c4\uc778\uc774 \ud558\ub098\uc758 \uacc4\ud68d\uc73c\ub85c \uc6c0\uc9c1\uc778 \uac83\ub3c4 \uc544\ub2c8\uc5c8\ub2e4. \uc774 \uc0ac\uac74\uc744 \ub530\ub77c\uac00\uba74 \ud0c4\uc57d\uc758 \uc18c\ubb38\uc5d0\uc11c \uc2dc\uc791\ud574 \ud1a0\uc9c0\uc640 \uc655\uad8c, \uc885\uad50\uc640 \uc0dd\uacc4\uac00 \uc5bd\ud78c \ub354 \ub113\uc740 \uc138\uacc4\ub97c \ub9cc\ub098\uac8c \ub41c\ub2e4. \ub3d9\uc778\ub3c4\ud68c\uc0ac\ub294 \ubb34\uc5ed \ud68c\uc0ac\uc600\uc9c0\ub9cc \uc804\uc7c1\uacfc \uc870\uc57d, \uc601\ud1a0 \ud655\uc7a5\uc744 \ud1b5\ud574 \uc778\ub3c4\uc758 \uad11\ub300\ud55c \uc9c0\uc5ed\uc744 \ub2e4\uc2a4\ub9ac\ub294 \uad8c\ub825\uc774 \ub418\uc5c8\ub2e4. \uc138\uae08\uc744 \uac70\ub450\uace0 \uad70\ub300\ub97c \uc720\uc9c0\ud558\uba70 \ub2e4\ub978 \ud1b5\uce58\uc790\ub4e4\uc758 \uc9c0\uc704\ub97c \ubc14\uafb8\ub294 \uc77c\uc740 \uc0c1\ud488\uc744 \uc0ac\uace0\ud30c\ub294 \uc77c\uacfc \ub2ec\ub790\ub2e4. \ud68c\uc0ac \uc9c0\ubc30\uc758 \ud655\ub300\ub294 \uc11c\ub85c \ub2e4\ub978 \uc9d1\ub2e8\uc5d0 \ub2e4\ub978 \ubd88\ub9cc\uc744 \ub0a8\uacbc\ub2e4. \uad8c\uc704\ub97c \uc783\uc740 \uad70\uc8fc\uc640 \uadc0\uc871, \ud1a0\uc9c0\uc640 \uc218\uc785\uc744 \ub458\ub7ec\uc2fc \uc9c8\uc11c\uc758 \ubcc0\ud654\uc5d0 \ubd80\ub52a\ud78c \uc0ac\ub78c\ub4e4, \uad70\ub300 \uc548\uc5d0\uc11c \ub300\uc6b0\uc5d0 \ubd88\ub9cc\uc744 \uac00\uc9c4 \ubcd1\uc0ac\ub4e4\uc774 \uc788\uc5c8\ub2e4. \uc774\ub4e4\uc758 \uc774\ud574\uad00\uacc4\uac00 \uac19\uc9c0\ub294 \uc54a\uc544\ub3c4 \ubd88\uc2e0\uc774 \uc313\uc77c \uc870\uac74\uc740 \ub113\uc5b4\uc9c0\uace0 \uc788\uc5c8\ub2e4. \uad70\ub300 \uc548\uc758 \uad00\uacc4\ub3c4 \ud68c\uc0ac \uc9c0\ubc30\uc640 \uc9c0\uc5ed \uc0ac\ud68c\ub97c \uc774\uc5b4 \uc8fc\uc5c8\ub2e4. \ubcd1\uc0ac\ub294 \uad70\uc601 \ubc16\uc5d0 \uac00\uc871\uacfc \uc0dd\ud65c\uc758 \uae30\ubc18\uc744 \ub450\uace0 \uc788\uc5c8\uace0, \uc601\ud1a0 \ubcd1\ud569\uc774\ub098 \uc138\uae08 \ubb38\uc81c\uc640 \uc644\uc804\ud788 \ubd84\ub9ac\ub41c \uc874\uc7ac\uac00 \uc544\ub2c8\uc5c8\ub2e4. \uad70\uc0ac\uc801 \ubd88\ub9cc\uacfc \uc0ac\ud68c\uc801 \ubd88\ub9cc\uc774 \ub9cc\ub098\ub294 \uae38\uc744 \uc0b4\ud53c\uba74 \uc0ac\uac74\uc774 \uc5ec\ub7ec \uc9c0\uc5ed\uc73c\ub85c \ubc88\uc9c4 \uc870\uac74\uc774 \ub354 \uc798 \ubcf4\uc778\ub2e4. \uc0c8 \uc18c\ucd1d\uc758 \ud0c4\uc57d\uc744 \uc785\uc73c\ub85c \ubb3c\uc5b4 \uac1c\ubd09\ud558\ub294 \ubc29\uc2dd\uc740 \ubcd1\uc0ac\ub4e4\uc758 \uc885\uad50\uc801 \uae08\uae30\uc640 \uc5f0\uacb0\ub418\uc5b4 \ud070 \ubb38\uc81c\uac00 \ub418\uc5c8\ub2e4. \ud0c4\uc57d\uc5d0 \uc18c\ub098 \ub3fc\uc9c0\uc758 \uae30\ub984\uc744 \uc37c\ub2e4\ub294 \uc18c\ubb38\uc740 \ud78c\ub450\uad50\ub3c4\uc640 \ubb34\uc2ac\ub9bc \ubcd1\uc0ac \ubaa8\ub450\uc5d0\uac8c \ubd88\uc548\uc744 \ubd88\ub7ec\uc77c\uc73c\ucf30\ub2e4. \ubb34\uae30\ub97c \uc4f0\ub294 \ub3d9\uc791\uc774 \uc2e0\uc559\uc744 \ud6fc\uc190\ud558\ub294 \uc77c\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc9c8 \uc218 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4. \uc5ec\uae30\uc11c \uc911\uc694\ud55c \uac83\uc740 \ubaa8\ub4e0 \ud0c4\uc57d\uc758 \uc131\ubd84\uc744 \uc18c\ubb38 \ud558\ub098\ub85c \ud655\uc815\ud558\ub294 \uc77c\uc774 \uc544\ub2c8\ub2e4. \ud68c\uc0ac\uac00 \uc790\uc2e0\ub4e4\uc758 \uc885\uad50\uc640 \uc0dd\ud65c\uc744 \uc874\uc911\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \ubd88\uc2e0\uc774 \uc774\ubbf8 \uc874\uc7ac\ud588\ub2e4\ub294 \uc810\uc774\ub2e4. \uc9c0\ud718\uad00\uc758 \uc124\uba85\ub9cc\uc73c\ub85c \uc758\uc2ec\uc744 \uac00\ub77c\uc549\ud788\uae30 \uc5b4\ub824\uc6e0\ub358 \uae4c\ub2ed\ub3c4 \uadf8 \uc624\ub798\ub41c \uad00\uacc4\uc5d0 \uc788\uc5c8\ub2e4. 1857\ub144 5\uc6d4 \uba54\ub8e8\ud2b8\uc5d0\uc11c \ubd09\uae30\uac00 \uc77c\uc5b4\ub0ac\uace0 \ubcd1\uc0ac\ub4e4\uc740 \ub378\ub9ac\ub85c \uc774\ub3d9\ud588\ub2e4. \ub378\ub9ac\uc758 \ubb34\uad74 \ud669\uc81c \ubc14\ud558\ub450\ub974 \uc0e4 2\uc138\ub294 \ud604\uc2e4\uc758 \uad8c\ud55c\uc774 \uc81c\ud55c\ub418\uc5b4 \uc788\uc5c8\uc9c0\ub9cc \uc624\ub798\ub41c \uc655\uad8c\uc744 \uc0c1\uc9d5\ud558\ub294 \uc778\ubb3c\uc774\uc5c8\ub2e4. \uadf8\ub97c \ub0b4\uc138\uc6b0\ub294 \uac83\uc740 \ud68c\uc0ac \uc9c0\ubc30\uc640 \ub2e4\ub978 \uc815\ub2f9\uc131\uc744 \ucc3e\ub294 \ud589\ub3d9\uc774 \ub420 \uc218 \uc788\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \ud669\uc81c\uc758 \uc774\ub984 \uc544\ub798 \ubaa8\ub4e0 \uc6c0\uc9c1\uc784\uc774 \ud558\ub098\uc758 \uc9c0\ud718 \uccb4\uacc4\ub85c \ubb36\uc778 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc9c0\uc5ed\ubcc4 \uad70\uc0ac \ud589\ub3d9\uacfc \uc815\uce58\uc801 \ubaa9\ud45c\ub294 \ub2ec\ub790\ub2e4. \uc601\uad6d \uce21\uc774 \ubcd1\uc0ac\uc758 \ubc18\ub780\uc73c\ub85c \ubd80\ub974\uace0 \ub4a4\uc758 \uc0ac\ub78c\ub4e4\uc774 \ub3c5\ub9bd\uc804\uc7c1\uc758 \uc758\ubbf8\ub97c \uac15\uc870\ud558\ub294 \uc0ac\uc774\uc5d0\ub294, \uc5b4\ub5a4 \ucc38\uc5ec\uc790\uc640 \ubaa9\uc801\uc744 \uc911\uc2ec\uc5d0 \ub193\ub294\uac00\ub77c\ub294 \ud574\uc11d\uc758 \ucc28\uc774\uac00 \uc788\ub2e4. \uc774\ub3d9\ud558\ub294 \ubcd1\uc0ac\uc640 \uc804\ub2ec\ub418\ub294 \uc18c\uc2dd\uc740 \uc9c0\uc5ed\ub9c8\ub2e4 \ub2e4\ub978 \ubc18\uc751\uc744 \ubd88\ub7ec\uc654\ub2e4. \uac19\uc740 \uc0ac\uac74\uc744 \ub4e3\uace0\ub3c4 \ubd09\uae30\uc5d0 \ub098\uc11c\uac70\ub098 \uad00\ub9dd\ud558\uac70\ub098 \ud68c\uc0ac \uce21\uc744 \ub3d5\ub294 \ud310\ub2e8\uc774 \uac00\ub2a5\ud588\ub2e4. \ucc38\uc5ec\ud558\uc9c0 \uc54a\uc740 \uc0ac\ub78c\ub4e4\uae4c\uc9c0 \ud55c \uac00\uc9c0 \ub73b\uc744 \uac00\uc9c4 \uc9d1\ub2e8\uc73c\ub85c \ubb36\uc9c0 \uc54a\ub294 \uac83\uc774 \uc804\uccb4\uc758 \ubcf5\uc7a1\ud568\uc744 \uc774\ud574\ud558\ub294 \ubc29\ubc95\uc774\ub2e4. 1856\ub144 \ud68c\uc0ac\uc5d0 \ubcd1\ud569\ub41c \uc544\uc640\ub4dc\uc5d0\uc11c\ub294 \ud1b5\uce58 \uc9c8\uc11c\uc758 \ubcc0\ud654\uac00 \ud070 \ucda9\uaca9\uc744 \ub0a8\uacbc\ub2e4. \uae30\uc874 \uc9c0\ubc30\uce35\uacfc \uc9c0\uc5ed \uc0ac\ud68c\uac00 \ucc98\ud55c \ubd88\ub9cc\uc740 \uad70\ub300 \uc548\uc758 \ubb38\uc81c\uc640 \ub9cc\ub0a0 \uc218 \uc788\uc5c8\ub2e4. \ub7ec\ud06c\ub098\uc6b0\ub97c \ub458\ub7ec\uc2fc \uc804\ud22c\ub294 \uc774\ub7f0 \uc9c0\uc5ed\uc758 \uc815\uce58\uc801 \ubc30\uacbd \uc18d\uc5d0 \ub193\uc5ec \uc788\uc5c8\ub2e4. \uc794\uc2dc\uc758 \ub77c\ub2c8 \ub77d\uc288\ubbf8 \ubc14\uc774 \uc5ed\uc2dc \uacc4\uc2b9\uacfc \uc9c0\ubc30\uad8c\uc758 \ubb38\uc81c\ub97c \uacaa\uc740 \uc778\ubb3c\uc774\uc5c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc9c0\uc5ed \uc9c0\ub3c4\uc790\ub4e4\uc774 \ubaa8\ub450 \uac19\uc740 \uc774\uc720\ub85c \uc2f8\uc6e0\ub2e4\uace0 \ubcf4\uba74 \uc774 \ucc28\uc774\uac00 \uc0ac\ub77c\uc9c4\ub2e4. \ud55c\ud3b8 \ud68c\uc0ac \ud3b8\uc5d0 \uc120 \uad70\ub300\uc640 \ud1b5\uce58\uc790\ub4e4\ub3c4 \uc788\uc5c8\ub2e4. \uc778\ub3c4 \uc804\uccb4\uac00 \ub450 \uc9c4\uc601\uc73c\ub85c \uae54\ub054\ud558\uac8c \ub098\ub25c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ubd09\uae30\uc640 \uc9c4\uc555 \uacfc\uc815\uc5d0\uc11c \ubbfc\uac04\uc778\ub3c4 \uc0b4\ud574\ub418\uc5c8\ub2e4. \uc601\uad6d\uc778\uc758 \ud53c\ud574\ub97c \uc790\uc138\ud788 \uae30\ub85d\ud55c \ub2f9\uc2dc \ucc45\ub4e4\uc740 \uc885\uc885 \ubcf4\ubcf5\uc758 \uc815\ub2f9\uc131\uc744 \uac15\uc870\ud558\uace0 \uc778\ub3c4\uc778\uc758 \ud53c\ud574\ub97c \uc791\uac8c \ub2e4\ub8e8\uc5c8\ub2e4. \ubc18\ub300\ub85c \uc601\uc6c5\uc801\uc778 \uc800\ud56d\uc758 \uc7a5\uba74\ub9cc \uace0\ub974\uba74 \ubbfc\uac04\uc778\uc774 \uacaa\uc740 \uace0\ud1b5\uc774 \ub610 \uc9c0\uc6cc\uc9c8 \uc218 \uc788\ub2e4. \uc5ed\uc0ac\ub97c \uc77d\ub294 \uc77c\uc740 \uc5b4\ub290 \ucabd\uc758 \ud3ed\ub825\uc744 \ud658\ud638\ud560 \uc774\uc720\ub97c \ucc3e\ub294 \uc77c\uc774 \uc544\ub2c8\ub2e4. \ub204\uac00 \uc5b4\ub5a4 \uc870\uac74\uc5d0\uc11c \uc8fd\uac70\ub098 \ud53c\ub780\ud574\uc57c \ud588\ub294\uc9c0, \uc5b4\ub5a4 \uae30\ub85d\uc774 \ub0a8\uace0 \uc5b4\ub5a4 \ubaa9\uc18c\ub9ac\uac00 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\uc9c0 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc804\ud22c\uc758 \uc2b9\ud328\uc640 \uc0ac\ub78c\ub4e4\uc758 \uc0dd\ud65c\uc774 \ud68c\ubcf5\ub418\ub294 \uc2dc\uac04\uc740 \uac19\uc9c0 \uc54a\uc558\ub2e4. \ubd09\uae30\uc758 \uc9c4\uc555\uacfc \ud568\uaed8 \uc601\uad6d\uc740 \ud1b5\uce58 \uad6c\uc870\ub97c \ubc14\uafb8\uc5c8\ub2e4. 1858\ub144 \ub3d9\uc778\ub3c4\ud68c\uc0ac\uc758 \uc9c0\ubc30 \uad8c\ud55c\uc740 \uc601\uad6d \uc655\uc2e4\ub85c \ub118\uc5b4\uac14\ub2e4. \uac19\uc740 \ud574 11\uc6d4 \ubc1c\ud45c\ub41c \uc5ec\uc655\uc758 \ud3ec\uace0\ub294 \uc885\uad50\uc5d0 \ub300\ud55c \uac04\uc12d\uacfc \ud1b5\uce58 \uc6d0\uce59 \ub4f1\uc744 \ub2e4\ub8e8\uba70 \uc0c8\ub85c\uc6b4 \uad00\uacc4\ub97c \uc57d\uc18d\ud588\ub2e4. \ud558\uc9c0\ub9cc \ud68c\uc0ac\uc758 \ud1f4\uc7a5\uc740 \uc778\ub3c4\uc758 \ub3c5\ub9bd\uc744 \ub73b\ud558\uc9c0 \uc54a\uc558\ub2e4. \uad8c\ud55c\uc744 \ud589\uc0ac\ud558\ub294 \uc601\uad6d \uce21\uc758 \uc870\uc9c1\uacfc \ucc45\uc784 \uad6c\uc870\uac00 \ubc14\ub010 \uac83\uc774\uc5c8\ub2e4. \uad70\ub300 \ud3b8\uc81c\uc640 \ud1b5\uce58 \ubc29\uc2dd\ub3c4 \uc7ac\uac80\ud1a0\ub418\uc5c8\ub2e4. \ud3ec\uace0\uc758 \ud45c\ud604\uacfc \uc774\ud6c4\uc758 \uc2e4\uc81c \uc6b4\uc601\uc774 \uc5b8\uc81c\ub098 \uc77c\uce58\ud588\ub294\uc9c0\ub294 \ubcc4\ub3c4\ub85c \ub530\uc838\uc57c \ud558\ub294 \ubb38\uc81c\ub2e4. 1857\ub144\uc744 \ubb34\uc5c7\uc774\ub77c\uace0 \ubd80\ub974\ub294\uac00\ub294 \uc0ac\uc18c\ud55c \ub9d0\uc758 \uc120\ud0dd\uc774 \uc544\ub2c8\ub2e4. \ubcd1\uc0ac\uc758 \uba85\ub839 \ubd88\ubcf5\uc885\uc744 \uc911\uc2ec\uc5d0 \ub193\uc73c\uba74 \uad70\ub300\uc758 \uc0ac\uac74\uc774 \ub418\uace0, \uc9c0\uc5ed\uc758 \uc655\uad8c\uacfc \uc0ac\ud68c\uc801 \ubd88\ub9cc\uc744 \ud568\uaed8 \ubcf4\uba74 \ub354 \ub113\uc740 \uc9c0\ubc30\uc758 \uc704\uae30\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \ub2e4\uc591\ud55c \ucc38\uc5ec\uc790\ub97c \uc0b4\ud53c\ub294 \uc77c\uc774 \ud558\ub098\uc758 \uc774\ub984\uc744 \uace0\ub974\ub294 \uac83\ubcf4\ub2e4 \uba3c\uc800\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \ub2f9\uc2dc \uc18c\uc2dd\uc774 \uc804\ud574\uc9c0\ub294 \uad70\uc601\uc744 \uc5f0\uc0c1\ud558\ub294 \uc124\uba85\uc6a9 \uc0bd\ud654\ub2e4. \ud2b9\uc815 \ubd80\ub300\ub098 \uc778\ubb3c\uc744 \ucd2c\uc601\ud55c \uae30\ub85d\uc740 \uc544\ub2c8\ub2e4. \uc624\ub798\ub41c \uc601\uad6d \uce21 \uc11c\uc220\ub3c4 \ub2f9\uc2dc\uc758 \uc2dc\uac01\uc744 \uc0b4\ud53c\ub294 \uc790\ub8cc\ub85c \uc77d\ub418, \uadf8 \uc548\uc758 \uc778\uc885\uc801 \ube44\ud558\uc640 \uc81c\uad6d \uc9c0\ubc30\ub97c \ub2f9\uc5f0\uc2dc\ud55c \ud310\ub2e8\uc744 \uc0ac\uc2e4\uc758 \uc124\uba85\uc73c\ub85c \ubc1b\uc544\ub4e4\uc774\uc9c0 \uc54a\uc544\uc57c \ud55c\ub2e4."}, {"id": "isfahan-square-and-everyday-life", "title": "\uc774\uc2a4\ud30c\ud55c \u2014 \uad11\uc7a5\uc5d0\uc11c\ub294 \uc7a5\uc0ac\ub3c4 \ud558\uace0 \uacf5\ub3c4 \ucce4\ub2e4", "summary": "\ub098\ud06c\uc170 \uc790\ud55c \uad11\uc7a5\uc5d0\uc11c \ud1b5\uce58\u00b7\uad50\uc5ed\u00b7\uc758\ub840\uc640 \uc77c\uc0c1\uc774 \ud568\uaed8 \ub9cc\ub098\ub294 \ubc29\uc2dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/isfahan-square-and-everyday-life/index.html", "image": "../media/isfahan-square-and-everyday-life.jpg", "alt": "\uc774\uc2a4\ud30c\ud55c \ub098\ud06c\uc170 \uc790\ud55c \uad11\uc7a5\uc758 \uc815\uc6d0 \ub108\uba38 \uc0e4 \ubaa8\uc2a4\ud06c\ub97c \ubc14\ub77c\ubcf8 \uc0ac\uc9c4.", "text": "\uc774\uc2a4\ud30c\ud55c \u2014 \uad11\uc7a5\uc5d0\uc11c\ub294 \uc7a5\uc0ac\ub3c4 \ud558\uace0 \uacf5\ub3c4 \ucce4\ub2e4 \uad81\uc804\uacfc \ubaa8\uc2a4\ud06c \uc0ac\uc774\uc5d0 \ud3bc\uccd0\uc9c4 \ub3c4\uc2dc\uc758 \ubb34\ub300 \ub098\ud06c\uc170 \uc790\ud55c \uad11\uc7a5\uc5d0\uc11c \ud1b5\uce58\u00b7\uad50\uc5ed\u00b7\uc758\ub840\uc640 \uc77c\uc0c1\uc774 \ud568\uaed8 \ub9cc\ub098\ub294 \ubc29\uc2dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ucee4\ub2e4\ub780 \uad11\uc7a5\uc744 \ubcf4\uba74 \ub113\uace0 \ube44\uc5b4 \uc788\ub294 \ubc14\ub2e5\ubd80\ud130 \ubcf4\uac8c \ub41c\ub2e4. \ud558\uc9c0\ub9cc \ube44\uc5b4 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ud560 \uc77c\uc774 \uc5c6\uc5c8\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uc7a5\uc744 \uc5f4\uace0 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc774\uace0, \uc5b4\ub5a4 \ub0a0\uc5d0\ub294 \ub9d0\uc744 \ud0c0\uace0 \uacf5\uc744 \uce58\ub294 \uacbd\uae30\uac00 \ubc8c\uc5b4\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \uacf5\uac04\uc744 \ube44\uc6cc \ub450\uc5c8\uae30\uc5d0 \uc5ec\ub7ec \uc77c\uc774 \ub4e4\uc5b4\uc628\ub2e4. \uc774\ub780 \uc774\uc2a4\ud30c\ud55c\uc758 \ub098\ud06c\uc170 \uc790\ud55c \uad11\uc7a5\uc740 \uc774\ub7f0 \uc0dd\uac01\uc73c\ub85c \ubcf4\uae30 \uc88b\uc740 \uc7a5\uc18c\ub2e4. \uc8fc\ubcc0\uc5d0\ub294 \uad81\uc815\uc758 \uacf5\uac04\uacfc \ubaa8\uc2a4\ud06c, \uc2dc\uc7a5\uc774 \uc5f0\uacb0\ub418\uc5c8\ub2e4. \uac74\ubb3c \ud558\ub098\uc529\uc758 \uc544\ub984\ub2e4\uc6c0\ub3c4 \uc911\uc694\ud558\uc9c0\ub9cc \uadf8 \uc0ac\uc774\uc758 \ud070 \uc5f4\ub9b0 \uc790\ub9ac\uac00 \ubb34\uc5c7\uc744 \uac00\ub2a5\ud558\uac8c \ud588\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc0ac\ud30c\ube44 \uc655\uc870\uc758 \uc544\ubc14\uc2a4 1\uc138\ub294 1598\ub144 \uc218\ub3c4\ub97c \uce74\uc988\ube48\uc5d0\uc11c \uc774\uc2a4\ud30c\ud55c\uc73c\ub85c \uc62e\uacbc\ub2e4. \uad50\uc7ac\ub294 \uc774 \uc704\uce58\uac00 \ubd88\uc548\uc815\ud55c \uad6d\uacbd\uc5d0\uc11c \ub354 \uba40\uace0 \ud398\ub974\uc2dc\uc544\ub9cc\uacfc \uc0c8\ub85c\uc6b4 \uad50\uc5ed \uc0c1\ub300\uc5d0\uac8c \ub354 \uac00\uae4c\uc6e0\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc218\ub3c4\ub294 \ubcf4\uae30 \uc88b\uc740 \uc7a5\uc18c\ub97c \uace0\ub974\ub294 \ubb38\uc81c\ub9cc\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ud1b5\uce58\uc758 \uc548\uc815\uacfc \ubb3c\uc790\uc758 \uc774\ub3d9, \ub2e4\ub978 \uc9c0\uc5ed\uacfc\uc758 \uad00\uacc4\uac00 \ud568\uaed8 \uace0\ub824\ub41c\ub2e4. \uc0c8 \uc218\ub3c4\ub97c \ub9cc\ub4e0\ub2e4\ub294 \uac83\uc740 \uac74\ubb3c\uc744 \uc62e\uae30\ub294 \uc77c\ubfd0 \uc544\ub2c8\ub77c \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5a4 \ubc29\ud5a5\uc73c\ub85c \ubaa8\uc774\uace0 \uc790\uc6d0\uc774 \uc5b4\ub514\uc5d0 \uc9d1\uc911\ub420\uc9c0\ub97c \ubc14\uafb8\ub294 \uc120\ud0dd\uc774\ub2e4. \uc774\uc2a4\ud30c\ud55c\uc758 \ud070 \uacf5\uac04\uc5d0\ub294 \uadf8\ub7f0 \uc815\uce58\uc801 \uad6c\uc0c1\uc774 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \ub098\ud06c\uc170 \uc790\ud55c \uad11\uc7a5 \uc8fc\ubcc0\uc5d0\ub294 \ud589\uc815 \uacf5\uac04\uacfc \uacf5\uacf5 \uc2dc\uc7a5\uc774 \uc5f4\ub824 \uc788\uc5c8\ub2e4. \uc655\uc2e4\uc758 \uacf5\uac04\uc740 \uad11\uc7a5\uc744 \ub0b4\ub824\ub2e4\ubcf4\uc558\uace0, \ub0a8\ucabd\uc5d0\ub294 \uc0e4 \ubaa8\uc2a4\ud06c\uac00 \uc790\ub9ac\ud588\ub2e4. \uc885\uad50\uc640 \uad8c\ub825, \uac70\ub798\uc758 \uc7a5\uc18c\uac00 \ud070 \uc5f4\ub9b0 \uacf5\uac04\uc744 \ud568\uaed8 \ub9c8\uc8fc\ud55c \uac83\uc774\ub2e4. \uac01 \uac74\ubb3c\uc744 \ub530\ub85c \uac10\uc0c1\ud560 \ub54c\ub294 \ub2e4\ub978 \uae30\ub2a5\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uadf8\ub7ec\ub098 \uad11\uc7a5\uc5d0\uc11c \ubc14\ub77c\ubcf4\uba74 \uac19\uc740 \ub3c4\uc2dc\uc758 \uc911\uc2ec\uc744 \ub9cc\ub4dc\ub294 \uc694\uc18c\ub4e4\uc774 \ub41c\ub2e4. \ub204\uad6c\ub97c \ud5a5\ud574 \uc785\uad6c\uac00 \uc5f4\ub9ac\uace0 \uc5b4\ub290 \uacf3\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc774 \uc11c\ub85c\ub97c \ubcfc \uc218 \uc788\uc5c8\ub294\uc9c0 \uc0dd\uac01\ud558\uba74 \uacf5\uac04\uc758 \ubc30\uce58\uac00 \uc774\uc57c\uae30\ub97c \uc2dc\uc791\ud55c\ub2e4. \uad50\uc7ac\ub294 \uc774 \uc911\uc2ec\uc5d0\uc11c \uad81\uc815 \uc0ac\ub78c\uacfc \uc131\uc9c1\uc790, \uc678\uad6d \uc0ac\uc808\uacfc \uad70\uc778, \uc0c1\uc778\uacfc \uc77c\ubc18 \uc8fc\ubbfc\uc774 \uc11e\uc77c \uc218 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc2e0\ubd84\uc774 \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc774 \uac19\uc740 \uc7a5\uc18c\uc5d0 \uc788\uc5c8\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uadf8\ub807\ub2e4\uace0 \uadf8\ub4e4\uc774 \ubaa8\ub450 \uac19\uc740 \uad8c\ud55c\uc744 \uac00\uc84c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uad11\uc7a5\uc758 \uac1c\ubc29\uc131\uacfc \uc0ac\ud68c\uc758 \ud3c9\ub4f1\uc740 \ub2e4\ub978 \uc9c8\ubb38\uc774\ub2e4. \ub204\uad70\uac00\ub294 \ud589\uc0ac\ub97c \uc9c0\ucf1c\ubcf4\uace0 \ub204\uad70\uac00\ub294 \ud1b5\uce58\uc790\uc758 \uc704\uc138\ub97c \ubcf4\uc600\uc744 \uc218 \uc788\ub2e4. \ud55c \uacf5\uac04\uc744 \ud568\uaed8 \uc4f4\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8 \uc548\uc5d0\uc11c \ucc28\uc9c0\ud55c \uc790\ub9ac\ub294 \uad6c\ubcc4\ud574 \ubcfc \uc218 \uc788\ub2e4. \ub3c4\uc2dc\uc758 \uc911\uc2ec\uc740 \ub9cc\ub0a8\uc758 \uc790\ub9ac\uc774\uba74\uc11c \ucc28\uc774\uac00 \ub4dc\ub7ec\ub098\ub294 \uc790\ub9ac\uc774\uae30\ub3c4 \ud558\ub2e4. \uad11\uc7a5\uc740 \ub54c\ub54c\ub85c \ud3f4\ub85c \uacbd\uae30\uc640 \uacf5\uc801 \uc758\ub840, \ucd95\uc81c\ub97c \uc704\ud574 \ube44\uc6cc\uc84c\ub2e4. \ud3c9\uc18c\uc758 \uc774\ub3d9\uacfc \uac70\ub798\uac00 \ub2e4\ub978 \ud589\uc0ac\ub97c \uc704\ud55c \uacf5\uac04\uc73c\ub85c \ubc14\ub010 \uac83\uc774\ub2e4. \ub113\uc740 \uc7a5\uc18c\ub97c \ud55c \uac00\uc9c0 \uc6a9\ub3c4\uc758 \uc0c1\uc790\ucc98\ub7fc\ub9cc \uc0dd\uac01\ud558\uba74 \uc774\ub7f0 \ubcc0\ud654\ub294 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc0ac\uc9c4\uc5d0\ub294 \ub2f9\uc2dc\uc758 \uacbd\uae30 \uc7a5\uba74\uc774 \ub2f4\uaca8 \uc788\uc9c0 \uc54a\ub2e4. \uadf8\ub798\uc11c \ud2b9\uc815 \uc120\uc218\uac00 \uc5b4\ub514\uc5d0\uc11c \ub2ec\ub838\ub294\uc9c0 \uc0c1\uc0c1\uc73c\ub85c \uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uad11\uc7a5\uc758 \uae38\uc774\uc640 \uc5f4\ub9b0 \ud3ed\uc744 \ubcf4\uba70 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc774\uace0 \uc6c0\uc9c1\uc774\ub294 \ud589\uc0ac\uc5d0 \uc5b4\ub5a4 \uc870\uac74\uc744 \uc8fc\uc5c8\uc744\uc9c0 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uac74\ubb3c \uc0ac\uc774\uc758 \ube48 \uacf5\uac04\ub3c4 \ub3c4\uc2dc\uc758 \uc911\uc694\ud55c \uc2dc\uc124\uc774\uc5c8\ub2e4. \uc774\uc2a4\ud30c\ud55c\uc5d0\ub294 \ucc28\ud558\ub974 \ubc14\uadf8\ub77c\ub294 \ub113\uc740 \uac00\ub85c\uc640 \uad81\uc804, \uc815\uc6d0\ub3c4 \uc870\uc131\ub418\uc5c8\ub2e4. \uad50\uc7ac\ub294 \ub098\ubb34\uc758 \uadf8\ub298\uacfc \uacfc\uc77c\ub098\ubb34, \ubd84\uc218\uc640 \ud750\ub974\ub294 \ubb3c\uc744 \ud568\uaed8 \uc124\uba85\ud55c\ub2e4. \ub3c4\uc2dc\ub294 \ub192\uc740 \ub3d4\uacfc \uc7a5\uc2dd\ub9cc\uc73c\ub85c \uafb8\uba70\uc9c4 \uac83\uc774 \uc544\ub2c8\ub77c \uc18c\ub9ac\uc640 \ubc14\ub78c, \ub0c4\uc0c8\ub97c \uacbd\ud5d8\ud558\ub294 \uacf5\uac04\uc73c\ub85c\ub3c4 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4. \ubb3c\uc774 \ud750\ub974\uace0 \ub098\ubb47\uc78e\uc774 \ud754\ub4e4\ub9ac\ub294 \uc870\uac74\uc740 \uac74\ucd95\uc758 \ud06c\uae30\uc640 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uc0ac\ub78c\uc758 \ubab8\uc5d0 \ub2ff\ub294\ub2e4. \ub3c4\uc2dc\ub97c \ubcf8\ub2e4\ub294 \ub9d0\uc744 \uc7a0\uc2dc \ub113\ud788\uba74 \uac77\uace0 \uc26c\uace0 \ub4e3\ub294 \uc77c\ub3c4 \ud3ec\ud568\ub41c\ub2e4. \uc544\ub984\ub2e4\uc6b4 \uc218\ub3c4\ub77c\ub294 \ud45c\ud604\uc774 \uc0ac\uc9c4\uc758 \uc678\uad00\ub9cc\uc744 \ub73b\ud558\uc9c0 \uc54a\uc558\uc74c\uc744 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc544\ubc14\uc2a4\ub294 \uc0c8 \uc218\ub3c4\ub97c \ucc44\uc6b0\uae30 \uc704\ud574 \uc5ec\ub7ec \uacf5\ub3d9\uccb4\ub97c \uc774\uc8fc\uc2dc\ucf30\ub2e4. \uadf8\uc911\uc5d0\ub294 \uc804\uc7c1 \uacfc\uc815\uc5d0\uc11c \uace0\ud5a5\uc744 \ub5a0\ub098\uc57c \ud588\ub358 \uc544\ub974\uba54\ub2c8\uc544\uc778\uacfc \uce85\uce74\uc2a4 \uc9c0\uc5ed \uc0ac\ub78c\ub4e4\ub3c4 \uc788\uc5c8\ub2e4. \ub3c4\uc2dc\uac00 \ub2e4\ucc44\ub85c\uc6cc\uc84c\ub2e4\ub294 \uacb0\uacfc\ub97c \ubaa8\ub450\uc758 \uc790\uc720\ub85c\uc6b4 \uc5ec\ud589\uc73c\ub85c \uadf8\ub9b4 \uc218\ub294 \uc5c6\ub2e4. \uc544\ub974\uba54\ub2c8\uc544 \uae30\ub3c5\uad50 \uacf5\ub3d9\uccb4\uc758 \uc885\uad50 \uacf5\uac04\uacfc \uacbd\uc81c \ud65c\ub3d9\ub3c4 \uc774 \ub3c4\uc2dc\uc758 \uc77c\ubd80\uac00 \ub418\uc5c8\ub2e4. \uad50\uc7ac\ub294 \uc2e4\ud06c \uc81c\uc870\uc640 \uc218\ucd9c\uc5d0 \ucc38\uc5ec\ud55c \uc0ac\ub78c\ub4e4\uc758 \uc5ed\ud560\uc744 \uc124\uba85\ud55c\ub2e4. \ub2e4\ub978 \uc2e0\uc559\uc744 \ubc1b\uc544\ub4e4\uc778 \ub3c4\uc2dc\uc758 \ubaa8\uc2b5\uacfc \ud1b5\uce58\uc790\uac00 \uc0ac\ub78c\uc744 \uc774\ub3d9\uc2dc\ud0a8 \uad8c\ub825\uc740 \uac19\uc740 \uc5ed\uc0ac \uc548\uc5d0 \ud568\uaed8 \uc788\uc5c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc2e4\uc81c \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uba3c\uc800 \uad11\uc7a5\uc758 \ub113\uc740 \uc790\ub9ac\uc640 \uadf8 \ub4a4\uc758 \uc0e4 \ubaa8\uc2a4\ud06c\ub97c \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc774\uc5b4 \uc0ac\ub78c\uc758 \ud06c\uae30\uc640 \uac74\ubb3c\uc758 \ub192\uc774\ub97c \ube44\uad50\ud574 \ubcf4\uc790. \ud070 \uc7a5\uc2dd\uc758 \uc138\ubd80\ub97c \ub2e4 \uc54c\uc9c0 \ubabb\ud574\ub3c4 \uc911\uc2ec \uacf5\uac04\uc758 \uaddc\ubaa8\uc640 \ubc29\ud5a5\uc740 \ub290\ub084 \uc218 \uc788\ub2e4. \uc774 \uc0ac\uc9c4\uc774 \ub2f9\uc2dc\uc758 \ud589\uc0ac\ub97c \uadf8\ub300\ub85c \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud604\uc7ac\uae4c\uc9c0 \ub0a8\uc740 \uacf5\uac04\uc5d0\uc11c \uacfc\uac70\uc758 \uae30\ub2a5\uc744 \uc790\ub8cc\uc640 \ud568\uaed8 \uc77d\ub294 \uac83\uc774\ub2e4. \uad50\uc7ac\uac00 \uc124\uba85\ud55c \uc2dc\uc7a5\uacfc \uc758\ub840, \ud3f4\ub85c\ub97c \ub5a0\uc62c\ub9ac\uba74 \uc0ac\uc9c4 \uc18d \ube44\uc5b4 \ubcf4\uc774\ub294 \uc790\ub9ac\uc5d0\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc2dc\uac04\uc758 \uc4f0\uc784\uc774 \ub193\uc778\ub2e4. \uc774\uc2a4\ud30c\ud55c\uc758 \uad11\uc7a5\uc740 \ub2e8\uc21c\ud788 \uba4b\uc9c4 \uac74\ubb3c\uc744 \uac10\uc0c1\ud560 \ubc30\uacbd\uc774 \uc544\ub2c8\ub2e4. \uad8c\ub825\uacfc \uad50\uc5ed, \uc2e0\uc559\uacfc \uc77c\uc0c1\uc774 \ub9cc\ub098\ub294 \ubb34\ub300\uc600\ub2e4. \uac19\uc740 \ubc14\ub2e5\uc774 \ub2e4\ub978 \ub0a0\uc5d0\ub294 \ub2e4\ub978 \uc5ed\ud560\uc744 \ud560 \uc218 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub3c4\uc2dc\ub97c \uc0b4\uc544 \uc788\ub294 \uacf5\uac04\uc73c\ub85c \ubcf4\uac8c \ud55c\ub2e4. \ub2e4\uc74c\uc5d0 \ud070 \uad11\uc7a5\uc744 \uac78\uc744 \ub54c \ubb34\uc5c7\uc744 \uc138\uc6cc \ub193\uc558\ub294\uc9c0\ub9cc \ubcf4\uc9c0 \ub9d0\uace0 \ubb34\uc5c7\uc744 \uc704\ud574 \ube44\uc6cc \ub450\uc5c8\ub294\uc9c0\ub3c4 \uc0b4\ud3b4\ubcf4\uc790. \uc774\uc2a4\ud30c\ud55c\uc758 \uc5f4\ub9b0 \uc911\uc2ec\uc740 \uc0ac\ub78c\uc774 \ubaa8\uc774\uace0 \uad8c\uc704\uac00 \ubcf4\uc774\uba70 \ud589\uc0ac\uac00 \ud3bc\uccd0\uc9c0\ub294 \ubc29\uc2dd\uc744 \ud568\uaed8 \uc124\uacc4\ud55c \uc7a5\uc18c\uc600\ub2e4."}, {"id": "istanbul-hagia-sophia-many-times", "title": "\uc544\uc57c \uc18c\ud53c\uc544 \u2014 \ud070 \uc9c0\ubd95 \uc544\ub798 \uc5ec\ub7ec \uc2dc\ub300\uac00 \uba38\ubb3c\ub2e4", "summary": "19\uc138\uae30 \ub3c4\ud310\uc758 \ub3d4\uacfc \ucca8\ud0d1\uc744 \ub530\ub77c \uc544\uc57c \uc18c\ud53c\uc544\uc640 \uc774\uc2a4\ud0c4\ubd88\uc5d0 \uacb9\uce5c \uc2dc\ub300\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/istanbul-hagia-sophia-many-times/index.html", "image": "../media/istanbul-hagia-sophia-many-times.jpg", "alt": "\uc544\uc57c \uc18c\ud53c\uc544\uc758 \ud070 \uc911\uc559 \ub3d4\uacfc \ub0ae\uc740 \uc9c0\ubd95, \ucca8\ud0d1\uacfc \uac70\ub9ac\uc758 \uc0ac\ub78c\ub4e4\uc744 \ud45c\ud604\ud55c 1857\ub144 \uc5ed\uc0ac \ub3c4\ud310.", "text": "\uc544\uc57c \uc18c\ud53c\uc544 \u2014 \ud070 \uc9c0\ubd95 \uc544\ub798 \uc5ec\ub7ec \uc2dc\ub300\uac00 \uba38\ubb3c\ub2e4 \uc624\ub798\ub41c \uac74\ubb3c\uc740 \ud55c \ubc88\uc5d0 \uc644\uc131\ub41c \ubaa8\uc2b5\uc73c\ub85c \ub0a8\uc9c0 \uc54a\ub294\ub2e4 19\uc138\uae30 \ub3c4\ud310\uc758 \ub3d4\uacfc \ucca8\ud0d1\uc744 \ub530\ub77c \uc544\uc57c \uc18c\ud53c\uc544\uc640 \uc774\uc2a4\ud0c4\ubd88\uc5d0 \uacb9\uce5c \uc2dc\ub300\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc774\uc2a4\ud0c4\ubd88\uc758 \uc624\ub798\ub41c \ud48d\uacbd\uc5d0\uc11c \uc544\uc57c \uc18c\ud53c\uc544\ub97c \ucc3e\uc744 \ub54c\ub294 \ud070 \ub3d4\uc744 \uba3c\uc800 \ubcf4\uac8c \ub41c\ub2e4. \uadf8 \uc606\uc73c\ub85c\ub294 \uac00\ub298\uace0 \ub192\uc740 \ucca8\ud0d1\ub4e4\uc774 \uc19f\uc544 \uc788\ub2e4. \ub0ae\uace0 \ub113\uc740 \uc9c0\ubd95\uacfc \uace7\uac8c \ubed7\uc740 \uc120\uc774 \ud55c\ub370 \uc788\uc73c\ub2c8 \ucc98\uc74c\ubd80\ud130 \uc774\ub7f0 \ubaa8\uc2b5\uc73c\ub85c \uc124\uacc4\ub418\uc5c8\uc744 \uac83 \uac19\ub2e4. \uadf8\ub7ec\ub098 \uc774 \uac74\ubb3c\uc744 \ud55c \ubc88\uc5d0 \ub9cc\ub4e0 \uc791\ud488\ucc98\ub7fc \uc0dd\uac01\ud558\uba74 \uc911\uc694\ud55c \uc774\uc57c\uae30\ub97c \ub193\uce5c\ub2e4. \ube44\uc794\ud2f4 \ud669\uc81c\uc758 \ub3c4\uc2dc\uc640 \uc624\uc2a4\ub9cc \uc220\ud0c4\uc758 \ub3c4\uc2dc\uac00 \uac19\uc740 \uc7a5\uc18c\uc5d0 \uacb9\uccd0 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 1857\ub144 \ub3c4\ud310\uc744 \ucc9c\ucc9c\ud788 \ubcf4\uba74 \uac74\ubb3c \ud558\ub098\uac00 \uc2dc\uac04\uc744 \ubcf4\uad00\ud558\ub294 \ubc29\uc2dd\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \uc544\uc57c \uc18c\ud53c\uc544\ub294 \uc131\uc2a4\ub7ec\uc6b4 \uc9c0\ud61c\ub97c \ub73b\ud558\ub294 \uc774\ub984\uc774\ub2e4. \uc18c\ud53c\uc544\ub77c\ub294 \uc778\ubb3c\uc5d0\uac8c \ubc14\uce5c \uac74\ubb3c\ub85c\ub9cc \uc774\ud574\ud558\uba74 \uc774\ub984\uc758 \ub73b\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uae30\ub3c5\uad50 \uc2e0\uc559\uc758 \uacf5\uac04\uc73c\ub85c \uc138\uc6cc\uc9c4 \uc774 \uac74\ubb3c\uc5d0\ub294 \ub2f9\uc2dc \ud1b5\uce58\uc790\uac00 \ud45c\ud604\ud558\ub824 \ud588\ub358 \uc885\uad50\uc801 \uad8c\uc704\ub3c4 \ub2f4\uaca8 \uc788\uc5c8\ub2e4. 6\uc138\uae30 \ud669\uc81c \uc720\uc2a4\ud2f0\ub2c8\uc544\ub204\uc2a4\ub294 \uc5ec\ub7ec \uad50\ud68c \uac74\uc124\uc744 \ud6c4\uc6d0\ud588\ub2e4. \uc544\uc57c \uc18c\ud53c\uc544\ub294 \uadf8 \uac00\uc6b4\ub370 \ud2b9\ud788 \uc911\uc694\ud55c \uac74\ubb3c\uc774\uc5c8\ub2e4. \uadf8\ub54c \ub3c4\uc2dc\uc758 \uc774\ub984\uc740 \ucf58\uc2a4\ud0c4\ud2f0\ub178\ud3f4\ub9ac\uc2a4\uc600\ub2e4. \uc624\ub298\ub0a0 \uc774\uc2a4\ud0c4\ubd88\uc5d0\uc11c \ub9cc\ub098\ub294 \uba85\uc18c\ub294 \uc624\ub798\uc804\ubd80\ud130 \uc9c0\uae08\uacfc \ub611\uac19\uc740 \uc774\ub984\uacfc \uc5ed\ud560\uc744 \uac00\uc84c\ub358 \uc7a5\uc18c\uac00 \uc544\ub2c8\ub2e4. \uad50\uc7ac\ub294 \uc544\uc57c \uc18c\ud53c\uc544\uac00 \ud669\uc81c\uc758 \uac70\ucc98\uc640 \ud788\ud3ec\ub4dc\ub86c \uac00\uae4c\uc774\uc5d0 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud788\ud3ec\ub4dc\ub86c\uc740 \ub9d0\uacfc \uc804\ucc28 \uacbd\uc8fc\ub97c \ud558\ub294 \uacbd\uae30\uc7a5\uc774\ub2e4. \uc2e0\uc559\uc758 \uacf5\uac04, \ud1b5\uce58\uc758 \uc790\ub9ac, \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc774\ub294 \ud070 \ud589\uc0ac\uac00 \ub3c4\uc2dc \uc911\uc2ec\uc5d0\uc11c \uac00\uae4c\uc774 \ub193\uc5ec \uc788\uc5c8\ub358 \uc148\uc774\ub2e4. \uc774 \ubc30\uce58\ub97c \ub5a0\uc62c\ub9ac\uba74 \uad50\ud68c\ub97c \uadf8\uc800 \uc870\uc6a9\ud788 \uae30\ub3c4\ud558\ub294 \uac74\ubb3c\ub85c\ub9cc \ubcf4\uae30 \uc5b4\ub835\ub2e4. \ud669\uc81c\uc758 \uad8c\uc704\uc640 \uc2dc\ubbfc \uc55e\uc5d0 \ubaa8\uc2b5\uc744 \ub4dc\ub7ec\ub0b4\ub294 \ubc29\uc2dd\uc774 \uc885\uad50 \uacf5\uac04\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uac74\ubb3c \uc548\uc758 \uc7a5\uc2dd\ub9cc \ubcf4\ub294 \ub300\uc2e0 \uc8fc\ubcc0\uc5d0 \ubb34\uc5c7\uc774 \uc788\uc5c8\ub294\uc9c0 \ubb3c\uc5b4\ubcf4\uba74 \ub3c4\uc2dc \uc18d \uc704\uce58\uac00 \uc774\uc57c\uae30\ub97c \ub354\ud574 \uc900\ub2e4. \uc790\ub8cc\uac00 \uc18c\uac1c\ud558\ub294 \uc911\uc2ec \ub3d4\uc758 \uc9c0\ub984\uc740 105\ud53c\ud2b8, \uc57d 32\ubbf8\ud130\ub2e4. \uc22b\uc790\ub97c \uc815\ud655\ud788 \uc0c1\uc0c1\ud558\uae30 \uc5b4\ub835\ub354\ub77c\ub3c4 \uc77c\ubc18\uc801\uc778 \ubc29\uc758 \ucc9c\uc7a5\ubcf4\ub2e4 \ud6e8\uc52c \ub113\uc740 \uacf5\uac04\uc744 \ub36e\ub294 \uaddc\ubaa8\ub77c\ub294 \uac83\uc740 \uc54c \uc218 \uc788\ub2e4. \ub3c4\ud310\uc5d0\uc11c\ub3c4 \uc911\uc559\uc758 \ub192\uc740 \uace1\uba74 \uc544\ub798\ub85c \ub354 \ub0ae\uc740 \uc9c0\ubd95\ub4e4\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ub208\uc740 \uadf8 \uc5ec\ub7ec \uce35\uc744 \ub530\ub77c \uc704\ub85c \uc62c\ub77c\uac14\ub2e4\uac00 \uc8fc\ubcc0\uc73c\ub85c \ub0b4\ub824\uc628\ub2e4. \ub192\uc740 \ud558\ub098\uc758 \ubfb0\uc871\ud55c \uaf2d\ub300\uae30\ub9cc \ubcf4\ub294 \uac83\uacfc\ub294 \ub2e4\ub978 \uac10\uc0c1\uc774\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc815\ubc00\ud55c \uad6c\uc870 \uacc4\uc0b0\ubcf4\ub2e4, \ud070 \uace1\uba74\uacfc \uc8fc\ubcc0 \ubd80\ubd84\uc774 \uc804\uccb4\uc758 \ubb34\uac8c\uac10\uc744 \uc5b4\ub5bb\uac8c \ub098\ub204\ub294\uc9c0 \ubcf4\uc544\ub3c4 \ucda9\ubd84\ud558\ub2e4. \uac74\ucd95\uc758 \uc7ac\ubbf8\ub294 \uc774\ub984\uacfc \uc5f0\ub3c4\ub97c \uc678\uc6b0\uae30 \uc804\uc5d0 \uc2dc\uc791\ub420 \uc218 \uc788\ub2e4. 1453\ub144 \uc624\uc2a4\ub9cc \uc81c\uad6d\uc774 \ucf58\uc2a4\ud0c4\ud2f0\ub178\ud3f4\ub9ac\uc2a4\ub97c \uc815\ubcf5\ud588\ub2e4. \uba54\ud750\uba54\ud2b8 2\uc138\ub294 \uc774\uacf3\uc744 \uc0c8 \uc218\ub3c4\ub85c \uc0bc\uace0 \ub3c4\uc2dc\ub97c \uc7ac\uac74\ud588\ub2e4. \uad81\uc804\uacfc \ubcd1\uc6d0, \uad50\uc721 \uacf5\uac04\uc744 \ub9c8\ub828\ud558\uba70 \uc0c8\ub85c\uc6b4 \uc81c\uad6d\uc758 \uc911\uc2ec\uc73c\ub85c \ub9cc\ub4e4\uc5b4 \uac14\ub2e4. \uc544\uc57c \uc18c\ud53c\uc544\ub3c4 \uadf8 \ubcc0\ud654 \uc548\uc5d0 \uc788\uc5c8\ub2e4. \uad50\uc7ac\ub294 \uba54\ud750\uba54\ud2b8\uac00 \uae30\uc874 \uac74\ubb3c\uc744 \ubcf4\uc874\ud558\uba74\uc11c \ubaa8\uc2a4\ud06c\ub85c \uc804\ud658\ud558\ub3c4\ub85d \ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc911\uc694\ud55c \uac74\ubb3c\uc758 \uc5ed\uc0ac\ub294 \ucca0\uac70\uc640 \uc2e0\ucd95\uc73c\ub85c\ub9cc \uc774\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \ub0a8\uaca8 \ub454 \uad6c\uc870\uc5d0 \ub2e4\ub978 \uc0ac\uc6a9\uacfc \uc0c1\uc9d5\uc774 \ub354\ud574\uc9c0\ub294 \ubc29\uc2dd\ub3c4 \uc788\ub2e4. \ubaa8\uc2a4\ud06c\uc758 \ucca8\ud0d1\uc740 \ube44\uc794\ud2f4 \uad50\ud68c\ub85c \uc138\uc6cc\uc84c\ub358 \ub54c\uc758 \ubaa8\uc2b5\uacfc \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \ub3c4\ud310 \uc18d\uc5d0\uc11c \ud568\uaed8 \ubcf4\uc778\ub2e4\uace0 \ubaa8\ub450 \uac19\uc740 \uc2dc\uae30\uc5d0 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uac74\ubb3c\uc5d0 \uc313\uc778 \uc2dc\uac04\uc740 \ud558\ub098\uc758 \uc644\uc131\ub41c \uc724\uacfd \uc548\uc5d0 \uc11e\uc5ec \ubcf4\uc77c \uc218 \uc788\ub2e4. \uc0ac\uc9c4\uc774\ub098 \uadf8\ub9bc\uc5d0\uc11c \uc774\ub7f0 \ubd80\ubd84\uc744 \ucc3e\uc544\ubcf4\ub294 \uc77c\uc740 \ubcf5\uc7a1\ud55c \uc591\uc2dd \uc2dc\ud5d8\uc774 \uc544\ub2c8\ub2e4. \uc5b4\ub290 \ubd80\ubd84\uc774 \uc624\ub798\ub41c \uc911\uc2ec\uc774\uace0 \uc5b4\ub5a4 \uc694\uc18c\uac00 \ub098\uc911\uc758 \uc4f0\uc784\uc744 \ubcf4\uc5ec \uc8fc\ub294\uc9c0 \uc9c8\ubb38\ud558\ub294 \uac83\uc774\ub2e4. \uc804\ubd80\uc758 \uc815\ud655\ud55c \uac74\ub9bd \uc5f0\ub300\ub97c \ubaa8\ub974\ub294 \uc0c1\ud0dc\uc5d0\uc11c\ub3c4, \ud55c \uc2dc\ub300\uc758 \uc124\uacc4\ub3c4\ub85c\ub9cc \uc124\uba85\ud558\uae30 \uc5b4\ub835\ub2e4\ub294 \uc810\uc740 \ucda9\ubd84\ud788 \uc77d\uc744 \uc218 \uc788\ub2e4. \ud070 \uac74\ubb3c\uc774 \ub0a8\uc544 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub3cc\uacfc \ubcbd\ub3cc\uc774 \ub2e8\ub2e8\ud588\ub2e4\ub294 \uc124\uba85\ub9cc\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc0c8\ub85c\uc6b4 \uc9c0\ubc30\uc790\uac00 \uadf8 \uacf5\uac04\uc744 \uc5b4\ub5bb\uac8c \ub2e4\ub8f0\uc9c0 \uacb0\uc815\ud588\uace0, \ub2e4\ub978 \ubaa9\uc801\uc5d0 \ub9de\ucd94\uc5b4 \uc0ac\uc6a9\ud588\ub2e4. \ubb3c\ub9ac\uc801\uc778 \uad6c\uc870\uc640 \uc815\uce58\uc801 \uc120\ud0dd\uc774 \ud568\uaed8 \uac74\ubb3c\uc758 \uc0dd\uc560\ub97c \ub9cc\ub4e4\uc5c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc804\ud658 \uacfc\uc815\uc5d0\uc11c \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uac19\uc740 \uac10\uc815\uc744 \ub290\uaf08\uc73c\ub9ac\ub77c\uace0 \uc0dd\uac01\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub204\uad70\uac00\uc5d0\uac8c \uad8c\uc704\uc758 \uacc4\uc2b9\uc774\uc5c8\ub358 \ubcc0\ud654\ub294 \ub2e4\ub978 \ub204\uad70\uac00\uc5d0\uac8c \uc0c1\uc2e4\uc774\uc5c8\uc744 \uc218 \uc788\ub2e4. \ud55c \uac74\ubb3c\uc5d0 \uc5ec\ub7ec \uacf5\ub3d9\uccb4\uc758 \uae30\uc5b5\uc774 \ubd99\uc5b4 \uc788\ub2e4\ub294 \uc810\uc744 \uc778\uc815\ud558\uba74, \uc544\ub984\ub2f5\ub2e4\ub294 \uac10\uc0c1 \uc606\uc5d0 \uc5ed\uc0ac\uc758 \ubcf5\uc7a1\ud568\ub3c4 \ub193\uc744 \uc790\ub9ac\uac00 \uc0dd\uae34\ub2e4. 1857\ub144 \ub3c4\ud310\uc758 \uc544\ub798\ucabd\uc5d0\ub294 \uae38\uc744 \uac77\uac70\ub098 \uc11c \uc788\ub294 \uc791\uc740 \uc0ac\ub78c\ub4e4\uc774 \ubcf4\uc778\ub2e4. \uac74\ubb3c\uc5d0 \ube44\ud574 \ubab8\uc9d1\uc774 \uc791\uc544\uc11c \uc8fc\ubcc0 \uacf5\uac04\uc758 \uaddc\ubaa8\ub97c \ub290\ub07c\uac8c \ud55c\ub2e4. \uc2dc\uc120\uc744 \uc704\ub85c\ub9cc \ubcf4\ub0b4\ub2e4\uac00 \uc544\ub798\ub85c \ub0b4\ub9ac\uba74 \uac70\ub300\ud55c \uc720\uc801\ub3c4 \uc0ac\ub78c\ub4e4\uc774 \uc9c0\ub098\uac00\ub294 \ub3c4\uc2dc \uc548\uc5d0 \uc788\uc5c8\uc74c\uc744 \uc54c\uac8c \ub41c\ub2e4. \uc774 \uadf8\ub9bc\uc740 6\uc138\uae30\uc758 \ud604\uc7a5 \uc0ac\uc9c4\ub3c4 \ud604\uc7ac\uc758 \ubc29\ubb38 \uc548\ub0b4\ub3c4 \uc544\ub2c8\ub2e4. \ud2b9\uc815 \uc2dc\ub300\uc5d0 \ud45c\ud604\ud55c \uc678\uad00\uc774\ub2e4. \ub530\ub77c\uc11c \uc785\uc7a5 \ub3d9\uc120\uc774\ub098 \uc624\ub298\uc758 \ub0b4\ubd80 \uc6b4\uc601\uc744 \uc774 \ub3c4\ud310\uc5d0\uc11c \uc54c\uc544\ub0b4\ub824 \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub300\uc2e0 \uadf8\ub9bc\uc774 \ubcf4\uc5ec \uc8fc\ub294 \uc5ec\ub7ec \uc9c0\ubd95\uacfc \ucca8\ud0d1, \uc0ac\ub78c\uc758 \ube44\uc728\uc744 \uc77d\ub294 \uc790\ub8cc\ub85c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4. \uc544\uc57c \uc18c\ud53c\uc544\ub97c \ub2e4\uc2dc \ub5a0\uc62c\ub9b4 \ub54c\ub294 \ub3d4 \ud558\ub098\ub9cc \uae30\uc5b5\ud574\ub3c4 \uc88b\ub2e4. \uac70\uae30\uc5d0 \ub3c4\uc2dc \uc911\uc2ec\uc758 \uad81\uc804\uacfc \uacbd\uae30\uc7a5, \ub2e4\ub978 \ud1b5\uce58\uc790\uac00 \ub4e4\uc5b4\uc628 \ub4a4\uc758 \uc5ed\ud560\uc744 \uc870\uae08\uc529 \ub367\ubd99\uc774\uba74 \uac74\ubb3c\uc774 \ud6e8\uc52c \uc785\uccb4\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4. \uc2dc\ub300\ub294 \uac74\ubb3c \uacc1\uc744 \uc9c0\ub098\uac00\uae30\ub9cc \ud55c \uac83\uc774 \uc544\ub2c8\ub77c \uadf8 \uc4f0\uc784\uc744 \ubc14\uafb8\uc5c8\ub2e4. \uc624\ub798\ub41c \uac74\ucd95\ubb3c\uc744 \ubcf4\ub294 \uc990\uac70\uc6c0\uc740 \ucd5c\ucd08\uc758 \ubaa8\uc2b5\ub9cc \ucc3e\uc544\ub0b4\ub294 \ub370 \uc788\uc9c0 \uc54a\ub2e4. \ubb34\uc5c7\uc774 \ub0a8\uace0 \ubb34\uc5c7\uc774 \ub354\ud574\uc84c\ub294\uc9c0 \uc0b4\ud53c\ub294 \ub370\ub3c4 \uc788\ub2e4. \ud070 \uc9c0\ubd95 \uc544\ub798 \uba38\ubb3c\ub800\ub358 \uc5ec\ub7ec \uc2dc\ub300\ub97c \uc0dd\uac01\ud558\uba74, \uc775\uc219\ud55c \uba85\uc18c\uc758 \uc724\uacfd\uc774 \ud55c \uc7a5\uc758 \uadf8\ub9bc\ubcf4\ub2e4 \uae34 \uc774\uc57c\uae30\ub85c \ub2e4\uac00\uc628\ub2e4."}, {"id": "japan-1871-domains-prefectures-and-central-power", "title": "\ud3d0\ubc88\uce58\ud604 \u2014 \uc601\uc8fc\uc758 \ub545\uc740 \uc5b4\ub5bb\uac8c \uc911\uc559\uc815\ubd80\uc758 \uc9c0\ub3c4\uac00 \ub418\uc5c8\uc744\uae4c", "summary": "1869\ub144\uc758 \ubc18\ud658\uc5d0\uc11c1871\ub144\uc758 \ud604 \uc124\uce58, \uc9c0\ubc29 \uad8c\ub825\uacfc \uc7ac\uc815\uc758 \uc7ac\ud3b8\uc758 \ubc30\uacbd\uacfc \uc804\uac1c, \uc774\ud6c4\uc758 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/japan-1871-domains-prefectures-and-central-power/index.html", "image": "../media/japan-1871-domains-prefectures-and-central-power.jpg", "alt": "\uc0b0\uc870 \uc0ac\ub124\ud1a0\ubbf8\uc640 \uac00\uc4f0 \uac00\uc774\uc288\uc758 \uc778\ubb3c \ubaa8\uc2b5\uc744 \uc2e4\uc740 \uc5ed\uc0ac \ucd9c\ud310 \ub3c4\ud310", "text": "\ud3d0\ubc88\uce58\ud604 \u2014 \uc601\uc8fc\uc758 \ub545\uc740 \uc5b4\ub5bb\uac8c \uc911\uc559\uc815\ubd80\uc758 \uc9c0\ub3c4\uac00 \ub418\uc5c8\uc744\uae4c 1869\ub144\uc758 \ubc18\ud658\uc5d0\uc11c1871\ub144\uc758 \ud604 \uc124\uce58, \uc9c0\ubc29 \uad8c\ub825\uacfc \uc7ac\uc815\uc758 \uc7ac\ud3b8 1869\ub144\uc758 \ubc18\ud658\uc5d0\uc11c1871\ub144\uc758 \ud604 \uc124\uce58, \uc9c0\ubc29 \uad8c\ub825\uacfc \uc7ac\uc815\uc758 \uc7ac\ud3b8\uc758 \ubc30\uacbd\uacfc \uc804\uac1c, \uc774\ud6c4\uc758 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc9c0\ub3c4\uc5d0 \uac19\uc740 \uc0c9\uc744 \uce60\ud55c\ub2e4\uace0 \uadf8 \uc548\uc758 \uc138\uae08\uacfc \uad70\ub300\uac00 \uc800\uc808\ub85c \ud558\ub098\uac00 \ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \uba54\uc774\uc9c0 \ucd08\uae30 \uc77c\ubcf8 \uc815\ubd80\uac00 \ub9c8\uc8fc\ud55c \ubb38\uc81c\ub3c4 \uadf8\ub7ac\ub2e4. \ub9c9\ubd80\ub97c \ubb34\ub108\ub728\ub838\uc9c0\ub9cc \uc9c0\uc5ed\uc5d0\ub294 \uc5ec\uc804\ud788 \ubc88\uc758 \uc7ac\uc815\uacfc \uc778\ub9e5, \ubb34\ub825\uc774 \ub0a8\uc544 \uc788\uc5c8\ub2e4. 1871\ub144 \ubc88\uc744 \uc5c6\uc560\uace0 \ud604\uc744 \uc124\uce58\ud55c \ud3d0\ubc88\uce58\ud604\uc740 \ud589\uc815\uad6c\uc5ed\uc758 \uc774\ub984\uc744 \uace0\uce5c \uc0ac\uac74\uc778 \ub3d9\uc2dc\uc5d0, \ub204\uac00 \uc9c0\ubc29\uc744 \ub2e4\uc2a4\ub9ac\uace0 \ub3c8\uc744 \uac70\ub458 \uac83\uc778\uc9c0 \ub2e4\uc2dc \uc815\ud55c \uad8c\ub825\uc758 \uc7ac\ud3b8\uc774\uc5c8\ub2e4. \uc5d0\ub3c4 \uc2dc\ub300\uc758 \ubc88\uc740 \uac01 \uc601\uc8fc\uac00 \uc9c0\ubc30\ud558\ub358 \uc601\uc5ed\uc744 \uac00\ub9ac\ud0a8\ub2e4. \uc601\uc8fc\ub294 \ub9c9\ubd80\uc758 \uc9c8\uc11c \uc548\uc5d0 \uc788\uc5c8\uc9c0\ub9cc \uc790\uc2e0\uc758 \uac00\uc2e0\uacfc \uc218\uc785, \uc9c0\uc5ed \uc6b4\uc601 \uc870\uc9c1\uc744 \uac70\ub290\ub838\ub2e4. \ub18d\ubbfc\uc5d0\uac8c \ud574\ub9c8\ub2e4 \uc138\uae08\uc744 \uc694\uad6c\ud558\ub294 \uac00\uae4c\uc6b4 \uad8c\ub825\uc740 \uba40\ub9ac \uc788\ub294 \uc1fc\uad70\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4. 1868\ub144 \uc0c8 \uc815\ubd80\uac00 \ub4f1\uc7a5\ud55c \ub4a4\uc5d0\ub3c4 \uc774\ub7f0 \uc870\uc9c1\uc774 \ud55c\uaebc\ubc88\uc5d0 \uc0ac\ub77c\uc9c0\uc9c0\ub294 \uc54a\uc558\ub2e4. \ud2b9\ud788 \uc815\uad8c \uad50\uccb4\uc5d0 \uae30\uc5ec\ud55c \uc720\ub825 \ubc88\uc740 \uc0c8 \uc815\ubd80\ub97c \ub5a0\ubc1b\uce58\ub294 \uae30\ubc18\uc774\uba74\uc11c \ub3c5\uc790\uc801\uc778 \ud798\uc744 \uac00\uc9c4 \uc874\uc7ac\uc600\ub2e4. \uc911\uc559\uc740 \uadf8\ub4e4\uc758 \ud611\ub825\uc744 \ud544\uc694\ub85c \ud588\uace0, \ub3d9\uc2dc\uc5d0 \uadf8 \ud798\uc744 \uc911\uc559\uc758 \uc870\uc9c1\uc73c\ub85c \uc62e\uaca8\uc57c \ud588\ub2e4. 1869\ub144\uc5d0\ub294 \uc601\uc8fc\ub4e4\uc774 \ud1a0\uc9c0\uc640 \uc8fc\ubbfc\uc5d0 \ub300\ud55c \uc9c0\ubc30\uad8c\uc744 \ucc9c\ud669\uc5d0\uac8c \ub3cc\ub824\uc900\ub2e4\ub294 \ud615\uc2dd\uc758 \uc870\uce58\uac00 \uc774\ub8e8\uc5b4\uc84c\ub2e4. \uc774\ub97c \ud310\uc801\ubd09\ud658\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \uadf8\ub7ec\ub098 \uae30\uc874 \uc601\uc8fc\uac00 \ud574\ub2f9 \ubc88\uc758 \uc7a5\uad00\uc73c\ub85c \uc784\uba85\ub418\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc544 \uc9c0\uc5ed\uc758 \uc778\uc801 \uc5f0\uacb0\uae4c\uc9c0 \uace7\ubc14\ub85c \ub04a\uae34 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc5ec\uae30\uc5d0\ub294 \uc911\uc694\ud55c \ucc28\uc774\uac00 \uc788\ub2e4. \uad8c\ub825\uc774 \ub204\uad6c\uc5d0\uac8c\uc11c \ub098\uc628\ub2e4\uace0 \uc120\uc5b8\ud558\ub294 \uc77c\uacfc \uc2e4\uc81c\ub85c \uc138\uae08 \uc7a5\ubd80\ub97c \uad00\ub9ac\ud558\uace0 \uba85\ub839\uc744 \uc9d1\ud589\ud558\ub294 \uc0ac\ub78c\uc744 \ubc14\uafb8\ub294 \uc77c\uc740 \uc11c\ub85c \ub2e4\ub974\ub2e4. \uccab \uc870\uce58\ub294 \uc911\uc559\uc758 \uc6d0\uce59\uc744 \uc138\uc6e0\uc9c0\ub9cc, \uc9c0\ubc29\uc758 \uc6b4\uc601 \ubc29\uc2dd\uc740 \ub354 \ubc14\ub00c\uc5b4\uc57c \ud588\ub2e4. \uc601\uc8fc\ub97c \uac19\uc740 \uc9c0\uc5ed\uc758 \ucc45\uc784\uc790\ub85c \ub0a8\uaca8 \ub450\ub294 \ubc29\uc2dd\uc740 \ubcc0\ud654\ub97c \uc218\uc6a9\ud558\uac8c \ud558\ub294 \ud0c0\ud611\uc77c \uc218 \uc788\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \uc61b \uac00\uc2e0\uacfc \uc7ac\uc815\uc758 \uc5f0\uacb0\uc774 \uc720\uc9c0\ub418\uba74 \uc911\uc559\uc758 \uba85\ub839\uc740 \uc5ec\uc804\ud788 \uae30\uc874 \uc778\ub9e5\uc744 \uac70\uccd0\uc57c \ud588\ub2e4. \uba85\ubaa9\uc0c1\uc758 \uc8fc\uad8c\uacfc \uc77c\uc0c1\uc758 \ud589\uc815 \uad8c\ud55c \uc0ac\uc774\uc5d0 \uc0dd\uae34 \uc774 \ud2c8\uc774 \ub2e4\uc74c \uc870\uce58\uc758 \ubc30\uacbd\uc774\uc5c8\ub2e4. \ud3d0\ubc88\uce58\ud604\uc740 \uadf8 \uac04\uaca9\uc744 \uc904\uc774\ub294 \uc870\uce58\uc600\ub2e4. \ubc88\uc744 \ud3d0\uc9c0\ud558\uace0 \ud604\uc744 \ub450\uba70, \uae30\uc874 \uc601\uc8fc \ub300\uc2e0 \uc911\uc559\uc774 \uc9c0\ubc29 \ucc45\uc784\uc790\ub97c \uc784\uba85\ud558\ub294 \uccb4\uc81c\ub85c \ub098\uc544\uac14\ub2e4. \uc61b \uc601\uc8fc\ub4e4\uc774 \ub3c4\ucfc4\ub85c \uc62e\uaca8 \uc0b4\uac8c \ub41c \uac83\ub3c4 \uc9c0\uc5ed \uad8c\ub825\uacfc\uc758 \uac70\ub9ac\ub97c \ubc8c\ub9ac\ub294 \uc758\ubbf8\uac00 \uc788\uc5c8\ub2e4. \uc815\uad8c\uc758 \uc8fc\uc694 \uc778\ubb3c\ub4e4\uc774 \uc774 \uc120\ud0dd\uc744 \ucd94\uc9c4\ud560 \uc218 \uc788\uc5c8\ub358 \ubc30\uacbd\uc5d0\ub294 \uad70\uc0ac\uc801 \uae30\ubc18\uc758 \uc815\ube44\uac00 \uc788\uc5c8\ub2e4. \uc9c0\ubc29\uc5d0\uc11c \ubc18\ub300\uac00 \ub098\uc654\uc744 \ub54c \uba85\ub839\ub9cc\uc73c\ub85c \ud574\uacb0\ud560 \uc218 \uc5c6\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4. \ud589\uc815 \uac1c\ud601\uc758 \ubb38\uc7a5\uc740 \uc9e7\uc544\ub3c4 \uadf8 \ubb38\uc7a5\uc744 \ud604\uc2e4\ub85c \ub9cc\ub4dc\ub294 \ub370\uc5d0\ub294 \uc815\uce58\uc801 \ud569\uc758\uc640 \ubb34\ub825\uc758 \ub4b7\ubc1b\uce68\uc774 \ud544\uc694\ud588\ub2e4. \ubc88\ub9c8\ub2e4 \ub530\ub85c \uad00\ub9ac\ud558\ub358 \uc218\uc785\uacfc \uc9c0\ucd9c\uc744 \uc911\uc559\uc758 \uad6d\uac00 \uc7ac\uc815\uc73c\ub85c \ubb36\ub294 \uc77c\uc740 \uc27d\uc9c0 \uc54a\uc558\ub2e4. \uae30\uc874 \ucc44\ubb34\uc640 \uac00\uc2e0\uc758 \uc0dd\uacc4, \uc9c0\uc5ed \uad00\ub9ac \uc870\uc9c1\uc744 \uc5b4\ub5bb\uac8c \ucc98\ub9ac\ud560\uc9c0 \ubb38\uc81c\uac00 \ub4a4\ub530\ub790\ub2e4. \ubc88\uc758 \uc774\ub984\uc774 \uc5c6\uc5b4\uc84c\ub2e4\uace0 \uadf8 \ubc88\uc774 \uc9c4 \uc758\ubb34\uae4c\uc9c0 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc911\uc559\uc815\ubd80\uc5d0\ub294 \uc804\uad6d\uc758 \uc790\uc6d0\uc744 \ud30c\uc545\ud558\uace0 \ud559\uad50\uc640 \uad70\ub300, \ud1b5\uc2e0\ub9dd \ub4f1\uc744 \uc6b4\uc601\ud560 \uae30\ubc18\uc774 \ud544\uc694\ud588\ub2e4. \ub2e4\ub9cc \ub4a4\uc774\uc5b4 \uc9c4\ud589\ub41c \uc138\uc81c \uac1c\ud601\uc774\ub098 \uad70\uc81c \uac1c\ud3b8\uc744 \ubaa8\ub450 \ud3d0\ubc88\uce58\ud604\uc774\ub77c\ub294 \ud558\ub098\uc758 \uba85\ub839 \uc548\uc5d0 \ub123\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc11c\ub85c \uc774\uc5b4\uc84c\uc9c0\ub9cc \uc2dc\uae30\uc640 \ub0b4\uc6a9\uc774 \ub2e4\ub978 \uc5ec\ub7ec \uc815\ucc45\uc774\uc5c8\ub2e4. 1871\ub144 \ucc98\uc74c \uc815\ube44\ud55c \uad6c\uc5ed\uc774 \uc624\ub298\ub0a0 \uc77c\ubcf8\uc758 \ub3c4\ub3c4\ubd80\ud604\uacfc \uadf8\ub300\ub85c \uc77c\uce58\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc791\uc740 \ud589\uc815 \ub2e8\uc704\ub4e4\uc744 \ud569\uce58\uace0 \uacbd\uacc4\ub97c \uc870\uc815\ud558\ub294 \uacfc\uc815\uc774 \uc774\uc5b4\uc84c\ub2e4. \ud604\uc774\ub77c\ub294 \uc81c\ub3c4\uc758 \ub3c4\uc785\uacfc \ud604\uc7ac \uc9c0\ub3c4\uc758 \uc644\uc131\uc740 \uad6c\ubd84\ud574\uc11c \ubcf4\uc544\uc57c \ud55c\ub2e4. \uacbd\uacc4\ub294 \uc8fc\ubbfc\uc5d0\uac8c\ub3c4 \ucd94\uc0c1\uc801\uc778 \uc120\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc5b4\ub290 \uad00\uccad\uc5d0 \ubb38\uc11c\ub97c \ub0b4\uace0, \uc5b4\ub5a4 \uae38\uc744 \uc774\uc6a9\ud574 \uc5c5\ubb34\ub97c \ubcf4\uba70, \uc5b4\ub290 \uc9c0\uc5ed\uacfc \uac19\uc740 \ud589\uc815 \ub2e8\uc704\uac00 \ub418\ub294\uc9c0\ub97c \uacb0\uc815\ud588\ub2e4. \uc911\uc559\uc758 \uc9c0\ub3c4\ub294 \uc9c0\uc5ed \uc0dd\ud65c\uc5d0 \uc0c8\ub85c\uc6b4 \uc911\uc2ec\uacfc \uc774\ub3d9 \uacbd\ub85c\ub97c \ub9cc\ub4e4\uc5b4 \ub0c8\ub2e4. \ud589\uc815 \ub2e8\uc704\uc758 \ud06c\uae30\ub97c \ubc14\uafb8\uba74 \uad00\ub9ac\uc758 \uc218\uc640 \uad00\uccad\uc758 \uc704\uce58, \ubb38\uc11c\uac00 \uc774\ub3d9\ud558\ub294 \uc2dc\uac04\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc9c0\uc5ed \uc774\ub984\uc744 \uc554\uae30\ud558\ub294 \uac83\ub9cc\uc73c\ub85c\ub294 \ubcf4\uc774\uc9c0 \uc54a\ub294 \ubcc0\ud654\ub2e4. \ud604\uc758 \uc124\uce58\uc640 \ud1b5\ud569\uc744 \uc8fc\ubbfc\uc774 \uc0c8\ub85c\uc6b4 \uad6d\uac00\ub97c \ub9cc\ub098\ub294 \ucc3d\uad6c\uac00 \ubc14\ub010 \uc0ac\uac74\uc73c\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \ubc88\uc758 \uac00\uc2e0\uc774\ub358 \ubb34\uc0ac\ub4e4\uc5d0\uac8c \ubcc0\ud654\ub294 \uc18c\uc18d\uacfc \uc218\uc785\uc758 \ubb38\uc81c\uc600\ub2e4. \uad6d\uac00\uac00 \uc0c8 \uc870\uc9c1\uc744 \ub9cc\ub4e0\ub2e4\uace0 \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uc0c8\ub85c\uc6b4 \uc9c1\uc5c5\uc744 \uc5bb\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc2e0\ubd84\uacfc \uc0dd\uacc4\uc5d0 \uad00\ud55c \uac1c\ud601\uc774 \uc774\uc5b4\uc9c0\uba74\uc11c \ubd88\ub9cc\ub3c4 \uc313\uc600\uace0, \uc77c\ubd80\ub294 \ub4a4\uc758 \ubb34\ub825 \ucda9\ub3cc\ub85c \ub098\ud0c0\ub0ac\ub2e4. \uadf8\ub7ec\ub098 \ubaa8\ub4e0 \ubb34\uc0ac\uac00 \uac19\uc740 \uc120\ud0dd\uc744 \ud588\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uad00\ub8cc\uc640 \uad70\uc778\uc73c\ub85c \uc790\ub9ac\ub97c \uc62e\uae30\ub294 \uc0ac\ub78c\ub3c4 \uc788\uc5c8\uace0 \ub2e4\ub978 \uc0dd\uc5c5\uc744 \ucc3e\uc544\uc57c \ud558\ub294 \uc0ac\ub78c\ub3c4 \uc788\uc5c8\ub2e4. 1877\ub144 \uc0ac\uc4f0\ub9c8 \ubc18\ub780 \uac19\uc740 \uc0ac\uac74\ub3c4 \ud3d0\ubc88\uce58\ud604 \ud558\ub098\ub9cc\uc758 \uc9c1\uc811\uc801 \uacb0\uacfc\ub85c \ub2e8\uc21c\ud558\uac8c \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc815\ubd80 \uc548\uc5d0\uc11c \uc77c\ud558\uac8c \ub41c \uc0ac\ub78c\uc5d0\uac8c\ub3c4 \uacfc\uac70\uc758 \uc778\uc5f0\uc774 \uc644\uc804\ud788 \uc5c6\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc9c0\uc5ed \ucd9c\uc2e0\uacfc \uc815\uce58\uc801 \uad00\uacc4\ub294 \uc0c8 \uc870\uc9c1 \uc548\uc5d0\uc11c\ub3c4 \uc791\uc6a9\ud560 \uc218 \uc788\uc5c8\ub2e4. \uc81c\ub3c4\ub97c \uc911\uc559\uc5d0 \ubb36\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ubaa8\ub4e0 \uc778\uc801 \uad00\uacc4\uac00 \uade0\uc77c\ud574\uc84c\ub2e4\ub294 \uc8fc\uc7a5\uc740 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ud3d0\ubc88\uce58\ud604\uc740 \uc77c\ubcf8\uc758 \ubcc0\ud654\uac00 \uc11c\uc591 \uae30\uacc4\ub97c \uc0ac\ub4e4\uc774\ub294 \uc77c\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\uc558\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub204\uac00 \uc784\uba85\ud558\uace0, \ub204\uac00 \ub3c8\uc744 \ubaa8\uc73c\uba70, \uc5b4\ub290 \uc870\uc9c1\uc774 \uc8fc\ubbfc\uacfc \ub9cc\ub098\ub294\uc9c0\ub97c \ubc14\uafb8\ub294 \uc77c\ub3c4 \uc0c8\ub85c\uc6b4 \uad6d\uac00\ub97c \ub9cc\ub4dc\ub294 \ud575\uc2ec\uc774\uc5c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc5ed\uc0ac \ucd9c\ud310\ubb3c\uc758 \uc778\ubb3c \ub3c4\ud310\uc740 \uc0b0\uc870 \uc0ac\ub124\ud1a0\ubbf8\uc640 \uac00\uc4f0 \uac00\uc774\uc288\ub97c \ubcf4\uc5ec \uc900\ub2e4. \uc0c8 \uc815\ubd80\uc640 \uc61b \ub9c9\ubd80\ub77c\ub294 \uc11c\ub85c \ub2e4\ub978 \uc815\uce58\uc801 \ubc30\uacbd\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\uc9c0\ub9cc \ud3d0\ubc88\uce58\ud604\uc744 \uacb0\uc815\ud55c \ud68c\uc758\uc758 \uae30\ub85d \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \uc778\ubb3c\uc758 \ubaa8\uc2b5\uacfc \uc81c\ub3c4\uac00 \uc2e4\uc81c\ub85c \uc6c0\uc9c1\uc778 \uacfc\uc815\uc744 \uad6c\ubd84\ud558\uba70 \uc77d\uc744 \ud544\uc694\uac00 \uc788\ub2e4."}, {"id": "kyoto-genji-court-and-snow", "title": "\uad50\ud1a0 \u2014 \uad81\uc815\uc758 \ud558\ub8e8\ub294 \uc18c\uc124 \uc18d\uc5d0 \ub0a8\uc558\ub2e4", "summary": "\u300e\uac90\uc9c0 \uc774\uc57c\uae30\u300f\uc758 \ud6c4\ub300 \uadf8\ub9bc\uc744 \ubcf4\uba70 \ud5e4\uc774\uc548\ucfc4\uc758 \uad81\uc815 \ubb38\ud654\uc640 \uae00\uc4f0\uae30, \uae30\ub85d\uc758 \ubc94\uc704\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/kyoto-genji-court-and-snow/index.html", "image": "../media/kyoto-genji-court-and-snow.jpg", "alt": "17\uc138\uae30 \uac90\uc9c0 \uc774\uc57c\uae30 \ud654\ucca9\uc758 \uc7a5\uba74. \ud207\ub9c8\ub8e8 \ucabd \uc778\ubb3c\ub4e4\uacfc \ub208 \uc18d\uc758 \uc5b4\ub9b0 \uc2dc\ub140\ub4e4.", "text": "\uad50\ud1a0 \u2014 \uad81\uc815\uc758 \ud558\ub8e8\ub294 \uc18c\uc124 \uc18d\uc5d0 \ub0a8\uc558\ub2e4 \ub208\ub180\uc774 \uadf8\ub9bc\uc5d0\uc11c \ub9cc\ub098\ub294 \ud5e4\uc774\uc548 \uc2dc\ub300\uc758 \uc0dd\ud65c \u300e\uac90\uc9c0 \uc774\uc57c\uae30\u300f\uc758 \ud6c4\ub300 \uadf8\ub9bc\uc744 \ubcf4\uba70 \ud5e4\uc774\uc548\ucfc4\uc758 \uad81\uc815 \ubb38\ud654\uc640 \uae00\uc4f0\uae30, \uae30\ub85d\uc758 \ubc94\uc704\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uad50\ud1a0\ub97c \ub5a0\uc62c\ub9ac\uba74 \uc808\uacfc \uc815\uc6d0\ubd80\ud130 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \uadf8\ub7f0\ub370 \uc774 \ub3c4\uc2dc\uc758 \uc61b \uc0dd\ud65c\ub85c \ub4e4\uc5b4\uac00\ub294 \ub610 \ud558\ub098\uc758 \ubb38\uc740 \uc18c\uc124\uc774\ub2e4. \uad81\uc815\uc5d0\uc11c \ubb34\uc5c7\uc744 \uc785\uace0 \uc5b4\ub5a4 \uc545\uae30\ub97c \uc990\uacbc\uc73c\uba70 \uc0ac\ub78c\ub4e4 \uc0ac\uc774\uc5d0 \uc5b4\ub5a4 \uae30\ub300\uac00 \uc788\uc5c8\ub294\uc9c0\uac00 \uc774\uc57c\uae30 \uc18d\uc5d0 \ub0a8\uc544 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc5d0\uc11c\ub294 \uac74\ubb3c \uc548\ucabd\uc5d0\uc11c \ubc14\uae65\uc758 \ub208\ub180\uc774\ub97c \ubc14\ub77c\ubcf4\ub294 \uc0ac\ub78c\ub4e4\uc744 \ubcfc \uc218 \uc788\ub2e4. \u300e\uac90\uc9c0 \uc774\uc57c\uae30\u300f\uc758 \ud55c \uc7a5\uba74\uc744 \uadf8\ub9b0 17\uc138\uae30 \ud654\ucca9\uc774\ub2e4. \uc18c\uc124\uc758 \ubc30\uacbd\uacfc \uadf8\ub9bc\uc758 \uc81c\uc791 \uc2dc\uae30\ub294 \ub2e4\ub974\uc9c0\ub9cc, \ud6c4\ub300 \uc0ac\ub78c\ub4e4\uc774 \uc624\ub798\ub41c \uad81\uc815\uc758 \ud558\ub8e8\ub97c \uc5b4\ub5bb\uac8c \uc0c1\uc0c1\ud588\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uac8c \ud55c\ub2e4. 794\ub144 \uac04\ubb34 \ucc9c\ud669\uc740 \uc218\ub3c4\ub97c \ub098\ub77c\uc5d0\uc11c \ubd81\ucabd\uc758 \ud5e4\uc774\uc548\ucfc4\ub85c \uc62e\uacbc\ub2e4. \uc624\ub298\ub0a0 \uad50\ud1a0\uac00 \uc788\ub294 \uacf3\uc774\ub2e4. \uad50\uc7ac\ub294 \uc774\ud6c4 \uc624\ub7ab\ub3d9\uc548 \uc774\uacf3\uc774 \uc77c\ubcf8\uc758 \uc218\ub3c4\ub85c \uae30\ub2a5\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc9c0\uae08 \ub208\uc55e\uc5d0 \ub0a8\uc740 \ubaa8\ub4e0 \uac74\ubb3c\uc774 \uadf8\ub54c\ubd80\ud130 \uadf8\ub300\ub85c \uc788\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc218\ub3c4\uac00 \ub41c\ub2e4\ub294 \uac83\uc740 \uad81\uc804 \ud558\ub098\ub97c \uc138\uc6b0\ub294 \uac83 \uc774\uc0c1\uc774\uc5c8\ub2e4. \ud1b5\uce58\uc790\uc640 \uc720\ub825 \uac00\ubb38, \uad00\ub9ac\uc640 \uadf8 \uc0dd\ud65c\uc744 \ub4b7\ubc1b\uce68\ud558\ub294 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc600\ub2e4. \uc815\uce58\uc758 \uc911\uc2ec\uc740 \ud2b9\uc815\ud55c \ucde8\ud5a5\uacfc \uaddc\uce59\uc744 \ub098\ub204\ub294 \ubb38\ud654\uc758 \uc911\uc2ec\uc774 \ub418\uae30\ub3c4 \ud588\ub2e4. \u300e\uac90\uc9c0 \uc774\uc57c\uae30\u300f\uac00 \ubcf4\uc5ec \uc8fc\ub294 \uad81\uc815\uc740 \uc774\ub7f0 \uad00\uacc4 \uc18d\uc5d0 \uc788\uc5c8\ub2e4. \uad50\uc7ac\ub294 \ud5e4\uc774\uc548 \uc2dc\ub300\uc5d0 \ud6c4\uc9c0\uc640\ub77c \uac00\ubb38\uc774 \ucc9c\ud669\uc744 \ubcf4\uc88c\ud558\uac70\ub098 \uc12d\uc815\uc758 \uc790\ub9ac\uc5d0 \uc624\ub974\uba70 \uc601\ud5a5\ub825\uc744 \ud0a4\uc6e0\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uad81\uc815\uc758 \uc5ed\uc0ac\ub294 \ucc9c\ud669 \ud55c \uc0ac\ub78c\uc758 \uc120\ud0dd\ub9cc\uc73c\ub85c \uc6c0\uc9c1\uc778 \uac83\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uac00\ubb38\uacfc \uc9c0\uc704, \ud63c\uc778\uacfc \uce5c\uc871 \uad00\uacc4\uac00 \uad8c\ub825\uc758 \uc870\uac74\uc774 \ub418\uc5c8\ub2e4. \uc18c\uc124 \uc18d \uc778\ubb3c\uc758 \uc0ac\ub791\uc774\ub098 \ub9cc\ub0a8\uc774 \uc624\ub298\uc758 \ub3c5\uc790\uc5d0\uac8c\ub294 \uc0ac\uc801\uc778 \uc77c\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc2e0\ubd84\uacfc \ud608\ud1b5\uc774 \uc911\uc694\ud55c \uc0ac\ud68c\uc5d0\uc11c\ub294 \uce5c\ubc00\ud55c \uad00\uacc4\ub3c4 \uacf5\uc801\uc778 \uc790\ub9ac\ub97c \ubc14\uafc0 \uc218 \uc788\uc5c8\ub2e4. \uc904\uac70\ub9ac\uc758 \uac10\uc815\uc744 \ub530\ub77c\uac00\uba74\uc11c \uadf8 \uac10\uc815\uc774 \ub193\uc778 \uc0ac\ud68c\uc758 \uaddc\uce59\uc744 \ud568\uaed8 \ubcf4\uba74 \ud589\ub3d9\uc774 \uc870\uae08 \ub354 \uc798 \uc774\ud574\ub41c\ub2e4. \ub2f9\uc2dc \uc77c\ubcf8\uc5d0\uc11c\ub294 \uc911\uad6d\uc758 \ubb38\uc790\uc640 \ud559\ubb38\uc744 \ubc1b\uc544\ub4e4\uc774\ub294 \uc804\ud1b5\uc774 \uc788\uc5c8\ub2e4. \ub3d9\uc2dc\uc5d0 \uc77c\ubcf8\uc5b4\uc758 \uc18c\ub9ac\ub97c \uc801\ub294 \uac00\ub098\uac00 \ubc1c\uc804\ud588\ub2e4. \uad50\uc7ac\ub294 \uc774 \ubcc0\ud654\uc640 \u300e\uac90\uc9c0 \uc774\uc57c\uae30\u300f\ub97c \uc5f0\uacb0\ud574 \uc124\uba85\ud55c\ub2e4. \ub2e4\ub978 \ubb38\ud654\uc5d0\uc11c \uc628 \uae00\uc790\ub97c \uc0ac\uc6a9\ud558\ub358 \uc0ac\ud68c\uac00 \uc790\uae30 \ub9d0\uc758 \ud45c\ud604 \ubc29\ubc95\uc744 \ub113\ud600 \uac04 \uac83\uc774\ub2e4. \ubb38\uc790\uc758 \ubcc0\ud654\ub294 \uae00\uc790 \ubaa8\uc591\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \ub9d0\uc744 \uc5bc\ub9c8\ub098 \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc801\uc744 \uc218 \uc788\ub294\uc9c0\uc640 \uad00\ub828\ub41c\ub2e4. \ub9d0\ud22c\uc640 \uac10\uc815, \uc77c\uc0c1 \uc18d \uad00\uacc4\uac00 \uae00\ub85c \uc62e\uaca8\uc9c8 \uae38\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc678\ubd80\uc758 \ubb38\ud654\ub97c \ubc1b\uc544\ub4e4\uc774\ub294 \uc77c\uacfc \uc790\uae30 \uc5b8\uc5b4\uc758 \ud45c\ud604\uc744 \ub9cc\ub4dc\ub294 \uc77c\uc774 \ud568\uaed8 \uc9c4\ud589\ub418\uc5c8\ub2e4. \u300e\uac90\uc9c0 \uc774\uc57c\uae30\u300f\ub294 11\uc138\uae30 \uad81\uc815 \uc5ec\uc131 \ubb34\ub77c\uc0ac\ud0a4 \uc2dc\ud0a4\ubd80\uac00 \uc4f4 \uc791\ud488\uc73c\ub85c \uc54c\ub824\uc838 \uc788\ub2e4. \uad50\uc7ac\ub294 \uadf8\uac00 \uadc0\uc871 \uac00\ubb38 \ucd9c\uc2e0\uc73c\ub85c \uad81\uc815\uc5d0\uc11c \uc77c\ud588\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc790\uc138\ud55c \uc0dd\uc560\uc640 \uc9d1\ud544 \uacfc\uc815\uc5d0\ub294 \uc54c\ub824\uc9c0\uc9c0 \uc54a\uc740 \ubd80\ubd84\ub3c4 \uc788\uc73c\ubbc0\ub85c \ubaa8\ub4e0 \uc7a5\uba74\uc744 \uc791\uac00\uc758 \uc2e4\uc81c \uacbd\ud5d8\uc73c\ub85c \uc77d\uc744 \uc218\ub294 \uc5c6\ub2e4. \uc791\ud488\uc5d0\ub294 \ud5c8\uad6c\uc758 \ud669\uc790 \ud788\uce74\ub8e8 \uac90\uc9c0\uc640 \uc8fc\ubcc0 \uc778\ubb3c\ub4e4\uc758 \uad00\uacc4\uac00 \ud3bc\uccd0\uc9c4\ub2e4. \uc655\uc704 \uacc4\uc2b9\uc5d0\uc11c \ubc97\uc5b4\ub09c \uc778\ubb3c\uc758 \uc0b6\uacfc \uc5ec\ub7ec \uc0ac\ub791, \uc9c0\uc704\uc758 \ubb38\uc81c\uac00 \uc5bd\ud78c\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc804\uccb4 \uc904\uac70\ub9ac\ub97c \uc555\ucd95\ud558\uae30\ubcf4\ub2e4 \uc774 \uc18c\uc124\uc774 \uc61b \uc218\ub3c4\uc758 \uc0dd\ud65c\uc744 \ubc14\ub77c\ubcf4\ub294 \ucc3d\uc774 \ub41c\ub2e4\ub294 \uc810\uc5d0 \uc8fc\ubaa9\ud574 \ubcf4\uc790. 17\uc138\uae30 \ud654\ucca9\uc758 \uc7a5\uba74\uc5d0\uc11c\ub294 \uc5b4\ub9b0 \uc2dc\ub140\ub4e4\uc774 \ub208 \uc18d\uc5d0\uc11c \ub178\ub294 \ub3d9\uc548 \uac90\uc9c0\uc640 \ubb34\ub77c\uc0ac\ud0a4\uac00 \ud207\ub9c8\ub8e8 \ucabd\uc5d0\uc11c \uc9c0\ucf1c\ubcf8\ub2e4. \ud070 \uc0ac\uac74\ubcf4\ub2e4 \uc791\uc740 \ub180\uc774\uac00 \ud654\uba74\uc758 \uc911\uc2ec\uc774 \ub41c\ub2e4. \uac74\ubb3c\uc758 \uc548\ud30e\uacfc \uc0ac\ub78c\ub4e4\uc758 \uc790\ub9ac \ucc28\uc774\ub97c \uc0b4\ud53c\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \uadf8\ub9bc\uc744 \uc77d\ub294 \uc7ac\ubbf8\uac00 \uc788\ub2e4. \ub2e4\ub9cc \uc774 \uadf8\ub9bc\uc740 11\uc138\uae30 \uad81\uc815\uc5d0\uc11c \uc9c1\uc811 \ucd2c\uc601\ud55c \uc0dd\ud65c \uae30\ub85d\uc774 \uc544\ub2c8\ub2e4. \uc218\ubc31 \ub144 \ub4a4 \uc81c\uc791\uc790\uac00 \uc18c\uc124\uc744 \ud574\uc11d\ud55c \uc774\ubbf8\uc9c0\ub2e4. \uc61b \uc774\uc57c\uae30\ub97c \ud6c4\ub300\uc758 \ub208\uc73c\ub85c \ub2e4\uc2dc \ud45c\ud604\ud558\ub294 \uacfc\uc815\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uc18c\uc124 \uc18d \uc2dc\ub300\uc640 \uadf8\ub9bc\uc758 \uc2dc\ub300\ub97c \ub098\ub204\uc5b4 \ubcf4\uba74 \uc624\ub798\ub41c \uc791\ud488\uc774 \uc5b4\ub5bb\uac8c \uacc4\uc18d \uc77d\ud614\ub294\uc9c0\ub3c4 \ubcf4\uc778\ub2e4. \uad50\uc7ac\ub294 \uc791\ud488\uc5d0 \uc758\ubcf5\uacfc \ub180\uc774, \uc545\uae30, \uc77c\uc0c1\uc758 \uc608\uc808\uc774 \ub098\ud0c0\ub09c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc774\ub7f0 \uc138\ubd80\ub294 \uad81\uc815 \ubb38\ud654\ub97c \uc774\ud574\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ud558\uc9c0\ub9cc \uad81\uc815\uc758 \uc0dd\ud65c\uc774 \ub2f9\uc2dc \uad50\ud1a0 \uc8fc\ubbfc \ubaa8\ub450\uc758 \uc0dd\ud65c\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ub3c4\uc2dc\uc758 \ubb38\ud654\ub294 \uadf8\uacf3\uc5d0\uc11c \uae00\uc744 \ub0a8\uae34 \uc0ac\ub78c\uc758 \ubc94\uc704\ubcf4\ub2e4 \ub113\uc5c8\ub2e4. \uc2dc\ub140\uc640 \uad00\ub9ac, \ubb3c\uc790\ub97c \uacf5\uae09\ud55c \uc0ac\ub78c\ub4e4\uc758 \uc790\ub9ac\ub294 \uc11c\ub85c \ub2ec\ub790\ub2e4. \uc791\ud488\uc5d0\uc11c \uc544\ub984\ub2e4\uc6b4 \uc7a5\uba74\uc744 \ub9cc\ub0ac\ub2e4\uace0 \uadf8 \uc0ac\ud68c\uc758 \ubaa8\ub4e0 \uad00\uacc4\uac00 \ud3b8\uc548\ud588\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub204\uac00 \ub9d0\ud558\uace0 \ub204\uad6c\uc758 \uad00\uc810\uc774 \uc911\uc2ec\uc778\uc9c0 \ubb3b\ub294 \uc77c\uc740 \uac10\uc0c1\uc744 \ubb34\uac81\uac8c \ub9cc\ub4e4\uae30\ubcf4\ub2e4 \ubcf4\uc774\uc9c0 \uc54a\ub358 \uc8fc\ubcc0\uc744 \ud568\uaed8 \ubcf4\uac8c \ud55c\ub2e4. \uc720\uba85\ud55c \uc18c\uc124\uc740 \uc2e4\uc81c \uc7a5\uc18c\ub97c \ub2e4\uc2dc \ubcf4\uac8c \ub9cc\ub4e0\ub2e4. \uad81\uc815\uc758 \ubc29\uacfc \ud207\ub9c8\ub8e8, \uacc4\uc808\uc744 \ub290\ub07c\ub294 \ub9c8\ub2f9\ub3c4 \uc774\uc57c\uae30\ub97c \uc54c\uace0 \ub098\uba74 \ub2e4\ub978 \ud45c\uc815\uc744 \uc5bb\ub294\ub2e4. \uac74\ubb3c\uc774 \ub2e8\uc9c0 \uc624\ub798\ub41c \ub098\ubb34\uc640 \uc9c0\ubd95\uc774 \uc544\ub2c8\ub77c \uc0ac\ub78c\ub4e4\uc774 \uc11c\ub85c\ub97c \uae30\ub2e4\ub9ac\uace0 \ubc14\ub77c\ubcf8 \uacf5\uac04\uc73c\ub85c \ub290\uaef4\uc9c0\ub294 \uac83\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc18c\uc124\uc758 \ubaa8\ub4e0 \uc7a5\uc18c\ub97c \uc9c0\uae08\uc758 \uc9c0\ub3c4 \uc704\uc5d0 \uc815\ud655\ud788 \ud45c\uc2dc\ud560 \uc218 \uc788\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud5c8\uad6c\uc640 \uc5ed\uc0ac \uc790\ub8cc, \ud604\uc874\ud558\ub294 \uc720\uc801\uc740 \uac01\uac01\uc758 \ud655\uc778\uc774 \ud544\uc694\ud558\ub2e4. \uc774\ubc88 \uadf8\ub9bc\uc740 \ud2b9\uc815 \uad00\uad11\uc9c0\uc758 \uc61b \ubaa8\uc2b5\uc744 \uc778\uc99d\ud558\uae30\ubcf4\ub2e4 \uad81\uc815\uc758 \uacf5\uac04\uacfc \uc0dd\ud65c\uc744 \uc0dd\uac01\ud558\uac8c \ud558\ub294 \uc790\ub8cc\ub85c \ubcf4\ub294 \ud3b8\uc774 \uc54c\ub9de\ub2e4. \uc61b \ub3c4\uc2dc\ub97c \uc774\ud574\ud558\ub824\uace0 \uc655\uacfc \uc804\uc7c1\uc758 \uc5f0\ub3c4\ub9cc \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \ubb34\uc5c7\uc744 \uc785\uace0 \uc5b4\ub5bb\uac8c \ub180\uba70 \uc5b4\ub5a4 \ub9d0\uc744 \uae00\ub85c \ub0a8\uacbc\ub294\uc9c0\ub3c4 \ub3c4\uc2dc\uc758 \uc5ed\uc0ac\ub2e4. \u300e\uac90\uc9c0 \uc774\uc57c\uae30\u300f\uc640 \ud6c4\ub300\uc758 \uadf8\ub9bc\uc740 \ud5e4\uc774\uc548\ucfc4\uc758 \uad81\uc815 \ubb38\ud654\uac00 \uae34 \uc2dc\uac04 \ub3d9\uc548 \uc77d\ud788\uace0 \ub2e4\uc2dc \uadf8\ub824\uc84c\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uad50\ud1a0\ub97c \uc0dd\uac01\ud560 \ub54c \uc815\uc6d0\uacfc \uc0ac\ucc30 \uacc1\uc5d0 \uc774 \ub208\ub180\uc774 \uc7a5\uba74\ub3c4 \ub193\uc544 \ubcf4\uba74 \uc5b4\ub5a8\uae4c. \ud55c \ub3c4\uc2dc\uc5d0\ub294 \ud070 \uc815\uce58\uc758 \uc2dc\uac04\uacfc \uc791\uc740 \uc0dd\ud65c\uc758 \uc2dc\uac04\uc774 \ud568\uaed8 \ud750\ub978\ub2e4. \uc18c\uc124 \uc18d\uc758 \ud558\ub8e8\ub97c \uc77d\ub294 \uac83\uc740 \uadf8 \uac00\uc6b4\ub370 \uae30\ub85d\uacfc \uc0c1\uc0c1 \uc0ac\uc774\uc5d0 \ub0a8\uc740 \ud55c \uce35\uc744 \ucc9c\ucc9c\ud788 \uac78\uc5b4 \ubcf4\ub294 \uc77c\uc774\ub2e4."}, {"id": "lisbon-1755-earthquake-and-new-streets", "title": "\ub9ac\uc2a4\ubcf8 1755 \u2014 \ubb34\ub108\uc9c4 \ub3c4\uc2dc\uc758 \uae38\uc740 \uc5b4\ub5bb\uac8c \ub2e4\uc2dc \uadf8\ub824\uc84c\uc744\uae4c", "summary": "1755\ub144\uc758 \uc2dc\uc640 1760\ub144 \uad00\ucc30 \uae30\ub85d, \uc774\ud6c4\uc758 \uac70\ub9ac \uacc4\ud68d\uc73c\ub85c \uc7ac\ub09c\uacfc \uc7ac\uac74\uc758 \uc2dc\uac04\uc744 \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/lisbon-1755-earthquake-and-new-streets/index.html", "image": "../media/lisbon-1755-earthquake-and-new-streets.png", "alt": "\uc9c0\uc9c4 \ub4a4 \uc11c\ub85c \ub3d5\ub294 \uc0ac\ub78c\ub4e4\uacfc \uac15\ubcc0\uc758 \ub9ac\uc2a4\ubcf8\uc744 \uadf8\ub9b0 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ub9ac\uc2a4\ubcf8 1755 \u2014 \ubb34\ub108\uc9c4 \ub3c4\uc2dc\uc758 \uae38\uc740 \uc5b4\ub5bb\uac8c \ub2e4\uc2dc \uadf8\ub824\uc84c\uc744\uae4c \ud14c\uc8fc\uac15\uc758 \ud56d\uad6c\uc640 \uc7ac\ub09c\uc758 \uae30\ub85d, \uad11\uc7a5\uacfc \uac70\ub9ac\uc758 \uc7ac\uac74 1755\ub144\uc758 \uc2dc\uc640 1760\ub144 \uad00\ucc30 \uae30\ub85d, \uc774\ud6c4\uc758 \uac70\ub9ac \uacc4\ud68d\uc73c\ub85c \uc7ac\ub09c\uacfc \uc7ac\uac74\uc758 \uc2dc\uac04\uc744 \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ub3c4\uc2dc\uac00 \ud070 \uc7ac\ub09c\uc744 \uacaa\uc73c\uba74 \uac74\ubb3c\ub9cc \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \uc624\uac00\ub358 \uae38\uacfc \uc77c\ud558\ub358 \uc7a5\uc18c, \uc775\uc219\ud55c \uc911\uc2ec\ub3c4 \ud568\uaed8 \ud754\ub4e4\ub9b0\ub2e4. 1755\ub144 \ub9ac\uc2a4\ubcf8\uc758 \uc9c0\uc9c4\uc740 \uc720\ub7fd\uc5d0 \ud070 \ucda9\uaca9\uc744 \ub0a8\uacbc\ub2e4. \uc5ec\uae30\uc11c\ub294 \ud53c\ud574 \uaddc\ubaa8\uc758 \uc22b\uc790\ub97c \uacbd\uc7c1\ud558\ub4ef \ub098\uc5f4\ud558\uae30\ubcf4\ub2e4, \uc7ac\ub09c\uc774 \ub0a8\uae34 \uae30\ub85d\uacfc \uc774\ud6c4\uc758 \uac70\ub9ac \uacc4\ud68d\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubcf8\ub2e4. \ub9ac\uc2a4\ubcf8\uc740 \ud14c\uc8fc\uac15\uacfc \uc5f0\uacb0\ub41c \ud56d\uad6c \ub3c4\uc2dc\uc600\ub2e4. \ubb3c\uac00\uc5d0\ub294 \ubc30\uc640 \uad50\uc5ed, \uc655\uc2e4\uc758 \uacf5\uac04\uc774 \ubaa8\uc600\ub2e4. \uac15\uc740 \uc544\ub984\ub2e4\uc6b4 \uc804\ub9dd\uc778 \ub3d9\uc2dc\uc5d0 \uc0ac\ub78c\uacfc \ubb3c\uac74\uc774 \ub4dc\ub098\ub4dc\ub294 \ud1b5\ub85c\uc600\ub2e4. \ub3c4\uc2dc\uc758 \uc911\uc2ec\uc744 \uc774\ud574\ud558\ub824\uba74 \uac74\ubb3c\uc758 \ubaa9\ub85d\ub9cc\uc774 \uc544\ub2c8\ub77c \uac15\uacfc \uae38\uc774 \uc5b4\ub5bb\uac8c \ub9cc\ub0ac\ub294\uc9c0 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc7ac\ub09c \uc774\uc804\uc758 \uad81\uc804\uacfc \uc881\uc740 \uae38\ub4e4\uc774 \uc788\ub358 \uc790\ub9ac\ub294 \uc774\ud6c4 \ud06c\uac8c \ubc14\ub00c\uc5c8\ub2e4. \uc624\ub298 \ub113\uace0 \uc815\ub3c8\ub418\uc5b4 \ubcf4\uc774\ub294 \uacf5\uac04\uc744 \ucc98\uc74c\ubd80\ud130 \ub298 \uadf8\ub7ac\ub358 \uac83\uc73c\ub85c \uc0dd\uac01\ud558\uba74 \ubcc0\ud654\uc758 \uc758\ubbf8\ub97c \ub193\uce5c\ub2e4. \ub3c4\uc2dc\ub294 \uc624\ub798\ub418\uc5c8\uc5b4\ub3c4 \uadf8 \uc548\uc758 \uae38\uacfc \uad11\uc7a5\uc740 \ud2b9\uc815\ud55c \uc0ac\uac74 \ub4a4\uc5d0 \uc0c8\ub85c \ub9cc\ub4e4\uc5b4\uc9c8 \uc218 \uc788\ub2e4. 1755\ub144\uc758 \uc9c0\uc9c4\uc5d0 \uad00\ud55c \uae30\ub85d\uc5d0\ub294 \ubb34\ub108\uc9c0\ub294 \uac74\ubb3c\uacfc \ud654\uc7ac, \uac15\uacfc \ubc14\ub2e4 \ucabd\uc758 \uc704\ud5d8\uc774 \ud568\uaed8 \ub4f1\uc7a5\ud55c\ub2e4. \uc9c0\uc9c4\uc774 \uba48\ucd98 \uc21c\uac04 \uc7ac\ub09c\uc774 \ub05d\ub098\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \ud55c \uc704\ud5d8\uc744 \ud53c\ud574 \uc774\ub3d9\ud558\ub2e4 \ub2e4\ub978 \uc704\ud5d8\uacfc \ub9c8\uc8fc\ud560 \uc218 \uc788\uc5c8\ub2e4. \ub2e4\ub9cc \ub2f9\uc2dc\uc758 \uc2dc\uc640 \uc5ec\ud589 \uae30\ub85d\uc5d0 \uc2e4\ub9b0 \ubaa8\ub4e0 \ubb18\uc0ac\ub97c \uc815\ud655\ud55c \uce21\uc815 \uacb0\uacfc\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc11c\ub294 \uc548 \ub41c\ub2e4. \uacf5\ud3ec\ub97c \uc804\ub2ec\ud558\ub294 \ubb38\ud559\uc801\uc778 \uacfc\uc7a5\uacfc \uad00\ucc30\ub41c \uc0ac\uc2e4\uc774 \uc11e\uc77c \uc218 \uc788\ub2e4. \uc624\ub798\ub41c \uc790\ub8cc\uc758 \uc0ac\ub9dd\uc790 \uc218\ub098 \uadf9\uc801\uc778 \uc7a5\uba74\uc744 \uadf8\ub300\ub85c \ud655\uc815\ud558\uae30\ubcf4\ub2e4 \uc790\ub8cc\uac00 \ub9cc\ub4e4\uc5b4\uc9c4 \ubaa9\uc801\ub3c4 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uac19\uc740 \ud574 \ub7f0\ub358\uc5d0\uc11c \ucd9c\ud310\ub41c \uc775\uba85\uc758 \uc9c0\uc9c4 \uc2dc\ub294 \ub9ac\uc2a4\ubcf8\uc758 \ud30c\uad34\ub97c \uba3c \uacf3\uc758 \ub3c5\uc790\uc5d0\uac8c \uc804\ud588\ub2e4. \uc544\ub984\ub2f5\uace0 \ud48d\uc694\ub86d\ub358 \ub3c4\uc2dc\uc640 \ud3d0\ud5c8\uac00 \ub41c \ub3c4\uc2dc\uac00 \ub300\ube44\ub41c\ub2e4. \uae00\uc740 \ud604\uc7a5\uc758 \uce21\ub7c9\ub3c4\uac00 \uc544\ub2c8\ub77c \uc0c1\uc2e4\uc744 \ub290\ub07c\uac8c \ud558\ub294 \uc7a5\uce58\ub85c \uc0ac\uac74\uc744 \ubc30\uc5f4\ud55c\ub2e4. \uc774\ub7f0 \uc790\ub8cc\ub294 \ubb34\uc5c7\uc774 \uc77c\uc5b4\ub0ac\ub294\uc9c0\ubfd0 \uc544\ub2c8\ub77c \ub2e4\ub978 \uc9c0\uc5ed \uc0ac\ub78c\ub4e4\uc774 \uadf8 \uc0ac\uac74\uc744 \uc5b4\ub5bb\uac8c \ubc1b\uc544\ub4e4\uc600\ub294\uc9c0\ub3c4 \uc54c\ub824 \uc900\ub2e4. \uc7ac\ub09c\uc774 \ud55c \ub3c4\uc2dc\uc758 \uacbd\uacc4 \uc548\uc5d0\ub9cc \uba38\ubb3c\uc9c0 \uc54a\uace0 \ucd9c\ud310\uacfc \uc885\uad50\uc801 \ud574\uc11d\uc744 \ud1b5\ud574 \ud37c\uc9c4 \uac83\uc774\ub2e4. \ubb3c\ub9ac\uc801\uc778 \ucda9\uaca9\uacfc \uc18c\uc2dd\uc774 \ub9cc\ub4e0 \ucda9\uaca9\uc740 \uc11c\ub85c \ub2e4\ub978 \uacbd\ub85c\ub85c \uc774\ub3d9\ud588\ub2e4. \ub9c8\ud2f4 \ud744\uc758 \u300e\ud3ec\ub974\ud22c\uac08 \uc5ec\ud589\u300f\uc5d0\ub294 \uc2a4\ud2b8\ub798\uc2a4\ubaa8\uc5b4\uc758 1760\ub144 \uad00\ucc30\uc774 \uc778\uc6a9\ub418\uc5b4 \uc788\ub2e4. \uadf8 \uae30\ub85d\uc5d0\uc11c \uc0c8 \ub3c4\uc2dc\uc758 \uc644\uc131\uc740 \uc544\uc9c1 \uba3c \uc804\ub9dd\uc774\uc5c8\uace0, \uacc4\ud68d\ub41c \ubc29\uc2dd\ub300\ub85c \uc9c0\uc5b4\uc9c4 \uac74\ubb3c\ub3c4 \ub9ce\uc9c0 \uc54a\uc558\ub2e4. \uc7ac\ub09c \uc5f0\ub3c4\uc640 \uc7ac\uac74\uc758 \uc644\ub8cc\ub97c \ud558\ub098\uc758 \uc21c\uac04\uc73c\ub85c \ubb36\uc744 \uc218 \uc5c6\ub294 \uc774\uc720\ub2e4. \uc9c0\ub3c4 \uc704\uc758 \uacc4\ud68d\uc740 \ube68\ub9ac \uadf8\ub9b4 \uc218 \uc788\uc9c0\ub9cc \uc2e4\uc81c\ub85c \uc9d1\uacfc \uacf5\uacf5\uc2dc\uc124\uc744 \uc138\uc6b0\ub294 \ub370\uc5d0\ub294 \uc2dc\uac04\uacfc \uc790\uc6d0\uc774 \ub4e0\ub2e4. \uc784\uc2dc\ub85c \uc0b4\uc544\uc57c \ud558\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc2dc\uac04\ub3c4 \uadf8 \uc0ac\uc774\uc5d0 \ub193\uc778\ub2e4. \uc644\uc131\ub41c \uac70\ub9ac\uc758 \uc9c8\uc11c\ub9cc \uac10\uc0c1\ud558\uba74 \uacc4\ud68d\uacfc \uacb0\uacfc \uc0ac\uc774\uc5d0 \uc788\uc5c8\ub358 \uae34 \uacfc\uc815\uc774 \uc0ac\ub77c\uc9c0\uae30 \uc27d\ub2e4. \uc778\uc6a9\ubb38\uc5d0 \ub2f4\uae34 \ud310\ub2e8\ub3c4 \ud558\ub098\uc758 \ubaa9\uc18c\ub9ac\ub2e4. \uae30\ub85d\uc790\ub294 \uacc4\ud68d\uc758 \uaddc\ubaa8\ub97c \uce6d\ucc2c\ud558\uba74\uc11c \uac74\ucd95\uc758 \uc0dd\uae40\uc0c8\uc5d0\ub294 \ube44\ud310\uc801\uc778 \ub9d0\uc744 \ub0a8\uae34\ub2e4. \uac19\uc740 \uc7ac\uac74 \uc548\uc5d0\uc11c\ub3c4 \uac70\ub9ac\uc758 \ubc30\uce58\uc640 \uac74\ubb3c\uc758 \uc678\uad00\uc744 \ub530\ub85c \ud3c9\uac00\ud55c \uac83\uc774\ub2e4. \uc5ec\ud589\uc790\uac00 \uc0c8 \ub3c4\uc2dc\ub97c \uc5b4\ub5bb\uac8c \ubcf4\uc558\ub294\uc9c0 \uc54c \uc218 \uc788\ub294 \uad6c\uccb4\uc801\uc778 \ucc28\uc774\ub2e4. \uc624\ub298\uc758 \ub3c5\uc790\ub294 \uadf8 \ud3c9\uac00\ub97c \uadf8\ub300\ub85c \ub530\ub77c\uc57c \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2f9\uc2dc \uc544\uc9c1 \uacf5\uc0ac\uac00 \uc9c4\ud589 \uc911\uc774\uc5c8\ub2e4\ub294 \uc870\uac74\uc744 \uba3c\uc800 \ud655\uc778\ud558\uace0, \uadf8\uac00 \uae30\ub300\ud55c \uc544\ub984\ub2e4\uc6c0\uc774 \ubb34\uc5c7\uc774\uc5c8\ub294\uc9c0 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uacfc\uac70\uc758 \uc758\uacac\uc740 \uc0ac\uc2e4 \ud655\uc778\uc758 \uc790\ub8cc\uc774\uba74\uc11c \ub2e4\ub978 \uc2dc\ub300\uc758 \ucde8\ud5a5\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uae30\ub85d\uc774\uae30\ub3c4 \ud558\ub2e4. \uc778\uc6a9\ub41c \uacc4\ud68d\uc5d0\ub294 \uac15\uc744 \ud5a5\ud574 \uc5f4\ub9b0 \uad11\uc7a5, \uc77c\uc815\ud55c \ubaa8\uc2b5\uc758 \uac74\ubb3c, \uc11c\ub85c \uc9c1\uac01\uc73c\ub85c \ub9cc\ub098\ub294 \uac70\ub9ac\ub4e4\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \uc774\uc804\uc758 \ucd18\ucd18\ud55c \uae38\uc744 \uadf8\ub300\ub85c \ub418\uc0b4\ub9ac\ub294 \ub300\uc2e0 \uc0c8\ub85c\uc6b4 \uc911\uc2ec\uc744 \ub9cc\ub4dc\ub294 \uad6c\uc0c1\uc774\uc5c8\ub2e4. \uad11\uc7a5\uacfc \ud070\uae38\uc740 \uc11c\ub85c \ub530\ub85c \ub193\uc778 \uc7a5\uc2dd\uc774 \uc544\ub2c8\ub77c \uc5f0\uacb0\ub41c \uad6c\uc870\ub2e4. \uac15\uc5d0\uc11c \ub3c4\uc2dc \uc548\uc73c\ub85c \ub4e4\uc5b4\uc624\ub294 \uc2dc\uc120\uacfc \uc774\ub3d9\uc744 \uc0dd\uac01\ud558\uba74 \uadf8 \uad6c\uc131\uc774 \ub354 \uc798 \ubcf4\uc778\ub2e4. \uad11\uc7a5\uc740 \uc0ac\ub78c\uc744 \ubaa8\uc73c\uace0 \uae38\uc740 \ub2e4\ub978 \uacf5\uac04\uc73c\ub85c \uc774\ub048\ub2e4. \uc7ac\uac74\uc740 \uac1c\ubcc4 \uac74\ubb3c\uc744 \uc218\ub9ac\ud558\ub294 \uc77c\ub9cc\uc774 \uc544\ub2c8\ub77c \uc0ac\ub78c\ub4e4\uc774 \ub3c4\uc2dc\ub97c \uc774\uc6a9\ud560 \ubc29\uc2dd\uc744 \ub2e4\uc2dc \ubc30\uce58\ud558\ub294 \uc77c\uc774\uc5c8\ub2e4. \ud744\uc774 \ub098\uc911\uc5d0 \ubcf8 \ub9ac\uc2a4\ubcf8\uc740 \uc55e\uc120 \uacc4\ud68d\uacfc \uc5f0\uacb0\ub418\ub294 \ubaa8\uc2b5\uc774\uc5c8\ub2e4. \ud558\uc9c0\ub9cc \uc5ec\ud589\uc790\uac00 \uc815\ub3c8\ub41c \uac70\ub9ac\uc5d0\uc11c \ub290\ub080 \uc778\uc0c1\ub9cc\uc73c\ub85c \uc7ac\uac74\uc758 \ubaa8\ub4e0 \ud6a8\uacfc\ub97c \ud3c9\uac00\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc0c8\ub85c\uc6b4 \ubc30\uce58\ub294 \ub204\uad70\uac00\uc5d0\uac8c \ud3b8\ub9ac\ud558\uace0 \ub204\uad70\uac00\uc5d0\uac8c \ub0af\uc120 \ud658\uacbd\uc774\uc5c8\uc744 \uc218 \uc788\ub2e4. \uacc4\ud68d\uc790\ub294 \ub3c4\uc2dc\ub97c \ub113\uac8c \ubcf4\uc9c0\ub9cc \uc8fc\ubbfc\uc740 \uc9d1\uacfc \uac00\uac8c, \ub9e4\uc77c \uac77\ub294 \uae38\uc5d0\uc11c \ubcc0\ud654\ub97c \uacbd\ud5d8\ud55c\ub2e4. \uac19\uc740 \uc7ac\uac74\uc744 \uc11c\ub85c \ub2e4\ub978 \ud06c\uae30\ub85c \ubcf4\ub294 \uc148\uc774\ub2e4. \uc88b\uc740 \ub3c4\uc2dc \uacc4\ud68d\uc774 \ubb34\uc5c7\uc778\uc9c0 \ubb3b\uae30 \uc704\ud574\uc11c\ub294 \uc678\uad00\uc758 \ud1b5\uc77c\uc131\uc5d0 \ub354\ud574 \uadf8 \uc548\uc5d0\uc11c \uc0b4\uc544\uc57c \ud558\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc870\uac74\ub3c4 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \ub9ac\uc2a4\ubcf8\uc758 \uace7\uc740 \uae38\uacfc \uad11\uc7a5\uc744 \ubcfc \ub54c\uc5d0\ub294 \uc65c \uc774 \ud615\ud0dc\uac00 \ub418\uc5c8\uc744\uae4c \ud558\uace0 \ubb3c\uc5b4\ubcf4\uc790. \ud604\uc7ac\uc758 \ubaa8\uc2b5\uc740 \uc9c0\ud615\ub9cc\uc73c\ub85c \uacb0\uc815\ub418\uc9c0 \uc54a\uc558\ub2e4. \uc7ac\ub09c\uacfc \uc7ac\uac74\uc758 \ud310\ub2e8, \uc5ec\ub7ec \ud574\uc758 \uacf5\uc0ac\uac00 \uacb9\uccd0 \uc788\ub2e4. \uc624\ub798\ub41c \ub3c4\uc2dc\uc5d0\uc11c\ub3c4 \ubcc0\ud654\uc758 \ud754\uc801\uc740 \ud604\uc7ac\uc758 \uc9c8\uc11c \uc18d\uc5d0 \ub0a8\uc544 \uc788\ub2e4. 1755\ub144\uc744 \uac70\ub300\ud55c \ud30c\uad34\uc758 \uc7a5\uba74\uc73c\ub85c\ub9cc \uae30\uc5b5\ud558\uba74 \uadf8 \ub4a4\uc758 \uc2dc\uac04\uc774 \uc9c0\uc6cc\uc9c4\ub2e4. \ubc18\ub300\ub85c \uc544\ub984\ub2f5\uac8c \uc7ac\uac74\ub418\uc5c8\ub2e4\ub294 \ub9d0\ub9cc \ub0a8\uae30\uba74 \uc0c1\uc2e4\uc774 \uac00\ub824\uc9c4\ub2e4. \uc9c1\uc120\uc758 \uae38\ub3c4 \uc0ac\uac74\uc744 \uae30\uc5b5\ud558\ub294 \uc790\ub8cc\uac00 \ub420 \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \ud765\ubbf8\ub86d\ub2e4. \ub450 \uc2dc\uac04\uc744 \ud568\uaed8 \uc77d\uc744 \ub54c \ub3c4\uc2dc\ub294 \uc7ac\ub09c \uc0ac\uc9c4\uc758 \ubc30\uacbd\ub3c4 \uacc4\ud68d\uc758 \ub3c4\uba74\ub3c4 \uc544\ub2cc, \uc190\uc2e4\uc744 \uc548\uace0 \ub2e4\uc2dc \uc0dd\ud65c\uc744 \uc774\uc5b4 \uac04 \uc7a5\uc18c\ub85c \ubcf4\uc778\ub2e4."}, {"id": "london-great-stink-and-sewers", "title": "\ub7f0\ub358 \u2014 \uc9c0\ub3c5\ud55c \ub0c4\uc0c8\uac00 \ub3c4\uc2dc\uc758 \ubc11\ubc14\ub2e5\uc744 \ubc14\uafb8\ub2e4", "summary": "\ud15c\uc2a4\uac15\uc758 \uc545\ucde8\uc640 \uc758\ud68c\uc758 \ub300\uc751, \ubc14\uc798\uc81c\ud2b8\uc758 \ud558\uc218\ub3c4\uc5d0\uc11c \ub3c4\uc2dc\uac00 \uc0dd\ud65c\uc758 \ud754\uc801\uc744 \ucc98\ub9ac\ud558\ub294 \ubc29\uc2dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/london-great-stink-and-sewers/index.html", "image": "../media/london-great-stink-and-sewers.jpg", "alt": "\uc67c\ucabd\uc740 1865\ub144 \ub7f0\ub358 \ud06c\ub85c\uc2a4\ub124\uc2a4 \ud38c\ud504\uc7a5 \uac1c\uc7a5\uc2dd \ub3c4\ud310, \uc624\ub978\ucabd\uc740 \ud30c\ub9ac \uacf5\uc911\ud654\uc7a5\uc2e4 \uc0ac\uc9c4", "text": "\ub7f0\ub358 \u2014 \uc9c0\ub3c5\ud55c \ub0c4\uc0c8\uac00 \ub3c4\uc2dc\uc758 \ubc11\ubc14\ub2e5\uc744 \ubc14\uafb8\ub2e4 1858\ub144 \ud15c\uc2a4\uac15\uc5d0\uc11c \ud558\uc218\ub3c4\uc640 \ud38c\ud504\uc7a5\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uc774\uc57c\uae30 \ud15c\uc2a4\uac15\uc758 \uc545\ucde8\uc640 \uc758\ud68c\uc758 \ub300\uc751, \ubc14\uc798\uc81c\ud2b8\uc758 \ud558\uc218\ub3c4\uc5d0\uc11c \ub3c4\uc2dc\uac00 \uc0dd\ud65c\uc758 \ud754\uc801\uc744 \ucc98\ub9ac\ud558\ub294 \ubc29\uc2dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ub7f0\ub358\uc758 \uad6d\ud68c\uc758\uc0ac\ub2f9 \ucc3d\ubb38\uc5d0 \uc18c\ub3c5\uc81c\ub97c \uc801\uc2e0 \ucee4\ud2bc\uc774 \uac78\ub838\ub2e4. 1858\ub144 \uc5ec\ub984, \ud15c\uc2a4\uac15\uc5d0\uc11c \uc62c\ub77c\uc624\ub294 \ub0c4\uc0c8\ub97c \ub9c9\uae30 \uc704\ud55c \uc870\uce58\uc600\ub2e4. \uac15\ubcc0\uc758 \uc6c5\uc7a5\ud55c \uac74\ubb3c\ub3c4 \uc545\ucde8 \uc55e\uc5d0\uc11c\ub294 \ucc3d\ubb38 \ud558\ub098 \ub9c8\uc74c\ub300\ub85c \uc5f4\uae30 \uc5b4\ub824\uc6e0\ub2e4. \uc774 \uc0ac\uac74\uc740 \u2018\ub300\uc545\ucde8\u2019\ub77c\ub294 \uc774\ub984\uc73c\ub85c \ub0a8\uc558\ub2e4. \uadf8\ub7ec\ub098 \ubb38\uc81c\ub294 \ub0c4\uc0c8\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ub3c4\uc2dc\uac00 \ub9c8\uc2e0 \ubb3c\uacfc \ubc84\ub9b0 \ubb3c\uc774 \uc5b4\ub514\uc5d0\uc11c \ub2e4\uc2dc \ub9cc\ub098\ub294\uac00, \uadf8\ub3d9\uc548 \ub545\uc18d\uc5d0 \uc228\uaca8 \ub450\uc5c8\ub358 \uc9c8\ubb38\uc774 \uac15 \uc704\ub85c \ub5a0\uc62c\ub790\ub2e4. \uc9d1\uc5d0\uc11c \ubb3c\uc744 \ub0b4\ub824 \uc624\ubb3c\uc744 \ubcf4\ub0bc \uc218 \uc788\ub2e4\uba74 \uc0dd\ud65c\uc740 \ud6e8\uc52c \ud3b8\ud574\uc9c4\ub2e4. \ud558\uc9c0\ub9cc \uc9d1 \ubc16\uc73c\ub85c \uc0ac\ub77c\uc84c\ub2e4\ub294 \uac83\uc774 \ub3c4\uc2dc\uc5d0\uc11c\ub3c4 \uc0ac\ub77c\uc84c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ubc30\uc218\ub85c\uc758 \ub05d\uc774 \uac15\uc774\ub77c\uba74 \uc9d1 \uc548\uc758 \uae68\ub057\ud568\uc774 \uac15\ubb3c\uc758 \ubd80\ub2f4\uc73c\ub85c \uc62e\uaca8 \uac08 \uc218 \uc788\ub2e4. 19\uc138\uae30 \ub3c4\uc2dc\uc5d0\uc11c\ub294 \uac00\uc815\uc758 \uc624\uc218\uc5d0 \uacf5\uc7a5\uacfc \uc791\uc5c5\uc7a5\uc758 \ud3d0\uae30\ubb3c\uae4c\uc9c0 \ub354\ud574\uc84c\ub2e4. \uac15\uc740 \uad50\ud1b5\uacfc \ubb3c \uacf5\uae09\uc758 \uae38\uc778 \ub3d9\uc2dc\uc5d0 \ubc84\ub9ac\ub294 \ubb3c\uc744 \ubc1b\ub294 \uacf3\uc774\uc5c8\ub2e4. \uc11c\ub85c \ucda9\ub3cc\ud558\ub294 \uc4f0\uc784\uc774 \uac19\uc740 \ubb3c\uae38\uc5d0 \uc313\uc774\uace0 \uc788\uc5c8\ub2e4. \uc0b0\uc5c5\ub3c4\uc2dc\uc5d0\ub294 \uc77c\uc790\ub9ac\ub97c \ucc3e\uc544 \ub9ce\uc740 \uc0ac\ub78c\uc774 \ub4e4\uc5b4\uc654\ub2e4. \uc9d1\uacfc \uae38, \uc218\ub3c4\uc640 \ubc30\uc218 \uc2dc\uc124\uc774 \uadf8 \uc18d\ub3c4\ub97c \ub530\ub77c\uac00\uc9c0 \ubabb\ud588\ub2e4. \uc778\uad6c\uac00 \ubaa8\uc774\ub294 \uac83\uc740 \uc0dd\uc0b0\uacfc \uc18c\ube44\ub97c \ub298\ub838\uc9c0\ub9cc \uba39\uace0 \uc53b\uace0 \ubc30\uc124\ud558\ub294 \uc0dd\ud65c\uc758 \uaddc\ubaa8\ub3c4 \ud568\uaed8 \ud0a4\uc6e0\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ud55c \uc9d1\uc758 \uad00\ub9ac\ucc98\ub7fc \ubcf4\uc600\ub358 \uc77c\uc774 \uc774\uc6c3\uacfc \uac15\ubcc0 \uc804\uccb4\uc758 \ubb38\uc81c\uac00 \ub418\uc5c8\ub2e4. \ub0b4 \uc9d1\uc758 \ubc30\uc218\uad00\ub9cc \uace0\uccd0\ub3c4 \uadf8 \ub4a4\uc5d0\uc11c \ub2e4\ub978 \uc9d1\uc758 \ubb3c\uacfc \uc11e\uc778\ub2e4. \uc704\uc0dd\uc744 \uac01 \uac00\uc815\uc758 \ubd80\uc9c0\ub7f0\ud568\uc5d0\ub9cc \ub9e1\uae30\uae30 \uc5b4\ub824\uc6e0\ub358 \uc774\uc720\ub2e4. \ud15c\uc2a4\uac15\uc758 \uc545\ucde8\ub294 \uc758\ud68c\uc758 \uc77c\uc0c1\uc744 \uc9c1\uc811 \ubc29\ud574\ud588\ub2e4. \ucc3d\uac00\uc758 \ucee4\ud2bc\uc744 \uc801\uc2dc\ub294 \uc784\uc2dc\ubc29\ud3b8\uc73c\ub85c \uac15 \uc804\uccb4\ub97c \ubc14\uafc0 \uc218\ub294 \uc5c6\uc5c8\ub2e4. \uac15\uc5d0 \uc18c\ub3c5\uc81c\ub97c \ubd93\ub294 \ub300\uc751\ub3c4 \uc624\ubb3c\uc744 \uacc4\uc18d \ud758\ub824\ubcf4\ub0b4\ub294 \uad6c\uc870\ub97c \ud574\uacb0\ud558\uc9c0 \ubabb\ud588\ub2e4. \ub300\uc545\ucde8\uac00 \uc911\uc694\ud55c \uc804\ud658\uc810\uc73c\ub85c \uae30\uc5b5\ub418\ub294 \uae4c\ub2ed\uc740 \uc5ec\uae30 \uc788\ub2e4. \uc624\ub798 \uc874\uc7ac\ud558\ub358 \ubb38\uc81c\uac00 \uad8c\ub825\uc744 \uac00\uc9c4 \uc0ac\ub78c\ub4e4\uc758 \uc0dd\ud65c\uc5d0\ub3c4 \uac00\uae4c\uc774 \ub2e4\uac00\uc654\ub2e4. \ub3c4\uc2dc\uc758 \ubc30\uc218\ub294 \ub4a4\ub85c \ubbf8\ub904 \ub458 \uc218 \uc788\ub294 \ub545\uc18d \uc77c\uc774 \uc544\ub2c8\uac8c \ub418\uc5c8\ub2e4. \ud1a0\ubaa9\uae30\uc0ac \uc870\uc9c0\ud504 \ubc14\uc798\uc81c\ud2b8\ub294 \ub7f0\ub358\uc758 \ud558\uc218\ub3c4 \uc7ac\uc815\ube44\ub97c \uc774\ub04c\uc5c8\ub2e4. 1859\ub144\ubd80\ud130 \uc774\uc5b4\uc9c4 \ub300\uaddc\ubaa8 \uacf5\uc0ac\ub294 \ud769\uc5b4\uc9c4 \uc624\uc218\ub97c \ubaa8\uc544 \ubcf4\ub0b4\ub294 \uccb4\uacc4\ub97c \ub9cc\ub4dc\ub294 \uc77c\uc774\uc5c8\ub2e4. \uc9e7\uc740 \ubc30\uc218\uad00 \ud558\ub098\ub97c \ub354 \ub193\ub294 \uac83\uacfc\ub294 \uaddc\ubaa8\uac00 \ub2ec\ub790\ub2e4. \ubb3c\uc740 \uc9c0\ud615\uc744 \ub530\ub77c \ud750\ub974\uc9c0\ub9cc \ub3c4\uc2dc\uac00 \uc6d0\ud558\ub294 \ubc29\ud5a5\uc73c\ub85c \uc800\uc808\ub85c \uc6c0\uc9c1\uc5ec \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uad00\ub85c\uc640 \ub192\ub0ae\uc774, \ud38c\ud504\uc7a5\uc774 \ud558\ub098\uc758 \uccb4\uacc4\ub85c \ub9de\ubb3c\ub824\uc57c \ud588\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ub3d9\ub124\uc758 \uc0dd\ud65c\uc744 \uc5f0\uacb0\ud574 \uc0dd\uac01\ud558\ub294 \uc124\uacc4\uac00 \ud544\uc694\ud588\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc5ed\uc0ac \ub3c4\ud310\uc758 \ud55c\ucabd\uc740 1865\ub144 \ud06c\ub85c\uc2a4\ub124\uc2a4 \ud38c\ud504\uc7a5 \uac1c\uc7a5\uc2dd\uc774\ub2e4. \uc655\uc138\uc790\uac00 \ucc38\uc11d\ud55c \ud589\uc0ac\uac00 \uae30\uacc4\uc640 \uc2dc\uc124\uc744 \ub458\ub7ec\uc2f8\uace0 \uc5f4\ub9b0\ub2e4. \ub3c4\uc2dc\uc758 \uc704\uc0dd\uc744 \ub5a0\ubc1b\uce58\ub294 \uc7a5\uce58\uac00 \uacf5\uc801\uc778 \uc131\ucde8\ub85c \ub4f1\uc7a5\ud55c \uc7a5\uba74\uc774\ub2e4. \uadf8\ub9bc\uc758 \ub2e4\ub978 \ucabd\uc740 \ub7f0\ub358\uc774 \uc544\ub2c8\ub77c \ud30c\ub9ac\uc758 \uacf5\uc911\ud654\uc7a5\uc2e4 \uc0ac\uc9c4\uc774\ub2e4. \ub450 \uc790\ub8cc\ub294 \uac19\uc740 \uc7a5\uc18c\ub97c \ubcf4\uc5ec \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \ub2e4\ub9cc \uc624\uc218\ub97c \uc62e\uae30\ub294 \ud070 \uc2dc\uc124\uacfc \uc77c\uc0c1\uc5d0\uc11c \uc774\uc6a9\ud558\ub294 \uc791\uc740 \uc2dc\uc124\uc774 \ud568\uaed8 \ud544\uc694\ud588\ub2e4\ub294 \uc810\uc744 \ub098\ub780\ud788 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc0c8 \ud558\uc218\ub3c4\ub294 \uc624\uc218\ub97c \ubaa8\uc544 \ub3c4\uc2ec \ubc16\uc73c\ub85c \ubcf4\ub0b4\ub294 \ub370 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud588\ub2e4. \uadf8\ub7ec\ub098 \ubc30\ucd9c \uc9c0\uc810\uc744 \ubc14\uafb8\ub294 \uac83\uacfc \ubb3c\uc744 \ucda9\ubd84\ud788 \ucc98\ub9ac\ud558\ub294 \uac83\uc740 \uc11c\ub85c \ub2e4\ub978 \ubb38\uc81c\ub2e4. \uc2dc\uc124\uc774 \uc0dd\uacbc\ub2e4\uace0 \uadf8\ub0a0\ubd80\ud130 \uac15\uc758 \ubaa8\ub4e0 \ubb38\uc81c\uac00 \ub05d\ub09c \uac83\uc740 \uc544\ub2c8\ub2e4. \ud6c4\ub300\uc5d0\ub3c4 \ucc98\ub9ac \ubc29\uc2dd\uacfc \ud38c\ud504 \uc2dc\uc124\uc740 \uacc4\uc18d \ubc14\ub00c\uc5c8\ub2e4. \uc774 \uacfc\uc815\uc744 \ud55c \ubc88\uc758 \uc644\ubcbd\ud55c \ubc1c\uba85\uc73c\ub85c \ubcf4\uba74 \ub4a4\uc5d0 \uc774\uc5b4\uc9c4 \uc77c\uc744 \ub193\uce58\uac8c \ub41c\ub2e4. \ud070 \uacf5\uc0ac\ub294 \ud574\uacb0\uc758 \ub05d\uc774\uba74\uc11c \ub3d9\uc2dc\uc5d0 \uc720\uc9c0\uc640 \uac1c\uc120\uc744 \uc2dc\uc791\ud558\ub294 \uc57d\uc18d\uc774\uc5c8\ub2e4. \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc740 \uc545\ucde8\uc640 \uc9c8\ubcd1\uc758 \uad00\uacc4\ub97c \uc624\ub298\ub0a0\uacfc \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc774\ud574\ud558\uc9c0 \uc54a\uc558\ub2e4. \uc9c0\ub3c5\ud55c \ub0c4\uc0c8\ub97c \uc5c6\uc560\ub824\ub294 \ub3d9\uae30\uc640 \uc624\uc5fc\ub41c \ubb3c\uc774 \ubcd1\uc744 \uc62e\uae30\ub294 \uacfc\uc815\uc744 \ubc1d\ud788\ub294 \uc5f0\uad6c\ub294 \uad6c\ubcc4\ud560 \ud544\uc694\uac00 \uc788\ub2e4. \uadf8\ub807\ub354\ub77c\ub3c4 \uc0dd\ud65c\uc758 \uc624\uc5fc\uc6d0\uc744 \ubd84\ub9ac\ud558\uace0 \uc548\uc804\ud55c \ubb3c\uc744 \ud655\ubcf4\ud558\ub294 \uc2dc\uc124\uc740 \uc911\uc694\ud588\ub2e4. \ubaa8\ub4e0 \uc774\ub860\uc774 \uc644\uc131\ub41c \ub4a4\uc5d0\uc57c \uacf5\uc0ac\ub97c \uc2dc\uc791\ud55c \uac83\uc774 \uc544\ub2c8\ub2e4. \ub208\uc55e\uc758 \ubd88\ud3b8, \uad00\ucc30\uacfc \uc5f0\uad6c, \ud589\uc815\uc758 \ud310\ub2e8\uc774 \uc11c\ub85c \ub2e4\ub978 \uc18d\ub3c4\ub85c \uc6c0\uc9c1\uc600\ub2e4. \uac15\uc740 \ud589\uc815 \uad6c\uc5ed\uc758 \uc120\uc744 \ubcf4\uace0 \uba48\ucd94\uc9c0 \uc54a\ub294\ub2e4. \uc704\ucabd\uc5d0\uc11c \ud758\ub824\ubcf4\ub0b8 \uac83\uc774 \uc544\ub798\ucabd \uc0ac\ub78c\uc758 \uc0dd\ud65c\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4. \ud558\uc218\ub3c4\ub97c \uc5f0\uacb0\ud558\ub294 \uacf5\uc0ac\ub294 \uc774\ub7f0 \uad00\uacc4\ub97c \uc2dc\uc124\ub85c \ub2e4\ub8e8\ub294 \uc77c\uc774\uc5c8\ub2e4. \ub0b4 \uc9d1 \ubb38\uc55e\uc744 \uc4f8\uace0 \ub05d\ub0bc \uc218 \uc788\ub294 \uccad\uc18c\uc640 \uaddc\ubaa8\uac00 \ub2ec\ub790\ub2e4. \uc2dc\uc124\uc774 \uc791\ub3d9\ud55c \ub4a4\uc5d0\ub3c4 \ubb34\uc5c7\uc774 \ub4e4\uc5b4\uc624\uace0 \uc5b4\ub514\ub85c \ub098\uac00\ub294\uc9c0 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uad00\uc744 \ubb3b\uc740 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ub3c4\uc2dc\ub294 \uad00\ub9ac\uc758 \ubd80\ub2f4\uc5d0\uc11c \ubc97\uc5b4\ub098\uc9c0 \ubabb\ud55c\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc2dc\uc124\uc77c\uc218\ub85d \ubb38\uc81c\uac00 \uc0dd\uae30\uae30 \uc804\uc5d0\ub294 \uadf8 \uc911\uc694\uc131\uc744 \uc78a\uae30 \uc27d\ub2e4. \ub300\uc545\ucde8\ub97c \ub3cc\uc544\ubcfc \ub54c \ud55c \ubc88\uc758 \uc5ec\ub984\uacfc \uae34 \uacf5\uc0ac \uae30\uac04\uc744 \ud568\uaed8 \ubcf4\ub294 \uc774\uc720\ub3c4 \uc5ec\uae30 \uc788\ub2e4. \uac15\ud55c \ubd88\ud3b8\uc774 \uacb0\uc815\uc744 \uc7ac\ucd09\ud560 \uc218\ub294 \uc788\uc9c0\ub9cc \uadf8 \uacb0\uc815\uc744 \uc624\ub798 \uc791\ub3d9\ud558\uac8c \ub9cc\ub4dc\ub294 \uac83\uc740 \uc5ec\ub7ec \uc2dc\uc124\uacfc \uc0ac\ub78c\uc744 \uc774\uc5b4 \uc8fc\ub294 \uc9c0\uc18d\uc801\uc778 \uc77c\uc774\ub2e4. \uc624\ub298\ub0a0 \ub3c4\uc2dc\ub97c \ubcfc \ub54c\ub294 \ub2e4\ub9ac\uc640 \uc758\uc0ac\ub2f9, \uac15\ubcc0\uc758 \uc0b0\ucc45\ub85c\uac00 \uba3c\uc800 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \ud48d\uacbd\uc744 \ud3b8\ud558\uac8c \ub204\ub9ac\ub294 \uc77c\uc740 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc2dc\uc124\uc5d0 \uae30\ub300\uace0 \uc788\ub2e4. \ubb3c\uc744 \ub0b4\ub9b0 \ub4a4\uc758 \uae34 \uae38\ub3c4 \ub3c4\uc2dc\uc758 \uc77c\ubd80\ub2e4. 1858\ub144\uc758 \uc774\uc57c\uae30\ub294 \ub0c4\uc0c8\ub098\ub294 \uc61b\ub0a0\uc774\ub77c\ub294 \uc6c3\uc74c\uc73c\ub85c\ub9cc \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \ub0b4 \uc2dc\uc57c\uc5d0\uc11c \uc0ac\ub77c\uc9c4 \uac83\uc744 \ub204\uac00 \uc5b4\ub514\uc5d0\uc11c \ubc1b\uc544 \uc8fc\ub294\uc9c0 \ubb3b\ub294\ub2e4. \ucee4\ud2bc\uc73c\ub85c \ub9c9\uc73c\ub824\ub358 \uac15\uc758 \ubb38\uc81c\ub294 \uacb0\uad6d \ub3c4\uc2dc \uc804\uccb4\uc758 \uc5f0\uacb0 \ubc29\uc2dd\uc744 \ubc14\uafb8\uac8c \ud588\ub2e4."}, {"id": "luther-pamphlets-and-reformation", "title": "\ub8e8\ud130 \u2014 \uc791\uc740 \uc778\uc1c4\ubb3c\uc740 \uc5b4\ub5bb\uac8c \uc720\ub7fd\uc744 \ud754\ub4e4\uc5c8\uc744\uae4c", "summary": "1517\ub144\uc758 \ub17c\uc81c\uc640 \uc778\uc1c4\ubb3c\uc758 \ud655\uc0b0\uc744 \ub530\ub77c \uc885\uad50\uac1c\ud601\uc758 \uc0ac\uc0c1\u00b7\uad8c\uc704\u00b7\uc815\uce58\uac00 \ub9cc\ub098\ub294 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/luther-pamphlets-and-reformation/index.html", "image": "../media/luther-pamphlets-and-reformation.png", "alt": "16\uc138\uae30 \ucd08 \ubd84\uc704\uae30\uc758 \uc778\uc1c4\uc18c\uc5d0\uc11c \uc778\uc1c4\uacf5\uc774 \uc791\uc740 \uc778\uc1c4\ubb3c\uc744 \uc0b4\ud53c\ub294 \uc0c1\uc0c1 \uc18d \uc7a5\uba74.", "text": "\ub8e8\ud130 \u2014 \uc791\uc740 \uc778\uc1c4\ubb3c\uc740 \uc5b4\ub5bb\uac8c \uc720\ub7fd\uc744 \ud754\ub4e4\uc5c8\uc744\uae4c \ud55c \uad50\uc218\uc758 \ub17c\uc7c1\uc774 \uc5ec\ub7ec \ub3c4\uc2dc\uc758 \uc77d\uc744\uac70\ub9ac\uac00 \ub418\uae30\uae4c\uc9c0 1517\ub144\uc758 \ub17c\uc81c\uc640 \uc778\uc1c4\ubb3c\uc758 \ud655\uc0b0\uc744 \ub530\ub77c \uc885\uad50\uac1c\ud601\uc758 \uc0ac\uc0c1\u00b7\uad8c\uc704\u00b7\uc815\uce58\uac00 \ub9cc\ub098\ub294 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc 1517\ub144 \ub3c5\uc77c \ube44\ud150\ubca0\ub974\ud06c\uc758 \uad50\uc218 \ub9c8\ub974\ud2f4 \ub8e8\ud130\ub294 \uad50\ud68c\uc758 \ud55c \uad00\ud589\uc5d0 \ubc18\ub300\ud558\ub294 \ub17c\uc81c\ub4e4\uc744 \uc37c\ub2e4. \uac15\uc758\uc2e4\uacfc \uc131\uc9c1\uc790\ub4e4\uc758 \ud1a0\ub860 \uc548\uc5d0\uc11c \ub05d\ub0a0 \uc218\ub3c4 \uc788\uc5c8\ub358 \uae00\uc774\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \ubcf5\uc0ac\ub41c \uc885\uc774\ub294 \ub2e4\ub978 \ub3c4\uc2dc\ub85c \uc774\ub3d9\ud588\uace0 \ub17c\uc7c1\uc740 \uadf8 \uae00\uc744 \ucc98\uc74c \uc4f4 \uc7a5\uc18c\ubcf4\ub2e4 \ud6e8\uc52c \ub113\uc5b4\uc84c\ub2e4. \uc885\uad50\uac1c\ud601\uc744 \uac70\ub300\ud55c \uc0ac\uc0c1\uacfc \uc804\uc7c1\uc758 \uc774\ub984\uc73c\ub85c \uba3c\uc800 \ub9cc\ub098\uba74 \uc5b4\ub835\uac8c \ub290\uaef4\uc9c4\ub2e4. \uc774\ubc88\uc5d0\ub294 \uc791\uc740 \uc778\uc1c4\ubb3c\uc5d0\uc11c \ucd9c\ubc1c\ud574 \ubcf4\uc790. \uc65c \ud55c \uc218\ub3c4\uc0ac\uc758 \ubb38\uc81c \uc81c\uae30\uac00 \uc774\ub807\uac8c \uba40\ub9ac \ud37c\uc84c\uace0, \uc778\uc1c4\ub41c \uae00\uc740 \uadf8 \uacfc\uc815\uc5d0\uc11c \uc5b4\ub5a4 \uc5ed\ud560\uc744 \ud588\uc744\uae4c. \ub8e8\ud130\uac00 \ubb38\uc81c \uc0bc\uc740 \uac83 \uac00\uc6b4\ub370 \ud558\ub098\ub294 \uc624\ub298\ub0a0 \ud754\ud788 \uba74\uc8c4\ubd80\ub77c\uace0 \ubd80\ub974\ub294 \ub300\uc0ac \uc99d\uc11c\uc758 \ud310\ub9e4\uc600\ub2e4. \uac00\ud1a8\ub9ad\uc758 \uc124\uba85\uc5d0\uc11c\ub294 \uc5f0\uc625\uc5d0\uc11c \uacaa\ub294 \ubc8c\uc744 \uc904\uc774\ub294 \uac83\uacfc \uad00\ub828\ub41c \uc81c\ub3c4\uc600\ub2e4. \ub2e8\uc21c\ud788 \ub3c8\uc744 \ub0b4\uba74 \ubb34\uc2a8 \uc8c4\ub4e0 \uc5c6\uc5b4\uc9c4\ub2e4\ub294 \ud55c \ubb38\uc7a5\uc73c\ub85c \ub2f9\uc2dc \uad50\ub9ac\ub97c \uc694\uc57d\ud558\uba74 \uc815\ud655\ud558\uc9c0 \uc54a\ub2e4. \uadf8\ub7fc\uc5d0\ub3c4 \ub3c8\uc744 \ub0b4\ub294 \ud589\uc704\uac00 \ud68c\uac1c\uc640 \uc2e0\uc559\uc744 \ub300\uc2e0\ud558\ub294 \uac83\ucc98\ub7fc \ubc1b\uc544\ub4e4\uc5ec\uc9c8 \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \ub8e8\ud130\uc5d0\uac8c \ud070 \ubb38\uc81c\uc600\ub2e4. \uad50\uc7ac\ub294 \uc694\ud55c \ud14c\uccbc\uc758 \ud310\ub9e4 \ud65c\ub3d9\uacfc \ub8e8\ud130\uc758 \uad6c\uc6d0\uc5d0 \ub300\ud55c \uace0\ubbfc\uc744 \uc5f0\uacb0\ud55c\ub2e4. \uae08\uc735\uc801 \uac70\ub798\ucc98\ub7fc \ubcf4\uc774\ub294 \ud589\uc704\uc640 \uc601\ud63c\uc758 \ubb38\uc81c\uac00 \uac19\uc740 \uc790\ub9ac\uc5d0\uc11c \ubd80\ub52a\ucce4\ub2e4. \ub8e8\ud130\ub294 \ub300\uc0ac \uc99d\uc11c \ud310\ub9e4\ub97c \ube44\ud310\ud558\ub294 95\uac1c \ub17c\uc81c\ub97c \uc791\uc131\ud588\ub2e4. \uad50\uc7ac\uc5d0 \uc2e4\ub9b0 \uc77c\ubd80 \ub17c\uc81c\uc5d0\ub294 \uac00\ub09c\ud55c \uc0ac\ub78c\uc744 \ub3d5\ub294 \uc77c\uc774 \uc99d\uc11c\ub97c \uc0ac\ub294 \uac83\ubcf4\ub2e4 \ub0ab\ub2e4\ub294 \uc8fc\uc7a5\ub3c4 \ubcf4\uc778\ub2e4. \ub17c\uc7c1\uc758 \uc911\uc2ec\uc5d0\ub294 \ub3c8\uc758 \uc9c0\ucd9c\uacfc \uc2e0\uc559\uc758 \uc2e4\ucc9c\uc744 \uc5b4\ub5bb\uac8c \ud3c9\uac00\ud560\uc9c0\ub77c\ub294 \uc9c8\ubb38\uc774 \uc788\uc5c8\ub2e4. \uc720\uba85\ud55c \uc7a5\uba74\uc740 \uad50\ud68c \ubb38\uc5d0 \ub17c\uc81c\ub97c \ubabb\uc73c\ub85c \ubc15\ub294 \ubaa8\uc2b5\uc774\ub2e4. \ud558\uc9c0\ub9cc \uc774\ubc88 \uc774\uc57c\uae30\uc758 \ucd9c\ubc1c\uc810\uc744 \uadf8 \uadf9\uc801\uc778 \uc7a5\uba74\uc758 \ubaa8\ub4e0 \uc138\ubd80\uc5d0 \uac78 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uae00\uc774 \uc791\uc131\ub418\uace0 \uad50\ud68c \uad00\uacc4\uc790\uc5d0\uac8c \uc804\ub2ec\ub418\uc5c8\uc73c\uba70 \uc778\uc1c4\ub41c \uc0ac\ubcf8\uc73c\ub85c\ub3c4 \ud37c\uc84c\ub2e4\ub294 \uc810\uc774\ub2e4. \ub17c\uc7c1\uc740 \uc77d\uc744 \uc218 \uc788\ub294 \ud615\ud0dc\ub97c \uc5bb\uc5c8\ub2e4. \uc774\ubbf8 \uc720\ub7fd\uc5d0\uc11c \ubc1c\uc804\ud558\ub358 \uc778\uc1c4 \uae30\uc220\uc740 \uac19\uc740 \uae00\uc744 \uc5ec\ub7ec \ubd80 \ub9cc\ub4e4\uc5b4 \uc804\ub2ec\ud558\ub294 \ub370 \ud798\uc744 \ubcf4\ud0f0\ub2e4. \uad50\uc7ac\ub294 \ub8e8\ud130\uc758 \uc800\uc220 \uc218\ucc9c \ubd80\uac00 \uc720\ub7fd\uc5d0\uc11c \uc720\ud1b5\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud55c \uc0ac\ub78c\uc774 \uc9c1\uc811 \uac00\uc11c \ub9d0\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub2e4\ub978 \uacf3\uc758 \ub3c5\uc790\uac00 \uae00\uc744 \ub9cc\ub0a0 \uc218 \uc788\uc5c8\ub2e4. \ubb3c\ub860 \uc778\uc1c4\ud588\ub2e4\uace0 \ub204\uad6c\ub098 \uc989\uc2dc \uac19\uc740 \ub73b\uc73c\ub85c \uc774\ud574\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc77d\uc744 \uc218 \uc788\ub294 \uc0ac\ub78c\uc758 \ubc94\uc704\uc640 \uc5b8\uc5b4, \uc804\ub2ec\uacfc \ud1a0\ub860\uc758 \uad00\uacc4\uac00 \ub0a8\ub294\ub2e4. \uae30\uc220\uc740 \uc0ac\uc0c1\uc744 \ub300\uc2e0 \ub9cc\ub4e0 \uac83\uc774 \uc544\ub2c8\ub77c \uadf8 \uc0ac\uc0c1\uc774 \uc774\ub3d9\ud558\uace0 \ub2e4\uc2dc \ub17c\uc758\ub420 \uc870\uac74\uc744 \ubc14\uafb8\uc5c8\ub2e4. \uc885\uc774\uc758 \uc218\uac00 \ub298\uc5b4\ub09c \uc77c\uacfc \ub17c\uc7c1\uc758 \ubc94\uc704\uac00 \ub113\uc5b4\uc9c4 \uc77c\uc774 \ub9cc\ub0ac\ub2e4. \ub8e8\ud130\ub294 \ucc98\uc74c\ubd80\ud130 \uc0c8\ub85c\uc6b4 \uad50\ud68c\ub97c \ubaa8\ub450 \uc124\uacc4\ud574 \ub193\uace0 \uc2dc\uc791\ud55c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uad50\uc7ac\ub294 \uadf8\uac00 \uad50\ud68c \uad00\ud589\uc758 \uac1c\ud601\uc744 \ubc14\ub790\uc9c0\ub9cc \ub300\uc751 \uacfc\uc815\uc5d0\uc11c \uac08\ub4f1\uc774 \ub354 \ucee4\uc84c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub204\uac00 \uc8c4\uc640 \uad6c\uc6d0\uc5d0 \uad00\ud574 \uc5b4\ub5a4 \uad8c\ud55c\uc744 \uac00\uc9c0\ub294\uc9c0 \ubb3b\ub294 \uc77c\uc740 \uc81c\ub3c4\uc758 \uc911\uc2ec\uc744 \uac74\ub4dc\ub838\ub2e4. 1518\ub144 \uc544\uc6b0\ud06c\uc2a4\ubd80\ub974\ud06c\uc5d0\uc11c \ubb38\ub2f5\uc774 \uc774\ub8e8\uc5b4\uc84c\uace0, \uc8fc\uc7a5\uc744 \ucca0\ud68c\ud558\ub77c\ub294 \uc694\uad6c\ub3c4 \uc774\uc5b4\uc84c\ub2e4. \ub8e8\ud130\uac00 \ubb3c\ub7ec\uc11c\uc9c0 \uc54a\uc790 1521\ub144 \ud30c\ubb38\uc744 \ubc1b\uc558\ub2e4. \uc885\uc774\uc5d0 \uc801\ud78c \ube44\ud310\uc740 \ub2e8\uc21c\ud55c \uac1c\uc778 \uc758\uacac\uc73c\ub85c \ub0a8\uc9c0 \uc54a\uc558\ub2e4. \uae00\uc744 \uc4f4 \uc0ac\ub78c\uc758 \uc885\uad50\uc801 \uc9c0\uc704\uc640 \uadf8\ub97c \ub458\ub7ec\uc2fc \uad8c\ub825 \uad00\uacc4\uae4c\uc9c0 \ubc14\uafb8\uc5c8\ub2e4. \ub8e8\ud130\ub294 \uc2e0\uc559\uacfc \uc131\uc11c\uc758 \uad8c\uc704\ub97c \uac15\uc870\ud558\uba70 \uae30\uc874\uc758 \uad00\ud589\uacfc \uad50\ud669\uc758 \uad8c\uc704\ub97c \ub2e4\uc2dc \ubb3c\uc5c8\ub2e4. \uadf8\uac00 \uc8fc\uc7a5\ud55c \uad6c\uc6d0\uacfc \uc2e0\uc559\uc758 \uad00\uacc4\ub294 \ub2f9\uc2dc\uc758 \uacf5\uc2dd \uac00\ub974\uce68\uacfc \uc911\uc694\ud55c \ucc28\uc774\uac00 \uc788\uc5c8\ub2e4. \uc624\ub298\uc758 \ub3c5\uc790\ub294 \uc5b4\ub290 \ud55c\ucabd\uc744 \ud48d\uc790\uc801\uc778 \ud55c \uc904\ub85c \uc904\uc774\uae30\ubcf4\ub2e4 \uc0ac\ub78c\ub4e4\uc774 \ubb34\uc5c7\uc744 \ub450\uace0 \ub2e4\ud22c\uc5c8\ub294\uc9c0 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uc778\uc1c4\ubb3c\uc758 \ud798\ub3c4 \ubc14\ub85c \uadf8 \uad6c\uccb4\uc801\uc778 \uc9c8\ubb38\uacfc \uc5f0\uacb0\ub418\uc5c8\ub2e4. \uc778\uc1c4\uae30\ub9cc \ub193\uc5ec \uc788\ub2e4\uace0 \uac19\uc740 \uc0ac\uac74\uc774 \uc790\ub3d9\uc73c\ub85c \uc77c\uc5b4\ub098\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ub7ab\ub3d9\uc548 \uc313\uc778 \ubd88\ub9cc\uacfc \uc2e0\uc559\uc758 \uace0\ubbfc, \uc5b4\ub5a4 \uc124\uba85\uc5d0 \uadc0\ub97c \uae30\uc6b8\uc77c \uc900\ube44\uac00 \ub418\uc5b4 \uc788\ub358 \uc0ac\ub78c\ub4e4\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \uae30\uc220\uacfc \uc2dc\ub300\uc758 \uc870\uac74\uc774 \ub9cc\ub09c \uac83\uc774\ub2e4. \uc885\uad50\uac1c\ud601\uc740 \uad50\ud68c\uc640 \uac1c\uc778\uc758 \uad00\uacc4\ub9cc \ubc14\uafbc \uac83\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ub3c5\uc77c \uc9c0\uc5ed\uc758 \uc81c\ud6c4\ub4e4\uc5d0\uac8c \uad50\ud669\uc758 \uad8c\uc704\uc640 \uc0c8\ub85c\uc6b4 \uc2e0\uc559\uc758 \uc120\ud0dd\uc740 \uc815\uce58\uc801 \ubb38\uc81c\uc774\uae30\ub3c4 \ud588\ub2e4. \uad50\uc7ac\ub294 \ud1b5\uce58\uc790\ub4e4\uc774 \uc0c8 \uc885\uad50\ub97c \ubc1b\uc544\ub4e4\uc774\uba70 \uc790\uc2e0\uc758 \uad8c\ud55c\uacfc \uc5f0\uacb0\ud55c \uacfc\uc815\uc744 \uc124\uba85\ud55c\ub2e4. \ub530\ub77c\uc11c \ub17c\uc7c1\uc774 \ud37c\uc9c4 \uc77c\uc744 \ubaa8\ub450 \uc790\uc720\ub86d\uac8c \uc77d\uace0 \uace0\ub978 \uac1c\uc778\ub4e4\uc758 \ud569\uc758\ub85c\ub9cc \ubcfc \uc218\ub294 \uc5c6\ub2e4. \ub4a4\uc5d0\ub294 \ud1b5\uce58\uc790\uac00 \uc120\ud0dd\ud55c \uc885\uad50\ub97c \uc2e0\ubbfc\uc774 \ub530\ub77c\uc57c \ud558\ub294 \uc870\uac74\ub3c4 \ub098\ud0c0\ub0ac\ub2e4. \uc791\uc740 \uae00\uc774 \uacf5\uc801\uc778 \uc81c\ub3c4\uc5d0 \ub4e4\uc5b4\uac08 \ub54c \ucc98\uc74c\uc758 \uc9c8\ubb38\uacfc \ub2e4\ub978 \uad8c\ub825\uc758 \ubb38\uc81c\uac00 \ub354\ud574\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 16\uc138\uae30 \ucd08\uc758 \ubd84\uc704\uae30\ub97c \ub5a0\uc62c\ub9ac\ub294 \uc0c1\uc0c1 \uc18d \uc778\uc1c4\uc18c\ub2e4. \uc2e4\uc81c \ub8e8\ud130\uc758 \ucc45\uc744 \ucc0d\ub358 \uc7a5\uc18c\uc640 \uc7a5\ube44, \ud2b9\uc815 \uc778\ubb3c\uc744 \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uae00\uc744 \uc870\ud310\ud558\uace0 \uc885\uc774\uc5d0 \uc62e\uae30\uace0 \uc313\uc544 \ub450\ub294 \ubb3c\ub9ac\uc801\uc778 \uc791\uc5c5\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc0ac\uc0c1\uc758 \uc5ed\uc0ac\uc5d0\uc11c\ub294 \uae00\uc744 \uc4f4 \uc720\uba85\ud55c \uc0ac\ub78c\ub9cc \uae30\uc5b5\ud558\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uae00\uc774 \uba40\ub9ac \uac00\ub824\uba74 \ub9cc\ub4dc\ub294 \uc190\uacfc \uc62e\uae30\ub294 \uae38, \uc77d\uace0 \uc804\ud558\ub294 \uc0ac\ub78c\ub4e4\uc774 \ud544\uc694\ud558\ub2e4. \uc778\uc1c4\ubb3c\uc740 \uc0dd\uac01\uc758 \ub0b4\uc6a9\uacfc \uadf8\uac83\uc744 \uc774\ub3d9\uc2dc\ud0a4\ub294 \uc791\uc5c5\uc774 \ud568\uaed8 \uc774\ub8e8\uc5b4 \ub0b8 \ubb3c\uac74\uc774\uc5c8\ub2e4. \ub8e8\ud130\uc758 \uae00\uc774 \uc720\ub7fd\uc744 \ud754\ub4e0 \uc774\uc720\ub97c \uc778\uc1c4\uae30\uc758 \ubc1c\uba85 \ud558\ub098\ub85c \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uac19\uc740 \ub17c\uc7c1\uc744 \uc5ec\ub7ec \uacf3\uc5d0\uc11c \ub9cc\ub0a0 \uc218 \uc788\uac8c \ud55c \ub9e4\uccb4\uc758 \uc5ed\ud560\uc740 \ubd84\uba85\ud558\ub2e4. \ud55c \ub3c4\uc2dc\uc758 \ubb38\ub2f5\uc774 \ub2e4\ub978 \ub3c4\uc2dc \uc0ac\ub78c\ub4e4\uc758 \ub300\ud654\uc5d0 \ub4e4\uc5b4\uac08 \uc218 \uc788\uc5c8\ub2e4. \uc624\ub798\ub41c \uc791\uc740 \ucc45\uc790\ub97c \ubcf4\uba74 \uadf8 \uc548\uc758 \uc8fc\uc7a5\uacfc \ud568\uaed8 \uadf8 \ucc45\uc790\uac00 \ub204\uad6c\uc758 \uc190\uc744 \uac70\uccd0 \uc5b4\ub514\ub85c \uac14\uc744\uc9c0\ub3c4 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc885\uad50\uac1c\ud601\uc758 \uc774\uc57c\uae30\ub294 \uc0ac\uc0c1\uc774 \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc774\ub294\uc9c0\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\uc774\uae30\ub3c4 \ud558\ub2e4. \ub8e8\ud130\uc758 \uc778\uc1c4\ubb3c\uc740 \uc0dd\uac01\uc758 \ud798\uacfc \uadf8\uac83\uc744 \ud37c\ub728\ub9ac\ub294 \uae30\uc220\uc774 \ub9cc\ub09c \uc21c\uac04\uc744 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "machu-picchu-terraces-stone-and-landscape", "title": "\ub9c8\ucd94\ud53d\ucd94 \u2014 \uc0b0 \uc704\uc758 \ub3c4\uc2dc\ub294 \ub3cc\ub2f4\ub9cc\uc73c\ub85c \uc11c \uc788\uc9c0 \uc54a\uc558\ub2e4", "summary": "\uc0b0\uc758 \uacbd\uc0ac\uc640 \ud14c\ub77c\uc2a4, \ub3cc\ub2f4\uacfc \ucc3d, \uc9c0\uc5ed \uc548\ub0b4\uc640 \uc61b \uc0ac\uc9c4\uc73c\ub85c \uc720\uc801\uc758 \uc5ec\ub7ec \uce35\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/machu-picchu-terraces-stone-and-landscape/index.html", "image": "../media/machu-picchu-terraces-stone-and-landscape.jpg", "alt": "\uc0b0 \uc0ac\uc774\uc5d0 \ud14c\ub77c\uc2a4\uc640 \uc11d\uc870 \uac74\ucd95\uc774 \ud3bc\uccd0\uc9c4 \ub9c8\ucd94\ud53d\ucd94\uc758 \ucd08\uae30 \uc870\uc0ac \uc2dc\uae30 \uc0ac\uc9c4", "text": "\ub9c8\ucd94\ud53d\ucd94 \u2014 \uc0b0 \uc704\uc758 \ub3c4\uc2dc\ub294 \ub3cc\ub2f4\ub9cc\uc73c\ub85c \uc11c \uc788\uc9c0 \uc54a\uc558\ub2e4 \ud14c\ub77c\uc2a4\uc640 \uae38, \uc11d\uc870\uc640 \ucd08\uae30 \uc870\uc0ac \uae30\ub85d\uc73c\ub85c \uc0b0\uc758 \ub3c4\uc2dc \uc77d\uae30 \uc0b0\uc758 \uacbd\uc0ac\uc640 \ud14c\ub77c\uc2a4, \ub3cc\ub2f4\uacfc \ucc3d, \uc9c0\uc5ed \uc548\ub0b4\uc640 \uc61b \uc0ac\uc9c4\uc73c\ub85c \uc720\uc801\uc758 \uc5ec\ub7ec \uce35\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uac00\ud30c\ub978 \uc0b0\uacfc \uacc4\uace1 \uc0ac\uc774\uc5d0 \uacc4\ub2e8\uc2dd \ubc2d\uacfc \ub3cc \uac74\ucd95\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ub9c8\ucd94\ud53d\ucd94\uc758 \ud48d\uacbd\uc740 \ub108\ubb34 \uac15\ub82c\ud574 \ub3c4\uc2dc\uac00 \uc8fc\ubcc0 \uc790\uc5f0\uc5d0\uc11c \ub530\ub85c \ub5a0 \uc788\ub294 \uac83\ucc98\ub7fc \ubcf4\uc774\uae30\ub3c4 \ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc774\uacf3\uc744 \uc9c0\ud0f1\ud55c \uac83\uc740 \uac74\ubb3c\uc758 \ubcbd\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc9c0\ud615\uacfc \uae38, \ubb3c\uacfc \uacbd\uc791\uc758 \uc870\uac74\uc744 \ud568\uaed8 \uc77d\uc73c\uba74 \uc720\uc801\uc758 \ubaa8\uc2b5\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ub9c8\ucd94\ud53d\ucd94\ub294 \uc0b0\uc758 \ub192\uc740 \uc790\ub9ac\uc5d0 \uc788\uc9c0\ub9cc \uc8fc\ubcc0\uacfc \uc644\uc804\ud788 \ub2e8\uc808\ub41c \uc12c\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uae38\uc744 \ub530\ub77c \uc624\ub974\uace0 \uacc4\uace1\uc744 \uac74\ub108\uc57c \ub3c4\ucc29\ud560 \uc218 \uc788\ub2e4. \uba40\ub9ac\uc11c \ubcf8 \uc808\uacbd\uacfc \uc2e4\uc81c\ub85c \uc811\uadfc\ud558\ub294 \uc0ac\ub78c\uc758 \uacbd\ud5d8\uc740 \ub2e4\ub974\ub2e4. \uc704\uce58\ub294 \uc544\ub984\ub2e4\uc6b4 \ubc30\uacbd\uc774\uba74\uc11c \uc774\ub3d9\uacfc \uacf5\uae09\uc758 \uc870\uac74\uc774\ub2e4. \ub3c4\uc2dc\ub97c \uc774\ud574\ud560 \ub54c\uc5d0\ub294 \uac74\ubb3c \ubaa9\ub85d\uc744 \uc678\uc6b0\uae30 \uc804\uc5d0 \uadf8\uacf3\uae4c\uc9c0 \ubb34\uc5c7\uc774 \uc5b4\ub5bb\uac8c \uc624\uac14\uc744\uc9c0 \ubb3c\uc5b4\ubcfc \uc218 \uc788\ub2e4. \uc0ac\ub78c\uacfc \uc7ac\ub8cc, \uba39\uc744 \uac83\uc758 \uc774\ub3d9\uc774 \ud544\uc694\ud588\ub2e4. \uc624\ub298\uc758 \uc720\uba85\ud55c \uc0ac\uc9c4\uc740 \uadf8 \uad00\uacc4 \uc911 \ud55c \uc2dc\uc810\uacfc \ubc29\ud5a5\uc744 \uace0\uc815\ud574 \ubcf4\uc5ec \uc900\ub2e4. \ube44\ud0c8\uc744 \ub530\ub77c \ubc18\ubcf5\ub418\ub294 \ud14c\ub77c\uc2a4\ub294 \ud48d\uacbd\uc758 \uaddc\uce59\uc801\uc778 \ubb34\ub2ac\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uc0b0\uc758 \uacbd\uc0ac\ub97c \ub098\ub204\uace0 \ub545\uc744 \uc774\uc6a9\ud558\ub294 \ubc29\uc2dd\uacfc \uc5f0\uacb0\ub41c\ub2e4. \ud3c9\uc9c0\uac00 \uc801\uc740 \uacf3\uc5d0\uc11c \uc5b4\ub5a4 \uacf5\uac04\uc744 \ud655\ubcf4\ud560\uc9c0\uc5d0 \uad00\ud55c \uc120\ud0dd\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \ud14c\ub77c\uc2a4\uac00 \uc5b8\uc81c\ub098 \uac19\uc740 \uc791\ubb3c\uc744 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uae38\ub800\ub2e4\uace0 \ub2e8\uc815\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uad6c\uc870\uac00 \ub545\uc744 \uc9c0\ud0f1\ud558\ub294 \uc5ed\ud560\uacfc \uacbd\uc791\uc758 \uac00\ub2a5\uc131\uc740 \ud568\uaed8 \uac80\ud1a0\ud574\uc57c \ud55c\ub2e4. \ud55c\ub208\uc5d0 \ubcf4\uc774\ub294 \ubaa8\uc591\uc774 \uc5ec\ub7ec \uae30\ub2a5\uacfc \uc2dc\uac04\uc744 \uac00\uc9c8 \uc218 \uc788\ub2e4\ub294 \uc810\uc744 \uae30\uc5b5\ud560 \ud544\uc694\uac00 \uc788\ub2e4. \ub9c8\ucd94\ud53d\ucd94\uc758 \uc11d\uc870 \uac74\ucd95\uc5d0\ub294 \ub2e4\ub4ec\uc740 \ub3cc\uc758 \ub9de\ubb3c\ub9bc\uc774 \ub208\uc5d0 \ub748\ub2e4. \ud558\uc9c0\ub9cc \uc720\uc801\uc758 \ubaa8\ub4e0 \ubcbd\uc774 \uac19\uc740 \ubc29\uc2dd\uacfc \uc218\uc900\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc9c4 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac74\ubb3c\uc758 \uc704\uce58\uc640 \ubaa9\uc801, \uc81c\uc791\uc758 \ucc28\uc774\ub97c \ube44\uad50\ud574\uc57c \ud55c\ub2e4. \uac00\uc7a5 \uc720\uba85\ud55c \ubcbd \ud55c \ubd80\ubd84\uc744 \uc804\uccb4\uc758 \uc720\uc77c\ud55c \uae30\uc900\uc73c\ub85c \uc0bc\uae30 \uc27d\ub2e4. \ud2c8\uacfc \ubaa8\uc11c\ub9ac\ub97c \uc0b4\ud53c\uba74 \ub3cc\uc744 \uc900\ube44\ud558\uace0 \ubc30\uce58\ud55c \uc190\uc758 \ud310\ub2e8\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc644\uc131\ub41c \uacb0\uacfc\ub97c \uc2e0\ube44\ub85c\uc6b4 \uae30\uc220\uc774\ub77c\ub294 \ub9d0\ub85c\ub9cc \ubd80\ub974\uba74 \uc2e4\uc81c \uc791\uc5c5\uc758 \uc9c8\ubb38\uc774 \uc904\uc5b4\ub4e0\ub2e4. \uc7ac\ub8cc\uc640 \uc9c0\ud615\uc758 \uc870\uac74 \uc18d\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ub9de\ucd94\uace0 \uc313\uc558\ub294\uc9c0\ub97c \ubb3b\ub294 \ud3b8\uc774 \uc5ed\uc0ac\uc5d0 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \uc138 \ucc3d\uc774 \uc788\ub294 \uc11d\uc870 \uac74\ucd95\uc740 \ud558\uc774\ub7fc \ube59\uc5c4\uc758 \ucc45\uc5d0\ub3c4 \uc790\uc138\ud788 \uc18c\uac1c\ub41c\ub2e4. \ucc3d\uc740 \ube5b\uc774 \ub4e4\uc5b4\uc624\ub294 \uad6c\uba4d\uc774\uba74\uc11c \ubc14\uae65\uc744 \ubc14\ub77c\ubcf4\ub294 \ud2c0\uc774\ub2e4. \ub3cc\uc758 \ub0b4\ubd80 \uacf5\uac04\uacfc \uba40\ub9ac \uc788\ub294 \uc0b0\uc758 \uad00\uacc4\ub97c \ub9cc\ub4e0\ub2e4. \uac74\ucd95\uc774 \uc790\uc5f0\uc744 \uac00\ub9ac\ub294 \uac83\ub9cc\uc774 \uc544\ub2c8\ub77c \ud2b9\uc815\ud55c \ubc29\uc2dd\uc73c\ub85c \ubcf4\uac8c \ud55c\ub2e4. \uadf8 \uae30\ub2a5\uacfc \uc758\ubbf8\ub97c \ubaa8\ub450 \ud655\uc2e4\ud788 \uc54c \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc61b \uc5f0\uad6c\uc790\uc758 \uc774\ub984 \ubd99\uc774\uae30\uc640 \ucd94\uc815\uc740 \uc2e4\uc81c\ub85c \ub0a8\uc740 \ucc3d\uacfc \ubcbd\uc758 \uad00\ucc30\uacfc \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc544\ub984\ub2e4\uc6b4 \uc7a5\uba74\uc744 \uc774\ud574\ud558\ub824\ub294 \ub9c8\uc74c\uc774 \ube48\uce78\uc744 \uc131\uae09\ud558\uac8c \uc644\uc131\ud558\uc9c0 \uc54a\uac8c \ud558\ub294 \ud0dc\ub3c4\ub3c4 \ud544\uc694\ud558\ub2e4. \ube59\uc5c4\uc758 1911\ub144 \ubc29\ubb38 \uae30\ub85d\uc5d0\ub294 \uc9c0\uc5ed \uc8fc\ubbfc\uacfc \uc548\ub0b4\uc758 \uc5ed\ud560\uc774 \ub098\ud0c0\ub09c\ub2e4. \uadf8\uac00 \uae38\uc744 \uc54c\uace0 \ud63c\uc790 \ube48 \uc138\uacc4\ub97c \ucc98\uc74c \uc5f0 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc678\ubd80 \uc5f0\uad6c\uc790\uc758 \uae30\ub85d\uc774 \ub110\ub9ac \ud37c\uc9c4 \uacfc\uc815\uacfc \uc7a5\uc18c\ub97c \uc54c\uace0 \uc788\ub358 \uc0ac\ub78c\ub4e4\uc758 \uc9c0\uc2dd\uc740 \ub2e4\ub978 \uce35\uc758 \uc5ed\uc0ac\ub2e4. \ubc1c\uacac\uc774\ub77c\ub294 \ub2e8\uc5b4\ub97c \uc0ac\uc6a9\ud560 \ub54c\uc5d0\ub294 \ub204\uad6c\uc5d0\uac8c \uc0c8\ub85c \uc54c\ub824\uc84c\ub294\uc9c0 \ubc1d\ud600 \ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \uc720\uc801\uc5d0 \ub3c4\ucc29\ud55c \uc0ac\ub78c\ub9cc\ud07c \uadf8 \uae38\uc744 \uc54c\ub824 \uc900 \uc0ac\ub78c\ub3c4 \uad00\uacc4 \uc548\uc5d0 \uc788\uc5c8\ub2e4. \uc0ac\uc9c4\uacfc \ucc45\uc758 \uc800\uc790 \uc774\ub984\ub9cc\uc73c\ub85c \ud604\uc7a5 \uc9c0\uc2dd\uc758 \ubaa8\ub4e0 \ucd9c\ucc98\ub97c \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \ucd08\uae30 \ubc29\ubb38 \uae30\ub85d\uc5d0\uc11c \uc8fc\ubcc0\uc758 \uacbd\uc791\uacfc \uc0ac\ub78c\uc758 \uc0dd\ud65c\uc744 \uc0b4\ud53c\ub294 \uac83\ub3c4 \uc911\uc694\ud558\ub2e4. \uace0\ub300 \uac74\ucd95\uc774 \ub0a8\uc544 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8 \uc7a5\uc18c\uac00 \uc774\ud6c4 \uc5b4\ub290 \ub204\uad6c\uc640\ub3c4 \uad00\uacc4\ub97c \ub9fa\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc8fc\uc7a5\uc740 \ub2e4\ub974\ub2e4. \ud55c \uc2dc\ub300\uc758 \ub3c4\uc2dc \uae30\ub2a5\uc774 \ub05d\ub09c \ub4a4\uc5d0\ub3c4 \ub545\uc744 \uc774\uc6a9\ud558\uace0 \uae38\uc744 \uc544\ub294 \uc0b6\uc740 \uc774\uc5b4\uc9c8 \uc218 \uc788\ub2e4. \uc774 \uad6c\ubd84\uc744 \ud558\uc9c0 \uc54a\uc73c\uba74 \ubc1c\uacac\uc790\ub294 \ubaa8\ub4e0 \uc9c0\uc2dd\uc744 \ub9cc\ub4e0 \uc0ac\ub78c\ucc98\ub7fc \ucee4\uc9c0\uace0 \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc740 \uc0ac\uc9c4\uc758 \ubc30\uacbd\uc73c\ub85c \uc791\uc544\uc9c4\ub2e4. \ube59\uc5c4\uc758 \uae30\ub85d\uc5d0\uc11c \uc548\ub0b4\uc640 \ub3c4\uc6c0\uc758 \ud754\uc801\uc744 \ucc3e\uc544 \uc77d\ub294 \uc77c\uc740 \uc720\uba85\ud55c \uc774\ub984\uc744 \uc9c0\uc6b0\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc870\uc0ac\uc640 \ucd9c\ud310\uc774 \uac00\ub2a5\ud588\ub358 \uad00\uacc4\ub97c \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \uc54c\uc544\ubcf4\ub294 \uc77c\uc774\ub2e4. \uac19\uc740 \uc720\uc801\uc744 \ubcf4\ub354\ub77c\ub3c4 \uae30\ub85d\uc758 \uc8fc\uc5b4\ub97c \ub113\ud788\uba74 \uc0b0 \uc704\uc758 \uacf5\uac04\uc5d0 \ub300\ud55c \uc774\ud574\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \ud48d\uacbd\uc744 \uc54c\uac8c \ub41c \uacfc\uc815 \uc5ed\uc2dc \uc7a5\uc18c\uc758 \uc5ed\uc0ac \uc548\uc5d0 \ud3ec\ud568\ub41c\ub2e4. 1922\ub144\uc5d0 \ucd9c\ud310\ub41c \u300e\uc789\uce74 \ub79c\ub4dc\u300f\uc758 \uc0ac\uc9c4\uc740 \ucd08\uae30 \uc870\uc0ac \ub54c \uc720\uc801\uc744 \uc5b4\ub5bb\uac8c \ubcf4\uc558\ub294\uc9c0 \uc54c\ub824 \uc900\ub2e4. \uc9c0\uae08\uc758 \uc815\ube44\ub41c \ud48d\uacbd\uacfc \ube44\uad50\ud560 \ub2e8\uc11c\uac00 \ub418\uc9c0\ub9cc, \uadf8 \uc0ac\uc9c4\ub3c4 \ucd2c\uc601\uc790\uac00 \uace8\ub77c \ubcf8 \uc7a5\uba74\uc774\ub2e4. \ube5b\uacfc \uac01\ub3c4, \uc798 \ubcf4\uc774\uac8c \ud55c \ubd80\ubd84\uc5d0 \uc120\ud0dd\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ube59\uc5c4\uc774 \uc81c\uc2dc\ud55c \uc720\uc801\uc758 \uc815\uccb4\uc640 \ud2b9\uc815 \uacf5\uac04\uc758 \uae30\ub2a5\uc744 \uc624\ub298\uc758 \uc720\uc77c\ud55c \ub2f5\uc73c\ub85c \ubc1b\uc544\ub4e4\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \ud6c4\ub300 \uc5f0\uad6c\uc640 \ub2e4\ub978 \ud574\uc11d\uc774 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc5ed\uc0ac \uc790\ub8cc\ub294 \uace0\ub300\uc758 \ud754\uc801\ubfd0 \uc544\ub2c8\ub77c \uc870\uc0ac\uc790\uac00 \ubb34\uc5c7\uc744 \uc54c\uace0 \uc2f6\uc5b4 \ud588\ub294\uc9c0\ub3c4 \ubcf4\uc5ec \uc900\ub2e4. \ub9c8\ucd94\ud53d\ucd94\ub97c \ub2e4\uc2dc \ubcfc \ub54c\uc5d0\ub294 \ub3cc\ub2f4\uc758 \uc815\uad50\ud568\uc5d0\uc11c \uc2dc\uc791\ud574 \ud14c\ub77c\uc2a4\uc640 \uae38, \uc8fc\ubcc0 \uc0b0\uc73c\ub85c \uc2dc\uc120\uc744 \uc62e\uaca8 \ubcf4\uc790. \ub3c4\uc2dc\uac00 \uc9c0\ud615\uc744 \uc5b4\ub5bb\uac8c \ub098\ub204\uace0 \uc774\uc6a9\ud588\ub294\uc9c0 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc790\uc5f0\uacfc \uc778\uacf5\uc744 \uc644\uc804\ud788 \ubd84\ub9ac\ud55c \ub450 \ub369\uc5b4\ub9ac\ub85c \ubcf4\ub294 \ub300\uc2e0 \uadf8 \uad00\uacc4\ub97c \uc77d\ub294 \uac83\uc774\ub2e4. \uc774 \uc720\uc801\uc758 \uc778\uc0c1\uc740 \uc544\ub984\ub2e4\uc6b4 \uc704\uce58\uc5d0 \uc138\uc6b4 \uac74\ucd95\uc774\ub77c\ub294 \ub9d0\ubcf4\ub2e4 \ub113\ub2e4. \uc0b0 \uc704\uc758 \uc0dd\ud65c\uc744 \uac00\ub2a5\ud558\uac8c \ud558\ub294 \uc5ec\ub7ec \uc870\uac74\uc774 \uacf5\uac04\uc5d0 \uacb9\uccd0 \uc788\ub2e4. \ub545\uc744 \uc774\uc6a9\ud558\ub294 \ubc29\ubc95\uacfc \ub3cc\uc744 \ub2e4\ub8e8\ub294 \ubc29\ubc95\uc774 \ud568\uaed8 \uc0dd\ud65c\uc758 \uc790\ub9ac\ub97c \ub9cc\ub4e4\uc5c8\ub2e4. \ub3cc\ub2f4\ub9cc \ubcf4\uace0 \ub05d\ub0b4\uc9c0 \uc54a\uc744 \ub54c \ub9c8\ucd94\ud53d\ucd94\ub294 \uba40\ub9ac \ub5a0 \uc788\ub294 \uc2e0\ube44\ub85c\uc6b4 \ub3c4\uc2dc\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc774 \ub545\uacfc \uad00\uacc4\ub97c \ub9fa\uc740 \uad6c\uccb4\uc801\uc778 \uc7a5\uc18c\ub85c \ub3cc\uc544\uc628\ub2e4."}, {"id": "magna-carta-king-and-written-promise", "title": "\ub9c8\uadf8\ub098 \uce74\ub974\ud0c0 \u2014 \uc655\uc758 \uc57d\uc18d\uc744 \ubb38\uc11c\ub85c \ub0a8\uae34 \uc774\uc720", "summary": "\uc874 \uc655\uacfc \uc2e0\ud558\ub4e4\uc758 \uac08\ub4f1\uc5d0\uc11c \ucd9c\ubc1c\ud574 \ub9c8\uadf8\ub098 \uce74\ub974\ud0c0\uc758 \uc790\uc720\uc778 \uc870\ud56d\uacfc \uadf8 \ud55c\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/magna-carta-king-and-written-promise/index.html", "image": "../media/magna-carta-king-and-written-promise.png", "alt": "\uc911\uc138 \uadc0\uc871\uacfc \uc131\uc9c1\uc790\uac00 \uc778\uc7a5\uc774 \ub2ec\ub9b0 \ubb38\uc11c\ub97c \uc0b4\ud53c\ub294 \uc0c1\uc0c1 \uc7a5\uba74", "text": "\ub9c8\uadf8\ub098 \uce74\ub974\ud0c0 \u2014 \uc655\uc758 \uc57d\uc18d\uc744 \ubb38\uc11c\ub85c \ub0a8\uae34 \uc774\uc720 1215\ub144\uc758 \ud569\uc758\uc640 \uc624\ub298\uc758 \uad8c\ub9ac \uc0ac\uc774\uc5d0 \ub193\uc778 \uac70\ub9ac \uc874 \uc655\uacfc \uc2e0\ud558\ub4e4\uc758 \uac08\ub4f1\uc5d0\uc11c \ucd9c\ubc1c\ud574 \ub9c8\uadf8\ub098 \uce74\ub974\ud0c0\uc758 \uc790\uc720\uc778 \uc870\ud56d\uacfc \uadf8 \ud55c\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc655\uc774 \uba85\ub839\ud558\uba74 \ubaa8\ub450 \ub530\ub77c\uc57c \ud588\uc744 \uac83 \uac19\uc740 \uc911\uc138\uc5d0\ub3c4 \uad8c\ud55c\uc744 \ub458\ub7ec\uc2fc \ub2e4\ud23c\uc774 \uc788\uc5c8\ub2e4. \uc2e0\ud558\uc640 \uad50\ud68c\ub294 \uc624\ub798 \uc9c0\ucf1c \uc628 \uad8c\ub9ac\ub97c \uc8fc\uc7a5\ud588\uace0 \uc655\uc5d0\uac8c \uc57d\uc18d\uc744 \uc694\uad6c\ud588\ub2e4. \uadf8 \uc57d\uc18d\uc744 \ub9d0\ub85c\ub9cc \ub450\uc9c0 \uc54a\uace0 \ubb38\uc11c\uc5d0 \ub0a8\uae30\uba74 \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc9c8\uae4c. 1215\ub144 \uc601\uad6d\uc758 \uc874 \uc655\uacfc \uc5f0\uacb0\ub418\ub294 \ub9c8\uadf8\ub098 \uce74\ub974\ud0c0\ub294 \uc774\ub7f0 \uc9c8\ubb38\uc73c\ub85c \uc77d\uae30 \uc88b\uc740 \uc790\ub8cc\ub2e4. \uc624\ub298\ub0a0 \uc790\uc720\uc640 \ubc95\uc758 \uc0c1\uc9d5\uc73c\ub85c \uc790\uc8fc \ub4f1\uc7a5\ud558\uc9c0\ub9cc \ucc98\uc74c\ubd80\ud130 \ubaa8\ub4e0 \uc0ac\ub78c\uc5d0\uac8c \uac19\uc740 \uad8c\ub9ac\ub97c \uc900 \uc644\uc131\ub41c \uc120\uc5b8\ubb38\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uadf8 \uc0ac\uc774\uc758 \uac70\ub9ac\ub97c \uc0b4\ud3b4\ubcf4\ub294 \uac83\uc774 \uc774 \ubb38\uc11c\ub97c \ub354 \ud765\ubbf8\ub86d\uac8c \ub9cc\ub4e0\ub2e4. \uc911\uc138 \uc601\uad6d\uc5d0\uc11c \uc655\uc740 \uc5ec\ub7ec \uc2e0\ud558\uc640 \uad50\ud68c\uac00 \uac00\uc9c4 \uad8c\ub9ac\uc640 \uad00\uacc4 \uc18d\uc5d0 \uc788\uc5c8\ub2e4. \uad50\uc7ac\ub294 \uc655\uacfc \ubd09\uc2e0 \uc0ac\uc774\uc758 \uc758\ubb34\uc640 \uad8c\ud55c\uc774 \uc624\ub79c \uad00\ud589\uc73c\ub85c \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubd09\uc2e0\uc740 \uc655\uacfc \uac19\uc740 \uc0c1\uc704 \uc9c0\ubc30\uc790\uc5d0\uac8c \uc758\ubb34\ub97c \uc9c0\ub294 \ub300\uc2e0 \uc77c\uc815\ud55c \uc9c0\uc704\uc640 \uad8c\ub9ac\ub97c \uac00\uc9c4 \uc0ac\ub78c\uc774\uc5c8\ub2e4. \ub530\ub77c\uc11c \ubaa8\ub4e0 \uc81c\ub3c4\uac00 \uc655\uc758 \uae30\ubd84\ub9cc\uc73c\ub85c \ub9e4\uc77c \uc0c8\ub85c \ub9cc\ub4e4\uc5b4\uc84c\ub2e4\uace0 \uc0c1\uc0c1\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ubb34\uc5c7\uc774 \uc815\ub2f9\ud55c \uc694\uad6c\uc774\uba70 \uc5b4\ub514\uae4c\uc9c0 \uc751\ud574\uc57c \ud558\ub294\uc9c0\ub97c \ub450\uace0 \ud611\uc0c1\uacfc \ucda9\ub3cc\uc774 \uc788\uc5c8\ub2e4. \ub9c8\uadf8\ub098 \uce74\ub974\ud0c0\ub294 \uc774\ub7f0 \uad00\uacc4\ub97c \ub2e4\uc2dc \ud655\uc778\ud558\uace0 \uc77c\ubd80\ub97c \uba85\ud655\ud788 \ud558\ub824\ub294 \uac08\ub4f1 \uc18d\uc5d0\uc11c \ub098\uc654\ub2e4. \uc874 \uc655\uc740 \uad50\ud669\uacfc\uc758 \uad00\uacc4\uc5d0\uc11c\ub3c4 \uc5b4\ub824\uc6c0\uc744 \uacaa\uc5c8\uace0 \uacb0\uad6d \uad50\ud669\uc758 \uad8c\uc704\ub97c \ubc1b\uc544\ub4e4\uc5ec\uc57c \ud588\ub2e4. \uad50\uc7ac\ub294 \uc774\ub7f0 \uc0c1\ud669\uc5d0\uc11c \uc655\uc758 \uc2e0\ud558\ub4e4\uc774 \uc790\uc2e0\uc758 \uad8c\ub9ac\ub97c \ub354 \uac15\ud558\uac8c \uc694\uad6c\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc655\uc758 \ud798\uc774 \ud754\ub4e4\ub9b0 \ub54c\ub294 \ub2e4\ub978 \uc138\ub825\uc774 \uae30\uc874\uc758 \uc57d\uc18d\uc744 \ud655\uc778\ubc1b\uc744 \uae30\ud68c\uac00 \ub418\uc5c8\ub2e4. 1215\ub144 \ubb38\uc11c\uc5d0\ub294 \uad50\ud68c\uc758 \uad8c\ub9ac\uc640 \uc790\uc720\ub97c \ud6fc\uc190\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \ub0b4\uc6a9\ub3c4 \ub4e4\uc5b4\uac14\ub2e4. \uc9c0\uae08\uc758 \ub3c5\uc790\uac00 \uad6d\uac00\uc640 \uac1c\uc778\uc758 \uad00\uacc4\ub9cc \ub5a0\uc62c\ub9ac\uba74 \uc774 \ubd80\ubd84\uc774 \ub0af\uc124 \uc218 \uc788\ub2e4. \ub2f9\uc2dc\uc5d0\ub294 \uad50\ud68c\uac00 \ub3c5\uc790\uc801\uc778 \uad8c\ud55c\uc744 \uac00\uc9c4 \uc911\uc694\ud55c \uc815\uce58\uc801 \uc8fc\uccb4\uc600\ub2e4\ub294 \uc810\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uad50\uc7ac\uac00 \uc778\uc6a9\ud558\ub294 \uc720\uba85\ud55c \uc870\ud56d\uc740 \uc790\uc720\uc778\uc774 \uc815\ub2f9\ud55c \uc808\ucc28 \uc5c6\uc774 \ubd99\uc7a1\ud788\uac70\ub098 \uc7ac\uc0b0\uacfc \uc9c0\uc704\ub97c \ube7c\uc557\uaca8\uc11c\ub294 \uc548 \ub41c\ub2e4\ub294 \ucde8\uc9c0\ub2e4. \uadf8\uc640 \ub3d9\ub4f1\ud55c \uc774\ub4e4\uc758 \ud569\ubc95\uc801\uc778 \ud310\ub2e8\uc774\ub77c\ub294 \uae30\uc900\ub3c4 \uc81c\uc2dc\ub41c\ub2e4. \uc9c0\ubc30\uc790\uc758 \ud798\uc744 \ud589\uc0ac\ud560 \ub54c \ub530\ub77c\uc57c \ud560 \uc57d\uc18d\uc744 \uc801\uc5b4 \ub454 \uac83\uc774\ub2e4. \uc774 \ub9d0\uc740 \uc624\ub298\uc758 \ub3c5\uc790\uc5d0\uac8c\ub3c4 \uc758\ubbf8 \uc788\uac8c \ub4e4\ub9b0\ub2e4. \ub2e4\ub9cc \ubb38\uc11c \uc18d \uc790\uc720\uc778\uc774\ub77c\ub294 \ubc94\uc8fc\ub97c \uc9c0\uae08\uc758 \ubaa8\ub4e0 \uc2dc\ubbfc\uacfc \uace7\ubc14\ub85c \uac19\uac8c \ubcf4\uba74 \uc548 \ub41c\ub2e4. \ub2f9\uc2dc\uc758 \uc0ac\ud68c\ub294 \uc2e0\ubd84\uacfc \uc758\ubb34\uac00 \ub2ec\ub790\ub2e4. \ub204\uac00 \uc870\ud56d\uc758 \ubcf4\ud638\ub97c \ubc1b\uc744 \uc218 \uc788\uc5c8\ub294\uc9c0\ub294 \ubb38\uc7a5\uc758 \uc544\ub984\ub2e4\uc6c0\uacfc \ubcc4\ub3c4\ub85c \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \ubb38\uc11c\uac00 \uc788\ub2e4\uace0 \ud798\uc758 \ucda9\ub3cc\uc774 \uc790\ub3d9\uc73c\ub85c \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub7ec\ub098 \ubb34\uc5c7\uc744 \uc57d\uc18d\ud588\ub294\uc9c0\ub97c \ub2e4\uc2dc \uc8fc\uc7a5\ud560 \uae30\uc900\uc740 \uc0dd\uae34\ub2e4. \uc655\uacfc \uc2e0\ud558\uac00 \uc11c\ub85c \ub2e4\ub978 \ub9d0\uc744 \ud560 \ub54c \uae30\ub85d\ub41c \uc870\ud56d\uc740 \uad00\uacc4\ub97c \uc124\uba85\ud558\uace0 \uc694\uad6c\ub97c \uc81c\uae30\ud558\ub294 \uadfc\uac70\uac00 \ub420 \uc218 \uc788\ub2e4. \uc5ec\uae30\uc11c \ubb38\uc11c\uc758 \ud798\uc740 \uc789\ud06c \uc790\uccb4\uc758 \ub9c8\ubc95\uc774 \uc544\ub2c8\ub2e4. \uadf8 \ubb38\uc11c\ub97c \ub204\uac00 \uc778\uc815\ud558\uace0 \uc5b4\ub5a4 \uad00\uacc4\uc5d0\uc11c \uc9c0\ud0a4\uac8c \ud560 \uc218 \uc788\ub294\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \ubc95\uacfc \uc57d\uc18d\uc758 \uc5ed\uc0ac\ub294 \uc88b\uc740 \ubb38\uc7a5\uc744 \uc4f0\ub294 \uc77c\uacfc \uadf8 \ubb38\uc7a5\uc744 \uc2e4\uc81c\ub85c \uc791\ub3d9\uc2dc\ud0a4\ub294 \uc870\uac74\uc774 \ud568\uaed8 \uc774\ub8e8\uc5b4 \uc628 \uc5ed\uc0ac\ub2e4. \ub9c8\uadf8\ub098 \uce74\ub974\ud0c0\ub97c \ud604\ub300 \ubbfc\uc8fc\uc8fc\uc758\uc758 \ucd9c\ubc1c\uacfc \uc5f0\uacb0\ud574 \uc18c\uac1c\ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4. \ud558\uc9c0\ub9cc \ub2f9\uc2dc \ud611\uc0c1\uc5d0\uc11c \uc911\uc2ec\uc801\uc778 \uc5ed\ud560\uc744 \ud55c \uc9d1\ub2e8\uacfc \ud3c9\ubc94\ud55c \uc8fc\ubbfc \uc804\uccb4\ub294 \uac19\uc740 \uac83\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc5ec\uc131\uacfc \ub18d\ubbfc\uc744 \ud3ec\ud568\ud55c \ub2e4\uc591\ud55c \uc0ac\ub78c\uc758 \uc9c0\uc704\uac00 \uc9c0\uae08\uc758 \uc2dc\ubbfc\uad8c\ucc98\ub7fc \uc77c\uad04\uc801\uc73c\ub85c \ubcf4\uc7a5\ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubb38\uc11c\uc758 \uc758\ubbf8\ub97c \ubaa8\ub450 \uc9c0\uc6b8 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \uc9c0\ubc30\uc790\uc758 \ud589\ub3d9\uc5d0 \uae30\uc900\uc744 \uc694\uad6c\ud558\uace0 \uad8c\ub9ac\uc758 \uc5b8\uc5b4\ub97c \ub0a8\uacbc\ub2e4\ub294 \uc810\uc740 \uc911\uc694\ud558\ub2e4. \ubb34\uc5c7\uc744 \uac00\ub2a5\ud558\uac8c \ud588\uace0 \ub204\uad6c\ub97c \ucda9\ubd84\ud788 \ud3ec\ud568\ud558\uc9c0 \uc54a\uc558\ub294\uc9c0\ub97c \ud568\uaed8 \ubcf4\uba74 \ucc2c\uc591\uacfc \uc2e4\ub9dd \uc0ac\uc774\uc5d0\uc11c \ub354 \uc815\ud655\ud558\uac8c \uc77d\uc744 \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc774\ud6c4 \uc789\uae00\ub79c\ub4dc\uc5d0\uc11c \uc131\uc9c1\uc790\uc640 \uadc0\uc871, \uc77c\ubd80 \ub3c4\uc2dc\uc758 \ub300\ud45c\ub4e4\uc774 \ucc38\uc5ec\ud558\ub294 \uc758\ud68c\uac00 \ubc1c\uc804\ud55c \uacfc\uc815\ub3c4 \uc124\uba85\ud55c\ub2e4. \uc138\uae08\uacfc \ubc95\uc744 \ub458\ub7ec\uc2fc \ub3d9\uc758\uac00 \uc911\uc694\ud574\uc84c\ub2e4. \uc655\uc758 \ub9d0\uacfc \ub098\ub77c\uc758 \ubc95\uc774 \uc5b4\ub5a4 \uad00\uacc4\uc5ec\uc57c \ud558\ub294\uc9c0\ub97c \ub450\uace0 \uc81c\ub3c4\uc758 \ud615\ud0dc\uac00 \ubc14\ub00c\uc5b4 \uac14\ub2e4. \uadf8\ub7ec\ub098 1215\ub144 \ubb38\uc11c \ud55c \uc7a5\uc774 \uadf8 \ubaa8\ub4e0 \ubcc0\ud654\ub97c \uace7\ubc14\ub85c \ub9cc\ub4e4\uc5b4 \ub0c8\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc2dc\ub300\ub9c8\ub2e4 \uc0c8\ub85c\uc6b4 \uac08\ub4f1\uacfc \uc120\ud0dd\uc774 \uc788\uc5c8\ub2e4. \ub9c8\uadf8\ub098 \uce74\ub974\ud0c0\uc758 \uc758\ubbf8\ub97c \ubcf4\ub824\uba74 \ud55c\uc21c\uac04\uc758 \ud0c4\uc0dd\ub2f4\ubfd0 \uc544\ub2c8\ub77c \ub4a4\uc5d0 \uc0ac\ub78c\ub4e4\uc774 \uadf8 \ubb38\uc11c\ub97c \uc5b4\ub5bb\uac8c \ub2e4\uc2dc \uc77d\uc5c8\ub294\uc9c0\ub3c4 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \uc624\ub298\ub0a0\uc5d0\ub294 \ub9c8\uadf8\ub098 \uce74\ub974\ud0c0\ub77c\ub294 \uc774\ub984\ub9cc\uc73c\ub85c \ubc95\uc5d0 \ub530\ub978 \ud1b5\uce58\uc640 \uad8c\ub9ac\ub97c \ub5a0\uc62c\ub9ac\uae30\ub3c4 \ud55c\ub2e4. \uc6d0\ub798\uc758 \uad6c\uccb4\uc801\uc778 \ud611\uc0c1\uacfc \ud6c4\ub300\uc5d0 \ubd80\uc5ec\ub41c \uc758\ubbf8\uac00 \ud55c \uc774\ub984 \uc548\uc5d0 \uacb9\uce5c \uac83\uc774\ub2e4. \uc5ed\uc0ac \uc790\ub8cc\ub294 \ub9cc\ub4e4\uc5b4\uc9c8 \ub54c\uc758 \ubaa9\uc801\uacfc \ub098\uc911\uc5d0 \uae30\uc5b5\ub418\ub294 \ubc29\uc2dd\uc774 \ub2e4\ub97c \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc911\uc138\uc758 \ubb38\uc11c\ub97c \ub450\uace0 \ub17c\uc758\ud558\ub294 \uc0c1\uc0c1 \uc18d \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c \ub9c8\uadf8\ub098 \uce74\ub974\ud0c0\uc758 \uc9c0\uba74\uc774\ub098 \uc874 \uc655\uc758 \ucd08\uc0c1, \uae30\ub85d\ub41c \ud611\uc0c1 \ud604\uc7a5\uc744 \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uae00\uc5d0\uc11c\ub294 1215\ub144\uc758 \uad00\uacc4\ub97c \uc77d\uace0 \uadf8\ub9bc\uc5d0\uc11c\ub294 \uc57d\uc18d\uc744 \ubb38\uc11c\ub85c \ub0a8\uae34\ub2e4\ub294 \ud589\uc704\ub97c \ub5a0\uc62c\ub9ac\uba74 \ub41c\ub2e4. \ub9c8\uadf8\ub098 \uce74\ub974\ud0c0\ub97c \ub9cc\ub0a0 \ub54c\ub294 \ub204\uac00 \ub204\uad6c\uc5d0\uac8c \ubb34\uc5c7\uc744 \uc694\uad6c\ud588\ub294\uc9c0\ubd80\ud130 \ubb3c\uc5b4\ubcf4\uc790. \uc790\uc720\ub77c\ub294 \ud070 \ub2e8\uc5b4\uac00 \uc5b4\ub5a4 \uc0ac\ub78c\uacfc \uc5b4\ub5a4 \uc0c1\ud669\uc5d0 \uc801\uc6a9\ub418\uc5c8\ub294\uc9c0\ub3c4 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uadf8\ub807\uac8c \uc77d\uc73c\uba74 \ubb38\uc11c\ub294 \ubc15\ubb3c\uad00\uc758 \uba3c \uc0c1\uc9d5\ubcf4\ub2e4 \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc758 \ud798\uacfc \ubd88\uc548\uc774 \ub2f4\uae34 \ubb3c\uac74\uc73c\ub85c \ubcf4\uc778\ub2e4. \uc655\uc758 \uad8c\ud55c\ub3c4 \uc544\ubb34 \uc124\uba85 \uc5c6\uc774 \ub05d\uc5c6\uc774 \ud589\uc0ac\ub420 \uc218\ub294 \uc5c6\ub2e4\ub294 \uc8fc\uc7a5\uc740 \uae34 \uc5ed\uc0ac\ub97c \uac00\uc84c\ub2e4. 1215\ub144\uc758 \uc57d\uc18d\uc740 \uadf8 \uc5ed\uc0ac\uc5d0\uc11c \uc911\uc694\ud55c \ud55c \uc7a5\uc774\ub2e4. \ud55c\uacc4\ub97c \ud3ec\ud568\ud55c \uc2e4\uc81c\uc758 \ubb38\uc11c\ub97c \uc77d\uc744 \ub54c, \uc624\ub298 \uc775\uc219\ud55c \uad8c\ub9ac\uc758 \uc5b8\uc5b4\uac00 \uc5bc\ub9c8\ub098 \uae34 \uac08\ub4f1\uacfc \ud574\uc11d\uc744 \uc9c0\ub098\uc654\ub294\uc9c0 \ub354 \uae4a\uc774 \ub290\ub07c\uac8c \ub41c\ub2e4."}, {"id": "mecca-pilgrimage-and-city", "title": "\uba54\uce74\uc640 \uc21c\ub840 \u2014 \uac19\uc740 \ubc29\ud5a5\uc73c\ub85c \ubaa8\uc774\ub294 \uae38\uc758 \uc5ed\uc0ac", "summary": "\uce74\ubc14\uc640 \ud558\uc9c0\uc758 \uc758\ubbf8\ub97c \ub530\ub77c \uc77d\ub294 \uc131\uc9c0\u00b7\uc774\ub3d9\u00b7\uacf5\ub3d9\uccb4\uc744 \uc774\uc57c\uae30\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/mecca-pilgrimage-and-city/index.html", "image": "../media/mecca-pilgrimage-and-city.png", "alt": "\uba54\uce74\uc758 \uc2e0\uc131\ud55c \ubaa8\uc2a4\ud06c\uc640 \uce74\ubc14 \uc8fc\uc704\uc5d0 \ubaa8\uc778 \uc21c\ub840\uc790 \uc2e4\uc81c \uc0ac\uc9c4", "text": "\uba54\uce74\uc640 \uc21c\ub840 \u2014 \uac19\uc740 \ubc29\ud5a5\uc73c\ub85c \ubaa8\uc774\ub294 \uae38\uc758 \uc5ed\uc0ac \uce74\ubc14\uc640 \ud558\uc9c0\uc758 \uc758\ubbf8\ub97c \ub530\ub77c \uc77d\ub294 \uc131\uc9c0\u00b7\uc774\ub3d9\u00b7\uacf5\ub3d9\uccb4 \uce74\ubc14\uc640 \ud558\uc9c0\uc758 \uc758\ubbf8\ub97c \ub530\ub77c \uc77d\ub294 \uc131\uc9c0\u00b7\uc774\ub3d9\u00b7\uacf5\ub3d9\uccb4\uc744 \uc774\uc57c\uae30\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc138\uacc4 \uc5ec\ub7ec \uc9c0\uc5ed\uc5d0 \uc0ac\ub294 \ubb34\uc2ac\ub9bc\uc740 \uae30\ub3c4\ud560 \ub54c \uac19\uc740 \ubc29\ud5a5\uc744 \ud5a5\ud55c\ub2e4. \uadf8 \uc911\uc2ec\uc5d0\ub294 \uba54\uce74\uc758 \uce74\ubc14\uac00 \uc788\ub2e4. \uba40\ub9ac \ub5a8\uc5b4\uc9c4 \uc0ac\ub78c\ub4e4\uc774 \ud558\ub098\uc758 \uc7a5\uc18c\ub97c \uae30\uc5b5\ud558\uace0, \ub9ce\uc740 \uc774\uac00 \uc2e4\uc81c\ub85c \uadf8\uacf3\uc744 \ud5a5\ud574 \ub5a0\ub09c\ub2e4. \uba54\uce74\uc758 \uc5ed\uc0ac\ub294 \ub3c4\uc2dc\uc758 \uac74\ubb3c\ubfd0 \uc544\ub2c8\ub77c \ub3c4\uc2dc\ub85c \uc774\uc5b4\uc9c0\ub294 \uae38\uc758 \uc5ed\uc0ac\uc774\uae30\ub3c4 \ud558\ub2e4. \uc624\ub298\uc758 \uba54\uce74\ub294 \uc0ac\uc6b0\ub514\uc544\ub77c\ube44\uc544\uc5d0 \uc788\uc9c0\ub9cc \uc774\uc2ac\ub78c \ucd08\uae30\uc758 \uc544\ub77c\ube44\uc544\ub97c \uc9c0\uae08\uc758 \uad6d\uac00 \uccb4\uc81c\uc640 \uac19\ub2e4\uace0 \ubcf4\uc544\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc2dc\ub300\ub97c \uad6c\ubd84\ud558\uba74\uc11c \uc131\uc9c0\uc640 \uc21c\ub840\uac00 \uc5b4\ub5a4 \uc758\ubbf8\ub97c \uac00\uc84c\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uba74 \ub0af\uc120 \uc885\uad50\uc758 \ud48d\uacbd\uc744 \ub2e8\uc21c\ud55c \uad70\uc911 \uc0ac\uc9c4 \uc774\uc0c1\uc73c\ub85c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc774\uc2ac\ub78c\uc774 \ub4f1\uc7a5\ud558\uae30 \uc804 \uc544\ub77c\ube44\uc544\ubc18\ub3c4\uc5d0\ub294 \uc9c0\uc5ed\ub9c8\ub2e4 \ub2e4\ub978 \uc0dd\ud65c \uc870\uac74\uacfc \uacf5\ub3d9\uccb4\uac00 \uc788\uc5c8\ub2e4. \uc0ac\ub9c9\uc774\ub77c\ub294 \ud55c \ub2e8\uc5b4\ub9cc\uc73c\ub85c \ubaa8\ub450 \uc124\uba85\ud558\uae30 \uc5b4\ub835\ub2e4. \ubb3c\uc744 \uc5bb\uc744 \uc218 \uc788\ub294 \uc7a5\uc18c\uc640 \uad50\uc5ed\uc758 \uacbd\ub85c, \uc815\ucc29\uc9c0\uc640 \uc774\ub3d9\ud558\ub294 \uc9d1\ub2e8\uc758 \uad00\uacc4\uac00 \uc911\uc694\ud588\ub2e4. \uba54\uce74\ub3c4 \uc774\ub7f0 \uc544\ub77c\ube44\uc544\uc758 \uc5ed\uc0ac \uc548\uc5d0\uc11c \ubcf4\uc544\uc57c \ud55c\ub2e4. \ub3c4\uc2dc\uac00 \uc131\uc7a5\ud558\ub824\uba74 \uac74\ubb3c\ub9cc \ud544\uc694\ud55c \uac83\uc774 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \uba38\ubb3c\uace0 \uc655\ub798\ud560 \uc774\uc720\uac00 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uba54\uce74\uc5d0\ub294 \uad50\uc5ed\uacfc \uc131\uc18c\ub97c \uc911\uc2ec\uc73c\ub85c \ud55c \ub9cc\ub0a8\uc758 \uc870\uac74\uc774 \uc788\uc5c8\ub2e4. \uacbd\uc81c\uc640 \uc2e0\uc559\uc744 \uc11c\ub85c \uc644\uc804\ud788 \ubd84\ub9ac\ub41c \ub450 \uc138\uacc4\ub85c \uc0dd\uac01\ud558\uba74 \uc774 \ub3c4\uc2dc\uac00 \uac00\uc9c4 \uc624\ub798\ub41c \uc131\uaca9\uc744 \uc774\ud574\ud558\uae30 \uc5b4\ub835\ub2e4. \uce74\ubc14\ub294 \uba54\uce74\uc758 \uc2e0\uc131\ud55c \ubaa8\uc2a4\ud06c \uc911\uc2ec\uc5d0 \uc788\ub294 \uac74\ubb3c\uc774\ub2e4. \uac80\uc740 \ucc9c\uc73c\ub85c \ub36e\uc778 \ud615\ud0dc\uac00 \ub110\ub9ac \uc54c\ub824\uc838 \uc788\uc9c0\ub9cc, \ubb34\uc2ac\ub9bc\uc5d0\uac8c \uc911\uc694\ud55c \uac83\uc740 \uc678\uad00\uc758 \ud2b9\uc774\ud568\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uc774\uc2ac\ub78c\uc758 \uc804\uc2b9\uc5d0\uc11c \uc544\ube0c\ub77c\ud568\uacfc \uc774\uc2a4\ub9c8\uc5d8\uc5d0 \uc5f0\uacb0\ub418\ub294 \uc131\uc18c\uc774\uba70 \uc2e0\uc559\uc758 \uc911\uc2ec\uc744 \ub098\ud0c0\ub0b8\ub2e4. \uc774 \uc124\uba85\uc5d0\uc11c\ub294 \ubbff\uc74c\uc758 \uc804\uc2b9\uacfc \uc5ed\uc0ac\ud559\uc758 \ud655\uc778 \ubc29\uc2dd\uc744 \uad6c\ubcc4\ud560 \ud544\uc694\uac00 \uc788\ub2e4. \uc544\ube0c\ub77c\ud568\uc774 \uce74\ubc14\uc640 \ub9fa\ub294 \uad00\uacc4\ub294 \ubb34\uc2ac\ub9bc\uc758 \uc2e0\uc559\uacfc \uc804\ud1b5\uc5d0\uc11c \uc911\uc694\ud55c \uc758\ubbf8\ub97c \uac16\ub294\ub2e4. \uadf8 \uc758\ubbf8\ub97c \uc874\uc911\ud574 \uc18c\uac1c\ud558\ub294 \uc77c\uacfc \ubaa8\ub4e0 \uc138\ubd80\ub97c \ud604\ub300\uc758 \ubb38\uc11c \uae30\ub85d\uc73c\ub85c \uc785\uc99d\ub41c \uc0ac\uac74\ucc98\ub7fc \uc11c\uc220\ud558\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \ubb34\ud568\ub9c8\ub4dc\ub294 \uba54\uce74\uc5d0\uc11c \ud65c\ub3d9\ud558\uba70 \uc720\uc77c\uc2e0 \uc2e0\uc559\uc758 \uba54\uc2dc\uc9c0\ub97c \uc804\ud588\ub2e4. \uadf8 \uba54\uc2dc\uc9c0\ub294 \uae30\uc874\uc758 \uc885\uad50 \uad00\ud589\uacfc \uacf5\ub3d9\uccb4 \uc9c8\uc11c\uc5d0 \ubcc0\ud654\ub97c \uc694\uad6c\ud588\uace0 \uac08\ub4f1\ub3c4 \uc77c\uc5b4\ub0ac\ub2e4. \uc774\ud6c4 \uba54\ub514\ub098\uc5d0\uc11c \uacf5\ub3d9\uccb4\uac00 \ud615\uc131\ub418\uace0 \uba54\uce74\uc640\uc758 \uad00\uacc4\uac00 \ub2ec\ub77c\uc9c0\ub294 \uacfc\uc815\uc740 \uc774\uc2ac\ub78c \ucd08\uae30 \uc5ed\uc0ac\uc758 \uc911\uc694\ud55c \ud750\ub984\uc774\ub2e4. \uc774\ub54c\uc758 \uacf5\ub3d9\uccb4\ub97c \uc624\ub298\uc758 \uc0ac\uc6b0\ub514\uc544\ub77c\ube44\uc544\uc640 \uadf8\ub300\ub85c \uacb9\uccd0 \ubcf4\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\ub2e4. \ud604\uc7ac\uc758 \uad6d\uac00\ub294 \ud6e8\uc52c \ub4a4\uc5d0 \ud615\uc131\ub418\uc5c8\ub2e4. \uad6d\uac00\ubcc4 \uc77d\uc744\uac70\ub9ac\ub85c \uba54\uce74\ub97c \uc18c\uac1c\ud558\ub354\ub77c\ub3c4, \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc758 \uc138\uacc4\ub97c \ud604\uc7ac\uc758 \uad6d\uacbd \uc548\uc5d0\ub9cc \uac00\ub450\uc9c0 \uc54a\uc544\uc57c \uc5ed\uc0ac\uc758 \uc2dc\uac04 \ucc28\uc774\uac00 \uc0b4\uc544\ub09c\ub2e4. \uba54\uce74\ub85c \uac00\ub294 \ud558\uc9c0 \uc21c\ub840\ub294 \uc774\uc2ac\ub78c\uc758 \ub2e4\uc12f \uae30\ub465 \uac00\uc6b4\ub370 \ud558\ub098\ub2e4. \ub2a5\ub825\uc774 \ub418\ub294 \ubb34\uc2ac\ub9bc\uc5d0\uac8c \ud3c9\uc0dd \ud55c \ubc88 \uc218\ud589\ud558\ub3c4\ub85d \uc694\uad6c\ub418\ub294 \uc885\uad50\uc801 \uc758\ubb34\ub2e4. \ub204\uad6c\ub098 \uc5b4\ub5a4 \ud615\ud3b8\uc5d0\uc11c\ub3c4 \ubb34\uc870\uac74 \uac19\uc740 \uc5ec\ud589\uc744 \ud574\uc57c \ud55c\ub2e4\ub294 \ub73b\uc73c\ub85c \ub2e8\uc21c\ud654\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc218\ud589\ud560 \uc218 \uc788\ub294 \uc870\uac74\uc774 \ud568\uaed8 \uace0\ub824\ub41c\ub2e4. \ub610\ud55c \uba54\uce74\ub97c \ubc29\ubb38\ud558\ub294 \ubaa8\ub4e0 \ud589\uc704\ub97c \uac19\uc740 \uc774\ub984\uc758 \ud589\uc0ac\ub85c \ubb36\ub294 \uac83\ub3c4 \uc815\ud655\ud558\uc9c0 \uc54a\ub2e4. \ud558\uc9c0\ub294 \uc774\uc2ac\ub78c\ub825\uc758 \uc815\ud574\uc9c4 \uc2dc\uae30\uc5d0 \uc774\ub8e8\uc5b4\uc9c0\ub294 \uc21c\ub840\ub2e4. \uc131\uc9c0\ub97c \ucc3e\ub294\ub2e4\ub294 \ub113\uc740 \ud589\uc704 \uc548\uc5d0\uc11c\ub3c4 \uc2dc\uae30\uc640 \uc808\ucc28\uc5d0 \ub530\ub77c \uad6c\ubd84\uc774 \uc788\ub2e4. \ub3c5\uc790\ub294 \uba3c\uc800 \uc774 \uae30\ubcf8\uc801\uc778 \ucc28\uc774\ub97c \uc54c\uba74 \ubcf5\uc7a1\ud55c \uc124\uba85\uc744 \ub530\ub77c\uac00\uae30 \uc26c\uc6cc\uc9c4\ub2e4. \uc21c\ub840\uc758 \ub300\ud45c\uc801\uc778 \ubaa8\uc2b5\uc740 \uce74\ubc14 \uc8fc\uc704\ub97c \ub3c4\ub294 \uad70\uc911\uc774\ub2e4. \uadf8\ub7ec\ub098 \ud558\uc9c0\ub294 \uc720\uba85\ud55c \uac74\ubb3c\uc744 \uac00\uae4c\uc774\uc5d0\uc11c \ubcf4\uace0 \ub3cc\uc544\uc624\ub294 \uad00\uad11\uacfc \uac19\uc9c0 \uc54a\ub2e4. \uc544\ube0c\ub77c\ud568\uacfc \uadf8 \uac00\uc871\uc5d0 \uad00\ud55c \uc2e0\uc559\uc758 \uae30\uc5b5\uc744 \ub418\uc0c8\uae30\ub294 \uc5ec\ub7ec \uc758\ub840\uc640 \uc7a5\uc18c\uac00 \uc5f0\uacb0\ub41c\ub2e4. \uac77\ub294 \ud589\uc704\uc5d0\ub3c4 \uc774\ubbf8 \uc804\ud574\uc9c4 \uc774\uc57c\uae30\uc640 \uc885\uad50\uc801 \uc758\ubbf8\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \ubc16\uc5d0\uc11c \ubcf4\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc6c0\uc9c1\uc784\uacfc \uc778\ud30c\uac00 \uba3c\uc800 \ubcf4\uc774\uc9c0\ub9cc \ucc38\uc5ec\uc790\ub294 \uae30\ub3c4\uc640 \uc758\ubb34, \uacf5\ub3d9\uccb4\uc758 \uacbd\ud5d8 \uc18d\uc5d0 \uc788\ub2e4. \uac19\uc740 \uc7a5\uba74\uc744 \uc774\ud574\ud558\ub824\uba74 \ubcf4\ub294 \uc0ac\ub78c\uc758 \uad00\uc2ec\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uc9c0 \uc54a\ub294 \ud0dc\ub3c4\uac00 \ud544\uc694\ud558\ub2e4. \ubb34\uc5c7\uc744 \ud558\uace0 \uc788\ub294\uc9c0\uc5d0 \uc55e\uc11c \uc65c \uadf8 \ud589\ub3d9\uc744 \ud558\ub294\uc9c0 \ubb3b\ub294 \uac83\uc774\ub2e4. \uc5ec\ub7ec \uc9c0\uc5ed\uc5d0\uc11c \uc21c\ub840\uc790\uac00 \ubaa8\uc774\uba74 \uadf8\ub4e4\uc758 \uc774\ub3d9\uacfc \uccb4\ub958\ub97c \uac00\ub2a5\ud558\uac8c \ud558\ub294 \uc870\uac74\ub3c4 \ud544\uc694\ud558\ub2e4. \ubb3c\uacfc \uc2dd\uc0ac, \uba38\ubb3c \uacf3\uacfc \uc548\uc804\ud55c \uae38\uc740 \uc885\uad50\uc801 \ubaa9\uc801\uc744 \uc2e4\uc81c\uc758 \uc5ec\ud589\uc73c\ub85c \ubc14\uafb8\ub294 \ubb38\uc81c\ub2e4. \uc131\uc9c0\uc758 \uc5ed\uc0ac\ub294 \uc2e0\uc559\uc758 \uad50\ub9ac\ubfd0 \uc544\ub2c8\ub77c \uc0ac\ub78c\ub4e4\uc774 \ubaa9\uc801\uc9c0\uae4c\uc9c0 \ub3c4\ub2ec\ud558\ub294 \uc0dd\ud65c\uc758 \uc5ed\uc0ac\uc640\ub3c4 \uc5f0\uacb0\ub41c\ub2e4. \uc2dc\ub300\uc5d0 \ub530\ub77c \uad50\ud1b5\uc218\ub2e8\uacfc \uc774\ub3d9 \uc2dc\uac04\uc740 \ub2ec\ub77c\uc84c\uaca0\uc9c0\ub9cc \uba40\ub9ac \uc788\ub294 \uc774\ub4e4\uc774 \ud558\ub098\uc758 \uc7a5\uc18c\ub85c \ubaa8\uc778\ub2e4\ub294 \uad6c\uc870\ub294 \uc774\uc5b4\uc9c4\ub2e4. \uadf8\ub798\uc11c \uc21c\ub840\ub97c \uba54\uce74 \uc548\uc5d0\uc11c\ub9cc \uc77c\uc5b4\ub098\ub294 \uc0ac\uac74\uc73c\ub85c \ubcf4\uae30 \uc5b4\ub835\ub2e4. \ucd9c\ubc1c\ud55c \ub9c8\uc744\uacfc \uc774\ub3d9 \uacbd\ub85c, \ub3c4\ucc29\ud55c \ub3c4\uc2dc\uac00 \uae34 \ud558\ub098\uc758 \uacbd\ud5d8\uc744 \uc774\ub8ec\ub2e4. \uba54\uce74\ub294 \uc624\ub298\uc758 \uc0ac\uc6b0\ub514\uc544\ub77c\ube44\uc544 \uc9c0\ub3c4 \uc548\uc5d0 \uc788\uc9c0\ub9cc \uadf8 \uc885\uad50\uc801 \uc758\ubbf8\ub294 \ud55c \uad6d\uac00\uc758 \uc8fc\ubbfc\uc5d0\uac8c\ub9cc \ud55c\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc5b8\uc5b4\uc640 \uc0dd\ud65c \ubc30\uacbd\uc744 \uac00\uc9c4 \ubb34\uc2ac\ub9bc\ub4e4\uc774 \uac19\uc740 \uc131\uc9c0\ub97c \ud5a5\ud55c\ub2e4. \uad6d\uac00\ubcc4\ub85c \ub3c4\uc2dc\ub97c \uc77d\uc73c\uba74\uc11c\ub3c4 \uadf8 \ub3c4\uc2dc\uac00 \uad6d\uacbd\uc744 \ub118\ub294 \uc774\uc720\ub97c \ud568\uaed8 \uc54c\uc544\uc57c \ud558\ub294 \uc0ac\ub840\ub2e4. \uc21c\ub840\uc758 \uc5ed\uc0ac\ub97c \uc124\uba85\ud560 \ub54c\uc5d0\ub294 \ucc38\uc5ec\uc790\uc758 \ubbff\uc74c\uc744 \ub0af\uc120 \ud48d\uc2b5\uc73c\ub85c\ub9cc \ub2e4\ub8e8\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\ub2e4. \uc758\ub840\uc758 \uc774\ub984\uacfc \ub73b\uc744 \uba3c\uc800 \uc54c\uc544\ubcf4\uba74 \ubc18\ubcf5\ub418\ub294 \ud589\ub3d9\uc5d0\ub3c4 \uc774\uc720\uac00 \uc788\uc74c\uc744 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc9c0\uc2dd\uc744 \uc5bb\ub294 \uc77c\uc740 \ub2e4\ub978 \uc0b6\uc744 \ud310\ub2e8\ud558\uae30 \uc804\uc5d0 \uadf8 \ub9e5\ub77d\uc744 \ubc30\uc6b0\ub294 \uc77c\uc774\uae30\ub3c4 \ud558\ub2e4. \uce74\ubc14\ub97c \ub458\ub7ec\uc2fc \uc0ac\uc9c4\uc744 \ub2e4\uc2dc \ubcfc \ub54c\uc5d0\ub294 \uad70\uc911\uc758 \ud06c\uae30\ub9cc \uc138\uc9c0 \ub9d0\uace0 \uac01 \uc0ac\ub78c\uc774 \ucd9c\ubc1c\ud55c \uba3c \uacf3\uacfc \uacf5\uc720\ud558\ub294 \uae30\uc5b5\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uba54\uce74\ub294 \ud558\ub098\uc758 \ub3c4\uc2dc\uc774\uba74\uc11c \ub9ce\uc740 \uae38\uc774 \ubaa8\uc774\ub294 \uc911\uc2ec\uc774\ub2e4. \uc2e0\uc559\uc774 \uc0ac\ub78c\uc744 \uc6c0\uc9c1\uc774\uace0 \uadf8 \uc774\ub3d9\uc774 \ub3c4\uc2dc\uc758 \uc5ed\uc0ac\ub97c \ub9cc\ub4e0\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uadf8 \ud48d\uacbd \uc548\uc5d0 \ub2f4\uaca8 \uc788\ub2e4."}, {"id": "mohenjo-daro-bronze-and-city-life", "title": "\ubaa8\ud5e8\uc870\ub2e4\ub85c \u2014 \uc791\uc740 \uccad\ub3d9\uc0c1\uc5d0\uc11c \ub3c4\uc2dc\uc758 \uc0dd\ud65c\uc744 \ubcf4\ub2e4", "summary": "\uc2e4\uc81c \uccad\ub3d9\uc0c1\uc758 \uc790\uc138\uc640 \uc7a5\uc2e0\uad6c\uc5d0\uc11c \ubaa8\ud5e8\uc870\ub2e4\ub85c\uc758 \uc218\uacf5\uc5c5\uacfc \ubb3c\uc758 \uc2dc\uc124, \ud574\ub3c5\ub418\uc9c0 \uc54a\uc740 \uae30\ub85d\uc758 \ud55c\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/mohenjo-daro-bronze-and-city-life/index.html", "image": "../media/mohenjo-daro-bronze-and-city-life.jpg", "alt": "\ubaa8\ud5e8\uc870\ub2e4\ub85c\uc5d0\uc11c \ub098\uc628 \uc791\uc740 \uccad\ub3d9\uc0c1. \ud5c8\ub9ac\uc5d0 \ub304 \ud314\uacfc \uc5ec\ub7ec \uc7a5\uc2e0\uad6c\uac00 \ubcf4\uc778\ub2e4.", "text": "\ubaa8\ud5e8\uc870\ub2e4\ub85c \u2014 \uc791\uc740 \uccad\ub3d9\uc0c1\uc5d0\uc11c \ub3c4\uc2dc\uc758 \uc0dd\ud65c\uc744 \ubcf4\ub2e4 \ucda4\ucd94\ub294 \uc18c\ub140\ub77c\ub294 \uc774\ub984\uacfc \ubcbd\ub3cc, \ubb3c\uae38, \uc54c \uc218 \uc5c6\ub294 \uc0ac\ub78c\ub4e4 \uc2e4\uc81c \uccad\ub3d9\uc0c1\uc758 \uc790\uc138\uc640 \uc7a5\uc2e0\uad6c\uc5d0\uc11c \ubaa8\ud5e8\uc870\ub2e4\ub85c\uc758 \uc218\uacf5\uc5c5\uacfc \ubb3c\uc758 \uc2dc\uc124, \ud574\ub3c5\ub418\uc9c0 \uc54a\uc740 \uae30\ub85d\uc758 \ud55c\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ud55c \uc190\uc744 \ud5c8\ub9ac\uc5d0 \ub300\uace0 \uc11c \uc788\ub294 \uc791\uc740 \uccad\ub3d9\uc0c1. \ud314\uc5d0 \uc774\uc5b4\uc9c4 \uc7a5\uc2e0\uad6c\uc640 \uc0b4\uc9dd \uae30\uc6b8\uc5b4\uc9c4 \ubab8\uc5d0\uc11c \uc5ec\uc720\ub85c\uc6b4 \ud45c\uc815\uc774 \ub290\uaef4\uc9c4\ub2e4. \ud754\ud788 \u2018\ucda4\ucd94\ub294 \uc18c\ub140\u2019\ub77c \ubd80\ub974\ub294 \ubaa8\ud5e8\uc870\ub2e4\ub85c\uc758 \uc720\ubb3c\uc774\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uc774\ub984\uc774 \ub2f9\uc2dc \ubcf8\uc778\uc758 \uc9c1\uc5c5\uc744 \uc54c\ub824 \uc8fc\ub294 \uba85\ucc30\uc740 \uc544\ub2c8\ub2e4. \uc774 \uc778\ubb3c\uc774 \ub204\uad6c\uc778\uc9c0 \ud655\uc2e4\ud788 \ub9d0\ud560 \uc218 \uc5c6\uc5b4\ub3c4 \uc0b4\ud3b4\ubcfc \uac83\uc740 \ub9ce\ub2e4. \uc791\uc740 \uc0c1\uc744 \ub9cc\ub4e4 \uc218 \uc788\uc5c8\ub358 \uae30\uc220\uacfc \ucde8\ud5a5, \uadf8 \uc0ac\ub78c\uc744 \ub458\ub7ec\uc2fc \ub3c4\uc2dc\uc758 \uc0dd\ud65c\uc774 \uc788\uc5c8\ub2e4. \uc624\ub298\ub0a0 \ud30c\ud0a4\uc2a4\ud0c4\uc758 \uc720\uc801\uc5d0\uc11c \ub098\uc628 \uc774 \ubb3c\uac74\uc744 \ucd9c\ubc1c\uc810\uc73c\ub85c \uc624\ub798\ub41c \ub3c4\uc2dc \uc548\uc73c\ub85c \ub4e4\uc5b4\uac00 \ubcf4\uc790. \uccad\ub3d9\uc0c1\uc740 \ub9e4\uc6b0 \uc791\uc9c0\ub9cc \uc790\uc138\uac00 \ubd84\uba85\ud558\ub2e4. \ud55c \ud314\uc740 \ud5c8\ub9ac\uc5d0 \ub2ff\uace0 \ub2e4\ub978 \ud314\uc5d0\ub294 \uc5ec\ub7ec \uc7a5\uc2e0\uad6c\uac00 \ubcf4\uc778\ub2e4. \uba3c\uc800 \ucda4\ucd94\ub294 \uc7a5\uba74\uc774\ub77c\uace0 \uacb0\ub860\ub0b4\ub9ac\uae30\ubcf4\ub2e4 \ud314\uacfc \ub2e4\ub9ac\uc758 \ubc29\ud5a5, \ubab8\uc758 \ubb34\uac8c\uac00 \uc2e4\ub9b0 \ubaa8\uc591\uc744 \uc0b4\ud3b4\ubcf4\uba74 \uc88b\ub2e4. \uc791\ud488\uc744 \ubd80\ub974\ub294 \uc774\ub984\uc740 \uad00\ucc30\uc744 \ub3d5\uae30\ub3c4 \ud558\uace0 \ud55c \ubc29\ud5a5\uc73c\ub85c \uc774\ub04c\uae30\ub3c4 \ud55c\ub2e4. \ucda4\ucd94\ub294 \uc778\ubb3c\uc774\ub098 \ud2b9\uc815 \uc2e0\ubd84\uc758 \uc0ac\ub78c\uc774\ub77c\ub294 \ud574\uc11d\uc740 \uac00\ub2a5\uc131\uc774\uc9c0\ub9cc \ub2e8\uc815\uc740 \uc5b4\ub835\ub2e4. \uadf8 \ubaa8\ud638\ud568\uc744 \ub0a8\uaca8 \ub450\uc5b4\ub3c4 \uc870\uac01\uc774 \uc8fc\ub294 \uc0dd\uc0dd\ud568\uc740 \ucda9\ubd84\ud558\ub2e4. \ubaa8\ud5e8\uc870\ub2e4\ub85c \uc0ac\ub78c\ub4e4\uc740 \uccad\ub3d9\ubfd0 \uc544\ub2c8\ub77c \ub3cc\uacfc \uc810\ud1a0\ub85c\ub3c4 \ubb3c\uac74\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \uc7a5\uc2e0\uad6c\uc640 \ub3c4\uae30, \uc778\uc7a5 \uac19\uc740 \uc720\ubb3c\ub3c4 \ub0a8\uacbc\ub2e4. \uc2dd\ub7c9\uc744 \uc0dd\uc0b0\ud558\ub294 \uc0ac\ub78c \uc678\uc5d0 \uc5ec\ub7ec \uc7ac\ub8cc\ub97c \ub2e4\ub8e8\ub294 \uc7a5\uc778\uc774 \ud65c\ub3d9\ud560 \uc218 \uc788\uc5c8\ub358 \ub3c4\uc2dc\uc600\ub2e4. \uc791\uc740 \uc0c1\uc744 \ub9cc\ub4e4\ub824\uba74 \uc7ac\ub8cc\uc640 \uae30\uc220, \uc2dc\uac04\uc744 \ud655\ubcf4\ud574\uc57c \ud55c\ub2e4. \ub204\uad6c\uc758 \uc8fc\ubb38\uc774\uc5c8\ub294\uc9c0 \ubab0\ub77c\ub3c4 \uadf8\ub7f0 \uc0dd\uc0b0\uc774 \uac00\ub2a5\ud55c \ud658\uacbd\uc740 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc720\ubb3c\uc740 \ud2b9\ubcc4\ud55c \uc608\uc220\uac00 \ud55c \uba85\uc758 \uc7ac\ub2a5\uacfc \ud568\uaed8 \ub3c4\uc2dc\uc758 \ub2e4\uc591\ud55c \uc77c\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \ubaa8\ud5e8\uc870\ub2e4\ub85c\ub294 \uc778\ub354\uc2a4 \ubb38\uba85\uc758 \uc8fc\uc694 \ub3c4\uc2dc \uac00\uc6b4\ub370 \ud558\ub098\uc600\ub2e4. \ud558\ub77c\ud30c\uc640 \uc5ec\ub7ec \uac70\uc810\uc774 \uc624\ub298\ub0a0 \ud30c\ud0a4\uc2a4\ud0c4\uacfc \uc778\ub3c4\uc5d0 \uac78\uce5c \ub113\uc740 \uc9c0\uc5ed\uc5d0 \uc788\uc5c8\ub2e4. \ud55c \ub3c4\uc2dc\uc758 \uc720\uc801\ub9cc\uc73c\ub85c \uadf8 \ubb38\uba85 \uc804\uccb4\uc758 \uc0dd\ud65c\uc744 \ub2e4 \uc54c \uc218\ub294 \uc5c6\ub2e4. \uadf8\ub807\uc9c0\ub9cc \ube44\uc2b7\ud55c \uac74\ucd95\uacfc \ubb3c\uac74, \uc870\uc9c1\ub41c \uac70\ub9ac\uc758 \ud754\uc801\uc740 \ub3c4\uc2dc\ub4e4 \uc0ac\uc774\uc758 \uc5f0\uacb0\uc744 \ubb3b\uac8c \ud55c\ub2e4. \ub204\uac00 \uaddc\uce59\uc744 \uc815\ud558\uace0 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5bb\uac8c \ud611\ub825\ud588\ub294\uc9c0\uc5d0 \ub300\ud574\uc11c\ub294 \uc5ec\ub7ec \ud574\uc11d\uc774 \uc788\ub2e4. \uc774\ub984\uc774 \uc54c\ub824\uc9c4 \uc655\uc758 \uc5f0\ub300\uae30\ucc98\ub7fc \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b4 \uc5ed\uc0ac\ub2e4. \uc720\uc801\uc5d0\ub294 \uc815\ub3c8\ub41c \uac70\ub9ac\uc640 \uc8fc\uac70 \uad6c\uc5ed, \uc5ec\ub7ec \ud06c\uae30\uc758 \uac74\ubb3c\uc774 \ub0a8\uc544 \uc788\ub2e4. \ud070 \ub3c4\uc2dc\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc774 \ud568\uaed8 \uc0b4\ub824\uba74 \uc9d1\uc744 \ud55c \ucc44\uc529 \uc9d3\ub294 \uc77c \uc678\uc5d0\ub3c4 \uae38\uacfc \uacbd\uacc4\ub97c \ub9de\ucd94\ub294 \uc77c\uc774 \ud544\uc694\ud558\ub2e4. \ubb3c\uac74\uacfc \uc0ac\ub78c\uc774 \uc9c0\ub0a0 \uacf5\uac04\ub3c4 \ud655\ubcf4\ud574\uc57c \ud588\ub2e4. \uc774 \ubaa8\uc2b5\uc744 \uace7\ubc14\ub85c \ud604\ub300\uc801\uc778 \uacc4\ud68d\ub3c4\uc2dc\uc640 \uac19\ub2e4\uace0 \ubd80\ub974\uae30\ub294 \uc5b4\ub835\ub2e4. \uac74\ubb3c\uc758 \uc815\ud655\ud55c \uae30\ub2a5\uacfc \ud1b5\uce58 \ubc29\uc2dd\uc740 \uc544\uc9c1 \ub17c\uc758\ub41c\ub2e4. \ub2e4\ub9cc \uc8fc\ubbfc\ub4e4\uc774 \uc11c\ub85c \uc601\ud5a5\uc744 \uc8fc\ub294 \ubc00\uc9d1\ub41c \uc0dd\ud65c\uc744 \ud588\uace0 \uadf8 \uc0dd\ud65c\uc5d0 \ub9de\ucd98 \uc2dc\uc124\uc744 \ub9c8\ub828\ud588\ub2e4\ub294 \uc810\uc740 \ubd84\uba85\ud788 \ubcf4\uc778\ub2e4. \uc9d1\uc5d0\ub294 \uc911\uc815\uc744 \uc911\uc2ec\uc73c\ub85c \ubc29\uc774 \ub193\uc600\uace0 \uc6b0\ubb3c\uacfc \uc53b\ub294 \uacf5\uac04\uc744 \uac16\ucd98 \uc0ac\ub840\uac00 \uc788\ub2e4. \ub3c4\uc2dc\uc5d0\ub294 \ub36e\uac1c\uac00 \uc788\ub294 \ubc30\uc218 \uc2dc\uc124\ub3c4 \uc788\uc5c8\ub2e4. \ubb3c\uc744 \uad6c\ud558\uace0 \uc0ac\uc6a9\ud55c \ub4a4 \ubcf4\ub0b4\ub294 \uc77c\uc5d0 \uc0c1\ub2f9\ud55c \uc9c0\uc2dd\uacfc \ub178\ub3d9\uc744 \ub4e4\uc600\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uae68\ub057\ud55c \uc9d1 \ud55c \ucc44\ub9cc \ub530\ub85c \uc874\uc7ac\ud560 \uc218\ub294 \uc5c6\ub2e4. \ubc84\ub9b0 \ubb3c\uc774 \uc774\uc6c3\uc73c\ub85c \ud750\ub974\uba74 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc0dd\ud65c\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4. \uc624\ub798\ub41c \ubc30\uc218\ub85c\ub97c \ubcf4\uba74 \ub3c4\uc2dc\uac00 \uc774\ubbf8 \uc218\ucc9c \ub144 \uc804\ubd80\ud130 \uc774\ub7f0 \uc5f0\uacb0\uc744 \ub2e4\ub8e8\uc5b4\uc57c \ud588\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \ubaa8\ud5e8\uc870\ub2e4\ub85c\uc5d0\ub294 \uacc4\ub2e8\uc73c\ub85c \ub0b4\ub824\uac00\ub294 \ud070 \uc218\uc870\uac00 \ub0a8\uc544 \uc788\ub2e4. \ubb3c\uc744 \ucc44\uc6b0\uace0 \uc774\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d \ub9cc\ub4e0 \uaddc\ubaa8 \uc788\ub294 \uacf5\uac04\uc774\ub2e4. \uadf8\uacf3\uc5d0\uc11c \ub204\uac00 \uc5b4\ub5a4 \uc758\uc2dd\uc744 \ud588\ub294\uc9c0\uc5d0 \ub300\ud574\uc11c\ub294 \uc5ec\ub7ec \ucd94\uc815\uc774 \uc774\uc5b4\uc838 \uc654\ub2e4. \uacf5\ub3d9\uc73c\ub85c \uc774\uc6a9\ud588\uc744 \uac00\ub2a5\uc131\uacfc \uc885\uad50\uc801 \uc758\ubbf8\ub97c \uc0dd\uac01\ud560 \uc218 \uc788\uc9c0\ub9cc, \ud2b9\uc815 \uc2e0\uc758 \uc774\ub984\uc774\ub098 \uc815\ud655\ud55c \ud589\uc0ac \uc21c\uc11c\ub97c \uc815\ub2f5\ucc98\ub7fc \ubd99\uc77c \uc218\ub294 \uc5c6\ub2e4. \ub0a8\uc544 \uc788\ub294 \uad6c\uc870\uc640 \uc6b0\ub9ac\uac00 \ub367\ubd99\uc774\ub294 \uc124\uba85\uc744 \uad6c\ubd84\ud558\uba74 \uc624\ud788\ub824 \uacf5\uac04\uc744 \ub354 \uc790\uc138\ud788 \ubcf4\uac8c \ub41c\ub2e4. \uc778\ub354\uc2a4\uc758 \uc778\uc7a5\uc5d0\ub294 \uae30\ud638\uac00 \ub0a8\uc544 \uc788\uc9c0\ub9cc \uadf8 \uccb4\uacc4\ub294 \ud655\uc2e4\ud788 \ud574\ub3c5\ub418\uc9c0 \uc54a\uc558\ub2e4. \uadf8\ub798\uc11c \ub3c4\uc2dc \uc8fc\ubbfc\uc774 \uc790\uae30 \uc774\ub984\uacfc \uc9c1\uc5c5, \ubc95\uacfc \ubbff\uc74c\uc744 \uc5b4\ub5a4 \ub9d0\ub85c \uc124\uba85\ud588\ub294\uc9c0 \uc9c1\uc811 \uc77d\uae30 \uc5b4\ub835\ub2e4. \ubb3c\uac74\uacfc \uad6c\uc870\uac00 \uc911\uc694\ud55c \ub2e8\uc11c\uac00 \ub418\ub294 \uc774\uc720\ub2e4. \uadf8 \ube48\uc790\ub9ac\uc5d0 \uc775\uc219\ud55c \uc655\uad6d\uc758 \ubaa8\uc2b5\uc744 \uadf8\ub300\ub85c \ub123\uc73c\uba74 \ud3b8\ud558\uc9c0\ub9cc \uc704\ud5d8\ud558\ub2e4. \ud070 \uac74\ubb3c\uc744 \uad81\uc804\uc774\ub098 \uace1\ubb3c \ucc3d\uace0\ub77c\uace0 \ubd80\ub97c \ub54c\uc5d0\ub3c4 \ud574\uc11d\uc758 \uadfc\uac70\uc640 \ub17c\uc7c1\uc774 \uc788\ub2e4. \uc774\ub984\uc744 \ubaa8\ub978\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc544\uc26c\uc6c0\uc774\uba74\uc11c \uc131\uae09\ud55c \ub2f5\uc744 \uba48\ucd94\uac8c \ud558\ub294 \uc870\uac74\uc774\ub2e4. \uc778\ub354\uc2a4\uc758 \ud070 \ub3c4\uc2dc\ub4e4\uc740 \uc624\ub798 \ubc88\uc601\ud55c \ub4a4 \uc1e0\ud1f4\ud588\ub2e4. \uae30\ud6c4\uc640 \uac15\uc758 \ubcc0\ud654, \uc0dd\uc0b0\uacfc \uad50\uc5ed\uc758 \ubb38\uc81c \ub4f1 \uc5ec\ub7ec \uc694\uc778\uc774 \uc5f0\uad6c\ub41c\ub2e4. \ub204\uad70\uac00 \ud55c \ubc88 \uccd0\ub4e4\uc5b4\uc640 \ubaa8\ub450\ub97c \uc5c6\uc574\ub2e4\ub294 \uc774\uc57c\uae30 \ud558\ub098\ub85c \uc815\ub9ac\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \ub3c4\uc2dc\uac00 \uc904\uc5b4\ub4dc\ub294 \uac83\uacfc \uadf8\uacf3\uc758 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\ub450 \uc0ac\ub77c\uc9c0\ub294 \uac83\ub3c4 \uac19\uc740 \uc77c\uc774 \uc544\ub2c8\ub2e4. \uc720\uc801\uc758 \ubcc0\ud654\uc5d0\uc11c \uace7\ubc14\ub85c \ud55c \uac00\uc9c0 \ubbfc\uc871\uc758 \uc6b4\uba85\uc744 \ub2e8\uc815\ud558\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc624\ub798\ub41c \ub3c4\uc2dc\uc758 \ub9c8\uc9c0\ub9c9 \uc5ed\uc2dc \ub0a8\uc740 \uc790\ub8cc\ub97c \ub530\ub77c \uc870\uc2ec\uc2a4\ub7fd\uac8c \uc77d\uc5b4\uc57c \ud55c\ub2e4. \uccad\ub3d9\uc0c1\uc744 \ub2e4\uc2dc \ubcf4\uba74 \ub3c4\uc2dc\ub77c\ub294 \ub9d0\uc774 \ubcbd\ub3cc\uacfc \ub3c4\ub85c\ub9cc\uc744 \ub73b\ud558\uc9c0 \uc54a\uc558\ub2e4\ub294 \uac83\uc774 \ub290\uaef4\uc9c4\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \ubab8\uc744 \uafb8\ubbf8\uace0 \ubb3c\uac74\uc744 \ub9cc\ub4e4\uace0 \uc5b4\ub5a4 \ubaa8\uc2b5\uc744 \ub208\uc5ec\uaca8\ubcf4\uc558\ub2e4. \uc7a5\uc2e0\uad6c\uc758 \uc791\uc740 \uc120\ub3c4 \uadf8 \uc0dd\ud65c\uc774 \ub0a8\uae34 \ud754\uc801\uc774\ub2e4. \uc0c1 \uc18d \uc778\ubb3c\uc758 \uc774\ub984\uacfc \uc0dd\uac01\uc740 \uc54c \uc218 \uc5c6\ub2e4. \uadf8\ub798\ub3c4 \ubaa8\ub974\ub294 \ubd80\ubd84\uc744 \uac00\uc9dc \uc774\uc57c\uae30\ub85c \ucc44\uc6b0\uc9c0 \uc54a\uace0 \uac00\uae4c\uc774 \ubcfc \uc218\ub294 \uc788\ub2e4. \ubaa8\ud5e8\uc870\ub2e4\ub85c\uc758 \uc791\uc740 \uccad\ub3d9\uc0c1\uc740 \uac70\ub300\ud55c \ubb38\uba85\uc774\ub77c\ub294 \ub9d0 \ub4a4\uc5d0 \uad6c\uccb4\uc801\uc778 \ubab8\uacfc \ucde8\ud5a5\uc744 \uac00\uc9c4 \uc0ac\ub78c\uc774 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc77c\uae68\uc6b4\ub2e4."}, {"id": "mozambique-village-cultural-center", "title": "\uace0\ud5a5 \ub9c8\uc744\uc5d0 \ub465\uadfc \ucc3d\uc758 \ubb38\ud654 \uacf5\uac04\uc744 \ub9cc\ub4e4\ub2e4", "summary": "\ub9d0\ub791\uac00\ud0c0\ub098\uac00 \uace0\ud5a5\uc5d0\uc11c \uc2dc\uc791\ud55c \ubb38\ud654\uc13c\ud130\ub97c \ud1b5\ud574 \uc608\uc220\uacfc \ub9c8\uc744\uc758 \uad00\uacc4\ub97c \ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/mozambique-village-cultural-center/index.html", "image": "../media/mozambique-village-cultural-center.jpg", "alt": "\uace0\ud5a5 \ub9c8\uc744\uc5d0 \ub465\uadfc \ucc3d\uc758 \ubb38\ud654 \uacf5\uac04\uc744 \ub9cc\ub4e4\ub2e4\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\uace0\ud5a5 \ub9c8\uc744\uc5d0 \ub465\uadfc \ucc3d\uc758 \ubb38\ud654 \uacf5\uac04\uc744 \ub9cc\ub4e4\ub2e4 \ubaa8\uc7a0\ube44\ud06c \ud654\uac00\uc758 \uc77c\uc774 \uadf8\ub9bc \ubc16\uc73c\ub85c \uc774\uc5b4\uc9c4 \uc21c\uac04 \ub9d0\ub791\uac00\ud0c0\ub098\uac00 \uace0\ud5a5\uc5d0\uc11c \uc2dc\uc791\ud55c \ubb38\ud654\uc13c\ud130\ub97c \ud1b5\ud574 \uc608\uc220\uacfc \ub9c8\uc744\uc758 \uad00\uacc4\ub97c \ubd05\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ud654\uac00\uc758 \uc791\uc5c5\uc774\ub77c\uace0 \ud558\uba74 \uce94\ubc84\uc2a4 \uc55e\uc5d0 \uc120 \ubaa8\uc2b5\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7f0\ub370 \ubaa8\uc7a0\ube44\ud06c\uc758 \ud654\uac00 \ub9d0\ub791\uac00\ud0c0\ub098 \uc751\uc6e8\ub0d0\ub294 \uace0\ud5a5 \ub9c8\uc744\uc5d0 \ubb38\ud654\uc13c\ud130\ub97c \ub9cc\ub4dc\ub294 \uc77c\ub3c4 \uc2dc\uc791\ud588\ub2e4. \uadf8\ub9bc\uc744 \ub193\uc744 \ubcbd\ub9cc\uc774 \uc544\ub2c8\ub77c \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc77c \uacf5\uac04\uc744 \uc0dd\uac01\ud55c \uac83\uc774\ub2e4. \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc758 \uc5f0\uad6c \uc790\ub8cc\ub294 \uadf8\uac00 1995\ub144\uc5d0 \ub9c8\ud0c8\ub77c\ub098\uc5d0\uc11c \uc774 \uacf5\uac04\uc744 \ub9cc\ub4e4\uae30 \uc2dc\uc791\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc608\uc220 \uad50\uc721\uacfc \ub9c8\uc744 \ud589\uc0ac\ub97c \uc704\ud55c \uacf3\uc774\uc5c8\ub2e4. \uadf8\ub294 \uc5b4\ub9b0 \uc2dc\uc808 \uace0\ud5a5\uc5d0\uc11c \ub3c4\uc790\uae30\uc640 \ubc14\uad6c\ub2c8 \ub9cc\ub4e4\uae30, \uadf8\ub9bc \uac19\uc740 \uc9c0\uc5ed\uc758 \uc608\uc220\uacfc \uacf5\uc608\ub97c \uc811\ud588\ub2e4. \uc774\ud6c4 \ub3c4\uc2dc\ub85c \ub098\uac00 \uc77c\ud558\uace0 \uadf8\ub9bc\uc744 \ubc30\uc6b0\uba70 \uc790\uc2e0\uc758 \uae38\uc744 \ub113\ud614\ub2e4\uace0 \ubbf8\uc220\uad00\uc740 \uc18c\uac1c\ud55c\ub2e4. \uc774 \ub300\ubaa9\uc740 \uadf8\ub97c \uc544\ubb34\ub7f0 \ubc30\uc6c0\ub3c4 \uc5c6\uc774 \ub4f1\uc7a5\ud55c \ud2b9\ubcc4\ud55c \ucc9c\uc7ac\ub85c \ubcf4\ub294 \uc0dd\uac01\uacfc \ub2e4\ub974\ub2e4. \ub9c8\uc744\uc5d0\uc11c \ub9cc\ub09c \uc190\uc77c\uacfc \ub3c4\uc2dc\uc5d0\uc11c\uc758 \ubc30\uc6c0, \ub2e4\ub978 \uc608\uc220\uac00\ub4e4\uacfc\uc758 \uad00\uacc4\uac00 \ud568\uaed8 \uc313\uc778 \uc0b6\uc774\uc5c8\ub2e4. \uace0\ud5a5\uc758 \ubb38\ud654 \uacf5\uac04\ub3c4 \uadf8\ub7f0 \uc2dc\uac04\uc744 \ub5a0\uc62c\ub9ac\uba70 \ubcfc \uc218 \uc788\ub2e4. \ubbf8\uc220\uad00\uc740 \ubb38\ud654\uc13c\ud130\uc758 \uac74\ucd95\uc5d0 \uae30\ud558\ud559\uc801 \uad6c\uc131\uacfc \uc0b0\uc5c5 \uc7ac\ub8cc\uac00 \uc4f0\uc600\uace0, \ub465\uadfc \ucc3d\uacfc \uaca9\uc790, \uc778\ubb3c \ud615\ud0dc\uc758 \ubcbd\uba74 \ubd80\uc870 \uac19\uc740 \uc694\uc18c\uac00 \ub354\ud574\uc84c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uce5c\uad6c\uc774\uc790 \ud6c4\uc6d0\uc790\uc600\ub358 \uac74\ucd95\uac00 \ud310\ucd08 \uac8c\ub4dc\uc2a4\uc640\uc758 \uad00\uacc4\ub3c4 \ud568\uaed8 \uc18c\uac1c\ud55c\ub2e4. \uc774\ub984\ub09c \uac74\ucd95 \uc591\uc2dd\uc744 \uba3c\uc800 \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub465\uadfc \ucc3d\uc73c\ub85c \ube5b\uc774 \ub4e4\uc5b4\uc624\uace0 \ubcbd\uc5d0\ub3c4 \ubb34\uc5b8\uac00\ub97c \ud45c\ud604\ud560 \uc790\ub9ac\uac00 \uc788\ub294 \uacf5\uac04\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc5ec\uae30\uc758 \uc0bd\ud654\ub294 \uadf8 \uc0dd\uac01\uc744 \ub3d5\ub294 \uac1c\ub150 \uadf8\ub9bc\uc774\uba70 \uc2e4\uc81c \uac74\ubb3c\uc744 \uadf8\ub300\ub85c \uadf8\ub9b0 \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \ub9d0\ub791\uac00\ud0c0\ub098\ub294 1936\ub144\uc5d0 \ud0dc\uc5b4\ub098 2011\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub0ac\ub2e4. \uadf8 \uc0ac\uc774 \ubaa8\uc7a0\ube44\ud06c\ub294 \ud3ec\ub974\ud22c\uac08\uc758 \uc2dd\ubbfc \uc9c0\ubc30\ub97c \ubc97\uc5b4\ub098 \ub3c5\ub9bd\ud588\uace0, \ub2e4\uc2dc \ub0b4\uc804\uc744 \uacaa\uc5c8\ub2e4. \ud654\uac00\uc758 \uc0dd\uc560\ub97c \uc774\ub7f0 \ubcc0\ud654\uc640 \ub098\ub780\ud788 \ub193\uc73c\uba74 \ubb38\ud654\uc13c\ud130\uac00 \ub2e8\uc21c\ud55c \uac1c\uc778 \uae30\ub150\uad00\ub9cc\uc740 \uc544\ub2c8\uc5c8\ub2e4\ub294 \uc810\uc774 \ubcf4\uc778\ub2e4. \uc608\uc220\uc744 \ubc30\uc6b0\uace0 \ud568\uaed8 \ubaa8\uc77c \uc7a5\uc18c\ub97c \uace0\ud5a5\uc5d0 \ub9c8\ub828\ud558\ub294 \uc77c\uc5d0\ub294 \uadf8\uac00 \uc0b4\uc544\uc628 \uc0ac\ud68c\uc758 \uc2dc\uac04\uc774 \uacb9\uccd0 \uc788\uc5c8\ub2e4. \ubbf8\uc220\uad00\uc740 \uadf8\uc758 \ucd08\uae30 \uc791\ud488\uc5d0 \uc778\uac04\uacfc \ub3d9\ubb3c, \uad34\ubb3c \uac19\uc740 \ud615\uc0c1\ub4e4\uc774 \ube7d\ube7d\ud558\uac8c \ub4f1\uc7a5\ud55c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc885\uad50\uc640 \uc9c0\uc5ed\uc758 \uc804\uc2b9, \uc2dd\ubbfc \uc9c0\ubc30 \uc544\ub798\uc758 \ud604\uc2e4\uc774 \uac19\uc740 \ud654\uba74\uc5d0 \ub4e4\uc5b4\uc654\ub2e4. \uc775\uc219\ud55c \uc0b6\uc744 \uc608\uc058\uac8c \uc7a5\uc2dd\ud558\ub294 \uadf8\ub9bc\ub9cc \uadf8\ub9b0 \uac83\uc774 \uc544\ub2c8\ub2e4. \ubc14\ub00c\ub294 \uc138\uc0c1\uc744 \uc5b4\ub5a4 \ud615\ud0dc\ub85c \ud45c\ud604\ud560\uc9c0 \uace0\ubbfc\ud558\ub358 \uc791\uc5c5\uc740 \ud6d7\ub0a0 \uc0ac\ub78c\uc774 \ubaa8\uc774\ub294 \uac74\ucd95 \uacf5\uac04\uc73c\ub85c\ub3c4 \ub113\uc5b4\uc84c\ub2e4. \uadf8\uac00 \uc218\ub3c4\ub85c \ub098\uac14\uc744 \ub54c \ud751\uc778 \ubaa8\uc7a0\ube44\ud06c\uc778\uc5d0\uac8c \uc815\uaddc \ubbf8\uc220 \uad50\uc721\uc758 \uae30\ud68c\ub294 \ud3c9\ub4f1\ud558\uc9c0 \uc54a\uc558\ub2e4. \uc2dd\ubbfc \uc9c0\ubc30 \uc544\ub798\uc758 \uc778\uc885\uc801\u00b7\uc0ac\ud68c\uc801 \uc7a5\ubcbd\uc774 \uc788\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4. \ubbf8\uc220\uad00\uc774 \uad50\uc721 \uacbd\ub85c\ub97c \uc790\uc138\ud788 \uc124\uba85\ud558\ub294 \uc774\uc720\ub3c4 \uc5ec\uae30\uc5d0 \uc788\ub2e4. \ub204\uad6c\uc5d0\uac8c\ub098 \uac19\uc740 \ud559\uad50\uc758 \ubb38\uc774 \uc5f4\ub824 \uc788\uc5c8\ub294\ub370 \ud63c\uc790 \ub2e4\ub978 \uae38\uc744 \uace0\ub978 \uc0ac\ub78c\ucc98\ub7fc \uc0dd\uc560\ub97c \ub2e8\uc21c\ud654\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc0b0\uc5c5\ud559\uad50\uc640 \ubbf8\uc220\uc13c\ud130\uc5d0\uc11c\uc758 \ubc30\uc6c0, \ub2e4\ub978 \uc608\uc220\uac00\uc640\uc758 \ub9cc\ub0a8\uc774 \uc791\uc5c5\uc5d0 \uc601\ud5a5\uc744 \uc8fc\uc5c8\ub2e4. \ud310\ucd08 \uac8c\ub4dc\uc2a4\ub294 \uc791\uc5c5\uc2e4\uacfc \uc0dd\ud65c\uc744 \uc704\ud55c \uc9c0\uc6d0, \uc791\ud488 \uc8fc\ubb38\uc73c\ub85c\ub3c4 \uadf8\uc758 \ud65c\ub3d9\uc744 \ub3c4\uc654\ub2e4. \uce5c\uad6c\ub77c\ub294 \ub9d0 \uc548\uc5d0\ub3c4 \uc774\ub807\uac8c \uad6c\uccb4\uc801\uc778 \uc870\uac74\uc774 \uc788\uc5c8\ub2e4. \uadf8\ub9bc\uc744 \uacc4\uc18d \uadf8\ub9b4 \uc218 \uc788\ub294 \uc790\ub9ac\uc640 \uc2dc\uac04\uc774 \uc5b4\ub5bb\uac8c \ub9c8\ub828\ub418\uc5c8\ub294\uc9c0 \uc54c\uba74 \uc791\ud488 \ub4a4\uc758 \uad00\uacc4\uac00 \uc870\uae08 \ub354 \uc798 \ubcf4\uc778\ub2e4. \ubb38\ud654\uc13c\ud130\uc758 \ub465\uadfc \ucc3d\uacfc \uaca9\uc790\ub294 \ube5b\uacfc \uc2dc\uc120\uc744 \ub098\ub204\ub294 \uac74\ucd95 \uc694\uc18c\ub2e4. \ubcbd\uc758 \uc778\ubb3c \ubd80\uc870\ub294 \ud3c9\ud3c9\ud55c \ud654\uba74\uacfc \ub2ec\ub9ac \uc2e4\uc81c \uacf5\uac04\uc5d0\uc11c \uadf8\ub9bc\uc790\uc640 \ub450\uaed8\ub97c \ub9cc\ub4e0\ub2e4. \uac74\ucd95\uac00\uc758 \uc124\uacc4 \uc5b8\uc5b4\uc640 \ud654\uac00\uc758 \ud615\uc0c1 \uac10\uac01\uc744 \uac19\uc740 \uc7a5\uc18c\uc5d0\uc11c \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc5b4\ub290 \ud55c \uc694\uc18c\ub9cc \ubcf4\uace0 \uadf8 \uac74\ubb3c\uc744 \uc804\ud1b5\uc801\uc774\uac70\ub098 \uc678\ub798\uc801\uc774\ub77c\uace0 \ub2e8\uc815\ud558\uae30\uc5d0\ub294 \uc5ec\ub7ec \uacbd\ud5d8\uc774 \uc11e\uc5ec \uc788\ub2e4. \uc774\uac83\uc740 \uc0ac\uc9c4 \uc18d \uc138\ubd80\ub97c \uc678\uc6b0\uae30 \uc704\ud55c \ubaa9\ub85d\ubcf4\ub2e4 \ubcfc \uc21c\uc11c\ub97c \ub9cc\ub4dc\ub294 \uc124\uba85\uc774\ub2e4. \uc2e4\uc81c \uac74\ubb3c\uc758 \uc790\ub8cc\ub97c \ub9cc\ub098\uba74 \uba3c\uc800 \ucc3d\uacfc \ubcbd\uc758 \uad00\uacc4\ub97c, \ub2e4\uc74c\uc5d0\ub294 \uc0ac\ub78c\uc758 \ud615\uc0c1\uc774 \uc5b4\ub290 \ub192\uc774\uc5d0 \ub193\uc600\ub294\uc9c0 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ubcf8\ubb38\uc758 AI \uc0bd\ud654\ub294 \uc774\ub7f0 \uad00\uc2ec\uc744 \ub3d5\ub294 \uac1c\ub150 \uc774\ubbf8\uc9c0\uc774\ubbc0\ub85c \ucc3d\uc758 \uc815\ud655\ud55c \uac1c\uc218\ub098 \ubc30\uce58\ub97c \ud655\uc778\ud558\ub294 \uadfc\uac70\ub85c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud55c \uc810\uc758 \uadf8\ub9bc\uc740 \uadf8\uac83\uc744 \ubcf4\ub294 \uc0ac\ub78c\uc744 \ub9cc\ub09c\ub2e4. \uad50\uc721 \uacf5\uac04\uc740 \uadf8\uacf3\uc5d0\uc11c \ub2e4\ub978 \uc0ac\ub78c\uc774 \uadf8\ub9bc\uc744 \uadf8\ub824 \ubcfc \uac00\ub2a5\uc131\uc744 \ub9cc\ub4e0\ub2e4. \ub450 \uc77c\uc740 \uc11c\ub85c \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uc774\uc5b4\uc9c4\ub2e4. \uc644\uc131\ub41c \uc791\ud488\uc758 \uba85\uc131\uacfc \uadf8 \ub2e4\uc74c \uc791\uc5c5\uc744 \uc2dc\uc791\ud560 \uc0ac\ub78c\uc758 \uc790\ub9ac\ub97c \ud568\uaed8 \uc0dd\uac01\ud558\uba74, \ud654\uac00\uac00 \uc65c \uac74\ubb3c\uacfc \uc9c0\uc5ed \ud589\uc0ac\uc5d0\ub3c4 \uad00\uc2ec\uc744 \uac00\uc84c\ub294\uc9c0 \uc774\ud574\ud560 \uc2e4\ub9c8\ub9ac\uac00 \uc0dd\uae34\ub2e4. \ubb3c\ub860 \uc2e4\uc81c \uc774\uc6a9\uc790\uc758 \uacbd\ud5d8 \uc804\uccb4\ub97c \uc774 \uc124\ub9bd \ubaa9\uc801\ub9cc\uc73c\ub85c \uc54c \uc218\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c \ud655\uc778\ud558\ub294 \uac83\uc740 \uc608\uc220 \uad50\uc721\uacfc \uacf5\ub3d9\uccb4 \ud65c\ub3d9\uc744 \uc704\ud55c \uacf5\uac04\uc744 \uace0\ud5a5\uc5d0 \uc2dc\uc791\ud588\ub2e4\ub294 \uc120\ud0dd\uc774\ub2e4. \uba40\ub9ac \uc788\ub294 \ub300\ub3c4\uc2dc\uc758 \ubbf8\uc220\uad00\uc5d0 \uc791\ud488\uc774 \uac78\ub9ac\ub294 \uac83\uacfc \uc790\uae30\uac00 \uc790\ub780 \ub9c8\uc744\uc5d0\uc11c \uc608\uc220\uc744 \ub9cc\ub0a0 \uc218 \uc788\uac8c \ud558\ub294 \uc77c\uc774, \ud55c \uc0ac\ub78c\uc758 \ud65c\ub3d9 \uc548\uc5d0\uc11c \ub098\ub780\ud788 \uc774\uc5b4\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \ubb38\ud654\uc13c\ud130\uac00 \uad50\uc721\uacfc \ub9c8\uc744 \ud589\uc0ac\ub97c \uc704\ud574 \uc2dc\uc791\ub418\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc778\uc0c1\uc801\uc774\ub2e4. \uc608\uc220\uc744 \uba40\ub9ac \uc788\ub294 \uc804\uc2dc\uc7a5\uc5d0\uc11c\ub9cc \ub9cc\ub098\ub294 \ub300\uc2e0 \uc790\uc2e0\uc774 \uc790\ub780 \uacf3\uc5d0\uc11c \ubc30\uc6b0\uace0 \ubaa8\uc77c \uc218 \uc788\ub3c4\ub85d \ud558\ub294 \uc120\ud0dd\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \uc774 \ud654\uac00\ub294 \uadf8\ub9bc\ubfd0 \uc544\ub2c8\ub77c \uae00\uacfc \uc2dc, \uad50\uc721\uacfc \uc870\uac01\uc5d0\uc11c\ub3c4 \ud65c\ub3d9\ud588\ub2e4. \uace0\ud5a5\uc758 \uacf5\uac04\uc740 \uadf8 \uc5ec\ub7ec \uc77c\uc744 \ub2f4\uc744 \ub610 \ud558\ub098\uc758 \ud615\ud0dc\ub85c \uc77d\ud78c\ub2e4. \uadf8\ub9bc \ud55c \uc810\uc744 \ub0a8\uae30\ub294 \uac83\uacfc \ud568\uaed8, \ub2e4\uc74c \uc0ac\ub78c\uc774 \ubb34\uc5b8\uac00\ub97c \uc2dc\uc791\ud560 \uc790\ub9ac\ub3c4 \ub9cc\ub4e4\uace0 \uc2f6\uc5c8\ub358 \uac83\uc774\ub2e4."}, {"id": "new-york-before-new-amsterdam", "title": "\ub274\uc695 \u2014 \ud55c\ub54c\ub294 \ub274\uc554\uc2a4\ud14c\ub974\ub2f4\uc774\uc5c8\ub2e4", "summary": "1664\ub144\uc758 \uc2e4\uc81c \uadf8\ub9bc\uc5d0\uc11c \ucd9c\ubc1c\ud574 \ub124\ub35c\ub780\ub4dc \uc2dd\ubbfc \ub3c4\uc2dc\uc758 \uad50\uc5ed\uacfc \uc774\ub984 \ubcc0\ud654, \uac00\ub824\uc9c4 \ub178\ub3d9\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/new-york-before-new-amsterdam/index.html", "image": "../media/new-york-before-new-amsterdam.png", "alt": "1664\ub144 \ube59\ubcf8\uc2a4\uc758 \ub274\uc554\uc2a4\ud14c\ub974\ub2f4 \uadf8\ub9bc. \ubb3c\uac00\uc758 \ub0ae\uc740 \uac74\ubb3c\uacfc \uc55e\ucabd\uc758 \ubc30\ub4e4.", "text": "\ub274\uc695 \u2014 \ud55c\ub54c\ub294 \ub274\uc554\uc2a4\ud14c\ub974\ub2f4\uc774\uc5c8\ub2e4 \ub3c4\uc2dc\uc758 \uc774\ub984\uc744 \ubc14\uafbc \ubc30\uc640 \uad50\uc5ed, \uadf8\ub9ac\uace0 \uc131\ubcbd 1664\ub144\uc758 \uc2e4\uc81c \uadf8\ub9bc\uc5d0\uc11c \ucd9c\ubc1c\ud574 \ub124\ub35c\ub780\ub4dc \uc2dd\ubbfc \ub3c4\uc2dc\uc758 \uad50\uc5ed\uacfc \uc774\ub984 \ubcc0\ud654, \uac00\ub824\uc9c4 \ub178\ub3d9\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ub274\uc695\uc774\ub77c\ub294 \uc774\ub984\uc740 \ub108\ubb34 \uc775\uc219\ud574\uc11c \ucc98\uc74c\ubd80\ud130 \uadf8 \uc774\ub984\uc774\uc5c8\uc744 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uadf8\ub7ec\ub098 \ub9e8\ud574\ud2bc \ub0a8\ucabd\uc5d0 \uc790\ub9ac\ud55c \ucd08\uae30\uc758 \uc720\ub7fd \uc2dd\ubbfc \ub3c4\uc2dc\ub294 \ub274\uc554\uc2a4\ud14c\ub974\ub2f4\uc73c\ub85c \ubd88\ub838\ub2e4. \uc554\uc2a4\ud14c\ub974\ub2f4\uc5d0 \uc0c8\ub85c\uc6b4 \uacf3\uc744 \ub73b\ud558\ub294 \ub9d0\uc744 \ubd99\uc778 \uc774\ub984\uc774\ub2e4. \ub3c4\uc2dc \uc774\ub984\uc5d0 \ubc14\ub2e4 \uac74\ub108\uc758 \uace0\ud5a5\uc774 \ub4e4\uc5b4 \uc788\uc5c8\ub358 \uc148\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \ub124\ub35c\ub780\ub4dc\uc758 \ud654\uac00\uc774\uc790 \uc9c0\ub3c4 \uc81c\uc791\uc790 \uc694\ud558\ub124\uc2a4 \ube59\ubcf8\uc2a4\uac00 1664\ub144\uc5d0 \uadf8\ub9b0 \ub3c4\uc2dc\uc758 \ubaa8\uc2b5\uc774\ub2e4. \ubb3c\uac00\uc758 \ubc30\uc640 \ub0ae\uc740 \uac74\ubb3c\ub4e4\uc744 \ubcf4\uba74 \uc624\ub298\uc758 \ub192\uc740 \ube4c\ub529 \uc232\uacfc\ub294 \ub2e4\ub978 \ud48d\uacbd\uc774 \uc5f4\ub9b0\ub2e4. \uadf8 \uc791\uc740 \ud574\uc548\uc120\uc5d0 \uc5ec\ub7ec \ub300\ub959\uc758 \uad00\uacc4\uac00 \uacb9\uccd0 \uc788\uc5c8\ub2e4. \uad50\uc7ac\ub294 \ub124\ub35c\ub780\ub4dc\uc778\ub4e4\uc774 1624\ub144 \uc624\ub298\ub0a0 \ub9e8\ud574\ud2bc \uc12c\uc758 \ub0a8\ucabd\uc5d0 \ub274\uc554\uc2a4\ud14c\ub974\ub2f4\uc744 \uc138\uc6e0\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc774\uac83\uc740 \uc0ac\ub78c\uc774 \uc5c6\ub358 \uc12c\uc5d0\uc11c \ub3c4\uc2dc\uc758 \uc5ed\uc0ac\uac00 \ucc98\uc74c \uc2dc\uc791\ub418\uc5c8\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uc720\ub7fd\uc778\uc774 \uc624\uae30 \uc804\ubd80\ud130 \uc6d0\uc8fc\ubbfc \uacf5\ub3d9\uccb4\uc758 \ub545\uacfc \uc0dd\ud65c\uc774 \uc788\uc5c8\ub2e4. \uc2dd\ubbfc \ub3c4\uc2dc\uc758 \uc124\ub9bd \uc5f0\ub3c4\ub294 \ud2b9\uc815 \uc138\ub825\uc774 \uac70\uc810\uc744 \ub9cc\ub4e0 \ub54c\ub97c \uc54c\ub824 \uc900\ub2e4. \uadf8 \uc774\uc804\uc758 \uc0ac\ub78c\uacfc \uc7a5\uc18c\uae4c\uc9c0 \uc9c0\uc6cc \uc8fc\ub294 \uc22b\uc790\ub294 \uc544\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \uc61b \uc774\ub984\uc744 \uc77d\uc744 \ub54c\ub3c4 \ub204\uad6c\uc758 \uae30\ub85d\uc5d0\uc11c \ubd99\uc778 \uc774\ub984\uc778\uc9c0 \ubb3c\uc5b4\ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \uac19\uc740 \ub545\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\uac00 \ud558\ub098\uc758 \uc5b8\uc5b4\ub85c\ub9cc \uc2dc\uc791\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub124\ub35c\ub780\ub4dc \uc2dd\ubbfc\uc790\ub4e4\uc758 \uac70\uc8fc\uc9c0\ub294 \ub274\uc554\uc2a4\ud14c\ub974\ub2f4\uc5d0\uc11c \ud5c8\ub4dc\uc2a8\uac15 \uacc4\uace1\uc744 \ub530\ub77c \ubd81\ucabd\uc73c\ub85c \uc774\uc5b4\uc84c\ub2e4. \uad50\uc7ac\ub294 \ub18d\uc5c5\ub3c4 \uc774\ub8e8\uc5b4\uc84c\uc9c0\ub9cc \ubaa8\ud53c \uad50\uc5ed\uc774 \uc911\uc694\ud55c \uc218\uc785\uc6d0\uc774\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud56d\uad6c\uc5d0 \ub3c4\ucc29\ud55c \ubb3c\uac74\uc740 \ubc14\ub2e4 \ubc14\ub85c \uc606\uc5d0\uc11c\ub9cc \ub9cc\ub4e4\uc5b4\uc9c4 \uac83\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc9c0\uae08\uc758 \ub274\uc695\uc744 \uae08\uc735\uacfc \ubb38\ud654\uc758 \ub3c4\uc2dc\ub85c \uba3c\uc800 \ub5a0\uc62c\ub9ac\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ub3d9\ubb3c\uc758 \ubaa8\ud53c\uac00 \ub0af\uc120 \ucd9c\ubc1c\uc810\ucc98\ub7fc \ubcf4\uc778\ub2e4. \ud558\uc9c0\ub9cc \ucd08\uae30\uc758 \uad50\uc5ed\uc740 \ub0b4\ub959\uacfc \uac15, \ub300\uc11c\uc591\uc744 \uc5f0\uacb0\ud588\ub2e4. \uadf8\ub9bc \uc18d\uc758 \ubc30 \ud55c \ucc99\uc744 \ubcfc \ub54c\ub3c4 \uadf8 \ubc30\uc5d0 \uc2e4\ub9b4 \ubb3c\uac74\uc774 \uc5b4\ub514\uc11c \uc654\ub294\uc9c0 \uc0dd\uac01\ud558\uba74 \ub3c4\uc2dc\uc758 \uc9c0\ub3c4\uac00 \ub113\uc5b4\uc9c4\ub2e4. \ucd08\uae30\uc5d0\ub294 \ubaa8\ud53c\uc640 \uc720\ub7fd\uc758 \uae08\uc18d \ub3c4\uad6c, \ubaa8\uc9c1\ubb3c, \ubb34\uae30 \ub4f1\uc744 \uad50\ud658\ud558\ub294 \uad00\uacc4\uac00 \uc788\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \uad50\uc5ed\uc774 \uc774\uc5b4\uc84c\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uace7\ubc14\ub85c \ud3c9\ub4f1\ud558\uace0 \ud3c9\ud654\ub85c\uc6b4 \uacf5\uc874\uc73c\ub85c \ubc14\uafc0 \uc218\ub294 \uc5c6\ub2e4. \uc2dd\ubbfc \uc9c0\ubc30\uc758 \ud655\ub300\uc640 \uc6d0\uc8fc\ubbfc\uc5d0 \ub300\ud55c \uc694\uad6c\ub294 \ucda9\ub3cc\ub85c \uc774\uc5b4\uc84c\ub2e4. \uad50\uc7ac\ub294 \ub124\ub35c\ub780\ub4dc\uc778\ub4e4\uc774 \uc790\uc2e0\ub4e4\uc774 \uc81c\uacf5\ud588\ub2e4\uace0 \uc5ec\uae34 \ud61c\ud0dd\uc5d0 \ub300\uac00\ub97c \uc694\uad6c\ud558\uba70 \uac08\ub4f1\uc774 \ucee4\uc84c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc774 \ub300\ubaa9\uc5d0\uc11c\ub294 \uac70\ub798\uc758 \ubaa9\ub85d\ubcf4\ub2e4 \ub204\uac00 \uc870\uac74\uc744 \uc815\ud558\ub824 \ud588\ub294\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \uc11c\ub85c \ubb3c\uac74\uc744 \uc8fc\uace0\ubc1b\uc558\ub2e4\uace0 \ud798\uc758 \ucc28\uc774\ub098 \ub545\uc744 \ub458\ub7ec\uc2fc \ubb38\uc81c\uac00 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ub3c4\uc2dc\ub97c \ubc29\uc5b4\ud558\uae30 \uc704\ud55c \uc2dc\uc124\uc740 \ub2f9\uc2dc \uac70\uc8fc\uc9c0\uc758 \uacbd\uacc4\uc5d0 \uc138\uc6cc\uc84c\ub2e4. \uad50\uc7ac\ub294 \ub124\ub35c\ub780\ub4dc\uc778\ub4e4\uc774 \ub178\uc608\ud654\ub41c \uc544\ud504\ub9ac\uce74\uc778\ub4e4\uc5d0\uac8c \uc774 \ubc29\uc5b4 \uc2dc\uc124\uc744 \uc9d3\ub3c4\ub85d \uac15\uc694\ud588\ub2e4\uace0 \uae30\ub85d\ud55c\ub2e4. \uadf8 \ubcbd\uc744 \ub530\ub77c \ub09c \uae38\uc774 \uc6d4\uc2a4\ud2b8\ub9ac\ud2b8\ub77c\ub294 \uc774\ub984\uc73c\ub85c \ubd88\ub838\ub2e4. \uc624\ub298\uc758 \uae08\uc735\uac00\ub97c \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uc774\ub984 \ub4a4\uc5d0 \uac15\uc81c \ub178\ub3d9\uc758 \uc5ed\uc0ac\uac00 \uc788\ub294 \uac83\uc774\ub2e4. \uae38 \uc774\ub984\uc758 \uc720\ub798\ub97c \uc548\ub2e4\ub294 \uac83\uc740 \uc7ac\ubbf8\uc788\ub294 \ub9d0\ud480\uc774\ub9cc\uc740 \uc544\ub2c8\ub2e4. \ub204\uac00 \ud798\ub4e0 \uc77c\uc744 \ud588\uc73c\uba70 \ub204\uad6c\uc758 \uc774\ub984\uc740 \uae30\ub150\ub418\uc9c0 \uc54a\uc558\ub294\uc9c0 \ub3cc\uc544\ubcfc \uae30\ud68c\uc774\uae30\ub3c4 \ud558\ub2e4. \ub3c4\uc2dc\uc758 \uc720\uba85\ud55c \uc8fc\uc18c\uc5d0\ub294 \uc54c\ub824\uc9c4 \uc131\uacf5\ub2f4 \ubc16\uc758 \uc2dc\uac04\uc774 \ub4e4\uc5b4 \uc788\ub2e4. 1664\ub144 \uc601\uad6d\uc758 \uad70\uc0ac \uc6d0\uc815\ub300\uac00 \ub274\uc554\uc2a4\ud14c\ub974\ub2f4\uc5d0 \ub3c4\ucc29\ud588\ub2e4. \ub124\ub35c\ub780\ub4dc\uc640 \uc601\uad6d \uc0ac\uc774\uc758 \ub354 \ud070 \uacbd\uc7c1 \uc18d\uc5d0\uc11c \ubc8c\uc5b4\uc9c4 \uc77c\uc774\uc5c8\ub2e4. \uad50\uc7ac\ub294 \ubc29\uc5b4\uac00 \uc5b4\ub835\ub2e4\uace0 \ubcf8 \ub124\ub35c\ub780\ub4dc \uce21\uc774 \ud56d\ubcf5\ud588\uace0, \ub3c4\uc2dc \uc774\ub984\uc774 \ub274\uc695\uc73c\ub85c \ubc14\ub00c\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc0c8 \uc774\ub984\uc740 \uc6d0\uc815\uc744 \uc870\uc9c1\ud55c \uc694\ud06c \uacf5\uc791\uc744 \uae30\ub9ac\ub294 \uac83\uc774\uc5c8\ub2e4. \uc774\ub984 \ubcc0\uacbd\uc740 \ub2e8\uc21c\ud55c \uc0c8 \uac04\ud310\uc774 \uc544\ub2c8\ub77c \uc5b4\ub5a4 \uad8c\ub825\uc774 \uadf8 \uc7a5\uc18c\ub97c \ucc28\uc9c0\ud588\ub294\uc9c0 \ub4dc\ub7ec\ub0b4\ub294 \ud45c\uc2dc\uc600\ub2e4. \ub2e4\ub9cc \uadf8 \uc21c\uac04 \uc8fc\ubbfc\uc758 \ubaa8\ub4e0 \uc2b5\uad00\uacfc \uc5b8\uc5b4, \uc9d1\uc758 \ubaa8\uc2b5\uae4c\uc9c0 \ud55c \ubc88\uc5d0 \ub2ec\ub77c\uc84c\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub3c4\uc2dc\uc758 \uc774\ub984\uc774 \ub2ec\ub77c\uc9c0\uba74 \uc5ed\uc0ac\uac00 \ub450 \ub3d9\uac15 \ub09c \uac83\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ubc30\uac00 \ub4dc\ub098\ub4dc\ub294 \uc9c0\ub9ac\uc640 \uc774\ubbf8 \ud615\uc131\ub41c \uac70\ub798 \uad00\uacc4, \uadf8\uacf3\uc5d0 \uc0ac\ub294 \uc0ac\ub78c\ub4e4\uc740 \uc0c8 \uad8c\ub825 \uc544\ub798\uc5d0\uc11c\ub3c4 \uc774\uc5b4\uc9c0\ub294 \uc870\uac74\uc774\uc5c8\ub2e4. \uc9c0\ubc30\uc790\uac00 \ubc14\ub00c\ub294 \uc77c\uacfc \uc0dd\ud65c\uc758 \ubaa8\ub4e0 \uc694\uc18c\uac00 \uad50\uccb4\ub418\ub294 \uc77c\uc740 \uac19\uc740 \uc18d\ub3c4\ub85c \uc77c\uc5b4\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc774 \uc810\uc744 \uc0dd\uac01\ud558\uba74 \ub274\uc554\uc2a4\ud14c\ub974\ub2f4\uc740 \uc624\ub298\uc758 \ub274\uc695\uacfc \ubb34\uad00\ud55c \uc0ac\ub77c\uc9c4 \ub3d9\ub124\uac00 \uc544\ub2c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \ud604\ub300 \ub3c4\uc2dc\uc758 \uc131\uaca9\uc744 \ubaa8\ub450 \ucd08\uae30 \uc2dd\ubbfc\uc9c0\uc5d0\uc11c \uc124\uba85\ud560 \uc218\ub3c4 \uc5c6\ub2e4. \uc624\ub79c \ubcc0\ud654 \uac00\uc6b4\ub370 \ud558\ub098\uc758 \uce35\uc744 \uc77d\ub294 \uac83\uc774\ub2e4. \uc61b \uc774\ub984\uc740 \uadf8 \uce35\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \uc190\uc7a1\uc774\uac00 \ub41c\ub2e4. \ube59\ubcf8\uc2a4\uc758 \uadf8\ub9bc\uc5d0\uc11c\ub294 \ubb3c\uacfc \uac74\ubb3c \uc0ac\uc774\uc758 \uad00\uacc4\ub97c \uba3c\uc800 \uc0b4\ud3b4\ubcf4\uc790. \ubc14\ub2e4 \ucabd\uc5d0\uc11c \ubc14\ub77c\ubcf4\ub294 \ub3c4\uc2dc\uc758 \ubaa8\uc2b5\uc5d0\ub294 \ud56d\uad6c\uc758 \uc131\uaca9\uc774 \uc798 \ub4dc\ub7ec\ub09c\ub2e4. \uc624\ub298\uc758 \uc9c0\ub3c4\uc5d0\uc11c \uc775\uc219\ud55c \uac70\ub9ac\uc640 \uac74\ubb3c \ud558\ub098\ud558\ub098\ub97c \uadf8\ub300\ub85c \ucc3e\uc73c\ub824 \ud558\uae30\ubcf4\ub2e4 \ub2f9\uc2dc \ud654\uac00\uac00 \uc5b4\ub5a4 \uc724\uacfd\uc744 \ubcf4\uc5ec \uc8fc\uc5c8\ub294\uc9c0 \ubcf4\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uadf8\ub9bc\uc740 \uc0ac\uc9c4\uc774\ub098 \uc815\ubc00 \uce21\ub7c9\ub3c4\uc640 \uac19\uc9c0 \uc54a\ub2e4. \ud654\uac00\uc758 \uc2dc\uc810\uacfc \ud45c\ud604\uc744 \uac70\uce5c \uc790\ub8cc\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc6d0\uc8fc\ubbfc\uc758 \uc0dd\ud65c\uacfc \uac15\uc81c \ub178\ub3d9\uae4c\uc9c0 \uc774 \ud654\uba74 \ud55c \uc7a5\uc774 \ubaa8\ub450 \ub2f4\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub798\uc11c \uadf8\ub9bc\uc744 \uac10\uc0c1\ud558\ub294 \uc77c\uacfc \uc5ed\uc0ac \uae30\ub85d\uc744 \ud568\uaed8 \uc77d\ub294 \uc77c\uc774 \uc11c\ub85c\ub97c \ubcf4\uc644\ud55c\ub2e4. \ub274\uc695\uc758 \uc61b \uc774\ub984\uc740 \uc720\ub7fd\uc758 \ub3c4\uc2dc \uc774\ub984\uc774 \ubc14\ub2e4\ub97c \uac74\ub108\uc628 \uc774\uc57c\uae30\uc774\uba74\uc11c, \uad50\uc5ed\uacfc \uc2dd\ubbfc \uacbd\uc7c1\uc774 \uacb9\uce5c \uc774\uc57c\uae30\ub2e4. \ubaa8\ud53c\uac00 \uc624\uac04 \uac15\uacfc \ud56d\uad6c, \ub178\uc608\ud654\ub41c \uc774\ub4e4\uc774 \uc138\uc6b4 \ubc29\uc5b4 \uc2dc\uc124, \uc601\uad6d \uc6d0\uc815\ub300\uac00 \ub4e4\uc5b4\uc628 \ubb3c\uae38\uc774 \uc774\ub984\uc758 \ubcc0\ud654 \ub4a4\uc5d0 \ub193\uc5ec \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \ub3c4\uc2dc \uc774\ub984\uc758 \uc720\ub798\ub97c \ub9cc\ub098\uba74 \ub204\uac00 \ubd99\uc600\ub294\uc9c0\ub9cc \ubb3b\uc9c0 \ub9d0\uace0 \uadf8 \uc774\uc804\uc5d0\ub294 \ub204\uac00 \uc0b4\uc558\ub294\uc9c0\ub3c4 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc9e7\uc740 \uc774\ub984\uc740 \ub9ce\uc740 \uc2dc\uac04\uc744 \uc811\uc5b4 \ub123\uace0 \uc788\ub2e4. \ub274\uc554\uc2a4\ud14c\ub974\ub2f4\uc774\ub77c\ub294 \uc624\ub798\ub41c \uc774\ub984\uc744 \ud3b4 \ubcf4\ub294 \uc77c\uc740 \uc775\uc219\ud55c \ub274\uc695\uc744 \uc870\uae08 \ub354 \ub113\uac8c \uc774\ud574\ud558\ub294 \uc2dc\uc791\uc774 \ub41c\ub2e4."}, {"id": "newton-mint-work", "title": "\ub274\ud134\uc758 \ub610 \ub2e4\ub978 \uc77c\ud130\ub294 \uc870\ud3d0\uad6d\uc774\uc5c8\ub2e4", "summary": "\uacfc\ud559\uc790\uc758 \uc774\ub984 \uc606\uc5d0 \uc870\ud3d0\uad6d\uc774\ub77c\ub294 \uc9c1\uc7a5\uc774 \ubd99\uc2b5\ub2c8\ub2e4. \ub274\ud134\uc740 \uadf8\uacf3\uc5d0\uc11c \ubb34\uc2a8 \uc77c\uc744 \ud588\uc744\uae4c\uc694?", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/newton-mint-work/index.html", "image": "../media/newton-mint-work.jpg", "alt": "\uae43\ud39c\uacfc \ube48 \uc7a5\ubd80, \uc740\ube5b \ub3d9\uc804, \uc791\uc740 \ud504\ub9ac\uc998\uc774 \ub193\uc778 \ucc45\uc0c1\uc758 \uc124\uba85\uc6a9 AI \uc0bd\ud654", "text": "\ub274\ud134\uc758 \ub610 \ub2e4\ub978 \uc77c\ud130\ub294 \uc870\ud3d0\uad6d\uc774\uc5c8\ub2e4 \ub3d9\uc804\uc758 \ubb34\uac8c\ub97c \uc0b4\ud53c\ub358 \uacfc\ud559\uc790\uc758 \uc77c\uc0c1 \uacfc\ud559\uc790\uc758 \uc774\ub984 \uc606\uc5d0 \uc870\ud3d0\uad6d\uc774\ub77c\ub294 \uc9c1\uc7a5\uc774 \ubd99\uc2b5\ub2c8\ub2e4. \ub274\ud134\uc740 \uadf8\uacf3\uc5d0\uc11c \ubb34\uc2a8 \uc77c\uc744 \ud588\uc744\uae4c\uc694? \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ub274\ud134\uc774\ub77c\ub294 \uc774\ub984\uc744 \ub4e4\uc73c\uba74 \uacfc\ud559\ucc45\uc758 \ucd08\uc0c1\ud654\ubd80\ud130 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7f0\ub370 \uadf8\uc758 \uc774\ub825\uc5d0\ub294 \uc870\uae08 \ub2e4\ub978 \uc7a5\uc18c\ub3c4 \ub098\uc628\ub2e4. \uae08\uc18d\uc744 \ub179\uc774\uace0 \ub3d9\uc804\uc744 \ub9cc\ub4dc\ub294 \uc655\ub9bd\uc870\ud3d0\uad6d\uc774\ub2e4. \uc11c\ub958\uc5d0 \uc11c\uba85\ub9cc \ud558\ub7ec \uac00\ub054 \ub4e4\ub978 \uba85\uc608\uc9c1\uc774\uc5c8\uc744\uae4c. \uc601\uad6d \uc655\ub9bd\uc870\ud3d0\uad6d\uc758 \uc124\uba85\uc744 \uc77d\uc73c\uba74 \uaf64 \ubc14\uc05c \uc9c1\uc7a5\uc774\uc5c8\uc74c\uc744 \uc54c \uc218 \uc788\ub2e4. \ub274\ud134\uc740 1696\ub144 \uadf8\uacf3\uc5d0\uc11c \uc77c\uc744 \uc2dc\uc791\ud588\uace0, \ub3d9\uc804\uc758 \ubb34\uac8c\uc640 \ud488\uc9c8\uc744 \ud655\uc778\ud558\ub294 \ubb38\uc81c\uc5d0 \uae4a\uc774 \uad00\uc5ec\ud588\ub2e4. \uc2e4\ud5d8\uc2e4\uc744 \ub5a0\ub09c \ub4a4\uc5d0\ub3c4 \uc815\ud655\ud558\uac8c \uc7ac\uace0 \ud655\uc778\ud558\ub294 \uc77c\uc774 \uadf8\ub97c \uae30\ub2e4\ub838\ub358 \uc148\uc774\ub2e4. \ub274\ud134\uc774 \uc870\ud3d0\uad6d\uc5d0 \ub4e4\uc5b4\uac14\uc744 \ubb34\ub835\uc5d0\ub294 \uc624\ub798\ub41c \uc740\ud654\ub97c \uc0c8\ub85c \ub9cc\ub4dc\ub294 \ud070 \uc791\uc5c5\uc774 \uc9c4\ud589\ub418\uace0 \uc788\uc5c8\ub2e4. \uc5ec\ub7ec \uc9c0\uc5ed\uc5d0 \ubcf4\uc870 \uc870\ud3d0 \uc2dc\uc124\uae4c\uc9c0 \ub9c8\ub828\ud560 \ub9cc\ud07c \uaddc\ubaa8\uac00 \ucef8\ub2e4. \uc0c8\ub85c\uc6b4 \uc9c1\uc7a5\uc5d0 \uc801\uc751\ud560 \uc2dc\uac04\ubd80\ud130 \ub109\ub109\ud558\uac8c \uc8fc\uc5b4\uc9c4 \uc0c1\ud669\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\uc740 \uc774 \uc791\uc5c5\uc774 \uc57d 3\ub144 \uc548\uc5d0 \ub9c8\ubb34\ub9ac\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub274\ud134 \ud63c\uc790\uc11c \ubaa8\ub4e0 \uc77c\uc744 \ud574\ub0c8\ub2e4\ub294 \uc774\uc57c\uae30\ub294 \uc544\ub2c8\ub2e4. \uc218\ub9ce\uc740 \uc0ac\ub78c\uacfc \uc2dc\uc124\uc774 \uc6c0\uc9c1\uc774\ub294 \uc870\uc9c1 \uc548\uc5d0\uc11c \uadf8\ub3c4 \uc77c\uc744 \ub9e1\uc558\ub2e4. \uc774\ud6c4\uc5d0\ub294 \ub3d9\uc804\uc744 \uc704\uc870\ud558\uac70\ub098 \ud6fc\uc190\ud55c \uc0ac\ub78c\ub4e4\uc744 \uc870\uc0ac\ud558\ub294 \uc77c\uc5d0\ub3c4 \uad00\uc5ec\ud588\ub2e4. \ubc94\uc8c4\uc790\uc640 \uc81c\ubcf4\uc790\ub97c \uc9c1\uc811 \ub9cc\ub098 \uc870\uc0ac\ud55c \uae30\ub85d\ub3c4 \uc18c\uac1c\ub41c\ub2e4. \uc6b0\ub9ac\uac00 \uc775\uc219\ud558\uac8c \ub5a0\uc62c\ub9ac\ub294 \uacfc\ud559\uc790\uc758 \ubaa8\uc2b5\uc5d0 \uc11c\ub958\uc640 \uba74\ub2f4 \uc77c\uc815\uc774 \ub354\ud574\uc9c4\ub2e4. \uadf8\ub807\ub2e4\uace0 \uac70\ub9ac\uc5d0\uc11c \ubc94\uc778\uc744 \ucad3\ub294 \uc7a5\uba74\uae4c\uc9c0 \uc0c1\uc0c1\ud574 \ub123\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc2e4\uc81c\ub85c \ud655\uc778\ub418\ub294 \uc5c5\ubb34\ub9cc\uc73c\ub85c\ub3c4 \uadf8\uc758 \uc870\ud3d0\uad6d \uc0dd\ud65c\uc740 \ucda9\ubd84\ud788 \ubd84\uc8fc\ud574 \ubcf4\uc778\ub2e4. \uc870\ud3d0\uad6d\uc5d0\uc11c \uc911\uc694\ud55c \uac83\uc740 \ub3d9\uc804\uc5d0 \uc608\uc05c \uadf8\ub9bc\uc744 \ucc0d\ub294 \uc77c\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc815\ud574\uc9c4 \ubb34\uac8c\uc640 \uae08\uc18d\uc758 \uc21c\ub3c4\ub97c \ub9de\ucd94\uace0, \ub3d9\uc804\ub07c\ub9ac\uc758 \ucc28\uc774\ub97c \uc904\uc774\ub294 \uac83\ub3c4 \ud544\uc694\ud588\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\uc740 \ub274\ud134\uc758 \uae30\uc5ec \uac00\uc6b4\ub370 \ud558\ub098\ub85c \uc774\ub7f0 \uc815\ud655\uc131\uc5d0 \ub300\ud55c \uad00\uc2ec\uc744 \ub4e0\ub2e4. \uc190\uc5d0 \uc950\ub294 \uc791\uc740 \ub3d9\uc804\uc774\ub77c\ub3c4, \uc5ec\ub7ec \uac1c\uac00 \uc11c\ub85c \ub2e4\ub974\uac8c \ub9cc\ub4e4\uc5b4\uc9c0\uba74 \ub3c8\uc744 \uc0ac\uc6a9\ud558\ub294 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \ubb38\uc81c\uac00 \ub420 \uc218 \uc788\uc5c8\ub2e4. \ub204\uad70\uac00\uc5d0\uac8c\ub294 \uc11c\ub958 \uc18d \uc791\uc740 \uc218\uce58\uc600\uaca0\uc9c0\ub9cc, \uc2e4\uc81c\ub85c\ub294 \uc7ac\ub8cc\uc640 \uc81c\uc791 \uacfc\uc815, \uac80\uc0ac\ub97c \uc5f0\uacb0\ud558\ub294 \ubb38\uc81c\uc600\ub2e4. \ucc45\uc0c1 \uc704\uc5d0\uc11c \uacc4\uc0b0\ud55c \uae30\uc900\uc774 \uc791\uc5c5\uc7a5\uc758 \uae08\uc18d\uc73c\ub85c \uc774\uc5b4\uc838\uc57c \ud588\ub2e4. \uadf8\uc758 \uc774\ub984\uc774 \ubd99\uc5c8\ub2e4\uace0 \ud574\uc11c \uc870\ud3d0\uad6d\uc758 \ubaa8\ub4e0 \uc81c\ub3c4\uac00 \ub2e8\ubc88\uc5d0 \ubc14\ub010 \uac83\uc740 \uc544\ub2c8\ub2e4. \uacf5\uc2dd \uc124\uba85\ub3c4 \ud070 \uc870\uc9c1 \uac1c\ud601\uacfc \uadf8\uac00 \uae30\uc6b8\uc778 \uad00\ub9ac\uc758 \ub178\ub825\uc744 \uad6c\ubd84\ud55c\ub2e4. \uc720\uba85\ud55c \uc778\ubb3c\uc758 \uc774\ub825\uc774\ub77c\uace0 \ubaa8\ub4e0 \uc77c\uc744 \uadf9\uc801\uc778 \ud601\uba85\uc73c\ub85c \ub9cc\ub4e4 \ud544\uc694\ub294 \uc5c6\ub2e4. \uacfc\ud559\uc0ac\uc5d0\uc11c \uc720\uba85\ud55c \uc0ac\ub78c\uc774\ub77c\ub3c4 \uc2e4\uc81c \uc9c1\uc7a5\uc5d0\uc11c\ub294 \ub9e1\uc740 \uc5ed\ud560\uacfc \uc870\uc9c1\uc758 \uc870\uac74\uc774 \uc788\ub2e4. \ub274\ud134\uc774 \uc870\ud3d0\uad6d\uc5d0\uc11c \ud55c \uc77c\uc744 \uc774\ub984\uc758 \uc704\ub300\ud568\uc73c\ub85c\ub9cc \uc124\uba85\ud558\uba74 \uc8fc\ubcc0\uc758 \ub178\ub3d9\uacfc \uc81c\ub3c4\uac00 \uc0ac\ub77c\uc9c4\ub2e4. \uc7ac\uc8fc\uc870\ub294 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uc7ac\ub8cc\uc640 \uc7a5\ube44, \uae30\ub85d\uc744 \ub2e4\ub8e8\ub294 \ud070 \uc77c\uc774\uc5c8\ub2e4. \ub274\ud134\uc758 \uae30\uc5ec\ub97c \uc774\ud574\ud558\ub824\uba74 \uadf8\uac00 \ubb34\uc5c7\uc744 \ub9e1\uc558\ub294\uc9c0\ubd80\ud130 \uad6c\uccb4\uc801\uc73c\ub85c \ubcf4\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uacfc\ud559\uc758 \ubc1c\uacac\uacfc \ud589\uc815\uc758 \uc131\uacfc\uac00 \uc5b8\uc81c\ub098 \uac19\uc740 \ubaa8\uc2b5\uc73c\ub85c \ub098\ud0c0\ub098\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uc2e4\ud5d8\uacfc \uacc4\uc0b0\uc5d0 \uc775\uc219\ud55c \ud0dc\ub3c4\uac00 \uc815\ud655\uc131\uc744 \uc911\uc2dc\ud558\ub294 \uc77c\uacfc \uc5f0\uacb0\ub420 \uc218 \uc788\uc9c0\ub9cc \ubaa8\ub4e0 \uad00\ub9ac\uc758 \uacb0\uc815\uc744 \uacfc\ud559 \ubc95\uce59\uc758 \uc801\uc6a9\uc774\ub77c\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uacf5\uc2dd \uc124\uba85\uc774 \ud655\uc778\ud574 \uc8fc\ub294 \uc5c5\ubb34\ub97c \ub530\ub77c\uac00\uba74 \uacfc\uc7a5\ud558\uc9c0 \uc54a\uace0\ub3c4 \ub113\uc740 \uc0dd\uc560\uc758 \ud55c \ubd80\ubd84\uc744 \ub9cc\ub0a0 \uc218 \uc788\ub2e4. \ud55c \ub3d9\uc804\uc758 \ubb34\uac8c \ucc28\uc774\ub294 \uc791\uc544 \ubcf4\uc77c \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ub9ce\uc740 \ub3d9\uc804\uc774 \ub9cc\ub4e4\uc5b4\uc9c0\uace0 \uc11c\ub85c \uad50\ud658\ub41c\ub2e4\uba74 \uc77c\uc815\ud55c \uae30\uc900\uc744 \uc720\uc9c0\ud558\ub294 \uc77c\uc774 \uc911\uc694\ud574\uc9c4\ub2e4. \uae08\uc18d\uc758 \uc21c\ub3c4\uc640 \ubb34\uac8c\ub294 \ub2e4\ub978 \ud56d\ubaa9\uc774\uc9c0\ub9cc \ud568\uaed8 \uad00\ub9ac\ud574\uc57c \ud560 \uc218 \uc788\ub2e4. \uc870\ud3d0\ub294 \ub208\uc5d0 \ub744\ub294 \ubb38\uc591\uacfc \ub35c \ubcf4\uc774\ub294 \uc218\uce58\ub97c \uac19\uc740 \ubb3c\uac74\uc5d0 \ub9de\ucd94\ub294 \uc791\uc5c5\uc774\uc5c8\ub2e4. \uc815\ud655\uc131\uc744 \uc694\uad6c\ud55c\ub2e4\ub294 \ub9d0\ub3c4 \uae30\uc900\ub9cc \uc885\uc774\uc5d0 \uc801\ub294 \uac83\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc7ac\ub8cc\ub97c \ub9c8\ub828\ud558\uace0 \ub9cc\ub4dc\ub294 \uacfc\uc815\uc5d0\uc11c \uadf8 \uae30\uc900\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uc0ac\ub78c\uc758 \uc190\uc5d0\uc11c \ub098\uc628 \ubb3c\uac74\uc774 \ub2e4\uc74c \uc0ac\ub78c\uc5d0\uac8c \uac19\uc740 \ud654\ud3d0\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc9c0\ub824\uba74 \ubc18\ubcf5 \uac00\ub2a5\ud55c \ud488\uc9c8\uc774 \ud544\uc694\ud558\ub2e4. \uc870\ud3d0\uad6d\uc758 \uc5c5\ubb34\ub294 \ucd94\uc0c1\uc801\uc778 \uc22b\uc790\uc640 \uc190\uc5d0 \uc950\ub294 \uae08\uc18d\uc744 \uc774\uc5b4 \uc8fc\ub294 \uc790\ub9ac\uc600\ub2e4. \uc704\uc870\uc640 \ud6fc\uc190\uc744 \ub2e4\ub8e8\ub294 \uc5c5\ubb34\uc5d0\ub294 \uc9c4\uc220\uacfc \uc99d\uac70, \uc11c\ub85c \ub2e4\ub978 \uc815\ubcf4\uc758 \ud655\uc778\uc774 \ub4e4\uc5b4\uac04\ub2e4. \ub274\ud134\uc774 \uc81c\ubcf4\uc790\uc640 \uad00\ub828\uc790\ub97c \uc9c1\uc811 \uc870\uc0ac\ud588\ub2e4\ub294 \uc124\uba85\uc740 \uadf8\uac00 \uc774\ub984\ub9cc \uc62c\ub824 \ub454 \uc778\ubb3c\uc774 \uc544\ub2c8\uc5c8\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub2e4\ub9cc \uc720\uba85\ud55c \ud0d0\uc815\ucc98\ub7fc \ubaa8\ub4e0 \ubc94\uc8c4\ub97c \ud63c\uc790 \ud574\uacb0\ud588\ub2e4\ub294 \uadf9\uc801\uc778 \uc774\uc57c\uae30\ub85c \ubc14\uafc0 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5f0\uad6c\uc2e4\uc5d0\uc11c\uc758 \ubaa8\uc2b5\ub9cc \uc54c\uace0 \uc788\ub358 \ub3c5\uc790\uc5d0\uac8c\ub294 \uc774\ub7f0 \uc5c5\ubb34 \uc790\uccb4\uac00 \ucda9\ubd84\ud788 \uc0c8\ub85c\uc6b4 \uc7a5\uba74\uc774\ub2e4. \uc138\uc0c1\uacfc \ub5a8\uc5b4\uc838 \uc0dd\uac01\ub9cc \ud55c \uc0ac\ub78c\uc774 \uc544\ub2c8\ub77c \uc81c\ub3c4\uc758 \uc2e4\ubb34\ub97c \ub9e1\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc758 \ub9d0\uacfc \uae30\ub85d\uc744 \ub2e4\ub8e8\uc5c8\ub2e4. \uc778\ubb3c\uc758 \uc0b6\uc744 \ud558\ub098\uc758 \ub300\ud45c \uc5c5\uc801\uc73c\ub85c\ub9cc \uc555\ucd95\ud558\uc9c0 \uc54a\uc744 \ub54c, \uc775\uc219\ud55c \uc774\ub984\uc5d0\uc11c\ub3c4 \uc544\uc9c1 \uc77d\uc744 \ubd80\ubd84\uc774 \ub0a8\uc544 \uc788\ub2e4. \ub274\ud134\uc740 1699\ub144\ubd80\ud130 \uc870\ud3d0\uad6d\uc758 \ub2e4\ub978 \uad00\ub9ac\uc9c1\uc744 \ub9e1\uc558\uace0, 1727\ub144 \uc138\uc0c1\uc744 \ub5a0\ub0a0 \ub54c\uae4c\uc9c0 \uadf8\uacf3\uacfc \uad00\uacc4\ub97c \uc774\uc5b4 \uac14\ub2e4. \uc7a0\uae50\uc758 \uc678\ub3c4\uac00 \uc544\ub2c8\ub77c \uc0dd\uc560\uc758 \uae34 \ubd80\ubd84\uc774\uc5c8\ub2e4. \uc774 \uc0ac\uc2e4\uc744 \uc54c\uace0 \ub098\uba74 \uc704\uc778\uc758 \uc774\ub825\ub3c4 \ud55c \uac00\uc9c0 \uc9c1\ud568\uc73c\ub85c\ub9cc \uc77d\ud788\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5f0\uad6c \uacb0\uacfc\ub97c \ub0a8\uae34 \uc0ac\ub78c\uc5d0\uac8c\ub3c4 \uc870\uc9c1 \uc548\uc5d0\uc11c \ucc98\ub9ac\ud574\uc57c \ud560 \uc77c\uacfc \ud655\uc778\ud574\uc57c \ud560 \ubb38\uc11c\uac00 \uc788\uc5c8\ub2e4. \ub2e4\uc74c\uc5d0 \ub3d9\uc804\uc744 \uc190\uc5d0 \uc954\ub2e4\uace0 \ub274\ud134\uc744 \uaf2d \ub5a0\uc62c\ub9b4 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uacfc\ud559\ucc45\uc758 \ucd08\uc0c1\ud654 \uc606\uc5d0 \ub3d9\uc804\uc758 \ubb34\uac8c\uc640 \uc21c\ub3c4\ub97c \uc0b4\ud53c\ub358 \ub610 \ub2e4\ub978 \uc9c1\uc7a5\uc778\uc758 \ubaa8\uc2b5\ub3c4 \ub193\uc544 \ubcfc \uc218\ub294 \uc788\uaca0\ub2e4. \uc791\uc740 \ub3c8 \ud55c \uac1c\ub97c \uc815\ud655\ud558\uac8c \ub9cc\ub4dc\ub294 \uc77c\ub3c4 \uadf8\uc758 \uc624\ub79c \uc77c\uc0c1\uc774\uc5c8\ub2e4."}, {"id": "oracle-bones-questions-and-written-traces", "title": "\uac11\uace8\ubb38 \u2014 \uc655\uc774 \ub0b4\uc77c\uc744 \ubb3c\uc5c8\ub354\ub2c8 \uc9c8\ubb38\uc774 \ub0a8\uc558\ub2e4", "summary": "\ube44\uc640 \uc218\ud655, \uc804\uc7c1\uacfc \uc655\uc2e4\uc758 \uc77c\uc744 \ubb3b\ub358 \uc810\ubcf5 \uc790\ub8cc\ub97c \ud1b5\ud574 \uc624\ub798\ub41c \ubb38\uc790\uac00 \ub0a8\uae34 \uc0dd\ud65c\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/oracle-bones-questions-and-written-traces/index.html", "image": "../media/oracle-bones-questions-and-written-traces.jpg", "alt": "\uac11\uace8\ubb38\uc774 \uc0c8\uaca8\uc9c4 \uc2e4\uc81c \ubf08\uc758 \uc0ac\uc9c4\uacfc \ubb38\uc790 \ud615\ud0dc \ubcc0\ud654\ub97c \ud568\uaed8 \uc2e4\uc740 \uad50\uc7ac \ub3c4\ud310", "text": "\uac11\uace8\ubb38 \u2014 \uc655\uc774 \ub0b4\uc77c\uc744 \ubb3c\uc5c8\ub354\ub2c8 \uc9c8\ubb38\uc774 \ub0a8\uc558\ub2e4 \uac08\ub77c\uc9c4 \ubf08\uc640 \uac70\ubd81 \uaecd\ub370\uae30\uc5d0\uc11c \uc77d\ub294 \uc0c1\ub098\ub77c\uc758 \ud558\ub8e8 \ube44\uc640 \uc218\ud655, \uc804\uc7c1\uacfc \uc655\uc2e4\uc758 \uc77c\uc744 \ubb3b\ub358 \uc810\ubcf5 \uc790\ub8cc\ub97c \ud1b5\ud574 \uc624\ub798\ub41c \ubb38\uc790\uac00 \ub0a8\uae34 \uc0dd\ud65c\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ub0b4\uc77c \ube44\uac00 \uc62c\uae4c. \uc218\ud655\uc740 \uad1c\ucc2e\uc744\uae4c. \uc804\uc7c1\uc5d0 \ub098\uac00\ub3c4 \ub420\uae4c. \uc624\ub298\ub3c4 \ub274\uc2a4\uc640 \uc608\ubcf4\ub97c \uc0b4\ud3b4\ubcf4\uac8c \ub9cc\ub4dc\ub294 \uc9c8\ubb38\ub4e4\uc774\ub2e4. \uc911\uad6d \uc0c1\ub098\ub77c\uc758 \uc655\uc2e4\uc5d0\uc11c\ub294 \uc774\ub7f0 \ubd88\uc548\uc744 \ubf08\uc640 \uac70\ubd81 \uaecd\ub370\uae30 \uc55e\uc5d0 \uac00\uc838\uac14\ub2e4. \ubd88\ub85c \uc0dd\uae34 \uae08\uc744 \uc77d\uace0, \uadf8\uc640 \uad00\ub828\ub41c \ub9d0\uc744 \uc0c8\uaca8 \ub0a8\uacbc\ub2e4. \uac11\uace8\ubb38\uc744 \ucc98\uc74c \ubcf4\uba74 \uc791\uace0 \ub0af\uc120 \uc120\ub4e4\uc774 \ud769\uc5b4\uc838 \uc788\ub294 \ub4ef\ud558\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \uc548\uc5d0 \ubbf8\ub798\ub97c \uad81\uae08\ud574\ud558\ub358 \uc9c8\ubb38\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c\uace0 \ub098\uba74 \ubb3c\uac74\uc758 \ud45c\uc815\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uae00\uc790\uc758 \uc870\uc0c1\uc774\uba74\uc11c, \uacb0\uc815\uc744 \uc55e\ub454 \uc0ac\ub78c\ub4e4\uc774 \ub0a8\uae34 \uae30\ub85d\uc774\uae30\ub3c4 \ud558\ub2e4. \uac11\uace8\uc774\ub77c\ub294 \ub9d0\uc740 \uac70\ubd81\uc758 \uaecd\ub370\uae30\uc640 \uc9d0\uc2b9\uc758 \ubf08\ub97c \uac00\ub9ac\ud0a8\ub2e4. \uac11\uace8\ubb38\uc740 \uadf8 \ud45c\uba74\uc5d0 \uc0c8\uae34 \ubb38\uc790\ub2e4. \uc0c1\ub098\ub77c\uc758 \uc810\ubcf5\uc5d0\uc11c \uc0ac\uc6a9\ub41c \uc790\ub8cc\uac00 \ub300\ud45c\uc801\uc774\uba70, \ucd08\uae30 \uc911\uad6d \ubb38\uc790\ub97c \uc5f0\uad6c\ud558\ub294 \uc911\uc694\ud55c \ub2e8\uc11c\uac00 \ub418\uc5c8\ub2e4. \uc885\uc774\uc640 \ubd93\uc73c\ub85c \uc4f4 \ucc45\ub9cc\uc774 \uc624\ub798\ub41c \uae00\uc758 \ud615\ud0dc\ub294 \uc544\ub2c8\uc5c8\ub358 \uc148\uc774\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uba3c\uc800 \uc804\uccb4 \ubaa8\uc591\uc744 \ubcf4\uace0, \ub2e4\uc74c\uc5d0 \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc0dd\uae34 \uae08\uacfc \uc0ac\ub78c\uc774 \uc0c8\uae34 \uc120\uc744 \uad6c\ubd84\ud574 \ubcf4\uc790. \ubaa8\ub450 \uac19\uc740 \uc120\ucc98\ub7fc \ubcf4\uc5ec\ub3c4 \uc0dd\uae34 \uc774\uc720\uac00 \ub2e4\ub974\ub2e4. \ubf08\ub77c\ub294 \uc7ac\ub8cc, \uc5f4\uc774 \ub9cc\ub4e0 \ud754\uc801, \uae00\uc790\ub85c \ub0a8\uae30\ub824 \ud55c \ud589\ub3d9\uc774 \ud55c \ud45c\uba74\uc5d0 \uacb9\uccd0 \uc788\ub2e4. \uc0c1\ub098\ub77c \uc655\uc2e4\uc740 \uc870\uc0c1\uacfc \ucd08\uc6d4\uc801 \uc874\uc7ac\uc5d0\uac8c \uc9c8\ubb38\uc744 \ub358\uc9c0\ub294 \uc810\ubcf5\uc744 \uc911\uc694\ud558\uac8c \uc5ec\uacbc\ub2e4. \uaecd\ub370\uae30\uc640 \ubf08\uc5d0 \uc5f4\uc744 \uac00\ud574 \uc0dd\uae34 \uade0\uc5f4\uc744 \ud574\uc11d\ud558\ub294 \ud589\uc704\ub294 \uadf8 \ubbff\uc74c\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc624\ub298\uc758 \uc2e4\ud5d8\uc774\ub098 \uc77c\uae30\uc608\ubcf4\uc640\ub294 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ubd88\ud655\uc2e4\ud55c \ubbf8\ub798\ub97c \ub2e4\ub8e8\uc5c8\ub2e4. \uc6b0\ub9ac\uac00 \ud655\uc778\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc0ac\ub78c\ub4e4\uc774 \uadf8\ub7f0 \ubc29\uc2dd\uc73c\ub85c \ubb3b\uace0 \ud310\ub2e8\ud588\ub2e4\ub294 \uc0ac\uc2e4\uc774\ub2e4. \uade0\uc5f4\uc774 \ubbf8\ub798\ub97c \uc2e4\uc81c\ub85c \uc608\uce21\ud588\ub2e4\ub294 \uacfc\ud559\uc801 \uc99d\uac70\ub97c \ub73b\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uacfc\uac70\uc758 \ubbff\uc74c\uc744 \uadf8\ub300\ub85c \ubc1b\uc544\ub4e4\uc774\uc9c0 \uc54a\uc544\ub3c4, \uc65c \ud1b5\uce58\uc790\uc5d0\uac8c \uadf8 \uc808\ucc28\uac00 \uc911\uc694\ud588\ub294\uc9c0\ub294 \uc5ed\uc0ac\uc801\uc73c\ub85c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uad50\uc7ac\uac00 \uc124\uba85\ud558\ub294 \uc9c8\ubb38\uc758 \ubc94\uc704\uc5d0\ub294 \uc218\ud655\uacfc \uad70\uc0ac \ud589\ub3d9, \ud6c4\uacc4\uc790\uc758 \ud0c4\uc0dd \ub4f1\uc774 \ud3ec\ud568\ub41c\ub2e4. \uac70\ub300\ud55c \uc655\uad8c\uc744 \uc0dd\uac01\ud558\ub2e4\uac00 \uc774\ub7f0 \uc8fc\uc81c\ub97c \ub9cc\ub098\uba74 \uc655\uc2e4\ub3c4 \uba39\uc744 \uac83\uacfc \uacc4\uc808, \uac00\uc871\uc758 \ubbf8\ub798\uc5d0\uc11c \uc790\uc720\ub86d\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ubcf4\uc778\ub2e4. \ub2e4\ub9cc \uadf8 \uac71\uc815\uc740 \uc655\uad6d\uc758 \ud1b5\uce58\uc640 \uc774\uc5b4\uc838 \uc788\uc5c8\ub2e4. \ube44 \ud55c \ubc88\uc740 \ub18d\uc0ac\uc640 \ubb3c\uc790\uc758 \ubb38\uc81c\uc600\uace0, \ud6c4\uacc4\uc790\uc758 \ud0c4\uc0dd\uc740 \uad8c\ub825\uc758 \ub2e4\uc74c \uc21c\uc11c\uc640 \uad00\uacc4\uac00 \uc788\uc5c8\ub2e4. \uc544\uc8fc \uc0ac\uc801\uc778 \ubd88\uc548\ucc98\ub7fc \ubcf4\uc774\ub294 \uc9c8\ubb38\uc774 \uacf5\uc801\uc778 \uc120\ud0dd\uc774 \ub418\uae30\ub3c4 \ud55c\ub2e4. \uac11\uace8\ubb38\uc744 \uc77d\ub294 \uc77c\uc740 \uc5b4\ub824\uc6b4 \uae00\uc790 \uba87 \uac1c\ub97c \ud574\ub3c5\ud558\ub294 \ub370\uc11c \ub05d\ub098\uc9c0 \uc54a\uace0, \ubb34\uc5c7\uc774 \uc911\uc694\ud588\ub358 \uc0ac\ud68c\uc778\uc9c0 \ubb3b\ub294 \uc77c\uc774 \ub41c\ub2e4. \ub2f9\uc2dc\uc758 \uc810\ubcf5\uc740 \ub2f9\uc7a5\uc758 \ud310\ub2e8\uc744 \ub3d5\uae30 \uc704\ud55c \uac83\uc774\uc5c8\uc744 \uac83\uc774\ub2e4. \uadf8\ub7ec\ub098 \uc624\ub298\uc758 \uc5f0\uad6c\uc790\uac00 \uc5bb\ub294 \uc815\ubcf4\ub294 \uc9c8\ubb38\uc790\uc758 \uae30\ub300\uc640 \uc870\uae08 \ub2e4\ub974\ub2e4. \uc5b4\ub5a4 \ubb38\uc790\uac00 \uc4f0\uc600\uace0, \uc5b4\ub5a4 \uad00\uc2ec\uc0ac\uac00 \ubc18\ubcf5\ub418\uba70, \uc655\uc2e4\uc774 \ubb34\uc5c7\uc744 \uacb0\uc815\ud558\ub824 \ud588\ub294\uc9c0 \uc0b4\ud3b4\ubcfc \uc790\ub8cc\uac00 \ub41c\ub2e4. \ubbf8\ub798\ub97c \uc54c\uace0 \uc2f6\uc5b4 \ub0a8\uae34 \ud754\uc801\uc774 \uba3c \ud6d7\ub0a0\uc5d0\ub294 \uacfc\uac70\ub97c \uc54c\uc544\ubcf4\ub294 \uc790\ub8cc\uac00 \ub41c \uc148\uc774\ub2e4. \uc774 \ub4a4\uc9d1\ud78c \uad00\uacc4\uac00 \uac11\uace8\ubb38\uc758 \ud765\ubbf8\ub85c\uc6b4 \uc810\uc774\ub2e4. \uc9c8\ubb38\uc774 \uc774\ub8e8\uc5b4\uc84c\ub294\uc9c0 \ud558\ub098\ud558\ub098 \ub2e8\uc815\ud558\uc9c0 \uc54a\uc544\ub3c4, \uc9c8\ubb38\ud588\ub2e4\ub294 \uc0ac\uc2e4 \uc790\uccb4\uac00 \uadf8 \uc0ac\ud68c\uc758 \uc77c\ubd80\ubd84\uc744 \ub4dc\ub7ec\ub0b8\ub2e4. \uac11\uace8\ubb38\uacfc \ud6c4\ub300 \ud55c\uc790 \uc0ac\uc774\uc5d0\ub294 \uc774\uc5b4\uc9c0\ub294 \ud754\uc801\uc774 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \ub3c4\ud310\uc740 \uc2e4\uc81c \ubf08\uc758 \uc0ac\uc9c4\uacfc \ubb38\uc790 \ud615\ud0dc\uc758 \ubcc0\ud654\ub97c \ub098\ub780\ud788 \ubcf4\uc5ec \uc900\ub2e4. \uc5b4\ub5a4 \uac83\uc740 \uadf8\ub9bc\ucc98\ub7fc \uc9d0\uc791\ub418\uc9c0\ub9cc, \ud604\ub300 \uae00\uc790\ub97c \uc544\ub294 \uac83\ub9cc\uc73c\ub85c \uc624\ub798\ub41c \ubb38\uc7a5\uc744 \ubaa8\ub450 \uc77d\uc744 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb38\uc790\ub294 \uae34 \uc2dc\uac04 \ub3d9\uc548 \ubaa8\uc591\uacfc \uc0ac\uc6a9 \ubc29\uc2dd\uc774 \ubc14\ub010\ub2e4. \ub2ee\uc740 \uc120\uc744 \ubc1c\uacac\ud558\ub294 \uc990\uac70\uc6c0\uacfc \uc804\ubb38\uc801\uc778 \ud310\ub3c5\uc740 \uad6c\ubd84\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc0ac\uc9c4\uc758 \ud55c \uae00\uc790\uc5d0 \ud655\uc2e0\uc774 \uc11c\uc9c0 \uc54a\ub294\ub2e4\uba74, \uc2a4\uc2a4\ub85c \uc815\ub2f5\uc744 \ub9cc\ub4e4\uae30\ubcf4\ub2e4 \ud574\uc124\uc774 \ud655\uc778\ud574 \uc8fc\ub294 \ubc94\uc704\uae4c\uc9c0\ub9cc \uc77d\uc5b4\ub3c4 \ucda9\ubd84\ud788 \ud765\ubbf8\ub86d\ub2e4. \uc0c1\ub098\ub77c \uc655\uc2e4\uc758 \uc810\ubcf5\uc740 \uc870\uc0c1 \uc22d\ubc30\uc640 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc8fd\uc740 \uc870\uc0c1\uc740 \uc9c0\ub098\uac04 \uac00\uc871\uc5d0 \uadf8\uce58\ub294 \uc874\uc7ac\uac00 \uc544\ub2c8\ub77c \uc0b4\uc544 \uc788\ub294 \uc655\uc758 \ud310\ub2e8\uacfc \uc758\ub840\uc5d0\uc11c \uc911\uc694\ud55c \uc790\ub9ac\ub97c \ucc28\uc9c0\ud588\ub2e4. \uc9c0\uae08\uc758 \uac10\uac01\uc73c\ub85c \uc0ac\uc801\uc778 \uac00\uc871 \ud589\uc0ac\uc640 \uacf5\uc801\uc778 \uc815\uce58\ub97c \uae54\ub054\ud788 \ub098\ub204\uba74 \uc774\ub7f0 \uad00\uacc4\uac00 \uc774\ud574\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc655\uc2e4\uc758 \uacc4\ubcf4\ub97c \uc787\ub294 \uc77c\uacfc \ud1b5\uce58\uc758 \uad8c\uc704\ub97c \uc138\uc6b0\ub294 \uc77c\uc774 \uc11c\ub85c \ub2ff\uc544 \uc788\uc5c8\ub2e4. \ub530\ub77c\uc11c \uac11\uace8\ubb38\uc5d0 \uac00\uc871\uacfc \ud6c4\uacc4\uc758 \uc9c8\ubb38\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc655\uc758 \uc18c\uc18c\ud55c \uc77c\uc0c1\uc744 \ubc1c\uacac\ud588\ub2e4\ub294 \uc7ac\ubbf8 \uc774\uc0c1\uc744 \uac00\uc9c4\ub2e4. \uc5b4\ub5a4 \uad00\uacc4\uac00 \uc655\uad8c\uc744 \ub4b7\ubc1b\uce68\ud588\uace0 \ub204\uad6c\uc758 \ub9d0\uc744 \ub2f5\uc73c\ub85c \ubc1b\uc544\ub4e4\uc600\ub294\uc9c0 \ubb3b\uac8c \ud55c\ub2e4. \ubf08 \uc704\uc758 \uae00\uc790\ub294 \uc815\ubcf4\ub97c \uc801\uc5b4 \ub454 \ud45c\uc2dc\uc774\uba74\uc11c, \uacb0\uc815\uc744 \uc815\ub2f9\ud558\uac8c \ubc1b\uc544\ub4e4\uc774\uac8c \ud558\ub294 \uc758\ub840\uc758 \uc77c\ubd80\uc600\ub2e4\uace0 \ubcfc \uc218 \uc788\ub2e4. \uac11\uace8\ubb38\uc774 \uc0dd\ud65c\uc758 \uc5ec\ub7ec \ubaa8\uc2b5\uc744 \uc54c\ub824 \uc900\ub2e4\uace0 \ud574\uc11c \uc0c1\ub098\ub77c\uc758 \ubaa8\ub4e0 \uc0ac\ub78c\uc744 \ub611\uac19\uc774 \ub300\ud45c\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc790\ub8cc\uac00 \uc8fc\ub85c \uc655\uc2e4\uc758 \uc810\ubcf5\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uae30\uc5b5\ud574\uc57c \ud55c\ub2e4. \ub204\uac00 \uae30\ub85d\uc744 \ub0a8\uae38 \uc218 \uc788\uc5c8\uace0, \ubb34\uc5c7\uc774 \ub0a8\uc744 \uac00\uce58\uac00 \uc788\ub2e4\uace0 \uc5ec\uaca8\uc84c\ub294\uc9c0\uc5d0 \ub530\ub77c \uc624\ub298 \uc6b0\ub9ac\uac00 \ubcf4\ub294 \uacfc\uac70\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \ubf08 \uc704\uc5d0 \ub0a8\uc740 \uc9c8\ubb38 \ud558\ub098\ub97c \ubcf4\uba70 \ub450 \uac00\uc9c0\ub97c \ud568\uaed8 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ubb34\uc5c7\uc774 \uac71\uc815\uc774\uc5c8\uae30\uc5d0 \uc774\uac83\uc744 \ubb3c\uc5c8\uc744\uae4c. \uadf8\ub9ac\uace0 \uc5ec\uae30\uc5d0 \uae00\uc744 \ub0a8\uae30\uc9c0 \ubabb\ud55c \uc0ac\ub78c\ub4e4\uc740 \ubb34\uc5c7\uc744 \uac71\uc815\ud588\uc744\uae4c. \uc791\uc740 \uc120\ub4e4\uc774 \uc624\ub798\ub41c \uc0ac\ud68c\ub97c \ud5a5\ud55c \uc81c\ubc95 \ub113\uc740 \ucc3d\uc774 \ub41c\ub2e4. \uc61b \ubb38\uc790\uac00 \uc5b4\ub835\ub2e4\uba74 \uc9c8\ubb38\uc758 \uc8fc\uc81c \ud55c \uac00\uc9c0\ub9cc \uae30\uc5b5\ud574\ub3c4 \uc88b\ub2e4. \uc218\ud655\uc774\ub4e0 \ud6c4\uacc4\ub4e0, \ubd88\ud655\uc2e4\ud55c \uc77c\uc744 \uc55e\ub450\uace0 \ub2f5\uc744 \uad6c\ud588\ub2e4\ub294 \ub9c8\uc74c\uc740 \ub0af\uc124\uc9c0 \uc54a\ub2e4. \uadf8 \uc775\uc219\ud568\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc810\ubcf5\uacfc \uc655\uad8c\uc774\ub77c\ub294 \ub2e4\ub978 \uc138\uacc4\ub85c \ucc9c\ucc9c\ud788 \ub4e4\uc5b4\uac00\uba74 \ub41c\ub2e4."}, {"id": "osaka-mills-mint-and-port-city", "title": "\uc624\uc0ac\uce74 \u2014 \uc131\uc758 \uc0ac\uc9c4 \uc606\uc5d0 \ubc29\uc9c1\uacf5\uc7a5\uc774 \uc2e4\ub9b0 \uc774\uc720", "summary": "\uc61b \uc548\ub0b4\uc11c\uc758 \uacf5\uc7a5\uacfc \uc870\ud3d0\uad6d, \ud574\uc6b4\uacfc \ub178\ub3d9 \uae30\ub85d\uc73c\ub85c \uadfc\ub300 \uc624\uc0ac\uce74\uc758 \uc5ec\ub7ec \ubaa8\uc2b5\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/osaka-mills-mint-and-port-city/index.html", "image": "../media/osaka-mills-mint-and-port-city.jpg", "alt": "20\uc138\uae30 \ucd08 \uc624\uc0ac\uce74 \ubc29\uc9c1\uacf5\uc7a5\uc758 \uac74\ubb3c\uacfc \uc8fc\ubcc0\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc2e4\uc81c \uc5ed\uc0ac \uc0ac\uc9c4", "text": "\uc624\uc0ac\uce74 \u2014 \uc131\uc758 \uc0ac\uc9c4 \uc606\uc5d0 \ubc29\uc9c1\uacf5\uc7a5\uc774 \uc2e4\ub9b0 \uc774\uc720 20\uc138\uae30 \ucd08 \uc548\ub0b4\uc11c\uc5d0\uc11c \uc77d\ub294 \ubc29\uc9c1\u00b7\ud654\ud3d0\u00b7\ud574\uc6b4\uacfc \ub178\ub3d9 \uc61b \uc548\ub0b4\uc11c\uc758 \uacf5\uc7a5\uacfc \uc870\ud3d0\uad6d, \ud574\uc6b4\uacfc \ub178\ub3d9 \uae30\ub85d\uc73c\ub85c \uadfc\ub300 \uc624\uc0ac\uce74\uc758 \uc5ec\ub7ec \ubaa8\uc2b5\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc624\ub798\ub41c \uc77c\ubcf8 \uc548\ub0b4\uc11c\uc5d0\uc11c \uc624\uc0ac\uce74\ub97c \ucc3e\uc73c\uba74 \uc131\uacfd \uc0ac\uc9c4\ub9cc \ub098\uc624\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \ubc29\uc9c1\uacf5\uc7a5\uacfc \uc870\ud3d0\uad6d, \ud574\uc6b4 \ud68c\uc0ac\uc640 \uc740\ud589\uc758 \uae30\ub85d\ub3c4 \ud568\uaed8 \ub4f1\uc7a5\ud55c\ub2e4. \uc131\uc740 \ub3c4\uc2dc\uc758 \uae34 \uc2dc\uac04\uc744 \uc0c1\uc9d5\ud558\uc9c0\ub9cc \uadfc\ub300 \uc624\uc0ac\uce74\uc758 \ud558\ub8e8\ub294 \ub2e4\ub978 \uc7a5\uc18c\uc5d0\uc11c\ub3c4 \ubc14\uc058\uac8c \uc6c0\uc9c1\uc600\ub2e4. 20\uc138\uae30 \ucd08\uc758 \ucc45\uc744 \ucc3d\uc73c\ub85c \uc0bc\uc544 \uc0b0\uc5c5\uacfc \uad50\uc5ed\uc774 \ub3c4\uc2dc\uc758 \ubaa8\uc2b5\uc744 \ubc14\uafb8\ub358 \uacfc\uc815\uc744 \uc77d\uc5b4 \ubcf4\uc790. \uc624\uc0ac\uce74\uc131\uc740 \ub3c4\uc694\ud1a0\ubbf8 \ud788\ub370\uc694\uc2dc\uc640 \uadf8 \ub4a4 \uad8c\ub825\uc758 \ubcc0\ud654\ub97c \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uc7a5\uc18c\ub2e4. \uadf8\ub7ec\ub098 \uc131\uc758 \uc5ed\uc0ac\uac00 \uace7 \uc624\uc0ac\uce74\uc758 \ubaa8\ub4e0 \uc5ed\uc0ac\uc778 \uac83\uc740 \uc544\ub2c8\ub2e4. \uad8c\ub825\uc758 \uacf5\uac04 \uc8fc\ubcc0\uc5d0\ub294 \ubb3c\uc790\ub97c \ub098\ub974\uace0 \uc0ac\uace0\ud314\uba70 \uc0dd\ud65c\uc744 \uc774\uc5b4 \uac00\ub294 \uc0ac\ub78c\ub4e4\uc758 \ub3c4\uc2dc\uac00 \uc788\uc5c8\ub2e4. \uc131\uc758 \ub3cc\ub2f4\uacfc \ubb3c\uc744 \ubcfc \ub54c\uc5d0\ub294 \uadf8\uac83\uc744 \uc9c0\ud0a4\uace0 \ub2e4\uc2a4\ub9ac\ub294 \uad6c\uc870\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \ubc18\uba74 \ud56d\ub9cc\uacfc \ucc3d\uace0, \uacf5\uc7a5\uacfc \uc0c1\uc810\uc744 \ubcf4\ub824\uba74 \ub2e4\ub978 \uc9c8\ubb38\uc774 \ud544\uc694\ud558\ub2e4. \ub204\uac00 \ubb34\uc5c7\uc744 \uc5b4\ub514\ub85c \uc62e\uae30\uba70 \uc0b4\uc544\uac14\ub294\uc9c0 \ubb3b\ub294 \uc21c\uac04, \uad00\uad11 \uba85\uc18c\ub97c \uc911\uc2ec\uc73c\ub85c \ubcf4\ub358 \ub3c4\uc2dc\uc758 \uc9c0\ub3c4\uac00 \ub113\uc5b4\uc9c4\ub2e4. \uc5b4\ub2c8\uc2a4\ud2b8 \uc70c\uc2a8 \ud074\ub808\uba3c\ud2b8\uc758 \u300e\uadfc\ub300 \uc77c\ubcf8 \uc548\ub0b4\uc11c\u300f\ub294 \uae30\uacc4\ub97c \uc774\uc6a9\ud55c \uba74\ubc29\uc9c1\uc5c5\uc774 \ube60\ub974\uac8c \ucee4\uc84c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uba74\uc9c1\ubb3c\uc774 \uc0dd\ud65c\uc5d0 \ub110\ub9ac \ud544\uc694\ud588\uc9c0\ub9cc \uc77c\ubcf8 \uc548\uc5d0\uc11c \uc7ac\ubc30\ud55c \uba74\ud654\ub9cc\uc73c\ub85c \uc218\uc694\ub97c \ubaa8\ub450 \ucc44\uc6b0\uc9c0 \ubabb\ud574 \uc6d0\ub8cc\ub97c \uc218\uc785\ud588\ub2e4\ub294 \uc810\ub3c4 \uc801\uc5c8\ub2e4. \uc774 \ub300\ubaa9\uc740 \uacf5\uc7a5\uc744 \ub3c4\uc2dc \uc548\uc758 \ub3c5\ub9bd\ub41c \uac74\ubb3c\ub85c \ubcf4\uc9c0 \uc54a\uac8c \ud55c\ub2e4. \ud56d\uad6c\uc5d0 \ub3c4\ucc29\ud55c \uba74\ud654\uac00 \uacf5\uc7a5\uc73c\ub85c \ub4e4\uc5b4\uac00 \uc2e4\uc774\ub098 \ucc9c\uc774 \ub418\uace0 \ub2e4\uc2dc \uc2dc\uc7a5\uc73c\ub85c \ub098\uac00\ub294 \uc5f0\uacb0\uc774 \uc788\uc5b4\uc57c \uc0dd\uc0b0\uc774 \uc774\uc5b4\uc9c4\ub2e4. \uc624\uc0ac\uce74\uc758 \uc0b0\uc5c5\uc740 \ubc14\ub2e4\uc640 \ub5a8\uc5b4\uc9c4 \uad74\ub69d\ub9cc\uc758 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\uc5c8\ub2e4. \uc131\uacfd\uacfc \uacf5\uc7a5\uc740 \uc61b\uac83\uacfc \uc0c8\uac83\uc774 \ubc88\uac08\uc544 \uc0ac\ub77c\uc9c0\ub294 \ub450 \uc7a5\uba74\uc73c\ub85c\ub9cc \ub098\ub258\uc9c0 \uc54a\ub294\ub2e4. \uac19\uc740 \ub3c4\uc2dc\uc5d0\uc11c \ub2e4\ub978 \uc2dc\uac04\uc758 \uc2dc\uc124\ub4e4\uc774 \ud568\uaed8 \uc4f0\uc774\uac70\ub098 \uc0c8 \uc6a9\ub3c4\ub97c \uc5bb\ub294\ub2e4. \uadfc\ub300 \ub3c4\uc2dc\uc758 \ubcc0\ud654\ub294 \ube48 \ub545 \uc704\uc758 \uc2dc\uc791\ubcf4\ub2e4 \uc774\ubbf8 \uc788\ub358 \uae38\uacfc \uc7a5\uc18c \uc704\uc758 \uc7ac\uc870\uc9c1\uc5d0 \uac00\uae5d\ub2e4. \ucc45\uc5d0 \uc2e4\ub9b0 \uc624\uc0ac\uce74 \ubc29\uc9c1\uacf5\uc7a5 \uc0ac\uc9c4\uc740 \ub300\uaddc\ubaa8 \uc0dd\uc0b0 \uc2dc\uc124\uc758 \uc874\uc7ac\ub97c \ubcf4\uc5ec \uc900\ub2e4. \ud558\uc9c0\ub9cc \uac74\ubb3c\uc758 \ud06c\uae30\ub9cc\uc73c\ub85c \uc548\uc5d0\uc11c \uc77c\ud55c \uc0ac\ub78c\ub4e4\uc758 \uc0dd\ud65c\uae4c\uc9c0 \uc54c \uc218\ub294 \uc5c6\ub2e4. \uae30\uacc4\uac00 \uba48\ucd94\uc9c0 \uc54a\ub294 \uc2dc\uac04\uacfc \ub178\ub3d9\uc790\uc758 \uadfc\ubb34 \uc2dc\uac04\uc740 \ubcc4\ub3c4\uc758 \ubb38\uc81c\ub2e4. \uc61b \uc548\ub0b4\uc11c\uac00 \uc0dd\uc0b0\ub7c9\uacfc \uc131\uc7a5\uc5d0 \uac10\ud0c4\ud55c\ub2e4\uace0 \ud574\uc11c \uadf8 \ud3c9\uac00\ub97c \uadf8\ub300\ub85c \ub530\ub97c \ud544\uc694\ub294 \uc5c6\ub2e4. \uac19\uc740 \ucc45\uc758 \uc0ac\ud68c \ubb38\uc81c \ubd80\ubd84\uc5d0\ub294 \uacf5\uc7a5\uc758 \uc5ec\uc131\uacfc \uc5b4\ub9b0 \ub178\ub3d9\uc790, \uc791\uc5c5 \ud658\uacbd\uc5d0 \ub300\ud55c \uc6b0\ub824\ub3c4 \ub098\uc628\ub2e4. \uc0b0\uc5c5\ub3c4\uc2dc\ub97c \uc77d\uc744 \ub54c\uc5d0\ub294 \uc218\ucd9c\uc758 \uc22b\uc790\uc640 \uc77c\ud558\ub294 \ubab8\uc744 \ud568\uaed8 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc624\uc0ac\uce74\uc5d0\ub294 1871\ub144 \uadfc\ub300 \uc870\ud3d0\uad6d\uc774 \uc138\uc6cc\uc84c\ub2e4. \uc870\ud3d0\uad6d\uc740 \uae08\uc18d\uc744 \ub465\uae00\uac8c \ub9cc\ub4dc\ub294 \uacf5\uc7a5\uc5d0 \uadf8\uce58\uc9c0 \uc54a\ub294\ub2e4. \ubb34\uac8c\uc640 \ud488\uc9c8, \ud654\ud3d0 \ub2e8\uc704\uc640 \uc720\ud1b5\uc758 \uc2e0\ub8b0\ub97c \uad6d\uac00\uac00 \uc77c\uc815\ud558\uac8c \ub9de\ucd94\ub824\ub294 \ubcc0\ud654\uc758 \uc77c\ubd80\uc600\ub2e4. \ub3c4\uc2dc\uc758 \uacf5\uc5c5\uc774 \ud589\uc815\uacfc \uc81c\ub3c4\uc5d0 \uc5f0\uacb0\ub418\ub294 \uc9c0\uc810\uc774\ub2e4. \ud654\ud3d0\uac00 \uc77c\uc815\ud55c \uaddc\uaca9\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc9c0\ub294 \uc77c\uacfc \ubaa8\ub4e0 \uac70\ub798\uac00 \uc989\uc2dc \ud3b8\ud574\uc9c0\ub294 \uc77c\uc740 \uac19\uc9c0 \uc54a\ub2e4. \uc720\ud1b5\uacfc \uac00\uaca9, \uc740\ud589\uacfc \uac70\ub798 \uad00\ud589\ub3c4 \ud568\uaed8 \ubc14\ub00c\uc5b4\uc57c \ud55c\ub2e4. \uc870\ud3d0\uad6d\uc744 \ub2e4\ub978 \uc0b0\uc5c5 \uc2dc\uc124\uacfc \ub098\ub780\ud788 \ubcf4\uba74 \uadfc\ub300\ud654\uac00 \uae30\uacc4\ub97c \ub4e4\uc5ec\uc624\ub294 \uc77c\ubcf4\ub2e4 \ub113\uc740 \uacfc\uc815\uc784\uc744 \uc54c \uc218 \uc788\ub2e4. \uba74\ud654 \uc218\uc785\uacfc \uc81c\ud488 \ud310\ub9e4\ub97c \ud568\uaed8 \uc77d\uc73c\uba74 \uc138\uacc4\uc640 \uc5f0\uacb0\ub418\uc5c8\ub2e4\ub294 \ub9d0\uc758 \uad6c\uccb4\uc801\uc778 \ub0b4\uc6a9\uc774 \ubcf4\uc778\ub2e4. \ubc14\ub2e4 \uac74\ub108 \uac00\uaca9\uc774\ub098 \uc218\uc1a1 \uc0ac\uc815\uc758 \ubcc0\ud654\ub294 \ub3c4\uc2dc \uacf5\uc7a5\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\ub2e4. \uc5f0\uacb0\uc740 \uae30\ud68c\ub97c \ub113\ud788\ub294 \ub3d9\uc2dc\uc5d0 \ub2e4\ub978 \uc9c0\uc5ed\uc758 \uc870\uac74\uc5d0 \uae30\ub300\uac8c \ub9cc\ub4dc\ub294 \uacfc\uc815\uc774\uae30\ub3c4 \ud558\ub2e4. \uc548\ub0b4\uc11c\ub294 \uc624\uc0ac\uce74 \uc0c1\uc120\ud68c\uc0ac\ub97c \uc911\uc694\ud55c \ud574\uc6b4 \uae30\uc5c5\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \uc120\ubc15\uc740 \uc0ac\ub78c\uacfc \ubb3c\uac74\uc744 \uc815\ud574\uc9c4 \uc7a5\uc18c \uc0ac\uc774\ub85c \uc774\ub3d9\uc2dc\ud0a4\uace0, \ud56d\uad6c\uc640 \ucc3d\uace0\ub294 \uadf8 \ud750\ub984\uc744 \uc774\uc5b4 \uc900\ub2e4. \uc0c1\ud488\uc774 \ub9ce\uc774 \ub9cc\ub4e4\uc5b4\uc838\ub3c4 \uc6b4\uc1a1\uacfc \uac70\ub798\uc758 \uc5f0\uacb0\uc774 \uc57d\ud558\uba74 \uc2dc\uc7a5\uae4c\uc9c0 \uac00\uae30 \uc5b4\ub835\ub2e4. \uc624\uc0ac\uce74\uc640 \uac00\uae4c\uc6b4 \uace0\ubca0\ub97c \uc0dd\uac01\ud558\uba74 \uc11c\ub85c \uacbd\uc7c1\ud558\uace0 \uc5f0\uacb0\ub418\ub294 \ud56d\ub9cc\uc758 \uc9c0\ub9ac\ub3c4 \ubcf4\uc778\ub2e4. \ud55c \ub3c4\uc2dc\uc758 \ubc1c\uc804\uc744 \ub2e4\ub978 \uacf3\uacfc \uad00\uacc4\uc5c6\ub294 \uc790\uae09\uc790\uc871\uc758 \uc131\uacf5\uc73c\ub85c \uc124\uba85\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \uacf5\uc7a5\uc758 \uc6d0\ub8cc\uc640 \ud310\ub9e4\ucc98\ub97c \ub530\ub77c\uac00\uba74 \uc8fc\ubcc0 \uc9c0\uc5ed\uacfc \ud574\uc678\uc758 \ub178\ub3d9\uacfc \uc2dc\uc7a5\uc774 \ud568\uaed8 \ub098\ud0c0\ub09c\ub2e4. 1903\ub144 \uc624\uc0ac\uce74\uc5d0\uc11c\ub294 \ub0b4\uad6d\uad8c\uc5c5\ubc15\ub78c\ud68c\uac00 \uc5f4\ub838\ub2e4. \uc0c8\ub85c\uc6b4 \uc0b0\uc5c5\uacfc \uc81c\ud488\uc744 \ub9ce\uc740 \uc0ac\ub78c\uc5d0\uac8c \ubcf4\uc5ec \uc8fc\ub294 \uc790\ub9ac\ub294 \uad6d\uac00\uac00 \uc5b4\ub5a4 \ubbf8\ub798\ub97c \ub0b4\uc138\uc6b0\ub294\uc9c0\ub3c4 \ub4dc\ub7ec\ub0c8\ub2e4. \ud074\ub808\uba3c\ud2b8\ub294 \uadf8 \uc804\uc2dc\ub97c \uc5b8\uae09\ud558\uba70 \uc77c\ubcf8\uc758 \uae30\uacc4 \uc0dd\uc0b0\uacfc \uc81c\uc870\uc5c5\uc5d0 \ub300\ud55c \uad00\uc2ec\uc744 \uc804\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc804\uc2dc\ub294 \ud56d\uc0c1 \uc120\ud0dd\ub41c \uc7a5\uba74\uc774\ub2e4. \ubc1d\uac8c \uc9c4\uc5f4\ub41c \uc81c\ud488\uc774 \uacf5\uc7a5 \ub178\ub3d9\uc774\ub098 \uc6d0\ub8cc\ub97c \uc5bb\ub294 \ubaa8\ub4e0 \uacfc\uc815\uc744 \ubcf4\uc5ec \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubc15\ub78c\ud68c\uc758 \ud654\ub824\ud568\uacfc \uc2e4\uc81c \uc0dd\ud65c \uc0ac\uc774\uc758 \uac70\ub9ac\ub97c \uc0dd\uac01\ud558\uba74, \uae30\uc220\uc744 \uad6c\uacbd\ud558\ub294 \uc77c\uc774 \uacbd\uc81c\uc640 \uad6d\uac00\uc758 \uc774\ubbf8\uc9c0\ub97c \ubc30\uc6b0\ub294 \uacbd\ud5d8\uc774\uae30\ub3c4 \ud588\uc74c\uc744 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc774 \ucc45\uc758 \uc784\uae08\uacfc \uc0dd\uc0b0 \ud1b5\uacc4\ub294 \uc9d1\uacc4 \uc2dc\uc810\uacfc \ubc94\uc704\ub97c \uac00\uc9c4 \uae30\ub85d\uc774\ub2e4. \uadf8 \uc22b\uc790\ub97c \uc624\ub298\uc758 \uc0dd\ud65c\ube44\ub85c \ubc14\ub85c \ubc14\uafb8\uac70\ub098 \uc624\uc0ac\uce74 \ub178\ub3d9\uc790 \ubaa8\ub450\uc5d0\uac8c \uc801\uc6a9\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub300\uc2e0 \uc5b4\ub5a4 \ud56d\ubaa9\uc744 \ub530\ub85c \uc14c\ub294\uc9c0 \uc77d\uc73c\uba74 \ub2f9\uc2dc\uc5d0 \ubb34\uc5c7\uc744 \uc131\uc7a5\uc758 \uc9c0\ud45c\ub85c \uc0bc\uc558\ub294\uc9c0 \uc54c \uc218 \uc788\ub2e4. \ud074\ub808\uba3c\ud2b8\uc758 \ucc45\uc740 20\uc138\uae30 \ucd08 \uc77c\ubcf8\uc758 \uc81c\ub3c4\uc640 \uc0b0\uc5c5\uc744 \uc678\uad6d \ub3c5\uc790\uc5d0\uac8c \uc124\uba85\ud558\ub824 \ud588\ub2e4. \uadf8\ub798\uc11c \uaddc\ubaa8\uc640 \uc18d\ub3c4, \ub2e4\ub978 \uad6d\uac00\uc640\uc758 \ube44\uad50\uac00 \uc790\uc8fc \ub4f1\uc7a5\ud55c\ub2e4. \uadf8 \uc548\uc758 \uadfc\ub300\ub77c\ub294 \ud3c9\uac00\ub97c \uc2dc\ub300\ub97c \ucd08\uc6d4\ud55c \uae30\uc900\ucc98\ub7fc \uc0ac\uc6a9\ud558\uc9c0 \ub9d0\uace0 \uc800\uc790\uc758 \uad00\uc2ec\uacfc \ud568\uaed8 \uc77d\uc5b4\uc57c \ud55c\ub2e4. \uc5ec\uae30\uc5d0 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \ucc45\uc5d0 \uc218\ub85d\ub41c \uc624\uc0ac\uce74 \ubc29\uc9c1\uacf5\uc7a5\uc758 \uc2e4\uc81c \uc5ed\uc0ac \uc0ac\uc9c4\uc774\ub2e4. \ud604\uc7ac \uc2dc\uc124\uc758 \ubaa8\uc2b5\uacfc \uad6c\ubd84\ud574\uc11c \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc624\ub798\ub41c \uc131\uacfd\uc744 \ub3c4\uc2dc\uc758 \uc720\uc77c\ud55c \uc5bc\uad74\ub85c \uc0bc\uc9c0 \ub9d0\uace0 \uadf8 \uacc1\uc758 \uacf5\uc7a5\uacfc \uc870\ud3d0\uad6d, \ud56d\ub9cc\uc758 \uae30\ub85d\uae4c\uc9c0 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc624\uc0ac\uce74\ub294 \uacfc\uac70\ub97c \uc9c0\ub2cc \ub3c4\uc2dc\uc778 \ub3d9\uc2dc\uc5d0 \uc77c\uc758 \ubc29\uc2dd\uc774 \uacc4\uc18d \ubc14\ub00c\uc5b4 \uc628 \ub3c4\uc2dc\uc600\ub2e4."}, {"id": "palace-roof-pangolin", "title": "\uad81\uad90 \uc9c0\ubd95 \uc704\uc5d0\ub294 \ub0af\uc120 \ub3d9\ubb3c\uc774 \uc549\uc544 \uc788\uc5c8\ub2e4", "summary": "\ub192\uc740 \uc9c0\ubd95\uc5d0\uc11c \uba40\ub9ac \ubcf4\uc774\ub358 \uc791\uc740 \uc870\uac01\uc0c1\uc744 \uac00\uae4c\uc774 \ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/palace-roof-pangolin/index.html", "image": "../media/palace-roof-pangolin.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc7a1\uc0c1 '\ucc9c\uc0b0\uac11' \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uad81\uad90 \uc9c0\ubd95 \uc704\uc5d0\ub294 \ub0af\uc120 \ub3d9\ubb3c\uc774 \uc549\uc544 \uc788\uc5c8\ub2e4 \uadfc\uc815\ubb38\uc5d0\uc11c \ub0b4\ub824\uc628 \ucc9c\uc0b0\uac11 \uc7a1\uc0c1 \ub192\uc740 \uc9c0\ubd95\uc5d0\uc11c \uba40\ub9ac \ubcf4\uc774\ub358 \uc791\uc740 \uc870\uac01\uc0c1\uc744 \uac00\uae4c\uc774 \ubd05\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uad81\uad90 \uc9c0\ubd95\uc744 \uc62c\ub824\ub2e4\ubcf4\uba74 \ub05d\ubd80\ubd84\uc744 \ub530\ub77c \uc791\uc740 \ud615\uc0c1\ub4e4\uc774 \ub298\uc5b4\uc11c \uc788\ub2e4. \uba40\ub9ac\uc11c\ub294 \uc724\uacfd\ub9cc \ubcf4\uc5ec\uc11c \ubaa8\ub450 \ube44\uc2b7\ud55c \uc870\uac01\ucc98\ub7fc \ub290\uaef4\uc9c0\uae30 \uc27d\ub2e4. \uac00\uae4c\uc774 \ubcf4\uba74 \uadf8\uc911 \ud558\ub098\ub294 \uad75\uc740 \ubaa9\uacfc \uc791\uc740 \uc5bc\uad74\uc744 \uac00\uc9c4 \ub0af\uc120 \ubaa8\uc2b5\uc774\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \ucc9c\uc0b0\uac11\uc774\ub77c\uace0 \uc18c\uac1c\ud558\ub294 \uc7a1\uc0c1\uc774\ub2e4. \uacbd\ubcf5\uad81 \uadfc\uc815\ubb38 \uc9c0\ubd95\uc758 \ucd94\ub140\ub9c8\ub8e8\uc5d0 \uc62c\ub838\ub358 \uac83 \uac00\uc6b4\ub370 \ud558\ub098\ub2e4. \uc6d0\ub798\ub294 \uace0\uac1c\ub97c \ud55c\ucc38 \ub4e4\uc5b4\uc57c \ubcf4\uc558\uc744 \ubb3c\uac74\uc744 \uc774\uc81c \uc0ac\uc9c4\uc5d0\uc11c \ub208\ub192\uc774\ub85c \ub9cc\ub09c\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc740 \uc774 \uc7a1\uc0c1\uc5d0 \ubfd4\uacfc \ube44\ub298\uc774 \uc788\uace0 \ub4f1\uc5d0 \uaddc\uce59\uc801\uc778 \ub3cc\uae30\uac00 \ub3cb\uc558\ub2e4\uace0 \uc54c\ub824 \uc900\ub2e4. \uc0ac\uc9c4\uc744 \ubcf4\uba74 \uc5bc\uad74\ubcf4\ub2e4 \ubab8\uc744 \ub530\ub77c \uc774\uc5b4\uc9c0\ub294 \uad74\uace1\uc774 \uba3c\uc800 \uc778\uc0c1\uc5d0 \ub0a8\uc744 \uc218\ub3c4 \uc788\ub2e4. \ud55c \ubc29\ud5a5\uc5d0\uc11c\ub9cc \ubcf4\uace0 \ub3d9\ubb3c \uc774\ub984 \ub9de\ud788\uae30\ub97c \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ucc9c\uc0b0\uac11\uc744 \ud615\uc0c1\ud654\ud55c \uc9c0\ubd95 \uc7a5\uc2dd\uc774\ub77c\ub294 \ubc15\ubb3c\uad00\uc758 \uba85\uce6d\uacfc \uc2e4\uc81c \uc870\uac01\uc758 \ud2b9\uc9d5\uc744 \ud568\uaed8 \uc77d\uc73c\uba74 \ub41c\ub2e4. \uc0b4\uc544 \uc788\ub294 \ub3d9\ubb3c\uc758 \ubab8\uc744 \uc815\ud655\ud788 \uc7ac\ud604\ud55c \ubaa8\ud615\uc73c\ub85c \uc0dd\uac01\ud560 \ubb3c\uac74\uc740 \uc544\ub2c8\ub2e4. \uc18c\uc7a5\ud488 \uc124\uba85\uc740 1867\ub144 \uadfc\uc815\ubb38\uc744 \ub2e4\uc2dc \uc138\uc6b8 \ub54c \ub610\ub294 \uadf8 \uc774\ud6c4\uc5d0 \uc9c0\ubd95\uc5d0 \uc62c\ub9b0 \uc7a1\uc0c1\uc774\ub77c\uace0 \ud55c\ub2e4. \ub531 \ud55c \ud574\uc5d0 \uc81c\uc791\ub418\uc5c8\ub2e4\uace0 \ubabb \ubc15\ub294 \ub300\uc2e0 \uac00\ub2a5\ud55c \uc2dc\uae30\ub97c \uc5f4\uc5b4 \ub193\uc740 \uc124\uba85\uc774\ub2e4. \uc774 \ucc28\uc774\ub294 \uc791\uc544 \ubcf4\uc5ec\ub3c4 \ubb3c\uac74\uc758 \uc774\ub825\uc744 \uc774\ud574\ud560 \ub54c \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uac74\ubb3c\uc774 \ub2e4\uc2dc \uc138\uc6cc\uc9c4 \ud574\ub97c \uc548\ub2e4\uace0 \uadf8 \uc704\uc758 \ubaa8\ub4e0 \uc7a5\uc2dd\uc774 \uadf8\ub0a0 \ud568\uaed8 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4\uace0 \uc815\ud560 \uc218\ub294 \uc5c6\ub294 \uac83\uc774\ub2e4. \uc775\uc219\ud55c \uad81\uad90\uc5d0\ub3c4 \uc774\ub807\uac8c \uc870\uae08\uc529 \ub530\ub85c \ud655\uc778\ud574\uc57c \ud560 \uc2dc\uac04\uc774 \ub0a8\uc544 \uc788\ub2e4. \ucd94\ub140\ub9c8\ub8e8\ub294 \uc9c0\ubd95 \ub05d\uc744 \ud5a5\ud574 \uc2dc\uc120\uc774 \ud758\ub7ec\uac00\ub294 \uc790\ub9ac\ub2e4. \uadf8 \uc704\uc5d0 \ub193\uc778 \ud615\uc0c1\uc740 \uc2e4\ub0b4\uc5d0\uc11c \uc190\uc5d0 \ub4e4\uace0 \ubcf4\ub294 \uc870\uac01\uacfc \ub2e4\ub978 \uc870\uac74\uc744 \uac00\uc9c4\ub2e4. \ubcf4\ub294 \uc0ac\ub78c\uc740 \ub300\uac1c \uc544\ub798\uc5d0\uc11c \uc62c\ub824\ub2e4\ubcf4\uace0, \uc138\ubd80\ubcf4\ub2e4 \uc724\uacfd\uc744 \uba3c\uc800 \ub9cc\ub09c\ub2e4. \ud070 \uac74\ucd95\ubb3c\uc758 \uac00\uc7a5\uc790\ub9ac\uc5d0\uc11c \uc791\uc740 \uc870\uac01\uc774 \uc5b4\ub5bb\uac8c \ub208\uc5d0 \ub4e4\uc5b4\uc624\ub294\uc9c0 \uc0dd\uac01\ud558\uba74 \uc7a5\uc2dd\uc758 \uc790\ub9ac\uac00 \uad6c\uccb4\uc801\uc73c\ub85c \ub290\uaef4\uc9c4\ub2e4. \uc624\ub298 \uc18c\uc7a5\ud488 \uc0ac\uc9c4\uc73c\ub85c \ubcf4\ub294 \ubb3c\uac74\uc740 \uadf8 \uac70\ub9ac\ub97c \ud06c\uac8c \uc904\uc5ec \uc900\ub2e4. \uba40\ub9ac\uc11c\ub294 \ud55c \ub369\uc5b4\ub9ac\uc600\uc744 \ubab8\uc774 \uad75\uc740 \ubaa9\uacfc \uc791\uc740 \uc5bc\uad74, \ub4f1 \uc704\uc758 \ub3cc\uae30\ub85c \ub098\ub25c\ub2e4. \ub192\uc740 \uacf3\uc5d0\uc11c \ubcf4\uc558\ub358 \uacbd\ud5d8\uacfc \ub208\ub192\uc774\uc5d0\uc11c \uc0b4\ud3b4\ubcf4\ub294 \uacbd\ud5d8\uc774 \uac19\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc15\ubb3c\uad00\uc758 \uc0ac\uc9c4\uc740 \uc6d0\ub798\uc758 \uc704\uce58\uc5d0\uc11c\ub294 \uc9c0\ub098\ucce4\uc744 \ud2b9\uc9d5\uc744 \uc54c\uc544\ucc28\ub9ac\uac8c \ud55c\ub2e4. \ucc9c\uc0b0\uac11\uc774\ub77c\ub294 \uba85\uce6d\uc744 \ub4e4\uc73c\uba74 \ube44\ub298\ub85c \ub36e\uc778 \uc2e4\uc81c \ub3d9\ubb3c\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc774 \uc7a1\uc0c1\uc740 \uc0dd\ubb3c\ud559 \uc218\uc5c5\uc758 \ud45c\ubcf8\uc73c\ub85c \uc81c\uc791\ub41c \uac83\uc774 \uc544\ub2c8\ub2e4. \ubc15\ubb3c\uad00\uc774 \uc18c\uac1c\ud558\ub294 \ubfd4\uacfc \ub3cc\uae30, \ubab8\uc758 \ube44\ub840\ub97c \ud568\uaed8 \ubcf4\uba74 \ub3d9\ubb3c\uc758 \ud2b9\uc9d5\uc744 \uc7a5\uc2dd\uc758 \uc5b8\uc5b4\ub85c \ubc14\uafbc \ud615\uc0c1\uc73c\ub85c \uc77d\ub294 \ud3b8\uc774 \uc790\uc5f0\uc2a4\ub7fd\ub2e4. \uc774\ub984\uc744 \ub9de\ud614\ub2e4\uace0 \uad00\ucc30\uc774 \ubaa8\ub450 \ub05d\ub098\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uc5b4\ub290 \ubd80\ubd84\uc744 \ud06c\uac8c \ud558\uace0 \ubb34\uc5c7\uc744 \ub2e8\uc21c\ud558\uac8c \ub9cc\ub4e4\uc5c8\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uba74 \uc7ac\ubbf8\uac00 \uc0dd\uae34\ub2e4. \uc5bc\uad74\ubcf4\ub2e4 \ubaa9\uacfc \ub4f1\uc5d0 \ub354 \ub208\uc774 \uac08 \uc218\ub3c4 \uc788\uace0, \uc606\ubaa8\uc2b5\uc5d0\uc11c\ub9cc \uc724\uacfd\uc774 \ubd84\uba85\ud574\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \uc774\ub294 \uc2e4\uc81c \ubb3c\uac74\uc744 \ubcf4\ub294 \ubc29\ubc95\uc5d0 \uad00\ud55c \uc81c\uc548\uc774\ub2e4. \uc870\uac01\uc758 \ubaa8\ub4e0 \ud2b9\uc9d5\ub9c8\ub2e4 \ubc18\ub4dc\uc2dc \uc228\uc740 \uc0c1\uc9d5 \ud558\ub098\ub97c \ucc3e\uc544 \ubd99\uc5ec\uc57c \ud55c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. 1867\ub144 \uc911\uac74 \ub54c \ub610\ub294 \uadf8 \uc774\ud6c4\ub77c\ub294 \uc124\uba85\uc740 \uac74\ubb3c\uacfc \ubd80\uc18d\ubb3c\uc758 \uad00\uacc4\ub97c \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uac74\ucd95\ubb3c\uc740 \ud55c \ubc88 \uc9c0\uc5b4\uc9c4 \ub4a4\uc5d0\ub3c4 \uace0\uce58\uace0 \ubc14\uafb8\ub294 \uc2dc\uac04\uc744 \uac70\uce60 \uc218 \uc788\ub2e4. \uc9c0\ubd95 \uc704 \uc7a5\uc2dd\uc774 \ud604\uc7ac\uae4c\uc9c0 \ub0a8\uc558\ub2e4\uace0 \ud574\uc11c \ucc98\uc74c\uc758 \ubaa8\ub4e0 \ubd80\uc7ac\uac00 \uac19\uc740 \uc2dc\uae30\uc5d0 \ub9cc\ub4e4\uc5b4\uc838 \uadf8\ub300\ub85c \uc774\uc5b4\uc84c\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc18c\uc7a5\ud488 \uc124\uba85\uc5d0 \ub0a8\uc740 \ub113\uc740 \uc2dc\uae30 \ubc94\uc704\ub294 \uc815\ubcf4\uac00 \ubb34\uc758\ubbf8\ud558\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uc5b4\ub514\uae4c\uc9c0 \ud655\uc778\ub418\uace0 \uc5b4\ub514\ubd80\ud130 \ub354 \uc54c\uc544\ubcf4\uc544\uc57c \ud558\ub294\uc9c0 \ud45c\uc2dc\ud55c \uac83\uc774\ub2e4. \uc5f0\ub3c4\ub97c \ub531 \ud558\ub098 \uc678\uc6b0\ub294 \ub300\uc2e0 \uac74\ubb3c\uc758 \uc911\uac74\uacfc \uc7a5\uc2dd\uc758 \uc124\uce58\ub97c \ub098\ub204\uc5b4 \uae30\uc5b5\ud558\uba74, \uad81\uad90\uc744 \uba48\ucd98 \uadf8\ub9bc\uc774 \uc544\ub2c8\ub77c \uc5ec\ub7ec \ubc88 \uc190\ubcf8 \uc7a5\uc18c\ub85c \ubcfc \uc218 \uc788\ub2e4. \uad81\uad90\uc744 \uac77\ub294 \uc0ac\ub78c\uc740 \ub300\ubb38\uc774 \uc5f4\uc5b4 \uc8fc\ub294 \ud1b5\ub85c\ub97c \ub530\ub77c \uc774\ub3d9\ud55c\ub2e4. \uc7a1\uc0c1\uc740 \uadf8 \ud1b5\ub85c\ubcf4\ub2e4 \ub192\uc740 \uacf3\uc5d0\uc11c \ub2e4\ub978 \uc885\ub958\uc758 \ub9ac\ub4ec\uc744 \ub9cc\ub4e0\ub2e4. \uba40\ub9ac\uc11c \uc774\uc5b4\uc9c4 \uc791\uc740 \ud615\uc0c1\ub4e4\uc774 \uc904\uc744 \uc774\ub8e8\uace0, \uac00\uae4c\uc6b4 \uc790\ub8cc\uc5d0\uc11c\ub294 \uac01\uac01 \ub2e4\ub978 \ubab8\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \uc804\uccb4 \uac74\ubb3c\uc5d0\uc11c \uc138\ubd80\ub85c \ub0b4\ub824\uc624\ub294 \ubcf4\uae30\uc640, \uc138\ubd80\ub97c \uc54c\uace0 \ub2e4\uc2dc \uc804\uccb4\ub97c \ubcf4\ub294 \ubcf4\uae30\uac00 \uc624\uac08 \uc218 \uc788\ub2e4. \uc774 \ubb3c\uac74\uc744 \ub2e4\uc74c\uc5d0 \ub5a0\uc62c\ub9b4 \ub54c\uc5d0\ub294 \uc5b4\ub824\uc6b4 \uc774\ub984 \ud558\ub098\ubcf4\ub2e4 \ubaa9\uacfc \ub4f1\uc758 \ubaa8\uc591\uc744 \uba3c\uc800 \uae30\uc5b5\ud574 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \ube44\uc2b7\ud558\uac8c \ubcf4\uc774\ub294 \uc7a5\uc2dd\uc774 \uc2e4\uc81c\ub85c\ub294 \ub2e4\ub97c \uc218 \uc788\ub2e4\ub294 \uc791\uc740 \ub2e8\uc11c\ub2e4. \uac74\ucd95\uc744 \uae4a\uac8c \ubcf8\ub2e4\ub294 \uc77c\uc740 \uc804\ubb38 \uc6a9\uc5b4\ub97c \ub9ce\uc774 \uc4f0\ub294 \uac83\ubcf4\ub2e4, \ub298 \uc9c0\ub098\uce58\ub358 \uc790\ub9ac\uc5d0\uc11c \ubb34\uc5c7\uc774 \ub2ec\ub790\ub294\uc9c0 \uc54c\uc544\ubcf4\ub294 \ub370\uc11c \uc2dc\uc791\ub418\uae30\ub3c4 \ud55c\ub2e4. \uad81\uad90\uc5d0 \uac00\uba74 \ud070 \ubb38\uc774\ub098 \ud604\ud310\uc744 \uba3c\uc800 \ucc3e\uae30 \uc27d\ub2e4. \uc774 \uc7a1\uc0c1\uc744 \ud55c \ubc88 \ubcf4\uace0 \ub098\uba74 \uc2dc\uc120\uc774 \uc9c0\ubd95\uc758 \uac00\uc7a5\uc790\ub9ac\ub85c\ub3c4 \ud5a5\ud560 \uac83 \uac19\ub2e4. \uc791\uac8c \ubcf4\uc774\ub358 \uc724\uacfd \ud558\ub098\ud558\ub098\uc5d0 \uc11c\ub85c \ub2e4\ub978 \ubaa8\uc2b5\uc774 \ub4e4\uc5b4 \uc788\uc744 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc0c1\uc9d5\uc758 \ub73b\uc744 \uc804\ubd80 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uad1c\ucc2e\ub2e4. \uc624\ub298\uc740 \uad75\uc740 \ubaa9\uacfc \ub4f1 \uc704\uc758 \ub3cc\uae30 \uc815\ub3c4\ub9cc \uae30\uc5b5\ud574 \ubcf4\uc790. \uc774\ub984\uc870\ucc28 \ub0af\uc124\ub358 \uc870\uac01 \ud558\ub098\uac00 \ub2e4\uc74c \uad81\uad90 \uc0b0\ucc45\uc5d0\uc11c \ub208\uae38\uc744 \ubd99\uc7a1\ub294 \ud45c\uc9c0\uac00 \ub420 \uc218 \uc788\ub2e4."}, {"id": "palenque-glyphs-and-city-memory", "title": "\ud314\ub81d\ucf00 \u2014 \ub9c8\uc57c\uc758 \uae00\uc790\ub294 \uc5b4\ub5bb\uac8c \ub3c4\uc2dc\uc758 \uc5ed\uc0ac\uac00 \ub418\uc5c8\uc744\uae4c", "summary": "\ub9c8\uc57c \ubb38\uc790\ub97c \ud1b5\ud574 \ub3c4\uc2dc\uad6d\uac00\uc758 \uad8c\ub825\u00b7\uc804\uc7c1\u00b7\uc2dc\uac04 \uae30\ub85d\uc744 \uc77d\ub294 \ubc29\ubc95\uc744 \uc54c\uc544\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/palenque-glyphs-and-city-memory/index.html", "image": "../media/palenque-glyphs-and-city-memory.jpg", "alt": "\uba55\uc2dc\ucf54 \ud314\ub81d\ucf00 \ubc15\ubb3c\uad00\uc5d0 \uc804\uc2dc\ub41c \ub9c8\uc57c \ubb38\uc790 \ud68c\ubc18\uc8fd \uc870\uac01 \uc2e4\uc81c \uc0ac\uc9c4", "text": "\ud314\ub81d\ucf00 \u2014 \ub9c8\uc57c\uc758 \uae00\uc790\ub294 \uc5b4\ub5bb\uac8c \ub3c4\uc2dc\uc758 \uc5ed\uc0ac\uac00 \ub418\uc5c8\uc744\uae4c \uba55\uc2dc\ucf54 \ub9c8\uc57c \ub3c4\uc2dc\uc758 \ucc44\uc0c9 \uac74\ucd95\u00b7\ubb38\uc790\u00b7\uc655\uc2e4 \uae30\ub85d\uc744 \uc77d\ub294 \ubc29\ubc95 \ub9c8\uc57c \ubb38\uc790\ub97c \ud1b5\ud574 \ub3c4\uc2dc\uad6d\uac00\uc758 \uad8c\ub825\u00b7\uc804\uc7c1\u00b7\uc2dc\uac04 \uae30\ub85d\uc744 \uc77d\ub294 \ubc29\ubc95\uc744 \uc54c\uc544\ubd05\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ub9c8\uc57c \uc720\uc801\uc758 \ubb38\uc790\ub97c \ucc98\uc74c \ubcf4\uba74 \uc0ac\ub78c\uc758 \uc5bc\uad74\uacfc \uae30\ubb18\ud55c \ubb34\ub2ac\ub97c \uc815\uad50\ud558\uac8c \uc774\uc5b4 \ubd99\uc778 \uc7a5\uc2dd\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uc548\uc5d0\ub294 \uc77d\uc744 \uc218 \uc788\ub294 \ub9d0\uc774 \uc788\ub2e4. \uc624\ub298\ub0a0 \uba55\uc2dc\ucf54\uc5d0 \uc788\ub294 \ud314\ub81d\ucf00\uc758 \ubb38\uc790 \uc790\ub8cc\ub97c \ucd9c\ubc1c\uc810\uc73c\ub85c \uc0bc\uc73c\uba74 \ub9c8\uc57c\uc758 \ub3c4\uc2dc\uac00 \ub3cc\uacfc \uac74\ucd95\ub9cc \ub0a8\uae34 \uacf3\uc774 \uc544\ub2c8\ub77c\ub294 \uc0ac\uc2e4\uc774 \ubcf4\uc778\ub2e4. \ubb38\uc790\ub294 \uc655\uacfc \uc804\uc7c1, \uc758\ub840\uc640 \uc2dc\uac04\uc744 \uae30\ub85d\ud588\ub2e4. \uc5f0\uad6c\uc790\ub4e4\uc774 \uadf8\uac83\uc744 \uc77d\uc744 \uc218 \uc788\uac8c \ub418\uba74\uc11c \uce68\ubb35\ud558\ub294 \ub4ef\ud588\ub358 \uc720\uc801\uc758 \ubaa8\uc2b5\ub3c4 \ub2ec\ub77c\uc84c\ub2e4. \uc774\ub984 \ubaa8\ub97c \uc0ac\ub78c\ub4e4\uc774 \ub9cc\ub4e0 \uc2e0\ube44\ud55c \uac74\ucd95\uc774\ub77c\ub294 \uc778\uc0c1\uc5d0\uc11c, \uc2a4\uc2a4\ub85c \uacfc\uac70\ub97c \ub0a8\uae34 \uc0ac\ud68c\uc758 \uc5ed\uc0ac\ub85c \ud55c \uac78\uc74c \ub354 \ub4e4\uc5b4\uac08 \uc218 \uc788\uac8c \ub41c \uac83\uc774\ub2e4. \ub9c8\uc57c\uc758 \uc5ec\ub7ec \ub3c4\uc2dc\ub294 \ub2e8 \ud55c \uba85\uc758 \ud669\uc81c\uac00 \ubaa8\ub450 \ub2e4\uc2a4\ub9b0 \ub098\ub77c\uc640 \uac19\uc9c0 \uc54a\uc558\ub2e4. \uace0\uc804\uae30\uc5d0\ub294 \uc218\ub9ce\uc740 \ub3c4\uc2dc\uad6d\uac00\uac00 \uc788\uc5c8\uace0 \ud314\ub81d\ucf00\ub3c4 \uadf8 \uac00\uc6b4\ub370 \ud558\ub098\uc600\ub2e4. \uac01 \ub3c4\uc2dc\uc5d0\ub294 \ud1b5\uce58\uc790\uac00 \uc788\uc5c8\uc73c\uba70 \uc11c\ub85c \uacbd\uc7c1\ud558\uace0 \ub3d9\ub9f9\uc744 \ub9fa\uc5c8\ub2e4. \uc624\ub298\uc758 \uad6d\uac00 \uc9c0\ub3c4\uc640 \ub2f9\uc2dc\uc758 \uc815\uce58 \uc9c0\ub3c4\ub97c \uadf8\ub300\ub85c \uacb9\uce60 \uc218 \uc5c6\ub294 \uc774\uc720\ub2e4. \ub3c4\uc2dc\ub9c8\ub2e4 \ubcc4\ub3c4\uc758 \uad8c\ub825\uc774 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c\uba74 \ud070 \uc0ac\uc6d0\uacfc \uae30\ub85d\ub3c4 \ub2e4\ub974\uac8c \ubcf4\uc778\ub2e4. \uadf8\uac83\uc740 \ub9c8\uc57c \uc804\uccb4\ub97c \uc704\ud55c \uae30\ub150\ubb3c\uc774\ub77c\ub294 \ub113\uc740 \uc124\uba85\ub9cc\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \ud2b9\uc815 \ub3c4\uc2dc\uc758 \uc655\uc2e4\uc774 \uc790\uc2e0\uc758 \uc704\uc0c1\uc744 \ub4dc\ub7ec\ub0b4\uace0 \uae30\uc5b5\uc744 \ub0a8\uae30\ub294 \ud589\uc704\uc600\ub2e4. \uc774\uc6c3 \ub3c4\uc2dc\uc640\uc758 \uad00\uacc4\ub3c4 \uadf8 \uae30\uc5b5\uc5d0 \ub4e4\uc5b4\uac04\ub2e4. \uc9c0\uae08 \ubcf4\ub294 \uc11d\uc870 \uc720\uc801\uc5d0\uc11c\ub294 \ub3cc\uc758 \ubc1d\uc740 \uc0c9\uacfc \ub179\uc0c9 \uc232\uc758 \ub300\ube44\uac00 \ub208\uc5d0 \ub748\ub2e4. \ud558\uc9c0\ub9cc \uace0\uc804\uae30\uc758 \ub9c8\uc57c \uac74\ucd95\uc5d0\ub294 \ucc44\uc0c9\uc774 \uc788\uc5c8\ub2e4. \uc0c9\uc774 \uc0ac\ub77c\uc9c4 \ud45c\uba74\uc744 \ucc98\uc74c\ubd80\ud130 \uc7a5\uc2dd \uc5c6\ub294 \ud770 \uac74\ucd95\uc73c\ub85c \uc0c1\uc0c1\ud558\uba74 \uacfc\uac70\uc758 \uc2dc\uac01\uc801 \uacbd\ud5d8\uc744 \ub193\uce5c\ub2e4. \ub0a8\uc544 \uc788\ub294 \ubaa8\uc2b5\uc740 \uae34 \uc2dc\uac04\uc758 \uacb0\uacfc\ub2e4. \ubb38\uc790\uc640 \uc870\uac01\ub3c4 \uac19\uc740 \uacf5\uac04 \uc548\uc5d0\uc11c \ubcf4\uc544\uc57c \ud55c\ub2e4. \uac74\ucd95\uc758 \uaddc\ubaa8\uc640 \ud45c\uba74\uc758 \ud45c\ud604\uc774 \ud568\uaed8 \ud1b5\uce58\uc790\uc758 \uc774\uc57c\uae30\ub97c \uc804\ud588\ub2e4. \uc720\uc801\uc740 \uadf8\uc800 \uc2e4\uc6a9\uc801\uc778 \uac74\ubb3c\uc758 \uc794\ud574\uac00 \uc544\ub2c8\ub77c \uc0ac\ub78c\ub4e4\uc5d0\uac8c \ubb34\uc5c7\uc778\uac00\ub97c \ubcf4\uc5ec \uc8fc\ub824 \ud588\ub358 \uacf5\uac04\uc774\ub2e4. \uae00\uc744 \uc77d\uc744 \uc218 \uc788\ub294 \uc0ac\ub78c\uacfc \uadf8\ub807\uc9c0 \ubabb\ud55c \uc0ac\ub78c\uc758 \uacbd\ud5d8\ub3c4 \uac19\uc9c0 \uc54a\uc558\uc744 \uac83\uc774\ub2e4. \ub9c8\uc57c \ubb38\uc790\uc5d0\ub294 \uc5b8\uc5b4\uc758 \uc18c\ub9ac\ub97c \uae30\ub85d\ud558\ub294 \uc694\uc18c\ub3c4 \uc788\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \ub300\uc0c1\uc744 \ub2e8\uc21c\ud788 \uadf8\ub9bc\uc73c\ub85c \uadf8\ub824 \ub73b\uc744 \uc804\ud558\ub294 \ubc29\uc2dd\ub9cc\uc73c\ub85c \uc124\uba85\ud560 \uc218 \uc5c6\ub2e4. \ubcf5\uc7a1\ud55c \uae30\ud638\ub97c \uc2e4\uc81c \uc5b8\uc5b4\uc640 \uc5f0\uacb0\ud574 \uc77d\uc5b4\uc57c \uc778\ubb3c\uacfc \uc0ac\uac74\uc5d0 \uc811\uadfc\ud560 \uc218 \uc788\ub2e4. \ubaa8\uc591\uc774 \uc544\ub984\ub2f5\ub2e4\ub294 \uac10\uc0c1\uacfc \ubb38\uc7a5\uc744 \ud574\ub3c5\ud558\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uc5f0\uad6c\uc790\ub4e4\uc740 \uc624\ub79c \ub300\uc870\uc640 \ud574\ub3c5\uc744 \uac70\uccd0 \uc774\ub7f0 \uae30\ub85d\uc744 \uc77d\uc5b4 \uc654\ub2e4. \uae00\uc790\uac00 \uc874\uc7ac\ud55c\ub2e4\uace0 \ud574\uc11c \ud6c4\ub300\uc758 \uc0ac\ub78c\uc774 \uace7\ubc14\ub85c \uc77d\uc744 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc790\ub8cc\uac00 \ub208\uc55e\uc5d0 \ub0a8\uc544 \uc788\ub294 \uac83\uacfc \uadf8 \uc758\ubbf8\uc5d0 \uc811\uadfc\ud560 \uc218 \uc788\ub294 \uac83 \uc0ac\uc774\uc5d0\ub294 \uc5f0\uad6c\uc758 \uc2dc\uac04\uc774 \ud544\uc694\ud558\ub2e4. \ud314\ub81d\ucf00\uc758 \ubb38\uc790\ub3c4 \uadf8 \uacfc\uc815\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ub9c8\uc57c\uc758 \ube44\ubb38\uc5d0\ub294 \uc815\uce58\uc801 \uc5ed\uc0ac\uc640 \uc758\ub840, \uc804\ud22c\uc640 \uacc4\ubcf4\uac00 \uae30\ub85d\ub418\uc5c8\ub2e4. \uc655\uc2e4\uc774 \ub204\uad6c\uc640 \uc5f0\uacb0\ub418\uace0 \uc5b4\ub5a4 \ud589\uc704\ub97c \ud588\ub294\uc9c0 \ub4dc\ub7ec\ub0b4\ub294 \uc790\ub8cc\ub2e4. \uc774\ub984\uacfc \uc0ac\uac74\uc744 \uc77d\uc744 \uc218 \uc788\uc73c\uba74 \uac74\ucd95\ubb3c\uc758 \ud06c\uae30\ub9cc\uc73c\ub85c \uc9d0\uc791\ud558\ub358 \uad8c\ub825\uc758 \ubaa8\uc2b5\uc5d0 \uad6c\uccb4\uc801\uc778 \uc778\ubb3c\uc774 \ub4e4\uc5b4\uc628\ub2e4. \uadf8\ub807\ub2e4\uace0 \uae30\ub85d\ub41c \ub0b4\uc6a9\uc774 \ubaa8\ub450 \uacf5\uc815\ud55c \uc5ed\uc0ac\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud1b5\uce58\uc790\uac00 \ub0a8\uae30\ub294 \uc804\uc7c1 \uc774\uc57c\uae30\ub294 \uc2b9\ub9ac\uc640 \uc815\ub2f9\uc131\uc744 \uac15\uc870\ud560 \uc218 \uc788\ub2e4. \ubb34\uc5c7\uc744 \uc790\ub791\ud558\uace0 \ubb34\uc5c7\uc744 \uc0dd\ub7b5\ud588\ub294\uc9c0 \ubb3b\ub294 \uc77c\uc774 \ud544\uc694\ud558\ub2e4. \ubb38\uc790\ub97c \uc77d\ub294 \ub2e8\uacc4 \ub2e4\uc74c\uc5d0\ub294 \uadf8 \ub9d0\uc744 \ud55c \uad8c\ub825\uc758 \uc785\uc7a5\uae4c\uc9c0 \uc77d\ub294 \ub2e8\uacc4\uac00 \uc788\ub2e4. \ub9c8\uc57c\uc758 \ub3c4\uc2dc\uad6d\uac00\ub4e4\uc740 \uc804\uc7c1\uc744 \ubc8c\uc600\uace0 \ud328\ubc30\ud55c \ucabd\uc740 \ubb3c\uc790\ub098 \ub178\ub3d9\uc73c\ub85c \ubd80\ub2f4\uc744 \uc9c0\uae30\ub3c4 \ud588\ub2e4. \uc804\uc7c1\uc744 \uc655\ub4e4\uc758 \uc601\uc6c5\ub2f4\uc73c\ub85c\ub9cc \uc18c\uac1c\ud558\uba74 \uadf8 \uacb0\uacfc\uac00 \uc881\uc544\uc9c4\ub2e4. \ub18d\uc0b0\ubb3c\uacfc \uc9c1\ubb3c, \uc0ac\ub78c\uc758 \uc77c\uc774 \ub2e4\ub978 \uad8c\ub825\uc73c\ub85c \ub118\uc5b4\uac00\ub294 \uacfc\uc815\uc774\uae30\ub3c4 \ud588\ub2e4. \uc655\uc2e4\uc758 \uae30\ub85d \ub4a4\uc5d0\ub294 \uc774\ub7f0 \uc0dd\ud65c\uc758 \ubcc0\ud654\uac00 \uc788\ub2e4. \ubaa8\ub4e0 \ub3c4\uc2dc\uac00 \uc5b8\uc81c\ub098 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc9c0\ubc30\ub418\uc5c8\ub2e4\uace0 \uc77c\ubc18\ud654\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ub2e4\ub9cc \ub3c4\uc2dc \uc0ac\uc774\uc758 \uacbd\uc7c1\uc774 \uc2e4\uc81c \uc790\uc6d0\uc758 \uc774\ub3d9\uacfc \uc5f0\uacb0\ub418\uc5c8\ub2e4\ub294 \uc810\uc740 \uc911\uc694\ud558\ub2e4. \uc6c5\uc7a5\ud55c \uae30\ub150\ubb3c\uacfc \uc804\uc7c1\uc758 \ubb38\uc7a5\uc740 \ub204\uac00 \ube44\uc6a9\uc744 \uac10\ub2f9\ud588\ub294\uac00\ub77c\ub294 \uc9c8\ubb38\uacfc \ud568\uaed8 \uc77d\uc5b4\uc57c \ud55c\ub2e4. \uad8c\ub825\uc758 \uc790\uae30\uc18c\uac1c\uac00 \uace7 \uc0ac\ud68c \uc804\uccb4\uc758 \uacbd\ud5d8\uc740 \uc544\ub2c8\ub2e4. \ub9c8\uc57c\ub294 \uc11c\ub85c \ub2e4\ub978 \uc8fc\uae30\uc758 \ub2ec\ub825\uc744 \uc0ac\uc6a9\ud588\uace0 \uae34 \uc2dc\uac04\uc744 \uc138\ub294 \ubc29\ubc95\ub3c4 \ubc1c\uc804\uc2dc\ucf30\ub2e4. \ub0a0\uc9dc\ub97c \uc801\ub294 \uac83\uc740 \uc758\ub840\uc640 \uc815\uce58\uc801 \uc0ac\uac74\uc744 \uc9c8\uc11c \uc788\uac8c \uc5f0\uacb0\ud558\ub294 \uc77c\uc774\uc5c8\ub2e4. \uadf8\ub7f0\ub370 \ud604\ub300\uc758 \ub300\uc911\ubb38\ud654\ub294 \uadf8 \ubcf5\uc7a1\ud55c \uccb4\uacc4\ub97c \uc138\uacc4\uc758 \ub05d\uc5d0 \uad00\ud55c \uc218\uc218\uaed8\ub07c\ub85c \ubc14\uafb8\uc5b4 \uc18c\uac1c\ud558\uae30\ub3c4 \ud588\ub2e4. \ub300\ud45c\uc801\uc778 \uac83\uc774 2012\ub144 \uc885\ub9d0\uc124\uc774\ub2e4. \uc2dc\uac04\uc758 \uc8fc\uae30\uac00 \ub05d\ub098\uace0 \uc0c8 \uc8fc\uae30\ub85c \ub118\uc5b4\uac04\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc138\uacc4\uac00 \ud30c\uad34\ub41c\ub2e4\ub294 \uc8fc\uc7a5\uc740 \uac19\uc9c0 \uc54a\ub2e4. \uc720\uc801\uc744 \uc2e0\ube44\ub86d\uac8c \ubcf4\uc774\uac8c \ud558\ub824\uace0 \ub9cc\ub4e0 \uc124\uba85\uc774 \uc624\ud788\ub824 \uc2e4\uc81c \uc9c0\uc2dd\uc744 \uac00\ub9b4 \uc218 \uc788\ub2e4. \uae30\ub85d\uc744 \uc77d\ub294 \ubaa9\uc801\uc740 \ub0af\uc126\uc744 \uacfc\uc7a5\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uadf8 \uc0ac\ud68c\uac00 \uc2dc\uac04\uc744 \ub2e4\ub8ec \ubc29\uc2dd\uc744 \uc774\ud574\ud558\ub294 \ub370 \uc788\ub2e4. \ud314\ub81d\ucf00\ub97c \ub9c8\uc57c \ubb38\uc790\ub85c \uc77d\ub294 \uac83\uc740 \uac74\ucd95 \uac10\uc0c1\uc744 \ud3ec\uae30\ud558\ub294 \uc77c\uc774 \uc544\ub2c8\ub2e4. \uadf8 \uac74\ucd95\uc744 \uc138\uc6b4 \uc0ac\ub78c\ub4e4\uc774 \ub0a8\uae30\ub824 \ud588\ub358 \ub9d0\uae4c\uc9c0 \ub354\ud558\ub294 \uac83\uc774\ub2e4. \ub3cc\uacfc \ud68c\ubc18\uc8fd\uc758 \ud45c\uba74\uc740 \uc7a5\uc2dd\uc774\uba74\uc11c \uae30\ub85d\uc774\uc5c8\uace0, \uadf8 \uae30\ub85d\uc5d0\ub294 \ud2b9\uc815\ud55c \uad8c\ub825\uc758 \uae30\uc5b5\uc774 \ub2f4\uacbc\ub2e4. \uc544\ub984\ub2e4\uc6c0\uacfc \uc5ed\uc0ac\uc801 \ud574\uc11d\uc774 \ud568\uaed8 \ub113\uc5b4\uc9c4\ub2e4. \ub9c8\uc57c\uc758 \uacfc\uac70\ub97c \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uc0ac\ub77c\uc9c4 \ubb38\uba85\uc758 \uc218\uc218\uaed8\ub07c\ub85c\ub9cc \ub300\ud558\uc9c0 \uc54a\ub294 \uac83\ub3c4 \uc911\uc694\ud558\ub2e4. \uc624\ub798\ub41c \ub3c4\uc2dc\uc758 \ubcc0\ud654\uc640 \uc0ac\ub78c\ub4e4\uc758 \uc644\uc804\ud55c \uc18c\uba78\uc740 \uac19\uc740 \ub9d0\uc774 \uc544\ub2c8\ub2e4. \ub0a8\uc740 \ubb38\uc790\ub97c \uc77d\ub294 \uc77c\uc740 \uacfc\uac70\ub97c \ub0ad\ub9cc\uc801\uc778 \uce68\ubb35 \uc18d\uc5d0 \uac00\ub450\ub294 \ub300\uc2e0, \uc774\ub984\uacfc \ub9d0\uacfc \uc120\ud0dd\uc744 \uac00\uc9c4 \uc0ac\ub78c\ub4e4\uc758 \uc2dc\uac04\uc73c\ub85c \ub418\ub3cc\ub824 \ub193\ub294\ub2e4."}, {"id": "panjikent-sogdian-merchants-and-mural", "title": "\ud310\uc9c0\ucf04\ud2b8 \u2014 \ubcbd\ud654 \uc18d \uae30\uc0ac\ub294 \uc65c \uc2e4\ud06c\ub85c\ub4dc\ub97c \ub5a0\uc62c\ub9ac\uac8c \ud560\uae4c", "summary": "\ud310\uc9c0\ucf04\ud2b8\uc758 \uc2e4\uc81c \ubcbd\ud654\uc5d0\uc11c \uc18c\uadf8\ub4dc \ub3c4\uc2dc\uc640 \uc0c1\uc778\uc758 \uc5b8\uc5b4, \uc885\uad50\uc640 \ubb38\ud654\uc758 \uc774\ub3d9\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/panjikent-sogdian-merchants-and-mural/index.html", "image": "../media/panjikent-sogdian-merchants-and-mural.jpg", "alt": "\ud310\uc9c0\ucf04\ud2b8\uc5d0\uc11c \ubc1c\uacac\ub41c 6~7\uc138\uae30 \ubcbd\ud654. \ub9d0\uc744 \ud0c4 \ubb34\uc7a5\ud55c \uc804\uc0ac\uac00 \ubcf4\uc778\ub2e4.", "text": "\ud310\uc9c0\ucf04\ud2b8 \u2014 \ubcbd\ud654 \uc18d \uae30\uc0ac\ub294 \uc65c \uc2e4\ud06c\ub85c\ub4dc\ub97c \ub5a0\uc62c\ub9ac\uac8c \ud560\uae4c \uc624\ub298\ub0a0 \ud0c0\uc9c0\ud0a4\uc2a4\ud0c4\uc5d0 \ub0a8\uc740 \uc18c\uadf8\ub4dc\uc778\uc758 \ub3c4\uc2dc\uc640 \uad50\ub958 \ud310\uc9c0\ucf04\ud2b8\uc758 \uc2e4\uc81c \ubcbd\ud654\uc5d0\uc11c \uc18c\uadf8\ub4dc \ub3c4\uc2dc\uc640 \uc0c1\uc778\uc758 \uc5b8\uc5b4, \uc885\uad50\uc640 \ubb38\ud654\uc758 \uc774\ub3d9\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc0c9\uc774 \ubc14\ub79c \ubcbd \uc704\uc5d0 \ub9d0\uc744 \ud0c4 \uc804\uc0ac\uac00 \ub0a8\uc544 \uc788\ub2e4. \uc624\ub298\ub0a0 \ud0c0\uc9c0\ud0a4\uc2a4\ud0c4\uc758 \ud310\uc9c0\ucf04\ud2b8\uc5d0\uc11c \ub098\uc628 \ubcbd\ud654\ub2e4. \uc2e4\ud06c\ub85c\ub4dc\ub77c\ub294 \uc774\ub984\uc744 \ub4e4\uc73c\uba74 \ub099\ud0c0\ubd80\ud130 \ub5a0\uc624\ub974\uc9c0\ub9cc, \uae38 \uc704 \uc0ac\ub78c\ub4e4\uc740 \uc774\ub7f0 \uadf8\ub9bc\uc774 \uc788\ub294 \uc9d1\uacfc \ub3c4\uc2dc\ub85c \ub3cc\uc544\uac14\ub2e4. \uc18c\uadf8\ub4dc\uc778\uc740 \uc911\uc559\uc544\uc2dc\uc544 \uad50\uc5ed\uc5d0\uc11c \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud588\ub2e4. \uadf8\ub4e4\uc744 \ub2e8\uc9c0 \ube44\ub2e8\uc744 \uc62e\uae34 \uc0c1\uc778\uc73c\ub85c\ub9cc \uae30\uc5b5\ud558\uba74 \ub3c4\uc2dc\uc758 \ubc29\uacfc \uc5b8\uc5b4, \uc11c\ub85c \ub2e4\ub978 \ubbff\uc74c\uc774 \ub9cc\ub098\ub358 \uc0dd\ud65c\uc740 \uc27d\uac8c \ubcf4\uc774\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uc18c\uadf8\ub514\uc544\ub294 \uc9c0\uae08\uc758 \uc6b0\uc988\ubca0\ud0a4\uc2a4\ud0c4\uacfc \ud0c0\uc9c0\ud0a4\uc2a4\ud0c4 \uc77c\ub300\uc5d0 \uac78\uccd0 \uc788\uc5c8\ub2e4. \uc0ac\ub9c8\ub974\uce78\ud2b8\uc640 \ubd80\ud558\ub77c, \ud310\uc9c0\ucf04\ud2b8 \uac19\uc740 \ub3c4\uc2dc\ub4e4\uc774 \uc790\ub9ac\ud588\ub2e4. \ubaa8\ub450 \ud558\ub098\uc758 \uc655\uc774 \ub2e4\uc2a4\ub9ac\ub294 \ub611\uac19\uc740 \uacf5\uac04\uc73c\ub85c \ubb36\uc5ec \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ub7ab\ub3d9\uc548 \uc5ec\ub7ec \uc81c\uad6d\uacfc \uc138\ub825\uc758 \uc601\ud5a5\uc744 \ubc1b\uc740 \uc774 \uc9c0\uc5ed\uc740 \uadf8\ub9cc\ud07c \ub2e4\uc591\ud55c \uc0ac\ub78c\uc744 \uc811\ud588\ub2e4. \uae38\uc740 \ub3c4\uc2dc\ub97c \uadf8\ub0e5 \uc9c0\ub098\uac00\uc9c0 \uc54a\uc558\ub2e4. \ubb3c\uac74\uc744 \ubc14\uafb8\uace0 \uc26c\uc5b4 \uac00\uba70 \ud544\uc694\ud55c \uc0ac\ub78c\uc744 \ub9cc\ub098\ub294 \uc7a5\uc18c\uac00 \uc788\uc5b4\uc57c \uba3c \uad50\uc5ed\ub3c4 \uc774\uc5b4\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \uc18c\uadf8\ub4dc \uc0c1\uc778\ub4e4\uc740 \uc11c\ucabd\uc758 \uc138\uacc4\uc640 \ucd08\uc6d0\uc758 \uc720\ubaa9\ubbfc, \ub3d9\ucabd\uc758 \uc911\uad6d\uc744 \uc787\ub294 \uad50\uc5ed\uc5d0 \ucc38\uc5ec\ud588\ub2e4. \uc0c1\ub300\uac00 \ubc14\ub00c\uba74 \ub9d0\uacfc \uad00\uc2b5\ub3c4 \ub2ec\ub77c\uc84c\ub2e4. \uc5ec\ub7ec \uc5b8\uc5b4\ub97c \ub2e4\ub8e8\uace0 \ub2e4\ub978 \uc0ac\ud68c\uc758 \ubc29\uc2dd\uc744 \uc544\ub294 \ub2a5\ub825\uc740 \uc911\uc694\ud55c \uc790\uc0b0\uc774\uc5c8\ub2e4. \ubb3c\uac74\uc758 \ud488\uc9c8\uacfc \uac12\ub9cc\ud07c \uc57d\uc18d\uc744 \uc774\ud574\ud558\ub294 \uc77c\ub3c4 \ud544\uc694\ud588\ub2e4. \ub204\uac00 \ubb34\uc5c7\uc744 \uc6d0\ud558\ub294\uc9c0 \uc804\ud558\uace0, \ub0af\uc120 \ud48d\uc2b5\uc774 \ub73b\ud558\ub294 \ubc14\ub97c \uc54c\uc544\uc57c \ud588\ub2e4. \uc0c1\uc778\uc758 \uc774\ub3d9\uc740 \uc9d0\uc744 \uc62e\uae30\ub294 \uc77c\uc774\uba74\uc11c \uc11c\ub85c \ub2e4\ub978 \uc0ac\ub78c \uc0ac\uc774\uc758 \ub73b\uc744 \uc774\uc5b4 \uc8fc\ub294 \uc77c\uc774\uae30\ub3c4 \ud588\ub2e4. \uc911\uad6d\uc758 \ube44\ub2e8\uacfc \uc0dd\uc0b0\ud488, \ucd08\uc6d0\uc5d0\uc11c \uc5bb\uc740 \uac00\uc8fd\uacfc \ub3d9\ubb3c\uc131 \ubb3c\ud488\uc774 \uad50\ud658\ub418\uc5c8\ub2e4. \uc9c0\uc5ed\ub9c8\ub2e4 \uac00\uc9c4 \uac83\uc774 \ub2ec\ub790\uae30\uc5d0 \uc911\uac04\uc5d0\uc11c \uc5f0\uacb0\ud558\ub294 \uc5ed\ud560\uc774 \ucee4\uc84c\ub2e4. \uc18c\uadf8\ub4dc\uc778\uc758 \ud65c\ub3d9 \ubb34\ub300\ub294 \uc911\uc559\uc544\uc2dc\uc544\uc758 \uace0\ud5a5 \ub3c4\uc2dc\uc5d0\ub9cc \uba38\ubb3c\uc9c0 \uc54a\uc558\ub2e4. \uc911\uad6d\uc758 \ub454\ud669\uacfc \uc7a5\uc548 \uac19\uc740 \uacf3\uc5d0\ub3c4 \uadf8\ub4e4\uc758 \uacf5\ub3d9\uccb4\uac00 \uc788\uc5c8\ub2e4. \ud55c \uba85\uc758 \uc5ec\ud589\uc790\uac00 \ubaa8\ub4e0 \uac70\ub9ac\ub97c \ud63c\uc790 \uc655\ubcf5\ud558\ub294 \ubaa8\uc2b5\ubcf4\ub2e4 \uc5ec\ub7ec \uac70\uc810\uc758 \uc0ac\ub78c\ub4e4\uc774 \uad00\uacc4\ub97c \uc774\uc5b4 \uac00\ub294 \uc7a5\uba74\uc744 \uc0dd\uac01\ud558\uba74 \uad50\uc5ed\ub9dd\uc774 \uc870\uae08 \ub354 \uc120\uba85\ud574\uc9c4\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc790\ub8cc\ub294 6~7\uc138\uae30\uc758 \uc804\uc0ac \ubcbd\ud654\ub2e4. \ub9d0\uacfc \ubb34\uc7a5\ud55c \uc778\ubb3c\uc774 \uc911\uc2ec\uc744 \uc774\ub8ec\ub2e4. \uc774 \uc9c0\uc5ed\uc758 \ud68c\ud654\uac00 \uc774\ub780\uacc4 \uc138\uacc4\uc758 \uc804\uc0ac \ubb38\ud654\uc640\ub3c4 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\uc74c\uc744 \uc0b4\ud53c\uac8c \ud558\ub294 \uc720\ubb3c\uc774\ub2e4. \uadf8\ub7ec\ub098 \ubcbd\ud654 \uc18d \uc778\ubb3c\uc744 \ubcf4\uace0 \ud2b9\uc815 \uc0c1\uc778\uc758 \ucd08\uc0c1\uc774\ub098 \uc2e4\uc81c \uc804\ud22c \ud604\uc7a5\uc774\ub77c\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc804\uc0ac\ub294 \uc0c1\uc778\uc774 \uc544\ub2c8\ub77c \uadf8\ub9bc\uc758 \uc8fc\uc81c\ub2e4. \uc0c1\uc5c5 \ub3c4\uc2dc\uc758 \uc8fc\ubbfc\uc774 \uc5b4\ub5a4 \uc774\ubbf8\uc9c0\ub97c \ubc29 \uc548\uc5d0 \ub450\uc5c8\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c \ud765\ubbf8\ub86d\ub2e4. \uc18c\uadf8\ub4dc\uc778\uc758 \uad50\ub958\uc5d0\ub294 \uc885\uad50\uac00 \ud568\uaed8\ud588\ub2e4. \ubd88\uad50\uc758 \uc804\ud30c\uc5d0 \ucc38\uc5ec\ud588\uace0 \ub9c8\ub2c8\uad50\uc640 \ub3d9\ubc29 \uae30\ub3c5\uad50\uc758 \uc804\ud1b5\ub3c4 \uc811\ud588\ub2e4. \ubb3c\uac74\uc744 \uc6b4\ubc18\ud55c \uae38\uc740 \uc2e0\uc559\uacfc \uc0dd\uac01\uc774 \uc0c8\ub85c\uc6b4 \uc5b8\uc5b4\ub97c \ub9cc\ub098\ub294 \ud1b5\ub85c\uc774\uae30\ub3c4 \ud588\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \uc18c\uadf8\ub4dc\uc778\uc774 \uac19\uc740 \uc885\uad50\ub97c \ubbff\uc5c8\uac70\ub098 \ubaa8\ub4e0 \uacf3\uc5d0\uc11c \uc870\ud654\ub86d\uac8c \uc9c0\ub0c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc5ec\ub7ec \uc804\ud1b5\uc774 \uc774\ub3d9\ud588\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8 \ub9cc\ub0a8\uc774 \ub298 \ud3c9\ud654\ub85c\uc6e0\ub2e4\ub294 \uc8fc\uc7a5\uc740 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \uad50\ub958\ub294 \ub2e4\uc591\uc131\uc744 \ub0b3\uc73c\uba74\uc11c \uac08\ub4f1\ub3c4 \ud488\uc744 \uc218 \uc788\uc5c8\ub2e4. 8\uc138\uae30\uc5d0\ub294 \uc911\uc559\uc544\uc2dc\uc544\uc5d0\uc11c \uc774\uc2ac\ub78c \uc138\ub825\uc758 \uc601\ud5a5\uc774 \ucee4\uc84c\ub2e4. \uc18c\uadf8\ub514\uc544\uc758 \ub3c4\uc2dc\uc640 \uc0c1\uc778\ub3c4 \uadf8 \ubcc0\ud654 \uc18d\uc5d0\uc11c \uc0b4\uc544\uac14\ub2e4. \uc0c8\ub85c\uc6b4 \uc815\uce58 \uad8c\ub825\uacfc \uc885\uad50, \uac70\ub798 \uc0c1\ub300\uc5d0 \ub9de\ucdb0 \uad00\uacc4\ub97c \ub2e4\uc2dc \ub9cc\ub4e4\uc5b4\uc57c \ud588\ub2e4. \uc624\ub798\ub41c \uae38\uc774 \uc788\ub2e4\uace0 \uadf8 \uae38\uc758 \uaddc\uce59\uae4c\uc9c0 \uc601\uc6d0\ud788 \uac19\uc9c0\ub294 \uc54a\uc558\ub2e4. \uc9c0\ubc30 \uc138\ub825\uc774 \ubc14\ub00c\uba74 \ud1b5\ud589\uacfc \uac70\ub798\uc758 \uc870\uac74\ub3c4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc18c\uadf8\ub4dc\uc778\uc758 \uc774\uc57c\uae30\ub294 \uace0\uc815\ub41c \uc2e4\ud06c\ub85c\ub4dc\ubcf4\ub2e4 \ubcc0\ud654\uc5d0 \ub300\uc751\ud558\ub358 \uc0ac\ub78c\ub4e4\uc758 \uc5ed\uc0ac\ub97c \ubcf4\uc5ec \uc900\ub2e4. \uc5ed\uc0ac\ucc45\uc5d0\uc11c\ub294 \uac70\ub300\ud55c \uc81c\uad6d\uc758 \uc774\ub984\uc774 \uba3c\uc800 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uadf8 \uc0ac\uc774\uc758 \ub3c4\uc2dc \uc0ac\ub78c\uc740 \ubb3c\uac74\uc744 \uc804\ub2ec\ud558\ub294 \uc870\uc5f0\ucc98\ub7fc \ubcf4\uc774\uae30 \uc27d\ub2e4. \ud558\uc9c0\ub9cc \uad50\ub958\uac00 \uc2e4\uc81c\ub85c \uc774\ub8e8\uc5b4\uc9c0\ub294 \uacfc\uc815\uc5d0\ub294 \uc5b8\uc5b4\uc640 \uc7a5\uc18c\ub97c \uc544\ub294 \uc774\ub4e4\uc758 \uc120\ud0dd\uc774 \ud544\uc694\ud588\ub2e4. \uc18c\uadf8\ub4dc\uc778\uc744 \ubcf4\uba74 \uc815\ubcf5\uc790\uac00 \ub9cc\ub4e0 \uc9c0\ub3c4\uc640 \uc0ac\ub78c\ub4e4\uc774 \uc624\uac00\ub358 \uc138\uacc4\uac00 \uaf2d \uc77c\uce58\ud558\uc9c0 \uc54a\uc558\uc74c\uc744 \uc54c\uac8c \ub41c\ub2e4. \uc815\uce58\uc801 \uacbd\uacc4\ub97c \ub118\ub294 \uad00\uacc4\uac00 \uc788\uc5c8\uace0 \uace0\ud5a5\uc744 \ub5a0\ub098 \uc790\ub9ac \uc7a1\uc740 \uacf5\ub3d9\uccb4\ub3c4 \uc788\uc5c8\ub2e4. \uc5f0\uacb0\uc740 \uba85\ub839\ub9cc\uc73c\ub85c \uc0dd\uae30\uc9c0 \uc54a\uc558\ub2e4. \uc624\ub798\ub41c \ubcbd\ud654\ub97c \ubcf4\uba74 \uba3c\uc800 \ub204\uad6c\ub97c \uadf8\ub838\ub294\uc9c0 \uc815\ub2f5\uc744 \ucc3e\uace0 \uc2f6\uc5b4\uc9c4\ub2e4. \ud558\uc9c0\ub9cc \uc774\ub984\uc744 \ubaa8\ub978\ub2e4\uace0 \ubcfc \uac83\uc774 \uc5c6\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub9d0\uc758 \uc790\uc138\uc640 \uc637, \uc8fc\ubcc0\uc758 \ubb34\ub2ac\ub97c \uc0b4\ud53c\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \uadf8 \uacf5\uac04\uc5d0\uc11c \uc911\uc694\ud558\uac8c \uc5ec\uae34 \uc774\ubbf8\uc9c0\uc5d0 \ub2e4\uac00\uac08 \uc218 \uc788\ub2e4. \uadf8\ub9bc\uc758 \uc138\ubd80\ub97c \uace7\ubc14\ub85c \ub2f9\uc2dc \ubaa8\ub4e0 \uc8fc\ubbfc\uc758 \uc0dd\ud65c\ub85c \ud655\ub300\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ubcbd\ud654\ub97c \uafb8\ubc00 \uc218 \uc788\ub294 \uacf5\uac04\uacfc \uadf8\ub807\uc9c0 \ubabb\ud55c \uacf5\uac04\uc740 \ub2ec\ub790\uc744 \uac83\uc774\ub2e4. \ub0a8\uc740 \uc720\ubb3c\uc740 \ub3c4\uc2dc\ub97c \ubcf4\ub294 \uadc0\ud55c \ucc3d\uc774\uba74\uc11c \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \ubaa8\uc2b5\uc744 \uace0\ub974\uac8c \ub2f4\uc740 \ucc3d\uc740 \uc544\ub2c8\ub2e4. \uc774 \ud55c\uacc4\ub97c \uae30\uc5b5\ud558\uba74 \ubcbd\ud654\uac00 \uc624\ud788\ub824 \uad6c\uccb4\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4. \uc2e4\ud06c\ub85c\ub4dc\ub77c\ub294 \uac70\ub300\ud55c \uc774\ub984 \uc544\ub798 \ubb3b\ud788\uae30 \uc26c\uc6b4 \ubc29 \ud558\ub098\uc758 \uc7a5\uc2dd\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \uadf8 \ubc29\uc5d0\uc11c \uc0c1\uc778\uc774 \uc2e4\uc81c\ub85c \ubb34\uc5c7\uc744 \ub9d0\ud588\ub2e4\uace0 \uafb8\ubbf8\uc9c0 \uc54a\uc544\ub3c4 \ub3c4\uc2dc\uac00 \ubb38\ud654\uc758 \uc7a5\uc18c\uc600\uc74c\uc744 \ucda9\ubd84\ud788 \ub290\ub084 \uc218 \uc788\ub2e4. \ud310\uc9c0\ucf04\ud2b8\uc758 \ubcbd\ud654\ub294 \uc0ac\ub77c\uc9c4 \ub3c4\uc2dc\uc758 \ubaa8\ub4e0 \uac83\uc744 \uc124\uba85\ud574 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub798\ub3c4 \uad50\uc5ed\ub85c\uc758 \uc810 \ud558\ub098\uc600\ub358 \uc7a5\uc18c\uc5d0 \uc0c9\uacfc \uc7a5\uba74\uc744 \ub3cc\ub824\uc900\ub2e4. \ubb3c\uac74\uc744 \uc62e\uae30\ub358 \uc0ac\ub78c\ub4e4\uc5d0\uac8c\ub3c4 \uafb8\ubbf8\uace0 \uc774\uc57c\uae30\ud558\uba70 \uc0b4 \uacf5\uac04\uc774 \uc788\uc5c8\ub2e4. \uc2e4\ud06c\ub85c\ub4dc\ub97c \ub2e4\uc2dc \ub5a0\uc62c\ub9b4 \ub54c \uae34 \uc0ac\ub9c9\uae38 \uc606\uc5d0 \uc774\ub7f0 \ubc29 \ud558\ub098\ub97c \ub193\uc544 \ubcf4\uc790. \uc138\uacc4\ub97c \uc5f0\uacb0\ud55c \uac83\uc740 \uba3c \uacf3\uc744 \ud5a5\ud574 \ucd9c\ubc1c\ud558\ub294 \uc77c\ubfd0 \uc544\ub2c8\ub77c, \ub3cc\uc544\uac00 \uc0b4 \ub3c4\uc2dc\uc640 \ub0af\uc120 \uc0ac\ub78c\uc744 \ub9de\uc744 \uc7a5\uc18c\ub97c \ub9cc\ub4dc\ub294 \uc77c\uc774\uae30\ub3c4 \ud588\ub2e4."}, {"id": "passport-three-languages", "title": "\uc61b \uc5ec\uad8c \ud55c \uc7a5\uc5d0 \uc138 \uc5b8\uc5b4\uac00 \ubaa8\uc600\ub2e4", "summary": "\ud55c\ubb38\uacfc \uc601\uc5b4, \ud504\ub791\uc2a4\uc5b4\uac00 \ub098\ub780\ud788 \ub193\uc778 \uc5ec\uad8c \uc591\uc2dd\uc744 \ub4e4\uc5ec\ub2e4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/passport-three-languages/index.html", "image": "../media/passport-three-languages.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \ub300\uc870\uc120\uad6d \uc5ec\uad8c \uc591\uc2dd \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc61b \uc5ec\uad8c \ud55c \uc7a5\uc5d0 \uc138 \uc5b8\uc5b4\uac00 \ubaa8\uc600\ub2e4 \ucc45\uc790 \ub300\uc2e0 \ucee4\ub2e4\ub780 \uc885\uc774\ub85c \ub9cc\ub098\ub294 \uc5ec\ud589 \ubb38\uc11c \ud55c\ubb38\uacfc \uc601\uc5b4, \ud504\ub791\uc2a4\uc5b4\uac00 \ub098\ub780\ud788 \ub193\uc778 \uc5ec\uad8c \uc591\uc2dd\uc744 \ub4e4\uc5ec\ub2e4\ubd05\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc5ec\uad8c\uc744 \ub5a0\uc62c\ub9ac\uba74 \uc190\ubc14\ub2e5\ub9cc \ud55c \ucc45\uc790\ub97c \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uadf8\ub7f0\ub370 \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \ub300\uc870\uc120\uad6d \uc5ec\uad8c \uc591\uc2dd\uc740 \ud55c \uc7a5\uc758 \ub113\uc740 \uc885\uc774\ub2e4. \uc0ac\uc9c4\uc744 \ubcf4\uba74 \uac00\uc6b4\ub370\ub97c \uacbd\uacc4\ub85c \uae00\uc904\uc758 \ubaa8\uc2b5\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc77d\uc744 \uc218 \uc788\ub294 \uae00\uc790\ub97c \uba3c\uc800 \ucc3e\uc544\ub3c4 \uc88b\uace0, \ubb38\uc7a5\uc774 \ub193\uc778 \ubc29\ud5a5\ubd80\ud130 \uc0b4\ud3b4\ubcf4\uc544\ub3c4 \uc88b\ub2e4. \ud55c \uc7a5\uc758 \uc885\uc774\uac00 \uc11c\ub85c \ub2e4\ub978 \ub3c5\uc790\ub97c \ub9cc\ub0a0 \uc900\ube44\ub97c \ud558\uace0 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc870\uae08\uc529 \ubcf4\uc778\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc624\ub978\ucabd\uc5d0\ub294 \ud55c\ubb38, \uc67c\ucabd\uc5d0\ub294 \uc601\uc5b4\uc640 \ud504\ub791\uc2a4\uc5b4\ub85c \ub0b4\uc6a9\uc744 \uc778\uc1c4\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc138 \uc5b8\uc5b4\uac00 \uc11c\ub85c \ub2e4\ub978 \ubb38\uc11c\uc5d0 \ud769\uc5b4\uc9c4 \uac83\uc774 \uc544\ub2c8\ub77c \uac19\uc740 \uc885\uc774 \uc704\uc5d0 \ubaa8\uc600\ub2e4. \ud574\uc678\uc5d0\uc11c \uc4f0\ub294 \ubb38\uc11c\ub77c\ub294 \uac83\uc744 \ubaa8\uc591\ub9cc\uc73c\ub85c\ub3c4 \uc2e4\uac10\ud558\uac8c \ub41c\ub2e4. \uc9c0\uae08\uc758 \uc5ec\ud589\uc790\uac00 \ud734\ub300\uc804\ud654 \ubc88\uc5ed \ud654\uba74\uc744 \uaebc\ub0b4\ub4ef, \uc774 \uc885\uc774\ub3c4 \uc5b8\uc5b4\uac00 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ub0b4\uc6a9\uc744 \uc804\ub2ec\ud560 \uc790\ub9ac\ub97c \uac16\ucd94\uace0 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4. \uc774\ub294 \uc624\ub298\uc758 \uacbd\ud5d8\uc5d0 \ube57\ub300\uc5b4 \ubcf4\ub294 \ubc29\ubc95\uc774\ub2e4. \uae00\uc790\ub9cc \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc14\uae65\uc5d0\ub294 \ubc30\uaf43\uacfc \ub369\uad74\uc744 \uc5ee\uc740 \ubb34\ub2ac\uac00 \ub458\ub7ec\uc838 \uc788\uace0, \uac00\uc6b4\ub370 \uc704\ucabd\uc5d0\ub294 \ubc30\uaf43\ubb34\ub2ac, \ub124 \uadc0\ud241\uc774\uc5d0\ub294 \ud0dc\uadf9\ubb34\ub2ac\uac00 \ubc30\uce58\ub418\uc5b4 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc740 \ucc0d\ud78c \ub3c4\uc7a5\uc758 \uc774\ub984\uacfc \uc704\uce58\ub3c4 \ud568\uaed8 \uc18c\uac1c\ud55c\ub2e4. \uba40\ub9ac\uc11c \ubcf4\uba74 \uc7a5\uc2dd\ucc98\ub7fc \ubcf4\uc774\ub294 \ubd80\ubd84\ub4e4\uc774 \ubb38\uc11c\ub97c \uc54c\uc544\ubcf4\uac8c \ud558\ub294 \uc5bc\uad74\uc744 \ub9cc\ub4e0\ub2e4. \uae00\uc744 \ubaa8\ub450 \uc77d\uae30 \uc5b4\ub824\uc6cc\ub3c4 \ud14c\ub450\ub9ac\uc640 \ub3c4\uc7a5\uc744 \ub530\ub77c\uac00\uba74 \ub2e8\uc21c\ud55c \uba54\ubaa8\uc9c0\uc640\ub294 \ub2e4\ub978 \uc131\uaca9\uc758 \uc885\uc774\ub77c\ub294 \uac83\uc744 \ub290\ub07c\uac8c \ub41c\ub2e4. \uac19\uc740 \uc885\uc774\uc5d0 \uc5ec\ub7ec \uc5b8\uc5b4\ub97c \ub193\uc73c\uba74 \uadf8 \ubb38\uc11c\uac00 \ud55c \uc5b8\uc5b4\ub97c \uc4f0\ub294 \uc0ac\ub78c\ub4e4 \uc548\uc5d0\uc11c\ub9cc \uba38\ubb3c\uc9c0 \uc54a\ub3c4\ub85d \uc900\ube44\ud588\ub2e4\ub294 \uc810\uc774 \ubcf4\uc778\ub2e4. \uc5ec\uad8c\uc740 \ub2e4\ub978 \uc7a5\uc18c\uc758 \ub2f4\ub2f9\uc790\uc5d0\uac8c\ub3c4 \uc790\uc2e0\uc744 \uc124\uba85\ud574\uc57c \ud558\ub294 \ubb3c\uac74\uc774\ub2e4. \ub204\uad6c\ub97c \uc704\ud55c \uae00\uc778\uc9c0 \uc0dd\uac01\ud558\uba74 \uc5b8\uc5b4\uc758 \ubc30\uce58\uac00 \ub2e8\uc21c\ud788 \uba4b\uc744 \ub0b4\uae30 \uc704\ud55c \uc120\ud0dd\ucc98\ub7fc \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ub2e4\ub9cc \uc138 \uc5b8\uc5b4\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ub2f9\uc2dc \ubaa8\ub4e0 \uc5ec\ud589\uc790\uac00 \ubaa8\ub4e0 \ub098\ub77c\uc5d0\uc11c \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc778\uc815\ubc1b\uc558\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ubb38\uc11c\ub97c \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc2e4\uc81c \uc2ec\uc0ac \ubc0f \uc0ac\uc6a9\uc758 \uc5ed\uc0ac\ub294 \ubcc4\ub3c4\ub85c \ud655\uc778\ud560 \ubd80\ubd84\uc774\ub2e4. \uc5ec\uae30\uc11c\ub294 \ud55c\ubb38\uacfc \uc601\uc5b4, \ud504\ub791\uc2a4\uc5b4\uac00 \uc5b4\ub5a4 \uc704\uce58\uc5d0 \ub193\uc600\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uba70 \ubc1c\uae09\ud558\ub294 \ucabd\uc774 \uc608\uc0c1\ud55c \uc804\ub2ec\uc758 \ubc94\uc704\ub97c \uc0dd\uac01\ud574 \ubcf8\ub2e4. \ub3c4\uc7a5\uc740 \ubb38\uc11c\uc758 \ubc1c\uae09\uacfc \ud655\uc778 \uad00\uacc4\ub97c \ub4dc\ub7ec\ub0b4\ub294 \ud45c\uc9c0\uac00 \ub420 \uc218 \uc788\ub2e4. \ubc30\uaf43\uacfc \ud0dc\uadf9\uc758 \ubb34\ub2ac\ub3c4 \uc885\uc774\uc758 \uc2dc\uac01\uc801 \uc815\uccb4\uc131\uc744 \ub9cc\ub4e0\ub2e4. \uc5ec\ub7ec \uc5b8\uc5b4\uac00 \ud568\uaed8 \uc788\uc5b4\ub3c4 \uac19\uc740 \ud14c\ub450\ub9ac\uc640 \ud45c\uc9c0\ub97c \uacf5\uc720\ud558\uba74 \ud55c \ubb38\uc11c\ub77c\ub294 \uc778\uc0c1\uc774 \uc774\uc5b4\uc9c4\ub2e4. \uae00\uc744 \uc77d\ub294 \ud589\uc704\uc640 \ubb3c\uac74\uc758 \ud615\uc2dd\uc744 \uc54c\uc544\ubcf4\ub294 \ud589\uc704\uac00 \uacb9\uccd0 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \ud14c\ub450\ub9ac\uac00 \ud654\ub824\ud558\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \ubb38\uc11c\uc758 \ud6a8\ub825\uc774\ub098 \ubaa8\ub4e0 \ub3c4\uc7a5\uc758 \uad8c\ud55c\uc744 \ud310\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uad6c\uccb4\uc801\uc778 \uba85\uce6d\uacfc \uc704\uce58\ub294 \ubc15\ubb3c\uad00 \uc124\uba85\uacfc \ub300\uc870\ud560 \ubd80\ubd84\uc774\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uba3c\uc800 \uae00\uc774 \ub193\uc778 \uad6c\uc5ed\uc744 \ub098\ub208 \ub4a4 \uac00\uc7a5\uc790\ub9ac\ub85c \ub208\uc744 \uc62e\uaca8 \ubcf4\uc790. \uc804\ub2ec\ud560 \ub0b4\uc6a9\uacfc \uadf8 \ub0b4\uc6a9\uc744 \ub2f4\ub294 \uacf5\uc801\uc778 \ud615\uc2dd\uc774 \uac19\uc740 \uc885\uc774 \uc704\uc5d0 \uc900\ube44\ub418\uc5b4 \uc788\uc5c8\ub2e4. \ubc15\ubb3c\uad00\uc740 \uac1c\uad6d \uc5f0\ud638\uc640 \uc678\ubd80\ub77c\ub294 \uae30\uad00 \uba85\uce6d \ub4f1\uc744 \uadfc\uac70\ub85c 1895\ub144 \uc791\uc131\uc73c\ub85c \ucd94\uc815\ud55c\ub2e4. \ub0a0\uc9dc\uac00 \uc624\ub298\uc758 \ubc29\uc2dd\uc73c\ub85c \ud06c\uac8c \uc801\ud600 \uc788\uc9c0 \uc54a\uc544\ub3c4 \ubb38\uc11c\uc758 \ud45c\ud604\uc774 \uc2dc\uae30\ub97c \uc881\ud788\ub294 \ub2e8\uc11c\uac00 \ub418\ub294 \uac83\uc774\ub2e4. \ud55c \ub2e8\uc5b4\uac00 \ub2f9\uc2dc\uc758 \uc81c\ub3c4\ub97c \uac00\ub9ac\ud0a4\uba74 \ub2e4\ub978 \uc2dc\uae30\uc758 \ubb38\uc11c\uc640 \uad6c\ubd84\ud560 \uae38\uc774 \uc0dd\uae34\ub2e4. \uc5ec\uae30\uc11c \ucd94\uc815\uc774\ub77c\ub294 \ub9d0\uc740 \uc9c0\uc6b0\uc9c0 \uc54a\ub294\ub2e4. \uc5ec\ub7ec \ub2e8\uc11c\uac00 \uac19\uc740 \ubc29\ud5a5\uc744 \uac00\ub9ac\ud0a8\ub2e4\ub294 \ud310\ub2e8\uacfc \ud2b9\uc815\ud55c \ub0a0\uc758 \ubc1c\uae09\uc744 \ubaa8\ub450 \ud655\uc778\ud588\ub2e4\ub294 \ud310\ub2e8\uc740 \ub2e4\ub974\ub2e4. \uc624\ub798\ub41c \uc790\ub8cc\uc758 \uc5f0\ub300\ub97c \uc77d\uc744 \ub54c\uc5d0\ub294 \uc774 \ucc28\uc774\ub97c \ub0a8\uaca8 \ub450\ub294 \uac83\uc774 \uc815\ud655\ud558\ub2e4. \uc5b8\uc5b4\uc758 \ub0b4\uc6a9\uc744 \ubab0\ub77c\ub3c4 \uae30\uad00 \uc774\ub984\uacfc \ud45c\uae30 \ubc29\uc2dd\uc774 \ubb38\uc11c\uc758 \uc2dc\uac04\uc744 \uc54c\ub824 \uc904 \uc218 \uc788\ub2e4\ub294 \uc810\uc740 \uc54c\uc544\ub458 \ub9cc\ud558\ub2e4. \uc5ec\uad8c\uc744 \uc18c\uc9c0\ud588\ub358 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ub2e4\ub978 \uacf3\uc73c\ub85c \uc6c0\uc9c1\uc774\ub294 \uc77c\uc744 \uc704\ud55c \ubb38\uc11c\uc600\uc744 \uac83\uc774\ub2e4. \ud6c4\ub300\uc758 \uad00\ub78c\uc790\ub294 \uadf8 \uc885\uc774\uc5d0\uc11c \uad6d\uc81c\uc801\uc778 \ud1b5\uc2e0\uacfc \uc2e0\ubd84 \ud655\uc778\uc758 \ubc29\uc2dd\uc744 \uc0b4\ud540\ub2e4. \uac1c\uc778\uc758 \uc774\ub3d9\uacfc \uad6d\uac00 \uae30\uad00\uc758 \uc5c5\ubb34\uac00 \ud55c \ubb3c\uac74\uc5d0 \ub9cc\ub098\ub294 \uac83\uc774\ub2e4. \ub2e4\ub9cc \uad6c\uccb4\uc801\uc778 \uc5ec\ud589 \uacbd\ub85c\uc640 \uc18c\uc9c0\uc790\uc758 \uac10\uc815\uc740 \ud655\uc778\ud55c \uc790\ub8cc\uac00 \uc5c6\uc73c\uba74 \uc0c8\ub85c \uc4f0\uc9c0 \uc54a\ub294\ub2e4. \uc774\ub807\uac8c \ubcf4\uba74 \uc5ec\uad8c \uc0ac\uc9c4\uc758 \uc791\uc740 \ub3c4\uc7a5\uacfc \ud14c\ub450\ub9ac\uac00 \ub2e8\uc21c\ud55c \uc7a5\uc2dd\uc5d0 \uadf8\uce58\uc9c0 \uc54a\ub294\ub2e4. \ub204\uad70\uac00\uc758 \uc774\ub3d9\uc744 \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc54c\uc544\ubcf4\uace0 \ud655\uc778\ud560 \uc218 \uc788\ub3c4\ub85d \ub9c8\ub828\ud55c \ud615\uc2dd\uc758 \uc77c\ubd80\uc600\ub2e4. \uc2a4\ub9c8\ud2b8\ud3f0 \ubc88\uc5ed \ud654\uba74\uc774\ub77c\ub294 \ud604\ub300\uc758 \ube44\uc720\ub294 \uadf8 \uc804\ub2ec\uc758 \ud544\uc694\ub97c \uac00\uae4c\uc774 \uac00\uc838\uc62c \ubfd0\uc774\ub2e4. \uc2e4\uc81c \ubb38\uc11c\uac00 \uac00\uc9c4 \uc2dc\ub300\uc758 \uc5b8\uc5b4\uc640 \uc81c\ub3c4\ub97c \ub530\ub85c \uc0b4\ud53c\uba74 \uc885\uc774 \ud55c \uc7a5\uc758 \uc774\uc57c\uae30\uac00 \ub354 \ub113\uc5b4\uc9c4\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc774 \uc591\uc2dd\uc5d0 \uc4f0\uc778 \uc5f0\ud638\uc640 \uc678\uad50 \ub2f4\ub2f9 \uad00\uccad\uc758 \uba85\uce6d\uc744 \uadfc\uac70\ub85c \uc791\uc131 \uc2dc\uae30\ub97c 1895\ub144\uc73c\ub85c \ucd94\uc815\ud55c\ub2e4. \ub0a0\uc9dc \ud558\ub098\ub97c \ub9d0\ud558\ub294 \ub370\ub3c4 \ubb38\uc11c \uc548\uc758 \ub2e8\uc11c\ub4e4\uc744 \ud568\uaed8 \uc77d\ub294 \uacfc\uc815\uc774 \ud544\uc694\ud55c \uac83\uc774\ub2e4. \uc774 \uc18c\uc7a5\ud488\uc740 \ud2b9\uc815 \uc5ec\ud589\uc790\uc758 \uc5ec\uc815\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc774 \uc544\ub2c8\ub77c \uc5ec\uad8c \uc591\uc2dd\uc744 \ubcf4\ub294 \uc790\ub8cc\ub2e4. \ub204\uad6c\uc758 \uc9d0\uac00\ubc29\uc5d0 \ub4e4\uc5b4 \uc788\uc5c8\uc744\uc9c0 \uc0c1\uc0c1\ud558\uae30\uc5d0 \uc55e\uc11c, \ud55c \uc885\uc774\uc5d0 \uc138 \uc5b8\uc5b4\ub97c \ub098\ub780\ud788 \ub193\uc558\ub2e4\ub294 \uc120\ud0dd\ubd80\ud130 \uae30\uc5b5\ud574 \ub450\uc790. \uad6d\uacbd\uc744 \ub118\uc744 \uc900\ube44\uac00 \ubb38\uc7a5 \ubc30\uce58\uc5d0\ub3c4 \ub0a8\uc544 \uc788\ub2e4."}, {"id": "penny-post-1840-price-prepayment-and-letters", "title": "\ud398\ub2c8 \uc6b0\ud3b8 1840 \u2014 \ud3b8\uc9c0\ub294 \uc65c \ubc1b\ub294 \uc0ac\ub78c\uc5d0\uac8c \ubd80\ub2f4\uc774\uc5c8\uc744\uae4c", "summary": "1840\ub144 \uc6b0\ud3b8\uc694\uae08 \uac1c\ud601\uacfc \uc120\ubd88, \uc6b0\ud45c\uc640 \uba40\ub808\ub514 \ubd09\ud22c\ub97c \ud1b5\ud574 \uc758\uc0ac\uc18c\ud1b5\uc758 \ubb38\ud131\uc774 \ub2ec\ub77c\uc9c4 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities", "ideas"], "url": "stories/penny-post-1840-price-prepayment-and-letters/index.html", "image": "../media/penny-post-1840-price-prepayment-and-letters.jpg", "alt": "1840\ub144 \uba40\ub808\ub514 \uc6b0\ud3b8 \ubd09\ud22c\uc758 \ub3c4\uc548\uc744 \uc7ac\ud604\ud55c \uc2e4\uc81c \uc5ed\uc0ac \ub3c4\ud310", "text": "\ud398\ub2c8 \uc6b0\ud3b8 1840 \u2014 \ud3b8\uc9c0\ub294 \uc65c \ubc1b\ub294 \uc0ac\ub78c\uc5d0\uac8c \ubd80\ub2f4\uc774\uc5c8\uc744\uae4c \uc694\uae08\ud45c\uc640 \uc120\ubd88, \uc6b0\ud45c\uc640 \ubd09\ud22c\uc5d0\uc11c \uc77d\ub294 \uc601\uad6d\uc758 \ud1b5\uc2e0 \uac1c\ud601 1840\ub144 \uc6b0\ud3b8\uc694\uae08 \uac1c\ud601\uacfc \uc120\ubd88, \uc6b0\ud45c\uc640 \uba40\ub808\ub514 \ubd09\ud22c\ub97c \ud1b5\ud574 \uc758\uc0ac\uc18c\ud1b5\uc758 \ubb38\ud131\uc774 \ub2ec\ub77c\uc9c4 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ud3b8\uc9c0\ub97c \ubc1b\uc558\ub294\ub370 \uc6b0\ud3b8\uc694\uae08\uc744 \ub0b4\uc57c \ud55c\ub2e4\uba74 \uae30\uc05c \uc18c\uc2dd\ub3c4 \ubd80\ub2f4\uc2a4\ub7ec\uc6b8 \uc218 \uc788\ub2e4. 19\uc138\uae30 \uc601\uad6d\uc5d0\uc11c\ub294 \uc774\ub7f0 \uc77c\uc774 \ub0af\uc124\uc9c0 \uc54a\uc558\ub2e4. 1840\ub144\uc758 \uc6b0\ud3b8\uc694\uae08 \uac1c\ud601\uc740 \ud3b8\uc9c0\ub97c \uc870\uae08 \uc2f8\uac8c \ubcf4\ub0b4\ub294 \uc870\uce58\ub97c \ub118\uc5b4 \ub204\uac00 \ube44\uc6a9\uc744 \ub0b4\uace0 \uad6d\uac00\uac00 \ubb34\uc5c7\uc744 \uc11c\ube44\uc2a4\ud574\uc57c \ud558\ub294\uc9c0 \ubc14\uafb8\uc5c8\ub2e4. \uc6b0\ud45c\ubcf4\ub2e4 \uba3c\uc800 \uc694\uae08\uc758 \uc5ed\uc0ac\ub97c \uc0b4\ud3b4\ubcf4\uc790. \uac1c\ud601 \uc804 \uc601\uad6d\uc758 \uc6b0\ud3b8\uc694\uae08\uc740 \uc9c0\uae08\ucc98\ub7fc \uac04\ub2e8\ud558\uc9c0 \uc54a\uc558\ub2e4. \ubcf4\ub0b4\ub294 \uac70\ub9ac\uc640 \ud3b8\uc9c0\ub97c \uc774\ub8e8\ub294 \uc885\uc774\uc758 \uc7a5\uc218 \ub4f1\uc774 \uc694\uae08\uc5d0 \uc601\ud5a5\uc744 \uc8fc\uc5c8\ub2e4. \ubd09\ud22c\uc5d0 \ubcc4\ub3c4\uc758 \uc885\uc774\ub97c \ub123\ub294 \uc77c\ub3c4 \ube44\uc6a9\uc744 \uc0dd\uac01\ud558\uac8c \ub9cc\ub4e4\uc5c8\ub2e4. \uc9e7\uc740 \uc18c\uc2dd \ud55c \ud1b5\uc774 \uac00\uacc4\uc5d0 \uc791\uc9c0 \uc54a\uc740 \uc9c0\ucd9c\uc774 \ub420 \uc218 \uc788\uc5c8\ub2e4. \ubc1c\uc1a1\uc778\uc774 \ubbf8\ub9ac \ub0b4\uae30\ub3c4 \ud588\uc9c0\ub9cc \uc218\uc2e0\uc778\uc774 \ub0b4\ub294 \ubc29\uc2dd\ub3c4 \ub110\ub9ac \uc4f0\uc600\ub2e4. \ubc1b\ub294 \uc0ac\ub78c\uc774 \ub3c8\uc744 \ub0bc \uc218 \uc5c6\uac70\ub098 \uc218\ucde8\ub97c \uac70\uc808\ud558\uba74 \ubc30\ub2ec \uacfc\uc815\uc5d0\uc11c \ubb38\uc81c\uac00 \uc0dd\uacbc\ub2e4. \ud3b8\uc9c0\uc758 \ub0b4\uc6a9\uacfc \ubb34\uad00\ud558\uac8c \uc804\ub2ec\uc758 \ub9c8\uc9c0\ub9c9 \uc21c\uac04\uc5d0 \ube44\uc6a9\uacfc \uc218\ub839 \uc5ec\ubd80\ub97c \uc870\uc815\ud574\uc57c \ud588\ub358 \uac83\uc774\ub2e4. \uc694\uae08\uc774 \ube44\uc2f8\uba74 \uc0ac\ub78c\ub4e4\uc740 \ube48 \uacf5\uac04\uc744 \ucd5c\ub300\ud55c \ucc44\uc6b0\uac70\ub098 \ub2e4\ub978 \uc804\ub2ec \ubc29\ubc95\uc744 \ucc3e\ub294\ub2e4. \ud3b8\uc9c0\uc758 \ubaa8\uc591\uacfc \uc4f0\ub294 \uc2b5\uad00\ub3c4 \uac00\uaca9 \uc81c\ub3c4\uc758 \uc601\ud5a5\uc744 \ubc1b\ub294 \uc148\uc774\ub2e4. \uc624\ub798\ub41c \ud3b8\uc9c0\ub97c \uc77d\uc744 \ub54c \ube7d\ube7d\ud55c \uae00\uc528\ub97c \uac1c\uc778\uc758 \uc131\uaca9\ub9cc\uc73c\ub85c \ud574\uc11d\ud558\uc9c0 \ub9d0\uc544\uc57c \ud558\ub294 \uc774\uc720\uac00 \uc5ec\uae30\uc5d0 \uc788\ub2e4. \uad50\uc721\uc790\uc600\ub358 \ub864\ub7f0\ub4dc \ud790\uc740 \uc6b0\ud3b8 \ud589\uc815\uc758 \uad00\ud589\uc744 \ubc16\uc5d0\uc11c \ub4e4\uc5ec\ub2e4\ubcf4\uc558\ub2e4. \uadf8\ub294 \uc6b0\ud3b8 \ube44\uc6a9 \uac00\uc6b4\ub370 \ud3b8\uc9c0 \ud55c \ud1b5\uc744 \uba3c \uacf3\uc73c\ub85c \uc62e\uae30\ub294 \ucd94\uac00 \ube44\uc6a9\uc774 \uc0dd\uac01\ubcf4\ub2e4 \uc791\uace0, \ubd84\ub958\uc640 \uacc4\uc0b0 \uac19\uc740 \ucc98\ub9ac \uacfc\uc815\uc758 \ubd80\ub2f4\uc774 \ud06c\ub2e4\ub294 \uc810\uc5d0 \uc8fc\ubaa9\ud588\ub2e4. \uadf8\ub807\ub2e4\uba74 \uac70\ub9ac\ub9c8\ub2e4 \uc694\uae08\uc744 \ubcf5\uc7a1\ud558\uac8c \ub9e4\uae30\ub294 \ubc29\uc2dd\uc774 \uc2e4\uc81c \ube44\uc6a9\uc744 \uc798 \ubc18\uc601\ud558\ub294\uc9c0 \ubb3c\uc744 \uc218 \uc788\ub2e4. \ud790\uc758 \uc8fc\uc7a5\uc740 \uc2fc\uac12\uc774\uba74 \uc88b\uaca0\ub2e4\ub294 \ud76c\ub9dd\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc694\uae08\uc744 \ub2e8\uc21c\ud654\ud558\uace0 \uc120\ubd88\uc744 \ub298\ub9ac\uba74 \ucc98\ub9ac\ub3c4 \uc26c\uc6cc\uc9c0\uace0 \ub354 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uc6b0\ud3b8\uc744 \uc4f0\uac8c \ub41c\ub2e4\ub294 \uc124\uacc4\uc600\ub2e4. \ud790\uc740 1837\ub144 \uc6b0\ud3b8 \uac1c\ud601\uc548\uc744 \ubc1c\ud45c\ud588\ub2e4. \ud3b8\uc9c0\uc758 \ubb34\uac8c\ub97c \uae30\uc900\uc73c\ub85c \ub0ae\uace0 \uade0\uc77c\ud55c \uc694\uae08\uc744 \ub9e4\uae30\uc790\ub294 \uad6c\uc0c1\uc740 \uad00\uc2ec\uc744 \ubaa8\uc558\uc9c0\ub9cc \ubc18\ub300\ub3c4 \ucef8\ub2e4. \uc694\uae08\uc744 \ud06c\uac8c \ub0b4\ub9ac\uba74 \uad6d\uac00 \uc218\uc785\uc774 \uc904\uc5b4\ub4e4 \uac83\uc774\ub77c\ub294 \uc6b0\ub824\uac00 \ud2b9\ud788 \uc911\uc694\ud588\ub2e4. \uc0c1\uc778\uacfc \uac1c\ud601 \uc9c0\uc9c0\uc790\ub4e4\uc740 \ud3b8\uc9c0\uc758 \uc655\ub798\uac00 \uac70\ub798\uc640 \uc0dd\ud65c\uc744 \ub3d5\ub294\ub2e4\uace0 \uc8fc\uc7a5\ud588\ub2e4. \uc6b0\uccb4\uad6d\uc744 \uc218\uc785\uc744 \ucd5c\ub300\ud55c \uac70\ub450\ub294 \uae30\uad00\uc73c\ub85c \ubcfc \uac83\uc778\uc9c0, \uc0ac\ud68c\uc758 \uc758\uc0ac\uc18c\ud1b5\uc744 \ub3d5\ub294 \uc2dc\uc124\ub85c \ubcfc \uac83\uc778\uc9c0\uac00 \ucda9\ub3cc\ud588\ub2e4. \uae30\uc220 \ubc1c\uba85 \ud558\ub098\ubcf4\ub2e4 \uc815\ucc45\uc758 \ubaa9\uc801\uc744 \ubc14\uafb8\ub294 \ub17c\uc758\uac00 \uba3c\uc800 \ud544\uc694\ud588\ub2e4. \uc120\ubd88\uc744 \ub298\ub9ac\ub824\uba74 \uc6b0\uccb4\uad6d\uc5d0\uc11c \ub3c8\uc744 \ubc1b\ub294 \uc2dc\uc810\ub9cc \ubc14\uafb8\uc5b4\uc11c\ub294 \ubd80\uc871\ud588\ub2e4. \uc5b4\ub514\uc5d0\uc11c \ubb34\uc5c7\uc744 \uc0ac\uc11c \ubd99\uc774\uace0, \ubc30\ub2ec\ud558\ub294 \ucabd\uc740 \uadf8\uac83\uc744 \uc5b4\ub5bb\uac8c \ud655\uc778\ud560\uc9c0 \uc815\ud574\uc57c \ud588\ub2e4. \ud790\uc758 \uac1c\ud601\uc740 \uc791\uc740 \uc6b0\ud45c\uc640 \ud070 \ud589\uc815 \uc870\uc9c1\uc774 \uc11c\ub85c \ub9de\ubb3c\ub9ac\ub294 \uacfc\uc815\uc774\uae30\ub3c4 \ud588\ub2e4. 1840\ub144 1\uc6d4 10\uc77c \uade0\uc77c\ud55c \ud398\ub2c8 \uc6b0\ud3b8\uc774 \uc2dc\ud589\ub418\uc5c8\ub2e4. \uc77c\uc815\ud55c \ubb34\uac8c \uc774\ub0b4\uc758 \uc120\ubd88 \ud3b8\uc9c0\ub294 \uc601\uad6d \uad6d\ub0b4\uc5d0\uc11c \ub0ae\uc740 \ub3d9\uc77c \uc694\uae08\uc73c\ub85c \ubcf4\ub0bc \uc218 \uc788\uac8c \ub418\uc5c8\ub2e4. \uba3c \uacf3\uc73c\ub85c \ubcf4\ub0bc \ub54c\ub9c8\ub2e4 \ub2e4\ub978 \uac00\uaca9\ud45c\ub97c \ub530\uc838\uc57c \ud588\ub358 \ubd80\ub2f4\uc774 \uc904\uc5c8\ub2e4. \ud55c \ud398\ub2c8\ub77c\ub294 \uc774\ub984\uc774 \ubaa8\ub4e0 \uc885\ub958\uc758 \uc6b0\ud3b8\uc744 \uc870\uac74 \uc5c6\uc774 \ud55c \uac12\uc5d0 \ubcf4\ub0c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ubb34\uac8c\uac00 \ub298\uac70\ub098 \ub2e4\ub978 \uc11c\ube44\uc2a4\uc640 \uc870\uac74\uc774 \ubd99\uc73c\uba74 \ub2ec\ub790\ub2e4. \uc911\uc694\ud55c \ubcc0\ud654\ub294 \uae30\ubcf8 \ud3b8\uc9c0\uc758 \uac00\uaca9\uc744 \ub113\uc740 \ubc94\uc704\uc5d0\uc11c \ub2e8\uc21c\ud558\uace0 \uc608\uce21 \uac00\ub2a5\ud558\uac8c \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \uc810\uc774\ub2e4. \uac19\uc740 \ud574 \ub4f1\uc7a5\ud55c \uc811\ucc29\uc2dd \uc6b0\ud45c\ub294 \uc120\ubd88\uc744 \ub208\uc5d0 \ubcf4\uc774\ub294 \ud45c\uc2dd\uc73c\ub85c \ub9cc\ub4e4\uc5c8\ub2e4. \uac80\uc740 \ubc14\ud0d5\uc5d0 \ube45\ud1a0\ub9ac\uc544 \uc5ec\uc655\uc758 \uc606\uc5bc\uad74\uc744 \ub123\uc740 \ucd08\uae30 \uc6b0\ud45c\uac00 \ud398\ub2c8 \ube14\ub799\uc774\ub2e4. \uc791\uc740 \uc885\uc787\uc870\uac01\uc740 \ubc1c\uc1a1\uc778\uc774 \uc815\ud574\uc9c4 \uc11c\ube44\uc2a4\ub97c \ubbf8\ub9ac \uc0c0\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc804\ub2ec\ud588\ub2e4. \uc774 \ubcc0\ud654\ub294 \uc0ac\ub78c\uc774 \uc77c\uc77c\uc774 \uc694\uae08\uc744 \uc124\uba85\ud558\uace0 \uc218\uc2e0\uc778\uc5d0\uac8c \ub3c8\uc744 \ubc1b\ub294 \ubd80\ub2f4\uc744 \uc904\uc774\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub418\uc5c8\ub2e4. \ub2e4\ub9cc \uc6b0\ud45c\uac00 \uc6b0\ud3b8\uc81c\ub3c4 \uc790\uccb4\ub97c \ucc98\uc74c \ub9cc\ub4e0 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774\ubbf8 \uc788\ub358 \uc6b4\uc1a1\u00b7\ubc30\ub2ec \uc870\uc9c1 \uc704\uc5d0\uc11c \uacb0\uc81c\uc640 \ud655\uc778\uc758 \ubc29\ubc95\uc744 \ubc14\uafbc \uc7a5\uce58\uc600\ub2e4. \ud790\uc758 \uae30\ub85d\uc5d0\ub294 \uac1c\ud601\uc744 \uc9c0\uc9c0\ud55c \uc0ac\ub78c\ub4e4\uc758 \uccad\uc6d0\uacfc \ubc18\ub300, \uc218\uc785 \uac10\uc18c\ub97c \ub458\ub7ec\uc2fc \uac71\uc815\uc774 \ud568\uaed8 \ub0a8\uc544 \uc788\ub2e4. \uacb0\uacfc\ub97c \uc54c\uace0 \uc77d\ub294 \uc624\ub298\uc758 \ub3c5\uc790\uc5d0\uac8c \uc26c\uc6cc \ubcf4\uc774\ub294 \uc120\ud0dd\ub3c4 \ub2f9\uc2dc\uc5d0\ub294 \ubd88\ud655\uc2e4\ud55c \uc815\ucc45\uc774\uc5c8\ub2e4. \ud3b8\uc9c0\uac00 \ub298 \uac83\uc774\ub77c\ub294 \uae30\ub300\ub97c \ud604\uc2e4\uc758 \uc11c\ube44\uc2a4\ub85c \ub9cc\ub4dc\ub294 \uc77c\uc774 \ub0a8\uc544 \uc788\uc5c8\ub2e4. \uc815\ubd80\ub294 \uc6b0\ud45c\ubfd0 \uc544\ub2c8\ub77c \ubbf8\ub9ac \uc694\uae08\uc744 \ub0b8 \uc7a5\uc2dd\uc6a9 \uc6b0\ud3b8\uc9c0\uc640 \ubd09\ud22c\ub3c4 \ub0b4\ub193\uc558\ub2e4. \ud654\uac00 \uc70c\ub9ac\uc5c4 \uba40\ub808\ub514\uac00 \uadf8\ub9b0 \ub3c4\uc548\uc5d0\ub294 \uc601\uad6d\uc744 \uc0c1\uc9d5\ud558\ub294 \uc778\ubb3c\uacfc \uc138\uacc4 \uac01\uc9c0\ub85c \uc18c\uc2dd\uc774 \ud37c\uc9c0\ub294 \uc7a5\uba74\uc774 \ub2f4\uacbc\ub2e4. \uc6b0\ud3b8\uc744 \uc81c\uad6d\uc758 \uc911\uc2ec\uacfc \uc138\uacc4\uc758 \uc5f0\uacb0\ub85c \ubcf4\uc5ec \uc900 \uc774\ubbf8\uc9c0\ub2e4. \uadf8\ub7ec\ub098 \ubcf5\uc7a1\ud558\uace0 \uc7a5\uc911\ud55c \uadf8\ub9bc\uc740 \uc870\ub871\uacfc \ud48d\uc790\uc758 \ub300\uc0c1\uc774 \ub418\uc5c8\ub2e4. \uc815\uc131 \ub4e4\uc5ec \ub514\uc790\uc778\ud588\ub2e4\uace0 \uc0ac\uc6a9\uc790\uac00 \uc88b\uc544\ud558\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc5ec\uae30 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \ub2f9\uc2dc \uba40\ub808\ub514 \ubd09\ud22c\ub97c \uc7ac\ud604\ud55c \uc5ed\uc0ac \ub3c4\ud310\uc774\ub2e4. \ud398\ub2c8 \ube14\ub799 \uc790\uccb4\uc758 \uc0ac\uc9c4\uacfc \ud63c\ub3d9\ud558\uc9c0 \uc54a\ub3c4\ub85d \uad6c\ubd84\ud588\ub2e4. \uac00\uc871\uacfc \uce5c\uad6c, \uac70\ub798 \uc0c1\ub300\uc5d0\uac8c \ud3b8\uc9c0\ub97c \ubcf4\ub0b4\ub294 \ubb38\ud131\uc774 \ub0ae\uc544\uc84c\uc9c0\ub9cc \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \ub3d9\uc2dc\uc5d0 \uac19\uc740 \ud61c\ud0dd\uc744 \ub204\ub9b0 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc77d\uace0 \uc4f0\ub294 \ub2a5\ub825\uacfc \uc2dc\uac04, \uc548\uc815\ub41c \uc8fc\uc18c\uc640 \uc0dd\ud65c \uc870\uac74\ub3c4 \ud544\uc694\ud588\ub2e4. \uac00\uaca9\uc758 \ubcc0\ud654\uac00 \ub2e4\ub978 \ubd88\ud3c9\ub4f1\uc744 \ud55c \ubc88\uc5d0 \uc5c6\uc560\uc9c0\ub294 \ubabb\ud588\ub2e4. \uc6b0\ud3b8\ub7c9\uc758 \uc99d\uac00 \uc5ed\uc2dc \ud558\ub8e8 \ub9cc\uc758 \uc131\uacf5 \uc2e0\ud654\ubcf4\ub2e4 \uae34 \uacfc\uc815\uc73c\ub85c \ubcf4\uc544\uc57c \ud55c\ub2e4. \ud790\uc758 \uc0dd\uc560\uc640 \uac1c\ud601 \uae30\ub85d\uc740 \ub0ae\uc740 \uc694\uae08, \uc120\ubd88, \ubd84\ub958\uc640 \ubc30\ub2ec \uc870\uc9c1\uc774 \ud568\uaed8 \ubc14\ub00c\uc5b4\uc57c \ud588\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc624\ub298 \uc775\uc219\ud55c \uc6b0\ud45c \ub4a4\uc5d0\ub294 \ud1b5\uc2e0\uc744 \ub204\uad6c\ub098 \uc774\uc6a9\ud560 \uc218 \uc788\uac8c \ud558\ub824\ub294 \uc81c\ub3c4\uc758 \uc120\ud0dd\uc774 \uc788\uc5c8\ub2e4. \uba40\ub808\ub514 \ubd09\ud22c\uc758 \ub3c4\uc548\uacfc \uadf8\uac83\uc744 \ud749\ub0b4 \ub0b8 \ud48d\uc790\ubb3c\uc740 \uac19\uc740 \uc81c\ub3c4\ub97c \uc0ac\ub78c\ub4e4\uc774 \uc11c\ub85c \ub2e4\ub974\uac8c \ubc1b\uc544\ub4e4\uc600\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ud3b8\ub9ac\ud55c \uc218\ub2e8\uacfc \uad6d\uac00\uc758 \uc7a5\uc5c4\ud55c \ud64d\ubcf4 \uc774\ubbf8\uc9c0\ub294 \ubc18\ub4dc\uc2dc \uac19\uc740 \ubc29\ud5a5\uc73c\ub85c \ud658\uc601\ubc1b\uc9c0 \uc54a\ub294\ub2e4. \uc0ac\uc6a9\ud558\ub294 \uc0ac\ub78c\uc758 \ubc18\uc751\ub3c4 \uc81c\ub3c4\uc758 \uc5ed\uc0ac\ub97c \ubc14\uafbc\ub2e4."}, {"id": "pepys-fire-and-buried-cheese", "title": "\ud398\ud53c\uc2a4 \u2014 \ub7f0\ub358\uc774 \ubd88\ud0c8 \ub54c \uce58\uc988\ub97c \ub545\uc5d0 \ubb3b\uc740 \uc774\uc720", "summary": "\uc0ac\ubb34\uc5d8 \ud398\ud53c\uc2a4\uc758 \ub300\ud654\uc7ac \uc77c\uae30\ub97c \ub530\ub77c \ud654\uc7ac\uc758 \uad00\ucc30\u00b7\ud53c\ub09c\u00b7\ubb38\uc11c\uc640 \uc74c\uc2dd\uc758 \ubcf4\uc874\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/pepys-fire-and-buried-cheese/index.html", "image": "../media/pepys-fire-and-buried-cheese.png", "alt": "\ub7f0\ub358 \ub300\ud654\uc7ac \ub54c \uc815\uc6d0\uc5d0 \ubb3c\uac74\uc744 \ubb3b\ub294 \uc0c1\ud669\uc744 \ub5a0\uc62c\ub9b0 \uc0c1\uc0c1 \uc7a5\uba74", "text": "\ud398\ud53c\uc2a4 \u2014 \ub7f0\ub358\uc774 \ubd88\ud0c8 \ub54c \uce58\uc988\ub97c \ub545\uc5d0 \ubb3b\uc740 \uc774\uc720 1666\ub144 9\uc6d4\uc758 \uc77c\uae30\uc5d0\uc11c \ub9cc\ub098\ub294 \uc7ac\ub09c\uacfc \uc0dd\ud65c\uc758 \ubb3c\uac74\ub4e4 \uc0ac\ubb34\uc5d8 \ud398\ud53c\uc2a4\uc758 \ub300\ud654\uc7ac \uc77c\uae30\ub97c \ub530\ub77c \ud654\uc7ac\uc758 \uad00\ucc30\u00b7\ud53c\ub09c\u00b7\ubb38\uc11c\uc640 \uc74c\uc2dd\uc758 \ubcf4\uc874\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ub7f0\ub358 \ub300\ud654\uc7ac\ub97c \uae30\ub85d\ud55c \uc0ac\ubb34\uc5d8 \ud398\ud53c\uc2a4\uc758 \uc77c\uae30\uc5d0\ub294 \ub73b\ubc16\uc758 \ubb3c\uac74\uc774 \ub098\uc628\ub2e4. \ud30c\ub974\uba54\uc0b0 \uce58\uc988\ub2e4. 1666\ub144 9\uc6d4 4\uc77c, \uadf8\ub294 \uc774\uc6c3\uacfc \uc815\uc6d0\uc5d0 \uad6c\ub369\uc774\ub97c \ud30c\uace0 \ud3ec\ub3c4\uc8fc\uc640 \ud568\uaed8 \uce58\uc988\ub97c \ub123\uc5c8\ub2e4\uace0 \uc37c\ub2e4. \ub3c4\uc2dc\ub97c \ud0dc\uc6b4 \ud070\ubd88\uc758 \uae30\ub85d \ud55c\uac00\uc6b4\ub370 \uc2dd\ud0c1\uc758 \uc74c\uc2dd\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \uc774 \uc7a5\uba74\uc774 \uc624\ub798 \uae30\uc5b5\ub418\ub294 \uac83\uc740 \uce58\uc988\uac00 \ub3c4\uc2dc\ubcf4\ub2e4 \uc911\uc694\ud574\uc11c\uac00 \uc544\ub2c8\ub2e4. \uc7ac\ub09c\uc744 \uacaa\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ubb34\uc5c7\uc744 \uba3c\uc800 \uc62e\uae30\uace0 \uc5b4\ub5bb\uac8c \ub0a8\uaca8 \ub458\uc9c0 \uad6c\uccb4\uc801\uc778 \uc120\ud0dd\uc774 \uacc4\uc18d \uc0dd\uae30\uae30 \ub54c\ubb38\uc774\ub2e4. \uc77c\uae30\uc758 \uc55e\ub4a4\ub97c \uc77d\uc73c\uba74 \uc791\uc740 \ubb3c\uac74\uc774 \ub193\uc778 \uae34\ubc15\ud55c \ud558\ub8e8\uac00 \ubcf4\uc778\ub2e4. 9\uc6d4 2\uc77c \uc0c8\ubcbd, \ud398\ud53c\uc2a4\ub294 \ud558\ub140 \uc81c\uc778\uc774 \uc2dc\ub0b4\uc758 \ud070\ubd88\uc744 \ubcf4\uc558\ub2e4\uace0 \uae68\uc6b0\uc790 \ucc3d\ubc16\uc744 \uc0b4\ud3c8\ub2e4. \uadf8\ub294 \ubd88\uc774 \ucda9\ubd84\ud788 \uba40\ub9ac \uc788\ub2e4\uace0 \uc0dd\uac01\ud574 \ub2e4\uc2dc \uc7a0\uc790\ub9ac\uc5d0 \ub4e4\uc5c8\ub2e4\uace0 \uc801\uc5c8\ub2e4. \ucc98\uc74c\ubd80\ud130 \uc7ac\ub09c\uc758 \uaddc\ubaa8\ub97c \ubaa8\ub450 \uc54c\uace0 \uc6c0\uc9c1\uc778 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc544\uce68\uc5d0 \ub2e4\uc2dc \uc18c\uc2dd\uc744 \ub4e3\uace0 \ub192\uc740 \uacf3\uc5d0 \uc62c\ub77c\uac00\uc790 \uc0c1\ud669\uc740 \ub2ec\ub77c \ubcf4\uc600\ub2e4. \ub2e4\ub9ac \uc8fc\ubcc0\uacfc \uc2dc\ub0b4\ub85c \ubc88\uc9c0\ub294 \ubd88\uc774 \ub208\uc5d0 \ub4e4\uc5b4\uc654\ub2e4. \uc774 \ubcc0\ud654\ub294 \ub098\uc911\uc5d0 \uc804\uccb4 \uc0ac\uac74\uc744 \uc544\ub294 \ub3c5\uc790\uc640 \uadf8 \uc21c\uac04 \uc870\uae08\uc529 \uc815\ubcf4\ub97c \uc5bb\ub358 \ub2f9\uc0ac\uc790 \uc0ac\uc774\uc758 \ucc28\uc774\ub97c \ubcf4\uc5ec \uc900\ub2e4. \ud398\ud53c\uc2a4\ub294 \uac15\uc73c\ub85c \ub0b4\ub824\uac00 \ubc30\ub97c \ud0c0\uace0 \ubd88\uc744 \uc0b4\ud3c8\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \ubb3c\uac74\uc744 \uc62e\uae30\uace0 \uac15\uac00\uc758 \ubc30\ub85c \ud53c\ud558\ub824\ub294 \ubaa8\uc2b5\ub3c4 \uc801\uc5c8\ub2e4. \uc77c\uae30\uc5d0\ub294 \ub5a0\ub098\uae30\ub97c \ub2a6\ucd94\ub2e4\uac00 \ubd88\uae38\uc774 \uac00\uae4c\uc6cc\uc838\uc11c\uc57c \uc6c0\uc9c1\uc774\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc7a5\uba74\uc774 \ub098\uc628\ub2e4. \ub3c4\uc2dc\ub294 \uc9c0\ub3c4 \uc704\uc758 \uac74\ubb3c\ub4e4\uc774 \uc544\ub2c8\ub77c \uc6c0\uc9c1\uc774\ub294 \uc0ac\ub78c\uacfc \uc9d0\uc73c\ub85c \ub098\ud0c0\ub09c\ub2e4. \uc774\uac83\uc740 \ub7f0\ub358 \uc804\uccb4\ub97c \ube60\uc9d0\uc5c6\uc774 \uc870\uc0ac\ud55c \uae30\ub85d\uc740 \uc544\ub2c8\ub2e4. \ud398\ud53c\uc2a4\uac00 \uc9c0\ub098\uac00\uba70 \ubcf8 \uad6c\uac04\uacfc \uadf8\uc5d0\uac8c \uc804\ud574\uc9c4 \uc18c\uc2dd\uc774\ub2e4. \ub2e4\ub9cc \uac15\uc774 \ud53c\ub09c\uacfc \uc6b4\uc1a1\uc758 \uae38\uc774 \ub418\uc5c8\ub2e4\ub294 \uc810, \ubb3c\uac74\uc744 \uc62e\uae30\ub294 \uc77c\uc774 \uc5bc\ub9c8\ub098 \uc911\uc694\ud588\ub294\uc9c0\ub294 \uadf8\uc758 \uad00\ucc30\uc5d0\uc11c \uc0dd\uc0dd\ud558\uac8c \uc77d\uc744 \uc218 \uc788\ub2e4. \ud574\uad70 \ud589\uc815\uacfc \uad00\ub828\ub41c \uc77c\uc744 \ud558\ub358 \ud398\ud53c\uc2a4\ub294 \ud654\uc774\ud2b8\ud640\ub85c \uac00\uc11c \uc790\uc2e0\uc774 \ubcf8 \uc0c1\ud669\uc744 \uc54c\ub838\ub2e4. \uadf8\ub294 \uc655\uacfc \uc694\ud06c \uacf5\uc791\uc5d0\uac8c \ubd88\uae38\uc744 \ub9c9\uae30 \uc704\ud574 \uc9d1\uc744 \ucca0\uac70\ud560 \ud544\uc694\uac00 \uc788\ub2e4\uace0 \ub9d0\ud588\ub2e4\uace0 \uae30\ub85d\ud55c\ub2e4. \uc655\uc740 \uc2dc\uc7a5\uc5d0\uac8c \uc9c0\uc2dc\ub97c \uc804\ud558\ub3c4\ub85d \ud588\ub2e4. \uc774 \uc7a5\uba74\uc5d0\ub294 \uadf8\uc758 \uc0ac\ud68c\uc801 \uc704\uce58\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \ubaa8\ub4e0 \uc2dc\ubbfc\uc774 \uc655\uc5d0\uac8c \uc9c1\uc811 \ubcf4\uace0\ud560 \uc218 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc77c\uae30 \uc18d\uc758 \uacbd\ud5d8\uc744 \uc77d\uc744 \ub54c \uae30\ub85d\uc790\uac00 \uc5b4\ub5a4 \uc77c\uc744 \ud588\uace0 \ub204\uad6c\ub97c \ub9cc\ub0a0 \uc218 \uc788\uc5c8\ub294\uc9c0\ub3c4 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc7ac\ub09c\uc758 \ubaa9\uaca9\uc5d0\ub294 \uac01\uc790\uc758 \uc815\ubcf4\uc640 \uad00\uacc4\uc758 \ucc28\uc774\uac00 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4. \ubd88\uae38\uc774 \uac00\uae4c\uc6cc\uc9c0\uc790 \ud398\ud53c\uc2a4\ub3c4 \uc790\uc2e0\uc758 \ubb3c\uac74\uc744 \uc62e\uae30\ub294 \ub370 \ud798\uc744 \uc37c\ub2e4. \uc77c\uae30\uc5d0\ub294 \uc9d0\uc744 \uc2e4\uc744 \ubc30\ub97c \uad6c\ud558\uace0 \uc9c1\uc811 \ubb3c\uac74\uc744 \ub098\ub974\ub294 \uacfc\uc815, \uae38\uc774 \uc0ac\ub78c\uacfc \uc9d0\uc73c\ub85c \ub9c9\ud78c \uc0c1\ud669\uc774 \uc774\uc5b4\uc9c4\ub2e4. \uacc4\ud68d\ud55c \uc6b4\uc1a1\ub3c4 \uc2e4\uc81c \ud604\uc7a5\uc5d0\uc11c\ub294 \uc27d\uac8c \uc9c4\ud589\ub418\uc9c0 \uc54a\uc558\ub2e4. \uadf8\uac00 \uc62e\uae30\ub824\ub358 \uac83\uc740 \uac1c\uc778\uc758 \uc7ac\uc0b0\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc0ac\ubb34\uc2e4\uc758 \uae30\ub85d\uacfc \uacf5\uc801\uc778 \uc5c5\ubb34\ub97c \uc774\uc5b4 \uac08 \uc870\uac74\ub3c4 \uc911\uc694\ud588\ub2e4. \ub3c4\uc2dc\uc758 \uae30\ub2a5\uacfc \ud55c \uc9d1\uc758 \uc0dd\ud65c\uc774 \ub3d9\uc2dc\uc5d0 \ud754\ub4e4\ub9ac\ub294 \uc0c1\ud669\uc774\uc5c8\ub2e4. \uce58\uc988\uc758 \uc774\uc57c\uae30\ub294 \uc774\ub7f0 \uc218\ub9ce\uc740 \uc774\ub3d9\uacfc \ud310\ub2e8 \uc0ac\uc774\uc5d0 \ub193\uc5ec \uc788\ub2e4. \uc77c\uae30\uc5d0\uc11c \uc774\uc6c3 \uc70c\ub9ac\uc5c4 \ubc30\ud2bc\uc740 \ud3ec\ub3c4\uc8fc\ub97c \uc62e\uae38 \ubc29\ubc95\uc744 \ucc3e\uc9c0 \ubabb\ud574 \uc815\uc6d0\uc5d0 \uad6c\ub369\uc774\ub97c \ud320\ub2e4. \ud398\ud53c\uc2a4\ub294 \ub2e4\ub978 \uacf3\uc5d0 \ub450\uae30 \uc5b4\ub824\uc6b4 \uc0ac\ubb34\uc2e4\uc758 \ubb38\uc11c\ub97c \uadf8 \uae30\ud68c\uc5d0 \ub123\uc5c8\ub2e4\uace0 \uc37c\ub2e4. \uadf8\ub0a0 \uc800\ub141\uc5d0\ub294 \uc70c\ub9ac\uc5c4 \ud39c\uacfc \ub610 \ub2e4\ub978 \uad6c\ub369\uc774\ub97c \ud30c\uace0 \ud3ec\ub3c4\uc8fc\uc640 \ud30c\ub974\uba54\uc0b0 \uce58\uc988 \ub4f1\uc744 \ub123\uc5c8\ub2e4. \ub530\ub77c\uc11c \ubaa8\ub4e0 \ubb38\uc11c\uc640 \uce58\uc988\ub97c \ud55c \ubc88\uc5d0 \uac19\uc740 \uad6c\ub369\uc774\uc5d0 \ub123\uc740 \ud55c \uc7a5\uba74\uc73c\ub85c \ubb49\ub6b1\uadf8\ub9ac\uba74 \uc77c\uae30\uc758 \uc21c\uc11c\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uc5ec\ub7ec \ucc28\ub840\uc758 \ub300\uc751 \uac00\uc6b4\ub370 \uc74c\uc2dd\ub3c4 \uc9c0\ud0ac \ubb3c\uac74\uc73c\ub85c \uc120\ud0dd\ub41c \uac83\uc774\ub2e4. \uc65c \uadf8 \uce58\uc988\ub97c \uc5bc\ub9c8\ub098 \uc544\uaf08\ub294\uc9c0\uae4c\uc9c0 \ub9c8\uc74c\uc18d \ub3c5\ubc31\uc744 \ucc3d\uc791\ud558\uc9c0 \uc54a\uc544\ub3c4 \ud589\ub3d9 \uc790\uccb4\uac00 \uc0dd\ud65c\uc758 \uad6c\uccb4\uc131\uc744 \uc804\ud574 \uc900\ub2e4. \uadf8\ub0a0 \uc800\ub141\uc758 \uc77c\uae30\uc5d0\ub294 \uc774\uc6c3\uacfc \ud568\uaed8 \uc74c\uc2dd\uc744 \uba39\uc740 \uc77c\ub3c4 \ub098\uc628\ub2e4. \ud398\ud53c\uc2a4\ub294 \uc81c\ub300\ub85c \ucc28\ub9b4 \ubb3c\uac74\uc774 \uc5c6\ub294 \uc2dd\uc0ac\uc640 \ubd88\ube5b\uc73c\ub85c \ubd89\uc5b4\uc9c4 \ud558\ub298\uc744 \uc801\uc5c8\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \uc9d0\uc744 \uc62e\uae30\ub294 \uc77c\uc744 \uba48\ucd98 \ub4a4\uc5d0\ub3c4 \uc544\uc9c1 \uc704\ud5d8\uc774 \ub05d\ub098\uc9c0 \uc54a\uc558\uc74c\uc744 \ub290\uaf08\ub2e4. \uc77c\uae30\uc5d0\ub294 \uc2ac\ud508 \ud615\ud3b8\uacfc \uc7a0\uc2dc \ud568\uaed8 \uc6c3\ub294 \uc2dc\uac04\uc774 \ub098\ub780\ud788 \ub098\ud0c0\ub09c\ub2e4. \uc774\uac83\uc744 \ubaa8\ub4e0 \ud53c\ub09c\ubbfc\uc758 \uac10\uc815\uc73c\ub85c \uc77c\ubc18\ud654\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \ud55c \uc0ac\ub78c\uc758 \uae30\ub85d \uc548\uc5d0\uc11c \ud070 \uacf5\ud3ec\uc640 \uc0dd\ud65c\uc744 \uc774\uc5b4 \uac00\ub824\ub294 \uc6c0\uc9c1\uc784\uc774 \ud568\uaed8 \uc788\ub2e4\ub294 \uc810\uc740 \ubcfc \uc218 \uc788\ub2e4. \uc7ac\ub09c \uc18d \ud558\ub8e8\ub294 \ud55c \uac00\uc9c0 \uac10\uc815\uc73c\ub85c\ub9cc \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\uc558\ub2e4. \uce58\uc988\ub97c \ubb3b\uc740 \uc77c\uc740 \uc7ac\ubbf8\uc788\uc5b4\uc11c \uc27d\uac8c \uc804\ud574\uc9c0\uc9c0\ub9cc, \uc77c\uae30\uc758 \ub2e4\ub978 \uc7a5\uba74\uc5d0\ub294 \ud53c\ub09c\ud558\ub294 \uc0ac\ub78c\uacfc \uc0ac\ub77c\uc9c0\ub294 \uac74\ubb3c, \ubd88\uc744 \ub9c9\uae30 \uc704\ud55c \uc5b4\ub824\uc6b4 \ud310\ub2e8\uc774 \uc788\ub2e4. \uc791\uc740 \uc77c\ud654\ub97c \uc77d\uc740 \ub4a4 \uc55e\ub4a4\uc758 \uc2dc\uac04\uc744 \ud568\uaed8 \ub193\uc73c\uba74 \uc0ac\uac74\uc758 \ubb34\uac8c\uc640 \uac1c\uc778\uc758 \uc120\ud0dd\uc744 \ub3d9\uc2dc\uc5d0 \ubcfc \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \ubb3c\uac74\uc744 \uc815\uc6d0\uc5d0 \ubb3b\ub294 \uc0c1\ud669\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc0c1\uc0c1 \uc18d \uc7a5\uba74\uc774\ub2e4. \ud398\ud53c\uc2a4\uc758 \uc2e4\uc81c \ucd08\uc0c1\uc774\ub098 \uc815\uc6d0, \uce58\uc988\ub97c \ud3ec\uc7a5\ud55c \ubc29\uc2dd\uae4c\uc9c0 \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uadf8\ub9bc\uc758 \uc138\ubd80\uac00 \uc77c\uae30\uc5d0 \ubaa8\ub450 \uae30\ub85d\ub418\uc5b4 \uc788\ub2e4\uace0 \ubc1b\uc544\ub4e4\uc774\uc9c0 \uc54a\ub3c4\ub85d \uad6c\ubd84\ud588\ub2e4. \uc655\uacfc \uc18c\ubc29 \ub300\ucc45\uc758 \uc774\uc57c\uae30\ub9cc\uc73c\ub85c\ub294 \ub3c4\uc2dc\uc758 \uc0dd\ud65c\uc774 \ubaa8\ub450 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ubc18\ub300\ub85c \uce58\uc988 \ud55c \ub369\uc774\ub9cc\uc73c\ub85c \ub300\ud654\uc7ac \uc804\uccb4\ub97c \uc124\uba85\ud560 \uc218\ub3c4 \uc5c6\ub2e4. \ub450 \ud06c\uae30\uc758 \uc7a5\uba74\uc744 \ud568\uaed8 \uc77d\uc744 \ub54c \uc5ed\uc0ac \uc18d \uc0ac\ub78c\uc774 \ubb34\uc5c7\uc744 \uc120\ud0dd\ud574\uc57c \ud588\ub294\uc9c0 \ub354 \uac00\uae4c\uc774 \ub290\ub084 \uc218 \uc788\ub2e4. \ud398\ud53c\uc2a4\uac00 \ubb3b\uc5b4 \ub454 \uac83\uc740 \uba39\uc744\uac70\ub9ac\uc600\uc9c0\ub9cc \uc77c\uae30\uc5d0\ub294 \uadf8 \uc120\ud0dd\uc758 \uc2dc\uac04\uc774 \ub0a8\uc558\ub2e4. \ubb34\uc5c7\uc744 \uac00\uc838\uac00\uace0 \ub204\uad6c\uc640 \uc758\ub17c\ud558\uba70 \ubb34\uc5c7\uc744 \ub098\uc911\uc73c\ub85c \ubbf8\ub8e8\uc5c8\ub294\uac00. \uc791\uc740 \uce58\uc988\uc758 \uc774\uc57c\uae30\ub294 \ud070 \uc7ac\ub09c \uc18d\uc5d0\uc11c \uc0dd\ud65c\uc774 \uc5b4\ub5a4 \ubaa8\uc591\uc73c\ub85c \ubc84\ud2f0\ub824 \ud588\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \ub73b\ubc16\uc758 \uc785\uad6c\ub2e4."}, {"id": "perry-1853-black-ships-and-negotiated-ports", "title": "\ud398\ub9ac\uc758 \ud751\uc120 \u2014 \ubc30\uac00 \ub3c4\ucc29\ud588\ub2e4\uace0 \ubaa8\ub4e0 \ud56d\uad6c\uac00 \uc5f4\ub9b0 \uac83\uc740 \uc544\ub2c8\ub2e4", "summary": "1853\ub144 \ubc29\ubb38\uacfc1854\ub144 \uc870\uc57d, \ub4a4\uc758 \ud1b5\uc0c1 \ubcc0\ud654\ub97c \ub098\ub204\uc5b4 \ub9c9\ubd80\uc758 \uc120\ud0dd\uacfc \uc678\uad50\uc758 \uc555\ubc15\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/perry-1853-black-ships-and-negotiated-ports/index.html", "image": "../media/perry-1853-black-ships-and-negotiated-ports.jpg", "alt": "1855\ub144 \uc77c\ubcf8 \uc6d0\uc815 \uad00\ub828 \ucd9c\ud310\ubb3c\uc5d0 \uc2e4\ub9b0 \uc5d0\ub3c4 \ubd80\uadfc\uc758 \uc2e4\uc81c \uc5ed\uc0ac \ud48d\uacbd \ub3c4\ud310", "text": "\ud398\ub9ac\uc758 \ud751\uc120 \u2014 \ubc30\uac00 \ub3c4\ucc29\ud588\ub2e4\uace0 \ubaa8\ub4e0 \ud56d\uad6c\uac00 \uc5f4\ub9b0 \uac83\uc740 \uc544\ub2c8\ub2e4 1853\ub144 \ubc29\ubb38\uacfc1854\ub144 \ud569\uc758, \ud1b5\uc0c1\uacfc \uac1c\ud56d\uc744 \uad6c\ubd84\ud574 \uc77d\uae30 1853\ub144 \ubc29\ubb38\uacfc1854\ub144 \uc870\uc57d, \ub4a4\uc758 \ud1b5\uc0c1 \ubcc0\ud654\ub97c \ub098\ub204\uc5b4 \ub9c9\ubd80\uc758 \uc120\ud0dd\uacfc \uc678\uad50\uc758 \uc555\ubc15\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc 1853\ub144 \ubbf8\uad6d \ud568\ub300\uac00 \uc5d0\ub3c4\ub9cc\uc5d0 \ub4e4\uc5b4\uc628 \uc77c\uc740 \ud754\ud788 \ub2eb\ud600 \uc788\ub358 \uc77c\ubcf8\uc758 \ubb38\uc774 \uc5f4\ub9ac\ub294 \uc21c\uac04\uc73c\ub85c \uadf8\ub824\uc9c4\ub2e4. \uadf8\ub7ec\ub098 \ubc30\uc758 \ub3c4\ucc29\uacfc \uc870\uc57d, \ud1b5\uc0c1 \uccb4\uc81c\uc758 \ubcc0\ud654 \uc0ac\uc774\uc5d0\ub294 \uc2dc\uac04\uc774 \uc788\uc5c8\ub2e4. \ud398\ub9ac\uc758 \ubc29\ubb38\uc744 \uad70\ud568 \ud55c \ucc99\uc758 \uc704\ub825\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uc9c0 \uc54a\uace0, \uae30\uc874 \uad50\ub958\uc640 \ub9c9\ubd80\uc758 \uc120\ud0dd, \ub2e8\uacc4\uc801\uc73c\ub85c \ub2ec\ub77c\uc9c4 \ud56d\uad6c\uc758 \uc870\uac74\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubcf4\uc790. \uc5d0\ub3c4 \ub9c9\ubd80\ub294 \uc678\uad6d\uacfc\uc758 \uad50\ub958\ub97c \uc5c4\uaca9\ud788 \ud1b5\uc81c\ud588\uc9c0\ub9cc \ubaa8\ub4e0 \uc811\ucd09\uc744 \ub04a\uc9c0\ub294 \uc54a\uc558\ub2e4. \ub098\uac00\uc0ac\ud0a4\ub97c \ud1b5\ud55c \ub124\ub35c\ub780\ub4dc\u00b7\uc911\uad6d\uacfc\uc758 \uac70\ub798, \uc4f0\uc2dc\ub9c8\ub97c \ub9e4\uac1c\ub85c \ud55c \uc870\uc120\uacfc\uc758 \uad00\uacc4 \ub4f1 \uc5ec\ub7ec \ud1b5\ub85c\uac00 \uc788\uc5c8\ub2e4. \uc815\ubcf4\uc640 \ubb3c\uac74\uc740 \uc81c\ud55c\ub41c \uacbd\ub85c\ub85c \uacc4\uc18d \ub4e4\uc5b4\uc654\ub2e4. \uadf8\ub7ec\ubbc0\ub85c \ud398\ub9ac \uc774\uc804\uc744 \uc678\uad6d\uc758 \uc874\uc7ac\ub3c4 \ubaa8\ub974\ub358 \uace0\ub9bd \uc0c1\ud0dc\ub85c \uc0c1\uc0c1\ud558\uba74 \uace4\ub780\ud558\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uad50\ub958\uc758 \uc720\ubb34\ub9cc\uc774 \uc544\ub2c8\ub77c \ub204\uac00 \uc5b4\ub5a4 \ud56d\uad6c\uc5d0\uc11c \ubb34\uc5c7\uc744 \ud560 \uc218 \uc788\uc5c8\ub294\uac00\uc774\ub2e4. \ubbf8\uad6d\uc758 \uc694\uad6c\ub294 \ub9c9\ubd80\uac00 \uad00\ub9ac\ud558\ub358 \uae30\uc874 \ud1b5\ub85c\uc640 \uaddc\uce59\uc744 \ubc14\uafb8\ub77c\ub294 \uc555\ubc15\uc774\uc5c8\ub2e4. \ubc30\uac00 \uc4f0\ub294 \ub3d9\ub825\ub3c4 \uad50\uc12d\uc758 \uc870\uac74\uc774\uc5c8\ub2e4. \ubc14\ub78c\uc758 \ubc29\ud5a5\uc5d0 \ub35c \ub9e4\uc774\ub294 \uc99d\uae30\uc120\uc740 \ud574\uc548\uc758 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uc0c8\ub85c\uc6b4 \ud798\uc744 \ubcf4\uc600\uc9c0\ub9cc \uc5f0\ub8cc\ub97c \uacc4\uc18d \ud655\ubcf4\ud574\uc57c \ud588\ub2e4. \uad70\ud568\uc758 \uc704\ub825\uacfc \ubcf4\uae09\uc758 \ud544\uc694\ub294 \uc11c\ub85c \ubc18\ub300\ub418\ub294 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub77c \uac19\uc740 \ud574\uc591 \uc815\ucc45\uc758 \ub450 \uce21\uba74\uc774\uc5c8\ub2e4. \ubbf8\uad6d \uc120\ubc15\uc758 \ud0dc\ud3c9\uc591 \ud56d\ud574\uc640 \ud3ec\uacbd \ud65c\ub3d9\uc774 \ub298\uba74\uc11c \ubcf4\uae09\uacfc \ub09c\ud30c\uc120\uc6d0\uc758 \ucc98\ub9ac\uac00 \uad00\uc2ec\uc0ac\uac00 \ub418\uc5c8\ub2e4. \uc99d\uae30\uc120\uc758 \uc6b4\ud56d\uc5d0\ub294 \uc5f0\ub8cc\uc640 \uc815\ubc15\uc758 \uc870\uac74\ub3c4 \uc911\uc694\ud588\ub2e4. \uc77c\ubcf8\uc744 \ud5a5\ud55c \uc811\uadfc\uc5d0\ub294 \uad50\uc5ed\ubfd0 \uc544\ub2c8\ub77c \ubc14\ub2e4\ub97c \uac74\ub108\ub294 \uc120\ubc15\ub9dd\uc758 \uc2e4\ubb34\uc801 \ud544\uc694\uac00 \uc5bd\ud600 \uc788\uc5c8\ub2e4. \ubbf8\uad6d\uc740 \uc774\ub7f0 \uc694\uad6c\ub97c \ub300\ub4f1\ud55c \ubbfc\uac04 \uc5ec\ud589\uc790\uc758 \ubd80\ud0c1\uc73c\ub85c\ub9cc \uc804\ub2ec\ud558\uc9c0 \uc54a\uc558\ub2e4. \ud398\ub9ac\uac00 \uc774\ub044\ub294 \ubb34\uc7a5 \ud568\ub300\ub97c \ubcf4\ub0c8\ub2e4. \uc678\uad50 \ubb38\uc11c\uc758 \ubb38\uc7a5\uacfc \uad70\ud568\uc758 \uc874\uc7ac\ub97c \ud568\uaed8 \ubd10\uc57c \ubc29\ubb38\uc774 \uac00\uc9c4 \uc555\ubc15\uc744 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ub300\ud654\uc640 \uac15\uc81c\ub825\uc740 \uac19\uc740 \ud604\uc7a5\uc5d0\uc11c \uc791\ub3d9\ud588\ub2e4. \ud398\ub9ac\uc758 \ud568\ub300\ub294 1853\ub144 \uc5d0\ub3c4\ub9cc\uc5d0 \ub098\ud0c0\ub0ac\ub2e4. \uc99d\uae30\uc120\uacfc \uad70\ud568\uc740 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uac15\ud55c \uc778\uc0c1\uc744 \uc8fc\uc5c8\uace0 \ud751\uc120\uc774\ub77c\ub294 \uc774\ub984\uc73c\ub85c \uae30\uc5b5\ub418\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \ud751\uc120\uc774\ub77c\ub294 \ub9d0\uc774 \ubaa8\ub4e0 \ubc30\uac00 \uac19\uc740 \ub3d9\ub825\uacfc \ud06c\uae30\uc600\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ubbf8\uad6d \ub300\ud1b5\ub839\uc758 \uc11c\ud55c\uc774 \uc804\ub2ec\ub418\uc5c8\uace0 \ud398\ub9ac\ub294 \uace7\ubc14\ub85c \ubaa8\ub4e0 \uc694\uad6c\uc758 \uc2e4\ud604\uc744 \ubcf4\uace0 \ub5a0\ub09c \uac83\uc774 \uc544\ub2c8\ub77c \ub2f5\uc744 \uc694\uad6c\ud558\uba70 \ub2e4\uc2dc \uc624\uaca0\ub2e4\uace0 \ud588\ub2e4. \ub9c9\ubd80\uc5d0\ub294 \uc2dc\uac04\uc744 \uc5bb\uc5b4 \ub300\uc751\uc744 \ub17c\uc758\ud558\ub294 \uacfc\uc81c\uac00 \ub0a8\uc558\ub2e4. \uccab \ubc29\ubb38\uc740 \ud611\uc0c1\uc758 \ub05d\ubcf4\ub2e4 \uc704\uae30\uc758 \uc2dc\uc791\uc5d0 \uac00\uae4c\uc6e0\ub2e4. \ub300\ud1b5\ub839\uc758 \uc11c\ud55c\uc744 \uc5b4\ub514\uc5d0\uc11c \ub204\uad6c\uc5d0\uac8c \uac74\ub12c\uc9c0\ub3c4 \ub2e8\uc21c\ud55c \uc804\ub2ec \uc5c5\ubb34\uac00 \uc544\ub2c8\uc5c8\ub2e4. \uc678\uad6d \uc120\ubc15\uc744 \uc815\ud574\uc9c4 \ud1b5\ub85c\ub85c \ub3cc\ub824\ubcf4\ub0b4\ub824\ub294 \ub9c9\ubd80\uc758 \uad00\ud589\uacfc \uc5d0\ub3c4 \uac00\uae4c\uc774\uc5d0\uc11c \uc9c1\uc811 \uc811\ucd09\ud558\ub824\ub294 \ubbf8\uad6d\uc758 \ubc29\uc2dd\uc774 \ubd80\ub52a\ud614\ub2e4. \uc7a5\uc18c\uc640 \uc758\ub840\ub294 \ud611\uc0c1\ud560 \uad8c\ud55c\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc218\ub2e8\uc774\uae30\ub3c4 \ud588\ub2e4. \uc678\uad6d \uc120\ubc15\uc744 \ubb3c\ub9ac\uce58\uc790\ub294 \uc8fc\uc7a5\uacfc \ubb34\ub825\uc758 \ucc28\uc774\ub97c \uace0\ub824\ud574 \ud0c0\ud611\ud558\uc790\ub294 \uc758\uacac\uc774 \ucda9\ub3cc\ud588\ub2e4. \ub9c9\ubd80\uac00 \uc5ec\ub7ec \ub2e4\uc774\ubb18\uc758 \uc758\uacac\uc744 \uad6c\ud55c \uc77c\uc740 \uc911\uc694\ud55c \uc815\ucc45 \ubb38\uc81c\ub97c \ub2e4\ub8e8\ub294 \ubc29\uc2dd\uc5d0\ub3c4 \ubcc0\ud654\ub97c \uc8fc\uc5c8\ub2e4. \uc678\uc555\uc5d0 \ub300\ud55c \ud310\ub2e8\uc740 \uad6d\ub0b4 \uad8c\ub825 \uad00\uacc4\uc640 \uc774\uc5b4\uc84c\ub2e4. \uc774\ub54c \ubaa8\ub4e0 \uc77c\ubcf8\uc778\uc774 \ub3d9\uc77c\ud55c \uc0dd\uac01\uc73c\ub85c \ucc2c\uc131\ud558\uac70\ub098 \ubc18\ub300\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ud574\uc548 \ubc29\uc5b4\uc640 \uc815\ubcf4 \uc218\uc9d1, \uc678\uad50\uc640 \ud1b5\uce58\uc758 \ucc45\uc784\uc744 \ub204\uac00 \ub9e1\ub294\uc9c0\uc5d0 \ub530\ub77c \uc6b0\ub824\uac00 \ub2ec\ub790\ub2e4. \uc678\ubd80\uc758 \uad70\ud568\uc740 \uae30\uc874\uc758 \uc815\uce58\uc801 \uac08\ub4f1\uc744 \ub4dc\ub7ec\ub0b4\uace0 \ub354 \ud06c\uac8c \ub9cc\ub4dc\ub294 \uacc4\uae30\uac00 \ub418\uc5c8\ub2e4. \ud398\ub9ac\ub294 \ub354 \ud070 \ud568\ub300\ub97c \uc774\ub04c\uace0 \ub3cc\uc544\uc654\uace0 1854\ub144 \uac00\ub098\uac00\uc640 \uc870\uc57d\uc774 \uccb4\uacb0\ub418\uc5c8\ub2e4. \uc2dc\ubaa8\ub2e4\uc640 \ud558\ucf54\ub2e4\ud14c\uc5d0\uc11c \ubbf8\uad6d \uc120\ubc15\uc774 \ubcf4\uae09\uc744 \ubc1b\uc744 \uae38\uc774 \uc5f4\ub838\uace0 \ub09c\ud30c\uc120\uc6d0\uc5d0 \ub300\ud55c \ub300\uc6b0\uc640 \uc678\uad50\uc801 \uc811\ucd09\uc758 \uc870\uac74\uc774 \uc815\ud574\uc84c\ub2e4. \uc0c8\ub85c\uc6b4 \uad00\uacc4\uc758 \ucd9c\ubc1c\uc774\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \uc774\ub97c \uace7\ubc14\ub85c \ubaa8\ub4e0 \ud56d\uad6c\uc5d0\uc11c \uc790\uc720\ubb34\uc5ed\uc774 \uc2dc\uc791\ub41c \uc870\uc57d\uc73c\ub85c \uc124\uba85\ud558\uba74 \ubd80\uc815\ud655\ud558\ub2e4. \ud1b5\uc0c1\uc758 \uad6c\uccb4\uc801\uc778 \uaddc\uce59\uacfc \ub354 \ub113\uc740 \uac1c\ud56d\uc740 \ub4a4\uc758 \ud611\uc57d\uacfc \uc870\uc57d\uc744 \ud1b5\ud574 \ub2ec\ub77c\uc84c\ub2e4. \ud2b9\ud788 1858\ub144\uc758 \ud1b5\uc0c1 \uc870\uc57d\uacfc 1854\ub144\uc758 \ud569\uc758\ub97c \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uac1c\ud56d\uc774\ub77c\ub294 \ub9d0\uc774 \ud558\ub098\uc5ec\ub3c4 \ud56d\uad6c\ubcc4\ub85c \ud560 \uc218 \uc788\ub294 \uc77c\uc774 \ub2ec\ub790\ub2e4\ub294 \uc810\uc744 \uae30\uc5b5\ud558\uba74 \ub4a4\uc758 \uc5ed\uc0ac\ub97c \uc77d\uae30 \uc26c\uc6cc\uc9c4\ub2e4. \ubcf4\uae09\uc744 \ud5c8\uc6a9\ud558\ub294 \uac83\uacfc \uc0c1\ud488 \uac70\ub798\uc758 \uaddc\uce59, \uc678\uad6d\uc778\uc758 \uac70\uc8fc\uc640 \uad00\ud560\uad8c\uc744 \uc815\ud558\ub294 \uac83\uc740 \ubcc4\ub3c4\uc758 \ubb38\uc81c\ub2e4. \uac01\uac01\uc758 \uc870\uc57d\uc774 \ub2e4\ub8ec \ubc94\uc704\ub97c \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uc6d0\uc815\uc5d0 \ucc38\uc5ec\ud55c \uc874 \uc70c\ub81b \uc2a4\ud3f4\ub529\uc758 \ucc45\uc740 \ud56d\ud574\uc640 \uc811\ucd09, \ubc29\ubb38\uc9c0\uc640 \uad50\uc12d\uc758 \ubd84\uc704\uae30\ub97c \uc804\ud55c\ub2e4. \ud604\uc7a5\uc5d0 \uac00\uae4c\uc6b4 \uc0ac\ub78c\uc774 \uc37c\ub2e4\ub294 \uc810\uc740 \uac00\uce58\uac00 \uc788\uc9c0\ub9cc \ubbf8\uad6d\uc758 \ud65c\ub3d9\uc744 \uc815\ub2f9\ud558\uace0 \uc131\uacf5\uc801\uc778 \uc77c\ub85c \ubcf4\uc5ec \uc8fc\ub824\ub294 \uc2dc\uc120\ub3c4 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4. \uadf8\uac00 \ubcf8 \uc77c\ubcf8\uc778\uc758 \ubab8\uc9d3\uc774\ub098 \uad00\uc2b5\uc5d0 \ub300\ud55c \uc778\uc0c1\uc774 \uace7 \uadf8 \uc0ac\ud68c \uc804\uccb4\uc758 \uc0ac\uc2e4\uc740 \uc544\ub2c8\ub2e4. \uc774 \uae00\uc758 \uc2e4\uc81c \uc5ed\uc0ac \ub3c4\ud310\ub3c4 \uc5d0\ub3c4 \ubd80\uadfc\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ub2f9\uc2dc \ucd9c\ud310\ubb3c\uc758 \ud48d\uacbd\uc73c\ub85c, \uc11c\ud55c \uc804\ub2ec \uc7a5\uba74\uc744 \ucd2c\uc601\ud55c \uc0ac\uc9c4\uc774 \uc544\ub2c8\ub2e4. \uae30\ub85d\uc758 \uc704\uce58\ub97c \uc54c\uba74 \uc790\ub8cc\ub97c \ub354 \uc815\ud655\ud788 \uc4f8 \uc218 \uc788\ub2e4. \ud398\ub9ac\uc758 \ubc29\ubb38\uc740 \ud070 \uc804\ud658\uc810\uc774\uc5c8\uc9c0\ub9cc \uadf8\ub0a0 \ub9c9\ubd80\uac00 \ubb34\ub108\uc9c0\uace0 \uba54\uc774\uc9c0 \uad6d\uac00\uac00 \ud0c4\uc0dd\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774\ud6c4\uc758 \uc870\uc57d\uacfc \ud1b5\uc0c1, \ubb3c\uac00\uc640 \uc815\uce58 \uac08\ub4f1, \ubb34\ub825 \ucda9\ub3cc\uc774 \uc774\uc5b4\uc9c0\uba74\uc11c \uad8c\ub825\uc758 \uc870\uac74\uc774 \ub2ec\ub77c\uc84c\ub2e4. \ud55c \uc0ac\uac74\uc744 \ubaa8\ub4e0 \ubcc0\ud654\uc758 \uc720\uc77c\ud55c \uc6d0\uc778\uc73c\ub85c \uc0bc\uc744 \uc218\ub294 \uc5c6\ub2e4. \ud751\uc120\uc744 \uae30\uc5b5\ud560 \ub54c \ubc30\uc758 \uad74\ub69d\ub9cc \ubcf4\uc9c0 \ub9d0\uace0 \ud3b8\uc9c0\uc640 \ud611\uc0c1\uc758 \uc2dc\uac04, \ud56d\uad6c\ubcc4 \uc870\uac74\uc744 \ud568\uaed8 \ubcf4\uc790. \uadf8\ub7ec\uba74 \uac1c\ud56d\uc740 \ub2e8\ub2e8\ud55c \ubb38 \ud558\ub098\ub97c \ubd80\uc21c \uc7a5\uba74\ubcf4\ub2e4, \uc774\ubbf8 \uc5f0\uacb0\ub418\uc5b4 \uc788\ub358 \uc0ac\ud68c\uc758 \uad00\uacc4\uc640 \uaddc\uce59\uc744 \ud798\uc758 \ucc28\uc774 \uc18d\uc5d0\uc11c \ub2e4\uc2dc \uc9dc\ub294 \uacfc\uc815\uc73c\ub85c \ubcf4\uc778\ub2e4. \ubbf8\uad6d \ucabd \ud56d\ud574 \uae30\ub85d\uc740 \uc120\ubc15\uacfc \uc77c\uc815\uc5d0 \uc790\uc138\ud574\ub3c4 \ub9c9\ubd80 \ub0b4\ubd80\uc5d0\uc11c \uc624\uac04 \ub17c\uc758\ub97c \ubaa8\ub450 \uc54c\ub824 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud55c\ucabd \uae30\ub85d\uc758 \uce68\ubb35\uc744 \uc0c1\ub300\uac00 \uc544\ubb34 \uc0dd\uac01\ub3c4 \ud558\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc99d\uac70\ub85c \uc0bc\uc744 \uc218 \uc5c6\ub2e4. \uc54c\ub824\uc9c4 \uc0ac\uc2e4\uacfc \uc790\ub8cc\uc758 \uc2dc\uc57c\ub97c \uad6c\ubd84\ud558\ub294 \uac83\uc774 \uc678\uad50\uc0ac\ub97c \uc77d\ub294 \uae30\ubcf8\uc774\ub2e4."}, {"id": "persepolis-fire-and-clay-records", "title": "\ud398\ub974\uc138\ud3f4\ub9ac\uc2a4 \u2014 \ubd88\ud0c4 \uad81\uc804\uc5d0\uc11c \uc0b4\uc544\ub0a8\uc740 \uae30\ub85d", "summary": "\uac70\ub300\ud55c \uc655\uc2e4 \uc720\uc801\uacfc \uc791\uc740 \uc810\ud1a0\ud310\uc744 \ud1b5\ud574 \ud398\ub974\uc2dc\uc544\uc758 \ud1b5\uce58\uc640 \ud30c\uad34\uc758 \uae30\uc5b5\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/persepolis-fire-and-clay-records/index.html", "image": "../media/persepolis-fire-and-clay-records.jpg", "alt": "\ud398\ub974\uc138\ud3f4\ub9ac\uc2a4 \ud589\uc815 \uae30\ub85d\uc5d0 \uc4f0\uc778 \uc410\uae30\ubb38\uc790 \uc810\ud1a0\ud310 \uc2e4\uc81c \uc0ac\uc9c4", "text": "\ud398\ub974\uc138\ud3f4\ub9ac\uc2a4 \u2014 \ubd88\ud0c4 \uad81\uc804\uc5d0\uc11c \uc0b4\uc544\ub0a8\uc740 \uae30\ub85d \uc655\uc2e4 \uacf5\uac04\u00b7\uc810\ud1a0\ud310\u00b7\uc54c\ub809\uc0b0\ub4dc\ub85c\uc2a4\uc758 \ud654\uc7ac \uc804\uc2b9\uc744 \ub098\ub204\uc5b4 \uc77d\uae30 \uac70\ub300\ud55c \uc655\uc2e4 \uc720\uc801\uacfc \uc791\uc740 \uc810\ud1a0\ud310\uc744 \ud1b5\ud574 \ud398\ub974\uc2dc\uc544\uc758 \ud1b5\uce58\uc640 \ud30c\uad34\uc758 \uae30\uc5b5\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ub192\uc740 \uae30\ub465\uacfc \ubd80\uc11c\uc9c4 \uc11d\uc870 \uac74\ucd95\ub9cc \ub0a8\uc740 \uacf3\uc5d0\uc11c\ub3c4 \ud55c\ub54c\uc758 \uc9c8\uc11c\ub97c \uc0c1\uc0c1\ud560 \uc218 \uc788\ub2e4. \uc624\ub298\ub0a0 \uc774\ub780\uc5d0 \uc788\ub294 \ud398\ub974\uc138\ud3f4\ub9ac\uc2a4\ub294 \uc544\ucf00\uba54\ub124\uc2a4 \uc655\uc870 \ud398\ub974\uc2dc\uc544\uc758 \uc911\uc694\ud55c \uc655\uc2e4 \uc911\uc2ec\uc9c0\uc600\ub2e4. \uac70\ub300\ud55c \uc81c\uad6d\uc774 \uc790\uc2e0\uc744 \ub4dc\ub7ec\ub0b8 \uacf5\uac04\uc774\uc9c0\ub9cc, \uc9c0\uae08 \uc6b0\ub9ac\uac00 \uc77d\ub294 \uc5ed\uc0ac\ub294 \uc655\uc758 \uc704\uc5c4\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uad81\uc804\uc758 \uc720\uc801 \uacc1\uc5d0\ub294 \ud589\uc815\uc744 \uae30\ub85d\ud55c \uc810\ud1a0\ud310\uc774 \uc788\uace0, \ub3c4\uc2dc\ub97c \ubd88\ud0dc\uc6b4 \uc815\ubcf5\uc790\uc5d0 \uad00\ud55c \uc11c\ub85c \ub2e4\ub978 \uc774\uc57c\uae30\uac00 \uc788\ub2e4. \ud070 \uac74\ucd95\uacfc \uc791\uc740 \uae30\ub85d, \uc0ac\uac74\uacfc \ud6c4\ub300\uc758 \uc124\uba85\uc744 \ub098\ub204\uc5b4 \ubcf4\uba74 \uc774 \uc720\uc801\uc740 \ub2e8\uc21c\ud788 \uc81c\uad6d\uc774 \ubb34\ub108\uc9c4 \uc790\ub9ac\ubcf4\ub2e4 \ud6e8\uc52c \ubcf5\uc7a1\ud55c \uc77d\uc744\uac70\ub9ac\uac00 \ub41c\ub2e4. \ud398\ub974\uc2dc\uc544\uc81c\uad6d\uc740 \ub113\uc740 \uc9c0\uc5ed\uacfc \ub2e4\uc591\ud55c \uacf5\ub3d9\uccb4\ub97c \ub2e4\uc2a4\ub838\ub2e4. \ud398\ub974\uc138\ud3f4\ub9ac\uc2a4\ub294 \ub2e4\ub9ac\uc6b0\uc2a4 1\uc138 \uc2dc\ub300\uc758 \uc655\uc2e4 \uad8c\ub825\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc911\uc694\ud55c \uc911\uc2ec\uc774\uc5c8\uc9c0\ub9cc, \uc81c\uad6d\uc5d0\ub294 \uc218\uc0ac\uc640 \ud30c\uc0ac\ub974\uac00\ub2e4\uc774 \uac19\uc740 \ub2e4\ub978 \uc8fc\uc694 \ub3c4\uc2dc\ub3c4 \uc788\uc5c8\ub2e4. \uc624\ub298\uc758 \uc218\ub3c4\ucc98\ub7fc \ubaa8\ub4e0 \uae30\ub2a5\uc774 \ub2e8 \ud55c\uacf3\uc5d0 \ubaa8\uc600\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uc2e4\uc81c \ubaa8\uc2b5\uc744 \ub2e8\uc21c\ud654\ud558\uac8c \ub41c\ub2e4. \uc5ec\ub7ec \uc911\uc2ec\uc744 \uac00\uc9c4 \uc81c\uad6d\uc5d0\uc11c \uc655\uc2e4 \uacf5\uac04\uc740 \ubb34\uc5c7\uc744 \ud558\ub294 \uacf3\uc774\uc5c8\uc744\uae4c. \ud1b5\uce58\uc758 \uc77c\uc744 \ucc98\ub9ac\ud558\uba74\uc11c \uc655\uc758 \uc704\uc0c1\uc744 \ub208\uc5d0 \ubcf4\uc774\uac8c \ud558\ub294 \uae30\ub2a5\ub3c4 \uc788\uc5c8\ub2e4. \uc0ac\ub78c\uacfc \ubb3c\uc790\uac00 \uc624\uac00\ub294 \ub113\uc740 \uc601\ud1a0\ub97c \uc9c0\ubc30\ud558\ub824\uba74 \uba85\ub839\ubfd0 \uc544\ub2c8\ub77c \uadf8 \uc9c0\ubc30\uac00 \uc5b4\ub5a4 \uc9c8\uc11c\uc778\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \uc7a5\uc18c\ub3c4 \ud544\uc694\ud588\ub2e4. \ud398\ub974\uc138\ud3f4\ub9ac\uc2a4\uc758 \uae30\ub465\uacfc \uac74\ubb3c \ud754\uc801\uc740 \ub2f9\uc2dc \uc655\uc2e4 \uac74\ucd95\uc758 \uaddc\ubaa8\ub97c \uc9d0\uc791\ud558\uac8c \ud55c\ub2e4. \uc9c0\uae08\uc740 \ub3cc\uc758 \uc0c9\uacfc \ud3d0\ud5c8\uc758 \uc778\uc0c1\uc774 \uac15\ud558\uc9c0\ub9cc, \ud55c\ub54c\ub294 \uc7a5\uc2dd\uacfc \uc0c9\ucc44\uac00 \uc788\ub294 \uacf5\uac04\uc774\uc5c8\ub2e4. \ub0a8\uc740 \ubd80\ubd84\uc744 \uace7\ubc14\ub85c \uc6d0\ub798\uc758 \uc804\uccb4 \ubaa8\uc2b5\uc774\ub77c\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc5c6\uc5b4\uc84c\uae30 \ub54c\ubb38\uc5d0 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc694\uc18c\ub3c4 \uc788\ub2e4. \uc655\uc758 \uc55e\uc5d0\uc11c \ubab8\uc744 \ub0ae\ucd94\uc5b4\uc57c \ud588\ub358 \uc81c\uad6d\uc758 \uc9c8\uc11c\ub97c \ub5a0\uc62c\ub9ac\uba74 \uaddc\ubaa8\ub3c4 \ub2e4\ub974\uac8c \uc77d\ud78c\ub2e4. \uac74\ucd95\uc740 \uac10\ud0c4\ud560 \ub300\uc0c1\uc774\uba74\uc11c \uc0ac\ub78c\uc758 \uc790\ub9ac\ub97c \ub098\ub204\ub294 \ud658\uacbd\uc774\ub2e4. \ub204\uac00 \ub192\uc740 \uacf3\uc5d0 \uc11c\uace0 \ub204\uac00 \ub2e4\uac00\uac00\uba70 \uc5b4\ub5a4 \uc790\uc138\ub97c \ucde8\ud558\ub294\uc9c0\uac00 \uacf5\uac04\uc758 \uc758\ubbf8\ub97c \ub9cc\ub4e0\ub2e4. \uc544\ub984\ub2e4\uc6c0\uacfc \uc704\uacc4\uac00 \ud568\uaed8 \uc791\ub3d9\ud588\ub2e4. \ud398\ub974\uc138\ud3f4\ub9ac\uc2a4\uc5d0\uc11c \ub098\uc628 \uc218\ub9ce\uc740 \uc810\ud1a0\ud310\uc740 \uc81c\uad6d\uc758 \uc6b4\uc601\uc744 \uc774\ud574\ud558\ub294 \uc911\uc694\ud55c \uc790\ub8cc\ub2e4. \uc410\uae30\ubb38\uc790\ub85c \ub0a8\uc740 \ud589\uc815 \uae30\ub85d\uc740 \uc655\uc744 \ucc2c\uc591\ud558\ub294 \uc6c5\uc7a5\ud55c \ubb38\uc7a5\uacfc\ub294 \ub2e4\ub978 \uc885\ub958\uc758 \uc815\ubcf4\ub97c \uc804\ud55c\ub2e4. \uae30\ub150 \uac74\ucd95\uc774 \ubcf4\uc5ec \uc8fc\ub824\ub294 \ubaa8\uc2b5\uacfc \uc2e4\uc81c \uc6b4\uc601\uc5d0\uc11c \ub0a8\uae34 \ud754\uc801\uc744 \ub098\ub780\ud788 \uc77d\uc744 \uc218 \uc788\ub2e4. \uc81c\uad6d\uc740 \uc804\uc7c1\uc5d0\uc11c \uc774\uae30\ub294 \uc21c\uac04\uc5d0\ub9cc \uc874\uc7ac\ud55c \uac83\uc774 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\uc758 \uc77c\uc744 \uc870\uc9c1\ud558\uace0 \ubb3c\uc790\ub97c \uad00\ub9ac\ud558\uba70 \ud544\uc694\ud55c \ub0b4\uc6a9\uc744 \uc801\uc5b4 \ub450\ub294 \ubc18\ubcf5\ub3c4 \uc788\uc5c8\ub2e4. \uc791\uc740 \uc810\ud1a0\ud310\uc740 \uc774\ub7f0 \uc77c\uc0c1\uc758 \ud589\uc815\uc774 \ud070 \uad8c\ub825\uc744 \uc9c0\ud0f1\ud588\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub208\uc5d0 \ub744\ub294 \ub3cc\uae30\ub465\ub9cc \ubcf4\uc558\uc744 \ub54c \ub193\uce58\uae30 \uc26c\uc6b4 \uc5ed\uc0ac\ub2e4. \ud398\ub974\uc2dc\uc544 \uc0ac\ud68c\uc5d0\ub294 \ub18d\ubbfc\uacfc \uc7a5\uc778, \uae30\ub85d\uc744 \ub2f4\ub2f9\ud558\ub294 \uc11c\uae30\uad00\uacfc \uc0c1\uc778, \uadc0\uc871\uacfc \uc804\uc0ac \ub4f1 \uc11c\ub85c \ub2e4\ub978 \uc704\uce58\uc758 \uc0ac\ub78c\ub4e4\uc774 \uc788\uc5c8\ub2e4. \uc815\ubcf5\ud55c \uc9c0\uc5ed\uc5d0\uc11c\ub294 \ub178\uc608\uc81c\ub3c4 \uc774\uc6a9\ub418\uc5c8\ub2e4. \uc655\uc2e4\uc758 \ud654\ub824\ud568\uc744 \ubaa8\ub4e0 \uc8fc\ubbfc\uc774 \ub204\ub9b0 \ud48d\uc694\ub85c \uace7\ubc14\ub85c \ubc14\uafb8\uc5b4 \uc124\uba85\ud560 \uc218 \uc5c6\ub294 \uc774\uc720\ub2e4. \ud589\uc815 \uae30\ub85d\uc744 \uc77d\ub294 \uc77c\uc740 \uc655 \ud55c \uc0ac\ub78c\uc758 \uc131\uaca9\ub9cc\uc73c\ub85c \uc81c\uad6d\uc744 \uc124\uba85\ud558\ub294 \ubc29\uc2dd\uc5d0\uc11c \ubc97\uc5b4\ub098\uac8c \ud55c\ub2e4. \ub204\uac00 \uc77c\ud558\uace0 \ub204\uac00 \uae30\ub85d\ud558\uba70 \ub204\uac00 \uacb0\uc815\ud588\ub294\uc9c0 \ubb3b\uac8c \ub41c\ub2e4. \ub0a8\uc544 \uc788\ub294 \uc790\ub8cc\uac00 \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \ubaa9\uc18c\ub9ac\ub97c \ub611\uac19\uc774 \uc804\ud574 \uc8fc\uc9c0\ub294 \uc54a\uc9c0\ub9cc, \ud1b5\uce58 \uc544\ub798 \uc5ec\ub7ec \uc0b6\uc774 \uc788\uc5c8\ub2e4\ub294 \ub2e8\uc11c\ub294 \uc81c\uacf5\ud55c\ub2e4. \uae30\uc6d0\uc804 330\ub144 \uc54c\ub809\uc0b0\ub4dc\ub85c\uc2a4\uc758 \uad70\ub300\uac00 \ud398\ub974\uc138\ud3f4\ub9ac\uc2a4\ub97c \ucc28\uc9c0\ud588\ub2e4. \uc774\ud6c4 \uc655\uc2e4 \uac74\ucd95\uc774 \ubd88\ud0c0\uba74\uc11c \ub3c4\uc2dc\uc758 \ubaa8\uc2b5\uc740 \ud06c\uac8c \ub2ec\ub77c\uc84c\ub2e4. \uc81c\uad6d\uc758 \uc6c5\uc7a5\ud568\uc744 \ubcf4\uc5ec \uc8fc\ub358 \uacf3\uc774 \uc815\ubcf5\uacfc \ud30c\uad34\uc758 \uae30\uc5b5\uc744 \ub0a8\uae34 \uc7a5\uc18c\uac00 \ub41c \uac83\uc774\ub2e4. \uadf8\ub7ec\ub098 \uc0ac\uac74\uc774 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8 \ub3d9\uae30\ub97c \uc124\uba85\ud558\ub294 \uc77c\uc740 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \uc220\uc790\ub9ac\uc758 \ud765\ubd84\uacfc \uadf8\ub9ac\uc2a4 \uc5ec\uc131 \ud0c0\uc774\uc2a4\uc758 \ub9d0\uc744 \ud654\uc7ac\uc5d0 \uc5f0\uacb0\ud558\ub294 \uc720\uba85\ud55c \uc804\uc2b9\uc774 \uc788\ub2e4. \uadf8\ub9ac\uc2a4\uc5d0 \ub300\ud55c \ud398\ub974\uc2dc\uc544\uc758 \uacf5\uaca9\uc5d0 \ubcf4\ubcf5\ud588\ub2e4\ub294 \uc124\uba85\ub3c4 \ud568\uaed8 \uc804\ud574\uc9c4\ub2e4. \uc774\ub7f0 \uc774\uc57c\uae30\uac00 \uc778\uc0c1\uc801\uc774\ub77c\uace0 \ud574\uc11c \uc815\ubcf5\uc790\uc758 \ub9c8\uc74c\uc744 \ud604\uc7a5\uc5d0\uc11c \uadf8\ub300\ub85c \uae30\ub85d\ud55c \uc99d\uc5b8\uc73c\ub85c \ubcfc \uc218\ub294 \uc5c6\ub2e4. \ud654\uc7ac\ub97c \uc804\ud558\ub294 \uace0\ub300 \ubb38\ud5cc \uc911\uc5d0\ub294 \uc2e4\uc81c \uc0ac\uac74\ubcf4\ub2e4 \uc624\ub79c \ub4a4\uc5d0 \uc4f0\uc778 \uac83\uc774 \uc788\ub2e4. \ud6c4\ub300\uc758 \uc800\uc790\ub294 \uc55e\uc120 \uc774\uc57c\uae30\uc640 \uc790\uc2e0\uc774 \uc0dd\uac01\ud55c \uad50\ud6c8\uc744 \ud1b5\ud574 \uc0ac\uac74\uc744 \uc815\ub9ac\ud55c\ub2e4. \uadf8\ub798\uc11c \uc5f0\ud68c\uc640 \ubcf5\uc218\uc758 \uc7a5\uba74\uc744 \uc77d\uc744 \ub54c\uc5d0\ub294 \ub204\uac00 \uc5b8\uc81c \uc5b4\ub5a4 \ubaa9\uc801\uc73c\ub85c \uc804\ud588\ub294\uc9c0 \ud568\uaed8 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc5ec\ub7ec \uc124\uba85\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc5ed\uc0ac\ub97c \uc544\ubb34\ub807\uac8c\ub098 \uc0c1\uc0c1\ud574\ub3c4 \ub41c\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uc624\ud788\ub824 \ub0a8\uc740 \uadfc\uac70\uac00 \ub9d0\ud574 \uc8fc\ub294 \ubc94\uc704\ub97c \uc815\ud558\ub294 \uc77c\uc774\ub2e4. \ud654\uc7ac\uc640 \ud30c\uad34\uc758 \uc0ac\uc2e4, \uad6c\uccb4\uc801\uc778 \ud589\ub3d9\uc758 \uc21c\uc11c, \uac1c\uc778\uc758 \ub3d9\uae30\ub294 \ud655\uc778\uc758 \uc815\ub3c4\uac00 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uadf8 \ucc28\uc774\ub97c \ub4dc\ub7ec\ub0b4\ub294 \uc124\uba85\uc774 \ub354 \uc815\ud655\ud55c \uc124\uba85\uc774\ub2e4. \uc624\ub298\uc758 \ud398\ub974\uc138\ud3f4\ub9ac\uc2a4\uc5d0\uc11c\ub294 \uac70\ub300\ud55c \uae30\ub465\uc744 \uc62c\ub824\ub2e4\ubcf4\ub294 \ub208\uacfc \uc791\uc740 \uae30\ub85d\uc744 \uc77d\ub294 \ub208\uc774 \ubaa8\ub450 \ud544\uc694\ud558\ub2e4. \ud558\ub098\ub294 \uad8c\ub825\uc774 \uc790\uc2e0\uc744 \uc5b4\ub5bb\uac8c \ubcf4\uc5ec \uc8fc\uc5c8\ub294\uc9c0 \uc54c\ub824 \uc8fc\uace0 \ub2e4\ub978 \ud558\ub098\ub294 \uadf8 \uad8c\ub825\uc774 \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc600\ub294\uc9c0 \uc774\ud574\ud558\uac8c \ud55c\ub2e4. \ud3d0\ud5c8\uc758 \uc7a5\uad00\uacfc \ud589\uc815\uc758 \uc138\ubd80\ub294 \uc11c\ub85c \ub2e4\ub978 \ud06c\uae30\uc758 \uc5ed\uc0ac\ub2e4. \uc54c\ub809\uc0b0\ub4dc\ub85c\uc2a4\ub294 \ub3c4\uc2dc\ub97c \ud30c\uad34\ud55c \ub4a4 \ud398\ub974\uc2dc\uc544\uc758 \uc655\uc704\ub97c \uc8fc\uc7a5\ud558\uace0 \uad81\uc815\uc758 \uad00\ud589\ub3c4 \ubc1b\uc544\ub4e4\uc600\ub2e4. \uc815\ubcf5\uc774 \uc774\uc804 \uc138\uacc4\ub97c \uc804\ubd80 \ubc84\ub9ac\ub294 \ud589\ub3d9\ub9cc\uc740 \uc544\ub2c8\uc5c8\ub358 \uac83\uc774\ub2e4. \ubb34\ub108\ub728\ub9b0 \uad8c\ub825\uc758 \uc790\ub9ac\uc640 \uad8c\uc704\ub97c \ub2e4\uc2dc \uc774\uc6a9\ud558\ub294 \ubaa8\uc2b5\uc774 \uac19\uc740 \uc778\ubb3c\uc5d0\uac8c\uc11c \ub098\ud0c0\ub09c\ub2e4. \ubd88\ud0d4\ub2e4\uace0 \ubaa8\ub4e0 \uae30\uc5b5\uc774 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc0ac\ub77c\uc9c4 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac74\ucd95\uacfc \uae30\ub85d, \ud6c4\ub300\uc758 \uc774\uc57c\uae30\ub294 \uac01\uac01 \ub2e4\ub978 \ud754\uc801\uc744 \ub0a8\uacbc\ub2e4. \uc774 \uc720\uc801\uc744 \uc81c\uad6d\uc758 \ubab0\ub77d\uc774\ub77c\ub294 \ud55c \uc7a5\uba74\uc73c\ub85c\ub9cc \uae30\uc5b5\ud558\uc9c0 \uc54a\uc744 \ub54c, \ud55c\ub54c \uadf8\uacf3\uc5d0\uc11c \uc77c\ud558\uace0 \uae30\ub85d\ud558\uba70 \ud1b5\uce58\ud588\ub358 \uc0ac\ub78c\ub4e4\uc758 \uc138\uacc4\uac00 \uc870\uae08 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4."}, {"id": "persian-couriers-and-relay-stations", "title": "\ud398\ub974\uc2dc\uc544\uc758 \uc804\ub839 \u2014 \ube60\ub978 \ub9d0 \ub4a4\uc5d0\ub294 \uc5b4\ub5a4 \uc900\ube44\uac00 \uc788\uc5c8\uc744\uae4c", "summary": "\ud398\ub974\uc2dc\uc544\uc758 \ub3c4\ub85c\uc640 \ud5e4\ub85c\ub3c4\ud1a0\uc2a4\uc758 \uc804\ub839 \uae30\ub85d\uc744 \ud1b5\ud574 \ub113\uc740 \uc81c\uad6d\uc758 \ud1b5\uc2e0\uc744 \ub4b7\ubc1b\uce68\ud55c \uc870\uc9c1\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/persian-couriers-and-relay-stations/index.html", "image": "../media/persian-couriers-and-relay-stations.png", "alt": "\ud398\ub974\uc2dc\uc544 \uc5ed\ucc38\uc5d0\uc11c \ub9d0\uc744 \uc900\ube44\ud558\ub294 \uc804\ub839\ub4e4\uc758 \uc0c1\uc0c1 \uc7a5\uba74", "text": "\ud398\ub974\uc2dc\uc544\uc758 \uc804\ub839 \u2014 \ube60\ub978 \ub9d0 \ub4a4\uc5d0\ub294 \uc5b4\ub5a4 \uc900\ube44\uac00 \uc788\uc5c8\uc744\uae4c \uc81c\uad6d\uc758 \uae38\uacfc \uc5ed\ucc38, \ud3b8\uc9c0\ub97c \uc62e\uae30\ub294 \uc0ac\ub78c\ub4e4 \ud398\ub974\uc2dc\uc544\uc758 \ub3c4\ub85c\uc640 \ud5e4\ub85c\ub3c4\ud1a0\uc2a4\uc758 \uc804\ub839 \uae30\ub85d\uc744 \ud1b5\ud574 \ub113\uc740 \uc81c\uad6d\uc758 \ud1b5\uc2e0\uc744 \ub4b7\ubc1b\uce68\ud55c \uc870\uc9c1\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ub9d0\uc744 \ud0c4 \uc804\ub839\uc774 \uba3c \uae38\uc744 \ub2ec\ub9b0\ub2e4. \uc6b0\ub9ac\ub294 \ubcf4\ud1b5 \uadf8 \uc0ac\ub78c\uc758 \uc6a9\uae30\uc640 \ub9d0\uc758 \uc18d\ub3c4\ub97c \uba3c\uc800 \ub5a0\uc62c\ub9b0\ub2e4. \uadf8\ub7f0\ub370 \ub2e4\uc74c \ub9d0\uc744 \uad6c\ud558\uc9c0 \ubabb\ud558\uac70\ub098 \ubb3c\uacfc \uba39\uc774\ub97c \ub9c8\ub828\ud558\uc9c0 \ubabb\ud558\uba74 \ube60\ub978 \ub2ec\ub9ac\uae30\ub294 \uc624\ub798 \uc774\uc5b4\uc9c0\uae30 \uc5b4\ub835\ub2e4. \ud3b8\uc9c0\uac00 \uba40\ub9ac \uac00\ub824\uba74 \uae38 \uc704\uc5d0 \uc900\ube44\ub41c \uac83\ub4e4\uc774 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uace0\ub300 \ud398\ub974\uc2dc\uc544\uc758 \ud1b5\uc2e0\ub9dd\uc740 \uc774 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc900\ube44\ub97c \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc655\uacfc \uc9c0\ubc29\uc758 \ud1b5\uce58\uc790\uac00 \ub113\uc740 \uc9c0\uc5ed\uc5d0\uc11c \uc18c\uc2dd\uc744 \uc8fc\uace0\ubc1b\uae30 \uc704\ud574 \ub3c4\ub85c\uc640 \uac70\uc810, \uc0ac\ub78c\uacfc \ub3d9\ubb3c\uc744 \uc5f0\uacb0\ud588\ub2e4. \uc804\ub839\uc758 \uc774\uc57c\uae30\ub294 \ud63c\uc790 \ub2ec\ub9ac\ub294 \uc601\uc6c5\ubcf4\ub2e4 \ud568\uaed8 \ub9c8\ub828\ud55c \uae38\uc758 \uc774\uc57c\uae30\uc774\uae30\ub3c4 \ud558\ub2e4. \ud398\ub974\uc2dc\uc544 \uc81c\uad6d\uc740 \uc5ec\ub7ec \uc9c0\uc5ed\uacfc \ub3c4\uc2dc\ub97c \uc5f0\uacb0\ud55c \ud070 \uc815\uce58\uccb4\uc600\ub2e4. \uc9c0\ubc29\uc744 \ub9e1\uc740 \ud1b5\uce58\uc790\uc640 \uc911\uc559\uc758 \uc655 \uc0ac\uc774\uc5d0\ub294 \uba85\ub839\uacfc \ubcf4\uace0\uac00 \uc624\uac00\uc57c \ud588\ub2e4. \uad50\uc7ac\ub294 \uc774\ub97c \uc0ac\ud2b8\ub77c\ud504\uc640 \uc655\uc758 \uad00\uacc4 \uc18d\uc5d0\uc11c \uc124\uba85\ud55c\ub2e4. \uc0ac\ud2b8\ub77c\ud504\ub294 \uc81c\uad6d\uc758 \ud55c \uc9c0\uc5ed\uc744 \ub2e4\uc2a4\ub9ac\ub294 \ucc45\uc784\uc790\uc600\ub2e4. \uc9c1\uc811 \ub9cc\ub0a0 \uc218 \uc5c6\ub294 \uac70\ub9ac\uc5d0\uc11c\ub294 \ub9d0\uc744 \ubb38\uc11c\ub85c \uc62e\uae30\ub294 \uc0ac\ub78c\uc774 \ud544\uc694\ud558\ub2e4. \uc655\uc758 \uc9c0\uc2dc\uac00 \ud3b8\uc9c0\uac00 \ub418\uace0 \uadf8 \ud3b8\uc9c0\uac00 \ub2e4\ub978 \ub3c4\uc2dc\ub85c \uc804\ub2ec\ub418\uc5c8\ub2e4. \ub113\uc740 \ub545\uc744 \uc9c0\ubc30\ud55c\ub2e4\ub294 \uac83\uc740 \uad70\ub300\ub97c \ubcf4\ub0bc \ud798\ubfd0 \uc544\ub2c8\ub77c \uba40\ub9ac \uc788\ub294 \uc0c1\ud669\uc744 \uc54c\uace0 \ub73b\uc744 \uc804\ub2ec\ud560 \ub2a5\ub825\uc744 \ud544\uc694\ub85c \ud588\ub2e4. \uad50\uc7ac\ub294 \ud398\ub974\uc2dc\uc544\uac00 \ub354 \uc774\ub978 \uc544\uc2dc\ub9ac\uc544\uc758 \ub3c4\ub85c\ub9dd\uc744 \ubc1b\uc544\ub4e4\uc774\uace0 \uac1c\uc120\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubaa8\ub4e0 \uae38\uc744 \ud55c \uc655\uc774 \ucc98\uc74c\ubd80\ud130 \uc0c8\ub85c \ubc1c\uba85\ud55c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc774\ubbf8 \uc788\ub358 \uc5f0\uacb0\uc744 \ub354 \ub113\uc740 \ud1b5\uce58\uc758 \ub3c4\uad6c\ub85c \ub2e4\ub4ec\uc740 \uac83\uc774\ub2e4. \uc218\uc0ac\uc640 \ud398\ub974\uc138\ud3f4\ub9ac\uc2a4 \uac19\uc740 \uc911\uc694\ud55c \ub3c4\uc2dc\uac00 \uc774\ub7f0 \uae38\ub85c \uc774\uc5b4\uc84c\ub2e4. \uae38\uc774 \ub9ce\ub2e4\ub294 \uac83\ub9cc\uc73c\ub85c \ud1b5\uc2e0\uc774 \uc800\uc808\ub85c \ube68\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uac70\uc810\uc744 \uc5f0\uacb0\ud558\uace0 \uc5b4\ub5bb\uac8c \uad00\ub9ac\ud560\uc9c0 \uc815\ud574\uc57c \ud55c\ub2e4. \ubb3c\ub9ac\uc801\uc778 \ub3c4\ub85c\uc640 \uadf8 \uc704\uc5d0\uc11c \uc6c0\uc9c1\uc774\ub294 \uc870\uc9c1\uc774 \ud568\uaed8 \uc81c\uad6d\uc758 \ud1b5\uc2e0\ub9dd\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \uc655\uc758 \ub3c4\ub85c\uc5d0\ub294 \uc26c\ub294 \uacf3\uacfc \uc219\ubc15 \uc2dc\uc124, \ub9d0\uc774 \uc788\ub294 \uc5ed\ucc38\uc774 \uc788\uc5c8\ub2e4. \ub2ec\ub9ac\ub294 \ubaa8\uc2b5\uacfc\ub294 \ubc18\ub300\ub85c \uba48\ucd94\ub294 \uc7a5\uc18c\ub2e4. \uadf8\ub7ec\ub098 \ub9d0\uc744 \ubc14\uafb8\uace0 \ub2e4\uc74c \uad6c\uac04\uc744 \uc900\ube44\ud560 \uc218 \uc788\uc5c8\uae30\uc5d0 \uc18c\uc2dd\uc758 \uc774\ub3d9\uc740 \ub354 \uc624\ub798 \uc774\uc5b4\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \uc26c\uc9c0 \uc54a\ub294 \ube60\ub974\uae30\uc640 \uc900\ube44\ub41c \uad50\ub300\ub294 \ub2e4\ub978 \ubc29\uc2dd\uc774\ub2e4. \ucc98\uc74c\uc758 \ub9d0\uacfc \uc0ac\ub78c\uc774 \ub05d\uae4c\uc9c0 \ubaa8\ub4e0 \uad6c\uac04\uc744 \uac10\ub2f9\ud574\uc57c \ud55c\ub2e4\uba74 \uc9c0\uce58\ub294 \uc2dc\uac04\uc774 \uae38\uc5b4\uc9c4\ub2e4. \ud1b5\uc2e0\uc758 \uc18d\ub3c4\ub97c \ub2ec\ub9ac\uae30 \ub2a5\ub825\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uba74 \uac70\uc810\uc5d0 \ub3d9\ubb3c\uc744 \ub9c8\ub828\ud558\uace0 \ub3cc\ubcf4\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc77c\uc744 \ub193\uce58\uac8c \ub41c\ub2e4. \uadf8\ub9ac\uc2a4\uc758 \uc5ed\uc0ac\uac00 \ud5e4\ub85c\ub3c4\ud1a0\uc2a4\ub294 \ud398\ub974\uc2dc\uc544\uc758 \uc804\ub839 \uccb4\uacc4\ub97c \uae30\ub85d\ud588\ub2e4. \uadf8\uc758 \uc124\uba85\uc5d0\uc11c\ub294 \uc815\ud574\uc9c4 \uad6c\uac04\uc758 \uc0ac\ub78c\uacfc \ub9d0\uc774 \uc18c\uc2dd\uc744 \uc774\uc5b4\ubc1b\ub294\ub2e4. \uadf8\ub294 \uc774\ub97c \uadf8\ub9ac\uc2a4\uc778\uc5d0\uac8c \uc775\uc219\ud55c \ud683\ubd88 \ub9b4\ub808\uc774\uc5d0 \ube57\ub300\uc5c8\ub2e4. \ub0af\uc120 \uc870\uc9c1\uc744 \ub3c5\uc790\uc5d0\uac8c \uc124\uba85\ud558\ub824 \ud55c \ube44\uc720\uc600\ub2e4. \uad50\uc7ac\ub294 \uc774 \uae30\ub85d\uc744 \ud1b5\uc2e0\ub9dd\uc758 \uc911\uc694\ud55c \uc99d\uc5b8\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \uad6c\uac04\uc758 \uc2e4\uc81c \uc18d\ub3c4\uc640 \uc778\uc6d0 \ubc30\uce58\uac00 \uc815\ud655\ud788 \uce21\uc815\ub41c \ud604\ub300\uc758 \uc6b4\uc601 \ubcf4\uace0\uc11c\ub294 \uc544\ub2c8\ub2e4. \uacbd\ud0c4\uc744 \ub2f4\uc740 \uc5ed\uc0ac \uc11c\uc220\uacfc \uc2e4\uce21 \ud1b5\uacc4\ub97c \uad6c\ubd84\ud558\uba74\uc11c\ub3c4, \uad50\ub300\ub77c\ub294 \uad6c\uc870\uac00 \ud575\uc2ec\uc774\uc5c8\ub2e4\ub294 \uc810\uc740 \uc77d\uc744 \uc218 \uc788\ub2e4. \ud5e4\ub85c\ub3c4\ud1a0\uc2a4\ub294 \ub208\uacfc \ube44, \ub354\uc704\uc640 \ubc24\uc758 \uc5b4\ub460\ub3c4 \uc804\ub839\ub4e4\uc758 \uc784\ubb34\ub97c \ub9c9\uc9c0 \ubabb\ud55c\ub2e4\ub294 \ucde8\uc9c0\ub85c \uc37c\ub2e4. \uc774\ub7f0 \ubb38\uc7a5\uc740 \uc624\ub298 \uc77d\uc5b4\ub3c4 \uc778\uc0c1\uc801\uc774\ub2e4. \uba3c \uae38\uc5d0\uc11c \ube60\ub978 \ud1b5\uc2e0\uc744 \uc720\uc9c0\ud558\ub294 \uc77c\uc774 \ub2f9\uc2dc \uc0ac\ub78c\uc5d0\uac8c \uc5bc\ub9c8\ub098 \ub180\ub77c\uc6b4 \ub2a5\ub825\uc73c\ub85c \ubcf4\uc600\ub294\uc9c0 \ub290\ub07c\uac8c \ud55c\ub2e4. \ub2e4\ub9cc \uc774 \ucc2c\uc0ac\ub97c \ud55c \ubc88\ub3c4 \uc9c0\uc5f0\ub418\uc9c0 \uc54a\uc558\ub2e4\ub294 \ubcf4\uc99d\uc73c\ub85c \ubc1b\uc544\ub4e4\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uad50\ud1b5\uc758 \uc2e4\uc81c \uc870\uac74\uacfc \uc5ed\uc0ac \ubb38\uc7a5\uc758 \ud45c\ud604\uc740 \ub2e4\ub974\ub2e4. \uc6b0\ub9ac\uac00 \uc8fc\ubaa9\ud560 \uac83\uc740 \ub098\uc05c \ub0a0\uc528 \uc18d\uc5d0\uc11c\ub3c4 \uc774\ub3d9\uc744 \uc774\uc5b4 \uac00\ub824 \ud55c \uc870\uc9c1\uacfc \uadf8 \uc870\uc9c1\uc744 \uac00\ub2a5\ud558\uac8c \ud55c \uc900\ube44\ub2e4. \uad50\uc7ac\ub294 \uc911\uc694\ud55c \uc9c0\uc810\uacfc \ucde8\uc57d\ud55c \uad6c\uac04\uc5d0 \ubcd1\ub825\uc774 \ubc30\uce58\ub418\uc5b4 \ub3c4\ub85c\uc758 \uc548\uc804\uc744 \uc9c0\ucf30\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc5ed\ucc38\uc774 \uc788\uc5b4\ub3c4 \ub3c4\uc911\uc5d0 \ud1b5\ud589\uc774 \ub04a\uae30\uba74 \uc18c\uc2dd\uc740 \uc804\ub2ec\ub418\uae30 \uc5b4\ub835\ub2e4. \ub3c4\ub85c\ub9dd\uc740 \uc81c\uad6d\uc758 \ud589\uc815\uacfc \uad70\uc0ac\ub825\uc774 \uac19\uc740 \uc7a5\uc18c\uc5d0\uc11c \ub9cc\ub098\ub294 \uc2dc\uc124\uc774\uc5c8\ub2e4. \ub530\ub77c\uc11c \uc774 \uae38\uc744 \uc624\ub298\uc758 \ub204\uad6c\ub098 \uc774\uc6a9\ud558\ub294 \uc6b0\ud3b8 \uc11c\ube44\uc2a4\uc640 \uc644\uc804\ud788 \uac19\uc740 \uac83\uc73c\ub85c \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uc655\uc758 \uba85\ub839\uacfc \ud1b5\uce58\uc758 \ud544\uc694\uac00 \uc911\uc2ec\uc774\uc5c8\ub2e4. \ube60\ub974\uac8c \uc815\ubcf4\ub97c \uc62e\uae30\ub294 \ub2a5\ub825\uc740 \ud3b8\ub9ac\ud55c \uae30\uc220\uc774\uba74\uc11c \uba40\ub9ac \uc788\ub294 \uc9c0\uc5ed\uc744 \uad00\ub9ac\ud558\uace0 \ud1b5\uc81c\ud558\ub294 \ud798\uc774\uae30\ub3c4 \ud588\ub2e4. \uac70\ub300\ud55c \uc655\uad81\uc740 \ub208\uc5d0 \ub744\uc9c0\ub9cc \uadf8\uac83\uc744 \ub458\ub7ec\uc2fc \ubb38\uc11c\uc758 \uc774\ub3d9\uc740 \uc720\uc801 \uc0ac\uc9c4\uc5d0\uc11c \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ud1b5\uce58\uc790\ub294 \uc5ec\ub7ec \uc9c0\uc5ed\uc758 \uc790\uc6d0\uacfc \uc0c1\ud0dc\ub97c \uc54c\uc544\uc57c \ud588\uace0 \uc9c0\uc5ed\uc758 \ucc45\uc784\uc790\ub294 \uc911\uc559\uacfc \uad00\uacc4\ub97c \uc720\uc9c0\ud574\uc57c \ud588\ub2e4. \uc791\uc740 \ud3b8\uc9c0\uc758 \uc774\ub3d9\uc774 \ud070 \uac74\ubb3c\uc758 \uad8c\ub825\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub358 \uc148\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc804\ub839\uacfc \uc0c8 \ub9d0\uc744 \uc900\ube44\ud558\ub294 \uc0ac\ub78c\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc0c1\uc0c1 \uc18d \uc5ed\ucc38 \uc7a5\uba74\uc774\ub2e4. \ud2b9\uc815 \uc720\uc801\uc758 \ubcf5\uc6d0\uc774\ub098 \ub2f9\uc2dc \ub9d0\uc758 \uc7a5\ube44\ub97c \uc815\ud655\ud788 \uc7ac\ud604\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uae00\uc5d0\uc11c\ub294 \uc5ed\uc0ac \uae30\ub85d\uc758 \uad6c\uc870\ub97c \uc77d\uace0 \uadf8\ub9bc\uc5d0\uc11c\ub294 \uc774\ub3d9\uc744 \ub4b7\ubc1b\uce68\ud55c \uc900\ube44\ub97c \uc0dd\uac01\ud558\uba74 \ub41c\ub2e4. \ud398\ub974\uc2dc\uc544\uc758 \uc804\ub839\uc744 \uae30\uc5b5\ud560 \ub54c\ub294 \ub2ec\ub9ac\ub294 \ub9d0 \uc606\uc5d0 \uba48\ucd94\uc5b4 \uae30\ub2e4\ub9ac\ub294 \ub9d0\ub3c4 \ub193\uc544 \ubcf4\uc790. \ub2e4\uc74c \uad6c\uac04\uc758 \uae38\uacfc \ubb3c, \ub3d9\ubb3c\uc744 \ub3cc\ubcf4\ub294 \uc0ac\ub78c\uacfc \uc548\uc804\uc744 \uc9c0\ud0a4\ub294 \uc0ac\ub78c\uc774 \uc788\uc5c8\ub2e4. \ube60\ub978 \ud1b5\uc2e0\uc740 \uadf8 \ub9ce\uc740 \uc77c\uc774 \uc81c\ub54c \uc774\uc5b4\uc9c4 \uacb0\uacfc\uc600\ub2e4. \uc774\ub7f0 \uc2dc\uc120\uc73c\ub85c \ubcf4\uba74 \uc5ed\uc0ac\ub294 \uc774\ub984\ub09c \uc655\uc758 \uba85\ub839\ub9cc\uc73c\ub85c \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294\ub2e4. \uadf8 \uba85\ub839\uc744 \uc2e4\uc81c\ub85c \uc62e\uae30\ub294 \uc870\uc9c1\uc774 \ud544\uc694\ud558\ub2e4. \ud398\ub974\uc2dc\uc544\uc758 \ub3c4\ub85c\ub294 \ud070 \uc81c\uad6d\uc774 \uc791\uc740 \ud3b8\uc9c0\uc758 \uc774\ub3d9\uc744 \uc5b4\ub5bb\uac8c \ub2e4\ub8e8\uc5c8\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\uba70, \uc18d\ub3c4\uc758 \uc5ed\uc0ac\uc5d0\uc11c \uc900\ube44\uc640 \uad50\ub300\uc758 \uac00\uce58\ub97c \ub2e4\uc2dc \ubcf4\uac8c \ud55c\ub2e4."}, {"id": "petra-siq-facade-and-local-knowledge", "title": "\ud398\ud2b8\ub77c \u2014 \uc881\uc740 \ud611\uace1 \ub05d\uc758 \ub3c4\uc2dc\ub294 \ub204\uac00 \uc54c\uace0 \uc788\uc5c8\uc744\uae4c", "summary": "\ud611\uace1\uacfc \uc554\ubcbd \uc815\uba74, 1812\ub144 \uc5ec\ud589\uc790\uc758 \uc548\ub0b4\uc790\uc640 \uc9c0\uc5ed \uc9c0\uc2dd\uc744 \ub530\ub77c \ubc1c\uacac\uc774\ub77c\ub294 \ub9d0\uc744 \ub2e4\uc2dc \ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/petra-siq-facade-and-local-knowledge/index.html", "image": "../media/petra-siq-facade-and-local-knowledge.png", "alt": "\ud611\uace1 \uc0ac\uc774\uc5d0 \ub098\ud0c0\ub098\ub294 \ud398\ud2b8\ub77c\uc758 \uc554\ubcbd \uc815\uba74\uc744 \uc5f0\uc0c1\ud558\ub294 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ud398\ud2b8\ub77c \u2014 \uc881\uc740 \ud611\uace1 \ub05d\uc758 \ub3c4\uc2dc\ub294 \ub204\uac00 \uc54c\uace0 \uc788\uc5c8\uc744\uae4c \uc720\uc801\uc758 \ubaa8\uc2b5\uacfc \uc9c0\uc5ed \uc9c0\uc2dd, \uc678\ubd80 \uc5ec\ud589\uc790\uc758 \uae30\ub85d\uc744 \ud568\uaed8 \uc77d\uae30 \ud611\uace1\uacfc \uc554\ubcbd \uc815\uba74, 1812\ub144 \uc5ec\ud589\uc790\uc758 \uc548\ub0b4\uc790\uc640 \uc9c0\uc5ed \uc9c0\uc2dd\uc744 \ub530\ub77c \ubc1c\uacac\uc774\ub77c\ub294 \ub9d0\uc744 \ub2e4\uc2dc \ubd05\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc881\uc740 \ubc14\uc704 \uc0ac\uc774\ub97c \uc9c0\ub098\uba74 \ud070 \uac74\ucd95\uc758 \uc815\uba74\uc774 \uac11\uc790\uae30 \ub098\ud0c0\ub09c\ub2e4. \ud398\ud2b8\ub77c\uc758 \uc778\uc0c1\uc801\uc778 \uc7a5\uba74\uc740 \uc885\uc885 \uc783\uc5b4\ubc84\ub9b0 \ub3c4\uc2dc\ub97c \uc678\ubd80\uc778\uc774 \ubc1c\uacac\ud588\ub2e4\ub294 \uc774\uc57c\uae30\uc640 \ud568\uaed8 \uc18c\uac1c\ub41c\ub2e4. \uadf8\ub7ec\ub098 1812\ub144 \uc774\uacf3\uc744 \ucc3e\uc740 \ubd80\ub974\ud06c\ud558\ub974\ud2b8\uc758 \uae30\ub85d\uc744 \uc77d\uc73c\uba74, \uc720\uc801\uc744 \uc54c\uace0 \uc788\ub358 \uc8fc\ubbfc\uacfc \uc548\ub0b4\uc790\uc758 \uc874\uc7ac\uac00 \uba3c\uc800 \ubcf4\uc778\ub2e4. \ud398\ud2b8\ub77c\ub294 \uc624\ub298\ub0a0 \uc694\ub974\ub2e8\uc5d0 \uc788\ub294 \uace0\ub300 \ub3c4\uc2dc \uc720\uc801\uc774\ub2e4. \ubc14\uc704\uc5d0 \uc0c8\uae34 \ud070 \uc815\uba74\uc774 \uc720\uba85\ud558\uc9c0\ub9cc \ub3c4\uc2dc \uc804\uccb4\uac00 \ud55c \uac74\ubb3c\uc740 \uc544\ub2c8\ub2e4. \ud611\uace1\uacfc \ud1b5\ub85c, \ubb34\ub364\uacfc \uc5ec\ub7ec \uc2dc\uc124\uc774 \ud568\uaed8 \uc874\uc7ac\ud55c\ub2e4. \uac00\uc7a5 \uc720\uba85\ud55c \uc0ac\uc9c4 \ud55c \uc7a5\uc744 \ub3c4\uc2dc \uc804\uccb4\uc758 \ubaa8\uc2b5\uc73c\ub85c \uc0dd\uac01\ud558\uba74 \uacf5\uac04\uc758 \ub113\uc774\ub97c \ub193\uce5c\ub2e4. \uc785\uad6c\ub85c \uc774\uc5b4\uc9c0\ub294 \uc881\uc740 \uae38\uc740 \uad00\uac1d\uc758 \uc2dc\uc57c\ub97c \uc81c\ud55c\ud55c\ub2e4. \uba3c \uac74\ubb3c\uc774 \ucc98\uc74c\ubd80\ud130 \uc804\ubd80 \ubcf4\uc774\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc5d0 \uc870\uae08\uc529 \ub4dc\ub7ec\ub098\ub294 \ubd80\ubd84\uc758 \uc778\uc0c1\uc774 \uac15\ud574\uc9c4\ub2e4. \uc6c5\uc7a5\ud568\uc740 \uac74\ucd95 \uc790\uccb4\uc758 \ud06c\uae30\ubfd0 \uc544\ub2c8\ub77c \uadf8\uacf3\uc5d0 \uc774\ub974\ub294 \uc811\uadfc \ubc29\uc2dd\uc5d0\uc11c\ub3c4 \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4. \uc11d\uc7ac\ub97c \ub2e4\ub978 \uacf3\uc5d0\uc11c \uac00\uc838\ub2e4 \uc313\ub294 \uac74\ubb3c\uacfc \ubc14\uc704\ub97c \uae4e\uc544 \uc815\uba74\uc744 \ub9cc\ub4dc\ub294 \uc791\uc5c5\uc740 \ub2e4\ub974\ub2e4. \uae30\ub465\uacfc \uce35\ucc98\ub7fc \ubcf4\uc774\ub294 \ud615\ud0dc\uac00 \uc554\ubcbd\uc5d0\uc11c \ub4dc\ub7ec\ub09c\ub2e4. \uac74\ucd95\uc758 \uc5b8\uc5b4\uac00 \ubc14\uc704\uc758 \ud45c\uba74\uc5d0 \uc62e\uaca8\uc9c4 \uac83\uc774\ub2e4. \uc678\uad00\uc744 \ubcf4\uba74 \uad6c\uc870\ub97c \uc138\uc6b0\ub294 \uc77c\uacfc \ud45c\uba74\uc744 \uc870\uac01\ud558\ub294 \uc77c\uc774 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \uac89\uc758 \ud654\ub824\ud568\uacfc \uc548\ucabd \uacf5\uac04\uc758 \ud06c\uae30\ub098 \uad6c\uc131\uc740 \uac19\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uc815\uba74\uc774 \ud06c\ub2e4\uace0 \ub4a4\uc5d0 \uc0ac\uc9c4\uc5d0\uc11c \uc0c1\uc0c1\ud55c \uad81\uc804 \uc804\uccb4\uac00 \uc228\uc5b4 \uc788\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ubc14\uae65\uc5d0\uc11c \ubcf4\ub294 \uae30\ub150\uc131, \uc548\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \uacf5\uac04\uc758 \uae30\ub2a5\uc744 \ub098\ub204\uc5b4 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ubd80\ub974\ud06c\ud558\ub974\ud2b8\uc758 \ucc45\uc5d0 \ubd99\uc740 \uc124\uba85\uc740 \ud398\ud2b8\ub77c\ub97c \uc544\ub77c\ube44\uc544\uc640 \uc9c0\uc911\ud574 \uc0ac\uc774\uc758 \uad50\uc5ed\uacfc \uc5f0\uacb0\ud55c\ub2e4. \uc678\ub534 \uc0ac\ub9c9\uc758 \uae30\ubb18\ud55c \uc7a5\uc2dd\uc73c\ub85c\ub9cc \ubcf4\uc774\ub358 \uc720\uc801\uc774 \uc0ac\ub78c\uacfc \ubb3c\uac74\uc774 \uc774\ub3d9\ud558\ub358 \uae38\uc758 \uac70\uc810\uc73c\ub85c \ubc14\ub010\ub2e4. \ub3c4\uc2dc\uac00 \ubc88\uc131\ud558\ub824\uba74 \ub204\uad70\uac00 \uc624\uace0 \uba38\ubb3c\uace0 \ub2e4\uc2dc \ub5a0\ub098\uc57c \ud588\ub2e4. \ub0af\uc120 \uac74\ucd95 \uc694\uc18c\ub4e4\uc774 \ud568\uaed8 \ubcf4\uc774\ub294 \uac83\ub3c4 \uace0\ub9bd\ub41c \uc7a5\uc18c\ub77c\ub294 \uc774\ubbf8\uc9c0\uc640\ub294 \uc5b4\uc6b8\ub9ac\uc9c0 \uc54a\ub294\ub2e4. \ud2b9\uc815 \ubb38\ud654\uc758 \ud615\ud0dc\ub97c \uc54c\uc544\ubcf4\ub294 \uc77c\uacfc \ub3c4\uc2dc\uac00 \ub2e4\ub978 \uc138\uacc4\uc640 \ub9fa\uc740 \uad00\uacc4\ub97c \uc0dd\uac01\ud558\ub294 \uc77c\uc774 \ud568\uaed8 \uac00\ub2a5\ud558\ub2e4. \ubc14\uc704\uc758 \uc0c9\uc5d0 \uac10\ud0c4\ud55c \ub4a4 \uae38\uc774 \uc5b4\ub514\ub85c \uc774\uc5b4\uc84c\ub294\uc9c0 \ubb3c\uc744 \uc218 \uc788\ub2e4. 1812\ub144\uc758 \uc5ec\ud589 \uae30\ub85d\uc5d0\ub294 \uc640\ub514 \ubb34\uc0ac \uc8fc\ubcc0\uc758 \uc0d8\uacfc \ubb3c\uae38, \uad00\uac1c\ud558\ub294 \ubc2d\uacfc \ub9c8\uc744\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \uace0\ub300 \uc720\uc801 \uc8fc\ubcc0\uc740 \uc0ac\ub78c\uc774 \uc5c6\ub294 \ube48 \ubb34\ub300\uac00 \uc544\ub2c8\uc5c8\ub2e4. \ubb3c\uc744 \uc774\uc6a9\ud558\uace0 \uc791\ubb3c\uc744 \uae30\ub974\ub294 \uc0dd\ud65c\uc774 \uc774\uc5b4\uc9c0\uace0 \uc788\uc5c8\ub2e4. \ud48d\uacbd\uc758 \uac74\uc870\ud568\ub9cc\uc73c\ub85c \uc0ac\ub78c\uc758 \ubd80\uc7ac\ub97c \ucd94\uc815\ud560 \uc218 \uc5c6\ub2e4. \uc774 \uae30\ub85d\ub9cc\uc73c\ub85c \uace0\ub300\uc758 \ubaa8\ub4e0 \uc218\ub9ac \uc2dc\uc124\uc744 \ubcf5\uc6d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uadf8\ub7ec\ub098 \uc0ac\ub78c\ub4e4\uc774 \ubb3c\uc758 \uc704\uce58\ub97c \uc54c\uace0 \uad00\ub9ac\ud558\ub294 \uc9c0\uc2dd\uc774 \ud544\uc694\ud588\ub2e4\ub294 \uc810\uc740 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ud070 \uc815\uba74\uc758 \uc870\uac01\ub9cc\ud07c \ubb3c\uacfc \uae38\uc758 \uc870\uac74\uc774 \uc0ac\ub78c\uc774 \uc774\uacf3\uc5d0 \uc0b4 \uc218 \uc788\ub294\uac00\uc5d0 \uc911\uc694\ud588\ub2e4. \ubd80\ub974\ud06c\ud558\ub974\ud2b8\ub294 \uc9c0\uc5ed\uc5d0\uc11c \ub4e4\uc740 \uc720\uc801\uc758 \uc18c\ubb38\uc744 \ub530\ub77c \ubc29\ubb38\ud558\ub824 \ud588\ub2e4. \uadf8\uac00 \uae38\uc744 \ucc3e\ub294 \ub370\uc5d0\ub294 \uc548\ub0b4\uc790\uc640 \ud604\uc9c0\uc758 \uc9c0\uc2dd\uc774 \ud544\uc694\ud588\ub2e4. \uc678\ubd80\uc778\uc774 \ubc29\ubb38 \uc0ac\uc2e4\uc744 \uae00\ub85c \ub0a8\uacbc\ub2e4\ub294 \uc774\uc720\ub85c \uadf8\uc804\uc5d0\ub294 \uc544\ubb34\ub3c4 \uc7a5\uc18c\ub97c \uc54c\uc9c0 \ubabb\ud588\ub2e4\uace0 \ub9d0\ud560 \uc218 \uc5c6\ub294 \uac83\uc774\ub2e4. \uadf8\ub294 \uc544\ub860\uc758 \ubb34\ub364\uc5d0\uc11c \uc81c\ubb3c\uc744 \ubc14\uce58\uaca0\ub2e4\ub294 \ub73b\uc744 \ub0b4\uc138\uc6cc \uc720\uc801 \ucabd\uc73c\ub85c \uac00\ub824 \ud588\ub2e4\uace0 \uae30\ub85d\ud55c\ub2e4. \uc5ec\ud589\uc790\uc758 \ud638\uae30\uc2ec\uacfc \uc8fc\ubbfc\uc774 \ub0af\uc120 \ubc29\ubb38\uac1d\uc744 \ubc1b\uc544\ub4e4\uc774\ub294 \uc870\uac74 \uc0ac\uc774\uc5d0\ub294 \uae34\uc7a5\uc774 \uc788\uc5c8\ub2e4. \uae30\ub85d\uc744 \uc77d\uc744 \ub54c\uc5d0\ub294 \ubaa8\ud5d8\ub2f4\uc758 \uc7ac\uce58\ub9cc\ud07c \uc815\ubcf4\ub97c \uac10\ucd94\uace0 \uc774\ub3d9\ud55c \uc0c1\ud669\ub3c4 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ubc29\ubb38\uc790\ub294 \uc790\uae30\uac00 \uc5b4\ub514\uc5d0 \uac00\ub824\ub294\uc9c0 \ub2e4 \ubc1d\ud788\uc9c0 \uc54a\uace0 \uae38\uc744 \uc5bb\ub294\ub2e4. \ubc18\uba74 \uc548\ub0b4\uc790\ub294 \uadf8\uac00 \uc65c \uadf8\ub7f0 \uacf3\uc744 \ubcf4\ub824\ub294\uc9c0 \uc758\uc2ec\ud560 \uc218 \uc788\ub2e4. \uac19\uc740 \uc5ec\uc815\uc774 \ud55c \uc0ac\ub78c\uc5d0\uac8c\ub294 \ud0d0\uad6c\uc774\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ub0af\uc120 \ud589\ub3d9\uc774\uc5c8\ub358 \uac83\uc774\ub2e4. \uc5ec\ud589\uae30\uc758 \uc8fc\uc778\uacf5\uacfc \ub3d9\ud589\uc790\uc758 \uacbd\ud5d8\uc774 \uac19\uc9c0 \uc54a\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ud604\uc9c0\uc778\uc774 \uc54c\ub824 \uc900 \uae38\uacfc \uc9c0\uba85\uc774 \uae30\ub85d\uc790\uc758 \uae00 \uc18d\uc5d0 \ub4e4\uc5b4\uac08 \ub54c, \uadf8 \uc9c0\uc2dd\uc740 \uc0c8 \ucd9c\ud310\ubb3c\uc758 \uad8c\uc704\ub97c \uc5bb\ub294\ub2e4. \ud558\uc9c0\ub9cc \ucc45 \ud45c\uc9c0\uc5d0 \uc774\ub984\uc774 \uc2e4\ub9ac\uc9c0 \uc54a\uc740 \uc0ac\ub78c\uc758 \uae30\uc5ec\ub294 \ud750\ub824\uc9c8 \uc218 \uc788\ub2e4. \ubc1c\uacac\uc774\ub77c\ub294 \ub2e8\uc5b4\ub97c \uc4f8 \ub54c \ub204\uad6c\uc758 \uc77c\uc744 \ud3ec\ud568\ud558\ub294\uc9c0 \uc0b4\ud3b4\uc57c \ud558\ub294 \uc774\uc720\uac00 \uc5ec\uae30\uc5d0 \uc788\ub2e4. \uc720\uba85\ud55c \uc815\uba74\uc5d0 \ubd99\uc740 \ubcf4\ubb3c \ucc3d\uace0\ub77c\ub294 \ud1b5\uce6d\uc740 \uc7a5\uc18c\uc5d0 \uad00\ud55c \uc0c1\uc0c1\uc744 \uac15\ud558\uac8c \ub9cc\ub4e0\ub2e4. \uadf8\ub7ec\ub098 \ub110\ub9ac \ubd88\ub9ac\ub294 \uc774\ub984\uc774 \uace7 \uc6d0\ub798 \uac74\ubb3c\uc758 \uc6a9\ub3c4\ub97c \ud655\uc815\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc804\ud574\uc9c0\ub294 \uc774\uc57c\uae30\uc640 \uac74\ucd95\uc758 \uc5ed\uc0ac\uc801 \uae30\ub2a5\uc740 \uc11c\ub85c \ub2e4\ub978 \uc885\ub958\uc758 \uc815\ubcf4\ub2e4. \uc61b \uc5ec\ud589\uc790\uc758 \ubb38\uc7a5\uc5d0\ub3c4 \ucd94\uce21\uacfc \uad00\ucc30\uc774 \uc11e\uc5ec \uc788\ub2e4. \ub208\uc73c\ub85c \ubcf8 \ubcbd\uacfc \ubc29\uc758 \ubb18\uc0ac, \uadf8\uac83\uc774 \ubb34\uc5c7\uc774\uc5c8\uc744 \uac83\uc774\ub77c\ub294 \uc124\uba85\uc744 \uad6c\ubcc4\ud558\uba74 \uc790\ub8cc\ub97c \ub354 \uc815\ud655\ud788 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4. \uc624\ub798\ub41c \uae30\ub85d\uc740 \ubaa8\ub4e0 \ub2f5\uc744 \uc8fc\ub294 \uc548\ub0b4\uc11c\ubcf4\ub2e4 \uc9c8\ubb38\uc744 \uad6c\uccb4\uc801\uc73c\ub85c \ub9cc\ub4dc\ub294 \ucd9c\ubc1c\uc810\uc774\ub2e4. \ud398\ud2b8\ub77c\ub294 \uc5b4\ub290 \ub0a0 \uac11\uc790\uae30 \uc874\uc7ac\ud558\uac8c \ub41c \ub3c4\uc2dc\uac00 \uc544\ub2c8\ub2e4. \uc720\uc801\uc744 \uc54c\ub358 \uc8fc\ubbfc\uacfc \uae38\uc744 \uc548\ub0b4\ud55c \uc0ac\ub78c, \uc774\uc804\uc5d0 \uc0b4\uace0 \uc77c\ud588\ub358 \uc0ac\ub78c\ub4e4\uc758 \uc2dc\uac04\uc774 \uc788\ub2e4. \ub098\uc911\uc5d0 \uc720\ub7fd\uc5d0 \ub110\ub9ac \uc54c\ub824\uc9c4 \uacfc\uc815\uc740 \uadf8 \uae34 \uc5ed\uc0ac \uc911 \ud558\ub098\uc758 \ub2e8\uacc4\ub2e4. \uc881\uc740 \ud611\uace1 \ub05d\uc758 \uc815\uba74\uc744 \ub2e4\uc2dc \ubcfc \ub54c\uc5d0\ub294 \uac74\ucd95\uc774 \ubaa8\uc2b5\uc744 \ub4dc\ub7ec\ub0b4\ub294 \ub180\ub77c\uc6c0\uacfc \uadf8\uac83\uc744 \ubc1c\uacac\ud588\ub2e4\uace0 \ub9d0\ud558\ub294 \uc774\uc57c\uae30\uc758 \uad6c\uc870\ub97c \ud568\uaed8 \uc0dd\uac01\ud574 \ubcf4\uc790. \ub204\uac00 \uc54c\uace0 \ub204\uac00 \uc774\ub984\uc744 \ubd99\uc774\uba70 \ub204\uac00 \uae30\ub85d\uc744 \ub0a8\uae30\ub294\uc9c0\uc5d0 \ub530\ub77c \uac19\uc740 \uc7a5\uc18c\uc758 \uc5ed\uc0ac\uac00 \ub2ec\ub77c \ubcf4\uc77c \uc218 \uc788\ub2e4. \uc720\uc801\uc758 \uc544\ub984\ub2e4\uc6c0\uacfc \uadf8 \uc7a5\uc18c\uc5d0 \uad00\ud55c \uc9c0\uc2dd\uc774 \uc804\ud574\uc9c0\ub294 \uacbd\ub85c\ub294 \ud568\uaed8 \uc0b4\ud544 \uc218 \uc788\ub2e4. \uadf8 \uc9c8\ubb38\uc740 \ud48d\uacbd\uc758 \uac10\ub3d9\uc744 \uc904\uc774\uc9c0 \uc54a\uace0 \ub354 \uae4a\uac8c \ub9cc\ub4e0\ub2e4."}, {"id": "pliny-vesuvius-pine-cloud-two-letters", "title": "\ubca0\uc218\ube44\uc624\uac00 \uc5b4\ub450\uc6cc\uc9c4 \ub0a0 \u2014 \ud50c\ub9ac\ub2c8\uc6b0\uc2a4\uc758 \ub450 \ud3b8\uc9c0", "summary": "\uc18c\ub098\ubb34 \ubaa8\uc591\uc758 \uad6c\ub984\uacfc \ud55c\ub0ae\uc758 \uc5b4\ub460, \uc9c1\uc811 \ubcf8 \uc77c\uacfc \uc804\ud574 \ub4e4\uc740 \uc77c\uc744 \uad6c\ubd84\ud55c \uace0\ub300\uc758 \ud3b8\uc9c0\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/pliny-vesuvius-pine-cloud-two-letters/index.html", "image": "../media/pliny-vesuvius-pine-cloud-two-letters.png", "alt": "\ub098\ud3f4\ub9ac\ub9cc \ub108\uba38 \ubca0\uc218\ube44\uc624\uc758 \uc18c\ub098\ubb34 \ubaa8\uc591 \ubd84\ud654 \uad6c\ub984\uc744 \ubc14\ub77c\ubcf4\ub294 \ub450 \uad00\ucc30\uc790\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ubca0\uc218\ube44\uc624\uac00 \uc5b4\ub450\uc6cc\uc9c4 \ub0a0 \u2014 \ud50c\ub9ac\ub2c8\uc6b0\uc2a4\uc758 \ub450 \ud3b8\uc9c0 \uad6c\uc870\ud558\ub7ec \ub5a0\ub09c \uc0bc\ucd0c\uacfc \ucc45\uc744 \ub193\uc9c0 \uc54a\ub358 \uc870\uce74\uc758 \uc11c\ub85c \ub2e4\ub978 \uae30\ub85d \uc18c\ub098\ubb34 \ubaa8\uc591\uc758 \uad6c\ub984\uacfc \ud55c\ub0ae\uc758 \uc5b4\ub460, \uc9c1\uc811 \ubcf8 \uc77c\uacfc \uc804\ud574 \ub4e4\uc740 \uc77c\uc744 \uad6c\ubd84\ud55c \uace0\ub300\uc758 \ud3b8\uc9c0\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc0b0 \uc704\uc5d0 \uc19f\uc740 \uad6c\ub984\uc740 \uc18c\ub098\ubb34\ucc98\ub7fc \ubcf4\uc600\ub2e4. \uc544\ub798\uc5d0\uc11c\ub294 \uae30\ub2e4\ub780 \uc904\uae30\uac00 \uc62c\ub77c\uac00\uace0 \ub192\uc740 \uacf3\uc5d0\uc11c\ub294 \uac00\uc9c0\ucc98\ub7fc \ud37c\uc84c\ub2e4. \uc11c\uae30 79\ub144 \ubca0\uc218\ube44\uc624 \ubd84\ud654\ub97c \ubb18\uc0ac\ud55c \uc18c \ud50c\ub9ac\ub2c8\uc6b0\uc2a4\uc758 \ud3b8\uc9c0\ub294 \uac70\ub300\ud55c \uc7ac\ub09c\uc744 \uc774\ub7f0 \uad6c\uccb4\uc801\uc778 \ubaa8\uc591\uc73c\ub85c \uae30\uc5b5\ud558\uac8c \ud55c\ub2e4. \uadf8\uc758 \ub450 \ud3b8\uc9c0\uc5d0\ub294 \uc0bc\ucd0c\uc778 \ub300 \ud50c\ub9ac\ub2c8\uc6b0\uc2a4\uc758 \ub9c8\uc9c0\ub9c9 \ud56d\ud574\uc640 \uc790\uc2e0\uc774 \uc5b4\uba38\ub2c8\uc640 \ud568\uaed8 \uacaa\uc740 \ud53c\ub09c\uc774 \ub2f4\uaca8 \uc788\ub2e4. \ub450 \uc0ac\ub78c\uc774 \uac19\uc740 \uc7a5\uba74\uc744 \ud568\uaed8 \ubcf8 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8 \ucc28\uc774\ub97c \uae30\uc5b5\ud558\uba70 \uc77d\uc73c\uba74, \uc624\ub798\ub41c \uc7ac\ub09c \uae30\ub85d\uc774 \uc5b4\ub5bb\uac8c \ub9cc\ub4e4\uc5b4\uc84c\ub294\uc9c0\ub3c4 \ud568\uaed8 \ubcf4\uc778\ub2e4. \uc18c \ud50c\ub9ac\ub2c8\uc6b0\uc2a4\ub294 \uc5ed\uc0ac\uac00 \ud0c0\ud0a4\ud22c\uc2a4\uc758 \uc694\uccad\uc744 \ubc1b\uace0 \uc0bc\ucd0c\uc758 \uc8fd\uc74c\uc744 \uc124\uba85\ud55c\ub2e4. \uc0ac\uac74\uc774 \ud55c\ucc3d\uc77c \ub54c \uae09\ud788 \ubcf4\ub0b8 \ubcf4\uace0\uac00 \uc544\ub2c8\ub77c \uc2dc\uac04\uc774 \uc9c0\ub09c \ub4a4 \uae30\uc5b5\uacfc \uc804\ud574 \ub4e4\uc740 \uc0ac\uc815\uc744 \uc815\ub9ac\ud55c \uae00\uc774\ub2e4. \uadf8\ub294 \uc0bc\ucd0c\uc758 \uba85\uc131\uc774 \uc5ed\uc0ac \uc18d\uc5d0 \ub0a8\uae30\ub97c \ubc14\ub77c\ub294 \ub9c8\uc74c\ub3c4 \uc228\uae30\uc9c0 \uc54a\ub294\ub2e4. \uc774 \uc810\uc740 \uae30\ub85d\uc744 \ubc84\ub824\uc57c \ud560 \uc774\uc720\uac00 \uc544\ub2c8\ub77c \uc77d\ub294 \uae30\uc900\uc774 \ub41c\ub2e4. \ud3b8\uc9c0\uc758 \uae00\uc4f4\uc774\uc5d0\uac8c\ub294 \uc120\ud0dd\ud55c \uc0ac\uac74\uacfc \uac15\uc870\ud558\uace0 \uc2f6\uc740 \uc778\ubb3c\uc774 \uc788\ub2e4. \ubb34\uc5c7\uc744 \ubcf4\uc558\ub294\uc9c0\uc640 \uadf8\uac83\uc744 \uc5b4\ub5bb\uac8c \uc774\uc57c\uae30\ud558\uace0 \uc2f6\uc740\uc9c0\ub294 \uc644\uc804\ud788 \uac19\uc740 \ubb38\uc81c\uac00 \uc544\ub2c8\ub2e4. \uc9c1\uc811 \ubaa9\uaca9\uacfc \uc8fc\ubcc0\uc758 \uc99d\uc5b8\uc744 \ub098\ub204\ub824\ub294 \uadf8\uc758 \uc124\uba85\ub3c4 \uadf8\ub798\uc11c \uc911\uc694\ud558\ub2e4. \uc0bc\ucd0c\uc740 \ubbf8\uc138\ub214\uc5d0\uc11c \ud568\ub300\ub97c \uc9c0\ud718\ud558\uace0 \uc788\uc5c8\ub2e4. \ud559\ubb38\uc5d0\ub3c4 \ud070 \uad00\uc2ec\uc774 \uc788\ub358 \uadf8\ub294 \ud2b9\uc774\ud55c \uad6c\ub984\uc744 \ubcf4\uace0 \ub354 \uac00\uae4c\uc774 \uac00 \ubcf4\ub824 \ud55c\ub2e4. \ucc98\uc74c\ubd80\ud130 \uc7ac\ub09c \uad6c\uc870\ub97c \ubaa9\ud45c\ub85c \ucd9c\ubc1c\ud55c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc790\uc5f0 \ud604\uc0c1\uc744 \uc54c\uc544\ubcf4\ub824\ub294 \ud638\uae30\uc2ec\uc774 \uba3c\uc800 \uc6c0\uc9c1\uc778\ub2e4. \uadf8\ub294 \uc870\uce74\uc5d0\uac8c \ub3d9\ud589\ud560 \uc218 \uc788\ub2e4\uace0 \ud558\uc9c0\ub9cc, \uc870\uce74\ub294 \ub0a8\uc544\uc11c \uacf5\ubd80\ud558\uaca0\ub2e4\uace0 \ud55c\ub2e4. \uc774 \uc120\ud0dd \ub54c\ubb38\uc5d0 \ub450 \uc0ac\ub78c\uc758 \uacbd\ud5d8\uc774 \uac08\ub77c\uc9c4\ub2e4. \uc18c \ud50c\ub9ac\ub2c8\uc6b0\uc2a4\ub294 \uc0bc\ucd0c\uc758 \ud56d\ud574 \uc804\uccb4\ub97c \uc790\uae30 \ub208\uc73c\ub85c \ubcf8 \uac83\ucc98\ub7fc \uc4f8 \uc218 \uc5c6\ub2e4. \ub3c5\uc790 \uc5ed\uc2dc \ub4a4\uc5d0 \uc774\uc5b4\uc9c0\ub294 \uc120\uc0c1\uacfc \ud574\uc548\uc758 \uc7a5\uba74\uc774 \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc758 \uc774\uc57c\uae30\ub97c \uac70\uccd0 \uc654\uc74c\uc744 \uae30\uc5b5\ud574\uc57c \ud55c\ub2e4. \ucd9c\ubc1c \ubb34\ub835 \ub3c4\uc6c0\uc744 \uccad\ud558\ub294 \ud3b8\uc9c0\uac00 \ub3c4\ucc29\ud55c\ub2e4. \uc704\ud5d8\uc5d0 \ub193\uc778 \ud574\uc548\uc5d0\uc11c \ubc14\ub2e4\ub97c \ud1b5\ud55c \ud0c8\ucd9c\uc774 \ud544\uc694\ud558\ub2e4\ub294 \uc18c\uc2dd\uc774\ub2e4. \uc0bc\ucd0c\uc758 \uacc4\ud68d\uc740 \ubc14\ub010\ub2e4. \ud604\uc0c1\uc744 \uc0b4\ud53c\ub824\ub358 \ubc30\uac00 \uc0ac\ub78c\ub4e4\uc744 \ub3d5\uae30 \uc704\ud574 \uc704\ud5d8 \ucabd\uc73c\ub85c \ud5a5\ud55c\ub2e4. \ub0a8\ub4e4\uc774 \ubc97\uc5b4\ub098\ub824\ub294 \ubc29\ud5a5\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \ud56d\ud574\ub2e4. \uac00\uae4c\uc6cc\uc9c8\uc218\ub85d \uc7ac\uc640 \ub3cc\uc774 \ubc30 \uc704\ub85c \ub5a8\uc5b4\uc9c4\ub2e4. \ubc14\ub2e4\uc640 \ud574\uc548\uc758 \uc0c1\ud669\ub3c4 \ud56d\ud574\ub97c \uc5b4\ub835\uac8c \ud55c\ub2e4. \uae30\ub85d\uc740 \uadf8\uac00 \uce68\ucc29\ud558\uac8c \uad00\ucc30\uc744 \uacc4\uc18d\ud588\ub2e4\uace0 \uc804\ud55c\ub2e4. \ub3d9\uc2dc\uc5d0 \uc774 \uce68\ucc29\ud568\uc744 \ud6cc\ub96d\ud55c \uc778\ubb3c\uc758 \uc790\uc9c8\ub85c \ubcf4\uc5ec \uc8fc\ub824\ub294 \uc870\uce74\uc758 \uc11c\uc220\uc774\ub77c\ub294 \uc810\ub3c4 \ub193\uce58\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\ub2e4. \uc6a9\uac10\ud588\ub2e4\ub294 \ud3c9\uac00\uc640 \uc2e4\uc81c \uc704\ud5d8\uc758 \uc815\ub3c4\ub294 \ub530\ub85c \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc0bc\ucd0c\uc740 \uc2a4\ud0c0\ube44\uc544\uc774\uc5d0\uc11c \ud3fc\ud3ec\ub2c8\uc544\ub204\uc2a4 \uc77c\ud589\uacfc \ub9cc\ub09c\ub2e4. \ubc14\ub78c\uc740 \uadf8\uac00 \ub3c4\ucc29\ud558\ub294 \ub370\uc5d0\ub294 \uc720\ub9ac\ud588\uc9c0\ub9cc \uadf8\uacf3 \uc0ac\ub78c\ub4e4\uc774 \ubc14\ub2e4\ub85c \ube60\uc838\ub098\uac00\ub824\ub294 \ub370\uc5d0\ub294 \ub3c4\uc6c0\uc774 \ub418\uc9c0 \uc54a\ub294\ub2e4. \uac19\uc740 \uc790\uc5f0\uc870\uac74\uc774 \uc624\ub294 \ubc30\uc640 \ub5a0\ub098\ub824\ub294 \ubc30\uc5d0 \ub2e4\ub978 \uc758\ubbf8\uac00 \ub41c\ub2e4. \ubc30\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ud0c8\ucd9c\uc774 \uac00\ub2a5\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uac74\ubb3c\uc740 \ud754\ub4e4\ub9ac\uace0 \uc7ac\uc640 \ub3cc\uc740 \uc313\uc778\ub2e4. \uc77c\ud589\uc740 \uc2e4\ub0b4\uc5d0 \ub0a8\uc744\uc9c0 \ubc14\uae65\uc73c\ub85c \ub098\uac08\uc9c0 \uace0\ubbfc\ud55c\ub2e4. \ub098\uac00\uba74\uc11c \uba38\ub9ac\uc5d0 \ubca0\uac1c\ub97c \ubb36\uc5b4 \ub099\ud558\ubb3c\uc744 \ub9c9\uc73c\ub824 \ud55c\ub2e4. \uc544\uc8fc \uc791\uace0 \uc77c\uc0c1\uc801\uc778 \ubb3c\uac74\uc774 \uac70\ub300\ud55c \uc704\ud5d8\uc5d0 \ub9de\uc11c\ub294 \ubc29\uc5b4\uad6c\uac00 \ub418\ub294 \ubaa8\uc2b5\uc740 \uc7ac\ub09c\uc758 \ud06c\uae30\ub97c \uc5b4\ub5a4 \uc218\uc2dd\ubcf4\ub2e4 \uac00\uae4c\uc774 \uc804\ud55c\ub2e4. \ud574\uc548\uc5d0\uc11c\ub3c4 \uc0c1\ud669\uc740 \ub098\uc544\uc9c0\uc9c0 \uc54a\uace0 \ub300 \ud50c\ub9ac\ub2c8\uc6b0\uc2a4\ub294 \uacb0\uad6d \uc4f0\ub7ec\uc838 \uc8fd\ub294\ub2e4. \uc870\uce74\ub294 \uacf5\uae30\uc640 \uac74\uac15 \uc0c1\ud0dc\ub97c \ub4e4\uc5b4 \uc6d0\uc778\uc744 \ucd94\uce21\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc774 \uc124\uba85\uc744 \uc624\ub298\uc758 \ud655\uc815\ub41c \uc758\ud559 \uc9c4\ub2e8\uc73c\ub85c \uc62e\uae38 \uc218\ub294 \uc5c6\ub2e4. \ud3b8\uc9c0\uac00 \ubd84\uba85\ud788 \uc804\ud558\ub294 \uac83\uc740 \uc0dd\ud658\ud558\uc9c0 \ubabb\ud588\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ub9c8\uc9c0\ub9c9 \uc21c\uac04\uc5d0 \uad00\ud55c \uc99d\uc5b8\uc774\ub2e4. \ubd84\ud654\uc758 \ub0a0\uc9dc \uc5ed\uc2dc \uc624\ub798\ub41c \ubc88\uc5ed\ubcf8\uc5d0 \uc801\ud78c \ud55c \ub0a0\uc9dc\ub9cc\uc73c\ub85c \ub17c\uc7c1\uc744 \ub05d\ub0bc \uc218 \uc788\ub294 \uc8fc\uc81c\ub294 \uc544\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \uc11c\uae30 79\ub144\uc774\ub77c\ub294 \uc5f0\ub300\uc640 \ud3b8\uc9c0 \uc18d \uacbd\ud5d8\uc5d0 \uc9d1\uc911\ud55c\ub2e4. \uc798 \uc54c\ub824\uc9c4 \uc22b\uc790\ub97c \ubc18\ubcf5\ud558\ub294 \uc77c\ubcf4\ub2e4 \uc790\ub8cc\uac00 \uc5b4\ub514\uae4c\uc9c0 \ub9d0\ud558\ub294\uc9c0 \ubc1d\ud788\ub294 \uc77c\uc774 \uc774 \uae30\ub85d\uc744 \ub354 \ubbff\uc744 \ub9cc\ud558\uac8c \uc77d\uac8c \ud55c\ub2e4. \ub450 \ubc88\uc9f8 \ud3b8\uc9c0\uc5d0\uc11c \uc18c \ud50c\ub9ac\ub2c8\uc6b0\uc2a4\ub294 \uc790\uc2e0\uc758 \uacbd\ud5d8\uc744 \uc774\uc5b4 \uac04\ub2e4. \ub545\uc774 \ud754\ub4e4\ub9ac\uace0 \uc5b4\uba38\ub2c8\uac00 \ucc3e\uc544\uc624\ub294 \ub3d9\uc548\uc5d0\ub3c4 \uadf8\ub294 \uc5ed\uc0ac\ucc45\uc744 \uc77d\uace0 \ubc1c\ucdcc\ud558\uace0 \uc788\uc5c8\ub2e4\uace0 \uc4f4\ub2e4. \uc790\uc2e0\ub3c4 \uadf8\uac83\uc774 \uc6a9\uae30\uc600\ub294\uc9c0 \uc5b4\ub9ac\uc11d\uc74c\uc774\uc5c8\ub294\uc9c0 \ud310\ub2e8\ud558\uae30 \uc5b4\ub835\ub2e4\ub294 \uc2dd\uc73c\ub85c \ub3cc\uc544\ubcf8\ub2e4. \uacf5\ubd80\uc5d0 \uce68\ucc29\ud588\ub358 \uc601\uc6c5\uc73c\ub85c\ub9cc \ud3ec\uc7a5\ud558\uc9c0 \uc54a\ub294 \ub300\ubaa9\uc774\ub2e4. \uc8fc\ubcc0\uc758 \uc5b4\ub978\uc740 \uadf8\ub7f0 \ud0dc\ub3c4\ub97c \uafb8\uc9d6\uace0 \ub5a0\ub0a0 \uac83\uc744 \uc7ac\ucd09\ud55c\ub2e4. \uc775\uc219\ud55c \uc791\uc740 \ud754\ub4e4\ub9bc\uc744 \uacc4\uc18d \uac19\uc740 \uc77c\ub85c \ubc1b\uc544\ub4e4\uc774\ub2e4\uac00 \uc0c1\ud669\uc774 \ub2ec\ub77c\uc84c\uc74c\uc744 \uae68\ub2eb\ub294 \uacfc\uc815\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \ud6c4\ub300\uc758 \ub3c5\uc790\uac00 \uacb0\uacfc\ub97c \uc548\ub2e4\uace0 \ud574\uc11c \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\ub3c4 \ucc98\uc74c\ubd80\ud130 \uc704\ud5d8\uc758 \ud06c\uae30\ub97c \uc815\ud655\ud788 \uc54c\uc558\uc744 \uac83\uc774\ub77c \uc0dd\uac01\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc5b4\uba38\ub2c8\ub294 \uc790\uc2e0 \ub54c\ubb38\uc5d0 \uc544\ub4e4\uc758 \ud53c\ub09c\uc774 \ub2a6\uc5b4\uc9c4\ub2e4\uba70 \uba3c\uc800 \uac00\ub77c\uace0 \ud558\uc9c0\ub9cc, \uadf8\ub294 \ub0a8\uaca8 \ub450\uc9c0 \uc54a\uace0 \ud568\uaed8 \uc6c0\uc9c1\uc778\ub2e4. \uc7ac\uac00 \ub5a8\uc5b4\uc9c0\uace0 \ub9c8\uce68\ub0b4 \uc0ac\ubc29\uc774 \uae4a\uc774 \uc5b4\ub450\uc6cc\uc9c4\ub2e4. \ud3b8\uc9c0\uc758 \uc5b4\ub460\uc740 \ud3c9\ubc94\ud55c \ud750\ub9b0 \ub0a0\ubcf4\ub2e4 \ubd88\uc744 \ubaa8\ub450 \ub048 \ubc29\uc5d0 \uac00\uae4c\uc6b4 \uac83\uc73c\ub85c \ubb18\uc0ac\ub41c\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \uc5bc\uad74 \ub300\uc2e0 \ubaa9\uc18c\ub9ac\ub85c \uac00\uc871\uc744 \ucc3e\ub294\ub2e4. \uacf5\ud3ec \uc18d\uc5d0\uc11c\ub294 \ud2c0\ub9b0 \uc18c\ubb38\ub3c4 \ud37c\uc9c4\ub2e4. \ub3c4\uc2dc \uc77c\ubd80\uac00 \ubb34\ub108\uc84c\uac70\ub098 \ubd88\ud0d4\ub2e4\ub294 \ub9d0 \uac00\uc6b4\ub370\uc5d0\ub294 \uc0ac\uc2e4\uc774 \uc544\ub2cc \uac83\ub3c4 \uc788\uc5c8\ub2e4\uace0 \uadf8\ub294 \uc801\ub294\ub2e4. \uc7ac\ub09c\uc758 \uae30\ub85d\uc740 \uc790\uc5f0\uc774 \ud55c \uc77c\ub9cc\uc774 \uc544\ub2c8\ub77c \uc0ac\ub78c\ub4e4\uc774 \uc54c\uc9c0 \ubabb\ud55c \ucc44 \uc11c\ub85c \uc804\ud55c \ub9d0\uae4c\uc9c0 \ud3ec\ud568\ud55c\ub2e4. \uc6b0\ub9ac\uac00 \uc9c0\uae08 \uc77d\ub294 \ud3b8\uc9c0\ub3c4 \uadf8 \ud63c\ub780\uc744 \uc9c0\ub098 \uc815\ub9ac\ub41c \uc774\uc57c\uae30\ub2e4. \uc5b4\ub460\uc774 \ubb3c\ub7ec\ub09c \ub4a4 \uc8fc\ubcc0\uc740 \uc7ac\uc5d0 \ub36e\uc5ec \ub2e4\ub978 \uc7a5\uc18c\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uc18c \ud50c\ub9ac\ub2c8\uc6b0\uc2a4\uc640 \uc5b4\uba38\ub2c8\ub294 \uc0b4\uc544\ub0a8\uc9c0\ub9cc, \uc0bc\ucd0c\uc758 \uc18c\uc2dd\uc744 \uc54c\uae30 \uc804\uae4c\uc9c0 \uc548\uc2ec\ud560 \uc218 \uc5c6\ub2e4. \ub3c5\uc790\ub294 \ub05d\uc744 \uc54c\uace0 \ud3b8\uc9c0\ub97c \uc77d\uc5b4\ub3c4 \uadf8 \uae30\ub2e4\ub9bc\uc758 \ubb34\uac8c\ub97c \ub290\ub07c\uac8c \ub41c\ub2e4. \ud55c \uc0ac\ub78c\uc5d0\uac8c \uadc0\ud658\uc774\uc5c8\ub358 \uc2dc\uac04\uc774 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ub9c8\uc9c0\ub9c9 \ud56d\ud574\uc600\ub2e4. \uc774 \ub450 \ud3b8\uc9c0\ub97c \uc77d\ub294 \uc774\uc720\ub294 \uc7ac\ub09c\uc744 \uc0dd\uc0dd\ud558\uac8c \uad6c\uacbd\ud558\uae30 \uc704\ud574\uc11c\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uc9c1\uc811 \ubcf8 \uac83\uacfc \ub4e4\uc740 \uac83, \uad00\ucc30\uacfc \ucd94\uce21, \ucd94\ubaa8\uc640 \uc5ed\uc0ac\ub97c \uc5b4\ub5bb\uac8c \uad6c\ubcc4\ud560\uc9c0 \uc0dd\uac01\ud558\uac8c \ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \uc18c\ub098\ubb34 \uac19\uc740 \uad6c\ub984\uc740 \uadf8\ub798\uc11c \ub2e8\uc9c0 \uc720\uba85\ud55c \ube44\uc720\uac00 \uc544\ub2c8\ub2e4. \uac70\ub300\ud55c \uc0ac\uac74\uc744 \uc790\uc2e0\uc774 \uc774\ud574\ud560 \uc218 \uc788\ub294 \ub9d0\ub85c \ub0a8\uae30\ub824 \ud588\ub358 \uc0ac\ub78c\uc758 \uccab \ubc88\uc9f8 \uc190\uc7a1\uc774\ub2e4."}, {"id": "pompeii-79-ash-and-everyday-city", "title": "\ud3fc\ud398\uc774 \u2014 \ud654\uc0b0\uc7ac \uc544\ub798\uc5d0\uc11c \ub3c4\uc2dc\uc758 \uc77c\uc0c1\uc774 \ub098\ud0c0\ub098\ub2e4", "summary": "\uc7ac\ub09c \uc774\uc804\uc758 \ubcf5\uad6c\uc640 \uc774\ud6c4\uc758 \ubc1c\uad74, \uae38\uacfc \uc791\uc5c5\uc7a5\uc5d0 \ub0a8\uc740 \ub85c\ub9c8\uc778\uc758 \uc0dd\ud65c\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/pompeii-79-ash-and-everyday-city/index.html", "image": "../media/pompeii-79-ash-and-everyday-city.jpg", "alt": "\ud3fc\ud398\uc774 \uc81c\ube75 \uc791\uc5c5\uc7a5\uc758 \ub9f7\ub3cc\uacfc \ubcbd\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc61b \uc720\uc801 \uc790\ub8cc \uc774\ubbf8\uc9c0", "text": "\ud3fc\ud398\uc774 \u2014 \ud654\uc0b0\uc7ac \uc544\ub798\uc5d0\uc11c \ub3c4\uc2dc\uc758 \uc77c\uc0c1\uc774 \ub098\ud0c0\ub098\ub2e4 79\ub144\uc758 \uc7ac\ub09c\uacfc \uac70\ub9ac\u00b7\uc81c\ube75\u00b7\uae00\uc758 \ud754\uc801\uc744 \ud1b5\ud574 \uc77d\ub294 \uace0\ub300 \uc0dd\ud65c \uc7ac\ub09c \uc774\uc804\uc758 \ubcf5\uad6c\uc640 \uc774\ud6c4\uc758 \ubc1c\uad74, \uae38\uacfc \uc791\uc5c5\uc7a5\uc5d0 \ub0a8\uc740 \ub85c\ub9c8\uc778\uc758 \uc0dd\ud65c\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ub3cc\uae38\uacfc \uc9d1\uc758 \ubcbd, \ube75\uc744 \ub9cc\ub4e4\ub358 \uc791\uc5c5\uc7a5\uae4c\uc9c0 \ub0a8\uc544 \uc788\ub2e4. \ud3fc\ud398\uc774\ub97c \ubcf4\uba74 \ub85c\ub9c8 \uc2dc\ub300\uc758 \uc0ac\ub78c\ub4e4\uc774 \uac11\uc790\uae30 \uba40\uc9c0 \uc54a\uac8c \ub290\uaef4\uc9c4\ub2e4. \ubca0\uc218\ube44\uc624 \ud654\uc0b0\uc758 \ubd84\ud654\uac00 \ub3c4\uc2dc\ub97c \ud30c\uad34\ud588\uc9c0\ub9cc, \uadf8 \uc7ac\ub09c\uc774 \ub0a8\uae34 \ud1f4\uc801\ubb3c\uc740 \ud6c4\ub300\uac00 \uc0dd\ud65c\uc758 \ud754\uc801\uc744 \uc77d\ub294 \uc870\uac74\uc774 \ub418\uae30\ub3c4 \ud588\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub3c4\uc2dc \uc804\uccb4\uac00 \ud55c\uc21c\uac04\uc758 \ubaa8\uc2b5 \uadf8\ub300\ub85c \uc644\ubcbd\ud558\uac8c \ubcf4\uc874\ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. \ubd84\ud654\uc640 \ub9e4\ubab0, \ubc1c\uad74\uacfc \ubcf5\uc6d0\uc758 \uc2dc\uac04\uc774 \uacb9\uccd0 \uc788\ub2e4. \uae30\uc6d0\ud6c4 79\ub144\uc758 \uc7ac\ub09c\uc5d0\uc11c \uc2dc\uc791\ud574 \uc9d1\uacfc \uac70\ub9ac, \uc0dd\uc5c5\uc758 \ud754\uc801\uc744 \uc77d\ub294 \ubc29\ubc95\uae4c\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \ud3fc\ud398\uc774\ub294 \uc7ac\ub09c\uc744 \uae30\ub2e4\ub9ac\ub294 \ubc15\uc81c\ub41c \ub3c4\uc2dc\uac00 \uc544\ub2c8\uc5c8\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \uc0b4\uace0 \uc7a5\uc0ac\ud558\uace0 \uac74\ubb3c\uc744 \uace0\uce58\ub294 \uacf3\uc774\uc5c8\ub2e4. 62\ub144\uc758 \ud070 \uc9c0\uc9c4 \ub4a4\uc5d0\ub294 \ubcf5\uad6c\uac00 \uc9c4\ud589\ub418\uc5c8\uace0, 79\ub144 \ubd84\ud654 \ub2f9\uc2dc\uc5d0\ub3c4 \uc774\uc804 \ud53c\ud574\uc640 \uc7ac\uac74\uc758 \ud754\uc801\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \uc720\uc801\uc5d0 \ubcf4\uc774\ub294 \uc11c\ub85c \ub2e4\ub978 \uc0c1\ud0dc\ub97c \uc774\ud574\ud558\ub294 \uc911\uc694\ud55c \ubc30\uacbd\uc774\ub2e4. \uc774 \uc0ac\uc2e4\uc744 \uc54c\uba74 \ubb34\ub108\uc9c4 \ubcbd \ud558\ub098\ub97c \ubcf4\uace0 \ubaa8\ub450 \ud654\uc0b0 \ub54c\ubb38\uc774\ub77c\uace0 \ud310\ub2e8\ud558\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \ub3c4\uc2dc\uc5d0\ub294 \uc774\ubbf8 \uc5ec\ub7ec \uc2dc\uae30\uc758 \uc218\ub9ac\uc640 \ubcc0\uacbd\uc774 \uc313\uc5ec \uc788\uc5c8\ub2e4. \ud55c \uc0ac\uac74\uc774 \uc720\uba85\ud560\uc218\ub85d \ubaa8\ub4e0 \ud754\uc801\uc744 \uadf8 \uc0ac\uac74\uc5d0\ub9cc \uc5f0\uacb0\ud558\uae30 \uc27d\ub2e4. \ud3fc\ud398\uc774\ub3c4 \uc7ac\ub09c \uc774\uc804\uc758 \uc2dc\uac04\uc774 \uc788\ub294 \uc7a5\uc18c\ub2e4. 79\ub144 \ud654\uc0b0\uc758 \ubd84\ud654\ub85c \ud654\uc0b0\uc7ac\uc640 \ubd84\ucd9c\ubb3c\uc774 \ub3c4\uc2dc\ub97c \ub36e\uace0 \ud070 \ud53c\ud574\ub97c \uc77c\uc73c\ucf30\ub2e4. \ub2f9\uc2dc \uc0c1\ud669\uc744 \uc774\ud574\ud558\ub294 \uc911\uc694\ud55c \ubb38\ud5cc\uc5d0\ub294 \uc18c\ud50c\ub9ac\ub2c8\uc6b0\uc2a4\uac00 \ub0a8\uae34 \ud3b8\uc9c0\ub4e4\uc774 \uc788\ub2e4. \uadf8\uc758 \uc0bc\ucd0c \ub300\ud50c\ub9ac\ub2c8\uc6b0\uc2a4\ub294 \uad6c\uc870\uc5d0 \ub098\uc130\ub2e4\uac00 \ubaa9\uc228\uc744 \uc783\uc5c8\ub2e4. \uc7ac\ub09c\uc758 \uc5ed\uc0ac\ub294 \ub545\uc758 \ud754\uc801\uacfc \uae00\uc758 \uc99d\uc5b8\uc744 \ud568\uaed8 \uc77d\uc73c\uba70 \uad6c\uc131\ub41c\ub2e4. \ud3b8\uc9c0\ub97c \uc4f4 \uc18c\ud50c\ub9ac\ub2c8\uc6b0\uc2a4\ub294 \ub2f9\uc2dc \ubbf8\uc138\ub214\uc5d0 \uba38\ubb3c\ub800\ub2e4. \ub3c4\uc2dc \uc548\uc758 \ubaa8\ub4e0 \uc7a5\uba74\uc744 \uc9c1\uc811 \ubcf8 \uc0ac\ub78c\uc758 \ubcf4\uace0\uc640\ub294 \ub2e4\ub974\ub2e4. \uac19\uc740 \uc7ac\ub09c\ub3c4 \uc5b4\ub290 \uc704\uce58\uc5d0\uc11c \ubb34\uc5c7\uc744 \ubcf4\uace0 \ub4e4\uc5c8\ub294\uc9c0\uc5d0 \ub530\ub77c \uae30\ub85d\uc758 \ubc94\uc704\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \ubb38\ud5cc\uacfc \ubc1c\uad74\uc758 \ud754\uc801\uc744 \ud568\uaed8 \ub300\uc870\ud558\ub294 \uc774\uc720\ub2e4. \uac70\ub9ac\uc758 \ud3ec\uc7a5\uacfc \uae38\uc744 \uac74\ub108\ub294 \ub3cc, \ubb3c\uc744 \ub2e4\ub8e8\ub294 \uc2dc\uc124\uc744 \ubcf4\uba74 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5bb\uac8c \uc774\ub3d9\ud588\ub294\uc9c0 \uc9c8\ubb38\ud558\uac8c \ub41c\ub2e4. \uc9c0\ub3c4\ub97c \ud3c9\uba74\uc73c\ub85c \ubcf4\ub294 \uac83\uacfc \uc2e4\uc81c \ub192\ub0ae\uc774\ub97c \uac00\uc9c4 \uae38\uc744 \uac77\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uc791\uc740 \uad6c\uc870\uc5d0\ub3c4 \ubcf4\ud589\uacfc \uc6b4\ubc18, \uac70\ub9ac\uc758 \uc0ac\uc6a9 \ubc29\uc2dd\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uae38\uc744 \ub3c4\uc2dc\uc758 \ud070 \uac74\ubb3c\uc744 \uc787\ub294 \ube48 \uacf5\uac04\uc73c\ub85c\ub9cc \uc0dd\uac01\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\ub2e4. \uac00\uac8c\uc640 \uc9d1\uc758 \ubb38\uc774 \uc5f4\ub9ac\ub294 \uacf3\uc774\uba70 \uc0ac\ub78c\ub4e4\uc774 \uc11c\ub85c \ub9cc\ub098\ub294 \uc790\ub9ac\uc600\ub2e4. \uc720\uc801\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\ub294 \uc0dd\ud65c\uc740 \ud654\ub824\ud55c \uacf5\uacf5\uac74\ubb3c \uc548\uc5d0\ub9cc \ub0a8\uc544 \uc788\uc9c0 \uc54a\ub2e4. \uac70\ub9ac\uc758 \ud3ed\uacfc \ubb38\ud131\ub3c4 \ub3c4\uc2dc\ub97c \uc77d\ub294 \uc790\ub8cc\ub2e4. \ud3fc\ud398\uc774\uc758 \uc81c\ube75 \uc791\uc5c5\uc7a5\uc5d0\ub294 \uace1\uc2dd\uc744 \uac00\ub294 \ub9f7\ub3cc\uacfc \ube75\uc744 \uad7d\ub294 \uc2dc\uc124\uc758 \ud754\uc801\uc774 \ub0a8\uc544 \uc788\ub2e4. \uc774\ub97c \ubcf4\uba74 \ube75\uc774\ub77c\ub294 \uc644\uc131\ud488 \uc774\uc804\uc758 \uc77c\uc774 \ubcf4\uc778\ub2e4. \uc7ac\ub8cc\ub97c \uc62e\uae30\uace0 \uac08\uace0 \ubc18\uc8fd\ud558\uace0 \uad7d\ub294 \uc21c\uc11c\uac00 \uc788\uc5c8\ub2e4. \ub85c\ub9c8\uc778\uc758 \uc0dd\ud65c\uc744 \uc74c\uc2dd \uc774\ub984\ub9cc\uc774 \uc544\ub2c8\ub77c \uc791\uc5c5\uc758 \uc5f0\uacb0\ub85c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc791\uc5c5\uc7a5\uc740 \ubaa8\ub4e0 \uc8fc\ubbfc\uc774 \ub611\uac19\uc774 \uc5ec\uc720\ub85c\uc6b4 \uc0dd\ud65c\uc744 \ud588\ub2e4\ub294 \uc778\uc0c1\uc744 \uae68\uae30\ub3c4 \ud55c\ub2e4. \ub204\uad70\uac00\ub294 \ube75\uc744 \uc0ac\uace0 \ub204\uad70\uac00\ub294 \ubc18\ubcf5\ub418\ub294 \uc77c\uc744 \uc218\ud589\ud588\ub2e4. \uc720\uc801\uc758 \uc544\ub984\ub2e4\uc6c0\uc744 \uac10\uc0c1\ud558\uba74\uc11c \uadf8 \uc548\uc5d0\uc11c \uc77c\ud55c \uc0ac\ub78c\uc744 \ud568\uaed8 \ub5a0\uc62c\ub824\uc57c \ud55c\ub2e4. \uc624\ub798\ub41c \ub3c4\uc2dc\ub294 \uc0dd\ud65c\uc758 \ud3b8\ub9ac\ud568\uacfc \ub178\ub3d9\uc758 \ubd80\ub2f4\uc744 \ub3d9\uc2dc\uc5d0 \ub2f4\uc558\ub2e4. \uc9d1 \uc548\uc758 \ubcbd\ud654\ub294 \uac70\uc8fc\uc790\uc758 \ucde8\ud5a5\uacfc \uacf5\uac04 \uc0ac\uc6a9\uc744 \uc0dd\uac01\ud558\uac8c \ud558\uace0, \ubcbd\uc5d0 \ub0a8\uc740 \uae00\uc740 \ub2e4\ub978 \uc885\ub958\uc758 \uc0dd\ud65c\uc744 \uc804\ud55c\ub2e4. \uc815\uce58\uc801 \uc120\uc804\uacfc \uac1c\uc778\uc801\uc778 \ud45c\ud604\uc774 \ub3c4\uc2dc\uc758 \ud45c\uba74\uc5d0 \uacb9\uccd0 \uc788\uc5c8\ub2e4. \ud6c4\ub300\uc758 \uc5ed\uc0ac\ucc45\ub9cc\uc73c\ub85c\ub294 \ub9cc\ub098\uae30 \uc5b4\ub824\uc6b4 \uc0ac\ub78c\ub4e4\uc758 \uad00\uc2ec\uc0ac\uac00 \ub0a8\uc740 \uac83\uc774\ub2e4. \uadf8\ub7ec\ub098 \uae00 \ud558\ub098\ub85c \ubaa8\ub4e0 \uc8fc\ubbfc\uc758 \uc0dd\uac01\uc744 \ub300\ud45c\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub204\uac00 \uc37c\uace0 \ub204\uad6c\uc5d0\uac8c \ubcf4\uc774\ub824 \ud588\ub294\uc9c0\uc758 \uc9c8\ubb38\uc774 \ud544\uc694\ud558\ub2e4. \uc9d1 \uc5ed\uc2dc \ud070 \uc800\ud0dd\uacfc \uc791\uc740 \uac70\ucc98\uac00 \uac19\uc9c0 \uc54a\uc558\ub2e4. \ud3fc\ud398\uc774\uc758 \ud48d\ubd80\ud55c \uc790\ub8cc\ub294 \ud558\ub098\uc758 \ub85c\ub9c8\uc2dd \uc0dd\ud65c\uc744 \ud655\uc815\ud558\uae30\ubcf4\ub2e4 \uadf8 \uc548\uc758 \ucc28\uc774\ub97c \ub354 \uc798 \ubcf4\uac8c \ud55c\ub2e4. \uacf5\uc911\ubaa9\uc695 \uc2dc\uc124\ub3c4 \ub3c4\uc2dc\uc758 \uc77c\uc0c1\uc744 \uc77d\ub294 \uc911\uc694\ud55c \uc790\ub9ac\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \ud568\uaed8 \uc0ac\uc6a9\ud558\ub294 \uacf5\uac04\uacfc \ubb3c\uc744 \ub2e4\ub8e8\ub294 \uad6c\uc870\uac00 \ub0a8\uc544 \uc788\ub2e4. \uc9d1 \uc548\uc5d0\uc11c \ud558\ub294 \uc77c\ub9cc\uc73c\ub85c \uc0dd\ud65c \uc804\uccb4\ub97c \uc124\uba85\ud560 \uc218 \uc5c6\uc5c8\ub358 \uac83\uc774\ub2e4. \uc0ac\uc801\uc778 \uac70\ucc98\uc640 \uacf5\uacf5\uc758 \uc2dc\uc124\uc744 \ud568\uaed8 \ubcf4\uba74 \ub3c4\uc2dc\uac00 \uc81c\uacf5\ud55c \uc0dd\ud65c\uc758 \ubc94\uc704\uac00 \ub354 \uc798 \ubcf4\uc778\ub2e4. \ub9e4\ubab0\ub41c \ud754\uc801\uc744 \ub4dc\ub7ec\ub0b4\ub294 \uacfc\uc815\uc5d0\uc11c\ub3c4 \ud310\ub2e8\uacfc \uae30\uc220\uc774 \ub4e4\uc5b4\uac04\ub2e4. \ubb34\uc5c7\uc744 \ub0a8\uae30\uace0 \uc5b4\ub5bb\uac8c \ubcf4\ud638\ud558\uba70 \uc5b4\ub514\uae4c\uc9c0 \ubcf5\uc6d0\ud560\uc9c0\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ubc1c\uad74 \uc774\ud6c4 \ube44\uc640 \ud587\ube5b\uc5d0 \ub178\ucd9c\ub418\ub294 \uc720\uc801\uc740 \ub2e4\uc2dc \ubcf4\uc874\uc758 \ubb38\uc81c\ub97c \uacaa\ub294\ub2e4. \ub545 \uc704\uc5d0 \ub098\ud0c0\ub0ac\ub2e4\uace0 \uc548\uc804\ud558\uac8c \uc2dc\uac04\uc774 \uba48\ucd94\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud3fc\ud398\uc774\uc5d0\uc11c \uc54c\ub824\uc9c4 \uc11d\uace0 \uc8fc\ud615\ub3c4 \ubab8 \uc790\uccb4\uac00 \ub3cc\ub85c \ubc14\ub00c\uc5b4 \ub0a8\uc740 \uac83\uc774 \uc544\ub2c8\ub77c, \uc720\ud574 \uc8fc\ubcc0\uc5d0 \uc0dd\uae34 \ube48 \uacf5\uac04\uc744 \uc774\uc6a9\ud55c \uae30\ub85d\uc758 \ubc29\uc2dd\uc774\ub2e4. \ub0a8\uc740 \uc2e4\ubb3c\uacfc \ud6c4\ub300\uac00 \ud754\uc801\uc744 \ub4dc\ub7ec\ub0b8 \ubc29\ubc95\uc744 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ubb34\uc5c7\uc744 \ubcf4\uace0 \uc788\ub294\uc9c0 \uc544\ub294 \uc77c\uc774 \uc7ac\ub09c\uc758 \uae30\uc5b5\uc744 \ub354 \uc815\ud655\ud558\uac8c \ub300\ud558\uac8c \ud55c\ub2e4. \ud3fc\ud398\uc774\uac00 \ud2b9\ubcc4\ud55c \uc774\uc720\ub294 \uace0\ub300\uc758 \uc0dd\ud65c\uc744 \uad6c\uccb4\uc801\uc73c\ub85c \ub9cc\ub0a0 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ud558\uc9c0\ub9cc \ud6c4\ub300\uc758 \ub3c5\uc790\uac00 \ub9ce\uc740 \uac83\uc744 \ubc30\uc6b8 \uc218 \uc788\uac8c \ub418\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub2f9\uc2dc\uc758 \ube44\uadf9\uc744 \uc88b\uc740 \uc77c\ub85c \ubc14\uafb8\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc9c0\uc2dd\uc758 \uac00\uce58\uc640 \uc0ac\ub78c\ub4e4\uc758 \uc190\uc2e4\uc744 \ud568\uaed8 \uae30\uc5b5\ud560 \uc218 \uc788\ub2e4. \ube75\uc9d1\uc758 \ub9f7\ub3cc\uacfc \uae38\uc758 \ub3cc, \uc9d1\uc758 \ubcbd\uc744 \ub2e4\uc2dc \ubcf4\uba74 \uac70\ub300\ud55c \ub85c\ub9c8\uc81c\uad6d\uc774 \uc791\uc740 \uc77c\uc0c1\uc758 \ubc18\ubcf5 \uc704\uc5d0 \uc788\uc5c8\ub2e4\ub294 \uac83\uc774 \ubcf4\uc778\ub2e4. \ud3fc\ud398\uc774\ub294 \ud654\uc0b0\uc5d0 \ud30c\uad34\ub41c \ub3c4\uc2dc\uc778 \ub3d9\uc2dc\uc5d0 \uc0ac\ub78c\ub4e4\uc774 \uc77c\ud558\uace0 \uc26c\uace0 \uace0\uce58\uba70 \uc0b4\uc544\uac04 \ub3c4\uc2dc\uc600\ub2e4. \uadf8 \ub450 \uc2dc\uac04\uc744 \ud568\uaed8 \uc77d\uc744 \ub54c \uc720\uc801\uc740 \ub354 \uae4a\uc740 \uc77d\uc744\uac70\ub9ac\uac00 \ub41c\ub2e4."}, {"id": "pompeii-isis-small-temple", "title": "\ud3fc\ud398\uc774 \u2014 \uc774\uc9d1\ud2b8\uc758 \uc5ec\uc2e0\uc740 \uc5b4\ub5bb\uac8c \uc774\uacf3\uc5d0 \uc654\uc744\uae4c", "summary": "\ud3fc\ud398\uc774 \uc774\uc2dc\uc2a4 \uc2e0\uc804\uc758 \uc704\uce58\uc640 \uacf5\uac04\uc744 \ud1b5\ud574 \ub85c\ub9c8 \ub3c4\uc2dc \uc548\uc5d0 \ub4e4\uc5b4\uc628 \uc2e0\uc559\uacfc \uc0dd\ud65c\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/pompeii-isis-small-temple/index.html", "image": "../media/pompeii-isis-small-temple.png", "alt": "\ud3fc\ud398\uc774 \uc774\uc2dc\uc2a4 \uc2e0\uc804\uc758 \uacc4\ub2e8\uacfc \uae30\ub465\uc774 \ub0a8\uc740 \uc815\uba74 \uc0ac\uc9c4.", "text": "\ud3fc\ud398\uc774 \u2014 \uc774\uc9d1\ud2b8\uc758 \uc5ec\uc2e0\uc740 \uc5b4\ub5bb\uac8c \uc774\uacf3\uc5d0 \uc654\uc744\uae4c \uadf9\uc7a5 \ub4a4 \uc791\uc740 \uc2e0\uc804\uc5d0\uc11c \ub9cc\ub098\ub294 \ub85c\ub9c8 \ub3c4\uc2dc\uc758 \ub2e4\ub978 \uc5bc\uad74 \ud3fc\ud398\uc774 \uc774\uc2dc\uc2a4 \uc2e0\uc804\uc758 \uc704\uce58\uc640 \uacf5\uac04\uc744 \ud1b5\ud574 \ub85c\ub9c8 \ub3c4\uc2dc \uc548\uc5d0 \ub4e4\uc5b4\uc628 \uc2e0\uc559\uacfc \uc0dd\ud65c\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ud3fc\ud398\uc774\ub77c\uace0 \ud558\uba74 \ud654\uc0b0\uc774 \ud130\uc9c0\ub358 \ub9c8\uc9c0\ub9c9 \ub0a0\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uc720\uc801 \uc548\uc5d0\ub294 \uadf8\ub0a0 \uc774\uc804\uc758 \uc624\ub79c \uc0dd\ud65c\ub3c4 \ub0a8\uc544 \uc788\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \uc7a5\uc0ac\ub97c \ud558\uace0 \uacf5\uc5f0\uc744 \ubcf4\uace0 \uc2e0\uc5d0\uac8c \uae30\ub3c4\ud588\ub2e4. \ub3c4\uc2dc\ub97c \uc7ac\ub09c\uc758 \uc7a5\uba74 \ud558\ub098\ub85c\ub9cc \uae30\uc5b5\ud558\uba74 \uadf8\ub4e4\uc774 \ud3c9\uc18c \ubb34\uc5c7\uc744 \ubbff\uc5c8\ub294\uc9c0\ub294 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc791\uc740 \uc774\uc2dc\uc2a4 \uc2e0\uc804\uc740 \uc774\ub7f0 \uc77c\uc0c1\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \uc785\uad6c\uac00 \ub41c\ub2e4. \uc774\uc9d1\ud2b8\uc5d0\uc11c \uc628 \uc5ec\uc2e0\uc744 \ub85c\ub9c8\uc758 \uc774\ud0c8\ub9ac\uc544 \ub3c4\uc2dc\uc5d0\uc11c \ub9cc\ub09c\ub2e4\ub294 \uc0ac\uc2e4\ubd80\ud130 \ud765\ubbf8\ub86d\ub2e4. \uc2e0\uc804\uc758 \uaddc\ubaa8\uc640 \uadf9\uc7a5 \ub4a4\ub77c\ub294 \uc704\uce58\ub97c \uc0b4\ud53c\uba74 \ub0af\uc120 \uc2e0\uc559\uc774 \ub3c4\uc2dc \uc548\uc5d0\uc11c \ucc28\uc9c0\ud55c \uc790\ub9ac\uac00 \uc870\uae08\uc529 \ub4dc\ub7ec\ub09c\ub2e4. \ub85c\ub9c8\uc81c\uad6d\uc5d0\ub294 \uc5ec\ub7ec \uc9c0\uc5ed\uc758 \uc885\uad50\uac00 \ud568\uaed8 \uc874\uc7ac\ud588\ub2e4. \uc774\uc2dc\uc2a4 \uc22d\ubc30\ub294 \uc774\uc9d1\ud2b8\uc5d0\uc11c \uc2dc\uc791\ud574 \uae30\uc6d0\uc804 1\uc138\uae30 \ubb34\ub835 \ub85c\ub9c8\uc81c\uad6d \uc11c\ubd80\uc5d0\uc11c\ub3c4 \ud37c\uc84c\ub2e4. \uc0ac\ub78c\uc774 \uc774\ub3d9\ud558\uace0 \uc11c\ub85c \ub2e4\ub978 \uc9c0\uc5ed\uc774 \uc5f0\uacb0\ub418\uba74 \ubb3c\uac74\ubfd0 \uc544\ub2c8\ub77c \uae30\ub3c4\ud558\ub294 \ubc29\uc2dd\ub3c4 \uc804\ud574\uc9c8 \uc218 \uc788\ub2e4. \uc774\uc2dc\uc2a4\ub294 \uc2e0\uc790\ub4e4\uc5d0\uac8c \ud070 \ud798\uc744 \uc9c0\ub2cc \uc5ec\uc2e0\uc73c\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc84c\ub2e4. \ub85c\ub9c8 \uc18c\uc124 \u300a\ud669\uae08 \ub2f9\ub098\uadc0\u300b\uc5d0\ub3c4 \uc8fc\uc778\uacf5\uc744 \uad6c\ud558\ub294 \uc874\uc7ac\ub85c \ub4f1\uc7a5\ud55c\ub2e4. \uc18c\uc124 \uc18d \uc7a5\uba74\uc744 \uc2e4\uc81c \uc0ac\uac74\uc73c\ub85c \ubcfc \uc218\ub294 \uc5c6\uc9c0\ub9cc, \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc774 \uc774 \uc5ec\uc2e0\uc744 \uc5b4\ub5a4 \ub2a5\ub825\uacfc \uc5f0\uacb0\ud588\ub294\uc9c0 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub294 \uc790\ub8cc\ub2e4. \ud3fc\ud398\uc774\uc758 \uc774\uc2dc\uc2a4 \uc2e0\uc804\uc740 \ub3c4\uc2dc \uadf9\uc7a5 \ubc14\ub85c \ub4a4\uc5d0 \uc788\uc5c8\ub2e4. \ub2e4\ub978 \uacf5\uacf5 \uac74\ubb3c\uacfc \uba40\ub9ac \ub5a8\uc5b4\uc9c4 \uacf5\uac04\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc774 \uc704\uce58\ub294 \uc0c8\ub85c\uc6b4 \uc2e0\uc559\uc758 \uc7a5\uc18c\ub3c4 \ub3c4\uc2dc\uc758 \ud3c9\ubc94\ud55c \uc774\ub3d9\uacfc \ub9cc\ub0a0 \uc218 \uc788\uc5c8\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uadf8\ub807\ub2e4\uace0 \uacf5\uc5f0\uc744 \ubcf8 \uc0ac\ub78c\uc774 \ubaa8\ub450 \uc774\uc2dc\uc2a4 \uc2e0\uc790\uac00 \ub418\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc778\uc811\ud55c \uac74\ubb3c\ub4e4\uc774 \uc5b4\ub5a4 \uc77c\uc0c1 \uc18d\uc5d0 \ub193\uc5ec \uc788\uc5c8\ub294\uc9c0 \uc0dd\uac01\ud574 \ubcf4\ub294 \uac83\uc774\ub2e4. \uc720\uc801\uc744 \ud55c \ucc44\uc529 \ub530\ub85c \ubcfc \ub54c\ubcf4\ub2e4 \uc8fc\ubcc0\uc758 \uadf9\uc7a5\uacfc \uae38\uc744 \ud568\uaed8 \ub5a0\uc62c\ub9ac\uba74 \uc2e0\uc804\uc740 \uace0\ub9bd\ub41c \uae30\ub150\ubb3c\uc774 \uc544\ub2c8\ub77c \ub3c4\uc2dc\uc758 \ud55c \uc7a5\uc18c\uac00 \ub41c\ub2e4. \uc0ac\uc9c4\uc5d0\ub294 \ub730 \uc548\ucabd\uc758 \uc2e0\uc804 \uc815\uba74\uc774 \ubcf4\uc778\ub2e4. \uacc4\ub2e8 \uc704\uc5d0 \uae30\ub465\uc774 \ubc1b\uce58\ub294 \uc785\uad6c\uac00 \ub193\uc5ec \uc788\uace0 \uc8fc\ubcc0\uc73c\ub85c \ub0ae\uc740 \uacf5\uac04\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ud070 \uc81c\uad6d\uc758 \uc885\uad50 \uac74\ucd95\uc774\ub77c\uace0 \ud574\uc11c \uc5b8\uc81c\ub098 \uac70\ub300\ud55c \uaddc\ubaa8\ub9cc\uc744 \uae30\ub300\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uad50\uc7ac\ub294 \uc774 \uc2e0\uc804\uc758 \ube44\uad50\uc801 \uc791\uc740 \ud06c\uae30\uc640 \ub0b4\ubd80 \uad6c\uc131\uc774 \uc774\uc2dc\uc2a4 \uc2e0\uc559\uc758 \uc785\ubb38 \uc758\ub840\uc640 \uad00\ub828\ub41c \uacf5\uac04\uc784\uc744 \uc124\uba85\ud55c\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\ub294 \uac83\uc740 \ub0a8\uc740 \uac74\ucd95\uc758 \ubaa8\uc2b5\uc774\ub2e4. \uacfc\uac70\uc5d0 \uc774\uacf3\uc744 \ub4dc\ub098\ub4e0 \uc0ac\ub78c\uc758 \uc218\uc640 \ud2b9\uc815 \uc758\ub840\uc758 \uc9c4\ud589\uc744 \uc0ac\uc9c4\ub9cc\uc73c\ub85c \uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc774 \uc2e0\uc804\uc740 \uc544\uc6b0\uad6c\uc2a4\ud22c\uc2a4 \uc2dc\ub300\uc5d0 \uc138\uc6cc\uc84c\uace0, 62\ub144 \ud3fc\ud398\uc774\uc758 \uc9c0\uc9c4 \ub4a4 \uc7ac\uac74\ub418\uc5c8\ub2e4\uace0 \uad50\uc7ac\ub294 \uc124\uba85\ud55c\ub2e4. \uadf8\ub85c\ubd80\ud130 17\ub144 \ub4a4 \ubca0\uc218\ube44\uc624 \ud654\uc0b0\uc758 \ubd84\ud654\uac00 \uc77c\uc5b4\ub0ac\ub2e4. \ub3c4\uc2dc\uc758 \ub9c8\uc9c0\ub9c9 \uc7ac\ub09c \uc774\uc804\uc5d0\ub3c4 \uac74\ubb3c\uc744 \ub2e4\uc2dc \uc138\uc6b0\ub294 \uc2dc\uac04\uc774 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4. \uc720\uc801\uc744 \ubcf4\uba74 \ucc98\uc74c \uc138\uc6e0\uc744 \ub54c\ubd80\ud130 \uadf8\ub300\ub85c \uba48\ucd98 \ubb3c\uac74\ucc98\ub7fc \ub290\ub07c\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uc0ac\ub78c\uc774 \uc0ac\ub294 \ub3c4\uc2dc\ub294 \uc190\uc0c1\ub418\uace0 \uace0\uccd0\uc9c4\ub2e4. \uc2e0\uc804\uc774 \uc7ac\uac74\ub418\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub204\uad70\uac00 \uadf8 \uc7a5\uc18c\ub97c \uacc4\uc18d \uc0ac\uc6a9\ud558\ub824 \ud588\uc74c\uc744 \uc54c\ub824 \uc900\ub2e4. \ub0a8\uc740 \ubcbd \ub4a4\uc5d0\ub294 \uc720\uc9c0\ud558\uace0 \ub2e4\uc2dc \ub9c8\ub828\ud55c \uc0dd\ud65c\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uad50\uc7ac\uac00 \uc124\uba85\ud558\ub294 \uc61b \uc2e0\uc804\uc5d0\ub294 \uc774\uc2dc\uc2a4\uc640 \uc624\uc2dc\ub9ac\uc2a4\uc758 \uc0c1, \uc2e0\ud654\ub97c \uadf8\ub9b0 \ubcbd\ud654\uac00 \uc788\uc5c8\ub2e4. \uc785\ubb38\ud55c \uc2e0\uc790\ub4e4\uc774 \ubaa8\uc774\ub294 \uacf5\uac04\uacfc \uc0ac\uc81c\uc758 \uac70\ucc98, \uc81c\ub2e8\uacfc \uc9c0\ud558\uc758 \uc758\ub840 \uacf5\uac04\ub3c4 \uc18c\uac1c\ub41c\ub2e4. \uc785\uad6c \ud558\ub098\ub9cc \ubcf4\uace0 \uc804\uccb4\uc758 \uc5ed\ud560\uc744 \ub2e4 \uc54c \uc218\ub294 \uc5c6\ub294 \ubc30\uce58\ub2e4. \ub2e4\ub9cc \ud604\uc7ac \uc0ac\uc9c4\uc5d0 \uadf8 \ubaa8\ub4e0 \uc7a5\uc2dd\uacfc \ub0b4\ubd80 \uc2dc\uc124\uc774 \uc644\uc804\ud55c \ubaa8\uc2b5\uc73c\ub85c \ubcf4\uc778\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc790\ub8cc\uac00 \uc124\uba85\ud558\ub294 \uacfc\uac70 \uad6c\uc131\uacfc \ub208\uc55e\uc5d0 \ub0a8\uc740 \uc720\uc801\uc744 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \uc774 \ucc28\uc774\ub97c \uc54c\uba74 \ubcf4\uc774\uc9c0 \uc54a\ub294 \ubd80\ubd84\uc744 \ub9c8\uc74c\ub300\ub85c \ucc44\uc6b0\uae30\ubcf4\ub2e4 \ubb34\uc5c7\uc744 \ub354 \ud655\uc778\ud560\uc9c0 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \uc774\uc2dc\uc2a4 \uc2e0\uc559\uc740 \uc785\ubb38 \uc808\ucc28\uc640 \uc2e0\uc790 \uc9d1\ub2e8\uc758 \ud65c\ub3d9\uc744 \uac00\uc9c4 \uc774\ub978\ubc14 \uc2e0\ube44 \uc885\uad50\uc758 \ud558\ub098\ub85c \uc124\uba85\ub41c\ub2e4. \uc774\ub984 \ub54c\ubb38\uc5d0 \ud658\uc0c1 \uc18c\uc124\uc758 \ube44\ubc00 \uc870\uc9c1\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\uc9c0\ub9cc, \uadf8\uac83\ub9cc\uc73c\ub85c \ub2f9\uc2dc \uc885\uad50 \uc0dd\ud65c\uc744 \uc774\ud574\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc2e4\uc81c\ub85c\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc2e0\uacfc \uad6c\uc6d0, \uacf5\ub3d9\uccb4\ub97c \ub9cc\ub098\ub294 \ubc29\uc2dd\uc758 \ud558\ub098\uc600\ub2e4. \uc5ec\ub7ec \uc885\uad50\uac00 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uace7\ubc14\ub85c \uc544\ubb34 \uac08\ub4f1\ub3c4 \uc5c6\uc5c8\ub2e4\ub294 \ub9d0\ub85c \ubc14\uafc0 \uc218\ub3c4 \uc5c6\ub2e4. \ub85c\ub9c8\uc81c\uad6d\uc5d0\uc11c \uac01 \uc885\uad50\uac00 \uc804\ud1b5 \uc758\ub840\uc640 \ub9fa\uc740 \uad00\uacc4\ub294 \ub2ec\ub790\ub2e4. \uc791\uc740 \uc2e0\uc804\uc740 \ub3c4\uc2dc\uc758 \ub2e4\uc591\uc131\uc744 \ubcf4\uc5ec \uc8fc\uc9c0\ub9cc, \uc81c\uad6d\uc758 \ubaa8\ub4e0 \uc2e0\uc559\uc774 \uac19\uc740 \uc870\uac74\uc5d0 \uc788\uc5c8\ub2e4\ub294 \uc99d\uba85\uc740 \uc544\ub2c8\ub2e4. \ud3fc\ud398\uc774\ub294 79\ub144\uc758 \ubd84\ud654 \ub54c\ubb38\uc5d0 \ud2b9\ubcc4\ud55c \uace0\uace0\ud559 \uc790\ub8cc\ub97c \ub0a8\uacbc\ub2e4. \ud558\uc9c0\ub9cc \uadf8\uacf3\uc758 \uc8fc\ubbfc\uc744 \ub9c8\uc9c0\ub9c9 \uc21c\uac04\ub9cc\uc73c\ub85c \uc124\uba85\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uacf5\uc5f0\uc7a5 \uac00\uae4c\uc774 \uc2e0\uc804\uc744 \ub450\uace0 \uac74\ubb3c\uc744 \uace0\uce58\uba70 \uc0dd\ud65c\uc744 \uc774\uc5b4 \uac00\ub358 \uc0ac\ub78c\ub4e4\uc774 \uc788\uc5c8\ub2e4. \uc774\uc2dc\uc2a4 \uc2e0\uc804\uc744 \ubc14\ub77c\ubcf4\uba74 \uc7ac\ub09c\ubcf4\ub2e4 \uc55e\uc120 \uc9c8\ubb38\uc774 \uc0dd\uae34\ub2e4. \uc774 \ub3c4\uc2dc \uc0ac\ub78c\ub4e4\uc740 \ub204\uad6c\uc640 \ud568\uaed8 \uae30\ub3c4\ud588\uace0 \uc5b4\ub5a4 \uc774\uc57c\uae30\uc5d0 \uc704\uc548\uc744 \uc5bb\uc5c8\uc744\uae4c. \uc815\ud655\ud788 \uc54c \uc218 \uc5c6\ub294 \uac1c\uc778\uc758 \ub9c8\uc74c\uc744 \ucc3d\uc791\ud558\uc9c0 \uc54a\uc544\ub3c4, \uacf5\uac04\uacfc \uc790\ub8cc\ub97c \ud1b5\ud574 \ub2f9\uc2dc \uc0dd\ud65c\uc758 \uc5ec\ub7ec \uc120\ud0dd\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \ubc1c\uad74\ub41c \uc774\uc2dc\uc2a4 \uc2e0\uc804\uc758 \uc2e4\uc81c \uc0ac\uc9c4\uc774\ub2e4. \uc774\uc9d1\ud2b8 \uc2e0\uc559\uc774 \uc774\ud0c8\ub9ac\uc544 \ub3c4\uc2dc \uc548\uc5d0 \uc790\ub9ac\ud588\ub358 \uac74\ucd95\uc758 \ud754\uc801\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc5ec\uc2e0\uc758 \uc774\ub3d9 \uacbd\ub85c\ub97c \ud55c \uc0ac\ub78c\uc758 \uc5ec\ud589\uc73c\ub85c \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\uc9c0\ub9cc \uc9c0\uc911\ud574 \uc138\uacc4\uc758 \uc5f0\uacb0\uc744 \ub290\ub07c\uac8c \ud55c\ub2e4. \ub2e4\uc74c\uc5d0 \ub85c\ub9c8 \uc720\uc801\uc744 \ub9cc\ub098\uba74 \uc774\ub984\ub09c \ud669\uc81c\uc640 \ud070 \uacbd\uae30\uc7a5 \uacc1\uc758 \uc791\uc740 \uacf5\uac04\ub3c4 \ubcf4\uc544 \ub450\uc790. \uc81c\uad6d\uc758 \ub3c4\uc2dc\uc5d0\ub294 \uc5ec\ub7ec \uc9c0\uc5ed\uc5d0\uc11c \uc628 \ubbff\uc74c\uacfc \uc0dd\ud65c\uc774 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \ud3fc\ud398\uc774\uc758 \uc791\uc740 \uc2e0\uc804\uc740 \ub3c4\uc2dc\uac00 \ubb34\uc5c7\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ud558\ub294 \uc870\uc6a9\ud55c \uc774\uc57c\uae30\ub2e4."}, {"id": "qin-terracotta-army-faces-and-afterlife", "title": "\ubcd1\ub9c8\uc6a9 \u2014 \ud669\uc81c\uc758 \uad70\ub300\ub294 \uc65c \ub545\uc18d\uc5d0 \uc11c \uc788\uc744\uae4c", "summary": "\ud759\uc73c\ub85c \ub9cc\ub4e0 \ubcd1\uc0ac\uc758 \uc5bc\uad74\uacfc \ub300\uc5f4\uc744 \ubcf4\uba70 \uc9c4\uc758 \ud1b5\uc77c\uacfc \ud669\uc81c\uac00 \uafc8\uafbc \uc0ac\ud6c4 \uc138\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/qin-terracotta-army-faces-and-afterlife/index.html", "image": "../media/qin-terracotta-army-faces-and-afterlife.jpg", "alt": "\ubcd1\ub9c8\uc6a9\uc758 \ub113\uc740 \ub300\uc5f4\uacfc \ubcd1\uc0ac \uc5bc\uad74\u00b7\ubcf5\uc2dd\uc758 \ucc28\uc774\ub97c \ud568\uaed8 \ubcf4\uc5ec \uc8fc\ub294 \ub450 \uc0ac\uc9c4", "text": "\ubcd1\ub9c8\uc6a9 \u2014 \ud669\uc81c\uc758 \uad70\ub300\ub294 \uc65c \ub545\uc18d\uc5d0 \uc11c \uc788\uc744\uae4c \uc9c4\uc2dc\ud669\uc758 \ubb34\ub364 \uacc1\uc5d0\uc11c \ub9cc\ub098\ub294 \ud759\uc73c\ub85c \ub9cc\ub4e0 \uc81c\uad6d \ud759\uc73c\ub85c \ub9cc\ub4e0 \ubcd1\uc0ac\uc758 \uc5bc\uad74\uacfc \ub300\uc5f4\uc744 \ubcf4\uba70 \uc9c4\uc758 \ud1b5\uc77c\uacfc \ud669\uc81c\uac00 \uafc8\uafbc \uc0ac\ud6c4 \uc138\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ubc15\ubb3c\uad00 \uc0ac\uc9c4 \uc18d \ubcd1\uc0ac\ub4e4\uc740 \ub180\ub784 \ub9cc\ud07c \uc870\uc6a9\ud558\ub2e4. \ub204\uad70\uac00\ub294 \uc55e\uc744 \ubcf4\uace0, \ub204\uad70\uac00\ub294 \uace0\uac1c\ub97c \uc870\uae08 \ub3cc\ub9b0 \ub4ef\ud558\ub2e4. \uac19\uc740 \ub300\uc5f4\uc5d0 \uc11c \uc788\uc9c0\ub9cc \uc5bc\uad74\uacfc \uc637\uc758 \uc138\ubd80\ub294 \uc11c\ub85c \ub2e4\ub974\ub2e4. \uadf8\ub7f0\ub370 \uc774\ub4e4\uc740 \uc0b4\uc544\uc11c \ud589\uc9c4\ud55c \uad70\ub300\uac00 \uc544\ub2c8\ub2e4. \ud669\uc81c\uc758 \ubb34\ub364 \uacc1\uc5d0 \ubb3b\ud614\ub358 \ud759\uc73c\ub85c \ub9cc\ub4e0 \ubcd1\uc0ac\ub4e4\uc774\ub2e4. \uc911\uad6d \uc2dc\uc548\uc758 \ubcd1\ub9c8\uc6a9\uc744 \ubcfc \ub54c \uac00\uc7a5 \uba3c\uc800 \ub5a0\uc624\ub974\ub294 \uc9c8\ubb38\uc740 \uaddc\ubaa8\uc5d0 \uad00\ud55c \uac83\uc77c \uc218 \uc788\ub2e4. \uc5bc\ub9c8\ub098 \ub9ce\uc774 \ub9cc\ub4e4\uc5c8\uc744\uae4c. \ud558\uc9c0\ub9cc \ud55c \uac78\uc74c \ub354 \ub4e4\uc5b4\uac00\uba74 \ub2e4\ub978 \uc9c8\ubb38\uc774 \uc0dd\uae34\ub2e4. \ud1b5\uc77c\uc744 \uc774\ub8ec \ud669\uc81c\uc5d0\uac8c\ub294 \uc8fd\uc740 \ub4a4\uc5d0\ub3c4 \uad70\ub300\uac00 \ud544\uc694\ud588\ub358 \uac83\uc77c\uae4c. \uae30\uc6d0\uc804 3\uc138\uae30 \uc911\uad6d\uc5d0\ub294 \uc624\ub798 \ub2e4\ud22c\uc5b4 \uc628 \uc5ec\ub7ec \ub098\ub77c\uac00 \uc788\uc5c8\ub2e4. \uadf8 \uacbd\uc7c1\uc5d0\uc11c \uc2b9\ub9ac\ud55c \uc9c4\uc758 \uad70\uc8fc\uac00 \uc9c4\uc2dc\ud669\uc774\ub2e4. \uadf8\ub294 \uc55e\uc120 \uc655\ub4e4\uacfc \ub2e4\ub978 \uc9c0\uc704\ub97c \ub4dc\ub7ec\ub0b4\ub294 \ud669\uc81c\ub77c\ub294 \uc774\ub984\uc73c\ub85c \ub113\uc5b4\uc9c4 \uc601\uc5ed\uc744 \ub2e4\uc2a4\ub838\ub2e4. \ubcd1\ub9c8\uc6a9\uc740 \uc774 \ud1b5\uc77c\uc758 \uc5ed\uc0ac\uc640 \ub5a8\uc5b4\uc838 \uc788\ub294 \uc7a5\uc2dd\ud488\uc774 \uc544\ub2c8\ub2e4. \uc804\uc7c1\uc744 \ub05d\ub0c8\ub2e4\ub294 \ub9d0\ub9cc\uc73c\ub85c \ud1b5\uc77c\uc758 \ud48d\uacbd\uc744 \ub2e4 \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc9c0\uc5ed\uc744 \ud558\ub098\uc758 \uba85\ub839 \uccb4\uacc4\ub85c \ubb36\uace0, \uc0ac\ub78c\uacfc \ubb3c\uc790\ub97c \uc6c0\uc9c1\uc774\uba70, \ud1b5\uce58\uc790\uc758 \uad8c\uc704\ub97c \ubcf4\uc774\uac8c \ud574\uc57c \ud588\ub2e4. \ub545\uc18d\uc758 \uac00\uc9c0\ub7f0\ud55c \ub300\uc5f4\uc740 \uadf8\ub7f0 \uc81c\uad6d\uc758 \uc9c8\uc11c\ub97c \ucd95\uc18c\ud574 \ub193\uc740 \uc7a5\uba74\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uc0ac\uc9c4\uc744 \uba40\ub9ac\uc11c \ubcf4\uba74 \ube44\uc2b7\ud55c \ud615\uc0c1\uc774 \ub05d\uc5c6\uc774 \ubc18\ubcf5\ub418\ub294 \ub4ef\ud558\ub2e4. \uac00\uae4c\uc774 \ubcf4\uba74 \uc218\uc5fc\uacfc \uba38\ub9ac \ubaa8\uc591, \uc637\uc758 \ud45c\ud604, \uc5bc\uad74\uc758 \uc0dd\uae40\uc0c8\uac00 \ub2ec\ub77c\uc9c4\ub2e4. OpenStax \uad50\uc7ac\ub3c4 \uc774\ub7ec\ud55c \uc791\uc740 \ucc28\uc774\ub97c \ubcd1\ub9c8\uc6a9\uc758 \ud2b9\uc9d5\uc73c\ub85c \uc9da\ub294\ub2e4. \uc804\uccb4\ub97c \ubcfc \ub54c\uc640 \ud55c \uc0ac\ub78c\uc744 \ubcfc \ub54c\uc758 \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c0\ub294 \uc774\uc720\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \uc5bc\uad74\uc744 \uc2e4\uc81c \ubcd1\uc0ac \ud55c \uba85\uc529\uc758 \ucd08\uc0c1\uc73c\ub85c \ud655\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2ee\uc544 \ubcf4\uc778\ub2e4\ub294 \uac10\uc0c1\uacfc \ub204\uad6c\ub97c \ubcf8\ub5a0 \ub9cc\ub4e4\uc5c8\ub294\uc9c0\uc5d0 \ub300\ud55c \uc99d\uac70\ub294 \ub2e4\ub974\ub2e4. \uc774\ub984\uc744 \ubaa8\ub974\ub294 \uc5bc\uad74\uc744 \ubc14\ub77c\ubcf4\ub418, \uadf8 \ube48\uc790\ub9ac\ub97c \uadf8\ub7f4\ub4ef\ud55c \uc778\ubb3c \uc774\uc57c\uae30\ub85c \ucc44\uc6b0\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc774 \uc720\ubb3c\uc744 \ub354 \uc624\ub798 \ubcf4\uac8c \ud55c\ub2e4. \ubcd1\ub9c8\uc6a9\uc740 \ubb34\ub364\uc744 \ub458\ub7ec\uc2fc \uc138\uacc4\uc758 \uc77c\ubd80\ub2e4. \uc0b4\uc544 \uc788\ub294 \ub3d9\uc548 \ub204\ub9b0 \uad8c\ub825\uacfc \uc9c8\uc11c\uac00 \uc8fd\uc74c \ub4a4\uc5d0\ub3c4 \uc774\uc5b4\uc9c0\uae30\ub97c \ubc14\ub77c\ub294 \uc0dd\uac01\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uad70\ub300\ub77c\ub294 \ud615\uc2dd\uc740 \ud669\uc81c\uac00 \uc790\uae30 \uc9c0\uc704\ub97c \uc5b4\ub5bb\uac8c \ud45c\ud604\ud558\ub824 \ud588\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \uac15\ub825\ud55c \uc120\ud0dd\uc774\uc5c8\ub2e4. \uc624\ub298\uc758 \uad00\ub78c\uac1d\uc740 \uc0ac\ud6c4 \uc138\uacc4\ub97c \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ubbff\uc9c0 \uc54a\uc544\ub3c4 \uc774 \uaddc\ubaa8\uc5d0 \uc555\ub3c4\ub420 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uac70\ub300\ud55c \uc720\ubb3c\uc774 \ub0a8\uc558\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8 \uc2e0\uc559\uc758 \ub0b4\uc6a9\uc774 \uc2e4\uc81c\ub85c \uc774\ub8e8\uc5b4\uc84c\ub2e4\ub294 \uc8fc\uc7a5\uc740 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc6b0\ub9ac\uac00 \ub9cc\ub098\ub294 \uac83\uc740 \uc8fd\uc74c \ub108\uba38\uc758 \uc99d\uac70\uac00 \uc544\ub2c8\ub77c, \uc8fd\uc74c\uc744 \uc900\ube44\ud55c \uc0ac\ub78c\ub4e4\uc758 \ud754\uc801\uc774\ub2e4. \uc774 \uad70\ub300\ub97c \ud669\uc81c\uc758 \uc791\ud488\uc774\ub77c\uace0\ub9cc \ubd80\ub974\uba74 \uc774\uc0c1\ud55c \uc77c\uc774 \uc0dd\uae34\ub2e4. \ub9cc\ub4e4\ub77c\uace0 \uba85\ub839\ud55c \uc0ac\ub78c\uc740 \ubcf4\uc774\ub294\ub370, \ud759\uc744 \ub2e4\ub8e8\uace0 \ud615\uc0c1\uc744 \uc138\uc6b4 \uc0ac\ub78c\ub4e4\uc740 \uc2dc\uc57c\uc5d0\uc11c \uc0ac\ub77c\uc9c4\ub2e4. \uaddc\ubaa8\uac00 \ucee4\uc9c8\uc218\ub85d \uc7ac\ub8cc\uc640 \uc219\ub828, \uc6b4\ubc18\uacfc \uc791\uc5c5\uc744 \uc870\uc9c1\ud558\ub294 \ub2a5\ub825\ub3c4 \ud544\uc694\ud588\uc744 \uac83\uc774\ub2e4. \uc720\ubb3c\uc744 \uac10\uc0c1\ud560 \ub54c \ubaa8\ub4e0 \uc81c\uc791\uc790\uc758 \uc774\ub984\uc744 \uc54c \uc218\ub294 \uc5c6\ub2e4. \uadf8\ub798\ub3c4 \uc2dc\uc120\uc744 \ubc14\uafb8\ub294 \uac83\uc740 \uac00\ub2a5\ud558\ub2e4. \uc5b4\ub290 \uc190\uc774 \uc637\uc758 \uc8fc\ub984\uc744 \ub9cc\ub4e4\uc5c8\uc744\uae4c, \ub204\uac00 \ubcd1\uc0ac\uc758 \uc5bc\uad74\uc744 \ub9c8\ubb34\ub9ac\ud588\uc744\uae4c. \uc815\ud655\ud788 \ub2f5\ud558\uc9c0 \ubabb\ud558\ub294 \uc9c8\ubb38\ub3c4 \ud669\uc81c\ub9cc\uc73c\ub85c \uac00\ub4dd\ud588\ub358 \ud654\uba74\uc5d0 \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc744 \ubd88\ub7ec\ub4e4\uc778\ub2e4. \ubcd1\ub9c8\uc6a9\uc774 \ub110\ub9ac \uc54c\ub824\uc9c4 \uacc4\uae30\ub294 1970\ub144\ub300\uc758 \ubc1c\uacac\uacfc \uc774\uc5b4\uc9c4 \ubc1c\uad74\uc774\uc5c8\ub2e4. \uc624\ub7ab\ub3d9\uc548 \ub545\uc18d\uc5d0 \uc788\ub358 \ud615\uc0c1\ub4e4\uc774 \uc774\uc81c\ub294 \uc138\uacc4 \uc5ec\ub7ec \uacf3\uc758 \uad00\ub78c\uac1d\uc744 \ub9cc\ub09c\ub2e4. \ud669\uc81c\uc758 \ubb34\ub364\uc744 \uc704\ud55c \ubb3c\uac74\uc774 \uc5ed\uc0ac\uc640 \uc608\uc220\uc744 \uc0b4\ud3b4\ubcf4\ub294 \uc790\ub8cc\ub85c \uc0c8\ub85c\uc6b4 \uc0b6\uc744 \uc5bb\uc740 \uc148\uc774\ub2e4. \uc5ec\uae30\uc11c \ubc1c\uad74\uc744 \ub2e8\ubc88\uc5d0 \uc644\uc131\ub418\ub294 \ubcf4\ubb3c\ucc3e\uae30\ub85c \uc0dd\uac01\ud558\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \ubc1c\uacac\ub41c \uc704\uce58\uc640 \uc0c1\ud0dc\ub97c \uc0b4\ud53c\uace0, \uae68\uc9c4 \ubd80\ubd84\uc744 \uc774\ud574\ud558\uba70, \ub0a8\uc544 \uc788\ub294 \uc815\ubcf4\ub97c \ubcf4\uc874\ud574\uc57c \ud55c\ub2e4. \uc9c0\uae08 \ubcfc \uc218 \uc788\ub294 \ubcd1\uc0ac\uc758 \ubaa8\uc2b5 \ub4a4\uc5d0\ub3c4 \uc870\uc0ac\uc640 \ubcf4\uc874\uc758 \uc2dc\uac04\uc774 \uc788\ub2e4. \ud759\uc5d0\uc11c \ub098\uc654\ub2e4\uace0 \ubaa8\ub4e0 \uc774\uc57c\uae30\uac00 \uace7\ubc14\ub85c \uc77d\ud788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc9c4\uc740 \uc5ec\ub7ec \uc9c0\uc5ed\uc744 \ubb36\ub294 \uacfc\uc815\uc5d0\uc11c \ubc95\uacfc \ud589\uc815\uc758 \ud1b5\uc77c\uc744 \uac15\uc870\ud588\ub2e4. \ub113\uc5b4\uc9c4 \uc81c\uad6d\uc744 \uac19\uc740 \uae30\uc900\uc73c\ub85c \ub2e4\uc2a4\ub9ac\ub824\ub294 \ub178\ub825\uc740 \uac15\ub825\ud55c \ud1b5\uce58\uc640 \uc5f0\uacb0\ub418\uc5c8\ub2e4. \ubcd1\ub9c8\uc6a9\uc744 \ubcf4\uace0 \uae30\uc220\uc758 \uaddc\ubaa8\uc5d0 \uac10\ud0c4\ud558\uba74\uc11c\ub3c4 \uadf8 \uc2dc\ub300\ub97c \uc0b4\uae30 \uc88b\uc740 \uc2dc\ub300\uc600\ub2e4\uace0 \ubc14\ub85c \uacb0\ub860 \ub0b4\ub9b4 \uc218 \uc5c6\ub294 \uc774\uc720\ub2e4. \uc798 \uc870\uc9c1\ub41c \uad8c\ub825\uacfc \uadf8 \uc544\ub798 \uc0ac\ub78c\ub4e4\uc758 \uc0b6\uc740 \uac19\uc740 \ud3c9\uac00 \ud56d\ubaa9\uc774 \uc544\ub2c8\ub2e4. \uad50\uc7ac\ub294 \uac70\ub300\ud55c \uac74\uc124 \uc0ac\uc5c5\uc5d0 \ud3c9\ubbfc\ub4e4\uc758 \ub178\ub3d9\uc774 \uc138\uae08\uc774\ub098 \ubc95\uc801 \uc758\ubb34\uc758 \ud615\ud0dc\ub85c \ub3d9\uc6d0\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub610 \uc9c4\uc2dc\ud669\uc774 \uc8fd\uc740 \ub4a4 \uc81c\uad6d\uc774 \uc624\ub798 \uc720\uc9c0\ub418\uc9c0 \ubabb\ud588\ub2e4\ub294 \uc0ac\uc2e4\ub3c4 \ud568\uaed8 \ub2e4\ub8ec\ub2e4. \ub3cc\uacfc \ud759\uc73c\ub85c \ub0a8\uc740 \uac70\ub300\ud55c \uc9c8\uc11c\uac00 \uc815\uce58\uc758 \uc601\uc6d0\ud568\uc744 \ubcf4\uc7a5\ud558\uc9c0\ub294 \uc54a\uc558\ub2e4. \ubcd1\uc0ac\ub4e4\uc758 \ub300\uc5f4\uc740 \uc624\ub798 \uc0b4\uc544\ub0a8\uc558\uc9c0\ub9cc, \uadf8 \ub300\uc5f4\uc744 \uba85\ub839\ud55c \uc655\uc870\uc758 \uc2dc\uac04\uc740 \ud6e8\uc52c \uc9e7\uc558\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc804\uccb4 \ub300\uc5f4\uc744 \ubcf4\uc790. \uc774\uc5b4 \ud55c \ubcd1\uc0ac\uc758 \uc5bc\uad74\uacfc \uc637\uc744 \ucc9c\ucc9c\ud788 \uc0b4\ud3b4\ubcf4\uace0, \ub9c8\uc9c0\ub9c9\uc5d0 \ub2e4\uc2dc \ud070 \ud48d\uacbd\uc73c\ub85c \ub3cc\uc544\uc624\uba74 \uc88b\ub2e4. \uc138 \ubc88\uc758 \uc2dc\uc120\ub9cc\uc73c\ub85c\ub3c4 \ubcd1\ub9c8\uc6a9\uc740 \uc22b\uc790\ub85c \uc678\uc6b0\ub294 \uc720\uc801\uc5d0\uc11c \uc870\uae08 \ubc97\uc5b4\ub09c\ub2e4. \ubc18\ubcf5\ub418\ub294 \uc9c8\uc11c \uc18d\uc5d0\uc11c \uc11c\ub85c \ub2e4\ub978 \uc138\ubd80\uac00 \ubcf4\uc774\uae30 \uc2dc\uc791\ud55c\ub2e4. \uc9c4\uc2dc\ud669\uc740 \uac70\ub300\ud55c \uc81c\uad6d\uc744 \ub0a8\uae30\ub824 \ud588\ub2e4. \uadf8\ub7ec\ub098 \uc624\ub298\uc758 \uad00\ub78c\uac1d\uc744 \ubd99\ub4dc\ub294 \uac83\uc740 \ud759\uc73c\ub85c \ub9cc\ub4e0 \uc5bc\uad74 \ud558\ub098\uc77c \uc218\ub3c4 \uc788\ub2e4. \uc624\ub798\ub41c \uad8c\ub825\uc774 \uc5bc\ub9c8\ub098 \ucef8\ub294\uc9c0\uc640, \uadf8 \uad8c\ub825\uc744 \ud45c\ud604\ud558\ub294 \ub370 \uc5bc\ub9c8\ub098 \ub9ce\uc740 \uc190\uc774 \ud544\uc694\ud588\ub294\uc9c0\ub97c \ud568\uaed8 \uc0dd\uac01\ud558\uac8c \ud558\ub294 \uc5bc\uad74\uc774\ub2e4. \uc0ac\uc9c4\uc744 \ub098\ub780\ud788 \ubcf4\uba74 \ub113\uc740 \ub300\uc5f4\uacfc \uc791\uc740 \uc5bc\uad74\uc774 \uc11c\ub85c\ub97c \uc124\uba85\ud55c\ub2e4. \uaddc\ubaa8\ub9cc \ubcf4\uc544\uc11c\ub294 \ub193\ucce4\ub358 \uc138\ubd80\ub97c \ucc3e\uace0 \ub098\uba74 \ucc98\uc74c\uc758 \uc6c5\uc7a5\ud568\ub3c4 \uc870\uae08 \ub2e4\ub974\uac8c \ub290\uaef4\uc9c4\ub2e4. \ub450 \uac10\uc0c1\uc744 \ud568\uaed8 \ub0a8\uaca8 \ub450\uc5b4\ub3c4 \uc88b\ub2e4."}, {"id": "quebec-1608-river-and-fur-trade", "title": "\ud018\ubca1 1608 \u2014 \uac15\uac00\uc758 \uc791\uc740 \uac70\ucc98\ub294 \uc5b4\ub5bb\uac8c \uad50\uc5ed\uc758 \uc911\uc2ec\uc774 \ub418\uc5c8\uc744\uae4c", "summary": "\uac15\uac00\uc758 \ucc3d\uace0\uc640 \uac70\ucc98\uac00 \ubaa8\ud53c \uad50\uc5ed\u00b7\uc5ec\ub7ec \uacf5\ub3d9\uccb4\uc758 \uad00\uacc4\uc5d0 \uc5f0\uacb0\ub41c \uacfc\uc815\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/quebec-1608-river-and-fur-trade/index.html", "image": "../media/quebec-1608-river-and-fur-trade.png", "alt": "\uac15\uac00\uc758 \ubaa9\uc870 \uc815\ucc29\uc9c0\uc640 \ubc30, \uad50\uc5ed\ud558\ub294 \uc791\uc740 \uc778\ubb3c\ub4e4\uc744 \uadf8\ub9b0 \ucd08\uae30 \ud018\ubca1 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ud018\ubca1 1608 \u2014 \uac15\uac00\uc758 \uc791\uc740 \uac70\ucc98\ub294 \uc5b4\ub5bb\uac8c \uad50\uc5ed\uc758 \uc911\uc2ec\uc774 \ub418\uc5c8\uc744\uae4c \uc0f9\ud50c\ub7ad\uc758 \uac70\ucc98\uc640 \ubaa8\ud53c \uad50\uc5ed\uc73c\ub85c \uc0b4\ud53c\ub294 \uc138\uc778\ud2b8\ub85c\ub80c\uc2a4\uac15\uc758 \ub3c4\uc2dc \uac15\uac00\uc758 \ucc3d\uace0\uc640 \uac70\ucc98\uac00 \ubaa8\ud53c \uad50\uc5ed\u00b7\uc5ec\ub7ec \uacf5\ub3d9\uccb4\uc758 \uad00\uacc4\uc5d0 \uc5f0\uacb0\ub41c \uacfc\uc815\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ud070 \ub3c4\uc2dc\uc758 \uc2dc\uc791\uc744 \uc0b4\ud3b4\ubcf4\uba74 \ucc98\uc74c\uc5d0\ub294 \ucc3d\uace0\uc640 \uac70\ucc98, \ubb3c\uc790\ub97c \ub0b4\ub9b4 \uac15\uac00\uac00 \ubcf4\uc77c \ub54c\uac00 \uc788\ub2e4. \uc0ac\ubb88\uc5d8 \ub4dc \uc0f9\ud50c\ub7ad\uc774 1608\ub144 \ud504\ub791\uc2a4 \uc815\ucc29\uc9c0\ub97c \uc138\uc6b4 \ud018\ubca1\ub3c4 \uadf8\ub807\ub2e4. \uc138\uc778\ud2b8\ub85c\ub80c\uc2a4\uac15\uc758 \uc704\uce58\uc640 \uad50\uc5ed\uc758 \uac00\ub2a5\uc131, \uaca8\uc6b8\uc744 \uc0b4\uc544\ub0a8\ub294 \ubb38\uc81c\ub4e4\uc774 \uba3c \ubbf8\ub798\uc758 \ub3c4\uc2dc\ubcf4\ub2e4 \uba3c\uc800 \uc788\uc5c8\ub2e4. \uc774\uac83\uc744 \ud504\ub791\uc2a4\uc778\uc774 \ube48 \ub545\uc5d0 \ub3c4\uc2dc\ub97c \ubc1c\uba85\ud55c \uc774\uc57c\uae30\ub85c \uc77d\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uac15\uacfc \uc8fc\ubcc0 \uc9c0\uc5ed\uc5d0\ub294 \uc774\ubbf8 \uc6d0\uc8fc\ubbfc\uc758 \uc774\ub3d9\uacfc \uc0dd\ud65c, \uad50\uc5ed\uc758 \uad00\uacc4\uac00 \uc788\uc5c8\ub2e4. \uc0f9\ud50c\ub7ad\uc758 \uae30\ub85d\uacfc \ubaa8\ud53c \uad50\uc5ed\uc758 \ubc30\uacbd\uc744 \ud568\uaed8 \ubcf4\uba74 \uc791\uc740 \uac70\ucc98\uc758 \uc5ed\uc0ac\uac00 \ub354 \ub113\uc740 \uc0ac\ub78c\ub4e4\uc758 \ub9cc\ub0a8\uc73c\ub85c \uc774\uc5b4\uc9c4\ub2e4. \uc138\uc778\ud2b8\ub85c\ub80c\uc2a4\uac15\uc740 \ubc30\uac00 \ub4dc\ub098\ub4dc\ub294 \uacf5\uac04\uc774\uc790 \ub0b4\ub959\uc73c\ub85c \uc5f0\uacb0\ub418\ub294 \ud1b5\ub85c\uc600\ub2e4. \uac15\uac00\uc5d0 \uc815\ucc29\uc9c0\ub97c \ub9c8\ub828\ud558\ub294 \uc77c\uc740 \uc9d1 \uc9c0\uc744 \ub545\uc744 \uc5bb\ub294 \uac83 \uc774\uc0c1\uc744 \ub73b\ud588\ub2e4. \uc0ac\ub78c\uacfc \ubb3c\uc790\ub97c \uc5b4\ub290 \ubc29\ud5a5\uc73c\ub85c \ubcf4\ub0bc\uc9c0, \ub204\uac00 \uadf8 \uc774\ub3d9\uc744 \uad00\ub9ac\ud560\uc9c0\uc758 \ubb38\uc81c\uc640 \uc774\uc5b4\uc84c\ub2e4. \uc704\uce58 \uc790\uccb4\uac00 \uacbd\uc81c\uc801 \uac00\ub2a5\uc131\uc774\uc5c8\ub2e4. \uc624\ub298\uc758 \uad50\ud1b5 \uc9c0\ub3c4\ub97c \ub5a0\uc62c\ub824 \uac15\uc744 \ud48d\uacbd\uc73c\ub85c\ub9cc \ubcf4\uba74 \uc774 \uc911\uc694\uc131\uc774 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ub2f9\uc2dc \ubb3c\uae38\uc740 \uba3c \uac70\ub9ac\ub97c \uc787\ub294 \uc2e4\uc81c\uc758 \uae38\uc774\uc5c8\ub2e4. \ub3c4\uc2dc\ub294 \uae38\uc774 \ubaa8\uc774\uace0 \ubb3c\uc790\uac00 \uba38\ubb34\ub294 \uacf3\uc5d0\uc11c \uc131\uc7a5\ud560 \uc218 \uc788\uc5c8\ub2e4. \ud018\ubca1\uc758 \uc2dc\uc791\uc744 \uc77d\uc744 \ub54c\uc5d0\ub3c4 \uac74\ubb3c\ubcf4\ub2e4 \uba3c\uc800 \uac15\uc758 \ubc29\ud5a5\uc744 \ubcf4\ub294 \uac83\uc774 \uc88b\ub2e4. \uc0f9\ud50c\ub7ad\uc740 \uc801\ud569\ud55c \uc815\ucc29\uc9c0\ub97c \uc0b4\ud540 \ub4a4 \ub098\ubb34\ub97c \ubca0\uace0 \uac74\uc124\uc744 \uc2dc\uc791\ud55c \uacfc\uc815\uc744 \uae30\ub85d\ud588\ub2e4. \uc791\uc5c5\uc790\ub294 \ud310\uc790\ub97c \ucf1c\uace0 \ub545\uc744 \ud30c\uace0 \ub2e4\ub978 \uacf3\uc5d0\uc11c \ubb3c\uc790\ub97c \uac00\uc838\uc654\ub2e4. \uadf8\ub294 \ubcf4\uae09\ud488\uc744 \ube44\ub85c\ubd80\ud130 \uc9c0\ud0ac \ucc3d\uace0\ub97c \uba3c\uc800 \ub9c8\ub828\ud55c \uc77c\ub3c4 \uc124\uba85\ud55c\ub2e4. \uac70\ub300\ud55c \uacc4\ud68d\ubcf4\ub2e4 \uc2dd\ub7c9\uacfc \uc790\uc7ac\ub97c \ubcf4\uc874\ud558\ub294 \uc77c\uc774 \uae09\ud588\ub358 \uac83\uc774\ub2e4. \uc774\ub7f0 \uc138\ubd80\ub294 \ub3c4\uc2dc \uac74\uc124\uc744 \uc601\uc6c5 \ud55c \uc0ac\ub78c\uc758 \uacb0\ub2e8\uc73c\ub85c\ub9cc \uc124\uba85\ud558\ub294 \ubc29\uc2dd\uc744 \ubc14\uafbc\ub2e4. \uc7a5\uc18c\ub97c \uace0\ub978 \uc0ac\ub78c\uacfc \uc2e4\uc81c\ub85c \uc791\uc5c5\ud55c \uc0ac\ub78c, \ubcf4\uae09\uc744 \ub9e1\uc740 \uc0ac\ub78c\uc758 \uc77c\uc774 \ud568\uaed8 \ud544\uc694\ud588\ub2e4. \ud55c \uc0ac\ub78c\uc758 \uc774\ub984\uc73c\ub85c \uae30\uc5b5\ub418\ub294 \ucd9c\ubc1c\uc5d0\ub3c4 \uc5ec\ub7ec \uc885\ub958\uc758 \ub178\ub3d9\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ud504\ub791\uc2a4\uc758 \ubd81\uc544\uba54\ub9ac\uce74 \uc9c4\ucd9c\uc5d0\uc11c \ubaa8\ud53c\ub294 \uc911\uc694\ud55c \uc0c1\ud488\uc774\uc5c8\ub2e4. \uc720\ub7fd\uc758 \uc2dc\uc7a5\uc5d0\uc11c \uac12\uc774 \ub098\uac00\ub294 \ub3d9\ubb3c\uc758 \uac00\uc8fd\uc774 \ubc14\ub2e4 \uac74\ub108 \uad50\uc5ed\uc744 \uc774\ub04c\uc5c8\ub2e4. \uac15\uac00\uc758 \uc815\ucc29\uc9c0\ub294 \ubb3c\uac74\uc744 \ubaa8\uc73c\uace0 \uc62e\uae30\ub294 \uac70\uc810\uc774 \ub420 \uc218 \uc788\uc5c8\ub2e4. \uc791\uc544 \ubcf4\uc774\ub294 \uac74\ubb3c\uc774 \uba3c \uc18c\ube44\uc790\uc758 \uc695\ub9dd\uacfc \uc5f0\uacb0\ub41c \uac83\uc774\ub2e4. \ud558\uc9c0\ub9cc \uc815\ucc29\ubbfc\uc774 \uc2a4\uc2a4\ub85c \ubaa8\ub4e0 \uc9c0\uc5ed\uc744 \uc54c\uace0 \uc0ac\ub0e5\ud558\uace0 \uc6b4\uc1a1\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ud604\uc9c0\uc758 \ub545\uacfc \ubb3c\uae38\uc744 \uc544\ub294 \uc6d0\uc8fc\ubbfc \uacf5\ub3d9\uccb4\uc640\uc758 \uad00\uacc4\uac00 \uc911\uc694\ud588\ub2e4. \uc0c1\ud488\uc744 \uc5bb\ub294 \uc77c\uc740 \ub2e8\uc21c\ud788 \uc790\uc5f0 \uc18d\uc5d0\uc11c \ubb3c\uac74\uc744 \uaebc\ub0b4 \uc624\ub294 \uc77c\uc774 \uc544\ub2c8\ub77c \uc774\ubbf8 \uc874\uc7ac\ud558\ub358 \uc0ac\ub78c\ub4e4\uc758 \uc9c0\uc2dd\uacfc \uc774\ub3d9\ub9dd\uc5d0 \ub4e4\uc5b4\uac00\ub294 \uacfc\uc815\uc774\uc5c8\ub2e4. \uc11c\ub85c \ud544\uc694\ud55c \ubb3c\uac74\uc744 \uc8fc\uace0\ubc1b\ub294 \uad00\uacc4\uac00 \uc0dd\uacbc\ub2e4\uace0 \uc774\ud574\uad00\uacc4\uae4c\uc9c0 \ubaa8\ub450 \uac19\uc544\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud504\ub791\uc2a4\uc778\ub4e4\uacfc \uc6d0\uc8fc\ubbfc \uc9d1\ub2e8 \uc0ac\uc774\uc758 \ub3d9\ub9f9\uc740 \ub2e4\ub978 \uc9d1\ub2e8\uacfc\uc758 \uacbd\uc7c1\u00b7\uac08\ub4f1\uc5d0\ub3c4 \uc5f0\uacb0\ub418\uc5c8\ub2e4. \uc0f9\ud50c\ub7ad\uc758 \uae30\ub85d\uc5d0\ub294 \uad50\uc5ed\ubfd0 \uc544\ub2c8\ub77c \uc804\ud22c\uc758 \uc7a5\uba74\ub3c4 \ub4f1\uc7a5\ud55c\ub2e4. \ubb3c\uac74\uc744 \uc0ac\uace0\ud30c\ub294 \uc77c\uacfc \uc815\uce58\uac00 \uba40\ub9ac \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\uc558\ub2e4. \uc2dd\ubbfc\uc9c0 \uad00\uacc4\ub97c \uc5b8\uc81c\ub098 \uc6b0\ud638\uc801\uc778 \ub9cc\ub0a8\uc774\ub098 \uc5b8\uc81c\ub098 \uac19\uc740 \ud615\ud0dc\uc758 \ucda9\ub3cc\ub85c\ub9cc \uc124\uba85\ud558\uba74 \uad6c\uccb4\uc131\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \ub204\uac00 \ub204\uad6c\uc640 \uc5b4\ub5a4 \uc870\uac74\uc5d0\uc11c \uad00\uacc4\ub97c \ub9fa\uc5c8\ub294\uc9c0 \ubd10\uc57c \ud55c\ub2e4. \ub610\ud55c \uc6d0\uc8fc\ubbfc\uc744 \ud558\ub098\uc758 \uc0dd\uac01\uc73c\ub85c \uc6c0\uc9c1\uc774\ub294 \ub2e8\uc77c \uc9d1\ub2e8\ucc98\ub7fc \ubd80\ub974\uc9c0 \uc54a\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \ucd08\uae30 \uc815\ucc29\uc9c0\ub294 \ucd94\uc704\uc640 \uc2dd\ub7c9, \uc9c8\ubcd1\uc758 \ubb38\uc81c\ub97c \uacaa\uc5c8\ub2e4. \uac15\uc744 \ud1b5\ud574 \ub4e4\uc5b4\uc628 \uc0ac\ub78c\ub4e4\uc774 \uadf8 \uac15\uac00\uc5d0\uc11c \uaca8\uc6b8\uc744 \ubcf4\ub0b4\ub294 \uc77c\uc740 \ub3c4\ucc29 \uc790\uccb4\uc640 \ub2e4\ub978 \ub09c\uad00\uc774\uc5c8\ub2e4. \ubb34\uc5ed\uc758 \uac00\ub2a5\uc131\uc744 \ubc1c\uacac\ud588\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc548\uc815\uc801\uc778 \uc0dd\ud65c\uc774 \uace7\ubc14\ub85c \ub9cc\ub4e4\uc5b4\uc9c0\uc9c0\ub294 \uc54a\uc558\ub2e4. \ubab8\uc774 \uacac\ub51c \uc870\uac74\uc744 \ub9c8\ub828\ud574\uc57c \ud588\ub2e4. \uc774\ub7f0 \uc0dd\ud65c\uc758 \uc81c\uc57d\uc744 \uc54c\uba74 \uc815\ucc29\uc9c0\uc758 \ucc3d\uace0\uc640 \uac74\ubb3c \ubc30\uce58\ub3c4 \ub2e4\ub974\uac8c \ubcf4\uc778\ub2e4. \ud654\ub824\ud55c \ub3c4\uc2dc \uacc4\ud68d\ubcf4\ub2e4 \ubcf4\uae09\uc744 \uc9c0\ud0a4\uace0 \uc77c\uc0c1\uc744 \uc720\uc9c0\ud558\ub294 \uae30\ub2a5\uc774 \uba3c\uc800\uc600\ub2e4. \uc624\ub298\uc758 \uac70\ub9ac \uc544\ub798\uc5d0\ub294 \uc774\ub7f0 \uc791\uace0 \ubd88\uc548\uc815\ud55c \uac70\ucc98\uc758 \uc2dc\uac04\uc774 \uc788\ub2e4. \ub3c4\uc2dc\uac00 \uc131\uc7a5\ud55c \uacb0\uacfc\ub9cc \ubcf4\uba74 \uc78a\uae30 \uc26c\uc6b4 \ubd80\ubd84\uc774\ub2e4. \uc0f9\ud50c\ub7ad\uc740 \uc7a5\uc18c\uc640 \uc9c0\ub3c4, \uac74\uc124 \uacfc\uc815\uc744 \uc790\uc138\ud788 \ub0a8\uacbc\ub2e4. \ub355\ubd84\uc5d0 \ucd08\uae30 \uc815\ucc29\uc758 \uad6c\uccb4\uc801\uc778 \ubaa8\uc2b5\uc744 \uc54c \uc218 \uc788\uc9c0\ub9cc \uadf8\uc758 \uae00\uc740 \ud504\ub791\uc2a4 \uc9c4\ucd9c\uc744 \uc774\ub048 \uc0ac\ub78c\uc758 \uae30\ub85d\uc774\ub2e4. \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\uc5d0 \ub300\ud55c \ud3c9\uac00\uc640 \uc790\uc2e0\uc758 \ubaa9\uc801\uc774 \uc11c\uc220\uc5d0 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4. \uc798 \uc801\ud78c \uae30\ub85d\ub3c4 \ud558\ub098\uc758 \uc785\uc7a5\uc5d0\uc11c \uc4f0\uc600\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2ec\ub77c\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uc9c0\ub3c4\uc5d0 \ubd99\uc778 \uc774\ub984\uacfc \uc124\uba85\uc744 \uc77d\uc744 \ub54c\uc5d0\ub3c4 \uadf8\uacf3\uc744 \uba3c\uc800 \uc774\uc6a9\ud558\ub358 \uc0ac\ub78c\ub4e4\uc774 \ubb34\uc5c7\uc774\ub77c\uace0 \ubd80\ub974\uace0 \uc5b4\ub5bb\uac8c \uae30\uc5b5\ud588\ub294\uc9c0\uc758 \uc9c8\ubb38\uc774 \ub0a8\ub294\ub2e4. \uc720\ub7fd\uc778\uc758 \uae30\ub85d\uc5d0\uc11c \ucc98\uc74c \ub098\ud0c0\ub0ac\ub2e4\uace0 \uadf8 \uc774\uc804\uc5d0 \uc7a5\uc18c\uc758 \uc5ed\uc0ac\uac00 \uc5c6\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc790\ub8cc\uac00 \ud48d\ubd80\ud55c \ucabd\uc758 \ubaa9\uc18c\ub9ac\ub9cc \uc804\uccb4\ub85c \ubc1b\uc544\ub4e4\uc774\uc9c0 \uc54a\ub294 \ud0dc\ub3c4\uac00 \ud544\uc694\ud558\ub2e4. 1608\ub144\uc740 \ud018\ubca1\uc758 \ud504\ub791\uc2a4 \uc815\ucc29\uc9c0\ub97c \uc124\uba85\ud558\ub294 \uc911\uc694\ud55c \ucd9c\ubc1c\uc810\uc774\ub2e4. \uadf8\ub7ec\ub098 \uc624\ub298\uc758 \uce90\ub098\ub2e4\uac00 \uadf8\ub54c \uc9c0\uae08\uc758 \ubaa8\uc2b5\uc73c\ub85c \ud0c4\uc0dd\ud588\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc655\uc2e4\uacfc \ud68c\uc0ac, \uad50\uc5ed\ub9dd\uacfc \uc5ec\ub7ec \uacf5\ub3d9\uccb4\uac00 \uc5bd\ud78c \ub274\ud504\ub791\uc2a4\uc758 \uc2dc\uac04\uacfc \ud604\ub300\uc758 \uad6d\uac00\ub294 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \uc0f9\ud50c\ub7ad\uc758 \uc9c0\ub3c4 \uc124\uba85\uc5d0\ub294 \uc815\uc6d0\uacfc \uc791\uc740 \ubb3c\uae38, \ub18d\uc0ac\uc640 \uc2dc\uc124\uc5d0 \uc774\uc6a9\ud560 \ub9cc\ud55c \uacf3\ub3c4 \ud45c\uc2dc\ub41c\ub2e4. \uc0c8 \uc7a5\uc18c\ub97c \ubcf4\ub294 \ub208\uc774 \uc774\ubbf8 \uc0dd\ud65c\uacfc \uc791\uc5c5\uc758 \ud544\uc694\ub97c \ub530\ub77c \uc6c0\uc9c1\uc600\uc74c\uc744 \uc54c \uc218 \uc788\ub2e4. \uc9c0\ub3c4\ub97c \ud48d\uacbd\uc758 \ucd95\uc18c\ud310\ubcf4\ub2e4 \uc55e\uc73c\ub85c \ud560 \uc77c\uc744 \uc815\ub9ac\ud558\ub294 \ub3c4\uad6c\ub85c \uc77d\uc744 \uc218\ub3c4 \uc788\ub2e4. \uac15\uac00\uc758 \uc791\uc740 \uac70\ucc98\ub97c \ub5a0\uc62c\ub9ac\uba70 \ub3c4\uc2dc\ub97c \ubcf4\uba74 \ucc3d\uace0\uc640 \ubc30, \ubaa8\ud53c\uc640 \uc2dd\ub7c9, \uc11c\ub85c \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc774 \ud55c\ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ud018\ubca1\uc758 \uae30\uc6d0\uc740 \ub3cc\ub85c \ub41c \uac74\ubb3c\uc758 \uc5f0\ub300\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uac15\uc744 \ub530\ub77c \ubb34\uc5c7\uc774 \uc624\uac14\uace0 \uadf8 \uc774\ub3d9\uc744 \ud1b5\ud574 \uc5b4\ub5a4 \uad00\uacc4\uac00 \uc0dd\uacbc\ub294\uc9c0 \uc77d\ub294 \uc77c\uc5d0\uc11c \ub3c4\uc2dc\uc758 \uc5ed\uc0ac\uac00 \ub113\uc5b4\uc9c4\ub2e4."}, {"id": "rio-1808-court-crosses-atlantic", "title": "1808\ub144 \ub9ac\uc6b0 \u2014 \uc720\ub7fd\uc758 \uc655\uc2e4\uc774 \uc2dd\ubbfc\uc9c0\ub85c \uac74\ub108\uc624\ub2e4", "summary": "\ud3ec\ub974\ud22c\uac08 \uad81\uc815\uc758 \ub300\uc11c\uc591 \uc774\ub3d9\uc774 \ud56d\uad6c\u00b7\uae30\uad00\u00b7\ub3c4\uc2dc\uc758 \uc704\uc0c1\uc744 \ubc14\uafb8\ub2e4\uc744 \uc774\uc57c\uae30\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/rio-1808-court-crosses-atlantic/index.html", "image": "../media/rio-1808-court-crosses-atlantic.png", "alt": "19\uc138\uae30 \ucd08 \ubc30\uc640 \uc9d0, \uc5ec\ub7ec \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc778 \ub9ac\uc6b0 \ud56d\uad6c \uc0c1\uc0c1 \uc0bd\ud654", "text": "1808\ub144 \ub9ac\uc6b0 \u2014 \uc720\ub7fd\uc758 \uc655\uc2e4\uc774 \uc2dd\ubbfc\uc9c0\ub85c \uac74\ub108\uc624\ub2e4 \ud3ec\ub974\ud22c\uac08 \uad81\uc815\uc758 \ub300\uc11c\uc591 \uc774\ub3d9\uc774 \ud56d\uad6c\u00b7\uae30\uad00\u00b7\ub3c4\uc2dc\uc758 \uc704\uc0c1\uc744 \ubc14\uafb8\ub2e4 \ud3ec\ub974\ud22c\uac08 \uad81\uc815\uc758 \ub300\uc11c\uc591 \uc774\ub3d9\uc774 \ud56d\uad6c\u00b7\uae30\uad00\u00b7\ub3c4\uc2dc\uc758 \uc704\uc0c1\uc744 \ubc14\uafb8\ub2e4\uc744 \uc774\uc57c\uae30\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc2dd\ubbfc\uc9c0\ub97c \ub2e4\uc2a4\ub9ac\ub294 \uc655\uc740 \ubcf4\ud1b5 \ubc14\ub2e4 \uac74\ub108 \ubcf8\uad6d\uc5d0 \uc788\ub2e4\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \uadf8\ub7f0\ub370 1808\ub144 \ud3ec\ub974\ud22c\uac08 \uc655\uc2e4\uc740 \ub300\uc11c\uc591\uc744 \uac74\ub108 \ube0c\ub77c\uc9c8\uc758 \ub9ac\uc6b0\ub370\uc790\ub124\uc774\ub8e8\uc5d0 \uc790\ub9ac \uc7a1\uc558\ub2e4. \uc2dd\ubbfc\uc9c0\uac00 \uc655\uc2e4\uc758 \uba85\ub839\uc744 \ubc1b\ub294 \uacf3\uc5d0\uc11c \uc655\uc2e4\uc774 \uc9c1\uc811 \uba38\ubb34\ub294 \uacf3\uc73c\ub85c \ub2ec\ub77c\uc9c4 \uac83\uc774\ub2e4. \uc774 \uc774\ub3d9\uc740 \ud654\ub824\ud55c \uc774\uc0ac \uc774\uc57c\uae30\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uc720\ub7fd\uc758 \uc804\uc7c1\uc774 \ud56d\uad6c\uc640 \ubb34\uc5ed, \ud589\uc815\uacfc \uc77c\uc0c1\uc744 \ubc14\uafb8\uc5c8\ub2e4. \uc655\uc2e4\uc774 \uc654\uc73c\ub2c8 \ubaa8\ub450\uc5d0\uac8c \uc88b\uc740 \uc77c\uc774 \uc0dd\uacbc\ub2e4\uace0\ub3c4 \ud560 \uc218 \uc5c6\ub2e4. \ub9ac\uc6b0\uc758 \ubcc0\ud654\ub97c \ub530\ub77c\uac00\uba74 \uc81c\uad6d\uc758 \uc911\uc2ec\uc774 \uc6c0\uc9c1\uc77c \ub54c \uc5b4\ub5a4 \uae30\ud68c\uc640 \ubd80\ub2f4\uc774 \ud568\uaed8 \uc0dd\uae30\ub294\uc9c0 \ubcf4\uc778\ub2e4. \ud3ec\ub974\ud22c\uac08 \uc655\uc2e4\uc774 \ube0c\ub77c\uc9c8\ub85c \uac74\ub108\uac04 \ubc30\uacbd\uc5d0\ub294 \ub098\ud3f4\ub808\uc639 \uc2dc\ub300\uc758 \uc720\ub7fd \uc804\uc7c1\uacfc \uce68\uacf5\uc758 \uc704\ud611\uc774 \uc788\uc5c8\ub2e4. \uc655\uc2e4\uc758 \uc774\ub3d9\uc740 \uad00\uad11\uc774\ub098 \uc2dd\ubbfc\uc9c0 \uc21c\ubc29\uc774 \uc544\ub2c8\ub77c \ud1b5\uce58 \uccb4\uc81c\ub97c \uc9c0\ud0a4\uae30 \uc704\ud55c \uc120\ud0dd\uc774\uc5c8\ub2e4. \ubc14\ub2e4\uac00 \uba40\ub2e4\uace0 \ud574\uc11c \uc544\uba54\ub9ac\uce74\uac00 \uc720\ub7fd\uc758 \uc804\uc7c1\uc5d0\uc11c \ub5a8\uc5b4\uc838 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774 \uc0ac\uac74\uc744 \ubcf4\uba74 \uc81c\uad6d\uc774 \ub2e8\uc21c\ud788 \ud55c \uc218\ub3c4\uc640 \uc5ec\ub7ec \uc8fc\ubcc0 \uc9c0\uc5ed\uc73c\ub85c \uace0\uc815\ub418\uc5b4 \uc788\uc9c0 \uc54a\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c \uc218 \uc788\ub2e4. \uad70\uc0ac\uc801 \uc555\ub825\uc774 \uac00\ud574\uc9c0\uc790 \ud1b5\uce58\uc758 \uc911\uc2ec\uc744 \uc62e\uae30\ub294 \ubc29\uc548\uc774 \uac00\ub2a5\ud574\uc84c\ub2e4. \ubc30\ub294 \uc0ac\ub78c\uacfc \ubb3c\uac74\ubfd0 \uc544\ub2c8\ub77c \uad81\uc815\uc758 \uae30\ub2a5\uacfc \uad8c\uc704\ub3c4 \uc2e4\uc5b4 \ub0a0\ub790\ub2e4. \uc655\uc2e4 \uc77c\ud589\uc740 \ube0c\ub77c\uc9c8 \ubd81\ub3d9\ubd80\uc758 \uc0b4\ubc14\ub3c4\ub974\uc5d0 \ub4e4\ub978 \ub4a4 \ub0a8\ub3d9\ubd80\uc758 \ub9ac\uc6b0\ub370\uc790\ub124\uc774\ub8e8\ub85c \ud5a5\ud588\ub2e4. \uae34 \uc774\ub3d9\uc758 \ub05d\uc5d0 \ub3c4\ucc29\ud55c \uacf3\uc740 \ud145 \ube48 \ub545\uc774 \uc544\ub2c8\ub77c \uc774\ubbf8 \ud56d\uad6c\uc640 \uc0c1\uc5c5, \ud589\uc815\uc758 \uae30\ub2a5\uc774 \uc788\ub358 \ub3c4\uc2dc\uc600\ub2e4. \uc0c8\ub85c\uc6b4 \uad81\uc815\uc740 \uadf8 \uae30\uc874 \ub3c4\uc2dc \uc704\uc5d0 \ub4e4\uc5b4\uc654\ub2e4. \uc655\uc2e4\uc758 \ub3c4\ucc29\uc744 \ubcf8 \uc0ac\ub78c\ub4e4\uc758 \uacbd\ud5d8\ub3c4 \uac19\uc9c0 \uc54a\uc558\uc744 \uac83\uc774\ub2e4. \uc655\uc2e4\uacfc \uac00\uae4c\uc6cc\uc9c8 \uae30\ud68c\ub97c \uc5bb\uc740 \uc0ac\ub78c, \ubb3c\uc790\uc640 \uacf5\uac04\uc744 \ub9c8\ub828\ud574\uc57c \ud588\ub358 \uc0ac\ub78c, \uc6d0\ub798\uc758 \uc77c\uc0c1\uc744 \uc774\uc5b4 \uac00\ub358 \uc0ac\ub78c\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \ud55c \ubc88\uc758 \ub3c4\ucc29\uc744 \ub3c4\uc2dc \uc804\uccb4\uac00 \uac19\uc740 \ub9c8\uc74c\uc73c\ub85c \ub9de\uc774\ud588\ub2e4\uace0 \uc0c1\uc0c1\ud558\uae30\ubcf4\ub2e4 \uc11c\ub85c \ub2e4\ub978 \uc790\ub9ac\ub97c \ub5a0\uc62c\ub9ac\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \uc655\uc2e4\uc774 \ube0c\ub77c\uc9c8\uc5d0 \uba38\ubb3c\uae30 \uc2dc\uc791\ud55c \uc2dc\uae30\uc758 \uc911\uc694\ud55c \ubcc0\ud654\ub294 \ud56d\uad6c \uac1c\ubc29\uc774\uc5c8\ub2e4. \ud3ec\ub974\ud22c\uac08\uc744 \uc911\uc2ec\uc73c\ub85c \ubb36\uc5ec \uc788\ub358 \uc2dd\ubbfc\uc9c0 \uad50\uc5ed\uc758 \uc870\uac74\uc774 \ub2ec\ub77c\uc84c\uace0 \ud2b9\ud788 \uc601\uad6d\uacfc\uc758 \uad00\uacc4\uac00 \uc911\uc694\ud574\uc84c\ub2e4. \uc655\uc2e4\uc758 \uac70\ucc98\ub97c \uc62e\uae30\ub294 \uc77c\uacfc \ubb34\uc5ed \uaddc\uce59\uc744 \ubc14\uafb8\ub294 \uc77c\uc774 \uc11c\ub85c \uc5f0\uacb0\ub41c \uac83\uc774\ub2e4. \ud56d\uad6c \uac1c\ubc29\uc774\ub77c\ub294 \ub9d0\uc740 \ucd94\uc0c1\uc801\uc774\uc9c0\ub9cc \uc2e4\uc81c\ub85c\ub294 \ub204\uac00 \ubb3c\uac74\uc744 \ub4e4\uc5ec\uc624\uace0 \ub204\uad6c\uc5d0\uac8c \ud314 \uc218 \uc788\ub294\uc9c0\uc758 \ubb38\uc81c\ub2e4. \uc0c8\ub85c\uc6b4 \uac70\ub798 \uc0c1\ub300\uac00 \uc0dd\uae30\uba74 \uc774\uc775\uc744 \uc5bb\ub294 \uc0ac\ub78c\uacfc \uacbd\uc7c1\uc774 \ucee4\uc9c0\ub294 \uc0ac\ub78c\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654\ub294 \uad81\uc804 \uc548\uc758 \ud589\uc0ac\ubfd0 \uc544\ub2c8\ub77c \ubd80\ub450\uc640 \ucc3d\uace0, \uc0c1\uc778\uc758 \uacc4\uc0b0\uc5d0\uc11c\ub3c4 \uc77c\uc5b4\ub0ac\ub2e4. \ube0c\ub77c\uc9c8\uc758 \uc81c\uc870\uc5c5\uc744 \uc81c\ud55c\ud558\ub358 \uc870\uce58\uac00 \ud480\ub9ac\uace0 \uc0c8\ub85c\uc6b4 \uacbd\uc81c \uae30\uad00\uc774 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4. \ube0c\ub77c\uc9c8 \uc740\ud589\uc758 \uc124\ub9bd\ub3c4 \uc774 \uc2dc\uae30\uc758 \ubcc0\ud654 \uac00\uc6b4\ub370 \ud558\ub098\ub2e4. \uc655\uc2e4\uc744 \uc720\uc9c0\ud558\uace0 \uac70\ub798\ub97c \uc6b4\uc601\ud558\ub824\uba74 \ub2e8\uc21c\ud788 \uc655\uc871\uc758 \uc219\uc18c\ub9cc \ub9c8\ub828\ud574\uc11c\ub294 \ubd80\uc871\ud588\ub2e4. \ub3c8\uacfc \ud589\uc815\uc744 \uc6c0\uc9c1\uc774\ub294 \uccb4\uacc4\uac00 \ud544\uc694\ud588\ub2e4. \uc81c\ub3c4\uc758 \uc774\ub984\ub9cc \ub098\uc5f4\ud558\uba74 \uc774 \ubcc0\ud654\uac00 \uba40\uac8c \ub290\uaef4\uc9c4\ub2e4. \ud558\uc9c0\ub9cc \uc774\uc804\uc5d0\ub294 \ubcf8\uad6d\uc758 \uc774\uc775\uc5d0 \ub9de\ucdb0 \uc81c\ud55c\ud558\ub358 \ud65c\ub3d9\uc744 \ube0c\ub77c\uc9c8 \ud604\uc9c0\uc758 \ud1b5\uce58\uc640 \uacbd\uc81c\ub97c \uc704\ud574 \ub2e4\uc2dc \uc870\uc815\ud588\ub2e4\ub294 \ub73b\uc73c\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \uc2dd\ubbfc\uc9c0\ub97c \ubc14\ub77c\ubcf4\ub294 \uc655\uc2e4\uc758 \ud544\uc694\uac00 \ub2ec\ub77c\uc9c0\uc790 \ud5c8\uc6a9\ub418\ub294 \uc77c\uacfc \ud544\uc694\ud55c \uae30\uad00\ub3c4 \ub2ec\ub77c\uc84c\ub2e4. \uad81\uc815\uc758 \uc874\uc7ac\ub294 \ubb38\ud654\uc640 \uad50\uc721 \uae30\uad00\uc758 \ud655\ucda9\uacfc \uc5f0\uacb0\ub418\uc5c8\ub2e4. \ucc45\uacfc \uc9c0\uc2dd\uc744 \ubaa8\uc73c\ub294 \uc2dc\uc124, \uc0ac\ub78c\uc744 \uac00\ub974\uce58\uace0 \ub3cc\ubcf4\ub294 \uae30\uad00\uc740 \ub3c4\uc2dc\uc758 \uae30\ub2a5\uc744 \ub113\ud614\ub2e4. \ub2e4\ub9cc \uae30\uad00\uc774 \ub298\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uace7\ubc14\ub85c \ubaa8\ub4e0 \uc8fc\ubbfc\uc758 \uc0dd\ud65c\uc774 \uac19\uc740 \uc815\ub3c4\ub85c \ub098\uc544\uc84c\ub2e4\ub294 \ub73b\uc73c\ub85c \ubc14\uafb8\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc655\uc2e4\uacfc \uad00\ub8cc \uc870\uc9c1, \uc804\uc7c1\uc744 \uc720\uc9c0\ud558\ub294 \ub370\uc5d0\ub294 \ube44\uc6a9\uc774 \ub4e4\uc5c8\ub2e4. \uc774\ub97c \uac10\ub2f9\ud558\uae30 \uc704\ud55c \uc138\uae08\uc740 \ub610 \ub2e4\ub978 \ubd80\ub2f4\uc774\uc5c8\ub2e4. \uc0c8\ub85c\uc6b4 \ubb38\ud654 \uc2dc\uc124\uc774 \uc0dd\uacbc\ub2e4\ub294 \ubc18\uac00\uc6b4 \uc18c\uc2dd\uacfc \ub298\uc5b4\ub09c \uc9c0\ucd9c\uc758 \ubb34\uac8c\ub294 \uac19\uc740 \ub3c4\uc2dc \uc548\uc5d0 \ud568\uaed8 \uc874\uc7ac\ud560 \uc218 \uc788\ub2e4. \ubc1c\uc804\uc758 \uc5ed\uc0ac\ub294 \ubb34\uc5c7\uc744 \uc5bb\uc5c8\ub294\uc9c0\uc640 \ub204\uac00 \ube44\uc6a9\uc744 \ub0c8\ub294\uc9c0\ub97c \ud568\uaed8 \ubb3c\uc5b4\uc57c \ud55c\ub2e4. \ube0c\ub77c\uc9c8\uc758 \ud1b5\uce58\uac00 \ub9ac\uc6b0\ub97c \uc911\uc2ec\uc73c\ub85c \ubaa8\uc774\uba74\uc11c \ub3c4\uc2dc\uc758 \uc911\uc694\uc131\uc740 \ucee4\uc84c\ub2e4. \uba40\ub9ac \ub5a8\uc5b4\uc9c4 \uc9c0\uc5ed\uc744 \ud558\ub098\uc758 \ud589\uc815\uc801 \ud750\ub984\uc73c\ub85c \ubb36\ub294 \ud798\uc774 \uc0dd\uacbc\uc9c0\ub9cc, \ub2e4\ub978 \uc9c0\uc5ed\uc5d0\uc11c \ubcf4\uba74 \uacb0\uc815\uc774 \ud2b9\uc815 \ub3c4\uc2dc\uc5d0 \uc9d1\uc911\ub418\ub294 \ubcc0\ud654\uc774\uae30\ub3c4 \ud588\ub2e4. \uc218\ub3c4\uc758 \uc131\uc7a5\uc740 \uc804\uccb4\uc758 \uade0\ub4f1\ud55c \uc131\uc7a5\uacfc \uac19\uc740 \ub9d0\uc774 \uc544\ub2c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc655\uc2e4\uc758 \uc774\ub3d9\ub9cc\uc73c\ub85c \uc774\ud6c4\uc758 \ub3c5\ub9bd \uacfc\uc815\uc774 \ubaa8\ub450 \uc124\uba85\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc9c0\uc5ed\uc758 \uc774\ud574\uad00\uacc4\uc640 \uc815\uce58\uc801 \uac08\ub4f1\uc740 \uacc4\uc18d \ub0a8\uc558\ub2e4. \ub2e4\ub9cc \uc655\uc2e4\uc774 \uc544\uba54\ub9ac\uce74\uc5d0\uc11c \uc9c1\uc811 \ud1b5\uce58\ud55c \uacbd\ud5d8\uc740 \ubcf8\uad6d\uacfc \uc2dd\ubbfc\uc9c0\ub77c\ub294 \uae30\uc874 \uad00\uacc4\ub97c \uc774\uc804\uacfc \ub611\uac19\uc774 \uc720\uc9c0\ud558\uae30 \uc5b4\ub835\uac8c \ub9cc\ub4e0 \uc911\uc694\ud55c \uc870\uac74\uc774\uc5c8\ub2e4. 1808\ub144\uc744 \ub098\ud3f4\ub808\uc639\uc758 \uc804\uc7c1 \uc5f0\ud45c\uc5d0\uc11c\ub9cc \ubcf4\uba74 \uc655\uc2e4\uc758 \uc774\ub3d9\uc740 \uc9e7\uc740 \ud55c \uc904\ub85c \uc9c0\ub098\uac04\ub2e4. \ub9ac\uc6b0\uc758 \ub208\uc73c\ub85c \ubcf4\uba74 \ud56d\uad6c\uc758 \uaddc\uce59\uacfc \uae30\uad00, \ub3c4\uc2dc\uc758 \uc704\uc0c1\uacfc \uc8fc\ubbfc\uc758 \ubd80\ub2f4\uc774 \ubc14\ub00c\ub294 \ud070 \uc0ac\uac74\uc774\ub2e4. \uac19\uc740 \uc5ed\uc0ac\ub97c \uc5b4\ub290 \uc7a5\uc18c\uc5d0\uc11c \ubc14\ub77c\ubcf4\ub290\ub0d0\uc5d0 \ub530\ub77c \uc911\uc2ec \uc7a5\uba74\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc774 \uc0ac\uac74\uc744 \uc77d\uc73c\uba70 \uad81\uc815\uc758 \uc774\ub3d9\uacfc \uc8fc\ubbfc\uc758 \uc774\ub3d9\uc744 \uad6c\ubcc4\ud574 \ubcfc \ud544\uc694\ub3c4 \uc788\ub2e4. \uad8c\ub825\uc774 \uc62e\uaca8 \uac04\ub2e4\ub294 \uac83\uc740 \ub2e8\uc21c\ud788 \uc0ac\ub78c\uc774 \ub9ce\uc774 \ub3c4\ucc29\ud55c\ub2e4\ub294 \ub73b\ubcf4\ub2e4 \ub113\ub2e4. \uacb0\uc815\uad8c\uacfc \ub3c8\uc758 \ud750\ub984, \ub3c4\uc2dc \uc0ac\uc774\uc758 \uc704\uacc4\uac00 \uc0c8\ub85c\uc6b4 \ubc29\ud5a5\uc73c\ub85c \ub9de\ucdb0\uc9c0\ub294 \ubcc0\ud654\ub2e4. \ub9ac\uc6b0\ub97c \ud574\ubcc0\uacfc \ucd95\uc81c\uc758 \ub3c4\uc2dc\ub85c\ub9cc \uae30\uc5b5\ud588\ub2e4\uba74 \uc774 \uc624\ub798\ub41c \uad81\uc815\uc758 \uc2dc\uac04\uc744 \ub354\ud574 \ubcf4\uc790. \ub3c4\uc2dc\ub294 \uc720\uba85\ud55c \ud48d\uacbd \uc774\uc804\uc5d0\ub3c4 \uc138\uacc4\uc758 \uc804\uc7c1\uacfc \ubb34\uc5ed\uc774 \ub9cc\ub098\ub294 \uacf3\uc774\uc5c8\ub2e4. \uc720\ub7fd\uc5d0\uc11c \uc2dc\uc791\ub41c \uc704\uae30\uac00 \ubc14\ub2e4 \uac74\ub108 \ub3c4\uc2dc\uc758 \uc77c\uc0c1\uc744 \ubc14\uafb8\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub9ac\uc6b0\uc758 \uc5ed\uc0ac\ub97c \ud55c\uce35 \uc785\uccb4\uc801\uc73c\ub85c \ub9cc\ub4e0\ub2e4."}, {"id": "rome-arena-crowd", "title": "\ucf5c\ub85c\uc138\uc6c0\uc5d0\uc11c\ub294 \ubb34\ub300\ub9cc\ud07c \uad00\uc911\uc11d\ub3c4 \ud06c\ub2e4", "summary": "\uc720\uba85\ud55c \uc720\uc801\uc744 \uacbd\uae30\uc7a5\uacfc \uad00\uc911\uc758 \uc790\ub9ac\ub77c\ub294 \uad00\uc810\uc5d0\uc11c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/rome-arena-crowd/index.html", "image": "../media/rome-arena-crowd.jpg", "alt": "\uc774\ud0c8\ub9ac\uc544 \ub85c\ub9c8 \ucf5c\ub85c\uc138\uc6c0 \ub0b4\ubd80\uc758 \uc2e4\uc81c \uc0ac\uc9c4. \uc5ec\ub7ec \uce35\uc758 \ubcbd\uacfc \ud604\uc7ac \ub0a8\uc740 \ub0b4\ubd80 \uad6c\uc870\uac00 \ubcf4\uc785\ub2c8\ub2e4.", "text": "\ucf5c\ub85c\uc138\uc6c0\uc5d0\uc11c\ub294 \ubb34\ub300\ub9cc\ud07c \uad00\uc911\uc11d\ub3c4 \ud06c\ub2e4 \ub85c\ub9c8\uc758 \ub3cc \uac74\ubb3c\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc774\ub358 \uc790\ub9ac\ub97c \ubcf4\uae30 \uc720\uba85\ud55c \uc720\uc801\uc744 \uacbd\uae30\uc7a5\uacfc \uad00\uc911\uc758 \uc790\ub9ac\ub77c\ub294 \uad00\uc810\uc5d0\uc11c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ub85c\ub9c8\uc758 \ucf5c\ub85c\uc138\uc6c0 \uc0ac\uc9c4\uc744 \ubcf4\uba74 \ub3cc\ub85c \uc774\uc5b4\uc9c4 \ub465\uadfc \ubcbd\uacfc \uc5ec\ub7ec \uce35\uc758 \uacf5\uac04\uc774 \uba3c\uc800 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ub108\ubb34 \uc720\uba85\ud55c \uac74\ubb3c\uc774\ub77c \uc774\ub984\ub9cc \ud655\uc778\ud558\uace0 \uc9c0\ub098\uce58\uae30 \uc27d\ub2e4. \uc774\ubc88\uc5d0\ub294 \uac00\uc6b4\ub370\uc758 \ubb34\ub300\ubcf4\ub2e4 \uadf8 \uc8fc\ubcc0\uc758 \uad00\uc911\uc11d\uc744 \uba3c\uc800 \ubcf4\uc790. \uc774 \uac74\ubb3c\uc740 \ube44\uc5b4 \uc788\ub294 \ub3cc \uad6c\uc870\ubb3c\ub85c \uc2dc\uc791\ud55c \uac83\uc774 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc5ec \ubb34\uc5b8\uac00\ub97c \ud568\uaed8 \ubcf4\ub358 \uc7a5\uc18c\uc600\ub2e4. \uc0ac\uc9c4 \uc18d \ube48 \uacf5\uac04\uc5d0 \uad00\uc911\uc744 \ub5a0\uc62c\ub9ac\uba74 \uac74\ubb3c\uc758 \ud06c\uae30\uac00 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ub290\uaef4\uc9c4\ub2e4. OpenStax \uad50\uc7ac\ub294 \uace0\ub300 \ub85c\ub9c8\uc758 \uc774\uacf3\uc5d0 \uc218\ub9cc \uba85\uc774 \ubaa8\uc5ec \uacbd\uae30\ub97c \ubcf4\uc558\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ucf5c\ub85c\uc138\uc6c0\uc758 \uc774\uc57c\uae30\ub294 \ubb34\ub300 \uc704\uc5d0\uc11c \ubb34\uc5c7\uc774 \uc77c\uc5b4\ub0ac\ub294\uc9c0\ubfd0 \uc544\ub2c8\ub77c, \uadf8 \uc7a5\uba74\uc744 \ubcf4\uae30 \uc704\ud574 \uc5bc\ub9c8\ub098 \ub9ce\uc740 \uc0ac\ub78c\uc774 \ubaa8\uc600\ub294\uc9c0\uc640\ub3c4 \uad00\ub828\ub41c\ub2e4. \ud55c \uc0ac\ub78c\uc774 \uadf8\ub9bc \uc55e\uc5d0 \uc11c\ub294 \uac83\uacfc \ucee4\ub2e4\ub780 \uad00\uc911\uc11d\uc5d0\uc11c \uad70\uc911\uacfc \ud568\uaed8 \uad00\ub78c\ud558\ub294 \uacbd\ud5d8\uc740 \ub2e4\ub974\ub2e4. \uac19\uc740 \uc7a5\uba74\uc744 \ud5a5\ud574 \uc2dc\uc120\uc774 \ubaa8\uc774\ub3c4\ub85d \uacf5\uac04\uc744 \ub9c8\ub828\ud55c\ub2e4\ub294 \uac83\uc774 \uc774 \uac74\ubb3c\uc744 \ubcf4\ub294 \ub610 \ud558\ub098\uc758 \uc2e4\ub9c8\ub9ac\ub2e4. \uad50\uc7ac\ub294 \ucf5c\ub85c\uc138\uc6c0\uc774 \uace0\ub300 \uc0ac\ud68c\uc5d0\uc11c \ub9e1\uc558\ub358 \uc5ed\ud560\uc744 \uc624\ub298\ub0a0\uc758 \ud070 \uc2a4\ud3ec\uce20 \uacbd\uae30\uc7a5\uacfc \ube44\uad50\ud55c\ub2e4. \ub2e8\uc21c\ud788 \uad6c\uacbd\uac70\ub9ac\ub97c \uc81c\uacf5\ud558\ub294 \ub370 \uadf8\uce58\uc9c0 \uc54a\uace0 \uc0ac\ub78c\ub4e4\uc774 \uc18c\uc18d\uac10\uacfc \uc815\uccb4\uc131\uc744 \ub290\ub07c\ub294 \uc790\ub9ac\uac00 \ub420 \uc218 \uc788\ub2e4\ub294 \uad00\uc810\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub2f9\uc2dc\uc758 \uacbd\uae30\uc640 \uc624\ub298\ub0a0\uc758 \uc2a4\ud3ec\uce20\uac00 \ub611\uac19\uc558\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uad50\uc7ac\ub294 \uac80\ud22c\uc0ac\uc640 \ub3d9\ubb3c\uc774 \ub4f1\uc7a5\ud558\ub294 \ud3ed\ub825\uc801\uc778 \uad6c\uacbd\uac70\ub9ac\ub3c4 \uc124\uba85\ud55c\ub2e4. \ubaa8\uc5ec \ubcf4\ub294 \uacf5\uac04\uc774\ub77c\ub294 \ub2ee\uc740 \uc810\uacfc, \uadf8 \uc548\uc758 \uc11c\ub85c \ub2e4\ub978 \ub0b4\uc6a9\uc744 \ub098\ub204\uc5b4 \ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \uc0ac\uc9c4\uc758 \uc911\uc2ec\uc5d0\ub294 \ud55c\ub54c \ub9ce\uc740 \uc2dc\uc120\uc774 \ubaa8\uc600\uc744 \uacf5\uac04\uc774 \uc788\ub2e4. \uadf8 \ub458\ub808\ub97c \uc5ec\ub7ec \uce35\uc758 \uc790\ub9ac\uac00 \ub458\ub7ec\uc2fc\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \ubcf4\uace0\uc790 \ud55c \uc77c\uc774 \uac00\uc6b4\ub370\uc5d0\uc11c \ubc8c\uc5b4\uc9c0\uace0 \uad00\uc911\uc740 \uadf8 \uc8fc\ubcc0\uc5d0\uc11c \ubc14\ub77c\ubcf4\ub294 \ubc30\uce58\ub2e4. \uac74\ucd95\uc740 \uad6c\uacbd\uac70\ub9ac\uc758 \ubc30\uacbd\ub9cc\uc774 \uc544\ub2c8\ub77c, \uc11c\ub85c \ub5a8\uc5b4\uc9c4 \ub9ce\uc740 \uc0ac\ub78c\uc774 \ud55c \ub300\uc0c1\uc744 \ud5a5\ud558\uac8c \ud558\ub294 \uc7a5\uce58\uc774\uae30\ub3c4 \ud588\ub2e4. \uc774\uac83\uc744 \uc774\ud574\ud558\ub824\uace0 \uc5c6\uc5b4\uc9c4 \uac74\ucd95 \ubd80\ubd84\uc744 \uc0c1\uc0c1\uc73c\ub85c \ubaa8\ub450 \ubcf5\uc6d0\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud604\uc7ac \uc0ac\uc9c4\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\ub294 \uc911\uc2ec\uacfc \ub458\ub808, \ub192\uc774\uc758 \uad00\uacc4\ub9cc \ub530\ub77c\uac00\ub3c4 \ub41c\ub2e4. \uac19\uc740 \uc790\ub9ac\uc5d0 \uc549\uc544\ub3c4 \ubb34\ub300\ub97c \ub0b4\ub824\ub2e4\ubcf4\ub294 \uac01\ub3c4\uc640 \uc606 \uc0ac\ub78c\uc744 \ub290\ub07c\ub294 \ubc29\uc2dd\uc740 \ub2ec\ub790\uc744 \uac83\uc774\ub2e4. \uacf5\uac04\uc758 \ud06c\uae30\uac00 \uad00\ub78c\uc758 \uacbd\ud5d8\uacfc \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ub418\ub294\uc9c0 \ubb3c\uc5b4\ubcfc \uc218 \uc788\ub2e4. \uc9d1\uc5d0\uc11c \ud63c\uc790 \uacbd\uae30\ub97c \ubcf4\ub294 \uc21c\uac04\uacfc \ud070 \uacbd\uae30\uc7a5\uc5d0\uc11c \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc18c\ub9ac\ub97c \ub4e4\uc73c\uba70 \ubcf4\ub294 \uc21c\uac04\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc7a5\uba74\uc758 \ub0b4\uc6a9\uc774 \ube44\uc2b7\ud574\ub3c4 \uae34\uc7a5\uacfc \ud765\ubd84\uc774 \uc804\ud574\uc9c0\ub294 \ubc29\uc2dd\uc740 \ub2e4\ub974\ub2e4. \uad50\uc7ac\uac00 \uc624\ub298\uc758 \uc2a4\ud3ec\uce20 \uacf5\uac04\uc744 \ub098\ub780\ud788 \ub193\ub294 \uc774\uc720\ub3c4 \uc774\ub7f0 \uc9d1\ub2e8 \uacbd\ud5d8\uc744 \uc0dd\uac01\ud558\uac8c \ud558\ub824\ub294 \ub370 \uc788\ub2e4. \ub2e4\ub9cc \uc774\uac83\uc740 \ube44\uad50\ub97c \uc704\ud55c \ucd9c\ubc1c\uc810\uc774\uc9c0 \uace0\ub300\uc778\uc758 \uac10\uc815\uc744 \uadf8\ub300\ub85c \uc548\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc5ec\ub7ec \uc0ac\ub78c\uc774 \uac19\uc740 \ub54c \uac19\uc740 \uacf3\uc5d0 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc18c\uc18d\uac10\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \ubc18\ub300\ub85c \ub204\uac00 \uadf8 \uc790\ub9ac\uc5d0 \ud3ec\ud568\ub418\uace0 \uc5b4\ub5a4 \uc704\uce58\ub97c \ucc28\uc9c0\ud558\ub294\uc9c0\ub3c4 \uc9c8\ubb38\ud558\uac8c \ud55c\ub2e4. \uad70\uc911\uc774 \ud55c \ub369\uc5b4\ub9ac\ucc98\ub7fc \ubcf4\uc77c \ub54c\uc5d0\ub3c4 \uac1c\ubcc4 \uad00\ub78c\uc790\uc758 \uacbd\ud5d8\uae4c\uc9c0 \ubaa8\ub450 \uac19\uc558\ub2e4\uace0 \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uac74\ucd95\uc758 \uc804\uccb4 \ubaa8\uc2b5\uacfc \uadf8 \uc548\uc758 \uc11c\ub85c \ub2e4\ub978 \uc790\ub9ac\ub97c \ud568\uaed8 \ub5a0\uc62c\ub9b4 \ud544\uc694\uac00 \uc788\ub2e4. \uac80\ud22c\uc0ac\uc640 \ub3d9\ubb3c\uc774 \ub4f1\uc7a5\ud558\ub294 \uad6c\uacbd\uac70\ub9ac\ub97c \uc624\ub298\uc758 \uc2a4\ud3ec\uce20\uc640 \uac19\uc740 \uc624\ub77d\uc73c\ub85c\ub9cc \uc815\ub9ac\ud558\uba74 \uc911\uc694\ud55c \ucc28\uc774\uac00 \uc0ac\ub77c\uc9c4\ub2e4. \uc0ac\ub78c\uacfc \ub3d9\ubb3c\uc758 \uace0\ud1b5\uc774 \uad00\ub78c\uc758 \ub300\uc0c1\uc774 \ub418\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ub9ce\uc740 \uc0ac\ub78c\uc774 \ubaa8\uc600\ub2e4\ub294 \uaddc\ubaa8\uc640 \uadf8\uac83\uc744 \ubcfc \ub9cc\ud55c \uc77c\ub85c \ubc1b\uc544\ub4e4\uc600\ub2e4\ub294 \ud310\ub2e8\uc740 \uc11c\ub85c \ub2e4\ub978 \ubb38\uc81c\ub2e4. \uadf8\ub798\uc11c \ucf5c\ub85c\uc138\uc6c0\uc740 \uac74\ucd95 \uae30\uc220\uc5d0 \ub300\ud55c \uac10\ud0c4\uacfc \uad00\ub78c \ubb38\ud654\uc5d0 \ub300\ud55c \uc9c8\ubb38\uc744 \ub3d9\uc2dc\uc5d0 \ubd80\ub978\ub2e4. \ud070 \uacf5\uac04\uc744 \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \uc131\ucde8\ub9cc\uc73c\ub85c \uadf8 \uc548\uc5d0\uc11c \uc77c\uc5b4\ub09c \uc77c\uc774 \uc815\ub2f9\ud574\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc720\uc801\uc744 \uc77d\ub294 \uc990\uac70\uc6c0\uc740 \uacfc\uac70\ub97c \ubb34\uc870\uac74 \ucc2c\uc591\ud558\ub294 \ub370 \uc788\uc9c0 \uc54a\ub2e4. \uc624\ub298\uacfc \ub2ee\uc740 \uc810\uc744 \uc54c\uc544\ubcf4\uba74\uc11c \ub0af\uc124\uace0 \ubd88\ud3b8\ud55c \ucc28\uc774\ub3c4 \ub193\uce58\uc9c0 \uc54a\ub294 \ub370 \uc788\ub2e4. \ud604\uc7ac\uc758 \ub0b4\ubd80 \uc0ac\uc9c4\uc740 \uc0ac\ub78c\ub4e4\uc774 \ub5a0\ub09c \ub4a4 \ub0a8\uc740 \uc0c1\ud0dc\ub97c \ubcf4\uc5ec \uc900\ub2e4. \ubb34\ub108\uc9c4 \ubd80\ubd84\uc774\ub098 \ub4dc\ub7ec\ub09c \uad6c\uc870\ub97c \ubaa8\ub450 \uc6d0\ub798 \ubb34\ub300\uc758 \ubaa8\uc2b5\uc774\ub77c\uace0 \uc77d\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc2dc\uac04\uc774 \uc9c0\ub098\uba70 \ub2ec\ub77c\uc9c4 \uac74\ubb3c\uc758 \ud604\uc7ac\uc640 \uacfc\uac70\uc758 \uc4f0\uc784\uc744 \ub098\ub204\uc5b4 \ubcf4\ub294 \uc77c\uc774 \ud544\uc694\ud558\ub2e4. \uc790\ub8cc \uc0ac\uc9c4\uc774 \uc720\uc6a9\ud55c \uac83\uc740 \uc5c6\ub294 \ubd80\ubd84\uc744 \ub9c8\uc74c\ub300\ub85c \ucc44\uc6b0\uc9c0 \uc54a\uace0 \ub0a8\uc740 \uac83\uc744 \uc0b4\ud53c\uac8c \ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \ub3cc\uc758 \ud070 \ub369\uc5b4\ub9ac\uc5d0\uc11c \uc0ac\ub78c\uc758 \uc6c0\uc9c1\uc784\uc744 \ub5a0\uc62c\ub9ac\uba74 \uac74\ubb3c\uc774 \uc870\uae08 \ub35c \ucd94\uc0c1\uc801\uc73c\ub85c \ub290\uaef4\uc9c4\ub2e4. \uc5b4\ub514\ub85c \ub4e4\uc5b4\uac00 \uc5b4\ub290 \ucabd\uc744 \ubcf4\uc558\uc744\uc9c0, \ub9ce\uc740 \uc2dc\uc120\uc774 \uac19\uc740 \uc21c\uac04 \uc5b4\ub514\uc5d0 \ubaa8\uc600\uc744\uc9c0\ub97c \uc9c8\ubb38\ud574 \ubcf4\uc790. \uc815\ud655\ud55c \uc88c\uc11d \ubc30\uce58\ub098 \uc2e0\ubd84\ubcc4 \uad6c\uc5ed\uc758 \uc124\uba85\uc740 \ubcc4\ub3c4 \uc5ed\uc0ac \uc790\ub8cc\uac00 \ud544\uc694\ud55c \ubb38\uc81c\ub85c \ub0a8\uae30\ub418, \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc5ec \ubcf4\ub294 \uc7a5\uc18c\ub77c\ub294 \uae30\ubcf8 \uc131\uaca9\uc740 \uc0ac\uc9c4 \uc18d \uacf5\uac04\uc5d0\uc11c\ub3c4 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \ucf5c\ub85c\uc138\uc6c0 \ub0b4\ubd80\uc758 \uc2e4\uc81c \uc0ac\uc9c4\uc774\ub2e4. \uc624\ub298 \ub0a8\uc740 \ubaa8\uc2b5\uc744 \uace0\ub300\uc758 \uc644\uc804\ud55c \ubaa8\uc2b5\uc73c\ub85c \ubc14\uafb8\uc5b4 \uadf8\ub9ac\uc9c0\ub294 \uc54a\uc558\ub2e4. \ud604\uc7ac \ubcf4\uc774\ub294 \uc790\ub9ac\uc640 \uc0ac\ub77c\uc9c4 \ubd80\ubd84\uc744 \uc788\ub294 \uadf8\ub300\ub85c \ub9cc\ub098\uae30 \uc704\ud574\uc11c\ub2e4. \uc720\uba85\ud55c \uc720\uc801 \uc55e\uc5d0\uc11c\ub294 \uc5b8\uc81c \uc9c0\uc5c8\ub294\uc9c0\uc640 \uc5bc\ub9c8\ub098 \ud070\uc9c0\ub97c \uba3c\uc800 \ubb3b\uac8c \ub41c\ub2e4. \uadf8 \uc606\uc5d0 \ub204\uac00 \uc5b4\ub514\uc5d0\uc11c \ubb34\uc5c7\uc744 \ubcf4\uc558\uc744\uae4c\ub77c\ub294 \uc9c8\ubb38\ub3c4 \ub193\uc544 \ubcf4\uc790. \ub85c\ub9c8\uc758 \ub3cc \uac74\ubb3c\uc740 \uad00\uc911\uc774 \ub5a0\ub09c \ub4a4\uc5d0\ub3c4 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc600\ub358 \uc790\ub9ac\ub97c \ub0a8\uaca8 \ub193\uace0 \uc788\ub2e4."}, {"id": "rosetta-stone-three-scripts", "title": "\ub85c\uc81c\ud0c0\uc11d \u2014 \uc65c \uac19\uc740 \ub9d0\uc744 \uc138 \uac00\uc9c0 \ubb38\uc790\ub85c \uc0c8\uacbc\uc744\uae4c", "summary": "\ub450 \uc5b8\uc5b4\u00b7\uc138 \ubb38\uc790\ub85c \ub0a8\uc740 \ube44\ubb38\uc744 \ud1b5\ud574 \uc774\ub984\uacfc \ubc18\ubcf5\uc744 \ube44\uad50\ud558\uba70 \ubb38\uc790\ub97c \uc77d\uc5b4 \uac04 \uacfc\uc815\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/rosetta-stone-three-scripts/index.html", "image": "../media/rosetta-stone-three-scripts.png", "alt": "\uae68\uc9c4 \uac00\uc7a5\uc790\ub9ac\uc640 \uc138 \ubb38\uc790 \uad6c\uc5ed\uc774 \ubcf4\uc774\ub294 \ub85c\uc81c\ud0c0\uc11d\uc758 \uc61b \ube44\ubb38 \ub3c4\ud310.", "text": "\ub85c\uc81c\ud0c0\uc11d \u2014 \uc65c \uac19\uc740 \ub9d0\uc744 \uc138 \uac00\uc9c0 \ubb38\uc790\ub85c \uc0c8\uacbc\uc744\uae4c \ub3cc \ud55c \uc870\uac01\uc5d0\uc11c \uc2dc\uc791\ub41c \ube44\uad50\uc640 \ud574\ub3c5\uc758 \uae34 \uc2dc\uac04 \ub450 \uc5b8\uc5b4\u00b7\uc138 \ubb38\uc790\ub85c \ub0a8\uc740 \ube44\ubb38\uc744 \ud1b5\ud574 \uc774\ub984\uacfc \ubc18\ubcf5\uc744 \ube44\uad50\ud558\uba70 \ubb38\uc790\ub97c \uc77d\uc5b4 \uac04 \uacfc\uc815\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uae00\uc790\uac00 \ube7d\ube7d\ud55c \ub3cc \ud55c \uc870\uac01\uc774 \uc788\ub2e4. \ub9e8 \uc704\uc640 \uac00\uc6b4\ub370, \uc544\ub798\ucabd\uc758 \uae00\uc790 \ubaa8\uc591\uc774 \uc11c\ub85c \ub2e4\ub974\ub2e4. \uc138 \uc885\ub958\uc758 \ube44\ubc00\uc744 \ub530\ub85c \uc801\uc740 \uac83 \uac19\uc9c0\ub9cc, \ub85c\uc81c\ud0c0\uc11d\uc758 \uc911\uc694\ud55c \uc810\uc740 \uc11c\ub85c \uad00\uacc4\uc788\ub294 \ub0b4\uc6a9\uc744 \ub2e4\ub978 \ubb38\uc790\ub85c \uc0c8\uacbc\ub2e4\ub294 \ub370 \uc788\ub2e4. \uc77d\uc744 \uc218 \uc788\ub358 \ubd80\ubd84\uc774 \uc77d\uae30 \uc5b4\ub824\uc6e0\ub358 \ubd80\ubd84\uc744 \uc54c\uc544\ubcf4\ub294 \uc2e4\ub9c8\ub9ac\uac00 \ub418\uc5c8\ub2e4. \ub3cc \uc790\uccb4\uac00 \uace0\ub300 \uc774\uc9d1\ud2b8\uc758 \ubaa8\ub4e0 \ube44\ubc00\uc744 \ud55c\uaebc\ubc88\uc5d0 \uc124\uba85\ud574 \uc900 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5ec\ub7ec \uc0ac\ub78c\uc774 \uc0ac\ubcf8\uacfc \ub2e4\ub978 \uc790\ub8cc\ub97c \ube44\uad50\ud558\uba70 \uc624\ub7ab\ub3d9\uc548 \uc5f0\uad6c\ud588\ub2e4. \ud574\ub3c5\uc758 \uc774\uc57c\uae30\ub97c \ucc9c\uc7ac\uac00 \ub2e8\ubc88\uc5d0 \uc554\ud638\ub97c \ud47c \uc7a5\uba74\ubcf4\ub2e4, \ubc18\ubcf5\ub418\ub294 \ubaa8\uc591\uc5d0 \uc9c8\ubb38\uc744 \ub358\uc9c0\ub294 \uacfc\uc815\uc73c\ub85c \uc77d\uc5b4 \ubcf4\uc790. \ub85c\uc81c\ud0c0\uc11d\uc5d0\ub294 \uace0\ub300 \uc774\uc9d1\ud2b8\uc5b4\uc640 \uadf8\ub9ac\uc2a4\uc5b4\uac00 \uc4f0\uc600\ub2e4. \uc774\uc9d1\ud2b8\uc5b4\ub294 \uc0c1\ud615\ubb38\uc790\uc640 \ub370\ubaa8\ud2f1\uc774\ub77c\ub294 \ub450 \ubb38\uc790 \ud615\ud0dc\ub85c \ud45c\ud604\ub418\uc5c8\ub2e4. \uadf8\ub9ac\uc2a4\uc5b4 \ubd80\ubd84\uae4c\uc9c0 \ud569\ud558\uba74 \uc5b8\uc5b4\ub294 \ub458, \ubb38\uc790 \uccb4\uacc4\ub294 \uc14b\uc774\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \uad6c\uc5ed\uc774 \uc138 \uac1c\ub77c\uace0 \uc5b8\uc5b4\ub3c4 \uc138 \uac1c\ub77c\uace0 \ub9d0\ud558\uba74 \uad6c\ubd84\uc744 \ub193\uce58\uac8c \ub41c\ub2e4. \uac19\uc740 \uc5b8\uc5b4\ub3c4 \ub2e4\ub978 \uae00\uc790 \uccb4\uacc4\ub85c \uc801\uc744 \uc218 \uc788\ub2e4\ub294 \uc810\uc744 \ub5a0\uc62c\ub9ac\uba74 \uc870\uae08 \uc26c\uc6cc\uc9c4\ub2e4. \ub2e4\ub9cc \ud604\ub300\uc758 \ud45c\uae30 \uc0ac\ub840\uc640 \uace0\ub300 \ubb38\uc790\uac00 \uc644\uc804\ud788 \uac19\uc740 \uad00\uacc4\uc778 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c\ub294 \ub9d0\uc758 \uccb4\uacc4\uc778 \uc5b8\uc5b4\uc640 \uadf8 \ub9d0\uc744 \uc801\ub294 \ubb38\uc790\ub77c\ub294 \uc11c\ub85c \ub2e4\ub978 \uce35\uc744 \ub098\ub204\uc5b4 \ubcf4\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \ube44\ubb38\uc740 \uae30\uc6d0\uc804 196\ub144 \ud504\ud1a8\ub808\ub9c8\uc774\uc624\uc2a4 5\uc138\uc640 \uad00\ub828\ub41c \ud3ec\uace0\uc758 \ub0b4\uc6a9\uc774\ub2e4. \ud6c4\ub300 \uc5f0\uad6c\uc790\ub4e4\uc5d0\uac8c \ubb38\uc790\ub97c \uac00\ub974\uccd0 \uc8fc\ub824\uace0 \ub9cc\ub4e0 \ube44\uad50\ud45c\uac00 \uc544\ub2c8\ub2e4. \ub2f9\uc2dc\uc758 \uad8c\ub825\uacfc \uc885\uad50\uc801 \uad00\uacc4 \uc18d\uc5d0\uc11c \uc655\uc744 \uae30\ub9ac\ub294 \ubb38\uc11c\uac00 \uc5ec\ub7ec \ubb38\uc790\ub85c \uc0c8\uaca8\uc9c4 \uac83\uc774\ub2e4. \ud558\ub098\uc758 \ub0b4\uc6a9\uc744 \uc5ec\ub7ec \ub3c5\uc790\uc640 \uad00\uc2b5\uc5d0 \ub9de\ucdb0 \ud45c\ud604\ud55c \uacb0\uacfc\uac00 \ud6d7\ub0a0 \uc804\ud600 \ub2e4\ub978 \uc6a9\ub3c4\ub85c \uc911\uc694\ud574\uc84c\ub2e4. \uc790\ub8cc\uc758 \uc6d0\ub798 \ubaa9\uc801\uacfc \ub098\uc911\uc5d0 \uc5bb\uc740 \uc758\ubbf8\ub294 \uac19\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uc5b4\ub5a4 \ubb3c\uac74\uc774 \uc720\uba85\ud574\uc84c\ub294\uc9c0 \uc774\ud574\ud558\ub824\uba74 \ub9cc\ub4e4\uc5b4\uc9c4 \ub54c\uc758 \uc4f0\uc784\uacfc \ub4a4\uc5d0 \uc77c\uc5b4\ub09c \uc77c\uc744 \ub098\ub204\uc5b4 \uc0b4\ud544 \ud544\uc694\uac00 \uc788\ub2e4. \uc0c1\ub2e8\uacfc \uac00\uc7a5\uc790\ub9ac\ub294 \uae68\uc838 \uc788\uace0 \uae00\ub3c4 \ubaa8\ub450 \uac19\uc740 \uc815\ub3c4\ub85c \ubcf4\uc874\ub418\uc9c0 \uc54a\uc558\ub2e4. \ud2b9\ud788 \uc704\ucabd \uc0c1\ud615\ubb38\uc790 \uad6c\uc5ed\uc740 \uc6d0\ub798 \uc804\uccb4\uc758 \uc77c\ubd80\ub9cc \ub0a8\uc544 \uc788\ub2e4. \ub208\uc55e\uc758 \ubaa8\uc2b5\uc774 \ucc98\uc74c \uc81c\uc791\ub41c \ube44\uc11d\uc758 \uc644\uc804\ud55c \ud615\ud0dc\ub77c\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ub530\ub77c\uc11c \uac19\uc740 \ub0b4\uc6a9\uc774 \uc788\ub2e4\uace0 \ud574\uc11c \uc704\uc5d0\uc11c \ud55c \uc904, \uc544\ub798\uc5d0\uc11c \ud55c \uc904\uc744 \uadf8\ub300\ub85c \ub9de\ucd94\uba74 \ub05d\ub098\ub294 \ubb38\uc81c\ub294 \uc544\ub2c8\uc5c8\ub2e4. \ube60\uc9c4 \ubd80\ubd84\uacfc \ubb38\uc7a5\uc758 \ucc28\uc774, \uac01 \ubb38\uc790\uac00 \uc4f0\uc774\ub294 \ubc29\uc2dd\uc744 \uace0\ub824\ud574\uc57c \ud588\ub2e4. \uc2e4\uc81c \uc5f0\uad6c\ub294 \uac04\ub2e8\ud55c \uc138 \uce78\uc9dc\ub9ac \ub300\uc870\ud45c\ubcf4\ub2e4 \ud6e8\uc52c \ubcf5\uc7a1\ud55c \uc791\uc5c5\uc774\uc5c8\ub2e4. \uc774 \ub3cc\uc740 1799\ub144 \uc774\uc9d1\ud2b8\uc758 \ub85c\uc81c\ud0c0, \uace7 \ub77c\uc2dc\ub4dc \ubd80\uadfc\uc5d0\uc11c \ud504\ub791\uc2a4\uad70\uc758 \uacf5\uc0ac \uc911 \ubc1c\uacac\ub418\uc5c8\ub2e4. \uc774\ud6c4 \uad70\uc0ac\uc801 \ucda9\ub3cc\uacfc \ud56d\ubcf5 \ud611\uc815\uc758 \uacfc\uc815\uc5d0\uc11c \uc601\uad6d \uce21\uc73c\ub85c \ub118\uc5b4\uac14\uace0 1802\ub144 \uc601\uad6d\uc5d0 \ub3c4\ucc29\ud588\ub2e4. \ub098\uc911\uc5d0\ub294 \ub300\uc601\ubc15\ubb3c\uad00\uc5d0 \ub193\uc5ec \uad00\ub78c\uacfc \uc5f0\uad6c\uc758 \ub300\uc0c1\uc774 \ub418\uc5c8\ub2e4. \uc774 \uc774\ub3d9\uc744 \uc9c0\uc2dd\uc774 \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc720\ub7fd\uc73c\ub85c \ubaa8\uc5ec\ub4e4\uc5c8\ub2e4\ub294 \uc774\uc57c\uae30\ub85c\ub9cc \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \uad70\ub300\uc640 \uad8c\ub825\uc774 \uc720\ubb3c\uc758 \uc774\ub3d9\uc5d0 \uc791\uc6a9\ud588\ub2e4. \ud574\ub3c5\uc5d0 \uae30\uc5ec\ud55c \uc5f0\uad6c\uc758 \uc5ed\uc0ac\uc640 \uc720\ubb3c\uc744 \ub204\uac00 \uc18c\uc720\ud558\uace0 \uc804\uc2dc\ud558\ub294\uac00\uc758 \uc9c8\ubb38\uc740 \uad6c\ubcc4\ud558\uba74\uc11c\ub3c4 \ud568\uaed8 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc77d\uc744 \uc218 \uc788\ub294 \uadf8\ub9ac\uc2a4\uc5b4 \ub0b4\uc6a9\uc744 \ud1b5\ud574 \ube44\ubb38\uc774 \ub204\uad6c\uc640 \uc5b4\ub5a4 \uc77c\uc5d0 \uad00\ud55c \uac83\uc778\uc9c0 \uc54c \uc218 \uc788\uc5c8\ub2e4. \ub2e4\ub978 \ubb38\uc790 \uad6c\uc5ed\uc5d0\uc11c\ub3c4 \uc655\uc758 \uc774\ub984\ucc98\ub7fc \ubc18\ubcf5\ub420 \ub9cc\ud55c \ubd80\ubd84\uc744 \ucc3e\uc73c\uba74 \ube44\uad50\ud560 \ucd9c\ubc1c\uc810\uc774 \uc0dd\uae34\ub2e4. \ub0af\uc120 \uae00\uc790\ub97c \ubb34\uc791\uc815 \ud558\ub098\uc529 \ucd94\uce21\ud558\ub294 \uac83\uacfc\ub294 \ub2e4\ub978 \uc811\uadfc\uc774\ub2e4. \ud0c0\uc6d0\ud615 \ud14c\ub450\ub9ac\uc5d0 \uc2f8\uc778 \uc655\uba85\uc778 \uce74\ub974\ud22c\uc288\ub3c4 \uc911\uc694\ud55c \ub2e8\uc11c\uc600\ub2e4. \uc5f0\uad6c\uc790\ub4e4\uc740 \ud504\ud1a8\ub808\ub9c8\uc774\uc624\uc2a4\uc758 \uc774\ub984\uacfc \ub2e4\ub978 \ube44\ubb38 \uc790\ub8cc\uc758 \uc774\ub984\uc744 \ube44\uad50\ud588\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \ud074\ub808\uc624\ud30c\ud2b8\ub77c \uc774\ub984\uc758 \ube44\uad50\uc5d0\ub294 \ud544\ub77c\uc774\uc758 \uc624\ubca8\ub9ac\uc2a4\ud06c \uac19\uc740 \ub2e4\ub978 \uc790\ub8cc\uac00 \uc4f0\uc600\ub2e4. \ub450 \uc774\ub984\uc774 \ubaa8\ub450 \ub85c\uc81c\ud0c0\uc11d\uc5d0 \uc788\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\ub3c4\ub85d \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc0c8\ub098 \ub208, \uc0ac\ub78c\ucc98\ub7fc \ubcf4\uc774\ub294 \ubaa8\uc591\uc774 \uc788\ub2e4\uace0 \ud574\uc11c \ubaa8\ub4e0 \uae30\ud638\ub97c \uc0ac\ubb3c\uc758 \uadf8\ub9bc \ub73b \ud558\ub098\ub85c \ubc14\uafc0 \uc218\ub294 \uc5c6\ub2e4. \uc18c\ub9ac\ub97c \ub098\ud0c0\ub0b4\ub294 \uae30\ub2a5\uc744 \uc774\ud574\ud558\ub294 \uac83\uc774 \uc911\uc694\ud588\ub2e4. \uae00\uc790\ucc98\ub7fc \uc0dd\uae34 \uadf8\ub9bc\uc774 \uc544\ub2c8\ub77c \uc5b8\uc5b4\ub97c \ud45c\ud604\ud558\ub294 \ubcf5\uc7a1\ud55c \ubb38\uc790 \uccb4\uacc4\ub97c \uc77d\uc5b4\uc57c \ud588\ub358 \uac83\uc774\ub2e4. \ud1a0\uba38\uc2a4 \uc601\uacfc \uc7a5\ud504\ub791\uc218\uc544 \uc0f9\ud3f4\ub9ac\uc639\uc744 \ube44\ub86f\ud55c \uc5ec\ub7ec \uc5f0\uad6c\uc790\uc758 \uae30\uc5ec\uac00 \uc774\uc5b4\uc84c\ub2e4. \uac19\uc740 \uc790\ub8cc\ub97c \ub450\uace0 \uc55e\uc120 \ud574\uc11d\uc744 \uace0\uce58\uace0 \ub2e4\ub978 \uc5b8\uc5b4 \uc9c0\uc2dd\uc744 \uc5f0\uacb0\ud558\ub294 \uacfc\uc815\uc774 \uc788\uc5c8\ub2e4. \uc774\uc9d1\ud2b8\uc5b4\ub97c \uc5f0\uad6c\ud560 \ub54c \ucf65\ud2b8\uc5b4\ub97c \uc544\ub294 \uc77c\ub3c4 \uc911\uc694\ud588\ub2e4. \ub3cc \ud55c \uc870\uac01\uacfc \ud55c \uc0ac\ub78c\uc758 \uc7ac\ub2a5\ub9cc\uc73c\ub85c \ub05d\ub09c \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \ub85c\uc81c\ud0c0\uc11d\uc744 \uc9c1\uc811 \ubcfc \uc218 \uc788\ub294 \uc0ac\ub78c\uc740 \uc81c\ud55c\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc778\uc1c4\ud55c \ubcf5\uc0ac\uc640 \ud0c1\ubcf8, \uc11d\uace0 \ubaa8\ud615 \uac19\uc740 \uc790\ub8cc\uac00 \uc5ec\ub7ec \uacf3\uc73c\ub85c \uc804\ud574\uc9c0\uba74\uc11c \ub2e4\ub978 \uc5f0\uad6c\uc790\ub4e4\ub3c4 \ub0b4\uc6a9\uc744 \ube44\uad50\ud560 \uc218 \uc788\uc5c8\ub2e4. \uc6d0\ubcf8\uc744 \ubcf4\uc874\ud558\ub294 \uc77c\uacfc \uc815\ud655\ud558\uac8c \ubcf5\uc81c\ud574 \ub098\ub204\ub294 \uc77c\uc774 \uc5f0\uad6c\uc5d0\uc11c \uc5f0\uacb0\ub418\uc5c8\ub2e4. \uc774 \uae00\uc758 \uadfc\uac70\ub85c \uc77d\uc740 1913\ub144 \ubc15\ubb3c\uad00 \ud574\uc124\uc11c\ub294 \uadf8\ub7f0 \uacfc\uc815\uc744 \uae30\ub85d\ud558\uc9c0\ub9cc \uc2dc\ub300\uc758 \uc124\uba85\uacfc \ud55c\uacc4\ub3c4 \uc788\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \ub3cc\uc758 \uc7ac\uc9c8\uc5d0 \ub300\ud55c \uc61b \ubd84\ub958\ub97c \uc5ec\uae30\uc11c \uadf8\ub300\ub85c \ubc18\ubcf5\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc624\ub798\ub41c \uc790\ub8cc\ub294 \uc720\uc6a9\ud55c \uc6d0\uc804\uc774\uba74\uc11c \uc774\ud6c4 \uc5f0\uad6c\uc640 \uad6c\ubd84\ud574 \uc77d\uc5b4\uc57c \ud560 \ub300\uc0c1\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uadf8 \ud574\uc124\uc11c\uc758 \uc2e4\uc81c \ube44\ubb38 \ub3c4\ud310\uc774\ub2e4. AI\uac00 \uc0c1\ud615\ubb38\uc790\ub97c \ub9cc\ub4e4\uc5b4 \ub123\uc740 \uadf8\ub9bc\uc774 \uc544\ub2c8\ub2e4. \uc138 \uad6c\uc5ed\uc758 \uae00\uc790 \ubaa8\uc591\uacfc \uae68\uc9c4 \uac00\uc7a5\uc790\ub9ac\ub97c \ubcf4\uace0 \ub098\uba74, \uc775\uc219\ud558\uac8c \uc77d\ub294 \uae00\uc5d0\ub3c4 \uc5b4\ub5a4 \ubb38\uc790\uc640 \uc5b8\uc5b4\uc758 \uc57d\uc18d\uc774 \ub193\uc5ec \uc788\ub294\uc9c0 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \ub85c\uc81c\ud0c0\uc11d\uc774 \ud765\ubbf8\ub85c\uc6b4 \uc774\uc720\ub294 \ube44\ubc00\uc2a4\ub7ec\uc6b4 \ub3cc\uc774\ub77c\ub294 \uc774\ub984 \ub54c\ubb38\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uc54c\ub358 \ubd80\ubd84\uc5d0\uc11c \ubaa8\ub974\ub358 \ubd80\ubd84\uc73c\ub85c \ub118\uc5b4\uac00\uace0, \ud558\ub098\uc758 \ucd94\uce21\uc744 \ub2e4\ub978 \uc790\ub8cc\uc640 \ub300\uc870\ud574 \uace0\uccd0 \uac04 \uacfc\uc815\uc774 \ub2f4\uaca8 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc77d\uae30\uc758 \uc5ed\uc0ac\ub294 \ud63c\uc790 \ub5a0\uc62c\ub9b0 \uc815\ub2f5\ubcf4\ub2e4 \ud568\uaed8 \ud655\uc778\ud55c \uc5f0\uacb0 \uc18d\uc5d0\uc11c \ub113\uc5b4\uc9c0\uae30\ub3c4 \ud55c\ub2e4."}, {"id": "samarkand-registan-and-learning", "title": "\uc0ac\ub9c8\ub974\uce78\ud2b8 \u2014 \ud478\ub978 \uad11\uc7a5\uc5d0 \uc7a5\uc778\uacfc \ud559\uc790\uac00 \ubaa8\uc774\ub2e4", "summary": "\ub808\uae30\uc2a4\ud0c4\uacfc \ud559\ubb38\uc758 \ub3c4\uc2dc\ub97c \ud1b5\ud574 \uc0ac\ub9c8\ub974\uce78\ud2b8\uc5d0 \ubaa8\uc778 \uad50\uc5ed\u00b7\uc7a5\uc778\u00b7\ucc9c\ubb38\ud559\uc758 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/samarkand-registan-and-learning/index.html", "image": "../media/samarkand-registan-and-learning.jpg", "alt": "\uc67c\ucabd\uc740 \uc0ac\ub9c8\ub974\uce78\ud2b8 \uc170\ub974\ub3c4\ub974 \ub9c8\ub4dc\ub77c\uc0ac\uc758 \uc2e4\uc81c \uc0ac\uc9c4, \uc624\ub978\ucabd\uc740 \uc5ed\uc0ac\uc801 \ub300\ubaa8\uc2a4\ud06c \uac74\uc124 \ud68c\ud654.", "text": "\uc0ac\ub9c8\ub974\uce78\ud2b8 \u2014 \ud478\ub978 \uad11\uc7a5\uc5d0 \uc7a5\uc778\uacfc \ud559\uc790\uac00 \ubaa8\uc774\ub2e4 \uc544\ub984\ub2e4\uc6b4 \uac74\ubb3c\uc744 \ubcf4\ub294 \uc77c\uacfc \uadf8 \ub4a4\uc758 \uc0ac\ub78c\uc744 \uae30\uc5b5\ud558\ub294 \uc77c \ub808\uae30\uc2a4\ud0c4\uacfc \ud559\ubb38\uc758 \ub3c4\uc2dc\ub97c \ud1b5\ud574 \uc0ac\ub9c8\ub974\uce78\ud2b8\uc5d0 \ubaa8\uc778 \uad50\uc5ed\u00b7\uc7a5\uc778\u00b7\ucc9c\ubb38\ud559\uc758 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ud478\ub978\uc0c9\uacfc \ud759\ube5b\uc774 \uc11e\uc778 \ucee4\ub2e4\ub780 \uc785\uad6c, \ub192\uac8c \uc19f\uc740 \ud0d1, \uc7a5\uc2dd\uc73c\ub85c \ucc44\uc6b4 \ubcbd\uba74. \uc0ac\ub9c8\ub974\uce78\ud2b8\uc758 \ub808\uae30\uc2a4\ud0c4\uc744 \ubcf4\uba74 \uac74\ubb3c\uc774 \ub113\uc740 \uad11\uc7a5\uc744 \ud5a5\ud574 \ubb34\ub300\ucc98\ub7fc \uc11c \uc788\ub2e4\ub294 \ub290\ub08c\uc774 \ub4e0\ub2e4. \uc6b0\uc988\ubca0\ud0a4\uc2a4\ud0c4\uc758 \uc774 \ub3c4\uc2dc\ub294 \uc0ac\uc9c4 \ud55c \uc7a5\ub9cc\uc73c\ub85c\ub3c4 \uc5ec\ud589\ud558\uace0 \uc2f6\uc740 \ub9c8\uc74c\uc744 \uc77c\uc73c\ud0a8\ub2e4. \uadf8\ub7ec\ub098 \uc544\ub984\ub2e4\uc6b4 \uc7a5\uc18c\uac00 \uc800\uc808\ub85c \uc0dd\uae30\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\uc774 \ubaa8\uc774\uace0 \ubb3c\uc790\uac00 \ub4e4\uc5b4\uc624\uba70, \ub204\uad70\uac00 \uadf8 \uc77c\uc744 \ud6c4\uc6d0\ud558\uace0 \ub2e4\ub978 \ub204\uad70\uac00\ub294 \uc190\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc57c \ud55c\ub2e4. \uc0ac\ub9c8\ub974\uce78\ud2b8\uc758 \uc774\uc57c\uae30\ub294 \uba4b\uc9c4 \uc678\uad00 \ub4a4\uc5d0\uc11c \uad50\uc5ed\uacfc \uad8c\ub825, \ubc30\uc6c0\uc774 \ub9cc\ub09c \uacfc\uc815\uc73c\ub85c \uc774\uc5b4\uc9c4\ub2e4. \uc0ac\ub9c8\ub974\uce78\ud2b8\ub294 \uc911\uc559\uc544\uc2dc\uc544\uc758 \uc911\uc694\ud55c \uc624\uc544\uc2dc\uc2a4 \ub3c4\uc2dc\uc600\ub2e4. \ubd80\ud558\ub77c\uc640 \ud568\uaed8 \uc18c\uadf8\ub4dc \uc0c1\uc778\ub4e4\uc758 \ud65c\ub3d9\uacfc \uc5f0\uacb0\ub418\uc5c8\uc73c\uba70, \ub3d9\uc11c \uad50\uc5ed\uc744 \uc774\uc5b4 \uc8fc\ub294 \uac70\uc810 \uac00\uc6b4\ub370 \ud558\ub098\uc600\ub2e4. \uc2e4\ud06c\ub85c\ub4dc\ub294 \ud55c \uc0ac\ub78c\uc774 \ucc98\uc74c\ubd80\ud130 \ub05d\uae4c\uc9c0 \uac77\ub294 \ud558\ub098\uc758 \ub3c4\ub85c\ubcf4\ub2e4 \uc5ec\ub7ec \uc9c0\uc5ed\uc744 \uc787\ub294 \uae38\uc758 \ub9dd\uc774\uc5c8\ub2e4. \uc18c\uadf8\ub4dc\uc778\ub4e4\uc740 \uc11c\ucabd\uacfc \ub3d9\ucabd\uc758 \uc5ec\ub7ec \uc0ac\ub78c\uacfc \uac70\ub798\ud588\uace0 \uc911\uad6d\uc758 \uc8fc\uc694 \ub3c4\uc2dc\ub4e4\uc5d0\ub3c4 \uad50\uc5ed \uacf5\ub3d9\uccb4\ub97c \ub450\uc5c8\ub2e4. \ubb3c\uac74\ubfd0 \uc544\ub2c8\ub77c \uc5b8\uc5b4\uc640 \uc885\uad50, \uc0dd\ud65c\uc758 \ubc29\uc2dd\ub3c4 \uc774\ub3d9\ud588\ub2e4. \uc0ac\ub9c8\ub974\uce78\ud2b8\ub97c \ud2b9\uc815 \uc815\ubcf5\uc790\uac00 \ucc98\uc74c \ub9cc\ub4e0 \ube48 \ubb34\ub300\ucc98\ub7fc \ubcf4\uba74 \uadf8\ubcf4\ub2e4 \uc624\ub798 \uc313\uc778 \ub3c4\uc2dc\uc758 \uc5ed\ud560\uc744 \ub193\uce5c\ub2e4. 14\uc138\uae30\uc5d0 \uc138\ub825\uc744 \ub113\ud78c \ud2f0\ubb34\ub974\ub294 \uc0ac\ub9c8\ub974\uce78\ud2b8\ub97c \uc790\uc2e0\uc758 \uc218\ub3c4\ub85c \uc0bc\uc558\ub2e4. \uc815\ubcf5\ud55c \uc9c0\uc5ed\uc5d0\uc11c \ubd80\uc640 \uc720\uc6a9\ud55c \uae30\uc220\uc744 \ubaa8\uc558\uace0, \uac74\ucd95\uac00\uc640 \uc608\uc220\uac00, \uc7a5\uc778\ub4e4\uc744 \uc218\ub3c4\ub85c \ubcf4\ub0c8\ub2e4. \ub3c4\uc2dc\ub294 \ud070 \uac74\uc124 \uc791\uc5c5\uc774 \uc774\uc5b4\uc9c0\ub294 \uc7a5\uc18c\uac00 \ub418\uc5c8\ub2e4. \uc7a5\uc778\uc774 \ub9ce\uc544\uc84c\ub2e4\ub294 \uacb0\uacfc\ub9cc\uc73c\ub85c \uc774\ub97c \uc790\uc720\ub85c\uc6b4 \uc608\uc220\uac00\ub4e4\uc758 \uc5ec\ud589\uc73c\ub85c \uadf8\ub824\uc11c\ub294 \uc548 \ub41c\ub2e4. \uad50\uc7ac\ub294 \uc815\ubcf5\uacfc \uac15\uc81c\uc801\uc778 \uc774\ub3d9\uc774 \uc774 \uacfc\uc815\uc5d0 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uac74\ubb3c\uc758 \uc544\ub984\ub2e4\uc6c0\uc774 \uadf8 \ubc30\uacbd\uc758 \ud3ed\ub825\uc744 \uc5c6\uc560 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub3c4\uc2dc\ub97c \uce6d\ucc2c\ud558\ub294 \uc77c\uacfc \uadf8\uacf3\uc73c\ub85c \uc624\uac8c \ub41c \uc0ac\ub78c\ub4e4\uc758 \uc870\uac74\uc744 \ubb3b\ub294 \uc77c\uc740 \ud568\uaed8 \ud560 \uc218 \uc788\ub2e4. \ub808\uae30\uc2a4\ud0c4\uc740 \uc0ac\ub9c8\ub974\uce78\ud2b8\uc758 \uacf5\uacf5 \uc9d1\ud68c\uc640 \ubc30\uc6c0\uc774 \uc774\ub8e8\uc5b4\uc9c4 \uc911\uc694\ud55c \uad11\uc7a5\uc774\uc5c8\ub2e4. \uad11\uc7a5\uc744 \ud5a5\ud574 \uc120 \ub9c8\ub4dc\ub77c\uc0ac\ub4e4\uc740 \uc885\uad50\uc640 \ud559\ubb38\uc758 \uad50\uc721 \uacf5\uac04\uc774\ub2e4. \ucee4\ub2e4\ub780 \ube48 \uacf5\uac04\uacfc \uadf8 \ub458\ub808\uc758 \uac74\ubb3c\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \uc7a5\uc18c\uc758 \uc131\uaca9\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \uac74\ubb3c \ud558\ub098\uc758 \uc815\uba74\ub9cc \ubcf4\uba74 \uc7a5\uc2dd\uc758 \uc544\ub984\ub2e4\uc6c0\uc5d0 \uc9d1\uc911\ud558\uac8c \ub41c\ub2e4. \ubc18\ub300\ub85c \uad11\uc7a5\uc5d0\uc11c \uc5b4\ub290 \ubc29\ud5a5\uc744 \ubcf4\uc544\ub3c4 \uc911\uc694\ud55c \uc785\uad6c\uac00 \uc2dc\uc120\uc5d0 \ub4e4\uc5b4\uc624\ub294 \ubc30\uce58\ub97c \uc0dd\uac01\ud558\uba74 \ub3c4\uc2dc\uc758 \uc911\uc2ec\uc744 \ub9cc\ub4dc\ub294 \ubc29\uc2dd\ub3c4 \ubcf4\uc778\ub2e4. \uc7a5\uc2dd\uacfc \uacf5\uac04\uc758 \uad00\uacc4\ub294 \uc11c\ub85c \ub2e4\ub978 \uac10\uc0c1\uc774 \uc544\ub2c8\ub77c \uac19\uc740 \uc7a5\uc18c\ub97c \ubcf4\ub294 \ub450 \uac70\ub9ac\ub2e4. \ud568\uaed8 \uc2e4\uc740 \ub3c4\ud310\uc758 \uc67c\ucabd\uc740 \ub808\uae30\uc2a4\ud0c4\uc758 \uc170\ub974\ub3c4\ub974 \ub9c8\ub4dc\ub77c\uc0ac \uc0ac\uc9c4\uc774\ub2e4. \uc624\ub978\ucabd\uc740 \ud2f0\ubb34\ub974\uc758 \uc6d0\uc815\uc744 \ub2e4\ub8ec \u300a\uc2b9\uc804\uae30\u300b\uc5d0 \uc2e4\ub9b0 \uc0ac\ub9c8\ub974\uce78\ud2b8 \ub300\ubaa8\uc2a4\ud06c \uac74\uc124 \uc7a5\uba74\uc774\ub2e4. \ud558\ub098\ub294 \ub0a8\uc544 \uc788\ub294 \uac74\ubb3c\uc758 \uc0ac\uc9c4\uc774\uace0 \ub2e4\ub978 \ud558\ub098\ub294 \uc5ed\uc0ac\uc801 \ud68c\ud654\ub2e4. \ub458\uc744 \ub098\ub780\ud788 \ub193\uc558\ub2e4\uace0 \uac19\uc740 \uac74\ubb3c\uc758 \uc644\uacf5 \uc804\uacfc \ud6c4\uac00 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0ac\uc9c4\uc758 \ub9c8\ub4dc\ub77c\uc0ac\uc640 \ud68c\ud654 \uc18d \ub300\ubaa8\uc2a4\ud06c, \ub4a4\uc5d0\uc11c \uc18c\uac1c\ud560 \ucc9c\ubb38\ub300\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc7a5\uc18c\ub2e4. \uc774 \uad6c\ubd84\uc744 \uba3c\uc800 \ud574 \ub450\uba74 \uc5ec\ub7ec \uc2dc\ub300\uc758 \uac74\ucd95\uc744 \ud55c \uc0ac\ub78c\uc774 \ud55c \ubc88\uc5d0 \ub9cc\ub4e0 \ub3c4\uc2dc\ub85c \ubb49\ub6b1\uadf8\ub9ac\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uc624\ub978\ucabd \uadf8\ub9bc\uc5d0\ub294 \uc77c\uc744 \ud558\ub294 \uc5ec\ub7ec \uc778\ubb3c\uacfc \uc7ac\ub8cc\ub97c \uc62e\uae30\ub294 \uc7a5\uba74\uc774 \ubcf4\uc778\ub2e4. \ud070 \uac74\ubb3c\uc744 \uac10\uc0c1\ud558\ub2e4\uac00 \uc791\uc5c5\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c \uc2dc\uc120\uc744 \uc62e\uae30\uba74 \ub3c4\uc2dc \uac74\uc124\uc774 \uc190\uacfc \uc2dc\uac04\uc758 \ubb38\uc81c\uc600\ub2e4\ub294 \uc810\uc774 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \uc655\uc758 \uc774\ub984\uc73c\ub85c \ubd88\ub9ac\ub294 \uac74\ubb3c\ub3c4 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \ub2a5\ub825\uc774 \uc788\uc5b4\uc57c \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4. \ub2e4\ub9cc \uc774 \uadf8\ub9bc\uc740 \uacf5\uc0ac \ud604\uc7a5\uc744 \uc0ac\uc9c4\ucc98\ub7fc \uadf8\ub300\ub85c \uc62e\uae34 \uae30\ub85d\uc740 \uc544\ub2c8\ub2e4. \uc2b9\ub9ac\ub97c \uae30\ub150\ud558\uace0 \ud1b5\uce58\uc790\uc758 \uc704\uc5c5\uc744 \ud45c\ud604\ud558\ub294 \ucc45\uc5d0 \ub2f4\uae34 \uc7a5\uba74\uc774\ub77c\ub294 \ub9e5\ub77d\uc774 \uc788\ub2e4. \uadf8 \ubaa9\uc801\uc744 \uae30\uc5b5\ud558\uba74\uc11c\ub3c4 \uadf8\ub9bc\uc774 \uc791\uc5c5\uc744 \uc5b4\ub5a4 \ubaa8\uc2b5\uc73c\ub85c \ubcf4\uc5ec \uc8fc\ub824 \ud588\ub294\uc9c0\ub294 \uad00\ucc30\ud560 \uc218 \uc788\ub2e4. \ud2f0\ubb34\ub974\uc758 \uc190\uc790 \uc6b8\ub8e8\uadf8\ubca0\ud06c\ub294 \uc0ac\ub9c8\ub974\uce78\ud2b8\uc5d0 \ub9c8\ub4dc\ub77c\uc0ac\uc640 \ucc9c\ubb38\ub300\ub97c \uc138\uc6b0\uace0 \uc218\ud559\uc790\uc640 \ucc9c\ubb38\ud559\uc790\ub97c \ucd08\uccad\ud588\ub2e4. \uad50\uc7ac\ub294 \uc774 \ub3c4\uc2dc\uac00 15\uc138\uae30\uc5d0 \uc911\uc694\ud55c \ud559\ubb38\uc758 \uc911\uc2ec\uc774 \ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uad8c\ub825\uc744 \uacfc\uc2dc\ud558\ub294 \uac74\ucd95\ub9cc\uc774 \uc544\ub2c8\ub77c \ubc30\uc6c0\uc744 \ud6c4\uc6d0\ud558\ub294 \uacf5\uac04\ub3c4 \uc0dd\uaca8\ub09c \uac83\uc774\ub2e4. \ucc9c\ubb38\ub300\ub294 \ubcc4\uc744 \ubcf4\uae30 \uc88b\uc740 \uacbd\uce58\ub9cc\uc73c\ub85c \uc644\uc131\ub418\uc9c0 \uc54a\ub294\ub2e4. \uad00\uce21\uc744 \ud560 \uc0ac\ub78c\uacfc \uc9c0\uc2dd\uc744 \uc774\uc5b4 \uac08 \ud658\uacbd\uc774 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc815\ubc00\ud55c \uad00\uce21 \uae30\uae30\uc758 \uad6c\uc870\ub098 \uac1c\ubcc4 \uc218\uce58\ub97c \ub2e4\ub8e8\uae30\ubcf4\ub2e4, \ud1b5\uce58\uc790\uc758 \ud6c4\uc6d0\uacfc \ud559\uc790\uc758 \ud65c\ub3d9\uc774 \ub3c4\uc2dc \uc548\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ub9cc\ub0ac\ub294\uc9c0 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uba3c \uacf3\uc5d0\uc11c \uc0ac\ub78c\uc774 \ub4e4\uc5b4\uc624\ub294 \ub3c4\uc2dc\ub294 \ub2e4\ub978 \uc5b8\uc5b4\uc640 \uae30\uc220\uc744 \uc811\ud560 \uae30\ud68c\uac00 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \uad50\uc5ed\uc774 \ud65c\ubc1c\ud55c \uacf3\uc774 \ubc18\ub4dc\uc2dc \ud559\ubb38\uc758 \ub3c4\uc2dc\uac00 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc77c\ud560 \uc7a5\uc18c\uc640 \ud6c4\uc6d0, \ubc30\uc6c0\uc744 \uc9c0\uc18d\ud560 \uad00\uacc4\uac00 \ud568\uaed8 \ud544\uc694\ud558\ub2e4. \uc0ac\ub9c8\ub974\uce78\ud2b8\uc5d0\uc11c\ub294 \uc624\ub798\ub41c \uad50\uc5ed \uac70\uc810\uc758 \uc131\uaca9 \uc704\uc5d0 \uc815\ubcf5 \uc655\uc870\uc758 \uc218\ub3c4\ub77c\ub294 \uc5ed\ud560\uacfc \ud559\ubb38 \ud6c4\uc6d0\uc774 \uacb9\ucce4\ub2e4. \uac01\uac01\uc758 \uc2dc\uae30\ub97c \uac19\uc740 \uc7a5\uba74\uc73c\ub85c \uc11e\uae30\ubcf4\ub2e4 \ucc28\ub840\ub85c \ubcf4\uc544\uc57c \ub3c4\uc2dc\uc758 \ubcc0\ud654\uac00 \ubcf4\uc778\ub2e4. \uc5ec\ub7ec \uae30\ub2a5\uc774 \ub298 \ub611\uac19\uc740 \ube44\uc728\ub85c \uc720\uc9c0\ub418\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc0ac\uc9c4 \uc18d\uc758 \uc7a5\uc2dd\uc740 \uc5ec\uc804\ud788 \uc544\ub984\ub2f5\ub2e4. \uc5ed\uc0ac\uc801 \ubc30\uacbd\uc744 \uc548\ub2e4\uace0 \uadf8 \uc544\ub984\ub2e4\uc6c0\uc744 \ud3ec\uae30\ud560 \uc774\uc720\ub294 \uc5c6\ub2e4. \uc624\ud788\ub824 \uac74\ubb3c\uc744 \ub9cc\ub4e0 \uae30\uc220\uacfc \uadf8 \uae30\uc220\uc744 \uc9c0\ub2cc \uc0ac\ub78c\ub4e4\uc758 \uc774\ub3d9\uc774 \uad6c\uccb4\uc801\uc73c\ub85c \ub290\uaef4\uc838 \uac10\uc0c1\uc758 \ub0b4\uc6a9\uc774 \ub9ce\uc544\uc9c4\ub2e4. \uc0ac\ub9c8\ub974\uce78\ud2b8\ub97c \uae30\uc5b5\ud560 \ub54c \ud478\ub978 \uc815\uba74 \uc606\uc5d0 \uad11\uc7a5\uacfc \uc791\uc5c5\ud558\ub294 \uc190, \ubcc4\uc744 \uc5f0\uad6c\ud558\ub358 \uc0ac\ub78c\uc758 \uc790\ub9ac\ub3c4 \ub0a8\uaca8 \ubcf4\uc790. \ub3c4\uc2dc\ub294 \ud55c \uc601\uc6c5\uc758 \uc131\ucde8\ub9cc\uc73c\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc0ac\uc9c4\uc5d0 \ud06c\uac8c \ubcf4\uc774\ub294 \uc774\ub984\ub09c \uac74\ubb3c\uacfc \uc791\uac8c \ubcf4\uc774\uac70\ub098 \uc0ac\ub77c\uc9c4 \uc0ac\ub78c\uc758 \uc2dc\uac04\uc744 \ud568\uaed8 \uc77d\uc744 \ub54c \uadf8 \uc7a5\uc18c\uc758 \uae4a\uc774\uac00 \uc0dd\uae34\ub2e4."}, {"id": "sofala-port-and-hinterland", "title": "\uc18c\ud314\ub77c \u2014 \uc791\uc740 \ud56d\uad6c \ub4a4\uc5d0\ub294 \uae34 \uae38\uc774 \uc788\uc5c8\ub2e4", "summary": "17\uc138\uae30 \uc18c\ud314\ub77c \ub3c4\ud310\uc5d0\uc11c \ucd9c\ubc1c\ud574 \ub0b4\ub959\uacfc \uc778\ub3c4\uc591\uc744 \uc774\uc740 \ud56d\uad6c\uc758 \uc5ed\ud560\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/sofala-port-and-hinterland/index.html", "image": "../media/sofala-port-and-hinterland.png", "alt": "1683\ub144 \uc18c\ud314\ub77c\ub97c \ud45c\ud604\ud55c \ub9d0\ub808 \ub3c4\ud310\uc758 \uc804\uccb4\uc640 \ud655\ub300 \uad6c\uc131. \ubb3c\uae38\uacfc \uc131\ucc44, \uc8fc\ubcc0 \uac74\ubb3c.", "text": "\uc18c\ud314\ub77c \u2014 \uc791\uc740 \ud56d\uad6c \ub4a4\uc5d0\ub294 \uae34 \uae38\uc774 \uc788\uc5c8\ub2e4 \ubc14\ub2e4\uc5d0 \ub3c4\ucc29\ud55c \uae08\uc740 \uc5b4\ub514\uc5d0\uc11c \uc654\uc744\uae4c 17\uc138\uae30 \uc18c\ud314\ub77c \ub3c4\ud310\uc5d0\uc11c \ucd9c\ubc1c\ud574 \ub0b4\ub959\uacfc \uc778\ub3c4\uc591\uc744 \uc774\uc740 \ud56d\uad6c\uc758 \uc5ed\ud560\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ud56d\uad6c\ub77c\uace0 \ud558\uba74 \ubc14\ub2e4\uc640 \ubc30\ubd80\ud130 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \ud574\uc548\uc120\uacfc \uadf8 \uc606\uc758 \uac74\ubb3c\ub4e4\uc774 \ub3c4\uc2dc\uc758 \uc804\ubd80\ucc98\ub7fc \ub290\uaef4\uc9c0\uae30\ub3c4 \ud55c\ub2e4. \uadf8\ub7f0\ub370 \ud56d\uad6c\ub97c \ubd80\uc720\ud558\uac8c \ud55c \ubb3c\uac74\uc740 \uadf8\ub9bc\uc5d0 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uba3c \ub0b4\ub959\uc5d0\uc11c \uc654\uc744 \uc218\ub3c4 \uc788\ub2e4. \uc18c\ud314\ub77c\ub294 \uadf8 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uae38\uc744 \uc0dd\uac01\ud558\uac8c \ud558\ub294 \ub3c4\uc2dc\ub2e4. \uc624\ub298\ub0a0 \ubaa8\uc7a0\ube44\ud06c\uc5d0 \uc788\ub294 \uc774 \ud56d\uad6c\ub294 \ub3d9\uc544\ud504\ub9ac\uce74\uc758 \ud574\uc548\uacfc \ub0b4\ub959\uc744 \uc5f0\uacb0\ud588\ub2e4. \ubc30\uac00 \ub4e4\uc5b4\uc624\ub294 \uc790\ub9ac\ub77c\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uadf8 \uc911\uc694\uc131\uc774 \ubaa8\ub450 \uc124\uba85\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubb34\uc5c7\uc774 \uc774\uacf3\uae4c\uc9c0 \uc654\uace0 \ub204\uac00 \ubc14\uae65\uc73c\ub85c \uac00\uc838\uac14\ub294\uc9c0\ub97c \uc0b4\ud53c\uba74 \uc791\uc740 \ud574\uc548 \ub3c4\uc2dc \ub4a4\uc758 \uc138\uacc4\uac00 \ub113\uc5b4\uc9c4\ub2e4. \uc544\ud504\ub9ac\uce74 \ub0b4\ub959\uc5d0\uc11c \ub098\uc628 \uae08\uacfc \uc5ec\ub7ec \ubb3c\ud488\uc740 \ud574\uc548\uc73c\ub85c \uc62e\uaca8\uc84c\ub2e4. \uc18c\ud314\ub77c\ub294 \uc774\ub97c \uc778\ub3c4\uc591 \uad50\uc5ed\uc73c\ub85c \uc787\ub294 \uc911\uc694\ud55c \uc9c0\uc810\uc774\uc5c8\ub2e4. \uc55e\uc120 \uae00\uc5d0\uc11c \ub9cc\ub09c \uadf8\ub808\uc774\ud2b8 \uc9d0\ubc14\ube0c\uc6e8\uc640\ub3c4 \uc5f0\uacb0\ub418\ub294 \uae38\uc774\ub2e4. \ub0b4\ub959\uc758 \ubc88\uc601\uacfc \ud56d\uad6c\uc758 \ubc88\uc601\uc740 \uc11c\ub85c \ub2e4\ub978 \uc9c0\ub3c4\uc758 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\uc5c8\ub2e4. \ud56d\uad6c\uc5d0\uc11c\ub294 \ubb3c\uac74\uc744 \ub0b4\ub9ac\ub294 \uc77c\uacfc \ub2e4\uc74c \uc5ec\uc815\uc744 \uc900\ube44\ud558\ub294 \uc77c\uc774 \ub9cc\ub09c\ub2e4. \uc624\ub7ab\ub3d9\uc548 \uc774\ub3d9\ud55c \uc9d0\ub3c4 \ub204\uad70\uac00\uc5d0\uac8c\ub294 \uc774\uc81c \ub9c9 \uac70\ub798\ud560 \ubb3c\uac74\uc774\ub2e4. \uc5ec\ud589\uc758 \ub05d\uacfc \uc2dc\uc791\uc774 \uac19\uc740 \uc7a5\uc18c\uc5d0 \uacb9\uce5c\ub2e4\ub294 \uad00\uc810\uc73c\ub85c \ubcf4\uba74, \ud56d\uad6c\uac00 \ub2e8\uc9c0 \ubc30\ub97c \uc138\uc6cc \ub450\ub294 \uacf5\uac04 \uc774\uc0c1\uc774\ub77c\ub294 \uc810\uc774 \ubcf4\uc778\ub2e4. \ub3d9\uc544\ud504\ub9ac\uce74 \ud574\uc548\uc758 \uac15\ub825\ud55c \ub3c4\uc2dc\uad6d\uac00 \ud0ac\uc640\ub294 \uc18c\ud314\ub77c\ub97c \ud1b5\ud574 \uae08 \uad50\uc5ed\uc5d0 \uc811\uadfc\ud588\ub2e4. OpenStax\ub294 \ud0ac\uc640\uac00 \uc911\uac04\uc758 \uac70\ub798\uc790\ub97c \uac70\uce58\uc9c0 \uc54a\uace0 \ub354 \uc9c1\uc811\uc801\uc73c\ub85c \uae08\uc744 \ud655\ubcf4\ud558\ub824 \ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uad50\uc5ed\ub9dd\uc758 \ud55c \uc9c0\uc810\uc744 \ud1b5\uc81c\ud558\ub294 \uc77c\uc774 \ub3c4\uc2dc\uc758 \ud798\uacfc \uc5f0\uacb0\ub418\uc5c8\ub358 \uac83\uc774\ub2e4. \ubd80\uc720\ud55c \ud56d\uad6c\uac00 \ubc18\ub4dc\uc2dc \uc790\uae30 \uc8fc\ubcc0\uc5d0\uc11c \uae08\uc744 \uce90\ub294 \uacf3\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uc0dd\uc0b0\uc9c0\uc640 \uad50\ud658 \uc9c0\uc810\uc744 \uc787\ub294 \uad00\uacc4\ub97c \uc7a5\uc545\ud574 \uc601\ud5a5\ub825\uc744 \uc5bb\uc744 \uc218 \uc788\ub2e4. \ubb3c\uac74\uc774 \uc5b4\ub514\uc5d0\uc11c \ub098\uc624\ub294\uc9c0\uc640 \uadf8 \ubb3c\uac74\uc758 \uc774\ub3d9\uc744 \ub204\uac00 \uc870\uc815\ud558\ub294\uc9c0\ub294 \ub2e4\ub978 \uc9c8\ubb38\uc774\ub2e4. \uc18c\ud314\ub77c\ub97c \ub458\ub7ec\uc2fc \uad00\uc2ec\uc740 \ubc14\ub85c \uadf8 \ucc28\uc774\uc5d0\uc11c \uc0dd\uaca8\ub0ac\ub2e4. \uc2a4\uc640\ud790\ub9ac \ud574\uc548\uc758 \uad50\uc5ed\uc740 \uc778\ub3c4\uc591\uc758 \uacc4\uc808\ud48d\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \ubc14\ub78c\uc758 \ubc29\ud5a5\uc774 \ubc14\ub00c\ub294 \uc2dc\uae30\ub97c \uc774\uc6a9\ud574 \ud56d\ud574\ud588\uae30 \ub54c\ubb38\uc774\ub2e4. \uc721\uc9c0\uc5d0\uc11c \uacc4\uc808\uc744 \ubcf4\uba70 \ub18d\uc0ac\uc77c\uc744 \uc815\ud558\ub294 \uac83\ucc98\ub7fc \ubc14\ub2e4\uc5d0\uc11c\ub294 \uc774\ub3d9\uc758 \ub54c\ub97c \uc0dd\uac01\ud574\uc57c \ud588\ub2e4. \uc774\uac83\uc740 \ud56d\uad6c\uac00 \uc790\uc5f0\uc758 \uc870\uac74\uc744 \ubb34\uc2dc\ud558\uace0 \uc5b8\uc81c\ub098 \uac19\uc740 \uc18d\ub3c4\ub85c \uc6c0\uc9c1\uc77c \uc218 \uc5c6\uc5c8\ub2e4\ub294 \ub73b\uc774\ub2e4. \ubb3c\uac74\uc744 \ud655\ubcf4\ud558\ub294 \uc77c\ubfd0 \uc544\ub2c8\ub77c \ucd9c\ud56d\uc744 \uae30\ub2e4\ub9ac\uace0 \ub2e4\ub978 \uc9c0\uc5ed\uacfc \ub54c\ub97c \ub9de\ucd94\ub294 \uacfc\uc815\ub3c4 \uc911\uc694\ud588\uc744 \uac83\uc774\ub2e4. \uc2e4\uc81c \ud56d\ud574\uc77c\uc815\uc744 \ucc3d\uc791\ud558\uc9c0 \uc54a\uc544\ub3c4 \uacc4\uc808\ud48d\uc774\ub77c\ub294 \uc870\uac74\uc5d0\uc11c \uad50\uc5ed\uc758 \ub9ac\ub4ec\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \ub3d9\uc544\ud504\ub9ac\uce74 \ud574\uc548\uc5d0\ub294 \uc544\ud504\ub9ac\uce74 \uc8fc\ubbfc\uacfc \uc544\ub78d\u00b7\ud398\ub974\uc2dc\uc544 \uc9c0\uc5ed\uc5d0\uc11c \uc628 \uc0ac\ub78c\ub4e4\uc774 \uad50\ub958\ud558\ub294 \ub3c4\uc2dc\ub4e4\uc774 \uc788\uc5c8\ub2e4. \uc2a4\uc640\ud790\ub9ac\uc5b4\ub294 \ubc18\ud22c\uacc4 \uc5b8\uc5b4\ub97c \ubc14\ud0d5\uc73c\ub85c \uc544\ub78d\uc5b4 \uc5b4\ud718 \ub4f1\uc758 \uc601\ud5a5\uc744 \ubc1b\uc73c\uba70 \ubc1c\uc804\ud588\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ubc30\uacbd\uc758 \uc0ac\ub78c\ub4e4\uc774 \uac70\ub798\ud558\uace0 \uc0dd\ud65c\ud558\ub294 \ub370 \uacf5\ud1b5\uc758 \ub9d0\uc774 \uc5ed\ud560\uc744 \ud588\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc774 \ub3c4\uc2dc\ub4e4\uc744 \uc678\ubd80\uc778\uc774 \ube48 \ub545\uc5d0 \uc138\uc6b4 \uc7a5\uc18c\ucc98\ub7fc \uc124\uba85\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc9c0\uc5ed \uacf5\ub3d9\uccb4\uc640 \ub0b4\ub959\uc758 \uc0dd\uc0b0, \ud574\uc548\uc758 \uad50\ud658\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \ubc14\ub2e4 \uac74\ub108\uc628 \uc0ac\ub78c\uc758 \uae30\ub85d\ub9cc \ubc14\ub77c\ubcf4\uba74 \ud56d\uad6c\uac00 \uae30\ub300\uace0 \uc788\ub358 \ud604\uc9c0\uc758 \uad00\uacc4\uc640 \ub178\ub3d9\uc740 \uc27d\uac8c \ubc30\uacbd\uc73c\ub85c \ubc00\ub824\ub09c\ub2e4. \uc2a4\uc640\ud790\ub9ac \ud574\uc548\uc758 \ub3c4\uc2dc\ub4e4\uc740 \uc11c\ub85c \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\uc9c0\ub9cc \uacbd\uc7c1\ud558\uae30\ub3c4 \ud588\ub2e4. \ud0ac\uc640\uc758 \uc601\ud5a5\ub825\uc5d0\uc11c \ubc97\uc5b4\ub098\ub824\ub294 \ub2e4\ub978 \ub3c4\uc2dc\uc758 \ud1b5\uce58\uc790\ub4e4\uc740 \ud3ec\ub974\ud22c\uac08 \uc138\ub825\uacfc \uad00\uacc4\ub97c \ub9fa\uc5c8\ub2e4. \uc18c\ud314\ub77c\uc758 \uc9c0\ubc30\uc790\ub3c4 16\uc138\uae30 \ucd08 \ud3ec\ub974\ud22c\uac08\uacfc \ud611\uc57d\uc744 \ub9fa\uc5c8\ub2e4\uace0 \uad50\uc7ac\ub294 \uc124\uba85\ud55c\ub2e4. \ub530\ub77c\uc11c \uc544\ud504\ub9ac\uce74 \ub3c4\uc2dc\ub4e4\uacfc \uc720\ub7fd\uc778\uc774 \ucc98\uc74c\ubd80\ud130 \ub450 \ub369\uc5b4\ub9ac\ub85c\ub9cc \ub9de\uc130\ub2e4\uace0 \ubcf4\uba74 \ub2f9\uc2dc\uc758 \uc120\ud0dd\uc744 \ub193\uce5c\ub2e4. \uac00\uae4c\uc6b4 \uacbd\uc7c1\uc790\ub97c \uacac\uc81c\ud558\ub824\ub294 \ud310\ub2e8\uacfc \uc678\ubd80 \uc138\ub825\uc758 \uad50\uc5ed \ud1b5\uc81c \uc695\uad6c\uac00 \uc5bd\ud614\ub2e4. \ud55c\ucabd\uc5d0 \ub3c4\uc6c0\uc774 \ub420 \uac83\ucc98\ub7fc \ubcf4\uc778 \uad00\uacc4\uac00 \uc774\ud6c4\uc5d0\ub3c4 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc720\uc9c0\ub41c\ub2e4\ub294 \ubcf4\uc7a5\uc740 \uc5c6\uc5c8\ub2e4. \ud3ec\ub974\ud22c\uac08\uc758 \uac1c\uc785\uc740 \ud1b5\uce58\uc790\ub97c \ubc14\uafb8\ub294 \ub370 \uadf8\uce58\uc9c0 \uc54a\uc558\ub2e4. \uad50\uc7ac\ub294 \ud0ac\uc640\uc5d0\uc11c \ubb3c\uac74\uc744 \ud3ec\ub974\ud22c\uac08 \ubc30\ub85c\ub9cc \uc6b4\ubc18\ud558\ub3c4\ub85d \ud55c \uc815\ucc45\uc774 \ud604\uc9c0 \uc0c1\uc778\ub4e4\uc5d0\uac8c \uc190\ud574\ub97c \uc8fc\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud56d\ud574 \uae30\uc220\ubfd0 \uc544\ub2c8\ub77c \uc5b4\ub5a4 \ubc30\ub97c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294\uc9c0\uac00 \uacbd\uc81c\uc758 \ubb38\uc81c\uac00 \ub41c \uac83\uc774\ub2e4. \uc774\ub294 \ud0ac\uc640\uc5d0\uc11c \uc124\uba85\ub41c \uc0ac\ub840\uc774\ubbc0\ub85c \uc18c\ud314\ub77c\uc758 \ub9e4\uc77c\uc758 \uc6b4\uc601\uc5d0 \uadf8\ub300\ub85c \uc62e\uaca8 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uac19\uc740 \uad50\uc5ed\uad8c\uc5d0\uc11c \uc6b4\uc1a1\uc744 \ud1b5\uc81c\ud558\ub294 \ud798\uc774 \uc5b4\ub5a4 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc5c8\ub294\uc9c0\ub294 \ubcf4\uc5ec \uc900\ub2e4. \ud56d\uad6c\uc758 \uc5ed\uc0ac\ub294 \ubb34\uc5c7\uc744 \uc2e4\uc5c8\ub294\uc9c0\ubfd0 \uc544\ub2c8\ub77c \ub204\uac00 \uc6b4\ubc18 \uc870\uac74\uc744 \uc815\ud588\ub294\uc9c0\ub3c4 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 1683\ub144 \uc18c\ud314\ub77c\uc758 \ubaa8\uc2b5\uc744 \ud45c\ud604\ud55c \ub9d0\ub808\uc758 \uc5ed\uc0ac \ub3c4\ud310\uc774\ub2e4. \ubb3c\uae38\uacfc \ubc29\uc5b4 \uc2dc\uc124, \uc8fc\ubcc0 \uac74\ubb3c\uc744 \uad00\ucc30\ud560 \uc218 \uc788\uc9c0\ub9cc \ud604\ub300 \uc9c0\ub3c4\ub098 \ub2f9\uc2dc\uc758 \ubaa8\ub4e0 \uc0dd\ud65c\uc744 \uae30\ub85d\ud55c \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \uc720\ub7fd \uc81c\uc791\uc790\uc758 \uc2dc\uc120\uacfc \ud45c\ud604 \ubc29\uc2dd\uc744 \uac70\uce5c \uc790\ub8cc\ub77c\ub294 \uc810\ub3c4 \uae30\uc5b5\ud560 \ub9cc\ud558\ub2e4. \uadf8\ub9bc\uc5d0 \ub0b4\ub959\uc758 \uc0dd\uc0b0\uc9c0\uac00 \uc548 \ubcf4\uc778\ub2e4\uace0 \ud56d\uad6c\uc640 \ubb34\uad00\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ud788\ub824 \ubc14\ub2e4 \ucabd\uc5d0\uc11c \uadf8\ub9b0 \uadf8\ub9bc\uc774 \ubb34\uc5c7\uc744 \uc798 \ubcf4\uc5ec \uc8fc\uace0 \ubb34\uc5c7\uc744 \ud654\uba74 \ubc16\uc73c\ub85c \ub0a8\uacbc\ub294\uc9c0 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \ud48d\uacbd\uc744 \ubcf4\ub294 \uc7ac\ubbf8\uc5d0 \ubb3c\uac74\uc758 \ucd9c\ubc1c\uc9c0\ub97c \ucc3e\ub294 \uad00\uc2ec\uc774 \ub354\ud574\uc9c4\ub2e4. \uc18c\ud314\ub77c\ub97c \uae30\uc5b5\ud560 \ub54c\ub294 \uae08\ube5b \ub3c4\uc2dc\ub97c \ub9c9\uc5f0\ud788 \uc0c1\uc0c1\ud558\uae30\ubcf4\ub2e4 \uae38\uc774 \ub9cc\ub098\ub294 \uc790\ub9ac\ub97c \ub5a0\uc62c\ub824 \ubcf4\uc790. \ub0b4\ub959\uc5d0\uc11c \uc628 \uc9d0\uacfc \uacc4\uc808\ud48d\uc744 \uae30\ub2e4\ub9ac\ub294 \ubc30, \uadf8 \uc0ac\uc774\ub97c \uc5f0\uacb0\ud55c \uc0ac\ub78c\ub4e4\uc758 \uac70\ub798\uac00 \uc788\uc5c8\ub2e4. \uc791\uc740 \ud574\uc548\uc120\uc740 \ud6e8\uc52c \ub113\uc740 \uad00\uacc4\uc758 \ud55c \ubd80\ubd84\uc774\uc5c8\ub2e4. \ub2e4\ub978 \ud56d\uad6c\ub97c \ubcfc \ub54c\ub3c4 \uac19\uc740 \uc9c8\ubb38\uc744 \ud574 \ubcfc \uc218 \uc788\ub2e4. \ubc30\uac00 \uc5b4\ub514\ub85c \uac00\ub294\uc9c0\ub9cc\uc774 \uc544\ub2c8\ub77c \uadf8 \ubc30\uc5d0 \uc2e4\ub9b0 \uac83\uc774 \uc5b4\ub514\uc5d0\uc11c \uc654\ub294\uac00. \uc18c\ud314\ub77c\ub294 \ubc14\ub2e4 \uc55e\uc5d0 \uc120 \ub3c4\uc2dc\uc774\uba74\uc11c, \ub4a4\ucabd\uc758 \uae34 \uc721\uc9c0 \uae38\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \uc774\ud574\ud560 \uc218 \uc788\ub294 \uc7a5\uc18c\uc600\ub2e4."}, {"id": "suez-canal-shortcut-and-power", "title": "\uc218\uc5d0\uc988 \uc6b4\ud558 \u2014 \uc9c0\ub984\uae38\uc740 \uc5b4\ub5bb\uac8c \uc81c\uad6d\uc758 \uae38\uc774 \ub418\uc5c8\uc744\uae4c", "summary": "1881\ub144 \uc2e4\uc81c \ub3c4\ud310\uc744 \ubcf4\uba70 \uc6b4\ud558 \uac74\uc124\uacfc \ub178\ub3d9, 1875\ub144 \uc9c0\ubd84 \ub9e4\uac01, \uc601\uad6d\uc758 \uac1c\uc785\uc73c\ub85c \uc774\uc5b4\uc9c4 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/suez-canal-shortcut-and-power/index.html", "image": "../media/suez-canal-shortcut-and-power.jpg", "alt": "1881\ub144 \uc5ed\uc0ac \ub3c4\ud310. \uc704\ucabd \uc9c0\uc911\ud574\uc640 \uc544\ub798\ucabd \ud64d\ud574\ub97c \uc787\ub294 \uc218\uc5d0\uc988 \uc6b4\ud558\uc758 \uacbd\ub85c.", "text": "\uc218\uc5d0\uc988 \uc6b4\ud558 \u2014 \uc9c0\ub984\uae38\uc740 \uc5b4\ub5bb\uac8c \uc81c\uad6d\uc758 \uae38\uc774 \ub418\uc5c8\uc744\uae4c 1869\ub144 \uc5f4\ub9b0 \ubb3c\uae38\uacfc \uc774\uc9d1\ud2b8\uc758 \uc8fc\uc2dd\u00b7\ubd80\ucc44\u00b7\uc8fc\uad8c 1881\ub144 \uc2e4\uc81c \ub3c4\ud310\uc744 \ubcf4\uba70 \uc6b4\ud558 \uac74\uc124\uacfc \ub178\ub3d9, 1875\ub144 \uc9c0\ubd84 \ub9e4\uac01, \uc601\uad6d\uc758 \uac1c\uc785\uc73c\ub85c \uc774\uc5b4\uc9c4 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ubc30\uac00 \uc720\ub7fd\uc5d0\uc11c \uc544\uc2dc\uc544\ub85c \uac00\ub824\uba74 \uc544\ud504\ub9ac\uce74 \ub0a8\ucabd\uc744 \ud06c\uac8c \ub3cc\uc544\uc57c \ud588\ub2e4. \uc9c0\uc911\ud574\uc640 \ud64d\ud574 \uc0ac\uc774\ub97c \uac00\ub85c\uc9c0\ub974\ub294 \ubb3c\uae38\uc774 \uc5f4\ub9b0\ub2e4\uba74 \ud56d\ub85c\uc758 \ubaa8\uc591\uc740 \ud06c\uac8c \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \uc9c0\ub3c4 \uc704\uc758 \uc9e7\uc740 \uc120 \ud558\ub098\uac00 \uc138\uacc4\uc758 \ubc30\uac00 \uc6c0\uc9c1\uc774\ub294 \ubc29\uc2dd\uc744 \ubc14\uafb8\ub294 \uc148\uc774\ub2e4. 1869\ub144 \uc218\uc5d0\uc988 \uc6b4\ud558\uac00 \uac1c\ud1b5\ud588\ub2e4. \ud558\uc9c0\ub9cc \uc0c8\ub85c\uc6b4 \uae38\uc744 \ub9cc\ub4e0 \uc5ed\uc0ac\ub294 \ubc30\uac00 \ud3b8\ub9ac\ud574\uc84c\ub2e4\ub294 \uc774\uc57c\uae30\ub85c\ub9cc \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc774\uc9d1\ud2b8\uc758 \ub178\ub3d9\uacfc \uc815\ubd80\uc758 \ube5a, \uc6b4\ud558 \ud68c\uc0ac\uc758 \uc9c0\ubd84\uacfc \uc720\ub7fd \uac15\ub300\uad6d\uc758 \uc774\ud574\uad00\uacc4\uac00 \uac19\uc740 \ubb3c\uae38\uc5d0 \ubaa8\uc600\ub2e4. \uc218\uc5d0\uc988 \uc9c0\ud611\uc740 \uc9c0\uc911\ud574\uc640 \ud64d\ud574 \uc0ac\uc774\ub97c \ub098\ub204\uace0 \uc788\uc5c8\ub2e4. \uc774\uacf3\uc5d0 \uc6b4\ud558\ub97c \ub9cc\ub4e4\uba74 \ubc30\ub294 \uc544\ud504\ub9ac\uce74 \ub0a8\ub2e8\uc744 \ub3cc\uc544\uac00\uc9c0 \uc54a\uace0 \uc778\ub3c4\uc591 \ubc29\ud5a5\uc73c\ub85c \ub098\uc544\uac08 \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc774\ub7f0 \uc5f0\uacb0\uc774 \ub0a8\uc544\uc2dc\uc544\uc640 \ub3d9\uc544\uc2dc\uc544\ub85c \uac00\ub294 \ubb34\uc5ed\uc744 \ud06c\uac8c \uc27d\uac8c \ud560 \uc218 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub2e4\ub9cc \uc9c0\ub3c4\uc5d0\uc11c \uc120\uc774 \uc9e7\uc544 \ubcf4\uc778\ub2e4\uace0 \uacf5\uc0ac\uae4c\uc9c0 \uac04\ub2e8\ud55c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ubb3c\uae38\uc744 \uc2e4\uc81c\ub85c \ud30c\uace0 \uc6b4\uc601\ud558\ub824\uba74 \ud5c8\uac00\uc640 \uc790\uae08, \uae30\uc220\uacfc \ub178\ub3d9\uc744 \ub9c8\ub828\ud574\uc57c \ud588\ub2e4. \uc9c0\ub9ac\uc801\uc778 \uac00\ub2a5\uc131\uc744 \ud604\uc2e4\uc758 \uae38\ub85c \ub9cc\ub4dc\ub294 \uacfc\uc815\uc5d0\ub294 \uc5ec\ub7ec \uc885\ub958\uc758 \uacb0\uc815\uc774 \ud544\uc694\ud588\ub2e4. 1854\ub144 \ud504\ub791\uc2a4\uc758 \uc678\uad50\uad00\uc774\uc790 \uc0ac\uc5c5\uac00 \ud398\ub974\ub514\ub0ad \ub4dc \ub808\uc149\uc2a4\ub294 \uc774\uc9d1\ud2b8\uc758 \uc0ac\uc774\ub4dc \ud30c\uc0e4\uc5d0\uac8c \uc6b4\ud558 \uac74\uc124 \ud5c8\uac00\ub97c \uc694\uccad\ud588\ub2e4. \ud5c8\uac00\ub97c \uc5bb\uc740 \ub4a4 \uc0ac\uc5c5\uc744 \ucd94\uc9c4\ud588\uace0 1859\ub144 \uacf5\uc0ac\uac00 \uc2dc\uc791\ub418\uc5c8\ub2e4. \uad6d\uc81c\uc801\uc778 \uae30\uc220\uacfc \uc790\uae08\uc758 \uad00\uc2ec\uc774 \uc774\uc9d1\ud2b8 \uc601\ud1a0 \uc704\uc5d0\uc11c \uad6c\uccb4\uc801\uc778 \uc0ac\uc5c5\uc774 \ub41c \uac83\uc774\ub2e4. \uc5ec\uae30\uc5d0\ub294 \uc720\ub7fd\uc778\uc758 \uacc4\ud68d\ub9cc \uc788\uc5c8\ub358 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc774\uc9d1\ud2b8 \ud1b5\uce58\uc790\uc758 \uc2b9\uc778\uacfc \uad6d\uac00\uc758 \uc790\uc6d0, \ud604\uc7a5\uc5d0\uc11c \uc77c\ud560 \uc0ac\ub78c\ub4e4\uc774 \ud544\uc694\ud588\ub2e4. \uc6b4\ud558\ub97c \uc720\uba85\ud55c \uc124\uacc4\uc790 \ud55c \uc0ac\ub78c\uc758 \uc791\ud488\ucc98\ub7fc \uc77d\uc73c\uba74 \uadf8 \uae38\uc774 \uc5b4\ub5a4 \uc815\uce58\uc801 \uad00\uacc4\uc640 \ub178\ub3d9 \uc704\uc5d0 \ub9cc\ub4e4\uc5b4\uc84c\ub294\uc9c0 \ub193\uce58\uae30 \uc27d\ub2e4. \uad50\uc7ac\ub294 \uc218\uc5d0\uc988 \uc6b4\ud558 \uc77c\ubd80\uc758 \uac74\uc124\uc5d0 \uc774\uc9d1\ud2b8\uc758 \uac15\uc81c \ub3d9\uc6d0 \ub178\ub3d9\uc774 \uc0ac\uc6a9\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc138\uacc4\uc758 \uad50\ud1b5\uc744 \ud3b8\ub9ac\ud558\uac8c \ub9cc\ub4dc\ub294 \uacf5\uc0ac\uc600\uc9c0\ub9cc \uadf8 \ud3b8\ub9ac\ud568\uc744 \ub9cc\ub4e0 \uc0ac\ub78c\ub4e4\uc758 \uacbd\ud5d8\uae4c\uc9c0 \uac00\ubcbc\uc6e0\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc30\uc758 \uc774\ub3d9 \uc2dc\uac04\uc774 \uc904\uc5b4\ub4dc\ub294 \ud6a8\uacfc\uc640 \ud604\uc7a5\uc758 \ubd80\ub2f4\uc740 \ub2e4\ub978 \uc790\ub9ac\uc5d0\uc11c \ub098\ud0c0\ub0ac\ub2e4. \uc774\ubc88 \uae00\uc740 \ud655\uc778\ud558\uc9c0 \uc54a\uc740 \uc0ac\ub9dd\uc790 \uc218\ub098 \ud2b9\uc815 \ub178\ub3d9\uc790\uc758 \ud558\ub8e8\ub97c \ucc3d\uc791\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub2e4\ub9cc \uac15\uc81c\ub85c \uc77c\uc744 \ud574\uc57c \ud588\ub358 \uc0ac\ub78c\ub4e4\uc774 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uac74\uc124\uc758 \uc911\uc694\ud55c \ubd80\ubd84\uc774\ub2e4. \uae30\ub150\ube44\uc801\uc778 \uae30\uc220\uc758 \uc5ed\uc0ac\ub97c \uc77d\uc744 \ub54c \ub204\uac00 \uc5b4\ub5a4 \uc870\uac74\uc73c\ub85c \uadf8\uac83\uc744 \ub9cc\ub4e4\uc5c8\ub294\uc9c0 \ud568\uaed8 \ubb3c\uc5b4\uc57c \ud55c\ub2e4. \uc6b4\ud558\ub294 1869\ub144 \uc120\ubc15 \ud1b5\ud589\uc5d0 \uc5f4\ub838\ub2e4. \uad50\uc7ac\uc5d0 \ub530\ub974\uba74 \uc601\uad6d\uc740 \ucc98\uc74c\ubd80\ud130 \uc774 \uc0ac\uc5c5\uc744 \ubc18\uae30\uae30\ub9cc \ud55c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc544\ud504\ub9ac\uce74 \ub0a8\ub2e8\uc744 \uc9c0\ub098\ub294 \uae30\uc874 \ud56d\ub85c\uc5d0\uc11c\uc758 \uc6b0\uc704\uc640, \uc778\ub3c4\uc5d0 \uc811\uadfc\ud558\ub294 \uae38\uc774 \ub2ec\ub77c\uc9c0\ub294 \ubb38\uc81c\uac00 \uc788\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4. \uc0c8 \uae38\uc740 \ubaa8\ub450\uc5d0\uac8c \uac19\uc740 \uc758\ubbf8\uac00 \uc544\ub2c8\uc5c8\ub2e4. \ub204\uad70\uac00\uc5d0\uac8c\ub294 \uc774\ub3d9\uc758 \ud6a8\uc728\uc774\uc9c0\ub9cc \ub2e4\ub978 \uc138\ub825\uc5d0\uac8c\ub294 \uae30\uc874\uc758 \uc6b0\uc704\uac00 \ud754\ub4e4\ub9b4 \uac00\ub2a5\uc131\uc774\uc5c8\ub2e4. \uc6b4\ud558\uac00 \uae30\uc220\uc801\uc73c\ub85c \uac00\ub2a5\ud55c\uac00\uc640 \ub204\uac00 \uadf8 \uae38\uc744 \uc720\ub9ac\ud558\uac8c \uc774\uc6a9\ud558\ub294\uac00\ub294 \ub2e4\ub978 \uc9c8\ubb38\uc774\uc5c8\ub2e4. \ubb3c\uae38\uc774 \uc5f4\ub9ac\ub294 \uc21c\uac04\uc5d0\ub3c4 \uacbd\uc7c1\uc758 \uc9c0\ub3c4\ub294 \ud568\uaed8 \uadf8\ub824\uc9c0\uace0 \uc788\uc5c8\ub2e4. \uc0ac\uc774\ub4dc\uc758 \ub4a4\ub97c \uc774\uc740 \uc774\uc2a4\ub9c8\uc77c \ud30c\uc0e4\ub294 \uc720\ub7fd\uc758 \ucc44\uad8c\uc790\ub4e4\uc5d0\uac8c \ud070 \ube5a\uc744 \uc9c0\uac8c \ub418\uc5c8\ub2e4. 1875\ub144 \uadf8\ub294 \uc774\uc9d1\ud2b8\uac00 \uac00\uc9c4 \uc6b4\ud558 \ud68c\uc0ac\uc758 \uc9c0\ubd84\uc744 \uc601\uad6d\uc5d0 \ud314\uc558\ub2e4. \uad50\uc7ac\ub294 \ubd80\ucc44\uac00 \uc774\uc9d1\ud2b8 \uc815\ubd80\uc5d0 \ub300\ud55c \uc720\ub7fd\uc758 \uc601\ud5a5\ub825\uc744 \ud0a4\uc6b0\ub294 \uc870\uac74\uc774 \ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc774\ub54c \uc6b4\ud558\uc758 \ubb3c\ub9ac\uc801\uc778 \uc18c\uc720\uc640 \ud68c\uc0ac \uc8fc\uc2dd, \uc815\ubd80\uc758 \uc8fc\uad8c\uc744 \ud55c \uac00\uc9c0\ub85c \uc11e\uc9c0 \uc54a\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \uc9c0\ubd84\uc744 \uc0c0\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uace7 \uadf8\ub0a0 \uc774\uc9d1\ud2b8 \uc804\uccb4\ub97c \uc601\ud1a0\ub85c \uc5bb\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \ud68c\uc0ac\uc640 \uad6d\uac00\uc758 \uc7ac\uc815 \uad00\uacc4\uac00 \uc815\uce58\uc801 \uac1c\uc785\uc758 \uae38\uc744 \ub113\ud614\ub2e4. \ubaa8\ub4e0 \ube5a\uc774 \uc6b4\ud558 \ud558\ub098 \ub54c\ubb38\uc5d0 \uc0dd\uacbc\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218\ub3c4 \uc5c6\ub2e4. \uc601\uad6d\uacfc \ud504\ub791\uc2a4\uc758 \uad00\ub9ac\ub4e4\uc774 \uc774\uc9d1\ud2b8\uc758 \uc7ac\uc815\uc5d0 \uad00\uc5ec\ud588\uace0 \uc678\uc138\uc758 \uc601\ud5a5\uc5d0 \ubc18\ubc1c\ud558\ub294 \uc6c0\uc9c1\uc784\ub3c4 \ucee4\uc84c\ub2e4. \uad50\uc7ac\ub294 \uc544\ud750\uba54\ub4dc \uc6b0\ub77c\ube44\uac00 \uc774\ub048 \ubc18\ubc1c\uacfc \ud1b5\uce58\uc790\ub97c \ub458\ub7ec\uc2fc \uac08\ub4f1, 1882\ub144 \uc601\uad6d\uc758 \uad70\uc0ac \uac1c\uc785\uc73c\ub85c \uc774\uc5b4\uc9c4 \uacfc\uc815\uc744 \uc124\uba85\ud55c\ub2e4. \uc774 \uc0ac\uac74\ub4e4\uc744 \uc6b4\ud558\ub97c \uc0c0\uc73c\ub2c8 \uc804\uc7c1\ub3c4 \uc790\ub3d9\uc73c\ub85c \ub530\ub77c\uc654\ub2e4\ub294 \ud55c \uc904\ub85c \uc904\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uad6d\ub0b4 \uc815\uce58\uc640 \ub300\uc678 \uad00\uacc4, \uc7ac\uc815\uacfc \uad70\uc0ac\uc758 \uc5ec\ub7ec \uc774\ud574\uad00\uacc4\uac00 \uc5bd\ud614\ub2e4. \ub2e4\ub9cc \uc138\uacc4\ub97c \uc787\ub294 \ubb3c\uae38\uacfc \uc774\uc9d1\ud2b8\uc758 \ub3c8 \ubb38\uc81c\uac00 \ud1b5\uce58\uc758 \ubb38\uc81c\ub85c \uae4a\uc774 \uc5f0\uacb0\ub418\uc5c8\ub2e4\ub294 \ud750\ub984\uc740 \ubd84\uba85\ud788 \ubcfc \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc2e4\uc81c \ub3c4\ud310\uc740 1881\ub144 \ubc31\uacfc\uc0ac\uc804\uc5d0 \ub098\uc628 \uc218\uc5d0\uc988 \uc6b4\ud558\uc758 \uacbd\ub85c\ub2e4. \uc704\ucabd \uc9c0\uc911\ud574\uc5d0\uc11c \uc544\ub798\ucabd \ud64d\ud574\ub85c \uc774\uc5b4\uc9c0\ub294 \uc120\uc744 \ub530\ub77c\uac00 \ubcf4\uc790. \uc0ac\ub78c\uacfc \ubc30\ubcf4\ub2e4 \uacbd\ub85c\uc758 \uc5f0\uacb0\uc744 \ud55c\ub208\uc5d0 \ubcf4\uac8c \ub9cc\ub4dc\ub294 \uadf8\ub9bc\uc774\ub2e4. \ud604\uc7ac\uc758 \uc6b4\ud558 \uc2dc\uc124\uc774\ub098 \ucd5c\uc2e0 \ud56d\ub85c \uc548\ub0b4\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc9c0\ub3c4\ub294 \uc544\ub2c8\ub2e4. \uadf8\ub9bc\uc774 \uc81c\uc791\ub41c \uc2dc\uc810\uc740 \uac1c\ud1b5 \ub4a4\uc774\uba74\uc11c \uc601\uad6d\uc758 1882\ub144 \uac1c\uc785\ubcf4\ub2e4\ub294 \uc55e\uc120 \ub54c\ub2e4. \ud55c \uc7a5\uc758 \uc9c0\ub9ac \uc790\ub8cc\ub3c4 \uc5b4\ub290 \uc2dc\uac04\uc5d0 \ub9cc\ub4e4\uc5b4\uc84c\ub294\uc9c0 \uc54c\uba74 \ub2e4\ub978 \uc5ed\uc0ac\uc801 \uc790\ub9ac\uc5d0 \ub193\uc778\ub2e4. \ub2e8\uc21c\ud55c \uc9c0\ub984\uae38\ucc98\ub7fc \ubcf4\uc774\ub294 \uc120 \uc704\uc5d0\uc11c \uadf8 \ubb34\ub835 \uc5b4\ub5a4 \uc120\ud0dd\ub4e4\uc774 \uc9c4\ud589\ub418\uace0 \uc788\uc5c8\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uc218\uc5d0\uc988 \uc6b4\ud558\ub294 \ubc14\ub2e4 \uc0ac\uc774\uc758 \uac70\ub9ac\ub97c \uc904\uc600\uc9c0\ub9cc \uadf8 \uc774\uc775\uacfc \ubd80\ub2f4\uc744 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ub098\ub204\uc9c0\ub294 \uc54a\uc558\ub2e4. \ud56d\ub85c\uac00 \uc9e7\uc544\uc9c4 \ubc30\uc640 \uac15\uc81c\ub85c \ub3d9\uc6d0\ub41c \ub178\ub3d9\uc790, \uc7ac\uc815\uc744 \ub9c8\ub828\ud558\ub824\ub358 \uc815\ubd80\uc640 \uc601\ud5a5\ub825\uc744 \ub113\ud78c \uac15\ub300\uad6d\uc740 \uac19\uc740 \uacf5\uc0ac\ub97c \uc11c\ub85c \ub2e4\ub974\uac8c \uacaa\uc5c8\ub2e4. \ub2e4\uc74c\uc5d0 \uc6b4\ud558\uc640 \ucca0\ub3c4 \uac19\uc740 \ud070 \uae38\uc744 \ubcf4\uba74 \uc5bc\ub9c8\ub098 \ube68\ub77c\uc84c\ub294\uc9c0\uc640 \ud568\uaed8 \ub204\uac00 \ub9cc\ub4e4\uace0 \ub204\uac00 \ud1b5\uc81c\ud588\ub294\uc9c0\ub3c4 \uc0b4\ud3b4\ubcf4\uc790. \uc218\uc5d0\uc988\uc758 \ubb3c\uae38\uc740 \uae30\uc220\uc758 \uc131\uacf5\uacfc \uae08\uc735\uc758 \uc5f0\uacb0, \uc815\uce58\uc801 \ud798\uc774 \ud55c \uc9c0\ub3c4 \uc704\uc5d0 \ub193\uc774\ub294 \uacfc\uc815\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uadf8\ub54c \uc9c0\ub984\uae38\uc758 \uc5ed\uc0ac\ub294 \uc138\uacc4\ub97c \uc774\ud574\ud558\ub294 \ud6e8\uc52c \uae34 \uc774\uc57c\uae30\uac00 \ub41c\ub2e4."}, {"id": "suzhou-grand-canal-and-city", "title": "\uc464\uc800\uc6b0 \u2014 \ubc30 \ud55c \ucc99\uc774 \ub3c4\uc2dc\uc758 \uae38\uc774 \ub418\ub358 \ud48d\uacbd", "summary": "\uccad\ub300 \uad81\uc815 \ud68c\ud654 \uc18d \uc464\uc800\uc6b0\uc758 \ubb3c\uae38\uc744 \ub530\ub77c \ub3c4\uc2dc\uc640 \ub300\uc6b4\ud558\uc758 \uc5f0\uacb0\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/suzhou-grand-canal-and-city/index.html", "image": "../media/suzhou-grand-canal-and-city.jpg", "alt": "\uac74\ub96d\uc81c\uc758 \ub0a8\ubc29 \uc21c\ud589 \uadf8\ub9bc \uc77c\ubd80\uc5d0 \ub098\ud0c0\ub09c \uc464\uc800\uc6b0\uc758 \ubc30\uc640 \ubb3c\uac00\uc758 \uc0ac\ub78c\ub4e4, \uac74\ubb3c.", "text": "\uc464\uc800\uc6b0 \u2014 \ubc30 \ud55c \ucc99\uc774 \ub3c4\uc2dc\uc758 \uae38\uc774 \ub418\ub358 \ud48d\uacbd \ud669\uc81c\uc758 \uc21c\ud589 \uadf8\ub9bc\uc5d0\uc11c \uc6b4\ud558\uc758 \uc77c\uc0c1\uc744 \ub4e4\uc5ec\ub2e4\ubcf4\ub2e4 \uccad\ub300 \uad81\uc815 \ud68c\ud654 \uc18d \uc464\uc800\uc6b0\uc758 \ubb3c\uae38\uc744 \ub530\ub77c \ub3c4\uc2dc\uc640 \ub300\uc6b4\ud558\uc758 \uc5f0\uacb0\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uae38\uc744 \uc124\uba85\ud560 \ub54c \uc6b0\ub9ac\ub294 \ub300\uac1c \uc624\ub978\ucabd\uc73c\ub85c \ub3cc\uc544 \uace8\ubaa9\uc744 \uc9c0\ub098\ub77c\uace0 \ub9d0\ud55c\ub2e4. \ud558\uc9c0\ub9cc \ubb3c\uae38\uc774 \uc0dd\ud65c \uae4a\uc219\uc774 \ub4e4\uc5b4\uc628 \ub3c4\uc2dc\ub77c\uba74 \ubc30\ub97c \uc5b4\ub514\uc5d0 \ub300\ub294\uc9c0\ub3c4 \uc911\uc694\ud55c \uc548\ub0b4\uac00 \ub41c\ub2e4. \uc911\uad6d \uc464\uc800\uc6b0\uc758 \uc61b \ud48d\uacbd\uc5d0\ub294 \uc9d1\uacfc \ub098\ubb34, \uc0ac\ub78c\uacfc \ubc30\uac00 \ubb3c\uac00\ub97c \uc911\uc2ec\uc73c\ub85c \ub098\ub780\ud788 \ub193\uc5ec \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc5d0\uc11c\ub294 \ucee4\ub2e4\ub780 \ubc30\ub97c \uba3c\uc800 \ucc3e\uac8c \ub41c\ub2e4. \uadf8\ub2e4\uc74c\uc5d0\ub294 \uae30\uc2ad\uc5d0 \uc120 \uc0ac\ub78c\ub4e4\uacfc \uac74\ubb3c \uc0ac\uc774\ub97c \ucc9c\ucc9c\ud788 \ubcf4\uc790. \ud669\uc81c\uc758 \uc5ec\ud589\uc744 \uae30\ub150\ud55c \uc7a5\uba74\uc774\uc9c0\ub9cc, \ub208\uae38\uc744 \uc870\uae08 \uc62e\uae30\uba74 \ubb3c\uc744 \uae38\ub85c \uc0bc\uc740 \ub3c4\uc2dc\uac00 \uc5b4\ub5bb\uac8c \ubcf4\uc600\ub294\uc9c0\ub3c4 \uc77d\uc744 \uc218 \uc788\ub2e4. \uc774 \ub3c4\ud310\uc740 \uac74\ub96d\uc81c\uc758 \ub0a8\ubc29 \uc21c\ud589\uc744 \uadf8\ub9b0 \uae34 \ub450\ub8e8\ub9c8\ub9ac \uac00\uc6b4\ub370 \uc464\uc800\uc6b0\ub85c \ub4e4\uc5b4\uc624\ub294 \uc7a5\uba74\uc758 \uc77c\ubd80\ub2e4. 1751\ub144\uc758 \uc5ec\ud589\uc744 \uae30\ub150\ud574 18\uc138\uae30 \uad81\uc815 \ud654\uac00\uac00 \uc81c\uc791\ud55c \uadf8\ub9bc\uc73c\ub85c \uad50\uc7ac\uc5d0 \uc18c\uac1c\ub418\uc5b4 \uc788\ub2e4. \uc5ec\ud589\ud55c \ub54c\uc640 \uadf8\ub9bc\uc744 \uc644\uc131\ud55c \ub54c\ub294 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \uc0ac\uc9c4\ucc98\ub7fc \uc6b0\uc5f0\ud788 \ud3ec\ucc29\ud55c \ud558\ub8e8\ub3c4 \uc544\ub2c8\ub2e4. \ud1b5\uce58\uc790\uc758 \uc774\ub3d9\uc744 \uae30\ub85d\ud558\uace0 \uae30\ub150\ud558\ub824\ub294 \ubaa9\uc801\uc774 \uc788\ub294 \uad81\uc815 \ud68c\ud654\ub2e4. \ud654\uba74\uc758 \uc7a5\uba74\uc744 \uc790\uc138\ud788 \ubcfc \uc218 \uc788\uc73c\uba74\uc11c\ub3c4, \uadf8 \ubaa8\uc2b5\uc774 \ub2f9\uc2dc \uc8fc\ubbfc\uc758 \ud558\ub8e8\ub97c \uc544\ubb34\ub7f0 \uc120\ud0dd \uc5c6\uc774 \ubcf4\uc5ec \uc900\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc774 \uadf8\ub9bc\uc744 \uc77d\ub294 \uccab\uac78\uc74c\uc774\ub2e4. \uadf8\ub9bc \ud55c\uac00\uc6b4\ub370 \ud070 \ubc30\uac00 \uc788\uace0 \uc591\ucabd\uc5d0\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc11c \uc788\ub2e4. \uac74\ubb3c\uc740 \ubb3c\uc744 \uba40\ub9ac \ubc00\uc5b4\ub0b4\uc9c0 \uc54a\uace0 \uae30\uc2ad\uc744 \ub530\ub77c \uac00\uae4c\uc774 \ub193\uc5ec \uc788\ub2e4. \ubc30\uac00 \ub3c4\uc2dc \ubc14\uae65\uc5d0 \uc7a0\uc2dc \uc815\ubc15\ud55c \uc7a5\uba74\uc774\ub77c\uae30\ubcf4\ub2e4, \ubb3c\uae38\uc774 \uc2dc\uac00\uc9c0\uc758 \uc911\uc694\ud55c \ud1b5\ub85c\ub77c\ub294 \ub290\ub08c\uc744 \uc900\ub2e4. \uc5ec\uae30\uc11c \uad00\uc2ec\uc744 \ubc30 \ud55c \ucc99\uc5d0\uc11c \ubb3c\uacfc \uc721\uc9c0\uc758 \uc811\uc810\uc73c\ub85c \uc62e\uaca8 \ubcf4\uc790. \uc0ac\ub78c\uc774 \ubaa8\uc778 \uae30\uc2ad\uacfc \uac74\ubb3c\ub85c \uc774\uc5b4\uc9c0\ub294 \uae38, \ubc30\uac00 \ub2e4\uac00\uac08 \uc218 \uc788\ub294 \uc790\ub9ac\uac00 \ud568\uaed8 \ubcf4\uc778\ub2e4. \ub3c4\uc2dc\uc758 \ubb3c\uae38\uc740 \uacbd\uce58\uac00 \uc544\ub984\ub2e4\uc6b4 \uacf5\uac04\uc774\uba74\uc11c \uc0ac\ub78c\uacfc \ubb3c\uac74\uc774 \ub9cc\ub098\ub294 \uc2e4\uc6a9\uc801\uc778 \uc790\ub9ac\uc774\uae30\ub3c4 \ud588\ub2e4. \ub208\uc744 \ubb3c\uac00\uc758 \uc791\uc740 \uc778\ubb3c\ub4e4\ub85c \uc62e\uae30\uba74 \ud654\uba74\uc744 \uc77d\ub294 \uc18d\ub3c4\ub3c4 \ub290\ub824\uc9c4\ub2e4. \ucee4\ub2e4\ub780 \ubc30\ub97c \ub2e8\ubc88\uc5d0 \uc54c\uc544\ubcf4\ub294 \uac83\uacfc \ub2ec\ub9ac, \uc904\uc9c0\uc5b4 \uc120 \uc0ac\ub78c\uacfc \ub0ae\uc740 \uc9c0\ubd95\uc740 \ud55c \ubd80\ubd84\uc529 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ub450\ub8e8\ub9c8\ub9ac\uc758 \uc7ac\ubbf8\ub294 \uc774\ub807\uac8c \uc2dc\uc120\uc744 \uc62e\uae38 \ub54c \uc8fc\uc778\uacf5 \ub4a4\uc758 \ub3c4\uc2dc\uac00 \uc870\uae08\uc529 \ub4dc\ub7ec\ub09c\ub2e4\ub294 \ub370\ub3c4 \uc788\ub2e4. \uc911\uad6d\uc758 \ud070 \uac15\ub4e4\uc740 \ub300\uccb4\ub85c \ub3d9\ucabd \ubc14\ub2e4\ub97c \ud5a5\ud574 \ud750\ub978\ub2e4. \ubc18\uba74 \ub113\uc740 \ub098\ub77c \uc548\uc5d0\uc11c\ub294 \ub0a8\ucabd\uacfc \ubd81\ucabd\uc744 \uc787\ub294 \uc774\ub3d9\ub3c4 \ud544\uc694\ud588\ub2e4. \uc9c0\uc5ed\ub9c8\ub2e4 \uc0dd\uc0b0\ud558\ub294 \uace1\ubb3c\uacfc \uae30\ud6c4\uac00 \ub2ec\ub790\uace0, \ubd81\ucabd\uc758 \ud070 \ub3c4\uc2dc\uc640 \uad8c\ub825 \uc911\uc2ec\uc5d0\ub294 \uc9c0\uc18d\uc801\uc778 \ubb3c\uc790 \uacf5\uae09\uc774 \ud544\uc694\ud588\ub2e4. \ub300\uc6b4\ud558\ub294 \uc774\ub7f0 \ubc29\ud5a5\uc758 \ucc28\uc774\ub97c \uc0ac\ub78c\uc758 \uc190\uc73c\ub85c \uc5f0\uacb0\ud55c \uac70\ub300\ud55c \ubb3c\uae38 \uccb4\uacc4\uc600\ub2e4. \ud55c \uc655\uc774 \uc5b4\ub290 \ub0a0 \ube48 \ub545\uc5d0 \ucc98\uc74c\ubd80\ud130 \ub05d\uae4c\uc9c0 \uadf8\uc5c8\ub2e4\uae30\ubcf4\ub2e4, \uc55e\uc120 \uc218\ub85c\ub97c \uc5ec\ub7ec \uc2dc\ub300\uc5d0 \uac78\uccd0 \uc5f0\uacb0\ud558\uace0 \uace0\uce58\uba70 \ud655\ub300\ud588\ub2e4. \uc9c0\ub3c4 \uc704\uc758 \ud55c \uc904\uc5d0\ub294 \uc11c\ub85c \ub2e4\ub978 \uc2dc\uae30\uc758 \uacf5\uc0ac\uc640 \ubaa9\uc801\uc774 \uacb9\uccd0 \uc788\ub2e4. \uc300\uc774\ub098 \ubc00 \uac19\uc740 \ubb3c\uac74\uc744 \ub9ce\uc774 \uc62e\uae30\ub824\uba74 \uc6b4\ubc18 \uc790\uccb4\uac00 \uc911\uc694\ud55c \ubb38\uc81c\uac00 \ub41c\ub2e4. \ud55c \uc0ac\ub78c\uc774 \ub4dc\ub294 \uc9d0\uacfc \ubc30\uc5d0 \uc2e4\uc5b4 \ubcf4\ub0b4\ub294 \uc9d0\uc740 \uac00\ub2a5\ud55c \uaddc\ubaa8\uac00 \ub2e4\ub974\ub2e4. \ub300\uc6b4\ud558\ub294 \ub0a8\ubd81\uc758 \uc2dd\ub7c9\uacfc \ubb3c\uc790 \uc774\ub3d9\uc744 \uac00\ub2a5\ud558\uac8c \ud558\uba70 \ub5a8\uc5b4\uc9c4 \uc9c0\uc5ed\uc758 \uacbd\uc81c\ub97c \uc5f0\uacb0\ud588\ub2e4. \ub3c4\uc2dc\ub294 \uc790\uae30 \uc548\uc5d0\uc11c \ub9cc\ub4e0 \uac83\ub9cc\uc73c\ub85c \uc0b4\uc544\uac00\uc9c0 \uc54a\ub294\ub2e4. \uba3c \uacf3\uc758 \uc0dd\uc0b0\uc774 \ub3c4\ucc29\ud558\uace0 \ub3c4\uc2dc\uc758 \ud544\uc694\uac00 \ub2e4\uc2dc \ub2e4\ub978 \uacf3\uc73c\ub85c \uc804\ud574\uc9c4\ub2e4. \ubb3c\uae38 \uc606\uc758 \uc9d1\ub4e4\uc744 \ubcf4\uba74\uc11c \uc791\uc740 \ub9c8\uc744 \uac19\uc740 \uce5c\uadfc\ud568\uc744 \ub290\ub084 \uc218 \uc788\uc9c0\ub9cc, \uadf8 \ubc30\uacbd\uc5d0\ub294 \ud6e8\uc52c \ub113\uc740 \ubc94\uc704\uc758 \uacf5\uae09\uacfc \uc18c\ube44\uac00 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub358 \uc148\uc774\ub2e4. \uad50\uc7ac\ub294 \uc218\ub098\ub77c\uc758 \ub300\uaddc\ubaa8 \uc218\ub85c \uacf5\uc0ac\uc5d0 \uac15\uc81c\ub85c \ub3d9\uc6d0\ub41c \ub178\ub3d9\uc774 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub0a8\ubd81\uc744 \uc787\ub294 \uc2dc\uc124\uc740 \ubb3c\uc790\ub97c \ud3b8\ub9ac\ud558\uac8c \uc62e\uae30\ub294 \ud1b5\ub85c\uc600\uc9c0\ub9cc, \uadf8\uac83\uc744 \ub9cc\ub4dc\ub294 \uacfc\uc815\uae4c\uc9c0 \ubaa8\ub450\uc5d0\uac8c \uc88b\uc740 \uacbd\ud5d8\uc774\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc6b4\ud558\uc758 \uc131\uacfc\uc640 \uac74\uc124\uc758 \ubd80\ub2f4\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc644\uc131\ub41c \ud48d\uacbd\uc5d0\uc11c\ub294 \uacf5\uc0ac \ud604\uc7a5\uacfc \ucc38\uc5ec\ud55c \uc0ac\ub78c\uc758 \uc774\ub984\uc774 \ubcf4\uc774\uc9c0 \uc54a\uc744 \ub54c\uac00 \ub9ce\ub2e4. \ubb3c \uc704\ub97c \uc774\ub3d9\ud558\ub294 \ud669\uc81c\uc758 \ubc30\uac00 \ub208\uae38\uc744 \ub04c\uc218\ub85d, \uadf8 \uc774\ub3d9\uc744 \uac00\ub2a5\ud558\uac8c \ud55c \uae38\uc740 \ub204\uac00 \ub9cc\ub4e4\uace0 \uc720\uc9c0\ud588\uc744\uae4c\ub77c\ub294 \uc9c8\ubb38\ub3c4 \ub0a8\uaca8 \ub458 \uc218 \uc788\ub2e4. \uadf8\ub9bc\uc758 \uc544\ub984\ub2e4\uc6c0\uc744 \uac10\uc0c1\ud558\ub294 \uc77c\uacfc \uadf8\ub7f0 \uc9c8\ubb38\uc740 \ucda9\ub3cc\ud558\uc9c0 \uc54a\ub294\ub2e4. \uadf8\ub9bc\uc758 \ud070 \ubc30\ub294 \ud2b9\ubcc4\ud55c \uc21c\ud589\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc774 \ubc30\uc758 \uc7a5\uc2dd\uacfc \ud06c\uae30\ub97c \ub2f9\uc2dc \ubaa8\ub4e0 \uc6b4\ubc18\uc120\uc758 \ud45c\uc900\uc73c\ub85c \uc774\ud574\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc606\uc758 \uc791\uc740 \ubc30\uc640 \uae30\uc2ad\uc758 \uc0ac\ub78c\ub4e4\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubcf4\uba74 \ud55c \ud654\uba74 \uc548\uc5d0\uc11c\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc5ed\ud560\uacfc \uaddc\ubaa8\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \ud654\uac00\ub294 \uc5b4\ub5a4 \uc7a5\uba74\uc744 \uae38\uac8c \ubcf4\uc5ec \uc8fc\uace0 \ubb34\uc5c7\uc744 \ud654\uba74\uc5d0\uc11c \ub35c\uc5b4 \ub0c8\uc744\uae4c. \uc774 \uc9c8\ubb38\uc744 \uac00\uc9c0\uace0 \ubcf4\uba74 \ub450\ub8e8\ub9c8\ub9ac\ub294 \ub2e8\uc21c\ud55c \ub3c4\uc2dc \uc548\ub0b4\ub3c4\uac00 \uc544\ub2c8\ub77c \ub3c4\uc2dc\ub97c \ubc14\ub77c\ubcf4\ub294 \ud55c \ubc29\uc2dd\uc774 \ub41c\ub2e4. \ub2f9\uc2dc\uc758 \uc464\uc800\uc6b0\ub97c \uad81\uae08\ud574\ud558\ub294 \ub9c8\uc74c\uacfc \uad81\uc815\uc774 \ubcf4\uc5ec \uc8fc\ub824 \ud55c \uc464\uc800\uc6b0\ub97c \uc77d\ub294 \uc77c\uc774 \ud568\uaed8 \uc2dc\uc791\ub41c\ub2e4. \uad50\uc7ac\ub294 \uadf8\ub9bc \uc18d \uc6b4\ud558 \uad6c\uac04\uc774 \uc624\ub298\ub0a0\uc5d0\ub294 \ub2f9\uc2dc\ucc98\ub7fc \uc4f0\uc774\uc9c0 \uc54a\ub294 \uacf3\uc774\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \uc774 \ub3c4\ud310\ub9cc \ub4e4\uace0 \ud604\uc7ac\uc758 \ubc30\ud3b8\uc774\ub098 \uc0b0\ucc45\ub85c\ub97c \uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc61b \ubb3c\uae38\uacfc \uc9c0\uae08\uc758 \ub3c4\uc2dc\ub97c \ube44\uad50\ud558\ub824\uba74 \ubcc4\ub3c4\uc758 \ud604\uc7ac \uc790\ub8cc\uac00 \ud544\uc694\ud558\ub2e4. \uadf8 \ub300\uc2e0 \uc774 \uadf8\ub9bc\uc740 \ub3c4\uc2dc\ub97c \uc774\ud574\ud558\ub294 \uc2dc\uc120\uc744 \ub113\ud600 \uc900\ub2e4. \uae38\uc740 \uc5b8\uc81c\ub098 \uc544\uc2a4\ud314\ud2b8\uc77c \ud544\uc694\uac00 \uc5c6\uace0, \uac74\ubb3c\uc758 \uc815\uba74\uc740 \ucc28\ub3c4\ub9cc \ud5a5\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc464\uc800\uc6b0\uc758 \ubc30\uc640 \uae30\uc2ad\uc744 \ucc9c\ucc9c\ud788 \ubcf4\uace0 \ub098\uba74 \ub0af\uc120 \uc61b \ud48d\uacbd\uc5d0\uc11c \uc6b0\ub9ac\uac00 \uc0ac\ub294 \ub3c4\uc2dc\uc5d0\ub3c4 \ud544\uc694\ud55c \uc9c8\ubb38\uc774 \ub5a0\uc624\ub978\ub2e4. \uc624\ub298\uc758 \uc0dd\ud65c\uc740 \uc5b4\ub5a4 \uae38\uc744 \ud1b5\ud574 \ub2e4\ub978 \uacf3\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\uc744\uae4c."}, {"id": "sydney-cove-1788-fleet-and-shore", "title": "\uc2dc\ub4dc\ub2c8 \ucf54\ube0c 1788 \u2014 \ubc30\uac00 \ub3c4\ucc29\ud588\ub2e4\uace0 \uc5ed\uc0ac\uac00 \uc2dc\uc791\ub41c \uac83\uc740 \uc544\ub2c8\ub2e4", "summary": "\uc601\uad6d \uc120\ub2e8\uc758 \ub3c4\ucc29\uacfc \uc815\ucc29 \ub178\ub3d9\uc744 \uae30\uc874 \uc8fc\ubbfc\uc758 \uc5ed\uc0ac \ubc0f \uae30\ub85d\uc790\uc758 \uc785\uc7a5\uacfc \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/sydney-cove-1788-fleet-and-shore/index.html", "image": "../media/sydney-cove-1788-fleet-and-shore.png", "alt": "\ud604\ub300 \uac74\ubb3c\uc774 \uc5c6\ub294 \uc2dc\ub4dc\ub2c8 \ucf54\ube0c \ud574\uc548\uacfc \ucd08\uae30 \uc120\ub2e8\uc744 \uadf8\ub9b0 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uc2dc\ub4dc\ub2c8 \ucf54\ube0c 1788 \u2014 \ubc30\uac00 \ub3c4\ucc29\ud588\ub2e4\uace0 \uc5ed\uc0ac\uac00 \uc2dc\uc791\ub41c \uac83\uc740 \uc544\ub2c8\ub2e4 \uccab \uc120\ub2e8\uc758 \ud56d\ud574\u00b7\uc815\ucc29 \ub178\ub3d9\u00b7\uc6d0\uc8fc\ubbfc \uc811\ucd09\uc744 \uae30\ub85d\uc790\uc758 \uc2dc\uc120\uacfc \ud568\uaed8 \uc77d\uae30 \uc601\uad6d \uc120\ub2e8\uc758 \ub3c4\ucc29\uacfc \uc815\ucc29 \ub178\ub3d9\uc744 \uae30\uc874 \uc8fc\ubbfc\uc758 \uc5ed\uc0ac \ubc0f \uae30\ub85d\uc790\uc758 \uc785\uc7a5\uacfc \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc624\ub298\uc758 \uc2dc\ub4dc\ub2c8\ub97c \ub5a0\uc62c\ub9ac\uba74 \ud56d\uad6c\uc640 \uc624\ud398\ub77c\ud558\uc6b0\uc2a4\uac00 \uba3c\uc800 \ubcf4\uc774\uc9c0\ub9cc 1788\ub144\uc758 \ub9cc\uc5d0\ub294 \uc804\ud600 \ub2e4\ub978 \ubc30\ub4e4\uc774 \ub4e4\uc5b4\uc654\ub2e4. \uc601\uad6d\uc5d0\uc11c \uc8c4\uc218\uc640 \ud574\ubcd1\ub300, \uad00\ub9ac\uc640 \ubb3c\uc790\ub97c \uc2e4\uc5b4 \uc628 \uc120\ub2e8\uc774\uc5c8\ub2e4. \uc774 \ub3c4\ucc29\uc740 \uc774\ud6c4 \ub3c4\uc2dc\uc758 \ud615\uc131\uc5d0 \uc911\uc694\ud55c \uc0ac\uac74\uc774\uc9c0\ub9cc \uadf8 \ub545\uc5d0 \uc0ac\ub78c\uc774 \ucc98\uc74c \ub098\ud0c0\ub09c \uc21c\uac04\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc0c8 \uc815\ucc29\uc9c0\uc5d0 \uad00\ud55c \uae30\ub85d\uc744 \ub0a8\uae34 \ud574\ubcd1\ub300 \uc7a5\uad50 \uc653\ud0a8 \ud150\uce58\uc758 \uae00\uc744 \ub530\ub77c\uac00\uba74 \uae34 \ud56d\ud574\uc640 \uc7a5\uc18c \uc120\ud0dd, \ubb3c\uacfc \uc2dd\ub7c9\uc758 \ubb38\uc81c\ub97c \uad6c\uccb4\uc801\uc73c\ub85c \ubcfc \uc218 \uc788\ub2e4. \ub3d9\uc2dc\uc5d0 \uadf8\uc758 \uae00\uc774 \ub3c4\ucc29\ud55c \uc0ac\ub78c\uc758 \uc2dc\uc120\uc774\ub77c\ub294 \uc810\ub3c4 \uae30\uc5b5\ud574\uc57c \ud55c\ub2e4. \ud56d\uad6c\uc5d0\ub294 \uc11c\ub85c \ub2e4\ub978 \uc0b6\uc758 \uc2dc\uac04\uc774 \ub9cc\ub098\uace0 \uc788\uc5c8\ub2e4. 1787\ub144 \uc601\uad6d\uc744 \ub5a0\ub09c \uccab \uc120\ub2e8\uc5d0\ub294 \uc790\uc2e0\uc758 \ub73b\ub300\ub85c \uc0c8\ub85c\uc6b4 \uc0b6\uc744 \ucc3e\uc544\uac00\ub294 \uc5ec\ud589\uc790\ub9cc \uc788\uc5c8\ub358 \uac83\uc774 \uc544\ub2c8\ub2e4. \ud615\uc744 \uc9d1\ud589\ubc1b\uae30 \uc704\ud574 \uc774\uc1a1\ub418\ub294 \uc8c4\uc218\ub4e4\uc774 \uc788\uc5c8\uace0 \uadf8\ub4e4\uc744 \uad00\ub9ac\ud560 \uad70\uc778\uacfc \uc2dd\ubbfc\uc9c0 \uc6b4\uc601\uc744 \ub9e1\uc740 \uc0ac\ub78c\ub4e4\uc774 \ud568\uaed8 \uac14\ub2e4. \uac19\uc740 \ubc30\ub97c \ud0c0\ub3c4 \uc774\ub3d9\uc758 \uc758\ubbf8\uc640 \uac00\uc9c4 \uad8c\ud55c\uc774 \ub2ec\ub790\ub2e4. \uc774 \ucc28\uc774\ub97c \uc9c0\uc6b0\uba74 \uc815\ucc29\uc758 \uc5ed\uc0ac\ub294 \uc6a9\uae30 \uc788\ub294 \uac1c\ucc99\uc790\ub4e4\uc758 \ubaa8\ud5d8\uc73c\ub85c\ub9cc \ub0a8\uae30 \uc27d\ub2e4. \ub204\uad70\uac00\ub294 \uba85\ub839\uc744 \ub0b4\ub9ac\uace0 \ub204\uad70\uac00\ub294 \uadf8 \uba85\ub839\uc5d0 \ub530\ub77c \uba3c \uacf3\uc73c\ub85c \uc62e\uaca8\uc84c\ub2e4. \uc0c8 \ub3c4\uc2dc\uc758 \ucd9c\ubc1c\uc744 \uc77d\uc744 \ub54c\uc5d0\ub294 \ud48d\uacbd\uc758 \ubcc0\ud654\ubfd0 \uc544\ub2c8\ub77c \ubc30 \uc548\uc758 \uc704\uacc4\uc640 \uac15\uc81c\uc131\ub3c4 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc120\ub2e8\uc740 \uc601\uad6d\uc5d0\uc11c \ud638\uc8fc\ub85c \uace7\ubc14\ub85c \uac74\ub108\uac04 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc5ec\ub7ec \uae30\ud56d\uc9c0\ub97c \uac70\uce58\uba70 \ubcf4\uae09\ud558\uace0 \uc218\ub9ac\ud558\uace0 \uc0ac\ub78c\ub4e4\uc758 \uac74\uac15\uc744 \uc0b4\ud3b4\uc57c \ud588\ub2e4. \ud150\uce58\uc758 \uae30\ub85d\uc5d0\ub3c4 \ub300\uc11c\uc591\uacfc \ub2e4\ub978 \uc9c0\uc5ed\uc5d0\uc11c \ubcf4\ub0b8 \uc2dc\uac04\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ubaa9\uc801\uc9c0\uc758 \uc5ed\uc0ac\ub294 \ub3c4\ucc29 \uc774\uc804\uc758 \uae34 \uc774\ub3d9\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc9c0\uae08\uc758 \uc9c0\ub3c4\uc5d0\uc11c\ub294 \uc120 \ud558\ub098\ub85c \uc774\uc5b4\uc9c0\ub294 \uae38\uc774 \ub2f9\uc2dc\uc5d0\ub294 \uc2dd\ub7c9\uacfc \ubb3c, \ubc14\ub78c\uacfc \uc9c8\ubcd1\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c0\ub294 \uc0dd\ud65c\uc774\uc5c8\ub2e4. \uc5bc\ub9c8\ub098 \uba40\ub9ac \uac14\ub294\uc9c0\uc758 \uc22b\uc790\ubcf4\ub2e4 \uadf8 \uc548\uc5d0\uc11c \ub9ce\uc740 \uc0ac\ub78c\uc774 \ub9e4\uc77c \uba39\uace0 \uc9c0\ub0b4\uc57c \ud588\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc911\uc694\ud558\ub2e4. \uc120\ub2e8\uc744 \uc6c0\uc9c1\uc774\ub294 \uac83\uc740 \ud56d\ud574 \uae30\uc220\ub9cc\uc774 \uc544\ub2c8\ub77c \ubcf4\uae09\uacfc \uad00\ub9ac\uc758 \uccb4\uacc4\uc774\uae30\ub3c4 \ud588\ub2e4. 1788\ub144 1\uc6d4 \uc120\ub2e8\uc740 \ubcf4\ud130\ub2c8\ubca0\uc774\uc5d0 \ub3c4\ucc29\ud588\uc9c0\ub9cc \uc815\ucc29\uc9c0\ub294 \uadf8\uacf3\uc5d0 \uadf8\ub300\ub85c \uc815\ud574\uc9c0\uc9c0 \uc54a\uc558\ub2e4. \uc544\uc11c \ud544\ub9bd \ucd1d\ub3c5 \uc77c\ud589\uc740 \uc8fc\ubcc0\uc744 \uc870\uc0ac\ud55c \ub4a4 \ud3ec\ud2b8\uc7ad\uc2a8\uc73c\ub85c \uc62e\uacbc\uace0 \uc2dc\ub4dc\ub2c8 \ucf54\ube0c\uc5d0 \ud130\ub97c \uc7a1\uc558\ub2e4. \uc9c0\uba85 \ud558\ub098\ub97c \uc54c\uace0 \ub3c4\ucc29\ud558\ub294 \uac83\uacfc \uc2e4\uc81c\ub85c \uc624\ub798 \uba38\ubb3c \uc790\ub9ac\ub97c \uace0\ub974\ub294 \uc77c\uc740 \ub2ec\ub790\ub2e4. \ubc30\ub97c \uc548\uc804\ud558\uac8c \ub308 \uc218 \uc788\ub294\uc9c0, \ubb3c\uc744 \uad6c\ud560 \uc218 \uc788\ub294\uc9c0, \uc0ac\ub78c\uacfc \ubb3c\uc790\ub97c \uc5b4\ub514\uc5d0 \ub193\uc744\uc9c0\uac00 \uc911\uc694\ud588\ub2e4. \ud56d\uad6c\uac00 \uc544\ub984\ub2f5\ub2e4\ub294 \uac10\uc0c1\ub9cc\uc73c\ub85c \ud574\uacb0\ud560 \uc218 \uc5c6\ub294 \uc9c8\ubb38\ub4e4\uc774\ub2e4. \ub3c4\uc2dc\uc758 \uc2dc\uc791\uc740 \ud070 \uc774\uc0c1\uc744 \uc120\uc5b8\ud558\ub294 \uc21c\uac04\ubfd0 \uc544\ub2c8\ub77c \uc774\ub7f0 \uad6c\uccb4\uc801\uc778 \uc870\uac74\uc744 \ube44\uad50\ud558\ub294 \uacfc\uc815\uc5d0\ub3c4 \uc788\uc5c8\ub2e4. \ubc30\uac00 \ub2fb\uc744 \ub0b4\ub838\ub2e4\uace0 \uc0dd\ud65c\uc774 \uace7\ubc14\ub85c \uc548\uc815\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc721\uc9c0\uc5d0 \ud544\uc694\ud55c \uacf5\uac04\uc744 \ub9cc\ub4e4\uace0 \uac00\uc838\uc628 \ubb3c\uc790\ub97c \ubc30\uce58\ud558\uba70 \uba39\uace0 \uc798 \ubc29\ubc95\uc744 \ub9c8\ub828\ud574\uc57c \ud588\ub2e4. \ubc8c\ubaa9\uacfc \uac74\uc124, \uc2dd\ub7c9\uc744 \ub2e4\ub8e8\ub294 \ubc18\ubcf5\uc801\uc778 \uc77c\uc774 \uc774\uc5b4\uc84c\ub2e4. \uc9c0\ub3c4 \uc704\uc758 \uc810\uc774 \uc2e4\uc81c \uac70\ucc98\uac00 \ub418\ub294 \ub370\uc5d0\ub294 \ub9ce\uc740 \ub178\ub3d9\uc774 \ud544\uc694\ud588\ub2e4. \uc8c4\uc218\ub4e4\uc740 \uac10\uc2dc\ubc1b\ub294 \uc874\uc7ac\uc774\uba74\uc11c \uc815\ucc29\uc744 \ub9cc\ub4e4\uc5b4 \uac00\ub294 \ub178\ub3d9\ub825\uc774\uae30\ub3c4 \ud588\ub2e4. \ub204\uac00 \uc77c\uc744 \uc9c0\uc2dc\ud558\uace0 \ub204\uac00 \uc218\ud589\ud588\ub294\uc9c0\uc758 \uad00\uacc4\ub294 \ub545\uc5d0 \ub0b4\ub9b0 \ub4a4\uc5d0\ub3c4 \uc0ac\ub77c\uc9c0\uc9c0 \uc54a\uc558\ub2e4. \ud56d\uad6c\uc758 \ucd08\uae30 \ubaa8\uc2b5\uc5d0\ub294 \uc2dd\ubbfc\uc9c0\uc640 \ud615\ubc8c \uc81c\ub3c4\uac00 \ud568\uaed8 \uc0c8\uaca8\uc838 \uc788\uc5c8\ub2e4. \uac70\ub9ac\uc758 \ud0c4\uc0dd\uc740 \uc81c\ub3c4\uc758 \uc5ed\uc0ac\uc640\ub3c4 \uc5f0\uacb0\ub41c\ub2e4. \ud150\uce58\uc758 \uae30\ub85d\uc5d0\ub294 \uc6d0\uc8fc\ubbfc\uacfc\uc758 \ub9cc\ub0a8\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \ubb3c\uc744 \uad6c\ud558\ub294 \uc77c\uc5d0\uc11c\ubd80\ud130 \uc11c\ub85c\uc758 \ubab8\uc9d3\uc744 \ud574\uc11d\ud558\ub294 \uc7a5\uba74\uc774 \ubcf4\uc778\ub2e4. \ub3c4\ucc29\ud55c \uc0ac\ub78c\ub4e4\uc740 \ubaa8\ub4e0 \uac83\uc744 \uc0c8\ub86d\uac8c \uc54c\uc544\uac00\uc57c \ud588\uc9c0\ub9cc \uae30\uc874 \uc8fc\ubbfc\uc5d0\uac8c \uadf8\uacf3\uc740 \uc774\ubbf8 \uc774\ub984\uacfc \uc0dd\ud65c, \uad00\uacc4\uac00 \uc788\ub294 \uacf5\uac04\uc774\uc5c8\ub2e4. \ube44\uc5b4 \uc788\ub294 \ub545\uc774\ub77c\ub294 \uc0c1\uc0c1\uacfc \ub9de\uc9c0 \uc54a\ub294\ub2e4. \ucc98\uc74c\uc758 \ub9cc\ub0a8\uc5d0\uc11c \uc6b0\ud638\uc801\uc778 \uc7a5\uba74\uc774 \uc788\uc5c8\ub2e4\uace0 \uc2dd\ubbfc\uc9c0\ud654\uc758 \uc804\uccb4 \uacb0\uacfc\uae4c\uc9c0 \ud3c9\ud654\ub85c\uc6e0\ub2e4\uace0 \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud55c \ubc88\uc758 \uc811\ucd09\uacfc \uc624\ub79c \uc9c0\ubc30\uc758 \uacfc\uc815\uc740 \ub2e4\ub974\ub2e4. \ub3c4\ucc29\uc758 \uae30\ub85d\uc744 \uc77d\uc73c\uba74\uc11c \uadf8 \ub4a4\uc758 \ud1a0\uc9c0\uc640 \uad8c\ub825 \uad00\uacc4\uc5d0 \ub300\ud55c \uc9c8\ubb38\uc744 \ub0a8\uaca8\uc57c \ud558\ub294 \uc774\uc720\ub2e4. \ud150\uce58\ub294 \ud604\uc7a5\uc744 \uad00\ucc30\ud55c \uc911\uc694\ud55c \uae30\ub85d\uc790\uc9c0\ub9cc \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \uc785\uc7a5\uc744 \uac19\uc740 \uac70\ub9ac\uc5d0\uc11c \ub2f4\uc740 \uc0ac\ub78c\uc740 \uc544\ub2c8\ub2e4. \uad70\uc778\uc73c\ub85c\uc11c\uc758 \uc784\ubb34\uc640 \uc601\uad6d\uc778 \uc815\ucc29\uc790\uc758 \uad00\uc2ec\uc774 \uc11c\uc220\uc5d0 \ub4e4\uc5b4 \uc788\ub2e4. \uc8c4\uc218\ub098 \uae30\uc874 \uc8fc\ubbfc\uc774 \ub290\ub080 \uc77c\uc744 \uadf8\uc758 \ubb38\uc7a5\ub9cc\uc73c\ub85c \uc644\uc804\ud788 \ub300\uc2e0\ud560 \uc218 \uc5c6\ub2e4. \uadf8\ub807\ub2e4\uace0 \uae30\ub85d\uc744 \ubc84\ub9b4 \ud544\uc694\ub294 \uc5c6\ub2e4. \ubb34\uc5c7\uc744 \uc9c1\uc811 \ubcf4\uc558\uace0 \ubb34\uc5c7\uc744 \ud310\ub2e8\ud588\ub294\uc9c0 \ub098\ub204\uc5b4 \uc77d\uc73c\uba74 \uc720\uc6a9\ud558\ub2e4. \ubb3c\uc790\uc640 \ud56d\ud574\uc5d0 \uad00\ud55c \uad6c\uccb4\uc801\uc778 \uc124\uba85, \ub2e4\ub978 \uc0ac\ub78c\uc744 \ud3c9\uac00\ud558\ub294 \ub9d0\uc740 \uc11c\ub85c \uc131\uaca9\uc774 \ub2e4\ub974\ub2e4. \uc624\ub798\ub41c \uc5ec\ud589\uae30\uc640 \uc2dd\ubbfc\uc9c0 \uae30\ub85d\uc744 \uc77d\ub294 \uc7ac\ubbf8\ub294 \ub0b4\uc6a9\ubfd0 \uc544\ub2c8\ub77c \uadf8 \uc2dc\uc120\uc744 \uc54c\uc544\uac00\ub294 \ub370\uc5d0\ub3c4 \uc788\ub2e4. 1788\ub144\uc740 \uc2dc\ub4dc\ub2c8\uc758 \uc2dd\ubbfc\uc9c0 \uc815\ucc29\uc744 \uc124\uba85\ud558\ub294 \uc911\uc694\ud55c \uc5f0\ub3c4\ub2e4. \ud558\uc9c0\ub9cc \uadf8\uac83\uc744 \ud638\uc8fc \uc804\uccb4\uc758 \uc5ed\uc0ac\ub098 \uadf8 \ub545\uc758 \uc778\uac04 \uc0dd\ud65c\uc774 \uc2dc\uc791\ub41c \ub54c\ub77c\uace0 \ub9d0\ud558\uba74 \ud6e8\uc52c \uae34 \uc2dc\uac04\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \ubb34\uc5c7\uc758 \uc2dc\uc791\uc778\uc9c0 \uc815\ud655\ud788 \ubd99\uc5ec \ub9d0\ud558\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \uc124\uba85\uc740 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uae30\ub85d\uc5d0\uc11c \ubb3c\uc744 \ucc3e\uace0 \ud574\uc548\uc744 \uc870\uc0ac\ud558\ub294 \uc7a5\uba74\uc744 \uc77d\uc73c\uba74 \uc815\ucc29\uc758 \uaddc\ubaa8\uac00 \uc190\uc5d0 \uc7a1\ud78c\ub2e4. \uba3c \uc81c\uad6d\uc758 \uba85\ub839\ub3c4 \ud604\uc7a5\uc5d0\uc11c\ub294 \ubc30\ub97c \ub308 \uacf3\uacfc \ub9c8\uc2e4 \ubb3c\uc774\ub77c\ub294 \uc870\uac74\uc744 \ub9cc\ub098\uc57c \ud588\ub2e4. \uc0c8\ub85c\uc6b4 \uc774\ub984\uc744 \ubd99\uc774\ub294 \uc77c\ubcf4\ub2e4 \uba3c\uc800 \uc0b4\uc544\uac08 \ud658\uacbd\uc744 \ud30c\uc545\ud574\uc57c \ud588\ub358 \uc148\uc774\ub2e4. \uc624\ub298\uc758 \ud56d\uad6c \ud48d\uacbd\uc5d0 \uccab \uc120\ub2e8\uc758 \ubc30\ub97c \uacb9\uccd0 \ubcf4\ub418, \ubc30\uc5d0\uc11c \ub0b4\ub9ac\uae30 \uc804\ubd80\ud130 \ud574\uc548\uc744 \uc54c\uace0 \uc788\ub358 \uc0ac\ub78c\ub4e4\ub3c4 \ud568\uaed8 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc2dc\ub4dc\ub2c8 \ucf54\ube0c\ub294 \uc0c8 \ub3c4\uc2dc\ub97c \uc138\uc6b4 \uc7a5\uba74\uc774\uba74\uc11c \uc11c\ub85c \ub2e4\ub978 \uad8c\ud55c\uacfc \uae30\uc5b5\uc774 \ub9cc\ub09c \uc7a5\uc18c\uc600\ub2e4. \uadf8 \ub450 \uce21\uba74\uc744 \ud568\uaed8 \uc77d\uc744 \ub54c \ub3c4\uc2dc\uc758 \uae30\uc6d0\uc774 \ub354 \uc785\uccb4\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4."}, {"id": "taghaza-salt-caravan-and-labor", "title": "\ud0c0\uac00\uc790 \u2014 \uc0ac\ub9c9\uc5d0\uc11c \uc18c\uae08\uc740 \uc65c \uba3c \uae38\uc744 \ub5a0\ub0ac\uc744\uae4c", "summary": "\uc18c\uae08\uc73c\ub85c \uc9c0\uc740 \uc9d1\uc5d0 \uad00\ud55c \uc5ec\ud589\uae30\uc5d0\uc11c \uc2dc\uc791\ud574 \uc0ac\ud558\ub77c \ubb34\uc5ed\uc758 \ud544\uc694\uc640 \uc6b4\uc1a1, \uac15\uc81c \ub178\ub3d9\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/taghaza-salt-caravan-and-labor/index.html", "image": "../media/taghaza-salt-caravan-and-labor.png", "alt": "\uc18c\uae08 \uc9d0\uc744 \uc2e4\uc740 \ub099\ud0c0\uc640 \uc0ac\ub9c9\uc758 \uc5ec\ud589\uc790\ub4e4\uc744 \uadf8\ub9b0 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ud0c0\uac00\uc790 \u2014 \uc0ac\ub9c9\uc5d0\uc11c \uc18c\uae08\uc740 \uc65c \uba3c \uae38\uc744 \ub5a0\ub0ac\uc744\uae4c \uc774\ube10 \ubc14\ud22c\ud0c0\uc758 \uae30\ub85d\uc73c\ub85c \ub9cc\ub098\ub294 \uc18c\uae08 \uad11\uc0b0\uacfc \ub300\uc0c1 \ubb34\uc5ed \uc18c\uae08\uc73c\ub85c \uc9c0\uc740 \uc9d1\uc5d0 \uad00\ud55c \uc5ec\ud589\uae30\uc5d0\uc11c \uc2dc\uc791\ud574 \uc0ac\ud558\ub77c \ubb34\uc5ed\uc758 \ud544\uc694\uc640 \uc6b4\uc1a1, \uac15\uc81c \ub178\ub3d9\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc9d1\uacfc \ubaa8\uc2a4\ud06c\uac00 \uc18c\uae08\uc73c\ub85c \uc9c0\uc5b4\uc838 \uc788\ub2e4\ub294 \ub9c8\uc744. \ub3d9\ud654 \uc18d\uc758 \uacfc\uc790 \uc9d1\ucc98\ub7fc \ub4e4\ub9ac\uc9c0\ub9cc 14\uc138\uae30 \uc5ec\ud589\uc790 \uc774\ube10 \ubc14\ud22c\ud0c0\uac00 \uc0ac\ud558\ub77c\uc758 \ud0c0\uac00\uc790\ub97c \uc124\uba85\ud55c \ub300\ubaa9\uc774\ub2e4. \ub098\ubb34\uac00 \ub4dc\ubb38 \uc0ac\ub9c9\uc5d0\uc11c \uc18c\uae08\uc740 \uce90\uc11c \uc62e\uae30\ub294 \uc0c1\ud488\uc778 \ub3d9\uc2dc\uc5d0 \uacc1\uc5d0 \ub9ce\uc740 \uc7ac\ub8cc\uc600\ub2e4. \uadf8\uac00 \uc801\uc740 \ud48d\uacbd\uc744 \ub530\ub77c\uac00\uba74 \uae08\uc73c\ub85c \uac00\ub4dd\ud55c \uc655\uad6d\ubcf4\ub2e4 \uba3c\uc800 \uae38\ucb49\ud55c \uc18c\uae08 \ub369\uc5b4\ub9ac\uc640 \ub099\ud0c0\uc758 \ub4f1\uc774 \ubcf4\uc778\ub2e4. \uba3c \uc2dc\uc7a5\uc73c\ub85c \uac08 \uc774 \ubb34\uac70\uc6b4 \uc9d0\uc740 \ub204\uac00 \ud544\uc694\ub85c \ud588\uace0, \ub204\uac00 \ub545\uc5d0\uc11c \uaebc\ub0b4\uc5c8\uc744\uae4c. \uc774\ube10 \ubc14\ud22c\ud0c0\ub294 \ud0c0\uac00\uc790\uc5d0\uc11c \ub545\uc744 \ud30c\uba74 \ud070 \uc18c\uae08 \ud310\ub4e4\uc774 \uacb9\uacb9\uc774 \ub098\uc628\ub2e4\uace0 \uc801\uc5c8\ub2e4. \uc9d1\uacfc \ubaa8\uc2a4\ud06c\uc758 \ubcbd, \ub099\ud0c0 \uac00\uc8fd\uc73c\ub85c \ub36e\uc740 \uc9c0\ubd95\ub3c4 \ubb18\uc0ac\ud588\ub2e4. \uadf8\uac00 \ubcf8 \ub9c8\uc744\uc740 \uc0ac\ub9c9 \ud55c\uac00\uc6b4\ub370\uc758 \ucc44\uad74\uacfc \uc0dd\ud65c\uc774 \ub9de\ubb3c\ub9b0 \uc7a5\uc18c\uc600\ub2e4. \uc774\uac83\uc740 \uc624\ub298\ub0a0\uc758 \ud604\uc7a5 \uc870\uc0ac \ubcf4\uace0\uc11c\uc640\ub294 \uc131\uaca9\uc774 \ub2e4\ub978 \uc5ec\ud589 \uae30\ub85d\uc774\ub2e4. \ub0af\uc120 \uacf3\uc758 \uc778\uc0c1\uacfc \uc5ec\ud589\uc790\uc758 \uad00\uc2ec\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uadf8\ub807\ub354\ub77c\ub3c4 \uc18c\uae08\uc774 \ub2e8\uc21c\ud55c \uc2dd\ud0c1 \uc704 \uac00\ub8e8\uac00 \uc544\ub2c8\ub77c \ud070 \ub369\uc5b4\ub9ac\ub85c \ucc44\uad74\ub418\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uad6c\uccb4\uc801\uc73c\ub85c \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uc11c\uc544\ud504\ub9ac\uce74\uc758 \uae08\uc740 \ubd81\uc544\ud504\ub9ac\uce74\uc640 \uc9c0\uc911\ud574\uc758 \uc2dc\uc7a5\uc73c\ub85c \uc774\uc5b4\uc84c\ub2e4. \ubc18\ub300 \ubc29\ud5a5\uc73c\ub85c \uc774\ub3d9\ud55c \uc911\uc694\ud55c \ubb3c\ud488 \uac00\uc6b4\ub370 \ud558\ub098\uac00 \uc0ac\ud558\ub77c\uc758 \uc18c\uae08\uc774\uc5c8\ub2e4. \uc0dd\uc0b0\ub418\ub294 \uacf3\uc774 \ub2e4\ub974\uba74 \uc11c\ub85c \ud544\uc694\ud55c \uac83\uc744 \uc5bb\uae30 \uc704\ud55c \uae38\uc774 \uc0dd\uae34\ub2e4. \uae08\uacfc \uc18c\uae08\uc740 \ubaa8\ub450 \ube5b\ub098\ub294 \uc0ac\uce58\ud488\uc774\ub77c\uc11c \ub9cc\ub09c \uac83\uc774 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \ubb3c\uac74\uc758 \uac00\uce58\ub294 \uadf8\uac83\uc774 \ud544\uc694\ud55c \uacf3\uae4c\uc9c0 \ub2ff\uc744 \uc218 \uc788\ub290\ub0d0\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c4\ub2e4. \uae08\uad11 \uac00\uae4c\uc774 \uc0ac\ub294 \uc0ac\ub78c\ub3c4 \ub2e4\ub978 \uc9c0\uc5ed\uc758 \uc0dd\ud65c \ubb3c\uc790\ub97c \ud544\uc694\ub85c \ud588\ub2e4. \uc5ec\ud589\uae30\uc5d0\ub294 \ub099\ud0c0\uac00 \ucee4\ub2e4\ub780 \uc18c\uae08 \ud310\uc744 \uc2e3\ub294 \ubaa8\uc2b5\uc774 \ub098\uc628\ub2e4. \ud310\uc744 \uce90\ub294 \ub370\uc11c \uc77c\uc774 \ub05d\ub098\uc9c0 \uc54a\uc558\ub2e4. \ubb34\uac70\uc6b4 \uc9d0\uc744 \ubb36\uace0, \uc0ac\ub9c9\uc744 \uac74\ub108\uba70, \uc0ac\ub78c\uacfc \uc9d0\uc2b9\uc774 \ubc84\ud2f8 \uc870\uac74\uc744 \ub9c8\ub828\ud574\uc57c \ud588\ub2e4. \uae38 \uc704\uc758 \ubb3c\uacfc \uc27c, \ud568\uaed8 \uc774\ub3d9\ud560 \uc0ac\ub78c\uc5d0 \ub300\ud55c \uc815\ubcf4\ub294 \uc6b4\uc1a1\uc758 \uc77c\ubd80\uc600\ub2e4. \uc9c0\ub3c4\uc758 \uc120 \ud558\ub098\uac00 \uace7\ubc14\ub85c \ud3b8\ub9ac\ud55c \uae38\uc744 \ub73b\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubaa9\uc801\uc9c0\uc5d0 \ub3c4\ucc29\ud55c \uc18c\uae08\uc5d0\ub294 \ub545\uc5d0\uc11c \uce90\ub0b8 \uac00\uce58\ubfd0 \uc544\ub2c8\ub77c \uc774\ub3d9\uc758 \uc218\uace0\ub3c4 \ub2f4\uacbc\ub2e4. \uc0ac\ud558\ub77c \ubb34\uc5ed\uc740 \uae08\uc744 \ub4e0 \uc0ac\ub78c\uacfc \uc18c\uae08\uc744 \ub4e0 \uc0ac\ub78c\uc774 \uc0ac\ub9c9 \ud55c\uac00\uc6b4\ub370\uc11c \ud55c \ubc88 \ubc14\uafb8\ub294 \uc7a5\uba74\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uae30 \uc5b4\ub835\ub2e4. \uc5ec\ub7ec \uc9c0\uc5ed\uc758 \uc0c1\uc778\uacfc \uc911\uac1c\uc790, \uac70\uc810\uc774 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uac70\ub798\ub294 \uc11c\ub85c \ub2e4\ub978 \ud544\uc694\ub97c \uc774\uc5b4 \uc8fc\ub294 \uacfc\uc815\uc774\uc5c8\ub2e4. \uadf8 \uacbd\ub85c \uac00\uae4c\uc774\uc5d0 \uc790\ub9ac \uc7a1\uc740 \uc815\uce58 \uc138\ub825\uc740 \ud1b5\ud589\uacfc \uc2dc\uc7a5\uc744 \ubc14\ud0d5\uc73c\ub85c \ud798\uc744 \uc5bb\uc5c8\ub2e4. \uac00\ub098\uc640 \ub9d0\ub9ac\uc758 \ubc88\uc601\uc5d0\ub3c4 \ubb34\uc5ed\uc774 \uc911\uc694\ud588\ub2e4. \uad11\uc0b0\uc744 \uac00\uc9c4 \uac83\uacfc \uad11\uc0b0\uc5d0\uc11c \ub098\uc628 \ubb3c\ud488\uc774 \uc9c0\ub098\ub294 \uae38\uc744 \uad00\ub9ac\ud558\ub294 \uac83\uc740 \uc11c\ub85c \ub2e4\ub978 \uad8c\ud55c\uc774\uc5c8\ub2e4. \uc0ac\ud558\ub77c \ubb34\uc5ed\uc744 \uc124\uba85\ud560 \ub54c \uae08\uacfc \uc18c\uae08\uc774 \ubb34\uac8c\ub300\ub85c \ub9de\ubc14\ub00c\uc5c8\ub2e4\ub294 \uc774\uc57c\uae30\uac00 \uc790\uc8fc \ub530\ub77c\uc628\ub2e4. \uadf8\ub7ec\ub098 \uae34 \uc2dc\uae30\uc640 \ub113\uc740 \uc9c0\uc5ed\uc758 \ubaa8\ub4e0 \uac70\ub798\uc5d0 \ub611\uac19\uc740 \ube44\uc728\uc744 \ubd99\uc774\uba74 \uc7a5\uc18c\uc640 \uc6b4\uc1a1 \uc870\uac74\uc758 \ucc28\uc774\uac00 \uc0ac\ub77c\uc9c4\ub2e4. \uac19\uc740 \uc18c\uae08\ub3c4 \uc0dd\uc0b0\uc9c0\uc640 \ub3c4\ucc29\uc9c0\uc5d0\uc11c \uad6c\ud558\uae30 \uc26c\uc6b4 \uc815\ub3c4\uac00 \ub2e4\ub974\ub2e4. \uc774 \uae00\uc5d0\uc11c \uc911\uc694\ud55c \uac83\uc740 \ub180\ub77c\uc6b4 \uad50\ud658 \ube44\uc728\uc744 \uc678\uc6b0\ub294 \uc77c\uc774 \uc544\ub2c8\ub2e4. \ud3c9\ubc94\ud574 \ubcf4\uc774\ub294 \ubb3c\uac74\uc774 \uba40\ub9ac \uc774\ub3d9\ud560 \uc774\uc720\uc640 \uadf8 \uacfc\uc815\uc5d0\uc11c \uc0dd\uae34 \uac00\uce58\ub2e4. \uc774\ube10 \ubc14\ud22c\ud0c0\ub294 \ud0c0\uac00\uc790\uc758 \uc18c\uae08\uc744 \ub178\uc608\ud654\ub41c \uc0ac\ub78c\ub4e4\uc774 \ucea4\ub2e4\uace0 \uae30\ub85d\ud588\ub2e4. \uc5ec\ud589\uae30\uc758 \uc774 \ub300\ubaa9\uc744 \ube7c\uace0 \ub099\ud0c0 \ud589\ub82c\ub9cc \uadf8\ub9ac\uba74 \uad50\uc5ed\uc758 \ud48d\uacbd\uc740 \ud6e8\uc52c \ub0ad\ub9cc\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4. \uadf8\ub7ec\ub098 \ubb3c\uac74\uc758 \uc774\ub3d9\uc5d0\ub294 \uc790\uc720\ub86d\uc9c0 \ubabb\ud55c \ub178\ub3d9\ub3c4 \uc788\uc5c8\ub2e4. \uc11c\uc544\ud504\ub9ac\uce74\uc758 \ubb34\uc5ed\ub9dd\uc5d0\uc11c\ub294 \uae08\uacfc \uc18c\uae08\ubfd0 \uc544\ub2c8\ub77c \ubd99\uc7a1\ud78c \uc0ac\ub78c\ub4e4\uae4c\uc9c0 \uac70\ub798\ub418\uc5c8\ub2e4. \ubc88\uc601\ud55c \uc655\uad6d\uacfc \ubd84\uc8fc\ud55c \uc2dc\uc7a5\uc744 \uc774\uc57c\uae30\ud560 \ub54c \ub204\uac00 \uc218\uc775\uc744 \uc5bb\uc5c8\uace0 \ub204\uac00 \uac15\uc81c\ub85c \uc77c\ud588\ub294\uc9c0 \ub530\ub85c \uc0b4\ud544 \ud544\uc694\uac00 \uc788\ub2e4. \ubb34\uc5ed\uc758 \uaddc\ubaa8\uac00 \uace7 \ubaa8\ub450\uc758 \ud48d\uc694\ub97c \ub73b\ud558\uc9c0\ub294 \uc54a\uc558\ub2e4. \uadf8\uc758 \ub9d0\ub9ac \uae30\ub85d\uc5d0\ub294 \uce58\uc548\uacfc \ud1b5\uce58\uc5d0 \ub300\ud55c \uce6d\ucc2c\ub3c4 \uc788\ub2e4. \uc548\uc804\ud55c \uc774\ub3d9\uc740 \uc5ec\ud589\uc790\uc758 \ub208\uc5d0 \uc911\uc694\ud55c \uc7a5\uc810\uc774\uc5c8\ub2e4. \ud558\uc9c0\ub9cc \uae38\uc744 \uc9c0\ub098\ub294 \uc0ac\ub78c\uc774 \ub290\ub080 \uc548\uc804\uacfc \uad11\uc0b0 \ub178\ub3d9\uc790\uc758 \uc790\uc720\ub294 \uac19\uc740 \uae30\uc900\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ud55c \uae30\ub85d \uc548\uc5d0 \ucc2c\ud0c4\uacfc \uac00\ud639\ud55c \ud604\uc2e4\uc774 \ud568\uaed8 \ub2f4\uae38 \uc218 \uc788\ub2e4. \uc5ed\uc0ac \uc790\ub8cc\ub97c \uc77d\ub294 \uc7ac\ubbf8\ub3c4 \uc5ec\uae30\uc5d0 \uc788\ub2e4. \uc5ec\ud589\uc790\uc758 \ub9d0\uc744 \uc804\ubd80 \uc758\uc2ec\ud558\uac70\ub098 \uadf8\ub300\ub85c \ud48d\uacbd\uc73c\ub85c \ubc1b\uc544\ub4e4\uc774\uae30\ubcf4\ub2e4, \uadf8\uac00 \uc5b4\ub5a4 \uc704\uce58\uc5d0\uc11c \ubb34\uc5c7\uc744 \ubcf4\uace0 \uc788\uc5c8\ub294\uc9c0 \uc0b4\ud53c\ub294 \uac83\uc774\ub2e4. \uac19\uc740 \uc18c\uae08\uc774 \uc5b4\ub5a4 \uacf3\uc5d0\uc11c\ub294 \ud754\ud558\uace0 \ub2e4\ub978 \uacf3\uc5d0\uc11c\ub294 \uba40\ub9ac\uc11c \uad6c\ud574\uc57c \ud558\ub294 \ubb3c\uac74\uc774\uc5c8\ub2e4. \uc9c0\ub9ac\uc801 \ucc28\uc774\uac00 \uac70\ub798\uc758 \uc774\uc720\uac00 \ub41c\ub2e4. \uc0ac\ub9c9\uc5d0 \ub9ce\uc740 \uc790\uc6d0\uc774 \uc232\uacfc \ub4e4\uc758 \uc0dd\uc0b0\ubb3c\uacfc \ub9cc\ub0a0 \ub54c \uac01 \uc9c0\uc5ed\uc758 \uc0dd\ud65c\ub3c4 \ubc14\uae65\uc758 \uae38\uc5d0 \uae30\ub300\uac8c \ub41c\ub2e4. \uc774 \uc5f0\uacb0\uc744 \ub2e8\uc21c\ud788 \ubd81\ucabd\uc740 \uc18c\uae08, \ub0a8\ucabd\uc740 \uae08\uc774\ub77c\ub294 \uadf8\ub9bc\uc73c\ub85c\ub9cc \uc678\uc6b0\uba74 \uc5ec\ub7ec \uc0dd\uc0b0\uc790\uc640 \uc911\uac1c\uc790\uc758 \uc5ed\ud560\uc774 \uac00\ub824\uc9c4\ub2e4. \ubb3c\ud488\uc740 \uc5ec\ub7ec \uac70\uc810\uc744 \uac70\ucce4\uace0 \uac01 \uac70\uc810\uc740 \uc8fc\ubcc0\uc758 \ub2e4\ub978 \uac70\ub798\uc640\ub3c4 \uc774\uc5b4\uc84c\ub2e4. \uc0ac\ud558\ub77c\uc758 \uae38\uc740 \ub450 \ub05d\uc810\ub9cc \uc788\ub294 \ud1b5\ub85c\uac00 \uc544\ub2c8\uc5c8\ub2e4. \uadf8\ub7f0 \uae4c\ub2ed\uc5d0 \ud070 \uc655\uad6d\uc758 \uc774\ub984\ub9cc \ubc14\ub00c\ub294 \uc5f0\ud45c\ubcf4\ub2e4 \ubb3c\uac74 \ud558\ub098\ub97c \ub530\ub77c\uac00\ub294 \ubc29\uc2dd\ub3c4 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ud0c0\uac00\uc790\uc758 \uc18c\uae08\uc740 \ud1b5\uce58\uc790\uac00 \uc544\ub2cc \ucc44\uad74\uc790\uc640 \uc9d0\uc2b9, \ubb3c\uc744 \uad6c\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c\uae4c\uc9c0 \uc2dc\uc120\uc744 \ub370\ub824\uac04\ub2e4. \ud070 \uc5ed\uc0ac\ub97c \uc774\ub8e8\ub294 \uc791\uc740 \uc77c\ub4e4\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \ud0c0\uac00\uc790\uc758 \uc774\uc57c\uae30 \ub05d\uc5d0 \ub0a8\ub294 \uac83\uc740 \uac70\ub300\ud55c \uae08\ub369\uc5b4\ub9ac\ub9cc\uc774 \uc544\ub2c8\ub2e4. \ud070 \ud310\uc73c\ub85c \uce90\uc5b4 \ub099\ud0c0\uc5d0 \uc2e3\uace0 \uba3c \uc2dc\uc7a5\uc73c\ub85c \ubcf4\ub0c8\ub358 \uc18c\uae08\uc774\ub2e4. \uc624\ub298\uc758 \uc791\uc740 \uc591\ub150\ud1b5\uc5d0\uc11c \ub5a0\uc62c\ub9ac\uae30 \uc5b4\ub824\uc6b4 \uac70\ub9ac\uc640 \ub178\ub3d9\uc774 \uadf8 \ubb3c\uac74 \ub4a4\uc5d0 \uc788\uc5c8\ub2e4. \uc0ac\ub9c9\uc740 \uc0ac\ub78c\uc758 \uc655\ub798\uac00 \uc5c6\ub294 \ube48 \uacf5\uac04\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ud658\uacbd\uc744 \uc774\uc5b4 \uc8fc\ub294 \uae38\uc774\uc5c8\uace0, \uadf8 \uae38\uc5d0\ub294 \uae30\uc220\uacfc \uc9c0\uc2dd, \uad8c\ub825\uacfc \ubd88\ud3c9\ub4f1\uc774 \ud568\uaed8 \uc6c0\uc9c1\uc600\ub2e4. \uc18c\uae08\uc73c\ub85c \uc9c0\uc740 \uc9d1\uc740 \uadf8 \ub113\uc740 \uc5f0\uacb0\uc744 \ub4e4\uc5ec\ub2e4\ubcf4\ub294 \uc791\uc740 \uc785\uad6c\ub2e4."}, {"id": "taj-mahal-marble-memory", "title": "\ud0c0\uc9c0\ub9c8\ud560 \u2014 \ud558\uc580 \ubb34\ub364\uc5d0 \ub2f4\uae34 \uc0ac\ub791\uacfc \uc81c\uad6d", "summary": "\uc544\uadf8\ub77c\uc758 \uc655\uc2e4 \ubb18\uc5ed\uc5d0\uc11c \uc77d\ub294 \uc560\ub3c4\u00b7\uc815\uc6d0\u00b7\ub300\ub9ac\uc11d\uc758 \uc758\ubbf8\uc744 \uc774\uc57c\uae30\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/taj-mahal-marble-memory/index.html", "image": "../media/taj-mahal-marble-memory.jpg", "alt": "\ud0c0\uc9c0\ub9c8\ud560\uc758 \ub3d4\uacfc \ubbf8\ub098\ub808\ud2b8, \uc57c\ubb34\ub098\uac15\uc744 \ud568\uaed8 \ubcf4\uc5ec \uc8fc\ub294 \uc2e4\uc81c \uc0ac\uc9c4", "text": "\ud0c0\uc9c0\ub9c8\ud560 \u2014 \ud558\uc580 \ubb34\ub364\uc5d0 \ub2f4\uae34 \uc0ac\ub791\uacfc \uc81c\uad6d \uc544\uadf8\ub77c\uc758 \uc655\uc2e4 \ubb18\uc5ed\uc5d0\uc11c \uc77d\ub294 \uc560\ub3c4\u00b7\uc815\uc6d0\u00b7\ub300\ub9ac\uc11d\uc758 \uc758\ubbf8 \uc544\uadf8\ub77c\uc758 \uc655\uc2e4 \ubb18\uc5ed\uc5d0\uc11c \uc77d\ub294 \uc560\ub3c4\u00b7\uc815\uc6d0\u00b7\ub300\ub9ac\uc11d\uc758 \uc758\ubbf8\uc744 \uc774\uc57c\uae30\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc57c\ubb34\ub098\uac15 \uac00\uc5d0 \ud770 \ub3d4\uc774 \ub5a0 \uc788\ub294 \ub4ef\ud558\ub2e4. \ud0c0\uc9c0\ub9c8\ud560\uc744 \ucc98\uc74c \ubcf4\ub294 \uc0ac\ub78c\uc740 \uad81\uc804\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc27d\uc9c0\ub9cc, \uc774 \uac74\ubb3c\uc758 \uc911\uc2ec\uc5d0\ub294 \ubb34\ub364\uc774 \uc788\ub2e4. \ubb34\uad74\uc81c\uad6d\uc758 \ud669\uc81c \uc0e4 \uc790\ud55c\uc774 \uc138\uc0c1\uc744 \ub5a0\ub09c \uc544\ub0b4 \ubb44\ud0c0\uc988 \ub9c8\ud560\uc744 \uc704\ud574 \uc138\uc6b4 \ubb18\ub2f9\uc774\ub2e4. \uc0ac\ub791\uc758 \uae30\ub150\ubb3c\uc774\ub77c\ub294 \uc124\uba85\uc740 \ud2c0\ub9ac\uc9c0 \uc54a\ub294\ub2e4. \ub2e4\ub9cc \uadf8 \ub9d0\ub9cc\uc73c\ub85c \uc815\uc6d0\uacfc \uc218\ub85c, \uac70\ub300\ud55c \ubb38\uacfc \ub124 \uac1c\uc758 \ud0d1\uae4c\uc9c0 \ubaa8\ub450 \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud55c \uc0ac\ub78c\uc5d0 \ub300\ud55c \uc560\ub3c4\ub294 \uc5b4\ub5bb\uac8c \uc81c\uad6d\uc744 \ub300\ud45c\ud558\ub294 \uac74\ucd95\uc774 \ub418\uc5c8\uc744\uae4c. \uac74\ubb3c\uc758 \uc6a9\ub3c4\uc640 \uc138\ubd80\ub97c \ucc28\ub840\ub85c \ubcf4\uba74 \uc775\uc219\ud55c \uc0ac\uc9c4\uc774 \uc870\uae08 \ub2e4\ub974\uac8c \uc77d\ud78c\ub2e4. \uc0e4 \uc790\ud55c\uacfc \ubb44\ud0c0\uc988 \ub9c8\ud560\uc740 17\uc138\uae30 \ubb34\uad74 \uad81\uc815\uc758 \uc778\ubb3c\ub4e4\uc774\ub2e4. \uc544\ub0b4\uc758 \uc8fd\uc74c\uc744 \uacc4\uae30\ub85c \ud669\uc81c\ub294 \uc544\uadf8\ub77c\uc5d0 \ub300\uaddc\ubaa8 \ubb18\uc5ed\uc744 \uc870\uc131\ud588\ub2e4. \uc624\ub298\uc758 \uad00\ub78c\uac1d\uc5d0\uac8c\ub294 \uc778\ub3c4\uc758 \ub300\ud45c \uc720\uc0b0\uc774\uc9c0\ub9cc, \ucc98\uc74c\ubd80\ud130 \uad00\uad11\uac1d\uc5d0\uac8c \ubcf4\uc5ec \uc8fc\uae30 \uc704\ud574 \uc9c0\uc740 \uac74\ubb3c\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc8fd\uc740 \uc774\ub97c \uae30\ub9ac\uace0 \uc655\uc2e4\uc758 \uae30\uc5b5\uc744 \ub0a8\uae30\ub294 \uc7a5\uc18c\uc600\ub2e4. \uc774 \ub54c\ubb38\uc5d0 \ud0c0\uc9c0\ub9c8\ud560\uc744 \ud3c9\ubc94\ud55c \uc0ac\ub791 \uc774\uc57c\uae30\uc758 \ubc30\uacbd\uc73c\ub85c\ub9cc \uc77d\uc73c\uba74 \uc911\uc694\ud55c \ucc28\uc774\uac00 \uc0ac\ub77c\uc9c4\ub2e4. \ud669\uc81c\uc5d0\uac8c\ub294 \uac1c\uc778\uc758 \uac10\uc815\uc744 \uad6d\uac00 \uaddc\ubaa8\uc758 \uc0ac\uc5c5\uc73c\ub85c \uc62e\uae38 \uc218 \uc788\ub294 \uad8c\ub825\uc774 \uc788\uc5c8\ub2e4. \uc560\ub3c4\uc758 \uae4a\uc774\uc640 \uc0ac\uc5c5\uc5d0 \ub3d9\uc6d0\ud560 \uc218 \uc788\ub294 \uc790\uc6d0\uc758 \ud06c\uae30\ub294 \uc11c\ub85c \ub2e4\ub978 \ubb38\uc81c\uc774\uba74\uc11c \uc774\uacf3\uc5d0\uc11c \ud568\uaed8 \ub9cc\ub09c\ub2e4. \uc544\uadf8\ub77c\ub294 \ubb34\uad74\uc81c\uad6d\uc758 \uc911\uc694\ud55c \uc815\uce58\uc801 \uac70\uc810\uc774\uc5c8\ub2e4. \ud0c0\uc9c0\ub9c8\ud560\uc740 \uc774\ub984 \uc5c6\ub294 \uc678\ub534\uacf3\uc5d0 \uac11\uc790\uae30 \ub4f1\uc7a5\ud55c \uae30\ub150\ubb3c\uc774 \uc544\ub2c8\ub2e4. \uad81\uc815\uacfc \ub3c4\uc2dc\uc758 \uc5ed\uc0ac\uac00 \uc313\uc778 \uc7a5\uc18c, \uadf8\ub9ac\uace0 \uac15\uc744 \ub07c\uace0 \uc788\ub294 \ub545\uc5d0 \ub4e4\uc5b4\uc130\ub2e4. \uac74\ubb3c \ub4a4\ucabd\uc758 \uc57c\ubb34\ub098\uac15\uc744 \ud568\uaed8 \ub5a0\uc62c\ub824\uc57c \ubb18\uc5ed\uc774 \ub3c4\uc2dc\uc758 \uc5b4\ub290 \ud48d\uacbd \uc18d\uc5d0 \ub193\uc600\ub294\uc9c0 \ubcf4\uc778\ub2e4. \uc815\uba74 \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uac74\ubb3c\ub9cc \ub3c5\ub9bd\ud574 \uc788\ub294 \ub4ef\ud558\uc9c0\ub9cc \uc2e4\uc81c \uac74\ucd95\uc740 \uc8fc\ubcc0\uc758 \ub545\uacfc \ubb3c, \uc811\uadfc\ud558\ub294 \ubc29\ud5a5\uc744 \ud3ec\ud568\ud55c\ub2e4. \uad00\ub78c\uac1d\uc774 \ubb38\uc744 \ud1b5\uacfc\ud574 \uba3c \ub3d4\uc744 \ubc14\ub77c\ubcf4\ub294 \uacbd\ud5d8\uacfc \uac15 \uac74\ub108\uc5d0\uc11c \uac74\ubb3c\uc744 \ubcf4\ub294 \uacbd\ud5d8\ub3c4 \uac19\uc9c0 \uc54a\ub2e4. \ud0c0\uc9c0\ub9c8\ud560\uc758 \uc544\ub984\ub2e4\uc6c0\uc740 \uc815\uba74\uc758 \uc678\uacfd\uc120\ubfd0 \uc544\ub2c8\ub77c \uadf8\uac83\uc744 \ub9cc\ub098\uac8c \ud558\ub294 \ubc30\uce58\uc5d0 \uc788\ub2e4. \uc815\uc6d0\uacfc \uae38\uac8c \ubed7\uc740 \uc218\ub85c\ub294 \uc2dc\uc120\uc744 \uc911\uc559\uc758 \ubb18\ub2f9\uc73c\ub85c \ubaa8\uc740\ub2e4. \ubb3c\uc5d0 \ub3d4\uc774 \ube44\uce58\uba74 \ub545 \uc704\uc758 \uac74\ubb3c\uacfc \uc218\uba74\uc758 \ubaa8\uc2b5\uc774 \ub9c8\uc8fc\ud55c\ub2e4. \uc815\uc6d0\uc740 \uac70\ub300\ud55c \uac74\ubb3c\uc744 \ub0a8\uc740 \uacf5\uac04\uc5d0 \uc7a5\uc2dd\ud55c \ubd80\uc18d\ubb3c\uc774 \uc544\ub2c8\ub77c, \uc0ac\ub78c\ub4e4\uc774 \uc18d\ub3c4\ub97c \ub2a6\ucd94\uace0 \uac74\ubb3c\uc744 \ubc14\ub77c\ubcf4\ub3c4\ub85d \ub9cc\ub4dc\ub294 \uc7a5\uce58\ub2e4. \uac74\ubb3c\uc5d0 \uac00\uae4c\uc774 \uac08\uc218\ub85d \uba40\ub9ac\uc11c \ubcf4\uc774\ub358 \uc804\uccb4 \ud615\ud0dc\ub294 \ub3cc \ud45c\uba74\uc758 \uc791\uc740 \ubb34\ub2ac\ub85c \ubc14\ub010\ub2e4. \uc774\ucc98\ub7fc \ud070 \ucd95\uc120\uacfc \uc138\ubd80 \uc7a5\uc2dd \uc0ac\uc774\ub97c \uc624\uac00\uba70 \ubcf4\ub294 \uac83\uc774 \uc88b\ub2e4. \uc815\uba74 \uc0ac\uc9c4 \ud55c \uc7a5\uc740 \uc804\uccb4\uc758 \uade0\ud615\uc744 \uc798 \ubcf4\uc5ec \uc8fc\uc9c0\ub9cc, \uadf8 \uc548\uc73c\ub85c \uac78\uc5b4 \ub4e4\uc5b4\uac00\ub294 \ub3d9\uc548 \uc2dc\uc57c\uac00 \ub2ec\ub77c\uc9c4\ub2e4\ub294 \uc0ac\uc2e4\uae4c\uc9c0 \ub2f4\uc9c0\ub294 \ubabb\ud55c\ub2e4. \ud0c0\uc9c0\ub9c8\ud560\uc758 \ud770\uc0c9\uc740 \uc7a5\uc2dd\uc774 \uc5c6\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \ub300\ub9ac\uc11d\uc5d0\ub294 \uc900\ubcf4\uc11d\uc744 \uc774\uc6a9\ud55c \uc7a5\uc2dd\uacfc \uc815\uad50\ud55c \ubb38\uc591\uc774 \ub354\ud574\uc84c\ub2e4. \uba40\ub9ac\uc11c\ub294 \ud558\ub098\uc758 \ubc1d\uc740 \ub369\uc5b4\ub9ac\ucc98\ub7fc \ubcf4\uc774\ub358 \ud45c\uba74\uc774 \uac00\uae4c\uc774\uc5d0\uc11c\ub294 \uc7ac\ub8cc\uc640 \uae30\uc220\uc774 \uacb9\uce5c \uc790\ub9ac\ub85c \ub4dc\ub7ec\ub09c\ub2e4. \ub3d4\uc758 \ud06c\uae30\ub97c \uac10\ud0c4\ud55c \ub2e4\uc74c\uc5d0\ub294 \ub3cc\uc744 \ub2e4\ub8ec \uc190\uc758 \uaddc\ubaa8\ub97c \uc0dd\uac01\ud574 \ubcfc \ucc28\ub840\ub2e4. \ubb34\uad74\uc758 \uac74\ucd95 \ubb38\ud654\uc5d0\ub294 \uc778\ub3c4\uc640 \uc774\uc2ac\ub78c\uad8c, \ud398\ub974\uc2dc\uc544\uacc4 \ubbf8\uac10\uc774 \ub9cc\ub098\ub294 \ubcf5\ud569\uc801\uc778 \uc131\uaca9\uc774 \uc788\ub2e4. \uadf8\ub798\uc11c \uc774 \uac74\ubb3c\uc744 \uc5b4\ub290 \ud55c \uc9c0\uc5ed\uc758 \uc591\uc2dd\uc774 \uadf8\ub300\ub85c \uc62e\uaca8 \uc628 \uacb0\uacfc\ub85c\ub9cc \uc124\uba85\ud558\uae30 \uc5b4\ub835\ub2e4. \uc7ac\ub8cc\uc640 \uc7a5\uc2dd, \uc815\uc6d0\uc758 \uad6c\uc131 \uc18d\uc5d0\uc11c \uc5ec\ub7ec \uc804\ud1b5\uc774 \uc655\uc2e4\uc758 \uc694\uad6c\uc5d0 \ub9de\uac8c \uc0c8\ub86d\uac8c \uacb0\ud569\ud588\ub2e4. \uc911\uc559 \ub3d4 \uc8fc\uc704\uc5d0\ub294 \ub3c5\ub9bd\ub41c \ub124 \uac1c\uc758 \ubbf8\ub098\ub808\ud2b8\uac00 \uc11c \uc788\ub2e4. \uc774 \ud0d1\ub4e4\uc740 \uc911\uc559\uc758 \ubb18\ub2f9\uc774 \uc678\ub86d\uac8c \ub0a8\uc9c0 \uc54a\ub3c4\ub85d \uc804\uccb4\uc758 \uc724\uacfd\uc744 \uc7a1\uc544 \uc900\ub2e4. \uadf8\ub7ec\ub098 \uc885\uad50 \uac74\ucd95\uc758 \ud0d1\uc744 \ub2e8\uc21c\ud55c \uc7a5\uc2dd \uae30\ub465\ucc98\ub7fc \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ud615\ud0dc\uc5d0\ub294 \uc774\uc2ac\ub78c \uac74\ucd95\uc758 \uc804\ud1b5\uacfc \uc758\ubbf8\uac00 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4. \uac74\ubb3c\uc758 \uae00\uc528 \uc5ed\uc2dc \ube48 \uacf5\uac04\uc744 \ucc44\uc6b4 \ubb34\ub2ac\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uafb8\ub780\uc758 \uad6c\uc808\uc774 \uc544\ub984\ub2e4\uc6b4 \uc11c\uccb4\ub85c \uc0c8\uaca8\uc838 \uc788\uc5b4 \ubb18\ub2f9\uc758 \uc885\uad50\uc801 \uc131\uaca9\uc744 \ub4dc\ub7ec\ub0b8\ub2e4. \uc77d\uc744 \uc218 \uc5c6\ub294 \uad00\ub78c\uac1d\uc5d0\uac8c\ub294 \uc120\uacfc \ube44\ub840\uac00 \uba3c\uc800 \ubcf4\uc774\uaca0\uc9c0\ub9cc, \uc6d0\ub798\ub294 \uc758\ubbf8\ub97c \uac00\uc9c4 \uc5b8\uc5b4\uc600\ub2e4. \ubcf4\ub294 \uac74\ucd95\uacfc \uc77d\ub294 \uac74\ucd95\uc774 \uac19\uc740 \ud45c\uba74\uc5d0 \uacb9\uccd0 \uc788\ub294 \uc148\uc774\ub2e4. \uac70\ub300\ud55c \uc655\uc2e4 \uac74\ucd95\uc740 \ud669\uc81c \ud55c \uc0ac\ub78c\uc758 \uc0c1\uc0c1\ub9cc\uc73c\ub85c \uc644\uc131\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc124\uacc4\ud558\uace0 \ub3cc\uc744 \uc6b4\ubc18\ud558\uba70 \uac00\uacf5\ud558\uace0 \uc7a5\uc2dd\uc744 \ub9de\ucd94\ub294 \uc0ac\ub78c\ub4e4\uc774 \ud544\uc694\ud558\ub2e4. \uc644\uc131\ub41c \uac74\ubb3c \uc55e\uc5d0\uc11c \ud6c4\uc6d0\uc790\uc758 \uc774\ub984\uc740 \uc27d\uac8c \uae30\uc5b5\ub418\uc9c0\ub9cc, \uc218\ub9ce\uc740 \uc791\uc5c5\uc790\uc758 \uac1c\ubcc4 \uc0b6\uc740 \uc880\ucc98\ub7fc \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc774 \ucc28\uc774\ub97c \uae30\uc5b5\ud55c\ub2e4\uace0 \uc544\ub984\ub2e4\uc6c0\uc744 \ubd80\uc815\ud574\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ud788\ub824 \uac10\ud0c4\uc758 \ub300\uc0c1\uc744 \ub113\ud790 \uc218 \uc788\ub2e4. \ud669\uc81c\uc758 \uc560\ub3c4\uc640 \uad8c\ub825, \uc7ac\ub8cc\ub97c \ub2e4\ub8ec \uae30\uc220\uacfc \uc774\ub984\uc774 \uc804\ud574\uc9c0\uc9c0 \uc54a\ub294 \ub178\ub3d9\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \ud0c0\uc9c0\ub9c8\ud560\uc744 \uc0ac\ub791\uc758 \uc99d\uac70\ub77c\uace0 \ubd80\ub97c \ub54c \uadf8 \uc0ac\ub791\uc744 \uac70\ub300\ud55c \ubb3c\uc9c8\ub85c \ub9cc\ub4e0 \uc0ac\ub78c\ub4e4\uae4c\uc9c0 \uc0dd\uac01\ud558\uba74 \uc774\uc57c\uae30\uac00 \ud48d\ubd80\ud574\uc9c4\ub2e4. \ud0c0\uc9c0\ub9c8\ud560\uc744 \ub2e4\uc2dc \ubc14\ub77c\ubcfc \ub54c\uc5d0\ub294 \uba3c\uc800 \ubb18\ub2f9\uc774\ub77c\ub294 \uc6a9\ub3c4\ub97c \ub5a0\uc62c\ub824 \ubcf4\uc790. \uba38\ubb34\ub294 \uc0ac\ub78c\uc758 \uc77c\uc0c1\uc744 \uc704\ud55c \ubc29\uc774 \uc544\ub2c8\ub77c \uc8fd\uc740 \uc774\ub97c \uae30\uc5b5\ud558\ub294 \uc7a5\uc18c\ub77c\ub294 \uc810\uc774 \ub3d4\uacfc \uc815\uc6d0, \uae00\uc528\ub97c \uc77d\ub294 \ubc29\ud5a5\uc744 \ubc14\uafbc\ub2e4. \uc544\ub984\ub2e4\uc6b4 \uc678\uad00\uacfc \uc8fd\uc74c\uc5d0 \ub300\ud55c \uc0dd\uac01\uc774 \uc11c\ub85c \uba40\ub9ac \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\ub2e4. \ubb18\uc5ed\uc744 \ubcf8 \ub4a4 \ub3c4\uc2dc\uc758 \uad81\uc815 \uac74\ucd95\uacfc \ube44\uad50\ud558\uba74 \uc9c8\ubb38\uc774 \ud558\ub098 \ub354 \uc0dd\uae34\ub2e4. \uc0b4\uc544 \uc788\ub294 \uad8c\ub825\uc774 \uba38\ubb34\ub294 \uacf5\uac04\uacfc \uc8fd\uc740 \uc774\ub97c \uae30\uc5b5\ud558\ub294 \uacf5\uac04\uc740 \ubb34\uc5c7\uc744 \uacf5\uc720\ud558\uace0 \ubb34\uc5c7\uc774 \ub2e4\ub97c\uae4c. \ud0c0\uc9c0\ub9c8\ud560\uc758 \uc815\uc5f0\ud568\uc740 \uc774\ub7f0 \ube44\uad50\ub97c \uc2dc\uc791\ud558\uac8c \ud558\ub294 \uc88b\uc740 \uc2e4\ub9c8\ub9ac\ub2e4. \uc774\uacf3\uc740 \ud55c \ubd80\ubd80\uc758 \uc0ac\uc5f0\uc774\uba74\uc11c \ud55c \uc81c\uad6d\uc758 \ubb38\ud654\uc640 \uc790\uc6d0\uc774 \ubaa8\uc778 \uacb0\uacfc\ub2e4. \uc0ac\uc9c4 \uc18d \ud558\uc580 \uac74\ubb3c\uc744 \uc544\ub294 \uac83\uc5d0\uc11c \ud55c \uac78\uc74c \ub354 \ub098\uc544\uac00, \uc65c \uc774 \uc790\ub9ac\uc5d0 \ubb34\uc5c7\uc744 \uc704\ud574 \uc774\ub7f0 \ud615\ud0dc\ub97c \uc138\uc6e0\ub294\uc9c0 \ubb3b\ub294\ub2e4\uba74 \ud0c0\uc9c0\ub9c8\ud560\uc740 \uc720\uba85\ud55c \ud48d\uacbd\uc744 \ub118\uc5b4 \ud558\ub098\uc758 \uc77d\uc744\uac70\ub9ac\uac00 \ub41c\ub2e4."}, {"id": "tenochtitlan-lake-and-city", "title": "\ud14c\ub178\uce58\ud2f0\ud2c0\ub780 \u2014 \ud638\uc218 \uc704\uc758 \ub3c4\uc2dc\ub294 \uc5b4\ub5bb\uac8c \uba39\uace0\uc0b4\uc558\uc744\uae4c", "summary": "\uc544\uc2a4\ud14c\uce74 \uc218\ub3c4\uc758 \uc81c\ubc29\uae38\uacfc \uce58\ub0a8\ud30c, \uacf5\ub0a9\uc744 \ud1b5\ud574 \ud070 \ub3c4\uc2dc\ub97c \uc720\uc9c0\ud558\ub294 \uc77c\uc0c1\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/tenochtitlan-lake-and-city/index.html", "image": "../media/tenochtitlan-lake-and-city.jpg", "alt": "\ud14c\ub178\uce58\ud2f0\ud2c0\ub780 \ud15c\ud50c\ub85c \ub9c8\uc694\ub974\uc758 \uc30d\ub465\uc774 \uc2e0\uc804\uacfc \uacc4\ub2e8\uc744 \ud45c\ud604\ud55c \ud604\ub300 \ubaa8\ud615\uc758 \uc0ac\uc9c4.", "text": "\ud14c\ub178\uce58\ud2f0\ud2c0\ub780 \u2014 \ud638\uc218 \uc704\uc758 \ub3c4\uc2dc\ub294 \uc5b4\ub5bb\uac8c \uba39\uace0\uc0b4\uc558\uc744\uae4c \ud53c\ub77c\ubbf8\ub4dc \ub108\uba38\uc5d0\uc11c \ub9cc\ub098\ub294 \ubb3c\uae38\uacfc \ubc2d, \uc9d1\uc758 \uc774\uc57c\uae30 \uc544\uc2a4\ud14c\uce74 \uc218\ub3c4\uc758 \uc81c\ubc29\uae38\uacfc \uce58\ub0a8\ud30c, \uacf5\ub0a9\uc744 \ud1b5\ud574 \ud070 \ub3c4\uc2dc\ub97c \uc720\uc9c0\ud558\ub294 \uc77c\uc0c1\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ud070 \ub3c4\uc2dc\ub97c \uc9d3\uace0 \uc2f6\uc740\ub370 \ub208\uc55e\uc5d0 \ud638\uc218\uac00 \uc788\ub2e4. \ubb3c\uc744 \ud53c\ud574 \ub2e4\ub978 \uacf3\uc73c\ub85c \uac00\ub294 \ubc29\ubc95\ub3c4 \uc788\uaca0\uc9c0\ub9cc, \uba55\uc2dc\ucf54 \ubd84\uc9c0\uc5d0\uc11c\ub294 \ud638\uc218\uc758 \uc12c\ub4e4\uc774 \uac70\ub300\ud55c \uc218\ub3c4\uc758 \ubc14\ud0d5\uc774 \ub418\uc5c8\ub2e4. \uc544\uc2a4\ud14c\uce74\uc758 \ud14c\ub178\uce58\ud2f0\ud2c0\ub780\uc774\ub2e4. \uc774\ub984\uc740 \uc870\uae08 \uae38\uc5b4\ub3c4 \ucd9c\ubc1c \uc7a5\uba74\uc740 \uc27d\uac8c \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uc774 \ub3c4\uc2dc\ub97c \uc124\uba85\ud560 \ub54c\ub294 \ub192\uc774 \uc19f\uc740 \uc2e0\uc804\uc774 \uba3c\uc800 \ub4f1\uc7a5\ud558\uace4 \ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc2e0\uc804 \uacc4\ub2e8 \uc544\ub798\uc5d0\uc11c\ub3c4 \ub9e4\uc77c \uc2dd\uc0ac\uac00 \ud544\uc694\ud588\uace0, \uc0ac\ub78c\uc740 \uc9d1\uc73c\ub85c \ub3cc\uc544\uac00\uc57c \ud588\uc73c\uba70, \ubb3c\uac74\uc740 \uc81c\ub54c \ub3c4\ucc29\ud574\uc57c \ud588\ub2e4. \uc624\ub298\uc740 \uc720\uba85\ud55c \uaf2d\ub300\uae30\ubcf4\ub2e4 \ub3c4\uc2dc\ub97c \uacc4\uc18d \uc6c0\uc9c1\uc774\uac8c \ud55c \ub0ae\uc740 \uacf3\uc758 \uc774\uc57c\uae30\ub97c \ub530\ub77c\uac00 \ubcf4\uc790. \uc544\uc2a4\ud14c\uce74 \uc0ac\ub78c\ub4e4\uc740 1325\ub144 \ubb34\ub835 \ud14d\uc2a4\ucf54\ucf54\ud638\uc758 \uc12c\ub4e4\uc5d0\uc11c \ub3c4\uc2dc\ub97c \ub9cc\ub4e4\uae30 \uc2dc\uc791\ud588\ub2e4. \ucd08\uae30\uc5d0\ub294 \uc8fc\ubcc0 \uc138\ub825\uacfc \uac70\ub798\ud558\uace0 \uad70\uc0ac \ud65c\ub3d9\uc5d0 \ucc38\uc5ec\ud558\uba70 \uc0b4\uc544\ub0a8\uc558\ub2e4. \ucc98\uc74c\ubd80\ud130 \uba55\uc2dc\ucf54 \uc911\ubd80\ub97c \uc9c0\ubc30\ud558\ub294 \uac70\ub300\ud55c \uc218\ub3c4\uac00 \uc644\uc131\ub418\uc5b4 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. 1428\ub144\uc5d0\ub294 \ud14c\ub178\uce58\ud2f0\ud2c0\ub780\uc774 \ud14d\uc2a4\ucf54\ucf54, \ud2c0\ub77c\ucf54\ud310\uacfc \uc0bc\uac01\ub3d9\ub9f9\uc744 \uc774\ub8e8\uc5b4 \uc9c0\uc5ed\uc758 \uac15\ub825\ud55c \uc138\ub825\uc744 \uaebe\uc5c8\ub2e4. \uc774\ud6c4 \uc9c0\ubc30 \uc601\uc5ed\uc774 \ud655\ub300\ub418\uba74\uc11c \uc218\ub3c4\uc758 \uc704\uc0c1\ub3c4 \ucee4\uc84c\ub2e4. \ub3c4\uc2dc\ub294 \uc88b\uc740 \uc790\ub9ac\uc5d0 \uac74\ubb3c\uc744 \ubaa8\uc740 \uacb0\uacfc\uc778 \ub3d9\uc2dc\uc5d0, \uc8fc\ubcc0\uacfc \uc5b4\ub5a4 \uad00\uacc4\ub97c \ub9fa\uc5c8\ub294\uc9c0\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc7a5\uc18c\uc600\ub2e4. 16\uc138\uae30 \ucd08 \ud14c\ub178\uce58\ud2f0\ud2c0\ub780\uc740 \uc801\uc5b4\ub3c4 20\ub9cc \uba85\uc774 \uc0b4\uc558\ub358 \uac83\uc73c\ub85c \uad50\uc7ac\ub294 \uc124\uba85\ud55c\ub2e4. \ub2f9\uc2dc\uc758 \uc815\ud655\ud55c \uc778\uad6c\ub97c \uc624\ub298\ub0a0 \uc8fc\ubbfc\ub4f1\ub85d \ud1b5\uacc4\ucc98\ub7fc \ud655\uc815\ud560 \uc218\ub294 \uc5c6\uc9c0\ub9cc, \ub300\uaddc\ubaa8 \ub3c4\uc2dc\uc600\ub2e4\ub294 \uc810\uc740 \ubd84\uba85\ud558\ub2e4. \uc12c\uacfc \ud638\uc22b\uac00\ub97c \uc5f0\uacb0\ud558\ub294 \ud070 \uc81c\ubc29\uae38\ub4e4\uc774 \ubc14\uae65\uc73c\ub85c \ubed7\uc5b4 \uc788\uc5c8\ub2e4. \uc81c\ubc29\uae38\uc740 \uc131\uacfd\ub3c4\uc2dc\uc758 \ubb38 \uc55e \ub3c4\ub85c\uc640\ub294 \uc870\uac74\uc774 \ub2e4\ub974\ub2e4. \uc591\uc606\uc774 \ubb3c\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \uc0ac\ub78c\uacfc \ubb3c\uc790\uac00 \ub4dc\ub098\ub4dc\ub294 \uc5f0\uacb0\ubd80\uac00 \uc5b4\ub514\uc5d0 \ub193\uc600\ub294\uc9c0 \uc0dd\uac01\ud574 \ubcf4\uba74, \ud638\uc218\uac00 \ub3c4\uc2dc\ub97c \ubcf4\ud638\ud558\ub294 \ud658\uacbd\uc774\uba74\uc11c \uc774\ub3d9\uc758 \ubc29\ubc95\uc744 \ub530\ub85c \ub9c8\ub828\ud574\uc57c \ud558\ub294 \uc870\uac74\uc774\uae30\ub3c4 \ud588\uc74c\uc744 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ub3c4\uc2dc \uc8fc\ubcc0\uc5d0\ub294 \uce58\ub0a8\ud30c\ub77c\uace0 \ubd80\ub974\ub294 \uc778\uacf5\uc801\uc73c\ub85c \uc870\uc131\ud55c \uacbd\uc791\uc9c0\uac00 \uc788\uc5c8\ub2e4. \ud754\ud788 \ubb3c \uc704\uc758 \ubc2d\uc774\ub77c\ub294 \ub9d0\ub9cc \ub4e3\uace0 \uc791\uc740 \ub5cf\ubaa9\ucc98\ub7fc \ub5a0\ub2e4\ub2c8\ub294 \ubaa8\uc2b5\uc744 \uc0c1\uc0c1\ud558\uc9c0\ub9cc, \ud638\uc218\uc758 \uc595\uc740 \uacf3\uc5d0 \ud759 \ub4f1\uc744 \uc313\uc544 \ub9cc\ub4e0 \uace0\uc815\ub41c \ubc2d\uc73c\ub85c \uc774\ud574\ud558\ub294 \ud3b8\uc774 \ub9de\ub2e4. \uadf8 \uc0ac\uc774\uc758 \uc218\ub85c\ub294 \ubb3c\uc744 \ub300\uace0 \uc774\ub3d9\ud558\ub294 \ub370 \uc4f0\uc600\ub2e4. \uc774 \ubc2d\ub4e4\uc740 \ub3c4\uc2dc \uc8fc\ubbfc\uc5d0\uac8c \uba39\uc744\uac70\ub9ac\ub97c \uacf5\uae09\ud588\ub2e4. \uac74\ubb3c\uc744 \uc138\uc6b4 \ub4a4 \uc2dd\ub7c9 \ubb38\uc81c\ub97c \ub530\ub85c \ud574\uacb0\ud55c \uac83\uc774 \uc544\ub2c8\ub77c, \uc0b4 \uacf5\uac04\uacfc \uc0dd\uc0b0\ud560 \uacf5\uac04, \ubb3c\uae38\uc774 \ud568\uaed8 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4. \uc624\ub298\ub0a0 \ub3c4\uc2dc\uc758 \uc2dd\uc7ac\ub8cc\uac00 \uc5b4\ub514\uc11c \uc624\ub294\uc9c0 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uac83\uacfc \ube44\uad50\ud558\uba74 \ud638\uc218 \ub3c4\uc2dc\uc758 \uad6c\uc870\uac00 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \ub290\uaef4\uc9c4\ub2e4. \uc8fc\ubbfc\uc758 \uc9d1\uc740 \ud759\ubcbd\ub3cc\uacfc \ud3c9\ud3c9\ud55c \uc9c0\ubd95, \uc791\uc740 \ub9c8\ub2f9\uc744 \uac16\ucd98 \ud615\ud0dc\uac00 \ub9ce\uc558\ub2e4. \ub3c4\uc2dc \uc911\uc2ec\uc5d0\ub294 \uc2e0\uc804\uacfc \uacf5\ub180\uc774 \uacbd\uae30\uc7a5, \ud589\uc815 \uac74\ubb3c\uacfc \uc9c0\ubc30\uce35\uc758 \uac70\ucc98\uac00 \ubaa8\uc600\ub2e4. \uc0ac\ub78c\ub9c8\ub2e4 \uc0ac\ub294 \uc790\ub9ac\uc640 \ub3c4\uc2dc\uc5d0\uc11c \ub9e1\uc740 \uc5ed\ud560\uc774 \uac19\uc9c0\ub294 \uc54a\uc558\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uc911\uc2ec \uc2e0\uc804\uc778 \ud15c\ud50c\ub85c \ub9c8\uc694\ub974 \ub4f1\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ud604\ub300 \ubaa8\ud615\uc758 \uc0ac\uc9c4\uc774\ub2e4. \uc2e4\uc81c \uace0\ub300 \uac74\ubb3c\uc744 \uadf8\ub300\ub85c \ucd2c\uc601\ud55c \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \uc704\ucabd\uc5d0 \ub098\ub780\ud788 \uc120 \ub450 \uc2e0\uc804\uacfc \ub113\uc740 \uacc4\ub2e8\uc744 \ubcf4\uba74, \ub3c4\uc2dc \ud55c\ubcf5\ud310\uc758 \uc81c\uc758 \uacf5\uac04\uc774 \uc5bc\ub9c8\ub098 \ub450\ub4dc\ub7ec\uc9c4 \ud615\ud0dc\ub85c \uad6c\uc131\ub418\uc5c8\ub294\uc9c0 \uc9d0\uc791\ud560 \uc218 \uc788\ub2e4. \uc218\ub3c4\ub294 \uc8fc\ubcc0\uc758 \uacbd\uc791\uc9c0\ubfd0 \uc544\ub2c8\ub77c \ub113\uc740 \uc9c0\ubc30 \uc9c0\uc5ed\uc5d0\uc11c \ub4e4\uc5b4\uc624\ub294 \uacf5\ub0a9\uc5d0\ub3c4 \uc758\uc874\ud588\ub2e4. \uc9c0\uc5ed\uc5d0 \ub530\ub77c \uc2dd\ub7c9\uacfc \uc9c1\ubb3c, \ub3c4\uad6c\uc640 \uc0ac\uce58\ud488 \ub4f1 \uc694\uad6c\ubc1b\ub294 \ubb3c\ud488\uc774 \ub2ec\ub790\ub2e4. \uac00\uae4c\uc6b4 \uacf3\uc5d0\uc11c \uc77c\uc0c1\uc801\uc778 \uba39\uc744\uac70\ub9ac\ub97c, \ub354 \uba3c \uacf3\uc5d0\uc11c \ud2b9\ubcc4\ud55c \ubb3c\uac74\uc744 \ub4e4\uc5ec\uc624\ub294 \uc5f0\uacb0\ub3c4 \ub098\ud0c0\ub0ac\ub2e4. \ubb3c\uac74\uc774 \ub3c4\ucc29\ud588\ub2e4\ub294 \uacb0\uacfc\ub9cc \ubcf4\uba74 \uac70\ub300\ud55c \uc2dc\uc7a5\uc758 \ud48d\uc694\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc, \uacf5\ub0a9\uc740 \uc790\uc720\ub85c\uc6b4 \uac70\ub798\uc640 \uac19\uc9c0 \uc54a\ub2e4. \uc9c0\ubc30\uc640 \uc758\ubb34\uc758 \uad00\uacc4\uac00 \uc788\uc5c8\ub2e4. \uc218\ub3c4\uc758 \ubc88\uc601\uc744 \uc774\ud574\ud558\ub824\uba74 \ubb34\uc5c7\uc774 \uc5bc\ub9c8\ub098 \ubaa8\uc600\ub294\uc9c0\ubfd0 \uc544\ub2c8\ub77c \ub204\uac00 \uadf8\uac83\uc744 \ub9cc\ub4e4\uc5b4 \ubcf4\ub0b4\uc57c \ud588\ub294\uc9c0\ub3c4 \ud568\uaed8 \ubb3c\uc5b4\uc57c \ud55c\ub2e4. \uc544\uc2a4\ud14c\uce74 \uad6d\uac00\uc758 \uc885\uad50 \uc758\ub840\uc5d0\ub294 \uc778\uc2e0\uacf5\ud76c\uac00 \ud3ec\ud568\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc774 \uc0ac\uc2e4\uc744 \uac10\ucd94\uc9c0 \uc54a\ub354\ub77c\ub3c4 \uc790\uadf9\uc801\uc778 \uc7a5\uba74\ub9cc\uc73c\ub85c \ub3c4\uc2dc\ub97c \uc124\uba85\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub18d\uc0ac\uc640 \uc218\uacf5\uc5c5, \uc2dc\uc7a5 \uac70\ub798\uc640 \uac00\uc815\uc758 \ub178\ub3d9\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \uc774 \uc0ac\ud68c\uac00 \uc5b4\ub5bb\uac8c \uc720\uc9c0\ub418\uc5c8\ub294\uc9c0 \uc54c \uc218 \uc788\ub2e4. \uc8fc\ubbfc\ub4e4\uc740 \uac19\uc740 \ub192\uc774\uc758 \uacc4\uce35\uc5d0 \uc11c \uc788\uc9c0 \uc54a\uc558\ub2e4. \uadc0\uc871\uacfc \uc804\ubb38 \uc7a5\uc778, \uc0c1\uc778\uacfc \ub18d\ubbfc, \ub178\uc608\uac00 \ub41c \uc0ac\ub78c\ub4e4\uc774 \ub2e4\ub978 \uc870\uac74\uc5d0\uc11c \uc0b4\uc544\uac14\ub2e4. \ud2b9\ud788 \uc9d1 \uc548\uc5d0\uc11c \uc74c\uc2dd\uc744 \uc900\ube44\ud558\uace0 \uc9c1\ubb3c\uc744 \ub9cc\ub4dc\ub294 \uc77c\ub3c4 \ub9e4\uc77c \ub3c4\uc2dc\ub97c \uc9c0\ud0f1\ud588\ub2e4. \ub208\uc5d0 \ud06c\uac8c \ubcf4\uc774\ub294 \uac74\ucd95\uacfc \uc624\ub798 \ub0a8\uae30 \uc5b4\ub824\uc6b4 \uc77c\uc0c1\uc758 \ub178\ub3d9\uc740 \ubaa8\ub450 \ub3c4\uc2dc\uc758 \uc5ed\uc0ac\ub2e4. \uc624\ub298\ub0a0\uc758 \uc124\uba85\uc5d0\ub294 \uc6d0\uc8fc\ubbfc \uadf8\ub9bc \uae30\ub85d\uacfc \uace0\uace0\ud559 \uc790\ub8cc, \uc2a4\ud398\uc778\uc778\ub4e4\uc774 \ub0a8\uae34 \uae30\ub85d\uc774 \ud568\uaed8 \uc0ac\uc6a9\ub41c\ub2e4. \uc815\ubcf5 \uacfc\uc815\uc5d0\uc11c \ub9ce\uc740 \ud1a0\ucc29 \uae30\ub85d\uc774 \ud30c\uad34\ub418\uc5c8\uace0 \uc720\ub7fd\uc778\uc758 \uc124\uba85\uc5d0\ub294 \uc790\uc2e0\uc758 \uc885\uad50\uc640 \uac00\uce58\uad00\uc774 \ub4e4\uc5b4\uac14\ub2e4. \ub530\ub77c\uc11c \ub0a8\uc544 \uc788\ub294 \uae00\uc744 \ud22c\uba85\ud55c \ucc3d\ucc98\ub7fc \uc77d\uc744 \uc218\ub294 \uc5c6\ub2e4. \ud14c\ub178\uce58\ud2f0\ud2c0\ub780\uc744 \ucc98\uc74c \ub5a0\uc62c\ub9b4 \ub54c \ubb3c \uc704\uc5d0 \uc19f\uc740 \uc2e0\uc804\uc758 \ubaa8\uc2b5\uc740 \uc88b\uc740 \uc785\uad6c\uac00 \ub41c\ub2e4. \uac70\uae30\uc11c \uc81c\ubc29\uae38\uc744 \ub530\ub77c\uac00\uace0 \ubc2d\uacfc \uc9d1, \ub3c4\uc2dc\ub85c \ub4e4\uc5b4\uc624\ub294 \uc9d0\uc744 \uc0dd\uac01\ud574 \ubcf4\uc790. \uac70\ub300\ud55c \uc218\ub3c4\uac00 \uc720\uc9c0\ub41c \uae4c\ub2ed\uc740 \uc778\uc0c1\uc801\uc778 \uaf2d\ub300\uae30 \ud558\ub098\ubcf4\ub2e4, \uadf8 \uc544\ub798 \uc218\ub9ce\uc740 \uc0dd\ud65c\uc774 \uc11c\ub85c \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4."}, {"id": "timbuktu-trade-and-learning", "title": "\ud300\ubd81\ud22c \u2014 \uc0ac\ub9c9\uc758 \uae38 \ub05d\uc5d0\uc11c \ucc45\uc744 \ud3bc\uce58\ub2e4", "summary": "\uad50\uc5ed\ub85c\uc640 \uc774\uc2ac\ub78c \ud559\ubb38\uc774 \ub9cc\ub09c \ud300\ubd81\ud22c\ub97c \ubaa8\uc2a4\ud06c \uc0ac\uc9c4\uacfc \uc5ed\uc0ac \uae30\ub85d\uc73c\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\ub3c4\uc2dc\uc758 \ubcc0\ud654", "categories": ["history-cities"], "url": "stories/timbuktu-trade-and-learning/index.html", "image": "../media/timbuktu-trade-and-learning.jpg", "alt": "\ud300\ubd81\ud22c \uc9d5\uac8c\ub808\ubca0\ub974 \ubaa8\uc2a4\ud06c\ub97c \ub2e4\ub978 \ubc29\ud5a5\uc5d0\uc11c \ucd2c\uc601\ud55c \ub450 \uc7a5\uc758 \uc2e4\uc81c \uc0ac\uc9c4.", "text": "\ud300\ubd81\ud22c \u2014 \uc0ac\ub9c9\uc758 \uae38 \ub05d\uc5d0\uc11c \ucc45\uc744 \ud3bc\uce58\ub2e4 \uae08\uacfc \uc18c\uae08\uc774 \uc624\uac00\ub358 \ub3c4\uc2dc\uac00 \ubc30\uc6c0\uc758 \uc7a5\uc18c\uac00 \ub41c \uc774\uc720 \uad50\uc5ed\ub85c\uc640 \uc774\uc2ac\ub78c \ud559\ubb38\uc774 \ub9cc\ub09c \ud300\ubd81\ud22c\ub97c \ubaa8\uc2a4\ud06c \uc0ac\uc9c4\uacfc \uc5ed\uc0ac \uae30\ub85d\uc73c\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \ubcc0\ud654 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ud300\ubd81\ud22c\ub77c\ub294 \uc774\ub984\uc5d0\uc11c\ub294 \uc5b4\ub518\uac00 \uc544\uc8fc \uba3c \uacf3\uc758 \ub290\ub08c\uc774 \ub09c\ub2e4. \uc0ac\ub9c9 \ub108\uba38\uc758 \uc678\ub534 \ub3c4\uc2dc\ub97c \ub5a0\uc62c\ub9ac\uae30\ub3c4 \uc27d\ub2e4. \ud558\uc9c0\ub9cc \uc911\uc138 \uc11c\uc544\ud504\ub9ac\uce74\uc758 \uc9c0\ub3c4\uc5d0 \ubb34\uc5ed\uae38\uc744 \uadf8\ub824 \ub123\uc73c\uba74 \uc778\uc0c1\uc774 \ubc14\ub010\ub2e4. \uba40\ub9ac \ub5a8\uc5b4\uc9c4 \ub05d\uc790\ub9ac\uac00 \uc544\ub2c8\ub77c \uc5ec\ub7ec \uc774\ub3d9\uc774 \ub9cc\ub098\ub294 \uacf3\uc774 \ub098\ud0c0\ub09c\ub2e4. \uae08\uacfc \uc18c\uae08, \uc9c1\ubb3c\ub9cc \uadf8 \uae38\uc744 \ub530\ub77c \uc6c0\uc9c1\uc600\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\uacfc \ucc45, \uacf5\ubd80\ud558\ub294 \ubc29\uc2dd\ub3c4 \ud568\uaed8 \uac74\ub108\uac14\ub2e4. \ud300\ubd81\ud22c\uac00 \ud559\ubb38\uc758 \ub3c4\uc2dc\ub85c \uae30\uc5b5\ub418\ub294 \uae4c\ub2ed\uc744 \uc774\ud574\ud558\ub824\uba74 \uba3c\uc800 \ub3c4\uc11c\uad00\uc758 \ubb38\ubcf4\ub2e4 \ub3c4\uc2dc \ubc14\uae65\uc758 \uae38\uc744 \ubc14\ub77c\ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \ud300\ubd81\ud22c\ub294 \uc624\ub298\ub0a0 \ub9d0\ub9ac\uc5d0 \uc788\uc73c\uba70, \uadf8 \uc5ed\uc0ac\ub294 \uc0ac\ud558\ub77c\uc640 \uc0ac\ud5ec, \ub2c8\uc81c\ub974\uac15 \uc77c\ub300\uc758 \uad50\uc5ed\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\ub2e4. \uc0ac\ud5ec\uc740 \uc0ac\ub9c9 \ub0a8\ucabd\uc5d0 \uc774\uc5b4\uc9c0\ub294 \uc9c0\uc5ed\uc774\ub2e4. \ubd81\ucabd\uc744 \uac00\ub85c\uc9c0\ub974\ub294 \uae38\uacfc \uc11c\uc544\ud504\ub9ac\uce74 \uc548\ucabd\uc758 \uc0dd\uc0b0\uc9c0\uac00 \ub9cc\ub098\ub294 \ub3c4\uc2dc\ub4e4\uc740 \uba3c \uacf3\uc758 \ubb3c\uac74\uc744 \uc11c\ub85c \uc774\uc5b4 \uc8fc\uc5c8\ub2e4. \uc18c\uae08\uc740 \ubd81\ucabd\uc5d0\uc11c \uc6b4\ubc18\ub418\uc5c8\uace0 \uae08\uc744 \ube44\ub86f\ud55c \uc5ec\ub7ec \ubb3c\ud488\uc740 \ub2e4\ub978 \uacbd\ub85c\ub97c \ud1b5\ud574 \uac70\ub798\ub418\uc5c8\ub2e4. \ubb3c\uac74\uc758 \ucd9c\ubc1c\uc9c0\uc640 \ud544\uc694\ud55c \uc7a5\uc18c\uac00 \ub2e4\ub974\uba74 \uadf8 \uc0ac\uc774\uc758 \uac70\ub9ac\ub97c \uac74\ub108\ub294 \uc0ac\ub78c\uc774 \uc911\uc694\ud574\uc9c4\ub2e4. \ud300\ubd81\ud22c\ub97c \uc0ac\ub9c9\uc5d0 \uace0\ub9bd\ub41c \uc810\uc73c\ub85c \uadf8\ub9ac\uba74 \ubc14\ub85c \uc774 \uc5f0\uacb0\uc744 \uc9c0\uc6cc \ubc84\ub9ac\uac8c \ub41c\ub2e4. 14\uc138\uae30 \ub9d0\ub9ac\uc758 \ud1b5\uce58\uc790 \ub9cc\uc0ac \ubb34\uc0ac\ub294 \uba54\uce74\ub85c \uc21c\ub840\ub97c \ub5a0\ub09c \uc778\ubb3c\ub85c \uc720\uba85\ud558\ub2e4. \ub9ce\uc740 \uae08\uc744 \ub098\ub204\uc5b4 \uc8fc\uc5c8\ub2e4\ub294 \uc774\uc57c\uae30\uac00 \uc790\uc8fc \ub530\ub77c\ubd99\uc9c0\ub9cc, \ub3c4\uc2dc\uc758 \ubb38\ud654\ub77c\ub294 \uad00\uc810\uc5d0\uc11c\ub294 \ub3cc\uc544\uc624\ub294 \uae38\ub3c4 \uc911\uc694\ud558\ub2e4. \uadf8\ub294 \ud559\uc790\uc640 \uac74\ucd95\uac00, \ucc45\uc744 \ub9d0\ub9ac\ub85c \ub4e4\uc5ec\uc624\ub294 \ub370 \uae30\uc5ec\ud588\ub2e4. \uad50\uc7ac\ub294 \uc774\ub7ec\ud55c \ud750\ub984 \uc18d\uc5d0\uc11c \ud300\ubd81\ud22c\uc758 \uc774\uc2ac\ub78c \ud559\ubb38\uacfc \uad50\uc721\uc774 \uc131\uc7a5\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc885\uad50\uc801 \uad8c\uc704, \ud1b5\uce58\uc790\uc758 \ud6c4\uc6d0, \uad50\uc5ed\uc73c\ub85c \uc5bb\ub294 \ubd80\uac00 \uc11c\ub85c \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\uc558\ub358 \uac83\uc774\ub2e4. \uae08\uc774 \ub9ce\uc558\ub2e4\ub294 \uc77c\ud654\ub9cc\uc73c\ub85c \uae30\uc5b5\ud558\uba74, \uadf8 \uc790\uc6d0\uc774 \uc5b4\ub5a4 \ud65c\ub3d9\uc744 \uac00\ub2a5\ud558\uac8c \ud588\ub294\uc9c0\ub294 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ud568\uaed8 \uc2e4\uc740 \ub450 \uc0ac\uc9c4\uc740 \ud300\ubd81\ud22c\uc758 \uc9d5\uac8c\ub808\ubca0\ub974 \ubaa8\uc2a4\ud06c\ub97c \ubcf4\uc5ec \uc900\ub2e4. \uad50\uc7ac\ub294 \uc774 \ubaa8\uc2a4\ud06c\uc758 \uac74\ub9bd\uc744 1327\ub144\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \ud300\ubd81\ud22c\uc5d0\uc11c\ub294 \uafb8\ub780\uc744 \uacf5\ubd80\ud558\ub294 \uad50\uc721\uacfc \ud568\uaed8 \uc774\uc2ac\ub78c \ubc95, \ucca0\ud559\uacfc \uacfc\ud559\uc5d0 \uad00\ud55c \ubc30\uc6c0\ub3c4 \uc774\ub8e8\uc5b4\uc84c\ub2e4. \uc5ec\uae30\uc11c \uc624\ub298\ub0a0\uc758 \uc885\ud569\ub300\ud559 \ucea0\ud37c\uc2a4\ub97c \uadf8\ub300\ub85c \uc0c1\uc0c1\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc61b \ub3c4\uc2dc\uc758 \ubc30\uc6c0\uc740 \uc885\uad50 \uacf5\uac04, \uad50\uc0ac\uc640 \uc81c\uc790\uc758 \uad00\uacc4, \ud6c4\uc6d0\uc758 \ubc29\uc2dd \uc548\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc84c\ub2e4. \ud559\ubb38\uc774 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc874\uc911\ud558\uba74\uc11c\ub3c4, \ud604\ub300 \ub300\ud559\uc758 \uc2dc\uac04\ud45c\uc640 \ud559\uacfc \uc870\uc9c1\uc744 \uacfc\uac70\uc5d0 \uadf8\ub300\ub85c \uc62e\uaca8 \ub193\uc9c0 \uc54a\ub294 \ud3b8\uc774 \ub3c4\uc2dc\ub97c \ub354 \uc815\ud655\ud558\uac8c \uc774\ud574\ud558\uac8c \ud55c\ub2e4. \ucc45\uc740 \ud45c\uc9c0 \uc548\uc758 \uae00\ub9cc\uc73c\ub85c \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub9cc\ub4e0 \uc0ac\ub78c\uc774 \uc788\uace0 \uc6b4\ubc18\ud55c \uc0ac\ub78c\uc774 \uc788\uc73c\uba70, \uadf8 \uae00\uc744 \uc77d\uac70\ub098 \uac00\ub974\uce60 \uc0ac\ub78c\uc774 \ud544\uc694\ud558\ub2e4. \uba3c \uacf3\uc5d0\uc11c \ucc45\uc744 \ub4e4\uc5ec\uc628\ub2e4\ub294 \uc124\uba85\uc5d0\ub294 \uc774\ub7f0 \uc5ec\ub7ec \ub2e8\uacc4\uac00 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4. \uad50\uc5ed\ub85c\uc640 \uc9c0\uc2dd\uc758 \uc774\ub3d9\uc744 \uac19\uc774 \ubcf4\uc544\uc57c \ud558\ub294 \uc774\uc720\ub2e4. \uc774\ub807\uac8c \uc0dd\uac01\ud558\uba74 \uc0c1\uc778\uacfc \ud559\uc790\ub294 \uc11c\ub85c \ubb34\uad00\ud55c \uc778\ubb3c\ub9cc\uc740 \uc544\ub2c8\ub2e4. \ub3c4\uc2dc\ub97c \ub4dc\ub098\ub4dc\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc5f0\uacb0\uacfc \uc548\uc815\uc801\uc778 \uc0dd\ud65c\uc758 \uae30\ubc18\uc774 \uad50\uc721\uc744 \ub4b7\ubc1b\uce68\ud560 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \uc0c1\uc778\uc774 \ud559\uc790\uc600\uac70\ub098 \uac70\ub798\uac00 \uace7\ubc14\ub85c \ud559\ubb38\uc744 \ub0b3\uc558\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ud65c\ub3d9\uc774 \uac19\uc740 \ub3c4\uc2dc \uc548\uc5d0\uc11c \ub9cc\ub0a0 \uc870\uac74\uc744 \uc0b4\ud3b4\ubcf4\ub294 \uac83\uc774\ub2e4. \ud6c4\ub300\uc5d0 \ud300\ubd81\ud22c\ub97c \ubb18\uc0ac\ud55c \ub808\uc624 \uc544\ud504\ub9ac\uce74\ub204\uc2a4\uc758 \uae30\ub85d\uc5d0\ub294 \uc0c1\uc810\uacfc \uc9c1\ubb3c \uac70\ub798, \ubb3c\uacfc \uc2dd\ub7c9, \uad81\uc815\uc758 \ubaa8\uc2b5\uc774 \ub098\uc628\ub2e4. \ubc30\uc6c0\uc758 \uba85\uc131\ub9cc \uc788\ub294 \ub3c4\uc2dc\uac00 \uc544\ub2c8\ub77c \uba39\uace0 \uc77c\ud558\uace0 \uc0ac\uace0\ud30c\ub294 \uc0dd\ud65c\uc758 \uacf5\uac04\uc774\uc5c8\ub2e4\ub294 \uc810\uc744 \uc54c\ub824 \uc900\ub2e4. \ub2e4\ub9cc \uc5ec\ud589\uc790\uc758 \uc11c\uc220\uc744 \ub3c4\uc2dc \uc8fc\ubbfc \uc804\uccb4\uc758 \ubaa9\uc18c\ub9ac\ub85c \uc77d\uc744 \uc218\ub294 \uc5c6\ub2e4. \uadf8 \uae30\ub85d\uc5d0\ub294 \ub178\uc608\uac00 \ub41c \uc0ac\ub78c\ub4e4\uc758 \uc874\uc7ac\ub3c4 \ub4f1\uc7a5\ud55c\ub2e4. \ubc88\uc601\uacfc \ud559\ubb38\uc758 \uc774\uc57c\uae30\uac00 \ub2f9\uc2dc\uc758 \ubd88\ud3c9\ub4f1\uc744 \uc5c6\uc560 \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc544\ub984\ub2e4\uc6b4 \ubb38\ud654\uc758 \uc131\uacfc\uc640 \uadf8 \ub3c4\uc2dc\ub97c \ub5a0\ubc1b\uce5c \uc0ac\ud68c\uc801 \uad00\uacc4\ub97c \ud568\uaed8 \ubcf4\uc544\uc57c, \ud300\ubd81\ud22c\ub97c \ub9c9\uc5f0\ud55c \ud669\uae08\uc2dc\ub300\uc758 \ud48d\uacbd\uc73c\ub85c\ub9cc \uc18c\ube44\ud558\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \ud300\ubd81\ud22c\ub294 \ub9d0\ub9ac\uc640 \uc1a1\uac00\uc774\uc758 \uad8c\ub825 \ubcc0\ud654 \uc18d\uc5d0 \uc788\uc5c8\ub2e4. \uc1a1\uac00\uc774\uc758 \uc21c\ub2c8 \uc54c\ub9ac\uac00 \uc138\ub825\uc744 \ub113\ud788\ub358 \uc2dc\uae30\ub97c \ub450\uace0, \uc544\ub78d\uc5b4 \uc5ed\uc0ac \uae30\ub85d\uc740 \ud559\uc790\ub4e4\uc744 \uc5b5\uc555\ud55c \ud1b5\uce58\uc790\ub85c \ube44\ud310\ud55c\ub2e4. \ubc18\uba74 \uc1a1\uac00\uc774\uc758 \uad6c\uc804 \uc804\ud1b5\uc5d0\uc11c\ub294 \uac15\ub825\ud55c \uc815\ubcf5\uc790\uc774\uc790 \uac74\uad6d\uc758 \uc601\uc6c5\uc73c\ub85c \uae30\uc5b5\ub41c\ub2e4. \uac19\uc740 \uc778\ubb3c\uc758 \ud3c9\uac00\uac00 \ub2e4\ub978 \uc774\uc720\ub97c \uc0dd\uac01\ud558\uba74 \uc5ed\uc0ac\uac00 \uc870\uae08 \uc785\uccb4\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4. \uc804\uc7c1\uc5d0\uc11c \uc774\uae34 \ud1b5\uce58\uc790\uc758 \uc131\ucde8\uc640 \ud559\uc790\ub4e4\uc774 \uacaa\uc740 \ubd88\uc548\uc740 \uac19\uc740 \uc810\uc218\ud45c\ub85c \uc815\ub9ac\ub418\uc9c0 \uc54a\ub294\ub2e4. \uad50\uc7ac\ub294 \uc774 \uacfc\uc815\uc5d0\uc11c \ud559\uc790\ub4e4\uc774 \ub2e4\ub978 \ub3c4\uc2dc\ub85c \ub5a0\ub098\uae30\ub3c4 \ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc9c0\uc2dd\uc744 \ub098\ub204\ub294 \ud658\uacbd\uc740 \uc815\uce58\uc758 \ubcc0\ud654\uc640 \ubb34\uad00\ud558\uc9c0 \uc54a\uc558\ub2e4. \uc0ac\uc9c4\uc758 \ud759\ube5b \ubcbd\uacfc \ub3cc\ucd9c\ub41c \ubd80\uc7ac, \ubb38 \uc55e\uc758 \uc0ac\ub78c\uc744 \ucc28\ub840\ub85c \ubcf4\uc790. \ub204\uad70\uac00\uc5d0\uac8c\ub294 \uc774\ub984\ub09c \uc720\uc801\uc774\uc9c0\ub9cc \ub204\uad70\uac00\uc5d0\uac8c\ub294 \uc0dd\ud65c \uc18d \uc885\uad50 \uacf5\uac04\uc774\ub2e4. \uc0ac\uc9c4\uc740 \uc911\uc138\uc758 \uc218\uc5c5 \uc7a5\uba74\uc774\ub098 \ucc45\uc758 \ub0b4\ubd80\ub97c \ubcf4\uc5ec \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc9c0\uae08 \ubcf4\uc774\ub294 \uac74\ubb3c\uacfc \uc5ed\uc0ac \uc124\uba85\uc744 \uad6c\ubcc4\ud558\uba70 \uc77d\uc73c\uba74 \ub41c\ub2e4. \ud300\ubd81\ud22c\uc758 \uc7ac\ubbf8\ub294 \uba3c \uc0ac\ub9c9\uc5d0\ub3c4 \ub73b\ubc16\uc5d0 \ucc45\uc774 \uc788\uc5c8\ub2e4\ub294 \ub180\ub77c\uc6c0\uc5d0\uc11c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \ucc98\uc74c\ubd80\ud130 \uadf8\uacf3\uc744 \uba40\uace0 \ube44\uc5b4 \uc788\ub294 \uc7a5\uc18c\ub85c \ubcf4\uc558\ub358 \uc6b0\ub9ac\uc758 \uc2dc\uc120\ub3c4 \ub3cc\uc544\ubcf4\uac8c \ud55c\ub2e4. \ubb3c\uac74\uacfc \uc0ac\ub78c, \uc2e0\uc559\uacfc \ubc30\uc6c0\uc774 \uc624\uac00\ub358 \uae38 \uc704\uc5d0\uc11c \uc774 \ub3c4\uc2dc\ub294 \uc624\ub7ab\ub3d9\uc548 \ub2e4\ub978 \uc138\uacc4\uc640 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4."}, {"id": "versailles-1789-women-bread-and-royal-move", "title": "\ubca0\ub974\uc0ac\uc720 \uc5ec\uc131 \ud589\uc9c4 \u2014 \ube75\uc744 \uad6c\ud558\ub358 \uc0ac\ub78c\ub4e4\uc774 \uc655\uc744 \uc6c0\uc9c1\uc774\ub2e4", "summary": "1789\ub14410\uc6d4 \ube75\uc744 \uc694\uad6c\ud55c \ud589\uc9c4\uc774 \uc655\uc2e4\uc758 \uac70\ucc98\uc640 \uad8c\ub825\uc758 \uc704\uce58\ub97c \ubc14\uafbc \uacfc\uc815\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/versailles-1789-women-bread-and-royal-move/index.html", "image": "../media/versailles-1789-women-bread-and-royal-move.png", "alt": "\ube44 \uc624\ub294 \uae38\uc744 \ubca0\ub974\uc0ac\uc720\ub85c \uac77\ub294 \uc5ec\uc131\ub4e4\uc744 \uadf8\ub9b0 \uc5ed\uc0ac \uc774\ud574\uc6a9 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ubca0\ub974\uc0ac\uc720 \uc5ec\uc131 \ud589\uc9c4 \u2014 \ube75\uc744 \uad6c\ud558\ub358 \uc0ac\ub78c\ub4e4\uc774 \uc655\uc744 \uc6c0\uc9c1\uc774\ub2e4 \uc2dd\ud0c1\uc758 \uc704\uae30\uc5d0\uc11c \ud30c\ub9ac\ub85c \uc62e\uaca8 \uc628 \uc655\uc2e4\uae4c\uc9c0 1789\ub14410\uc6d4 \ube75\uc744 \uc694\uad6c\ud55c \ud589\uc9c4\uc774 \uc655\uc2e4\uc758 \uac70\ucc98\uc640 \uad8c\ub825\uc758 \uc704\uce58\ub97c \ubc14\uafbc \uacfc\uc815\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc 1789\ub144 \ud504\ub791\uc2a4\ud601\uba85\uc744 \ub5a0\uc62c\ub9ac\uba74 \ubc14\uc2a4\ud2f0\uc720 \uac10\uc625\uc774\ub098 \uad6d\ubbfc\uc758\ud68c\uac00 \uba3c\uc800 \uc0dd\uac01\ub09c\ub2e4. \uadf8\ub7ec\ub098 \uadf8\ud574 10\uc6d4\uc5d0\ub294 \ud30c\ub9ac\uc758 \uc5ec\uc131\ub4e4\uc774 \ubca0\ub974\uc0ac\uc720\uae4c\uc9c0 \uac78\uc5b4\uac14\ub2e4. \ube75\uc744 \uad6c\ud558\ub824\ub294 \uc808\ubc15\ud568\uc740 \uc655\uc758 \uac70\ucc98\ub97c \ubc14\uafb8\ub294 \uc815\uce58\uc801 \uc0ac\uac74\uacfc \uc5f0\uacb0\ub418\uc5c8\ub2e4. \uc774 \ud589\uc9c4\uc744 \uc6b0\uc5f0\ud788 \ud765\ubd84\ud55c \uad70\uc911\uc758 \ud558\ub8e8\ub85c \uc904\uc774\uc9c0 \uc54a\uace0 \uc0b4\ud3b4\ubcf4\uc790. 1789\ub144 \uc5ec\ub984\uc758 \uc815\uce58\uc801 \ubcc0\ud654\ub294 \ucef8\ub2e4. \uadf8\ub7ec\ub098 \ud30c\ub9ac\uc758 \uc0dd\ud65c\uc5d0\uc11c\ub294 \ube75\uc758 \ubd80\uc871\uacfc \uac00\uaca9\uc774 \uc5ec\uc804\ud788 \uc808\ubc15\ud55c \ubb38\uc81c\uc600\ub2e4. \uba39\uc744\uac70\ub9ac\ub97c \ub9c8\ub828\ud574\uc57c \ud558\ub294 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uc0c8 \uc81c\ub3c4\uc758 \uc120\uc5b8\uacfc \uc624\ub298 \uc7a5\uc5d0 \ub098\uac00 \uc0b4 \uc218 \uc788\ub294 \ube75\uc740 \ub2e4\ub978 \ucc28\uc6d0\uc758 \uc77c\uc774\uc5c8\ub2e4. \ub2f9\uc2dc \ub3c4\uc2dc \uac00\uacc4\uc5d0\uc11c \ube75\uc774 \ucc28\uc9c0\ud558\ub294 \ube44\uc911\uc740 \ucef8\uace0 \uacf5\uae09\uc774 \ud754\ub4e4\ub9ac\uba74 \ubd88\uc548\uc774 \ud37c\uc84c\ub2e4. \uc2dc\uc7a5\uc5d0\uc11c \ubb3c\uac74\uc744 \uad6c\ud558\uace0 \uac00\uc871\uc744 \uba39\uc774\ub294 \uc5ec\uc131\ub4e4\uc740 \uadf8 \ubcc0\ud654\ub97c \uac00\uae4c\uc774\uc5d0\uc11c \uacaa\uc5c8\ub2e4. \uc0dd\ud65c\uc758 \ubb38\uc81c\ub85c \ubcf4\uc774\ub358 \uc694\uad6c\uac00 \uc815\uce58\uc758 \ud55c\uac00\uc6b4\ub370\ub85c \ub4e4\uc5b4\uc62c \uc870\uac74\uc774 \uc0dd\uae34 \uac83\uc774\ub2e4. \uc2dc\uc7a5\uacfc \uac00\uc815\uc5d0\uc11c \uc74c\uc2dd\uc744 \ub9c8\ub828\ud558\ub294 \uc77c\uc740 \uc624\ub7ab\ub3d9\uc548 \uc0ac\uc801\uc778 \uc77c\ub85c \uc5ec\uaca8\uc9c0\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \ube75\uc758 \uacf5\uae09\uc744 \ucc45\uc784\uc9c8 \uad8c\ub825\uc774 \ub204\uad6c\uc778\uac00 \ubb3b\ub294 \uc21c\uac04 \uadf8 \uc77c\uc740 \uacf5\uacf5\uc758 \ubb38\uc81c\uac00 \ub41c\ub2e4. \uc774 \ud589\uc9c4\uc740 \uc815\uce58 \ucc38\uc5ec\uac00 \uacf5\uc2dd \uc9c1\ud568\uc744 \uac00\uc9c4 \uc0ac\ub78c\uc758 \uc5f0\uc124\uc5d0\uc11c\ub9cc \uc2dc\uc791\ub418\uc9c0 \uc54a\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. 10\uc6d4 5\uc77c \ud30c\ub9ac\uc5d0\uc11c \ubaa8\uc778 \uc0ac\ub78c\ub4e4\uc740 \uc2dc\uccad\uc73c\ub85c \ud5a5\ud588\uace0 \uc774\uc5b4 \ubca0\ub974\uc0ac\uc720\ub85c \uac00\uae30 \uc2dc\uc791\ud588\ub2e4. \uc5ec\uc131\ub4e4\uc774 \ud589\ub82c\uc758 \uc911\uc694\ud55c \ubd80\ubd84\uc744 \uc774\ub8e8\uc5c8\uc9c0\ub9cc \ucc38\uc5ec\uc790\ub97c \ubaa8\ub450 \uac19\uc740 \uc9c1\uc5c5\uacfc \uc0dd\uac01\uc744 \uac00\uc9c4 \ud55c \uc9d1\ub2e8\uc73c\ub85c \ubcfc \uc218\ub294 \uc5c6\ub2e4. \ub0a8\uc131\ub4e4\ub3c4 \ud568\uaed8\ud588\uace0 \uc0ac\ub78c\ub4e4\uc758 \uc694\uad6c\uc640 \ud589\ub3d9\ub3c4 \ub2ec\ub790\ub2e4. \uadf8\ub4e4\uc740 \ube44\uc640 \uc9c4\ud759\uae38 \uc18d\uc5d0\uc11c \uae34 \uac70\ub9ac\ub97c \uc774\ub3d9\ud588\ub2e4. \uba40\ub9ac \uc788\ub294 \uad81\uc815\uc5d0 \uc9c1\uc811 \uc694\uad6c\ub97c \uc804\ub2ec\ud558\ub824\ub294 \ud589\uc704 \uc790\uccb4\uac00 \uc911\uc694\ud588\ub2e4. \uc6d0\ub798 \uc815\uce58\uc801 \uad8c\uc704\ub97c \uac00\uc9c4 \uc0ac\ub78c\ub9cc \uacf5\uc2dd \ud1b5\ub85c\ub97c \ud1b5\ud574 \ub9d0\ud560 \uc218 \uc788\uc5c8\ub358 \uacf5\uac04\uc5d0, \uc77c\uc0c1\uc758 \uc704\uae30\ub97c \uacaa\ub294 \uc0ac\ub78c\ub4e4\uc774 \ubab8\uc73c\ub85c \ub2e4\uac00\uac04 \uac83\uc774\ub2e4. \uc655\uc2e4 \uadfc\uc704\ub300\uc758 \uc5f0\ud68c\uc640 \uad00\ub828\ud55c \uc18c\ubb38\uc740 \ud30c\ub9ac\uc758 \ubd84\ub178\ub97c \uc790\uadf9\ud588\ub2e4. \uad81\uc815\uc740 \uba39\uace0 \ub9c8\uc2dc\ub294\ub370 \ub3c4\uc2dc\ub294 \uad76\ub294\ub2e4\ub294 \ub300\ube44, \ud601\uba85\uc758 \uc0c1\uc9d5\uc774 \ubaa8\uc695\ub2f9\ud588\ub2e4\ub294 \uc774\uc57c\uae30\uac00 \ud37c\uc84c\ub2e4. \uc2e4\uc81c \ud589\uc0ac\uc640 \ub4a4\uc5d0 \uc804\ud574\uc9c4 \uc138\ubd80 \uc18c\ubb38\uc740 \uad6c\ubd84\ud574\uc11c \ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \uc774 \uc0ac\uac74\uc744 \uc655\ube44\uc758 \uc0ac\uce58 \ud55c \uac00\uc9c0\ub85c \uc124\uba85\ud558\uba74 \ubd80\uc871\ud558\ub2e4. \uc7ac\uc815 \uc704\uae30\uc640 \uace1\ubb3c \uacf5\uae09, \uad6d\uc655\uc5d0 \ub300\ud55c \uc815\uce58\uc801 \ubd88\uc2e0\uc774 \uc5bd\ud600 \uc788\uc5c8\ub2e4. \uc655\ube44\uac00 \ube75 \ub300\uc2e0 \uacfc\uc790\ub97c \uba39\uc73c\ub77c\uace0 \ud588\ub2e4\ub294 \uc720\uba85\ud55c \ub9d0\uc744 \uc774 \ud589\uc9c4\uc758 \ud655\uc778\ub41c \ub300\uc0ac\ucc98\ub7fc \ubd99\uc774\ub294 \uac83\ub3c4 \uc62c\ubc14\ub978 \uc124\uba85\uc774 \uc544\ub2c8\ub2e4. \uc655\uc774 \uac00\uae4c\uc774 \uc624\uba74 \ubb38\uc81c\ub97c \ub354 \uc798 \uc54c\uac8c \ub420 \uac83\uc774\ub77c\ub294 \uae30\ub300\uc640, \uac00\uae4c\uc774 \ub450\uc5b4\uc57c \uc57d\uc18d\uc744 \uc9c0\ud0ac \uac83\uc774\ub77c\ub294 \ubd88\uc2e0\uc740 \ud568\uaed8 \uc788\uc744 \uc218 \uc788\uc5c8\ub2e4. \uc655\uc744 \ud30c\ub9ac\ub85c \ub370\ub824\uc624\ub824\ub294 \uc694\uad6c\uc5d0\uc11c\ub3c4 \ubcf4\ud638\ubc1b\uace0 \uc2f6\uc740 \ub9c8\uc74c\uacfc \uac10\uc2dc\ud558\ub824\ub294 \ub73b\uc774 \uacb9\uccd0\uc9c4\ub2e4. \uad70\uc911\uc758 \uac10\uc815\uc744 \ud55c \ub2e8\uc5b4\ub85c \ubb36\uae30 \uc5b4\ub824\uc6b4 \uc774\uc720\ub2e4. \ubca0\ub974\uc0ac\uc720\uc5d0 \ub3c4\ucc29\ud55c \uc0ac\ub78c\ub4e4\uc740 \uad6d\ubbfc\uc758\ud68c\uc640 \uc655\uc5d0\uac8c \uc694\uad6c\ub97c \uc804\ub2ec\ud588\ub2e4. \ube75 \ubb38\uc81c\ubfd0 \uc544\ub2c8\ub77c \ud601\uba85 \uc774\ud6c4\uc758 \uc815\uce58\uc801 \uacb0\uc815\uc5d0 \ub300\ud55c \uc655\uc758 \ud0dc\ub3c4\ub3c4 \uad00\uc2ec\uc758 \ub300\uc0c1\uc774\uc5c8\ub2e4. \uc0dd\uacc4\uc640 \ud5cc\uc815 \uc9c8\uc11c\uac00 \uc644\uc804\ud788 \ub098\ub25c \uc8fc\uc81c\ub294 \uc544\ub2c8\uc5c8\ub358 \uc148\uc774\ub2e4. \uc77c\ubd80 \ub300\ud45c\uac00 \ub9cc\ub098 \ud611\uc0c1\ud588\ub2e4\uace0 \ud574\uc11c \ubc16\uc758 \ubd88\uc548\uc774 \ubaa8\ub450 \uc0ac\ub77c\uc9c0\uc9c0\ub294 \uc54a\uc558\ub2e4. \ube44\ub97c \ub9de\uace0 \uc624\ub798 \uae30\ub2e4\ub9ac\ub294 \uc0ac\ub78c\ub4e4\uacfc \uad81\uc804 \uc548\uc758 \uacb0\uc815 \uc0ac\uc774\uc5d0\ub294 \ud070 \uac70\ub9ac\uac00 \uc788\uc5c8\ub2e4. \uc18c\uc218 \ub300\ud45c\uc758 \ub9d0, \uad70\uc911\uc758 \uae30\ub300, \ub2f9\uad6d\uc758 \uc57d\uc18d\uc774 \uc11c\ub85c \ub2e4\ub978 \uc18d\ub3c4\ub85c \uc6c0\uc9c1\uc600\ub2e4. \ub77c\ud30c\uc608\ud2b8\uac00 \uc774\ub044\ub294 \uad6d\ubbfc\ubc29\uc704\ub300\ub3c4 \ubca0\ub974\uc0ac\uc720\ub85c \uc654\ub2e4. \ud589\uc9c4\uc740 \ucc98\uc74c\ubd80\ud130 \ub05d\uae4c\uc9c0 \uc5ec\uc131\ub4e4\ub9cc\uc758 \ub3c5\ub9bd\ub41c \ub300\uc5f4\ub85c \uc720\uc9c0\ub41c \uac83\uc774 \uc544\ub2c8\ub77c \ubb34\uc7a5 \uc870\uc9c1\uacfc \uc758\ud68c, \uc655\uc2e4 \uacbd\ube44\uac00 \uc5bd\ud78c \ubcf5\uc7a1\ud55c \uc0ac\uac74\uc774 \ub418\uc5c8\ub2e4. \ub204\uac00 \uc9c8\uc11c\ub97c \ud1b5\uc81c\ud558\ub294\uc9c0\ub3c4 \ubd88\ud655\uc2e4\ud588\ub2e4. \ub2e4\uc74c \ub0a0 \uc544\uce68\uc5d0\ub294 \uad81\uc804\uc5d0 \uc0ac\ub78c\ub4e4\uc774 \ub4e4\uc5b4\uac00\uace0 \uacbd\ube44\ubcd1\ub4e4\uc774 \uc8fd\ub294 \ud3ed\ub825\uc774 \uc77c\uc5b4\ub0ac\ub2e4. \uc655\ube44\uac00 \uae09\ud788 \ud53c\ud574\uc57c \ud558\ub294 \uc0c1\ud669\ub3c4 \uc0dd\uacbc\ub2e4. \uc774 \uc77c\uc744 \ud3c9\ud654\ub85c\uc6b4 \uc2dc\uc704\ub85c\ub9cc \ubbf8\ud654\ud558\uac70\ub098, \ubc18\ub300\ub85c \ubaa8\ub4e0 \ucc38\uc5ec\uc790\ub97c \ud3ed\ub825 \uc9d1\ub2e8\uc73c\ub85c \ubb36\ub294 \uc124\uba85\uc740 \ub458 \ub2e4 \uc2e4\uc81c\uc758 \uc5ec\ub7ec \uce35\uc744 \uc9c0\uc6b4\ub2e4. \ud30c\ub9ac\ub85c \ud5a5\ud558\ub294 \uc655\uc2e4\uc758 \uc774\ub3d9\uc740 \ub9ce\uc740 \uc0ac\ub78c\uc774 \ubcf4\ub294 \uacf5\uac1c\uc801\uc778 \uc7a5\uba74\uc774 \ub418\uc5c8\ub2e4. \uad81\uc815\uc758 \uacb0\uc815\uc774 \uad81\uc804 \uc548\uc5d0\ub9cc \uba38\ubb3c\uc9c0 \uc54a\uace0 \uac70\ub9ac\uc758 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \ud3c9\uac00\ub418\ub294 \ubcc0\ud654\uc600\ub2e4. \uad8c\ub825\uc758 \uc0c1\uc9d5\uacfc \uc2e4\uc81c\uc758 \uac70\ucc98, \uc2dc\ubbfc\uc758 \uc2dc\uc120\uc774 \uac19\uc740 \uae38 \uc704\uc5d0\uc11c \ub9cc\ub0ac\ub2e4. \uacb0\uad6d \ub8e8\uc774 16\uc138\uc640 \uc655\uc2e4\uc740 \ud30c\ub9ac\ub85c \uc774\ub3d9\ud588\ub2e4. \uc655\uacfc \uc655\ube44, \uc655\uc138\uc790\ub97c \ube75\uc744 \uac00\uc838\ub2e4\uc8fc\ub294 \uac00\uc871\uc5d0 \ube57\ub300\uc5b4 \ubd80\ub978 \uad70\uc911\uc758 \ud45c\ud604\uc740 \uc0dd\uacc4\uc640 \uc655\uad8c\uc774 \uacb0\ud569\ud574 \uc788\uc5c8\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc655\uc2e4\uc740 \ud288\ub974\ub9ac \uad81\uc804\uc5d0 \uac70\ucc98\ub97c \ub450\uac8c \ub418\uc5c8\ub2e4. \uc774 \ubcc0\ud654\ub294 \ub2e8\uc21c\ud55c \uc774\uc0ac\uac00 \uc544\ub2c8\uc5c8\ub2e4. \uc218\ub3c4\uc758 \uc815\uce58\uc801 \uc555\ub825\uc5d0\uc11c \ub5a8\uc5b4\uc838 \uc788\ub358 \uc655\uc774 \ud30c\ub9ac \uc2dc\ubbfc\uacfc \ubb34\uc7a5 \uc138\ub825\uc758 \ub208\uc55e\uc5d0 \ub193\uc600\ub2e4. \uad6d\ubbfc\uc758\ud68c \uc5ed\uc2dc \ub4a4\uc5d0 \ud30c\ub9ac\ub85c \uc62e\uacbc\ub2e4. \ub204\uac00 \uc5b4\ub514\uc5d0\uc11c \uad8c\ub825\uc744 \ud589\uc0ac\ud558\ub294\uc9c0\uac00 \ud601\uba85\uc758 \uc9c4\ud589\uc5d0 \uc911\uc694\ud55c \uc870\uac74\uc774 \ub418\uc5c8\ub2e4. \ud589\uc9c4\uc740 \uc5ec\uc131\ub4e4\uc774 \uc815\uce58\uc758 \uc218\ub3d9\uc801\uc778 \uad00\uac1d\uc774 \uc544\ub2c8\uc5c8\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uba39\uc744\uac70\ub9ac\ub97c \uc694\uad6c\ud558\ub294 \ub9d0\ub3c4 \uad6d\uac00\uc640 \ud1b5\uce58\uc790\ub97c \ud5a5\ud55c \uc815\uce58\uc801 \uc694\uad6c\uac00 \ub420 \uc218 \uc788\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \uc774 \ud589\ub3d9\uc774 \uace7 \uc5ec\uc131\uc758 \ub3d9\ub4f1\ud55c \uc815\uce58\uc801 \uad8c\ub9ac \ubcf4\uc7a5\uc73c\ub85c \uc774\uc5b4\uc9c4 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub610\ud55c 10\uc6d4\uc758 \uc774\ub3d9\uc73c\ub85c \uc655\uc815\uc774 \uadf8\ub0a0 \ub05d\ub09c \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uc774\ud6c4\uc5d0\ub3c4 \ud0c0\ud611\uacfc \uac08\ub4f1, \uc655\uc758 \ub3c4\uc8fc \uc2dc\ub3c4\uc640 \uc804\uc7c1\uc744 \uac70\uccd0 \uc0c1\ud669\uc774 \ub2ec\ub77c\uc84c\ub2e4. \ud589\uc9c4\uc758 \uc758\ubbf8\ub294 \ud601\uba85\uc758 \uacb0\ub9d0\uc744 \ubbf8\ub9ac \uc2e4\ud604\ud588\ub2e4\ub294 \ub370\ubcf4\ub2e4, \uc0dd\ud65c\uc758 \uc704\uae30\uac00 \uad8c\ub825\uc758 \uc704\uce58\ub97c \uc2e4\uc81c\ub85c \ubc14\uafc0 \uc218 \uc788\uc74c\uc744 \ub4dc\ub7ec\ub0b8 \ub370 \uc788\ub2e4. \uce7c\ub77c\uc77c\uc758 \ud6c4\ub300 \uc5ed\uc0ac\uc11c\ub294 \uc774 \uc7a5\uba74\uc744 \uac15\ub82c\ud558\uace0 \uadf9\uc801\uc778 \uc5b8\uc5b4\ub85c \uadf8\ub9b0\ub2e4. \uc77d\uc744\uac70\ub9ac\ub85c\uc11c\uc758 \ud798\uacfc \uc0ac\uc2e4 \ud655\uc778\uc758 \uadfc\uac70\ub97c \uad6c\ubd84\ud560 \ud544\uc694\uac00 \uc788\ub2e4. \uae30\ub85d \uc18d \ub4f1\uc7a5\uc778\ubb3c\uc758 \ub9d0\uc774 \uc5b8\uc81c\ub098 \ud604\uc7a5\uc5d0\uc11c \uadf8\ub300\ub85c \ubc1b\uc544 \uc801\uc740 \ub300\uc0ac\uc778 \uac83\ucc98\ub7fc \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uc740 \uac83\ub3c4 \uadf8 \ub54c\ubb38\uc774\ub2e4."}, {"id": "zheng-he-gifts-and-indian-ocean", "title": "\uc815\ud654\uc758 \ud56d\ud574 \u2014 \ud070 \ubc30\uc5d0\ub294 \ubb34\uc5c7\uc774 \uc2e4\ub824 \uc788\uc5c8\uc744\uae4c", "summary": "1405~1433\ub144\uc758 \uc77c\uacf1 \ucc28\ub840 \uc6d0\uc815\uacfc \ub9d0\ub77c\uce74\uc758 \uad00\uacc4\ub97c \ud1b5\ud574 \ubc30\u00b7\uc120\ubb3c\u00b7\uc678\uad50\uac00 \ub9cc\ub098\ub294 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities"], "url": "stories/zheng-he-gifts-and-indian-ocean/index.html", "image": "../media/zheng-he-gifts-and-indian-ocean.png", "alt": "\uc815\ud654\uc758 \ud56d\ud574 \uc2dc\ub300\ub97c \ub5a0\uc62c\ub9ac\ub294 \uc778\ub3c4\uc591 \ud56d\uad6c\uc640 \uad50\uc5ed\uc758 \uc0c1\uc0c1 \uc7a5\uba74", "text": "\uc815\ud654\uc758 \ud56d\ud574 \u2014 \ud070 \ubc30\uc5d0\ub294 \ubb34\uc5c7\uc774 \uc2e4\ub824 \uc788\uc5c8\uc744\uae4c \uba85\ub098\ub77c\uc758 \uc120\ubb3c\uacfc \uc778\ub3c4\uc591 \ud56d\uad6c\ub4e4\uc758 \uad00\uacc4 1405~1433\ub144\uc758 \uc77c\uacf1 \ucc28\ub840 \uc6d0\uc815\uacfc \ub9d0\ub77c\uce74\uc758 \uad00\uacc4\ub97c \ud1b5\ud574 \ubc30\u00b7\uc120\ubb3c\u00b7\uc678\uad50\uac00 \ub9cc\ub098\ub294 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \ud070 \ubc30\uac00 \ud56d\uad6c\ub85c \ub4e4\uc5b4\uc624\uba74 \uc0ac\ub78c\ub4e4\uc740 \uadf8 \ud06c\uae30\ubfd0 \uc544\ub2c8\ub77c \ubb34\uc5c7\uc744 \uc2e3\uace0 \uc654\ub294\uc9c0\ub3c4 \uad81\uae08\ud574\ud55c\ub2e4. \ube44\ub2e8\uacfc \ub3c4\uc790\uae30, \uba3c \ub098\ub77c\uc758 \uc120\ubb3c\uacfc \uc0ac\uc808\uc774 \ud568\uaed8 \uc654\ub2e4\uba74 \ud56d\uad6c\uc758 \ub9cc\ub0a8\uc740 \ubb3c\uac74\uc744 \uc0ac\uace0\ud30c\ub294 \uc77c\ubcf4\ub2e4 \ub113\uc5b4\uc9c4\ub2e4. 15\uc138\uae30 \uc815\ud654\uc758 \ud56d\ud574\ub294 \uadf8\ub7f0 \uc7a5\uba74\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uba85\ub098\ub77c \uc601\ub77d\uc81c\uc758 \uc2dc\ub300\uc5d0 \uc2dc\uc791\ub41c \uc6d0\uc815\uc740 1405\ub144\ubd80\ud130 1433\ub144\uae4c\uc9c0 \uc77c\uacf1 \ucc28\ub840 \uc774\uc5b4\uc84c\ub2e4. \ub3d9\ub0a8\uc544\uc2dc\uc544\uc5d0\uc11c \uc778\ub3c4, \uc544\ub77c\ube44\uc544\uc640 \ub3d9\uc544\ud504\ub9ac\uce74\ub85c \ud5a5\ud588\ub2e4. \uc774\ubc88\uc5d0\ub294 \ubc30\uc758 \ud06c\uae30\ub97c \uacfc\uc7a5\ud558\ub294 \uc774\uc57c\uae30\ubcf4\ub2e4 \uadf8 \ubc30\uac00 \uc5b4\ub5a4 \uad00\uacc4\ub97c \ub9cc\ub4e4\ub824 \ud588\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uba85\ub098\ub77c\ub97c \uc138\uc6b4 \ud64d\ubb34\uc81c\uc640 \uadf8 \ub4a4\uc758 \uc601\ub77d\uc81c\ub294 \ubc14\ub2e4\ub97c \ub300\ud558\ub294 \uc815\ucc45\uc5d0\uc11c \ucc28\uc774\ub97c \ubcf4\uc600\ub2e4. \uad50\uc7ac\ub294 \ud64d\ubb34\uc81c\uac00 \uc678\ubd80\uc758 \uc704\ud5d8\uc744 \uacbd\uacc4\ud558\uba70 \ud574\uc0c1 \ud65c\ub3d9\uc744 \uc81c\ud55c\ud558\ub824 \ud55c \ubc18\uba74, \uc601\ub77d\uc81c\ub294 \ub2e4\ub978 \uc9c0\uc5ed\uc5d0 \uba85\ub098\ub77c\uc758 \ubd80\uc640 \ud798\uc744 \ub4dc\ub7ec\ub0b4\ub824 \ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uac19\uc740 \ub098\ub77c\uc5d0\uc11c\ub3c4 \ud1b5\uce58\uc790\uc758 \ubaa9\ud45c\uc640 \ud310\ub2e8\uc5d0 \ub530\ub77c \ud070 \uc6d0\uc815\uc758 \uc870\uac74\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \ubc30\ub97c \ub9cc\ub4e4 \uae30\uc220\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc5b8\uc81c\ub098 \uac19\uc740 \ud56d\ud574\uac00 \uc774\ub8e8\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc744 \uc5bb\uace0 \uc5b4\ub5a4 \uad00\uacc4\ub97c \ub9cc\ub4e4\ub824\ub294\uc9c0\uac00 \uc790\uae08\uacfc \uc0ac\ub78c\uc744 \uc6c0\uc9c1\uc774\ub294 \uc911\uc694\ud55c \uc774\uc720\uc600\ub2e4. \uc815\ud654\uc758 \uc120\ub2e8\uc740 \uc774\ubbf8 \uc0ac\ub78c\uacfc \ubb3c\uac74\uc774 \uc624\uac00\ub358 \uc778\ub3c4\uc591\uc758 \uc5ec\ub7ec \ud56d\uad6c\ub85c \ub098\uc544\uac14\ub2e4. \ub3d9\ub0a8\uc544\uc2dc\uc544\uc640 \uc778\ub3c4, \uc544\ub77c\ube44\uc544\uc640 \ub3d9\uc544\ud504\ub9ac\uce74\ub294 \uc11c\ub85c \ub2e4\ub978 \uc0ac\ud68c\uc640 \uad50\uc5ed\uc758 \uad00\uacc4\ub97c \uac00\uc9c4 \uc9c0\uc5ed\uc774\uc5c8\ub2e4. \ubc30\uac00 \ub098\ud0c0\ub09c \uacf3\uc744 \ub204\uad70\uac00\uac00 \ucc98\uc74c \ubc1c\uacac\ud55c \ube48 \uc138\uacc4\ucc98\ub7fc \ubcfc \uc218\ub294 \uc5c6\ub2e4. \ub530\ub77c\uc11c \ud56d\ud574\uc758 \uc758\ubbf8\ub294 \uc9c0\ub3c4\uc5d0 \ucc98\uc74c \uc774\ub984\uc744 \uc37c\ub2e4\ub294 \uc2dd\uc758 \uae30\ub85d \uacbd\uc7c1\uacfc \ub2e4\ub974\ub2e4. \uc5b4\ub5a4 \ud56d\uad6c\uc5d0 \ub4e4\uc5b4\uac00 \ub204\uad6c\ub97c \ub9cc\ub098\uace0 \ubb34\uc5c7\uc744 \uad50\ud658\ud588\ub294\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \ud070 \ubc30\uc758 \uc774\ub3d9\uc740 \uc774\ubbf8 \uc788\ub358 \ubc14\ub2e4\uc758 \uc5f0\uacb0\uc5d0 \uc0c8\ub85c\uc6b4 \uc678\uad50\uc801 \ubb34\uac8c\ub97c \ub354\ud558\ub294 \ud589\uc704\uc600\ub2e4. \uad50\uc7ac\ub294 \uc815\ud654\uac00 \uc678\uad6d \ud1b5\uce58\uc790\ub4e4\uc5d0\uac8c \ube44\ub2e8\uacfc \ub3c4\uc790\uae30, \uae08 \ub4f1\uc758 \uc120\ubb3c\uc744 \uc804\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc120\ubb3c\uc740 \ubb3c\uac74\uc758 \uc0ac\uc6a9 \uac00\uce58\ubfd0 \uc544\ub2c8\ub77c \ubcf4\ub0b8 \ub098\ub77c\uac00 \uc5b4\ub5a4 \ubd80\uc640 \uae30\uc220\uc744 \uac00\uc84c\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\uc5c8\ub2e4. \uba3c \uacf3\uc5d0\uc11c \uc628 \uc88b\uc740 \ubb3c\uac74\uc5d0\ub294 \uadf8 \ubb3c\uac74\uc744 \ubcf4\ub0bc \uc218 \uc788\ub294 \ud798\uc758 \uc774\ubbf8\uc9c0\ub3c4 \ubd99\uc5c8\ub2e4. \uc774\ub54c \uc120\ubb3c\uc744 \ud604\ub300\uc758 \uac1c\uc778\uc801\uc778 \ud638\uc758\uc640 \uc644\uc804\ud788 \uac19\uc740 \uac83\uc73c\ub85c\ub9cc \uc0dd\uac01\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub204\uad6c\uc5d0\uac8c \ubb34\uc5c7\uc744 \ubcf4\ub0b4\uace0 \uc0c1\ub300\ub97c \uc5b4\ub5bb\uac8c \ub300\ud560\uc9c0\ub294 \uc678\uad50\uc801 \uad00\uacc4\uc758 \uc77c\ubd80\uc600\ub2e4. \ud56d\uad6c\uc5d0 \ub0b4\ub824\ub193\uc740 \ubb3c\uac74\uc740 \ub9d0\ub85c \uc804\ud558\ub294 \uba54\uc2dc\uc9c0\uc640 \ud568\uaed8 \uc6c0\uc9c1\uc600\ub2e4. \uc6d0\uc815\uc740 \uc120\ubb3c\uc744 \uc8fc\uace0 \ub05d\ub098\ub294 \uc77c\ub9cc\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uad50\uc7ac\ub294 \ub3cc\uc544\uc624\ub294 \uae38\uc5d0 \uc0c1\uc544\uc640 \uc774\uad6d\uc801\uc778 \ub3d9\ubb3c \ub4f1\uc774 \uc2e4\ub838\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc5bc\ub8e9\ub9d0\uacfc \ud0c0\uc870 \uac19\uc740 \ub3d9\ubb3c\uc740 \uad81\uc815\uc5d0\uc11c \uba3c \uc9c0\uc5ed\uc758 \uc874\uc7ac\ub97c \ub208\uc55e\uc758 \uacbd\ud5d8\uc73c\ub85c \ubc14\uafb8\uc5c8\uc744 \uac83\uc774\ub2e4. \uc774\uac83\uc744 \uc624\ub298\uc758 \ub3d9\ubb3c \uc804\uc2dc \ubc29\uc2dd\uacfc \uadf8\ub300\ub85c \uac19\uc740 \uac83\uc73c\ub85c \ubcfc \ud544\uc694\ub294 \uc5c6\ub2e4. \uc911\uc694\ud55c \uc810\uc740 \uba40\ub9ac \uc788\ub294 \uad00\uacc4\uac00 \ubb3c\uac74\uacfc \uc0b4\uc544 \uc788\ub294 \uc874\uc7ac\uc758 \uc774\ub3d9\uc744 \ud1b5\ud574 \ubcf4\uc774\ub294 \ud615\ud0dc\ub97c \uc5bb\uc5c8\ub2e4\ub294 \uac83\uc774\ub2e4. \ud56d\ud574\ub294 \uc9c0\ub9ac \uc9c0\uc2dd\ubfd0 \uc544\ub2c8\ub77c \ub2e4\ub978 \uc138\uacc4\ub97c \uc0c1\uc0c1\ud558\ub294 \uc7ac\ub8cc\ub3c4 \uc62e\uacbc\ub2e4. \ub9d0\ub77c\uce74\ub294 \uc5ec\ub7ec \ubc14\ub2f7\uae38\uc774 \ub9cc\ub098\ub294 \uc911\uc694\ud55c \ud56d\uad6c\uc600\ub2e4. \uad50\uc7ac\ub294 \ub9d0\ub77c\uce74\uac00 \uba85\ub098\ub77c\uc640 \uad00\uacc4\ub97c \ub9fa\uc5c8\uace0 \uc815\ud654\uc758 \ud56d\ud574\uc5d0\uc11c\ub3c4 \ubc18\ubcf5\ud574\uc11c \ub4f1\uc7a5\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc774\uacf3\uc5d0\uc11c \uba85\ub098\ub77c\uc758 \uc0ac\uc808\uacfc \uad00\uacc4\ub97c \ub9fa\ub294 \uc77c\uc740 \uba40\ub9ac \uc788\ub294 \uac15\uad6d\uc758 \uc704\uc138\ub97c \uad6c\uacbd\ud558\ub294 \uac83\ub9cc\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ub9d0\ub77c\uce74\uc5d0\ub294 \uac00\uae4c\uc6b4 \uc138\ub825\uacfc\uc758 \uacbd\uc7c1\uc774\ub77c\ub294 \ud604\uc2e4\uc774 \uc788\uc5c8\ub2e4. \uad50\uc7ac\ub294 \uc2dc\uc554\uc758 \uc544\uc720\ud0c0\uc57c\uac00 \uc704\ud611\ud560 \ub54c \uba85\ub098\ub77c\uc758 \uc0ac\uc808\uc774 \ub9d0\ub77c\uce74\uc640\uc758 \uad00\uacc4\ub97c \ub0b4\uc138\uc6cc \uacac\uc81c\ud55c \uc77c\uc744 \uc18c\uac1c\ud55c\ub2e4. \uac19\uc740 \ud56d\ud574\ub97c \uc911\uad6d \uad81\uc815\uc5d0\uc11c \ubcfc \ub54c\uc640 \ud56d\uad6c\uc758 \ud1b5\uce58\uc790\uac00 \ubcfc \ub54c \uc758\ubbf8\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \uba85\ub098\ub77c\uc758 \uae30\ub85d\uc5d0\uc11c \uc678\uad6d\uc774 \uac00\uc838\uc628 \ubb3c\uac74\uc740 \uc870\uacf5\uc774\ub77c\ub294 \uc9c8\uc11c \uc548\uc5d0\uc11c \uc124\uba85\ub418\uae30\ub3c4 \ud588\ub2e4. \uadf8\ub7ec\ub098 \ud56d\uad6c\uc758 \uc8fc\ubbfc\uacfc \ud1b5\uce58\uc790\uac00 \uc6d0\ud558\ub294 \uc774\uc775\uacfc \uc548\uc804\uc774 \ubaa8\ub450 \uac19\uc740 \ud45c\ud604\uc73c\ub85c \uc815\ub9ac\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc758\ub840\uc758 \uc5b8\uc5b4\uc640 \uac01 \uc9c0\uc5ed\uc758 \uc2e4\uc81c \ud310\ub2e8\uc744 \ub098\ub204\uc5b4 \ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \ud070 \uad6d\uac00\uac00 \uad00\uacc4\uc758 \uc774\ub984\uc744 \uc815\ud55c\ub2e4\uace0 \uc0c1\ub300\uac00 \uc544\ubb34 \uc120\ud0dd\ub3c4 \ud558\uc9c0 \uc54a\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub9d0\ub77c\uce74\uc758 \uc0ac\ub840\ub294 \uba3c \uac15\uad6d\uacfc\uc758 \uad00\uacc4\ub97c \uac00\uae4c\uc6b4 \uc704\ud611\uc5d0 \ub300\uc751\ud558\ub294 \uc790\uc6d0\uc73c\ub85c \ud65c\uc6a9\ud560 \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc678\uad50\uc758 \uc5ed\uc0ac\uc5d0\ub294 \ud798\uc758 \ucc28\uc774\uc640 \uadf8 \ucc28\uc774 \uc18d\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c4 \ud310\ub2e8\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \uc774 \ub300\uaddc\ubaa8 \uad6d\uac00 \uc6d0\uc815\uc740 \uacc4\uc18d \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc774\uc5b4\uc9c0\uc9c0 \uc54a\uc558\ub2e4. \uad50\uc7ac\ub294 15\uc138\uae30 \uc911\ubc18 \uba85\ub098\ub77c\uc758 \uad00\uc2ec\uc774 \ub2ec\ub77c\uc9c0\ub294 \ud750\ub984\uc744 \uc124\uba85\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \ubcc0\ud654\uac00 \uc778\ub3c4\uc591\uc758 \ubaa8\ub4e0 \uad50\uc5ed\uc774\ub098 \uc911\uad6d\uc778\uc758 \ud574\uc0c1 \ud65c\ub3d9\uc744 \uac19\uc740 \ub0a0 \ub05d\ub0c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud55c \uc815\ucc45\uc758 \ubcc0\ud654\uc640 \ubc14\ub2e4 \uc804\uccb4\uc758 \uc0dd\ud65c\uc740 \ubc94\uc704\uac00 \ub2e4\ub974\ub2e4. \ub9d0\ub77c\uce74 \uac19\uc740 \ud56d\uad6c\ub4e4\uc740 \uc790\uae30 \uc9c0\uc5ed\uc758 \uad00\uacc4 \uc18d\uc5d0\uc11c \uacc4\uc18d \uc6c0\uc9c1\uc600\ub2e4. \uc815\ud654 \uc774\ud6c4\ub97c \ub2e8\uc21c\ud788 \ubb38\uc744 \ub2eb\uc544 \ubaa8\ub4e0 \ubc1c\uc804\uc774 \uba48\ucd98 \uc774\uc57c\uae30\ub85c \uc904\uc774\uae30\ubcf4\ub2e4 \ubb34\uc5c7\uc774 \uc911\ub2e8\ub418\uc5c8\uace0 \ubb34\uc5c7\uc740 \uc774\uc5b4\uc84c\ub294\uc9c0 \uad6c\ubd84\ud574 \ubcfc \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 15\uc138\uae30 \uc778\ub3c4\uc591 \ud56d\uad6c\uc758 \ub9cc\ub0a8\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc0c1\uc0c1 \uc18d \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c \uc815\ud654 \uc120\ub2e8\uc758 \uc815\ud655\ud55c \uc120\ubc15 \ud06c\uae30\ub098 \ud2b9\uc815 \uc785\ud56d \ud604\uc7a5\uc744 \ubcf5\uc6d0\ud558\uc9c0 \uc54a\uc558\ub2e4. \ubc30\uc640 \uc0ac\ub78c, \ubb3c\uac74\uc774 \ub9cc\ub098\ub294 \ubd84\uc704\uae30\ub97c \ud45c\ud604\ud55c \uadf8\ub9bc\uc774\ub2e4. \uc815\ud654\uc758 \ud56d\ud574\ub97c \uae30\uc5b5\ud560 \ub54c\ub294 \uac70\ub300\ud55c \uc120\uccb4\uc640 \ud568\uaed8 \ube44\ub2e8\uc744 \ubc1b\uc740 \ud1b5\uce58\uc790, \ubc30\ub97c \ub9de\uc740 \ud56d\uad6c, \ub2e4\ub978 \ubb3c\uac74\uc744 \uc2e3\uace0 \ub3cc\uc544\uc624\ub294 \uae38\ub3c4 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc6d0\uc815\uc758 \uc5ed\uc0ac\ub294 \ub204\uac00 \uac00\uc7a5 \ud070 \ubc30\ub97c \uac00\uc84c\ub294\uc9c0\ubcf4\ub2e4 \uadf8 \ubc30\ub85c \uc5b4\ub5a4 \uad00\uacc4\ub97c \ub9cc\ub4e4\ub824 \ud588\ub294\uc9c0 \ubb3c\uc744 \ub54c \ub354 \ub113\uc740 \uc138\uacc4\ub97c \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "zongli-yamen-1861-translation-and-diplomacy", "title": "\ucd1d\ub9ac\uc544\ubb38 \u2014 \uccad\uc758 \uc678\uad50\ub294 \uc65c \ubc88\uc5ed\ud558\ub294 \uad00\uccad\uc774 \ud544\uc694\ud588\uc744\uae4c", "summary": "\uc804\uc7c1 \ub4a4\uc758 \uc678\uad50 \ucc3d\uad6c, \ud1b5\uc5ed\uacfc \ub3d9\ubb38\uad00\uc774 \ub9e1\uc740 \uc0c8\ub85c\uc6b4 \uc5c5\ubb34\uc758 \ubc30\uacbd\uacfc \uc804\uac1c, \uc774\ud6c4\uc758 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history-cities", "category_title": "\uc5ed\uc0ac\uc640 \ub3c4\uc2dc", "subcategory": "\uc5ed\uc0ac\uc640 \uc81c\ub3c4", "categories": ["history-cities", "ideas"], "url": "stories/zongli-yamen-1861-translation-and-diplomacy/index.html", "image": "../media/zongli-yamen-1861-translation-and-diplomacy.png", "alt": "\ubb38\uc11c\ub97c \uac80\ud1a0\ud558\ub294 \uccad \uad00\uc6d0\ub4e4\uc758 \ubaa8\uc2b5\uc744 \uc0c1\uc0c1\ud55c \ucd1d\ub9ac\uc544\ubb38 \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ucd1d\ub9ac\uc544\ubb38 \u2014 \uccad\uc758 \uc678\uad50\ub294 \uc65c \ubc88\uc5ed\ud558\ub294 \uad00\uccad\uc774 \ud544\uc694\ud588\uc744\uae4c \uc804\uc7c1 \ub4a4\uc758 \uc678\uad50 \ucc3d\uad6c, \ud1b5\uc5ed\uacfc \ub3d9\ubb38\uad00\uc774 \ub9e1\uc740 \uc0c8\ub85c\uc6b4 \uc5c5\ubb34 \uc804\uc7c1 \ub4a4\uc758 \uc678\uad50 \ucc3d\uad6c, \ud1b5\uc5ed\uacfc \ub3d9\ubb38\uad00\uc774 \ub9e1\uc740 \uc0c8\ub85c\uc6b4 \uc5c5\ubb34\uc758 \ubc30\uacbd\uacfc \uc804\uac1c, \uc774\ud6c4\uc758 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc5ed\uc0ac\uc640 \uc81c\ub3c4 \uc5ed\uc0ac\uc640 \ub3c4\uc2dc \uc870\uc57d \ubb38\uc11c \ud55c \uc7a5\uc774 \ub3c4\ucc29\ud588\ub2e4. \uae00\uc790\ub97c \uc62e\uae30\ub294 \uac83\ub9cc\uc73c\ub85c \ub0b4\uc6a9\uc744 \uc774\ud574\ud588\ub2e4\uace0 \ub9d0\ud560 \uc218 \uc788\uc744\uae4c. \ud56d\uad6c\uc640 \uad00\uc138, \uc678\uad6d\uc778\uc758 \uc7ac\ud310\uc744 \ub458\ub7ec\uc2fc \ud45c\ud604\uc5d0\ub294 \uccad \uc870\uc815\uc774 \uc775\uc219\ud558\uac8c \uc6b4\uc601\ud558\ub358 \uc9c8\uc11c\uc640 \ub2e4\ub978 \uaddc\uce59\uc774 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. 1861\ub144 \uc124\uce58\ub41c \ucd1d\ub9ac\uc544\ubb38\uc740 \uc774\ub7f0 \ubb38\uc81c\ub97c \uacc4\uc18d \ucc98\ub9ac\ud560 \ucc3d\uad6c\uc600\ub2e4. \uadf8 \uc5ed\uc0ac\ub294 \uc678\uad6d\uc5b4\ub97c \ubc30\uc6b0\ub294 \uc774\uc57c\uae30\ub97c \ub118\uc5b4, \uc804\uc7c1 \ub4a4\uc758 \uc555\ubc15 \uc18d\uc5d0\uc11c \uc0c8\ub85c\uc6b4 \uc5c5\ubb34\ub97c \ub5a0\ub9e1\uc740 \uad6d\uac00 \uc870\uc9c1\uc758 \uc774\uc57c\uae30\ub2e4. \uc81c2\ucc28 \uc544\ud3b8\uc804\uc7c1 \ub9d0\uae30\uc778 1860\ub144 \uc601\uad6d\u00b7\ud504\ub791\uc2a4 \uad70\ub300\ub294 \ubca0\uc774\uc9d5\uc73c\ub85c \uc9c4\uaca9\ud588\ub2e4. \ud669\uc81c\uac00 \uc218\ub3c4\ub97c \ub5a0\ub09c \uc0c1\ud669\uc5d0\uc11c \uacf5\uce5c\uc655\uc740 \ud611\uc0c1\uacfc \uc870\uc57d \ucc98\ub9ac\uc5d0 \ub098\uc130\ub2e4. \uc804\uc7c1\uc758 \uc190\uc2e4\uacfc \uc678\uad6d\uc758 \uc694\uad6c\ub294 \ucd94\uc0c1\uc801\uc778 \ubc14\uae65 \uc18c\uc2dd\uc774 \uc544\ub2c8\ub77c \uc870\uc815\uc774 \ub2f9\uc7a5 \ud574\uacb0\ud574\uc57c \ud560 \ubb38\uc81c\uac00 \ub418\uc5c8\ub2e4. \ubca0\uc774\uc9d5\uc5d0 \uc678\uad6d \uacf5\uc0ac\ub4e4\uc774 \uc0c1\uc8fc\ud558\uac8c \ub41c \uac83\ub3c4 \ud070 \ubcc0\ud654\uc600\ub2e4. \uc815\ud574\uc9c4 \ub54c\uc5d0 \uc0ac\uc808\uc744 \ub9de\uc774\ud558\ub294 \ubc29\uc2dd\ub9cc\uc73c\ub85c\ub294 \ubc18\ubcf5\ub418\ub294 \ubb38\uc11c\uc640 \uba74\ub2f4 \uc694\uccad\uc744 \uac10\ub2f9\ud558\uae30 \uc5b4\ub824\uc6e0\ub2e4. \uc678\uad50\ub97c \uc77c\uc2dc\uc801\uc778 \uc0ac\uac74\uc774 \uc544\ub2c8\ub77c \uc77c\uc0c1\uc801\uc778 \ud589\uc815 \uc5c5\ubb34\ub85c \ub2e4\ub8f0 \uc870\uc9c1\uc774 \ud544\uc694\ud588\ub2e4. \ucd1d\ub9ac\uc544\ubb38\uc774\ub77c\ub294 \uc57d\uce6d\uc758 \uae34 \uc774\ub984\uc740 \uac01\uad6d\uacfc \uad00\ub828\ub41c \uc0ac\ubb34\ub97c \ucd1d\uad04\ud55c\ub2e4\ub294 \ub73b\uc744 \ub2f4\uace0 \uc788\uc5c8\ub2e4. \uacf5\uce5c\uc655\uacfc \ubb38\uc0c1 \ub4f1\uc740 \uc0c8\ub85c\uc6b4 \ub300\uc678 \uc5c5\ubb34\ub97c \ucc98\ub9ac\ud558\ub294 \uc8fc\uc694 \uc778\ubb3c\uc774\uc5c8\ub2e4. \uc870\uc57d\uacfc \ud1b5\uc0c1\uc5d0 \uad00\ud55c \ubb38\uc11c, \uc678\uad6d \uc0ac\uc808\uacfc\uc758 \uc811\ucd09\uc774 \uc774 \uad00\uccad\uc758 \uc5c5\ubb34\uac00 \ub418\uc5c8\ub2e4. \uc774\ub97c \uc911\uad6d\uc5d0 \uc678\uad50\uac00 \ucc98\uc74c \uc0dd\uae34 \uc21c\uac04\uc774\ub77c\uace0 \uc124\uba85\ud558\uba74 \uc774\uc804 \uc5ed\uc0ac\uac00 \uc9c0\uc6cc\uc9c4\ub2e4. \uccad\uc740 \uc774\ubbf8 \uc8fc\ubcc0 \uad6d\uac00\uc640 \ub2e4\uc591\ud55c \ubc29\uc2dd\uc73c\ub85c \uad00\uacc4\ub97c \ub9fa\uace0 \uc788\uc5c8\ub2e4. \ub2ec\ub77c\uc9c4 \uac83\uc740 \uc804\uc7c1 \ub4a4 \uc11c\uad6c \uc5f4\uac15\uacfc\uc758 \uad00\uacc4\ub97c \uc0c1\uc2dc\uc801\uc73c\ub85c \ucc98\ub9ac\ud558\ub294 \uc870\uc9c1\uacfc \uc5c5\ubb34\uc758 \ube44\uc911\uc774\uc5c8\ub2e4. \uc0c8 \uc870\uc9c1\uc774 \ubaa8\ub4e0 \ub300\uc678 \uc0ac\uc548\uc744 \ud63c\uc790 \uacb0\uc815\ud560 \uc218 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uae30\uc874 \uc911\uc559 \uad00\uccad\uacfc \uc9c0\ubc29\uc758 \uc720\ub825 \uad00\ub9ac\ub4e4\ub3c4 \uad00\ub828 \uc5c5\ubb34\ub97c \ub9e1\uc558\ub2e4. \uc870\uc815\uc758 \ud310\ub2e8\uacfc \ud56d\uad6c \ud604\uc7a5\uc758 \uc0c1\ud669\uc774 \ub2e4\ub974\uba74 \ubcf4\uace0\uc640 \ud611\uc758\ub97c \uac70\uccd0\uc57c \ud588\ub2e4. \ub530\ub77c\uc11c \ucd1d\ub9ac\uc544\ubb38\uc744 \uc624\ub298\ub0a0 \uc678\uad50\ubd80\uc640 \uc644\uc804\ud788 \uac19\uc740 \uac83\uc73c\ub85c \uc0dd\uac01\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \uc61b \uc870\uc9c1\uc744 \ubaa8\ub450 \uc5c6\uc560\uace0 \uc0c8 \uccb4\uc81c\ub97c \ub9cc\ub4e0 \uac83\uc774 \uc544\ub2c8\ub77c, \uae30\uc874\uc758 \ud1b5\uce58 \uad6c\uc870 \uc548\uc5d0 \uc0c8\ub85c\uc6b4 \ucc3d\uad6c\ub97c \ub367\ubd99\uc778 \uc131\uaca9\uc774 \uc788\uc5c8\ub2e4. \uc774\ub7f0 \uacb9\uce68\uc740 \ud0c0\ud611\uc758 \ubc29\ubc95\uc774\uba74\uc11c \ucc45\uc784\uacfc \uad8c\ud55c\uc744 \uc870\uc815\ud574\uc57c \ud558\ub294 \ubd80\ub2f4\uc774\uc5c8\ub2e4. \uc678\uad50 \uc5c5\ubb34\ub294 \uc218\ub3c4\uc758 \ucc45\uc0c1\uc5d0\ub9cc \uba38\ubb3c\uc9c0 \uc54a\uc558\ub2e4. \ud56d\uad6c\uc5d0\uc11c \uc0dd\uae34 \uc0ac\uac74\uc744 \uc774\ud574\ud558\ub824\uba74 \ud604\uc7a5\uc758 \ubcf4\uace0\uac00 \ud544\uc694\ud588\uace0 \uc911\uc559\uc758 \ub2f5\ubcc0\uc740 \ub2e4\uc2dc \uc9c0\ubc29\uc5d0\uc11c \uc9d1\ud589\ub418\uc5b4\uc57c \ud588\ub2e4. \ucd1d\ub9ac\uc544\ubb38\uc758 \uc874\uc7ac\ub9cc \ud655\uc778\ud558\uae30\ubcf4\ub2e4 \ubcf4\uace0\uc640 \uc9c0\uc2dc\uac00 \uc5b4\ub5a4 \uae38\ub85c \uc624\uac14\ub294\uc9c0\ub97c \uc0dd\uac01\ud574\uc57c \uc870\uc9c1\uc758 \uc2e4\uc81c \uc5ed\ud560\uc774 \ubcf4\uc778\ub2e4. \uc678\uad50 \ubb38\uc11c\uc758 \ud45c\ud604\uc740 \uc2e4\uc81c \uad8c\ub9ac\uc640 \uc758\ubb34\ub85c \uc5f0\uacb0\ub418\uc5c8\ub2e4. \uac19\uc740 \ubb38\uc7a5\uc744 \ub450\uace0 \uc11c\ub85c \ub2e4\ub978 \ub73b\uc744 \uc8fc\uc7a5\ud558\uba74 \ud1b5\uc0c1\uacfc \uc7ac\ud310\uc758 \ubb38\uc81c\uac00 \ub420 \uc218 \uc788\uc5c8\ub2e4. \uc870\uc815\uc5d0 \ud544\uc694\ud55c \uac83\uc740 \uc678\uad6d\uc778\uc774 \ubcf4\ub0b4 \uc900 \ubc88\uc5ed\ubb38\uc744 \uadf8\ub300\ub85c \ubc1b\uc544 \uc801\ub294 \uc0ac\ub78c\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc678\uad6d\uc5b4\uc640 \ubb38\uc11c\uc758 \ud615\uc2dd, \uc0c1\ub300\uac00 \uadfc\uac70\ub85c \uc81c\uc2dc\ud558\ub294 \uaddc\uce59\uc744 \uc774\ud574\ud560 \uc778\uc7ac\uac00 \ud544\uc694\ud588\ub2e4. \ubc88\uc5ed\uad00\uc758 \ubb38\uc81c\ub294 \uacb0\uad6d \ub204\uac00 \uc815\ubcf4\ub97c \ud310\ub2e8\ud560 \uc218 \uc788\ub294\uac00\uc758 \ubb38\uc81c\uc600\ub2e4. \uc5b8\uc5b4\ub97c \ubaa8\ub974\uba74 \ud611\uc0c1 \uc790\ub9ac\uc5d0\uc11c \uc5b4\ub5a4 \uc120\ud0dd\uc774 \uac00\ub2a5\ud55c\uc9c0\ub3c4 \uc0c1\ub300\uc758 \uc124\uba85\uc5d0 \ud06c\uac8c \uae30\ub300\uac8c \ub41c\ub2e4. \uc678\uad6d\uc5b4\ub97c \ubc30\uc6b4 \uc0ac\ub78c\uc774 \uc804\ud1b5\uc801\uc778 \uad00\uc9c1 \uacbd\ub85c\uc5d0\uc11c \uc5b4\ub5a4 \ud3c9\uac00\ub97c \ubc1b\uc744\uc9c0\ub3c4 \ubb38\uc81c\uc600\ub2e4. \uc2e4\ubb34\uc5d0 \ud544\uc694\ud558\ub2e4\ub294 \uc778\uc815\uacfc \uc0ac\ud68c\uc801\uc73c\ub85c \ub192\uc740 \uc9c0\uc704\ub97c \uc5bb\ub294 \uc77c\uc740 \uac19\uc9c0 \uc54a\uc558\ub2e4. \uc0c8 \uc9c0\uc2dd\uc758 \ub3c4\uc785\uc744 \ud559\uad50 \uc124\ub9bd \uc5f0\ub300\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b4 \uae4c\ub2ed\uc774\ub2e4. 1862\ub144 \uc678\uad6d\uc5b4 \uad50\uc721\uc744 \uc704\ud55c \ub3d9\ubb38\uad00\uc774 \ubb38\uc744 \uc5f4\uc5c8\ub2e4. \uc601\uc5b4\ub098 \ud504\ub791\uc2a4\uc5b4, \ub7ec\uc2dc\uc544\uc5b4 \ub4f1\uc744 \uac00\ub974\uce60 \uc778\ub825\uc774 \ub4e4\uc5b4\uc654\uace0 \uad50\uc721\uc740 \uc810\ucc28 \uc218\ud559\uacfc \ucc9c\ubb38\ud559 \uac19\uc740 \uc601\uc5ed\uc73c\ub85c\ub3c4 \ub113\uc5b4\uc84c\ub2e4. \uad6d\uc81c\ubc95\uc744 \uc18c\uac1c\ud558\ub294 \uc791\uc5c5 \uc5ed\uc2dc \uc774 \uc0c8\ub85c\uc6b4 \uc9c0\uc2dd\uc758 \ud658\uacbd\uacfc \uc5f0\uacb0\ub418\uc5c8\ub2e4. \ub3d9\ubb38\uad00\uc5d0 \uad00\uc5ec\ud55c \ubbf8\uad6d\uc778 \uc120\uad50\uc0ac \ub9c8\ud2f4\uc740 \uc790\uc2e0\uc758 \ucc45\uc5d0\uc11c \uc774\ub7f0 \ud655\ub300 \uacfc\uc815\uc744 \uc124\uba85\ud55c\ub2e4. \ub2e4\ub9cc \uadf8\ub294 \uac1c\ud601\uc744 \uc678\ubd80\uc778\uc774 \uc774\ub048 \uc9c4\ubcf4\ub85c \uac15\uc870\ud558\ub294 \uacbd\ud5a5\uc774 \uc788\ub2e4. \uadf8\uc758 \ud68c\uace0\ub97c \uc77d\uc744 \ub54c\uc5d0\ub294 \uadf8 \uc548\uc5d0\uc11c \ubc30\uc6b0\uace0 \uac00\ub974\uce58\uba70 \uc120\ud0dd\ud55c \uc911\uad6d\uc778\ub4e4\uc758 \ud310\ub2e8\uacfc \uc5ed\ud560\ub3c4 \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \uaddc\uce59\uc744 \ubc30\uc6b4\ub2e4\uace0 \ud798\uc758 \ucc28\uc774\uac00 \uace7 \uc0ac\ub77c\uc9c0\uc9c0\ub294 \uc54a\uc558\ub2e4. \uccad\uc774 \ub9c8\uc8fc\ud55c \uc870\uc57d \uad00\uacc4\uc5d0\ub294 \uc804\uc7c1\uc758 \uacb0\uacfc\ub85c \uac15\uc694\ub41c \uc870\uac74\uacfc \uc678\uad6d\uc758 \ud2b9\uad8c\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\uc5c8\ub2e4. \ucd1d\ub9ac\uc544\ubb38\uc758 \uc5c5\ubb34\ub294 \ucc98\uc74c\ubd80\ud130 \ub3d9\ub4f1\ud55c \uc870\uac74\uc758 \uad6d\uac00\ub4e4\uc774 \ud3c9\uc628\ud558\uac8c \ud611\uc758\ud558\ub294 \uc0c1\ud669\uacfc \ub2ec\ub790\ub2e4. \ub354\uad6c\ub098 \uc870\uc815 \ub0b4\ubd80\uc5d0\uc11c\ub3c4 \uc5b4\ub5a4 \uc9c0\uc2dd\uacfc \uc81c\ub3c4\ub97c \ubc1b\uc544\ub4e4\uc77c\uc9c0 \uc758\uacac\uc774 \uac08\ub838\ub2e4. \uc678\uad6d\uc758 \uae30\uc220\uc744 \ud65c\uc6a9\ud558\ub824\ub294 \ud544\uc694\uc640 \uae30\uc874 \uc9c8\uc11c\uc5d0 \ub300\ud55c \ubd88\uc548\uc740 \ud568\uaed8 \uc874\uc7ac\ud588\ub2e4. \uac1c\ud601\uc740 \ucc2c\uc131\uacfc \ubc18\ub300\uac00 \ubd84\uba85\ud788 \ub098\ub25c \ub2e8\uc21c\ud55c \uad6c\ub3c4\uac00 \uc544\ub2c8\ub77c \uc5ec\ub7ec \ubaa9\uc801\uc774 \ubd80\ub52a\uce58\uba70 \uc9c4\ud589\ub41c \uc120\ud0dd\uc758 \uc5f0\uc18d\uc774\uc5c8\ub2e4. \uc5b4\ub5a4 \uc81c\ub3c4\ub97c \ubc1b\uc544\ub4e4\uc77c \uac83\uc778\uac00\ub97c \ubb3b\uae30 \uc804\uc5d0 \uadf8 \uc81c\ub3c4\uac00 \ubb34\uc2a8 \uc77c\uc744 \ud558\ub294\uc9c0 \uc815\ud655\ud788 \uc544\ub294 \uacfc\uc815\uc774 \ud544\uc694\ud588\ub2e4. \uc678\uad50 \ubb38\uc11c\uc640 \uad50\uc7ac\ub294 \uadf8 \uc774\ud574\uc758 \uae30\ubc18\uc774\uc5c8\ub2e4. \ubc88\uc5ed\uc758 \ucd95\uc801\uc740 \uc989\uac01\uc801\uc778 \uc2b9\ub9ac\ub97c \uc8fc\uc9c0\ub294 \uc54a\uc544\ub3c4 \uae30\uc874\uc758 \ud45c\ud604\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b4 \uc138\uacc4\ub97c \ub2e4\ub8f0 \uc218 \uc788\uac8c \ud588\ub2e4. \ucd1d\ub9ac\uc544\ubb38\uc758 \uc5ed\uc0ac\ub97c \ud1b5\ud574 \uc804\uc7c1\uacfc \ud68c\ub2f4 \uc0ac\uc774\uc5d0 \ub193\uc778 \uae34 \uc2e4\ubb34\ub97c \ubcfc \uc218 \uc788\ub2e4. \ubb38\uc11c\uac00 \uc624\uace0, \ubc88\uc5ed\uc744 \uac80\ud1a0\ud558\uace0, \uad00\uccad \uc0ac\uc774\uc5d0\uc11c \ub2f5\uc744 \uc870\uc728\ud558\ub294 \uacfc\uc815\uc774 \uc5c6\uc73c\uba74 \uad6d\uac00\ub294 \uc9c0\uc18d\uc801\uc778 \uad00\uacc4\ub97c \uc6b4\uc601\ud560 \uc218 \uc5c6\ub2e4. \uc0c8\ub85c\uc6b4 \uc9c0\uc2dd\uc740 \uad50\uc2e4\uc744 \ub118\uc5b4 \ud589\uc815\uc758 \uc5b8\uc5b4\uac00 \ub418\uc5b4\uc57c \ud588\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \ubb38\uc11c\ub97c \uac80\ud1a0\ud558\ub294 \uad00\uc6d0\ub4e4\uc744 \uc5f0\uc0c1\ud558\ub3c4\ub85d \ub9cc\ub4e0 \uc0c1\uc0c1 \uc0bd\ud654\ub2e4. \ucd1d\ub9ac\uc544\ubb38\uc758 \uc2e4\uc81c \uc2e4\ub0b4\ub098 \ud2b9\uc815 \uc778\ubb3c\uc758 \ubaa8\uc2b5\uc744 \ubcf5\uc6d0\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc7a5\uba74\uc758 \ubd84\uc704\uae30\ubcf4\ub2e4 \uc911\uc694\ud55c \uac83\uc740 \uadf8 \ucc45\uc0c1\uc5d0 \uc5b4\ub5a4 \ubb38\uc81c\uac00 \uc62c\ub77c\uc654\uc73c\uba70, \uacb0\uc815\ud560 \uc218 \uc788\ub294 \uad8c\ud55c\uc740 \uc5b4\ub514\uc5d0 \uc788\uc5c8\ub294\uc9c0\ub97c \ubb3b\ub294 \uc77c\uc774\ub2e4."}, {"id": "abu-simbel-temple-and-rescue", "title": "\uc544\ubd80\uc2ec\ubca8 \u2014 \uc655\uc758 \uc5bc\uad74\uc744 \uc0c8\uae34 \uc808\ubcbd\uc744 \uc65c \uc62e\uacbc\uc744\uae4c", "summary": "\ub78c\uc138\uc2a4 2\uc138\uc758 \uc554\uad74 \uc2e0\uc804\uacfc 1968\ub144 \uc774\uc804\uc73c\ub85c \uc77d\ub294 \uad8c\ub825\uacfc \ubcf4\uc874\uc744 \uc774\uc57c\uae30\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uac74\ucd95", "categories": ["arts"], "url": "stories/abu-simbel-temple-and-rescue/index.html", "image": "../media/abu-simbel-temple-and-rescue.jpg", "alt": "\uc544\ubd80\uc2ec\ubca8 \ub300\uc2e0\uc804\uc758 \uac70\ub300\ud55c \ub78c\uc138\uc2a4 2\uc138 \uc88c\uc0c1\uacfc \uc815\uba74 \uc785\uad6c \uc2e4\uc81c \uc0ac\uc9c4", "text": "\uc544\ubd80\uc2ec\ubca8 \u2014 \uc655\uc758 \uc5bc\uad74\uc744 \uc0c8\uae34 \uc808\ubcbd\uc744 \uc65c \uc62e\uacbc\uc744\uae4c \ub78c\uc138\uc2a4 2\uc138\uc758 \uc554\uad74 \uc2e0\uc804\uacfc 1968\ub144 \uc774\uc804\uc73c\ub85c \uc77d\ub294 \uad8c\ub825\uacfc \ubcf4\uc874 \ub78c\uc138\uc2a4 2\uc138\uc758 \uc554\uad74 \uc2e0\uc804\uacfc 1968\ub144 \uc774\uc804\uc73c\ub85c \uc77d\ub294 \uad8c\ub825\uacfc \ubcf4\uc874\uc744 \uc774\uc57c\uae30\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uac74\ucd95 \ubb38\ud654\uc640 \uc608\uc220 \uc774\uc9d1\ud2b8 \ub0a8\ucabd\uc758 \uc544\ubd80\uc2ec\ubca8\uc5d0\uc11c\ub294 \ub124 \uac1c\uc758 \uac70\ub300\ud55c \uc88c\uc0c1\uc774 \uc815\uba74\uc744 \ubc14\ub77c\ubcf8\ub2e4. \uac19\uc740 \uc655\uc758 \uc5bc\uad74\uc774 \uc808\ubcbd\uc744 \ucc44\uc6b0\uace0, \uadf8 \uc0ac\uc774\uc758 \uc791\uc740 \uc785\uad6c\uac00 \uc2e0\uc804 \uc548\ucabd\uc73c\ub85c \uc774\uc5b4\uc9c4\ub2e4. \uc0ac\ub78c\uc758 \ubab8\ubcf4\ub2e4 \ud6e8\uc52c \ud070 \ud615\uc0c1 \uc55e\uc5d0\uc11c \uad00\ub78c\uac1d\uc740 \ud06c\uae30\uac00 \uc5b4\ub5bb\uac8c \uad8c\ub825\uc758 \uc5b8\uc5b4\uac00 \ub418\ub294\uc9c0 \uc2e4\uac10\ud55c\ub2e4. \uc774\uacf3\uc5d0\ub294 \ub610 \ud558\ub098\uc758 \ub180\ub77c\uc6b4 \uc2dc\uac04\uc774 \uacb9\uccd0 \uc788\ub2e4. \uace0\ub300\uc5d0 \ubc14\uc704\ub97c \ud30c\uc11c \ub9cc\ub4e0 \uc2e0\uc804\uc774 \ud604\ub300\uc5d0 \uc6d0\ub798\uc758 \uc790\ub9ac\uc5d0\uc11c \uc62e\uaca8\uc84c\ub2e4\ub294 \uc0ac\uc2e4\uc774\ub2e4. \uc655\uc774 \uc790\uc2e0\uc744 \uae30\uc5b5\ud558\uac8c \ub9cc\ub4e4\ub824 \ud588\ub358 \uc7a5\uc18c\ub97c \ud6c4\ub300\uc758 \uc0ac\ub78c\ub4e4\uc774 \ub2e4\uc2dc \uc9c0\ucf1c \ub0b8 \uc148\uc774\ub2e4. \uac74\uc124\uacfc \ubcf4\uc874\uc758 \uc5ed\uc0ac\ub97c \ud568\uaed8 \ub530\ub77c\uac00 \ubcf4\uc790. \uc544\ubd80\uc2ec\ubca8\uc758 \ub450 \uc2e0\uc804\uc740 \uae30\uc6d0\uc804 13\uc138\uae30 \uc774\uc9d1\ud2b8\uc758 \uc655 \ub78c\uc138\uc2a4 2\uc138\uc640 \uad00\ub828\ub41c \uac74\ucd95\uc774\ub2e4. \ud2b9\ud788 \ub300\uc2e0\uc804\uc758 \uc815\uba74\uc5d0\ub294 \uc655\uc744 \ub098\ud0c0\ub0b8 \uac70\ub300\ud55c \uc88c\uc0c1 \ub124 \uac1c\uac00 \uc788\ub2e4. \ud55c \ubc88\ub9cc \ubcf4\uc5ec \uc8fc\uc5b4\ub3c4 \uc54c\uc544\ubcfc \uc778\ubb3c\uc744 \ubc18\ubcf5\ud558\uace0 \ud655\ub300\ud558\ub294 \ubc29\uc2dd \uc790\uccb4\uac00 \uac15\ud55c \uc778\uc0c1\uc744 \uc900\ub2e4. \uc655\uc758 \ud615\uc0c1\uc740 \uc624\ub298\ub0a0\uc758 \uac1c\uc778 \ucd08\uc0c1\uacfc \uac19\uc740 \ubaa9\uc801\uc73c\ub85c\ub9cc \ub9cc\ub4e4\uc5b4\uc9c0\uc9c0 \uc54a\uc558\ub2e4. \ud1b5\uce58\uc790\uc758 \uc704\uc0c1\uacfc \uc2e0\uc131\ud55c \uc9c8\uc11c\ub97c \ub4dc\ub7ec\ub0b4\ub294 \uc7a5\uc18c\uc5d0 \ub193\uc778\ub2e4. \uc5bc\uad74\uc774 \ub2ee\uc558\ub294\uc9c0\ubcf4\ub2e4 \uc5b4\ub5a4 \ud06c\uae30\uc640 \uc790\uc138\ub85c \uc5b4\ub514\uc5d0 \ub098\ud0c0\ub098\ub294\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \uc774 \uc870\uac01\ub4e4\uc740 \uc655\uc744 \uc124\uba85\ud558\ub294 \ubb38\uc7a5\ubcf4\ub2e4 \uba3c\uc800 \ub2e4\uac00\uc624\ub294 \uad8c\ub825\uc758 \ud45c\uc9c0\ub2e4. \uc544\ubd80\uc2ec\ubca8\uc740 \uc774\uc9d1\ud2b8 \ub0a8\ucabd, \ub204\ube44\uc544 \uc9c0\uc5ed\uc5d0 \uc790\ub9ac\ud55c\ub2e4. \ud53c\ub77c\ubbf8\ub4dc\uac00 \uc788\ub294 \ubd81\ucabd\uc758 \ud48d\uacbd\ub9cc \ub5a0\uc62c\ub9ac\uba74 \uc774 \uc9c0\ub9ac\uc801 \uc758\ubbf8\ub97c \ub193\uce58\uae30 \uc27d\ub2e4. \uace0\ub300 \uc774\uc9d1\ud2b8\uc758 \uc5ed\uc0ac\ub294 \ub098\uc77c\uac15\uc744 \ub530\ub77c \uba40\ub9ac \uc774\uc5b4\uc84c\uace0 \ub0a8\ucabd \uc9c0\uc5ed\uacfc\uc758 \uad00\uacc4\ub3c4 \uc911\uc694\ud588\ub2e4. \uac70\ub300\ud55c \uc655\uc758 \uc5bc\uad74\uc740 \uadf8 \uad00\uacc4 \uc18d\uc758 \uc7a5\uc18c\uc5d0 \uc138\uc6cc\uc84c\ub2e4. \uac19\uc740 \uc870\uac01\ub3c4 \uc218\ub3c4 \ud55c\uac00\uc6b4\ub370 \ub193\uc778 \uacbd\uc6b0\uc640 \uba3c \uc9c0\uc5ed\uc758 \uae38\ubaa9\uc5d0 \ub193\uc778 \uacbd\uc6b0 \uc758\ubbf8\uac00 \ub2e4\ub974\ub2e4. \ub204\uac00 \uc774\uacf3\uc744 \ubcf4\uace0 \uc5b4\ub5a4 \uad8c\uc704\ub97c \ub290\ub07c\ub3c4\ub85d \ud588\ub294\uc9c0 \ubb3b\uac8c \ub418\uae30 \ub54c\ubb38\uc774\ub2e4. \uc2e0\uc804\uc744 \uc544\ub984\ub2e4\uc6b4 \ub3cc \uc870\uac01\uc73c\ub85c\ub9cc \ubcf4\uc9c0 \uc54a\uace0 \uc9c0\ub3c4 \uc18d\uc5d0 \ub193\uc73c\uba74 \uac74\ucd95\uc774 \ud1b5\uce58\uc758 \uacf5\uac04\uc744 \ub9cc\ub4dc\ub294 \ubc29\ubc95\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \ub300\uc2e0\uc804\uc740 \uc808\ubcbd\uc758 \ubc14\uc704\ub97c \ud30c\uc11c \uacf5\uac04\uc744 \ub9cc\ub4e0 \uc554\uad74 \uc2e0\uc804\uc774\ub2e4. \uc815\uba74\uc758 \ubb38\uc744 \uc9c0\ub098\uba74 \ud1b5\ub85c\uc640 \ub0b4\ubd80\uc758 \ubc29\ub4e4\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ubc14\uae65\uc5d0 \uc138\uc6b4 \ubcbd\ub3cc \uac74\ubb3c\ucc98\ub7fc \uc0dd\uac01\ud558\uba74 \uadf8 \ub3c5\ud2b9\ud568\uc774 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ub0b4\ubd80 \uacf5\uac04\uc744 \uc5bb\ub294 \ubc29\uc2dd\uc774 \uc7ac\ub8cc\ub97c \ub354\ud558\ub294 \uc77c\uacfc\ub294 \ub2ec\ub790\ub2e4. \ubc16\uc5d0\uc11c \ubcf4\ub294 \uac70\ub300\ud55c \uc870\uac01\uacfc \uc548\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \uc881\uc740 \uae38\uc758 \ube44\ub840\ub3c4 \ub208\uc5ec\uaca8\ubcfc \ub9cc\ud558\ub2e4. \uc655\uc758 \uc5bc\uad74\uc774 \uc9c0\ubc30\ud558\ub294 \ubc1d\uc740 \uc815\uba74\uc744 \uc9c0\ub098 \ub0b4\ubd80\ub85c \uc6c0\uc9c1\uc774\uba74 \ubab8\uc774 \ub290\ub07c\ub294 \ud06c\uae30\uc640 \ube5b\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc544\ubd80\uc2ec\ubca8\uc740 \uc815\uba74 \uc0ac\uc9c4\ubfd0 \uc544\ub2c8\ub77c \uc548\ud30e\uc758 \ucc28\uc774\ub97c \uc0c1\uc0c1\ud558\uba70 \uc77d\uc5b4\uc57c \ud558\ub294 \uac74\ucd95\uc774\ub2e4. \ub300\uc2e0\uc804\uc740 \ud574\ub9c8\ub2e4 \ud2b9\uc815\ud55c \uc2dc\uae30\uc5d0 \uc0c8\ubcbd\uc758 \ud587\ube5b\uc774 \uc548\ucabd\uae4c\uc9c0 \ub4e4\uc5b4\uc624\ub3c4\ub85d \uc124\uacc4\ub41c \uac83\uc73c\ub85c \uc54c\ub824\uc838 \uc788\ub2e4. \uace0\uc815\ub41c \ub3cc \uacf5\uac04\uc5d0 \uc6c0\uc9c1\uc774\ub294 \ud0dc\uc591\uc758 \uc2dc\uac04\uc774 \uacb9\uce5c\ub2e4. \ubcbd\uacfc \uc870\uac01\ub9cc\uc73c\ub85c \uac74\ucd95\uc744 \uc124\uba85\ud560 \ub54c \ub193\uce58\uae30 \uc26c\uc6b4 \uc694\uc18c\ub2e4. \ube5b\uc774 \ub4e4\uc5b4\uc624\ub294 \uc21c\uac04\uc5d0\ub294 \uac19\uc740 \ubc29\ub3c4 \ub2e4\ub974\uac8c \ubcf4\uc778\ub2e4. \uc774\ub97c \ud604\ub300\uc758 \uc815\ubc00 \uae30\uacc4\uc640 \ub611\uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ud574\uc11d\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uc790\uc5f0\uc758 \ubc29\ud5a5\uacfc \uc2dc\uac04\uc774 \uc885\uad50\uc801 \uacf5\uac04\uc758 \uacbd\ud5d8\uc5d0 \ucc38\uc5ec\ud588\ub2e4\ub294 \uc810\uc774\ub2e4. \uace0\ub300\uc758 \uac74\ucd95\uac00\ub294 \ub545 \uc704\uc5d0 \ud615\ud0dc\ub97c \ub9cc\ub4dc\ub294 \ub3d9\uc2dc\uc5d0 \uadf8 \uc7a5\uc18c\uc5d0\uc11c \ube5b\uc774 \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc774\ub294\uc9c0 \uace0\ub824\ud588\ub2e4. 20\uc138\uae30\uc5d0 \ub098\uc77c\uac15\uc5d0 \ud070 \ub310\uc744 \uac74\uc124\ud558\uba74\uc11c \uc2e0\uc804\uc758 \uc6d0\ub798 \uc790\ub9ac\uac00 \ubb3c\uc5d0 \uc7a0\uae38 \uc704\ud5d8\uc774 \uc0dd\uacbc\ub2e4. \ud604\ub300\uc758 \uac1c\ubc1c \uc0ac\uc5c5\uc774 \uace0\ub300 \uc720\uc0b0\uc758 \uc874\uc18d\uacfc \ucda9\ub3cc\ud55c \uac83\uc774\ub2e4. \ubb3c\uc744 \ub2e4\ub8e8\uc5b4 \ud604\uc7ac\uc758 \ud544\uc694\ub97c \ud574\uacb0\ud558\ub294 \uc77c\uacfc \ubb3c \ub54c\ubb38\uc5d0 \uacfc\uac70\uc758 \uc7a5\uc18c\ub97c \uc783\ub294 \uc77c\uc774 \uac19\uc740 \uc0ac\uc5c5 \uc548\uc5d0\uc11c \ub9cc\ub0ac\ub2e4. \uc774\ub54c \ubb38\uc81c\ub294 \ub208\uc55e\uc758 \uc870\uac01\uc744 \uc544\uae5d\uac8c \uc5ec\uae30\ub294 \ub370 \uadf8\uce58\uc9c0 \uc54a\ub294\ub2e4. \uac74\ucd95\uc740 \uc8fc\ubcc0 \uc9c0\ud615\uacfc \ube5b, \ubc29\ud5a5\uc744 \ud3ec\ud568\ud55c \uc7a5\uc18c\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \ubb3c\uac74\ucc98\ub7fc \ub4e4\uc5b4 \ub2e4\ub978 \uc9c4\uc5f4\ub300\uc5d0 \uc62c\ub824\ub193\uc744 \uc218 \uc788\ub294\uc9c0, \uc62e\uae34 \ub4a4 \ubb34\uc5c7\uc774 \uac19\uace0 \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc9c8\uc9c0\uae4c\uc9c0 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \ubcf4\uc874\uc740 \uc120\ud0dd\uacfc \uae30\uc220\uc744 \ud568\uaed8 \uc694\uad6c\ud55c\ub2e4. \uc544\ubd80\uc2ec\ubca8 \uc2e0\uc804\uc740 \uc774\uc804 \uc791\uc5c5\uc744 \uac70\uccd0 1968\ub144 \uc0c8\ub85c\uc6b4 \uc790\ub9ac\uc5d0\uc11c \ubcf4\uc874\ub418\uc5c8\ub2e4. \uc624\ub298\ub0a0 \uad00\ub78c\uac1d\uc774 \ub9cc\ub098\ub294 \ud48d\uacbd\uc5d0\ub294 \uc774 \ud604\ub300\uc758 \uad6c\ucd9c \uacfc\uc815\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4. \uc9c0\uae08\ub3c4 \uc624\ub798\ub41c \ub3cc\uc774 \ub0a8\uc544 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc \ubcf4\uba74, \uadf8\uac83\uc744 \ub0a8\uae30\uae30 \uc704\ud574 \uc7a5\uc18c\ub97c \ubc14\uafd4\uc57c \ud588\ub358 \uc5ed\uc0ac\ub294 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc774\uc804\uc740 \uc783\uc744 \uc704\uae30\uc5d0 \ub193\uc778 \uc720\uc0b0\uc744 \uc9c0\ud0a8 \uc911\uc694\ud55c \uc120\ud0dd\uc774\uc9c0\ub9cc \uc6d0\ub798\uc758 \uc7a5\uc18c\ub97c \uadf8\ub300\ub85c \uc720\uc9c0\ud55c \uac83\uacfc \ub3d9\uc77c\ud558\uc9c0\ub294 \uc54a\ub2e4. \uadf8\ub798\uc11c \ubcf4\uc874\uc758 \uc131\uacfc\uc640 \ubcc0\ud654\uc758 \uc0ac\uc2e4\uc744 \ud568\uaed8 \uc124\uba85\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uacfc\uac70\uc758 \ub3cc\uc744 \ub0a8\uae30\ub294 \uc77c\uacfc \uacfc\uac70\uc758 \ud658\uacbd\uc744 \uc644\uc804\ud788 \ub0a8\uae30\ub294 \uc77c \uc0ac\uc774\uc5d0\ub294 \ucc28\uc774\uac00 \uc788\ub2e4. \ucc98\uc74c \uc774\uacf3\uc744 \ub9cc\ub4e0 \uc0ac\ub78c\ub4e4\uc740 \uc655\uacfc \uc2e0\uc744 \uae30\ub9ac\uba70 \uc624\ub798 \uae30\uc5b5\ub418\uae30\ub97c \ubc14\ub790\uc744 \uac83\uc774\ub2e4. \ud6c4\ub300\uc758 \uc0ac\ub78c\ub4e4\uc740 \uadf8 \uc655\uc758 \ud1b5\uce58\ub97c \ubc1b\uc9c0 \uc54a\uc73c\uba74\uc11c\ub3c4 \uc2e0\uc804\uc744 \ub0a8\uae38 \uac00\uce58\uac00 \uc788\ub2e4\uace0 \ud310\ub2e8\ud588\ub2e4. \ud2b9\uc815 \ud1b5\uce58\uc790\ub97c \uc704\ud55c \uae30\ub150\ubb3c\uc774 \ub354 \ub113\uc740 \uc0ac\ub78c\ub4e4\uc758 \uc5ed\uc0ac \uc720\uc0b0\uc73c\ub85c \uc77d\ud788\uac8c \ub41c \uac83\uc774\ub2e4. \ubcf4\uc874\ub41c \uc720\uc0b0\uc744 \ubcfc \ub54c \uc774\uc804\uc758 \uc0ac\uc2e4\uc744 \uc124\uba85\ud558\ub294 \uae30\ub85d\ub3c4 \ud568\uaed8 \uc77d\ub294 \uac83\uc774 \uc88b\ub2e4. \uc644\uc131\ub41c \ubaa8\uc2b5\ub9cc \uac10\uc0c1\ud558\uba74 \ub3cc\uc774 \uc62e\uaca8\uc9c4 \uacbd\uc704\ub97c \uc54c\uae30 \uc5b4\ub835\ub2e4. \ubb34\uc5c7\uc774 \uc6d0\ub798 \ub0a8\uc740 \ubd80\ubd84\uc774\uba70 \ubb34\uc5c7\uc774 \ud6c4\ub300\uc758 \ub178\ub825\uc73c\ub85c \uc720\uc9c0\ub418\uc5c8\ub294\uc9c0 \uc544\ub294 \uc77c\ub3c4 \uac10\uc0c1\uc758 \uc77c\ubd80\ub2e4. \uc544\ubd80\uc2ec\ubca8\uc744 \ubcfc \ub54c\uc5d0\ub294 \ub124 \uac1c\uc758 \uc5bc\uad74 \ub4a4\uc5d0 \ub450 \ubc88\uc758 \uac70\ub300\ud55c \uc77c\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ubc14\uc704\ub97c \ud30c\uc11c \uc2e0\uc804\uc744 \ub9cc\ub4e0 \uc77c\uacfc, \uc0ac\ub77c\uc9c8 \uc704\uae30\uc758 \uc2e0\uc804\uc744 \uc62e\uaca8 \ub0a8\uae34 \uc77c\uc774\ub2e4. \uc774 \uc7a5\uc18c\ub294 \uc778\uac04\uc774 \ubb34\uc5c7\uc744 \ud06c\uac8c \ub9cc\ub4e4\uace0 \ubb34\uc5c7\uc744 \uc624\ub798 \uc9c0\ud0a4\ub824 \ud558\ub294\uc9c0 \uc11c\ub85c \ub2e4\ub978 \uc2dc\ub300\uc758 \ub2f5\uc744 \ud568\uaed8 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "aida-triumphal-march-private-grief", "title": "\u300e\uc544\uc774\ub2e4\u300f \u2014 \uac1c\uc120\ud589\uc9c4\uace1\uc774 \uc6b8\ub9b4 \ub54c \uc2ac\ud37c\ud558\ub294 \uc0ac\ub78c\ub4e4", "summary": "\uc544\uc774\ub2e4\u00b7\ub77c\ub2e4\uba54\uc2a4\u00b7\uc554\ub124\ub9ac\uc2a4\uc758 \uac08\ub4f1\uacfc \ub300\ud45c \uc74c\uc545\uc744 \uc904\uac70\ub9ac\u00b7\uacb0\ub9d0\uacfc \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc74c\uc545", "categories": ["arts"], "url": "stories/aida-triumphal-march-private-grief/index.html", "image": "../media/aida-triumphal-march-private-grief.png", "alt": "\uadf8\ub298\uc758 \uc544\uc774\ub2e4\uc640 \uc7a5\uc218 \ub4a4\ub85c \uc774\uc9d1\ud2b8\uc758 \uac1c\uc120 \ud589\ub82c\uc774 \uc774\uc5b4\uc9c0\ub294 \uc0c1\uc0c1 \uc624\ud398\ub77c \uc7a5\uba74", "text": "\u300e\uc544\uc774\ub2e4\u300f \u2014 \uac1c\uc120\ud589\uc9c4\uace1\uc774 \uc6b8\ub9b4 \ub54c \uc2ac\ud37c\ud558\ub294 \uc0ac\ub78c\ub4e4 \ubca0\ub974\ub514\uc758 \ud654\ub824\ud55c \uc2b9\ub9ac \uc7a5\uba74 \ub4a4\uc5d0 \uc228\uc740 \uc138 \uc0ac\ub78c\uc758 \ube44\uadf9 \uc544\uc774\ub2e4\u00b7\ub77c\ub2e4\uba54\uc2a4\u00b7\uc554\ub124\ub9ac\uc2a4\uc758 \uac08\ub4f1\uacfc \ub300\ud45c \uc74c\uc545\uc744 \uc904\uac70\ub9ac\u00b7\uacb0\ub9d0\uacfc \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4. \uc74c\uc545 \ubb38\ud654\uc640 \uc608\uc220 \ud589\uc9c4\uace1\uc774 \uc6b8\ub9ac\uace0 \uad70\ub300\uac00 \ub3cc\uc544\uc628\ub2e4. \ubb34\ub300\ub294 \uc0ac\ub78c\uacfc \uae43\ubc1c\ub85c \uac00\ub4dd\ud558\uace0 \uad00\uac1d\uc740 \uc2b9\ub9ac\uc758 \uaddc\ubaa8\uc5d0 \uc555\ub3c4\ub41c\ub2e4. \uadf8\ub7f0\ub370 \uadf8 \uc7a5\uba74\uc5d0 \uc788\ub294 \ubaa8\ub450\uac00 \uae30\uc05c \uac83\uc740 \uc544\ub2c8\ub2e4. \u300e\uc544\uc774\ub2e4\u300f\uc758 \uc7ac\ubbf8\uc640 \uc544\ud514\uc740 \uc774\ub807\uac8c \uac19\uc740 \uc74c\uc545 \uc544\ub798 \uc11c\ub85c \ub2e4\ub978 \ub9c8\uc74c\uc774 \ub193\uc778\ub2e4\ub294 \ub370 \uc788\ub2e4. \ubca0\ub974\ub514\uc758 \uc624\ud398\ub77c\ub294 1871\ub144 \uce74\uc774\ub85c\uc5d0\uc11c \ucd08\uc5f0\ub418\uc5c8\ub2e4. \uc548\ud1a0\ub2c8\uc624 \uae30\uc2ac\ub780\ucd08\ub2c8\uac00 \ub300\ubcf8\uc744 \uc37c\uace0, \uace0\ub300 \uc774\uc9d1\ud2b8\ub97c \ubb34\ub300\ub85c \uc0bc\ub294\ub2e4. \ub2e4\ub9cc \uc2e4\uc81c \uace0\ub300\uc758 \ud55c \uc0ac\uac74\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc5ed\uc0ac\ub294 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \ube44\uadf9\uc758 \uacb0\ub9d0\uae4c\uc9c0 \ub530\ub77c\uac00 \ubcf8\ub2e4. \uc544\uc774\ub2e4\ub294 \uc774\uc9d1\ud2b8\uc5d0\uc11c \ud3ec\ub85c\uc774\uc790 \ub178\uc608\uc758 \ucc98\uc9c0\ub85c \uc0b4\uc544\uac04\ub2e4. \ud558\uc9c0\ub9cc \ubcf8\ub798 \uc5d0\ud2f0\uc624\ud53c\uc544 \uc655 \uc544\ubaa8\ub098\uc2a4\ub85c\uc758 \ub538\uc774\ub2e4. \uc0ac\ub791\ud558\ub294 \uc0ac\ub78c\uc740 \uc774\uc9d1\ud2b8\uc758 \uc7a5\uc218 \ub77c\ub2e4\uba54\uc2a4\ub2e4. \ub450 \uc0ac\ub78c\uc774 \uac00\uae4c\uc6cc\uc9c0\uace0 \uc2f6\ub2e4\ub294 \uc18c\ub9dd\uc740 \ucc98\uc74c\ubd80\ud130 \uc804\uc7c1\uacfc \uc2e0\ubd84\uc758 \ubcbd \uc548\uc5d0 \ub193\uc778\ub2e4. \uac8c\ub2e4\uac00 \uc774\uc9d1\ud2b8 \uc655\uc758 \ub538 \uc554\ub124\ub9ac\uc2a4\ub3c4 \ub77c\ub2e4\uba54\uc2a4\ub97c \uc0ac\ub791\ud55c\ub2e4. \ub450 \uc5ec\uc778\uc758 \ub9c8\uc74c\uc774 \uac19\uc740 \uc0ac\ub78c\uc744 \ud5a5\ud558\uc9c0\ub9cc, \uadf8 \ub9c8\uc74c\uc744 \ud45c\ud604\ud558\uace0 \uc0c1\ub300\ub97c \uc555\ubc15\ud560 \uc218 \uc788\ub294 \ud798\uc740 \uac19\uc9c0 \uc54a\ub2e4. \uc544\uc774\ub2e4\uc758 \ub9d0 \ud55c\ub9c8\ub514\uc5d0\ub294 \uc704\ud5d8\uc774 \ub530\ub974\uace0 \uc554\ub124\ub9ac\uc2a4\uc758 \uc758\uc2ec\uc5d0\ub294 \uad8c\ub825\uc774 \ubd99\ub294\ub2e4. \ub2e8\uc21c\ud55c \uc0bc\uac01\uad00\uacc4\ub9cc\uc73c\ub85c \ubcf4\uae30 \uc5b4\ub824\uc6b4 \uc774\uc720\ub2e4. \ub77c\ub2e4\uba54\uc2a4\ub294 \uc804\uc7c1\uc5d0\uc11c \uacf5\uc744 \uc138\uc6b0\uba74 \uc544\uc774\ub2e4\uc640\uc758 \ubbf8\ub798\ub3c4 \uc5f4\ub9b4 \uac83\uc774\ub77c\uace0 \uae30\ub300\ud55c\ub2e4. \uadf8\uac00 \ubd80\ub974\ub294 \u300c\uccad\uc544\ud55c \uc544\uc774\ub2e4\u300d\uc5d0\ub294 \uc0ac\ub791\uacfc \ud76c\ub9dd\uc774 \ub2f4\uae34\ub2e4. \ud55c\ud3b8 \uc804\uc7c1\uc744 \uc55e\ub454 \uc544\uc774\ub2e4\uc5d0\uac8c\ub294 \uc2b9\ub9ac\ub97c \ubc14\ub77c\ub294 \ub9d0\uc870\ucc28 \uc26c\uc6b8 \uc218 \uc5c6\ub2e4. \uc5f0\uc778\uc774 \uc774\uae30\uba74 \uace0\ud5a5\uacfc \uac00\uc871\uc774 \ud328\ud560 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc544\uc774\ub2e4\uc758 \u300c\uc774\uae30\uace0 \ub3cc\uc544\uc624\ub77c\u300d\ub294 \ubc14\ub85c \uadf8 \ucda9\ub3cc\uc744 \ub4dc\ub7ec\ub0b8\ub2e4. \ub0a8\ub4e4\uc774 \ud55c \ubc29\ud5a5\uc73c\ub85c \uc678\uce58\ub294 \ub9d0\uc744 \uc790\uc2e0\uc740 \uac19\uc740 \ub9c8\uc74c\uc73c\ub85c \uc678\uce60 \uc218 \uc5c6\ub2e4. \uadf8\ub140\uac00 \uac08\ub4f1\ud558\ub294 \uae4c\ub2ed\uc740 \uc0ac\ub791\uc774 \ubd80\uc871\ud574\uc11c\uac00 \uc544\ub2c8\ub2e4. \ub204\uad6c\ub97c \ubc14\ub77c\ubcf4\ub290\ub0d0\uc5d0 \ub530\ub77c \ubc14\ub77c\ub294 \uacb0\uacfc\uac00 \ub2ec\ub77c\uc9c0\ub294 \uc0c1\ud669\uc5d0 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc554\ub124\ub9ac\uc2a4\ub294 \uc544\uc774\ub2e4\uc758 \ub9c8\uc74c\uc744 \ud655\uc778\ud558\ub824 \ub77c\ub2e4\uba54\uc2a4\uac00 \uc8fd\uc5c8\ub2e4\uace0 \ub9d0\ud55c\ub2e4. \uc544\uc774\ub2e4\uac00 \ud06c\uac8c \ud754\ub4e4\ub9ac\ub294 \ubc18\uc751\uc744 \ubcf4\uc790 \uc758\uc2ec\uc740 \ud655\uc2e0\uc73c\ub85c \ubc14\ub010\ub2e4. \ub204\uad70\uac00\ub97c \ub5a0\ubcf4\ub294 \uc9e7\uc740 \ub300\ud654\uc774\uc9c0\ub9cc \ub450 \uc0ac\ub78c\uc758 \ud798\uc758 \ucc28\uc774\uac00 \uc120\uba85\ud558\uac8c \ub4dc\ub7ec\ub09c\ub2e4. \ud55c\ucabd\uc740 \uc815\ubcf4\ub97c \uc2dc\ud5d8 \uc0bc\uc544 \uc4f8 \uc218 \uc788\uace0 \ub2e4\ub978 \ucabd\uc740 \uadf8 \ub9d0\uc5d0 \uc0b6\uc774 \ud754\ub4e4\ub9b0\ub2e4. \uc554\ub124\ub9ac\uc2a4\uc5d0\uac8c\ub3c4 \uc9c4\uc2ec\uc740 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc9c4\uc2ec\uc774 \uc788\ub2e4\uace0 \ud574\uc11c \uc0c1\ub300\ub97c \uc704\ud611\ud558\uace0 \uc120\ud0dd\uc744 \ube7c\uc557\ub294 \ud589\ub3d9\uc774 \uc815\ub2f9\ud574\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc791\ud488\uc740 \uadf8\ub140\uc758 \uc9c8\ud22c\ub97c \uc74c\uc545\uc73c\ub85c \uac15\ud558\uac8c \ub4e4\ub824\uc8fc\uba74\uc11c\ub3c4, \ub098\uc911\uc5d0\ub294 \uc790\uae30 \ud589\ub3d9\uc774 \ubd88\ub7ec\uc628 \uacb0\uacfc \uc55e\uc5d0\uc11c \ubb34\ub108\uc9c0\ub294 \ubaa8\uc2b5\uae4c\uc9c0 \ubcf4\uc5ec \uc900\ub2e4. \ucc98\uc74c\ubd80\ud130 \uac10\uc815\uc774 \ud558\ub098\uc778 \uc545\uc5ed\uc73c\ub85c\ub9cc \ub0a8\uc9c0 \uc54a\ub294\ub2e4. \ub77c\ub2e4\uba54\uc2a4\uac00 \uc2b9\ub9ac\ud574 \ub3cc\uc544\uc624\ub294 \uac1c\uc120 \uc7a5\uba74\uc740 \uc774 \uc791\ud488\uc758 \uc720\uba85\ud55c \ubcfc\uac70\ub9ac\ub2e4. \uad70\ub300\uc640 \uc2dc\ubbfc, \uc655\uacfc \uc0ac\uc81c, \ud3ec\ub85c\ub4e4\uc774 \ud55c\uacf3\uc5d0 \ubaa8\uc778\ub2e4. \ud589\uc9c4\uacfc \ud569\ucc3d\uc740 \uc774\uc9d1\ud2b8\uc758 \ud798\uc744 \ub4dc\ub7ec\ub0b8\ub2e4. \uadf8\ub7ec\ub098 \uc544\uc774\ub2e4\uc758 \ub208\uc5d0\ub294 \uadf8 \ud589\ub82c \uc18d\uc5d0 \uc7a1\ud600 \uc628 \uc544\ubc84\uc9c0\uac00 \ubcf4\uc778\ub2e4. \uc544\ubaa8\ub098\uc2a4\ub85c\ub294 \uc790\uc2e0\uc758 \uc655\uc774\ub77c\ub294 \uc2e0\ubd84\uc744 \uac10\ucd98\ub2e4. \ub77c\ub2e4\uba54\uc2a4\ub294 \ud3ec\ub85c\ub4e4\uc758 \uc0dd\uba85\uc744 \uc0b4\ub824 \ub2ec\ub77c\uace0 \uccad\ud558\uace0, \uc655\uc740 \uc77c\ubd80\ub97c \ud480\uc5b4 \uc8fc\ub418 \uc544\uc774\ub2e4\uc640 \uc544\ubc84\uc9c0\ub294 \ub0a8\uae34\ub2e4. \uc774\uc5b4 \uc2b9\ub9ac\uc758 \ubcf4\uc0c1\uc73c\ub85c \uc554\ub124\ub9ac\uc2a4\uc640 \ub77c\ub2e4\uba54\uc2a4\uc758 \uacb0\ud63c\uc744 \uc815\ud55c\ub2e4. \ubaa8\ub450\uac00 \ud658\ud638\ud558\ub294 \uc21c\uac04 \ub450 \uc5f0\uc778\uc758 \uae38\uc740 \uc624\ud788\ub824 \ub9c9\ud78c\ub2e4. \uc74c\uc545\uc758 \uac89\ubaa8\uc2b5\uacfc \uc778\ubb3c\uc758 \uc18d\ub9c8\uc74c\uc774 \uc5b4\uae0b\ub098\ub294 \uc7a5\uba74\uc774\ub2e4. \uc6c5\uc7a5\ud55c \ub0ae\uc758 \uc7a5\uba74 \ub4a4\uc5d0\ub294 \ub2e4\ub978 \ud06c\uae30\uc758 \uc74c\uc545\uc774 \uc628\ub2e4. \uc544\uc774\ub2e4\ub294 \uace0\ud5a5\uc758 \ud478\ub978 \ud558\ub298\uacfc \uc775\uc219\ud55c \ud48d\uacbd\uc744 \uadf8\ub9ac\uc6cc\ud55c\ub2e4. \uc2b9\ub9ac\uc758 \uc5b8\uc5b4\ub85c\ub294 \uc124\uba85\ub418\uc9c0 \uc54a\ub358 \ud55c \uc0ac\ub78c\uc758 \uc0c1\uc2e4\uc774 \uc55e\uc73c\ub85c \ub098\uc628\ub2e4. \u300c\uc624, \ub098\uc758 \uace0\ud5a5\uc774\uc5ec\u300d\ub85c\ub3c4 \uc54c\ub824\uc9c4 \ub178\ub798\uac00 \uc778\uc0c1\uc801\uc778 \uac83\uc740 \ud654\ub824\ud55c \ubb34\ub300 \uc548\uc5d0 \uc5c6\ub294 \uc7a5\uc18c\ub97c \ub4e3\uac8c \ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \uc544\ubc84\uc9c0\ub294 \ub538\uc758 \uc0ac\ub791\uc744 \uc54c\uc544\ucc44\uace0 \ub77c\ub2e4\uba54\uc2a4\uc5d0\uac8c\uc11c \uad70\uc0ac \uc815\ubcf4\ub97c \uc5bb\uc73c\ub77c\uace0 \uc694\uad6c\ud55c\ub2e4. \uc544\uc774\ub2e4\ub294 \uc5f0\uc778\uacfc \uc870\uad6d \uc0ac\uc774\uc5d0\uc11c \ub354 \ub0a0\uce74\ub85c\uc6b4 \uc555\ubc15\uc744 \ubc1b\ub294\ub2e4. \uac00\uc871\uc744 \uc0ac\ub791\ud558\ub77c\ub294 \ub9d0\ub3c4 \uc774 \uc21c\uac04\uc5d0\ub294 \ub538\uc744 \uc6c0\uc9c1\uc774\ub294 \ud798\uc774 \ub41c\ub2e4. \uc5b4\ub290 \ucabd\uc744 \ud0dd\ud574\ub3c4 \uc0c1\ucc98 \uc5c6\uc774 \ube60\uc838\ub098\uac08 \uae38\uc774 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc544\uc774\ub2e4\ub294 \ub77c\ub2e4\uba54\uc2a4\uc640 \ud568\uaed8 \ub2ec\uc544\ub0a0 \uae38\uc744 \uc774\uc57c\uae30\ud55c\ub2e4. \uadf8\ub294 \uc9c0\ub098\uac08 \uacbd\ub85c\uc5d0 \uad00\ud55c \uc815\ubcf4\ub97c \ub9d0\ud558\uace0, \uc228\uc5b4 \uc788\ub358 \uc544\ubaa8\ub098\uc2a4\ub85c\ub294 \uadf8 \ub0b4\uc6a9\uc744 \ub4e3\ub294\ub2e4. \ube44\ubc00\uc774 \ubc16\uc73c\ub85c \ub098\uc654\uc74c\uc744 \uc54c\uac8c \ub41c \ub77c\ub2e4\uba54\uc2a4\ub294 \uc790\uc2e0\uc774 \uc5b4\ub5a4 \uc77c\uc744 \ud588\ub294\uc9c0 \uae68\ub2eb\ub294\ub2e4. \uc0ac\ub791\uc744 \uc704\ud55c \ub300\ud654\uac00 \uad70\uc0ac\uc801\uc778 \uc0ac\uac74\uc774 \ub41c\ub2e4. \uc554\ub124\ub9ac\uc2a4\uc640 \uc0ac\uc81c\ub4e4\uc774 \ub098\ud0c0\ub098\uace0 \uc544\uc774\ub2e4\uc640 \uc544\ubc84\uc9c0\ub294 \ub2ec\uc544\ub098\uc9c0\ub9cc \ub77c\ub2e4\uba54\uc2a4\ub294 \ub0a8\ub294\ub2e4. \uc5ec\uae30\uc11c \ube44\uadf9\uc740 \ud55c \uc0ac\ub78c\uc758 \ub9d0\uc2e4\uc218\ub9cc\uc73c\ub85c \uc0dd\uae34 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc5f0\uc778\uc744 \ud0dd\ud558\ub294 \ud589\ub3d9\uc774 \uad6d\uac00\uc5d0 \ub300\ud55c \ubc30\uc2e0\uc73c\ub85c \uc77d\ud788\ub294 \uad6c\uc870, \uac00\uc871\uacfc \uc804\uc7c1\uc774 \uc0ac\uc801\uc778 \uad00\uacc4 \uc548\uc73c\ub85c \ub4e4\uc5b4\uc640 \uc788\ub358 \uc0c1\ud669\uc774 \ud568\uaed8 \uc791\ub3d9\ud55c\ub2e4. \uc554\ub124\ub9ac\uc2a4\ub294 \uc774\uc81c \ub77c\ub2e4\uba54\uc2a4\ub97c \uc0b4\ub9ac\ub824 \ud55c\ub2e4. \uadf8\ub7ec\ub098 \uadf8\uac00 \uc544\uc774\ub2e4\ub97c \ubc84\ub9ac\uace0 \uc790\uc2e0\uc5d0\uac8c \ub3cc\uc544\uc624\uae30\ub97c \ubc14\ub77c\ub294 \ub9c8\uc74c\uacfc \uc0c1\ub300\ub97c \uc0b4\ub9ac\uace0 \uc2f6\uc740 \ub9c8\uc74c\uc774 \uc27d\uac8c \ubd84\ub9ac\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub77c\ub2e4\uba54\uc2a4\ub294 \uadf8\ub140\uac00 \uc6d0\ud558\ub294 \ub2f5\uc744 \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \uc2ec\ud310\uc740 \uc9c4\ud589\ub418\uace0, \uadf8\ub294 \uc9c0\ud558 \uacf5\uac04\uc5d0 \uac07\ud600 \uc0dd\uc744 \ub9c8\uac10\ud558\ub294 \ud615\uc744 \ubc1b\ub294\ub2e4. \uc554\ub124\ub9ac\uc2a4\uc758 \uc9c0\uc704\ub3c4 \uacb0\uacfc\ub97c \ub9c8\uc74c\ub300\ub85c \ubc14\uafb8\uc9c0 \ubabb\ud55c\ub2e4. \uc9c8\ud22c\ub85c \uc0c1\ub300\ub97c \uc6c0\uc9c1\uc77c \uc218 \uc788\ub2e4\uace0 \uc0dd\uac01\ud588\ub358 \uc778\ubb3c\uc740 \ub9c8\uce68\ub0b4 \uc0ac\uc81c\ub4e4\uc758 \ud310\ub2e8 \uc55e\uc5d0\uc11c \uc808\ub9dd\ud55c\ub2e4. \ud798\uc744 \uac00\uc84c\ub358 \uc0ac\ub78c\ub9c8\uc800 \uc790\uc2e0\uc774 \ub4e4\uc5b4\uac04 \uccb4\uacc4\ub97c \uba48\ucd9c \uc218 \uc5c6\uac8c \ub41c\ub2e4. \uadf8\ub54c \uadf8\ub140\uc758 \uace0\ud1b5\ub3c4 \uad00\uac1d\uc5d0\uac8c \uac00\uae4c\uc774 \ub4e4\ub9b0\ub2e4. \ub9c8\uc9c0\ub9c9 \ubb34\ub300\ub294 \uc704\uc640 \uc544\ub798\ub85c \ub098\ub25c\ub2e4. \uac07\ud78c \ub77c\ub2e4\uba54\uc2a4\ub294 \uc544\uc774\ub2e4\uac00 \uc774\ubbf8 \uadf8\uacf3\uc5d0 \uc640 \uc788\uc74c\uc744 \uc54c\uac8c \ub41c\ub2e4. \ub450 \uc0ac\ub78c\uc740 \uc9c0\uc0c1\uacfc \uc791\ubcc4\ud558\ub294 \ub178\ub798\ub97c \ubd80\ub974\uace0, \uc704\uc5d0\uc11c\ub294 \uc554\ub124\ub9ac\uc2a4\uac00 \ud3c9\ud654\ub97c \ube48\ub2e4. \uc7a5\ub300\ud55c \uac1c\uc120 \uc7a5\uba74\uacfc \ub2ec\ub9ac \ub9c8\uc9c0\ub9c9\uc758 \ud798\uc740 \uac00\uae4c\uc6b4 \ubaa9\uc18c\ub9ac\uc640 \uc870\uc6a9\ud55c \uc774\ubcc4\uc5d0\uc11c \ub098\uc628\ub2e4. \uc774 \uacb0\ub9d0\uc740 \uc0ac\ub791\ud55c\ub2e4\uba74 \ud568\uaed8 \uc8fd\uc5b4\uc57c \ud55c\ub2e4\ub294 \uc0dd\ud65c\uc758 \ubcf8\ubcf4\uae30\uac00 \uc544\ub2c8\ub2e4. \uc0b4\uc544\uc11c \ud568\uaed8\ud560 \uae38\uc744 \ud5c8\ub77d\ud558\uc9c0 \uc54a\uc740 \uc138\uacc4\uc758 \ube44\uadf9\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \uac1c\uc120\ud589\uc9c4\uace1\uc744 \ub4e3\uac8c \ub418\uba74 \uc2b9\ub9ac\uc758 \ud589\ub82c \uc606\uc5d0\ub3c4 \uc2dc\uc120\uc744 \uc8fc\uc5b4 \ubcf4\uc790. \u300e\uc544\uc774\ub2e4\u300f\ub294 \uac00\uc7a5 \ud06c\uac8c \ud658\ud638\ud558\ub294 \uc74c\uc545 \uc548\uc5d0\uc11c\uc870\ucc28 \ub4e4\ub9ac\uc9c0 \uc54a\ub294 \uc2ac\ud514\uc774 \uc788\uc744 \uc218 \uc788\uc74c\uc744 \ub05d\uae4c\uc9c0 \uae30\uc5b5\ud558\uac8c \ud55c\ub2e4."}, {"id": "ajanta-caves-prayer-halls-painting-and-monks", "title": "\uc544\uc794\ud0c0 \uc11d\uad74 \u2014 \ubc14\uc704\ub97c \ud30c\uc11c \ube5b\uacfc \uc774\uc57c\uae30\ub97c \ub2f4\ub2e4", "summary": "\ubc14\uc704\ub97c \ud30c\ub0b8 \uc608\ubc30\ud640\uacfc \uc2b9\uc6d0, \ube5b\uacfc \ub3d9\uc120, \uc870\uac01\uacfc \ubcbd\ud654\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uac74\ucd95", "categories": ["arts"], "url": "stories/ajanta-caves-prayer-halls-painting-and-monks/index.html", "image": "../media/ajanta-caves-prayer-halls-painting-and-monks.jpg", "alt": "\uc544\uc794\ud0c0 19\ubc88 \uc11d\uad74\uc758 \ud070 \uc785\uad6c\uc640 \uc815\uba74 \uc870\uac01\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc2e4\uc81c \uc720\uc801 \uc5ed\uc0ac \ub3c4\ud310", "text": "\uc544\uc794\ud0c0 \uc11d\uad74 \u2014 \ubc14\uc704\ub97c \ud30c\uc11c \ube5b\uacfc \uc774\uc57c\uae30\ub97c \ub2f4\ub2e4 \ucc28\uc774\ud2f0\uc57c\uc640 \ube44\ud558\ub77c, \ub3cc \uc18d\uc758 \ubaa9\uc870 \ud615\uc2dd\uacfc \ubcbd\ud654 \ubc14\uc704\ub97c \ud30c\ub0b8 \uc608\ubc30\ud640\uacfc \uc2b9\uc6d0, \ube5b\uacfc \ub3d9\uc120, \uc870\uac01\uacfc \ubcbd\ud654\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uac74\ucd95 \ubb38\ud654\uc640 \uc608\uc220 \uc778\ub3c4 \uc544\uc794\ud0c0 \uc11d\uad74\uc740 \ubc14\uc704\ub97c \ub6ab\uc5b4 \ub9cc\ub4e0 \ubd88\uad50 \uacf5\uac04\uc774\uc9c0\ub9cc, \ub3d9\uad74\uc774\ub77c\ub294 \ub9d0\ub9cc\uc73c\ub85c \ub5a0\uc62c\ub9ac\uae30\uc5d0\ub294 \ub108\ubb34 \uc815\uad50\ud558\ub2e4. \uae30\ub465\uacfc \ucc9c\uc7a5, \uc608\ubc30\uc758 \uc7a5\uc18c\uc640 \uc0dd\ud65c\uc758 \ubc29, \ubcbd\ud654\uc640 \uc870\uac01\uc774 \ud568\uaed8 \uc788\ub2e4. \uae38\uac8c \uc774\uc5b4\uc9c4 \uc11d\uad74\ub4e4\uc744 \ud558\ub098\uc758 \uac74\ubb3c\ub85c \ubb36\uae30\ubcf4\ub2e4, \uc2dc\ub300\uc640 \uc4f0\uc784\uc774 \ub2e4\ub978 \uacf5\uac04\ub4e4\uc774 \uacc4\uace1\uc744 \ub530\ub77c \ubaa8\uc778 \uc7a5\uc18c\ub85c \uc77d\uc5b4 \ubcf4\uc790. \ubcf4\ud1b5 \uac74\ubb3c\uc740 \uc7ac\ub8cc\ub97c \uac00\uc838\uc640 \ubcbd\uacfc \uc9c0\ubd95\uc744 \uc138\uc6b4\ub2e4. \uc544\uc794\ud0c0\uc758 \uc11d\uad74\uc5d0\uc11c\ub294 \ubc14\uc704\ub97c \uc81c\uac70\ud558\uba74\uc11c \ub0b4\ubd80 \uacf5\uac04\uc744 \ub9cc\ub4e0\ub2e4. \uae30\ub465\ucc98\ub7fc \ubcf4\uc774\ub294 \ubd80\ubd84\ub3c4 \ub530\ub85c \uac00\uc838\ub2e4 \uc138\uc6b4 \ub3cc\uc774 \uc544\ub2c8\ub77c \uc8fc\ubcc0\uc744 \ud30c\ub0b4\uace0 \ub0a8\uae34 \ubc14\uc704\uc778 \uacbd\uc6b0\uac00 \ub9ce\ub2e4. \uc774 \ucc28\uc774\ub97c \uc0dd\uac01\ud558\uba74 \uc775\uc219\ud55c \uae30\ub465\uacfc \ub4e4\ubcf4\uc758 \ubaa8\uc591\uc774 \uc0c8\ub86d\uac8c \ubcf4\uc778\ub2e4. \uad6c\uc870\ub97c \ub9cc\ub4e4\uc5b4 \ub193\uace0 \uac89\uc744 \uafb8\ubbf8\ub294 \uacfc\uc815\uacfc \uc644\uc804\ud788 \uac19\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc774\ub2e4. \uc5b4\ub5a4 \uacf5\uac04\uacfc \ud615\uc0c1\uc744 \ub0a8\uae38\uc9c0 \uacc4\ud68d\ud558\uba74\uc11c \ubb3c\uc9c8\uc744 \ub35c\uc5b4 \ub0b4\uc57c \ud588\uace0, \uadf8\ub9cc\ud07c \uacf5\uc815\uacfc \uc791\uc5c5\uc758 \uc21c\uc11c\uac00 \uc911\uc694\ud588\uc744 \uac83\uc774\ub2e4. \uc544\uc794\ud0c0\uc5d0\ub294 \uc774\ub978 \uc2dc\uae30\uc758 \uc11d\uad74\uacfc \ub4a4\uc5d0 \ud06c\uac8c \ud655\uc7a5\ub41c \uc2dc\uae30\uc758 \uc11d\uad74\uc774 \uacf5\uc874\ud55c\ub2e4. \ub300\uccb4\ub85c \uae30\uc6d0\uc804 \uc218 \uc138\uae30\uc5d0\uc11c \uae30\uc6d0\ud6c4 \ucd08\uae30\uae4c\uc9c0\uc758 \uc791\uc5c5\uacfc, 5\uc138\uae30 \ubb34\ub835\uc758 \ud65c\ubc1c\ud55c \uc870\uc131\uc774 \uad6c\ubd84\ub41c\ub2e4. \ubaa8\ub4e0 \uacf5\uac04\uc744 \ud55c \uc655\uc774 \ud55c \ubc88\uc5d0 \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \uc774\uc57c\uae30\ub294 \ub9de\uc9c0 \uc54a\ub294\ub2e4. \ubc88\ud638 \uc5ed\uc2dc \uac74\ub9bd \uc5f0\ub300\uc758 \uc21c\uc11c\ub97c \uadf8\ub300\ub85c \ub73b\ud558\uc9c0 \uc54a\ub294\ub2e4. \ucc98\uc74c \uc811\ud560 \ub54c\uc5d0\ub294 \uba87 \ubc88 \uc11d\uad74\uc778\uac00\ub97c \uc678\uc6b0\uae30\ubcf4\ub2e4, \uc608\ubc30\ub97c \uc704\ud55c \uae34 \ud640\uc778\uc9c0 \uc0dd\ud65c\uc744 \uc704\ud55c \uc5ec\ub7ec \ubc29\uc774 \uc788\ub294\uc9c0 \uba3c\uc800 \uad6c\ubd84\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4. \ud615\ud0dc\ub97c \ud1b5\ud574 \uae30\ub2a5\uc744 \uc77d\uae30 \uc2dc\uc791\ud558\uba74 \ubcf5\uc7a1\ud55c \uc9d1\ud569\uc774 \uc870\uae08\uc529 \uc815\ub9ac\ub41c\ub2e4. \ubc14\uc704\ub97c \ud30c\ub0b4 \ub9cc\ub4e0 \uacf5\uac04\uc774\ub77c\ub3c4 \uacf5\uc0ac\uac00 \ub05d\ub09c \ub4a4\uc758 \uc0ac\uc6a9\uae4c\uc9c0 \ubaa8\ub450 \ub3cc\uc5d0 \uacb0\uc815\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc870\uba85\uacfc \uc758\ub840, \uc0ac\ub78c\uc758 \uc774\ub3d9\uc774 \ub0b4\ubd80\ub97c \ucc44\uc6e0\uc744 \uac83\uc774\ub2e4. \ube48 \uc11d\uad74\uc758 \uc0ac\uc9c4\uc744 \ubcfc \ub54c\uc5d0\ub294 \ud604\uc7ac\uc758 \uace0\uc694\ud568\uc744 \uacfc\uac70\uc758 \ud56d\uc0c1 \uac19\uc740 \uc0c1\ud0dc\ub85c \uc0dd\uac01\ud558\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \ucc28\uc774\ud2f0\uc57c\ub85c \ubd80\ub974\ub294 \uc608\ubc30 \uacf5\uac04\uc5d0\ub294 \uae34 \ud640\uacfc \uae30\ub465\uc758 \uc5f4, \uc548\ucabd\uc758 \ud0d1\uc774 \uc5b4\uc6b0\ub7ec\uc9c4\ub2e4. \uae30\ub465\uc740 \uac00\uc6b4\ub370\uc640 \uc591\uc606\uc758 \ud1b5\ub85c\ub97c \uad6c\ubd84\ud558\uba74\uc11c \uc2dc\uc120\uc744 \uc548\uc73c\ub85c \uc774\ub048\ub2e4. \ud0d1 \uc8fc\uc704\ub97c \ub3c4\ub294 \ub3d9\uc120\uae4c\uc9c0 \uc0dd\uac01\ud558\uba74 \uc815\uba74\uc5d0\uc11c\ub9cc \ubcf4\ub294 \uc7a5\uc2dd\ubb3c\uacfc \ub2e4\ub974\ub2e4\ub294 \uc810\uc774 \ubcf4\uc778\ub2e4. \uc55e\uba74\uc758 \ud070 \uc544\uce58\ud615 \uac1c\uad6c\ubd80\uc640 \ub0b4\ubd80\ub85c \ub4e4\uc5b4\uc624\ub294 \ube5b\ub3c4 \uc911\uc694\ud558\ub2e4. \ubc14\uae65\uc758 \ubc1d\uc74c\uc5d0\uc11c \uc5b4\ub450\uc6b4 \uc548\ucabd\uc73c\ub85c \uc774\ub3d9\ud558\ub294 \ub3d9\uc548 \uacf5\uac04\uc758 \uae4a\uc774\uc640 \uc911\uc2ec\uc774 \ub290\uaef4\uc9c4\ub2e4. \uc0ac\uc9c4 \ud55c \uc7a5\uc73c\ub85c\ub294 \ube5b\uc774 \uc2e4\uc81c\ub85c \uc5b4\ub5bb\uac8c \ub2ec\ub77c\uc9c0\ub294\uc9c0 \ubaa8\ub450 \uc54c \uc218 \uc5c6\uc9c0\ub9cc, \ucd9c\uc785\uad6c\uc640 \ud0d1\uc758 \uad00\uacc4\ub97c \ub530\ub77c \uc0c1\uc0c1\ud560 \uc218 \uc788\ub2e4. \ube44\ud558\ub77c\ub85c \ubd80\ub974\ub294 \uc2b9\uc6d0 \uacf5\uac04\uc5d0\ub294 \ud640\uacfc \uc8fc\ubcc0\uc758 \uc791\uc740 \ubc29\ub4e4\uc774 \ub193\uc778\ub2e4. \uc11d\uad74\uc744 \uc804\ubd80 \uc608\ubc30\ub2f9\uc774\ub77c\uace0\ub9cc \uc0dd\uac01\ud558\uba74 \uc774\ub807\uac8c \uc0ac\ub78c\uc774 \uba38\ubb3c\uace0 \uc0dd\ud65c\ud558\ub358 \uad6c\uc870\ub97c \ub193\uce5c\ub2e4. \uc218\ud589\uacfc \ud559\uc2b5, \uacf5\ub3d9\uc0dd\ud65c\uc744 \ub4b7\ubc1b\uce68\ud558\ub294 \uacf5\uac04\uc774 \uc885\uad50 \uac74\ucd95\uc758 \ud070 \ubd80\ubd84\uc774\uc5c8\ub2e4. \ub4a4 \uc2dc\uae30\uc758 \uc77c\ubd80 \uc2b9\uc6d0\uc5d0\ub294 \uc548\ucabd\uc758 \ubd88\uc0c1\uacfc \uc131\uc18c\uac00 \uc911\uc694\ud558\uac8c \uc790\ub9ac\ud55c\ub2e4. \uc0dd\ud65c \uacf5\uac04\uacfc \uc608\ubc30 \uacf5\uac04\uc774 \uc5b8\uc81c\ub098 \uc644\uc804\ud788 \ub5a8\uc5b4\uc838 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc29\ubb38\uc790\ub294 \ubc29\uc758 \uc218\uc640 \ud1b5\ub85c, \uc548\ucabd\uc744 \ud5a5\ud55c \ucd95\uc120\uc744 \ubcf4\uba74\uc11c \uacf5\ub3d9\uccb4\uac00 \uacf5\uac04\uc744 \uc5b4\ub5bb\uac8c \uc870\uc9c1\ud588\ub294\uc9c0 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \ud0d1\uacfc \ubd88\uc0c1\uc744 \uc5b4\ub290 \uc704\uce58\uc5d0 \ub450\uc5c8\ub294\uc9c0 \ube44\uad50\ud558\uba74 \uc2dc\ub300\uc5d0 \ub530\ub978 \ud45c\ud604\uc758 \ucc28\uc774\ub3c4 \uc77d\uc744 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \ucd08\uae30 \ubd88\uad50 \uc138\uacc4 \uc804\uccb4\uc5d0 \ub3d9\uc77c\ud55c \ud615\uc0c1 \uae08\uc9c0 \uaddc\uce59\uc774 \uc788\uc5c8\ub2e4\uace0 \uac04\ub2e8\ud788 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud55c \uc7a5\uc18c\uc5d0\uc11c \ubcf8 \ubcc0\ud654\ub97c \uac70\ub300\ud55c \uc885\uad50 \uc804\uccb4\uc758 \ub2e8\uc77c \ubc95\uce59\uc73c\ub85c \ub113\ud788\uc9c0 \ub9d0\uc544\uc57c \ud55c\ub2e4. \uc608\ubc30 \ud640\uc758 \ub465\uadfc \uc9c0\ubd95\uacfc \ubc18\ubcf5\ub418\ub294 \ubd80\uc7ac\uc5d0\ub294 \ubaa9\uc870 \uac74\ucd95\uc744 \uc5f0\uc0c1\uc2dc\ud0a4\ub294 \ud615\uc2dd\uc774 \ubcf4\uc778\ub2e4. \ub3cc\ub85c \ub9cc\ub4e4\uc5c8\ub2e4\uace0 \ud574\uc11c \ubaa9\uc7ac\ub85c \uc9d3\ub358 \uc138\uacc4\uc640 \ub2e8\uc808\ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc775\uc219\ud55c \uac74\ucd95\uc758 \ubaa8\uc591\uc744 \ubc14\uc704 \uc548\uc5d0 \uc62e\uae30\uba74\uc11c \ub2e4\ub978 \uc7ac\ub8cc\uc5d0\uc11c \uc5bb\uc740 \uacbd\ud5d8\uc744 \uc774\uc5b4 \uac04 \uac83\uc774\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \uc7a5\uc2dd\uc774 \uc2e4\uc81c \uad6c\uc870\uc758 \uc5ed\ud560\uc744 \uadf8\ub300\ub85c \uc218\ud589\ud55c\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uae30\ub2a5\uacfc \ubaa8\uc591\uc744 \uad6c\ubd84\ud574\uc11c \ubcf4\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \uac89\uc73c\ub85c\ub294 \ub4e4\ubcf4\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc \uacf5\uac04\uc758 \uae30\uc5b5\uc744 \ud45c\ud604\ud558\ub294 \uc7a5\uce58\uc77c \uc218\ub3c4 \uc788\ub2e4. \uc774 \uc810\uc774 \uc11d\uad74 \uac74\ucd95\uc758 \ub3c5\ud2b9\ud55c \uc7ac\ubbf8\ub97c \ub9cc\ub4e0\ub2e4. \uc544\uc794\ud0c0\uc758 \ubcbd\ud654\ub294 \ubd88\uad50 \uc774\uc57c\uae30\uc640 \uc804\uc0dd\ub2f4\uc744 \ud1b5\ud574 \ub113\uc740 \uc138\uacc4\ub97c \ud3bc\uce5c\ub2e4. \uc655\uacfc \uc2dc\uc885, \uc218\ud589\uc790\uc640 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \ubab8, \uc637\uacfc \uc7a5\uc2e0\uad6c, \uc2dc\uc120\uacfc \uc190\uc9d3\uc774 \uc0ac\uac74\uc744 \uc804\ub2ec\ud55c\ub2e4. \ud55c \uc778\ubb3c\uc744 \ud06c\uac8c \ub5bc\uc5b4 \ub0b4 \ubcf4\ub294 \uac83\uacfc \uc5f0\uc18d\ub41c \uc11c\uc0ac\uc758 \uc77c\ubd80\ub85c \uc77d\ub294 \uac83\uc740 \ub2e4\ub978 \uacbd\ud5d8\uc774\ub2e4. \uc6b0\ub9ac\uac00 \uc624\ub298 \ubcf4\ub294 \ubcbd\ud654\ub294 \ub0a8\uc544 \uc788\ub294 \ubd80\ubd84\uc744 \ud1b5\ud574 \uc774\ud574\ud558\ub294 \uadf8\ub9bc\uc774\ub2e4. \uc190\uc0c1\uacfc \ubcf4\uc874\uc758 \uc5ed\uc0ac\uac00 \uc788\uc73c\ubbc0\ub85c \ube48 \ubd80\ubd84\uc758 \ub0b4\uc6a9\uc744 \ub9c8\uc74c\ub300\ub85c \ucc44\uc6cc \ud655\uc815\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ub610\ud55c \ubcbd\ud654\uc758 \ubaa8\ub4e0 \uc0dd\ud65c \uc7a5\uba74\uc744 \ub2f9\uc2dc \uc778\ub3c4 \uc804\uccb4\uc758 \uc77c\uc0c1\uc744 \uadf8\ub300\ub85c \uae30\ub85d\ud55c \uc790\ub8cc\ub85c \uc77c\ubc18\ud654\ud558\ub294 \uc77c\ub3c4 \uc870\uc2ec\ud574\uc57c \ud55c\ub2e4. \uc7a5\uc778\uc758 \uc791\uc5c5\uc5d0\ub294 \ub3cc\uc744 \ub35c\uc5b4 \ub0b4\ub294 \uae30\uc220\uacfc \ud45c\uba74\uc744 \ub2e4\ub4ec\uace0 \uadf8\ub9bc\uc744 \ub0a8\uae30\ub294 \uae30\uc220\uc774 \ud568\uaed8 \ud544\uc694\ud588\ub2e4. \uc870\uac01\uacfc \ud68c\ud654, \uac74\ucd95\uc744 \uc624\ub298\uc758 \ubd84\uc57c \uc774\ub984\uc73c\ub85c \ub098\ub204\uc5b4\ub3c4 \ud604\uc7a5\uc5d0\uc11c\ub294 \uc11c\ub85c \uc5f0\uacb0\ub418\uc5c8\ub2e4. \uc544\uc794\ud0c0\ub97c \ubcfc \ub54c \ud55c \uc608\uc220 \uc7a5\ub974\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b4 \uc774\uc720\ub2e4. 19\uc138\uae30 \uc601\uad6d\uc778\ub4e4\uc758 \ubc29\ubb38\uacfc \uc870\uc0ac\ub85c \uc544\uc794\ud0c0\uac00 \uc11c\uad6c \ucd9c\ud310\ubb3c\uc5d0 \ub110\ub9ac \uc54c\ub824\uc84c\ub2e4. \uadf8\ub7ec\ub098 \uadf8\uac83\uc744 \uace7 \uc0ac\ub78c\uc774 \uc804\ud600 \ubab0\ub790\ub358 \uc7a5\uc18c\uac00 \ucc98\uc74c \uc138\uc0c1\uc5d0 \ub098\ud0c0\ub09c \uc77c\ub85c \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc9c0\uc5ed\uc758 \uc874\uc7ac\uc640 \uc9c0\uc2dd, \uc624\ub79c \uac74\ucd95\uc758 \uc5ed\uc0ac\ub294 \uc5ec\ud589\uc790\uc758 \ub3c4\ucc29\ubcf4\ub2e4 \uc55e\uc120\ub2e4. \uc5ec\uae30\uc5d0\ub294 \uc2e4\uc81c 19\ubc88 \uc11d\uad74 \uc815\uba74\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc5ed\uc0ac \ub3c4\ud310\uc744 \uc2e4\uc5c8\ub2e4. \ud604\uc7ac \ud604\uc7a5 \uc0c1\ud0dc\ub098 \ubcbd\ud654\uc758 \uc6d0\ub798 \uc0c9\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc774\ubbf8\uc9c0\ub294 \uc544\ub2c8\ub2e4. \ud070 \uc785\uad6c\uc640 \uc870\uac01, \uc548\ucabd\uc744 \ud5a5\ud55c \uae38\uc744 \ud568\uaed8 \ubcf4\uba74 \uc544\uc794\ud0c0\uac00 \ubc14\uc704 \uc18d\uc5d0 \ub9cc\ub4e0 \uac83\uc740 \ub2e8\uc21c\ud55c \ubc29\uc774 \uc544\ub2c8\ub77c \ube5b\uacfc \uc6c0\uc9c1\uc784, \uc774\uc57c\uae30\uc758 \uc9c8\uc11c\uc600\uc74c\uc744 \uc54c \uc218 \uc788\ub2e4."}, {"id": "alhambra-water-and-stories", "title": "\uc54c\ub78c\ube0c\ub77c \u2014 \ubb3c\uc18c\ub9ac\uc640 \uc624\ub798\ub41c \uc774\uc57c\uae30\uac00 \ub0a8\uc740 \uad81\uc804", "summary": "\uadf8\ub77c\ub098\ub2e4\uc758 \uad81\uc815 \uacf5\uac04\uacfc \uc6cc\uc2f1\ud134 \uc5b4\ube59\uc774 \uc62e\uae34 \uc804\uc124\uc744 \uad6c\ubd84\ud574 \uc77d\uae30\uc744 \uc774\uc57c\uae30\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uac74\ucd95", "categories": ["arts"], "url": "stories/alhambra-water-and-stories/index.html", "image": "../media/alhambra-water-and-stories.jpg", "alt": "\uc0ac\uc790 \ubd84\uc218\uc640 \ud68c\ub791 \uc55e \uc778\ubb3c\uc744 \ub2f4\uc740 1910\ub144\ud310 \uc54c\ub78c\ube0c\ub77c \uc218\ub85d \uc5ed\uc0ac \uc774\ubbf8\uc9c0", "text": "\uc54c\ub78c\ube0c\ub77c \u2014 \ubb3c\uc18c\ub9ac\uc640 \uc624\ub798\ub41c \uc774\uc57c\uae30\uac00 \ub0a8\uc740 \uad81\uc804 \uadf8\ub77c\ub098\ub2e4\uc758 \uad81\uc815 \uacf5\uac04\uacfc \uc6cc\uc2f1\ud134 \uc5b4\ube59\uc774 \uc62e\uae34 \uc804\uc124\uc744 \uad6c\ubd84\ud574 \uc77d\uae30 \uadf8\ub77c\ub098\ub2e4\uc758 \uad81\uc815 \uacf5\uac04\uacfc \uc6cc\uc2f1\ud134 \uc5b4\ube59\uc774 \uc62e\uae34 \uc804\uc124\uc744 \uad6c\ubd84\ud574 \uc77d\uae30\uc744 \uc774\uc57c\uae30\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uac74\ucd95 \ubb38\ud654\uc640 \uc608\uc220 \uc2a4\ud398\uc778 \uadf8\ub77c\ub098\ub2e4\uc758 \uc54c\ub78c\ube0c\ub77c\ub294 \uac70\ub300\ud55c \uc678\ubcbd\ub9cc\uc73c\ub85c \uae30\uc5b5\ub418\ub294 \uad81\uc804\uc774 \uc544\ub2c8\ub2e4. \uc548\uc73c\ub85c \ub4e4\uc5b4\uac00\uba74 \uc791\uc740 \uae30\ub465\uacfc \uc815\uad50\ud55c \ud45c\uba74, \uc911\uc815\uacfc \ubb3c\uc774 \uc2dc\uc120\uc744 \ubd99\ub4e0\ub2e4. \uba40\ub9ac\uc11c \ubcf4\ub358 \uc131\ucc44\uc758 \uc778\uc0c1\uacfc \uc548\ucabd\uc5d0\uc11c \uacbd\ud5d8\ud558\ub294 \uc12c\uc138\ud568 \uc0ac\uc774\uc5d0 \ub73b\ubc16\uc758 \ucc28\uc774\uac00 \uc788\ub2e4. \uc774\uacf3\uc740 \uc774\uc2ac\ub78c \uc655\uc870\uc758 \uad81\uc804\uc774\ub77c\ub294 \uc5ed\uc0ac\uc640 \uadf8 \ub4a4\ub97c \uc774\uc740 \uc5ec\ub7ec \uc2dc\ub300\uc758 \uae30\uc5b5\uc744 \ud488\uace0 \uc788\ub2e4. \ub610\ud55c \uc5ec\ud589\uc790\uac00 \ub4e3\uace0 \uc62e\uae34 \uc804\uc124\uc774 \uc7a5\uc18c\uc758 \uc774\ubbf8\uc9c0\uc5d0 \ub354\ud574\uc84c\ub2e4. \uac74\ucd95\uacfc \uc774\uc57c\uae30\ub97c \ud568\uaed8 \uc77d\ub418, \uc804\uc124\uc744 \uc2e4\uc81c \uc0ac\uac74\uacfc \uad6c\ubcc4\ud574 \ubcf4\ub294 \uac83\uc774 \uc54c\ub78c\ube0c\ub77c\ub97c \uc990\uae30\ub294 \uc88b\uc740 \ucd9c\ubc1c\uc810\uc774\ub2e4. \uc54c\ub78c\ube0c\ub77c\uc758 \uc911\uc2ec\uc5d0\ub294 \uadf8\ub77c\ub098\ub2e4\ub97c \ub2e4\uc2a4\ub9b0 \ub098\uc2a4\ub974 \uc655\uc870\uc758 \uad81\uc815 \uacf5\uac04\uc774 \uc788\ub2e4. \uc624\ub298\ub0a0 \uc2a4\ud398\uc778\uc774\ub77c\ub294 \uad6d\uac00\uc758 \uc9c0\ub3c4 \uc548\uc5d0 \uc788\uc9c0\ub9cc, \uadf8 \ud615\uc131\uc758 \ud575\uc2ec\uc5d0\ub294 \uc774\ubca0\ub9ac\uc544\ubc18\ub3c4\uc5d0 \uc624\ub7ab\ub3d9\uc548 \uc774\uc5b4\uc9c4 \uc774\uc2ac\ub78c \ubb38\ud654\uac00 \ub193\uc778\ub2e4. \ud604\uc7ac\uc758 \uad6d\uac00 \uc774\ub984\ub9cc\uc73c\ub85c \uacfc\uac70 \uc0ac\ub78c\ub4e4\uc758 \uc815\uce58\uc640 \uc2e0\uc559\uc744 \ubaa8\ub450 \uc124\uba85\ud560 \uc218 \uc5c6\ub294 \uc774\uc720\ub2e4. \uad81\uc804\uc740 \uc544\ub984\ub2e4\uc6b4 \uac70\ucc98\uc778 \ub3d9\uc2dc\uc5d0 \ud1b5\uce58\uc758 \uc790\ub9ac\uc600\ub2e4. \ub204\uac00 \uc5b4\ub514\uae4c\uc9c0 \ub4e4\uc5b4\uac08 \uc218 \uc788\ub294\uc9c0, \uc5b4\ub5a4 \uae38\ub85c \uc0ac\ub78c\uc744 \ub9cc\ub098\uac8c \ud558\ub294\uc9c0\ub3c4 \uacf5\uac04\uc758 \uc758\ubbf8\uc5d0 \ud3ec\ud568\ub41c\ub2e4. \uc7a5\uc2dd\ub9cc \ub530\ub85c \ub5bc\uc5b4 \uac10\uc0c1\ud558\uba74 \ud3b8\uc548\ud55c \uc815\uc6d0\uacfc \uad8c\ub825\uc774 \ud589\uc0ac\ub418\ub358 \uad81\uc815\uc774\ub77c\ub294 \ub450 \uc5bc\uad74 \uac00\uc6b4\ub370 \ud558\ub098\ub97c \ub193\uce58\uae30 \uc27d\ub2e4. \uba40\ub9ac\uc11c \ubcf4\ub294 \uc54c\ub78c\ube0c\ub77c\uc5d0\ub294 \uc9c0\ud615\uc744 \ub530\ub77c \uc120 \ubcbd\uacfc \ud0d1\uc758 \uc778\uc0c1\uc774 \uac15\ud558\ub2e4. \ud558\uc9c0\ub9cc \uc548\ucabd\uc758 \uc911\uc815\uc73c\ub85c \ub4e4\uc5b4\uac00\uba74 \uc2dc\uc120\uc740 \ud070 \ubc29\uc5b4 \uc2dc\uc124\uc5d0\uc11c \uac00\ub290\ub2e4\ub780 \uae30\ub465\uacfc \ubb34\ub2ac\ub85c \uc774\ub3d9\ud55c\ub2e4. \uc811\uadfc\ud558\ub294 \ubc29\ud5a5\uc5d0 \ub530\ub77c \uac19\uc740 \uc7a5\uc18c\uc758 \uc131\uaca9\uc774 \ub2ec\ub77c\uc9c0\ub294 \uac83\uc774\ub2e4. \uc774 \ucc28\uc774\ub294 \uac74\ucd95\uc744 \ud55c \uc7a5\uc758 \ub300\ud45c \uc0ac\uc9c4\uc73c\ub85c\ub9cc \uae30\uc5b5\ud558\uae30 \uc5b4\ub835\uac8c \ub9cc\ub4e0\ub2e4. \ubc16\uc5d0\uc11c \uc548\uc73c\ub85c, \ubc1d\uc740 \uc911\uc815\uc5d0\uc11c \uadf8\ub298\uc9c4 \ubc29\uc73c\ub85c \uc6c0\uc9c1\uc774\ub294 \uacfc\uc815\uc774 \uc911\uc694\ud558\ub2e4. \uad81\uc804\uc740 \ud55c\ub208\uc5d0 \ub2e4 \ubcf4\uc774\ub294 \uc870\uac01\uc0c1\uc774 \uc544\ub2c8\ub77c \ubab8\uc744 \uc6c0\uc9c1\uc774\uba70 \uc21c\uc11c\ub300\ub85c \ub9cc\ub098\ub294 \uacf5\uac04\uc774\ub77c\ub294 \uc0ac\uc2e4\uc744 \uc54c\ub78c\ube0c\ub77c\uac00 \uc798 \ubcf4\uc5ec \uc900\ub2e4. \uc0ac\uc790\uc758 \uc911\uc815\uc774\ub77c\ub294 \uc774\ub984\uc740 \uc911\uc2ec \ubd84\uc218\ub97c \ub5a0\ubc1b\uce58\ub294 \uc0ac\uc790\ub4e4\uc5d0\uc11c \uc628\ub2e4. \ub3d9\ubb3c \uc870\uac01\uc744 \uba3c\uc800 \ubcf4\ub354\ub77c\ub3c4 \uc8fc\ubcc0\uc758 \uc218\ub85c\uc640 \uae30\ub465\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \uac00\uc6b4\ub370\uc758 \ud55c \ubb3c\uac74\ub9cc\uc73c\ub85c \uacf5\uac04\uc774 \uc644\uc131\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb3c\uacfc \ubc14\ub2e5, \ub458\ub808\uc758 \ud68c\ub791\uc774 \ud558\ub098\uc758 \uad00\uacc4\ub97c \ub9cc\ub4e0\ub2e4. \uae30\ub465\uc740 \ubc29\uc744 \ubc1b\uce58\ub294 \uad6c\uc870\uc774\uba74\uc11c \uc2dc\uc57c\ub97c \ub098\ub204\ub294 \uc120\uc774\ub2e4. \uc77c\uc815\ud55c \uac04\uaca9\uc73c\ub85c \ubc18\ubcf5\ub418\uba74 \uac77\ub294 \ubc29\ud5a5\uc5d0 \ub530\ub77c \uacb9\uce58\uace0 \ud480\ub9b0\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uc7a5\uc2dd\uc758 \ubc00\ub3c4\uac00 \uba3c\uc800 \ubcf4\uc774\uc9c0\ub9cc, \uc2e4\uc81c\ub85c\ub294 \ube48 \uacf3\uacfc \uac00\ub824\uc9c0\ub294 \uacf3\uc758 \ubcc0\ud654\uac00 \uc911\uc694\ud558\ub2e4. \ubd84\uc218\ub294 \uadf8\ub7f0 \uacf5\uac04\uc758 \uc911\uc2ec\uc744 \ub208\uacfc \uadc0\ub85c \ub290\ub07c\uac8c \ud55c\ub2e4. \uace0\uc694\ud55c \uc218\uba74\uc740 \uac74\ubb3c\uc758 \ubaa8\uc2b5\uc744 \ube44\ucd94\uace0, \ud750\ub974\ub294 \ubb3c\uc740 \uc18c\ub9ac\ub97c \ub0b8\ub2e4. \ubb3c\uc744 \uc0ac\uc6a9\ud558\ub294 \ubc29\uc2dd\uc5d0 \ub530\ub77c \uac19\uc740 \uc911\uc815\uc5d0\uc11c\ub3c4 \ub2e4\ub978 \uac10\uac01\uc774 \uc0dd\uae34\ub2e4. \uad81\uc804\uc758 \uc544\ub984\ub2e4\uc6c0\uc744 \ub208\uc73c\ub85c \ubcf4\ub294 \ubb34\ub2ac\uc5d0\ub9cc \ud55c\uc815\ud558\uba74 \uc774 \uc18c\ub9ac\uc640 \uc6c0\uc9c1\uc784\uc744 \ub193\uce5c\ub2e4. \ubb3c\uc740 \ub193\uc778 \ubb3c\uac74\uc774\uba74\uc11c \uacc4\uc18d \ubcc0\ud654\ud558\ub294 \uc694\uc18c\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \uc7a5\uc2dd\uc744 \ud558\ub098\uc758 \uace0\uc815\ub41c \uc0c1\uc9d5\uc73c\ub85c \ud574\ub3c5\ud558\ub824 \uc560\uc4f8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uba3c\uc800 \uc5b4\ub514\uc5d0 \ubb3c\uc774 \ub193\uc600\uace0 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5bb\uac8c \uadf8 \uacc1\uc744 \uc9c0\ub098\ub294\uc9c0 \ubcf4\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \ucda9\ubd84\ud558\ub2e4. \uc0ac\uc6a9\uacfc \uac10\uac01\uc744 \ud568\uaed8 \uc0dd\uac01\ud558\uba74 \uc815\uc6d0\uc740 \uc655\uc2e4\uc758 \ucde8\ud5a5\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ub3d9\uc2dc\uc5d0 \uc77c\uc0c1\uc744 \uad6c\uc131\ud55c \ud658\uacbd\uc73c\ub85c \uc77d\ud78c\ub2e4. \ubbf8\uad6d \uc791\uac00 \uc6cc\uc2f1\ud134 \uc5b4\ube59\uc740 1829\ub144 \uc2a4\ud398\uc778\uc744 \uc5ec\ud589\ud558\uace0 \uc54c\ub78c\ube0c\ub77c\uc5d0 \uba38\ubb38 \uacbd\ud5d8\uc744 \uae00\ub85c \ub0a8\uacbc\ub2e4. \uadf8\uc758 \u300e\uc54c\ub78c\ube0c\ub77c\u300f\uc5d0\ub294 \uad00\ucc30\uacfc \uc5ec\ud589\uc758 \uae30\uc5b5, \ud604\uc9c0\uc5d0\uc11c \ub4e4\uc740 \uc774\uc57c\uae30\uc640 \uc804\uc124\uc774 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4. \uc77d\ub294 \uc0ac\ub78c\uc740 \uc624\ub798\ub41c \uac74\ubb3c \uc0ac\uc774\uc5d0 \ub2e4\uc2dc \uc0ac\ub78c\ub4e4\uc758 \ubaa9\uc18c\ub9ac\ub97c \ucc44\uc6cc \ub123\uac8c \ub41c\ub2e4. \uc774 \ucc45\uc758 \ub9e4\ub825\uc740 \uacf5\uac04\uc744 \ubaa9\ub85d\ucc98\ub7fc \uc124\uba85\ud558\ub294 \ub370 \uadf8\uce58\uc9c0 \uc54a\ub294\ub2e4\ub294 \uac83\uc774\ub2e4. \uad81\uc804\uc5d0\uc11c \uc0ac\ub294 \uc0ac\ub78c\uacfc \uc9c0\ub098\uac04 \uc655\uc870\uc5d0 \ub300\ud55c \uc0c1\uc0c1\uc774 \uac74\ucd95\uc5d0 \uacb9\uce5c\ub2e4. \uadf8\ub7ec\ub098 \uc5b4\ube59\uc740 \uc911\uc138 \uad81\uc815\uc758 \ud604\uc7a5 \uae30\ub85d\uc790\uac00 \uc544\ub2c8\ub2e4. \uadf8\uc758 \uc2dc\ub300\uc640 \ucde8\ud5a5\uc744 \uac70\uccd0 \uc7ac\uad6c\uc131\ub41c \uc54c\ub78c\ube0c\ub77c\ub77c\ub294 \uc810\ub3c4 \ud568\uaed8 \uae30\uc5b5\ud574\uc57c \ud55c\ub2e4. \uc54c\ub78c\ube0c\ub77c\ub97c \ub458\ub7ec\uc2fc \uc774\uc57c\uae30\uc5d0\ub294 \uc0ac\ub791\uacfc \ubcf4\ubb3c, \ubab0\ub77d\ud55c \uc655\uc2e4\uacfc \uae30\uc774\ud55c \uc0ac\uac74\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \uc804\uc124\uc740 \uc7a5\uc18c\ub97c \uc624\ub798 \uae30\uc5b5\ud558\uac8c \ud558\uc9c0\ub9cc, \uc7ac\ubbf8\uc788\uac8c \uc804\ud574\uc9c4\ub2e4\ub294 \uc774\uc720\ub85c \uc5ed\uc0ac\uc801 \uc0ac\uc2e4\uc774 \ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc2e4\uc81c\ub85c \ub0a8\uc740 \uac74\ucd95\uacfc \ubb38\ud5cc\uc758 \uae30\ub85d, \ud6c4\ub300\uc5d0 \ub367\ubd99\uc740 \uc774\uc57c\uae30\ub294 \uac01\uac01 \ub2e4\ub978 \uc885\ub958\uc758 \uadfc\uac70\ub2e4. \uc774 \uad6c\ubcc4\uc740 \uc5ec\ud589\uc758 \uc990\uac70\uc6c0\uc744 \uc904\uc774\uae30\ubcf4\ub2e4 \ub113\ud600 \uc900\ub2e4. \ubb34\uc2a8 \uc77c\uc774 \uc2e4\uc81c\ub85c \uc788\uc5c8\ub294\uc9c0 \ubb3b\ub294 \ub3c5\uc11c\uc640 \uc0ac\ub78c\ub4e4\uc774 \uc65c \uadf8\ub7f0 \uc774\uc57c\uae30\ub97c \ub9cc\ub4e4\uc5c8\ub294\uc9c0 \ubb3b\ub294 \ub3c5\uc11c\ub294 \uc11c\ub85c \ub2e4\ub978 \uc7ac\ubbf8\uac00 \uc788\ub2e4. \uad81\uc804\uc740 \ud1b5\uce58\uc790\uc758 \uacfc\uac70\ub97c \ub2f4\ub294 \ub3d9\uc2dc\uc5d0, \uadf8 \uacfc\uac70\ub97c \uc0c1\uc0c1\ud55c \ud6c4\ub300 \uc0ac\ub78c\ub4e4\uc758 \ub9c8\uc74c\ub3c4 \ub2f4\ub294\ub2e4. \uad81\uc804\uc774 \ub9cc\ub4e4\uc5b4\uc9c4 \uc2dc\ub300\uac00 \ub05d\ub09c \ub4a4\uc5d0\ub3c4 \uc54c\ub78c\ube0c\ub77c\uc758 \uc2dc\uac04\uc740 \uacc4\uc18d \ud758\ub800\ub2e4. \ub2e4\ub978 \ud1b5\uce58\uc790\uc640 \uac70\uc8fc\uc790, \uc5ec\ud589\uc790\uc640 \ub3c5\uc790\uac00 \uc774\uacf3\uc744 \uc0c8\ub86d\uac8c \ubcf4\uc558\ub2e4. \uadf8\ub798\uc11c \uc624\ub298\uc758 \uad00\ub78c\uac1d\uc774 \ub9cc\ub098\ub294 \ubaa8\uc2b5\uc740 \ub2e8 \ud55c \uc2dc\ub300\uc758 \uc0dd\ud65c\uc774 \uadf8\ub300\ub85c \uc815\uc9c0\ud55c \uc7a5\uba74\uc774\ub77c\uace0 \ud560 \uc218 \uc5c6\ub2e4. \uc624\ub798\ub41c \uc5ec\ud589 \ucc45\uc758 \uadf8\ub9bc\uc744 \uc9c0\uae08\uc758 \uc0ac\uc9c4\uacfc \ub098\ub780\ud788 \ubcf4\ub294 \uac83\ub3c4 \ud765\ubbf8\ub86d\ub2e4. \uc5b4\ub5a4 \ubd80\ubd84\uc744 \ud06c\uac8c \ubcf4\uc5ec \uc8fc\uace0 \uc5b4\ub5a4 \uc778\ubb3c\uc744 \ubc30\uce58\ud588\ub294\uc9c0\uc5d0 \ub530\ub77c \uac19\uc740 \uad81\uc804\uc758 \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc774\ubbf8\uc9c0 \uc5ed\uc2dc \uc7a5\uc18c\ub97c \ud22c\uba85\ud558\uac8c \uc62e\uae34 \ucc3d\uc774 \uc544\ub2c8\ub77c \ud2b9\uc815 \uc2dc\ub300\uac00 \uadf8\uacf3\uc744 \ubc14\ub77c\ubcf8 \uae30\ub85d\uc774\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc0ac\uc790\uc640 \uae30\ub465, \ubb3c\uc744 \ubcf4\uace0, \ub2e4\uc74c\uc5d0\ub294 \uadf8\uacf3\uc744 \uc0ac\uc6a9\ud55c \uc0ac\ub78c\uacfc \uc774\uc57c\uae30\ub97c \uc62e\uae34 \uc791\uac00\ub97c \ub5a0\uc62c\ub824 \ubcf4\uc790. \uac74\ucd95\uc758 \uc138\ubd80\ub97c \ubcf4\ub294 \uc990\uac70\uc6c0\uacfc \uc804\ud574\uc9c4 \ub9d0\uc758 \uc131\uaca9\uc744 \uac00\ub9ac\ub294 \uc7ac\ubbf8\uac00 \ud568\uaed8 \uc0dd\uae34\ub2e4. \uc54c\ub78c\ube0c\ub77c\ub294 \uc544\ub984\ub2e4\uc6b4 \uad81\uc804\uc778 \ub3d9\uc2dc\uc5d0 \uc5ec\ub7ec \uc2dc\ub300\uac00 \uac19\uc740 \uc7a5\uc18c\ub97c \uc5b4\ub5bb\uac8c \uae30\uc5b5\ud588\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \uacf5\uac04\uc774\ub2e4."}, {"id": "alice-language-and-rules", "title": "\uc774\uc0c1\ud55c \ub098\ub77c\uc758 \uc568\ub9ac\uc2a4 \u2014 \ub9d0\uc774 \ud1b5\ud558\uc9c0 \uc54a\ub294 \uc138\uacc4\uc5d0\uc11c \ub098\ub97c \ucc3e\uae30", "summary": "\uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \ub530\ub77c \ub9d0\uacfc \uaddc\uce59\uc774 \ud754\ub4e4\ub9ac\ub294 \ubaa8\ud5d8\uc758 \uc7ac\ubbf8\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/alice-language-and-rules/index.html", "image": "../media/alice-language-and-rules.png", "alt": "\uc568\ub9ac\uc2a4\uac00 \uc232\uc18d \uac08\ub9bc\uae38\uc5d0\uc11c \ub098\ubb34 \uc704\uc758 \uccb4\uc154 \uace0\uc591\uc774\ub97c \ubc14\ub77c\ubcf4\ub294 \uc0c1\uc0c1 \uc0bd\ud654.", "text": "\uc774\uc0c1\ud55c \ub098\ub77c\uc758 \uc568\ub9ac\uc2a4 \u2014 \ub9d0\uc774 \ud1b5\ud558\uc9c0 \uc54a\ub294 \uc138\uacc4\uc5d0\uc11c \ub098\ub97c \ucc3e\uae30 \ud1a0\ub07c\uad74\uacfc \ub2e4\uacfc\ud68c, \uc774\uc0c1\ud55c \uc7ac\ud310\uc744 \uc9c0\ub098\uac00\ub294 \uc18c\ub140 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \ub530\ub77c \ub9d0\uacfc \uaddc\uce59\uc774 \ud754\ub4e4\ub9ac\ub294 \ubaa8\ud5d8\uc758 \uc7ac\ubbf8\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \uae09\ud558\uac8c \ub2ec\ub9ac\ub294 \ud1a0\ub07c\uac00 \ud68c\uc911\uc2dc\uacc4\ub97c \uaebc\ub0b8\ub2e4. \uc2e0\uae30\ud574\uc11c \ub530\ub77c\uac04 \uc18c\ub140\ub294 \ud1a0\ub07c\uad74 \uc544\ub798\ub85c \ub5a8\uc5b4\uc9c0\uace0, \ubab8\uc758 \ud06c\uae30\uc640 \ub300\ud654\uc758 \uaddc\uce59\uc774 \uc790\uafb8 \ub2ec\ub77c\uc9c0\ub294 \uc138\uacc4\uc5d0 \ub4e4\uc5b4\uac04\ub2e4. \ub8e8\uc774\uc2a4 \uce90\ub7f4\uc758 \u300e\uc774\uc0c1\ud55c \ub098\ub77c\uc758 \uc568\ub9ac\uc2a4\u300f\ub2e4. \uc775\uc219\ud55c \uc81c\ubaa9\uc774\uc9c0\ub9cc \uc904\uac70\ub9ac\ub97c \ucc28\ub840\ub85c \uc77d\uc5b4 \ubcf4\uba74 \ub2e8\uc21c\ud788 \uae30\ubb18\ud55c \uc0dd\ubb3c\uc744 \ub9cc\ub098\ub294 \uc774\uc57c\uae30\ubcf4\ub2e4 \ud6e8\uc52c \uc7a5\ub09c\uc2a4\ub7fd\ub2e4. \uc568\ub9ac\uc2a4\ub294 \ubc30\uc6b4 \ub9d0\uacfc \uc608\uc808\uc744 \uac00\uc9c0\uace0 \ub0af\uc120 \uc138\uacc4\ub97c \uc774\ud574\ud558\ub824 \ud55c\ub2e4. \uadf8\ub7ec\ub098 \uadf8\uacf3\uc758 \uc778\ubb3c\ub4e4\uc740 \uac19\uc740 \ub2e8\uc5b4\ub97c \uc4f0\uba74\uc11c\ub3c4 \uac19\uc740 \ub73b\uc744 \ub098\ub204\uc9c0 \uc54a\ub294\ub2e4. \uc544\ub798\uc5d0\ub294 \uc8fc\uc694 \uc7a5\uba74\uacfc \uacb0\ub9d0\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4. \ud1a0\ub07c\uad74\uc744 \ub0b4\ub824\uac04 \uc568\ub9ac\uc2a4\ub294 \uc791\uc740 \ubb38 \ub108\uba38\uc758 \uc544\ub984\ub2e4\uc6b4 \uc815\uc6d0\uc5d0 \uac00\uace0 \uc2f6\uc5b4 \ud55c\ub2e4. \ud558\uc9c0\ub9cc \ubb38\uacfc \ubab8\uc758 \ud06c\uae30\uac00 \ub9de\uc9c0 \uc54a\ub294\ub2e4. \ub9c8\uc2dc\uace0 \uba39\uc73c\uba70 \uc791\uc544\uc9c0\uac70\ub098 \ucee4\uc9c0\ub294 \ub3d9\uc548 \uc5f4\uc1e0\ub97c \ub193\uce58\uace0 \uc790\uae30 \ub208\ubb3c\uc5d0 \ud729\uc4f8\ub9ac\uae30\ub3c4 \ud55c\ub2e4. \uc6d0\ud558\ub294 \uacf3\uc5d0 \ub4e4\uc5b4\uac00\ub294 \uc77c\uc774 \uc0dd\uac01\ucc98\ub7fc \ub2e8\uc21c\ud558\uc9c0 \uc54a\ub2e4. \uc774 \ubcc0\ud654\ub294 \uc7ac\ubbf8\uc788\ub294 \ub9c8\ubc95\uc774\uba74\uc11c \uc790\uc2e0\uc744 \uc54c\uc544\ubcf4\ub294 \uac10\uac01\uc744 \ud754\ub4e0\ub2e4. \ubab8\uc774 \uc790\uafb8 \ubc14\ub00c\ub2c8 \ud3c9\uc18c\uc5d0 \ub2f9\uc5f0\ud588\ub358 \uc77c\uc744 \ud560 \uc218 \uc5c6\uace0, \uc678\uc6e0\ub358 \ub9d0\ub3c4 \uc774\uc0c1\ud558\uac8c \ub098\uc628\ub2e4. \ub3c5\uc790\ub294 \uc568\ub9ac\uc2a4\uc640 \ud568\uaed8 \uc775\uc219\ud55c \uae30\uc900\uc744 \uc7a0\uc2dc \uc783\ub294\ub2e4. \ubb34\uc5c7\uc744 \ud558\ub824\ub294\uc9c0\ub9cc\ud07c \uc9c0\uae08 \uc5b4\ub5a4 \uc0c1\ud0dc\uc778\uc9c0\ub3c4 \uc911\uc694\ud574\uc9c4\ub2e4. \uc560\ubc8c\ub808\ub97c \ub9cc\ub0ac\uc744 \ub54c \uc568\ub9ac\uc2a4\ub294 \uc790\uc2e0\uc774 \ub204\uad6c\uc778\uc9c0 \uc124\uba85\ud558\uae30 \uc5b4\ub835\ub2e4. \uc624\ub298\ub9cc \ud574\ub3c4 \ubab8\uc774 \uc5ec\ub7ec \ubc88 \ub2ec\ub77c\uc84c\uae30 \ub54c\ubb38\uc774\ub2e4. \uc0c1\ub300\uc758 \uc9c8\ubb38\uc740 \uac04\ub2e8\ud558\uc9c0\ub9cc \ub300\ub2f5\ud560 \uc870\uac74\uc740 \uac04\ub2e8\ud558\uc9c0 \uc54a\ub2e4. \uc5b4\uc81c \uc54c\uace0 \uc788\ub358 \uc790\uae30 \ubaa8\uc2b5\uc774 \uc624\ub298\uc758 \uc0c1\ud669\uc744 \ucda9\ubd84\ud788 \uc124\uba85\ud558\uc9c0 \ubabb\ud55c\ub2e4. \uc774\ub97c \ud55c \uac00\uc9c0 \ucca0\ud559 \uc774\ub860\uc758 \uc815\ub2f5\uc73c\ub85c \ud574\uc11d\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5b4\ub9b0\uc544\uc774\uc5d0\uac8c\ub3c4 \uc5b4\ub978\uc5d0\uac8c\ub3c4 \ubcc0\ud654\ud558\ub294 \uc790\uc2e0\uc744 \ub9d0\ud558\uae30 \uc5b4\ub824\uc6b4 \uc21c\uac04\uc740 \uc788\ub2e4. \uc791\ud488\uc740 \uadf8 \ubb38\uc81c\ub97c \ubb34\uac70\uc6b4 \uac15\uc758 \ub300\uc2e0 \ud06c\uae30\uc640 \ub9d0\ud22c, \uc5c9\ub6b1\ud55c \ubb38\ub2f5\uc73c\ub85c \ubcf4\uc5ec \uc900\ub2e4. \uc6c3\uc74c \uc18d\uc5d0\uc11c \uc790\uae30\uc18c\uac1c\uac00 \uc7a0\uae50 \ub0af\uc124\uc5b4\uc9c4\ub2e4. \uac08\ub9bc\uae38\uc5d0\uc11c \ub9cc\ub09c \uccb4\uc154 \uace0\uc591\uc774\uc640\uc758 \ub300\ud654\uc5d0\uc11c\ub294 \uc5b4\ub514\ub85c \uac00\uace0 \uc2f6\uc740\uc9c0\uac00 \uc911\uc694\ud574\uc9c4\ub2e4. \uae38\uc744 \ubb3b\ub294 \uc0ac\ub78c\uc740 \uc788\uc9c0\ub9cc \ubaa9\uc801\uc9c0\uac00 \ubd84\uba85\ud558\uc9c0 \uc54a\uc73c\uba74 \uc5b4\ub290 \uae38\uc774 \ub9de\ub294\uc9c0\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \ud754\ud788 \uc774 \uc7a5\uba74\ub9cc \ub5bc\uc5b4 \uaca9\uc5b8\ucc98\ub7fc \uc77d\uc9c0\ub9cc, \uc791\ud488 \uc18d\uc5d0\uc11c\ub294 \uace0\uc591\uc774\uc758 \uc5c9\ub6b1\ud568\uacfc \uc568\ub9ac\uc2a4\uc758 \ub2f9\ud669\uc774 \ud568\uaed8 \uc788\ub2e4. \uc18c\uc124\uc758 \ud55c \ubb38\uc7a5\uc744 \uc778\uc0dd\uc758 \ubaa8\ub4e0 \uc120\ud0dd\uc5d0 \uc801\uc6a9\ud560 \uba85\ub839\uc73c\ub85c \ub9cc\ub4e4 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \ubb34\uc5c7\uc744 \uc6d0\ud558\ub290\ub0d0\ub294 \uc9c8\ubb38 \uc5c6\uc774 \ud6a8\uc728\uc801\uc778 \uae38\ub9cc \ucc3e\uc744 \ub54c \uc0dd\uae30\ub294 \uc774\uc0c1\ud568\uc744 \ub290\uaef4 \ubcfc \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc0bd\ud654\ub294 \uc774 \ub9cc\ub0a8\uc744 \uc0c8\ub85c \uc0c1\uc0c1\ud55c \uc7a5\uba74\uc774\ub2e4. \uc6d0\uc791\uc758 \uc61b \ub3c4\ud310\uc774\ub098 \uc601\ud654\uc758 \uace0\uc591\uc774\ub97c \ubcf5\uc81c\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ubaa8\uc790 \uc7a5\uc218\uc640 \uc0bc\uc6d4 \ud1a0\ub07c, \uaca8\uc6b8\uc7a0\uc950\uac00 \uc788\ub294 \ub2e4\uacfc\ud68c\ub294 \uc190\ub2d8\uc744 \ubc18\uae30\ub294 \ud3b8\uc548\ud55c \uc790\ub9ac\uac00 \uc544\ub2c8\ub2e4. \uc790\ub9ac\ub97c \uc62e\uae30\uace0 \ub9d0\uc7a5\ub09c\uc744 \ud558\uba70 \uc9c8\ubb38\uacfc \ub300\ub2f5\uc774 \uc5c7\uac08\ub9b0\ub2e4. \uc568\ub9ac\uc2a4\uac00 \uc608\uc758\ub97c \uc9c0\ud0a4\uba70 \uc774\ud574\ud558\ub824 \ud560\uc218\ub85d \ub300\ud654\ub294 \ub2e4\ub978 \ubc29\ud5a5\uc73c\ub85c \ub2ec\uc544\ub09c\ub2e4. \ub2e8\uc21c\ud788 \ubaa8\ub450\uac00 \uc774\uc0c1\ud55c \ub9d0\uc744 \ud574\uc11c \uc6c3\uae34 \uac83\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uc6b0\ub9ac\ub294 \uc9c8\ubb38\uc744 \ubc1b\uc73c\uba74 \ub2f5\ud560 \uac83\uc774\ub77c\ub294 \uae30\ub300, \ub9d0\uc758 \uc21c\uc11c\uc640 \ub73b\uc774 \uc5b4\ub290 \uc815\ub3c4 \uacf5\uc720\ub420 \uac83\uc774\ub77c\ub294 \ubbff\uc74c\uc744 \uac00\uc9c0\uace0 \uc788\ub2e4. \uadf8 \uc57d\uc18d\uc774 \uacc4\uc18d \uc5b4\uae0b\ub0a0 \ub54c \uc775\uc219\ud55c \ucc28 \ud55c \uc794\uc758 \uc790\ub9ac\ub3c4 \ub0af\uc120 \uc138\uacc4\uac00 \ub41c\ub2e4. \uc5ec\uc655\uc758 \uacbd\uae30\uc5d0\uc11c\ub294 \ud64d\ud559\uacfc \uace0\uc2b4\ub3c4\uce58\uac00 \ub3c4\uad6c\uac00 \ub418\uace0, \uc0ac\ub78c\ub4e4\uc758 \ud0dc\ub3c4\ub3c4 \uc548\uc815\uc801\uc774\uc9c0 \uc54a\ub2e4. \ubb3c\uac74\ucc98\ub7fc \ub2e4\ub8e8\ub824\ub294 \ub300\uc0c1\uc774 \uc0b4\uc544 \uc6c0\uc9c1\uc774\ub2c8 \uacbd\uae30\uc758 \uaddc\uce59\uc744 \uc9c0\ud0a4\uae30 \uc5b4\ub835\ub2e4. \uc5ec\uc655\uc740 \uc790\uc8fc \uc704\ud611\uc801\uc778 \uba85\ub839\uc744 \ub0b4\ub9ac\uc9c0\ub9cc \uadf8 \ubaa9\uc18c\ub9ac\uac00 \ud569\ub9ac\uc801\uc778 \uc9c8\uc11c\ub97c \ubcf4\uc7a5\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc568\ub9ac\uc2a4\ub294 \uc815\ud574\uc9c4 \uaddc\uce59\uc744 \uc798 \ub530\ub974\ub294 \uac83\ub9cc\uc73c\ub85c \ubb38\uc81c\ub97c \ud574\uacb0\ud560 \uc218 \uc5c6\ub294 \uc790\ub9ac\uc5d0 \ub193\uc778\ub2e4. \uaddc\uce59\uc744 \ub9d0\ud558\ub294 \uc0ac\ub78c\uc774 \uc790\uae30 \uae30\ubd84\uc5d0 \ub530\ub77c \uadf8\uac83\uc744 \ubc14\uafb8\uae30 \ub54c\ubb38\uc774\ub2e4. \uad8c\uc704\uac00 \ud06c\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ub9d0\uc774 \uc774\uce58\uc5d0 \ub9de\ub294\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub97c \uc218 \uc788\ub2e4\ub294 \uac10\uc0c1\uc774 \uac00\ub2a5\ud574\uc9c4\ub2e4. \ud6c4\ubc18\uc5d0\ub294 \ud30c\uc774\ub97c \ud6d4\uce5c \uc0ac\uac74\uc744 \ub450\uace0 \uc7ac\ud310\uc774 \uc5f4\ub9b0\ub2e4. \uc99d\uac70\uc640 \uc99d\uc5b8\uc744 \ub530\uc838\uc57c \ud560 \uc790\ub9ac\uc778\ub370 \uc5c9\ub6b1\ud55c \ub9d0\uacfc \uc21c\uc11c\uac00 \ub07c\uc5b4\ub4e4\uace0, \ud310\uacb0\uacfc \ucc98\ubc8c\uc758 \uad00\uacc4\ub9c8\uc800 \ud754\ub4e4\ub9b0\ub2e4. \uaca9\uc2dd\uc744 \uac16\ucd98 \uc7a5\uc18c\ub77c\uace0 \ud574\uc11c \ud310\ub2e8\uc774 \uc81c\ub300\ub85c \uc774\ub8e8\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc568\ub9ac\uc2a4\ub294 \uc774\uacf3\uc5d0\uc11c\ub3c4 \uacc4\uc18d \ub2f9\ud669\ud558\uae30\ub9cc \ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubab8\uc774 \ucee4\uc9c0\ub294 \ubcc0\ud654\uc640 \ud568\uaed8 \uc0c1\ub300\uc758 \ub9d0\uc744 \uc804\ubcf4\ub2e4 \ub35c \ub450\ub824\uc6cc\ud558\uba70 \ubc18\uc751\ud55c\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ub0af\uc120 \uc138\uacc4\uc5d0 \ub9de\ucd94\ub824 \uc560\uc37c\ub358 \uc18c\ub140\uac00, \uc774\uc81c \uadf8 \uc138\uacc4\uc758 \uc774\uc0c1\ud568\uc744 \uc790\uae30 \ub9d0\ub85c \uc9c0\uc801\ud560 \uc218 \uc788\uac8c \ub41c\ub2e4. \ub9c8\uc9c0\ub9c9\uc5d0 \uce74\ub4dc\ub4e4\uc774 \ub0a0\uc544\uc624\ub974\uace0 \uc568\ub9ac\uc2a4\ub294 \uc7a0\uc5d0\uc11c \uae68\uc5b4\ub09c\ub2e4. \ubaa8\ud5d8\uc740 \uafc8\uc758 \uc2dc\uac04\uc73c\ub85c \ub3cc\uc544\uc628\ub2e4. \uadf8\ub807\ub2e4\uace0 \uafc8\uc774\uc5c8\uc73c\ub2c8 \ubaa8\ub4e0 \uc7a5\uba74\uc774 \ubb34\uc758\ubbf8\ud574\uc84c\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub0af\uc120 \ub9d0\uacfc \uaddc\uce59\uc744 \ud1b5\uacfc\ud558\uba70 \ub290\uaf08\ub358 \ud63c\ub780\uacfc \uc6c3\uc74c\uc740 \ub3c5\uc790\uc5d0\uac8c \ub0a8\uc544 \uc788\ub2e4. \ub05d\uc5d0\uc11c\ub294 \uc5b8\ub2c8\uac00 \uc568\ub9ac\uc2a4\uc758 \uafc8\uacfc \uc55e\uc73c\ub85c\uc758 \uc2dc\uac04\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc7a5\uba74\ub3c4 \uc774\uc5b4\uc9c4\ub2e4. \uc774\uc0c1\ud55c \uc138\uacc4\uac00 \ub2eb\ud788\uace0 \uc77c\uc0c1\uc73c\ub85c \ub3cc\uc544\uc640\ub3c4 \uc774\uc57c\uae30\ub97c \ub4e3\uace0 \uc0c1\uc0c1\ud558\ub294 \ub2a5\ub825\uc740 \uacc4\uc18d\ub41c\ub2e4. \uadf8\ub798\uc11c \uacb0\ub9d0\uc740 \ud37c\uc990\uc758 \ud574\ub2f5 \ud558\ub098\ub97c \uc8fc\uae30\ubcf4\ub2e4 \uafc8\uc744 \uc774\uc57c\uae30\ub85c \uac04\uc9c1\ud558\ub294 \uc790\ub9ac\ub97c \ub0a8\uae34\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc5b4\ub5a4 \uc778\ubb3c\uc744 \uc5b4\ub5a4 \uc21c\uc11c\ub85c \ub9cc\ub098\ub294\uc9c0 \ud3b8\ud558\uac8c \uc77d\uc5b4\ub3c4 \uc88b\ub2e4. \ub2e4\uc74c\uc5d0\ub294 \uc568\ub9ac\uc2a4\uac00 \uc4f4 \ub9d0\uc774 \uc0c1\ub300\uc5d0\uac8c \uc5b4\ub5bb\uac8c \ubc1b\uc544\ub4e4\uc5ec\uc9c0\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \ub204\uac00 \uc9c8\ubb38\uc744 \ud53c\ud558\uace0 \ub204\uac00 \uc790\uae30 \ub73b\ub300\ub85c \ub2e8\uc5b4\ub97c \uc4f0\ub294\uc9c0 \ubcf4\uba74 \uae30\ubb18\ud55c \ub300\ud654\uac00 \uc870\uae08 \ub354 \uc815\uad50\ud558\uac8c \ub4e4\ub9b0\ub2e4. \u300e\uc774\uc0c1\ud55c \ub098\ub77c\uc758 \uc568\ub9ac\uc2a4\u300f\ub294 \ub0af\uc120 \uc138\uacc4\uc5d0 \ub300\ud55c \uc0c1\uc0c1\uacfc \uc6b0\ub9ac\uac00 \ub2f9\uc5f0\ud558\uac8c \uc4f0\ub294 \uc5b8\uc5b4\uc5d0 \ub300\ud55c \uc7a5\ub09c\uc744 \ud568\uaed8 \uac00\uc9c4\ub2e4. \ubaa8\ub4e0 \uc0c1\uc9d5\uc5d0 \ud558\ub098\uc529 \uc815\ub2f5\uc744 \ubd99\uc774\uc9c0 \uc54a\uc544\ub3c4 \uc990\uae38 \uc218 \uc788\ub2e4. \ud1a0\ub07c\uad74\uc5d0\uc11c \ub098\uc640 \ud3c9\uc18c\uc758 \ub300\ud654\ub97c \ub5a0\uc62c\ub9b4 \ub54c, \ub9d0\uc774 \ud1b5\ud55c\ub2e4\ub294 \uc77c\uc774 \uc5bc\ub9c8\ub098 \ub9ce\uc740 \uc57d\uc18d \uc704\uc5d0 \ub193\uc5ec \uc788\ub294\uc9c0 \uc870\uae08 \uc0c8\ub86d\uac8c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4."}, {"id": "amaterasu-cave-laughter-and-mirror", "title": "\uc544\ub9c8\ud14c\ub77c\uc2a4 \u2014 \ub3d9\uad74 \ubc16\uc5d0\uc11c\ub294 \uc65c \uc6c3\uc74c\uc774 \ud130\uc84c\uc744\uae4c", "summary": "\uc544\ub9c8\ud14c\ub77c\uc2a4\uc758 \uc740\ub454\uacfc \uc2e0\ub4e4\uc758 \uc900\ube44, \uc6b0\uc988\uba54\uc758 \ucda4\uacfc \ud638\uae30\uc2ec\uc744 \ub370\uc774\ube44\uc2a4\uc758 \uc7ac\ud654\ubcf8\uc744 \ub530\ub77c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc2e0\ud654\uc640 \ubbfc\uc18d", "categories": ["arts"], "url": "stories/amaterasu-cave-laughter-and-mirror/index.html", "image": "../media/amaterasu-cave-laughter-and-mirror.png", "alt": "\ub3d9\uad74\uc5d0\uc11c \ubc14\uae65\uc758 \uac70\uc6b8\uacfc \uc6b0\uc988\uba54\uc758 \ucda4\uc744 \ub0b4\ub2e4\ubcf4\ub294 \uc544\ub9c8\ud14c\ub77c\uc2a4\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uc544\ub9c8\ud14c\ub77c\uc2a4 \u2014 \ub3d9\uad74 \ubc16\uc5d0\uc11c\ub294 \uc65c \uc6c3\uc74c\uc774 \ud130\uc84c\uc744\uae4c \ud0dc\uc591\uc758 \uc5ec\uc2e0\uc744 \ub2e4\uc2dc \ub098\uc624\uac8c \ud55c \ucda4\uacfc \uac70\uc6b8 \uc544\ub9c8\ud14c\ub77c\uc2a4\uc758 \uc740\ub454\uacfc \uc2e0\ub4e4\uc758 \uc900\ube44, \uc6b0\uc988\uba54\uc758 \ucda4\uacfc \ud638\uae30\uc2ec\uc744 \ub370\uc774\ube44\uc2a4\uc758 \uc7ac\ud654\ubcf8\uc744 \ub530\ub77c \uc77d\uc2b5\ub2c8\ub2e4. \uc2e0\ud654\uc640 \ubbfc\uc18d \ubb38\ud654\uc640 \uc608\uc220 \uc138\uc0c1\uc5d0\uc11c \ube5b\uc774 \uc0ac\ub77c\uc84c\ub2e4. \ud0dc\uc591\uc758 \uc5ec\uc2e0\uc774 \ub3d9\uad74\uc5d0 \ub4e4\uc5b4\uac00 \ub098\uc624\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc774\ub2e4. \uadf8\ub7f0\ub370 \ub3d9\uad74 \ubc16\uc5d0\uc11c\ub294 \uc2e0\ub4e4\uc774 \uc18c\ub9ac \ub0b4\uc5b4 \uc6c3\uace0 \uc788\ub2e4. \ubaa8\ub450 \uc5b4\ub460\uc5d0 \uc7a0\uaca8 \uc2ac\ud37c\ud560 \uc904 \uc54c\uc558\ub358 \uc5ec\uc2e0\uc740 \ubb34\uc2a8 \uc77c\uc778\uc9c0 \uad81\uae08\ud574\uc9c4\ub2e4. \uc544\ub9c8\ud14c\ub77c\uc2a4\uac00 \ub3d9\uad74\uc5d0\uc11c \ub098\uc624\ub294 \uc774\uc57c\uae30\ub294 \uc77c\ubcf8 \uc2e0\ud654\uc758 \uc775\uc219\ud55c \uc7a5\uba74\uc774\ub2e4. \uc774 \uae00\uc740 F. \ud574\ub4e4\ub7f0\ub4dc \ub370\uc774\ube44\uc2a4\uc758 \u300e\uc77c\ubcf8 \uc2e0\ud654\uc640 \uc804\uc124\u300f\uc5d0 \uc2e4\ub9b0 \uc7ac\ud654\ubcf8\uc744 \ub530\ub77c \uc77d\ub294\ub2e4. \ub2e4\ub978 \ud310\ubcf8\uc758 \uc138\ubd80\ub97c \ubaa8\ub450 \ud55c \uc7a5\uba74\uc73c\ub85c \ud569\uce58\uc9c0\ub294 \uc54a\uc558\ub2e4. \uc544\ub9c8\ud14c\ub77c\uc2a4\uc758 \ub3d9\uc0dd \uc2a4\uc0ac\ub178\uc624\ub294 \uac70\uce60\uac8c \ud589\ub3d9\ud558\uba70 \ub204\ub098\uac00 \uac00\uafb8\ub358 \uc9c8\uc11c\ub97c \uc5b4\uc9c0\ub7fd\ud78c\ub2e4. \ub17c\uc758 \uacbd\uacc4\ub97c \ub9dd\uac00\ub728\ub9ac\uace0 \uc77c\ud558\ub294 \uacf5\uac04\uae4c\uc9c0 \uce68\ubc94\ud55c\ub2e4. \uc5ec\uc2e0\uc740 \ub3d9\uc0dd\uacfc \uad00\uacc4\ub97c \ub9fa\uc73c\ub824 \ud558\uc9c0\ub9cc \uc0ac\ud0dc\ub294 \ub098\uc544\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uc774 \uc774\uc57c\uae30\uc5d0\uc11c \ub17c\uacfc \ubca0 \uc9dc\ub294 \uacf5\uac04\uc740 \ub2e8\uc21c\ud55c \ubc30\uacbd\uc774 \uc544\ub2c8\ub2e4. \uba39\uace0 \uc785\ub294 \uc0b6\uacfc \uc2e0\ub4e4\uc758 \uc9c8\uc11c\ub97c \ub5a0\ubc1b\uce58\ub294 \uc77c\uc774\ub2e4. \uc2a4\uc0ac\ub178\uc624\uc758 \ud589\ub3d9\uc740 \uc2ec\uc220\uad82\uc740 \uc7a5\ub09c\ucc98\ub7fc \uc2dc\uc791\ud574 \uadf8 \uc0dd\ud65c\uc774 \uacc4\uc18d\ub420 \uc870\uac74\uc744 \uc704\ud611\ud55c\ub2e4. \ubca0\ub97c \uc9dc\ub358 \uacf5\uac04\uc5d0\uc11c \ub610 \ud55c \ubc88 \ud070 \uc18c\ub3d9\uc774 \ubc8c\uc5b4\uc9c4 \ub4a4 \uc544\ub9c8\ud14c\ub77c\uc2a4\ub294 \ub3d9\uad74\ub85c \ub4e4\uc5b4\uac04\ub2e4. \uc774 \ud310\ubcf8\uc5d0\uc11c\ub294 \uc5ec\uc2e0\uc774 \ub180\ub77c \ub2e4\uce58\ub294 \uc0ac\uac74\uc73c\ub85c \uc124\uba85\ub41c\ub2e4. \ubd84\ub178\uc640 \uc0c1\ucc98 \ub05d\uc5d0 \uc790\uae30 \ube5b\uc744 \uac70\ub450\ub294 \uac83\uc774\ub2e4. \uadf8 \ub4a4 \uc138\uc0c1\uc740 \uc5b4\ub450\uc6cc\uc9c0\uace0 \ubc24\uacfc \ub0ae\uc758 \ubc88\uac08\uc74c\ub3c4 \uc0ac\ub77c\uc9c4\ub2e4. \ud55c \uc778\ubb3c\uc774 \uc77c\uc744 \uba48\ucd98 \uac83\uc774 \ubaa8\ub450\uc758 \uc704\uae30\uac00 \ub41c\ub2e4. \uc8fc\ubcc0 \uc2e0\ub4e4\uc5d0\uac8c\ub3c4 \ubb38\uc81c\ub294 \uc5ec\uc2e0\uc758 \ub9c8\uc74c\ub9cc \ub2ec\ub798\ub294 \uc77c\uc774 \uc544\ub2c8\ub77c \ube5b\uc774 \ub3cc\uc544\uc62c \uae38\uc744 \ucc3e\ub294 \uc77c\uc774\uc5c8\ub2e4. \ub9ce\uc740 \uc2e0\uc774 \ubaa8\uc5ec \ubc29\ubc95\uc744 \uc758\ub17c\ud55c\ub2e4. \uc0dd\uac01\uc744 \ubaa8\uc73c\ub294 \uc2e0\uc774 \ub098\uc11c\uace0 \uc5ec\ub7ec \uc900\ube44\uac00 \uc774\ub8e8\uc5b4\uc9c4\ub2e4. \uc0c8\ub97c \ubaa8\uc73c\uace0 \ub3c4\uad6c\ub97c \ub9cc\ub4e4\uba70 \uac70\uc6b8\uacfc \uc7a5\uc2e0\uad6c, \uc18c\ub9ac\ub97c \ub0bc \ubb3c\uac74\uc744 \ub9c8\ub828\ud55c\ub2e4. \ud574\uacb0\uc740 \ud55c \uc2e0\uc758 \uc8fc\uba39\uc5d0\uc11c \ub098\uc624\uc9c0 \uc54a\ub294\ub2e4. \uac01\uac01\uc744 \ub530\ub85c \ubcf4\uba74 \ub3d9\uad74\ubb38\uacfc \ubb34\uc2a8 \uc0c1\uad00\uc778\uc9c0 \uc54c\uae30 \uc5b4\ub835\ub2e4. \uadf8\ub7ec\ub098 \ubaa9\uc801\uc740 \ubc16\uc758 \uc138\uacc4\uac00 \uc5b4\ub5a4 \ubaa8\uc2b5\uc778\uc9c0 \uc5ec\uc2e0\uc774 \uad00\uc2ec\uc744 \uac16\uac8c \ud558\ub294 \ub370 \uc788\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc548\ucabd\uc758 \uc0ac\ub78c\uc744 \uc6c0\uc9c1\uc774\ub824\uba74 \ubc14\uae65\uc5d0\uc11c \ub290\ub084 \uc774\uc720\ub97c \ub9cc\ub4e4\uc5b4\uc57c \ud588\ub2e4. \uadf8 \uc900\ube44\uc5d0\ub294 \uc5ec\ub7ec \uc190\uc774 \ud544\uc694\ud588\ub2e4. \uc5ec\uc2e0 \ud55c \uba85\uc758 \uadc0\ud658\uc744 \uc704\ud574 \uc11c\ub85c \ub2e4\ub978 \uc7ac\uc8fc\uac00 \ubaa8\uc774\ub294 \uacfc\uc815\uc774\ub2e4. \uc2e0\ub4e4\uc740 \ub098\ubb34\uc5d0 \uc7a5\uc2e0\uad6c\uc640 \uac70\uc6b8\uc744 \uac74\ub2e4. \ube5b\uc744 \ubc1b\uc544 \ubc18\uc9dd\uc77c \ubb3c\uac74\ub4e4\uc774 \uc544\uc9c1 \uc5b4\ub450\uc6b4 \uacf5\uac04\uc5d0 \ub193\uc778\ub2e4. \uac70\uc6b8\uc740 \ub204\uad70\uac00\ub97c \ube44\ucd94\uba74\uc11c\ub3c4 \uadf8 \uc815\uccb4\ub97c \uc7a0\uae50 \ub0af\uc124\uac8c \ub9cc\ub4dc\ub294 \ubb3c\uac74\uc774\ub2e4. \ub2e4\ub9cc \uc9c0\uae08 \uc77d\ub294 \uc7ac\ud654\ubcf8\uc740 \ubaa8\ub4e0 \uc7a5\uba74\uc744 \uae38\uac8c \ud480\uc9c0 \uc54a\ub294\ub2e4. \ub2e4\ub978 \uc804\uc2b9\uc5d0\uc11c \uc775\uc219\ud55c \uc138\ubd80\ub97c \uc5ec\uae30\uc5d0\ub3c4 \uc788\uc5c8\ub2e4\uace0 \ub367\ubd99\uc774\uae30\ubcf4\ub2e4 \uac70\uc6b8\uc744 \ube44\ub86f\ud55c \uc900\ube44\uac00 \uc774\ub8e8\uc5b4\uc84c\ub2e4\ub294 \ubc94\uc704\uc5d0\uc11c \uc77d\ub294\ub2e4. \uc5ec\ub7ec \ud310\ubcf8\uc744 \ub098\ub204\uc5b4 \ubcf4\uba74 \uac19\uc740 \ubb3c\uac74\uc758 \uc5ed\ud560\ub3c4 \ub354 \uad81\uae08\ud574\uc9c4\ub2e4. \uc6b0\uc988\uba54\ub294 \ud1b5\uc744 \ub4a4\uc9d1\uc5b4 \uadf8 \uc704\uc5d0\uc11c \ucda4\ucd98\ub2e4. \ub2e4\ub978 \uc2e0\ub4e4\uc740 \uadf8 \ubaa8\uc2b5\uc744 \ubcf4\uba70 \ud06c\uac8c \uc6c3\ub294\ub2e4. \ubb34\uac70\uc6b4 \uc704\uae30\uc758 \ud55c\uac00\uc6b4\ub370\uc11c \uc758\uc678\uc758 \uc18c\ub780\uc774 \uc2dc\uc791\ub41c \uac83\uc774\ub2e4. \ub3d9\uad74 \uc548\ucabd\uc5d0\uc11c\ub3c4 \ubabb \ub4e4\uc740 \ucc99\ud558\uae30 \uc5b4\ub824\uc6b4 \uc18c\ub9ac\ub2e4. \uadf8 \ucda4\uc744 \uc624\ub298\ub0a0\uc758 \ud2b9\uc815 \uacf5\uc5f0\ucc98\ub7fc \uc815\ubc00\ud558\uac8c \ubcf5\uc6d0\ud560 \uc790\ub8cc\ub85c \uc4f0\ub824\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774 \uc774\uc57c\uae30\uc5d0\uc11c \uc911\uc694\ud55c \uac83\uc740 \uc6c0\uc9c1\uc784\uacfc \uc6c3\uc74c\uc774 \uacf5\ub3d9\uc758 \uad00\uc2ec\uc744 \ubc14\uafb8\ub294 \ubc29\uc2dd\uc774\ub2e4. \ub2eb\ud78c \ubb38\uc744 \ud5a5\ud55c \uba85\ub839\uacfc\ub294 \ub2e4\ub978 \uc885\ub958\uc758 \ud798\uc774 \uc0dd\uae34\ub2e4. \uc544\ub9c8\ud14c\ub77c\uc2a4\ub294 \ubc16\uc758 \uc6c3\uc74c\uc744 \ub4e3\uace0 \ubb34\uc2a8 \uc77c\uc778\uc9c0 \uc54c\uace0 \uc2f6\uc5b4\uc9c4\ub2e4. \uc790\uc2e0\uc774 \uc5c6\uc5b4\uc11c \ubaa8\ub450 \uace4\ub780\ud558\ub9ac\ub77c \uc0dd\uac01\ud560 \uc218 \uc788\ub294 \uc0c1\ud669\uc778\ub370 \ubc14\uae65\uc5d0\uc11c\ub294 \uc990\uac70\uc6b4 \uc77c\uc774 \ubc8c\uc5b4\uc9c0\ub294 \ub4ef\ud558\ub2e4. \uc608\uc0c1\uacfc \uc18c\ub9ac\uac00 \uc5b4\uae0b\ub098\uc790 \ub3d9\uad74 \ubc16\uc744 \ub0b4\ub2e4\ubcf8\ub2e4. \uadf8 \uc21c\uac04 \ube5b\uc774 \ub2e4\uc2dc \uc138\uc0c1\uc73c\ub85c \ud37c\uc9c4\ub2e4. \ub370\uc774\ube44\uc2a4\uc758 \uc7ac\ud654\ub294 \uc774 \uc7a5\uba74\uc744 \ube44\uad50\uc801 \ube60\ub974\uac8c \ub9c8\ubb34\ub9ac\ud55c\ub2e4. \ubc27\uc904\uacfc \ub2e4\ub978 \uc2e0\uc758 \ub3d9\uc791\uae4c\uc9c0 \ub367\ubd99\uc778 \uc0c1\uc138\ud55c \uacb0\ub9d0\uc774 \uc775\uc219\ud574\ub3c4 \uc5ec\uae30\uc11c\ub294 \uc774 \ud310\ubcf8\uc774 \ub9d0\ud55c \ud750\ub984\uc5d0 \uba38\ubb38\ub2e4. \uc2e0\ub4e4\uc774 \uc6c3\uc5c8\ub2e4\uace0 \uc2a4\uc0ac\ub178\uc624\uc758 \ud589\ub3d9\uc774 \uc544\ubb34 \uc77c\ub3c4 \uc544\ub2c8\uac8c \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774\uc57c\uae30\uc5d0\uc11c\ub294 \uadf8\uc5d0\uac8c \ubc8c\uacfc \ucd94\ubc29\uc774 \ub530\ub978\ub2e4. \uc5ec\uc2e0\uc774 \ub3cc\uc544\uc628\ub2e4\ub294 \uacb0\uacfc\uc640 \uac08\ub4f1\uc744 \uc77c\uc73c\ud0a8 \ud589\ub3d9\uc758 \ucc45\uc784\uc740 \ud568\uaed8 \ub0a8\ub294\ub2e4. \uadf8\ub7ec\ubbc0\ub85c \ub204\uad70\uac00 \uc0c1\ucc98\ubc1b\uc544 \ubb3c\ub7ec\ub098\uba74 \uc6c3\uaca8\uc11c \ub098\uc624\uac8c \ud558\uba74 \ub41c\ub2e4\ub294 \uc0dd\ud65c\uc758 \ucc98\ubc29\uc73c\ub85c \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc2e0\ud654\ub294 \uadf9\uc801\uc778 \uc7a5\uba74\uacfc \uc0c1\uc9d5\uc73c\ub85c \uad00\uacc4\uc758 \uc704\uae30\ub97c \uc774\uc57c\uae30\ud55c\ub2e4. \ud604\uc2e4\uc758 \ubaa8\ub4e0 \ub9c8\uc74c\uc774 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc6c0\uc9c1\uc778\ub2e4\ub294 \uc124\uba85\uc740 \uc544\ub2c8\ub2e4. \uc544\ub9c8\ud14c\ub77c\uc2a4\uc640 \uad00\ub828\ub41c \uc2e0\ud654\ub294 \uc9c0\uae08\ub3c4 \uc774\uc5b4\uc9c0\ub294 \uc885\uad50\uc640 \ubb38\ud654\uc758 \ub9e5\ub77d\uc744 \uac16\ub294\ub2e4. \uc61b \uc601\ubb38 \ucc45\uc5d0 \uc2e4\ub838\ub2e4\uace0 \uc0ac\ub77c\uc9c4 \uc0ac\ub78c\ub4e4\uc758 \uae30\uc774\ud55c \ubbff\uc74c\uc73c\ub85c\ub9cc \ub2e4\ub8f0 \uc218\ub294 \uc5c6\ub2e4. \uc218\uc9d1\ud558\uace0 \ub2e4\uc2dc \uc4f4 \uc0ac\ub78c\uc758 \uc2dc\uc120\ub3c4 \uc790\ub8cc\uc5d0 \ub4e4\uc5b4 \uc788\ub2e4. \uc774 \uae00\uc740 \ud574\ub2f9 \ucc45\uc758 \uc0ac\uac74\uc744 \uc548\ub0b4\ud558\ub294 \uc77d\uc744\uac70\ub9ac\ub2e4. \ubaa8\ub4e0 \uc77c\ubcf8\uc778\uc774 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc774\ud574\ud55c\ub2e4\uac70\ub098 \ud55c \uac00\uc9c0 \uc758\ub840\uc758 \uc815\ud655\ud55c \uae30\uc6d0\uc744 \uc774 \uc7a5\uba74\ub9cc\uc73c\ub85c \uc99d\uba85\ud55c\ub2e4\uace0 \ub9d0\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc774\uc57c\uae30\uc758 \uc7ac\ubbf8\uc640 \uc804\uc2b9\uc744 \ub2e4\ub8e8\ub294 \uc2e0\uc911\ud568\uc740 \ud568\uaed8 \uac08 \uc218 \uc788\ub2e4. \ub3d9\uad74\uc5d0 \ub4e4\uc5b4\uac00\ub294 \uc7a5\uba74\uc5d0\uc11c\ub294 \ud558\ub098\uc758 \ube5b\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \ub3cc\uc544\uc624\ub294 \uc7a5\uba74\uc5d0\uc11c\ub294 \uc5ec\ub7ec \uc2e0\uc758 \uc900\ube44\uc640 \ucda4, \uc18c\ub9ac\uac00 \ud568\uaed8 \uc791\ub3d9\ud55c\ub2e4. \ud63c\uc790 \ube5b\ub098\ub294 \uc874\uc7ac\ub97c \ub2e4\uc2dc \ubd88\ub7ec\ub0b4\ub294 \uc77c\uc774 \uc5ec\ub7ff\uc758 \ud611\ub825\uc774\uc5c8\ub2e4\ub294 \uc810\uc774 \ud765\ubbf8\ub86d\ub2e4. \uc544\ub9c8\ud14c\ub77c\uc2a4\uc758 \uc774\uc57c\uae30\ub97c \ub5a0\uc62c\ub9b4 \ub54c \uac70\uc6b8\ubfd0 \uc544\ub2c8\ub77c \uc6c3\uc74c\uc18c\ub9ac\ub3c4 \uae30\uc5b5\ud574 \ubcf4\uc790. \ud798\uc73c\ub85c \ubb38\uc744 \ubd80\uc218\ub294 \uc7a5\uba74 \ub300\uc2e0 \uc548\ucabd\uc5d0\uc11c \ubc14\uae65\uc744 \uad81\uae08\ud574\ud558\ub294 \uc21c\uac04\uc774 \uc788\ub2e4. \uc138\uc0c1\uc73c\ub85c \ub3cc\uc544\uc624\ub294 \uae38\uc774 \ub73b\ubc16\uc758 \uad00\uc2ec\uc5d0\uc11c \uc2dc\uc791\ub41c\ub2e4\ub294 \uc0c1\uc0c1\uc774 \uc624\ub798 \ub0a8\ub294\ub2e4."}, {"id": "anansi-wisdom-pot-and-son", "title": "\uc544\ub09c\uc2dc \u2014 \uc9c0\ud61c\ub97c \ud56d\uc544\ub9ac\uc5d0 \uc228\uae30\ub824\ub358 \ub0a0", "summary": "\uc544\ubc84\uc9c0 \uc544\ub09c\uc2dc\uac00 \uc9c0\ud61c\ub97c \ub3c5\uc810\ud558\ub824\ub2e4 \uc544\ub4e4\uc758 \uc870\uc5b8\uc5d0 \ub9c9\ud788\ub294 \uc774\uc57c\uae30\ub97c \ud310\ud2f0 \uc9c0\uc5ed \uc7ac\ud654\ubcf8\uc5d0 \ub530\ub77c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc2e0\ud654\uc640 \ubbfc\uc18d", "categories": ["arts"], "url": "stories/anansi-wisdom-pot-and-son/index.html", "image": "../media/anansi-wisdom-pot-and-son.png", "alt": "\uac00\uc2b4 \uc55e\uc73c\ub85c \ud56d\uc544\ub9ac\ub97c \ub9e8 \uc544\ub09c\uc2dc\uac00 \ub098\ubb34\ub97c \uc624\ub974\uace0 \uc544\ub4e4\uc774 \ub4f1\uc744 \uac00\ub9ac\ud0a4\ub294 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uc544\ub09c\uc2dc \u2014 \uc9c0\ud61c\ub97c \ud56d\uc544\ub9ac\uc5d0 \uc228\uae30\ub824\ub358 \ub0a0 \uc544\ub4e4\uc758 \ud55c\ub9c8\ub514\uac00 \uc138\uc0c1\uc758 \uc9c0\ud61c\ub97c \ubc14\uae65\uc73c\ub85c \uaebc\ub0b4\ub2e4 \uc544\ubc84\uc9c0 \uc544\ub09c\uc2dc\uac00 \uc9c0\ud61c\ub97c \ub3c5\uc810\ud558\ub824\ub2e4 \uc544\ub4e4\uc758 \uc870\uc5b8\uc5d0 \ub9c9\ud788\ub294 \uc774\uc57c\uae30\ub97c \ud310\ud2f0 \uc9c0\uc5ed \uc7ac\ud654\ubcf8\uc5d0 \ub530\ub77c \uc77d\uc2b5\ub2c8\ub2e4. \uc2e0\ud654\uc640 \ubbfc\uc18d \ubb38\ud654\uc640 \uc608\uc220 \uc138\uc0c1\uc758 \uc9c0\ud61c\ub97c \ubaa8\ub450 \ud56d\uc544\ub9ac\uc5d0 \ub123\uc5c8\ub2e4\uba74 \uac71\uc815\ud560 \uc77c\uc774 \uc5c6\uc744\uae4c. \uc544\ub09c\uc2dc\ub294 \uadf8\ub807\uac8c \uc0dd\uac01\ud55c \ub4ef\ud558\ub2e4. \uc544\ubb34\ub3c4 \ub2ff\uc9c0 \ubabb\ud558\ub294 \ub192\uc740 \ub098\ubb34\uc5d0 \uc228\uae30\uba74 \ub2e4\uc2dc\ub294 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ub098\ub204\uc5b4 \uc8fc\uc9c0 \uc54a\uc544\ub3c4 \ub420 \uac83\uc774\ub2e4. \uadf8\ub7f0\ub370 \ub098\ubb34\uc5d0 \uc624\ub974\ub294 \uc544\uc8fc \uc791\uc740 \uc77c\uc774 \ub73b\ub300\ub85c \ub418\uc9c0 \uc54a\ub294\ub2e4. \uc11c\uc544\ud504\ub9ac\uce74\uc758 \uc544\ub09c\uc2dc \uc774\uc57c\uae30\uc5d0\ub294 \uc7ac\uce58\uc640 \uc695\uc2ec, \ub73b\ubc16\uc758 \uc2e4\ud328\uac00 \uc790\uc8fc \ub4f1\uc7a5\ud55c\ub2e4. \uc774 \uae00\uc740 \ubc14\ucee4\uc640 \uc2f1\ud074\ub808\uc5b4\uac00 \ud3b4\ub0b8 \u300e\uc11c\uc544\ud504\ub9ac\uce74 \ubbfc\ub2f4\u300f\uc758 \u300c\uc9c0\ud61c\uac00 \uc778\ub958\uc758 \uac83\uc774 \ub41c \uae4c\ub2ed\u300d\uc744 \ub530\ub77c \uc77d\ub294\ub2e4. \uc774 \ud310\ubcf8\uc758 \uc544\ub09c\uc2dc\ub294 \uc9c0\ud61c\ub97c \uac00\uc9c4 \uc544\ubc84\uc9c0\ub85c \ub098\uc628\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \ub0a0\ub9c8\ub2e4 \uadf8\uc5d0\uac8c \uc870\uc5b8\uacfc \ub3c4\uc6c0\uc744 \uad6c\ud55c\ub2e4. \ub9ce\uc740 \uc544\ub09c\uc2dc \uc804\uc2b9\uc5d0\uc11c \uac70\ubbf8\uc758 \ubaa8\uc2b5\uc774 \uce5c\uc219\ud558\uc9c0\ub9cc \uc5ec\uae30\uc11c\ub294 \uc0ac\ub78c\ucc98\ub7fc \ud589\ub3d9\ud558\ub294 \uc544\ubc84\uc9c0\uc640 \uc544\ub4e4\uc774 \uc774\uc57c\uae30\ub97c \uc774\ub048\ub2e4. \uadf8\uc758 \uc9c0\ud61c\ub294 \ud63c\uc790 \uc54c\uace0 \uc788\ub294 \ube44\ubc00\ub9cc\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc774\ubbf8 \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uac74\ub128 \uac83\ub3c4 \uc788\uc5c8\ub2e4. \ub204\uad70\uac00 \ubb3b\uace0 \ub2f5\uc744 \ub4e3\ub294 \uad00\uacc4 \uc18d\uc5d0\uc11c \uadf8\uc758 \ud798\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \uc774\uc57c\uae30\uc758 \ucd9c\ubc1c\uc5d0\ub294 \uc9c0\uc2dd\uc744 \ub098\ub204\ub294 \uc7a5\uba74\uc774 \ub193\uc5ec \uc788\ub2e4. \uc5b4\ub290 \ub0a0 \uc0ac\ub78c\ub4e4\uc774 \uc544\ub09c\uc2dc\uc758 \ub9c8\uc74c\uc744 \uc0c1\ud558\uac8c \ud55c\ub2e4. \uadf8\ub294 \ubc8c\uc744 \uc8fc\ub824\uace0 \uc790\uae30\uac00 \uc54c\ub824 \uc900 \uc9c0\ud61c\ub97c \ub2e4\uc2dc \uac70\ub450\uae30\ub85c \ud55c\ub2e4. \uc5bc\ub9c8\ub098 \uc2ec\ud55c \uc77c\uc774 \uc788\uc5c8\ub294\uc9c0\ubcf4\ub2e4 \uadf8\uac00 \ud0dd\ud55c \ub300\uc751\uc774 \uc774\uc57c\uae30\uc758 \uad00\uc2ec\uc774\ub2e4. \ub0a8\ub4e4\uc774 \uc4f0\uc9c0 \ubabb\ud558\uac8c \ub9cc\ub4e4\uaca0\ub2e4\ub294 \uac83\uc774\ub2e4. \uadf8\ub294 \uc9c0\ud61c\ub97c \ubaa8\uc544 \ud070 \ud56d\uc544\ub9ac\uc5d0 \ub2f4\uace0 \ub2e8\ub2e8\ud788 \ubd09\ud55c\ub2e4. \uc190\uc5d0 \uc7a1\ud788\uc9c0 \uc54a\ub294 \uc9c0\ud61c\ub97c \ub2f4\uc744 \uc218 \uc788\ub294 \ubb3c\uac74\ucc98\ub7fc \ub2e4\ub8e8\ub294 \uc0c1\uc0c1\uc774 \uc2dc\uc791\ub41c\ub2e4. \ud56d\uc544\ub9ac\ub97c \ub204\uac00 \uac00\uc9c0\uace0 \uc788\ub290\ub0d0\uac00 \uace7 \uc9c0\ud61c\ub97c \ub204\uac00 \uac00\uc9c0\ub290\ub0d0\ub77c\ub294 \uacc4\uc0b0\uc774\ub2e4. \uc544\ub4e4 \ud06c\uc6e8\ucfe0 \uce5c\uc740 \uc544\ubc84\uc9c0\uac00 \ubb34\uc5b8\uac00\ub97c \uafb8\ubbf8\ub294 \uac83\uc744 \ub208\uce58\ucc48\ub2e4. \ub2e4\uc74c \ub0a0 \uc544\ub09c\uc2dc\uac00 \ud56d\uc544\ub9ac\ub97c \uac00\uc9c0\uace0 \ub098\uac00\uc790 \uc870\uc6a9\ud788 \ub4a4\ub530\ub77c\uac04\ub2e4. \uc544\ubc84\uc9c0\ub294 \ub9c8\uc744\uc5d0\uc11c \uba40\ub9ac \ub5a8\uc5b4\uc9c4 \uc232\uc73c\ub85c \ub4e4\uc5b4\uac04\ub2e4. \uc544\ub4e4\uc740 \ucc98\uc74c\ubd80\ud130 \uacc4\ud68d\uc744 \ub9dd\uce58\ub824\ub294 \uac15\ud55c \uc801\uc73c\ub85c \ub4f1\uc7a5\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc9c0\ucf1c\ubcf4\uace0 \uc54c\uc544\ucc28\ub9ac\ub294 \uc0ac\ub78c\uc774 \ub420 \ubfd0\uc774\ub2e4. \ub204\uad6c\ub3c4 \ubaa8\ub974\uac8c \uac10\ucd94\ub824\ub294 \uc77c\uc5d0 \uac00\uae4c\uc6b4 \uc0ac\ub78c\uc774 \ubaa9\uaca9\uc790\ub85c \ub530\ub77c\ubd99\uc73c\uba74\uc11c \ub73b\ubc16\uc758 \uc7a5\uba74\uc774 \uc900\ube44\ub41c\ub2e4. \uc544\ub09c\uc2dc\ub294 \uc544\uc8fc \ub192\uc740 \ub098\ubb34\ub97c \uace8\ub77c \uc624\ub974\uae30 \uc2dc\uc791\ud55c\ub2e4. \ud56d\uc544\ub9ac\ub294 \ubaa9\uc5d0 \uac78\uc5b4 \uac00\uc2b4 \uc55e\uc73c\ub85c \ub9e4\ub2ec\uc558\ub2e4. \uc190\uacfc \ubab8\uc744 \ub098\ubb34\uc5d0 \ubd99\uc5ec\uc57c \ud558\ub294\ub370 \ubb34\uac70\uc6b4 \ud56d\uc544\ub9ac\uac00 \uadf8 \uc0ac\uc774\uc5d0\uc11c \uc790\uafb8 \uac78\ub9b0\ub2e4. \ub192\uc774 \uc228\uae38 \uc7a5\uc18c\ub97c \uace0\ub974\ub294 \uc9c0\ud61c\ub294 \uc788\uc5c8\uc9c0\ub9cc \uadf8\uacf3\uae4c\uc9c0 \uc5b4\ub5bb\uac8c \uc6b4\ubc18\ud560\uc9c0\ub294 \ud574\uacb0\ud558\uc9c0 \ubabb\ud588\ub2e4. \ub2e4\uc2dc \uc624\ub974\ub824 \ud560 \ub54c\ub9c8\ub2e4 \uac19\uc740 \uc7a5\uc560\ubb3c\uc774 \uc0dd\uae34\ub2e4. \uc774\uc57c\uae30\uc758 \ud070 \uc790\ub791\uc774 \ubab8 \uc55e\uc758 \ud56d\uc544\ub9ac \ud558\ub098\uc5d0 \ub9c9\ud788\ub294 \uc7a5\uba74\uc774\ub2e4. \ud55c\ub3d9\uc548 \ubc14\ub77c\ubcf4\ub358 \uc544\ub4e4\uc774 \ub9d0\ud55c\ub2e4. \ud56d\uc544\ub9ac\ub97c \ub4f1 \ucabd\uc73c\ub85c \ub3cc\ub824 \ub9e4\uba74 \ub354 \uc27d\uac8c \uc62c\ub77c\uac08 \uc218 \uc788\uc9c0 \uc54a\uaca0\ub290\ub0d0\ub294 \uc870\uc5b8\uc774\ub2e4. \ud2b9\ubcc4\ud55c \uc8fc\ubb38\ub3c4 \uc0c8 \ubb3c\uac74\ub3c4 \ud544\uc694 \uc5c6\ub2e4. \ub9e4\ub2ec\ub9b0 \uc704\uce58\ub97c \ubc14\uafb8\uc5b4 \ubcf4\ub294 \uc0dd\uac01\uc774\ub2e4. \uc774 \ud55c\ub9c8\ub514\uac00 \uc544\ub09c\uc2dc\uc758 \uacc4\ud68d \uc804\uccb4\ub97c \ud754\ub4e0\ub2e4. \uc9c0\ud61c\ub97c \ubaa8\ub450 \ubaa8\uc558\ub2e4\uace0 \ubbff\uc5c8\ub294\ub370 \uc790\uae30\uac00 \ub5a0\uc62c\ub9ac\uc9c0 \ubabb\ud55c \ubc29\ubc95\uc744 \uc544\ub4e4\uc774 \uc54c\uace0 \uc788\ub2e4. \ubb38\uc81c\ub294 \ub354 \uc774\uc0c1 \ub098\ubb34\ub97c \uc5bc\ub9c8\ub098 \ub192\uc774 \uc624\ub97c \uc218 \uc788\ub290\ub0d0\uac00 \uc544\ub2c8\ub2e4. \ud56d\uc544\ub9ac\uc5d0 \uc815\ub9d0 \ubaa8\ub4e0 \uc9c0\ud61c\uac00 \ub4e4\uc5b4 \uc788\ub290\ub0d0\uac00 \ub41c\ub2e4. \uc544\ub09c\uc2dc\ub294 \uc790\uae30\ubcf4\ub2e4 \uc544\ub4e4\uc774 \ub354 \ub098\uc740 \ub2f5\uc744 \ub0c8\ub2e4\ub294 \uc0ac\uc2e4\uc5d0 \ud654\uac00 \ub09c\ub2e4. \ud56d\uc544\ub9ac\ub97c \uc544\ub798\ub85c \ub358\uc9c0\uace0, \ubc14\uc704\uc5d0 \ubd80\ub52a\ud78c \ud56d\uc544\ub9ac\ub294 \uae68\uc9c4\ub2e4. \uc548\uc5d0 \uc788\ub358 \uc9c0\ud61c\uac00 \ubc14\uae65\uc73c\ub85c \ud758\ub7ec\ub098\uc640 \uc138\uc0c1\uc5d0 \ud37c\uc9c4\ub2e4. \uadf8\uac00 \ub9c8\uc74c\uc744 \uace0\uccd0\uba39\uace0 \ubaa8\ub450\uc5d0\uac8c \ub098\ub204\uc5b4 \uc8fc\uae30\ub85c \ud55c \uacb0\ub9d0\uacfc\ub294 \ub2e4\ub974\ub2e4. \ub3c5\uc810\ud558\ub824\ub358 \uacc4\ud68d\uc774 \uc2e4\ud328\ud558\uba74\uc11c \ub098\ub214\uc758 \uacb0\uacfc\uac00 \uc0dd\uae34 \uac83\uc774\ub2e4. \ub3d9\uae30\ub97c \uc0b4\ud3b4\ubcf4\uba74 \uc774 \uc774\uc57c\uae30\ub294 \ud6cc\ub96d\ud55c \uc5b4\ub978\uc758 \uad50\ud6c8\ubcf4\ub2e4 \uc695\uc2ec\uc774 \uc5c9\ub6b1\ud55c \uacb0\uacfc\ub97c \ub0b3\ub294 \uc775\uc0b4\uc5d0 \uac00\uae5d\ub2e4. \uc9c0\ud61c\uac00 \ud37c\uc9c0\ub294 \ub9c8\uc9c0\ub9c9\ubcf4\ub2e4 \uba3c\uc800 \uc911\uc694\ud55c \uc77c\uc774 \uc77c\uc5b4\ub0ac\ub2e4. \uc544\uc9c1 \ud56d\uc544\ub9ac\uac00 \uae68\uc9c0\uae30 \uc804\uc778\ub370 \uc544\ub4e4\uc740 \uc88b\uc740 \ubc29\ubc95\uc744 \uc54c\uc544\ub0c8\ub2e4. \uc9c0\ud61c\uac00 \uc804\ubd80 \uadf8 \uc548\uc5d0\ub9cc \uc788\ub2e4\ub294 \uc544\ubc84\uc9c0\uc758 \uc0dd\uac01\uc740 \uc774\ubbf8 \uc0ac\uc2e4\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uadf8\ub798\uc11c \ud56d\uc544\ub9ac\ub294 \uc9c0\ud61c \uc790\uccb4\uc774\uba74\uc11c \uc9c0\ud61c\ub97c \ub3c5\uc810\ud560 \uc218 \uc788\ub2e4\ub294 \ubbff\uc74c\uc758 \uc0c1\uc9d5\uc73c\ub85c\ub3c4 \uc77d\ud78c\ub2e4. \ubb3c\uac74\uc744 \uc790\uae30 \uc190\uc5d0 \uc950\uc5c8\ub2e4\uace0 \ubaa8\ub4e0 \ud310\ub2e8\uae4c\uc9c0 \ud63c\uc790 \uac00\uc9c8 \uc218\ub294 \uc5c6\uc5c8\ub2e4. \ub208\uc55e\uc758 \uc791\uc740 \uc77c\uc744 \uc0c8\ub86d\uac8c \ubcf4\ub294 \uc0ac\ub78c\uc740 \ub2e4\ub978 \uacf3\uc5d0\ub3c4 \uc788\uc5c8\ub2e4. \uc774 \ucc45\uc758 \uc774\uc57c\uae30\ub294 \ud310\ud2f0 \uc9c0\uc5ed\uc744 \ubc30\uacbd\uc73c\ub85c \uc18c\uac1c\ub41c\ub2e4. \uc544\ub09c\uc2dc \uc804\uc2b9\uc740 \ub354 \ub113\uc740 \uc544\uce78 \ubb38\ud654\uad8c\uacfc \ub2e4\ub978 \uc9c0\uc5ed\uc5d0\ub3c4 \uc774\uc5b4\uc838 \uc788\ub2e4. \uac19\uc740 \uc774\ub984\uc774 \ub098\uc628\ub2e4\uace0 \uc778\ubb3c\uc758 \ubaa8\uc2b5\uacfc \uc544\ub4e4\uc758 \uc774\ub984, \uae68\uc9c0\ub294 \uc774\uc720\uac00 \uc5b8\uc81c\ub098 \uac19\uc9c0\ub294 \uc54a\ub2e4. \uc624\ub798\ub41c \uc601\ubb38 \uc218\uc9d1\ubcf8\uc5d0\ub294 \ub2f9\uc2dc \uc218\uc9d1\uac00\uc758 \uc2dc\uc120\ub3c4 \ub2f4\uaca8 \uc788\ub2e4. \uadf8 \uc124\uba85\uc744 \uc624\ub298\uc758 \uc0ac\ub78c\ub4e4 \uc804\uccb4\uc5d0 \ub300\ud55c \ud3c9\uac00\ub85c \ubc1b\uc544\ub4e4\uc774\uc9c0 \uc54a\uc558\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \ud574\ub2f9 \uc774\uc57c\uae30\uc758 \uc0ac\uac74\uc744 \uc911\uc2ec\uc73c\ub85c \uc4f0\uace0 \ub2e4\ub978 \ud310\ubcf8\uc744 \ud45c\uc2dc \uc5c6\uc774 \uc11e\uc9c0 \uc54a\uc558\ub2e4. \ub2e4\uc2dc \ud56d\uc544\ub9ac\ub97c \uc0c1\uc0c1\ud574 \ubcf4\uc790. \uc544\ub09c\uc2dc\ub294 \ub0a8\ub4e4\uc774 \ub2ff\uc9c0 \ubabb\ud560 \ub192\uc774\ub97c \ucc3e\ub290\ub77c \ubc14\ub85c \uacc1\uc758 \uc544\ub4e4\uc774 \ubb34\uc5c7\uc744 \ubcfc \uc218 \uc788\ub294\uc9c0 \ub193\ucce4\ub2e4. \ud070 \ube44\ubc00\uc744 \uac00\uc9c4 \uc0ac\ub78c\ubcf4\ub2e4 \ubc16\uc5d0\uc11c \uc9c0\ucf1c\ubcf8 \uc0ac\ub78c\uc774 \uc26c\uc6b4 \uae38\uc744 \ubc1c\uacac\ud55c\ub2e4. \uc774\uac83\uc744 \uc5b4\ub978\uc740 \uc5b4\ub9ac\uc11d\uace0 \uc544\uc774\ub294 \uc5b8\uc81c\ub098 \uc633\ub2e4\ub294 \uaddc\uce59\uc73c\ub85c \ubc14\uafc0 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub204\uac00 \ub2f5\uc744 \uac00\uc84c\ub294\uc9c0 \ubbf8\ub9ac \uc815\ud574 \ub450\uba74 \uac00\uae4c\uc6b4 \uc870\uc5b8\uc744 \ubabb \ub4e4\uc744 \uc218 \uc788\ub2e4\ub294 \uc775\uc0b4\ub85c \uc77d\uc5b4\ub3c4 \ucda9\ubd84\ud558\ub2e4. \uc138\uc0c1\uc758 \uc9c0\ud61c\ub294 \ud56d\uc544\ub9ac \ud558\ub098\ubcf4\ub2e4 \ub113\ub2e4\ub294 \ub9d0\uc774 \uc6c3\uc74c \uc18d\uc5d0 \ub0a8\ub294\ub2e4."}, {"id": "angkor-wat-temple-and-changing-faith", "title": "\uc559\ucf54\ub974 \uc640\ud2b8 \u2014 \ub2e4\uc12f \ud0d1 \uc544\ub798\uc5d0 \uacb9\uccd0\uc9c4 \uc2e0\uc559\uc758 \uc2dc\uac04", "summary": "\uc0ac\uc6d0\uc758 \ub2e4\uc12f \ud0d1\uacfc \ubd80\uc870, \ubcc0\ud654\ud55c \uc2e0\uc559\uacfc \uc5ec\ud589\uae30 \uc774\ubbf8\uc9c0\uc758 \uc758\ubbf8\ub97c \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uac74\ucd95", "categories": ["arts"], "url": "stories/angkor-wat-temple-and-changing-faith/index.html", "image": "../media/angkor-wat-temple-and-changing-faith.jpg", "alt": "\uc559\ucf54\ub974 \uc640\ud2b8 \ubd81\uce21\uc744 \uadf8\ub9b0 1864\ub144 \uc5ec\ud589\uae30 \uc218\ub85d \uc5ed\uc0ac \uc0bd\ud654", "text": "\uc559\ucf54\ub974 \uc640\ud2b8 \u2014 \ub2e4\uc12f \ud0d1 \uc544\ub798\uc5d0 \uacb9\uccd0\uc9c4 \uc2e0\uc559\uc758 \uc2dc\uac04 \ud06c\uba54\ub974 \uc655\uc2e4\uc758 \ud78c\ub450\uad50 \uc0ac\uc6d0\uc5d0\uc11c \ud6c4\ub300 \ubd88\uad50 \uacf5\uac04\uae4c\uc9c0 \uc0ac\uc6d0\uc758 \ub2e4\uc12f \ud0d1\uacfc \ubd80\uc870, \ubcc0\ud654\ud55c \uc2e0\uc559\uacfc \uc5ec\ud589\uae30 \uc774\ubbf8\uc9c0\uc758 \uc758\ubbf8\ub97c \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4. \uac74\ucd95 \ubb38\ud654\uc640 \uc608\uc220 \ubb3c \ub108\uba38\ub85c \ub2e4\uc12f \uac1c\uc758 \ud0d1\uc774 \uc19f\uc740 \ud48d\uacbd\uc740 \uce84\ubcf4\ub514\uc544\ub97c \ub300\ud45c\ud558\ub294 \ubaa8\uc2b5\uc774 \ub418\uc5c8\ub2e4. \uc559\ucf54\ub974 \uc640\ud2b8\ub97c \uac70\ub300\ud55c \uc720\uc801\uc774\ub77c\uace0\ub9cc \uc18c\uac1c\ud558\uba74 \uadf8 \ud06c\uae30\ub294 \uc804\ud574\uc838\ub3c4 \uc65c \uc774\ub7f0 \ud615\ud0dc\uac00 \ud544\uc694\ud588\ub294\uc9c0\ub294 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc774\uacf3\uc740 \uc655\uc758 \uad8c\ub825\uacfc \uc885\uad50\uc801 \uc138\uacc4\ub97c \uac74\ucd95\uc73c\ub85c \ub4dc\ub7ec\ub0b8 \uc7a5\uc18c\uc600\ub2e4. \ub610\ud55c \ud55c \ubc88 \uc9c0\uc5b4\uc9c4 \ub4a4 \uc758\ubbf8\uac00 \uba48\ucd98 \uacf3\ub3c4 \uc544\ub2c8\ub2e4. \ucc98\uc74c\uc758 \uc2e0\uc559\uacfc \ud6c4\ub300\uc758 \ubd88\uad50\uc801 \uc0ac\uc6a9, \uc5ec\ud589\uc790\uac00 \ub0a8\uae34 \uadf8\ub9bc\uacfc \uc624\ub298\uc758 \uad00\ub78c\uc774 \uacb9\uce5c\ub2e4. \uc5b4\ub5a4 \uc655\uc774 \ubb34\uc5c7\uc744 \uc138\uc6b0\ub824 \ud588\ub294\uc9c0\uc5d0\uc11c \uc2dc\uc791\ud574 \uc0ac\ub78c\ub4e4\uc774 \uac19\uc740 \uac74\ubb3c\uc744 \uc5b4\ub5bb\uac8c \ub2e4\ub974\uac8c \uc774\uc5b4 \uc0ac\uc6a9\ud588\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc559\ucf54\ub974 \uc640\ud2b8\uc758 \uac74\uc124\uc740 12\uc138\uae30 \uc218\ub9ac\uc57c\ubc14\ub974\ub9cc 2\uc138\uc640 \uc5f0\uacb0\ub41c\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ud78c\ub450\uad50\uc758 \ube44\uc288\ub204\uc5d0\uac8c \ubc14\uce5c \uc655\uc2e4 \uc0ac\uc6d0\uc774\uc5c8\ub2e4. \ub2f9\uc2dc\uc758 \ud06c\uba54\ub974 \uc655\uad6d\uc740 \uc624\ub298\ub0a0\uc758 \uce84\ubcf4\ub514\uc544\uc640 \ub611\uac19\uc740 \uad6d\uac00 \uccb4\uc81c\uac00 \uc544\ub2c8\uc5c8\ub2e4. \ud604\uc7ac\uc758 \uc9c0\ub3c4\ub294 \uc7a5\uc18c\ub97c \ucc3e\ub294 \ucd9c\ubc1c\uc810\uc774\uc9c0 \ub2f9\uc2dc \uc138\uacc4\ub97c \ubaa8\ub450 \uc124\uba85\ud558\ub294 \ub2f5\uc740 \uc544\ub2c8\ub2e4. \uc655\uc2e4 \uc0ac\uc6d0\uc740 \uac1c\uc778\uc774 \uc870\uc6a9\ud788 \uae30\ub3c4\ud560 \uc791\uc740 \ubc29\uacfc \ub2ec\ub790\ub2e4. \uad6d\uac00\uc758 \uad8c\uc704\uc640 \uc655\uc2e4\uc758 \uae30\uc5b5, \uc885\uad50\uc801 \uc9c8\uc11c\ub97c \ud568\uaed8 \ub2f4\ub294 \uacf5\uac04\uc774\uc5c8\ub2e4. \uadf8\ub798\uc11c \uac74\ucd95\uc758 \uaddc\ubaa8\ub97c \ubd80\uc720\ud55c \uc655\uc758 \ucde8\ud5a5\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uae30 \uc5b4\ub835\ub2e4. \uadf8\uac00 \uc5b4\ub5a4 \uc138\uacc4\uc758 \uc911\uc2ec\uc5d0 \uc11c \uc788\ub2e4\uace0 \ubcf4\uc5ec \uc8fc\ub824 \ud588\ub294\uc9c0\ub97c \ud568\uaed8 \ubb3c\uc5b4\uc57c \ud55c\ub2e4. \uc559\ucf54\ub974 \uc640\ud2b8\uc758 \ub2e4\uc12f \ud0d1\uc740 \ud78c\ub450\uad50\uc5d0\uc11c \uc2e0\ub4e4\uc758 \uac70\ucc98\ub85c \uc5ec\uae30\ub294 \uba54\ub8e8\uc0b0\uc744 \ub098\ud0c0\ub0b4\ub294 \uac83\uc73c\ub85c \uc124\uba85\ub41c\ub2e4. \ud0d1\uc774 \ub192\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc774 \uc544\ub2c8\ub77c \ud2b9\uc815\ud55c \uc6b0\uc8fc\uad00\uc744 \uacf5\uac04\uc73c\ub85c \uc62e\uacbc\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \uc2e4\uc81c \ub545 \uc704\ub97c \uac78\uc73c\uba74\uc11c \uc2e0\uc131\ud55c \uc138\uacc4\ub97c \ud45c\ud604\ud55c \uac74\ucd95\uc744 \ub9c8\uc8fc\ud588\ub2e4. \uc774 \uc758\ubbf8\ub97c \uc54c\uace0 \ubcf4\uba74 \uc911\uc559\uc73c\ub85c \ubaa8\uc774\ub294 \ud615\ud0dc\uac00 \ub2e8\uc21c\ud55c \uc7a5\uc2dd\uc758 \uade0\ud615\uc744 \ub118\uc5b4\uc120\ub2e4. \uac74\ubb3c\uc740 \uc0ac\ub78c\uc774 \ub4dc\ub098\ub4e4 \uc218 \uc788\ub294 \uc2dc\uc124\uc774\uba74\uc11c \uc138\uacc4\ub97c \uc0c1\uc0c1\ud558\ub294 \ubaa8\ud615\uc774\uae30\ub3c4 \ud588\ub2e4. \ubb3c\ub860 \uad00\ub78c\uac1d\uc774 \ubaa8\ub4e0 \uc0c1\uc9d5\uc744 \uc678\uc6cc\uc57c \uac10\uc0c1\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc744 \ub2ee\uac8c \ub9cc\ub4e4\uc5c8\ub294\uc9c0 \ud558\ub098\ub9cc \uc54c\uc544\ub3c4 \uc2dc\uc57c\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \ub300\ud45c \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uc0ac\uc6d0\uc774 \ud558\ub098\uc758 \uc724\uacfd\uc73c\ub85c \ub4e4\uc5b4\uc624\uc9c0\ub9cc \uc548\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \uacbd\ud5d8\uc740 \ub2e4\ub974\ub2e4. \ubb3c\uacfc \uae38, \ubb38\uacfc \ud68c\ub791\uc744 \ucc28\ub840\ub85c \uc9c0\ub098\uba70 \uc2dc\uc57c\uc640 \ubab8\uc758 \uc704\uce58\uac00 \ubc14\ub010\ub2e4. \uac74\ucd95\uc758 \uc911\uc2ec\uc740 \uba40\ub9ac\uc11c \ubcf4\ub294 \ub300\uc0c1\uc774\uc5c8\ub2e4\uac00 \uac00\uae4c\uc774\uc5d0\uc11c \ub458\ub7ec\ubcf4\ub294 \uacf5\uac04\uc73c\ub85c \ubcc0\ud55c\ub2e4. \uc0ac\uc9c4\uc758 \uad6c\ub3c4\uc640 \ubc29\ubb38\uc758 \uc21c\uc11c\ub294 \uac19\uc9c0 \uc54a\ub2e4. \ub113\uc740 \uc7a5\uc18c\ub97c \uac78\uc744 \ub54c\uc5d0\ub294 \uac74\ubb3c\uc758 \ub192\uc774\ubfd0 \uc544\ub2c8\ub77c \uc790\uc2e0\uc774 \uc5b4\ub514\uc5d0 \uc788\ub294\uc9c0\ub3c4 \ub290\ub07c\uac8c \ub41c\ub2e4. \uc5b4\ub514\uac00 \uc5f4\ub9ac\uace0 \uc5b4\ub514\uac00 \ub9c9\ud788\uba70 \uc5b4\ub290 \ubc29\ud5a5\uc73c\ub85c \uc2dc\uc120\uc774 \uc774\ub04c\ub9ac\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uba74 \uc88b\ub2e4. \uc655\uc2e4 \uc0ac\uc6d0\uc758 \uc9c8\uc11c\ub294 \ubcbd\uc5d0 \uc4f0\uc778 \uc124\uba85\ub9cc\uc774 \uc544\ub2c8\ub77c \uc774\ub807\uac8c \uc6c0\uc9c1\uc774\ub294 \ubab8\uc758 \uacbd\ud5d8 \uc18d\uc5d0\ub3c4 \uc788\uc5c8\ub2e4. \uc559\ucf54\ub974 \uc640\ud2b8\uc758 \ubd80\uc870\uc5d0\ub294 \ud78c\ub450\uad50\uc758 \uc2e0\ub4e4\uacfc \uc11c\uc0ac\uc2dc\uc758 \uc7a5\uba74\ub4e4\uc774 \ud45c\ud604\ub418\uc5b4 \uc788\ub2e4. \u300e\ub9c8\ud558\ubc14\ub77c\ud0c0\u300f\uc640 \uac19\uc740 \uc774\uc57c\uae30\uc758 \uc138\uacc4\uac00 \uac74\ucd95 \ud45c\uba74\uc73c\ub85c \ub4e4\uc5b4\uc628 \uac83\uc774\ub2e4. \uc885\uad50\uc640 \ubb38\ud559, \uc870\uac01\uc744 \ubcc4\ub3c4\uc758 \ubd84\uc57c\ub85c \ub098\ub204\ub294 \uc624\ub298\uc758 \ubd84\ub958\ub9cc\uc73c\ub85c\ub294 \uc774 \ub9cc\ub0a8\uc774 \uc798 \ub4dc\ub7ec\ub098\uc9c0 \uc54a\ub294\ub2e4. \uad00\ub78c\uac1d\uc5d0\uac8c\ub294 \ubcf5\uc7a1\ud55c \uc778\ubb3c\uc758 \ud589\ub82c\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\uc9c0\ub9cc \ub2f9\uc2dc\uc5d0\ub294 \uc774\ubbf8 \uc804\ud574\uc9c0\ub358 \uc774\uc57c\uae30\ub97c \ub5a0\uc62c\ub9ac\ub294 \uc7a5\uba74\uc774\uc5c8\ub2e4. \ubd80\uc870\ub294 \ub3cc\ub85c \ub9cc\ub4e0 \uc774\ubbf8\uc9c0\uc774\uba74\uc11c \uae30\uc5b5\uc744 \ubd80\ub974\ub294 \uc7a5\uce58\ub2e4. \uc5b4\ub5a4 \uc7a5\uba74\uc778\uc9c0 \uc54c\uc544\uac00\ub294 \uc77c\uacfc \uc778\ubb3c\uc758 \uc790\uc138\uc640 \ubc18\ubcf5\uc744 \ubcf4\ub294 \uc990\uac70\uc6c0\uc774 \ud568\uaed8 \uc788\uc744 \uc218 \uc788\ub2e4. \ud6c4\ub300\uc5d0 \uc559\ucf54\ub974 \uc640\ud2b8\ub294 \ubd88\uad50 \uc2e0\uc559\uc758 \uc7a5\uc18c\ub85c\ub3c4 \uc0ac\uc6a9\ub418\uc5c8\ub2e4. \uc774 \ubcc0\ud654\ub294 \uac74\ubb3c\uc774 \ud558\ub098\uc758 \uc885\uad50\uc801 \uc758\ubbf8\ub9cc \uac00\uc9c0\uace0 \uc2dc\uac04\uc744 \uba48\ucdc4\ub2e4\ub294 \uc0dd\uac01\uc744 \ud754\ub4e0\ub2e4. \uac19\uc740 \ub3cc\uacfc \ud68c\ub791\uc774 \ub0a8\uc544 \uc788\uc5b4\ub3c4 \uadf8\uacf3\uc5d0\uc11c \uae30\ub3c4\ud558\ub294 \uc0ac\ub78c\ub4e4\uc774 \ubd80\uc5ec\ud558\ub294 \uc758\ubbf8\ub294 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc774\uc804\uc758 \ubaa8\ub4e0 \ud754\uc801\uc774 \uc9c0\uc6cc\uc9c0\uace0 \uc644\uc804\ud788 \uc0c8 \uac74\ubb3c\uc774 \ub41c \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uc624\ub798\ub41c \ud615\ud0dc\uc640 \uc0c8\ub85c\uc6b4 \uc0ac\uc6a9\uc774 \ud568\uaed8 \ub0a8\ub294\ub2e4. \uc720\uc801\uc744 \uc774\ud574\ud560 \ub54c \uac74\uc124 \ub2f9\uc2dc\uc758 \ub73b\uc744 \ucc3e\ub294 \uc77c\uc740 \uc911\uc694\ud558\uc9c0\ub9cc \uadf8\uac83\ub9cc\uc73c\ub85c \uc774\ud6c4\uc758 \uc2dc\uac04\uc744 \uc9c0\uc6cc\uc11c\ub294 \uc548 \ub41c\ub2e4. \uac74\ucd95\uc758 \uc5ed\uc0ac\ub294 \ucc98\uc74c \ub9cc\ub4e0 \uc0ac\ub78c\uacfc \uacc4\uc18d \uc0ac\uc6a9\ud55c \uc0ac\ub78c \ubaa8\ub450\uc758 \uc5ed\uc0ac\ub2e4. 19\uc138\uae30 \uc720\ub7fd \uc5ec\ud589\uc790 \uc559\ub9ac \ubb34\uc624\uc758 \uae30\ub85d\uacfc \uadf8\ub9bc\uc740 \uc559\ucf54\ub974\ub97c \ub2e4\ub978 \uc9c0\uc5ed\uc758 \ub3c5\uc790\ub4e4\uc5d0\uac8c \uc54c\ub9ac\ub294 \ub370 \uc601\ud5a5\uc744 \uc8fc\uc5c8\ub2e4. \uc774\ub7f0 \uc5ec\ud589\uae30\ub294 \ub2f9\uc2dc\uc758 \ud48d\uacbd\uc744 \uc0b4\ud3b4\ubcfc \uc790\ub8cc\uc9c0\ub9cc, \uc678\ubd80\uc778\uc774 \uae00\uc744 \ub0a8\uacbc\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uadf8 \uc7a5\uc18c\uc5d0 \uc774\uc804\uc758 \uae30\uc5b5\uacfc \uc0ac\uc6a9\uc774 \uc5c6\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ubc1c\uacac\uc774\ub77c\ub294 \uc775\uc219\ud55c \ub9d0\uc5d0\ub294 \ub204\uad6c\uc758 \uc2dc\uc120\uc5d0\uc11c \uc0c8\ub85c \uc54c\uac8c \ub418\uc5c8\ub294\uc9c0\uac00 \ube60\uc9c0\uae30 \uc27d\ub2e4. \uc774\ubbf8 \uadf8\uacf3\uc744 \uc54c\ub358 \uc0ac\ub78c\uacfc \uba40\ub9ac\uc11c \ucc98\uc74c \uadf8\ub9bc\uc744 \ubcf8 \ub3c5\uc790\uc758 \uacbd\ud5d8\uc740 \ub2e4\ub974\ub2e4. \uc5ec\ud589\uc790\uc758 \uac10\ud0c4\uc744 \uc77d\uc73c\uba74\uc11c\ub3c4 \uadf8\uac83\uc744 \uc138\uacc4 \uc804\uccb4\uac00 \ucc98\uc74c \ub9cc\ub09c \uc21c\uac04\uc73c\ub85c \ubc14\uafb8\uc9c0 \uc54a\ub294 \ud0dc\ub3c4\uac00 \ud544\uc694\ud558\ub2e4. \uc559\ucf54\ub974 \uc640\ud2b8\ub294 \uc0ac\ub77c\uc9c4 \uc655\uad6d\uc758 \uac74\ucd95\uc744 \ubcf4\uc5ec \uc8fc\uba74\uc11c\ub3c4 \uc9c0\uae08\uae4c\uc9c0 \uc774\uc5b4\uc9c4 \uc2e0\uc559\uc758 \uc2dc\uac04\uc744 \ud488\uace0 \uc788\ub2e4. \uacfc\uac70\uc758 \uc815\uce58\uc801 \uccb4\uc81c\uac00 \ub05d\ub0ac\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc7a5\uc18c\uc758 \ubaa8\ub4e0 \uc758\ubbf8\uac00 \ub05d\ub0ac\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub974\ub2e4. \uc774 \ucc28\uc774\ub97c \uc54c\uba74 \ud3d0\ud5c8\ub77c\ub294 \ud55c \ub2e8\uc5b4\ub85c \ub2f4\uae30 \uc5b4\ub824\uc6b4 \uba74\uc774 \ubcf4\uc778\ub2e4. \uc5ed\uc0ac \uc0bd\ud654\uc640 \uc624\ub298\uc758 \ud48d\uacbd\uc744 \ube44\uad50\ud560 \ub54c\uc5d0\ub3c4 \uc774 \uc810\uc740 \uc720\uc6a9\ud558\ub2e4. \uc5ec\ud589 \ucc45\uc758 \uadf8\ub9bc\uc740 \ud2b9\uc815 \ubc29\ud5a5\uacfc \uc7a5\uba74\uc744 \uc120\ud0dd\ud574 \ubcf4\uc5ec \uc900\ub2e4. \uadf8\uac83\uc774 \uc2e4\uc81c \ucd9c\ud310\ub41c \uc790\ub8cc\ub77c\ub294 \uc0ac\uc2e4\uacfc \uac74\ucd95\uc758 \ubaa8\ub4e0 \uc138\ubd80\ub97c \uc815\ud655\ud788 \ubcf5\uc6d0\ud574 \uc900\ub2e4\ub294 \uc8fc\uc7a5\uc740 \uc11c\ub85c \ub2e4\ub974\ub2e4. \ub2e4\uc12f \ud0d1\uc758 \uba4b\uc9c4 \uc724\uacfd\uc744 \ubcf8 \ub2e4\uc74c\uc5d0\ub294 \ud45c\uba74\uc758 \uc774\uc57c\uae30\uc640 \uac74\ubb3c\uc744 \uc0ac\uc6a9\ud55c \uc5ec\ub7ec \uc2dc\ub300\ub97c \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc655\uc2e4\uc758 \ud78c\ub450\uad50 \uc0ac\uc6d0, \ud6c4\ub300\uc758 \ubd88\uad50\uc801 \uacf5\uac04, \uc5ec\ud589 \ucc45 \uc18d \uc774\ubbf8\uc9c0\uac00 \ud55c \uc7a5\uc18c\uc5d0 \uacb9\uce5c\ub2e4. \uc559\ucf54\ub974 \uc640\ud2b8\uc758 \uae4a\uc774\ub294 \ud06c\uae30\ubfd0 \uc544\ub2c8\ub77c \uadf8 \uacb9\uce68\uc744 \uc77d\ub294 \ub370\uc5d0\ub3c4 \uc788\ub2e4."}, {"id": "antigone-burial-law-and-listening", "title": "\uc548\ud2f0\uace0\ub124 \u2014 \uc655\uc758 \uba85\ub839\uc73c\ub85c \uc7a5\ub840\ub97c \uae08\ud560 \uc218 \uc788\uc744\uae4c", "summary": "\uc7a5\ub840\ub97c \uae08\ud55c \uba85\ub839\uacfc \uc790\ub9e4\u00b7\ubd80\uc790 \uc0ac\uc774\uc758 \ub300\ud654, \ub108\ubb34 \ub2a6\uc740 \uc218\uc815\uc758 \uacb0\ub9d0\uc744 \ub530\ub77c\uac11\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/antigone-burial-law-and-listening/index.html", "image": "../media/antigone-burial-law-and-listening.png", "alt": "\ud14c\ubca0\uc758 \uc131\ubcbd \uc55e\uc5d0\uc11c \uacb0\uc2ec\ud55c \uc548\ud2f0\uace0\ub124\ub97c \uc5f0\uc0c1\ud558\ub294 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uc548\ud2f0\uace0\ub124 \u2014 \uc655\uc758 \uba85\ub839\uc73c\ub85c \uc7a5\ub840\ub97c \uae08\ud560 \uc218 \uc788\uc744\uae4c \uc18c\ud3ec\ud074\ub808\uc2a4\uc758 \ube44\uadf9\uc5d0\uc11c \uc7a5\ub840\uc640 \ud1b5\uce58, \ub4e3\ub294 \ub2a5\ub825\uc744 \ubb3b\uae30 \uc7a5\ub840\ub97c \uae08\ud55c \uba85\ub839\uacfc \uc790\ub9e4\u00b7\ubd80\uc790 \uc0ac\uc774\uc758 \ub300\ud654, \ub108\ubb34 \ub2a6\uc740 \uc218\uc815\uc758 \uacb0\ub9d0\uc744 \ub530\ub77c\uac11\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \ub3c4\uc2dc\ub97c \uacf5\uaca9\ud55c \uc0ac\ub78c\uc758 \uc2dc\uc2e0\uc744 \ubb3b\uc9c0 \ub9d0\ub77c\ub294 \uba85\ub839\uc774 \ub0b4\ub824\uc9c4\ub2e4. \uadf8\ub7f0\ub370 \uadf8 \uc8fd\uc740 \uc774\ub294 \ud55c \uc5ec\uc131\uc758 \uc624\ube60\uc774\uae30\ub3c4 \ud558\ub2e4. \uc18c\ud3ec\ud074\ub808\uc2a4\uc758 \u300e\uc548\ud2f0\uace0\ub124\u300f\ub294 \uacf5\ub3d9\uccb4\uc758 \uc9c8\uc11c\uc640 \uac00\uc871\uc758 \uc758\ubb34\uac00 \ucda9\ub3cc\ud560 \ub54c \ub204\uac00 \uc633\ub2e4\uace0 \ub9d0\ud560 \uc218 \uc788\ub294\uc9c0 \ubb3b\ub294\ub2e4. \ud14c\ubca0\ub97c \ubb34\ub300\ub85c \ud55c \uc774 \ube44\uadf9\uc758 \uc8fc\uc694 \uc0ac\uac74\uacfc \uacb0\ub9d0\uc744 \ub530\ub77c\uac00 \ubcf4\uc790. \uc624\uc774\ub514\ud478\uc2a4\uc758 \ub450 \uc544\ub4e4 \uc5d0\ud14c\uc624\ud074\ub808\uc2a4\uc640 \ud3f4\ub9ac\ub124\uc774\ucf00\uc2a4\ub294 \uc11c\ub85c \uc801\uc774 \ub418\uc5b4 \uc2f8\uc6b0\ub2e4 \ud568\uaed8 \uc8fd\ub294\ub2e4. \uc0c8 \uc9c0\ubc30\uc790 \ud06c\ub808\uc628\uc740 \ub3c4\uc2dc\ub97c \uc9c0\ud0a8 \ucabd\uc740 \uc7a5\ub840\ub97c \uce58\ub974\uace0, \uacf5\uaca9\ud55c \ud3f4\ub9ac\ub124\uc774\ucf00\uc2a4\ub294 \ub9e4\uc7a5\ud558\uc9c0 \ubabb\ud558\uac8c \ud55c\ub2e4. \uc8fd\uc740 \ub450 \uc0ac\ub78c\uc758 \ubab8\uc5d0 \uc11c\ub85c \ub2e4\ub978 \uc815\uce58\uc801 \uc758\ubbf8\uac00 \ubd80\uc5ec\ub41c\ub2e4. \uc548\ud2f0\uace0\ub124\uc5d0\uac8c \ub450 \uc0ac\ub78c\uc740 \ubaa8\ub450 \uc624\ube60\ub2e4. \ud06c\ub808\uc628\uc758 \uba85\ub839\uc744 \ubc1b\uc544\ub4e4\uc774\uba74 \uac00\uc871\uc5d0\uac8c \ud574\uc57c \ud560 \uc758\ubb34\ub97c \ubc84\ub9ac\uac8c \ub41c\ub2e4. \uc2f8\uc6c0\uc740 \ub05d\ub0ac\uc9c0\ub9cc \uc8fd\uc740 \uc0ac\ub78c\uc744 \uc5b4\ub5bb\uac8c \ub300\ud560 \uac83\uc778\uc9c0\ub97c \ub458\ub7ec\uc2f8\uace0 \uc0c8\ub85c\uc6b4 \uc2f8\uc6c0\uc774 \uc2dc\uc791\ub41c\ub2e4. \uc804\uc7c1 \ub4a4\uc758 \uc9c8\uc11c\uac00 \ub204\uad6c\uc5d0\uac8c \uc5b4\ub5a4 \uace0\ud1b5\uc744 \uc694\uad6c\ud558\ub294\uc9c0\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \uc548\ud2f0\uace0\ub124\ub294 \uc790\ub9e4 \uc774\uc2a4\uba54\ub124\uc5d0\uac8c \ud568\uaed8 \ud589\ub3d9\ud558\uc790\uace0 \ud55c\ub2e4. \uc774\uc2a4\uba54\ub124\ub294 \uad8c\ub825\uc5d0 \ub9de\uc124 \ucc98\uc9c0\uc640 \uc774\ubbf8 \uac00\uc871\uc774 \uacaa\uc740 \ud30c\uba78\uc744 \ub450\ub824\uc6cc\ud55c\ub2e4. \ub450 \uc790\ub9e4\uc758 \ub300\ud654\ub294 \uc6a9\uac10\ud55c \uc0ac\ub78c\uacfc \ube44\uac81\ud55c \uc0ac\ub78c\uc774\ub77c\ub294 \uad6c\ubd84\ub9cc\uc73c\ub85c \ucda9\ubd84\ud788 \uc77d\ud788\uc9c0 \uc54a\ub294\ub2e4. \uc0b4\uc544\ub0a8\uc544\uc57c \ud55c\ub2e4\ub294 \ud310\ub2e8\ub3c4 \uadf8\ub4e4\uc758 \uc5ed\uc0ac \uc18d\uc5d0\uc11c \ub098\uc628\ub2e4. \uc548\ud2f0\uace0\ub124\ub294 \ud63c\uc790\ub77c\ub3c4 \uc7a5\ub840\uc758 \uc758\ubb34\ub97c \uc218\ud589\ud558\ub824 \ud55c\ub2e4. \uadf8\ub140\uc5d0\uac8c \uadf8\uac83\uc740 \uc655\uc774 \ud5c8\uc6a9\ud558\uba74 \ud558\uace0 \uae08\ud558\uba74 \uba48\ucd94\ub294 \uc77c\uc774 \uc544\ub2c8\ub2e4. \uc778\uac04\uc758 \uba85\ub839\ubcf4\ub2e4 \uc624\ub798\ub41c \uc2e0\uc131\ud55c \uc758\ubb34\uac00 \uc788\ub2e4\uace0 \ubbff\uae30 \ub54c\ubb38\uc774\ub2e4. \ubc95\uc744 \uc5b4\uae30\ub294 \ud589\ub3d9\uc774 \ub354 \ub192\uc740 \uaddc\ubc94\uc5d0 \ub300\ud55c \ubcf5\uc885\uc774\ub77c\ub294 \uc5ed\uc804\uc774 \uc0dd\uae34\ub2e4. \uacbd\ube44\ubcd1\uc740 \uc2dc\uc2e0\uc5d0 \ud759\uc774 \ub36e\uc778 \ud754\uc801\uc744 \ubc1c\uacac\ud55c\ub2e4. \ub4a4\uc774\uc5b4 \ubd99\uc7a1\ud78c \uc548\ud2f0\uace0\ub124\ub294 \uc790\uc2e0\uc774 \ud55c \uc77c\uc744 \ubd80\uc778\ud558\uc9c0 \uc54a\ub294\ub2e4. \ubab0\ub790\ub2e4\uace0 \ubcc0\uba85\ud558\uac70\ub098 \uc798\ubabb\uc744 \uc6a9\uc11c\ud574 \ub2ec\ub77c\uace0 \ub9d0\ud558\uc9c0\ub3c4 \uc54a\ub294\ub2e4. \uadf8\ub140\uac00 \uba85\ub839\uc744 \uc54c\uba74\uc11c\ub3c4 \uc5b4\uacbc\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub300\ub9bd\uc744 \ub354\uc6b1 \ub0a0\uce74\ub86d\uac8c \ub9cc\ub4e0\ub2e4. \ud06c\ub808\uc628\uc740 \uc790\uc2e0\uc758 \uc9c0\uc2dc\uac00 \ubb34\uc2dc\ub418\uba74 \ub3c4\uc2dc\ub97c \ub2e4\uc2a4\ub9b4 \uad8c\uc704\uac00 \ubb34\ub108\uc9c4\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uba85\ub839\uc744 \uc9c0\ud0a4\uac8c \ud558\ub294 \uc77c\uacfc \uadf8 \uba85\ub839\uc774 \uc633\uc740\uc9c0 \uac80\ud1a0\ud558\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uadf8\ub294 \ubd88\ubcf5\uc885\uc744 \uac1c\uc778\uc801\uc778 \ub3c4\uc804\uc73c\ub85c \ubc1b\uc544\ub4e4\uc77c\uc218\ub85d \ub2e4\ub978 \ud310\ub2e8\uc744 \ub4e4\uc744 \uc5ec\uc720\ub97c \uc783\ub294\ub2e4. \ud06c\ub808\uc628\uc758 \uc544\ub4e4 \ud558\uc774\ubaac\uc740 \uc548\ud2f0\uace0\ub124\uc640 \uacb0\ud63c\ud560 \uc0ac\uc774\uc9c0\ub9cc, \ub2e8\uc21c\ud788 \uc57d\ud63c\uc790\ub97c \uc0b4\ub824 \ub2ec\ub77c\uace0\ub9cc \ub9d0\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc2dc\ubbfc\ub4e4\uc774 \uacf5\uac1c\uc801\uc73c\ub85c \ud558\uc9c0 \ubabb\ud558\ub294 \ub2e4\ub978 \uc758\uacac\uc774 \uc788\uc74c\uc744 \uc804\ud55c\ub2e4. \ud1b5\uce58\uc790\ub294 \uc790\uae30\uac00 \ub4e3\ub294 \ub9d0\uc774 \ub3c4\uc2dc \uc804\uccb4\uc758 \uc0dd\uac01\uacfc \uac19\uc9c0 \uc54a\uc744 \uc218 \uc788\uc74c\uc744 \uc54c\uc544\uc57c \ud55c\ub2e4\ub294 \ub73b\uc774\ub2e4. \ud06c\ub808\uc628\uc740 \uadf8 \ucda9\uace0\ub97c \uc544\ub4e4\uc758 \ubbf8\uc219\ud568\uacfc \ubd88\ubcf5\uc885\uc73c\ub85c \ubc1b\uc544\ub4e4\uc778\ub2e4. \ub300\ud654\ub294 \uc810\uc810 \ub204\uac00 \ub204\uad6c\ub97c \uac00\ub974\uce60 \uc218 \uc788\ub294\uac00 \ud558\ub294 \uc2f8\uc6c0\uc774 \ub41c\ub2e4. \uac00\uc871\uc758 \uad00\uacc4\uc640 \uc815\uce58\uc801 \uad8c\uc704\uac00 \uacb9\uce58\uba74\uc11c, \uac00\uae4c\uc6b4 \uc0ac\ub78c\uc758 \ub9d0\uc870\ucc28 \ub0b4\uc6a9\ubcf4\ub2e4 \ub9d0\ud55c \uc0ac\ub78c\uc758 \uc9c0\uc704\ub85c \ud3c9\uac00\ub41c\ub2e4. \uc791\ud488\uc5d0\ub294 \uc0ac\uac74\uc744 \ubc14\ub77c\ubcf4\uace0 \ub178\ub798\ud558\ub294 \ud569\ucc3d\ub300\ub3c4 \uc788\ub2e4. \uc774\ub4e4\uc740 \uc8fc\uc778\uacf5\ucc98\ub7fc \uc9c1\uc811 \uacb0\uc815\uc744 \ub0b4\ub9ac\uc9c0 \uc54a\uc73c\uba74\uc11c \ub3c4\uc2dc\uc640 \uc778\uac04\uc758 \uc0b6\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc778\ubb3c\uc758 \ub300\uc0ac\ub9cc \ub530\ub77c \uc77d\uae30\ubcf4\ub2e4 \uc7a5\uba74 \uc0ac\uc774\uc758 \ubaa9\uc18c\ub9ac\uac00 \ubb34\uc5c7\uc744 \ub450\ub824\uc6cc\ud558\uace0 \uc5b4\ub5bb\uac8c \ud310\ub2e8\ud558\ub294\uc9c0 \uc0b4\ud53c\uba74 \uac08\ub4f1\uc758 \ubc94\uc704\uac00 \ub113\uc5b4\uc9c4\ub2e4. \ud558\uc774\ubaac\uacfc \ud06c\ub808\uc628\uc758 \ub2e4\ud23c\uc5d0\uc11c\ub3c4 \uc0ac\ub791\uacfc \uc815\uce58\uac00 \ub2e8\uc21c\ud558\uac8c \ub098\ub258\uc9c0 \uc54a\ub294\ub2e4. \uc544\ub4e4\uc740 \uc544\ubc84\uc9c0\ub97c \uc124\ub4dd\ud558\ub824 \ud558\uc9c0\ub9cc \uc544\ubc84\uc9c0\ub294 \uc790\uae30 \ud3b8\uc5d0 \uc11c\ub294\uc9c0\uac00 \uba3c\uc800 \uc911\uc694\ud574\uc9c4\ub2e4. \ucda9\uace0\ub97c \uc801\ub300\uc758 \ud45c\uc2dc\ub85c \ubc1b\uc544\ub4e4\uc774\ub294 \uc21c\uac04 \ub300\ud654\uc758 \ubb38\uc740 \ub2eb\ud78c\ub2e4. \uac00\uc871 \uc548\uc758 \uc7a5\uba74\uc774 \ud1b5\uce58\uc758 \ubb38\uc81c\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc774\uc720\ub2e4. \uc548\ud2f0\uace0\ub124\uc5d0\uac8c \ub0b4\ub824\uc9c0\ub294 \ucc98\ubc8c\uc740 \ubc14\uc704 \ub3d9\uad74\uc5d0 \uac00\ub450\ub294 \uac83\uc774\ub2e4. \uc8fd\uc740 \uc0ac\ub78c\uc5d0\uac8c \ubb34\ub364\uc744 \uc8fc\ub824\ub358 \uc0ac\ub78c \uc790\uc2e0\uc774 \uc0b0 \ucc44\ub85c \uc8fd\uc74c\uc758 \uacf5\uac04\uc5d0 \ub193\uc778\ub2e4. \uc7a5\ub840\ub97c \ub458\ub7ec\uc2fc \uac08\ub4f1\uc774 \uc0b6\uacfc \uc8fd\uc74c\uc758 \uc790\ub9ac\ub97c \ub4a4\uc9d1\ub294 \ud615\ud0dc\ub85c \ub098\ud0c0\ub09c\ub2e4. \uadf8\ub140\ub294 \ub9c8\uc9c0\ub9c9\uae4c\uc9c0 \ud55c \uac00\uc9c0 \uac10\uc815\ub9cc \uac00\uc9c4 \ucca0\uc778\ucc98\ub7fc \ud589\ub3d9\ud558\uc9c0 \uc54a\ub294\ub2e4. \uacb0\ud63c\uacfc \uc55e\uc73c\ub85c\uc758 \uc0b6\uc744 \uc783\ub294 \uc2ac\ud514\ub3c4 \ub9d0\ud55c\ub2e4. \uc790\uc2e0\uc758 \uc120\ud0dd\uc744 \uc633\ub2e4\uace0 \ubbff\ub294\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc8fd\uc74c\uc744 \ub450\ub835\uc9c0 \uc54a\uac8c \ub9cc\ub4dc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud655\uc2e0\uacfc \uc0c1\uc2e4\uc774 \ud568\uaed8 \uc788\uc744 \ub54c \uc778\ubb3c\uc758 \uacb0\uc2ec\uc740 \ub354 \ubb34\uac81\uac8c \ub290\uaef4\uc9c4\ub2e4. \uc608\uc5b8\uc790 \ud14c\uc774\ub808\uc2dc\uc544\uc2a4\ub294 \ub3c4\uc2dc\uc758 \uc81c\uc758\uac00 \uc5b4\uae0b\ub098\uace0 \uc788\uc74c\uc744 \uacbd\uace0\ud55c\ub2e4. \ud06c\ub808\uc628\uc740 \ucc98\uc74c\uc5d0\ub294 \uadf8 \ub9d0\ub3c4 \uc758\uc2ec\ud558\uc9c0\ub9cc \uacb0\uad6d \uacb0\uc815\uc744 \ubc14\uafbc\ub2e4. \ud3f4\ub9ac\ub124\uc774\ucf00\uc2a4\ub97c \ubb3b\uace0 \uc548\ud2f0\uace0\ub124\ub97c \ud480\uc5b4 \uc8fc\ub824 \ud55c\ub2e4. \ube44\uadf9\uc740 \ub05d\uae4c\uc9c0 \ud55c \ubc88\ub3c4 \ub9c8\uc74c\uc744 \ubc14\uafb8\uc9c0 \uc54a\uc740 \uc0ac\ub78c\uc5d0\uac8c\ub9cc \uc77c\uc5b4\ub098\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \ub3d9\uad74\uc5d0 \uc774\ub974\ub800\uc744 \ub54c \uc548\ud2f0\uace0\ub124\ub294 \uc774\ubbf8 \uc8fd\uc5b4 \uc788\ub2e4. \ud558\uc774\ubaac\ub3c4 \ubaa9\uc228\uc744 \uc783\uace0, \uc18c\uc2dd\uc744 \ub4e4\uc740 \ud06c\ub808\uc628\uc758 \uc544\ub0b4 \uc5d0\uc6b0\ub9ac\ub514\ucf00\uae4c\uc9c0 \uc8fd\ub294\ub2e4. \ud1b5\uce58\uc790\ub294 \uba85\ub839\uc744 \uac70\ub450\uc5c8\uc9c0\ub9cc \uad00\uacc4\ub97c \ub418\ub3cc\ub9b4 \uc218 \uc5c6\ub2e4. \ud310\ub2e8\uc758 \uc218\uc815\uc5d0 \ud544\uc694\ud55c \uc2dc\uac04\uc774 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ub9c8\uc9c0\ub9c9 \uc2dc\uac04\uc774\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4. \u300e\uc548\ud2f0\uace0\ub124\u300f\ub97c \ud55c\ucabd\uc774 \uc644\uc804\ud788 \uc633\uace0 \ub2e4\ub978 \ucabd\uc740 \uc544\ubb34 \uc774\uc720 \uc5c6\uc774 \uc545\ud558\ub2e4\ub294 \uc774\uc57c\uae30\ub85c \ub9cc\ub4e4\uba74 \uc9c8\ubb38\uc758 \uae4a\uc774\uac00 \uc904\uc5b4\ub4e0\ub2e4. \ub3c4\uc2dc\uc758 \uc9c8\uc11c\ub294 \ud544\uc694\ud558\uc9c0\ub9cc \uadf8 \ud544\uc694\uac00 \ubaa8\ub4e0 \uba85\ub839\uc744 \uc633\uac8c \ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uac00\uc871\uc758 \uc758\ubb34\ub3c4 \uac1c\uc778\uc774 \uac10\ub2f9\ud574\uc57c \ud560 \ud070 \ub300\uac00\ub97c \uc5c6\uc560 \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \ud2b9\ud788 \ud06c\ub808\uc628\uc758 \ube44\uadf9\uc740 \ub4e3\ub294 \ub2a5\ub825\uc758 \uc2e4\ud328\uc640 \uc5f0\uacb0\ub41c\ub2e4. \uc790\ub9e4\uc640 \uacbd\ube44\ubcd1, \uc544\ub4e4\uacfc \uc608\uc5b8\uc790\uc758 \ub9d0\uc774 \uc774\uc5b4\uc9c0\ub294\ub370\ub3c4 \ub300\ud654\uac00 \ud310\ub2e8\uc744 \uace0\uce58\ub294 \uae30\ud68c\uac00 \ub418\uc9c0 \ubabb\ud55c\ub2e4. \uace0\ub300\uc758 \ubb34\ub300\ub294 \ubc95\uacfc \uc591\uc2ec\uc744 \ub17c\ud558\ub294 \ub3d9\uc2dc\uc5d0, \ub2e4\ub978 \ubaa9\uc18c\ub9ac\uac00 \ub4e4\uc5b4\uc62c \ud2c8\uc744 \uad8c\ub825\uc774 \uc5b4\ub5bb\uac8c \ub2eb\ub294\uc9c0 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "bach-brandenburg-dedication-and-voices", "title": "\ube0c\ub780\ub374\ubd80\ub974\ud06c \ud611\uc8fc\uace1 \u2014 \uac19\uc740 \uc774\ub984 \uc544\ub798 \uc5ec\uc12f \uac00\uc9c0 \ud569\uc8fc\uac00 \ubaa8\uc778 \uc774\uc720", "summary": "\ud5cc\uc815\uc758 \ubc30\uacbd\uacfc \uc5ec\uc12f \uace1\uc758 \ud3b8\uc131, \uc81c2\u00b75\u00b76\ubc88\uc758 \uc74c\uc0c9\uc744 \ud1b5\ud574 \uc5ec\ub7ec \ubaa9\uc18c\ub9ac\uc758 \uad00\uacc4\ub97c \ub4e3\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc74c\uc545", "categories": ["arts"], "url": "stories/bach-brandenburg-dedication-and-voices/index.html", "image": "../media/bach-brandenburg-dedication-and-voices.png", "alt": "\ud558\ud504\uc2dc\ucf54\ub4dc\uc640 \uad00\uc545\uae30\u00b7\ud604\uc545\uae30\uac00 \ud568\uaed8\ud558\ub294 \ubc14\ub85c\ud06c \uad81\uc815 \uc5f0\uc8fc\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ube0c\ub780\ub374\ubd80\ub974\ud06c \ud611\uc8fc\uace1 \u2014 \uac19\uc740 \uc774\ub984 \uc544\ub798 \uc5ec\uc12f \uac00\uc9c0 \ud569\uc8fc\uac00 \ubaa8\uc778 \uc774\uc720 \ubc14\ud750\uc758 \ud5cc\uc815 \ubb36\uc74c\uacfc \ub3c5\uc8fc \uadf8\ub8f9\u00b7\ud569\uc8fc\u00b7\uc545\uae30 \uc0c9\ucc44\ub97c \ube44\uad50\ud558\uae30 \ud5cc\uc815\uc758 \ubc30\uacbd\uacfc \uc5ec\uc12f \uace1\uc758 \ud3b8\uc131, \uc81c2\u00b75\u00b76\ubc88\uc758 \uc74c\uc0c9\uc744 \ud1b5\ud574 \uc5ec\ub7ec \ubaa9\uc18c\ub9ac\uc758 \uad00\uacc4\ub97c \ub4e3\uc2b5\ub2c8\ub2e4. \uc74c\uc545 \ubb38\ud654\uc640 \uc608\uc220 \u300e\ube0c\ub780\ub374\ubd80\ub974\ud06c \ud611\uc8fc\uace1\u300f\uc740 \ud55c \uace1\uc774 \uc544\ub2c8\ub77c \ubc14\ud750\uc758 \ud611\uc8fc\uace1 \uc5ec\uc12f \uace1\uc744 \uac00\ub9ac\ud0a8\ub2e4. \uac19\uc740 \uc81c\ubaa9\uc744 \ub2ec\uace0 \uc788\uc9c0\ub9cc \ud3b8\uc131\uacfc \uc74c\uc0c9\uc740 \uc11c\ub85c \ub2e4\ub974\ub2e4. \uc774 \uc74c\uc545\uc744 \ub4e4\uc744 \ub54c\uc5d0\ub294 \uc6c5\uc7a5\ud55c \uad00\ud604\uc545\uc744 \ud55c \ub369\uc5b4\ub9ac\ub85c \ub4e3\uae30\ubcf4\ub2e4 \ub204\uac00 \uc55e\uc73c\ub85c \ub098\uc624\uace0 \ub204\uac00 \ub2e4\ub978 \uc18c\ub9ac\ub97c \ubc1b\uccd0 \uc8fc\ub294\uc9c0 \uadc0\ub97c \uae30\uc6b8\uc5ec \ubcf4\uc790. \uc774 \uc774\ub984\uc740 \ubc14\ud750\uac00 \ube0c\ub780\ub374\ubd80\ub974\ud06c\uc758 \ud06c\ub9ac\uc2a4\ud2f0\uc548 \ub8e8\ud2b8\ube44\ud788 \ubcc0\uacbd\ubc31\uc5d0\uac8c \uc791\ud488\ub4e4\uc744 \ubc14\uce5c \uc77c\uacfc \uc5f0\uacb0\ub41c\ub2e4. 1721\ub144 3\uc6d4 24\uc77c \ub0a0\uc9dc\uc758 \ud5cc\uc815\ubb38\uc774 \uadf8 \uad00\uacc4\ub97c \ubcf4\uc5ec \uc900\ub2e4. \uc74c\uc545\uc758 \uc81c\ubaa9\uc740 \ud48d\uacbd\uc744 \ubb18\uc0ac\ud558\ub294 \ud45c\uc9c0\uac00 \uc544\ub2c8\ub77c \uc791\ud488\uc774 \ub204\uad6c\uc5d0\uac8c \uc804\ub2ec\ub418\uc5c8\ub294\uc9c0\ub97c \uae30\uc5b5\ud558\ub294 \ud45c\uc9c0\uac00 \ub41c \uc148\uc774\ub2e4. \ubc14\ud750\uac00 \uc5ec\uc12f \uace1 \ubaa8\ub450\ub97c \uac19\uc740 \ub0a0 \ucc98\uc74c\ubd80\ud130 \uc0c8\ub85c \uc791\uace1\ud588\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5ec\ub7ec \uc791\uc5c5\uc758 \uacbd\ud5d8\uc774 \ud5cc\uc815 \ubb36\uc74c \uc548\uc5d0 \ubaa8\uc600\ub2e4. \uc791\ud488\uc774 \ub9cc\ub4e4\uc5b4\uc9c4 \uc2dc\uac04\uacfc \uc815\ub9ac\ud574\uc11c \ub204\uad70\uac00\uc5d0\uac8c \uac74\ub128 \uc2dc\uac04\uc774 \uac19\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4\ub294 \uc810\uc740 \uc74c\uc545\uc0ac\ub97c \uc77d\uc744 \ub54c \uc911\uc694\ud558\ub2e4. \ubc14\ud750\ub294 \ub2f9\uc2dc \ucfa8\ud150\uc5d0\uc11c \uad81\uc815 \uc74c\uc545\uc744 \ub9e1\uc558\ub2e4. \uad50\ud68c\uc758 \uc608\ubc30\ub97c \uc704\ud55c \uc791\ud488\ub9cc\uc774 \uc544\ub2c8\ub77c \uc5f0\uc8fc\uc790\ub4e4\uacfc \ud568\uaed8\ud558\ub294 \uae30\uc545 \uc791\uc5c5\uc774 \uc911\uc694\ud55c \ud658\uacbd\uc774\uc5c8\ub2e4. \uc791\uace1\uac00\ub294 \uba38\ub9bf\uc18d\uc758 \uc18c\ub9ac\ub9cc\uc774 \uc544\ub2c8\ub77c \uc2e4\uc81c\ub85c \ub204\uac00 \ubb34\uc5c7\uc744 \uc5f0\uc8fc\ud560 \uc218 \uc788\ub294\uc9c0 \uc0dd\uac01\ud574\uc57c \ud588\ub2e4. \uad81\uc815\uc758 \ucde8\ud5a5\uacfc \uc5f0\uc8fc\uc790\uc758 \ub2a5\ub825, \uc791\ud488\uc744 \ud6c4\uc6d0\ubc1b\ub294 \uad00\uacc4\uac00 \uc74c\uc545\uc758 \ubc14\uae65\uc5d0\ub9cc \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uc545\uae30\ub97c \uc55e\uc5d0 \uc138\uc6b8 \uc218 \uc788\ub294\uac00 \ud558\ub294 \uc120\ud0dd\uc5d0\ub3c4 \uc5f0\uacb0\ub41c\ub2e4. \uc774 \ud611\uc8fc\uace1\ub4e4\uc740 \ud55c \uc0ac\ub78c\uc758 \ucc9c\uc7ac\uc131\ubfd0 \uc544\ub2c8\ub77c \uc5ec\ub7ec \uc5f0\uc8fc\uc790\uac00 \uc18c\ub9ac\ub97c \uc8fc\uace0\ubc1b\uc744 \uc218 \uc788\uc5c8\ub358 \ud658\uacbd\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uc624\ub298\uc758 \ud611\uc8fc\uace1 \ud558\uba74 \ub3c5\uc8fc\uc790 \ud55c \uba85\uacfc \ud070 \uc624\ucf00\uc2a4\ud2b8\ub77c\uac00 \ub9c8\uc8fc \uc120 \ubaa8\uc2b5\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uc774 \uace1\ub4e4\uc5d0\uc11c\ub294 \uc5ec\ub7ec \ub3c5\uc8fc \uc545\uae30\uc640 \ud569\uc8fc\uac00 \ub2e4\uc591\ud55c \uad00\uacc4\ub97c \ub9fa\ub294\ub2e4. \uc791\uc740 \uadf8\ub8f9\uacfc \uc804\uccb4\uac00 \ub300\ube44\ub418\ub294 \ubc14\ub85c\ud06c \ud611\uc8fc\uace1\uc758 \uad00\uc2b5\uc774 \uc911\uc694\ud55c \ucd9c\ubc1c\uc810\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc5ec\uc12f \uace1\uc744 \ub611\uac19\uc740 \uacf5\uc2dd\uc73c\ub85c \ub4e4\uc744 \uc218\ub294 \uc5c6\ub2e4. \uc5b4\ub5a4 \uace1\uc740 \uad00\uc545\uae30\uc758 \ub69c\ub837\ud55c \uc0c9\uc774 \uc55e\uc11c\uace0, \uc5b4\ub5a4 \uace1\uc740 \ud604\uc545\uae30 \uc0ac\uc774\uc758 \uc9dc\uc784\uc774 \uc911\uc2ec\uc774 \ub41c\ub2e4. \uc81c\ubaa9\ubcf4\ub2e4 \uc545\uae30\uc758 \uad6c\uc131\uc744 \uba3c\uc800 \ud655\uc778\ud558\uba74 \uc11c\ub85c \ub2e4\ub978 \uc74c\uc545\uc744 \uac19\uc740 \ubd84\uc704\uae30\ub85c \ubb49\ub6b1\uadf8\ub9ac\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uc791\uc740 \ub3c5\uc8fc \uadf8\ub8f9\uacfc \uc804\uccb4 \ud569\uc8fc\uc758 \ucc28\uc774\ub97c \ucc98\uc74c\ubd80\ud130 \uc804\ubb38 \uc6a9\uc5b4\ub85c \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc0ac\ub78c\uc774 \uc801\uac8c \ub9d0\ud560 \ub54c\uc640 \uc5ec\ub7ff\uc774 \ud568\uaed8 \ub9d0\ud560 \ub54c \uc18c\ub9ac\uc758 \ub450\uaed8\uac00 \uc5b4\ub5bb\uac8c \ub2ec\ub77c\uc9c0\ub294\uc9c0 \ub4e4\uc5b4 \ubcf4\uba74 \ub41c\ub2e4. \uc8fc\uc81c\uac00 \ub3cc\uc544\uc62c \ub54c\ub9c8\ub2e4 \ub204\uac00 \ud568\uaed8 \uc5f0\uc8fc\ud558\ub294\uc9c0 \ud655\uc778\ud558\ub294 \uac04\ub2e8\ud55c \uc9c8\ubb38\uc73c\ub85c \uc74c\uc545\uc758 \uad6c\uc870\uc5d0 \uc811\uadfc\ud560 \uc218 \uc788\ub2e4. \uc5f0\uc8fc\ub97c \uc5ec\ub7ec \ubc88 \ub4e4\uc744 \uc218 \uc788\ub2e4\uba74 \uccab \ubc88\uc9f8\uc5d0\ub294 \ub192\uc740 \uc18c\ub9ac, \ub450 \ubc88\uc9f8\uc5d0\ub294 \ub0ae\uc740 \uc18c\ub9ac\ub97c \ub530\ub77c\uac00 \ubcf4\uc790. \ud55c \ubc88\uc5d0 \ubaa8\ub4e0 \uc131\ubd80\ub97c \uc54c\uc544\ub4e3\uc9c0 \ubabb\ud574\ub3c4 \uad1c\ucc2e\ub2e4. \uc55e\uc5d0\uc11c \ub4e4\uc740 \uc120\uc728\uc774 \ub2e4\ub978 \uc545\uae30\uc758 \uc6c0\uc9c1\uc784\uacfc \uc5b4\ub5a4 \uad00\uacc4\ub97c \ub9fa\ub294\uc9c0 \uc870\uae08\uc529 \ub4dc\ub7ec\ub09c\ub2e4. \ubc18\ubcf5\ud574\uc11c \ub4e3\ub294 \uc2dc\uac04\uc774 \uace1\uc758 \uc9dc\uc784\uc744 \uc54c\uc544\ubcf4\ub294 \ubc29\ubc95\uc774 \ub41c\ub2e4. \uc81c2\ubc88\uc5d0\uc11c\ub294 \ud2b8\ub7fc\ud3ab\uc744 \ube44\ub86f\ud55c \uc11c\ub85c \ub2e4\ub978 \ub3c5\uc8fc \uc545\uae30\ub4e4\uc758 \uc0c9\uc744 \ube44\uad50\ud560 \uc218 \uc788\ub2e4. \ub192\uc740 \uc74c\uc5ed\uc758 \uc120\uba85\ud55c \uc18c\ub9ac\ub294 \ub2e4\ub978 \uc545\uae30\ub4e4 \uc0ac\uc774\uc5d0\uc11c \uc27d\uac8c \ub4dc\ub7ec\ub09c\ub2e4. \ud558\uc9c0\ub9cc \uac00\uc7a5 \uc798 \ub4e4\ub9ac\ub294 \uc545\uae30\ub9cc \ub530\ub77c\uac00\uba74 \uadf8 \uc18c\ub9ac\uac00 \uc26c\ub294 \ub3d9\uc548 \ub2e4\ub978 \uc131\ubd80\uac00 \uc774\uc5b4 \uac00\ub294 \uc6c0\uc9c1\uc784\uc744 \ub193\uce5c\ub2e4. \ud070 \uc18c\ub9ac\uc640 \uc791\uc740 \uc18c\ub9ac\ub97c \ub2e8\uc21c\ud55c \uc6b0\uc5f4\ub85c \ubcf4\uc9c0 \ub9d0\uc790. \uc74c\uc545\uc740 \uc11c\ub85c \ub2e4\ub978 \uc7ac\ub8cc\ub97c \uac19\uc740 \ub192\uc774\ub85c \uce60\ud574 \ubc84\ub9ac\uc9c0 \uc54a\uace0 \ucc28\uc774\ub97c \uc774\uc6a9\ud55c\ub2e4. \ud55c \uc131\ubd80\uac00 \ub0b4\ub193\uc740 \uc6c0\uc9c1\uc784\uc744 \ub2e4\ub978 \uc131\ubd80\uac00 \uc774\uc5b4\ubc1b\ub294 \uc21c\uac04\uc744 \ucc3e\uc73c\uba74, \ud654\ub824\ud568 \uc548\uc5d0\uc11c \uc12c\uc138\ud55c \ub300\ud654\uac00 \ub4e4\ub9ac\uae30 \uc2dc\uc791\ud55c\ub2e4. \uc81c5\ubc88\uc758 \uc911\uc694\ud55c \uc990\uac70\uc6c0\uc740 \ud558\ud504\uc2dc\ucf54\ub4dc\uac00 \ub2e8\uc21c\ud55c \ubc14\ud0d5\uc5d0 \uba38\ubb3c\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc774\ub2e4. \ud50c\ub8e8\ud2b8\uc640 \ubc14\uc774\uc62c\ub9b0, \uac74\ubc18\uc774 \uad00\uacc4\ub97c \uc774\ub8e8\ub294 \uac00\uc6b4\ub370 \uac74\ubc18\uc758 \uc874\uc7ac\uac00 \ud06c\uac8c \ubd80\uac01\ub41c\ub2e4. \uc5ec\ub7ec \uc131\ubd80\ub97c \uc624\uac00\uba70 \ub450\ub4dc\ub7ec\uc9c0\ub294 \uac74\ubc18\uc758 \uc6c0\uc9c1\uc784\uc5d0 \uc9d1\uc911\ud558\uba74 \uadf8 \ubcc0\ud654\ub97c \ub290\ub084 \uc218 \uc788\ub2e4. \ud3c9\uc18c \ub2e4\ub978 \uc545\uae30\ub97c \ubc1b\uccd0 \uc900\ub2e4\uace0 \uc0dd\uac01\ud588\ub358 \uc18c\ub9ac\uac00 \uac11\uc790\uae30 \ubb34\ub300\uc758 \uc911\uc2ec\uc744 \ucc28\uc9c0\ud558\uba74 \uc775\uc219\ud55c \uc5ed\ud560\uc758 \uad6c\ubd84\ub3c4 \ud754\ub4e4\ub9b0\ub2e4. \ud604\ub300 \ud53c\uc544\ub178 \ud611\uc8fc\uace1\uacfc \uac19\uc740 \uac83\uc73c\ub85c \ubd80\ub974\uae30\ubcf4\ub2e4, \uc774 \uc791\ud488 \uc548\uc5d0\uc11c \uac74\ubc18\uc774 \ub9e1\ub294 \uad6c\uccb4\uc801\uc778 \uc77c\uc744 \ub4e4\uc5b4 \ubcf4\ub294 \ud3b8\uc774 \ud765\ubbf8\ub86d\ub2e4. \uc81c6\ubc88\uc740 \ub192\uc740 \ubc14\uc774\uc62c\ub9b0 \uc18c\ub9ac\uac00 \uc5c6\ub294 \ud604\uc545 \ud3b8\uc131\uc73c\ub85c \ub2e4\ub978 \uc0c9\uc744 \ub9cc\ub4e0\ub2e4. \ube44\uc62c\ub77c\uc640 \ube44\uc62c\ub77c \ub2e4 \uac10\ubc14 \ub4f1 \ub0ae\uace0 \uc911\uac04 \uc74c\uc5ed\uc758 \uc545\uae30\ub4e4\uc774 \uc5b4\uc6b8\ub9b0\ub2e4. \uc545\uae30 \ud558\ub098\ub97c \ube7c\ub294 \uc120\ud0dd\ub3c4 \uc0c8\ub85c\uc6b4 \uc545\uae30\ub97c \ub354\ud558\ub294 \uac83\ub9cc\ud07c \uc804\uccb4\uc758 \ubd84\uc704\uae30\ub97c \ubc14\uafc0 \uc218 \uc788\ub2e4. \ub298 \ub9e8 \uc55e\uc5d0 \uc788\uc744 \uac83 \uac19\uc740 \ubaa9\uc18c\ub9ac\uac00 \ube60\uc9c0\uba74 \ub2e4\ub978 \uc18c\ub9ac\uc758 \uacb0\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \uc81c2\ubc88\uc758 \ubc1d\uace0 \uc120\uba85\ud55c \uc778\uc0c1\uacfc \uc81c6\ubc88\uc758 \uc9c8\uac10\uc744 \ub098\ub780\ud788 \ub4e4\uc5b4 \ubcf4\uc790. \uace1\uc5d0 \ub300\ud55c \uc88b\uace0 \uc2eb\uc74c\uc758 \ud310\ub2e8\uc744 \uc7a0\uc2dc \ubbf8\ub8e8\uace0 \uc5b4\ub5a4 \uc18c\ub9ac\uc758 \uc870\ud569\uc774 \uadf8\ub7f0 \uc778\uc0c1\uc744 \ub9cc\ub4dc\ub294\uc9c0 \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \ubcc0\uacbd\ubc31\uc5d0\uac8c \uc545\ubcf4\uac00 \uc804\ub2ec\ub418\uc5c8\ub2e4\uace0 \uadf8\uacf3\uc5d0\uc11c \uc5b4\ub5a4 \uc5f0\uc8fc\uac00 \uc774\ub8e8\uc5b4\uc84c\ub294\uc9c0\uae4c\uc9c0 \ubaa8\ub450 \ud655\uc2e4\ud574\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ub798\ub41c \uc804\uae30\ub4e4\uc5d0\ub3c4 \uc218\uc2e0\uc778\uc758 \ubc18\uc751\uacfc \uc5f0\uc8fc \uc5ec\ubd80\uc5d0 \ub300\ud55c \ube48\uce78\uc774 \ub0a8\uc544 \uc788\ub2e4. \uc911\uc694\ud55c \ubb38\uc11c\uac00 \ub0a8\uc558\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ubaa8\ub4e0 \uc0ac\uc815\uc744 \uc54c \uc218 \uc788\ub2e4\ub294 \ud310\ub2e8\uc740 \ub2e4\ub974\ub2e4. \uc624\ub298 \uc6b0\ub9ac\ub294 \uadf8 \ube48\uce78\uc744 \uc9c0\ub098 \uc5ec\uc12f \uace1\uc744 \uc5f0\uc774\uc5b4 \ub4e4\uc744 \uc218 \uc788\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc81c2\ubc88\u00b7\uc81c5\ubc88\u00b7\uc81c6\ubc88\ucc98\ub7fc \uc74c\uc0c9 \ucc28\uc774\uac00 \ud070 \uace1\uc744 \ube44\uad50\ud558\uace0, \ub2e4\uc74c\uc5d0\ub294 \ud55c \uace1 \uc548\uc5d0\uc11c \ubaa9\uc18c\ub9ac\uac00 \uad50\ub300\ud558\ub294 \uc21c\uac04\uc744 \ucc3e\uc544\ubcf4\uba74 \uc88b\ub2e4. \uc81c\ubaa9\uc744 \uc678\uc6b4 \ub2e4\uc74c\uc758 \uac10\uc0c1\uc774 \uc545\uae30\ub4e4\uc774 \uad00\uacc4 \ub9fa\ub294 \ubc29\uc2dd\uc744 \ub4e3\ub294 \uacbd\ud5d8\uc73c\ub85c \ub113\uc5b4\uc9c4\ub2e4."}, {"id": "bahia-palace-courtyards-water-and-craft", "title": "\ubc14\ud788\uc544 \uad81\uc804 \u2014 \ub730\uc744 \uc9c0\ub098\uba70 \ub2ec\ub77c\uc9c0\ub294 \ube5b\uacfc \uad8c\ub825", "summary": "\ub730\uacfc \ubb3c, \uc7a5\uc778\uc758 \uc7ac\ub8cc\uc640 \ucd9c\uc785\uc758 \uacbd\uacc4\ub97c \uc5ec\ud589\uc790\uc758 \uc2dc\uc120\uacfc \uad6c\ubd84\ud558\uba70 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uac74\ucd95", "categories": ["arts"], "url": "stories/bahia-palace-courtyards-water-and-craft/index.html", "image": "../media/bahia-palace-courtyards-water-and-craft.jpg", "alt": "\ub9c8\ub77c\ucf00\uc2dc \ubc14\ud788\uc544 \uad81\uc804\uc758 \ud070 \ub730\uacfc \uc8fc\ubcc0 \uac74\ubb3c\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc2e4\uc81c \uc5ed\uc0ac \uc0ac\uc9c4", "text": "\ubc14\ud788\uc544 \uad81\uc804 \u2014 \ub730\uc744 \uc9c0\ub098\uba70 \ub2ec\ub77c\uc9c0\ub294 \ube5b\uacfc \uad8c\ub825 \uc6cc\ud134\uc758 \uc5ec\ud589\uae30\uc640 \uc5ed\uc0ac \uc0ac\uc9c4\uc73c\ub85c \uc77d\ub294 \ub9c8\ub77c\ucf00\uc2dc\uc758 \uad81\uc804 \ub730\uacfc \ubb3c, \uc7a5\uc778\uc758 \uc7ac\ub8cc\uc640 \ucd9c\uc785\uc758 \uacbd\uacc4\ub97c \uc5ec\ud589\uc790\uc758 \uc2dc\uc120\uacfc \uad6c\ubd84\ud558\uba70 \uc77d\uc2b5\ub2c8\ub2e4. \uac74\ucd95 \ubb38\ud654\uc640 \uc608\uc220 \ub9c8\ub77c\ucf00\uc2dc\uc758 \ubc14\ud788\uc544 \uad81\uc804\uc740 \ub192\uc740 \ud0d1 \ud558\ub098\ub85c \uc2dc\uc120\uc744 \ub044\ub294 \uac74\ucd95\uacfc \ub2e4\ub974\ub2e4. \ub730\uacfc \ubc29, \uc881\uc740 \ud1b5\ub85c\uc640 \uc815\uc6d0\uc744 \uc9c0\ub098\uba70 \uc7a5\uba74\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ubb38\ud559\uac00 \uc774\ub514\uc2a4 \uc6cc\ud134\uc774 \ub0a8\uae34 20\uc138\uae30 \ucd08 \uc5ec\ud589\uae30\uc640 \uc5ed\uc0ac \uc0ac\uc9c4\uc744 \ubc14\ud0d5\uc73c\ub85c, \uc544\ub984\ub2e4\uc6b4 \uc7a5\uc2dd \uc548\uc5d0 \uacf5\uac04\uc758 \uc0ac\uc6a9\uacfc \uad8c\ub825\uc758 \uc2dc\uac04\uc774 \uc5b4\ub5bb\uac8c \ud568\uaed8 \ub193\uc600\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \ubc14\ud788\uc544\uc5d0\uc11c\ub294 \ubc14\uae65\uc5d0\uc11c \ubaa8\ub4e0 \uacf5\uac04\uc774 \ud55c\uaebc\ubc88\uc5d0 \ub4dc\ub7ec\ub098\uc9c0 \uc54a\ub294\ub2e4. \ub9c8\ub2f9\uc5d0\uc11c \ub2e4\ub978 \ub9c8\ub2f9\uc73c\ub85c \uac00\uace0 \ub0ae\uc740 \ud1b5\ub85c\ub97c \uc9c0\ub098 \uc548\ucabd\uc758 \ubc29\uc744 \ub9cc\ub09c\ub2e4. \ub204\uad70\uac00\uc5d0\uac8c\ub294 \uae38\uac8c \uc774\uc5b4\uc9c4 \uc544\ub984\ub2e4\uc6b4 \ub3d9\uc120\uc774\uc9c0\ub9cc, \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc27d\uac8c \uc811\uadfc\ud560 \uc218 \uc5c6\ub294 \uacbd\uacc4\uc758 \uc5f0\uc18d\uc774\uc5c8\uc744 \uac83\uc774\ub2e4. \uc655\uad81\uc774\ub77c\ub294 \ub9d0\ub85c \ubb49\ub6b1\uadf8\ub9ac\uae30\ubcf4\ub2e4 \uace0\uc704 \uad8c\ub825\uc790\uc758 \uac70\ucc98\uc640 \uc811\uacac, \uac00\uc871\uc0dd\ud65c\uacfc \uc2e4\ubb34\uac00 \uc5bd\ud78c \ubcf5\ud569 \uacf5\uac04\uc73c\ub85c \uc774\ud574\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc5b4\ub290 \ubc29\uc774\ub4e0 \uac19\uc740 \uc6a9\ub3c4\ub85c \uc4f0\uc600\ub358 \uac83\ub3c4, \ub204\uad6c\ub098 \uac19\uc740 \uae38\ub85c \ub4e4\uc5b4\uac08 \uc218 \uc788\uc5c8\ub358 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \ubc14\ud788\uc544\uc758 \ud615\uc131\uacfc \ud655\uc7a5\uc740 19\uc138\uae30 \ud6c4\ubc18\uc758 \uad8c\ub825\uc790 \uc2dc \ubb34\uc0ac\uc640 \uadf8 \uc544\ub4e4 \ubc14 \uc544\ud750\uba54\ub4dc\uc758 \uc2dc\ub300\uc640 \uc5f0\uacb0\ub41c\ub2e4. \ud2b9\ud788 \ubc14 \uc544\ud750\uba54\ub4dc\ub294 \uad81\uc804\uc758 \uaddc\ubaa8\uc640 \uc7a5\uc2dd\uc744 \ud06c\uac8c \ud0a4\uc6b4 \uc778\ubb3c\ub85c \uc54c\ub824\uc84c\ub2e4. \uc9c0\uae08\uc758 \ubaa8\uc2b5\uc744 \ud55c \ubc88\uc758 \uacf5\uc0ac\ub85c \uc124\uba85\ud558\uae30\ubcf4\ub2e4 \uc774\uc5b4\uc9c4 \uc870\uc131 \uacfc\uc815\uc73c\ub85c \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc6cc\ud134\uc740 \ud398\uc2a4\uc5d0\uc11c \uc628 \uc219\ub828\ub41c \uc7a5\uc778\ub4e4\uc774 \uad81\uc804\uc5d0 \ucc38\uc5ec\ud588\ub2e4\uace0 \uae30\ub85d\ud588\ub2e4. \uad8c\ub825\uc790\uc758 \uc774\ub984\uc740 \ub0a8\uae30 \uc26c\uc6cc\ub3c4 \ud68c\ubcbd\uacfc \ud0c0\uc77c, \ub098\ubb34\ub97c \ub2e4\ub8ec \uc218\ub9ce\uc740 \uc0ac\ub78c\uc740 \uac1c\ubcc4 \uc774\ub984\uc774 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ud654\ub824\ud55c \uac74\ubb3c\uc758 \uc81c\uc791\uc790\ub97c \uc8fc\ubb38\uc790 \ud55c \uc0ac\ub78c\uc73c\ub85c\ub9cc \uc124\uba85\ud560 \uc218 \uc5c6\ub294 \uc774\uc720\ub2e4. \ud070 \ub730\uacfc \uc548\ucabd\uc758 \uc791\uc740 \ub730\uc740 \ub2e8\uc21c\ud788 \ud06c\uae30\uac00 \ub2e4\ub978 \ubcf5\uc81c\ud488\uc774 \uc544\ub2c8\ub2e4. \uc8fc\uc704\ub97c \ub458\ub7ec\uc2fc \ubc29\uc758 \uc218\uc640 \ubb38, \uc678\ubd80\uc5d0\uc11c \uc811\uadfc\ud558\ub294 \uae38\uc774 \ub2e4\ub974\uba74 \uadf8\uacf3\uc5d0\uc11c \ub9cc\ub098\ub294 \uc0ac\ub78c\uacfc \ud65c\ub3d9\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uacf5\uac04\uc744 \ube44\uad50\ud560 \ub54c \ub113\uc774\ub9cc \ubcf4\uc9c0 \ub9d0\uc544\uc57c \ud558\ub294 \uc774\uc720\ub2e4. \ubcbd \uc544\ub798\ucabd\uc758 \ud0c0\uc77c\uacfc \uadf8 \uc704\uc758 \uc12c\uc138\ud55c \ud68c\ubcbd \uc7a5\uc2dd, \ubb38\uacfc \ucc9c\uc7a5\uc758 \ubaa9\uc7ac\ub294 \uc11c\ub85c \ub2e4\ub978 \uc7ac\ub8cc\uc758 \uc9c8\uac10\uc744 \ub9cc\ub4e0\ub2e4. \uac00\uae4c\uc774\uc5d0\uc11c \uc77d\ub294 \uc791\uc740 \ubb34\ub2ac\uac00 \ubc18\ubcf5\ub418\uace0 \uba40\ub9ac\uc11c\ub294 \ud558\ub098\uc758 \ub113\uc740 \ub760\ub098 \uba74\uc73c\ub85c \ubb36\uc778\ub2e4. \uc7a5\uc2dd\uc740 \uc0ac\ubb3c \ud558\ub098\ubcf4\ub2e4 \ud45c\uba74 \uc804\uccb4\uc758 \uad00\uacc4\ub85c \uc791\ub3d9\ud55c\ub2e4. \uc0ac\uc9c4\uc744 \ubcfc \ub54c\uc5d0\ub294 \ubb34\ub2ac \uc774\ub984\uc744 \uba3c\uc800 \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc7ac\ub8cc\uac00 \uc5b4\ub514\uc5d0\uc11c \ubc14\ub00c\ub294\uc9c0 \ucc3e\uc544\ubcf4\uc790. \uc0ac\ub78c\uc774 \uac00\uae4c\uc774 \ub2e4\uac00\uac08 \ubd80\ubd84\uacfc \uc704\ub97c \uc62c\ub824\ub2e4\ubcfc \ubd80\ubd84\uc758 \ucc98\ub9ac\uac00 \ub2e4\ub978\uc9c0\ub3c4 \ubcfc \uc218 \uc788\ub2e4. \uc7a5\uc2dd\uc758 \ud48d\ubd80\ud568\uc744 \uadf8\uc800 \ube48\ud2c8\uc5c6\uc774 \ucc44\uc6e0\ub2e4\ub294 \ud45c\ud604\uc73c\ub85c \ub05d\ub0b4\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uc6cc\ud134\uc758 \uae30\ub85d\uc5d0\ub294 \ubd84\uc218\uc640 \ubb3c\uae38, \ub098\ubb34\uc640 \uadf8\ub298\uc774 \uc790\uc8fc \ub4f1\uc7a5\ud55c\ub2e4. \ubb3c\uc740 \uc6c0\uc9c1\uc774\ub294 \uc18c\ub9ac\ub97c \ub9cc\ub4e4\uace0 \ub730\uacfc \ubc29\uc758 \uad00\uacc4\ub97c \ub290\ub07c\uac8c \ud558\ub294 \uc694\uc18c\ub2e4. \ub354\uc6b4 \ubc14\uae65\uc5d0\uc11c \uc5b4\ub450\uc6b4 \uc548\ucabd\uc73c\ub85c \ub4e4\uc5b4\uac08 \ub54c \ub2ec\ub77c\uc9c0\ub294 \uac10\uac01\ub3c4 \uc5ec\ud589\uae30\uc5d0 \uac15\ud558\uac8c \ub0a8\uc544 \uc788\ub2e4. \ub2e4\ub9cc \ubd84\uc218\uac00 \uc788\ub2e4\uace0 \ubaa8\ub4e0 \uacf5\uac04\uc774 \uac19\uc740 \uc628\ub3c4\ub97c \uc720\uc9c0\ud588\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uac74\ucd95\uc758 \ubc29\ud5a5\uacfc \ud1b5\ud48d, \uacc4\uc808\uacfc \uc0ac\uc6a9 \ubc29\uc2dd\uc774 \ud568\uaed8 \uc791\uc6a9\ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \uc544\ub984\ub2e4\uc6c0\uc5d0 \ub354\ud574 \ube5b\uacfc \uc18c\ub9ac, \uc628\ub3c4\uc758 \uacbd\ud5d8\uc744 \uc0c1\uc0c1\ud558\ub418 \uc2e4\uc81c \uce21\uc815\ucc98\ub7fc \ub9d0\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\ub2e4. \uc5ec\ud589\uae30 \uc18d \uac10\ud0c4\uc740 \ub3c5\uc790\uc758 \uc2dc\uc120\uc744 \ud2b9\uc815\ud55c \ubc29\ud5a5\uc73c\ub85c \uc548\ub0b4\ud55c\ub2e4. \ubd84\uc218\uc640 \ud5a5\uae30, \ube5b\uc744 \uc544\ub984\ub2f5\uac8c \ubb18\uc0ac\ud560\uc218\ub85d \uad81\uc804\uc758 \uc6b4\uc601\uacfc \ub178\ub3d9\uc740 \ubc30\uacbd\uc73c\ub85c \ubb3c\ub7ec\ub0a0 \uc218 \uc788\ub2e4. \uac19\uc740 \ubb38\uc7a5\uc5d0\uc11c \ubb34\uc5c7\uc774 \uc790\uc138\ud788 \ubcf4\uc774\uace0 \ubb34\uc5c7\uc774 \uc774\ub984 \uc5c6\uc774 \ub0a8\ub294\uc9c0 \ucc3e\uc544\ubcf4\ub294 \uac83\ub3c4 \ub3c5\uc11c\uc758 \ud55c \ubc29\ubc95\uc774\ub2e4. \uc548\ucabd\uc5d0 \ubc30\uce58\ub41c \uacf5\uac04\uc740 \uc2dc\uc120\uc744 \ud53c\ud558\uace0 \uc0ac\uc0dd\ud65c\uc744 \uc9c0\ucf1c \uc8fc\ub294 \ub3d9\uc2dc\uc5d0 \ucd9c\uc785\uc744 \uc81c\ud55c\ud560 \uc218 \uc788\ub2e4. \uc6cc\ud134\uc740 \uc5b4\ub5a4 \ubc29\uc744 \uc544\ub984\ub2e4\uc6b4 \uac10\uc625\uc5d0 \ube44\uc720\ud588\ub2e4. \uadf8\ub7ec\ub098 \uadf8\uac83\uc740 \ud2b9\uc815 \uc704\uce58\uc5d0\uc11c \ubcf8 \uc678\ubd80 \uc5ec\ud589\uc790\uc758 \ubb38\ud559\uc801 \ud574\uc11d\uc774\uae30\ub3c4 \ud558\ub2e4. \uadf8 \ud45c\ud604\ub9cc\uc73c\ub85c \uad81\uc804\uc5d0 \uc0b4\uc558\ub358 \ubaa8\ub4e0 \uc5ec\uc131\uc758 \uacbd\ud5d8\uc744 \ub611\uac19\uc774 \uc124\uba85\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uac00\uc871\uacfc \uc0ac\uc6a9\uc778, \uad8c\ub825\uc790\uc640 \uc190\ub2d8\uc758 \uc774\ub3d9 \uc870\uac74\uc740 \ub2ec\ub790\uc744 \uac83\uc774\ub2e4. \ubc29\uc774 \uc544\ub984\ub2e4\uc6b4\uc9c0 \ubb3b\ub294 \ub370\uc11c \uba48\ucd94\uc9c0 \uc54a\uace0 \ub204\uac00 \ubb34\uc5c7\uc744 \uacb0\uc815\ud558\uba70 \ub4dc\ub098\ub4e4\uc5c8\ub294\uc9c0\ub97c \ubb3b\ub294 \ud3b8\uc774 \ub354 \uae4a\uc740 \uac74\ucd95 \uc77d\uae30\uac00 \ub41c\ub2e4. \uc6cc\ud134\uc774 \ubaa8\ub85c\ucf54\ub97c \uc5ec\ud589\ud55c 1917\ub144\uc740 \ud504\ub791\uc2a4 \ubcf4\ud638\ub839 \uc2dc\uae30\uc600\ub2e4. \uadf8\ub140\ub294 \uc2dd\ubbfc \ud1b5\uce58 \ub2f9\uad6d\uc758 \uc9c0\uc6d0\uc744 \ubc1b\uc558\uace0 \uad81\uc804 \uacf5\uac04\uc5d0 \uba38\ubb3c \uc218 \uc788\uc5c8\ub2e4. \uc5ec\ud589\uae30\uc5d0 \ub4f1\uc7a5\ud558\ub294 \uc811\uadfc\uc758 \uc790\uc720\ub294 \ub2f9\uc2dc \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \ub611\uac19\uc774 \ub204\ub9b0 \uc870\uac74\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uadf8\ub140\ub294 \uc7a5\uc2dd\uacfc \uac74\ucd95\uc744 \uc608\ubbfc\ud558\uac8c \uad00\ucc30\ud558\uc9c0\ub9cc \ubaa8\ub85c\ucf54\uc778\uacfc \uc544\ud504\ub9ac\uce74\uc5d0 \ub300\ud55c \ud3b8\uacac\ub3c4 \uae00\uc5d0 \ub2f4\uc558\ub2e4. \uc138\ubc00\ud55c \uad00\ucc30\uacfc \ubd80\ub2f9\ud55c \uc77c\ubc18\ud654\ub294 \ud55c \uc800\uc790 \uc548\uc5d0 \ud568\uaed8 \uc788\uc744 \uc218 \uc788\ub2e4. \ucc45\uc744 \uc790\ub8cc\ub85c \uc4f4\ub2e4\ub294 \uac83\uc740 \uadf8 \ud310\ub2e8 \uc804\uccb4\ub97c \uc624\ub298\uc758 \ud574\uc124\ub85c \uc2b9\uc778\ud55c\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \ubc29\uc774 \ube44\uc5b4 \uc788\ub294 \ud604\uc7ac\uc758 \uc0ac\uc9c4\ub9cc\uc73c\ub85c \uacfc\uac70 \uac70\uc8fc\uc790\uc758 \uc131\uaca9\uacfc \uad00\uacc4\ub97c \ubcf5\uc6d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uac74\ucd95\uc774 \ubcf4\uc5ec \uc8fc\ub294 \uacbd\uacc4\uc640 \ubb38\ud5cc\uc774 \uc804\ud558\ub294 \uc0ac\uc6a9, \uc800\uc790\uac00 \uc0c1\uc0c1\ud55c \ubd84\uc704\uae30\ub97c \ub098\ub204\uc5b4 \ubcf4\uba74 \ubaa8\ub974\ub294 \ubd80\ubd84\ub3c4 \ubd84\uba85\ud574\uc9c4\ub2e4. \uadf8 \uad6c\ubd84\uc740 \uac10\uc0c1\uc758 \uc5ec\uc9c0\ub97c \uc904\uc774\uae30\ubcf4\ub2e4 \uadfc\uac70\ub97c \ub354 \ub2e8\ub2e8\ud558\uac8c \ub9cc\ub4e0\ub2e4. \uc774 \uae00\uc5d0 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uc6cc\ud134\uc758 \ucc45\uc5d0 \uc218\ub85d\ub41c \ubc14\ud788\uc544 \uad81\uc804 \ud070 \ub730\uc758 \uc2e4\uc81c \uc5ed\uc0ac \uc0ac\uc9c4\uc774\ub2e4. \ub2f9\uc2dc \uc0ac\uc9c4\uac00 \ud3a0\ub9ad\uc2a4\uc758 \uc774\ub984\uc774 \ucd9c\ucc98\uc5d0 \uc801\ud600 \uc788\ub2e4. \ud751\ubc31 \ud654\uba74\uc774\ubbc0\ub85c \ud604\uc7ac \ud604\uc7a5\uc758 \uc0c9\uacfc \ubcf4\uc874 \uc0c1\ud0dc\ub97c \uadf8\ub300\ub85c \ubcf4\uc5ec \uc8fc\ub294 \uc0ac\uc9c4\uacfc \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ub110\ucc0d\ud55c \ub730\uc744 \ubcf8 \ub4a4\uc5d0\ub294 \uc8fc\ubcc0 \ubb38\uc774 \uc5b4\ub290 \uacf5\uac04\uc73c\ub85c \uc774\uc5b4\uc9c8\uc9c0, \uadf8\ub298\uc758 \ud3ed\uc774 \uc5bc\ub9c8\ub098 \ub2ec\ub77c\uc9c8\uc9c0 \uc0dd\uac01\ud574 \ubcf4\uc790. \ubc14\ud788\uc544\ub294 \uc7a5\uc2dd\uc758 \ubaa9\ub85d\uc744 \ubaa8\uc740 \uc7a5\uc18c\ubcf4\ub2e4 \uc5ec\ub7ec \uacbd\uacc4\ub97c \ud1b5\uacfc\ud558\uba70 \uacbd\ud5d8\ud558\ub294 \uac74\ucd95\uc774\ub2e4. \uadf8 \uc548\uc5d0\uc11c\ub294 \uc7a5\uc778\uc758 \uc190, \uac70\uc8fc\uc790\uc758 \uc0dd\ud65c, \uad8c\ub825\uc758 \ud5c8\uac00\uac00 \uc11c\ub85c \ub2e4\ub978 \ud754\uc801\uc744 \ub0a8\uae34\ub2e4."}, {"id": "barber-seville-figaro-letters-disguises", "title": "\u300e\uc138\ube44\uc57c\uc758 \uc774\ubc1c\uc0ac\u300f \u2014 \ud53c\uac00\ub85c\ub294 \uc65c \uc774\ub807\uac8c \ubc14\uc060\uae4c", "summary": "\ub85c\uc2dc\ub2c8\uc758 \ud76c\uadf9\uc5d0\uc11c \ud53c\uac00\ub85c\u00b7\ub85c\uc9c0\ub098\u00b7\uc54c\ub9c8\ube44\ubc14\uac00 \uafb8\ubbf8\ub294 \uc791\uc804\uacfc \ub300\ud45c \uc544\ub9ac\uc544\ub97c \uc18c\uac1c\ud569\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc74c\uc545", "categories": ["arts"], "url": "stories/barber-seville-figaro-letters-disguises/index.html", "image": "../media/barber-seville-figaro-letters-disguises.png", "alt": "\ubc1c\ucf54\ub2c8\uc758 \ud3b8\uc9c0\ub97c \ub4e0 \ub85c\uc9c0\ub098\uc640 \uc544\ub798\uc758 \uc774\ubc1c\uc0ac\u00b7\ubcc0\uc7a5\ud55c \uad6c\ud63c\uc790\ub97c \uadf8\ub9b0 \uc0c1\uc0c1 \uc624\ud398\ub77c \uc7a5\uba74", "text": "\u300e\uc138\ube44\uc57c\uc758 \uc774\ubc1c\uc0ac\u300f \u2014 \ud53c\uac00\ub85c\ub294 \uc65c \uc774\ub807\uac8c \ubc14\uc060\uae4c \ud3b8\uc9c0\uc640 \ubcc0\uc7a5, \uc218\ub2e4\uc640 \ub178\ub798\uac00 \uc9d1\uc758 \ubb38\uc744 \uc5ec\ub294 \ubc29\ubc95 \ub85c\uc2dc\ub2c8\uc758 \ud76c\uadf9\uc5d0\uc11c \ud53c\uac00\ub85c\u00b7\ub85c\uc9c0\ub098\u00b7\uc54c\ub9c8\ube44\ubc14\uac00 \uafb8\ubbf8\ub294 \uc791\uc804\uacfc \ub300\ud45c \uc544\ub9ac\uc544\ub97c \uc18c\uac1c\ud569\ub2c8\ub2e4. \uc74c\uc545 \ubb38\ud654\uc640 \uc608\uc220 \ud53c\uac00\ub85c, \ud53c\uac00\ub85c, \ud53c\uac00\ub85c. \ube60\ub974\uac8c \uc790\uae30 \uc774\ub984\uc744 \uc678\uce58\ub294 \ub178\ub798\ub97c \ub4e3\ub2e4 \ubcf4\uba74 \uc774 \uc0ac\ub78c\uc774 \uc65c \uadf8\ub807\uac8c \uc720\uba85\ud55c\uc9c0 \uad81\uae08\ud574\uc9c4\ub2e4. \u300e\uc138\ube44\uc57c\uc758 \uc774\ubc1c\uc0ac\u300f\uc758 \ud53c\uac00\ub85c\ub294 \uba38\ub9ac\ub9cc \uc190\uc9c8\ud558\ub294 \uc0ac\ub78c\uc774 \uc544\ub2c8\ub2e4. \ub3d9\ub124\uc758 \uc18c\uc2dd\uacfc \uc0ac\ub78c\ub4e4\uc758 \uc0ac\uc815\uc744 \uc54c\uace0, \ub9c9\ud78c \uad00\uacc4\ub97c \ub6ab\uc5b4 \uc8fc\ub294 \ubc14\uc05c \ud574\uacb0\uc0ac\ub2e4. \ub85c\uc2dc\ub2c8\uc758 \uc624\ud398\ub77c\ub294 \ubcf4\ub9c8\ub974\uc170\uc758 \ud76c\uadf9\uc744 \ubc14\ud0d5\uc73c\ub85c \uccb4\uc0ac\ub808 \uc2a4\ud14c\ub974\ube44\ub2c8\uac00 \uc4f4 \ub300\ubcf8\uc5d0 \uc74c\uc545\uc744 \ubd99\uc778 \uc791\ud488\uc774\ub2e4. 1816\ub144 \ub85c\ub9c8\uc5d0\uc11c \ucc98\uc74c \ubb34\ub300\uc5d0 \uc62c\ub790\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \uacb0\ud63c\uc5d0 \uc774\ub974\ub294 \uacb0\ub9d0\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubcf8\ub2e4. \uc6c3\uc74c\uc740 \uc74c\uc545\uc758 \uc18d\ub3c4\ubfd0 \uc544\ub2c8\ub77c \ub204\uac00 \ubb34\uc5c7\uc744 \uc54c\uace0 \uc788\ub294\uc9c0\uc5d0\uc11c \uc0dd\uae34\ub2e4. \uc54c\ub9c8\ube44\ubc14 \ubc31\uc791\uc740 \ub85c\uc9c0\ub098\ub97c \uc0ac\ub791\ud55c\ub2e4. \ud558\uc9c0\ub9cc \uadf8\ub140\uc5d0\uac8c \uc790\uc2e0\uc758 \uc2e0\ubd84\uc744 \uba3c\uc800 \ub0b4\uc138\uc6b0\uc9c0 \uc54a\uace0 \ub9b0\ub3c4\ub85c\ub77c\ub294 \uc774\ub984\uc73c\ub85c \uc811\uadfc\ud55c\ub2e4. \ub192\uc740 \uc9c0\uc704\uac00 \uc544\ub2c8\ub77c \uc790\uc2e0\uc744 \uc88b\uc544\ud558\ub294\uc9c0 \uc54c\uace0 \uc2f6\ub2e4\ub294 \ub9c8\uc74c\uc774\ub2e4. \uadf8\uac00 \ubd80\ub974\ub294 \uc138\ub808\ub098\ub370\ub294 \ubc1c\ucf54\ub2c8 \uc548\ucabd\uc758 \uc0ac\ub78c\uc5d0\uac8c \ub2e4\uac00\uac00\ub824\ub294 \uccab \uc2dc\ub3c4\ub2e4. \uadf8\ub7f0\ub370 \ub85c\uc9c0\ub098\ub97c \ubcf4\ud638\ud55c\ub2e4\ub294 \ubc14\ub974\ud1a8\ub85c\ub294 \uadf8\ub140\uc640 \uc790\uc2e0\uc774 \uacb0\ud63c\ud558\ub824 \ud55c\ub2e4. \uc9d1 \uc548\uc73c\ub85c \ub4e4\uc5b4\uac08 \uae38\uc774 \ub9c9\ud600 \uc788\uc73c\ub2c8 \ub178\ub798\ub9cc\uc73c\ub85c\ub294 \uc77c\uc774 \ud480\ub9ac\uc9c0 \uc54a\ub294\ub2e4. \uc5ec\uae30\uc5d0\uc11c \ud53c\uac00\ub85c\uac00 \ub4f1\uc7a5\ud55c\ub2e4. \uc5f0\uc778\uc758 \ub9c8\uc74c\ubfd0 \uc544\ub2c8\ub77c \uc9d1\uc758 \uad6c\uc870\uc640 \ubcf4\ud638\uc790\uc758 \uc2b5\uad00\uc744 \uc544\ub294 \uc0ac\ub78c\uc774 \ud544\uc694\ud574\uc9c4 \uac83\uc774\ub2e4. \u300c\ub098\ub294 \uc774 \uac70\ub9ac\uc758 \ub9cc\ub2a5 \uc77c\uafbc\u300d\uc73c\ub85c \uc54c\ub824\uc9c4 \ud53c\uac00\ub85c\uc758 \uc544\ub9ac\uc544\ub294 \uadf8\uac00 \uc5bc\ub9c8\ub098 \ubd88\ub824 \ub2e4\ub2c8\ub294\uc9c0 \uc3df\uc544\ub0b8\ub2e4. \ub9d0\uc744 \ube68\ub9ac \ub9ce\uc774 \ud558\ub294 \ub370\uc5d0\ub9cc \ub9e4\ub825\uc774 \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc800\uae30\uc11c \ucc3e\ub294 \uc0ac\ub78c\uc774 \ub418\uc5b4 \uc790\uae30 \ub2a5\ub825\uc744 \uc790\ub791\ud558\ub294 \uae30\uc138\uac00 \ub178\ub798\uc5d0 \ub4e4\uc5b4 \uc788\ub2e4. \ud53c\uac00\ub85c\ub77c\ub294 \uc774\ub984\uc774 \ubc18\ubcf5\ub420\uc218\ub85d \ub3d9\ub124 \uc804\uccb4\uac00 \uadf8\ub97c \ubd80\ub974\ub294 \uac83\ucc98\ub7fc \ub4e4\ub9b0\ub2e4. \ub4e3\ub294 \uc0ac\ub78c\ub3c4 \uadf8 \ud65c\ub825\uc5d0 \ub04c\ub824\uac04\ub2e4. \uadc0\uc871\uc758 \uc6b0\uc544\ud55c \uc0ac\ub791 \ub178\ub798\uc640 \ub2e4\ub978 \uc5d0\ub108\uc9c0\uac00 \ubb34\ub300\ub97c \ucc44\uc6b4\ub2e4. \ud53c\uac00\ub85c\ub294 \uc0c1\ub300\uc758 \uc2e0\ubd84\ubcf4\ub2e4 \uc2e4\ubb34\uc640 \ubcf4\uc0c1\uc5d0 \ubbfc\uac10\ud558\uace0, \ud070 \uac10\uc815\uc744 \uad6c\uccb4\uc801\uc778 \uacc4\ud68d\uc73c\ub85c \ubc14\uafbc\ub2e4. \ud3b8\uc9c0\ub97c \ub204\uad6c\uc5d0\uac8c \uc804\ud558\uace0 \uc5b4\ub290 \uc21c\uac04 \ubb38\uc744 \uc5f4 \uac83\uc778\uc9c0\uac00 \uadf8\uc758 \uc601\uc5ed\uc774\ub2e4. \ub85c\uc9c0\ub098\uac00 \ubd80\ub974\ub294 \u300c\ubc29\uae08 \ub4e4\ub9b0 \uadf8 \ubaa9\uc18c\ub9ac\u300d\ub294 \uc0ac\ub791\uc5d0 \ub9c8\uc74c\uc774 \uc6c0\uc9c1\uc778 \ub178\ub798\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \uc548\uc5d0\ub294 \uc790\uae30 \ub73b\uc744 \uc774\ub8e8\ub824\ub294 \ub2e8\ub2e8\ud568\ub3c4 \uc788\ub2e4. \ub0a8\ub4e4\uc774 \ubcf4\ud638\ud574\uc57c \ud560 \uc21c\ud55c \uc0ac\ub78c\uc73c\ub85c\ub9cc \ubcf4\ub824 \ud574\ub3c4 \uadf8\ub140\uc5d0\uac8c\ub294 \ud310\ub2e8\uacfc \uc791\uc804\uc774 \uc788\ub2e4. \uc7a5\uc2dd\uc801\uc778 \uc74c\ub4e4\uc774 \ubc18\uc9dd\uc774\ub294 \ub3d9\uc548 \uc131\uaca9\ub3c4 \ud568\uaed8 \ub4dc\ub7ec\ub09c\ub2e4. \uadf8\ub140\ub294 \ud3b8\uc9c0\ub97c \uc4f0\uace0 \uc0c1\ud669\uc744 \uc0b4\ud540\ub2e4. \uc9d1\uc5d0 \uac07\ud600 \uc788\ub294 \uc704\uce58\uc640 \ub9c8\uc74c\uae4c\uc9c0 \uc218\ub3d9\uc801\uc778 \uac83\uc740 \ub2e4\ub974\ub2e4. \ud53c\uac00\ub85c\uc758 \ub3c4\uc6c0\uc740 \uc911\uc694\ud558\uc9c0\ub9cc, \ubaa8\ub4e0 \uacc4\ud68d\uc744 \ubc16\uc758 \ub0a8\uc790\ub4e4\uc774 \uc815\ud574 \uc8fc\uace0 \ub85c\uc9c0\ub098\ub294 \ub9c8\uc9c0\ub9c9\uc5d0 \uac10\uc0ac\ub9cc \ud558\ub294 \uc774\uc57c\uae30\ub294 \uc544\ub2c8\ub2e4. \ub204\uac00 \ub204\uad6c\ub97c \uc18d\uc774\uace0 \uc788\ub294\uc9c0 \uc0b4\ud53c\uba74 \uadf8\ub140\ub3c4 \ud76c\uadf9\uc758 \uc6c0\uc9c1\uc784\uc744 \ub9cc\ub4dc\ub294 \uc0ac\ub78c\uc774\ub2e4. \ubc14\ub974\ud1a8\ub85c\uc758 \ud3b8\uc5d0 \uc120 \uc74c\uc545 \uad50\uc0ac \ubc14\uc9c8\ub9ac\uc624\ub294 \uc911\uc0c1\ubaa8\ub7b5\uc744 \uc81c\uc548\ud55c\ub2e4. \u300c\uc18c\ubb38\uc740 \ubbf8\ud48d\ucc98\ub7fc\u300d\uc73c\ub85c \uc54c\ub824\uc9c4 \uc544\ub9ac\uc544\uc5d0\uc11c\ub294 \uc791\uc740 \ub9d0\uc774 \uc810\uc810 \ucee4\uc9c0\ub294 \ubaa8\uc2b5\uc744 \uc74c\uc545\uc774 \ubcf4\uc5ec \uc900\ub2e4. \ucc98\uc74c\uc758 \uc870\uc2ec\uc2a4\ub7ec\uc6b4 \uc6c0\uc9c1\uc784\uc774 \ub098\uc911\uc5d0\ub294 \ud798 \uc788\ub294 \uc18c\ub9ac\ub85c \ubd88\uc5b4\ub09c\ub2e4. \ub208\uc5d0 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc18c\ubb38\uc774 \ud06c\uae30\uc640 \ubb34\uac8c\ub97c \uc5bb\ub294 \uc148\uc774\ub2e4. \ub0b4\uc6a9\uc744 \ubaa8\ub450 \uc54c\uc544\ub4e3\uc9c0 \ubabb\ud574\ub3c4 \ubcc0\ud654\ub294 \uadc0\ub85c \ub290\ub084 \uc218 \uc788\ub2e4. \uc74c\uc545\uc774 \ub9d0\uc758 \ub73b\uc744 \uc124\uba85\ud558\ub294 \ub3d9\uc2dc\uc5d0 \ud589\ub3d9\uc744 \ud749\ub0b4 \ub0b8\ub2e4. \ud76c\uadf9 \uc18d \uc74c\ubaa8\uac00 \uc6b0\uc2b5\uac8c \ub4e4\ub9ac\uc9c0\ub9cc, \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \ub9d0\uc774 \ubc18\ubcf5\ub418\uba70 \uc0ac\ub78c\uc744 \ubab0\uc544\uac00\ub294 \ubaa8\uc2b5\uc740 \ub0af\uc124\uc9c0 \uc54a\ub2e4. \ud55c \uc544\ub9ac\uc544 \uc548\uc5d0 \uc778\ubb3c\uc758 \uc131\uaca9\uacfc \uc0ac\ud68c\uc801\uc778 \uad00\ucc30\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ubc31\uc791\uc740 \uc220 \ucde8\ud55c \uad70\uc778\uc73c\ub85c \ubcc0\uc7a5\ud574 \uc9d1 \uc548\uc73c\ub85c \ub4e4\uc5b4\uac00\ub824 \ud55c\ub2e4. \ubc14\ub974\ud1a8\ub85c\uc640 \uc2e4\ub791\uc774\uac00 \ubc8c\uc5b4\uc9c0\uace0 \uc0c1\ud669\uc740 \uc18c\ub780\uc2a4\ub7ec\uc6cc\uc9c4\ub2e4. \uacbd\ube44\uae4c\uc9c0 \ub4f1\uc7a5\ud558\uba74\uc11c \ube44\ubc00\uc2a4\ub7ec\uc6b4 \uad6c\uc560\ub294 \ud1b5\uc81c\ud558\uae30 \uc5b4\ub824\uc6b4 \uc7a5\uba74\uc73c\ub85c \ubcc0\ud55c\ub2e4. \ud53c\uac00\ub85c\uc758 \uacc4\ud68d\uc740 \ub2a5\uc219\ud574 \ubcf4\uc5ec\ub3c4 \ub298 \uae54\ub054\ud558\uac8c \uc791\ub3d9\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc774 \uc7a5\uba74\uc5d0\uc11c \uad00\uac1d\uc758 \uc990\uac70\uc6c0\uc740 \uc778\ubb3c\ub4e4\ubcf4\ub2e4 \ub354 \ub9ce\uc774 \uc54c\uace0 \uc788\ub2e4\ub294 \ub370 \uc788\ub2e4. \ub204\uac00 \ubc31\uc791\uc778\uc9c0 \uc544\ub294 \uad00\uac1d\uc740 \ubc14\ub974\ud1a8\ub85c\uac00 \uc9d0\uc791\ud558\ub294 \uc0ac\uc815\uacfc \uc2e4\uc81c \uc0c1\ud669\uc758 \uac04\uaca9\uc744 \ubcf8\ub2e4. \uc5ec\ub7ec \uc0ac\ub78c\uc774 \uc81c\uac01\uae30 \ub2e4\ub978 \uc0dd\uac01\uc73c\ub85c \ub178\ub798\ud560 \ub54c \uc74c\uc545\uc740 \uadf8 \ud63c\ub780\uc744 \ud769\uc5b4 \ub193\uc9c0 \uc54a\uace0 \ud55c\ub370 \ubb36\ub294\ub2e4. \ub9d0\uc774 \ud1b5\ud558\uc9c0 \uc54a\ub294 \uc21c\uac04\uc774 \uc624\ud788\ub824 \uc815\uad50\ud55c \ud569\uc8fc\uac00 \ub41c\ub2e4. \ub450 \ubc88\uc9f8 \uc791\uc804\uc5d0\uc11c \ubc31\uc791\uc740 \ubc14\uc9c8\ub9ac\uc624 \ub300\uc2e0 \uc654\ub2e4\ub294 \uc74c\uc545 \uad50\uc0ac\ub85c \ubcc0\uc7a5\ud55c\ub2e4. \uc218\uc5c5\uc774\ub77c\ub294 \ud551\uacc4\uac00 \uc0dd\uae30\uc790 \ub85c\uc9c0\ub098\uc640 \uac00\uae4c\uc774 \uc788\uc744 \uc218 \uc788\ub2e4. \uc0ac\ub791\uc758 \ub300\ud654\ub97c \ud558\ub824\uba74 \uba3c\uc800 \uadf8 \uc9d1\uc5d0\uc11c \uc815\ub2f9\ud574 \ubcf4\uc774\ub294 \uc5ed\ud560\uc744 \uc5bb\uc5b4\uc57c \ud55c\ub2e4. \uc55e\uc120 \uad70\uc778\uc758 \ud798\ubcf4\ub2e4 \uc774\ubc88\uc5d0\ub294 \uadf8\ub7f4\ub4ef\ud55c \uc124\uba85\uc774 \ubb38\uc744 \uc5f0\ub2e4. \uadf8\ub7f0\ub370 \uc544\ud504\ub2e4\ub358 \uc9c4\uc9dc \ubc14\uc9c8\ub9ac\uc624\uac00 \ub098\ud0c0\ub098\uba74 \uacc4\ud68d\uc740 \ud754\ub4e4\ub9b0\ub2e4. \ubaa8\ub974\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \ubc29\ubb38\uc774 \ube44\ubc00\uc744 \uc544\ub294 \uc0ac\ub78c\ub4e4\uc5d0\uac8c\ub294 \ube44\uc0c1\uc0ac\ud0dc\ub2e4. \uac19\uc740 \uc5bc\uad74 \ud558\ub098\ub97c \ubcf4\uace0 \ubaa8\ub450\uc758 \ubc18\uc751\uc774 \ub2ec\ub77c\uc9c0\ub294 \uac83\ub9cc\uc73c\ub85c \ubb34\ub300\ub294 \uc6c3\uc74c\uc744 \ub9cc\ub4e0\ub2e4. \uc74c\ubaa8\uac00 \uac70\ucc3d\ud574\uc11c\uac00 \uc544\ub2c8\ub77c \uc815\ubcf4\uc758 \ubc30\uce58\uac00 \uc815\ud655\ud574\uc11c \uc7ac\ubbf8\uc788\ub294 \uc7a5\uba74\uc774\ub2e4. \ubc14\ub974\ud1a8\ub85c\ub294 \ub85c\uc9c0\ub098\uac00 \uc4f4 \ud3b8\uc9c0\ub97c \uc774\uc6a9\ud574 \uadf8\ub140\uc758 \uc9c8\ud22c\uc640 \uc758\uc2ec\uc744 \uc790\uadf9\ud55c\ub2e4. \ub85c\uc9c0\ub098\ub294 \ub9b0\ub3c4\ub85c\uc5d0\uac8c \uc18d\uc558\ub2e4\uace0 \ubbff\uac8c \ub41c\ub2e4. \uc9c4\uc2ec\uc744 \uc804\ud558\ub824\ub358 \uc885\uc774\uac00 \ub2e4\ub978 \uc124\uba85\uacfc \ud568\uaed8 \ub193\uc774\uc790 \uc0c1\ucc98\uc758 \uc99d\uac70\ucc98\ub7fc \uc77d\ud78c\ub2e4. \ud3b8\uc9c0\uc758 \ub0b4\uc6a9\ub9cc\ud07c \ub204\uac00 \ubb34\uc2a8 \ub9d0\uc744 \ubd99\uc5ec \uac74\ub124\ub294\uc9c0\ub3c4 \uc911\uc694\ud574\uc9c4\ub2e4. \uc774\ud6c4 \ubc31\uc791\uacfc \ud53c\uac00\ub85c\uac00 \ub2e4\uc2dc \ub098\ud0c0\ub098\uba74\uc11c \uc624\ud574\uac00 \ud480\ub9ac\uace0, \ub9b0\ub3c4\ub85c\uc758 \uc2e0\ubd84\ub3c4 \ubc1d\ud600\uc9c4\ub2e4. \uc900\ube44\ub41c \uacf5\uc99d\uc778\uacfc \uc99d\uc778\ub4e4\uc774 \uacb0\ud63c\uc744 \uac00\ub2a5\ud558\uac8c \ud55c\ub2e4. \ubc14\ub974\ud1a8\ub85c\uac00 \ubb38\uc744 \uc7a0\uadf8\uace0 \uac10\uc2dc\ud574\ub3c4 \uc0ac\ub78c\ub4e4 \uc0ac\uc774\uc758 \ud611\ub825\uacfc \uc815\ubcf4\uc758 \uc774\ub3d9\uc744 \ubaa8\ub450 \ub9c9\uc9c0\ub294 \ubabb\ud588\ub2e4. \uc81c\ubaa9\uc758 \uc774\ubc1c\uc0ac\uac00 \ubc14\ube74\ub358 \uc774\uc720\uac00 \ub9c8\uc9c0\ub9c9\uae4c\uc9c0 \uc774\uc5b4\uc9c4\ub2e4. \uc791\ud488\uc740 \uc5f0\uc778\ub4e4\uc758 \uacb0\ud569\uc73c\ub85c \ub05d\ub098\uc9c0\ub9cc, \uadc0\uc871\uc774 \uc2e0\ubd84\uc744 \uac10\ucd94\uace0 \uc0ac\ub78c\uc744 \uc2dc\ud5d8\ud558\ub294 \ubc29\uc2dd\uae4c\uc9c0 \uc624\ub298\uc758 \ub208\uc5d0 \ubaa8\ub450 \ud3b8\uc548\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc18c\uc720\uc640 \uacb0\ud63c\uc744 \ub2f9\uc5f0\ud558\uac8c \uc5f0\uacb0\ud558\ub294 \ubcf4\ud638\uc790\uc758 \ud0dc\ub3c4 \uc5ed\uc2dc \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \ud76c\uadf9\uc744 \uc990\uae34\ub2e4\uace0 \ub4f1\uc7a5\uc778\ubb3c\uc758 \ubaa8\ub4e0 \uacc4\ud68d\uc5d0 \ub3d9\uc758\ud574\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub798\ub3c4 \ud53c\uac00\ub85c\uc758 \uccab \uc544\ub9ac\uc544\uac00 \ub2e4\uc2dc \ub4e4\ub9ac\uba74 \uadf8\uc758 \ubc14\uc068\uc744 \uc870\uae08 \ub354 \uc774\ud574\ud558\uac8c \ub41c\ub2e4. \uc774 \uc774\uc57c\uae30\uc5d0\uc11c \uc0ac\ub791\uc740 \ub9c8\uc74c\ub9cc\uc73c\ub85c \uc9d1\uc744 \ud1b5\uacfc\ud558\uc9c0 \ubabb\ud55c\ub2e4. \ud3b8\uc9c0\ub97c \uc804\ud558\uace0 \uc2dc\uac04\uc744 \ub9de\ucd94\uace0 \uc0ac\ub78c\uc744 \uc124\ub4dd\ud558\ub294 \uad6c\uccb4\uc801\uc778 \uc77c\uc774 \ud544\uc694\ud558\ub2e4. \ub85c\uc2dc\ub2c8\uc758 \uc74c\uc545\uc740 \ubc14\ub85c \uadf8 \uc77c\ub4e4\uc744 \ube60\ub974\uace0 \ubc18\uc9dd\uc774\ub294 \uc18c\ub3d9\uc73c\ub85c \ubc14\uafb8\uc5b4 \ub193\uc558\ub2e4."}, {"id": "bayeux-embroidery-comet-and-story", "title": "\ubc14\uc774\uc678 \uc790\uc218 \u2014 \ud558\ub298\uc758 \uae34 \uaf2c\ub9ac\ub97c \uc0ac\ub78c\ub4e4\uc774 \uac00\ub9ac\ud0a8 \uc774\uc720", "summary": "\ud61c\uc131\uc744 \uac00\ub9ac\ud0a4\ub294 \uc7a5\uba74\uc5d0\uc11c \ubc14\uc774\uc678 \uc790\uc218\uc758 \uc5f0\uc18d \uc11c\uc0ac\uc640 \uc2b9\uc790\uc758 \uad00\uc810, \uc0dd\ud65c\uc758 \uc138\ubd80\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/bayeux-embroidery-comet-and-story/index.html", "image": "../media/bayeux-embroidery-comet-and-story.jpg", "alt": "\ud61c\uc131\uc744 \uac00\ub9ac\ud0a4\ub294 \uc0ac\ub78c\ub4e4\uacfc \ud574\ub7f4\ub4dc\uc758 \ubaa8\uc2b5\uc774 \uc788\ub294 \ubc14\uc774\uc678 \uc790\uc218 \ud328\ub110\uc758 \uc61b \uc0c9\ucc44 \ubcf5\uc81c", "text": "\ubc14\uc774\uc678 \uc790\uc218 \u2014 \ud558\ub298\uc758 \uae34 \uaf2c\ub9ac\ub97c \uc0ac\ub78c\ub4e4\uc774 \uac00\ub9ac\ud0a8 \uc774\uc720 1066\ub144\uc758 \uc815\ubcf5 \uc774\uc57c\uae30\ub97c \uc2e4\ub85c \uc774\uc5b4 \ub193\uc740 \uae34 \ud654\uba74 \ud61c\uc131\uc744 \uac00\ub9ac\ud0a4\ub294 \uc7a5\uba74\uc5d0\uc11c \ubc14\uc774\uc678 \uc790\uc218\uc758 \uc5f0\uc18d \uc11c\uc0ac\uc640 \uc2b9\uc790\uc758 \uad00\uc810, \uc0dd\ud65c\uc758 \uc138\ubd80\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \ud55c \ubb34\ub9ac\uc758 \uc0ac\ub78c\ub4e4\uc774 \ud558\ub298\uc744 \uc62c\ub824\ub2e4\ubcf8\ub2e4. \uc190\uac00\ub77d\uc774 \ud5a5\ud55c \uacf3\uc5d0\ub294 \uae34 \uaf2c\ub9ac\ub97c \ub2e8 \ubcc4 \uac19\uc740 \uac83\uc774 \uc788\ub2e4. \uadf8 \uc606\uc5d0\ub294 \uc655\uc758 \uc774\ub984\uacfc \ubc30\uc758 \ubaa8\uc2b5\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ubc14\uc774\uc678 \uc790\uc218 \uc18d\uc5d0\uc11c \ud61c\uc131\uc740 \ud48d\uacbd\uc758 \uc791\uc740 \uc7a5\uc2dd\uc774 \uc544\ub2c8\ub77c \uc0ac\ub78c\ub4e4\uc758 \uad00\uc2ec\uc744 \ubd99\ub4dc\ub294 \uc0ac\uac74\uc774\ub2e4. \uc624\ub298\ub0a0 \ud504\ub791\uc2a4 \ubc14\uc774\uc678\uc5d0 \uc804\ud558\ub294 \uc774 \uae34 \uc791\ud488\uc740 1066\ub144 \uc789\uae00\ub79c\ub4dc \uc815\ubcf5\uacfc \uadf8 \uc55e\uc758 \uc77c\uc744 \uadf8\ub9bc\uacfc \uae00\ub85c \uc5ee\ub294\ub2e4. \uc720\uba85\ud55c \uc804\ud22c\ub9cc \ucc3e\uc9c0 \ub9d0\uace0 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub514\ub97c \ubcf4\uace0 \ubb34\uc5c7\uc744 \ud558\ub294\uc9c0 \ub530\ub77c\uac00\uba74 \uc624\ub798\ub41c \ud654\uba74\uc774 \uc870\uae08\uc529 \uc6c0\uc9c1\uc774\uae30 \uc2dc\uc791\ud55c\ub2e4. \ud754\ud788 \ubc14\uc774\uc678 \ud0dc\ud53c\uc2a4\ud2b8\ub9ac\ub77c\uace0 \ubd80\ub974\uc9c0\ub9cc \uadf8\ub9bc\uc740 \ucc9c\uc744 \uc9dc\uba74\uc11c \ub9cc\ub4e0 \ubb34\ub2ac\uac00 \uc544\ub2c8\ub77c \ubc14\ud0d5\ucc9c \uc704\uc5d0 \uc2e4\ub85c \uc218\ub193\uc740 \uac83\uc774\ub2e4. \uc774\ub984\uc774 \uc775\uc219\ud558\ub2e4\uace0 \uc81c\uc791 \ubc29\uc2dd\uae4c\uc9c0 \uac19\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2e4\uc758 \uc120\uc774 \uc778\ubb3c\uc758 \ubab8\uacfc \ub9d0, \ubc30\uc640 \uac74\ubb3c\uc744 \ub9cc\ub4e0\ub2e4. \ud070 \uc7a5\uba74\uc740 \uac00\ub85c \ubc29\ud5a5\uc73c\ub85c \uc774\uc5b4\uc9c0\uace0 \uc704\uc544\ub798\uc5d0\ub294 \uc881\uc740 \ub760\uac00 \ubd99\ub294\ub2e4. \uad00\uac1d\uc740 \ud55c\ub208\uc5d0 \uc804\ubd80 \ubcf4\uae30\ubcf4\ub2e4 \uc2dc\uc120\uc744 \uc62e\uae30\uba70 \uc55e\ub4a4\ub97c \uc5f0\uacb0\ud55c\ub2e4. \ud55c \uc7a5\uc758 \ucd08\uc0c1\ud654\uc640 \ub2ec\ub9ac \uc2dc\uac04\uc744 \uae38\uac8c \ud3bc\uccd0 \ub193\uc740 \ud654\uba74\uc774\ub2e4. \uc791\ud488\uc758 \uc911\uc2ec\uc5d0\ub294 \uc789\uae00\ub79c\ub4dc\uc758 \ud574\ub7f4\ub4dc\uc640 \ub178\ub974\ub9dd\ub514\uc758 \uc70c\ub9ac\uc5c4\uc774 \uc788\ub2e4. \uc5d0\ub4dc\uc6cc\ub4dc \uc655\uc758 \uc8fd\uc74c \ub4a4 \ub204\uac00 \uc655\uc704\ub97c \ucc28\uc9c0\ud560 \uac83\uc778\uac00\ub97c \ub458\ub7ec\uc2fc \uac08\ub4f1\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ud574\ub7f4\ub4dc\uac00 \uc655\uc774 \ub418\uace0 \uc70c\ub9ac\uc5c4\uc774 \ubc14\ub2e4\ub97c \uac74\ub108\uc624\ub294 \uacfc\uc815\uc774 \uc804\ud22c\ub85c \ud5a5\ud55c\ub2e4. \uc774 \uc774\uc57c\uae30\ub294 \uc5b4\ub290 \ub204\uad6c\uc5d0\uac8c\ub3c4 \uc18d\ud558\uc9c0 \uc54a\uc740 \uc911\ub9bd\uc801\uc778 \uc911\uacc4\uac00 \uc544\ub2c8\ub2e4. \uc57d\uc18d\uacfc \uc655\uc704, \uc815\ubcf5\uc758 \uc815\ub2f9\uc131\uc744 \ubcf4\ub294 \uad00\uc810\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ud654\uba74\uc774 \ubb34\uc5c7\uc744 \uac15\uc870\ud558\uace0 \ubb34\uc5c7\uc744 \uc0dd\ub7b5\ud588\ub294\uc9c0 \uc0b4\ud53c\uba74 \uadf8\ub9bc\uc744 \uc5ed\uc0ac \uc790\ub8cc\ub85c \uc77d\ub294 \uc7ac\ubbf8\uac00 \ucee4\uc9c4\ub2e4. \uc778\ubb3c\uacfc \uc0ac\uac74 \uc704\uc5d0\ub294 \uc9e7\uc740 \ub77c\ud2f4\uc5b4 \uae00\uc774 \ubd99\uc5b4 \uc788\ub2e4. \uc774\ub984\uc744 \uc54c\ub824 \uc8fc\uac70\ub098 \ubb34\uc5c7\uc774 \uc77c\uc5b4\ub098\ub294\uc9c0 \uc694\uc57d\ud55c\ub2e4. \uc624\ub298\ub0a0\uc758 \ub9cc\ud654\uc640 \uaf2d \uac19\uc740 \ud615\uc2dd\uc740 \uc544\ub2c8\uc9c0\ub9cc \uae00\uacfc \uc5f0\uc18d \uadf8\ub9bc\uc774 \uc11c\ub85c\ub97c \ub3d5\ub294 \ubc29\uc2dd\uc740 \uce5c\uc219\ud558\uac8c \ub290\uaef4\uc9c4\ub2e4. \uadf8\ub9bc\ub9cc \ubcf4\uba74 \ub204\uac00 \ub204\uad6c\uc778\uc9c0 \ub193\uce58\uae30 \uc27d\uace0 \uae00\ub9cc \uc77d\uc73c\uba74 \ubab8\uc9d3\uacfc \ubb3c\uac74\uc758 \ud48d\ubd80\ud568\uc744 \uc783\ub294\ub2e4. \ub450 \uc694\uc18c\ub97c \ubc88\uac08\uc544 \uc0b4\ud53c\ub294 \uac83\uc774 \uc88b\ub2e4. \uc190\uc9d3\uacfc \uc2dc\uc120\uc774 \ub2e4\uc74c \uc7a5\uba74\uc744 \ud5a5\ud558\uac8c \ud558\uace0 \uc9e7\uc740 \ubb38\uc7a5\uc774 \uadf8 \ud750\ub984\uc744 \ubd99\uc7a1\ub294\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc790\ub8cc\uc758 \uc67c\ucabd\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc740 \ud61c\uc131\uc744 \uac00\ub9ac\ud0a8\ub2e4. \uc624\ub978\ucabd\uc5d0\ub294 \ud574\ub7f4\ub4dc\uc758 \uc774\ub984\uacfc \uc655\uc88c\uc758 \uc778\ubb3c\uc774 \ubcf4\uc778\ub2e4. 1066\ub144\uc5d0 \ub098\ud0c0\ub09c \ud61c\uc131\uc744 \uc815\uce58\uc801 \uc0ac\uac74\uc758 \ud750\ub984 \uc18d\uc5d0 \ub123\uc740 \uc7a5\uba74\uc774\ub2e4. \ud558\ub298\uc758 \uc77c\uacfc \ub545\uc758 \uad8c\ub825\uc774 \uac19\uc740 \ub760\uc5d0 \ub193\uc778\ub2e4. \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uc774\ub7f0 \ud604\uc0c1\uc740 \ubd88\uc548\ud55c \uc9d5\uc870\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \ud61c\uc131\uc774 \uc2e4\uc81c\ub85c \ub204\uad6c\uc758 \ud328\ubc30\ub97c \uc608\uace0\ud588\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uc791\ud488\uc774 \uadf8 \ud604\uc0c1\uc744 \uc5b4\ub5a4 \uc0ac\uac74 \uc606\uc5d0 \ub193\uc544 \uc758\ubbf8\ub97c \ub9cc\ub4e4\uc5c8\ub290\ub0d0\ub2e4. \uc815\ubcf5\uc744 \uc900\ube44\ud558\ub294 \uc7a5\uba74\uc5d0\ub294 \ubc30\ub97c \ub9cc\ub4e4\uace0 \ubb3c\uc790\ub97c \uc62e\uae30\ub294 \uc77c\uc774 \ub098\uc628\ub2e4. \uc804\uc7c1\uc758 \uc2b9\ud328\ub97c \uc655\uacfc \uc6a9\ub9f9\ud55c \uae30\uc0ac\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uba74 \ube60\uc9c0\uae30 \uc26c\uc6b4 \ub178\ub3d9\uc774\ub2e4. \uc0ac\ub78c\uacfc \ub9d0\uc774 \uc6c0\uc9c1\uc774\ub824\uba74 \uc218\uc1a1\uacfc \uc74c\uc2dd, \uc7a5\ube44\uac00 \ud544\uc694\ud588\ub2e4. \uce7c\uc744 \uc950\uace0 \uc2f8\uc6b0\ub294 \uc21c\uac04\ubcf4\ub2e4 \uc774\ub7f0 \uc900\ube44 \uc7a5\uba74\uc744 \ucc9c\ucc9c\ud788 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \ub204\uac00 \ub098\ubb34\ub97c \ub2e4\ub8e8\uace0 \ub204\uac00 \uc9d0\uc744 \ub098\ub974\ub294\uc9c0 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc815\ubcf5\uc758 \ud070 \uc774\uc57c\uae30\uac00 \uc2e4\uc81c \ubb3c\uac74\uacfc \uc218\ub9ce\uc740 \uc190\uc744 \ud1b5\ud574 \uc774\ub8e8\uc5b4\uc84c\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc74c\uc2dd\uc744 \uc900\ube44\ud558\uace0 \ud568\uaed8 \uba39\ub294 \uc7a5\uba74\uc740 \uc791\ud488\uc758 \ud65c\uae30\ub97c \ub9cc\ub4e0\ub2e4. \uc804\ud22c\ub97c \uc55e\ub454 \uc0ac\ub78c\ub4e4\uc774 \uba39\uace0 \ub9c8\uc2dc\uba70 \uc790\ub9ac\ub97c \uc7a1\ub294\ub2e4. \uc774\ub4e4\uc5d0\uac8c\ub3c4 \ubc30\uace0\ud514\uacfc \ud734\uc2dd, \uc5ed\ud560\uc758 \ucc28\uc774\uac00 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ud654\uba74\uc5d0 \ub0a8\uc544 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \uadf8\ub9bc \ud558\ub098\ub85c \ub2f9\uc2dc \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \uc2dd\uc0dd\ud65c\uc744 \ubcf5\uc6d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc120\ud0dd\ub41c \uc7a5\uba74\uc774\uba70 \uc11c\uc0ac\uc758 \ubaa9\uc801\uc744 \uac16\ub294\ub2e4. \ub2e4\ub9cc \ubb34\uae30\uc640 \uac11\uc637\ub9cc \ubcf4\ub358 \ub208\uc744 \uadf8\ub987\uacfc \uc74c\uc2dd, \uc0ac\ub78c\ub4e4\uc758 \ubc30\uce58\ub85c \uc62e\uae30\uba74 \ub2e4\ub978 \uc885\ub958\uc758 \uc5ed\uc0ac\uac00 \ub098\ud0c0\ub09c\ub2e4. \ud5e4\uc774\uc2a4\ud305\uc2a4 \uc804\ud22c\uc640 \ud574\ub7f4\ub4dc\uc758 \ucd5c\ud6c4\ub294 \uc774 \uc791\ud488\uc744 \uc720\uba85\ud558\uac8c \ub9cc\ub4e0 \ubd80\ubd84\uc774\ub2e4. \uadf8\ub7ec\ub098 \uc791\uc740 \ud615\uc0c1 \ud558\ub098\ub97c \ud2b9\uc815 \uc778\ubb3c\uc758 \uc815\ud655\ud55c \uc8fd\uc74c \uc21c\uac04\uc73c\ub85c \ub2e8\uc815\ud560 \ub54c\uc5d0\ub294 \uc870\uc2ec\ud574\uc57c \ud55c\ub2e4. \uc624\ub798 \uc804\ud574 \uc628 \uc124\uba85\uacfc \ud654\uba74\uc5d0\uc11c \ud655\uc778\ub418\ub294 \uac83\uc740 \ud56d\uc0c1 \uc77c\uce58\ud558\uc9c0 \uc54a\ub294\ub2e4. \ubcf4\uc218\uc640 \uc804\uc2b9\uc758 \uacfc\uc815, \ud568\uaed8 \uc77d\ub294 \ub2e4\ub978 \uae30\ub85d\ub3c4 \ud574\uc11d\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4. \uad81\uae08\ud55c \ubd80\ubd84\uc744 \uace7\ubc14\ub85c \uc815\ub2f5\uc73c\ub85c \ucc44\uc6b0\uae30\ubcf4\ub2e4 \uc5b4\ub5a4 \uadfc\uac70\ub85c \uadf8\ub807\uac8c \ubcf4\ub294\uc9c0 \ubb3b\ub294 \ud3b8\uc774 \uc88b\ub2e4. \ubaa8\ud638\ud55c \uc9c0\uc810\uc774 \ub0a8\uc544 \uc788\uc5b4\ub3c4 \uc791\ud488\uc758 \ud798\uc740 \uc904\uc9c0 \uc54a\ub294\ub2e4. \uc774 \uae00\uc5d0 \uc2e4\uc740 \uac83\uc740 \ud790\ub808\uc5b4 \ubca8\ub85d\uc758 1914\ub144 \ucc45\uc5d0 \uc218\ub85d\ub41c \uc0c9\ucc44 \ubcf5\uc81c \ub3c4\ud310\uc774\ub2e4. \uc6d0\ub798 \uc790\uc218\ub97c \uc624\ub298 \ucd2c\uc601\ud55c \uc0ac\uc9c4\uc774 \uc544\ub2c8\ub2e4. \ud61c\uc131 \uc7a5\uba74\uc744 \uc77d\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub418\uc9c0\ub9cc \uc2e4\uc758 \uc9c8\uac10\uacfc \uc2e4\uc81c \uc0c9\uc744 \uc9c1\uc811 \ubcf4\ub294 \uacbd\ud5d8\uae4c\uc9c0 \ub300\uc2e0\ud558\uc9c0\ub294 \ubabb\ud55c\ub2e4. \ubca8\ub85d\uc758 \ud574\uc124 \uc5ed\uc2dc \ud6c4\ub300\uc758 \ud574\uc11d\uc774\ub2e4. \uc791\ud488\uc758 \uc81c\uc791 \uc2dc\uae30\ub97c \ub2a6\uac8c \uc7a1\uc740 \uacac\ud574\ub098 \ucc9c\ubb38 \ud604\uc0c1\uc5d0 \ub300\ud55c \uadf8\uc758 \ud310\ub2e8\uae4c\uc9c0 \uc624\ub298\uc758 \uacb0\ub860\uc73c\ub85c \ucc44\ud0dd\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc624\ub798\ub41c \ub3c4\ud310\uacfc \uc624\ub798\ub41c \ud574\uc124\uc744 \uac01\uac01\uc758 \uc790\ub8cc\ub85c \uad6c\ubd84\ud558\uba70 \uc0ac\uc6a9\ud588\ub2e4. \ubc14\uc774\uc678 \uc790\uc218\ub97c \ubcfc \ub54c \ucc98\uc74c\uc5d0\ub294 \uc655\uacfc \uc804\ud22c\uc758 \uc21c\uc11c\ub97c \ub530\ub77c\uac00 \ubcf4\uc790. \ub2e4\uc74c\uc5d0\ub294 \uc190\uac00\ub77d\uacfc \ub9d0\uc758 \ub2e4\ub9ac, \ubc25\uc744 \uc900\ube44\ud558\ub294 \uc0ac\ub78c, \ubc30\ub97c \ub2e4\ub8e8\ub294 \uc0ac\ub78c\uc744 \ucc3e\uc544\ubcf4\uba74 \uc88b\ub2e4. \uac19\uc740 \uc774\uc57c\uae30 \uc548\uc5d0\uc11c \uc2dc\uc120\uc744 \uc62e\uae38 \ub54c\ub9c8\ub2e4 \ub2e4\ub978 \uc2dc\uac04\uc774 \uc5f4\ub9b0\ub2e4. \ucc9c \uc704\uc758 \uae34 \ud589\ub82c\uc740 \uc2b9\uc790\uc758 \uae30\uc5b5\uc744 \uc804\ud558\uba74\uc11c \uadf8 \uae30\uc5b5\uc744 \ub9cc\ub4e4\uae30 \uc704\ud574 \uc120\ud0dd\ud55c \uc0dd\ud65c\uc758 \uc138\ubd80\ub3c4 \ub0a8\uacbc\ub2e4. \ud61c\uc131\uc744 \ud5a5\ud55c \uc190\uac00\ub77d \ud558\ub098\ub294 \uadf8 \uc138\uacc4\uc758 \ubd88\uc548\uacfc \uad00\uc2ec\uc744 \uc624\ub298\uc758 \ub208\uc55e\uc73c\ub85c \ub04c\uc5b4\uc628\ub2e4. \ud070 \uc0ac\uac74\uc744 \uc791\uc740 \ubab8\uc9d3\uc73c\ub85c \uc77d\uac8c \ud558\ub294 \uc791\ud488\uc774\ub2e4."}, {"id": "beethoven-fifth-four-notes", "title": "\ubca0\ud1a0\ubca4 \uad50\ud5a5\uace1 \uc81c5\ubc88 \u2014 \ub124 \uc74c\uc740 \uc5b4\ub5bb\uac8c \uae34 \uc774\uc57c\uae30\uac00 \ub420\uae4c", "summary": "\uc9e7\uc740 \uc74c\ud615\uc758 \ubc18\ubcf5\uacfc \ubcc0\ud654, \ub9c8\uc9c0\ub9c9 \uc545\uc7a5\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \ud750\ub984\uc744 \uc2e4\uc81c \uc545\ubcf4\uc640 \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc74c\uc545", "categories": ["arts"], "url": "stories/beethoven-fifth-four-notes/index.html", "image": "../media/beethoven-fifth-four-notes.jpg", "alt": "\ubca0\ud1a0\ubca4 \uad50\ud5a5\uace1 \uc81c5\ubc88\uc758 \ub300\ud45c \uc74c\ud615\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc2e4\uc81c \uc545\ubcf4 \uc77c\ubd80. \uc138 \uac1c\uc758 \uc9e7\uc740 \uc74c\uacfc \uae38\uac8c \uba38\ubb34\ub294 \uc74c, \uac15\uc57d\u00b7\uc27c\ud45c\u00b7\ub298\uc784\ud45c\uac00 \ubcf4\uc785\ub2c8\ub2e4.", "text": "\ubca0\ud1a0\ubca4 \uad50\ud5a5\uace1 \uc81c5\ubc88 \u2014 \ub124 \uc74c\uc740 \uc5b4\ub5bb\uac8c \uae34 \uc774\uc57c\uae30\uac00 \ub420\uae4c \uc6b4\uba85\uc774\ub77c\ub294 \uc774\ub984\uc744 \uc7a0\uc2dc \ub0b4\ub824\ub193\uace0 \ub4e3\ub294 \ub124 \uc545\uc7a5 \uc9e7\uc740 \uc74c\ud615\uc758 \ubc18\ubcf5\uacfc \ubcc0\ud654, \ub9c8\uc9c0\ub9c9 \uc545\uc7a5\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \ud750\ub984\uc744 \uc2e4\uc81c \uc545\ubcf4\uc640 \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc74c\uc545 \ubb38\ud654\uc640 \uc608\uc220 \uc138 \ubc88 \uc9e7\uac8c, \ud55c \ubc88 \uae38\uac8c. \ubca0\ud1a0\ubca4 \uad50\ud5a5\uace1 \uc81c5\ubc88\uc758 \uc2dc\uc791\uc740 \ud074\ub798\uc2dd \uc81c\ubaa9\uc744 \uc798 \ubab0\ub77c\ub3c4 \uc54c\uc544\ub4e3\ub294 \uc0ac\ub78c\uc774 \ub9ce\ub2e4. \ub108\ubb34 \uc775\uc219\ud574\uc11c \ucc98\uc74c \ub124 \uc74c\ub9cc \ud655\uc778\ud558\uace0 \uc774\ubbf8 \uace1 \uc804\uccb4\ub97c \uc548\ub2e4\uace0 \ub290\ub07c\uae30 \uc27d\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \uc9e7\uc740 \uc2dc\uc791\uc740 \uae34 \uc74c\uc545\uc758 \ubb38\uc5d0 \uac00\uae5d\ub2e4. \uc791\ud488\uc740 \ub2e4\ub2e8\uc870 \uad50\ud5a5\uace1 \uc81c5\ubc88, \uc791\ud488\ubc88\ud638 67\uc774\ub2e4. \u2018\uc6b4\uba85\u2019\uc774\ub77c\ub294 \uc774\ub984\uc774 \ub110\ub9ac \uc4f0\uc774\uc9c0\ub9cc \uadf8 \ud55c \ub2e8\uc5b4\ub85c \ubaa8\ub4e0 \uc7a5\uba74\uc744 \uc815\ub9ac\ud558\uc9c0 \uc54a\uace0, \uc791\uc740 \uc74c\ud615\uc774 \uc5b4\ub5bb\uac8c \ub3cc\uc544\uc624\uace0 \ub2ec\ub77c\uc9c0\ub294\uc9c0 \ub530\ub77c\uac00 \ubcf4\uc790. \uc545\ubcf4\ub97c \uc77d\uc9c0 \ubabb\ud574\ub3c4 \uc2dc\uc791\ud560 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \uc61b \uad50\ud5a5\uace1 \ud574\uc124\uc11c\uac00 \uc2e4\uc740 \uc2e4\uc81c \uc545\ubcf4 \uc77c\ubd80\ub2e4. \uc138 \uac1c\uc758 \uc9e7\uc740 \uc74c \ub4a4\uc5d0 \uc624\ub798 \uba38\ubb34\ub294 \uc74c\uc774 \ub098\uc624\uace0, \uadf8 \uc55e\uc758 \uc27c\uacfc \ub298\uc784\ud45c, \uac15\ud558\uac8c \ub0b4\ub77c\ub294 \ud45c\uae30\ub3c4 \ubcf4\uc778\ub2e4. \uc775\uc219\ud55c \u2018\ub530\ub530\ub530\ub2e8\u2019\uc744 \uae00\uc790\ub85c\ub9cc \uc801\uc73c\uba74 \ube60\uc9c0\ub294 \uc815\ubcf4\ub4e4\uc774\ub2e4. \ucc98\uc74c \ub4e4\uc5b4 \ubcfc \ub54c\ub294 \uc18c\ub9ac\uac00 \ub09c \uc21c\uac04\ubfd0 \uc544\ub2c8\ub77c \uba48\ucd94\uc5b4 \uc788\ub294 \uc21c\uac04\ub3c4 \uae30\ub2e4\ub824 \ubcf4\uc790. \ub2e4\uc74c \uc74c\uc774 \uc5b8\uc81c \uc62c\uc9c0 \uc0dd\uae30\ub294 \uae30\ub300\uac00 \uc2dc\uc791\uc758 \ud798\uc744 \ub9cc\ub4e0\ub2e4. \uac19\uc740 \ub124 \uc74c\uc774\ub77c\ub3c4 \uc5bc\ub9c8\ub098 \ubc00\uace0 \uc5b4\ub514\uc5d0\uc11c \uba38\ubb34\ub290\ub0d0\uc5d0 \ub530\ub77c \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ub9ac\ub4ec\uc740 \uc74c\uc758 \uac1c\uc218\ub9cc\uc744 \ub73b\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc61b \ud574\uc124\uc11c\uc5d0\ub3c4 \uc6b4\uba85\uc774 \ubb38\uc744 \ub450\ub4dc\ub9b0\ub2e4\ub294 \uc720\uba85\ud55c \uc124\uba85\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \uc774\ub7f0 \uc774\uc57c\uae30\ub294 \uc9e7\uc740 \uc2dc\uc791\uc744 \uae30\uc5b5\ud558\ub294 \ub370 \ub3c4\uc6c0\uc744 \uc900\ub2e4. \ub2e4\ub9cc \uadf8\uac83\uc744 \uace1\uc758 \ubaa8\ub4e0 \ubd80\ubd84\uc744 \ud574\uc11d\ud558\ub294 \ud655\uc815\ub41c \uc791\uace1 \uc77c\uc9c0\ucc98\ub7fc \ucde8\uae09\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774\ubc88\uc5d0 \ud655\uc778\ud55c \uc790\ub8cc\uc758 \uc815\uc2dd \ud45c\uc81c\ub294 \ubc88\ud638\uc640 \uc870\uc131\uc73c\ub85c \uc791\ud488\uc744 \uc2dd\ubcc4\ud55c\ub2e4. \uc6b4\uba85\uacfc \uc2f8\uc6cc \uc774\uae34\ub2e4\ub294 \uc774\uc57c\uae30\ub85c \ub4e4\uc5b4\ub3c4 \uc88b\uc9c0\ub9cc, \ub2e4\ub978 \ubc29\uc2dd\uc758 \ub4e3\uae30\ub3c4 \uac00\ub2a5\ud558\ub2e4. \uc5b4\ub5a4 \uc74c\ud615\uc774 \ub04a\uae30\uc9c0 \uc54a\uace0 \uc774\uc5b4\uc9c0\ub294\uc9c0, \ub2e4\ub978 \uc545\uae30\ub85c \ub118\uc5b4\uac08 \ub54c \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc9c0\ub294\uc9c0 \ub4e3\ub294 \uac83\uc774\ub2e4. \uce5c\uc219\ud55c \ubcc4\uba85 \uacc1\uc5d0 \uc74c\uc545\uc774 \uc2e4\uc81c\ub85c \ub9cc\ub4dc\ub294 \uad00\uacc4\ub97c \ub193\uc73c\uba74 \uace1\uc774 \ud55c \uac00\uc9c0 \uc904\uac70\ub9ac\ubcf4\ub2e4 \ub113\uc5b4\uc9c4\ub2e4. \uccab \uc545\uc7a5\uc5d0\uc11c\ub294 \uc2dc\uc791\uc758 \ub9ac\ub4ec\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uc6c0\uc9c1\uc784\uc774 \uc5ec\ub7ec \uc790\ub9ac\uc5d0\uc11c \uadc0\ub97c \ubd99\uc7a1\ub294\ub2e4. \uac15\ud558\uac8c \ubab0\uc544\ubd99\uc774\ub294 \uc21c\uac04\uacfc \uc7a0\uc2dc \ub2e4\ub978 \ud45c\uc815\uc774 \uc5f4\ub9ac\ub294 \ubd80\ubd84\uc774 \uc774\uc5b4\uc9c0\uc9c0\ub9cc, \ucc98\uc74c\uc758 \uae34\uc7a5\uc740 \uc27d\uac8c \uc0ac\ub77c\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uc9e7\uc740 \uc7ac\ub8cc\ub97c \uc5bc\ub9c8\ub098 \uae38\uace0 \ub2e4\uc591\ud558\uac8c \uc4f8 \uc218 \uc788\ub294\uc9c0 \ub290\ub07c\uac8c \ud55c\ub2e4. \ubc18\ubcf5\uc740 \uc81c\uc790\ub9ac\uc5d0\uc11c \uac19\uc740 \ub9d0\uc744 \ud558\ub294 \uac83\ub9cc\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub978 \ub192\uc774\uc640 \ub2e4\ub978 \uc545\uae30, \ub354 \ud070 \uc18c\ub9ac\uc640 \uc791\uc740 \uc18c\ub9ac\uc5d0\uc11c \ub3cc\uc544\uc62c \uc218 \uc788\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc5b4\ub514\uc11c \ub2e4\uc2dc \uc54c\uc544\ub4e3\uac8c \ub418\ub294\uc9c0 \ucc3e\uace0, \ub2e4\uc74c\uc5d0\ub294 \uadf8\ub54c \uc8fc\ubcc0\uc758 \uc18c\ub9ac\uac00 \uc5b4\ub5a4\uc9c0 \ub4e4\uc5b4 \ubcf4\uc790. \ubaa8\ub974\ub294 \uc545\uae30 \uc774\ub984\uc744 \ubaa8\ub450 \uc54c\uc544\uc57c \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub450 \ubc88\uc9f8 \uc545\uc7a5\uc5d0\uc11c\ub294 \uccab \uc545\uc7a5\ubcf4\ub2e4 \ub113\uac8c \ub178\ub798\ud558\ub294 \uc120\uc728\uacfc \ucc28\ubd84\ud55c \uac78\uc74c\uc744 \ub9cc\ub09c\ub2e4. \uacc4\uc18d \uae34\ubc15\ud558\uac8c \ubab0\uc544\ubd99\uc774\ub294 \ud55c \ud3b8\uc758 \uc74c\uc545\uc744 \uc608\uc0c1\ud588\ub2e4\uba74 \uc758\uc678\ub85c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ud55c \uc791\ud488 \uc548\uc5d0\uc11c\ub3c4 \ub2e4\ub978 \uc885\ub958\uc758 \uc2dc\uac04\uc774 \uc5f4\ub9ac\ub294 \uac83\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \uae34\uc7a5\uc774 \uc0ac\ub77c\uc838 \ud3b8\uc548\ud55c \ubc30\uacbd\uc74c\uc545\ub9cc \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc120\uc728\uc774 \ub2e4\uc2dc \ub098\ud0c0\ub0a0 \ub54c \uc8fc\ubcc0\uc758 \uc9dc\uc784\uacfc \ud798\uc774 \ub2ec\ub77c\uc9c0\ub294\uc9c0 \uadc0\ub97c \uae30\uc6b8\uc5ec \ubcf4\uc790. \ubd80\ub4dc\ub7ec\uc6b4 \ubd80\ubd84\uacfc \ub354 \ub2f9\ub2f9\ud558\uac8c \ub4e4\ub9ac\ub294 \ubd80\ubd84\uc744 \ube44\uad50\ud558\uba74 \ub290\ub9b0 \uc545\uc7a5\uc5d0\ub3c4 \ubcc0\ud654\uc758 \ud3ed\uc774 \uc788\ub2e4\ub294 \uc810\uc744 \uc54c \uc218 \uc788\ub2e4. \uc138 \ubc88\uc9f8 \uc545\uc7a5\uc5d0\uc11c\ub294 \ub0ae\uc740 \uc18c\ub9ac\uc640 \uc870\uc2ec\uc2a4\ub7ec\uc6b4 \uc6c0\uc9c1\uc784, \uac15\ud558\uac8c \ub098\ud0c0\ub098\ub294 \ubd80\ubd84\uc758 \ub300\ube44\ub97c \ub290\ub084 \uc218 \uc788\ub2e4. \uc55e\uc5d0\uc11c \ub4e4\uc740 \ub9ac\ub4ec\uc758 \uc131\uaca9\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \ub300\ubaa9\ub3c4 \uc788\ub2e4. \uccab \uc545\uc7a5\uc758 \uae30\uc5b5\uc774 \uc644\uc804\ud788 \ub2eb\ud788\uc9c0 \uc54a\uace0 \ub2e4\ub978 \ud45c\uc815\uc73c\ub85c \ub0a8\ub294 \uc148\uc774\ub2e4. \uc774 \ubd80\ubd84\uc744 \ube44\ubc00\uc2a4\ub7ec\uc6b4 \ubc24\uc774\ub098 \uae34\uc7a5\ub41c \ubc1c\uac78\uc74c\ucc98\ub7fc \uc0c1\uc0c1\ud574\ub3c4 \uc88b\uc9c0\ub9cc, \uadf8\uac83\uc774 \uc791\uace1\uac00\uac00 \uc815\ud574 \ub454 \uc7a5\uba74\uc774\ub77c\uace0 \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc870\uc6a9\ud558\ub2e4\ub294 \uac83\uc774 \ub2e8\uc9c0 \uc26c\ub294 \uc2dc\uac04\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc744 \ub4e4\uc5b4 \ubcf4\uc790. \uc18c\ub9ac\uac00 \uc791\uc544\uc9c8\uc218\ub85d \ub2e4\uc74c\uc5d0 \ubb34\uc5c7\uc774 \ub098\uc62c\uc9c0 \uae30\ub2e4\ub9ac\ub294 \uac10\uac01\uc774 \ucee4\uc9c0\uae30\ub3c4 \ud55c\ub2e4. \uc138 \ubc88\uc9f8\uc5d0\uc11c \ub124 \ubc88\uc9f8\ub85c \uc774\uc5b4\uc9c0\ub294 \ubd80\ubd84\uc740 \uc804\uccb4\ub97c \ub4e3\ub294 \uc911\uc694\ud55c \uc774\uc720 \uc911 \ud558\ub098\ub2e4. \uc18c\ub9ac\uac00 \uc313\uc774\uace0 \uae30\ub2e4\ub9bc\uc774 \uae38\uc5b4\uc9c0\ub2e4\uac00 \ub9c8\uc9c0\ub9c9 \uc545\uc7a5\uc758 \ub113\uace0 \uac15\ud55c \uc18c\ub9ac\ub85c \ub098\uc544\uac04\ub2e4. \ucc98\uc74c \ub124 \uc74c\ub9cc \ub530\ub85c \ub4e4\uc5c8\uc744 \ub54c\ub294 \ub9cc\ub0a0 \uc218 \uc5c6\ub294 \uae34 \ud638\ud761\uc774\ub2e4. \uc774\ub54c \ub290\ub07c\ub294 \ud574\ubc29\uac10\uc774\ub098 \ubc1d\uc74c\uc740 \uc55e\uc5d0\uc11c \uc5b4\ub5a4 \uc2dc\uac04\uc744 \uac70\ucce4\ub294\uc9c0\uc640 \uc5f0\uacb0\ub41c\ub2e4. \ub05d\ubd80\ubd84\ub9cc \ub5bc\uc5b4 \ub4e4\uc73c\uba74 \uc6c5\uc7a5\ud55c \uc18c\ub9ac\uc774\uc9c0\ub9cc, \uadf8\uc804\uc758 \uae34\uc7a5\uc744 \uae30\uc5b5\ud558\uba70 \ub4e4\uc73c\uba74 \ub2e4\ub978 \ubb34\uac8c\ub97c \uac00\uc9c4\ub2e4. \uc74c\uc545\uc758 \uc758\ubbf8\uac00 \ud55c \uc120\uc728 \uc548\uc5d0\ub9cc \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc21c\uc11c\uc640 \uc9c0\ub098\uc628 \uc2dc\uac04\uc5d0\ub3c4 \uc788\ub2e4\ub294 \uc810\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub9c8\uc9c0\ub9c9 \uc545\uc7a5\uc5d0\uc11c\ub294 \ud798\ucc28\uac8c \ub098\uc544\uac00\ub294 \ud750\ub984 \uc18d\uc5d0\uc11c\ub3c4 \uc55e\uc120 \uc545\uc7a5\uc758 \uae30\uc5b5\uc774 \ub418\uc0b4\uc544\ub098\ub294 \uc21c\uac04\uc774 \uc788\ub2e4. \uc9c1\uc120\uc73c\ub85c \ubc1d\uc740 \uacb0\ub860\uc5d0 \ub3c4\ucc29\ud55c\ub2e4\uace0\ub9cc \uc608\uc0c1\ud558\uba74 \uc774\ub7f0 \ub418\ub3cc\uc544\uc634\uc744 \ub193\uce60 \uc218 \uc788\ub2e4. \uc791\ud488\uc740 \uc9c0\ub098\uc628 \uc18c\ub9ac\ub97c \ub2e4\uc2dc \ub5a0\uc62c\ub9ac\uac8c \ud558\uba74\uc11c \ub05d\uc744 \ud5a5\ud55c\ub2e4. \ub9c8\ubb34\ub9ac\uac00 \uae38\uac8c \ub290\uaef4\uc9c8 \ub54c\uc5d0\ub294 \uc5b8\uc81c \ub05d\ub098\ub294\uc9c0 \ub9de\ud788\ub824 \ud558\uae30\ubcf4\ub2e4 \ub05d\uc744 \uc900\ube44\ud558\ub294 \ud798\uc774 \uc5b4\ub5bb\uac8c \uc720\uc9c0\ub418\ub294\uc9c0 \ub4e4\uc5b4 \ubcf4\uc790. \ud55c \ubc88\uc758 \ud070 \uc18c\ub9ac\ub85c \ub2eb\ub294 \uac83\uacfc \uc5ec\ub7ec \ubc88 \ud655\uc778\ud558\uba70 \ub2eb\ub294 \uac83\uc740 \ub2e4\ub978 \uacbd\ud5d8\uc774\ub2e4. \uc774 \uace1\uc774 \uc9e7\uc740 \ud45c\uc5b4\uac00 \uc544\ub2c8\ub77c \uae38\uac8c \uc9c4\ud589\ub418\ub294 \uc74c\uc545\uc774\ub77c\ub294 \uc0ac\uc2e4\uc774 \ub9c8\uc9c0\ub9c9\uae4c\uc9c0 \ub0a8\ub294\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc81c1\uc545\uc7a5, \ub2e4\uc74c\uc5d0\ub294 \uc81c3\uc545\uc7a5\uc5d0\uc11c \uc81c4\uc545\uc7a5\uc73c\ub85c \ub118\uc5b4\uac00\ub294 \ubd80\ubd84\uc744 \ub4e4\uc5b4\ub3c4 \uc88b\ub2e4. \uc5ec\uc720\uac00 \uc0dd\uae30\uba74 \ub124 \uc545\uc7a5\uc744 \uc774\uc5b4 \ub4e4\uc73c\uba70 \uc11c\ub85c \ub2e4\ub978 \ud45c\uc815\uc774 \uc5b4\ub5bb\uac8c \ud55c \uc791\ud488\uc744 \uc774\ub8e8\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc815\ud574\uc9c4 \uac10\uc815\uc744 \ub9de\ud600\uc57c \ud558\ub294 \uac10\uc0c1\uc740 \uc544\ub2c8\ub2e4. \uc545\ubcf4\uc758 \uc9e7\uc740 \uc74c\uacfc \uae34 \uc74c\uc744 \ub208\uc73c\ub85c \ud655\uc778\ud55c \ub4a4 \uadc0\ub85c \ub2e4\uc2dc \ub9cc\ub098\uba74 \uc775\uc219\ud55c \uc2dc\uc791\ub3c4 \uc870\uae08 \uad6c\uccb4\uc801\uc73c\ub85c \ub4e4\ub9b0\ub2e4. \uc6b4\uba85\uc774\ub77c\ub294 \uc720\uba85\ud55c \uc774\ub984\uc740 \ucd9c\ubc1c\uc810\uc73c\ub85c \ub450\uace0, \uadf8 \ub4a4\uc758 \uc120\uc728\uacfc \uba48\ucda4, \ub3cc\uc544\uc624\ub294 \ub9ac\ub4ec\uc744 \ub530\ub77c\uac00 \ubcf4\uc790. \uc774\ubbf8 \uc548\ub2e4\uace0 \uc0dd\uac01\ud588\ub358 \ub124 \uc74c\uc774 \uc544\uc9c1 \ub4e3\uc9c0 \ubabb\ud55c \uae34 \uc2dc\uac04\uc73c\ub85c \uc774\uc5b4\uc9c4\ub2e4."}, {"id": "beethoven-life-and-work", "title": "\ubca0\ud1a0\ubca4\uc758 \uc0dd\uc560 \u2014 \ub4e4\ub9ac\ub294 \uc138\uacc4\uac00 \ub2ec\ub77c\uc838\ub3c4 \uc791\uc5c5\uc740 \uc774\uc5b4\uc84c\ub2e4", "summary": "\uc704\ub300\ud55c \uc74c\uc545\uac00\ub77c\ub294 \ub9d0 \ub4a4\uc758 \ubc30\uc6c0\uacfc \uc0dd\ud65c, \uc6d0\uace0\uc640 \uc0ac\ub78c\ub4e4\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc74c\uc545", "categories": ["arts"], "url": "stories/beethoven-life-and-work/index.html", "image": "../media/beethoven-life-and-work.jpg", "alt": "\ub8e8\uc774 \ub808\ud2b8\ub860\uc758 1814\ub144 \ub4dc\ub85c\uc789\uc744 \ubc14\ud0d5\uc73c\ub85c \ud55c \ubca0\ud1a0\ubca4\uc758 \uc5ed\uc0ac\uc801 \ud310\ud654 \ucd08\uc0c1.", "text": "\ubca0\ud1a0\ubca4\uc758 \uc0dd\uc560 \u2014 \ub4e4\ub9ac\ub294 \uc138\uacc4\uac00 \ub2ec\ub77c\uc838\ub3c4 \uc791\uc5c5\uc740 \uc774\uc5b4\uc84c\ub2e4 \ubcf8\uc5d0\uc11c \ube48\uc73c\ub85c, \uccad\ub825\uc758 \uc5b4\ub824\uc6c0\uacfc \uc791\ud488\uc744 \ub9cc\ub4e4\uc5b4 \uac00\ub294 \uc2dc\uac04 \uc704\ub300\ud55c \uc74c\uc545\uac00\ub77c\ub294 \ub9d0 \ub4a4\uc758 \ubc30\uc6c0\uacfc \uc0dd\ud65c, \uc6d0\uace0\uc640 \uc0ac\ub78c\ub4e4\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uc74c\uc545 \ubb38\ud654\uc640 \uc608\uc220 \ubca0\ud1a0\ubca4\uc744 \ub5a0\uc62c\ub9ac\uba74 \uac15\ud55c \ud45c\uc815\uc758 \uc5bc\uad74\uacfc \uc6c5\uc7a5\ud55c \uc74c\uc545, \ub4e4\uc744 \uc218 \uc5c6\uac8c \ub41c \uc791\uace1\uac00\ub77c\ub294 \uc774\uc57c\uae30\uac00 \ud568\uaed8 \ub098\uc628\ub2e4. \uadf8\ub7f0\ub370 \uadf8 \uba87 \uac00\uc9c0 \uc774\ubbf8\uc9c0\ub85c\ub294 \ud55c \uc0ac\ub78c\uc774 \uc5b4\ub5bb\uac8c \ubc30\uc6b0\uace0 \uc77c\ud558\uba70 \uc791\ud488\uc744 \ub2e4\ub4ec\uc5c8\ub294\uc9c0 \uc54c\uae30 \uc5b4\ub835\ub2e4. \uc0b6\uc744 \uc74c\uc545\uc758 \ube44\uadf9\uc801\uc778 \ubc30\uacbd \ud558\ub098\ub85c\ub9cc \ub9cc\ub4e4\uc9c0 \uc54a\uace0 \ub530\ub77c\uac00 \ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \uadf8\ub294 1770\ub144 \ubcf8\uc5d0\uc11c \ud0dc\uc5b4\ub098 1827\ub144 \ube48\uc5d0\uc11c \uc138\uc0c1\uc744 \ub5a0\ub0ac\ub2e4. \uadf8 \uc0ac\uc774\uc5d0\ub294 \ud53c\uc544\ub178\ub97c \uc5f0\uc8fc\ud558\ub358 \uccad\ub144\uacfc \uc0c8\ub85c\uc6b4 \uc791\ud488\uc744 \uc4f0\ub358 \uc791\uace1\uac00, \uccad\ub825\uc758 \uc5b4\ub824\uc6c0\uacfc \uc0ac\ub78c\ub4e4\uacfc\uc758 \uad00\uacc4\ub97c \uac10\ub2f9\ud558\ub358 \uc0dd\ud65c\uc778\uc774 \uc788\uc5c8\ub2e4. \uc5b4\ub9b0 \ubca0\ud1a0\ubca4\uc740 \ubcf8\uc5d0\uc11c \uc74c\uc545\uc744 \ubc30\uc6e0\ub2e4. \uac00\uc871\uc758 \ud658\uacbd\uacfc \uc0dd\uacc4, \uc5f0\uc8fc\ub97c \uc775\ud600\uc57c \ud558\ub294 \uc2dc\uac04\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \ud6d7\ub0a0\uc758 \uc791\ud488 \uc774\ub984\ub9cc \ubcf4\uba74 \uc5b4\ub9b0 \uc2dc\uc808\ubd80\ud130 \uc790\uae30 \uc74c\uc545\uc744 \ubaa8\ub450 \uc54c\uace0 \uc788\ub358 \uc0ac\ub78c\ucc98\ub7fc \uc0c1\uc0c1\ud558\uae30 \uc27d\uc9c0\ub9cc, \uadf8\uc5d0\uac8c\ub3c4 \ubc30\uc6cc\uc57c \ud560 \uae30\uc220\uacfc \ucc98\uc74c \ub9cc\ub098\ub294 \uae30\ud68c\uac00 \uc788\uc5c8\ub2e4. \uc7ac\ub2a5\uc744 \ubc1c\uacac\ud558\ub294 \uadf9\uc801\uc778 \uc77c\ud654 \ud558\ub098\ubcf4\ub2e4 \uacc4\uc18d \uc545\uae30\ub97c \ub2e4\ub8e8\uace0 \uc74c\uc545\uc744 \uc775\ud788\ub294 \uc2dc\uac04\uc744 \uc0dd\uac01\ud574 \ubcf4\uc790. \ub208\uc5d0 \ub744\ub294 \ub2a5\ub825\uacfc \uadf8\uac83\uc744 \uc77c\ub85c \uc774\uc5b4 \uac00\ub294 \uc0dd\ud65c\uc740 \ub2e4\ub974\ub2e4. \uc74c\uc545\uac00\uc758 \uc0dd\uc560\uc5d0\uc11c\ub3c4 \uc5f0\uc2b5\uacfc \ud658\uacbd, \ub3c4\uc6c0\uc744 \uc8fc\ub294 \uc0ac\ub78c\ub4e4\uc774 \uad6c\uccb4\uc801\uc778 \uc790\ub9ac\ub97c \ucc28\uc9c0\ud55c\ub2e4. 1792\ub144 \uadf8\ub294 \ube48\uc73c\ub85c \uc62e\uaca8 \ud65c\ub3d9\ud55c\ub2e4. \uc0c8\ub85c\uc6b4 \ub3c4\uc2dc\uc5d0\uc11c \ubc30\uc6b0\uace0 \uc5f0\uc8fc\ud558\uba70 \uc0ac\ub78c\ub4e4\uc744 \ub9cc\ub09c\ub2e4. \uc5f0\uc8fc\uc790\ub85c \uc54c\ub824\uc9c0\ub294 \uc77c\uacfc \uc790\uae30 \uc791\ud488\uc744 \uc791\uace1\uac00\ub85c \ub0b4\ub193\ub294 \uc77c\uc774 \uc774\uc5b4\uc9c0\ub294 \uc2dc\uae30\ub2e4. \ube48\uc740 \uadf8\uc5d0\uac8c \uc774\ubbf8 \uc644\uc131\ub41c \uba85\uc131\uc744 \ud655\uc778\ud558\ub294 \ubb34\ub300\ub9cc\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ub3c4\uc2dc\uc758 \uccad\uc911\uacfc \uc74c\uc545\uac00, \ud6c4\uc6d0\uc790\uc640 \ucd9c\ud310\uc758 \uc870\uac74 \uc18d\uc5d0\uc11c \uc790\uc2e0\uc758 \uc790\ub9ac\ub97c \ub9cc\ub4e4\uc5b4\uc57c \ud588\ub2e4. \uc2a4\uc2a4\ub85c\uc758 \uac1c\uc131\uc744 \uc9c0\ud0a4\ub824\ub294 \ud0dc\ub3c4\ub3c4 \uc774\ub7f0 \uad00\uacc4\uc640 \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\ub2e4. \ub3c5\ub9bd\uc801\uc778 \uc608\uc220\uac00\ub77c\ub294 \ub9d0\uc744 \ubaa8\ub4e0 \ub3c4\uc6c0\uacfc \ud604\uc2e4\uc758 \uc870\uac74\uc744 \ubc97\uc5b4\ub09c \uc0ac\ub78c\uc774\ub77c\ub294 \ub73b\uc73c\ub85c \ubc1b\uc544\ub4e4\uc774\uc9c0\ub294 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uccad\ub825\uc774 \ub098\ube60\uc9c0\ub294 \uacfc\uc815\uc740 \uc5f0\uc8fc\uc640 \uc77c\ubfd0 \uc544\ub2c8\ub77c \uc0ac\ub78c\uc744 \ub9cc\ub098\ub294 \uc0dd\ud65c\uc5d0\ub3c4 \uc601\ud5a5\uc744 \ubbf8\ucce4\ub2e4. \ub85c\ub9f9 \ub864\ub791\uc758 \uc804\uae30\uc5d0 \uc218\ub85d\ub41c \ud3b8\uc9c0\uc640 \ubb38\uc11c\uc5d0\ub294 \uadf8 \uc5b4\ub824\uc6c0\uc744 \uc5b4\ub5bb\uac8c \uc124\uba85\ud574\uc57c \ud560\uc9c0 \uace0\ubbfc\ud558\ub294 \ubaa9\uc18c\ub9ac\uac00 \ub0a8\uc544 \uc788\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ubb34\ub69d\ub69d\ud558\uac8c \ubcf4\uc774\ub294 \ubaa8\uc2b5 \ub4a4\uc5d0 \uc54c\ub9ac\uc9c0 \ubabb\ud55c \uc0ac\uc815\uc774 \uc788\uc744 \uc218 \uc788\uc5c8\ub2e4. \uc774 \uae30\ub85d\uc744 \uc77d\uc73c\uba74 \uc131\uaca9\uc5d0 \ub300\ud55c \ub2e8\uc815\uc774 \uc870\uae08 \ub2a6\uc5b4\uc9c4\ub2e4. \ub298 \ud654\ub97c \ub0b4\ub294 \ucc9c\uc7ac\ub77c\ub294 \uc775\uc219\ud55c \uc778\uc0c1\ub9cc\uc73c\ub85c \uad00\uacc4 \uc804\uccb4\ub97c \uc124\uba85\ud558\uae30 \uc5b4\ub835\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \uac08\ub4f1\uc774 \uccad\ub825 \ud558\ub098 \ub54c\ubb38\uc5d0 \uc77c\uc5b4\ub0ac\ub2e4\uace0 \uc815\ub9ac\ud560 \uc218\ub3c4 \uc5c6\ub2e4. \uc5ec\ub7ec \uc870\uac74\uc774 \ud55c \uc0ac\ub78c\uc758 \uc77c\uc0c1\uc744 \ud568\uaed8 \ub9cc\ub4e0\ub2e4. \ud558\uc77c\ub9ac\uac90\uc288\ud0c0\ud2b8\uc5d0\uc11c \uc4f4 1802\ub144\uc758 \uc720\uc11c\ub294 \uc790\uc2e0\uc758 \uace0\ud1b5\uacfc \uc624\ud574, \uc55e\uc73c\ub85c\uc758 \uc0b6\uc5d0 \uad00\ud55c \uc0dd\uac01\uc744 \uc804\ud55c\ub2e4. \uc791\ud488\uc744 \ub4e4\uc73c\uba70 \ub9c9\uc5f0\ud788 \uc0c1\uc0c1\ud588\ub358 \uc5b4\ub824\uc6c0\uc774 \uc2e4\uc81c \uae00\uc758 \ud615\ud0dc\ub85c \ub0a8\uc544 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c \uc911\uc694\ud55c \uc790\ub8cc\ub2e4. \ud654\ub824\ud55c \uc131\uacf5\ub2f4\ub9cc\uc73c\ub85c\ub294 \uc54c\uae30 \ud798\ub4e0 \ubaa9\uc18c\ub9ac\ub2e4. \uc5ec\uae30\uc11c \uace0\ud1b5\uc774 \ud6cc\ub96d\ud55c \uc791\ud488\uc744 \uc790\ub3d9\uc73c\ub85c \ub9cc\ub4e4\uc5b4 \uc8fc\uc5c8\ub2e4\ub294 \uacf5\uc2dd\uc744 \uc138\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5b4\ub824\uc6c0\uc744 \uacaa\ub294 \ub3d9\uc548\uc5d0\ub3c4 \uc5b4\ub5bb\uac8c \uc0b4\uc544\uac00\uace0 \uc791\uc5c5\ud560\uc9c0 \uace0\ubbfc\ud588\ub2e4\ub294 \uc810\uc744 \uc77d\ub294 \ud3b8\uc774 \ub0ab\ub2e4. \uc608\uc220\uc744 \uc774\ud574\ud558\ub824\uace0 \ud55c \uc0ac\ub78c\uc758 \uc544\ud514\uc744 \uac10\ub3d9\uc801\uc778 \uc7a5\uc2dd\uc73c\ub85c \uc18c\ube44\ud558\uc9c0 \uc54a\ub294 \ud0dc\ub3c4\ub3c4 \uc911\uc694\ud558\ub2e4. \uc791\uace1\uac00\uc758 \uc74c\uc545\uc740 \uc885\uc885 \uba38\ub9bf\uc18d\uc5d0\uc11c \uc644\uc131\ub418\uc5b4 \ud55c \ubc88\uc5d0 \uc885\uc774\ub85c \ub098\uc624\ub294 \uac83\ucc98\ub7fc \uc774\uc57c\uae30\ub41c\ub2e4. \ud558\uc9c0\ub9cc \ub0a8\uc740 \uc6d0\uace0\uc640 \uc5ec\ub7ec \uc790\ub8cc\ub97c \ubcf4\uba74 \ubb34\uc5c7\uc744 \uc120\ud0dd\ud558\uace0 \ub2e4\ub4ec\uc744\uc9c0 \uace0\ubbfc\ud558\ub294 \uc2dc\uac04\uc774 \uc788\uc5c8\ub2e4. \ud558\ub098\uc758 \uc120\uc728\uc744 \ub9cc\ub4e0 \ub4a4 \uc804\uccb4\uc758 \uad00\uacc4\ub97c \uc9dc\ub294 \uc77c\uc740 \ub2e4\ub978 \uc885\ub958\uc758 \uc791\uc5c5\uc774\ub2e4. \uc791\ud488\uc744 \ub4e4\uc744 \ub54c\ub3c4 \uc720\uba85\ud55c \uc8fc\uc81c\ub9cc \ub530\ub85c \uc544\ub294 \uac83\uc5d0\uc11c \uc870\uae08 \ub354 \ub098\uc544\uac08 \uc218 \uc788\ub2e4. \uc55e\uc758 \uc74c\uc545\uc774 \ub4a4\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ub3cc\uc544\uc624\ub294\uc9c0, \uc5b4\ub5a4 \uc545\uc7a5\uc774 \uc11c\ub85c \ub300\ube44\ub418\ub294\uc9c0 \ub4e4\uc5b4 \ubcf4\ub294 \uac83\uc774\ub2e4. \ud55c \ubc88\uc758 \uc601\uac10\uacfc \uae34 \uad6c\uc131\uc758 \uc2dc\uac04\uc744 \ud568\uaed8 \uc0dd\uac01\ud558\uba74 \uc74c\uc545\uac00\uc758 \ub178\ub3d9\uc774 \uc870\uae08 \uad6c\uccb4\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4. \uc804\uae30\uc640 \ud3b8\uc9c0\uc5d0\ub294 \ud6c4\uc6d0\uacfc \ub3c8, \uac00\uc871\uacfc \uac70\ucc98 \uac19\uc740 \ubb38\uc81c\uac00 \ub4f1\uc7a5\ud55c\ub2e4. \uc704\ub300\ud55c \uc791\ud488\uc744 \uc4f4\ub2e4\uace0 \uc77c\uc0c1\uc758 \uc0ac\uc815\uc774 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc791\ud488\uc744 \ub0b4\uace0 \uc5f0\uc8fc\ud558\uace0 \uc0dd\ud65c\uc744 \uc720\uc9c0\ud558\ub294 \uc77c\uc774 \uc11c\ub85c \uc5bd\ud614\ub2e4. \uc74c\uc545\uc758 \uc5ed\uc0ac\uc640 \uc0dd\ud65c\uc758 \uc5ed\uc0ac\ub294 \uac19\uc740 \uc0dd\uc560 \uc548\uc5d0 \uc788\ub2e4. \uc774\ub97c \uc54c\uba74 \uc791\ud488\uc744 \ub4e3\ub294 \uc990\uac70\uc6c0\uc774 \uaf2d \uc904\uc5b4\ub4dc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ud788\ub824 \uc644\uc131\ub41c \uc74c\uc545\uc744 \ub0a8\uae30\uae30 \uc704\ud574 \uc5b4\ub5a4 \uc870\uac74\uc744 \uac10\ub2f9\ud588\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc791\uace1\uac00\ub97c \uc644\ubcbd\ud55c \uc131\uc778\uc73c\ub85c \ub9cc\ub4e4\uac70\ub098 \ubc18\ub300\ub85c \uc0ac\uc0dd\ud65c\uc758 \uac08\ub4f1\uc73c\ub85c \uc791\ud488 \uc804\uccb4\ub97c \ud310\uacb0\ud560 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \uad50\ud5a5\uace1 \uc81c9\ubc88\uc744 \ube44\ub86f\ud55c \ud6c4\uae30 \uc791\uc5c5\uc5d0\uc11c\ub294 \ubaa9\uc18c\ub9ac\uc640 \uc545\uae30, \ud070 \ud615\uc2dd\uacfc \uc138\ubc00\ud55c \uc6c0\uc9c1\uc784\uc774 \uc5ec\ub7ec \ubc29\uc2dd\uc73c\ub85c \ub098\ud0c0\ub09c\ub2e4. \uccad\ub825\uc774 \ud06c\uac8c \uc190\uc0c1\ub41c \uc2dc\uae30\uc5d0\ub3c4 \uc791\uc5c5\uc774 \uc774\uc5b4\uc84c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc911\uc694\ud558\ub2e4. \uadf8\ub7ec\ub098 \ubaa8\ub4e0 \uc791\ud488\uc744 \uac19\uc740 \uace0\ud1b5\uc758 \uace0\ubc31\uc73c\ub85c\ub9cc \ub4e3\ub294\ub2e4\uba74 \uc11c\ub85c \ub2e4\ub978 \uc74c\uc545\uc758 \uc131\uaca9\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \uc55e\uc11c \ub9cc\ub09c \u3008\uc804\uc6d0\u3009\uc758 \uc2dc\ub0c7\uac00\uc640 \ub2e4\ub978 \uc791\ud488\uc758 \uae34\uc7a5, \ub178\ub798\ud558\ub294 \uc120\uc728\uacfc \uac15\ud55c \ub9ac\ub4ec\uc744 \ube44\uad50\ud574 \ubcf4\uc790. \ud55c \uc791\uace1\uac00 \uc548\uc5d0\ub3c4 \ub2e4\uc591\ud55c \ud45c\uc815\uc774 \uc788\ub2e4. \uc0dd\uc560\uc758 \ud070 \uc0ac\uc2e4\uc744 \uc54c\uc544 \ub454 \ub4a4\uc5d0\ub294 \ub2e4\uc2dc \uc2e4\uc81c\ub85c \uc774\uc5b4\uc9c0\ub294 \uc74c\uacfc \uad6c\uc870\uc5d0 \uadc0\ub97c \ub3cc\ub9ac\ub294 \uac83\uc774 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \ub8e8\uc774 \ub808\ud2b8\ub860\uc758 1814\ub144 \ub4dc\ub85c\uc789\uc744 \ubc14\ud0d5\uc73c\ub85c \ud55c \ube14\ub77c\uc9c0\uc6b0\uc2a4 \ud68c\ud3a0\uc758 \uc5ed\uc0ac\uc801 \ucd08\uc0c1 \ud310\ud654\ub2e4. \uc624\ub298 \ub5a0\uc62c\ub9ac\ub294 \ubca0\ud1a0\ubca4\uc758 \uc5bc\uad74\uc744 \uc804\ud558\ub294 \uc790\ub8cc \uc911 \ud558\ub098\uc9c0\ub9cc, \uadf8 \ud45c\uc815\ub9cc\uc73c\ub85c \ub9e4\uc77c\uc758 \uac10\uc815\uc744 \uc9c4\ub2e8\ud560 \uc218\ub294 \uc5c6\ub2e4. \ubca0\ud1a0\ubca4\uc758 \uc0b6\uc744 \uc54c\uc558\ub2e4\ub294 \uac83\uc740 \uccad\ub825\uacfc \uc8fd\uc74c\uc758 \uc5f0\ub3c4\ub97c \uc678\uc6e0\ub2e4\ub294 \ub73b\uc5d0 \uba38\ubb3c\uc9c0 \uc54a\ub294\ub2e4. \ubc30\uc6b0\uace0 \uc774\ub3d9\ud558\uace0, \ubb38\uc11c\ub97c \uc4f0\uace0, \uc6d0\uace0\ub97c \uace0\uce58\uba70 \uc77c\uc744 \uc774\uc5b4 \uac04 \uc0ac\ub78c\uc744 \ud568\uaed8 \uae30\uc5b5\ud558\ub294 \uac83\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \uc775\uc219\ud55c \uace1\uc744 \ub9cc\ub098\uba74 \ucc9c\uc7ac\ub77c\ub294 \ub9d0\uc5d0 \uac00\ub824\uc84c\ub358 \uae34 \uc791\uc5c5\uc758 \uc2dc\uac04\uc744 \uc870\uae08 \ub5a0\uc62c\ub824 \ubcf4\uc544\ub3c4 \uc88b\uaca0\ub2e4."}, {"id": "beethoven-pastoral-five-scenes", "title": "\ubca0\ud1a0\ubca4 \uc804\uc6d0 \uad50\ud5a5\uace1 \u2014 \uc2dc\uace8\uc758 \ud558\ub8e8\ub97c \ub2e4\uc12f \uc545\uc7a5\uc73c\ub85c \uac77\uae30", "summary": "\ud48d\uacbd\uacfc \uac10\uc815\uc774 \ud568\uaed8 \uc6c0\uc9c1\uc774\ub294 \uad50\ud5a5\uace1 \uc81c6\ubc88\uc758 \ud750\ub984\uc744 \ub530\ub77c \ub4e3\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc74c\uc545", "categories": ["arts"], "url": "stories/beethoven-pastoral-five-scenes/index.html", "image": "../media/beethoven-pastoral-five-scenes.jpg", "alt": "\ucf54\ub85c\uc758 \ud48d\uacbd\ud654 \uc791\uc740 \uace8\uc9dc\uae30\ub97c \uc7ac\ud604\ud55c \uc61b \ub3c4\ud310. \uc804\uc6d0 \uad50\ud5a5\uace1\uc758 \uc790\uc5f0 \ubd84\uc704\uae30\ub97c \ud568\uaed8 \ub5a0\uc62c\ub9ac\uae30 \uc704\ud55c \uad00\ub828 \uc774\ubbf8\uc9c0\uc785\ub2c8\ub2e4.", "text": "\ubca0\ud1a0\ubca4 \uc804\uc6d0 \uad50\ud5a5\uace1 \u2014 \uc2dc\uace8\uc758 \ud558\ub8e8\ub97c \ub2e4\uc12f \uc545\uc7a5\uc73c\ub85c \uac77\uae30 \ub4e4\ud310\uc758 \uae30\uc068\uacfc \uc2dc\ub0c7\ubb3c, \ud3ed\ud48d \ub4a4\uc758 \uac10\uc0ac \ud48d\uacbd\uacfc \uac10\uc815\uc774 \ud568\uaed8 \uc6c0\uc9c1\uc774\ub294 \uad50\ud5a5\uace1 \uc81c6\ubc88\uc758 \ud750\ub984\uc744 \ub530\ub77c \ub4e3\uc2b5\ub2c8\ub2e4. \uc74c\uc545 \ubb38\ud654\uc640 \uc608\uc220 \uc2dc\uace8\uc5d0 \ub3c4\ucc29\ud558\uc790 \ub9c8\uc74c\uc774 \uc870\uae08 \ud480\ub9ac\uace0, \ubb3c\uac00\uc5d0\uc11c \uc624\ub798 \uba38\ubb3c\uace0 \uc2f6\uc5b4\uc9c4\ub2e4. \uc0ac\ub78c\ub4e4\uc758 \ubaa8\uc784\uc774 \uc2dc\uc791\ub418\uc9c0\ub9cc \uc5b4\ub290\uc0c8 \ud558\ub298\uc774 \uc5b4\ub450\uc6cc\uc9c0\uace0 \ube44\ubc14\ub78c\uc774 \ubab0\ub824\uc628\ub2e4. \ud3ed\ud48d\uc774 \uc9c0\ub09c \ub4a4\uc5d0\ub294 \ucc98\uc74c\uacfc \ub2e4\ub978 \uace0\uc694\uac00 \ucc3e\uc544\uc628\ub2e4. \ubca0\ud1a0\ubca4 \uad50\ud5a5\uace1 \uc81c6\ubc88 \u3008\uc804\uc6d0\u3009\uc740 \uc774\ub7f0 \ud750\ub984\uc744 \ub2e4\uc12f \uc545\uc7a5\uc73c\ub85c \ub4e4\ub824\uc900\ub2e4. 1808\ub144\uc758 \uc774 \uc791\ud488\uc740 \uac01 \uc545\uc7a5\uc5d0 \uc7a5\uba74\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \ud45c\uc81c\uac00 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub4e4\ub9ac\ub294 \uc74c\uc744 \ubaa8\ub450 \uc0ac\ubb3c \ud558\ub098\uc640 \ub9de\ucd94\ub294 \ud034\uc988\ub85c \ub9cc\ub4e4 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud48d\uacbd\uc744 \ub9cc\ub098\ub294 \uc0ac\ub78c\uc758 \uac10\uc815\uc774 \uc5b4\ub5bb\uac8c \ubc14\ub00c\ub294\uc9c0 \ud568\uaed8 \ub4e4\uc5b4 \ubcf4\uc790. \uccab \uc545\uc7a5\uc758 \ud45c\uc81c\ub294 \uc2dc\uace8\uc5d0 \ub3c4\ucc29\ud588\uc744 \ub54c\uc758 \uc990\uac70\uc6b4 \uac10\uc815\uacfc \uc5f0\uacb0\ub41c\ub2e4. \ub9c9 \ub2ec\ub824\uc628 \ub4a4 \uac11\uc790\uae30 \uc644\uc804\ud788 \uba48\ucd94\uae30\ubcf4\ub2e4 \uc791\uc740 \uc6c0\uc9c1\uc784\uc774 \ubc18\ubcf5\ub418\uace0 \uc790\ub77c\uba70 \uacf5\uac04\uc774 \uc5f4\ub9ac\ub294 \ub290\ub08c\uc744 \uc900\ub2e4. \ucc98\uc74c\ubd80\ud130 \ud070 \uc0ac\uac74\uc774 \ud130\uc9c0\uc9c0 \uc54a\uc544\ub3c4 \uc74c\uc545\uc740 \uc6b0\ub9ac\ub97c \uc5b4\ub5a4 \uc7a5\uc18c\ub85c \ub370\ub824\uac08 \uc218 \uc788\ub2e4. \uc8fc\uc81c\uac00 \ub2e4\uc2dc \ub098\uc62c \ub54c\ub9c8\ub2e4 \uc5b4\ub514\uac00 \uac19\uace0 \uc5b4\ub514\uac00 \ub2ec\ub77c\uc9c0\ub294\uc9c0 \ub4e4\uc5b4 \ubcf4\uc790. \ubc18\ubcf5\uc740 \uc9c0\ub8e8\ud55c \ub300\uae30\uac00 \uc544\ub2c8\ub77c \ud55c \ud48d\uacbd\uc5d0 \ub354 \uc624\ub798 \uba38\ubb34\ub294 \uc2dc\uac04\uc774 \ub420 \uc218 \uc788\ub2e4. \ub0af\uc120 \uc7a5\uc18c\uc5d0 \ub3c4\ucc29\ud574 \uc11c\uc11c\ud788 \uc8fc\ubcc0\uc758 \uc18c\ub9ac\ub97c \uc54c\uc544\ub4e3\ub294 \uacbd\ud5d8\uc744 \ub5a0\uc62c\ub824\ub3c4 \uc88b\ub2e4. \ub458\uc9f8 \uc545\uc7a5\uc740 \uc2dc\ub0c7\uac00\uc758 \uc7a5\uba74\uc774\ub2e4. \ud750\ub974\ub294 \ubc18\uc8fc\uc640 \uc120\uc728\uc774 \uc774\uc5b4\uc9c0\uba74\uc11c \uccab \uc545\uc7a5\uc758 \ub3c4\ucc29\uacfc\ub294 \ub2e4\ub978 \uc885\ub958\uc758 \uba38\ubb34\ub984\uc744 \ub290\ub07c\uac8c \ud55c\ub2e4. \ubaa9\uc801\uc9c0\ub85c \ube68\ub9ac \uac00\ub294 \uc6c0\uc9c1\uc784\ubcf4\ub2e4 \uac19\uc740 \uacf3\uc5d0\uc11c \uacc4\uc18d \ud750\ub974\ub294 \ubb3c\uc744 \ub4e3\ub294 \uc2dc\uac04\uc5d0 \uac00\uae5d\ub2e4. \uc774\ub54c \uc5b4\ub5a4 \uc2e4\uc81c \uc2dc\ub0c7\ubb3c\uc744 \uc815\ud655\ud788 \ub179\uc74c\ud574 \uc62e\uae34 \uac83\ucc98\ub7fc \ub4e4\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc545\uae30\uac00 \ub9cc\ub4e0 \ubc18\ubcf5\uacfc \ubcc0\ud654\uac00 \ubb3c\uc758 \ub290\ub08c\uc744 \uc5b4\ub5bb\uac8c \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uba74 \ub41c\ub2e4. \uc790\uc5f0\uc744 \ubb18\uc0ac\ud558\ub294 \uc74c\uc545\uacfc \uc790\uc5f0 \uc18d\uc5d0\uc11c \uc0ac\ub78c\uc774 \ub290\ub07c\ub294 \uc74c\uc545\uc774 \uc11c\ub85c \uac00\uae4c\uc774 \ub193\uc778\ub2e4. \ub458\uc9f8 \uc545\uc7a5 \ub05d \ubb34\ub835\uc758 \uc0c8\uc18c\ub9ac\ub294 \uc720\uba85\ud558\ub2e4. \ud574\uc124 \uc790\ub8cc\ub294 \ub098\uc774\ud305\uac8c\uc77c\uc744 \ud50c\ub8e8\ud2b8, \uba54\ucd94\ub77c\uae30\ub97c \uc624\ubcf4\uc5d0, \ubed0\uafb8\uae30\ub97c \ud074\ub77c\ub9ac\ub137\uacfc \uc5f0\uacb0\ud558\uba70 \uc545\ubcf4\uc5d0 \ud45c\uc9c0\uac00 \uc788\uc74c\uc744 \uc124\uba85\ud55c\ub2e4. \ubaa8\ub4e0 \uc18c\ub9ac\uac00 \ub9c9\uc5f0\ud55c \uccad\uc911\uc758 \uc0c1\uc0c1\ub9cc\uc740 \uc544\ub2c8\ub77c\ub294 \ub73b\uc774\ub2e4. \uba3c\uc800 \uc0c8 \uc774\ub984\uc744 \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc5b4\ub5a4 \uc18c\ub9ac\uac00 \uac00\ubccd\uac8c \uc774\uc5b4\uc9c0\uace0 \uc5b4\ub5a4 \uc18c\ub9ac\uac00 \ubc18\ubcf5\ud574\uc11c \ubd80\ub974\ub294\uc9c0 \ub4e4\uc5b4 \ubcf4\uc790. \uc54c\uace0 \ub4e4\uc73c\uba74 \uc545\uae30\uc758 \ucc28\uc774\ub97c \uc54c\uc544\ubcf4\ub294 \uae38\ub3c4 \ub41c\ub2e4. \ub2e4\ub9cc \uc2e4\uc81c \uc0c8 \uc6b8\uc74c\uc758 \uacfc\ud559\uc801 \ud45c\ubcf8\uc73c\ub85c \ud310\uc815\ud560 \uc77c\uc740 \uc544\ub2c8\ub2e4. \uc74c\uc545 \uc548\uc5d0\uc11c \uc11c\ub85c \ub2e4\ub978 \uc18c\ub9ac\ub4e4\uc774 \ub193\uc774\ub294 \uad00\uacc4\uac00 \uc911\uc694\ud558\ub2e4. \uc2dc\uace8 \uc0ac\ub78c\ub4e4\uc758 \uc990\uac70\uc6b4 \ubaa8\uc784\uc774\ub77c\ub294 \ud45c\uc81c\uac00 \ub098\uc624\uba74 \uc790\uc5f0\ub9cc \ubc14\ub77c\ubcf4\ub358 \uc2dc\uc120\uc774 \uc0ac\ub78c\ub4e4\uc758 \uc6c0\uc9c1\uc784\uc73c\ub85c \ubc14\ub010\ub2e4. \ucda4\uacfc \ubaa8\uc784\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub294 \ub9ac\ub4ec\uc774 \uadc0\ub97c \ubd99\uc7a1\ub294\ub2e4. \uc2dc\uace8\uc740 \ube48 \ub4e4\ud310\uc774 \uc544\ub2c8\ub77c \uc0ac\ub78c\ub4e4\uc774 \ub9cc\ub098 \uc0b4\uc544\uac00\ub294 \uc7a5\uc18c\uc774\uae30\ub3c4 \ud558\ub2e4. \uc778\ubb3c\uc758 \uc5bc\uad74\uc774\ub098 \uad6c\uccb4\uc801\uc778 \uc758\uc0c1\uc744 \uc0c1\uc0c1\ud558\uc9c0 \uc54a\uc544\ub3c4 \uad1c\ucc2e\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc545\uae30\uac00 \ub0b4\ub193\ub294 \uc6c0\uc9c1\uc784\uc774 \uc5bc\ub9c8\ub098 \uac00\ubccd\uac70\ub098 \ud22c\ubc15\ud558\uac8c \ub290\uaef4\uc9c0\ub294\uc9c0 \ub4e4\uc5b4 \ubcf4\uc790. \ud55c \uac00\uc9c0 \uc544\ub984\ub2e4\uc6b4 \ud45c\uc815\uc73c\ub85c\ub9cc \uc790\uc5f0\uc744 \uc124\uba85\ud558\uc9c0 \uc54a\uace0 \uadf8 \uc548\uc758 \ud65c\uae30\uc640 \ubab8\uc758 \ub9ac\ub4ec\uc744 \ub9cc\ub098\ub294 \uc2dc\uac04\uc774 \ub41c\ub2e4. \uc990\uac70\uc6b4 \ubaa8\uc784\uc5d0\uc11c \uac11\uc790\uae30 \ub0a0\uc528\uac00 \ubc14\ub010\ub2e4. \uc18c\ub9ac\uac00 \uac70\uce60\uc5b4\uc9c0\uace0 \uae34\uc7a5\uc774 \ucee4\uc9c0\uba70 \ucc9c\ub465\uacfc \ube44\ubc14\ub78c\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uc55e\uc5d0\uc11c \ucda9\ubd84\ud788 \ud3c9\uc628\uacfc \ud65c\uae30\ub97c \uacbd\ud5d8\ud588\uae30 \ub54c\ubb38\uc5d0 \uc774 \ubcc0\ud654\ub294 \ub354 \ud06c\uac8c \ub2e4\uac00\uc62c \uc218 \uc788\ub2e4. \ud3ed\ud48d\uc774\ub77c\ub294 \uc81c\ubaa9\uc744 \uc54c\uace0 \ub4e4\uc73c\uba74 \ubb34\uc5c7\uc744 \ud45c\ud604\ud558\ub294\uc9c0 \uc27d\uac8c \ub4e4\uc5b4\uac08 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ubaa8\ub4e0 \ud070 \uc18c\ub9ac\ub97c \ubc88\uac1c \ud55c \ubc88, \uc791\uc740 \uc18c\ub9ac\ub97c \ube57\ubc29\uc6b8 \ud558\ub098\ub85c \uc138\uc5b4 \ub9de\ucd9c \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5ec\ub7ec \uc18c\ub9ac\uac00 \ud568\uaed8 \uac15\ub3c4\ub97c \ubc14\uafb8\uba70 \uc548\uc815\ub41c \ub290\ub08c\uc744 \ud754\ub4dc\ub294 \ubc29\uc2dd\uc5d0 \uadc0\ub97c \ub450\uba74 \uc74c\uc545\uc758 \ud070 \ud750\ub984\uc774 \ubcf4\uc778\ub2e4. \ub2e4\uc12f\uc9f8 \uc545\uc7a5\uc740 \ubaa9\ub3d9\uc758 \ub178\ub798\uc640 \ud3ed\ud48d \ub4a4\uc758 \uae30\uc058\uace0 \uac10\uc0ac\ud55c \uac10\uc815\uc73c\ub85c \uc18c\uac1c\ub41c\ub2e4. \ub2e8\uc21c\ud788 \uccab \uc7a5\uba74\uc73c\ub85c \ub3cc\uc544\uac00 \uc544\ubb34 \uc77c\ub3c4 \uc5c6\uc5c8\ub358 \ub4ef \ub05d\ub098\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub4e3\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc774\ubbf8 \ud3ed\ud48d\uc744 \uc9c0\ub098\uc628 \uae30\uc5b5\uc774 \uc788\ub2e4. \uadf8\ub798\uc11c \ub9c8\uc9c0\ub9c9\uc758 \ubd80\ub4dc\ub7ec\uc6c0\uc774 \ucc98\uc74c\uc758 \uc5ec\uc720\uc640 \ub2e4\ub974\uac8c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uc791\ud488 \uc18d \ud48d\uacbd\uc774 \ub2ec\ub77c\uc84c\uae30 \ub54c\ubb38\ub9cc\uc774 \uc544\ub2c8\ub77c \uc6b0\ub9ac\uac00 \uc9c0\ub098\uc628 \uc2dc\uac04 \ub54c\ubb38\uc774\ub2e4. \ud55c \uc545\uc7a5\ub9cc \ub530\ub85c \ub4e4\uc5c8\uc744 \ub54c\uc640 \uc804\uccb4\ub97c \uc774\uc5b4 \ub4e4\uc5c8\uc744 \ub54c\uc758 \ucc28\uc774\uac00 \uc5ec\uae30\uc11c \ubd84\uba85\ud574\uc9c4\ub2e4. \uc804\uc6d0 \uad50\ud5a5\uace1\uc744 \ub2e4\ub8ec \uc61b \ud574\uc124\uc740 \ud48d\uacbd\uc758 \ubb18\uc0ac\ubcf4\ub2e4 \uac10\uc815\uc758 \ud45c\ud604\uc774\ub77c\ub294 \uc791\uace1\uac00\uc758 \uc124\uba85\ub3c4 \uc804\ud55c\ub2e4. \uc7a5\uba74\uc758 \uc774\ub984\uc744 \uc54c\ub824 \uc8fc\uba74\uc11c\ub3c4 \uc790\uc5f0\ubb3c\uc758 \ubaa8\uc0ac\ub9cc\uc73c\ub85c \uc791\ud488\uc744 \ub2eb\uc9c0 \uc54a\uc73c\ub824\ub294 \uc0dd\uac01\uc744 \uc77d\uc744 \uc218 \uc788\ub2e4. \uc624\ub298\uc758 \ub3c5\uc790\ub294 \uc74c\uc545\uc758 \ud45c\uc81c\ub97c \ucd9c\ubc1c\uc810\uc73c\ub85c \uc0bc\ub418 \uac19\uc740 \uac10\uc815\uc744 \ub290\uaef4\uc57c \ud55c\ub2e4\uace0 \uc560\uc4f8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc2dc\ub0c7\uac00\uc5d0\uc11c \ud3c9\uc628\ud568\uc744 \ub290\ub07c\ub294 \uc0ac\ub78c\ub3c4 \uc788\uace0 \ub04a\uc784\uc5c6\uc774 \uc6c0\uc9c1\uc774\ub294 \uc2dc\uac04\uc5d0 \ub354 \uadc0\ub97c \uae30\uc6b8\uc774\ub294 \uc0ac\ub78c\ub3c4 \uc788\ub2e4. \ud48d\uacbd\uc744 \ub9cc\ub09c\ub2e4\ub294 \uc77c\uc5d0\ub3c4 \uac01\uc790\uc758 \uae30\uc5b5\uc774 \ub4e4\uc5b4\uac04\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \ucf54\ub85c\uc758 \ud48d\uacbd\ud654 \u3008\uc791\uc740 \uace8\uc9dc\uae30\u3009\uc758 \uc61b \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \uc790\uc5f0\uc758 \ubd84\uc704\uae30\ub97c \ud568\uaed8 \ub5a0\uc62c\ub9ac\uae30 \uc704\ud574 \uace0\ub978 \uad00\ub828 \ud68c\ud654\uc774\uba70 \ubca0\ud1a0\ubca4\uc774 \uc774 \uadf8\ub9bc\uc744 \ubcf4\uace0 \uc791\uace1\ud588\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc74c\uc545\uc758 \uc2e4\uc81c \uc545\ubcf4\ub098 \ud2b9\uc815 \uc2dc\uace8\uc758 \ubcf5\uc6d0\ub3c4\uc640\ub3c4 \uad6c\ubd84\ub41c\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc2dc\ub0c7\uac00\uc758 \ub458\uc9f8 \uc545\uc7a5\uacfc \ud3ed\ud48d \ub4a4\uc758 \ub9c8\uc9c0\ub9c9 \uc545\uc7a5\uc744 \ube44\uad50\ud574 \ub4e4\uc5b4\ub3c4 \uc88b\ub2e4. \ub2e4\uc74c\uc5d0\ub294 \ub2e4\uc12f \uc545\uc7a5\uc744 \uc774\uc5b4 \ubcf4\uba70 \ub3c4\ucc29\uacfc \uba38\ubb34\ub984, \uc0ac\ub78c\ub4e4\uc758 \ubaa8\uc784\uacfc \ub0a0\uc528\uc758 \ubcc0\ud654\uac00 \uc5b4\ub5a4 \uc21c\uc11c\ub85c \ub9c8\uc74c\uc744 \uc6c0\uc9c1\uc774\ub294\uc9c0 \ub290\uaef4 \ubcf4\uc790. \uad50\ud5a5\uace1\uc774\ub77c\ub294 \uae34 \ud615\uc2dd\uc774 \ud55c \ud48d\uacbd\uc5d0 \uc624\ub798 \uba38\ubb3c \uc5ec\uc720\ub97c \ub9cc\ub4e4\uc5b4 \uc904 \uc218 \uc788\ub2e4."}, {"id": "book-owner-seal", "title": "\ucc45\uc5d0\ub3c4 \uc8fc\uc778\uc758 \uc774\ub984\ud45c\ub97c \ucc0d\uc5b4 \ub450\uc5c8\ub2e4", "summary": "\uc774\ub984\uc744 \uc4f0\uac70\ub098 \uc2a4\ud2f0\ucee4\ub97c \ubd99\uc774\ub4ef, \ucc45\uc5d0 \ub3c4\uc7a5\uc744 \ucc0d\uc5b4 \uc18c\uc7a5\uc744 \ud45c\uc2dc\ud558\uae30\ub3c4 \ud588\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/book-owner-seal/index.html", "image": "../media/book-owner-seal.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00 \uc18c\uc7a5 \uc5f0\uacbd\uc7ac\uc7a5\uc11c\uc778 \uc778\uc7a5\uc758 \ub3cc \ubab8\uccb4 \ubaa8\uc2b5", "text": "\ucc45\uc5d0\ub3c4 \uc8fc\uc778\uc758 \uc774\ub984\ud45c\ub97c \ucc0d\uc5b4 \ub450\uc5c8\ub2e4 \uc791\uc740 \uc5f0\uacbd\uc7ac\uc7a5\uc11c\uc778\uc774 \uc54c\ub824\uc8fc\ub294 \ucc45\uacfc \ub3c4\uc7a5\uc758 \uad00\uacc4 \uc774\ub984\uc744 \uc4f0\uac70\ub098 \uc2a4\ud2f0\ucee4\ub97c \ubd99\uc774\ub4ef, \ucc45\uc5d0 \ub3c4\uc7a5\uc744 \ucc0d\uc5b4 \uc18c\uc7a5\uc744 \ud45c\uc2dc\ud558\uae30\ub3c4 \ud588\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \ucc45\uc744 \ube4c\ub824\uc8fc\uae30 \uc804\uc5d0 \uccab \uc7a5\uc5d0 \uc774\ub984\uc744 \uc368 \ub454 \uacbd\ud5d8\uc774 \uc788\uc744 \uac83\uc774\ub2e4. \ub098\uc911\uc5d0 \ub3cc\uc544\uc654\uc744 \ub54c \ub204\uad6c\uc758 \ucc45\uc778\uc9c0 \uc54c\uc544\ubcfc \uc218 \uc788\uac8c \ud558\ub824\ub294 \uc791\uc740 \ud45c\uc2dc\ub2e4. \uc61b \ucc45\uacfc \uc11c\ud654\uc5d0\uc11c\ub294 \uadf8\ub7f0 \uc5ed\ud560\uc744 \ud558\ub294 \ub3c4\uc7a5\ub3c4 \ub9cc\ub09c\ub2e4. \uc7a5\uc11c\uc778\uc774\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc5d0\ub294 \u2018\uc5f0\uacbd\uc7ac\uc7a5\uc11c\uc778\u2019\uc774\ub77c\ub294 \uae00\uc790\ub97c \uc0c8\uae34 \ub3cc\ub3c4\uc7a5\uc774 \uc788\ub2e4. \uc0ac\uc9c4 \uc18d\uc758 \ubab8\uccb4\ub294 \uc190\uc5d0 \ub4e4\uc5b4\uc62c \ub9cc\ud55c \ud06c\uae30\uc758 \uc791\uc740 \ub3cc\uc774\ub2e4. \uadf8\ub7f0\ub370 \uadf8 \ub3c4\uc7a5\uc774 \ub0a8\uae30\ub294 \uae00\uc790\uc5d0\ub294 \ucc45\uc774 \uba38\ubb3c\ub358 \uacf3\uc758 \uc774\ub984\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc774 \uc778\uc7a5\uc774 \uc5f0\uacbd\uc7ac\uc5d0 \uc18c\uc7a5\ud55c \uc11c\uc801\uacfc \uc11c\ud654 \ub4f1\uc5d0 \ucc0d\ub358 \uac83\uc774\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \uc81c\ubaa9\uc758 \u2018\uc7a5\uc11c\u2019\ub294 \ucc45\uc744 \ubaa8\uc544 \uc18c\uc7a5\ud55c\ub2e4\ub294 \ub9d0\uc774\ub2e4. \ub3c4\uc7a5\uc740 \uc791\uc740 \uc774\ub984\ud45c\uac00 \ub418\uc5b4 \uc18c\uc7a5 \uad00\uacc4\ub97c \ub4dc\ub7ec\ub0c8\ub2e4. \uc11c\uba85\uacfc \ub2ee\uc740 \uc810\ub3c4 \uc788\uc9c0\ub9cc \ud55c \ubc88 \uc0c8\uae34 \uae00\uc790\ub97c \uc5ec\ub7ec \uacf3\uc5d0 \ubc18\ubcf5\ud574 \ucc0d\uc744 \uc218 \uc788\ub2e4\ub294 \ucc28\uc774\uac00 \uc788\ub2e4. \ucc45\uc774 \uc5ec\ub7ec \uad8c\uc774\uc5b4\ub3c4 \uac19\uc740 \ub3c4\uc7a5\uc73c\ub85c \ud45c\uc2dc\ud560 \uc218 \uc788\ub2e4. \uc190\uc73c\ub85c \ub9e4\ubc88 \uac19\uc740 \uae00\uc790\ub97c \uc4f0\ub294 \uac83\uacfc\ub294 \ub2e4\ub978 \uc7ac\ubbf8\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc61b \ucc45\uc758 \ub3c4\uc7a5\uc774 \ubaa8\ub450 \uac19\uc740 \ubaa9\uc801\uc774\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774 \uc774\uc57c\uae30\uc5d0\uc11c \uc0b4\ud3b4\ubcf4\ub294 \uac83\uc740 \uc18c\uc7a5\uc744 \ud45c\uc2dc\ud558\ub294 \uc7a5\uc11c\uc778 \ud55c \uc810\uc774\ub2e4. \uc778\uc7a5\uc758 \uc138\uacc4\uc5d0\ub294 \uad6d\uac00 \uc5c5\ubb34\uc6a9 \ub3c4\uc7a5\ubd80\ud130 \uac1c\uc778\uc774 \uc4f0\ub294 \ub3c4\uc7a5\uae4c\uc9c0 \uc5ec\ub7ec \uc885\ub958\uac00 \uc788\uc5c8\ub2e4. \uc774 \uc778\uc7a5\uc758 \uc0ac\uc6a9\uc790\uc5d0 \ub300\ud574 \ubc15\ubb3c\uad00\uc740 \u2018\ud5cc\uc885 \ucd94\uc815\u2019\uc774\ub77c\uace0 \uc801\uc5b4 \ub454\ub2e4. \ud5cc\uc885\uc774 \uc0ac\uc6a9\ud588\ub2e4\uace0 \ud655\uc815\ud558\ub294 \ub300\uc2e0, \ud604\uc7ac\uc758 \ud310\ub2e8\uc5d0 \uc5ec\uc9c0\ub97c \ub0a8\uae34 \uc124\uba85\uc774\ub2e4. \uc720\ubb3c \uc774\ub984\uc774 \ub610\ub837\ud558\uac8c \uc801\ud600 \uc788\uc5b4\ub3c4 \uadf8 \uc774\ub825\uc758 \ubaa8\ub4e0 \ubd80\ubd84\uc744 \uac19\uc740 \uc815\ub3c4\ub85c \uc544\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc774 \uc0c8\uaca8\uc838 \uc788\ub294\uc9c0\uc640 \ub204\uac00 \uc2e4\uc81c\ub85c \uc0ac\uc6a9\ud588\ub294\uc9c0\ub294 \ub2e4\ub978 \uc9c8\ubb38\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \ubc15\ubb3c\uad00\uc758 \uc124\uba85\uc5d0\ub294 \ud5cc\uc885\uc774 \uc5ec\ub7ec \uc61b \uc778\uc7a5\uc744 \uc218\uc9d1\ud558\uace0 \uac10\uc0c1\ud588\uc73c\uba70 \uac1c\uc778\uc6a9 \uc778\uc7a5\ub3c4 \uc0ac\uc6a9\ud588\ub2e4\ub294 \uc774\uc57c\uae30\uac00 \ud568\uaed8 \ub098\uc628\ub2e4. \ub2e4\ub9cc \uadf8 \uc77c\ubc18\uc801\uc778 \ubc30\uacbd\uc774 \uc774 \ud55c \uc810\uc758 \uc0ac\uc6a9\uc790 \ucd94\uc815\uc744 \ud655\uc815\uc73c\ub85c \ubc14\uafb8\uc5b4 \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc6b0\ub9ac\uac00 \ucc59\uae38 \uac83\uc740 \uc5b4\ub824\uc6b4 \uc655\uc2e4 \uacc4\ubcf4\ubcf4\ub2e4 \uc774 \uc791\uc740 \ub9d0\uc758 \ucc28\uc774\ub2e4. \u2018\ucd94\uc815\u2019\uc774\ub77c\ub294 \ub450 \uae00\uc790\ub97c \uadf8\ub300\ub85c \ub450\uc5b4\ub3c4 \ub3c4\uc7a5\uc744 \uad6c\uacbd\ud558\ub294 \uc7ac\ubbf8\ub294 \ucda9\ubd84\ud558\ub2e4. \uac19\uc740 \uc81c\ubaa9\uc758 \ucc45\uc774\ub77c\ub3c4 \uc5b4\ub290 \uc9d1\uc774\ub098 \uae30\uad00\uc5d0 \uc788\uc5c8\ub294\uc9c0\uc5d0 \ub530\ub77c \uc11c\ub85c \ub2e4\ub978 \ud754\uc801\uc774 \ub0a8\uc744 \uc218 \uc788\ub2e4. \uc7a5\uc11c\uc778\uc740 \uadf8 \ud754\uc801 \uac00\uc6b4\ub370 \ud558\ub098\ub2e4. \ubcf8\ubb38\uc744 \uc77d\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc800\uc790\uc758 \ubb38\uc7a5\uc774 \uba3c\uc800 \uc911\uc694\ud558\uc9c0\ub9cc, \ucc45\uc744 \ubb3c\uac74\uc73c\ub85c \uc0b4\ud3b4\ubcf4\ub294 \uc0ac\ub78c\uc740 \ub204\uac00 \uc18c\uc7a5\ud558\uace0 \uc5b4\ub5bb\uac8c \uc62e\uaca8 \uac14\ub294\uc9c0\ub3c4 \ubb3b\ub294\ub2e4. \ub3c4\uc7a5 \ud558\ub098\uac00 \uadf8 \ub450 \ubc88\uc9f8 \uc77d\uae30\ub97c \uc5f4\uc5b4 \uc900\ub2e4. \uc18c\uc720 \ud45c\uc2dc\uac00 \uc788\ub2e4\uace0 \ucc45\uc758 \ubaa8\ub4e0 \uc774\ub3d9 \uacbd\ub85c\uac00 \uace7 \uc644\uc131\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc778\uc7a5\uc774 \ucc0d\ud78c \ub54c\uc640 \uc774\ud6c4\uc758 \uc804\ub798\ub97c \ub2e4\ub978 \uc790\ub8cc\uc640 \ube44\uad50\ud574\uc57c \ud55c\ub2e4. \uadf8\ub798\ub3c4 \uc544\ubb34 \ud754\uc801 \uc5c6\ub294 \ud45c\uba74\uacfc\ub294 \uc9c8\ubb38\uc758 \ucd9c\ubc1c\uc810\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uac19\uc740 \uae00\uc790\uac00 \ub2e4\ub978 \ucc45\uc5d0\ub3c4 \ucc0d\ud600 \uc788\ub2e4\uba74 \uc5b4\ub5a4 \ubb36\uc74c\uc5d0 \uc18d\ud588\ub294\uc9c0 \uc0b4\ud3b4\ubcfc \uac00\ub2a5\uc131\uc774 \uc0dd\uae34\ub2e4. \uc791\uc740 \ud45c\uc9c0\uac00 \uc18c\uc7a5\uc758 \uad00\uacc4\ub97c \uc774\uc5b4 \uc8fc\ub294 \uac83\uc774\ub2e4. \uc778\uc7a5\uc740 \uc0c8\uaca8 \ub454 \uba74\uc5d0 \uc0c9\uc744 \ubb3b\ud600 \ub2e4\ub978 \ud45c\uba74\uc5d0 \ucc0d\ub294 \ub3c4\uad6c\ub2e4. \uc190\uc73c\ub85c \ub9e4\ubc88 \uac19\uc740 \uae00\uc790\ub97c \uc4f0\ub294 \ub300\uc2e0 \uac19\uc740 \ubaa8\uc591\uc744 \ubc18\ubcf5\ud574\uc11c \ub0a8\uae38 \uc218 \uc788\ub2e4. \ub3c4\uc7a5 \uc790\uccb4\uc758 \uc870\ud615\uacfc \ucc0d\ud78c \uc790\uad6d\uc740 \uc11c\ub85c \ub2e4\ub978 \ub300\uc0c1\uc73c\ub85c \ubcfc \uc218 \uc788\ub2e4. \ub3cc\ub85c \ub41c \ubb3c\uac74\uc744 \uac10\uc0c1\ud560 \ub54c\uc640 \ucc45\uc758 \uc5ec\ubc31\uc5d0\uc11c \uc778\uc601\uc744 \ucc3e\uc744 \ub54c \ub208\uc5ec\uaca8\ubcf4\ub294 \uc810\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc0ac\uc9c4\uc73c\ub85c \uc778\uc7a5\uc744 \ub9cc\ub09c\ub2e4\uba74 \uc0c8\uaca8\uc9c4 \uba74\uacfc \ubab8\uccb4, \uc7a1\ub294 \ubd80\ubd84\uc744 \uad6c\ubcc4\ud574 \ubcfc \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc774\ubbf8\uc9c0\uc5d0\uc11c \ubcf4\uc774\ub294 \uae00\uc790\ub97c \uadf8\ub300\ub85c \uc77d\uc5c8\ub2e4\uace0 \uc2e4\uc81c \ucc0d\ud614\uc744 \ub54c\uc758 \ubc29\ud5a5\uae4c\uc9c0 \uac19\uc740 \uac83\uc73c\ub85c \uc5ec\uaca8\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc0ac\uc6a9\ud574 \ub0a8\uae34 \uc790\uad6d\uacfc \ub3c4\uad6c\uc758 \uc0c1\ud0dc\ub97c \ud568\uaed8 \ud655\uc778\ud558\uba74 \ub354 \uc815\ud655\ud558\ub2e4. \ubb3c\uac74\uc758 \ubaa8\uc591\uc774 \ud589\ub3d9\uc744 \uac70\uccd0 \ub2e4\ub978 \uae30\ub85d\uc73c\ub85c \uc62e\uaca8 \uac00\ub294 \uad6c\uc870\ub97c \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc5f0\uacbd\uc7ac\uc5d0 \uc18c\uc7a5\ud55c \ucc45\uacfc \uc11c\ud654\uc5d0 \uc0ac\uc6a9\ud55c \uc778\uc7a5\uc774\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \uc774\ub984\uc740 \uc18c\uc7a5 \uacf5\uac04\uacfc \uad00\uacc4\ub97c \uc54c\ub824 \uc8fc\uc9c0\ub9cc \uac1c\ubcc4 \ucc45\ub9c8\ub2e4 \uc5b8\uc81c \ub204\uac00 \uc9c1\uc811 \ucc0d\uc5c8\ub294\uc9c0\uae4c\uc9c0 \uae30\ub85d\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uacf5\uac04\uc758 \uc774\ub984\uacfc \uc0ac\uc6a9\uc790\uc758 \uc774\ub984\ub3c4 \uc5b8\uc81c\ub098 \uac19\uc740 \uce35\uc758 \uc815\ubcf4\ub294 \uc544\ub2c8\ub2e4. \ud45c\uc2dc\uac00 \ubb34\uc5c7\uc744 \uac00\ub9ac\ud0a4\ub294\uc9c0 \uba3c\uc800 \uad6c\ubcc4\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4. \ud5cc\uc885\uc758 \uc778\uc7a5 \uc218\uc9d1\uacfc \uac10\uc0c1\uc774\ub77c\ub294 \ubc30\uacbd\uc740 \uc774 \ubb3c\uac74\uc744 \uc2dc\ub300 \uc548\uc5d0 \ub193\ub294 \ub370 \ub3c4\uc6c0\uc744 \uc900\ub2e4. \uadf8\ub7ec\ub098 \uc77c\ubc18\uc801\uc778 \ubc30\uacbd\ub9cc\uc73c\ub85c \ud55c \uc810\uc758 \uc0ac\uc6a9\uc790\uae4c\uc9c0 \ud655\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ubc15\ubb3c\uad00\uc774 \ucd94\uc815\uc774\ub77c\uace0 \ub0a8\uae34 \ud45c\ud604\uc744 \uc720\uc9c0\ud558\uba74 \uc774\uc57c\uae30\uac00 \ub35c \uc7ac\ubbf8\uc788\uc5b4\uc9c0\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \ud655\uc2e4\ud55c \ubd80\ubd84\uacfc \ub0a8\uc740 \uc9c8\ubb38\uc744 \ud568\uaed8 \uac00\uc9c4 \ubb3c\uac74\uc73c\ub85c \ub354 \uc138\ubc00\ud558\uac8c \ubcf4\uac8c \ub41c\ub2e4. \uc624\ub298\uc758 \ucc45\uc5d0\ub3c4 \uc774\ub984\uc744 \uc801\uac70\ub098 \ucc45\uac08\ud53c\ub97c \ub123\uace0 \uba54\ubaa8\ub97c \ub0a8\uae34\ub2e4. \uc774\uac83\uc744 \uc655\uc2e4\uc758 \uc7a5\uc11c\uc778\uacfc \uac19\uc740 \uc81c\ub3c4\ub77c\uace0 \ud560 \uc218\ub294 \uc5c6\uc9c0\ub9cc, \ud14d\uc2a4\ud2b8\ub97c \ub2f4\uc740 \ubb3c\uac74\uc5d0 \uc0ac\uc6a9\uc790\uc758 \ud754\uc801\uc774 \ub354\ud574\uc9c4\ub2e4\ub294 \uc810\uc740 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \ud55c \uad8c\uc774 \uac19\uc740 \uc778\uc1c4 \ub0b4\uc6a9\ub9cc\uc73c\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\ub294 \uc774\uc720\ub2e4. \uc77d\uace0 \ubcf4\uad00\ud558\uace0 \uac74\ub124\ub294 \ud589\ub3d9\uc774 \ucc45\uc758 \uc2dc\uac04\uc744 \ub298\ub9b0\ub2e4. \uc7a5\uc11c\uc778\uc744 \ubcf4\uc558\uc744 \ub54c\uc5d0\ub294 \uae00\uc790 \ubaa8\uc591\uc744 \uc0b4\ud540 \ub4a4 \uc5b4\ub514\uc5d0 \uc0ac\uc6a9\ud588\ub2e4\uace0 \uc124\uba85\ud558\ub294\uc9c0 \uc77d\uc5b4 \ubcf4\uc790. \uc778\uc7a5\uc758 \uc7ac\ub8cc\uc640 \uc0c8\uae40\uc740 \uc81c\uc791\uc744, \uc18c\uc7a5 \ud45c\uc2dc\ub294 \ucc45\uacfc \uc0ac\ub78c\uc758 \uad00\uacc4\ub97c \ubcf4\uc5ec \uc900\ub2e4. \ub3c5\uc11c\uc758 \uc5ed\uc0ac\ub294 \ubb34\uc5c7\uc744 \uc77d\uc5c8\ub294\uc9c0\ub9cc\uc774 \uc544\ub2c8\ub77c \uc5b4\ub5a4 \ubb3c\uac74\uc744 \ubaa8\uc73c\uace0 \uc54c\uc544\ubcf4\uba70 \ubcf4\uad00\ud588\ub294\uc9c0\ub3c4 \ud3ec\ud568\ud55c\ub2e4. \uc791\uc740 \ub3cc \ub3c4\uc7a5\uc5d0 \uadf8\ub7f0 \uc8fc\ubcc0\uc758 \uc2dc\uac04\uc774 \ub2f4\uaca8 \uc788\ub2e4. \ucc45\uc5d0\uc11c \uc77d\uc744\uac70\ub9ac\ub294 \ubcf8\ubb38\uc5d0\ub9cc \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc774\ub984\uc744 \uc801\uc740 \uc790\ub9ac, \uc18c\uc7a5 \ud45c\uc2dc, \ub204\uad70\uac00 \ub0a8\uae34 \uba54\ubaa8\ub3c4 \uadf8 \ucc45\uc774 \uc9c0\ub098\uc628 \uc2dc\uac04\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc7a5\uc11c\uc778\uc744 \ubcf4\uba74 \uae00\uc790\ub97c \uc77d\ub294 \ubc29\uc2dd\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \ubb38\uc7a5\uc758 \ub73b\ub9cc \uc774\ud574\ud558\ub824\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uc65c \uadf8 \uc790\ub9ac\uc5d0 \uadf8 \uc774\ub984\uc744 \ub0a8\uacbc\ub294\uc9c0 \uad81\uae08\ud574\uc9c4\ub2e4. \uac19\uc740 \ucc45\uc774\ub77c\ub3c4 \ub204\uad6c\uc758 \ucc45\uc7a5\uc5d0 \uc788\uc5c8\ub294\uc9c0\uac00 \ub610 \ud558\ub098\uc758 \uc774\uc57c\uae30\uac00 \ub420 \uc218 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \uc624\ub798\ub41c \ucc45\uc758 \uccab \uc7a5\uc5d0\uc11c \uc791\uc740 \uc778\uc7a5\uc744 \ubc1c\uacac\ud55c\ub2e4\uba74 \ubcf8\ubb38\uc73c\ub85c \ubc14\ub85c \ub118\uc5b4\uac00\uae30 \uc804\uc5d0 \uc7a0\uae50 \ubcf4\uc544\ub3c4 \uc88b\uaca0\ub2e4. \ucc45\uc5d0 \ub2f4\uae34 \uc774\uc57c\uae30 \uc606\uc5d0, \ucc45\uc744 \uac00\uc9c0\uace0 \uc788\ub358 \uc0ac\ub78c\uc758 \ud754\uc801\uc774 \ucc0d\ud600 \uc788\uc744\uc9c0\ub3c4 \ubaa8\ub978\ub2e4."}, {"id": "botticelli-venus-shell-wind-shore", "title": "\u300c\ube44\ub108\uc2a4\uc758 \ud0c4\uc0dd\u300d \u2014 \uc870\uac1c \uc704\uc758 \uc5ec\uc778\uc740 \uc5b4\ub514\ub85c \uac00\ub294\uac00", "summary": "\uc2e4\uc81c \uc791\ud488\uc744 \ubcf4\uba70 \uc870\uac1c\uc640 \ubc14\ub78c, \ub9dd\ud1a0\uc640 \uc120\uc758 \uc6c0\uc9c1\uc784\uc774 \ub9cc\ub4dc\ub294 \uc2e0\ud654\uc758 \ud55c\uc21c\uac04\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/botticelli-venus-shell-wind-shore/index.html", "image": "../media/botticelli-venus-shell-wind-shore.jpg", "alt": "\uc870\uac1c \uc704 \ube44\ub108\uc2a4\uc640 \uc67c\ucabd\uc758 \ubc14\ub78c, \uc624\ub978\ucabd\uc5d0\uc11c \ub9dd\ud1a0\ub97c \ub4e0 \uc778\ubb3c\uc774 \uc788\ub294 \ubcf4\ud2f0\uccbc\ub9ac\uc758 \ube44\ub108\uc2a4\uc758 \ud0c4\uc0dd", "text": "\u300c\ube44\ub108\uc2a4\uc758 \ud0c4\uc0dd\u300d \u2014 \uc870\uac1c \uc704\uc758 \uc5ec\uc778\uc740 \uc5b4\ub514\ub85c \uac00\ub294\uac00 \uc81c\ubaa9\ubcf4\ub2e4 \uba3c\uc800 \ubc14\ub78c\uc758 \ubc29\ud5a5\uc744 \ub530\ub77c \uc77d\ub294 \ubcf4\ud2f0\uccbc\ub9ac \uc2e4\uc81c \uc791\ud488\uc744 \ubcf4\uba70 \uc870\uac1c\uc640 \ubc14\ub78c, \ub9dd\ud1a0\uc640 \uc120\uc758 \uc6c0\uc9c1\uc784\uc774 \ub9cc\ub4dc\ub294 \uc2e0\ud654\uc758 \ud55c\uc21c\uac04\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \uac70\ub300\ud55c \uc870\uac1c \uc704\uc5d0 \ud55c \uc5ec\uc778\uc774 \uc11c \uc788\ub2e4. \uc67c\ucabd\uc5d0\uc11c\ub294 \ub450 \uc778\ubb3c\uc774 \ubc14\ub78c\uc744 \ubd88\uace0, \uc624\ub978\ucabd\uc5d0\uc11c\ub294 \ub2e4\ub978 \uc5ec\uc778\uc774 \uc637\uc744 \ud3bc\uccd0 \uae30\ub2e4\ub9b0\ub2e4. \u300c\ube44\ub108\uc2a4\uc758 \ud0c4\uc0dd\u300d\uc740 \uc81c\ubaa9\uc744 \uc54c\uace0 \ubcf4\uba74 \uc775\uc219\ud55c \uba85\ud654\uc9c0\ub9cc, \ud654\uba74\uc744 \ucc9c\ucc9c\ud788 \uc0b4\ud53c\uba74 \ub73b\ubc16\uc5d0 \uc6c0\uc9c1\uc784\uc774 \ub9ce\uc740 \uadf8\ub9bc\uc774\ub2e4. \uc5ec\uae30\uc5d0 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \ubcf4\ud2f0\uccbc\ub9ac\uc758 \uc2e4\uc81c \uc791\ud488\uc744 \uc61b \ubbf8\uc220\uc11c\uc5d0 \ubcf5\uc81c\ud55c \ub3c4\ud310\uc774\ub2e4. \uc0c8\ub85c \ub9cc\ub4e0 \uc0c1\uc0c1 \uadf8\ub9bc\uc774 \uc544\ub2c8\ub2e4. \uc624\ub798\ub41c \uc778\uc1c4\ubb3c\uc758 \uc0c9\uc740 \uc6d0\ud654\uc640 \ucc28\uc774\uac00 \uc788\uc744 \uc218 \uc788\ub2e4. \uc124\uba85\uc740 \ud5e8\ub9ac \ube0c\ub77c\uc774\uc5b8 \ube48\uc2a4\uc758 \u300e\ubcf4\ud2f0\uccbc\ub9ac\u300f\uc5d0\uc11c \uc791\ud488\uc744 \ub2e4\ub8ec \ub300\ubaa9\uc744 \ucc38\uace0\ud558\ub418, \uc800\uc790\uc758 \uac1c\uc778\uc801\uc778 \uac10\uc0c1\uacfc \ud655\uc778\ud560 \uc218 \uc788\ub294 \ud654\uba74\uc744 \uad6c\ubd84\ud588\ub2e4. \uc911\uc559\uc758 \uc5ec\uc778\uc740 \ub85c\ub9c8 \uc2e0\ud654\uc758 \uc0ac\ub791\uacfc \uc544\ub984\ub2e4\uc6c0\uc758 \uc5ec\uc2e0 \ube44\ub108\uc2a4\ub2e4. \uc81c\ubaa9\uc740 \ud0c4\uc0dd\uc744 \ub9d0\ud558\uc9c0\ub9cc \ud654\uba74\uc740 \uc544\uae30\uac00 \ud0dc\uc5b4\ub098\ub294 \uc7a5\uba74\uc774 \uc544\ub2c8\ub2e4. \uc774\ubbf8 \uc131\uc219\ud55c \ubaa8\uc2b5\uc758 \uc5ec\uc2e0\uc774 \ubc14\ub2e4\uc5d0\uc11c \uc721\uc9c0\ub85c \ub2e4\uac00\uc624\ub294 \uc21c\uac04\uc5d0 \uac00\uae5d\ub2e4. \uadf8\ub9bc\uc744 \ucc98\uc74c \ubcf4\ub294 \uc0ac\ub78c\uc774 \uc7a5\uba74\uc744 \uc774\ud574\ud560 \ub54c \uac00\uc7a5 \uba3c\uc800 \ud480\uc5b4 \ub450\uba74 \uc88b\uc740 \uc810\uc774\ub2e4. \uac70\ub300\ud55c \uc870\uac1c \uc5ed\uc2dc \uc790\uc5f0 \uad00\ucc30 \uadf8\ub9bc \uc18d\uc758 \uc0ac\uc2e4\uc801\uc778 \ubc30\uac00 \uc544\ub2c8\ub2e4. \uc2e0\ud654\uc758 \ubc14\ub2e4\uc5d0\uc11c \uc5ec\uc2e0\uc744 \uc62e\uae30\ub294 \ubc1b\uce68\uc774\uc790, \ud654\uba74\uc758 \uc911\uc559\uc744 \ub113\uac8c \ubc1b\uccd0 \uc8fc\ub294 \ud615\ud0dc\ub2e4. \uc0ac\ub78c\uc774 \uc2e4\uc81c\ub85c \uc800 \uc870\uac1c \uc704\uc5d0 \uc124 \uc218 \uc788\ub294\uc9c0 \ub530\uc9c0\uae30 \uc2dc\uc791\ud558\uba74 \ud654\uac00\uac00 \ub9cc\ub4e0 \ub2e4\ub978 \uc885\ub958\uc758 \uc9c8\uc11c\ub97c \ub193\uce58\uac8c \ub41c\ub2e4. \uc2dc\uc120\uc744 \uc67c\ucabd\uc73c\ub85c \uc62e\uae30\uba74 \ubc14\ub78c\uc744 \ubd80\ub294 \uc778\ubb3c\uacfc \uadf8\uc5d0\uac8c \ubab8\uc744 \uae30\ub300\ub294 \ub3d9\ubc18\uc790\uac00 \ubcf4\uc778\ub2e4. \uc785\uc220\uc5d0\uc11c \ub098\uc628 \ubc14\ub78c\uc740 \ub208\uc5d0 \ubcf4\uc774\uc9c0 \uc54a\uc9c0\ub9cc \uba38\ub9ac\uce74\ub77d\uacfc \uc637\uc790\ub77d, \ub5a0\ub2e4\ub2c8\ub294 \uaf43\uc744 \uc6c0\uc9c1\uc778\ub2e4. \ubc14\ub78c\uc744 \uc9c1\uc811 \uce60\ud558\ub294 \ub300\uc2e0 \ubc14\ub78c\uc5d0 \ubc18\uc751\ud558\ub294 \uac83\ub4e4\uc744 \uadf8\ub824 \uadf8 \ud798\uc744 \ub290\ub07c\uac8c \ud55c\ub2e4. \uadf8 \ud798\uc744 \ub530\ub77c \uc911\uc559\uc73c\ub85c \ub3cc\uc544\uc624\uba74 \ube44\ub108\uc2a4\uc758 \uba38\ub9ac\uce74\ub77d\ub3c4 \ud55c\ucabd\uc73c\ub85c \ud758\ub7ec\uac04\ub2e4. \ub2e4\uc2dc \uc624\ub978\ucabd\uc5d0\uc11c\ub294 \uaf43\ubb34\ub2ac \uc637\uc744 \uc785\uc740 \uc778\ubb3c\uc774 \ud070 \ub9dd\ud1a0\ub97c \ud3bc\uccd0 \ub4e0\ub2e4. \ud654\uba74\uc758 \uc138 \ubb34\ub9ac\ub294 \ub5a8\uc5b4\uc838 \uc11c \uc788\uc9c0\ub9cc \uac19\uc740 \uc0ac\uac74\uc5d0 \ucc38\uc5ec\ud55c\ub2e4. \ubcf4\ub0b4\ub294 \ucabd, \ub3c4\ucc29\ud558\ub294 \uc874\uc7ac, \ub9de\uc774\ud558\ub294 \ucabd\uc774 \uc774\uc5b4\uc9c0\ub294 \uc148\uc774\ub2e4. \ube44\ub108\uc2a4\uc758 \ubab8\uc740 \uc548\uc815\ub41c \uc870\uac01\uc0c1\ucc98\ub7fc \ub2e8\ub2e8\ud788 \uc11c \uc788\uae30\ubcf4\ub2e4 \uae38\uace0 \uac00\ub298\uac8c \ud754\ub4e4\ub9ac\ub294 \ub290\ub08c\uc744 \uc900\ub2e4. \uba38\ub9ac\uc758 \uae30\uc6b8\uae30\uc640 \uc5b4\uae68, \ubab8\uc758 \uace1\uc120\uc774 \uc774\uc5b4\uc9c0\uace0 \uba38\ub9ac\uce74\ub77d\uc774 \ub2e4\uc2dc \uc120\uc744 \ub9cc\ub4e0\ub2e4. \ud574\ubd80\ud559 \uad50\uacfc\uc11c\uc758 \uc815\ud655\ud55c \uc790\uc138\ub97c \ud655\uc778\ud558\ub294 \ub208\uc73c\ub85c\ub9cc \ubcf4\uba74 \uc5b4\uc0c9\ud55c \ubd80\ubd84\uc774 \uba3c\uc800 \ubcf4\uc77c \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \ubcf4\ud2f0\uccbc\ub9ac\uc758 \ud654\uba74\uc5d0\uc11c\ub294 \ubc14\ub85c \uadf8 \uae34 \uc120\uc774 \uc911\uc694\ud558\ub2e4. \uc778\ubb3c\uc758 \ubb34\uac8c\ubcf4\ub2e4 \ub9ac\ub4ec\uc744 \uc55e\uc138\uc6cc, \ubc14\ub78c\uacfc \ubab8\uacfc \uc637\uc774 \ud55c \uc120\uc728 \uc548\uc5d0 \uc788\ub294 \ub4ef \ubcf4\uc774\uac8c \ud55c\ub2e4. \ube44\ud604\uc2e4\uc801\uc778 \ube44\ub840\ub97c \ubaa8\ub450 \uc2e4\uc218\ub85c \ucc98\ub9ac\ud560 \ud544\uc694\ub3c4, \ubc18\ub300\ub85c \uc5b4\ub5a4 \uacfc\uc7a5\ub3c4 \ucc9c\uc7ac\uc758 \uc554\ud638\ub77c\uace0 \ub5a0\ubc1b\ub4e4 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ud654\uba74\uc5d0\uc11c \uc5b4\ub5a4 \ud6a8\uacfc\ub97c \ub9cc\ub4dc\ub294\uc9c0 \uba3c\uc800 \ubcf4\uba74 \ub41c\ub2e4. \ube44\ub108\uc2a4\ub294 \uc190\uacfc \uba38\ub9ac\uce74\ub77d\uc73c\ub85c \ubab8\uc758 \uc77c\ubd80\ub97c \uac00\ub9b0\ub2e4. \uc774\ub7f0 \uc790\uc138\ub294 \uace0\uc804 \ubbf8\uc220\uc758 \uc5ec\uc2e0 \ud45c\ud604\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uc644\uc804\ud788 \uac10\ucd94\uc9c0\ub3c4, \uc544\ubb34\ub807\uc9c0 \uc54a\uac8c \ub4dc\ub7ec\ub0b4\uc9c0\ub3c4 \uc54a\ub294 \ub3d9\uc791\uc774\uc5b4\uc11c \ubcf4\ub294 \uc2dc\uc120\uc744 \uc758\uc2dd\ud558\uac8c \ub9cc\ub4e0\ub2e4. \uc544\ub984\ub2e4\uc6c0\uc758 \uc5ec\uc2e0\uc740 \uc790\uc2e0\uc774 \ubcf4\uc774\ub294 \uc874\uc7ac\ub77c\ub294 \uc0ac\uc2e4\uacfc \ud568\uaed8 \ub4f1\uc7a5\ud55c\ub2e4. \uc624\ub978\ucabd\uc758 \ub9dd\ud1a0\ub3c4 \uac19\uc740 \uc8fc\uc81c\ub97c \uc787\ub294\ub2e4. \uace7 \ubab8\uc744 \ub36e\uc744 \uc637\uc774 \uc900\ube44\ub418\uc5b4 \uc788\uc9c0\ub9cc \uc544\uc9c1 \ub2ff\uc9c0 \uc54a\uc558\ub2e4. \ub3c4\ucc29\uacfc \ud658\uc601, \ub4dc\ub7ec\ub0a8\uacfc \uac00\ub9bc \uc0ac\uc774\uc758 \uc9e7\uc740 \uc2dc\uac04\uc774 \ud654\uba74\uc5d0 \uba48\ucdb0 \uc788\ub2e4. \ud070 \uc0ac\uac74\uc758 \uc808\uc815 \ub300\uc2e0 \uadf8 \uc9c1\uc804\uc758 \uc21c\uac04\uc744 \uc624\ub798 \ubcf4\uac8c \ud558\ub294 \uac83\uc774 \uc774 \uadf8\ub9bc\uc758 \ubb18\ubbf8\ub2e4. \ubc14\ub2e4\uc758 \uc791\uc740 \ubb3c\uacb0\uc740 \ubc18\ubcf5\ub418\uace0, \ud574\uc548\uc758 \ub098\ubb34\uc640 \ud480\uc740 \ucd18\ucd18\ud558\uac8c \uc790\ub9ac\ub97c \uc7a1\ub294\ub2e4. \uc778\ubb3c\uc758 \uba38\ub9ac\uce74\ub77d\uacfc \uc9c1\ubb3c\uc5d0\ub294 \ub354 \ud48d\uc131\ud55c \uace1\uc120\uc774 \uc0dd\uae34\ub2e4. \uc2dc\uc120\uc740 \ub113\uc740 \ubc14\ud0d5\uacfc \uc12c\uc138\ud55c \ubb34\ub2ac \uc0ac\uc774\ub97c \uc624\uac04\ub2e4. \uba40\ub9ac\uc11c \ubcfc \ub54c\uc758 \ub2e8\uc21c\ud568\uacfc \uac00\uae4c\uc774 \ubcfc \ub54c\uc758 \uc7a5\uc2dd\uc131\uc774 \ud568\uaed8 \uc788\ub294 \uadf8\ub9bc\uc774\ub2e4. \ube48\uc2a4\ub294 \uc774 \uc791\ud488\uc5d0\uc11c \ucc28\uac00\uc6b4 \ubc14\ub2e4\uc758 \uc0c9\uacfc \ubd89\uc740 \uc637\uc758 \ub300\ube44\uc5d0\ub3c4 \uc8fc\ubaa9\ud55c\ub2e4. \uc624\ub298\uc758 \ubcf5\uc81c \ub3c4\ud310\uc5d0\uc11c\ub294 \uc0c9\uc744 \uc815\ud655\ud788 \ud310\ub2e8\ud558\uae30 \uc5b4\ub824\uc6b4 \ubd80\ubd84\uc774 \uc788\uc9c0\ub9cc, \ub113\uc740 \ubc14\ub2e4\uc640 \uc624\ub978\ucabd \uc9c1\ubb3c\uc774 \uc11c\ub85c \ub2e4\ub978 \ub369\uc5b4\ub9ac\ub97c \ub9cc\ub4e0\ub2e4\ub294 \uac83\uc740 \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \uc0c9 \uc774\ub984\uc744 \uc678\uc6b0\uae30\ubcf4\ub2e4 \ud654\uba74\uc774 \uc5b4\ub514\uc5d0\uc11c \ucc28\ubd84\ud558\uace0 \uc5b4\ub514\uc5d0\uc11c \ud48d\uc131\ud574\uc9c0\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uba74 \uc88b\ub2e4. 15\uc138\uae30 \ud53c\ub80c\uccb4\uc758 \ubcf4\ud2f0\uccbc\ub9ac\uc5d0\uac8c \uace0\ub300 \uc2e0\ud654\ub294 \uc0c8\ub85c\uc6b4 \uadf8\ub9bc\uc758 \uc5b8\uc5b4\uac00 \ub418\uc5c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub974\ub124\uc0c1\uc2a4 \uc0ac\ub78c\ub4e4\uc774 \uc885\uad50\ub97c \ubc84\ub9ac\uace0 \uadf8\ub9ac\uc2a4\u00b7\ub85c\ub9c8 \uc774\uc57c\uae30\ub9cc \ubcf4\uae30 \uc2dc\uc791\ud588\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ubcf4\ud2f0\uccbc\ub9ac \uc790\uc2e0\ub3c4 \uc885\uad50\ud654\ub97c \uadf8\ub838\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc8fc\uc81c\uc640 \ud6c4\uc6d0, \uc0dd\uac01\uc774 \uac19\uc740 \uc2dc\ub300 \uc548\uc5d0 \ud568\uaed8 \uc874\uc7ac\ud588\ub2e4. \uc774 \uc791\ud488\uc744 \ub204\uac00 \uc5b4\ub5a4 \ub300\ud654 \ub05d\uc5d0 \uc8fc\ubb38\ud588\ub294\uc9c0, \uc5ec\uc2e0\uc758 \uc5bc\uad74\uc774 \uc815\ud655\ud788 \ub204\uad6c\ub97c \ub2ee\uc558\ub294\uc9c0\uc5d0\ub294 \ub110\ub9ac \uc54c\ub824\uc9c4 \uc5ec\ub7ec \uc124\uba85\uc774 \ubd99\ub294\ub2e4. \uadf8\ub7ec\ub098 \ud765\ubbf8\ub85c\uc6b4 \uc774\ub984\uc774 \ub4f1\uc7a5\ud55c\ub2e4\uace0 \ubaa8\ub450 \ud655\uc815\ub41c \uc0ac\uc2e4\uc740 \uc544\ub2c8\ub2e4. \ubaa8\ub378\uc758 \uc5f0\uc560 \uc0ac\uc5f0\uc744 \ub2e8\uc815\ud558\uc9c0 \uc54a\uc544\ub3c4 \ubc14\ub78c\uacfc \ucc9c\uacfc \ubab8\uc758 \uad00\uacc4\ub9cc\uc73c\ub85c \uadf8\ub9bc\uc740 \ucda9\ubd84\ud788 \ud48d\ubd80\ud558\ub2e4. \uc61b \ubbf8\uc220\uc11c\uc758 \uc800\uc790\ub294 \uc790\uc2e0\uc758 \ubcf4\ud2f0\uccbc\ub9ac\uc0c1\uc744 \ubc14\ud0d5\uc73c\ub85c \uc774 \uc5ec\uc778\uc744 \ud2b9\ubcc4\ud55c \ubba4\uc988\ucc98\ub7fc \ud574\uc11d\ud558\uae30\ub3c4 \ud55c\ub2e4. \uadf8\ub7f0 \uae00\uc740 \ud55c \uc2dc\ub300\uac00 \uba85\ud654\ub97c \uc5b4\ub5bb\uac8c \uc0ac\ub791\ud588\ub294\uc9c0 \uc54c\ub824 \uc900\ub2e4. \ub2e4\ub9cc \uc791\uac00\uc758 \uac10\uc0c1\uc744 \uadf8\ub9bc\uc758 \ub4f1\uc7a5\uc778\ubb3c\uc744 \ud655\uc815\ud558\ub294 \ubb38\uc11c\ucc98\ub7fc \ubc1b\uc544\ub4e4\uc774\uc9c0\ub294 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \ub2e4\uc2dc \uadf8\ub9bc\uc744 \ubcf4\uba74 \uc624\ub978\ucabd \ub9dd\ud1a0\uac00 \uace7 \ube44\ub108\uc2a4\uc5d0\uac8c \ub2ff\uc744 \uac83 \uac19\ub2e4. \uadf8\ub7f0\ub370 \ubc14\ub78c\uc740 \uc544\uc9c1 \ubd88\uace0, \uc5ec\uc2e0\uc758 \ubc1c\uc740 \uc5ec\uc804\ud788 \uc870\uac1c \uc704\uc5d0 \uc788\ub2e4. \uc6b0\ub9ac\uac00 \ubcf4\ub294 \uac83\uc740 \ud55c \uc2e0\uc758 \uc774\ub984\uc744 \uc124\uba85\ud558\ub294 \uc0bd\ud654\ub9cc\uc774 \uc544\ub2c8\ub2e4. \ud55c \uc874\uc7ac\uac00 \uc0c8\ub85c\uc6b4 \uc138\uacc4\uc5d0 \ub9c9 \ub3c4\ucc29\ud55c \uc21c\uac04\uc774\ub2e4. \uc81c\ubaa9\uc744 \uc7a0\uae50 \uc78a\uace0 \ubc14\ub78c\ubd80\ud130 \ub530\ub77c\uac00\uba74 \uc624\ub798\ub41c \uba85\ud654\ub3c4 \uc870\uae08 \uc0c8\ub86d\uac8c \uc6c0\uc9c1\uc774\uae30 \uc2dc\uc791\ud55c\ub2e4."}, {"id": "bremen-old-animals-and-new-home", "title": "\ube0c\ub808\uba58 \uc74c\uc545\ub300 \u2014 \ub124 \ub3d9\ubb3c\uc740 \uc65c \ubaa9\uc801\uc9c0\uc5d0 \ub3c4\ucc29\ud558\uc9c0 \uc54a\uc558\uc744\uae4c", "summary": "\uadf8\ub9bc \ud615\uc81c\uc758 \uc6d0\uc791\uc744 \ub530\ub77c \uc77d\ub294 \ub299\uc74c\u00b7\ud611\ub825\u00b7\uc0c8\ub85c\uc6b4 \uac70\ucc98\uc744 \uc774\uc57c\uae30\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc2e0\ud654\uc640 \ubbfc\uc18d", "categories": ["arts"], "url": "stories/bremen-old-animals-and-new-home/index.html", "image": "../media/bremen-old-animals-and-new-home.png", "alt": "\uc232\uae38\uc5d0\uc11c \uc9d1\uc744 \ud5a5\ud574 \uac00\ub294 \ub2f9\ub098\uadc0\uc640 \uac1c, \uace0\uc591\uc774, \uc218\ud0c9 \uc0bd\ud654", "text": "\ube0c\ub808\uba58 \uc74c\uc545\ub300 \u2014 \ub124 \ub3d9\ubb3c\uc740 \uc65c \ubaa9\uc801\uc9c0\uc5d0 \ub3c4\ucc29\ud558\uc9c0 \uc54a\uc558\uc744\uae4c \uadf8\ub9bc \ud615\uc81c\uc758 \uc6d0\uc791\uc744 \ub530\ub77c \uc77d\ub294 \ub299\uc74c\u00b7\ud611\ub825\u00b7\uc0c8\ub85c\uc6b4 \uac70\ucc98 \uadf8\ub9bc \ud615\uc81c\uc758 \uc6d0\uc791\uc744 \ub530\ub77c \uc77d\ub294 \ub299\uc74c\u00b7\ud611\ub825\u00b7\uc0c8\ub85c\uc6b4 \uac70\ucc98\uc744 \uc774\uc57c\uae30\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc2e0\ud654\uc640 \ubbfc\uc18d \ubb38\ud654\uc640 \uc608\uc220 \ub2f9\ub098\uadc0 \uc704\uc5d0 \uac1c, \uadf8 \uc704\uc5d0 \uace0\uc591\uc774, \ub9e8 \uc704\uc5d0 \uc218\ud0c9. \u300e\ube0c\ub808\uba58 \uc74c\uc545\ub300\u300f\ub97c \uc77d\uc9c0 \uc54a\uc740 \uc0ac\ub78c\ub3c4 \ub124 \ub3d9\ubb3c\uc774 \ucc28\ub840\ub85c \uc62c\ub77c\uc120 \ubaa8\uc2b5\uc740 \ubcf8 \uc801\uc774 \uc788\uc744 \uac83\uc774\ub2e4. \uc81c\ubaa9\uc744 \ub4e4\uc73c\uba74 \ube0c\ub808\uba58\uc5d0\uc11c \uc5f0\uc8fc\ud68c\ub97c \uc5ec\ub294 \uc774\uc57c\uae30\ucc98\ub7fc \ub290\uaef4\uc9c0\uc9c0\ub9cc, \uc2e4\uc81c \uacb0\ub9d0\uc740 \uc870\uae08 \ub2e4\ub974\ub2e4. \uadf8\ub9bc \ud615\uc81c\uc758 \ub3d9\ud654\uc5d0\uc11c \ub3d9\ubb3c\ub4e4\uc740 \ube0c\ub808\uba58\uae4c\uc9c0 \uac00\uc9c0 \uc54a\ub294\ub2e4. \ub3c4\uc911\uc5d0 \uc0c8\ub85c\uc6b4 \uc0b6\uc758 \uc790\ub9ac\ub97c \ucc3e\uace0 \uadf8\uacf3\uc5d0 \ub0a8\ub294\ub2e4. \uc774 \uc9e7\uc740 \uc904\uac70\ub9ac\ub97c \ucc98\uc74c\ubd80\ud130 \ub530\ub77c\uac00 \ubcf4\uba74 \uadc0\uc5ec\uc6b4 \ub3d9\ubb3c \uadf8\ub9bc \ub4a4\uc5d0 \ub299\uc74c\uacfc \uc4f8\ubaa8, \ub3d9\ub8cc\uc640 \uc9d1\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\uac00 \uc228\uc5b4 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubc1c\uacac\ud558\uac8c \ub41c\ub2e4. \uc8fc\uc778\uc744 \uc704\ud574 \uc624\ub7ab\ub3d9\uc548 \uace1\uc2dd \uc790\ub8e8\ub97c \ub098\ub974\ub358 \ub2f9\ub098\uadc0\ub294 \ud798\uc774 \uc57d\ud574\uc9c4\ub2e4. \ub354\ub294 \uc608\uc804\ucc98\ub7fc \uc77c\ud558\uc9c0 \ubabb\ud558\uc790 \uc8fc\uc778\uc774 \uc790\uc2e0\uc744 \uacc4\uc18d \uba39\uc5ec \uc0b4\ub9ac\uc9c0 \uc54a\uc744 \uac83 \uac19\ub2e4\uace0 \ub290\ub080\ub2e4. \ub2f9\ub098\uadc0\ub294 \uadf8\uacf3\uc744 \ub5a0\ub098 \ube0c\ub808\uba58\uc73c\ub85c \uac00\uc11c \ub3c4\uc2dc\uc758 \uc74c\uc545\uac00\uac00 \ub418\uaca0\ub2e4\ub294 \uacc4\ud68d\uc744 \uc138\uc6b4\ub2e4. \ucd9c\ubc1c\uc758 \uc774\uc720\uac00 \uc74c\uc545\uc5d0 \ub300\ud55c \uc21c\uc218\ud55c \uafc8\ub9cc\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \ub2f9\ub098\uadc0\ub294 \uba3c\uc800 \uc0b4\uc544\ub0a8\uc744 \uae38\uc744 \ucc3e\uc544\uc57c \ud55c\ub2e4. \uc624\ub798 \uc77c\ud55c \uc7a5\uc18c\uac00 \ub354\ub294 \uc548\uc804\ud55c \uc9d1\uc774 \ub418\uc9c0 \ubabb\ud558\ub294 \uc0c1\ud669\uc774\ub2e4. \ub3d9\ud654\ub294 \uc5b4\ub824\uc6b4 \uc81c\ub3c4\ub97c \uc124\uba85\ud558\uc9c0 \uc54a\uc73c\uba74\uc11c\ub3c4, \uc4f8\ubaa8\uac00 \uc904\uc5c8\ub2e4\uace0 \uc5ec\uaca8\uc9c0\ub294 \uc874\uc7ac\uc758 \ub450\ub824\uc6c0\uc744 \uace7\ubc14\ub85c \ubcf4\uc5ec \uc900\ub2e4. \uae38\uc5d0\uc11c \ub2f9\ub098\uadc0\ub294 \uc0ac\ub0e5\uc744 \uc798\ud558\uc9c0 \ubabb\ud558\uac8c \ub41c \uac1c\uc640 \uc950\ub97c \uc7a1\uae30 \uc5b4\ub824\uc6cc\uc9c4 \uace0\uc591\uc774\ub97c \ub9cc\ub09c\ub2e4. \ub458 \ub2e4 \uc774\uc804\uc758 \uc77c\uc744 \uacc4\uc18d\ud560 \uc218 \uc5c6\uc5b4 \uc704\ud5d8\uc5d0 \ub193\uc600\ub2e4. \uc218\ud0c9\uc740 \uc870\uae08 \ub2e4\ub974\ub2e4. \uc190\ub2d8\uc5d0\uac8c \ub300\uc811\ud560 \uc74c\uc2dd\uc774 \ub420 \ucc98\uc9c0\ub2e4. \ub124 \ub3d9\ubb3c\uc758 \uad6c\uccb4\uc801\uc778 \uc0ac\uc815\uc740 \uac19\uc9c0 \uc54a\uc9c0\ub9cc \uba38\ubb3c\ub358 \uacf3\uc5d0\uc11c \uc0dd\uba85\uc744 \uc9c0\ud0a4\uae30 \uc5b4\ub835\ub2e4\ub294 \uc810\uc774 \ub2ee\uc558\ub2e4. \ub2f9\ub098\uadc0\ub294 \ub3d9\ub8cc\ub4e4\uc5d0\uac8c \ud568\uaed8 \uc74c\uc545\uac00\uac00 \ub418\uc790\uace0 \uad8c\ud55c\ub2e4. \ud55c \ub3d9\ubb3c\uc5d0\uac8c\ub294 \uc9d6\ub294 \uc18c\ub9ac\uac00 \uc788\uace0 \ub2e4\ub978 \ub3d9\ubb3c\uc5d0\uac8c\ub294 \uc6b8\uc74c\uc18c\ub9ac\uac00 \uc788\ub2e4. \uc8fc\uc778\uc774 \uc6d0\ud558\ub358 \uc77c\uc744 \ubabb\ud55c\ub2e4\uace0 \ud574\uc11c \uac00\uc9c4 \ub2a5\ub825\uc774 \uc804\ubd80 \uc5c6\uc5b4\uc9c4 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub3d9\ud654\ub294 \ubb34\uc5c7\uc744 \uc798\ud558\ub294\uc9c0 \ud310\ub2e8\ud558\ub294 \uc790\ub9ac\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub124 \ub3d9\ubb3c\uc740 \ud558\ub8e8 \ub9cc\uc5d0 \ube0c\ub808\uba58\uae4c\uc9c0 \uac08 \uc218 \uc5c6\uc5c8\ub2e4. \uc232\uc5d0\uc11c \ubc24\uc744 \ubcf4\ub0b4\ub824\ub294\ub370 \ub192\uc740 \uacf3\uc5d0 \uc62c\ub77c\uac04 \uc218\ud0c9\uc774 \uba40\ub9ac \ubd88\ube5b\uc744 \ubc1c\uacac\ud55c\ub2e4. \uadf8 \ube5b\uc744 \ub530\ub77c\uac04 \uacf3\uc5d0\ub294 \ub3c4\ub451\ub4e4\uc774 \uc74c\uc2dd\uc744 \ucc28\ub824 \ub193\uace0 \uc788\ub294 \uc9d1\uc774 \uc788\ub2e4. \ucd94\uc704\uc640 \ud5c8\uae30\uc5d0 \uc9c0\uce5c \ub3d9\ubb3c\ub4e4\uc5d0\uac8c \ubd88\ube5b\uc740 \uc74c\uc545\uac00\uc758 \uba85\uc608\ubcf4\ub2e4 \ub354 \uae09\ud55c \uac00\ub2a5\uc131\uc774\ub2e4. \uc774 \uc7a5\uba74\uc5d0\uc11c \uc774\uc57c\uae30\uc758 \ubaa9\ud45c\uac00 \uc870\uc6a9\ud788 \ubc14\ub010\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ube0c\ub808\uba58\uc774\ub77c\ub294 \ub3c4\uc2dc\uc640 \uc0c8\ub85c\uc6b4 \uc9c1\uc5c5\uc774 \uc788\uc5c8\ub2e4. \uc774\uc81c\ub294 \uc624\ub298 \ubc24 \uba39\uc744 \uac83\uacfc \uc548\uc804\ud558\uac8c \uc7a0\ub4e4 \uc790\ub9ac\uac00 \ud544\uc694\ud558\ub2e4. \ud070 \uafc8\uc744 \uc774\ub8e8\ub294 \uacfc\uc815\uc5d0\uc11c \uc791\uc740 \ud734\uc2dd\uc774 \ub4f1\uc7a5\ud55c \uac83 \uac19\uc9c0\ub9cc, \uacb0\uad6d \ubc14\ub85c \uadf8 \uc27c\ud130\uac00 \uc0c8\ub85c\uc6b4 \uc0b6\uc758 \uc911\uc2ec\uc774 \ub41c\ub2e4. \ub3d9\ubb3c\ub4e4\uc740 \ud798\uc744 \ud569\uccd0 \ub3c4\ub451\uc744 \ubab0\uc544\ub0bc \uacc4\ud68d\uc744 \uc138\uc6b4\ub2e4. \ub2f9\ub098\uadc0\uac00 \ucc3d\uac00\uc5d0 \uc11c\uace0 \uadf8 \uc704\ub85c \uac1c\uc640 \uace0\uc591\uc774, \uc218\ud0c9\uc774 \ucc28\ub840\ub85c \uc62c\ub77c\uac04\ub2e4. \uadf8\ub7f0 \ub2e4\uc74c \ub3d9\uc2dc\uc5d0 \uc6b8\ubd80\uc9d6\uc73c\uba70 \uc548\uc73c\ub85c \ub6f0\uc5b4\ub4e0\ub2e4. \ub180\ub780 \ub3c4\ub451\ub4e4\uc740 \ubb34\uc11c\uc6b4 \uc874\uc7ac\uac00 \ub098\ud0c0\ub0ac\ub2e4\uace0 \uc5ec\uae30\uace0 \ub2ec\uc544\ub09c\ub2e4. \uc774\uac83\uc774 \ub3d9\ud654\uc5d0\uc11c \ucc98\uc74c \uc774\ub8e8\uc5b4\uc9c0\ub294 \ud569\ub3d9 \uacf5\uc5f0\uc778 \uc148\uc774\ub2e4. \uc544\ub984\ub2e4\uc6b4 \ud654\uc74c\uc740 \uc544\ub2c8\uc9c0\ub9cc \ub124 \ub3d9\ubb3c\uc758 \uc18c\ub9ac\ub294 \ubd84\uba85\ud55c \uc77c\uc744 \ud574\ub0b8\ub2e4. \ud63c\uc790\uc77c \ub54c\ub294 \uc57d\ud55c \ub3d9\ubb3c\uc774 \ud568\uaed8 \uc788\uc744 \ub54c \uc608\uc0c1\ud558\uc9c0 \ubabb\ud55c \ud798\uc744 \ub9cc\ub4e0\ub2e4. \ubab8\uc744 \ud3ec\uac1c\ub294 \uc720\uba85\ud55c \ubaa8\uc2b5\uc740 \ub2e8\uc21c\ud55c \uc7a5\ub09c\uc774 \uc544\ub2c8\ub77c \uc774 \ud611\ub825\uc744 \ub208\uc5d0 \ubcf4\uc774\uac8c \ud558\ub294 \uc7a5\uba74\uc774\ub2e4. \ubc24\uc911\uc5d0 \ub3c4\ub451 \ud55c \uba85\uc774 \uc9d1\uc744 \uc0b4\ud53c\ub7ec \ub3cc\uc544\uc628\ub2e4. \uc5b4\ub460 \uc18d\uc5d0\uc11c \uace0\uc591\uc774\uc5d0\uac8c \ud560\ud034\uc774\uace0 \uac1c\uc5d0\uac8c \ubb3c\ub9ac\uba70 \ub2f9\ub098\uadc0\uc5d0\uac8c \ucc28\uc774\uace0 \uc218\ud0c9\uc758 \uc18c\ub9ac\uae4c\uc9c0 \ub4e3\ub294\ub2e4. \uadf8\ub294 \uc2e4\uc81c \ub3d9\ubb3c\ub4e4\uc744 \uc81c\ub300\ub85c \ud30c\uc545\ud558\uc9c0 \ubabb\ud55c \ucc44 \uc9d1 \uc548\uc5d0 \ubb34\uc2dc\ubb34\uc2dc\ud55c \uc874\uc7ac\ub4e4\uc774 \uc788\ub2e4\uace0 \ub3d9\ub8cc\ub4e4\uc5d0\uac8c \uc124\uba85\ud55c\ub2e4. \ub3c5\uc790\ub294 \ubb34\uc2a8 \uc77c\uc774 \uc77c\uc5b4\ub0ac\ub294\uc9c0 \uc54c\uc9c0\ub9cc \ub3c4\ub451\uc740 \ubaa8\ub978\ub2e4. \ubc14\ub85c \uc774 \ucc28\uc774\uac00 \uc6c3\uc74c\uc744 \ub9cc\ub4e0\ub2e4. \ucc98\uc74c\uc758 \uc18c\ub3d9\ub9cc\uc73c\ub85c \uc774\uc57c\uae30\uac00 \ub05d\ub098\uc9c0 \uc54a\uace0, \ub450 \ubc88\uc9f8 \ubc29\ubb38\uc5d0\uc11c \uc624\ud574\uac00 \ub354 \ucee4\uc9c0\ub294 \uad6c\uc131\ub3c4 \uc7ac\ubbf8\uc788\ub2e4. \uac70\ub300\ud55c \ud798\uc744 \uc5bb\uc740 \ub3d9\ubb3c\ub4e4\uc774 \uc544\ub2c8\ub77c \uac01\uc790\uc758 \uc790\ub9ac\uc5d0 \ub204\uc6cc \uc788\ub358 \ub3d9\ubb3c\ub4e4\uc774 \ub450\ub824\uc6c0\uc758 \ub300\uc0c1\uc744 \ub9cc\ub4e4\uc5b4 \ub0b8\ub2e4. \ub3c4\ub451\ub4e4\uc774 \ub5a0\ub09c \ub4a4 \ub3d9\ubb3c\ub4e4\uc740 \uadf8 \uc9d1\uc5d0\uc11c \uacc4\uc18d \uc0b4\uae30\ub85c \ud55c\ub2e4. \uc81c\ubaa9\uc5d0 \uc788\ub294 \ub3c4\uc2dc\ub85c \uac00\uc11c \uacf5\uc2dd \uc74c\uc545\ub300\uac00 \ub418\ub294 \uc7a5\uba74\uc740 \ub098\uc624\uc9c0 \uc54a\ub294\ub2e4. \uc6d0\ub798\uc758 \uacc4\ud68d\uc744 \ub2ec\uc131\ud558\uc9c0 \ubabb\ud588\ub294\ub370\ub3c4 \uacb0\ub9d0\uc774 \uc2e4\ud328\ucc98\ub7fc \ub290\uaef4\uc9c0\uc9c0 \uc54a\ub294 \uc774\uc720\ub294 \ubb34\uc5c7\uc77c\uae4c. \ucd9c\ubc1c \ub2f9\uc2dc \ubd80\uc871\ud588\ub358 \uac83\ub4e4\uc744 \uc774\ubbf8 \uc5bb\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4. \uadf8\ub4e4\uc5d0\uac8c \ud544\uc694\ud55c \uac83\uc740 \uc0b4\uc544\ub0a8\uc744 \uc218 \uc788\ub294 \uc7a5\uc18c\uc640 \ud568\uaed8\ud560 \ub3d9\ub8cc\uc600\ub2e4. \ube0c\ub808\uba58\uc740 \uadf8 \uac00\ub2a5\uc131\uc744 \uc0c1\uc0c1\ud558\uac8c \ud55c \uc774\ub984\uc774\uc9c0\ub9cc \uc720\uc77c\ud55c \ub2f5\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ubaa9\uc801\uc9c0\ub97c \ubc14\uafb8\ub294 \uc77c\uacfc \uc0b6\uc744 \ud3ec\uae30\ud558\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uc774 \ub3d9\ud654\uc758 \ub9c8\uc9c0\ub9c9\uc740 \uc131\uacf5\uc758 \ubaa8\uc591\uc744 \ucd9c\ubc1c\ud560 \ub54c \uc815\ud55c \uc9c1\uc5c5 \ud558\ub098\ub85c \ubb36\uc5b4 \ub450\uc9c0 \uc54a\ub294\ub2e4. \ub124 \ub3d9\ubb3c\uc774 \ub3c4\ub451\uc744 \ub180\ub77c\uac8c \ud558\ub294 \uc7a5\uba74\uc740 \uc5b4\ub9b0 \ub3c5\uc790\uc5d0\uac8c\ub3c4 \uc990\uac81\ub2e4. \ud558\uc9c0\ub9cc \ub098\uc774\uac00 \ub4e0 \ub3c5\uc790\ub294 \ucc98\uc74c\uc5d0 \ubc84\ub824\uc9c8 \uc704\uae30\uc5d0 \ub193\uc778 \ub3d9\ubb3c\ub4e4\uc744 \ub354 \uc624\ub798 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uac19\uc740 \uc774\uc57c\uae30 \uc548\uc5d0\uc11c \uc6c3\uc74c\uc758 \uc7a5\uba74\uacfc \ubd88\uc548\uc758 \uc7a5\uba74\uc774 \uc774\uc5b4\uc9c0\ub294 \uac83\uc774 \uc774 \ub3d9\ud654\uac00 \uc624\ub798 \uc77d\ud788\ub294 \uc774\uc720 \uac00\uc6b4\ub370 \ud558\ub098\ub2e4. \ub124 \ub3d9\ubb3c\uc5d0\uac8c \uc0c8 \uc9d1\uc744 \uc900 \uac83\uc740 \ub2e4\uc2dc \uc80a\uc5b4\uc9c0\ub294 \ub9c8\ubc95\uc774 \uc544\ub2c8\ub2e4. \ubab8\uc740 \uc5ec\uc804\ud788 \uc774\uc804\uacfc \uac19\uc9c0\ub9cc \ub3d9\ub8cc\uc640 \uacf5\uac04\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ub299\uc74c\uc744 \uc5c6\uc564 \ub4a4\uc5d0 \ud589\ubcf5\ud574\uc9c0\ub294 \uacb0\ub9d0\uc774 \uc544\ub2c8\ub77c\ub294 \uc810\uc774 \uc774 \uc774\uc57c\uae30\uc758 \uc704\uc548\uc744 \ub354\uc6b1 \ud2b9\ubcc4\ud558\uac8c \ub9cc\ub4e0\ub2e4. \uc774\uac83\uc744 \ud604\uc2e4\uc758 \ubaa8\ub4e0 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub294 \ucc98\ubc29\uc73c\ub85c \ubc14\uafc0 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \ub354\ub294 \uc608\uc804\ucc98\ub7fc \uc77c\ud558\uc9c0 \ubabb\ud558\ub294 \uc874\uc7ac\uc5d0\uac8c\ub3c4 \uc0c8\ub85c\uc6b4 \uad00\uacc4\uc640 \uc790\ub9ac\uac00 \uac00\ub2a5\ud558\ub2e4\ub294 \uc0c1\uc0c1\uc740 \ub0a8\ub294\ub2e4. \u300e\ube0c\ub808\uba58 \uc74c\uc545\ub300\u300f\ub294 \ub3c4\uc2dc\uc5d0 \ub3c4\ucc29\ud55c \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub77c, \uae38\uc5d0\uc11c \ub9cc\ub09c \uc774\ub4e4\uc774 \ud568\uaed8 \uc9d1\uc744 \uc5bb\ub294 \uc774\uc57c\uae30\ub85c \uc77d\uc744 \ub54c \ub354\uc6b1 \ub530\ub73b\ud574\uc9c4\ub2e4."}, {"id": "building-repair-letter", "title": "\uac74\ubb3c\uc744 \uace0\uce58\ub294 \uc77c\uc740 \uae00\ub85c\ub3c4 \ub0a8\uc558\ub2e4", "summary": "\ub0a1\uc740 \uac74\ubb3c\uc744 \uc190\ubcf4\ub294 \uc77c\uc5d0\ub3c4 \uae30\ub150\ubb38\uc774 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uc885\uc774 \ud55c \uc7a5\uc5d0\uc11c \uc61b \uacf5\uc0ac\uc758 \uc0ac\uc815\uc744 \uc77d\uc5b4 \ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uac74\ucd95", "categories": ["arts"], "url": "stories/building-repair-letter/index.html", "image": "../media/building-repair-letter.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00 \uc18c\uc7a5 \uc120\ub989 \uc815\uc790\uac01 \uc911\uc218 \uc0c1\ub7c9\ubb38\uc758 \uae00\uc528\uac00 \ubcf4\uc774\ub294 \uacf5\uac1c \uc0ac\uc9c4", "text": "\uac74\ubb3c\uc744 \uace0\uce58\ub294 \uc77c\uc740 \uae00\ub85c\ub3c4 \ub0a8\uc558\ub2e4 \uc120\ub989 \uc815\uc790\uac01 \uc0c1\ub7c9\ubb38\uc5d0 \ub2f4\uae34 \uc218\ub9ac\uc758 \uae30\ub85d \ub0a1\uc740 \uac74\ubb3c\uc744 \uc190\ubcf4\ub294 \uc77c\uc5d0\ub3c4 \uae30\ub150\ubb38\uc774 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uc885\uc774 \ud55c \uc7a5\uc5d0\uc11c \uc61b \uacf5\uc0ac\uc758 \uc0ac\uc815\uc744 \uc77d\uc5b4 \ubd05\ub2c8\ub2e4. \uac74\ucd95 \ubb38\ud654\uc640 \uc608\uc220 \uc624\ub798\ub41c \uac74\ubb3c \uc55e\uc5d0\uc11c\ub294 \uc5b8\uc81c \ucc98\uc74c \uc138\uc6e0\ub294\uc9c0\ubd80\ud130 \ubb3b\uac8c \ub41c\ub2e4. \ud558\uc9c0\ub9cc \ucc98\uc74c \uc9c0\uc740 \ub0a0\ub9cc\uc73c\ub85c \uac74\ubb3c\uc758 \uae34 \uc2dc\uac04\uc744 \ub2e4 \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \uae30\uc6b8\uc5b4\uc9c4 \uacf3\uc744 \ubc14\ub85c\uc7a1\uace0 \uc624\ub798\ub41c \ubd80\ubd84\uc744 \uace0\uce5c \uc2dc\uac04\ub3c4 \uc788\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \u300c\uc120\ub989 \uc815\uc790\uac01 \uc911\uc218 \uc0c1\ub7c9\ubb38\u300d\uc740 \uadf8\ub7f0 \uc77c\uc744 \uae00\ub85c \ub0a8\uae34 \uc790\ub8cc\ub2e4. \uc0ac\uc9c4\uc73c\ub85c \ubcf4\uba74 \uc885\uc774 \uc704\uc5d0 \uae00\uc790\uac00 \uae38\uac8c \uc774\uc5b4\uc838 \uc788\ub2e4. \uac74\ubb3c\uc758 \uadf8\ub9bc\uc774\ub098 \uc124\uacc4\ub3c4\ub97c \uae30\ub300\ud588\ub2e4\uba74 \uc870\uae08 \ub2e4\ub978 \ubaa8\uc2b5\uc774\ub2e4. \uc774 \uae00\uc5d0\ub294 \ubb34\uc5c7\uc744 \uace0\ucce4\uace0 \uc65c \uc190\uc744 \ubcf4\uc544\uc57c \ud588\ub294\uc9c0\uac00 \ub2f4\uaca8 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc774 \uc0c1\ub7c9\ubb38\uc774 1706\ub144 \uc120\ub989\uc758 \uc815\uc790\uac01\uc744 \uc911\uac74\ud560 \ub54c \uc791\uc131\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc624\ub79c \uc138\uc6d4 \ub3d9\uc548 \uc11d\ubb3c\uacfc \uc815\uc790\uac01\uc744 \ubcf4\uc218\ud574\uc57c \ud55c\ub2e4\ub294 \ud544\uc694\uac00 \uc81c\uae30\ub418\uc5c8\uace0, \uc2e4\uc81c\ub85c \uae30\uc6b8\uc5b4\uc9c4 \uac74\ubb3c\uc744 \ub2e4\uc2dc \uc190\ubcf4\uac8c \ub41c \uac83\uc774\ub2e4. \uae00\uc744 \uc9c0\uc740 \uc0ac\ub78c\uc740 \uc870\uc120 \ud6c4\uae30\uc758 \ubb38\uc2e0 \ucd5c\uc11d\ud56d\uc774\ub2e4. \uac19\uc740 \ub0b4\uc6a9\uc774 \uadf8\uc758 \ubb38\uc9d1\uc5d0\ub3c4 \uc2e4\ub824 \uc788\ub2e4\uace0 \ud55c\ub2e4. \ubc15\ubb3c\uad00\uc5d0 \ub0a8\uc740 \uc885\uc774\uc640 \ucc45 \uc18d\uc758 \uae00\uc774 \uc11c\ub85c \uc5f0\uacb0\ub41c\ub2e4. \uc0c1\ub7c9\ubb38\uc740 \uac74\ubb3c\uc744 \uc138\uc6b0\uac70\ub098 \uace0\uce58\ub294 \uc77c\uc744 \uae30\ub150\ud558\uace0 \uc798 \ub9c8\ubb34\ub9ac\ub418\uae30\ub97c \ubc14\ub77c\ub294 \uae00\uc774\ub2e4. \uc774 \uc790\ub8cc\uc758 \ubc88\uc5ed\uc5d0\uc11c\ub3c4 \uae30\ub465\uacfc \ucc98\ub9c8\uac00 \ube44\ubc14\ub78c\uc744 \uacaa\uc740 \uc0ac\uc815, \uc218\uc120\uc744 \ub2a6\ucd9c \uc218 \uc5c6\ub2e4\ub294 \ub73b\uc744 \uc77d\uc744 \uc218 \uc788\ub2e4. \uacf5\uc0ac\ub97c \uc544\ub984\ub2e4\uc6b4 \uc77c\ub85c\ub9cc \uafb8\ubbf8\ub294 \uae00\uc778 \uc904 \uc54c\uc558\ub294\ub370, \uc624\ub798\ub41c \uac74\ubb3c\uc774 \uacac\ub38c \uc628 \ubb38\uc81c\ub3c4 \ud568\uaed8 \ubcf4\uc778\ub2e4. \uc624\ub298\uc758 \uc218\ub9ac \uae30\ub85d\uc5d0\uc11c \ubc1c\uacac\ud560 \ubc95\ud55c \uc0ac\uc815\uc774 \uc61b \ubb38\uc7a5 \uc548\uc5d0\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \uc124\uacc4\ub3c4\ub77c\uba74 \uce58\uc218\uc640 \uad6c\uc870\ub97c \uba3c\uc800 \ubcf4\uac8c \ub420 \uac83\uc774\ub2e4. \uc0c1\ub7c9\ubb38\uc5d0\uc11c\ub294 \uac74\ubb3c\uc744 \ub300\ud558\ub294 \ud0dc\ub3c4\uc640 \uacf5\uc0ac\uc758 \uc758\ubbf8\uac00 \uc55e\uc5d0 \ub098\uc628\ub2e4. \uac19\uc740 \uac74\ubb3c\uc744 \ub0a8\uae30\ub294 \uc790\ub8cc\uc5ec\ub3c4 \ub9e1\uc740 \uc5ed\ud560\uc774 \ub2e4\ub974\ub2e4. \uc774 \uae00\uc740 \uae30\uc874 \uc81c\ub3c4\ub97c \ub530\ub974\uba70 \ud130\ub97c \ub354 \ub113\ud788\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc810, \uac10\ub3c5\uc744 \ub9e1\uaca8 \uc77c\uc744 \uc9c4\ud589\ud588\ub2e4\ub294 \uc810\ub3c4 \uc774\uc57c\uae30\ud55c\ub2e4. \uc774\ub7f0 \ub300\ubaa9\uc740 \ud654\ub824\ud55c \uc218\uc0ac \uc0ac\uc774\uc5d0 \ub193\uc5ec \uc788\uc5b4 \uadf8\ub0e5 \uc9c0\ub098\uce58\uae30 \uc27d\ub2e4. \ubb3c\ub860 \uc0c1\ub7c9\ubb38 \ud55c \ud3b8\ub9cc\uc73c\ub85c \uacf5\uc0ac\uc758 \ubaa8\ub4e0 \uacfc\uc815\uc744 \ubcf5\uc6d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub204\uac00 \uc5b4\ub290 \ub0a0 \uc5b4\ub5a4 \uc5f0\uc7a5\uc744 \ub4e4\uc5c8\ub294\uc9c0\uae4c\uc9c0 \uc54c\ub824\uc8fc\ub294 \uc791\uc5c5 \uc77c\uc9c0\ub294 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uc65c \uacf5\uc0ac\uac00 \ud544\uc694\ud588\uace0 \uc5b4\ub5bb\uac8c \uc758\ubbf8\ub97c \ubd80\uc5ec\ud588\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \ucc3d\uc740 \ub41c\ub2e4. \ucc3d\uac74 \uc5f0\ub3c4\ub294 \uac74\ubb3c\uc758 \uc2dc\uc791\uc744 \uc54c\ub824 \uc8fc\uc9c0\ub9cc \uadf8 \ub4a4\uc758 \ube44\ubc14\ub78c\uacfc \uc190\uc9c8\uae4c\uc9c0 \ub9d0\ud574 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc218\ub9ac\uc758 \uae30\ub85d\uc744 \ud568\uaed8 \uc77d\uc73c\uba74 \uc624\ub798\ub41c \ubaa8\uc2b5\uc774 \uc800\uc808\ub85c \uc774\uc5b4\uc9c4 \uac83\uc774 \uc544\ub2d8\uc744 \uc54c\uac8c \ub41c\ub2e4. \uae30\uc6b8\uc5b4\uc9c4 \ubd80\ubd84\uc744 \uc0b4\ud53c\uace0 \uacf5\uc0ac\ub97c \uacb0\uc815\ud558\uba70 \ub9e1\uae38 \uc0ac\ub78c\uc744 \uc815\ud558\ub294 \uc77c\uc774 \uc788\uc5c8\ub2e4. \uc9c0\uae08\uc758 \uad00\ub78c\uc790\ub294 \uadf8 \uc5ec\ub7ec \ubc88\uc758 \uc120\ud0dd \ub4a4\uc5d0 \ub0a8\uc740 \uac74\ubb3c\uc744 \ub9cc\ub098\ub294 \uc148\uc774\ub2e4. \uc0c1\ub7c9\ubb38\uc740 \uadf8 \uc120\ud0dd\uc744 \uae30\ub150\ud558\uace0 \uc758\ubbf8\ub97c \ubd80\uc5ec\ud558\ub294 \uae00\uc774\ub2e4. \ub0a1\uc740 \uacf3\uc744 \uace0\ucce4\ub2e4\ub294 \uc2e4\uc6a9\uc801\uc778 \uc0ac\uc815\uacfc, \uc624\ub798 \uc720\uc9c0\ub418\uae30\ub97c \ubc14\ub77c\ub294 \ub9c8\uc74c\uc774 \uac19\uc740 \ubb38\uc7a5 \uc548\uc5d0 \ub4e4\uc5b4\uac04\ub2e4. \uc624\ub298\uc758 \uacf5\uc0ac \ubcf4\uace0\uc11c\uc640 \uc5ed\ud560\uc774 \uc644\uc804\ud788 \uac19\uc9c0\ub294 \uc54a\uc9c0\ub9cc \uac74\ubb3c\uc744 \ub3cc\ubcf4\uc544\uc57c \ud560 \uc774\uc720\ub97c \uc124\uba85\ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c \ub098\ub780\ud788 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ud130\ub97c \ub354 \ub113\ud788\uc9c0 \uc54a\uace0 \uae30\uc874\uc758 \uc81c\ub3c4\ub97c \ub530\ub790\ub2e4\ub294 \uc124\uba85\uc740 \uacf5\uc0ac\ub97c \ud655\uc7a5\uacfc \uacfc\uc2dc\ub85c\ub9cc \ubcf4\uc9c0 \uc54a\uac8c \ud55c\ub2e4. \uc798 \ubcf4\uc874\ud55c\ub2e4\ub294 \uc77c\uc774 \ubb34\uc5c7\uc744 \ub0a8\uae30\uace0 \ubb34\uc5c7\uc744 \ubc14\uafb8\ub294 \uc120\ud0dd\uc778\uc9c0 \ubb3b\uac8c \ud55c\ub2e4. \ub2e4\ub9cc \uc774 \ubb38\uc7a5\ub9cc\uc73c\ub85c \uc9c0\uae08\uc758 \ubaa8\ub4e0 \ubd80\uc7ac\uac00 \uadf8\ub54c\uc640 \ub611\uac19\ub2e4\ub294 \ub73b\uc73c\ub85c \ub113\ud790 \uc218\ub294 \uc5c6\ub2e4. \uae00\uc774 \ubcf4\uace0\ud558\ub294 \uacf5\uc0ac\uc758 \ubc29\uce68\uacfc \uc2e4\uc81c \ub0a8\uc740 \uac74\ucd95\uc740 \ud568\uaed8 \ub300\uc870\ud574\uc57c \ud560 \ub300\uc0c1\uc774\ub2e4. \ubb38\uc7a5 \uc18d\uc5d0\uc11c \uac10\ub3c5\uc744 \ub9e1\uacbc\ub2e4\ub294 \ubd80\ubd84\ub3c4 \uc9c0\ub098\uce58\uae30 \uc27d\ub2e4. \uacf5\uc0ac\ub294 \uc88b\uc740 \ub73b\ub9cc\uc73c\ub85c \uc9c4\ud589\ub418\uc9c0 \uc54a\ub294\ub2e4. \ud560 \uc77c\uc744 \ub098\ub204\uace0 \ucc45\uc784\uc744 \uc815\ud558\uba70 \uae30\uc874 \uc0c1\ud0dc\ub97c \ud655\uc778\ud558\ub294 \uacfc\uc815\uc774 \ud544\uc694\ud558\ub2e4. \ud654\ub824\ud55c \uc218\uc0ac \uc0ac\uc774\uc5d0 \uc774\ub7f0 \uc2e4\ubb34\uc801\uc778 \ub9d0\uc774 \ub193\uc774\uba74 \uc61b \uac74\ucd95\uc758 \uc5ed\uc0ac\uac00 \uc870\uae08 \ub354 \uc0ac\ub78c\uc758 \uc77c\ub85c \ub290\uaef4\uc9c4\ub2e4. \ubc15\ubb3c\uad00\uc758 \uc790\ub8cc\uc640 \ucd5c\uc11d\ud56d\uc758 \ubb38\uc9d1\uc740 \uac19\uc740 \ub0b4\uc6a9\uc744 \uc11c\ub85c \ub2e4\ub978 \uc790\ub9ac\uc5d0\uc11c \uc804\ud55c\ub2e4. \ud558\ub098\ub294 \ud2b9\uc815\ud55c \uac74\ucd95 \ud589\uc704\uc640 \uc5f0\uacb0\ub41c \ubb3c\uac74\uc774\uace0, \ub2e4\ub978 \ud558\ub098\ub294 \uae00\uc4f4\uc774\uc758 \uc800\uc220 \uac00\uc6b4\ub370 \ub193\uc778 \uae00\uc774\ub2e4. \ub0b4\uc6a9\uc774 \uacb9\uce5c\ub2e4\uace0 \ub450 \uc790\ub8cc\uc758 \uc9c8\ubb38\ub3c4 \ubaa8\ub450 \uac19\uc9c0\ub294 \uc54a\ub2e4. \uc885\uc774\uc758 \ud615\uc2dd\uacfc \uc804\ub798\ub97c \ubcfc \uc218\ub3c4 \uc788\uace0 \uc800\uc790\uc758 \uae00\uc4f0\uae30 \uc548\uc5d0\uc11c \uadf8 \ub73b\uc744 \uc77d\uc744 \uc218\ub3c4 \uc788\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ud615\ud0dc\uc758 \uae30\ub85d\uc744 \ube44\uad50\ud558\uba74 \ube60\uc9c4 \uacf3\uc774\ub098 \ud45c\ud604\uc758 \ucc28\uc774\ub97c \ud655\uc778\ud560 \uae38\uc774 \uc0dd\uae34\ub2e4. \uc5ec\uae30\uc11c \uc2e4\uc81c \ud310\ubcf8 \ucc28\uc774\ub97c \uc870\uc0ac\ud574 \uc0c8 \uacb0\ub860\uc744 \ub0b8 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud55c \ub0b4\uc6a9\uc744 \uc5ec\ub7ec \uc790\ub8cc\uac00 \uc804\ud55c\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc5f0\uad6c\uc5d0 \uc5b4\ub5a4 \uac00\ub2a5\uc131\uc744 \uc8fc\ub294\uc9c0 \uc0dd\uac01\ud558\ub294 \uac83\uc774\ub2e4. \uc624\ub798\ub41c \uae00\uc740 \uc77d\ub294 \ubb38\uc7a5\uc774\uba74\uc11c \uc804\ub2ec\ub418\uc5b4 \uc628 \ubb3c\uac74\uc774\uae30\ub3c4 \ud558\ub2e4. \uac74\ubb3c \uc0ac\uc9c4\uc740 \ucc98\ub9c8\uc640 \uae30\ub465\uc758 \ubaa8\uc591\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc0c1\ub7c9\ubb38\uc740 \uc65c \uadf8 \uac74\ubb3c\uc744 \ub3cc\ubcfc \uac00\uce58\uac00 \uc788\ub2e4\uace0 \ubcf4\uc558\ub294\uc9c0\uc5d0 \uac00\uae4c\uc774 \uac04\ub2e4. \uc190\uc744 \ubcf4\uc544\uc57c \ud588\ub2e4\ub294 \uc0ac\uc815\uacfc \uc55e\uc73c\ub85c \uc798 \uc720\uc9c0\ub418\uae30\ub97c \ubc14\ub780\ub2e4\ub294 \ub9d0\uc774 \ud568\uaed8 \uc788\ub2e4. \uc790\ub8cc \ud558\ub098\uac00 \uac74\ucd95\uc758 \ubaa8\ub4e0 \uc815\ubcf4\ub97c \ub300\uc2e0\ud560 \uc218 \uc5c6\uae30\uc5d0 \uc11c\ub85c \ub2e4\ub978 \uae30\ub85d\uc744 \uc77d\ub294 \uc7ac\ubbf8\uac00 \uc0dd\uae34\ub2e4. \uc6d0\ubb38\uc744 \ubaa8\ub450 \ud574\ub3c5\ud558\uc9c0 \ubabb\ud558\ub354\ub77c\ub3c4 \ubc88\uc5ed\uc5d0\uc11c \ubc18\ubcf5\ub418\ub294 \uad00\uc2ec\uc744 \ucc3e\uc744 \uc218 \uc788\ub2e4. \ub0a1\uc74c\uacfc \uae30\uc6b8\uc5b4\uc9d0, \uae30\uc874 \uaddc\ubaa8\uc640 \ucc45\uc784, \uc774\ud6c4\uc758 \uc548\ub155 \uac19\uc740 \ub9d0\ub4e4\uc744 \ub530\ub77c\uac00 \ubcf4\uc790. \uc624\ub798\ub418\uc5c8\ub2e4\ub294 \uac10\ud0c4 \uc606\uc5d0 \ub204\uac00 \uc5b4\ub5bb\uac8c \uc624\ub798 \ub0a8\uae30\ub824 \ud588\ub294\uc9c0\ub77c\ub294 \uc9c8\ubb38\uc774 \ubd99\ub294\ub2e4. \uc218\ub9ac\uc758 \uc5ed\uc0ac\ub294 \uac74\ubb3c\uc758 \ubd80\uc218\uc801\uc778 \uc8fc\uc11d\uc774 \uc544\ub2c8\ub77c \ub0a8\uc544 \uc788\uac8c \ud55c \uc2dc\uac04\uc758 \uc77c\ubd80\ub2e4. \uc6d0\ubb38\uc758 \ud55c\uc790\ub97c \ubaa8\ub450 \uc77d\uc9c0 \ubabb\ud574\ub3c4 \uad1c\ucc2e\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc790\ub8cc\uc758 \uc124\uba85\uacfc \ubc88\uc5ed\uc744 \ud568\uaed8 \uacf5\uac1c\ud55c\ub2e4. \uae00\uc758 \uc81c\ubaa9\uacfc \uc791\uc131 \ubc30\uacbd\uc744 \uc54c\uace0 \ubcf4\uba74 \uc885\uc774 \uc704\uc758 \ube7d\ube7d\ud55c \uae00\uc528\ub3c4 \ub2e4\ub978 \uc778\uc0c1\uc744 \uc900\ub2e4. \uc624\ub798\ub41c \uac74\ubb3c\uc740 \ucc98\uc74c \ubaa8\uc2b5 \uadf8\ub300\ub85c \uc2dc\uac04\uc774 \uba48\ucd98 \ubb3c\uac74\ucc98\ub7fc \ubcf4\uc77c \ub54c\uac00 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \ubaa8\uc2b5\uc744 \uc774\uc5b4 \uac00\uae30 \uc704\ud574 \ub204\uad70\uac00\ub294 \uc190\uc744 \ubcf4\uc558\uace0, \ub54c\ub85c\ub294 \uadf8 \uc77c\uc744 \uae00\ub85c \ub0a8\uacbc\ub2e4. \ub2e4\uc74c\uc5d0 \uc720\uc11c \uae4a\uc740 \uac74\ubb3c\uc744 \uad6c\uacbd\ud55c\ub2e4\uba74 \ucc3d\uac74 \uc5f0\ub3c4 \uc606\uc758 \uc911\uc218\ub098 \uc911\uac74 \uae30\ub85d\ub3c4 \ud55c\ubc88 \uc0b4\ud3b4\ubcf4\uc790. \uc624\ub798\ub418\uc5c8\ub2e4\ub294 \ud55c\ub9c8\ub514 \uc548\uc5d0, \uc624\ub798 \ubc84\ud2f0\uac8c \ud558\ub824\ub358 \uc5ec\ub7ec \ubc88\uc758 \uc77c\uc774 \uc811\ud600 \uc788\ub2e4."}, {"id": "bulgaria-magura-human-figures", "title": "\ub3d9\uad74 \ubcbd\uc5d0\ub294 \ub3d9\ubb3c\ub9cc \uadf8\ub824\uc9c4 \uac83\uc774 \uc544\ub2c8\ub2e4", "summary": "\ubcbd\uba74\uc5d0 \ub0a8\uc740 \uc2e4\uc81c \uadf8\ub9bc\uc5d0\uc11c \uc0ac\ub78c\uacfc \ub3d9\ubb3c\uc758 \ud615\uc0c1\uc744 \ucc3e\uc544\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/bulgaria-magura-human-figures/index.html", "image": "../media/bulgaria-magura-human-figures.jpg", "alt": "\ubd88\uac00\ub9ac\uc544 \ub9c8\uad6c\ub77c \ub3d9\uad74 \ubcbd\uba74\uc5d0 \uc0ac\ub78c\uacfc \ub3d9\ubb3c \ubaa8\uc591\uc774 \ud568\uaed8 \ub0a8\uc544 \uc788\ub294 \uc2e4\uc81c \ubcbd\ud654 \uc0ac\uc9c4.", "text": "\ub3d9\uad74 \ubcbd\uc5d0\ub294 \ub3d9\ubb3c\ub9cc \uadf8\ub824\uc9c4 \uac83\uc774 \uc544\ub2c8\ub2e4 \ubd88\uac00\ub9ac\uc544 \ub9c8\uad6c\ub77c \ub3d9\uad74\uc5d0\uc11c \ucc3e\ub294 \uc0ac\ub78c\uc758 \ubaa8\uc2b5 \ubcbd\uba74\uc5d0 \ub0a8\uc740 \uc2e4\uc81c \uadf8\ub9bc\uc5d0\uc11c \uc0ac\ub78c\uacfc \ub3d9\ubb3c\uc758 \ud615\uc0c1\uc744 \ucc3e\uc544\ubd05\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \ub3d9\uad74 \ubcbd\ud654\ub77c\uace0 \ud558\uba74 \ucee4\ub2e4\ub780 \ub4e4\uc18c\ub098 \ub9d0\uc774 \uba3c\uc800 \ub5a0\uc624\ub97c \uc218 \uc788\ub2e4. \uadf8\ub7f0\ub370 \ubd88\uac00\ub9ac\uc544\uc758 \ub9c8\uad6c\ub77c \ub3d9\uad74 \uc0ac\uc9c4\uc744 \ubcf4\uba74 \uc0ac\ub78c\ucc98\ub7fc \ubcf4\uc774\ub294 \uc5ec\ub7ec \ud615\uc0c1\ub3c4 \ub3d9\ubb3c\ub4e4\uacfc \ud568\uaed8 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ud314\uacfc \ub2e4\ub9ac\ub97c \ubc8c\ub9b0 \ub4ef\ud55c \uc5b4\ub450\uc6b4 \uc120\ub4e4\uc774\ub2e4. OpenStax \uad50\uc7ac\ub294 \uc774 \uadf8\ub9bc\ub4e4\uc744 \uc0ac\ub78c\uacfc \ub3d9\ubb3c\uc774 \ud568\uaed8 \ub4f1\uc7a5\ud558\ub294 \uc120\uc0ac\uc2dc\ub300 \ub3d9\uad74 \uadf8\ub9bc\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \uc774\ub984\uc744 \ubaa8\ub974\ub358 \ub3d9\uad74\uc5d0\uc11c\ub3c4 \uc2dc\uc120\uc744 \uc5b4\ub514\uc5d0 \ub450\ub290\ub0d0\uc5d0 \ub530\ub77c \ub2e4\ub978 \uc7a5\uba74\uc774 \uc5f4\ub9b0\ub2e4. \uc0ac\uc9c4 \uc18d \ud615\uc0c1\ub4e4\uc740 \uc624\ub298\uc758 \uc815\ubc00\ud55c \uc778\ubb3c\ud654\ucc98\ub7fc \uc5bc\uad74\uc744 \uc790\uc138\ud788 \ubcf4\uc5ec \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \ub300\uc2e0 \ubab8\ud1b5\uacfc \ud314\ub2e4\ub9ac\ub97c \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uac04\ub2e8\ud55c \ubaa8\uc591\uc774 \uc788\ub2e4. \ubb34\uc5c7\uc744 \uc0ac\ub78c\uc73c\ub85c \uc77d\uac8c \ub9cc\ub4dc\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\ub294 \uc7ac\ubbf8\uac00 \uc0dd\uae34\ub2e4. \uc606\uc5d0\ub294 \ubab8\uc758 \ud615\ud0dc\uac00 \ub2e4\ub978 \ub3d9\ubb3c \uadf8\ub9bc\ub4e4\ub3c4 \ub193\uc5ec \uc788\ub2e4. \uc120\uc744 \ud558\ub098\uc529 \ub530\ub77c\uac00\uba70 \uc11c\ub85c \ub2ee\uc740 \uac83\uacfc \ub2e4\ub978 \uac83\uc744 \uad6c\ubcc4\ud574 \ubcf4\uc790. \uba3c\uc800 \ub208\uc55e\uc758 \ud615\ud0dc\ub97c \ubcf4\ub294 \ub370 \ubcf5\uc7a1\ud55c \ud574\ub3c5\ud45c\uac00 \ud544\uc694\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \ud615\uc0c1\uc774 \ub450 \ud314\uc744 \uc62c\ub9b0 \uac83\ucc98\ub7fc \ubcf4\uc778\ub2e4\uace0 \uadf8 \uc0ac\ub78c\uc774 \ubb34\uc5c7\uc744 \ud558\ub358 \uc911\uc778\uc9c0\uae4c\uc9c0 \ubc14\ub85c \uc54c \uc218\ub294 \uc5c6\ub2e4. \uadf8\ub9bc\uc758 \ud615\ud0dc\ub97c \uc54c\uc544\ubcf4\ub294 \uc77c\uacfc \uadf8 \uc7a5\uba74\uc758 \ub73b\uc744 \ud655\uc815\ud558\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uadf8\ub798\uc11c \uc774 \uae00\uc5d0\uc11c\ub294 \ud2b9\uc815 \uc758\ub840\ub098 \uc774\uc57c\uae30\ub97c \uc815\ub2f5\ucc98\ub7fc \ubd99\uc774\uc9c0 \uc54a\ub294\ub2e4. \uad50\uc7ac\uac00 \uc0ac\ub78c\uacfc \ub3d9\ubb3c\uc758 \uadf8\ub9bc\uc774\ub77c\uace0 \uc124\uba85\ud55c \ubc94\uc704 \uc548\uc5d0\uc11c \uc2e4\uc81c \uc0ac\uc9c4\uc744 \uc0b4\ud3b4\ubcf8\ub2e4. \uc624\ub798\ub41c \uadf8\ub9bc\uc744 \ubcfc \ub54c \ubaa8\ub974\ub294 \ubd80\ubd84\uc744 \ub0a8\uaca8 \ub450\ub294 \uac83\ub3c4 \ubcf4\ub294 \ubc29\ubc95\uc774\ub2e4. \uac04\ub2e8\ud55c \ud615\uc0c1\uc5d0\uc11c\ub3c4 \uc6b0\ub9ac\ub294 \uba38\ub9ac\uc640 \ubab8, \ud314\uacfc \ub2e4\ub9ac\ub97c \ucc3e\uc73c\ub824 \ud55c\ub2e4. \uc138\ubd80\uc801\uc778 \uc5bc\uad74\uc774 \uc5c6\uc5b4\ub3c4 \ubab8\uc758 \ubc29\ud5a5\uc774\ub098 \uc5ec\ub7ec \uc120\uc758 \uad00\uacc4\uac00 \uc0ac\ub78c\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud560 \uc218 \uc788\ub2e4. \uc0ac\uc9c4\uc744 \ucc9c\ucc9c\ud788 \ubcf4\uba74 \uc6b0\ub9ac\uac00 \ubb34\uc5c7\uc744 \uadfc\uac70\ub85c \uc778\ubb3c\ub85c \uc77d\ub294\uc9c0\ub3c4 \uc9c8\ubb38\ud558\uac8c \ub41c\ub2e4. \uadf8\ub9bc\uc744 \uc774\ud574\ud55c\ub2e4\ub294 \uc77c\uc774 \ud56d\uc0c1 \uc5bc\uad74\uc758 \ud45c\uc815\uc744 \uc815\ud655\ud788 \uc54c\uc544\ubcf4\ub294 \ub370\uc11c \uc2dc\uc791\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub3d9\ubb3c\ub85c \uc18c\uac1c\ub41c \ud615\uc0c1\uacfc \ub098\ub780\ud788 \ube44\uad50\ud558\uba74 \uc774 \ucc28\uc774\uac00 \ub354 \ubcf4\uc778\ub2e4. \uae38\uac8c \ubed7\uc740 \ubd80\ubd84\uacfc \ubab8\ud1b5\uc758 \ube44\ub840, \ub2e4\ub9ac\uac00 \ub193\uc778 \ubc29\ud5a5\uc744 \uc0b4\ud3b4\ubcf4\ub294 \uac83\uc774\ub2e4. \ub2e4\ub9cc \ube44\uad50\uac00 \uace7 \uc885\uc774\ub098 \uc778\ubb3c\uc758 \uc774\ub984\uc744 \uc0c8\ub85c \ud655\uc815\ud558\ub294 \uc791\uc5c5\uc740 \uc544\ub2c8\ub2e4. \uad50\uc7ac\uac00 \uc124\uba85\ud55c \ud070 \uad6c\ubd84 \uc548\uc5d0\uc11c \uc9c1\uc811 \ubcfc \uc218 \uc788\ub294 \ud615\ud0dc\ub97c \uc54c\uc544\ubcf4\ub824\ub294 \uad00\ucc30\uc5d0 \uac00\uae5d\ub2e4. \ub3d9\uad74 \ubcbd\uc740 \ubc18\ub4ef\ud558\uac8c \uc900\ube44\ud55c \uc885\uc774\uc758 \ud14c\ub450\ub9ac\uc640 \ub2e4\ub974\ub2e4. \uadf8\ub9bc\uc740 \uc790\uc5f0\uc758 \ud45c\uba74 \uc548\uc5d0\uc11c \ub2e4\ub978 \ubaa8\uc591\uacfc \uc774\uc6c3\ud55c\ub2e4. \uc9c0\uae08\uc758 \uc0ac\uc9c4\ub3c4 \uc804\uccb4 \uacf5\uac04 \uc911 \uc77c\ubd80\ub97c \uace8\ub77c \ubcf4\uc5ec \uc8fc\ubbc0\ub85c, \ud55c \ud654\uba74\uc758 \ub05d\uc744 \uc6d0\ub798 \uadf8\ub9bc \uc804\uccb4\uc758 \uacbd\uacc4\ub85c \uc624\ud574\ud558\uc9c0 \uc54a\uc544\uc57c \ud55c\ub2e4. \ubb34\uc5c7\uc774 \ud568\uaed8 \ubcf4\uc774\uace0 \ubb34\uc5c7\uc774 \uc0ac\uc9c4 \ubc16\uc5d0 \uc788\ub294\uc9c0 \uad6c\ubd84\ud560 \uc774\uc720\uac00 \uc788\ub2e4. \uc774\ub7f0 \ud45c\uba74\uc5d0\uc11c \ud615\uc0c1\ub4e4\uc744 \ubcf4\ub294 \uc77c\uc740 \ubc15\ubb3c\uad00 \uc561\uc790 \uc18d\uc758 \ud55c \uc791\ud488\uc744 \ubcf4\ub294 \uacbd\ud5d8\uacfc \ub2e4\ub97c \uc218 \uc788\ub2e4. \uac01\uac01\uc744 \ub530\ub85c \ub5bc\uc5b4 \ubcfc \uc218\ub3c4 \uc788\uace0 \uc11c\ub85c\uc758 \uac04\uaca9\uacfc \ubc29\ud5a5\uc744 \ubcfc \uc218\ub3c4 \uc788\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4\uc758 \uc870\uba85\uacfc \ucd2c\uc601 \ubc94\uc704\ub9cc\uc73c\ub85c \uc6d0\ub798 \ub3d9\uad74\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc774 \ubb34\uc5c7\uc744 \uc5bc\ub9c8\ub098 \ubcfc \uc218 \uc788\uc5c8\ub294\uc9c0 \ubaa8\ub450 \uc7ac\uad6c\uc131\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc774\ubbf8\uc9c0\uac00 \uc54c\ub824 \uc8fc\ub294 \ubd80\ubd84\uacfc \ud544\uc694\ud55c \ud604\uc7a5 \uc815\ubcf4\ub294 \ub098\ub25c\ub2e4. \ud314\uc744 \ub4e4\uc5c8\uac70\ub098 \ubab8\uc744 \uad7d\ud78c \ub4ef \ubcf4\uc774\uba74 \uc6b0\ub9ac\ub294 \uace7 \ud2b9\uc815\ud55c \uc7a5\uba74\uc758 \uc774\ub984\uc744 \ucc3e\ub294\ub2e4. \ucda4\uc774\ub098 \uc0ac\ub0e5, \uc758\uc2dd\uc774\ub77c\ub294 \ub9d0\uc774 \uba3c\uc800 \ub5a0\uc624\ub97c \uc218\ub3c4 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ube44\uc2b7\ud55c \ubab8\uc9d3\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc0c1\ud669\uc5d0\uc11c \ub098\ud0c0\ub0a0 \uc218 \uc788\ub2e4. \ud615\ud0dc\uc758 \ub2ee\uc74c\ub9cc\uc73c\ub85c \ubb34\uc5c7\uc744 \uae30\ub150\ud558\uace0 \ub204\uac00 \uadf8\ub838\ub294\uc9c0\uae4c\uc9c0 \uc815\ud558\uba74 \uc124\uba85\uc774 \uc790\ub8cc\ub97c \ub118\uc5b4\uac08 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \uc5ec\uae30\uc11c\ub294 \ubd88\ud655\uc2e4\ud568\uc744 \ub450\ub824\uc6cc\ud558\uae30\ubcf4\ub2e4 \uc9c8\ubb38\uc744 \ub098\ub204\uc5b4 \ubcf8\ub2e4. \uc5b4\ub5a4 \uc120\uc774 \ubcf4\uc774\ub294\uac00, \uc790\ub8cc\ub294 \uadf8\uac83\uc744 \ubb34\uc5c7\uc73c\ub85c \uc18c\uac1c\ud558\ub294\uac00, \uadf8 \uc774\uc0c1\uc758 \ud574\uc11d\uc5d0\ub294 \uc5b4\ub5a4 \uadfc\uac70\uac00 \ud544\uc694\ud55c\uac00. \uc774 \uc138 \ub2e8\uacc4\ub97c \uad6c\ubd84\ud558\uba74 \uc0c1\uc0c1\ud560 \uc5ec\uc9c0\uc640 \uc0ac\uc2e4\uc758 \ubc94\uc704\ub97c \ubaa8\ub450 \ub0a8\uae38 \uc218 \uc788\ub2e4. \uc815\ub2f5 \ud558\ub098\ub97c \ubd99\uc774\uc9c0 \uc54a\uc544\ub3c4 \uc624\ub798\ub41c \ubcbd\uc744 \ubcf4\ub294 \uc77c\uc740 \ucda9\ubd84\ud788 \ud48d\ubd80\ud558\ub2e4. \ud604\ub300\uc758 \uc815\ubc00\ud55c \uc778\ubb3c\ud654\ub97c \uae30\uc900\uc73c\ub85c\ub9cc \ubcf4\uba74 \ub2e8\uc21c\ud55c \uc120\uc740 \ubd80\uc871\ud558\uac8c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc801\uc740 \uc694\uc18c\ub85c \uc0ac\ub78c\uc774\ub098 \ub3d9\ubb3c\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4\ub294 \uc810\ub3c4 \ubcfc \uc218 \uc788\ub2e4. \uc774\uac83\uc744 \uc624\ub298\uc758 \uac04\ub2e8\ud55c \uadf8\ub9bc\uacfc \uace7\uc7a5 \uac19\uc740 \uc758\ubbf8\ub77c\uace0 \ub193\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \ube44\uc2b7\ud55c \ud45c\ud604 \uc218\ub2e8\uc774 \ubcf4\uc5ec\ub3c4 \uc0ac\uc6a9\ud55c \uc2dc\ub300\uc640 \uad00\uacc4\ub294 \ub2e4\ub97c \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc0ac\uc9c4\uc744 \ub2e4\uc2dc \ubcfc \ub54c\uc5d0\ub294 \uba3c\uc800 \ud615\uc0c1 \ud558\ub098\ub97c \uace0\ub974\uace0 \ub2e4\uc74c\uc5d0 \uc8fc\ubcc0\uc758 \ubaa8\uc591\uc73c\ub85c \ub208\uc744 \ub113\ud600 \ubcf4\uc790. \uc5b4\ub290 \uac83\uc740 \ub2ee\uace0 \uc5b4\ub290 \uac83\uc740 \ub2e4\ub974\uac8c \ubcf4\uc774\ub294\uc9c0 \ucc9c\ucc9c\ud788 \ube44\uad50\ud558\uba74 \ub41c\ub2e4. \ub9c8\uad6c\ub77c \ub3d9\uad74\uc758 \uc2e4\uc81c \uc0ac\uc9c4\uc740 \uc0c1\uc0c1 \uc18d \uc120\uc0ac\uc2dc\ub300\ub97c \uc7a5\uc2dd\ud55c \uadf8\ub9bc\uacfc \uad6c\ubcc4\ub41c\ub2e4. \uc774\ub984\uc744 \ubaa8\ub974\ub294 \uc0ac\ub78c\ub4e4\uc774 \ub0a8\uae34 \ud45c\ud604 \uc55e\uc5d0\uc11c \uc624\ub298\uc758 \uc6b0\ub9ac\uac00 \uc5b4\ub5bb\uac8c \ubcf4\ub294\uc9c0 \ub3cc\uc544\ubcf4\uac8c \ud558\ub294 \uc790\ub8cc\ub2e4. \uc774\ubc88 \uc0ac\uc9c4\uc740 \ubcbd\ud654\ub97c AI\ub85c \ub2e4\uc2dc \uadf8\ub9b0 \uac83\uc774 \uc544\ub2c8\ub2e4. \ubc14\uc704\uc758 \ud45c\uba74\uacfc \uadf8 \uc704\uc5d0 \ub0a8\uc740 \uc120\uc744 \ud568\uaed8 \ubcf4\ub824\uba74 \uc2e4\uc81c \uc774\ubbf8\uc9c0\uac00 \ub354 \uc801\uc808\ud558\ub2e4. \ub9e4\ub048\ud55c \ud770 \uc885\uc774\uc5d0 \uc62e\uaca8 \ub193\uc558\uc744 \ub54c\uc640\ub294 \ub2e4\ub978 \uc778\uc0c1\uc774 \uc788\ub2e4. \ub3d9\uad74\uc758 \uc2dc\uac04\uc744 \ud55c \ubc88\uc5d0 \uc774\ud574\ud558\ub824 \uc560\uc4f8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc624\ub298\uc740 \ub3d9\ubb3c \uc606\uc5d0 \uc0ac\ub78c\uc774 \uc788\uc5c8\ub2e4\ub294 \uc810\ubd80\ud130 \uae30\uc5b5\ud574 \ubcf4\uc790. \uc624\ub798\ub41c \ubcbd\uba74\uc5d0\ub3c4 \uc138\uc0c1\uc744 \ubcf4\ub294 \uc0ac\ub78c\ubfd0 \uc544\ub2c8\ub77c, \uc790\uae30\uc640 \ub2ee\uc740 \ubab8\uc744 \ub0a8\uae30\ub294 \uc0ac\ub78c\uc758 \uc190\uae38\uc774 \uc788\uc5c8\ub2e4."}, {"id": "canterbury-pilgrims-and-pardoners-gold", "title": "\uce94\ud130\ubca0\ub9ac \uc774\uc57c\uae30 \u2014 \uc21c\ub840\uae38\uc5d0\uc11c\ub294 \ub204\uac00 \uc774\uc57c\uae30\ub97c \uc798\ud588\uc744\uae4c", "summary": "\uc21c\ub840\uae38\uc758 \uc774\uc57c\uae30 \uacbd\uc5f0\uacfc \uae08\ud654 \uc55e\uc5d0\uc11c \ubb34\ub108\uc9c4 \uc6b0\uc815\uc744 \ud1b5\ud574 \ucd08\uc11c\uc758 \uc6c3\uc74c\uacfc \ud48d\uc790\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/canterbury-pilgrims-and-pardoners-gold/index.html", "image": "../media/canterbury-pilgrims-and-pardoners-gold.png", "alt": "\uc5ec\uad00\uc744 \ub5a0\ub098 \ubd04\ub0a0\uc758 \uae38\uc744 \uac00\ub294 \uc911\uc138 \uc601\uad6d \uc21c\ub840\uc790\ub4e4\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uce94\ud130\ubca0\ub9ac \uc774\uc57c\uae30 \u2014 \uc21c\ub840\uae38\uc5d0\uc11c\ub294 \ub204\uac00 \uc774\uc57c\uae30\ub97c \uc798\ud588\uc744\uae4c \ucd08\uc11c\uc758 \uc21c\ub840 \uc561\uc790\uc640 \uae08\ud654\ub97c \ubc1c\uacac\ud55c \uc138 \uc80a\uc740\uc774\uc758 \ube44\uadf9 \uc21c\ub840\uae38\uc758 \uc774\uc57c\uae30 \uacbd\uc5f0\uacfc \uae08\ud654 \uc55e\uc5d0\uc11c \ubb34\ub108\uc9c4 \uc6b0\uc815\uc744 \ud1b5\ud574 \ucd08\uc11c\uc758 \uc6c3\uc74c\uacfc \ud48d\uc790\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \uc5ec\ud589\uae38\uc5d0 \ucc98\uc74c \ub9cc\ub09c \uc0ac\ub78c\ub4e4\uc774 \ucc28\ub840\ub85c \uc774\uc57c\uae30\ub97c \ub4e4\ub824\uc900\ub2e4. \ub204\uad70\uac00\ub294 \uace0\uc0c1\ud55c \uc0ac\ub791\uc744 \ub9d0\ud558\uace0 \ub204\uad70\uac00\ub294 \ub0a8\uc744 \uc18d\uc774\ub294 \uc6b0\uc2a4\uc6b4 \uc0ac\uac74\uc744 \uaebc\ub0b8\ub2e4. \uc81c\ud504\ub9ac \ucd08\uc11c\uc758 \u300e\uce94\ud130\ubca0\ub9ac \uc774\uc57c\uae30\u300f\ub294 \ubaa9\uc801\uc9c0\uc5d0 \ub3c4\ucc29\ud558\ub294 \uacfc\uc815\ub9cc\ud07c\uc774\ub098 \uae38 \uc704\uc5d0\uc11c \uc11c\ub85c \ub9d0\ud558\uace0 \ubc18\uc751\ud558\ub294 \uc77c\uc774 \uc911\uc694\ud55c \uc791\ud488\uc774\ub2e4. \uc81c\ubaa9\ub9cc \ubcf4\uba74 \uc131\uc2a4\ub7ec\uc6b4 \uc21c\ub840\uc5d0 \uad00\ud55c \ucc45 \uac19\uc9c0\ub9cc, \uadf8 \uc548\uc5d0\ub294 \ub3c8\uacfc \uc695\ub9dd, \uc9c1\uc5c5\uc758 \uc790\ubd80\uc2ec\uacfc \ub0a8\uc758 \ud5c8\ubb3c\uc744 \ub4e4\ucd94\ub294 \uc6c3\uc74c\uc774 \uac00\ub4dd\ud558\ub2e4. \ud070 \uad6c\uc131\uc744 \uba3c\uc800 \uc0b4\ud3b4\ubcf4\uace0 \u300c\uba74\uc8c4\ubd80 \ud310\ub9e4\uc778\uc758 \uc774\uc57c\uae30\u300d\ub97c \ub530\ub77c \uc77d\uc73c\uba74 \uc911\uc138 \ubb38\ud559\uc774 \uc608\uc0c1\ubcf4\ub2e4 \ud6e8\uc52c \uc2dc\ub04c\ubc85\uc801\ud558\uac8c \ub2e4\uac00\uc628\ub2e4. \uc544\ub798\uc5d0\ub294 \uc8fc\uc694 \uc774\uc57c\uae30\uc758 \uacb0\ub9d0\ub3c4 \ud3ec\ud568\ub41c\ub2e4. \uc21c\ub840\uc790\ub4e4\uc758 \ubaa9\uc801\uc9c0\ub294 \ud1a0\uba38\uc2a4 \ubca0\ucf13\uc758 \uc131\uc9c0\uac00 \uc788\ub294 \uce94\ud130\ubca0\ub9ac\ub2e4. \uadf8\ub7ec\ub098 \ucd9c\ubc1c\ubd80\ud130 \uae30\ub3c4\ub9cc \ud558\ub294 \ud589\ub82c\uc740 \uc544\ub2c8\ub2e4. \ub7f0\ub358 \ub0a8\ucabd \uc11c\ub354\ud06c\uc758 \ud0dc\ubc84\ub4dc \uc5ec\uad00\uc5d0 \ubaa8\uc778 \uc774\ub4e4\uc740 \ud568\uaed8 \uae38\uc744 \uac00\uba70 \uc2dc\uac04\uc744 \ubcf4\ub0bc \ubc29\ubc95\uc744 \ucc3e\ub294\ub2e4. \uc5ec\uad00 \uc8fc\uc778\uc774 \uc774\uc57c\uae30 \uacbd\uc5f0\uc744 \uc81c\uc548\ud558\uba74\uc11c \uc5ec\ud589\uacfc \ubb38\ud559\uc774 \ud55c \ud2c0 \uc548\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc774 \uad6c\uc870\ub97c \uc561\uc790 \uc774\uc57c\uae30\ub77c\uace0 \ubd80\ub978\ub2e4. \ubc14\uae65\uc5d0\ub294 \uc5ec\ud589\ud558\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc0c1\ud669\uc774 \uc788\uace0 \uc548\ucabd\uc5d0\ub294 \uac01\uc790\uac00 \ub4e4\ub824\uc8fc\ub294 \uc0ac\uac74\uc774 \uc788\ub2e4. \uadf8\ub798\uc11c \uac19\uc740 \uc774\uc57c\uae30\ub3c4 \ub204\uac00 \uc5b8\uc81c \ub9d0\ud558\ub290\ub0d0\uc5d0 \ub530\ub77c \uc758\ubbf8\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \ub3c5\uc790\ub294 \uc904\uac70\ub9ac\ub9cc\uc774 \uc544\ub2c8\ub77c \uc774\uc57c\uae30\ud558\ub294 \uc0ac\ub78c\uacfc \ub4e3\ub294 \uc0ac\ub78c \uc0ac\uc774\uc758 \uad00\uacc4\uae4c\uc9c0 \uc77d\uac8c \ub41c\ub2e4. \uc774 \uc5ec\ud589\uc5d0\ub294 \uae30\uc0ac\uc640 \uc218\ub3c4\uc790, \uc0c1\uc778\uacfc \uc5ec\ub7ec \uc9c1\uc5c5\uc758 \uc0ac\ub78c\ub4e4\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \uadf8\ub4e4\uc758 \uc637\ucc28\ub9bc\uacfc \ub9d0\ud22c, \uc790\ub791\uac70\ub9ac\uc640 \uc57d\uc810\uc740 \uc11c\ub450\ubd80\ud130 \ub4dc\ub7ec\ub09c\ub2e4. \uc911\uc138 \uc0ac\ud68c\ub97c \uba87 \uac1c\uc758 \uc2e0\ubd84 \uc774\ub984\uc73c\ub85c\ub9cc \uc678\uc6b8 \ub54c\ubcf4\ub2e4 \uad6c\uccb4\uc801\uc778 \uc0ac\ub78c\ub4e4\uc774 \ubcf4\uc778\ub2e4. \ub2e4\ub9cc \uc774\ub4e4\uc774 \ub2f9\uc2dc \uc0ac\ud68c\uc758 \ubaa8\ub4e0 \uacc4\uce35\uc744 \ube60\uc9d0\uc5c6\uc774 \ub300\ud45c\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ucd08\uc11c\ub294 \uc778\ubb3c\uc744 \uc18c\uac1c\ud558\uba74\uc11c \uac89\uc73c\ub85c \uce6d\ucc2c\ud558\ub294 \ub9d0 \uc548\uc5d0 \uc758\uc2ec\ud560 \ub2e8\uc11c\ub97c \uc2ec\uae30\ub3c4 \ud55c\ub2e4. \ud654\uc790\uac00 \uc88b\ub2e4\uace0 \ub9d0\ud55c\ub2e4\uace0 \ub3c5\uc790\ub3c4 \uace7\uc774\uace7\ub300\ub85c \ubbff\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc9c1\uc5c5\uc774 \ub0b4\uc138\uc6b0\ub294 \uc774\uc0c1\uacfc \uc2e4\uc81c \ud589\ub3d9 \uc0ac\uc774\uc758 \ud2c8\uc744 \ubc1c\uacac\ud558\ub294 \uac83\uc774 \uc774 \uc791\ud488\uc758 \uc911\uc694\ud55c \uc7ac\ubbf8\ub2e4. \ucc98\uc74c \uc81c\uc548\ub41c \uacbd\uc5f0\uc5d0\ub294 \uae38\uc744 \uc624\uac00\uba70 \uc5ec\ub7ec \uc774\uc57c\uae30\ub97c \ud558\uaca0\ub2e4\ub294 \ud070 \uacc4\ud68d\uc774 \uc788\uc5c8\ub2e4. \ud558\uc9c0\ub9cc \ub0a8\uc544 \uc788\ub294 \uc791\ud488\uc774 \uadf8 \uacc4\ud68d\uc744 \ubaa8\ub450 \ucc44\uc6b4 \uac83\uc740 \uc544\ub2c8\ub2e4. \u300e\uce94\ud130\ubca0\ub9ac \uc774\uc57c\uae30\u300f\ub97c \ucc98\uc74c\ubd80\ud130 \uc644\ubcbd\ud558\uac8c \ub2eb\ud78c \ud558\ub098\uc758 \uc7a5\ud3b8 \uc904\uac70\ub9ac\ucc98\ub7fc \uae30\ub300\ud558\uba74 \ud2b9\uc720\uc758 \ub290\uc2a8\ud568\uc744 \uc774\ud574\ud558\uae30 \uc5b4\ub835\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \ub0a8\uc758 \uc774\uc57c\uae30\uc5d0 \ubc18\uc751\ud558\uace0 \ub07c\uc5b4\ub4e4\uba70 \ub54c\ub85c\ub294 \ub9de\ubc1b\uc544\uce5c\ub2e4. \uc810\uc796\uc740 \uc774\uc57c\uae30 \ub2e4\uc74c\uc5d0 \uac70\uce5c \uc6c3\uc74c\uc774 \ub098\uc624\ub294 \uc2dd\uc774\ub2e4. \uacbd\uc5f0\uc774\ub77c\ub294 \uaddc\uce59 \uc548\uc5d0\uc11c \uc2e4\uc81c \uc0ac\ub78c\ub4e4\uc758 \uacbd\uc7c1\uc2ec\uc774 \ud758\ub7ec\ub118\uce5c\ub2e4. \uadf8 \ub355\ubd84\uc5d0 \uc774\uc57c\uae30\ub97c \ubaa8\uc544 \ub454 \ucc45\uc774\uba74\uc11c\ub3c4 \ud568\uaed8 \uc5ec\ud589\ud558\ub294 \ud604\uc7a5\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uba74\uc8c4\ubd80 \ud310\ub9e4\uc778\uc740 \ud0d0\uc695\uc744 \uacbd\uacc4\ud558\ub294 \uc124\uad50\ub97c \ud558\uba74\uc11c\ub3c4 \uc790\uc2e0\uc740 \ub3c8\uc744 \uc6d0\ud55c\ub2e4\uace0 \ub4dc\ub7ec\ub0b4\ub294 \uc778\ubb3c\uc774\ub2e4. \uadf8\uc758 \ub9d0\uacfc \ub3d9\uae30\ub294 \uc11c\ub85c \uc5b4\uae0b\ub09c\ub2e4. \ub3c5\uc790\ub294 \uc88b\uc740 \uad50\ud6c8\uc744 \ub4e3\uae30 \uc804\uc5d0 \uadf8 \uad50\ud6c8\uc744 \uc774\uc6a9\ud574 \uc774\uc775\uc744 \uc5bb\ub294 \uc0ac\ub78c\uc774 \ub204\uad6c\uc778\uc9c0\ubd80\ud130 \ubcf4\uac8c \ub41c\ub2e4. \uc5ec\uae30\uc11c \uc791\ud488\uc744 \ub2f9\uc2dc \ubaa8\ub4e0 \uc885\uad50\uc778\uc744 \ud55c\uaebc\ubc88\uc5d0 \uacf5\uaca9\ud558\ub294 \uae00\ub85c \ub2e8\uc21c\ud654\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uc131\uc2a4\ub7ec\uc6b4 \uad8c\uc704\uc758 \ub9d0\ub3c4 \ud604\uc2e4\uc5d0\uc11c\ub294 \uac70\ub798\uc758 \uc218\ub2e8\uc774 \ub420 \uc218 \uc788\ub2e4\ub294 \uad00\ucc30\uc774\ub2e4. \uc124\uad50 \ub0b4\uc6a9\uc774 \uc633\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc124\uad50\ud558\ub294 \uc0ac\ub78c\uc744 \ubbff\uc744 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uac19\uc9c0 \uc54a\ub2e4. \uadf8\uac00 \ub4e4\ub824\uc8fc\ub294 \uc774\uc57c\uae30\uc5d0\uc11c \uc138 \uc80a\uc740\uc774\ub294 \uce5c\uad6c\ub97c \uc8fd\uc600\ub2e4\ub294 \uc8fd\uc74c\uc744 \ucc3e\uc544 \ub098\uc120\ub2e4. \uae38\uc5d0\uc11c \ub9cc\ub09c \ub178\uc778\uc740 \ub098\ubb34\uac00 \uc788\ub294 \uacf3\uc744 \uac00\ub9ac\ud0a8\ub2e4. \uadf8\ub7f0\ub370 \uadf8\uacf3\uc5d0\ub294 \ub208\uc5d0 \ubcf4\uc774\ub294 \uc8fd\uc74c \ub300\uc2e0 \uae08\ud654\uac00 \uc313\uc5ec \uc788\ub2e4. \ubd84\ub178\ud558\uba70 \ucd9c\ubc1c\ud55c \uc138 \uc0ac\ub78c\uc758 \uad00\uc2ec\uc740 \uc21c\uc2dd\uac04\uc5d0 \uc7ac\ubb3c\ub85c \uc62e\uaca8 \uac04\ub2e4. \uae08\uc744 \uc62e\uae38 \ubc29\ubc95\uc744 \uc758\ub17c\ud558\uba74\uc11c \uadf8\ub4e4\uc758 \uc6b0\uc815\ub3c4 \ubb34\ub108\uc9c4\ub2e4. \ud55c \uc0ac\ub78c\uc774 \uba39\uc744 \uac83\uacfc \uc220\uc744 \uc0ac\ub7ec \uac04 \uc0ac\uc774 \ub0a8\uc740 \ub458\uc740 \ub3cc\uc544\uc628 \uadf8\ub97c \uc5c6\uc560\uace0 \ubaab\uc744 \ub298\ub9ac\ub824 \ud55c\ub2e4. \ubc16\uc73c\ub85c \ub098\uac04 \uc0ac\ub78c\ub3c4 \ub3c5\uc744 \uc774\uc6a9\ud574 \uae08\uc744 \ub3c5\ucc28\uc9c0\ud560 \uc0dd\uac01\uc744 \ud55c\ub2e4. \uac19\uc740 \ubaa9\uc801\uc744 \uac00\uc9c4 \ub3d9\ub8cc\uac00 \uc11c\ub85c\uc758 \uc7a5\uc560\ubb3c\uc774 \ub41c\ub2e4. \ub3cc\uc544\uc628 \uc0ac\ub78c\uc740 \ub450 \ub3d9\ub8cc\uc5d0\uac8c \uc0b4\ud574\ub2f9\ud558\uace0, \uc0b4\uc544\ub0a8\uc740 \ub458\ub3c4 \ub3c5\uc774 \ub4e0 \uc220\uc744 \ub9c8\uc154 \uc8fd\ub294\ub2e4. \uc8fd\uc74c\uc744 \uc5c6\uc560\uaca0\ub2e4\ub294 \uc0ac\ub78c\ub4e4 \ubaa8\ub450\uac00 \uc8fd\uc74c\uc5d0 \uc774\ub978\ub2e4. \uc774\uc57c\uae30 \ucc98\uc74c\uc758 \uc704\ud611\uc774 \ub9c8\uc9c0\ub9c9\uc5d0 \ub2e4\ub978 \ubaa8\uc2b5\uc73c\ub85c \ub3cc\uc544\uc624\ub294 \uad6c\uc131\uc774\ub2e4. \uae08 \uc790\uccb4\uac00 \ub9c8\ubc95\uc744 \ubd80\ub9b0 \uac83\uc774 \uc544\ub2c8\ub77c \uadf8\uac83\uc744 \ub300\ud558\ub294 \ud589\ub3d9\uc774 \ud30c\uad6d\uc744 \ub9cc\ub4e0\ub2e4. \uad50\ud6c8\uc740 \ubd84\uba85\ud574 \ubcf4\uc774\uc9c0\ub9cc \uadf8\uac83\uc73c\ub85c \ubc14\uae65\uc758 \uc21c\ub840\uae38\uae4c\uc9c0 \uc815\ub9ac\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc774 \uad50\ud6c8\uc744 \ub4e4\ub824\uc900 \uc0ac\ub78c \uc790\uc2e0\uc774 \ud0d0\uc695\uc2a4\ub7fd\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub0a8\uae30 \ub54c\ubb38\uc774\ub2e4. \uc774\uc57c\uae30\ub294 \ud0d0\uc695\uc744 \uacbd\uacc4\ud558\uac8c \ud558\uace0, \uc561\uc790\ub294 \uadf8 \uacbd\uacc4\ub97c \uc785\uc5d0 \uc62c\ub9ac\ub294 \uad8c\uc704\ub3c4 \ub2e4\uc2dc \uc0b4\ud53c\uac8c \ud55c\ub2e4. \ub450 \uce35\uc774 \ud568\uaed8 \uc791\ub3d9\ud55c\ub2e4. \u300e\uce94\ud130\ubca0\ub9ac \uc774\uc57c\uae30\u300f\ub97c \uc77d\uc744 \ub54c\uc5d0\ub294 \uc5b4\ub290 \uc778\ubb3c\uc774 \ucd08\uc11c \uc790\uc2e0\uc758 \uc758\uacac\uc744 \uadf8\ub300\ub85c \ub9d0\ud55c\ub2e4\uace0 \uc11c\ub458\ub7ec \uacb0\uc815\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\ub2e4. \uc791\uac00\ub294 \uc11c\ub85c \ub2e4\ub978 \ubaa9\uc18c\ub9ac\ub97c \ubd80\ub52a\uce58\uac8c \ud558\uba74\uc11c \ub3c5\uc790\uac00 \uadf8 \ucc28\uc774\ub97c \uc54c\uc544\ucc28\ub9ac\ub3c4\ub85d \ud55c\ub2e4. \uc21c\ub840\uae38\uc740 \ud558\ub098\uc758 \uc815\ub2f5\uc744 \uc804\ub2ec\ud558\ub294 \uc904\uc774 \uc544\ub2c8\ub77c \uc5ec\ub7ec \uc0ac\ub78c\uc774 \ub9d0\ud560 \ucc28\ub840\ub97c \uc5bb\ub294 \uc790\ub9ac\ub2e4. \uc5ec\ud589\uc758 \ud2c0\uc774 \uc5c6\uc5c8\ub2e4\uba74 \uc774 \uc791\ud488\uc740 \uc11c\ub85c \ub2e4\ub978 \uad50\ud6c8\uc744 \ubaa8\uc740 \ucc45\ucc98\ub7fc \uc77d\ud614\uc744 \uc218\ub3c4 \uc788\ub2e4. \ud558\uc9c0\ub9cc \ub4e3\ub294 \uc774\ub4e4\uc758 \ubc18\uc751\uc774 \ub4e4\uc5b4\uc624\uba74\uc11c \ub9d0\uc740 \uace7 \ud589\ub3d9\uc774 \ub41c\ub2e4. \uc5b4\ub5a4 \uc774\uc57c\uae30\ub97c \uace8\ub77c \uaebc\ub0c8\ub294\uc9c0\uac00 \uc774\uc57c\uae30\uafbc \uc790\uc2e0\uc758 \uc131\uaca9\uc744 \ub4dc\ub7ec\ub0b4\ub294 \ubc29\uc2dd\uc774\uae30\ub3c4 \ud558\ub2e4. \uc131\uc9c0\ub85c \ud5a5\ud558\ub294 \uae38 \uc704\uc5d0\uc11c\ub3c4 \uc0ac\ub78c\uc740 \ud5c8\uc138\ub97c \ubd80\ub9ac\uace0 \ub3c8\uc744 \ud0d0\ub0b4\uba70 \ub0a8\uc758 \ub9d0\uc744 \uc6c3\uc5b4\ub118\uae34\ub2e4. \uadf8 \uc0dd\ud65c\uc758 \uad6c\uccb4\uc131\uc774 \uc791\ud488\uc744 \uc624\ub798 \uc0b4\uc544 \uc788\uac8c \ud55c\ub2e4. \uc21c\ub840\uc758 \uc5ed\uc0ac\uc640 \uc774\uc57c\uae30\uafbc\ub4e4\uc758 \uacbd\uc7c1\uc744 \ud568\uaed8 \ubcf4\uba74 \uc774 \ucc45\uc740 \uba3c \uc2dc\ub300\uc758 \uad50\uc7ac\ub97c \ub118\uc5b4 \uc0ac\ub78c\ub4e4 \uc0ac\uc774\uc5d0 \uc549\uc544 \ub4e3\ub294 \ubb38\ud559\uc774 \ub41c\ub2e4."}, {"id": "carmen-love-freedom-and-stage", "title": "\uce74\ub974\uba58 \u2014 \uc775\uc219\ud55c \ub178\ub798 \ub4a4\uc5d0\ub294 \uc5b4\ub5a4 \uc774\uc57c\uae30\uac00 \uc788\uc744\uae4c", "summary": "\ub124 \ub9c9\uc758 \uc904\uac70\ub9ac\uc640 \ud558\ubc14\ub124\ub77c\u00b7\ud22c\uc6b0\uc0ac\uc758 \ub178\ub798\u00b7\uaf43\ub178\ub798\ub97c \ud568\uaed8 \uc77d\uace0 \uc790\uc720\uc640 \uc18c\uc720\uc758 \uac08\ub4f1\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc74c\uc545", "categories": ["arts"], "url": "stories/carmen-love-freedom-and-stage/index.html", "image": "../media/carmen-love-freedom-and-stage.png", "alt": "\uc138\ube44\uc57c\ub97c \ub5a0\uc62c\ub9ac\ub294 \ubb34\ub300\uc5d0\uc11c \ub5a8\uc5b4\uc838 \ub9c8\uc8fc \uc120 \uce74\ub974\uba58\uacfc \uc7a5\uad50\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uce74\ub974\uba58 \u2014 \uc775\uc219\ud55c \ub178\ub798 \ub4a4\uc5d0\ub294 \uc5b4\ub5a4 \uc774\uc57c\uae30\uac00 \uc788\uc744\uae4c \ube44\uc81c\uc758 \uc624\ud398\ub77c\uc5d0\uc11c \uc0ac\ub791\uc758 \ud638\uc18c\uc640 \uc120\ud0dd\uc758 \uac70\uc808\uc744 \ub4e3\uae30 \ub124 \ub9c9\uc758 \uc904\uac70\ub9ac\uc640 \ud558\ubc14\ub124\ub77c\u00b7\ud22c\uc6b0\uc0ac\uc758 \ub178\ub798\u00b7\uaf43\ub178\ub798\ub97c \ud568\uaed8 \uc77d\uace0 \uc790\uc720\uc640 \uc18c\uc720\uc758 \uac08\ub4f1\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc74c\uc545 \ubb38\ud654\uc640 \uc608\uc220 \uad11\uace0\uc640 \uacf5\uc5f0\uc5d0\uc11c \ud55c \ubc88\ucbe4 \ub4e4\uc5c8\uc744 \uc120\uc728\uc774 \uc788\ub2e4. \ube44\uc81c\uc758 \uc624\ud398\ub77c \u300e\uce74\ub974\uba58\u300f\uc5d0 \ub098\uc624\ub294 \ud558\ubc14\ub124\ub77c\uc640 \ud22c\uc6b0\uc0ac\uc758 \ub178\ub798\ub2e4. \uba5c\ub85c\ub514\ub9cc \ub4e4\uc73c\uba74 \ud654\ub824\ud55c \ucd95\uc81c\ucc98\ub7fc \ub290\uaef4\uc9c0\uc9c0\ub9cc \ubb34\ub300\uc758 \uc774\uc57c\uae30\ub294 \uc0ac\ub791\uacfc \uc9c8\ud22c, \uac70\uc808\uacfc \ud3ed\ub825\uc73c\ub85c \ud758\ub7ec\uac04\ub2e4. \ud30c\ub9ac\uc5d0\uc11c 1875\ub144 \ucc98\uc74c \uacf5\uc5f0\ub41c \uc774 \uc791\ud488\uc758 \ubc30\uacbd\uc740 \uc2a4\ud398\uc778\uc758 \uc138\ube44\uc57c\ub2e4. \uc6d0\uc791 \uc18c\uc124\uc744 \ubc14\ud0d5\uc73c\ub85c \ud558\ub418 \uc624\ud398\ub77c\uc758 \uc778\ubb3c\uacfc \uad6c\uc131\uc774 \ub354\ud574\uc84c\ub2e4. \uc544\ub798\uc5d0\ub294 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \ube44\uadf9\uc801\uc778 \uacb0\ub9d0\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4. \uccab \ub9c9\uc5d0\uc11c \ubcd1\uc0ac\ub4e4\uacfc \ub2f4\ubc30 \uacf5\uc7a5 \ub178\ub3d9\uc790\ub4e4\uc774 \uc624\uac04\ub2e4. \ubbf8\uce74\uc5d8\ub77c\ub294 \ub3c8 \ud638\uc138\uc5d0\uac8c \uc5b4\uba38\ub2c8\uc758 \uc18c\uc2dd\uc744 \uc804\ud558\ub7ec \uc628\ub2e4. \uce74\ub974\uba58\uc740 \ud638\uc138\uc5d0\uac8c \uad00\uc2ec\uc744 \ubcf4\uc774\uba70 \uaf43\uc744 \ub358\uc9c4\ub2e4. \uc775\uc219\ud55c \uace0\ud5a5\uc758 \uad00\uacc4\uc640 \ub0af\uc120 \ub04c\ub9bc\uc774 \uadf8\uc758 \uc55e\uc5d0\uc11c \ub9cc\ub09c\ub2e4. \uacf5\uc7a5\uc5d0\uc11c \ub2e4\ud23c\uc774 \ubc8c\uc5b4\uc9c4 \ub4a4 \uce74\ub974\uba58\uc740 \ubd99\uc7a1\ud78c\ub2e4. \ud638\uc138\ub294 \uadf8\ub140\ub97c \ud638\uc1a1\ud558\ub294 \uc784\ubb34\ub97c \ub9e1\uc9c0\ub9cc \uacb0\uad6d \ud0c8\ucd9c\uc744 \ub3d5\ub294\ub2e4. \uadf8 \uc120\ud0dd\uc758 \ub300\uac00\ub294 \uc790\uc2e0\uc758 \ucc98\ubc8c\uc774\ub2e4. \uc0ac\ub791\uc758 \uc2dc\uc791\uc740 \uc774\ubbf8 \uad70\uc778\uc758 \uc758\ubb34\uc640 \uac1c\uc778\uc758 \uc695\ub9dd\uc774 \ucda9\ub3cc\ud558\ub294 \uc0ac\uac74\uc774 \ub41c\ub2e4. \uce74\ub974\uba58\uc774 \ucc98\uc74c \ubd80\ub974\ub294 \ud558\ubc14\ub124\ub77c\ub294 \uc0ac\ub791\uc744 \uba85\ub839\ud558\uac70\ub098 \ubd99\ub4e4\uae30 \uc5b4\ub835\ub2e4\ub294 \ud0dc\ub3c4\ub97c \uc804\ud55c\ub2e4. \ubc18\ubcf5\ub418\ub294 \ubc18\uc8fc\uc640 \uc720\uc5f0\ud558\uac8c \uc6c0\uc9c1\uc774\ub294 \uc120\uc728\uc740 \uc27d\uac8c \uadc0\uc5d0 \ub0a8\ub294\ub2e4. \uadf8\ub7ec\ub098 \ub178\ub798\ub294 \uad00\uac1d\uc744 \uc990\uac81\uac8c \ud558\ub294 \uc7a5\uc2dd\uc5d0 \uadf8\uce58\uc9c0 \uc54a\ub294\ub2e4. \uadf8\ub140\uac00 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \uc0ac\ub791\uc744 \ub9d0\ud558\ub294\uc9c0 \uba3c\uc800 \uc54c\ub824 \uc900\ub2e4. \uc55e\uc73c\ub85c\ub3c4 \uc0ac\ub791\uc744 \uc601\uc6d0\ud55c \ubcf5\uc885\uc758 \uc57d\uc18d\uc73c\ub85c \uc0dd\uac01\ud558\uc9c0 \uc54a\uc73c\ub9ac\ub77c\ub294 \ub2e8\uc11c\ub2e4. \uc775\uc219\ud55c \uc120\uc728\uc744 \uc778\ubb3c\uc758 \ub9d0\ub85c \ub4e4\uc73c\uba74 \uc774\ud6c4 \ud638\uc138\uc640\uc758 \uac08\ub4f1\uc774 \uc870\uae08 \ub354 \ubd84\uba85\ud574\uc9c4\ub2e4. \ub450 \ubc88\uc9f8 \ub9c9\uc5d0\uc11c\ub294 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc5ec \ub178\ub798\ud558\uace0 \ucda4\ucd94\ub294 \uacf5\uac04\uc5d0 \ud22c\uc6b0\uc0ac \uc5d0\uc2a4\uce74\ubbf8\uc694\uac00 \ub4f1\uc7a5\ud55c\ub2e4. \uadf8\uc758 \ub178\ub798\uc5d0\ub294 \uad00\uc911\uc758 \ud658\ud638\uc640 \uba85\uc131, \uacbd\uae30\uc7a5\uc758 \ud765\ubd84\uc774 \ub2f4\uaca8 \uc788\ub2e4. \uc0ac\uc801\uc778 \uac10\uc815\uacfc\ub294 \ub2e4\ub978 \uacf5\uac1c\uc801\uc778 \uc790\uc2e0\uac10\uc774 \ubb34\ub300\ub97c \ucc44\uc6b4\ub2e4. \ud22c\uc6b0\uc0ac\uc758 \ub178\ub798\uac00 \uc774\uc57c\uae30 \ubc16\uc5d0\uc11c\ub3c4 \uc720\uba85\ud55c \uc774\uc720\ub97c \uc9d0\uc791\ud560 \uc218 \uc788\ub2e4. \uc5ec\ub7ff\uc774 \ub530\ub77c \ubd80\ub974\uae30 \uc88b\uc740 \uc120\uba85\ud55c \uc120\uc728\uacfc \ud798\ucc2c \ubd84\uc704\uae30\uac00 \uc788\ub2e4. \uc791\ud488 \uc548\uc5d0\uc11c\ub294 \uce74\ub974\uba58\uc5d0\uac8c \uad00\uc2ec\uc744 \ubcf4\uc774\ub294 \ub610 \ud55c \uc0ac\ub78c\uc758 \uc874\uc7ac\ub97c \uad00\uac1d\uc5d0\uac8c \uac15\ud558\uac8c \uac01\uc778\ud55c\ub2e4. \ud638\uc138\ub294 \uce74\ub974\uba58\uc774 \uc900 \uaf43\uc744 \uac04\uc9c1\ud574 \uc654\ub2e4\uace0 \ub178\ub798\ud55c\ub2e4. \uaf43\ub178\ub798\ub294 \ud558\ubc14\ub124\ub77c\uc640 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uc0ac\ub791\uc744 \ub4e4\ub824\uc900\ub2e4. \uadf8\uc5d0\uac8c \uaf43\uc740 \uac07\ud600 \uc9c0\ub0b8 \uc2dc\uac04\uc5d0\ub3c4 \ubc84\ub9ac\uc9c0 \ubabb\ud55c \uac10\uc815\uc758 \ud45c\uc2dd\uc774\uc5c8\ub2e4. \uadf8 \uc9c4\uc2ec\uc744 \ub4e3\ub294\ub2e4\uace0 \ub450 \uc0ac\ub78c\uc758 \uc0dd\uac01\uc774 \uac19\uc544\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uce74\ub974\uba58\uc740 \ud638\uc138\uac00 \uc790\uc2e0\uc758 \uc0dd\ud65c\uacfc \uc790\uc720\uc5d0 \ud568\uaed8\ud558\uae30\ub97c \uc6d0\ud558\uace0, \ud638\uc138\ub294 \uad70\uc778\uc758 \uc758\ubb34\uc640 \uadf8\ub140 \uc0ac\uc774\uc5d0\uc11c \ud754\ub4e4\ub9b0\ub2e4. \uc544\ub984\ub2e4\uc6b4 \uc0ac\ub791\uc758 \ub178\ub798\uc640 \uad00\uacc4\uac00 \uc9c0\uc18d\ub420 \uc870\uac74\uc740 \uc11c\ub85c \ub2e4\ub97c \uc218 \uc788\uc5c8\ub2e4. \ud638\uc138\ub294 \uacb0\uad6d \ubc00\uc218\uafbc\ub4e4\uacfc \ud568\uaed8 \uc0b0\uc73c\ub85c \uac04\ub2e4. \uadf8\ub7ec\ub098 \uce74\ub974\uba58\uc758 \ub9c8\uc74c\uc740 \ub2ec\ub77c\uc9c0\uace0 \ub450 \uc0ac\ub78c\uc758 \uad00\uacc4\ub294 \uac70\uce60\uc5b4\uc9c4\ub2e4. \uc5d0\uc2a4\uce74\ubbf8\uc694\uac00 \ucc3e\uc544\uc624\uc790 \ud638\uc138\uc758 \uc9c8\ud22c\ub294 \ub354 \ucee4\uc9c4\ub2e4. \uc7a5\uc18c\ub97c \uc62e\uacbc\ub2e4\uace0 \uc11c\ub85c \ub2e4\ub978 \uae30\ub300\uac00 \ud574\uacb0\ub418\uc9c0 \uc54a\uc558\ub2e4. \ubbf8\uce74\uc5d8\ub77c\ub294 \uc704\ud5d8\ud55c \uacf3\uae4c\uc9c0 \uc640\uc11c \uc5b4\uba38\ub2c8\uc758 \uc18c\uc2dd\uc744 \uc804\ud55c\ub2e4. \ud638\uc138\uac00 \ub5a0\ub098\uc628 \uc0b6\uc744 \ub2e4\uc2dc \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uc778\ubb3c\uc774\ub2e4. \uadf8\ub140\ub97c \ub2e8\uc9c0 \ucc29\ud55c \uc5ec\uc131\uc758 \ube44\uad50 \ub300\uc0c1\uc73c\ub85c\ub9cc \ubcf4\uae30\ubcf4\ub2e4, \ub450\ub824\uc6c0\uc744 \ubb34\ub985\uc4f0\uace0 \ud589\ub3d9\ud558\ub294 \uc0ac\ub78c\uc73c\ub85c \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uce74\ub974\uba58\uacfc \ub3d9\ub8cc\ub4e4\uc774 \uce74\ub4dc\ub97c \ubcf4\ub294 \uc7a5\uba74\uc740 \uc55e\uc120 \ucda4\uacfc \ub178\ub798\uc758 \ub4e4\ub72c \ubd84\uc704\uae30\uc5d0\uc11c \ubc97\uc5b4\ub09c\ub2e4. \uc8fd\uc74c\uc758 \uc608\uac10\uc774 \ubb34\ub300\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uad00\uac1d\uc740 \uc778\ubb3c\ubcf4\ub2e4 \uba3c\uc800 \ub2e4\uac00\uc62c \ube44\uadf9\uc744 \ub290\ub07c\uba74\uc11c\ub3c4 \uc0ac\uac74\uc744 \uba48\ucd9c \uc218 \uc5c6\ub2e4. \uc74c\uc545\uc740 \uac19\uc740 \uc791\ud488 \uc548\uc5d0\uc11c \uc774\ucc98\ub7fc \uc7a5\uba74\uc758 \uc628\ub3c4\ub97c \ubc14\uafbc\ub2e4. \uc720\uba85\ud55c \uba87 \uace1\ub9cc \uace8\ub77c \ub4e4\uc744 \ub54c \ub193\uce58\uae30 \uc26c\uc6b4 \ubd80\ubd84\uc774\ub2e4. \ub178\ub798 \uc0ac\uc774\uc758 \ubcc0\ud654\uc640 \uc778\ubb3c\ub4e4\uc758 \ub300\ub2f5\uae4c\uc9c0 \ub530\ub77c\uac00\uba74 \ubc1d\uc740 \uc120\uc728\uc774 \ube44\uadf9\uc744 \ub354 \uc120\uba85\ud558\uac8c \ub9cc\ub4dc\ub294 \ubc29\uc2dd\ub3c4 \ub4e4\ub9b0\ub2e4. \ub9c8\uc9c0\ub9c9 \ub9c9\uc5d0\uc11c \uce74\ub974\uba58\uc740 \uc5d0\uc2a4\uce74\ubbf8\uc694\uc640 \ud568\uaed8 \ud22c\uc6b0\uc7a5\uc5d0 \uc628\ub2e4. \ud638\uc138\uac00 \uc790\uc2e0\uc744 \ucc3e\uace0 \uc788\ub2e4\ub294 \uacbd\uace0\ub97c \ub4e3\uc9c0\ub9cc \ud53c\ud558\uc9c0 \uc54a\ub294\ub2e4. \uacbd\uae30\uc7a5 \uc548\uc5d0\uc11c \ud658\ud638\uac00 \uc774\uc5b4\uc9c0\ub294 \ub3d9\uc548 \ubc14\uae65\uc5d0\uc11c\ub294 \ud638\uc138\uc640 \uce74\ub974\uba58\uc758 \ub300\ud654\uac00 \ub9c9\ub2e4\ub978 \uae38\ub85c \ud5a5\ud55c\ub2e4. \ud638\uc138\ub294 \ub3cc\uc544\uc624\ub77c\uace0 \ud638\uc18c\ud558\uace0 \uce74\ub974\uba58\uc740 \uac70\uc808\ud55c\ub2e4. \uadf8\uac00 \uadf8\ub140\ub97c \uc0b4\ud574\ud558\uba74\uc11c \ube44\uadf9\uc774 \ub05d\ub09c\ub2e4. \uc0ac\ub791\uc774 \uae4a\uc5c8\ub2e4\ub294 \ub9d0\ub85c \uc774 \ud3ed\ub825\uc744 \uc815\ub2f9\ud654\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc0c1\ub300\uc758 \uc120\ud0dd\uc744 \ubc1b\uc544\ub4e4\uc77c \uc218 \uc5c6\ub294 \uac10\uc815\uc774 \uc5b4\ub5bb\uac8c \ud30c\uad34\ub85c \ubcc0\ud558\ub294\uc9c0\uac00 \ubb34\ub300\uc5d0 \ub0a8\ub294\ub2e4. \uc774 \uc624\ud398\ub77c\uc5d0\ub294 19\uc138\uae30 \ud504\ub791\uc2a4\uac00 \uc0c1\uc0c1\ud55c \uc2a4\ud398\uc778\uacfc \ub85c\ub9c8\ub2c8 \uc778\ubb3c\uc758 \uc774\ubbf8\uc9c0\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \ub0af\uc120 \uc138\uacc4\ub97c \ub9e4\ub825\uc801\uc774\uac70\ub098 \uc704\ud5d8\ud558\uac8c \uadf8\ub9ac\ub294 \uc2dc\uc120\ub3c4 \uc788\ub2e4. \ubb34\ub300\uc758 \uc778\ubb3c\uc744 \uc2e4\uc81c \ubbfc\uc871\uacfc \uc5ec\uc131 \uc804\uccb4\uc758 \uc131\uaca9\uc73c\ub85c \ubc1b\uc544\ub4e4\uc774\uc9c0 \uc54a\ub3c4\ub85d \uc8fc\uc758\ud560 \ub300\ubaa9\uc774\ub2e4. \uc624\ub798\ub41c \ud574\uc124\uc740 \uce74\ub974\uba58\uc744 \ub0c9\ud639\ud55c \uc720\ud639\uc790\ub85c \uc27d\uac8c \uaddc\uc815\ud558\uae30\ub3c4 \ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc791\ud488\uc744 \uc77d\ub294 \uae38\uc740 \ud558\ub098\uac00 \uc544\ub2c8\ub2e4. \uadf8\ub140\uc758 \uc790\uc720\uc640 \uac70\uc808, \ud638\uc138\uc758 \uc9d1\ucc29\uc744 \uc911\uc2ec\uc5d0 \ub193\uc73c\uba74 \uc774\ubbf8 \uc54c\uace0 \uc788\ub358 \uc904\uac70\ub9ac\ub3c4 \ub2e4\ub974\uac8c \ub4e4\ub9b4 \uc218 \uc788\ub2e4. \uba3c\uc800 \ud558\ubc14\ub124\ub77c\uc640 \ud22c\uc6b0\uc0ac\uc758 \ub178\ub798\ub97c \ub4e3\uace0, \uaf43\ub178\ub798\uc640 \ub9c8\uc9c0\ub9c9 \ub300\uba74\uc744 \uc774\uc5b4 \ub4e4\uc5b4 \ubcf4\uc790. \uac19\uc740 \uc0ac\ub791\uc774\ub77c\ub294 \ub9d0\uc774 \uc778\ubb3c\ub9c8\ub2e4 \ub2e4\ub978 \ub73b\uc73c\ub85c \uc4f0\uc778\ub2e4. \ubc18\ubcf5\ub418\ub294 \uc120\uc728\ub3c4 \ub204\uad6c\uc758 \uc5b4\ub5a4 \uc0c1\ud669\uc5d0 \ub3cc\uc544\uc624\ub294\uc9c0\uc5d0 \ub530\ub77c \ub290\ub08c\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uac00\uc218\uc758 \ud45c\ud604\uacfc \ubb34\ub300 \ud574\uc11d\uc5d0 \ub530\ub77c \uad00\uac1d\uc774 \ubc1b\ub294 \uc778\uc0c1\ub3c4 \ubc14\ub010\ub2e4. \u300e\uce74\ub974\uba58\u300f\uc744 \uc624\ub798 \ub4e3\uac8c \ub9cc\ub4dc\ub294 \uac83\uc740 \uce5c\uc219\ud55c \uba5c\ub85c\ub514\uc640 \ud568\uaed8 \ub0a8\ub294 \ubd88\ud3b8\ud55c \uc9c8\ubb38\uc774\ub2e4. \uc0ac\ub791\ud55c\ub2e4\uace0 \ub9d0\ud558\ub294 \uac83\uacfc \uc0c1\ub300\ub97c \uc790\uae30 \ub73b\ub300\ub85c \uc6c0\uc9c1\uc774\ub824\ub294 \uac83\uc740 \uc5b4\ub514\uc5d0\uc11c \uac08\ub77c\uc9c8\uae4c."}, {"id": "chardin-grace-before-meal", "title": "\uc2dd\uc0ac \uc804\uc758 \uae30\ub3c4 \u2014 \uc218\ud504\uac00 \uc2dd\uae30 \uc804, \uc7a0\uae50 \uba48\ucd98 \uc2dc\uac04", "summary": "\uc5b4\ub978\uacfc \ub450 \uc544\uc774, \uc2dd\uae30\uc640 \uc7a5\ub09c\uac10\uc758 \uad00\uacc4\ub85c 18\uc138\uae30 \uc77c\uc0c1\uc758 \ud68c\ud654\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/chardin-grace-before-meal/index.html", "image": "../media/chardin-grace-before-meal.jpg", "alt": "\uc0e4\ub974\ub315\uc758 \uc2dd\uc0ac \uc804\uc758 \uae30\ub3c4. \uc2dd\ud0c1 \uacc1\uc758 \uc5b4\ub978\uacfc \ub450 \uc544\uc774, \uc218\ud504 \uadf8\ub987\uacfc \uc758\uc790 \ub4a4\uc758 \uc791\uc740 \ubd81\uc774 \ubcf4\uc785\ub2c8\ub2e4.", "text": "\uc2dd\uc0ac \uc804\uc758 \uae30\ub3c4 \u2014 \uc218\ud504\uac00 \uc2dd\uae30 \uc804, \uc7a0\uae50 \uba48\ucd98 \uc2dc\uac04 \uc0e4\ub974\ub315\uc758 \uc791\uc740 \uc2dd\ud0c1\uc5d0\uc11c \uadf8\ub9bc\uc758 \uc911\uc2ec\uc744 \ucc3e\ub294 \ubc29\ubc95 \uc5b4\ub978\uacfc \ub450 \uc544\uc774, \uc2dd\uae30\uc640 \uc7a5\ub09c\uac10\uc758 \uad00\uacc4\ub85c 18\uc138\uae30 \uc77c\uc0c1\uc758 \ud68c\ud654\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \uc218\ud504\ub97c \ub2f4\uc73c\ub824\ub358 \uc5b4\ub978\uc774 \uace0\uac1c\ub97c \ub3cc\ub9b0\ub2e4. \uc2dd\ud0c1 \uacc1\uc758 \ub450 \uc544\uc774\ub294 \uc190\uc744 \ubaa8\uc73c\uace0 \uc788\ub2e4. \uc544\uc8fc \uc7a0\uae50 \uba48\ucd98 \uc2dd\uc0ac \uc2dc\uac04\uc774\ub2e4. \ud070 \uc5ed\uc0ac\uc801 \uc0ac\uac74\ub3c4 \uae30\uc801\ub3c4 \uc5c6\ub294\ub370 \uc7a5\ubc14\ud2f0\uc2a4\ud2b8 \uc2dc\uba54\uc639 \uc0e4\ub974\ub315\uc740 \uc774 \uc21c\uac04\uc744 \ud55c \uc7a5\uc758 \uadf8\ub9bc\uc73c\ub85c \ub0a8\uacbc\ub2e4. \u3008\uc2dd\uc0ac \uc804\uc758 \uae30\ub3c4\u3009\ub294 \ub204\uac00 \ubb34\uc5c7\uc744 \ud558\ub294\uc9c0 \ube44\uad50\uc801 \uc27d\uac8c \uc54c \uc218 \uc788\ub294 \uc791\ud488\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \uccab\ub208\uc5d0 \ub0b4\uc6a9\uc744 \uc54c\uc544\ubcf4\uc558\uc73c\ub2c8 \ub2e4 \ubcf4\uc558\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc0ac\ub78c\uacfc \ubb3c\uac74\uc774 \uc5b4\ub5bb\uac8c \ub193\uc600\ub294\uc9c0 \uc0b4\ud53c\uba74 \ud3c9\ubc94\ud55c \uc7a5\uba74\uc758 \uc9dc\uc784\uc774 \ubcf4\uc778\ub2e4. \ud504\ub791\uc2a4\uc5b4 \uc81c\ubaa9 Le B\u00e9n\u00e9dicit\u00e9\ub294 \uc2dd\uc0ac \uc804\uc5d0 \ub4dc\ub9ac\ub294 \uac10\uc0ac\uc758 \uae30\ub3c4\ub97c \uac00\ub9ac\ud0a8\ub2e4. \uc544\uc774\ub4e4\uc774 \uc190\uc744 \ubaa8\uc740 \uc774\uc720\ub97c \uc54c\ub824 \uc8fc\ub294 \ub2e8\uc11c\ub2e4. \uc7a5\uba74\uc744 \uc774\ud574\ud558\ub294 \ub370 \uae34 \uc885\uad50\uc801 \ubc30\uacbd\uc9c0\uc2dd\uc774 \ud544\uc694\ud558\uc9c0\ub294 \uc54a\ub2e4. \uc74c\uc2dd\uc774 \ub098\uc624\uae30 \uc804 \ud568\uaed8 \uc7a0\uc2dc \uba48\ucd94\ub294 \uc2dc\uac04\uc73c\ub85c \ub4e4\uc5b4\uac00\uba74 \ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc774 \uc7a5\uba74\uc744 \ubaa8\ub4e0 \uc720\ub7fd \uac00\uc815\uc758 \uacf5\ud1b5\ub41c \ubaa8\uc2b5\uc73c\ub85c \uc77c\ubc18\ud654\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ud2b9\uc815 \uc2dc\ub300\uc758 \uac00\uc815\uc0dd\ud65c\uc744 \uc18c\uc7ac\ub85c \ud654\uac00\uac00 \uad6c\uc131\ud55c \uadf8\ub9bc\uc774\ub2e4. \uc61b \uc77c\uc0c1\uc758 \ud55c \ub2e8\uba74\uc744 \ubcf4\uc5ec \uc900\ub2e4\ub294 \uc810\uacfc, \ub2f9\uc2dc \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \uc0dd\ud65c\uc744 \uadf8\ub300\ub85c \uc99d\uba85\ud55c\ub2e4\ub294 \uc8fc\uc7a5\uc740 \ub2e4\ub974\ub2e4. \uc5b4\ub978\uc758 \uc190\uc740 \uc74c\uc2dd\uc744 \ub2f4\ub294 \uc77c\uc5d0 \uac00\uae4c\uc774 \uc788\uace0 \uc5bc\uad74\uc740 \uc544\uc774\ub4e4 \ucabd\uc73c\ub85c \ud5a5\ud55c\ub2e4. \ubab8 \uc804\uccb4\ub97c \ud55c \ubc88\uc5d0 \ubcf4\uba74 \ub3cc\ubd04\uc774 \ub2e8\uc21c\ud55c \ubb3c\uac74\uc758 \uc804\ub2ec\ub9cc\uc740 \uc544\ub2c8\ub77c\ub294 \ub290\ub08c\uc744 \ubc1b\uc744 \uc218 \uc788\ub2e4. \uc74c\uc2dd\uc744 \ub0b4\uba74\uc11c \uc544\uc774\uac00 \ubb34\uc5c7\uc744 \ud558\ub294\uc9c0\ub3c4 \uc0b4\ud53c\ub294 \uac83\uc774\ub2e4. \uc774\uac83\uc744 \ud2b9\uc815 \uc778\ubb3c\uc758 \uc18d\ub9c8\uc74c\uc744 \uc6b0\ub9ac\uac00 \uc815\ud655\ud788 \uc548\ub2e4\ub294 \ub73b\uc73c\ub85c \ubc1b\uc544\ub4e4\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uc190\uacfc \uc2dc\uc120\uc774 \uc11c\ub85c \ub2e4\ub978 \ubc29\ud5a5\uc758 \uad00\uacc4\ub97c \ub9cc\ub4e0\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uad00\ucc30\ud558\uba74 \ub41c\ub2e4. \ud55c \ubab8 \uc548\uc758 \uc791\uc740 \ubc29\ud5a5 \ucc28\uc774\uac00 \uc0ac\ub78c \uc0ac\uc774\uc758 \uc5f0\uacb0\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc544\uc774\ub4e4\uc758 \ud06c\uae30\uc640 \uc549\uc740 \uc790\uc138, \ubc14\ub77c\ubcf4\ub294 \ubc29\ud5a5\uc5d0\ub294 \ucc28\uc774\uac00 \uc788\ub2e4. \ub450 \uc0ac\ub78c\uc744 \ud55c \ub369\uc5b4\ub9ac\ub85c \ubcf4\uace0 \u2018\uae30\ub3c4\ud558\ub294 \uc544\uc774\ub4e4\u2019\uc774\ub77c\uace0\ub9cc \ubd80\ub974\uba74 \uc774\ub7f0 \uc791\uc740 \ucc28\uc774\ub97c \uc9c0\ub098\uce58\uae30 \uc27d\ub2e4. \uac01\uc790\uc758 \uc5bc\uad74\uacfc \uc190\uc744 \ub530\ub85c \ubcf8 \ub4a4 \ub2e4\uc2dc \ud568\uaed8 \ubcf4\uba74 \uad00\uacc4\uac00 \uc120\uba85\ud574\uc9c4\ub2e4. \uc5b4\ub9b0\uc544\uc774\uc5d0\uac8c \uc2dd\uc0ac \uc608\uc808\uc744 \uac00\ub974\uce58\ub294 \uc2dc\uac04\ucc98\ub7fc \uc77d\uc744 \uc218\ub3c4 \uc788\uc9c0\ub9cc, \uadf8\ub9bc\uc774 \ubaa8\ub4e0 \ub300\ud654\ub97c \uc9c1\uc811 \uc54c\ub824 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub204\uac00 \ubc29\uae08 \ubb34\uc2a8 \ub9d0\uc744 \ud588\ub294\uc9c0 \ud655\uc815\ud558\uae30\ubcf4\ub2e4 \uc9c0\uae08 \ub208\uc55e\uc5d0 \ub0a8\uc740 \uc790\uc138\ub97c \ubcf4\uc790. \ud68c\ud654\uc758 \uc774\uc57c\uae30\ub294 \ub4e4\ub9ac\uc9c0 \uc54a\ub294 \ub300\uc0ac\ub97c \ubc18\ub4dc\uc2dc \ub9cc\ub4e4\uc5b4 \ub123\uc5b4\uc57c\ub9cc \uc0dd\uae30\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc791\uc740 \ubd81\uc740 \uc774 \ubc29\uc774 \uc5c4\uc219\ud55c \uae30\ub3c4\ub9cc\uc744 \uc704\ud55c \uacf3\uc774 \uc544\ub2c8\ub77c \uc544\uc774\uac00 \uc0dd\ud65c\ud558\ub294 \uacf5\uac04\uc784\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uc544\uc774\ub4e4\uc740 \uc2dd\uc0ac\ud558\uae30 \uc804\uc5d0 \ub2e4\ub978 \ub180\uc774\ub97c \ud588\uc744 \uc218\ub3c4 \uc788\ub2e4. \ub2e4\ub9cc \uc2e4\uc81c\ub85c \uc5b8\uc81c \ubd81\uc744 \ucce4\ub294\uc9c0\uae4c\uc9c0 \uadf8\ub9bc\uc774 \uc54c\ub824 \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb3c\uac74\uc774 \ub354\ud558\ub294 \uc0dd\ud65c\uc758 \uae30\uc6b4\uc744 \ub290\uaef4 \ubcf4\uba74 \ucda9\ubd84\ud558\ub2e4. \uc2dd\ud0c1\uacfc \uc758\uc790, \uadf8\ub987\ub4e4\uc740 \ubc30\uacbd\uc758 \ube48\uce78\uc744 \ucc44\uc6b0\ub824\uace0 \uc544\ubb34\ub807\uac8c\ub098 \ub193\uc778 \uac83\ucc98\ub7fc \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ubab8\uacfc \ubb3c\uac74 \uc0ac\uc774\uc758 \uac70\ub9ac\uac00 \uc7a5\uba74\uc758 \ud06c\uae30\ub97c \uc815\ud55c\ub2e4. \ubc29 \uc804\uccb4\uac00 \uac70\ub300\ud55c \ubb34\ub300\uac00 \uc544\ub2c8\ub77c \uc11c\ub85c \uc190\uacfc \ub208\uae38\uc774 \ub2ff\ub294 \uc790\ub9ac\ub85c \ub2e4\uac00\uc628\ub2e4. \ubc1d\uc740 \uc2dd\ud0c1\ubcf4\ub294 \ud654\uba74\uc5d0\uc11c \ub113\uc740 \uc790\ub9ac\ub97c \ucc28\uc9c0\ud55c\ub2e4. \uc8fc\ubcc0\uc758 \uc5b4\ub450\uc6b4 \ubd80\ubd84\uacfc \ube44\uad50\ud558\uba74 \uc2dc\uc120\uc774 \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc2dd\uc0ac\ud558\ub294 \uc790\ub9ac\ub85c \ubaa8\uc778\ub2e4. \uc778\ubb3c\uc758 \uc637\uacfc \uadf8\ub987\uc744 \ubcfc \ub54c\ub3c4 \uadf8 \ubc1d\uc740 \ubc14\ud0d5\uc774 \uc5b4\ub5a4 \uc5ed\ud560\uc744 \ud558\ub294\uc9c0 \ud568\uaed8 \uc0b4\ud3b4\ubcf4\uc790. \uc0c9\uc744 \ud654\ub824\ud568\uc758 \uc815\ub3c4\ub85c\ub9cc \ud3c9\uac00\ud558\uc9c0 \uc54a\uc73c\uba74 \uc774 \uadf8\ub9bc\uc758 \uc7ac\ubbf8\uac00 \ucee4\uc9c4\ub2e4. \ubb34\uc5c7\uc774 \uc55e\uc73c\ub85c \ub2e4\uac00\uc624\uace0 \ubb34\uc5c7\uc774 \ub4a4\ub85c \ubb3c\ub7ec\ub098\ub294\uc9c0, \ub2e4\ub978 \ubb3c\uac74\uc758 \uc0c9\uc774 \uacc1\uc5d0 \ub193\uc77c \ub54c \uc5b4\ub5bb\uac8c \ub290\uaef4\uc9c0\ub294\uc9c0 \ubcfc \uc218 \uc788\ub2e4. \uc815\ubb3c\ud654\ub97c \ub9ce\uc774 \uadf8\ub9b0 \uc0e4\ub974\ub315\uc758 \uadf8\ub9bc\uc5d0\uc11c \uc0ac\ub78c\uacfc \uc0ac\ubb3c\uc740 \uc11c\ub85c\uc758 \uc790\ub9ac\ub97c \ub9cc\ub4e0\ub2e4. \uc0e4\ub974\ub315\uc740 1699\ub144\uc5d0 \ud0dc\uc5b4\ub098 1779\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub09c \ud504\ub791\uc2a4 \ud654\uac00\ub2e4. \uc774 \uc791\ud488\uc5d0\uc11c\ub294 \ud654\ub824\ud55c \uc758\uc2dd\uc774\ub098 \uc601\uc6c5\uc758 \ud589\ub3d9 \ub300\uc2e0 \uc2dd\uc0ac \uc804\uc758 \uac00\uc871\uacfc \uc0dd\ud65c \ubb3c\uac74\uc774 \uc911\uc2ec\uc774 \ub41c\ub2e4. \ubb34\uc5c7\uc774 \uadf8\ub9bc\uc758 \uc911\uc694\ud55c \uc8fc\uc81c\uac00 \ub420 \uc218 \uc788\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ud558\ub294 \uc120\ud0dd\uc774\ub2e4. \uadf8\ub7ec\ub098 \uc18c\ubc15\ud574 \ubcf4\uc774\ub294 \uc7a5\uba74\uc774\ub77c\uace0 \ud574\uc11c \ud654\uac00\uac00 \uc190\uc744 \ub300\uc9c0 \uc54a\uc740 \uc0dd\ud65c \uc0ac\uc9c4\ucc98\ub7fc \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uac01\uc790\uc758 \uc790\uc138\uc640 \ube5b, \ubb3c\uac74\uc758 \uac04\uaca9\uc740 \ud654\uba74\uc758 \uc77c\ubd80\ub2e4. \ud3c9\ubc94\ud55c \uc18c\uc7ac\uc640 \uc138\uc2ec\ud55c \uad6c\uc131\uc740 \ubc18\ub300\ub9d0\uc774 \uc544\ub2c8\ub2e4. \uc624\ud788\ub824 \uc775\uc219\ud55c \uc21c\uac04\uc774 \uc624\ub798 \ubcf4\uac8c \ub418\ub294 \uadf8\ub9bc\uc73c\ub85c \ubc14\ub00c\ub294 \uc774\uc720\uac00 \uadf8 \uc548\uc5d0 \uc788\ub2e4. \uc61b \ub3c4\ub85d\uc740 \uc774 \uc8fc\uc81c\uc758 \uc5ec\ub7ec \ud310\ubcf8\uc744 \uc5b8\uae09\ud55c\ub2e4. \ub530\ub77c\uc11c \uac19\uc740 \uc7a5\uba74\uc774 \ubcf4\uc774\ub294 \ub2e4\ub978 \uc0ac\uc9c4\uc744 \ub9cc\ub098\ub354\ub77c\ub3c4 \ubaa8\ub450 \uc9c0\uae08 \ub3c4\ud310\uacfc \uc644\uc804\ud788 \uac19\uc740 \uadf8\ub9bc\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc774 \uae00\uc5d0\uc11c \ud568\uaed8 \ubcf4\ub294 \uac83\uc740 \ub8e8\ube0c\ub974 \ub3c4\ub85d\uc5d0 \uc2e4\ub9b0 \uc18c\uc7a5\ubcf8\uc758 \uc0c9\ucc44 \uc7ac\ud604 \uc790\ub8cc\ub2e4. \uc61b \uc778\uc1c4\uc758 \uc0c9\uacfc \uc138\ubd80\uac00 \ud604\uc7ac\uc758 \uc2e4\ubb3c\uc744 \uadf8\ub300\ub85c \ubcf4\uc5ec \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub3c4\ud310\uc744 \ubcf4\uba74\uc11c \uc815\ud655\ud55c \ud45c\uba74\uc774\ub098 \uc2e4\uc81c \ud06c\uae30\ub97c \ub9c8\uc74c\ub300\ub85c \ucd94\uc815\ud558\uae30\ubcf4\ub2e4 \uc138 \uc0ac\ub78c\uc758 \ubc30\uce58\uc640 \uc2dd\ud0c1\uc758 \ubc1d\uae30, \uc8fc\ubcc0 \ubb3c\uac74\uc758 \uad00\uacc4\ub97c \uc0b4\ud3b4\ubcf4\uba74 \uc88b\ub2e4. \ub9e4\uccb4\uc758 \ud55c\uacc4\ub97c \uc54c\uc544\ub3c4 \uac10\uc0c1\uc758 \uae38\uc740 \ucda9\ubd84\ud788 \ub0a8\ub294\ub2e4. \uc624\ub298\uc758 \uac00\uc871 \uc2dd\uc0ac\uc640 \uc774 \uc7a5\uba74\uc740 \uc637\ub3c4 \uc74c\uc2dd\ub3c4 \uc0dd\ud65c \ubc29\uc2dd\ub3c4 \ub2e4\ub974\ub2e4. \uadf8 \ucc28\uc774\ub97c \uc9c0\uc6b4 \ucc44 \u2018\uc608\ub098 \uc9c0\uae08\uc774\ub098 \ub611\uac19\ub2e4\u2019\uace0 \ub05d\ub0b4\uae30\ubcf4\ub2e4, \ub2ec\ub77c\uc9c4 \uac83\uacfc \uc54c\uc544\ubcfc \uc218 \uc788\ub294 \uac83\uc744 \ud568\uaed8 \ubcf4\uba74 \uc88b\ub2e4. \ub204\uad70\uac00 \uc74c\uc2dd\uc744 \ub0b4\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc190\uc9d3\uc744 \uc0b4\ud53c\ub294 \uad00\uacc4\ub294 \ub0af\uc120 \uc61b \ubc29 \uc548\uc5d0\uc11c\ub3c4 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uae30\ub3c4\ud558\ub294 \uc7a5\uba74\uc744 \ud655\uc778\ud588\ub2e4\uba74, \ub450 \ubc88\uc9f8\uc5d0\ub294 \uc74c\uc2dd\uacfc \uc544\uc774\ub97c \ud568\uaed8 \ubcf4\ub294 \uc5b4\ub978\uc758 \uc5bc\uad74\uc744, \uc138 \ubc88\uc9f8\uc5d0\ub294 \uc7a5\ub09c\uac10\uacfc \uc2dd\uae30\ub97c \ucc3e\uc544\ubcf4\uc790. \ud070 \uc0ac\uac74\uc774 \uc5c6\ub294 \uadf8\ub9bc\ub3c4 \uc2dc\uc120\uc744 \uc62e\uae38 \ub54c\ub9c8\ub2e4 \uc0c8\ub85c\uc6b4 \uc911\uc2ec\uc744 \ub0b4\uc5b4 \uc900\ub2e4. \uc2dd\uc0ac\uac00 \uc2dc\uc791\ub418\uae30 \uc804\uc758 \uc7a0\uae50\uc774 \uc774\ub807\uac8c \uae34 \uac10\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4."}, {"id": "cherry-orchard-auction-and-firs", "title": "\ubc9a\uaf43 \ub3d9\uc0b0 \u2014 \uc544\ub984\ub2e4\uc6b4 \uc815\uc6d0\uc740 \uc65c \uacbd\ub9e4\uc5d0 \ub098\uc654\uc744\uae4c", "summary": "\ube5a\uacfc \uacbd\ub9e4, \ub85c\ud30c\ud78c\uc758 \uc81c\uc548\uacfc \ud53c\ub974\uc2a4\uc758 \ub9c8\uc9c0\ub9c9 \uc7a5\uba74\uc73c\ub85c \ubcc0\ud654\uc758 \uc2dc\uac04\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/cherry-orchard-auction-and-firs/index.html", "image": "../media/cherry-orchard-auction-and-firs.png", "alt": "\ub7ec\uc2dc\uc544\uc758 \uc800\ud0dd\uacfc \ubc9a\uaf43 \ub3d9\uc0b0, \uc5ec\ud589 \uac00\ubc29 \uc606\uc758 \uc5ec\uc778\uc744 \uadf8\ub9b0 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ubc9a\uaf43 \ub3d9\uc0b0 \u2014 \uc544\ub984\ub2e4\uc6b4 \uc815\uc6d0\uc740 \uc65c \uacbd\ub9e4\uc5d0 \ub098\uc654\uc744\uae4c \ub3cc\uc544\uc628 \uc9d1\uc5d0\ub294 \uae30\uc5b5\uacfc \ube5a\uc774 \ud568\uaed8 \uc788\ub2e4\uc5d0\uc11c \uc2dc\uc791\ud558\ub294 \uc5ed\uc0ac\uc640 \uc791\ud488 \uc77d\uae30 \ube5a\uacfc \uacbd\ub9e4, \ub85c\ud30c\ud78c\uc758 \uc81c\uc548\uacfc \ud53c\ub974\uc2a4\uc758 \ub9c8\uc9c0\ub9c9 \uc7a5\uba74\uc73c\ub85c \ubcc0\ud654\uc758 \uc2dc\uac04\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \uc624\ub798 \ub5a0\ub098 \uc788\ub358 \uc0ac\ub78c\uc774 \uc9d1\uc73c\ub85c \ub3cc\uc544\uc628\ub2e4. \ucc3d\ubc16\uc5d0\ub294 \ucd94\uc5b5\uc774 \uac00\ub4dd\ud55c \ubc9a\uaf43 \ub3d9\uc0b0\uc774 \uc788\uc9c0\ub9cc \uc601\uc9c0\ub294 \ube5a \ub54c\ubb38\uc5d0 \uacbd\ub9e4\uc5d0 \ub118\uc5b4\uac08 \ucc98\uc9c0\ub2e4. \uc548\ud1a4 \uccb4\ud638\ud504\uc758 \u300e\ubc9a\uaf43 \ub3d9\uc0b0\u300f\uc740 \uc0ac\ub77c\uc9c0\ub294 \uc544\ub984\ub2e4\uc6b4 \uc7a5\uc18c\ub97c \ubc14\ub77c\ubcf4\ub294 \uc774\uc57c\uae30\uc774\uba74\uc11c, \uadf8 \uc7a5\uc18c\ub97c \ub204\uad6c\uc758 \ub3c8\uacfc \ub178\ub3d9\uc73c\ub85c \uc720\uc9c0\ud574 \uc654\ub294\uc9c0 \ubb3b\ub294 \ud76c\uace1\uc774\ub2e4. \uc8fc\uc694 \uc0ac\uac74\uacfc \uacb0\ub9d0\uc744 \ub530\ub77c\uac00\uba74 \ubab0\ub77d\ud55c \uc61b \uc8fc\uc778\uacfc \uc131\uacf5\ud55c \uc0c8 \uc8fc\uc778\uc744 \uac04\ub2e8\ud788 \uc120\uc545\uc73c\ub85c \ub098\ub204\uae30 \uc5b4\ub835\ub2e4. \uc778\ubb3c\ub4e4\uc740 \ubcc0\ud654\ub97c \uc54c\uace0\ub3c4 \ub193\uce58\uace0, \uc11c\ub85c\ub97c \uc544\ub07c\uba74\uc11c\ub3c4 \ud544\uc694\ud55c \ub9d0\uc744 \ud558\uc9c0 \ubabb\ud55c\ub2e4. \uadf8 \uc5b4\uae0b\ub0a8\uc774 \uc774 \uc791\ud488\uc758 \uc6c3\uc74c\uacfc \uc2ac\ud514\uc744 \ud568\uaed8 \ub9cc\ub4e0\ub2e4. \ub77c\ub124\ud504\uc2a4\uce74\uc57c\ub294 \uc678\uad6d\uc5d0\uc11c \ub3cc\uc544\uc640 \ub538 \uc544\ub0d0\uc640 \uac00\uc871\ub4e4\uc744 \ub9cc\ub09c\ub2e4. \uc624\ube60 \uac00\uc608\ud504\uc640 \ud568\uaed8 \uc5b4\ub9b0 \uc2dc\uc808\uc758 \uc9d1\uacfc \uc815\uc6d0\uc744 \ubc14\ub77c\ubcf4\uc9c0\ub9cc, \ucd94\uc5b5\ub9cc\uc73c\ub85c \uc601\uc9c0\uc758 \uc7ac\uc815\uc744 \ud574\uacb0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ubc9a\uaf43 \ub3d9\uc0b0\uc740 \uac00\uc871\uc5d0\uac8c \ub9c8\uc74c\uc758 \uace0\ud5a5\uc778 \ub3d9\uc2dc\uc5d0 \ud314\ub9b4 \uc218 \uc788\ub294 \uc7ac\uc0b0\uc774\ub2e4. \uc774 \ub450 \uc131\uaca9\uc740 \uc778\ubb3c\ub9c8\ub2e4 \ub2e4\ub974\uac8c \ub2e4\uac00\uc628\ub2e4. \ub204\uad70\uac00\ub294 \uc544\ub984\ub2e4\uc6c0\uacfc \uae30\uc5b5\uc744 \uba3c\uc800 \ub9d0\ud558\uace0 \ub2e4\ub978 \ub204\uad70\uac00\ub294 \uae30\ud55c\uacfc \ube44\uc6a9\uc744 \ubcf8\ub2e4. \uac19\uc740 \ub545\uc744 \ubcf4\uba74\uc11c\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uac83\uc744 \ubcf4\ub294 \uac83\uc774\ub2e4. \uc791\ud488\uc758 \uac08\ub4f1\uc740 \ubcc0\ud654\uc5d0 \ub300\ud55c \ucc2c\uc131\uacfc \ubc18\ub300\ub9cc\uc774 \uc544\ub2c8\ub77c \uc7a5\uc18c\uc758 \uac00\uce58\ub97c \uacc4\uc0b0\ud558\ub294 \ubc29\uc2dd\uc758 \ucc28\uc774\uc5d0\uc11c \uc2dc\uc791\ub41c\ub2e4. \uc0c1\uc778 \ub85c\ud30c\ud78c\uc740 \ubc9a\ub098\ubb34\ub97c \ubca0\uace0 \ub545\uc744 \ubcc4\uc7a5 \ubd80\uc9c0\ub85c \ub098\ub204\uc5b4 \uc784\ub300\ud558\uc790\ub294 \ubc29\uc548\uc744 \uc81c\uc2dc\ud55c\ub2e4. \uacfc\uac70\uc758 \ubaa8\uc2b5\uc744 \uadf8\ub300\ub85c \uc720\uc9c0\ud558\ub294 \uae38\uc740 \uc544\ub2c8\uc9c0\ub9cc \uc218\uc785\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub294 \ud574\ubc95\uc774\ub2e4. \uadf8\ub294 \ubc18\ubcf5\ud574\uc11c \ub9d0\ud558\uc9c0\ub9cc \uc8fc\uc778\ub4e4\uc740 \uadf8 \uc81c\uc548\uc744 \ubc1b\uc544\ub4e4\uc774\uc9c0 \ubabb\ud55c\ub2e4. \uacbd\ub9e4\uc758 \uc2dc\uac04\uc740 \uadf8 \uc0ac\uc774\uc5d0\ub3c4 \ub2e4\uac00\uc628\ub2e4. \uc774\ub54c \ub85c\ud30c\ud78c\uc744 \uc544\ub984\ub2e4\uc6c0\uc744 \ubaa8\ub974\ub294 \uc545\ub2f9\uc73c\ub85c\ub9cc \ubcfc \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8\ub294 \uc2e4\uc81c \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub824 \ud55c\ub2e4. \ubc18\ub300\ub85c \uc8fc\uc778\ub4e4\uc774 \ub9dd\uc124\uc778\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \uae30\uc5b5\uacfc \uc7a5\uc18c\uc5d0 \ub300\ud55c \uc560\ucc29\uc774 \ubaa8\ub450 \uc5b4\ub9ac\uc11d\uc5b4\uc9c0\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \ubb34\uc5c7\uc744 \uc544\uae4c\uc6cc\ud558\ub294\uc9c0\uc758 \uac10\uc815\uc774 \uc2e4\ud589 \uac00\ub2a5\ud55c \ub300\ucc45\uc744 \ub300\uc2e0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub85c\ud30c\ud78c\uc758 \uc9d1\uc548\uc740 \ud55c\ub54c \uc774 \uc601\uc9c0\uc5d0\uc11c \ub18d\ub178\ub85c \uc0b4\uc558\ub2e4. \uadf8\uc5d0\uac8c \uc601\uc9c0\ub294 \ub0a8\uc758 \uace0\uc0c1\ud55c \ucd94\uc5b5\ub9cc \ub2f4\uc740 \uc7a5\uc18c\uac00 \uc544\ub2c8\ub2e4. \uac00\uc871\uc758 \ub0ae\uc740 \uc9c0\uc704\uc640 \uc544\ud514\uc774 \uc788\uc5c8\ub358 \uacf3\uc774\ub2e4. \uadf8 \ud6c4\uc190\uc778 \uc790\uc2e0\uc774 \uc774\uc81c \uc7ac\uc0b0\uc744 \uc0b4 \uc218 \uc788\uac8c \ub418\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uac15\ud55c \uac10\uc815\uc73c\ub85c \ub3cc\uc544\uc628\ub2e4. \uadf8\ub798\uc11c \uc18c\uc720\uad8c\uc758 \ubcc0\ud654\ub294 \ub2e8\uc21c\ud55c \ub9e4\ub9e4 \uc774\uc0c1\uc758 \uc758\ubbf8\ub97c \uac16\ub294\ub2e4. \uc61b \uc8fc\uc778\uc758 \uc0c1\uc2e4\uc774 \ub204\uad70\uac00\uc5d0\uac8c\ub294 \uc624\ub798\ub41c \uc9c8\uc11c\ub97c \ub118\uc5b4\uc11c\ub294 \uc131\ucde8\ub2e4. \uac19\uc740 \uc815\uc6d0\uc744 \ub450\uace0 \uc11c\ub85c \ub2e4\ub978 \uc5ed\uc0ac\uac00 \uc788\uc5c8\uc74c\uc744 \uc54c\uba74 \ub208\uc55e\uc758 \uac08\ub4f1\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc544\ub984\ub2e4\uc6b4 \uc7a5\uc18c\uc758 \uacfc\uac70\uac00 \ubaa8\ub450\uc5d0\uac8c \ub611\uac19\uc774 \uc544\ub984\ub2e4\uc6e0\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc791\ud488\uc740 \uacbd\ub9e4\uc758 \ubaa8\ub4e0 \uacfc\uc815\uc744 \uc9c1\uc811 \ubcf4\uc5ec \uc8fc\uae30\ubcf4\ub2e4 \ub204\uac00 \uc0c0\ub294\uc9c0 \ub3cc\uc544\uc640 \uc804\ud558\ub294 \uc7a5\uba74\uc5d0 \ubb34\uac8c\ub97c \ub454\ub2e4. \uc601\uc9c0\ub97c \uc0b0 \uc0ac\ub78c\uc740 \ub85c\ud30c\ud78c\uc774\ub2e4. \uadf8\ub294 \uc790\uc2e0\uc758 \uc131\uacf5\uc5d0 \ub4e4\ub728\uc9c0\ub9cc \uadf8 \uc55e\uc5d0\ub294 \uc61b \uc8fc\uc778\uc758 \uc2ac\ud514\ub3c4 \uc788\ub2e4. \ud55c \uc0ac\ub78c\uc758 \ud658\ud76c\uc640 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc0c1\uc2e4\uc774 \uac19\uc740 \ubc29 \uc548\uc5d0 \ub193\uc778\ub2e4. \ud070 \uc0ac\uac74\uc744 \ubb34\ub300 \ubc16\uc5d0 \ub450\ub294 \uad6c\uc131\ub3c4 \ud765\ubbf8\ub86d\ub2e4. \uad00\uac1d\uc740 \uac00\uaca9 \uacbd\uc7c1\ubcf4\ub2e4 \uadf8 \uacb0\uacfc\uac00 \uad00\uacc4\uc5d0 \ub4e4\uc5b4\uc624\ub294 \uc21c\uac04\uc744 \ubcf8\ub2e4. \ub204\uac00 \uc5b4\ub5a4 \ub9d0\uc744 \ud558\uace0 \uc5b4\ub5a4 \ubc18\uc751\uc744 \ubcf4\uc774\ub294\uc9c0\uac00 \uc911\uc694\ud574\uc9c4\ub2e4. \uc18c\uc720\uad8c\uc740 \uc11c\ub958\uc5d0\uc11c \ubc14\ub00c\uc9c0\ub9cc \uadf8 \ubcc0\ud654\ub294 \uc0ac\ub78c\ub4e4\uc758 \ubaa9\uc18c\ub9ac\uc640 \ubab8\uc5d0 \ub0a8\ub294\ub2e4. \uacbd\ub9e4 \uacb0\uacfc\ub97c \uae30\ub2e4\ub9ac\ub294 \ubb34\ub300\uc758 \uc2dc\uac04\ub3c4 \uc911\uc694\ud558\ub2e4. \uacb0\uc815\uc801\uc778 \uac70\ub798 \uc790\uccb4\ubcf4\ub2e4 \uadf8 \uacb0\uacfc\ub97c \ub4e4\uc5b4\uc57c \ud558\ub294 \uc0ac\ub78c\ub4e4\uc758 \ud45c\uc815\uacfc \ub9d0\uc774 \ub0a8\ub294\ub2e4. \ubd80\ub3d9\uc0b0\uc758 \uc18c\uc720\uc790\uac00 \ubc14\ub00c\ub294 \uc0ac\uac74\uc774 \uac01 \uc778\ubb3c\uc758 \ubbf8\ub798\ub97c \uc11c\ub85c \ub2e4\ub978 \uc18d\ub3c4\ub85c \ubc14\uafb8\ub294 \uacfc\uc815\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uad6c\uc131\uc774\ub2e4. \uc9d1\uc758 \ubb38\uc81c\ub9cc\ud07c\uc774\ub098 \uc778\ubb3c\ub4e4 \uc0ac\uc774\uc758 \uad00\uacc4\ub3c4 \uacb0\ub860\uc744 \uc5bb\uc9c0 \ubabb\ud55c\ub2e4. \ub85c\ud30c\ud78c\uacfc \ubc14\ub7b4\uc758 \uad00\uacc4\uc5d0\uc11c\ub3c4 \uc8fc\ubcc0\uc758 \uae30\ub300\uc640 \uc2e4\uc81c \ud589\ub3d9\uc774 \uc5b4\uae0b\ub09c\ub2e4. \uc801\uc808\ud55c \uc21c\uac04\uc774 \uc628 \uac83 \uac19\uc544\ub3c4 \ud544\uc694\ud55c \ub9d0\uc774 \ub098\uc624\uc9c0 \uc54a\ub294\ub2e4. \uc791\ud488 \uc804\uccb4\uc5d0 \uc774\ub7f0 \ubbf8\ub8e8\uae30\uc640 \ube57\ub098\uac10\uc774 \ubc18\ubcf5\ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub450\uac00 \uac10\uc815\uc774 \uc5c6\ub294 \uc0ac\ub78c\ub4e4\uc740 \uc544\ub2c8\ub2e4. \uc560\ucc29\uacfc \ud76c\ub9dd\uc740 \uc788\uc9c0\ub9cc \uadf8\uac83\uc744 \uc2e4\uc81c \uc120\ud0dd\uc73c\ub85c \uc62e\uae30\uc9c0 \ubabb\ud55c\ub2e4. \uccb4\ud638\ud504\ub294 \uac70\ucc3d\ud55c \uc120\uc5b8\ubcf4\ub2e4 \uc774\ub7f0 \uc791\uc740 \uc5b4\uc0c9\ud568\uc744 \ud1b5\ud574 \uc778\ubb3c\uc744 \ub4dc\ub7ec\ub0b8\ub2e4. \uad00\uac1d\uc740 \uc6c3\uc744 \uc218\ub3c4 \uc788\uc9c0\ub9cc, \uc790\uae30 \uc0b6\uc758 \ubbf8\ub904 \ub454 \ub9d0\uacfc \uc77c\uc744 \ub5a0\uc62c\ub9ac\uba70 \ubd88\ud3b8\ud574\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc9d1\uc744 \ub5a0\ub098\uace0 \ubb38\uc774 \ub2eb\ud78c\ub2e4. \uc624\ub798\ub41c \ud558\uc778 \ud53c\ub974\uc2a4\ub294 \uadf8 \uc548\uc5d0 \ub0a8\uaca8\uc9c4\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc774 \uadf8\ub97c \ucc59\uacbc\uc744 \uac83\uc774\ub77c\ub294 \uc0dd\uac01 \uc18d\uc5d0 \ud55c \uc0ac\ub78c\uc774 \ube60\uc9c4 \uac83\uc774\ub2e4. \uadf8\ub294 \ub204\uc6b4 \ucc44 \uc6c0\uc9c1\uc774\uc9c0 \uc54a\uace0, \uba40\ub9ac \ub098\ubb34\ub97c \ucc0d\ub294 \uc18c\ub9ac\uc640 \uae30\ubb18\ud55c \uc18c\ub9ac\uac00 \ub4e4\ub9b0\ub2e4. \uc774 \ub9c8\uc9c0\ub9c9\uc744 \ud53c\ub974\uc2a4\uc758 \uc8fd\uc74c\uc774 \ud655\uc815\ub41c \ubcf4\uace0\ucc98\ub7fc\ub9cc \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \ubb34\ub300\uac00 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \ub0a8\uaca8\uc9c4 \ubab8\uacfc \uc18c\ub9ac\ub2e4. \uc55e\uc744 \ud5a5\ud574 \ub5a0\ub098\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc774\uc57c\uae30 \ub4a4\uc5d0 \ub204\uac00 \uc78a\ud614\ub294\uc9c0 \ubcf4\uac8c \ud55c\ub2e4. \ubcc0\ud654\ub97c \ub9de\ub294 \ud76c\ub9dd\uacfc \ub5a0\ub09c \ub4a4 \ub0a8\ub294 \ucc45\uc784\uc774 \uc11c\ub85c \ub2e4\ub978 \ubc29\ud5a5\uc73c\ub85c \uc5f4\ub9b0\ub2e4. \uccb4\ud638\ud504\ub294 \uc774 \uc791\ud488\uc744 \ud76c\uadf9\uc73c\ub85c \ubd88\ub800\ub2e4. \uc544\ub984\ub2e4\uc6b4 \uc815\uc6d0\uc744 \uc783\ub294 \uc774\uc57c\uae30\uc778\ub370 \uc65c \uc6c3\uc74c\uc774 \ub4e4\uc5b4\uac00\ub294\uc9c0 \uc0dd\uac01\ud574 \ubcfc \ub9cc\ud558\ub2e4. \uc778\ubb3c\uc758 \ud5c8\uc138\uc640 \uc2e4\uc218, \uc5b4\uae0b\ub09c \ub300\ud654\ub294 \uc2e4\uc81c\ub85c \uc6b0\uc2b5\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uc6c3\uc74c\uc774 \uc0c1\uc2e4\uc758 \ubb34\uac8c\ub97c \uc5c6\uc560\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub450 \uac10\uac01\uc774 \ud568\uaed8 \uc6c0\uc9c1\uc778\ub2e4. \u300e\ubc9a\uaf43 \ub3d9\uc0b0\u300f\uc740 \uc61b\uac83\uc744 \uc9c0\ud0a4\uac70\ub098 \uc0c8\uac83\uc744 \uc120\ud0dd\ud558\uba74 \ubaa8\ub4e0 \ubb38\uc81c\uac00 \ud574\uacb0\ub41c\ub2e4\ub294 \ub2f5\uc744 \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \ubcc0\ud654\ub294 \uc77c\uc5b4\ub098\uc9c0\ub9cc \uadf8 \uc548\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc740 \uc11c\ub85c \ub2e4\ub978 \uac83\uc744 \uc5bb\uace0 \uc783\ub294\ub2e4. \uc815\uc6d0\uc758 \uc544\ub984\ub2e4\uc6c0\uacfc \uc18c\uc720\uc758 \uc5ed\uc0ac, \ub5a0\ub098\ub294 \uc0ac\ub78c\uacfc \ub0a8\uc740 \uc0ac\ub78c\uc744 \ud568\uaed8 \ubcfc \ub54c \uc774 \ud76c\uace1\uc740 \ub354 \uc624\ub798 \ub9c8\uc74c\uc5d0 \ub0a8\ub294\ub2e4."}, {"id": "chicago-floating-stair-detail", "title": "\uacc4\ub2e8 \uc544\ub798\uc758 \uc791\uc740 \ud2c8\uc774 \uac74\ubb3c\uc744 \uac00\ubccd\uac8c \ub9cc\ub4e0\ub2e4", "summary": "\ubcbd\uacfc \uacc4\ub2e8, \uc758\uc790 \uc544\ub798\uc758 \uac00\ub290\ub2e4\ub780 \ud2c8\uc5d0 \uc8fc\ubaa9\ud569\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uac74\ucd95", "categories": ["arts"], "url": "stories/chicago-floating-stair-detail/index.html", "image": "../media/chicago-floating-stair-detail.jpg", "alt": "\uacc4\ub2e8 \uc544\ub798\uc758 \uc791\uc740 \ud2c8\uc774 \uac74\ubb3c\uc744 \uac00\ubccd\uac8c \ub9cc\ub4e0\ub2e4\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\uacc4\ub2e8 \uc544\ub798\uc758 \uc791\uc740 \ud2c8\uc774 \uac74\ubb3c\uc744 \uac00\ubccd\uac8c \ub9cc\ub4e0\ub2e4 \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc5d0\uc11c \ubc14\ub2e5\uc744 \ud55c \ubc88 \ub354 \ubcf4\ub294 \ubc29\ubc95 \ubcbd\uacfc \uacc4\ub2e8, \uc758\uc790 \uc544\ub798\uc758 \uac00\ub290\ub2e4\ub780 \ud2c8\uc5d0 \uc8fc\ubaa9\ud569\ub2c8\ub2e4. \uac74\ucd95 \ubb38\ud654\uc640 \uc608\uc220 \ud070 \uac74\ubb3c\uc744 \ubcf4\uace0 \uac00\ubccd\ub2e4\ub294 \ub290\ub08c\uc744 \ubc1b\uc744 \ub54c\uac00 \uc788\ub2e4. \uc2e4\uc81c \ubb34\uac8c\uac00 \uac00\ubcbc\uc6b8 \ub9ac\ub294 \uc5c6\ub294\ub370 \ubcbd\uc774\ub098 \uacc4\ub2e8\uc774 \uc0b4\uc9dd \ub5a0 \uc788\ub294 \uac83\ucc98\ub7fc \ubcf4\uc774\ub294 \uc21c\uac04\uc774\ub2e4. \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc758 \ubaa8\ub358 \uc719 \uc124\uba85\uc5d0\ub294 \uadf8 \ub290\ub08c\uc744 \ub9cc\ub4dc\ub294 \uc791\uc740 \ud2c8\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \uc124\uacc4\uc790\ub294 \uc774\ud0c8\ub9ac\uc544 \uac74\ucd95\uac00 \ub80c\ucd08 \ud53c\uc544\ub178\ub2e4. \ubbf8\uc220\uad00\uc774 \uc18c\uac1c\ud558\ub294 \uadf8\uc758 \uc0dd\uac01 \uac00\uc6b4\ub370 \ud558\ub098\ub294 \uac74\ubb3c\uc774 \ub5a0\uc624\ub974\ub4ef \ubcf4\uc774\uac8c \ud558\ub294 \uc81c\ub85c \uadf8\ub798\ube44\ud2f0\ub77c\ub294 \ud45c\ud604\uc774\ub2e4. \ub9d0\uc740 \uac70\ucc3d\ud558\uc9c0\ub9cc \ub208\uc5ec\uaca8\ubcfc \uacf3\uc740 \uc758\uc678\ub85c \ubc1c\ubc11\uc774\ub2e4. \uae30\uad00\uc758 \uae00\uc740 \ubcbd \uc544\ub7ab\ubd80\ubd84\uc5d0 \uc57d 1\uc778\uce58\uc758 \ub4dc\ub7ec\ub09c \ud2c8\uc774 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc57d 2.5\uc13c\ud2f0\ubbf8\ud130\ub2e4. \ubcbd \uc804\uccb4\uc5d0 \ube44\ud558\uba74 \uc791\uc740 \ub192\uc774\uc9c0\ub9cc \ubc14\ub2e5\uacfc \ubcbd \uc0ac\uc774\uc5d0 \uac00\ub290\ub2e4\ub780 \uc120\uc744 \ub9cc\ub4e0\ub2e4. \ubcbd\uc740 \ub2f9\uc5f0\ud788 \ubc14\ub2e5\uc5d0 \ub2ff\uc544 \uc788\uc744 \uac83\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \uadf8 \ub9cc\ub098\ub294 \uc790\ub9ac\ub97c \uc870\uae08 \ub2e4\ub974\uac8c \ucc98\ub9ac\ud558\uba74 \ub369\uc5b4\ub9ac\uc758 \ub290\ub08c\ub3c4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ucc9c\uc7a5\ub9cc \uc62c\ub824\ub2e4\ubcf4\ub358 \uc2dc\uc120\uc744 \uc544\ub798\ub85c \ub0b4\ub9ac\ub294 \uc774\uc720\uac00 \uc0dd\uae34\ub2e4. \uae00\uc5d0 \ub530\ub974\uba74 \ud53c\uc544\ub178\uac00 \ub514\uc790\uc778\ud55c \ubca4\uce58\ub3c4 \uc791\uc740 \ubc1b\uce68 \uc704\uc5d0 \ub193\uc5ec \ubc14\ub2e5\uc5d0\uc11c \uc870\uae08 \uc62c\ub77c\uac00 \uc788\ub2e4. \uc870\uac01\uc758 \ubc1b\uce68\ub300\uc640 \ub2e8 \uc5ed\uc2dc \ubc14\ub2e5\uc5d0\uc11c \ub5a8\uc5b4\uc838 \ubcf4\uc774\ub3c4\ub85d \ud588\uc73c\uba70, \ud070 \uacc4\ub2e8 \uc544\ub798\uc5d0\ub3c4 \ud2c8\uc774 \uc788\ub2e4. \ubcbd \ud558\ub098\uc5d0\ub9cc \ub123\uc740 \uc6b0\uc5f0\ud55c \uc7a5\uc2dd\uc774 \uc544\ub2c8\ub77c \uc5ec\ub7ec \ubd80\ubd84\uc5d0\uc11c \uc774\uc5b4\uc9c0\ub294 \uc120\ud0dd\uc774\uc5c8\ub2e4. \ub2e4\ub978 \ubaa8\uc591\uc758 \uac00\uad6c\uc640 \uad6c\uc870\ubb3c\uc774 \ube44\uc2b7\ud55c \ubc29\uc2dd\uc73c\ub85c \ubc14\ub2e5\uc744 \ub9cc\ub098\uba74 \uacf5\uac04 \uc804\uccb4\uc5d0\ub3c4 \uacf5\ud1b5\ub41c \uc778\uc0c1\uc774 \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4. \ubcbd\uacfc \uacc4\ub2e8\uc740 \uc2e4\uc81c\ub85c \uc9c0\uc9c0\ub418\uc5b4\uc57c \ud55c\ub2e4. \uc81c\ub85c \uadf8\ub798\ube44\ud2f0\ub77c\ub294 \ub9d0\uc774 \uadf8 \uc870\uac74\uc744 \uc5c6\uc560\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubbf8\uc220\uad00\uc758 \uc124\uba85\uc740 \ubcf4\uc774\ub294 \uc811\uc810\uc744 \uc870\uc815\ud574 \ub369\uc5b4\ub9ac\uc758 \uc778\uc0c1\uc744 \ubc14\uafb8\ub294 \uc124\uacc4\ub97c \uc774\uc57c\uae30\ud55c\ub2e4. \uad6c\uc870\uc801\uc73c\ub85c \uc5b4\ub5bb\uac8c \uc11c \uc788\ub294\uac00\uc640 \uc0ac\ub78c\uc758 \ub208\uc5d0 \uc5b4\ub5bb\uac8c \ubcf4\uc774\ub294\uac00\ub294 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc9c0\ub9cc \uac19\uc740 \uc9c8\ubb38\ub9cc\uc740 \uc544\ub2c8\ub2e4. \ubcbd \uc544\ub798\uc758 \ud2c8\uc740 \uadf8 \ucc28\uc774\ub97c \ub290\ub07c\uac8c \ud558\ub294 \uc791\uc740 \uc790\ub9ac\ub2e4. \ubc14\ub2e5\uc5d0\uc11c \ubcbd\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uacbd\uacc4\uc5d0 \uadf8\ub9bc\uc790\uac00 \uc0dd\uae30\uba74 \uc804\uccb4 \uba74\uc774 \uc870\uae08 \ub5a8\uc5b4\uc838 \uc788\ub294 \ub4ef \ubcf4\uc77c \uc218 \uc788\ub2e4. \uac70\ub300\ud55c \uc7a5\uc2dd\uc744 \uc0c8\ub85c \ub354\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc775\uc219\ud55c \uc811\uc810 \ud558\ub098\ub97c \ub2e4\ub974\uac8c \ucc98\ub9ac\ud574 \uacf5\uac04\uc758 \ud45c\uc815\uc744 \ubc14\uafb8\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc815\ud655\ud55c \uad6c\uc870 \ub3c4\uba74 \uc5c6\uc774\ub3c4 \uad00\ub78c\uc790\uac00 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub294 \ub2e8\uc11c\uac00 \ub41c\ub2e4. \uc57d 2.5\uc13c\ud2f0\ubbf8\ud130\ub77c\ub294 \ub192\uc774\ub294 \uac74\ubb3c\uc758 \uc804\uccb4 \ud06c\uae30\uc5d0 \ube44\ud558\uba74 \uc544\uc8fc \uc791\ub2e4. \uadf8\ub7f0\ub370 \uc0ac\ub78c\uc740 \uc2e4\ub0b4\uc5d0\uc11c \ubcbd\uacfc \uac00\uad6c\ub97c \uac00\uae4c\uc774 \ub9cc\ub098\uae30 \ub54c\ubb38\uc5d0 \uc774\ub7f0 \uacbd\uacc4\ub97c \ub208\uce58\ucc4c \uc218 \uc788\ub2e4. \uba3c \uacf3\uc5d0\uc11c \uac74\ubb3c\uc758 \uc724\uacfd\uc744 \ubcf4\ub294 \uacbd\ud5d8\uacfc \ubcf5\ub3c4\uc5d0\uc11c \ubc1c\ubc11\uc758 \uc120\uc744 \ubcf4\ub294 \uacbd\ud5d8\uc740 \ub2e4\ub978 \ud06c\uae30\uc758 \uc815\ubcf4\ub97c \uc900\ub2e4. \ud06c\uae30 \ud558\ub098\ub9cc \uc678\uc6b0\uae30\ubcf4\ub2e4 \uadf8 \ud2c8\uc774 \uc5bc\ub9c8\ub098 \uae38\uac8c \uc774\uc5b4\uc9c0\ub294\uc9c0 \uc0dd\uac01\ud574 \ubcf4\uc790. \uc791\uc740 \ub192\uc774\ub3c4 \uc120\uc73c\ub85c \ubc18\ubcf5\ub418\uba74 \ud55c \uc810\uc758 \uc7a5\uc2dd\uacfc \ub2e4\ub978 \uc778\uc0c1\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \ubcf8\ubb38\uc758 \uac1c\ub150 \uc0bd\ud654\ub294 \uc774\ub7f0 \uc2dc\uc120\uc744 \ub3d5\ub294 \uac83\uc774\ubbc0\ub85c \uc2e4\uc81c \ud604\uc7a5\uc758 \ubaa8\ub4e0 \uae38\uc774\uc640 \ubc1b\uce68 \uc704\uce58\ub97c \ud655\uc778\ud558\ub294 \uc790\ub8cc\ub85c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc218\uce58\uc640 \uacf5\uac04\uc758 \uc2e4\uc81c \ubaa8\uc2b5\uc740 \uae30\uad00 \uc124\uba85 \ubc0f \ud604\uc7a5 \uc790\ub8cc\uc640 \ud568\uaed8 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \ubca4\uce58\uc640 \uc870\uac01 \ubc1b\uce68, \uacc4\ub2e8\uc740 \uc11c\ub85c \ub2e4\ub978 \uc77c\uc744 \ud558\ub294 \ubb3c\uac74\uc774\ub2e4. \uadf8\ub7f0\ub370 \ubc14\ub2e5\uacfc \ub9cc\ub098\ub294 \ubc29\uc2dd\uc744 \ube44\uc2b7\ud558\uac8c \ub2e4\ub8e8\uba74 \uacf5\uac04 \uc548\uc5d0\uc11c \uacf5\ud1b5\ub41c \ub9ac\ub4ec\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \ud558\ub098\ud558\ub098\ub97c \ub530\ub85c \ub514\uc790\uc778\ud558\uba74\uc11c\ub3c4 \uc804\uccb4 \uc778\uc0c1\uc774 \uc774\uc5b4\uc9c0\ub3c4\ub85d \ud55c \uc120\ud0dd\uc73c\ub85c \uc77d\ud78c\ub2e4. \uac74\ucd95\uac00\uc758 \uc0dd\uac01\uc774 \uac74\ubb3c \uc678\uad00\uc5d0\uc11c\ub9cc \ub4dc\ub7ec\ub098\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac00\uad6c\uc758 \ubc1b\uce68\uc744 \ubcf4\ub294 \uc77c\ub3c4 \uadf8\ub798\uc11c \uac10\uc0c1\uc758 \uc77c\ubd80\uac00 \ub41c\ub2e4. \uc549\ub294 \uba74\uc774\ub098 \uc804\uc2dc\ud558\ub294 \uc870\uac01\ubd80\ud130 \ubcf4\uae30 \uc27d\uc9c0\ub9cc \uadf8 \uc544\ub798\uc758 \uc791\uc740 \ubd80\ubd84\uc774 \ub369\uc5b4\ub9ac\uc758 \ubb34\uac8c\ub97c \ub2e4\ub974\uac8c \ub290\ub07c\uac8c \ud560 \uc218 \uc788\ub2e4. \uacf5\uac04\uc758 \ud1b5\uc77c\uac10\uc774 \ubaa8\ub450 \uac19\uc740 \ubaa8\uc591\uc744 \ubc18\ubcf5\ud558\ub294 \ub370\uc11c\ub9cc \uc0dd\uae30\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ub2e4\ub978 \uc0ac\ubb3c\ub4e4\uc774 \uac19\uc740 \uc811\uc810\uc758 \uaddc\uce59\uc744 \uacf5\uc720\ud560 \uc218\ub3c4 \uc788\ub2e4. \ub192\uc740 \ucc9c\uc7a5\uacfc \ud070 \uc720\ub9ac\ucc3d\uc744 \uc62c\ub824\ub2e4\ubcf8 \ub2e4\uc74c \ubc14\ub2e5 \uac00\uae4c\uc774\ub85c \ub208\uc744 \uc62e\uaca8 \ubcf4\uc790. \ubcbd\uacfc \ubc14\ub2e5\uc774 \ub9cc\ub098\ub294 \uc120, \uc758\uc790 \ub2e4\ub9ac\uc640 \ubc1b\uce68\uc758 \uac04\uaca9, \uacc4\ub2e8 \uc544\ub798\uc758 \uadf8\ub9bc\uc790\uac00 \uc0c8\ub85c\uc6b4 \uad00\ucc30 \ub300\uc0c1\uc774 \ub41c\ub2e4. \uc804\ubb38 \uc6a9\uc5b4\ub97c \ub9ce\uc774 \uae30\uc5b5\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub208\uc758 \ub192\uc774\ub97c \ubc14\uafb8\ub294 \uac83\ub9cc\uc73c\ub85c \uc815\ubcf4\uac00 \ub298\uc5b4\ub09c\ub2e4. \ub2e4\ub9cc \uac00\ubccd\uac8c \ubcf4\uc778\ub2e4\ub294 \uac10\uc0c1\uc774 \ub204\uad6c\uc5d0\uac8c\ub098 \uac19\uc740 \uc815\ub3c4\ub85c \uc0dd\uae30\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uae30\uad00\uc758 \uc124\uacc4 \uc124\uba85\uc740 \uc758\ub3c4\ub97c \uc54c\ub824 \uc8fc\uace0 \uad00\ub78c\uc790\ub294 \uc790\uae30 \uacbd\ud5d8\uc744 \ud1b5\ud574 \ud655\uc778\ud55c\ub2e4. \uc758\ub3c4\ub97c \ub4e4\uc5c8\ub2e4\uace0 \ubc18\ub4dc\uc2dc \uac19\uc740 \ub290\ub08c\uc744 \ub0b4\uc57c \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc124\uba85\uc774 \ud48d\uacbd\uc744 \ub300\uc2e0\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ud3c9\uc18c\uc5d0 \uc9c0\ub098\ucce4\ub358 \ubd80\ubd84\uc744 \ub2e4\uc2dc \ubcf4\uac8c \ud560 \ub54c \uac74\ucd95 \uc774\uc57c\uae30\ub294 \ub354 \uc7ac\ubbf8\uc788\uc5b4\uc9c4\ub2e4. \ubb3c\ub860 \uac74\ubb3c\uc774 \uc2e4\uc81c\ub85c \uacf5\uc911\uc5d0 \ub9e4\ub2ec\ub838\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uae30\uad00 \uae00\uc740 \ub208\uc5d0 \ubcf4\uc774\ub294 \uc811\uc810\uacfc \ud2c8\uc774 \uac00\ubcbc\uc6b4 \uc778\uc0c1\uc744 \uc8fc\ub294 \ubc29\uc2dd\uc744 \uc124\uba85\ud55c\ub2e4. \uad6c\uc870\ub97c \uc9c0\ud0f1\ud558\ub294 \uc6d0\ub9ac\ub97c \uc804\ubd80 \uc54c\uc544\uc57c\ub9cc \uc990\uae38 \uc218 \uc788\ub294 \ub300\ubaa9\uc740 \uc544\ub2c8\ub2e4. \ub2e4\uc74c\uc5d0 \uc0c8\ub85c\uc6b4 \uac74\ubb3c\uc5d0 \ub4e4\uc5b4\uac00\uba74 \ucc3d\ubb38\uc774\ub098 \uba4b\uc9c4 \ucc9c\uc7a5\uc744 \ubcf8 \ub4a4 \uc758\uc790 \ubc11\ub3c4 \ud55c \ubc88 \ubcf4\uc790. \ubc14\ub2e5\uacfc \ub9cc\ub098\ub294 \uc120\uc744 \uc5b4\ub5bb\uac8c \ub2e4\ub918\ub294\uc9c0 \uc0b4\ud53c\ub294 \uac83\uc774\ub2e4. \uac74\ucd95\uac00\uc758 \uc0dd\uac01\uc774 \uac00\uc7a5 \uc791\uc740 \uadf8\ub9bc\uc790\ucc98\ub7fc \ub0a8\uc544 \uc788\ub294 \uc790\ub9ac\uc77c \uc218 \uc788\ub2e4."}, {"id": "chopin-life-piano-and-home", "title": "\uc1fc\ud33d\uc758 \uc0dd\uc560 \u2014 \ub5a0\ub098\uc628 \ub098\ub77c\uac00 \ud53c\uc544\ub178\uc5d0 \ub0a8\uc744 \ub54c", "summary": "\ubc30\uc6c0\uacfc \uc774\uc8fc, \uac00\ub974\uce58\ub294 \uc0dd\ud65c\uacfc \uc791\uace1\uc758 \uc2dc\uac04\uc744 \ud1b5\ud574 \uc1fc\ud33d\uc744 \ub9cc\ub0a9\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc74c\uc545", "categories": ["arts"], "url": "stories/chopin-life-piano-and-home/index.html", "image": "../media/chopin-life-piano-and-home.png", "alt": "\ud1a0\uba38\uc2a4 \ud0dc\ud37c\uc758 \uc61b \uc1fc\ud33d \uc548\ub0b4\uc11c\uc5d0 \uc218\ub85d\ub41c \uc1fc\ud33d\uc758 \ucd08\uc0c1 \uc7ac\ud604 \ub3c4\ud310.", "text": "\uc1fc\ud33d\uc758 \uc0dd\uc560 \u2014 \ub5a0\ub098\uc628 \ub098\ub77c\uac00 \ud53c\uc544\ub178\uc5d0 \ub0a8\uc744 \ub54c \ubc14\ub974\uc0e4\ubc14\uc5d0\uc11c \ud30c\ub9ac\ub85c, \ucda4\uc758 \ub9ac\ub4ec\uacfc \ub178\ub798\ud558\ub294 \uac74\ubc18\uc744 \ub530\ub77c \ubc30\uc6c0\uacfc \uc774\uc8fc, \uac00\ub974\uce58\ub294 \uc0dd\ud65c\uacfc \uc791\uace1\uc758 \uc2dc\uac04\uc744 \ud1b5\ud574 \uc1fc\ud33d\uc744 \ub9cc\ub0a9\ub2c8\ub2e4. \uc74c\uc545 \ubb38\ud654\uc640 \uc608\uc220 \uc1fc\ud33d\uc758 \uc74c\uc545\uc744 \ub4e4\uc73c\uba74 \ud53c\uc544\ub178\uac00 \ub178\ub798\ud558\ub294 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c8 \ub54c\uac00 \uc788\ub2e4. \uba5c\ub85c\ub514\uac00 \ud55c\uc228\ucc98\ub7fc \uae38\uc5b4\uc84c\ub2e4\uac00 \uc7a5\uc2dd\uc74c\uc774 \uac00\ubccd\uac8c \ud769\uc5b4\uc9c0\uace0, \ub2e4\ub978 \uace1\uc5d0\uc11c\ub294 \ucda4\uc758 \uac78\uc74c\uc774 \ub610\ub837\ud558\uac8c \uc0b4\uc544\ub09c\ub2e4. \uc774\ub7f0 \ud45c\uc815\ub4e4\uc744 \uc5f0\uc57d\ud568\uc774\ub098 \uc2ac\ud514 \ud55c \uac00\uc9c0\ub85c\ub9cc \ubb36\uae30\ub294 \uc5b4\ub835\ub2e4. \ud504\ub808\ub370\ub9ac\ud06c \uc1fc\ud33d\uc740 1810\ub144\uc5d0 \ud0dc\uc5b4\ub098 1849\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub09c \ud3f4\ub780\ub4dc \uc791\uace1\uac00\uc774\uc790 \ud53c\uc544\ub2c8\uc2a4\ud2b8\ub2e4. \uc9e7\uc740 \uc0dd\uc560\ub97c \ucc9c\uc7ac\uc758 \ube44\uadf9\uc73c\ub85c\ub9cc \ub530\ub77c\uac00\uae30\ubcf4\ub2e4, \ubc30\uc6c0\uacfc \uc774\uc8fc, \uad50\uc2b5\uacfc \uc791\uace1\uc774 \uc5b4\ub5bb\uac8c \ud55c \uc545\uae30\uc758 \uc138\uacc4\ub97c \ub113\ud614\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc1fc\ud33d\uc740 \ubc14\ub974\uc0e4\ubc14 \uadfc\ucc98\uc5d0\uc11c \ud0dc\uc5b4\ub098 \uc5b4\ub9b0 \uc2dc\uc808\ubd80\ud130 \uc74c\uc545\uc744 \ubc30\uc6b0\uace0 \uc5f0\uc8fc\ud588\ub2e4. \ubc14\ub974\uc0e4\ubc14\uc5d0\uc11c \uc131\uc7a5\ud558\uba70 \uc5d8\uc2a4\ub124\ub974 \uac19\uc740 \uc2a4\uc2b9\uc5d0\uac8c \ubc30\uc6e0\uace0, \ub610\ub798\uc640 \uac00\uc871\uc758 \uc0dd\ud65c \uc18d\uc5d0\uc11c \uc74c\uc545\uc744 \uc775\ud614\ub2e4. \uc774\ubbf8 \uc644\uc131\ub41c \ud53c\uc544\ub178\uc758 \uc2dc\uc778\uc774 \uc5b4\ub290 \ub0a0 \ub4f1\uc7a5\ud588\ub2e4\uae30\ubcf4\ub2e4 \ubc30\uc6c0\uacfc \uae30\ud68c\uac00 \uc313\uc778 \uc2dc\uac04\uc774\uc5c8\ub2e4. \uc774 \uc2dc\uae30\uc5d0 \ub9cc\ub09c \ud3f4\ub780\ub4dc\uc758 \ucda4\uacfc \ub178\ub798\ub294 \uc774\ud6c4 \uc791\ud488\uc744 \uc774\ud574\ud558\ub294 \ubc30\uacbd\uc774 \ub41c\ub2e4. \ub2e4\ub9cc \uadf8\uac00 \ub4e4\uc740 \ubaa8\ub4e0 \ubbfc\uc18d \uc120\uc728\uc744 \uadf8\ub300\ub85c \uc545\ubcf4\uc5d0 \uc62e\uacbc\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc775\uc219\ud55c \ub9ac\ub4ec\uacfc \ubab8\uc758 \uac10\uac01\uc744 \uc790\uae30 \uc791\ud488\uc758 \uc5b8\uc5b4\ub85c \ubc14\uafb8\uc5b4 \uac14\ub2e4\uace0 \ubcf4\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc1fc\ud33d\uc740 1830\ub144 \ubc14\ub974\uc0e4\ubc14\ub97c \ub5a0\ub0ac\uace0, 1831\ub144\uc5d0\ub294 \ud30c\ub9ac\uc5d0\uc11c \uc0dd\ud65c\ud558\uac8c \ub41c\ub2e4. \uadf8 \uc0ac\uc774 \ud3f4\ub780\ub4dc\uc758 \uc815\uce58\uc801 \uaca9\ubcc0\uc774 \uc774\uc5b4\uc84c\ub2e4. \uac00\uc871\uacfc \uc775\uc219\ud55c \ub3c4\uc2dc\ub97c \uc7a0\uc2dc \ub5a0\ub098\ub294 \uac83\uacfc, \uc27d\uac8c \ub3cc\uc544\uac08 \uc218 \uc5c6\ub294 \uc0dd\ud65c\uc744 \uc2dc\uc791\ud558\ub294 \uac83\uc740 \uac19\uc740 \uacbd\ud5d8\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc791\ud488\uc744 \ubaa8\ub450 \uace0\ud5a5\uc744 \uadf8\ub9ac\uc6cc\ud55c \uc554\ud638\ub85c \ud574\ub3c5\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8\ub7ec\ub098 \ucda4\uc758 \ub9ac\ub4ec\uacfc \ud3f4\ub780\ub4dc\uc758 \uc774\ub984\uc774 \uadf8\uc758 \uc74c\uc545\uc5d0\uc11c \uacc4\uc18d \uc911\uc694\ud558\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc0dd\uc560\uc640 \ud568\uaed8 \ubcfc \uc218\ub294 \uc788\ub2e4. \uc774\uc8fc\ud55c \uc0ac\ub78c\uc5d0\uac8c \uace0\ud5a5\uc740 \ud48d\uacbd\uc758 \uae30\uc5b5\ubfd0 \uc544\ub2c8\ub77c \ubab8\uc5d0 \uc775\uc740 \uac78\uc74c\uacfc \ub9d0\ud22c\ub85c \ub0a8\uae30\ub3c4 \ud55c\ub2e4. \ud30c\ub9ac\ub294 \uc5ec\ub7ec \uc74c\uc545\uac00\uc640 \uc791\uac00, \ud6c4\uc6d0\uc790\uac00 \ub9cc\ub098\ub294 \ub3c4\uc2dc\uc600\ub2e4. \uc1fc\ud33d\uc740 \uadf8\uacf3\uc5d0\uc11c \uc5f0\uc8fc\ud558\uace0 \uc791\ud488\uc744 \ub0b4\uba70 \ud559\uc0dd\ub4e4\uc744 \uac00\ub974\ucce4\ub2e4. \ub300\uaddc\ubaa8 \ubb34\ub300\uc758 \uc5f4\uad11\ub9cc\uc73c\ub85c \uc0dd\ud65c\ud55c \uc608\uc220\uac00\ub77c\uace0 \ubcf4\uba74 \uad50\uc2b5\uacfc \uc0b4\ub871, \uc77c\uc0c1\uc801\uc778 \uad00\uacc4\uac00 \ucc28\uc9c0\ud55c \uc790\ub9ac\ub97c \ub193\uce5c\ub2e4. \ub204\uad70\uac00\uc758 \uc190\uac00\ub77d\uacfc \uc18c\ub9ac\ub97c \uac00\uae4c\uc774 \uc0b4\ud53c\ub294 \uad50\uc2b5\uc740 \uc791\uace1\uac00\uc758 \uc0dd\ud65c\uacfc\ub3c4 \uc5f0\uacb0\ub41c\ub2e4. \uadf8\uc758 \uc74c\uc545\uc5d0\ub294 \ud53c\uc544\ub178\uac00 \uc5b4\ub5a4 \uc6b8\ub9bc\uc744 \ub0bc \uc218 \uc788\uace0 \uc190\uc774 \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc77c \uc218 \uc788\ub294\uc9c0\uc5d0 \ub300\ud55c \uc138\ubc00\ud55c \uad00\uc2ec\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uba5c\ub85c\ub514\uc758 \uc544\ub984\ub2e4\uc6c0\uacfc \uc545\uae30\uc758 \uad6c\uccb4\uc801\uc778 \uc870\uac74\uc744 \ub530\ub85c \ub5bc\uae30 \uc5b4\ub835\ub2e4. \uc57c\uc0c1\uace1\uc774\ub77c\ub294 \uc774\ub984\uc740 \ubc24\uc758 \ubd84\uc704\uae30\ub97c \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uc1fc\ud33d\uc774 \uc774 \uc7a5\ub974\ub97c \ud63c\uc790 \ucc98\uc74c \ubc1c\uba85\ud588\ub2e4\uace0 \ub9d0\ud558\ub294 \uac83\uc740 \uc815\ud655\ud558\uc9c0 \uc54a\ub2e4. \ud734\ub108\ucee4\uc758 \uc804\uae30\ub3c4 \uc874 \ud544\ub4dc\uc640\uc758 \uad00\uacc4\ub97c \uc9da\ub294\ub2e4. \uc1fc\ud33d\uc740 \uc774\ubbf8 \uc874\uc7ac\ud558\ub358 \uc7a5\ub974 \uc548\uc5d0\uc11c \uc790\uae30\ub9cc\uc758 \ub178\ub798\uc640 \uae34\uc7a5, \uc7a5\uc2dd\uc744 \ubc1c\uc804\uc2dc\ucf30\ub2e4. \ub4e4\uc5b4 \ubcfc \ub54c\ub294 \uc704\ucabd\uc758 \ub178\ub798\uc640 \uc544\ub798\ucabd\uc758 \ubc18\uc8fc\ub97c \ub530\ub85c \ub530\ub77c\uac00 \ubcf4\uc790. \ubc18\uc8fc\uac00 \ubc14\ud0d5\uc744 \ub9cc\ub4e4\uace0 \uc120\uc728\uc740 \uadf8 \uc704\uc5d0\uc11c \uc870\uae08 \ub354 \uc720\uc5f0\ud558\uac8c \uc6c0\uc9c1\uc774\ub294 \ub4ef \ub4e4\ub9b4 \uc218 \uc788\ub2e4. \uc2ac\ud504\ub2e4\ub294 \ub2e8\uc5b4 \ud558\ub098\ub85c \uc815\ub9ac\ud558\uae30\ubcf4\ub2e4 \ub178\ub798\uac00 \uc5b4\ub514\uc5d0\uc11c \uc26c\uace0 \uc5b4\ub514\uc5d0\uc11c \uae38\uc5b4\uc9c0\ub294\uc9c0 \ub290\ub07c\uba74 \uc74c\uc545\uc758 \ud45c\uc815\uc774 \uc138\ubd84\ub41c\ub2e4. \ub9c8\uc8fc\ub974\uce74\uc640 \ud3f4\ub85c\ub124\uc988\ub294 \ud3f4\ub780\ub4dc\uc758 \ucda4\uacfc \uc5f0\uacb0\ub41c \uc774\ub984\uc774\ub2e4. \uc1fc\ud33d\uc758 \uc791\ud488\uc5d0\uc11c\ub294 \uc2e4\uc81c \ucda4\uc758 \uc790\ub9ac\ub97c \ub118\uc5b4 \ud53c\uc544\ub178\ub85c \ub4e3\ub294 \uc74c\uc545\uc758 \uc138\uacc4\uac00 \ub41c\ub2e4. \ucda4\uc5d0\uc11c \ucd9c\ubc1c\ud588\ub2e4\uace0 \ud574\uc11c \uc5b8\uc81c\ub098 \ubb34\ub3c4\uc7a5\uc5d0\uc11c \ub611\uac19\uc774 \ucd94\ub3c4\ub85d \ub9cc\ub4e4\uc5b4\uc9c4 \uace1\ub9cc\uc740 \uc544\ub2c8\ub2e4. \ubc15\uc790\ub9c8\ub2e4 \ubb34\uac8c\uac00 \ub611\uac19\uc740\uc9c0, \uc5b4\ub5a4 \ubd80\ubd84\uc5d0\uc11c \ubc1c\uac78\uc74c\uc774 \uac78\ub9ac\ub294 \ub4ef \ub290\uaef4\uc9c0\ub294\uc9c0 \ub4e4\uc5b4 \ubcf4\uc790. \ud070 \uac10\uc815\ub9cc \ub530\ub77c\uac08 \ub54c\ubcf4\ub2e4 \ub9ac\ub4ec\uc758 \ud2b9\uc9d5\uc774 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \uace0\ud5a5\uc758 \ud754\uc801\uc740 \ud2b9\uc815 \uc120\uc728\uc758 \uc778\uc6a9\ub9cc\uc774 \uc544\ub2c8\ub77c \uc774\ub7f0 \ubb34\uac8c\uc640 \uc6c0\uc9c1\uc784\uc758 \ubc29\uc2dd\uc5d0\ub3c4 \ub0a8\uc744 \uc218 \uc788\ub2e4. \uc1fc\ud33d\uc744 \uc124\uba85\ud560 \ub54c \ub8e8\ubc14\ud1a0\ub77c\ub294 \ub9d0\uc744 \uc790\uc8fc \ub9cc\ub09c\ub2e4. \uc2dc\uac04\uc744 \uc870\uae08 \ub298\uc774\uac70\ub098 \ub2f9\uae30\uba70 \ud45c\ud604\ud558\ub294 \uc5f0\uc8fc\uc640 \uad00\ub828\ub41c \ub9d0\uc774\ub2e4. \uadf8\ub7ec\ub098 \uc544\ubb34 \uacf3\uc5d0\uc11c\ub098 \uba48\ucd94\uace0 \uc804\uccb4 \ubc15\uc790\ub97c \uc783\uc5b4\ub3c4 \ub41c\ub2e4\ub294 \ud5c8\uac00\uc99d\uc740 \uc544\ub2c8\ub2e4. \ud750\ub984\uc744 \uc720\uc9c0\ud558\uba74\uc11c \uc18c\ub9ac\uc758 \ub9d0\ud22c\ub97c \uc138\uc2ec\ud558\uac8c \uc870\uc808\ud558\ub294 \ubb38\uc81c\uc5d0 \uac00\uae5d\ub2e4. \uc6b0\ub9ac\uac00 \ubb38\uc7a5\uc744 \uc77d\uc744 \ub54c \ubaa8\ub4e0 \uc74c\uc808\uc744 \uac19\uc740 \uae38\uc774\ub85c \ub9d0\ud558\uc9c0 \uc54a\ub294 \uac83\uc5d0 \ube44\uc720\ud560 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubb38\uc7a5\uc774 \uc5b4\ub514\ub85c \ud5a5\ud558\ub294\uc9c0 \uc78a\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5f0\uc8fc \ub450 \uac1c\ub97c \ube44\uad50\ud574 \ubcf4\uba74 \uac19\uc740 \uc120\uc728\ub3c4 \uc228\uc744 \uc26c\ub294 \uc704\uce58\uc640 \uc6c0\uc9c1\uc784\uc774 \ub2e4\ub974\uac8c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uc774\ub97c \ubaa8\ub450 \uc791\uace1\uac00\uc758 \ud55c \uac00\uc9c0 \uac10\uc815\uc73c\ub85c \ud658\uc6d0\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc791\uac00 \uc870\ub974\uc8fc \uc0c1\ub4dc\uc640\uc758 \uad00\uacc4\ub294 \uc1fc\ud33d\uc758 \uc0dd\uc560\uc5d0\uc11c \ud070 \ube44\uc911\uc744 \ucc28\uc9c0\ud55c\ub2e4. \ub9c8\uc694\ub974\uce74 \uccb4\ub958\uc640 \ud504\ub791\uc2a4 \ub178\uc559\uc5d0\uc11c\uc758 \uc2dc\uac04\uc5d0\ub294 \uac74\uac15\uc758 \uc5b4\ub824\uc6c0\uacfc \uc0dd\ud65c, \uc791\uace1\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \ub450 \uc0ac\ub78c\uc758 \uad00\uacc4\ub97c \ub0ad\ub9cc\uc801\uc778 \uc0ac\ub791 \uc774\uc57c\uae30\ub9cc\uc73c\ub85c \ubcf4\uac70\ub098, \ubc18\ub300\ub85c \ub204\uac00 \ub204\uad6c\uc758 \uc608\uc220\uc744 \ub9dd\ucce4\ub2e4\ub294 \ud310\uc815\uc73c\ub85c \ub05d\ub0b4\uae30\ub294 \uc5b4\ub835\ub2e4. \uc624\ub798\ub41c \uc804\uae30\uc5d0\ub294 \uc0c1\ub4dc\uc640 \uc1fc\ud33d\uc744 \ud3c9\uac00\ud558\ub294 \uac15\ud55c \ud3b8\uacac\ub3c4 \uc11e\uc5ec \uc788\ub2e4. \uadf8\ub7f0 \uc778\ubb3c\ud3c9\uc744 \uadf8\ub300\ub85c \ubc1b\uc544\ub4e4\uc774\uae30\ubcf4\ub2e4 \uc5b4\ub514\uc5d0\uc11c \ud568\uaed8 \uc9c0\ub0c8\uace0 \uc5b4\ub5a4 \uc791\uc5c5\uacfc \uc5b4\ub824\uc6c0\uc774 \uc788\uc5c8\ub294\uc9c0 \uad6c\ubd84\ud574 \uc77d\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc0ac\uc0dd\ud65c\uc740 \uc791\ud488\uc744 \ub9cc\ub098\ub294 \ud55c \ubc30\uacbd\uc774\uc9c0\ub9cc \uc74c\uc545\uc758 \uac00\uce58\ub97c \ub300\uc2e0 \ud310\uacb0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uac74\uac15\uc774 \uc545\ud654\ub41c \uc1fc\ud33d\uc740 1849\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub0ac\ub2e4. \ud53c\uc544\ub178\ub97c \uc911\uc2ec\uc73c\ub85c \ub0a8\uae34 \uc791\ud488\ub4e4\uc740 \ub178\ub798\ud558\ub294 \uc120\uc728\uacfc \ucda4\uc758 \ub9ac\ub4ec, \uc815\uad50\ud55c \uc6c0\uc9c1\uc784\uc744 \uc11c\ub85c \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uc774\uc5b4 \uac04\ub2e4. \ub4e3\uae30 \ud3b8\ud55c \uc57c\uc0c1\uace1 \ud558\ub098\uc640 \ud798 \uc788\ub294 \ud3f4\ub85c\ub124\uc988 \ud558\ub098\ub97c \ube44\uad50\ud558\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \ud55c \uc791\uace1\uac00\uc758 \ud3ed\ub113\uc740 \ud45c\uc815\uc744 \ub9cc\ub0a0 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \uc61b \uc74c\uc545 \uc548\ub0b4\uc11c\uc5d0 \uc2e4\ub9b0 \uc1fc\ud33d\uc758 \uc5ed\uc0ac\uc801 \ucd08\uc0c1 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \uc5bc\uad74\ub9cc\uc73c\ub85c \uadf8\uc758 \uac74\uac15\uc774\ub098 \uc131\uaca9\uc744 \ud310\ub2e8\ud558\uae30\ubcf4\ub2e4 \uc74c\uc545\uc73c\ub85c \ub3cc\uc544\uac08 \ucd9c\ubc1c\uc810\uc73c\ub85c \ubcf4\uba74 \uc88b\ub2e4. \ubc14\ub974\uc0e4\ubc14\uc5d0\uc11c \ubc30\uc6b4 \uccad\ub144, \ud30c\ub9ac\uc5d0\uc11c \uac00\ub974\uce58\ub358 \uc74c\uc545\uac00, \ud55c \uc545\uae30\ub97c \uae4a\uac8c \ud0d0\uad6c\ud55c \uc791\uace1\uac00\ub97c \ud568\uaed8 \uae30\uc5b5\ud558\uba74 \uc775\uc219\ud55c \uc774\ub984 \ub4a4\uc758 \uc0b6\uc774 \uc870\uae08 \ub354 \uc785\uccb4\uc801\uc73c\ub85c \ub4e4\ub9b0\ub2e4."}, {"id": "christmas-carol-scrooge-change", "title": "\ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \uce90\ub7f4 \u2014 \uc2a4\ud06c\ub8e8\uc9c0\uac00 \ub2e4\uc2dc \ubc30\uc6b0\ub294 \uc0ac\ub78c\uc758 \uc628\uae30", "summary": "\uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \ub530\ub77c\uac00\uba70 \ub3c8\uc744 \uc138\ub358 \uc2a4\ud06c\ub8e8\uc9c0\uac00 \uc0ac\ub78c\ub4e4\uc758 \uc0b6\uc744 \ub2e4\uc2dc \ubcf4\uac8c \ub418\ub294 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/christmas-carol-scrooge-change/index.html", "image": "../media/christmas-carol-scrooge-change.jpg", "alt": "\ud398\uc9c0\uc704\uadf8\uc758 \ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \ubb34\ub3c4\ud68c\ub97c \uadf8\ub9b0 \uc61b \uc0bd\ud654. \uc2e4\ub0b4\uc5d0 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc5ec \ucda4\ucd94\uace0 \uc788\uc2b5\ub2c8\ub2e4.", "text": "\ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \uce90\ub7f4 \u2014 \uc2a4\ud06c\ub8e8\uc9c0\uac00 \ub2e4\uc2dc \ubc30\uc6b0\ub294 \uc0ac\ub78c\uc758 \uc628\uae30 \uc138 \uc720\ub839\uc774 \ubcf4\uc5ec \uc900 \uacfc\uac70\uc640 \ud604\uc7ac, \uc544\uc9c1 \ubc14\uafc0 \uc218 \uc788\ub294 \ubbf8\ub798 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \ub530\ub77c\uac00\uba70 \ub3c8\uc744 \uc138\ub358 \uc2a4\ud06c\ub8e8\uc9c0\uac00 \uc0ac\ub78c\ub4e4\uc758 \uc0b6\uc744 \ub2e4\uc2dc \ubcf4\uac8c \ub418\ub294 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \ud06c\ub9ac\uc2a4\ub9c8\uc2a4\ub97c \uc55e\ub454 \uac70\ub9ac\uc5d0\uc11c \ub204\uad70\uac00\ub294 \ub4e4\ub728\uace0 \ub204\uad70\uac00\ub294 \ubc14\uc058\ub2e4. \uc2a4\ud06c\ub8e8\uc9c0\ub294 \uadf8 \uc18c\ub780\uc744 \ub2ec\uac00\uc6cc\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud568\uaed8 \uc77c\ud558\ub294 \uc0ac\ub78c\uc758 \ucd94\uc704\ubcf4\ub2e4 \uc7a5\ubd80\uc758 \uc22b\uc790\uc5d0 \ubbfc\uac10\ud558\uace0, \uc870\uce74\uc758 \ucd08\ub300\ub3c4 \uac70\uc808\ud55c\ub2e4. \ub530\ub73b\ud568\uc744 \ub204\ub9b4 \uc5ec\uc720\uac00 \uc5c6\ub294 \uc0ac\ub78c\uc774\ub77c\uae30\ubcf4\ub2e4, \ub530\ub73b\ud568\uc744 \uc4f8\ub370\uc5c6\ub294 \uc77c\ub85c \uc5ec\uae30\ub294 \uc0ac\ub78c\uc5d0 \uac00\uae5d\ub2e4. \ucc30\uc2a4 \ub514\ud0a8\uc2a4\uac00 1843\ub144\uc5d0 \ubc1c\ud45c\ud55c \u300e\ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \uce90\ub7f4\u300f\uc740 \uadf8\uc5d0\uac8c \uc774\uc0c1\ud55c \ud558\ub8fb\ubc24\uc744 \uc120\ubb3c\ud55c\ub2e4. \uc8fd\uc740 \ub3d9\uc5c5\uc790\uc640 \uc138 \uc720\ub839\uc774 \ucc3e\uc544\uc640 \ub3c8\uc73c\ub85c\ub294 \ubcf4\uc774\uc9c0 \uc54a\ub358 \uc2dc\uac04\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc544\ub798\uc5d0\ub294 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4. \uc774\uc57c\uae30\ub294 \ub9d0\ub9ac\uac00 \uc8fd\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubd84\uba85\ud788 \ubc1d\ud788\uba70 \uc2dc\uc791\ud55c\ub2e4. \uadf8 \ub9d0\ub9ac\uac00 \uc1e0\uc0ac\uc2ac\uc5d0 \ubb36\uc778 \uc720\ub839\uc73c\ub85c \uc2a4\ud06c\ub8e8\uc9c0 \uc55e\uc5d0 \ub098\ud0c0\ub09c\ub2e4. \uc0ac\uc2ac\uc5d0\ub294 \uc7a5\ubd80\uc640 \ub3c8\uc0c1\uc790 \uac19\uc740 \ubb3c\uac74\uc774 \ub9e4\ub2ec\ub824 \uc788\ub2e4. \uc0b4\uc544 \uc788\ub294 \ub3d9\uc548 \ubb34\uc5c7\uc5d0 \ub9e4\uc600\ub294\uc9c0\uac00 \uc8fd\uc5b4\uc11c\ub3c4 \ubab8\uc5d0 \ub0a8\uc740 \ubaa8\uc2b5\ucc98\ub7fc \uc77d\uc744 \uc218 \uc788\ub2e4. \ub9d0\ub9ac\ub294 \uc2a4\ud06c\ub8e8\uc9c0\uc5d0\uac8c \uacbd\uace0\ud558\uace0 \uc138 \uc720\ub839\uc758 \ubc29\ubb38\uc744 \uc608\uace0\ud55c\ub2e4. \ub2e8\uc21c\ud788 \uac81\uc744 \uc8fc\ub294 \uc7a5\uce58\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uc2a4\ud06c\ub8e8\uc9c0\uac00 \uadf8\ub300\ub85c \uc0b4\uc544\uac00\uba74 \uc5b4\ub5a4 \uc0ac\ub78c\uc774 \ub420\uc9c0, \uc8fd\uc740 \ub3d9\uc5c5\uc790\uac00 \uba3c\uc800 \ubcf4\uc5ec \uc8fc\ub294 \uc148\uc774\ub2e4. \uc774\ubbf8 \ub05d\ub09c \uc0b6\uc758 \ud6c4\ud68c\uac00 \uc544\uc9c1 \uc0b4\uc544 \uc788\ub294 \uc0ac\ub78c\uc5d0\uac8c \ub3c4\ucc29\ud55c\ub2e4. \uccab \uc720\ub839\uc740 \uc2a4\ud06c\ub8e8\uc9c0\ub97c \uc5b4\ub9b0 \uc2dc\uc808\ub85c \ub370\ub824\uac04\ub2e4. \ud559\uad50\uc5d0 \ud640\ub85c \ub0a8\uaca8\uc9c4 \uc18c\ub144\uacfc \uadf8\ub97c \ucc3e\uc544\uc628 \uc5ec\ub3d9\uc0dd\uc758 \uae30\uc5b5\uc744 \ub9c8\uc8fc\ud558\uba74\uc11c, \uc9c0\uae08\uc758 \ub0c9\uc815\ud568 \uc544\ub798\uc5d0\ub3c4 \uc678\ub85c\uc6c0\uacfc \uc560\uc815\uc774 \uc788\uc5c8\uc74c\uc744 \uc54c\uac8c \ub41c\ub2e4. \uc2a4\ud06c\ub8e8\uc9c0\uac00 \uc6d0\ub798\ubd80\ud130 \uac10\uc815 \uc5c6\ub294 \uae30\uacc4\uc600\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc80a\uc740 \ub0a0\uc758 \uace0\uc6a9\uc8fc \ud398\uc9c0\uc704\uadf8\uac00 \uc5f0 \ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \ubb34\ub3c4\ud68c\ub3c4 \ubcf4\uac8c \ub41c\ub2e4. \ubc29\uacfc \uc74c\uc2dd, \uc74c\uc545\uc744 \ub9c8\ub828\ud55c \ub355\ubd84\uc5d0 \uc0ac\ub78c\ub4e4\uc774 \uc5bc\ub9c8\ub098 \uc990\uac70\uc6cc\ud558\ub294\uc9c0 \uc9c0\ucf1c\ubcf4\ub294 \uc7a5\uba74\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc61b \uc0bd\ud654\uac00 \ubc14\ub85c \uc774 \ubb34\ub3c4\ud68c\ub97c \uadf8\ub838\ub2e4. \ub3c8\uc758 \uc561\uc218\ubcf4\ub2e4 \uadf8\uac83\uc744 \uc4f0\ub294 \uc0ac\ub78c\uc774 \ub2e4\ub978 \uc774\uc5d0\uac8c \uc5b4\ub5a4 \uc2dc\uac04\uc744 \ub9cc\ub4e4\uc5b4 \uc8fc\ub294\uc9c0\uac00 \uc911\uc694\ud574\uc9c4\ub2e4. \uacfc\uac70\uc5d0\ub294 \uc2a4\ud06c\ub8e8\uc9c0\ub97c \uc0ac\ub791\ud55c \ubca8\ub3c4 \uc788\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \uadf8\uc758 \uad00\uc2ec\uc774 \uc810\ucc28 \ubd80\uc640 \uc548\uc804\uc5d0 \uc3e0\ub9ac\uba74\uc11c \ub450 \uc0ac\ub78c\uc758 \uad00\uacc4\ub294 \ub05d\ub09c\ub2e4. \uc720\ub839\uc774 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \uac00\ub09c\ud588\uc744 \ub54c\ub294 \ud589\ubcf5\ud558\uace0 \ubd80\uc790\uac00 \ub418\uba74 \uc545\ud574\uc9c4\ub2e4\ub294 \ub2e8\uc21c\ud55c \uacf5\uc2dd\uc774 \uc544\ub2c8\ub2e4. \ub450\ub824\uc6c0\uc744 \ud53c\ud558\ub824\uace0 \ubd99\ub4e0 \uac83\uc774 \uc5b4\ub290 \uc21c\uac04 \uc0b6\uc758 \uc911\uc2ec\uc744 \ubaa8\ub450 \ucc28\uc9c0\ud558\ub294 \uacfc\uc815\uc774\ub2e4. \uc2a4\ud06c\ub8e8\uc9c0\ub294 \ubca8\uc774 \ub2e4\ub978 \uac00\uc871\uacfc \ud568\uaed8 \uc0ac\ub294 \ubaa8\uc2b5\ub3c4 \ubcf4\uac8c \ub41c\ub2e4. \uc790\uc2e0\uc774 \uac16\uc9c0 \ubabb\ud55c \uc0b6\uc744 \uc678\ubd80\uc5d0\uc11c \uad6c\uacbd\ud558\ub294 \uc2dc\uac04\uc774 \ub41c\ub2e4. \uacfc\uac70\uc758 \uc7a5\uba74\uc744 \ubc14\uafc0 \uc218 \uc5c6\uae30\uc5d0 \ub354 \uc544\ud504\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uae30\uc5b5\uc740 \ud604\uc7ac\uc758 \uc0ac\ub78c\ub4e4\uc744 \uc5b4\ub5bb\uac8c \ub300\ud560\uc9c0 \ub2e4\uc2dc \uc0dd\uac01\ud558\uac8c \ud558\ub294 \ud798\ub3c4 \uac00\uc9c4\ub2e4. \ub458\uc9f8 \uc720\ub839\uc740 \uc11c\uae30 \ubc25 \ud06c\ub798\uce6b\uc758 \uc9d1\uc73c\ub85c \ub370\ub824\uac04\ub2e4. \uc2dd\ud0c1\uc740 \ub109\ub109\ud558\uc9c0 \uc54a\uc9c0\ub9cc \uac00\uc871\uc740 \ud568\uaed8 \uc74c\uc2dd\uc744 \ub098\ub204\uba70 \ud558\ub8e8\ub97c \ubcf4\ub0b8\ub2e4. \ubab8\uc774 \uc57d\ud55c \uc5b4\ub9b0 \ud0c0\uc774\ub2c8 \ud300\ub3c4 \uadf8 \uc790\ub9ac\uc5d0 \uc788\ub2e4. \uc2a4\ud06c\ub8e8\uc9c0\uc5d0\uac8c\ub294 \uc784\uae08\uc758 \ud56d\ubaa9\uc73c\ub85c\ub9cc \ubcf4\uc774\ub358 \uc0ac\ub78c\uc774 \uac00\uc871\uc758 \uc911\uc2ec\uc5d0\uc11c \uc0b4\uc544\uac00\ub294 \uc7a5\uba74\uc774\ub2e4. \uac00\ub09c\ud55c \uc9d1\uc758 \uc815\uaca8\uc6c0\uc774 \ubcf4\uc778\ub2e4\uace0 \ud574\uc11c \uac00\ub09c\uc774 \uc88b\uc740 \uac83\uc774\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc544\uc774\uc758 \uac74\uac15\uacfc \uc0dd\ud65c\uc758 \ubd88\uc548\ub3c4 \ud568\uaed8 \ub193\uc5ec \uc788\ub2e4. \uc791\ud488\uc740 \uac00\uc871\uc758 \uc560\uc815\uc744 \ubcf4\uc5ec \uc8fc\uba74\uc11c, \uadf8 \uc560\uc815\ub9cc\uc73c\ub85c \ud574\uacb0\ud560 \uc218 \uc5c6\ub294 \uc870\uac74\uae4c\uc9c0 \ub3c5\uc790\uac00 \ubcf4\uac8c \ud55c\ub2e4. \uc0ac\ub78c\uc744 \ub3d5\ub294 \ubb38\uc81c\ub294 \uae30\ubd84 \uc88b\uc740 \ub3d9\uc815\uc73c\ub85c\ub9cc \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \ud604\uc7ac\uc758 \uc720\ub839\uc740 \uc637\uc790\ub77d \uc544\ub798\uc5d0\uc11c \ub450 \uc544\uc774\ub97c \ub4dc\ub7ec\ub0b8\ub2e4. \uc791\ud488\uc740 \uadf8\ub4e4\uc744 \ubb34\uc9c0\uc640 \uacb0\ud54d\uc774\ub77c\ub294 \uc774\ub984\uc73c\ub85c \uc81c\uc2dc\ud55c\ub2e4. \uc990\uac70\uc6b4 \ucd95\uc81c\uc758 \uc7a5\uba74\uc744 \ubcf4\ub358 \ub3c5\uc790\uc5d0\uac8c \uac11\uc790\uae30 \ubd88\ud3b8\ud55c \ud604\uc2e4\uc774 \ub4e4\uc5b4\uc624\ub294 \ub300\ubaa9\uc774\ub2e4. \ub204\uad70\uac00\uc758 \ud06c\ub9ac\uc2a4\ub9c8\uc2a4\uac00 \ube5b\ub0a0 \ub54c\uc5d0\ub3c4 \ub3c4\uc6c0\ubc1b\uc9c0 \ubabb\ud558\ub294 \uc544\uc774\ub294 \uc874\uc7ac\ud55c\ub2e4. \uc2a4\ud06c\ub8e8\uc9c0\uac00 \uac00\ub09c\ud55c \uc0ac\ub78c\ub4e4\uc5d0\uac8c \ud588\ub358 \ucc28\uac00\uc6b4 \ub9d0\ub3c4 \ub2e4\ub978 \uc790\ub9ac\uc5d0\uc11c \ub418\ub3cc\uc544\uc628\ub2e4. \uc81c\ub3c4\ub098 \uc2dc\uc124\uc774 \uc788\uc73c\ub2c8 \ub0b4 \ucc45\uc784\uc740 \ub05d\ub0ac\ub2e4\ub294 \ud0dc\ub3c4\uac00 \uc2e4\uc81c \uc0ac\ub78c \uc55e\uc5d0\uc11c \uc5b4\ub5a4 \ub9d0\uc774 \ub418\ub294\uc9c0 \ub4e3\uac8c \ub418\ub294 \uac83\uc774\ub2e4. \uc720\ub839\uc758 \uc5ec\ud589\uc740 \uc138\uc0c1\uc758 \uc5b4\ub824\uc6c0\uc744 \uc0c8\ub85c \ubc1c\uba85\ud558\uae30\ubcf4\ub2e4 \uadf8\uac00 \uc678\uba74\ud588\ub358 \uac83\uc744 \uac00\uae4c\uc774 \uac00\uc838\uc628\ub2e4. \ub9c8\uc9c0\ub9c9 \uc720\ub839\uc740 \ub9d0\uc5c6\uc774 \uc55e\ub0a0\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc5b4\ub5a4 \uc0ac\ub78c\uc774 \uc8fd\uc5c8\uc9c0\ub9cc \uc0ac\ub78c\ub4e4\uc758 \ubc18\uc751\uc740 \uc2f8\ub298\ud558\uace0, \ub0a8\uaca8\uc9c4 \ubb3c\uac74\uc740 \ud765\uc815\uac70\ub9ac\uac00 \ub41c\ub2e4. \uc2a4\ud06c\ub8e8\uc9c0\ub294 \uadf8\uac83\uc774 \uc790\uc2e0\uc758 \uc8fd\uc74c\uc784\uc744 \uc54c\uc544\ucc28\ub9b0\ub2e4. \uc7ac\uc0b0\uc744 \uc9c0\ud0a4\uba70 \uc0b4\uc544\ub3c4 \uadf8 \uc0b6\uc744 \uc560\ub3c4\ud560 \uad00\uacc4\uae4c\uc9c0 \uc800\uc808\ub85c \ub0a8\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ud06c\ub798\uce6b \uac00\uc871\uc5d0\uac8c\ub3c4 \uc0c1\uc2e4\uc774 \ub2e5\uce5c \ubbf8\ub798\uac00 \ud3bc\uccd0\uc9c4\ub2e4. \uc774 \uc7a5\uba74\uc740 \uc6b4\uba85\uc774 \uc774\ubbf8 \uc815\ud574\uc84c\ub2e4\ub294 \uc120\uc5b8\uc774\ub77c\uae30\ubcf4\ub2e4 \uc9c0\uae08\uc758 \uc120\ud0dd\uc744 \ubb3b\ub294 \uc704\uae30\ub2e4. \uc2a4\ud06c\ub8e8\uc9c0\ub294 \uc55e\uc73c\ub85c\uc758 \uc0b6\uc744 \ubc14\uafb8\uba74 \uc774 \ubbf8\ub798\ub3c4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub294\uc9c0 \ub9e4\ub2ec\ub9b0\ub2e4. \uacfc\uac70\ub294 \ub3cc\uc774\ud0ac \uc218 \uc5c6\uc9c0\ub9cc \ud604\uc7ac\uc5d0\ub294 \uc544\uc9c1 \uc190\uc744 \ubed7\uc744 \uc218 \uc788\ub2e4. \uae68\uc5b4\ub09c \uc2a4\ud06c\ub8e8\uc9c0\ub294 \ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \uc544\uce68\uc774 \uc544\uc9c1 \ub0a8\uc544 \uc788\uc74c\uc744 \uc54c\uace0 \uae30\ubed0\ud55c\ub2e4. \uc74c\uc2dd\uc744 \ubcf4\ub0b4\uace0 \uae30\ubd80\ud558\uba70 \uc870\uce74\uc758 \uc9d1\uc744 \ucc3e\ub294\ub2e4. \ubc25 \ud06c\ub798\uce6b\uc744 \ub300\ud558\ub294 \ubc29\uc2dd\uacfc \uc784\uae08\ub3c4 \ubc14\uafbc\ub2e4. \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \ud0c0\uc774\ub2c8 \ud300\uc774 \uc0b4\uc544\ub0a8\uace0, \uc2a4\ud06c\ub8e8\uc9c0\uac00 \uadf8 \uc544\uc774\uc5d0\uac8c \ub610 \ud55c \uc0ac\ub78c\uc758 \ubcf4\ud638\uc790 \uac19\uc740 \uc874\uc7ac\uac00 \ub418\uc5c8\ub2e4\uace0 \uc804\ud55c\ub2e4. \uc774 \uacb0\ub9d0\uc758 \uc911\uc694\ud55c \uc810\uc740 \ub9c8\uc74c\uc18d \ubc18\uc131\ub9cc\uc73c\ub85c \uba48\ucd94\uc9c0 \uc54a\ub294\ub2e4\ub294 \ub370 \uc788\ub2e4. \uc5b4\uc81c \uc790\uc2e0\uc774 \ucc28\uac11\uac8c \ub300\ud588\ub358 \uc0ac\ub78c\uc5d0\uac8c \uc624\ub298 \ubb34\uc5c7\uc744 \ud560 \uac83\uc778\uac00. \ub3c8\uacfc \uc2dc\uac04, \uad00\uacc4\ub97c \ub2e4\ub974\uac8c \uc4f0\ub294 \ud589\ub3d9\uc774 \uc774\uc5b4\uc9c0\uba74\uc11c \ubcc0\ud654\ub294 \ub2e4\ub978 \uc0ac\ub78c\ub3c4 \uacaa\ub294 \ud604\uc2e4\uc774 \ub41c\ub2e4. \uc6d0\uc791\uc758 \ub2e4\uc12f \ubd80\ubd84\uc740 \ub178\ub798\uc758 \uc808\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uc774\ub984\uc73c\ub85c \ub098\ub25c\ub2e4. \uc81c\ubaa9\uc758 \uce90\ub7f4\ub3c4 \ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \ub178\ub798\ub97c \uac00\ub9ac\ud0a8\ub2e4. \uc990\uac70\uc6b4 \uacc4\uc808\uc758 \uc774\ub984\uc744 \ub2e8 \uc791\ud488\uc774\uc9c0\ub9cc, \uadf8 \ub178\ub798 \uc548\uc5d0\ub294 \uc678\ub85c\uc6c0\uacfc \uc0ac\ud68c\uc758 \ubb34\uc2ec\ud568, \ubc14\uafc0 \uc218 \uc788\ub294 \uc120\ud0dd\uc774 \ud568\uaed8 \ub2f4\uaca8 \uc788\ub2e4. \uc2a4\ud06c\ub8e8\uc9c0\uc758 \ubcc0\ud654\ub97c \ud604\uc2e4\uc758 \ubaa8\ub4e0 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub294 \ucc98\ubc29\uc73c\ub85c \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \ud55c \uc0ac\ub78c\uc774 \uc790\uae30 \uc0b6\uc758 \uc911\uc2ec\uc744 \ubc14\uafb8\ub294 \uc774\uc57c\uae30\ub294 \uc5ec\uc804\ud788 \uc77d\uc744 \ub9cc\ud558\ub2e4. \uc624\ub298 \ub0b4\uac00 \ube44\uc6a9\uc73c\ub85c\ub9cc \uc14c\ub358 \ub204\uad70\uac00\uc5d0\uac8c \uc5b4\ub5a4 \uc0dd\ud65c\uacfc \uac00\uc871\uc774 \uc788\ub294\uc9c0, \uc624\ub798\ub41c \uc720\ub839 \uc774\uc57c\uae30\uac00 \uadf8 \uc791\uc740 \uc0c1\uc0c1\uc744 \uc5f4\uc5b4 \uc900\ub2e4."}, {"id": "christmas-pudding-sixpence", "title": "\ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \ud478\ub529\uc5d0\ub294 \uc65c \ub3d9\uc804 \uc774\uc57c\uae30\uac00 \ub530\ub77c\uc62c\uae4c", "summary": "\uc5f0\ub9d0 \ub514\uc800\ud2b8 \uc606\uc5d0 \uc740\ube5b \ub3d9\uc804\uc774 \ub4f1\uc7a5\ud569\ub2c8\ub2e4. \ub3c8\uc758 \uc561\uba74\ubcf4\ub2e4 \ud589\uc6b4\uc744 \ubc14\ub77c\ub294 \ub9c8\uc74c\uc774 \uc55e\uc5d0 \ub193\uc774\ub294 \ud48d\uc2b5\uc785\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc2e0\ud654\uc640 \ubbfc\uc18d", "categories": ["arts"], "url": "stories/christmas-pudding-sixpence/index.html", "image": "../media/christmas-pudding-sixpence.jpg", "alt": "\ud478\ub529 \uc811\uc2dc \ubc14\uae65\uc5d0 \uc740\ube5b \ub3d9\uc804\uc744 \ub098\ub780\ud788 \ub193\uc740 AI \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \ud478\ub529\uc5d0\ub294 \uc65c \ub3d9\uc804 \uc774\uc57c\uae30\uac00 \ub530\ub77c\uc62c\uae4c \uc791\uc740 \uc2dd\uc2a4\ud39c\uc2a4\uc5d0 \ub2f4\uc544 \ub450\uc5c8\ub358 \uc0c8\ud574\uc758 \ubc14\ub78c \uc5f0\ub9d0 \ub514\uc800\ud2b8 \uc606\uc5d0 \uc740\ube5b \ub3d9\uc804\uc774 \ub4f1\uc7a5\ud569\ub2c8\ub2e4. \ub3c8\uc758 \uc561\uba74\ubcf4\ub2e4 \ud589\uc6b4\uc744 \ubc14\ub77c\ub294 \ub9c8\uc74c\uc774 \uc55e\uc5d0 \ub193\uc774\ub294 \ud48d\uc2b5\uc785\ub2c8\ub2e4. \uc2e0\ud654\uc640 \ubbfc\uc18d \ubb38\ud654\uc640 \uc608\uc220 \ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \ud478\ub529 \uc0ac\uc9c4\uc744 \ubcf4\uba74 \ub465\uadfc \ub514\uc800\ud2b8 \uc606\uc5d0 \uc791\uc740 \uc740\ube5b \ub3d9\uc804\uc774 \ub193\uc5ec \uc788\uae30\ub3c4 \ud558\ub2e4. \ud6c4\uc2dd \uac12\uc744 \ubbf8\ub9ac \uacc4\uc0b0\ud574 \ub454 \uac83\uc77c\uae4c. \uadf8 \ub3d9\uc804\uc740 \uc601\uad6d\uc758 \uc2dd\uc2a4\ud39c\uc2a4\uc640 \uad00\ub828\ub41c \ud48d\uc2b5\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \ud478\ub529 \uc18d\uc5d0 \ub3d9\uc804\uc744 \uc228\uae30\uace0, \uadf8\uac83\uc744 \ucc3e\uc740 \uc0ac\ub78c\uc5d0\uac8c \ub2e4\uc74c \ud574\uc758 \uc88b\uc740 \uc6b4\uc774 \uc624\uae30\ub97c \ubc14\ub790\ub2e4\ub294 \uc774\uc57c\uae30\ub2e4. \ub3d9\uc804\uc774 \ub3c8\uc744 \ub0b4\ub294 \uc790\ub9ac\uc5d0\uc11c \uc7a0\uae50 \ubc97\uc5b4\ub098 \uc18c\uc6d0\uc744 \ub2f4\ub294 \ubb3c\uac74\uc774 \ub41c\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\uc740 2024\ub144 \ubcf4\ub3c4\uc790\ub8cc\uc5d0\uc11c \u2018\uc2a4\ud138\uc5c5 \uc120\ub370\uc774\u2019\ub77c\ub294 \ud48d\uc2b5\uc744 \uc18c\uac1c\ud588\ub2e4. \ub300\ub9bc\uc808\uc774 \uc2dc\uc791\ub418\uae30 \uc804 \ub9c8\uc9c0\ub9c9 \uc77c\uc694\uc77c, \uac00\uc871\uacfc \uce5c\uad6c\uac00 \ubaa8\uc5ec \ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \ud478\ub529\uc744 \uc900\ube44\ud558\ub294 \ub0a0\uc774\ub2e4. \uc790\ub8cc\uc5d0 \uc18c\uac1c\ub41c \uc74c\uc2dd\uc0ac \uc5f0\uad6c\uc790 \uc560\ub2c8 \uadf8\ub808\uc774\ub294 \uc0ac\ub78c\ub4e4\uc774 \ubc18\uc8fd\uc744 \ubc88\uac08\uc544 \uc800\uc73c\uba70 \uc18c\uc6d0\uc744 \ube4c\ub358 \uc804\ud1b5\uc744 \uc124\uba85\ud55c\ub2e4. \ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \ub2f9\uc77c\ub9cc \uae30\ub2e4\ub9ac\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \ubbf8\ub9ac \ubaa8\uc5ec \uc900\ube44\ud558\ub294 \uc2dc\uac04\uc5d0\ub3c4 \uc758\ubbf8\ub97c \ub450\uc5c8\ub358 \uc148\uc774\ub2e4. \uc774 \uc774\ub984\uc5d0\ub294 \u2018\uc800\uc5b4 \uc11e\ub2e4\u2019\ub77c\ub294 \ub73b\uacfc \uc5f0\uacb0\ub418\ub294 \ub9d0\uc7a5\ub09c\ub3c4 \uc788\ub2e4. \uadf8\ub808\uc774\ub294 \uad50\ud68c\uc758 \uae30\ub3c4\ubb38\uc5d0 \ub098\uc624\ub294 \ud45c\ud604\uc774 \ud478\ub529 \uc900\ube44\ub97c \ub5a0\uc62c\ub9ac\ub294 \uacc4\uae30\ub85c \uc4f0\uc600\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uae38\uace0 \uc5b4\ub824\uc6b4 \uc124\uba85\ubcf4\ub2e4, \uc775\uc219\ud55c \ub9d0\uc744 \uc5f0\ub9d0\uc758 \ud560 \uc77c\uacfc \uc5ee\uc5b4 \uae30\uc5b5\ud55c \ubaa8\uc2b5\uc774 \uc7ac\ubbf8\uc788\ub2e4. \uac19\uc740 \uc790\ub8cc\ub294 \ub354 \uc624\ub798\ub41c \ud2b8\uc6f0\ud504\uc2a4 \ucf00\uc774\ud06c\uc5d0 \ud45c\uc2dd\uc744 \uc228\uae30\ub358 \ud48d\uc2b5\ub3c4 \uc774\uc57c\uae30\ud55c\ub2e4. \uc774\ud6c4\uc758 \ud478\ub529 \uc804\ud1b5\uc5d0\uc11c\ub294 \uc791\uc740 \ub3d9\uc804\uc744 \ucc3e\uc740 \uc0ac\ub78c\uc5d0\uac8c \ubd80\uc640 \uac74\uac15, \ud589\ubcf5\uc744 \uae30\uc6d0\ud588\ub2e4\ub294 \uac83\uc774\ub2e4. \ub3d9\uc804\uc744 \ucc3e\uc558\ub2e4\uace0 \uc2e4\uc81c\ub85c \ubbf8\ub798\uac00 \ub2ec\ub77c\uc9c4\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ud55c \ud574\ub97c \ub9c8\ubb34\ub9ac\ud558\ub294 \uc790\ub9ac\uc5d0 \ub2e4\uc74c \ud574\uc758 \ubc14\ub78c\uc744 \uc5b9\uc5c8\ub2e4\ub294 \uc810\uc774\ub2e4. \ud3c9\ubc94\ud55c \ud6c4\uc2dd\uc5d0 \uc791\uc740 \ub73b\ubc16\uc758 \uc77c\uc774 \ub354\ud574\uc9c4\ub2e4. \uadf8\ub798\uc11c \uc774 \uc774\uc57c\uae30\uc5d0\uc11c \ub3d9\uc804\uc758 \uc561\uba74\uc740 \uc8fc\uc778\uacf5\uc774 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \ud568\uaed8 \uc900\ube44\ud558\uace0, \ub204\uad70\uac00 \uc88b\uc740 \uac83\uc744 \ubc1c\uacac\ud558\uae30\ub97c \uae30\ub300\ud588\ub2e4\ub294 \uae30\uc5b5\uc774 \ub3d9\uc804 \uc8fc\ubcc0\uc5d0 \ub0a8\ub294\ub2e4. \ud478\ub529\uc744 \uc900\ube44\ud558\ub294 \ub0a0\uc5d0 \ubaa8\uc5ec \ubc18\uc8fd\uc744 \uc813\ub294\ub2e4\ub294 \uc774\uc57c\uae30\ub294 \ud06c\ub9ac\uc2a4\ub9c8\uc2a4\uc758 \uc911\uc2ec\uc744 \uc2dd\ud0c1\uc758 \ud55c\uc21c\uac04\uc5d0\uc11c \uc55e\uc120 \uc2dc\uac04\uc73c\ub85c \uc62e\uae34\ub2e4. \ub9cc\ub4dc\ub294 \uacfc\uc815\uc5d0 \ud568\uaed8 \ucc38\uc5ec\ud558\uba74 \uc74c\uc2dd\uc740 \ub204\uad70\uac00 \uc644\uc131\ud574\uc11c \ub0b4\ub193\ub294 \uacb0\uacfc\ub9cc\uc774 \uc544\ub2c8\ub77c \uac19\uc774 \uc900\ube44\ud55c \uae30\uc5b5\ub3c4 \uac16\uac8c \ub41c\ub2e4. \ub2ec\ub825\uc758 \ud2b9\uc815\ud55c \ub0a0\uacfc \ubc18\ubcf5\ub418\ub294 \ud589\ub3d9\uc774 \ud574\ub9c8\ub2e4 \uc5f0\uacb0\ub418\ub294 \uc148\uc774\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \uac00\uc815\uc774 \uc5b8\uc81c\ub098 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc774 \ud48d\uc2b5\uc744 \uc9c0\ucf30\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc790\ub8cc\ub294 \ud2b9\uc815 \uc804\ud1b5\uc744 \uc18c\uac1c\ud558\uace0 \ub418\uc0b4\ub9ac\ub824\ub294 \ubaa9\uc801\uc73c\ub85c \uc4f0\uc600\ub2e4. \uba85\uc808\uc758 \ud48d\uc2b5\uc5d0\ub294 \uc774\uc5b4\uc9c4 \uc2e4\ucc9c\ubfd0 \uc544\ub2c8\ub77c \ub098\uc911\uc5d0 \ub2e4\uc2dc \uac15\uc870\ud558\uace0 \uc0c1\ud488\uacfc \uc5f0\uacb0\ud558\ub294 \uc120\ud0dd\ub3c4 \uc788\ub2e4. \uc9c0\uae08 \uc77d\ub294 \uc124\uba85\uc774 \uc5b4\ub290 \uc2dc\uc810\uc5d0 \uc5b4\ub5a4 \ubaa9\uc801\uc73c\ub85c \uc804\ud574\uc9c0\ub294\uc9c0 \ud568\uaed8 \ubcf4\uba74 \ub354 \uc815\ud655\ud558\ub2e4. \uc2a4\ud138\uc5c5\uc774\ub77c\ub294 \ud45c\ud604\uc740 \uc885\uad50\uc801 \ubb38\ub9e5\uc758 \ub9d0\uacfc \ubc18\uc8fd\uc744 \uc813\ub294 \ud589\ub3d9\uc744 \uc5f0\uacb0\ud558\ub294 \ub9d0\uc7a5\ub09c\uc73c\ub85c \uc18c\uac1c\ub41c\ub2e4. \uc5b4\ub824\uc6b4 \uad50\ub9ac\ub97c \ubaa8\ub450 \uc54c\uc544\uc57c\ub9cc \uc774\ud574\ud560 \uc218 \uc788\ub294 \uc7a5\uba74\uc740 \uc544\ub2c8\ub2e4. \uc774\ubbf8 \uc775\uc219\ud55c \ud45c\ud604\uc774 \uacc4\uc808\uc758 \uc900\ube44\uc640 \ub9cc\ub098 \uae30\uc5b5\ud558\uae30 \uc26c\uc6b4 \uc774\ub984\uc774 \ub418\uc5c8\ub2e4\ub294 \uc810\uc744 \ubcfc \uc218 \uc788\ub2e4. \uac19\uc740 \ub9d0\ub3c4 \uc7a5\uc18c\uac00 \ub2ec\ub77c\uc9c0\uba74 \ub2e4\ub978 \ud589\ub3d9\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uc774\ub984\uc744 \uae30\uc5b5\ud55c\ub2e4\uace0 \uc720\ub798\uc758 \ubaa8\ub4e0 \uc2dc\uac04\uc774 \ud655\uc815\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub290 \uc124\uba85\uc774 \uc74c\uc2dd\uc0ac \uc5f0\uad6c\uc790\uc758 \ud574\uc124\uc774\uace0 \uc5b4\ub290 \ubd80\ubd84\uc774 \uc9c0\uae08\uc758 \ud64d\ubcf4 \ubb38\uad6c\uc778\uc9c0 \uad6c\ubd84\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc804\ud1b5\uc758 \uc774\uc57c\uae30\ub294 \uc790\ub8cc\ub97c \uc77d\ub294 \ud604\uc7ac\uc5d0\ub3c4 \uc0c8\ub85c \uafb8\ub824\uc838 \uc804\ub2ec\ub41c\ub2e4. \uc774\ub984\uc774 \uc7ac\ubbf8\uc788\ub2e4\ub294 \uac10\uc0c1\uacfc \uadf8 \uc720\ub798\uac00 \uc5b4\ub5a4 \uadfc\uac70\ub85c \uc18c\uac1c\ub418\ub294\uc9c0\uc758 \uc9c8\ubb38\uc744 \ud568\uaed8 \uac00\uc9c8 \uc218 \uc788\ub2e4. \uc791\uc740 \ud45c\uc2dd\uc744 \uc74c\uc2dd \uc548\uc5d0\uc11c \ucc3e\ub294 \ud48d\uc2b5\uc740 \uc815\ud574\uc9c4 \uc21c\uc11c\uc5d0 \ub73b\ubc16\uc758 \uc21c\uac04\uc744 \ub354\ud55c\ub2e4. \ub204\uac00 \ubc1c\uacac\ud560\uc9c0 \ubaa8\ub974\ub294 \ud45c\uc9c0\ub294 \uadf8 \uc790\ub9ac\uc5d0 \uc788\ub294 \uc0ac\ub78c\ub4e4\uc758 \uae30\ub300\ub97c \ubaa8\uc744 \uc218 \uc788\ub2e4. \ub3d9\uc804\uc758 \uae08\uc18d \uac00\uce58\ub098 \uc561\uba74\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b4 \uc4f0\uc784\uc774\ub2e4. \uba39\ub294 \uc74c\uc2dd\uacfc \ubc1c\uacac\uc744 \uae30\ub2e4\ub9ac\ub294 \ub180\uc774, \uc88b\uc740 \ub73b\uc758 \uae30\uc6d0\uc774 \uc5f0\uacb0\ub41c\ub2e4. \ubb3c\ub860 \ud45c\uc2dd\uc744 \ucc3e\uc740 \uc0ac\ub78c\uc758 \ubbf8\ub798\uac00 \uc2e4\uc81c\ub85c \ub2ec\ub77c\uc84c\ub2e4\ub294 \uc99d\uac70\ub97c \ub9d0\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb38\ud654\uc801 \uc758\ubbf8\ub97c \uc790\uc5f0\uc758 \uc778\uacfc\uad00\uacc4\ub85c \ubc14\uafb8\uc9c0 \uc54a\uc544\ub3c4 \uc774\uc57c\uae30\ub294 \ucda9\ubd84\ud788 \uc7ac\ubbf8\uc788\ub2e4. \uc774 \uae00\uc740 \uc720\ub798\ub97c \uc18c\uac1c\ud558\uba70 \uc2e4\uc81c \uc74c\uc2dd\uc5d0 \ub3d9\uc804\uc744 \ub123\uc5b4 \uc870\ub9ac\ud558\ub294 \ubc29\ubc95\uc744 \uc548\ub0b4\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc804\ud1b5\uc744 \uc77d\ub294 \uc77c\uacfc \uadf8\ub300\ub85c \uc2e4\ud589\ud558\ub294 \uc77c\uc740 \uad6c\ubd84\ud560 \uc218 \uc788\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\uc774 \uc774 \uc804\ud1b5\uc744 \uc18c\uac1c\ud55c\ub2e4\ub294 \uc0ac\uc2e4\ub3c4 \ub208\uc5ec\uaca8\ubcfc \ub9cc\ud558\ub2e4. \uc74c\uc2dd\ub9cc\uc774 \uc544\ub2c8\ub77c \ub3d9\uc804\uc774 \uc0ac\ub78c\ub4e4\uc758 \uae30\uc5b5 \uc18d\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uc4f0\uc600\ub294\uc9c0\ub97c \ubcf4\uc5ec \uc904 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ub3d9\uc2dc\uc5d0 \uc0c1\ud488\uacfc \uc5f0\uacb0\ud55c \ubcf4\ub3c4\uc790\ub8cc\ub77c\ub294 \uc131\uaca9\uc774 \uc788\ub2e4. \uc5ed\uc0ac \uc774\uc57c\uae30\uac00 \ud2b9\uc815\ud55c \ubb3c\uac74\uc758 \ud64d\ubcf4\uc5d0 \uc4f0\uc778\ub2e4\ub294 \uc810\uc744 \uc228\uae30\uc9c0 \uc54a\uace0 \uc77d\uc73c\uba74 \uc815\ubcf4\uc758 \ub9e5\ub77d\uc774 \ub354 \ubd84\uba85\ud574\uc9c4\ub2e4. \uc774 \uc0ac\ub840\uc5d0\uc11c\ub294 \uc74c\uc2dd\uc0ac \uc5f0\uad6c\uc790\uc758 \uc124\uba85\uacfc \uc790\ub8cc\uc758 \ubaa9\uc801\uc744 \ub098\ub780\ud788 \ub193\ub294\ub2e4. \ud64d\ubcf4 \uc790\ub8cc\ub77c\uace0 \ubaa8\ub4e0 \uc124\uba85\uc744 \uc9c0\uc6b8 \ud544\uc694\ub3c4, \uae30\uad00 \uc774\ub984\uc774 \uc788\ub2e4\uace0 \ubaa8\ub4e0 \uacfc\uc7a5\uc744 \uc0ac\uc2e4\ub85c \ubc1b\uc744 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ub204\uad6c\uc758 \uc5b4\ub5a4 \uc124\uba85\uc744 \uadfc\uac70\ub85c \uc0bc\uc558\ub294\uc9c0 \ud655\uc778\ud558\uba70 \ub0a8\uae38 \ubd80\ubd84\uc744 \uace0\ub974\ub294 \uac83\uc774\ub2e4. \ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \ud478\ub529\uc758 \ub3d9\uc804\uc740 \uba85\uc808\uc758 \ubd80\uc5cc\uacfc \uc624\ub298\uc758 \uc804\ud1b5 \uc18c\uac1c\uac00 \ub9cc\ub098\ub294 \uc791\uc740 \ubb3c\uac74\uc774\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\uc774 \uc774 \uc790\ub8cc\ub97c \ub0b8 \uac83\uc740 \uc804\ud1b5\uc744 \ub418\uc0b4\ub9ac\ub824\ub294 \uc0c1\ud488 \ud64d\ubcf4\uc640\ub3c4 \uad00\ub828\uc774 \uc788\ub2e4. \uadf8\ub7ec\ub2c8 \uc624\ub298\uc758 \uc601\uad6d \uac00\uc815\uc774 \ubaa8\ub450 \uac19\uc740 \ud478\ub529\uc744 \ub9cc\ub4e4\uace0 \uac19\uc740 \ud48d\uc2b5\uc744 \uc9c0\ud0a8\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8 \uc810\uc744 \uc54c\uace0 \uc77d\uc5b4\ub3c4 \uc791\uc740 \uc774\uc57c\uae30\ub294 \ub0a8\ub294\ub2e4. \ud2b9\ubcc4\ud55c \ub0a0\uc758 \uc74c\uc2dd\uc5d0\ub294 \ub9db\uacfc \uc7ac\ub8cc\ub9cc \ub4e4\uc5b4\uac00\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc900\ube44\ud558\ub294 \uc21c\uc11c, \ud568\uaed8\ud558\ub294 \uc0ac\ub78c, \uc88b\uc740 \uc6b4\uc744 \ubc14\ub77c\ub358 \ub9c8\uc74c\ub3c4 \ubd99\uc5b4 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \ud478\ub529 \uc606\uc758 \uc740\ube5b \ub3d9\uc804\uc744 \ubcf4\uac8c \ub41c\ub2e4\uba74 \ud6c4\uc2dd \uac12 \ub300\uc2e0 \ub204\uad70\uac00\uc758 \uc18c\uc6d0\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc774\ubc88 \uc0bd\ud654\ucc98\ub7fc \ub3d9\uc804\uc744 \uc811\uc2dc \ubc16\uc5d0 \ub098\ub780\ud788 \ub193\uc544\ub450\uc5b4\ub3c4, \uadf8 \uc791\uc740 \ubb3c\uac74\uc774 \ub4e4\ub824\uc8fc\ub294 \uc5f0\ub9d0 \uc774\uc57c\uae30\ub294 \ucda9\ubd84\ud788 \uc804\ud574\uc9c4\ub2e4."}, {"id": "confucius-life-and-learning", "title": "\uacf5\uc790\uc758 \uc0dd\uc560 \u2014 \ubc30\uc6c0\uc740 \uc5b8\uc81c \ub05d\ub098\ub294 \uac78\uae4c", "summary": "\ub178\ub098\ub77c\uc5d0\uc11c \uc5ec\ub7ec \ub098\ub77c\ub97c \uac70\uce5c \uc5ec\uc815, \ub17c\uc5b4\uc758 \ubc30\uc6c0\uacfc \uad00\uacc4\ub97c \ud1b5\ud574 \uacf5\uc790\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ucca0\ud559", "categories": ["arts"], "url": "stories/confucius-life-and-learning/index.html", "image": "../media/confucius-life-and-learning-cover-20261030.jpg", "alt": "1910\ub144 \uc601\ubb38\ud310 The Sayings of Confucius\uc758 \uc2e4\uc81c \ud45c\uc9c0. \uacf5\uc790\ub97c \ud45c\ud604\ud55c \ud6c4\ub300\uc758 \uc778\ubb3c \uadf8\ub9bc\uacfc \ucc45 \uc81c\ubaa9\uc774 \ubcf4\uc785\ub2c8\ub2e4.", "text": "\uacf5\uc790\uc758 \uc0dd\uc560 \u2014 \ubc30\uc6c0\uc740 \uc5b8\uc81c \ub05d\ub098\ub294 \uac78\uae4c \ub73b\ub300\ub85c \ub418\uc9c0 \uc54a\uc740 \uc815\uce58\uc758 \uae38\uacfc \uc624\ub798 \ub0a8\uc740 \uac00\ub974\uce68 \ub178\ub098\ub77c\uc5d0\uc11c \uc5ec\ub7ec \ub098\ub77c\ub97c \uac70\uce5c \uc5ec\uc815, \ub17c\uc5b4\uc758 \ubc30\uc6c0\uacfc \uad00\uacc4\ub97c \ud1b5\ud574 \uacf5\uc790\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ucca0\ud559 \ubb38\ud654\uc640 \uc608\uc220 \uc11c\ub978\uc774\uba74 \uc790\ub9ac\ub97c \uc7a1\uace0 \ub9c8\ud754\uc774\uba74 \ud754\ub4e4\ub9ac\uc9c0 \uc54a\uc544\uc57c \ud55c\ub2e4\ub294 \ub9d0\uc744 \ub4e4\uc73c\uba74 \uc624\ud788\ub824 \ub9c8\uc74c\uc774 \uae09\ud574\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub7f0\ub370 \uadf8 \ub098\uc774\uc758 \ud45c\ud604\uc774 \uc624\ub298\uc758 \ubaa8\ub4e0 \uc0ac\ub78c\uc5d0\uac8c \uc801\uc6a9\ub418\ub294 \uc778\uc0dd \ud3c9\uac00\ud45c\uc600\uc744\uae4c. \uacf5\uc790\uc758 \ub9d0\uc744 \uc77d\ub294 \ucd9c\ubc1c\uc810\uc744 \uc5ec\uae30\uc11c \uc870\uae08 \ubc14\uafb8\uc5b4 \ubcfc \uc218 \uc788\ub2e4. \uacf5\uc790\ub294 \uae30\uc6d0\uc804 551\ub144\uc5d0 \ud0dc\uc5b4\ub098 \uae30\uc6d0\uc804 479\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub09c \uc911\uad6d \ucd98\ucd94\uc2dc\ub300\uc758 \uc778\ubb3c\uc774\ub2e4. \ub178\ub098\ub77c\uc5d0\uc11c \ubc30\uc6b0\uace0 \uac00\ub974\ucce4\uc73c\uba70 \uc815\uce58\uc758 \ud604\uc7a5\uc5d0\ub3c4 \ub098\uc130\ub2e4. \ucc98\uc74c\ubd80\ud130 \uc644\uc131\ub41c \uba85\uc5b8\uc758 \uc8fc\uc778\uc774\uc5c8\ub2e4\uae30\ubcf4\ub2e4, \ub73b\ub300\ub85c \ub418\uc9c0 \uc54a\ub294 \ud604\uc2e4 \uc18d\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uc0b4\uace0 \ubc30\uc6b8\uc9c0 \ubb3c\uc5c8\ub358 \uc0ac\ub78c\uc73c\ub85c \ub9cc\ub098 \ubcf4\uc790. \uacf5\uc790\uac00 \uc0b4\ub358 \uc2dc\ub300\uc5d0\ub294 \uc5ec\ub7ec \ub098\ub77c\uc640 \uac15\ud55c \uac00\ubb38\uc774 \ud798\uc744 \uaca8\ub8e8\uc5c8\ub2e4. \uc624\ub798\ub41c \uc9c8\uc11c\uc640 \uc774\ub984\uc740 \ub0a8\uc544 \uc788\uc5b4\ub3c4 \uadf8\uac83\uc774 \uc2e4\uc81c \ud589\ub3d9\uc744 \ud1b5\uc81c\ud558\uc9c0 \ubabb\ud558\ub294 \uc77c\uc774 \ubc8c\uc5b4\uc84c\ub2e4. \uacf5\uc790\uac00 \uc608\uc640 \ubc14\ub978 \ud1b5\uce58\uc5d0 \uad00\uc2ec\uc744 \uac00\uc84c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc774\ub7f0 \ubc30\uacbd \uc18d\uc5d0\uc11c \uc774\ud574\ud558\uba74 \ub35c \ucd94\uc0c1\uc801\uc774\ub2e4. \uc608\ub294 \uc624\ub298\uc758 \uc778\uc0ac\ubc95\uc774\ub098 \uc2dd\uc0ac \uc608\uc808 \ubaa9\ub85d\ubcf4\ub2e4 \ub113\uc740 \ubb38\uc81c\ub2e4. \uad00\uacc4 \uc548\uc5d0\uc11c \uc5b4\ub5a4 \ud0dc\ub3c4\ub85c \ud589\ub3d9\ud558\uba70, \uc774\ub984\uc5d0 \uac78\ub9de\uc740 \ucc45\uc784\uc744 \uc5b4\ub5bb\uac8c \uc218\ud589\ud560 \uac83\uc778\uac00\uc640 \uc774\uc5b4\uc9c4\ub2e4. \uac89\uc73c\ub85c \uc758\uc2dd\uc744 \uc815\ud655\ud788 \uce58\ub974\ub294 \uc77c\uacfc \ub2e4\ub978 \uc0ac\ub78c\uc744 \uc81c\ub300\ub85c \ub300\ud558\ub294 \uc77c\uc774 \ub5a8\uc5b4\uc838 \ubc84\ub9b4 \ub54c \ubb34\uc5c7\uc774 \ub0a8\ub290\ub0d0\ub294 \uc9c8\ubb38\uc73c\ub85c \ub4e4\uc5b4\uac00\ub3c4 \uc88b\ub2e4. \uacf5\uc790\ub294 \ubc30\uc6b0\uace0 \uac00\ub974\uce58\ub294 \uc0ac\ub78c\uc73c\ub85c \uc54c\ub824\uc84c\uc9c0\ub9cc \uc815\uce58\uc640 \ubb34\uad00\ud558\uac8c \uad50\uc2e4\uc5d0\ub9cc \uba38\ubb34\ub978 \uc778\ubb3c\uc740 \uc544\ub2c8\ub2e4. \ub178\ub098\ub77c\uc5d0\uc11c \uad00\uc9c1\uc744 \ub9e1\uc558\uace0, \uc790\uc2e0\uc774 \uc0dd\uac01\ud55c \ubc14\ub978 \ud1b5\uce58\uac00 \ud604\uc2e4\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c0\uae30\ub97c \ubc14\ub790\ub2e4. \ub2e4\ub9cc \uc804\ud574\uc9c0\ub294 \uad00\uc9c1\uc758 \uc138\ubd80\uc640 \uc77c\ud654\uc5d0\ub294 \ud6c4\ub300\uc758 \uc124\uba85\uc774 \uc5bd\ud600 \uc788\uc73c\ubbc0\ub85c \ubaa8\ub4e0 \uc7a5\uba74\uc744 \uadf8\ub300\ub85c \ud604\uc7a5 \uae30\ub85d\ucc98\ub7fc \uc77d\uc9c0\ub294 \ub9d0\uc790. \uc911\uc694\ud55c \uac83\uc740 \uc0dd\uac01\uacfc \ud604\uc2e4\uc758 \uac70\ub9ac\uac00 \uadf8\uc758 \uc0dd\uc560 \uc548\uc5d0 \uc788\uc5c8\ub2e4\ub294 \uc810\uc774\ub2e4. \ubc14\ub978 \ub9d0\uc744 \uc548\ub2e4\uace0 \ud574\uc11c \uad8c\ub825\uc790\uac00 \uace7 \ub530\ub974\ub294 \uac83\ub3c4, \uc81c\ub3c4\uac00 \uc790\ub3d9\uc73c\ub85c \ubc14\ub00c\ub294 \uac83\ub3c4 \uc544\ub2c8\uc5c8\ub2e4. \uacf5\uc790\ub97c \ub298 \uc131\uacf5\ud55c \uc870\uc5b8\uc790\ub85c\ub9cc \uc0c1\uc0c1\ud558\uba74 \uc624\ud788\ub824 \ubc30\uc6c0\uc774 \uc65c \ud3c9\uc0dd\uc758 \uc77c\uc774 \ub418\uc5c8\ub294\uc9c0 \uc774\ud574\ud558\uae30 \uc5b4\ub835\ub2e4. \ub178\ub098\ub77c\ub97c \ub5a0\ub09c \ub4a4 \uacf5\uc790\ub294 \uc81c\uc790\ub4e4\uacfc \uc5ec\ub7ec \ub098\ub77c\ub97c \ub2e4\ub154\ub2e4. \uc790\uc2e0\uc758 \uc0dd\uac01\uc744 \ubc1b\uc544\ub4e4\uc77c \ud1b5\uce58\uc790\uc640 \uc790\ub9ac\ub97c \ucc3e\ub294 \uc5ec\uc815\uc774\uc5c8\uc9c0\ub9cc \uacc4\uc18d \ud658\uc601\ubc1b\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc815\uce58\uc801 \uc870\uac74\uacfc \uc0ac\ub78c\ub4e4\uc758 \uc774\ud574\uad00\uacc4\ub294 \uc774\uc0c1\uacfc \ub2e4\ub974\uac8c \uc6c0\uc9c1\uc600\ub2e4. \uc774\ub3d9\uc5d0\ub294 \uae30\ub300\ubfd0 \uc544\ub2c8\ub77c \uace4\ub780\uacfc \uc2e4\ub9dd\ub3c4 \uc788\uc5c8\ub2e4. \uc5ec\ud589\uc744 \ud588\ub2e4\ub294 \uc0ac\uc2e4 \uc790\uccb4\ubcf4\ub2e4 \ub73b\uc774 \ubc1b\uc544\ub4e4\uc5ec\uc9c0\uc9c0 \uc54a\uc744 \ub54c \uc5b4\ub5bb\uac8c \uc0b4\uc544\uac14\ub294\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \uacf5\uc790\uc640 \uc81c\uc790\ub4e4\uc758 \uad00\uacc4, \uc9c8\ubb38\uacfc \ub300\ub2f5\ub3c4 \uadf8\ub7f0 \uc2dc\uac04 \uc548\uc5d0 \uc788\uc5c8\ub2e4. \ud6d7\ub0a0\uc758 \ud070 \uba85\uc131\uc774 \ub2f9\ub300\uc758 \uc548\uc815\ub41c \uc131\uacf5\uc744 \uadf8\ub300\ub85c \ub73b\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc744 \uae30\uc5b5\ud560 \uc218 \uc788\ub2e4. \u300e\ub17c\uc5b4\u300f\ub294 \uacf5\uc790\uac00 \uc790\uc2e0\uc758 \ucca0\ud559\uc744 \ucc98\uc74c\ubd80\ud130 \ub05d\uae4c\uc9c0 \uccb4\uacc4\uc801\uc73c\ub85c \uc801\uc5b4 \ucd9c\ud310\ud55c \ucc45\uc774 \uc544\ub2c8\ub2e4. \uacf5\uc790\uc640 \uc81c\uc790\ub4e4\uc758 \ub9d0\uacfc \ud589\ub3d9\uc5d0 \uad00\ud55c \uc804\uc2b9\uc774 \ud6c4\ub300\uc5d0 \ubaa8\uc774\uace0 \uc815\ub9ac\ub41c \uc790\ub8cc\ub2e4. \uc6b0\ub9ac\uac00 \uc77d\ub294 \ubaa9\uc18c\ub9ac\uc5d0\ub294 \uc804\ub2ec\uacfc \ud3b8\uc9d1\uc758 \uc2dc\uac04\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uadf8\ub798\uc11c \ud55c \uad6c\uc808\uc744 \uc5ed\uc0ac \uc18d \uc5b4\ub290 \ub0a0\uc758 \ubc1c\uc5b8\uacfc \uc644\uc804\ud788 \uac19\uc740 \ub179\ucde8\ub85c \ubcf4\uae30\ub294 \uc5b4\ub835\ub2e4. \uadf8\ub807\ub2e4\uace0 \uac00\ub974\uce68\uc758 \uc758\ubbf8\uac00 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uc9c8\ubb38\uc5d0 \uc5b4\ub5a4 \ub2f5\uc774 \ub193\uc600\ub294\uc9c0 \uc0b4\ud53c\uba74, \ub204\uad6c\uc5d0\uac8c\ub098 \uac19\uc740 \ubb38\uc7a5 \ud558\ub098\ub97c \uac74\ub124\uae30\ubcf4\ub2e4 \uad00\uacc4\uc640 \uc0c1\ud669\uc744 \uc0dd\uac01\ud558\ub294 \uc77d\uae30\uac00 \uac00\ub2a5\ud574\uc9c4\ub2e4. \uc704\uc815\ud3b8\uc5d0\ub294 \uc5f4\ub2e4\uc12f\uc5d0 \ubc30\uc6c0\uc5d0 \ub73b\uc744 \ub450\uace0, \uc11c\ub978\uc5d0 \uc11c\uace0, \ub9c8\ud754\uc5d0 \ubbf8\ud639\ub418\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc2dd\uc758 \uc0dd\uc560 \ud68c\uace0\uac00 \ub098\uc628\ub2e4. \uc270\uacfc \uc608\uc21c\uc744 \uac70\uccd0 \uc77c\ud754\uc5d0\ub294 \uc6d0\ud558\ub294 \ub300\ub85c \ud574\ub3c4 \uae30\uc900\uc744 \ub118\uc9c0 \uc54a\ub294 \uacbd\uc9c0\uc5d0 \uc774\ub974\ub800\ub2e4\uace0 \uc804\ud55c\ub2e4. \ubc30\uc6b0\uace0 \ub2e4\ub4ec\ub294 \uae34 \uc2dc\uac04\uc744 \ub3cc\uc544\ubcf4\ub294 \ud615\uc2dd\uc774\ub2e4. \uc774\uac83\uc744 \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uac19\uc740 \ub098\uc774\uc5d0 \ub611\uac19\uc774 \ub2ec\uc131\ud574\uc57c \ud55c\ub2e4\ub294 \uaddc\uce59\uc73c\ub85c \ubc14\uafb8\uba74 \ubb38\uc7a5\uc758 \ubc29\ud5a5\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ub0a8\uc758 \uc18d\ub3c4\ub97c \ud3c9\uac00\ud558\ub294 \ub370 \uc4f0\uae30\ubcf4\ub2e4, \uc9c0\uc2dd\uacfc \ubab8\uc5d0 \ubc34 \ud589\ub3d9\uc774 \uac00\uae4c\uc6cc\uc9c0\ub824\uba74 \uc2dc\uac04\uc774 \ud544\uc694\ud558\ub2e4\ub294 \ub73b\uc73c\ub85c \uc77d\uc5b4 \ubcfc \uc218 \uc788\ub2e4. \uc775\uc219\ud55c \ub9d0\ub3c4 \uc6d0\ub798\uc758 \ud68c\uace0 \ud615\uc2dd \uc548\uc5d0 \ub193\uc73c\uba74 \uc870\uae08 \ubd80\ub4dc\ub7fd\uac8c \ub2e4\uac00\uc628\ub2e4. \u300e\ub17c\uc5b4\u300f\uc5d0\uc11c\ub294 \ubc30\uc6b0\ub294 \uc77c\uacfc \uc0dd\uac01\ud558\ub294 \uc77c\uc744 \ud568\uaed8 \uac15\uc870\ud55c\ub2e4. \uc815\ubcf4\ub97c \ub9ce\uc774 \uc5bb\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ud310\ub2e8\uc774 \uc88b\uc544\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uace0, \uc790\ub8cc \uc5c6\uc774 \uc790\uae30 \uc0dd\uac01\ub9cc \ubc18\ubcf5\ud558\ub294 \uac83\ub3c4 \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4. \ubc30\uc6b4 \uac83\uc744 \uc790\uae30 \uacbd\ud5d8\uacfc \ud310\ub2e8 \uc18d\uc5d0\uc11c \ub2e4\uc2dc \uc0b4\ud53c\ub294 \uc655\ubcf5\uc774 \ud544\uc694\ud558\ub2e4. \uc624\ub298\uc758 \ub3c5\uc790\uc5d0\uac8c\ub3c4 \ub0af\uc124\uc9c0 \uc54a\uc740 \ubb38\uc81c\ub2e4. \ucc45\uc5d0\uc11c \ub9c8\uc74c\uc5d0 \ub4dc\ub294 \uad6c\uc808\uc744 \ucc3e\uc558\uc744 \ub54c \uadf8\uac83\uc744 \uc678\uc6b0\ub294 \ub370\uc11c \uba48\ucd94\uc9c0 \uc54a\uace0 \uc5b4\ub5a4 \uc0c1\ud669\uc5d0 \ub9de\uc73c\uba70 \uc5b4\ub5a4 \uacbd\uc6b0\uc5d0\ub294 \uc124\uba85\uc774 \ub354 \ud544\uc694\ud55c\uc9c0 \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub2e4. \uc774\ub294 \uacf5\uc790\uc758 \uc2e4\uc81c \ub300\ud654\ub97c \uadf8\ub300\ub85c \uc778\uc6a9\ud55c \uc608\uac00 \uc544\ub2c8\ub77c \uac00\ub974\uce68\uc744 \ud604\uc7ac\uc758 \uc77d\uae30\uc5d0 \uc5f0\uacb0\ud574 \ubcf4\ub294 \ubc29\ubc95\uc774\ub2e4. \uc778\uc774\ub77c\ub294 \ub9d0\uc740 \ubc88\uc5ed \ud55c \ub2e8\uc5b4\ub85c \ubaa8\ub450 \ub2f4\uae30 \uc5b4\ub835\uc9c0\ub9cc \uc0ac\ub78c\uc744 \ub300\ud558\ub294 \ud0dc\ub3c4\ub97c \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ub610 \uc790\uc2e0\uc774 \uc6d0\ud558\uc9c0 \uc54a\ub294 \uc77c\uc744 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uac15\uc694\ud558\uc9c0 \ub9d0\ub77c\ub294 \uac00\ub974\uce68\uc740 \uc0c1\ub300\uc758 \uc785\uc7a5\uc744 \ub3cc\uc544\ubcf4\ub294 \ucd9c\ubc1c\uc810\uc774 \ub41c\ub2e4. \ub73b\uc744 \uc54c\uace0 \uc788\ub2e4\ub294 \uac83\uacfc \ubd88\ud3b8\ud55c \uc21c\uac04\uc5d0 \uc2e4\uc81c\ub85c \uadf8\ub807\uac8c \ud589\ub3d9\ud558\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uac00\ub839 \ub2e4\ub978 \uc0ac\ub78c\uc774 \ub9d0\uc744 \ub04a\uc744 \ub54c \ubd88\ucf8c\ud558\ub2e4\uba74 \ub098\ub3c4 \uc0c1\ub300\uc758 \ub9d0\uc744 \ub05d\uae4c\uc9c0 \ub4e3\ub294\uc9c0 \ub3cc\uc544\ubcfc \uc218 \uc788\ub2e4. \uc774\ub7f0 \uc791\uc740 \uc608\uac00 \uc778\uc774\ub098 \uc11c\uc758 \ubaa8\ub4e0 \ub73b\uc744 \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub2e4\ub9cc \ud070 \ucca0\ud559\uc801 \uc774\ub984\uc744 \uc77c\uc0c1\uc758 \uad6c\uccb4\uc801\uc778 \uad00\uacc4\uc5d0 \uc5f0\uacb0\ud558\ub294 \uccab\uac78\uc74c\uc740 \ub420 \uc218 \uc788\ub2e4. \uad00\uacc4\uc758 \uc870\ud654\uac00 \uc5b8\uc81c\ub098 \ud798\uc5c6\ub294 \uc0ac\ub78c\ub9cc \ucc38\uc544\uc57c \ud55c\ub2e4\ub294 \ub73b\uc73c\ub85c \uad73\uc5b4\uc838\uc11c\ub3c4 \uc548 \ub41c\ub2e4. \ub9d0\ub144\uc5d0 \ub178\ub098\ub77c\ub85c \ub3cc\uc544\uc628 \uacf5\uc790\ub294 \uac00\ub974\uce68\uacfc \uc61b \uc790\ub8cc\ub97c \ub2e4\ub8e8\ub294 \uc77c\uc5d0 \ud798\uc744 \uc3df\uc740 \uc778\ubb3c\ub85c \uc804\ud574\uc9c4\ub2e4. \uc624\ub298 \ub0a8\uc740 \uba85\uc131\ub9cc \ubcf4\uace0 \uc0dd\uc560 \uc804\uccb4\uac00 \uc21c\ud0c4\ud588\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \ud604\uc2e4\uacfc \ubd80\ub52a\uce58\ub358 \uc2dc\uac04\uc744 \ub193\uce5c\ub2e4. \uc815\uce58\uc5d0\uc11c \ub73b\uc744 \ubaa8\ub450 \ud3bc\uce58\uc9c0 \ubabb\ud55c \uc0b6\uacfc \uc624\ub798 \uc804\ud574\uc9c4 \uac00\ub974\uce68\uc774 \ud55c \uc0ac\ub78c \uc548\uc5d0 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 1910\ub144\uc5d0 \ucd9c\ud310\ub41c \u300eThe Sayings of Confucius\u300f\uc758 \uc2e4\uc81c \ud45c\uc9c0\ub2e4. \uc778\ubb3c \uadf8\ub9bc\uc740 \ud6c4\ub300 \ucd9c\ud310\ubb3c\uc774 \ud45c\ud604\ud55c \uacf5\uc790\uc758 \ubaa8\uc2b5\uc774\uba70, \uacf5\uc790\uac00 \uc0b4\ub358 \uc2dc\ub300\uc5d0 \uadf8\ub9b0 \ucd08\uc0c1\uc740 \uc544\ub2c8\ub2e4. \uacf5\uc790\ub97c \uc624\ub798\ub41c \uba85\ub839\uc758 \ubaa9\uc18c\ub9ac\ub85c\ub9cc \ub9cc\ub098\uae30\ubcf4\ub2e4, \ubc30\uc6b4 \uac83\uc744 \uc0b6\uc5d0 \uc775\ud788\ub824\uba74 \uc65c \uae34 \uc2dc\uac04\uc774 \ud544\uc694\ud55c\uc9c0 \ubb3b\ub294 \uc0ac\ub78c\uc73c\ub85c \uc77d\uc5b4 \ubcf4\uc790. \uc9c0\uae08 \ubc30\uc6b0\ub294 \uac83\uc774 \uc544\uc9c1 \uc788\ub2e4\uba74 \uadf8 \uc9c8\ubb38\uc744 \uc2dc\uc791\ud560 \uc790\ub9ac\ub3c4 \ub0a8\uc544 \uc788\ub2e4."}, {"id": "crystal-palace-greenhouse-and-prefabrication", "title": "\uc218\uc815\uad81 \u2014 \uc628\uc2e4\uc758 \uc0dd\uac01\uc73c\ub85c \uac70\ub300\ud55c \uc804\uc2dc\uc7a5\uc744 \ub9cc\ub4e4\ub2e4", "summary": "\uc870\uc9c0\ud504 \ud329\uc2a4\ud134\uc758 \uc628\uc2e4 \uacbd\ud5d8\uacfc \uc218\uc815\uad81\uc758 \uac74\uc124 \uacfc\uc815\uc744 \uc2e4\uc81c \uc61b \ub3c4\ud310\uacfc \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uac74\ucd95", "categories": ["arts"], "url": "stories/crystal-palace-greenhouse-and-prefabrication/index.html", "image": "../media/crystal-palace-greenhouse-and-prefabrication.jpg", "alt": "\uae38\uac8c \ubc18\ubcf5\ub418\ub294 \ucca0\uacfc \uc720\ub9ac, \ub192\uc740 \uac00\ub85c \uacf5\uac04\uc774 \ubcf4\uc774\ub294 \uc218\uc815\uad81\uc758 \uc61b \uc678\uad00 \uadf8\ub9bc", "text": "\uc218\uc815\uad81 \u2014 \uc628\uc2e4\uc758 \uc0dd\uac01\uc73c\ub85c \uac70\ub300\ud55c \uc804\uc2dc\uc7a5\uc744 \ub9cc\ub4e4\ub2e4 1851\ub144 \ub7f0\ub358\uc5d0\uc11c \uc720\ub9ac\uc640 \ucca0, \ubc18\ubcf5\ub418\ub294 \ubd80\ud488\uc774 \ub9cc\ub09c \uac74\ucd95 \uc870\uc9c0\ud504 \ud329\uc2a4\ud134\uc758 \uc628\uc2e4 \uacbd\ud5d8\uacfc \uc218\uc815\uad81\uc758 \uac74\uc124 \uacfc\uc815\uc744 \uc2e4\uc81c \uc61b \ub3c4\ud310\uacfc \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uac74\ucd95 \ubb38\ud654\uc640 \uc608\uc220 \uac70\ub300\ud55c \uc804\uc2dc\uc7a5\uc744 \uc138\uc6cc\uc57c \ud558\ub294\ub370 \uc2dc\uac04\uc774 \ub109\ub109\ud558\uc9c0 \uc54a\ub2e4. \ub3cc\uc744 \ud55c \uc7a5\uc529 \uc313\uc544 \ub450\uaebc\uc6b4 \ubcbd\uc744 \ub9cc\ub4dc\ub294 \ubc29\uc2dd\uc73c\ub85c \uac00\ub2a5\ud560\uae4c. 1851\ub144 \ub7f0\ub358 \ub9cc\uad6d\ubc15\ub78c\ud68c\ub97c \uc704\ud55c \uac74\ubb3c\uc5d0\uc11c \uc870\uc9c0\ud504 \ud329\uc2a4\ud134\uc774 \uac00\uc838\uc628 \uc911\uc694\ud55c \uacbd\ud5d8\uc740 \uad81\uc804\ubcf4\ub2e4 \uc628\uc2e4\uc5d0 \uac00\uae4c\uc6e0\ub2e4. \ucca0\uacfc \uc720\ub9ac\ub85c \uc774\ub8e8\uc5b4\uc9c4 \uc218\uc815\uad81\uc740 \ud06c\uae30\ub9cc\uc73c\ub85c \ub180\ub77c\uc6b4 \uac74\ubb3c\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uac19\uc740 \ubd80\ud488\uc744 \ubc18\ubcf5\ud558\uace0 \uc9e7\uc740 \uc2dc\uac04 \uc548\uc5d0 \uc870\ub9bd\ud560 \uc218 \uc788\ub3c4\ub85d \uc0dd\uac01\ud55c \uacfc\uc815\ub3c4 \uc911\uc694\ud588\ub2e4. \ub2f9\uc2dc\uc758 \u300e\uc218\uc815\uad81: \uac74\ucd95\uc758 \uc5ed\uc0ac\uc640 \uac74\uc124\uc758 \uacbd\uc774\u300f\ub97c \ubc14\ud0d5\uc73c\ub85c \uadf8 \uacfc\uc815\uc744 \uc77d\ub294\ub2e4. \ub9cc\uad6d\ubc15\ub78c\ud68c\uc5d0\ub294 \ub9ce\uc740 \ubb3c\uac74\uacfc \uc0ac\ub78c\uc774 \ub4e4\uc5b4\uac08 \ub113\uc740 \uc2e4\ub0b4\uac00 \ud544\uc694\ud588\ub2e4. \uc804\uc2dc\ud488\uc744 \ubcf4\uace0 \uc774\ub3d9\ud560 \ube5b\uacfc \ud1b5\ub85c\uac00 \uc788\uc5b4\uc57c \ud588\uace0, \uc77c\uc815 \uc548\uc5d0 \uc9c0\uc5b4\uc57c \ud588\ub2e4. \uc601\uc6d0\ud788 \ub0a8\uae38 \uc655\uc2e4 \uac74\ubb3c\uacfc\ub294 \ub2e4\ub978 \uacfc\uc81c\uac00 \uc788\uc5c8\ub2e4. \uc784\uc2dc\uc801\uc778 \ubaa9\uc801\uc5d0 \ub9de\ub294 \uac74\ucd95\uc774\ub77c\ub294 \uc870\uac74\uc774 \uc911\uc694\ud574\uc9c4 \uac83\uc774\ub2e4. \uc5ec\ub7ec \uc124\uacc4\uc640 \ube44\uc6a9\uc744 \ube44\uad50\ud558\ub294 \uacfc\uc815\uc5d0\uc11c \uac74\ubb3c\uc744 \uc5b4\ub5a4 \ubaa8\uc591\uc73c\ub85c \ub9cc\ub4e4\uc9c0\ubfd0 \uc544\ub2c8\ub77c \uc5b4\ub5bb\uac8c \uc2e4\uc81c\ub85c \uc9c0\uc744\uc9c0\uac00 \ud568\uaed8 \ub17c\uc758\ub418\uc5c8\ub2e4. \uc6c5\uc7a5\ud55c \uc815\uba74\uc744 \uadf8\ub9ac\ub294 \uac83\ub9cc\uc73c\ub85c \uc0ac\uc5c5\uc774 \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc81c\uc791\uacfc \uc6b4\uc1a1, \uc124\uce58\uc758 \uc21c\uc11c\ub97c \uac10\ub2f9\ud560 \uc218 \uc788\ub294 \uacc4\ud68d\uc774\uc5b4\uc57c \ud55c\ub2e4. \uac74\ucd95\uc758 \uc774\uc57c\uae30\ub294 \ub3c4\uba74 \ub4a4\uc758 \uacf5\uc7a5\uacfc \ud604\uc7a5\uc73c\ub85c \ub113\uc5b4\uc9c4\ub2e4. \ud329\uc2a4\ud134\uc740 \uc720\ub9ac\ub85c \ub41c \uc2dd\ubb3c \uc7ac\ubc30 \uacf5\uac04\uc744 \ub9cc\ub4e4\uace0 \uac1c\uc120\ud574 \uc628 \uc0ac\ub78c\uc774\uc5c8\ub2e4. \ub450\uaecd\uace0 \ubb34\uac70\uc6b4 \uad6c\uc870\ub294 \uc2e4\ub0b4\ub97c \uc5b4\ub461\uac8c \ud558\uace0, \uc9c0\ubd95\uacfc \uc720\ub9ac \uc0ac\uc774\uc758 \ud2c8\uc73c\ub85c \ube44\uac00 \ub4e4\uae30\ub3c4 \ud588\ub2e4. \uc2dd\ubb3c\uc744 \uc704\ud574 \ube5b\uacfc \ubb3c\uc744 \ub2e4\ub8e8\ub294 \uc2e4\ubb34\uc801\uc778 \ubb38\uc81c\uac00 \uc0c8\ub85c\uc6b4 \uad6c\uc870\ub97c \uc0dd\uac01\ud558\uac8c \ud588\ub2e4. \uc790\ub8cc\uc5d0\ub294 \ud329\uc2a4\ud134 \uc790\uc2e0\uc774 \uc774\ub7f0 \uacbd\ud5d8\uc744 \uc124\uba85\ud558\ub294 \ub300\ubaa9\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uc218\uc815\uad81\uc758 \uc544\uc774\ub514\uc5b4\uac00 \uc544\ubb34 \ubc30\uacbd \uc5c6\uc774 \ud55c\uc21c\uac04\uc5d0 \uc644\uc131\ub418\uc5c8\ub2e4\uace0 \ubcf4\uae30\ub294 \uc5b4\ub835\ub2e4. \uc791\uc740 \uac74\ucd95\uc5d0\uc11c \uc5ec\ub7ec \ud574\uc5d0 \uac78\uccd0 \ub2e4\ub8ec \ubb38\uc81c\uac00 \ud6e8\uc52c \ud070 \uc804\uc2dc\uc7a5\uc73c\ub85c \uc62e\uaca8 \uac14\ub2e4. \ub2e4\ub978 \uc6a9\ub3c4\uc758 \uacbd\ud5d8\uc744 \uc0c8 \ubb38\uc81c\uc5d0 \uc801\uc6a9\ud558\ub294 \ub2a5\ub825\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \uc720\ub9ac \uc9c0\ubd95\uc740 \ube5b\uc744 \ub4e4\uc774\uc9c0\ub9cc \uadf8 \uc704\uc758 \ube57\ubb3c\ub3c4 \ucc98\ub9ac\ud574\uc57c \ud55c\ub2e4. \uac00\ubcbc\uc6b4 \ud2c0\uc744 \uc4f0\uba74 \uc88b\uc744 \uac83 \uac19\uc544\ub3c4 \uc57d\ud574\uc838\uc11c\ub294 \uc548 \ub418\uace0, \ubb3c\uc774 \uc0c8\uba74 \uc804\uc2dc\ud488\uacfc \uad00\ub78c\uac1d\uc774 \uace4\ub780\ud574\uc9c4\ub2e4. \uc544\ub984\ub2e4\uc6b4 \ud22c\uba85\ud568\uc758 \ub4a4\uc5d0\ub294 \ud648\uacfc \uc774\uc74c, \ubc30\uc218\uc640 \uc9c0\uc9c0\ub77c\ub294 \uad6c\uccb4\uc801\uc778 \uc77c\uc774 \uc788\ub2e4. \uc774\uac83\uc740 \uac74\ucd95\uc744 \uae30\uc220 \uc124\uba85\uc73c\ub85c\ub9cc \uc904\uc774\uc790\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uc624\ud788\ub824 \ucee4\ub2e4\ub780 \uacf5\uac04\uc744 \ud3b8\ud558\uac8c \uacbd\ud5d8\ud560 \uc218 \uc788\ub294 \uc774\uc720\ub97c \ubcf4\uac8c \ud55c\ub2e4. \ucc9c\uc7a5\uc774 \ubc1d\ub2e4\ub294 \uac10\ud0c4\uacfc \ubc14\ub2e5\uc774 \uc816\uc9c0 \uc54a\ub294 \uc77c\uc740 \uac19\uc740 \uc124\uacc4 \uc548\uc5d0\uc11c \ud574\uacb0\ud574\uc57c \ud588\ub2e4. \ube5b\ub9cc \uc0dd\uac01\ud558\uac70\ub098 \ubb3c\ub9cc \uc0dd\uac01\ud574\uc11c\ub294 \uadf8 \uacf5\uac04\uc774 \uc720\uc9c0\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc218\uc815\uad81\uc758 \uc911\uc694\ud55c \ud2b9\uc9d5\uc740 \ubc18\ubcf5\ub418\ub294 \ub2e8\uc704\uc600\ub2e4. \uae30\ub465\uacfc \ubcf4, \uc720\ub9ac\uc640 \ud2c0\uc744 \uc77c\uc815\ud55c \uaddc\uaca9\uc73c\ub85c \ub9cc\ub4e4\uace0 \uc5f0\uacb0\ud558\uba74 \ub9e4\ubc88 \uc804\ud600 \ub2e4\ub978 \uc870\uac01\uc744 \ud604\uc7a5\uc5d0\uc11c \ub9de\ucd94\ub294 \uc77c\uc744 \uc904\uc77c \uc218 \uc788\ub2e4. \uaddc\ubaa8\ub97c \ud0a4\uc6b0\ub294 \ubc29\ubc95\uc774 \ud558\ub098\uc758 \uac70\ub300\ud55c \ub369\uc5b4\ub9ac\ub97c \ub9cc\ub4dc\ub294 \ub370\uc5d0\ub9cc \uc788\uc9c0 \uc54a\uc558\ub358 \uac83\uc774\ub2e4. \uc624\ub298\uc758 \ub208\uc73c\ub85c\ub294 \ub300\ub7c9\uc0dd\uc0b0\uacfc \uc870\ub9bd\uc774 \ub2f9\uc5f0\ud574 \ubcf4\uc774\uc9c0\ub9cc, \uadf8 \ubd80\ud488\ub4e4\uc774 \uac74\ucd95 \uc804\uccb4\uc758 \ub9ac\ub4ec\uc744 \ub9cc\ub4e0\ub2e4\ub294 \uc0dd\uac01\uc740 \uc5ec\uc804\ud788 \ud765\ubbf8\ub86d\ub2e4. \ubc18\ubcf5\uc740 \ub2e8\uc870\ub85c\uc6c0\uc77c \uc218\ub3c4 \uc788\uc9c0\ub9cc \ubc1d\uace0 \uae34 \uacf5\uac04\uc744 \ub9cc\ub4e4 \ud798\uc774 \ub418\uae30\ub3c4 \ud55c\ub2e4. \ud55c \ub2e8\uc704\uac00 \uc81c\uc790\ub9ac\ub97c \ucc3e\uc744 \ub54c \ub9ce\uc740 \ub2e8\uc704\uac00 \ud568\uaed8 \uc774\ud574\ub418\ub294 \uc9c8\uc11c\uac00 \uc0dd\uae34\ub2e4. \uc720\ub9ac\ub97c \uc6d0\ud558\ub294 \ud06c\uae30\ub85c \uc544\ubb34 \uc81c\ud55c \uc5c6\uc774 \ub9cc\ub4e4 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2e4\uc81c \uc81c\uc870\uac00 \uac00\ub2a5\ud55c \ud310\uc758 \ud06c\uae30\uc640 \ud2c0\uc758 \ubc30\uce58, \uc790\uc7ac\uc758 \uacf5\uae09\uc774 \uac74\ubb3c\uc758 \ubaa8\uc591\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uac74\ucd95\uac00\ub294 \uadf8\ub9bc\uc744 \uadf8\ub9ac\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc740 \uadf8\ub300\ub85c\ub9cc \ub9cc\ub4e4\uba74 \ub41c\ub2e4\ub294 \ubd84\uc5c5\uc758 \uc0c1\uc0c1\ubcf4\ub2e4 \ud6e8\uc52c \uae34 \ub300\ud654\uac00 \ud544\uc694\ud588\ub2e4. \uc790\ub8cc\uac00 \ucca0\uacfc \uc720\ub9ac\uc758 \uc0dd\uc0b0, \uc124\uce58 \uc7a5\ube44\uc640 \uc791\uc5c5 \uc21c\uc11c\ub97c \uc790\uc138\ud788 \ub2e4\ub8e8\ub294 \uc774\uc720\ub3c4 \uc5ec\uae30\uc5d0 \uc788\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc81c\uc870\uc5c5\uc758 \ub2a5\ub825\uc774 \uad00\ub78c\uac1d\uc774 \ubcf4\uac8c \ub420 \uc2e4\ub0b4\uc758 \uc870\uac74\uc744 \uc815\ud55c\ub2e4. \uc644\uc131\ub41c \uac74\ubb3c\uc758 \ub2e8\uc21c\ud568\uc740 \uacfc\uc815\uc774 \ub2e8\uc21c\ud588\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub77c, \ub9ce\uc740 \uc870\uac74\uc744 \ud558\ub098\uc758 \ubc18\ubcf5 \uac00\ub2a5\ud55c \ubc29\uc2dd\uc73c\ub85c \uc815\ub9ac\ud588\ub2e4\ub294 \uacb0\uacfc\ub2e4. \uac74\uc124 \ubd80\uc9c0\uc758 \ud070 \ub098\ubb34\ub4e4\uc744 \ub458\ub7ec\uc2fc \ubb38\uc81c\ub3c4 \uc788\uc5c8\ub2e4. \uc218\uc815\uad81\uc758 \ub192\uac8c \uc19f\uc740 \uac00\ub85c \uacf5\uac04\uc740 \uadf8 \ub098\ubb34\ub4e4\uc744 \uc548\uc5d0 \ub450\ub294 \ubc29\uc2dd\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uac74\ubb3c\uc744 \uc9d3\uae30 \uc804\uc5d0 \uadf8\uacf3\uc5d0 \uc774\ubbf8 \uc788\ub358 \uac83\uc744 \ubb34\uc870\uac74 \uc5c6\uc560\uae30\ubcf4\ub2e4 \uc124\uacc4 \uc548\uc5d0 \ud3ec\ud568\ud55c \uac83\uc774\ub2e4. \uc720\ub9ac\uc758 \uac70\ub300\ud55c \uacf5\uac04\uc5d0\uc11c \uc0b4\uc544 \uc788\ub294 \ub098\ubb34\uac00 \ud568\uaed8 \ubcf4\uc774\ub294 \ud48d\uacbd\uc774 \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4. \uc774 \uc7a5\uba74\uc740 \uae30\uc220\uc774 \uc790\uc5f0\uc744 \uc644\uc804\ud788 \uc815\ubcf5\ud588\ub2e4\ub294 \uc120\uc5b8\uacfc\ub294 \uc870\uae08 \ub2e4\ub974\uac8c \uc77d\uc744 \uc218 \uc788\ub2e4. \uc628\uc2e4\uc758 \uacbd\ud5d8\uc5d0\uc11c \ucd9c\ubc1c\ud55c \uac74\ubb3c \uc548\uc5d0 \ub2e4\uc2dc \ub098\ubb34\uac00 \ub4e4\uc5b4\uc628\ub2e4. \ubb3c\ub860 \uadf8 \ud55c \uc120\ud0dd\ub9cc\uc73c\ub85c \uc0ac\uc5c5 \uc804\uccb4\uac00 \uc624\ub298\uc758 \ud658\uacbd \uae30\uc900\uc5d0 \ub9de\uc558\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \ub0a8\uc544 \uc788\ub358 \uc870\uac74\uc774 \uc124\uacc4\ub97c \ubc14\uafb8\ub294 \ud55c \uc0ac\ub840\ub2e4. \uc774 \uae00\uc758 \uadf8\ub9bc\uc740 \ub2f9\uc2dc \uac74\ucd95\uc11c\uc5d0 \uc2e4\ub9b0 \uc218\uc815\uad81\uc758 \uc678\uad00 \ub3c4\ud310\uc774\ub2e4. \uc2e4\uc81c \uc0ac\uc9c4\uc774\ub098 AI\uac00 \ub9cc\ub4e0 \ubcf5\uc6d0\ub3c4\uac00 \uc544\ub2c8\ub2e4. \uae38\uac8c \ubc18\ubcf5\ub418\ub294 \uae30\ub465\uacfc \uc720\ub9ac, \ub192\uc774\uac00 \ub2ec\ub77c\uc9c0\ub294 \ubd80\ubd84\uc744 \ub208\uc73c\ub85c \ub530\ub77c\uac00\uba74 \uae00\ub85c \uc77d\ub358 \ub2e8\uc704\uc640 \uaddc\ubaa8\uc758 \uad00\uacc4\uac00 \uc870\uae08 \ub354 \uc27d\uac8c \ub290\uaef4\uc9c4\ub2e4. \ub3d9\uc2dc\uc5d0 \uc774\ub7f0 \ucc45\uc740 \ub2f9\ub300\uc758 \uc131\ucde8\ub97c \ud06c\uac8c \uae30\ub150\ud558\ub294 \uc790\ub8cc\uc774\uae30\ub3c4 \ud558\ub2e4. \uc800\uc790\uc758 \uac10\ud0c4\uc744 \uadf8\ub300\ub85c \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \uacbd\ud5d8\uc73c\ub85c \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc644\uacf5\uc758 \uc601\uad11\uacfc \ud604\uc7a5\uc758 \ub178\ub3d9, \ubc15\ub78c\ud68c\uac00 \ubcf4\uc5ec \uc8fc\ub824 \ud55c \uc138\uacc4 \uc0ac\uc774\uc5d0\ub294 \ub2e4\ub978 \uc9c8\ubb38\ub3c4 \uc788\uc744 \uc218 \uc788\ub2e4. \uc790\ub8cc\uc758 \uc2dc\uc120\uc744 \uc54c\uace0 \uc77d\uc73c\uba74 \ub3c4\ud310\uc774 \ub354 \ud48d\ubd80\ud574\uc9c4\ub2e4. \uc218\uc815\uad81\uc758 \uc774\uc57c\uae30\ub294 \uc720\ub9ac\ub85c \uc544\uc8fc \ud070 \uac74\ubb3c\uc744 \uc9c0\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc2dc\uac04\uc774 \ucd09\ubc15\ud560 \ub54c \uc5b4\ub5a4 \uacbd\ud5d8\uc744 \uac00\uc838\uc654\uace0, \ubd80\ud488\uc758 \ud06c\uae30\uc640 \ubb3c\uc758 \uae38\uc744 \uc5b4\ub5bb\uac8c \ud558\ub098\uc758 \uacf5\uac04\uc73c\ub85c \ubb36\uc5c8\ub294\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \ub208\uc5d0 \ub744\ub294 \uc544\ub984\ub2e4\uc6c0\uacfc \ubc18\ubcf5\ub418\ub294 \uc2e4\ubb34\uac00 \ud568\uaed8 \ub9cc\ub4e0 \uac74\ucd95\uc774\uc5c8\ub2e4. \uc61b \uadf8\ub9bc\uc758 \uae34 \ubcbd\uc744 \ub2e4\uc2dc \ubcf4\uc790. \ud558\ub098\ud558\ub098 \ub2e4\ub978 \uad81\uc804 \uc7a5\uc2dd \ub300\uc2e0 \uac19\uc740 \ub2e8\uc704\uac00 \uc774\uc5b4\uc9c4\ub2e4. \uadf8 \ubc18\ubcf5 \uc18d\uc5d0\ub294 \uc628\uc2e4\uc5d0\uc11c \uae30\ub978 \uac10\uac01\uacfc \uacf5\uc7a5\uc758 \uc0dd\uc0b0, \ud604\uc7a5\uc5d0\uc11c \uc870\ub9bd\ud55c \uc190\ub4e4\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uc2dd\ubb3c\uc744 \uc704\ud55c \uc791\uc740 \uacf5\uac04\uc758 \ubb38\uc81c\ub97c \ub05d\uae4c\uc9c0 \ub4e4\uc5ec\ub2e4\ubcf8 \uacbd\ud5d8\uc774 \uc0ac\ub78c\ub4e4\uc744 \uc704\ud55c \uac70\ub300\ud55c \uacf5\uac04\uc73c\ub85c \uc790\ub790\ub358 \uac83\uc774\ub2e4."}, {"id": "david-recamier-empty-space", "title": "\ub808\uce74\ubbf8\uc5d0 \ubd80\uc778\uc758 \ucd08\uc0c1 \u2014 \ube48 \uacf5\uac04\uc774 \uc0ac\ub78c\uc744 \ub3cb\ubcf4\uc774\uac8c \ud560 \ub54c", "summary": "\ub2e4\ube44\ub4dc\uc758 \ucd08\uc0c1\uc5d0\uc11c \uc790\uc138\uc640 \uac00\uad6c, \ub113\uac8c \ub0a8\uc740 \ubc30\uacbd\uc774 \ub9cc\ub4dc\ub294 \uc778\uc0c1\uc744 \uc2e4\uc81c \ub3c4\ud310\uacfc \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/david-recamier-empty-space/index.html", "image": "../media/david-recamier-empty-space.jpg", "alt": "\ub2e4\ube44\ub4dc\uc758 \ub808\uce74\ubbf8\uc5d0 \ubd80\uc778 \ucd08\uc0c1\uc744 \uc7ac\ud604\ud55c \uc61b \ub3c4\ud310. \ud770 \ub4dc\ub808\uc2a4\ub97c \uc785\uc740 \uc778\ubb3c\uc774 \uae34 \uc758\uc790\uc5d0 \uae30\ub300\uace0 \uc67c\ucabd\uc5d0 \ub4f1\uc794\ub300\uac00 \uc11c \uc788\uc2b5\ub2c8\ub2e4.", "text": "\ub808\uce74\ubbf8\uc5d0 \ubd80\uc778\uc758 \ucd08\uc0c1 \u2014 \ube48 \uacf5\uac04\uc774 \uc0ac\ub78c\uc744 \ub3cb\ubcf4\uc774\uac8c \ud560 \ub54c \ud770 \ub4dc\ub808\uc2a4\uc640 \uae34 \uc758\uc790, \ub05d\ub0b4 \uc644\uc131\ub418\uc9c0 \uc54a\uc740 \uadf8\ub9bc \ub2e4\ube44\ub4dc\uc758 \ucd08\uc0c1\uc5d0\uc11c \uc790\uc138\uc640 \uac00\uad6c, \ub113\uac8c \ub0a8\uc740 \ubc30\uacbd\uc774 \ub9cc\ub4dc\ub294 \uc778\uc0c1\uc744 \uc2e4\uc81c \ub3c4\ud310\uacfc \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \ucd08\uc0c1\ud654\ub77c\uba74 \uc778\ubb3c\uc758 \uc5bc\uad74\uc774 \uac00\uc7a5 \uc911\uc694\ud560 \uac83 \uac19\ub2e4. \uadf8\ub7f0\ub370 \ub2e4\ube44\ub4dc\uc758 \u3008\ub808\uce74\ubbf8\uc5d0 \ubd80\uc778\uc758 \ucd08\uc0c1\u3009\uc5d0\uc11c\ub294 \uc5bc\uad74\ubcf4\ub2e4 \uba3c\uc800 \uae38\uac8c \ub193\uc778 \uc758\uc790\uc640 \ud770\uc637, \ub113\uace0 \uc870\uc6a9\ud55c \ubc30\uacbd\uc774 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ubc29\uc744 \uac00\ub4dd \ucc44\uc6b8 \uc218\ub3c4 \uc788\uc5c8\uc744 \ubb3c\uac74\ub4e4\uc774 \ube60\uc838 \uc788\uc5b4\uc11c \uc624\ud788\ub824 \uc0ac\ub78c\uc774 \ub610\ub837\ud574 \ubcf4\uc778\ub2e4. \ubb34\uc5c7\uc744 \ub354 \uadf8\ub838\ub294\uc9c0\ubfd0 \uc544\ub2c8\ub77c \ubb34\uc5c7\uc774 \uc801\uac8c \ub193\uc600\ub294\uc9c0\ub3c4 \uc0b4\ud3b4\ubcf4\uc790. \uc774 \uadf8\ub9bc\uc740 \ub05d\ub0b4 \uc644\uc131\ub418\uc9c0 \uc54a\uc740 \uc791\ud488\uc73c\ub85c \uc804\ud574\uc9c4\ub2e4. \uadf8 \uc0ac\uc2e4\uc744 \uc54c\uace0 \ubcf4\uba74 \ube44\uc5b4 \uc788\ub294 \ub4ef\ud55c \ubd80\ubd84\uc744 \ub2e8\uc21c\ud788 \ubd80\uc871\ud55c \uc790\ub9ac\ub85c\ub9cc \uc77d\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \ub808\uce74\ubbf8\uc5d0 \ubd80\uc778\uc740 \uae34 \uc758\uc790 \uc704\uc5d0 \ubab8\uc744 \uae30\ub300\uace0 \uc788\ub2e4. \ubab8\uc774 \ubed7\uc740 \ubc29\ud5a5\uacfc \uace0\uac1c\uac00 \ub3cc\uc544\uc628 \ubc29\ud5a5\uc774 \ub2e4\ub974\ub2e4. \ubab8\uc758 \uae38\uace0 \ub290\uae0b\ud55c \ud750\ub984\uc744 \ub530\ub77c\uac00\ub2e4\uac00 \uc5bc\uad74\uc5d0\uc11c \ub2e4\uc2dc \uad00\ub78c\uc790 \ucabd\uc73c\ub85c \uc2dc\uc120\uc774 \ub3cc\uc544\uc628\ub2e4. \uac00\ub9cc\ud788 \uc549\uc544 \uc788\uc5b4\ub3c4 \ud654\uba74\uc5d0\ub294 \uc6c0\uc9c1\uc784\uc758 \ubc29\ud5a5\uc774 \uc0dd\uae34\ub2e4. \ubab8\uc744 \uc815\uba74\uc73c\ub85c \uc138\uc6b0\uace0 \uc5bc\uad74\uc744 \uac00\uc6b4\ub370 \ub454 \ucd08\uc0c1\uacfc \ube44\uad50\ud558\uba74 \ucc28\uc774\uac00 \ubd84\uba85\ud558\ub2e4. \uc6b0\ub9ac\ub294 \uc778\ubb3c\uc744 \uace7\uc7a5 \ub9c8\uc8fc\ubcf4\uae30\ubcf4\ub2e4 \uadf8\ub140\uac00 \ub193\uc778 \uacf5\uac04\uacfc \uc790\uc138\ub97c \uac70\uccd0 \uc5bc\uad74\uc5d0 \ub3c4\ucc29\ud55c\ub2e4. \uc774\uac83\uc744 \uc2e4\uc81c \ubaa8\ub378\uc758 \uc131\uaca9\uc774\ub098 \ub9c8\uc74c \uc0c1\ud0dc\uc5d0 \ub300\ud55c \uc99d\uac70\ub85c \ub2e8\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8\ub9bc\uc774 \uad00\ub78c\uc790\ub97c \ub9cc\ub098\uac8c \ud558\ub294 \ubc29\uc2dd\uc73c\ub85c \ubcf4\uba74 \ucda9\ubd84\ud558\ub2e4. \ud770 \ub4dc\ub808\uc2a4\ub294 \uc778\ubb3c\uc758 \uc0c1\uccb4\uc640 \ub2e4\ub9ac, \uc758\uc790\uc758 \uac00\uc7a5\uc790\ub9ac\ub85c \uae38\uac8c \uc774\uc5b4\uc9c4\ub2e4. \ubc30\uacbd\uc774 \uc0c1\ub300\uc801\uc73c\ub85c \uc5b4\ub461\uace0 \ucc28\ubd84\ud574\uc11c \ubc1d\uc740 \ucc9c\uc758 \uba74\uc774 \ub354 \uc27d\uac8c \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc5bc\uad74\uc774 \ucc28\uc9c0\ud558\ub294 \ud06c\uae30\ub294 \uc791\uc9c0\ub9cc \uadf8\ucabd\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \ubc1d\uc740 \ud750\ub984\uc740 \ud6e8\uc52c \ub113\ub2e4. \uc637\uac10\uc774 \uc811\ud788\uace0 \ubc14\ub2e5 \ucabd\uc73c\ub85c \ub0b4\ub824\uc624\ub294 \ubd80\ubd84\uc744 \ucc9c\ucc9c\ud788 \ubcf4\uc790. \uac19\uc740 \ud770\uc0c9 \uc548\uc5d0\ub3c4 \uadf8\ub298\uacfc \ube5b\uc758 \ucc28\uc774\uac00 \uc788\ub2e4. \ube5b\ub098\ub294 \uc7a5\uc2e0\uad6c\ub97c \ub9ce\uc774 \uadf8\ub9ac\uc9c0 \uc54a\uc544\ub3c4 \ubc1d\uc740 \uba74\uacfc \uc8fc\ubcc0 \uc0c9\uc758 \ub300\ube44\ub9cc\uc73c\ub85c \uc778\ubb3c\uc758 \uc790\ub9ac\ub97c \uac15\uc870\ud560 \uc218 \uc788\ub2e4. \uc801\uc740 \uc0c9\uc774 \uace7 \ub2e8\uc21c\ud55c \ud6a8\uacfc\ub9cc \ub9cc\ub4e0\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc778\ubb3c\uc774 \uae30\ub300\ub294 \uac00\uad6c\ub294 \uc591\ub05d\uc774 \uc62c\ub77c\uac04 \uae34 \ud615\ud0dc\ub2e4. \ubab8\uc740 \uadf8 \uc704\uc5d0\uc11c \uc606\uc73c\ub85c \ubed7\uace0 \ud314\uc740 \ub465\uadfc \ubc1b\uce68 \uac00\uae4c\uc774\uc5d0 \ub193\uc778\ub2e4. \uac00\uad6c\uac00 \uc5c6\ub2e4\uba74 \uc774 \uc790\uc138\ub3c4 \uac19\uc740 \uc778\uc0c1\uc744 \ub9cc\ub4e4\uae30 \uc5b4\ub835\ub2e4. \uc758\uc790\ub294 \uc0ac\ub78c \ub4a4\uc758 \uc18c\ud488\uc774\uba74\uc11c \ubab8\uc758 \ubaa8\uc591\uc744 \uad6c\uc131\ud558\ub294 \uc7a5\uce58\ub2e4. \uc61b \ub3c4\ub85d\uc740 \uc774 \uac00\uad6c\ub97c \uc5e0\ud30c\uc774\uc5b4 \uc591\uc2dd\uc758 \uc18c\ud30c\ub85c \uc124\uba85\ud55c\ub2e4. \ub0af\uc120 \uc591\uc2dd \uc774\ub984\uc744 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uc120\uc758 \ud615\ud0dc\ub97c \ubcf4\uba74 \ub41c\ub2e4. \uace7\uc740 \ub2e4\ub9ac\uc640 \uace1\uc120\uc73c\ub85c \uc62c\ub77c\uac04 \ub05d\ubd80\ubd84\uc774 \ud654\uba74 \uc548\uc5d0\uc11c \uc5b4\ub5a4 \uc724\uacfd\uc744 \ub9cc\ub4dc\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc778\ubb3c\uc758 \ubd80\ub4dc\ub7ec\uc6b4 \uc637\uacfc \uac00\uad6c\uc758 \ub610\ub837\ud55c \uc120\uc774 \uc11c\ub85c \ub2e4\ub978 \ud45c\uc815\uc744 \ub0b8\ub2e4. \ud654\uba74 \uc67c\ucabd\uc5d0\ub294 \ub192\uace0 \uac00\ub290\ub2e4\ub780 \ub4f1\uc794\ub300\uac00 \uc11c \uc788\ub2e4. \ubb3c\uac74\uc774 \ub9ce\uc9c0 \uc54a\uc740 \uacf5\uac04\uc5d0\uc11c \uc774 \uc138\ub85c\uc120\uc740 \uaf64 \uac15\ud55c \uc5ed\ud560\uc744 \ud55c\ub2e4. \uae38\uac8c \ub204\uc6b4 \uc778\ubb3c\uacfc \uac00\uad6c\uac00 \ub9cc\ub4dc\ub294 \uac00\ub85c \ubc29\ud5a5\uc5d0 \ub2e4\ub978 \ubc29\ud5a5\uc744 \ub193\uc544 \uc900\ub2e4. \ube44\uc5b4 \uc788\ub294 \ubc30\uacbd \uc18d\uc5d0\uc11c \ub192\uc774\ub3c4 \ub290\uaef4\uc9c0\uac8c \ud55c\ub2e4. \uc774 \ubb3c\uac74\uc5d0 \ubc18\ub4dc\uc2dc \ud558\ub098\uc758 \ube44\ubc00 \uc0c1\uc9d5\uc774 \uc788\ub2e4\uace0 \uc815\ud574 \ub193\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uba3c\uc800 \uc2e4\uc81c\ub85c \ubcf4\uc774\ub294 \uc704\uce58\uc640 \ud06c\uae30, \uc724\uacfd\uc744 \uc0b4\ud3b4\ubcf4\uba74 \ub41c\ub2e4. \ubb3c\uac74\uc774 \uc801\uc744\uc218\ub85d \uc791\uc740 \ucc28\uc774\uac00 \ud06c\uac8c \ub290\uaef4\uc9c4\ub2e4. \ucd08\uc0c1\ud654\ub97c \uc77d\ub294 \ub370 \ud56d\uc0c1 \uc778\ubb3c\uc758 \uc2e0\ubd84\uc744 \uc54c\ub824 \uc8fc\ub294 \uc228\uc740 \uc554\ud638\uac00 \ud544\uc694\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc30\uacbd\uc5d0\ub294 \uad6c\uccb4\uc801\uc778 \uc0dd\ud65c\uc758 \ud754\uc801\uc774 \ub9ce\uc9c0 \uc54a\ub2e4. \ucc45\uc7a5\uacfc \ucc3d\ubb38, \uc190\ub2d8\uacfc \ud654\ub824\ud55c \uc7a5\uc2dd\uc73c\ub85c \uc778\ubb3c\uc758 \uc0b6\uc744 \uc124\uba85\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc5bc\uad74\uacfc \uc790\uc138, \uc637\uacfc \uac00\uad6c\uac00 \ub354 \ub9ce\uc740 \ubaab\uc744 \ub9e1\ub294\ub2e4. \uc2e4\uc81c \ubc29\uc774 \uadf8\ub300\ub85c \uc774\ub807\uac8c \ube44\uc5b4 \uc788\uc5c8\ub2e4\uace0 \uc99d\uba85\ud558\ub294 \uadf8\ub9bc\ub3c4 \uc544\ub2c8\ub2e4. \ucd08\uc0c1\ud654\ub294 \ud604\uc2e4\uc758 \ubaa8\ub4e0 \uac83\uc744 \ube60\uc9d0\uc5c6\uc774 \uc62e\uae30\ub294 \ubaa9\ub85d\uc774 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc744 \ud654\uba74\uc5d0 \ub193\uace0 \ubb34\uc5c7\uc744 \ub35c \ubcf4\uc5ec \uc904\uc9c0 \uc120\ud0dd\ud55c \uacb0\uacfc\ub2e4. \uc774 \uadf8\ub9bc\uc5d0\uc11c\ub294 \uc8fc\ubcc0 \uc774\uc57c\uae30\uac00 \uc904\uc5b4\ub4e0 \uc790\ub9ac\uc5d0 \uc778\ubb3c\uc758 \uc724\uacfd\uacfc \uc0c9\uc758 \uad00\uacc4\uac00 \ub0a8\ub294\ub2e4. \ub9d0\uc218\uac00 \uc801\uc740 \uacf5\uac04\uc774 \uc624\ud788\ub824 \ub208\uc744 \uc624\ub798 \uba38\ubb3c\uac8c \ud560 \uc218 \uc788\ub2e4. \ub3c4\ub85d\uc740 \uc774 \uc791\ud488\uc774 \uc644\uc131\ub418\uc9c0 \uc54a\uc740 \uc0c1\ud0dc\ub85c \ub0a8\uc558\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\ub798\uc11c \uc5b4\ub5a4 \ubd80\ubd84\uc758 \ub35c \ub2e4\ub4ec\uc5b4\uc9c4 \ub290\ub08c\uc744 \ubcfc \ub54c\ub3c4 \uadf8\uac83\uc744 \ub2e8\uc21c\ud788 \uc6d0\ub798 \uc758\ub3c4\ud55c \uc644\uc131 \ud6a8\uacfc\ub77c\uace0 \ud655\uc815\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc624\ub298 \uc6b0\ub9ac\uac00 \uac10\uc0c1\ud558\ub294 \ubaa8\uc2b5\uacfc \ud654\uac00\uac00 \ub05d\uae4c\uc9c0 \uc644\uc131\ud588\uc744 \ubaa8\uc2b5\uc740 \uac19\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubbf8\uc644\uc131\uc774\ub2c8 \ubcfc \uac83\uc774 \uc801\ub2e4\ub294 \ub73b\ub3c4 \uc544\ub2c8\ub2e4. \ud604\uc7ac \ub0a8\uc740 \uadf8\ub9bc \uc548\uc5d0\uc11c \ubc1d\uc740 \uc637\uacfc \ucc28\ubd84\ud55c \ubc30\uacbd, \uc815\ub9ac\ub41c \uac00\uad6c\uc758 \uc724\uacfd\uc740 \ubd84\uba85\ud788 \uc791\ub3d9\ud55c\ub2e4. \ubbf8\uc644\uc131\uc774\ub77c\ub294 \uc5ed\uc0ac\uc801 \uc0c1\ud0dc\uc640 \uc9c0\uae08\uc758 \uac10\uc0c1 \ud6a8\uacfc\ub97c \uad6c\ubd84\ud558\uba74 \ub458 \uc911 \ud558\ub098\ub97c \uc9c0\uc6b8 \ud544\uc694 \uc5c6\uc774 \uadf8\ub9bc\uc744 \ubcfc \uc218 \uc788\ub2e4. \uc790\ud06c \ub8e8\uc774 \ub2e4\ube44\ub4dc\ub294 \ud601\uba85\uacfc \ub098\ud3f4\ub808\uc639 \uc2dc\ub300\uc758 \uc5ed\uc0ac\ud654\ub85c\ub3c4 \uc54c\ub824\uc838 \uc788\ub2e4. \uc5ec\ub7ec \uc778\ubb3c\uacfc \uc758\uc2dd\uc744 \ud06c\uac8c \ubc30\uce58\ud55c \uc791\ud488\ub4e4\uc744 \ub5a0\uc62c\ub9ac\uba74 \uc774 \ucd08\uc0c1\uc758 \uc801\uc740 \uc694\uc18c\uac00 \ub354 \ud765\ubbf8\ub85c\uc6cc\uc9c4\ub2e4. \ud55c \ud654\uac00\uac00 \uadf8\ub9b0 \uadf8\ub9bc\uc774\ub77c\uace0 \ub298 \uac19\uc740 \uaddc\ubaa8\uc640 \ubaa9\uc18c\ub9ac\ub85c \ub9d0\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc61b \ub3c4\ub85d\uc740 \uadf8\uc758 \uc5ec\ub7ec \uc791\ud488\uc744 \uac15\ud558\uac8c \ud3c9\uac00\ud558\uc9c0\ub9cc \uadf8 \ud3c9\uac00\ub97c \uadf8\ub300\ub85c \uc624\ub298\uc758 \uc815\ub2f5\uc73c\ub85c \uc0bc\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5ed\uc0ac\ud654\ub294 \ucc28\uac11\uace0 \ucd08\uc0c1\ud654\ub9cc \uc9c4\uc2e4\ud558\ub2e4\uace0 \uc678\uc6b0\uae30\ubcf4\ub2e4, \uc11c\ub85c \ub2e4\ub978 \ud654\uba74\uc5d0\uc11c \ubb34\uc5c7\uc744 \uac15\uc870\ud558\ub294\uc9c0 \ube44\uad50\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc791\ud488\uc744 \ubd84\ub958\ud558\ub294 \uc774\ub984\uc740 \ubcf4\uae30\uc758 \ucd9c\ubc1c\uc810\uc774\uc9c0 \uac10\uc0c1\uc758 \ub05d\uc740 \uc544\ub2c8\ub2e4. \uba3c\uc800 \ud770 \ub4dc\ub808\uc2a4\uac00 \ub9cc\ub4dc\ub294 \ubc1d\uc740 \uba74\uc744 \ubcf4\uace0, \ub2e4\uc74c\uc5d0\ub294 \ubab8\uacfc \uc5bc\uad74\uc758 \ubc29\ud5a5\uc744, \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \uc758\uc790\uc640 \ub4f1\uc794\ub300\uac00 \ub9cc\ub4dc\ub294 \uc120\uc744 \ub530\ub77c\uac00 \ubcf4\uc790. \uc778\ubb3c\uc5d0 \ub300\ud574 \uc544\ub294 \uac83\uc774 \ub9ce\uc9c0 \uc54a\uc544\ub3c4 \uc2e4\uc81c \uadf8\ub9bc \uc548\uc5d0\uc11c \ubcfc \uc218 \uc788\ub294 \uad00\uacc4\uac00 \ub298\uc5b4\ub09c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uc61b \ub8e8\ube0c\ub974 \ub3c4\ub85d\uc5d0 \uc218\ub85d\ub41c \uc2e4\uc81c \uc791\ud488\uc758 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \uc778\ubb3c\uacfc \uac00\uad6c\ub97c \uc0c8\ub85c \ub9cc\ub4e0 AI \uadf8\ub9bc\uc774 \uc544\ub2c8\ub2e4. \uc0c9\uc740 \uc7ac\ud604\uacfc \ud654\uba74\uc5d0 \ub530\ub77c \ucc28\uc774\uac00 \uc788\uc744 \uc218 \uc788\uc9c0\ub9cc, \ube48 \ubc30\uacbd\uc774 \uc0ac\ub78c\uc744 \uc5b4\ub5bb\uac8c \ub3cb\ubcf4\uc774\uac8c \ud558\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uae30\uc5d0\ub294 \ucda9\ubd84\ud55c \uc785\uad6c\uac00 \ub41c\ub2e4."}, {"id": "delacroix-liberty-1830-and-barricade", "title": "\ubbfc\uc911\uc744 \uc774\ub044\ub294 \uc790\uc720\uc758 \uc5ec\uc2e0 \u2014 \uc0bc\uc0c9\uae30 \uc544\ub798\uc758 1830\ub144", "summary": "1830\ub144\uc758 \uc0ac\uac74\uacfc \uc790\uc720\uc758 \uc758\uc778\ud654, \uad70\uc911\uacfc \uc0bc\uc0c9\uae30, \uc804\uc9c4 \uc544\ub798\uc758 \uc8fd\uc74c\uc744 \ud568\uaed8 \ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/delacroix-liberty-1830-and-barricade/index.html", "image": "../media/delacroix-liberty-1830-and-barricade.jpg", "alt": "\ub4e4\ub77c\ud06c\ub8e8\uc544\uc758 \ubbfc\uc911\uc744 \uc774\ub044\ub294 \uc790\uc720\uc758 \uc5ec\uc2e0\uc744 \uc7ac\ud604\ud55c \uc5ed\uc0ac \ucd9c\ud310\ubb3c\uc758 \uceec\ub7ec \ub3c4\ud310", "text": "\ubbfc\uc911\uc744 \uc774\ub044\ub294 \uc790\uc720\uc758 \uc5ec\uc2e0 \u2014 \uc0bc\uc0c9\uae30 \uc544\ub798\uc758 1830\ub144 \ub4e4\ub77c\ud06c\ub8e8\uc544\uc758 7\uc6d4\ud601\uba85 \ud68c\ud654\uc5d0\uc11c \uc5ed\uc0ac\uc640 \uc758\uc778\ud654\ub97c \ub098\ub204\uc5b4 \ubcf4\uae30 1830\ub144\uc758 \uc0ac\uac74\uacfc \uc790\uc720\uc758 \uc758\uc778\ud654, \uad70\uc911\uacfc \uc0bc\uc0c9\uae30, \uc804\uc9c4 \uc544\ub798\uc758 \uc8fd\uc74c\uc744 \ud568\uaed8 \ubd05\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \uc5f0\uae30\uac00 \uc790\uc6b1\ud55c \uac70\ub9ac\uc5d0\uc11c \ud55c \uc5ec\uc778\uc774 \uc0bc\uc0c9\uae30\ub97c \ub192\uc774 \ub4e0\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \ubb34\ub108\uc9c4 \uc7a5\uc560\ubb3c\uacfc \uc8fd\uc740 \uc774\ub4e4\uc744 \ub118\uc5b4 \uc55e\uc73c\ub85c \uc6c0\uc9c1\uc778\ub2e4. \uc678\uc820 \ub4e4\ub77c\ud06c\ub8e8\uc544\uc758 \u300e\ubbfc\uc911\uc744 \uc774\ub044\ub294 \uc790\uc720\uc758 \uc5ec\uc2e0\u300f\uc740 \ud504\ub791\uc2a4\uc758 \ud601\uba85\uc744 \ub300\ud45c\ud558\ub294 \uc774\ubbf8\uc9c0\ub85c \ub110\ub9ac \uc54c\ub824\uc84c\ub2e4. \uadf8\ub7ec\ub098 \uadf8\ub9bc\uc774 \uac00\ub9ac\ud0a4\ub294 \uc0ac\uac74\ubd80\ud130 \uc815\ud655\ud788 \uc9da\uc73c\uba74 \ubcf4\uc774\ub294 \uac83\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc774 \uc791\ud488\uc758 \uc9c1\uc811\uc801\uc778 \ubc30\uacbd\uc740 1789\ub144\uc774 \uc544\ub2c8\ub77c 1830\ub144\uc758 7\uc6d4\ud601\uba85\uc774\ub2e4. \uc2e4\uc81c \uac70\ub9ac\uc758 \uc778\ubb3c\uacfc \ucd94\uc0c1\uc801\uc778 \uc790\uc720\uc758 \uc0c1\uc9d5\uc774 \uac19\uc740 \ud654\uba74\uc5d0 \uc788\ub2e4. \ubb34\uc5c7\uc774 \uc5ed\uc0ac\uc774\uace0 \ubb34\uc5c7\uc774 \ud654\uac00\uc758 \uad6c\uc131\uc778\uc9c0 \ub098\ub204\uc5b4 \ubcf4\uba74\uc11c \uadf8\ub9bc \uc18d\uc73c\ub85c \ub4e4\uc5b4\uac00 \ubcf4\uc790. 1830\ub144 \ud504\ub791\uc2a4\uc5d0\uc11c\ub294 \uc0e4\ub97c 10\uc138\uc758 \ud1b5\uce58\uc5d0 \ub300\ud55c \ubc18\ubc1c\uc774 \uac70\ub9ac\uc758 \ubd09\uae30\ub85c \uc774\uc5b4\uc84c\ub2e4. \uc655\uc774 \ubb3c\ub7ec\ub098\uace0 \ub8e8\uc774 \ud544\ub9ac\ud504\uac00 \ub4f1\uc7a5\ud558\ub294 \ubcc0\ud654\uac00 \uc77c\uc5b4\ub0ac\ub2e4. \uadf8\ub9bc\uc740 \uc774 \uaca9\ub3d9\uc5d0 \uc5f0\uacb0\ub41c\ub2e4. \ud504\ub791\uc2a4\ud601\uba85\uc774\ub77c\ub294 \ub113\uc740 \uc774\ub984\ub9cc \uae30\uc5b5\ud558\uba74 \uc5ec\ub7ec \uc2dc\uae30\uc758 \uc11c\ub85c \ub2e4\ub978 \uc0ac\uac74\uc774 \ud55c \uc7a5\uba74\uc73c\ub85c \ud569\uccd0\uc9c0\uae30 \uc27d\ub2e4. \uc5f0\ub3c4\ub97c \uc544\ub294 \uac83\uc740 \uc2dc\ud5d8\uc758 \uc815\ub2f5\uc744 \uc678\uc6b0\ub294 \uc77c \uc774\uc0c1\uc774\ub2e4. \uc5b4\ub5a4 \uad8c\ub825\uc5d0 \ub9de\uc130\uc73c\uba70 \uadf8 \ub4a4 \ubb34\uc5c7\uc774 \ubc14\ub00c\uc5c8\ub294\uc9c0 \uc9c8\ubb38\ud560 \uc218 \uc788\uac8c \ud55c\ub2e4. 1789\ub144\uc758 \uc0c1\uc9d5\uc774 \ud6c4\ub300\uc758 \uc815\uce58\uc801 \ud589\ub3d9\uc5d0 \uc774\uc5b4 \uc4f0\uc774\uae30\ub3c4 \ud588\uc9c0\ub9cc, \ubc18\ubcf5\ub418\ub294 \uc0c1\uc9d5\uacfc \ub3d9\uc77c\ud55c \uc0ac\uac74\uc740 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \uc911\uc559\uc758 \uc5ec\uc778\uc740 \uc0ac\ub78c\ub4e4\uc744 \uc774\ub044\ub294 \uc704\uce58\uc5d0 \uc11c \uc788\uc9c0\ub9cc \ud2b9\uc815\ud55c \ucc38\uac00\uc790\ub97c \uadf8\ub300\ub85c \uadf8\ub9b0 \ucd08\uc0c1\uc73c\ub85c\ub9cc \uc77d\uae30 \uc5b4\ub835\ub2e4. \uc790\uc720\ub97c \uc0ac\ub78c\uc758 \ubaa8\uc2b5\uc73c\ub85c \ub098\ud0c0\ub0b8 \uc758\uc778\ud654\ub2e4. \uace0\uc804\uc801\uc778 \ud615\uc0c1\uacfc \uac70\ub9ac\uc5d0\uc11c \ub4e4\uace0 \uc4f0\ub294 \ubb34\uae30, \uc0bc\uc0c9\uae30\uac00 \ud55c \uc778\ubb3c\uc5d0 \uacb0\ud569\ud55c\ub2e4. \uad00\ub150\uc774 \uc2e4\uc81c \uc0ac\uac74 \uc18d\uc73c\ub85c \ub4e4\uc5b4\uc628 \uc148\uc774\ub2e4. \uadf8\ub798\uc11c \ud654\uba74\uc740 \ud604\uc7a5 \uc0ac\uc9c4\ucc98\ub7fc \uc0ac\uc2e4\uc744 \ubcf5\uc0ac\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c \uc791\ub3d9\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud654\uac00\ub294 \ud55c \uc0ac\uac74\uc774 \ubb34\uc5c7\uc744 \uc758\ubbf8\ud558\ub294\uc9c0 \ubcf4\uc774\uac8c \ud558\ub824 \ud588\ub2e4. \uc0c1\uc9d5\uc801\uc778 \uc778\ubb3c\uc774 \uc788\ub2e4\uace0 \ubaa8\ub4e0 \uc778\ubb3c\uc774 \ud5c8\uad6c\uac00 \ub418\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \ub2f9\ub300\uc758 \uc637\uacfc \ubb34\uae30, \uac70\ub9ac\uc758 \uacbd\ud5d8\uc774 \uc0c1\uc9d5\uc744 \uad6c\uccb4\uc801\uc778 \ud604\uc2e4\uc5d0 \ubb36\uc5b4 \ub454\ub2e4. \ud654\uba74\uc5d0\ub294 \ubaa8\uc790\ub97c \uc4f0\uace0 \uaca9\uc2dd\uc744 \uac16\ucd98 \uc778\ubb3c\uacfc \ub354 \uc18c\ubc15\ud55c \uc637\uc758 \uc0ac\ub78c, \uc5b4\ub9b0 \uc778\ubb3c\uc774 \ud568\uaed8 \uc788\ub2e4. \uac19\uc740 \ubaa9\ud45c\ub97c \ud5a5\ud55c \uc9d1\ub2e8\uc758 \ubaa8\uc2b5\uc774\uc9c0\ub9cc \uc5bc\uad74\uacfc \uc790\uc138\ub294 \uc11c\ub85c \ub2e4\ub974\ub2e4. \ubbfc\uc911\uc774\ub77c\ub294 \ud55c \ub2e8\uc5b4 \uc548\uc5d0 \ub2e4\uc591\ud55c \uc0ac\ub78c\uc774 \ub4e4\uc5b4 \uc788\uc74c\uc744 \ubcf4\uac8c \ub41c\ub2e4. \uc637\ub9cc \ubcf4\uace0 \uac01 \uc778\ubb3c\uc758 \uc9c1\uc5c5\uacfc \uc815\uce58\uc801 \uc0dd\uac01\uc744 \ubaa8\ub450 \ud655\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \ucc28\uc774\ub97c \uac00\uc9c4 \uc0ac\ub78c\ub4e4\uc774 \ud55c \uc7a5\uba74\uc5d0 \ubaa8\uc600\ub2e4\ub294 \uad6c\uc131\uc740 \uc911\uc694\ud558\ub2e4. \uc790\uc720\uac00 \ud63c\uc790 \uc2b9\ub9ac\ud558\ub294 \uc778\ubb3c\ub85c \uc11c \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ub2e4\ub978 \uc774\ub4e4\uc774 \ub530\ub77c \uc6c0\uc9c1\uc774\ub294 \ud798\uc73c\ub85c \ub098\ud0c0\ub09c\ub2e4. \uac1c\uc778\uc758 \ubab8\uacfc \uc9d1\ub2e8\uc758 \ud589\ub3d9\uc774 \uc5f0\uacb0\ub41c\ub2e4. \ub192\uc774 \ub4e0 \uae43\ubc1c\uc740 \uc5b4\ub514\ubd80\ud130 \ubcfc\uc9c0 \uc54c\ub824 \uc8fc\ub294 \uac15\ud55c \ud45c\uc9c0\ub2e4. \uc6d0\uc791\uc5d0\uc11c\ub294 \uc5b4\ub450\uc6b4 \uc5f0\uae30\uc640 \ud759\ube5b \uc0ac\uc774\ub85c \ud30c\ub791\uacfc \ud770\uc0c9, \ube68\uac15\uc774 \uac15\ud558\uac8c \ub4dc\ub7ec\ub09c\ub2e4. \uc0c9\uc740 \uc0ac\ubb3c\uc758 \ud45c\uba74\uc744 \uc124\uba85\ud558\ub294 \ub3d9\uc2dc\uc5d0 \uad00\ub78c\uac1d\uc758 \uc2dc\uc120\uc744 \uc6c0\uc9c1\uc778\ub2e4. \uadf8\ub9bc\uc758 \uc758\ubbf8\uc640 \uad6c\uc131\uc758 \uae30\uc220\uc774 \uac19\uc740 \uacf3\uc5d0\uc11c \ub9cc\ub09c\ub2e4. \uae43\ubc1c\uc5d0\uc11c \ub2e4\ub978 \uc778\ubb3c\uacfc \ubc1d\uc740 \ubd80\ubd84\uc73c\ub85c \ub208\uc744 \uc62e\uaca8 \ubcf4\uba74 \ud654\uba74\uc774 \ubb34\uc791\uc704\ub85c \ud769\uc5b4\uc838 \uc788\uc9c0 \uc54a\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ub290\ub084 \uc218 \uc788\ub2e4. \ud63c\ub780\uc744 \uadf8\ub9ac\uba74\uc11c\ub3c4 \ud654\uac00\ub294 \ubcfc \uc21c\uc11c\ub97c \ub9cc\ub4e4\uc5b4 \ub193\uc558\ub2e4. \uc5ed\ub3d9\uc801\uc778 \uc7a5\uba74\uc774 \uc54c\uc544\ubcfc \uc218 \uc788\ub294 \ud558\ub098\uc758 \uc774\ubbf8\uc9c0\uac00 \ub418\ub294 \ub370\uc5d0\ub294 \uc774\ub7f0 \uc870\uc9c1\uc774 \ud544\uc694\ud588\ub2e4. \uba40\ub9ac\uc5d0\ub294 \ud30c\ub9ac\uc758 \uac74\ucd95\uc744 \uc54c\uc544\ubcfc \ub2e8\uc11c\ub3c4 \ubcf4\uc778\ub2e4. \ud070 \uc778\ubb3c\uacfc \uae43\ubc1c\ub9cc\uc774 \uc544\ub2c8\ub77c \ubc30\uacbd\uc758 \uc791\uc740 \ud45c\uc9c0\uac00 \uc774 \uc7a5\uba74\uc744 \ud2b9\uc815\ud55c \ub3c4\uc2dc\uc640 \uc5f0\uacb0\ud55c\ub2e4. \uc0c1\uc9d5\uc801\uc778 \uc790\uc720\uac00 \uc5b4\ub290 \uc7a5\uc18c\uc5d0\ub3c4 \uc18d\ud558\uc9c0 \uc54a\uc740 \ucd94\uc0c1\uc801\uc778 \uad6c\ub984 \uc18d\uc744 \uac77\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \uc55e\uc73c\ub85c \ub098\uc544\uac00\ub294 \uae38\uc5d0\ub294 \uc4f0\ub7ec\uc9c4 \ubab8\ub4e4\uc774 \uc788\ub2e4. \uae43\ubc1c\ub9cc \uc798\ub77c \ubcf4\uba74 \uc2b9\ub9ac\uc640 \ud574\ubc29\uc758 \uadf8\ub9bc\ucc98\ub7fc \ub290\uaef4\uc9c0\uc9c0\ub9cc \uc804\uccb4 \ud654\uba74\uc740 \uadf8 \ub300\uac00\ub97c \ud568\uaed8 \ubcf4\uc5ec \uc900\ub2e4. \uc804\uc9c4\ud558\ub294 \ubab8\uacfc \uc6c0\uc9c1\uc784\uc744 \uba48\ucd98 \ubab8\uc774 \uac19\uc740 \uacf5\uac04\uc5d0 \uc788\ub2e4. \ubc14\ub9ac\ucf00\uc774\ub4dc\ub294 \uad6c\ud638\uc758 \ubc30\uacbd\uc774\uba74\uc11c \uc2e4\uc81c \uc704\ud5d8\uc758 \uc7a5\uc18c\ub2e4. \uc774 \ub300\ubaa9\uc744 \ub193\uce58\uba74 \uadf8\ub9bc\uc774 \ub108\ubb34 \ub2e8\uc21c\ud55c \uc120\uc804 \ubb38\uad6c\ub85c \uc904\uc5b4\ub4e0\ub2e4. \uacf5\ub3d9\uc758 \uc774\uc0c1\uc744 \ud798 \uc788\uac8c \ud45c\ud604\ud558\uba74\uc11c\ub3c4 \ud3ed\ub825\uacfc \uc8fd\uc74c\uc744 \uc9c0\uc6b0\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uad00\ub78c\uac1d\uc740 \ubb34\uc5c7\uc744 \uc5bb\uc5c8\ub2e4\ub294 \ub9d0 \uacc1\uc5d0 \ub204\uac00 \uc5b4\ub5a4 \uc190\uc2e4\uc744 \uacaa\uc5c8\ub294\uc9c0\ub3c4 \ubcf4\uac8c \ub41c\ub2e4. \ud654\uba74\uc758 \uc544\ub798\ucabd\uc740 \uc758\ubbf8 \uc5c6\ub294 \ube48\uc790\ub9ac\ub85c \ub0a8\uc9c0 \uc54a\ub294\ub2e4. \ub4e4\ub77c\ud06c\ub8e8\uc544\ub294 \uc6c0\uc9c1\uc784\uacfc \uc0c9, \uac15\ud55c \uac10\uc815\uc758 \ud45c\ud604\uc73c\ub85c \uc54c\ub824\uc9c4 \ub0ad\ub9cc\uc8fc\uc758\uc758 \uc911\uc694\ud55c \ud654\uac00\ub2e4. \uadf8\uc758 \uadf8\ub9bc\uc5d0\uc11c \uc5ed\uc0ac\uc801 \uc0ac\uac74\uc740 \uc778\ubb3c\uc758 \ubab8\uacfc \uc2dc\uc120, \uacb9\uce58\ub294 \ub3d9\uc791\uc744 \ud1b5\ud574 \uc804\ub2ec\ub41c\ub2e4. \uc5f0\ud45c\uc758 \ubb38\uc7a5\uc774 \uc8fc\uc9c0 \ubabb\ud558\ub294 \uae34\uc7a5\uacfc \uc5f4\uae30\uac00 \ud654\uba74\uc5d0 \uc0dd\uae34\ub2e4. \uadf8\ub7ec\ub098 \uac10\uc815\uc774 \uac15\ud558\ub2e4\uace0 \uad6c\uc131\uae4c\uc9c0 \uc989\ud765\uc801\uc778 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\ub4e4\uc758 \uc704\uce58\uc640 \ubc1d\uae30\uc758 \ucc28\uc774, \uc911\uc2ec\uc744 \ub9cc\ub4dc\ub294 \uc120\uc774 \ud568\uaed8 \uc791\ub3d9\ud55c\ub2e4. \ud654\uac00\uac00 \uaca9\ub3d9\uc744 \uc5b4\ub5bb\uac8c \uc815\ub9ac\ud588\ub294\uc9c0 \uc0b4\ud53c\uba74 \uaca9\uc815\uc801\uc778 \uc608\uc220\uacfc \uce58\ubc00\ud55c \uc120\ud0dd\uc774 \ud568\uaed8 \uac08 \uc218 \uc788\uc74c\uc744 \uc54c \uc218 \uc788\ub2e4. \uc774 \uadf8\ub9bc\uc758 \ud798\uc740 \ub0b4\uc6a9\uacfc \ud615\uc2dd \uc5b4\ub290 \ud55c\ucabd\ub9cc\uc73c\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc774 \uadf8\ub9bc\uc740 \uc6d0\ub798 \uc0ac\uac74\uc758 \ubc94\uc704\ub97c \ub118\uc5b4 \uc790\uc720\uc640 \ud601\uba85\uc758 \uc0c1\uc9d5\uc73c\ub85c \ubc18\ubcf5\ud574\uc11c \uc4f0\uc778\ub2e4. \ub110\ub9ac \uc54c\ub824\uc9c4 \uc774\ubbf8\uc9c0\uac00 \ub418\uba74 \uc0bc\uc0c9\uae30\uc640 \uc911\uc559 \uc778\ubb3c\ub9cc \uba3c\uc800 \ub5a0\uc624\ub974\uae30 \uc27d\ub2e4. \uadf8\ub7f4\uc218\ub85d \uc5f0\ub3c4\uc640 \uad70\uc911, \ud654\uba74 \uc544\ub798\uc758 \ubab8\uc744 \ub2e4\uc2dc \ubcf4\ub294 \uc77c\uc774 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uc791\ud488\uc758 \ud655\uc7a5\ub41c \uc758\ubbf8\uc640 \ucc98\uc74c\uc758 \ub9e5\ub77d\uc740 \ud568\uaed8 \uc77d\uc744 \uc218 \uc788\ub2e4. \ubcf4\ud3b8\uc801\uc778 \uc790\uc720\ub77c\ub294 \uc0dd\uac01\uc774 \uc5b4\ub5a4 \uac70\ub9ac\uc640 \uc5b4\ub5a4 \uc0ac\ub78c\ub4e4\uc758 \ubaa8\uc2b5\uc73c\ub85c \ud45c\ud604\ub418\uc5c8\ub294\uc9c0 \ub3cc\uc544\uac00\ub294 \uac83\uc774\ub2e4. \uadf8\ub807\uac8c \ubcf4\uba74 \u300e\ubbfc\uc911\uc744 \uc774\ub044\ub294 \uc790\uc720\uc758 \uc5ec\uc2e0\u300f\uc740 \uc775\uc219\ud55c \ud45c\uc9c0\ub97c \ub118\uc5b4 \uc5ed\uc0ac\uc640 \uc0c1\uc9d5, \uadf8\ub9bc\uc758 \uad6c\uc131\uc774 \ub9cc\ub09c \ud55c \uc7a5\uc758 \uad6c\uccb4\uc801\uc778 \ud68c\ud654\uac00 \ub41c\ub2e4."}, {"id": "demeter-persephone-seed-and-return", "title": "\ub370\uba54\ud14c\ub974 \u2014 \uc11d\ub958 \ud55c \uc54c\uc774 \ub538\uc758 \uadc0\ud658\uc744 \ubc14\uafbc \uc774\uc720", "summary": "\ud398\ub974\uc138\ud3ec\ub124\uc758 \ub0a9\uce58\uc640 \ub370\uba54\ud14c\ub974\uc758 \uc218\uc0c9, \uace1\uc2dd\uc758 \uc911\ub2e8\uacfc \uc11d\ub958 \uc528\uc557\uc758 \uc870\uac74\uc744 \ucc2c\uac00\uc758 \ud310\ubcf8\uc5d0 \ub530\ub77c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc2e0\ud654\uc640 \ubbfc\uc18d", "categories": ["arts"], "url": "stories/demeter-persephone-seed-and-return/index.html", "image": "../media/demeter-persephone-seed-and-return.png", "alt": "\ubc00\ubc2d \uacc1\uc5d0\uc11c \ub2e4\uc2dc \ub9cc\ub098\ub294 \ub370\uba54\ud14c\ub974\uc640 \ud398\ub974\uc138\ud3ec\ub124, \uc11d\ub958\ub97c \uacc1\ub4e4\uc778 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ub370\uba54\ud14c\ub974 \u2014 \uc11d\ub958 \ud55c \uc54c\uc774 \ub538\uc758 \uadc0\ud658\uc744 \ubc14\uafbc \uc774\uc720 \u300e\ub370\uba54\ud14c\ub974 \ucc2c\uac00\u300f\uc5d0\uc11c \uc77d\ub294 \uc5b4\uba38\ub2c8\uc758 \uc218\uc0c9\uacfc \ub545\uc758 \uce68\ubb35 \ud398\ub974\uc138\ud3ec\ub124\uc758 \ub0a9\uce58\uc640 \ub370\uba54\ud14c\ub974\uc758 \uc218\uc0c9, \uace1\uc2dd\uc758 \uc911\ub2e8\uacfc \uc11d\ub958 \uc528\uc557\uc758 \uc870\uac74\uc744 \ucc2c\uac00\uc758 \ud310\ubcf8\uc5d0 \ub530\ub77c \uc77d\uc2b5\ub2c8\ub2e4. \uc2e0\ud654\uc640 \ubbfc\uc18d \ubb38\ud654\uc640 \uc608\uc220 \ub538\uc744 \ub2e4\uc2dc \ud488\uc5d0 \uc548\uc740 \uc5b4\uba38\ub2c8\uac00 \uba3c\uc800 \ubb3b\ub294 \uac83\uc740 \ub73b\ubc16\uc5d0\ub3c4 \uc74c\uc2dd\uc774\ub2e4. \uc544\ub798 \uc138\uc0c1\uc5d0\uc11c \ubb34\uc5c7\uc744 \uba39\uc5c8\ub290\ub0d0\ub294 \uc9c8\ubb38. \ubc18\uac00\uc6b4 \uc7ac\ud68c \ub4a4\uc5d0 \uc11d\ub958 \uc528\uc557\uc774 \ub4f1\uc7a5\ud558\uba74\uc11c \ub3cc\uc544\uc628 \ub538\uc774 \uacc4\uc18d \uba38\ubb34\ub97c \uc218 \uc788\ub294\uc9c0\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \ub370\uba54\ud14c\ub974\uc640 \ud398\ub974\uc138\ud3ec\ub124\uc758 \uc774\uc57c\uae30\ub294 \uacc4\uc808\uc758 \uc2e0\ud654\ub85c \uc775\uc219\ud558\ub2e4. \ud558\uc9c0\ub9cc \u300e\ud638\uba54\ub85c\uc2a4 \ucc2c\uac00\u300f\uc5d0 \uc18d\ud55c \u300c\ub370\uba54\ud14c\ub974 \ucc2c\uac00\u300d\ub97c \ub530\ub77c\uac00\uba74 \uc0ac\ub77c\uc9c4 \ub538\uc744 \ucc3e\ub294 \uc2dc\uac04\uacfc \uc2e0\ub4e4 \uc0ac\uc774\uc758 \ud798\uaca8\ub8e8\uae30\uac00 \uba3c\uc800 \ubcf4\uc778\ub2e4. \uc774 \uae00\uc740 \uadf8 \ucc2c\uac00\uc758 \uc804\uac1c\ub97c \uae30\uc900\uc73c\ub85c \uc77d\ub294\ub2e4. \ud398\ub974\uc138\ud3ec\ub124\uac00 \ub4e4\ud310\uc5d0\uc11c \uaf43\uc744 \ub530\ub358 \ub54c \ub545\uc774 \uac08\ub77c\uc9c0\uace0 \ud558\ub370\uc2a4\uac00 \ub098\ud0c0\ub09c\ub2e4. \uadf8\ub294 \ud398\ub974\uc138\ud3ec\ub124\ub97c \uc804\ucc28\uc5d0 \ud0dc\uc6cc \uc8fd\uc740 \uc774\ub4e4\uc758 \uc138\uacc4\ub85c \ub370\ub824\uac04\ub2e4. \ucc2c\uac00\ub294 \uadf8\ub140\uac00 \uc6d0\ud558\uc9c0 \uc54a\uc558\uace0 \uc5b4\uba38\ub2c8\ub97c \ubd80\ub974\uba70 \uc6b8\uc5c8\ub2e4\uace0 \uc804\ud55c\ub2e4. \uc774 \uc2dc\uc791\uc744 \ub450 \uc2e0\uc758 \ub0ad\ub9cc\uc801\uc778 \ub9cc\ub0a8\uc73c\ub85c \ubc14\uafb8\uba74 \ub4a4\uc758 \uc774\uc57c\uae30\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \ub370\uba54\ud14c\ub974\uc758 \ubd84\ub178\ub294 \ub2e8\uc9c0 \ub538\uc774 \uacb0\ud63c\ud574 \uc12d\uc12d\ud55c \ub9c8\uc74c\uc774 \uc544\ub2c8\ub2e4. \uc790\uae30\uc640 \ub538\uc758 \ub73b\uc744 \ubb3b\uc9c0 \uc54a\uc740 \ucc44 \uad00\uacc4\uac00 \uacb0\uc815\ub41c \uc0c1\ud669\uc5d0\uc11c \uc0dd\uae34\ub2e4. \uace1\uc2dd\uacfc \uad00\ub828\ub41c \uc5ec\uc2e0 \ub370\uba54\ud14c\ub974\ub294 \ub538\uc744 \ucc3e\uc544 \ud5e4\ub9e8\ub2e4. \uba39\uace0 \ub9c8\uc2dc\uba70 \uc26c\ub294 \uc77c\ub3c4 \ub4a4\ub85c \ubbf8\ub8ec\ub2e4. \ud5e4\uce74\ud14c\uac00 \uc18c\ub9ac\ub97c \ub4e4\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc804\ud558\uace0, \ud0dc\uc591\uc2e0 \ud5ec\ub9ac\uc624\uc2a4\uc5d0\uac8c\uc11c \uc0ac\uac74\uc758 \uc0ac\uc815\uc744 \ub354 \ub4e3\uac8c \ub41c\ub2e4. \uadf8 \uacfc\uc815\uc5d0\uc11c \ud558\ub370\uc2a4 \ud63c\uc790 \ubc8c\uc778 \uc77c\uc774 \uc544\ub2c8\uc5c8\ub2e4\ub294 \uc810\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \uc81c\uc6b0\uc2a4\uc758 \ud5c8\ub77d\uc774 \uc788\uc5c8\ub2e4. \ub538\uc758 \uc544\ubc84\uc9c0\uc774\uc790 \uac15\ud55c \uad8c\ub825\uc744 \uac00\uc9c4 \uc2e0\uc774 \uacb0\uc815\uc5d0 \uad00\uc5ec\ud55c \uac83\uc774\ub2e4. \uc218\uc0c9\uc740 \uac00\uc871\uc744 \ucc3e\ub294 \uc77c\uc5d0\uc11c \ub2e4\ub978 \uc2e0\ub4e4\uc758 \uacb0\uc815\uc5d0 \ub9de\uc11c\ub294 \uc77c\ub85c \ub113\uc5b4\uc9c4\ub2e4. \uadf8\ub140\uac00 \ub9cc\ub098\ub294 \uc99d\uc5b8\uc740 \uc800\ub9c8\ub2e4 \ubcf4\uace0 \ub4e4\uc740 \ubc94\uc704\uac00 \ub2ec\ub790\ub2e4. \uc218\uc0c9\uc5d0\ub294 \uadf8 \ucc28\uc774\ub97c \uc774\uc5b4 \ubd99\uc774\ub294 \uc2dc\uac04\ub3c4 \ud544\uc694\ud588\ub2e4. \ub370\uba54\ud14c\ub974\ub294 \uc2e0\ub4e4\uc758 \uc138\uacc4\ub97c \ub5a0\ub098 \ub178\ud30c\uc758 \ubaa8\uc2b5\uc73c\ub85c \uc5d8\ub808\uc6b0\uc2dc\uc2a4\uc5d0 \uba38\ubb38\ub2e4. \uadf8\uacf3\uc758 \uc655\uac00\uc640 \uad00\uacc4\ub97c \ub9fa\uace0 \uc544\uc774\ub97c \ub3cc\ubcf4\ub294 \uc77c\ub3c4 \ud55c\ub2e4. \uc790\uc2e0\uc758 \uc815\uccb4\uac00 \ub4dc\ub7ec\ub09c \ub4a4\uc5d0\ub294 \uc2e0\uc804\uc744 \ub9c8\ub828\ud558\ub3c4\ub85d \ud55c\ub2e4. \uc774 \ub300\ubaa9\uc740 \uc2e0\ud654\uac00 \ub545 \uc704\uc758 \ud2b9\uc815 \uc7a5\uc18c\uc640\ub3c4 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub204\uad6c\ub098 \uc544\ub294 \uacc4\uc808 \uc774\uc57c\uae30\ub85c\ub9cc \uc694\uc57d\ud558\uba74 \uc5d8\ub808\uc6b0\uc2dc\uc2a4\uc5d0\uc11c \uc5ec\uc2e0\uc774 \uacaa\ub294 \uc77c\uacfc \uadf8\uacf3\uc758 \uc81c\uc758\ub85c \uc774\uc5b4\uc9c0\ub294 \ucc2c\uac00\uc758 \ud750\ub984\uc740 \uc27d\uac8c \ube60\uc9c4\ub2e4. \uc5ec\uc2e0\uc740 \uace1\uc2dd\uc774 \uc790\ub77c\uc9c0 \ubabb\ud558\uac8c \ud55c\ub2e4. \ub545\uc740 \uc2ec\uc5b4\ub3c4 \uc218\ud655\uc744 \ub0b4\uc8fc\uc9c0 \uc54a\uace0 \uc0ac\ub78c\ub4e4\uc740 \uad76\uc8fc\ub9b4 \ucc98\uc9c0\uac00 \ub41c\ub2e4. \uc778\uac04\uc758 \uc0b6\uc744 \ub5a0\ubc1b\uce58\ub358 \uc77c\uc774 \uba48\ucd94\uc790 \uc2e0\ub4e4\uc5d0\uac8c \ubc14\uce58\ub294 \uc81c\ubb3c\ub3c4 \uc0ac\ub77c\uc9c8 \uc704\ud5d8\uc5d0 \ub193\uc778\ub2e4. \uc774 \uc7a5\uba74\uc5d0\uc11c \ub370\uba54\ud14c\ub974\ub294 \uc790\uc2e0\uc758 \ud798\uc744 \ubd84\uba85\ud558\uac8c \ub4dc\ub7ec\ub0b8\ub2e4. \uc81c\uc6b0\uc2a4\uac00 \ubb34\uc5c7\uc744 \uacb0\uc815\ud558\ub4e0 \ub545\uc758 \uc0dd\uc7a5\uc744 \ub9c8\uc74c\ub300\ub85c \ub300\uc2e0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \ub300\uce58\uc758 \ubd80\ub2f4\uc740 \uc778\uac04\uc5d0\uac8c\ub3c4 \ub5a8\uc5b4\uc9c4\ub2e4. \uc5ec\uc2e0\uc758 \uc2ac\ud514\uc740 \uc138\uc0c1 \uc804\uccb4\uc758 \uc704\uae30\ub85c \ubc88\uc9c4\ub2e4. \ub2e4\ub978 \uc2e0\ub4e4\uc774 \ucc3e\uc544\uc640 \uc124\ub4dd\ud558\uc9c0\ub9cc \ub370\uba54\ud14c\ub974\ub294 \uc27d\uac8c \ub73b\uc744 \ubc14\uafb8\uc9c0 \uc54a\ub294\ub2e4. \uba85\uc608\uc640 \uc120\ubb3c\ub85c \ub2ec\ub7a0 \uc218 \uc788\ub294 \uc694\uad6c\uac00 \uc544\ub2c8\uc5c8\ub2e4. \ub538\uc744 \uc9c1\uc811 \ubcf4\uc9c0 \uc54a\uace0\uc11c\ub294 \uace1\uc2dd\uc774 \uc790\ub77c\ub294 \uc77c\uc744 \ub2e4\uc2dc \uc2dc\uc791\ud558\uc9c0 \uc54a\uaca0\ub2e4\ub294 \ud0dc\ub3c4\ub2e4. \uacb0\uad6d \uc81c\uc6b0\uc2a4\ub294 \ud5e4\ub974\uba54\uc2a4\ub97c \ud558\ub370\uc2a4\uc5d0\uac8c \ubcf4\ub0b8\ub2e4. \ub545 \uc704\uc758 \uc704\uae30\ub97c \ud480\ub824\uba74 \ub538\uc758 \uadc0\ud658\uc744 \ub2e4\ub8e8\uc5b4\uc57c \ud588\ub2e4. \uace1\uc2dd\uacfc \uc81c\ubb3c\uc774 \uc774\uc5b4 \uc8fc\ub294 \uc2e0\uacfc \uc778\uac04\uc758 \uad00\uacc4\uac00 \ud611\uc0c1\uc744 \uc6c0\uc9c1\uc774\ub294 \uc911\uc694\ud55c \uc870\uac74\uc774 \ub41c\ub2e4. \ud558\ub370\uc2a4\ub294 \ud398\ub974\uc138\ud3ec\ub124\uac00 \ub5a0\ub098\ub294 \uac83\uc744 \ubc1b\uc544\ub4e4\uc774\uba74\uc11c\ub3c4 \uc11d\ub958 \uc528\uc557\uc744 \uba39\uac8c \ud55c\ub2e4. \ucc2c\uac00\uc5d0\uc11c \ud398\ub974\uc138\ud3ec\ub124\ub294 \uc5b4\uba38\ub2c8\uc5d0\uac8c \uc790\uc2e0\uc758 \ub73b\uacfc \ub2e4\ub974\uac8c \uadf8\uac83\uc744 \ub9db\ubcf4\uc558\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc791\uc740 \uc74c\uc2dd \ud558\ub098\uac00 \uc544\ub798 \uc138\uacc4\uc640\uc758 \uad00\uacc4\ub97c \ubd99\ub4dc\ub294 \uc7a5\uce58\uac00 \ub41c \uac83\uc774\ub2e4. \uc11d\ub958\uac00 \ub2e8\uc21c\ud55c \uac04\uc2dd\uc774 \uc544\ub2c8\ub77c\ub294 \uc810\uc740 \uc7ac\ud68c \uc7a5\uba74\uc5d0\uc11c \ub4dc\ub7ec\ub09c\ub2e4. \ub370\uba54\ud14c\ub974\ub294 \uae30\uc068 \uc18d\uc5d0\uc11c\ub3c4 \ubb34\uc5c7\uc744 \uba39\uc5c8\ub294\uc9c0 \ubb3b\ub294\ub2e4. \ub538\uc744 \ub9cc\ub098 \uc548\uc2ec\ud558\ub824\ub294 \uc21c\uac04\uc5d0 \uc544\uc9c1 \ub05d\ub098\uc9c0 \uc54a\uc740 \uc870\uac74\uc774 \ub07c\uc5b4\ub4e0\ub2e4. \ucd5c\uc885\uc801\uc73c\ub85c \ud398\ub974\uc138\ud3ec\ub124\ub294 \ud55c \ud574\uc758 \uc0bc\ubd84\uc758 \uc77c\uc744 \uc544\ub798\uc5d0\uc11c, \ub098\uba38\uc9c0\ub97c \uc5b4\uba38\ub2c8\uc640 \ub2e4\ub978 \uc2e0\ub4e4 \uacc1\uc5d0\uc11c \uc9c0\ub0b4\uac8c \ub41c\ub2e4. \ud754\ud788 \ub4e3\ub294 \ubc18\ub144\uc529\uc758 \uc124\uba85\uacfc \ub2e4\ub974\ub2e4. \uc2e0\ud654\ub97c \uc77d\uc744 \ub54c \uc5b4\ub290 \ud310\ubcf8\uc744 \ub530\ub974\ub294\uc9c0\uac00 \uc911\uc694\ud55c \uc774\uc720\ub2e4. \ud569\uc758 \ub4a4 \ub370\uba54\ud14c\ub974\ub294 \ub545\uc5d0 \ub2e4\uc2dc \uc5f4\ub9e4\uc640 \uaf43\uc774 \ub098\uac8c \ud55c\ub2e4. \ubd04\uc758 \uadc0\ud658\uacfc \uace1\uc2dd\uc758 \uc0dd\uc7a5\uc740 \uc774\uc57c\uae30\uc758 \uc911\uc694\ud55c \uc774\ubbf8\uc9c0\ub2e4. \ub2e4\ub9cc \uc774\ub97c \uc624\ub298\uc758 \ubaa8\ub4e0 \uc9c0\uc5ed\uc5d0\uc11c \ub611\uac19\uc774 \uc801\uc6a9\ub418\ub294 \uae30\uc0c1 \ubc95\uce59\ucc98\ub7fc \ubc1b\uc544\ub4e4\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774 \uc2e0\ud654\uc5d0\uc11c\ub294 \uc804\ucc28\ub97c \ud0c0\uace0 \uc5b4\ub290 \uacf3\uc73c\ub85c \uac00\ub290\ub0d0\ub9cc\ud07c \ubb34\uc5c7\uc744 \uba39\uc5c8\ub290\ub0d0\ub3c4 \uc911\uc694\ud558\ub2e4. \uc7a5\uc18c\ub97c \ub5a0\ub0ac\uc5b4\ub3c4 \uadf8\uacf3\uc758 \uc74c\uc2dd\uc744 \ubab8\uc5d0 \ubc1b\uc544\ub4e4\uc778 \uc77c\uc774 \uad00\uacc4\ub97c \ub0a8\uae34\ub2e4. \uc11d\ub958 \uc528\uc557\uc740 \ub208\uc5d0 \uc798 \ub744\uc9c0 \uc54a\ub294 \ub048\ucc98\ub7fc \uc791\ub3d9\ud55c\ub2e4. \uc5b4\uba38\ub2c8\uc758 \ud798\ub3c4 \ube44\uc2b7\ud558\uac8c \uad00\uacc4 \uc18d\uc5d0\uc11c \ub4dc\ub7ec\ub09c\ub2e4. \ub545\uacfc \uc0ac\ub78c, \uc0ac\ub78c\uacfc \uc2e0\uc758 \uc81c\ubb3c\uc774 \uc5f0\uacb0\ub418\uc5b4 \uc788\uae30 \ub54c\ubb38\uc5d0 \uc5ec\uc2e0\uc758 \uc911\ub2e8\uc740 \ubaa8\ub450\uc758 \ubb38\uc81c\uac00 \ub41c\ub2e4. \uc2e0\ub4e4\ub07c\ub9ac\uc758 \ub300\ud654 \uac19\uc9c0\ub9cc \uc778\uac04\uc758 \uc2dd\ud0c1\ub3c4 \uc774\uc57c\uae30 \ud55c\uac00\uc6b4\ub370 \uc788\ub2e4. \ub538\uc740 \ub3cc\uc544\uc624\uc9c0\ub9cc \ucc98\uc74c\uc758 \ub4e4\ud310\uc73c\ub85c \ubaa8\ub4e0 \uac83\uc774 \ub418\ub3cc\uc544\uac00\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc544\ub798 \uc138\uacc4\uc640\uc758 \uad00\uacc4\uac00 \ub0a8\uace0, \uc5b4\uba38\ub2c8\uc640 \ub538\uc740 \ub2e4\uc2dc \ub9cc\ub098\uace0 \ud5e4\uc5b4\uc9c0\ub294 \uc2dc\uac04\uc744 \uc0b4\uac8c \ub41c\ub2e4. \uae30\uc068\uacfc \uc0c1\uc2e4\uc774 \ud55c \uacb0\ub9d0 \uc548\uc5d0 \ud568\uaed8 \uc788\ub2e4. \uadf8\ub798\uc11c \uc774 \uc2e0\ud654\ub97c \uacc4\uc808\uc744 \uc678\uc6b0\ub294 \uc9e7\uc740 \uc124\uba85\uc73c\ub85c\ub9cc \ub0a8\uae30\uc9c0 \uc54a\uc544\ub3c4 \uc88b\ub2e4. \uc783\uc5b4\ubc84\ub9b0 \uc0ac\ub78c\uc744 \ucc3e\ub294 \ud798\uacfc \ub2e4\ub978 \uc774\ub4e4\uc774 \uc815\ud55c \uc9c8\uc11c\uc5d0 \ub9de\uc11c\ub294 \ub9c8\uc74c, \uc644\uc804\ud558\uc9c0 \uc54a\uc740 \uadc0\ud658\uc744 \ubc1b\uc544\ub4e4\uc774\ub294 \uacfc\uc815\uc774 \uc788\ub2e4. \uc791\uc740 \uc11d\ub958 \uc528\uc557\uc774 \uc624\ub798 \uae30\uc5b5\ub418\ub294 \uc774\uc720\ub2e4."}, {"id": "diamond-sutra-868-print-and-gift", "title": "\u300e\uae08\uac15\uacbd\u300f \u2014 \ucc9c \ub144 \uc804\uc758 \ucc45\uc740 \uc5b4\ub5bb\uac8c \uc5ec\ub7ec \ub3c5\uc790\ub97c \ub9cc\ub0ac\uc744\uae4c", "summary": "\ubd88\uad50 \uacbd\uc804\uc744 \uc0c8\uae30\uace0 \ucc0d\uc5b4 \ub0b4\ub358 \ub2f9\ub300 \uc911\uad6d\uc758 \ubb38\ud654\ub97c \uc2e4\uc81c \uc778\uc1c4\ubcf8 \ub3c4\ud310\uacfc \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/diamond-sutra-868-print-and-gift/index.html", "image": "../media/diamond-sutra-868-print-and-gift.jpg", "alt": "868\ub144 \uae08\uac15\uacbd \uc778\uc1c4\ubcf8\uc758 \ubd80\ucc98\uc640 \uccad\uc911\uc744 \ub098\ud0c0\ub0b8 \uad8c\ub450 \uadf8\ub9bc", "text": "\u300e\uae08\uac15\uacbd\u300f \u2014 \ucc9c \ub144 \uc804\uc758 \ucc45\uc740 \uc5b4\ub5bb\uac8c \uc5ec\ub7ec \ub3c5\uc790\ub97c \ub9cc\ub0ac\uc744\uae4c 868\ub144 \uc778\uc1c4\ubcf8 \ud55c \uc7a5\uc5d0\uc11c \ub9cc\ub098\ub294 \ubbff\uc74c\uacfc \ubaa9\ud310\uc758 \ud798 \ubd88\uad50 \uacbd\uc804\uc744 \uc0c8\uae30\uace0 \ucc0d\uc5b4 \ub0b4\ub358 \ub2f9\ub300 \uc911\uad6d\uc758 \ubb38\ud654\ub97c \uc2e4\uc81c \uc778\uc1c4\ubcf8 \ub3c4\ud310\uacfc \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \uc624\ub798\ub41c \ucc45\uc758 \uccab \uc7a5\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc740 \ud55c \uc778\ubb3c\uc758 \ub9d0\uc744 \ub4e3\uace0 \uc788\ub2e4. \ubd88\uad50 \uacbd\uc804 \u300e\uae08\uac15\uacbd\u300f\uc758 868\ub144 \uc778\uc1c4\ubcf8\uc5d0 \uc2e4\ub9b0 \uadf8\ub9bc\uc774\ub2e4. \uc7a5\uba74\uc740 \uc870\uc6a9\ud558\uc9c0\ub9cc, \uadf8 \uadf8\ub9bc\uacfc \uae00\uc744 \uc5ec\ub7ec \uc7a5 \ucc0d\uc5b4 \ub0bc \uc218 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uae4c\uc9c0 \uc0dd\uac01\ud558\uba74 \uc885\uc774 \ud55c \uc7a5\uc774 \uc870\uae08 \ub2e4\ub974\uac8c \ubcf4\uc778\ub2e4. \uc624\ub298\uc740 \uae00\uc744 \ubcf5\uc0ac\ud558\ub294 \ub370 \ud070 \uacb0\uc2ec\uc774 \ud544\uc694\ud558\uc9c0 \uc54a\ub2e4. \uadf8\ub7ec\ub098 \ud55c \uad8c\uc529 \uc190\uc73c\ub85c \uc62e\uaca8 \uc801\ub358 \uc138\uacc4\uc5d0\uc11c\ub294 \uac19\uc740 \ub0b4\uc6a9\uc744 \uc5ec\ub7ec \uc0ac\ub78c\uc5d0\uac8c \uc804\ud558\ub294 \uc77c\uc774 \ub9ce\uc740 \uc2dc\uac04\uc744 \uc694\uad6c\ud588\ub2e4. \uc774 \uc624\ub798\ub41c \uc778\uc1c4\ubcf8\uc740 \ucc45\uc758 \ub0b4\uc6a9\ubfd0 \uc544\ub2c8\ub77c \ucc45\uc774 \uc0ac\ub78c\uc744 \ucc3e\uc544\uac00\ub294 \ubc29\uc2dd\ub3c4 \ud568\uaed8 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ub2f9\ub300 \uc911\uad6d\uc5d0\uc11c \ubd88\uad50\ub294 \uc2e0\uc559\uacfc \uc0ac\uc0c1, \uc0dd\ud65c\uc758 \uc5ec\ub7ec \uc601\uc5ed\uc5d0 \uc601\ud5a5\uc744 \ubbf8\ucce4\ub2e4. \uacbd\uc804\uc744 \ubc30\uc6b0\uace0 \uc804\ud558\ub294 \uc77c\ub3c4 \uadf8 \ud655\uc0b0\uc758 \uc77c\ubd80\uc600\ub2e4. \uae00\uc744 \uc774\ud574\ud558\ub294 \uc0ac\ub78c\uacfc \uc9c1\uc811 \uc77d\uc9c0 \ubabb\ud558\ub294 \uc0ac\ub78c, \uac00\ub974\uce58\ub294 \uc0ac\ub78c\uacfc \ubc30\uc6b0\ub294 \uc0ac\ub78c\uc774 \uac01\uae30 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uacbd\uc804\uacfc \ub9cc\ub0ac\ub2e4. \uc5ec\uae30\uc11c \uc778\uc1c4\ub97c \uace7\ubc14\ub85c \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \ub3c5\uc11c\ub85c \uc5f0\uacb0\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ucc45\uc774 \ub298\uc5b4\ub09c\ub2e4\uace0 \ubb38\ud574\ub825\uacfc \uc811\uadfc \uc870\uac74\uc774 \ud55c\uaebc\ubc88\uc5d0 \uac19\uc544\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub798\ub3c4 \uac19\uc740 \uae00\uc744 \ub354 \ub9ce\uc774 \ub9cc\ub4e4 \uc218 \uc788\ub2e4\ub294 \ubcc0\ud654\ub294 \ubc30\uc6c0\uacfc \uc2e0\uc559\uc758 \ud1b5\ub85c\ub97c \ub113\ud788\ub294 \uc911\uc694\ud55c \uc870\uac74\uc774\uc5c8\ub2e4. \ubaa9\ud310 \uc778\uc1c4\ub294 \ub098\ubb34\ud310\uc5d0 \uae00\uacfc \uadf8\ub9bc\uc744 \uc0c8\uae30\uace0 \uba39\uc744 \ubb3b\ud600 \uc885\uc774\uc5d0 \ucc0d\ub294 \ubc29\uc2dd\uc774\ub2e4. \ucc0d\ud78c \uacb0\uacfc\uac00 \ubc14\ub974\uac8c \uc77d\ud788\ub824\uba74 \ud310\uc758 \ud615\uc0c1\uc740 \ubc18\ub300\ub85c \uc900\ube44\ub418\uc5b4\uc57c \ud55c\ub2e4. \ud3b8\ud558\uac8c \ubcf4\uc774\ub294 \ud55c \uc7a5 \ub4a4\uc5d0 \uba3c\uc800 \uac70\uafb8\ub85c \uc0dd\uac01\ud558\uace0 \uc0c8\uae30\ub294 \uc77c\uc774 \ub193\uc5ec \uc788\ub2e4. \uae00\uc744 \uc4f4 \uc0ac\ub78c\ub9cc\uc73c\ub85c \ucc45\uc774 \ub9cc\ub4e4\uc5b4\uc9c0\uc9c0 \uc54a\ub294 \uc774\uc720\ub3c4 \uc5ec\uae30\uc5d0 \uc788\ub2e4. \ud310\uc744 \ub2e4\ub8e8\ub294 \uc0ac\ub78c\uacfc \uc885\uc774, \uba39, \uc791\uc5c5\uc758 \uc9c8\uc774 \ud568\uaed8 \uacb0\uacfc\ub97c \uacb0\uc815\ud55c\ub2e4. \uc778\uc1c4\ub294 \uc190\uc758 \ub178\ub3d9\uc744 \uc5c6\uc564 \ub9c8\ubc95\uc774\ub77c\uae30\ubcf4\ub2e4, \ub9ce\uc740 \uc900\ube44\ub97c \ubc14\ud0d5\uc73c\ub85c \uac19\uc740 \ub0b4\uc6a9\uc744 \ub418\ud480\uc774\ud574 \ub9cc\ub4e4 \uc218 \uc788\uac8c \ud55c \uc791\uc5c5 \ubc29\uc2dd\uc774\uc5c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc2e4\uc81c \ub3c4\ud310\uc5d0\ub294 \ubd80\ucc98\uc640 \uadf8 \ub9d0\uc744 \ub4e3\ub294 \uc774\ub4e4\uc758 \ubaa8\uc2b5\uc774 \ub2f4\uaca8 \uc788\ub2e4. \uae00\uc904\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c4 \ucc45\uc774 \uc544\ub2c8\ub77c \uadf8\ub9bc\uc744 \ud1b5\ud574 \ub0b4\uc6a9\uc744 \ub9cc\ub0a0 \uc218 \uc788\ub294 \ubb3c\uac74\uc774\uc5c8\ub358 \uac83\uc774\ub2e4. \uc778\uc1c4\ub294 \uae00\uc790\ubfd0 \uc544\ub2c8\ub77c \uc7a5\uba74\uc744 \ubc18\ubcf5\ud574\uc11c \uc804\ud558\ub294 \ubc29\ubc95\uc774\uae30\ub3c4 \ud588\ub2e4. \uadf8\ub9bc\uc744 \ubcfc \ub54c\ub294 \uba3c\uc800 \uac00\uc6b4\ub370\uc640 \uc8fc\ubcc0\uc758 \uad00\uacc4\ub97c \uc0b4\ud3b4\ubcf4\uc790. \ub204\uac00 \ub9d0\ud558\uace0 \ub204\uac00 \uadc0\ub97c \uae30\uc6b8\uc774\ub294\uc9c0 \ub208\uc73c\ub85c \ub530\ub77c\uac08 \uc218 \uc788\ub2e4. \ubaa8\ub4e0 \uc778\ubb3c\uc758 \uba85\uce6d\uc744 \ubc14\ub85c \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4. \ud55c \uc7a5\uc774 \uc5b4\ub5bb\uac8c \ub3c5\uc790\uc758 \uc8fc\uc758\ub97c \uc774\ub044\ub294\uc9c0 \ubcf4\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \uc624\ub798\ub41c \ucc45\uc744 \uc77d\ub294 \uae38\uc774 \uc5f4\ub9b0\ub2e4. \uc774 \uc778\uc1c4\ubcf8\uc774 \uc790\uc8fc \uc18c\uac1c\ub418\ub294 \uc774\uc720 \uac00\uc6b4\ub370 \ud558\ub098\ub294 868\ub144\uc774\ub77c\ub294 \uc81c\uc791 \uc2dc\uc810\uc744 \uc54c \uc218 \uc788\ub2e4\ub294 \uc810\uc774\ub2e4. \ub9c9\uc5f0\ud788 \uc624\ub798\ub41c \ucc45\uc774\ub77c\uace0 \ubd80\ub97c \ub54c\uc640 \ud2b9\uc815\ud55c \uc2dc\uae30\uc758 \ubb3c\uac74\uc73c\ub85c \ubc14\ub77c\ubcfc \ub54c\ub294 \uc5ed\uc0ac \uc18d \uc790\ub9ac\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \ub2f9\ub300\uc758 \uc2e0\uc559\uacfc \uc81c\uc791 \uae30\uc220\uc774\ub77c\ub294 \ub9e5\ub77d \uc18d\uc5d0 \ub193\uc744 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc774\uac83\uc744 \uc778\ub958\uac00 \ucc98\uc74c\uc73c\ub85c \ubb34\uc5b8\uac00\ub97c \uc778\uc1c4\ud55c \uc21c\uac04\uc774\ub77c\uace0 \ub2e8\uc815\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ub0a8\uc544 \uc788\ub294 \uc790\ub8cc\uc640 \ucc98\uc74c \ubc1c\uba85\ub41c \ub54c\ub294 \uac19\uc740 \uc9c8\ubb38\uc774 \uc544\ub2c8\ub2e4. \uac00\uc7a5 \uc624\ub798\ub418\uc5c8\ub2e4\ub294 \uc21c\uc704\ub97c \uc11c\ub458\ub7ec \ubd99\uc774\uae30\ubcf4\ub2e4, \uc774 \uc790\ub8cc\uac00 \ubb34\uc5c7\uc744 \ud655\uc2e4\ud558\uac8c \ubcf4\uc5ec \uc8fc\ub294\uc9c0 \uc0b4\ud53c\ub294 \ud3b8\uc774 \ub354 \ub9ce\uc740 \uac83\uc744 \uc54c\ub824 \uc900\ub2e4. \uac19\uc740 \ud310\uc744 \uc0ac\uc6a9\ud558\uba74 \uac19\uc740 \ub0b4\uc6a9\uc744 \ubc18\ubcf5\ud574\uc11c \ucc0d\uc744 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc885\uc774\uc758 \uc0c1\ud0dc\uc640 \uba39\uc758 \ub18d\ub3c4, \ud310\uc758 \ub9c8\ubaa8, \ubcf4\uc874 \uacfc\uc815\uc740 \uac1c\ubcc4 \uc778\uc1c4\ubb3c\uc758 \ubaa8\uc2b5\uc5d0 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\ub2e4. \uc624\ub298\uc758 \ubcf5\uc0ac\ubcf8\uc744 \ub5a0\uc62c\ub9ac\ub418 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \uc791\uc5c5 \ud658\uacbd\uc774\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\ub2e4. \uc6d0\ubcf8\uacfc \ubcf5\uc81c\ub77c\ub294 \ub9d0\ub3c4 \uc5ec\uae30\uc11c\ub294 \uc870\uae08 \ubcf5\uc7a1\ud574\uc9c4\ub2e4. \uc778\uc1c4\ub41c \ucc45\uc740 \ucc98\uc74c\ubd80\ud130 \uc5ec\ub7ec \uc7a5\uc744 \ub9cc\ub4e4\uae30 \uc704\ud574 \uc900\ube44\ub41c \ubb3c\uac74\uc774\ub2e4. \ub611\uac19\uc740 \ub0b4\uc6a9\uc774 \uc788\ub2e4\ub294 \uc774\uc720\ub85c \ud55c \uc7a5\uc758 \uac00\uce58\uac00 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uc5b4\ub5bb\uac8c \ucc0d\ud788\uace0 \ub0a8\uc558\ub294\uc9c0\uac00 \ub2e4\uc2dc \uadf8 \ubb3c\uac74\uc758 \uc774\ub825\uc774 \ub41c\ub2e4. \ub2f9\ub300\uc5d0 \ubd88\uad50\uac00 \ub110\ub9ac \ud37c\uc84c\ub2e4\uace0 \ud574\uc11c \uad6d\uac00\uc640 \uc5b8\uc81c\ub098 \ud3b8\uc548\ud55c \uad00\uacc4\ub97c \uc720\uc9c0\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. OpenStax\ub294 9\uc138\uae30 \uc911\uc5fd \ubd88\uad50\uc758 \uc601\ud5a5\ub825\uc744 \ub458\ub7ec\uc2fc \uae34\uc7a5\uacfc \ud0c4\uc555\ub3c4 \ud568\uaed8 \uc124\uba85\ud55c\ub2e4. \uacbd\uc804\uc758 \ubcf4\uae09\uc774\ub77c\ub294 \ubc1d\uc740 \uc7a5\uba74\ub9cc \uc774\uc5b4 \ub193\uc73c\uba74 \uadf8 \uacbd\uc804\uc744 \ub458\ub7ec\uc2fc \uc0ac\ub78c\ub4e4\uc758 \ubd88\uc548\ud55c \ucc98\uc9c0\ub294 \ubcf4\uc774\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \ucc45\uc758 \uc5ed\uc0ac\ub294 \uae30\uc220\uc758 \ubc1c\uc804\uacfc \uc815\uce58\uc758 \ubcc0\ud654\uac00 \ub9cc\ub098\ub294 \uacf3\uc774\ub2e4. \uc774 \uc778\uc1c4\ubcf8 \ud55c \uc810\uc774 \uadf8 \ubaa8\ub4e0 \uac08\ub4f1\uc758 \uc9c1\uc811\uc801\uc778 \ud604\uc7a5\uc744 \ubcf4\uc5ec \uc900\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uac19\uc740 \uc2dc\ub300\uc5d0 \uc5ec\ub7ec \ud750\ub984\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4\ub294 \ub9e5\ub77d\uc744 \uc81c\uacf5\ud55c\ub2e4. \ub0a8\uc544 \uc788\ub294 \ucc45\uc744 \ubcf4\uba70 \uc65c \ub9cc\ub4e4\uc5c8\ub294\uc9c0\ub9cc \ubb3b\ub294 \ub370\uc11c \ud55c \uac78\uc74c \ub354 \ub098\uc544\uac00, \uc5b4\ub5bb\uac8c \uc804\ud574\uc9c0\uace0 \uc5b4\ub5a4 \ud658\uacbd\uc5d0\uc11c \ub0a8\uc744 \uc218 \uc788\uc5c8\ub294\uc9c0\ub3c4 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uc885\uc774 \ud55c \uc7a5\uc758 \uc0dd\uc874\ub3c4 \ub2f9\uc5f0\ud55c \uacb0\uacfc\ub294 \uc544\ub2c8\uc5c8\ub2e4. \uc774\uc57c\uae30\uc758 \ub05d\uc5d0\uc11c \ub2e4\uc2dc \ub3c4\ud310\uc744 \ubcf4\uc790. \ubd80\ucc98\uc758 \ub9d0\uc744 \ub4e3\ub294 \uc778\ubb3c\ub4e4 \ubc14\uae65\uc5d0\ub3c4 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc788\ub2e4. \uae00\uc744 \uc804\ud558\uace0, \ud310\uc744 \uc0c8\uae30\uace0, \uc885\uc774\ub97c \ub9c8\ub828\ud558\uace0, \ucc45\uc744 \ubcf4\uad00\ud55c \uc0ac\ub78c\ub4e4\uc774\ub2e4. \ud55c \uc7a5\uc758 \ucc45\uc740 \uc5ec\ub7ec \uc5ed\ud560\uc774 \ub9cc\ub09c \uacb0\uacfc\ub85c \ub0a8\uc558\ub2e4. \uc911\uad6d\uc758 \uc624\ub798\ub41c \uc778\uc1c4 \ubb38\ud654\ub97c \uc77d\ub294 \uc990\uac70\uc6c0\uc740 \ubc1c\uba85\uc758 \uc21c\uc704\ub97c \uc678\uc6b0\ub294 \ub370\ub9cc \uc788\uc9c0 \uc54a\ub2e4. \ub204\uad70\uac00 \uc911\uc694\ud558\ub2e4\uace0 \uc5ec\uae34 \ub9d0\uc744 \ub354 \uba40\ub9ac \ubcf4\ub0b4\ub824 \ud588\ub2e4\ub294 \uc0ac\uc2e4\uc5d0 \uc788\ub2e4. \ud654\uba74\uc5d0\uc11c \uc774 \uadf8\ub9bc\uc744 \ub9cc\ub098\ub294 \uc9c0\uae08\uc758 \uc6b0\ub9ac\ub3c4, \ub9e4\uccb4\ub294 \ub2ec\ub77c\uc84c\uc9c0\ub9cc \uadf8 \uae34 \uc804\ub2ec\uc758 \ub9e8 \ub4a4\uc5d0 \uc7a0\uc2dc \uc11c \uc788\ub294 \uc148\uc774\ub2e4. \uadf8\ub9bc\uc758 \uac00\uc7a5\uc790\ub9ac\uc640 \uc774\uc5b4\uc9c0\ub294 \uc120\ub3c4 \ud568\uaed8 \uc0b4\ud3b4\ubcf4\uc790. \ub0b4\uc6a9\uacfc \uc81c\uc791, \uac10\uc0c1\uacfc \uc804\ub2ec\uc774 \ub9cc\ub098\ub294 \uc9c0\uc810\uc774\ub2e4. \uc624\ub798\ub41c \ucc45\uc758 \uac00\uce58\ub294 \uae00\uc744 \uc774\ud574\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub9cc \uc5f4\ub9ac\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uadf8 \ubb3c\uac74\uc774 \ub9cc\ub4e4\uc5b4\uc9c4 \ubc29\uc2dd\uc744 \ubc14\ub77c\ubcf4\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub3c4 \uc5f4\ub824 \uc788\ub2e4."}, {"id": "dokseodang-gathering", "title": "\uadf8\ub9bc \uc18d \ubc43\ub180\uc774\uc5d0\ub294 \ucc38\uc11d\uc790 \uba85\ub2e8\uc774 \uc788\ub2e4", "summary": "\ud55c\uac15\uc5d0\uc11c \ubc30\ub97c \ud0c4 \uc0ac\ub78c\ub4e4, \uadf8\ub9ac\uace0 \uadf8\ub9bc \uc544\ub798 \ube7d\ube7d\ud55c \uae00\uc528. \uc624\ub798\ub41c \ubaa8\uc784 \uadf8\ub9bc\uc5d0\ub294 \ub204\uac00 \ud568\uaed8\ud588\ub294\uc9c0\ub3c4 \uc801\ud600 \uc788\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/dokseodang-gathering/index.html", "image": "../media/dokseodang-gathering.jpg", "alt": "\uc704\ucabd \uc81c\ubaa9\uacfc \uac00\uc6b4\ub370 \ud55c\uac15 \ud48d\uacbd, \uc544\ub798\ucabd \ucc38\uc11d\uc790 \uba85\ub2e8\uc73c\ub85c \uad6c\uc131\ub41c \ub3c5\uc11c\ub2f9\uacc4\ud68c\ub3c4 \uc871\uc790 \uc804\uccb4", "text": "\uadf8\ub9bc \uc18d \ubc43\ub180\uc774\uc5d0\ub294 \ucc38\uc11d\uc790 \uba85\ub2e8\uc774 \uc788\ub2e4 \ub3c5\uc11c\ub2f9\uacc4\ud68c\ub3c4\uc5d0 \ub0a8\uc740 \uc5f4\ub450 \uc0ac\ub78c\uc758 \ubaa8\uc784 \ud55c\uac15\uc5d0\uc11c \ubc30\ub97c \ud0c4 \uc0ac\ub78c\ub4e4, \uadf8\ub9ac\uace0 \uadf8\ub9bc \uc544\ub798 \ube7d\ube7d\ud55c \uae00\uc528. \uc624\ub798\ub41c \ubaa8\uc784 \uadf8\ub9bc\uc5d0\ub294 \ub204\uac00 \ud568\uaed8\ud588\ub294\uc9c0\ub3c4 \uc801\ud600 \uc788\uc2b5\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \uc61b \uadf8\ub9bc\uc744 \ubcfc \ub54c \uae00\uc528\ub294 \uc77c\ub2e8 \uac74\ub108\ub6f0\uac8c \ub41c\ub2e4. \uc0b0\uc774 \uc5b4\ub514 \uc788\ub294\uc9c0, \uc0ac\ub78c\uc740 \ubb34\uc5c7\uc744 \ud558\ub294\uc9c0\ubd80\ud130 \ucc3e\uc544\ubcf4\ub294 \ud3b8\uc774 \uc27d\ub2e4. \ud55c\uc790\uac00 \ube7d\ube7d\ud558\uac8c \uc801\ud600 \uc788\uc73c\uba74 \uadf8\ub9bc \uc124\uba85\uc774\uaca0\uac70\ub2c8 \ud558\uace0 \uc9c0\ub098\uce58\uae30\ub3c4 \ud55c\ub2e4. \uadf8\ub7f0\ub370 \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \u300c\ub3c5\uc11c\ub2f9\uacc4\ud68c\ub3c4\u300d\uc5d0\uc11c\ub294 \uc544\ub798\ucabd \uae00\uc528\uc5d0\ub3c4 \uc7a0\uae50 \ub208\uc744 \uc8fc\uba74 \uc88b\uaca0\ub2e4. \uac70\uae30\uc5d0\ub294 \uc774 \ubaa8\uc784\uc5d0 \ucc38\uc11d\ud55c \uc0ac\ub78c\ub4e4\uc758 \uc774\ub984\uc774 \uc801\ud600 \uc788\ub2e4. \uadf8\ub9bc \uc18d\uc5d0\uc11c\ub294 \uad00\ubcf5 \ucc28\ub9bc\uc758 \uc0ac\ub78c\ub4e4\uc774 \ud55c\uac15\uc5d0\uc11c \ubc43\ub180\uc774\ub97c \ud55c\ub2e4. \ub290\uae0b\ud55c \ud48d\uacbd\ud654\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc, \uc791\ud488\uc740 \ubaa8\uc784\uc758 \uae30\uc5b5\uacfc \ucc38\uc11d\uc790 \uc815\ubcf4\ub97c \ud568\uaed8 \ub0a8\uaca8 \ub450\uc5c8\ub2e4. \uc624\ub298\uc758 \ub2e8\uccb4 \uae30\ub150\uc0ac\uc9c4 \ub4a4\uc5d0 \uc774\ub984\uc744 \uc801\uc5b4 \ub193\ub294 \ubaa8\uc2b5\uc774 \uc870\uae08 \ub5a0\uc624\ub978\ub2e4. \uc81c\ubaa9\uc758 \u2018\uacc4\ud68c\ub3c4\u2019\ub294 \ubaa8\uc784\uc744 \uae30\ub150\ud558\ub294 \uadf8\ub9bc\uc774\ub77c\ub294 \ub73b\uc73c\ub85c \uc77d\uc73c\uba74 \ub41c\ub2e4. \uc774 \uc791\ud488\uc740 \uc0ac\uac00\ub3c5\uc11c\ud55c \uc774\ub825\uc774 \uc788\ub294 \uad00\ub8cc\ub4e4\uc758 \ubaa8\uc784\uc744 \uae30\ub150\ud574 \ub9cc\ub4e4\uc5c8\ub2e4\uace0 \ubc15\ubb3c\uad00\uc740 \uc124\uba85\ud55c\ub2e4. \uc0ac\uac00\ub3c5\uc11c\ub294 \ud734\uac00\ub97c \ubc1b\uc544 \ub3c5\uc11c\uc5d0 \uc804\ub150\ud558\ub294 \uc77c\uc744 \uac00\ub9ac\ud0a8\ub2e4. \ucc45 \uc77d\ub358 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc600\ub2e4\uace0 \ud558\ub2c8 \uadf8\ub9bc \uc18d\uc5d0\uc11c\ub3c4 \ubaa8\ub450 \ucc45\uc0c1 \uc55e\uc5d0 \uc549\uc544 \uc788\uc744 \uac83 \uac19\ub2e4. \ud558\uc9c0\ub9cc \uae30\ub85d\ub41c \ubaa8\uc784\uc758 \ubaa8\uc2b5\uc740 \ub2e4\ub974\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \ubc30\ub97c \ud0d4\uace0, \uadf8 \uc8fc\ubcc0\uc73c\ub85c \uac15\uacfc \uc0b0\uc774 \ud3bc\uccd0\uc838 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \uad00\ub9ac\ub4e4\uc774 \ubab0\ub798 \uc77c\uc744 \ube7c\uba39\uc5c8\ub2e4\uace0 \uc0c1\uc0c1\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8\ub9bc\uc740 \ubaa8\uc784\uc758 \ud55c \uc7a5\uba74\uc744 \ubcf4\uc5ec\uc904 \ubfd0, \uc0ac\ub78c\ub4e4\uc774 \uc8fc\uace0\ubc1b\uc740 \ub9d0\uc774\ub098 \uadf8\ub0a0\uc758 \uc18d\uc0ac\uc815\uae4c\uc9c0 \uc54c\ub824\uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uad00\ubcf5\uacfc \ubc43\ub180\uc774\uac00 \ud55c \ud654\uba74\uc5d0 \uc788\ub2e4\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \ucda9\ubd84\ud788 \ub208\uae38\uc744 \ub048\ub2e4. \ud48d\uacbd\uc740 \ub9c9\uc5f0\ud788 \uba4b\uc9c4 \uc0b0\uc218\ub97c \uadf8\ub824 \ub123\uc740 \uac83\ub9cc\uc740 \uc544\ub2c8\ub2e4. \ubc15\ubb3c\uad00\uc740 \ub3c5\uc11c\ub2f9\uc774 \uc788\ub358 \ud55c\uac15\ubcc0 \ub450\ubaa8\ud3ec, \uc9c0\uae08\uc758 \uc11c\uc6b8 \uc131\ub3d9\uad6c \uc625\uc218\ub3d9 \uc77c\ub300\uac00 \ubb18\uc0ac\ub418\uc5b4 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud654\uba74 \uac00\uc6b4\ub370 \uc19f\uc740 \uc751\ubd09\uc740 \ud604\uc7ac\uc758 \ub9e4\ubd09\uc0b0\uc5d0 \ud574\ub2f9\ud55c\ub2e4. \uc9c0\uae08 \uc544\ub294 \uc11c\uc6b8\uc758 \uc9c0\uba85\uacfc \uc5f0\uacb0\ud574 \ubcf4\uba74 \uc624\ub798\ub41c \uadf8\ub9bc\uc774 \uc870\uae08 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \ud48d\uacbd\uc744 \ud1b5\uc9f8\ub85c \ud604\uc7ac\uc758 \uc9c0\ub3c4\uc640 \ub9de\ucd9c \ud544\uc694\ub294 \uc5c6\ub2e4. \ud55c\uac15\ubcc0\uc758 \uc5b4\ub290 \uc7a5\uc18c\ub97c \uae30\uc5b5\ud558\uba70 \uadf8\ub838\ub2e4\ub294 \ub2e8\uc11c \uc815\ub3c4\ub9cc \ucc59\uaca8\ub3c4 \uc88b\ub2e4. \uc774 \uc791\ud488\uc740 \uc704\uc5d0\uc11c \uc544\ub798\ub85c \uc77d\ub294 \uc21c\uc11c\uac00 \uc788\ub2e4. \ub9e8 \uc704\uc5d0\ub294 \uc81c\ubaa9, \uac00\uc6b4\ub370\uc5d0\ub294 \ubaa8\uc784 \uc7a5\uba74, \uc544\ub798\uc5d0\ub294 \ucc38\uc11d\uc790 \uba85\ub2e8\uc774 \ub193\uc778\ub2e4. \uba40\ub9ac\uc11c \ubcf4\uba74 \uae34 \uc871\uc790 \ud558\ub098\uc9c0\ub9cc, \uac00\uae4c\uc774\uc5d0\uc11c\ub294 \uc11c\ub85c \ub2e4\ub978 \uc77c\uc744 \ud558\ub294 \uc138 \ubd80\ubd84\uc774 \ubaa8\uc5ec \uc788\ub2e4. \uc544\ub798\ucabd \uba85\ub2e8\uc740 \u2018\uc88c\ubaa9\u2019\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \uc774 \uadf8\ub9bc\uc758 \uc88c\ubaa9\uc5d0\ub294 \uc5f4\ub450 \uc0ac\ub78c\uc758 \ud638\uc640 \uc774\ub984\ubfd0 \uc544\ub2c8\ub77c \ubcf8\uad00\uacfc \uc0dd\ub144, \uacfc\uac70\uc5d0 \uae09\uc81c\ud55c \uc5f0\ub3c4, \uc0ac\uac00\ub3c5\uc11c\ub97c \ud55c \uc2dc\uae30, \ub2f9\uc2dc \ud488\uacc4\uc640 \uad00\uc9c1\uae4c\uc9c0 \uc801\ud600 \uc788\ub2e4. \uc774\ub984\ub9cc \uc801\uc5b4\ub3c4 \uae30\ub150\uc740 \ub420 \ud150\ub370 \uaf64 \uaf3c\uaf3c\ud558\ub2e4. \ubaa8\uc784\uc5d0 \ub204\uac00 \uc788\uc5c8\ub294\uc9c0\uc640 \uadf8 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5a4 \uc774\ub825\uc744 \uc9c0\ub154\ub294\uc9c0\ub97c \ud568\uaed8 \ub0a8\uacbc\ub2e4. \ud6c4\ub300\uc758 \uad00\ub78c\uac1d\uc5d0\uac8c\ub294 \uadf8\ub9bc \uc606\uc5d0 \uc791\uc740 \uc778\ubb3c \uc18c\uac1c\uac00 \ubd99\uc5b4 \uc788\ub294 \uc148\uc774\ub2e4. \uc6b0\ub9ac\uac00 \uba85\ub2e8\uc758 \ud55c\uc790\ub97c \ubaa8\ub450 \uc77d\uc5b4\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub9bc\uc5d0\uc11c \uc0ac\ub78c\uc744 \ucc3e\uc740 \ub4a4 \uc544\ub798\uc758 \uae00\uc528\ub85c \ub208\uc744 \uc62e\uaca8 \ubcf4\uba74 \ub41c\ub2e4. \ub208\uc55e\uc758 \uc7a5\uba74\uacfc \uadf8 \uc7a5\uba74\uc5d0 \ucc38\uc5ec\ud55c \uc0ac\ub78c\ub4e4\uc758 \uae30\ub85d\uc774 \ud55c \uc791\ud488 \uc548\uc5d0 \ub098\ub780\ud788 \uc788\ub2e4\ub294 \uc810\uc744 \uc54c\uc544\ubcf4\ub294 \uac83\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4. \uadf8\ub9bc\uc5d0 \uc5f0\ub3c4\uac00 \ud06c\uac8c \uc4f0\uc5ec \uc788\uc9c0 \uc54a\uc544\ub3c4 \uba85\ub2e8\uc740 \uc81c\uc791 \uc2dc\uae30\ub97c \ucd94\uc815\ud560 \ub2e8\uc11c\uac00 \ub41c\ub2e4. \uc5b4\ub5a4 \uc778\ubb3c\uc774 \uc5b4\ub5a4 \uad00\uc9c1\uc5d0 \uc788\uc5c8\ub2e4\ub294 \uae30\ub85d\uc740 \uadf8 \uc0ac\ub78c\uc758 \uc0dd\uc560 \uac00\uc6b4\ub370 \ud2b9\uc815\ud55c \ubc94\uc704\uc640 \uc5f0\uacb0\ub41c\ub2e4. \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc774\ub825\uc774 \uacb9\uce58\ub294 \ub54c\ub97c \ube44\uad50\ud558\uba74 \uac00\ub2a5\ud55c \uc2dc\uac04\uc744 \ub354 \uc881\ud600 \ubcfc \uc218 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc774 1531\ub144\uacbd\uc774\ub77c\ub294 \uc2dc\uae30\ub97c \uc81c\uc2dc\ud558\ub294 \ubc30\uacbd\uc774\ub2e4. \uc5ec\uae30\uc11c \uc911\uc694\ud55c \uac83\uc740 \ud55c \uc0ac\ub78c\uc758 \uc774\ub984\uc744 \uc54c\uc544\ubcf4\ub294 \ub370\uc11c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc774\ub2e4. \ucc38\uc11d\uc790 \uc5f4\ub450 \uba85\uc758 \uc815\ubcf4\uac00 \ud568\uaed8 \ub193\uc600\uae30\uc5d0 \uc11c\ub85c \ube44\uad50\ud560 \uae38\uc774 \uc0dd\uae34\ub2e4. \uc791\uc740 \uae00\uc528\ub97c \uc7a5\uc2dd\uc801\uc778 \ubd80\ub85d\uc73c\ub85c\ub9cc \ubcf4\uba74 \ub193\uce58\ub294 \uae30\ub2a5\uc774\ub2e4. \ud48d\uacbd\uacfc \uc778\ubb3c\uc740 \ubaa8\uc784\uc758 \ubaa8\uc2b5\uc744 \ub0a8\uae30\uace0, \uc88c\ubaa9\uc740 \uadf8 \uc7a5\uba74\uc744 \uc5ed\uc0ac \uc18d \uc0ac\ub78c\uacfc \uc2dc\uac04\uc73c\ub85c \uc5f0\uacb0\ud574 \uc900\ub2e4. \ub450\ubaa8\ud3ec\uc640 \uc751\ubd09\uc774\ub77c\ub294 \uc9c0\uba85\uc740 \uc9c0\uae08\uc758 \ub3c4\uc2dc \ud48d\uacbd\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc61b \uadf8\ub9bc\uc744 \uc624\ub298\uc758 \ud56d\uacf5\uc0ac\uc9c4\ucc98\ub7fc \ub9de\ucd94\ub824 \ud558\uba74 \uc5b4\ub824\uc6c0\uc774 \uc0dd\uae34\ub2e4. \ud654\uac00\ub294 \uae30\uc5b5\ud560 \uc7a5\uc18c\uc640 \uae30\ub150\ud560 \ubaa8\uc784\uc744 \ud654\uba74\uc5d0 \ubc30\uce58\ud588\uace0 \uc138\ubd80\uc758 \uac70\ub9ac\uc640 \ubc29\ud5a5\uc744 \uc0ac\uc9c4\uacfc \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uae30\ub85d\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2e4\uc81c \uc7a5\uc18c\ub97c \uac00\ub9ac\ud0a8\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uacf5\uac04 \uc804\uccb4\uac00 \uc815\ubc00 \uc9c0\ub3c4\ub77c\ub294 \uc8fc\uc7a5\uc740 \ub2e4\ub974\ub2e4. \uadf8\ub798\ub3c4 \uc9c0\uba85\uc744 \uc54c\uc544\ub450\uba74 \uc0b0\uc218\ub294 \uc774\ub984 \uc5c6\ub294 \ubc30\uacbd\uc5d0\uc11c \ubc97\uc5b4\ub09c\ub2e4. \ucc45\uc744 \uc77d\ub358 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5a4 \uc7a5\uc18c\ub97c \ud568\uaed8 \uae30\uc5b5\ud588\ub294\uc9c0 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uae00\uacfc \ud48d\uacbd\uc744 \ubc88\uac08\uc544 \ubcf4\uba70 \uc775\uc219\ud55c \uc11c\uc6b8\uc758 \ub2e4\ub978 \uc2dc\uac04\uc744 \ub9cc\ub098 \ubcf4\uc790. \ud589\uc815\uacfc \ub3c5\uc11c, \ud734\uc2dd\uc774 \ud55c \ud654\uba74\uc5d0 \ub193\uc778\ub2e4\ub294 \uc810\ub3c4 \uc774 \ubaa8\uc784 \uadf8\ub9bc\uc758 \uc7ac\ubbf8\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc774 \uc791\ud488\uc744 1531\ub144\uacbd\uc758 \uadf8\ub9bc\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \ud654\uba74\uc758 \uc5b4\ub290 \uad6c\uc11d\uc5d0 \ud070 \uc22b\uc790\ub85c \uc5f0\ub3c4\uac00 \uc801\ud600 \uc788\uc5b4\uc11c\uc77c\uae4c? \uc124\uba85\uc5d0 \ub530\ub974\uba74 \uc81c\uc791 \uc2dc\uae30\ub97c \ucd94\uc815\ud558\ub294 \uadfc\uac70\ub294 \uc88c\ubaa9\uc5d0 \uc801\ud78c \uad00\uc9c1\uc774\ub2e4. \ub4f1\uc7a5\uc778\ubb3c\ub4e4\uc774 \uc5b8\uc81c \uc5b4\ub5a4 \uc790\ub9ac\uc5d0 \uc788\uc5c8\ub294\uc9c0\ub97c \uc0b4\ud53c\uba74, \uadf8\ub9bc\uc774 \ub9cc\ub4e4\uc5b4\uc9c4 \ub54c\ub97c \uc881\ud600 \ubcfc \uc218 \uc788\ub2e4. \ud48d\uacbd\ubcf4\ub2e4 \uc544\ub798\ucabd\uc758 \uae00\uc528\uac00 \ub0a0\uc9dc\uc758 \ub2e8\uc11c\ub97c \uc8fc\ub294 \uac83\uc774\ub2e4. \uc5ec\uae30\uc11c \u2018\uacbd\u2019\uc774\ub77c\ub294 \ub9d0\ub3c4 \ub193\uce58\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. 1531\ub144\uc758 \uc5b4\ub290 \ud558\ub8e8\ub97c \uc815\ud655\ud558\uac8c \ud655\uc778\ud588\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub0a8\uc544 \uc788\ub294 \uc815\ubcf4\ub97c \ubc14\ud0d5\uc73c\ub85c \uadf8 \ubb34\ub835\uc774\ub77c\uace0 \ucd94\uc815\ud55c\ub2e4\ub294 \ub73b\uc774\ub2e4. \ubaa8\ub974\ub294 \ubd80\ubd84\uae4c\uc9c0 \ucc44\uc6cc \ub123\uc9c0 \uc54a\uc544\ub3c4 \uadf8\ub9bc\uc758 \uc7ac\ubbf8\uac00 \uc904\uc5b4\ub4e4\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub2e8\uccb4\uc0ac\uc9c4\uc744 \uc624\ub798 \ubcf4\uad00\ud558\ub2e4\uac00 \ub204\uad70\uac00\uc758 \uc774\ub984\uc774\ub098 \ub2f9\uc2dc\uc758 \uc77c\uc744 \ub5a0\uc62c\ub9b0 \uacbd\ud5d8\uc774 \uc788\uc744 \uac83\uc774\ub2e4. \uc774 \uadf8\ub9bc\uc5d0\uc11c\ub294 \uadf8 \ub2e8\uc11c\uac00 \uc791\ud488 \uc544\ub798\uc5d0 \ucc98\uc74c\ubd80\ud130 \ud568\uaed8 \uc801\ud600 \uc788\uc5c8\ub2e4. \ub2e4\uc74c\uc5d0 \uc61b \uadf8\ub9bc \uc18d\uc758 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc5ec \uc788\ub294 \uc7a5\uba74\uc744 \ub9cc\ub098\uba74 \ud48d\uacbd\ub9cc \ubcf4\uace0 \uc9c0\ub098\uce58\uc9c0 \ub9d0\uace0 \uc8fc\ubcc0\uc758 \uae00\uc528\ub3c4 \ud55c\ubc88 \uc0b4\ud3b4\ubcf4\uc790. \uc77d\uae30 \uc5b4\ub824\uc6b4 \uae00\uc790 \uc0ac\uc774\uc5d0, \ub204\uac00 \ud568\uaed8\ud588\ub294\uc9c0 \uc78a\uc9c0 \uc54a\uc73c\ub824 \ub0a8\uae34 \uba85\ub2e8\uc774 \uc788\uc744\uc9c0\ub3c4 \ubaa8\ub978\ub2e4."}, {"id": "don-quixote-windmills-and-sancho", "title": "\u300e\ub3c8\ud0a4\ud638\ud14c\u300f \u2014 \ud48d\ucc28\uac00 \uac70\uc778\uc73c\ub85c \ubcf4\uc774\ub294 \uc0ac\ub78c", "summary": "\ud48d\ucc28 \ubaa8\ud5d8\uacfc \uc5ec\uc815\uc758 \uacb0\ub9d0\uc744 \ud1b5\ud574 \uc774\uc0c1\uacfc \ucc29\uac01, \ud568\uaed8 \uac77\ub294 \ub450 \uc0ac\ub78c\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/don-quixote-windmills-and-sancho/index.html", "image": "../media/don-quixote-windmills-and-sancho.png", "alt": "\ud48d\ucc28\uac00 \uc788\ub294 \ub4e4\ud310\uc744 \ub9d0 \ud0c4 \uae30\uc0ac\uc640 \ub2f9\ub098\uadc0 \ud0c4 \ub3d9\ud589\uc790\uac00 \uc9c0\ub098\uac00\ub294 \ub3c8\ud0a4\ud638\ud14c\uc758 \uc18c\uc124 \uc0bd\ud654", "text": "\u300e\ub3c8\ud0a4\ud638\ud14c\u300f \u2014 \ud48d\ucc28\uac00 \uac70\uc778\uc73c\ub85c \ubcf4\uc774\ub294 \uc0ac\ub78c \uc6c3\uc74c \ub4a4\uc5d0\uc11c \uc0b0\ucd08\uc758 \ubaa9\uc18c\ub9ac\ub97c \ud568\uaed8 \ub4e4\uc5b4\uc57c \ud558\ub294 \uc774\uc720 \ud48d\ucc28 \ubaa8\ud5d8\uacfc \uc5ec\uc815\uc758 \uacb0\ub9d0\uc744 \ud1b5\ud574 \uc774\uc0c1\uacfc \ucc29\uac01, \ud568\uaed8 \uac77\ub294 \ub450 \uc0ac\ub78c\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \ub4e4\ud310\uc758 \ud48d\ucc28\ub97c \ubcf8 \ub0a8\uc790\uac00 \ucc3d\uc744 \uaca8\ub204\uace0 \ub2ec\ub824\ub4e0\ub2e4. \uadf8\uc758 \ub208\uc5d0\ub294 \uae34 \ud314\uc744 \ud718\ub450\ub974\ub294 \uac70\uc778\uc774 \ubcf4\uc778\ub2e4. \uacc1\uc758 \ub3d9\ud589\uc790\uac00 \ud48d\ucc28\uc77c \ubfd0\uc774\ub77c\uace0 \ub9d0\ud574\ub3c4 \uc18c\uc6a9\uc5c6\ub2e4. \ub3c8\ud0a4\ud638\ud14c\ub294 \uc774\ubbf8 \uc790\uc2e0\uc774 \ub4e4\uc5b4\uac08 \uc774\uc57c\uae30\uc758 \uc885\ub958\ub97c \uc815\ud574 \ub193\uc558\ub2e4. \uc138\ub974\ubc18\ud14c\uc2a4\uc758 \uc18c\uc124\uc5d0\uc11c \uac00\uc7a5 \uc720\uba85\ud55c \uc7a5\uba74\uc774\uc9c0\ub9cc, \uc791\ud488 \uc804\uccb4\uac00 \uc774 \ud55c \ubc88\uc758 \uc2e4\uc218\ub85c \ub05d\ub098\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c\ub294 \ud48d\ucc28 \ubaa8\ud5d8\uc744 \uc785\uad6c\ub85c \uc0bc\uc544 \ub450 \uc8fc\uc778\uacf5\uc758 \uc5ec\uc815\uacfc \uacb0\ub9d0\uae4c\uc9c0 \uc0b4\ud3b4\ubcf8\ub2e4. \uc6c3\uae30\ub294 \uae30\uc0ac \ud55c \uc0ac\ub78c\ub9cc \uae30\uc5b5\ud558\uae30\uc5d0\ub294 \uadf8 \uae38\uc5d0 \ub108\ubb34 \ub2e4\uc591\ud55c \uc0ac\ub78c\ub4e4\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \uc2dc\uace8\uc758 \ud55c \uc2e0\uc0ac\uac00 \uae30\uc0ac\ub3c4 \uc774\uc57c\uae30\uc5d0 \uae4a\uc774 \ube60\uc9c4\ub2e4. \ub9c8\uce68\ub0b4 \uc790\uc2e0\ub3c4 \ud3b8\ub825 \uae30\uc0ac\uac00 \ub418\uc5b4 \uc138\uc0c1\uc758 \ubd88\uc758\ub97c \ubc14\ub85c\uc7a1\uaca0\ub2e4\uace0 \ub098\uc120\ub2e4. \ub0a1\uc740 \uac11\uc637\uc744 \ucc59\uae30\uace0 \ub9d0\uc5d0\uac8c \ub85c\uc2dc\ub09c\ud14c\ub77c\ub294 \uc774\ub984\uc744 \ubd99\uc774\uba70, \uc790\uc2e0\uc758 \ud589\ub3d9\uc744 \ubc14\uce60 \uadc0\ubd80\uc778\ub3c4 \ub458\uc2dc\ub124\uc544\ub77c\uace0 \ubd80\ub978\ub2e4. \ud604\uc2e4\uc758 \uc0dd\ud65c\uc5d0 \uc77d\uc5b4 \uc628 \ucc45\uc758 \ud2c0\uc744 \uc50c\uc6b0\uae30 \uc2dc\uc791\ud55c \uac83\uc774\ub2e4. \uc5ec\uae30\uc11c \uc0c1\uc0c1\ub825\uc740 \uc138\uacc4\ub97c \ub113\ud788\ub294 \ud798\uc774\uba74\uc11c \uc138\uacc4\ub97c \uc798\ubabb \uc77d\uac8c \ub9cc\ub4dc\ub294 \ud798\uc774\uae30\ub3c4 \ud558\ub2e4. \uac00\ub09c\ud558\uace0 \ud3c9\ubc94\ud55c \uc7a5\uc18c\ub3c4 \uae30\uc0ac\ub3c4\uc758 \ubb34\ub300\uac00 \ub418\uc9c0\ub9cc, \uadf8\uacf3\uc5d0 \uc0ac\ub294 \uc0ac\ub78c\ub4e4\uc740 \uadf8\uc758 \ud574\uc11d\uc5d0 \ub3d9\uc758\ud55c \uc801\uc774 \uc5c6\ub2e4. \ubcf8\uc778\uc774 \ub73b\uc744 \uc138\uc6e0\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \ub0a8\ub4e4\uc774 \uc774\uc57c\uae30 \uc18d \ubc30\uc5ed\uc744 \ub9e1\uc544 \uc8fc\uc5b4\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub3c8\ud0a4\ud638\ud14c\uc640 \ud568\uaed8 \uae38\uc744 \ub5a0\ub098\ub294 \uc0b0\ucd08 \ud310\uc0ac\ub294 \ub2f9\ub098\uadc0\ub97c \ud0c4\ub2e4. \uace0\uc0c1\ud55c \uba85\uc608\ubcf4\ub2e4 \uba39\uc744 \uac83\uacfc \uc7a0\uc790\ub9ac, \uc7a5\ucc28 \ubc1b\uc744 \ubcf4\uc0c1\uc5d0 \uad00\uc2ec\uc774 \ub9ce\ub2e4. \uc8fc\uc778\uc774 \uc5b8\uc820\uac00 \uc12c\uc744 \ub2e4\uc2a4\ub9ac\uac8c \ud574 \uc8fc\uaca0\ub2e4\ub294 \uc57d\uc18d\ub3c4 \uadf8\ub97c \uc6c0\uc9c1\uc778\ub2e4. \ucc98\uc74c\ubd80\ud130 \uc138\uc0c1\uc744 \ubc14\uafc0 \uc774\uc0c1\uc744 \uacf5\uc720\ud574\uc11c \ub530\ub77c\uac00\ub294 \ub3d9\ud589\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc0b0\ucd08\uac00 \uc695\uc2ec\ub9cc \ub9ce\uc740 \ubc14\ubcf4\uc778 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub208\uc55e\uc758 \ud615\ud3b8\uc744 \uc0b4\ud53c\uace0 \ub9d0\ub85c \uc8fc\uc778\uacfc \ubd80\ub52a\uce58\uba70 \ub54c\ub85c\ub294 \uc0dd\ud65c\uc758 \uc9c0\ud61c\ub97c \ubcf4\uc5ec \uc900\ub2e4. \ub3c8\ud0a4\ud638\ud14c\uc758 \ud655\uc2e0\uc5d0 \uc0b0\ucd08\uc758 \uc758\uc2ec\uc774 \ubd99\uc73c\uba74\uc11c \uc18c\uc124\uc758 \ub300\ud654\uac00 \uc0b4\uc544\ub09c\ub2e4. \ub458 \uc911 \ud558\ub098\uac00 \uc644\uc804\ud788 \uc0ac\ub77c\uc9c0\uba74 \uc5ec\ud589\uc758 \ub9ac\ub4ec\ub3c4 \uc0ac\ub77c\uc9c4\ub2e4. \ud48d\ucc28 \uc7a5\uba74\uc5d0\uc11c \uc0b0\ucd08\ub294 \ubd84\uba85\ud788 \uae30\uacc4\uc758 \ub0a0\uac1c\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\ub7ec\ub098 \ub3c8\ud0a4\ud638\ud14c\ub294 \uadf8 \ub9d0\uc744 \uac81\uba39\uc740 \uc0ac\ub78c\uc758 \ubcc0\uba85\ucc98\ub7fc \ubc1b\uc544\ub4e4\uc778\ub2e4. \ubc14\ub78c\uc774 \ubd88\uc5b4 \ub0a0\uac1c\uac00 \ub3cc\uc544\uac00\uae30 \uc2dc\uc791\ud558\uc790 \uac70\uc778\uc774 \ud314\uc744 \ud718\ub450\ub978\ub2e4\uace0 \ud574\uc11d\ud55c\ub2e4. \uad00\ucc30\uc774 \ubbff\uc74c\uc744 \ubc14\uafb8\ub294 \ub300\uc2e0 \uae30\uc874 \ubbff\uc74c\uc744 \ub354\uc6b1 \ub2e8\ub2e8\ud558\uac8c \ub9cc\ub4e0\ub2e4. \uacb0\uacfc\ub294 \ucc38\ub2f4\ud558\ub2e4. \ucc3d\uc774 \ubd80\ub7ec\uc9c0\uace0 \ub9d0\uacfc \uae30\uc0ac\ub294 \ub545\ubc14\ub2e5\uc73c\ub85c \uad74\ub7ec \ub5a8\uc5b4\uc9c4\ub2e4. \ub3c5\uc790\ub294 \uc774\ubbf8 \uc815\uccb4\ub97c \uc54c\uace0 \uc788\uc5b4 \uc6c3\uc9c0\ub9cc, \ubab8\uc774 \ubc1b\ub294 \ucda9\uaca9\uc740 \uc791\ud488 \uc18d\uc5d0\uc11c\ub3c4 \uc2e4\uc81c\ub2e4. \uc120\ud55c \ub73b\uacfc \ub300\ub2f4\ud568\ub9cc\uc73c\ub85c \ud604\uc2e4\uc758 \ubc95\uce59\uc744 \uac74\ub108\ub6f8 \uc218 \uc5c6\ub2e4\ub294 \uc810\uc774 \uc6b0\uc2a4\uaf5d\uc2a4\ub7fd\uace0 \uc544\ud504\uac8c \ub4dc\ub7ec\ub09c\ub2e4. \ub3c8\ud0a4\ud638\ud14c\ub294 \ud328\ubc30 \ub4a4\uc5d0\ub3c4 \ucc98\uc74c \ud310\ub2e8\uc744 \uc27d\uac8c \uac70\ub450\uc9c0 \uc54a\ub294\ub2e4. \uc790\uc2e0\uc744 \ubbf8\uc6cc\ud558\ub294 \ub9c8\ubc95\uc0ac\uac00 \uac70\uc778\uc744 \ud48d\ucc28\ub85c \ubc14\uafb8\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub208\uc55e\uc758 \uc99d\uac70\uac00 \uc0dd\uac01\uacfc \ub9de\uc9c0 \uc54a\uc744 \ub54c \uc0dd\uac01\uc744 \uace0\uce58\ub294 \ub300\uc2e0, \uc99d\uac70\uac00 \ubc14\ub00c\uc5c8\ub2e4\ub294 \uc0c8\ub85c\uc6b4 \uc774\uc57c\uae30\ub97c \ub9cc\ub4e0\ub2e4. \ud48d\ucc28\ubcf4\ub2e4 \uc624\ub798 \ub0a8\ub294 \uac83\uc740 \uc774 \ub300\uc751 \ubc29\uc2dd\uc77c\uc9c0 \ubaa8\ub978\ub2e4. \uc6b0\ub9ac\uac00 \uc774 \uc7a5\uba74\uc5d0\uc11c \uc790\uae30 \ubaa8\uc2b5\uc744 \uc7a0\uae50 \ubc1c\uacac\ud558\ub294 \uc774\uc720\ub3c4 \uc5ec\uae30\uc5d0 \uc788\ub2e4. \ubb3c\ub860 \uc790\uc2e0\uc774 \ubbff\ub294 \uc77c\uc744 \ub05d\uae4c\uc9c0 \ubc00\uc5b4\ubd99\uc774\ub294 \ud0dc\ub3c4\uc640 \ud604\uc2e4 \ud310\ub2e8\uc758 \uc5b4\ub824\uc6c0\uc740 \uac19\uc740 \ub9d0\uc774 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \ubb34\uc5c7\uc774 \ub098\ud0c0\ub098\ub3c4 \ub0b4 \uc0dd\uac01\uc774 \ub9de\ub2e4\uace0 \uc124\uba85\ud560 \uc218 \uc788\ub2e4\uba74, \uadf8 \uc0dd\uac01\uc740 \uc5b4\ub5a4 \uc21c\uac04\uc5d0 \ubc14\ub014 \uc218 \uc788\uc744\uc9c0 \ubb3b\uac8c \ub41c\ub2e4. \uc5ec\uc815\uc5d0\uc11c \ub3c8\ud0a4\ud638\ud14c\ub294 \uc5b5\uc6b8\ud55c \uc0ac\ub78c\uc744 \ub3d5\uaca0\ub2e4\uace0 \ub098\uc120\ub2e4. \ud558\uc9c0\ub9cc \uc0ac\uc815\uc744 \ucda9\ubd84\ud788 \uc54c\uc9c0 \ubabb\ud55c \ucc44 \uc790\uc2e0\uc774 \uc544\ub294 \uc774\uc57c\uae30\uc758 \uad6c\ub3c4\ub85c \ud310\ub2e8\ud560 \ub54c\uc5d0\ub294 \ub3c4\uc6c0\uc774 \uc5c9\ub6b1\ud55c \uacb0\uacfc\ub97c \ub0b3\ub294\ub2e4. \uc798\ubabb\ud55c \uc0ac\ub78c\uc5d0\uac8c \ubc8c\uc744 \ub0b4\ub9ac\uace0 \ub5a0\ub098\uba74 \uc57d\ud55c \uc0ac\ub78c\uc758 \uc0b6\uc774 \uace7 \uc88b\uc544\uc9c8 \uac83\uc774\ub77c\ub294 \uae30\ub300\ub3c4 \ubc88\ubc88\uc774 \ud754\ub4e4\ub9b0\ub2e4. \uc774\ub7f0 \uc7a5\uba74\uc740 \uadf8\ub97c \ube44\uc6c3\uc73c\ub77c\uace0\ub9cc \ub193\uc5ec \uc788\uc9c0 \uc54a\ub2e4. \uc57d\ud55c \uc0ac\ub78c\uc744 \uadf8\ub0e5 \uc9c0\ub098\uce58\uc9c0 \ubabb\ud558\ub294 \ub9c8\uc74c\uc5d0\ub294 \ubd84\uba85 \ud798\uc774 \uc788\ub2e4. \ubb38\uc81c\ub294 \uadf8 \ub9c8\uc74c\uc774 \uc0c1\ub300\uc758 \ud604\uc2e4\uc744 \ub4e3\ub294 \uc77c\uacfc \ud568\uaed8 \uac00\uc57c \ud55c\ub2e4\ub294 \uc810\uc774\ub2e4. \uc18c\uc124\uc740 \ubb34\uad00\uc2ec\ud55c \ud604\uc2e4\uc8fc\uc758\ub3c4, \uc0ac\uc815\uc744 \ubb34\uc2dc\ud55c \uc601\uc6c5 \ub180\uc774\ub3c4 \ud3b8\uc548\ud55c \uc815\ub2f5\uc73c\ub85c \ub0b4\ub193\uc9c0 \uc54a\ub294\ub2e4. \ub450 \uc0ac\ub78c\uc744 \ub9cc\ub098\ub294 \uc8fc\ubcc0 \uc778\ubb3c \uac00\uc6b4\ub370\uc5d0\ub294 \uadf8\ub4e4\uc758 \ucc29\uac01\uc744 \uc774\uc6a9\ud574 \uc7a5\ub09c\uc744 \ubc8c\uc774\ub294 \uc774\ub4e4\ub3c4 \uc788\ub2e4. \ub3c5\uc790\ub294 \uc790\uc2e0\uc774 \uc6c3\uace0 \uc788\ub294 \uc774\uc720\ub97c \ub2e4\uc2dc \uc0b4\ud53c\uac8c \ub41c\ub2e4. \uc5c9\ub6b1\ud55c \ud589\ub3d9\uc774 \uc6b0\uc2a4\uc6b4 \uac83\uacfc \ub204\uad70\uac00\uc758 \ucde8\uc57d\ud568\uc744 \uc774\uc6a9\ud574 \uc990\uae30\ub294 \uc77c\uc740 \uac19\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc774\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ub2e8\uc21c\ud588\ub358 \uad6c\uacbd\uc758 \uc704\uce58\uac00 \ud754\ub4e4\ub9b0\ub2e4. \ud2b9\ud788 \uc5ec\uc815\uc758 \ub4a4\ucabd\uc73c\ub85c \uac08\uc218\ub85d \ub3c8\ud0a4\ud638\ud14c\uc640 \uc0b0\ucd08\ub97c \uc544\ub294 \uc0ac\ub78c\ub4e4\uc758 \uae30\ub300\ub3c4 \uc0ac\uac74\uc744 \ub9cc\ub4e0\ub2e4. \ub450 \uc0ac\ub78c\uc740 \uc790\uae30\uac00 \ub9cc\ub4e0 \uc774\uc57c\uae30 \uc548\uc5d0\ub9cc \uac07\ud78c \uac83\uc774 \uc544\ub2c8\ub77c, \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc774 \uafb8\ubbfc \uad6c\uacbd\uac70\ub9ac \uc548\uc5d0\ub3c4 \ub193\uc778\ub2e4. \uc0c1\uc0c1\uacfc \ud604\uc2e4\uc744 \ub098\ub204\ub358 \uc120\uc774 \uc5ec\ub7ec \ubc29\ud5a5\uc73c\ub85c \ubc88\uc9c4\ub2e4. \uc791\ud488\uc758 \ub9c8\uc9c0\ub9c9\uc5d0\uc11c \uadf8\ub294 \uc9d1\uc73c\ub85c \ub3cc\uc544\uc640 \ubcd1\uc0c1\uc5d0 \ub215\uace0, \uc790\uc2e0\uc774 \ub530\ub790\ub358 \uae30\uc0ac\ub3c4 \uc774\uc57c\uae30\uc758 \ud658\uc0c1\uc744 \ub0b4\ub824\ub193\ub294\ub2e4. \uc775\uc219\ud55c \ub3c8\ud0a4\ud638\ud14c\uc758 \ubaa8\uc2b5\uc774 \uc0ac\ub77c\uc9c0\ub294 \uc21c\uac04, \uc0b0\ucd08\ub294 \uc624\ud788\ub824 \ub2e4\uc2dc \uae38\uc744 \ub5a0\ub0a0 \uc218 \uc788\ub2e4\uace0 \ubd99\uc7a1\uc73c\ub824 \ud55c\ub2e4. \ub298 \ub9d0\ub9ac\ub358 \ub3d9\ud589\uc790\uac00 \uc774\uc57c\uae30\ub97c \uacc4\uc18d\ud558\uc790\uace0 \ud558\ub294 \ubc18\uc804\uc774\ub2e4. \uadf8\ub798\uc11c \uacb0\ub9d0\uc740 \uc815\uc2e0\uc744 \ucc28\ub838\uc73c\ub2c8 \ubaa8\ub450 \uc798\ub418\uc5c8\ub2e4\ub294 \ub290\ub08c\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \ucc29\uac01\uc5d0\uc11c \ubc97\uc5b4\ub09c \uc548\ub3c4\uc640 \ud55c \uc778\ubb3c\uc774 \uc9c0\ub154\ub358 \uc0dd\uae30\uc758 \uc18c\uba78\uc774 \uacb9\uce5c\ub2e4. \uadf8\ub97c \uac00\uc7a5 \uac00\uae4c\uc774 \ubcf8 \uc0b0\ucd08\uc5d0\uac8c\ub294 \uc798\ubabb\ub41c \ud310\ub2e8\ub9cc\uc774 \uc544\ub2c8\ub77c \ud568\uaed8 \ub2e4\ub2cc \uc2dc\uac04\ub3c4 \ub0a8\uc544 \uc788\ub2e4. \ub3c5\uc790 \uc5ed\uc2dc \uadf8 \ub450 \uac00\uc9c0\ub97c \ud55c\uaebc\ubc88\uc5d0 \ub0b4\ub824\ub193\uae30 \uc5b4\ub835\ub2e4. \u300e\ub3c8\ud0a4\ud638\ud14c\u300f\ub294 \uafc8\uc744 \uac00\uc9c0\uba74 \uc548 \ub41c\ub2e4\ub294 \uad50\ud6c8\ub3c4, \ud604\uc2e4\uc744 \ubb34\uc2dc\ud558\uace0 \ub2ec\ub824\ub4e4\ub77c\ub294 \uc751\uc6d0\ub3c4 \uc544\ub2c8\ub2e4. \uc774\uc0c1\uc774 \uc0ac\ub78c\uc744 \uc6c0\uc9c1\uc77c \ub54c \uc0dd\uae30\ub294 \ud798\uacfc \ube44\uc6a9\uc744 \uc5ec\ub7ec \ubaa9\uc18c\ub9ac\ub85c \ubcf4\uc5ec \uc8fc\ub294 \uc18c\uc124\uc774\ub2e4. \ud48d\ucc28\ub294 \uadf8 \ubcf5\uc7a1\ud55c \uc5ec\ud589\uc744 \uc5ec\ub294 \ub208\uc5d0 \uc798 \ubcf4\uc774\ub294 \ubb38\uc774\ub2e4. \ub2e4\uc2dc \uadf8 \uc7a5\uba74\uc744 \ub5a0\uc62c\ub9b4 \ub54c \uae30\uc0ac\ub9cc \ubcf4\uc9c0 \ub9d0\uace0 \uc606\uc758 \ub2f9\ub098\uadc0\ub3c4 \ubcf4\uc790. \uc0b0\ucd08\ub294 \ub9d0\ub9ac\uace0, \ub2e4\uce5c \uc8fc\uc778\uc5d0\uac8c \ub2ec\ub824\uac00\uba70, \uacb0\uad6d \ub2e4\uc2dc \ud568\uaed8 \uae38\uc744 \uac04\ub2e4. \uc11c\ub85c\uc758 \uc138\uacc4\ub97c \uc644\uc804\ud788 \uc774\ud574\ud558\uc9c0 \ubabb\ud574\ub3c4 \ub300\ud654\ub97c \uba48\ucd94\uc9c0 \uc54a\ub294 \ub450 \uc0ac\ub78c. \uadf8 \ub3d9\ud589 \ub355\ubd84\uc5d0 \ud48d\ucc28\uc5d0 \uc4f0\ub7ec\uc9c4 \ub0a8\uc790\uc758 \uc774\uc57c\uae30\ub294 \uc9e7\uc740 \ub18d\ub2f4\ubcf4\ub2e4 \ud6e8\uc52c \uae38\uc5b4\uc84c\ub2e4."}, {"id": "dorian-gray-portrait-and-conscience", "title": "\ub3c4\ub9ac\uc5b8 \uadf8\ub808\uc774\uc758 \ucd08\uc0c1 \u2014 \uc5bc\uad74 \ub300\uc2e0 \uadf8\ub9bc\uc774 \ub299\uc5b4 \uac04\ub2e4\uba74", "summary": "\uc790\uc2e0 \ub300\uc2e0 \ubcc0\ud574 \uac00\ub294 \ucd08\uc0c1\ud654 \uc55e\uc5d0\uc11c \ub3c4\ub9ac\uc5b8\uc774 \uc5b4\ub5a4 \uc120\ud0dd\uc744 \ud558\ub294\uc9c0 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \ub530\ub77c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/dorian-gray-portrait-and-conscience/index.html", "image": "../media/dorian-gray-portrait-and-conscience.png", "alt": "\ube45\ud1a0\ub9ac\uc544 \uc2dc\ub300\ud48d \ud654\uc2e4\uc5d0\uc11c \uc80a\uc740 \ub3c4\ub9ac\uc5b8\uc774 \uc790\uc2e0\uc758 \ucd08\uc0c1\ud654\ub97c \ubc14\ub77c\ubcf4\ub294 \uc6d0\uc791 \uae30\ubc18 \uc0c1\uc0c1 \uc0bd\ud654.", "text": "\ub3c4\ub9ac\uc5b8 \uadf8\ub808\uc774\uc758 \ucd08\uc0c1 \u2014 \uc5bc\uad74 \ub300\uc2e0 \uadf8\ub9bc\uc774 \ub299\uc5b4 \uac04\ub2e4\uba74 \uc544\ub984\ub2e4\uc6b4 \uac89\ubaa8\uc2b5\uacfc \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc120\ud0dd\uc758 \uae30\ub85d \uc790\uc2e0 \ub300\uc2e0 \ubcc0\ud574 \uac00\ub294 \ucd08\uc0c1\ud654 \uc55e\uc5d0\uc11c \ub3c4\ub9ac\uc5b8\uc774 \uc5b4\ub5a4 \uc120\ud0dd\uc744 \ud558\ub294\uc9c0 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \ub530\ub77c \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \ub0b4 \uc5bc\uad74\uc740 \uc80a\uc740 \ubaa8\uc2b5 \uadf8\ub300\ub85c\uc778\ub370 \ub098\ub97c \uadf8\ub9b0 \uadf8\ub9bc\ub9cc \ub098\uc774\ub97c \uba39\ub294\ub2e4\uba74 \uc5b4\ub5a8\uae4c. \uc624\uc2a4\uce74 \uc640\uc77c\ub4dc\uc758 \u300e\ub3c4\ub9ac\uc5b8 \uadf8\ub808\uc774\uc758 \ucd08\uc0c1\u300f\uc740 \ub204\uad6c\ub098 \uc7a0\uae50 \ub5a0\uc62c\ub9b4 \ub9cc\ud55c \uc18c\ub9dd\uc744 \uc704\ud5d8\ud55c \uc774\uc57c\uae30\ub85c \ubc14\uafbc\ub2e4. \uadf8\ub9bc\uc774 \ub300\uc2e0 \uac04\uc9c1\ud558\ub294 \uac83\uc740 \uc138\uc6d4\ubfd0 \uc544\ub2c8\ub77c \ub3c4\ub9ac\uc5b8\uc774 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ud55c \ud589\ub3d9\uc758 \ud754\uc801\uc774\ub2e4. \uc544\ub984\ub2f5\ub2e4\ub294 \ud3c9\uac00\uac00 \uc88b\uc740 \uc0ac\ub78c\uc774\ub77c\ub294 \ud3c9\uac00\uc640 \ub4a4\uc11e\uc77c \ub54c \ubb34\uc2a8 \uc77c\uc774 \uc0dd\uae38\uae4c. \uc18c\uc124\uc740 \uc774 \uc9c8\ubb38\uc744 \ud654\ub824\ud55c \ub300\ud654\uc640 \uc740\ubc00\ud55c \ubc29, \uac10\ucd94\uace0 \uc2f6\uc740 \ucd08\uc0c1\ud654\uc5d0 \ub2f4\ub294\ub2e4. \uc544\ub798\uc5d0\ub294 \uc8fc\uc694 \uc0ac\uac74\uacfc \uacb0\ub9d0\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4. \ud654\uac00 \ubc30\uc9c8 \ud640\uc6cc\ub4dc\ub294 \uc80a\uc740 \ub3c4\ub9ac\uc5b8\uc758 \ucd08\uc0c1\ud654\ub97c \uadf8\ub9b0\ub2e4. \ubc30\uc9c8\uc5d0\uac8c \ub3c4\ub9ac\uc5b8\uc740 \ub2e8\uc21c\ud788 \uc544\ub984\ub2e4\uc6b4 \ubaa8\ub378\uc744 \ub118\uc5b4 \uc790\uae30 \uc608\uc220\uc5d0 \uae4a\uc740 \uc601\ud5a5\uc744 \uc900 \uc874\uc7ac\ub2e4. \uc644\uc131\ub41c \uadf8\ub9bc\uc5d0\ub294 \ud654\uac00\uac00 \ub300\uc0c1\uc744 \ubc14\ub77c\ubcf4\ub294 \ub9c8\uc74c\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \uadf8\ub9bc\uacfc \uc2e4\uc81c \uc0ac\ub78c\uc774 \ucc98\uc74c\uc5d0\ub294 \ub098\ub780\ud788 \ub193\uc778\ub2e4. \uadf8 \uc790\ub9ac\uc5d0 \ud5e8\ub9ac \uacbd\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \uadf8\ub294 \uc80a\uc74c\uacfc \uc544\ub984\ub2e4\uc6c0, \ucf8c\ub77d\uc758 \uac00\uce58\ub97c \ub9e4\ub825\uc801\uc778 \ub9d0\ub85c \uc774\uc57c\uae30\ud55c\ub2e4. \ub3c4\ub9ac\uc5b8\uc740 \uadf8 \ub9d0\uc744 \ub4e3\uace0 \uc790\uc2e0\uc5d0\uac8c \uc788\ub294 \uac83\uc774 \uc5bc\ub9c8\ub098 \ube68\ub9ac \uc0ac\ub77c\uc9c8 \uc218 \uc788\ub294\uc9c0 \ub450\ub824\uc6cc\ud55c\ub2e4. \ud5e8\ub9ac\uac00 \ub0b4\ub193\ub294 \ub3c4\ubc1c\uc801\uc778 \ubb38\uc7a5\uc744 \uc18c\uc124\uc758 \ucd5c\uc885 \uc815\ub2f5\uc73c\ub85c \uace7\ubc14\ub85c \ubc1b\uc544\ub4e4\uc774\uc9c0\ub294 \ub9d0\uc790. \uadf8 \ub9d0\uc774 \ub3c4\ub9ac\uc5b8\uc5d0\uac8c \ubbf8\uce58\ub294 \uc601\ud5a5\ub3c4 \uc774\uc57c\uae30\uc758 \uc77c\ubd80\ub2e4. \ub3c4\ub9ac\uc5b8\uc740 \uadf8\ub9bc\uc740 \uc80a\uac8c \ub0a8\uace0 \uc790\uc2e0\ub9cc \ub299\ub294 \ud604\uc2e4\uc744 \uacac\ub514\uae30 \uc5b4\ub824\uc6cc\ud55c\ub2e4. \ucc28\ub77c\ub9ac \uc790\uc2e0\uc774 \uadf8\ub300\ub85c \uc788\uace0 \uadf8\ub9bc\uc774 \ub2ec\ub77c\uc84c\uc73c\uba74 \uc88b\uaca0\ub2e4\uace0 \ubc14\ub780\ub2e4. \uc18c\ub9dd\uc740 \uc544\ub984\ub2e4\uc6b4 \uc21c\uac04\uc744 \ub193\uce58\uae30 \uc2eb\ub2e4\ub294 \ub9c8\uc74c\uc5d0\uc11c \uc2dc\uc791\ud558\uc9c0\ub9cc, \uace7 \uc0b6\uc758 \uacb0\uacfc\ub97c \ub2e4\ub978 \uacf3\uc5d0 \ub5a0\ub118\uae30\ub294 \uad6c\uc870\ub85c \uc774\uc5b4\uc9c4\ub2e4. \uc18c\uc124\uc740 \ub9c8\ubc95\uc758 \uc791\ub3d9 \uc6d0\ub9ac\ub97c \uae30\uc220 \uc124\uba85\uc11c\ucc98\ub7fc \ud480\uc9c0 \uc54a\ub294\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uc18c\ub9dd\uc774 \uc774\ub8e8\uc5b4\uc9c4 \ub4a4 \ub3c4\ub9ac\uc5b8\uc774 \uc5b4\ub5a4 \uad00\uacc4\ub97c \ub9fa\ub294\uac00\ub2e4. \uac89\uc73c\ub85c\ub294 \uc774\uc804\uacfc \uac19\uc740 \uc5bc\uad74\uc744 \ubcf4\uc5ec \uc904 \uc218 \uc788\ub2e4\uba74 \uadf8\ub294 \ubb34\uc5c7\uae4c\uc9c0 \ud574\ub3c4 \ub41c\ub2e4\uace0 \uc0dd\uac01\ud558\uac8c \ub420\uae4c. \ucd08\uc0c1\ud654\ub294 \uc7a5\uc2dd\ud488\uc5d0\uc11c \uac10\ucd94\uace0 \uc2f6\uc740 \uae30\ub85d\uc73c\ub85c \ubc14\ub010\ub2e4. \ub3c4\ub9ac\uc5b8\uc740 \ubc30\uc6b0 \uc2dc\ube4c \ubca0\uc778\uc744 \uc0ac\ub791\ud55c\ub2e4\uace0 \ub290\ub080\ub2e4. \ubb34\ub300\uc5d0\uc11c \uc5ec\ub7ec \uc778\ubb3c\uc744 \uc5f0\uae30\ud558\ub294 \uadf8\ub140\uc758 \ubaa8\uc2b5\uc5d0 \ub9e4\ub8cc\ub41c\ub2e4. \uadf8\ub7f0\ub370 \uc2dc\ube4c\uc774 \uc2e4\uc81c \uc0ac\ub791\uc744 \uacbd\ud5d8\ud55c \ub4a4 \uc5f0\uae30\ub97c \uc804\ucc98\ub7fc \ud558\uc9c0 \ubabb\ud558\uc790 \ub3c4\ub9ac\uc5b8\uc758 \ud0dc\ub3c4\uac00 \uae09\uaca9\ud788 \ub2ec\ub77c\uc9c4\ub2e4. \uadf8\ub294 \uadf8\ub140\uc758 \uacf5\uc5f0\uc5d0 \uc2e4\ub9dd\ud558\uace0 \uc794\uc778\ud55c \ub9d0\uc744 \ud55c\ub2e4. \uc5ec\uae30\uc11c \uc0ac\ub791\ud55c \uac83\uc774 \ud55c \uc0ac\ub78c\uc758 \uc0b6\uc778\uc9c0, \uc790\uc2e0\uc774 \ubc14\ub77c\ubcf4\ub358 \uc544\ub984\ub2e4\uc6b4 \uacf5\uc5f0\uc778\uc9c0 \ubb3b\uac8c \ub41c\ub2e4. \uc2dc\ube4c\uc5d0\uac8c\ub294 \ubb34\ub300 \ubc16\uc758 \ub9c8\uc74c\uc774 \uc0dd\uacbc\ub294\ub370 \ub3c4\ub9ac\uc5b8\uc740 \uc790\uc2e0\uc744 \uc990\uac81\uac8c \ud574 \uc8fc\ub358 \ubaa8\uc2b5\uc774 \uc0ac\ub77c\uc84c\ub2e4\uace0 \ubc18\uc751\ud55c\ub2e4. \uc774\ud6c4 \uc2dc\ube4c\uc758 \uc8fd\uc74c\uc774 \uc804\ud574\uc9c0\uace0, \ucd08\uc0c1\ud654\uc5d0\ub294 \uc774\uc804\uacfc \ub2e4\ub978 \ud45c\uc815\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \ub3c4\ub9ac\uc5b8\uc740 \ucd08\uc0c1\ud654\uc5d0 \uc790\uc2e0\uc758 \ud589\ub3d9\uacfc \uc5f0\uacb0\ub41c \ubcc0\ud654\uac00 \uc0dd\uae34\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c\uc544\ucc28\ub9b0\ub2e4. \uadf8\ub9bc\uc744 \ub0a8\uc5d0\uac8c \ubcf4\uc774\uc9c0 \uc54a\ub294 \uacf3\uc5d0 \uac10\ucd94\uba74 \ubc14\uae65\uc758 \uc0ac\ub78c\ub4e4\uc740 \uc5ec\uc804\ud788 \uc80a\uace0 \ub9e4\ub825\uc801\uc778 \uadf8\ub97c \ub9cc\ub09c\ub2e4. \ubcf4\uc774\ub294 \ubaa8\uc2b5\uacfc \ubcf4\uc774\uc9c0 \uc54a\ub294 \uae30\ub85d \uc0ac\uc774\uc5d0 \uac70\ub9ac\uac00 \ubc8c\uc5b4\uc9c4\ub2e4. \uadf8\ub294 \ucde8\ud5a5\uacfc \uac10\uac01\uc758 \uc990\uac70\uc6c0\uc744 \uc887\uc73c\uba70 \uc0b4\uc544\uac04\ub2e4. \uc18c\uc124\uc774 \uc637\uac10\uacfc \ud5a5, \uc74c\uc545\uacfc \uc218\uc9d1\ud488\uc744 \uae38\uac8c \ub098\uc5f4\ud558\ub294 \ub300\ubaa9\ub3c4 \uc774 \uc0b6\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc544\ub984\ub2e4\uc6b4 \uac83\uc744 \uc88b\uc544\ud558\ub294 \uc77c \uc790\uccb4\uac00 \uc8c4\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ubbf8\uce5c \uacb0\uacfc\ub97c \uac00\ub9b0 \ucc44 \uc990\uac70\uc6c0\ub9cc\uc73c\ub85c \uc790\uae30\ub97c \uc124\uba85\ud558\ub824\ub294 \ud0dc\ub3c4\uac00 \ubb38\uc81c\ub97c \ud0a4\uc6b4\ub2e4. \uc138\uc6d4\uc774 \uc9c0\ub098\uba74\uc11c \ub3c4\ub9ac\uc5b8\uc5d0 \uad00\ud55c \uc88b\uc9c0 \uc54a\uc740 \uc18c\ubb38\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ubc30\uc9c8\uc740 \ud55c\ub54c \uc790\uae30 \uc608\uc220\uc758 \uc911\uc2ec\uc774\uc5c8\ub358 \uc0ac\ub78c\uc5d0\uac8c \ubb34\uc2a8 \uc77c\uc774 \uc0dd\uacbc\ub294\uc9c0 \uc54c\uace0 \uc2f6\uc5b4 \ud55c\ub2e4. \ub3c4\ub9ac\uc5b8\uc774 \ucd08\uc0c1\ud654\ub97c \ubcf4\uc5ec \uc8fc\uc790 \uadf8\ub294 \uadf8\ub9bc\uc774 \ud488\uc740 \ubcc0\ud654\ub97c \ub9c8\uc8fc\ud558\uace0 \ub450\ub824\uc6cc\ud55c\ub2e4. \ubc30\uc9c8\uc740 \ub3c4\ub9ac\uc5b8\uc5d0\uac8c \ub3cc\uc544\uc124 \uae38\uc744 \uad8c\ud558\uc9c0\ub9cc, \ub3c4\ub9ac\uc5b8\uc740 \uadf8\ub97c \uc0b4\ud574\ud55c\ub2e4. \uadf8\ub9bc\uc774 \uc678\ubd80\uc758 \ubb3c\uac74\uc774\ub77c\uace0 \ud574\uc11c \uadf8 \uc55e\uc5d0\uc11c \uc0dd\uae30\ub294 \uac10\uc815\uc744 \ub2e4\ub8f0 \uc218 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc790\uc2e0\uc758 \ubaa8\uc2b5\uc744 \uc99d\uc5b8\ud558\ub294 \uc0ac\ub78c\uc744 \uc5c6\uc560\ub3c4 \uc774\ubbf8 \uc77c\uc5b4\ub09c \uc120\ud0dd\uc740 \uc0ac\ub77c\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uc228\uae30\ub294 \ud589\uc704\uac00 \ub610 \ub2e4\ub978 \ud3ed\ub825\uc73c\ub85c \uc774\uc5b4\uc9c4\ub2e4. \ub3c4\ub9ac\uc5b8\uc740 \uc568\ub7f0 \ucea0\ubca8\uc744 \uc555\ubc15\ud574 \uc0b4\ud574\uc758 \ud754\uc801\uc744 \ucc98\ub9ac\ud558\uac8c \ud55c\ub2e4. \uc5ec\uae30\uc5d0\uc11c\ub3c4 \uc790\uc2e0\uc774 \uc800\uc9c0\ub978 \uc77c\uc758 \ub4a4\ucc98\ub9ac\ub97c \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ub118\uae34\ub2e4. \ucd08\uc0c1\ud654\uac00 \ub300\uc2e0 \ub299\uc5b4 \uc8fc\ub294 \uad6c\uc870\uc640, \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uacb0\uacfc\ub97c \uac10\ub2f9\ud558\uac8c \ud558\ub294 \ud589\ub3d9\uc774 \uc11c\ub85c \ub2ee\uc544 \uac04\ub2e4. \ubc14\uae65\uc5d0\uc11c \ubcf4\ub294 \ub3c4\ub9ac\uc5b8\uc740 \uc5ec\uc804\ud788 \ubcc0\ud654\uac00 \uc801\uc9c0\ub9cc \uad00\uacc4\ub294 \uadf8\ub807\uc9c0 \uc54a\ub2e4. \ube44\ubc00\uc744 \uc720\uc9c0\ud558\ub824\uba74 \ub354 \ub9ce\uc740 \uac70\uc9d3\uacfc \uc555\ubc15\uc774 \ud544\uc694\ud574\uc9c4\ub2e4. \uc80a\uc74c\uc744 \ubcf4\uc874\ud55c \uac83\uc774 \ub450\ub824\uc6c0\uc744 \uc904\uc5ec \uc8fc\uae30\ubcf4\ub2e4 \ub450\ub824\uc6c0\uc744 \uac10\ucd9c \uacf5\uac04\uc744 \ub298\ub838\ub2e4\ub294 \uac10\uc0c1\uc774 \uac00\ub2a5\ud558\ub2e4. \uadf8\ub294 \uc790\uc720\ub85c\uc6cc\uc9c4 \ub4ef \ubcf4\uc774\uba74\uc11c\ub3c4 \uadf8\ub9bc\uc758 \uc874\uc7ac\uc5d0 \ubd99\uc7a1\ud78c\ub2e4. \ud6c4\ubc18\uc758 \ub3c4\ub9ac\uc5b8\uc740 \uc790\uc2e0\uc758 \ubcc0\ud654 \uac00\ub2a5\uc131\uc744 \uc0dd\uac01\ud558\uc9c0\ub9cc \ucd08\uc0c1\ud654\uc5d0\uc11c \uae30\ub300\ud55c \uae68\ub057\ud568\uc744 \ucc3e\uc9c0 \ubabb\ud55c\ub2e4. \uadf8\ub294 \ub9c8\uce68\ub0b4 \uadf8\ub9bc\uc744 \ud30c\uad34\ud558\ub824\uace0 \uce7c\uc744 \ub4e0\ub2e4. \uacb0\uacfc\ub97c \ub2f4\uace0 \uc788\ub294 \ubb3c\uac74\uc744 \uc5c6\uc560\uba74 \uadf8 \uacb0\uacfc\ub85c\ubd80\ud130 \ubc97\uc5b4\ub0a0 \uc218 \uc788\ub2e4\uace0 \uc5ec\uae30\ub294 \ub4ef\ud55c \ud589\ub3d9\uc774\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \ubc29\uc5d0 \ub4e4\uc5b4\uc654\uc744 \ub54c \uadf8\ub9bc\uc740 \ub2e4\uc2dc \uc80a\uc740 \ub3c4\ub9ac\uc5b8\uc758 \ubaa8\uc2b5\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ubc14\ub2e5\uc5d0\ub294 \ub299\uace0 \ubcc0\ud55c \ub0a8\uc790\uac00 \uc4f0\ub7ec\uc838 \uc788\uace0, \ubc18\uc9c0 \ub4f1\uc744 \ud1b5\ud574 \uadf8\uac00 \ub3c4\ub9ac\uc5b8\uc784\uc744 \uc54c\uc544\ubcf8\ub2e4. \uac89\ubaa8\uc2b5\uacfc \uac10\ucd94\uc5b4 \ub454 \uae30\ub85d\uc744 \ubd84\ub9ac\ud574 \ub193\ub358 \uc18c\ub9dd\uc740 \ub9c8\uc9c0\ub9c9\uc5d0 \ubb34\ub108\uc9c4\ub2e4. \uadf8\ub294 \uadf8\ub9bc \ubc16\uc5d0\uc11c\ub3c4 \uc790\uae30 \uc0b6\uc744 \ubc97\uc5b4\ub0a0 \uc218 \uc5c6\uc5c8\ub2e4. \uc18c\uc124\uc740 \uc544\ub984\ub2e4\uc6b4 \uc5bc\uad74\uacfc \uc544\ub984\ub2e4\uc6b4 \uc608\uc220\uc744 \ub9ce\uc774 \uc774\uc57c\uae30\ud558\uc9c0\ub9cc \ub2e8\uc21c\ud788 \uc544\ub984\ub2e4\uc6c0\uc740 \uc704\ud5d8\ud558\ub2e4\ub294 \uad50\ud6c8\uc73c\ub85c \uc904\uc774\uae30 \uc5b4\ub835\ub2e4. \ubc30\uc9c8\uacfc \ud5e8\ub9ac, \ub3c4\ub9ac\uc5b8\uc774 \uac19\uc740 \uc544\ub984\ub2e4\uc6c0\uc5d0 \uc11c\ub85c \ub2e4\ub974\uac8c \ubc18\uc751\ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \ubbf8\uc801\uc778 \uc990\uac70\uc6c0\uacfc \ud0c0\uc778\uc5d0 \ub300\ud55c \ucc45\uc784\uc740 \uc5b4\ub5a4 \uad00\uacc4\uc5d0 \ub193\uc77c \uc218 \uc788\uc744\uae4c. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \uc18c\uc124\uc758 \uc778\ubb3c\uacfc \ud654\uc2e4\uc744 \uc0c8\ub85c \uc0c1\uc0c1\ud55c AI \uc0bd\ud654\ub2e4. \ud2b9\uc815 \uc601\ud654\uc758 \ubc30\uc6b0\ub098 \uc2e4\uc81c \ucd08\uc0c1\ud654\ub97c \uc7ac\ud604\ud55c \uac83\uc774 \uc544\ub2c8\ub2e4. \uadf8\ub9bc \uc18d \uc80a\uc740 \uc5bc\uad74\uc744 \ubcf4\uba70 \uc6b0\ub9ac\uac00 \uadf8 \uc0ac\ub78c\uc5d0 \ub300\ud574 \uc5bc\ub9c8\ub098 \ub9ce\uc740 \uac83\uc744 \uc131\uae09\ud788 \uc9d0\uc791\ud558\ub294\uc9c0 \ub5a0\uc62c\ub9ac\uba74, \uc624\ub798\ub41c \uc18c\uc124\uc758 \uc9c8\ubb38\ub3c4 \uc870\uae08 \uac00\uae4c\uc6cc\uc9c4\ub2e4."}, {"id": "dunhuang-caves-paintings-and-donors", "title": "\ub454\ud669 \ub9c9\uace0\uad74 \u2014 \ube44\ub2e8 \uc704\uc758 \ubd88\ud654\ub294 \ub204\uad6c\uc758 \uc18c\ub9dd\uc744 \ub2f4\uc558\uc744\uae4c", "summary": "\ub9c9\uace0\uad74\uc758 \uacf5\uac04\uacfc \ud734\ub300\ud558\ub294 \ubd88\ud654, \uc791\uc740 \uae30\uc99d\uc790\uc640 \ud6c4\ub300 \uc790\ub8cc \uc774\ub3d9\uc744 \ud1b5\ud574 \uc0ac\ub78c\ub4e4\uc758 \uc18c\ub9dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/dunhuang-caves-paintings-and-donors/index.html", "image": "../media/dunhuang-caves-paintings-and-donors.jpg", "alt": "1921\ub144 \ub454\ud669 \ubd88\ud654 \ub3c4\ub85d\uc5d0 \uc2e4\ub9b0 \ube44\ub2e8 \uadf8\ub9bc\uc758 \uc5ed\uc0ac \ub3c4\ud310", "text": "\ub454\ud669 \ub9c9\uace0\uad74 \u2014 \ube44\ub2e8 \uc704\uc758 \ubd88\ud654\ub294 \ub204\uad6c\uc758 \uc18c\ub9dd\uc744 \ub2f4\uc558\uc744\uae4c \uc624\uc544\uc2dc\uc2a4\uc758 \uc2e0\uc559\uacfc \uacf5\uc591\uc790, \ube44\ub2e8 \uadf8\ub9bc\uc758 \ubcf4\uc874\uacfc \uc774\ub3d9 \ub9c9\uace0\uad74\uc758 \uacf5\uac04\uacfc \ud734\ub300\ud558\ub294 \ubd88\ud654, \uc791\uc740 \uae30\uc99d\uc790\uc640 \ud6c4\ub300 \uc790\ub8cc \uc774\ub3d9\uc744 \ud1b5\ud574 \uc0ac\ub78c\ub4e4\uc758 \uc18c\ub9dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \uc0ac\ub9c9\uc758 \uc624\uc544\uc2dc\uc2a4 \uac00\uae4c\uc6b4 \uc808\ubcbd\uc5d0 \uc218\ub9ce\uc740 \ub3d9\uad74\uc774 \uc788\ub2e4. \uc911\uad6d \ub454\ud669\uc758 \ub9c9\uace0\uad74\uc5d0\uc11c\ub294 \ubc14\uc704\ub97c \ud30c \ub9cc\ub4e0 \uacf5\uac04\uacfc \ubcbd\ud654, \ubd88\uad50 \uc870\uac01\uc774 \ub9cc\ub09c\ub2e4. \uadf8\ub7f0\ub370 \uc774\uacf3\uc744 \uc774\ud574\ud560 \uc790\ub8cc\ub294 \ubcbd\uc5d0\ub9cc \ub0a8\uc544 \uc788\uc9c0 \uc54a\ub2e4. \uc791\uc740 \ubc29\uc5d0\uc11c \ub098\uc628 \ube44\ub2e8 \uadf8\ub9bc\uacfc \ubb38\uc11c\ub3c4 \uadf8\uacf3\uc744 \uc624\uac04 \uc0ac\ub78c\ub4e4\uc758 \uc138\uacc4\ub97c \uc804\ud55c\ub2e4. \uc774\ubc88\uc5d0\ub294 \ucee4\ub2e4\ub780 \uc720\uc801\uc758 \uc804\uacbd\ubcf4\ub2e4 \ud734\ub300\ud560 \uc218 \uc788\ub294 \ubd88\ud654\uc640 \uadf8 \uc548\uc758 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uc2dc\uc120\uc744 \ub9de\ucdb0 \ubcf4\uc790. \ub204\uac00 \uadf8\ub9bc\uc744 \ubc14\ucce4\uace0 \ubb34\uc5c7\uc744 \ubc14\ub790\ub294\uc9c0, \ud6c4\ub300\uc5d0\ub294 \uadf8 \uadf8\ub9bc\uc774 \uc5b4\ub5bb\uac8c \ub2e4\ub978 \uc7a5\uc18c\ub85c \uc62e\uaca8\uc84c\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uba74 \ub454\ud669\uc758 \uc5ed\uc0ac\uac00 \uc5ec\ub7ec \uacb9\uc73c\ub85c \uc5f4\ub9b0\ub2e4. \ub454\ud669\uc740 \uc5ec\ub7ec \uad50\uc5ed\uacfc \uc774\ub3d9\uc758 \uacbd\ub85c\uac00 \ub9cc\ub098\ub294 \uc704\uce58\uc5d0 \uc788\uc5c8\ub2e4. \uc0ac\ub9c9\uc758 \uac00\uc7a5\uc790\ub9ac\uc5d0\uc11c \ubb3c\uacfc \uba38\ubb3c \uacf3\uc740 \uc5ec\ud589\uc758 \uc870\uac74\uc774\uc5c8\ub2e4. \ub3d9\uc2dc\uc5d0 \uc0ac\ub78c\ub4e4\uc740 \uc0c1\ud488\ub9cc \ub098\ub974\uc9c0 \uc54a\uc558\ub2e4. \uc5b8\uc5b4\uc640 \uc2e0\uc559, \uadf8\ub9bc\uc758 \ubc29\uc2dd\uacfc \uc774\uc57c\uae30\ub3c4 \ud568\uaed8 \uc6c0\uc9c1\uc600\ub2e4. \uc624\uc544\uc2dc\uc2a4\uc758 \ubb38\ud654\ub294 \uc774\ub7f0 \uc774\ub3d9\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uad50\ub958\ub77c\ub294 \ub9d0\uc744 \ubaa8\ub4e0 \ub9cc\ub0a8\uc774 \ud3c9\ud654\ub86d\uace0 \ud3c9\ub4f1\ud588\ub2e4\ub294 \ub73b\uc73c\ub85c \ubc1b\uc544\ub4e4\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uae38\uc5d0\ub294 \ud1b5\uc81c\uc640 \ucda9\ub3cc\ub3c4 \uc788\uc5c8\ub2e4. \ub2e4\ub9cc \ub454\ud669\uc758 \ubd88\uad50 \uc774\ubbf8\uc9c0\ub97c \ud55c \uc9c0\uc5ed\uc5d0\uc11c\ub9cc \uc644\uc131\ub41c \ub2eb\ud78c \uc591\uc2dd\uc73c\ub85c \uc774\ud574\ud558\uae30 \uc5b4\ub835\ub2e4\ub294 \uc810\uc740 \uc911\uc694\ud558\ub2e4. \uc5ec\ub7ec \ubc29\ud5a5\uc73c\ub85c \uc774\uc5b4\uc9c4 \uae38\uc774 \uadf8 \uc2dc\uac01\uc801 \uc138\uacc4\uc758 \ubc30\uacbd\uc774\uc5c8\ub2e4. \ub9c9\uace0\uad74\uc758 \uc5ec\ub7ec \ub3d9\uad74\uc740 \ubd88\uad50\uc758 \uc608\ubc30\uc640 \uc218\ud589\uc5d0 \uc4f0\uc774\ub294 \uacf5\uac04\uc774\uc5c8\ub2e4. \ubc14\uc704 \uc18d\uc744 \ube44\uc6b0\uace0 \ubcbd\uc744 \uafb8\ubbf8\uba70 \uc0c1\uc744 \ub193\ub294 \uc77c\uc740 \uac74\ucd95\uacfc \ud68c\ud654, \uc870\uac01\uc774 \uacb0\ud569\ud55c \uc791\uc5c5\uc774\ub2e4. \ubcbd\ud654\ub294 \ub530\ub85c \uac78\uc5b4 \ub193\uc740 \uc7a5\uc2dd\uc774 \uc544\ub2c8\ub77c \uadf8 \uacf5\uac04\uc744 \uc0ac\uc6a9\ud558\ub294 \uc0ac\ub78c\uc758 \uc2dc\uc57c\ub97c \ub458\ub7ec\uc2fc\ub2e4. \uc624\ub298\uc758 \uc0ac\uc9c4\uc5d0\uc11c\ub294 \ub3d9\uad74 \ud558\ub098\uc758 \ub300\ud45c \uc7a5\uba74\ub9cc \ubcf4\uc77c \ub54c\uac00 \ub9ce\ub2e4. \uadf8\ub7ec\ub098 \uc2e4\uc81c \uc7a5\uc18c\uc5d0\ub294 \ud06c\uae30\uc640 \uad6c\uc131\uc774 \ub2e4\ub978 \uacf5\uac04\uc774 \uc5ec\ub7ec \uc2dc\ub300\uc5d0 \uac78\uccd0 \uc870\uc131\ub418\uc5c8\ub2e4. \ub9c9\uace0\uad74\uc744 \ud55c \uc0ac\ub78c\uc774 \ud55c \ubc88\uc5d0 \ub9cc\ub4e0 \uac70\ub300\ud55c \uc791\ud488\uc73c\ub85c \uc0dd\uac01\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\ub2e4. \uc624\ub79c \ud6c4\uc6d0\uacfc \uc0ac\uc6a9\uc774 \ubaa8\uc778 \uc720\uc0b0\uc774\ub2e4. \ubc1c\uacac\ub41c \ube44\ub2e8 \ubd88\ud654\ub294 \ubcbd\ud654\uc640 \ub2e4\ub978 \uc131\uaca9\uc744 \uac00\uc9c4\ub2e4. \ud3bc\uce58\uace0 \uac78\uac70\ub098 \uc62e\uae38 \uc218 \uc788\ub294 \ubb3c\uac74\uc774\uc5c8\ub2e4. \ubd88\ubcf4\uc0b4\uacfc \uc815\ud1a0\uc758 \ubaa8\uc2b5, \uc2e0\uc559\uc758 \uc7a5\uba74\uc744 \ub2f4\uc544 \uc608\ubc30\uc640 \uae30\uc6d0\uc758 \uad00\uacc4 \uc18d\uc5d0\uc11c \uc4f0\uc600\ub2e4. \uac19\uc740 \ubd88\uad50 \uadf8\ub9bc\uc774\ub77c\ub3c4 \uc5b4\ub290 \ud45c\uba74\uc5d0 \uc5b4\ub5a4 \ud06c\uae30\ub85c \ub0a8\uacbc\ub294\uc9c0\uc5d0 \ub530\ub77c \uc0ac\uc6a9 \ubc29\uc2dd\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc774\ubbf8\uc9c0\ub97c \ubcfc \ub54c\uc5d0\ub294 \uc911\uc2ec\uc758 \ud070 \uc778\ubb3c\ub9cc \ucc3e\uc9c0 \ub9d0\uace0 \ub458\ub808\uc758 \uc791\uc740 \uc7a5\uba74\uacfc \uae00, \uc544\ub798\ucabd\uc758 \uc0ac\ub78c\ub3c4 \uc0b4\ud3b4\ubcf4\uba74 \uc88b\ub2e4. \ub3c4\uc0c1\uc740 \uc2e0\uc131\ud55c \uc138\uacc4\ub97c \ub098\ud0c0\ub0b4\uba74\uc11c \uadf8\ub9bc\uc744 \ub9c8\ub828\ud55c \uc0ac\ub78c\uc758 \ud604\uc2e4\uacfc\ub3c4 \uc5f0\uacb0\ub41c\ub2e4. \uc885\uad50 \ubbf8\uc220\uc744 \uc544\ub984\ub2e4\uc6b4 \uc591\uc2dd\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b4 \uc774\uc720\ub2e4. \ubd88\ud654\uc5d0\ub294 \ub54c\ub85c \uacf5\uc591\uc790\ub098 \uae30\uc99d\uc790\uc758 \ubaa8\uc2b5\uacfc \uae00\uc774 \ub0a8\ub294\ub2e4. \uc911\uc2ec\uc758 \ubd88\ubcf4\uc0b4\ubcf4\ub2e4 \uc791\uac8c \uadf8\ub824\uc84c\ub354\ub77c\ub3c4 \uadf8 \uc0ac\ub78c\uc740 \uadf8\ub9bc\uc758 \uc5ed\uc0ac\uc5d0\uc11c \uc911\uc694\ud558\ub2e4. \ub204\uad70\uac00\uac00 \uc790\uc6d0\uc744 \ub4e4\uc5ec \uc774 \uc774\ubbf8\uc9c0\ub97c \ub9c8\ub828\ud588\uace0 \uae30\ub3c4\ud560 \uc774\uc720\uac00 \uc788\uc5c8\ub2e4\ub294 \ud754\uc801\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \uc2e0\uc559\uc758 \ub300\uc0c1\uacfc \ud6c4\uc6d0\uc758 \ud589\uc704\uac00 \uac19\uc740 \ud654\uba74\uc5d0 \uc788\ub2e4. \uc774\ub97c \ud1b5\ud574 \ud6c4\ub300\uc758 \ub3c5\uc790\ub294 \uc655\uc774\ub098 \uc720\uba85\ud55c \uc2b9\ub824\ub9cc\uc774 \uc544\ub2c8\ub77c \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc18c\ub9dd\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc791\uc740 \ud615\uc0c1 \ud558\ub098\ub85c \uae30\uc99d\uc790\uc758 \uc0b6 \uc804\uccb4\ub97c \uc54c\uc544\ub0c8\ub2e4\uace0 \uc5ec\uaca8\uc11c\ub294 \uc548 \ub41c\ub2e4. \ub0a8\uc740 \uc774\ub984\uacfc \uc637\ucc28\ub9bc, \uae00\uc758 \uc131\uaca9\uc744 \ub300\uc870\ud558\uba70 \uc5b4\ub514\uae4c\uc9c0 \uc54c \uc218 \uc788\ub294\uc9c0 \uc815\ud574\uc57c \ud55c\ub2e4. 20\uc138\uae30 \ucd08, \uc624\ub7ab\ub3d9\uc548 \ub2eb\ud600 \uc788\ub358 \uacf5\uac04\uc5d0\uc11c \ub9ce\uc740 \ubb38\uc11c\uc640 \uadf8\ub9bc\uc774 \uc54c\ub824\uc84c\ub2e4. \ubc1c\uacac\ub41c \uc790\ub8cc\ub294 \ud55c \uc2dc\ub300\uc758 \ud55c \uc885\ub958\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\uc558\ub2e4. \uc5ec\ub7ec \uae30\ub85d\uc774 \ud568\uaed8 \ub0a8\uc544 \uc788\uc5b4 \uc774\uacf3\uc758 \uc2e0\uc559\uacfc \uc5b8\uc5b4, \uc774\ubbf8\uc9c0\uc758 \uc5ed\uc0ac\ub97c \uc77d\uc744 \uae30\ud68c\uac00 \ucee4\uc84c\ub2e4. \uc65c \uc790\ub8cc\ub97c \ub123\uace0 \uc785\uad6c\ub97c \ub9c9\uc558\ub294\uc9c0\uc5d0 \ub300\ud574\uc11c\ub294 \uc2e0\uc911\ud574\uc57c \ud55c\ub2e4. \uc624\ub798\ub41c \uc5f0\uad6c\uc11c\uc5d0\ub294 \uce68\uc785\uc758 \uc704\ud611\uacfc \uae09\ud55c \ud53c\ub09c\uc744 \uc5f0\uacb0\ud558\ub294 \ucd94\uc815\ub3c4 \ub098\uc624\uc9c0\ub9cc \uadf8\uac83\uc744 \ud655\uc815\ub41c \ud558\ub098\uc758 \uc7a5\uba74\ucc98\ub7fc \uc7ac\ud604\ud560 \uc218\ub294 \uc5c6\ub2e4. \ubcf4\uad00\ub41c \uc0ac\uc2e4\uacfc \ubcf4\uad00\uc758 \uc774\uc720\ub97c \uc124\uba85\ud558\ub294 \uac00\uc124\uc740 \ub2e4\ub978 \uc218\uc900\uc758 \uc8fc\uc7a5\uc774\ub2e4. \uc544\uc6b0\ub810 \uc2a4\ud0c0\uc778\uacfc \ud3f4 \ud3a0\ub9ac\uc624 \ub4f1\uc740 \ub454\ud669 \uc790\ub8cc\ub97c \uc870\uc0ac\ud558\uace0 \ub9ce\uc740 \ubb3c\uac74\uc744 \uad6d\uc678\ub85c \uac00\uc838\uac14\ub2e4. \uc624\ub798\ub41c \ub3c4\ub85d\uc740 \uc774 \uacfc\uc815\uc744 \uc5f0\uad6c\uc790\uc758 \ubc1c\uacac\uacfc \uc131\uacfc\ub97c \uc911\uc2ec\uc73c\ub85c \uc804\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \ucc45\uc758 \uc2dc\uc120\uc774 \uc790\ub8cc\uc640 \uad00\ub828\ub41c \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \uc785\uc7a5\uc744 \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub9bc\uc744 \uc5f0\uad6c\ud560 \uc218 \uc788\uac8c \ub41c \uacfc\uc815\uacfc \ubb3c\uac74\uc774 \uc6d0\ub798\uc758 \uc7a5\uc18c\ub97c \ub5a0\ub09c \uacfc\uc815\uc740 \ud568\uaed8 \uc788\uc5c8\ub2e4. \ud611\uc0c1\uacfc \uc218\uc9d1\uc774 \uc5b4\ub5a4 \uad8c\ub825 \uad00\uacc4 \uc18d\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc84c\ub294\uc9c0 \ubb3b\uac8c \ub41c\ub2e4. \uc624\ub298 \ub2e4\ub978 \ubc15\ubb3c\uad00\uc774\ub098 \ucc45\uc5d0\uc11c \ubd88\ud654\ub97c \ub9cc\ub0a0 \ub54c\uc5d0\ub3c4 \ud604\uc7ac\uc758 \uc18c\uc7a5 \uc7a5\uc18c\ub9cc\uc774 \uadf8 \ubb3c\uac74\uc758 \uc804\uccb4 \uc5ed\uc0ac\ub77c\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\ub2e4. \ub3c4\ub85d\uc740 \uc811\ud788\uace0 \ubd80\uc11c\uc9c0\uae30 \uc26c\uc6b4 \ube44\ub2e8 \uadf8\ub9bc\uc744 \ud3bc\uce58\uace0 \uc815\ub9ac\ud558\ub294 \ub370\uc5d0\ub3c4 \uc624\ub79c \uc77c\uc774 \ud544\uc694\ud588\ub2e4\uace0 \uc804\ud55c\ub2e4. \uc790\ub8cc\ub97c \uac00\uc838\uc654\ub2e4\uace0 \uace7\ubc14\ub85c \uc77d\uc744 \uc218 \uc788\ub294 \uc0c1\ud0dc\uac00 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubcf4\uc874\uacfc \uc815\ub9ac\uc758 \uc190\uae38\ub3c4 \uc624\ub298 \uc6b0\ub9ac\uac00 \ubcf4\ub294 \uc774\ubbf8\uc9c0\uc5d0 \uc5f0\uacb0\ub41c\ub2e4. \uadf8 \uacfc\uc815\uc774 \ub0a8\uae34 \ud310\ub2e8\uae4c\uc9c0 \ud568\uaed8 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ub454\ud669 \ubd88\ud654\uc758 \uc0c9\uacfc \uc120\uc744 \uac10\uc0c1\ud558\ub294 \uc77c\uc740 \uc911\uc694\ud558\ub2e4. \uc5ec\uae30\uc5d0 \uc774\ub3d9\uc758 \uae38\uacfc \uae30\uc99d\uc790\uc758 \uc18c\ub9dd, \ubcf4\uad00\uacfc \uc218\uc9d1\uc758 \uc2dc\uac04\uc744 \ub354\ud558\uba74 \uadf8\ub9bc\uc740 \ud6e8\uc52c \uad6c\uccb4\uc801\uc778 \ubb3c\uac74\uc774 \ub41c\ub2e4. \uc5b4\ub290 \uc2dc\ub300\uc758 \ub204\uad70\uac00\uc5d0\uac8c \ud544\uc694\ud588\uace0, \uc5ec\ub7ec \uc0ac\ub78c\uc758 \ud310\ub2e8\uc744 \uac70\uccd0 \uc9c0\uae08\uae4c\uc9c0 \ub0a8\uc740 \uc790\ub8cc\ub2e4. \ub9c9\uace0\uad74\uc744 \uc2e4\ud06c\ub85c\ub4dc\uc758 \ud654\ub824\ud55c \ubcf4\ubb3c\uc774\ub77c\ub294 \ub9d0\ub85c\ub9cc \ubb36\uc9c0 \ub9d0\uace0 \ud55c \uadf8\ub9bc\uc758 \uc791\uc740 \uc778\ubb3c\uacfc \uae00\ubd80\ud130 \uc0b4\ud3b4\ubcf4\uc790. \uc2e0\uc131\ud55c \uc138\uacc4\ub97c \ub098\ud0c0\ub0b8 \uc774\ubbf8\uc9c0 \uc548\uc5d0 \uc2e4\uc81c\ub85c \uae30\ub3c4\ud558\uace0 \ud6c4\uc6d0\ud55c \uc0ac\ub78c\uc774 \uc788\ub2e4. \uadf8 \ub458\uc744 \ud568\uaed8 \uc77d\ub294 \uc21c\uac04 \uc0ac\ub9c9\uc758 \uc624\ub798\ub41c \uadf8\ub9bc\uc740 \uba3c \ubb38\uba85\uc758 \uc7a5\uc2dd\ubcf4\ub2e4 \uac00\uae4c\uc6b4 \uc778\uac04\uc758 \uae30\ub85d\uc774 \ub41c\ub2e4."}, {"id": "eighty-days-time-and-travel", "title": "80\uc77c\uac04\uc758 \uc138\uacc4 \uc77c\uc8fc \u2014 \uc2dc\uacc4\ubcf4\ub2e4 \ub2a6\uac8c \uc54c\uac8c \ub41c \uc5ec\ud589\uc758 \uc758\ubbf8", "summary": "\uad50\ud1b5\uc218\ub2e8\uacfc \uc2dc\uac04 \uacc4\uc0b0\uc744 \ub530\ub77c\uac00\uba70 \ud3ec\uadf8\uac00 \ub0b4\uae30 \ubc16\uc5d0\uc11c \uc5bb\uc740 \uac83\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/eighty-days-time-and-travel/index.html", "image": "../media/eighty-days-time-and-travel.png", "alt": "1870\ub144\ub300 \uae30\ucc28\uc5ed \ubd84\uc704\uae30 \uc18d\uc5d0\uc11c \ud68c\uc911\uc2dc\uacc4\ub97c \ubcf4\ub294 \ud3ec\uadf8\uc640 \uae30\ucc28\ub97c \uc0b4\ud53c\ub294 \ud30c\uc2a4\ud30c\ub974\ud22c\ub97c \uadf8\ub9b0 \uc0c1\uc0c1 \uc0bd\ud654.", "text": "80\uc77c\uac04\uc758 \uc138\uacc4 \uc77c\uc8fc \u2014 \uc2dc\uacc4\ubcf4\ub2e4 \ub2a6\uac8c \uc54c\uac8c \ub41c \uc5ec\ud589\uc758 \uc758\ubbf8 \ud3ec\uadf8\uc640 \ud30c\uc2a4\ud30c\ub974\ud22c, \uacc4\ud68d\uacfc \uc6b0\uc5f0\uc774 \ud568\uaed8 \uc6c0\uc9c1\uc774\ub294 \ubaa8\ud5d8 \uad50\ud1b5\uc218\ub2e8\uacfc \uc2dc\uac04 \uacc4\uc0b0\uc744 \ub530\ub77c\uac00\uba70 \ud3ec\uadf8\uac00 \ub0b4\uae30 \ubc16\uc5d0\uc11c \uc5bb\uc740 \uac83\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \ub9e4\uc77c \uac19\uc740 \uc2dc\uac04\uc5d0 \uc9d1\uc744 \ub098\uc11c\uace0 \uac19\uc740 \uc2b5\uad00\uc744 \uc9c0\ud0a4\ub294 \uc0ac\ub78c\uc774 \uc788\ub2e4. \ud544\ub9ac\uc5b4\uc2a4 \ud3ec\uadf8\uc5d0\uac8c \ud558\ub8e8\ub294 \uc815\ubc00\ud558\uac8c \ub9de\ucd98 \uc2dc\uacc4\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uadf8\ub7f0\ub370 \uadf8\uac00 \uc5b4\ub290 \ub0a0 80\uc77c \uc548\uc5d0 \uc138\uacc4\ub97c \ub3cc\uc544\uc624\uaca0\ub2e4\ub294 \ub0b4\uae30\uc5d0 \ub098\uc120\ub2e4. \uc9c8\uc11c\uc815\uc5f0\ud55c \uc0ac\ub78c\uc774 \uc608\uce21\ud560 \uc218 \uc5c6\ub294 \uc138\uacc4\ub85c \ub4e4\uc5b4\uac00\ub294 \uc21c\uac04\uc774\ub2e4. \uc958 \ubca0\ub978\uc758 \u300e80\uc77c\uac04\uc758 \uc138\uacc4 \uc77c\uc8fc\u300f\uc5d0\uc11c\ub294 \uae30\ucc28\uc640 \ubc30\uac00 \uae38\uc744 \uc787\uace0 \uc0ac\uace0\uc640 \uc624\ud574\uac00 \uadf8 \uae38\uc744 \uc790\uafb8 \ubc14\uafbc\ub2e4. \uc0c8\ub85c\uc6b4 \ud558\uc778 \ud30c\uc2a4\ud30c\ub974\ud22c\ub294 \uc870\uc6a9\ud55c \uc77c\uc790\ub9ac\ub97c \uae30\ub300\ud588\ub2e4\uac00 \ub73b\ubc16\uc758 \ubaa8\ud5d8\uc5d0 \ud718\ub9d0\ub9b0\ub2e4. \uc544\ub798\uc5d0\ub294 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4. \uc774\uc57c\uae30\uc758 \ucd9c\ubc1c\uc810\uc740 1872\ub144 \ub7f0\ub358\uc774\ub2e4. \ub9ac\ud3fc \ud074\ub7fd\uc5d0\uc11c \uc138\uacc4 \uc5ec\ud589\uc5d0 \uac78\ub9ac\ub294 \uc2dc\uac04\uc744 \ub17c\ud558\ub358 \ud3ec\uadf8\ub294 80\uc77c\uc774\ub77c\ub294 \uacc4\uc0b0\uc5d0 \uc790\uae30 \ub3c8 2\ub9cc \ud30c\uc6b4\ub4dc\ub97c \uac74\ub2e4. \uae30\ucc28\uc640 \uc99d\uae30\uc120\uc758 \uc5f0\uacb0\uc774 \uc138\uacc4\ub97c \ub354 \uc791\uac8c \ubcf4\uc774\uac8c \ud558\ub358 \uc2dc\ub300\ub2e4. \ud558\uc9c0\ub9cc \uc608\uc815\ud45c\uc5d0\uc11c \uc120 \ud558\ub098\ub85c \uc774\uc5b4\uc9c0\ub294 \uae38\ub3c4 \ud604\uc7a5\uc5d0\uc11c\ub294 \ub2e4\ub974\ub2e4. \uae30\ucc28\ub97c \ub193\uce60 \uc218 \uc788\uace0 \ubc30\uc758 \ucd9c\ud56d \uc2dc\uac04\uc774 \ubc14\ub014 \uc218 \uc788\uc73c\uba70, \ub178\uc120\uc774 \uc644\uc131\ub418\uc5c8\ub2e4\ub294 \ub9d0\uacfc \uc2e4\uc81c\ub85c \ub05d\uae4c\uc9c0 \ub2ec\ub9b4 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc5b4\uae0b\ub098\uae30\ub3c4 \ud55c\ub2e4. \uacc4\uc0b0 \uac00\ub2a5\ud55c \uc2dc\uac04\uacfc \ubab8\uc73c\ub85c \ud1b5\uacfc\ud574\uc57c \ud558\ub294 \uc2dc\uac04\uc774 \uc18c\uc124\uc758 \uae34\uc7a5\uc744 \ub9cc\ub4e0\ub2e4. \ud3ec\uadf8\ub294 \uce68\ucc29\ud558\uace0 \ub3c8\uc744 \uc368\uc11c\ub77c\ub3c4 \uc77c\uc815\uc744 \uc9c0\ud0a4\ub824 \ud55c\ub2e4. \ud30c\uc2a4\ud30c\ub974\ud22c\ub294 \uc8fc\ubcc0\uc744 \uad81\uae08\ud574\ud558\uace0 \uc0ac\ub78c\uacfc \ubd80\ub52a\uce58\uba70 \ub2f9\ud669\ud558\uae30\ub3c4 \ud55c\ub2e4. \uac19\uc740 \ubaa9\uc801\uc9c0\ub85c \uac00\uc9c0\ub9cc \uc138\uacc4\ub97c \ub300\ud558\ub294 \ubc29\uc2dd\uc774 \ub2e4\ub974\ub2e4. \ub3c5\uc790\ub294 \ub450 \uc0ac\ub78c\uc758 \ucc28\uc774 \ub355\ubd84\uc5d0 \uc2dc\uac04\ud45c \ubc16\uc758 \uc7a5\uba74\ub4e4\ub3c4 \ub9cc\ub098\uac8c \ub41c\ub2e4. \uc5b4\ub290 \ud55c\ucabd\uc774 \ub298 \uc633\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \ube60\ub978 \ud310\ub2e8\uc774 \uc704\uae30\ub97c \ud480 \ub54c\ub3c4 \uc788\uace0, \ud638\uae30\uc2ec\uacfc \uc2e4\uc218\uac00 \ub73b\ubc16\uc758 \uace4\ub780\uc744 \ub9cc\ub4e4 \ub54c\ub3c4 \uc788\ub2e4. \ub450 \uc0ac\ub78c\uc774 \uc11c\ub85c\uc758 \ubd80\uc871\ud55c \ubd80\ubd84\uc744 \ucc44\uc6b0\uac70\ub098 \ub2e4\uc2dc \uc218\uc2b5\ud558\ub294 \uacfc\uc815\uc774 \uc5ec\ud589\uc744 \ub2e8\uc21c\ud55c \uae30\ub85d \uacbd\uc7c1 \uc774\uc0c1\uc758 \uc774\uc57c\uae30\ub85c \ub9cc\ub4e0\ub2e4. \ud615\uc0ac \ud53d\uc2a4\ub294 \ud3ec\uadf8\ub97c \uc740\ud589 \uc808\ub3c4 \uc0ac\uac74\uc758 \ubc94\uc778\uc73c\ub85c \uc758\uc2ec\ud55c\ub2e4. \uae09\ud788 \ub9ce\uc740 \ub3c8\uc744 \uac00\uc9c0\uace0 \uc774\ub3d9\ud558\ub294 \ud589\ub3d9\uc774 \uadf8\uc758 \ub208\uc5d0\ub294 \ub3c4\uc8fc\ucc98\ub7fc \ubcf4\uc778\ub2e4. \ud3ec\uadf8\uc5d0\uac8c\ub294 \ub0b4\uae30\uc758 \uc77c\uc815\uc774\uc9c0\ub9cc \ud53d\uc2a4\uc5d0\uac8c\ub294 \ubc94\uc778\uc758 \ud754\uc801\uc774\ub2e4. \uac19\uc740 \ud589\ub3d9\uc744 \uc11c\ub85c \ub2e4\ub978 \uc774\uc57c\uae30 \uc548\uc5d0\uc11c \ud574\uc11d\ud558\ub294 \uc148\uc774\ub2e4. \uc624\ud574\ub294 \ub2e8\uc21c\ud55c \uc7a5\uc2dd\uc774 \uc544\ub2c8\ub2e4. \uc758\uc2ec\ud55c \uc0ac\ub78c\uc774 \uc790\uae30 \ud574\uc11d\uc744 \ud655\uc2e0\ud558\uba70 \uc6c0\uc9c1\uc77c \ub54c \ub2e4\ub978 \uc0ac\ub78c\uc758 \uae38\uc774 \uc2e4\uc81c\ub85c \ub9c9\ud78c\ub2e4. \ub3c5\uc790\ub294 \ud3ec\uadf8\uac00 \uc5b4\ub5a4 \uc0ac\ub78c\uc778\uc9c0 \uc54c\uace0 \uc9c0\ucf1c\ubcf4\ubbc0\ub85c \ud53d\uc2a4\uc758 \ucd94\uc801\uc5d0\uc11c \ub2f5\ub2f5\ud568\uacfc \uc6c3\uc74c\uc744 \ud568\uaed8 \ub290\ub07c\uac8c \ub41c\ub2e4. \uc5ec\ud589 \uc911 \uc778\ub3c4\uc758 \ucca0\uae38\uc774 \uc774\uc5b4\uc9c0\uc9c0 \uc54a\uc740 \uad6c\uac04\uc744 \ub9cc\ub098\uc790 \uc77c\ud589\uc740 \ub2e4\ub978 \uc774\ub3d9 \uc218\ub2e8\uc744 \uad6c\ud55c\ub2e4. \ucf54\ub07c\ub9ac\ub97c \ud0c0\uace0 \ub098\uc544\uac00\ub294 \uacfc\uc815\uc5d0\uc11c \uc544\uc6b0\ub2e4\ub97c \uad6c\ud558\uac8c \ub41c\ub2e4. \uc2dc\uac04\uc744 \uc544\uaef4\uc57c \ud558\ub294 \ud3ec\uadf8\uac00 \ub2e4\ub978 \uc0ac\ub78c\uc744 \uc704\ud574 \uc704\ud5d8\uacfc \uc9c0\uc5f0\uc744 \uac10\uc218\ud558\ub294 \ub300\ubaa9\uc774\ub2e4. \uc774 \uc7a5\uba74\uc744 \uc77d\uc744 \ub54c\uc5d0\ub294 \ub2f9\uc2dc \uc720\ub7fd \uc18c\uc124\uc774 \ub0af\uc120 \uc9c0\uc5ed\uc744 \uadf8\ub9ac\ub294 \ubc29\uc2dd\ub3c4 \ud568\uaed8 \uc0dd\uac01\ud558\uba74 \uc88b\ub2e4. \uc791\ud488 \uc18d \uc704\ud5d8\uacfc \ud48d\uc2b5 \ubb18\uc0ac\ub97c \uadf8 \ub098\ub77c \uc0ac\ub78c\ub4e4\uc758 \uc0dd\ud65c \uc804\uccb4\ub85c \uc77c\ubc18\ud654\ud560 \uc218\ub294 \uc5c6\ub2e4. \ubaa8\ud5d8\uc758 \uc7ac\ubbf8\ub97c \uc77d\uc73c\uba74\uc11c\ub3c4 \uc11c\uc220\uc790\uc758 \uc2dc\uc120\uc774 \uc5b4\ub514\uc5d0\uc11c \uc654\ub294\uc9c0 \uc0b4\ud544 \uc5ec\uc9c0\ub294 \uc788\ub2e4. \uc544\uc6b0\ub2e4\ub294 \uad6c\uc870 \ub4a4 \uc5ec\ud589\uc758 \ub3d9\ud589\uc790\uac00 \ub41c\ub2e4. \ud3ec\uadf8\uc758 \ucc98\uc74c \uacc4\ud68d\uc5d0\ub294 \uc5c6\ub358 \uc0ac\ub78c\uc774\ub2e4. \ub0af\uc120 \uc774\ub97c \ub3d5\ub294 \uc120\ud0dd\uc774 \uc77c\ud589\uc758 \uad6c\uc131\uacfc \uc774\ud6c4\uc758 \uc0b6\uc744 \ubc14\uafbc\ub2e4. \uc5ec\ud589\uc774\ub780 \uc608\uc815\ud55c \uc9c0\uc810\uc744 \ud655\uc778\ud558\ub294 \uc77c\ub9cc\uc774 \uc544\ub2c8\ub77c \uc608\uc0c1\ud558\uc9c0 \ubabb\ud55c \uad00\uacc4\ub97c \ubc1b\uc544\ub4e4\uc774\ub294 \uc2dc\uac04\uc774\uae30\ub3c4 \ud558\ub2e4\ub294 \uc77d\uae30\uac00 \uac00\ub2a5\ud558\ub2e4. \ud3ec\uadf8\uac00 \ubaa8\ub4e0 \uad6c\uac04\uc5d0\uc11c \uac10\uc815\uc744 \uae38\uac8c \uc124\uba85\ud558\ub294 \uc778\ubb3c\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub798\uc11c \ub3c5\uc790\ub294 \ub9d0\ubcf4\ub2e4 \uc5b4\ub5a4 \uc0c1\ud669\uc5d0\uc11c \ub3c8\uacfc \uc2dc\uac04\uc744 \uc4f0\ub294\uc9c0 \uad00\ucc30\ud558\uac8c \ub41c\ub2e4. \uacc4\uc0b0\uc744 \uc798\ud558\ub294 \uc0ac\ub78c\uc774\ub77c\ub294 \uc18c\uac1c\ub9cc\uc73c\ub85c \uadf8\uc758 \ud589\ub3d9\uc744 \ub2e4 \uc774\ud574\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc77c\uc815\uc774 \ubd88\ub9ac\ud574\uc9c8 \ub54c \ubb34\uc5c7\uc744 \ud3ec\uae30\ud558\uc9c0 \uc54a\ub294\uc9c0\uac00 \uadf8\ub97c \ub354 \uc798 \ubcf4\uc5ec \uc900\ub2e4. \ub3d9\uc544\uc2dc\uc544\uc640 \ud0dc\ud3c9\uc591\uc744 \uc9c0\ub098 \ubbf8\uad6d\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uc5ec\uc815\uc5d0\uc11c\ub3c4 \uc77c\ud589\uc740 \uacc4\uc18d \uad50\ud1b5\ud3b8\uc744 \ubc14\uafb8\uace0 \uc2dc\uac04\uc744 \ub9de\ucd98\ub2e4. \uae30\uacc4\uac00 \ube68\ub77c\uc84c\ub2e4\uace0 \uc5ec\ud589\uc774 \ub9c8\ucc30 \uc5c6\uc774 \uc9c4\ud589\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uae38\uc758 \uc870\uac74\uacfc \uc0ac\ub78c\ub4e4\uc758 \uacb0\uc815\uc774 \ub9e4\ubc88 \uc0ac\uc774\uc5d0 \ub07c\uc5b4\ub4e0\ub2e4. \ud754\ud788 \uac01\uc0c9\uc758 \uc774\ubbf8\uc9c0\ub85c \ub5a0\uc62c\ub9ac\ub294 \uc5f4\uae30\uad6c\uac00 \uc6d0\uc791\uc758 \uc138\uacc4 \uc77c\uc8fc\ub97c \ub04c\uace0 \uac00\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc6d0\ubb38\uc5d0\uc11c\ub294 \ucca0\ub3c4\uc640 \uc5ec\ub7ec \ubc30, \ucf54\ub07c\ub9ac \ub4f1 \uad6c\uccb4\uc801\uc778 \uc218\ub2e8\uc774 \uc911\uc694\ud558\ub2e4. \uc5b4\ub5a4 \uc7a5\uba74\uc744 \uae30\uc5b5\ud558\uace0 \uc788\uc5c8\ub294\uc9c0 \uc6d0\uc791\uacfc \ube44\uad50\ud558\ub294 \uc7ac\ubbf8\ub3c4 \uc788\ub2e4. \uc774\ubc88 \uc0bd\ud654\ub3c4 \uc774\ub3d9\uacfc \uae30\ub2e4\ub9bc\uc774 \ub9cc\ub098\ub294 \uae30\ucc28\uc5ed\uc758 \ubd84\uc704\uae30\ub97c \uc120\ud0dd\ud588\ub2e4. \uc601\uad6d\uc5d0 \ub3cc\uc544\uc628 \ub4a4 \ud53d\uc2a4\uc758 \uccb4\ud3ec \ub54c\ubb38\uc5d0 \uc2dc\uac04\uc774 \ub354 \uc9c0\uccb4\ub41c\ub2e4. \ud3ec\uadf8\ub294 \uc790\uc2e0\uc774 \ub0b4\uae30\uc5d0\uc11c \uc84c\ub2e4\uace0 \ubbff\ub294\ub2e4. \uadf8\ub7ec\ub098 \ud30c\uc2a4\ud30c\ub974\ud22c\uac00 \ub0a0\uc9dc\ub97c \ud655\uc778\ud558\uba74\uc11c \uc0c1\ud669\uc774 \ub4a4\uc9d1\ud78c\ub2e4. \ub3d9\ucabd\uc73c\ub85c \uc138\uacc4\ub97c \ub3cc\uc544\uc628 \ub3d9\uc548 \uacc4\uc0b0\uc5d0 \ud558\ub8e8\uc758 \ucc28\uc774\uac00 \uc0dd\uae34 \uac83\uc744 \ubbf8\ucc98 \uc54c\uc544\ucc28\ub9ac\uc9c0 \ubabb\ud588\ub358 \uac83\uc774\ub2e4. \uc18c\uc124\uc740 \ub9e4\uc77c\uc758 \uc2dc\uac04\uacfc \uc9c0\uad6c\ub97c \ud55c \ubc14\ud034 \ub3c4\ub294 \uc5ec\ud589\uc758 \uad00\uacc4\ub97c \uacb0\ub9d0\uc5d0 \uc5f0\uacb0\ud55c\ub2e4. \uc624\ub298\uc758 \ud45c\uc900\uc2dc \uc81c\ub3c4\ub97c \uadf8 \uc2dc\ub300\uc5d0 \uadf8\ub300\ub85c \uc801\uc6a9\ud574 \ub2e8\uc815\ud558\uae30\ubcf4\ub2e4 \uc791\ud488\uc774 \uc124\uba85\ud558\ub294 \u2018\uc5bb\uc740 \ud558\ub8e8\u2019\uc758 \uc7a5\uce58\ub85c \uc77d\uc73c\uba74 \uc88b\ub2e4. \ubaa8\ub4e0 \uac83\uc744 \uaf3c\uaf3c\ud788 \uacc4\uc0b0\ud558\ub358 \uc0ac\ub78c\ub3c4 \uacc4\uc0b0\uc758 \ud2c0 \ud558\ub098\ub97c \ub193\uce60 \uc218 \uc788\uc5c8\ub2e4\ub294 \uc810\uc774 \uc720\ucf8c\ud558\ub2e4. \ud3ec\uadf8\ub294 \uc57d\uc18d\ud55c \uc2dc\uac04\uc5d0 \ud074\ub7fd\uc5d0 \ub098\ud0c0\ub09c\ub2e4. \uadf8\ub7ec\ub098 \ub9c8\uc9c0\ub9c9 \uc9c8\ubb38\uc740 \uc2b9\ub9ac\ud55c \ub3c8\uc774 \uc5bc\ub9c8\ub0d0\uc5d0\ub9cc \uba38\ubb3c\uc9c0 \uc54a\ub294\ub2e4. \uc544\uc6b0\ub2e4\uc640 \ud568\uaed8\ud560 \uc0b6\uc774 \uc0dd\uacbc\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc5ec\ud589\uc758 \ub2e4\ub978 \uacb0\uc2e4\uc774 \ub41c\ub2e4. \ucc98\uc74c\uc758 \uacc4\uc0b0\uc5d0 \ub4e4\uc5b4 \uc788\uc9c0 \uc54a\uc558\ub358 \uac83\uc774 \ub05d\uc5d0\uc11c\ub294 \uc911\uc694\ud574\uc9c4\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \ud3ec\uadf8\uc640 \ud30c\uc2a4\ud30c\ub974\ud22c\ub97c 1870\ub144\ub300 \ubd84\uc704\uae30\uc758 \uac00\uc0c1 \uae30\ucc28\uc5ed\uc5d0 \ub193\uc558\ub2e4. \uc2e4\uc81c \uc5ed\uc774\ub098 \uc61b \uc778\ubb3c \uc0ac\uc9c4\uc744 \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ud55c \uc0ac\ub78c\uc740 \uc2dc\uacc4\ub97c, \ub2e4\ub978 \uc0ac\ub78c\uc740 \ucd9c\ubc1c\ud560 \uae30\ucc28\ub97c \ubc14\ub77c\ubcf4\ub294 \ub300\ube44\ub85c \uc774\uc57c\uae30\ub97c \uc5f4\uc5c8\ub2e4. \uc138\uacc4\ub97c \ub3cc\uba70 \ub9de\ucd94\ub824\ub358 \uc2dc\uacc4\uc640, \uadf8 \uc5ec\ud589\uc5d0\uc11c \ub9cc\ub098\uac8c \ub41c \uc0ac\ub78c\uc744 \ud568\uaed8 \ub5a0\uc62c\ub9ac\uba70 \uc77d\uc5b4 \ubcf4\uc790."}, {"id": "el-greco-painting-journey", "title": "\uc720\uba85\ud55c \uadf8\ub9bc\ub3c4 \ucc98\uc74c\uc5d0\ub294 \uac70\uc808\ub2f9\ud588\ub2e4", "summary": "\uba54\ub9ac \ucee4\uc0db\uc774 \uc5d8 \uadf8\ub808\ucf54\uc758 \uc131\ubaa8\uc2b9\ucc9c\uc744 \ubbf8\uc220\uad00\uc5d0 \uc5f0\uacb0\ud558\ub824\ub358 \uc774\uc57c\uae30\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/el-greco-painting-journey/index.html", "image": "../media/el-greco-painting-journey.jpg", "alt": "\uc720\uba85\ud55c \uadf8\ub9bc\ub3c4 \ucc98\uc74c\uc5d0\ub294 \uac70\uc808\ub2f9\ud588\ub2e4\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\uc720\uba85\ud55c \uadf8\ub9bc\ub3c4 \ucc98\uc74c\uc5d0\ub294 \uac70\uc808\ub2f9\ud588\ub2e4 \uc5d8 \uadf8\ub808\ucf54\uc758 \uc791\ud488\uc744 \uc704\ud574 \ubc1c \ubc97\uace0 \ub098\uc120 \ud654\uac00 \uba54\ub9ac \ucee4\uc0db\uc774 \uc5d8 \uadf8\ub808\ucf54\uc758 \uc131\ubaa8\uc2b9\ucc9c\uc744 \ubbf8\uc220\uad00\uc5d0 \uc5f0\uacb0\ud558\ub824\ub358 \uc774\uc57c\uae30\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \uc9c0\uae08 \ubbf8\uc220\uad00\uc758 \ub300\ud45c \uc791\ud488\uc774\ub77c\uace0 \ud574\uc11c \ucc98\uc74c\ubd80\ud130 \ubaa8\ub450\uac00 \uac16\uace0 \uc2f6\uc5b4 \ud588\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5d8 \uadf8\ub808\ucf54\uc758 \uc131\ubaa8\uc2b9\ucc9c\uc5d0\ub3c4 \uc120\ub73b \uc0c8 \uc9d1\uc744 \ucc3e\uc9c0 \ubabb\ud558\ub358 \uc2dc\uac04\uc774 \uc788\uc5c8\ub2e4. \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc758 \uacf5\uc2dd \uae00\uc740 \uc774 \uc791\ud488\uc774 \uc5ec\ub7ec \uae30\uad00\uc758 \uac70\uc808\uc744 \uc9c0\ub098 \uc18c\uc7a5\ud488\uc774 \ub41c \uacfc\uc815\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc774\uc57c\uae30\uc758 \uac00\uc6b4\ub370\uc5d0\ub294 \ub2e4\ub978 \ud654\uac00 \uba54\ub9ac \ucee4\uc0db\uc774 \uc788\ub2e4. \uc790\uae30 \uadf8\ub9bc\uc774 \uc544\ub2cc \uc791\ud488\uc744 \uc704\ud574 \uafb8\uc900\ud788 \uc0ac\ub78c\ub4e4\uc744 \uc124\ub4dd\ud55c \uac83\uc774\ub2e4. \ubbf8\uc220\uad00\uc5d0 \ub530\ub974\uba74 \uc791\ud488\uc740 1904\ub144\uc5d0 \uc2dc\uc7a5\uc5d0 \ub098\uc654\ub2e4. \ub2f9\uc2dc \uc5d8 \uadf8\ub808\ucf54\uc758 \ud3c9\ud310\uc740 \uc9c0\uae08 \uc6b0\ub9ac\uac00 \uc0dd\uac01\ud558\ub294 \uac83\uacfc \uac19\uc9c0 \uc54a\uc558\ub2e4. \ub9c8\ub4dc\ub9ac\ub4dc\uc5d0\uc11c \ud314\ub9ac\uc9c0 \ubabb\ud55c \uc791\ud488\uc740 1904\ub144\ubd80\ud130 1905\ub144\uae4c\uc9c0 \ud30c\ub9ac\uc758 \ub4a4\ub791\ub93c\uc5d8 \ud654\ub791\uc5d0\uc11c \uc804\uc2dc\ub418\uc5c8\ub2e4. \uadf8\uacf3\uc5d0\uc11c \ucee4\uc0db\uc744 \ube44\ub86f\ud55c \ud654\uac00\ub4e4\uc774 \uc774 \uc791\ud488\uc5d0 \uad00\uc2ec\uc744 \uac00\uc84c\ub2e4. \ub204\uad70\uac00\uc5d0\uac8c\ub294 \ud314\uae30 \uc5b4\ub824\uc6b4 \uc624\ub798\ub41c \uadf8\ub9bc\uc774 \ub2e4\ub978 \ub204\uad70\uac00\uc5d0\uac8c\ub294 \uaf2d \ubbf8\uc220\uad00\uc5d0 \uc788\uc5b4\uc57c \ud560 \uadf8\ub9bc\uc774\uc5c8\ub358 \uc148\uc774\ub2e4. \ucee4\uc0db\uc740 \uba3c\uc800 \uce5c\uad6c\uc778 \ud558\ube0c\ub9c8\uc774\uc5b4 \ubd80\ubd80\uac00 \ud654\ub791\uc758 \uc791\ud488 \uad6c\uc785\uc744 \uc9c0\uc6d0\ud558\ub3c4\ub85d \uc124\ub4dd\ud588\ub2e4. \uc774\ud6c4 \ubbf8\uad6d \ubbf8\uc220\uad00\ub4e4\uc774 \uad00\uc2ec\uc744 \uac16\ub3c4\ub85d \uc6c0\uc9c1\uc600\ub2e4. \uc791\ud488\uc758 \ub2e4\uc74c \uc8fc\uc18c\ub97c \ucc3e\ub294 \uc77c\uc774 \ud55c \uc0ac\ub78c\uc758 \ubd80\ud0c1\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\uc558\ub358 \uac83\uc774\ub2e4. \ubbf8\uc220\uad00\uc758 \uae00\uc740 \ub274\uc695\uacfc \ud544\ub77c\ub378\ud53c\uc544, \ubcf4\uc2a4\ud134\uc5d0\uc11c \uac70\uc808\uc774 \uc774\uc5b4\uc84c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc624\ub298\uc758 \uba85\uc131\ub9cc \uc0dd\uac01\ud558\uba74 \ub180\ub78d\uc9c0\ub9cc, \uadf8\ub54c\uc758 \uae30\uad00\ub4e4\uc740 \uac01\uc790\uc758 \ud310\ub2e8\uc744 \ud588\ub2e4. \uc720\uba85\ud574\uc9c4 \ub4a4\uc758 \ud3c9\uac00\ub97c \uacfc\uac70\uc5d0 \uadf8\ub300\ub85c \uac00\uc838\uac00\uba74 \ubcf4\uc774\uc9c0 \uc54a\ub294 \ub300\ubaa9\uc774\ub2e4. \uae30\uad00\uc774 \ub2e4\ub8e8\ub294 \uc791\ud488\uc740 \uc5d8 \uadf8\ub808\ucf54\uc758 \u3008\uc131\ubaa8 \uc2b9\ucc9c\u3009\uc774\ub2e4. \uc885\uad50\uc801 \uc8fc\uc81c\ub97c \ub2f4\uc740 \uc624\ub798\ub41c \uadf8\ub9bc\uc774 \uc5ec\ub7ec \uc18c\uc720\uc790\ub97c \uac70\uccd0 \uadfc\ub300\uc758 \uc2dc\uc7a5\uacfc \ubbf8\uc220\uad00\uc744 \ub9cc\ub0ac\ub2e4. \uc9c0\uae08\uc758 \uc804\uc2dc\uc2e4\uc5d0\uc11c \ubcf4\ub294 \ud55c \uc7a5\uba74 \uc774\uc804\uc5d0, \uadf8\ub9bc\uc5d0\ub294 \ub2e4\uc74c \uc8fc\uc778\uc744 \ucc3e\uc73c\uba70 \ub3c4\uc2dc\ub97c \uc62e\uae34 \uc2dc\uac04\uc774 \uc788\uc5c8\ub2e4. \uc18c\uc7a5\ucc98\ub294 \uc791\ud488\uc758 \ucc98\uc74c\ubd80\ud130 \uace0\uc815\ub41c \uc8fc\uc18c\uac00 \uc544\ub2c8\uc5c8\ub2e4. 1904\ub144 \ub9c8\ub4dc\ub9ac\ub4dc\uc5d0\uc11c \ud310\ub9e4\uac00 \uc27d\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc791\ud488\uc758 \uc218\uc900\uc744 \uc624\ub298 \ub300\uc2e0 \ud310\uc815\ud574 \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \ub2f9\uc2dc\uc758 \ucde8\ud5a5\uacfc \ud3c9\uac00, \uad6c\uc785 \uc870\uac74\uc774 \uc11c\ub85c \uc791\uc6a9\ud588\uc744 \uc218 \uc788\ub2e4. \ubbf8\uc220\uad00\uc758 \uc124\uba85\uc740 \ud2b9\ud788 \uadf8 \ubb34\ub835 \uc5d8 \uadf8\ub808\ucf54\uc758 \uba85\uc131\uc774 \ub192\uc9c0 \uc54a\uc558\uc74c\uc744 \uac15\uc870\ud55c\ub2e4. \ud604\uc7ac\uc758 \uc720\uba85\ud568\uc744 \uacfc\uac70\uc758 \ubaa8\ub4e0 \uc0ac\ub78c\ub3c4 \ub2f9\uc5f0\ud788 \uc54c\uc558\uc744 \uac83\uc73c\ub85c \uc5ec\uae30\uc9c0 \uc54a\uc744 \ub54c \uc774\ub3d9\uc758 \uc774\uc57c\uae30\uac00 \ud765\ubbf8\ub85c\uc6cc\uc9c4\ub2e4. \ucee4\uc0db\uc740 \uc791\ud488\uc744 \uc88b\ub2e4\uace0 \ub9d0\ud558\ub294 \ub370\uc11c \uadf8\uce58\uc9c0 \uc54a\uc558\ub2e4. \ud558\ube0c\ub9c8\uc774\uc5b4 \ubd80\ubd80\uc758 \uc9c0\uc6d0\uc744 \ub04c\uc5b4\ub0b4\uace0 \ubbf8\uad6d\uc758 \uc5ec\ub7ec \uae30\uad00\uc774 \uad00\uc2ec\uc744 \uac16\ub3c4\ub85d \uc5f0\uacb0\ud588\ub2e4. \ubbf8\uc220\uad00\uc5d0 \uc88b\uc740 \uadf8\ub9bc\uc774 \ub4e4\uc5b4\uc624\ub294 \uacfc\uc815\uc5d0\ub294 \uac10\uc2dd\uc548\ub9cc\uc774 \uc544\ub2c8\ub77c \uc0ac\ub78c \uc0ac\uc774\uc758 \uc2e0\ub8b0\uc640 \uc2e4\uc81c \uad6c\uc785\uc744 \uac00\ub2a5\ud558\uac8c \ud558\ub294 \uc790\uae08\ub3c4 \ud544\uc694\ud588\ub2e4. \uc791\ud488\uc758 \uac00\uce58\ub97c \uc54c\uc544\ubcf4\ub294 \ud310\ub2e8\uacfc \uadf8 \ud310\ub2e8\uc744 \ud589\ub3d9\uc73c\ub85c \uc62e\uae30\ub294 \uc77c\uc740 \ub2e4\ub978 \ub2e8\uacc4\uc600\ub2e4. \uc774 \ub54c\ubb38\uc5d0 \uadf8\ub9bc\uc744 \ub458\ub7ec\uc2fc \uc0ac\ub78c\uc758 \uc774\ub984\ub3c4 \uc81c\uc791\uc790\uc758 \uc774\ub984 \uc606\uc5d0 \ub193\uc744 \uc218 \uc788\ub2e4. \ub204\uad6c\uc5d0\uac8c \ubcf4\uc5ec \uc8fc\uace0 \uc5b4\ub5bb\uac8c \uc124\ub4dd\ud588\ub294\uc9c0\uac00 \ub2e4\uc74c \uc18c\uc7a5\ucc98\uc5d0 \uc601\ud5a5\uc744 \uc8fc\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4. \ub2e4\ub9cc \ucee4\uc0db\uc774 \ubbf8\ub798\uc758 \uba85\uc131\uc744 \ubaa8\ub450 \uc815\ud655\ud788 \uc608\uacac\ud588\ub2e4\uace0 \uacfc\uc7a5\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub0a8\uc544 \uc788\ub294 \ud589\ub3d9\uc744 \ub530\ub77c\uac00\uba74 \ucda9\ubd84\ud558\ub2e4. \ub2e4\ub978 \uae30\uad00\ub4e4\uc774 \uac70\uc808\ud558\ub294 \ub3d9\uc548\uc5d0\ub3c4 \uc5f0\uacb0\uc744 \uc774\uc5b4 \uac14\ub2e4\ub294 \uc810\uc774 \uad6c\uccb4\uc801\uc778 \uc774\uc57c\uae30\ub2e4. \uc2dc\uce74\uace0\uc5d0\uc11c\uc758 \uad6c\uc785\ub3c4 \ud55c \ubc88\uc758 \uacb0\uc815\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\uc558\ub2e4. \ud544\uc694\ud55c \ub3c8\uc744 \ub9c8\ub828\ud558\ub294 \ub370 19\uac1c\uc6d4\uc774 \uac78\ub838\uace0, \uc774\uc0ac\ud68c \ub0b4\ubd80\uc5d0\ub3c4 \uc791\uac00\uc758 \ubbf8\uc220\uc0ac\uc801 \uc704\uce58\ub97c \uc758\uc2ec\ud558\ub294 \uc2dc\uc120\uc774 \uc788\uc5c8\ub2e4\uace0 \uae00\uc740 \uc804\ud55c\ub2e4. \ubbf8\uc220\uad00\uc774\ub77c\ub294 \uc774\ub984 \uc544\ub798\uc5d0 \ud558\ub098\uc758 \ub9c8\uc74c\ub9cc \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc88b\uc740 \uc791\ud488\uc774\ub77c\ub294 \ud3c9\uac00\ub97c \uacf5\uc720\ud558\uace0 \ube44\uc6a9\uc744 \uac10\uc218\ud560 \uc0ac\ub78c\uc744 \ubaa8\uc544\uc57c \ud588\ub2e4. \uc624\ub298 \ub300\ud45c \uc18c\uc7a5\ud488\uc774 \ub418\uc5c8\ub2e4\ub294 \uacb0\uacfc\ub97c \uc548 \ub4a4 \uc77d\uc73c\uba74 \uae30\ub2e4\ub9bc\uc740 \ub2f9\uc5f0\ud55c \uc808\ucc28\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \ub2f9\uc2dc\uc5d0\ub294 \uacb0\uad6d \uad6c\uc785\ud558\uac8c \ub420\uc9c0 \uc815\ud574\uc838 \uc788\uc9c0 \uc54a\uc558\uc744 \uac83\uc774\ub2e4. \uc774 \ubd88\ud655\uc2e4\uc131\uc744 \uae30\uc5b5\ud558\uba74 \uc791\ud488\uc744 \uc9c0\ucf1c\ub0b8 \ud55c \uc601\uc6c5\uc774\ub77c\ub294 \uc124\uba85\ubcf4\ub2e4 \uc5ec\ub7ec \ud310\ub2e8\uc774 \uc774\uc5b4\uc9c4 \uacfc\uc815\uc744 \ubcf4\uac8c \ub41c\ub2e4. \uc804\uc2dc\uc2e4\uc758 \uace0\uc694\ud55c \ubcbd \ub4a4\uc5d0\ub3c4 \ud1a0\ub860\uacfc \uc2dc\uac04\uc774 \uc788\uc5c8\ub2e4. \uae30\uad00 \uae00\uc740 \uc5b4\ub9b0 \ud5e4\ubc0d\uc6e8\uc774\uac00 \uc5b4\uba38\ub2c8\uc640 \ubbf8\uc220\uad00\uc5d0 \uc640 \uc774 \uadf8\ub9bc\uc744 \ubcf4\uc558\ub2e4\ub294 \uc77c\ud654\ub3c4 \uc18c\uac1c\ud55c\ub2e4. \uadf8\uac00 \ub098\uc911\uc5d0 \uc5d8 \uadf8\ub808\ucf54\uc758 \ub300\ub2f4\ud55c \ud45c\ud604\uacfc \uc790\uae30 \uae00\uc4f0\uae30\ub97c \uc5f0\uacb0\ud574 \ub9d0\ud588\ub2e4\ub294 \uc124\uba85\uc774\ub2e4. \uc774\ub294 \uadf8 \uae00\uc774 \uc804\ud558\ub294 \uc218\uc6a9\uc758 \uc77c\ud654\ub85c \uc77d\uc744 \uc218 \uc788\uc73c\uba70, \ubaa8\ub4e0 \uc791\ud488\uc758 \uc601\ud5a5\ub825\uc744 \uc22b\uc790\ub85c \uc99d\uba85\ud558\ub294 \uc790\ub8cc\ucc98\ub7fc \ub2e4\ub8e8\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub798\ub3c4 \uc791\ud488\uc758 \ub2e4\uc74c \uc2dc\uac04\uc774 \ubb34\uc5c7\uc778\uc9c0 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ubbf8\uc220\uad00\uc774 \uadf8\ub9bc\uc744 \uad6c\uc785\ud55c \ub4a4\uc5d0\ub294 \uc2e4\uc81c\ub85c \ucc3e\uc544\uc628 \uc0ac\ub78c\ub4e4\uc774 \uc790\uae30 \uacbd\ud5d8 \uc18d\uc5d0\uc11c \ub9cc\ub09c\ub2e4. \ub9cc\ub4e4\uc5b4\uc9c4 \uc2dc\ub300\uc758 \ub73b\uacfc \ud6c4\ub300 \uad00\ub78c\uc790\uac00 \uc5bb\uc740 \uc778\uc0c1\uc740 \uac19\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \ud55c \uadf8\ub9bc\uc758 \uc5ec\uc815\uc744 \ubcf8\ub2e4\ub294 \uac83\uc740 \uc2dc\uc7a5\uacfc \uae30\uad00\uc758 \uc774\ub3d9\ubfd0 \uc544\ub2c8\ub77c \ub2e4\ub978 \uc138\ub300\uc758 \uc2dc\uc120\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \uae38\ub3c4 \ubcf4\ub294 \uc77c\uc774\ub2e4. \ub9c8\uce68\ub0b4 \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc774 \uad00\uc2ec\uc744 \ubcf4\uc600\uc9c0\ub9cc \uc790\uae08\uc744 \ubaa8\uc73c\ub294 \ub370\uc5d0\ub3c4 19\uac1c\uc6d4\uc774 \uac78\ub838\ub2e4\uace0 \ud55c\ub2e4. \uc791\ud488\uc740 \ub3c4\ucc29\ud55c \ub4a4 \ubbf8\uc220\uad00\uc744 \ub300\ud45c\ud558\ub294 \uadf8\ub9bc \uac00\uc6b4\ub370 \ud558\ub098\uac00 \ub418\uc5c8\ub2e4. \ud55c \uadf8\ub9bc\uc758 \uc790\ub9ac\ub97c \ub9cc\ub4e0 \uac83\uc740 \ud654\uac00\uc758 \uc190\uae38\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ub2e4\ub978 \ud654\uac00\uc758 \uad00\uc2ec, \uce5c\uad6c\ub4e4\uc758 \uc9c0\uc6d0, \uae30\uad00\uc758 \uacb0\uc815\uacfc \uae30\ub2e4\ub9bc\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \uc804\uc2dc\uc7a5 \ubcbd\uc5d0 \uac78\ub9b0 \ud55c \uc810\uc744 \ubcfc \ub54c \uadf8 \ubcbd\uae4c\uc9c0 \uc624\ub294 \uae38\ub3c4 \uc788\uc5c8\ub2e4\ub294 \uac83\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uc774\uc57c\uae30\ub2e4."}, {"id": "faust-first-part-gretchen-and-desire", "title": "\ud30c\uc6b0\uc2a4\ud2b8 1\ubd80 \u2014 \ub354 \ub9ce\uc740 \uc0b6\uc744 \uc6d0\ud55c \uc0ac\ub78c\uc740 \ub204\uad6c\ub97c \ub2e4\uce58\uac8c \ud588\uc744\uae4c", "summary": "\ub354 \ub9ce\uc740 \uc0b6\uc744 \uc6d0\ud55c \ud559\uc790\uc758 \uc5ec\uc815\uacfc \uadf8\ub808\ud2b8\ud5e8\uc758 \ube44\uadf9\uc744 \ud1b5\ud574 \uc695\ub9dd\uc758 \ub300\uac00\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/faust-first-part-gretchen-and-desire/index.html", "image": "../media/faust-first-part-gretchen-and-desire.png", "alt": "\uc11c\uc7ac\uc758 \ud559\uc790\uc640 \ubb38\uac00\uc758 \ub0af\uc120 \ubc29\ubb38\uc790\ub97c \uadf8\ub9b0 \ud30c\uc6b0\uc2a4\ud2b8 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ud30c\uc6b0\uc2a4\ud2b8 1\ubd80 \u2014 \ub354 \ub9ce\uc740 \uc0b6\uc744 \uc6d0\ud55c \uc0ac\ub78c\uc740 \ub204\uad6c\ub97c \ub2e4\uce58\uac8c \ud588\uc744\uae4c \uad34\ud14c 1\ubd80\uc758 \uacc4\uc57d\uacfc \uadf8\ub808\ud2b8\ud5e8\uc758 \uc6b4\uba85\uc744 \ud568\uaed8 \uc77d\uae30 \ub354 \ub9ce\uc740 \uc0b6\uc744 \uc6d0\ud55c \ud559\uc790\uc758 \uc5ec\uc815\uacfc \uadf8\ub808\ud2b8\ud5e8\uc758 \ube44\uadf9\uc744 \ud1b5\ud574 \uc695\ub9dd\uc758 \ub300\uac00\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \ub9ce\uc774 \ubc30\uc6e0\ub294\ub370\ub3c4 \uc0b6\uc744 \uc81c\ub300\ub85c \uc54c\uc9c0 \ubabb\ud55c\ub2e4\ub294 \uc0ac\ub78c\uc774 \uc788\ub2e4. \uad34\ud14c\uc758 \u300e\ud30c\uc6b0\uc2a4\ud2b8\u300f\uc5d0\uc11c \ud559\uc790 \ud30c\uc6b0\uc2a4\ud2b8\ub294 \ucd95\uc801\ud55c \uc9c0\uc2dd\ub9cc\uc73c\ub85c \ub9cc\uc871\ud558\uc9c0 \ubabb\ud55c\ub2e4. \uadf8 \uc55e\uc5d0 \ub098\ud0c0\ub09c \uba54\ud53c\uc2a4\ud1a0\ud3a0\ub808\uc2a4\ub294 \uadf8\ub97c \ucc45\uc0c1 \ubc16\uc758 \uacbd\ud5d8\uc73c\ub85c \uc774\ub048\ub2e4. \uc0c8\ub85c\uc6b4 \uc0b6\uc744 \uc5bb\uc73c\ub824\ub294 \uc695\ub9dd\uc740 \uace7 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc6b4\uba85\uacfc \uc5bd\ud78c\ub2e4. \uc774 \uae00\uc740 \uc791\ud488 \uc804\uccb4 \uac00\uc6b4\ub370 1\ubd80\ub97c \uc911\uc2ec\uc73c\ub85c \uc77d\uc73c\uba70 \uc8fc\uc694 \uc0ac\uac74\uacfc \uacb0\ub9d0\uc744 \ud3ec\ud568\ud55c\ub2e4. \uc545\ub9c8\uc5d0\uac8c \uc601\ud63c\uc744 \ud314\uc558\ub2e4\ub294 \uc720\uba85\ud55c \ub9d0\ub9cc \uae30\uc5b5\ud558\uba74 \uc0ac\ub791\uacfc \ucc45\uc784\uc758 \ubb38\uc81c\uac00 \uac00\ub824\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub808\ud2b8\ud5e8\uc758 \uc774\uc57c\uae30\ub97c \ub530\ub77c\uac00\uba74 \uc695\ub9dd\uc758 \ub300\uac00\ub97c \ub204\uac00 \uce58\ub974\ub294\uc9c0\uac00 \ub354 \uc120\uba85\ud574\uc9c4\ub2e4. \ud30c\uc6b0\uc2a4\ud2b8\ub294 \ud559\ubb38\uc744 \ud0d0\uad6c\ud574 \uc654\uc9c0\ub9cc \uc9c0\uc2dd\uacfc \uc0b4\uc544 \uc788\ub294 \uacbd\ud5d8 \uc0ac\uc774\uc5d0 \uac70\ub9ac\ub97c \ub290\ub080\ub2e4. \uc774 \uc2dc\uc791\uc744 \ub2e8\uc21c\ud788 \uacf5\ubd80\uac00 \uc4f8\ubaa8\uc5c6\ub2e4\ub294 \uc8fc\uc7a5\uc73c\ub85c \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc790\uc2e0\uc774 \uc313\uc740 \ub9d0\uacfc \uccb4\uacc4\uac00 \uc138\uacc4\uc758 \uc0dd\uc0dd\ud568\uc744 \ucda9\ubd84\ud788 \ub2f4\ub294\uc9c0 \ubb3b\ub294 \ubd88\ub9cc\uc774\ub2e4. \uadf8\ub294 \ud604\uc7ac\uc758 \ud55c\uacc4\ub97c \ub118\uace0 \uc2f6\uc5b4 \ud55c\ub2e4. \uc774 \ubd88\ub9cc\uc5d0\ub294 \uc0c8\ub85c\uc6b4 \uac83\uc744 \ud5a5\ud55c \ud798\uacfc \ub05d\uc5c6\uc774 \ub9cc\uc871\ud558\uc9c0 \ubabb\ud558\ub294 \uc704\ud5d8\uc774 \ud568\uaed8 \uc788\ub2e4. \ub354 \uc54c\uace0 \ub354 \uc0b4\uace0 \uc2f6\ub2e4\ub294 \uc695\ub9dd\uc740 \uc5b4\ub5a4 \uacbd\uacc4\uae4c\uc9c0 \ud5c8\uc6a9\ub420 \uc218 \uc788\uc744\uae4c. \uc791\ud488\uc740 \ucc98\uc74c\ubd80\ud130 \uba85\ucf8c\ud55c \ub2f5\uc744 \uc8fc\uae30\ubcf4\ub2e4 \uadf8 \uc695\ub9dd\uc774 \uc2e4\uc81c \uad00\uacc4 \uc18d\uc5d0\uc11c \uc5b4\ub5a4 \uacb0\uacfc\ub97c \ub9cc\ub4dc\ub294\uc9c0 \ubcf4\uc5ec \uc900\ub2e4. \uba54\ud53c\uc2a4\ud1a0\ud3a0\ub808\uc2a4\ub294 \ud30c\uc6b0\uc2a4\ud2b8\ub97c \uc720\ud639\ud558\uace0 \uadf8\uac00 \uc6d0\ud558\ub294 \uacbd\ud5d8\uc744 \uc81c\uacf5\ud55c\ub2e4. \ub450 \uc0ac\ub78c\uc758 \uc57d\uc18d\uc5d0\ub294 \ud30c\uc6b0\uc2a4\ud2b8\uac00 \uc5b4\ub5a4 \uc21c\uac04\uc5d0 \uc644\uc804\ud788 \ub9cc\uc871\ud558\uc5ec \uba38\ubb3c\uace0 \uc2f6\uc5b4 \ud558\ub294\uc9c0\uac00 \uc911\uc694\ud55c \uc870\uac74\uc73c\ub85c \ub4e4\uc5b4 \uc788\ub2e4. \ub2e8\uc21c\ud788 \uae08\uc804\uacfc \uc601\ud63c\uc744 \ud55c \ubc88 \ubc14\uafb8\ub294 \uac70\ub798\ubcf4\ub2e4 \ubcf5\uc7a1\ud558\ub2e4. \uba48\ucd94\uc9c0 \uc54a\uc73c\ub824\ub294 \uc778\uac04\uc758 \uc695\ub9dd \uc790\uccb4\uac00 \uc2dc\ud5d8\uc758 \ub300\uc0c1\uc774 \ub41c\ub2e4. \uc791\ud488\uc758 \ucc9c\uc0c1 \uc11c\uace1\ub3c4 \uc774 \uad00\uacc4\ub97c \ub354 \ub113\uc740 \uc9c8\ubb38 \uc548\uc5d0 \ub193\ub294\ub2e4. \ud30c\uc6b0\uc2a4\ud2b8\uc758 \ud589\ub85c\ub294 \uac1c\uc778\uc758 \ubab0\ub798 \ud55c \uacc4\uc57d\ub9cc\uc774 \uc544\ub2c8\ub77c \uc778\uac04\uc758 \ub178\ub825\uacfc \ubc29\ud669\uc744 \ub458\ub7ec\uc2fc \uc774\uc57c\uae30\ub85c \ud3bc\uccd0\uc9c4\ub2e4. \uadf8\ub7ec\ub098 \ud070 \ucca0\ud559\uc801 \ud2c0\uc774 \uc788\ub2e4\uace0 \ud574\uc11c \ub4a4\uc5d0 \uc0dd\uae30\ub294 \uac1c\uc778\uc758 \ud53c\ud574\uac00 \uc0ac\uc18c\ud574\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc80a\uc5b4\uc9c4 \ud30c\uc6b0\uc2a4\ud2b8\ub294 \uadf8\ub808\ud2b8\ud5e8, \uace7 \ub9c8\ub974\uac00\ub808\ud14c\ub97c \ub9cc\ub098 \ub9c8\uc74c\uc744 \ube7c\uc557\uae34\ub2e4. \uadf8\uac00 \uac08\ub9dd\ud558\ub358 \uc0b6\uc740 \ub354 \uc774\uc0c1 \ucd94\uc0c1\uc801\uc778 \uc0dd\uc0dd\ud568\uc774 \uc544\ub2c8\ub2e4. \ud55c \uc0ac\ub78c\uacfc\uc758 \uad00\uacc4\ub85c \uad6c\uccb4\ud654\ub41c\ub2e4. \uba54\ud53c\uc2a4\ud1a0\ud3a0\ub808\uc2a4\uc758 \uac1c\uc785 \uc18d\uc5d0\uc11c \ub450 \uc0ac\ub78c\uc740 \uac00\uae4c\uc6cc\uc9c0\uace0 \uadf8\ub808\ud2b8\ud5e8\uc758 \uc0dd\ud65c\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \ubb38\uc81c\ub294 \uac19\uc740 \uad00\uacc4\uac00 \ub450 \uc0ac\ub78c\uc5d0\uac8c \uac19\uc740 \uc870\uac74\uc774 \uc544\ub2c8\ub77c\ub294 \uc810\uc774\ub2e4. \ud30c\uc6b0\uc2a4\ud2b8\uc5d0\uac8c\ub294 \uc0c8\ub85c\uc6b4 \uacbd\ud5d8\uc73c\ub85c \ud5a5\ud560 \uac00\ub2a5\uc131\uc774 \uc788\uc9c0\ub9cc \uadf8\ub808\ud2b8\ud5e8\uc740 \uac00\uc871\uacfc \uacf5\ub3d9\uccb4\uc758 \uaddc\ubc94 \uc18d\uc5d0 \ub193\uc778\ub2e4. \uc0ac\ub791\uc744 \uc774\uc57c\uae30\ud558\uba74\uc11c\ub3c4 \uc774\ub3d9\ud560 \uc790\uc720\uc640 \uc2e4\ud328\uc758 \ubd80\ub2f4\uc774 \ub204\uad6c\uc5d0\uac8c \ub354 \ud06c\uac8c \ub3cc\uc544\uac00\ub294\uc9c0 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uadf8\ub808\ud2b8\ud5e8\uc774 \ud30c\uc6b0\uc2a4\ud2b8\uc758 \uc2e0\uc559\uc744 \ubb3b\ub294 \uc7a5\uba74\ub3c4 \uc911\uc694\ud558\ub2e4. \uadf8\ub140\uc5d0\uac8c\ub294 \uc0dd\ud65c\uc744 \uc9c0\ud0f1\ud558\ub294 \ubbff\uc74c\uc758 \ubb38\uc81c\uac00 \uadf8\uc5d0\uac8c\ub294 \ub2e4\ub978 \ubc29\uc2dd\uc758 \ub9d0\uacfc \uc0ac\uc720\ub85c \ub3cc\uc544\uc628\ub2e4. \uc11c\ub85c\uc5d0\uac8c \ub04c\ub9ac\ub294 \ub9c8\uc74c\uc774 \uc788\ub2e4\uace0 \uc0b6\uc758 \uae30\uc900\uae4c\uc9c0 \ucda9\ubd84\ud788 \uacf5\uc720\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8 \ucc28\uc774\ub294 \ub4a4\uc758 \uc120\ud0dd\uc5d0\uc11c\ub3c4 \ubb34\uac8c\ub97c \uac16\ub294\ub2e4. \ub450 \uc0ac\ub78c\uc758 \ub9cc\ub0a8\uc744 \ub458\ub7ec\uc2fc \uacfc\uc815\uc5d0\uc11c \uadf8\ub808\ud2b8\ud5e8\uc758 \uc5b4\uba38\ub2c8\uac00 \uc8fd\uace0, \uc624\ube60 \ubc1c\ub80c\ud2f4\ub3c4 \ud30c\uc6b0\uc2a4\ud2b8\uc640\uc758 \uc2f8\uc6c0 \ub05d\uc5d0 \uc8fd\ub294\ub2e4. \uac1c\uc778\uc758 \uc5f4\uc815\ucc98\ub7fc \ubcf4\uc774\ub358 \uad00\uacc4\uac00 \uac00\uc871\uc758 \uc0b6 \uc804\uccb4\ub85c \ubc88\uc9c4\ub2e4. \ud30c\uc6b0\uc2a4\ud2b8\uac00 \uc6d0\ud55c \uac83\uc740 \ud48d\ubd80\ud55c \uacbd\ud5d8\uc774\uc5c8\uc9c0\ub9cc \uadf8 \uacfc\uc815\uc758 \uc190\uc2e4\uc740 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc138\uacc4\uc5d0\uc11c \ucee4\uc9c4\ub2e4. \uc774 \uc0ac\uac74\ub4e4\uc744 \ub2e8\uc21c\ud788 \uc545\ub9c8\uac00 \ub098\uc05c \uc77c\uc744 \ud588\ub2e4\ub294 \uc124\uba85\uc73c\ub85c\ub9cc \ub118\uae30\uae30\ub294 \uc5b4\ub835\ub2e4. \ud30c\uc6b0\uc2a4\ud2b8\ub3c4 \uc695\ub9dd\ud558\uace0 \uc120\ud0dd\ud558\uba70 \ub3c4\uc6c0\uc744 \uc774\uc6a9\ud55c\ub2e4. \ucc45\uc784\uc744 \uc911\uac1c\uc790\uc5d0\uac8c \ubaa8\ub450 \ubc00\uc5b4\ub0bc \uc218 \uc788\ub294\uac00\ub77c\ub294 \uc9c8\ubb38\uc774 \uc0dd\uae34\ub2e4. \ucd08\uc790\uc5f0\uc801 \uc7a5\uce58\uac00 \uc778\uac04\uc758 \ucc45\uc784\uc744 \uc5c6\uc560 \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc791\ud488\uc5d0\ub294 \ubc1c\ud478\ub974\uae30\uc2a4\uc758 \ubc24\ucc98\ub7fc \ud658\uc0c1\uacfc \uc695\ub9dd\uc774 \ub118\uce58\ub294 \uc7a5\uba74\uc774 \ub098\uc628\ub2e4. \ud30c\uc6b0\uc2a4\ud2b8\uac00 \uc0c8\ub85c\uc6b4 \uc790\uadf9 \uc18d\uc5d0 \uc6c0\uc9c1\uc774\ub294 \ub3d9\uc548 \uadf8\ub808\ud2b8\ud5e8\uc758 \uc0c1\ud669\uc740 \uc810\uc810 \ub354 \uc808\ubc15\ud574\uc9c4\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ub450 \uc138\uacc4\uc758 \ub300\ube44\uac00 \uc911\uc694\ud558\ub2e4. \ud55c\ucabd\uc758 \ub05d\uc5c6\ub294 \uacbd\ud5d8\uacfc \ub2e4\ub978 \ucabd\uc758 \uc881\uc544\uc9c0\ub294 \uc0b6\uc774 \uac19\uc740 \uc2dc\uac04\uc5d0 \uc788\ub2e4. \uadf8\ub808\ud2b8\ud5e8\uc740 \uc790\uc2e0\uc758 \uc544\uc774\ub97c \uc8fd\uc778 \uc8c4\ub85c \uac10\uc625\uc5d0 \uac07\ud600 \ucc98\ud615\uc744 \uc55e\ub454\ub2e4. \uc791\ud488\uc740 \uc774 \ube44\uadf9\uc744 \uc544\ub984\ub2e4\uc6b4 \uc0ac\ub791\uc758 \uc18c\ub3d9\uc73c\ub85c \uac00\ubccd\uac8c \ucc98\ub9ac\ud558\uc9c0 \uc54a\ub294\ub2e4. \ucc98\uc74c\uc5d0 \uc791\uac8c \ubcf4\uc774\ub358 \uc57d\uc18d\uacfc \ub9cc\ub0a8\uc758 \uacb0\uacfc\uac00 \ud55c \uc0ac\ub78c\uc758 \uc0dd\uc874\uc744 \ubb34\ub108\ub728\ub9b0\ub2e4. \ub3c5\uc790\ub294 \ud30c\uc6b0\uc2a4\ud2b8\uac00 \uc5bc\ub9c8\ub098 \ub9ce\uc774 \ub290\uaf08\ub294\uc9c0\ubcf4\ub2e4 \ubb34\uc5c7\uc744 \ub0a8\uacbc\ub294\uc9c0 \ubb3b\uac8c \ub41c\ub2e4. \ud30c\uc6b0\uc2a4\ud2b8\ub294 \uac10\uc625\uc73c\ub85c \uac00 \uadf8\ub808\ud2b8\ud5e8\uc744 \ub370\ub9ac\uace0 \ub098\uc624\ub824 \ud55c\ub2e4. \uadf8\ub7ec\ub098 \uadf8\ub140\ub294 \uba54\ud53c\uc2a4\ud1a0\ud3a0\ub808\uc2a4\uac00 \ud568\uaed8 \uc788\ub294 \ud0c8\ucd9c\uc744 \ubc1b\uc544\ub4e4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ub450\ub824\uc6c0\uacfc \ud63c\ub780 \uc18d\uc5d0\uc11c\ub3c4 \uc790\uc2e0\uc758 \uc8c4\uc640 \uc6b4\uba85\uc744 \ub9c8\uc8fc\ud558\ub824 \ud55c\ub2e4. \ubab8\uc744 \ube7c\ub0b4\ub294 \uac00\ub2a5\uc131\uc774 \uace7 \ub9c8\uc74c\uacfc \uc0b6\uc758 \ud574\uacb0\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \uba54\ud53c\uc2a4\ud1a0\ud3a0\ub808\uc2a4\ub294 \uadf8\ub140\uac00 \uc2ec\ud310\ubc1b\uc558\ub2e4\uace0 \ub9d0\ud558\uc9c0\ub9cc \uc704\uc5d0\uc11c\ub294 \uad6c\uc6d0\ub418\uc5c8\ub2e4\ub294 \ubaa9\uc18c\ub9ac\uac00 \ub4e4\ub9b0\ub2e4. \uc138\uc18d\uc758 \ucc98\uc9c0\uc640 \uc885\uad50\uc801 \ud310\ub2e8\uc774 \uac19\uc740 \ubc29\ud5a5\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc774 \uacb0\ub9d0\uc744 \ub2e8\uc21c\ud55c \ud604\uc2e4 \ud0c8\ucd9c\uc758 \uc131\uacf5\uc774\ub098 \uc2e4\ud328\ub85c\ub9cc \uc77d\uc73c\uba74 \uc791\ud488\uc774 \ub098\ub204\uc5b4 \ub193\uc740 \ub450 \ucc28\uc6d0\uc744 \ub193\uce58\uac8c \ub41c\ub2e4. \uadf8\ub808\ud2b8\ud5e8\uc758 \ube44\uadf9\uc774 \ub05d\ub0ac\ub2e4\uace0 \ud30c\uc6b0\uc2a4\ud2b8\uc758 \uc804\uccb4 \uc5ec\uc815\ub3c4 \uc644\uacb0\ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. 2\ubd80\ub294 \ub2e4\ub978 \ubc94\uc704\uc758 \uc0ac\uac74\uacfc \ubb38\uc81c\ub97c \ub2e4\ub8ec\ub2e4. \ub530\ub77c\uc11c 1\ubd80\uc758 \ub9c8\uc9c0\ub9c9\uc744 \u300e\ud30c\uc6b0\uc2a4\ud2b8\u300f \uc804\uccb4\uc5d0 \ub300\ud55c \ucd5c\uc885 \ud310\uacb0\uc774\ub77c\uace0 \ub2e8\uc815\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\ub2e4. \uc9c0\uae08 \uc77d\uc740 \ubd80\ubd84\uc5d0\uc11c \ubb34\uc5c7\uc774 \ub05d\ub098\uace0 \ubb34\uc5c7\uc774 \ub0a8\ub294\uc9c0 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. 1\ubd80\uac00 \uac15\ud558\uac8c \ub0a8\uae30\ub294 \uac83\uc740 \uac08\ub9dd\uc758 \ud06c\uae30\uc640 \ucc45\uc784\uc758 \ubb34\uac8c\ub2e4. \ub354 \ub9ce\uc740 \uc138\uacc4\ub97c \uc5bb\uace0 \uc2f6\ub2e4\ub294 \ub9d0\uc774 \ud0c0\uc778\uc758 \uc190\uc2e4\uc744 \uc815\ub2f9\ud654\ud560 \uc218 \uc788\ub294\uac00. \ud30c\uc6b0\uc2a4\ud2b8\ub97c \uc9c0\uc2dd\uacfc \uc695\ub9dd\uc758 \uc0c1\uc9d5\uc73c\ub85c \uae30\uc5b5\ud558\ub354\ub77c\ub3c4 \uadf8\ub808\ud2b8\ud5e8\uc758 \uc774\ub984\uc744 \ud568\uaed8 \ub5a0\uc62c\ub824\uc57c \ud558\ub294 \uc774\uc720\uac00 \uc5ec\uae30\uc5d0 \uc788\ub2e4."}, {"id": "fidelio-leonore-prison-and-chorus", "title": "\ud53c\ub378\ub9ac\uc624 \u2014 \ubca0\ud1a0\ubca4\uc758 \uc624\ud398\ub77c\uc5d0\uc11c \ubb38\uc774 \uc5f4\ub9ac\ub294 \uc21c\uac04", "summary": "\ubcc0\uc7a5\ud55c \uc544\ub0b4\uc758 \uad6c\ucd9c\uacfc \uc8c4\uc218\ub4e4\uc758 \ubaa9\uc18c\ub9ac, \ub9c8\uc9c0\ub9c9 \ub098\ud314\uc774 \ubc14\uafb8\ub294 \uc0ac\uac74\uc744 \ud568\uaed8 \ub4e3\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc74c\uc545", "categories": ["arts"], "url": "stories/fidelio-leonore-prison-and-chorus/index.html", "image": "../media/fidelio-leonore-prison-and-chorus.png", "alt": "\ub0a8\uc131 \uc870\uc218\ub85c \ubcc0\uc7a5\ud55c \ub808\uc624\ub178\ub808\uc640 \uac10\uc625\uc758 \uc5b4\ub460\uc744 \uc5f0\uc0c1\ud558\ub294 \ud53c\ub378\ub9ac\uc624 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ud53c\ub378\ub9ac\uc624 \u2014 \ubca0\ud1a0\ubca4\uc758 \uc624\ud398\ub77c\uc5d0\uc11c \ubb38\uc774 \uc5f4\ub9ac\ub294 \uc21c\uac04 \ub808\uc624\ub178\ub808\uc758 \ubcc0\uc7a5\uacfc \uad6c\ucd9c, \uc911\ucc3d\u00b7\ud569\ucc3d\u00b7\ub098\ud314\ub85c \ub4e3\ub294 \uc790\uc720 \ubcc0\uc7a5\ud55c \uc544\ub0b4\uc758 \uad6c\ucd9c\uacfc \uc8c4\uc218\ub4e4\uc758 \ubaa9\uc18c\ub9ac, \ub9c8\uc9c0\ub9c9 \ub098\ud314\uc774 \ubc14\uafb8\ub294 \uc0ac\uac74\uc744 \ud568\uaed8 \ub4e3\uc2b5\ub2c8\ub2e4. \uc74c\uc545 \ubb38\ud654\uc640 \uc608\uc220 \ubca0\ud1a0\ubca4\uc744 \uad50\ud5a5\uace1\uacfc \ud53c\uc544\ub178\uace1\uc73c\ub85c\ub9cc \uae30\uc5b5\ud558\uba74 \u300e\ud53c\ub378\ub9ac\uc624\u300f\ub294 \ub2e4\ub978 \uc5bc\uad74\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uac10\uc625\uc5d0 \uac07\ud78c \ub0a8\ud3b8\uc744 \uad6c\ud558\ub824\ub294 \uc5ec\uc131\uc774 \ubcc0\uc7a5\ud574 \uadf8\uacf3\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \uc774\uc57c\uae30\ub2e4. \uc0ac\ub791\uacfc \uc815\uce58\uc801 \uc5b5\uc555, \uac1c\uc778\uc758 \ubaa9\uc18c\ub9ac\uc640 \ud569\ucc3d\uc774 \ub9cc\ub09c\ub2e4. \uc544\ub798\uc5d0\ub294 \uc904\uac70\ub9ac\uc640 \ub9c8\uc9c0\ub9c9 \uad6c\ucd9c \uc7a5\uba74\uc774 \ud3ec\ud568\ub41c\ub2e4. \ub808\uc624\ub178\ub808\ub294 \ub0a8\ud3b8 \ud50c\ub85c\ub808\uc2a4\ud0c4\uc758 \ud589\ubc29\uc744 \ucc3e\ub294\ub2e4. \uadf8\ub294 \uad8c\ub825\uc790 \ud53c\ucc28\ub85c\uc5d0\uac8c \ubbf8\uc6c0\uc744 \ubc1b\uc544 \uac10\uc625\uc5d0 \uac07\ud600 \uc788\ub2e4. \uc544\ub0b4\ub294 \ub0a8\uc131 \uc870\uc218 \ud53c\ub378\ub9ac\uc624\ub85c \ubcc0\uc7a5\ud574 \uac04\uc218 \ub85c\ucf54\uc758 \uacc1\uc5d0\uc11c \uc77c\ud55c\ub2e4. \uc774\ub984\uacfc \uc637\uc744 \ubc14\uafb8\uc5b4\uc57c \uc811\uadfc\ud560 \uc218 \uc788\ub294 \uacf5\uac04\uc5d0 \ub4e4\uc5b4\uac04 \uac83\uc774\ub2e4. \ubcc0\uc7a5\uc740 \ub3c4\uc6c0\uc744 \uc5bb\ub294 \ubc29\ubc95\uc774\uba74\uc11c \ub2e4\ub978 \uc624\ud574\ub3c4 \ub9cc\ub4e0\ub2e4. \ub85c\ucf54\uc758 \ub538 \ub9c8\ub974\uccbc\ub9ac\ub124\ub294 \ud53c\ub378\ub9ac\uc624\ub97c \uc0ac\ub791\ud558\uac8c \ub41c\ub2e4. \uacf5\uc5f0\uc758 \ucd08\ubc18\uc5d0\ub294 \uc774\ub7f0 \uad00\uacc4 \ub54c\ubb38\uc5d0 \uac00\ubcbc\uc6b4 \ud76c\uadf9\ucc98\ub7fc \ub290\uaef4\uc9c0\ub294 \uc21c\uac04\ub3c4 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \ub4a4\uc5d0\ub294 \uc544\uc9c1 \ub4dc\ub7ec\ub098\uc9c0 \uc54a\uc740 \uac10\uc625\uc758 \uace0\ud1b5\uc774 \ub193\uc5ec \uc788\ub2e4. \ucd08\ubc18\uc758 \uc778\ubb3c\ub4e4\uc740 \uac19\uc740 \uc790\ub9ac\uc5d0 \uc788\uc73c\uba74\uc11c \uc11c\ub85c \ub2e4\ub978 \uc0dd\uac01\uc744 \ud488\ub294\ub2e4. \ub9c8\ub974\uccbc\ub9ac\ub124\ub294 \uc0ac\ub791\uc744 \uae30\ub300\ud558\uace0 \ub808\uc624\ub178\ub808\ub294 \uc790\uc2e0\uc758 \uc784\ubb34\uc640 \uc815\uccb4\ub97c \uac71\uc815\ud55c\ub2e4. \uc911\ucc3d\uc740 \uc5ec\ub7ec \ub9c8\uc74c\uc774 \ub3d9\uc2dc\uc5d0 \uc874\uc7ac\ud55c\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc74c\uc545\uc73c\ub85c \ubcf4\uc5ec \uc900\ub2e4. \ub300\uc0ac\ub9cc\uc73c\ub85c \ud55c \uc0ac\ub78c\uc529 \uc124\uba85\ud588\ub2e4\uba74 \uc21c\uc11c\ub300\ub85c \ub4e4\uc5c8\uc744 \ub0b4\uc6a9\uc744 \uc74c\uc545\uc740 \uacb9\uccd0 \ub193\ub294\ub2e4. \uad00\uac1d\uc740 \uac89\uc73c\ub85c \uc870\ud654\ub86d\uac8c \ub4e4\ub9ac\ub294 \uc18c\ub9ac \uc548\uc5d0\uc11c \uc11c\ub85c \ub9de\uc9c0 \uc54a\ub294 \uae30\ub300\ub97c \uc54c \uc218 \uc788\ub2e4. \uc624\ud398\ub77c\ub97c \ub4e3\ub294 \uc7ac\ubbf8\ub294 \ub204\uac00 \ub178\ub798\ub97c \uc798\ud558\ub294\uc9c0\ubfd0 \uc544\ub2c8\ub77c \ub3d9\uc2dc\uc5d0 \ubb34\uc5c7\uc744 \uc0dd\uac01\ud558\ub294\uc9c0\uc5d0\ub3c4 \uc788\ub2e4. \uc774\ub7f0 \uc911\ucc3d\uc5d0\uc11c\ub294 \uc18c\ub9ac\uac00 \ucc28\ub840\ub85c \ub4e4\uc5b4\uc624\uba70 \uacb9\uce58\ub294 \ubc29\uc2dd\uc744 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ud568\uaed8 \ubd80\ub978\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uac19\uc740 \ub73b\uc5d0 \ub3d9\uc758\ud588\ub2e4\ub294 \uc758\ubbf8\ub294 \uc544\ub2c8\ub2e4. \uc74c\uc545\uc740 \uc11c\ub85c \ub2e4\ub978 \ub0b4\uba74\uc744 \ud55c \uacf5\uac04\uc5d0 \ub193\uace0 \uad00\uac1d\ub9cc \uadf8 \ucc28\uc774\ub97c \ub113\uac8c \ub4e3\ub3c4\ub85d \ud55c\ub2e4. \uac89\uc73c\ub85c \uc54c \uc218 \uc5c6\ub294 \uad00\uacc4\uac00 \ubaa9\uc18c\ub9ac\uc758 \ubc30\uc5f4\uc744 \ud1b5\ud574 \ub098\ud0c0\ub09c\ub2e4. \ucd08\ubc18\uc758 \uacb9\uce58\ub294 \uae30\ub300\uc640 \ub9c8\uc9c0\ub9c9\uc758 \ud568\uaed8\ud558\ub294 \uae30\uc068\uc744 \ube44\uad50\ud558\uba74 \ud569\ucc3d\uacfc \uc911\ucc3d\uc758 \uae30\ub2a5\ub3c4 \ub2ec\ub9ac \ub4e4\ub9b0\ub2e4. \ubaa8\ub450\uac00 \ud55c \ubc88\uc5d0 \uc18c\ub9ac\ub97c \ub0b8\ub2e4\ub294 \uacf5\ud1b5\uc810\ubcf4\ub2e4 \ub204\uad6c\uc758 \ub9c8\uc74c\uc774 \uc5b4\ub5a4 \uc0ac\uac74 \ub4a4\uc5d0 \ud569\uccd0\uc9c0\ub294\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \ucc98\uc74c\uc758 \uc870\ud654\ub294 \uc624\ud574\ub97c \ud3ec\ud568\ud558\uace0 \ub9c8\uc9c0\ub9c9\uc758 \uc870\ud654\ub294 \uac10\ucdb0\uc9c4 \uc0ac\uc2e4\uc774 \ub4dc\ub7ec\ub09c \ub4a4\uc5d0 \ub098\uc628\ub2e4. \uc774 \ubcc0\ud654 \ub54c\ubb38\uc5d0 \uacb0\ub9d0\uc758 \ud070 \ud569\ucc3d\uc740 \ub2e8\uc21c\ud788 \uc18c\ub9ac\ub97c \ud06c\uac8c \ub05d\ub0b4\ub294 \uc7a5\uc2dd\uc5d0 \uadf8\uce58\uc9c0 \uc54a\ub294\ub2e4. \uc74c\uc545\uc740 \uac10\uc625\uc758 \ubb38\uc774 \uc5f4\ub838\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uacf5\ub3d9 \uacbd\ud5d8\uc73c\ub85c \ubc14\uafbc\ub2e4. \ub808\uc624\ub178\ub808\uc758 \ubd80\ud0c1\uc73c\ub85c \uc8c4\uc218\ub4e4\uc774 \uc7a0\uc2dc \ubc14\uae65\uc5d0 \ub098\uc624\ub294 \uc7a5\uba74\uc774 \uc788\ub2e4. \ud569\ucc3d\uc740 \uac1c\uc778 \ud55c \uba85\uc758 \uc0ac\uc5f0\uc744 \ub118\uc5b4 \uac07\ud600 \uc788\ub358 \uc0ac\ub78c\ub4e4\uc758 \uacbd\ud5d8\uc744 \ub4dc\ub7ec\ub0b8\ub2e4. \ud587\ube5b\uacfc \uacf5\uae30\uac00 \ud3c9\ubc94\ud55c \ubc30\uacbd\uc774 \uc544\ub2c8\ub77c \uac04\uc808\ud788 \ubc14\ub77c\ub294 \uac83\uc774 \ub41c\ub2e4. \uc774 \uc7a5\uba74\uc5d0\uc11c \ub290\ub07c\ub294 \ud574\ubc29\uc740 \uc544\uc9c1 \uc644\uc804\ud558\uc9c0 \uc54a\ub2e4. \uc774\ub4e4\uc740 \ub2e4\uc2dc \uc5b5\uc555\uc758 \uacf5\uac04\uc73c\ub85c \ub3cc\uc544\uac00\uc57c \ud55c\ub2e4. \uc7a0\uae50 \uc5f4\ub9b0 \ubb38\uacfc \ub05d\uae4c\uc9c0 \uc5f4\ub9b0 \ubb38\uc740 \ub2e4\ub974\ub2e4. \uad00\uac1d\uc740 \uc544\ub984\ub2e4\uc6b4 \ud569\ucc3d\uc744 \ub4e3\ub294 \ub3d9\uc548 \uadf8\uac83\uc744 \ub9c8\uc74c\ub300\ub85c \ub204\ub9b4 \uc218 \uc5c6\ub294 \uc0b6\uc758 \uc870\uac74\ub3c4 \ud568\uaed8 \uc54c\uac8c \ub41c\ub2e4. \uc0c1\uae09\uc790\uc778 \uc7a5\uad00\uc774 \uc628\ub2e4\ub294 \uc18c\uc2dd\uc740 \ud53c\ucc28\ub85c\uc5d0\uac8c \uc704\ud611\uc774\ub2e4. \uac10\uc625 \uc548\uc5d0\uc11c \uc790\uc2e0\uc774 \ud55c \uc77c\uc774 \ub4dc\ub7ec\ub0a0 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uadf8\ub294 \ud50c\ub85c\ub808\uc2a4\ud0c4\uc744 \uc5c6\uc560\ub824 \ud558\uace0 \ub85c\ucf54\uc5d0\uac8c \uc900\ube44\ub97c \uc2dc\ud0a8\ub2e4. \uac10\uc625\uc758 \ube44\ubc00\uacfc \uc678\ubd80\uc758 \uac10\ub3c5\uc774 \uc774\uc57c\uae30\uc758 \uc2dc\uac04\uc744 \uc7ac\ucd09\ud55c\ub2e4. \ub808\uc624\ub178\ub808\ub294 \ub85c\ucf54\uc640 \ud568\uaed8 \uc9c0\ud558\ub85c \ub4e4\uc5b4\uac04\ub2e4. \uc5b4\ub450\uc6b4 \uacf5\uac04\uc5d0\uc11c \ub0a8\ud3b8\uc744 \uc54c\uc544\ubcfc \uc218 \uc788\uc744\uc9c0, \uc5b4\ub5a4 \ud589\ub3d9\uc744 \ud574\uc57c \ud560\uc9c0 \uad00\uac1d\ub3c4 \ud568\uaed8 \uae30\ub2e4\ub9b0\ub2e4. \uc758\uc9c0\uac00 \uac15\ud558\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc870\uac74\uc744 \ud1b5\uc81c\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub3c4\uc6c0\uacfc \uae30\ud68c\uac00 \ud544\uc694\ud55c \uae34\uc7a5\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ud50c\ub85c\ub808\uc2a4\ud0c4\uc758 \ub178\ub798\ub294 \uadf8\uac00 \ub2e8\uc21c\ud788 \uad6c\ucd9c\ub420 \ub300\uc0c1\ub9cc\uc774 \uc544\ub2d8\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc5b4\ub460\uacfc \uace0\ub9bd \uc18d\uc5d0\uc11c \uae30\uc5b5\uacfc \ud76c\ub9dd\uc744 \ubd99\ub4dc\ub294 \ub9c8\uc74c\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \ubaa9\uc18c\ub9ac\ub294 \ub208\uc5d0 \ubcf4\uc774\ub294 \uac10\uc625\uc758 \uc881\uc740 \uacf5\uac04\uc744 \ub118\uc5b4 \ub2e4\ub978 \uc0b6\uc744 \uc0c1\uc0c1\ud558\uac8c \ud55c\ub2e4. \ub808\uc624\ub178\ub808\ub294 \uadf8\ub97c \uad6c\ud558\ub824 \ud558\uc9c0\ub9cc \uc815\uccb4\ub97c \ub4dc\ub7ec\ub0b4\ub294 \uc21c\uac04\uc5d0\ub294 \uc790\uc2e0\ub3c4 \uc704\ud5d8\uc744 \uac10\uc218\ud574\uc57c \ud55c\ub2e4. \uc74c\uc545\uc740 \ucc98\uc74c\uc758 \uac00\ubcbc\uc6b4 \uc624\ud574\uc5d0\uc11c \uc0dd\uc0ac\uc758 \uacb0\uc815\uc73c\ub85c \uc774\ub3d9\ud55c\ub2e4. \ud55c \uc791\ud488 \uc548\uc5d0\uc11c \ubd84\uc704\uae30\uac00 \ud06c\uac8c \ub2ec\ub77c\uc9c0\ub294 \uac83\uc740 \uc774\uc57c\uae30\uc758 \ubc14\uae65\uacfc \uc548\ucabd\uc774 \ucc28\ub840\ub85c \uc5f4\ub9ac\uae30 \ub54c\ubb38\uc774\ub2e4. \ud53c\ucc28\ub85c\uac00 \ud589\ub3d9\ud558\ub824 \ud560 \ub54c \ub808\uc624\ub178\ub808\ub294 \uc790\uc2e0\uc774 \uc544\ub0b4\uc784\uc744 \ubc1d\ud788\uba70 \ub9c9\uc544\uc120\ub2e4. \uc774\uc5b4 \ubc14\uae65\uc758 \ub098\ud314 \uc18c\ub9ac\uac00 \uc7a5\uad00\uc758 \ub3c4\ucc29\uc744 \uc54c\ub9b0\ub2e4. \uadf8 \uc18c\ub9ac\ub294 \ub2e8\uc21c\ud55c \ubc30\uacbd \ud6a8\uacfc\uac00 \uc544\ub2c8\ub77c \uad8c\ub825 \uad00\uacc4\ub97c \ubc14\uafb8\ub294 \uc0ac\uac74\uc774\ub2e4. \uac10\uc625\uc758 \ube44\ubc00\uc744 \uc9c0\ucf1c \uc8fc\ub358 \uc2dc\uac04\uc774 \ub05d\ub09c\ub2e4. \ub9c8\uc9c0\ub9c9\uc5d0 \uc8c4\uc218\ub4e4\uc740 \ud480\ub824\ub098\uace0 \ud53c\ucc28\ub85c\uc758 \ud589\uc704\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \ub808\uc624\ub178\ub808\uac00 \ub0a8\ud3b8\uc758 \uc0ac\uc2ac\uc744 \ud478\ub294 \uc7a5\uba74\uc740 \uc774\uc57c\uae30\uc758 \ubaa9\ud45c\ub97c \uad6c\uccb4\uc801\uc778 \ubab8\uc9d3\uc73c\ub85c \ubcf4\uc5ec \uc900\ub2e4. \ud569\ucc3d\uc740 \uc0ac\uc801\uc778 \uc7ac\ud68c\uc758 \uae30\uc068\uc744 \ub354 \ub113\uc740 \uc790\uc720\uc640 \uad6c\uc6d0\uc758 \uae30\uc068\uc73c\ub85c \ud655\uc7a5\ud55c\ub2e4. \u300e\ud53c\ub378\ub9ac\uc624\u300f\ub294 1805\ub144\uc758 \uccab \uacf5\uc5f0 \uc774\ud6c4 \uc218\uc815\uc744 \uac70\ucce4\uace0 1814\ub144\uc758 \ud310\ubcf8\uc73c\ub85c \uc774\uc5b4\uc84c\ub2e4. \uc5ec\ub7ec \uc11c\uace1\uc774 \ub0a8\uc740 \uc0ac\uc2e4\ub3c4 \uc624\ub79c \uac1c\uc791\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc775\uc219\ud55c \uc81c\ubaa9\uc758 \uc791\ud488\uc774 \ucc98\uc74c\ubd80\ud130 \uc9c0\uae08\uc758 \ubaa8\uc2b5\uc73c\ub85c \ud55c \ubc88\uc5d0 \uc644\uc131\ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. \ub4e4\uc744 \ub54c\uc5d0\ub294 \ucd08\ubc18 \uc911\ucc3d\uacfc \uc8c4\uc218\ub4e4\uc758 \ud569\ucc3d, \uc9c0\ud558\uc758 \ub3c5\ucc3d\uacfc \ub9c8\uc9c0\ub9c9 \ub098\ud314\uc744 \ucc28\ub840\ub85c \ube44\uad50\ud574 \ubcf4\uc790. \uc74c\uc545\uc774 \uc778\ubb3c\uc758 \ub9c8\uc74c\uc744 \ub4dc\ub7ec\ub0b4\ub294 \ubc29\uc2dd\uacfc \uc0ac\uac74\uc744 \ubc14\uafb8\ub294 \ubc29\uc2dd\uc774 \ub2e4\ub974\ub2e4. \ud63c\uc790 \ub178\ub798\ud558\ub358 \uc0ac\ub78c\uc758 \uacbd\ud5d8\uc774 \ub9c8\uc9c0\ub9c9\uc5d0 \ub2e4\ub978 \ubaa9\uc18c\ub9ac\uc640 \uc5f0\uacb0\ub41c\ub2e4\ub294 \ud750\ub984\uc744 \ub530\ub77c\uac00 \ubcfc \uc218 \uc788\ub2e4. \ub3c5\ucc3d\uacfc \ud569\ucc3d\uc758 \ub300\ube44\uac00 \uc904\uac70\ub9ac\uc758 \ubcc0\ud654\ub97c \ud568\uaed8 \ub9cc\ub4e0\ub2e4. \ubca0\ud1a0\ubca4\uc758 \uc624\ud398\ub77c\ub294 \ubb38\uc774 \uc5f4\ub9ac\ub294 \uc77c\uc744 \uac74\ucd95\uc758 \ubcc0\ud654\uc5d0\uc11c \uc0ac\ub78c\uacfc \uacf5\ub3d9\uccb4\uc758 \ubcc0\ud654\ub85c \ub113\ud600 \ub4e4\ub824\uc900\ub2e4."}, {"id": "fionn-salmon-wisdom-and-teacher", "title": "\ud53c\uc628 \u2014 \uc9c0\ud61c\uc758 \uc5f0\uc5b4\ub294 \ub204\uad6c\uc758 \ubaab\uc774\uc5c8\uc744\uae4c", "summary": "\ud53c\uc628\uacfc \ud53c\ub124\uac00\uc2a4\uc758 \ubc30\uc6c0, \uc5f0\uc5b4\uc758 \ub9db\uacfc \uc2a4\uc2b9\uc758 \uc120\ud0dd\uc744 \uc81c\uc784\uc2a4 \uc2a4\ud2f0\ube10\uc2a4\uc758 \uc7ac\ud654\ubcf8\uc5d0 \ub530\ub77c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc2e0\ud654\uc640 \ubbfc\uc18d", "categories": ["arts"], "url": "stories/fionn-salmon-wisdom-and-teacher/index.html", "image": "../media/fionn-salmon-wisdom-and-teacher.png", "alt": "\uac15\ubcc0 \uc9d1 \uc55e\uc5d0\uc11c \uc5f0\uc5b4 \ubc14\uad6c\ub2c8\ub97c \ub450\uace0 \ub300\ud654\ud558\ub294 \ud53c\uc628\uacfc \ud53c\ub124\uac00\uc2a4\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ud53c\uc628 \u2014 \uc9c0\ud61c\uc758 \uc5f0\uc5b4\ub294 \ub204\uad6c\uc758 \ubaab\uc774\uc5c8\uc744\uae4c \ubd88\uc5d0 \ub374 \uc5c4\uc9c0\uc190\uac00\ub77d\uacfc \uc2dc\uc778\uc774 \uac10\ucd94\uc5b4 \ub454 \uc608\uc5b8 \ud53c\uc628\uacfc \ud53c\ub124\uac00\uc2a4\uc758 \ubc30\uc6c0, \uc5f0\uc5b4\uc758 \ub9db\uacfc \uc2a4\uc2b9\uc758 \uc120\ud0dd\uc744 \uc81c\uc784\uc2a4 \uc2a4\ud2f0\ube10\uc2a4\uc758 \uc7ac\ud654\ubcf8\uc5d0 \ub530\ub77c \uc77d\uc2b5\ub2c8\ub2e4. \uc2e0\ud654\uc640 \ubbfc\uc18d \ubb38\ud654\uc640 \uc608\uc220 \uc5f0\uc5b4\ub97c \uad7d\ub2e4\uac00 \uaecd\uc9c8\uc774 \ubd80\ud478\ub294 \uac83\uc744 \ubcf4\uc558\ub2e4. \uc190\uac00\ub77d\uc73c\ub85c \ub20c\ub800\ub354\ub2c8 \ub728\uac70\uc6cc\uc11c \ubb34\uc2ec\ucf54 \uc785\uc5d0 \ub123\uc5c8\ub2e4. \ub300\ub2e8\ud55c \ubaa8\ud5d8\uc774\ub77c\uace0 \ubd80\ub974\uae30 \uc5b4\ub824\uc6b4 \uc774 \uc791\uc740 \ub3d9\uc791\uc774 \uc9c0\ud61c\uc758 \uc8fc\uc778\uc744 \ubc14\uafb8\ub294 \uc0ac\uac74\uc774 \ub41c\ub2e4. \uc544\uc77c\ub79c\ub4dc\uc758 \ud53c\uc628\uc5d0\uac8c\ub294 \uc9c0\ud61c\uc758 \uc5f0\uc5b4 \uc774\uc57c\uae30\uac00 \ub530\ub77c\uc628\ub2e4. \uc774 \uae00\uc740 \uc81c\uc784\uc2a4 \uc2a4\ud2f0\ube10\uc2a4\uc758 \u300e\uc544\uc77c\ub79c\ub4dc \uc61b\uc774\uc57c\uae30\u300f \uac00\uc6b4\ub370 \u300c\ud53c\uc628\uc758 \uc18c\ub144 \uc2dc\uc808\u300d\uc744 \uc77d\ub294\ub2e4. \ud2b9\ud788 \uc2a4\uc2b9 \ud53c\ub124\uac00\uc2a4\uc758 \ub9c8\uc74c\uacfc \ub9d0\uc774 \uc790\uc138\ud558\uac8c \uadf8\ub824\uc9c0\ub294 \ud310\ubcf8\uc774\ub2e4. \ud53c\uc628\uc740 \uc5b4\ub9b4 \ub54c\ubd80\ud130 \ubab8\uc744 \uc6c0\uc9c1\uc774\uace0 \uc0b4\uc544\uac08 \uae30\uc220\uc744 \ubc30\uc6e0\ub2e4. \uc774\ud6c4\uc5d0\ub294 \uc2dc\uc778 \ud53c\ub124\uac00\uc2a4\ub97c \ub9cc\ub098 \uc0c8\ub85c\uc6b4 \uacf5\ubd80\ub97c \ud55c\ub2e4. \uc7ac\ube60\ub978 \ub2e4\ub9ac\uc640 \ud314\ub9cc\ud07c \uc9c8\ubb38\ud558\uace0 \uc0dd\uac01\ud558\ub294 \ud798\ub3c4 \uc911\uc694\ud574\uc9c0\ub294 \uc2dc\uae30\ub2e4. \uadf8\ub294 \uc2a4\uc2b9\uc758 \uc9d1\uc548\uc77c\uc744 \ub9e1\uace0 \ubb3c\uc744 \uae38\uc5b4 \uc624\uba70 \uc774\uc57c\uae30\ub97c \ub4e3\ub294\ub2e4. \ubc30\uc6c0\uc740 \ucc45\uc0c1 \uc55e\uc758 \ud55c \uc2dc\uac04\uc73c\ub85c\ub9cc \uad6c\ubd84\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc2dd\uc0ac\ub97c \uc900\ube44\ud558\uace0 \uc26c\ub294 \ub3d9\uc548\uc5d0\ub3c4 \ub4e4\uc740 \ub9d0\uc744 \ub5a0\uc62c\ub9b0\ub2e4. \uc9c0\ud61c\uc758 \uc5f0\uc5b4\uac00 \ub098\ud0c0\ub098\uae30 \uc804\ubd80\ud130 \uc18c\ub144\uc758 \ud558\ub8e8\ub294 \ubc30\uc6c0\uc73c\ub85c \ucc28 \uc788\ub2e4. \ud53c\ub124\uac00\uc2a4\ub294 \ubcf4\uc778\uac15\uc5d0\uc11c \ud2b9\ubcc4\ud55c \uc5f0\uc5b4\ub97c \uc7a1\uac8c \ub418\ub9ac\ub77c\ub294 \uc608\uc5b8\uc744 \ub9d0\ud55c\ub2e4. \uadf8 \uc5f0\uc5b4\ub97c \uba39\uc73c\uba74 \ud070 \uc9c0\uc2dd\uc744 \uc5bb\uc744 \uc218 \uc788\ub2e4. \ud53c\uc628\uc740 \ubb3c\uace0\uae30\uc758 \uc0b4\uc5d0 \uc5b4\ub5bb\uac8c \uc9c0\ud61c\uac00 \ub4e4\uc5b4\uac00\ub294\uc9c0 \uad81\uae08\ud574\ud55c\ub2e4. \uc2a4\uc2b9\uc740 \uc2e0\uc131\ud55c \uac1c\uc554\ub098\ubb34\uc758 \uc5f4\ub9e4\uac00 \ubb3c\uc5d0 \ub5a8\uc5b4\uc9c0\uace0 \uc5f0\uc5b4\uac00 \uadf8\uac83\uc744 \uba39\ub294\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc18c\ub144\uc740 \uadf8\ub7ec\uba74 \uc5f4\ub9e4\ub97c \ubc14\ub85c \ucc3e\uc544 \uba39\uc73c\uba74 \uc5b4\ub5a0\ub0d0\uace0 \ubb3b\ub294\ub2e4. \uba4b\uc9c4 \uc774\uc57c\uae30\ub97c \ub4e4\uc740 \ub4a4\uc5d0\ub3c4 \uc26c\uc6b4 \ub2e4\ub978 \ubc29\ubc95\uc744 \uc0dd\uac01\ud574 \ubcf4\ub294 \uc544\uc774\uc758 \uc9c8\ubb38\uc774 \uc7ac\ubbf8\uc788\ub2e4. \ud53c\ub124\uac00\uc2a4\ub294 \uc9c8\ubb38\uc744 \ub358\uc9c0\ub294 \uac83\uc73c\ub85c\ub9cc \ub9cc\uc871\ud558\uac8c \ub450\uc9c0 \uc54a\ub294\ub2e4. \uc18c\ub144\uc774 \uc790\uae30 \uc0dd\uac01\uc73c\ub85c \ub2f5\ud574 \ubcf4\uac8c \ud558\uace0 \uc5b4\ub290 \ubd80\ubd84\uc774 \uc5b4\uae0b\ub0ac\ub294\uc9c0 \uc9da\uc5b4 \uc900\ub2e4. \ud53c\uc628\uc740 \ubb3b\ub294 \ubc95\uacfc \uc124\uba85\ud558\ub294 \ubc95\uc744 \ud568\uaed8 \uc775\ud78c\ub2e4. \uc774 \uc7a5\uba74\uc740 \ub098\uc911\uc5d0 \uc5f0\uc5b4\ub97c \uba39\ub294 \uc0ac\uac74\uacfc \ub098\ub780\ud788 \ub193\uace0 \ubcfc \ub9cc\ud558\ub2e4. \ubaa8\ub4e0 \uc9c0\ud61c\uac00 \uc2e0\ube44\ud55c \ud55c \uc785\uc73c\ub85c\ub9cc \ub4e4\uc5b4\uc654\ub2e4\uba74 \uc55e\uc758 \uae34 \uacf5\ubd80\ub294 \ud544\uc694 \uc5c6\uc5c8\uc744 \uac83\uc774\ub2e4. \uc2a4\ud2f0\ube10\uc2a4\uc758 \uc7ac\ud654\ub294 \ub180\ub77c\uc6b4 \uc0ac\uac74\uc744 \uae30\ub2e4\ub9ac\ub294 \uc2dc\uac04\uc5d0\ub3c4 \ubc30\uc6c0\uc774 \uc788\uc5c8\ub2e4\uace0 \uadf8\ub9b0\ub2e4. \uc5b4\ub290 \ub0a0 \uc2a4\uc2b9\uc774 \ubb3c\uace0\uae30 \ub4e0 \ubc14\uad6c\ub2c8\ub97c \uac00\uc9c0\uace0 \ub3cc\uc544\uc628\ub2e4. \ud53c\uc628\uc740 \ud2b9\ubcc4\ud55c \uc5f0\uc5b4\ub97c \uc7a1\uc558\ub2e4\ub294 \ub9d0\uc5d0 \uae30\ubed0\ud55c\ub2e4. \uadf8\ub7f0\ub370 \uc2a4\uc2b9\uc758 \ud45c\uc815\uc5d0\ub294 \uc2b9\ub9ac\uac10\uacfc \ud568\uaed8 \uc2ac\ud514 \uac19\uc740 \uac83\ub3c4 \uc788\ub2e4. \uc18c\ub144\uc740 \uadf8 \ub9c8\uc74c\uc758 \uae4c\ub2ed\uc744 \uc544\uc9c1 \ubaa8\ub978\ub2e4. \ud53c\ub124\uac00\uc2a4\ub294 \uc790\uae30\uac00 \ub3cc\uc544\uc62c \ub54c\uae4c\uc9c0 \uc5f0\uc5b4\ub97c \uad6c\uc6cc \ub450\ub77c\uace0 \ub9e1\uae34\ub2e4. \uba39\uc9c0 \uc54a\uaca0\ub290\ub0d0\uace0 \ubb3b\uace0 \uc18c\ub144\uc740 \uc57d\uc18d\ud55c\ub2e4. \ub3c5\uc790\ub294 \ub9db\uc788\ub294 \ubb3c\uace0\uae30\ub97c \uc55e\uc5d0 \ub454 \uc720\ud639\uc744 \uc608\uc0c1\ud558\uc9c0\ub9cc \uc774\uc57c\uae30\uc758 \uc791\uc740 \uc2e4\uc218\ub294 \ub2e4\ub978 \ubc29\ud5a5\uc5d0\uc11c \uc0dd\uae34\ub2e4. \ud53c\uc628\uc740 \uc5f0\uc5b4\ub97c \uad7d\ub2e4\uac00 \uaecd\uc9c8\uc758 \ubd80\ud47c \uacf3\uc744 \uc5c4\uc9c0\ub85c \ub204\ub978\ub2e4. \ub370\uc778 \uc190\uc744 \uc785\uc5d0 \ub123\ub294 \ubc14\ub78c\uc5d0 \uc0dd\uc120\uc758 \ub9db\uc744 \ubcf4\uac8c \ub41c\ub2e4. \uc2a4\uc2b9\uc758 \uc74c\uc2dd\uc744 \ubab0\ub798 \ud6d4\uccd0 \uba39\uc73c\ub824\uace0 \uacc4\ud68d\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc77c\ud558\ub2e4 \uc0dd\uae34 \ubb34\uc2ec\ud55c \ubc18\uc751\uc774\ub2e4. \ud53c\ub124\uac00\uc2a4\uac00 \ub3cc\uc544\uc654\uc744 \ub54c \ud53c\uc628\uc740 \uadf8 \uc77c\uc744 \uc228\uae30\uc9c0 \uc54a\uace0 \ub9d0\ud55c\ub2e4. \ubb3c\uace0\uae30\uc758 \ub9db\uc774 \uc190\uac00\ub77d\uc5d0 \ubb3b\uc740 \uac83\ucc98\ub7fc \uc88b\ub2e4\uba74 \uc544\uc8fc \ub9db\uc788\uaca0\ub2e4\uace0 \uc6c3\uae30\uae4c\uc9c0 \ud55c\ub2e4. \uc2ec\uac01\ud55c \ube44\ubc00\uc774 \uc788\ub294 \uc5b4\ub978\uacfc \uc544\uc9c1 \uadf8\uac83\uc744 \ubaa8\ub974\ub294 \uc544\uc774\uc758 \ub300\ud654\uac00 \uc5b4\uae0b\ub09c\ub2e4. \ud53c\ub124\uac00\uc2a4\ub294 \uc18c\ub144\uc758 \uc774\ub984\uc744 \ud655\uc778\ud558\uace0 \uc608\uc5b8\uc758 \ub098\uba38\uc9c0\ub97c \ud138\uc5b4\ub193\ub294\ub2e4. \uc5f0\uc5b4\ub97c \uc7a1\ub294 \uc0ac\ub78c\uc740 \uc790\uc2e0\uc774\uc9c0\ub9cc \uba39\uc744 \uc0ac\ub78c\uc740 \ud53c\uc628\uc73c\ub85c \uc815\ud574\uc838 \uc788\uc5c8\ub2e4. \uc55e\uc11c \uadf8 \uc0ac\uc2e4\uc744 \ubaa8\ub450 \ub9d0\ud558\uc9c0 \uc54a\uc558\ub358 \uac83\uc774\ub2e4. \uc774 \ud310\ubcf8\uc5d0\uc11c \uc2a4\uc2b9\uc740 \ub2e8\uc21c\ud788 \uc6b0\uc5f0\ud788 \uc790\uae30 \ubaab\uc744 \ube7c\uc557\uae34 \uc0ac\ub78c\uc774 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc774 \uc633\uc740\uc9c0 \uc54c\uace0\ub3c4 \ub9c8\uc74c\uc774 \ud754\ub4e4\ub9b0 \uc0ac\ub78c\uc774\ub2e4. \uadf8\uac00 \ubb3c\uace0\uae30\ub97c \uc7a1\uc73c\uba70 \uce58\ub978 \uc2f8\uc6c0\uc740 \uc5f0\uc5b4\ub97c \ub04c\uc5b4\uc62c\ub9ac\ub294 \ud798\uaca8\ub8e8\uae30 \uc678\uc5d0 \uc790\uae30 \uc695\ub9dd\uacfc\uc758 \ub2e4\ud23c\uc774\uae30\ub3c4 \ud588\ub2e4. \ud53c\uc628\uc740 \uc2a4\uc2b9\uc5d0\uac8c \ubc18\uc744 \uc8fc\uaca0\ub2e4\uace0 \ud55c\ub2e4. \ud558\uc9c0\ub9cc \ud53c\ub124\uac00\uc2a4\ub294 \uc790\uc2e0\uc774 \uba39\uc9c0 \uc54a\uaca0\ub2e4\uba70 \uc18c\ub144\uc5d0\uac8c \uc5f0\uc5b4\ub97c \uba39\uac8c \ud55c\ub2e4. \uc88b\uc740 \uac83\uc744 \uc790\uae30 \uacc1\uc5d0 \ub450\uace0 \uc2f6\uc5c8\ub358 \ub9c8\uc74c\uc744 \ub0b4\ub824\ub193\ub294 \uc21c\uac04\uc774\ub2e4. \uc5f0\uc5b4\ub97c \uba39\uc740 \ub4a4 \uc2a4\uc2b9\uc758 \ub9c8\uc74c\uc5d0\ub294 \uae30\uc068\uacfc \ud3c9\uc628\uc774 \ub3cc\uc544\uc628\ub2e4. \uc18c\ub144\uc774 \uc5bb\uc740 \uc9c0\ud61c\ub9cc\uc774 \uacb0\ub9d0\uc758 \uc120\ubb3c\uc774 \uc544\ub2c8\ub2e4. \uc2a4\uc2b9\ub3c4 \uc633\ub2e4\uace0 \uc544\ub294 \uc77c\uc744 \uc120\ud0dd\ud55c \ub4a4 \uc0c8\ub85c\uc6b4 \ub9c8\uc74c\uc744 \uc5bb\ub294\ub2e4. \ub450 \uc0ac\ub78c \ubaa8\ub450\uc758 \ubcc0\ud654\uac00 \uc788\uc5b4\uc11c \uc7a5\uba74\uc774 \ub530\ub73b\ud558\uac8c \ub0a8\ub294\ub2e4. \uc774\ud6c4 \ud53c\uc628\uc740 \ubc30\uc6b4 \uac83\uc744 \ub354 \ub113\uc740 \uc138\uacc4\uc5d0\uc11c \uc2dc\ud5d8\ud558\ub7ec \ub5a0\ub09c\ub2e4. \uc798 \uc54c\ub824\uc9c4 \uc601\uc6c5\uc758 \uc774\ub984\uc744 \uba3c\uc800 \uc0dd\uac01\ud558\uba74 \uc774 \uc791\uc740 \uc9d1\uacfc \ubb3c\uace0\uae30 \ubc14\uad6c\ub2c8\ub294 \uc7a0\uae50 \uc9c0\ub098\uac08 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uadf8\uacf3\uc5d0\uc11c \uadf8\ub294 \uc9c8\ubb38\uacfc \uc815\uc9c1\ud568, \uc8fc\uace0\ubc1b\ub294 \uad00\uacc4\ub97c \ubc30\uc6e0\ub2e4. \uc5f0\uc5b4\uc758 \uc9c0\ud61c\ub294 \uc778\uac04\uad00\uacc4\uc640 \ub5a8\uc5b4\uc9c4 \uc2e0\ube44\ud55c \ub2a5\ub825\ub9cc\uc73c\ub85c \uadf8\ub824\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uac00\ub974\uccd0 \uc900 \uc0ac\ub78c\uacfc \ubc30\uc6b0\ub294 \uc0ac\ub78c\uc774 \uc11c\ub85c\ub97c \uc544\ub07c\uace0 \ub54c\ub85c\ub294 \uc790\uae30 \ub9c8\uc74c\uc744 \uace0\uccd0\uc57c \ud588\ub2e4. \uc774\uc57c\uae30\uc758 \ud070 \ud798\uc774 \uc870\uc6a9\ud55c \uc0b4\ub9bc \uc18d\uc5d0 \uba38\ubb38\ub2e4. \uc2a4\ud2f0\ube10\uc2a4\uc758 \ucc45\uc740 \uc624\ub798\ub41c \uc544\uc77c\ub79c\ub4dc \uc774\uc57c\uae30\ub4e4\uc744 20\uc138\uae30\uc5d0 \ubb38\ud559\uc801\uc73c\ub85c \ub2e4\uc2dc \uc4f4 \uac83\uc774\ub2e4. \uc624\ub298 \uc77d\uc740 \ub300\ud654\uc640 \uc778\ubb3c\uc758 \ub9c8\uc74c\uc744 \uace0\ub300\uc758 \ud604\uc7a5 \uae30\ub85d\ucc98\ub7fc \ubc1b\uc544\ub4e4\uc774\uc9c0\ub294 \uc54a\uc558\ub2e4. \uc804\uc2b9\uc774 \uc0c8 \uc791\uac00\uc758 \ubaa9\uc18c\ub9ac\ub97c \ub9cc\ub098 \ud48d\uc131\ud574\uc9c0\ub294 \uc0ac\ub840\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \ub2e4\uc2dc \uc5f0\uc5b4\ub97c \ub5a0\uc62c\ub9b4 \ub54c \ud53c\uc628\uc758 \uc5c4\uc9c0\uc190\uac00\ub77d\uacfc \ud568\uaed8 \ud53c\ub124\uac00\uc2a4\uc758 \uc120\ud0dd\ub3c4 \uae30\uc5b5\ud574 \ubcf4\uc790. \uc9c0\ud61c\ub97c \uc5bb\ub294 \uc77c\uacfc \uc9c0\ud61c\ub86d\uac8c \ud589\ub3d9\ud558\ub294 \uc77c\uc740 \uc11c\ub85c \ub2e4\ub978 \uc7a5\uba74\uc5d0\uc11c \ub4dc\ub7ec\ub09c\ub2e4. \ubb3c\uace0\uae30\ub97c \uba39\uc9c0 \uc54a\uc740 \uc2a4\uc2b9\uc5d0\uac8c\ub3c4 \uc774\uc57c\uae30\uac00 \ub0a8\ub294 \uc774\uc720\ub2e4."}, {"id": "fragonard-music-lesson", "title": "\uc74c\uc545 \uc218\uc5c5 \u2014 \uc545\ubcf4\ubcf4\ub2e4 \uc11c\ub85c\uc758 \uc5bc\uad74\uc774 \uac00\uae4c\uc6b4 \uc2dc\uac04", "summary": "\uc74c\uc545\uc744 \uac00\ub974\uce58\ub294 \uc7a5\uba74\uacfc \uc778\ubb3c \uc0ac\uc774\uc758 \uce5c\ubc00\ud568\uc774 \uacb9\uce58\ub294 \uadf8\ub9bc\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/fragonard-music-lesson/index.html", "image": "../media/fragonard-music-lesson.jpg", "alt": "\ud504\ub77c\uace0\ub098\ub974\uc758 \uc74c\uc545 \uc218\uc5c5. \uac74\ubc18\uc545\uae30 \uc55e\uc758 \uc5ec\uc131\uacfc \uc545\ubcf4\ub97c \ub4e0 \ub0a8\uc131, \uc758\uc790 \uc704\uc758 \uace0\uc591\uc774\uc640 \ud604\uc545\uae30\uac00 \ubcf4\uc785\ub2c8\ub2e4.", "text": "\uc74c\uc545 \uc218\uc5c5 \u2014 \uc545\ubcf4\ubcf4\ub2e4 \uc11c\ub85c\uc758 \uc5bc\uad74\uc774 \uac00\uae4c\uc6b4 \uc2dc\uac04 \ud504\ub77c\uace0\ub098\ub974\uc758 \uc2e4\ub0b4\uc5d0\uc11c \uac74\ubc18\uacfc \uc2dc\uc120, \uc791\uc740 \uace0\uc591\uc774\ub97c \ucc3e\uc544\ubcf4\uae30 \uc74c\uc545\uc744 \uac00\ub974\uce58\ub294 \uc7a5\uba74\uacfc \uc778\ubb3c \uc0ac\uc774\uc758 \uce5c\ubc00\ud568\uc774 \uacb9\uce58\ub294 \uadf8\ub9bc\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \uc545\ubcf4\uac00 \ud3bc\uccd0\uc838 \uc788\uace0 \ud55c \uc0ac\ub78c\uc774 \uac74\ubc18 \uc55e\uc5d0 \uc549\uc544 \uc788\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\uc740 \uc545\ubcf4\ub97c \ub4e4\uace0 \uac00\uae4c\uc774 \ubab8\uc744 \uae30\uc6b8\uc778\ub2e4. \uc81c\ubaa9\uc740 \uc74c\uc545 \uc218\uc5c5\uc778\ub370 \uadf8\ub9bc\uc744 \ubcfc\uc218\ub85d \ub450 \uc0ac\ub78c\uc758 \uc2dc\uc120\uc5d0\ub3c4 \uad00\uc2ec\uc774 \uac04\ub2e4. \ubb34\uc2a8 \uace1\uc744 \ubc30\uc6b0\ub294\uc9c0\ubcf4\ub2e4 \uc5b4\ub5a4 \uad00\uacc4\uc758 \uc2dc\uac04\uc774 \ud750\ub974\ub294\uc9c0\uac00 \uba3c\uc800 \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ud504\ub77c\uace0\ub098\ub974\uc758 \u3008\uc74c\uc545 \uc218\uc5c5\u3009\uc774\ub2e4. \uc18c\ub9ac\ub97c \uc9c1\uc811 \ub4e4\uc744 \uc218 \uc5c6\ub294 \uadf8\ub9bc\uc774 \uc74c\uc545\uc744 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \ubcf4\uc5ec \uc8fc\ub294\uc9c0, \ub610 \uc77c\uc0c1\uc758 \ud55c \uc7a5\uba74\uc744 \uc5b4\ub5bb\uac8c \uce5c\ubc00\ud55c \uacf5\uac04\uc73c\ub85c \ub9cc\ub4dc\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc55e\ucabd \uc758\uc790\uc5d0\ub294 \ub73b\ubc16\uc758 \uc791\uc740 \uad6c\uacbd\uafbc\ub3c4 \uc788\ub2e4. \uadf8\ub9bc \uac00\uc6b4\ub370\uc5d0\ub294 \uac74\ubc18\uc545\uae30\uac00 \uc788\uace0 \uadf8 \uc55e\uc5d0 \uc5ec\uc131\uc774 \uc549\uc544 \uc788\ub2e4. \ub0a8\uc131\uc740 \ud3bc\uccd0\uc9c4 \uc545\ubcf4 \uac00\uae4c\uc774\uc5d0 \uc190\uc744 \ub454\ub2e4. \uc774 \ubb3c\uac74\ub4e4 \ub54c\ubb38\uc5d0 \uc81c\ubaa9\uc744 \uc77d\uae30 \uc804\uc5d0\ub3c4 \uc74c\uc545\uacfc \uad00\ub828\ub41c \uc2dc\uac04\uc784\uc744 \uc54c\uc544\ubcfc \uc218 \uc788\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc18c\ub9ac\uac00 \ub208\uc5d0 \ubcf4\uc774\ub294 \ub3c4\uad6c\ub85c \ud45c\ud604\ub418\ub294 \uc148\uc774\ub2e4. \uc9c0\uae08 \uc6b0\ub9ac\uac00 \uc775\uc219\ud55c \ud604\ub300 \ud53c\uc544\ub178\uc640 \uc18c\ub9ac\uac00 \ub611\uac19\uc558\uc744 \uac83\uc774\ub77c\uace0 \uac00\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc6b0\uc120\uc740 \uac74\ubc18\uc744 \ub2e4\ub8e8\ub294 \uc0ac\ub78c\uacfc \uc545\ubcf4\ub97c \ud568\uaed8 \ubcf4\ub294 \uc0ac\ub78c\uc774 \uc5b4\ub5a4 \uac70\ub9ac\ub97c \uc774\ub8e8\ub294\uc9c0 \ubcf4\uc790. \uc545\uae30\uc758 \uc815\ud655\ud55c \uad6c\uc870\ub97c \ubaa8\ub450 \uc54c\uc544\uc57c \uc7a5\uba74\uc5d0 \ub4e4\uc5b4\uac08 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub0a8\uc131\uc758 \ud55c \uc190\uc740 \uc545\ubcf4 \ucabd\uc5d0 \uc788\uace0 \ub2e4\ub978 \uc190\uc740 \uc5ec\uc131\uc758 \uc758\uc790 \ub4a4 \uac00\uae4c\uc774\uc5d0 \ub193\uc5ec \uc788\ub2e4. \uc545\ubcf4\ub97c \ub3c4\uc640\uc8fc\ub294 \ud589\ub3d9\uacfc \uc778\ubb3c \uacc1\uc5d0 \uba38\ubb34\ub294 \uc790\uc138\uac00 \ub3d9\uc2dc\uc5d0 \ubcf4\uc778\ub2e4. \ud558\ub098\uc758 \ubab8 \uc548\uc5d0\uc11c \uc74c\uc545\uacfc \uad00\uacc4\uac00 \ud568\uaed8 \ud45c\ud604\ub41c\ub2e4. \uc774\ub97c \uace7\ubc14\ub85c \ud2b9\uc815\ud55c \uc5f0\uc560 \uc0ac\uac74\uc758 \uc99d\uac70\ub77c\uace0 \ub2e8\uc815\ud558\uc9c0\ub294 \ub9d0\uc790. \uadf8\ub9bc\uc774 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \ubab8\uc758 \uac70\ub9ac\uc640 \uc190\uc758 \uc704\uce58\ub2e4. \uad50\uc0ac\uc640 \ud559\uc0dd\uc774\ub77c\ub294 \uae30\ub2a5\ub9cc\uc73c\ub85c \uc7a5\uba74\uc774 \ub05d\ub098\ub294\uc9c0, \uadf8\ubcf4\ub2e4 \uac00\uae4c\uc6b4 \ubd84\uc704\uae30\ub3c4 \ub290\uaef4\uc9c0\ub294\uc9c0 \uad00\uac1d\uc774 \uc0b4\ud3b4\ubcfc \uc5ec\uc9c0\uac00 \uc0dd\uae34\ub2e4. \uc545\ubcf4\ub97c \ubcf4\uace0 \uc5bc\uad74\ub85c \ub208\uc744 \uc62e\uae30\uba74 \ub450 \uc0ac\ub78c\uc774 \uc11c\ub85c\ub97c \uc5b4\ub5bb\uac8c \ud5a5\ud558\ub294\uc9c0 \uad00\uc2ec\uc774 \uac04\ub2e4. \uc77d\uc5b4\uc57c \ud560 \uc885\uc774\uc640 \uac00\uae4c\uc774 \uc788\ub294 \uc5bc\uad74\uc774 \ud55c \ud654\uba74 \uc548\uc5d0\uc11c \uacbd\uc7c1\ud558\ub294 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \uc74c\uc545 \uc218\uc5c5\uc774\ub77c\ub294 \uc81c\ubaa9\uc5d0 \uc791\uc740 \uc6c3\uc74c\uc774 \ub354\ud574\uc9c0\ub294 \uc9c0\uc810\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub450 \uc0ac\ub78c\uc758 \ub300\uc0ac\ub97c \uc6b0\ub9ac\uac00 \uc2e4\uc81c\ub85c \ub4e4\uc740 \uac83\ucc98\ub7fc \uc368 \ub123\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud45c\uc815\uacfc \ubc29\ud5a5\uc744 \ubcf4\uba70 \uac00\ub2a5\uc131\uc744 \ub290\ub07c\ub294 \uac83\uacfc \uc228\uc740 \uc0ac\uc5f0\uc744 \ud655\uc815\ud558\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \ud68c\ud654\ub294 \ub9d0\uc774 \uc5c6\uae30 \ub54c\ubb38\uc5d0 \uad00\uacc4\uc758 \ud574\uc11d\uc744 \uc5ec\uc720 \uc788\uac8c \ub0a8\uaca8 \ub458 \uc218 \uc788\ub2e4. \uc55e\ucabd \uc758\uc790\uc5d0\ub294 \uace0\uc591\uc774\uac00 \ubcf4\uc778\ub2e4. \uc74c\uc545\uc744 \uc5f0\uc8fc\ud558\uac70\ub098 \uc545\ubcf4\ub97c \uc77d\ub294 \uc8fc\uc778\uacf5\uc740 \uc544\ub2c8\uc9c0\ub9cc, \uc774 \ubc29\uc774 \uc0ac\ub78c\ub4e4\uc758 \uc77c\uc0c1\uc774 \uc788\ub294 \uacf5\uac04\ucc98\ub7fc \ub290\uaef4\uc9c0\uac8c \ud55c\ub2e4. \ud070 \uc8fc\uc81c\ub9cc \ucc3e\uc73c\ub824 \ubcf4\uba74 \ub193\uce58\uae30 \uc26c\uc6b4 \uc791\uc740 \uc874\uc7ac\ub2e4. \uace0\uc591\uc774\ub97c \ubc1c\uacac\ud588\ub2e4\uace0 \uc989\uc2dc \uc5b4\ub5a4 \uace0\uc815\ub41c \uc0c1\uc9d5\uc73c\ub85c \ubc88\uc5ed\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uba3c\uc800 \ub450 \uc0ac\ub78c\uacfc \uc5bc\ub9c8\ub098 \uac00\uae4c\uc774 \uc788\uc73c\uba70 \uc5b4\ub5a4 \ubb3c\uac74 \uacc1\uc5d0 \uc788\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \ubc29 \uc548\uc758 \uc791\uc740 \uc0dd\uba85\uc774 \uc7a5\uba74\uc758 \ub531\ub531\ud568\uc744 \ub35c\uc5b4 \uc8fc\ub294 \ub4ef\ud55c \uac10\uc0c1\uc744 \uac00\uc9c8 \uc218 \uc788\ub2e4. \uc81c\ubaa9 \ubc14\uae65\uc758 \uc138\ubd80\uac00 \uadf8\ub9bc\uc744 \ub354 \uc624\ub798 \ubcf4\uac8c \ud55c\ub2e4. \uc758\uc790 \uc704\uc640 \uc8fc\ubcc0\uc5d0\ub294 \ud604\uc545\uae30\uc640 \uc545\ubcf4 \uac19\uc740 \ubb3c\uac74\uc774 \ub193\uc5ec \uc788\ub2e4. \ubab8\uc758 \ubc29\ud5a5\uacfc \ubb3c\uac74\uc758 \ube44\uc2a4\ub4ec\ud55c \uc120\uc774 \uc11c\ub85c \uc774\uc5b4\uc9c0\uba70 \ud654\uba74\uc758 \uc6c0\uc9c1\uc784\uc744 \ub9cc\ub4e0\ub2e4. \uc778\ubb3c \ub458\ub9cc \uc798\ub77c \ubcf4\uba74 \uc774 \ub9ac\ub4ec\uc758 \uc77c\ubd80\uac00 \uc0ac\ub77c\uc9c4\ub2e4. \uc61b \ub3c4\ub85d\uc758 \uc545\uae30 \uc774\ub984\uc744 \uadf8\ub300\ub85c \ubaa8\ub4e0 \uc138\ubd80\uc758 \ud655\uc815 \ub2f5\uc73c\ub85c \uc0bc\uae30\ubcf4\ub2e4, \uc9c0\uae08 \ub3c4\ud310\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\ub294 \ud615\uc0c1\uacfc \ubc30\uce58\ubd80\ud130 \ubcf4\uc558\ub2e4. \uc0dd\ud65c\uc758 \ubb3c\uac74\uc774 \uc5b4\ub5a4 \uc120\uacfc \uba74\uc744 \ub9cc\ub4dc\ub294\uc9c0 \uc0b4\ud53c\ub294 \uc77c\ub3c4 \uac10\uc0c1\uc758 \uc77c\ubd80\ub2e4. \uc7a5\uc2dd\uc740 \ub54c\ub85c \uc778\ubb3c\uacfc \uac19\uc740 \uc815\ub3c4\ub85c \ud654\uba74\uc758 \uad00\uacc4\ub97c \ub9cc\ub4e0\ub2e4. \ud770 \uc637\uacfc \ub530\ub73b\ud55c \uc0c9\uc758 \uc545\uae30, \ud750\ub974\ub294 \ucc9c\uc758 \ubaa8\uc591\uc744 \ubc88\uac08\uc544 \ubcf4\uc790. \uc5bc\uad74\uacfc \uc190 \uc8fc\ubcc0\uc758 \ubc1d\uc740 \ubd80\ubd84\uc774 \uac00\uae4c\uc774 \ub2e4\uac00\uc624\uace0, \ub098\uba38\uc9c0 \uc2e4\ub0b4\ub294 \uc778\ubb3c\ub4e4\uc744 \ub458\ub7ec\uc2fc\ub2e4. \uc138\ubd80\ub97c \ub611\uac19\uc774 \uc120\uba85\ud558\uac8c \uc124\uba85\ud558\uc9c0 \uc54a\uc544\ub3c4 \uce5c\ubc00\ud55c \ubd84\uc704\uae30\uac00 \uc0dd\uae38 \uc218 \uc788\ub2e4. \uc774\ub7f0 \uc7a5\uba74\uc774 \ub2f9\uc2dc \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \uc0dd\ud65c\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud2b9\uc815\ud55c \uc2e4\ub0b4\uc640 \uc5ec\uac00\uc758 \ubaa8\uc2b5\uc744 \ud654\uac00\uac00 \uace8\ub77c \uad6c\uc131\ud55c \uadf8\ub9bc\uc774\ub2e4. \ud3b8\uc548\ud558\uace0 \uc544\ub984\ub2e4\uc6b4 \uc778\uc0c1 \uc18d\uc5d0\ub3c4 \uc5b4\ub5a4 \uacf5\uac04\uc774 \uc608\uc220\uc758 \uc8fc\uc81c\uac00 \ub418\uc5c8\ub294\uc9c0 \uc0dd\uac01\ud560 \uc9c8\ubb38\uc774 \uc788\ub2e4. \ud48d\uacbd\uc744 \uc990\uae30\uba74\uc11c \uadf8 \uc870\uac74\ub3c4 \ud568\uaed8 \ubcfc \uc218 \uc788\ub2e4. \uc6b0\ub9ac\ub294 \uc545\uae30\ub97c \ubcf4\uba74 \uc5b4\ub5a4 \uc18c\ub9ac\uac00 \ub0a0\uc9c0 \ub5a0\uc62c\ub9b0\ub2e4. \uadf8\ub7ec\ub098 \uadf8\ub9bc\uc774 \ub4e4\ub824 \uc8fc\ub294 \uc2e4\uc81c \ub179\uc74c\uc740 \uc5c6\ub2e4. \uc9c0\uae08 \uc5b4\ub5a4 \uace1\uc744 \uc5f0\uc8fc\ud558\ub294\uc9c0 \ud655\uc815\ud558\uae30\ubcf4\ub2e4 \ud55c \uc0ac\ub78c\uc774 \ub4e3\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc5f0\uc8fc\ud558\ub294 \uad00\uacc4\ub97c \uc0c1\uc0c1\ud558\ub294 \ud3b8\uc774 \uc7a5\uba74\uc5d0 \uac00\uae4c\uc6b8 \uc218 \uc788\ub2e4. \ubc18\ub300\ub85c \uc7a0\uae50 \ubaa8\ub4e0 \uc18c\ub9ac\ub97c \ub044\uace0 \ub450 \uc0ac\ub78c\uc758 \uc790\uc138\ub9cc \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc74c\uc545\uc774\ub77c\ub294 \uacf5\ub3d9\uc758 \ud65c\ub3d9\uc774 \uc5b4\ub5bb\uac8c \uac00\uae4c\uc6b4 \uac70\ub9ac\ub97c \ub9cc\ub4dc\ub294\uc9c0 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc791\ud488\uc758 \uc81c\ubaa9\uacfc \uc2dc\uac01\uc801\uc778 \uc815\ubcf4\uac00 \uc11c\ub85c\ub97c \ub3d5\uc9c0\ub9cc \ud55c\ucabd\uc774 \ubaa8\ub4e0 \ud574\uc11d\uc744 \ub05d\ub0b4\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uc61b \ub8e8\ube0c\ub974 \ub3c4\ub85d\uc5d0 \uc218\ub85d\ub41c \uc2e4\uc81c \ud68c\ud654\uc758 \uc0c9\ucc44 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \ud604\ub300\uc778\uc774 \uc0c8\ub85c \ub9cc\ub4e0 \uc74c\uc545 \uc218\uc5c5 \uc0bd\ud654\uac00 \uc544\ub2c8\ub77c \ud504\ub77c\uace0\ub098\ub974\uc758 \ud654\uba74\uc744 \ubcf4\ub294 \uc790\ub8cc\ub2e4. \uc61b \uc778\uc1c4\uac00 \uc2e4\ubb3c\uc758 \ubaa8\ub4e0 \uc0c9\uacfc \uc9c8\uac10\uc744 \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\uc73c\ubbc0\ub85c \ud070 \uad6c\uc131\ubd80\ud130 \uc0b4\ud3b4\ubcf4\uc558\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc74c\uc545 \uc218\uc5c5\uc774\ub77c\ub294 \uc7a5\uba74\uc744 \ud655\uc778\ud558\uace0, \ub2e4\uc74c\uc5d0\ub294 \uc190\uacfc \uc5bc\uad74, \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \uace0\uc591\uc774\uc640 \uc8fc\ubcc0 \ubb3c\uac74\uc744 \ucc3e\uc544\ubcf4\uc790. \uac19\uc740 \ubc29\uc774 \ubcfc \ub54c\ub9c8\ub2e4 \uc870\uae08 \ub2e4\ub978 \uc911\uc2ec\uc744 \ub0b4\uc5b4 \uc904 \uc218 \uc788\ub2e4. \ud2b9\ubcc4\ud55c \uc0ac\uac74\uc774 \uc5c6\ub294 \uadf8\ub9bc\ub3c4 \uc0ac\ub78c \uc0ac\uc774\uc758 \uac70\ub9ac\uc640 \uc791\uc740 \uc138\ubd80\ub97c \ud1b5\ud574 \ucda9\ubd84\ud788 \ud48d\ubd80\ud55c \uc77d\uc744\uac70\ub9ac\uac00 \ub41c\ub2e4."}, {"id": "frankenstein-creator-and-creature", "title": "\ud504\ub791\ucf04\uc288\ud0c0\uc778 \u2014 \ub9cc\ub4e4\uc5b4 \ub0b8 \uc0dd\uba85\uc5d0\uac8c\ub294 \ub204\uac00 \ucc45\uc784\uc9c8\uae4c", "summary": "\ube45\ud130\uc640 \ud53c\uc870\ubb3c\uc758 \uc904\uac70\ub9ac, \uc5ec\ub7ec \uacb9\uc758 \uc774\uc57c\uae30 \uad6c\uc870\ub97c \ud1b5\ud574 \ucc3d\uc870\uc640 \ucc45\uc784\uc758 \ubb38\uc81c\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/frankenstein-creator-and-creature/index.html", "image": "../media/frankenstein-creator-and-creature-scene-20261030.png", "alt": "\uc232\uc18d \uc740\uc2e0\ucc98\uc5d0\uc11c \ucc45 \uacc1\uc5d0 \ud640\ub85c \uc549\uc544 \uba40\ub9ac \ubd88\ube5b\uc774 \uc788\ub294 \uc624\ub450\ub9c9\uc744 \ubc14\ub77c\ubcf4\ub294 \ud53c\uc870\ubb3c\uc758 \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ud504\ub791\ucf04\uc288\ud0c0\uc778 \u2014 \ub9cc\ub4e4\uc5b4 \ub0b8 \uc0dd\uba85\uc5d0\uac8c\ub294 \ub204\uac00 \ucc45\uc784\uc9c8\uae4c \uacfc\ud559\uc790\uc758 \uc774\ub984\uacfc \uc774\ub984 \uc5c6\ub294 \ud53c\uc870\ubb3c, \uc11c\ub85c\uc758 \uc774\uc57c\uae30\ub97c \ub4e3\ub294 \uc18c\uc124 \ube45\ud130\uc640 \ud53c\uc870\ubb3c\uc758 \uc904\uac70\ub9ac, \uc5ec\ub7ec \uacb9\uc758 \uc774\uc57c\uae30 \uad6c\uc870\ub97c \ud1b5\ud574 \ucc3d\uc870\uc640 \ucc45\uc784\uc758 \ubb38\uc81c\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \u2018\ud504\ub791\ucf04\uc288\ud0c0\uc778\u2019\uc774\ub77c\uace0 \ud558\uba74 \ubcfc\ud2b8\uac00 \ubc15\ud78c \uba38\ub9ac\ub098 \ud070 \ubab8\uc9d1\uc758 \uad34\ubb3c\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uc6d0\uc791\uc5d0\uc11c \ud504\ub791\ucf04\uc288\ud0c0\uc778\uc740 \uc0dd\uba85\uc744 \ub9cc\ub4e4\uc5b4 \ub0b8 \ube45\ud130\uc758 \uc131\uc774\ub2e4. \ub9cc\ub4e4\uc5b4\uc9c4 \uc874\uc7ac\uc5d0\uac8c\ub294 \ubcc4\ub3c4\uc758 \uace0\uc720\ud55c \uc774\ub984\uc774 \ubd99\uc9c0 \uc54a\ub294\ub2e4. \uccab \uad6c\ubd84\uc744 \uc54c\uace0 \ub098\uba74 \uc81c\ubaa9\ubd80\ud130 \uc870\uae08 \ub2e4\ub974\uac8c \ub4e4\ub9b0\ub2e4. \uba54\ub9ac \uc178\ub9ac\uc758 \uc18c\uc124\uc740 1818\ub144\uc5d0 \ucc98\uc74c \ucd9c\uac04\ub418\uc5c8\ub2e4. \ub110\ub9ac \uc77d\ud788\ub294 1831\ub144 \ud310\ubcf8\uacfc\ub3c4 \uad6c\ubcc4\ud560 \ud544\uc694\uac00 \uc788\ub2e4. \uc5ec\uae30\uc11c\ub294 \ub300\uc870\ud55c \uc6d0\ubb38\uc758 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \ud3ec\ud568\ud574, \uad34\ubb3c\uc774 \ub204\uad6c\ub0d0\ub294 \uc9c8\ubb38\ubcf4\ub2e4 \ub204\uac00 \uc5b4\ub5a4 \ucc45\uc784\uc744 \uc9c0\ub294\uac00\ub77c\ub294 \uc9c8\ubb38\uc73c\ub85c \ub4e4\uc5b4\uac00 \ubcf8\ub2e4. \uc18c\uc124\uc740 \uacfc\ud559\uc790\uc758 \uc2e4\ud5d8\uc2e4\uc774 \uc544\ub2c8\ub77c \ud0d0\ud5d8\uac00 \ub85c\ubc84\ud2b8 \uc6d4\ud134\uc774 \ub204\uc774\uc5d0\uac8c \ubcf4\ub0b4\ub294 \ud3b8\uc9c0\ub85c \uc2dc\uc791\ud55c\ub2e4. \ubd81\ucabd\uc744 \ud5a5\ud558\ub358 \uc6d4\ud134\uc740 \uc5bc\uc74c \uc18d\uc5d0\uc11c \uae30\uc9c4\ub9e5\uc9c4\ud55c \ube45\ud130\ub97c \ub9cc\ub09c\ub2e4. \ube45\ud130\uac00 \uc790\uc2e0\uc758 \uc774\uc57c\uae30\ub97c \ub4e4\ub824\uc8fc\uace0, \uc6d4\ud134\uc740 \uadf8\uac83\uc744 \ud3b8\uc9c0\uc5d0 \uc62e\uae34\ub2e4. \ub3c5\uc790\ub294 \uc0ac\uac74\uc744 \ubc14\ub85c \ub208\uc55e\uc5d0\uc11c \ubcf4\ub294 \ub300\uc2e0 \ub204\uad70\uac00\uc758 \ub9d0\uc744 \ud1b5\ud574 \ub4e3\ub294\ub2e4. \uadf8 \uc548\uc5d0\ub294 \ud53c\uc870\ubb3c\uc774 \ube45\ud130\uc5d0\uac8c \ub4e4\ub824\uc8fc\ub294 \ud68c\uc0c1\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \ubc14\uae65\uc758 \uc6d4\ud134, \uc548\ucabd\uc758 \ube45\ud130, \ub354 \uc548\ucabd\uc758 \ud53c\uc870\ubb3c\uc774\ub77c\ub294 \uc5ec\ub7ec \uacb9\uc744 \uae30\uc5b5\ud558\uba74 \uc65c \uc11c\ub85c\uc758 \ub9d0\uc744 \ube44\uad50\ud574\uc57c \ud558\ub294\uc9c0 \ubcf4\uc778\ub2e4. \uc81c\ub124\ubc14\uc5d0\uc11c \uc790\ub780 \ube45\ud130\ub294 \uc790\uc5f0\uc758 \ube44\ubc00\uacfc \uc0dd\uba85\uc758 \uc6d0\ub9ac\uc5d0 \ub9e4\ub8cc\ub41c\ub2e4. \ub300\ud559\uc774 \uc788\ub294 \uc789\uace8\uc288\ud0c0\ud2b8\uc5d0\uc11c \uc5f0\uad6c\uc5d0 \ubab0\ub450\ud558\uba70 \uc0b4\uc544 \uc788\ub294 \uc874\uc7ac\ub97c \ub9cc\ub4e4\uc5b4 \ub0bc \ubc29\ubc95\uc744 \ucc3e\ub294\ub2e4. \uac00\uc871\uacfc \uc77c\uc0c1\uc5d0\uc11c \uba40\uc5b4\uc9c4 \ucc44 \ubaa9\ud45c \ud558\ub098\ub97c \ud5a5\ud574 \ub098\uc544\uac00\ub294 \ubaa8\uc2b5\uc774\ub2e4. \uadf8\ub7ec\ub098 \ub9c8\uce68\ub0b4 \uc0dd\uba85\uc774 \uc6c0\uc9c1\uc774\ub294 \uc21c\uac04 \uadf8\ub294 \uc790\uc2e0\uc774 \ub9cc\ub4e0 \uc874\uc7ac\ub97c \ub450\ub824\uc6cc\ud558\uace0 \ud53c\ud55c\ub2e4. \uc624\ub7ab\ub3d9\uc548 \uc131\uacf5\ub9cc \uc0c1\uc0c1\ud588\uc9c0\ub9cc \uc131\uacf5 \ub4a4\uc758 \uad00\uacc4\ub294 \uc900\ube44\ud558\uc9c0 \ubabb\ud588\ub2e4. \uc18c\uc124\uc758 \ubb38\uc81c\ub294 \u2018\ub9cc\ub4e4 \uc218 \uc788\ub294\uac00\u2019\ub77c\ub294 \uc9c8\ubb38\uc774 \ud574\uacb0\ub418\ub294 \ubc14\ub85c \uadf8 \uc21c\uac04\ubd80\ud130 \ub354 \ucee4\uc9c4\ub2e4. \ud53c\uc870\ubb3c\uc740 \ucc98\uc74c\ubd80\ud130 \uc138\uc0c1\uc744 \ub2a5\uc219\ud558\uac8c \uc774\ud574\ud558\uc9c0 \ubabb\ud55c\ub2e4. \uac10\uac01\uacfc \ubc30\uace0\ud514, \ucd94\uc704\uc640 \ubd88\uc744 \uacbd\ud5d8\ud558\uba70 \uc0b4\uc544\uac08 \ubc29\ubc95\uc744 \ubc30\uc6b4\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \uadf8\uc758 \uc678\ubaa8\uc5d0 \ub180\ub77c \ub3c4\ub9dd\uce58\uac70\ub098 \uacf5\uaca9\ud55c\ub2e4. \uadf8\ub294 \uc778\uac04\uc758 \uc138\uacc4\ub97c \uc6d0\ud558\uc9c0\ub9cc \uadf8 \uc138\uacc4\ub85c \ub4e4\uc5b4\uac08 \ubb38\uc744 \ucc3e\uae30 \uc5b4\ub835\ub2e4. \ub4dc \ub77c\uc138 \uac00\uc871\uc758 \uc0dd\ud65c\uc744 \uc228\uc5b4 \uc9c0\ucf1c\ubcf4\ub294 \ub3d9\uc548 \ub9d0\uacfc \uad00\uacc4\ub97c \ubc30\uc6b4\ub2e4. \ucc45\uc744 \uc77d\uc73c\uba74\uc11c \uc790\uc2e0\uc758 \ucc98\uc9c0\uc640 \uc778\uac04\uc758 \uc5ed\uc0ac\ub97c \uc0dd\uac01\ud558\uac8c\ub3c4 \ub41c\ub2e4. \uc774 \uacfc\uc815\uc5d0\uc11c \ud53c\uc870\ubb3c\uc740 \uc18c\ub9ac\ub9cc \uc9c0\ub974\ub294 \uad34\ubb3c\uc774 \uc544\ub2c8\ub77c \ubc30\uc6b0\uace0 \ube44\uad50\ud558\uba70 \uc790\uae30 \uc0b6\uc758 \uc774\uc720\ub97c \ubb3b\ub294 \uc874\uc7ac\uac00 \ub41c\ub2e4. \ud53c\uc870\ubb3c\uc740 \ub208\uc774 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uac00\uc871\uc758 \ub178\uc778\uc5d0\uac8c \ub2e4\uac00\uac00 \uc790\uc2e0\uc758 \ub9d0\uc744 \ub4e4\uc5b4 \ub2ec\ub77c\uace0 \ud55c\ub2e4. \uc678\ubaa8\ub97c \uba3c\uc800 \ubcf4\uc9c0 \uc54a\ub294 \uc0c1\ub300\uc5d0\uac8c\ub294 \uc774\ud574\ubc1b\uc744 \uc218 \uc788\uc73c\ub9ac\ub77c\ub294 \uae30\ub300\ub2e4. \ud558\uc9c0\ub9cc \ub2e4\ub978 \uac00\uc871\uc774 \ub3cc\uc544\uc624\uba74\uc11c \uc2dc\ub3c4\ub294 \ubb34\ub108\uc9c0\uace0 \uadf8\ub294 \ub2e4\uc2dc \ubc30\ucc99\ub2f9\ud55c\ub2e4. \uc774 \uc7a5\uba74\uc740 \uc678\ubaa8\uc5d0 \ub300\ud55c \ud310\ub2e8\uacfc \ub9d0\uc744 \ub4e4\uc744 \uae30\ud68c\uc758 \uad00\uacc4\ub97c \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ub3d9\uc2dc\uc5d0 \ud53c\uc870\ubb3c\uc774 \ubd88\ud589\ud588\uc73c\ub2c8 \uc774\ud6c4\uc758 \ud3ed\ub825\uc740 \ubaa8\ub450 \uc815\ub2f9\ud558\ub2e4\ub294 \uacb0\ub860\uc73c\ub85c \ub098\uc544\uac00\uc9c0\ub294 \ub9d0\uc790. \uc18c\uc124\uc740 \uadf8\uac00 \uacaa\uc740 \uc0c1\ucc98\ub97c \ub4e4\ub824\uc8fc\uc9c0\ub9cc, \ub2e4\ub978 \uc0dd\uba85\uc744 \ud574\uce58\ub294 \uc120\ud0dd\uc758 \ucc45\uc784\uae4c\uc9c0 \uc5c6\uc560\uc9c0\ub294 \uc54a\ub294\ub2e4. \ube45\ud130\uc758 \uc5b4\ub9b0 \ub3d9\uc0dd \uc70c\ub9ac\uc5c4\uc774 \uc0b4\ud574\ub418\uace0 \uc950\uc2a4\ud2f4\uc774 \ubc94\uc778\uc73c\ub85c \ubab0\ub9b0\ub2e4. \ud53c\uc870\ubb3c\uc758 \ud589\ub3d9\uacfc \ube45\ud130\uc758 \uce68\ubb35\uc740 \uc9c1\uc811 \uc2e4\ud5d8\uc5d0 \ucc38\uc5ec\ud558\uc9c0 \uc54a\uc740 \uc0ac\ub78c\ub4e4\uc758 \uc0b6\uae4c\uc9c0 \ubb34\ub108\ub728\ub9b0\ub2e4. \ube44\ubc00\uc744 \uc9c0\ud0a4\uba74 \ubb38\uc81c\ub97c \uc790\uae30 \uc548\uc5d0 \ubb36\uc5b4 \ub458 \uc218 \uc788\ub2e4\ub294 \uc0dd\uac01\uc740 \ud1b5\ud558\uc9c0 \uc54a\ub294\ub2e4. \ube45\ud130\ub294 \ub450\ub824\uc6c0\uacfc \uc8c4\ucc45\uac10\uc744 \uacaa\uc73c\uba74\uc11c\ub3c4 \uc790\uc2e0\uc758 \uc774\uc57c\uae30\ub97c \uc5b4\ub5bb\uac8c \uc124\uba85\ud560\uc9c0 \ub9dd\uc124\uc778\ub2e4. \uadf8\ub294 \ub2e8\uc21c\ud788 \uc545\ud55c \uacfc\ud559\uc790\ub77c\uae30\ubcf4\ub2e4, \ud558\uace0 \uc2f6\uc740 \uc77c\uc744 \ud560 \ub54c\uc758 \ub300\ub2f4\ud568\uacfc \uacb0\uacfc\ub97c \uac10\ub2f9\ud560 \ub54c\uc758 \uc8fc\uc800\ud568\uc774 \ud06c\uac8c \uc5b4\uae0b\ub098\ub294 \uc778\ubb3c\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \uadf8 \uc5b4\uae0b\ub0a8\uc758 \ub300\uac00\ub294 \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\ub3c4 \uce58\ub978\ub2e4. \ud53c\uc870\ubb3c\uc740 \uc790\uc2e0\uacfc \ud568\uaed8 \uc0b4\uc544\uac08 \uc874\uc7ac\ub97c \ub9cc\ub4e4\uc5b4 \ub2ec\ub77c\uace0 \uc694\uad6c\ud55c\ub2e4. \uc778\uac04\uc5d0\uac8c \ubc1b\uc544\ub4e4\uc5ec\uc9c0\uae30 \uc5b4\ub835\ub2e4\uba74 \uc801\uc5b4\ub3c4 \ud640\ub85c \ub0a8\uc9c0 \uc54a\uac8c \ud574 \ub2ec\ub77c\ub294 \uc694\uccad\uc774\ub2e4. \ube45\ud130\ub294 \uc57d\uc18d\ud558\uace0 \uc791\uc5c5\uc744 \uc2dc\uc791\ud558\uc9c0\ub9cc \uc55e\uc73c\ub85c \uc0dd\uae38 \uc77c\uc744 \ub450\ub824\uc6cc\ud574 \uc644\uc131\ud558\uae30 \uc804\uc5d0 \ud30c\uad34\ud55c\ub2e4. \uc774 \uacb0\uc815\uc740 \uc26c\uc6b4 \uc815\ub2f5\uc73c\ub85c \ub098\ub204\uae30 \uc5b4\ub835\ub2e4. \uc774\ubbf8 \ub9cc\ub4e4\uc5b4\uc9c4 \uc874\uc7ac\uc5d0\uac8c \uc9c0\ub294 \ucc45\uc784\uacfc, \ub610 \ub2e4\ub978 \uc0dd\uba85\uc744 \ub9cc\ub4dc\ub294 \uc77c\uc758 \uc704\ud5d8\uc774 \ucda9\ub3cc\ud55c\ub2e4. \uc18c\uc124\uc740 \ub3c5\uc790\ub97c \uc5f0\uad6c\ub97c \uacc4\uc18d\ud558\ub77c\ub294 \ucabd\uc774\ub098 \ubaa8\ub4e0 \ucc3d\uc870\ub97c \uae08\uc9c0\ud558\ub77c\ub294 \ucabd\uc73c\ub85c \uace7\uc7a5 \ubcf4\ub0b4\uc9c0 \uc54a\uace0, \ucc98\uc74c\uc5d0 \ud53c\ud588\ub358 \uad00\uacc4\uc758 \ubb38\uc81c \uc55e\uc73c\ub85c \ub418\ub3cc\ub824 \ub193\ub294\ub2e4. \uce5c\uad6c \ud074\ub808\ub974\ubc1c\uacfc \ube45\ud130\uc758 \uc2e0\ubd80 \uc5d8\ub9ac\uc790\ubca0\uc2a4\uc5d0\uac8c\ub3c4 \uc8fd\uc74c\uc774 \ub2e5\uce5c\ub2e4. \ube45\ud130\ub294 \ud53c\uc870\ubb3c\uc744 \ucd94\uc801\ud558\uba70 \ub0a8\uc740 \uc0b6\uc744 \ubcf5\uc218\uc5d0 \uac74\ub2e4. \uc790\uc2e0\uc774 \ub9cc\ub4e0 \uc874\uc7ac\ub97c \ud53c\ud558\ub358 \uc0ac\ub78c\uc774 \uc774\uc81c \uadf8 \uc874\uc7ac\ub97c \ucad3\ub294 \uc77c\ub9cc\uc744 \uc0b6\uc758 \ubaa9\uc801\uc73c\ub85c \uc0bc\ub294\ub2e4. \ub458\uc758 \uad00\uacc4\ub294 \ub04a\uc5b4\uc9c0\uc9c0 \uc54a\uace0 \ub354 \ud30c\uad34\uc801\uc778 \ubc29\uc2dd\uc73c\ub85c \ubd99\uc7a1\ud78c\ub2e4. \uc5bc\uc74c\ubc14\ub2e4\uc5d0\uc11c \ube45\ud130\ub294 \uc6d4\ud134\uc5d0\uac8c \uc774\uc57c\uae30\ub97c \ub05d\ub0b4\uace0 \uc8fd\ub294\ub2e4. \ub9c8\uc9c0\ub9c9\uc5d0 \ud53c\uc870\ubb3c\uc774 \ub098\ud0c0\ub098 \uc790\uae30 \ud589\ub3d9\uc744 \ub3cc\uc544\ubcf4\uace0 \uc790\uc2e0\uc758 \uc0b6\ub3c4 \ub05d\ub0b4\uaca0\ub2e4\ub294 \ub73b\uc744 \ub9d0\ud55c \ub4a4 \uc0ac\ub77c\uc9c4\ub2e4. \ub3c5\uc790\uac00 \uadf8 \ub4a4\uc758 \uc2e4\ud589\uae4c\uc9c0 \uc9c1\uc811 \ubcf4\uc9c0\ub294 \uc54a\ub294\ub2e4. \uacb0\ub9d0\uc740 \uc2b9\ub9ac\ud55c \uc601\uc6c5\ubcf4\ub2e4 \ud669\ud3d0\ud574\uc9c4 \uad00\uacc4\ub97c \ub0a8\uae34\ub2e4. \uc6d4\ud134\uc5d0\uac8c\ub3c4 \ub0a8\ub4e4\uc774 \ub118\uc9c0 \ubabb\ud55c \uacbd\uacc4\ub97c \ub118\uace0 \uc2f6\ub2e4\ub294 \uc57c\ub9dd\uc774 \uc788\ub2e4. \uadf8\ub798\uc11c \ube45\ud130\uc758 \uc774\uc57c\uae30\ub97c \ub4e3\ub294 \uadf8\uc758 \uc704\uce58\uac00 \uc911\uc694\ud558\ub2e4. \ub204\uad70\uac00\uc758 \ube44\uadf9\uc744 \uc54c\uace0 \ub098\uc11c\ub3c4 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ub2e4\ub978 \uc0ac\ub78c\uc744 \uc704\ud5d8\uc5d0 \ubc00\uc5b4 \ub123\uc744 \uac83\uc778\uac00. \ud0d0\ud5d8\uc5d0 \ub3d9\ud589\ud55c \uc0ac\ub78c\ub4e4\uc758 \uc0b6\ub3c4 \uace0\ub824\ud574\uc57c \ud55c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \ud53c\uc870\ubb3c\uc758 \ubc30\uc6c0\uacfc \uace0\ub9bd\uc774\ub77c\ub294 \uc815\uc11c\ub97c \uc0c1\uc0c1\ud55c AI \uc0bd\ud654\ub2e4. \ud2b9\uc815 \uc7a5\uba74\uc744 \uc815\ud655\ud788 \ubcf5\uc6d0\ud558\uac70\ub098 \uc601\ud654 \uc18d \uc678\ud615\uc744 \uc62e\uae34 \uadf8\ub9bc\uc740 \uc544\ub2c8\ub2e4. \ub204\uad6c\uc758 \ub9d0\uc774 \ub204\uad6c\ub97c \uac70\uccd0 \ub3c5\uc790\uc5d0\uac8c \uc624\ub294\uc9c0 \ud655\uc778\ud558\uace0 \uc77d\uc73c\uba74, \ube45\ud130\uc758 \ud6c4\ud68c\uc640 \ud53c\uc870\ubb3c\uc758 \ud56d\ubcc0\uc774 \uac01\uac01 \ubb34\uc5c7\uc744 \uac15\uc870\ud558\uace0 \ube44\uc6cc \ub450\ub294\uc9c0\ub3c4 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \u300e\ud504\ub791\ucf04\uc288\ud0c0\uc778\u300f\uc744 \uacfc\ud559\uc740 \uc704\ud5d8\ud558\ub2e4\ub294 \ud55c \uc904\uc758 \uacbd\uace0\ub85c\ub9cc \uc77d\uc73c\uba74 \ub9ce\uc740 \ubd80\ubd84\uc774 \ube60\uc9c4\ub2e4. \uc9c0\uc2dd\uc5d0 \ub300\ud55c \uc5f4\ub9dd, \ub3cc\ubd04\uc744 \ubc1b\uc9c0 \ubabb\ud55c \uc0b6, \uc678\ubaa8\uc5d0 \ub300\ud55c \ud310\ub2e8, \uacb0\uacfc\ub97c \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ub5a0\ub118\uae30\ub294 \ud0dc\ub3c4\uac00 \ud568\uaed8 \ub4e4\uc5b4 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc5b4\ub290 \ud55c\ucabd\uc758 \uace0\ud1b5\uc744 \uc774\ud574\ud558\ub294 \uac83\uacfc \uadf8 \ud589\ub3d9\uc744 \ubaa8\ub450 \ud5c8\uc6a9\ud558\ub294 \uac83\ub3c4 \ub2e4\ub978 \uc77c\uc774\ub2e4. \ubb34\uc5c7\uc744 \uc0c8\ub85c \ub9cc\ub4e4\uc5c8\uc744 \ub54c \uc131\uacf5\uc758 \uc21c\uac04\ub9cc\uc774 \uc544\ub2c8\ub77c \uadf8 \ub4a4\uc758 \uad00\uacc4\uae4c\uc9c0 \uc0c1\uc0c1\ud560 \uc218 \uc788\uc744\uae4c. \uc774 \uc9c8\ubb38\uc740 \uc2e4\ud5d8\uc2e4 \ubc16\uc5d0\uc11c\ub3c4 \uc720\ud6a8\ud558\ub2e4. \uc624\ub798\ub41c \uad34\ubb3c\uc758 \uc5bc\uad74\uc744 \ud655\uc778\ud558\uae30\ubcf4\ub2e4, \uc11c\ub85c\uc758 \uc774\uc57c\uae30\ub97c \ub4e3\uc9c0 \ubabb\ud55c \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5bb\uac8c \ube44\uadf9\uc744 \ud0a4\uc6e0\ub294\uc9c0 \ub530\ub77c\uac00 \ubcf4\uba74 \uc791\ud488\uc740 \ud6e8\uc52c \ub113\uc5b4\uc9c4\ub2e4."}, {"id": "freischutz-wolfs-glen-and-final-shot", "title": "\ub9c8\ud0c4\uc758 \uc0ac\uc218 \u2014 \ub9c8\uc9c0\ub9c9 \ud0c4\ud658\uc740 \ub204\uad6c\uc758 \ub73b\ub300\ub85c \ub0a0\uc544\uac08\uae4c", "summary": "\ub9c9\uc2a4\uc758 \uc0ac\uaca9 \uc2dc\ud5d8\uacfc \ub9c8\ud0c4, \uc544\uac00\ud14c\uc640 \uc740\uc790\uc758 \uc911\uc7ac\ub97c \uc74c\uc545\uc758 \uc7a5\uba74\uacfc \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc74c\uc545", "categories": ["arts"], "url": "stories/freischutz-wolfs-glen-and-final-shot/index.html", "image": "../media/freischutz-wolfs-glen-and-final-shot.png", "alt": "\uc5b4\ub450\uc6b4 \uc232\uc18d \uace8\uc9dc\uae30\uc5d0\uc11c \ub9c8\ud0c4\uc744 \ub9cc\ub4dc\ub294 \uc0ac\ub0e5\uafbc\ub4e4\uc744 \uadf8\ub9b0 \uc624\ud398\ub77c \uad00\ub828 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ub9c8\ud0c4\uc758 \uc0ac\uc218 \u2014 \ub9c8\uc9c0\ub9c9 \ud0c4\ud658\uc740 \ub204\uad6c\uc758 \ub73b\ub300\ub85c \ub0a0\uc544\uac08\uae4c \uc11c\uace1\uc758 \ud638\ub978\uacfc \ub291\ub300 \uace8\uc9dc\uae30, \uba85\uc911\uc758 \uc57d\uc18d\uacfc \uc77c \ub144\uc758 \uc720\uc608 \ub9c9\uc2a4\uc758 \uc0ac\uaca9 \uc2dc\ud5d8\uacfc \ub9c8\ud0c4, \uc544\uac00\ud14c\uc640 \uc740\uc790\uc758 \uc911\uc7ac\ub97c \uc74c\uc545\uc758 \uc7a5\uba74\uacfc \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc74c\uc545 \ubb38\ud654\uc640 \uc608\uc220 \ubca0\ubc84\uc758 \uc624\ud398\ub77c \u300e\ub9c8\ud0c4\uc758 \uc0ac\uc218\u300f\uc5d0\uc11c \uc232\uc740 \uc0b0\ucc45\ud558\uae30 \uc88b\uc740 \ubc30\uacbd\ub9cc\uc774 \uc544\ub2c8\ub2e4. \ub0ae\uc5d0\ub294 \uc0ac\ub0e5\uacfc \uacf5\ub3d9\uccb4\uc758 \uacf5\uac04\uc774\uc9c0\ub9cc \ubc24\uc5d0\ub294 \ubd88\uc548\uacfc \uc720\ud639\uc774 \ubaa8\uc2b5\uc744 \uc5bb\ub294\ub2e4. 1821\ub144 \ubca0\ub97c\ub9b0\uc5d0\uc11c \ucd08\uc5f0\ud55c \uc774 \ub3c5\uc77c\uc5b4 \uc624\ud398\ub77c\ub294 \uba85\uc911\ud558\ub294 \ud0c4\ud658\uc744 \uc5bb\uc740 \uccad\ub144\uc774 \ubb34\uc5c7\uc744 \uc783\uc744 \ubed4\ud558\ub294\uc9c0 \ub178\ub798\uc640 \uad00\ud604\uc545\uc73c\ub85c \ubcf4\uc5ec \uc900\ub2e4. \uc80a\uc740 \uc0ac\ub0e5\uafbc \ub9c9\uc2a4\ub294 \uc0ac\uaca9 \uc2dc\ud5d8\uc744 \uc55e\ub450\uace0 \uc788\ub2e4. \uc2e4\ub825\uc744 \uc99d\uba85\ud574\uc57c \uc55e\ub0a0\uc758 \uc790\ub9ac\ub3c4, \ucfe0\ub178\uc758 \ub538 \uc544\uac00\ud14c\uc640\uc758 \uacb0\ud63c\ub3c4 \uc21c\uc870\ub85c\uc6b8 \uc218 \uc788\ub2e4. \uadf8\ub7f0\ub370 \uc5f0\uc2b5\uc5d0\uc11c \uc790\uafb8 \uc2e4\ud328\ud55c\ub2e4. \uc0ac\ub78c\ub4e4\uc758 \uc2dc\uc120\uacfc \uc870\ub871\uc740 \uadf8\uc5d0\uac8c \ub2e8\uc21c\ud55c \uc2e4\uc218\ubcf4\ub2e4 \ud070 \uc555\ubc15\uc73c\ub85c \ub2e4\uac00\uc628\ub2e4. \uc545\ud55c \ub9c8\uc74c\uc744 \uac00\uc9c4 \uce74\uc2a4\ud30c\ub974\ub294 \uadf8 \ubd88\uc548\uc744 \uc774\uc6a9\ud55c\ub2e4. \uc790\uc2e0\uc744 \uc5b4\ub460\uc758 \ud798\uc5d0 \ub300\uc2e0 \ub118\uae38 \uc0ac\ub78c\uc73c\ub85c \ub9c9\uc2a4\ub97c \ub04c\uc5b4\ub4e4\uc774\ub824\ub294 \uac83\uc774\ub2e4. \ubbfc\uac04 \uc804\uc124 \uac19\uc740 \uc904\uac70\ub9ac\uc774\uc9c0\ub9cc, \ud55c \ubc88\uc758 \uc131\uacfc\ub85c \uc778\uc0dd\uc744 \ud310\uc815\ud558\ub294 \uc0c1\ud669\uc774 \uc9c0\ub984\uae38\uc758 \uc720\ud639\uc744 \ud0a4\uc6b4\ub2e4\ub294 \uc810\uc740 \ub0af\uc124\uc9c0 \uc54a\ub2e4. \uce74\uc2a4\ud30c\ub974\uac00 \ub0b4\ubbf8\ub294 \ud574\uacb0\ucc45\uc740 \ubc18\ub4dc\uc2dc \ud45c\uc801\uc744 \ub9de\ud788\ub294 \ub9c8\ubc95\uc758 \ud0c4\ud658\uc774\ub2e4. \uc6d0\uc81c\uc758 \uc0ac\uc218\ub294 \uc774\ub7f0 \ucd08\uc790\uc5f0\uc801 \ub3c4\uc6c0\uc744 \ubc1b\ub294 \uba85\uc0ac\uc218\uc640 \uc5f0\uacb0\ub41c\ub2e4. \ud55c\uad6d\uc5b4 \uc81c\ubaa9\uc758 \ub9c8\ud0c4\uc740 \uc2e0\ube44\ud55c \ud798\uc744 \uc555\ucd95\ud558\uc9c0\ub9cc, \uadf8 \ud798\uc774 \ubaa8\ub450 \uc0ac\uc6a9\uc790\uc758 \uc758\uc9c0\uc5d0 \ubcf5\uc885\ud55c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub9c8\ubc95\uc73c\ub85c \ub9cc\ub4e0 \uc77c\uacf1 \ubc1c \uac00\uc6b4\ub370 \ub9c8\uc9c0\ub9c9 \ud55c \ubc1c\uc740 \uc545\ub9c8 \uc790\ubbf8\uc5d8\uc758 \ubaab\uc774\ub2e4. \ub9c9\uc2a4\uac00 \uc6d0\ud558\ub294 \uac83\uc740 \uc2e4\ud328\ud558\uc9c0 \uc54a\ub294 \ud655\uc2e4\ud568\uc774\uc9c0\ub9cc, \uadf8 \ud655\uc2e4\ud568\uc744 \uc5bb\ub294 \uacc4\uc57d \uc548\uc5d0 \uc790\uae30 \ub73b\ub300\ub85c \ud560 \uc218 \uc5c6\ub294 \ubd80\ubd84\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uc791\ud488\uc758 \uae34\uc7a5\uc740 \ubc14\ub85c \uadf8 \ubaa8\uc21c\uc5d0\uc11c \ub098\uc628\ub2e4. \uacf5\uc5f0\uc5d0\uc11c\ub294 \ub178\ub798 \uc0ac\uc774\uc758 \ub300\uc0ac\ub3c4 \uc0ac\uac74\uc744 \uc774\uc5b4 \uc900\ub2e4. \uc74c\uc545\uc774 \uc544\ub984\ub2e4\uc6b4 \ub3c5\ub9bd \uace1\ub4e4\ub9cc\uc73c\ub85c \ub193\uc774\uc9c0 \uc54a\uace0 \ub9d0\uacfc \ubb34\ub300 \ud589\ub3d9 \uc18d\uc5d0\uc11c \uc758\ubbf8\ub97c \uc5bb\ub294\ub2e4\ub294 \ub73b\uc774\ub2e4. \ub300\ud45c \uc544\ub9ac\uc544\ub97c \ub4e4\uc740 \ub4a4 \ud55c \ub9c9 \uc804\uccb4\ub97c \ubcf4\uba74 \uac19\uc740 \uc120\uc728\uc774 \ub2e4\ub978 \uae34\uc7a5\uc744 \uac16\uac8c \ub41c\ub2e4. \ub9c9\uc2a4\uac00 \uc870\uae09\ud558\uac8c \ud574\uacb0\ucc45\uc744 \ucc3e\ub294 \ub3d9\uc548 \uc544\uac00\ud14c\ub294 \uc9d1\uc5d0\uc11c \ubd88\uae38\ud55c \uc9d5\uc870\uc640 \ubd88\uc548\uc744 \ub290\ub080\ub2e4. \ud568\uaed8 \uc788\ub294 \uc5d4\ud5e8\uc758 \ub9d0\uacfc \ub178\ub798\ub294 \ubb34\uac70\uc6b4 \ubd84\uc704\uae30\uc5d0 \uc0dd\uae30\uc640 \uc77c\uc0c1\uc758 \uac10\uac01\uc744 \ub354\ud55c\ub2e4. \uc5ec\uc131 \uc778\ubb3c\ub4e4\uc774 \ubaa8\ub450 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uacf5\ud3ec\ub97c \ud45c\ud604\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\ub3c4 \ub4e4\uc744 \ub9cc\ud558\ub2e4. \uc544\uac00\ud14c\uc758 \uae34 \ub178\ub798\uc5d0\uc11c\ub294 \uae30\ub2e4\ub9bc\uc774 \uc74c\uc545\uc758 \uc2dc\uac04\uc774 \ub41c\ub2e4. \ub9c9\uc2a4\uc758 \ub2e4\uc74c \ud589\ub3d9\uc744 \uc124\uba85\ud558\ub294 \uc815\ubcf4\ub9cc \uc804\ub2ec\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \ubbff\uace0 \uc2f6\uc740 \ub9c8\uc74c\uacfc \uc5fc\ub824\uac00 \ubc88\uac08\uc544 \ub4dc\ub7ec\ub09c\ub2e4. \uc232\uc758 \uc0ac\uac74\uacfc \ubc29 \uc548\uc758 \uae30\ub3c4\uac00 \uc11c\ub85c \ub2e4\ub978 \uc18c\ub9ac\uc758 \uc138\uacc4\ub97c \ub9cc\ub4e0\ub2e4. \ubc24\uc911\uc5d0 \ub450 \uc0ac\ub78c\uc774 \ub9cc\ub098\ub294 \ub291\ub300\uc758 \uace8\uc9dc\uae30\ub294 \uc774 \uc624\ud398\ub77c\uc758 \uc911\uc2ec \uc7a5\uba74\uc774\ub2e4. \ud0c4\ud658\uc744 \ub9cc\ub4e4\uc218\ub85d \uae30\uad34\ud55c \uc18c\ub9ac\uc640 \ud658\uc601\uc774 \uac15\ud574\uc9c0\uace0, \ubb34\ub300\ub294 \uc548\uc804\ud55c \ub9c8\uc744\uc5d0\uc11c \uba40\uc5b4\uc9c4\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc608\uc05c \uc120\uc728 \ud558\ub098\ub97c \ub5bc\uc5b4 \ub4e3\ub294 \uac83\ub9cc\uc73c\ub85c \uc7a5\uba74\uc758 \ud798\uc744 \uc54c\uae30 \uc5b4\ub835\ub2e4. \uc5b4\ub450\uc6b4 \uc74c\uc0c9\uacfc \uae09\uaca9\ud55c \ubcc0\ud654, \ubaa9\uc18c\ub9ac\uc640 \uad00\ud604\uc545\uc758 \ucda9\ub3cc\uc744 \ud568\uaed8 \ub4e4\uc5b4\uc57c \ud55c\ub2e4. \ud0c4\ud658\uc744 \uc138\ub294 \uc9c4\ud589 \uc790\uccb4\uac00 \uc55e\uc73c\ub85c \ub2e5\uce60 \uc77c\uc744 \uae30\ub2e4\ub9ac\uac8c \ub9cc\ub4e0\ub2e4. \ub208\uc73c\ub85c \ubcf4\ub294 \uc7a5\uce58\ubfd0 \uc544\ub2c8\ub77c \uc18c\ub9ac\uc758 \ubc00\ub3c4\uc640 \ubc18\ubcf5\uc774 \uad00\uac1d\uc5d0\uac8c \uc704\ud5d8\uc744 \ub290\ub07c\uac8c \ud558\ub294 \uac83\uc774\ub2e4. \uace8\uc9dc\uae30\ub294 \ub2e8\uc21c\ud55c \uc545\ub2f9\uc758 \uac70\ucc98\ub9cc\uc740 \uc544\ub2c8\ub2e4. \ub9c9\uc2a4\ub294 \ub450\ub824\uc6c0\uc744 \ub290\ub07c\uba74\uc11c\ub3c4 \uc9c1\uc811 \uadf8\uacf3\uc73c\ub85c \uac78\uc5b4 \ub4e4\uc5b4\uac04\ub2e4. \ubb34\uc11c\uc6b4 \ud658\uacbd\uc774 \uc8fc\uc778\uacf5\uc758 \uc758\uc9c0\ub97c \uc644\uc804\ud788 \uc5c6\uc560 \ubc84\ub9ac\uae30\ubcf4\ub2e4, \uc5b4\ub5a4 \uacb0\uc815\uc744 \ub0b4\ub9ac\uace0 \uc788\ub294\uc9c0 \uad00\uac1d\uc5d0\uac8c \uacc4\uc18d \uc758\uc2dd\ud558\uac8c \ud55c\ub2e4. \uc11c\uace1 \uc55e\ubd80\ubd84\uc758 \ud638\ub978\uc740 \uc232\uacfc \uc0ac\ub0e5\uc758 \uc138\uacc4\ub97c \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc74c\uc545\uc774 \uacc4\uc18d \uac19\uc740 \ud3c9\uc628\ud568\uc5d0 \uba38\ubb3c\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5b4\ub461\uace0 \ubd88\uc548\ud55c \uc6c0\uc9c1\uc784\uc744 \uac70\uce58\uace0 \ub2e4\ub978 \uc815\uc11c\ub85c \ub098\uc544\uac00\uba74\uc11c, \ubcf8 \uacf5\uc5f0\uc5d0\uc11c \ubd80\ub52a\uce60 \uc138\uacc4\ub97c \ubbf8\ub9ac \uc555\ucd95\ud55c\ub2e4. \ucc98\uc74c \ub4e3\ub294\ub2e4\uba74 \uc545\uae30\uc758 \uc774\ub984\uc744 \ubaa8\ub450 \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc11c\uace1\uc758 \uc548\uc815\uac10\uc774 \uc5b8\uc81c \ud754\ub4e4\ub9ac\ub294\uc9c0 \uadc0 \uae30\uc6b8\uc5ec \ubcf4\uc790. \ubb34\uc11c\uc6b4 \uace8\uc9dc\uae30\uc758 \uc74c\uc545\uc744 \ub4e4\uc740 \ub4a4 \uc11c\uace1\uc744 \ub2e4\uc2dc \ub4e4\uc73c\uba74, \ucc98\uc74c\uc5d0\ub294 \ud48d\uacbd\ucc98\ub7fc \ub4e4\ub9ac\ub358 \uc18c\ub9ac \uc18d\uc5d0 \uc774\uc57c\uae30\uc758 \uac08\ub4f1\uc774 \uc774\ubbf8 \ub4e4\uc5b4 \uc788\uc5c8\uc74c\uc744 \ub290\ub084 \uc218 \uc788\ub2e4. \uacb0\ub9d0\uc758 \uc2dc\ud5d8\uc5d0\uc11c \ub9c9\uc2a4\ub294 \ube44\ub458\uae30\ub97c \ud5a5\ud574 \uc3d8\ub77c\ub294 \uba85\ub839\uc744 \ubc1b\ub294\ub2e4. \uc544\uac00\ud14c\ub294 \uc790\uc2e0\uc774 \ube44\ub458\uae30\uac00 \ub418\uc5b4 \ucd1d\uc5d0 \ub9de\ub294 \uafc8\uc744 \uafb8\uc5c8\uace0, \ud63c\ub840\ub97c \uc55e\ub454 \uc900\ube44\uc5d0\ub3c4 \uc8fd\uc74c\uc758 \uc9d5\uc870\uac00 \ub07c\uc5b4\ub4e4\uc5c8\ub2e4. \ub9c8\uc9c0\ub9c9 \ud0c4\ud658\uc774 \ub0a0\uc544\uac08 \ub54c \uadf8 \ubd88\uc548\uc774 \ud604\uc2e4\uc774 \ub418\ub294 \ub4ef \ubcf4\uc778\ub2e4. \uc544\uac00\ud14c\ub294 \uc4f0\ub7ec\uc9c0\uc9c0\ub9cc \uc0b4\uc544\ub0a8\uace0 \uce74\uc2a4\ud30c\ub974\uac00 \uc8fd\ub294\ub2e4. \uc131\uc2a4\ub7ec\uc6b4 \uc7a5\ubbf8 \ud654\ud658\uacfc \uc740\uc790\uc758 \uc874\uc7ac\uac00 \uad6c\uc6d0\uc758 \ub9e5\ub77d\uc744 \ub9cc\ub4e0\ub2e4. \ub9c8\ubc95\uc758 \ucd1d\uc54c\uc774 \ub2e8\uc21c\ud788 \uc0ac\uaca9 \uae30\uc220\uc758 \ube48\ud2c8\uc744 \uba54\uc6cc \uc900 \uac83\uc774 \uc544\ub2c8\ub77c, \uacf5\ub3d9\uccb4 \uc804\uccb4\ub97c \ud30c\uad6d \uac00\uae4c\uc774 \ub04c\uace0 \uac14\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \ub9c8\uc744\uc758 \ud569\ucc3d\uacfc \uc232\uc758 \uc74c\uc0c9\uc744 \ub098\ub780\ud788 \ub4e4\uc73c\uba74 \uac1c\uc778\uc758 \uc120\ud0dd\uc774 \uacf5\ub3d9\uccb4 \uc548\uc5d0\uc11c \uc77c\uc5b4\ub09c\ub2e4\ub294 \uc810\ub3c4 \ub4dc\ub7ec\ub09c\ub2e4. \ub9c9\uc2a4\uc758 \ubd88\uc548\uc740 \ud63c\uc790\ub9cc\uc758 \uc131\uaca9\uc774 \uc544\ub2c8\ub77c \uc8fc\ubcc0\uc758 \ud3c9\uac00\uc640 \uad00\uc2b5 \uc18d\uc5d0\uc11c \ucee4\uc84c\ub2e4. \ub9c8\uc9c0\ub9c9\uc758 \uc6a9\uc11c \uc5ed\uc2dc \uacf5\ub3d9\uccb4\uac00 \ucc38\uc5ec\ud558\ub294 \uacb0\uc815\uc774\ub2e4. \ub9c9\uc2a4\ub294 \uc790\uc2e0\uc758 \uc798\ubabb\uc744 \uace0\ubc31\ud558\uace0 \ucd94\ubc29\ub2f9\ud560 \uc704\uae30\uc5d0 \ub193\uc778\ub2e4. \uc740\uc790\ub294 \uc911\uc7ac\ud558\uba70 \ub2e8 \ud55c \ubc88\uc758 \uc0ac\uaca9\uc73c\ub85c \uc0ac\ub78c\uc758 \uc55e\ub0a0\uc744 \uc7ac\ub2e8\ud558\ub294 \uad00\uc2b5\uc5d0\ub3c4 \ubb38\uc81c\ub97c \uc81c\uae30\ud55c\ub2e4. \ub9c9\uc2a4\uc5d0\uac8c\ub294 \uc77c \ub144\uc758 \uc2dc\ud5d8 \uae30\uac04\uc774 \uc8fc\uc5b4\uc9c0\uace0, \uadf8 \ub4a4 \uacb0\ud63c\uacfc \uc790\ub9ac\ub97c \uc5bb\uc744 \uae38\uc774 \uc5f4\ub9b0\ub2e4. \ub530\ub77c\uc11c \uacb0\ub9d0\uc740 \uc88b\uc740 \ud0c4\ud658 \ub355\ubd84\uc5d0 \uc131\uacf5\ud588\ub2e4\ub294 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \ucc45\uc784\uc744 \uc778\uc815\ud558\uace0 \ub2e4\uc2dc \uc0b4\uc544 \ubcfc \uc2dc\uac04\uc744 \uc5bb\ub294 \uc774\uc57c\uae30\ub2e4. \u300e\ub9c8\ud0c4\uc758 \uc0ac\uc218\u300f\ub294 \ubcf4\ud5e4\ubbf8\uc544\uc758 \uc232\uc744 \ubb34\ub300\ub85c \uc0bc\uc9c0\ub9cc, \ubca0\ubc84\uc758 \ub3c5\uc77c\uc5b4 \uc624\ud398\ub77c\uc640 \ub0ad\ub9cc\uc8fc\uc758 \uc74c\uc545\uc744 \uc77d\ub294 \ub9e5\ub77d\uc5d0\uc11c \ub3c5\uc77c\uc5d0 \ubc30\uce58\ud588\ub2e4. \uc61b \uc624\ud398\ub77c \uc694\uc57d \uc911\uc5d0\ub294 \ub9c8\uc9c0\ub9c9\uc744 \uace7\ubc14\ub85c \uacb0\ud63c\uc758 \uae30\uc068\uc73c\ub85c \uc904\uc5ec \uc4f0\ub294 \uacbd\uc6b0\ub3c4 \uc788\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc740\uc790\uc758 \uc911\uc7ac\uc640 \uc77c \ub144\uc758 \uc720\uc608\ub97c \ud3ec\ud568\ud588\ub2e4. \ub05d\uc744 \uc5b4\ub5bb\uac8c \uc124\uba85\ud558\ub290\ub0d0\uc5d0 \ub530\ub77c \uc791\ud488\uc774 \uc131\uacf5\uc758 \ucd95\uc81c\uac00 \ub420 \uc218\ub3c4, \uc131\uae09\ud55c \ud310\uc815\uc744 \ub3cc\uc544\ubcf4\ub294 \uc774\uc57c\uae30\uac00 \ub420 \uc218\ub3c4 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4."}, {"id": "fur-elise-title-and-theme", "title": "\uc5d8\ub9ac\uc81c\ub97c \uc704\ud558\uc5ec \u2014 \uc775\uc219\ud55c \uc120\uc728 \uc55e\uc5d0 \ub0a8\uc740 \uc774\ub984", "summary": "\ubca0\ud1a0\ubca4\uc758 \uc791\uc740 \ud53c\uc544\ub178\uace1\uc744 \uc120\uc728\uacfc \ud45c\uc81c\uc5d0\uc11c \uc2dc\uc791\ud574 \ub4e4\uc5b4 \ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc74c\uc545", "categories": ["arts"], "url": "stories/fur-elise-title-and-theme/index.html", "image": "../media/fur-elise-title-and-theme-scene-20261030.png", "alt": "\ubd80\ub4dc\ub7ec\uc6b4 \ucc3d\uac00 \ube5b\uc774 \ub4dc\ub294 \ubc29\uc5d0 \uc61b \ud53c\uc544\ub178\uc640 \uc758\uc790\uac00 \ub193\uc778 \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\uc5d8\ub9ac\uc81c\ub97c \uc704\ud558\uc5ec \u2014 \uc775\uc219\ud55c \uc120\uc728 \uc55e\uc5d0 \ub0a8\uc740 \uc774\ub984 \uc81c\ubaa9\uc774 \ub9d0\ud574 \uc8fc\ub294 \uac83\uacfc \ub9d0\ud574 \uc8fc\uc9c0 \uc54a\ub294 \uac83 \ubca0\ud1a0\ubca4\uc758 \uc791\uc740 \ud53c\uc544\ub178\uace1\uc744 \uc120\uc728\uacfc \ud45c\uc81c\uc5d0\uc11c \uc2dc\uc791\ud574 \ub4e4\uc5b4 \ubd05\ub2c8\ub2e4. \uc74c\uc545 \ubb38\ud654\uc640 \uc608\uc220 \ubbf8, \ub808 \uc0f5, \ubbf8, \ub808 \uc0f5. \uc9e7\uc740 \uc2dc\uc791\ub9cc\uc73c\ub85c \uace1\uc744 \uc54c\uc544\ub4e3\ub294 \uc0ac\ub78c\uc774 \ub9ce\ub2e4. \ubca0\ud1a0\ubca4\uc758 \u3008\uc5d8\ub9ac\uc81c\ub97c \uc704\ud558\uc5ec\u3009\ub294 \ud53c\uc544\ub178\ub97c \ubc30\uc6b0\ub358 \uae30\uc5b5\uc774\ub098 \uc77c\uc0c1\uc5d0\uc11c \ud758\ub7ec\ub098\uc624\ub358 \uc18c\ub9ac\uc640 \ud568\uaed8 \uc775\uc219\ud574\uc9c4 \uc791\ud488\uc774\ub2e4. \uadf8\ub7f0\ub370 \ucc98\uc74c\uc758 \uba87 \uc74c\uc744 \uc548\ub2e4\ub294 \uac83\uacfc \uace1 \uc804\uccb4\ub97c \ub4e4\uc5b4 \ubcf4\uc558\ub2e4\ub294 \uac83\uc740 \uc870\uae08 \ub2e4\ub974\ub2e4. \uc774 \uc791\ud488\uc744 \ub450 \uac1c\uc758 \uae38\ub85c \ub9cc\ub098 \ubcf4\uc790. \uba3c\uc800 \uc81c\ubaa9\uc774 \ubb34\uc5c7\uc744 \uc54c\ub824 \uc8fc\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uace0, \ub2e4\uc74c\uc5d0\ub294 \uc775\uc219\ud55c \uc120\uc728\uc774 \ub0af\uc120 \uad6c\uac04\uc744 \uc9c0\ub098 \uc5b4\ub5bb\uac8c \ub3cc\uc544\uc624\ub294\uc9c0 \ub4e4\uc5b4 \ubcf4\ub294 \uac83\uc774\ub2e4. \uc545\ubcf4\ub97c \uc77d\uc9c0 \ubabb\ud574\ub3c4 \ub530\ub77c\uac08 \uc218 \uc788\ub2e4. \ub3c5\uc77c\uc5b4 F\u00fcr Elise\ub294 \u2018\uc5d8\ub9ac\uc81c\ub97c \uc704\ud558\uc5ec\u2019\ub77c\ub294 \ub73b\uc774\ub2e4. \ub204\uad70\uac00\ub97c \ud5a5\ud55c \ud45c\uc81c\uac00 \ubd99\uc5b4 \uc788\uc73c\ub2c8 \uc774\ub984\uc758 \uc8fc\uc778\uc774 \uad81\uae08\ud574\uc9c0\ub294 \uac83\uc740 \uc790\uc5f0\uc2a4\ub7fd\ub2e4. \uadf8\ub7ec\ub098 \uc81c\ubaa9 \ud558\ub098\uac00 \uadf8 \uc0ac\ub78c\uc758 \uc2e0\uc6d0\uacfc \uc791\uace1\uac00\uc758 \uc5f0\uc560\uc0ac\ub97c \uc804\ubd80 \uc99d\uba85\ud574 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc774\ubc88\uc5d0 \ub300\uc870\ud55c \uc545\ubcf4\ub294 \uc774 \uace1\uc744 \ubca0\ud1a0\ubca4\uc758 \ud53c\uc544\ub178\uace1, \uac00\ub2e8\uc870, WoO 59\ub85c \uc81c\uc2dc\ud558\uace0 1810\ub144\uc744 \ud45c\uae30\ud55c\ub2e4. \ubc18\uba74 \uc5d8\ub9ac\uc81c\uc758 \uc2e0\uc6d0\uc774\ub098 \ud5cc\uc815\uc758 \uacbd\uc704\ub97c \uc124\uba85\ud558\ub294 \uadfc\uac70\ub294 \uc81c\uacf5\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub530\ub77c\uc11c \uc5ec\uae30\uc11c\ub294 \ud2b9\uc815 \uc778\ubb3c\uc744 \uc8fc\uc778\uacf5\uc73c\ub85c \ud55c \uace0\ubc31 \uc774\uc57c\uae30\ub97c \ud655\uc815\ud574\uc11c \ub4e4\ub824\uc8fc\uc9c0 \uc54a\ub294\ub2e4. \uc81c\ubaa9\uc758 \ub73b\uc740 \ubd84\uba85\ud788 \uc124\uba85\ud558\ub418, \uc0ac\uc5f0\uc744 \ud655\uc778\ud558\uc9c0 \ubabb\ud55c \uacf3\uc740 \ub0a8\uaca8 \ub450\ub294 \ud3b8\uc774 \uc791\ud488\uc744 \uc774\ud574\ud558\ub294 \ub370\ub3c4 \uc815\uc9c1\ud558\ub2e4. \ud074\ub798\uc2dd \uace1\uc5d0\ub294 \uc791\ud488\ubc88\ud638\uac00 \ubd99\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4. \uc774 \uace1\uc758 WoO\ub294 \ub3c5\uc77c\uc5b4 \u2018\uc791\ud488\ubc88\ud638 \uc5c6\ub294 \uc791\ud488\ub4e4\u2019\uc774\ub77c\ub294 \ubd84\ub958\ub97c \uc904\uc778 \ud45c\uae30\ub2e4. \ubca0\ud1a0\ubca4\uc758 \uc74c\uc545\uc744 \uc815\ub9ac\ud558\ub294 \ubaa9\ub85d \uc548\uc5d0\uc11c \uc774 \uace1\uc744 \ucc3e\uac8c \ud574 \uc8fc\ub294 \uc8fc\uc18c\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \ub41c\ub2e4. \uc22b\uc790\uac00 \uc791\ub2e4\uace0 \ucd08\ubcf4\uc790\uc6a9\uc774\ub77c\ub294 \ub73b\ub3c4, 59\ubc88\uc9f8\ub85c \uc791\uace1\ud588\ub2e4\ub294 \ub73b\ub3c4 \uc544\ub2c8\ub2e4. \uac19\uc740 \uc81c\ubaa9\uc758 \ud3b8\uace1\uacfc \uc9e7\uac8c \uc798\ub77c \ub0b8 \uc74c\uc6d0\uc774 \ub9ce\uc744 \ub54c \u2018\ubca0\ud1a0\ubca4, WoO 59, \ud53c\uc544\ub178 \ub3c5\uc8fc\u2019\ub97c \ud568\uaed8 \ud655\uc778\ud558\uba74 \uc5b4\ub5a4 \uace1\uc778\uc9c0 \uad6c\ubd84\ud558\uae30 \uc27d\ub2e4. \uc5ec\uae30\uc11c \uc77d\uc740 \uac83\uc740 1888\ub144 \ucd9c\ud310 \uc545\ubcf4\ub97c \ubc14\ud0d5\uc73c\ub85c \ud604\ub300\uc5d0 \uc0c8\ub85c \uc870\ud310\ud55c \uc790\ub8cc\ub2e4. \uc624\ub298 \ubcf4\ub294 \uc545\ubcf4\uc640 \uc791\uace1\uac00\uac00 \uc885\uc774\uc5d0 \ucc98\uc74c \uc801\uc5c8\ub358 \uc6d0\uace0\ub97c \uac19\uc740 \ubb3c\uac74\uc73c\ub85c \uc18c\uac1c\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc2dc\uc791 \ubd80\ubd84\uc740 \ubbf8\uc640 \uadf8 \ubc14\ub85c \uc544\ub798\uc758 \ub808 \uc0f5\uc744 \uc624\uac00\uba70 \ub9dd\uc124\uc774\ub294 \ub4ef \uc6c0\uc9c1\uc778\ub2e4. \ub450 \uc74c\uc758 \uac70\ub9ac\ub294 \ud53c\uc544\ub178 \uac74\ubc18\uc5d0\uc11c \ubc14\ub85c \uc774\uc6c3\ud55c \ubc18\uc74c\uc774\ub2e4. \ud070 \ud3ed\uc73c\ub85c \ub6f0\uc5b4\uc624\ub974\ub294 \ub300\uc2e0 \uc881\uc740 \uacf3\uc744 \ubc18\ubcf5\ud574\uc11c \uac74\ub4dc\ub9ac\ubbc0\ub85c, \uc9e7\uc740 \uc6c0\uc9c1\uc784 \uc790\uccb4\uac00 \uace1\uc758 \uc5bc\uad74\uc774 \ub41c\ub2e4. \uc774\uc5b4 \uc2dc, \ub808, \ub3c4, \ub77c\ub85c \uae38\uc774 \uc5f4\ub9ac\uba70 \uc6b0\ub9ac\uac00 \uae30\uc5b5\ud558\ub294 \uccab \uad6c\uc808\uc774 \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4. \uc624\ub978\uc190\uc758 \uc120\uc728 \uc544\ub798\uc5d0\uc11c\ub294 \uc67c\uc190\uc774 \ud654\uc74c\uc758 \uc74c\ub4e4\uc744 \ucc28\ub840\ub85c \ud3bc\uccd0 \ub193\ub294\ub2e4. \uc5ec\ub7ec \uc74c\uc744 \ud55c\uaebc\ubc88\uc5d0 \ub204\ub974\uc9c0 \uc54a\uace0 \ub098\ub204\uc5b4 \uc6b8\ub9ac\ub294 \ubc18\uc8fc\ub2e4. \uc775\uc219\ud55c \uba5c\ub85c\ub514\ub9cc \ub530\ub77c \ubd80\ub974\ub358 \uc0ac\ub78c\ub3c4 \ub0ae\uc740 \ucabd\uc758 \uc6c0\uc9c1\uc784\uc744 \ud568\uaed8 \ub4e4\uc73c\uba74 \uc74c\uc545\uc774 \ud55c \uc904\ub85c\ub9cc \uc9c4\ud589\ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uac83\uc744 \ub290\ub084 \uc218 \uc788\ub2e4. \uace1\uc758 \ud750\ub984\uc744 \uac04\ub2e8\ud788 \uc801\uc73c\uba74 \u2018\ucc98\uc74c \uc120\uc728 \u2014 \ub2e4\ub978 \uc7a5\uba74 \u2014 \ucc98\uc74c \uc120\uc728 \u2014 \ub610 \ub2e4\ub978 \uc7a5\uba74 \u2014 \ucc98\uc74c \uc120\uc728\u2019\ucc98\ub7fc \ub4e4\uc744 \uc218 \uc788\ub2e4. \uc74c\uc545\uc5d0\uc11c \uc774\ub7f0 \ubc18\ubcf5\uacfc \ub300\ube44\ub97c \uc124\uba85\ud560 \ub54c \ub860\ub3c4\ub77c\ub294 \ub9d0\uc744 \uc4f4\ub2e4. \uc5b4\ub824\uc6b4 \ud615\uc2dd \uc774\ub984\ubcf4\ub2e4 \uc9d1\uc73c\ub85c \ub3cc\uc544\uc624\ub294 \uae38\uc744 \ub5a0\uc62c\ub824\ub3c4 \uc88b\ub2e4. \uac19\uc740 \ubb38\uc744 \ub2e4\uc2dc \uc5f4\uc5b4\ub3c4, \uadf8 \uc0ac\uc774 \uc5b4\ub514\ub97c \ub2e4\ub140\uc654\ub290\ub0d0\uc5d0 \ub530\ub77c \ub3cc\uc544\uc628 \ub290\ub08c\uc740 \ub2ec\ub77c\uc9c4\ub2e4. \ubc18\ubcf5\ub418\ub294 \uccab \uc120\uc728\uc744 A\ub77c\uace0 \ub9c8\uc74c\uc18d\uc73c\ub85c \ud45c\uc2dc\ud574 \ubcf4\uc790. A\uac00 \uc544\ub2cc \ubd80\ubd84\uc774 \ub098\uc624\uba74 \ubaa8\ub974\ub294 \uace1\uc73c\ub85c \ubc14\ub00c\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud558\uae30\ubcf4\ub2e4, \uc775\uc219\ud55c \uc120\uc728\uacfc \ubb34\uc5c7\uc774 \ub2e4\ub978\uc9c0 \ub4e4\uc5b4 \ubcf4\uba74 \ub41c\ub2e4. \uc545\ubcf4\uc758 \ubaa8\ub4e0 \ubc18\ubcf5 \uae30\ud638\ub97c \uacc4\uc0b0\ud558\uc9c0 \uc54a\uc544\ub3c4 \uadc0\ub85c \ud070 \uad6c\uc870\ub97c \uc7a1\uc744 \uc218 \uc788\ub294 \ubc29\ubc95\uc774\ub2e4. \ucc98\uc74c \uc120\uc728\uc744 \ubc97\uc5b4\ub098\uba74 \uc74c\ub4e4\uc774 \ub354 \ucd18\ucd18\ud558\uac8c \uc6c0\uc9c1\uc774\uace0 \uc74c\uc545\uc758 \ud45c\uc815\uc774 \ubc1d\uc544\uc9c0\ub294 \uad6c\uac04\uc774 \ub098\ud0c0\ub09c\ub2e4. \ucc98\uc74c\uc758 \uc870\uc2ec\uc2a4\ub7ec\uc6b4 \ubb3c\uc74c\ud45c\uc5d0\uc11c \uc870\uae08 \ub354 \ub113\uace0 \uc720\uc5f0\ud55c \uc6c0\uc9c1\uc784\uc73c\ub85c \ub098\uc544\uac00\ub294 \ub4ef \ub4e4\uc744 \uc218 \uc788\ub2e4. \uc774\ub294 \uac10\uc0c1\uc744 \ub3d5\uae30 \uc704\ud55c \ube44\uc720\uc774\uba70 \uc791\uace1\uac00\uac00 \uc815\ud574 \ub454 \uc904\uac70\ub9ac\ub294 \uc544\ub2c8\ub2e4. \ud53c\uc544\ub178\ub97c \ub9c9 \ubc30\uc6b0\ub294 \uc0ac\ub78c\uc774 \uccab \ubd80\ubd84\uc744 \uc5f0\uc8fc\ud560 \uc218 \uc788\ub2e4\uace0 \ud574\uc11c \uace1 \uc804\uccb4\uac00 \uac19\uc740 \ub09c\uc774\ub3c4\ub85c \uc774\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774 \uad6c\uac04\uc5d0\uc11c\ub294 \ube60\ub974\uac8c \uc774\uc5b4\uc9c0\ub294 \uc74c\ub4e4\uacfc \uc190\uc758 \uc774\ub3d9\uc774 \ud544\uc694\ud558\ub2e4. \ucc98\uc74c \uba87 \ub9c8\ub514\ub9cc\uc73c\ub85c \u2018\uc26c\uc6b4 \uc18c\ud488\u2019\uc774\ub77c\uace0 \ud310\ub2e8\ud558\uba74 \uc74c\uc545\uc774 \uac10\ucd94\uace0 \uc788\ub358 \ub2e4\ub978 \ud45c\uc815\uc744 \ub193\uce5c\ub2e4. \ub4a4\ucabd\uc758 \ub610 \ub2e4\ub978 \uad6c\uac04\uc5d0\uc11c\ub294 \ub0ae\uc740 \uc74c\uc758 \ubc18\ubcf5\uc774 \uadc0\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uadf8 \uc704\uc758 \ud654\uc74c\uacfc \uc120\uc728\uc774 \uc6c0\uc9c1\uc774\uba74\uc11c \ucc98\uc74c\ubcf4\ub2e4 \uae34\uc7a5\ub41c \ub290\ub08c\uc744 \ub9cc\ub4e0\ub2e4. \ucc98\uc74c\uc5d0 \uac00\uae4c\uc6b4 \ub450 \uc74c\uc744 \uc624\uac00\ub358 \uc12c\uc138\ud568\uacfc\ub294 \ub2e4\ub978, \uc870\uae08 \ub354 \ub2e8\ub2e8\ud558\uace0 \ub2e4\uae09\ud55c \ucd94\uc9c4\ub825\uc744 \ub4e4\uc744 \uc218 \uc788\ub2e4. \uadf8 \uae34\uc7a5\uc774 \uc9c0\ub09c \ub4a4 \ucc98\uc74c\uc758 \uc120\uc728\uc774 \ub3cc\uc544\uc624\uba74 \uace1\uc758 \uc2dc\uc791\uacfc \ub05d\uc774 \uc5f0\uacb0\ub41c\ub2e4. \uac19\uc740 \uc74c\uc774 \ub3cc\uc544\uc640\ub3c4 \uc774\ubbf8 \ub2e4\ub978 \uc7a5\uba74\uc744 \uac70\ucce4\uae30 \ub54c\ubb38\uc5d0 \ub2e8\uc21c\ud55c \ub418\ud480\uc774\ub85c\ub9cc \ub4e4\ub9ac\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uc774\ubc88\uc5d0\ub294 \ubc18\uc8fc\ub97c, \ub2e4\uc74c\uc5d0\ub294 \uc120\uc728\uc744 \ub530\ub77c\uac00\uba70 \ub450 \ubc88 \ub4e4\uc5b4 \ubcf4\uba74 \uc774\ub7f0 \ubcc0\ud654\uac00 \ub354 \ubd84\uba85\ud574\uc9c4\ub2e4. \uba3c\uc800 \uace1 \uc804\uccb4\ub97c \ub05d\uae4c\uc9c0 \ud55c \ubc88 \ub4e4\uc5b4 \ubcf4\uc790. \ub450 \ubc88\uc9f8\uc5d0\ub294 \uccab \uc120\uc728\uc774 \ub3cc\uc544\uc624\ub294 \uc21c\uac04\uc744 \ucc3e\uace0, \uc138 \ubc88\uc9f8\uc5d0\ub294 \uac00\uc6b4\ub370 \ub450 \uad6c\uac04\uc758 \ucc28\uc774\ub97c \ub4e4\uc5b4 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \ubaa8\ub4e0 \uac83\uc744 \ud55c\uaebc\ubc88\uc5d0 \uc54c\uc544\ub0b4\ub824\uace0 \ud558\uc9c0 \uc54a\uc73c\uba74 \uc775\uc219\ud55c \uc74c\uc545\ub3c4 \uc0c8\ub86d\uac8c \ub4e4\uc744 \uc5ec\uc720\uac00 \uc0dd\uae34\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \uc61b \ud53c\uc544\ub178\uac00 \ub193\uc778 \ubc29\uc744 \ud1b5\ud574 \uace1\uc758 \uc870\uc6a9\ud55c \ubd84\uc704\uae30\ub97c \uc0c1\uc0c1\ud55c AI \uc0bd\ud654\ub2e4. \ubca0\ud1a0\ubca4\uc758 \uc2e4\uc81c \ubc29\uc774\ub098 \uc545\uae30, \uc5d8\ub9ac\uc81c\uc758 \uc815\uccb4\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc5d8\ub9ac\uc81c\uac00 \ub204\uad6c\uc600\ub294\uc9c0 \uad81\uae08\ud574\ud558\ub294 \ub9c8\uc74c\uacfc, \uc2e4\uc81c\ub85c \ub4e4\ub9ac\ub294 \uc74c\uc744 \uc990\uae30\ub294 \ub9c8\uc74c\uc740 \ud568\uaed8 \uac08 \uc218 \uc788\ub2e4. \ud655\uc815\ub418\uc9c0 \uc54a\uc740 \ub85c\ub9e8\uc2a4\ub97c \ucc44\uc6cc \ub123\uc9c0 \uc54a\uc544\ub3c4 \uc774 \uc9e7\uc740 \uace1 \uc548\uc5d0\ub294 \ubc18\ubcf5, \ub300\ube44, \uae34\uc7a5\uacfc \uadc0\ud658\uc774\ub77c\ub294 \uaf64 \ud48d\ubd80\ud55c \uc2dc\uac04\uc774 \ub4e4\uc5b4 \uc788\ub2e4."}, {"id": "gericault-medusa-distant-ship", "title": "\uba54\ub450\uc0ac\ud638\uc758 \ub5cf\ubaa9 \u2014 \uba40\ub9ac \ubcf4\uc774\ub294 \uc791\uc740 \ubc30\ub97c \ud5a5\ud558\uc5ec", "summary": "\uc81c\ub9ac\ucf54\uac00 \uc2e4\uc81c \ub09c\ud30c \uc0ac\uac74\uc744 \uadf8\ub9bc\uc73c\ub85c \uc62e\uae30\uba70 \uc2dc\uc120\uacfc \ubab8\uc758 \ubc29\ud5a5\uc73c\ub85c \uae34\uc7a5\uc744 \ub9cc\ub4e0 \ubc29\ubc95\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/gericault-medusa-distant-ship/index.html", "image": "../media/gericault-medusa-distant-ship.jpg", "alt": "\uc81c\ub9ac\ucf54\uc758 \uba54\ub450\uc0ac\ud638\uc758 \ub5cf\ubaa9\uc744 \uc7ac\ud604\ud55c \uc61b \ub3c4\ud310. \uc55e\ucabd\uc758 \uc4f0\ub7ec\uc9c4 \uc778\ubb3c\ub4e4\uacfc \uba3c \ubc30\ub97c \ud5a5\ud574 \ucc9c\uc744 \ub4dc\ub294 \uc0ac\ub78c\ub4e4\uc774 \ud568\uaed8 \ubcf4\uc785\ub2c8\ub2e4.", "text": "\uba54\ub450\uc0ac\ud638\uc758 \ub5cf\ubaa9 \u2014 \uba40\ub9ac \ubcf4\uc774\ub294 \uc791\uc740 \ubc30\ub97c \ud5a5\ud558\uc5ec \uc808\ub9dd\uacfc \uad6c\uc870\uc758 \uae30\ub300\uac00 \ud55c \ud654\uba74\uc5d0 \ub193\uc774\ub294 \ubc29\uc2dd \uc81c\ub9ac\ucf54\uac00 \uc2e4\uc81c \ub09c\ud30c \uc0ac\uac74\uc744 \uadf8\ub9bc\uc73c\ub85c \uc62e\uae30\uba70 \uc2dc\uc120\uacfc \ubab8\uc758 \ubc29\ud5a5\uc73c\ub85c \uae34\uc7a5\uc744 \ub9cc\ub4e0 \ubc29\ubc95\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \uadf8\ub9bc \uc548\uc758 \uc0ac\ub78c\ub4e4\uc740 \uba3c \uacf3\uc744 \ud5a5\ud574 \uc190\uacfc \ucc9c\uc744 \ub4e4\uc5b4 \uc62c\ub9b0\ub2e4. \uadf8\ub7f0\ub370 \uadf8\ub4e4\uc774 \ubc14\ub77c\ubcf4\ub294 \ubc30\ub294 \ub180\ub784 \ub9cc\ud07c \uc791\ub2e4. \ubc14\ub85c \uc55e\uc5d0\ub294 \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294 \ubab8\ub4e4\uc774 \uc788\uace0 \ubc14\ub2e4\ub294 \ubd88\uc548\ud558\ub2e4. \uc81c\ub9ac\ucf54\uc758 \u3008\uba54\ub450\uc0ac\ud638\uc758 \ub5cf\ubaa9\u3009\uc5d0\uc11c\ub294 \ud76c\ub9dd\uc774 \uac70\ub300\ud55c \uc601\uc6c5\uc758 \ubaa8\uc2b5\ubcf4\ub2e4 \uac70\uc758 \ub193\uce60 \ub9cc\ud55c \uc218\ud3c9\uc120\uc758 \uc810\uc73c\ub85c \ub098\ud0c0\ub09c\ub2e4. \uc2e4\uc81c \ub09c\ud30c \uc0ac\uac74\uc5d0\uc11c \ucd9c\ubc1c\ud55c \uc774 \uadf8\ub9bc\uc740 1819\ub144 \uc0b4\ub871\uc5d0\uc11c \ud070 \uc8fc\ubaa9\uc744 \ubc1b\uc558\ub2e4. \ud3b8\uc548\ud55c \ud48d\uacbd\ud654\ub294 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uad34\ub85c\uc6b4 \uc7a5\uba74\uc744 \uc790\uc138\ud788 \uc124\uba85\ud558\uae30\ubcf4\ub2e4 \uc0ac\ub78c\ub4e4\uc758 \uc2dc\uc120\uacfc \ud654\uba74\uc758 \ubc29\ud5a5\uc744 \ub530\ub77c\uac00\uba74, \ud654\uac00\uac00 \uace0\ud1b5\uacfc \uae30\ub300\ub97c \uc5b4\ub5bb\uac8c \ud568\uaed8 \ubcf4\uc774\uac8c \ud588\ub294\uc9c0 \uc77d\uc744 \uc218 \uc788\ub2e4. \uc81c\ubaa9\uc758 \uba54\ub450\uc0ac\ub294 \uc2e0\ud654 \uc18d \uc778\ubb3c\uc774 \uc544\ub2c8\ub77c \ub09c\ud30c\ud55c \ubc30\uc758 \uc774\ub984\uc774\ub2e4. \uc0b4\uc544\ub0a8\uc740 \uc0ac\ub78c\ub4e4\uc774 \ub5cf\ubaa9\uc5d0 \ub9e4\ub2ec\ub824 \ubc14\ub2e4\ub97c \ub5a0\ub3c4\ub294 \uc0c1\ud669\uc774 \uadf8\ub9bc\uc758 \ubc14\ud0d5\uc774\ub2e4. \uc548\uc815\ub41c \ubc30\uc758 \uac11\ud310\ucc98\ub7fc \ubcf4\uc544\uc11c\ub294 \uc548 \ub418\ub294 \uc774\uc720\ub2e4. \uc778\ubb3c\ub4e4\uc774 \uc11c\uac70\ub098 \uae30\ub300\ub294 \ubc14\ub2e5 \uc790\uccb4\uac00 \ubd88\uc548\uc815\ud558\ub2e4. \ub113\uc740 \ubc14\ub2e4\uc5d0 \ube44\ud558\uba74 \uc0ac\ub78c\uc774 \ub51b\ub294 \uacf3\uc740 \uc881\ub2e4. \ubb34\ub300\uc758 \uac00\uc7a5\uc790\ub9ac\ucc98\ub7fc \ud654\uba74 \uc55e\ucabd\uc5d0 \uac78\ub9b0 \ub5cf\ubaa9\uc744 \ubcf4\uba74 \uad00\ub78c\uc790\uc640 \uc0ac\uac74\uc758 \uac70\ub9ac\ub3c4 \uac00\uae5d\uac8c \ub290\uaef4\uc9c4\ub2e4. \uba40\ub9ac\uc11c \ubc14\ub2e4\uc758 \uc544\ub984\ub2e4\uc6c0\uc744 \uac10\uc0c1\ud558\ub294 \uc2dc\uc810\ubcf4\ub2e4 \uc0ac\ub78c\ub4e4\uc758 \uc704\ud0dc\ub85c\uc6b4 \uc790\ub9ac \uac00\uae4c\uc774\uc5d0 \uc138\uc6cc\uc9c0\ub294 \ub290\ub08c\uc774\ub2e4. \uc544\ub798\ucabd\uc5d0\ub294 \ud798\uc5c6\uc774 \ub298\uc5b4\uc9c4 \uc778\ubb3c\ub4e4\uc774 \uc788\ub2e4. \uadf8 \uacc1\uc758 \uc0ac\ub78c\ub4e4\ub3c4 \uc11c\ub85c \ub2e4\ub978 \ubc29\ud5a5\uc73c\ub85c \ubab8\uc744 \uae30\ub300\uac70\ub098 \uace0\uac1c\ub97c \uc219\uc778\ub2e4. \ubaa8\ub450\uac00 \ud55c \uac00\uc9c0 \uac10\uc815\uc744 \uac19\uc740 \uc790\uc138\ub85c \ud45c\ud604\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc774\ubbf8 \uc9c0\uce5c \uc0ac\ub78c\uacfc \uc544\uc9c1 \ubc14\uae65\uc744 \ubc14\ub77c\ubcf4\ub294 \uc0ac\ub78c\uc774 \uac19\uc740 \ub5cf\ubaa9\uc5d0 \uc788\ub2e4. \uc774 \ucc28\uc774 \ub54c\ubb38\uc5d0 \uadf8\ub9bc\uc744 \uc808\ub9dd\uc774\ub77c\ub294 \ub2e8\uc5b4 \ud558\ub098\ub85c \ub05d\ub0b4\uae30 \uc5b4\ub835\ub2e4. \uc5b4\ub5a4 \uc778\ubb3c\uc5d0\uac8c\ub294 \ubab8\uc744 \ub4dc\ub294 \uc77c\uc870\ucc28 \uc5b4\ub824\uc6cc \ubcf4\uc774\uace0, \ub2e4\ub978 \uc778\ubb3c\uc5d0\uac8c\ub294 \uc190\uc744 \ub4e4\uc5b4 \uc2e0\ud638\ub97c \ubcf4\ub0b4\ub294 \uc77c\uc774 \ub9c8\uc9c0\ub9c9 \ud589\ub3d9\uc774 \ub41c\ub2e4. \uac10\uc815\uc740 \ud45c\uc815\ubfd0 \uc544\ub2c8\ub77c \ubab8\uc758 \ub192\uc774\uc640 \ud798\uc758 \ubc29\ud5a5\uc73c\ub85c \ub4dc\ub7ec\ub09c\ub2e4. \uc2dc\uc120\uc744 \uc624\ub978\ucabd \uc704\ub85c \uc62e\uae30\uba74 \ubab8\ub4e4\uc774 \uacb9\uccd0\uc9c0\uace0 \uc6c0\uc9c1\uc784\uc774 \ub192\uc544\uc9c4\ub2e4. \ub0ae\uac8c \ub193\uc778 \uc0ac\ub78c\ub4e4\uc5d0\uc11c \ubb34\uc5b8\uac00\ub97c \uac00\ub9ac\ud0a4\ub294 \uc0ac\ub78c\uc744 \uc9c0\ub098, \uac00\uc7a5 \ub192\uc740 \uc790\ub9ac\uc5d0\uc11c \ucc9c\uc744 \ud754\ub4dc\ub294 \uc778\ubb3c \ucabd\uc73c\ub85c \uc62c\ub77c\uac04\ub2e4. \uc5ec\ub7ec \uc0ac\ub78c\uc774 \ud558\ub098\uc758 \ud070 \ubc29\ud5a5\uc744 \ub9cc\ub4dc\ub294 \uc148\uc774\ub2e4. \uac1c\uac1c\uc778\uc758 \ud574\ubd80\ud559\uc801 \uc790\uc138\ub97c \ubd84\uc11d\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc774 \ud750\ub984\uc740 \ubcf4\uc778\ub2e4. \ud654\uba74\uc758 \uc5b4\ub514\uac00 \ub0ae\uace0 \uc5b4\ub514\uac00 \ub192\uc544\uc9c0\ub294\uc9c0, \ud314\uc774 \uc5b4\ub290 \ucabd\uc73c\ub85c \ubed7\ub294\uc9c0\ub9cc \ub530\ub77c\uac00\ub3c4 \ub41c\ub2e4. \uadf8\ub9bc\uc740 \ub9ce\uc740 \uc778\ubb3c\uc744 \ubb34\uc791\uc815 \ubaa8\uc544 \ub193\uc740 \uac83\uc774 \uc544\ub2c8\ub77c \uc6b0\ub9ac\uc758 \ub208\uc774 \uc9c0\ub098\uac08 \uae38\uc744 \uc870\uc9c1\ud558\uace0 \uc788\ub2e4. \uc778\ubb3c\ub4e4\uc758 \uc6c0\uc9c1\uc784\uc744 \ub530\ub77c \ub05d\uae4c\uc9c0 \uac00\uba74 \uc218\ud3c9\uc120 \uadfc\ucc98\uc758 \uc791\uc740 \uad6c\uc870\uc120\uc774 \ubcf4\uc778\ub2e4. \uc0ac\ub78c\uc774 \uc544\ubb34\ub9ac \ud06c\uac8c \ubab8\uc9d3\ud574\ub3c4 \uba3c \ubc30\uc5d0\uc11c \uc54c\uc544\ubcfc \uc218 \uc788\uc744\uc9c0\ub294 \uc54c \uc218 \uc5c6\ub2e4. \ud76c\ub9dd\uc758 \ub300\uc0c1\uc774 \uc791\uace0 \uba40\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc2e0\ud638\ub97c \ubcf4\ub0b4\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc808\ubc15\ud568\uc744 \ub354 \ud06c\uac8c \ub9cc\ub4e0\ub2e4. \ubc30\uac00 \ub208\uc55e\uc5d0\uc11c \ud655\uc2e4\ud558\uac8c \ub2e4\uac00\uc624\ub294 \uc7a5\uba74\uc774\uc5c8\ub2e4\uba74 \uadf8\ub9bc\uc758 \uae34\uc7a5\uc740 \ub2ec\ub790\uc744 \uac83\uc774\ub2e4. \uc5ec\uae30\uc11c\ub294 \uad6c\uc870\ub420 \uac00\ub2a5\uc131\uacfc \ub193\uce60 \uac00\ub2a5\uc131\uc774 \ud568\uaed8 \ub0a8\uc544 \uc788\ub2e4. \uc0ac\uac74\uc758 \ubaa8\ub4e0 \uacb0\uacfc\ub97c \ud55c \uc7a5\uba74\uc5d0 \ud3bc\uce58\uae30\ubcf4\ub2e4 \uc5b4\ub290 \uc21c\uac04\uc744 \uba48\ucd94\uc5b4 \ub193\uc744\uc9c0\uac00 \uadf8\ub9bc\uc758 \ud798\uacfc \uc5f0\uacb0\ub41c\ub2e4\ub294 \uac83\uc744 \ubcfc \uc218 \uc788\ub2e4. \uc67c\ucabd\uc758 \ub3db\uacfc \uc904, \uc5b4\ub450\uc6b4 \ud558\ub298\uacfc \ud30c\ub3c4\ub3c4 \ud654\uba74\uc758 \uc6c0\uc9c1\uc784\uc5d0 \ucc38\uc5ec\ud55c\ub2e4. \uc0ac\ub78c\ub4e4\uc758 \ubab8\uc774 \uad6c\uc870\uc120 \ucabd\uc73c\ub85c \ud5a5\ud558\ub354\ub77c\ub3c4 \uadf8 \ubc14\ub78c\uc774 \uace7 \uc548\uc815\ub41c \uc774\ub3d9\uc744 \ubcf4\uc7a5\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc790\uc5f0\uc740 \uc778\ubb3c\uc758 \uae30\ub300\uc5d0 \ub9de\ucdb0 \ud3b8\uc548\ud55c \ubc30\uacbd\uc774 \ub418\uc5b4 \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \ubc1d\uc740 \ubd80\ubd84\uacfc \uc5b4\ub450\uc6b4 \ubd80\ubd84\uc758 \ub300\ube44\ub3c4 \uc0b4\ud3b4\ubcf4\uc790. \uc778\ubb3c\uc758 \ubab8\uc774 \ub4dc\ub7ec\ub098\ub294 \uacf3\uacfc \uadf8\ub9bc\uc790\uac00 \ubb49\uce58\ub294 \uacf3\uc744 \uc624\uac00\uba74 \uc2dc\uc120\uc774 \ud55c\uacf3\uc5d0\ub9cc \uace0\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4. \ubc14\ub2e4\uac00 \ub113\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc0ac\ub78c\uc774 \uac00\uae4c\uc774 \uc788\ub2e4\ub294 \ub290\ub08c\uc774 \ud568\uaed8 \uc0dd\uae34\ub2e4. \ubc30\uacbd\uc758 \ub0a0\uc528\ub3c4 \uc0ac\uac74\uc758 \uc555\ub825\uc73c\ub85c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uc774 \uc791\ud488\uc740 \uc2e4\uc81c \ub09c\ud30c\uc758 \uace0\ud1b5\uc5d0\uc11c \ucd9c\ubc1c\ud588\uc9c0\ub9cc \uc0ac\uac74\uc744 \ucd2c\uc601\ud55c \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \ud654\uac00\ub294 \uc0ac\ub78c\uacfc \ube5b, \ub3d9\uc791\uc744 \uc120\ud0dd\ud558\uace0 \uad6c\uc131\ud588\ub2e4. \uc2e4\uc81c \uc77c\uc774 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ub208\uc55e\uc758 \ubaa8\ub4e0 \uc138\ubd80\uac00 \uadf8 \uc21c\uac04 \uadf8\ub300\ub85c\ub77c\ub294 \uc8fc\uc7a5\uc740 \ub2e4\ub974\ub2e4. \uc624\ub798\ub41c \ub3c4\ub85d\uc5d0\ub294 \uc778\ubb3c\ub4e4\uc744 \ud2b9\uc815 \uc0dd\uc874\uc790\uc640 \uc5f0\uacb0\ud558\ub294 \uc124\uba85\ub3c4 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc774 \uae00\uc5d0\uc11c\ub294 \ud654\uba74\uc5d0\uc11c \uc9c1\uc811 \ubcfc \uc218 \uc788\ub294 \uad00\uacc4\uc640 \ud655\uc778\ud55c \ud070 \ubc30\uacbd\uc744 \uc911\uc2ec\uc73c\ub85c \uc77d\ub294\ub2e4. \uc0ac\uac74\uc758 \ucc38\uac00\uc790 \uc218\ub098 \ucc45\uc784 \ubb38\uc81c \uc804\uccb4\ub97c \uc774 \ud55c \uadf8\ub9bc\uc758 \ubaa8\uc2b5\ub9cc\uc73c\ub85c \ud655\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc5ed\uc0ac \uc790\ub8cc\uc640 \ud68c\ud654\uc758 \ud45c\ud604\uc740 \uc11c\ub85c \ub300\uc870\ud560 \ud544\uc694\uac00 \uc788\ub2e4. \uc791\ud488\uc740 \uc138\ub85c \uc57d 5\ubbf8\ud130, \uac00\ub85c \uc57d 7\ubbf8\ud130\uc5d0 \uc774\ub974\ub294 \uac70\ub300\ud55c \uce94\ubc84\uc2a4\ub2e4. \ud654\uba74\uc5d0\uc11c \uc791\uac8c \ubcfc \ub54c\uc640 \uc2e4\uc81c \ud06c\uae30 \uc55e\uc5d0 \uc130\uc744 \ub54c\uc758 \uacbd\ud5d8\uc774 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc0dd\uc874\uc744 \uae30\ub2e4\ub9ac\ub294 \uc0ac\ub78c\ub4e4\uc758 \ubab8\uc774 \ub2e8\uc21c\ud55c \uc791\uc740 \uc0bd\ud654 \uc18d \uc778\ubb3c\ub85c\ub9cc \ubcf4\uc774\uc9c0 \uc54a\ub294 \uaddc\ubaa8\ub2e4. \uc61b \ub3c4\ub85d\uc740 \uc774 \uc791\ud488\uc744 \ub0ad\ub9cc\uc8fc\uc758 \ud68c\ud654\uc758 \uc911\uc694\ud55c \ubcc0\ud654\uc640 \uc5f0\uacb0\ud55c\ub2e4. \uc591\uc2dd \uc774\ub984\uc744 \uc678\uc6b0\uae30\ubcf4\ub2e4 \ubb34\uc5c7\uc774 \uc804\uba74\uc73c\ub85c \ub098\uc654\ub294\uc9c0 \ubcf4\uba74 \ub41c\ub2e4. \uc815\ub3c8\ub41c \uc704\uc5c4\ubcf4\ub2e4 \ud754\ub4e4\ub9ac\ub294 \ubab8\uacfc \uaca9\ud55c \uac10\uc815, \ud604\uc2e4\uc758 \uace0\ud1b5\uc774 \ud070 \ud654\uba74\uc744 \ucc28\uc9c0\ud55c\ub2e4. \ubbf8\uc220\uc758 \uc911\uc694\ud55c \uc8fc\uc81c\uac00 \ubb34\uc5c7\uc77c \uc218 \uc788\ub294\uc9c0 \ubb3b\ub294 \uadf8\ub9bc\uc774\uae30\ub3c4 \ud558\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uba3c \ubc30\uac00 \uc5b4\ub514\uc5d0 \uc788\ub294\uc9c0 \ucc3e\uc544\ubcf4\uace0, \ub2e4\uc74c\uc5d0\ub294 \uadf8 \ubc30\ub97c \ud5a5\ud55c \ubab8\uc9d3\uc774 \uc5b4\ub514\uc5d0\uc11c \uc2dc\uc791\ub418\ub294\uc9c0 \uac70\uafb8\ub85c \ub530\ub77c\uac00 \ubcf4\uc790. \uc791\ud488\uc758 \uc758\ubbf8\ub97c \uc228\uc740 \ubb3c\uac74 \ud558\ub098\uc758 \uc815\ub2f5\uc73c\ub85c \ud478\ub294 \ub300\uc2e0 \ud654\uba74 \uc548\uc758 \uac70\ub9ac\uc640 \ubc29\ud5a5\uc744 \uc77d\ub294 \ubc29\ubc95\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uc61b \ub8e8\ube0c\ub974 \ub3c4\ub85d\uc758 \uc2e4\uc81c \uc791\ud488 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \uace0\ud1b5\uc758 \uc7a5\uba74\uc744 \uc0c8\ub85c \ub9cc\ub4e4\uc5b4 \ub0b8 AI \uc0bd\ud654\uac00 \uc544\ub2c8\ub2e4. \uc791\uc740 \ubc30\ub97c \ud5a5\ud574 \uc62c\ub77c\uac00\ub294 \uc2dc\uc120\uacfc \uc55e\ucabd\uc5d0 \ub0a8\uc740 \ubb34\uac8c\ub97c \ud568\uaed8 \ubcf4\uba74, \ud76c\ub9dd\uacfc \uc808\ub9dd\uc774 \uc5b4\ub5bb\uac8c \uac19\uc740 \uc21c\uac04\uc5d0 \uc874\uc7ac\ud558\ub294\uc9c0 \ub290\ub084 \uc218 \uc788\ub2e4."}, {"id": "gift-magi-watch-chain-and-combs", "title": "\uc624 \ud5e8\ub9ac\uc758 \u300c\ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \uc120\ubb3c\u300d \u2014 \ub2f9\uc7a5 \uc4f8 \uc218 \uc5c6\ub294 \ub450 \uc120\ubb3c", "summary": "\ub378\ub77c\uc640 \uc9d0\uc758 \uc2dc\uacd7\uc904\uacfc \uba38\ub9ac \uc7a5\uc2dd\uc744 \ub530\ub77c \ubc18\uc804\uacfc \uc81c\ubaa9\uc758 \uc758\ubbf8\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/gift-magi-watch-chain-and-combs/index.html", "image": "../media/gift-magi-watch-chain-and-combs.png", "alt": "\uc9e7\uc740 \uba38\ub9ac\uc758 \ub378\ub77c\uac00 \uc2dc\uacd7\uc904\uc744 \ub4e4\uace0 \uc9d0\uc774 \uba38\ub9ac \uc7a5\uc2dd \ube57\uc744 \uac74\ub124\ub294 \uc18c\uc124 \uc7a5\uba74 \uc0bd\ud654", "text": "\uc624 \ud5e8\ub9ac\uc758 \u300c\ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \uc120\ubb3c\u300d \u2014 \ub2f9\uc7a5 \uc4f8 \uc218 \uc5c6\ub294 \ub450 \uc120\ubb3c \uac00\uc7a5 \uc544\ub07c\ub358 \uac83\uc744 \ud314\uc558\ub354\ub2c8 \uc11c\ub85c\uc758 \ub9c8\uc74c\uc774 \ub0a8\uc558\ub2e4 \ub378\ub77c\uc640 \uc9d0\uc758 \uc2dc\uacd7\uc904\uacfc \uba38\ub9ac \uc7a5\uc2dd\uc744 \ub530\ub77c \ubc18\uc804\uacfc \uc81c\ubaa9\uc758 \uc758\ubbf8\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \ud06c\ub9ac\uc2a4\ub9c8\uc2a4\uac00 \ub0b4\uc77c\uc778\ub370 \uac00\uc9c4 \ub3c8\uc740 1\ub2ec\ub7ec 87\uc13c\ud2b8\ub2e4. \uc624 \ud5e8\ub9ac\uc758 \uc9e7\uc740 \uc18c\uc124\uc740 \ub378\ub77c\uac00 \ub3c8\uc744 \ub2e4\uc2dc \uc138\ub294 \uc7a5\uba74\uc5d0\uc11c \uc2dc\uc791\ud55c\ub2e4. \uba87 \ubc88\uc744 \uc138\uc5b4\ub3c4 \uc22b\uc790\ub294 \ub2ec\ub77c\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uc0ac\ub791\ud558\ub294 \ub0a8\ud3b8\uc5d0\uac8c \uc88b\uc740 \uc120\ubb3c\uc744 \uc8fc\uace0 \uc2f6\ub2e4\ub294 \ub9c8\uc74c\ub9cc \uadf8\ubcf4\ub2e4 \ud6e8\uc52c \ud06c\ub2e4. \u300c\ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \uc120\ubb3c\u300d\ub85c \ub110\ub9ac \uc77d\ud788\ub294 \uc774 \uc791\ud488\uc758 \uc6d0\uc81c\ub294 \u300e\ub3d9\ubc29\ubc15\uc0ac\uc758 \uc120\ubb3c\u300f\uc774\ub2e4. \uc9e7\uc740 \ubc18\uc804\uc774 \uc720\uba85\ud558\uc9c0\ub9cc \uadf8 \uc804\ud6c4\uc758 \uc0dd\ud65c\uc744 \uc0b4\ud53c\uba74 \uacb0\ub9d0\uc774 \ub354 \ub530\ub73b\ud558\uace0\ub3c4 \uc4f8\uc4f8\ud574\uc9c4\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc120\ubb3c\uc758 \uc815\uccb4\ub97c \ud3ec\ud568\ud574 \uc904\uac70\ub9ac \uc804\uccb4\ub97c \uc18c\uac1c\ud55c\ub2e4. \ub378\ub77c\uc640 \uc9d0\uc740 \ub109\ub109\ud558\uc9c0 \uc54a\uc740 \uc9d1\uc5d0\uc11c \uc0b0\ub2e4. \uc18c\ub4dd\uc740 \uc804\ubcf4\ub2e4 \uc904\uc5c8\uace0, \ub378\ub77c\uac00 \uc870\uae08\uc529 \uc544\uaef4 \ubaa8\uc740 \ub3c8\ub3c4 \uae30\ub300\ud55c \ub9cc\ud07c \ub418\uc9c0 \uc54a\uc558\ub2e4. \uc791\uac00\ub294 \uac00\ub09c\uc744 \uac70\ub300\ud55c \uc124\uba85\uc73c\ub85c \uba3c\uc800 \ud3bc\uce58\uae30\ubcf4\ub2e4 \uc791\uc740 \uc22b\uc790\uc640 \uc9d1\uc758 \uc138\ubd80\ub85c \ubcf4\uc5ec \uc900\ub2e4. \ub3c5\uc790\ub294 \uadf8 \ud558\ub8e8\uc758 \ub09c\uac10\ud568\uc744 \ube60\ub974\uac8c \ub290\ub07c\uac8c \ub41c\ub2e4. \ub450 \uc0ac\ub78c\uc5d0\uac8c \ubd80\uc871\ud55c \uac83\uc740 \ub9c8\uc74c\uc774 \uc544\ub2c8\ub2e4. \ub9c8\uc74c\uc744 \uc88b\uc740 \ubb3c\uac74\uc73c\ub85c \ubc14\uafb8\ub294 \ub370 \ud544\uc694\ud55c \ub3c8\uc774\ub2e4. \uadf8\ub798\uc11c \uc774\uc57c\uae30\ub294 \ube44\uc2fc \uc120\ubb3c\uc744 \uc0ac\uba74 \uc0ac\ub791\uc774 \ucee4\uc9c4\ub2e4\ub294 \ub2e8\uc21c\ud55c \uae30\uc900\uc5d0\uc11c \ucd9c\ubc1c\ud558\ub294 \ub4ef \ubcf4\uc778\ub2e4. \ub2e4\ub9cc \uadf8 \uae30\uc900\uc744 \ub05d\uae4c\uc9c0 \uadf8\ub300\ub85c \uc720\uc9c0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ucc98\uc74c\uc758 \ubd80\uc871\ud568\uc774 \ub9c8\uc9c0\ub9c9\uc5d0 \ub2e4\ub978 \uc9c8\ubb38\uc73c\ub85c \ubc14\ub010\ub2e4. \ub450 \uc0ac\ub78c\uc774 \ud2b9\ud788 \uc544\ub07c\ub294 \uac83\uc774 \uc788\ub2e4. \ub378\ub77c\uc5d0\uac8c\ub294 \uae38\uace0 \uc544\ub984\ub2e4\uc6b4 \uba38\ub9ac\uce74\ub77d\uc774, \uc9d0\uc5d0\uac8c\ub294 \uc9d1\uc548\uc5d0\uc11c \ubb3c\ub824\ubc1b\uc740 \uae08\uc2dc\uacc4\uac00 \uc788\ub2e4. \uc774\uac83\ub4e4\uc740 \ub2e8\uc21c\ud788 \ud604\uae08\uc73c\ub85c \ubc14\uafc0 \uc218 \uc788\ub294 \uc7ac\uc0b0\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uc790\uc2e0\uc774 \uc88b\uc544\ud558\ub294 \ubaa8\uc2b5\uacfc \uac00\uc871\uc758 \uae30\uc5b5, \uc790\ubd80\uc2ec\uc774 \ubd99\uc5b4 \uc788\ub294 \ubb3c\uac74\uc774\ub2e4. \uac00\ub09c\ud55c \uc9d1\uc5d0\ub3c4 \uc18c\uc911\ud568\uc758 \uae30\uc900\uc740 \ud48d\ubd80\ud558\uac8c \uc874\uc7ac\ud55c\ub2e4. \ubaa8\ub4e0 \uac83\uc744 \uac00\uaca9\ud45c \ud558\ub098\ub85c\ub9cc \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uc791\uac00\ub294 \uc774 \ub450 \ubcf4\ubb3c\uc744 \uba3c\uc800 \uc54c\ub824 \uc90c\uc73c\ub85c\uc368 \ub4a4\uc5d0 \uc120\ud0dd\uc774 \uc5bc\ub9c8\ub098 \ud070 \uac83\uc778\uc9c0 \ub3c5\uc790\uac00 \uc774\ud574\ud558\uac8c \ud55c\ub2e4. \uba38\ub9ac\uce74\ub77d\uacfc \uc2dc\uacc4\ub294 \uacb0\ub9d0\uc744 \uc704\ud55c \uc18c\ud488\uc774\uba74\uc11c \ub450 \uc0ac\ub78c\uc758 \uc0dd\ud65c\uc5d0\uc11c \uc774\ubbf8 \uc758\ubbf8\ub97c \uac00\uc9c4 \uc874\uc7ac\ub2e4. \ub378\ub77c\ub294 \uba38\ub9ac\uce74\ub77d\uc744 \ud314\uae30\ub85c \ud55c\ub2e4. \uadf8 \ub3c8\uc744 \ubcf4\ud0dc \uc9d0\uc758 \uc2dc\uacc4\uc5d0 \uc5b4\uc6b8\ub9ac\ub294 \uc904\uc744 \ucc3e\ub294\ub2e4. \ub0a8\ud3b8\uc740 \uc88b\uc740 \uc2dc\uacc4\ub97c \uac00\uc9c0\uace0\ub3c4 \ub0a1\uc740 \uc904 \ub54c\ubb38\uc5d0 \ub4dc\ub7ec\ub0b4\uae30\ub97c \uc870\uc2ec\uc2a4\ub7ec\uc6cc\ud588\ub2e4. \ub378\ub77c\uac00 \uace0\ub978 \uac83\uc740 \uadf8\ub0e5 \uac12\ube44\uc2fc \uc7a5\uc2e0\uad6c\uac00 \uc544\ub2c8\ub77c \uc9d0\uc774 \uac00\uc9c4 \uac83\uc744 \ub354 \uae30\uc058\uac8c \uc0ac\uc6a9\ud560 \uc218 \uc788\uac8c \ud574 \uc8fc\ub294 \ubb3c\uac74\uc774\ub2e4. \uc774 \uc120\ud0dd\uc5d0\ub294 \uc0c1\ub300\ub97c \ud3c9\uc18c\uc5d0 \ubcf4\uc544 \uc628 \uc2dc\uac04\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ubb34\uc5c7\uc744 \uc88b\uc544\ud558\uace0 \ubb34\uc5c7\uc744 \uc544\uc26c\uc6cc\ud558\ub294\uc9c0 \uc54c\uace0 \uc788\uae30 \ub54c\ubb38\uc5d0 \uc120\ubb3c\uc5d0 \uad6c\uccb4\uc801\uc778 \ubaa8\uc591\uc774 \uc0dd\uae34\ub2e4. \ub378\ub77c\ub294 \uc790\uae30 \uba38\ub9ac\uce74\ub77d\uc744 \uc783\uc9c0\ub9cc \ub0a8\ud3b8\uc5d0\uac8c \ud544\uc694\ud55c \uac83\uc744 \uc5bb\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4. \uc801\uc5b4\ub3c4 \uc774 \uc21c\uac04\uc5d0\ub294 \uc120\ubb3c\uc758 \uc4f0\uc784\uc774 \ubd84\uba85\ud574 \ubcf4\uc778\ub2e4. \uae30\uc05c \ub9c8\uc74c\uc73c\ub85c \ub3cc\uc544\uc628 \ub378\ub77c\ub294 \uc9e7\uc544\uc9c4 \uba38\ub9ac\ub97c \uc815\ub9ac\ud55c\ub2e4. \ub0a8\ud3b8\uc774 \uc790\uae30 \ubaa8\uc2b5\uc744 \ubcf4\uace0 \uc5b4\ub5bb\uac8c \uc0dd\uac01\ud560\uc9c0 \uac71\uc815\ud55c\ub2e4. \uc88b\uc740 \uc77c\uc744 \ud588\uc73c\ub2c8 \uc5b4\ub5a4 \ubd88\uc548\ub3c4 \uc5c6\uc744 \uac83\uc774\ub77c\ub294 \uc2dd\uc758 \uc778\ubb3c\uc774 \uc544\ub2c8\ub2e4. \uc0c1\ub300\ub97c \uc704\ud574 \ub0b4\ub193\uc740 \ub4a4\uc5d0\ub3c4 \uc790\uc2e0\uc774 \uc783\uc740 \ubaa8\uc2b5\uacfc \uc0ac\ub791\ubc1b\uace0 \uc2f6\uc740 \ub9c8\uc74c\uc740 \ub0a8\uc544 \uc788\ub2e4. \uc774 \uc791\uc740 \ub9dd\uc124\uc784 \ub54c\ubb38\uc5d0 \ub378\ub77c\ub294 \ud76c\uc0dd\uc758 \ud45c\uc5b4\ubcf4\ub2e4 \uc0b4\uc544 \uc788\ub294 \uc0ac\ub78c\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uc120\ubb3c\uc744 \uc900\ube44\ud558\ub294 \uae30\uc068\uacfc \ub2ec\ub77c\uc9c4 \uc678\ubaa8\uc5d0 \ub300\ud55c \uac71\uc815\uc774 \ub3d9\uc2dc\uc5d0 \uc788\ub2e4. \ub3c5\uc790\ub294 \uadf8\ub140\ub97c \uce6d\ucc2c\ud558\uae30 \uc804\uc5d0 \uc7a0\uae50 \ud568\uaed8 \uae30\ub2e4\ub9ac\uac8c \ub41c\ub2e4. \uc9d0\uc774 \ubb38\uc744 \uc5f4\uace0 \ub4e4\uc5b4\uc624\uba74 \uc5b4\ub5a4 \ud45c\uc815\uc744 \uc9c0\uc744\uc9c0 \uad81\uae08\ud574\uc9c4\ub2e4. \uc9d0\uc740 \ub378\ub77c\ub97c \ubcf4\uace0 \ub180\ub780\ub2e4. \ub378\ub77c\ub294 \uba38\ub9ac\uce74\ub77d\uc744 \uc798\ub790\uc5b4\ub3c4 \uc790\uc2e0\uc740 \uac19\uc740 \uc0ac\ub78c\uc774\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \uc7a0\uc2dc \ub3d9\uc548 \ub3c5\uc790\ub294 \uadf8\uac00 \ub2ec\ub77c\uc9c4 \uc678\ubaa8\ub97c \uc2eb\uc5b4\ud558\ub294 \uac83\uc778\uc9c0 \uac71\uc815\ud558\uac8c \ub41c\ub2e4. \uc791\uac00\ub294 \ub0a8\ud3b8\uc774 \uc54c\uace0 \ub3c5\uc790\ub294 \uc544\uc9c1 \ubaa8\ub974\ub294 \uc815\ubcf4\ub97c \ub4a4\uc5d0 \ub450\uc5b4 \uc9e7\uc740 \uae34\uc7a5\uc744 \ub9cc\ub4e0\ub2e4. \uc9d0\uc774 \uac00\uc838\uc628 \uc120\ubb3c\uc744 \ubcf4\uba74 \uc774\uc720\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \ub378\ub77c\uac00 \uc624\ub7ab\ub3d9\uc548 \uc9c4\uc5f4\uc7a5\uc5d0\uc11c \ubc14\ub77c\ubcf4\ub358 \uc544\ub984\ub2e4\uc6b4 \uba38\ub9ac \uc7a5\uc2dd \ube57\uc774\uc5c8\ub2e4. \uadf8\ub7f0\ub370 \uc774\uc81c \uadf8 \uc7a5\uc2dd\uc744 \uaf42\uc744 \uae34 \uba38\ub9ac\uce74\ub77d\uc774 \uc5c6\ub2e4. \uae30\uc05c \uc120\ubb3c\uc774 \uc0c1\uc2e4\uc744 \ubc14\ub85c \ubcf4\uc5ec \uc8fc\ub294 \ubb3c\uac74\uc774 \ub41c\ub2e4. \ub378\ub77c\uac00 \uc0c1\ub300\ub97c \ubcf4\uc544 \uc654\ub4ef \uc9d0\ub3c4 \ub378\ub77c\uc758 \uc18c\ub9dd\uc744 \uae30\uc5b5\ud558\uace0 \uc788\uc5c8\ub2e4. \ub378\ub77c\ub294 \uba38\ub9ac\uce74\ub77d\uc740 \ub2e4\uc2dc \uc790\ub780\ub2e4\uba70 \ub9c8\uc74c\uc744 \ucd94\uc2a4\ub974\uace0 \uc790\uc2e0\uc774 \uc900\ube44\ud55c \uc904\uc744 \ub0b4\ubbfc\ub2e4. \uc2dc\uacc4\uc5d0 \uc5f0\uacb0\ud55c \ubaa8\uc2b5\uc744 \ubcf4\uace0 \uc2f6\uc5b4 \ud55c\ub2e4. \uadf8\ub7f0\ub370 \uc9d0\uc740 \uadf8 \uc2dc\uacc4\ub97c \ud314\uc544 \uba38\ub9ac \uc7a5\uc2dd\uc744 \uc0c0\ub2e4\uace0 \ubc1d\ud78c\ub2e4. \uc11c\ub85c\ub97c \uc704\ud574 \uac00\uc7a5 \uc544\ub07c\ub358 \uac83\uc744 \ub0b4\ub193\uc558\uace0, \ubc14\ub85c \uadf8 \ub54c\ubb38\uc5d0 \ub450 \uc120\ubb3c\uc740 \ub2f9\uc7a5 \uc4f8 \uc218 \uc5c6\uac8c \ub418\uc5c8\ub2e4. \uc5ec\uae30\uc11c \ubc18\uc804\uc740 \uc0c8 \uc815\ubcf4 \ub450 \uac1c\ub97c \ub2e8\uc21c\ud788 \uad50\ud658\ud558\ub294 \uc7a5\uce58\uac00 \uc544\ub2c8\ub2e4. \uc55e\uc5d0\uc11c \uc758\ubbf8\ub97c \uc313\uc544 \ub454 \ub450 \ubcf4\ubb3c\uc774 \ub3d9\uc2dc\uc5d0 \uc6c0\uc9c1\uc600\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \uc11c\ub85c\uc5d0\uac8c \uc5c6\ub294 \ub9c8\uc74c\uc744 \uc694\uad6c\ud55c \uac83\uc774 \uc544\ub2c8\ub77c \uc790\uc2e0\uc5d0\uac8c \uc788\ub294 \uc18c\uc911\ud55c \uac83\uc744 \uc0ac\uc6a9\ud588\ub2e4. \uacc4\ud68d\uc758 \uacb0\uacfc\ub294 \uc5b4\uae0b\ub0ac\uc9c0\ub9cc \ub9c8\uc74c\uc758 \ubc29\ud5a5\uc740 \ub2ee\uc544 \uc788\uc5c8\ub2e4. \uacbd\uc81c\uc801\uc778 \uacc4\uc0b0\ub9cc \ud558\uba74 \ub450 \uc0ac\ub78c\uc740 \uc11c\ub85c \uc0c1\uc758\ud588\uc5b4\uc57c \ud588\ub2e4. \ub2f9\uc7a5 \uc4f8 \uc218 \uc788\ub294 \ubb3c\uac74\uc744 \uace0\ub974\ub294 \ub370\uc5d0\ub294 \ub354 \ub098\uc740 \ubc29\ubc95\ub3c4 \uc788\uc5c8\uc744 \uac83\uc774\ub2e4. \uc18c\uc124\ub3c4 \uadf8 \uc5b4\ub9ac\uc11d\uc74c\uc744 \uc804\ud600 \ubaa8\ub974\ub294 \ucc99\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc624\ud788\ub824 \uadf8 \uc5b4\uae0b\ub0a8\uc744 \ubd84\uba85\ud788 \ubcf4\uc5ec \uc900 \ub4a4 \ub2e4\ub978 \uae30\uc900\uc744 \ub0b4\ub193\ub294\ub2e4. \ub450 \uc0ac\ub78c\uc740 \uc0c1\ub300\uc5d0\uac8c \ubb34\uc5c7\uc774 \uae30\uc068\uc77c\uc9c0 \uc0dd\uac01\ud588\ub2e4. \uc544\ubb34\ub807\uac8c\ub098 \ud070\ub3c8\uc744 \uc4f0\ub824 \ud55c \uac83\uc774 \uc544\ub2c8\ub77c \uc0c1\ub300\uc758 \uc791\uc740 \uc18c\ub9dd\uc744 \uae30\uc5b5\ud588\ub2e4. \uadf8\ub798\uc11c \ub3c5\uc790\ub294 \uc120\ubb3c\uc758 \uc4f0\uc784\uacfc \uc120\ubb3c\uc744 \uc900\ube44\ud55c \uad00\uacc4\ub97c \ub098\ub204\uc5b4 \ubcf4\uac8c \ub41c\ub2e4. \ubb3c\uac74\uc744 \ub2f9\uc7a5 \uc0ac\uc6a9\ud560 \uc218 \uc5c6\ub2e4\ub294 \uacb0\uacfc\uac00 \uc0ac\ub791\uc744 \uc900\ube44\ud588\ub358 \uc2dc\uac04\uae4c\uc9c0 \uc5c6\uc560\uc9c0\ub294 \ubabb\ud55c\ub2e4. \ub9c8\uae30\ub294 \uc544\uae30 \uc608\uc218\uc5d0\uac8c \uc120\ubb3c\uc744 \uac00\uc838\uc628 \uc9c0\ud61c\ub85c\uc6b4 \uc0ac\ub78c\ub4e4\uc744 \uac00\ub9ac\ud0a8\ub2e4. \uc791\uac00\ub294 \ub9c8\uc9c0\ub9c9\uc5d0 \ub378\ub77c\uc640 \uc9d0\uc744 \uadf8 \uc774\ub984\uc5d0 \uc5f0\uacb0\ud55c\ub2e4. \uacc4\uc0b0\uc744 \uc798\ubabb\ud55c \ub450 \uc0ac\ub78c\uc774 \uac00\uc7a5 \uc9c0\ud61c\ub85c\uc6b4 \uc120\ubb3c\uc744 \ud588\ub2e4\ub294 \uc5ed\uc124\uc774\ub2e4. \uc774\ub54c \uc9c0\ud61c\ub294 \uc774\uc775\uc744 \ucd5c\ub300\ud55c \ub0a8\uae30\ub294 \ub2a5\ub825\uacfc\ub294 \ub2e4\ub978 \ub73b\uc744 \uc5bb\ub294\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc9c4\uc2ec\uc744 \ubcf4\uc774\ub824\uba74 \uc5b8\uc81c\ub098 \uac00\uc7a5 \uc544\ub07c\ub294 \uac83\uc744 \ud314\uc544\uc57c \ud55c\ub2e4\ub294 \uc0dd\ud65c\uc758 \uaddc\uce59\uc740 \uc544\ub2c8\ub2e4. \uac00\ub09c\uc744 \uc544\ub984\ub2e4\uc6b4 \uc2dc\ud5d8\uc73c\ub85c\ub9cc \uafb8\ubbf8\uba74 \ucc98\uc74c\uc758 \ub2f5\ub2f5\ud55c \uc0dd\ud65c\ub3c4 \uc9c0\uc6cc\uc9c4\ub2e4. \uc774 \uc9e7\uc740 \uc18c\uc124\uc774 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \ud2b9\uc815\ud55c \ub450 \uc0ac\ub78c\uc774 \ub9de\uc740 \ud06c\ub9ac\uc2a4\ub9c8\uc2a4\ub2e4. \uc6b0\ub9ac\ub294 \uadf8 \uc120\ud0dd\uc744 \uadf8\ub300\ub85c \ud749\ub0b4 \ub0b4\uc9c0 \uc54a\uace0\ub3c4 \uadf8 \uc548\uc758 \ub9c8\uc74c\uc744 \uc77d\uc744 \uc218 \uc788\ub2e4. \uacb0\ub9d0\uc5d0\uc11c \ub450 \uc0ac\ub78c\uc740 \uc120\ubb3c\uc744 \uc7a0\uc2dc \uac04\uc9c1\ud558\uace0 \uc800\ub141\uc744 \uba39\uc73c\ub824 \ud55c\ub2e4. \uc0b6\uc740 \ubc18\uc804\uc774 \ubc1d\ud600\uc9c4 \ub4a4\uc5d0\ub3c4 \uacc4\uc18d\ub41c\ub2e4. \ub0b4\uc77c\uc758 \ub3c8 \ubb38\uc81c\uac00 \ub2e4 \ud574\uacb0\ub41c \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc \uc624\ub298 \uc0c1\ub300\uac00 \uc790\uc2e0\uc744 \uc5b4\ub5bb\uac8c \ubcf4\uc544 \uc654\ub294\uc9c0\ub294 \uc54c\uac8c \ub418\uc5c8\ub2e4. \ub2f9\uc7a5 \uc4f0\uc9c0 \ubabb\ud558\ub294 \ubb3c\uac74\uc774 \uad00\uacc4\ub97c \ud655\uc778\ud558\ub294 \ubb3c\uac74\uc73c\ub85c \ubc14\ub010 \uc148\uc774\ub2e4. \ub2e4 \uc77d\uc740 \ub4a4 \ucc98\uc74c\uc758 1\ub2ec\ub7ec 87\uc13c\ud2b8\ub97c \ub5a0\uc62c\ub9ac\uba74 \uc22b\uc790\ub294 \uc5ec\uc804\ud788 \uc791\ub2e4. \uadf8\ub7f0\ub370 \uadf8 \ub3c8\uc73c\ub85c \ubb34\uc5c7\uc744 \ud558\uace0 \uc2f6\uc5c8\ub294\uc9c0\uc758 \uc774\uc57c\uae30\ub294 \ucee4\uc838 \uc788\ub2e4. \ub378\ub77c\uc640 \uc9d0\uc774 \uc8fc\uace0\ubc1b\uc740 \uac83\uc740 \ube57\uacfc \uc904\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ub9d0\ub85c \uc790\uc8fc \uc124\uba85\ud558\uc9c0 \uc54a\uc558\ub358 \uad00\uc2ec\uc774 \uc11c\ub85c \ub2e4\ub978 \ubb3c\uac74\uc5d0 \ub2f4\uaca8 \uac19\uc740 \uc9d1\uc73c\ub85c \ub3cc\uc544\uc628 \uc800\ub141\uc774\uc5c8\ub2e4."}, {"id": "gogol-nose-rank-and-recognition", "title": "\uace0\uace8\uc758 \ucf54 \u2014 \uc5bc\uad74\uc5d0\uc11c \uc0ac\ub77c\uc9c4 \ucf54\uac00 \ub098\ubcf4\ub2e4 \ub192\uc740 \uad00\ub9ac\ub77c\uba74", "summary": "\ube75 \uc18d\uc758 \ucf54\uc640 \ub192\uc740 \uad00\ub9ac\uac00 \ub41c \ucf54, \ub418\ub3cc\uc544\uc628 \uc77c\uc0c1\uc744 \ub530\ub77c \uc2e0\ubd84\uacfc \uad8c\uc704\uc758 \ud48d\uc790\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/gogol-nose-rank-and-recognition/index.html", "image": "../media/gogol-nose-rank-and-recognition.png", "alt": "\uad00\ubcf5\uc744 \uc785\uace0 \uac77\ub294 \ucee4\ub2e4\ub780 \ucf54\uc640 \ub180\ub780 \uad00\ub9ac\uac00 \uc788\ub294 \uace0\uace8\uc758 \ucf54 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uace0\uace8\uc758 \ucf54 \u2014 \uc5bc\uad74\uc5d0\uc11c \uc0ac\ub77c\uc9c4 \ucf54\uac00 \ub098\ubcf4\ub2e4 \ub192\uc740 \uad00\ub9ac\ub77c\uba74 \uad00\ub4f1\uacfc \uccb4\uba74, \uc808\ucc28\uc640 \ud658\uc0c1\uc774 \ub9cc\ub09c \ud398\ud14c\ub974\ubd80\ub974\ud06c\uc758 \ud48d\uc790 \ube75 \uc18d\uc758 \ucf54\uc640 \ub192\uc740 \uad00\ub9ac\uac00 \ub41c \ucf54, \ub418\ub3cc\uc544\uc628 \uc77c\uc0c1\uc744 \ub530\ub77c \uc2e0\ubd84\uacfc \uad8c\uc704\uc758 \ud48d\uc790\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \uc5b4\ub290 \uc544\uce68 \uc774\ubc1c\uc0ac\ub294 \ube75 \uc18d\uc5d0\uc11c \ucf54\ub97c \ubc1c\uacac\ud558\uace0, \ud55c \uad00\ub9ac\ub294 \uc790\uae30 \uc5bc\uad74\uc5d0\uc11c \ucf54\uac00 \uc0ac\ub77c\uc9c4 \uac83\uc744 \uc54c\uac8c \ub41c\ub2e4. \uace0\uace8\uc758 \u300c\ucf54\u300d\ub294 \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b4 \uc0ac\uac74\uc744 \ub9e4\uc6b0 \uad6c\uccb4\uc801\uc778 \uc77c\uc0c1\uc758 \ub9d0\ud22c\ub85c \uc804\ud55c\ub2e4. \uc6c3\uc74c\uc774 \ub098\ub294 \ub3d9\uc548 \uc2e0\ubd84\uacfc \uccb4\uba74\uc744 \ub458\ub7ec\uc2fc \uc9c8\uc11c\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \uc544\ub798\uc5d0\ub294 \uc0ac\uac74\uc758 \uc804\uac1c\uc640 \uacb0\ub9d0\uc774 \ud3ec\ud568\ub41c\ub2e4. \uc774\ubc1c\uc0ac \uc774\ubc18 \uc57c\ucf54\ube14\ub808\ube44\uce58\ub294 \ud3c9\ubc94\ud55c \uc2dd\uc0ac \uc911 \uc788\uc744 \uc218 \uc5c6\ub294 \uac83\uc744 \ubc1c\uacac\ud55c\ub2e4. \uadf8\ub294 \uadf8\uac83\uc774 \uc790\uae30\uac00 \uba74\ub3c4\ud574 \uc8fc\ub358 \uc0ac\ub78c\uc758 \ucf54\uc784\uc744 \uc54c\uc544\ubcf4\uace0 \ub450\ub824\uc6cc\ud55c\ub2e4. \ubb34\uc5c7\uc774 \uc77c\uc5b4\ub0ac\ub294\uc9c0\ubcf4\ub2e4 \ub204\uac00 \uc790\uc2e0\uc744 \uc758\uc2ec\ud560\uc9c0, \uc5b4\ub5bb\uac8c \uce58\uc6cc\uc57c \ud560\uc9c0\ub97c \uba3c\uc800 \uac71\uc815\ud55c\ub2e4. \ud55c\ud3b8 \ucf54\ubc1c\ub8cc\ud504\ub294 \uac70\uc6b8\uc744 \ubcf4\uace0 \uc790\uae30 \ucf54\uac00 \uc5c6\uc5b4\uc9c4 \uc0ac\uc2e4\uc744 \uc548\ub2e4. \ubab8\uc758 \uc77c\ubd80\uac00 \uc0ac\ub77c\uc84c\ub2e4\ub294 \ucda9\uaca9\uc740 \uace7 \uc0ac\ub78c\ub4e4 \uc55e\uc5d0 \ub098\uc124 \uc218 \uc5c6\ub2e4\ub294 \ubb38\uc81c\ub85c \uc774\uc5b4\uc9c4\ub2e4. \uc791\ud488\uc740 \ud658\uc0c1\uc801\uc778 \uc0ac\uac74\uc744 \uacbd\ucc30\uacfc \uc9c1\uc5c5, \uc678\ubaa8\uc640 \ud3c9\ud310\uc774\ub77c\ub294 \uc775\uc219\ud55c \uad00\uacc4 \uc548\uc5d0 \ub193\ub294\ub2e4. \ucf54\ubc1c\ub8cc\ud504\ub294 \uc790\uc2e0\uc744 \ub354 \uadf8\ub7f4\ub4ef\ud558\uac8c \ubcf4\uc774\uac8c \ud558\ub294 \ud638\uce6d\uc744 \uc88b\uc544\ud55c\ub2e4. \uadf8\uc5d0\uac8c \uc2e0\ubd84\uc740 \uc774\ub984 \uc55e\uc5d0 \ubd99\ub294 \ub9d0 \uc774\uc0c1\uc774\ub2e4. \ub204\uad6c\ub97c \ub9cc\ub098\uace0 \uc5b4\ub5a4 \uae30\ud68c\ub97c \uc5bb\uc744\uc9c0, \uacb0\ud63c\uc744 \uc5b4\ub5bb\uac8c \uc0dd\uac01\ud560\uc9c0\ub3c4 \uccb4\uba74\uacfc \uc5f0\uacb0\ub41c\ub2e4. \ucf54\uc758 \uc0c1\uc2e4\uc774 \uadf8\uc5d0\uac8c \ud2b9\ubcc4\ud788 \ud070 \uc0ac\ud68c\uc801 \uc7ac\ub09c\uc774 \ub418\ub294 \uc774\uc720\ub2e4. \uc5ec\uae30\uc11c \uc6c3\uc74c\uc740 \uc778\ubb3c \ud55c \uc0ac\ub78c\uc744 \ub180\ub9ac\ub294 \ub370\ub9cc \uc788\uc9c0 \uc54a\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\uc774 \ub098\ub97c \uc5b4\ub5a4 \uc9c1\ud568\uacfc \ubaa8\uc2b5\uc73c\ub85c \ubcfc \uac83\uc778\uc9c0\uc5d0 \uc0b6\uc758 \ub9ce\uc740 \ubd80\ubd84\uc774 \uac78\ub9b0 \uc9c8\uc11c\ub97c \ube44\ucd98\ub2e4. \uc5bc\uad74\uc5d0\uc11c \uc791\uc740 \ubd80\ubd84\uc774 \uc0ac\ub77c\uc84c\ub294\ub370 \uc0ac\ud68c \uc804\uccb4\uc640\uc758 \uad00\uacc4\uac00 \ud754\ub4e4\ub9ac\ub294 \uacfc\uc7a5\uc774 \ud48d\uc790\ub97c \ub9cc\ub4e0\ub2e4. \ucf54\ubc1c\ub8cc\ud504\ub294 \uac70\ub9ac\ub97c \ub2e4\ub2c8\ub294 \uc790\uae30 \ucf54\ub97c \ubcf8\ub2e4. \uadf8\ub7f0\ub370 \ucf54\ub294 \uad00\ubcf5\uc744 \uc785\uace0 \uc790\uc2e0\ubcf4\ub2e4 \ub192\uc740 \uc9c0\uc704\uc758 \uc778\ubb3c\ucc98\ub7fc \ud589\ub3d9\ud55c\ub2e4. \uc6d0\ub798 \ubab8\uc758 \uc77c\ubd80\uc600\ub358 \uac83\uc774 \uc774\uc81c\ub294 \ub3c5\ub9bd\ub41c \uad8c\uc704\uac00 \ub418\uc5c8\ub2e4. \uc8fc\uc778\uc740 \uc790\uae30 \uc18c\uc720\ub97c \ub3cc\ub824 \ub2ec\ub77c\uace0 \uc694\uad6c\ud574\uc57c \ud558\uc9c0\ub9cc \uc0c1\ub300\uc758 \uc9c0\uc704 \uc55e\uc5d0\uc11c \ub9d0\uc744 \uace0\ub978\ub2e4. \ucf54\ub294 \uadf8\uc640\uc758 \uad00\uacc4\ub97c \uc778\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub3c5\uc790\ub294 \uc774 \uc0c1\ud669\uc758 \ubd88\uac00\ub2a5\ud568\uc744 \uc54c\uba74\uc11c\ub3c4 \ud638\uce6d\uacfc \uc608\uc758\uac00 \uc791\ub3d9\ud558\ub294 \ubc29\uc2dd\uc740 \uc775\uc219\ud558\uac8c \ub290\ub080\ub2e4. \ubb34\uc5c7\uc774 \uc0ac\ub78c\uc744 \ub192\uc740 \uc0ac\ub78c\uc73c\ub85c \ubcf4\uc774\uac8c \ud558\ub294\uc9c0, \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5a4 \ud45c\uc9c0\ub97c \ubcf4\uace0 \ubcf5\uc885\ud558\ub294\uc9c0\uac00 \uae30\ubb18\ud558\uac8c \ub4dc\ub7ec\ub09c\ub2e4. \ubab8\uc758 \uc77c\ubd80\uac00 \uc790\uae30\ubcf4\ub2e4 \ub192\uc740 \uad00\ub4f1\uc758 \ubaa8\uc2b5\uc73c\ub85c \ub098\ud0c0\ub09c\ub2e4\ub294 \uc124\uc815\uc740 \uc6b0\uc5f0\ud55c \uc7a5\uc2dd\uc774 \uc544\ub2c8\ub2e4. \ucf54\ubc1c\ub8cc\ud504\uac00 \ud3c9\uc18c \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud558\ub358 \uae30\uc900\uc774 \uc790\uae30 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub294 \uc21c\uac04\uc5d0\ub3c4 \uc7a5\uc560\ubb3c\uc774 \ub41c\ub2e4. \uc0c1\ub300\uc758 \uc815\uccb4\ub97c \uc54c\uace0 \uc788\ub2e4\uace0 \uc0dd\uac01\ud558\uba74\uc11c\ub3c4 \uc678\ud615\uc774 \ub098\ud0c0\ub0b4\ub294 \uad8c\uc704 \uc55e\uc5d0\uc11c \ub9dd\uc124\uc774\ub294 \uac83\uc774\ub2e4. \uc774 \uc7a5\uba74\uc744 \uc77d\uc744 \ub54c\uc5d0\ub294 \ucf54\uac00 \uc5b4\ub5bb\uac8c \uac77\ub294\uc9c0\ub97c \ud604\uc2e4\uc801\uc73c\ub85c \ubcf5\uc6d0\ud558\ub824 \uc560\uc4f0\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4. \uc791\ud488\uc740 \uc637\uacfc \uc774\ub3d9, \ub9d0\ud22c\uc640 \uc608\uc758\ub77c\ub294 \uad6c\uccb4\uc801\uc778 \ud45c\uc9c0\ub97c \ud1b5\ud574 \ubd88\uac00\ub2a5\ud55c \uc874\uc7ac\ub97c \uc0ac\ud68c \uc548\uc5d0\uc11c \uc791\ub3d9\ud558\uac8c \ud55c\ub2e4. \ud658\uc0c1\uc740 \ud604\uc2e4\uc744 \uc644\uc804\ud788 \ubc84\ub9b0 \uc138\uacc4\uac00 \uc544\ub2c8\ub77c \ud604\uc2e4\uc758 \uaddc\uce59 \uc77c\ubd80\ub97c \uadf9\ub2e8\uae4c\uc9c0 \ubc00\uc5b4\ubd99\uc778 \uc138\uacc4\ub2e4. \ub3c5\uc790\ub294 \uadf8 \ubd88\uac00\ub2a5\ud568\uc5d0 \uc6c3\uc73c\uba74\uc11c\ub3c4 \uc0ac\ub78c\ub4e4\uc774 \uc9c0\uc704\uc758 \ud45c\uc9c0\ub97c \uc54c\uc544\ubcf4\ub294 \ubc29\uc2dd\uc740 \ub0af\uc124\uc9c0 \uc54a\ub2e4\uace0 \ub290\ub084 \uc218 \uc788\ub2e4. \uc775\uc219\ud55c \uccb4\uacc4\uac00 \uae30\uc774\ud55c \ubab8\uc744 \ud1b5\ud574 \uc0c8\ub86d\uac8c \ub4dc\ub7ec\ub098\ub294 \uc21c\uac04\uc774\ub2e4. \ucf54\ubc1c\ub8cc\ud504\ub294 \uc18c\ubb38\uc744 \ub0b4\uac70\ub098 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub824\uace0 \uc5ec\ub7ec \uacf3\uc744 \ucc3e\ub294\ub2e4. \uc2e0\ubb38 \uad11\uace0\ub97c \ud1b5\ud574 \uc54c\ub9ac\uace0 \uc2f6\uc9c0\ub9cc \uc2e0\ubb38\uc758 \uccb4\uba74\uacfc \uc6b4\uc601 \ub17c\ub9ac\uac00 \uadf8 \uc694\uccad\uc744 \ub9c9\ub294\ub2e4. \uc808\ubc15\ud55c \uac1c\uc778\uc758 \uc0ac\uac74\uc774 \uae30\uad00\uc758 \uad00\ub840 \uc18d\uc5d0\uc11c\ub294 \ub2e4\ub978 \uc885\ub958\uc758 \ubb38\uc81c\uac00 \ub41c\ub2e4. \uc758\uc0ac\uc5d0\uac8c \uac00\ub3c4 \uc6d0\ud558\ub294 \ud574\uacb0\uc744 \uc5bb\uc9c0 \ubabb\ud55c\ub2e4. \ucf54\uac00 \uc5c6\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub108\ubb34 \uc774\uc0c1\ud574\uc11c \uc124\uba85\ub418\uc9c0 \uc54a\ub294 \ub3d9\uc548, \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\uc740 \uc800\ub9c8\ub2e4 \uc775\uc219\ud55c \ubc29\uc2dd\uc73c\ub85c \ubc18\uc751\ud55c\ub2e4. \uc138\uacc4 \uc804\uccb4\uac00 \uba48\ucd94\uae30\ubcf4\ub2e4 \uc77c\uc0c1\uc758 \uc808\ucc28\uac00 \uae30\uc774\ud55c \uc0ac\uac74\uc744 \ub458\ub7ec\uc2f8\uace0 \uacc4\uc18d \ub3cc\uc544\uac00\ub294 \uc810\uc774 \ub354 \uc6b0\uc2a4\uc6b0\uba74\uc11c \ubd88\ud3b8\ud558\ub2e4. \uacbd\ucc30\uc744 \ud1b5\ud574 \ucf54\ub97c \ub3cc\ub824\ubc1b\ub294 \uacfc\uc815\uc5d0\uc11c\ub3c4 \uc0ac\uac74\uc740 \uae54\ub054\ud558\uac8c \ud574\uacb0\ub418\uc9c0 \uc54a\ub294\ub2e4. \ucf54\uac00 \uc190\uc5d0 \uc788\ub2e4\uace0 \uc5bc\uad74\uc5d0 \ub2e4\uc2dc \ubd99\uc77c \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\uae30 \ub54c\ubb38\uc774\ub2e4. \uc6d0\ub798\uc758 \ubb3c\uac74\uc744 \ucc3e\uc558\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc6d0\ub798 \uc0c1\ud0dc\ub97c \ud68c\ubcf5\ud588\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub974\ub2e4. \ucf54\ubc1c\ub8cc\ud504\ub294 \ub204\uac00 \uc790\uc2e0\uc5d0\uac8c \uc774\ub7f0 \uc77c\uc744 \ud588\uc744\uc9c0 \uc758\uc2ec\ud558\uba70 \uc6d0\uc778\uc744 \ucc3e\uc73c\ub824 \ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc791\ud488\uc740 \ub3c5\uc790\uac00 \ub0a9\ub4dd\ud560 \ub9cc\ud55c \ud55c \uac00\uc9c0 \uc778\uacfc\uad00\uacc4\ub97c \uc81c\uacf5\ud558\uc9c0 \uc54a\ub294\ub2e4. \ubb34\uc5b8\uac00\ub97c \ub418\ucc3e\uae30 \uc704\ud55c \ud589\ub3d9\uc740 \uacc4\uc18d\ub418\uc9c0\ub9cc \uadf8 \ud589\ub3d9\uc758 \ud569\ub9ac\uc131\uc774 \uae30\uc774\ud55c \uc138\uacc4 \uc804\uccb4\ub97c \ubc14\ub85c\uc7a1\uc9c0\ub294 \ubabb\ud55c\ub2e4. \ub9c8\uce68\ub0b4 \ucf54\ub294 \ucc98\uc74c\ubd80\ud130 \uc544\ubb34 \uc77c\ub3c4 \uc5c6\uc5c8\ub358 \uac83\ucc98\ub7fc \uc5bc\uad74\ub85c \ub3cc\uc544\uc628\ub2e4. \ucf54\ubc1c\ub8cc\ud504\ub294 \uae30\ubed0\ud558\uba70 \uc77c\uc0c1\uc73c\ub85c \ubcf5\uadc0\ud55c\ub2e4. \uc65c \uc0ac\ub77c\uc84c\uace0 \uc65c \ub3cc\uc544\uc654\ub294\uc9c0\uc5d0 \ub300\ud55c \ucda9\ubd84\ud55c \uc124\uba85\uc740 \ub0a8\uc9c0 \uc54a\ub294\ub2e4. \uc0ac\uac74\uc758 \ud574\uacb0\uacfc \uc0ac\uac74\uc758 \uc774\ud574\uac00 \uc11c\ub85c \uac08\ub77c\uc9c4\ub2e4. \ub2ec\ub77c\uc9c4 \uc77c\uc744 \uacaa\uc5c8\ub2e4\uace0 \uc778\ubb3c\uc758 \uac00\uce58\uad00\uc774 \ud06c\uac8c \ubc14\ub00c\uc5c8\ub2e4\uace0 \ub2e8\uc815\ud558\uae30\ub3c4 \uc5b4\ub835\ub2e4. \uadf8\ub294 \ub2e4\uc2dc \uc790\uc2e0\uc744 \ubcf4\uc774\uace0 \uc0ac\ub78c\ub4e4\uc744 \ub9cc\ub098\uba70 \uc774\uc804\uc758 \uad00\uc2ec\uc744 \uc774\uc5b4 \uac04\ub2e4. \ud48d\uc790\ub294 \uad50\ud6c8\uc744 \uc5bb\uc740 \uc8fc\uc778\uacf5\uc758 \uc131\uc7a5\uc73c\ub85c \uc815\ub9ac\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc775\uc219\ud55c \uc0ac\ud68c\uac00 \uacc4\uc18d\ub41c\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uacb0\ub9d0\uc758 \ud55c \ubd80\ubd84\uc774\ub2e4. \ub05d\ubd80\ubd84\uc758 \uc11c\uc220\uc790\ub294 \uc774 \uc774\uc57c\uae30\uac00 \uc65c \uadf8\ub807\uac8c \ub418\uc5c8\ub294\uc9c0 \uc2a4\uc2a4\ub85c \uc774\uc0c1\ud558\uac8c \uc5ec\uae30\ub294 \ud0dc\ub3c4\ub97c \ubcf4\uc778\ub2e4. \uc77d\ub294 \uc0ac\ub78c\uc758 \uc758\ubb38\uc744 \ubbf8\ub9ac \ub9d0\ud558\uba74\uc11c\ub3c4 \uc81c\ub300\ub85c \uc124\uba85\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc791\ud488\uc740 \uc9c4\uc9dc \uc788\uc5c8\ub358 \uc0ac\uac74\ucc98\ub7fc \uc138\ubd80\ub97c \uc313\ub2e4\uac00 \uadf8\ub7f4\ub4ef\ud568\uc758 \ubc14\ub2e5\uc744 \ud754\ub4e0\ub2e4. \u300c\ucf54\u300d\ub294 \ud669\ub2f9\ud55c \uc77c\uc744 \uc0c1\uc0c1\ud558\ub294 \uc7ac\ubbf8\uc5d0 \ub354\ud574 \uad8c\uc704\uac00 \uc5b4\ub5a4 \ubaa8\uc2b5\uc73c\ub85c \ud1b5\uc6a9\ub418\ub294\uc9c0 \ubb3b\ub294\ub2e4. \ucf54\uac00 \ub192\uc740 \uad00\ub9ac\ucc98\ub7fc \ubcf4\uc774\uba74 \uc0ac\ub78c\ub4e4\uc740 \uadf8 \uc55e\uc5d0\uc11c \uc9c0\uc704\ub97c \uc758\uc2dd\ud55c\ub2e4. \ud604\uc2e4\uc758 \uaddc\uce59\uc744 \uc9c0\ud0a4\ub294 \ub9d0\ud22c\uac00 \ubd88\uac00\ub2a5\ud55c \uc0c1\ud669\uacfc \ub9cc\ub0a0 \ub54c, \uace0\uace8\uc758 \ud48d\uc790\ub294 \uc544\uc8fc \ub0af\uc124\uace0\ub3c4 \uc54c\uc544\ubcfc \uc218 \uc788\ub294 \uc5bc\uad74\uc744 \uc5bb\ub294\ub2e4."}, {"id": "gogol-overcoat-clerk-and-city", "title": "\uace0\uace8\uc758 \uc678\ud22c \u2014 \uc0c8 \uc637 \ud55c \ubc8c\uc774 \ud55c \uc0ac\ub78c\uc758 \uc138\uacc4\ub97c \ubc14\uafc0 \ub54c", "summary": "\uc791\uc740 \uad00\ub9ac\uc758 \uc0c8 \uc678\ud22c\uc640 \uc0c1\uc2e4, \ub3c4\uc2dc\uc758 \uc720\ub839 \uc18c\ubb38\uc5d0\uc11c \uac00\ub09c\uacfc \uc704\uacc4\uc758 \ubb38\uc81c\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/gogol-overcoat-clerk-and-city/index.html", "image": "../media/gogol-overcoat-clerk-and-city.png", "alt": "\ub208 \ub0b4\ub9ac\ub294 \ud398\ud14c\ub974\ubd80\ub974\ud06c \uac70\ub9ac\uc5d0\uc11c \uc678\ud22c\ub97c \uc785\uc740 \ud558\uae09 \uad00\ub9ac\ub97c \uadf8\ub9b0 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uace0\uace8\uc758 \uc678\ud22c \u2014 \uc0c8 \uc637 \ud55c \ubc8c\uc774 \ud55c \uc0ac\ub78c\uc758 \uc138\uacc4\ub97c \ubc14\uafc0 \ub54c \ubb38\uc11c \uc815\uc11c\uc6d0 \uc544\uce74\ud0a4\uc758 \uc0dd\ud65c\uc5d0\uc11c \uc77d\ub294 \ube48\uace4\u00b7\uc704\uacc4\u00b7\uc720\ub839\uc758 \uc5ec\uc6b4 \uc791\uc740 \uad00\ub9ac\uc758 \uc0c8 \uc678\ud22c\uc640 \uc0c1\uc2e4, \ub3c4\uc2dc\uc758 \uc720\ub839 \uc18c\ubb38\uc5d0\uc11c \uac00\ub09c\uacfc \uc704\uacc4\uc758 \ubb38\uc81c\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \ub0a1\uc740 \uc678\ud22c\ub97c \uc0c8\uac83\uc73c\ub85c \ubc14\uafb8\ub294 \uc77c\uc774 \ud55c \uc0ac\ub78c\uc758 \uc778\uc0dd\uc5d0\uc11c \uac00\uc7a5 \ud070 \uc0ac\uac74\uc774 \ub420 \uc218 \uc788\uc744\uae4c. \ub2c8\ucf5c\ub77c\uc774 \uace0\uace8\uc758 \u300e\uc678\ud22c\u300f\uc5d0\uc11c\ub294 \uadf8\ub807\ub2e4. \ub7ec\uc2dc\uc544\uc758 \ud558\uae09 \uad00\ub9ac \uc544\uce74\ud0a4 \uc544\uce74\ud0a4\uc608\ube44\uce58\ub294 \uc791\uc740 \ubd09\uae09\uc73c\ub85c \uc0b4\uc544\uac00\uba70 \ubb38\uc11c\ub97c \ubca0\uaef4 \uc4f0\ub294 \uc77c\uc5d0 \uc775\uc219\ud55c \uc0ac\ub78c\uc774\ub2e4. \uadf8\uc758 \uc138\uacc4\uc5d0 \uc0c8 \uc678\ud22c\uac00 \ub4e4\uc5b4\uc624\uba74\uc11c \uc870\uc6a9\ud55c \uc77c\uc0c1\uc774 \ud754\ub4e4\ub9b0\ub2e4. \uc774 \uc791\ud488\uc740 \uac00\ub09c\ud55c \uad00\ub9ac\uc758 \ubd88\ud589\uc744 \ub4e4\ub824\uc8fc\uc9c0\ub9cc \uc5f0\ubbfc\ub9cc\uc73c\ub85c \uc4f0\uc778 \uc774\uc57c\uae30\ub294 \uc544\ub2c8\ub2e4. \uc6b0\uc2a4\uc6b4 \uc774\ub984\uacfc \ub9d0\ud22c, \uad00\ub8cc \uc870\uc9c1\uc758 \ud5c8\uc138\uc640 \uae30\ubb18\ud55c \uc18c\ubb38\uc774 \ud568\uaed8 \uc6c0\uc9c1\uc778\ub2e4. \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \ub530\ub77c\uac00\uba70 \uc6c3\uc74c\uc774 \uc5b4\ub290 \uc21c\uac04 \ubd88\ud3b8\ud568\uc73c\ub85c \ubc14\ub00c\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc544\uce74\ud0a4\ub294 \uc11c\ub958\ub97c \uc815\uc11c\ud558\ub294 \uc77c\uc744 \ud55c\ub2e4. \uc790\uae30 \uc0dd\uac01\uc744 \ud3bc\uce58\ub294 \ubb38\uc7a5\uc744 \uc4f0\uae30\ubcf4\ub2e4 \uc774\ubbf8 \uc788\ub294 \ubb38\uc11c\ub97c \uc815\ud655\ud788 \uc62e\uae34\ub2e4. \ub3d9\ub8cc\ub4e4\uc740 \uadf8\ub97c \ub300\ub2e8\ud55c \uc778\ubb3c\ub85c \uc5ec\uae30\uc9c0 \uc54a\uace0 \ub180\ub9ac\uae30\ub3c4 \ud55c\ub2e4. \uadf8\uc758 \uc0b6\uc740 \ub192\uc740 \uad00\ub9ac\uc758 \uc5c5\uc801\uc774\ub098 \ub3c4\uc2dc\uc758 \ud654\ub824\ud55c \uc18c\ubb38\uc5d0 \uc880\ucc98\ub7fc \ub4e4\uc5b4\uac00\uc9c0 \uc54a\ub294\ub2e4. \uadf8\ub7f0\ub370 \uace0\uace8\uc740 \ubc14\ub85c \uadf8 \uc0ac\ub78c\uc744 \uc774\uc57c\uae30\uc758 \uc911\uc2ec\uc5d0 \ub454\ub2e4. \ub0a8\ub4e4\uc774 \uc9c0\ub098\uccd0 \ubc84\ub9b4 \uc0ac\uc18c\ud55c \uc0dd\ud65c\uc744 \uae38\uac8c \ub4e4\uc5ec\ub2e4\ubcf4\ub294 \uac83\uc774\ub2e4. \ub3c5\uc790\ub294 \ucc98\uc74c\uc5d0\ub294 \ud76c\uadf9\uc801\uc778 \uc778\ubb3c\ucc98\ub7fc \ubcf4\ub358 \uad00\ub9ac\uc5d0\uac8c \uc810\ucc28 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \ub204\uac00 \uc774\uc57c\uae30\uc758 \uc8fc\uc778\uacf5\uc774 \ub420 \ub9cc\ud55c\uac00\ub77c\ub294 \uc624\ub798\ub41c \uae30\uc900\ub3c4 \ud568\uaed8 \ud754\ub4e4\ub9b0\ub2e4. \ud398\ud14c\ub974\ubd80\ub974\ud06c\uc758 \ucd94\uc704 \uc18d\uc5d0\uc11c \ub0a1\uc740 \uc678\ud22c\ub294 \ub354\ub294 \ubab8\uc744 \uc9c0\ucf1c \uc8fc\uae30 \uc5b4\ub835\ub2e4. \uc544\uce74\ud0a4\ub294 \uc218\uc120\uacf5 \ud398\ud2b8\ub85c\ube44\uce58\uc5d0\uac8c \uc637\uc744 \uac00\uc838\uac00\uc9c0\ub9cc \uc218\uc120\uc73c\ub85c \ud574\uacb0\ud558\uae30 \ud798\ub4e4\ub2e4\ub294 \ub9d0\uc744 \ub4e3\ub294\ub2e4. \uc0c8\ub85c\uc6b4 \uc678\ud22c\uac00 \ud544\uc694\ud574\uc9c4\ub2e4. \ubd80\uc720\ud55c \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc120\ud0dd\uc758 \ubb38\uc81c\uc77c \uc218 \uc788\uc9c0\ub9cc \uadf8\uc5d0\uac8c\ub294 \uc0dd\ud65c \uc804\uccb4\ub97c \uc870\uc815\ud574\uc57c \ud558\ub294 \uc77c\uc774\ub2e4. \uc637\uc740 \uc5ec\uae30\uc11c \uafb8\ubc08\uacfc \uccb4\uba74\ub9cc\uc758 \ubb3c\uac74\uc774 \uc544\ub2c8\ub2e4. \ubc16\uc73c\ub85c \ub098\uac00 \uc77c\ud558\uace0 \ub2e4\uc2dc \uc9d1\uc73c\ub85c \ub3cc\uc544\uc624\uae30 \uc704\ud574 \ud544\uc694\ud55c \ubcf4\ud638\ub9c9\uc774\ub2e4. \ucd94\uc704\uc5d0 \ucde8\uc57d\ud55c \ubab8\uacfc \uc801\uc740 \ubd09\uae09\uc774 \ub9cc\ub098\uba74 \ub0a1\uc740 \ucc9c\uc758 \uad6c\uba4d\ub3c4 \ud070 \uc0ac\uac74\uc774 \ub41c\ub2e4. \uc18c\uc124\uc740 \uac00\ub09c\uc744 \ucd94\uc0c1\uc801\uc778 \uc22b\uc790\ubcf4\ub2e4 \uc774\ub7f0 \uad6c\uccb4\uc801\uc778 \ubd88\ud3b8\uc73c\ub85c \ubcf4\uc5ec \uc900\ub2e4. \uc544\uce74\ud0a4\ub294 \uc0c8 \uc678\ud22c\ub97c \ub9c8\ub828\ud558\ub824\uace0 \uc0dd\ud65c\ube44\ub97c \uc904\uc778\ub2e4. \uc791\uc740 \uc990\uac70\uc6c0\uacfc \uc77c\uc0c1\uc758 \uc9c0\ucd9c\uc744 \ud3ec\uae30\ud558\ub294 \uc2dc\uac04\uc774 \uc774\uc5b4\uc9c4\ub2e4. \uc544\uc9c1 \uc190\uc5d0 \ub123\uc9c0 \ubabb\ud55c \ubb3c\uac74\uc774 \uadf8\uc758 \uc0dd\uac01\uc744 \ucc28\uc9c0\ud558\uba74\uc11c \uc774\uc804\uc5d0\ub294 \uc5c6\ub358 \uae30\ub300\uac00 \uc0dd\uae34\ub2e4. \uc678\ud22c\ub294 \ubbf8\ub798\ub97c \uae30\ub2e4\ub9ac\uac8c \ud558\ub294 \ub300\uc0c1\uc774 \ub41c\ub2e4. \uc774 \uae30\ub300\ub97c \ub2e8\uc21c\ud55c \ud5c8\uc601\uc774\ub77c\uace0 \ubd80\ub974\uae30\ub294 \uc5b4\ub835\ub2e4. \uadf8\uc5d0\uac8c\ub294 \uc0c8\ub85c\uc6b4 \uc0dd\ud65c\uc758 \uac00\ub2a5\uc131\uc744 \uc0c1\uc0c1\ud560 \uc5ec\uc9c0\uac00 \ub9ce\uc9c0 \uc54a\uc558\ub2e4. \uc637 \ud55c \ubc8c\uc5d0 \uc9c0\ub098\uce58\uac8c \ud070 \uc758\ubbf8\uac00 \uc2e4\ub9b0 \uac83\uc740 \ub9c8\uc74c\uc774 \uc595\uc544\uc11c\ub77c\uae30\ubcf4\ub2e4 \uc0b6\uc758 \uc120\ud0dd\uc9c0\uac00 \uc881\uc558\uae30 \ub54c\ubb38\uc774\ub2e4. \uc678\ud22c\ub97c \uae30\ub2e4\ub9ac\ub294 \ub3d9\uc548 \uadf8\ub294 \uc804\ubcf4\ub2e4 \uc0dd\uae30 \uc788\ub294 \uc0ac\ub78c\uc774 \ub41c\ub2e4. \ub9c8\uce68\ub0b4 \uc678\ud22c\uac00 \uc644\uc131\ub418\uc790 \uc0ac\ubb34\uc2e4 \uc0ac\ub78c\ub4e4\uc758 \ubc18\uc751\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \ub298 \ub180\ub9bc\uc744 \ubc1b\ub358 \uc0ac\ub78c\uc774 \ucd95\ud558\uc640 \uad00\uc2ec\uc758 \ub300\uc0c1\uc774 \ub41c\ub2e4. \uc0c8 \uc637\uc744 \uae30\ub150\ud558\ub294 \ubaa8\uc784\uae4c\uc9c0 \uc774\uc5b4\uc9c4\ub2e4. \uac19\uc740 \uc544\uce74\ud0a4\uc778\ub370 \uac89\uc744 \uac10\uc2fc \ubb3c\uac74\uc774 \ub2ec\ub77c\uc9c0\uc790 \uc8fc\uc704\uc758 \ub300\uc6b0\ub3c4 \ub2ec\ub77c\uc9c4 \uac83\uc774\ub2e4. \uc774 \ubcc0\ud654\ub294 \uae30\uc058\uba74\uc11c\ub3c4 \uc501\uc4f8\ud558\ub2e4. \uadf8\uac00 \uc774\uc804\uc5d0\ub294 \uc5c6\ub358 \ub2a5\ub825\uc744 \uac11\uc790\uae30 \uc5bb\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub3d9\ub8cc\ub4e4\uc740 \uc6d0\ub798 \uadf8\uacf3\uc5d0 \uc788\ub358 \uc0ac\ub78c\uc744 \uc774\uc81c\uc57c \ub2e4\ub974\uac8c \ubcf8\ub2e4. \uc637\uc774 \ubab8\uc744 \ub530\ub73b\ud558\uac8c \ud560 \ubfd0 \uc544\ub2c8\ub77c \uc0ac\ud68c\uc801 \uc874\uc7ac\uac10\uae4c\uc9c0 \ub9cc\ub4e4\uc5b4 \uc900\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc6c3\uc74c \uc18d\uc5d0 \ub4dc\ub7ec\ub09c\ub2e4. \ubaa8\uc784\uc5d0\uc11c \ub3cc\uc544\uc624\ub358 \uc544\uce74\ud0a4\ub294 \uac15\ub3c4\ub97c \ub9cc\ub098 \uc0c8 \uc678\ud22c\ub97c \ube7c\uc557\uae34\ub2e4. \uc624\ub79c \uc808\uc57d\uacfc \uae30\ub300\uac00 \ud55c\uc21c\uac04\uc5d0 \uc0ac\ub77c\uc9c4\ub2e4. \uac00\uaca9\ub9cc \ub530\uc9c0\uba74 \uc637 \ud55c \ubc8c\uc758 \uc190\uc2e4\uc774\uc9c0\ub9cc, \ub3c5\uc790\ub294 \uc774\ubbf8 \uadf8 \ubb3c\uac74\uc774 \uadf8\uc758 \uc0dd\ud65c\uc5d0\uc11c \ubb34\uc5c7\uc774\uc5c8\ub294\uc9c0 \uc54c\uace0 \uc788\ub2e4. \uadf8\ub798\uc11c \uc0ac\uac74\uc758 \ubb34\uac8c\ub294 \ubb3c\uac74\uac12\uc744 \ub118\uc5b4\uc120\ub2e4. \uc544\uce74\ud0a4\ub294 \ub3c4\uc6c0\uc744 \uad6c\ud558\ub824 \uc6c0\uc9c1\uc774\uc9c0\ub9cc \uad00\uccad\uacfc \uad8c\uc704\ub294 \uadf8\ub97c \ucda9\ubd84\ud788 \ubcf4\ud638\ud558\uc9c0 \ubabb\ud55c\ub2e4. \uc81c\ub300\ub85c \ub4e4\uc5b4 \uc8fc\ub294 \uc0ac\ub78c\uc744 \ub9cc\ub098\uae30 \uc5b4\ub824\uc6b4 \uc0c1\ud669\uc774 \ub610 \ub2e4\ub978 \uace0\ud1b5\uc774\ub2e4. \uc790\uc2e0\uc5d0\uac8c \uc77c\uc5b4\ub09c \uc77c\uc744 \uc124\uba85\ud558\uace0 \ubbff\uc5b4 \ub2ec\ub77c\uace0 \uc694\uccad\ud558\ub294 \ub370\uc5d0\ub3c4 \uc9c0\uc704\uac00 \uc601\ud5a5\uc744 \ubbf8\uce5c\ub2e4. \uc18c\uc124\uc740 \ucd94\uc704\ub9cc\ud07c\uc774\ub098 \ucc28\uac00\uc6b4 \uad00\uacc4\ub97c \ubcf4\uc5ec \uc900\ub2e4. \uc774\ub984 \ub300\uc2e0 \uc911\uc694\ud55c \uc778\ubb3c\ub85c \ubd88\ub9ac\ub294 \uace0\uc704 \uad00\ub9ac\uc5d0\uac8c \ub3c4\uc6c0\uc744 \uad6c\ud55c \uc544\uce74\ud0a4\ub294 \uad8c\uc704\uc801\uc778 \uc9c8\ucc45\uc744 \ubc1b\ub294\ub2e4. \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub294 \uc790\ub9ac\ubcf4\ub2e4 \uc704\uacc4\ub97c \ud655\uc778\ud558\ub294 \uc790\ub9ac\uac00 \ub418\uc5b4 \ubc84\ub9b0\ub2e4. \ub3c4\uc6c0\uc744 \uccad\ud55c \uc0ac\ub78c\uc758 \ucc98\uc9c0\ubcf4\ub2e4 \uc808\ucc28\uc640 \uccb4\uba74\uc744 \uc55e\uc138\uc6b0\ub294 \ubaa8\uc2b5\uc774 \ud76c\uadf9\uc801\uc73c\ub85c \uacfc\uc7a5\ub41c\ub2e4. \uc544\uce74\ud0a4\ub294 \uacb0\uad6d \ubcd1\ub4e4\uc5b4 \uc8fd\ub294\ub2e4. \uadf8\ub7f0\ub370 \uace0\uace8\uc740 \uc5ec\uae30\uc11c \ud604\uc2e4\uc801\uc778 \ube44\uadf9\ub9cc\uc73c\ub85c \uc774\uc57c\uae30\ub97c \ub2eb\uc9c0 \uc54a\ub294\ub2e4. \ub3c4\uc2dc\uc5d0\ub294 \uc8fd\uc740 \uad00\ub9ac \uac19\uc740 \uc720\ub839\uc774 \uc0ac\ub78c\ub4e4\uc758 \uc678\ud22c\ub97c \ube7c\uc557\ub294\ub2e4\ub294 \uc18c\ubb38\uc774 \ub3c8\ub2e4. \uc0b4\uc544 \uc788\uc744 \ub54c \ub4e4\ub9ac\uc9c0 \uc54a\ub358 \ubaa9\uc18c\ub9ac\uac00 \uc8fd\uc740 \ub4a4 \ubd88\uc628\ud55c \uc18c\ubb38\uc73c\ub85c \ub3cc\uc544\uc624\ub294 \uc148\uc774\ub2e4. \uc720\ub839\uc5d0 \uad00\ud55c \ub9c8\uc9c0\ub9c9 \ubd80\ubd84\uc740 \uae30\uc774\ud558\uace0 \uc6b0\uc2a4\uc6b0\uba70 \ub2e8\uc815\ud558\uae30 \uc5b4\ub835\ub2e4. \uc5b5\uc6b8\ud55c \uc0ac\ub78c\uc774 \uba85\ud655\ud558\uac8c \ubcf4\uc0c1\ubc1b\ub294 \uacb0\ub9d0\uc774\ub77c\uace0\ub9cc \uc77d\uc73c\uba74 \uc774 \uc5b4\uc0c9\ud55c \uc5ec\uc6b4\uc774 \uc904\uc5b4\ub4e0\ub2e4. \ub3c4\uc2dc\uc758 \uc18c\ubb38\uacfc \ud654\uc790\uc758 \ub9d0\uc774 \uacb9\uce58\uba70 \ud604\uc2e4\uacfc \ud658\uc0c1\uc758 \uacbd\uacc4\ub3c4 \ud754\ub4e4\ub9b0\ub2e4. \uace0\uace8\uc740 \ub3c5\uc790\ub97c \ud3b8\uc548\ud558\uac8c \uc704\ub85c\ud558\ub294 \ub370\uc11c \uba48\ucd94\uc9c0 \uc54a\ub294\ub2e4. \ubb38\uc11c\ub97c \ubca0\ub07c\ub294 \uadf8\uc758 \uc190\uc740 \ub0a8\ub4e4\uc758 \uc5c5\ubb34\uc5d0 \ubd84\uba85\ud788 \uc4f0\uc774\uace0 \uc788\uc5c8\ub2e4. \uadf8\ub7f0\ub370 \uadf8\uac00 \uc0ac\ub77c\uc9c4 \uc790\ub9ac\uc5d0\ub294 \ub2e4\ub978 \uc0ac\ub78c\uc774 \ub4e4\uc5b4\uc628\ub2e4. \uc77c\uc744 \ub300\uc2e0\ud560 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ud55c \uc0ac\ub78c\uc758 \uc0b6\uae4c\uc9c0 \uc911\uc694\ud558\uc9c0 \uc54a\ub2e4\ub294 \ub73b\uc778\uc9c0, \uc18c\uc124\uc740 \uadf8 \uc9e7\uc740 \uad50\uccb4\uc758 \uc7a5\uba74\uc73c\ub85c\ub3c4 \ubb3b\ub294\ub2e4. \uc0c8 \uc678\ud22c\uac00 \uc5c6\uc744 \ub54c\ub098 \uadf8\uac83\uc744 \uc5bb\uc5c8\uc744 \ub54c\ub098 \uc544\uce74\ud0a4\ub294 \uac19\uc740 \uc0ac\ub78c\uc774\uc5c8\ub2e4. \uadf8\ub7f0\ub370 \ub204\uad6c\ub3c4 \uadf8 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uadf8\ub97c \ucda9\ubd84\ud788 \ub300\uc6b0\ud558\uc9c0 \uc54a\uc558\ub2e4. \u300e\uc678\ud22c\u300f\uac00 \uc624\ub798 \ub0a8\uae30\ub294 \uc9c8\ubb38\uc740 \ubb3c\uac74\uc744 \uc798 \uc9c0\ucf1c\uc57c \ud55c\ub2e4\ub294 \uad50\ud6c8\uc774 \uc544\ub2c8\ub77c, \ud3c9\ubc94\ud558\uace0 \ud798\uc5c6\ub294 \uc0ac\ub78c\uc758 \uc0c1\uc2e4\uc744 \ub204\uac00 \uc9c4\uc9c0\ud558\uac8c \ub4e4\uc5b4 \uc8fc\ub294\uac00\uc5d0 \uc788\ub2e4."}, {"id": "goldberg-variations-return", "title": "\uace8\ub4dc\ubca0\ub974\ud06c \ubcc0\uc8fc\uace1 \u2014 \uac19\uc740 \uc74c\uc545\uc774 \ub3cc\uc544\uc640\ub3c4 \ub2e4\ub974\uac8c \ub4e4\ub9ac\ub294 \uc774\uc720", "summary": "\uace1\uc758 \uc774\ub984\uc5d0 \uc5bd\ud78c \uc804\uc2b9\uc744 \uad6c\ubd84\ud558\uace0, \ubc18\ubcf5\uacfc \ubcc0\ud615\uc744 \ub530\ub77c \ubc14\ud750\uc758 \uae34 \uc791\ud488\uc744 \ub4e3\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc74c\uc545", "categories": ["arts"], "url": "stories/goldberg-variations-return/index.html", "image": "../media/goldberg-variations-return.jpg", "alt": "\ud558\uc6b0\uc2a4\ub9cc\uc774 \uadf8\ub9b0 \uc694\ud55c \uc81c\ubc14\uc2a4\ud2f0\uc548 \ubc14\ud750 \ucd08\uc0c1\uc758 \uc61b \uc7ac\ud604 \ub3c4\ud310. \ubc14\ud750\uac00 \uc545\ubcf4\ub97c \ub4e4\uace0 \uc788\uc2b5\ub2c8\ub2e4.", "text": "\uace8\ub4dc\ubca0\ub974\ud06c \ubcc0\uc8fc\uace1 \u2014 \uac19\uc740 \uc74c\uc545\uc774 \ub3cc\uc544\uc640\ub3c4 \ub2e4\ub974\uac8c \ub4e4\ub9ac\ub294 \uc774\uc720 \uc544\ub9ac\uc544\uc640 \uc11c\ub978 \uac1c\uc758 \ubcc0\uc8fc, \uc7a0 \ubabb \ub4dc\ub294 \ubc31\uc791\uc758 \uc774\uc57c\uae30\ub97c \ub118\uc5b4\uc11c \uace1\uc758 \uc774\ub984\uc5d0 \uc5bd\ud78c \uc804\uc2b9\uc744 \uad6c\ubd84\ud558\uace0, \ubc18\ubcf5\uacfc \ubcc0\ud615\uc744 \ub530\ub77c \ubc14\ud750\uc758 \uae34 \uc791\ud488\uc744 \ub4e3\uc2b5\ub2c8\ub2e4. \uc74c\uc545 \ubb38\ud654\uc640 \uc608\uc220 \uc870\uc6a9\ud55c \uc544\ub9ac\uc544\uac00 \ub05d\ub09c \ub4a4 \uc74c\uc545\uc774 \uc5ec\ub7ec \ubaa8\uc2b5\uc73c\ub85c \ubc14\ub010\ub2e4. \uc5b4\ub5a4 \ubd80\ubd84\uc740 \uacbd\ucf8c\ud558\uace0 \uc5b4\ub5a4 \ubd80\ubd84\uc740 \ucd18\ucd18\ud558\uba70, \uc5b4\ub290 \uc21c\uac04\uc5d0\ub294 \uc2dc\uac04\uc774 \uae4a\uac8c \uac00\ub77c\uc549\ub294 \ub4ef\ud558\ub2e4. \uae34 \uae38\uc744 \uc9c0\ub09c \ub4a4 \ucc98\uc74c\uc758 \uc544\ub9ac\uc544\uac00 \ub2e4\uc2dc \ub098\uc628\ub2e4. \uac19\uc740 \uc74c\uc545\uc778\ub370 \ucc98\uc74c \ub4e4\uc744 \ub54c\uc640 \uac19\uc9c0 \uc54a\uac8c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ubc14\ud750\uc758 \u300a\uace8\ub4dc\ubca0\ub974\ud06c \ubcc0\uc8fc\uace1\u300b\uc740 \uadf8 \uacbd\ud5d8\uc744 \ub9cc\ub4dc\ub294 \uc791\ud488\uc774\ub2e4. \uc720\uba85\ud55c \uc774\ub984\uc758 \uc0ac\uc5f0\ub3c4 \ud765\ubbf8\ub86d\uc9c0\ub9cc, \ub4e3\ub294 \uc0ac\ub78c\uc5d0\uac8c \ub354 \uc624\ub798 \ub0a8\ub294 \uac83\uc740 \uac19\uc740 \ubc14\ud0d5\uc5d0\uc11c \uc5bc\ub9c8\ub098 \ub2e4\ub978 \uc138\uacc4\uac00 \ub098\uc62c \uc218 \uc788\ub290\ub0d0\ub294 \ub180\ub77c\uc6c0\uc774\ub2e4. \ud3ec\ub974\ucf08\uc774 1802\ub144\uc5d0 \uc4f4 \ubc14\ud750 \uc804\uae30\uc5d0\ub294 \ud55c \ubc31\uc791\uc758 \ubd88\uba74\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\uac00 \ub098\uc628\ub2e4. \uc7a0 \ubabb \ub4dc\ub294 \ubc24\uc5d0 \uc74c\uc545\uc744 \ub4e3\ub358 \ubc31\uc791\uc774 \uace8\ub4dc\ubca0\ub974\ud06c\uc5d0\uac8c \uc5f0\uc8fc\ud560 \uace1\uc744 \ubc14\ud750\uc5d0\uac8c \ubd80\ud0c1\ud588\uace0, \uc774 \ubcc0\uc8fc\uace1\uc774 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4\ub294 \uc804\uc2b9\uc774\ub2e4. \ud070 \ubcf4\uc0c1\uc744 \uc8fc\uc5c8\ub2e4\ub294 \uc77c\ud654\uae4c\uc9c0 \ub4a4\ub530\ub978\ub2e4. \ub2e4\ub9cc \uc774 \uc804\uae30\ub294 \uc791\ud488\uc758 \ud0c4\uc0dd\uc744 \uadf8 \uc790\ub9ac\uc5d0\uc11c \uae30\ub85d\ud55c \ub3d9\uc2dc\ub300 \uc77c\uc9c0\uac00 \uc544\ub2c8\ub2e4. \uc624\ub298\uc758 \ub300\uc870 \uc790\ub8cc\ub85c\ub294 \uadf8\ub7f0 \uc774\uc57c\uae30\uac00 \ud6c4\ub300\uc5d0 \uc804\ud574\uc84c\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \ub530\ub77c\uc11c \u2018\uc7a0\uc7ac\uc6b0\ub824\uace0 \uc8fc\ubb38\ubc1b\uc544 \ub9cc\ub4e0 \uc218\uba74 \uc74c\uc545\u2019\uc774\ub77c\uace0 \uc791\ud488\uc758 \ubaa9\uc801\uc744 \ub2e8\uc815\ud558\uc9c0 \ub9d0\uc790. \uc81c\ubaa9\uc758 \uc774\uc57c\uae30\uc640 \uc2e4\uc81c \uc74c\uc545\uc740 \uad6c\ubcc4\ud574 \ub4e4\uc744 \uc5ec\uc9c0\uac00 \uc788\ub2e4. \uc545\ubcf4\uc5d0\ub294 \uc544\ub9ac\uc544\uc640 \uc11c\ub978 \uac1c\uc758 \ubcc0\uc8fc\ub77c\ub294 \uad6c\uc131\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \ucc98\uc74c\uc758 \uc544\ub9ac\uc544\ub294 \uc138 \ubc15\uc758 \ud750\ub984 \uc18d\uc5d0\uc11c \uc7a5\uc2dd\ub41c \uc120\uc728\uc744 \ub4e4\ub824\uc900\ub2e4. \uc774\uc5b4\uc9c0\ub294 \ubcc0\uc8fc\ub4e4\uc740 \uac19\uc740 \uba5c\ub85c\ub514\ub97c \ub2e8\uc21c\ud788 \ube60\ub974\uac8c, \ub290\ub9ac\uac8c \ubc18\ubcf5\ud558\ub294 \ubc29\uc2dd\uc5d0 \uba38\ubb3c\uc9c0 \uc54a\ub294\ub2e4. \uc911\uc694\ud55c \uc5f0\uacb0\uc740 \uc74c\uc545 \uc544\ub798\ub97c \ubc1b\uce58\ub294 \ud654\uc131\uacfc \uad6c\uc870\uc5d0 \uc788\ub2e4. \uc120\uc728\uc758 \uac89\ubaa8\uc2b5\uc774 \ud06c\uac8c \ubc14\ub00c\uc5b4\ub3c4 \ubc14\ud0d5\uc758 \uae38\uc744 \uacf5\uc720\ud558\ub294 \uc148\uc774\ub2e4. \uc9d1\uc758 \uae30\ub465\uacfc \ubc29\uc758 \ud2c0\uc740 \uc774\uc5b4\uc9c0\ub294\ub370 \uadf8 \uc548\uc758 \uc0dd\ud65c\uacfc \ube5b\uc774 \ub2ec\ub77c\uc9c4\ub2e4\uace0 \uc0dd\uac01\ud574\ub3c4 \uc88b\ub2e4. \uc5b4\ub824\uc6b4 \uc6a9\uc5b4\ubcf4\ub2e4 \ud45c\uba74\uacfc \ubc14\ud0d5\uc774 \ub530\ub85c \uc6c0\uc9c1\uc77c \uc218 \uc788\ub2e4\ub294 \uac10\uac01\uc744 \uba3c\uc800 \uc7a1\uc544 \ubcf4\uc790. \uccab \ubcc0\uc8fc\ub97c \ub4e3\uace0 \u2018\ubc29\uae08 \uc544\ub9ac\uc544\uc640 \uc5b4\ub514\uac00 \uac19\uc9c0?\u2019 \ud558\uace0 \ub290\ub07c\ub294 \uac83\uc740 \uc790\uc5f0\uc2a4\ub7fd\ub2e4. \uc544\ub9ac\uc544\uc758 \ub178\ub798\ub97c \uadf8\ub300\ub85c \ud765\uc5bc\uac70\ub9ac\ub824 \ud558\uba74 \uc774\uc5b4\uc9c0\ub294 \uc74c\uc545\uc774 \ub0af\uc124 \uc218 \uc788\ub2e4. \ub300\uc2e0 \ubc15\uc790\uc758 \ud750\ub984\uacfc \uad6c\uc808\uc774 \ub9c8\ubb34\ub9ac\ub418\ub294 \uac10\uac01, \ub0ae\uc740 \uc74c\uc758 \ubc29\ud5a5\uc5d0 \uadc0\ub97c \uae30\uc6b8\uc5ec \ubcf4\uc790. \ucc98\uc74c \ub4e3\ub294 \uc790\ub9ac\uc5d0\uc11c \uc11c\ub978 \uace1\uc744 \ubc88\ud638\ub300\ub85c \uae30\uc5b5\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ubc1d\uac8c \ub6f0\ub294 \ubd80\ubd84\uc774 \uc788\ub294\uc9c0, \uc131\ubd80\uac00 \uc5bd\ud600 \ub4e4\ub9ac\ub294\uc9c0, \uc74c\uc774 \ub4dc\ubb38\ub4dc\ubb38 \ub193\uc774\ub294\uc9c0 \uc815\ub3c4\ub97c \uad6c\ubd84\ud574\ub3c4 \ucda9\ubd84\ud558\ub2e4. \ud558\ub098\uc758 \ud45c\uc815\uc73c\ub85c \ub05d\uae4c\uc9c0 \uc774\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ub290\ub07c\ub294 \ub370\uc11c \uac10\uc0c1\uc774 \uc2dc\uc791\ub41c\ub2e4. \uc81c3\ubcc0\uc8fc\uc758 \uc545\ubcf4\uc5d0\ub294 \uce74\ub17c\uc774\ub77c\ub294 \ud45c\uc81c\uac00 \uc788\ub2e4. \ud55c \uc131\ubd80\uac00 \ub0b4\ub193\uc740 \uc6c0\uc9c1\uc784\uc744 \ub2e4\ub978 \uc131\ubd80\uac00 \uc77c\uc815\ud55c \uac04\uaca9\uc744 \ub450\uace0 \ub530\ub77c\uc624\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc6b0\ub9ac\uac00 \ub3cc\ub9bc\ub178\ub798\uc5d0\uc11c \uacbd\ud5d8\ud558\ub294 \uc6d0\ub9ac\ub97c \ub5a0\uc62c\ub9ac\uba74 \uc9c4\uc785\ud558\uae30 \uc27d\ub2e4. \ub2e8\uc21c\ud788 \uac19\uc740 \uc18c\ub9ac\ub97c \ud06c\uac8c \uacb9\uce58\ub294 \uac83\uacfc\ub294 \ub2e4\ub974\ub2e4. \ub4e3\ub294 \uc0ac\ub78c\uc740 \uba3c\uc800 \uc55e\uc5d0 \ub098\uc628 \uc18c\ub9ac\ub97c \ucc3e\uace0, \ub4a4\uc5d0\uc11c \ube44\uc2b7\ud55c \uc6c0\uc9c1\uc784\uc774 \ub098\uc624\ub294\uc9c0 \uae30\ub2e4\ub824 \ubcfc \uc218 \uc788\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc18c\ub9ac\uac00 \uac01\uc790\uc758 \uae38\uc744 \uac00\uba74\uc11c \uc804\uccb4\ub97c \uc774\ub8ec\ub2e4\ub294 \uac83\uc774 \ubc14\ud750 \uc74c\uc545\uc758 \uc7ac\ubbf8 \uc911 \ud558\ub098\ub2e4. \ubaa8\ub4e0 \uaddc\uce59\uc744 \uc54c\uc544\ub9de\ud600\uc57c \uc990\uae38 \uc218 \uc788\ub294 \uc218\ud559 \uc2dc\ud5d8\uc740 \uc544\ub2c8\ub2e4. \uc81c25\ubcc0\uc8fc\ub294 \uc0ac\ub2e8\uc870\ub85c \ub418\uc5b4 \uc788\uc73c\uba70, \uc55e\ub4a4\uc758 \ud65c\uae30\ucc2c \ubd80\ubd84\uacfc \ub2e4\ub978 \ubb34\uac8c\ub97c \ub290\ub07c\uac8c \ud560 \uc218 \uc788\ub2e4. \uc5b4\ub5a4 \ud45c\uc815\uc744 \ub290\ub084\uc9c0\ub294 \ub4e3\ub294 \uc0ac\ub78c\uc758 \ubaab\uc774\uc9c0\ub9cc \uae34 \uc5ec\uc815\uc5d0\uc11c \uae4a\uc219\ud55c \uacf3\uc73c\ub85c \ub4e4\uc5b4\uc624\ub294 \ub4ef\ud55c \uacbd\ud5d8\uc744 \uc8fc\ub294 \ub300\ubaa9\uc774\ub2e4. \uac19\uc740 \ubc14\ud0d5 \uc704\uc5d0\uc11c\ub3c4 \uc74c\uc545\uc758 \uc815\uc11c\ub294 \ud06c\uac8c \ub2ec\ub77c\uc9c4\ub2e4. \uc2ac\ud508 \uc0ac\uc5f0\uc744 \ud558\ub098 \uc815\ud574 \uc74c\ub9c8\ub2e4 \ubc30\uc815\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4. \uc120\uc728\uc774 \uc5bc\ub9c8\ub098 \uc624\ub798 \uba38\ubb34\ub294\uc9c0, \ub2e4\ub978 \uc74c\uc774 \ub4e4\uc5b4\uc62c \ub54c \uae34\uc7a5\uc774 \uc5b4\ub5bb\uac8c \ub290\uaef4\uc9c0\ub294\uc9c0 \ub4e4\uc5b4 \ubcf4\uc790. \ube60\ub978 \uc190\ub180\ub9bc\ub9cc\uc774 \uc791\ud488\uc758 \ud48d\ubd80\ud568\uc744 \ub9cc\ub4dc\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\ub3c4 \uc774 \ubd80\ubd84\uc5d0\uc11c \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uc81c30\ubcc0\uc8fc\ub294 \ucffc\ub4e4\ub9ac\ubcb3\uc774\ub77c\ub294 \uc774\ub984\uc744 \uac00\uc9c4\ub2e4. \ud3ec\ub974\ucf08 \uc804\uae30\uc5d0 \ubd99\uc740 \ud574\uc124\uc740 \uc11c\ub85c \ub2e4\ub978 \ubbfc\uc694 \uc120\uc728\ub4e4\uc774 \uc4f0\uc600\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc5c4\uaca9\ud55c \uc9dc\uc784\uc744 \ub530\ub77c \uae34 \uae38\uc744 \uc628 \ub4a4 \uc0dd\ud65c \uc18d \ub178\ub798 \uac19\uc740 \uc131\uaca9\uc744 \ub9cc\ub098\ub294 \uc148\uc774\ub2e4. \uc5ec\uae30\uc11c\ub3c4 \ubc14\ud750\uc758 \uc74c\uc545\uc740 \ud55c \uac00\uc9c0 \uc704\uc5c4\ub9cc \uc720\uc9c0\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub2f9\uc2dc \ub178\ub798\uc758 \uac00\uc0ac\ub97c \ubaa8\ub450 \uc54c\uc9c0 \ubabb\ud574\ub3c4 \ub9c8\uc9c0\ub9c9 \ubd80\ubd84\uc758 \uc131\uaca9\uc774 \uc55e\uc758 \ubcc0\uc8fc\uc640 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0 \ub4e4\uc744 \uc218 \uc788\ub2e4. \ub0af\uc120 \uc774\ub984\uc774 \ub9ce\uc774 \ub098\uc640 \ubd80\ub2f4\uc2a4\ub7fd\ub2e4\uba74 \u2018\uc5ec\ub7ec \ub178\ub798\ub97c \ud568\uaed8 \ub193\ub294 \uc74c\uc545\u2019 \uc815\ub3c4\uc758 \uae38\uc7a1\uc774\ub85c \uc2dc\uc791\ud574\ub3c4 \uc88b\ub2e4. \uad6c\uccb4\uc801\uc778 \uc9c0\uc2dd\uc740 \ub2e4\uc2dc \ub4e4\uc744 \ub54c \uc870\uae08\uc529 \ubcf4\ud0dc\uba74 \ub41c\ub2e4. \ub9c8\uc9c0\ub9c9 \uc545\ubcf4\uc5d0\ub294 \ucc98\uc74c\uc758 \uc544\ub9ac\uc544\ub85c \ub3cc\uc544\uac00 \ub05d\ub0b4\ub77c\ub294 \uc9c0\uc2dc\uac00 \uc788\ub2e4. \uc0c8\ub85c\uc6b4 \uacb0\ub860\uc758 \uc120\uc728\uc744 \ub367\ubd99\uc774\ub294 \ub300\uc2e0 \ucd9c\ubc1c\ud588\ub358 \uc74c\uc545\uc744 \ub2e4\uc2dc \ub9cc\ub098\ub294 \uac83\uc774\ub2e4. \ub4e3\ub294 \uc0ac\ub78c\uc740 \uadf8 \uc0ac\uc774 \uc11c\ub978 \ubc88\uc758 \ub2e4\ub978 \ud48d\uacbd\uc744 \uc9c0\ub098\uc654\ub2e4. \uadf8\ub798\uc11c \uc74c\uc545\uc740 \uac19\uc544\ub3c4 \uae30\uc5b5\uc740 \uac19\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ub2e8\uc815\ud55c \uc2dc\uc791\uc73c\ub85c \ub4e4\ub838\ub358 \uc544\ub9ac\uc544\uac00 \ub05d\uc5d0\uc11c\ub294 \ud734\uc2dd\uc774\ub098 \ub3cc\uc544\uc634\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \uc791\uace1\uac00\uac00 \uc815\ud574 \uc900 \ud558\ub098\uc758 \uac10\uc815\uc774\ub77c\uace0 \ub2e8\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uad6c\uc870\uac00 \uccad\uc911\uc758 \uacbd\ud5d8\uc744 \uc5b4\ub5bb\uac8c \ubc14\uafb8\ub294\uc9c0 \uc2a4\uc2a4\ub85c \ub290\uaef4 \ubcf4\ub294 \ub300\ubaa9\uc774\ub2e4. \uba3c\uc800 \uc544\ub9ac\uc544\uc640 \uc81c1\ubcc0\uc8fc\ub97c \ub4e3\uace0, \ub2e4\uc74c\uc5d0\ub294 \uce74\ub17c\uc778 \uc81c3\ubcc0\uc8fc, \uc81c25\ubcc0\uc8fc, \ub9c8\uc9c0\ub9c9 \ubcc0\uc8fc\uc640 \ub3cc\uc544\uc628 \uc544\ub9ac\uc544\ub97c \ube44\uad50\ud574 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc804\uccb4\ub97c \ub2e4 \ub4e4\uc73c\uba74 \ud750\ub984\uc744 \ub354 \ub113\uac8c \ub290\ub084 \uc218 \uc788\uc9c0\ub9cc, \ucc98\uc74c\ubd80\ud130 \uae34 \uc2dc\uac04\uc744 \ub0b4\uc57c\ub9cc \uc2dc\uc791\ud560 \uc218 \uc788\ub294 \uc791\ud488\uc740 \uc544\ub2c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \ud558\uc6b0\uc2a4\ub9cc\uc774 \uadf8\ub9b0 \ubc14\ud750 \ucd08\uc0c1\uc758 \uc5ed\uc0ac\uc801 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \ubc31\uc791\uc758 \uce68\uc2e4\uc774\ub098 \ub2f9\uc2dc \uc5f0\uc8fc \uc7a5\uba74\uc744 \uc7ac\ud604\ud55c \uadf8\ub9bc\uc740 \uc544\ub2c8\ub2e4. \uc81c\ubaa9\uc758 \uc804\uc2b9\uc744 \ub4e3\ub294 \uc990\uac70\uc6c0 \uacc1\uc5d0, \uc74c\ub4e4\uc774 \uc2e4\uc81c\ub85c \ub9cc\ub4dc\ub294 \ubcc0\ud615\uacfc \uadc0\ud658\uc758 \uacbd\ud5d8\uc744 \ub450\uc5b4 \ubcf4\uc790. \uc65c \uac19\uc740 \uc74c\uc545\uc774 \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \uc870\uae08 \ub2e4\ub974\uac8c \ub4e4\ub9ac\ub294\uc9c0 \uc9c1\uc811 \ub9cc\ub0a0 \uc218 \uc788\ub2e4."}, {"id": "goya-third-may-lantern-and-facing-men", "title": "\uace0\uc57c\uc758 1808\ub144 5\uc6d4 3\uc77c \u2014 \ubd88\ube5b\uc740 \ub204\uad6c\uc758 \uc5bc\uad74\uc744 \ube44\ucd94\ub294\uac00", "summary": "1808\ub144\uc758 \ud3ed\ub825\uacfc \uace0\uc57c\uc758 \uad6c\ub3c4\uc5d0\uc11c \ub204\uad6c\uc758 \uc5bc\uad74\uacfc \uc2dc\uac04\uc774 \uae30\uc5b5\ub418\ub294\uc9c0 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/goya-third-may-lantern-and-facing-men/index.html", "image": "../media/goya-third-may-lantern-and-facing-men.jpg", "alt": "\uace0\uc57c\uc758 1808\ub144 5\uc6d4 3\uc77c \uc18d \ub4f1\ubd88\uacfc \ud314\uc744 \ubc8c\ub9b0 \ub0a8\uc790, \ucd1d\uc744 \uaca8\ub204\ub294 \uad70\uc778\ub4e4\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc5ed\uc0ac \ud751\ubc31 \ub3c4\ud310", "text": "\uace0\uc57c\uc758 1808\ub144 5\uc6d4 3\uc77c \u2014 \ubd88\ube5b\uc740 \ub204\uad6c\uc758 \uc5bc\uad74\uc744 \ube44\ucd94\ub294\uac00 \uad70\uc778\uc758 \ub4f1\uacfc \ud76c\uc0dd\uc790\uc758 \uc5bc\uad74, \ub4f1\ubd88\uacfc \ubc18\ubcf5\ub418\ub294 \ud3ed\ub825\uc758 \uc2dc\uac04 1808\ub144\uc758 \ud3ed\ub825\uacfc \uace0\uc57c\uc758 \uad6c\ub3c4\uc5d0\uc11c \ub204\uad6c\uc758 \uc5bc\uad74\uacfc \uc2dc\uac04\uc774 \uae30\uc5b5\ub418\ub294\uc9c0 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \uc5b4\ub450\uc6b4 \ubc24, \ubc1d\uc740 \uc637\uc758 \ub0a8\uc790\uac00 \ub450 \ud314\uc744 \ubc8c\ub9ac\uace0 \ubb34\uc7a5\ud55c \uad70\uc778\ub4e4 \uc55e\uc5d0 \uc11c \uc788\ub2e4. \uace0\uc57c\uc758 \u300c1808\ub144 5\uc6d4 3\uc77c\u300d\uc740 \uc804\uc7c1\uc744 \uc2b9\ub9ac\ud55c \uc7a5\uad70\uc758 \ubaa8\uc2b5\uc73c\ub85c \ubcf4\uc5ec \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \uc8fd\uc74c\uc744 \uc55e\ub454 \uc0ac\ub78c\uacfc \ucd1d\uc744 \uaca8\ub204\ub294 \uc9d1\ub2e8\uc774 \ub9c8\uc8fc\ud55c\ub2e4. \uadf8\ub9bc\uc758 \ube5b\uacfc \uc5bc\uad74, \ud654\uba74\uc5d0 \ub0a8\uc740 \uc2dc\uac04\uc744 \ub530\ub77c\uac00 \ubcf4\uc790. 1808\ub144 \ud504\ub791\uc2a4\uc758 \uc2a4\ud398\uc778 \uce68\uc785\uacfc \ub9c8\ub4dc\ub9ac\ub4dc\uc758 \uc800\ud56d\uc740 \ud3ed\ub825\uc801\uc778 \uc9c4\uc555\uc73c\ub85c \uc774\uc5b4\uc84c\ub2e4. \uadf8\ub9bc\uc740 \uadf8 \uc0ac\uac74\uc744 \ub2e4\ub8e8\uba70, \uc81c\uc791\uc740 1814\ub144\uc73c\ub85c \uc54c\ub824\uc838 \uc788\ub2e4. \uc0ac\uac74\uc774 \ubc8c\uc5b4\uc9c4 \ub0a0\uacfc \ud654\uac00\uac00 \ud654\uba74\uc73c\ub85c \uc815\ub9ac\ud55c \ub54c\ub97c \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ub208\uc55e\uc758 \uc7a5\uba74\uc740 \ud604\uc7a5\uc5d0\uc11c \uc989\uc2dc \ucc0d\uc740 \uae30\ub85d \uc0ac\uc9c4\uc774 \uc544\ub2c8\ub2e4. \uace0\uc57c\uac00 \uc0ac\uac74\uc744 \uc5b4\ub5bb\uac8c \ubcf4\uc558\ub294\uc9c0\ub97c \ubaa8\ub450 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uc5b4\ub5a4 \uc7a5\uba74\uc744 \uace8\ub77c \uad00\uac1d \uc55e\uc5d0 \ub193\uc558\ub294\uc9c0\ub2e4. \uc655\uacfc \uad70\ub300\uc758 \uc601\uad11\ubcf4\ub2e4 \ubb34\ubc29\ube44\ud55c \uc0ac\ub78c\ub4e4\uc774 \uacaa\ub294 \uc8fd\uc74c\uc774 \uc55e\uc5d0 \ub098\uc628\ub2e4. \uc5ed\uc0ac\ud654\uac00 \ubb34\uc5c7\uc744 \uae30\uc5b5\ud558\uac8c \ud560 \uac83\uc778\uc9c0\uc5d0 \uad00\ud55c \uc120\ud0dd\uc774\ub2e4. \uc624\ub978\ucabd \uad70\uc778\ub4e4\uc740 \ubab8\uc744 \uae30\uc6b8\uc5ec \ucd1d\uc744 \uaca8\ub208\ub2e4. \ube44\uc2b7\ud55c \uc790\uc138\uac00 \ubc18\ubcf5\ub418\uace0 \uad00\uac1d\uc5d0\uac8c \uc5bc\uad74\uc744 \uac70\uc758 \ubcf4\uc5ec \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \ubc18\ub300\ud3b8 \uc0ac\ub78c\ub4e4\uc740 \uac01\uae30 \ub2e4\ub978 \ubab8\uc9d3\uacfc \ud45c\uc815\uc744 \uac16\ub294\ub2e4. \ub450 \uc9d1\ub2e8\uc740 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uadf8\ub824\uc838 \uc788\uc9c0 \uc54a\ub2e4. \uc774 \ucc28\uc774\ub294 \ud3ed\ub825\uc758 \ube44\ub300\uce6d\uc744 \ub9cc\ub4e0\ub2e4. \ud55c\ucabd\uc740 \ud589\ub3d9\ud558\ub294 \ud558\ub098\uc758 \uc7a5\uce58\ucc98\ub7fc \ubcf4\uc774\uace0 \ub2e4\ub978 \ucabd\uc740 \uace0\ud1b5\uc744 \uacaa\ub294 \uc5ec\ub7ec \uc0ac\ub78c\uc73c\ub85c \ubcf4\uc778\ub2e4. \uac1c\uc778\uc758 \uc774\ub984\uc744 \ubaa8\ub974\ub354\ub77c\ub3c4 \ub450\ub824\uc6c0\uacfc \uc808\ub9dd\uc758 \ucc28\uc774\ub97c \uc54c\uc544\ubcfc \uc218 \uc788\ub2e4. \uadf8\ub9bc\uc740 \uc22b\uc790\ub85c \ubb36\uc77c \uc218 \uc788\ub294 \ud76c\uc0dd\uc790\ub97c \uc11c\ub85c \ub2e4\ub978 \uc5bc\uad74\ub85c \ub418\ub3cc\ub9b0\ub2e4. \ub4f1\ubd88\uc740 \uad70\uc778\uacfc \ud76c\uc0dd\uc790 \uc0ac\uc774\uc758 \ub0ae\uc740 \uacf3\uc5d0 \ub193\uc5ec \uc788\ub2e4. \uadf8 \ube5b\uc740 \ubc1d\uc740 \uc637\uc758 \uc778\ubb3c\uacfc \uc55e\ucabd \uc0ac\ub78c\ub4e4\uc744 \uac15\ud558\uac8c \ub4dc\ub7ec\ub0b8\ub2e4. \ube5b\uc774 \uc788\ub2e4\uace0 \uc548\uc804\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c \uc798 \ubcf4\uc778\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc624\ud788\ub824 \ud53c\ud560 \uc218 \uc5c6\ub294 \uc0c1\ud669\uc744 \ub354 \ub69c\ub837\ud558\uac8c \ub9cc\ub4e0\ub2e4. \uc5b4\ub460 \uc18d\uc5d0\uc11c \uc77c\ubd80\ub9cc \uc120\uba85\ud574\uc9c0\uba74 \uad00\uac1d\uc758 \uc2dc\uc120\ub3c4 \uc815\ud574\uc9c4\ub2e4. \uba40\ub9ac \uc788\ub294 \ub3c4\uc2dc\ubcf4\ub2e4 \uc55e\uc758 \ubab8\uacfc \uc190\uc744 \uba3c\uc800 \ubcf4\uac8c \ub41c\ub2e4. \ub4f1\ubd88\uc740 \uc7a5\uba74 \uc548\uc758 \ubb3c\uac74\uc774\uba74\uc11c \uadf8\ub9bc\uc744 \uc77d\ub294 \uc21c\uc11c\ub97c \ub9cc\ub4dc\ub294 \uc7a5\uce58\ub2e4. \ube5b\uc744 \uc544\ub984\ub2e4\uc6c0\uc774\ub098 \ud76c\ub9dd\uacfc \uc790\ub3d9\uc73c\ub85c \uc5f0\uacb0\ud560 \uc218 \uc5c6\ub294 \uc774\uc720\ub2e4. \uc911\uc559\uc758 \ub0a8\uc790\ub294 \ub450 \ud314\uc744 \ubc8c\ub9ac\uace0 \uc788\ub2e4. \uc774 \uc790\uc138\ub294 \uc885\uad50\ud654\uc758 \uace0\ud1b5\uc774\ub098 \ud76c\uc0dd\uc744 \uc5f0\uc0c1\uc2dc\ud0a4\uae30\ub3c4 \ud558\uc9c0\ub9cc, \uadf8\ub97c \ud55c \uac00\uc9c0 \uc0c1\uc9d5\uc73c\ub85c\ub9cc \ubc14\uafc0 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8\ub294 \ub3d9\uc2dc\uc5d0 \ubc14\ub85c \ub2e4\uc74c \uc21c\uac04\uc744 \ub9de\uc544\uc57c \ud560 \uad6c\uccb4\uc801\uc778 \uc0ac\ub78c\uc774\ub2e4. \ubb34\uae30\ub97c \ub4e0 \uc601\uc6c5\ucc98\ub7fc \uc2f8\uc6b0\ub294 \ubaa8\uc2b5\uc774 \uc544\ub2c8\ub77c \ub4dc\ub7ec\ub09c \ubab8\uc73c\ub85c \uc11c \uc788\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uac15\ud55c \uac10\uc815\uc740 \uc2b9\ub9ac\uc758 \ud589\ub3d9\uc5d0\uc11c\ub9cc \ub098\uc624\uc9c0 \uc54a\ub294\ub2e4. \uc800\ud56d\ud560 \uc218 \uc5c6\ub294 \uc0c1\ud0dc\ub97c \uad00\uac1d\uc774 \ubc14\ub77c\ubcf4\uac8c \ud558\ub294 \uad6c\uc131\uc5d0\uc11c\ub3c4 \ub098\uc628\ub2e4. \uace0\uc57c\ub294 \uc5ed\uc0ac\ud654\uc758 \uc911\uc2ec\uc5d0 \ucde8\uc57d\ud55c \ubab8\uc744 \ub193\uc558\ub2e4. \ud654\uba74 \uc55e\uc5d0\ub294 \uc4f0\ub7ec\uc9c4 \uc0ac\ub78c\ub4e4\uc774 \uc788\uace0, \ub4a4\uc5d0\ub294 \ucc28\ub840\ub97c \uae30\ub2e4\ub9ac\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc788\ub2e4. \ud604\uc7ac\uc758 \ud55c \uc21c\uac04 \uc548\uc5d0 \uc870\uae08 \uc804\uacfc \uace7 \ub2e4\uac00\uc62c \ubbf8\ub798\uac00 \uacb9\uce5c\ub2e4. \uc8fd\uc74c\uc744 \uc55e\ub454 \uc778\ubb3c\uc740 \uc55e\uc5d0 \ub193\uc778 \ubab8\uc744 \ud1b5\ud574 \uc790\uae30\uc5d0\uac8c \uc77c\uc5b4\ub0a0 \uc77c\uc744 \ubcf4\uac8c \ub41c\ub2e4. \uadf8\ub798\uc11c \uc774 \uadf8\ub9bc\uc758 \uc2dc\uac04\uc740 \ud55c \ubc88\uc758 \ucd1d\uc131\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \ubc18\ubcf5\ub420 \ud3ed\ub825\uc758 \uad6c\uc870\ub97c \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uad00\uac1d\uc758 \ub208\uc740 \uc774\ubbf8 \ub05d\ub09c \uc77c\uacfc \uc544\uc9c1 \ub05d\ub098\uc9c0 \uc54a\uc740 \uc77c \uc0ac\uc774\ub97c \uc6c0\uc9c1\uc778\ub2e4. \uc804\ud22c\uc758 \ube60\ub978 \uc6c0\uc9c1\uc784 \ub300\uc2e0 \uae30\ub2e4\ub9bc\uc774 \ub354 \ud070 \uacf5\ud3ec\ub97c \ub9cc\ub4dc\ub294 \uc7a5\uba74\uc774\ub2e4. \ud76c\uc0dd\uc790\ub4e4\uc774 \ubaa8\ub450 \uac19\uc740 \ud45c\uc815\uacfc \uc790\uc138\ub85c \uc11c \uc788\uc9c0 \uc54a\ub2e4\ub294 \uc810\ub3c4 \ub2e4\uc2dc \uc0b4\ud3b4\ubcfc \ub9cc\ud558\ub2e4. \uc190\uc744 \ubaa8\uc73c\uac70\ub098 \uc5bc\uad74\uc744 \uac00\ub9ac\uace0 \uc2dc\uc120\uc744 \ud53c\ud558\ub294 \ubab8\uc774 \uc11e\uc778\ub2e4. \ud55c \uc0ac\uac74\uc5d0 \ud568\uaed8 \ub193\uc600\ub2e4\uace0 \uadf8 \uc0ac\uac74\uc744 \uacaa\ub294 \ubc29\uc2dd\uae4c\uc9c0 \uac19\uc544\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc791\uc740 \ucc28\uc774\uac00 \uc9d1\ub2e8 \uc548\uc758 \uac1c\uc778\uc744 \ub0a8\uae34\ub2e4. \ubc18\ub300\ub85c \uad70\uc778\ub4e4\uc758 \ubc18\ubcf5\ub418\ub294 \ub3d9\uc791\uc740 \uac1c\ubcc4 \uc5bc\uad74\ubcf4\ub2e4 \uba85\ub839\uc5d0 \ub9de\ucd94\uc5b4\uc9c4 \uc6c0\uc9c1\uc784\uc744 \uc55e\uc138\uc6b4\ub2e4. \uadf8\ub9bc\uc774 \uc591\ucabd\uc744 \uac19\uc740 \uc815\ub3c4\ub85c \uc790\uc138\ud788 \uc124\uba85\ud558\uc9c0 \uc54a\ub294 \uac83\uc740 \uad00\uac1d\uc758 \uac10\uc815\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc900\ub2e4. \uc774 \uad6c\uc131\uc744 \ubcf4\uace0\ub3c4 \ud3ed\ub825\uc758 \uc8fc\uccb4\uc640 \ub300\uc0c1\uc744 \uad6c\ubcc4\ud558\uc9c0 \uc54a\ub294 \ucd94\uc0c1\uc801\uc778 \uc804\uc7c1\ub9cc \ub5a0\uc62c\ub9b0\ub2e4\uba74 \ud654\uba74\uc758 \ucc28\uc774\ub97c \ub193\uce58\uac8c \ub41c\ub2e4. \ube5b\uacfc \ubc30\uce58\ub294 \ub204\uad6c\uc758 \uacbd\ud5d8\uc5d0 \ub354 \uac00\uae4c\uc774 \uc11c\ub3c4\ub85d \ud560 \uac83\uc778\uc9c0 \uc815\ud55c\ub2e4. \uad6c\uccb4\uc801\uc778 \uad6c\ub3c4\uac00 \uc724\ub9ac\uc801\uc778 \uc9c8\ubb38\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uc9c0\uc810\uc774\ub2e4. \ubc30\uacbd\uc5d0\ub294 \uac74\ubb3c\uacfc \uc5b8\ub355\uc774 \uc788\uc9c0\ub9cc \uc55e\uc758 \ube44\uadf9\uc744 \ub9c9\uc544 \uc8fc\ub294 \ud53c\ub09c\ucc98\ub85c \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ub3c4\uc2dc\uc758 \ud615\ud0dc\uac00 \ub0a8\uc544 \uc788\ub2e4\uace0 \uadf8 \uc548\uc758 \uc9c8\uc11c\uac00 \uc0ac\ub78c\uc744 \ubcf4\ud638\ud55c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uac00\uae4c\uc6b4 \ubab8\uacfc \uba40\ub9ac \uc788\ub294 \uac74\ucd95\uc758 \uac70\ub9ac\uac00 \ud654\uba74\uc5d0\uc11c \ud06c\uac8c \ub290\uaef4\uc9c4\ub2e4. \uc0ac\uc6a9\ud55c \uc5ed\uc0ac \ub3c4\ud310\uc740 \ud751\ubc31\uc774\ub2e4. \uc6d0\uc791\uc758 \uc0c9\ucc44\ub97c \uc628\uc804\ud788 \ub300\uc2e0\ud558\uc9c0\ub294 \ubabb\ud558\uc9c0\ub9cc \ubc1d\uae30\uc640 \uc9d1\ub2e8\uc758 \ubc30\uc5f4\uc740 \uc0b4\ud544 \uc218 \uc788\ub2e4. \ub3c4\ud310\uc758 \uc61b \ucea1\uc158\uc774 \uc0ac\uac74\uc744 \ub113\uac8c 5\uc6d4 2\uc77c\uacfc \uc5f0\uacb0\ud55c \uac83\uacfc \uc624\ub298\uc758 \uc791\ud488 \uc81c\ubaa9\uc744 \uad6c\ubd84\ud558\uba74 \uc774\ubbf8\uc9c0\uc640 \uc124\uba85\uc758 \uc5ed\uc0ac\ub97c \ud63c\ub3d9\ud558\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uc774 \uadf8\ub9bc\uc5d0\uc11c \ub204\uad6c\uc758 \ud3b8\uc778\uc9c0 \ubb3b\ub294 \uc77c\ub9cc\ud07c \ub204\uad6c\uc758 \uc5bc\uad74\uc744 \ubcf4\uac8c \ud558\ub294\uc9c0 \ubb3b\ub294 \uc77c\uc774 \uc911\uc694\ud558\ub2e4. \uad70\uc778\uc758 \ub4f1 \ub4a4\uc5d0\uc11c \uc7a5\uba74\uc744 \ubc14\ub77c\ubcf4\ub294 \uad00\uac1d\uc740 \ud3ed\ub825\uc758 \uac70\ub9ac\uc5d0\uc11c \uc790\uc720\ub86d\uc9c0 \uc54a\ub2e4. \uc548\uc804\ud55c \uacf3\uc5d0\uc11c \ub05d\ub09c \uc0ac\uac74\uc744 \uad6c\uacbd\ud558\ub294 \ub290\ub08c\uc774 \uc27d\uac8c \uc0dd\uae30\uc9c0 \uc54a\ub294\ub2e4. \u300c1808\ub144 5\uc6d4 3\uc77c\u300d\uc740 \ud2b9\uc815 \uc0ac\uac74\uc758 \uae30\uc5b5\uc774\uba74\uc11c \uc804\uc7c1\uc744 \uadf8\ub9ac\ub294 \ubc29\uc2dd\uc5d0 \ub300\ud55c \uc9c8\ubb38\uc774\ub2e4. \ud654\ub824\ud55c \uc9c0\ud718\uad00 \uc5c6\uc774\ub3c4 \uc5ed\uc0ac\ub97c \ub9d0\ud560 \uc218 \uc788\uace0, \uac15\ud55c \uc0ac\ub78c\ubcf4\ub2e4 \ucde8\uc57d\ud55c \uc0ac\ub78c\uc744 \uc911\uc2ec\uc5d0 \ub193\uc744 \uc218 \uc788\ub2e4. \ub204\uad6c\uc758 \uc5bc\uad74\uc774 \ub0a8\ub294\uc9c0\ub3c4 \uc5ed\uc0ac\ub97c \ud45c\ud604\ud558\ub294 \uc120\ud0dd\uc774\uc5c8\ub2e4. \ubd88\ube5b\uc774 \ud5a5\ud55c \uc790\ub9ac\ub97c \ub530\ub77c\uac00\uba74 \uadf8\ub9bc\uc774 \ub0a8\uae30\ub824 \ud55c \uace0\ud1b5\uc758 \ubb34\uac8c\uac00 \ubcf4\uc778\ub2e4."}, {"id": "great-gatsby-green-light-and-past", "title": "\uc704\ub300\ud55c \uac1c\uce20\ube44 \u2014 \ucd08\ub85d \ubd88\ube5b \ub108\uba38\uc5d0\ub294 \ubb34\uc5c7\uc774 \uc788\uc5c8\uc744\uae4c", "summary": "\uac1c\uce20\ube44\uc640 \ub370\uc774\uc9c0, \uc0ac\uace0\uc640 \uc7a5\ub840\ub97c \ub530\ub77c \ucd08\ub85d \ubd88\ube5b\uc5d0 \ub2f4\uae34 \uc695\ub9dd\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/great-gatsby-green-light-and-past/index.html", "image": "../media/great-gatsby-green-light-and-past.png", "alt": "\ubc24\uc758 \ubd80\ub450\uc5d0\uc11c \uba3c \ucd08\ub85d \ubd88\ube5b\uc744 \ubc14\ub77c\ubcf4\ub294 \ub0a8\uc790\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uc704\ub300\ud55c \uac1c\uce20\ube44 \u2014 \ucd08\ub85d \ubd88\ube5b \ub108\uba38\uc5d0\ub294 \ubb34\uc5c7\uc774 \uc788\uc5c8\uc744\uae4c \ub2c9\uc774 \ub9cc\ub09c \uc0ac\ub78c\ub4e4\uc758 \uc138\uacc4\uc5d0\uc11c \uc2dc\uc791\ud558\ub294 \uc5ed\uc0ac\uc640 \uc791\ud488 \uc77d\uae30 \uac1c\uce20\ube44\uc640 \ub370\uc774\uc9c0, \uc0ac\uace0\uc640 \uc7a5\ub840\ub97c \ub530\ub77c \ucd08\ub85d \ubd88\ube5b\uc5d0 \ub2f4\uae34 \uc695\ub9dd\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \ubc24\uc758 \ub9cc \uac74\ub108\uc5d0 \uc791\uc740 \ucd08\ub85d \ubd88\ube5b\uc774 \uc788\ub2e4. \uc81c\uc774 \uac1c\uce20\ube44\ub294 \uadf8\ucabd\uc744 \ubc14\ub77c\ubcf4\uba70 \uc624\ub798\uc804\uc758 \uc0ac\ub791\uacfc \uc55e\uc73c\ub85c \uc5bb\uace0 \uc2f6\uc740 \uc0b6\uc744 \ud568\uaed8 \uafc8\uafbc\ub2e4. F. \uc2a4\ucf67 \ud53c\uce20\uc81c\ub7f4\ub4dc\uc758 \u300e\uc704\ub300\ud55c \uac1c\uce20\ube44\u300f\ub294 \ud654\ub824\ud55c \uc800\ud0dd\uacfc \ud30c\ud2f0\uc758 \uc774\uc57c\uae30\uc774\uc9c0\ub9cc, \uadf8 \ube5b \uc544\ub798\uc5d0\uc11c\ub294 \uacc4\uae09\uacfc \uae30\uc5b5, \ucc45\uc784\uc744 \ud53c\ud558\ub294 \uc0ac\ub78c\ub4e4\uc758 \ubb38\uc81c\uac00 \uc6c0\uc9c1\uc778\ub2e4. \uc791\ud488\uc758 \uc8fc\uc694 \uc0ac\uac74\uacfc \uacb0\ub9d0\uc744 \ub530\ub77c\uac00 \ubcf4\uc790. \uac1c\uce20\ube44\ub97c \uc21c\uc218\ud55c \uc0ac\ub791\uc758 \uc8fc\uc778\uacf5\uc73c\ub85c\ub9cc \ubcf4\uac70\ub098 \ub3c8 \ub9ce\uc740 \ud5c8\ud48d\uc7c1\uc774\ub85c\ub9cc \uc904\uc774\uba74 \uc18c\uc124\uc758 \uc591\uba74\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \uadf8\uac00 \uc2e4\uc81c\ub85c \ub204\uad6c\uc778\uc9c0\uc640 \uc0ac\ub78c\ub4e4\uc774 \uadf8\ub97c \uc5b4\ub5bb\uac8c \uc774\uc57c\uae30\ud558\ub294\uc9c0\uac00 \uacc4\uc18d \uc5b4\uae0b\ub09c\ub2e4. \uc774\uc57c\uae30\ub97c \uc804\ud558\ub294 \ub2c9 \uce90\ub7ec\uc6e8\uc774\ub294 \ub274\uc695 \uadfc\ucc98\uc5d0\uc11c \uac1c\uce20\ube44\uc758 \uc774\uc6c3\uc774 \ub41c\ub2e4. \uc0ac\ucd0c \ub370\uc774\uc9c0\uc640 \uadf8\ub140\uc758 \ub0a8\ud3b8 \ud1b0 \ubdf0\uce90\ub10c\ub3c4 \uadf8\uc758 \uad00\uacc4\ub9dd\uc5d0 \uc788\ub2e4. \ub2c9\uc740 \uc0ac\ub78c\ub4e4\uc744 \uad00\ucc30\ud558\uace0 \ud3c9\uac00\ud558\uc9c0\ub9cc \uc644\uc804\ud788 \ud22c\uba85\ud55c \ucc3d\uc740 \uc544\ub2c8\ub2e4. \ub3c5\uc790\ub294 \uc0ac\uac74\uacfc \ud568\uaed8 \uadf8\uac83\uc744 \ub3cc\uc544\ubcf4\uba70 \ub9d0\ud558\ub294 \uadf8\uc758 \uc2dc\uc120\ub3c4 \uc77d\uc5b4\uc57c \ud55c\ub2e4. \ubc30\uacbd\uc758 \uc11c\ub85c \ub2e4\ub978 \uc8fc\uac70\uc9c0\ub294 \ubd80\uc790\ub77c\ub294 \ud55c \ub2e8\uc5b4 \uc548\uc758 \ucc28\uc774\ub97c \ub4dc\ub7ec\ub0b8\ub2e4. \uc624\ub798\ub41c \ubd80\uc640 \uc0c8\ub85c \uc5bb\uc740 \ubd80\uac00 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc778\uc815\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc9d1\uc758 \ud06c\uae30\ub9cc\uc73c\ub85c \ub118\uc5b4\uac08 \uc218 \uc5c6\ub294 \uacbd\uacc4\uac00 \uc788\ub2e4. \ud654\ub824\ud55c \uc0dd\ud65c\uc758 \uc774\uba74\uc5d0 \ub204\uac00 \uc774\ubbf8 \uc548\ucabd\uc5d0 \uc18d\ud558\uace0 \ub204\uac00 \ub4e4\uc5b4\uac00\ub824 \ud558\ub294\uc9c0\uac00 \ub193\uc778\ub2e4. \uac1c\uce20\ube44\uc758 \uc9d1\uc5d0\ub294 \ub9ce\uc740 \uc0ac\ub78c\uc774 \ubaa8\uc778\ub2e4. \uadf8\ub7ec\ub098 \uadf8\uac00 \ub204\uad6c\uc778\uc9c0\uc5d0 \ub300\ud574\uc11c\ub294 \uc18c\ubb38\uc774 \ub354 \ud48d\ubd80\ud558\ub2e4. \uc9c1\uc811 \ud568\uaed8 \uc788\ub2e4\uace0 \uadf8 \uc0ac\ub78c\uc758 \uc0b6\uc744 \uc548\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ucd95\uc81c\uc758 \uaddc\ubaa8\uc640 \uad00\uacc4\uc758 \uae4a\uc774\uac00 \uc11c\ub85c \ub2e4\ub974\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub098\uc911\uc758 \uacb0\ub9d0\uc744 \uc900\ube44\ud55c\ub2e4. \uac1c\uce20\ube44\ub294 \uc790\uae30 \uacfc\uac70\ub97c \ub2e4\uc2dc \ub9cc\ub4e4\uace0 \uc0c8\ub85c\uc6b4 \ubaa8\uc2b5\uc73c\ub85c \uc0b4\uc544\uc628 \uc0ac\ub78c\uc774\ub2e4. \uadf8 \uc7ac\uc0b0\uacfc \uacbd\ub825\uc5d0\ub294 \ubd88\ubd84\uba85\ud55c \ubd80\ubd84\ub3c4 \uc788\ub2e4. \ub3c5\uc790\ub294 \ub9e4\ud639\uc744 \ub290\ub07c\uba74\uc11c \uc758\uc2ec\ud55c\ub2e4. \uc18c\uc124\uc740 \uc131\uacf5\ud55c \uc0ac\ub78c\uc758 \uc678\uc591\uc774 \uc5b4\ub5bb\uac8c \ub9cc\ub4e4\uc5b4\uc9c0\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uae30\ub300\uc640 \uc18c\ubb38 \uc18d\uc5d0\uc11c \uc720\uc9c0\ub418\ub294\uc9c0 \ubcf4\uc5ec \uc900\ub2e4. \uac1c\uce20\ube44\uc5d0\uac8c \ub370\uc774\uc9c0\ub294 \ud604\uc7ac\uc758 \ud55c \uc0ac\ub78c\ub9cc\uc774 \uc544\ub2c8\ub2e4. \ud5e4\uc5b4\uc84c\ub358 \uc2dc\uc808\uacfc \ub418\ucc3e\uace0 \uc2f6\uc740 \uac00\ub2a5\uc131\uc774 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4. \uadf8\ub294 \ub2c9\uc758 \ub3c4\uc6c0\uc73c\ub85c \ub370\uc774\uc9c0\uc640 \ub2e4\uc2dc \ub9cc\ub098\uc9c0\ub9cc, \ub9cc\ub0a8\uc774 \uc774\ub8e8\uc5b4\uc84c\ub2e4\uace0 \uc774\uc804\uc758 \uc2dc\uac04\uc774 \uadf8\ub300\ub85c \ub3cc\uc544\uc624\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub7fc\uc5d0\ub3c4 \uac1c\uce20\ube44\ub294 \uacfc\uac70\ub97c \ub2e4\uc2dc \ub9cc\ub4e4 \uc218 \uc788\ub2e4\uace0 \ubbff\uc73c\ub824 \ud55c\ub2e4. \ub370\uc774\uc9c0\uac00 \uc9c0\uae08\uae4c\uc9c0 \uc0b4\uc544\uc628 \uc2dc\uac04\uacfc \uad00\uacc4\ub294 \uadf8\uc758 \uafc8\uc5d0 \ub9de\ucdb0 \uc9c0\uc6cc\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uc0ac\ub791\ud558\ub294 \uc0ac\ub78c\uc744 \ucda9\ubd84\ud788 \ubcf8\ub2e4\ub294 \uac83\uacfc \uadf8 \uc0ac\ub78c\uc5d0\uac8c \uc783\uc5b4\ubc84\ub9b0 \ubbf8\ub798\ub97c \ubaa8\ub450 \ub9e1\uae34\ub2e4\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uadf8\uc758 \uc5f4\uc815\uc5d0\ub294 \uc774 \ub450 \ud0dc\ub3c4\uac00 \uc11e\uc5ec \uc788\ub2e4. \uac1c\uce20\ube44\uc640 \ud1b0\uc758 \uac08\ub4f1\uc740 \ub370\uc774\uc9c0\ub97c \ub458\ub7ec\uc2fc \uc120\ud0dd\uc73c\ub85c \ub4dc\ub7ec\ub098\uc9c0\ub9cc \ubd80\uc640 \uc9c0\uc704\uc758 \ud798\ub3c4 \ud568\uaed8 \uc791\ub3d9\ud55c\ub2e4. \ud1b0\uc740 \uc790\uc2e0\uc774 \uc18d\ud55c \uc138\uacc4\uc758 \uc548\uc815\uac10\uc744 \uc774\uc6a9\ud55c\ub2e4. \uac1c\uce20\ube44\uac00 \ub9c8\ub828\ud55c \ub3c8\uacfc \ud654\ub824\ud568\uc774 \uadf8 \uc138\uacc4\uc758 \ubaa8\ub4e0 \uad8c\ub9ac\ub97c \uac00\uc838\ub2e4\uc8fc\uc9c0\ub294 \ubabb\ud55c\ub2e4. \uacbd\uc7c1\uc740 \uac19\uc740 \ucd9c\ubc1c\uc120\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \ub370\uc774\uc9c0 \uc5ed\uc2dc \ub450 \ub0a8\uc790\uac00 \uc8fc\uc7a5\ud558\ub294 \uc774\uc57c\uae30 \ubc16\uc758 \uc2dc\uac04\uacfc \uc695\ub9dd\uc744 \uac00\uc9c4 \uc778\ubb3c\uc774\ub2e4. \uadf8\ub7ec\ub098 \uc704\uae30 \uc55e\uc5d0\uc11c \uc5b4\ub5a4 \uc120\ud0dd\uc744 \ud558\ub294\uc9c0\uc758 \ucc45\uc784\uc740 \ub0a8\ub294\ub2e4. \uc18c\uc124\uc740 \uc0ac\ub791\uc774 \uc9c4\uc2e4\ud55c\uc9c0\ub9cc \ubb3b\uc9c0 \uc54a\uace0 \uadf8 \uac10\uc815\uc744 \uc704\ud574 \ub204\uac00 \ubb34\uc5c7\uc744 \uac10\ub2f9\ud558\ub294\uc9c0 \uc0b4\ud540\ub2e4. \uc9c0\uc704\ub294 \uc798\ubabb\uc758 \uacb0\uacfc\uc5d0\uc11c \ube60\uc838\ub098\uc624\ub294 \ub2a5\ub825\uacfc\ub3c4 \uc5f0\uacb0\ub41c\ub2e4. \ub2c9\uc774 \ubaa8\ub450\uc758 \ub9c8\uc74c\uc744 \uc9c1\uc811 \uc54c \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\uac00 \ub4e4\uc740 \ub9d0\uacfc \ub098\uc911\uc5d0 \uc7ac\uad6c\uc131\ud55c \uc7a5\uba74\uc774 \uc11e\uc5ec \uc788\uc73c\ubbc0\ub85c, \uc11c\uc220\uc744 \uc77d\uc744 \ub54c\uc5d0\ub294 \ub204\uac00 \ubcf4\uace0 \ub204\uac00 \uc124\uba85\ud558\ub294\uc9c0\ub3c4 \uc0b4\ud544 \ud544\uc694\uac00 \uc788\ub2e4. \uac1c\uce20\ube44\uc758 \uc2e0\ube44\ub85c\uc6b4 \uc774\ubbf8\uc9c0\ub294 \uc778\ubb3c\uc758 \ud589\ub3d9\uacfc \uadf8\ub97c \ubc14\ub77c\ubcf4\ub294 \uc2dc\uc120\uc774 \ud568\uaed8 \ub9cc\ub4e0\ub2e4. \ub370\uc774\uc9c0\uac00 \uc6b4\uc804\ud558\ub358 \ucc28\uc5d0 \uba38\ud2c0 \uc70c\uc2a8\uc774 \uce58\uc5ec \uc8fd\ub294\ub2e4. \uba38\ud2c0\uc740 \ud1b0\uacfc \uad00\uacc4\ub97c \ub9fa\uace0 \uc788\ub358 \uc0ac\ub78c\uc774\ub2e4. \uba40\ub9ac \ub5a8\uc5b4\uc838 \ubcf4\uc774\ub358 \uc778\ubb3c\ub4e4\uc758 \uc0b6\uc774 \ud55c \uc0ac\uac74\uc5d0\uc11c \uacb9\uce5c\ub2e4. \ucc28\uc758 \uc18c\uc720\uc790\uc640 \uc6b4\uc804\uc790\uac00 \ub2e4\ub974\ub2e4\ub294 \uc810, \uc0ac\ub78c\ub4e4\uc774 \ub204\uad6c\uc5d0\uac8c \uc5b4\ub5a4 \ub9d0\uc744 \uc804\ud558\ub294\uc9c0\uac00 \uacb0\uc815\uc801\uc774\ub2e4. \uac1c\uce20\ube44\ub294 \ub370\uc774\uc9c0\ub97c \uc9c0\ud0a4\ub824 \ud55c\ub2e4. \uba38\ud2c0\uc758 \ub0a8\ud3b8 \uc870\uc9c0 \uc70c\uc2a8\uc740 \uc798\ubabb\ub41c \ud310\ub2e8 \ub05d\uc5d0 \uac1c\uce20\ube44\ub97c \uc8fd\uc774\uace0 \uc790\uc2e0\ub3c4 \ubaa9\uc228\uc744 \uc783\ub294\ub2e4. \uc0ac\uac74\uc758 \ucc45\uc784\uc774 \uc2e4\uc81c \ud589\uc704\uc790\uc5d0\uac8c \ucc28\ubd84\ud788 \ub3cc\uc544\uac00\uc9c0 \uc54a\ub294\ub2e4. \ub3c8\uacfc \uc18c\ubb38, \uc624\ud574\uc640 \ud68c\ud53c\uac00 \uc11e\uc774\uba74\uc11c \uac00\uc7a5 \uac00\uae4c\uc6b4 \uc124\uba85\uc774 \uc9c4\uc2e4\uc744 \ub300\uc2e0\ud55c\ub2e4. \ub9ce\uc740 \uc0ac\ub78c\uc774 \ub4dc\ub098\ub4e4\ub358 \uc800\ud0dd\uacfc \ub2ec\ub9ac \uac1c\uce20\ube44\uc758 \uc8fd\uc74c \ub4a4\uc5d0\ub294 \ud568\uaed8 \ub0a8\ub294 \uc0ac\ub78c\uc774 \ub9ce\uc9c0 \uc54a\ub2e4. \ub2c9\uc740 \uadf8 \ube48\uc790\ub9ac\ub97c \ub9c8\uc8fc\ud55c\ub2e4. \uc794\uce58\uc758 \uc190\ub2d8\uc73c\ub85c \ucc38\uc5ec\ud558\ub294 \uc77c\uacfc \ud55c \uc0ac\ub78c\uc758 \ub05d\uc744 \ucc45\uc784 \uc788\uac8c \ub300\ud558\ub294 \uc77c\uc740 \ub2e4\ub978 \uad00\uacc4\uc600\ub2e4. \uc55e\ubd80\ubd84\uc758 \ud654\ub824\ud568\uc774 \ub4a4\uc5d0\uc11c \ub2e4\ub978 \uc758\ubbf8\ub85c \ub3cc\uc544\uc628\ub2e4. \ud1b0\uacfc \ub370\uc774\uc9c0\ub294 \uc790\uc2e0\uc758 \uc548\uc804\ud55c \uc138\uacc4\ub85c \ubb3c\ub7ec\ub09c\ub2e4. \ub2c9\uc774 \ub290\ub07c\ub294 \ubd84\ub178\ub294 \uc774 \ubb34\ucc45\uc784\uacfc \uc5f0\uacb0\ub41c\ub2e4. \ub204\uad70\uac00\uac00 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc0b6\uc744 \ud754\ub4e4\uc5b4 \ub193\uace0\ub3c4 \uc790\uc2e0\uc744 \ubcf4\ud638\ud574 \uc8fc\ub294 \ubd80\uc640 \uc9c0\uc704\ub85c \ub3cc\uc544\uac08 \uc218 \uc788\ub2e4\ub294 \uac83. \uc18c\uc124\uc758 \uc0ac\ud68c\uc801 \ube44\ud310\uc740 \uc774 \ub3c4\ud53c\uc758 \uad6c\uc870\ub97c \ud5a5\ud55c\ub2e4. \ub9cc \uac74\ub108\uc758 \ubd88\ube5b\uc740 \uac00\uae4c\uc6cc \ubcf4\uc774\uba74\uc11c\ub3c4 \uc27d\uac8c \ub2ff\uc9c0 \uc54a\ub294 \ubbf8\ub798\ub97c \ub098\ud0c0\ub0b8\ub2e4. \uac1c\uce20\ube44\ub294 \uadf8\uac83\uc744 \ub370\uc774\uc9c0\uc640 \uc5f0\uacb0\ud588\uc9c0\ub9cc \ub3c5\uc790\ub294 \ub354 \ub113\uc740 \uc131\uacf5\uc758 \uafc8\uae4c\uc9c0 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uc6d0\ud558\ub294 \uacf3\uc5d0 \ub3c4\ucc29\ud558\uba74 \uc9c0\ub09c \uc2dc\uac04\ub3c4 \ud68c\ubcf5\ub420 \uac83\uc774\ub77c\ub294 \uae30\ub300\ub2e4. \uc18c\uc124\uc740 \uadf8 \uae30\ub300\uc758 \uc544\ub984\ub2e4\uc6c0\uacfc \uc704\ud5d8\uc744 \ud568\uaed8 \ub0a8\uae34\ub2e4. \u300e\uc704\ub300\ud55c \uac1c\uce20\ube44\u300f\uc758 \uc704\ub300\ud568\uc774\ub77c\ub294 \ub9d0\ub3c4 \ub2e8\uc21c\ud55c \uce6d\ucc2c\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uafc8\uc744 \ubbff\ub294 \ud798\uacfc \uadf8 \uafc8\uc774 \uc2e4\uc81c \uc0ac\ub78c\uc744 \uac00\ub9ac\ub294 \ubc29\uc2dd\uc774 \ud568\uaed8 \uc788\ub2e4. \ud30c\ud2f0\uac00 \ub05d\ub09c \ub4a4 \ub204\uac00 \ub0a8\uace0 \ub204\uac00 \uc0ac\ub77c\uc9c0\ub294\uc9c0\uae4c\uc9c0 \uc77d\uc744 \ub54c, \uba40\ub9ac \uc788\ub358 \ucd08\ub85d \ubd88\ube5b\uc740 \ud55c \uc2dc\ub300\uc758 \uc695\ub9dd\uc744 \ube44\ucd94\ub294 \uc774\ubbf8\uc9c0\uac00 \ub41c\ub2e4."}, {"id": "gulliver-travels-size-and-satire", "title": "\u300e\uac78\ub9ac\ubc84 \uc5ec\ud589\uae30\u300f \u2014 \uc18c\uc778\uad6d\ubcf4\ub2e4 \ub354 \uc774\uc0c1\ud55c \uac83\uc740 \ubb34\uc5c7\uc77c\uae4c", "summary": "\uc18c\uc778\uad6d\ubd80\ud130 \ub9d0\ub4e4\uc758 \ub098\ub77c\uae4c\uc9c0 \ub124 \uc5ec\ud589\uc758 \uc904\uac70\ub9ac\uc640 \ud48d\uc790\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/gulliver-travels-size-and-satire/index.html", "image": "../media/gulliver-travels-size-and-satire.png", "alt": "\uc791\uc740 \ub3c4\uc2dc\uc758 \uc0ac\ub78c\ub4e4\uacfc \uc0ac\ub2e4\ub9ac \uacc1\uc5d0 \uc549\uc740 \uac70\ub300\ud55c \uc5ec\ud589\uc790 \uac78\ub9ac\ubc84\ub97c \uadf8\ub9b0 \uc18c\uc124 \uc0bd\ud654", "text": "\u300e\uac78\ub9ac\ubc84 \uc5ec\ud589\uae30\u300f \u2014 \uc18c\uc778\uad6d\ubcf4\ub2e4 \ub354 \uc774\uc0c1\ud55c \uac83\uc740 \ubb34\uc5c7\uc77c\uae4c \ubab8\uc758 \ud06c\uae30\ub97c \ubc14\uafb8\uc5b4 \uc778\uac04 \uc0ac\ud68c\ub97c \ub2e4\uc2dc \ubcf4\uac8c \ud55c \uc5ec\ud589 \uc18c\uc778\uad6d\ubd80\ud130 \ub9d0\ub4e4\uc758 \ub098\ub77c\uae4c\uc9c0 \ub124 \uc5ec\ud589\uc758 \uc904\uac70\ub9ac\uc640 \ud48d\uc790\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \uc7a0\uc5d0\uc11c \uae68\uc5b4\ub0ac\ub354\ub2c8 \ubab8\uc774 \ub545\uc5d0 \ubb36\uc5ec \uc788\ub2e4. \uc791\uc740 \uc0ac\ub78c\ub4e4\uc774 \uac00\uc2b4 \uc704\ub97c \uac77\uace0 \uc5bc\uad74\uc744 \uc62c\ub824\ub2e4\ubcf8\ub2e4. \u300e\uac78\ub9ac\ubc84 \uc5ec\ud589\uae30\u300f\ub97c \ub5a0\uc62c\ub9ac\uba74 \uac00\uc7a5 \uba3c\uc800 \ub098\uc624\ub294 \uc7a5\uba74\uc774\ub2e4. \ud558\uc9c0\ub9cc \uc18c\uc778\uad6d\uc740 \ub124 \ubc88\uc758 \uc5ec\ud589 \uac00\uc6b4\ub370 \uccab \ubc88\uc9f8\uc77c \ubfd0\uc774\ub2e4. \uc870\ub108\uc120 \uc2a4\uc704\ud504\ud2b8\uc758 \uc18c\uc124\uc740 \uc791\uc740 \ub098\ub77c\ub97c \uad6c\uacbd\ud558\ub294 \uc990\uac70\uc6c0 \ub4a4\uc5d0 \uad8c\ub825\uacfc \uc790\uc874\uc2ec, \ud559\ubb38\uacfc \uc778\uac04 \ud610\uc624\uc5d0 \ub300\ud55c \uc9c8\ubb38\uc744 \uc228\uaca8 \ub193\uc558\ub2e4. \uc5ec\uae30\uc11c\ub294 \uac01 \uc5ec\ud589\uc758 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \ub05d\ubd80\ubd84\uc744 \ud568\uaed8 \uc18c\uac1c\ud55c\ub2e4. \uc5b4\ub9b0\uc774\uc6a9\uc73c\ub85c \uc904\uc778 \uc774\uc57c\uae30\uc5d0\uc11c \ubcf4\uc9c0 \ubabb\ud588\ub358 \ubd88\ud3b8\ud55c \uc7a5\uba74\ub3c4 \ub9cc\ub098\uac8c \ub41c\ub2e4. \ub9b4\ub9ac\ud38f\uc5d0\uc11c \uac78\ub9ac\ubc84\ub294 \uc555\ub3c4\uc801\uc73c\ub85c \ud070 \uc874\uc7ac\ub2e4. \uc8fc\ubbfc\ub4e4\uc5d0\uac8c\ub294 \uc704\ud5d8\ud55c \uc7ac\ub09c\uc77c \uc218\ub3c4, \uc4f8\ubaa8 \uc788\ub294 \uad70\uc0ac\ub825\uc77c \uc218\ub3c4 \uc788\ub2e4. \uba39\uc774\uace0 \uc774\ub3d9\uc2dc\ud0a4\uace0 \uacbd\uacc4\ud558\ub294 \ub370\uc5d0 \ub9ce\uc740 \uc0ac\ub78c\uacfc \ubb3c\uac74\uc774 \ud544\uc694\ud558\ub2e4. \uc2e0\uccb4\uc758 \ud06c\uae30\uac00 \ub2e4\ub974\uba74 \uc77c\uc0c1\uc801\uc778 \ud55c \ub07c\ub3c4 \uad6d\uac00\uc801\uc778 \uc900\ube44\uac00 \ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uac78\ub9ac\ubc84\uac00 \ub9c8\uc74c\ub300\ub85c \uc655\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b8\uc5b4\ub97c \uc775\ud788\uace0 \uc870\uac74\uc744 \ubc1b\uc544\ub4e4\uc774\uba70 \uad81\uc815\uc758 \ud310\ub2e8 \uc18d\uc5d0 \ub4e4\uc5b4\uac04\ub2e4. \ubab8\uc758 \ud798\uacfc \uc81c\ub3c4\uc758 \ud798\uc740 \uc11c\ub85c \ub2e4\ub974\ub2e4. \uac70\uc778\uc774 \ub41c \uc5ec\ud589\uc790\ub3c4 \ubc95\uacfc \uba85\ub839, \uc18c\ubb38\uacfc \ucc98\ubc8c \uc55e\uc5d0\uc11c\ub294 \ucde8\uc57d\ud560 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uccab \uc5ec\ud589\uc758 \uae34\uc7a5\uc744 \ub9cc\ub4e0\ub2e4. \uc774 \ub098\ub77c\uc5d0\ub294 \ub192\uc740 \uad7d\uacfc \ub0ae\uc740 \uad7d\uc744 \ub458\ub7ec\uc2fc \uc815\uce58\uc801 \uad6c\ubcc4\uc774 \uc788\uace0, \ub2ec\uac40\uc744 \uc5b4\ub290 \ub05d\uc5d0\uc11c \uae68\ub290\ub0d0\ub294 \ubb38\uc81c\ub294 \uc2ec\uac01\ud55c \ub2e4\ud23c\uc774 \ub41c\ub2e4. \uc0ac\uc18c\ud574 \ubcf4\uc774\ub294 \ucc28\uc774\uac00 \ucda9\uc131\uc758 \uc99d\uac70\uac00 \ub418\uace0, \uba85\ub839\uacfc \uc800\ud56d\uc744 \ub0b3\uc73c\uba70 \uc774\uc6c3 \ub098\ub77c\uc640\uc758 \uc801\ub300\uc5d0\ub3c4 \uc5f0\uacb0\ub41c\ub2e4. \ub2f9\uc0ac\uc790\ub4e4\uc5d0\uac8c\ub294 \ubaa9\uc228\uae4c\uc9c0 \uac78\ub9b0 \ubb38\uc81c\ub2e4. \ub3c5\uc790\ub294 \uadf8 \uc791\uc74c\uc744 \ubcf4\uace0 \uc6c3\uc9c0\ub9cc, \ud48d\uc790\ub294 \ub9b4\ub9ac\ud38f \uc0ac\ub78c\ub4e4\ub9cc \ud5a5\ud558\uc9c0 \uc54a\ub294\ub2e4. \uba40\ub9ac\uc11c \ubcf4\uba74 \ud558\ucc2e\uc740 \ucc28\uc774\ub97c \uc808\ub300\uc801\uc778 \uae30\uc900\uc73c\ub85c \uc0bc\uace0 \uc2f8\uc6b0\ub294 \uc77c\uc740 \uc778\uac04 \uc0ac\ud68c\uc5d0\ub3c4 \uc788\ub2e4. \uc791\uac00\ub294 \ub17c\uc7c1\uc758 \uc8fc\uc81c\ub9cc \uc791\uac8c \ub9cc\ub4e4\uc5b4 \uc775\uc219\ud55c \uc5f4\uc815\uc744 \ub0af\uc124\uac8c \ubcf4\uc774\uac8c \ud55c\ub2e4. \uc6b0\ub9ac\uac00 \uc5b8\uc81c\ub098 \ud569\ub9ac\uc801\uc778 \ud3b8\uc5d0 \uc788\ub2e4\ub294 \ud655\uc2e0\ub3c4 \uc870\uae08 \ubd88\ud3b8\ud574\uc9c4\ub2e4. \uac78\ub9ac\ubc84\ub294 \uc774\uc6c3 \ube14\ub808\ud478\uc2a4\ucfe0\uc758 \ud568\ub300\ub97c \ub04c\uc5b4\uc624\ub294 \ub180\ub77c\uc6b4 \uc77c\uc744 \ud574\ub0b8\ub2e4. \uadf8\ub7ec\ub098 \ud669\uc81c\uac00 \uc0c1\ub300 \ub098\ub77c\ub97c \uc644\uc804\ud788 \uad74\ubcf5\uc2dc\ud0a4\ub824 \ud560 \ub54c\uc5d0\ub294 \ub05d\uae4c\uc9c0 \ub73b\uc744 \ub9de\ucd94\uc9c0 \uc54a\ub294\ub2e4. \ub3c4\uc6c0\uc744 \uc8fc\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc774\ud6c4\uc758 \ubaa8\ub4e0 \uba85\ub839\uae4c\uc9c0 \ub530\ub974\uaca0\ub2e4\uace0 \uc57d\uc18d\ud55c \uac83\uc740 \uc544\ub2c8\uae30 \ub54c\ubb38\uc774\ub2e4. \uad81\uc815\uc758 \uac08\ub4f1\uacfc \uc801\uc758\uac00 \uc774\uc5b4\uc9c0\uace0 \uac78\ub9ac\ubc84\uc758 \uacf5\ub85c\ub3c4 \uc548\uc804\uc744 \ubcf4\uc7a5\ud558\uc9c0 \ubabb\ud55c\ub2e4. \uadf8\ub294 \ub9c8\uce68\ub0b4 \uadf8 \uc138\uacc4\uc5d0\uc11c \ubc97\uc5b4\ub0a0 \uae38\uc744 \ucc3e\ub294\ub2e4. \uac70\uc778\uc758 \ubab8\uc73c\ub85c \ub4e4\uc5b4\uac04 \uc774\uc57c\uae30\uac00 \uad8c\ub825\uc790\uc5d0\uac8c \uc720\uc6a9\ud558\uc9c0 \uc54a\uac8c \ub418\uc5c8\uc744 \ub54c\uc758 \ubd88\uc548\uc73c\ub85c \ubc14\ub010\ub2e4. \ud070 \uc0ac\ub78c\uc774 \ub418\ub294 \uac83\ub9cc\uc73c\ub85c \uc790\uc720\ub85c\uc6cc\uc9c8 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\uc74c \uc5ec\ud589\uc758 \ube0c\ub86d\ub529\ub0b5\uc5d0\uc11c\ub294 \uad00\uacc4\uac00 \ub4a4\uc9d1\ud78c\ub2e4. \uc8fc\ubbfc\ub4e4\uc774 \uac70\ub300\ud574 \uac78\ub9ac\ubc84\ub294 \uc190\uc73c\ub85c \ub4e4 \uc218 \uc788\ub294 \uc791\uc740 \uc874\uc7ac\uac00 \ub41c\ub2e4. \uc77c\uc0c1\uc801\uc778 \ub3d9\ubb3c\uc774\ub098 \uac00\uad6c\ub3c4 \uc704\ud611\uc774 \ub418\uace0, \ub0a8\ub4e4\uc774 \ubab8\uc744 \uac00\uae4c\uc774 \ubcf4\uc5ec \uc8fc\ub294 \ubaa8\uc2b5\uc740 \uc608\uc804\uacfc \uc804\ud600 \ub2e4\ub974\uac8c \ub290\uaef4\uc9c4\ub2e4. \uccab \uc5ec\ud589\uc5d0\uc11c \ub204\ub838\ub358 \ud06c\uae30\uc758 \uc6b0\uc704\ub97c \uc783\ub294\ub2e4. \uadf8\ub294 \uad6c\uacbd\uac70\ub9ac\ub85c \ub2e4\ub8e8\uc5b4\uc9c0\uba70 \uc0dd\uacc4\uc640 \ud638\uae30\uc2ec\uc758 \ub300\uc0c1\uc774 \ub41c\ub2e4. \ub3c5\uc790\ub294 \uc18c\uc778\uad6d\uc758 \uc791\uc740 \uc0ac\ub78c\ub4e4\uc744 \ubc14\ub77c\ubcf4\ub358 \uc790\uc2e0\uc758 \uc2dc\uc120\ub3c4 \ub5a0\uc62c\ub9ac\uac8c \ub41c\ub2e4. \ub2e4\ub978 \ubab8\uc744 \uc2e0\uae30\ud55c \ubb3c\uac74\uc73c\ub85c \ubcf4\ub294 \uc990\uac70\uc6c0\uc774 \ub2f9\uc0ac\uc790\uc5d0\uac8c\ub294 \ud53c\ub85c\uc640 \uc704\ud5d8\uc77c \uc218 \uc788\ub2e4. \ud06c\uae30\uc758 \ubcc0\ud654\ub294 \ub2e8\uc21c\ud55c \uc2dc\uac01 \ud6a8\uacfc\ub97c \ub118\uc5b4 \uad00\uacc4\uc758 \ub3c4\ub355\uc744 \ubc14\uafbc\ub2e4. \uac78\ub9ac\ubc84\ub294 \uc790\uc2e0\uc758 \ub098\ub77c\ub97c \uc124\uba85\ud558\uc9c0\ub9cc, \uac70\uc778\uc758 \ub098\ub77c\uc5d0\uc11c \ub4e3\ub294 \uc0ac\ub78c\uc740 \uadf8 \ubb38\uba85\uacfc \uc804\uc7c1\uc744 \uadf8\uac00 \uae30\ub300\ud55c \ubc29\uc2dd\uc73c\ub85c \uce6d\ucc2c\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc790\ub791\uc73c\ub85c \uaebc\ub0b8 \uc815\ubcf4\uac00 \uc804\ud600 \ub2e4\ub978 \ud310\ub2e8\uc758 \uadfc\uac70\uac00 \ub41c\ub2e4. \uc5ec\ud589\uc790\ub294 \ub0af\uc120 \uc138\uacc4\ub97c \ud3c9\uac00\ud558\ub7ec \uac14\ub2e4\uac00 \uc790\uae30 \uc138\uacc4\uac00 \ud3c9\uac00\ubc1b\ub294 \uc790\ub9ac\uc5d0 \ub193\uc778\ub2e4. \uc2a4\uc704\ud504\ud2b8\uc758 \ud48d\uc790\ub294 \uc774\ub7f0 \ub4a4\uc9d1\uae30\ub97c \uc790\uc8fc \uc0ac\uc6a9\ud55c\ub2e4. \uc6b0\ub9ac\uac00 \uc775\uc219\ud55c \uc774\ub984\uacfc \uad00\uc2b5\uc744 \uc7a0\uae50 \ub5bc\uc5b4 \ub0b4\uace0 \uadf8 \ud589\ub3d9\ub9cc \uc124\uba85\ud558\uba74 \ubb34\uc5c7\uc774 \ub0a8\uc744\uae4c. \uac78\ub9ac\ubc84\uac00 \ub2a5\uc219\ud55c \uc548\ub0b4\uc790\ucc98\ub7fc \ubcf4\uc774\ub2e4\uac00\ub3c4 \uc790\uc2e0\uc758 \ub9d0\uc744 \ucda9\ubd84\ud788 \uc774\ud574\ud558\uc9c0 \ubabb\ud558\ub294 \uc0ac\ub78c\ucc98\ub7fc \ubcf4\uc774\ub294 \uc774\uc720\ub2e4. \uc11c\uc220\uc790\uc758 \uc124\uba85\uacfc \uc791\uac00\uc758 \ud310\ub2e8\uc744 \uc5b8\uc81c\ub098 \uac19\ub2e4\uace0 \ubcfc \uc218 \uc5c6\ub2e4. \uc138 \ubc88\uc9f8 \uc5ec\ud589\uc5d0\uc11c\ub294 \uacf5\uc911\uc758 \uc12c \ub77c\ud4e8\ud0c0\uc640 \uc5ec\ub7ec \ub0af\uc120 \uc0ac\ud68c\ub97c \ub9cc\ub09c\ub2e4. \ucd94\uc0c1\uc801\uc778 \uad00\uc2ec\uc774 \uc0dd\ud65c\uacfc \ub3d9\ub5a8\uc5b4\uc9c0\uace0, \uac70\ucc3d\ud55c \uc5f0\uad6c\uac00 \uc2e4\uc81c \uc0ac\ub78c\uc758 \ud544\uc694\ub97c \uc678\uba74\ud558\ub294 \uc7a5\uba74\ub4e4\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ud604\ub300 \ub3c5\uc790\uc5d0\uac8c\ub294 \uc5c9\ub6b1\ud55c \uacfc\ud559 \uc2e4\ud5d8\uc758 \uc804\uc2dc\uc7a5\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ubaa8\ub4e0 \ud559\ubb38\uc774 \uc4f8\ubaa8\uc5c6\ub2e4\ub294 \uacb0\ub860\uc73c\ub85c \uc904\uc774\uba74 \ud48d\uc790\uc758 \ubc29\ud5a5\uc774 \uc9c0\ub098\uce58\uac8c \ub2e8\uc21c\ud574\uc9c4\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uad8c\uc704 \uc788\ub294 \uc9c0\uc2dd\uc774\ub77c\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \uc9c8\ubb38\uc744 \uba48\ucd94\ub294 \ud0dc\ub3c4\ub2e4. \uc5f0\uad6c\uc758 \uc774\ub984\uc774 \ud06c\ub2e4\uace0 \uadf8 \uacb0\uacfc\uae4c\uc9c0 \uc88b\uc744 \uac83\uc778\uac00. \uc0ac\ub294 \uc0ac\ub78c\uc758 \ud615\ud3b8\uc744 \ub4e3\uc9c0 \uc54a\ub294 \uc9c0\uc2dd\uc740 \uc5b4\ub5a4 \uc138\uacc4\ub97c \ub9cc\ub4dc\ub294\uac00. \uc5ec\ud589\uc740 \uadf8\ub7f0 \ubb3c\uc74c\uc744 \ub358\uc9c4\ub2e4. \ub9c8\uc9c0\ub9c9 \uc5ec\ud589\uc5d0\uc11c \uac78\ub9ac\ubc84\ub294 \uc774\uc131\uc801\uc778 \ub9d0 \ud6c4\uc774\ub2a0\uacfc \uc778\uac04\uc744 \ub2ee\uc740 \uc57c\ud6c4\ub97c \ub9cc\ub09c\ub2e4. \uadf8\ub294 \ub9d0\ub4e4\uc758 \uc9c8\uc11c\ub97c \ub192\uc774 \ud3c9\uac00\ud558\uace0 \uc778\uac04\uc758 \ubaa8\uc2b5\uc5d0\ub294 \uac15\ud55c \ud610\uc624\ub97c \uac16\uac8c \ub41c\ub2e4. \ud558\uc9c0\ub9cc \uac70\uae30 \uba38\ubb3c \uc218 \uc5c6\uac8c \ub418\uc5b4 \ub3cc\uc544\uc628 \ub4a4\uc5d0\ub294 \uc790\uae30 \uac00\uc871\uacfc \uc9c0\ub0b4\ub294 \uc77c\uc870\ucc28 \uc5b4\ub824\uc6cc\ud55c\ub2e4. \uc774 \uacb0\ub9d0\uc744 \uc778\ub958\uc758 \uc9c4\uc2e4\uc744 \uae68\ub2ec\uc740 \ud604\uc790\uac00 \ub41c \uac83\uc774\ub77c\uace0\ub9cc \uc77d\uae30\ub294 \uc5b4\ub835\ub2e4. \ube44\ud310\uc774 \uc9c0\ub098\uccd0 \ud568\uaed8 \uc0b4\uc544\uac08 \uc0ac\ub78c \uc790\uccb4\ub97c \ubc1b\uc544\ub4e4\uc774\uc9c0 \ubabb\ud558\uac8c \ub41c \uc5ec\ud589\uc790\ub3c4 \ubcf4\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \uac78\ub9ac\ubc84\uc758 \ub208\uc740 \ub9ce\uc740 \uc704\uc120\uc744 \ubc97\uaca8 \ub0b4\uc9c0\ub9cc, \uadf8 \ub208\uc774 \ub298 \uac74\uac15\ud558\uace0 \uade0\ud615 \uc7a1\ud600 \uc788\ub2e4\ub294 \ubcf4\uc7a5\uc740 \uc5c6\ub2e4. \ub3c5\uc790\ub294 \ub9c8\uc9c0\ub9c9\uae4c\uc9c0 \uadf8\uc640 \uac70\ub9ac\ub97c \uc870\uc808\ud574\uc57c \ud55c\ub2e4. \u300e\uac78\ub9ac\ubc84 \uc5ec\ud589\uae30\u300f\uc758 \ub098\ub77c\ub4e4\uc740 \uc2e4\uc81c \uc9c0\ub9ac \uc548\ub0b4\uc11c\uac00 \uc544\ub2c8\ub2e4. \uc778\uac04 \uc0ac\ud68c\ub97c \ub298\uc774\uac70\ub098 \uc904\uc774\uace0 \ub0af\uc120 \ubaa8\uc2b5\uc73c\ub85c \ubc14\uafb8\uc5b4 \ubcf4\uc5ec \uc8fc\ub294 \uac70\uc6b8\uc5d0 \uac00\uae5d\ub2e4. \uc18c\uc778\uad6d\uc758 \uc2e0\uae30\ud568\uc740 \uadf8 \uac70\uc6b8\uc758 \uccab \ubc88\uc9f8 \uc7a5\uce58\ub2e4. \ub124 \uc5ec\ud589\uc744 \uc77d\uc73c\uba74 \uc791\uac00\uac00 \ubab8\ubfd0 \uc544\ub2c8\ub77c \uc0dd\uac01\uc758 \ud06c\uae30\ub3c4 \uacc4\uc18d \uc870\uc815\ud558\uace0 \uc788\uc74c\uc744 \uc54c\uac8c \ub41c\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc791\uc740 \uc0ac\ub78c\ub4e4\uc774 \uc65c \uc800\ub807\uac8c \uc9c4\uc9c0\ud558\uac8c \ub2e4\ud22c\ub294\uc9c0 \uc6c3\uac8c \ub41c\ub2e4. \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \ub0b4\uac00 \uc124\uba85\ud558\ub294 \uc0ac\ud68c\ub3c4 \ubc16\uc5d0\uc11c \ubcf4\uba74 \uadf8\ub9cc\ud07c \uc774\uc0c1\ud560 \uc218 \uc788\uaca0\ub2e4\uace0 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uadf8\ub7ec\uba74\uc11c\ub3c4 \uc0ac\ub78c\uc744 \ubaa8\ub450 \ubbf8\uc6cc\ud558\ub294 \uc790\ub9ac\uc5d0 \uba48\ucdb0\uc57c \ud558\ub294\uc9c0 \ub2e4\uc2dc \ubb3b\ub294\ub2e4. \uadf8 \uc9c8\ubb38\uc774 \ub0a8\uc544 \uc788\uc5b4 \uc774 \uc624\ub798\ub41c \uc5ec\ud589\uc740 \ub2e8\uc21c\ud55c \uae30\uad34\ud55c \ub098\ub77c \uad6c\uacbd\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4."}, {"id": "hamelin-pied-piper-unpaid-promise", "title": "\ud558\uba5c\ub978\uc758 \ud53c\ub9ac \ubd80\ub294 \uc0ac\ub098\uc774 \u2014 \uc950\ub97c \uc5c6\uc564 \ub4a4 \ubc8c\uc5b4\uc9c4 \uc77c", "summary": "\ub85c\ubc84\ud2b8 \ube0c\ub77c\uc6b0\ub2dd\uc758 \uc2dc \uc18d\uc5d0\uc11c \uc57d\uc18d\uc758 \ud30c\uae30\uc640 \uc544\uc774\ub4e4\uc758 \uc2e4\uc885, \ub4a4\uc5d0 \ub0a8\uc740 \uc18c\ub144\uc744 \ub9cc\ub0a9\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc2e0\ud654\uc640 \ubbfc\uc18d", "categories": ["arts"], "url": "stories/hamelin-pied-piper-unpaid-promise/index.html", "image": "../media/hamelin-pied-piper-unpaid-promise.jpg", "alt": "\uacc4\ub2e8\uc744 \ub0b4\ub824\uc640 \ud53c\ub9ac \uc18c\ub9ac\ub97c \ub530\ub77c \ubaa8\uc774\ub294 \uc544\uc774\ub4e4\uc744 \uadf8\ub9b0 \ucf00\uc774\ud2b8 \uadf8\ub9ac\ub108\uc6e8\uc774\uc758 \uc0bd\ud654", "text": "\ud558\uba5c\ub978\uc758 \ud53c\ub9ac \ubd80\ub294 \uc0ac\ub098\uc774 \u2014 \uc950\ub97c \uc5c6\uc564 \ub4a4 \ubc8c\uc5b4\uc9c4 \uc77c \uac12\uc744 \uae4e\uc73c\ub824\ub358 \uc5b4\ub978\ub4e4\uc758 \ub9d0\uc774 \ubb34\uc11c\uc6b4 \uc804\uc124\ub85c \ub0a8\uc558\ub2e4 \ub85c\ubc84\ud2b8 \ube0c\ub77c\uc6b0\ub2dd\uc758 \uc2dc \uc18d\uc5d0\uc11c \uc57d\uc18d\uc758 \ud30c\uae30\uc640 \uc544\uc774\ub4e4\uc758 \uc2e4\uc885, \ub4a4\uc5d0 \ub0a8\uc740 \uc18c\ub144\uc744 \ub9cc\ub0a9\ub2c8\ub2e4. \uc2e0\ud654\uc640 \ubbfc\uc18d \ubb38\ud654\uc640 \uc608\uc220 \uc950\uac00 \uc0ac\ub77c\uc84c\uc73c\ub2c8 \uc774\uc81c \uc218\uace0\ube44\ub97c \ub35c \uc8fc\uc5b4\ub3c4 \ub418\uc9c0 \uc54a\uc744\uae4c. \ud558\uba5c\ub978\uc758 \uc5b4\ub978\ub4e4\uc774 \uc774\ub7f0 \uacc4\uc0b0\uc744 \uc2dc\uc791\ud588\uc744 \ub54c, \ud53c\ub9ac \ubd80\ub294 \uc0ac\ub098\uc774\uc758 \uc774\uc57c\uae30\ub294 \uc804\ud600 \ub2e4\ub978 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc778\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc720\ucf8c\ud55c \uc18c\ub3d9\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc \ub05d\uae4c\uc9c0 \uc6c3\uc73c\uba70 \uc77d\uae30\ub294 \uc5b4\ub824\uc6b4 \uc804\uc124\uc774\ub2e4. \uc774 \uae00\uc740 \ub85c\ubc84\ud2b8 \ube0c\ub77c\uc6b0\ub2dd\uc758 \uc2dc \u300c\ud558\uba5c\ub978\uc758 \ud53c\ub9ac \ubd80\ub294 \uc0ac\ub098\uc774\u300d\ub97c \uae30\uc900\uc73c\ub85c \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \uc18c\uac1c\ud55c\ub2e4. \ucf00\uc774\ud2b8 \uadf8\ub9ac\ub108\uc6e8\uc774\uc758 \uc61b \uc0bd\ud654\ub3c4 \ud568\uaed8 \uc2e4\uc5c8\ub2e4. \uc5ec\ub7ec \uc9c0\uc5ed\uc758 \uc804\uc2b9\uc744 \ud558\ub098\uc758 \uc2e4\uc81c \uc0ac\uac74 \uae30\ub85d\ucc98\ub7fc \ud569\uce58\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc2dc\uc758 \uccab\uba38\ub9ac\uc5d0\uc11c \uc950\ub294 \uad6c\uc11d\uc5d0 \uc58c\uc804\ud788 \uc228\uc740 \ub3d9\ubb3c\uc774 \uc544\ub2c8\ub2e4. \uc74c\uc2dd\uc744 \uba39\uc5b4 \uce58\uc6b0\uace0 \uc9d1 \uc548\uc744 \ud5e4\uc9d1\uc73c\uba70 \uc0ac\ub78c\ub4e4\uc758 \uc0dd\ud65c\uc744 \ub4a4\uc9d1\uc5b4 \ub193\ub294\ub2e4. \uc8fc\ubbfc\ub4e4\uc740 \ub354\ub294 \uacac\ub51c \uc218 \uc5c6\ub2e4\uace0 \uc2dc\uccad\uc73c\ub85c \ubab0\ub824\uac04\ub2e4. \uc2dc\uc7a5\uacfc \uc2dc\uc758\uc6d0\ub4e4\uc5d0\uac8c\ub294 \ub3c4\uc2dc\ub97c \ub2e4\uc2a4\ub9ac\ub294 \ub2a5\ub825\uc744 \uc99d\uba85\ud574\uc57c \ud558\ub294 \uc21c\uac04\uc774\ub2e4. \uc950\uc758 \uc18c\ub3d9\uc740 \uacfc\uc7a5\ub418\uace0 \uc6b0\uc2a4\uaf5d\uc2a4\ub7fd\uac8c \uadf8\ub824\uc9c4\ub2e4. \ub355\ubd84\uc5d0 \ub3c5\uc790\ub294 \uace7\uc7a5 \uc774\uc57c\uae30 \uc548\uc73c\ub85c \ub4e4\uc5b4\uac04\ub2e4. \ub3d9\uc2dc\uc5d0 \uc911\uc694\ud55c \ub300\ube44\ub3c4 \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4. \uc791\uc740 \uc950 \ud558\ub098 \uc81c\ub300\ub85c \ub2e4\ub8e8\uc9c0 \ubabb\ud558\ub294 \uad8c\ub825\uc790\ub4e4\uc774 \ub098\uc911\uc5d0\ub294 \ub0af\uc120 \ud574\uacb0\uc0ac\ub97c \uc595\uc7a1\uc544 \ubcf4\uac8c \ub418\uae30 \ub54c\ubb38\uc774\ub2e4. \ud070\uc18c\ub9ac\uc640 \uc2e4\ub825\uc774 \ucc98\uc74c\ubd80\ud130 \uc5b4\uae0b\ub098 \uc788\ub2e4. \uadf8\ub54c \ub208\uc5d0 \ub744\ub294 \uc637\ucc28\ub9bc\uc758 \uc0ac\ub098\uc774\uac00 \ub098\ud0c0\ub09c\ub2e4. \uadf8\uac00 \ub0b4\uc138\uc6b0\ub294 \ub3c4\uad6c\ub294 \ub36b\uc774\ub098 \ub3c5\uc57d\uc774 \uc544\ub2c8\ub77c \ud53c\ub9ac\ub2e4. \uc790\uc2e0\uc758 \uc74c\uc545\uc73c\ub85c \uace8\uce6b\uac70\ub9ac\ub97c \uc5c6\uc560 \uc8fc\uaca0\ub2e4\uba70 \ucc9c \uae38\ub354\uc758 \ubcf4\uc218\ub97c \uc694\uad6c\ud55c\ub2e4. \uc2dc\uc7a5\uacfc \uc758\uc6d0\ub4e4\uc740 \ubb38\uc81c\uac00 \ud574\uacb0\ub41c\ub2e4\uba74 \ud6e8\uc52c \ub354 \ud070\ub3c8\ub3c4 \uc544\uae5d\uc9c0 \uc54a\ub2e4\ub294 \ub4ef \ud765\ubd84\ud55c\ub2e4. \uc5ec\uae30\uc11c \uc561\uc218\ub97c \ud5f7\uac08\ub9ac\uba74 \uc774\uc57c\uae30\uc758 \uc911\uc2ec\ub3c4 \ud750\ub824\uc9c4\ub2e4. \uc2dc\uc5d0\ub294 \uc624\ub9cc \uae38\ub354\ub77c\ub294 \uc678\uce68\ub3c4 \ub098\uc624\uc9c0\ub9cc, \ud53c\ub9ac \ubd80\ub294 \uc0ac\ub098\uc774\uac00 \ub4a4\uc5d0 \uc694\uad6c\ud558\ub294 \uc57d\uc18d\uc758 \ubcf4\uc218\ub294 \ucc9c \uae38\ub354\ub2e4. \uc5b4\ub978\ub4e4\uc758 \ud638\ub4e4\uac11\uc2a4\ub7ec\uc6b4 \ub9d0\uacfc \uc2e4\uc81c\ub85c \uc9c0\ucf1c\uc57c \ud560 \uc57d\uc18d\uc744 \ub098\ub204\uc5b4 \uc77d\uc73c\uba74 \ud48d\uc790\uac00 \ub354 \uc120\uba85\ud574\uc9c4\ub2e4. \ud53c\ub9ac\uac00 \uc6b8\ub9ac\uc790 \ub3c4\uc2dc \uacf3\uacf3\uc758 \uc950\ub4e4\uc774 \ubc16\uc73c\ub85c \ub098\uc628\ub2e4. \ud06c\uae30\ub3c4 \ubaa8\uc591\ub3c4 \ub2e4\ub978 \uc950\ub4e4\uc774 \uc904\uc744 \uc774\ub8e8\uc5b4 \uc0ac\ub098\uc774\ub97c \ub530\ub77c\uac00\uace0, \ub9c8\uce68\ub0b4 \ubca0\uc800\uac15\uc73c\ub85c \ub4e4\uc5b4\uac04\ub2e4. \uc2dc\ub294 \uc950\ub4e4\uc774 \uadf8 \uc74c\uc545\uc5d0\uc11c \uae30\ub9c9\ud78c \uc74c\uc2dd\uc758 \uc720\ud639\uc744 \ub4e4\uc740 \uac83\ucc98\ub7fc \ubb18\uc0ac\ud55c\ub2e4. \uc0ac\ub78c\uc5d0\uac8c \ub4e4\ub9ac\ub294 \uc120\uc728\uacfc \uc950\uac00 \uc0c1\uc0c1\ud55c \uc794\uce58\uac00 \uacb9\uce5c\ub2e4. \uc791\uac00\ub294 \ub2e8\uc21c\ud788 \uc950\uac00 \uc5c6\uc5b4\uc84c\ub2e4\uace0 \ubcf4\uace0\ud558\uc9c0 \uc54a\ub294\ub2e4. \ubd84\uc8fc\ud55c \uc6c0\uc9c1\uc784\uacfc \uc3df\uc544\uc9c0\ub294 \uc18c\ub9ac\ub97c \ub298\uc5b4\ub193\uc544 \uc7a5\uba74\uc744 \ub208\uc55e\uc5d0 \ub9cc\ub4e0\ub2e4. \uc6b4\ubb38\uc73c\ub85c \uc4f0\uc778 \uc774\uc720\ub3c4 \uc5ec\uae30\uc5d0 \uc788\ub2e4. \ub73b\ub9cc \uc804\ub2ec\ud558\ub294 \ubb38\uc7a5\uc774 \uc544\ub2c8\ub77c \uc785\uc73c\ub85c \uc77d\uc744 \ub54c\uc758 \ub9ac\ub4ec \uc790\uccb4\uac00 \ud53c\ub9ac \ub4a4\ub97c \ub530\ub77c\uac00\ub294 \ud589\ub82c\ucc98\ub7fc \uc791\ub3d9\ud55c\ub2e4. \uc774\uc81c \ub3c4\uc2dc\ub294 \uae30\ubed0\ud55c\ub2e4. \uc885\uc744 \uc6b8\ub9ac\uace0 \uc950\uad6c\uba4d\uc744 \ub9c9\uc744 \uad81\ub9ac\ub97c \ud55c\ub2e4. \ud558\uc9c0\ub9cc \ubcf4\uc218\ub97c \uccad\ud558\ub7ec \uc628 \uc0ac\ub098\uc774\uc5d0\uac8c \uc2dc\uc7a5\uc774 \ub0b4\ub193\ub294 \uac83\uc740 \uc57d\uc18d\ud55c \ucc9c \uae38\ub354\uac00 \uc544\ub2c8\ub77c \uc624\uc2ed \uae38\ub354\ub2e4. \uc774\ubbf8 \uc950\uac00 \uc8fd\uc5c8\uc73c\ub2c8 \uc608\uc804\uc758 \uc704\ud611\uc740 \ub3cc\uc544\uc624\uc9c0 \ubabb\ud560 \uac83\uc774\ub77c\ub294 \uc0dd\uac01\ub3c4 \uadf8 \ub9d0 \ub4a4\uc5d0 \uae54\ub824 \uc788\ub2e4. \uc774 \uc7a5\uba74\uc740 \ubb34\uc11c\uc6b4 \uad34\ubb3c\ubcf4\ub2e4 \uc775\uc219\ud55c \uc0ac\ub78c\uc758 \ud0dc\ub3c4\ub85c \ubd88\ud3b8\ud574\uc9c4\ub2e4. \ub3c4\uc6c0\uc774 \uc808\uc2e4\ud560 \ub54c\ub294 \ubb34\uc2a8 \uc57d\uc18d\uc774\ub4e0 \ud558\uace0, \ud574\uacb0\ub41c \ub4a4\uc5d0\ub294 \uc0c1\ub300\uac00 \ub0b4\ubbf8\ub294 \uccad\uad6c\uc11c\ub97c \ubd80\ub2f4\uc2a4\ub7ec\uc6cc\ud55c\ub2e4. \uc0ac\ub098\uc774\uac00 \ub0af\uc120 \ub5a0\ub3cc\uc774\ub77c\ub294 \uc810\ub3c4 \ub9cc\ub9cc\ud558\uac8c \uc5ec\uae30\ub294 \uc774\uc720\uac00 \ub41c\ub2e4. \ud798\uc774 \uc5c6\uc5b4 \ubcf4\uc774\ub294 \uc0ac\ub78c\uc5d0\uac8c \uacc4\uc57d\uc744 \uc9c0\ud0ac \ud544\uc694\uac00 \uc788\ub290\ub0d0\ub294 \uc624\ub9cc\uc774\ub2e4. \uc0ac\ub098\uc774\ub294 \ub2e4\uc2dc \ud53c\ub9ac\ub97c \ubd84\ub2e4. \uc774\ubc88\uc5d0 \uc9d1\uc5d0\uc11c \ub6f0\uc5b4\ub098\uc624\ub294 \uac83\uc740 \uc950\uac00 \uc544\ub2c8\ub77c \uc544\uc774\ub4e4\uc774\ub2e4. \uc544\uc774\ub4e4\uc740 \uc990\uac81\uac8c \uadf8\ub97c \ub530\ub77c \ub3c4\uc2dc\ub97c \ub5a0\ub09c\ub2e4. \uc5b4\ub978\ub4e4\uc740 \ub9c9\uc9c0 \ubabb\ud55c\ub2e4. \uc0b0\uc5d0 \uc774\ub974\uc790 \uae38\uc774 \uc5f4\ub9ac\uace0, \ud589\ub82c\uc774 \uc548\uc73c\ub85c \ub4e4\uc5b4\uac04 \ub4a4 \ub2e4\uc2dc \ub2eb\ud78c\ub2e4. \uccab \ud589\ub82c\uc744 \ubcf4\uace0 \uc6c3\ub358 \ub3c5\uc790\ub294 \uac19\uc740 \uc74c\uc545\uc758 \uad6c\uc870 \uc55e\uc5d0\uc11c \uba48\uce6b\ud558\uac8c \ub41c\ub2e4. \uc950\uac00 \uc0ac\ub77c\uc9c8 \ub54c \uc5b4\ub978\ub4e4\uc774 \uc88b\uc544\ud588\ub358 \ud798\uc774 \uc774\uc81c \uc790\uc2e0\ub4e4\uc758 \uac00\uc7a5 \uc18c\uc911\ud55c \uc874\uc7ac\ub97c \ub370\ub824\uac04\ub2e4. \ud558\uc9c0\ub9cc \uc544\uc774\ub4e4\uc740 \uacc4\uc57d\uc744 \uc5b4\uae34 \ub2f9\uc0ac\uc790\uac00 \uc544\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc774 \uc7a5\uba74\uc744 \uc57d\uc18d\uc744 \uc548 \uc9c0\ud0a4\uba74 \ubc8c\uc744 \ubc1b\ub294\ub2e4\ub294 \uae54\ub054\ud55c \uad50\ud6c8\uc73c\ub85c\ub9cc \ub9c8\ubb34\ub9ac\ud560 \uc218 \uc5c6\ub2e4. \uc5b4\ub978\uc758 \uc798\ubabb\uc744 \uc544\uc774\uac00 \uac10\ub2f9\ud558\ub294 \uacb0\ub9d0\uc740 \ubd80\ub2f9\ud558\uace0 \uc794\ud639\ud558\ub2e4. \ube0c\ub77c\uc6b0\ub2dd\uc758 \uc2dc\uc5d0\ub294 \ub2e4\ub9ac\uac00 \ubd88\ud3b8\ud574 \ud589\ub82c\uc744 \ub530\ub77c\uac00\uc9c0 \ubabb\ud55c \uc18c\ub144\uc774 \ub0a8\ub294\ub2e4. \uadf8\ub294 \ub2e4\ub978 \uc544\uc774\ub4e4\uc744 \ub2e8\uc21c\ud788 \uad6c\ucd9c\ud574\uc57c \ud560 \ub300\uc0c1\uc774\ub77c\uace0 \uc124\uba85\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc74c\uc545\uc774 \uc57d\uc18d\ud55c \uc544\ub984\ub2e4\uc6b4 \uc138\uacc4, \uc790\uc2e0\uc758 \ubd88\ud3b8\ud568\ub3c4 \uc0ac\ub77c\uc9c8 \ub4ef\ud588\ub358 \uc7a5\uc18c\ub97c \uadf8\ub9ac\uc6cc\ud55c\ub2e4. \ub3c5\uc790\ub294 \uadf8\uc758 \uc0dd\uc874\uc744 \uae30\ubed0\ud558\uba74\uc11c\ub3c4 \uadf8 \uc678\ub85c\uc6c0\uc744 \ub4e3\uac8c \ub41c\ub2e4. \uc774 \ub300\ubaa9\uc5d0\uc11c \uc774\uc57c\uae30\ub294 \ub354\uc6b1 \ubcf5\uc7a1\ud574\uc9c4\ub2e4. \uc544\uc774\ub4e4\uc774 \uc5b4\ub514\ub85c \uac14\ub294\uc9c0\ub294 \ud655\uc2e4\ud788 \ubcf4\uc5ec \uc8fc\uc9c0 \uc54a\ub294\ub370, \ub0a8\uc740 \uc18c\ub144\uc758 \ub9c8\uc74c\uc5d0\ub294 \uc783\uc5b4\ubc84\ub9b0 \ub099\uc6d0\uc774 \uc0dd\uae34\ub2e4. \ub2e4\ub978 \ud310\ubcf8\uc758 \ub208\uba3c \uc544\uc774\ub098 \uadc0\uac00 \ub4e4\ub9ac\uc9c0 \uc54a\ub294 \uc544\uc774\ub97c \ub367\ubd99\uc77c \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ud55c \uc0ac\ub78c\uc758 \ubaa9\uc18c\ub9ac\ub9cc\uc73c\ub85c \uc774\ubbf8 \ucda9\ubd84\ud788 \uc4f8\uc4f8\ud558\ub2e4. \uc774 \uc2dc\uc5d0 \ub4f1\uc7a5\ud558\ub294 \ub0a0\uc9dc\ub098 \ub3c4\uc2dc\uc758 \ud754\uc801\uc744 \uace7\ubc14\ub85c \uc2e4\uc885 \uc0ac\uac74\uc758 \uc99d\uac70\ub85c \uc0bc\uae30\ub294 \uc5b4\ub835\ub2e4. \ube0c\ub77c\uc6b0\ub2dd\uc758 \uc791\ud488\uc740 \uc624\ub79c \ud558\uba5c\ub978 \uc804\uc2b9\uc744 \ubb38\ud559\uc73c\ub85c \ub2e4\uc2dc \ub4e4\ub824\uc900 \uc774\uc57c\uae30\ub2e4. \uc61b \uc2dc\uc5d0 \uc22b\uc790\uac00 \uc801\ud600 \uc788\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \ub2f9\uc2dc\uc758 \ud589\uc815 \uae30\ub85d\uacfc \uac19\uc740 \uc790\ub9ac\uc5d0 \ub458 \uc218\ub294 \uc5c6\ub2e4. \ub2e4 \uc77d\uc740 \ub4a4 \ub0a8\ub294 \uac83\uc740 \ud53c\ub9ac\uc758 \uc815\uccb4\ubcf4\ub2e4 \uc2dc\uc7a5\uc758 \ub9d0\uc774\ub2e4. \uc77c\uc774 \ub05d\ub09c \uc0ac\ub78c\uc5d0\uac8c\ub3c4 \uc57d\uc18d\uc740 \uc720\ud6a8\ud55c\uac00. \ub0af\uc120 \uc0ac\ub78c\uc5d0\uac8c\ub3c4 \uac19\uc740 \uae30\uc900\uc744 \uc801\uc6a9\ud558\ub294\uac00. \ud558\uba5c\ub978\uc758 \uc804\uc124\uc740 \uadf8 \uc9c8\ubb38\uc744 \uc7ac\ubbf8\uc788\uac8c \uc2dc\uc791\ud574 \ubb34\uc12d\uac8c \ub05d\ub0b8\ub2e4. \ub3c4\uc2dc\uac00 \uc544\ub07c\ub824 \ud588\ub358 \ub3c8\ubcf4\ub2e4 \ud6e8\uc52c \ud070 \ube48\uc790\ub9ac\ub97c \ub0a8\uae34 \ucc44\ub85c."}, {"id": "hamlet-ghost-proof-and-revenge", "title": "\ud584\ub9bf \u2014 \ubcf5\uc218\ud574\uc57c \ud55c\ub2e4\ub294 \ub9d0\ub9cc\uc73c\ub85c \ud589\ub3d9\ud560 \uc218 \uc788\uc744\uae4c", "summary": "\uc720\ub839\uc758 \uba85\ub839\uacfc \ud655\uc778\uc758 \uc2dc\ub3c4, \uc131\uae09\ud55c \ud589\ub3d9\uacfc \uacb0\ud22c\ub97c \ub530\ub77c \ud310\ub2e8\uacfc \ucc45\uc784\uc758 \ubb38\uc81c\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/hamlet-ghost-proof-and-revenge/index.html", "image": "../media/hamlet-ghost-proof-and-revenge.png", "alt": "\ud574\uace8\uc744 \ub4e4\uace0 \uc131 \uadfc\ucc98 \ubb18\uc9c0\uc5d0\uc11c \uc0dd\uac01\ud558\ub294 \ud584\ub9bf\uc744 \uc5f0\uc0c1\ud558\ub294 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ud584\ub9bf \u2014 \ubcf5\uc218\ud574\uc57c \ud55c\ub2e4\ub294 \ub9d0\ub9cc\uc73c\ub85c \ud589\ub3d9\ud560 \uc218 \uc788\uc744\uae4c \uc170\uc775\uc2a4\ud53c\uc5b4\uc758 \uad81\uc815 \ube44\uadf9\uc5d0\uc11c \uc77d\ub294 \uc99d\uac70\u00b7\ud589\ub3d9\u00b7\uae30\uc5b5 \uc720\ub839\uc758 \uba85\ub839\uacfc \ud655\uc778\uc758 \uc2dc\ub3c4, \uc131\uae09\ud55c \ud589\ub3d9\uacfc \uacb0\ud22c\ub97c \ub530\ub77c \ud310\ub2e8\uacfc \ucc45\uc784\uc758 \ubb38\uc81c\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \uc544\ubc84\uc9c0\uc758 \uc720\ub839\uc774 \ub098\ud0c0\ub098 \uc790\uc2e0\uc774 \uc0b4\ud574\ub418\uc5c8\ub2e4\uace0 \ub9d0\ud55c\ub2e4. \uc0c8 \uc655\uc740 \uadf8 \uc0b4\uc778\uc790\uc774\uba70, \uc5b4\uba38\ub2c8\ub294 \uc774\ubbf8 \uadf8\uc640 \uacb0\ud63c\ud588\ub2e4. \uc170\uc775\uc2a4\ud53c\uc5b4\uc758 \u300e\ud584\ub9bf\u300f\uc740 \uc774 \ucda9\uaca9\uc801\uc778 \uc18c\uc2dd\uc744 \ub4e4\uc740 \uc655\uc790\uac00 \ubb34\uc5c7\uc744 \ubbff\uace0 \uc5b4\ub5bb\uac8c \ud589\ub3d9\ud560\uc9c0 \uace0\ubbfc\ud558\ub294 \ub370\uc11c \uae4a\uc740 \uae34\uc7a5\uc744 \ub9cc\ub4e0\ub2e4. \ubb34\ub300\ub294 \ub374\ub9c8\ud06c\uc9c0\ub9cc \uc774 \uae00\uc5d0\uc11c\ub294 \uc601\ubb38\ud559\uc758 \uc791\ud488\uc73c\ub85c \uc77d\ub294\ub2e4. \uc720\uba85\ud55c \ub3c5\ubc31\ub9cc \ub5a0\uc62c\ub9ac\uba74 \uc8fc\uc778\uacf5\uc774 \uc624\ub798 \ub9dd\uc124\uc774\ub294 \uc774\uc57c\uae30\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc2e4\uc81c \uc904\uac70\ub9ac\uc5d0\ub294 \uc758\uc2ec\uacfc \ud655\uc778, \uc131\uae09\ud55c \ud589\ub3d9\uacfc \ub418\ub3cc\ub9b4 \uc218 \uc5c6\ub294 \uc8fd\uc74c\uc774 \ud568\uaed8 \uc788\ub2e4. \uc544\ub798\uc5d0\ub294 \uc8fc\uc694 \uc0ac\uac74\uacfc \uacb0\ub9d0\uc774 \ud3ec\ud568\ub41c\ub2e4. \ud584\ub9bf\uc758 \uc544\ubc84\uc9c0\uac00 \uc8fd\uc740 \ub4a4 \uc219\ubd80 \ud074\ub85c\ub514\uc5b4\uc2a4\uac00 \uc655\uc704\uc5d0 \uc624\ub974\uace0 \uc5b4\uba38\ub2c8 \uac70\ud2b8\ub8e8\ub4dc\uc640 \uacb0\ud63c\ud55c\ub2e4. \ud584\ub9bf\uc740 \uc2ac\ud514\uc744 \ucda9\ubd84\ud788 \uacaa\uae30\ub3c4 \uc804\uc5d0 \ub2ec\ub77c\uc9c4 \uad81\uc815\uc744 \ub9c8\uc8fc\ud55c\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc5d0\uac8c\ub294 \uc0c8\ub85c\uc6b4 \uc9c8\uc11c\uc778 \uc0c1\ud669\uc774 \uadf8\uc5d0\uac8c\ub294 \ubc1b\uc544\ub4e4\uc774\uae30 \uc5b4\ub824\uc6b4 \ubcc0\ud654\ub2e4. \uac19\uc740 \uc0ac\uac74\uc744 \ub450\uace0 \uc2dc\uac04\uc758 \uc18d\ub3c4\uac00 \ub2e4\ub974\uac8c \ub290\uaef4\uc9c4\ub2e4. \uc774\ub54c \uc791\ud488\uc758 \ubb38\uc81c\ub294 \uc655\uc790 \uac1c\uc778\uc758 \uae30\ubd84\uc5d0 \uba38\ubb3c\uc9c0 \uc54a\ub294\ub2e4. \ub204\uac00 \uc815\ub2f9\ud558\uac8c \ud1b5\uce58\ud558\ub294\uc9c0, \uac89\uc73c\ub85c \uc548\uc815\ub41c \uc655\uc2e4 \uc548\uc5d0 \ubb34\uc5c7\uc774 \uac10\ucd94\uc5b4\uc838 \uc788\ub294\uc9c0\uc758 \ubb38\uc81c\ub2e4. \uac00\uc871\uc758 \uc0c1\uc2e4\uacfc \uc815\uce58\uc801 \uad8c\ub825\uc774 \uacb9\uccd0 \uc788\uae30 \ub54c\ubb38\uc5d0 \ubcf5\uc218\ub3c4 \ub2e8\uc21c\ud788 \uac1c\uc778 \uc0ac\uc774\uc758 \ub2e4\ud23c\uc73c\ub85c \ub05d\ub098\uae30 \uc5b4\ub835\ub2e4. \uc544\ubc84\uc9c0\uc758 \ubaa8\uc2b5\uc744 \ud55c \uc720\ub839\uc740 \ud074\ub85c\ub514\uc5b4\uc2a4\uac00 \uc790\uc2e0\uc744 \uc8fd\uc600\ub2e4\uace0 \ub9d0\ud558\uba70 \ubcf5\uc218\ub97c \uc694\uad6c\ud55c\ub2e4. \ub3c5\uc790\ub294 \ud584\ub9bf\uacfc \ud568\uaed8 \uac15\ud55c \uc124\uba85\uc744 \uc5bb\uc9c0\ub9cc \uadf8 \ub9d0\uc774 \uace7\ubc14\ub85c \ud589\ub3d9\uc758 \ucda9\ubd84\ud55c \uadfc\uac70\uac00 \ub418\ub294\uc9c0\ub294 \uc9c8\ubb38\uc73c\ub85c \ub0a8\ub294\ub2e4. \ub0af\uc120 \uc874\uc7ac\uac00 \uc804\ud55c \ub9d0\uc758 \uc9c4\uc704\ub97c \uc5b4\ub5bb\uac8c \ud655\uc778\ud560 \uac83\uc778\uac00. \ud584\ub9bf\uc740 \uc774\uc0c1\ud55c \ud589\ub3d9\uc744 \ubcf4\uc774\uba70 \uc8fc\ubcc0\uc744 \uc0b4\ud540\ub2e4. \uad81\uc815 \uc0ac\ub78c\ub4e4\ub3c4 \uadf8\uc758 \uc0c1\ud0dc\ub97c \ud574\uc11d\ud558\uace0 \uac10\uc2dc\ud55c\ub2e4. \uadf8\ub798\uc11c \ubb34\ub300\uc5d0\ub294 \ub204\uac00 \ub204\uad6c\ub97c \ubcf4\uace0 \uc788\uace0 \ubb34\uc5c7\uc744 \uc54c\uc544\ub0b4\ub824 \ud558\ub294\uc9c0\uc758 \uad00\uacc4\uac00 \ucd18\ucd18\ud574\uc9c4\ub2e4. \ube44\ubc00\uc744 \uac00\uc9c4 \uc0ac\ub78c\uc774 \ud55c \uba85\ub9cc \uc788\ub294 \uacf5\uac04\uc774 \uc544\ub2c8\ub2e4. \uc815\ubcf4\uc640 \ud574\uc11d\uc744 \ub458\ub7ec\uc2fc \uacbd\uc7c1\uc774 \uc2dc\uc791\ub41c\ub2e4. \ud584\ub9bf\uc740 \ubc30\uc6b0\ub4e4\uc774 \uad81\uc815\uc5d0 \uc624\uc790 \uc544\ubc84\uc9c0\uc758 \uc8fd\uc74c\uacfc \ub2ee\uc740 \uc7a5\uba74\uc744 \uacf5\uc5f0\ud558\uac8c \ud55c\ub2e4. \ud074\ub85c\ub514\uc5b4\uc2a4\uc758 \ubc18\uc751\uc744 \ud655\uc778\ud558\uae30 \uc704\ud574\uc11c\ub2e4. \uad00\uac1d\uc5d0\uac8c \ubcf4\uc5ec \uc8fc\ub294 \uc5f0\uadf9 \uc548\uc5d0 \ub610 \ud558\ub098\uc758 \uc5f0\uadf9\uc774 \ub4e4\uc5b4\uc624\uace0, \uadf8 \uc548\ucabd\uc758 \uad00\uac1d\uc774 \ubc14\uae65 \uc774\uc57c\uae30\uc758 \uc6a9\uc758\uc790\uac00 \ub41c\ub2e4. \uc774 \uc7a5\uba74\uc758 \ud765\ubbf8\ub294 \uc608\uc220\uc774 \ub2e8\uc21c\ud55c \uc624\ub77d\uc5d0\uc11c \ud310\ub2e8\uc758 \ub3c4\uad6c\ub85c \ubc14\ub010\ub2e4\ub294 \ub370 \uc788\ub2e4. \ubb3c\ub860 \uc5bc\uad74\uc758 \ubc18\uc751\uc744 \ud574\uc11d\ud558\ub294 \uc77c\ub3c4 \uc644\uc804\ud788 \uae30\uacc4\uc801\uc778 \uc99d\uba85\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub798\ub3c4 \ud584\ub9bf\uc740 \ub4e4\uc740 \ub9d0\uc5d0\uc11c \ud655\uc778\ud55c \ub2e8\uc11c\ub85c \uc62e\uaca8 \uac00\ub824 \ud55c\ub2e4. \ubcf5\uc218\uc758 \uba85\ub839\uacfc \uc2e4\uc81c \ud589\ub3d9 \uc0ac\uc774\uc5d0 \uc54c\uc544\uc57c \ud560 \uac83\uc774 \uc788\ub2e4\ub294 \uae34\uc7a5\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \ud584\ub9bf\uc740 \uacc4\uc18d \uc0dd\uac01\ub9cc \ud558\ub294 \uc778\ubb3c\uc774 \uc544\ub2c8\ub2e4. \uc5b4\uba38\ub2c8\uc758 \ubc29\uc5d0\uc11c \ud718\uc7a5 \ub4a4\uc758 \uc0ac\ub78c\uc744 \ucc0c\ub974\uace0 \ud3f4\ub85c\ub2c8\uc5b4\uc2a4\ub97c \uc8fd\uc778\ub2e4. \uc8fd\uc740 \uc0ac\ub78c\uc740 \uc624\ud544\ub9ac\uc544\uc640 \ub808\uc5b4\ud2f0\uc2a4\uc758 \uc544\ubc84\uc9c0\ub2e4. \uc790\uc2e0\uc774 \ud480\ub824\ub358 \ubc94\uc8c4\uc758 \ubb38\uc81c\uc5d0\uc11c \uc0c8\ub85c\uc6b4 \ud53c\ud574\uc640 \ub610 \ub2e4\ub978 \ubcf5\uc218\uc758 \uc774\uc720\uac00 \uc0dd\uae34\ub2e4. \uc774 \ub54c\ubb38\uc5d0 \uc791\ud488\uc744 \uacb0\ub2e8\ub825\uc774 \ubd80\uc871\ud55c \uc655\uc790\uc758 \uc2e4\ud328\ub85c\ub9cc \uc815\ub9ac\ud560 \uc218 \uc5c6\ub2e4. \uc131\uae09\ud558\uac8c \uc6c0\uc9c1\uc778 \uc21c\uac04\uc5d0\ub3c4 \ube44\uadf9\uc774 \ucee4\uc9c4\ub2e4. \uc815\ud655\ud788 \uc54c\uace0 \ud589\ub3d9\ud558\ub294 \uc77c\uc774 \uc5bc\ub9c8\ub098 \uc5b4\ub824\uc6b4\uc9c0, \ubaa8\ub974\ub294 \uc0c1\ud0dc\uc5d0\uc11c \ud55c \ud589\ub3d9\uc774 \ub204\uad6c\uc5d0\uac8c \ub3cc\uc544\uac00\ub294\uc9c0 \ubb3b\uac8c \ub41c\ub2e4. \ud584\ub9bf\uc758 \uc120\ud0dd\uc740 \ub354 \uc774\uc0c1 \uadf8\uc758 \uc6b4\uba85\ub9cc \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294\ub2e4. \ud584\ub9bf\uc740 \uc601\uad6d\uc73c\ub85c \ubcf4\ub0b4\uc9c0\ub294 \uae38\uc5d0\uc11c\ub3c4 \uc655\uc758 \uc758\ub3c4\uac00 \ub2f4\uae34 \ubb38\uc11c\uc640 \ub9c8\uc8fc\ud55c\ub2e4. \uadf8\ub294 \uadf8 \uba85\ub839\uc744 \ubc14\uafb8\uace0 \ub3cc\uc544\uc628\ub2e4. \uce7c\uc744 \ub4e4\uace0 \ub9de\uc11c\ub294 \uc7a5\uba74\ubfd0 \uc544\ub2c8\ub77c \uae00\uacfc \uba85\ub839, \ub2e4\ub978 \uc0ac\ub78c\uc744 \uc6c0\uc9c1\uc774\ub294 \uc81c\ub3c4\ub3c4 \uad8c\ub825\uc758 \ub3c4\uad6c\ub2e4. \uad81\uc815\uc758 \ubcf5\uc218\ub294 \ub450 \uc0ac\ub78c\uc758 \ub9c8\uc74c\uc18d\uc5d0\uc11c\ub9cc \uc9c4\ud589\ub418\ub294 \uc77c\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc624\ud544\ub9ac\uc544\ub294 \uc0ac\ub791\uacfc \uac00\uc871, \uad81\uc815\uc758 \uc694\uad6c \uc0ac\uc774\uc5d0 \ub193\uc778\ub2e4. \uc544\ubc84\uc9c0\uc758 \uc8fd\uc74c \ub4a4 \ud63c\ub780\uc5d0 \ube60\uc9c0\uace0 \ub05d\ub0b4 \ubb3c\uc5d0 \ube60\uc838 \uc8fd\ub294\ub2e4. \uadf8\ub140\uc758 \uc0b6\uc744 \ud584\ub9bf\uc758 \uc131\uaca9\uc744 \uc124\uba85\ud558\ub294 \ubd80\uc18d\ubb3c\ub85c\ub9cc \ubcf4\uba74 \uc791\ud488\uc758 \uc190\uc2e4\uc774 \uc881\uc544\uc9c4\ub2e4. \uc655\uc2e4\uc758 \uac08\ub4f1\uc740 \uadf8 \uc911\uc2ec\uc5d0 \uc11c\uc9c0 \uc54a\uc558\ub358 \uc0ac\ub78c\ub3c4 \ud30c\uad34\ud55c\ub2e4. \ubb34\ub364 \uc7a5\uba74\uc5d0\uc11c \ud584\ub9bf\uc740 \ud574\uace8\uc744 \ud1b5\ud574 \uc0b4\uc544 \uc788\ub358 \ud55c \uc0ac\ub78c\uc758 \uae30\uc5b5\uc744 \ub9c8\uc8fc\ud55c\ub2e4. \ub204\uad6c\ub098 \uc544\ub294 \uc8fd\uc74c\uc774\ub77c\ub294 \ub9d0\uc744 \uad6c\uccb4\uc801\uc778 \uc5bc\uad74\uacfc \uc5f0\uacb0\ud558\ub294 \uc21c\uac04\uc774\ub2e4. \uc0b6\uacfc \uc8fd\uc74c\uc5d0 \uad00\ud55c \uc720\uba85\ud55c \ub3c5\ubc31\ub3c4 \uc774\ucc98\ub7fc \uc2e4\uc81c \uc0c1\uc2e4\uc774 \uc774\uc5b4\uc9c0\ub294 \uc11c\uc0ac \uc548\uc5d0\uc11c \uc77d\uc5b4\uc57c \ubb34\uac8c\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \ub808\uc5b4\ud2f0\uc2a4\uc640 \ud074\ub85c\ub514\uc5b4\uc2a4\ub294 \ud584\ub9bf\uc744 \uc8fd\uc77c \uacc4\ud68d\uc744 \uc138\uc6b0\uace0 \uacb0\ud22c\ub97c \ub9c8\ub828\ud55c\ub2e4. \ub3c5\uc744 \ubc14\ub978 \uce7c\uacfc \ub3c5\uc774 \ub4e0 \uc220\uc774 \uc900\ube44\ub418\uc9c0\ub9cc \uacc4\ud68d\uc740 \ud55c \uc0ac\ub78c\uc5d0\uac8c\ub9cc \ud5a5\ud558\uc9c0 \uc54a\ub294\ub2e4. \uac70\ud2b8\ub8e8\ub4dc\uac00 \uc220\uc744 \ub9c8\uc2dc\uace0 \ud584\ub9bf\uacfc \ub808\uc5b4\ud2f0\uc2a4\ub3c4 \uce58\uba85\uc801\uc778 \uc0c1\ucc98\ub97c \uc785\ub294\ub2e4. \ud584\ub9bf\uc740 \ub9c8\uce68\ub0b4 \ud074\ub85c\ub514\uc5b4\uc2a4\ub97c \uc8fd\uc774\uc9c0\ub9cc \uc790\uc2e0\ub3c4 \uc0b4\uc544\ub0a8\uc9c0 \ubabb\ud55c\ub2e4. \ubcf5\uc218\uac00 \uc2e4\ud589\ub418\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc9c8\uc11c\uac00 \ud68c\ubcf5\ub418\ub294 \uacb0\ub9d0\uc740 \uc544\ub2c8\ub2e4. \ucc98\uc74c\uc758 \uc0b4\uc778\uc5d0\uc11c \uc2dc\uc791\ud55c \uc758\uc2ec\uacfc \ud589\ub3d9\uc774 \ub9ce\uc740 \uc8fd\uc74c\uc73c\ub85c \ubc88\uc84c\ub2e4. \uc655\uc88c\ub97c \ub458\ub7ec\uc2fc \uc815\uce58\uc801 \uacb0\uacfc\ub3c4 \ub0a8\ub294\ub2e4. \uc798\ubabb\ud55c \ud55c \uc0ac\ub78c\uc744 \uc5c6\uc560\uba74 \ubaa8\ub4e0 \uad00\uacc4\uac00 \uc6d0\ub798\ub300\ub85c \ub3cc\uc544\uac04\ub2e4\ub294 \uae30\ub300\ub294 \ubb34\ub108\uc9c4\ub2e4. \ud584\ub9bf\uc740 \ud638\ub808\uc774\uc1fc\uc5d0\uac8c \uc790\uc2e0\uc758 \uc774\uc57c\uae30\ub97c \ub0a8\uaca8 \ub2ec\ub77c\uace0 \ud55c\ub2e4. \ube44\uadf9\uc758 \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \ud589\ub3d9\uc758 \ubb38\uc81c\ubfd0 \uc544\ub2c8\ub77c \uae30\uc5b5\uacfc \uc11c\uc220\uc758 \ubb38\uc81c\uac00 \ub193\uc778\ub2e4. \ubb34\uc2a8 \uc77c\uc774 \uc788\uc5c8\ub294\uc9c0 \ub204\uac00 \uc5b4\ub5bb\uac8c \uc124\uba85\ud560 \uac83\uc778\uac00. \ub3c5\uc790\ub294 \uae34 \uc0ac\uac74\uc744 \ubcf8 \ub4a4 \uadf8 \uc774\uc57c\uae30\ub97c \uc804\ud558\ub294 \uc0ac\ub78c\uc758 \ucc45\uc784\ub3c4 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \u300e\ud584\ub9bf\u300f\uc758 \uc9c8\ubb38\uc740 \ub2e8\uc21c\ud788 \ud560 \uac83\uc778\uac00 \ub9d0 \uac83\uc778\uac00\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \ubb34\uc5c7\uc744 \uadfc\uac70\ub85c \ud310\ub2e8\ud560\uc9c0, \ud589\ub3d9\uc758 \uacb0\uacfc\ub97c \ub204\uac00 \uac10\ub2f9\ud560\uc9c0, \uc8fd\uc740 \ub4a4 \ubb34\uc5c7\uc774 \ub0a8\uc744\uc9c0\uac00 \ud568\uaed8 \uc788\ub2e4. \uadf8\ub798\uc11c \uc624\ub798\ub41c \uad81\uc815\uc758 \ubcf5\uc218\uadf9\uc740 \uc624\ub298\uc758 \ub3c5\uc790\uc5d0\uac8c\ub3c4 \ud310\ub2e8\uacfc \ucc45\uc784\uc5d0 \uad00\ud55c \ubd88\ud3b8\ud558\uace0 \ud48d\ubd80\ud55c \uc77d\uc744\uac70\ub9ac\uac00 \ub41c\ub2e4."}, {"id": "hokusai-fuji-thirty-six-changing-views", "title": "\ud638\ucfe0\uc0ac\uc774 \u2014 \uac19\uc740 \ud6c4\uc9c0\uc0b0\uc744 \uc11c\ub978\uc5ec\uc12f \ubc88 \ubc14\ub77c\ubcf8\ub2e4\uba74", "summary": "\ub2e4\ub9c8\uac15 \ub108\uba38\uc758 \ud6c4\uc9c0\uc0b0 \ud310\ud654\ub97c \ubcf4\uba70 \uac19\uc740 \uc0b0\uc774 \ub9e4\ubc88 \ub2e4\ub978 \uadf8\ub9bc\uc774 \ub418\ub294 \uc774\uc720\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/hokusai-fuji-thirty-six-changing-views/index.html", "image": "../media/hokusai-fuji-thirty-six-changing-views.jpg", "alt": "\ud638\ucfe0\uc0ac\uc774\uc758 \ub2e4\ub9c8\uac15 \ub108\uba38 \ud6c4\uc9c0\uc0b0 \ud310\ud654, \uc61b \ubbf8\uc220\uc11c\uc758 \ub3c4\ud310 49", "text": "\ud638\ucfe0\uc0ac\uc774 \u2014 \uac19\uc740 \ud6c4\uc9c0\uc0b0\uc744 \uc11c\ub978\uc5ec\uc12f \ubc88 \ubc14\ub77c\ubcf8\ub2e4\uba74 \u300e\ud6c4\uac00\ucfe0 \uc0bc\uc2ed\uc721\uacbd\u300f\uc5d0\uc11c \uc0b0\ubcf4\ub2e4 \uba3c\uc800 \ubcf4\uc774\ub294 \uc0ac\ub78c\uacfc \ud48d\uacbd \ub2e4\ub9c8\uac15 \ub108\uba38\uc758 \ud6c4\uc9c0\uc0b0 \ud310\ud654\ub97c \ubcf4\uba70 \uac19\uc740 \uc0b0\uc774 \ub9e4\ubc88 \ub2e4\ub978 \uadf8\ub9bc\uc774 \ub418\ub294 \uc774\uc720\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \ud6c4\uc9c0\uc0b0\uc744 \uadf8\ub838\ub2e4\uace0 \ud558\ub294\ub370 \uadf8\ub9bc\uc5d0\uc11c \uc0b0\uc740 \uc0dd\uac01\ubcf4\ub2e4 \uba40\ub9ac \uc788\ub2e4. \uba3c\uc800 \uac15\uacfc \uc0ac\ub78c, \uac00\uae4c\uc6b4 \ud48d\uacbd\uc774 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc0b0\uc744 \ud06c\uac8c \uadf8\ub9b4 \uc218\ub3c4 \uc788\uc5c8\uc744 \ud150\ub370 \ud654\uac00\ub294 \uadf8 \uc790\ub9ac\ub97c \ube44\uc6cc \ub450\uace0 \uc6b0\ub9ac\uac00 \uc55e\ucabd\uc744 \uc9c0\ub098 \uba3c \uacf3\uae4c\uc9c0 \ubc14\ub77c\ubcf4\uac8c \ud55c\ub2e4. \uac00\uc4f0\uc2dc\uce74 \ud638\ucfe0\uc0ac\uc774\uc758 \u300e\ud6c4\uac00\ucfe0 \uc0bc\uc2ed\uc721\uacbd\u300f\uc740 \uac19\uc740 \uc0b0\uc744 \uac70\ub4ed \ub2e4\ub8ec \ud310\ud654 \uc5f0\uc791\uc774\ub2e4. \uc81c\ubaa9\ub9cc \ub4e4\uc73c\uba74 \ube44\uc2b7\ud55c \uadf8\ub9bc\uc744 \uc5ec\ub7ec \uc7a5 \ub9cc\ub4e0 \uac83 \uac19\uc9c0\ub9cc, \uc2e4\uc81c\ub85c\ub294 \uac19\uc740 \ub300\uc0c1\uc774 \uc5bc\ub9c8\ub098 \ub2e4\ub978 \uc7a5\uba74\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \ubb36\uc74c\uc5d0 \uac00\uae5d\ub2e4. \uc5f0\uc791\uc5d0\uc11c\ub294 \uc0b0\uc774 \ud654\uba74\uc744 \ud06c\uac8c \ucc28\uc9c0\ud558\uae30\ub3c4 \ud558\uace0 \uba40\ub9ac \uc791\uac8c \ub193\uc774\uae30\ub3c4 \ud55c\ub2e4. \uc0ac\ub78c\ub4e4\uc758 \uc77c\uacfc \uae38, \ubb3c\uacfc \ub0a0\uc528\uac00 \uadf8 \uc55e\uc5d0 \ub4f1\uc7a5\ud55c\ub2e4. \uc0b0\uc758 \ud615\ud0dc\uac00 \uc775\uc219\ud574\uc9c8\uc218\ub85d \uc624\ud788\ub824 \uadf8 \uc8fc\ubcc0\uc5d0\uc11c \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc9c0\ub294\uc9c0 \ub354 \uc798 \ubcf4\uc778\ub2e4. \ud558\ub098\uc758 \uc0b0\uc774 \ud48d\uacbd\uc744 \ube44\uad50\ud558\ub294 \uae30\uc900\uc774 \ub418\ub294 \uc148\uc774\ub2e4. \uc5ec\ud589 \uc0ac\uc9c4\uc5d0\uc11c\ub3c4 \ube44\uc2b7\ud55c \uc77c\uc744 \uacaa\ub294\ub2e4. \uac19\uc740 \uac74\ubb3c\uc744 \ucc0d\uc5b4\ub3c4 \uc5b4\ub290 \uac70\ub9ac\uc5d0\uc11c \uc5b4\ub5a4 \uc2dc\uac04\uc5d0 \ubc14\ub77c\ubcf4\uc558\ub294\uc9c0\uc5d0 \ub530\ub77c \uc0ac\uc9c4\uc740 \ub2ec\ub77c\uc9c4\ub2e4. \ud638\ucfe0\uc0ac\uc774\uc758 \uadf8\ub9bc\uc744 \uadf8\uc800 \uacbd\uce58\ub97c \ubcf5\uc0ac\ud55c \uacb0\uacfc\ub85c \ubcf4\uae30\ubcf4\ub2e4, \ubb34\uc5c7\uc744 \uc55e\uc5d0 \ub193\uace0 \ubb34\uc5c7\uc744 \ub4a4\ub85c \ubcf4\ub0bc\uc9c0 \uace0\ub978 \ud654\uba74\uc73c\ub85c \ubcf4\uba74 \uc120\ud0dd\uc758 \uc7ac\ubbf8\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc791\ud488\uc740 \ub2e4\ub9c8\uac15 \ub108\uba38\uc758 \ud6c4\uc9c0\uc0b0\uc744 \ub2e4\ub8ec \ud310\ud654\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc624\ub798\ub41c \ubbf8\uc220\uc11c\uc5d0 \uc218\ub85d\ub41c \ub3c4\ud310\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \uba3c\uc800 \uc0b0\uc744 \ucc3e\uace0, \ub2e4\uc74c\uc5d0\ub294 \uc55e\ucabd \ud48d\uacbd\uc774 \ub208\uc744 \uc5b4\ub5a4 \ubc29\ud5a5\uc73c\ub85c \uc774\ub044\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uba3c \uc0b0\uc5d0 \ub2ff\uae30 \uc804\uc5d0 \uc9c0\ub098\uc57c \ud560 \uc7a5\uba74\uc774 \uc788\ub2e4. \uc791\ud488\uc744 \ubcfc \ub54c \uc55e\uacfc \ub4a4\uc758 \ud06c\uae30 \ucc28\uc774\ub3c4 \uc911\uc694\ud558\ub2e4. \uac00\uae4c\uc6b4 \uc694\uc18c\uac00 \ud06c\uac8c \ubcf4\uc774\uace0 \uc0b0\uc740 \uba40\ub9ac \ubb3c\ub7ec\ub09c\ub2e4. \uc2e4\uc81c \ud06c\uae30\uac00 \ud070 \uc0b0\uc774 \uadf8\ub9bc\uc5d0\uc11c\ub294 \uc791\uc544\uc9c8 \uc218 \uc788\ub2e4\ub294 \uc775\uc219\ud55c \uc6d0\ub9ac\ub97c \ud654\uac00\ub294 \ud654\uba74\uc758 \ub9ac\ub4ec\uc73c\ub85c \ubc14\uafbc\ub2e4. \uc791\uc740 \uc0b0\uc744 \ucc3e\uc558\uc744 \ub54c \uadf8\ub9bc \uc804\uccb4\uac00 \ud55c \ubc88 \ub354 \uc815\ub9ac\ub418\ub294 \ub290\ub08c\uc744 \ubc1b\uac8c \ub41c\ub2e4. \uc774 \uadf8\ub9bc\ub4e4\uc5d0\ub294 \ud6c4\uc9c0\uc0b0\ub9cc \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc0b0\uc774 \ubcf4\uc774\ub294 \uacf3\uc5d0\uc11c \uc0b4\uc544\uac00\ub294 \uc0ac\ub78c\uc758 \uc0dd\ud65c\ub3c4 \ub4e4\uc5b4\uac04\ub2e4. \uc790\uc5f0\uc744 \ubc14\ub77c\ubcf4\ub294 \uadf8\ub9bc\uacfc \uc77c\uc0c1\uc758 \ud48d\uacbd\uc774 \uc11c\ub85c \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\ub2e4. \ub300\uc0c1\uc744 \ud558\ub098 \uc815\ud574 \ub193\uc558\uae30\uc5d0 \uadf8 \ub300\uc0c1\uc744 \ub458\ub7ec\uc2fc \uc5ec\ub7ec \uc7a5\uba74\uc744 \ube44\uad50\ud560 \uc218 \uc788\uc5c8\ub2e4\uace0\ub3c4 \ubcfc \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \ud310\ud654\ub97c \ub2f9\uc2dc \uc77c\ubcf8 \uc0dd\ud65c\uc758 \uc815\ud655\ud55c \uc0ac\uc9c4\ucc98\ub7fc \uc77d\uc744 \uc218\ub294 \uc5c6\ub2e4. \ud654\uac00\ub294 \ubcf4\uace0 \uc2f6\uc740 \uad00\uacc4\ub97c \uac15\uc870\ud558\uac70\ub098 \ud654\uba74\uc744 \uc815\ub9ac\ud560 \uc218 \uc788\ub2e4. \uadf8\ub9bc \uc18d\uc5d0 \ubb34\uc5c7\uc774 \uc788\ub294\uc9c0 \uad00\ucc30\ud558\ub294 \uac83\uacfc \uadf8 \uc7a5\uba74\uc774 \ud604\uc2e4\uc5d0\uc11c \ub298 \ub611\uac19\uc558\ub2e4\uace0 \ub9d0\ud558\ub294 \uac83\uc740 \ub2e4\ub978 \ub2e8\uacc4\ub2e4. \uac10\uc0c1\uacfc \uc5ed\uc0ac \uc790\ub8cc \uc77d\uae30\ub97c \ud568\uaed8\ud558\ub418 \uc11e\uc9c0\ub294 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc774 \uc5f0\uc791\uc774 \uc18d\ud55c \ubaa9\ud310\ud654\uc5d0\uc11c\ub294 \ubc11\uadf8\ub9bc\uc744 \uadf8\ub9ac\uace0 \ud310\uc744 \uc0c8\uae30\uace0 \uc885\uc774\uc5d0 \ucc0d\ub294 \uacfc\uc815\uc774 \uc774\uc5b4\uc9c4\ub2e4. \uc624\ub298\ub0a0 \ud638\ucfe0\uc0ac\uc774\uc758 \uc774\ub984\uc73c\ub85c \uc791\ud488\uc744 \uae30\uc5b5\ud558\ub354\ub77c\ub3c4 \uc644\uc131\ub41c \uc778\uc1c4\ubb3c\uc5d0\ub294 \uc5ec\ub7ec \uc791\uc5c5\uc758 \uc219\ub828\uc774 \ub4e4\uc5b4\uac04\ub2e4. \uc885\uc774 \uc704\uc758 \uc120\uc774 \ub610\ub837\ud558\ub824\uba74 \uc55e\uc120 \ub2e8\uacc4\ub4e4\ub3c4 \ub9de\ubb3c\ub824\uc57c \ud55c\ub2e4. \uac19\uc740 \uadf8\ub9bc\uc774 \uc5ec\ub7ec \uc7a5 \uc874\uc7ac\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\ub3c4 \ud68c\ud654 \ud55c \uc810\uc744 \ubcfc \ub54c\uc640 \ub2e4\ub974\ub2e4. \uc778\uc1c4\uc640 \ubcf4\uc874\uc758 \uc0c1\ud0dc\uc5d0 \ub530\ub77c \uac1c\ubcc4 \ub3c4\ud310\uc758 \ubaa8\uc2b5\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc5ec\uae30 \uc2e4\uc740 \uc61b \ubbf8\uc220\uc11c\uc758 \uc7ac\ud604 \uc774\ubbf8\uc9c0\ub294 \ud654\uba74 \uad6c\uc131\uc744 \ubcf4\ub294 \uc790\ub8cc\ub85c \ud65c\uc6a9\ud558\uace0, \uc6d0\uc791\uc758 \uc0c9\uc744 \uc644\ubcbd\ud558\uac8c \ub300\uc2e0\ud55c\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\ub2e4. \uc5f0\uc791\uc740 \ud754\ud788 \uc11c\ub978\uc5ec\uc12f \uc7a5\uc774\ub77c\ub294 \uc81c\ubaa9\uc73c\ub85c \uae30\uc5b5\ub418\uc9c0\ub9cc \ucd94\uac00 \uc791\ud488\uc774 \ub354\ud574\uc9c4 \ubb36\uc74c\uc73c\ub85c\ub3c4 \uc54c\ub824\uc838 \uc788\ub2e4. \uc81c\ubaa9\uc774 \uc2e4\uc81c\ub85c \uc720\ud1b5\ub418\ub294 \ubaa8\ub4e0 \uad6c\uc131\uc758 \uc218\uc640 \uc5b8\uc81c\ub098 \uc815\ud655\ud788 \uc77c\uce58\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc791\ud488 \ud558\ub098\ub97c \ubcfc \ub54c\uc5d0\ub3c4 \uc5b4\ub290 \ubb36\uc74c\uacfc \ud310\ubcf8\uc744 \uc124\uba85\ud558\ub294\uc9c0 \ud655\uc778\ud560 \uc774\uc720\uac00 \uc788\ub2e4. \uc22b\uc790\ub97c \uba3c\uc800 \uc678\uc6b0\uba74 \uc5f0\uc791\uc758 \uc7ac\ubbf8\ub97c \ub193\uce60 \uc218 \uc788\ub2e4. \ub354 \uc911\uc694\ud55c \uac83\uc740 \uac19\uc740 \uc0b0\uc774 \uc5ec\ub7ec \uc2dc\uc120\uc758 \uc911\uc2ec\uc774 \ub41c\ub2e4\ub294 \ubc1c\uc0c1\uc774\ub2e4. \ud55c \uc7a5\uc744 \ubcf8 \ub4a4 \ub2e4\ub978 \ud55c \uc7a5\uc744 \ub098\ub780\ud788 \ub193\uace0 \uc0b0\uc758 \uc704\uce58\uc640 \uc55e\ucabd \ud48d\uacbd\uc744 \ube44\uad50\ud574 \ubcf4\uc790. \ub2ee\uc740 \ub300\uc0c1\uc744 \ucc3e\ub294 \uc77c\uc5d0\uc11c \ub2e4\ub978 \uad6c\uc131\uc744 \ubc1c\uacac\ud558\ub294 \uc77c\ub85c \uac10\uc0c1\uc774 \ubc14\ub010\ub2e4. \ud638\ucfe0\uc0ac\uc774\ub77c\ub294 \uc774\ub984\uc5d0\uc11c \uac70\ub300\ud55c \ud30c\ub3c4 \uadf8\ub9bc\uc744 \uba3c\uc800 \ub5a0\uc62c\ub9ac\ub294 \uc0ac\ub78c\ub3c4 \ub9ce\ub2e4. \ud558\uc9c0\ub9cc \uc720\uba85\ud55c \ud55c \uc7a5\uc774 \uc5f0\uc791 \uc804\uccb4\uc758 \ubd84\uc704\uae30\ub97c \ub300\uc2e0\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub9c8\uac15 \ub108\uba38\uc758 \uc0b0\uc744 \ubcf4\uba74 \uc2dc\uc120\uc740 \ub2e4\ub978 \uc18d\ub3c4\ub85c \uc6c0\uc9c1\uc778\ub2e4. \uac15\ub82c\ud55c \uc7a5\uba74\uc744 \uc54c\uace0 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc870\uc6a9\ud55c \ud48d\uacbd\uc744 \uc0c8\ub85c \ubcf4\ub294 \ub370 \ubc29\ud574\uac00 \ub418\uc9c0 \uc54a\ub3c4\ub85d \uc7a0\uc2dc \uae30\uc5b5\uc744 \ub0b4\ub824\ub193\uc544\ub3c4 \uc88b\ub2e4. \uc5f0\uc791\uc744 \ub9cc\ub4dc\ub294 \ubc1c\uc0c1\uc740 \ub3c5\uc790\uc5d0\uac8c\ub3c4 \ube44\uad50\ud560 \uc790\uc720\ub97c \uc900\ub2e4. \uc5b4\ub290 \uadf8\ub9bc\uc774 \ub354 \ud6cc\ub96d\ud55c\uc9c0 \uc21c\uc704\ub97c \uc815\ud558\uae30 \uc804\uc5d0 \ubb34\uc5c7\uc744 \ub2e4\ub974\uac8c \uc120\ud0dd\ud588\ub294\uc9c0 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uac00\uae4c\uc6b4 \ud48d\uacbd\uc774 \ub9ce\uc544\uc84c\ub294\uc9c0, \uba40\ub9ac \uc788\ub294 \uc0b0\uc774 \ub354 \ub450\ub4dc\ub7ec\uc9c0\ub294\uc9c0, \uc0ac\ub78c\uc774 \ud654\uba74\uc758 \uc911\uc2ec\uc778\uc9c0 \ubc30\uacbd\uc778\uc9c0. \uc815\ub2f5\uc744 \uc678\uc6b0\ub294 \ub300\uc2e0 \ud654\uac00\uc758 \uc120\ud0dd\uc744 \ud558\ub098\uc529 \ubc1c\uacac\ud558\ub294 \uac10\uc0c1\uc774 \ub41c\ub2e4. \ud638\ucfe0\uc0ac\uc774\ub294 \uae34 \uc0dd\uc560 \ub3d9\uc548 \uc5ec\ub7ec \uc791\uc5c5\uc744 \uc774\uc5b4 \uac04 \ud654\uac00\uc600\ub2e4. \uc61b \ubbf8\uc220\uc11c\uc5d0\ub294 \ub098\uc774\uac00 \ub4e0 \ub4a4\uc5d0\ub3c4 \ub354 \uc798 \uadf8\ub9ac\uace0 \uc2f6\ub2e4\ub294 \ub73b\uc744 \ud45c\ud604\ud55c \uadf8\uc758 \ub9d0\uc774 \uc18c\uac1c\ub418\uc5b4 \uc788\ub2e4. \uadf8 \uc804\uc5b8\uc744 \ubaa8\ub4e0 \uc0ac\ub78c\uc5d0\uac8c \uc801\uc6a9\ub418\ub294 \uc131\uacf5\uc758 \ube44\uacb0\ub85c \ubc14\uafc0 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uc774\ubbf8 \uc624\ub798 \uadf8\ub9b0 \uc0ac\ub78c\ub3c4 \uad00\ucc30\uc774 \ub05d\ub0ac\ub2e4\uace0 \uc5ec\uae30\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc810\uc740 \ub0a8\ub294\ub2e4. \uc774 \uadf8\ub9bc \uc55e\uc5d0\uc11c \uc6b0\ub9ac\ub3c4 \ube44\uc2b7\ud55c \uc791\uc740 \uc5f0\uc2b5\uc744 \ud560 \uc218 \uc788\ub2e4. \ud6c4\uc9c0\uc0b0\uc744 \ucc3e\uace0, \uadf8 \uc0b0\uc744 \uc7a0\uc2dc \uc78a\uc740 \ucc44 \uc55e\ucabd\uc744 \ubcf4\uace0, \ub2e4\uc2dc \uc0b0\uc73c\ub85c \ub3cc\uc544\uc624\ub294 \uac83\uc774\ub2e4. \uadf8\ub9bc\uc774 \ubc14\ub010 \uac83\uc740 \uc544\ub2cc\ub370 \ubcf4\ub294 \uc21c\uc11c\uac00 \ubc14\ub00c\uba74 \ud48d\uacbd\uc774 \uc0c8\ub85c\uc6cc\uc9c4\ub2e4. \uac19\uc740 \uc0b0\uc744 \uac70\ub4ed \uadf8\ub9b4 \ub9cc\ud55c \uc774\uc720\uac00 \uc870\uae08 \uc774\ud574\ub418\uae30 \uc2dc\uc791\ud55c\ub2e4. \uc774\ub54c \uc791\uac00\uc758 \ub9c8\uc74c\uc744 \ubaa8\ub450 \uc54c\uc544\ub0c8\ub2e4\uace0 \ub9d0\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud654\uba74\uc5d0\uc11c \uc2e4\uc81c\ub85c \ubcf4\uc774\ub294 \uc120\ud0dd\uc744 \uc0b4\ud53c\uace0, \uadf8\uac83\uc774 \ub098\uc5d0\uac8c \uc5b4\ub5a4 \uc778\uc0c1\uc744 \uc8fc\ub294\uc9c0 \uad6c\ubd84\ud574 \ub9d0\ud558\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \ucda9\ubd84\ud788 \uae4a\uc740 \uac10\uc0c1\uc774 \ub41c\ub2e4."}, {"id": "inkstone-water-dropper", "title": "\ubcbc\ub8e8\ud568 \uc18d \ud574\ud0dc\uc758 \uc785\uc5d0\ub294 \uc791\uc740 \uad6c\uba4d\uc774 \uc788\ub2e4", "summary": "\uac80\uc740 \uce60\ud568\uc758 \ub69c\uaed1\uc5d0\ub294 \ubd80\ucc44\uac00, \uc548\ucabd\uc5d0\ub294 \uc791\uc740 \ud574\ud0dc\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uc7a5\uc2dd\uacfc \uc4f0\uc784\uc774 \ud55c \uc0c1\uc790\uc5d0\uc11c \ub9cc\ub0a9\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/inkstone-water-dropper/index.html", "image": "../media/inkstone-water-dropper.jpg", "alt": "\ub69c\uaed1\uc744 \uc5f4\uc5b4 \ubcbc\ub8e8\uc640 \uc791\uc740 \ud574\ud0dc \ubaa8\uc591 \uc5f0\uc801\uc744 \ud568\uaed8 \ubcf4\uc5ec \uc8fc\ub294 \ub098\uc804\uce60\uae30\ubd80\ucc44\ubb34\ub2ac\uc5f0\uac11 \uc0ac\uc9c4", "text": "\ubcbc\ub8e8\ud568 \uc18d \ud574\ud0dc\uc758 \uc785\uc5d0\ub294 \uc791\uc740 \uad6c\uba4d\uc774 \uc788\ub2e4 \uae00\uc4f0\uae30 \ub3c4\uad6c\ub97c \ub2f4\uc740 \uc0c1\uc790\uc5d0\uc11c \ub9cc\ub098\ub294 \ub73b\ubc16\uc758 \ub3d9\ubb3c \uac80\uc740 \uce60\ud568\uc758 \ub69c\uaed1\uc5d0\ub294 \ubd80\ucc44\uac00, \uc548\ucabd\uc5d0\ub294 \uc791\uc740 \ud574\ud0dc\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uc7a5\uc2dd\uacfc \uc4f0\uc784\uc774 \ud55c \uc0c1\uc790\uc5d0\uc11c \ub9cc\ub0a9\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \uac80\uc740 \uce60\uc744 \ud55c \uc0c1\uc790\uc5d0 \ubc18\uc9dd\uc774\ub294 \ubd80\ucc44 \ubb34\ub2ac\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \uac89\ubaa8\uc2b5\ub9cc \ubcf4\uba74 \uc7a5\uc2dd\ud488\uc744 \ub2f4\uc740 \ud568\uc77c \uac83 \uac19\ub2e4. \uadf8\ub7f0\ub370 \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc18c\uac1c\ud558\ub294 \uc774 \ubb3c\uac74\uc758 \uc774\ub984\uc740 \u300c\ub098\uc804\uce60\uae30\ubd80\ucc44\ubb34\ub2ac\uc5f0\uac11\u300d\uc774\ub2e4. \ubcbc\ub8e8\uc640 \uc5f0\uc801\uc744 \ud568\uaed8 \ubcf4\uad00\ud558\ub294 \uc0c1\uc790\ub2e4. \u2018\uc5f0\uc801\u2019\uc774\ub77c\ub294 \ub0af\uc120 \ub9d0\uc740 \uc7a0\uae50 \ub4a4\ub85c \ub450\uc5b4\ub3c4 \uc88b\ub2e4. \uc774 \uc0c1\uc790 \uc548\uc5d0\ub294 \uc791\uc740 \ud574\ud0dc \ubaa8\uc591\uc758 \uae08\uc18d \ubb3c\uac74\uc774 \ub4e4\uc5b4 \uc788\uace0, \uadf8 \ub4f1\uc5d0 \ud558\ub098, \uc785\uc5d0 \ud558\ub098 \uad6c\uba4d\uc774 \uc788\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc5d0 \ub530\ub974\uba74 \ud568\uc758 \uc548\ucabd \uac00\uc6b4\ub370\ub294 \ubcbc\ub8e8 \ubaa8\uc591\uc5d0 \ub9de\uac8c \ud30c\uc5ec \uc788\ub2e4. \ubcbc\ub8e8\ub97c \uadf8 \uc790\ub9ac\uc5d0 \ub07c\uc6cc \ub123\uc5b4 \ubcf4\uad00\ud558\ub3c4\ub85d \ud55c \uac83\uc774\ub2e4. \uc5f0\uc801\uc744 \uc704\ud55c \ud648\ub3c4 \uc788\uc5b4 \uc27d\uac8c \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub3c4\ub85d \ud588\ub2e4. \uadf8\ub0e5 \ub113\uc740 \uc0c1\uc790\uc5d0 \ub3c4\uad6c\ub97c \ub123\uc5b4 \ub454 \uac83\uacfc\ub294 \ub2e4\ub974\ub2e4. \uc548\uc5d0 \ub4e4\uc5b4\uac08 \ubb3c\uac74\uc758 \ubaa8\uc591\uc744 \uc0dd\uac01\ud574 \uc790\ub9ac\ub97c \ub9c8\ub828\ud588\ub2e4. \uc624\ub298\uc758 \uc548\uacbd\uc9d1\uc774\ub098 \ub3c4\uad6c \ubcf4\uad00\ud568\uc5d0\uc11c\ub3c4 \ub9cc\ub098\ub294 \uc775\uc219\ud55c \uc0dd\uac01\uc774\ub2e4. \ub69c\uaed1\uc774 \uae4a\ub2e4\ub294 \uc810\ub3c4 \ub208\uc5d0 \ub748\ub2e4. \ub69c\uaed1\uacfc \ubab8\uccb4\ub97c \ub36e\uc73c\uba74 \ubab8\uccb4\uc758 \ubc14\ub2e5 \ubd80\ubd84\ub9cc \ubcf4\uc774\ub294 \ud615\ud0dc\ub77c\uace0 \ud55c\ub2e4. \ub2eb\uc558\uc744 \ub54c\uc758 \ub2e8\uc815\ud55c \ubaa8\uc2b5\uacfc \uc5f4\uc5c8\uc744 \ub54c\uc758 \uc54c\ub9de\uc740 \uc790\ub9ac\uac00 \ud55c \ubb3c\uac74 \uc548\uc5d0 \uc788\ub2e4. \uc5f0\uc801\uc740 \ubcbc\ub8e8\uc5d0 \uc4f8 \ubb3c\uc744 \ub2f4\ub294 \ub3c4\uad6c\ub2e4. \uc774 \ud568\uc758 \uc5f0\uc801\uc740 \ud574\ud0dc \ubaa8\uc591\uc774\uba70, \ub4f1 \ubd80\ubd84\uc5d0 \ubb3c\uc744 \ub123\ub294 \uad6c\uba4d\uc774 \uc788\uace0 \uc785 \ubd80\ubd84\uc5d0\ub294 \ubb3c\uc774 \ub098\uc624\ub294 \uc791\uc740 \ub465\uadfc \uad6c\uba4d\uc774 \ub6ab\ub824 \uc788\ub2e4. \ub3d9\ubb3c\uc758 \uc5bc\uad74\uc744 \uc54c\uc544\ubcf8 \ub2e4\uc74c\uc5d0 \uad6c\uba4d\uc758 \uc704\uce58\ub97c \ubcf4\uba74 \uc4f0\uc784\ub3c4 \ud568\uaed8 \ub4dc\ub7ec\ub09c\ub2e4. \uc7a5\uc2dd\uc744 \uc704\ud574 \ub354\ud55c \uc785\uc774 \ubb3c\uc744 \ub0b4\ubcf4\ub0b4\ub294 \uc790\ub9ac\uc774\uae30\ub3c4 \ud558\ub2e4. \ubb3c\uac74\uc758 \uae30\ub2a5\uc774 \uc0dd\uae40\uc0c8 \uc548\uc73c\ub85c \ub4e4\uc5b4\uac00 \uc788\ub2e4. \uc0ac\uc9c4\uc73c\ub85c \uad6c\uba4d\uc774 \ubaa8\ub450 \ub610\ub837\ud558\uc9c0 \uc54a\ub354\ub77c\ub3c4 \ubc15\ubb3c\uad00 \uc124\uba85\uc744 \ub530\ub77c \uc704\uce58\ub97c \uc9d0\uc791\ud574 \ubcfc \uc218 \uc788\ub2e4. \ud574\ud0dc\uac00 \uc65c \uadf8 \uc0c1\uc790 \uc548\uc5d0 \uc788\ub294\uc9c0 \uc54c\uace0 \ub098\uba74 \uc791\uc740 \ub3d9\ubb3c\uc744 \ubcf4\ub294 \ub208\uc774 \uc870\uae08 \ub2ec\ub77c\uc9c4\ub2e4. \uba39\uacfc \ubcbc\ub8e8\ub97c \uc0ac\uc6a9\ud558\ub294 \uae00\uc4f0\uae30\uc5d0\ub294 \ubb3c\uc744 \ub9c8\ub828\ud558\uace0 \ub3c4\uad6c\ub97c \uc81c\uc790\ub9ac\uc5d0 \ub450\ub294 \uc77c\uc774 \ub530\ub77c\uc628\ub2e4. \uc644\uc131\ub41c \uae00\uc528\ub9cc \ubcf4\uc544\uc11c\ub294 \uc798 \ub4dc\ub7ec\ub098\uc9c0 \uc54a\ub294 \uc2dc\uac04\uc774\ub2e4. \ubcbc\ub8e8\ud568\uc740 \uadf8 \uc900\ube44\ub97c \ud55c \ubb3c\uac74 \uc548\uc5d0 \ubaa8\uc544 \ub193\ub294\ub2e4. \uc5b4\ub290 \ub3c4\uad6c\ub97c \uc5b4\ub514\uc5d0 \ub450\uace0 \ub2e4\uc2dc \uaebc\ub0bc\uc9c0 \uc0dd\uac01\ud55c \uad6c\uc870\uac00 \uc788\uc5b4\uc57c \uc0ac\uc6a9\ud558\ub294 \uc190\ub3c4 \ub2e4\uc74c \ud589\ub3d9\uc744 \ucc3e\uae30 \uc27d\ub2e4. \uc774 \ud568\uc758 \uc548\ucabd\uc5d0 \ub3c4\uad6c \ubaa8\uc591\uc5d0 \ub9de\ucd98 \ud648\uc774 \uc788\ub2e4\ub294 \uc124\uba85\uc740 \uadf8\ub798\uc11c \uc911\uc694\ud558\ub2e4. \ub123\uc744 \uc218 \uc788\ub294 \uacf5\uac04\uc744 \ud06c\uac8c \ub9cc\ub4e4\uae30\ub9cc \ud55c \uac83\uc774 \uc544\ub2c8\ub2e4. \ub4e4\uc5b4\uac08 \ubb3c\uac74\uc758 \uc724\uacfd\uc5d0 \ub9de\ucdb0 \uc790\ub9ac\ub97c \ub098\ub204\uc5c8\ub2e4. \uc624\ub298\uc758 \ub3c4\uad6c \uc0c1\uc790\uc640 \ube44\uad50\ud558\ub294 \uac83\uc740 \uc4f0\uc784\uc744 \uc774\ud574\ud558\ub294 \ube44\uc720\uc774\uba70, \ub2f9\uc2dc \uc0ac\uc6a9\uc790\uac00 \uac19\uc740 \ub9d0\uc744 \ud588\ub2e4\ub294 \uae30\ub85d\uc744 \ub73b\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubb3c\uac74\uc758 \ubc30\uce58\uac00 \uae00\uc4f0\uae30\uc758 \uc900\ube44\ub97c \ub3c4\uc654\ub2e4\ub294 \uc810\uc744 \ubcfc \uc218 \uc788\ub2e4. \ubb3c\uc740 \ub4f1 \ucabd\uc758 \uc785\uc218\uad6c\ub85c \ub4e4\uc5b4\uac00\uace0 \uc785 \ucabd\uc758 \uc791\uc740 \uad6c\uba4d\uc73c\ub85c \ub098\uc628\ub2e4. \ud558\ub098\uc758 \ud615\uc0c1\uc5d0\uc11c \ubb3c\uc744 \ucc44\uc6b0\ub294 \uc790\ub9ac\uc640 \ub0b4\ubcf4\ub0b4\ub294 \uc790\ub9ac\uac00 \ub098\ub25c\ub2e4. \uc870\uac01\uc744 \ubcf4\ub294 \ub208\uc5d0\uc11c \ub3c4\uad6c\ub97c \uc4f0\ub294 \ub208\uc73c\ub85c \ubc14\uafb8\uba74 \uac19\uc740 \ubab8\uc774 \ud1b5\ub85c\ub97c \uac00\uc9c4 \uc6a9\uae30\ub85c \ubcf4\uc778\ub2e4. \uc7a5\uc2dd\uacfc \uae30\ub2a5\uc774 \ubcc4\ub3c4\uc758 \ubd80\ud488\uc73c\ub85c\ub9cc \ub098\ub258\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub358 \uac83\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \uad6c\uba4d\uc758 \uc704\uce58\ub9cc\uc73c\ub85c \ub2f9\uc2dc \ubb3c\uc744 \ub530\ub974\ub294 \uc190\ub3d9\uc791\uacfc \uc0ac\uc6a9\ub7c9\uc744 \ubaa8\ub450 \uc54c \uc218\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc5f0\uc801\uc774\ub77c\ub294 \ub3c4\uad6c\uc758 \uc5ed\ud560\uacfc \ud655\uc778\ub41c \uad6c\uc870\ub97c \uc5f0\uacb0\ud55c\ub2e4. \ubb3c\uc744 \ubcf4\uad00\ud558\uace0 \uc870\uae08\uc529 \uc4f0\ub294 \uc77c\uc744 \ub3d9\ubb3c\uc758 \ubab8 \uc548\uc5d0 \ub2f4\uc558\ub2e4\ub294 \uc810\uc774 \ud765\ubbf8\ub86d\ub2e4. \uae30\ub2a5\uc744 \uc228\uacbc\ub2e4\uae30\ubcf4\ub2e4 \uae30\ub2a5\uc744 \uc990\uae38 \ub9cc\ud55c \ud615\uc0c1\uc73c\ub85c \ub9cc\ub4e0 \ubb3c\uac74\uc73c\ub85c \uc77d\uc5b4 \ubcfc \uc218 \uc788\ub2e4. \uae4a\uc740 \ub69c\uaed1\uc740 \ub2eb\uc740 \uc0c1\ud0dc\uc5d0\uc11c \ubab8\uccb4\uc758 \ub9ce\uc740 \ubd80\ubd84\uc744 \uac00\ub9b0\ub2e4. \ubc14\uae65\uc5d0\uc11c\ub294 \ud558\ub098\uc758 \ub2e8\uc815\ud55c \ud568\ucc98\ub7fc \ubcf4\uc774\uace0 \uc548\uc744 \uc5f4\uba74 \ubcbc\ub8e8\uc640 \uc5f0\uc801\uc758 \uad6c\uccb4\uc801\uc778 \uc790\ub9ac\uac00 \ub098\ud0c0\ub09c\ub2e4. \ubcf4\uad00\ud558\ub294 \uc2dc\uac04\uacfc \uc0ac\uc6a9\ud558\ub294 \uc2dc\uac04\uc774 \uac19\uc740 \ubaa8\uc2b5\uc744 \uc694\uad6c\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub69c\uaed1\uc774 \ub9cc\ub4e0 \uacbd\uacc4\uac00 \uadf8 \ub450 \uc7a5\uba74\uc744 \ub098\ub204\uc5b4 \uc900\ub2e4. \uc774\ub7f0 \ubb3c\uac74\uc744 \uc0ac\uc9c4 \ud55c \uc7a5\uc73c\ub85c \ubcfc \ub54c\uc5d0\ub294 \ud604\uc7ac \uc5f4\ub824 \uc788\ub294\uc9c0, \ubb34\uc5c7\uc774 \uaebc\ub0b4\uc838 \uc788\ub294\uc9c0\ubd80\ud130 \ud655\uc778\ud558\uba74 \uc88b\ub2e4. \uc804\uc2dc\ub97c \uc704\ud574 \ud3bc\uccd0 \ub193\uc740 \uc0c1\ud0dc\ub97c \uc5b8\uc81c\ub098 \uadf8 \ubaa8\uc2b5\uc73c\ub85c \uc0ac\uc6a9\ud588\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc218\ub0a9 \ub3c4\uad6c\ub294 \ub2eb\ud78c \uc678\ud615\uacfc \uc5f4\ub9b0 \ub0b4\ubd80\ub97c \ud568\uaed8 \ubcfc \ub54c \uc124\uacc4\uc758 \ub73b\uc774 \ub354 \uc798 \ubcf4\uc778\ub2e4. \uac89\uc758 \uc7a5\uc2dd\uacfc \uc548\ucabd\uc758 \ud648\uc774 \uc11c\ub85c \ub2e4\ub978 \uc77c\uc744 \ud558\uace0 \uc788\uc5c8\ub2e4. \ubc15\ubb3c\uad00\uc740 \ud568\uc758 \ubd80\ucc44 \ubaa8\uc591 \ub098\uc804\uacfc \uae08\uc0c9 \ub048 \uc7a5\uc2dd\ub3c4 \uc124\uba85\ud55c\ub2e4. \ubc14\uae65\uc758 \ud45c\uba74\uacfc \ub0b4\ubd80\uc758 \uc5f0\uc801\uc740 \uac01\uae30 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ubb3c\uac74\uc5d0 \ud45c\uc815\uc744 \ub354\ud55c\ub2e4. \ud558\ub098\ub294 \uba74\uc758 \ubb34\ub2ac\uc640 \ube5b\uc744 \ub9cc\ub4e4\uace0, \ub2e4\ub978 \ud558\ub098\ub294 \uc785\uccb4\uc801\uc778 \ubab8 \uc548\uc5d0 \ubb3c\uc744 \ub2f4\ub294\ub2e4. \ub2e8\uc21c\ud788 \ud654\ub824\ud55c \uc0c1\uc790\ub77c\ub294 \ub9d0\ubcf4\ub2e4 \uac01\uac01 \uc5b4\ub514\uc5d0 \ubb34\uc5c7\uc774 \ub193\uc600\ub294\uc9c0 \ubcf4\uba74 \ub354 \ub9ce\uc740 \uac83\uc774 \uc77d\ud78c\ub2e4. \ud574\ud0dc\ub77c\ub294 \uc774\ub984\uc744 \ub4e4\uc5c8\ub2e4\uace0 \ubaa8\ub4e0 \uc7a5\uc2dd\uc5d0 \uac19\uc740 \uae30\uc6d0\uc744 \ud655\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774 \ubb3c\uac74\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\ub294 \uc704\uce58\uc640 \uc4f0\uc784\uc744 \uba3c\uc800 \uc0b4\ud3b4\ubcf4\uba74 \ub41c\ub2e4. \uc88b\uc740 \uae00\uc528\uac00 \ub0a8\uae30 \uc804\uc758 \uc870\uc6a9\ud55c \uc900\ube44 \uc2dc\uac04\uc5d0\ub3c4 \uc0ac\ub78c\ub4e4\uc774 \uc0ac\uc6a9\ud558\ub294 \ubb3c\uac74\uc744 \uace0\ub974\uace0 \uafb8\ubbf8\ub294 \ucde8\ud5a5\uc774 \uc788\uc5c8\ub2e4. \uc791\uc740 \uc5f0\uc801\uc758 \uc785\uc740 \uadf8 \uc0dd\ud65c\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \ub73b\ubc16\uc758 \uc785\uad6c\ub2e4. \ud568\uc758 \ub69c\uaed1\uc5d0\ub294 \ubd80\ucc44\ub97c \ubcf8\ub72c \ubb34\ub2ac\uac00 \uc788\ub2e4. \ubd80\ucc44\uc5d0 \ub4e4\uc5b4\uac04 \ubb34\ub2ac\uc640 \ubd80\ucc57\uc0b4, \uad6c\uc2ac\uacfc \uace0\ub9ac\ub294 \ub098\uc804\uc73c\ub85c \ud45c\ud604\ud588\uace0 \ub048\uc740 \uae08\uc0c9 \uc548\ub8cc\ub85c \ub098\ud0c0\ub0c8\ub2e4\uace0 \ud55c\ub2e4. \ub098\uc804\uc740 \ube5b\uc744 \ubc1b\uc73c\uba74 \ubc18\uc9dd\uc774\ub294 \uc7ac\ub8cc\ub2e4. \uc0c1\uc790\uc758 \uae30\ub2a5\ub9cc \uc0dd\uac01\ud558\uba74 \uc5c6\uc5b4\ub3c4 \ub420 \uac83 \uac19\uc740 \ubd80\ubd84\uc774\uc9c0\ub9cc, \uadf8 \ub355\ubd84\uc5d0 \ub2eb\ud78c \ud568\uc5d0\ub3c4 \uc624\ub798 \ubc14\ub77c\ubcfc \uc790\ub9ac\uac00 \uc0dd\uae34\ub2e4. \ub2e4\uc74c\uc5d0 \uc61b \ubb38\ubc29\uad6c\ub97c \ub9cc\ub098\uba74 \uae00\uc528\ub97c \uc4f0\ub294 \ub3c4\uad6c\ub77c\ub294 \uc124\uba85\ub9cc \uc77d\uace0 \uc9c0\ub098\uce58\uc9c0 \uc54a\uc544\ub3c4 \uc88b\uaca0\ub2e4. \ub69c\uaed1\uc758 \ubd80\ucc44\uc5d0\uc11c \uc548\ucabd\uc758 \uc791\uc740 \ud574\ud0dc\uae4c\uc9c0, \uc4f0\ub294 \uc0ac\ub78c\uc758 \uc190\uae38\uc744 \uae30\ub2e4\ub9ac\ub358 \ubb3c\uac74\uc5d0\ub294 \uae30\ub2a5\uacfc \uad6c\uacbd\uac70\ub9ac\uac00 \ub098\ub780\ud788 \ub4e4\uc5b4 \uc788\ub2e4."}, {"id": "ise-shrine-rebuilding-and-inherited-craft", "title": "\uc774\uc138 \uc2e0\uad81 \u2014 \uc0c8\ub85c \uc9c0\uc740 \uac74\ubb3c\uc5d0 \uc624\ub798\ub41c \uc2dc\uac04\uc774 \ub0a8\ub294 \ubc95", "summary": "\uc8fc\uae30\uc801 \uc7ac\uac74\uacfc \uc7a5\uc778\uc758 \uc804\uc2b9, \uc21c\ub840 \uae30\ub85d\uc744 \ud1b5\ud574 \uc624\ub798\ub41c \uc804\ud1b5\uc774 \uc774\uc5b4\uc9c0\ub294 \ubc29\uc2dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uac74\ucd95", "categories": ["arts"], "url": "stories/ise-shrine-rebuilding-and-inherited-craft/index.html", "image": "../media/ise-shrine-rebuilding-and-inherited-craft.png", "alt": "\uc0bc\ub098\ubb34 \uc232\uc758 \uc18c\ubc15\ud55c \ubaa9\uc870 \uc2e0\uc0ac\ub97c \ub5a0\uc62c\ub9ac\ub294 \uc774\uc138 \uc2e0\uad81 \uad00\ub828 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uc774\uc138 \uc2e0\uad81 \u2014 \uc0c8\ub85c \uc9c0\uc740 \uac74\ubb3c\uc5d0 \uc624\ub798\ub41c \uc2dc\uac04\uc774 \ub0a8\ub294 \ubc95 \uc2e0\uad81\uc740 \ud558\ub098\uc758 \uac74\ubb3c\ubcf4\ub2e4 \ub113\ub2e4\uc5d0\uc11c \uc2dc\uc791\ud558\ub294 \uc5ed\uc0ac\uc640 \uc791\ud488 \uc77d\uae30 \uc8fc\uae30\uc801 \uc7ac\uac74\uacfc \uc7a5\uc778\uc758 \uc804\uc2b9, \uc21c\ub840 \uae30\ub85d\uc744 \ud1b5\ud574 \uc624\ub798\ub41c \uc804\ud1b5\uc774 \uc774\uc5b4\uc9c0\ub294 \ubc29\uc2dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uac74\ucd95 \ubb38\ud654\uc640 \uc608\uc220 \uc624\ub798\ub41c \uac74\ucd95\uc774\ub77c\uba74 \ucc98\uc74c\uc758 \uc7ac\ub8cc\uac00 \ub9ce\uc774 \ub0a8\uc544 \uc788\uc744\uc218\ub85d \uac00\uce58 \uc788\ub2e4\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \uc77c\ubcf8\uc758 \uc774\uc138 \uc2e0\uad81\uc740 \ub2e4\ub978 \uc9c8\ubb38\uc744 \ub358\uc9c4\ub2e4. \uc77c\uc815\ud55c \uc8fc\uae30\uc5d0 \uac74\ubb3c\uc744 \uc0c8\ub85c \uc9d3\ub294 \uc804\ud1b5 \uc18d\uc5d0\uc11c, \ubb34\uc5c7\uc774 \uc774\uc5b4\uc9c0\uba74 \uac19\uc740 \uc131\uc18c\ub77c\uace0 \ud560 \uc218 \uc788\uc744\uae4c. \uc774\uacf3\uc758 \uc5ed\uc0ac\ub294 \ub098\ubb34\uc758 \ub098\uc774\uc640 \uc804\ud1b5\uc758 \ub098\uc774\uac00 \ubc18\ub4dc\uc2dc \uac19\uc9c0 \uc54a\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc774\uc138 \uc2e0\uad81\uc774\ub77c\ub294 \uc774\ub984\uc740 \ud55c \ucc44\uc758 \uc804\uac01\ub9cc\uc744 \uac00\ub9ac\ud0a4\uc9c0 \uc54a\ub294\ub2e4. \ub0b4\uad81\uacfc \uc678\uad81\uc744 \ube44\ub86f\ud55c \uc5ec\ub7ec \uc81c\uc758 \uacf5\uac04\uacfc \uc232, \uae38\uc774 \ud568\uaed8 \uad00\uacc4\ub97c \uc774\ub8ec\ub2e4. \ub0b4\uad81\uc740 \uc544\ub9c8\ud14c\ub77c\uc2a4\uc640 \uc5f0\uacb0\ub418\ub294 \uc131\uc18c\ub2e4. \uc2e0\ud654\uc640 \uc81c\uc758\uc758 \uc758\ubbf8\ub97c \uac00\uc9c4 \uc7a5\uc18c\ub97c \ub2e8\uc21c\ud55c \uc61b \ubaa9\uc870\uac74\ucd95 \uc804\uc2dc\uc7a5\uc73c\ub85c \ubcf4\ub294 \ub370\uc5d0\ub294 \ud55c\uacc4\uac00 \uc788\ub2e4. \ubc29\ubb38\uac1d\uc774 \uac78\uc5b4 \ub4e4\uc5b4\uac00\ub294 \uae38\uacfc \ubb3c, \uc232\ub3c4 \uacbd\ud5d8\uc758 \uc77c\ubd80\ub2e4. \uac74\ubb3c \uc815\uba74\uc758 \uc0ac\uc9c4 \ud55c \uc7a5\uc740 \uc774\ub7f0 \uc811\uadfc \uacfc\uc815\uc744 \ucda9\ubd84\ud788 \uc804\ub2ec\ud558\uc9c0 \ubabb\ud55c\ub2e4. \uc5b4\ub514\uae4c\uc9c0 \uac08 \uc218 \uc788\uace0 \uc5b4\ub5a4 \uacf3\uc740 \uba40\ub9ac\uc11c \ubc14\ub77c\ubcf4\uac8c \ub418\ub294\uc9c0\uc5d0 \ub530\ub77c, \uacf5\uac04\uc744 \ubc1b\uc544\ub4e4\uc774\ub294 \ubc29\uc2dd\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc2dd\ub144\ucc9c\uad81\uc740 \uc815\ud574\uc9c4 \uc8fc\uae30\uc5d0 \uac74\ubb3c\uc744 \uc0c8\ub85c \ub9c8\ub828\ud558\uace0 \uc2e0\uc131\ud55c \ub300\uc0c1\uc744 \uc62e\uae30\ub294 \uc804\ud1b5\uc73c\ub85c \uc54c\ub824\uc838 \uc788\ub2e4. \uc774\uc138\uc5d0\uc11c\ub294 \ud754\ud788 \uc2a4\ubb34 \ud574\ub77c\ub294 \uc8fc\uae30\uac00 \ud575\uc2ec\uc73c\ub85c \uc124\uba85\ub41c\ub2e4. \ub2e4\ub9cc \uc624\ub79c \uc5ed\uc0ac \ub0b4\ub0b4 \uc5b4\ub5a4 \uc911\ub2e8\ub3c4 \uc5c6\uc5c8\ub2e4\uace0 \ub9d0\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc804\ud1b5\uc5d0\ub3c4 \uc804\uc7c1\uacfc \uacbd\uc81c\uc801 \uc870\uac74\uc774 \uc601\ud5a5\uc744 \uc8fc\uc5c8\ub2e4. \uc774 \uc7ac\uac74\uc744 \ub0a1\uc740 \uc9d1\uc744 \uc0c8\uc9d1\uc73c\ub85c \ubc14\uafb8\ub294 \uc2e4\uc6a9\uc801 \uc218\uc120\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uba74 \uc81c\uc758\uc758 \uc758\ubbf8\ub97c \ub193\uce5c\ub2e4. \uc2dc\uac04\uc5d0 \ub9de\ucd94\uc5b4 \uc900\ube44\ud558\uace0 \uc62e\uae30\ub294 \ud589\uc704 \uc790\uccb4\uac00 \uc804\ud1b5\uc758 \uc77c\ubd80\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uc0c8 \uac74\ubb3c\uc774\ub77c\ub294 \uacb0\uacfc\ubfd0 \uc544\ub2c8\ub77c \uadf8 \uacb0\uacfc\uc5d0 \uc774\ub974\ub294 \uc808\ucc28\ub97c \ud568\uaed8 \uc774\uc5b4 \uac04\ub2e4\ub294 \uc810\uc774\ub2e4. \ub098\ubb34\uc640 \uc9c0\ubd95, \uc9c0\ubd95 \uc704\ub85c \ubed7\ub294 \ubd80\uc7ac\ub294 \uac15\ud55c \uc778\uc0c1\uc744 \uc900\ub2e4. \ud654\ub824\ud55c \ucc44\uc0c9\uc774\ub098 \ubcf5\uc7a1\ud55c \uc7a5\uc2dd\uc744 \uc911\uc2ec\uc73c\ub85c \uac10\uc0c1\ud558\ub294 \uad81\uc804\uacfc\ub294 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uad6c\uc870\uc640 \uc7ac\ub8cc\ub97c \ubcf4\uac8c \ud55c\ub2e4. \uac89\ubaa8\uc2b5\uc774 \uac04\uacb0\ud558\ub2e4\uace0 \uc81c\uc791 \uae30\uc220\ub3c4 \ub2e8\uc21c\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ubaa9\uc7ac\ub97c \uace0\ub974\uace0 \ub2e4\ub4ec\uace0 \ub9de\ucd94\ub294 \uc77c\uc5d0\ub294 \ucd95\uc801\ub41c \ud310\ub2e8\uc774 \ud544\uc694\ud558\ub2e4. \uc644\uc131\ub41c \uac74\ubb3c\uc744 \ubcfc \ub54c \uc798 \ub4dc\ub7ec\ub098\uc9c0 \uc54a\ub294 \uc811\ud569\uacfc \ube44\ub840, \uc21c\uc11c\ub97c \uc774\ud574\ud574\uc57c \ud55c\ub2e4. \ub2e8\uc21c\ud574 \ubcf4\uc774\ub294 \ud615\ud0dc\ub97c \uc77c\uc815\ud55c \uc218\uc900\uc73c\ub85c \ub2e4\uc2dc \ub9cc\ub4dc\ub294 \uc77c\uc740 \ub300\ucda9 \ube44\uc2b7\ud558\uac8c \ubaa8\ubc29\ud558\ub294 \uac83\uacfc \ub2e4\ub974\ub2e4. \uac74\ucd95\uc774 \uc218\ubc31 \ub144 \ub3d9\uc548 \uc11c \uc788\uae30\ub9cc \ud558\uba74 \ud2b9\uc815\ud55c \ud070 \uacf5\uc815\uc744 \uacbd\ud5d8\ud558\ub294 \uc7a5\uc778\uc740 \ub4dc\ubb3c \uc218 \uc788\ub2e4. \uc8fc\uae30\uc801 \uc7ac\uac74\uc740 \uc5ec\ub7ec \uc138\ub300\uac00 \uc2e4\uc81c \uc791\uc5c5\uc744 \ud568\uaed8 \ud560 \uae30\ud68c\ub97c \ub9cc\ub4e0\ub2e4. \uc774\uc804\uc5d0 \ubc30\uc6b4 \uc0ac\ub78c\uc774 \ub2e4\uc74c \uc791\uc5c5\uc5d0\uc11c \uacbd\ud5d8\uc744 \uc804\ud558\ub294 \uad00\uacc4\uac00 \uc0dd\uae30\ub294 \uac83\uc774\ub2e4. \uae30\uc220\uc740 \ub3c4\uba74\uacfc \uae00\uc5d0 \ubaa8\ub450 \ub2f4\uae30\uc9c0 \uc54a\ub294\ub2e4. \uc7ac\ub8cc\uc758 \uc0c1\ud0dc\ub97c \ud310\ub2e8\ud558\uace0 \uc190\uc73c\ub85c \ud798\uc744 \uc870\uc808\ud558\ub294 \ub2a5\ub825\ub3c4 \uc788\ub2e4. \uc774\uc138\uc758 \uc7ac\uac74\uc740 \uac74\ubb3c\uc744 \ubcf4\uc874\ud558\ub294 \ubb38\uc81c\uc640 \uc77c\uc744 \ud560 \uc904 \uc544\ub294 \uc0ac\ub78c\uc744 \uc774\uc5b4 \uac00\ub294 \ubb38\uc81c\uac00 \uc11c\ub85c \uc5f0\uacb0\ub41c\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ubc18\ubcf5\uc740 \ub9e4\ubc88 \ub611\uac19\uc740 \uc2dc\uac04\uc744 \ubcf5\uc0ac\ud558\ub294 \uc77c\uacfc \ub2e4\ub974\ub2e4. \ucc98\uc74c \uc791\uc5c5\uc5d0 \ucc38\uc5ec\ud558\ub294 \uc0ac\ub78c\uc740 \ubc30\uc6b0\uace0, \uc5ec\ub7ec \uacf5\uc815\uc744 \uacaa\uc740 \uc0ac\ub78c\uc740 \ub2e4\uc74c \uc138\ub300\ub97c \uc9c0\ub3c4\ud55c\ub2e4. \uac19\uc740 \ud615\ud0dc\ub97c \ubaa9\ud45c\ub85c \ud558\ub294 \uc791\uc5c5 \uc548\uc5d0\uc11c\ub3c4 \ucc38\uc5ec\uc790\uc758 \uacbd\ud5d8\uc740 \ub2ec\ub77c\uc9c4\ub2e4. \uc804\ud1b5\uc774 \uac1c\uc778\uc758 \uc0b6\ubcf4\ub2e4 \uae38\uac8c \uc774\uc5b4\uc9c0\ub294 \uacfc\uc815\uc740 \uc774\ub7f0 \uc5ed\ud560\uc758 \ubcc0\ud654 \uc18d\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c4\ub2e4. \ubc29\ubb38\ud560 \ub54c\uc5d0\ub294 \uc885\uad50 \uc2dc\uc124\uc758 \uc811\uadfc \ubc94\uc704\uc640 \uc548\ub0b4\ub97c \uc874\uc911\ud558\ub294 \ud0dc\ub3c4\ub3c4 \uc911\uc694\ud558\ub2e4. \uac00\uae4c\uc774 \ub4e4\uc5b4\uac00 \ubaa8\ub4e0 \ub0b4\ubd80\ub97c \ubcf4\uc9c0 \uc54a\uc544\ub3c4 \uae38\uacfc \uc232, \uc678\ubd80\uc758 \uad6c\uc870\ub97c \ud1b5\ud574 \uc7a5\uc18c\ub97c \uacbd\ud5d8\ud560 \uc218 \uc788\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294 \ubd80\ubd84\uc744 \uc0c1\uc0c1\ud55c \uc0bd\ud654\ub294 \uc2e4\uc81c \ub0b4\ubd80\uc758 \uae30\ub85d \uc0ac\uc9c4\uacfc \uad6c\ubd84\ud574\uc11c \uc77d\uc5b4\uc57c \ud55c\ub2e4. \ub77c\ud504\uce74\ub514\uc624 \ud5cc\uc758 1904\ub144 \uae30\ub85d\uc5d0\ub294 \uc7ac\uac74 \ub54c \ub098\uc628 \ubaa9\uc7ac\uc640 \uac00\uc815\uc5d0\uc11c \ubaa8\uc2dc\ub294 \uc2e0\uc131\ud55c \ud45c\uc9c0\uc758 \uad00\uacc4\uac00 \ub4f1\uc7a5\ud55c\ub2e4. \uc774\ub294 \uc2e0\uad81\uc758 \uc2dc\uac04\uc774 \uacbd\ub0b4 \uc548\uc5d0\uc11c\ub9cc \ub05d\ub098\uc9c0 \uc54a\uace0 \uc0ac\ub78c\ub4e4\uc758 \uc9d1\uacfc \uc774\uc5b4\uc84c\uc74c\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc624\ub798\ub41c \uc99d\uc5b8\uc774\ub2e4. \ub2f9\uc2dc \uad00\ucc30\uc744 \uc624\ub298 \ubaa8\ub4e0 \uac00\uc815\uc758 \uc0dd\ud65c\ub85c \uc77c\ubc18\ud654\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc911\uc2ec \uc131\uc18c\uc640 \uba40\ub9ac \uc788\ub294 \uc0dd\ud65c \uacf5\uac04 \uc0ac\uc774\uc5d0\ub294 \ubb3c\uac74\uacfc \uc0ac\ub78c\uc758 \uc774\ub3d9\uc774 \uc788\uc5c8\ub2e4. \uac74\ubb3c\uc744 \uc0c8\ub85c \uc9d3\uace0 \ub0a8\ub294 \uc7ac\ub8cc\ub3c4 \uc758\ubbf8 \uc5c6\ub294 \ud3d0\uae30\ubb3c\ub85c\ub9cc \uc774\ud574\ub418\uc9c0 \uc54a\uc558\ub2e4. \uc7ac\ub8cc\uac00 \uc4f0\uc774\ub294 \uc790\ub9ac\uc640 \uc885\uad50\uc801 \uc758\ubbf8\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \ud765\ubbf8\ub86d\ub2e4. \ud5cc\uc740 \ub9c8\uc744\uc5d0\uc11c \ub300\ud45c\ub97c \ubcf4\ub0b4\uac70\ub098 \ube44\uc6a9\uc744 \ubaa8\uc544 \uc21c\ub840\ub97c \uc900\ube44\ud558\ub294 \ubaa8\uc2b5\ub3c4 \uae30\ub85d\ud588\ub2e4. \uc774\ub7f0 \uae30\ub85d\uc740 \uc21c\ub840\uac00 \uc5b8\uc81c\ub098 \uac1c\uc778 \ud55c \uc0ac\ub78c\uc758 \uc790\ubc1c\uc801\uc778 \uc5ec\ud589\ub9cc\uc740 \uc544\ub2c8\uc5c8\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uae38\uc744 \ub5a0\ub098\ub294 \uc0ac\ub78c \ub4a4\uc5d0 \uacf5\ub3d9\uccb4\uc758 \ub3c8\uacfc \uae30\ub300\uac00 \ub193\uc77c \uc218 \uc788\uc5c8\ub2e4. \ub2e4\ub9cc \uadf8\uc758 \uae00\uc5d0\ub294 \ub2f9\uc2dc\uc758 \uc81c\ub3c4\uc640 \uc77c\ubcf8 \uc0ac\ud68c\ub97c \ub113\uac8c \uc77c\ubc18\ud654\ud558\ub294 \uc2dc\uc120\ub3c4 \uc11e\uc5ec \uc788\ub2e4. \ud55c \uc2dc\ub300\uc758 \uc678\uad6d\uc778 \uae30\ub85d\uc744 \uc77c\ubcf8\uc778 \uc804\uccb4\uc758 \ubcc0\ud558\uc9c0 \uc54a\ub294 \uc2e0\uc559\uc73c\ub85c \uc77d\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uad6c\uccb4\uc801\uc778 \uad00\ucc30\uc740 \ucc38\uace0\ud558\ub418 \uadf8\uac00 \ubcf4\uc9c0 \ubabb\ud55c \ucc28\uc774\uc640 \ubcc0\ud654\ub3c4 \ub0a8\uaca8 \ub450\uc5b4\uc57c \ud55c\ub2e4. \uc774\uc138\ub97c \uc774\ud574\ud560 \ub54c\uc5d0\ub294 \uc774 \ubaa9\uc7ac\uac00 \uc5bc\ub9c8\ub098 \uc624\ub798\ub418\uc5c8\ub294\uac00\uc640 \uc774 \uc77c\uc744 \uc5bc\ub9c8\ub098 \uc624\ub798 \uc774\uc5b4 \uc654\ub294\uac00\ub97c \ub098\ub204\uc5b4 \ubb3c\uc5b4 \ubcf4\uc790. \ub450 \uc9c8\ubb38\uc740 \ubaa8\ub450 \uc911\uc694\ud558\uc9c0\ub9cc \uac19\uc740 \ub2f5\uc744 \uc694\uad6c\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc624\ub798\ub41c \ubb3c\uc9c8\uc744 \uc9c0\ud0a4\ub294 \ubcf4\uc874\uacfc \uae30\uc220\uacfc \uc808\ucc28\ub97c \ub418\ud480\uc774\ud558\ub294 \uc804\uc2b9\uc740 \ub2e4\ub978 \uac00\uce58\ub97c \uac00\uc9c8 \uc218 \uc788\ub2e4. \uc0c8\ub85c \uc9c0\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc5ed\uc0ac\uac00 \uc0ac\ub77c\uc9c0\ub294 \uac83\ub3c4, \uac19\uc740 \ud615\uc2dd\uc744 \ubc18\ubcf5\ud55c\ub2e4\ub294 \uc774\uc720\ub85c \uc2dc\uac04\uc774 \uba48\ucd94\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uc900\ube44\uc5d0 \ucc38\uc5ec\ud558\ub294 \uc0ac\ub78c\uacfc \uc7ac\ub8cc\ub97c \uc5bb\ub294 \uc870\uac74\uc740 \uc2dc\ub300\ub9c8\ub2e4 \ub2ec\ub77c\uc9c4\ub2e4. \uc720\uc9c0\uc640 \uac31\uc2e0\uc744 \ub300\ub9bd\uc2dc\ud0a4\uc9c0 \uc54a\uace0 \ud568\uaed8 \uc0dd\uac01\ud560 \uc218 \uc788\ub294 \uc0ac\ub840\ub2e4. \uc774\uc138 \uc2e0\uad81\uc740 \uc804\ud1b5\uc744 \uc644\uc131\ub41c \ubb3c\uac74\ubcf4\ub2e4 \uacc4\uc18d \uc218\ud589\ud574\uc57c \ud558\ub294 \uc77c\ub85c \ubc14\ub77c\ubcf4\uac8c \ud55c\ub2e4."}, {"id": "isis-osiris-chest-and-search", "title": "\uc774\uc2dc\uc2a4 \u2014 \uc0ac\ub77c\uc9c4 \uc624\uc2dc\ub9ac\uc2a4\ub97c \ucc3e\uc544 \ub098\uc120 \uae38", "summary": "\uc774\uc2dc\uc2a4\uc758 \ub450 \ucc28\ub840 \uc218\uc0c9\uacfc \uc624\uc2dc\ub9ac\uc2a4\uc758 \uc0ac\ud6c4 \uc655\uad8c\uc744 \uc2a4\ud39c\uc2a4\uac00 \uc815\ub9ac\ud55c \uc804\uc2b9\uc758 \ud750\ub984\uc5d0 \ub530\ub77c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc2e0\ud654\uc640 \ubbfc\uc18d", "categories": ["arts"], "url": "stories/isis-osiris-chest-and-search/index.html", "image": "../media/isis-osiris-chest-and-search.jpg", "alt": "\u300e\uc544\ub2c8\uc758 \ud30c\ud53c\ub8e8\uc2a4\u300f\uc758 \uc624\uc2dc\ub9ac\uc2a4 \uc55e \uc7a5\uba74\uc744 \uc7ac\ud604\ud55c 1915\ub144 \ucc45\uc758 \ubcf5\uc81c \ub3c4\ud310", "text": "\uc774\uc2dc\uc2a4 \u2014 \uc0ac\ub77c\uc9c4 \uc624\uc2dc\ub9ac\uc2a4\ub97c \ucc3e\uc544 \ub098\uc120 \uae38 \uc794\uce58\uc758 \uc0c1\uc790\uc5d0\uc11c \ub0af\uc120 \uad81\uc804\uc758 \uae30\ub465, \ub2e4\uc2dc \uc774\uc5b4\uc9c0\ub294 \uc218\uc0c9\uae4c\uc9c0 \uc774\uc2dc\uc2a4\uc758 \ub450 \ucc28\ub840 \uc218\uc0c9\uacfc \uc624\uc2dc\ub9ac\uc2a4\uc758 \uc0ac\ud6c4 \uc655\uad8c\uc744 \uc2a4\ud39c\uc2a4\uac00 \uc815\ub9ac\ud55c \uc804\uc2b9\uc758 \ud750\ub984\uc5d0 \ub530\ub77c \uc77d\uc2b5\ub2c8\ub2e4. \uc2e0\ud654\uc640 \ubbfc\uc18d \ubb38\ud654\uc640 \uc608\uc220 \uc794\uce58\uc5d0 \uc544\ub984\ub2e4\uc6b4 \uc0c1\uc790\uac00 \ub4e4\uc5b4\uc628\ub2e4. \ubab8\uc5d0 \uaf2d \ub9de\ub294 \uc0ac\ub78c\uc5d0\uac8c \uc8fc\uaca0\ub2e4\ub294 \uc81c\uc548\uc5d0 \uc190\ub2d8\ub4e4\uc774 \ucc28\ub840\ub85c \ub204\uc6cc \ubcf8\ub2e4. \ub9c8\uc9c0\ub9c9\uc73c\ub85c \uc624\uc2dc\ub9ac\uc2a4\uac00 \ub4e4\uc5b4\uac00\uc790 \ub69c\uaed1\uc774 \ub2eb\ud78c\ub2e4. \uc120\ubb3c\ucc98\ub7fc \ubcf4\uc774\ub358 \ubb3c\uac74\uc740 \ucc98\uc74c\ubd80\ud130 \uadf8\ub97c \uac00\ub450\uae30 \uc704\ud574 \uc900\ube44\ub41c \uac83\uc774\uc5c8\ub2e4. \uc774\uc2dc\uc2a4\uc640 \uc624\uc2dc\ub9ac\uc2a4\uc758 \uc2e0\ud654\ub294 \uc774\ub807\uac8c \ud654\ub824\ud55c \uc794\uce58\uc5d0\uc11c \uae34 \uc218\uc0c9\uc73c\ub85c \ubc14\ub010\ub2e4. \uc774 \uae00\uc740 \ub8e8\uc774\uc2a4 \uc2a4\ud39c\uc2a4\uc758 \u300e\uace0\ub300 \uc774\uc9d1\ud2b8 \uc2e0\ud654\uc640 \uc804\uc124\u300f\uc5d0 \uc815\ub9ac\ub41c \uc774\uc57c\uae30\ub97c \ub530\ub77c \uc77d\ub294\ub2e4. \uc2dc\ub300\uc640 \uc9c0\uc5ed\uc5d0 \ub530\ub77c \uc5ec\ub7ec \ud615\ud0dc\ub85c \uc804\ud574\uc9c4 \uc2e0\ud654 \uac00\uc6b4\ub370 \ud55c \ud750\ub984\uc774\ub2e4. \uc624\uc2dc\ub9ac\uc2a4\ub97c \ud574\uce58\ub824\ub294 \uc138\ud2b8\ub294 \uadf8\uc758 \ubab8\uc5d0 \ub9de\ucdb0 \uc0c1\uc790\ub97c \ub9cc\ub4e4\uac8c \ud55c\ub2e4. \uc794\uce58\uc5d0\uc11c\ub294 \uc6b0\uc5f0\ud788 \ub9de\ub294 \uc0ac\ub78c\uc744 \ucc3e\ub294 \ub180\uc774\ucc98\ub7fc \uafb8\ubbfc\ub2e4. \ub2e4\ub978 \uc190\ub2d8\uc5d0\uac8c \ub9de\uc9c0 \uc54a\uc558\ub358 \uac83\uc740 \ud589\uc6b4\uc744 \uae30\ub2e4\ub9ac\ub294 \uacfc\uc815\uc774 \uc544\ub2c8\ub77c \uacc4\ud68d\ub41c \uc21c\uc11c\uc600\ub2e4. \uc624\uc2dc\ub9ac\uc2a4\uac00 \ub204\uc6b4 \ub4a4 \uc138\ud2b8\uc640 \ub3d9\ub8cc\ub4e4\uc740 \uc0c1\uc790\ub97c \ub2eb\uc544 \ub098\uc77c\uac15\uc73c\ub85c \ubcf4\ub0b8\ub2e4. \uc774\uc57c\uae30\ub294 \uc120\ud55c \uc655\uc744 \uc704\ud611\ud558\ub294 \ubc30\uc2e0\uc744 \uadf8\ub9b0\ub2e4. \ubc18\uc9dd\uc774\ub294 \uc7a5\uc2dd\uacfc \ud658\ub300\uc758 \uacf5\uac04\uc774 \uc0ac\ub78c\uc744 \uc548\uc2ec\uc2dc\ud0a4\ub294 \ud568\uc815\uc73c\ub85c \ubcc0\ud55c\ub2e4\ub294 \uc810\uc774 \uc624\ub798 \uae30\uc5b5\ub41c\ub2e4. \ub0a8\ud3b8\uc744 \uc783\uc740 \uc774\uc2dc\uc2a4\ub294 \uc560\ub3c4\uc758 \ubaa8\uc2b5\uc73c\ub85c \uae38\uc744 \ub098\uc120\ub2e4. \uc7a5\ub840\ub97c \uce58\ub974\uace0 \uc8fd\uc740 \uc774\ub97c \ub3cc\ubcf4\ub824\uba74 \ubab8\uc744 \ucc3e\uc544\uc57c \ud588\ub2e4. \ub9cc\ub098\ub294 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uc0c1\uc790\uc758 \ud589\ubc29\uc744 \ubb3b\uc9c0\ub9cc \uc27d\uac8c \ub2f5\uc744 \uc5bb\uc9c0 \ubabb\ud55c\ub2e4. \uc774 \ud310\ubcf8\uc5d0\uc11c\ub294 \uac15\uac00\uc758 \uc544\uc774\ub4e4\uc5d0\uac8c\ub3c4 \ubb3c\uc5b4\ubcf8\ub2e4. \ud070 \uad8c\ub825\uc744 \uac00\uc9c4 \uc5ec\uc2e0\uc774 \uc791\uc740 \ubaa9\uaca9\uc790\uc758 \ub9d0\uc5d0 \uadc0\ub97c \uae30\uc6b8\uc774\ub294 \uc7a5\uba74\uc774\ub2e4. \uc218\uc0c9\uc740 \ud798\uc73c\ub85c \ub2e8\ubc88\uc5d0 \ud574\uacb0\ub418\uc9c0 \uc54a\uace0 \ubcf4\uc558\ub2e4\ub294 \ub9d0\uacfc \uc9c0\ub098\uac04 \ud754\uc801\uc744 \uc774\uc5b4 \uac00\uba70 \uc9c4\ud589\ub41c\ub2e4. \uc0c1\uc790\ub294 \ubc14\ub2e4\ub97c \uac74\ub108 \ube44\ube14\ub85c\uc2a4\uc758 \ud574\uc548\uc5d0 \ub2ff\uace0 \ub098\ubb34\uac00 \uc790\ub77c\uba70 \uadf8 \uc548\uc5d0 \uac07\ud78c\ub2e4. \uadf8 \ub098\ub77c\uc758 \uc655\uc740 \ud6cc\ub96d\ud55c \ub098\ubb34\ub97c \ubca0\uc5b4 \uad81\uc804\uc744 \ubc1b\uce60 \uae30\ub465\uc73c\ub85c \uc0bc\ub294\ub2e4. \uad81\uc804 \uc0ac\ub78c\ub4e4\uc740 \uc790\uae30 \uc9d1 \uc548\uc5d0 \ubb34\uc5c7\uc774 \ub4e4\uc5b4 \uc788\ub294\uc9c0 \ubaa8\ub978\ub2e4. \ub5a0\ub0b4\ub824\uc628 \uc0c1\uc790\uc5d0\uc11c \ub098\ubb34, \ub098\ubb34\uc5d0\uc11c \uac74\ubb3c\uc758 \uc77c\ubd80\ub85c \ubaa8\uc2b5\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uac19\uc740 \ubb3c\uac74\uc774 \ub2e4\ub978 \uc4f0\uc784 \uc18d\uc5d0 \uc228\uc73c\ub2c8 \ucc3e\uc544\ub0b4\uae30 \ub354 \uc5b4\ub835\ub2e4. \uc774\uc2dc\uc2a4\uc758 \uc774\uc57c\uae30\ub294 \ubb3c\uac74\uc774 \uc5b4\ub514\ub85c \uac14\ub294\uc9c0\ubfd0 \uc544\ub2c8\ub77c \ubb34\uc5c7\uc73c\ub85c \ubc14\ub00c\uc5c8\ub294\uc9c0\ub3c4 \ub530\ub77c\uac00\uac8c \ud55c\ub2e4. \uc774\uc2dc\uc2a4\ub294 \ube44\ube14\ub85c\uc2a4\ub85c \uac00\uc11c \uc655\uac00\uc758 \uc0ac\ub78c\ub4e4\uacfc \uad00\uacc4\ub97c \ub9fa\ub294\ub2e4. \uad81\uc804\uc5d0 \ub4e4\uc5b4\uac04 \ub4a4\uc5d0\ub294 \uc544\uc774\ub97c \ub3cc\ubcf4\ub294 \uc5ed\ud560\ub3c4 \ub9e1\ub294\ub2e4. \uadf8\uacf3\uc5d0\uc11c\ub3c4 \uc2e0\uc758 \ud798\uacfc \uc778\uac04\uc758 \uc774\ud574\uac00 \uc5b4\uae0b\ub098\ub294 \uc77c\uc774 \uc77c\uc5b4\ub09c\ub2e4. \ub9c8\uce68\ub0b4 \uc790\uc2e0\uc758 \uc815\uccb4\uc640 \uc0ac\uc5f0\uc744 \uc54c\ub9b0 \uc774\uc2dc\uc2a4\ub294 \uae30\ub465\uc744 \ub2ec\ub77c\uace0 \ud55c\ub2e4. \ub098\ubb34\ub97c \uc5f4\uc790 \uadf8 \uc548\uc5d0\uc11c \uc624\uc2dc\ub9ac\uc2a4\uac00 \ub4e0 \uc0c1\uc790\ub97c \uaebc\ub0bc \uc218 \uc788\uc5c8\ub2e4. \uad81\uc804\uc744 \uc9c0\ud0f1\ud558\ub358 \ubb3c\uac74\uc774 \ud55c \uc5ec\uc2e0\uc5d0\uac8c\ub294 \uc0ac\ub791\ud558\ub294 \uc774\uc758 \uc228\uaca8\uc9c4 \uc790\ub9ac\uc600\ub358 \uac83\uc774\ub2e4. \uc774\uc2dc\uc2a4\ub294 \uc0c1\uc790\ub97c \uc774\uc9d1\ud2b8\ub85c \uac00\uc838\uc628\ub2e4. \uadf8\ub7ec\ub098 \uc7a0\uc2dc \uc228\uaca8 \ub454 \ub3d9\uc548 \uc138\ud2b8\uac00 \uadf8\uac83\uc744 \ubc1c\uacac\ud55c\ub2e4. \uadf8\ub294 \uc624\uc2dc\ub9ac\uc2a4\uc758 \uc720\ud574\ub97c \uc5ec\ub7ec \uc870\uac01\uc73c\ub85c \ub098\ub204\uc5b4 \ud769\uc5b4 \ub193\ub294\ub2e4. \uc774 \ud310\ubcf8\uc5d0\uc11c\ub294 \uc5f4\ub124 \uc870\uac01\uc774\ub77c\uace0 \uc804\ud55c\ub2e4. \ud55c \ubc88 \ucc3e\uc73c\uba74 \ub05d\ub098\ub294 \uc774\uc57c\uae30\uc600\ub2e4\uba74 \uc5ec\uae30\uc11c \uc774\ubbf8 \uc548\uc2ec\ud588\uc744 \uac83\uc774\ub2e4. \uadf8\ub7ec\ub098 \uc0c1\uc2e4\uc774 \ubc18\ubcf5\ub418\uba74\uc11c \uc774\uc2dc\uc2a4\ub294 \ub2e4\uc2dc \uae38\uc744 \ub098\uc11c\uc57c \ud55c\ub2e4. \ub3cc\uc544\uc628 \ubb3c\uac74\uc744 \uc9c0\ud0a4\ub294 \uc77c\uacfc \uc0ac\ub77c\uc9c4 \ubb3c\uac74\uc744 \ucc3e\ub294 \uc77c\uc740 \uc11c\ub85c \ub2e4\ub978 \uc5b4\ub824\uc6c0\uc774\uc5c8\ub2e4. \uc5ec\uc2e0\uc740 \ud30c\ud53c\ub8e8\uc2a4\ub85c \ub9cc\ub4e0 \ubc30\ub97c \ud0c0\uace0 \ud769\uc5b4\uc9c4 \uc720\ud574\ub97c \ucc3e\ub294\ub2e4. \ubc1c\uacac\ud55c \uacf3\uc5d0 \ubb3b\uace0 \ud45c\uc2dd\uc744 \uc138\uc6b0\ub294 \uc774\uc57c\uae30\ub294 \uc5ec\ub7ec \uc9c0\uc5ed\uc758 \uc624\uc2dc\ub9ac\uc2a4 \ubb34\ub364\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc218\uc0c9\uc758 \uae38\uc774 \ub545 \uc704\uc758 \uc5ec\ub7ec \uc7a5\uc18c\ub97c \ubb36\uc5b4 \uc8fc\ub294 \uc148\uc774\ub2e4. \uc774\ub97c \uc624\ub298\ub0a0\uc758 \ubc1c\uad74 \uc9c0\ub3c4\uc640 \uac19\ub2e4\uace0 \ubcfc \ud544\uc694\ub294 \uc5c6\ub2e4. \uc2e0\ud654\uac00 \uc7a5\uc18c\uc5d0 \uc758\ubbf8\ub97c \ubd80\uc5ec\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uc775\uc219\ud55c \ubb34\ub364\uacfc \uc131\uc18c\uac00 \ud558\ub098\uc758 \ud070 \uc0ac\uc5f0 \uc18d\uc5d0 \ub4e4\uc5b4\uac00\uba74\uc11c \uba40\ub9ac \ub5a8\uc5b4\uc9c4 \uacf3\ub3c4 \uad00\uacc4\ub97c \ub9fa\uac8c \ub41c\ub2e4. \uc774\uc57c\uae30\uc5d0\uc11c \uc624\uc2dc\ub9ac\uc2a4\ub294 \uc8fd\uc740 \uc774\ub4e4\uc758 \uc138\uacc4\ub97c \ub2e4\uc2a4\ub9ac\ub294 \uc874\uc7ac\ub85c \ub098\ud0c0\ub09c\ub2e4. \uc544\ub4e4 \ud638\ub8e8\uc2a4\uc640 \uc138\ud2b8\uc758 \ub2e4\ud23c\ub3c4 \uc774\uc5b4\uc9c4\ub2e4. \uc774\uc2dc\uc2a4\uac00 \ucc3e\uc558\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uace7 \ubaa8\ub4e0 \uc778\ubb3c\uc774 \uc61b \uc655\uad6d\uc5d0\uc11c \uc608\uc804\ucc98\ub7fc \uc0b0\ub2e4\ub294 \uacb0\ub9d0\uc740 \uc544\ub2c8\ub2e4. \ub0a8\ud3b8\uc744 \ub3cc\ubcf4\ub294 \uc77c\uacfc \ub2e4\uc74c \uc138\ub300\uc758 \uad8c\ub9ac\ub97c \uc9c0\ud0a4\ub294 \uc77c\uc774 \ud568\uaed8 \ub0a8\ub294\ub2e4. \uadf8\ub798\uc11c \uc774 \uc2e0\ud654\ub97c \uc8fd\uc740 \uc655\uc744 \ud55c \ubc88 \uc0b4\ub824 \ub0b4\ub294 \uc774\uc57c\uae30\ub85c\ub9cc \uc904\uc774\uba74 \ub9ce\uc740 \ubd80\ubd84\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \uc560\ub3c4\uc640 \uc0ac\ud6c4\uc758 \uc9c8\uc11c, \uc655\uad8c\uc758 \ubb38\uc81c\uac00 \uc11c\ub85c \uc5bd\ud600 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc61b \ub3c4\ud310\uc740 \u300e\uc544\ub2c8\uc758 \ud30c\ud53c\ub8e8\uc2a4\u300f\uc5d0 \ub098\ud0c0\ub09c \uc624\uc2dc\ub9ac\uc2a4 \uc55e\uc758 \uc7a5\uba74\uc744 \uc7ac\ud604\ud55c \uc790\ub8cc\ub2e4. \uc774\uc2dc\uc2a4\uac00 \ub098\ubb34\ub97c \uc5f4\uac70\ub098 \ubc30\ub97c \ud0c0\uace0 \uc218\uc0c9\ud558\ub294 \uc21c\uac04\uc744 \ucc0d\uc740 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc0ac\ud6c4\uc138\uacc4\uc5d0\uc11c \uc624\uc2dc\ub9ac\uc2a4\uac00 \uc5b4\ub5a4 \uc790\ub9ac\ub97c \uac16\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. 1915\ub144 \ucc45\uc5d0 \uc2e4\ub9b0 \ubcf5\uc81c \ub3c4\ud310\uacfc \uadf8 \ucc45\uc758 \uc124\uba85\uc740 \uac01\uac01\uc758 \uc790\ub8cc\ub2e4. \uc624\ub798\ub41c \uc800\uc790\uc758 \uad00\uc810\uc5d0\ub294 \uc624\ub298\uacfc \ub2e4\ub978 \ud574\uc11d\ub3c4 \uc788\ub2e4. \uc774 \uae00\uc740 \uc0ac\uac74\uc758 \ud750\ub984\uacfc \uc774\ubbf8\uc9c0\uc758 \uc5ed\ud560\uc744 \uad6c\ubcc4\ud558\uace0 \ub2f9\uc2dc \uc800\uc790\uc758 \ubaa8\ub4e0 \ud310\ub2e8\uc744 \uadf8\ub300\ub85c \ubc1b\uc544\ub4e4\uc774\uc9c0\ub294 \uc54a\uc558\ub2e4. \uc624\uc2dc\ub9ac\uc2a4\uc758 \uc2e0\ud654\uc5d0\ub294 \uc655\uc704\uc640 \ubc30\uc2e0\uc774 \uc788\uc9c0\ub9cc \ub3c5\uc790\uac00 \uc624\ub798 \ub530\ub77c\uac00\uac8c \ub418\ub294 \uac83\uc740 \uc774\uc2dc\uc2a4\uc758 \uc6c0\uc9c1\uc784\uc774\ub2e4. \ubb3b\uace0 \ucc3e\uc544\uac00\uace0 \ub2e4\uc2dc \uae38\uc744 \ub098\uc120\ub2e4. \ub2e4\ub978 \uc2e0\ub4e4\uc758 \ud070 \ud798\ubcf4\ub2e4 \ud3ec\uae30\ud558\uc9c0 \uc54a\ub294 \uc218\uc0c9\uc758 \uc2dc\uac04\uc774 \uc120\uba85\ud558\uac8c \ub0a8\ub294\ub2e4. \uc0c1\uc790\uac00 \uac15\uc744 \ub5a0\ub098 \ub098\ubb34\uc640 \uae30\ub465 \uc18d\uc5d0 \ub4e4\uc5b4\uac14\ub4ef \uc783\uc5b4\ubc84\ub9b0 \uac83\uc740 \ub54c\ub54c\ub85c \ub73b\ubc16\uc758 \ubaa8\uc2b5\uc73c\ub85c \uc228\uc5b4 \uc788\ub2e4. \uc774 \uc774\uc57c\uae30\ub294 \uadf8\uac83\uc744 \ub418\ucc3e\uc73c\uba74 \ubaa8\ub4e0 \uac83\uc774 \uc6d0\ub798\ub300\ub85c \ub41c\ub2e4\uace0 \uc27d\uac8c \uc57d\uc18d\ud558\uc9c0 \uc54a\ub294\ub2e4. \ucc3e\uace0 \ub3cc\ubcf4\ub294 \uc77c\uc774 \uc0c8\ub85c\uc6b4 \uad00\uacc4\uc640 \uc7a5\uc18c\ub97c \ub0a8\uae34\ub2e4\uace0 \ub4e4\ub824\uc900\ub2e4."}, {"id": "italy-print-painting-proposal", "title": "\ud310\ud654 \ud55c \uc7a5\uc774 \ud070 \uadf8\ub9bc\uc758 \uc81c\uc548\uc11c\uac00 \ub418\uc5c8\ub2e4", "summary": "\uc0b4\ubc14\ud1a0\ub974 \ub85c\uc0ac\uac00 \ud310\ud654\ub85c \ubcf4\uc5ec \uc8fc\uace0 \uc2f6\uc5c8\ub358 \ub354 \ud070 \uadf8\ub9bc\uc744 \uc0dd\uac01\ud574 \ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/italy-print-painting-proposal/index.html", "image": "../media/italy-print-painting-proposal.jpg", "alt": "\ud310\ud654 \ud55c \uc7a5\uc774 \ud070 \uadf8\ub9bc\uc758 \uc81c\uc548\uc11c\uac00 \ub418\uc5c8\ub2e4\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\ud310\ud654 \ud55c \uc7a5\uc774 \ud070 \uadf8\ub9bc\uc758 \uc81c\uc548\uc11c\uac00 \ub418\uc5c8\ub2e4 \uc774\ud0c8\ub9ac\uc544 \ud654\uac00\uac00 \ud6c4\uc6d0\uc790\ub97c \ucc3e\ub358 \ubc29\ubc95 \uc0b4\ubc14\ud1a0\ub974 \ub85c\uc0ac\uac00 \ud310\ud654\ub85c \ubcf4\uc5ec \uc8fc\uace0 \uc2f6\uc5c8\ub358 \ub354 \ud070 \uadf8\ub9bc\uc744 \uc0dd\uac01\ud574 \ubd05\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \uadf8\ub9bc\uc744 \ud06c\uac8c \uadf8\ub9ac\uace0 \uc2f6\uc740\ub370 \uadf8 \uc77c\uc744 \ub9e1\uaca8 \uc904 \uc0ac\ub78c\uc774 \uc5c6\ub2e4\uba74 \uc5b4\ub5bb\uac8c \ud560\uae4c. \uc694\uc998\uc774\ub77c\uba74 \uad6c\uc0c1\uc548\uc774\ub098 \uc791\uc740 \uacac\ubcf8\uc744 \ub9cc\ub4e4\uc5b4 \ubcf4\uc5ec \uc904 \uc218 \uc788\uc744 \uac83\uc774\ub2e4. \uc774\ud0c8\ub9ac\uc544\uc758 \uc608\uc220\uac00 \uc0b4\ubc14\ud1a0\ub974 \ub85c\uc0ac\uc5d0\uac8c\ub294 \ud310\ud654\ub77c\ub294 \ubc29\ubc95\uc774 \uc788\uc5c8\ub2e4. \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc740 \uadf8\uc758 \uac70\uc778\ub4e4\uc758 \ucd94\ub77d\uc774\ub77c\ub294 \ud310\ud654\ub97c \uc18c\uac1c\ud558\uba70 \ud070 \uadf8\ub9bc\uc744 \uc2e4\ud604\ud558\uae30 \uc704\ud574 \ud6c4\uc6d0\uc790\uc758 \uad00\uc2ec\uc744 \uc5bb\uc73c\ub824\ub358 \ubaa9\uc801\ub3c4 \uc124\uba85\ud55c\ub2e4. \ud310\ud654\uac00 \uc644\uc131\ub41c \uc791\ud488\uc774\uba74\uc11c \ub2e4\uc74c \uc77c\uc744 \uc81c\uc548\ud558\ub294 \ubb3c\uac74\uc774 \ub41c \uc148\uc774\ub2e4. \ubbf8\uc220\uad00 \ud574\uc124\uc5d0 \ub530\ub974\uba74 \uc791\ud488\uc740 \uac70\uc778\ub4e4\uc774 \uc2e0\ub4e4\uc758 \uc790\ub9ac\ub97c \uacf5\uaca9\ud558\ub824 \ud558\uc790 \uc720\ud53c\ud14c\ub974\uac00 \ubc88\uac1c\ub85c \uadf8\ub4e4\uc744 \ub5a8\uc5b4\ub728\ub9ac\ub294 \uc7a5\uba74\uc744 \ub2f4\ub294\ub2e4. \uc704\ucabd \uad6c\ub984\uc5d0\ub294 \uc2e0\uc774, \uc544\ub798\uc5d0\ub294 \ucd94\ub77d\ud558\ub294 \uac70\uc778\ub4e4\uc774 \ub193\uc774\ub294 \uad6c\uc0c1\uc774\ub2e4. \uc6b0\ub9ac\uac00 \uc5ec\uae30\uc11c \ubcf4\ub294 \uc0bd\ud654\ub294 \uadf8 \ud310\ud654\ub97c \ubcf5\uc81c\ud55c \uac83\uc774 \uc544\ub2c8\ub77c \uc791\uc5c5\uc2e4\uc744 \ub5a0\uc62c\ub9ac\ub3c4\ub85d \ub9cc\ub4e0 \uc124\uba85\uc6a9 \uadf8\ub9bc\uc774\ub2e4. \uc2e4\uc81c \ud654\uba74\uc758 \uad6c\uc131\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\ub294 \ubbf8\uc220\uad00\uc758 \uc791\ud488 \ud574\uc124\uc744 \uadfc\uac70\ub85c \uc77d\uc73c\uba74 \ub41c\ub2e4. \ub85c\uc0ac\ub294 \ud310\ud654\uac00\uc774\uba74\uc11c \ud654\uac00\uc600\uace0 \uc2dc\uc640 \uc5f0\uae30, \uc74c\uc545\uc5d0\uc11c\ub3c4 \ud65c\ub3d9\ud588\ub2e4\uace0 \ubbf8\uc220\uad00\uc740 \uc18c\uac1c\ud55c\ub2e4. \ud55c \uac00\uc9c0 \uc774\ub984\ud45c\ub9cc\uc73c\ub85c \uadf8\uc758 \uc77c\uc744 \ubaa8\ub450 \uc124\uba85\ud558\uae30\ub294 \uc5b4\ub824\uc6b4 \uc778\ubb3c\uc774\uc5c8\ub2e4. \uc774 \ud310\ud654\ub294 \uac19\uc740 \uc8fc\uc81c\uc758 \ud68c\ud654\ub97c \uc81c\uc791\ud560 \uc0dd\uac01\uc744 \uc54c\ub9ac\uace0 \uadf8 \uc77c\uc744 \ud6c4\uc6d0\ud560 \uc0ac\ub78c\uc744 \ucc3e\uae30 \uc704\ud55c \uac83\uc774\uc5c8\ub2e4\uace0 \ud55c\ub2e4. \uc774\ubbf8 \ud55c \ubc88 \ub9cc\ub4e0 \uc774\ubbf8\uc9c0\ub97c \ub2e4\uc74c \uc7ac\ub8cc\uc640 \ub2e4\uc74c \ud06c\uae30\uc758 \uc791\uc5c5\uc73c\ub85c \uc774\uc5b4 \ubcf4\ub824\ub294 \uc2dc\ub3c4\uc600\ub2e4. \ubbf8\uc220\uad00\uc774 \uc124\uba85\ud558\ub294 \uc7a5\uba74\uc5d0\ub294 \ub69c\ub837\ud55c \ubc29\ud5a5\uc774 \uc788\ub2e4. \uac70\uc778\ub4e4\uc740 \uc2e0\ub4e4\uc758 \uc790\ub9ac\ub97c \uacf5\uaca9\ud558\ub824 \ud558\uc9c0\ub9cc \uc720\ud53c\ud14c\ub974\uc758 \ubc88\uac1c\ub97c \ub9de\uc544 \uc544\ub798\ub85c \ucd94\ub77d\ud55c\ub2e4. \uc704\ucabd \uad6c\ub984\uacfc \uc544\ub798\ucabd \ubab8\uc758 \ub300\ube44\uac00 \uc774\uc57c\uae30\ub97c \uad6c\uc131\ud55c\ub2e4. \uc2e0\ud654\uc758 \uc774\ub984\uc744 \ubaa8\ub450 \ubaa8\ub974\ub354\ub77c\ub3c4 \uc5b4\ub290 \ubc29\ud5a5\uc73c\ub85c \ud798\uc774 \uc791\uc6a9\ud558\ub294\uc9c0 \uc54c\uba74 \uc7a5\uba74\uc758 \uae34\uc7a5\uc774 \uc870\uae08 \ubcf4\uc778\ub2e4. \ub2e4\ub9cc \ubcf8\ubb38\uc5d0 \uc2e4\ub9b0 \uc791\uc5c5\uc2e4 \uc0bd\ud654\uc5d0\uc11c \uc6d0\ubcf8 \ud310\ud654\uc758 \uc778\ubb3c \ubc30\uce58\ub97c \uc9c1\uc811 \ud655\uc778\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc2e4\uc81c \ud654\uba74\uc5d0 \ub300\ud55c \uc124\uba85\uc740 \uae30\uad00\uc758 \uc6d0\ubcf8 \ud574\uc124\uc744 \ub530\ub77c \uc77d\ub294 \ubd80\ubd84\uc774\ub2e4. \uadf8\ub9bc\uacfc \uc124\uba85\uc774 \uac01\uac01 \ubb34\uc5c7\uc744 \ubcf4\uc5ec \uc8fc\ub294\uc9c0 \uad6c\ubd84\ud558\uba74 \uc0c1\uc0c1\ud55c \uc7a5\uba74\uc744 \uc0ac\ub8cc\ucc98\ub7fc \ubc1b\uc544\ub4e4\uc774\uc9c0 \uc54a\uc73c\uba74\uc11c\ub3c4 \uc791\ud488\uc758 \uad6c\uc0c1\uc744 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uae30\uad00 \ud574\uc124\uc740 \uc791\ud488 \uc544\ub798\uc5d0 \uc62c\ub77c\uac04 \uc790\uac00 \ub354 \ud070 \ubab0\ub77d\uc744 \uacaa\ub294\ub2e4\ub294 \ucde8\uc9c0\uc758 \uacbd\uace0\uac00 \uc801\ud600 \uc788\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ucd94\ub77d\ud558\ub294 \ubab8\uacfc \ubb38\uc7a5\uc774 \uc11c\ub85c \uac19\uc740 \ubc29\ud5a5\uc744 \uac00\ub9ac\ud0a4\ub294 \uc148\uc774\ub2e4. \uc774\ubbf8\uc9c0\ub9cc \ubcf4\uace0 \uc2e0\ud654\uc758 \ud55c \uc7a5\uba74\uc73c\ub85c \uc9c0\ub098\ucce4\ub2e4\uba74 \uae00\uc744 \ud1b5\ud574 \uad00\ub78c\uc790\uc5d0\uac8c \uc5b4\ub5a4 \uc0dd\uac01\uc744 \uc694\uad6c\ud558\ub294\uc9c0 \ub2e4\uc2dc \ubcfc \uc218 \uc788\ub2e4. \uadf8 \ubb38\uc7a5\uc744 \uace7\ubc14\ub85c \ud654\uac00\uc758 \ubaa8\ub4e0 \uc815\uce58\uc801 \uc785\uc7a5\uc774\ub098 \uac1c\uc778\uc801 \ubd88\ud589\uc758 \uc554\ud638\ub85c \ud574\uc11d\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c \ud655\uc778\ub418\ub294 \uac83\uc740 \uadf8\ub9bc\uc5d0 \ub367\ubd99\uc778 \ub9d0\uc758 \uc5ed\ud560\uc774\ub2e4. \uc2dc\uc778\uc774\uae30\ub3c4 \ud588\ub358 \uc791\uac00\uc758 \ud65c\ub3d9\uacfc \uc5f0\uacb0\ud574 \ubcf4\uba74 \uc774\ubbf8\uc9c0\uc640 \uc5b8\uc5b4\uac00 \uc11c\ub85c \ub2e4\ub978 \ubd84\uc57c\ub85c\ub9cc \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc810\uc774 \ud765\ubbf8\ub86d\ub2e4. \uadf8\ub9bc\uc758 \ubc14\uae65 \uc5ec\ubc31\uc5d0\ub3c4 \uc77d\uc744 \uac83\uc774 \uc788\uc5c8\ub2e4. \ubcf4\ud1b5 \uc6b0\ub9ac\ub294 \uc644\uc131\ud488\uc744 \ubcf8 \ub4a4 \uadf8 \uc791\ud488\uc758 \uc804 \ub2e8\uacc4\ub97c \ucc3e\ub294\ub2e4. \uc774 \uacbd\uc6b0 \ud310\ud654\ub294 \uadf8 \uc790\uccb4\ub85c \uc644\uc131\ud55c \uc791\uc5c5\uc774\uba74\uc11c \uc55e\uc73c\ub85c \ub9cc\ub4e4 \ud68c\ud654\ub97c \uc54c\ub9ac\ub294 \uc81c\uc548\uc774\uae30\ub3c4 \ud588\ub2e4. \uc9c0\uae08 \uc788\ub294 \uc774\ubbf8\uc9c0\uac00 \ub2e4\uc74c \uc7ac\ub8cc\uc758 \uc791\uc5c5\uc744 \uc124\ub4dd\ud558\ub294 \uc5ed\ud560\uc744 \ub9e1\uc558\ub2e4. \uc791\ud488\uc774 \ud63c\uc790 \ub2eb\ud78c \uacb0\uacfc\ubb3c\uc774 \uc544\ub2c8\ub77c \ub2e4\uc74c \uc81c\uc791\uc744 \ud5a5\ud55c \ub300\ud654\uac00 \ub41c \uac83\uc774\ub2e4. \ud68c\ud654\ub97c \uc2e4\uc81c\ub85c \uc81c\uc791\ud558\ub824\uba74 \uc0dd\uac01\uacfc \uc19c\uc528\ub9cc\uc774 \uc544\ub2c8\ub77c \ube44\uc6a9\uacfc \ud6c4\uc6d0\uc774 \ud544\uc694\ud560 \uc218 \uc788\ub2e4. \uae30\uad00\uc774 \ud6c4\uc6d0\uc790\ub97c \ucc3e\uc73c\ub824\ub294 \ubaa9\uc801\uc744 \uc124\uba85\ud558\ub294 \uc774\uc720\ub2e4. \uc774 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uacb0\uad6d \uc5b4\ub290 \ud6c4\uc6d0\uc790\uac00 \ub098\uc130\uace0 \uacc4\ud68d\uc774 \uc5b4\ub5bb\uac8c \ub05d\ub0ac\ub294\uc9c0\uae4c\uc9c0 \ucd94\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc81c\uc548\uc758 \ubaa9\uc801\uacfc \ub098\uc911\uc758 \uc2e4\ud604 \uc5ec\ubd80\ub294 \uc11c\ub85c \ub2e4\ub978 \uae30\ub85d\uc73c\ub85c \ud655\uc778\ud560 \ubb38\uc81c\ub2e4. \ub85c\uc0ac\uac00 \uadf8\ub9bc\uacfc \ud310\ud654\ubfd0 \uc544\ub2c8\ub77c \uc2dc\uc640 \uc5f0\uae30, \uc74c\uc545\uc5d0\ub3c4 \uad00\uc5ec\ud588\ub2e4\ub294 \uc124\uba85\uc740 \ub2e8\uc21c\ud788 \uc7ac\uc8fc\uac00 \ub9ce\uc558\ub2e4\ub294 \uce6d\ucc2c\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc778\ubb3c\uc758 \ubab8\uc9d3\uacfc \uc7a5\uba74\uc758 \uadf9\uc801\uc778 \ub300\ube44, \ubb38\uc7a5\uc774 \ud568\uaed8 \uc788\ub294 \uc791\uc5c5\uc744 \ubcfc \ub54c \uadf8 \ud3ed\ub113\uc740 \uad00\uc2ec\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \ud615\uc2dd\uc758 \ud2b9\uc9d5\uc744 \ub2e4\ub978 \uc9c1\uc5c5 \ud558\ub098\uc5d0\uc11c \uc9c1\uc811 \uac00\uc838\uc654\ub2e4\uace0 \ud655\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud655\uc778\ub41c \ud65c\ub3d9\uc758 \ubc94\uc704\ub294 \uc791\uac00\ub97c \ub9cc\ub098\ub294 \uc785\uad6c\ub97c \ub113\ud600 \uc900\ub2e4. \ud55c \uc0ac\ub78c\uc744 \ud310\ud654\uac00\ub77c\ub294 \ub9d0\ub85c\ub9cc \uae30\uc5b5\ud588\uc744 \ub54c\ubcf4\ub2e4 \uc5ec\ub7ec \ub9e4\uccb4 \uc0ac\uc774\ub97c \uc624\uac04 \uc81c\uc791\uc790\ub85c \ubcfc \uc218 \uc788\ub2e4. \uc791\uc740 \uc885\uc774 \uc704\uc5d0 \ud070 \uc7a5\uba74\uc744 \uc81c\uc548\ud558\uace0 \ub610 \ub2e4\ub978 \uadf8\ub9bc\uc744 \uae30\ub300\ud558\uac8c \ud558\ub294 \uc77c\ub3c4 \uadf8 \ud65c\ub3d9\uc758 \ud55c \ubaa8\uc2b5\uc774\uc5c8\ub2e4. \uc608\uc220\ud488\uc744 \uad6c\uacbd\ud558\ub2e4\uac00 \uadf8\uac83\uc744 \ub9cc\ub4e4\uae30 \uc704\ud55c \uc870\uac74\uae4c\uc9c0 \ubcf4\uac8c \ub418\ub294 \uc774\uc57c\uae30\ub2e4. \uc624\ub298\uc758 \ub208\uc73c\ub85c \ubcf4\uba74 \uc791\uc740 \ubaa8\ud615\uc774\ub098 \uc81c\uc548\uc11c\ub97c \ub9cc\ub4dc\ub294 \uc77c\uacfc \ub2ee\uc544 \ubcf4\uc778\ub2e4. \ub2e4\ub9cc \ud310\ud654\uac00 \ub2e8\uc21c\ud55c \ubbf8\uc644\uc131 \ucd08\uc548\uc774\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud310\ud654 \uc790\uccb4\ub85c \uc644\uc131\ub41c \uc791\ud488\uc774\uba74\uc11c \ub354 \ud070 \uacc4\ud68d\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc5ed\ud560\ub3c4 \ud55c \uac83\uc774\ub2e4. \ubbf8\uc220\uad00\uc758 \uc791\ud488 \ud558\ub098\ub97c \ubcfc \ub54c \uadf8 \ub4a4\uc5d0 \ubb34\uc5c7\uc744 \ud558\ub824 \ud588\ub294\uc9c0\ub3c4 \uc9c8\ubb38\ud574 \ubcfc \uc218 \uc788\ub2e4. \ub9cc\ub4e0 \uc0ac\ub78c\uc774 \uc774 \uc774\ubbf8\uc9c0\ub85c \ub204\uad6c\ub97c \uc124\ub4dd\ud558\uace0 \uc2f6\uc5c8\ub294\uc9c0 \uc0dd\uac01\ud558\ub294 \uac83\uc774\ub2e4. \uac70\uc778\ub4e4\uc758 \ucd94\ub77d\uc740 \uc2e0\ud654\uc758 \uc7a5\uba74\uc778 \ub3d9\uc2dc\uc5d0 \ud55c \uc608\uc220\uac00\uc758 \ub2e4\uc74c \uc791\uc5c5\uc744 \ud5a5\ud55c \uc81c\uc548\uc774\uae30\ub3c4 \ud588\ub2e4."}, {"id": "jane-austen-life-and-writing", "title": "\uc81c\uc778 \uc624\uc2a4\ud2f4\uc758 \uc0dd\uc560 \u2014 \uc791\uc740 \uac70\uc2e4\uc5d0\uc11c \ub113\uc740 \uc138\uacc4\ub97c \uc4f0\ub2e4", "summary": "\uac00\uc871 \uc804\uae30\uc640 \ud3b8\uc9c0\ub97c \ud1b5\ud574 \uc775\uc219\ud55c \uc5f0\uc560\uc18c\uc124 \ub4a4\uc758 \uc791\uac00 \uc0dd\ud65c\uc744 \ub530\ub77c\uac11\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/jane-austen-life-and-writing/index.html", "image": "../media/jane-austen-life-and-writing.jpg", "alt": "\uc624\uc2a4\ud2f4 \uac00\uc871 \uc804\uae30\uc5d0 \uc2e4\ub9b0 \uc81c\uc778 \uc624\uc2a4\ud2f4\uc758 \uc5ed\uc0ac\uc801 \ucd08\uc0c1 \uc7ac\ud604 \ub3c4\ud310.", "text": "\uc81c\uc778 \uc624\uc2a4\ud2f4\uc758 \uc0dd\uc560 \u2014 \uc791\uc740 \uac70\uc2e4\uc5d0\uc11c \ub113\uc740 \uc138\uacc4\ub97c \uc4f0\ub2e4 \uc2a4\ud2f0\ube10\ud134\uc5d0\uc11c \ucd08\ud134\uae4c\uc9c0, \uac00\uc871\uacfc \uc774\uc0ac\uc640 \ucd9c\ud310\uc758 \uc2dc\uac04 \uac00\uc871 \uc804\uae30\uc640 \ud3b8\uc9c0\ub97c \ud1b5\ud574 \uc775\uc219\ud55c \uc5f0\uc560\uc18c\uc124 \ub4a4\uc758 \uc791\uac00 \uc0dd\ud65c\uc744 \ub530\ub77c\uac11\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \ubb34\ub3c4\ud68c\uc640 \ubc29\ubb38, \uac70\uc2e4\uc758 \ub300\ud654\uc640 \uacb0\ud63c \uc774\uc57c\uae30. \uc81c\uc778 \uc624\uc2a4\ud2f4\uc758 \uc18c\uc124\uc744 \ub5a0\uc62c\ub9ac\uba74 \uc791\uc740 \uc0dd\ud65c \uc7a5\uba74\ub4e4\uc774 \uba3c\uc800 \uc0dd\uac01\ub09c\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uc548\uc5d0\ub294 \ub3c8\uacfc \uc0c1\uc18d, \ud0c0\uc778\uc758 \ud3c9\uac00\uc640 \uc790\uae30 \ud310\ub2e8\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uc791\uac00\ub294 \uc775\uc219\ud55c \uacf5\uac04\uc744 \uc881\uc740 \uc138\uacc4\ub85c\ub9cc \ub450\uc9c0 \uc54a\uc558\ub2e4. \uc624\uc2a4\ud2f4\uc740 1775\ub144\uc5d0 \ud0dc\uc5b4\ub098 1817\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub0ac\ub2e4. \uadf8\uc758 \uc0dd\uc560\ub97c \uc870\uc6a9\ud55c \uc2dc\uace8\uc5d0\uc11c \uc800\uc808\ub85c \uba85\uc791\uc774 \ub098\uc628 \uc774\uc57c\uae30\ub85c\ub9cc \uc815\ub9ac\ud558\uba74, \uc774\ub3d9\uacfc \uac00\uc871\uc758 \uc0ac\uc815, \uc791\ud488\uc744 \uace0\uce58\uace0 \uc138\uc0c1\uc5d0 \ub0b4\ub193\ub294 \uc2dc\uac04\uc774 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc774\ubc88\uc5d0\ub294 \uc18c\uc124 \ubc16\uc758 \uc0dd\ud65c\uc744 \uc870\uae08 \ub530\ub77c\uac00 \ubcf4\uc790. \uadf8\ub294 \uc2a4\ud2f0\ube10\ud134\uc758 \ubaa9\uc0ac\uad00\uc5d0\uc11c \uc790\ub790\ub2e4. \uac00\uc871 \uc548\uc5d0\uc11c \ucc45\uc744 \uc77d\uace0 \uae00\uc744 \uc4f0\uba70 \uc774\uc57c\uae30\ub97c \uc990\uae30\ub294 \ud658\uacbd\uc774 \uc788\uc5c8\ub2e4. \uc5b4\ub9b0 \uc2dc\uc808\uc758 \uae00\uc5d0\uc11c\ub3c4 \ubb38\uc7a5\uc744 \ud749\ub0b4 \ub0b4\uace0 \uacfc\uc7a5\ud558\uba70 \uc0ac\ub78c\ub4e4\uc758 \ud0dc\ub3c4\ub97c \uc7ac\ubbf8\uc788\uac8c \ube44\ud2b8\ub294 \ubaa8\uc2b5\uc744 \ubcfc \uc218 \uc788\ub2e4. \ub098\uc911\uc758 \uc815\uad50\ud55c \uc18c\uc124\uc5d0 \uc55e\uc120 \uc5f0\uc2b5\uc758 \uc2dc\uac04\uc774\ub2e4. \uc791\uac00\uc758 \uc7ac\ub2a5\uc744 \uac00\uc871\uc758 \uc601\ud5a5\ub9cc\uc73c\ub85c \ubaa8\ub450 \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \ud63c\uc790 \uba38\ub9bf\uc18d\uc5d0\uc11c \uc774\uc57c\uae30\ub97c \uc644\uc131\ud55c \uc874\uc7ac\ub85c \uc0c1\uc0c1\ud558\uae30\ubcf4\ub2e4, \uae00\uc744 \uc77d\uace0 \ub4e4\uc5b4 \uc904 \uc0ac\ub78c\ub4e4\uc774 \uc788\ub358 \uad6c\uccb4\uc801\uc778 \uc0dd\ud65c\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ub300\ud654\uc758 \ub9ac\ub4ec\uacfc \ub2e4\ub978 \uc0ac\ub78c\uc758 \ubc18\uc751\uc744 \uc544\ub294 \uac10\uac01\ub3c4 \uc774\ub7f0 \uc138\uacc4\uc640 \ub2ff\uc544 \uc788\uc5c8\uc744 \uac83\uc774\ub2e4. \uc5b8\ub2c8 \uce90\uc120\ub4dc\ub77c\ub294 \uc911\uc694\ud55c \uac00\uc871\uc774\uc790 \ud3b8\uc9c0 \uc0c1\ub300\uc600\ub2e4. \ub0a8\uc544 \uc788\ub294 \ud3b8\uc9c0\ub294 \uc774\uc0ac\uc640 \ubc29\ubb38, \uc0ac\ub78c\ub4e4\uc758 \uc18c\uc2dd\uacfc \uc791\ud488\uc758 \uc9c4\ud589\uc744 \uc804\ud55c\ub2e4. \uc6b0\ub9ac\ub294 \uc18c\uc124\uacfc\ub294 \ub2e4\ub978 \ub9d0\ud22c\uc758 \uc624\uc2a4\ud2f4\uc744 \uadf8 \uae30\ub85d\uc5d0\uc11c \ub9cc\ub098\uae30\ub3c4 \ud55c\ub2e4. \uadf8\ub7ec\ub098 \ubaa8\ub4e0 \ud3b8\uc9c0\uac00 \ub0a8\uc544 \uc788\uc9c0\ub294 \uc54a\ub2e4. \uac00\uc871 \uc804\uae30 \uc790\uccb4\ub3c4 \uce90\uc120\ub4dc\ub77c\uac00 \ud3b8\uc9c0 \uc77c\ubd80\ub97c \uc5c6\uc574\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc124\uba85\ud55c\ub2e4. \uadf8\ub798\uc11c \ub0a8\uc740 \uae30\ub85d\uc758 \ube48\uce78\uc744 \uc0c1\uc0c1\uc73c\ub85c \ubaa8\ub450 \ucc44\uc6cc \uc791\uac00\uc758 \uc18d\ub9c8\uc74c\uc744 \ud655\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uac00\uae4c\uc6b4 \uac00\uc871\uc774 \uc804\ud55c \uc790\ub8cc\ub77c\ub294 \uc7a5\uc810\uacfc \uadf8\ub4e4\uc774 \uace0\ub974\uace0 \ub0a8\uae34 \uae30\ub85d\uc774\ub77c\ub294 \uc131\uaca9\uc744 \ud568\uaed8 \uc77d\uc73c\uba74 \uc88b\ub2e4. \uac00\uc871\uc774 \uc2a4\ud2f0\ube10\ud134\uc744 \ub5a0\ub098 \ubc30\uc2a4\ub85c \uc62e\uae34 \uc77c\uc740 \uc911\uc694\ud55c \uc0dd\ud65c\uc758 \ubcc0\ud654\uc600\ub2e4. \uc775\uc219\ud55c \uc9d1\uc744 \ub5a0\ub098 \uc0ac\ub78c\uacfc \uacf5\uac04\uc744 \uc0c8\ub86d\uac8c \ub9cc\ub098\uac8c \ub41c\ub2e4. \uc774\ud6c4 \uc544\ubc84\uc9c0\uac00 \uc138\uc0c1\uc744 \ub5a0\ub098\uba74\uc11c \uc5b4\uba38\ub2c8\uc640 \uc790\ub9e4\ub4e4\uc758 \uc0dd\ud65c \uc870\uac74\ub3c4 \ub2e4\uc2dc \ub2ec\ub77c\uc84c\ub2e4. \uc774 \uc774\ub3d9\uc744 \uace7\ubc14\ub85c \uc5b4\ub290 \uc18c\uc124 \uc7a5\uba74\uc758 \uc2e4\uc81c \uc6d0\uc778\uc774\ub77c\uace0 \uc5f0\uacb0\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc791\ud488 \uc18d \uc0ac\uac74\uacfc \uc791\uac00\uc758 \uacbd\ud5d8\uc740 \uc77c\ub300\uc77c \ub300\uc751\ud45c\uac00 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uac70\ucc98\uc640 \uacbd\uc81c\uc801 \uae30\ubc18\uc774 \ubc14\ub014 \ub54c \uae00\uc744 \uc4f0\ub294 \uc0ac\ub78c\uc758 \ud558\ub8e8\ub3c4 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4\ub294 \uc810\uc740 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc548\uc815\ub41c \uc791\uc5c5\uc740 \ub9c8\uc74c\ub9cc \uba39\uc73c\uba74 \uc5b8\uc81c\ub098 \ud655\ubcf4\ub418\ub294 \uc790\uc6d0\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ucd08\ud134\uc73c\ub85c \uc62e\uaca8 \uc9c0\ub0b4\uac8c \ub41c \uc2dc\uae30\ub294 \uc791\ud488\uc744 \ub2e4\ub4ec\uace0 \ucd9c\ud310\ud558\ub294 \uc0b6\uc744 \uc774\ud574\ud558\ub294 \ub370 \uc911\uc694\ud558\ub2e4. \uac00\uc871\uc758 \ub3c4\uc6c0\uc73c\ub85c \uac70\ucc98\uac00 \ub9c8\ub828\ub418\uace0 \uc775\uc219\ud55c \uc6d0\uace0\ub97c \ub2e4\uc2dc \uc190\ubcf4\uba70 \uc0c8\ub85c\uc6b4 \uc791\uc5c5\uc744 \uc774\uc5b4 \uac04\ub2e4. \ud55c \uad8c\uc758 \uc18c\uc124\uc740 \ucc98\uc74c \uc0dd\uac01\ub09c \ud574\uc640 \ub3c5\uc790\uac00 \ub9cc\ub098\uac8c \ub41c \ud574\uac00 \ud06c\uac8c \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc774 \uc810\uc744 \uc54c\uba74 \uc774\ubbf8 \uc368 \ub454 \uac83\uc744 \uace0\uce58\ub294 \uc77c\ub3c4 \ucc3d\uc791\uc758 \uc911\uc2ec\uc774\ub77c\ub294 \uc0ac\uc2e4\uc774 \ubcf4\uc778\ub2e4. \uc791\uac00\ub294 \uccab \uc601\uac10\uc744 \ubcf4\uad00\ub9cc \ud55c \uac83\uc774 \uc544\ub2c8\ub77c \ubb38\uc7a5\uacfc \uc778\ubb3c, \uad6c\uc870\ub97c \ub2e4\ub4ec\uc5c8\ub2e4. \ucd9c\ud310\ub41c \ucc45\uc744 \ubcf4\uace0 \ucc98\uc74c\ubd80\ud130 \uadf8 \ubaa8\uc2b5\uc73c\ub85c \ub5a0\uc62c\ub790\uc744 \uac83\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\uc9c0\ub9cc, \uadf8 \uc55e\uc5d0\ub294 \uc5ec\ub7ec \ubc88\uc758 \ud310\ub2e8\uc774 \ub193\uc5ec \uc788\ub2e4. \u300e\uc774\uc131\uacfc \uac10\uc131\u300f\uc740 1811\ub144, \u300e\uc624\ub9cc\uacfc \ud3b8\uacac\u300f\uc740 1813\ub144\uc5d0 \ucd9c\uac04\ub418\uc5c8\ub2e4. \uc774\ud6c4 \u300e\ub9e8\uc2a4\ud544\ub4dc \ud30c\ud06c\u300f\uc640 \u300e\uc5d0\ub9c8\u300f \uac19\uc740 \uc791\ud488\uc774 \uc774\uc5b4\uc9c4\ub2e4. \uc18c\uc124 \uc18d \ubb34\ub3c4\ud68c\uc640 \uac00\uc871\ub4e4\uc758 \ub300\ud654\uac00 \ucc45\uc744 \uc0b0 \ub3c5\uc790\uc758 \uc0dd\ud65c \uc548\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \uc2dc\uac04\uc774 \uc5f4\ub9b0 \uac83\uc774\ub2e4. \ucd9c\ud310\uc740 \uc791\ud488\uc774 \uc88b\uc73c\uba74 \uc790\ub3d9\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\ub294 \ub2e8\uc77c\ud55c \uc21c\uac04\uc774 \uc544\ub2c8\ub2e4. \uc6d0\uace0\ub97c \ub0b4\uace0 \uc870\uac74\uc744 \uc815\ud558\uace0 \uc778\uc1c4\uc640 \ud310\ub9e4\ub97c \uc9c0\ucf1c\ubcf4\ub294 \uacfc\uc815\uc774 \uc788\uc5c8\ub2e4. \uac00\uc871 \uc804\uae30\uc640 \ud3b8\uc9c0\ub97c \uc77d\uc73c\uba74 \uc791\ud488\uc744 \uc4f4 \uc0ac\ub78c\uc5d0\uac8c\ub3c4 \ub3c8\uacfc \ub3c5\uc790\uc758 \ubc18\uc751\uc774 \uad6c\uccb4\uc801\uc778 \uad00\uc2ec\uc774\uc5c8\ub2e4\ub294 \uc810\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \ubb38\ud559\uc758 \uac00\uce58\uc640 \ucc45\uc774 \ub9cc\ub4e4\uc5b4\uc9c0\ub294 \ud604\uc2e4\uc740 \ud568\uaed8 \uc874\uc7ac\ud55c\ub2e4. \uc624\uc2a4\ud2f4\uc758 \uc18c\uc124\uc5d0\uc11c\ub294 \ub204\uad6c\uc640 \uacb0\ud63c\ud558\ub294\uc9c0\uac00 \uc911\uc694\ud55c \ubb38\uc81c\ub2e4. \ub3d9\uc2dc\uc5d0 \uadf8 \uc120\ud0dd\uc744 \ub458\ub7ec\uc2fc \uc0dd\ud65c\uc758 \uc548\uc815\uacfc \uc7ac\uc0b0, \uac00\uc871\uc758 \uae30\ub300\uac00 \ubc18\ubcf5\ud574\uc11c \ub4f1\uc7a5\ud55c\ub2e4. \uc0ac\ub78c\uc744 \uc0ac\ub791\ud55c\ub2e4\ub294 \ub9d0\uc774 \uadf8\uac00 \ub193\uc778 \uc0ac\ud68c\uc801 \uc870\uac74\uc744 \uc800\uc808\ub85c \uc9c0\uc6b0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub798\uc11c \uadf8\uc758 \uad00\uc2ec\uc744 \uc5f0\uc560\ub9cc \uc798 \uad00\ucc30\ud55c \uc7ac\uce58\ub85c \uc881\ud788\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc791\uc740 \ubb34\ub840\uac00 \ub204\uad6c\uc5d0\uac8c \ub354 \uc27d\uac8c \ud5c8\uc6a9\ub418\ub294\uc9c0, \uc790\uae30 \ud310\ub2e8\uc5d0 \ub300\ud55c \uc790\uc2e0\uac10\uc774 \uc5b4\ub5bb\uac8c \uc624\ub958\ub97c \ub9cc\ub4e4 \uc218 \uc788\ub294\uc9c0\ub3c4 \uc77d\uac8c \ub41c\ub2e4. \uc778\ubb3c\ub4e4\uc758 \ub300\ud654\ub97c \ub530\ub77c\uac00\uba74 \uc0ac\ub791\uacfc \ub3c8, \uc778\uc2dd\uacfc \uc608\uc758\uac00 \uac19\uc740 \uc7a5\uba74\uc5d0\uc11c \uc791\ub3d9\ud55c\ub2e4. \uac74\uac15\uc774 \ub098\ube60\uc9c4 \uadf8\ub294 1817\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub0ac\ub2e4. \ub9d0\ub144\uae4c\uc9c0 \uc791\uc5c5\uacfc \uac00\uc871\uc758 \uc0dd\ud65c\uc774 \uc774\uc5b4\uc84c\uace0, \uc77c\ubd80 \uc791\ud488\uc740 \uc8fd\uc740 \ub4a4 \ub3c5\uc790\uc640 \ub9cc\ub0ac\ub2e4. \uc624\ub298 \uc6b0\ub9ac\uac00 \uc54c\uace0 \uc788\ub294 \uc791\ud488 \ubaa9\ub85d\uc774 \uc791\uac00\uac00 \uc0b4\uc544\uc11c \ub204\ub9b0 \uba85\uc131\uacfc \uc815\ud655\ud788 \uc77c\uce58\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud655\uc778\ud558\uc9c0 \uc54a\uc740 \ubcd1\uba85\uc744 \ubd99\uc774\uac70\ub098 \ub9c8\uc9c0\ub9c9 \uc2dc\uae30\ub97c \uc18c\uc124\uc758 \ubaa8\ub4e0 \ubd84\uc704\uae30\uc640 \uc5f0\uacb0\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub0a8\uc544 \uc788\ub294 \uae30\ub85d\uc774 \uc54c\ub824 \uc8fc\ub294 \uc0dd\ud65c\uacfc \uc791\ud488\uc758 \uc2dc\uac04\uc744 \ucc28\ub840\ub85c \uc77d\uc73c\uba74 \ucda9\ubd84\ud558\ub2e4. \uc9e7\uc740 \uc0dd\uc560\ub77c\ub294 \ub9d0 \uc548\uc5d0\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc9d1\uacfc \uc6d0\uace0, \uad00\uacc4\uac00 \uc788\uc5c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 1913\ub144 \uac00\uc871 \uc804\uae30\uc5d0 \uc218\ub85d\ub41c \uc624\uc2a4\ud2f4\uc758 \uc5ed\uc0ac\uc801 \ucd08\uc0c1 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \uc18c\uc124 \uc18d \uc5ec\uc8fc\uc778\uacf5\uc758 \uc5bc\uad74\uc744 \uadf8\ub9b0 \uac83\uc774 \uc544\ub2c8\ub77c \uc2e4\uc81c \uc791\uac00\ub97c \uc804\ud558\ub294 \ud6c4\ub300 \uc790\ub8cc\ub2e4. \uc5bc\uad74\ub9cc\uc73c\ub85c \ubb38\uccb4\ub098 \uc131\uaca9\uc744 \ubaa8\ub450 \uc124\uba85\ud560 \uc218\ub294 \uc5c6\uc9c0\ub9cc \uc791\uac00\uc758 \uc0b6\uc73c\ub85c \ub4e4\uc5b4\uac08 \ucd9c\ubc1c\uc810\uc774 \ub41c\ub2e4. \uc18c\uc124\ub85c \ub3cc\uc544\uac00\uba74 \ub204\uac00 \ub9d0\uc744 \ub3c5\ucc28\uc9c0\ud558\uace0 \ub204\uac00 \uc870\uc6a9\ud788 \ud310\ub2e8\uc744 \ubc14\uafb8\ub294\uc9c0 \ub4e4\uc5b4 \ubcf4\uc790. \uc791\uc740 \uac70\uc2e4\uc744 \uc138\ubc00\ud558\uac8c \uc37c\ub2e4\ub294 \uac83\uc740 \ubcfc \uc138\uacc4\uac00 \uc791\uc558\ub2e4\ub294 \ub73b\uacfc \uac19\uc9c0 \uc54a\ub2e4. \ud55c \uc0ac\ub78c\uc758 \ub9d0\ud22c\uc640 \uc120\ud0dd \uc548\uc5d0\uc11c \uc0ac\ud68c\uc758 \ub113\uc740 \uad00\uacc4\ub97c \ub4dc\ub7ec\ub0b8 \uc791\uac00\ub97c \ub2e4\uc2dc \ub9cc\ub098\uac8c \ub41c\ub2e4."}, {"id": "japan-fierce-temple-guardian", "title": "\uc808\uc744 \uc9c0\ud0a4\ub294 \uc5bc\uad74\uc740 \uc65c \uadf8\ub807\uac8c \ubb34\uc11c\uc6b8\uae4c", "summary": "\ud5d8\uc0c1\uad82\uc740 \ud45c\uc815\uc774 \ubc29\ubb38\uac1d\uc744 \ud5a5\ud55c \uc801\ub300\uac10\ub9cc\uc740 \uc544\ub2d0 \uc218 \uc788\ub2e4\ub294 \uc774\uc57c\uae30\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/japan-fierce-temple-guardian/index.html", "image": "../media/japan-fierce-temple-guardian.jpg", "alt": "\uc808\uc744 \uc9c0\ud0a4\ub294 \uc5bc\uad74\uc740 \uc65c \uadf8\ub807\uac8c \ubb34\uc11c\uc6b8\uae4c\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\uc808\uc744 \uc9c0\ud0a4\ub294 \uc5bc\uad74\uc740 \uc65c \uadf8\ub807\uac8c \ubb34\uc11c\uc6b8\uae4c \uc77c\ubcf8 \uc218\ud638\uc0c1\uc744 \ubcf4\ub294 \uc2dc\uc120\uc744 \ubc14\uafb8\ub294 \ubc29\ubc95 \ud5d8\uc0c1\uad82\uc740 \ud45c\uc815\uc774 \ubc29\ubb38\uac1d\uc744 \ud5a5\ud55c \uc801\ub300\uac10\ub9cc\uc740 \uc544\ub2d0 \uc218 \uc788\ub2e4\ub294 \uc774\uc57c\uae30\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \ub208\uc744 \ud06c\uac8c \ub728\uace0 \uc785\uc744 \ubc8c\ub9b0 \uc870\uac01\uc0c1\uc774 \uc55e\uc744 \ub0b4\ub824\ub2e4\ubcf8\ub2e4. \ucc98\uc74c \ub9cc\ub0ac\ub2e4\uba74 \ubc18\uac11\uac8c \ub9de\uc544 \uc8fc\ub294 \uc5bc\uad74\uc774\ub77c\uace0 \ud558\uae30\ub294 \uc5b4\ub824\uc6b8 \uac83\uc774\ub2e4. \uadf8\ub7f0\ub370 \uc77c\ubcf8\uc758 \ubd88\uad50 \uc218\ud638\uc0c1\uc744 \ubcfc \ub54c\ub294 \uc9c8\ubb38\uc744 \ud55c \ubc88 \ubc14\uafd4 \ubcfc \uc218 \uc788\ub2e4. \ub204\uad6c\ub97c \uac81\uc8fc\uae30 \uc704\ud55c \ud45c\uc815\uc77c\uae4c. \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc740 \uc288\ucf58\uace0\uc9c4\uc73c\ub85c \uc18c\uac1c\ud558\ub294 \uc218\ud638\uc0c1\uc5d0 \uad00\ud55c \uad50\uc721 \uc790\ub8cc\uc5d0\uc11c \ubc14\ub85c \uadf8 \ub450 \uac00\uc9c0 \ub290\ub08c\uc744 \ud568\uaed8 \uc9da\ub294\ub2e4. \ubb34\uc11c\uc6c0\uacfc \ubcf4\ud638\ubc1b\ub294 \ub9c8\uc74c\uc774\ub2e4. \ubbf8\uc220\uad00 \uc124\uba85\uc740 \ud06c\uac8c \ubd80\ub985\ub72c \ub208\uacfc \uc678\uce58\ub294 \ub4ef \uc5f4\ub9b0 \uc785, \uac15\ud55c \ubab8\uc758 \ud45c\ud604\uc744 \uc774\uc57c\uae30\ud55c\ub2e4. \uc0ac\ucc30\ub85c \ub2e4\uac00\uc624\ub294 \uc0ac\ub78c\uc5d0\uac8c \ub450\ub824\uc6c0\uc744 \uc904 \uc218 \uc788\ub294 \ubaa8\uc2b5\uc774\ub2e4. \uadf8\ub7ec\ub098 \uc548\uc73c\ub85c \ub4e4\uc5b4\uac00 \ub9c8\uc74c\uc744 \uac00\ub77c\uc549\ud788\ub824\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ub2e4\ub978 \ub73b\uc73c\ub85c \ub290\uaef4\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \ubb34\uc5b8\uac00\uac00 \uc790\uc2e0\uc744 \uc9c0\ucf1c \uc8fc\uace0 \uc788\ub2e4\ub294 \uc548\ub3c4\uac10\uc774\ub2e4. \uac19\uc740 \ud45c\uc815\uc774\ub77c\ub3c4 \uadf8 \uc874\uc7ac\ub97c \ub0b4 \ud3b8\uc73c\ub85c \uc0dd\uac01\ud558\ub294\uc9c0\uc5d0 \ub530\ub77c \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c0\ub294 \uac83\uc774\ub2e4. \uc774 \uc870\uac01\uc744 \uacf5\uaca9\uc801\uc778 \uc5bc\uad74 \ud558\ub098\ub85c\ub9cc \ubcf4\uba74 \uae30\uad34\ud55c \uc7a5\uc2dd\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc0ac\ucc30\uc744 \uc9c0\ud0a4\ub294 \uc5ed\ud560\uacfc \ud568\uaed8 \ubcf4\uba74 \ubab8\uc9d3\uc744 \uc77d\ub294 \ubc29\ubc95\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc6c3\uace0 \uc788\uc5b4\uc57c\ub9cc \uce5c\uc808\ud55c \uc874\uc7ac\uc778 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ub298\ub0a0 \ubb38 \uc55e\uc5d0 \ubd99\uc774\ub294 \uacbd\uace0\ubb38\ub3c4 \ub5a0\uc62c\ub824 \ubcfc \uc218 \uc788\ub2e4. \ub4e4\uc5b4\uc624\ub294 \ubaa8\ub4e0 \uc0ac\ub78c\uc744 \ubbf8\uc6cc\ud574\uc11c\ub77c\uae30\ubcf4\ub2e4 \uc548\ucabd\uc758 \uc0ac\ub78c\uacfc \uacf5\uac04\uc744 \ubcf4\ud638\ud558\ub824\ub294 \ubaa9\uc801\uc77c \ub54c\uac00 \uc788\ub2e4. \uc774\uac83\uc740 \uc5ed\ud560\uc744 \uc774\ud574\ud558\uae30 \uc704\ud55c \ud604\ub300\uc758 \ube44\uc720\ub2e4. \uac19\uc740 \uac15\ud55c \ud45c\uc815\uc774\ub77c\ub3c4 \ubb34\uc5c7\uc744 \uc9c0\ud0a4\ub294 \uc874\uc7ac\uc778\uc9c0\uc5d0 \ub530\ub77c \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc704\ud611\uc744 \ubc1b\ub294 \ucabd\uc5d0\uc11c\ub294 \uacf5\uaca9\uc73c\ub85c, \ubcf4\ud638\ubc1b\ub294 \ucabd\uc5d0\uc11c\ub294 \ubc29\uc5b4\ub85c \ub290\ub084 \uc218 \uc788\ub2e4. \ubbf8\uc220\uad00\uc758 \uad50\uc721 \uc790\ub8cc\ub3c4 \uc774 \ub450 \uac00\ub2a5\uc131\uc744 \ud568\uaed8 \uc81c\uc548\ud55c\ub2e4. \ud45c\uc815\uc758 \ubaa8\uc591\uacfc \uadf8\uac83\uc774 \ud5a5\ud55c \uad00\uacc4\ub97c \ub098\ub204\uc5b4 \uc77d\uc73c\uba74 \ubb34\uc12d\ub2e4\ub294 \uccab \uac10\uc0c1\uc5d0\uc11c \ud55c \uac78\uc74c \ub354 \ub4e4\uc5b4\uac08 \uc218 \uc788\ub2e4. \uc774\uac83\uc740 \ub2f9\uc2dc\uc758 \ubaa8\ub4e0 \ubc29\ubb38\uc790\uac00 \uac19\uc740 \uac10\uc815\uc744 \ub290\uaf08\ub2e4\ub294 \uae30\ub85d\uc740 \uc544\ub2c8\ub2e4. \uad50\uc721 \uc790\ub8cc\uac00 \uac00\ub2a5\ud55c \ubc18\uc751\uc744 \uc0dd\uac01\ud574 \ubcf4\ub3c4\ub85d \ub358\uc9c4 \uad00\uc810\uc774\ub2e4. \uc790\uc2e0\uc774 \uc0ac\ucc30\ub85c \ub2e4\uac00\uc624\ub294 \uc0ac\ub78c\uc778\uc9c0 \uc548\uc5d0\uc11c \uace0\uc694\ud788 \uba38\ubb34\ub974\ub824\ub294 \uc0ac\ub78c\uc778\uc9c0 \uc0c1\uc0c1\ud574 \ubcf4\uba74, \ud558\ub098\uc758 \uc870\uac01\uc744 \uc11c\ub85c \ub2e4\ub978 \uc790\ub9ac\uc5d0\uc11c \ub9cc\ub098\ub294 \uacbd\ud5d8\uc744 \uc774\ud574\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ubd80\ub985\ub72c \ub208\uc740 \uc2dc\uc120\uc758 \ubc29\ud5a5\uc744 \uac15\uc870\ud558\uace0 \ud06c\uac8c \uc5f4\ub9b0 \uc785\uc740 \uc18c\ub9ac\uac00 \ub098\ub294 \ub4ef\ud55c \uc778\uc0c1\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \uac15\ud55c \ubab8\uc758 \ud45c\ud604\uc774 \uadf8 \uc5bc\uad74\uacfc \ud568\uaed8 \ub193\uc774\uba74 \uc791\uc740 \ud45c\uc815 \ubcc0\ud654\ubcf4\ub2e4 \ud6e8\uc52c \ud070 \ud798\uc73c\ub85c \ub2e4\uac00\uc628\ub2e4. \ub3cc\uc774\ub098 \ub098\ubb34\ub85c \ub41c \ud615\uc0c1\uc5d0\uc11c\ub3c4 \uc6b0\ub9ac\ub294 \uc6c0\uc9c1\uc784\uacfc \uc18c\ub9ac\ub97c \ub5a0\uc62c\ub9b0\ub2e4. \uc870\uac01\uc758 \uc815\uc9c0\ud55c \uc0c1\ud0dc\uc640 \ud45c\ud604\ud558\ub294 \ud589\ub3d9 \uc0ac\uc774\uc5d0 \ucc28\uc774\uac00 \uc788\ub294 \uc148\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \ub9d0\uc744 \uc678\uce58\ub294\uc9c0 \ub300\uc0ac\ub97c \ubd99\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \ud655\uc778\ud560 \uc218 \uc788\ub294 \uac83\uc740 \ub208\uacfc \uc785, \ubab8\uc758 \ud45c\ud604\uc774\uba70 \uad6c\uccb4\uc801\uc778 \ubc1c\uc5b8\uc740 \ub0a8\uc544 \uc788\uc9c0 \uc54a\ub2e4. \uc18c\ub9ac\uac00 \ub0a0 \uac83 \uac19\ub2e4\ub294 \uac10\uc0c1\uacfc \uc2e4\uc81c\ub85c \ubb34\uc5c7\uc744 \ub9d0\ud588\ub2e4\ub294 \uc774\uc57c\uae30\ub294 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc870\uac01\uc774 \ubcf4\uc5ec \uc8fc\ub294 \ud798\ub9cc\uc73c\ub85c\ub3c4 \ud654\uba74\uc744 \uc624\ub798 \ubc14\ub77c\ubcfc \ub2e8\uc11c\ub294 \ucda9\ubd84\ud558\ub2e4. \uae30\uad00 \uc124\uba85\uc740 \uc774 \uc778\ubb3c\uc774 \ubc14\uc704 \uac19\uc740 \ubc1b\uce68 \uc704\uc5d0\uc11c \ub0b4\ub824\ub2e4\ubcf4\ub294 \uc778\uc0c1\uc744 \uc900\ub2e4\uace0 \uc774\uc57c\uae30\ud55c\ub2e4. \ubb3c\uac74\uc758 \ud06c\uae30\ubfd0 \uc544\ub2c8\ub77c \uad00\ub78c\uc790\uc640\uc758 \ub192\uc774 \ucc28\uc774\ub3c4 \uac10\uc0c1\uc5d0 \ucc38\uc5ec\ud55c\ub2e4. \ub208\ub192\uc774\ub97c \ub9de\ucd94\ub294 \uc791\uc740 \uc870\uac01\uacfc \uace0\uac1c\ub97c \ub4e4\uc5b4 \ub9c8\uc8fc\ud558\ub294 \ud615\uc0c1\uc740 \uc0ac\ub78c\uc758 \ubab8\uc5d0 \ub2e4\ub978 \ubc18\uc751\uc744 \uc904 \uc218 \uc788\ub2e4. \uc5b4\ub514\uc5d0\uc11c \ubcf4\ub294\uc9c0\uac00 \uc791\ud488\uc758 \uc77c\ubd80\uac00 \ub418\ub294 \ub300\ubaa9\uc774\ub2e4. \ubcf8\ubb38\uc758 \uc124\uba85\uc6a9 \uc0bd\ud654\ub294 \uc2e4\uc81c \uc870\uac01\uc758 \uce58\uc218\uc640 \uc804\uc2dc \uc704\uce58\ub97c \uc7ac\ud604\ud55c \uc0ac\uc9c4\uc774 \uc544\ub2c8\ub2e4. \uadf8\ub7ec\ubbc0\ub85c \uc815\ud655\ud55c \ubc1b\uce68 \ub192\uc774\ub97c \uadf8\ub9bc\uc5d0\uc11c \uc7ac\uac70\ub098 \ud604\uc7ac \uc5b4\ub290 \ubb38 \uc55e\uc5d0 \ub193\uc600\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uae30\uad00\uc758 \ud574\uc124\uc5d0\uc11c \ud655\uc778\ud55c \uad00\uacc4\ub97c \ubc14\ud0d5\uc73c\ub85c \uc65c \ub192\uc774\uc640 \ubc29\ud5a5\uc774 \uc911\uc694\ud560 \uc218 \uc788\ub294\uc9c0 \uc0dd\uac01\ud574 \ubcf4\ub294 \uac83\uc774\ub2e4. \uadf8\ub9bc\uc758 \uc0c1\uc0c1\uacfc \uc0ac\uc2e4\uc758 \ubc94\uc704\ub97c \ud568\uaed8 \uc77d\uc73c\uba74 \ub41c\ub2e4. \uc6b0\ub9ac\ub294 \uce5c\uc808\ud568\uc744 \ubd80\ub4dc\ub7ec\uc6b4 \uc5bc\uad74\uacfc \uc27d\uac8c \uc5f0\uacb0\ud55c\ub2e4. \uc218\ud638\uc0c1\uc758 \uc5ed\ud560\uc744 \uc54c\uba74 \uadf8 \uc5f0\uacb0\uc774 \uc720\uc77c\ud55c \uae30\uc900\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc744 \ub290\ub084 \uc218 \uc788\ub2e4. \ub204\uad70\uac00\ub97c \uc9c0\ud0a4\uae30 \uc704\ud574 \ubc14\uae65\uc744 \uacbd\uacc4\ud558\ub294 \ubaa8\uc2b5\uc740 \uc548\ucabd\uc758 \uc0ac\ub78c\uc5d0\uac8c \ub2e4\ub978 \uc758\ubbf8\ub85c \ub2e4\uac00\uc62c \uc218 \uc788\ub2e4. \ud558\ub098\uc758 \uac10\uc815 \ub2e8\uc5b4\ubcf4\ub2e4 \uad00\uacc4\ub97c \ubcf4\ub294 \uc77c\uc774 \ud574\uc11d\uc758 \ud3ed\uc744 \ub113\ud78c\ub2e4. \ub2e4\ub9cc \ubb34\uc11c\uc6b4 \ud615\uc0c1\uc774\uba74 \uc5b8\uc81c\ub098 \uc88b\uc740 \ubcf4\ud638\uc790\ub77c\ub294 \uc0c8\ub85c\uc6b4 \uaddc\uce59\uc744 \ub9cc\ub4e4 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \uac01\uac01\uc758 \uc804\ud1b5\uacfc \uc791\ud488 \uc124\uba85\uc744 \ub530\ub77c \ud655\uc778\ud560 \ubd80\ubd84\uc774 \uc788\ub2e4. \uc774 \uc870\uac01\uc5d0\uc11c\ub294 \uc0ac\ucc30\uc744 \uc9c0\ud0a8\ub2e4\ub294 \uc5ed\ud560\uc774 \ud45c\uc815\uc744 \uc77d\ub294 \uc911\uc694\ud55c \uc5f4\uc1e0\ub2e4. \ucc98\uc74c\uc758 \ub180\ub77c\uc6c0\uc744 \ubc84\ub9ac\uc9c0 \uc54a\uace0 \uadf8 \ub180\ub77c\uc6c0\uc774 \uc65c \uc0dd\uacbc\ub294\uc9c0 \ub354 \uc0b4\ud53c\ub294 \ubc29\uc2dd\uc73c\ub85c \uac10\uc0c1\uc744 \uc774\uc5b4 \uac08 \uc218 \uc788\ub2e4. \uae30\uad00 \uc790\ub8cc\ub294 \uc6d0\ub798 \ubc29\ubb38\uac1d\uc774 \ub290\uaf08\uc744 \ubc18\uc751\uc744 \uac00\ub2a5\uc131\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \uc2e4\uc81c \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uac19\uc740 \ub450\ub824\uc6c0\uc774\ub098 \uc548\ub3c4\uac10\uc744 \ub290\uaf08\ub2e4\uace0 \uc815\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ub798\ub41c \uc870\uac01 \uc55e\uc5d0\uc11c\ub3c4 \ubcf4\ub294 \uc0ac\ub78c\uc758 \uacbd\ud5d8\uc740 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uadf8\ub7fc\uc5d0\ub3c4 \ub204\uad6c\ub97c \uc9c0\ud0a4\uace0 \ub204\uad6c\ub97c \ud5a5\ud574 \ud798\uc744 \ubcf4\uc774\ub294\uac00\ub77c\ub294 \uc9c8\ubb38\uc740 \uc4f8\ubaa8\uac00 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \ubb34\uc11c\uc6b4 \ud45c\uc815\uc758 \uc218\ud638\uc0c1\uc744 \ub9cc\ub098\uba74 \uc5bc\uad74\uc744 \ud53c\ud558\uae30 \uc804\uc5d0 \uc5ed\ud560\uc744 \uc0dd\uac01\ud574 \ubcf4\uc790. \ub0af\uc124\ub358 \ud45c\uc815\uc774 \ub2e4\ub978 \ub73b\uc73c\ub85c \ub2e4\uac00\uc624\ub294 \uc21c\uac04\uc774 \uc788\uc744 \uc218 \uc788\ub2e4."}, {"id": "japan-phoenix-wood-panels", "title": "\uc77c\ubcf8\uc758 \ub098\ubb34 \uc7a5\uc2dd\uc740 \uad00\ub78c\uc11d \uc544\ub798\uc5d0\uc11c \ubc1c\uacac\ub410\ub2e4", "summary": "\uac74\ubb3c\uc774 \uc0ac\ub77c\uc9c4 \ub4a4\uc5d0\ub3c4 \ub0a8\uc558\ub358 \uc77c\ubcf8\uc2dd \uac74\ucd95 \uc7a5\uc2dd\uc758 \uc774\ub3d9\uc744 \ub530\ub77c\uac11\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uac74\ucd95", "categories": ["arts"], "url": "stories/japan-phoenix-wood-panels/index.html", "image": "../media/japan-phoenix-wood-panels.jpg", "alt": "\uc77c\ubcf8\uc758 \ub098\ubb34 \uc7a5\uc2dd\uc740 \uad00\ub78c\uc11d \uc544\ub798\uc5d0\uc11c \ubc1c\uacac\ub410\ub2e4\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\uc77c\ubcf8\uc758 \ub098\ubb34 \uc7a5\uc2dd\uc740 \uad00\ub78c\uc11d \uc544\ub798\uc5d0\uc11c \ubc1c\uacac\ub410\ub2e4 \ubc15\ub78c\ud68c \uac74\ubb3c\uc5d0\uc11c \ubbf8\uc220\uad00\uc73c\ub85c \uc774\uc5b4\uc9c4 \ub124 \uc870\uac01 \uac74\ubb3c\uc774 \uc0ac\ub77c\uc9c4 \ub4a4\uc5d0\ub3c4 \ub0a8\uc558\ub358 \uc77c\ubcf8\uc2dd \uac74\ucd95 \uc7a5\uc2dd\uc758 \uc774\ub3d9\uc744 \ub530\ub77c\uac11\ub2c8\ub2e4. \uac74\ucd95 \ubb38\ud654\uc640 \uc608\uc220 \uc6b4\ub3d9\uc7a5 \uad00\ub78c\uc11d \uc544\ub798\uc5d0\uc11c \uc77c\ubcf8 \uac74\ucd95 \uc7a5\uc2dd\uc774 \ub098\uc628\ub2e4\uba74 \uc870\uae08 \uc5c9\ub6b1\ud558\uac8c \ub4e4\ub9b0\ub2e4. \ud558\uc9c0\ub9cc \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc774 \uc18c\uac1c\ud558\ub294 \ub124 \uc810\uc758 \ubaa9\uc870 \uc7a5\uc2dd\uc5d0\ub294 \uadf8\ub7f0 \uc2dc\uac04\uc774 \uc788\uc5c8\ub2e4. \ud55c\ub54c \ubc15\ub78c\ud68c \uac74\ubb3c\uc5d0 \ub2ec\ub838\ub358 \ubb3c\uac74\ub4e4\uc774\ub2e4. \uc774 \uc7a5\uc2dd\uc740 \ub780\ub9c8\ub77c\uace0 \ubd80\ub974\ub294 \ubaa9\uc870 \uac74\ucd95 \ubd80\uc7ac\ub2e4. \ubb38 \uc704\ucabd \uacf5\uac04\uc5d0 \ub193\uc774\ub294 \uc7a5\uc2dd\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \ucc98\uc74c\ubd80\ud130 \uc720\ub9ac\uc7a5 \uc548\uc5d0 \uc804\uc2dc\ud558\ub824\uace0 \ub9cc\ub4e0 \uc870\uac01\uc740 \uc544\ub2c8\uc5c8\ub2e4. 1893\ub144 \uc2dc\uce74\uace0 \ub9cc\uad6d\ubc15\ub78c\ud68c\uc5d0\uc11c \uc77c\ubcf8\uc740 \ud53c\ub2c9\uc2a4 \ud640\uc774\ub77c\ub294 \uad6d\uac00 \uc804\uc2dc\uad00\uc744 \uc138\uc6e0\ub2e4. \ubbf8\uc220\uad00 \uc124\uba85\uc740 \uc774 \uac74\ubb3c\uc774 \uad50\ud1a0 \uadfc\uad50\uc758 11\uc138\uae30 \uc0ac\ucc30\uc744 \ubcf8\ub5b4\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ub2e4\ub978 \uc804\uc2dc\uad00\ub4e4\uacfc\ub294 \uad6c\ubcc4\ub418\ub294 \uc77c\ubcf8\uc2dd \uac74\ubb3c\uc774\uc5c8\ub2e4. \ub124 \uc810\uc758 \ubaa9\uc870 \uc7a5\uc2dd\ub3c4 \uadf8 \uc804\uc2dc\uad00\uc744 \uc704\ud574 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4. \uac74\ubb3c\uc758 \uc77c\ubd80\uc600\uc73c\ub2c8 \uc0ac\ub78c\ub4e4\uc740 \uc870\uac01 \ud558\ub098\ub97c \ub530\ub85c \ubcf4\uae30\ubcf4\ub2e4 \uadf8 \uc544\ub798\ub97c \uc9c0\ub098\uac00\uba70 \uacf5\uac04 \uc804\uccb4\ub97c \ub9cc\ub0ac\uc744 \uac83\uc774\ub2e4. \uc774\uac83\uc740 \uac74\ucd95 \ubd80\uc7ac\uc758 \uc790\ub9ac\ub97c \ub5a0\uc62c\ub824 \ubcf4\ub294 \ubc29\uc2dd\uc774\ub2e4. \ubc15\ub78c\ud68c\uac00 \ub05d\ub09c \ub4a4 \uc77c\ubcf8 \uc815\ubd80\ub294 \uc804\uc2dc\uad00\uc744 \uc2dc\uce74\uace0\uc2dc\uc5d0 \uae30\uc99d\ud588\ub2e4. \uadf8\ub7ec\ub098 \uac74\ubb3c\uc740 1945\ub144\uacfc 1946\ub144\uc758 \ud654\uc7ac\ub85c \ud6fc\uc190\ub418\uc5b4 \ucca0\uac70\ub418\uc5c8\ub2e4\uace0 \ud55c\ub2e4. \ubbf8\uc220\uad00\uc740 \ub124 \uc7a5\uc2dd\uc774 \ub0a8\uc740 \ubd80\uc7ac\uc600\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8 \ub4a4 \uc774 \ubb3c\uac74\ub4e4\uc740 \uc194\uc800 \ud544\ub4dc\uc758 \uad00\ub78c\uc11d \uc544\ub798\uc5d0 \ubcf4\uad00\ub418\uc5c8\uace0, \uc78a\ud78c \ucc44 \uc9c0\ub0b4\ub2e4\uac00 1973\ub144\uc5d0 \ubc1c\uacac\ub418\uc5c8\ub2e4. \uac74\ucd95 \uc7a5\uc2dd\uc758 \ub2e4\uc74c \uc8fc\uc18c\uac00 \uc0ac\ucc30\ub3c4 \ubc15\ubb3c\uad00\ub3c4 \uc544\ub2cc \uacbd\uae30\uc7a5\uc774\uc5c8\ub2e4\ub294 \uc810\uc774 \ub73b\ubc16\uc774\ub2e4. \ub780\ub9c8\ub294 \uac74\ubb3c \uc704\ucabd\uc758 \uac00\ub85c \uacf5\uac04\uc5d0 \uc4f0\uc774\ub294 \uc7a5\uc2dd \ubd80\uc7ac\ub2e4. \uc774 \ub124 \uc810\uc740 \ubd88\uad50 \uc870\uac01\uac00 \ub2e4\uce74\ubb34\ub77c \uace0\uc6b4\uc774 \ubc15\ub78c\ud68c \uc77c\ubcf8\uad00\uc744 \uc704\ud574 \ub9cc\ub4e0 \uac83\uc73c\ub85c \ubbf8\uc220\uad00\uc740 \uc18c\uac1c\ud55c\ub2e4. \uc791\uc740 \uc218\uc9d1\ud488\uc744 \ub098\uc911\uc5d0 \uac74\ubb3c\uc5d0 \ub193\uc740 \uac83\uc774 \uc544\ub2c8\ub77c \uac74\ucd95 \uacf5\uac04\uacfc \ud568\uaed8 \ubcf4\uc774\ub3c4\ub85d \ub9c8\ub828\ub41c \ubb3c\uac74\uc774\uc5c8\ub2e4. \uc804\uc2dc\uad00\uc758 \uc804\uccb4 \ubaa8\uc2b5\uacfc \uc870\uac01\uc758 \uc138\ubd80\ub97c \uc5f0\uacb0\ud574 \ubcfc \uc774\uc720\uac00 \uc788\ub2e4. \ubc15\ub78c\ud68c\uc5d0\uc11c \uad6d\uac00 \uc804\uc2dc\uad00\uc740 \ubb3c\uac74\ub9cc \ubcf4\uc5ec \uc8fc\ub294 \uacf3\uc774 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uac74\ubb3c \uc548\uc5d0\uc11c \uadf8 \ubb3c\uac74\uc744 \ub9cc\ub098\uac8c \ud560\uc9c0\ub3c4 \ud55c \ub098\ub77c\ub97c \ud45c\ud604\ud558\ub294 \uc120\ud0dd\uc774 \ub41c\ub2e4. \uad50\ud1a0 \uadfc\uad50 \uc0ac\ucc30\uc744 \ubcf8\ub72c \uc77c\ubcf8\uad00\uc740 \ub2f9\uc2dc \ub2e4\ub978 \uc804\uc2dc\uad00\ub4e4\uacfc \uad6c\ubcc4\ub418\ub294 \ubaa8\uc2b5\uc744 \uac00\uc84c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc774 \uac74\ubb3c \ud558\ub098\uac00 \uc77c\ubcf8 \uac74\ucd95\uc758 \ubaa8\ub4e0 \uc804\ud1b5\uc744 \ub300\ud45c\ud55c\ub2e4\uace0 \ub113\ud600 \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud654\uc7ac \ub4a4 \uc804\uc2dc\uad00\uc774 \ucca0\uac70\ub418\uc5c8\ub2e4\ub294 \ub9d0\ub9cc \ub4e4\uc73c\uba74 \uadf8 \uc5ed\uc0ac\ub3c4 \ubaa8\ub450 \ub05d\ub0ac\ub2e4\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \ub124 \ubaa9\uc870 \ubd80\uc7ac\ub294 \ub0a8\uc544 \ub2e4\ub978 \uc7a5\uc18c\ub85c \uc62e\uaca8\uc84c\ub2e4. \uc804\uccb4 \uac74\ubb3c\uc758 \uc6b4\uba85\uacfc \uc77c\ubd80\ub97c \uc774\ub8e8\ub358 \ubb3c\uac74\uc758 \uc6b4\uba85\uc774 \uac08\ub77c\uc9c4 \uac83\uc774\ub2e4. \uc720\ubb3c\uc758 \uc0dd\uc560\uc5d0\ub294 \uc81c\uc791\ubfd0 \uc544\ub2c8\ub77c \ubd84\ub9ac\uc640 \uc774\ub3d9, \ubcf4\uad00\uc758 \uc2dc\uac04\uc774 \ud3ec\ud568\ub41c\ub2e4. \uc194\uc800 \ud544\ub4dc\ub77c\ub294 \uc0c8 \uc7a5\uc18c\ub294 \ucc98\uc74c\uc758 \uc4f0\uc784\uacfc \ud06c\uac8c \ub2e4\ub974\ub2e4. \uc0ac\ucc30\uc744 \ubcf8\ub72c \uc804\uc2dc\uad00\uc758 \uc7a5\uc2dd\uc774 \uacbd\uae30\uc7a5 \uad00\ub78c\uc11d \uc544\ub798\uc5d0 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uacf5\uac04\uc758 \uc774\ub984\ub9cc\uc73c\ub85c \ubb34\uc5c7\uc774 \ub4e4\uc5b4 \uc788\ub294\uc9c0 \uc9d0\uc791\ud560 \uc218 \uc5c6\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub2e4\ub9cc \uc78a\ud600 \uc788\uc5c8\ub2e4\ub294 \uc124\uba85\uc5d0\uc11c \ub204\uac00 \uc5b8\uc81c \uc5b4\ub5a4 \uc2e4\uc218\ub97c \ud588\ub294\uc9c0\uae4c\uc9c0 \uc0c8 \uc774\uc57c\uae30\ub85c \ub9cc\ub4e4\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud655\uc778\ud55c \uc774\ub3d9\uc758 \ud070 \uacbd\ub85c\uac00 \uc911\uc2ec\uc774\ub2e4. 1973\ub144 \ubc1c\uacac\ud55c \ub4a4 \ub450 \uc810\uc740 \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc73c\ub85c, \ub098\uba38\uc9c0 \ub450 \uc810\uc740 \uc77c\ub9ac\ub178\uc774\ub300\ud559\uad50 \uc2dc\uce74\uace0 \ucea0\ud37c\uc2a4\ub85c \ub098\ub258\uc5b4 \uac14\ub2e4. \uc6d0\ub798 \uac19\uc740 \uac74\ubb3c\uc5d0 \uc788\ub358 \ubb3c\uac74\uc774\ub77c\ub3c4 \uad00\ub9ac\ud558\ub294 \uae30\uad00\uc740 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \uac19\uc740 \uc774\ub984\uc758 \ub124 \uc810\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uac19\uc740 \uc7a5\uc18c\uc5d0\uc11c \ubcfc \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ubcc4\uac1c\uc600\ub2e4. \uc774\ud6c4 \ub300\ud559 \uce21\uc5d0\uc11c \ubcf4\uc874 \uc0c1\ud0dc\ub97c \uc5fc\ub824\ud558\uba74\uc11c \uc18c\uc7a5\ud488\uc744 \ubbf8\uc220\uad00\uc73c\ub85c \ub118\uacbc\uace0 \ub124 \uc810\uc744 \ud568\uaed8 \ub3cc\ubcfc \uc870\uac74\uc774 \ub9c8\ub828\ub418\uc5c8\ub2e4\uace0 \uae00\uc740 \uc124\uba85\ud55c\ub2e4. \ubaa8\uc73c\ub294 \uc77c\uc5d0\ub294 \ub300\ud45c \uc791\ud488\uc744 \ub9ce\uc774 \uac16\ucd94\ub824\ub294 \ubaa9\uc801\ub9cc \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \ud568\uaed8 \ubcf4\uc874\ud558\uace0 \uad00\uacc4\ub97c \uc0b4\ud3b4\ubcfc \uc774\uc720\ub3c4 \uc788\ub2e4. \ubc1c\uacac\ud55c \uc21c\uac04 \uc774\ud6c4\uc5d0 \uc5b4\ub5a4 \ud310\ub2e8\uc744 \ud588\ub294\uc9c0\uac00 \ubb3c\uac74\uc758 \ub2e4\uc74c \uc2dc\uac04\uc744 \ub9cc\ub4e0\ub2e4. \uae30\uad00 \uae00\uc740 \uc77c\ubcf8 \ubbf8\uc220 \uc804\uc2dc\uc2e4\uc758 \uac1c\ud3b8\uc744 \uc900\ube44\ud558\ub358 \uc2dc\uc810\uc5d0 \uc4f0\uc600\ub2e4. \uadf8\ub798\uc11c \uadf8\ub54c\uc758 \ubcf4\uc874\uacfc \uc804\uc2dc \uacc4\ud68d\uc744 \ud604\uc7ac\uc758 \uad00\ub78c \uc815\ubcf4\ub85c \uadf8\ub300\ub85c \uc0ac\uc6a9\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc624\ub798\ub41c \uac8c\uc2dc\uae00\uc774 \uc54c\ub824 \uc8fc\ub294 \uc5ed\uc0ac\uc640 \uc624\ub298 \ubb38\uc744 \uc5ec\ub294 \uc804\uc2dc\uc2e4\uc740 \uad6c\ubd84\ud574\uc11c \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uc791\ud488\uc774 \uc5b4\ub514\ub97c \uac70\uccd0 \uc654\ub294\uc9c0 \uc77d\ub294 \uc790\ub8cc\uc640 \ubc29\ubb38 \uc548\ub0b4\ub294 \uc5ed\ud560\uc774 \ub2e4\ub974\ub2e4. \uc774 \uc774\ub825\uc744 \uc54c\uace0 \uc2e4\uc81c \ubd80\uc7ac\ub97c \ub9cc\ub09c\ub2e4\uba74 \uba3c\uc800 \uc870\uac01\uc758 \ubaa8\uc2b5\uc5d0, \ub2e4\uc74c\uc5d0\ub294 \ubcf8\ub798 \uac74\ubb3c\uc5d0\uc11c \ub193\uc600\ub358 \uc790\ub9ac\ub85c \uad00\uc2ec\uc744 \uc62e\uaca8 \ubcfc \uc218 \uc788\ub2e4. \uac74\ubb3c\uc5d0\uc11c \ub5a8\uc5b4\uc838 \ub098\uc628 \uc7a5\uc2dd\ub3c4 \uc81c\uc791 \uc7a5\uc18c\uc640 \ubc15\ub78c\ud68c, \uacbd\uae30\uc7a5\uc758 \ucc3d\uace0\uc640 \ubc15\ubb3c\uad00\uc744 \uc774\uc5b4 \uc900\ub2e4. \uc791\uc740 \ubaa9\uc870 \uc870\uac01\uc5d0 \uc2dc\uce74\uace0\uc758 \ub3c4\uc2dc\uc0ac\uc640 \uc77c\ubcf8\uc758 \ubbf8\uc220\uc774 \ud568\uaed8 \ub0a8\uc544 \uc788\ub294 \uc148\uc774\ub2e4. \ubc1c\uacac \ub4a4\uc5d0\ub294 \ub450 \uc810\uc529 \ub2e4\ub978 \uae30\uad00\uc73c\ub85c \ub098\ub258\uc5c8\ub2e4\uac00 \ub124 \uc810 \ubaa8\ub450 \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc73c\ub85c \ubaa8\uc600\ub2e4. \uae30\uad00\uc774 \ub0a8\uae34 \uae00\uc740 \uc774 \uc7a5\uc2dd\ub4e4\uc744 \ud568\uaed8 \ubcf4\uc874\ud558\uace0 \ubcf4\uc5ec \uc8fc\ub824\ub358 \uacfc\uc815\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc624\ub798\uc804\uc758 \uc804\uc2dc \uc900\ube44\ub97c \uae30\ub85d\ud55c \uae00\uc774\ubbc0\ub85c \uc9c0\uae08\uc758 \uc804\uc2dc\uc2e4 \uc548\ub0b4\uc640\ub294 \uad6c\ubd84\ud574\uc11c \uc77d\uc73c\uba74 \ub41c\ub2e4. \uac74\ubb3c\uc740 \uc0ac\ub77c\uc838\ub3c4 \uadf8 \uc77c\ubd80\uac00 \ub2e4\ub978 \uc2dc\uac04\uc744 \uc0b4\uc544\uac08 \uc218 \uc788\ub2e4. \uc77c\ubcf8\uc2dd \uc804\uc2dc\uad00\uacfc \ubbf8\uad6d\uc758 \uc6b4\ub3d9\uc7a5, \ubbf8\uc220\uad00\uc744 \uc774\uc5b4 \uc8fc\ub294 \uac83\uc740 \ub124 \uc870\uac01\uc758 \ub098\ubb34\uc600\ub2e4. \ubb3c\uac74\uc758 \uc774\ub825\uc740 \ub73b\ubc16\uc758 \uc7a5\uc18c\uc5d0\uc11c \ud55c \uc7a5 \ub354 \ub298\uc5b4\ub098\uae30\ub3c4 \ud55c\ub2e4."}, {"id": "japanese-theatre-revolving-stage-and-labor", "title": "\uc77c\ubcf8\uc758 \ud68c\uc804\ubb34\ub300 \u2014 \uc9d1 \ud55c \ucc44\uac00 \ub3cc\uc544\uac00\uba74 \ub2e4\uc74c \uc7a5\uba74\uc774 \uc5f4\ub9b0\ub2e4", "summary": "19\uc138\uae30 \ub9d0 \uae30\ub85d\uc758 \ud558\ub098\ubbf8\uce58\uc640 \ud68c\uc804 \ubc14\ub2e5, \ubcf4\uc774\uc9c0 \uc54a\ub294 \ub178\ub3d9\uc73c\ub85c \uc7a5\uba74 \uc804\ud658\uc758 \uc5ed\uc0ac\ub97c \ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uac74\ucd95", "categories": ["arts"], "url": "stories/japanese-theatre-revolving-stage-and-labor/index.html", "image": "../media/japanese-theatre-revolving-stage-and-labor.png", "alt": "\uc9d1\uc758 \ubb34\ub300 \uc7a5\uce58\uac00 \ud68c\uc804\ud558\ub294 \uc77c\ubcf8 \uadf9\uc7a5\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uc77c\ubcf8\uc758 \ud68c\uc804\ubb34\ub300 \u2014 \uc9d1 \ud55c \ucc44\uac00 \ub3cc\uc544\uac00\uba74 \ub2e4\uc74c \uc7a5\uba74\uc774 \uc5f4\ub9b0\ub2e4 \uc2dc\ub4dc\ubaa8\uc5b4\uc758 \uad00\ucc30\ub85c \uc77d\ub294 \ubc30\uc6b0\uc758 \uae38\uacfc \ubb34\ub300 \uc544\ub798 \ud611\uc5c5 19\uc138\uae30 \ub9d0 \uae30\ub85d\uc758 \ud558\ub098\ubbf8\uce58\uc640 \ud68c\uc804 \ubc14\ub2e5, \ubcf4\uc774\uc9c0 \uc54a\ub294 \ub178\ub3d9\uc73c\ub85c \uc7a5\uba74 \uc804\ud658\uc758 \uc5ed\uc0ac\ub97c \ubd05\ub2c8\ub2e4. \uac74\ucd95 \ubb38\ud654\uc640 \uc608\uc220 \uc5f0\uadf9\uc758 \uc7a5\uba74\uc774 \ubc14\ub014 \ub54c\ub9c8\ub2e4 \ub9c9\uc744 \ub0b4\ub9ac\uace0 \uac00\uad6c\ub97c \uc62e\uaca8\uc57c \ud560\uae4c. \uc77c\ubcf8 \uadf9\uc7a5\uc758 \ud68c\uc804\ubb34\ub300\ub294 \ubb34\ub300\uc758 \uc77c\ubd80\ub97c \ub3cc\ub824 \ub2e4\ub978 \uacf5\uac04\uc744 \ubcf4\uc5ec \uc8fc\uc5c8\ub2e4. 19\uc138\uae30 \ub9d0 \uc5ec\ud589\uc790 \uc5d8\ub77c\uc774\uc790 \uc2dc\ub4dc\ubaa8\uc5b4\uc758 \uad00\ucc30\uc744 \ub530\ub77c\uac00\uba74, \ub180\ub77c\uc6b4 \ubb34\ub300 \ud6a8\uacfc \ub4a4\uc5d0 \ubc14\ub2e5 \uc544\ub798\uc5d0\uc11c \uc77c\ud558\ub358 \uc0ac\ub78c\ub4e4\uacfc \uac1d\uc11d\uc758 \ud2b9\ubcc4\ud55c \uad6c\uc870\uac00 \ud568\uaed8 \ub098\ud0c0\ub09c\ub2e4. \u300e\uc77c\ubcf8\uc758 \uc778\ub825\uac70 \uc5ec\ud589\u300f\uc740 \ub2f9\uc2dc \uc678\uad6d \ubc29\ubb38\uac1d\uc774 \uacbd\ud5d8\ud55c \uc0dd\ud65c\uacfc \uacf5\uc5f0\uc744 \uae30\ub85d\ud55c \ucc45\uc774\ub2e4. \uc5ec\uae30\uc11c \ubb18\uc0ac\ud558\ub294 \uadf9\uc7a5\uc744 \uc77c\ubcf8\uc758 \ubaa8\ub4e0 \uc2dc\ub300\uc640 \ubaa8\ub4e0 \uacf5\uc5f0\uc7a5\uc5d0 \ub611\uac19\uc774 \uc801\uc6a9\ud560 \uc218\ub294 \uc5c6\ub2e4. \uae00\uc4f4\uc774\uc758 \uac10\ud0c4\uacfc \ube44\uad50\uc5d0\ub294 \uadf8\uac00 \uc775\uc219\ud588\ub358 \uc11c\uc591 \uacf5\uc5f0\uc758 \uae30\uc900\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \uadf8 \uc810\uc744 \uad6c\ubd84\ud558\uba74 \uae30\ub85d\uc740 \uc720\uc6a9\ud55c \ub2e8\uc11c\uac00 \ub41c\ub2e4. \ubb34\ub300\uac00 \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc600\ub294\uc9c0, \ubc30\uc6b0\uac00 \uc5b4\ub290 \uae38\ub85c \ub098\ud0c0\ub0ac\ub294\uc9c0 \uac19\uc740 \uad6c\uccb4\uc801\uc778 \ubb18\uc0ac\ub97c \uc0b4\ud544 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc624\ub298\uc758 \uadf9\uc7a5\uc744 \uc124\uba85\ud558\ub294 \ucd5c\uc2e0 \uc548\ub0b4\uc11c\uac00 \uc544\ub2c8\ub77c \ud55c \uc2dc\ub300 \uad00\uac1d\uc774 \ubcf8 \uc7a5\uba74\uc758 \uc99d\uc5b8\uc73c\ub85c \uc77d\ub294 \uac83\uc774\ub2e4. \uc2dc\ub4dc\ubaa8\uc5b4\ub294 \ubc30\uc6b0\ub4e4\uc774 \uac1d\uc11d\uc744 \uc9c0\ub098\ub294 \ub192\uc778 \uae38\uc744 \ub530\ub77c \ub4e4\uc5b4\uc624\ub294 \ubaa8\uc2b5\uc744 \uae30\ub85d\ud588\ub2e4. \ud558\ub098\ubbf8\uce58\ub77c\uace0 \ubd88\ub9ac\ub294 \ud1b5\ub85c\ub2e4. \ubc30\uc6b0\uac00 \uc5b8\uc81c\ub098 \ubb34\ub300 \uc606\uc758 \ubb38\uc5d0\uc11c\ub9cc \ub098\uc628\ub2e4\uace0 \uc0dd\uac01\ud558\ub358 \uad00\uac1d\uc5d0\uac8c\ub294, \uc790\uae30 \uac00\uae4c\uc774\uc5d0\uc11c \uc7a5\uba74\uc774 \uc2dc\uc791\ub418\ub294 \uacbd\ud5d8\uc774 \uc0c8\ub85c\uc6e0\uc744 \uac83\uc774\ub2e4. \uc774 \uae38\uc740 \ubc30\uc6b0\uc758 \uc774\ub3d9\uc744 \uac1d\uc11d\uacfc \uc5f0\uacb0\ud55c\ub2e4. \uad00\uac1d\uc740 \uba40\ub9ac \uc788\ub294 \ubb34\ub300\ub9cc \ubcf4\ub2e4\uac00 \uac00\uae4c\uc774 \ub2e4\uac00\uc624\ub294 \uc778\ubb3c\uc744 \ub530\ub77c \uc2dc\uc120\uc744 \ub3cc\ub9b4 \uc218 \uc788\ub2e4. \uacf5\uc5f0\uc758 \uacf5\uac04\uc774 \ubb34\ub300 \uc815\uba74\uc758 \uc0ac\uac01\ud615 \uc548\uc5d0\ub9cc \uac07\ud788\uc9c0 \uc54a\ub294\ub2e4. \uac19\uc740 \uc774\uc57c\uae30\ub3c4 \ubc30\uc6b0\uac00 \uc5b4\ub514\uc5d0\uc11c \ucd9c\ud604\ud558\ub294\uc9c0\uc5d0 \ub530\ub77c \ub2e4\ub974\uac8c \ub290\uaef4\uc9c4\ub2e4. \ud68c\uc804\ubb34\ub300\uc5d0\uc11c\ub294 \ubc14\ub2e5 \uc77c\ubd80\uac00 \ud070 \uc6d0\ud615 \uad6c\uc870\ub97c \uc774\ub8ec\ub2e4. \uadf8 \uc704\uc5d0 \uc9d1\uc774\ub098 \ub2e4\ub978 \uc7a5\uce58\ub97c \ubc30\uce58\ud558\uace0 \uc6d0\uc744 \ub3cc\ub9ac\uba74, \uc870\uae08 \uc804\uc5d0\ub294 \ubcf4\uc774\uc9c0 \uc54a\ub358 \uba74\uc774 \uad00\uac1d \ucabd\uc73c\ub85c \uc628\ub2e4. \ubb34\ub300 \uc704\uc758 \ubb3c\uac74\uc744 \uc804\ubd80 \uce58\uc6b0\ub294 \ub300\uc2e0 \ubc14\ub77c\ubcf4\ub294 \ubc29\ud5a5\uc744 \ubc14\uafb8\ub294 \ubc29\ubc95\uc774\ub2e4. \uae30\ub85d\uc5d0\ub294 \uc9d1\uc774 \ub3cc\uba74\uc11c \ub2e4\ub978 \ubc29\uc774\ub098 \uc815\uc6d0\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ubaa8\uc2b5\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \uac19\uc740 \uc9d1\uc758 \ubc14\uae65\uacfc \uc548\uc744 \uc774\uc5b4 \ubcf4\uc5ec \uc904 \uc218\ub3c4 \uc788\ub2e4. \uad00\uac1d\uc740 \uc7a5\uba74\uc774 \ub04a\uc5b4\uc838 \uc0c8\ub85c \uc2dc\uc791\ub418\uae30\ubcf4\ub2e4 \uc11c\ub85c \ub2e4\ub978 \uacf5\uac04\uc774 \uc774\uc5b4\uc9c4\ub2e4\uace0 \ub290\ub084 \uc218 \uc788\ub2e4. \uae30\uc220\uc774 \uc774\uc57c\uae30\uc758 \uc2dc\uac04\uc744 \uc870\uc9c1\ud558\ub294 \uc148\uc774\ub2e4. \uc2dc\ub4dc\ubaa8\uc5b4\uac00 \ubcf8 \uad6c\uc870\uc5d0\uc11c\ub294 \ubc14\ub2e5 \uc544\ub798\uc758 \uc0ac\ub78c\ub4e4\uc774 \ub3cc\ucd9c\ub41c \ub9c9\ub300\ub97c \ubc00\uc5b4 \ubb34\ub300\ub97c \ub3cc\ub838\ub2e4. \ub208\uc55e\uc758 \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \ubcc0\ud654\ub294 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uacf3\uc5d0\uc11c \uc5ec\ub7ec \ubab8\uc774 \ud798\uc744 \ub9de\ucd98 \uacb0\uacfc\uc600\ub2e4. \uc7a5\uba74 \uc804\ud658\uc758 \ub180\ub77c\uc6c0\uacfc \uc791\uc5c5\uc758 \uc218\uace0\uac00 \uc11c\ub85c \ub2e4\ub978 \uce35\uc5d0 \ub193\uc5ec \uc788\uc5c8\ub2e4. \ube60\ub974\uae30\uc640 \uba48\ucd9c \uc704\uce58\ub97c \ub9de\ucd94\ub294 \uc77c\ub3c4 \uc911\uc694\ud558\ub2e4. \uae30\ub85d\uc5d0\ub294 \ub108\ubb34 \ube68\ub9ac \ub3cc\uc544 \ubc30\uc6b0\uac00 \ub9d0\ud558\ub294 \ub3c4\uc911 \uc0ac\ub77c\uc9c0\ub294 \uc6b0\uc2a4\uc6b4 \uc0c1\ud669\ub3c4 \ub098\uc628\ub2e4. \uc7a5\uce58\ub294 \uc874\uc7ac\ud558\uae30\ub9cc \ud558\uba74 \uc800\uc808\ub85c \uc644\ubcbd\ud558\uac8c \uc791\ub3d9\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc5f0\uae30\uc640 \uc870\uc791\uc758 \ud638\ud761\uc774 \ub9de\uc544\uc57c \ud6a8\uacfc\uac00 \uc774\uc57c\uae30 \uc548\uc5d0 \ub4e4\uc5b4\uac04\ub2e4. \ubb34\ub300\ub97c \uc6c0\uc9c1\uc774\ub294 \uc2dc\uac04\uc740 \ubc30\uc6b0\uc758 \ub300\uc0ac\uc640\ub3c4 \uc5f0\uacb0\ub41c\ub2e4. \ub2e4\ub978 \ubc29\uc774 \ub4dc\ub7ec\ub098\ub294 \ub3d9\uc548 \ub9d0\uc744 \uc774\uc5b4 \uac08\uc9c0, \uc774\ub3d9\uc744 \uae30\ub2e4\ub9b4\uc9c0\uc5d0 \ub530\ub77c \uad00\uac1d\uc774 \ub290\ub07c\ub294 \uc18d\ub3c4\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uc7a5\uba74 \uc804\ud658\uc740 \ub300\ubcf8 \ubc16\uc758 \ube48 \uc2dc\uac04\uc774 \uc544\ub2c8\ub77c \uacf5\uc5f0\uc774 \uc2dc\uac04\uc744 \uc4f0\ub294 \uad6c\uccb4\uc801\uc778 \ubc29\uc2dd\uc774\ub2e4. \ubc14\ub2e5 \uc544\ub798\uc758 \uc0ac\ub78c\uc740 \uc55e\uc5d0\uc11c \uc5f0\uae30\ud558\ub294 \ubc30\uc6b0\ub97c \uad00\uac1d\uacfc \uac19\uc740 \uc790\ub9ac\uc5d0\uc11c \ubcf4\uc9c0 \ubabb\ud55c\ub2e4. \uadf8\ub798\uc11c \uc2e0\ud638\ub97c \ub4e3\uace0 \ub9e1\uc740 \uc77c\uc744 \ub9de\ucd94\ub294 \uad00\uacc4\uac00 \uc911\uc694\ud558\ub2e4. \uacf5\uc5f0\uc758 \uc815\ud655\ud568\uc740 \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uc804\uccb4\ub97c \ub0b4\ub824\ub2e4\ubcf4\uc544\uc11c\uac00 \uc544\ub2c8\ub77c \uc11c\ub85c \ub2e4\ub978 \uc790\ub9ac\uc758 \uc77c\uc744 \uc5f0\uacb0\ud574\uc11c \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4. \uacf5\uac04\uc758 \uad6c\ud68d\uc774 \ud611\uc5c5\uc758 \uc870\uac74\uc774 \ub41c \uc148\uc774\ub2e4. \ub2f9\uc2dc \ubb34\ub300\uc758 \uc815\uc6d0\uacfc \uc232\uc5d0\ub294 \ud654\ubd84\uc758 \ub098\ubb34\ub098 \uc62e\uaca8 \uc2ec\uc744 \uc2dd\ubb3c\ub3c4 \uc0ac\uc6a9\ub418\uc5c8\ub2e4\uace0 \ud55c\ub2e4. \uadf8\ub824\uc9c4 \ubc30\uacbd\uacfc \uc2e4\uc81c \uc0ac\ubb3c\uc774 \ud55c \uc7a5\uba74\uc5d0 \uc11e\uc778\ub2e4. \ubb34\ub300\ub294 \uc644\uc804\ud788 \uc9c4\uc9dc\uc778 \uc7a5\uc18c\ub3c4 \uc644\uc804\ud788 \ub0a9\uc791\ud55c \uadf8\ub9bc\ub3c4 \uc544\ub2c8\uc5c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc7ac\ub8cc\uac00 \uad00\uac1d\uc758 \ub208\uc5d0\uc11c \ud558\ub098\uc758 \uacf5\uac04\uc774 \ub41c\ub2e4. \uc791\uc740 \uc2dd\ubb3c\uacfc \uba3c \ubc30\uacbd\uc758 \uad00\uacc4\ub97c \uc5b4\ub5bb\uac8c \ub9de\ucd94\ub294\uc9c0\uc5d0 \ub530\ub77c \uae4a\uc774\uac00 \uc0dd\uae34\ub2e4. \uc5f0\uadf9\uc758 \uc0ac\uc2e4\uac10\uc740 \uc2e4\uc81c \ubb3c\uac74\uc744 \ub9ce\uc774 \ub193\ub294 \uac83\ub9cc\uc73c\ub85c \uacb0\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4. \ubc30\uc6b0\uac00 \uadf8 \uc0ac\uc774\ub97c \uc5b4\ub5bb\uac8c \uc9c0\ub098\uac00\uace0 \ube5b\uc774 \ubb34\uc5c7\uc744 \ub4dc\ub7ec\ub0b4\ub294\uc9c0\ub3c4 \uc7a5\uba74\uc744 \ubbff\uac8c \ud558\ub294 \uc870\uac74\uc774\ub2e4. \uc2dc\ub4dc\ubaa8\uc5b4\ub294 \uc790\uc2e0\uc774 \ubcf8 \uc77c\ubcf8\uc758 \ubb34\ub300 \ud6a8\uacfc\ub97c \ub192\uc774 \ud3c9\uac00\ud558\uba74\uc11c \uc11c\uc591\uc758 \uc720\uba85 \ubc30\uc6b0\uc640 \uacf5\uc5f0\uc744 \ube44\uad50\ud588\ub2e4. \uc774\ub7f0 \ube44\uad50\ub294 \ub2f9\uc2dc \uc678\uad6d \uad00\uac1d\uc758 \ub180\ub77c\uc6c0\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uadf8\ub7ec\ub098 \uc5b4\ub290 \ubb38\ud654\uc758 \uc5f0\uadf9\uc774 \ub354 \uc6b0\uc6d4\ud55c\uc9c0 \ud310\uc815\ud558\ub294 \uc624\ub298\uc758 \uae30\uc900\uc73c\ub85c \ubc1b\uc544\ub4e4\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8\uc758 \uae00\uc5d0 \ub098\uc624\ub294 \ub2f9\uc2dc\ub77c\ub294 \uc2dc\uac04\ub3c4 \uc624\ub298\uacfc \uac19\uc9c0 \uc54a\ub2e4. \uc9c0\uae08 \ubaa8\ub4e0 \ud68c\uc804\ubb34\ub300\uac00 \uc0ac\ub78c\uc758 \uc5b4\uae68 \ud798\uc73c\ub85c \uc6c0\uc9c1\uc778\ub2e4\uace0 \uc124\uba85\ud558\uba74 \uc798\ubabb\uc774\ub2e4. \uc5ed\uc0ac \uae30\ub85d\uc758 \uad6c\uccb4\uc801\uc778 \uae30\uc220\uc744 \ubc30\uc6b0\ub418, \uc774\ud6c4\uc758 \ubcc0\ud654\uc640 \ub2e4\ub978 \uadf9\uc7a5\uc758 \uac00\ub2a5\uc131\uc744 \ub0a8\uaca8 \ub450\uc5b4\uc57c \ud55c\ub2e4. \ud68c\uc804\ubb34\ub300\ub294 \ubb34\ub300\uc758 \ubcc0\ud654\ub97c \uc228\uae30\ub294 \ub3d9\uc2dc\uc5d0 \ubcc0\ud654 \uc790\uccb4\ub97c \ubcfc\uac70\ub9ac\ub85c \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \uc9d1\uc774 \ub3cc\uc544\uac00 \ub2e4\ub978 \ubc29\uc744 \ub4dc\ub7ec\ub0b4\ub294 \uc9e7\uc740 \uc2dc\uac04\uc5d0 \uad00\uac1d\uc740 \uacf5\uc5f0\uc774 \ub9cc\ub4e4\uc5b4\uc9c0\ub294 \ubc29\ubc95\ub3c4 \uc5b4\ub834\ud48b\uc774 \ub290\ub080\ub2e4. \ud658\uc0c1\uc744 \ubbff\ub294 \uc77c\uacfc \uc7a5\uce58\ub97c \uc54c\uc544\ubcf4\ub294 \uc77c\uc774 \uaf2d \ubc18\ub300\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\uc74c\uc5d0 \uacf5\uc5f0\uc744 \ubcfc \ub54c\uc5d0\ub294 \ubc30\uc6b0\uac00 \ub9d0\ud558\uc9c0 \uc54a\ub294 \uc21c\uac04\ub3c4 \uc0b4\ud3b4\ubcf4\uc790. \ubc14\ub2e5\uc774 \uc6c0\uc9c1\uc774\uace0 \ube5b\uc774 \ub2ec\ub77c\uc9c0\uba70 \uc0ac\ub78c\uc774 \ub2e4\ub978 \uae38\ub85c \ub4e4\uc5b4\uc624\ub294 \ub3d9\uc548 \uc774\uc57c\uae30\ub294 \uacc4\uc18d \uc9c4\ud589\ub41c\ub2e4. \ub208\uc5d0 \ub744\ub294 \ud6a8\uacfc\ub97c \ub9cc\ub4dc\ub294 \ub370\uc5d0\ub3c4 \uc11c\ub85c\uc758 \ud0c0\uc774\ubc0d\uc744 \ub9de\ucd94\ub294 \ud6c8\ub828\uc774 \ud544\uc694\ud588\ub2e4. \uc77c\ubcf8 \uadf9\uc7a5\uc758 \uc624\ub798\ub41c \uae30\ub85d\uc740 \uc5f0\uadf9\uc744 \ub300\uc0ac\uc640 \ubc30\uc6b0\ubfd0 \uc544\ub2c8\ub77c \uacf5\uac04\uc744 \ubc14\uafb8\ub294 \uc0ac\ub78c\ub4e4\uc758 \ud611\uc5c5\uc73c\ub85c \ubcf4\uac8c \ud55c\ub2e4."}, {"id": "jekyll-hyde-door-and-responsibility", "title": "\uc9c0\ud0ac \ubc15\uc0ac\uc640 \ud558\uc774\ub4dc \u2014 \ub2e4\ub978 \uc774\ub984\uc774\uba74 \ucc45\uc784\ub3c4 \uc0ac\ub77c\uc9c8\uae4c", "summary": "\uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \ub530\ub77c \uc9c0\ud0ac\uc758 \uc2e4\ud5d8, \uc5b4\ud130\uc2a8\uc758 \ucd94\uc801, \uba85\uc131\uacfc \ucc45\uc784\uc744 \ubd84\ub9ac\ud558\ub824\ub294 \uc695\ub9dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/jekyll-hyde-door-and-responsibility/index.html", "image": "../media/jekyll-hyde-door-and-responsibility.png", "alt": "\ubc1d\uc740 \uc8fc\ud0dd \ucd9c\uc785\ubb38\uacfc \uc5b4\ub450\uc6b4 \uc606 \uace8\ubaa9\uc758 \uc2e4\ud5d8\uc2e4 \uc785\uad6c\ub97c \ub5a0\uc62c\ub9ac\ub294 \uc18c\uc124 \uad00\ub828 \uc0bd\ud654", "text": "\uc9c0\ud0ac \ubc15\uc0ac\uc640 \ud558\uc774\ub4dc \u2014 \ub2e4\ub978 \uc774\ub984\uc774\uba74 \ucc45\uc784\ub3c4 \uc0ac\ub77c\uc9c8\uae4c \uc218\uc218\uaed8\ub07c\uc758 \ubb38\uc5d0\uc11c \uc2dc\uc791\ud574 \ud55c \uc0ac\ub78c\uc758 \uace0\ubc31\uc5d0 \ub3c4\ucc29\ud558\ub294 \uc18c\uc124 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \ub530\ub77c \uc9c0\ud0ac\uc758 \uc2e4\ud5d8, \uc5b4\ud130\uc2a8\uc758 \ucd94\uc801, \uba85\uc131\uacfc \ucc45\uc784\uc744 \ubd84\ub9ac\ud558\ub824\ub294 \uc695\ub9dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \uc874\uacbd\ubc1b\ub294 \uc758\uc0ac\uc640 \uc0ac\ub78c\ub4e4\uc774 \uaebc\ub9ac\ub294 \ub0a8\uc790. \ub450 \uc0ac\ub78c\uc758 \uc774\ub984\uc774 \ud568\uaed8 \ubd88\ub9b4 \ub9cc\ud07c \uc720\uba85\ud55c \uc18c\uc124\uc774\uc9c0\ub9cc, \uc6d0\uc791\uc740 \ucc98\uc74c\ubd80\ud130 \ub458\uc758 \ube44\ubc00\uc744 \uc124\uba85\ud558\uc9c0 \uc54a\ub294\ub2e4. \ubcc0\ud638\uc0ac\uac00 \uc5b4\ub290 \ub0a1\uc740 \ubb38\uc5d0 \uc5bd\ud78c \uc0ac\uac74\uc744 \ub4e4\uc73c\uba74\uc11c \uc774\uc57c\uae30\ub294 \uc2dc\uc791\ub41c\ub2e4. \ub85c\ubc84\ud2b8 \ub8e8\uc774\uc2a4 \uc2a4\ud2f0\ube10\uc2a8\uc758 \u300e\uc9c0\ud0ac \ubc15\uc0ac\uc640 \ud558\uc774\ub4dc\u300f\ub294 \ubcc0\uc2e0\uc758 \uacf5\ud3ec\ub97c \ub2f4\uc740 \uc18c\uc124\uc774\ub2e4. \ub3d9\uc2dc\uc5d0 \uc0ac\ub78c\uc758 \ud3c9\ud310\uc744 \uc9c0\ud0a4\ub824\ub294 \ub9c8\uc74c\uc774 \uc5b4\ub5bb\uac8c \uc9c4\uc2e4\uc744 \ubbf8\ub8e8\uace0 \ucc45\uc784\uc744 \ud750\ub9ac\ub294\uc9c0 \ubb3b\ub294 \uc774\uc57c\uae30\uc774\uae30\ub3c4 \ud558\ub2e4. \uc544\ub798\uc5d0\ub294 \uc911\uc694\ud55c \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4. \ubcc0\ud638\uc0ac \uc5b4\ud130\uc2a8\uc740 \uce5c\ucc99 \uc5d4\ud544\ub4dc\uc640 \uc0b0\ucc45\ud558\ub2e4\uac00 \ucd08\ub77c\ud55c \ubb38 \uc55e\uc5d0\uc11c \uae30\uc774\ud55c \uc774\uc57c\uae30\ub97c \ub4e3\ub294\ub2e4. \ud558\uc774\ub4dc\ub77c\ub294 \ub0a8\uc790\uac00 \uc5b4\ub9b0\uc544\uc774\ub97c \uc9d3\ubc1f\uace0 \uc9c0\ub098\uac14\uace0, \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\uc774 \uadf8\ub97c \ubd99\uc7a1\uc544 \ubcf4\uc0c1\uc744 \uc694\uad6c\ud588\ub2e4\ub294 \uac83\uc774\ub2e4. \uc794\ud639\ud55c \ud589\ub3d9\uacfc \ud0dc\ub3c4\ub294 \ubaa9\uaca9\uc790\uc5d0\uac8c \uac15\ud55c \ud610\uc624\ub97c \ub0a8\uacbc\ub2e4. \ud558\uc774\ub4dc\ub294 \uadf8 \ubb38\uc73c\ub85c \ub4e4\uc5b4\uac00 \ub3c8\uacfc \uc218\ud45c\ub97c \uac00\uc838\uc654\ub2e4. \uc218\ud45c\uc5d0\ub294 \uc874\uacbd\ubc1b\ub294 \uc0ac\ub78c\uc758 \uc774\ub984\uc774 \uc788\uc5c8\ub2e4. \uc5b4\ud130\uc2a8\uc5d0\uac8c \ubb38\uc81c\ub294 \ub0af\uc120 \uc545\uc778\uc758 \uc874\uc7ac\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc790\uc2e0\uc758 \uce5c\uad6c\uc778 \uc9c0\ud0ac \ubc15\uc0ac\uac00 \uadf8 \ub0a8\uc790\uc640 \uc5b4\ub5a4 \uad00\uacc4\uc778\uc9c0\uac00 \uac71\uc815\ub418\uae30 \uc2dc\uc791\ud588\ub2e4. \uc5b4\ud130\uc2a8\uc740 \uc9c0\ud0ac\uc758 \uc720\uc5b8\uc7a5\uc744 \uc54c\uace0 \uc788\uc5c8\ub2e4. \uc9c0\ud0ac\uc774 \uc8fd\uac70\ub098 \uc77c\uc815 \uae30\uac04 \uc0ac\ub77c\uc9c0\uba74 \uc7ac\uc0b0\uc744 \ud558\uc774\ub4dc\uc5d0\uac8c \ub118\uae34\ub2e4\ub294 \ub0b4\uc6a9\uc774\uc5c8\ub2e4. \ubcc0\ud638\uc0ac\ub294 \uce5c\uad6c\uac00 \ud611\ubc15\uc744 \ub2f9\ud558\ub294 \uac83\uc740 \uc544\ub2cc\uc9c0 \uc758\uc2ec\ud558\uba70 \ud558\uc774\ub4dc\ub97c \ucc3e\uc544\uac00 \uc9c1\uc811 \ub9cc\ub09c\ub2e4. \uc9c0\ud0ac\uc740 \uc790\uc2e0\uc774 \uc6d0\ud558\uba74 \ud558\uc774\ub4dc\uc640\uc758 \uad00\uacc4\ub97c \ub05d\ub0bc \uc218 \uc788\ub2e4\ub294 \ud0dc\ub3c4\ub97c \ubcf4\uc778\ub2e4. \uce5c\uad6c\uc5d0\uac8c \ub9e1\uaca8\uc9c4 \uc77c\uc744 \ubbff\uc5b4 \ub2ec\ub77c\uace0\ub3c4 \ud55c\ub2e4. \ub3c5\uc790\ub294 \uc5b4\ud130\uc2a8\uacfc \ud568\uaed8 \uc81c\ud55c\ub41c \uc815\ubcf4\ub9cc \uc5bb\ub294\ub2e4. \uc9c0\ud0ac\uc774 \ud53c\ud574\uc790\uc778\uc9c0 \uacf5\ubc94\uc778\uc9c0 \uc27d\uac8c \ud310\ub2e8\ud560 \uc218 \uc5c6\ub2e4. \ud558\uc774\ub4dc\ub294 \ub4a4\uc5d0 \ub304\ubc84\uc2a4 \ucee4\ub8e8 \uacbd\uc744 \uc0b4\ud574\ud55c\ub2e4. \ucc98\uc74c\uc758 \ubd88\uae38\ud55c \uc18c\ubb38\uc740 \uc2e4\uc81c \uc0b4\uc778 \uc0ac\uac74\uc73c\ub85c \ucee4\uc9c4\ub2e4. \uc5b4\ud130\uc2a8\uc740 \uacbd\ucc30\uacfc \ud568\uaed8 \ud558\uc774\ub4dc\uac00 \uc0b4\ub358 \uacf3\uc744 \ucc3e\uc544\uac00\uc9c0\ub9cc \uadf8\ub97c \ubd99\uc7a1\uc9c0 \ubabb\ud55c\ub2e4. \uc9c0\ud0ac\uc740 \ub354 \uc774\uc0c1 \ud558\uc774\ub4dc\uc640 \uad00\uacc4\ud558\uc9c0 \uc54a\uaca0\ub2e4\uace0 \ub9d0\ud55c\ub2e4. \uadf8 \ub4a4 \uc7a0\uc2dc \uc9c0\ud0ac\uc758 \uc0dd\ud65c\uc740 \ub098\uc544\uc9c0\ub294 \ub4ef \ubcf4\uc778\ub2e4. \uc0ac\ub78c\ub4e4\uc744 \ub9cc\ub098\uace0 \uce5c\uad6c\uc640\ub3c4 \uc5b4\uc6b8\ub9b0\ub2e4. \ub3c5\uc790\ub3c4 \uc545\uc778\uacfc\uc758 \uad00\uacc4\uac00 \ub04a\uc5b4\uc84c\ub2e4\uace0 \uc548\uc2ec\ud558\uace0 \uc2f6\uc5b4\uc9c4\ub2e4. \uadf8\ub7ec\ub098 \ub2eb\ud78c \ubb38\uacfc \ud3b8\uc9c0, \uce5c\uad6c\ub4e4\uc758 \ub2ec\ub77c\uc9c4 \ud0dc\ub3c4\ub294 \uacc4\uc18d \ub0a8\uc544 \uc788\ub2e4. \uc9c0\ud0ac\uacfc \uc624\ub7ab\ub3d9\uc548 \uc54c\ub358 \uc758\uc0ac \ub798\ub2c8\uc5b8\uc740 \ucda9\uaca9\uc801\uc778 \uc77c\uc744 \uacaa\uc740 \ub4a4 \uc1e0\uc57d\ud574\uc838 \uc8fd\ub294\ub2e4. \uadf8\uac00 \ub0a8\uae34 \ubb38\uc11c\ub294 \uc9c0\ud0ac\uc774 \uc0ac\ub77c\uc9c0\uac70\ub098 \uc8fd\uae30 \uc804\uae4c\uc9c0 \uc5f4\uc9c0 \ub9d0\ub77c\ub294 \uc870\uac74\uc73c\ub85c \uc5b4\ud130\uc2a8\uc5d0\uac8c \ub9e1\uaca8\uc9c4\ub2e4. \uc9c4\uc2e4\uc774 \uc885\uc774 \uc548\uc5d0 \uac07\ud78c \ucc44 \ubbf8\ub904\uc9c0\ub294 \uac83\uc774\ub2e4. \uacb0\uad6d \uc9d1\uc0ac \ud480\uc740 \uc9c0\ud0ac\uc758 \ubc29\uc5d0\uc11c \ub4e4\ub9ac\ub294 \ubaa9\uc18c\ub9ac\uac00 \uc8fc\uc778\uc758 \uac83\uc774 \uc544\ub2c8\ub77c\uace0 \uac71\uc815\ud558\uba70 \ubcc0\ud638\uc0ac\ub97c \ubd80\ub978\ub2e4. \ub450 \uc0ac\ub78c\uc774 \ubb38\uc744 \ubd80\uc218\uace0 \ub4e4\uc5b4\uac14\uc744 \ub54c \ubc1c\uacac\ud55c \uac83\uc740 \uc9c0\ud0ac\uc758 \ud070 \uc637\uc744 \uc785\uc740 \ud558\uc774\ub4dc\uc758 \uc2dc\uc2e0\uc774\ub2e4. \uc9c0\ud0ac\uc758 \ud589\ubc29\uc740 \uc5ec\uc804\ud788 \uc218\uc218\uaed8\ub07c\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uc774\uc81c \uc18c\uc124\uc740 \ub0a8\uaca8\uc9c4 \ubb38\uc11c\ub97c \ud1b5\ud574 \uc55e\uc120 \uc0ac\uac74\ub4e4\uc744 \ub2e4\uc2dc \uc124\uba85\ud55c\ub2e4. \ub798\ub2c8\uc5b8\uc740 \uc9c0\ud0ac\uc758 \uc694\uccad\uc73c\ub85c \uc57d\ud488\uc744 \uac00\uc838\ub2e4\uc8fc\uc5c8\uace0, \ucc3e\uc544\uc628 \ud558\uc774\ub4dc\uac00 \uadf8\uac83\uc744 \ub9c8\uc2dc\uace0 \uc9c0\ud0ac\uc758 \ubaa8\uc2b5\uc73c\ub85c \ubcc0\ud558\ub294 \uad11\uacbd\uc744 \ubcf4\uc558\ub2e4. \uadf8 \ucda9\uaca9\uc774 \uadf8\ub97c \ubb34\ub108\ub728\ub838\ub2e4. \ub450 \uc0ac\ub78c\ucc98\ub7fc \ubcf4\uc774\ub358 \uc778\ubb3c\uc774 \uac19\uc740 \ubab8\uc758 \ub2e4\ub978 \ubaa8\uc2b5\uc774\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \uc9c0\ud0ac\uc744 \ud611\ubc15\ud558\ub294 \uc678\ubd80\uc758 \uc545\uc778\uc744 \ucc3e\ub358 \uc5b4\ud130\uc2a8\uc758 \ucd94\uce21\ub3c4 \ubc14\ub010\ub2e4. \ub3c5\uc790\ub294 \uc774\ubbf8 \uc77d\uc740 \ubb38\uacfc \uc720\uc5b8\uc7a5, \uc218\ud45c\uc758 \uc758\ubbf8\ub97c \ub4a4\uc5d0\uc11c \ub2e4\uc2dc \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \ub9c8\uc9c0\ub9c9 \uace0\ubc31\uc5d0\uc11c \uc9c0\ud0ac\uc740 \uc0ac\ud68c\uc801\uc73c\ub85c \uc874\uacbd\ubc1b\uace0 \uc2f6\uc740 \ub9c8\uc74c\uacfc \ub4dc\ub7ec\ub0b4\uace0 \uc2f6\uc9c0 \uc54a\uc740 \uc695\ub9dd\uc774 \uc790\uc2e0 \uc548\uc5d0 \ud568\uaed8 \uc788\uc5c8\ub2e4\uace0 \ub9d0\ud55c\ub2e4. \uadf8\ub294 \uc2e4\ud5d8\uc73c\ub85c \uc11c\ub85c \ucda9\ub3cc\ud558\ub294 \ubd80\ubd84\uc744 \ubd84\ub9ac\ud558\uba74 \ub9c8\uc74c\uc758 \uac08\ub4f1\uc5d0\uc11c \ubc97\uc5b4\ub0a0 \uc218 \uc788\uc73c\ub9ac\ub77c \uae30\ub300\ud588\ub2e4. \uadf8\ub7ec\ub098 \ud558\uc774\ub4dc\ub97c \ub9cc\ub4e4\uc5b4 \ub0b8 \ub4a4\uc5d0\ub3c4 \uc9c0\ud0ac\uc740 \uc120\ub9cc \ub0a8\uc740 \uc21c\uc218\ud55c \uc874\uc7ac\uac00 \ub418\uc9c0 \uc54a\uc558\ub2e4. \uc9c0\ud0ac\uc5d0\uac8c\ub294 \ud558\uc774\ub4dc\uac00 \uc800\uc9c0\ub978 \ud589\ub3d9\uc744 \uc54c\uba74\uc11c \uadf8 \uc790\uc720\ub97c \uc774\uc6a9\ud558\ub824\ub294 \ub9c8\uc74c\uc774 \ub0a8\uc544 \uc788\uc5c8\ub2e4. \uc774\ub984\uacfc \uc678\ubaa8\ub97c \uac08\ub77c \ub193\uc544\ub3c4 \uc120\ud0dd\uc758 \uc5f0\uacb0\uc740 \ub04a\uc5b4\uc9c0\uc9c0 \uc54a\uc558\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc57d\uc744 \ub9c8\uc2dc\uace0 \ubcc0\ud55c \ub4a4 \ub2e4\uc2dc \ub3cc\uc544\uc62c \uc218 \uc788\uc5c8\ub2e4. \uc9c0\ud0ac\uc740 \uadf8 \uac00\ub2a5\uc131\uc744 \uc790\uc2e0\uc758 \ud1b5\uc81c\ub825\ucc98\ub7fc \uc5ec\uae34\ub2e4. \ud558\uc9c0\ub9cc \ub098\uc911\uc5d0\ub294 \uc6d0\ud558\uc9c0 \uc54a\uc740 \ub54c\uc5d0\ub3c4 \ud558\uc774\ub4dc\ub85c \ubcc0\ud55c\ub2e4. \ub2e4\ub978 \ubaa8\uc2b5\uc73c\ub85c \uc0ac\ub294 \uc790\uc720\ub294 \ub3cc\uc544\uac08 \uae38\uc744 \uc783\uc744 \uc704\ud5d8\uc73c\ub85c \ubc14\ub010\ub2e4. \uc0b4\uc778 \uc774\ud6c4 \uba48\ucd94\ub824\ub358 \uacb0\uc2ec\ub3c4 \uc548\uc815\uc801\uc778 \ud574\uacb0\uc774 \ub418\uc9c0 \ubabb\ud55c\ub2e4. \uc774\ubbf8 \ud3b8\ub9ac\ud558\uac8c \uc774\uc6a9\ud588\ub358 \uad00\uacc4\uac00 \uc790\uc2e0\uc744 \ubd99\uc7a1\uae30 \uc2dc\uc791\ud55c\ub2e4. \uc18c\uc124\uc758 \uacf5\ud3ec\ub294 \uc545\ud55c \ubaa8\uc2b5\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc \uc544\ub2c8\ub77c \uadf8\uac83\uc744 \ud544\uc694\ud560 \ub54c \uaebc\ub0c8\ub2e4\uac00 \ub9c8\uc74c\ub300\ub85c \ub123\uc744 \uc218 \uc788\ub2e4\ub294 \ubbff\uc74c\uc774 \ubb34\ub108\uc9c0\ub294 \ub370 \uc788\ub2e4. \uc9c0\ud0ac\uc740 \ubcc0\ud654\ub97c \ub418\ub3cc\ub9ac\ub294 \ub370 \uc4f0\ub358 \uc7ac\ub8cc\ub97c \uad6c\ud558\ub824 \ud558\uc9c0\ub9cc \uc0c8\ub85c \uad6c\ud55c \ubb3c\uc9c8\uc740 \uc608\uc804\ucc98\ub7fc \uc791\uc6a9\ud558\uc9c0 \uc54a\ub294\ub2e4. \uadf8\ub294 \ucc98\uc74c \uc7ac\ub8cc\uc5d0 \uc11e\uc5ec \uc788\ub358 \uc54c \uc218 \uc5c6\ub294 \ubd88\uc21c\ubb3c\uc774 \uc791\uc6a9\ud588\uc744\uc9c0 \ubaa8\ub978\ub2e4\uace0 \ucd94\uce21\ud55c\ub2e4. \uc790\uc2e0\uc774 \ub9cc\ub4e0 \ubc29\ubc95\uc744 \uc644\uc804\ud788 \uc774\ud574\ud558\uace0 \uc788\uc9c0\ub3c4 \uc54a\uc558\ub358 \uc148\uc774\ub2e4. \ub0a8\uc740 \uc7ac\ub8cc\ub85c \uc7a0\uc2dc \uc9c0\ud0ac\uc758 \ubaa8\uc2b5\uc744 \uc720\uc9c0\ud558\uba70 \uace0\ubc31\uc744 \ub05d\ub0b4\ub294 \uc7a5\uba74\uc774 \uc18c\uc124\uc758 \ub9c8\uc9c0\ub9c9\uc774\ub2e4. \uc55e\uc11c \ub3c5\uc790\uac00 \ubcf8 \uc2dc\uc2e0\uacfc \ubb38\uc11c\uac00 \uc5ec\uae30\uc11c \uc5f0\uacb0\ub41c\ub2e4. \uc2e4\ud5d8\uc73c\ub85c \ubc97\uc5b4\ub098\ub824\ub358 \ucc45\uc784\uc740 \ub05d\ub0b4 \uc790\uc2e0\uacfc \ubd84\ub9ac\ub418\uc9c0 \uc54a\uc558\uace0, \uadf8\uc758 \uc124\uba85\ub3c4 \ud1b5\uc81c\ub825\uc744 \ub418\ucc3e\uc544 \uc8fc\uc9c0\ub294 \ubabb\ud55c\ub2e4. \uc774 \uc791\ud488\uc744 \ub450 \uc131\uaca9\uc774 \uc2f8\uc6b0\ub294 \uc774\uc57c\uae30\ub85c\ub9cc \uc904\uc774\uba74 \uc9c0\ud0ac\uc758 \uc120\ud0dd\uc774 \ud750\ub824\uc9c4\ub2e4. \ud558\uc774\ub4dc\ub294 \ucc98\uc74c\ubd80\ud130 \uc6b0\uc5f0\ud788 \ubd99\uc740 \ub0af\uc120 \uc874\uc7ac\uac00 \uc544\ub2c8\ub2e4. \uc9c0\ud0ac\uc740 \uadf8 \ubaa8\uc2b5\uc744 \ub9cc\ub4e4\uace0 \uc774\uc6a9\ud560 \uc870\uac74\uc744 \uc900\ube44\ud588\uc73c\uba70 \uc790\uc2e0\uc758 \uba85\uc131\uacfc \uc7ac\uc0b0\ub3c4 \ubcf4\ud638\ud558\ub824 \ud588\ub2e4. \uadf8\ub798\uc11c \uc774\ub984\uc774 \ub2e4\ub974\ub2e4\ub294 \uc774\uc720\ub85c \ud589\uc704\uc758 \ucc45\uc784\uc744 \ub118\uae38 \uc218 \uc788\ub294\uc9c0\uac00 \uc911\uc694\ud55c \uc9c8\ubb38\uc774 \ub41c\ub2e4. \uc18c\uc124\uc758 \ubcc0\uc2e0\uc740 \ud5c8\uad6c\uc774\uc9c0\ub9cc \ud3c9\ud310\uc744 \uc9c0\ud0a4\uba74\uc11c \uc695\ub9dd\uc758 \ub300\uac00\ub9cc \ub2e4\ub978 \uacf3\uc73c\ub85c \ubc00\uc5b4\ub0b4\uace0 \uc2f6\uc740 \ub9c8\uc74c\uc740 \ub0af\uc124\uc9c0 \uc54a\ub2e4. \uc774 \ud574\uc11d\uc740 \uc791\ud488\uc744 \uc77d\ub294 \ud55c \uac00\uc9c0 \uae38\uc774\uc9c0 \uc758\ud559\uc801 \uc9c4\ub2e8\uc740 \uc544\ub2c8\ub2e4. \uc18c\uc124\uc5d0\ub294 \ud6cc\ub96d\ud55c \uc8fc\ud0dd\uc758 \ubaa8\uc2b5\uacfc \ub4b7\ucabd \uc2e4\ud5d8\uc2e4\ub85c \ub4dc\ub098\ub4dc\ub294 \ucd08\ub77c\ud55c \ucd9c\uc785\uad6c\uac00 \uc5f0\uacb0\ub418\uc5b4 \uc788\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc785\uad6c\uac00 \uacb0\uad6d \uac19\uc740 \uacf5\uac04\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uad6c\uc870\ub294 \ub450 \uc774\ub984\uc758 \uad00\uacc4\uc640\ub3c4 \ub2ee\uc558\ub2e4. \ubc14\uae65\uc5d0\uc11c \ubcf8 \uc778\uc0c1\ub9cc\uc73c\ub85c\ub294 \uadf8 \uc5f0\uacb0\uc774 \ub4dc\ub7ec\ub098\uc9c0 \uc54a\ub294\ub2e4. \ucc98\uc74c \uc77d\uc744 \ub54c\ub294 \uc5b4\ud130\uc2a8\uacfc \ud568\uaed8 \uc218\uc218\uaed8\ub07c\ub97c \ud480\uace0, \ub2e4\uc2dc \uc77d\uc744 \ub54c\ub294 \uc9c0\ud0ac\uc774 \uc5b4\ub5a4 \uc124\uba85\uc73c\ub85c \uc790\uc2e0\uc744 \uc548\uc2ec\uc2dc\ud0a4\ub294\uc9c0 \uc0b4\ud3b4\ubd10\ub3c4 \uc88b\ub2e4. \uacb0\ub9d0\uc744 \uc544\ub294 \ub4a4\uc5d0\ub3c4 \uc774 \uc18c\uc124\uc774 \ud765\ubbf8\ub85c\uc6b4 \uc774\uc720\ub294 \ube44\ubc00 \ud558\ub098\ubcf4\ub2e4 \uadf8 \ube44\ubc00\uc744 \uc720\uc9c0\ud55c \uc120\ud0dd\ub4e4\uc774 \uc624\ub798 \ub0a8\uae30 \ub54c\ubb38\uc774\ub2e4."}, {"id": "jingdezhen-blue-white-porcelain-sea", "title": "\uccad\ud654\ubc31\uc790 \u2014 \ud558\uc580 \uadf8\ub987\uc758 \ud478\ub978\ube5b\uc740 \ubc14\ub2e4\ub97c \uac74\ub11c\ub2e4", "summary": "\ud770 \ubc14\ud0d5\uc758 \ud478\ub978 \ubb34\ub2ac\ub97c \ub530\ub77c \uc911\uad6d \ub3c4\uc790\uae30\uc758 \uc81c\uc791\uacfc \ud574\uc0c1 \uad50\uc5ed\uc744 \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/jingdezhen-blue-white-porcelain-sea/index.html", "image": "../media/jingdezhen-blue-white-porcelain-sea.jpg", "alt": "\uccad\ud654\ubc31\uc790 \ubb3c\ubfcc\ub9ac\uac1c\uc640 \ub450 \ubcd1\uc758 \ubaa8\uc591\uacfc \ubb34\ub2ac\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc61b \uc5f0\uad6c\uc11c \ub3c4\ud310 92", "text": "\uccad\ud654\ubc31\uc790 \u2014 \ud558\uc580 \uadf8\ub987\uc758 \ud478\ub978\ube5b\uc740 \ubc14\ub2e4\ub97c \uac74\ub11c\ub2e4 \uc9d5\ub354\uc804\uc758 \ub3c4\uc790\uae30\uc5d0\uc11c \ub9cc\ub098\ub294 \uacf5\ubc29\uacfc \uad50\uc5ed\uc758 \uc5ed\uc0ac \ud770 \ubc14\ud0d5\uc758 \ud478\ub978 \ubb34\ub2ac\ub97c \ub530\ub77c \uc911\uad6d \ub3c4\uc790\uae30\uc758 \uc81c\uc791\uacfc \ud574\uc0c1 \uad50\uc5ed\uc744 \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \ud770 \uadf8\ub987 \uc704\uc758 \ud478\ub978 \uc120\uc740 \ub208\uc5d0 \uc798 \ub4e4\uc5b4\uc628\ub2e4. \uaf43\uacfc \ub369\uad74\uc774 \ub418\uace0, \uad6c\ub984\uacfc \uc6a9\uc774 \ub418\uae30\ub3c4 \ud55c\ub2e4. \uccad\ud654\ubc31\uc790\ub294 \ubaa8\uc591\uc774 \ubcf5\uc7a1\ud574\ub3c4 \uba3c\uc800 \uc0c9\uc758 \uc870\ud569\uc73c\ub85c \uae30\uc5b5\ub418\ub294 \ub3c4\uc790\uae30\ub2e4. \uc775\uc219\ud55c \ub450 \uc0c9\uc774\uc9c0\ub9cc \uadf8 \ub4a4\uc758 \uc5ed\uc0ac\ub294 \ud55c \uacf5\ubc29 \uc548\uc5d0\uc11c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc911\uad6d\uc758 \ub3c4\uc790\uae30 \uc0dd\uc0b0\uc9c0 \uc9d5\ub354\uc804\uc5d0\uc11c \ub9cc\ub4e4\uc5b4\uc9c4 \ubb3c\uac74\ub4e4\uc740 \uc911\uad6d \uc548\ud30e\uc758 \uc5ec\ub7ec \uc0ac\ub78c\uc744 \ub9cc\ub0ac\ub2e4. \uba40\ub9ac \uc6b4\ubc18\ub418\ub294 \uadf8\ub987\uc5d0\ub294 \ud759\uacfc \ubd88\uc758 \uae30\uc220\ubfd0 \uc544\ub2c8\ub77c \uc0c1\uc778\uc758 \uac70\ub798, \uc0ac\uc6a9\ud558\ub294 \uc0ac\ub78c\uc758 \ucde8\ud5a5\ub3c4 \ud568\uaed8 \uc2e4\ub838\ub2e4. \uc2dd\ud0c1\uc758 \ubb3c\uac74\uc774 \ubc14\ub2e4\uc758 \uc5ed\uc0ac\ub85c \uc774\uc5b4\uc9c0\ub294 \uc9c0\uc810\uc774\ub2e4. \uccad\ud654\ubc31\uc790\ub77c\ub294 \uc774\ub984\uc5d0\uc11c \uba3c\uc800 \ub5a0\uc62c\ub9b4 \uac83\uc740 \ud770 \ubc14\ud0d5\uacfc \ud478\ub978 \uc7a5\uc2dd\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc61b \ub3c4\ud310\uc740 \ud751\ubc31 \uc7ac\ud604\uc774\ubbc0\ub85c \uc2e4\uc81c \ud478\ub978\uc0c9\uc744 \ubcf4\uc5ec \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubb34\ub2ac\uc640 \ud615\ud0dc\ub97c \ubcf4\ub294 \ub370 \ud65c\uc6a9\ud558\uba74 \ub41c\ub2e4. \uc120\uc774 \uad75\uc5b4\uc84c\ub2e4 \uac00\ub298\uc5b4\uc9c0\ub294 \uacf3, \ud478\ub978\ube5b\uc774 \uc9c4\ud558\uac8c \ubaa8\uc774\ub294 \uacf3\uacfc \ud770 \uc5ec\ubc31\uc774 \ub0a8\uc740 \uacf3\uc744 \ucc3e\uc544\ubcf4\ub294 \uac83\ubd80\ud130 \uc2dc\uc791\ud560 \uc218 \uc788\ub2e4. \uac19\uc740 \ub450 \uc0c9\uc744 \uc4f0\ub354\ub77c\ub3c4 \uc778\uc0c1\uc740 \ub2ec\ub77c\uc9c4\ub2e4. \uc791\uc740 \uadf8\ub987\uc758 \uac00\uc7a5\uc790\ub9ac\ub97c \ub530\ub77c\uac00\ub294 \ubb34\ub2ac\uc640 \ud070 \ubcd1\uc758 \ubab8\ud1b5\uc744 \uac10\uc2f8\ub294 \ubb34\ub2ac\ub294 \ubcf4\ub294 \uc21c\uc11c\ub97c \ubc14\uafbc\ub2e4. \ub3c4\uc790\uae30\ub294 \uadf8\ub9bc\uc744 \ud3c9\ud3c9\ud55c \uc885\uc774\uc5d0 \uc5b9\uc740 \uac83\uacfc \ub2ec\ub9ac, \ubab8\uccb4\ub97c \ub3cc\ub824 \ubcf4\uba70 \uc77d\ub294 \ubb3c\uac74\uc774\ub2e4. \uc9d5\ub354\uc804\uc740 \uc624\ub7ab\ub3d9\uc548 \uc911\uad6d \ub3c4\uc790\uae30 \uc0dd\uc0b0\uc758 \uc911\uc694\ud55c \uc911\uc2ec\uc9c0\uc600\ub2e4. OpenStax\uac00 \uc18c\uac1c\ud558\ub294 18\uc138\uae30\uc758 \ubcd1\uacfc \uc811\uc2dc\ub3c4 \uc774\uacf3\uc5d0\uc11c \ub9cc\ub4e4\uc5b4\uc9c4 \ubb3c\uac74\uc774\ub2e4. \uc7a5\uc18c\uc758 \uc774\ub984\uc774 \ubc18\ubcf5\ud574\uc11c \ub4f1\uc7a5\ud55c\ub2e4\ub294 \uac83\uc740 \ud55c \uc0ac\ub78c\uc758 \uc7ac\uc8fc\ub97c \ub118\uc5b4 \uc81c\uc791 \uacbd\ud5d8\uacfc \uc77c\uc774 \ubaa8\uc774\ub294 \uae30\ubc18\uc774 \uc788\uc5c8\uc74c\uc744 \ub73b\ud55c\ub2e4. \ud759\uc73c\ub85c \ud615\ud0dc\ub97c \ub9cc\ub4e4\uace0 \uc7a5\uc2dd\uc744 \ub354\ud558\uace0 \uac00\ub9c8\uc5d0\uc11c \uad7d\ub294 \uc77c\uc740 \uac01\uac01\uc758 \uc870\uac74\uc744 \ub9de\ucd94\uc5b4\uc57c \ud55c\ub2e4. \uc644\uc131\ub41c \uadf8\ub987\uc758 \ud45c\uba74\uc740 \ub9e4\ub044\ub7ec\uc6cc\ub3c4 \uadf8 \uacfc\uc815\uc740 \uc5ec\ub7ec \ub2e8\uacc4\ub85c \uc774\ub8e8\uc5b4\uc9c4\ub2e4. \uac10\uc0c1\ud560 \ub54c \ud654\uac00\uc758 \ubd93\ub05d\ub9cc \ub5a0\uc62c\ub838\ub2e4\uba74 \uc774\ubc88\uc5d0\ub294 \uc7ac\ub8cc\uc640 \uac00\ub9c8, \uacf5\ubc29\uc758 \uc791\uc5c5\uae4c\uc9c0 \ud568\uaed8 \uc0dd\uac01\ud574 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \ud478\ub978 \uc7a5\uc2dd\uc5d0 \uc4f0\uc774\ub294 \ucf54\ubc1c\ud2b8\ub294 \uccad\ud654\ubc31\uc790\uc758 \ud2b9\uc9d5\uc744 \uc774\ud574\ud558\ub294 \uc2e4\ub9c8\ub9ac\ub2e4. \uc911\uad6d \ub3c4\uc790\uae30\ub97c \ub2e4\ub8ec \uc61b \uc5f0\uad6c\uc11c\ub294 \uc911\uad6d \uc548\uc758 \uc7ac\ub8cc\uc640 \uc678\ubd80\uc5d0\uc11c \ub4e4\uc5b4\uc624\ub294 \uc548\ub8cc\ub97c \ud568\uaed8 \uc124\uba85\ud55c\ub2e4. \ud55c \uac00\uc9c0 \uc544\ub984\ub2e4\uc6b4 \uc0c9\uc5d0\ub3c4 \uc7ac\ub8cc\ub97c \uad6c\ud558\uace0 \uc120\ud0dd\ud558\ub294 \ubb38\uc81c\uac00 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \uc2dc\ub300\uc758 \uccad\ud654\ubc31\uc790\uac00 \uac19\uc740 \uc0b0\uc9c0\uc758 \uac19\uc740 \uc548\ub8cc\ub85c \ub9cc\ub4e4\uc5b4\uc84c\ub2e4\uace0 \ubb36\uc744 \uc218\ub294 \uc5c6\ub2e4. \ud2b9\uc815 \uadf8\ub987\uc758 \uc7ac\ub8cc\uc640 \uc81c\uc791 \uc2dc\uae30\ub97c \uc54c\ub824\uba74 \uadf8 \uc720\ubb3c\uc758 \uc870\uc0ac \uacb0\uacfc\uac00 \ud544\uc694\ud558\ub2e4. \uc5ec\uae30\uc11c\ub294 \ud478\ub978 \ubb34\ub2ac\uac00 \uacf5\ubc29 \ubc14\uae65\uc758 \uad50\ub958\uc640\ub3c4 \uc5f0\uacb0\ub420 \uc218 \uc788\ub2e4\ub294 \ubc94\uc704\uae4c\uc9c0 \uc77d\ub294\ub2e4. \uc544\uc2dc\uc544\uc758 \ud574\uc0c1 \uad50\uc5ed\uc5d0\uc11c\ub294 \ud5a5\uc2e0\ub8cc\uc640 \uc9c1\ubb3c, \ub3c4\uc790\uae30 \uac19\uc740 \ubb3c\uac74\uc774 \uc5ec\ub7ec \ud56d\uad6c\ub97c \uc624\uac14\ub2e4. \uc720\ub7fd\uc758 \uc0c1\uc778\ub4e4\uc774 \ubcf8\uaca9\uc801\uc73c\ub85c \ub4e4\uc5b4\uc624\uae30 \uc804\ubd80\ud130 \uc778\ub3c4\uc591\uacfc \ub3d9\ub0a8\uc544\uc2dc\uc544\uc758 \uad50\uc5ed\ub9dd\uc740 \uc6c0\uc9c1\uc774\uace0 \uc788\uc5c8\ub2e4. \uc911\uad6d \ub3c4\uc790\uae30\ub3c4 \uc774\ub7f0 \uc624\ub798\ub41c \uc5f0\uacb0 \uc18d\uc5d0\uc11c \uc774\ub3d9\ud588\ub2e4. \uc218\ucd9c\ud488\uc744 \uc11c\uc591\uc774 \ubc1c\uacac\ud55c \ub4a4\uc5d0\uc57c \ube44\ub85c\uc18c \uc911\uc694\ud55c \ubb3c\uac74\uc774 \ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud558\uba74 \uadf8 \uc55e\uc758 \uc5ed\uc0ac\uac00 \uc0ac\ub77c\uc9c4\ub2e4. \uc911\uad6d\uc758 \uc0ac\uc6a9\uc790\uc640 \uc5ec\ub7ec \uc544\uc2dc\uc544 \uc9c0\uc5ed\uc758 \uac70\ub798 \uc0c1\ub300\ub3c4 \ub3c4\uc790\uae30\uc758 \uc0b6\uc744 \uc774\ub8e8\uc5c8\ub2e4. \uadf8\ub987\uc758 \uc5ec\ud589\uc744 \ud55c \ubc29\ud5a5\uc758 \ud56d\ub85c\ub85c\ub9cc \ubcf4\uc9c0 \uc54a\uc744 \ub54c \ubc14\ub2e4\uc758 \ud48d\uacbd\uc774 \ub354 \ub113\uc5b4\uc9c4\ub2e4. \ud568\uaed8 \uc2e4\uc740 \ub3c4\ud310\uc5d0\uc11c\ub294 \ubaa9\uc774 \uae34 \ubb3c\ubfcc\ub9ac\uac1c\uc640 \ub450 \ubcd1\uc758 \uc11c\ub85c \ub2e4\ub978 \ud615\ud0dc\ub97c \ubcfc \uc218 \uc788\ub2e4. \ubab8\uccb4\uc758 \uc724\uacfd\uacfc \uc190\uc7a1\uc774\uc758 \uc704\uce58\uac00 \ub2ec\ub77c\uc9c0\uba74 \uc7a5\uc2dd\uc774 \ub193\uc77c \uc790\ub9ac\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \ub3c4\uc790\uae30\ub97c \uc0c9\uacfc \ubb34\ub2ac\ub9cc\uc73c\ub85c \uae30\uc5b5\ud558\uc9c0 \ub9d0\uace0, \ubb34\uc5c7\uc744 \ub2f4\uace0 \uc5b4\ub5bb\uac8c \uc7a1\ub294 \ud615\ud0dc\uc778\uc9c0 \uc0b4\ud3b4\ubcf4\uba74 \uc88b\ub2e4. \uc624\ub798\ub41c \ubcd1\uc774 \uc544\ub984\ub2f5\ub2e4\uace0 \ud574\uc11c \ubaa8\ub450 \uac19\uc740 \uc6a9\ub3c4\ub098 \uac19\uc740 \uc0ac\uc6a9\uc790\ub97c \uac00\uc84c\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc18c\uc7a5\ud488 \uc124\uba85\uc774 \ud655\uc778\ud558\ub294 \ubc94\uc704\ub97c \uc9c0\ud0a4\uba74\uc11c \ubab8\uccb4\uc758 \uade0\ud615\uacfc \uc7a5\uc2dd\uc758 \uc704\uce58\ub97c \ubcf4\ub294 \uac83\uc73c\ub85c\ub3c4 \ucda9\ubd84\ud558\ub2e4. \ubaa8\uc591\uc744 \uad00\ucc30\ud558\ub294 \uc791\uc740 \uc2b5\uad00\uc774 \uadf8\ub987\uc758 \ucc28\uc774\ub97c \ub354 \uc798 \ub290\ub07c\uac8c \ud55c\ub2e4. \uc911\uad6d \ub3c4\uc790\uae30\uc758 \uc5ed\uc0ac\uc5d0\ub294 \ud669\uc2e4\uc744 \uc704\ud55c \uc81c\uc791\ub3c4 \uc788\uace0 \uac70\ub798\ub97c \uc704\ud55c \uc81c\uc791\ub3c4 \uc788\ub2e4. \uc61b \uc5f0\uad6c\uc11c\uac00 \uc9d5\ub354\uc804\uc758 \ud669\uc2e4 \uacf5\uc7a5\uc744 \uae38\uac8c \uc124\uba85\ud55c\ub2e4\uace0 \ud574\uc11c \uadf8 \ub3c4\uc2dc\uc758 \ubaa8\ub4e0 \uadf8\ub987\uc744 \ud669\uc81c\uc758 \uc2dd\ud0c1\uc73c\ub85c \ubcf4\ub0b4\uc9c0\ub294 \ub9d0\uc544\uc57c \ud55c\ub2e4. OpenStax \uc5ed\uc2dc \uc9d5\ub354\uc804\uc758 \uc0dd\uc0b0\ud488\uc774 \uc911\uad6d\uacfc \ub2e4\ub978 \uc9c0\uc5ed\uc5d0\uc11c \ud310\ub9e4\ub418\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc0dd\uc0b0 \uc911\uc2ec\uc9c0\ub294 \uc5ec\ub7ec \uc218\uc694\ub97c \ub9cc\ub098\ub294 \uc7a5\uc18c\uc774\uae30\ub3c4 \ud588\ub2e4. \uc655\uc2e4\uc758 \ubb3c\uac74\uc778\uc9c0, \uc2dc\uc7a5\uc5d0\uc11c \uc720\ud1b5\ub41c \ubb3c\uac74\uc778\uc9c0\uc5d0 \ub530\ub77c \ud655\uc778\ud574\uc57c \ud560 \uc815\ubcf4\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc720\uba85\ud55c \uc655\uc870\uc758 \uc774\ub984\uc774 \ubd99\uc5c8\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \ub204\uac00 \uc2e4\uc81c \uc0ac\uc6a9\ud588\ub294\uc9c0\uae4c\uc9c0 \uc54c \uc218\ub294 \uc5c6\ub2e4. \uc791\ud488 \uc124\uba85\uc5d0\uc11c \uc81c\uc791 \uc2dc\uae30\uc640 \uc0dd\uc0b0\uc9c0, \ud655\uc778\ub41c \uc720\ud1b5 \uc774\ub825\uc744 \ub530\ub85c \uc77d\ub294 \uc2b5\uad00\uc774 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ud654\ub824\ud55c \ubb34\ub2ac\ub97c \uac10\uc0c1\ud558\uba74\uc11c\ub3c4 \uadf8\ub987\uc758 \uc2e0\ubd84\uc744 \uc123\ubd88\ub9ac \uc815\ud558\uc9c0 \uc54a\ub294 \ubc29\ubc95\uc774\ub2e4. \uccad\ud654\ubc31\uc790\ub294 \uc911\uad6d \ubbf8\uc220\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uc720\uba85\ud55c \ubb3c\uac74\uc774\uc9c0\ub9cc \uc911\uad6d \ub3c4\uc790\uae30\uc758 \uc804\ubd80\ub294 \uc544\ub2c8\ub2e4. \ub2e4\ub978 \uc0c9\uacfc \uc7ac\ub8cc, \uac00\ub9c8\uc640 \uc2dc\ub300\uc758 \uc791\ud488\uc774 \ud568\uaed8 \uc874\uc7ac\ud588\ub2e4. \ub110\ub9ac \uc54c\ub824\uc9c4 \ud55c \uc591\uc2dd\uc740 \ud48d\ubd80\ud55c \uc138\uacc4\ub85c \ub4e4\uc5b4\uac00\ub294 \uc785\uad6c\uc774\uc9c0, \uadf8 \uc138\uacc4\ub97c \ubaa8\ub450 \ub300\uc2e0\ud558\ub294 \ud45c\uc9c0\uac00 \uc544\ub2c8\ub2e4. \uadf8\ub798\uc11c \ub2e4\uc74c \uadf8\ub987\uc744 \ub9cc\ub0a0 \ub54c\ub294 \uc544\ub294 \uc774\ub984\uc744 \uace7\ubc14\ub85c \ubd99\uc774\uae30\ubcf4\ub2e4 \ud55c \ubc88 \ub354 \ubcf4\ub294 \ud3b8\uc774 \uc88b\ub2e4. \ud770 \ubc14\ud0d5\uc758 \ub290\ub08c\uc740 \uc5b4\ub5a4\uc9c0, \uc120\uc740 \uc5b4\ub514\uc11c \uba48\ucd94\ub294\uc9c0, \ubb34\ub2ac\uac00 \ubab8\uccb4\ub97c \uc5b4\ub5bb\uac8c \uac10\uc2f8\ub294\uc9c0. \ubc14\ub2e4\ub97c \uac74\ub10c \ub3c4\uc790\uae30\uc758 \ud070 \uc5ed\uc0ac\ub3c4 \uacb0\uad6d \ub208\uc55e\uc758 \uc791\uc740 \ucc28\uc774\uc5d0\uc11c \ub2e4\uc2dc \uc2dc\uc791\ub41c\ub2e4. \uadf8\ub987\uc744 \uc815\uba74\uc5d0\uc11c \ubcf8 \ub4a4 \uc606\uc5d0\uc11c \ubcf4\uc558\ub2e4\uace0 \uc0c1\uc0c1\ud574 \ubcf4\uc790. \uac19\uc740 \ubb34\ub2ac\uac00 \uace1\uba74\uc744 \ub530\ub77c \ub2ec\ub77c \ubcf4\uc77c \uac83\uc774\ub2e4. \uc7a5\uc2dd\uc744 \uadf8\ub9b0 \uc190\uacfc \uadf8 \uc7a5\uc2dd\uc758 \ubc14\ud0d5\uc774 \ub420 \ud615\ud0dc\ub97c \ub9cc\ub4e0 \uc190\uc774 \uc5b4\ub5bb\uac8c \ub9cc\ub098\ub294\uc9c0 \uc0dd\uac01\ud558\uba74 \ub3c4\uc790\uae30\uc758 \uc990\uac70\uc6c0\uc774 \uc870\uae08 \ub354 \ucee4\uc9c4\ub2e4."}, {"id": "joyce-dead-song-snow-and-memory", "title": "\uc870\uc774\uc2a4\uc758 \u300c\uc8fd\uc740 \uc0ac\ub78c\ub4e4\u300d \u2014 \ub178\ub798 \ud55c \uace1\uc774 \uc800\ub141\uc744 \ubc14\uafb8\ub2e4", "summary": "\uc5f0\ud68c\uc640 \ub178\ub798, \uc544\ub0b4\uc758 \uae30\uc5b5\uacfc \ub208 \ub0b4\ub9ac\ub294 \uacb0\ub9d0\uc744 \ud1b5\ud574 \ud0c0\uc778\uc744 \uc774\ud574\ud558\ub294 \ubcc0\ud654\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/joyce-dead-song-snow-and-memory/index.html", "image": "../media/joyce-dead-song-snow-and-memory.png", "alt": "\ub208 \ub0b4\ub9ac\ub294 \ub354\ube14\ub9b0\uc758 \ud638\ud154\uc5d0\uc11c \uc0dd\uac01\uc5d0 \uc7a0\uae34 \ubd80\ubd80\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uc870\uc774\uc2a4\uc758 \u300c\uc8fd\uc740 \uc0ac\ub78c\ub4e4\u300d \u2014 \ub178\ub798 \ud55c \uace1\uc774 \uc800\ub141\uc744 \ubc14\uafb8\ub2e4 \ub354\ube14\ub9b0\uc758 \ubaa8\uc784\uc5d0\uc11c \uc775\uc219\ud55c \uc5ed\ud560\uc744 \ub9e1\ub2e4\uc5d0\uc11c \uc2dc\uc791\ud558\ub294 \uc5ed\uc0ac\uc640 \uc791\ud488 \uc77d\uae30 \uc5f0\ud68c\uc640 \ub178\ub798, \uc544\ub0b4\uc758 \uae30\uc5b5\uacfc \ub208 \ub0b4\ub9ac\ub294 \uacb0\ub9d0\uc744 \ud1b5\ud574 \ud0c0\uc778\uc744 \uc774\ud574\ud558\ub294 \ubcc0\ud654\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \uc990\uac70\uc6b4 \ubaa8\uc784\uc774 \ub05d\ub09c \ub4a4, \ub204\uad70\uac00 \uacc4\ub2e8\uc5d0\uc11c \ub178\ub798\ub97c \ub4e3\uace0 \uba48\ucd98\ub2e4. \ub0a8\ud3b8\uc740 \uc544\ub0b4\uc758 \ubaa8\uc2b5\uc744 \uc544\ub984\ub2f5\uac8c \ubc14\ub77c\ubcf4\uc9c0\ub9cc \uadf8\ub140\uac00 \ubb34\uc5c7\uc744 \ub5a0\uc62c\ub9ac\ub294\uc9c0\ub294 \uc544\uc9c1 \ubaa8\ub978\ub2e4. \uc81c\uc784\uc2a4 \uc870\uc774\uc2a4\uc758 \u300e\ub354\ube14\ub9b0 \uc0ac\ub78c\ub4e4\u300f \ub9c8\uc9c0\ub9c9 \uc791\ud488 \u300c\uc8fd\uc740 \uc0ac\ub78c\ub4e4\u300d\uc740 \uc774\ub807\uac8c \uac19\uc740 \uc21c\uac04\uc744 \uc11c\ub85c \ub2e4\ub974\uac8c \uc0ac\ub294 \ub450 \uc0ac\ub78c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc774\uc57c\uae30\ub294 \uc720\ub839\uc758 \ucd9c\ud604\uc744 \ub2e4\ub8e8\uae30\ubcf4\ub2e4 \uae30\uc5b5 \uc18d\uc758 \uc8fd\uc740 \uc0ac\ub78c\uc774 \ud604\uc7ac\uc758 \uad00\uacc4\uc5d0 \uc5b4\ub5bb\uac8c \ub3cc\uc544\uc624\ub294\uc9c0 \ubb3b\ub294\ub2e4. \uc8fc\uc694 \uc0ac\uac74\uacfc \uacb0\ub9d0\uc744 \ub530\ub77c\uac00\uba70 \ud30c\ud2f0\uc758 \ub9d0\ub4e4\uacfc \ud638\ud154 \ubc29\uc758 \uace0\ubc31, \ub9c8\uc9c0\ub9c9\uc5d0 \ub0b4\ub9ac\ub294 \ub208\uc744 \uc5f0\uacb0\ud574 \ubcf4\uc790. \uac8c\uc774\ube0c\ub9ac\uc5bc \ucf58\ub85c\uc774\ub294 \uc544\ub0b4 \uadf8\ub808\ud0c0\uc640 \ud568\uaed8 \uce5c\ucc99\ub4e4\uc758 \uc5f0\ub840 \ubaa8\uc784\uc5d0 \uac04\ub2e4. \uc74c\uc545\uacfc \ucda4, \uc74c\uc2dd\uacfc \ub300\ud654\uac00 \uc774\uc5b4\uc9c0\ub294 \uc790\ub9ac\ub2e4. \uadf8\ub294 \uc190\ub2d8\uc73c\ub85c \ucc38\uc5ec\ud558\uba74\uc11c\ub3c4 \uc5f0\uc124\uc744 \ub9e1\uace0 \ubd84\uc704\uae30\ub97c \uc0b4\ud53c\ub294 \uc5ed\ud560\uc744 \ud55c\ub2e4. \uc775\uc219\ud55c \uad00\uacc4 \uc548\uc5d0\uc11c \uc790\uc2e0\uc774 \uc5b4\ub5bb\uac8c \ubcf4\uc77c\uc9c0\ub3c4 \uacc4\uc18d \uc758\uc2dd\ud55c\ub2e4. \uc870\uc774\uc2a4\ub294 \uc774 \uc800\ub141\uc744 \uace7\uc7a5 \ud070 \uc0ac\uac74\uc73c\ub85c \ubab0\uc544\uac00\uc9c0 \uc54a\ub294\ub2e4. \uc791\uc740 \ub9d0\uacfc \uc5b4\uc0c9\ud55c \ubc18\uc751\uc744 \uc313\uc73c\uba70 \uac8c\uc774\ube0c\ub9ac\uc5bc\uc758 \uc790\uc2e0\uac10\uc744 \ud754\ub4e0\ub2e4. \uadf8\ub294 \ub2e4\ub978 \uc0ac\ub78c\uc744 \uc798 \ub300\ud558\ub824\uace0 \ud558\uc9c0\ub9cc \uadf8 \uc758\ub3c4\uac00 \uc5b8\uc81c\ub098 \uc0c1\ub300\uc5d0\uac8c \uac19\uc740 \ub73b\uc73c\ub85c \uc804\ub2ec\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubc30\ub824\uc640 \uc790\uae30\ub9cc\uc871 \uc0ac\uc774\uc758 \uac04\uaca9\uc774 \ub4dc\ub7ec\ub098\uae30 \uc2dc\uc791\ud55c\ub2e4. \ud558\ub140 \ub9b4\ub9ac\uc640\uc758 \ub300\ud654\uc5d0\uc11c \uac8c\uc774\ube0c\ub9ac\uc5bc\uc740 \uc608\uc0c1\ud558\uc9c0 \ubabb\ud55c \ubc18\uc751\uc744 \ub4e3\ub294\ub2e4. \uc0c1\ub300\uc758 \uc0b6\uc744 \uce5c\uadfc\ud55c \ub9d0 \uba87 \ub9c8\ub514\ub85c \uac00\ubccd\uac8c \uc9d0\uc791\ud560 \uc218 \uc5c6\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub098\ud0c0\ub09c\ub2e4. \uc774\uc5b4 \ubbf8\uc2a4 \uc544\uc774\ubc84\uc2a4\uc640\uc758 \ub300\ud654\uc5d0\uc11c\ub294 \uc544\uc77c\ub79c\ub4dc\uc758 \uc815\uccb4\uc131\uacfc \uadf8\uac00 \ubb38\ud654\uc801\uc73c\ub85c \ud5a5\ud558\ub294 \ubc29\ud5a5\uc774 \ubb38\uc81c\uac00 \ub41c\ub2e4. \uadf8\ub294 \ub2e4\ub978 \uacf3\uc744 \uc5ec\ud589\ud558\uace0 \ubb38\ud654\ub97c \uc990\uae30\ub824\ub294 \uc790\uae30 \uc0dd\uac01\uc744 \uac16\uace0 \uc788\uc9c0\ub9cc \uc0c1\ub300\ub294 \ub2e4\ub978 \uae30\uc900\uc5d0\uc11c \uc9c8\ubb38\ud55c\ub2e4. \uc791\ud488\uc740 \uc5b4\ub290 \ud55c\ucabd\uc744 \uc815\ub2f5\uc758 \ub300\ubcc0\uc790\ub85c\ub9cc \ub450\uc9c0 \uc54a\ub294\ub2e4. \ub2e4\ub9cc \uac8c\uc774\ube0c\ub9ac\uc5bc\uc774 \uc2a4\uc2a4\ub85c \ucda9\ubd84\ud788 \uc774\ud574\ud55c\ub2e4\uace0 \uc5ec\uae34 \uc138\uacc4\uc5d0\ub3c4 \uc790\uc2e0\uc744 \ubd88\ud3b8\ud558\uac8c \ud558\ub294 \ubaa9\uc18c\ub9ac\uac00 \uc788\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc800\ub141 \uc2dd\uc0ac \uc790\ub9ac\uc5d0\uc11c \uac8c\uc774\ube0c\ub9ac\uc5bc\uc740 \ud658\ub300\uc640 \uae30\uc5b5\uc5d0 \uad00\ud574 \ub9d0\ud55c\ub2e4. \uce5c\ucc99\ub4e4\uc758 \uce5c\uc808\uacfc \uc774\uc804 \uc138\ub300\ub97c \uae30\ub9ac\ub294 \ub9d0\uc740 \ubaa8\uc784\uc758 \ubd84\uc704\uae30\ub97c \ubb36\ub294\ub2e4. \uadf8\ub294 \uacf5\uac1c\uc801\uc73c\ub85c \ub9d0\ud560 \uc218 \uc788\ub294 \uc0ac\ub78c\uc774\uba70 \uadf8 \uc5ed\ud560\uc744 \uc218\ud589\ud55c\ub2e4. \ud558\uc9c0\ub9cc \ub2e4\ub978 \uc0ac\ub78c\uc758 \ub9c8\uc74c\uc744 \uc5bc\ub9c8\ub098 \uc544\ub294\uc9c0\ub294 \ubcc4\uac1c\uc758 \ubb38\uc81c\ub2e4. \uc774 \ub300\ubaa9\uc740 \ub4a4\uc5d0 \uc774\uc5b4\uc9c8 \uc0ac\uc801\uc778 \uace0\ubc31\uacfc \uc5f0\uacb0\ub41c\ub2e4. \ub9ce\uc740 \uc0ac\ub78c \uc55e\uc5d0\uc11c \uae30\uc5b5\uc758 \uac00\uce58\ub97c \uc798 \uc124\uba85\ud558\ub294 \uc0ac\ub78c\uc774 \ubc14\ub85c \uacc1\uc5d0 \uc788\ub294 \uc544\ub0b4\uc758 \uc911\uc694\ud55c \uae30\uc5b5\uc740 \ubaa8\ub974\uace0 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4. \uc5f0\uc124\uc774 \uac70\uc9d3\uc774\uc5c8\ub2e4\ub294 \ub2e8\uc21c\ud55c \ubc18\uc804\ubcf4\ub2e4, \uacf5\uc801\uc778 \ub9d0\uacfc \uac1c\uc778\uc801\uc778 \uc774\ud574\uac00 \ub2e4\ub97c \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \ubaa8\uc784\uc774 \ub05d\ub098 \uac08 \ubb34\ub835 \uadf8\ub808\ud0c0\ub294 \ud55c \ub178\ub798\uc5d0 \uadc0\ub97c \uae30\uc6b8\uc778\ub2e4. \uac8c\uc774\ube0c\ub9ac\uc5bc\uc740 \uadf8 \ubaa8\uc2b5\uc744 \ubc14\ub77c\ubcf4\uba70 \uc0c8\ub85c\uc6b4 \ub9e4\ub825\uc744 \ub290\ub080\ub2e4. \uadf8\ub7ec\ub098 \uadf8\uc5d0\uac8c \uc544\ub984\ub2e4\uc6b4 \uc7a5\uba74\uc778 \uc21c\uac04\uc774 \uadf8\ub140\uc5d0\uac8c\ub294 \ub2e4\ub978 \uc2dc\uac04\uc73c\ub85c \ud5a5\ud558\ub294 \ubb38\uc774\ub2e4. \ubcf4\ub294 \uc0ac\ub78c\uacfc \ub4e3\ub294 \uc0ac\ub78c\uc758 \uacbd\ud5d8\uc774 \ub098\ub780\ud788 \uac08\ub77c\uc9c4\ub2e4. \ub178\ub798\ub294 \uc124\uba85\ubcf4\ub2e4 \uba3c\uc800 \uae30\uc5b5\uc744 \uc6c0\uc9c1\uc778\ub2e4. \uadf8\ub808\ud0c0\uac00 \uc5b4\ub5a4 \ub9d0\uc744 \ub4e4\uc5c8\uace0 \ub204\uad6c\ub97c \ub5a0\uc62c\ub838\ub294\uc9c0 \uc54c\uae30 \uc804\uae4c\uc9c0 \ub0a8\ud3b8\uc740 \uc790\uae30 \uae30\ub300 \uc18d\uc5d0\uc11c \uadf8\ub140\ub97c \ud574\uc11d\ud55c\ub2e4. \uac00\uae4c\uc6b4 \uc0ac\ub78c\uc774\ub77c\uace0 \ud574\uc11c \uac19\uc740 \uc800\ub141\uc744 \uac19\uc740 \uc758\ubbf8\ub85c \ubcf4\ub0b4\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774 \ucc28\uc774\uac00 \ub450 \uc0ac\ub78c\uc774 \ub2e8\ub458\uc774 \ub41c \ub4a4 \ub4dc\ub7ec\ub09c\ub2e4. \ub178\ub798\ub294 \uc78a\uc5c8\ub358 \uc0ac\uc2e4\uc744 \uc124\uba85\ud558\ub294 \ub3c4\uad6c\ub9cc\uc774 \uc544\ub2c8\ub2e4. \ub4e3\ub294 \uc21c\uac04 \ubab8\uc774 \uba48\ucd94\uace0 \ub2e4\ub978 \uc2dc\uac04\uc758 \uac10\uc815\uc774 \ud604\uc7ac\ub85c \ub4e4\uc5b4\uc628\ub2e4. \uadf8\ub798\uc11c \uc774 \uc791\ud488\uc5d0\uc11c\ub294 \ud070 \uc0ac\uac74\uc774 \uc77c\uc5b4\ub098\uc9c0 \uc54a\uc544\ub3c4 \uc0ac\ub78c\uc758 \uc138\uacc4\uac00 \ubc14\ub014 \uc218 \uc788\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\uc758 \uce68\ubb35\uc744 \ud568\ubd80\ub85c \ud574\uc11d\ud558\uc9c0 \uc54a\uac8c \ub418\ub294 \ubcc0\ud654\ub2e4. \uadf8\ub808\ud0c0\ub294 \uc80a\uc740 \uc2dc\uc808 \uc54c\uace0 \uc9c0\ub0b4\ub358 \ub9c8\uc774\ud074 \ud4e8\ub9ac\uc5d0 \uad00\ud574 \uc774\uc57c\uae30\ud55c\ub2e4. \ubcd1\uc57d\ud588\ub358 \uadf8 \uc18c\ub144\uc740 \uadf8\ub140\uac00 \ub5a0\ub098\uae30 \uc804 \ub9cc\ub098\ub7ec \uc654\uace0 \ub4a4\uc5d0 \uc8fd\uc5c8\ub2e4. \uadf8\ub140\ub294 \uc790\uc2e0 \ub54c\ubb38\uc5d0 \uadf8\uac00 \uc8fd\uc5c8\ub2e4\uace0 \ub290\ub080\ub2e4. \ub3c5\uc790\ub294 \uc774\ub97c \uadf8\ub140\uac00 \uae30\uc5b5\ud558\uace0 \ud574\uc11d\ud558\ub294 \uc774\uc57c\uae30\ub85c \ub4e3\ub294\ub2e4. \uc815\ud655\ud55c \uc0ac\ub9dd \uc6d0\uc778\uc744 \ud310\uc815\ud558\ub294 \uae30\ub85d\uc740 \uc544\ub2c8\ub2e4. \uac8c\uc774\ube0c\ub9ac\uc5bc\uc740 \uc9c8\ud22c\uc640 \ub2f9\ud639\uac10 \uc18d\uc5d0\uc11c \uc774 \ub9d0\uc744 \ubc1b\uc544\ub4e4\uc778\ub2e4. \uc790\uc2e0\uc774 \ubaa8\ub974\ub358 \uc0ac\ub78c\uc774 \uc544\ub0b4\uc758 \ub9c8\uc74c\uc5d0 \uae4a\uc774 \ub0a8\uc544 \uc788\uc5c8\ub2e4. \uc8fd\uc740 \uacbd\uc7c1\uc790\ub97c \uc774\uae30\uac70\ub098 \uacfc\uac70\ub97c \ubc14\uafc0 \ubc29\ubc95\uc740 \uc5c6\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uadf8\ub140\uc758 \uc0b6\uc774 \uc790\uc2e0\uacfc\uc758 \uacb0\ud63c\ub9cc\uc73c\ub85c \uc2dc\uc791\ub418\uac70\ub098 \uc644\uc804\ud788 \uc124\uba85\ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc0ac\uc2e4\uc774\ub2e4. \uc544\ub0b4\uac00 \uc7a0\ub4e0 \ub4a4 \uac8c\uc774\ube0c\ub9ac\uc5bc\uc740 \uc790\uc2e0\uc758 \uc695\ub9dd\uacfc \ud0dc\ub3c4\ub97c \ub3cc\uc544\ubcf8\ub2e4. \uc870\uae08 \uc804\uae4c\uc9c0\uc758 \uae30\ub300\uc640 \uc790\ubd80\uc2ec\uc774 \ub2e4\ub978 \ube5b\uc5d0\uc11c \ubcf4\uc778\ub2e4. \uadf8\ub294 \uc790\uc2e0\uc774 \uadf8\ub9cc\ud07c \uae4a\uc740 \uac10\uc815\uc744 \uc0b4\uc544 \ubcf8 \uc801\uc774 \uc788\ub294\uc9c0 \uc0dd\uac01\ud55c\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\uc744 \uc18c\uc720\ud558\uac70\ub098 \ud3c9\uac00\ud558\ub294 \uc704\uce58\uc5d0\uc11c \ubc97\uc5b4\ub0a0 \uac00\ub2a5\uc131\uc774 \uc5f4\ub9b0\ub2e4. \uc774\uac83\uc744 \uadf8\uac00 \uc644\uc804\ud788 \ubcc0\ud574 \uc55e\uc73c\ub85c \ubaa8\ub4e0 \ubb38\uc81c\ub97c \ud574\uacb0\ud55c\ub2e4\ub294 \uc120\uc5b8\uc73c\ub85c \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc791\ud488\uc740 \ubbf8\ub798\uc758 \uc0dd\ud65c\uc744 \uc790\uc138\ud788 \ubcf4\uc7a5\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud55c\ubc24\uc758 \uc778\uc2dd\uc774 \uc5b4\ub514\uae4c\uc9c0 \uc774\uc5b4\uc9c8\uc9c0\ub294 \uc5f4\ub824 \uc788\ub2e4. \ub2e4\ub9cc \uc790\uc2e0\uc774 \uc911\uc2ec\uc774\ub77c\uace0 \uc5ec\uae34 \uad00\uacc4\ub97c \ub354 \ub113\uac8c \ubcfc \uc21c\uac04\uc774 \uc0dd\uacbc\ub2e4\ub294 \uc810\uc740 \ubd84\uba85\ud558\ub2e4. \ub9c8\uc9c0\ub9c9\uc758 \ub208\uc740 \ub354\ube14\ub9b0\uc758 \ubc29 \ubc14\uae65\uc73c\ub85c \uc2dc\uc57c\ub97c \ub113\ud78c\ub2e4. \uc544\uc77c\ub79c\ub4dc\uc758 \uc5ec\ub7ec \uacf3\uacfc \uc8fd\uc740 \uc774\uac00 \ubb3b\ud78c \uc790\ub9ac\uae4c\uc9c0 \uc5f0\uacb0\ub41c\ub2e4. \ud55c \ubd80\ubd80\uc758 \uc0ac\uc801\uc778 \uc774\uc57c\uae30\uac00 \ub354 \ub113\uc740 \uacf5\uac04\uacfc \uc2dc\uac04\uc5d0 \ub2ff\ub294\ub2e4. \uac8c\uc774\ube0c\ub9ac\uc5bc\uc774 \ub4e3\uc9c0 \ubabb\ud588\ub358 \uae30\uc5b5\ub3c4 \uac19\uc740 \uc138\uacc4 \uc548\uc5d0 \uc788\uc5c8\ub2e4. \u300c\uc8fd\uc740 \uc0ac\ub78c\ub4e4\u300d\uc758 \ub05d\uc740 \uc8fd\uc74c\uc774 \uc0b6\uc744 \uc774\uacbc\ub2e4\ub294 \ud55c\ub9c8\ub514\ub85c \ub2eb\ud788\uc9c0 \uc54a\ub294\ub2e4. \ub0a8\uc740 \uc0ac\ub78c\uc758 \ub9c8\uc74c\uc5d0\uc11c \uae30\uc5b5\uc740 \uacc4\uc18d \uc6c0\uc9c1\uc774\uace0, \uadf8 \uae30\uc5b5\uc744 \ub4e3\ub294 \uc0ac\ub78c\ub3c4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc624\ub798\ub41c \ub178\ub798\uc640 \ub0b4\ub9ac\ub294 \ub208\uc774 \ub0a8\uae30\ub294 \uc5ec\uc6b4\uc740 \uac00\uae4c\uc6b4 \uc0ac\ub78c\uc744 \uc5bc\ub9c8\ub098 \uc54c\uace0 \uc788\ub294\uc9c0 \ub2e4\uc2dc \ubb3b\uac8c \ud558\ub294 \ub370 \uc788\ub2e4."}, {"id": "karnak-columns-light-and-growing-temple", "title": "\uce74\ub974\ub098\ud06c \uc2e0\uc804 \u2014 \ub3cc\uae30\ub465\uc758 \uc232\uc740 \uc5b4\ub5bb\uac8c \ucee4\uc84c\uc744\uae4c", "summary": "\uc5ec\ub7ec \uc655\uc758 \uc2dc\uac04\uc774 \uacb9\uce5c \uc2e0\uc804\uacfc \uae30\ub465\uc758 \ub192\uc774, \uc0ac\ub77c\uc9c4 \uc9c0\ubd95\uc744 \ud1b5\ud574 \uac74\ucd95\uc758 \uacbd\ud5d8\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uac74\ucd95", "categories": ["arts"], "url": "stories/karnak-columns-light-and-growing-temple/index.html", "image": "../media/karnak-columns-light-and-growing-temple.png", "alt": "\uce74\ub974\ub098\ud06c \uc5f4\uc8fc\uc2e4\uc758 \uc911\uc559\ubd80\uc640 \uce21\uba74 \uae30\ub465, \uc9c0\ubd95 \ub192\uc774\uc640 \ucc44\uad11 \uad00\uacc4\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc61b \ub2e8\uba74\ub3c4", "text": "\uce74\ub974\ub098\ud06c \uc2e0\uc804 \u2014 \ub3cc\uae30\ub465\uc758 \uc232\uc740 \uc5b4\ub5bb\uac8c \ucee4\uc84c\uc744\uae4c \uc544\ubb38 \uc2e0\uc804\uc758 \ucd95\uc870\uc640 \uc131\uc7a5, \uc5f4\uc8fc\uc2e4\uc758 \uad6c\uc870\uc640 \ube5b\uc744 \ud568\uaed8 \ubcf4\uae30 \uc5ec\ub7ec \uc655\uc758 \uc2dc\uac04\uc774 \uacb9\uce5c \uc2e0\uc804\uacfc \uae30\ub465\uc758 \ub192\uc774, \uc0ac\ub77c\uc9c4 \uc9c0\ubd95\uc744 \ud1b5\ud574 \uac74\ucd95\uc758 \uacbd\ud5d8\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uac74\ucd95 \ubb38\ud654\uc640 \uc608\uc220 \uac70\ub300\ud55c \uae30\ub465 \uc0ac\uc774\uc5d0 \uc11c\uba74 \uc2e0\uc804\uc774 \uac74\ubb3c\ubcf4\ub2e4 \ub3cc\ub85c \ub9cc\ub4e0 \uc232\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uc624\ub298\ub0a0 \ub8e9\uc18c\ub974 \uc9c0\uc5ed\uc758 \uce74\ub974\ub098\ud06c\ub294 \uace0\ub300 \ud14c\ubca0\uc758 \uc911\uc694\ud55c \uc885\uad50 \uacf5\uac04\uc774\uc5c8\ub2e4. \ud55c \uba85\uc758 \uc655\uc774 \ud55c \ubc88\uc5d0 \uc644\uc131\ud55c \uae30\ub150\ubb3c\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\uc9c0\ub9cc, \uc2e4\uc81c\ub85c\ub294 \uc5ec\ub7ec \uc2dc\ub300\uc758 \ucd95\uc870\uc640 \ubcc0\uacbd\uc774 \uc313\uc778 \uc7a5\uc18c\ub2e4. \uc774\uacf3\uc744 \uc77d\ub294 \ucd9c\ubc1c\uc810\uc740 \uae30\ub465\uc774 \uba87 \uac1c\uc774\uace0 \uc5bc\ub9c8\ub098 \ub192\uc740\uc9c0\ub97c \uc678\uc6b0\ub294 \uac83\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub514\ub85c \ub4e4\uc5b4\uac00 \ubb34\uc5c7\uc744 \uc9c0\ub098\uba70 \uc5b4\ub5a4 \ube5b\uc744 \ub9cc\ub0ac\ub294\uc9c0 \uc0c1\uc0c1\ud574 \ubcf4\uc790. \uc2e0\uc559\uacfc \uc655\uad8c\uc774 \uac74\ucd95\uc758 \uc21c\uc11c\uc640 \ud06c\uae30\ub85c \ud45c\ud604\ub418\ub294 \ubc29\uc2dd\uc744 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uce74\ub974\ub098\ud06c\uc758 \uc911\uc2ec\uc5d0\ub294 \uc544\ubb38 \uc2e0\uc559\uacfc \uad00\ub828\ub41c \ud070 \uc2e0\uc804\uc774 \uc788\ub2e4. \uace0\ub300 \uc774\uc9d1\ud2b8\uc5d0\uc11c \uc2e0\uc804\uc740 \uc2e0\uc758 \uc9d1\uc73c\ub85c \uc5ec\uaca8\uc9c0\ub294 \uacf5\uac04\uc774\uba74\uc11c \uc655\uacfc \uc885\uad50\uc801 \uc9c8\uc11c\ub97c \uc5f0\uacb0\ud558\ub294 \uc7a5\uc18c\uc600\ub2e4. \uc2e0\uc744 \uc704\ud55c \uac74\ucd95\uc744 \uc138\uc6b0\ub294 \ud589\uc704\ub294 \ud1b5\uce58\uc790\uc758 \uc5ed\ud560\uacfc \uad8c\uc704\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc77c\uc774\uae30\ub3c4 \ud588\ub2e4. \uc624\ub298\uc758 \ubc15\ubb3c\uad00\ucc98\ub7fc \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uc790\uc720\ub86d\uac8c \ub0b4\ubd80\ub97c \uad6c\uacbd\ud558\ub294 \uacf3\uc73c\ub85c \uc0c1\uc0c1\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc885\uad50\uc801 \uc5ed\ud560\uacfc \uc9c0\uc704\uc5d0 \ub530\ub77c \uc811\uadfc\ud560 \uc218 \uc788\ub294 \uacf5\uac04\uc774 \ub2ec\ub790\ub2e4. \uac74\ucd95\uc758 \uc548\ucabd\uc73c\ub85c \uc6c0\uc9c1\uc778\ub2e4\ub294 \uac83\uc740 \ub2e8\uc21c\ud788 \uac70\ub9ac\uac00 \uc904\uc5b4\ub4dc\ub294 \uac83 \uc774\uc0c1\uc758 \uc758\ubbf8\uac00 \uc788\uc5c8\ub2e4. \uacf5\uac04\uc758 \uae4a\uc774\uc640 \uc704\uacc4\uac00 \ub9cc\ub0ac\ub2e4. \uce74\ub974\ub098\ud06c\uc5d0\ub294 \uc624\ub79c \uc2dc\uac04 \uc5ec\ub7ec \ud1b5\uce58\uc790\uac00 \uac74\ucd95\uacfc \uc7a5\uc2dd\uc744 \ub354\ud588\ub2e4. \uc55e\uc120 \uac83\uc744 \uc774\uc6a9\ud558\uba74\uc11c \uc0c8 \ubb38\uacfc \uacf5\uac04\uc744 \ub9cc\ub4e4\uae30\ub3c4 \ud588\ub2e4. \uc644\uc131\ub41c \ud55c \uc7a5\uc758 \uacc4\ud68d\uc744 \ucc98\uc74c\ubd80\ud130 \uadf8\ub300\ub85c \uc2e4\ud589\ud55c \uacb0\uacfc\uc640\ub294 \ub2e4\ub974\ub2e4. \uadf8\ub798\uc11c \uaddc\ubaa8\uac00 \ucee4\uc84c\ub2e4\ub294 \uc0ac\uc2e4 \uc548\uc5d0 \uc11c\ub85c \ub2e4\ub978 \uc120\ud0dd\uc758 \ud754\uc801\uc774 \uc788\ub2e4. \uc720\uc801\uc744 \uac78\uc73c\uba70 \ubc29\ud5a5\uc774 \ubc14\ub00c\uac70\ub098 \uac74\ucd95\uc758 \uacbd\uacc4\uac00 \ub9cc\ub0a0 \ub54c\uc5d0\ub294 \uadf8 \uc2dc\uac04\uc758 \ucc28\uc774\ub97c \ub5a0\uc62c\ub824 \ubcfc \uc218 \uc788\ub2e4. \ud558\ub098\uc758 \uc815\ub3c8\ub41c \uc678\uacfd\uc120\ub9cc \ucc3e\uc73c\uba74 \ubcf5\uc7a1\ud568\uc774 \uc2e4\uc218\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc2e0\uc804\uc758 \uc131\uc7a5\uc740 \uc5b4\ub5a4 \uc2dc\ub300\uac00 \uc55e\uc120 \uc2dc\ub300\uc640 \uad00\uacc4\ub97c \ub9fa\uc5c8\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \uc5ed\uc0ac \uc790\ub8cc\ub2e4. \uace0\ub300 \uc774\uc9d1\ud2b8\uc758 \ud070 \uc2e0\uc804\uc5d0\uc11c\ub294 \ud0d1\ubb38\uacfc \uc5f4\ub9b0 \ub730, \uae30\ub465\uc774 \uc9c0\ubd95\uc744 \ubc1b\uce58\ub294 \ubc29, \ub354 \uc548\ucabd\uc758 \uc131\uc18c\uac00 \uc911\uc694\ud55c \uacf5\uac04 \uc694\uc18c\uac00 \ub41c\ub2e4. \ubaa8\ub4e0 \ubd80\ubd84\uc774 \ud55c \ubc88\uc5d0 \uac19\uc740 \ubc1d\uae30\uc640 \uaddc\ubaa8\ub85c \ud3bc\uccd0\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc9c0\ub098\uac00\ub294 \uc21c\uc11c\uc5d0 \ub530\ub77c \ubab8\uc758 \uac10\uac01\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uce74\ub974\ub098\ud06c\uc758 \ud615\ud0dc\ub3c4 \uc774\ub7f0 \uc2e0\uc804 \uac74\ucd95\uc758 \uc6d0\ub9ac\uc640 \ud568\uaed8 \uc77d\uc744 \uc218 \uc788\ub2e4. \ub192\uc740 \ubb38\uc744 \ud1b5\uacfc\ud558\uace0 \ub113\uc740 \uacf3\uc5d0\uc11c \ub354 \uc870\ubc00\ud55c \uacf3\uc73c\ub85c \uc774\ub3d9\ud560 \ub54c \ubb34\uc5c7\uc774 \ub4dc\ub7ec\ub098\uace0 \uac00\ub824\uc9c0\ub294\uc9c0 \uc0dd\uac01\ud574 \ubcf4\uc790. \ud1b5\uce58\uc790\uc758 \uc774\ub984\uc744 \ubab0\ub77c\ub3c4 \uacf5\uac04\uc744 \uc5b4\ub5bb\uac8c \uacbd\ud5d8\ud558\uac8c \ud588\ub294\uc9c0\ubd80\ud130 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uc5f4\uc8fc\uc2e4\uc758 \uae30\ub465\uc740 \uac70\ub300\ud55c \uc7a5\uc2dd\ubb3c\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uc9c0\ubd95\uc744 \ubc1b\uce58\uace0 \ub0b4\ubd80\uc758 \ud1b5\ub85c\uc640 \uc2dc\uc57c\ub97c \ub098\ub208\ub2e4. \uc911\uc559 \ubd80\ubd84\uc744 \ub192\uac8c \ub9cc\ub4dc\ub294 \ubc29\uc2dd\uc740 \uc704\ucabd\uc5d0\uc11c \ube5b\uc774 \ub4e4\uc5b4\uc62c \uae38\uacfc\ub3c4 \uc5f0\uacb0\ub41c\ub2e4. \ub192\uc774\uc758 \ucc28\uc774\ub294 \uac89\uc73c\ub85c \ubcf4\uc774\ub294 \uc704\uc6a9\ubfd0 \uc544\ub2c8\ub77c \uc548\ucabd\uc758 \ubc1d\uae30\ub97c \ub9cc\ub4dc\ub294 \uc870\uac74\uc774\uc5c8\ub2e4. \uc624\ub298\uc740 \uc9c0\ubd95\uc774 \uc0ac\ub77c\uc9c4 \ubd80\ubd84\uc774 \ub9ce\uc544 \ud558\ub298\uc774 \ubc14\ub85c \ubcf4\uc778\ub2e4. \uadf8 \uc0c1\ud0dc\ub97c \ub2f9\uc2dc\uc5d0\ub3c4 \ub611\uac19\uc774 \ubc1d\uc558\ub358 \uacf5\uac04\uc73c\ub85c \ubc1b\uc544\ub4e4\uc774\uba74 \uc6d0\ub798\uc758 \uacbd\ud5d8\uc744 \ub193\uce5c\ub2e4. \ub0a8\uc740 \uae30\ub465 \uc0ac\uc774\uc5d0 \uc9c0\ubd95\uacfc \uadf8\ub9bc\uc790\ub97c \uc0c1\uc0c1\ud558\ub294 \uc77c\uc774 \ud544\uc694\ud558\ub2e4. \ubb34\uc5c7\uc774 \uc5c6\uc5b4\uc84c\ub294\uc9c0 \uc544\ub294 \uac83\uc774 \ub0a8\uc740 \uac83\uc744 \uc774\ud574\ud558\ub294 \ubc29\ubc95\uc774 \ub41c\ub2e4. \uc5f4\uc8fc\uc2e4\uc744 \uc124\uba85\ud558\ub294 \uc61b \uac74\ucd95 \ub2e8\uba74\ub3c4\ub294 \uc624\ub298 \uc720\uc801\uc5d0\uc11c \uc0ac\ub77c\uc9c4 \uc9c0\ubd95\uacfc \ub192\uc774\uc758 \uad00\uacc4\ub97c \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ub2e4\ub9cc \uadf8\ub7f0 \ub3c4\uba74\ub3c4 \ud2b9\uc815 \uc5f0\uad6c\uc790\uac00 \ub0a8\uc740 \ud754\uc801\uc744 \ud574\uc11d\ud55c \uc790\ub8cc\ub2e4. \ud604\uc7a5\uc758 \uc0ac\uc9c4\uacfc \uc7ac\uad6c\uc131 \uadf8\ub9bc\uc744 \uad6c\ubd84\ud574 \ud568\uaed8 \uc77d\uc73c\uba74, \ubb34\uc5c7\uc744 \ubcf4\uc558\uace0 \ubb34\uc5c7\uc744 \ubcf5\uc6d0\ud574 \uc0c1\uc0c1\ud588\ub294\uc9c0 \ub354 \uc815\ud655\ud558\uac8c \uc54c \uc218 \uc788\ub2e4. \uae30\ub465\uc758 \ud615\ud0dc\uc5d0\ub294 \ud30c\ud53c\ub8e8\uc2a4\ub098 \uc5f0\uaf43 \uac19\uc740 \uc2dd\ubb3c\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uc694\uc18c\uac00 \uc788\ub2e4. \ub3cc\uae30\ub465\uc744 \uc790\uc5f0\ubb3c\uc758 \ubaa8\uc591\uacfc \uc5f0\uacb0\ud55c \uac83\uc774\ub2e4. \uc2e0\uc804\uc758 \uc7a5\uc2dd\uc740 \ube44\uc5b4 \uc788\ub294 \ubcbd\uc744 \uc608\uc058\uac8c \ucc44\uc6b0\ub294 \ub370\uc11c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc885\uad50\uc801\uc73c\ub85c \uc774\ud574\ud55c \uc138\uacc4\ub97c \uac74\ucd95\uc758 \ud45c\uba74\uacfc \uad6c\uc870\uc5d0 \ub2f4\ub294\ub2e4. \ubcbd\uacfc \uae30\ub465\uc758 \uae00\uacfc \ubd80\uc870\uc5d0\ub294 \uc655\uacfc \uc2e0, \ubd09\ud5cc\uacfc \uc2b9\ub9ac\uc758 \uc774\uc57c\uae30\ub3c4 \ub0a8\ub294\ub2e4. \ud06c\uac8c \uc0c8\uacbc\ub2e4\ub294 \uc774\uc720\ub85c \ubaa8\ub4e0 \ub9d0\uc744 \uc911\ub9bd\uc801\uc778 \uc0ac\uc2e4\uc758 \ubcf4\uace0\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc11c\ub294 \uc548 \ub41c\ub2e4. \ub204\uac00 \uc5b4\ub5a4 \ubaa8\uc2b5\uc73c\ub85c \uae30\uc5b5\ub418\uace0 \uc2f6\uc5c8\ub294\uc9c0\uc758 \uc9c8\ubb38\uc774 \ud544\uc694\ud558\ub2e4. \uc2e0\uc804\uc740 \uc624\ub798\ub41c \uac74\ucd95\uc774\uba74\uc11c \uad8c\ub825\uc774 \ub0a8\uae34 \ubb38\uc11c\uc774\uae30\ub3c4 \ud558\ub2e4. \uae30\ub465\uacfc \ubcbd\uc744 \uc138\uc6b0\ub824\uba74 \ub3cc\uc744 \ub9c8\ub828\ud558\uace0 \uc6b4\ubc18\ud558\uace0 \uac00\uacf5\ud558\uba70 \ub9de\ucd94\ub294 \uacfc\uc815\uc774 \ud544\uc694\ud588\ub2e4. \uc7a5\uc2dd\uacfc \uae00\uc744 \uc0c8\uae30\ub294 \uc77c\ub3c4 \ub530\ub790\ub2e4. \uc655\uc758 \uc774\ub984\uc774 \ud06c\uac8c \ub0a8\uc740 \uc7a5\uc18c\ub77c\ub3c4 \uc2e4\uc81c \uc81c\uc791\uc740 \uc5ec\ub7ec \uc885\ub958\uc758 \ub178\ub3d9\uc774 \uc5f0\uacb0\ub41c \uacb0\uacfc\uc600\ub2e4. \uc644\uc131\ub41c \uaddc\ubaa8\ub294 \uadf8 \uc77c\uc744 \uc870\uc9c1\ud560 \uc218 \uc788\ub294 \uc790\uc6d0\uc758 \ud06c\uae30\uc640 \uad00\ub828\ub41c\ub2e4. \uc774\ub97c \uc548\ub2e4\uace0 \uc2e0\uc804\uc758 \uc544\ub984\ub2e4\uc6c0\uc744 \ud3ec\uae30\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc624\ud788\ub824 \uac10\ud0c4\uc758 \ub300\uc0c1\uc774 \ub113\uc5b4\uc9c4\ub2e4. \ud1b5\uce58\uc790\uc758 \uc758\ub3c4\uc640 \uc885\uad50\uc801 \uc758\ubbf8 \uc606\uc5d0 \uc7ac\ub8cc\ub97c \ub2e4\ub8ec \uc0ac\ub78c\ub4e4\uc758 \uae30\uc220\uc774 \ub4e4\uc5b4\uc628\ub2e4. \ub3cc\uc758 \ud070 \ub369\uc5b4\ub9ac\uac00 \uc815\uad50\ud55c \uacf5\uac04\uc774 \ub418\uae30\uae4c\uc9c0\uc758 \uacfc\uc815\uc744 \uc0dd\uac01\ud558\uba74 \uc6c0\uc9c1\uc784 \uc5c6\ub294 \uc720\uc801 \uc548\uc5d0 \ub9ce\uc740 \uc77c\uc774 \ubcf4\uc778\ub2e4. \uce74\ub974\ub098\ud06c\ub294 \uc9c0\uae08 \ub0a8\uc544 \uc788\ub294 \ubaa8\uc2b5\uacfc \ud55c\ub54c\uc758 \uc0ac\uc6a9\uc744 \ud568\uaed8 \uc77d\uc5b4\uc57c \ud558\ub294 \uc7a5\uc18c\ub2e4. \ud558\ub298\uc744 \ubc30\uacbd\uc73c\ub85c \uc120 \uae30\ub465\uc758 \uc7a5\uad00\uc740 \ud604\uc7ac\uc758 \uc720\uc801 \uacbd\ud5d8\uc774\uace0, \uc9c0\ubd95\uacfc \uc81c\ud55c\ub41c \ube5b \uc18d\uc758 \ud1b5\ub85c\ub294 \ub2e4\ub978 \uacbd\ud5d8\uc774\uc5c8\uc744 \uac83\uc774\ub2e4. \ub458 \uac00\uc6b4\ub370 \ud558\ub098\ub9cc\uc774 \uc9c4\uc9dc \uac10\uc0c1\uc774\ub77c\uace0 \uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uae30\ub465 \uc0ac\uc774\ub97c \ubc14\ub77c\ubcf4\uba70 \uc5b4\ub514\ub85c \uac78\uc5c8\uace0 \uc5b4\ub514\uc5d0\uc11c \uba48\ucd94\uc5c8\uc744\uc9c0 \uc0dd\uac01\ud574 \ubcf4\uc790. \uc5ec\ub7ec \uc655\uc758 \uc2dc\uac04\uc774 \uacb9\uce5c \uacf5\uac04\uc740 \uc2e0\uc559\uacfc \ud1b5\uce58, \ube5b\uacfc \uad6c\uc870\uac00 \ub9cc\ub09c \uacb0\uacfc\ub2e4. \uce74\ub974\ub098\ud06c\uc758 \ub3cc\uae30\ub465\uc740 \ud06c\uae30\ub97c \uc790\ub791\ud558\ub294 \ubb3c\uac74\uc778 \ub3d9\uc2dc\uc5d0 \uc0ac\ub78c\ub4e4\uc774 \uc138\uacc4\uc640 \uad8c\ub825\uc744 \uc5b4\ub5a4 \uc9c8\uc11c\ub85c \uacbd\ud5d8\ud558\uac8c \ud588\ub294\uc9c0 \uc804\ud558\ub294 \uc624\ub798\ub41c \uac74\ucd95\uc774\ub2e4."}, {"id": "la-traviata-violetta-party-and-silence", "title": "\u300e\ub77c \ud2b8\ub77c\ube44\uc544\ud0c0\u300f \u2014 \ucd95\ubc30\uac00 \ub05d\ub09c \ub4a4 \ube44\uc62c\ub808\ud0c0\uc5d0\uac8c \ub0a8\uc740 \uac83", "summary": "\ube44\uc62c\ub808\ud0c0\uc640 \uc54c\ud504\ub808\ub3c4\uc758 \ub9cc\ub0a8\u00b7\uc774\ubcc4\u00b7\uc7ac\ud68c\ub97c \ub300\ud45c \uc74c\uc545\uacfc \uc8fc\uc694 \uc904\uac70\ub9ac\ub85c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc74c\uc545", "categories": ["arts"], "url": "stories/la-traviata-violetta-party-and-silence/index.html", "image": "../media/la-traviata-violetta-party-and-silence.png", "alt": "\ud30c\ud2f0\uc758 \ubd88\ube5b\uc5d0\uc11c \uc870\uae08 \ub5a8\uc5b4\uc838 \ud3b8\uc9c0\uc640 \uaf43 \uacc1\uc5d0 \uc549\uc740 \ube44\uc62c\ub808\ud0c0\uc758 \uc0c1\uc0c1 \ubb34\ub300 \uc0bd\ud654", "text": "\u300e\ub77c \ud2b8\ub77c\ube44\uc544\ud0c0\u300f \u2014 \ucd95\ubc30\uac00 \ub05d\ub09c \ub4a4 \ube44\uc62c\ub808\ud0c0\uc5d0\uac8c \ub0a8\uc740 \uac83 \ud654\ub824\ud55c \ub178\ub798\uc640 \uc0ac\ub791 \ub4a4\uc5d0\uc11c \ub2e4\ub978 \uc0ac\ub78c\uc758 \ud3c9\ud310\uc744 \uac10\ub2f9\ud558\ub2e4 \ube44\uc62c\ub808\ud0c0\uc640 \uc54c\ud504\ub808\ub3c4\uc758 \ub9cc\ub0a8\u00b7\uc774\ubcc4\u00b7\uc7ac\ud68c\ub97c \ub300\ud45c \uc74c\uc545\uacfc \uc8fc\uc694 \uc904\uac70\ub9ac\ub85c \uc77d\uc2b5\ub2c8\ub2e4. \uc74c\uc545 \ubb38\ud654\uc640 \uc608\uc220 \uc794\uc744 \ub4e4\uace0 \uc990\uac70\uc6c0\uc744 \ub178\ub798\ud55c\ub2e4. \u300e\ub77c \ud2b8\ub77c\ube44\uc544\ud0c0\u300f\uc758 \ucd95\ubc30\uc758 \ub178\ub798\ub294 \uc791\ud488 \uc804\uccb4\ub97c \ubab0\ub77c\ub3c4 \uc775\uc219\ud55c \uc0ac\ub78c\uc774 \ub9ce\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \ud654\ub824\ud55c \ud30c\ud2f0\uc5d0\uc11c \uc2dc\uc791\ud55c \uc774\uc57c\uae30\ub294 \uac19\uc740 \ubc1d\uae30\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc0ac\ub78c\ub4e4 \uac00\uc6b4\ub370 \uc788\ub358 \ube44\uc62c\ub808\ud0c0\uac00 \uc810\uc810 \ud63c\uc790 \uac10\ub2f9\ud574\uc57c \ud560 \uc77c\ub4e4\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \ubca0\ub974\ub514\uac00 \uc791\uace1\ud558\uace0 \ud504\ub780\uccb4\uc2a4\ucf54 \ub9c8\ub9ac\uc544 \ud53c\uc544\ubca0\uac00 \ub300\ubcf8\uc744 \uc4f4 \uc624\ud398\ub77c\ub85c, 1853\ub144 \ubca0\ub124\uce58\uc544\uc5d0\uc11c \ucd08\uc5f0\ub418\uc5c8\ub2e4. \ub4a4\ub9c8\uc758 \u300e\ub3d9\ubc31\uaf43 \uc5ec\uc778\u300f\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uc774\uc57c\uae30\uc758 \uacc4\ubcf4\ub97c \uac00\uc9c4\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc8fc\uc694 \uc0ac\uac74\uacfc \ub9c8\uc9c0\ub9c9 \uc7ac\ud68c\uae4c\uc9c0 \uc18c\uac1c\ud55c\ub2e4. \ud30c\ub9ac\uc5d0\uc11c \uc0ac\uad50 \uc0dd\ud65c\uc744 \ud558\ub294 \ube44\uc62c\ub808\ud0c0\ub294 \ud654\ub824\ud55c \ubaa8\uc784\uc758 \uc911\uc2ec\uc774\ub2e4. \uadf8\ub7ec\ub098 \ubab8\uc740 \uc774\ubbf8 \ubcd1\ub4e4\uc5b4 \uc788\uace0, \uc0ac\ub78c\ub4e4\uc774 \uadf8\ub140\ub97c \uc5b4\ub5a4 \uc5ec\uc778\uc73c\ub85c \ud310\ub2e8\ud558\ub294\uc9c0\ub3c4 \uc0dd\ud65c\uc758 \uc77c\ubd80\ub2e4. \uc8fc\ubaa9\ubc1b\uace0 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc788\ub294 \uadf8\ub300\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc9c4\ub2e4\ub294 \uacbd\ud5d8\uc740 \uac19\uc9c0 \uc54a\ub2e4. \uc54c\ud504\ub808\ub3c4\ub294 \uc9c4\uc2ec\uc73c\ub85c \uadf8\ub140\ub97c \uc0ac\ub791\ud55c\ub2e4\uace0 \ub9d0\ud55c\ub2e4. \ube44\uc62c\ub808\ud0c0\uc5d0\uac8c\ub294 \uc775\uc219\ud55c \uad00\uacc4\uc640 \ub2e4\ub978 \uac00\ub2a5\uc131\ucc98\ub7fc \ub2e4\uac00\uc628\ub2e4. \ub450 \uc0ac\ub78c\uc774 \ud568\uaed8 \ubd80\ub974\ub294 \ucd95\ubc30\ub294 \uc990\uac81\uc9c0\ub9cc, \uc774\ud6c4 \ud63c\uc790 \ub0a8\uc740 \uadf8\ub140\uac00 \uc5b4\ub5a4 \ub9c8\uc74c\uc744 \ub4e3\uac8c \ub418\ub294\uc9c0\ub3c4 \uc911\uc694\ud558\ub2e4. \ubb34\ub300\uc758 \uad70\uc911\uc774 \uc0ac\ub77c\uc9c0\uba74 \ud654\ub824\ud568 \ub4a4\uc758 \ub9dd\uc124\uc784\uc774 \ub4dc\ub7ec\ub09c\ub2e4. 1\ub9c9\uc758 \ub05d\uc5d0\uc11c \ube44\uc62c\ub808\ud0c0\ub294 \uc0ac\ub791\uc758 \uac00\ub2a5\uc131\uc744 \uc0dd\uac01\ud558\ub2e4\uac00 \ub2e4\uc2dc \uc790\uc720\ub86d\uac8c \uc0b4\uaca0\ub2e4\uace0 \ub178\ub798\ud55c\ub2e4. \u300c\uc5b8\uc81c\ub098 \uc790\uc720\ub86d\uac8c\u300d\uc758 \ud654\ub824\ud558\uace0 \ube60\ub978 \uc74c\uc545\uc740 \uae30\uad50\uc758 \uc804\uc2dc\uc7a5\ucc98\ub7fc \ub4e4\ub9b4 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc904\uac70\ub9ac\ub97c \uc54c\uba74 \uadf8\uac83\uc774 \ub2e8\uc21c\ud788 \uc2e0\ub098\ub294 \uc120\uc5b8\ub9cc\uc740 \uc544\ub2d8\uc744 \ub290\ub07c\uac8c \ub41c\ub2e4. \uc0c8\ub85c\uc6b4 \uac10\uc815\uc744 \ubc1b\uc544\ub4e4\uc774\uace0 \uc2f6\uc740 \ub9c8\uc74c\uacfc \uc775\uc219\ud55c \uc0dd\ud65c\ub85c \ub3cc\uc544\uac00\ub824\ub294 \ub9c8\uc74c\uc774 \ubd80\ub52a\uce5c\ub2e4. \ubaa9\uc18c\ub9ac\uac00 \ub192\uace0 \ube60\ub974\uac8c \uc6c0\uc9c1\uc778\ub2e4\uace0 \uac10\uc815\uae4c\uc9c0 \ub2e8\uc21c\ud55c \uae30\uc068\uc778 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc74c\uc545\uc740 \uadf8\ub140\uc758 \ud655\uc2e0\uc744 \ubcf4\uc5ec \uc8fc\uba74\uc11c \uadf8 \ud655\uc2e0\uc744 \uacc4\uc18d \ubc00\uc5b4\ubd99\uc5ec\uc57c \ud558\ub294 \ubd88\uc548\ub3c4 \ub4e3\uac8c \ud55c\ub2e4. \ud55c \uc778\ubb3c\uc758 \uc548\ucabd\uc5d0\uc11c \ub300\ud654\uac00 \ubc8c\uc5b4\uc9c0\ub294 \uc7a5\uba74\uc774\ub2e4. \ub450 \uc0ac\ub78c\uc740 \ud30c\ub9ac\ub97c \ub5a0\ub098 \ud568\uaed8 \uc9c0\ub0b8\ub2e4. \ud558\uc9c0\ub9cc \uc870\uc6a9\ud55c \uc0ac\ub791\ub9cc\uc73c\ub85c \uc0dd\ud65c\ube44\uac00 \uc0dd\uae30\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ube44\uc62c\ub808\ud0c0\uac00 \uc7ac\uc0b0\uc744 \uc815\ub9ac\ud558\uba70 \uadf8 \uc0dd\ud65c\uc744 \uc720\uc9c0\ud558\uace0 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c\ud504\ub808\ub3c4\uac00 \uc54c\uac8c \ub41c\ub2e4. \ub0ad\ub9cc\uc801\uc778 \uacf5\uac04\uc5d0\ub3c4 \ub204\uad70\uac00\uac00 \uac10\ub2f9\ud55c \ube44\uc6a9\uc774 \uc788\ub2e4. \uc54c\ud504\ub808\ub3c4\uac00 \ud30c\ub9ac\ub85c \uac04 \uc0ac\uc774 \uadf8\uc758 \uc544\ubc84\uc9c0 \uc81c\ub974\ubabd\uc774 \ucc3e\uc544\uc628\ub2e4. \uadf8\ub294 \ube44\uc62c\ub808\ud0c0\uc640\uc758 \uad00\uacc4\uac00 \uc790\uae30 \uac00\uc871\uc758 \uba85\uc608\uc640 \ubbf8\ub798\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4\uace0 \ub9d0\ud55c\ub2e4. \uc5ec\uae30\uc11c \ubb38\uc81c\ub294 \ub450 \uc0ac\ub78c\uc758 \ub9c8\uc74c\uc774 \uc2dd\uc5c8\uae30 \ub54c\ubb38\uc774 \uc544\ub2c8\ub2e4. \uc8fc\ubcc0 \uc0ac\ud68c\uac00 \uc5b4\ub5a4 \uad00\uacc4\ub97c \ubc1b\uc544\ub4e4\uc774\ub294\uc9c0\uc758 \uae30\uc900\uc774 \uc9d1 \uc548\uc73c\ub85c \ub4e4\uc5b4\uc628\ub2e4. \uc81c\ub974\ubabd\uc740 \ube44\uc62c\ub808\ud0c0\uc5d0\uac8c \uc544\ub4e4\uacfc \ud5e4\uc5b4\uc838 \ub2ec\ub77c\uace0 \uc694\uad6c\ud55c\ub2e4. \uc790\uc2e0\uc758 \uac00\uc871\uc744 \uc9c0\ud0a4\ub824\ub294 \uc544\ubc84\uc9c0\uc758 \ub9d0\ub85c \ub2e4\uac00\uc624\uc9c0\ub9cc, \uadf8 \uc694\uad6c\uc758 \ube44\uc6a9\uc740 \ube44\uc62c\ub808\ud0c0\uc5d0\uac8c \ub3cc\uc544\uac04\ub2e4. \uadf8\ub140\uac00 \uc5bc\ub9c8\ub098 \uc9c4\uc2ec\uc778\uc9c0\uc640 \ubcc4\uac1c\ub85c \uacfc\uac70\uc640 \ud3c9\ud310 \ub54c\ubb38\uc5d0 \uc591\ubcf4\ud574\uc57c \ud560 \uc0ac\ub78c\uc73c\ub85c \ucde8\uae09\ub41c\ub2e4. \uc61b \ud574\uc124\uc11c\uc758 \ub3c4\ub355\uc801\uc778 \ud3c9\uac00\ub97c \uadf8\ub300\ub85c \ub530\ub974\uba74 \uc774 \uc7a5\uba74\uc744 \uadf8\ub140\uac00 \ub9c8\uce68\ub0b4 \uc62c\ubc14\ub978 \uae38\uc744 \ud0dd\ud588\ub2e4\uace0 \uc815\ub9ac\ud558\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uc624\ub298\uc758 \ub3c5\uc790\ub294 \ub204\uac00 \ud76c\uc0dd\uc744 \uc694\uad6c\ud560 \uc218 \uc788\uace0 \ub204\uac00 \uc124\uba85\uc870\ucc28 \ud558\uc9c0 \ubabb\ud55c \ucc44 \ub5a0\ub098\uc57c \ud558\ub294\uc9c0 \ubb3c\uc744 \uc218 \uc788\ub2e4. \uadf8\ub140\uac00 \uc0ac\ub791\uc744 \ub35c \ud574\uc11c \ub5a0\ub098\ub294 \uac83\uc774 \uc544\ub2c8\ub77c\ub294 \uc0ac\uc2e4\uc774 \uc774\ubcc4\uc744 \ub354 \uc544\ud504\uac8c \ub9cc\ub4e0\ub2e4. \ube44\uc62c\ub808\ud0c0\ub294 \uc54c\ud504\ub808\ub3c4\ub97c \ub5a0\ub09c\ub2e4. \uc54c\ud504\ub808\ub3c4\ub294 \uadf8 \uc774\uc720\ub97c \ubaa8\ub974\uace0 \ubc30\uc2e0\ub2f9\ud588\ub2e4\uace0 \uc5ec\uae34\ub2e4. \uad00\uac1d\uc774 \uc544\ub294 \uc0ac\uc815\uacfc \uc778\ubb3c\uc774 \uc544\ub294 \uc0ac\uc815\uc758 \ucc28\uc774\uac00 \ud070 \uac10\uc815\uc744 \ub9cc\ub4e0\ub2e4. \ud558\uace0 \uc2f6\uc740 \ub9d0\uacfc \ud560 \uc218 \uc788\ub294 \ub9d0 \uc0ac\uc774\uc5d0 \ub193\uc778 \uce68\ubb35\uc774 \ub450 \uc0ac\ub78c\uc758 \uad00\uacc4\ub97c \ubc14\uafbc\ub2e4. \uc81c\ub974\ubabd\uc774 \uc544\ub4e4\uc5d0\uac8c \uace0\ud5a5\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\uba70 \ubd80\ub974\ub294 \ub178\ub798\ub3c4 \uc774 \uc548\uc5d0\uc11c \ub4e4\ub9b0\ub2e4. \uc544\ubc84\uc9c0\uc5d0\uac8c\ub294 \ub3cc\uc544\uac08 \uc9d1\uc774 \uc704\uc548\uc774\uc9c0\ub9cc, \ube44\uc62c\ub808\ud0c0\uc5d0\uac8c \uac19\uc740 \uc790\ub9ac\uac00 \uc8fc\uc5b4\uc9c4 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubd80\ub4dc\ub7ec\uc6b4 \uc120\uc728\uacfc \ub530\ub73b\ud55c \uae30\uc5b5\uc774 \ubaa8\ub450\uc5d0\uac8c \ub611\uac19\uc774 \uc5f4\ub824 \uc788\uc9c0 \uc54a\ub2e4\ub294 \uc810\uae4c\uc9c0 \uc0dd\uac01\ud558\uba74 \uc74c\uc545\uc774 \ub2e4\ub978 \ube5b\uc73c\ub85c \ub4e4\ub9b0\ub2e4. \ud50c\ub85c\ub77c\uc758 \ubaa8\uc784\uc5d0\uc11c \ub2e4\uc2dc \ub9cc\ub09c \uc54c\ud504\ub808\ub3c4\ub294 \ube44\uc62c\ub808\ud0c0\ub97c \uacf5\uac1c\uc801\uc73c\ub85c \ubaa8\uc695\ud55c\ub2e4. \uadf8\ub294 \uc790\uc2e0\uc774 \uc54c\uace0 \uc788\ub294 \uc774\uc57c\uae30\ub9cc\uc73c\ub85c \ud589\ub3d9\ud55c\ub2e4. \uc55e\uc758 \ud30c\ud2f0\uac00 \uc0ac\ub791\uc758 \uc2dc\uc791\uc774\uc5c8\ub2e4\uba74 \uc774\ubc88\uc758 \uad70\uc911\uc740 \ud55c \uc0ac\ub78c\uc758 \uc0c1\ucc98\ub97c \uc9c0\ucf1c\ubcf4\ub294 \uc790\ub9ac\uac00 \ub41c\ub2e4. \uac19\uc740 \ud654\ub824\ud568\uc774 \ub2e4\ub978 \uc5ed\ud560\uc744 \ud55c\ub2e4. \uadf8 \uc7a5\uba74\uc744 \uc54c\ud504\ub808\ub3c4\uac00 \uc0ac\ub791\uc774 \ub108\ubb34 \ucee4\uc11c \uc5b4\uca54 \uc218 \uc5c6\uc5c8\ub2e4\ub294 \ub9d0\ub85c\ub9cc \uac10\uc2f8\uae30\ub294 \uc5b4\ub835\ub2e4. \uc798\ubabb\ub41c \ud310\ub2e8\uc774 \uc2e4\uc81c\ub85c \uc0c1\ub300\ub97c \ub2e4\uce58\uac8c \ud55c\ub2e4. \ub4a4\ub2a6\uac8c \uc9c4\uc2e4\uc744 \uc54c\uac8c \ub41c\ub2e4\uace0 \uc774\ubbf8 \uc0dd\uae34 \uace0\ud1b5\uc774 \uc790\ub3d9\uc73c\ub85c \uc9c0\uc6cc\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc624\ud398\ub77c\uc758 \ube44\uadf9\uc740 \uc5ec\uae30\uc11c \ub2e8\uc21c\ud55c \uc624\ud574\ubcf4\ub2e4 \ub354 \ubb34\uac70\uc6b4 \uacb0\uacfc\ub97c \uc5bb\ub294\ub2e4. \ub9c8\uc9c0\ub9c9\uc5d0 \ube44\uc62c\ub808\ud0c0\uc758 \ubcd1\uc740 \uae4a\uc5b4\uc9c0\uace0, \uc54c\ud504\ub808\ub3c4\ub294 \uc0ac\uc2e4\uc744 \uc54c\uace0 \ucc3e\uc544\uc628\ub2e4. \uc11c\ub85c\uc758 \ub9c8\uc74c\uc774 \ub2e4\uc2dc \uc774\uc5b4\uc9c0\ub294 \uc21c\uac04\uc774\uc9c0\ub9cc \ub0a8\uc740 \uc2dc\uac04\uae4c\uc9c0 \ub418\ub3cc\ub9b4 \uc218\ub294 \uc5c6\ub2e4. \uc6a9\uc11c\uc640 \uc7ac\ud68c\uac00 \uc774\ub8e8\uc5b4\uc838\ub3c4 \uac74\uac15\uc774 \uae30\uc801\ucc98\ub7fc \ud68c\ubcf5\ub418\ub294 \uacb0\ub9d0\uc740 \uc544\ub2c8\ub2e4. \ube44\uc62c\ub808\ud0c0\ub294 \uacb0\uad6d \uc8fd\ub294\ub2e4. \uadf8\ub798\uc11c \uc774 \uc791\ud488\uc740 \uc0ac\ub791\uc774 \ucda9\ubd84\ud558\uba74 \uc0ac\ud68c\uc758 \ud310\ub2e8\uacfc \ubab8\uc758 \ud55c\uacc4\ub97c \ubaa8\ub450 \ub118\ub294\ub2e4\ub294 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \uc0ac\ub791\uc744 \uc778\uc815\ud558\ub294 \ub370\uc5d0 \ub108\ubb34 \uc624\ub79c \uc2dc\uac04\uc774 \uac78\ub838\uace0, \uadf8\ub3d9\uc548 \ud55c \uc0ac\ub78c\uc774 \uac10\ub2f9\ud55c \ub300\uac00\uac00 \uc788\uc5c8\ub2e4\ub294 \uc774\uc57c\uae30\ub2e4. \ub9c8\uc9c0\ub9c9\uc758 \uac00\uae4c\uc6b4 \ubaa9\uc18c\ub9ac\ub294 \ucc98\uc74c\uc758 \ud070 \ud30c\ud2f0\uc640 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uad00\uac1d\uc744 \ubd99\uc7a1\ub294\ub2e4. \uc720\uba85\ud55c \ub178\ub798\ub294 \uc791\ud488\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \uc88b\uc740 \ubb38\uc774\ub2e4. \ucd95\ubc30\uc758 \ub178\ub798\ub97c \uba3c\uc800 \uc88b\uc544\ud574\ub3c4 \uc88b\uace0, \ube44\uc62c\ub808\ud0c0\uc758 \ud654\ub824\ud55c \uc544\ub9ac\uc544\uc5d0 \ub180\ub77c\uc11c \ub4e3\uae30 \uc2dc\uc791\ud574\ub3c4 \uc88b\ub2e4. \ub2e4\ub9cc \uc904\uac70\ub9ac\ub97c \uc54c\uac8c \ub41c \ub4a4\uc5d0\ub294 \uadf8 \ub178\ub798\uac00 \ub204\uad6c\uc758 \uc5b4\ub5a4 \uc21c\uac04\uc778\uc9c0 \ud55c \ubc88 \ub354 \ub4e4\uc744 \uc218 \uc788\ub2e4. \uc775\uc219\ud55c \uc120\uc728 \uc548\uc5d0 \ub2e4\ub978 \ud45c\uc815\uc774 \uc0dd\uae34\ub2e4. \ub2e4\uc2dc \uccab \ud30c\ud2f0\ub85c \ub3cc\uc544\uac00 \ubcf4\uba74 \uc0ac\ub78c\ub4e4 \uac00\uc6b4\ub370 \uc6c3\ub294 \ube44\uc62c\ub808\ud0c0\uac00 \ubcf4\uc778\ub2e4. \uad00\uac1d\uc740 \uc774\uc81c \uadf8\ub140\uc5d0\uac8c \ub0a8\uc740 \uc2dc\uac04\uc744 \uc870\uae08 \uc54c\uace0 \uc788\ub2e4. \uadf8\ub798\uc11c \uadf8 \uc990\uac70\uc6c0\uc774 \ub35c \uc544\ub984\ub2e4\uc6cc\uc9c0\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ub354 \uc9e7\uace0 \uc18c\uc911\ud558\uac8c \ub4e4\ub9b4 \uc218 \uc788\ub2e4. \u300e\ub77c \ud2b8\ub77c\ube44\uc544\ud0c0\u300f\ub294 \ud654\ub824\ud55c \ubaa9\uc18c\ub9ac \ub4a4\uc5d0 \uc788\ub294 \ud55c \uc0ac\ub78c\uc744 \ub05d\uae4c\uc9c0 \ub4e3\uac8c \ud558\ub294 \uc624\ud398\ub77c\ub2e4."}, {"id": "las-meninas-painter-mirror-and-viewer", "title": "\u300e\uc2dc\ub140\ub4e4\u300f \u2014 \uadf8\ub9bc \uc18d \uc0ac\ub78c\ub4e4\uc740 \ub204\uad6c\ub97c \ubcf4\uace0 \uc788\uc744\uae4c", "summary": "\ubca8\ub77c\uc2a4\ucf00\uc2a4\uc758 \uc2e4\uc81c \uc791\ud488 \ub3c4\ud310\uc744 \ub530\ub77c \uc2dc\uc120\uacfc \uac70\uc6b8, \ubcf4\uc774\uc9c0 \uc54a\ub294 \uce94\ubc84\uc2a4\uc758 \ub300\uc0c1\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/las-meninas-painter-mirror-and-viewer/index.html", "image": "../media/las-meninas-painter-mirror-and-viewer.jpg", "alt": "\ud654\uac00 \ubca8\ub77c\uc2a4\ucf00\uc2a4\uc640 \ub9c8\ub974\uac00\ub9ac\ud0c0 \uacf5\uc8fc, \uc2dc\ub140\ub4e4\uacfc \ub4a4\ucabd \uac70\uc6b8\uc774 \uc788\ub294 \uc2dc\ub140\ub4e4\uc758 \uc2e4\uc81c \uc791\ud488 \ub3c4\ud310", "text": "\u300e\uc2dc\ub140\ub4e4\u300f \u2014 \uadf8\ub9bc \uc18d \uc0ac\ub78c\ub4e4\uc740 \ub204\uad6c\ub97c \ubcf4\uace0 \uc788\uc744\uae4c \uacf5\uc8fc\uc640 \ud654\uac00, \uac70\uc6b8 \ub4a4\uc5d0\uc11c \uad00\ub78c\uc790\uc758 \uc790\ub9ac\uac00 \ubc14\ub00c\ub2e4 \ubca8\ub77c\uc2a4\ucf00\uc2a4\uc758 \uc2e4\uc81c \uc791\ud488 \ub3c4\ud310\uc744 \ub530\ub77c \uc2dc\uc120\uacfc \uac70\uc6b8, \ubcf4\uc774\uc9c0 \uc54a\ub294 \uce94\ubc84\uc2a4\uc758 \ub300\uc0c1\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \ud654\uac00\uac00 \ubd93\uc744 \ub4e4\uace0 \uc6b0\ub9ac \ucabd\uc744 \ubcf8\ub2e4. \ud654\uba74 \uac00\uc6b4\ub370\uc758 \uc5b4\ub9b0 \uacf5\uc8fc\ub3c4, \uadf8 \uacc1\uc758 \uba87\uba87 \uc778\ubb3c\ub3c4 \uadf8\ub9bc \ubc14\uae65\uc744 \ubc14\ub77c\ubcf4\ub294 \ub4ef\ud558\ub2e4. \u300e\uc2dc\ub140\ub4e4\u300f\uc744 \ubcf4\uace0 \uc788\uc73c\uba74 \uc5b4\ub290 \uc21c\uac04 \uc774\uc0c1\ud55c \ub290\ub08c\uc774 \uc0dd\uae34\ub2e4. \ub0b4\uac00 \uadf8\ub9bc\uc744 \ubcf4\ub294 \uac83\uc77c\uae4c, \uadf8\ub9bc \uc18d \uc0ac\ub78c\ub4e4\uc774 \ub098\ub97c \ubcf4\uace0 \uc788\ub294 \uac83\uc77c\uae4c. \ubca8\ub77c\uc2a4\ucf00\uc2a4\uac00 1656\ub144 \ubb34\ub835 \uadf8\ub9b0 \uc774 \uc791\ud488\uc740 \uc2a4\ud398\uc778 \uad81\uc815\uc758 \uc7a5\uba74\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc2e4\uc81c \uc791\ud488\uc744 \uc61b \ubbf8\uc220\uc11c\uc5d0 \ubcf5\uc81c\ud55c \ub3c4\ud310\uc744 \ud568\uaed8 \ubcf4\uba70, \uc5b4\ub824\uc6b4 \uc0c1\uc9d5\uc758 \uc815\ub2f5\uc744 \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc2dc\uc120\uc774 \uc6c0\uc9c1\uc774\ub294 \uae38\uc744 \ub530\ub77c\uac00 \ubcf4\uc790. \ucc38\uace0\ud55c \ud574\uc124\uc740 S. L. \ubca4\uc218\uc804\uc758 \u300e\ubca8\ub77c\uc2a4\ucf00\uc2a4\u300f\ub2e4. \uadf8\ub9bc \ud55c\uac00\uc6b4\ub370\uc5d0\ub294 \uc5b4\ub9b0 \ub9c8\ub974\uac00\ub9ac\ud0c0 \uacf5\uc8fc\uac00 \uc788\ub2e4. \ubc1d\uc740 \ub4dc\ub808\uc2a4\uc640 \uc5bc\uad74\uc5d0 \uc2dc\uc120\uc774 \uba3c\uc800 \uba38\ubb38\ub2e4. \uc591\uc606\uc758 \uc2dc\ub140\ub4e4\uc774 \uacf5\uc8fc\uc5d0\uac8c \uc8fc\uc758\ub97c \uae30\uc6b8\uc774\uace0, \uc8fc\ubcc0\uc5d0\ub294 \uad81\uc815\uc758 \uc5ec\ub7ec \uc778\ubb3c\uc774 \ud568\uaed8 \uc788\ub2e4. \uc81c\ubaa9\uc740 \uc2dc\ub140\ub4e4\uc744 \uac00\ub9ac\ud0a4\uc9c0\ub9cc \ud55c \uc0ac\ub78c\uc758 \ucd08\uc0c1\ucc98\ub7fc \ub2e8\uc21c\ud558\uac8c \uc815\ub9ac\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc774 \uc791\uc740 \ucc28\uc774\uac00 \uadf8\ub9bc\uc758 \uc7ac\ubbf8\ub97c \uc5f0\ub2e4. \ub204\uac00 \uac00\uc7a5 \uc911\uc694\ud558\uace0 \ub204\uac00 \ubc30\uacbd\uc778\uc9c0 \ucc98\uc74c\uc5d0\ub294 \uba85\ud655\ud574 \ubcf4\uc774\ub2e4\uac00, \uc870\uae08 \ub354 \ubcf4\uba74 \ub2e4\ub978 \uc778\ubb3c\uc758 \uc2dc\uc120\uacfc \ub3d9\uc791\uc774 \uc7a5\uba74\uc744 \uc6c0\uc9c1\uc778\ub2e4. \uad81\uc815\uc758 \uc704\uacc4\ub294 \ubd84\uba85\ud788 \uc874\uc7ac\ud558\uc9c0\ub9cc \uadf8\ub9bc\uc758 \uc774\uc57c\uae30\ub294 \ud55c \uc0ac\ub78c\uc5d0\uac8c\ub9cc \ub3c5\uc810\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc790\ub9ac\uc758 \uc0ac\ub78c\ub4e4\uc774 \uac19\uc740 \uc21c\uac04\uc5d0 \ub4e4\uc5b4 \uc788\ub2e4. \ud654\uba74 \uc67c\ucabd\uc5d0 \ucee4\ub2e4\ub780 \uce94\ubc84\uc2a4\uc758 \ub4a4\ucabd\uc774 \ubcf4\uc778\ub2e4. \uadf8 \uc55e\uc5d0 \ud654\uac00 \uc790\uc2e0\uc774 \uc11c \uc788\ub2e4. \uc6b0\ub9ac\uac00 \ubcfc \uc218 \uc788\ub294 \uac83\uc740 \uadf8\uac00 \uc791\uc5c5\ud55c\ub2e4\ub294 \uc0ac\uc2e4\uc774\uc9c0 \uadf8 \uc704\uc5d0 \ubb34\uc5c7\uc774 \uadf8\ub824\uc838 \uc788\ub294\uc9c0\ub294 \uc544\ub2c8\ub2e4. \ud575\uc2ec\uc801\uc778 \uc791\uc5c5\ubb3c \ud558\ub098\uac00 \uc624\ud788\ub824 \uad00\ub78c\uc790\uc758 \ub208\uc5d0\uc11c \uac00\ub824\uc838 \uc788\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294 \uce94\ubc84\uc2a4 \ub54c\ubb38\uc5d0 \uad81\uae08\uc99d\uc774 \uc0dd\uae34\ub2e4. \ud654\uac00\ub294 \uacf5\uc8fc\ub97c \uadf8\ub9ac\ub294 \uc911\uc77c\uae4c, \uc6b0\ub9ac \ucabd\uc5d0 \uc788\ub294 \ub204\uad70\uac00\ub97c \uadf8\ub9ac\ub294 \uc911\uc77c\uae4c. \uadf8\ub9bc\uc774 \ub108\ubb34 \uc815\uad50\ud574 \uc815\ub2f5\ub3c4 \uace7 \ubcf4\uc77c \uac83 \uac19\uc9c0\ub9cc, \ud544\uc694\ud55c \uc815\ubcf4\ub294 \uc77c\ubd80\ub7ec \ud654\uba74\uc758 \ub2e4\ub978 \ubc29\ud5a5\uc5d0 \ub193\uc5ec \uc788\ub2e4. \ubcf4\uc774\ub294 \uac83\ub9cc\uc774 \uc544\ub2c8\ub77c \uac00\ub824\uc9c4 \uba74\ub3c4 \uc774\uc57c\uae30\uc758 \uc7a5\uce58\uac00 \ub41c\ub2e4. \ub4a4\ucabd \ubcbd\uc5d0\ub294 \uc655 \ud3a0\ub9ac\ud398 4\uc138\uc640 \uc655\ube44 \ub9c8\ub9ac\uc544\ub098\uc758 \ubaa8\uc2b5\uc73c\ub85c \uc77d\ud788\ub294 \uc791\uc740 \ubc18\uc601\uc774 \uc788\ub2e4. \uacf5\uc8fc\uc758 \ubd80\ubaa8\uc774\uba70 \uad81\uc815\uc758 \uc911\uc2ec\uc778 \uc778\ubb3c\ub4e4\uc774 \uc815\uc791 \ud654\uba74\uc5d0\uc11c \uac00\uc7a5 \ud06c\uc9c0 \uc54a\ub2e4. \uadf8\ub4e4\uc740 \uac70\uc6b8\uc758 \uc791\uc740 \ube5b\uc73c\ub85c \ub4e4\uc5b4\uc628\ub2e4. \ud06c\uae30\uc640 \uad8c\uc704\uac00 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ubc30\uce58\ub418\uc9c0 \uc54a\ub294 \uc148\uc774\ub2e4. \ubca4\uc218\uc804\uc740 \ud654\uac00\uac00 \uc655\uacfc \uc655\ube44\uc758 \ucd08\uc0c1\uc744 \uadf8\ub9ac\ub294 \uc7a5\uba74\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \ud558\uc9c0\ub9cc \ubcf4\uc774\uc9c0 \uc54a\ub294 \uce94\ubc84\uc2a4\uc5d0 \ubb34\uc5c7\uc774 \uc788\ub294\uc9c0, \ubc18\uc601\uacfc \uadf8\ub9bc \ubc14\uae65\uc758 \uc704\uce58\ub97c \uc5b4\ub5bb\uac8c \uc774\ud574\ud560\uc9c0\ub294 \ud574\uc11d\uc758 \ubb38\uc81c\ub97c \ub0a8\uae34\ub2e4. \uc800\uc790\uc758 \uc124\uba85\uc744 \uc77d\uc744 \uc218\ub294 \uc788\uc5b4\ub3c4 \uce94\ubc84\uc2a4\uc758 \uc55e\uba74\uc744 \uc2e4\uc81c\ub85c \ud655\uc778\ud55c \uc0ac\uc2e4\ucc98\ub7fc \ub9d0\ud558\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \ub9cc\uc57d \uc655\uacfc \uc655\ube44\uac00 \uadf8\ub9bc \ubc14\uae65\uc758 \uc774\ucabd\uc5d0 \uc788\ub2e4\uba74, \uad00\ub78c\uc790\ub294 \uadf8\ub4e4\uacfc \ube44\uc2b7\ud55c \uc704\uce58\uc5d0\uc11c \ubc29\uc744 \ubcf4\uac8c \ub41c\ub2e4. \uadf8\ub798\uc11c \uadf8\ub9bc \uc18d \uc778\ubb3c\uc758 \uc2dc\uc120\uc774 \uc6b0\ub9ac\uc5d0\uac8c \ub2ff\ub294 \ub4ef\ud558\ub2e4. \ubcf4\ub294 \uc0ac\ub78c\uc758 \uc790\ub9ac\uac00 \uad6c\uacbd\uafbc\uc758 \uc790\ub9ac\ub9cc\uc774 \uc544\ub2c8\ub77c \uc7a5\uba74\uc744 \uc131\ub9bd\uc2dc\ud0a4\ub294 \uc790\ub9ac\ub85c \ub2ec\ub77c\uc9c4\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc2e4\uc81c\ub85c \uad00\ub78c\uac1d \ud55c \uc0ac\ub78c\uc774 \uc655\uc774 \ub41c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub9bc\uc774 \uc2dc\uc120\uc744 \ubc30\uce58\ud558\ub294 \ubc29\uc2dd\uc774 \uadf8\ub7f0 \uc5ed\ud560\uc744 \uc0c1\uc0c1\ud558\uac8c \ud55c\ub2e4\ub294 \uac83\uc774\ub2e4. \uc6b0\ub9ac\ub294 \uce94\ubc84\uc2a4 \ubc16\uc5d0 \uc788\uc73c\uba74\uc11c\ub3c4 \uadf8 \ubc29\uc758 \uad00\uacc4 \uc548\uc73c\ub85c \ucd08\ub300\ub41c\ub2e4. \uc0ac\ub78c\ub4e4\uc758 \uc774\ub984\uc744 \ubaa8\ub450 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uc774 \ub290\ub08c\uc740 \uacbd\ud5d8\ud560 \uc218 \uc788\ub2e4. \ub4a4\uc758 \ubb38\uc5d0\ub294 \ub610 \ub2e4\ub978 \uc778\ubb3c\uc774 \uc11c \uc788\uace0 \ubc1d\uc740 \uacf5\uac04\uc774 \uc5f4\ub9b0\ub2e4. \uadf8\ub9bc \uc548\uc5d0 \uac70\uc6b8\ub9cc \uc788\uc5c8\ub2e4\uba74 \uc2dc\uc120\uc774 \ubcbd\uc5d0\uc11c \uba48\ucd9c \uac83 \uac19\uc740\ub370, \ubb38\uc740 \uadf8 \ub4a4\uc5d0\ub3c4 \uae38\uc774 \uc788\ub2e4\uace0 \ub290\ub07c\uac8c \ud55c\ub2e4. \uac00\uae4c\uc6b4 \uacf5\uc8fc\uc640 \uba3c \ubb38 \uc0ac\uc774\uc5d0 \uacf5\uae30\uc640 \uac70\ub9ac\uac00 \uc0dd\uae34\ub2e4. \ubc1d\uc740 \ubd80\ubd84\uc774 \uc5ec\ub7ec \uacf3\uc5d0 \ub098\ub258\uc5b4 \uc788\uc5b4\uc11c \ub208\uc740 \uc55e\uacfc \ub4a4\ub97c \uc624\uac04\ub2e4. \uacf5\uc8fc\uc758 \uc5bc\uad74\uc744 \ubcf8 \ub4a4 \ubb38\uac00\ub85c \uac00\uace0, \ub2e4\uc2dc \ud654\uac00\uc758 \uc5bc\uad74\uacfc \uac70\uc6b8\ub85c \ub3cc\uc544\uc628\ub2e4. \uc2e4\uc81c \uacf5\uac04\uc744 \ub611\uac19\uc774 \uc7ac\ud604\ud558\ub294 \ub370\ub9cc \ubaa9\uc801\uc774 \uc788\uc5c8\ub2e4\uba74 \ud544\uc694 \uc5c6\uc5b4 \ubcf4\uc77c \uc218 \uc788\ub294 \uc120\ud0dd\ub4e4\uc774 \uad00\ub78c\uc758 \uc21c\uc11c\ub97c \ub9cc\ub4e0\ub2e4. \ubc29\uc740 \ubc30\uacbd\uc774 \uc544\ub2c8\ub77c \ub208\uc744 \uc774\ub044\ub294 \uad6c\uc870\uac00 \ub41c\ub2e4. \ubca8\ub77c\uc2a4\ucf00\uc2a4\ub294 \ub2e4\ub978 \uc0ac\ub78c\uc758 \ucd08\uc0c1\uc744 \uadf8\ub9ac\ub294 \uc0ac\ub78c\uc73c\ub85c \uadf8\ub9bc \uc548\uc5d0 \ubaa8\uc2b5\uc744 \ub0a8\uacbc\ub2e4. \ub2e8\uc21c\ud788 \uc791\uc5c5\uc790\uc758 \uc190\ub9cc \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ubd93\uc744 \ub4e0 \uc790\uc2e0\uc758 \ubab8\uc744 \uad81\uc815 \uc0ac\ub78c\ub4e4\uacfc \uac19\uc740 \uc7a5\uba74\uc5d0 \ub454\ub2e4. \ubcf4\ub294 \uc0ac\ub78c\uc740 \uadf8\ub9bc\uc758 \ub0b4\uc6a9\uacfc \uadf8\ub9bc\uc774 \ub9cc\ub4e4\uc5b4\uc9c0\ub294 \uc77c\uc744 \ud55c\uaebc\ubc88\uc5d0 \ubcf4\uac8c \ub41c\ub2e4. \uc774 \uc810\uc744 \ud654\uac00\uc758 \uc9c0\uc704\uc640 \uc5f0\uacb0\ud574 \uc77d\uc744 \uc218\ub3c4 \uc788\ub2e4. \uadf8\ub294 \uad81\uc815\uc5d0\uc11c \uc77c\ud588\uace0 \uc0ac\ud68c\uc801\uc778 \uc778\uc815\uc744 \uc911\uc694\ud558\uac8c \uc5ec\uacbc\ub2e4. \ub2e4\ub9cc \uae30\uc0ac \uc791\uc704\uc640 \uadf8\ub9bc\uc758 \uad00\uacc4\uc5d0 \uc5bd\ud78c \uba4b\uc9c4 \uc77c\ud654\ub97c \ud655\uc778 \uc5c6\uc774 \ubc18\ubcf5\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ucc38\uace0\ud55c \uc61b \ud574\uc124\uc11c\ub3c4 \uc774 \uc791\ud488\uc758 \ubcf4\uc0c1\uc73c\ub85c \uace7\ubc14\ub85c \uc791\uc704\ub97c \ubc1b\uc558\ub2e4\ub294 \uc2dd\uc758 \ub2e8\uc21c\ud55c \uc124\uba85\uc744 \uacbd\uacc4\ud55c\ub2e4. \uc774 \uae00\uc758 \uc774\ubbf8\uc9c0\ub294 \uc2e4\uc81c \uc791\ud488\uc758 \uc624\ub798\ub41c \ubcf5\uc81c \ub3c4\ud310\uc774\ub2e4. \uc778\ubb3c\uacfc \uad6c\ub3c4\ub294 \uc791\ud488\uc744 \ubcf4\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub418\uc9c0\ub9cc \uc778\uc1c4\uc758 \uc0c9\uacfc \uba85\uc554\uc774 \uc6d0\ud654\uc640 \uc644\uc804\ud788 \uac19\uc9c0\ub294 \uc54a\uc744 \uc218 \uc788\ub2e4. \uc5b4\ub450\uc6b4 \ubd80\ubd84\uc758 \uc138\ubd80\ub97c \ubaa8\ub450 \ud310\ub2e8\ud558\ub294 \uc790\ub8cc\ub85c \uc4f0\uae30\ubcf4\ub2e4\ub294 \ud654\uba74 \uc804\uccb4\uc758 \ubc30\uce58\ub97c \uba3c\uc800 \uc0b4\ud3b4\ubcf4\uba74 \uc88b\ub2e4. \uc61b \ud574\uc124\uc11c\uc5d0\ub294 \uadf8 \uc2dc\ub300\uc758 \ucde8\ud5a5\uacfc \uad81\uc815 \uc778\ubb3c\uc5d0 \ub300\ud55c \ud3c9\uac00\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \ud604\ub300\uc758 \ub3c5\uc790\uac00 \uc678\ubaa8\ub098 \uc2e0\ubd84\uc744 \ub0ae\ucd94\ub294 \ud45c\ud604\uae4c\uc9c0 \ub530\ub77c\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud654\uba74\uc5d0 \ud568\uaed8 \uc788\ub294 \uc0ac\ub78c\ub4e4\uc744 \uc6b0\uc5f4\uc744 \ub9e4\uae30\ub294 \uc18c\ud488\uc73c\ub85c \ubcf4\uc9c0 \uc54a\uace0, \uac01\uc790\uc758 \uc704\uce58\uc640 \ub3d9\uc791\uc744 \uac00\uc9c4 \uc874\uc7ac\ub85c \ubc14\ub77c\ubcfc \uc218 \uc788\ub2e4. \uac19\uc740 \uadf8\ub9bc\ub3c4 \uc77d\ub294 \ub208\uc5d0 \ub530\ub77c \uc9c8\ubb38\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \u300e\uc2dc\ub140\ub4e4\u300f\uc740 \uc655\uc2e4\uc758 \ud55c \uc7a5\uba74\ucc98\ub7fc \uc2dc\uc791\ud574 \uadf8\ub9bc\uc744 \ubcf4\ub294 \ud589\uc704 \uc790\uccb4\ub97c \uc758\uc2dd\ud558\uac8c \ub9cc\ub4e0\ub2e4. \ub204\uad6c\ub97c \uadf8\ub838\ub294\uc9c0\ubfd0 \uc544\ub2c8\ub77c \ub204\uac00 \ubcf4\uace0 \uc788\ub294\uc9c0, \ub204\uac00 \ubcf4\uc774\uc9c0 \uc54a\ub294\uc9c0, \ub0b4\uac00 \uc11c \uc788\ub294 \uc790\ub9ac\uac00 \ubb34\uc5c7\uc744 \ubc14\uafb8\ub294\uc9c0 \ubb3b\uac8c \ud55c\ub2e4. \uc624\ub798 \ubc14\ub77c\ubcfc\uc218\ub85d \ucc98\uc74c\uc758 \uc911\uc2ec\uc774 \uc870\uae08\uc529 \uc6c0\uc9c1\uc778\ub2e4. \ub2e4\uc2dc \ud654\uba74 \uac00\uc6b4\ub370\uc758 \uacf5\uc8fc\ub97c \ubcf8 \ub4a4 \uc67c\ucabd\uc758 \ud654\uac00\uc640 \ub4a4\uc758 \uac70\uc6b8\uc744 \ubc88\uac08\uc544 \ubcf4\uc790. \uac19\uc740 \uce94\ubc84\uc2a4\uc778\ub370 \uc2dc\uc120\uc774 \ub3cc\uc544\uc62c \ub54c\ub9c8\ub2e4 \ubc29\uc758 \uad00\uacc4\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \ubca8\ub77c\uc2a4\ucf00\uc2a4\uac00 \ub9cc\ub4e4\uc5b4 \ub193\uc740 \uac83\uc740 \uc778\ubb3c\ub4e4\uc744 \uc798 \ub2ee\uac8c \uadf8\ub9b0 \ud55c \uc7a5\uba74\ub9cc\uc774 \uc544\ub2c8\ub2e4. \ubc14\uae65\uc5d0 \uc11c \uc788\ub358 \uc6b0\ub9ac\uae4c\uc9c0 \uadf8 \ubc29\uc744 \uc644\uc131\ud558\ub294 \ub370 \ucc38\uc5ec\ud558\uac8c \ud558\ub294 \uadf8\ub9bc\uc774\ub2e4."}, {"id": "leonardo-life-of-observation", "title": "\ub808\uc624\ub098\ub974\ub3c4 \ub2e4\ube48\uce58\uc758 \uc0dd\uc560 \u2014 \uadf8\ub9bc \ud55c \uc7a5\uc5d0\uc11c \uc138\uc0c1\uc744 \uad00\ucc30\ud558\ub2e4", "summary": "\ud654\uac00\uc758 \uc774\ub3d9\uacfc \uc791\ud488, \uad00\ucc30 \uae30\ub85d\uc744 \ud1b5\ud574 \ub2e4\uc7ac\ub2e4\ub2a5\ud558\ub2e4\ub294 \ub9d0 \ub4a4\uc758 \uc2dc\uac04\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/leonardo-life-of-observation/index.html", "image": "../media/leonardo-life-of-observation.jpg", "alt": "\ub2e4\ube48\uce58\uc758 \ucd5c\ud6c4\uc758 \ub9cc\ucc2c\uc744 \uc7ac\ud604\ud55c \uc61b \ub3c4\ud310. \uae34 \uc2dd\ud0c1 \uc911\uc559\uc758 \uc608\uc218\uc640 \uc591\ucabd \uc81c\uc790\ub4e4\uc774 \ud45c\ud604\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.", "text": "\ub808\uc624\ub098\ub974\ub3c4 \ub2e4\ube48\uce58\uc758 \uc0dd\uc560 \u2014 \uadf8\ub9bc \ud55c \uc7a5\uc5d0\uc11c \uc138\uc0c1\uc744 \uad00\ucc30\ud558\ub2e4 \uacf5\ubc29\uc758 \ubc30\uc6c0\uacfc \uad81\uc815\uc758 \uc77c, \ub05d\ub098\uc9c0 \uc54a\uc740 \uc9c8\ubb38\ub4e4 \ud654\uac00\uc758 \uc774\ub3d9\uacfc \uc791\ud488, \uad00\ucc30 \uae30\ub85d\uc744 \ud1b5\ud574 \ub2e4\uc7ac\ub2e4\ub2a5\ud558\ub2e4\ub294 \ub9d0 \ub4a4\uc758 \uc2dc\uac04\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \ub2e4\ube48\uce58\ub77c\ub294 \uc774\ub984\uc5d0\ub294 \uc5ec\ub7ec \ubaa8\uc2b5\uc774 \uacb9\uccd0 \uc788\ub2e4. \u3008\ubaa8\ub098\ub9ac\uc790\u3009\ub97c \uadf8\ub9b0 \ud654\uac00\uc774\uba74\uc11c \uc778\uccb4\uc640 \ubb3c, \ub0a0\uc544\uac00\ub294 \uc6c0\uc9c1\uc784\uacfc \uae30\uacc4\uc5d0\ub3c4 \uad00\uc2ec\uc744 \uac00\uc84c\ub358 \uc0ac\ub78c\uc774\ub2e4. \uc774\ub7f0 \uc774\ub984 \uc55e\uc5d0\uc11c\ub294 \ud0c0\uace0\ub09c \ucc9c\uc7ac\uc600\ub2e4\ub294 \ub9d0\ub85c \uc27d\uac8c \uc815\ub9ac\uac00 \ub05d\ub098\uace4 \ud55c\ub2e4. \uadf8\ub7ec\ub098 1452\ub144\uc5d0 \ud0dc\uc5b4\ub098 1519\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub09c \ud55c \uc0ac\ub78c\uc758 \uc0b6\uc5d0\ub294 \ubc30\uc6b0\uace0 \uc758\ub8b0\ub97c \ubc1b\uace0 \uc774\ub3d9\ud558\uba70, \ub05d\ub0b4\uc9c0 \ubabb\ud55c \uc77c\uacfc \ub2e4\uc2dc \uc0b4\ud540 \ubb38\uc81c\uac00 \uc788\uc5c8\ub2e4. \ubb34\uc5c7\uc774\ub4e0 \uc989\uc2dc \ud574\ub0b8 \uc0ac\ub78c\uc73c\ub85c \uc0c1\uc0c1\ud558\uae30\ubcf4\ub2e4 \ubb34\uc5c7\uc744 \uc624\ub798 \ubcf4\uace0 \uc5b4\ub5bb\uac8c \uc77c\ud588\ub294\uc9c0 \ub530\ub77c\uac00 \ubcf4\uba74 \ub2e4\ube48\uce58\uac00 \uc870\uae08 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \uadf8\ub294 \ud53c\ub80c\uccb4\uc758 \ubca0\ub85c\ud0a4\uc624 \uacf5\ubc29\uc5d0\uc11c \ubc30\uc6e0\ub2e4. \uacf5\ubc29\uc740 \uc644\uc131\ub41c \uadf8\ub9bc\ub9cc \uad6c\uacbd\ud558\ub294 \uc7a5\uc18c\uac00 \uc544\ub2c8\ub77c \uc7ac\ub8cc\uc640 \ub3c4\uad6c\ub97c \ub2e4\ub8e8\uace0 \uc5ec\ub7ec \uc0ac\ub78c\uc774 \uc791\uc5c5\uc744 \ub098\ub204\ub294 \ud604\uc7a5\uc774\uc5c8\ub2e4. \uadf8\ub9bc\uacfc \uc785\uccb4\uc801\uc778 \ud615\ud0dc, \uc190\uc758 \uae30\uc220\uacfc \uad00\ucc30\uc774 \uac00\uae4c\uc774 \ub193\uc77c \uc218 \uc788\ub294 \ud658\uacbd\uc774\ub2e4. \uc5b4\ub9b0 \uc2dc\uc808\uc758 \uc7ac\ub2a5\uc744 \uacfc\uc7a5\ud558\ub294 \uc77c\ud654\ubcf4\ub2e4 \uc774\ub7f0 \ubc30\uc6c0\uc758 \uc870\uac74\uc744 \uc0dd\uac01\ud574 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \ubb34\uc5c7\uc744 \uc798 \ubcf4\ub824\uba74 \ubb34\uc5c7\uc744 \ub9cc\ub4e4\uc5b4 \ubcf4\uace0 \uc5b4\ub5a4 \uc7ac\ub8cc\ub97c \uc54c\uc544\uc57c \ud558\ub294\uc9c0 \uc775\ud788\ub294 \uc2dc\uac04\uc774 \ud544\uc694\ud588\ub2e4. \ub6f0\uc5b4\ub09c \uc791\ud488 \ub4a4\uc5d0\ub3c4 \ubc18\ubcf5\ub418\ub294 \uc190\uc758 \uc77c\uc774 \uc788\uc5c8\uc74c\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \ubc00\ub77c\ub178\uc5d0\uc11c \uc2a4\ud3ec\ub974\ucc28 \uac00\ubb38\uc758 \ud6c4\uc6d0\uc744 \ubc1b\ub294 \ub3d9\uc548 \ub2e4\ube48\uce58\uc758 \ud65c\ub3d9\uc740 \ud68c\ud654\ub9cc\uc73c\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\ub294\ub2e4. \uad81\uc815\uc758 \uc694\uad6c\uc640 \uc7a5\uc2dd, \uae30\ub150\ubb3c\uacfc \uae30\uc220\uc801 \uad00\uc2ec\uc774 \uac19\uc740 \uc0b6 \uc548\uc5d0 \uc788\uc5c8\ub2e4. \uc608\uc220\uac00\uac00 \uc790\uae30 \uad00\uc2ec\ub9cc\uc744 \uc704\ud574 \uc870\uc6a9\ud788 \uc791\uc5c5\ud558\ub294 \uc624\ub298\uc758 \ub0ad\ub9cc\uc801 \uc774\ubbf8\uc9c0\uc640\ub294 \ub2e4\ub978 \uc870\uac74\uc774\ub2e4. \ub204\uac00 \uc77c\uc744 \ub9e1\uae30\uace0 \uc5b4\ub5a4 \uc790\uc6d0\uc744 \uc8fc\ub294\uc9c0\ub294 \ubb34\uc5c7\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub294\uc9c0\uc640 \uc5f0\uacb0\ub41c\ub2e4. \ub2e4\ube48\uce58\uc758 \uc774\ub3d9\uc744 \ub3c4\uc2dc \uc774\ub984 \uba87 \uac1c\ub85c \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc791\uc5c5\uc758 \ud658\uacbd\uc774 \ubc14\ub00c\ub294 \uacfc\uc815\uc73c\ub85c \ubcf4\uba74 \uc88b\ub2e4. \uc0c8\ub85c\uc6b4 \uc7a5\uc18c\ub294 \ube5b\uacfc \ud48d\uacbd\ubfd0 \uc544\ub2c8\ub77c \uc77c\uc758 \uc885\ub958\uc640 \uc0ac\ub78c \uad00\uacc4\ub3c4 \ubc14\uafb8\uc5c8\ub2e4. \ubc00\ub77c\ub178\uc758 \u3008\ucd5c\ud6c4\uc758 \ub9cc\ucc2c\u3009\uc740 \uae34 \uc2dd\ud0c1\uc744 \ub458\ub7ec\uc2fc \uc778\ubb3c\ub4e4\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uac00\uc6b4\ub370 \uc608\uc218\ub97c \uc911\uc2ec\uc73c\ub85c \uc81c\uc790\ub4e4\uc758 \uc190\uacfc \uc5bc\uad74, \ubab8\uc758 \uc6c0\uc9c1\uc784\uc774 \uc11c\ub85c \ub2e4\ub974\uac8c \ud3bc\uccd0\uc9c4\ub2e4. \uac19\uc740 \uc0ac\uac74 \uc55e\uc5d0\uc11c \ubaa8\ub450\uac00 \ub611\uac19\uc774 \ubc18\uc751\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc744 \ud55c \ud654\uba74\uc5d0 \uc5ee\ub294\ub2e4. \uc0ac\ub78c\uc758 \ud45c\uc815\uc744 \uba87 \uc885\ub958\ub85c \ubd84\ub958\ud574 \ubd99\uc778 \uadf8\ub9bc\ucc98\ub7fc \ubcf4\uae30\ubcf4\ub2e4, \uc778\ubb3c\ub07c\ub9ac \uc2dc\uc120\uacfc \uc190\uc9d3\uc774 \uc5b4\ub5bb\uac8c \uc774\uc5b4\uc9c0\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uacf5\uac04\uc744 \uad6c\uc131\ud558\ub294 \uc77c\uacfc \uc0ac\ub78c\uc758 \ubc18\uc751\uc744 \uad00\ucc30\ud558\ub294 \uc77c\uc774 \ub9cc\ub098\ub294 \uc7a5\uba74\uc774\ub2e4. \uc644\uc131\ub41c \uc720\uba85 \uc791\ud488\uc758 \uc774\ub984 \ub4a4\uc5d0 \ubb34\uc5c7\uc744 \ubcfc\uc9c0 \uad6c\uccb4\uc801\uc778 \uae38\uc774 \uc0dd\uae34\ub2e4. \ub2e4\ube48\uce58\uc758 \uc791\uc5c5\uc5d0\ub294 \ubbf8\uc644\uc131\uc73c\ub85c \ub0a8\uc740 \uac83\ub4e4\ub3c4 \uc788\ub2e4. \uc644\ubcbd\ud55c \ucc9c\uc7ac\ub77c\uba74 \uc65c \ub05d\ub0b4\uc9c0 \ubabb\ud588\ub290\ub0d0\uace0 \uc27d\uac8c \ubb3b\uae30\ubcf4\ub2e4, \uad00\uc2ec\uc758 \ud3ed\uacfc \uc758\ub8b0\uc758 \uc870\uac74, \uc774\ub3d9\uacfc \uc644\uc131 \uc0ac\uc774\uc5d0 \uae34\uc7a5\uc774 \uc788\uc5c8\ub2e4\ub294 \uc810\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ubb34\uc5c7\uc5d0\ub4e0 \uad00\uc2ec\uc774 \ub9ce\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ubaa8\ub4e0 \uc77c\uc744 \ub9c8\uce5c\ub2e4\ub294 \ubcf4\uc7a5\uc740 \uc544\ub2c8\ub2e4. \uc774 \ubaa8\uc2b5\uc744 \uadfc\uac70\ub85c \uc624\ub298\uc758 \ubcd1\uba85\uc774\ub098 \uc131\uaca9 \uc720\ud615\uc744 \ubd99\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \ud655\uc778\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc791\uc5c5\uc758 \uacb0\uacfc\uc640 \uae30\ub85d\uc758 \ud754\uc801\uc774\ub2e4. \ub9ce\uc740 \uc9c8\ubb38\uc744 \uac00\uc84c\ub2e4\ub294 \ucc2c\uc0ac\uc640 \uc2e4\uc81c\ub85c \uc644\uc131\ud574\uc57c \ud558\ub294 \uc77c\uc758 \ubd80\ub2f4\uc744 \ud568\uaed8 \ubcf4\ub294 \ud3b8\uc774 \ud55c \uc0ac\ub78c\uc758 \uc0dd\uc560\ub97c \ub354 \uc785\uccb4\uc801\uc73c\ub85c \ub9cc\ub4e0\ub2e4. \uadf8\ub294 \uc778\uccb4\uc640 \ud574\ubd80\ud559, \uad11\ud559\uacfc \uc790\uc5f0\uc758 \uc6c0\uc9c1\uc784 \ub4f1\uc744 \uc0b4\ud3c8\ub2e4. \ud654\uac00\uac00 \uc5bc\uad74\uacfc \ubab8\uc744 \ud45c\ud604\ud558\ub824\uba74 \uac89\uc73c\ub85c \ub4dc\ub7ec\ub09c \uc724\uacfd\ubfd0 \uc544\ub2c8\ub77c \uc548\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc774\ub294\uc9c0\ub3c4 \uad81\uae08\ud574\uc9c8 \uc218 \uc788\ub2e4. \ubb3c\uccb4\uac00 \ubcf4\uc774\ub294 \ubc29\uc2dd\uacfc \ube5b\uc744 \uc5f0\uad6c\ud558\ub294 \uad00\uc2ec\ub3c4 \ud68c\ud654\uc640 \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\uc558\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub0a8\uc544 \uc788\ub294 \ubaa8\ub4e0 \uae30\uacc4 \uadf8\ub9bc\uc744 \uc2e4\uc81c\ub85c \uc81c\uc791\ub418\uc5b4 \uc791\ub3d9\ud55c \ubc1c\uba85\ud488\uc774\ub77c\uace0 \ubd80\ub97c \uc218\ub294 \uc5c6\ub2e4. \uad00\ucc30 \uae30\ub85d, \uad6c\uc0c1, \uc644\uc131\ub41c \ubb3c\uac74\uc740 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc2dc\ub300\ub97c \uc55e\uc11c\uac14\ub2e4\ub294 \uac10\ud0c4 \uacc1\uc5d0 \ubb34\uc5c7\uc774 \uc2e4\uc81c\ub85c \ud655\uc778\ub418\ub294\uc9c0\ub97c \uc0b4\ud53c\uba74 \uc5f0\uad6c\uc758 \uc131\uaca9\uc774 \uc624\ud788\ub824 \ub354 \ubd84\uba85\ud574\uc9c4\ub2e4. \uadf8\uc758 \uae30\ub85d\uc5d0\ub294 \uc624\ub978\ucabd\uc5d0\uc11c \uc67c\ucabd\uc73c\ub85c \uc4f4 \uae00\uc774 \uc788\ub2e4. \ub0af\uc120 \uae00\uc528 \ubc29\ud5a5\uc740 \uae30\uc5b5\ud558\uae30 \uc88b\uc740 \ud2b9\uc9d5\uc774\uc9c0\ub9cc, \ube44\ubc00 \uc554\ud638\ub97c \ub9cc\ub4e4\ub824\uace0 \ubaa8\ub4e0 \uae00\uc744 \uadf8\ub807\uac8c \uc37c\ub2e4\uace0 \ub2e8\uc815\ud558\uc9c0\ub294 \ub9d0\uc790. \uae30\ub85d\uc758 \ub0b4\uc6a9\uacfc \uc4f0\ub294 \ubc29\uc2dd\uc740 \uac01\uac01 \uadfc\uac70\ub97c \uc0b4\ud3b4\uc57c \ud558\ub294 \ubb38\uc81c\ub2e4. \uae00\uc528\uc758 \ud2b9\uc774\ud568\uc5d0\uc11c \ud55c \uac78\uc74c \ub354 \uac00\uba74 \ubb34\uc5c7\uc744 \uacc4\uc18d \uae30\ub85d\ud588\ub294\uc9c0\uc5d0 \uad00\uc2ec\uc774 \uc0dd\uae34\ub2e4. \ubcf8 \uac83\uc744 \uadf8\ub9ac\uace0, \uad81\uae08\ud55c \uad6c\uc870\ub97c \uc0b4\ud53c\uba70, \ubb38\uc81c\ub97c \ub2e4\uc2dc \ub0a8\uae30\ub294 \ud589\uc704\ub2e4. \ucc9c\uc7ac\uc758 \uc0dd\uac01\uc740 \uba38\ub9bf\uc18d\uc5d0\uc11c \ud55c \ubc88\uc5d0 \uc644\uc131\ub418\uae30\ubcf4\ub2e4 \uc885\uc774 \uc704\uc5d0\uc11c \ud754\uc801\uacfc \uc9c8\ubb38\uc73c\ub85c \ub0a8\uae30\ub3c4 \ud588\ub2e4. \ub9d0\ub144\uc758 \ub2e4\ube48\uce58\ub294 \ud504\ub791\uc218\uc544 1\uc138\uc758 \ud6c4\uc6d0\uc744 \ubc1b\uc73c\uba70 \ud504\ub791\uc2a4\uc5d0\uc11c \uc9c0\ub0c8\ub2e4. \uadf8\uc758 \uc791\ud488\uacfc \uae30\ub85d\uc740 \ud55c \ub098\ub77c\uc758 \uc791\uc5c5\uc2e4\uc5d0\ub9cc \uba38\ubb34\ub974\uc9c0 \uc54a\uc558\ub2e4. \uc774\ub3d9\uacfc \ud6c4\uc6d0, \ud6c4\ub300\uc758 \uc218\uc9d1\uc744 \uac70\uce58\uba70 \uc624\ub298\uc758 \ub3c5\uc790\uac00 \uc5ec\ub7ec \uc7a5\uc18c\uc640 \uc790\ub8cc\uc5d0\uc11c \ub9cc\ub098\uac8c \ub418\uc5c8\ub2e4. \uc655\uc758 \ud488\uc5d0\uc11c \uc8fd\uc5c8\ub2e4\ub294 \uc2dd\uc758 \uc720\uba85\ud55c \uc7a5\uba74\uc744 \ud655\uc778\ub41c \ub9c8\uc9c0\ub9c9 \uc21c\uac04\ucc98\ub7fc \uc7ac\ud604\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud55c \uc0ac\ub78c\uc758 \uc0dd\uc560\ub97c \uc544\ub984\ub2e4\uc6b4 \uc77c\ud654 \ud558\ub098\ub85c \ub2eb\uc9c0 \uc54a\uc544\ub3c4 \uadf8\ub9bc\uacfc \uae30\ub85d\uc740 \ucda9\ubd84\ud788 \ud48d\ubd80\ud558\ub2e4. \uc624\ud788\ub824 \ub0a8\uc740 \uc790\ub8cc\uac00 \uc11c\ub85c \ub2e4\ub978 \uc2dc\uae30\uc758 \uc77c\uc744 \uc5b4\ub5bb\uac8c \ubcf4\uc5ec \uc8fc\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\ub294 \uae38\uc774 \uc5f4\ub9b0\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uc61b \uc804\uae30\uc5d0 \uc218\ub85d\ub41c \u3008\ucd5c\ud6c4\uc758 \ub9cc\ucc2c\u3009\uc758 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \uc624\ub298\uc758 \ubcbd\ud654 \uc0c1\ud0dc\uc640 \uc0c9\uc744 \uadf8\ub300\ub85c \ubcf4\uc5ec \uc8fc\ub294 \ucd5c\uc2e0 \uc0ac\uc9c4\uc740 \uc544\ub2c8\uc9c0\ub9cc \uc778\ubb3c\uacfc \uacf5\uac04\uc758 \ud070 \uad6c\uc131\uc744 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ub2e4\ube48\uce58\uc758 \uc0c1\uc0c1 \uc18d \uc790\ud654\uc0c1\uc744 \uc0c8\ub85c \ub9cc\ub4e0 \uc790\ub8cc\uc640\ub3c4 \uad6c\ubd84\ub41c\ub2e4. \uadf8\ub97c \uc77d\uace0 \ub098\uba74 \ud55c \uadf8\ub9bc \uc548\uc5d0\uc11c \ubb34\uc5c7\uc744 \ubcf4\ub824 \ud588\ub294\uc9c0 \ub2e4\uc2dc \ubb3c\uc5b4\ubcfc \uc218 \uc788\ub2e4. \uc0ac\ub78c\uc758 \ud45c\uc815\uacfc \uc190, \ubab8\uc758 \uad6c\uc870\uc640 \ube5b\uc774 \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ub418\ub294\uac00. \ub2e4\uc7ac\ub2e4\ub2a5\ud558\ub2e4\ub294 \ud070 \uce6d\ucc2c\uc744 \uba87 \uac00\uc9c0 \uad6c\uccb4\uc801\uc778 \uad00\uc2ec\uc73c\ub85c \ub098\ub204\uba74, \ub2e4\ube48\uce58\ub294 \ubaa8\ub4e0 \uac83\uc744 \uc544\ub294 \uc774\ub984\uc5d0\uc11c \uc624\ub798 \uad00\ucc30\ud558\uace0 \uc9c8\ubb38\ud558\ub358 \uc0ac\ub78c\uc73c\ub85c \ubcf4\uc774\uae30 \uc2dc\uc791\ud55c\ub2e4."}, {"id": "les-miserables-reading-guide", "title": "\ub808 \ubbf8\uc81c\ub77c\ube14 \u2014 \ube75 \ud55c \uc870\uac01\uc5d0\uc11c \uc2dc\uc791\ub41c \uae34 \uc9c8\ubb38", "summary": "\uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0, \uc778\ubb3c\ub4e4\uc758 \uc120\ud0dd\uacfc 1832\ub144 \ud30c\ub9ac \ubd09\uae30\uc758 \ubc30\uacbd\uc744 \ucc28\ub840\ub85c \ud480\uc5b4 \ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/les-miserables-reading-guide/index.html", "image": "../media/les-miserables-reading-guide-scene-20261030.png", "alt": "\uc18c\ubc15\ud55c \ubc29\uc5d0\uc11c \ubbf8\ub9ac\uc5d8 \uc8fc\uad50\uac00 \uc9c0\uce5c \uc7a5\ubc1c\uc7a5\uc5d0\uac8c \uc740\ucd1b\ub300 \ub450 \uac1c\ub97c \uac74\ub124\ub294 \uc6d0\uc791 \uae30\ubc18 \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ub808 \ubbf8\uc81c\ub77c\ube14 \u2014 \ube75 \ud55c \uc870\uac01\uc5d0\uc11c \uc2dc\uc791\ub41c \uae34 \uc9c8\ubb38 \uc7a5\ubc1c\uc7a5\u00b7\ud321\ud2f4\u00b7\ucf54\uc81c\ud2b8\u00b7\uc790\ubca0\ub974\uc758 \uc0b6\uc73c\ub85c \uc77d\ub294 \uc904\uac70\ub9ac\uc640 \uc791\ud488\uc758 \uc9c8\ubb38 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0, \uc778\ubb3c\ub4e4\uc758 \uc120\ud0dd\uacfc 1832\ub144 \ud30c\ub9ac \ubd09\uae30\uc758 \ubc30\uacbd\uc744 \ucc28\ub840\ub85c \ud480\uc5b4 \ubd05\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \uc7a5\ubc1c\uc7a5\uc774 \ud6d4\uce5c \uac83\uc740 \ube75 \ud55c \uc870\uac01\uc774\uc5c8\ub2e4. \uad76\uc8fc\ub9ac\ub294 \ub204\uc774\uc758 \uc544\uc774\ub4e4\uc744 \uba39\uc774\ub824\uace0 \ud55c \uc77c\uc774\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \uc808\ub3c4\uc640 \uc774\uc5b4\uc9c4 \ud0c8\uc625 \uc2dc\ub3c4\ub85c \uac10\uc625\uc5d0\uc11c \ubcf4\ub0b8 \uc2dc\uac04\uc740 \ubaa8\ub450 19\ub144\uc774 \ub41c\ub2e4. \ubb38\uc774 \uc5f4\ub824 \ubc16\uc73c\ub85c \ub098\uc628 \ub4a4\uc5d0\ub3c4 \uc0ac\ub78c\ub4e4\uc740 \uadf8\ub97c \uc804\uacfc\uc790\ub85c \uba3c\uc800 \ubcf8\ub2e4. \ucc98\ubc8c\uc740 \ub05d\ub0ac\ub294\ub370 \uc0b6\uc744 \ub2e4\uc2dc \uc2dc\uc791\ud560 \uc790\ub9ac\ub294 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ube45\ud1a0\ub974 \uc704\uace0\uac00 1862\ub144\uc5d0 \ubc1c\ud45c\ud55c \u300e\ub808 \ubbf8\uc81c\ub77c\ube14\u300f\uc740 \uc774 \ucd9c\ubc1c\uc810\uc5d0\uc11c \ud55c \uc0ac\ub78c\uc758 \ubcc0\ud654\uc640 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \ubd88\ud589\uc744 \uae38\uac8c \uc5ee\ub294\ub2e4. \uc81c\ubaa9\uc740 \ub300\ub7b5 \u2018\ube44\ucc38\ud55c \uc0ac\ub78c\ub4e4\u2019\uc774\ub77c\ub294 \ub73b\uc774\ub2e4. \ud55c \uc601\uc6c5\uc758 \uc131\uacf5\ub2f4\uc744 \uae30\ub300\ud558\uae30\ubcf4\ub2e4, \uac00\ub09c\uacfc \uc81c\ub3c4 \uc18d\uc5d0\uc11c \uc11c\ub85c \uae30\ub300\uac70\ub098 \uc0c1\ucc98 \uc8fc\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc774\uc57c\uae30\ub85c \ub4e4\uc5b4\uac00\uba74 \ubc29\ub300\ud55c \uc18c\uc124\uc758 \uae38\uc774 \uc870\uae08 \ubcf4\uc778\ub2e4. \uc774 \uae00\uc5d0\ub294 \uc8fc\uc694 \uc0ac\uac74\uacfc \uacb0\ub9d0\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4. \uc791\ud488\uc744 \uc77d\uae30 \uc804 \uae38\uc7a1\uc774\ub85c \ubcf4\uc544\ub3c4 \uc88b\uace0, \ucc45\uc744 \ub36e\uc740 \ub4a4 \uc778\ubb3c\ub4e4\uc758 \uad00\uacc4\ub97c \uc815\ub9ac\ud558\ub294 \ub370 \uc368\ub3c4 \uc88b\ub2e4. \uc7a5\ubc1c\uc7a5\uc744 \uc9d1\uc5d0 \ub4e4\uc778 \ubbf8\ub9ac\uc5d8 \uc8fc\uad50\ub294 \uc74c\uc2dd\uacfc \uc7a0\uc790\ub9ac\ub97c \ub0b4\uc5b4 \uc900\ub2e4. \uc7a5\ubc1c\uc7a5\uc740 \uadf8 \uc9d1\uc5d0\uc11c \uc740\uc2dd\uae30\ub97c \ud6d4\uccd0 \ub2ec\uc544\ub0ac\ub2e4\uac00 \ud5cc\ubcd1\ub4e4\uc5d0\uac8c \ubd99\uc7a1\ud600 \ub3cc\uc544\uc628\ub2e4. \uadf8\ub54c \uc8fc\uad50\ub294 \uc790\uc2e0\uc774 \uc900 \ubb3c\uac74\uc774\ub77c\uace0 \ub9d0\ud558\uace0, \uc740\ucd1b\ub300\uae4c\uc9c0 \uac00\uc838\uac00\ub77c\uba70 \uac74\ub128\ub2e4. \uc7a5\ubc1c\uc7a5\uc774 \ub2e4\uc2dc \uc8c4\uc218\ub85c \ub3cc\uc544\uac08 \uc218\ub3c4 \uc788\ub358 \uc21c\uac04\uc5d0 \ub2e4\ub978 \uae38\uc774 \uc5f4\ub9b0 \uac83\uc774\ub2e4. \ud558\uc9c0\ub9cc \uc18c\uc124\uc740 \uadf8\ub97c \uc989\uc2dc \ucc29\ud55c \uc0ac\ub78c\uc73c\ub85c \ubc14\uafb8\uc9c0 \uc54a\ub294\ub2e4. \uc774\uc5b4 \ub9cc\ub09c \uc18c\ub144 \ud504\ud2f0 \uc81c\ub974\ubca0\uc758 \ub3d9\uc804\uc744 \ub3cc\ub824\uc8fc\uc9c0 \uc54a\ub294 \uc77c\uae4c\uc9c0 \ubc8c\uc5b4\uc9c4\ub2e4. \ub4a4\ub2a6\uac8c \uc790\uc2e0\uc758 \ud589\ub3d9\uc744 \uae68\ub2eb\uace0 \uad34\ub85c\uc6cc\ud558\ub294 \uc7a5\uba74\uc774 \uc911\uc694\ud558\ub2e4. \uc6a9\uc11c\ub97c \ud55c \ubc88 \ubc1b\uc558\ub2e4\uace0 \uc624\ub798 \uad73\uc5b4\uc9c4 \uc2b5\uad00\uc774 \uace7 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc8fc\uad50\uc758 \uce5c\uc808\uc740 \ubcc0\uc2e0\uc758 \ub9c8\ubc95\uc774\ub77c\uae30\ubcf4\ub2e4, \uc2a4\uc2a4\ub85c\ub97c \ub2e4\uc2dc \ubcf4\uac8c \ub9cc\ub4dc\ub294 \uc2dc\uc791\uc5d0 \uac00\uae5d\ub2e4. \uc138\uc6d4\uc774 \ud758\ub7ec \uc7a5\ubc1c\uc7a5\uc740 \ub9c8\ub4e4\ub80c\uc774\ub77c\ub294 \uc774\ub984\uc73c\ub85c \uc0b4\uc544\uac04\ub2e4. \uc0ac\uc5c5\uc744 \uc77c\uc73c\ucf1c \uc77c\uc790\ub9ac\ub97c \ub9cc\ub4e4\uace0 \uc0ac\ub78c\ub4e4\uc744 \ub3c4\uc6b0\uba70 \uc2dc\uc7a5\uc758 \uc790\ub9ac\uc5d0\uae4c\uc9c0 \uc624\ub978\ub2e4. \ub204\uad70\uac00\uc5d0\uac8c \uadf8\ub294 \uc874\uacbd\ud560 \ub9cc\ud55c \uc0ac\ub78c\uc774\ub2e4. \uadf8\ub7ec\ub098 \uacbd\ucc30\uad00 \uc790\ubca0\ub974\ub294 \uadf8\uc5d0\uac8c\uc11c \uacfc\uac70\uc758 \uc8c4\uc218\ub97c \ub5a0\uc62c\ub9b0\ub2e4. \uc774\ub984\uc744 \ubc14\uafb8\uc5b4\ub3c4 \uacfc\uac70\uc640 \ud604\uc7ac\uc758 \ucda9\ub3cc\uc740 \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc774\ub54c \uc0f9\ub9c8\ud2f0\uc678\ub77c\ub294 \uc0ac\ub78c\uc774 \uc7a5\ubc1c\uc7a5\uc73c\ub85c \uc624\uc778\ub418\uc5b4 \uc7ac\ud310\ubc1b\uac8c \ub41c\ub2e4. \uc7a5\ubc1c\uc7a5\uc774 \uc785\uc744 \ub2e4\ubb3c\uba74 \uc790\uc2e0\uc758 \uc0c8 \uc0b6\uacfc \ub3c4\uc2dc\uc758 \uc77c\uc790\ub9ac\ub97c \uc9c0\ud0ac \uc218 \uc788\uc9c0\ub9cc, \uc544\ubb34 \uc0c1\uad00 \uc5c6\ub294 \uc0ac\ub78c\uc774 \ub300\uc2e0 \ubc8c\uc744 \ubc1b\ub294\ub2e4. \uadf8\ub294 \uacb0\uad6d \ubc95\uc815\uc5d0 \ub098\uac00 \uc790\uc2e0\uc758 \uc815\uccb4\ub97c \ubc1d\ud78c\ub2e4. \uc18c\uc124\uc758 \uae34 \ub3c5\ubc31\uc774 \ud798\uc744 \uc5bb\ub294 \ub300\ubaa9\uc774\ub2e4. \ub3c5\uc790\ub294 \u2018\uc88b\uc740 \uc0ac\ub78c\uc774 \ub418\uc5c8\uc73c\ub2c8 \ube44\ubc00\uc744 \uc9c0\ucf1c\ub3c4 \ub41c\ub2e4\u2019\ub294 \uc26c\uc6b4 \ub2f5 \uc55e\uc5d0\uc11c \uba48\ucd94\uac8c \ub41c\ub2e4. \ud321\ud2f4\uc740 \uc5b4\ub9b0 \ub538 \ucf54\uc81c\ud2b8\ub97c \ud14c\ub098\ub974\ub514\uc5d0 \ubd80\ubd80\uc5d0\uac8c \ub9e1\uae30\uace0 \uc77c\ud558\ub294 \uc5ec\uc131\uc774\ub2e4. \ub538\uc744 \ub3cc\ubcf4\ub294 \ube44\uc6a9\uc744 \ubcf4\ub0b4\uc57c \ud558\uc9c0\ub9cc \uc77c\uc790\ub9ac\ub97c \uc783\uace0, \uc810\uc810 \ub354 \uad81\uc9c0\uc5d0 \ubab0\ub9b0\ub2e4. \ud14c\ub098\ub974\ub514\uc5d0 \ubd80\ubd80\ub294 \ucf54\uc81c\ud2b8\ub97c \uc798 \ub3cc\ubcf4\uc9c0 \uc54a\uc73c\uba74\uc11c\ub3c4 \ub3c8\uc744 \uc694\uad6c\ud55c\ub2e4. \ud321\ud2f4\uc740 \ubab8\uacfc \uc0dd\ud65c\uc744 \uc18c\ubaa8\ud558\uba70 \ub538\uc744 \uc9c0\ud0a4\ub824 \uc560\uc4f4\ub2e4. \uc704\uace0\ub294 \uc774 \uc778\ubb3c\uc744 \ud1b5\ud574 \uac00\ub09c\uc744 \ub2e8\uc9c0 \uc131\uc2e4\ud558\uc9c0 \ubabb\ud55c \uac1c\uc778\uc758 \ubb38\uc81c\ub85c \uc124\uba85\ud560 \uc218 \uc788\ub294\uc9c0 \ubb3b\ub294\ub2e4. \uc77c\uc790\ub9ac\uc640 \ud3c9\ud310, \ub3cc\ubd04\uc758 \ube44\uc6a9\uc774 \ub3d9\uc2dc\uc5d0 \ubb34\ub108\uc9c0\uba74 \ubb34\uc5c7\uc774 \ub0a8\ub294\uac00. \uc7a5\ubc1c\uc7a5\uc740 \ud321\ud2f4\uc744 \ub3d5\uace0 \ucf54\uc81c\ud2b8\ub97c \ub370\ub824\uc624\uaca0\ub2e4\uace0 \uc57d\uc18d\ud558\uc9c0\ub9cc, \ud321\ud2f4\uc740 \ub538\uacfc \ub2e4\uc2dc \ub9cc\ub098\uc9c0 \ubabb\ud55c \ucc44 \uc8fd\ub294\ub2e4. \uc57d\uc18d\uc740 \uc774\uc81c \ub0a8\uc740 \uc0ac\ub78c\uc758 \ucc45\uc784\uc774 \ub41c\ub2e4. \ucf54\uc81c\ud2b8\ub294 \ud14c\ub098\ub974\ub514\uc5d0 \ubd80\ubd80\uc758 \uc9d1\uc5d0\uc11c \ud5c8\ub4dc\ub81b\uc77c\uc744 \ud558\uba70 \uc9c0\ub0b8\ub2e4. \uc5b4\ub9b0\uc544\uc774\uac00 \uc5b4\ub450\uc6b4 \uae38\uc5d0\uc11c \ubb3c\uc744 \uae38\uc5b4 \ub098\ub974\ub294 \uc7a5\uba74\uc740 \uc18c\uc124\uc758 \ube44\ucc38\ud568\uc744 \ucd94\uc0c1\uc801\uc778 \ub9d0\ubcf4\ub2e4 \ubd84\uba85\ud558\uac8c \ubcf4\uc5ec \uc900\ub2e4. \uc7a5\ubc1c\uc7a5\uc740 \uadf8 \uc544\uc774\ub97c \ub9cc\ub098 \ubb3c\ud1b5\uc744 \ub4e4\uc5b4 \uc8fc\uace0, \uacb0\uad6d \uadf8 \uc9d1\uc5d0\uc11c \ub370\ub9ac\uace0 \ub098\uc628\ub2e4. \ub204\uad70\uac00\uc758 \uc9d0\uc744 \ub300\uc2e0 \ub4dc\ub294 \ud589\ub3d9\uc774 \ub450 \uc0ac\ub78c\uc758 \uad00\uacc4\ub97c \uc2dc\uc791\ud55c\ub2e4. \ucf54\uc81c\ud2b8\ub97c \ubcf4\ud638\ud558\ub294 \ub3d9\uc548 \uc7a5\ubc1c\uc7a5\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \ub3c4\uc6c0\uc744 \ubc1b\uc558\ub358 \uc0ac\ub78c\uc774 \uc774\uc81c \ub204\uad70\uac00\ub97c \ub3cc\ubcf4\ub294 \uc0ac\ub78c\uc774 \ub41c\ub2e4. \uc790\ubca0\ub974\uc758 \ucd94\uc801\uc744 \ud53c\ud574 \ud30c\ub9ac\uc758 \uc218\ub140\uc6d0\uc5d0 \uba38\ubb34\ub294 \uacfc\uc815\uc5d0\ub294 \uc7a5\ubc1c\uc7a5\uc774 \uc804\uc5d0 \uad6c\ud574 \uc900 \ud3ec\uc290\ub974\ubc29\uc758 \ub3c4\uc6c0\ub3c4 \uc791\uc6a9\ud55c\ub2e4. \uc18c\uc124\uc5d0\uc11c \uc120\ud589\uc740 \ub298 \uc989\uac01\uc801\uc778 \ubcf4\uc0c1\uc73c\ub85c \ub3cc\uc544\uc624\uc9c0\ub294 \uc54a\uc9c0\ub9cc, \uc0ac\ub78c \uc0ac\uc774\uc5d0 \uc608\uc0c1\ud558\uc9c0 \ubabb\ud588\ub358 \uae38\uc744 \ub0a8\uae34\ub2e4. \uc131\uc7a5\ud55c \ucf54\uc81c\ud2b8\ub294 \uccad\ub144 \ub9c8\ub9ac\uc6b0\uc2a4\ub97c \ub9cc\ub098 \uc0ac\ub791\uc5d0 \ube60\uc9c4\ub2e4. \ub9c8\ub9ac\uc6b0\uc2a4\ub294 \uac00\uc871\uacfc \uc815\uce58\uc801 \uc0dd\uac01\uc744 \ub193\uace0 \uac08\ub4f1\ud558\uace0, \uacf5\ud654\uc8fc\uc758\ub97c \uc9c0\uc9c0\ud558\ub294 \uc80a\uc740\uc774\ub4e4\uacfc\ub3c4 \uac00\uae4c\uc774 \uc9c0\ub0b8\ub2e4. \ub450 \uc0ac\ub78c\uc758 \uc0ac\ub791\uc740 \uc18c\uc124\uc5d0 \ubc1d\uc740 \uc6c0\uc9c1\uc784\uc744 \ub9cc\ub4e4\uc9c0\ub9cc \uc7a5\ubc1c\uc7a5\uc5d0\uac8c\ub294 \ubd88\uc548\uc774 \ub41c\ub2e4. \uc790\uc2e0\uc5d0\uac8c \uc0b6\uc758 \uc911\uc2ec\uc774 \ub41c \uc544\uc774\uac00 \ub2e4\ub978 \uc0ac\ub78c\uc744 \ud5a5\ud558\uae30 \uc2dc\uc791\ud55c \uac83\uc774\ub2e4. \ub9c8\ub9ac\uc6b0\uc2a4\ub97c \uc0ac\ub791\ud558\ub294 \uc5d0\ud3ec\ub2cc\uc740 \ud14c\ub098\ub974\ub514\uc5d0 \ubd80\ubd80\uc758 \ub538\uc774\ub2e4. \uac19\uc740 \uc9d1\uc5d0\uc11c \uc790\ub780 \uc544\uc774\ub4e4\uc774 \uc11c\ub85c \ub2e4\ub978 \uae38\uc5d0 \ub193\uc774\uace0, \uc0ac\ub791\ud558\ub294 \ub9c8\uc74c\ub3c4 \ubaa8\ub450 \uac19\uc740 \uacb0\ub9d0\ub85c \uc774\uc5b4\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc704\uace0\ub294 \uc8fc\uc778\uacf5 \ub450 \uc0ac\ub78c\uc758 \uc5f0\uc560\ub9cc \ub530\ub85c \ub5bc\uc5b4 \ub193\uc9c0 \uc54a\uace0 \uc8fc\ubcc0\uc758 \uac00\ub09c\uacfc \uc9c8\ud22c, \ud5cc\uc2e0\uc744 \ud568\uaed8 \ubcf4\uc5ec \uc900\ub2e4. \uc7a5\ubc1c\uc7a5 \uc5ed\uc2dc \ucf54\uc81c\ud2b8\uc758 \ud589\ubcf5\uc744 \ubc14\ub780\ub2e4\ub294 \ub9c8\uc74c\uacfc \uc790\uc2e0 \uacc1\uc5d0 \ub450\uace0 \uc2f6\ub2e4\ub294 \ub9c8\uc74c \uc0ac\uc774\uc5d0\uc11c \ud754\ub4e4\ub9b0\ub2e4. \ud6c4\ubc18\uc758 \ubd09\uae30\ub294 1789\ub144 \ud504\ub791\uc2a4\ud601\uba85\uc774 \uc544\ub2c8\ub77c 1832\ub144 6\uc6d4 \ud30c\ub9ac\uc758 \ubd09\uae30\ub2e4. \ub77c\ub9c8\ub974\ud06c \uc7a5\uad70\uc758 \uc7a5\ub840\ub97c \uacc4\uae30\ub85c \uae34\uc7a5\uc774 \ub192\uc544\uc9c0\uace0, \uc559\uc878\ub77c\ub97c \ube44\ub86f\ud55c \uccad\ub144\ub4e4\uc740 \ubc14\ub9ac\ucf00\uc774\ub4dc\ub97c \uc313\ub294\ub2e4. \ud601\uba85\uc73c\ub85c \ubaa8\ub4e0 \ubb38\uc81c\uac00 \ud574\uacb0\ub41c \uc0ac\ud68c\uac00 \uc544\ub2c8\ub77c, \uadf8 \ub4a4\uc5d0\ub3c4 \ubd88\ud3c9\ub4f1\uacfc \uc815\uce58\uc801 \uac08\ub4f1\uc774 \ub0a8\uc544 \uc788\ub358 \uc0ac\ud68c\ub2e4. \uc774\uacf3\uc5d0\ub294 \uc815\uce58\uc801 \uc774\uc0c1\uc744 \ub9d0\ud558\ub294 \uccad\ub144\ub4e4\ubfd0 \uc544\ub2c8\ub77c \uac70\ub9ac\uc758 \uc18c\ub144 \uac00\ube0c\ub85c\uc288\ub3c4 \uc788\ub2e4. \ubd09\uae30\ub294 \uc7a5\ub300\ud55c \uc601\uc6c5\ub2f4\uc73c\ub85c\ub9cc \uc9c4\ud589\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc80a\uc740\uc774\ub4e4\uc774 \uc8fd\uace0, \uc5d0\ud3ec\ub2cc\ub3c4 \ub9c8\ub9ac\uc6b0\uc2a4 \uacc1\uc5d0\uc11c \ubaa9\uc228\uc744 \uc783\ub294\ub2e4. \uac1c\uc778\uc758 \uc0ac\ub791\uacfc \uc0ac\ud68c\ub97c \ubc14\uafb8\ub824\ub294 \uc5f4\ub9dd\uc774 \ud55c \uc7a5\uc18c\uc5d0\uc11c \ub9cc\ub098\ub294 \ub3d9\uc2dc\uc5d0, \uadf8 \ub300\uac00\uac00 \uc5bc\ub9c8\ub098 \ud070\uc9c0\ub3c4 \ub4dc\ub7ec\ub09c\ub2e4. \uc7a5\ubc1c\uc7a5\uc740 \ubc14\ub9ac\ucf00\uc774\ub4dc\uc5d0\uc11c \ubd99\uc7a1\ud78c \uc790\ubca0\ub974\ub97c \ucc98\ud615\ud558\ub294 \ub300\uc2e0 \ud480\uc5b4 \uc900\ub2e4. \uc790\ubca0\ub974\uc5d0\uac8c \uc7a5\ubc1c\uc7a5\uc740 \ubd99\uc7a1\uc544\uc57c \ud560 \ubc94\uc8c4\uc790\ub2e4. \uadf8\ub7f0\ub370 \uadf8 \uc0ac\ub78c\uc774 \uc790\uc2e0\uc744 \uc0b4\ub824 \ubcf4\ub0b8\ub2e4. \ubc95\uc744 \uc9c0\ud0a4\ub294 \uc0ac\ub78c\uc740 \uc120\ud558\uace0 \uc8c4\uc218\ub294 \uc545\ud558\ub2e4\ub294 \ub2e8\ub2e8\ud55c \uad6c\ubd84 \uc548\uc5d0 \ub4e4\uc5b4\uac00\uc9c0 \uc54a\ub294 \uc77c\uc774 \ubc8c\uc5b4\uc9c4 \uc148\uc774\ub2e4. \uc804\ud22c \ub4a4 \uc7a5\ubc1c\uc7a5\uc740 \ubd80\uc0c1\ud55c \ub9c8\ub9ac\uc6b0\uc2a4\ub97c \uc5c5\uace0 \ud558\uc218\ub3c4\ub97c \uc9c0\ub098 \ube60\uc838\ub098\uc628\ub2e4. \ucf54\uc81c\ud2b8\ub97c \uc790\uc2e0\uc5d0\uac8c\uc11c \ub370\ub824\uac08 \uc0ac\ub78c\uc744 \uad6c\ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c \uc774 \ud589\ub3d9\uc740 \ub354 \ubb34\uac81\ub2e4. \ub2e4\uc2dc \uc7a5\ubc1c\uc7a5\uc744 \ub9cc\ub09c \uc790\ubca0\ub974\ub294 \ub05d\ub0b4 \uadf8\ub97c \ub193\uc544\uc8fc\uc9c0\ub9cc, \uc790\uc2e0\uc774 \ubbff\uc5b4 \uc628 \uc9c8\uc11c\uc640 \ub208\uc55e\uc758 \uc778\uac04 \uc0ac\uc774\uc758 \ubaa8\uc21c\uc744 \uacac\ub514\uc9c0 \ubabb\ud558\uace0 \uc2a4\uc2a4\ub85c \uc0dd\uc744 \ub9c8\uac10\ud55c\ub2e4. \uc774 \uc8fd\uc74c\uc744 \ub2e8\uc21c\ud55c \uc545\ub2f9\uc758 \ud328\ubc30\ub85c \uc77d\uc73c\uba74 \uc18c\uc124\uc774 \uc624\ub798 \uc313\uc544 \uc628 \uac08\ub4f1\uc744 \ub193\uce58\uac8c \ub41c\ub2e4. \ub9c8\ub9ac\uc6b0\uc2a4\uc640 \ucf54\uc81c\ud2b8\ub294 \uacb0\ud63c\ud55c\ub2e4. \uc7a5\ubc1c\uc7a5\uc740 \uc790\uc2e0\uc758 \uc804\uacfc\ub97c \ub9c8\ub9ac\uc6b0\uc2a4\uc5d0\uac8c \uc54c\ub9ac\uace0, \uc624\ud574\uc640 \uac70\ub9ac\uac10 \uc18d\uc5d0\uc11c \uc810\ucc28 \ucf54\uc81c\ud2b8\uc758 \uc77c\uc0c1\uc5d0\uc11c \ubb3c\ub7ec\ub09c\ub2e4. \uc0b4\uc544\ub0a8\uc740 \uc0ac\ub78c\ub4e4\uc774 \ud589\ubcf5\ud574\uc84c\ub2e4\uace0 \ud574\uc11c \uadf8\ub4e4\uc744 \uc0b4\ub9b0 \uc0ac\ub78c\uc758 \ubaab\uae4c\uc9c0 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ubcf4\uc7a5\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc18c\uc124\uc740 \ucd95\ubcf5\uc758 \uc7a5\uba74 \ub4a4\uc5d0 \ub0a8\uc740 \uc678\ub85c\uc6c0\uae4c\uc9c0 \ub530\ub77c\uac04\ub2e4. \ub4a4\ub2a6\uac8c \ub9c8\ub9ac\uc6b0\uc2a4\ub294 \uc790\uc2e0\uc744 \uad6c\ud55c \uc0ac\ub78c\uc774 \uc7a5\ubc1c\uc7a5\uc774\uc5c8\uc74c\uc744 \uc54c\uac8c \ub41c\ub2e4. \ucf54\uc81c\ud2b8\uc640 \ud568\uaed8 \ucc3e\uc544\uac14\uc744 \ub54c \uc7a5\ubc1c\uc7a5\uc758 \uc0dd\uba85\uc740 \uc5bc\ub9c8 \ub0a8\uc9c0 \uc54a\uc558\ub2e4. \ub450 \uc0ac\ub78c\uc774 \uacc1\uc5d0 \uc788\ub294 \uac00\uc6b4\ub370 \uadf8\uc758 \uc0b6\uc740 \ub05d\uc744 \ub9fa\uace0, \uc8fc\uad50\uc5d0\uac8c \ubc1b\uc740 \uc740\ucd1b\ub300\ub294 \ub9c8\uc9c0\ub9c9 \uc7a5\uba74\uc5d0\ub3c4 \ub0a8\ub294\ub2e4. \ucc98\uc74c \ubc1b\uc558\ub358 \uc790\ube44\uac00 \uae34 \uc138\uc6d4 \ub3d9\uc548 \uc5b4\ub5a4 \uc0b6\uc73c\ub85c \uc774\uc5b4\uc84c\ub294\uc9c0\ub97c \ub3cc\uc544\ubcf4\uac8c \ud558\ub294 \ubb3c\uac74\uc774\ub2e4. \uc6d0\uc791\uc5d0\ub294 \uc6cc\ud138\ub8e8 \uc804\ud22c, \uc218\ub3c4\uc6d0, \ud30c\ub9ac\uc758 \ud558\uc218\ub3c4\ucc98\ub7fc \uc904\uac70\ub9ac\ub9cc \ub530\ub77c\uac00\ub824\ub294 \ub3c5\uc790\uc5d0\uac8c \uae38\uac8c \ub290\uaef4\uc9c8 \uc124\uba85\uc774 \uc788\ub2e4. \ub9c8\ub9ac\uc6b0\uc2a4\uc758 \uc544\ubc84\uc9c0\uc640 \ud14c\ub098\ub974\ub514\uc5d0\uac00 \uc5bd\ud78c \uacfc\uac70\ub97c \uc774\ud574\ud558\uac8c \ud558\ub294 \ub300\ubaa9\ub3c4 \uc788\uc9c0\ub9cc, \ubaa8\ub4e0 \uc124\uba85\uc774 \uc0ac\uac74\uc744 \ube68\ub9ac \uc9c4\ud589\uc2dc\ud0a4\uae30 \uc704\ud574 \uc874\uc7ac\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc704\uace0\ub294 \uc0ac\ub78c\uc774 \uc0b4\uc544\uac00\ub294 \uc0ac\ud68c \uc804\uccb4\ub97c \uc18c\uc124 \uc548\uc73c\ub85c \ub04c\uc5b4\ub4e4\uc774\ub824 \ud55c\ub2e4. \uc774\ub7f0 \ubd80\ubd84\uc744 \uc77d\uc73c\uba70 \uc911\uc2ec \uc9c8\ubb38\uc744 \ubd99\ub4e4\uc5b4 \ub450\uba74 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ubb34\uc5c7\uc774 \ud55c \uc0ac\ub78c\uc744 \ube44\ucc38\ud558\uac8c \ub9cc\ub4dc\ub294\uac00, \uc0ac\ub78c\uc744 \ubc14\uafb8\ub294 \uac83\uc740 \ubb34\uc5c7\uc778\uac00, \ubc95\uc774 \uc9c0\ucf1c \uc8fc\uc9c0 \ubabb\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c \uc5b4\ub5a4 \ucc45\uc784\uc744 \uc9c8 \uac83\uc778\uac00. \uc778\ubb3c\uc758 \uc120\ud0dd\uc5d0\uc11c \uc7a0\uc2dc \uba40\uc5b4\uc9c4 \uc124\uba85\ub3c4 \uc774 \uc9c8\ubb38\ub4e4\uacfc \uc5f0\uacb0\ud574 \ubcfc \uc218 \uc788\ub2e4. \ucc98\uc74c\ubd80\ud130 \ubaa8\ub4e0 \ubc30\uacbd\uc744 \uc678\uc6b0\ub824 \ud558\uae30\ubcf4\ub2e4, \uc9c0\uae08 \uc774 \uc7a5\uba74\uc774 \ub204\uad6c\uc758 \uc0b6\uc744 \ub354 \uc798 \ubcf4\uac8c \ud558\ub294\uc9c0 \uc0dd\uac01\ud574 \ubcf4\uc790. \uc7a5\ubc1c\uc7a5\uc740 \uc22d\uace0\ud55c \uc120\ud0dd\uc744 \ud558\uc9c0\ub9cc \ucc98\uc74c\ubd80\ud130 \uc644\uc131\ub41c \uc131\uc778\uc740 \uc544\ub2c8\ub2e4. \uc790\ubca0\ub974\ub294 \ubb34\uc870\uac74 \uc0ac\uc545\ud574\uc11c\ub9cc \uc6c0\uc9c1\uc774\uc9c0 \uc54a\uace0, \ucf54\uc81c\ud2b8\uc758 \uc0ac\ub791\ub3c4 \uc544\ubc84\uc9c0\uc758 \ud76c\uc0dd\uc744 \uc989\uc2dc \uc54c\uc544\ubcf4\ub294 \uc644\ubcbd\ud55c \uc774\ud574\ub85c \uc774\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uc774\ub7f0 \uc5b4\uae0b\ub0a8\uc774 \uc778\ubb3c\ub4e4\uc744 \ub2e8\uc21c\ud55c \uad50\ud6c8\uc758 \ud45c\uc9c0\ud310\ubcf4\ub2e4 \uc624\ub798 \uc0b4\uc544 \uc788\uac8c \ud55c\ub2e4. \u300e\ub808 \ubbf8\uc81c\ub77c\ube14\u300f\uc744 \uc77d\uace0 \ub0a8\ub294 \uac83\uc740 \ube75\uc744 \ud6d4\uce5c \uc8c4\uc218\uac00 \ud6cc\ub96d\ud55c \uc0ac\ub78c\uc774 \ub418\uc5c8\ub2e4\ub294 \uc904\uac70\ub9ac\ub9cc\uc774 \uc544\ub2c8\ub2e4. \ud321\ud2f4\uc5d0\uac8c\ub294 \uc65c \ubc84\ud2f8 \uc790\ub9ac\uac00 \uc5c6\uc5c8\ub294\uc9c0, \ucf54\uc81c\ud2b8\uc5d0\uac8c\ub294 \ub204\uac00 \uc190\uc744 \ub0b4\ubc00\uc5c8\ub294\uc9c0, \uc790\ubca0\ub974\ub294 \uc65c \ub2e4\ub978 \ud310\ub2e8\uc73c\ub85c \ub118\uc5b4\uac00\uc9c0 \ubabb\ud588\ub294\uc9c0\ub3c4 \ud568\uaed8 \ub0a8\ub294\ub2e4. \uc81c\ubaa9\uc774 \ubcf5\uc218\ud615\uc778 \uae4c\ub2ed\uc744 \ub5a0\uc62c\ub9ac\uba70 \ud55c \uc0ac\ub78c\uc529 \ub2e4\uc2dc \ubcf4\uba74, \uae34 \uc18c\uc124\uc740 \uc5ec\ub7ec \uc0b6\uc744 \uc774\ud574\ud558\ub294 \uae38\ub85c \ubc14\ub010\ub2e4."}, {"id": "liberty-lazarus-and-harbor-poem", "title": "\uc790\uc720\uc758 \uc5ec\uc2e0\uc0c1\uacfc \ub77c\uc790\ub8e8\uc2a4 \u2014 \uc870\uac01\uc0c1\uc740 \uc5b4\ub5bb\uac8c \ud658\uc601\uc758 \ubaa9\uc18c\ub9ac\ub97c \uc5bb\uc5c8\uc744\uae4c", "summary": "1883\ub144 \uc18c\ub124\ud2b8 \u300c\uc0c8\ub85c\uc6b4 \uac70\uc0c1\u300d\uc774 \uc870\uac01\uc0c1\uc5d0 \ub354\ud55c \ud658\uc601\uc758 \uc5b8\uc5b4\uc744 \uc774\uc57c\uae30\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/liberty-lazarus-and-harbor-poem/index.html", "image": "../media/liberty-lazarus-and-harbor-poem.jpg", "alt": "\uc5d0\ub4dc\uc6cc\ub4dc \ubaa8\ub7f0\uc758 1886\ub144 \uadf8\ub9bc \uc790\uc720\uc758 \uc5ec\uc2e0\uc0c1 \uc81c\ub9c9\uc2dd, \ud56d\uad6c\uc758 \ubc30\uc640 \uae43\ubc1c\ub4e4", "text": "\uc790\uc720\uc758 \uc5ec\uc2e0\uc0c1\uacfc \ub77c\uc790\ub8e8\uc2a4 \u2014 \uc870\uac01\uc0c1\uc740 \uc5b4\ub5bb\uac8c \ud658\uc601\uc758 \ubaa9\uc18c\ub9ac\ub97c \uc5bb\uc5c8\uc744\uae4c 1883\ub144 \uc18c\ub124\ud2b8 \u300c\uc0c8\ub85c\uc6b4 \uac70\uc0c1\u300d\uc774 \uc870\uac01\uc0c1\uc5d0 \ub354\ud55c \ud658\uc601\uc758 \uc5b8\uc5b4 1883\ub144 \uc18c\ub124\ud2b8 \u300c\uc0c8\ub85c\uc6b4 \uac70\uc0c1\u300d\uc774 \uc870\uac01\uc0c1\uc5d0 \ub354\ud55c \ud658\uc601\uc758 \uc5b8\uc5b4\uc744 \uc774\uc57c\uae30\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \ub274\uc695 \ud56d\uad6c\ub97c \ud5a5\ud574 \ud683\ubd88\uc744 \ub4e0 \uc5ec\uc778\uc774 \uc11c \uc788\ub2e4. \uc790\uc720\uc758 \uc5ec\uc2e0\uc0c1\uc744 \ubcf4\uba74 \uc774\ubbfc\uc790\ub97c \ub9de\uc774\ud558\ub294 \ubbf8\uad6d\uc758 \ubaa8\uc2b5\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc0ac\ub78c\uc774 \ub9ce\ub2e4. \uadf8\ub7f0\ub370 \uccad\ub3d9\ube5b \ud615\uc0c1\ub9cc\uc73c\ub85c \uadf8 \uc758\ubbf8\uac00 \ubaa8\ub450 \uc815\ud574\uc84c\uc744\uae4c. \uc870\uac01\uc0c1\uc5d0 \ud55c \ud3b8\uc758 \uc2dc\ub97c \uacb9\uccd0 \uc77d\uc73c\uba74 \ub9d0 \uc5c6\ub294 \uae30\ub150\ubb3c\uc774 \uc804\ud600 \ub2e4\ub978 \ubaa9\uc18c\ub9ac\ub97c \uc5bb\ub294\ub2e4. \uc5d0\ub9c8 \ub77c\uc790\ub8e8\uc2a4\uc758 \u300c\uc0c8\ub85c\uc6b4 \uac70\uc0c1\u300d\uc740 1883\ub144 \ubc1b\uce68\ub300 \uae30\uae08\uc744 \ub3d5\uae30 \uc704\ud574 \uc4f0\uc778 \uc18c\ub124\ud2b8\ub2e4. \uc774 \uc9e7\uc740 \uc2dc\ub294 \uac70\ub300\ud55c \ub3d9\uc0c1\uc774 \ub204\uad6c\ub97c \ud5a5\ud574 \uc11c \uc788\ub294\uc9c0 \ubb3b\ub294\ub2e4. \ud798\uc744 \uc790\ub791\ud558\ub294 \uae30\ub150\ubb3c\uc744 \uc5b4\ub824\uc6c0\uc5d0 \ucc98\ud55c \uc0ac\ub78c\uc744 \ubd80\ub974\ub294 \ud615\uc0c1\uc73c\ub85c \ub2e4\uc2dc \uc77d\uac8c \ub9cc\ub4e0 \uc791\ud488\uc774\ub2e4. \ud070 \uc870\uac01\uc0c1\uc740 \uc624\ub7ab\ub3d9\uc548 \uad8c\ub825\uacfc \uc2b9\ub9ac, \ub3c4\uc2dc\uc758 \ubd80\ub97c \ub4dc\ub7ec\ub0b4\ub294 \uc218\ub2e8\uc774\uc5c8\ub2e4. \uc791\uc544 \ubcf4\uc774\ub294 \uc778\uac04\uc758 \ubab8 \uc55e\uc5d0 \uac70\ub300\ud55c \ud615\uc0c1\uc744 \ub193\uc73c\uba74 \uadf8 \ud06c\uae30 \uc790\uccb4\uac00 \ud798\uc744 \uc804\ub2ec\ud55c\ub2e4. \ub204\uad6c\ub97c \uae30\ub150\ud558\ub294\uc9c0 \ubab0\ub77c\ub3c4 \uba3c\uc800 \uc555\ub3c4\ub420 \uc218 \uc788\ub2e4. \uae30\ub150\ubb3c\uc758 \uaddc\ubaa8\uc640 \uadf8\uac83\uc774 \ub9d0\ud558\ub824\ub294 \uac00\uce58\uac00 \ub9cc\ub098\ub294 \ubc29\uc2dd\uc774\ub2e4. \ub77c\uc790\ub8e8\uc2a4\ub294 \uc2dc\uc758 \uccab\uba38\ub9ac\uc5d0\uc11c \uadf8 \uc775\uc219\ud55c \uc2dc\uc120\uc744 \ubd88\ub7ec\uc628 \ub4a4 \ubc29\ud5a5\uc744 \ub3cc\ub9b0\ub2e4. \uace0\ub300 \uadf8\ub9ac\uc2a4\uc758 \uac70\ub300\ud55c \uc0c1\uacfc \uc0c8 \uc5ec\uc2e0\uc0c1\uc744 \ub098\ub780\ud788 \ub193\uc9c0\ub9cc, \ub2ee\uc558\ub2e4\uace0 \uce6d\ucc2c\ud558\uae30 \uc704\ud574\uc11c\uac00 \uc544\ub2c8\ub2e4. \uc0c8\ub85c\uc6b4 \uae30\ub150\ubb3c\uc774 \uc774\uc804\uacfc \ub2e4\ub978 \uc874\uc7ac\uac00 \ub418\uc5b4\uc57c \ud55c\ub2e4\ub294 \uae30\ub300\ub97c \uadf8 \ube44\uad50 \uc18d\uc5d0 \ub2f4\ub294\ub2e4. \u300c\uc0c8\ub85c\uc6b4 \uac70\uc0c1\u300d\uc774\ub77c\ub294 \uc81c\ubaa9\uc5d0\uc11c \uc911\uc694\ud55c \ub9d0\uc740 \ud06c\uae30\ub9cc\uc774 \uc544\ub2c8\ub77c \uc0c8\ub85c\uc6c0\uc774\ub2e4. \uc2dc\uc5d0 \ub4f1\uc7a5\ud558\ub294 \uc5ec\uc778\uc740 \uc815\ubcf5\uc790\uc758 \ud314\ub2e4\ub9ac\ub97c \ub0b4\uc138\uc6b4 \uace0\ub300\uc758 \uac70\uc778\uacfc \uad6c\ubcc4\ub41c\ub2e4. \uac19\uc740 \uac70\ub300\ud568\uc774\ub77c\ub3c4 \uadf8\uac83\uc744 \ub204\uad6c\uc5d0\uac8c \uc5b4\ub5a4 \ubaa9\uc801\uc73c\ub85c \uc0ac\uc6a9\ud558\ub294\uc9c0\uc5d0 \ub530\ub77c \uc758\ubbf8\uac00 \ub2ec\ub77c\uc9c4\ub2e4\ub294 \uac83\uc774\ub2e4. \uadf8\ub798\uc11c \uc774 \uc2dc\ub294 \uc870\uac01\uc758 \ubaa8\uc591\uc744 \uc815\ud655\ud788 \ubb18\uc0ac\ud558\ub294 \uc548\ub0b4\ubb38\uc5d0 \uba38\ubb3c\uc9c0 \uc54a\ub294\ub2e4. \ub3c5\uc790\uac00 \uc774\ubbf8 \uc54c\uace0 \uc788\ub294 \uae30\ub150\ubb3c\uc758 \uc5b8\uc5b4\ub97c \ubc14\uafb8\ub294 \ud574\uc11d\uc774\ub2e4. \uac15\ud55c \ub3c4\uc2dc\uac00 \uc790\uc2e0\uc744 \uc790\ub791\ud558\ub294 \ub300\uc2e0, \ubc14\ub2e4\ub97c \uac74\ub108\uc624\ub294 \uc57d\ud55c \uc0ac\ub78c\uc5d0\uac8c \uc5b4\ub5a4 \ub9d0\uc744 \uac74\ub12c \uc218 \uc788\ub294\uc9c0 \uc0c1\uc0c1\ud558\uac8c \ud55c\ub2e4. \uc2dc \uc18d \ud683\ubd88\uc740 \uac07\ud78c \ubc88\uac1c\ucc98\ub7fc \ubb18\uc0ac\ub41c\ub2e4. \ubc1d\uc740 \ube5b\uc758 \ud798\uc740 \uc788\uc9c0\ub9cc \uadf8 \ube5b\uc774 \ud5a5\ud558\ub294 \uacf3\uc740 \uc801\uc774 \uc544\ub2c8\ub2e4. \ub0af\uc120 \ud56d\uad6c\uc5d0 \ub3c4\ucc29\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c \uae38\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc190\uc73c\ub85c \uc77d\ud78c\ub2e4. \uac19\uc740 \ubd88\ube5b\ub3c4 \uacf5\uaca9\uc758 \uc2e0\ud638\uc640 \uc548\ub0b4\uc758 \ud45c\uc9c0 \uac00\uc6b4\ub370 \uc5b4\ub290 \uac83\uc73c\ub85c \uc774\ud574\ud558\ub290\ub0d0\uc5d0 \ub530\ub77c \ub2e4\ub978 \uc7a5\uba74\uc744 \ub9cc\ub4e0\ub2e4. \ub77c\uc790\ub8e8\uc2a4\ub294 \ubc14\ub2e4\uc640 \ud574 \uc9c8 \ubb34\ub835\uc758 \ubb38, \ud56d\uad6c\ub97c \ud568\uaed8 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uc5ec\uc2e0\uc0c1\uc774 \ub193\uc778 \uacf5\uac04\uc740 \uc774\ucc98\ub7fc \uc2dc\uc758 \uc758\ubbf8\uc5d0 \ucc38\uc5ec\ud55c\ub2e4. \ub0b4\ub959\uc758 \uad11\uc7a5\uc5d0\uc11c \ubcf4\ub294 \uae30\ub150\ubb3c\uacfc \ubc14\ub2e4\ub97c \uac74\ub108\uc640 \ub9c8\uc8fc\ud558\ub294 \uae30\ub150\ubb3c\uc740 \ub2e4\ub974\ub2e4. \ub2e4\uac00\uc624\ub294 \uc0ac\ub78c\uc758 \uc2dc\uc810\uc73c\ub85c \ubcfc \ub54c \ud683\ubd88\uc740 \ub3c4\ucc29\uc758 \uac10\uc815\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc2dc\uc778\uc740 \uc5ec\uc2e0\uc0c1\uc5d0\uac8c \ub9dd\uba85\uc790\ub4e4\uc758 \uc5b4\uba38\ub2c8\ub77c\ub294 \uc774\ub984\uc744 \uc900\ub2e4. \uc601\ud1a0\ub97c \ucc28\uc9c0\ud55c \uc2b9\ub9ac\uc790\uac00 \uc544\ub2c8\ub77c \uc9d1\uc744 \ub5a0\ub09c \uc0ac\ub78c\uc744 \ub9de\uc774\ud558\ub294 \uc874\uc7ac\ub2e4. \uc5b4\uba38\ub2c8\ub77c\ub294 \ube44\uc720\uc5d0\ub294 \uac15\ud55c \uad6d\uac00\uc758 \ud798\uacfc\ub294 \ub2e4\ub978 \uc885\ub958\uc758 \ubcf4\ud638\uac00 \ub2f4\uae34\ub2e4. \ud06c\uae30\ub294 \uc5ec\uc804\ud558\uc9c0\ub9cc \uadf8\uac83\uc744 \uc0ac\uc6a9\ud558\ub294 \ubc29\ud5a5\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc774 \uc774\ub984\uc774 \uc5ec\uc2e0\uc0c1 \uac74\ub9bd\uc758 \ubaa8\ub4e0 \uc758\ub3c4\ub97c \ub300\uc2e0\ud55c\ub2e4\uace0 \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ud55c \uc791\ud488\uc774 \uc774\ubbf8 \uc788\ub294 \uc870\ud615\ubb3c\uc5d0 \uc0c8\ub85c\uc6b4 \ud574\uc11d\uc744 \ub354\ud588\ub2e4\ub294 \uc0ac\uc2e4\uc774\ub2e4. \ub3cc\uc774\ub098 \uae08\uc18d\uc73c\ub85c \ub9cc\ub4e0 \uae30\ub150\ubb3c\ub3c4 \uc758\ubbf8\uac00 \uc644\uc804\ud788 \uace0\uc815\ub418\uc5b4 \uc788\uc9c0 \uc54a\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \uae00\uacfc \uc758\uc2dd, \uae30\uc5b5\uc744 \ud1b5\ud574 \uacc4\uc18d \uadf8 \ub73b\uc744 \uc77d\uace0 \ubc14\uafbc\ub2e4. \ud6c4\ubc18\ubd80\uc758 \uc5ec\uc778\uc740 \uc9c0\uce58\uace0 \uac00\ub09c\ud55c \uc0ac\ub78c, \uc790\uc720\ub97c \ubc14\ub77c\uba70 \ubaa8\uc5ec \uc788\ub294 \uc0ac\ub78c\uacfc \uc9d1 \uc5c6\ub294 \uc0ac\ub78c\uc744 \ubd80\ub978\ub2e4. \ub098\ub77c\uc758 \uba85\uc608\uc5d0 \ubcf4\ud0ec\uc774 \ub420 \uc0ac\ub78c\ub9cc \uac00\ub824 \ud658\uc601\ud558\ub294 \uc5b8\uc5b4\uc640 \ub2e4\ub974\ub2e4. \ub3c5\uc790\ub294 \ud56d\uad6c\uc758 \ud48d\uacbd\uc5d0\uc11c \ubc30\uc5d0 \ud0c4 \uc775\uba85\uc758 \uc0ac\ub78c\ub4e4\ub85c \uc2dc\uc120\uc744 \uc62e\uae30\uac8c \ub41c\ub2e4. \uc774 \ub300\ubaa9\uc744 \uc544\ub984\ub2e4\uc6b4 \uad6c\ud638\ub85c\ub9cc \uc77d\uc73c\uba74 \ud798\uc774 \uc57d\ud574\uc9c4\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \uc65c \uc9c0\ucce4\uace0 \uc65c \uc9d1\uc744 \ub5a0\ub098\uc57c \ud588\ub294\uc9c0\uae4c\uc9c0 \uc0dd\uac01\ud558\uba74 \ud658\uc601\uc774\ub77c\ub294 \ub9d0\uc758 \ubb34\uac8c\uac00 \ucee4\uc9c4\ub2e4. \uc2dc\ub294 \uac1c\ubcc4 \uc774\uc8fc\uc790\uc758 \uc0ac\uc815\uc744 \ubaa8\ub450 \uc124\uba85\ud558\uc9c0 \uc54a\uc9c0\ub9cc, \uae30\ub150\ubb3c\uc744 \ubcf4\ub294 \ub3c5\uc790\uc5d0\uac8c \ub204\uad6c\uc758 \ucc98\uc9c0\ub97c \uba3c\uc800 \ub5a0\uc62c\ub9b4\uc9c0 \uc120\ud0dd\ud558\uac8c \ud55c\ub2e4. \ud658\uc601\uc758 \uc5b8\uc5b4\uac00 \uc874\uc7ac\ud55c\ub2e4\uace0 \ud574\uc11c \ud55c \uc0ac\ud68c\uc758 \uc2e4\uc81c \uc774\ubbfc \uc81c\ub3c4\uac00 \uc5b8\uc81c\ub098 \uadf8 \uc5b8\uc5b4\uc640 \uc77c\uce58\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb38\ud559 \uc791\ud488\uc740 \ubc95\ub960 \uc870\ubb38\ub3c4 \uc544\ub2c8\uace0 \ubaa8\ub4e0 \uc2dc\ub300\uc758 \ud604\uc2e4\uc744 \uc99d\uba85\ud558\ub294 \uae30\ub85d\ub3c4 \uc544\ub2c8\ub2e4. \uc2dc \uc18d\uc758 \uc774\uc0c1\uc744 \uadf8\ub300\ub85c \uc5ed\uc0ac \uc804\uccb4\uc758 \uc0ac\uc2e4\ub85c \ubc14\uafb8\uc5b4 \uc77d\uc73c\uba74 \uace4\ub780\ud558\ub2e4. \uc624\ud788\ub824 \uc774\uc0c1\uacfc \ud604\uc2e4 \uc0ac\uc774\uc758 \uac70\ub9ac\ub97c \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \uc774 \uc0ac\ud68c\ub294 \uc790\uc2e0\uc774 \uc18c\uc911\ud558\uac8c \ub0b4\uc138\uc6b4 \ub9d0\uc744 \uc5bc\ub9c8\ub098 \uc2e4\ucc9c\ud588\ub294\uac00. \ub204\uad6c\uc5d0\uac8c \ubb38\uc774 \uc5f4\ub838\uace0 \ub204\uad6c\uc5d0\uac8c \uc5b4\ub824\uc6e0\ub294\uac00. \uadf8\ub7f0 \uc9c8\ubb38\uc744 \uac00\ub2a5\ud558\uac8c \ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c \uc2dc\ub294 \ud604\uc2e4\uc744 \uac00\ub9ac\ub294 \uc7a5\uc2dd\uc774 \uc544\ub2c8\ub77c \ud604\uc2e4\uc744 \ud3c9\uac00\ud558\ub294 \uae30\uc900\uc774 \ub418\uae30\ub3c4 \ud55c\ub2e4. \ud55c \ud3b8\uc758 \uc18c\ub124\ud2b8\ub294 \uac70\ub300\ud55c \ub3d9\uc0c1\uc744 \ub9cc\ub4e4 \ub9cc\ud07c\uc758 \uc7ac\ub8cc\ub97c \uac16\uace0 \uc788\uc9c0 \uc54a\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \ub3d9\uc0c1\uc744 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5a4 \uc874\uc7ac\ub85c \uae30\uc5b5\ud560\uc9c0\uc5d0 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\ub2e4. \ub77c\uc790\ub8e8\uc2a4\uc758 \uc791\ud488\uc744 \uc77d\uc73c\uba74 \uc790\uc720\uc758 \uc5ec\uc2e0\uc0c1\uc740 \ucd94\uc0c1\uc801\uc778 \uc790\uc720\uc758 \ud45c\uc9c0\uc5d0\uc11c \ub3c4\ucc29\ud558\ub294 \uc0ac\ub78c\uc744 \ubc14\ub77c\ubcf4\ub294 \uc778\ubb3c\ub85c \ubc14\ub010\ub2e4. \ub3c5\uc790\ub294 \uc2dc\uc758 \uccab \ube44\uad50\uc640 \ub9c8\uc9c0\ub9c9 \ucd08\ub300\ub97c \uc5f0\uacb0\ud574 \uc77d\uc5b4 \ubcfc \uc218 \uc788\ub2e4. \uc55e\uc5d0\uc11c\ub294 \uc5b4\ub5a4 \uac70\uc0c1\uc774 \ub418\uc9c0 \uc54a\uc744\uc9c0 \ub9d0\ud558\uace0 \ub4a4\uc5d0\uc11c\ub294 \ub204\uad6c\ub97c \ub9de\uc774\ud560\uc9c0 \ubc1d\ud78c\ub2e4. \uc9e7\uc740 \ud615\uc2dd \uc548\uc5d0\uc11c \ubd80\uc815\uacfc \ucd08\ub300\uac00 \uc774\uc5b4\uc9c0\uba70 \uc5ec\uc2e0\uc0c1\uc758 \uc131\uaca9\uc774 \ub610\ub837\ud574\uc9c4\ub2e4. \ub2e4\uc74c\uc5d0 \ud683\ubd88\uc744 \ub4e0 \ud615\uc0c1\uc744 \ubcfc \ub54c\uc5d0\ub294 \ud06c\uae30\uc640 \uc0c9\uae54 \uc606\uc5d0 \uc2dc\uc758 \ubaa9\uc18c\ub9ac\ub3c4 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uac74\ucd95\uacfc \uc870\uac01\uc744 \uc774\ud574\ud558\ub294 \uc77c\uc774 \ub208\uc5d0 \ubcf4\uc774\ub294 \uac83\uc744 \uc124\uba85\ud558\ub294 \ub370\uc11c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c \uc218 \uc788\ub2e4. \ub204\uad70\uac00\uac00 \uac70\uae30\uc5d0 \uc5b4\ub5a4 \ub9d0\uc744 \uac74\ub138\ub294\uc9c0\uae4c\uc9c0 \uc77d\uc744 \ub54c \uae30\ub150\ubb3c\uc758 \uc5ed\uc0ac\ub294 \ub354 \ub113\uc5b4\uc9c4\ub2e4."}, {"id": "little-mermaid-voice-and-soul", "title": "\uc778\uc5b4\uacf5\uc8fc \u2014 \ubaa9\uc18c\ub9ac\ub97c \ub0b4\uc8fc\uace0 \uc5bb\uc73c\ub824 \ud588\ub358 \uac83\uc740 \ubb34\uc5c7\uc77c\uae4c", "summary": "\uc0ac\ub791\uacfc \ubd88\uba78\uc758 \uc601\ud63c\uc744 \ubc14\ub780 \uc778\uc5b4\uacf5\uc8fc\uc758 \ub300\uac00\uc640 \ub9c8\uc9c0\ub9c9 \uc120\ud0dd\uc744 \uc6d0\uc791\uc758 \uacb0\ub9d0\uae4c\uc9c0 \ub530\ub77c\uac11\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc2e0\ud654\uc640 \ubbfc\uc18d", "categories": ["arts"], "url": "stories/little-mermaid-voice-and-soul/index.html", "image": "../media/little-mermaid-voice-and-soul.png", "alt": "\ubc14\ub2e4 \ubc11\uc5d0\uc11c \ud574\uc548\uacfc \ubc94\uc120\uc744 \uc62c\ub824\ub2e4\ubcf4\ub294 \uac80\uc740 \uba38\ub9ac \uc778\uc5b4\ub97c \uadf8\ub9b0 \uc6d0\uc791 \ubd84\uc704\uae30 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uc778\uc5b4\uacf5\uc8fc \u2014 \ubaa9\uc18c\ub9ac\ub97c \ub0b4\uc8fc\uace0 \uc5bb\uc73c\ub824 \ud588\ub358 \uac83\uc740 \ubb34\uc5c7\uc77c\uae4c \uc548\ub370\ub974\uc13c \uc6d0\uc791\uc758 \ubcc0\uc2e0\uacfc \uce68\ubb35, \uacf5\uae30\uc758 \ub538\ub4e4\uc774 \uc5ec\ub294 \uacb0\ub9d0 \uc0ac\ub791\uacfc \ubd88\uba78\uc758 \uc601\ud63c\uc744 \ubc14\ub780 \uc778\uc5b4\uacf5\uc8fc\uc758 \ub300\uac00\uc640 \ub9c8\uc9c0\ub9c9 \uc120\ud0dd\uc744 \uc6d0\uc791\uc758 \uacb0\ub9d0\uae4c\uc9c0 \ub530\ub77c\uac11\ub2c8\ub2e4. \uc2e0\ud654\uc640 \ubbfc\uc18d \ubb38\ud654\uc640 \uc608\uc220 \ubc14\ub2e4\uc758 \uacf5\uc8fc\uac00 \uc778\uac04\uc758 \uc655\uc790\ub97c \uc0ac\ub791\ud55c\ub2e4. \uc548\ub370\ub974\uc13c\uc758 \u300e\uc778\uc5b4\uacf5\uc8fc\u300f\ub294 \uc775\uc219\ud55c \uc2dc\uc791 \ub4a4\uc5d0 \ubaa9\uc18c\ub9ac\uc640 \ubab8, \uc120\ud0dd\uacfc \uc601\ud63c\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\ub97c \uc774\uc5b4 \uac04\ub2e4. \uc655\uc790\uc640 \ud568\uaed8 \uc0ac\ub294 \uc77c\ub9cc\uc774 \uc8fc\uc778\uacf5\uc758 \ubaa8\ub4e0 \uc18c\ub9dd\uc740 \uc544\ub2c8\ub2e4. \uc6d0\uc791\uc744 \uc77d\uc73c\uba74 \ubc14\ub2e4\uc640 \uc778\uac04 \uc138\uacc4\ub97c \ub098\ub204\ub294 \ub354 \uae4a\uc740 \ucc28\uc774\uac00 \ub098\ud0c0\ub09c\ub2e4. \uc774 \uae00\uc5d0\ub294 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc774 \ud3ec\ud568\ub41c\ub2e4. \uc0ac\ub791\uc744 \uc704\ud574 \ub300\uac00\ub97c \uce58\ub974\ub294 \uc544\ub984\ub2e4\uc6b4 \uc774\uc57c\uae30\ub77c\uace0\ub9cc \uc18c\uac1c\ud558\uba74 \ub9c8\uc9c0\ub9c9\uc758 \uc544\ud514\uacfc \uc120\ud0dd\uc774 \uc57d\ud574\uc9c8 \uc218 \uc788\ub2e4. \uc778\uc5b4\uacf5\uc8fc\uac00 \ubb34\uc5c7\uc744 \uc5bb\uace0 \uc2f6\uc5c8\uc73c\uba70 \ub05d\ub0b4 \ubb34\uc5c7\uc744 \ud558\uc9c0 \uc54a\uae30\ub85c \ud588\ub294\uc9c0 \ub530\ub77c\uac00 \ubcf4\uc790. \uc778\uc5b4\uacf5\uc8fc\ub294 \ubc14\ub2e4 \ubc11 \uc655\uad6d\uc5d0\uc11c \uc0b4\uc9c0\ub9cc \uc778\uac04\uc758 \uc138\uacc4\uc5d0 \uad00\uc2ec\uc774 \ub9ce\ub2e4. \uc5b8\ub2c8\ub4e4\uc5d0\uac8c \ub4e4\uc740 \uc774\uc57c\uae30\uc640 \ubc14\ub2e4 \uc704\uc5d0\uc11c \ubcf8 \ud48d\uacbd\uc740 \uc544\uc9c1 \uac00 \ubcf4\uc9c0 \ubabb\ud55c \uc0b6\uc744 \uc0c1\uc0c1\ud558\uac8c \ud55c\ub2e4. \uc790\uc2e0\uc758 \uc138\uacc4\uac00 \ud48d\uc694\ub86d\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ub2e4\ub978 \uc0b6\uc744 \ud5a5\ud55c \ud638\uae30\uc2ec\uc774 \uc0ac\ub77c\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc774 \ub3d9\uacbd\uc5d0\ub294 \uc0ac\ub791\ubcf4\ub2e4 \uba3c\uc800 \uc0dd\uae34 \ubd80\ubd84\uc774 \uc788\ub2e4. \uc778\uac04\uc740 \uc5b4\ub5bb\uac8c \uc0b4\uace0 \uadf8\ub4e4\uc758 \uc2dc\uac04\uc740 \uc5b4\ub5bb\uac8c \ub05d\ub098\ub294\uc9c0 \uad81\uae08\ud574\ud55c\ub2e4. \uc6d0\uc791\uc5d0\uc11c \uc778\uc5b4\uc640 \uc778\uac04\uc758 \ucc28\uc774\ub294 \ub2e4\ub9ac\uc640 \uaf2c\ub9ac\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uc0b6\uc758 \uae38\uc774\uc640 \uc8fd\uc74c \ub4a4\uc758 \uc874\uc7ac\uc5d0 \ub300\ud55c \uc124\uba85\ub3c4 \uc911\uc694\ud558\ub2e4. \uc774\ud6c4\uc758 \uc120\ud0dd\uc744 \uc774\ud574\ud558\ub824\uba74 \uc774 \ubc30\uacbd\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc778\uc5b4\uacf5\uc8fc\ub294 \ud3ed\ud48d \uc18d\uc5d0\uc11c \uc704\ud5d8\uc5d0 \ube60\uc9c4 \uc655\uc790\ub97c \uad6c\ud574 \ud574\ubcc0\uc73c\ub85c \ub370\ub824\uac04\ub2e4. \uadf8\ub7ec\ub098 \uc655\uc790\ub294 \uc790\uc2e0\uc744 \uad6c\ud55c \uc0ac\ub78c\uc774 \ub204\uad6c\uc778\uc9c0 \uc81c\ub300\ub85c \uc54c\uc9c0 \ubabb\ud55c\ub2e4. \uadf8\ub140\uac00 \ubc14\ub77c\ub294 \uad00\uacc4\ub294 \uc774\ubbf8 \uc815\ubcf4\uc758 \uc5b4\uae0b\ub0a8 \uc704\uc5d0\uc11c \uc2dc\uc791\ub41c\ub2e4. \ub3c5\uc790\uac00 \uc544\ub294 \uc0ac\uc2e4\uacfc \uc655\uc790\uac00 \ubbff\ub294 \uc774\uc57c\uae30\uac00 \ub2e4\ub974\ub2e4. \uc774 \uc7a5\uba74\uc740 \ub2e8\uc21c\ud788 \uc5b8\uc820\uac00 \uc624\ud574\uac00 \ud480\ub9b4 \uc900\ube44\ub9cc\uc774 \uc544\ub2c8\ub2e4. \ub3c4\uc6c0\uc744 \uc900 \uc0ac\ub78c\uc758 \ub9c8\uc74c\uacfc \ub3c4\uc6c0\ubc1b\uc740 \uc0ac\ub78c\uc774 \uae30\uc5b5\ud558\ub294 \ubaa8\uc2b5\uc774 \uc77c\uce58\ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc778\uc5b4\uacf5\uc8fc\uc5d0\uac8c\ub294 \uacb0\uc815\uc801\uc778 \ub9cc\ub0a8\uc774\uc5c8\uc9c0\ub9cc \uc655\uc790\ub294 \uac19\uc740 \ub9cc\ub0a8\uc744 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uc774\ud574\ud55c\ub2e4. \uadf8 \ucc28\uc774\uac00 \uc624\ub798 \ub0a8\ub294\ub2e4. \ud560\uba38\ub2c8\uc758 \uc124\uba85\uc744 \ud1b5\ud574 \uc778\uc5b4\uacf5\uc8fc\ub294 \uc778\uac04\uc5d0\uac8c \ubd88\uba78\uc758 \uc601\ud63c\uc774 \uc788\ub2e4\ub294 \uc774\uc57c\uae30\ub97c \ub4e3\ub294\ub2e4. \uae34 \uc0b6 \ub4a4 \ubc14\ub2e4\uc758 \uac70\ud488\uc73c\ub85c \uc0ac\ub77c\uc9c0\ub294 \uc778\uc5b4\uc758 \uc6b4\uba85\uacfc \ub2e4\ub974\ub2e4. \uc778\uac04\uc744 \ud5a5\ud55c \ub3d9\uacbd\uc5d0\ub294 \uc655\uc790\uc758 \uc0ac\ub791\ubfd0 \uc544\ub2c8\ub77c \uc8fd\uc74c \uc774\ud6c4\uc5d0\ub3c4 \uc774\uc5b4\uc9c8 \uc874\uc7ac\uc5d0 \ub300\ud55c \ubc14\ub78c\uc774 \uacb9\uce5c\ub2e4. \uc774 \uc885\uad50\uc801 \uc694\uc18c\ub97c \ube7c\uba74 \uc6d0\uc791\uc758 \uacb0\ub9d0\uc774 \ub0af\uc124\uac8c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uc548\ub370\ub974\uc13c\uc740 \ub2e4\ub978 \ubab8\uc744 \uc5bb\ub294 \ubaa8\ud5d8\uacfc \uc601\ud63c\uc744 \uc5bb\ub294 \ubb38\uc81c\ub97c \ud568\uaed8 \uc5ee\uc5c8\ub2e4. \uc624\ub298\uc758 \ub3c5\uc790\uac00 \uac19\uc740 \ubbff\uc74c\uc744 \uac00\uc838\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc, \uc791\ud488 \uc548\uc5d0\uc11c \uadf8 \uc18c\ub9dd\uc774 \uc65c \uc911\uc694\ud55c\uc9c0 \uc774\ud574\ud560 \ud544\uc694\ub294 \uc788\ub2e4. \ubc14\ub2e4 \ub9c8\ub140\ub294 \uc778\uc5b4\uacf5\uc8fc\uc5d0\uac8c \uc778\uac04\uc758 \ub2e4\ub9ac\ub97c \uc5bb\uc744 \uae38\uc744 \uc81c\uc2dc\ud55c\ub2e4. \ub300\uac00\ub294 \uc544\ub984\ub2e4\uc6b4 \ubaa9\uc18c\ub9ac\uc774\uba70 \uac77\ub294 \uc77c\uc5d0\ub294 \uace0\ud1b5\uc774 \ub530\ub978\ub2e4. \uc778\uac04 \uc138\uacc4\uc5d0 \ub4e4\uc5b4\uac08 \uc218 \uc788\uc9c0\ub9cc \uc790\uc2e0\uc774 \ub204\uad6c\uc774\uace0 \ubb34\uc5c7\uc744 \ud588\ub294\uc9c0 \ub9d0\ud560 \uc911\uc694\ud55c \uc218\ub2e8\uc744 \uc783\ub294\ub2e4. \ubcc0\uc2e0\uc740 \uac00\ub2a5\uc131\uc744 \uc5ec\ub294 \ub3d9\uc2dc\uc5d0 \ub2e4\ub978 \ub2a5\ub825\uc744 \ub2eb\uc544 \ubc84\ub9b0\ub2e4. \uc655\uc790\uc5d0\uac8c\ub294 \ub9e4\ub825\uc801\uc778 \ub0af\uc120 \uc18c\ub140\ub85c \ubcf4\uc774\uc9c0\ub9cc \uadf8\ub140\uc758 \uc0dd\uac01\uc744 \ucda9\ubd84\ud788 \uc804\ud558\uae30 \uc5b4\ub835\ub2e4. \uc678\ubaa8\uc640 \uc6c0\uc9c1\uc784\uc774 \uc8fc\ub294 \uc778\uc0c1, \ubaa9\uc18c\ub9ac\ub85c \uc124\uba85\ud558\ub294 \uc790\uae30 \uc0b6 \uc0ac\uc774\uc758 \ucc28\uc774\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \uc0ac\ub791\ud558\ub294 \uc0ac\ub78c \uac00\uae4c\uc774\uc5d0 \ub3c4\ucc29\ud588\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc11c\ub85c\ub97c \uc774\ud574\ud560 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uac19\uc740 \uac83\uc774 \uc544\ub2c8\ub2e4. \uadf8\ub140\ub294 \uc655\uc790 \uacc1\uc5d0\uc11c \uc544\ub984\ub2f5\uac8c \ucda4\uc744 \ucd94\uc9c0\ub9cc \ub3c5\uc790\ub294 \uadf8 \uc6c0\uc9c1\uc784\uc5d0 \uc544\ud514\uc774 \ub530\ub978\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc548\ub2e4. \ubc16\uc5d0\uc11c \ubcf4\ub294 \uc6b0\uc544\ud568\uacfc \ub2f9\uc0ac\uc790\uac00 \uacaa\ub294 \ubab8\uc758 \uacbd\ud5d8\uc774 \ub2e4\ub974\ub2e4. \ubaa9\uc18c\ub9ac\ub97c \uc783\uc740 \ub4a4\uc758 \uc0b6\uc744 \uc678\ubaa8\uac00 \uc544\ub984\ub2e4\uc6cc\uc9c4 \uacb0\uacfc\ub9cc\uc73c\ub85c \uc124\uba85\ud560 \uc218 \uc5c6\ub294 \uc774\uc720\ub2e4. \uc655\uc790\ub294 \uc790\uc2e0\uc774 \uad6c\ud574\uc84c\uc744 \ub54c \ub9cc\ub0ac\ub2e4\uace0 \ubbff\ub294 \ub2e4\ub978 \uc5ec\uc778\uacfc \uacb0\ud63c\ud55c\ub2e4. \uc778\uc5b4\uacf5\uc8fc\uc5d0\uac8c\ub294 \ub2e8\uc21c\ud55c \uc2e4\uc5f0\ubcf4\ub2e4 \ub354 \ud070 \uc704\uae30\uac00 \uc628\ub2e4. \ub9c8\ub140\uc640\uc758 \uc870\uac74\uc5d0 \ub530\ub77c \uc790\uc2e0\uc774 \ubc14\ub2e4\uc758 \uac70\ud488\uc73c\ub85c \uc0ac\ub77c\uc9c8 \uc2dc\uac04\uc774 \ub2e4\uac00\uc624\uae30 \ub54c\ubb38\uc774\ub2e4. \uc655\uc790\uc758 \ud589\ubcf5\uacfc \uadf8\ub140\uc758 \uc808\ub9dd\uc774 \uac19\uc740 \uc794\uce58\uc758 \uc2dc\uac04 \uc548\uc5d0 \uc788\ub2e4. \uc774\ub54c \uc791\ud488\uc740 \ub204\uac00 \ub354 \uc0ac\ub791\ud588\uc73c\ub2c8 \ub204\uad6c\uc640 \uacb0\ud63c\ud574\uc57c \ud55c\ub2e4\ub294 \uacc4\uc0b0\uc73c\ub85c \ud574\uacb0\ub418\uc9c0 \uc54a\ub294\ub2e4. \uadf8\ub140\uc758 \ud76c\uc0dd\uc774 \ud06c\ub2e4\uace0 \uc655\uc790\uc758 \ub9c8\uc74c\uc744 \uac15\uc81c\ub85c \uc5bb\uc744 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uadf8\uac00 \ubaa8\ub974\ub294 \uc0ac\uc2e4\uacfc \uadf8\ub140\uac00 \ub9d0\ud558\uc9c0 \ubabb\ud558\ub294 \uc0b6\uc774 \ub3c5\uc790\uc5d0\uac8c\ub294 \uacc4\uc18d \ubcf4\uc778\ub2e4. \uadf8 \uac70\ub9ac\uac00 \ube44\uadf9\uc758 \ubb34\uac8c\ub97c \ub9cc\ub4e0\ub2e4. \uc5b8\ub2c8\ub4e4\uc740 \uc778\uc5b4\uacf5\uc8fc\uac00 \ubc14\ub2e4\ub85c \ub3cc\uc544\uac08 \ub9c8\uc9c0\ub9c9 \uae30\ud68c\ub97c \ub9c8\ub828\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uae38\uc5d0\ub294 \uc655\uc790\ub97c \uc8fd\uc5ec\uc57c \ud55c\ub2e4\ub294 \uc870\uac74\uc774 \ubd99\ub294\ub2e4. \uc0b4\uc544\ub0a8\uace0 \uc2f6\uc740 \ub9c8\uc74c\uacfc \uc0ac\ub791\ud558\ub294 \uc0ac\ub78c\uc758 \uc0dd\uba85 \uc0ac\uc774\uc5d0\uc11c \uc120\ud0dd\ud574\uc57c \ud55c\ub2e4. \uc774\uc81c \uc9c8\ubb38\uc740 \uadf8\ub97c \uc5bb\uc744 \uc218 \uc788\ub294\uac00\uc5d0\uc11c \uc790\uc2e0\uc744 \uc704\ud574 \uadf8\ub97c \ud574\uce60 \uc218 \uc788\ub294\uac00\ub85c \ubc14\ub010\ub2e4. \uc778\uc5b4\uacf5\uc8fc\ub294 \uadf8 \ud589\ub3d9\uc744 \uac70\ubd80\ud558\uace0 \ubc14\ub2e4\uc5d0 \ubab8\uc744 \ub9e1\uae34\ub2e4. \uc774 \uc120\ud0dd\uc774 \uc6d0\uc791\uc758 \ub9c8\uc9c0\ub9c9\uc744 \uc774\ud574\ud558\ub294 \uc911\uc2ec\uc774\ub2e4. \uc6d0\ud558\ub294 \uac83\uc744 \uc5bb\uc9c0 \ubabb\ud588\uc744 \ub54c \ub2e4\ub978 \uc0ac\ub78c\uc744 \ud30c\uad34\ud558\ub294 \uae38\uc744 \ud0dd\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc8fc\uc778\uacf5\uc758 \ud798\uc740 \uc131\uacf5\uc801\uc778 \uacb0\ud63c\ubcf4\ub2e4 \uc774 \uac70\ubd80\uc758 \ud589\ub3d9\uc5d0\uc11c \ub4dc\ub7ec\ub09c\ub2e4. \uc774\uc57c\uae30\ub294 \uac70\ud488\uc73c\ub85c \uc0ac\ub77c\uc9c0\ub294 \ubaa8\uc2b5\uc5d0\uc11c \uc644\uc804\ud788 \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc778\uc5b4\uacf5\uc8fc\ub294 \uacf5\uae30\uc758 \ub538\ub4e4\uacfc \ud568\uaed8\ud558\ub294 \uc874\uc7ac\uac00 \ub418\uace0 \uc120\ud55c \ud589\uc704\ub97c \ud1b5\ud574 \uc601\ud63c\uc744 \uc5bb\uc744 \uac00\ub2a5\uc131\uc744 \ub9de\uc774\ud55c\ub2e4. \uc655\uc790\uc758 \uc0ac\ub791 \ud558\ub098\ub9cc\uc774 \ubaa8\ub4e0 \uc18c\ub9dd\uc744 \uc774\ub8e8\ub294 \uc720\uc77c\ud55c \ubb38\uc73c\ub85c \ub0a8\uc9c0 \uc54a\ub294 \uac83\uc774\ub2e4. \uc774 \uacb0\ub9d0\uc744 \uc54c\uba74 \uc6d0\uc791\uc758 \uae38\uc774 \ub354 \ud48d\ubd80\ud574\uc9c4\ub2e4. \ub2e4\ub978 \uc138\uacc4\ub97c \ud5a5\ud55c \ub3d9\uacbd\uacfc \uc790\uae30 \ubaa9\uc18c\ub9ac\uc758 \uc0c1\uc2e4, \ud0c0\uc778\uc758 \uc0b6\uc744 \ub300\ud558\ub294 \uc120\ud0dd\uc774 \uc774\uc5b4\uc838 \uc788\uc5c8\ub2e4. \u300e\uc778\uc5b4\uacf5\uc8fc\u300f\ub294 \uc0ac\ub791\uc758 \ub300\uac00\ub9cc \ubb3b\ub294 \ub3d9\ud654\uac00 \uc544\ub2c8\ub77c \ubb34\uc5c7\uc744 \ubc14\ub77c\uba70 \uc5b4\ub5a4 \uc0ac\ub78c\uc774 \ub420 \uac83\uc778\uac00\uae4c\uc9c0 \ubb3b\ub294 \uc774\uc57c\uae30\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4."}, {"id": "little-women-four-sisters-different-futures", "title": "\u300e\uc791\uc740 \uc544\uc528\ub4e4\u300f \u2014 \ub124 \uc790\ub9e4\uc5d0\uac8c \uac19\uc740 \ubbf8\ub798\uac00 \ud544\uc694\ud588\uc744\uae4c", "summary": "\uc870\uc758 \uae00\uc4f0\uae30\uc640 \ub124 \uc790\ub9e4\uc758 \uac08\ub4f1\u00b7\ub3cc\ubd04\u00b7\uc120\ud0dd\uc744 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/little-women-four-sisters-different-futures/index.html", "image": "../media/little-women-four-sisters-different-futures.png", "alt": "\ucc45\uacfc \uc6d0\uace0\u00b7\ubc14\ub290\uc9c8\u00b7\ud53c\uc544\ub178\uac00 \uc788\ub294 \ubc29\uc5d0\uc11c \ud568\uaed8 \uc2dc\uac04\uc744 \ubcf4\ub0b4\ub294 \ub124 \uc790\ub9e4\uc758 \uc18c\uc124 \uc7a5\uba74 \uc0bd\ud654", "text": "\u300e\uc791\uc740 \uc544\uc528\ub4e4\u300f \u2014 \ub124 \uc790\ub9e4\uc5d0\uac8c \uac19\uc740 \ubbf8\ub798\uac00 \ud544\uc694\ud588\uc744\uae4c \uc9d1 \uc548\uc758 \uc791\uc740 \uc18c\ub3d9\uc774 \uac01\uc790\uc758 \uc0b6\uc73c\ub85c \uc790\ub77c\ub294 \uc774\uc57c\uae30 \uc870\uc758 \uae00\uc4f0\uae30\uc640 \ub124 \uc790\ub9e4\uc758 \uac08\ub4f1\u00b7\ub3cc\ubd04\u00b7\uc120\ud0dd\uc744 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \ub124 \uc790\ub9e4\ub294 \ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \uc120\ubb3c\uc744 \ub9c8\uc74c\uaecf \uc0b4 \ud615\ud3b8\uc774 \uc544\ub2c8\ub2e4. \uadf8\ub7f0\ub370 \uac01\uc790\uac00 \uc544\uc26c\uc6c0\uc744 \ud138\uc5b4\ub193\ub294 \ubc29\uc2dd\ubd80\ud130 \ub2e4\ub974\ub2e4. \ub204\uad70\uac00\ub294 \uc608\uc05c \uc637\uc744, \ub204\uad70\uac00\ub294 \ucc45\uacfc \uc74c\uc545\uc744 \ub5a0\uc62c\ub9b0\ub2e4. \u300e\uc791\uc740 \uc544\uc528\ub4e4\u300f\uc758 \uc7ac\ubbf8\ub294 \ud55c\uc9d1\uc5d0\uc11c \uc790\ub77c\ub3c4 \ub9c8\uc74c\uc18d\uc758 \ubbf8\ub798\ub294 \ub611\uac19\uc9c0 \uc54a\ub2e4\ub294 \ub370\uc11c \uc2dc\uc791\ud55c\ub2e4. \ub8e8\uc774\uc790 \uba54\uc774 \uc62c\ucef7\uc758 \uc18c\uc124\uc740 \ucc29\ud55c \uc790\ub9e4\ub4e4\uc774 \uc5b8\uc81c\ub098 \uc0ac\uc774\uc88b\uac8c \uc9c0\ub0b4\ub294 \uc774\uc57c\uae30\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uc9c8\ud22c\ud558\uace0 \ud654\ub0b4\uace0 \uc798\ubabb\uc744 \ub418\ub3cc\uc544\ubcf4\uba74\uc11c \uc11c\ub85c \ub2e4\ub978 \uc5b4\ub978\uc774 \ub418\uc5b4 \uac00\ub294 \uc774\uc57c\uae30\ub2e4. \uc5ec\uae30\uc11c\ub294 \ub450 \ubd80\ubd84\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c4 \uc791\ud488\uc758 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \ud568\uaed8 \uc18c\uac1c\ud55c\ub2e4. \ub9c8\uce58\uac00\uc758 \uc544\ubc84\uc9c0\ub294 \ub0a8\ubd81\uc804\uc7c1\uc5d0 \uad70\ubaa9\uc73c\ub85c \ub098\uac00 \uc788\ub2e4. \uc5b4\uba38\ub2c8\uc640 \ub124 \ub538\uc740 \ub109\ub109\ud558\uc9c0 \uc54a\uc740 \uc0b4\ub9bc\uc744 \uafb8\ub9b0\ub2e4. \uc804\uc7c1\uc758 \uc7a5\uba74\uc744 \uae38\uac8c \ubcf4\uc5ec \uc8fc\uc9c0 \uc54a\uc544\ub3c4, \uc544\ubc84\uc9c0\uc758 \ubd80\uc7ac\uc640 \ud3b8\uc9c0, \uac11\uc790\uae30 \ub0a0\uc544\uc628 \uc18c\uc2dd\uc774 \uc9d1 \uc548\uc758 \uacf5\uae30\ub97c \ubc14\uafbc\ub2e4. \ubc14\uae65\uc758 \ud070 \uc5ed\uc0ac\ub294 \uac70\uc2e4\uacfc \ubd80\uc5cc\uc5d0\uc11c\ub3c4 \ub290\uaef4\uc9c4\ub2e4. \uba54\uadf8\ub294 \uc544\ub984\ub2e4\uc6b4 \uc0dd\ud65c\uc744 \ub3d9\uacbd\ud558\uace0, \uc870\ub294 \uc774\uc57c\uae30\ub97c \uc4f0\uba70, \ubca0\uc2a4\ub294 \uc74c\uc545\uacfc \uc775\uc219\ud55c \uc9d1\uc744 \uc88b\uc544\ud558\uace0, \uc5d0\uc774\ubbf8\ub294 \ubbf8\uc220\uacfc \uc138\ub828\ub41c \uc138\uacc4\uc5d0 \ub9c8\uc74c\uc744 \ub454\ub2e4. \uc774\ub7f0 \ucc28\uc774\ub294 \ub2e8\uc21c\ud55c \uc131\uaca9\ud45c\uac00 \uc544\ub2c8\ub2e4. \uac19\uc740 \ub3c8\uacfc \uc2dc\uac04, \uac19\uc740 \uac00\uc871\uc758 \uad00\uc2ec\uc744 \ub098\ub204\uc5b4\uc57c \ud560 \ub54c \uc2e4\uc81c \uac08\ub4f1\uc744 \ub9cc\ub4e0\ub2e4. \ub204\uad6c\uc758 \uc18c\ub9dd\ubd80\ud130 \ub4e4\uc5b4\uc904 \uac83\uc778\uc9c0\uac00 \uc0dd\ud65c\uc758 \ubb38\uc81c\uac00 \ub41c\ub2e4. \uc870\ub294 \ud65c\ub2ec\ud558\uace0 \ub9d0\ub3c4 \ube60\ub974\uba70 \ud63c\uc790 \uc0c1\uc0c1\ud55c \uc138\uacc4\uc5d0 \uae4a\uc774 \ube60\uc838\ub4e0\ub2e4. \uae00\uc744 \uc4f0\ub294 \uc77c\uc740 \uc7a0\uae50\uc758 \ub180\uc774\ubcf4\ub2e4 \ub354 \uc911\uc694\ud558\ub2e4. \uadf8\ub7f0 \uc6d0\uace0\ub97c \uc5b4\ub9b0 \uc5d0\uc774\ubbf8\uac00 \ubd84\ud55c \ub9c8\uc74c\uc5d0 \ud0dc\uc6cc \ubc84\ub9b0\ub2e4. \uc870\uac00 \ud06c\uac8c \ud654\ub0b4\ub294 \uc774\uc720\ub294 \uc885\uc774\uac00 \uc544\uae4c\uc6cc\uc11c\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uadf8 \uc548\uc5d0\ub294 \ub2e4\uc2dc \ub9cc\ub4e4 \uc218 \uc788\uc744\uc9c0 \ubaa8\ub97c \uc2dc\uac04\uacfc \uafc8\uc774 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \ub4a4\uc774\uc5b4 \uc5bc\uc74c \uc704\uc5d0\uc11c \uc704\ud5d8\ud55c \uc77c\uc774 \ubc8c\uc5b4\uc9c0\uace0 \uc870\ub294 \uc790\uc2e0\uc758 \ubd84\ub178\ub3c4 \ub3cc\uc544\ubcf4\uac8c \ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc6d0\uace0\ub97c \ud0dc\uc6b4 \uc77c\uc774 \uac00\ubcbc\uc6b4 \uc7a5\ub09c\uc73c\ub85c \ubc14\ub00c\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc18c\uc124\uc740 \uac00\uc871\uc774\ub2c8\uae4c \uace7\ubc14\ub85c \ucc38\uc73c\ub77c\ub294 \ub9d0\ubcf4\ub2e4, \ud568\uaed8 \uc0b4\uc544\uac00\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc2e4\uc81c\ub85c \uc0c1\ucc98\ub97c \uc8fc\uace0 \uadf8 \ub4a4\ub97c \uac10\ub2f9\ud558\ub294 \ubaa8\uc2b5\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc0ac\ub791\ud558\ub294 \uc0ac\uc774\uc5d0\ub3c4 \uc0ac\uacfc\uc640 \uc2dc\uac04\uc774 \ud544\uc694\ud558\ub2e4. \uc774\uc6c3\uc758 \ub85c\ub9ac\uc640 \uadf8\uc758 \ud560\uc544\ubc84\uc9c0\uac00 \ub4f1\uc7a5\ud558\uba74\uc11c \uc790\ub9e4\ub4e4\uc758 \uc0dd\ud65c\uc740 \ub113\uc5b4\uc9c4\ub2e4. \ub85c\ub9ac\uc758 \uc9d1\uc5d0\ub294 \ub3c8\uacfc \ubb3c\uac74\uc774 \ub354 \ub9ce\uc9c0\ub9cc, \uadf8\uac83\ub9cc\uc73c\ub85c \uc678\ub85c\uc6c0\uae4c\uc9c0 \uc0ac\ub77c\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub9c8\uce58\uac00\uc758 \ub5a0\ub4e4\uc369\ud55c \uc0dd\ud65c\uacfc \ub85c\ub9ac\uc758 \uacf5\uac04\uc740 \uc11c\ub85c\uc5d0\uac8c \uc5c6\ub294 \uac83\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uad00\uacc4\ub294 \uc77c\ubc29\uc801\uc73c\ub85c \ubd80\uc720\ud55c \uc0ac\ub78c\uc774 \uac00\ub09c\ud55c \uc0ac\ub78c\uc744 \ub3d5\ub294 \ubc29\uc2dd\uc73c\ub85c\ub9cc \ud758\ub7ec\uac00\uc9c0 \uc54a\ub294\ub2e4. \ubca0\uc2a4\uac00 \uc74c\uc545\uc744 \ud1b5\ud574 \uc774\uc6c3\uacfc \uac00\uae4c\uc6cc\uc9c0\ub294 \uc7a5\uba74\ub3c4 \uadf8\ub7f0 \uc5f0\uacb0\uc774\ub2e4. \uc870\uc2ec\uc2a4\ub7fd\uace0 \uc9d1\uc744 \uc88b\uc544\ud558\ub294 \uc778\ubb3c\uc774 \ub0a8\ub4e4 \uc55e\uc5d0\uc11c \ud06c\uac8c \ud65c\uc57d\ud558\uc9c0 \uc54a\uc544\ub3c4, \uc8fc\ubcc0 \uc0ac\ub78c\uc758 \uc0b6\uc744 \ubc14\uafc0 \uc218 \uc788\ub2e4. \uc870\uc758 \ube60\ub978 \ub9d0\uacfc \ub300\ub2f4\ud55c \ud589\ub3d9 \uc606\uc5d0 \ubca0\uc2a4\uc758 \uc870\uc6a9\ud568\uc774 \ub530\ub85c \ub193\uc778\ub2e4. \uc791\uac00\ub294 \uadf8 \ucc28\uc774\ub97c \uac19\uc740 \uc7a3\ub300\ub85c \ud3c9\uac00\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc544\ubc84\uc9c0\uac00 \uc544\ud504\ub2e4\ub294 \uc18c\uc2dd\uc774 \uc624\uc790 \uac00\uc871\uc5d0\uac8c\ub294 \uc5ec\ud589\ube44\uac00 \ud544\uc694\ud574\uc9c4\ub2e4. \uc870\ub294 \uba38\ub9ac\uce74\ub77d\uc744 \uc798\ub77c \ud314\uc544 \ub3c8\uc744 \ubcf4\ud0e0\ub2e4. \uc529\uc529\ud558\uac8c \ud589\ub3d9\ud558\uc9c0\ub9cc \ub098\uc911\uc5d0\ub294 \uc790\uae30 \uba38\ub9ac\uce74\ub77d\uc744 \uc783\uc740 \uc2ac\ud514\ub3c4 \ub290\ub080\ub2e4. \ub0a8\uc744 \uc704\ud574 \uc88b\uc740 \uc77c\uc744 \ud588\ub2e4\uace0 \ud574\uc11c \uc790\uc2e0\uc758 \uc544\uc26c\uc6c0\uc774 \uae68\ub057\uc774 \uc5c6\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774\ub7f0 \uc791\uc740 \ud754\ub4e4\ub9bc\uc774 \uc778\ubb3c\uc744 \uc0b4\uc544 \uc788\uac8c \ub9cc\ub4e0\ub2e4. \uc870\ub97c \uc5b8\uc81c\ub098 \ub300\ub2f4\ud55c \uc0ac\ub78c\uc73c\ub85c\ub9cc \uae30\uc5b5\ud558\uba74 \uadf8 \uc7a5\uba74\uc758 \ubc18\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \ud55c \ubc88\uc758 \uc120\ud0dd \uc548\uc5d0\ub294 \uc790\ub791\uc2a4\ub7ec\uc6c0\uacfc \uc11c\uc6b4\ud568\uc774 \ud568\uaed8 \ub4e4\uc5b4\uac08 \uc218 \uc788\ub2e4. \u300e\uc791\uc740 \uc544\uc528\ub4e4\u300f\uc740 \ud070 \ubaa8\ud5d8 \ub300\uc2e0 \uadf8\ub7f0 \ub9c8\uc74c\uc758 \uacb9\uce68\uc744 \uc624\ub798 \ubc14\ub77c\ubcf8\ub2e4. \uc2dc\uac04\uc774 \ud750\ub974\uba70 \ub85c\ub9ac\ub294 \uc870\uc5d0\uac8c \ub9c8\uc74c\uc744 \uace0\ubc31\ud55c\ub2e4. \uc624\ub7ab\ub3d9\uc548 \ud568\uaed8 \uc9c0\ub0c8\uace0 \uc11c\ub85c\ub97c \uc798 \uc544\ub2c8\uae4c \ub2f9\uc5f0\ud788 \uc5f0\uc778\uc774 \ub420 \uac83\ucc98\ub7fc \ubcf4\uc778\ub2e4. \ud558\uc9c0\ub9cc \uc870\ub294 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc0ac\ub791\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc775\uc219\ud55c \ub450 \uc0ac\ub78c\uc774\ub2c8 \ubc18\ub4dc\uc2dc \uacb0\ud63c\ud574\uc57c \ud55c\ub2e4\ub294 \ub3c5\uc790\uc758 \uae30\ub300\ub3c4 \uc5ec\uae30\uc11c \uba48\ucd98\ub2e4. \uac70\uc808\uc774 \ub85c\ub9ac\ub97c \ub35c \uc18c\uc911\ud558\uac8c \uc5ec\uae34\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc6b0\uc815\uc758 \uce5c\ubc00\ud568\uacfc \ubd80\ubd80\ub85c \uc0b4\uc544\uac00\ub824\ub294 \ub9c8\uc74c\uc740 \ub2e4\ub97c \uc218 \uc788\ub2e4. \ub85c\ub9ac\uc758 \uc774\ud6c4 \uc0b6\uacfc \uc5d0\uc774\ubbf8\uc758 \uc120\ud0dd\ub3c4 \uc774\uc5b4\uc9c0\uc9c0\ub9cc, \uc870\uac00 \uacb0\uad6d \uc0dd\uac01\uc744 \ubc14\uafd4 \uadf8\uc5d0\uac8c \ub3cc\uc544\uac00\ub294 \uacb0\ub9d0\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub978 \uc778\ubb3c\uc758 \uc18c\ub9dd\uc744 \ub4e4\uc5b4\uc8fc\ub294 \uc77c\uacfc \uc790\uae30 \uc0b6\uc744 \uacb0\uc815\ud558\ub294 \uc77c \uc0ac\uc774\uc758 \uacbd\uacc4\uac00 \uc0dd\uae34\ub2e4. \ubca0\uc2a4\uc758 \ubcd1\uacfc \uc8fd\uc74c\uc740 \uac00\uc871\uc774 \ub178\ub825\ud558\uba74 \ubaa8\ub4e0 \uac83\uc744 \uc9c0\ud0ac \uc218 \uc788\ub2e4\ub294 \uae30\ub300\ub97c \ubb34\ub108\ub728\ub9b0\ub2e4. \ucc98\uc74c\uc758 \ud070 \ubcd1\uc744 \ub118\uae34 \ub4a4\uc5d0\ub3c4 \uac74\uac15\uc774 \uc628\uc804\ud788 \ub3cc\uc544\uc624\uc9c0 \uc54a\uace0, \uac00\uc871\uc740 \uc5b8\uc820\uac00 \ub9de\uc744 \uc774\ubcc4\uc744 \ud568\uaed8 \uacac\ub518\ub2e4. \ub2e4\ub978 \uc790\ub9e4\ub4e4\uc774 \ubc14\uae65\uc73c\ub85c \ubed7\uc5b4 \uac00\ub294 \ub3d9\uc548 \uc9d1\uc744 \uc911\uc2ec\uc73c\ub85c \uc0b4\ub358 \uc0ac\ub78c\uc758 \ube48\uc790\ub9ac\uac00 \ub354\uc6b1 \ud06c\uac8c \ub0a8\ub294\ub2e4. \uc774 \uc2dc\uac04\uc744 \uc9c0\ub098 \uc870\uc758 \uae00\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \ub3c5\uc790\ub97c \ub180\ub77c\uac8c \ud560 \uc18c\uc7ac\ub97c \ucc3e\ub358 \ub9c8\uc74c \uacc1\uc5d0 \uc790\uc2e0\uc774 \uc54c\uace0 \uc0ac\ub791\ud588\ub358 \uc0dd\ud65c\uc744 \uc801\ub294 \uc77c\uc774 \ub4e4\uc5b4\uc628\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc2ac\ud514\uc774 \uc791\uac00\uac00 \ub418\uae30 \uc704\ud574 \ubc18\ub4dc\uc2dc \ud544\uc694\ud55c \uac12\uc774\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc18c\uc124\uc774 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \uc774\ubbf8 \uacaa\uc740 \uc0c1\uc2e4\uc744 \ub9d0\ub85c \uc62e\uae30\uba70 \ub2e4\uc2dc \uc0ac\ub78c\uacfc \uc5f0\uacb0\ub418\ub294 \uacfc\uc815\uc774\ub2e4. \ud6c4\ubc18\ubd80\uc5d0\uc11c \uc870\ub294 \ubca0\uc5b4 \uad50\uc218\uc640 \uad00\uacc4\ub97c \ub9fa\uace0, \ubb3c\ub824\ubc1b\uc740 \ud50c\ub7fc\ud544\ub4dc\ub97c \ud559\uad50\ub85c \ubc14\uafb8\ub824 \ud55c\ub2e4. \uac74\ubb3c\uc744 \ud314\uc544 \ub3c8\uc73c\ub85c \ub9cc\ub4e4 \uc218\ub3c4 \uc788\uc9c0\ub9cc \ub2e4\ub978 \uc120\ud0dd\uc744 \ud55c\ub2e4. \uc790\uc2e0\uc758 \uc9d1\uc774\uc5c8\ub358 \uc7a5\uc18c\ub97c \ub2e4\uc74c \uc138\ub300\uac00 \uc0b4\uc544\uac08 \uacf5\uac04\uc73c\ub85c \ub113\ud788\ub294 \uac83\uc774\ub2e4. \uacb0\ub9d0\uc758 \uc9d1\uc740 \ucd9c\ubc1c\uc810\uc758 \uc9d1\uacfc \ub2ee\uc558\uc73c\uba74\uc11c\ub3c4 \ub2e4\ub974\ub2e4. \uc624\ub298\uc758 \ub3c5\uc790\ub294 \uc870\uc758 \uacb0\ud63c\uacfc \uc791\uac00\ub85c\uc11c\uc758 \uae38\uc5d0 \ub300\ud574 \uc11c\ub85c \ub2e4\ub978 \uc544\uc26c\uc6c0\uc744 \ub290\ub084 \uc218 \uc788\ub2e4. \uc791\ud488\uc758 \uc2dc\ub300\uc801 \uae30\ub300\uc640 \uc790\uc2e0\uc774 \ubc14\ub77c\ub294 \ubbf8\ub798\ub97c \ub098\ub780\ud788 \ub193\uace0 \uc77d\uc5b4\ub3c4 \uc88b\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ub124 \uc790\ub9e4\uc758 \uc0b6\uc744 \ud55c \uac00\uc9c0 \uc131\uacf5\ub2f4\uc73c\ub85c \uc815\ub9ac\ud558\uc9c0 \uc54a\ub294 \uc77c\uc774\ub2e4. \uc608\uc220, \uac00\uc871, \ub3cc\ubd04, \uad50\uc721\uc740 \uac01 \uc778\ubb3c\uc5d0\uac8c \ub2e4\ub978 \ube44\uc911\uc744 \uac00\uc9c4\ub2e4. \uc81c\ubaa9\uc758 \uc791\uc740 \uc544\uc528\ub4e4\uc740 \ucc98\uc74c\ubd80\ud130 \uc644\uc131\ub41c \ubaa8\ubc94\uc0dd\uc774 \uc544\ub2c8\ub2e4. \uc6d0\ud558\ub294 \uac83\uc744 \ub9d0\ud558\uace0 \uc2e4\uc218\ud558\uace0 \ub204\uad70\uac00\ub97c \uc783\uc740 \ub4a4\uc5d0\ub3c4 \uc0b4\uc544\uac08 \ubc29\uc2dd\uc744 \uc870\uae08\uc529 \ubc14\uafbc\ub2e4. \uadf8\ub798\uc11c \uc774 \uc18c\uc124\uc758 \uac70\uc2e4\uc740 \uc791\uc740 \uacf5\uac04\uc774\uc9c0\ub9cc \uc881\uc740 \uc138\uacc4\ub294 \uc544\ub2c8\ub2e4. \ud55c \uc2dd\ud0c1 \ub458\ub808\uc5d0\ub3c4 \uc5ec\ub7ec \ubbf8\ub798\uac00 \uc549\uc544 \uc788\ub2e4. \ub2e4 \uc77d\uace0 \ub098\uba74 \ub204\uac00 \uac00\uc7a5 \uc88b\uc740 \uc120\ud0dd\uc744 \ud588\ub294\uc9c0 \uc21c\uc704\ub97c \ub9e4\uae30\uae30\ubcf4\ub2e4, \uc5b4\ub290 \uc21c\uac04\uc758 \ub204\uad6c\uc5d0\uac8c \ub9c8\uc74c\uc774 \uac14\ub294\uc9c0 \ubb3b\uac8c \ub41c\ub2e4. \uc6d0\uace0\ub97c \uc783\uc740 \uc870\uc77c \uc218\ub3c4, \ub2e4\ub978 \uc0dd\ud65c\uc744 \uafc8\uafb8\ub294 \uba54\uadf8\uc77c \uc218\ub3c4 \uc788\ub2e4. \uc11c\ub85c \ub2e4\ub974\uac8c \uc0b4\uba74\uc11c\ub3c4 \uad00\uacc4\ub97c \uc774\uc5b4 \uac00\ub294 \uc77c. \uadf8 \uc624\ub798\ub41c \ubb38\uc81c\uac00 \ub124 \uc790\ub9e4\uc758 \uc18c\ub3d9\uc744 \uc9c0\uae08\ub3c4 \uac00\uae5d\uac8c \ub9cc\ub4e0\ub2e4."}, {"id": "macbeth-prophecy-and-borrowed-crown", "title": "\ub9e5\ubca0\uc2a4 \u2014 \uc608\uc5b8\uc740 \ub204\uad6c\uc758 \uc190\uc73c\ub85c \ud604\uc2e4\uc774 \ub418\uc5c8\uc744\uae4c", "summary": "\uc608\uc5b8\uacfc \uc0b4\uc778, \uc5f0\ud68c\uc758 \uc720\ub839\uacfc \ub9c8\uc9c0\ub9c9 \uc804\ud22c\ub97c \ub530\ub77c \ubbf8\ub798\ub97c \ubbff\ub294 \ubc29\uc2dd\uacfc \ucc45\uc784\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/macbeth-prophecy-and-borrowed-crown/index.html", "image": "../media/macbeth-prophecy-and-borrowed-crown.png", "alt": "\uc131\uc758 \ubc29\uc5d0\uc11c \uc655\uad00\uc744 \uc0ac\uc774\uc5d0 \ub454 \ub9e5\ubca0\uc2a4 \ubd80\ubd80\ub97c \uc5f0\uc0c1\ud558\ub294 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ub9e5\ubca0\uc2a4 \u2014 \uc608\uc5b8\uc740 \ub204\uad6c\uc758 \uc190\uc73c\ub85c \ud604\uc2e4\uc774 \ub418\uc5c8\uc744\uae4c \uc170\uc775\uc2a4\ud53c\uc5b4\uc758 \ube44\uadf9\uc5d0\uc11c \uc608\uc5b8\u00b7\ubd88\uc548\u00b7\uad8c\ub825\u00b7\uc120\ud0dd\uc744 \ub530\ub77c\uac00\uae30 \uc608\uc5b8\uacfc \uc0b4\uc778, \uc5f0\ud68c\uc758 \uc720\ub839\uacfc \ub9c8\uc9c0\ub9c9 \uc804\ud22c\ub97c \ub530\ub77c \ubbf8\ub798\ub97c \ubbff\ub294 \ubc29\uc2dd\uacfc \ucc45\uc784\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \uc655\uc774 \ub420 \uac83\uc774\ub77c\ub294 \ub9d0\uc744 \ub4e4\uc740 \uc0ac\ub78c\uc774 \uc788\ub2e4. \uadf8\ub294 \uadf8 \ub9d0\uc744 \uae30\ub2e4\ub9ac\ub294 \ub300\uc2e0 \uc9c1\uc811 \uc2e4\ud604\ud558\ub824 \ud55c\ub2e4. \uc170\uc775\uc2a4\ud53c\uc5b4\uc758 \u300e\ub9e5\ubca0\uc2a4\u300f\ub294 \uc608\uc5b8\uc774 \ub9de\ub294\uc9c0 \ud655\uc778\ud558\ub294 \uc774\uc57c\uae30\uc774\uba74\uc11c, \ubbf8\ub798\uc5d0 \uad00\ud55c \ub9d0\uc744 \ub4e4\uc740 \uc0ac\ub78c\uc774 \ud604\uc7ac\uc758 \ucc45\uc784\uc744 \uc5b4\ub5bb\uac8c \ubc14\uafb8\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \ube44\uadf9\uc774\ub2e4. \uc544\ub798\uc5d0\ub294 \uc8fc\uc694 \uc0ac\uac74\uacfc \uacb0\ub9d0\uc774 \ud3ec\ud568\ub41c\ub2e4. \uc2a4\ucf54\ud2c0\ub79c\ub4dc\uc758 \uc7a5\uad70 \ub9e5\ubca0\uc2a4\uc640 \ubc45\ucf54\ub294 \uc804\ud22c \ub4a4 \uae30\uc774\ud55c \uc874\uc7ac\ub4e4\uc744 \ub9cc\ub09c\ub2e4. \ub9e5\ubca0\uc2a4\uc5d0\uac8c\ub294 \uc0c8\ub85c\uc6b4 \uc9c0\uc704\uc640 \uc655\uc704\uac00, \ubc45\ucf54\uc5d0\uac8c\ub294 \ud6c4\uc190\uc774 \uc655\uc774 \ub420 \ubbf8\ub798\uac00 \uc81c\uc2dc\ub41c\ub2e4. \ub450 \uc0ac\ub78c\uc774 \ub4e3\ub294 \uc57d\uc18d\uc740 \uc11c\ub85c \ub2e4\ub974\ub2e4. \ubbf8\ub798\uc758 \uc601\uad11\uc740 \ucc98\uc74c\ubd80\ud130 \uc6b0\uc815 \uc548\uc5d0 \uacbd\uc7c1\uc758 \uac00\ub2a5\uc131\uc744 \uc2ec\ub294\ub2e4. \uc608\uace0\ub41c \uc9c0\uc704 \ud558\ub098\uac00 \uc2e4\uc81c\ub85c \uc8fc\uc5b4\uc9c0\uc790 \ub098\uba38\uc9c0 \ub9d0\ub3c4 \ubbff\uc744 \ub9cc\ud558\uac8c \ub290\uaef4\uc9c4\ub2e4. \uadf8\ub7ec\ub098 \uc77c\ubd80\uac00 \ub9de\uc558\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ubaa8\ub4e0 \ud589\ub3d9\uc744 \uc815\ub2f9\ud558\uac8c \ub9cc\ub4e4\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub9e5\ubca0\uc2a4\ub294 \uc544\uc9c1 \uc77c\uc5b4\ub098\uc9c0 \uc54a\uc740 \uc77c\uc744 \uc0c1\uc0c1\ud558\uba74\uc11c, \uc9c0\uae08 \uc790\uc2e0\uc774 \ud574\uc57c \ud560 \uc77c\uacfc \ud574\uc11c\ub294 \uc548 \ub420 \uc77c\uc758 \uacbd\uacc4\ub97c \ud754\ub4e4\uae30 \uc2dc\uc791\ud55c\ub2e4. \ub358\ucee8 \uc655\uc774 \ub9e5\ubca0\uc2a4\uc758 \uc131\uc5d0 \uc628\ub2e4. \ub9e5\ubca0\uc2a4\ub294 \uc655\uc758 \uc2e0\ud558\uc774\uba74\uc11c \uadf8\ub97c \ubcf4\ud638\ud574\uc57c \ud560 \uc8fc\uc778\uc774\ub2e4. \uc655\uc744 \ud574\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc774\uc720\ub97c \uc2a4\uc2a4\ub85c \uc54c\uace0 \uc788\uc9c0\ub9cc, \uc655\uc704\ub97c \uc5bb\uace0 \uc2f6\uc740 \ub9c8\uc74c\ub3c4 \ubc84\ub9ac\uc9c0 \ubabb\ud55c\ub2e4. \uc791\ud488\uc740 \ucc98\uc74c\ubd80\ud130 \uc591\uc2ec\uc774 \uc5c6\ub294 \uc545\uc778\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ub300\uc2e0, \uc54c\uba74\uc11c\ub3c4 \uc120\ud0dd\ud558\ub294 \uc0ac\ub78c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub9e5\ubca0\uc2a4 \ubd80\uc778\uc740 \ub9dd\uc124\uc774\ub294 \ub0a8\ud3b8\uc744 \ubc00\uc5b4\ubd99\uc778\ub2e4. \ubd80\ubd80\uc758 \ub300\ud654\uc5d0\uc11c\ub294 \uc6a9\uae30\uc640 \ub0a8\uc790\ub2e4\uc6c0\uc774\ub77c\ub294 \ub9d0\uc774 \ub3c4\ub355\uc801\uc778 \uc8fc\uc800\ud568\uc744 \ub204\ub974\ub294 \ub370 \uc0ac\uc6a9\ub41c\ub2e4. \uacb0\uad6d \ub358\ucee8\uc740 \uc8fd\uace0, \ub2ec\uc544\ub09c \uc655\uc790\ub4e4\uc5d0\uac8c \uc758\uc2ec\uc774 \ud5a5\ud558\ub294 \ud2c8\uc5d0 \ub9e5\ubca0\uc2a4\ub294 \uc655\uc774 \ub41c\ub2e4. \uc608\uc5b8\uc740 \uc800\uc808\ub85c \uc131\ucde8\ub41c \uac83\uc774 \uc544\ub2c8\ub2e4. \uc655\uad00\uc744 \uc5bb\uc5c8\ub2e4\uace0 \ubd88\uc548\uc774 \ub05d\ub098\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubc45\ucf54\uc758 \ud6c4\uc190\uc774 \uc655\uc774 \ub41c\ub2e4\ub294 \ub9d0\uc774 \ub0a8\uc544 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ub9e5\ubca0\uc2a4\ub294 \uc790\uae30\uac00 \uc5bb\uc740 \uc655\uc704\uac00 \ub2e4\ub978 \uac00\ubb38\uc758 \ubbf8\ub798\ub97c \uc900\ube44\ud558\ub294 \ub370 \uadf8\uce60\uae4c \ub450\ub824\uc6cc\ud55c\ub2e4. \uc131\ucde8\ub294 \ub9cc\uc871\ubcf4\ub2e4 \uc9c0\ucf1c\uc57c \ud55c\ub2e4\ub294 \uac15\ubc15\uc73c\ub85c \uc774\uc5b4\uc9c4\ub2e4. \uadf8\ub294 \ubc45\ucf54\ub97c \uc81c\uac70\ud558\ub824 \ud558\uace0, \ubc45\ucf54\ub294 \uc8fd\uc9c0\ub9cc \uc544\ub4e4 \ud50c\ub9ac\uc5b8\uc2a4\ub294 \ub3c4\ub9dd\uce5c\ub2e4. \uc5c6\uc560\ub824\ub358 \uac00\ub2a5\uc131\uc740 \ub0a8\ub294\ub2e4. \uc5f0\ud68c\uc5d0\uc11c \ub9e5\ubca0\uc2a4\uac00 \ubc45\ucf54\uc758 \uc720\ub839\uc744 \ubcf4\ub294 \uc7a5\uba74\uc740 \uc655\uc758 \uacf5\uc801\uc778 \uc5bc\uad74\uc744 \ubb34\ub108\ub728\ub9b0\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ubcf4\uc774\uc9c0 \uc54a\ub294 \uacf5\ud3ec\uac00 \ubaa8\ub450\uac00 \ubcf4\ub294 \uc790\ub9ac\uc5d0\uc11c \uadf8\uc758 \ubab8\uc744 \uc6c0\uc9c1\uc778\ub2e4. \uc5f0\ud68c\uc758 \uc790\ub9ac\ub294 \uc655\uc774 \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uc548\uc815\ub41c \uc9c8\uc11c\ub97c \ubcf4\uc5ec \uc8fc\uc5b4\uc57c \ud558\ub294 \uacf3\uc774\ub2e4. \uadf8\ub798\uc11c \uc720\ub839\uc758 \ucd9c\ud604\uc740 \ub9e5\ubca0\uc2a4 \ud63c\uc790 \ub180\ub77c\ub294 \uc0ac\uac74\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \ub204\uad6c\ub3c4 \uc774\ud574\ud560 \uc218 \uc5c6\ub294 \uc655\uc758 \ud589\ub3d9\uc744 \uc0ac\ub78c\ub4e4\uc774 \uc9c0\ucf1c\ubcf8\ub2e4. \uc0ac\uc801\uc778 \uc8c4\ucc45\uac10\uc774 \uacf5\uc801\uc778 \ud1b5\uce58 \ub2a5\ub825\uc758 \ubb38\uc81c\ub85c \ub4dc\ub7ec\ub098\ub294 \uc21c\uac04\uc774\ub2e4. \ubb34\ub300\uc5d0\uc11c \uc720\ub839\uc744 \uc5b4\ub5a4 \ubaa8\uc2b5\uc73c\ub85c \ubcf4\uc5ec \uc904\uc9c0\ub294 \uacf5\uc5f0\ub9c8\ub2e4 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uad00\uac1d\uacfc \ub4f1\uc7a5\uc778\ubb3c\uc774 \uac19\uc740 \uac83\uc744 \ubcf4\uace0 \uac19\uc740 \uc815\ubcf4\ub97c \uac16\ub294 \uc0c1\ud669\uc774 \uc544\ub2c8\ub77c\ub294 \uc810\uc774\ub2e4. \ub3c5\uc790\ub294 \ub9e5\ubca0\uc2a4\uc758 \uacf5\ud3ec\ub97c \ub530\ub77c\uac00\uba74\uc11c, \uadf8\ub97c \ubc14\ub77c\ubcf4\ub294 \uc0ac\ub78c\ub4e4\uc758 \ub2f9\ud639\uac10\ub3c4 \ud568\uaed8 \uc0c1\uc0c1\ud560 \uc218 \uc788\ub2e4. \ub9e5\ubca0\uc2a4\ub294 \ub2e4\uc2dc \ucd08\uc790\uc5f0\uc801\uc778 \ubaa9\uc18c\ub9ac\ub97c \ucc3e\ub294\ub2e4. \uc5ec\uc790\uac00 \ub0b3\uc740 \uc790\uc5d0\uac8c \ud328\ud558\uc9c0 \uc54a\uc73c\uba70 \ubc84\ub118 \uc232\uc774 \ub358\uc2dc\ub124\uc778\uc73c\ub85c \uc624\uae30 \uc804\uc5d0\ub294 \ubb34\ub108\uc9c0\uc9c0 \uc54a\ub294\ub2e4\ub294 \ub9d0\uc740 \ubd88\uac00\ub2a5\ud55c \uc870\uac74\ucc98\ub7fc \ub4e4\ub9b0\ub2e4. \uadf8\ub294 \uc790\uc2e0\uc5d0\uac8c \uc720\ub9ac\ud55c \ud574\uc11d\uc744 \uc120\ud0dd\ud574 \uc548\uc804\ud558\ub2e4\uace0 \ubbff\ub294\ub2e4. \ud558\uc9c0\ub9cc \ub9d0\uc758 \ubc94\uc704\uc640 \ub4e3\ub294 \uc0ac\ub78c\uc774 \uc774\ud574\ud55c \ubc94\uc704\ub294 \uac19\uc9c0 \uc54a\ub2e4. \uc791\ud488\uc758 \uae34\uc7a5\uc740 \uc608\uc5b8\uc774 \uac70\uc9d3\uc774\uc5b4\uc11c\ub9cc \uc0dd\uae30\uc9c0 \uc54a\ub294\ub2e4. \uc0ac\uc2e4\uc77c \uc218 \uc788\ub294 \ub9d0\ub3c4 \uc77c\ubd80\ub9cc \ub4e3\uac70\ub098 \ub73b\uc744 \uc131\uae09\ud788 \ud655\uc815\ud558\uba74 \uc704\ud5d8\ud574\uc9c4\ub2e4. \ub9e5\ubca0\uc2a4\ub294 \uacbd\uace0\ub97c \ub354 \uc870\uc2ec\ud558\ub77c\ub294 \uc694\uad6c\ubcf4\ub2e4 \ub450\ub824\uc6cc\ud560 \ud544\uc694 \uc5c6\ub2e4\ub294 \ubcf4\uc99d\uc73c\ub85c \ubc1b\uc544\ub4e4\uc778\ub2e4. \ub9e5\ubca0\uc2a4\uc758 \uad8c\ub825\uc740 \uc8fc\ubcc0 \uc0ac\ub78c\uc758 \uc0b6\uc744 \ud30c\uad34\ud55c\ub2e4. \ub9e5\ub354\ud504\uc758 \uac00\uc871\uc774 \ud76c\uc0dd\ub418\ub294 \uc0ac\uac74\uc740 \uc655 \uac1c\uc778\uc758 \ubd88\uc548\uc774 \ub2e4\ub978 \uc9d1\uc758 \ube44\uadf9\uc73c\ub85c \uc62e\uaca8 \uac00\ub294 \ubaa8\uc2b5\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc655\uc704 \ub2e4\ud23c\uc774\ub77c\ub294 \ud070 \ub9d0 \uc544\ub798 \uad6c\uccb4\uc801\uc778 \uac00\uc871\uacfc \uc77c\uc0c1\uc758 \uc190\uc2e4\uc774 \ub193\uc778\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ud568\uaed8 \ud589\ub3d9\ud588\ub358 \ubd80\ubd80\ub3c4 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uacf5\ud3ec\ub97c \uacac\ub514\uc9c0 \ubabb\ud55c\ub2e4. \ub9e5\ubca0\uc2a4 \ubd80\uc778\uc740 \uc7a0\ub4e0 \uc0c1\ud0dc\uc5d0\uc11c \uc190\uc744 \uc53b\ub294 \ub4ef\ud55c \ubab8\uc9d3\uacfc \ub9d0\uc744 \ub418\ud480\uc774\ud55c\ub2e4. \uc9c0\uc6cc\uc84c\ub2e4\uace0 \uc0dd\uac01\ud55c \ud754\uc801\uc740 \ub9c8\uc74c\uc5d0\uc11c \uc0ac\ub77c\uc9c0\uc9c0 \uc54a\uc558\ub2e4. \uadf8\ub140\uc758 \uc8fd\uc74c \ub4a4 \ub9e5\ubca0\uc2a4\uc758 \ub9d0\uc5d0\uc11c\ub294 \uc0b6\uc758 \uc758\ubbf8 \uc790\uccb4\uac00 \ud754\ub4e4\ub9b0\ub2e4. \ub9e5\ubca0\uc2a4\uc5d0\uac8c \ub9de\uc11c\ub294 \uad70\ub300\ub294 \ub098\ubb47\uac00\uc9c0\ub97c \ub4e4\uace0 \uc774\ub3d9\ud55c\ub2e4. \uc131\uc5d0\uc11c \ubcf4\uba74 \uc232\uc774 \ub2e4\uac00\uc624\ub294 \uac83\ucc98\ub7fc \ubcf4\uc778\ub2e4. \ubd88\uac00\ub2a5\ud558\ub2e4\uace0 \ubbff\uc5c8\ub358 \uc870\uac74\uc774 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ud604\uc2e4\uc774 \ub41c\ub2e4. \uc232 \uc804\uccb4\uac00 \ubfcc\ub9ac\uc9f8 \uac78\uc5b4\uc640\uc57c \ud55c\ub2e4\uace0 \uc0dd\uac01\ud55c \uac83\uc740 \ub9e5\ubca0\uc2a4\uc758 \ud574\uc11d\uc774\uc5c8\ub2e4. \ub9c8\uc9c0\ub9c9 \ub300\uacb0\uc5d0\uc11c \ub9e5\ub354\ud504\ub294 \uc790\uc2e0\uc774 \ud1b5\uc0c1\uc801\uc778 \ucd9c\uc0dd\uacfc \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uc5b4\uba38\ub2c8\uc758 \ubab8\uc5d0\uc11c \ub098\uc654\ub2e4\uace0 \ubc1d\ud78c\ub2e4. \ub9e5\ubca0\uc2a4\uac00 \uc758\uc9c0\ud55c \ub610 \ud558\ub098\uc758 \ud655\uc2e0\uc774 \uae68\uc9c4\ub2e4. \uadf8\ub294 \ud328\ud558\uace0 \ub358\ucee8\uc758 \uc544\ub4e4 \ub9ec\ucef4\uc774 \uc655\uc704\ub97c \uc787\ub294\ub2e4. \uc608\uc5b8\uc758 \uc218\uc218\uaed8\ub07c\uac00 \ud480\ub824\ub3c4 \uc774\ubbf8 \uc783\uc740 \uc0dd\uba85\uc740 \ub3cc\uc544\uc624\uc9c0 \uc54a\ub294\ub2e4. \ub9c8\ub140\ub4e4\uc774 \ubaa8\ub4e0 \ucc45\uc784\uc744 \ub300\uc2e0 \uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub9e5\ubca0\uc2a4\ub294 \ub9d0\uc744 \ub4e4\uc740 \ub4a4 \ud310\ub2e8\ud558\uace0 \uacc4\ud68d\ud558\uace0 \uba85\ub839\ud55c\ub2e4. \ubbf8\ub798\uac00 \uc815\ud574\uc838 \uc788\ub2e4\uace0 \ubbff\ub294 \ud0dc\ub3c4\uac00 \uc624\ud788\ub824 \uc9c0\uae08\uc758 \ud3ed\ub825\uc744 \uc120\ud0dd\ud558\uac8c \ub9cc\ub4e4\uc5c8\ub2e4. \uc6b4\uba85\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\uac00 \ud589\ub3d9\uc758 \ucc45\uc784\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\ub85c \uc774\uc5b4\uc9c0\ub294 \uc774\uc720\ub2e4. \u300e\ub9e5\ubca0\uc2a4\u300f\ub97c \ub2e4\uc2dc \uc77d\uc744 \ub54c\uc5d0\ub294 \ub204\uac00 \uc608\uc5b8\ud588\ub294\uc9c0\ub9cc\ud07c \ub204\uac00 \uc5b4\ub5bb\uac8c \ud574\uc11d\ud588\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc655\uad00\uc740 \ubaa9\ud45c\ub97c \uc774\ub8e8\uc5c8\ub2e4\ub294 \uc99d\uac70\uc774\uc9c0\ub9cc \uc548\uc804\uc744 \uc8fc\uc9c0 \ubabb\ud588\ub2e4. \uc5bb\uc73c\ub824\ub294 \uac83\uacfc \uc5bb\uc740 \ub4a4\uc758 \uc0b6\uc744 \uad6c\ubd84\ud558\uc9c0 \ubabb\ud55c \uc0ac\ub78c\uc758 \ube44\uadf9\uc774, \uc9e7\uace0 \ube60\ub978 \uc7a5\uba74\ub4e4 \uc18d\uc5d0\uc11c \uc624\ub798 \ub0a8\ub294\ub2e4."}, {"id": "madame-bovary-desire-and-credit", "title": "\ubcf4\ubc14\ub9ac \ubd80\uc778 \u2014 \uafc8\uafb8\ub358 \uc0b6\uc740 \uc65c \ube5a\uc774 \ub418\uc5c8\uc744\uae4c", "summary": "\uc5e0\ub9c8\uc758 \uc0ac\ub791\uacfc \uc18c\ube44, \ucc44\ubb34\uc640 \uac00\uc871\uc758 \uacb0\ub9d0\uc744 \ub530\ub77c \uafc8\uacfc \uc0dd\ud65c\uc758 \uac70\ub9ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/madame-bovary-desire-and-credit/index.html", "image": "../media/madame-bovary-desire-and-credit.png", "alt": "\ucc45\uacfc \uc11c\ub958\uac00 \ub193\uc778 \uc2dd\ud0c1 \uacc1\uc5d0\uc11c \ub9c8\uc744\uc744 \ubc14\ub77c\ubcf4\ub294 19\uc138\uae30 \ud504\ub791\uc2a4 \uc5ec\uc131 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ubcf4\ubc14\ub9ac \ubd80\uc778 \u2014 \uafc8\uafb8\ub358 \uc0b6\uc740 \uc65c \ube5a\uc774 \ub418\uc5c8\uc744\uae4c \ud50c\ub85c\ubca0\ub974\uc758 \uc778\ubb3c \uad00\uacc4\uc640 \uc2e0\uc6a9 \uac70\ub798\uac00 \uc5ee\ub294 \uc9c0\ubc29 \uc0dd\ud65c\uc758 \ud30c\uad6d \uc5e0\ub9c8\uc758 \uc0ac\ub791\uacfc \uc18c\ube44, \ucc44\ubb34\uc640 \uac00\uc871\uc758 \uacb0\ub9d0\uc744 \ub530\ub77c \uafc8\uacfc \uc0dd\ud65c\uc758 \uac70\ub9ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \uc5e0\ub9c8 \ubcf4\ubc14\ub9ac\ub294 \ud604\uc7ac\uc758 \uc0dd\ud65c\uc774 \uc790\uc2e0\uc774 \uae30\ub300\ud55c \uc0b6\uacfc \ub108\ubb34 \ub2e4\ub974\ub2e4\uace0 \ub290\ub080\ub2e4. \ub354 \uac15\ub82c\ud55c \uc0ac\ub791\uacfc \uc6b0\uc544\ud55c \uc0dd\ud65c, \ub2e4\ub978 \uacf3\uc5d0 \uc788\ub294 \ud589\ubcf5\uc744 \uc0c1\uc0c1\ud55c\ub2e4. \uadc0\uc2a4\ud0c0\ube0c \ud50c\ub85c\ubca0\ub974\uc758 \u300e\ubcf4\ubc14\ub9ac \ubd80\uc778\u300f\uc740 \uadf8 \uae30\ub300\uac00 \uc791\uc740 \uc9c0\ubc29 \ub3c4\uc2dc\uc758 \uc77c\uc0c1\uacfc \ubd80\ub52a\uce58\uba70 \ud30c\uad6d\uc73c\ub85c \uac00\ub294 \uacfc\uc815\uc744 \uadf8\ub9b0 \uc18c\uc124\uc774\ub2e4. \ubd88\ub95c\uc774\ub77c\ub294 \ud55c \ub2e8\uc5b4\ub85c \uc18c\uac1c\ud558\uae30\uc5d0\ub294 \uc791\ud488\uc774 \uc0b4\ud53c\ub294 \ubc94\uc704\uac00 \ub113\ub2e4. \uc77d\uc740 \ucc45\uacfc \ubcf4\uace0 \uc2f6\uc740 \ud48d\uacbd, \ubb3c\uac74\uc744 \uc0ac\ub294 \ubc29\uc2dd\uacfc \uc678\uc0c1 \uac70\ub798\uac00 \uac10\uc815\uc5d0 \uc5f0\uacb0\ub41c\ub2e4. \uc544\ub798\uc5d0\ub294 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc774 \ud3ec\ud568\ub41c\ub2e4. \uc5e0\ub9c8\uc758 \uc120\ud0dd\uacfc \uadf8 \uc120\ud0dd\uc744 \ub458\ub7ec\uc2fc \ud658\uacbd\uc744 \ud568\uaed8 \uc77d\uc5b4 \ubcf4\uc790. \uc0e4\ub97c \ubcf4\ubc14\ub9ac\uc640 \uacb0\ud63c\ud55c \uc5e0\ub9c8\ub294 \uc0c8\ub85c\uc6b4 \uc0b6\uc744 \ubc14\ub77c\uc9c0\ub9cc \uc77c\uc0c1\uc740 \uae30\ub300\ub9cc\ud07c \ud654\ub824\ud558\uc9c0 \uc54a\ub2e4. \uc0e4\ub97c\uc740 \uc544\ub0b4\ub97c \uc0ac\ub791\ud574\ub3c4 \uadf8\ub140\uac00 \uc6d0\ud558\ub294 \uc885\ub958\uc758 \uac15\ub82c\ud55c \uac10\uc815\uc744 \ucda9\ubd84\ud788 \uc774\ud574\ud558\uc9c0 \ubabb\ud55c\ub2e4. \ud55c \uc0ac\ub78c\uc774 \ud3c9\uc628\ud558\ub2e4\uace0 \ub290\ub07c\ub294 \uc0dd\ud65c\uc744 \ub2e4\ub978 \uc0ac\ub78c\uc740 \uacac\ub514\uae30 \uc5b4\ub824\uc6b4 \ubc18\ubcf5\uc73c\ub85c \uacbd\ud5d8\ud55c\ub2e4. \uc18c\uc124\uc740 \uc774 \ucc28\uc774\ub97c \ucc98\uc74c\ubd80\ud130 \ud55c\ucabd\uc758 \uc798\ubabb\ub9cc\uc73c\ub85c \uc815\ub9ac\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub2e4\uc815\ud568\uc774 \uc788\ub2e4\uace0 \uc0c1\ub300\ub97c \uc774\ud574\ud55c \uac83\uc740 \uc544\ub2c8\uace0, \ub2f5\ub2f5\ud568\uc744 \ub290\ub080\ub2e4\uace0 \uc774\ud6c4\uc758 \ubaa8\ub4e0 \uc120\ud0dd\uc774 \uc815\ub2f9\ud574\uc9c0\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \ub3c5\uc790\ub294 \ub450 \uc0ac\ub78c \uc0ac\uc774\uc758 \uac70\ub9ac\ub97c \ubcf4\uba74\uc11c \uc5b4\ub290 \ucabd\uc758 \ub9d0\uc5d0\ub3c4 \uc644\uc804\ud788 \uae30\ub300\uae30 \uc5b4\ub835\ub2e4. \uc5e0\ub9c8\uc5d0\uac8c \ub0ad\ub9cc\uc801\uc778 \ub3c5\uc11c\uc640 \ud654\ub824\ud55c \ubb34\ub3c4\ud68c\uc758 \uacbd\ud5d8\uc740 \ub2e4\ub978 \uc0b6\uc744 \uc0c1\uc0c1\ud558\ub294 \uc7ac\ub8cc\uac00 \ub41c\ub2e4. \uc7a0\uae50 \ubcf8 \ud48d\uacbd\uc774 \uc9c0\uae08\uc758 \uc0dd\ud65c\uc744 \ud3c9\uac00\ud558\ub294 \uae30\uc900\uc73c\ub85c \ub0a8\ub294\ub2e4. \uae30\uc5b5 \uc18d\uc758 \uc544\ub984\ub2e4\uc6b4 \uc7a5\uba74\uc740 \ubc18\ubcf5\ub418\ub294 \uc9d1\uc548\uc77c\uacfc \ud3c9\ubc94\ud55c \uc2dd\ud0c1\ubcf4\ub2e4 \ud6e8\uc52c \uc120\uba85\ud558\uac8c \ube5b\ub09c\ub2e4. \ubb38\uc81c\ub294 \ucc45\uc744 \uc77d\uac70\ub098 \uc544\ub984\ub2e4\uc6c0\uc744 \ubc14\ub77c\ub294 \ud589\uc704 \uc790\uccb4\uac00 \uc544\ub2c8\ub2e4. \ud2b9\ubcc4\ud55c \uc21c\uac04\ub9cc \ubaa8\uc740 \uc0c1\uc0c1\uacfc \uc2e4\uc81c \uc0dd\ud65c\uc758 \uae34 \uc2dc\uac04\uc744 \ube44\uad50\ud558\uba74 \ud604\uc2e4\uc740 \ub298 \ubd80\uc871\ud574 \ubcf4\uc77c \uc218 \uc788\ub2e4. \ud50c\ub85c\ubca0\ub974\ub294 \uc695\ub9dd\uc774 \uc9c4\uacf5\uc5d0\uc11c \uc0dd\uae30\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc774\ubbf8 \uc811\ud55c \ub9d0\uacfc \uc774\ubbf8\uc9c0\uc758 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4\ub294 \uc810\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ubcf4\ubc14\ub9ac \ubd80\ubd80\ub294 \uc6a9\ube4c\ub85c \uc62e\uae34\ub2e4. \uc7a5\uc18c\uac00 \ubc14\ub00c\uba74 \uc0b6\ub3c4 \ub2ec\ub77c\uc9c8 \uac83 \uac19\uc9c0\ub9cc \uc5e0\ub9c8\uc758 \ubd88\ub9cc\uc740 \uc0ac\ub77c\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uadf8\uacf3\uc5d0\uc11c \ub808\uc639\uacfc \uac00\uae4c\uc6cc\uc9c0\uc9c0\ub9cc \ucc98\uc74c\uc5d0\ub294 \uad00\uacc4\uac00 \ub73b\ub300\ub85c \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uc774\uc5b4 \ub85c\ub3cc\ud504\uac00 \ub4f1\uc7a5\ud558\uba74\uc11c \uc5e0\ub9c8\uac00 \ubc14\ub77c\ub358 \uc5f4\uc815\uc801\uc778 \uc0ac\ub791\uc774 \ud604\uc2e4\uc774 \ub41c \ub4ef \ubcf4\uc778\ub2e4. \uadf8\ub7ec\ub098 \uac19\uc740 \uad00\uacc4\uc5d0 \ub4e4\uc5b4\uc628 \ub450 \uc0ac\ub78c\uc758 \uae30\ub300\ub294 \ub2e4\ub974\ub2e4. \uc5e0\ub9c8\uc5d0\uac8c \uc0b6 \uc804\uccb4\ub97c \ubc14\uafc0 \uc0ac\uac74\ucc98\ub7fc \ub290\uaef4\uc9c0\ub294 \uc77c\uc774 \uc0c1\ub300\uc5d0\uac8c\ub3c4 \uac19\uc740 \ubb34\uac8c\uc778 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub140\ub294 \uac10\uc815\uc774 \uac15\ud558\ub2e4\ub294 \uc774\uc720\ub85c \uc57d\uc18d\uc758 \uc2e4\ud604 \uac00\ub2a5\uc131\uae4c\uc9c0 \ud06c\uac8c \ubbff\ub294\ub2e4. \uc774 \uc5b4\uae0b\ub0a8\uc774 \ub4a4\uc758 \uc0c1\ucc98\ub97c \uc900\ube44\ud55c\ub2e4. \ub85c\ub3cc\ud504\uc640 \ub5a0\ub0a0 \ubbf8\ub798\ub97c \uae30\ub300\ud558\ub358 \uc5e0\ub9c8\ub294 \uacb0\uad6d \ubc84\ub9bc\ubc1b\ub294\ub2e4. \uae30\ub300\uac00 \ucef8\ub358 \ub9cc\ud07c \uc88c\uc808\ub3c4 \uae4a\ub2e4. \uc774\ud6c4 \ub808\uc639\uacfc \ub2e4\uc2dc \ub9cc\ub098 \uad00\uacc4\ub97c \uc774\uc5b4 \uac00\uc9c0\ub9cc, \uc0c8\ub85c\uc6b4 \uc0ac\ub791\uc774 \uc0dd\ud65c\uc758 \ubaa8\ub4e0 \uade0\uc5f4\uc744 \uba54\uc6cc \uc8fc\uc9c0\ub294 \ubabb\ud55c\ub2e4. \uac10\uc815\uc758 \uace0\uc870\uac00 \uc9c0\ub098\uba74 \uad8c\ud0dc\uc640 \ubd88\uc548\uc774 \ub2e4\ub978 \ubaa8\uc2b5\uc73c\ub85c \ub3cc\uc544\uc628\ub2e4. \uc774 \ubc18\ubcf5 \ub54c\ubb38\uc5d0 \uc791\ud488\uc744 \uc0ac\ub791\uc5d0 \uc2e4\ud328\ud55c \uc0ac\ub78c\uc774 \ub354 \uc88b\uc740 \uc0c1\ub300\ub97c \ub9cc\ub098\uba74 \ud574\uacb0\ub418\ub294 \uc774\uc57c\uae30\ub85c \uc77d\uae30 \uc5b4\ub835\ub2e4. \uc5e0\ub9c8\uac00 \ubc14\ub77c\ubcf4\ub294 \uc774\uc0c1\uc801\uc778 \uc0b6\uacfc \uc2e4\uc81c \uad00\uacc4\uc758 \uc870\uac74 \uc0ac\uc774\uc5d0 \ub354 \uae4a\uc740 \ubb38\uc81c\uac00 \uc788\ub2e4. \uc0c1\ub300\ub97c \ubc14\uafb8\ub294 \uac83\ub9cc\uc73c\ub85c \uc0c1\uc0c1\uacfc \ud604\uc2e4\uc758 \ucc28\uc774\ub97c \ubaa8\ub450 \uc5c6\uc568 \uc218\ub294 \uc5c6\ub2e4. \uc0c1\uc778 \ub8b0\ub8b0\uc640\uc758 \uac70\ub798\ub294 \uc5e0\ub9c8\uc758 \uc695\ub9dd\uc744 \ubb3c\uac74\uacfc \ube5a\uc73c\ub85c \uc5f0\uacb0\ud55c\ub2e4. \ub2f9\uc7a5 \ub3c8\uc744 \ubaa8\ub450 \ub0b4\uc9c0 \uc54a\uc544\ub3c4 \uc6d0\ud558\ub294 \uac83\uc744 \ub9c8\ub828\ud560 \uc218 \uc788\ub2e4. \uc637\uacfc \uc0dd\ud65c\uc6a9\ud488\uc740 \ub2e4\ub978 \uc0b6\uc744 \uc190\uc5d0 \ub123\uc740 \ub4ef\ud55c \uac10\uac01\uc744 \uc8fc\uc9c0\ub9cc, \ub300\uae08\uc740 \uc0ac\ub77c\uc9c0\uc9c0 \uc54a\uace0 \ub4a4\ub85c \ubbf8\ub904\uc9c4\ub2e4. \uac10\uc815\uc758 \uc2dc\uac04\uacfc \uc9c0\ubd88\uc758 \uc2dc\uac04\uc774 \uc5c7\uac08\ub9ac\ub294 \uac83\uc774\ub2e4. \uc774 \uc9c0\uc810\uc5d0\uc11c \uc18c\uc124\uc758 \ub3c8 \uc774\uc57c\uae30\ub294 \ubc30\uacbd \uc7a5\uc2dd\uc774 \uc544\ub2c8\ub2e4. \uc57d\uc18d\uacfc \uc11c\ub958, \uac1a\uc544\uc57c \ud560 \uae08\uc561\uc774 \uc778\ubb3c\uc758 \uc120\ud0dd\uc744 \uc881\ud78c\ub2e4. \uc678\uc0c1\uc740 \ucc98\uc74c\uc5d0\ub294 \uac00\ub2a5\uc131\uc744 \ub113\ud788\ub294 \ub4ef\ud558\ub2e4\uac00 \ub098\uc911\uc5d0\ub294 \uc6c0\uc9c1\uc77c \uc790\ub9ac\ub97c \uc904\uc778\ub2e4. \uafc8\uc774 \ube5a\uc73c\ub85c \ubc14\ub00c\ub294 \uacfc\uc815\uc774 \uac70\ub798\uc758 \uad6c\uccb4\uc801\uc778 \ud615\ud0dc\ub85c \ub4dc\ub7ec\ub09c\ub2e4. \ucc44\ubb34 \ubb38\uc81c\uac00 \ub354\ub294 \uac10\ucd9c \uc218 \uc5c6\ub294 \uc0c1\ud669\uc774 \ub418\uc790 \uc5e0\ub9c8\ub294 \ub3c8\uc744 \uad6c\ud558\ub824 \ud558\uc9c0\ub9cc \ub3c4\uc6c0\uc744 \uc5bb\uc9c0 \ubabb\ud55c\ub2e4. \uc790\uc2e0\uc774 \uc758\uc9c0\ud588\ub358 \uad00\uacc4\ub4e4\uc774 \uc704\uae30 \uc55e\uc5d0\uc11c \uc5bc\ub9c8\ub098 \uc57d\ud55c\uc9c0 \ub4dc\ub7ec\ub09c\ub2e4. \uadf8\ub140\ub294 \ub05d\ub0b4 \uc2a4\uc2a4\ub85c \ubaa9\uc228\uc744 \ub04a\ub294\ub2e4. \uc18c\uc124\uc740 \uadf8 \uc8fd\uc74c\uc744 \ub0ad\ub9cc\uc801\uc778 \uc0ac\ub791\uc758 \uc644\uc131\ucc98\ub7fc \uc7a5\uc2dd\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc5e0\ub9c8\uac00 \uc8fd\uc5c8\ub2e4\uace0 \uac00\uc871\uc758 \ubb38\uc81c\uac00 \ud568\uaed8 \ub05d\ub098\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \ub0a8\uaca8\uc9c4 \uc0e4\ub97c\uacfc \ub538 \ubca0\ub974\ud2b8\uc758 \uc0b6\uc73c\ub85c \uc190\uc2e4\uc774 \uc774\uc5b4\uc9c4\ub2e4. \uc18c\uc124\uc758 \uc2dc\uc120\uc774 \uc8fc\uc778\uacf5\uc758 \uac15\ub82c\ud55c \uac10\uc815\uc5d0\uc11c \ubc97\uc5b4\ub098 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ub0a8\uc740 \uacb0\uacfc\uae4c\uc9c0 \ud5a5\ud55c\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \ube44\uadf9\uc740 \ud55c \uc0ac\ub78c\uc758 \ub9c8\uc9c0\ub9c9 \uc21c\uac04\ubcf4\ub2e4 \uae38\ub2e4. \u300e\ubcf4\ubc14\ub9ac \ubd80\uc778\u300f\uc758 \ubb38\uc7a5\uc740 \ub54c\ub85c \uc778\ubb3c\uc758 \uae30\ub300\uc640 \uc0c1\ud22c\uc801\uc778 \ud45c\ud604\uc5d0 \uac00\uae4c\uc6cc\uc84c\ub2e4\uac00 \ub2e4\uc2dc \uac70\ub9ac\ub97c \ub454\ub2e4. \ub3c5\uc790\ub294 \uc5e0\ub9c8\ub97c \uc774\ud574\ud558\uba74\uc11c\ub3c4 \uadf8\ub140\uac00 \uc790\uc2e0\uacfc \ud0c0\uc778\uc744 \uc18d\uc774\ub294 \uc7a5\uba74\uc744 \ubcf8\ub2e4. \uc8fc\ubcc0 \uc778\ubb3c\ub4e4\ub3c4 \ub2e8\uc21c\ud55c \uc0c1\uc2dd\uc758 \ub300\ubcc0\uc790\uac00 \uc544\ub2c8\ub77c \ud5c8\uc601\uacfc \uacc4\uc0b0\uc744 \uac00\uc9c4 \uc0ac\ub78c\ub4e4\uc774\ub2e4. \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \uc57d\uc0ac \uc624\uba54\uac00 \uc0ac\ud68c\uc801 \uc778\uc815\uc744 \uc5bb\uc5c8\ub2e4\ub294 \uc18c\uc2dd\ub3c4 \ub193\uc778\ub2e4. \ubca0\ub974\ud2b8\uc5d0\uac8c \ub0a8\uc740 \uac00\ub09c\uacfc \ub2e4\ub978 \uc778\ubb3c\uc758 \uc131\uacf5\uc774 \ub098\ub780\ud788 \ubcf4\uc778\ub2e4. \ud55c \uac00\uc871\uc758 \ud30c\uad6d\uacfc \ub9c8\uc744\uc758 \uc77c\uc0c1\uc740 \uac19\uc740 \uacb0\ub9d0\uc744 \ub9de\uc9c0 \uc54a\ub294\ub2e4. \uadf8 \ucc28\uc774 \ub54c\ubb38\uc5d0 \uc18c\uc124\uc758 \ub9c8\uc9c0\ub9c9\uc740 \ub354\uc6b1 \ucc28\uac11\uac8c \uc77d\ud78c\ub2e4. \uadf8\ub798\uc11c \uc774 \uc791\ud488\uc740 \uc695\ub9dd\uc744 \uac16\uc9c0 \ub9d0\ub77c\ub294 \uad50\ud6c8\uc73c\ub85c \uc904\uc5b4\ub4e4\uc9c0 \uc54a\ub294\ub2e4. \ubb34\uc5c7\uc744 \ud589\ubcf5\uc758 \uae30\uc900\uc73c\ub85c \uc0bc\ub294\uc9c0, \uc0ac\ub791\uacfc \uc18c\ube44\ub97c \ud1b5\ud574 \uc5b4\ub5a4 \uc0b6\uc744 \uc5bb\uc73c\ub824 \ud558\ub294\uc9c0 \ubb3b\uac8c \ud55c\ub2e4. \uc5e0\ub9c8\uc758 \uba3c \uc2dc\ub300\ub97c \uc77d\uc73c\uba70 \ud604\uc7ac\uc758 \ub3c5\uc790\ub3c4 \uc790\uc2e0\uc758 \uae30\ub300\ub97c \ub9cc\ub4e0 \ub9d0\uacfc \ud48d\uacbd\uc744 \ub3cc\uc544\ubcfc \uc218 \uc788\ub2e4."}, {"id": "maui-snaring-sun-kapa-days", "title": "\ub9c8\uc6b0\uc774\ub294 \uc65c \ud0dc\uc591\uc5d0 \ubc27\uc904\uc744 \uac78\uc5c8\uc744\uae4c", "summary": "\ud558\uc640\uc774 \uc804\uc2b9\uc9d1\uc758 \ud55c \ud310\ubcf8\uc5d0\uc11c, \ub108\ubb34 \ube68\ub9ac \ub2ec\ub9ac\ub294 \ud0dc\uc591\uc744 \ubd99\uc7a1\uc740 \ub9c8\uc6b0\uc774\uc758 \uc0ac\uc5f0\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc2e0\ud654\uc640 \ubbfc\uc18d", "categories": ["arts"], "url": "stories/maui-snaring-sun-kapa-days/index.html", "image": "../media/maui-snaring-sun-kapa-days.png", "alt": "\uc0b0 \uc704\uc5d0\uc11c \ubc27\uc904\ub85c \ud0dc\uc591\uc744 \ubd99\uc7a1\ub294 \ub9c8\uc6b0\uc774\ub97c \uadf8\ub9b0 \ud558\uc640\uc774 \uc804\uc2b9\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ub9c8\uc6b0\uc774\ub294 \uc65c \ud0dc\uc591\uc5d0 \ubc27\uc904\uc744 \uac78\uc5c8\uc744\uae4c \uc5b4\uba38\ub2c8\uc758 \ucc9c\uc774 \ub9c8\ub974\uae30\ub3c4 \uc804\uc5d0 \ud558\ub8e8\uac00 \ub05d\ub098\ub294 \uc138\uc0c1 \ud558\uc640\uc774 \uc804\uc2b9\uc9d1\uc758 \ud55c \ud310\ubcf8\uc5d0\uc11c, \ub108\ubb34 \ube68\ub9ac \ub2ec\ub9ac\ub294 \ud0dc\uc591\uc744 \ubd99\uc7a1\uc740 \ub9c8\uc6b0\uc774\uc758 \uc0ac\uc5f0\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc2e0\ud654\uc640 \ubbfc\uc18d \ubb38\ud654\uc640 \uc608\uc220 \ube68\ub798\uac00 \ub9c8\ub974\uae30\ub3c4 \uc804\uc5d0 \ud574\uac00 \uc838 \ubc84\ub9b0\ub2e4\uba74 \ud558\ub8e8\uac00 \uc5bc\ub9c8\ub098 \uc9e7\uac8c \ub290\uaef4\uc9c8\uae4c. \ud558\uc640\uc774\uc758 \uc601\uc6c5 \ub9c8\uc6b0\uc774\uc5d0\uac8c \ud0dc\uc591\uc744 \ubd99\uc7a1\uc73c\ub7ec \uac08 \uc774\uc720\ub97c \ub9cc\ub4e4\uc5b4 \uc900 \uac83\ub3c4 \uac70\ub300\ud55c \uc804\uc7c1\uc774 \uc544\ub2c8\ub77c \ucc9c\uc744 \ub9d0\ub9ac\ub294 \uc5b4\uba38\ub2c8\uc758 \uc5b4\ub824\uc6c0\uc774\uc5c8\ub2e4. \uc5ec\uae30\uc11c\ub294 \ud1a0\uba38\uc2a4 G. \uc2a4\ub7fc\uc774 \uc5ee\uc740 \u300e\ud558\uc640\uc774 \ubbfc\ub2f4\u300f \uc911 A. O. \ud3ec\ube0c\uc2a4\uac00 \uc18c\uac1c\ud55c \u300c\ub9c8\uc6b0\uc774\uc758 \ubaa8\ud5d8\u300d\uc758 \uccab \uc774\uc57c\uae30\ub97c \ub530\ub978\ub2e4. \ud0dc\ud3c9\uc591 \uc5ec\ub7ec \uc9c0\uc5ed\uc758 \ub9c8\uc6b0\uc774 \uc804\uc2b9\uc740 \uc11c\ub85c \uac19\uc9c0 \uc54a\ub2e4. \uc775\uc219\ud55c \uc560\ub2c8\uba54\uc774\uc158\uc774\ub098 \ub2e4\ub978 \uc9c0\uc5ed\uc758 \ubb34\uae30\ub97c \uc774 \ud310\ubcf8\uc5d0 \ub367\ubd99\uc774\uc9c0 \uc54a\uace0 \uacb0\ub9d0\uae4c\uc9c0 \uc77d\uc5b4 \ubcf8\ub2e4. \uc774\uc57c\uae30 \uc18d \ud0dc\uc591\uc740 \ud558\ub298\uc744 \uc544\uc8fc \ube60\ub974\uac8c \uac00\ub85c\uc9c0\ub978\ub2e4. \uc544\uce68\uc774 \uc654\ub2e4 \uc2f6\uc73c\uba74 \uace7 \uc800\ub141\uc774\ub2e4. \ud558\ub8e8\uac00 \uc9e7\uc73c\ub2c8 \ud574\uc57c \ud560 \uc77c\uc744 \ub9c8\uce58\uae30 \uc5b4\ub835\ub2e4. \ub9c8\uc6b0\uc774\uc758 \uc5b4\uba38\ub2c8 \ud788\ub098\ub294 \uce74\ud30c\ub77c\ub294 \ucc9c\uc744 \ub9cc\ub4e4\uc9c0\ub9cc, \ud3bc\uccd0 \ub9d0\ub9ac\ub824 \ud558\uba74 \ucda9\ubd84\ud788 \ub9c8\ub974\uae30\ub3c4 \uc804\uc5d0 \ud587\ube5b\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \uc6b0\ub9ac\uc5d0\uac8c \ud574\uac00 \uc9c4\ub2e4\ub294 \uac83\uc740 \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \uc77c\uc774\uc9c0\ub9cc, \uc774\uc57c\uae30 \uc18d\uc5d0\uc11c\ub294 \ud0dc\uc591\uc758 \ud589\ub3d9\uc774 \ud574\uacb0\ud574\uc57c \ud560 \ubb38\uc81c\uac00 \ub41c\ub2e4. \ub0ae\uc758 \uae38\uc774\ub97c \ub2f9\uc5f0\ud55c \uc870\uac74\uc73c\ub85c \ubc1b\uc544\ub4e4\uc774\ub294 \ub300\uc2e0 \ub204\uad70\uac00 \ub108\ubb34 \uc11c\ub458\ub7ec \uc9c0\ub098\uac00\ub294 \ud0d3\uc774\ub77c\uace0 \uc0dd\uac01\ud55c \uac83\uc774\ub2e4. \ud558\ub298\uc758 \uac70\ub300\ud55c \uc6c0\uc9c1\uc784\uc774 \uc9d1\uc548\uc758 \uc77c\uacfc \uc5f0\uacb0\ub418\uba70 \uc2e0\ud654\ub294 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \ub9c8\uc6b0\uc774\ub294 \ud0dc\uc591\uc774 \uc5b4\ub514\ub85c \uc6c0\uc9c1\uc774\ub294\uc9c0 \uc0b4\ud53c\uae30 \uc2dc\uc791\ud55c\ub2e4. \ubb34\uc791\uc815 \ud558\ub298\uc5d0 \ub300\uace0 \ud654\ub97c \ub0b4\ub294 \ub300\uc2e0 \uae38\ubaa9\uc744 \uc54c\uc544\ub0b4\uace0, \ubd99\uc7a1\uc744 \ub3c4\uad6c\ub97c \uc900\ube44\ud55c\ub2e4. \uc774 \ud310\ubcf8\uc5d0\uc11c \ubc27\uc904\uc740 \ucf54\ucf54\ub11b\uc758 \uc12c\uc720\ub97c \uc774\uc6a9\ud574 \ub9cc\ub4e0\ub2e4. \uc8fc\ubcc0\uc5d0\uc11c \uad6c\ud560 \uc218 \uc788\ub294 \uc7ac\ub8cc\uac00 \ud558\ub298\uc758 \uc874\uc7ac\uc640 \ub9de\uc11c\ub294 \uc7a5\ube44\ub85c \ubc14\ub010\ub2e4. \uc2e0\ud654\uc758 \uacfc\uc7a5\uc740 \ub300\ub2e8\ud558\uc9c0\ub9cc \uacfc\uc815\uc5d0\ub294 \ub178\ub3d9\uc758 \uac10\uac01\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uc7ac\ub8cc\ub97c \uc5bb\uace0 \ub048\uc744 \ub9cc\ub4dc\ub294 \uc900\ube44\uac00 \uc788\uc5b4\uc57c \uc0b0 \uc704\uc758 \ub300\uacb0\ub3c4 \uac00\ub2a5\ud558\ub2e4. \ud0dc\uc591\uc744 \ubd99\uc7a1\ub294 \ud798\ub9cc \ub5a0\uc62c\ub9ac\uae30 \uc27d\uc9c0\ub9cc, \uadf8 \ud798\uc740 \uc544\ubb34\uac83\ub3c4 \ud558\uc9c0 \uc54a\uc740 \uc0ac\ub78c\uc5d0\uac8c \uac11\uc790\uae30 \uc0dd\uae30\ub294 \ud3b8\ub9ac\ud55c \ud574\uacb0\ucc45\uc73c\ub85c \ub098\uc624\uc9c0 \uc54a\ub294\ub2e4. \ud0dc\uc591\uc744 \uc7a1\uaca0\ub2e4\ub294 \uacc4\ud68d\uc744 \ub4e3\uace0 \ubaa8\uc5d0\ubaa8\uc5d0\ub77c\ub294 \uc778\ubb3c\uc740 \ub9c8\uc6b0\uc774\ub97c \ube44\uc6c3\ub294\ub2e4. \uadf8 \uac70\ub300\ud55c \uc874\uc7ac\ub97c \uc5b4\ub5bb\uac8c \ubd99\uc7a1\ub290\ub0d0\ub294 \uac83\uc774\ub2e4. \ub4e3\ub294 \ucabd\uc5d0\uc11c\ub294 \uadf8\ub7f4\ub4ef\ud55c \uc758\ubb38\uc774\ub2e4. \ub9c8\uc6b0\uc774\ub294 \uc774 \uc870\ub871\uc744 \uac00\ubccd\uac8c \ud758\ub9ac\uc9c0 \uc54a\uace0, \uc77c\uc744 \ub05d\ub0b8 \ub4a4 \ub418\uac1a\uaca0\ub2e4\ub294 \ub73b\uc744 \ub4dc\ub7ec\ub0b8\ub2e4. \uc774 \ub300\ubaa9\uc740 \ub4a4\uc758 \uacb0\ub9d0\uc744 \uc704\ud574 \uae30\uc5b5\ud574 \ub458 \ud544\uc694\uac00 \uc788\ub2e4. \ub9c8\uc6b0\uc774\ub294 \uc5b4\uba38\ub2c8\ub97c \ub3d5\ub294 \ub2e4\uc815\ud55c \uc544\ub4e4\uc774\uc9c0\ub9cc \ubaa8\uc695\uc744 \uc27d\uac8c \ub118\uae30\ub294 \uc628\uc21c\ud55c \uc601\uc6c5\uc740 \uc544\ub2c8\ub2e4. \uc2e0\ud654\uc758 \uc8fc\uc778\uacf5\uc5d0\uac8c \uc88b\uc740 \uc131\uaca9\ub9cc \uace8\ub77c \ubd99\uc774\uba74 \uc774 \ud310\ubcf8\uc758 \uac70\uce60\uace0 \ubd88\ud3b8\ud55c \uba74\uc744 \ub193\uce58\uac8c \ub41c\ub2e4. \uc774\uc57c\uae30\ub294 \uc77c\ucc0d\ubd80\ud130 \ub450 \ubaa8\uc2b5\uc744 \ud568\uaed8 \ubcf4\uc5ec \uc900\ub2e4. \ub9c8\uc6b0\uc774\ub294 \ud560\ub808\uc544\uce7c\ub77c\ub85c \uc62c\ub77c\uac04\ub2e4. \ubc14\ub2e4\ub97c \uac74\ub108\uac70\ub098 \ud558\ub298\ub85c \ub0a0\uc544\uac00 \ud0dc\uc591\uc744 \ucd94\uaca9\ud558\ub294 \ub300\uc2e0, \ub5a0\uc624\ub974\ub294 \uae38\ubaa9\uc5d0\uc11c \uae30\ub2e4\ub9ac\ub294 \ubc29\ubc95\uc744 \ud0dd\ud55c\ub2e4. \uc544\ubb34\ub9ac \ube60\ub978 \uc0c1\ub300\ub77c\ub3c4 \ubc18\ub4dc\uc2dc \uc9c0\ub098\uc57c \ud558\ub294 \uc7a5\uc18c\uac00 \uc788\ub2e4\uba74 \uadf8\uacf3\uc774 \uae30\ud68c\uac00 \ub41c\ub2e4. \uc2e0\ud654 \uc18d \uaf80\ub294 \uc5ec\uae30\uc5d0\uc11c \ud1b5\ud55c\ub2e4. \uc774 \ud310\ubcf8\uc740 \ud0dc\uc591\uc758 \uac15\ud55c \uad11\uc120\uc744 \ub2e4\ub9ac\ucc98\ub7fc \ub2e4\ub8ec\ub2e4. \ub9c8\uc6b0\uc774\ub294 \uadf8 \ube5b\uc744 \uc62c\uac00\ubbf8\ub85c \ubd99\uc7a1\uace0 \ubd80\ub7ec\ub728\ub9b0\ub2e4. \ube5b\uc774 \ubc27\uc904\uc5d0 \uac78\ub9b4 \uc218 \uc788\ub2e4\ub294 \uc0c1\uc0c1 \ub355\ubd84\uc5d0 \uba40\ub9ac \uc788\ub358 \ud0dc\uc591\uc774 \ubab8\uc744 \uac00\uc9c4 \uc0c1\ub300\uac00 \ub41c\ub2e4. \ucc9c\ubb38 \ud604\uc0c1\uc744 \uc0ac\uc2e4\ub300\ub85c \uc124\uba85\ud558\ub294 \uc7a5\uba74\uc774 \uc544\ub2c8\ub77c, \ub208\uc5d0 \ubcf4\uc774\uc9c0 \uc54a\ub294 \ud798\uaca8\ub8e8\uae30\ub97c \ub208\uc55e\uc758 \ub3d9\uc791\uc73c\ub85c \ubc14\uafbc \uc7a5\uba74\uc774\ub2e4. \ubd99\uc7a1\ud78c \ud0dc\uc591\uc740 \uc0b4\ub824 \ub2ec\ub77c\uace0 \uccad\ud55c\ub2e4. \ub9c8\uc6b0\uc774\uc758 \ubaa9\uc801\uc740 \ud0dc\uc591\uc744 \uc5c6\uc560\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \ud0dc\uc591\uc774 \uc0ac\ub77c\uc9c0\uba74 \uc5b4\uba38\ub2c8\uc758 \ucc9c\ub3c4 \ub9c8\ub97c \uc218 \uc5c6\uace0 \uc0ac\ub78c\ub4e4\uc758 \uc0dd\ud65c\ub3c4 \uc774\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \ud544\uc694\ud55c \uac83\uc740 \ud30c\uad34\uac00 \uc544\ub2c8\ub77c \uc18d\ub3c4\uc758 \ubcc0\ud654\ub2e4. \uacb0\uad6d \ub354 \ucc9c\ucc9c\ud788 \uc6c0\uc9c1\uc774\uaca0\ub2e4\ub294 \uc57d\uc18d\uc774 \uc774\ub8e8\uc5b4\uc9c4\ub2e4. \uc804\uc2b9\uc740 \uc774 \uc57d\uc18d\uc744 \ud558\ub8e8\uc640 \uacc4\uc808\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c0\ub294 \ube5b\uc758 \uc2dc\uac04\uacfc \uc5f0\uacb0\ud55c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc2e4\uc81c \ub0ae\uc758 \uae38\uc774\uac00 \uc774 \uc0ac\uac74 \ub54c\ubb38\uc5d0 \ubcc0\ud588\ub2e4\uace0 \ubc1b\uc544\ub4e4\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uc2e0\ud654\uac00 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \uc0ac\ub78c\ub4e4\uc774 \ubab8\uc73c\ub85c \ub290\ub080 \uc2dc\uac04\uc774\ub2e4. \ucc9c\uc744 \ub9cc\ub4e4\uace0 \ub9d0\ub9ac\uace0 \uc77c\uc744 \ub9c8\uce60 \ub9cc\ud07c \ucda9\ubd84\ud55c \ud558\ub8e8\uac00 \ud544\uc694\ud588\ub2e4\ub294 \ubc14\ub78c\uc774\ub2e4. \uc5ec\uae30\uae4c\uc9c0\ub9cc \uc77d\uc73c\uba74 \uc5b4\uba38\ub2c8\ub97c \ub3d5\uae30 \uc704\ud574 \ud558\ub298\uc744 \uae38\ub4e4\uc778 \uc601\uc6c5\ub2f4\ucc98\ub7fc \ubcf4\uc778\ub2e4. \ud558\uc9c0\ub9cc \uc120\ud0dd\ud55c \uc804\uc2b9\uc9d1\uc740 \ub9c8\uc6b0\uc774\uac00 \ub3cc\uc544\uc640 \ubaa8\uc5d0\ubaa8\uc5d0\ub97c \ucc3e\uc544 \uc8fd\uc774\ub294 \uc77c\uae4c\uc9c0 \ub4e4\ub824\uc900\ub2e4. \uadf8\uc758 \ubab8\uc774 \ubc14\uc704\uac00 \ub418\uc5c8\ub2e4\ub294 \uc9c0\uc5ed\uc758 \uc774\uc57c\uae30\ub85c \uc774\uc5b4\uc9c4\ub2e4. \uc624\ub298\uc758 \uac10\uac01\uc73c\ub85c\ub294 \uc131\uacf5 \ub4a4\uc5d0 \ubd99\uc740 \uc9c0\ub098\uce5c \ubcf4\ubcf5\uc774\ub2e4. \uc774 \uacb0\ub9d0\uc744 \ube7c\uace0 \ub9c8\uc6b0\uc774\uac00 \ubaa8\ub450\ub97c \ud589\ubcf5\ud558\uac8c \ub9cc\ub4e0 \ucc29\ud55c \uc601\uc6c5\uc774\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud558\uba74 \uc77d\uae30\ub294 \ud3b8\ud574\uc838\ub3c4 \uc6d0\ub798 \uc774\uc57c\uae30\ub294 \ub2ec\ub77c\uc9c4\ub2e4. \ub300\ub2e8\ud55c \uc77c\uc744 \ud574\ub0b8 \uc778\ubb3c\uacfc \uadf8 \ud589\ub3d9\uc744 \ubaa8\ub450 \uc633\ub2e4\uace0 \uc778\uc815\ud560 \uc218 \uc788\ub294 \uc778\ubb3c\uc740 \uac19\uc9c0 \uc54a\ub2e4. \uac10\ud0c4\uacfc \ubd88\ud3b8\ud568\uc774 \ud568\uaed8 \ub0a8\ub294 \uac83\ub3c4 \uc61b \uc804\uc2b9\uc744 \uc77d\ub294 \uacbd\ud5d8\uc758 \uc77c\ubd80\ub2e4. \uc2e4\uc81c \uc0b0\uc758 \uc774\ub984\uc774\ub098 \ubc14\uc704\ub97c \uc804\uc2b9\uacfc \uc5f0\uacb0\ud558\ub294 \uc124\uba85\uc740 \ud48d\uacbd\uc744 \uae30\uc5b5\ud558\ub294 \ubc29\ubc95\uc774 \ub418\uc5c8\ub2e4. \ub2e4\ub9cc \uc61b \uc804\uc2b9\uc9d1\uc758 \uc774\ub984 \ud480\uc774\ub97c \uc624\ub298\uc758 \uc5b8\uc5b4\ud559\uc801 \uc815\uc124\ucc98\ub7fc \uc62e\uae30\uc9c0\ub294 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc9c0\uba85\uc5d0 \uc5bd\ud78c \uc774\uc57c\uae30\uc640 \uc774\ub984\uc758 \uc5ed\uc0ac\uc801 \uc5b4\uc6d0\uc744 \ubc1d\ud788\ub294 \uc77c\uc740 \uc11c\ub85c \ub2e4\ub978 \uc791\uc5c5\uc774\ub2e4. \ud558\uc640\uc774\uc758 \uc774 \ud310\ubcf8\uc740 \uc5b4\uba38\ub2c8\uc758 \uce74\ud30c, \ucf54\ucf54\ub11b \uc12c\uc720 \ubc27\uc904, \uc0b0 \uc704\uc758 \ub300\uacb0\uc744 \ud55c \uc904\ub85c \uc787\ub294\ub2e4. \ub2e4\ub978 \uc9c0\uc5ed \uc774\uc57c\uae30\uc758 \ud615\uc81c\ub4e4\uc774\ub098 \ud2b9\ubcc4\ud55c \ud131\ubf08 \ubb34\uae30\ub97c \uac00\uc838\uc624\uc9c0 \uc54a\uc544\ub3c4 \ucda9\ubd84\ud788 \uc0dd\uc0dd\ud558\ub2e4. \ub0ae\uc774 \uc870\uae08 \uae38\uc5c8\uc73c\uba74 \uc88b\uaca0\ub2e4\ub294 \uc18c\ubc15\ud55c \uc18c\ub9dd\uc774 \ud0dc\uc591\uacfc \ud611\uc0c1\ud558\ub294 \ubaa8\ud5d8\uc774 \ub41c \uac83\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \ud574\uac00 \uae38\uac8c \ub0a8\uc740 \uc800\ub141\uc744 \ub9cc\ub098\uba74 \uadf8 \ubc27\uc904\uc744 \uc7a0\uae50 \ub5a0\uc62c\ub824\ub3c4 \uc88b\uaca0\ub2e4."}, {"id": "metal-flute-inlaid-flowers", "title": "\ub300\uae08\uc5d0\ub3c4 \ubc18\uc9dd\uc774\ub294 \uaf43\ubb34\ub2ac\uac00 \uc788\uc5c8\ub2e4", "summary": "\uae08\uc740\uc785\uc0ac \uc7a5\uc2dd\uc774 \uc788\ub294 \ub300\uae08\uc5d0\uc11c \uc545\uae30\uc758 \ub610 \ub2e4\ub978 \ud45c\uc815\uc744 \ucc3e\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc74c\uc545", "categories": ["arts"], "url": "stories/metal-flute-inlaid-flowers/index.html", "image": "../media/metal-flute-inlaid-flowers.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \ucca0\uc81c\uae08\uc740\uc785\uc0ac\ub300\uae08 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\ub300\uae08\uc5d0\ub3c4 \ubc18\uc9dd\uc774\ub294 \uaf43\ubb34\ub2ac\uac00 \uc788\uc5c8\ub2e4 \uc18c\ub9ac\ub97c \ub0b4\ub294 \uae34 \uad00\uc5d0 \ub354\ud55c \uc7a5\uc2dd \uae08\uc740\uc785\uc0ac \uc7a5\uc2dd\uc774 \uc788\ub294 \ub300\uae08\uc5d0\uc11c \uc545\uae30\uc758 \ub610 \ub2e4\ub978 \ud45c\uc815\uc744 \ucc3e\uc2b5\ub2c8\ub2e4. \uc74c\uc545 \ubb38\ud654\uc640 \uc608\uc220 \ub300\uae08\uc774\ub77c\ub294 \uc774\ub984\uc744 \ub4e4\uc73c\uba74 \uae38\ucb49\ud55c \ub300\ub098\ubb34 \uc545\uae30\uac00 \ub5a0\uc624\ub978\ub2e4. \uadf8\ub7f0\ub370 \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \ucca0\uc81c\uae08\uc740\uc785\uc0ac\ub300\uae08\uc740 \uc774\ub984\ubd80\ud130 \uc870\uae08 \ub2e4\ub974\ub2e4. \uae08\uc18d\uc73c\ub85c \ub9cc\ub4e0 \uc545\uae30\uc5d0 \uaf43\uacfc \ud559 \ubb34\ub2ac\uae4c\uc9c0 \ub354\ud588\ub2e4. \uc804\uccb4 \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uac00\ub290\ub2e4\ub780 \uc120\ucc98\ub7fc \ubcf4\uc5ec\uc11c \uc7a5\uc2dd\uc774 \uc27d\uac8c \ub208\uc5d0 \ub4e4\uc5b4\uc624\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uc545\uae30\ub77c\ub294 \uc0ac\uc2e4\uc744 \ud655\uc778\ud55c \ub4a4, \uc774\ubc88\uc5d0\ub294 \uc5b4\ub514\uc5d0 \uc5b4\ub5a4 \ubb34\ub2ac\ub97c \ub193\uc558\ub294\uc9c0 \uc124\uba85\uc744 \uae38\uc7a1\uc774 \uc0bc\uc544 \ucc9c\ucc9c\ud788 \uc0b4\ud3b4\ubcf4\uc790. \ubc15\ubb3c\uad00\uc740 \uc774 \uc545\uae30\ub97c \uac00\ub85c\ub85c \uc5f0\uc8fc\ud558\ub294 \uad00\uc545\uae30\ub85c \uc18c\uac1c\ud558\uace0, \ubab8\uccb4\uc5d0 \uad6c\uba4d\uc774 \uc5f4\ub450 \uac1c \ub6ab\ub824 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uae38\uac8c \ubed7\uc740 \uad00\uacfc \uad6c\uba4d\uc740 \uc18c\ub9ac\ub97c \ub0b4\ub294 \uc545\uae30\uc758 \ud2b9\uc9d5\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ubd80\ubd84\uc774\ub2e4. \uac70\uae30\uc5d0 \uae08\uc740\uc785\uc0ac \uae30\ubc95\uc73c\ub85c \uaf43\ubb34\ub2ac\uc640 \uaf43\ub369\uad74\ubb34\ub2ac\ub97c \ub354\ud588\ub2e4\uace0 \ud55c\ub2e4. \uc5f0\uc8fc \ub3c4\uad6c\uc758 \ud45c\uba74\uc5d0 \uc7a5\uc2dd\uc758 \uc790\ub9ac\uac00 \ud568\uaed8 \ub9c8\ub828\ub41c \uac83\uc774\ub2e4. \uad6c\uba4d\uc744 \ubaa8\ub450 \uac19\uc740 \uc6a9\ub3c4\uc758 \uc190\uac00\ub77d \uad6c\uba4d\uc774\ub77c\uace0 \ub2e8\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubc15\ubb3c\uad00\uc774 \uc54c\ub824 \uc8fc\ub294 \uc804\uccb4 \uac1c\uc218\ub85c \uc77d\uc73c\uba74 \ub41c\ub2e4. \uc591\ub05d\uc5d0\ub294 \uac19\uc740 \uae30\ubc95\uc73c\ub85c \ud559 \ubb34\ub2ac\ub97c \ud45c\ud604\ud588\ub2e4. \ubab8\ud1b5\uc758 \uaf43\uacfc \ub05d\ubd80\ubd84\uc758 \uc0c8\ub97c \ub098\ub204\uc5b4 \ub193\uc740 \uad6c\uc131\uc774 \ubcf4\uc778\ub2e4. \uac00\uc6b4\ub370\uc640 \ub05d\uc744 \ub530\ub85c \uc0b4\ud53c\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \uae34 \ubb3c\uac74\uc744 \ubcf4\ub294 \uc21c\uc11c\uac00 \uc0dd\uae34\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uc791\uc740 \ubb34\ub2ac\uac00 \uc120\uba85\ud558\uc9c0 \uc54a\uc744 \ub54c\ub294 \ud655\ub300\ud574 \ubcf4\ub418 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc120\uc744 \uc5b5\uc9c0\ub85c \uc77d\uc5b4\ub0bc \ud544\uc694\ub294 \uc5c6\ub2e4. \uc545\uae30\uc758 \uc7a5\uc2dd\uc5d0 \uad00\ud55c \uc815\ubcf4\ub294 \uc0ac\uc9c4\uacfc \ud568\uaed8 \uc81c\uacf5\ub418\ub294 \uc18c\uc7a5\ud488 \uc124\uba85\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \ub300\uae08\uc758 \uc0ac\uc9c4\uc744 \ubcfc \ub54c \ud55c\uac00\uc6b4\ub370\ub9cc \ud655\ub300\ud558\uba74 \uae34 \uad00 \uc804\uccb4\uc758 \uad6c\uc131\uc744 \ub193\uce60 \uc218 \uc788\ub2e4. \uba3c\uc800 \ub05d\uc5d0\uc11c \ub05d\uae4c\uc9c0 \uc774\uc5b4\uc9c0\ub294 \ud615\ud0dc\ub97c \ubcf4\uace0 \ub2e4\uc74c\uc5d0 \uad6c\uba4d\uacfc \ud45c\uba74\uc758 \ubb34\ub2ac\ub97c \uc0b4\ud3b4\ubcf4\uc790. \uc18c\ub9ac\ub97c \ub9cc\ub4dc\ub294 \uad6c\uc870\uc640 \uc7a5\uc2dd\uc774 \uac19\uc740 \uae38\uc774 \uc548\uc5d0 \ub098\ub780\ud788 \ub193\uc778\ub2e4. \uc5b4\ub290 \ud55c\ucabd\uc744 \ubd80\uc218\uc801\uc778 \uac83\uc73c\ub85c \uc9c0\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uc545\uae30\ub97c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uad00\uc545\uae30\ub77c\ub294 \uc774\ub984\uc744 \ub4e4\uc5c8\ub2e4\uace0 \ub208\uc55e\uc758 \ubaa8\ub4e0 \uad6c\uba4d\uc744 \uac19\uc740 \uc6a9\ub3c4\ub85c \ubb36\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc790\ub8cc\ub294 \uc804\uccb4 \uad6c\uba4d\uc758 \uac1c\uc218\ub97c \uc54c\ub824 \uc8fc\uc9c0\ub9cc, \uac01\uac01\uc758 \uae30\ub2a5\uc744 \uc124\uba85 \uc5c6\uc774 \uc0c8\ub85c \ub098\ub204\uc5b4 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5f0\uc8fc \uad6c\uc870\uc758 \uc138\ubd80\ub294 \ub2e4\ub978 \uc545\uae30 \uc790\ub8cc\uc640 \ud568\uaed8 \ud655\uc778\ud560 \ubb38\uc81c\ub2e4. \uc720\ubb3c\uc758 \uc124\uba85\uc774 \uc81c\uacf5\ud558\ub294 \ubc94\uc704 \uc548\uc5d0\uc11c\ub3c4 \ubaa8\uc591\uacfc \uc7a5\uc2dd\uc758 \ubc30\uce58\ub97c \ubcfc \ub2e8\uc11c\ub294 \ucda9\ubd84\ud558\ub2e4. \uae08\uc740\uc785\uc0ac\ub77c\ub294 \ub9d0\uc740 \uae08\uacfc \uc740\uc744 \uc774\uc6a9\ud574 \ubb34\ub2ac\ub97c \ud45c\ud604\ud55c \uc81c\uc791\uc744 \uac00\ub9ac\ud0a8\ub2e4. \uc7a5\uc2dd\ub41c \uc120\uc774 \uc788\ub2e4\ub294 \uacb0\uacfc\ub9cc \ubcf4\uae30\ubcf4\ub2e4 \uc11c\ub85c \ub2e4\ub978 \uc7ac\ub8cc\ub97c \ud45c\uba74\uc5d0 \uc815\uad50\ud558\uac8c \ubc30\uce58\ud588\ub2e4\ub294 \uc218\uace0\ub97c \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uaf43\uacfc \ub369\uad74\uc758 \ubc18\ubcf5\uc740 \uae34 \uad00\uc744 \ub530\ub77c \uc2dc\uc120\uc744 \uc6c0\uc9c1\uc774\uac8c \ud55c\ub2e4. \uc18c\ub9ac\ub97c \ub4e3\uae30 \uc804\ubd80\ud130 \ub208\uc73c\ub85c \ub530\ub77c\uac08 \ub9ac\ub4ec\uc774 \uc788\ub294 \uc148\uc774\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4\uc758 \ubc18\uc9dd\uc784\uc744 \uadfc\uac70\ub85c \uc7ac\ub8cc\uc758 \uc815\ud655\ud55c \ube44\uc728\uc774\ub098 \ubaa8\ub4e0 \uac00\uacf5 \ub2e8\uacc4\ub97c \ud310\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubc15\ubb3c\uad00\uc774 \ud655\uc778\ud55c \uae30\ubc95\uacfc \ubb34\ub2ac\ub97c \uae30\uc900\uc73c\ub85c \uc77d\ub294\ub2e4. \uc61b \uc7a5\uc778\uc758 \uae30\uc220\uc774 \uad81\uae08\ud574\uc9c0\ub354\ub77c\ub3c4 \ube44\uc2b7\ud55c \uacf5\uc608\ud488\uc5d0\uc11c \ubcf8 \uacf5\uc815\uc744 \uc774 \ud55c \uc810\uc5d0 \ubaa8\ub450 \ub300\uc785\ud558\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc124\uba85\ub41c \uc0ac\uc2e4\uacfc \uac10\uc0c1\uc758 \ubc94\uc704\ub97c \ub098\ub204\uba74 \ubb3c\uac74\uc774 \ub354 \ub610\ub837\ud574\uc9c4\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc870\uc120\uc2dc\ub300 \ub300\uae08\uc774 \uc81c\ub840\uc545\uacfc \uc5f0\ub840\uc545\uc758 \ud3b8\uc131\uc5d0 \uc4f0\uc600\ub2e4\ub294 \ubc30\uacbd\ub3c4 \uc18c\uac1c\ud55c\ub2e4. \uc74c\uc545\uc774 \uc5b4\ub5a4 \uc790\ub9ac\uc5d0\uc11c \uc5f0\uc8fc\ub418\uc5c8\ub294\uc9c0 \uc54c\uba74 \uc545\uae30\uc758 \uc7a5\uc2dd\uc774 \uc0ac\uce58\ub77c\ub294 \ud55c\ub9c8\ub514\ub85c\ub9cc \uc815\ub9ac\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc758\ub840\uc640 \uc5f0\ud68c\uc5d0\uc11c\ub294 \ub4e3\ub294 \uacbd\ud5d8\ubfd0 \uc544\ub2c8\ub77c \uacf5\uac04\uacfc \uc0ac\ub78c, \ubb3c\uac74\uc774 \ud568\uaed8 \ub9cc\ub4dc\ub294 \uaca9\uc2dd\ub3c4 \uc911\uc694\ud588\uc744 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc774 \ud55c \uc810\uc774 \uc5b4\ub290 \uc758\uc2dd\uc5d0\uc11c \ub204\uad6c\uc758 \uc190\uc5d0 \ub4e4\ub838\ub294\uc9c0\uae4c\uc9c0 \ud655\uc778\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc545\uae30\uc758 \uc77c\ubc18\uc801\uc778 \uc5ed\uc0ac\uc640 \uac1c\ubcc4 \uc720\ubb3c\uc758 \uc0ac\uc6a9 \uc774\ub825\uc740 \ub2e4\ub974\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc74c\uc545\uc744 \uc774\ub8e8\ub294 \ub3c4\uad6c\uac00 \ub3d9\uc2dc\uc5d0 \uacf5\uc608\ud488\uc774\ub77c\ub294 \uc810\uc744 \uc0b4\ud3b4\ubcf8\ub2e4. \uacf5\uc5f0\uc758 \uc18c\ub9ac\uac00 \uc0ac\ub77c\uc9c4 \ub4a4\uc5d0\ub3c4 \uc7ac\ub8cc\uc640 \ubb34\ub2ac\ub294 \ub2f9\uc2dc \uc545\uae30\ub97c \ub300\ud558\ub358 \ud0dc\ub3c4\ub97c \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc0ac\uc9c4\uc5d0\ub294 \uad00\uc758 \ud615\ud0dc\uc640 \ud45c\uba74\uc740 \ub0a8\uc9c0\ub9cc \uc2e4\uc81c \uc74c\uc0c9\uacfc \uc5f0\uc8fc \uc870\uac74\uc740 \ub4e4\ub9ac\uc9c0 \uc54a\ub294\ub2e4. \ubc18\ub300\ub85c \uc545\uae30 \uc18c\ub9ac\ub9cc \ub4e4\uc5b4\uc11c\ub294 \uae08\uc740\uc785\uc0ac\uc758 \uc120\uc744 \uc54c\uc544\ubcfc \uc218 \uc5c6\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc790\ub8cc\uac00 \uc545\uae30\uc758 \ub2e4\ub978 \uba74\uc744 \uc804\ud55c\ub2e4. \uc804\uc2dc \uc0ac\uc9c4\uc744 \ubcf4\uace0 \uc2e4\uc81c \uc5f0\uc8fc \uc790\ub8cc\ub97c \ucc3e\uc544\ubcf4\ub294 \uc77c\uc774 \uc774\uc5b4\uc9c8 \uc218 \uc788\uc9c0\ub9cc \ub458\uc744 \uac19\uc740 \uc815\ubcf4\ub85c \ucde8\uae09\ud558\uc9c0 \uc54a\uc544\uc57c \ud55c\ub2e4. \uc774 \ubb3c\uac74\uc5d0\uc11c \ucd9c\ubc1c\ud574 \ub300\uae08 \uc18c\ub9ac\ub97c \ub4e3\uac8c \ub41c\ub2e4\uba74 \ubc18\uc9dd\uc774\ub294 \ubb34\ub2ac\uac00 \uc5b4\ub5a4 \ud2b9\uc815\ud55c \uc74c\uc744 \ub9cc\ub4e4\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uad6c\uc870\uc640 \uc7a5\uc2dd\uc740 \uad00\uacc4\uac00 \uc788\ub354\ub77c\ub3c4 \uac19\uc740 \uc5ed\ud560\uc744 \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubcf4\uae30\uc640 \ub4e3\uae30\uac00 \uac01\uc790\uc758 \ubaab\uc744 \uac00\uc9c8 \ub54c \uc545\uae30\ub97c \ub9cc\ub098\ub294 \uacbd\ud5d8\uc774 \ub113\uc5b4\uc9c4\ub2e4. \uae38\uac8c \ubed7\uc740 \uad00 \uc704\uc758 \uaf43 \ud55c \uc904\uc774 \uc74c\uc545 \ubc16\uc73c\ub85c\ub3c4 \uc774\uc5b4\uc9c0\ub294 \uc774\uc57c\uae30\ub97c \uc5f4\uc5b4 \uc900\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc870\uc120\uc2dc\ub300 \ub300\uae08\uc774 \uc81c\ub840\uc545\uacfc \uc5f0\ub840\uc545\uc758 \uc5ec\ub7ec \ud3b8\uc131\uc5d0\uc11c \uc5f0\uc8fc\ub418\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4\uc758 \uc774 \uc720\ubb3c\uc774 \uc5b4\ub5a4 \ub0a0 \uc5b4\ub5a4 \uace1\uc744 \uc5f0\uc8fc\ud588\ub294\uc9c0\uae4c\uc9c0 \uc54c\ub824 \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ub298 \uc0ac\uc9c4\uc73c\ub85c \uc54c \uc218 \uc5c6\ub294 \uac83\uc740 \uc2e4\uc81c \uc74c\uc0c9\uc774\ub2e4. \ub300\uc2e0 \ub0a8\uc544 \uc788\ub294 \uac83\uc740 \uae34 \uad00\uacfc \uad6c\uba4d, \uae08\uc18d \ud45c\uba74\uacfc \uc7a5\uc2dd\uc774\ub2e4. \uc74c\uc545\uc744 \ub4e3\uc9c0 \ubabb\ud558\ub294 \uc790\ub9ac\uc5d0\uc11c\ub3c4 \uc545\uae30\ub97c \ubcf4\ub294 \uc7ac\ubbf8\ub294 \uc788\ub2e4. \uc18c\ub9ac\ub97c \ub9cc\ub4e4\ub358 \ubb3c\uac74\uc5d0 \uaf43\uacfc \ud559\uc744 \ub354\ud558\uace0 \uc2f6\uc5c8\ub358 \uc120\ud0dd\uc774 \uadf8 \ud55c \uac00\uc9c0\ub2e4."}, {"id": "metamorphosis-gregor-door-and-family", "title": "\ubcc0\uc2e0 \u2014 \uadf8\ub808\uace0\ub974\uc758 \ubc29\ubb38 \ubc16\uc5d0\uc11c\ub294 \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\uc744\uae4c", "summary": "\uadf8\ub808\uace0\ub974\uc758 \ubc14\ub010 \ubab8\uacfc \ucd9c\uadfc, \uac00\uc871\uc758 \ub3cc\ubd04\uacfc \uace0\ub9bd\uc744 \ub530\ub77c \uacb0\ub9d0\uae4c\uc9c0 \uc791\ud488\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/metamorphosis-gregor-door-and-family/index.html", "image": "../media/metamorphosis-gregor-door-and-family.png", "alt": "\ub2eb\ud78c \ubc29\ubb38 \uc544\ub798\uc758 \ub0af\uc120 \uadf8\ub9bc\uc790\uc640 \uac71\uc815\ud558\ub294 \uac00\uc871\uc744 \uadf8\ub9b0 \ubcc0\uc2e0 \uad00\ub828 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ubcc0\uc2e0 \u2014 \uadf8\ub808\uace0\ub974\uc758 \ubc29\ubb38 \ubc16\uc5d0\uc11c\ub294 \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\uc744\uae4c \ucd9c\uadfc\uacfc \ub3cc\ubd04, \ubc29\uc758 \ubcc0\ud654\uc640 \uc74c\uc545\uc744 \ub530\ub77c \uc77d\ub294 \uce74\ud504\uce74\uc758 \uc911\ud3b8 \uadf8\ub808\uace0\ub974\uc758 \ubc14\ub010 \ubab8\uacfc \ucd9c\uadfc, \uac00\uc871\uc758 \ub3cc\ubd04\uacfc \uace0\ub9bd\uc744 \ub530\ub77c \uacb0\ub9d0\uae4c\uc9c0 \uc791\ud488\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \uc5b4\ub290 \ub0a0 \uc544\uce68 \uadf8\ub808\uace0\ub974 \uc7a0\uc790\ub294 \ub0af\uc120 \uc0dd\ubb3c\uc758 \ubab8\uc73c\ub85c \uae68\uc5b4\ub09c\ub2e4. \uce74\ud504\uce74\uc758 \u300e\ubcc0\uc2e0\u300f\uc5d0\uc11c \uc774 \uc0ac\uac74\uc740 \uc6d0\uc778\uc744 \uc124\uba85\ud558\ub294 \uc218\uc218\uaed8\ub07c\ub85c\ub9cc \ub2e4\ub904\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \ucd9c\uadfc\uacfc \uac00\uc871\uc758 \uc0dd\uacc4, \ub2eb\ud78c \ubb38\uacfc \ubc29\uc758 \uac00\uad6c\uac00 \ub354 \ud070 \ubb38\uc81c\ub85c \ub2e4\uac00\uc628\ub2e4. \uc544\ub798\uc5d0\ub294 \uc791\ud488\uc758 \uc8fc\uc694 \uc0ac\uac74\uacfc \uacb0\ub9d0\uc774 \ud3ec\ud568\ub41c\ub2e4. \uadf8\ub808\uace0\ub974\ub294 \ubab8\uc774 \ub2ec\ub77c\uc84c\ub294\ub370\ub3c4 \uc77c\uacfc \uc5f4\ucc28 \uc2dc\uac04\uc744 \uac71\uc815\ud55c\ub2e4. \ub3c5\uc790\uc5d0\uac8c \uac00\uc7a5 \ub180\ub77c\uc6b4 \uc77c\uc774 \uc778\ubb3c\uc5d0\uac8c\ub294 \ub2f9\uc7a5\uc758 \uc758\ubb34\uc640 \uc5bd\ud78c\ub2e4. \uadf8\ub294 \uac00\uc871\uc744 \ubd80\uc591\ud558\ub294 \uc678\ud310\uc6d0\uc774\uc5c8\ub2e4. \ubab8\uc744 \uc783\uc740 \ucda9\uaca9\uc740 \uc218\uc785\uc744 \uc783\uc744\uc9c0 \ubaa8\ub978\ub2e4\ub294 \ubd88\uc548\uacfc \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\ub2e4. \ud68c\uc0ac\uc5d0\uc11c\ub294 \uc9c0\ubc30\uc778\uc774 \uc9d1\uae4c\uc9c0 \ucc3e\uc544\uc628\ub2e4. \ud55c \ubc88\uc758 \uc9c0\uac01\uc774 \ud574\uba85\ud574\uc57c \ud560 \ubb38\uc81c\ub85c \ucee4\uc9c0\ub294 \ubaa8\uc2b5\uc744 \ubcf4\uba74 \uadf8\ub808\uace0\ub974\uac00 \uc5b4\ub5a4 \uc555\ubc15 \uc18d\uc5d0\uc11c \uc77c\ud588\ub294\uc9c0 \ub4dc\ub7ec\ub09c\ub2e4. \ubcc0\uc2e0 \uc774\uc804\uc758 \uc77c\uc0c1\ub3c4 \ub9c8\uc74c \ud3b8\ud55c \uc0c1\ud0dc\ub294 \uc544\ub2c8\uc5c8\ub2e4. \uae30\uc774\ud55c \uc0ac\uac74\uc774 \uc775\uc219\ud55c \uc0dd\ud65c\uc758 \uc870\uac74\uc744 \ub354 \uc120\uba85\ud558\uac8c \ube44\ucd98\ub2e4. \uadf8\ub808\uace0\ub974\ub294 \uc548\ucabd\uc5d0\uc11c \uc124\uba85\ud558\ub824 \ud558\uc9c0\ub9cc \ubc14\uae65 \uc0ac\ub78c\ub4e4\uc740 \uadf8\uc758 \ub9d0\uc744 \uc81c\ub300\ub85c \uc54c\uc544\ub4e3\uc9c0 \ubabb\ud55c\ub2e4. \uc2a4\uc2a4\ub85c \ub290\ub07c\ub294 \ub9c8\uc74c\uacfc \ub0a8\ub4e4\uc774 \ub4e3\ub294 \uc18c\ub9ac\uac00 \uac08\ub77c\uc9c4\ub2e4. \ubb38\uc744 \uc5f0\ub2e4\ub294 \ubb3c\ub9ac\uc801\uc778 \ud589\ub3d9\uc774 \uad00\uacc4\ub97c \ub2e4\uc2dc \uc5f0\uacb0\ud574 \uc8fc\uc9c0\ub294 \ubabb\ud55c\ub2e4. \uac00\uc871\uacfc \ud68c\uc0ac \uc0ac\ub78c\uc740 \ub208\uc55e\uc758 \ubab8\uc744 \ubcf4\uace0 \ubc18\uc751\ud55c\ub2e4. \ub3c5\uc790\ub294 \uadf8\uc758 \uc0dd\uac01\uc744 \ub530\ub77c\uac08 \uc218 \uc788\uae30 \ub54c\ubb38\uc5d0 \uadf8 \ubab8\ub9cc \ubcf4\ub294 \uc0ac\ub78c\ub4e4\uacfc \ub2e4\ub978 \uc815\ubcf4\ub97c \uac16\ub294\ub2e4. \uc791\ud488\uc740 \ub204\uad6c\ub97c \uc774\ud574\ud560 \ub54c \ubb34\uc5c7\uc744 \uadfc\uac70\ub85c \ud310\ub2e8\ud558\ub294\uc9c0 \ubb3b\uac8c \ud55c\ub2e4. \uc778\uac04\uc801\uc778 \ub9c8\uc74c\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uace7\ubc14\ub85c \uc804\ub2ec\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ucc98\uc74c\uc5d0 \uc5ec\ub3d9\uc0dd \uadf8\ub808\ud14c\ub294 \uba39\uc744 \uac83\uc744 \uac00\uc838\uc624\uace0 \ubc29\uc744 \uc0b4\ud540\ub2e4. \uadf8\ub294 \uc74c\uc2dd\uc758 \ucde8\ud5a5\uacfc \uc6c0\uc9c1\uc784\uc774 \uc774\uc804\uacfc \ub2ec\ub77c\uc84c\uc9c0\ub9cc \uc5ec\uc804\ud788 \uac00\uc871\uc5d0\uac8c \ub9c8\uc74c\uc744 \uc4f4\ub2e4. \ub3cc\ubd04\uc758 \uc7a5\uba74\uc740 \ud610\uc624\uc640 \uc5f0\ubbfc, \ubc30\ub824\uc640 \ub450\ub824\uc6c0\uc774 \ub2e8\uc21c\ud558\uac8c \ub098\ub258\uc9c0 \uc54a\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ud558\uc9c0\ub9cc \ub3cc\ubd04\uc740 \uacc4\uc18d \uc2dc\uac04\uacfc \ub178\ub3d9\uc744 \uc694\uad6c\ud55c\ub2e4. \uac00\uc871\uc758 \uc0dd\uacc4\ub3c4 \ubc14\ub00c\uba74\uc11c \uadf8\ub808\ud14c\uc758 \ud0dc\ub3c4\ub294 \ub2ec\ub77c\uc9c4\ub2e4. \ucc98\uc74c \ud55c \ubc88 \ub3c4\uc640\uc8fc\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc624\ub798 \uad00\uacc4\ub97c \uc720\uc9c0\ud560 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uac19\uc9c0 \uc54a\ub2e4. \uc791\ud488\uc740 \uac00\uc871\uc758 \uc0ac\ub791\uc744 \uc120\uc5b8\ubcf4\ub2e4 \ubc18\ubcf5\ub418\ub294 \ud589\ub3d9\uacfc \ubd80\ub2f4 \uc18d\uc5d0\uc11c \ubcf4\uc5ec \uc900\ub2e4. \uadf8\ub808\uace0\ub974\uac00 \uc6c0\uc9c1\uc774\uae30 \ud3b8\ud558\uac8c \ubc29\uc758 \uac00\uad6c\ub97c \uce58\uc6b0\ub824\ub294 \uc77c\uc774 \ubc8c\uc5b4\uc9c4\ub2e4. \uadf8\ub7ec\ub098 \ubb3c\uac74\uc740 \uc7a5\uc560\ubb3c\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uc608\uc804 \uc0dd\ud65c\uacfc \uc790\uae30 \ubaa8\uc2b5\uc744 \uae30\uc5b5\ud558\uac8c \ud558\ub294 \ud754\uc801\uc774\uae30\ub3c4 \ud558\ub2e4. \uacf5\uac04\uc744 \ud3b8\ud558\uac8c \ub9cc\ub4dc\ub294 \ud310\ub2e8\uc774 \ub2f9\uc0ac\uc790\uc5d0\uac8c\ub294 \uc0b6\uc758 \uc77c\ubd80\ub97c \uc5c6\uc560\ub294 \uc77c\ub85c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uadf8\uac00 \uc9c0\ud0a4\ub824 \ud558\ub294 \uadf8\ub9bc\ub3c4 \uc774\ub7f0 \ub9e5\ub77d\uc5d0\uc11c \ubcfc \uc218 \uc788\ub2e4. \ub0a8\ub4e4\uc774 \ubcf4\uae30\uc5d0\ub294 \ub0a1\uc740 \ubb3c\uac74\uc774\uc9c0\ub9cc \uadf8\uc5d0\uac8c\ub294 \ubc29\uc774 \uc544\uc9c1 \uc790\uae30\uc758 \uacf5\uac04\uc774\ub77c\ub294 \ud45c\uc9c0\uac00 \ub41c\ub2e4. \uc0c1\ub300\ub97c \uc704\ud55c\ub2e4\uace0 \uc0dd\uac01\ud55c \ud589\ub3d9\uacfc \uc0c1\ub300\uac00 \uc2e4\uc81c\ub85c \ubc14\ub77c\ub294 \uac83\uc774 \uac19\uc9c0 \uc54a\uc740 \uc7a5\uba74\uc774\ub2e4. \uc544\ubc84\uc9c0\ub294 \uadf8\ub808\uace0\ub974\ub97c \uc704\ud611\ud558\uace0 \uc0ac\uacfc\ub97c \ub358\uc9c4\ub2e4. \uadf8\uc911 \ud558\ub098\uac00 \ubab8\uc5d0 \ubc15\ud600 \uc0c1\ucc98\uac00 \ub0a8\ub294\ub2e4. \uc9d1\uc740 \ubcf4\ud638\ubc1b\ub294 \uc7a5\uc18c\uc774\uba74\uc11c \uc704\ud5d8\uc774 \uc0dd\uae30\ub294 \uacf3\uc774 \ub41c\ub2e4. \ubab8\uc758 \uace0\ud1b5\uacfc \uad00\uacc4\uc758 \uace0\ub9bd\uc774 \ud568\uaed8 \uae4a\uc5b4\uc9c4\ub2e4. \uac00\uc871\uc740 \uac01\uc790 \uc77c\uc744 \ud558\uba70 \uc0dd\uacc4\ub97c \ub2e4\uc2dc \uafb8\ub9ac\uae30 \uc2dc\uc791\ud55c\ub2e4. \uadf8\ub808\uace0\ub974\uac00 \uc0dd\uac01\ud588\ub358 \uac00\uc871\uc758 \ubb34\ub2a5\ub825\uacfc \uc2e4\uc81c \uac00\ub2a5\ud55c \uc77c \uc0ac\uc774\uc5d0\ub3c4 \ucc28\uc774\uac00 \ubcf4\uc778\ub2e4. \ub3d9\uc2dc\uc5d0 \uadf8\uc758 \ubc29\uc740 \uc810\uc810 \ubd88\ud544\uc694\ud55c \ubb3c\uac74\uc744 \ub450\ub294 \uacf3\ucc98\ub7fc \ubcc0\ud55c\ub2e4. \ud55c \uc0ac\ub78c\uc758 \uc790\ub9ac\uac00 \uc0dd\ud65c \uacf5\uac04 \uc548\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ubc00\ub824\ub098\ub294\uc9c0\uac00 \uad6c\uccb4\uc801\uc778 \ubc30\uce58\ub85c \ub4dc\ub7ec\ub09c\ub2e4. \uc9d1\uc5d0 \uba38\ubb34\ub294 \ud558\uc219\uc778\ub4e4 \uc55e\uc5d0\uc11c \uadf8\ub808\ud14c\uac00 \ubc14\uc774\uc62c\ub9b0\uc744 \ucf20\ub2e4. \uadf8\ub808\uace0\ub974\ub294 \uadf8 \uc18c\ub9ac\uc5d0 \ub04c\ub824 \ub098\uc628\ub2e4. \uc790\uc2e0\uc774 \ub3d9\uc0dd\uc758 \uc74c\uc545\uc744 \uc774\ud574\ud558\uace0 \uac00\uae4c\uc774\ud558\uace0 \uc2f6\uc5b4 \ud55c\ub2e4\ub294 \ub9c8\uc74c\uc774 \ub0a8\uc544 \uc788\ub2e4. \uac89\uc758 \ubab8\uacfc \uc548\uc758 \ubc18\uc751\uc774 \uac19\uc740 \uc18d\ub3c4\ub85c \ubc14\ub00c\uc9c0 \uc54a\uc558\ub2e4. \uadf8\ub7ec\ub098 \uadf8\uc758 \ub4f1\uc7a5\uc740 \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uc704\ud611\uacfc \uace8\uce6b\uac70\ub9ac\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc9c4\ub2e4. \uadf8\ub808\ud14c\ub294 \uc774\uc81c \uc774 \uc874\uc7ac\ub97c \uc608\uc804\uc758 \uc624\ube60\uc640 \uc5f0\uacb0\ud574 \uacc4\uc18d \ubc1b\uc544\ub4e4\uc774\uc9c0 \ubabb\ud558\uaca0\ub2e4\uace0 \ub9d0\ud55c\ub2e4. \uadf8\ub808\uace0\ub974\ub294 \ubc29\uc73c\ub85c \ub3cc\uc544\uac00\uace0 \uacb0\uad6d \uc8fd\ub294\ub2e4. \uac00\uc871\uc740 \uadf8 \ub4a4 \uc55e\uc73c\ub85c\uc758 \uc0dd\ud65c\uc744 \uc0dd\uac01\ud558\uba70 \uc9d1 \ubc16\uc73c\ub85c \ub098\uac04\ub2e4. \uadf8\ub808\uace0\ub974\ub294 \ub3d9\uc0dd\uc774 \uc74c\uc545\uc744 \ub354 \ubc30\uc6b8 \uc218 \uc788\uac8c \ub3d5\uace0 \uc2f6\uc5c8\ub358 \ub9c8\uc74c\uc744 \ud488\uace0 \uc788\ub2e4. \uc774\ub7f0 \uc0dd\uac01\uc740 \uadf8\uc758 \ubab8\uc774 \ubcc0\ud55c \ub4a4\uc5d0\ub3c4 \uc774\uc5b4\uc9c4\ub2e4. \uc790\uc2e0\uc744 \uc54c\uc544\ubcf4\uc9c0 \ubabb\ud558\ub294 \uac00\uc871\uc744 \ud5a5\ud55c \uad00\uacc4\uac00 \uadf8\uc758 \uc548\uc5d0\uc11c\ub294 \uc27d\uac8c \ub04a\uc5b4\uc9c0\uc9c0 \uc54a\uc558\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uadf8\ub7ec\ub098 \uc18d\uc73c\ub85c \uac04\uc9c1\ud55c \uacc4\ud68d\uacfc \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc2e4\uc81c\ub85c \ub4e3\ub294 \ub9d0\uc740 \ub2e4\ub974\ub2e4. \ubc14\uc774\uc62c\ub9b0\uc758 \uc18c\ub9ac\ub294 \uc5b8\uc5b4\uac00 \ud1b5\ud558\uc9c0 \uc54a\ub294 \uc778\ubb3c\uc744 \uc6c0\uc9c1\uc778\ub2e4. \uac00\uc871\uacfc \ud558\uc219\uc778\ub4e4\uc740 \ub2e4\ub978 \uae30\uc900\uc73c\ub85c \uc7a5\uba74\uc744 \ud3c9\uac00\ud558\uc9c0\ub9cc \ub3c5\uc790\ub294 \uadf8\uac00 \uc74c\uc545\uc744 \ud5a5\ud574 \ub2e4\uac00\uac00\ub294 \ub9c8\uc74c\uc744 \uc548\ub2e4. \uadf8\ub798\uc11c \ubc29\uc5d0\uc11c \ub098\uc628 \ud589\ub3d9\uc744 \ub2e8\uc21c\ud55c \ubc29\ud574\ub85c\ub9cc \ubcfc \uc218 \uc5c6\ub2e4. \ubab8\uc758 \ub0af\uc126\uc774 \ubcf4\uc774\ub294 \uad00\uac1d\uacfc \uc548\uc758 \uc0dd\uac01\uae4c\uc9c0 \uc544\ub294 \ub3c5\uc790 \uc0ac\uc774\uc5d0 \uac70\ub9ac\uac00 \uc0dd\uae34\ub2e4. \uc791\ud488\uc740 \uadf8 \uac04\uaca9\uc744 \uc720\uc9c0\ud55c \ucc44 \ub9c8\uc9c0\ub9c9 \uc7a5\uba74\uc73c\ub85c \uac04\ub2e4. \ub204\uad70\uac00\ub97c \uc548\ub2e4\uace0 \ub9d0\ud560 \ub54c \ubcf4\uc774\ub294 \ubaa8\uc2b5\uacfc \ub4e4\ub9ac\uc9c0 \uc54a\uc740 \ub9c8\uc74c \uc911 \ubb34\uc5c7\uc744 \ub193\ucce4\ub294\uc9c0 \uc9c8\ubb38\ud558\uac8c \ud55c\ub2e4. \ubcc0\uc2e0\uc758 \uc815\ud655\ud55c \uc6d0\uc778\uc744 \uc124\uba85\ud558\uc9c0 \uc54a\ub294 \uacb0\ub9d0\uc740 \ub3c5\uc790\ub97c \ubd88\ud3b8\ud558\uac8c \ud560 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc791\ud488\uc774 \ubcf4\uc5ec \uc900 \ucd9c\uadfc\uc758 \uc555\ubc15\uacfc \ub3cc\ubd04, \ubc29\uc758 \ubcc0\ud654\ub294 \uad6c\uccb4\uc801\uc774\ub2e4. \uc6d0\uc778\uc744 \ud478\ub294 \ub370\ub9cc \uc9d1\uc911\ud558\uba74 \uadf8 \ub4a4\uc5d0 \ubc8c\uc5b4\uc9c4 \uc77c\ub4e4\uc758 \ubb34\uac8c\ub97c \ub193\uce5c\ub2e4. \uce74\ud504\uce74\ub294 \ud504\ub77c\ud558\uc5d0\uc11c \ub3c5\uc77c\uc5b4\ub85c \uae00\uc744 \uc4f4 \uc791\uac00\ub2e4. \uc774 \uae00\uc740 \uadf8 \ub3c4\uc2dc\uc640 \uc791\uac00\uc758 \ub9e5\ub77d\uc73c\ub85c \uccb4\ucf54\uc5d0 \ubc30\uce58\ud558\ub418 \uc791\ud488\uc744 \ud55c \uad6d\uac00\uc758 \uc131\uaca9\uc73c\ub85c \uc77c\ubc18\ud654\ud558\uc9c0 \uc54a\ub294\ub2e4. \u300e\ubcc0\uc2e0\u300f\uc740 \uc4f8\ubaa8\ub97c \uc81c\uacf5\ud558\uc9c0 \ubabb\ud560 \ub54c\ub3c4 \ud55c \uc0ac\ub78c\uc744 \uac19\uc740 \uc874\uc7ac\ub85c \ub300\ud560 \uc218 \uc788\ub294\uc9c0 \ubb3b\ub294 \ub0af\uc120 \uac00\uc871 \uc774\uc57c\uae30\ub85c \ub0a8\ub294\ub2e4."}, {"id": "michelangelo-david-marble-and-republic", "title": "\ubbf8\ucf08\ub780\uc824\ub85c\uc758 \ub2e4\ube44\ub4dc \u2014 \ub3cc \uc18d\uc758 \uccad\ub144\uc740 \ubb34\uc5c7\uc744 \uae30\ub2e4\ub9b4\uae4c", "summary": "\ub300\ub9ac\uc11d\uc758 \uc81c\uc57d\uacfc \uc778\uccb4\uc758 \uae34\uc7a5, \ud53c\ub80c\uccb4 \uacf5\uacf5 \uc124\uce58\uc640 \uc6d0\uc791 \ubcf4\uc874\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/michelangelo-david-marble-and-republic/index.html", "image": "../media/michelangelo-david-marble-and-republic.jpg", "alt": "\ubbf8\ucf08\ub780\uc824\ub85c \ub2e4\ube44\ub4dc\uc0c1\uc758 \uc804\uc2e0\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc5ed\uc0ac \ucd9c\ud310 \ub3c4\ud310", "text": "\ubbf8\ucf08\ub780\uc824\ub85c\uc758 \ub2e4\ube44\ub4dc \u2014 \ub3cc \uc18d\uc758 \uccad\ub144\uc740 \ubb34\uc5c7\uc744 \uae30\ub2e4\ub9b4\uae4c \ubc84\ub824\uc9c4 \ub3cc\uc744 \ub9e1\uc740 \uc80a\uc740 \uc870\uac01\uac00\uc5d0\uc11c \uc2dc\uc791\ud558\ub294 \uc5ed\uc0ac\uc640 \uc791\ud488 \uc77d\uae30 \ub300\ub9ac\uc11d\uc758 \uc81c\uc57d\uacfc \uc778\uccb4\uc758 \uae34\uc7a5, \ud53c\ub80c\uccb4 \uacf5\uacf5 \uc124\uce58\uc640 \uc6d0\uc791 \ubcf4\uc874\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \ud53c\ub80c\uccb4\uc758 \ub2e4\ube44\ub4dc\uc0c1\uc740 \uc2b9\ub9ac\ud55c \uc601\uc6c5\uc758 \uae30\ub150\uc0ac\uc9c4\ucc98\ub7fc \uc11c \uc788\uc9c0 \uc54a\ub2e4. \ucee4\ub2e4\ub780 \uccad\ub144\uc740 \uace0\uac1c\ub97c \ub3cc\ub9ac\uace0 \uc5b4\ub518\uac00\ub97c \ubc14\ub77c\ubcf8\ub2e4. \ubab8\uc740 \uba48\ucd94\uc5b4 \uc788\ub294\ub370 \uc2dc\uc120\uc5d0\ub294 \uae34\uc7a5\uc774 \uc788\ub2e4. \ubbf8\ucf08\ub780\uc824\ub85c\uac00 \uc131\uc11c\uc758 \uc778\ubb3c\uc744 \uc870\uac01\ud55c \uc774 \uc791\ud488\uc740 \uc778\uac04\uc758 \ubab8\uc744 \ubc14\ub77c\ubcf4\ub294 \ubc29\ubc95\uacfc \ub3c4\uc2dc\uc758 \uc815\uce58\uac00 \ub9cc\ub09c \uc790\ub9ac\uc774\uae30\ub3c4 \ud558\ub2e4. 1501\ub144 \ubbf8\ucf08\ub780\uc824\ub85c\ub294 \uc774\ubbf8 \ub2e4\ub978 \uc870\uac01\uac00\uc758 \uc791\uc5c5\uc774 \uc2dc\ub3c4\ub418\uc5c8\ub358 \ud070 \ub300\ub9ac\uc11d\uc744 \ub9e1\uc558\ub2e4. \uc0c8 \ub3cc\uc744 \uc6d0\ud558\ub294 \ubaa8\uc591\uc73c\ub85c \uc798\ub77c \ub098\uac00\ub294 \uc77c\uacfc \ub2ec\ub9ac, \ub0a8\uc740 \ub3cc\uc758 \uc870\uac74\uc744 \ubc1b\uc544\ub4e4\uc774\uba70 \ud615\uc0c1\uc744 \ucc3e\uc544\uc57c \ud588\ub2e4. \uc624\ub298\uc758 \uc644\uc131\ub41c \ubab8\ub9cc \ubcf4\uba74 \uc81c\uc791\uc758 \ucd9c\ubc1c\uc810\uc5d0 \uc788\ub358 \uc81c\uc57d\uc744 \uc78a\uae30 \uc27d\ub2e4. \uadf8\ub294 \ud53c\uc5d0\ud0c0\ub85c \uc774\ub984\uc744 \uc54c\ub9b0 \uc80a\uc740 \uc870\uac01\uac00\uc600\ub2e4. \ub2e4\ube44\ub4dc \uc81c\uc791\uc740 \uc544\ub984\ub2e4\uc6b4 \uc778\uccb4\ub97c \ub9cc\ub4dc\ub294 \ubb38\uc81c\uc5d0 \ub354\ud574, \uc624\ub798 \ud574\uacb0\ub418\uc9c0 \ubabb\ud55c \uac70\ub300\ud55c \ub3cc\uc744 \uc644\uc131\ud560 \uc218 \uc788\ub294\uac00 \ud558\ub294 \uc2dc\ud5d8\uc774\uc5c8\ub2e4. \uc870\uac01\uc740 \uc5c6\ub294 \uac83\uc744 \ub367\ubd99\uc774\ub294 \ub300\uc2e0 \ub0a8\uae38 \ubd80\ubd84\uc744 \uacb0\uc815\ud558\ub294 \uc791\uc5c5\uc774\ub77c\ub294 \uc0ac\uc2e4\uc774 \uc774 \ucd9c\ubc1c\uc810\uc5d0\uc11c \uc120\uba85\ud574\uc9c4\ub2e4. \ub2e4\uc717\uc740 \uac70\uc778 \uace8\ub9ac\uc557\uc5d0 \ub9de\uc120 \uc131\uc11c\uc758 \uc778\ubb3c\uc774\ub2e4. \uc774\uc57c\uae30\ub97c \uc870\uac01\uc73c\ub85c \uc62e\uae38 \ub54c \uc791\uac00\ub294 \uc5b4\ub290 \uc21c\uac04\uc744 \ubcf4\uc5ec \uc904\uc9c0 \uc815\ud574\uc57c \ud55c\ub2e4. \uc801\uc758 \uba38\ub9ac\ub098 \uc2b9\ub9ac\uc758 \uc804\ub9ac\ud488\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ubc29\ubc95\ub3c4 \uc788\uc9c0\ub9cc, \ubbf8\ucf08\ub780\uc824\ub85c\uc758 \ub2e4\ube44\ub4dc\ub294 \uc2f8\uc6c0\uc5d0 \uc55e\uc120 \uc9d1\uc911\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc5b4\uae68\uc5d0 \uac78\uce5c \ubb3c\ub9e4\uc640 \uc190\uc758 \uc791\uc740 \uc900\ube44\ub294 \uac70\ub300\ud55c \uadfc\uc721\ubcf4\ub2e4 \uc870\uc6a9\ud558\ub2e4. \uad00\uac1d\uc740 \ub208\uc55e\uc5d0 \uc5c6\ub294 \uc0c1\ub300\ub97c \uc0c1\uc0c1\ud558\uac8c \ub41c\ub2e4. \uc0c1\ub300\ub97c \uc9c1\uc811 \ub9cc\ub4e4\uc9c0 \uc54a\uace0\ub3c4 \uc0c1\ub300\uac00 \uc788\ub2e4\ub294 \ub290\ub08c\uc744 \uc804\ub2ec\ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c, \uc774 \uc870\uac01\uc758 \uae34\uc7a5\uc740 \ubab8 \uc548\uc5d0\ub9cc \uba38\ubb3c\uc9c0 \uc54a\ub294\ub2e4. \uc815\uba74\uc5d0\uc11c \ubcf4\uba74 \ub450 \ub2e4\ub9ac\ub294 \uac19\uc740 \uc77c\uc744 \ud558\uc9c0 \uc54a\ub294\ub2e4. \ud55c\ucabd\uc740 \ubb34\uac8c\ub97c \uc9c0\ud0f1\ud558\uace0 \ub2e4\ub978 \ucabd\uc740 \uc0c1\ub300\uc801\uc73c\ub85c \ud480\ub824 \uc788\ub2e4. \uace8\ubc18\uacfc \uc5b4\uae68\uc758 \uad00\uacc4\ub3c4 \uc644\uc804\ud55c \uc88c\uc6b0 \ub300\uce6d\uc5d0\uc11c \ubc97\uc5b4\ub09c\ub2e4. \uace0\ub300 \uc870\uac01\uc758 \uc804\ud1b5\uacfc \uc5f0\uacb0\ub418\ub294 \uc774\ub7f0 \uc790\uc138\ub294 \uc11c \uc788\ub294 \ubab8\uc5d0 \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \uade0\ud615\uacfc \uc7a0\uc7ac\uc801\uc778 \uc6c0\uc9c1\uc784\uc744 \uc900\ub2e4. \uace0\uac1c\uac00 \ub3cc\uc544\uac04 \ubc29\ud5a5\uacfc \uc190\uc758 \uc704\uce58\ub97c \ud568\uaed8 \uc0b4\ud53c\uba74 \ubab8\uc774 \ub2e8\uc21c\ud788 \ud3b8\uc548\ud558\uac8c \uc26c\ub294 \uc0c1\ud0dc\uac00 \uc544\ub2d8\uc744 \uc54c \uc218 \uc788\ub2e4. \ub2e4\uac00\uac00\uc11c \ud45c\uba74\ub9cc \ubcf4\uae30\ubcf4\ub2e4 \uc870\uae08 \ub5a8\uc5b4\uc838 \ubab8 \uc804\uccb4\uc758 \ubb34\uac8c\uac00 \uc5b4\ub514\uc5d0 \ub193\uc774\ub294\uc9c0 \ubcf4\ub294 \ud3b8\uc774 \uc88b\ub2e4. \ud55c \ub369\uc5b4\ub9ac\uc758 \ub3cc\uc774 \uade0\ud615\uc744 \uc7a1\ub294 \uc0ac\ub78c\uc73c\ub85c \uc77d\ud788\uae30 \uc2dc\uc791\ud55c\ub2e4. \uc190\ub4f1\uacfc \uc190\uac00\ub77d\uc740 \uc720\ub09c\ud788 \uc2dc\uc120\uc744 \ub048\ub2e4. \uba38\ub9ac\uc640 \uc190\uc758 \ube44\ub840\ub97c \ub450\uace0\ub3c4 \uc5ec\ub7ec \uc124\uba85\uc774 \uc81c\uc2dc\ub418\uc5b4 \uc654\ub2e4. \ucc98\uc74c \uacc4\ud68d\ub41c \ub192\uc740 \uc124\uce58 \uc704\uce58\ub97c \uc0dd\uac01\ud560 \uc218 \uc788\uc9c0\ub9cc, \ubaa8\ub4e0 \ud2b9\uc9d5\uc744 \ud558\ub098\uc758 \uacc4\uc0b0 \uacf5\uc2dd\uc73c\ub85c \ub2e8\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uad00\uac1d\uc774 \uc2e4\uc81c\ub85c \ubcf4\uac8c \ub418\ub294 \uac83\uc740 \ud310\ub2e8\ud558\uace0 \ud589\ub3d9\ud560 \uc218 \uc788\ub294 \ubab8\uc758 \uac15\uc870\ub2e4. \uc774\ub9c8\uc640 \ub208 \uc8fc\ubcc0\uc758 \uae34\uc7a5\ub3c4 \uc911\uc694\ud558\ub2e4. \uc544\ub984\ub2e4\uc6c0\uc740 \uadfc\uc721\uc774 \ub9e4\ub048\ud558\ub2e4\ub294 \uc0ac\uc2e4\uc5d0\ub9cc \uc788\uc9c0 \uc54a\ub2e4. \uc704\ud5d8\uc744 \uc54c\uc544\ubcf4\uace0 \uacb0\uc815\uc744 \uc55e\ub454 \uc815\uc2e0\uc758 \uc0c1\ud0dc\uac00 \uc5bc\uad74\uacfc \uc790\uc138\uc5d0 \uc5f0\uacb0\ub41c\ub2e4. \ud798\uc774 \ub9ce\uc544 \ubcf4\uc774\ub294 \uc778\ubb3c\uacfc \ud798\uc744 \uc5b4\ub5bb\uac8c \uc4f8\uc9c0 \uc0dd\uac01\ud558\ub294 \uc778\ubb3c \uc0ac\uc774\uc5d0\ub294 \ucc28\uc774\uac00 \uc788\ub2e4. \uc131\uc11c\uc758 \uc774\uc57c\uae30\ub97c \uc54c\uace0 \ubcf4\uba74 \uc791\uc740 \ubb34\uae30\uac00 \ud2b9\ud788 \uc758\ubbf8 \uc788\uac8c \ubcf4\uc778\ub2e4. \uc555\ub3c4\uc801\uc778 \uc0c1\ub300\uc5d0 \ub9de\uc11c\ub294 \ub370 \ud544\uc694\ud55c \uac83\uc740 \ubab8\uc9d1\uc758 \ud06c\uae30\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc870\uac01\uc740 \uadfc\uc721\uc774 \ud070 \uc778\uccb4\ub97c \ubcf4\uc5ec \uc8fc\uba74\uc11c\ub3c4 \ud310\ub2e8\uacfc \uc9d1\uc911\uc774\ub77c\ub294 \ub2e4\ub978 \ud798\uc744 \ud568\uaed8 \uac15\uc870\ud55c\ub2e4. \uc774 \ub450 \uc694\uc18c\ub97c \uc5b4\ub290 \ud55c\ucabd\uc73c\ub85c\ub9cc \uc77d\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uacf5\uacf5\uc7a5\uc18c\uc758 \uc791\ud488\uc740 \uc138\uc6cc\uc9c0\ub294 \uc21c\uac04 \uc758\ubbf8\uac00 \uc644\uc131\ub418\uc9c0 \uc54a\ub294\ub2e4. \uac00\uae4c\uc774 \uc9c0\ub098\uac00\ub294 \uc2dc\ubbfc\uacfc \uba40\ub9ac\uc11c \ucc3e\uc544\uc624\ub294 \ubc29\ubb38\uac1d, \uc870\uac01\uc744 \ubcf4\ud638\ud558\ub824\ub294 \uc0ac\ub78c\uc740 \uc11c\ub85c \ub2e4\ub978 \uad00\uacc4\ub97c \ub9fa\ub294\ub2e4. \ub2e4\ube44\ub4dc\uc758 \uc5ed\uc0ac\uc5d0\ub294 \uc81c\uc791 \uc5f0\ub3c4 \uc774\ud6c4\uc758 \uc774\ub7f0 \ub9cc\ub0a8\ub3c4 \ud3ec\ud568\ub41c\ub2e4. \uc791\ud488\uc740 \ud53c\ub80c\uccb4 \ub300\uc131\ub2f9\uacfc \uad00\ub828\ub41c \uc0ac\uc5c5\uc5d0\uc11c \ucd9c\ubc1c\ud588\uc9c0\ub9cc, \uc644\uc131 \ub4a4\uc5d0\ub294 \uc2dc\uccad\uc774 \uc788\ub294 \uc2dc\ub1e8\ub9ac\uc544 \uad11\uc7a5\uc5d0 \uc138\uc6cc\uc84c\ub2e4. \uc5b4\ub514\uc5d0 \ub193\uc774\ub294\uac00\uc5d0 \ub530\ub77c \uc791\ud488\uc744 \uc77d\ub294 \uc0ac\ub78c\uacfc \uc758\ubbf8\ub3c4 \ub2ec\ub77c\uc84c\ub2e4. \ub192\uc740 \uac74\ucd95\uc758 \uc77c\ubd80\ub85c \ubcfc \ub54c\uc640 \uc2dc\ubbfc\uc774 \uc624\uac00\ub294 \uc815\uce58\uc801 \uacf5\uac04\uc5d0\uc11c \ubcfc \ub54c\ub294 \uacbd\ud5d8\uc774 \uac19\uc744 \uc218 \uc5c6\ub2e4. \uac15\ud55c \uc801\uc5d0 \ub9de\uc11c\ub294 \uccad\ub144\uc740 \ud53c\ub80c\uccb4 \uacf5\ud654\uad6d\uc758 \uc790\uc728\uc131\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc77d\ud790 \uc218 \uc788\uc5c8\ub2e4. \uc131\uc11c\uc758 \uc774\uc57c\uae30\uac00 \ub3c4\uc2dc\uc758 \ud604\uc7ac\ub97c \ub9d0\ud558\ub294 \uc5b8\uc5b4\uac00 \ub41c \uac83\uc774\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \uc2dc\ubbfc\uc774 \uac19\uc740 \ub73b\uc73c\ub85c \uc774\ud574\ud588\ub2e4\uace0 \ub2e8\uc815\ud558\uae30\ubcf4\ub2e4, \uacf5\uacf5\uc7a5\uc18c\uc758 \uc870\uac01\uc774 \uc5ec\ub7ec \uc815\uce58\uc801 \ud574\uc11d\uc744 \ubaa8\uc73c\ub294 \uacfc\uc815\uc744 \uc0dd\uac01\ud558\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \uc9c0\uae08 \uad11\uc7a5\uc5d0\uc11c \ub9cc\ub098\ub294 \ub2e4\ube44\ub4dc\ub294 \uc6d0\uc791\uacfc \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc6d0\uc791\uc740 \ubcf4\ud638\ub97c \uc704\ud574 19\uc138\uae30\uc5d0 \uc544\uce74\ub370\ubbf8\uc544\ub85c \uc62e\uaca8\uc84c\ub2e4. \uad11\uc7a5\uc5d0\uc11c\ub294 \ub3c4\uc2dc\uc640 \uc870\uac01\uc758 \uad00\uacc4\ub97c, \ubbf8\uc220\uad00\uc5d0\uc11c\ub294 \uc2e4\uc81c \ub300\ub9ac\uc11d\uc758 \ud45c\uba74\uacfc \uaddc\ubaa8\ub97c \uc11c\ub85c \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uacbd\ud5d8\ud558\uac8c \ub41c\ub2e4. \ubcf5\uc81c\ud488\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc6d0\uc791\uc758 \uac00\uce58\ub97c \uc5c6\uc560\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc624\ud788\ub824 \uc678\ubd80 \ud658\uacbd\uc5d0\uc11c \uc791\ud488\uc744 \uc9c0\ud0a4\ub294 \uc77c\uacfc \uc6d0\ub798 \uc7a5\uc18c\uc758 \uae30\uc5b5\uc744 \uc720\uc9c0\ud558\ub294 \uc77c\uc774 \uc5b4\ub5bb\uac8c \ud568\uaed8 \uac00\ub2a5\ud55c\uc9c0 \ubcf4\uc5ec \uc900\ub2e4. \uc0ac\uc9c4\uc744 \ubcfc \ub54c\ub3c4 \uc5b4\ub290 \uc7a5\uc18c\uc758 \uc5b4\ub290 \uc870\uac01\uc778\uc9c0 \ud655\uc778\ud558\uba74 \uc124\uba85\uacfc \uc774\ubbf8\uc9c0\ub97c \ud63c\ub3d9\ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \ub2e4\ube44\ub4dc\ub97c \ubcfc \ub54c\uc5d0\ub294 \ubc1c\uc5d0\uc11c \uc2dc\uc791\ud574 \ubb34\uac8c\ub97c \ub530\ub77c \uc62c\ub77c\uac00\uace0, \uc190\uc744 \ubcf8 \ub4a4 \ub9c8\uc9c0\ub9c9\uc73c\ub85c \ub208\uc758 \ubc29\ud5a5\uc744 \ub530\ub77c\uac00 \ubcf4\uc790. \uc774 \uc21c\uc11c\ub294 \ubab8\uacfc \ub9c8\uc74c\uc744 \ub530\ub85c \ub5bc\uc9c0 \uc54a\uace0 \uc77d\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ub208\uc55e\uc5d0 \uc5c6\ub294 \uc2f8\uc6c0\uc774 \ub3cc\uc758 \ud45c\uba74\uc744 \ud1b5\ud574 \uc11c\uc11c\ud788 \ub098\ud0c0\ub09c\ub2e4. \uc791\ud488\uc740 \uc131\uc11c \uc778\ubb3c\uc758 \uc124\uba85\uc744 \ub118\uc5b4\uc120\ub2e4. \uc81c\uc57d\uc774 \uc788\ub358 \uc7ac\ub8cc\ub97c \ub9e1\uc740 \uc870\uac01\uac00\uc758 \uc120\ud0dd, \uad11\uc7a5\uc5d0 \ub193\uc740 \ub3c4\uc2dc\uc758 \uacb0\uc815, \uc624\ub298 \uc6d0\uc791\uc744 \ubcf4\uc874\ud558\ub294 \uc81c\ub3c4\uac00 \uacb9\uccd0 \uc788\ub2e4. \ub2e4\ube44\ub4dc\ub294 \uc624\ub798 \uc0b4\uc544\ub0a8\uc740 \uc544\ub984\ub2e4\uc6b4 \ubab8\uc774\uba74\uc11c, \uc0ac\ub78c\ub4e4\uc774 \ud798\uacfc \uc790\uc720\ub97c \uc5b4\ub5a4 \ubaa8\uc2b5\uc73c\ub85c \ud45c\ud604\ud588\ub294\uc9c0 \ubb3b\ub294 \uc5ed\uc0ac \uc790\ub8cc\ub2e4."}, {"id": "midsummer-lovers-magic-and-artisans", "title": "\ud55c\uc5ec\ub984 \ubc24\uc758 \uafc8 \u2014 \uc0ac\ub791\uc740 \uc232\uc5d0\uc11c \ub204\uad6c\uc758 \ub9c8\uc74c\uc774 \ub418\uc5c8\uc744\uae4c", "summary": "\uc0ac\ub791\uc758 \ub3c4\ud53c\uc640 \ub9c8\ubc95\uc758 \ucc29\uc624, \uc9c1\uacf5\ub4e4\uc758 \ub9c8\uc9c0\ub9c9 \uacf5\uc5f0\uc744 \ub530\ub77c \ud76c\uadf9\uc758 \uc5ec\ub7ec \uce35\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/midsummer-lovers-magic-and-artisans/index.html", "image": "../media/midsummer-lovers-magic-and-artisans.png", "alt": "\uc694\uc815\uc758 \ubd88\ube5b\uacfc \ub124 \uc5f0\uc778, \ub2f9\ub098\uadc0 \uba38\ub9ac\uc758 \uc9c1\uacf5\uc744 \uc5f0\uc0c1\ud558\ub294 \ud55c\uc5ec\ub984 \uc232\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ud55c\uc5ec\ub984 \ubc24\uc758 \uafc8 \u2014 \uc0ac\ub791\uc740 \uc232\uc5d0\uc11c \ub204\uad6c\uc758 \ub9c8\uc74c\uc774 \ub418\uc5c8\uc744\uae4c \ub124 \uc5f0\uc778\uacfc \uc694\uc815, \uc9c1\uacf5\uc758 \uc5f0\uadf9\uc774 \uad50\ucc28\ud558\ub294 \uc170\uc775\uc2a4\ud53c\uc5b4\uc758 \ud76c\uadf9 \uc0ac\ub791\uc758 \ub3c4\ud53c\uc640 \ub9c8\ubc95\uc758 \ucc29\uc624, \uc9c1\uacf5\ub4e4\uc758 \ub9c8\uc9c0\ub9c9 \uacf5\uc5f0\uc744 \ub530\ub77c \ud76c\uadf9\uc758 \uc5ec\ub7ec \uce35\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \uc170\uc775\uc2a4\ud53c\uc5b4\uc758 \ud76c\uadf9 \u300e\ud55c\uc5ec\ub984 \ubc24\uc758 \uafc8\u300f\uc5d0\ub294 \uacb0\ud63c\uc744 \uc55e\ub454 \ub3c4\uc2dc\uc640 \ubc24\uc758 \uc232, \uc694\uc815\ub4e4\uc758 \ub2e4\ud23c\uacfc \uc9c1\uacf5\ub4e4\uc758 \uacf5\uc5f0\uc774 \ud568\uaed8 \ub4f1\uc7a5\ud55c\ub2e4. \uc5ec\ub7ec \uc774\uc57c\uae30\uac00 \uad50\ucc28\ud558\uc9c0\ub9cc \uc911\uc2ec\uc5d0\ub294 \ub2e4\ub978 \uc0ac\ub78c\uc758 \ub9c8\uc74c\uc744 \ub73b\ub300\ub85c \ub9cc\ub4e4 \uc218 \uc788\ub294\uac00 \ud558\ub294 \uc9c8\ubb38\uc774 \uc788\ub2e4. \uc544\ub798\uc5d0\ub294 \ub124 \uc5f0\uc778\uc758 \uad00\uacc4\uc640 \ub9c8\ubc95, \ub9c8\uc9c0\ub9c9 \uacf5\uc5f0\uc758 \uacb0\ub9d0\uc774 \ud3ec\ud568\ub41c\ub2e4. \uc544\ud14c\ub124\uc758 \ud1b5\uce58\uc790 \ud14c\uc138\uc6b0\uc2a4\ub294 \ud788\ud3f4\ub9ac\ud0c0\uc640 \uacb0\ud63c\uc744 \uc900\ube44\ud55c\ub2e4. \uadf8\ub7ec\ub098 \ud5e4\ub974\ubbf8\uc544\uc5d0\uac8c \uacb0\ud63c\uc740 \uae30\uc05c \ud589\uc0ac\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uc544\ubc84\uc9c0\ub294 \ub370\uba54\ud2b8\ub9ac\uc6b0\uc2a4\ub97c \uc6d0\ud558\uc9c0\ub9cc \uadf8\ub140\ub294 \ub77c\uc774\uc0cc\ub354\ub97c \uc0ac\ub791\ud55c\ub2e4. \ub3c4\uc2dc\uc758 \uc9c8\uc11c\ub294 \ub450 \uc0ac\ub78c\uc758 \ub9c8\uc74c\uc744 \uac19\uc740 \ubb34\uac8c\ub85c \ubc1b\uc544\ub4e4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ud5e4\ub974\ubbf8\uc544\uc640 \ub77c\uc774\uc0cc\ub354\ub294 \uc232\uc73c\ub85c \ub2ec\uc544\ub098\uae30\ub85c \ud55c\ub2e4. \ud55c\ud3b8 \ud5ec\ub808\ub098\ub294 \uc790\uc2e0\uc744 \ub5a0\ub09c \ub370\uba54\ud2b8\ub9ac\uc6b0\uc2a4\ub97c \uc5ec\uc804\ud788 \uc0ac\ub791\ud55c\ub2e4. \ub124 \uc0ac\ub78c\uc758 \uad00\uacc4\ub294 \uc9dd\uc774 \ub9de\uc9c0 \uc54a\uc740 \uc0c1\ud0dc\ub2e4. \ub204\uad70\uac00\uc5d0\uac8c \uc0ac\ub791\uc758 \ub3c4\ud53c\uc778 \uae38\uc774 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ubd99\uc7a1\uc73c\ub7ec \uac00\ub294 \ucd94\uaca9\uc774 \ub41c\ub2e4. \uc694\uc815\uc758 \uc655 \uc624\ubca0\ub860\uacfc \uc5ec\uc655 \ud2f0\ud0c0\ub2c8\uc544\ub3c4 \ub2e4\ud22c\uace0 \uc788\ub2e4. \uc778\uac04\ub4e4\uc774 \ub3c4\uc2dc\uc758 \uaddc\uce59\uc744 \ubc97\uc5b4\ub0ac\ub2e4\uace0 \ud3c9\ud654\ub85c\uc6b4 \uc790\uc5f0\uc73c\ub85c \ub4e4\uc5b4\uc628 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc232\uc5d0\ub294 \ub2e4\ub978 \uad8c\ub825\uacfc \uac08\ub4f1\uc774 \uc788\uc5c8\ub2e4. \uc624\ubca0\ub860\uc740 \uc7a0\uc5d0\uc11c \uae68\uc5b4 \ucc98\uc74c \ubcf8 \ub300\uc0c1\uc744 \uc0ac\ub791\ud558\uac8c \ub9cc\ub4dc\ub294 \ub9c8\ubc95\uc744 \uc774\uc6a9\ud558\ub824 \ud55c\ub2e4. \uc7a5\ub09c\uafb8\ub7ec\uae30 \ud37d\uc774 \uadf8 \uc77c\uc744 \ub3d5\ub294\ub2e4. \uc624\ubca0\ub860\uc740 \uc778\uac04 \uc5f0\uc778\uc758 \uad00\uacc4\uc5d0\ub3c4 \uac1c\uc785\ud558\uc9c0\ub9cc, \ud37d\uc740 \ub300\uc0c1\uc744 \uc798\ubabb \uc54c\uc544\ubcf8\ub2e4. \uc0c1\ub300\uc758 \ub9c8\uc74c\uc744 \ubc14\ub85c\uc7a1\uaca0\ub2e4\ub294 \uc2dc\ub3c4\uac00 \ub610 \ub2e4\ub978 \ud63c\ub780\uc744 \ub9cc\ub4e0\ub2e4. \uc88b\uc740 \uacb0\uacfc\ub97c \uc6d0\ud55c\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ub0a8\uc758 \uac10\uc815\uc744 \uc870\uc791\ud558\ub294 \uc77c\uc774 \uc548\uc804\ud574\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub9c8\ubc95\uc774 \uc5b4\uae0b\ub098\uba74\uc11c \ub77c\uc774\uc0cc\ub354\ub294 \ud5ec\ub808\ub098\uc5d0\uac8c \ub9c8\uc74c\uc744 \ub3cc\ub9b0\ub2e4. \ub4a4\uc774\uc5b4 \ub370\uba54\ud2b8\ub9ac\uc6b0\uc2a4\ub3c4 \ud5ec\ub808\ub098\ub97c \uc0ac\ub791\ud558\uac8c \ub41c\ub2e4. \uc0ac\ub791\ubc1b\uc9c0 \ubabb\ud558\ub358 \uc0ac\ub78c\uc774 \uac11\uc790\uae30 \ub450 \uc0ac\ub78c\uc758 \uad6c\uc560\ub97c \ubc1b\uc9c0\ub9cc \ud5ec\ub808\ub098\ub294 \uae30\ubed0\ud558\uc9c0 \ubabb\ud55c\ub2e4. \ubaa8\ub450\uac00 \uc790\uc2e0\uc744 \uc870\ub871\ud558\ub294 \uac83\uc774\ub77c\uace0 \uc0dd\uac01\ud55c\ub2e4. \ud5e4\ub974\ubbf8\uc544\ub294 \uc124\uba85\ud560 \uc218 \uc5c6\ub294 \ubc30\uc2e0 \uc55e\uc5d0 \ub193\uc778\ub2e4. \uad00\uac1d\uc740 \ub9c8\ubc95\uc758 \uc0ac\uc815\uc744 \uc54c\uc9c0\ub9cc \ub124 \uc0ac\ub78c\uc740 \ubaa8\ub978\ub2e4. \uac19\uc740 \ub9d0\uc774 \ud55c\ucabd\uc5d0\ub294 \uc9c4\uc2ec\uc774\uace0 \ub2e4\ub978 \ucabd\uc5d0\ub294 \uc794\uc778\ud55c \ub18d\ub2f4\ucc98\ub7fc \ub4e4\ub9ac\ub294 \ucc28\uc774\uc5d0\uc11c \ud76c\uadf9\uc774 \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4. \uac10\uc815\uc758 \uac15\ub3c4\uc640 \uc0c1\ud669\uc744 \uc815\ud655\ud788 \uc774\ud574\ud558\ub294 \ub2a5\ub825\uc740 \uac19\uc740 \uac83\uc774 \uc544\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \uc9c1\uacf5\ub4e4\uc740 \uacb0\ud63c\uc2dd\uc5d0\uc11c \uc62c\ub9b4 \uc5f0\uadf9\uc744 \uc5f0\uc2b5\ud558\ub824\uace0 \uc232\uc5d0 \uc654\ub2e4. \uadf8\uc911 \ubcf4\ud140\uc740 \ud37d\uc758 \uc7a5\ub09c\uc73c\ub85c \ub2f9\ub098\uadc0 \uba38\ub9ac\ub97c \uac16\uac8c \ub41c\ub2e4. \ub9c8\ubc95\uc5d0 \uac78\ub9b0 \ud2f0\ud0c0\ub2c8\uc544\uac00 \uadf8\ub97c \ucc98\uc74c \ubcf4\uace0 \uc0ac\ub791\ud55c\ub2e4. \ub192\uc740 \uc5ec\uc655\uacfc \uc18c\ubc15\ud55c \uc9c1\uacf5\uc774 \uae30\ubb18\ud55c \uc9dd\uc774 \ub418\ub294 \uac83\uc774\ub2e4. \ubcf4\ud140\uc740 \uc694\uc815\uc758 \ub300\uc811\uc744 \ubc1b\uc73c\uba74\uc11c\ub3c4 \uc790\uae30 \ubc29\uc2dd\uc758 \uc695\uad6c\uc640 \ub9d0\uc744 \uc783\uc9c0 \uc54a\ub294\ub2e4. \uc232\uc758 \uc7a5\uc5c4\ud568\uc774 \uc77c\uc0c1\uc758 \uc791\uc740 \uc694\uad6c\uc640 \ubd80\ub52a\ud78c\ub2e4. \uc0ac\ub791\uc774 \ubcf4\ub294 \uc0ac\ub78c\uc744 \uc5bc\ub9c8\ub098 \ub2e4\ub974\uac8c \ubcf4\uc774\uac8c \ud558\ub294\uc9c0, \uc2e0\ubd84\uacfc \uac89\ubaa8\uc2b5\uc774 \ud3c9\uac00\ub97c \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc774\ub294\uc9c0 \uc6c3\uc74c \uc18d\uc5d0\uc11c \ub4dc\ub7ec\ub09c\ub2e4. \uc624\ubca0\ub860\uacfc \ud2f0\ud0c0\ub2c8\uc544\uac00 \ud654\ud574\ud558\uace0 \ud63c\ub780\uc740 \uc815\ub9ac\ub41c\ub2e4. \ub77c\uc774\uc0cc\ub354\ub294 \ub2e4\uc2dc \ud5e4\ub974\ubbf8\uc544\uc5d0\uac8c \ub3cc\uc544\uac00\uba70 \ub370\uba54\ud2b8\ub9ac\uc6b0\uc2a4\ub294 \ud5ec\ub808\ub098\uc640 \uc774\uc5b4\uc9c4\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \uac10\uc815\uc774 \ub611\uac19\uc774 \ub9c8\ubc95 \uc774\uc804\uc758 \uc0c1\ud0dc\ub85c \ub3cc\uc544\uac04 \uac83\uc774\ub77c\uace0 \ub2e8\uc21c\ud558\uac8c \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc774 \ucc28\uc774\ub294 \uacb0\ub9d0\uc744 \uc77d\ub294 \ud765\ubbf8\ub85c\uc6b4 \uc9c0\uc810\uc774\ub2e4. \ud589\ubcf5\ud55c \uc9dd\uc774 \uc774\ub8e8\uc5b4\uc84c\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8 \ub9c8\uc74c\uc774 \uc5b4\ub5a4 \uacfc\uc815\uc744 \uac70\ucce4\ub294\uc9c0\ub294 \ub2e4\ub978 \uc9c8\ubb38\uc774\ub2e4. \uc232\uc758 \uc0ac\uac74\uc744 \uafc8\ucc98\ub7fc \ubc1b\uc544\ub4e4\uc774\uba74 \uac08\ub4f1\uc740 \uac00\ubcbc\uc6cc\uc9c0\uc9c0\ub9cc, \uad00\uac1d\uc740 \uadf8 \uafc8\uc758 \uc548\ucabd\uc5d0\uc11c \ubc8c\uc5b4\uc9c4 \uac1c\uc785\uc744 \uae30\uc5b5\ud55c\ub2e4. \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \uc9c1\uacf5\ub4e4\uc774 \uc900\ube44\ud55c \ud53c\ub77c\ubaa8\uc2a4\uc640 \ud2f0\uc2a4\ubca0 \uc774\uc57c\uae30\ub97c \uacf5\uc5f0\ud55c\ub2e4. \uc11c\ub85c \uc0ac\ub791\ud558\uc9c0\ub9cc \ub9cc\ub098\uae30 \uc5b4\ub824\uc6b4 \ub450 \uc0ac\ub78c\uc758 \ube44\uadf9\uc774\ub2e4. \uc55e\uc5d0\uc11c \uc5f0\uc778\ub4e4\uc774 \uacaa\uc740 \ubb38\uc81c\uc640 \ub2ee\uc740 \uc774\uc57c\uae30\uc9c0\ub9cc \uc11c\ud22c\ub978 \uc5f0\uae30\uc640 \uc124\uba85\uc774 \ubd84\uc704\uae30\ub97c \ubc14\uafbc\ub2e4. \ubcbd\uacfc \ub2ec\ube5b\uc744 \uc0ac\ub78c\uc774 \ub9e1\uace0, \uad00\uac1d\uc740 \ubb34\ub300\uc758 \uc57d\uc18d\uc744 \ub208\uc55e\uc5d0\uc11c \ud655\uc778\ud55c\ub2e4. \ubcf4\ud140\uacfc \ub3d9\ub8cc\ub4e4\uc740 \uc9c4\uc9c0\ud558\uc9c0\ub9cc \uacf5\uc5f0\uc758 \uc5b4\uae0b\ub0a8\uc740 \uc6c3\uc74c\uc744 \ub9cc\ub4e0\ub2e4. \uad00\uac1d\uc774 \ubb34\uc5c7\uc744 \ubbff\uc5b4 \uc8fc\ub294\uc9c0\uc5d0 \ub530\ub77c \uac19\uc740 \uc7a5\uba74\uc774 \ube44\uadf9\ub3c4 \ud76c\uadf9\ub3c4 \ub420 \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \ubcf4\uc778\ub2e4. \uc5f0\uadf9\uc774 \uc5f0\uadf9\uc744 \ubc14\ub77c\ubcf4\ub294 \uad6c\uc870\ub2e4. \uc9c1\uacf5\ub4e4\uc740 \uad00\uac1d\uc744 \ub180\ub77c\uac8c \ud558\uc9c0 \uc54a\uc73c\ub824\ub294 \uac71\uc815\ub3c4 \ud55c\ub2e4. \uc0ac\uc790 \uc5ed\ud560\uc774 \uc815\ub9d0 \uc704\ud5d8\ud55c \ub3d9\ubb3c\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc9c0\uba74 \uace4\ub780\ud558\ub2e4\uace0 \uc0dd\uac01\ud558\ub294 \uc2dd\uc774\ub2e4. \uad00\uac1d\uc740 \ubc30\uc6b0\ub77c\ub294 \uc0ac\uc2e4\uc744 \uc54c\uace0 \uc788\ub294\ub370 \ubc30\uc6b0\ub294 \uadf8 \uacbd\uacc4\ub97c \ub2e4\uc2dc \uc124\uba85\ud558\ub824 \ud55c\ub2e4. \ubb34\uc5c7\uc744 \uc9c4\uc9dc\ub77c\uace0 \ubbff\uc5b4\uc57c \ud558\ub294\uc9c0 \uc9c0\ub098\uce58\uac8c \uce5c\uc808\ud558\uac8c \uc54c\ub824 \uc8fc\ub294 \ud0dc\ub3c4\uac00 \uc624\ud788\ub824 \uc5f0\uadf9\uc758 \uc6c3\uc74c\uc774 \ub41c\ub2e4. \uc232\uc5d0\uc11c \ubc8c\uc5b4\uc9c4 \uc77c \uc5ed\uc2dc \ub204\uac00 \ubb34\uc5c7\uc744 \uc798\ubabb \uc54c\uc544\ubcf4\ub294\uc9c0\uc5d0 \ub530\ub77c \ubc29\ud5a5\uc774 \ubc14\ub010\ub2e4. \uc5f0\uc778\uacfc \uc9c1\uacf5\uc758 \uc774\uc57c\uae30\uac00 \uc644\uc804\ud788 \ub530\ub85c \uc788\uc9c0 \uc54a\uc740 \uc774\uc720\ub2e4. \ud55c\ucabd\uc5d0\uc11c\ub294 \ub9c8\ubc95\uc774 \uac10\uac01\uacfc \ud310\ub2e8\uc744 \ud750\ub9ac\uace0, \ub2e4\ub978 \ucabd\uc5d0\uc11c\ub294 \uc5f0\uc2b5\ud55c \uc57d\uc18d\uc774 \uac10\uac01\uc744 \ubbff\uac8c \ud558\ub824 \ud55c\ub2e4. \uc0ac\ub791\uacfc \uc5f0\uadf9\uc774 \ub098\ub780\ud788 \ub193\uc774\uba74\uc11c \uc0ac\ub78c\uc758 \uc0c1\uc0c1\ub825\uc774 \uad00\uacc4\ub97c \uc5b4\ub5bb\uac8c \ubc14\uafb8\ub294\uc9c0 \uc5ec\ub7ec \ubaa8\uc591\uc73c\ub85c \ub4dc\ub7ec\ub09c\ub2e4. \uad00\uac1d\uc740 \uadf8 \ucc28\uc774\ub97c \uc54c\uace0 \uc990\uae30\uba74\uc11c\ub3c4 \uc790\uae30\uc758 \ubbff\uc74c \uc5ed\uc2dc \uc5b4\ub5a4 \ud45c\uc9c0\uc5d0 \uae30\ub300\uace0 \uc788\ub294\uc9c0 \ub3cc\uc544\ubcfc \uc218 \uc788\ub2e4. \ud37d\uc740 \ub9c8\uc9c0\ub9c9\uc5d0 \uad00\uac1d\uc5d0\uac8c \uc774 \ubaa8\ub4e0 \uc77c\uc744 \uafc8\ucc98\ub7fc \ubc1b\uc544\ub4e4\uc77c \uc218 \uc788\ub2e4\uace0 \ub9d0\uc744 \uac74\ub128\ub2e4. \ubb34\ub300\uc640 \uac1d\uc11d\uc758 \uacbd\uacc4\uac00 \uc7a0\uc2dc \uc5f4\ub9ac\ub294 \uc21c\uac04\uc774\ub2e4. \uc774\uc57c\uae30\uac00 \ub05d\ub0ac\ub2e4\uace0 \uafc8\uc18d\uc758 \uac10\uc815\uae4c\uc9c0 \ubaa8\ub450 \uc815\ub9ac\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\uc744 \ud310\ub2e8\ud55c \uae30\uc900\uacfc \ubbff\uc5c8\ub358 \ub9d0\uc774 \ub0a8\ub294\ub2e4. \u300e\ud55c\uc5ec\ub984 \ubc24\uc758 \uafc8\u300f\uc740 \ub0ad\ub9cc\uc801\uc778 \uc232\uc758 \uc774\uc57c\uae30\uc774\uba74\uc11c \uc0ac\ub791\uc744 \ub458\ub7ec\uc2fc \uad8c\ub825\uacfc \uc624\ud574\uc758 \ud76c\uadf9\uc774\ub2e4. \ub124 \uc5f0\uc778\uacfc \uc694\uc815, \uc9c1\uacf5\uc758 \uc7a5\uba74\uc744 \ud568\uaed8 \ubcf4\uba74 \uafc8\uc740 \ud604\uc2e4\uc5d0\uc11c \ubc97\uc5b4\ub098\ub294 \uc7a5\uc18c\ub9cc\uc774 \uc544\ub2c8\ub2e4. \ud604\uc2e4\uc758 \uaddc\uce59\uc744 \ub0af\uc124\uac8c \ube44\ucd94\uc5b4 \ub2e4\uc2dc \ubcf4\uac8c \ud558\ub294 \ubb34\ub300\uac00 \ub41c\ub2e4."}, {"id": "millet-gleaners-harvest", "title": "\uc774\uc0ad \uc90d\ub294 \uc5ec\uc778\ub4e4 \u2014 \ud48d\uc694\ub85c\uc6b4 \ub4e4\ud310\uc758 \uac00\uc7a5 \ub0ae\uc740 \uc790\ub9ac", "summary": "\uc138 \uc0ac\ub78c\uc758 \ubab8\uacfc \ub113\uc740 \ub4e4\ud310\uc744 \ub530\ub77c \uc77c\uacfc \ubd84\ubc30\ub97c \uc0dd\uac01\ud558\uac8c \ud558\ub294 \ud654\uba74\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/millet-gleaners-harvest/index.html", "image": "../media/millet-gleaners-harvest.jpg", "alt": "\ubc00\ub808\uc758 \uc774\uc0ad \uc90d\ub294 \uc5ec\uc778\ub4e4. \uc804\uacbd\uc758 \uc138 \uc5ec\uc778\uc774 \ud5c8\ub9ac\ub97c \uc219\uc5ec \uc774\uc0ad\uc744 \uc90d\uace0 \ub4a4\ucabd\uc5d0\uc11c\ub294 \ub9ce\uc740 \uc218\ud655\ubb3c\uc774 \ubaa8\uc785\ub2c8\ub2e4.", "text": "\uc774\uc0ad \uc90d\ub294 \uc5ec\uc778\ub4e4 \u2014 \ud48d\uc694\ub85c\uc6b4 \ub4e4\ud310\uc758 \uac00\uc7a5 \ub0ae\uc740 \uc790\ub9ac \ubc00\ub808\uc758 \uadf8\ub9bc\uc5d0\uc11c \uc218\ud655\uacfc \uc791\uc740 \uc90d\uae30\ub97c \ud568\uaed8 \ubcf4\uae30 \uc138 \uc0ac\ub78c\uc758 \ubab8\uacfc \ub113\uc740 \ub4e4\ud310\uc744 \ub530\ub77c \uc77c\uacfc \ubd84\ubc30\ub97c \uc0dd\uac01\ud558\uac8c \ud558\ub294 \ud654\uba74\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \ub4e4\ud310\uc758 \uba40\ub9ac\uc5d0\ub294 \uace1\uc2dd\uc774 \ub9ce\uc774 \ubaa8\uc5ec \uc788\ub2e4. \uadf8\ub7f0\ub370 \uadf8\ub9bc \uc55e\ucabd\uc758 \uc138 \uc0ac\ub78c\uc740 \ud5c8\ub9ac\ub97c \uad7d\ud600 \ubc14\ub2e5\uc5d0\uc11c \uc791\uc740 \uc774\uc0ad\uc744 \uc90d\ub294\ub2e4. \uac19\uc740 \uc218\ud655\uc758 \ud48d\uacbd \uc548\uc5d0 \ud070 \ub354\ubbf8\uc640 \uc190\ub05d\uc758 \uc791\uc740 \uc591\uc774 \ud568\uaed8 \ub193\uc778\ub2e4. \ubc00\ub808\uc758 \u3008\uc774\uc0ad \uc90d\ub294 \uc5ec\uc778\ub4e4\u3009\uc774\ub2e4. \uc774 \uadf8\ub9bc\uc740 \ubb34\uc5c7\uc744 \ud558\ub294 \uc0ac\ub78c\ub4e4\uc778\uc9c0 \uc54c\uae30 \uc26c\uc6b0\uba74\uc11c\ub3c4, \uc624\ub798 \ubcf4\uba74 \uadf8 \ub2e8\uc21c\ud55c \uc124\uba85\ubcf4\ub2e4 \ub9ce\uc740 \uac83\uc744 \ub290\ub07c\uac8c \ud55c\ub2e4. \uc804\uacbd\uacfc \ubc30\uacbd, \ubab8\uc758 \ud06c\uae30\uc640 \uc77c\uc758 \uc591\uc774 \uc11c\ub85c \ub2e4\ub978 \uac10\uac01\uc744 \ub9cc\ub4e4\uae30 \ub54c\ubb38\uc774\ub2e4. \uba3c\uc800 \uc138 \uc0ac\ub78c\uc758 \uc190\uc5d0\uc11c \uc2dc\uc791\ud574 \ub4e4\ud310 \ub05d\uae4c\uc9c0 \ub208\uc744 \uc62e\uaca8 \ubcf4\uc790. \uc774\uc0ad \uc90d\uae30\ub294 \ud070 \uc218\ud655\uc744 \uac70\ub454 \ub4a4 \ub4e4\ud310\uc5d0 \ub0a8\uc740 \uc791\uc740 \uace1\uc2dd\ub4e4\uc744 \ubaa8\uc73c\ub294 \uc77c\uc774\ub2e4. \uadf8\ub9bc\uc5d0\uc11c\ub294 \ub450 \uc0ac\ub78c\uc774 \uae4a\uc774 \ud5c8\ub9ac\ub97c \uad7d\ud788\uace0 \ub2e4\ub978 \ud55c \uc0ac\ub78c\uc740 \uc870\uae08 \ubab8\uc744 \uc138\uc6b4 \uc790\uc138\ub97c \ubcf4\uc778\ub2e4. \uc77c\uc744 \ud558\ub294 \ub3d9\uc548 \uacc4\uc18d \ubc18\ubcf5\ub420 \ub3d9\uc791\uc744 \ud55c \ud654\uba74 \uc548\uc5d0\uc11c \ub9cc\ub098\ub294 \uc148\uc774\ub2e4. \uc774\ub97c \ub2e8\uc21c\ud788 \uc0b0\ucc45\ud558\ub2e4 \ub5a8\uc5b4\uc9c4 \uace1\uc2dd\uc744 \uc90d\ub294 \uac00\ubcbc\uc6b4 \uc77c\ub85c \uc0c1\uc0c1\ud558\uba74 \ubab8\uc758 \ubb34\uac8c\ub97c \ub193\uce58\uae30 \uc27d\ub2e4. \uc190\uc740 \ub0ae\uc740 \uacf3\uc5d0 \ub2ff\uc544\uc57c \ud558\uace0 \uc2dc\uc120\uc740 \ub545\uc744 \uc0b4\ud540\ub2e4. \uadf8\ub9bc\uc740 \ub178\ub3d9\uc774\ub77c\ub294 \ud070 \ub9d0 \ub300\uc2e0 \uadf8 \uc77c\uc744 \ud558\ub294 \ub370 \ud544\uc694\ud55c \uc790\uc138\ub97c \ubcf4\uc5ec \uc900\ub2e4. \uc6b0\ub9ac\ub294 \ucd08\uc0c1\ud654\uc5d0\uc11c \uc5bc\uad74\uc758 \ud45c\uc815\uc744 \uba3c\uc800 \ucc3e\ub294 \ub370 \uc775\uc219\ud558\ub2e4. \uc774 \uadf8\ub9bc\uc758 \uc778\ubb3c\ub4e4\uc740 \uace0\uac1c\ub97c \uc219\uc774\uace0 \uc788\uc5b4 \uc5bc\uad74\ub9cc\uc73c\ub85c \uac10\uc815\uc744 \uc77d\uae30 \uc5b4\ub835\ub2e4. \ub300\uc2e0 \ub4f1\uacfc \ud5c8\ub9ac, \ud314\uacfc \ubb34\ub98e\uc774 \uc5b4\ub5a4 \ubc29\ud5a5\uc73c\ub85c \ub193\uc600\ub294\uc9c0\uac00 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ud45c\uc815\uc744 \ub69c\ub837\uc774 \ubcf4\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uc0ac\ub78c\uc774 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ud788\ub824 \ubab8\uc774 \ud558\ub294 \uc77c\uc744 \ub354 \uc624\ub798 \ubcf4\uac8c \ub420 \uc218 \uc788\ub2e4. \ubb34\uc2a8 \uc0dd\uac01\uc744 \ud588\ub294\uc9c0 \ub300\uc0ac\ub97c \ubd99\uc774\uae30\ubcf4\ub2e4, \uc9c0\uae08 \uc774 \ud589\ub3d9\uc744 \uc5bc\ub9c8\ub098 \ubc18\ubcf5\ud574\uc57c \uc791\uc740 \ubb36\uc74c\uc774 \uc0dd\uae38\uc9c0 \uc0c1\uc0c1\ud574 \ubcf4\uc790. \uadf8\ub9bc\uc758 \uc2dc\uac04\uc740 \ud55c \ubc88\uc758 \ub3d9\uc791\ubcf4\ub2e4 \uae38\uc5b4\uc9c4\ub2e4. \uc67c\ucabd\uc758 \uc778\ubb3c\uc5d0\uc11c \uac00\uc6b4\ub370\ub97c \uac70\uccd0 \uc624\ub978\ucabd\uc73c\ub85c \ub208\uc744 \uc62e\uaca8 \ubcf4\uc790. \ube44\uc2b7\ud55c \uc77c\uc744 \ud558\uc9c0\ub9cc \ubab8\uc758 \ub192\uc774\uc640 \ud314\uc758 \uc704\uce58\ub294 \uc870\uae08\uc529 \ub2e4\ub974\ub2e4. \ubaa8\ub450 \ub611\uac19\uc740 \ubaa8\uc591\uc73c\ub85c \ubc18\ubcf5\ub418\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc5d0 \uc7a5\uba74\uc740 \uc815\uc9c0\ub41c \ub3c4\uc2dd\uc774 \uc544\ub2c8\ub77c \uc0b4\uc544 \uc788\ub294 \uc6c0\uc9c1\uc784\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uc774\ub97c \ud55c \uc0ac\ub78c\uc774 \uc6c0\uc9c1\uc774\ub294 \uc5f0\uc18d \uc0ac\uc9c4\uc774\ub77c\uace0 \ud655\uc815\ud558\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc778\ubb3c\uc758 \uc790\uc138\ub97c \uc774\uc5b4 \ubcf4\uba70 \uc77c\uc758 \ub9ac\ub4ec\uc744 \ub290\ub07c\ub294 \ubc29\ubc95\uc774\ub2e4. \uac19\uc740 \uc77c\uc744 \ud558\ub294 \uc0ac\ub78c\ub4e4\ub3c4 \uac01\uc790\uc758 \ubab8\uacfc \uc18d\ub3c4\ub97c \uac00\uc9c4\ub2e4\ub294 \uc810\uc774 \ud654\uba74 \uc548\uc5d0 \ub0a8\ub294\ub2e4. \ubc30\uacbd\uc5d0\ub294 \uace1\uc2dd \ub354\ubbf8\uc640 \uc218\ub808, \uc218\ud655\ud558\ub294 \uc0ac\ub78c\ub4e4, \ub9d0\uc744 \ud0c4 \uc778\ubb3c\uc774 \ubcf4\uc778\ub2e4. \uc55e\ucabd\uc5d0\uc11c \uc190\uc73c\ub85c \ubaa8\uc73c\ub294 \uc591\uacfc\ub294 \ub2e4\ub978 \uaddc\ubaa8\ub2e4. \ub450 \uc790\ub9ac\ub97c \ud568\uaed8 \ubcf4\uba74\uc11c \ub204\uac00 \ubb34\uc5c7\uc744 \uc5bc\ub9c8\ub098 \uac00\uc9c0\ub294\uc9c0\uc5d0 \uad00\ud55c \uc9c8\ubb38\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \uadf8\ub9bc \ud55c \uc7a5\uc73c\ub85c \ub2f9\uc2dc\uc758 \ubaa8\ub4e0 \ud1a0\uc9c0 \uc81c\ub3c4\uc640 \uc784\uae08 \uad00\uacc4\ub97c \ud655\uc778\ud588\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc9c0\uae08 \ub208\uc73c\ub85c \ud655\uc778\ud558\ub294 \uac83\uc740 \ud070 \uc218\ud655\uacfc \uc791\uc740 \uc90d\uae30\uac00 \ud55c \ud654\uba74\uc5d0 \ud568\uaed8 \uc788\ub2e4\ub294 \uc810\uc774\ub2e4. \uadf8 \uc2dc\uac01\uc801 \ucc28\uc774\uac00 \uc0ac\ud68c\uc758 \uad00\uacc4\ub97c \uc0dd\uac01\ud558\ub3c4\ub85d \uc5ec\uc9c0\ub97c \uc5f0\ub2e4. \uc804\uacbd\uc758 \uc138 \uc0ac\ub78c\uc740 \ud654\uba74\uc5d0\uc11c \ud070 \uc790\ub9ac\ub97c \ucc28\uc9c0\ud55c\ub2e4. \uba40\ub9ac\uc758 \ud48d\uc694\ub85c\uc6b4 \uc218\ud655\uc774 \uc7a5\uba74 \uc804\uccb4\ub97c \uc124\uba85\ud558\ub294 \uc8fc\uc778\uacf5\uc73c\ub85c\ub9cc \ub0a8\uc9c0 \uc54a\ub294\ub2e4. \uac00\uae4c\uc6b4 \uacf3\uc5d0\uc11c \ubab8\uc744 \ub0ae\ucd94\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc6b0\ub9ac\uc758 \ub208\uc55e\uc5d0 \uba3c\uc800 \ub193\uc778\ub2e4. \ubb34\uc5c7\uc744 \uc911\uc2ec\uc5d0 \ub458\uc9c0 \ud654\uac00\uac00 \uace0\ub978 \uacb0\uacfc\ub2e4. \uc791\uc740 \uc77c\uc744 \ud558\ub294 \uc0ac\ub78c\uc744 \uc791\uac8c \uadf8\ub9b4 \ud544\uc694\ub294 \uc5c6\uc5c8\ub2e4. \uadf8\ub9bc\uc758 \ubb3c\ub9ac\uc801\uc778 \ud06c\uae30\uc640 \uc0ac\ud68c\uc801\uc778 \uc8fc\ubaa9\uc774 \uc5b4\ub5a4 \uad00\uacc4\ub97c \ub9fa\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uc624\ub298\uc758 \uac10\uc0c1\uc744 \uc791\uac00\uac00 \uc9c1\uc811 \uc120\uc5b8\ud55c \uc815\uce58\uc801 \uad6c\ud638\ucc98\ub7fc \ub9cc\ub4e4\uc9c0\ub294 \uc54a\ub354\ub77c\ub3c4, \uc774 \uc120\ud0dd\uc774 \ubcf4\ub294 \uc21c\uc11c\ub97c \ubc14\uafb8\ub294 \uac83\uc740 \ub290\ub084 \uc218 \uc788\ub2e4. \ub530\ub73b\ud55c \ud759\ube5b\uacfc \uc218\ud655\uae30\uc758 \ud48d\uacbd \ub54c\ubb38\uc5d0 \ucc98\uc74c\uc5d0\ub294 \ud3c9\uc628\ud55c \ub18d\ucd0c \uc7a5\uba74\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc0ac\ub78c\ub4e4\uc758 \uad7d\uc740 \ubab8\uc744 \ud568\uaed8 \ubcf4\uba74 \ub2e4\ub978 \ubb34\uac8c\ub3c4 \ub290\uaef4\uc9c4\ub2e4. \ubcf4\uae30 \uc88b\uc740 \ud48d\uacbd\uacfc \uadf8 \uc548\uc5d0\uc11c \uc0b4\uc544\uac00\ub294 \ub178\ub3d9\uc740 \uac19\uc740 \uac10\uc815\uc73c\ub85c\ub9cc \uc815\ub9ac\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc0c9\uc774 \ub530\ub73b\ud558\ub2c8 \uc0dd\ud65c\ub3c4 \ud589\ubcf5\ud588\uc744 \uac83\uc774\ub77c\uace0 \uacb0\ub860 \ub0b4\ub9ac\uc9c0 \ub9d0\uc790. \ubc18\ub300\ub85c \ubab8\uc744 \uad7d\ud614\uc73c\ub2c8 \uc5bc\uad74\uc5d0 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc808\ub9dd\uae4c\uc9c0 \uc6b0\ub9ac\uac00 \ubaa8\ub450 \uc548\ub2e4\uace0 \ud560 \uc218\ub3c4 \uc5c6\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \uc790\uc138\uc640 \uacf5\uac04\uc744 \uadfc\uac70\ub85c \uc0dd\uac01\uc744 \ub113\ud788\ub418, \uc778\ubb3c\uc758 \ub0b4\uba74\uc744 \ub2e8\uc815\ud558\uc9c0 \uc54a\ub294 \uac10\uc0c1\uc774 \uac00\ub2a5\ud558\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uc624\ub798\ub41c \ubbf8\uc220 \ub3c4\ub85d\uc5d0 \uc218\ub85d\ub41c \uc2e4\uc81c \ud68c\ud654\uc758 \uc0c9\ucc44 \uc7ac\ud604 \uc790\ub8cc\ub2e4. \ub18d\ubbfc\ub4e4\uc758 \ubaa8\uc2b5\uc744 AI\ub85c \ub2e4\uc2dc \ub9cc\ub4e0 \uadf8\ub9bc\uc740 \uc544\ub2c8\ub2e4. \uc778\ubb3c\uc758 \ubc30\uce58\uc640 \ub113\uc740 \ub4e4\ud310\uc774 \uc774\ub8e8\ub294 \uad00\uacc4\ub97c \ud655\uc778\ud560 \uc218 \uc788\ub3c4\ub85d \uc6d0\ub798 \ub3c4\ud310\uc744 \uc0ac\uc6a9\ud588\ub2e4. \uc624\ub798\ub41c \uc18c\uc7a5\ud488 \uc548\ub0b4\uc758 \ubc88\ud638\uc640 \uc804\uc2dc \uc815\ubcf4\ub294 \uc624\ub298\uc758 \uc704\uce58\ub97c \ubcf4\uc99d\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc774 \uc790\ub8cc\ub294 \ud604\uc7ac \ubc15\ubb3c\uad00\uc744 \ucc3e\uc544\uac00\ub294 \uc9c0\ub3c4\uac00 \uc544\ub2c8\ub77c \uc791\ud488\uc744 \uc77d\ub294 \ub370 \uc4f0\ub294 \uc774\ubbf8\uc9c0\ub2e4. \uc61b \uc778\uc1c4\uc758 \uc0c9\uacfc \uc138\ubd80 \uc5ed\uc2dc \uc2e4\ubb3c \uc804\uccb4\ub97c \ub300\uc2e0\ud558\uc9c0 \uc54a\uc73c\ubbc0\ub85c \ud070 \uad6c\uc131\ubd80\ud130 \ubcf4\ub294 \ud3b8\uc774 \uc801\uc808\ud558\ub2e4. \uadf8\ub9bc\uc744 \ubcf8 \ub4a4 \ucc98\uc74c\uc758 \uc190\uc73c\ub85c \ub2e4\uc2dc \ub3cc\uc544\uac00 \ubcf4\uc790. \ub4a4\uc758 \ud070 \ub354\ubbf8\ub97c \uc54c\uace0 \ub098\uba74 \uc55e\uc758 \uc791\uc740 \uc90d\uae30\uac00 \ucc98\uc74c\uacfc \ub2e4\ub974\uac8c \ubcf4\uc77c \uc218 \uc788\ub2e4. \uba40\ub9ac\uc640 \uac00\uae4c\uc774, \ub9ce\uc740 \uac83\uacfc \uc791\uc740 \uac83\uc774 \uc11c\ub85c\uc758 \uc758\ubbf8\ub97c \ub9cc\ub4e0\ub2e4. \ud55c \ubd80\ubd84\ub9cc \uc798\ub77c \ubcfc \ub54c\ubcf4\ub2e4 \uc804\uccb4\uc5d0\uc11c \uc0dd\uae30\ub294 \ud798\uc774\ub2e4. \u3008\uc774\uc0ad \uc90d\ub294 \uc5ec\uc778\ub4e4\u3009\uc740 \uc77c\ud558\ub294 \uc0ac\ub78c\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc \uc54c\ub824 \uc8fc\ub294 \uadf8\ub9bc\uc774 \uc544\ub2c8\ub2e4. \ub204\uad6c\uc758 \ubab8\uc744 \ud06c\uac8c \ubcf4\uace0 \uc5b4\ub5a4 \ud48d\uc694\ub97c \ubc30\uacbd\uc73c\ub85c \ub450\ub294\uc9c0 \ubb3b\uac8c \ud55c\ub2e4. \uae38\uac8c \uc124\uba85\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc138 \uc0ac\ub78c\uc758 \ubc18\ubcf5\ub418\ub294 \uc790\uc138\uac00 \uc2dc\uc120\uc744 \ubd99\uc7a1\ub294\ub2e4. \uadf8 \uc55e\uc5d0 \uc7a0\uc2dc \uba38\ubb34\ub294 \uac83\uc774 \uc774 \uc791\ud488\uc744 \uc77d\ub294 \uc88b\uc740 \uc2dc\uc791\uc774\ub2e4."}, {"id": "moby-dick-ishmael-ahab-and-sea", "title": "\ubaa8\ube44 \ub515 \u2014 \ud55c \uc120\uc7a5\uc758 \ubcf5\uc218\uac00 \ubc30 \uc804\uccb4\uc758 \uc6b4\uba85\uc774 \ub420 \ub54c", "summary": "\ud53c\ucffc\ub4dc\ud638\uc758 \ud56d\ud574\uc640 \uc5ec\ub7ec \ubaa9\uc18c\ub9ac, \ub9c8\uc9c0\ub9c9 \ucd94\uaca9\uc744 \ud1b5\ud574 \uacf5\ub3d9\uccb4\uc758 \ubaa9\ud45c\uac00 \ubc14\ub00c\ub294 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/moby-dick-ishmael-ahab-and-sea/index.html", "image": "../media/moby-dick-ishmael-ahab-and-sea.png", "alt": "\uac70\ub300\ud55c \ubc14\ub2e4\uc758 \ud3ec\uacbd\uc120\uacfc \uc791\uc740 \ubc30, \uba40\ub9ac \ub5a0\uc624\ub978 \ud770 \uace0\ub798\ub97c \uadf8\ub9b0 \ubaa8\ube44 \ub515 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ubaa8\ube44 \ub515 \u2014 \ud55c \uc120\uc7a5\uc758 \ubcf5\uc218\uac00 \ubc30 \uc804\uccb4\uc758 \uc6b4\uba85\uc774 \ub420 \ub54c \uba5c\ube4c\uc758 \ud3ec\uacbd\uc120\uc5d0\uc11c \ucda9\ub3cc\ud558\ub294 \ub178\ub3d9\u00b7\uad8c\ud55c\u00b7\uc9d1\ucc29 \ud53c\ucffc\ub4dc\ud638\uc758 \ud56d\ud574\uc640 \uc5ec\ub7ec \ubaa9\uc18c\ub9ac, \ub9c8\uc9c0\ub9c9 \ucd94\uaca9\uc744 \ud1b5\ud574 \uacf5\ub3d9\uccb4\uc758 \ubaa9\ud45c\uac00 \ubc14\ub00c\ub294 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \ubc14\ub2e4\ub85c \ub098\uac04 \uc0ac\ub78c\ub4e4\uc758 \ubaa9\uc801\uc740 \uac19\uc544 \ubcf4\uc778\ub2e4. \uadf8\ub7ec\ub098 \ud55c \ubc30\uc5d0 \ud0d4\ub2e4\uace0 \uac19\uc740 \uac83\uc744 \ubc14\ub77c\ubcf4\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud5c8\uba3c \uba5c\ube4c\uc758 \u300e\ubaa8\ube44 \ub515\u300f\uc5d0\uc11c \ud53c\ucffc\ub4dc\ud638\uc758 \uc120\uc6d0\ub4e4\uc740 \ud3ec\uacbd \uc791\uc5c5\uc744 \uc704\ud574 \ubaa8\uc600\uc9c0\ub9cc \uc5d0\uc774\ud574\ube0c \uc120\uc7a5\uc740 \ud770 \uace0\ub798\ub97c \ud5a5\ud55c \uac1c\uc778\uc801\uc778 \uc9d1\ucc29\uc73c\ub85c \uadf8\ub4e4\uc758 \ud56d\ud574\ub97c \uc774\ub048\ub2e4. \uc791\ud488\uc740 \ub2e8\uc21c\ud55c \uace0\ub798 \ucd94\uaca9\ub2f4\ubcf4\ub2e4 \ud6e8\uc52c \ub113\ub2e4. \uace0\ub798\uc640 \ubc30\uc758 \uae30\uc220, \ub2e4\uc591\ud55c \uc0ac\ub78c\ub4e4\uc758 \uc0dd\ud65c\uacfc \uc138\uacc4\ub97c \ud574\uc11d\ud558\ub294 \ub9d0\uc774 \uae38\uac8c \ub4e4\uc5b4 \uc788\ub2e4. \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \ub530\ub77c \uc77d\uc73c\uba74 \ud55c \uc0ac\ub78c\uc758 \ud655\uc2e0\uc774 \uacf5\ub3d9\uccb4\uc758 \ubaa9\uc801\uc744 \uc5b4\ub5bb\uac8c \ubc14\uafb8\ub294\uc9c0\uac00 \ubcf4\uc778\ub2e4. \uc774\uc57c\uae30\ub97c \uc804\ud558\ub294 \uc774\uc288\uba54\uc77c\uc740 \uc721\uc9c0\uc758 \uc0dd\ud65c\uc5d0\uc11c \ubc97\uc5b4\ub098 \ubc14\ub2e4\ub85c \uac00\ub824 \ud55c\ub2e4. \uadf8\ub294 \ub274\ubca0\ub4dc\ud37c\ub4dc\uc5d0\uc11c \uc791\uc0b4\uc7a1\uc774 \ud034\ud018\uadf8\ub97c \ub9cc\ub098\uace0 \ub450 \uc0ac\ub78c\uc740 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \ub0af\uc120 \uc0ac\ub78c\uc744 \ucc98\uc74c \ubc14\ub77c\ubcf4\ub294 \ud3b8\uacac\uacfc \ud568\uaed8 \uc9c0\ub0b4\uba70 \ubc14\ub00c\ub294 \uad00\uacc4\uac00 \ud56d\ud574 \uc804\ubd80\ud130 \ub4f1\uc7a5\ud55c\ub2e4. \uc138\uacc4\ub97c \ubc30\uc6b0\ub294 \uc77c\uc740 \ubc30\uc5d0 \uc624\ub978 \ub4a4\uc5d0\ub9cc \uc2dc\uc791\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc774\ub4e4\uc740 \ub0b8\ud130\ud0b7\uc5d0\uc11c \ud53c\ucffc\ub4dc\ud638\uc5d0 \uc2b9\uc120\ud55c\ub2e4. \uc120\uc6d0\ub4e4\uc758 \ucd9c\uc2e0\uacfc \uc5ed\ud560\uc740 \ub2e4\uc591\ud558\ub2e4. \ubc30\ub294 \uc791\uc740 \uacf5\ub3d9\uccb4\uc774\uc9c0\ub9cc \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uac19\uc740 \uad8c\ud55c\uc744 \uac00\uc9c4 \uacf3\uc740 \uc544\ub2c8\ub2e4. \ub204\uac00 \uba85\ub839\ud558\uace0 \ub204\uac00 \uc704\ud5d8\ud55c \uc77c\uc744 \uc218\ud589\ud558\ub294\uc9c0\uc758 \uc9c8\uc11c\uac00 \uc788\ub2e4. \uc774\ud6c4 \uc120\uc7a5\uc758 \uc9d1\ucc29\uc740 \uc774 \uad6c\uc870\ub97c \ud1b5\ud574 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc804\ub2ec\ub41c\ub2e4. \ubc30\uac00 \ub5a0\ub09c \uacf5\uc2dd\uc801\uc778 \ubaa9\uc801\uc740 \uace0\ub798\ub97c \uc7a1\uc544 \uc218\uc775\uc744 \uc5bb\ub294 \uc77c\uc774\uc5c8\ub2e4. \uc791\uc740 \ubcf4\ud2b8\ub97c \ub0b4\ub9ac\uace0 \uace0\ub798\ub97c \ucd94\uc801\ud558\uba70 \uc5bb\uc740 \uac83\uc744 \ucc98\ub9ac\ud558\ub294 \ubcf5\uc7a1\ud55c \ub178\ub3d9\uc774 \ud544\uc694\ud588\ub2e4. \ub0ad\ub9cc\uc801\uc778 \ubc14\ub2e4 \ud48d\uacbd \ub4a4\uc5d0\ub294 \uae30\uc220\uacfc \ubd84\uc5c5, \uc704\ud5d8\uacfc \ubcf4\uc0c1\uc758 \ubb38\uc81c\uac00 \uc788\uc5c8\ub2e4. \uba5c\ube4c\uc774 \uc791\uc5c5\uc744 \uae38\uac8c \uc124\uba85\ud558\ub294 \uc774\uc720\ub97c \uc774 \ub9e5\ub77d\uc5d0\uc11c \ubcfc \uc218 \uc788\ub2e4. \uace0\ub798\uc5d0 \uad00\ud55c \uae34 \uc9c0\uc2dd\uc758 \ub300\ubaa9\ub3c4 \ucd94\uaca9\uc744 \ubc29\ud574\ud558\ub294 \uacc1\uac00\uc9c0\ub85c\ub9cc \ubcf4\uae30\ub294 \uc5b4\ub835\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \uc790\uc2e0\uc774 \ub2e4\ub8e8\ub294 \uc874\uc7ac\ub97c \ubd84\ub958\ud558\uace0 \uc774\ud574\ud558\ub824 \ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc124\uba85\uc774 \ub9ce\uc544\uc838\ub3c4 \ub300\uc0c1\uc774 \uc644\uc804\ud788 \uc190\uc548\uc5d0 \ub4e4\uc5b4\uc624\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ucc45\uc758 \ubc29\ub300\ud55c \uc9c0\uc2dd\uacfc \ubc14\ub2e4\uc758 \ud06c\uae30 \uc0ac\uc774\uc5d0\ub294 \uacc4\uc18d \uac70\ub9ac\uac00 \ub0a8\ub294\ub2e4. \uc5d0\uc774\ud574\ube0c\ub294 \ubaa8\ube44 \ub515\uc5d0\uac8c \ud55c\ucabd \ub2e4\ub9ac\ub97c \uc783\uc5c8\ub2e4. \uadf8\ub294 \ud770 \uace0\ub798\ub97c \ub2e8\uc21c\ud55c \ub3d9\ubb3c \uc774\uc0c1\uc73c\ub85c \ubc1b\uc544\ub4e4\uc774\uba70 \ubc18\ub4dc\uc2dc \ucd94\uc801\ud558\uaca0\ub2e4\uace0 \uc120\uc5b8\ud55c\ub2e4. \ubc30\uc758 \uc0c1\uc5c5\uc801 \ubaa9\uc801 \uc704\uc5d0 \uac1c\uc778\uc801\uc778 \ubcf5\uc218\uac00 \uc62c\ub77c\uc120\ub2e4. \uc120\uc7a5\uc758 \uad8c\ud55c\uacfc \uac15\ud55c \uc5b8\uc5b4\uac00 \uadf8 \uc804\ud658\uc744 \uc774\ub048\ub2e4. \uc774 \ub300\ubaa9\uc5d0\uc11c \uc911\uc694\ud55c \uac83\uc740 \uc9d1\ucc29\uc774 \ub9c8\uc74c\uc18d \uc0dd\uac01\uc73c\ub85c\ub9cc \ub0a8\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc0ac\uc2e4\uc774\ub2e4. \ubc30\uc758 \uae38\uacfc \uc2dc\uac04, \uc120\uc6d0\ub4e4\uc758 \ub178\ub3d9\uc774 \uac70\uae30\uc5d0 \ub9de\ucd94\uc5b4\uc9c4\ub2e4. \ud55c \uc0ac\ub78c\uc774 \uc138\uc0c1\uc744 \ud574\uc11d\ud558\ub294 \ubc29\uc2dd\uc774 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc0dd\uc874 \uc870\uac74\uc744 \ubc14\uafbc\ub2e4. \uac1c\uc778\uc758 \uc758\uc9c0\uac00 \uacf5\ub3d9\uccb4\uc758 \uc790\uc6d0\uc744 \uc0ac\uc6a9\ud560 \ub54c \uc5b4\ub5a4 \ubb38\uc81c\uac00 \uc0dd\uae30\ub294\uc9c0 \ub4dc\ub7ec\ub09c\ub2e4. \uc5d0\uc774\ud574\ube0c\ub294 \ub3db\ub300\uc5d0 \uae08\ud654\ub97c \ub0b4\uac78\uace0 \ud770 \uace0\ub798\ub97c \uba3c\uc800 \ubc1c\uacac\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c \ubcf4\uc0c1\uc744 \uc57d\uc18d\ud55c\ub2e4. \uac1c\uc778\uc758 \uc9d1\ucc29\uc774 \uc120\uc6d0\ub4e4\uc758 \uad00\uc2ec\uacfc \ud589\ub3d9\uc744 \ub04c\uc5b4\ub4e4\uc774\ub294 \uad6c\uccb4\uc801\uc778 \ubc29\uc2dd\uc774\ub2e4. \uc120\uc7a5\uc758 \ub9d0\ub9cc\uc774 \uc544\ub2c8\ub77c \ubcf4\uc0c1\uacfc \uad8c\ud55c\uc774 \ud568\uaed8 \uc791\ub3d9\ud558\uba70 \ubc30\uc758 \ubaa9\ud45c\ub97c \ubc14\uafbc\ub2e4. \uc77c\ub4f1\ud56d\ud574\uc0ac \uc2a4\ud0c0\ubc85\uc740 \uc120\uc7a5\uc758 \uc704\ud5d8\ud55c \ubaa9\uc801\uc5d0 \uc758\ubb38\uc744 \uc81c\uae30\ud55c\ub2e4. \uace0\ub798\uc7a1\uc774\ub77c\ub294 \uc77c\uacfc \ubcf5\uc218\ub77c\ub294 \ubaa9\ud45c\ub97c \uad6c\ubd84\ud558\ub824\ub294 \ubaa9\uc18c\ub9ac\ub2e4. \uadf8\ub7ec\ub098 \ubb38\uc81c\ub97c \uc54c\uc544\ucc28\ub9ac\ub294 \uac83\uacfc \uc2e4\uc81c\ub85c \uad8c\ub825\uc758 \ubc29\ud5a5\uc744 \ubc14\uafb8\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \ubc30 \uc548\uc758 \uc704\uacc4\uc640 \uac1c\uc778\uc758 \ub9dd\uc124\uc784\uc774 \ud568\uaed8 \uc791\uc6a9\ud55c\ub2e4. \uadf8\ub798\uc11c \ud53c\ucffc\ub4dc\ud638\ub97c \uad11\uc778 \ud55c \uba85\uacfc \uc544\ubb34 \uc0dd\uac01 \uc5c6\ub294 \uad70\uc911\uc758 \ubc30\ub85c\ub9cc \uc124\uba85\ud558\uba74 \ubcf5\uc7a1\ud568\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \ub2e4\ub978 \ud310\ub2e8\uacfc \ubd88\uc548\uc774 \uc874\uc7ac\ud574\ub3c4 \uadf8\uac83\uc774 \ud589\ub3d9\uc73c\ub85c \uc774\uc5b4\uc9c0\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uc870\uc9c1\uc774 \uc704\ud5d8\ud55c \uae38\ub85c \uc6c0\uc9c1\uc77c \ub54c \ubc18\ub300\uc758 \ubaa9\uc18c\ub9ac\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ucda9\ubd84\ud55c\uc9c0 \uc9c8\ubb38\ud558\uac8c \ub41c\ub2e4. \ubaa8\ube44 \ub515\uc740 \uc5d0\uc774\ud574\ube0c\uc5d0\uac8c \uc790\uc2e0\uc758 \uc0c1\ucc98\uc640 \ub9de\uc11c \uc2f8\uc6b8 \ub300\uc0c1\uc774 \ub41c\ub2e4. \uadf8\ub7ec\ub098 \uace0\ub798\uac00 \uc2e4\uc81c\ub85c \uadf8\uac00 \ubd80\uc5ec\ud55c \ub3c4\ub355\uc801 \uc758\ub3c4\ub97c \uac00\uc9c0\uace0 \uc788\ub294\uc9c0\ub294 \ubcc4\uac1c\uc758 \ubb38\uc81c\ub2e4. \uac70\ub300\ud55c \ub3d9\ubb3c\uc758 \uc6c0\uc9c1\uc784\uc5d0 \uc778\uac04\uc774 \uc5bc\ub9c8\ub098 \ub9ce\uc740 \ub73b\uc744 \ub367\ubd99\uc774\ub294\uc9c0 \ubcf4\uac8c \ub41c\ub2e4. \uc790\uc5f0\uc758 \uc874\uc7ac\uc640 \uc778\uac04\uc758 \ud574\uc11d\uc740 \uc644\uc804\ud788 \uacb9\uce58\uc9c0 \uc54a\ub294\ub2e4. \uc791\ud488\uc740 \uace0\ub798\uc758 \ud770\uc0c9\uc5d0\ub3c4 \uc5ec\ub7ec \uac10\uac01\uacfc \uc0dd\uac01\uc744 \uc5f0\uacb0\ud55c\ub2e4. \ud558\ub098\uc758 \uc0c1\uc9d5\uc744 \ud558\ub098\uc758 \uc815\ub2f5\uc73c\ub85c \ud480\uc5b4 \ubc84\ub9ac\uae30 \uc5b4\ub824\uc6b4 \uc774\uc720\ub2e4. \ub3c5\uc790\ub294 \uc120\uc7a5\uc758 \ud655\uc2e0\uc5d0 \uc774\ub04c\ub9ac\uba74\uc11c\ub3c4 \uadf8 \ud655\uc2e0 \ubc16\uc758 \uc138\uacc4\ub97c \uacc4\uc18d \ub9cc\ub09c\ub2e4. \u300e\ubaa8\ube44 \ub515\u300f\uc758 \ub113\uc740 \uc9c0\uc2dd\uacfc \ub2e4\uc591\ud55c \ubaa9\uc18c\ub9ac\uac00 \uc774\ub7f0 \uac70\ub9ac\ub97c \ub9cc\ub4e4\uc5b4 \uc900\ub2e4. \ub9c8\uce68\ub0b4 \ud770 \uace0\ub798\ub97c \ub9cc\ub09c \uc5d0\uc774\ud574\ube0c\ub294 \ucd94\uaca9\uc744 \uba48\ucd94\uc9c0 \uc54a\ub294\ub2e4. \uba70\uce60\uc5d0 \uac78\uce5c \ub300\uacb0 \ub05d\uc5d0 \ubaa8\ube44 \ub515\uc740 \ud53c\ucffc\ub4dc\ud638\ub97c \ud30c\uad34\ud558\uace0 \uc120\uc7a5\uacfc \uc120\uc6d0\ub4e4\uc740 \ubc14\ub2e4\uc5d0 \uc0ac\ub77c\uc9c4\ub2e4. \ubaa9\uc801\uc744 \ub2ec\uc131\ud558\uc9c0 \ubabb\ud55c \uac1c\uc778\uc758 \uc2e4\ud328\ub97c \ub118\uc5b4 \ud568\uaed8 \ud0c4 \uc0ac\ub78c\ub4e4\uc758 \uc0b6\uc774 \ubb34\ub108\uc9c0\ub294 \uacb0\ub9d0\uc774\ub2e4. \ub2e4\ub978 \ubc30 \ub808\uc774\ucca0\ud638\uac00 \uc783\uc5b4\ubc84\ub9b0 \uc0ac\ub78c\uc744 \ucc3e\ub294 \uc7a5\uba74\uacfc \uc5d0\uc774\ud574\ube0c\uc758 \uc120\ud0dd\ub3c4 \ub300\ube44\ub41c\ub2e4. \ub204\uad70\uac00\ub97c \ucc3e\uae30 \uc704\ud574 \ud56d\ub85c\ub97c \ubc14\uafb8\ub294 \uc77c\uacfc \uc790\uc2e0\uc758 \ubaa9\ud45c\ub9cc \ub530\ub77c\uac00\ub294 \uc77c\uc740 \ub2e4\ub978 \uad00\uacc4\ub97c \ub9cc\ub4e0\ub2e4. \ubc14\ub2e4 \uc704\uc758 \uacb0\ub2e8\uc740 \uc6a9\uae30\ub77c\ub294 \ub9d0 \ud558\ub098\ub85c \ud3c9\uac00\ud558\uae30 \uc5b4\ub835\ub2e4. \ubb34\uc5c7\uc744 \uc704\ud574 \ub204\uad6c\ub97c \ub450\uace0 \uac00\ub294\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \uc774\uc288\uba54\uc77c\uc740 \ud034\ud018\uadf8\uc758 \uad00\uc5d0\uc11c \ube44\ub86f\ub41c \ubd80\ud45c\uc5d0 \uae30\ub300\uc5b4 \uc0b4\uc544\ub0a8\uace0 \ub808\uc774\ucca0\ud638\uc5d0 \uad6c\uc870\ub41c\ub2e4. \uc8fd\uc74c\uc744 \uc704\ud574 \ub9cc\ub4e0 \ubb3c\uac74\uc774 \uc0dd\uba85\uc744 \uc9c0\ud0a4\ub294 \ubb3c\uac74\uc774 \ub418\ub294 \ubc18\uc804\uc774\ub2e4. \ub9ce\uc740 \uc0ac\ub78c\uc774 \uc0ac\ub77c\uc9c4 \ub4a4 \uc774\uc57c\uae30\ub97c \uc804\ud558\ub294 \ud55c \ubaa9\uc18c\ub9ac\uac00 \ub0a8\ub294\ub2e4. \ub3c5\uc790\uac00 \uc77d\uc740 \ud56d\ud574 \uc790\uccb4\uac00 \uadf8 \uc0dd\uc874\uc758 \uacb0\uacfc\ub2e4. \u300e\ubaa8\ube44 \ub515\u300f\uc744 \ub05d\uae4c\uc9c0 \uc77d\uc73c\uba74 \uace0\ub798\ub97c \uc774\uae38 \uc218 \uc788\uc5c8\ub294\uac00\ubcf4\ub2e4 \ub354 \ub9ce\uc740 \uc9c8\ubb38\uc774 \ub0a8\ub294\ub2e4. \ub204\uac00 \ubaa9\ud45c\ub97c \uc815\ud588\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc740 \uadf8\uac83\uc744 \uc5b4\ub5bb\uac8c \ubc1b\uc544\ub4e4\uc600\ub294\uac00. \uac70\ub300\ud55c \uc790\uc5f0 \uc55e\uc5d0\uc11c \uc9c0\uc2dd\uacfc \uc758\uc9c0\ub294 \uc5b4\ub514\uae4c\uc9c0 \uc720\ud6a8\ud55c\uac00. \ubc14\ub2e4\ub97c \ud5a5\ud55c \ubaa8\ud5d8\uc740 \uadf8\ub807\uac8c \uc778\uac04\uc774 \ud655\uc2e0\uc744 \uc0ac\uc6a9\ud558\ub294 \ubc29\uc2dd\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\ub85c \ub113\uc5b4\uc9c4\ub2e4."}, {"id": "momotaro-dumplings-and-companions", "title": "\ubaa8\ubaa8\ud0c0\ub85c \u2014 \ubcf5\uc22d\uc544\uc5d0\uc11c \ub098\uc628 \uc18c\ub144\uc5d0\uac8c \ub3d9\ub8cc\uac00 \ud544\uc694\ud588\ub358 \uc774\uc720", "summary": "\ubcf5\uc22d\uc544 \uc18c\ub144\uc758 \uc6d0\uc815\uacfc \uc138 \ub3d9\ubb3c\uc758 \ud611\ub825\uc744 \ub530\ub77c \uc775\uc219\ud55c \uc77c\ubcf8 \uc61b\uc774\uc57c\uae30\ub97c \ub2e4\uc2dc \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc2e0\ud654\uc640 \ubbfc\uc18d", "categories": ["arts"], "url": "stories/momotaro-dumplings-and-companions/index.html", "image": "../media/momotaro-dumplings-and-companions.png", "alt": "\uba39\uc744\uac70\ub9ac \uc8fc\uba38\ub2c8\ub97c \ucc2c \ubaa8\ubaa8\ud0c0\ub85c\uac00 \uac1c\u00b7\uc6d0\uc22d\uc774\u00b7\uafe9\uacfc \ud568\uaed8 \uac15\uac00\uc758 \uae38\uc744 \uac77\ub294 \uc61b\uc774\uc57c\uae30 \uc0bd\ud654", "text": "\ubaa8\ubaa8\ud0c0\ub85c \u2014 \ubcf5\uc22d\uc544\uc5d0\uc11c \ub098\uc628 \uc18c\ub144\uc5d0\uac8c \ub3d9\ub8cc\uac00 \ud544\uc694\ud588\ub358 \uc774\uc720 \uac1c\uc640 \uc6d0\uc22d\uc774\uc640 \uafe9, \uba39\uc744 \uac83\uc744 \ub098\ub204\uba70 \uc2dc\uc791\ub41c \ubaa8\ud5d8 \ubcf5\uc22d\uc544 \uc18c\ub144\uc758 \uc6d0\uc815\uacfc \uc138 \ub3d9\ubb3c\uc758 \ud611\ub825\uc744 \ub530\ub77c \uc775\uc219\ud55c \uc77c\ubcf8 \uc61b\uc774\uc57c\uae30\ub97c \ub2e4\uc2dc \uc77d\uc2b5\ub2c8\ub2e4. \uc2e0\ud654\uc640 \ubbfc\uc18d \ubb38\ud654\uc640 \uc608\uc220 \ud070 \ubcf5\uc22d\uc544\ub97c \uac08\ub790\ub354\ub2c8 \uc544\uc774\uac00 \ub098\uc628\ub2e4. \uc5ec\uae30\uae4c\uc9c0\ub9cc \ub4e4\uc5b4\ub3c4 \ubcf4\ud1b5\uc758 \ucd9c\uc0dd \uc774\uc57c\uae30\ub294 \uc544\ub2c8\ub2e4. \uc77c\ubcf8\uc758 \uc61b\uc774\uc57c\uae30 \ubaa8\ubaa8\ud0c0\ub85c\ub294 \uac15\uc5d0\uc11c \uac74\uc9c4 \ubcf5\uc22d\uc544\uc640 \uc544\uc774\ub97c \ubc14\ub77c\ub358 \ub178\ubd80\ubd80\uc5d0\uac8c\uc11c \uc2dc\uc791\ud55c\ub2e4. \ud6d7\ub0a0 \ubaa8\ud5d8\uc744 \ub5a0\ub098\ub294 \uc18c\ub144\uc758 \uc774\ub984\ub3c4 \uc774 \ubcf5\uc22d\uc544\uc640 \uc774\uc5b4\uc9c4\ub2e4. \uc6b0\ub9ac\ub294 \ud754\ud788 \ub3c4\uae68\ube44\ub97c \ubb3c\ub9ac\uce5c \uc601\uc6c5\uc73c\ub85c \uadf8\ub97c \uae30\uc5b5\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc774\uc57c\uae30\uc758 \uac00\uc6b4\ub370\ub97c \ucc9c\ucc9c\ud788 \uc77d\uc5b4 \ubcf4\uba74 \uc18c\ub144 \ud63c\uc790 \ud798\uc744 \uc4f0\ub294 \uc7a5\uba74\ub9cc \uc788\uc9c0\ub294 \uc54a\ub2e4. \uba39\uc744 \uac83\uc744 \ub098\ub204\uace0, \uc11c\ub85c \ub2e4\ud22c\ub294 \ub3d9\ubb3c\ub4e4\uc744 \uc774\ub04c\uace0, \ub2e4\ub978 \ub2a5\ub825\uc744 \uac00\uc9c4 \ub3d9\ub8cc\uc640 \ud568\uaed8 \uc6c0\uc9c1\uc774\ub294 \uacfc\uc815\uc774 \uc788\ub2e4. \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubcf8\ub2e4. \uc624\uc790\ud0a4 \uc608\uc774 \ub370\uc624\ub3c4\ub77c\uc758 \uc601\uc5b4 \uc7ac\uc11c\uc220\uc5d0\uc11c\ub294 \ud560\uba38\ub2c8\uac00 \uac15\uc5d0\uc11c \ube68\ub798\ub97c \ud558\ub2e4\uac00 \ucee4\ub2e4\ub780 \ubcf5\uc22d\uc544\ub97c \ubc1c\uacac\ud55c\ub2e4. \uc9d1\uc5d0 \ub3cc\uc544\uc628 \ub178\ubd80\ubd80\uac00 \uadf8 \ubcf5\uc22d\uc544\ub97c \ub300\ud558\uc790 \uc544\uc774\uac00 \ub098\ud0c0\ub09c\ub2e4. \uc544\uc774\ub294 \uc678\ub85c\uc6e0\ub358 \ub450 \uc0ac\ub78c\uc5d0\uac8c \uc544\ub4e4\ub85c \uc654\ub2e4\uace0 \ub9d0\ud558\uace0, \ubaa8\ubaa8\ud0c0\ub85c\ub77c\ub294 \uc774\ub984\uc744 \uc5bb\ub294\ub2e4. \ud604\uc2e4\uc758 \ucd9c\uc0dd \uae30\ub85d\uc774 \uc544\ub2c8\ub77c \ubbfc\ub2f4\uc758 \uc2dc\uc791\uc774\ub2e4. \ub3cc\ubcfc \uc544\uc774\uac00 \uc5c6\ub358 \ub178\ubd80\ubd80\uc758 \ubc14\ub78c\uc774 \ub73b\ubc16\uc758 \uc120\ubb3c\ub85c \uc751\ub2f5\ubc1b\ub294 \uc7a5\uba74\uc73c\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \ub2e4\ub978 \uc804\uc2b9\uc758 \uc138\ubd80\uac00 \uc774 \ud310\ubcf8\uacfc \ub298 \uac19\uc9c0\ub294 \uc54a\ub2e4. \ud558\ub098\uc758 \uc774\uc57c\uae30\uc5d0\ub294 \uc5ec\ub7ec \uc785\uad6c\uac00 \uc788\uc744 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ucc98\uc74c\ubd80\ud130 \uae30\uc5b5\ud574 \ub450\uba74 \uc88b\ub2e4. \ubaa8\ubaa8\ud0c0\ub85c\ub294 \ud798\uacfc \uc6a9\uae30\ub97c \uac16\ucd98 \uc18c\ub144\uc73c\ub85c \uc790\ub780\ub2e4. \uadf8\ub9ac\uace0 \uc0ac\ub78c\ub4e4\uc744 \uad34\ub86d\ud788\ub294 \ub3c4\uae68\ube44\ub4e4\uc758 \uc12c\uc73c\ub85c \uac00\uaca0\ub2e4\uace0 \ub9d0\ud55c\ub2e4. \uc790\uc2e0\uc744 \ud0a4\uc6cc \uc900 \ub178\ubd80\ubd80\uc5d0\uac8c \uac10\uc0ac\ud558\uba74\uc11c\ub3c4 \uc548\uc804\ud55c \uc9d1\uc744 \ub5a0\ub098\ub294 \uc120\ud0dd\uc774\ub2e4. \ubbfc\ub2f4\uc740 \uc18c\ub144\uc774 \ud798\uc744 \uc5bb\uc5c8\ub2e4\ub294 \uc124\uba85\uc5d0\uc11c \uadf8 \ud798\uc744 \uc5b4\ub514\uc5d0 \uc0ac\uc6a9\ud560\uc9c0\ub85c \ub118\uc5b4\uac04\ub2e4. \uadf8\ub97c \ubcf4\ub0b4\ub294 \uc0ac\ub78c\ub4e4\uc740 \uba39\uc744 \uac83\uc744 \ub9c8\ub828\ud574 \uc900\ub2e4. \ub110\ub9ac \uc54c\ub824\uc9c4 \uc804\uc2b9\uc5d0\uc11c\ub294 \uae30\ube44\ub2f9\uace0\uac00 \uc720\uba85\ud558\uc9c0\ub9cc, \uc5ec\uae30\uc11c \ucc38\uace0\ud55c \uc601\uc5b4 \ud310\ubcf8\uc740 \uae38\uc5d0\uc11c \ub098\ub20c \ub5a1\uacfc \uacfc\uc790\ub97c \uc911\uc2ec\uc73c\ub85c \uc11c\uc220\ud55c\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ud310\ubcf8\uc758 \ud45c\ud604\uc744 \ud55c \ubb38\uc7a5\uc5d0 \ubaa8\uc544 \uc720\uc77c\ud55c \uc815\ub2f5\ucc98\ub7fc \ub9cc\ub4e4\uc9c0\ub294 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uae38\uc5d0\uc11c \uc18c\ub144\uc740 \uac1c\uc640 \uc6d0\uc22d\uc774, \uafe9\uc744 \ucc28\ub840\ub85c \ub9cc\ub09c\ub2e4. \uba39\uc744 \uac83\uc744 \ub098\ub204\ub294 \uc7a5\uba74\uacfc \ub3d9\ud589\uc758 \uc57d\uc18d\uc774 \uc5f0\uacb0\ub41c\ub2e4. \ubc30\ub0ad \uc18d \uc74c\uc2dd\uc740 \ud5c8\uae30\ub97c \ub2ec\ub798\ub294 \uc900\ube44\ubb3c\uc774\uba74\uc11c \uad00\uacc4\ub97c \ub9cc\ub4dc\ub294 \uacc4\uae30\ub3c4 \ub41c\ub2e4. \ud070 \ubaa8\ud5d8\uc744 \uc2dc\uc791\ud55c \ub4a4\uc5d0\ub3c4 \uc544\uc8fc \uc77c\uc0c1\uc801\uc778 \ud544\uc694\uac00 \uc0ac\ub77c\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uc74c\uc2dd \ud558\ub098\ub85c \uce5c\uad6c\ub97c \uc0b0\ub2e4\ub294 \uad50\ud6c8\uc73c\ub85c \uc904\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774 \uc7a5\uba74\uc758 \uc7ac\ubbf8\ub294 \uc804\ud600 \ub2e4\ub978 \uc874\uc7ac\ub4e4\uc774 \uac19\uc740 \uae38\uc744 \uac00\uae30 \uc2dc\uc791\ud55c\ub2e4\ub294 \ub370 \uc788\ub2e4. \ucc98\uc74c\ubd80\ud130 \uce5c\ubc00\ud588\ub358 \ud300\uc774 \uc544\ub2c8\ub77c, \ub9cc\ub0a8\uacfc \ub300\ud654\ub97c \uac70\uccd0 \ud568\uaed8 \uc6c0\uc9c1\uc774\uac8c \ub41c \ud300\uc774\ub2e4. \uc601\uc6c5\uc758 \ud798 \uc606\uc5d0 \uad00\uacc4\ub97c \ub9cc\ub4dc\ub294 \ub2a5\ub825\uc774 \ub193\uc778\ub2e4. \ucc38\uace0 \ud310\ubcf8\uc5d0\uc11c\ub294 \ub3d9\ubb3c\ub4e4 \uc0ac\uc774\uc758 \ub2e4\ud23c\uacfc \uacac\uc81c\ub3c4 \ub098\uc628\ub2e4. \uac1c\ub294 \uc0c8 \ub3d9\ub8cc\ub97c \ubc18\uae30\uae30\ub9cc \ud558\uc9c0 \uc54a\uace0, \uc18c\ub144\uc740 \uadf8 \uac08\ub4f1\uc744 \uc870\uc815\ud574\uc57c \ud55c\ub2e4. \ub3d9\ub8cc\uac00 \ub298\uc5b4\ub09c\ub2e4\ub294 \uac83\uc740 \ud798\uc774 \ub298\uc5b4\ub098\ub294 \uc77c\uc774\uba74\uc11c \uc11c\ub85c \ub2e4\ub978 \uc131\uaca9\uc744 \uac10\ub2f9\ud558\ub294 \uc77c\uc774\uae30\ub3c4 \ud558\ub2e4. \uc774 \ub300\ubaa9 \ub355\ubd84\uc5d0 \uc774\uc57c\uae30\ub294 \ub2e8\uc21c\ud55c \ub3d9\ubb3c \uba85\ub2e8\ubcf4\ub2e4 \uc0b4\uc544 \uc788\uac8c \ub290\uaef4\uc9c4\ub2e4. \ud611\ub825\uc740 \uc544\ubb34 \ubb38\uc81c\ub3c4 \uc5c6\ub294 \uc0ac\ub78c\ub07c\ub9ac \ubaa8\uc774\ub294 \uac83\ub9cc\uc744 \ub73b\ud558\uc9c0 \uc54a\ub294\ub2e4. \uac19\uc740 \ubaa9\uc801\uc744 \ud5a5\ud574 \uac08 \ub54c \ubb34\uc5c7\uc744 \uba48\ucd94\uace0 \uc5b4\ub5a4 \uc57d\uc18d\uc744 \uc9c0\ud0ac\uc9c0 \uc815\ud558\ub294 \uacfc\uc815\uc774 \ud544\uc694\ud558\ub2e4. \uc61b\uc774\uc57c\uae30\uc758 \uc775\uc219\ud55c \ud589\ub82c\uc5d0\ub3c4 \uc791\uc740 \uae34\uc7a5\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ub3c4\uae68\ube44\uc758 \uc12c\uc5d0 \ub3c4\ucc29\ud558\uba74 \ub3d9\ubb3c\ub4e4\uc740 \uac01\uc790\uc758 \ubc29\uc2dd\uc73c\ub85c \ubaa8\ud5d8\uc5d0 \ucc38\uc5ec\ud55c\ub2e4. \ub0a0 \uc218 \uc788\ub294 \uc0c8\uc640 \ub545\uc5d0\uc11c \uc6c0\uc9c1\uc774\ub294 \ub3d9\ubb3c\uc740 \uac19\uc740 \uc77c\uc744 \ud558\uc9c0 \uc54a\ub294\ub2e4. \uc18c\ub144\uc758 \uc6a9\uac10\ud568\ub9cc\uc73c\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\ub294 \ud611\ub825\uc758 \uc7a5\uba74\uc774\ub2e4. \ud568\uaed8 \uac04 \ub3d9\ub8cc\ub4e4\uc774 \uc774\uc57c\uae30\uc758 \uc7a5\uc2dd\uc774 \uc544\ub2cc \uc774\uc720\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \ub2e4\ub9cc \ud3ed\ub825\uc744 \uc2e0\ub098\ub294 \uc2b9\ub9ac\ub85c\ub9cc \uc77d\uc9c0 \uc54a\uc744 \uc5ec\uc9c0\ub3c4 \uc788\ub2e4. \uc774 \ud310\ubcf8\uc740 \ub3c4\uae68\ube44\ub4e4\uc744 \uc0ac\ub78c\uc744 \uad34\ub86d\ud788\uace0 \uc7ac\ubb3c\uc744 \ube7c\uc557\uc740 \uc874\uc7ac\ub85c \uc81c\uc2dc\ud55c\ub2e4. \uc6b0\ub9ac\ub294 \uadf8 \uc11c\uc0ac\uc758 \uc7a5\uce58\ub97c \uc774\ud574\ud558\uba74\uc11c\ub3c4, \ud604\uc2e4\uc5d0\uc11c \ub0af\uc120 \uc9d1\ub2e8\uc744 \ub3c4\uae68\ube44\ucc98\ub7fc \ubd80\ub974\ub294 \ud0dc\ub3c4\uae4c\uc9c0 \ubc1b\uc544\ub4e4\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \ubbfc\ub2f4\uc758 \uc801\uacfc \uc2e4\uc81c \uc0ac\ub78c\uc740 \ub2e4\ub974\ub2e4. \ubcf5\uc22d\uc544\uc5d0\uc11c \uc544\uc774\uac00 \ub098\uc624\ub294 \uc21c\uac04\uc740 \uc544\uc8fc \uc9e7\uc9c0\ub9cc \uadf8\ub97c \ud0a4\uc6b0\ub294 \ub178\ubd80\ubd80\uc758 \uc2dc\uac04\uc740 \uae38\ub2e4. \ucc38\uace0 \ud310\ubcf8\uc5d0\uc11c \ubaa8\ubaa8\ud0c0\ub85c\ub294 \uc131\uc7a5\ud55c \ub4a4 \uc790\uc2e0\uc744 \ub3cc\ubd10 \uc900 \uc774\ub4e4\uc5d0\uac8c \uac10\uc0ac\ub97c \ub9d0\ud55c\ub2e4. \ud0dc\uc5b4\ub0a0 \ub54c\ubd80\ud130 \ud2b9\ubcc4\ud55c \uc874\uc7ac\uc600\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ub204\uad70\uac00\uc758 \ub3cc\ubd04 \uc18d\uc5d0\uc11c \uc790\ub790\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc11c\ub85c \ubaa8\uc21c\ub418\uc9c0 \uc54a\ub294\ub2e4. \ubbfc\ub2f4\uc740 \uae30\uc801 \ub4a4\uc758 \uad00\uacc4\ub97c \uc644\uc804\ud788 \uc9c0\uc6cc \ubc84\ub9ac\uc9c0 \uc54a\ub294\ub2e4. \uadf8 \uc810\uc744 \uae30\uc5b5\ud558\uba74 \ub9c8\uc9c0\ub9c9 \uadc0\ud658\ub3c4 \ub2ec\ub9ac \ubcf4\uc778\ub2e4. \ub5a0\ub0a0 \ub54c\uc758 \uc9d1\uc740 \ub4a4\ub85c \ubc84\ub9b0 \uacfc\uac70\uac00 \uc544\ub2c8\ub77c \ub3cc\uc544\uac00 \uacb0\uacfc\ub97c \ub098\ub20c \uc790\ub9ac\uc600\ub2e4. \uc18c\ub144\uc758 \ubaa8\ud5d8\uc744 \uc6a9\uae30\uc758 \uc2dc\ud5d8\uc73c\ub85c \uc77d\uc73c\uba74\uc11c \ub3d9\uc2dc\uc5d0 \ub3cc\ubd04\uc5d0 \ub300\ud55c \uc751\ub2f5\uc73c\ub85c \uc77d\uc744 \uc218\ub3c4 \uc788\ub2e4. \uc2e0\uae30\ud55c \ucd9c\uc0dd\uc758 \uc774\uc57c\uae30\uac00 \ud3c9\ubc94\ud55c \uac10\uc0ac\uc758 \ub9c8\uc74c\uacfc \uc774\uc5b4\uc9c0\ub294 \ub300\ubaa9\uc774, \uc774 \uc61b\uc774\uc57c\uae30\ub97c \ub108\ubb34 \uba40\uc9c0 \uc54a\uac8c \ub290\ub07c\uac8c \ud55c\ub2e4. \ubaa8\ubaa8\ud0c0\ub85c\ub294 \uc2b9\ub9ac\ud558\uace0 \ub3cc\uc544\uc628\ub2e4. \ucc38\uace0 \ud310\ubcf8\uc5d0\uc11c\ub294 \ube7c\uc557\uae34 \uc0ac\ub78c\ub4e4\uc758 \uadc0\ud658\uacfc \ub178\ubd80\ubd80\uc758 \uae30\uc068\ub3c4 \ud568\uaed8 \uc11c\uc220\ub41c\ub2e4. \uc9d1\uc744 \ub5a0\ub098\uae30 \uc804\uc758 \uad00\uacc4\uac00 \uacb0\ub9d0\uc5d0\uc11c \ub2e4\uc2dc \ub098\ud0c0\ub09c\ub2e4. \ubaa8\ud5d8\uc740 \uba40\ub9ac \uac14\ub2e4 \uc654\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\uace0, \uadf8 \uacb0\uacfc\ub97c \ub204\uad6c\uc640 \ub098\ub204\ub294\uc9c0\ub85c \ub9c8\ubb34\ub9ac\ub41c\ub2e4. \ub2e4\uc2dc \uc81c\ubaa9\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ubcf5\uc22d\uc544\uc5d0\uc11c \ub098\uc628 \uc18c\ub144\uc774\ub77c\ub294 \uc2e0\uae30\ud55c \ucd9c\uc0dd\uc774 \uc774\uc57c\uae30\ub97c \uc2dc\uc791\ud588\uc9c0\ub9cc, \ub05d\uae4c\uc9c0 \ub530\ub77c\uc624\uac8c \ud558\ub294 \uac83\uc740 \uadf8 \ud63c\uc790\ub9cc\uc758 \ud2b9\ubcc4\ud568\uc774 \uc544\ub2c8\ub2e4. \uae38\uc5d0\uc11c \ub9cc\ub09c \ub2e4\ub978 \uc874\uc7ac\ub4e4\uacfc \uc5b4\ub5bb\uac8c \ud55c \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc600\ub294\uc9c0\uac00 \ub0a8\ub294\ub2e4. \uc791\uc740 \uba39\uc744\uac70\ub9ac \ud558\ub098\uac00 \uae34 \ubaa8\ud5d8\uc758 \ud55c\uac00\uc6b4\ub370 \uc788\uc5c8\ub358 \uc148\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \uc774 \uc774\uc57c\uae30\ub97c \ub2e4\uc2dc \ub4e3\ub294\ub2e4\uba74 \ub3d9\ubb3c\uc758 \uc21c\uc11c\uc640 \uba39\uc744 \uac83\uc744 \uac74\ub124\ub294 \ub300\ud654\ub97c \uc0b4\ud3b4\ubcf4\uc790. \uc775\uc219\ud55c \uc904\uac70\ub9ac\uc5d0 \uc870\uae08 \ub2e4\ub978 \uc138\ubd80\uac00 \uc788\uc744 \uc218 \uc788\ub2e4. \ud310\ubcf8\ub9c8\ub2e4 \ub2ec\ub77c\uc9c0\ub294 \uc791\uc740 \uc7a5\uba74\uc744 \ubc1c\uacac\ud558\ub294 \uac83\ub3c4 \uc61b\uc774\uc57c\uae30\ub97c \uc77d\ub294 \uc990\uac70\uc6c0\uc774\ub2e4."}, {"id": "mona-lisa-looking-guide", "title": "\ubaa8\ub098\ub9ac\uc790 \u2014 \ubbf8\uc18c\uc640 \uc190, \uadf8\ub9ac\uace0 \uadf8\ub9bc\uc774 \uc0ac\ub77c\uc9c4 \ud574", "summary": "\uc190\uacfc \ud48d\uacbd\uc744 \ubcf4\ub294 \ubc29\ubc95\uc5d0 1911\ub144 \ub3c4\ub09c\uc758 \ub3d9\uc2dc\ub300 \uae30\ub85d\uc744 \ub354\ud574 \uc791\ud488\uacfc \uba85\uc131\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/mona-lisa-looking-guide/index.html", "image": "../media/mona-lisa-looking-guide.jpg", "alt": "\ub808\uc624\ub098\ub974\ub3c4 \ub2e4\ube48\uce58, \ubaa8\ub098\ub9ac\uc790 \u00b7 \uc61b \ub8e8\ube0c\ub974 \ub3c4\ub85d\uc758 \ud68c\ud654 \uc7ac\ud604\ub3c4\ud310", "text": "\ubaa8\ub098\ub9ac\uc790 \u2014 \ubbf8\uc18c\uc640 \uc190, \uadf8\ub9ac\uace0 \uadf8\ub9bc\uc774 \uc0ac\ub77c\uc9c4 \ud574 \ucd08\uc0c1 \uc18d \uc778\ubb3c\uacfc \ud48d\uacbd, 1911\ub144 \ub3c4\ub09c\uc774 \ub0a8\uae34 \uae30\ub85d \uc190\uacfc \ud48d\uacbd\uc744 \ubcf4\ub294 \ubc29\ubc95\uc5d0 1911\ub144 \ub3c4\ub09c\uc758 \ub3d9\uc2dc\ub300 \uae30\ub85d\uc744 \ub354\ud574 \uc791\ud488\uacfc \uba85\uc131\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \ubaa8\ub098\ub9ac\uc790 \uc55e\uc5d0 \uc11c\uba74 \ubbf8\uc18c\ub97c \uba3c\uc800 \ud655\uc778\ud558\uac8c \ub41c\ub2e4. \uadf8\ub7f0\ub370 \uc774 \uadf8\ub9bc\uc740 \uc785\uac00 \ud558\ub098\ub9cc\uc73c\ub85c \uc720\uba85\ud574\uc9c4 \uc791\ud488\uc774 \uc544\ub2c8\ub2e4. \uc778\ubb3c\uacfc \ud48d\uacbd\uc744 \uc5ee\uc740 \ud68c\ud654\uc774\uba74\uc11c, \uc774\ub984\uacfc \ud574\uc11d\uc774 \uc313\uc774\uace0 \ub3c4\ub09c\uae4c\uc9c0 \uacaa\uc73c\uba70 \uc0ac\ub78c\ub4e4\uc758 \uad00\uc2ec \uc18d\uc5d0 \uc0b4\uc544\uc628 \ubb3c\uac74\uc774\uae30\ub3c4 \ud558\ub2e4. \uc774\ubc88\uc5d0\ub294 \uadf8\ub9bc \uc18d\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \uae38\uacfc \uadf8\ub9bc \ubc14\uae65\uc758 \uc5ed\uc0ac\ub97c \ud568\uaed8 \uac78\uc5b4 \ubcf4\uc790. \ubb34\uc5c7\uc744 \uadf8\ub838\ub294\uc9c0 \uc54c\uba74 \uc5bc\uad74\uc774 \uac00\uae4c\uc6cc\uc9c0\uace0, \ub204\uad70\uac00 \uc774 \uc791\ud488\uc744 \uac00\uc838\uac00 \ubc84\ub838\ub2e4\ub294 \uc0ac\uac74\uc744 \uc54c\uba74 \ubc15\ubb3c\uad00\uc5d0 \uac78\ub9b0 \uadf8\ub9bc\uc744 \ubcf4\ub294 \uac10\uac01\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \ub974\ub124\uc0c1\uc2a4 \ud654\uac00 \ub808\uc624\ub098\ub974\ub3c4 \ub2e4\ube48\uce58\uac00 \uadf8\ub9b0 \uc774 \ucd08\uc0c1\uc740 \ub9ac\uc790 \uac8c\ub77c\ub974\ub514\ub2c8\ub97c \ubaa8\ub378\ub85c \ud55c \uac83\uc73c\ub85c \uc54c\ub824\uc838 \uc788\ub2e4. \ub0a8\ud3b8\uc758 \uc131 \uc870\ucf58\ub3c4\uc640 \uc5f0\uacb0\ub41c \uc774\ub984\uc73c\ub85c \uc774\ud0c8\ub9ac\uc544\uc5b4 \ub77c \uc870\ucf58\ub2e4, \ud504\ub791\uc2a4\uc5b4 \ub77c \uc870\ucf69\ub4dc\ub77c\uace0\ub3c4 \ubd88\ub9b0\ub2e4. \u2018\ubaa8\ub098\ub9ac\uc790\u2019\uc640 \u2018\ub77c \uc870\ucf69\ub4dc\u2019\uac00 \uc11c\ub85c \ub2e4\ub978 \uadf8\ub9bc\uc758 \uc774\ub984\uc740 \uc544\ub2c8\ub2e4. \uc720\uba85\ud55c \ubbf8\uc18c\ub77c\ub294 \ub9d0\ub9cc \ub5a0\uc62c\ub9ac\ub2e4\uac00 \ud55c \uc0ac\ub78c\uc758 \ucd08\uc0c1\uc774\ub77c\ub294 \uc0ac\uc2e4\ub85c \ub3cc\uc544\uc624\uba74 \uc9c8\ubb38\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \ubb34\uc5c7\uc744 \uc0dd\uac01\ud574\uc11c \uc6c3\uc5c8\ub290\ub0d0\ub294 \ucd94\uce21\uc5d0 \uc55e\uc11c, \ud654\uac00\uac00 \ud55c \uc778\ubb3c\uc744 \ud654\uba74 \uc548\uc5d0 \uc5b4\ub5bb\uac8c \uc549\ud614\ub294\uc9c0 \ubcf4\uac8c \ub41c\ub2e4. \uadf8\ub9bc \uc18d \ud45c\uc815\ub9cc\uc73c\ub85c \uc2e4\uc81c \ubaa8\ub378\uc758 \uc131\uaca9\uc774\ub098 \ub2f9\uc2dc \uac10\uc815\uae4c\uc9c0 \ud655\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud654\uba74 \uc544\ub798\uc5d0\ub294 \ub450 \uc190\uc774 \uacb9\uccd0\uc838 \uc788\ub2e4. \ubab8\uc740 \uc870\uae08 \ub3cc\ub824 \uc549\uc544 \uc788\uc9c0\ub9cc \uc5bc\uad74\uc740 \uad00\uac1d \ucabd\uc744 \ud5a5\ud55c\ub2e4. \uc190\uc5d0\uc11c \uc5b4\uae68\ub85c, \uc5b4\uae68\uc5d0\uc11c \uc5bc\uad74\ub85c \ub208\uc744 \uc62c\ub9ac\uba74 \uc778\ubb3c \uc804\uccb4\uac00 \ucc28\ubd84\ud558\uac8c \uc790\ub9ac\ub97c \uc7a1\uace0 \uc788\ub2e4\ub294 \ub290\ub08c\uc744 \ubc1b\uc744 \uc218 \uc788\ub2e4. \uc785\uac00\ub9cc \ud655\ub300\ud574 \ubcfc \ub54c\uc640\ub294 \ub2e4\ub978 \uacbd\ud5d8\uc774\ub2e4. \ub208\uae38\uc744 \uc7a1\uc544\ub044\ub294 \ud45c\uc815 \uc544\ub798\uc5d0 \uc190\uacfc \ud314\uc774 \ub9cc\ub4dc\ub294 \uc548\uc815\uac10\uc774 \uc788\ub2e4. \uc5bc\uad74\uc774 \ud63c\uc790 \ub5a0 \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ubab8\uacfc \ud568\uaed8 \uacf5\uac04\uc744 \ucc28\uc9c0\ud55c\ub2e4\ub294 \uc810\uc744 \uc0b4\ud3b4\ubcf4\uc790. \uba85\ud654\ub97c \ubcfc \ub54c \uc138\ubd80 \ud558\ub098\ub97c \uc54c\uace0 \ub098\uba74 \uadf8 \ubd80\ubd84\ub9cc \ud655\uc778\ud558\uae30 \uc26c\uc6b4\ub370, \uc624\ud788\ub824 \uc720\uba85\ud55c \uc138\ubd80\uc5d0\uc11c \uc7a0\uc2dc \ub5a8\uc5b4\uc838\uc57c \uadf8\ub9bc \uc804\uccb4\uac00 \ub2e4\uc2dc \ubcf4\uc774\uae30\ub3c4 \ud55c\ub2e4. \uc778\ubb3c \ub4a4\uc5d0\ub294 \ubc14\uc704\uc640 \ubb3c\uae38, \uad7d\uc774\uce58\ub294 \uae38\uacfc \uba40\ub9ac \uc774\uc5b4\uc9c0\ub294 \ud48d\uacbd\uc774 \ub193\uc5ec \uc788\ub2e4. \uac00\uae4c\uc6b4 \uc5bc\uad74\uacfc \uc190, \uc544\uc8fc \uba3c \ubc30\uacbd\uc774 \ud55c \ud654\uba74\uc5d0 \uacf5\uc874\ud55c\ub2e4. \uc778\ubb3c\uc758 \uc548\uc815\ub41c \uc790\uc138\uc640 \uad74\uace1\uc9c4 \uc9c0\ud615\uc744 \ubc88\uac08\uc544 \ubcf4\uba74 \uadf8\ub9bc\uc774 \ub2e8\uc21c\ud55c \uc99d\uba85\uc0ac\uc9c4\ucc98\ub7fc \ub9cc\ub4e4\uc5b4\uc9c0\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc810\uc744 \ub290\ub084 \uc218 \uc788\ub2e4. \uc774 \ubc30\uacbd\uc774 \uc2e4\uc81c \uc5b4\ub290 \uc7a5\uc18c\uc778\uc9c0 \uc5ec\uae30\uc11c \ud55c \uacf3\uc73c\ub85c \ud655\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud48d\uacbd\uc744 \uc9c0\uba85\uc758 \uc218\uc218\uaed8\ub07c\ub85c\ub9cc \ub2e4\ub8e8\uae30\ubcf4\ub2e4 \uac00\uae4c\uc6b4 \uc0ac\ub78c\uacfc \uba3c \uc138\uacc4\uac00 \uc5b4\ub5a4 \uad00\uacc4\ub97c \uc774\ub8e8\ub294\uc9c0 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uac19\uc740 \ub3c4\ud310\uc5d0\uc11c\ub3c4 \uc5bc\uad74\uc744 \uac00\ub9ac\uace0 \ubc30\uacbd\ub9cc \ubcf8 \ub4a4 \ub2e4\uc2dc \uc804\uccb4\ub97c \ubcf4\uba74 \ucc98\uc74c\uc5d0\ub294 \uc9c0\ub098\ucce4\ub358 \ubd80\ubd84\uc774 \ub208\uc5d0 \ub4e4\uc5b4\uc62c \uc218 \uc788\ub2e4. \uc774 \uc791\ud488\uc758 \uc5ed\uc0ac\uc5d0\ub294 \uc2e4\uc81c \ub3c4\ub09c \uc0ac\uac74\uc774 \uc788\ub2e4. 1911\ub144 \ubaa8\ub098\ub9ac\uc790\ub294 \ub8e8\ube0c\ub974\uc5d0\uc11c \ub3c4\ub09c\ub2f9\ud588\ub2e4. \ubc15\ubb3c\uad00\uc5d0 \uac78\ub9b0 \uba85\ud654\uac00 \ub2f9\uc5f0\ud788 \uadf8 \uc790\ub9ac\uc5d0 \uc788\uc744 \uac83\uc774\ub77c\ub294 \ubbff\uc74c\uc774 \uae68\uc9c4 \uac83\uc774\ub2e4. \uc624\ub298\uc758 \uc804\uc2dc\uc7a5\uc744 \ub5a0\uc62c\ub9ac\uba74 \uba3c \uc774\uc57c\uae30 \uac19\uc9c0\ub9cc, \ub2f9\uc2dc \uc0ac\ub78c\uc5d0\uac8c\ub294 \ubbf8\uc220 \uc791\ud488\uc758 \uac10\uc0c1\uacfc \ubcc4\uac1c\ub85c \uadf8\ub9bc \uc790\uccb4\uc758 \ud589\ubc29\uc774 \ubb38\uc81c\uac00 \ub418\uc5c8\ub2e4. \uadf8 \ucda9\uaca9\uc740 \ub2f9\uc2dc \uc5ec\ud589\ucc45\uc5d0\ub3c4 \ud754\uc801\uc744 \ub0a8\uacbc\ub2e4. E. V. \ub8e8\ucee4\uc2a4\ub294 1912\ub144 \uc11c\ubb38\uc744 \ubd99\uc778 \u300e\ud53c\ub80c\uccb4\ub97c \uac70\ub2d0\ub2e4\u300f\uc5d0\uc11c \ub808\uc624\ub098\ub974\ub3c4\uc758 \ud6fc\uc190\ub418\uac70\ub098 \ubbf8\uc644\uc131\uc73c\ub85c \ub0a8\uc740 \uc791\ud488\ub4e4\uc744 \uc774\uc57c\uae30\ud558\ub2e4\uac00, \ubaa8\ub098\ub9ac\uc790\ub9c8\uc800 1911\ub144 \ub8e8\ube0c\ub974\uc5d0\uc11c \ub3c4\ub09c\ub2f9\ud588\ub2e4\uace0 \ub367\ubd99\uc778\ub2e4. \uc774 \uae30\ub85d\uc5d0\uc11c\ub294 \ubc94\ud589\uc744 \uc18c\uc124\ucc98\ub7fc \uc7ac\ud604\ud558\uae30\ubcf4\ub2e4, \uc774\ubbf8 \uc720\uba85\ud588\ub358 \uadf8\ub9bc\uc758 \ubd80\uc7ac\uac00 \ub3d9\uc2dc\ub300\uc758 \uae00\uc5d0 \ub4e4\uc5b4\uc654\ub2e4\ub294 \uc810\uc744 \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \ub3c4\ub09c \uc9c1\uc804\uc758 \uba85\uc131\uc744 \uc0dd\uac01\ud560 \uc790\ub8cc\ub3c4 \uc788\ub2e4. \ub8e8\ucee4\uc2a4\uc758 \ub2e4\ub978 \ucc45 \u300e\ud30c\ub9ac\ub97c \uac70\ub2d0\ub2e4\u300f\ub294 \ubaa8\ub098\ub9ac\uc790\uac00 \uc5c6\ub294 \ud30c\ub9ac\ub294 \uc6b0\ub9ac\uac00 \uc544\ub294 \ud30c\ub9ac\uac00 \uc544\ub2d0 \uac83\uc774\ub77c\uace0 \ud560 \ub9cc\ud07c \uadf8\ub9bc\uc744 \ub192\uc774 \ud3c9\uac00\ud588\ub2e4. \ub530\ub77c\uc11c \u2018\ub3c4\ub09c \uc804\uc5d0\ub294 \uc544\ubb34\ub3c4 \ubaa8\ub974\ub358 \uadf8\ub9bc\uc778\ub370 \uc0ac\uac74 \ud558\ub098\ub85c \uba85\ud654\uac00 \ub418\uc5c8\ub2e4\u2019\uace0 \ub2e8\uc21c\ud654\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc774\ubbf8 \ud3c9\uac00\ubc1b\ub358 \uc791\ud488\uc5d0 \ub3c4\ub09c\uc774\ub77c\ub294 \uc0c8\ub85c\uc6b4 \uc774\uc57c\uae30\uac00 \ub354\ud574\uc84c\ub2e4\uace0 \ubcf4\ub294 \ud3b8\uc774 \uc790\ub8cc\uc640 \ub9de\ub294\ub2e4. \ud55c \uadf8\ub9bc\uc774 \uc0ac\ub77c\uc84c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub450 \uc885\ub958\uc758 \uac00\uce58\ub97c \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \ud558\ub098\ub294 \ud654\uba74 \uc790\uccb4\uc758 \ud68c\ud654\uc801 \uac00\uce58\uc774\uace0, \ub2e4\ub978 \ud558\ub098\ub294 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uadf8 \uc791\ud488\uc744 \uae30\uc5b5\ud558\uace0 \ub9cc\ub098\uace0 \uc2f6\uc5b4 \ud55c\ub2e4\ub294 \uc0ac\ud68c\uc801 \uac00\uce58\ub2e4. \uc720\uba85\ud55c \uadf8\ub9bc\uc758 \ubd80\uc7ac\uac00 \ud06c\uac8c \ub290\uaef4\uc9c0\ub294 \uac83\uc740 \uac00\uaca9 \ub54c\ubb38\ub9cc\uc774 \uc544\ub2c8\ub77c, \ud568\uaed8 \uacf5\uc720\ud558\ub358 \uc774\ubbf8\uc9c0\uac00 \uc2e4\uc81c \ubb3c\uac74\uc73c\ub85c\ub294 \ub354 \uc774\uc0c1 \uac70\uae30 \uc5c6\uae30 \ub54c\ubb38\uc774\ub2e4. \ub3c4\ub09c\uc744 \uc548 \ub4a4\uc5d0\ub294 \uc791\ud488\uc758 \uc874\uc7ac \ubc29\uc2dd\ub3c4 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uc0ac\uc9c4\uc73c\ub85c\ub294 \uc5bc\uad74\uc744 \uacc4\uc18d \ubcfc \uc218 \uc788\uc5b4\ub3c4, \uc2e4\uc81c \uadf8\ub9bc\uc774 \uc5b4\ub514 \uc788\ub294\uc9c0 \uc54c \uc218 \uc5c6\ub2e4\uba74 \uac19\uc740 \uacbd\ud5d8\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub9bc\uc758 \uc774\ubbf8\uc9c0\ub97c \uc548\ub2e4\ub294 \uac83\uacfc \uadf8 \uc6d0\uc791\uc774 \uc6b0\ub9ac \uacc1\uc5d0 \ub0a8\uc544 \uc788\ub2e4\ub294 \uac83\uc740 \uc11c\ub85c \ub2e4\ub978 \uc77c\uc774\ub2e4. \uc774 \uc0ac\uac74\uc740 \uc720\uba85\ud55c \uc5bc\uad74 \ub4a4\uc5d0 \uc0ac\ub77c\uc9c8 \uc218\ub3c4 \uc788\ub294 \ud55c \uc810\uc758 \ubb3c\uac74\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ub4dc\ub7ec\ub0b8\ub2e4. \ub3c4\ub09c \uc0ac\uac74, \ubcf5\uc81c\ud488, \ucc45\uacfc \uac01\uc885 \ub9e4\uccb4\ub97c \ud1b5\ud574 \uc6b0\ub9ac\ub294 \uc2e4\ubb3c\uc744 \ubcf4\uae30 \uc804\ubd80\ud130 \uc774 \uc5bc\uad74\uc744 \uc548\ub2e4. \ub108\ubb34 \uc775\uc219\ud558\uba74 \uadf8\ub9bc\uc744 \uc9c1\uc811 \uad00\ucc30\ud558\uae30\ubcf4\ub2e4 \u2018\uc720\uba85\ud558\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ud655\uc778\ud558\ub294 \uc77c\u2019\ub85c \uad00\ub78c\uc774 \ub05d\ub0a0 \uc218 \uc788\ub2e4. \uc774 \uc810\uc5d0\uc11c \ubaa8\ub098\ub9ac\uc790\ub294 \uadf8\ub9bc\uc744 \uac10\uc0c1\ud558\ub294 \uc6b0\ub9ac\uc758 \uc2b5\uad00\uae4c\uc9c0 \ub3cc\uc544\ubcf4\uac8c \ud55c\ub2e4. \ub2e4\uc2dc \uc190\uacfc \ubab8, \uc5bc\uad74\uacfc \ud48d\uacbd\uc744 \ucc28\ub840\ub85c \ubcf4\uc790. \ud45c\uc815\uc744 \ud55c \uac00\uc9c0 \uac10\uc815\uc73c\ub85c \uc815\ub9ac\ud558\uc9c0 \uc54a\uace0, \uac00\uae4c\uc774\uc5d0\uc11c \ubcfc \ub54c\uc640 \uc804\uccb4\ub97c \ubcfc \ub54c \uc778\uc0c1\uc774 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0 \ube44\uad50\ud574\ub3c4 \uc88b\ub2e4. \ub204\uad70\uac00\ub294 \ucc28\ubd84\ud568\uc744, \ub204\uad70\uac00\ub294 \uac70\ub9ac\uac10\uc744 \ub290\ub084 \uc218 \uc788\ub2e4. \uc720\uba85\ud55c \uc124\uba85\uc744 \uadf8\ub300\ub85c \ub290\ub07c\uc9c0 \ubabb\ud588\ub2e4\uace0 \uac10\uc0c1\uc5d0 \uc2e4\ud328\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uc61b \ub8e8\ube0c\ub974 \ub3c4\ub85d\uc758 \uc2e4\uc81c \uc791\ud488 \uc0c9\ucc44 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \uc624\ub298\uc758 \uc791\ud488\uc744 \uc0c8\ub85c \ucd2c\uc601\ud55c \uace0\ud574\uc0c1\ub3c4 \uc0ac\uc9c4\uc740 \uc544\ub2c8\ubbc0\ub85c \uc778\uc1c4\uc758 \uc0c9\uacfc \uc138\ubd80\uac00 \uc2e4\ubb3c\uc744 \uc644\uc804\ud788 \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc6d0\uc791\uc758 \uad6c\uc131\uacfc \uc8fc\uc694 \ubd80\ubd84\uc744 \uc0b4\ud3b4\ubcf4\ub294 \uc790\ub8cc\ub85c \uc0ac\uc6a9\ud588\ub2e4. \ubaa8\ub098\ub9ac\uc790\uc5d0\uc11c\ub294 \ud654\uba74\uc744 \ubcf4\ub294 \uc77c\uacfc \uadf8 \ud654\uba74\uc744 \ub458\ub7ec\uc2fc \uc5ed\uc0ac\ub97c \uc77d\ub294 \uc77c\uc774 \ud568\uaed8 \uac00\ub2a5\ud558\ub2e4. \ub3c4\ub09c \uc774\uc57c\uae30\ub97c \uc54c\uace0 \ub098\uc11c \uadf8\ub9bc\uc73c\ub85c \ub3cc\uc544\uc624\uba74 \uc720\uba85\ud55c \ubbf8\uc18c\uac00 \uc870\uae08 \ub2e4\ub978 \uc9c8\ubb38\uc744 \uac74\ub128\ub2e4. \uc6b0\ub9ac\ub294 \uc65c \uc774 \uc0ac\ub78c\uc744 \uae30\uc5b5\ud558\uace0, \uc65c \uc774 \ud55c \uc7a5\uc758 \uadf8\ub9bc\uc744 \ub9cc\ub098\ub7ec \uac00\ub294\uac00. \uc791\ud488\uc758 \uc0ac\uc5f0\uc740 \ub208\uc744 \ub300\uc2e0\ud558\ub294 \uc124\uba85\uc774 \uc544\ub2c8\ub77c, \ub2e4\uc2dc \ubc14\ub77c\ubcfc \uc774\uc720\uac00 \ub420 \uc218 \uc788\ub2e4."}, {"id": "mont-saint-michel-tides-abbey-and-stacked-rooms", "title": "\ubabd\uc0dd\ubbf8\uc178 \u2014 \uc791\uc740 \ubc14\uc704 \uc704\uc5d0 \uc218\ub3c4\uc6d0\uc758 \ud558\ub8e8\ub97c \uc313\ub2e4", "summary": "\ubc14\uc704 \uc704 \uc131\uc18c\ub97c \ub5a0\ubc1b\uce5c \uacf5\ub3d9\uc0dd\ud65c\uacfc \ub9c8\uc744, \ubc29\uc5b4\uc640 \uc804\uc6a9\uc758 \uc2dc\uac04\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uac74\ucd95", "categories": ["arts"], "url": "stories/mont-saint-michel-tides-abbey-and-stacked-rooms/index.html", "image": "../media/mont-saint-michel-tides-abbey-and-stacked-rooms.jpg", "alt": "\ubd81\ucabd\uc5d0\uc11c \ubcf8 \ubabd\uc0dd\ubbf8\uc178\uc758 \uc218\ub3c4\uc6d0\uacfc \ubc14\uc704, \uc131\ubcbd\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc2e4\uc81c \uc5ed\uc0ac \ub3c4\ud310", "text": "\ubabd\uc0dd\ubbf8\uc178 \u2014 \uc791\uc740 \ubc14\uc704 \uc704\uc5d0 \uc218\ub3c4\uc6d0\uc758 \ud558\ub8e8\ub97c \uc313\ub2e4 \uc870\uc218\uc640 \ubc14\uc704, \uc131\ub2f9 \uc544\ub798\uc758 \ubc29\uacfc \uc21c\ub840\uc790\uc758 \ub9c8\uc744 \ubc14\uc704 \uc704 \uc131\uc18c\ub97c \ub5a0\ubc1b\uce5c \uacf5\ub3d9\uc0dd\ud65c\uacfc \ub9c8\uc744, \ubc29\uc5b4\uc640 \uc804\uc6a9\uc758 \uc2dc\uac04\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uac74\ucd95 \ubb38\ud654\uc640 \uc608\uc220 \ubc14\ub2e4\uc640 \ubaa8\ub798 \uc704\ub85c \uc19f\uc740 \ubabd\uc0dd\ubbf8\uc178\uc740 \uba40\ub9ac\uc11c \ubcf4\uba74 \ud558\ub098\uc758 \uc131\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uadf8\ub7ec\ub098 \uc548\uc5d0\ub294 \uc218\ub3c4\uc6d0\uacfc \uc131\ub2f9, \ub9c8\uc744\uacfc \ubc29\uc5b4 \uc2dc\uc124, \uc21c\ub840\uc790\uac00 \ub2e4\ub2c8\ub358 \uae38\uc774 \uacb9\uccd0 \uc788\ub2e4. \ud504\ub791\uc2a4 \ub178\ub974\ub9dd\ub514\uc758 \uc791\uc740 \ubc14\uc704\uc12c\uc774 \uc65c \uc774\ub7f0 \ubaa8\uc2b5\uc744 \uac16\ucd94\uac8c \ub418\uc5c8\ub294\uc9c0, \uc724\uacfd \uc548\uc5d0 \ub4e4\uc5b4 \uc788\ub294 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \ud558\ub8e8\ub97c \uc0dd\uac01\ud558\uba70 \uc77d\uc5b4 \ubcf4\uc790. \ubabd\uc0dd\ubbf8\uc178 \uc8fc\ubcc0\uc758 \ud48d\uacbd\uc740 \uc870\uc218\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c4\ub2e4. \ubb3c\uc774 \ubb3c\ub7ec\ub098\uba74 \ub113\uc740 \ubaa8\ub798\uc640 \uac2f\ubc8c\uc774 \ub4dc\ub7ec\ub098\uace0 \ubb3c\uc774 \ucc28\uba74 \ubc14\uc704\uc758 \uace0\ub9bd\uac10\uc774 \ucee4\uc9c4\ub2e4. \uba3c \uacf3\uc5d0\uc11c \ubcf4\uc774\ub294 \ud55c \uc7a5\uba74\uc744 \uc774 \uc7a5\uc18c\uc758 \ud56d\uc0c1 \uac19\uc740 \uc0c1\ud0dc\ub85c \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc774 \ubcc0\ud654\ub294 \uc544\ub984\ub2e4\uc6b4 \ubc30\uacbd\uc744 \ub118\uc5b4 \uc811\uadfc\uacfc \uc774\ub3d9\uc758 \uc870\uac74\uc774\uc5c8\ub2e4. \uc21c\ub840\uc790\uc640 \ubb3c\uc790\ub97c \uc2e4\uc740 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5bb\uac8c \ub3c4\ucc29\ud558\uace0 \ub3cc\uc544\uac00\ub294\uc9c0\uc5d0 \uc601\ud5a5\uc744 \uc8fc\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4. \uc5ec\uae30\uc11c \uc5ed\uc0ac\uc801\uc778 \uae38\uc744 \uc124\uba85\ud558\ub294 \uc77c\uc740 \uc624\ub298\ub0a0 \uac2f\ubc8c\uc744 \ud63c\uc790 \uac74\ub108\ub3c4 \ub41c\ub2e4\ub294 \uc548\ub0b4\uc640 \ub2e4\ub974\ub2e4. \uc2e4\uc81c \uc774\ub3d9\uc740 \ud604\uc7ac\uc758 \uc548\ub0b4\uc640 \ud1b5\uc81c\uc5d0 \ub530\ub77c\uc57c \ud55c\ub2e4. \uc774\ub984\uc758 \ubabd\uc740 \uc0b0\uc774\ub098 \uc5b8\ub355\uc744, \uc0dd\ubbf8\uc178\uc740 \uc131 \ubbf8\uce74\uc5d8\uc744 \uac00\ub9ac\ud0a8\ub2e4. \uc624\ubca0\ub974 \uc8fc\uad50\uac00 \ucc9c\uc0ac\uc758 \uc9c0\uc2dc\ub97c \ubc1b\uc558\ub2e4\ub294 \uc804\uc2b9\uc774 \uc131\uc18c\uc758 \uae30\uc6d0\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc804\uc2b9 \uc18d \uae30\uc801\uacfc \uc774\ud6c4\uc758 \uac74\ucd95\u00b7\uc81c\ub3c4\uc5d0 \uad00\ud55c \uc5ed\uc0ac\ub97c \uad6c\ubd84\ud558\uba74 \uc774\uc57c\uae30\ub97c \ub354 \uc815\ud655\ud558\uac8c \uc77d\uc744 \uc218 \uc788\ub2e4. 10\uc138\uae30\uc5d0\ub294 \ubca0\ub124\ub515\ub3c4\ud68c \uc218\ub3c4 \uacf5\ub3d9\uccb4\uac00 \uc790\ub9ac \uc7a1\uc73c\uba70 \uc7a5\uc18c\uc758 \uc131\uaca9\uc774 \ub69c\ub837\ud574\uc84c\ub2e4. \uc774\ud6c4 \uac74\ubb3c\uc740 \uc5ec\ub7ec \uc138\ub300\uc5d0 \uac78\uccd0 \ucee4\uc9c0\uace0 \ub2ec\ub77c\uc84c\ub2e4. \uc624\ub298 \ubcf4\uc774\ub294 \uc218\ub3c4\uc6d0\uc744 \ud55c \uc0ac\ub78c\uc758 \uccad\uc0ac\uc9c4\uc774 \ud55c \ubc88\uc5d0 \uc2e4\ud604\ub41c \uacb0\uacfc\ub85c \uc0c1\uc0c1\ud558\uae30\ubcf4\ub2e4, \ub367\ub300\uace0 \uace0\uce5c \uc2dc\uac04\uc758 \ucd95\uc801\uc73c\ub85c \ubcf4\ub294 \ud3b8\uc774 \uc54c\ub9de\ub2e4. \uac74\ubb3c\uc758 \uc2dc\ub300\ub97c \uad6c\ubd84\ud558\uba74 \uc591\uc2dd\uc758 \ucc28\uc774\ub3c4 \ub2e8\uc21c\ud55c \uc7a5\uc2dd \ucde8\ud5a5 \uc774\uc0c1\uc758 \uc758\ubbf8\ub97c \uac16\ub294\ub2e4. \uad6c\uc870\ub97c \ubcf4\uac15\ud558\uac70\ub098 \ubb34\ub108\uc9c4 \uacf3\uc744 \uc0c8\ub85c \ub9cc\ub4e4\uba74\uc11c \uac01 \uc2dc\ub300\uc758 \uae30\uc220\uc774 \ub354\ud574\uc84c\ub2e4. \uc624\ub798\ub418\uc5c8\ub2e4\ub294 \ub9d0 \uc548\uc5d0\ub294 \uac19\uc740 \ubaa8\uc2b5\uc73c\ub85c \ubc84\ud2f4 \uc2dc\uac04\uacfc \ub2ec\ub77c\uc9c0\uba70 \uc0b4\uc544\ub0a8\uc740 \uc2dc\uac04\uc774 \ud568\uaed8 \uc788\ub2e4. \ubc14\uc704\uc758 \ub113\uc774\ub294 \uc81c\ud55c\ub418\uc5b4 \uc788\uace0 \uacbd\uc0ac\ub294 \uac00\ud30c\ub974\ub2e4. \uc131\ub2f9\ucc98\ub7fc \ud070 \uacf5\uac04\uc744 \uc704\uc5d0 \ub450\ub824\uba74 \uc544\ub798\uc758 \ubc14\uc704\uc640 \ubc1b\uce68 \uad6c\uc870, \uadf8 \uc8fc\ubcc0\uc758 \uc5ec\ub7ec \ubc29\uc774 \ud568\uaed8 \uc791\ub3d9\ud574\uc57c \ud55c\ub2e4. \uac74\ubb3c\uc740 \ud3c9\uc9c0\uc5d0\uc11c \uc606\uc73c\ub85c \ub298\uc5b4\ub098\ub294 \ub300\uc2e0 \ub192\ub0ae\uc774\ub97c \uc774\uc6a9\ud574 \ubcf5\uc7a1\ud558\uac8c \uacb9\uccd0\uc9c4\ub2e4. \uac89\uc5d0\uc11c \ubcf4\uc774\ub294 \uac70\ub300\ud55c \ubcbd\uc740 \uc5b4\ub290 \ud55c \ubc29\uc758 \ubcbd\ub9cc\uc774 \uc544\ub2d0 \uc218 \uc788\ub2e4. \uc704\uc5d0\ub294 \uc608\ubc30\uc758 \uacf5\uac04, \ub2e4\ub978 \ub192\uc774\uc5d0\ub294 \uacf5\ub3d9\uc0dd\ud65c\uacfc \uc2dd\uc0ac, \uc800\uc7a5\uacfc \ucd9c\uc785\uc758 \uacf5\uac04\uc774 \ub193\uc778\ub2e4. \ub2e8\uba74\ub3c4\ub97c \ub5a0\uc62c\ub9ac\uba70 \uc5ec\ub7ec \uce35\uc774 \uc5b4\ub5a4 \ubb34\uac8c\uc640 \ud65c\ub3d9\uc744 \uc9c0\ud0f1\ud558\ub294\uc9c0 \uc0dd\uac01\ud558\uba74 \uc131 \uac19\uc740 \uc678\uc591\uc774 \ub2e4\ub978 \uc758\ubbf8\ub97c \uac16\ub294\ub2e4. \ubd81\ucabd\uc758 \uace0\ub515 \uc218\ub3c4\uc6d0 \uac74\ubb3c\uad70\uc740 \uba54\ub974\ubca0\uc720\ub77c\ub294 \uc774\ub984\uc73c\ub85c \uc54c\ub824\uc84c\ub2e4. \ud754\ud788 \uacbd\uc774\ub85c\uc6c0\uc774\ub77c\ub294 \ub73b\uacfc \uc5f0\uacb0\ub418\ub294 \uc774\ub984\uc774\ub2e4. \ub192\uc740 \uacf3\uc758 \ud68c\ub791\uacfc \uc2dd\ub2f9, \uc544\ub798\ucabd\uc758 \uc5ec\ub7ec \ud640\uacfc \uc2e4\ubb34 \uacf5\uac04\uc744 \ubcf4\uba74 \uc218\ub3c4\uc6d0\uc758 \ud558\ub8e8\uac00 \uae30\ub3c4\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\uc558\uc74c\uc744 \uc54c \uc218 \uc788\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \uba39\uace0 \uacf5\ubd80\ud558\uace0 \uc190\ub2d8\uc744 \ub9de\uc558\uc73c\uba70 \ubb3c\uac74\uc744 \ubcf4\uad00\ud588\ub2e4. \uac74\ubb3c \uc548\uc758 \uc7a5\uc2dd\uacfc \ub3d9\uc120\uc740 \uadf8\ub7f0 \ud589\uc704\ub97c \ub098\ub204\uace0 \uc5f0\uacb0\ud55c\ub2e4. \uc544\ub984\ub2e4\uc6b4 \uae30\ub465 \ud558\ub098\ub9cc \uac10\uc0c1\ud558\ub294 \ub370\uc11c \ub354 \ub098\uc544\uac00 \uadf8\uacf3\uc774 \ub204\uad6c\uc758 \uc774\ub3d9\uc744 \ud5c8\uc6a9\ud558\uace0 \uc5b4\ub290 \ud65c\ub3d9\uc744 \ud488\uc5c8\ub294\uc9c0 \ubb3b\ub294 \uac83\uc774 \uac74\ucd95\uc744 \uc77d\ub294 \ubc29\ubc95\uc774\ub2e4. \uc21c\ub840 \uc5ed\uc2dc \ud55c \uc0ac\ub78c\uc758 \ub9c8\uc74c\uc18d \uc2e0\uc559\uc73c\ub85c\ub9cc \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\uc558\ub2e4. \uba3c \uacf3\uc5d0\uc11c \uc624\ub294 \uae38\uacfc \uba39\uc744 \uac83, \uc7a0\uc790\ub9ac\uc640 \uc548\ub0b4\uac00 \ud544\uc694\ud588\ub2e4. \ub192\uc740 \uc131\uc18c\ub97c \uac00\ub2a5\ud558\uac8c \ud55c \uac83\uc740 \uc544\ub798\uc5d0\uc11c \ubc18\ubcf5\ub41c \ud3c9\ubc94\ud55c \uc77c\ub4e4\uc774\uae30\ub3c4 \ud588\ub2e4. \ub9c8\uc744\uc758 \uae38\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud560 \uc774\uc720\ub2e4. \ud68c\ub791\uc740 \uc9c0\ubd95 \uc544\ub798 \ud1b5\ub85c\uc640 \uac00\uc6b4\ub370\uc758 \uc5f4\ub9b0 \uacf5\uac04\uc744 \ud568\uaed8 \uac00\uc9c4\ub2e4. \uae30\ub465\uacfc \uc544\uce58\uc758 \ubc18\ubcf5\uc744 \ub530\ub77c \uac77\ub2e4 \ubcf4\uba74 \uba40\ub9ac\uc11c \ubcf4\ub358 \uc218\ub3c4\uc6d0\uc758 \uc555\ub3c4\uc801\uc778 \ub369\uc5b4\ub9ac\uc640 \ub2e4\ub978, \uc791\uace0 \ubc18\ubcf5\uc801\uc778 \ub9ac\ub4ec\uc774 \uc0dd\uae34\ub2e4. \ubc16\uc758 \uad11\ub300\ud55c \ub9cc\uacfc \uc548\uc758 \uc81c\ud55c\ub41c \uacf5\uac04\uc774 \ub300\ube44\ub41c\ub2e4. \uc774\uacf3\uc744 \uc624\ub298\ub0a0\uc758 \uc870\uc6a9\ud55c \uba85\uc0c1 \uc7a5\uc18c\ub85c\ub9cc \ub0ad\ub9cc\ud654\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uacf5\ub3d9\uccb4\uc758 \uaddc\uc728\uacfc \ubc18\ubcf5\ub418\ub294 \uc0dd\ud65c \uc18d\uc5d0 \ub193\uc778 \uac74\ucd95\uc774\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4. \ub204\uac00 \uc5b8\uc81c \uc774 \uae38\uc744 \uc9c0\ub0ac\uc744\uc9c0 \ub5a0\uc62c\ub9ac\uba74 \uc815\uc6d0\uc758 \uc544\ub984\ub2e4\uc6c0\ub3c4 \uc0dd\ud65c\uc758 \uc2dc\uac04\uacfc \uc5f0\uacb0\ub41c\ub2e4. \ubabd\uc0dd\ubbf8\uc178\uc5d0\ub294 \uc218\ub3c4\uc790\ub9cc \uc788\uc5c8\ub358 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc21c\ub840\uc790\uc758 \ubc29\ubb38\uc740 \uc219\ubc15\uacfc \uc74c\uc2dd, \ubb3c\uac74\uc744 \ud30c\ub294 \ub9c8\uc744\uc758 \ud65c\ub3d9\uacfc \uc774\uc5b4\uc84c\ub2e4. \ub192\uc740 \uc131\uc18c\ub85c \uc62c\ub77c\uac00\ub294 \uae38\uc740 \uc885\uad50\uc801 \uc5ec\uc815\uc778 \ub3d9\uc2dc\uc5d0 \ub3c8\uacfc \ubb3c\uc790\uac00 \uc6c0\uc9c1\uc774\ub294 \uae38\uc774\uc5c8\ub2e4. \uc12c\uc758 \uc2e4\ub8e8\uc5e3 \uc544\ub798\uc5d0 \uc774\ub7f0 \uc0dd\ud65c\uc774 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \uc804\uc7c1\uc758 \uc2dc\ub300\uc5d0\ub294 \ubc29\uc5b4 \uc2dc\uc124\ub3c4 \uc911\uc694\ud574\uc84c\ub2e4. \ud2b9\ud788 \ubc31\ub144\uc804\uc7c1\uc758 \ub9e5\ub77d\uc5d0\uc11c \uad73\uac74\ud55c \uc694\uc0c8\ub77c\ub294 \uae30\uc5b5\uc774 \ub354\ud574\uc84c\ub2e4. \ud558\uc9c0\ub9cc \uc131\ubcbd\uc774 \uc788\ub2e4\ub294 \uc774\uc720\ub85c \ucc98\uc74c\ubd80\ud130 \uad70\uc0ac \uae30\uc9c0\uc600\ub2e4\uace0\ub9cc \uc124\uba85\ud558\uba74 \uc131\uc18c\uc640 \uc218\ub3c4\uc6d0, \ub9c8\uc744\uc774 \ub9cc\ub4e0 \uae34 \uc5ed\uc0ac\ub97c \ub193\uce5c\ub2e4. \uc624\ub798\ub41c \ub3c4\ud310 \uac00\uc6b4\ub370\uc5d0\ub294 \uc2e4\uc81c \uad00\ucc30\uacfc \ubcf5\uc6d0 \uc0c1\uc0c1\uc744 \uc11e\uc740 \uadf8\ub9bc\ub3c4 \uc788\ub2e4. \uc774 \uae00\uc740 \ucd9c\ud310 \ub2f9\uc2dc \ubd81\ucabd \uc804\uacbd\uc73c\ub85c \ud45c\uae30\ub41c \ub3c4\ud310\uc744 \uc0ac\uc6a9\ud588\ub2e4. \ucd9c\ucc98\uc758 \uc2dc\uc810\uacfc \uc131\uaca9\uc744 \ud655\uc778\ud558\uba74 \ud604\uc7ac \ubaa8\uc2b5\uacfc \ub2e4\ub978 \ubd80\ubd84\uc744 \ubb34\uc870\uac74 \uacfc\uac70\uc758 \uc0ac\uc2e4\ub85c \ubc1b\uc544\ub4e4\uc774\ub294 \uc77c\uc744 \uc904\uc77c \uc218 \uc788\ub2e4. \ud504\ub791\uc2a4\ud601\uba85 \uc774\ud6c4\uc5d0\ub294 \uac10\uc625\uc73c\ub85c \uc0ac\uc6a9\ub41c \uc2dc\uae30\ub3c4 \uc788\ub2e4. \uac19\uc740 \uac74\ubb3c\uc758 \ubb38\uacfc \ubcbd\uc774 \ub2e4\ub978 \uc81c\ub3c4 \uc544\ub798\uc5d0\uc11c \uc804\ud600 \ub2e4\ub978 \uc758\ubbf8\ub97c \uac16\uac8c \ub41c \uac83\uc774\ub2e4. \uc624\ub298\ub0a0\uc758 \uc720\uc0b0\uc740 \uc911\uc138\uc5d0\uc11c \uadf8\ub300\ub85c \uba48\ucd98 \uacf5\uac04\uc774 \uc544\ub2c8\ub77c \uc774\ud6c4\uc758 \uc804\uc6a9\uacfc \ubcf5\uc6d0\uc744 \ud568\uaed8 \uacaa\uc740 \uc7a5\uc18c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uc61b \ucd9c\ud310\ubb3c\uc758 \uc2e4\uc81c \ubabd\uc0dd\ubbf8\uc178 \ub3c4\ud310\uc774\uba70 \ud604\ub300 \ubc29\ubb38 \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \ubc14\uc704 \uc704\uc5d0 \uce35\uce35\uc774 \uc313\uc778 \uc678\uacfd\uc120\uc744 \ubcf8 \ub4a4 \uc131\ub2f9\uc758 \uc544\ub798\uc640 \ud68c\ub791\uc758 \ubc14\uae65, \ub9c8\uc744\uc758 \uc548\ucabd\uc744 \uc0c1\uc0c1\ud574 \ubcf4\uc790. \uacbd\uad00\uc744 \uc774\ub8e8\ub294 \ub369\uc5b4\ub9ac \uc548\uc5d0\uc11c \uc11c\ub85c \ub2e4\ub978 \uc0b6\uacfc \uc2dc\uac04\uc774 \uc870\uae08\uc529 \uac08\ub77c\uc838 \ubcf4\uc778\ub2e4."}, {"id": "monte-cristo-revenge-and-hope", "title": "\ubaac\ud14c\ud06c\ub9ac\uc2a4\ud1a0 \ubc31\uc791 \u2014 \ubcf5\uc218\uac00 \ub05d\ub098\uba74 \uc0b6\uc740 \ub3cc\uc544\uc62c\uae4c", "summary": "\ub2e8\ud14c\uc2a4\uc758 \ud22c\uc625\uacfc \ud0c8\ucd9c, \uc138 \uc0ac\ub78c\uc744 \ud5a5\ud55c \ubcf5\uc218\uc640 \ub73b\ubc16\uc758 \ud53c\ud574\ub97c \ub530\ub77c \uc791\ud488\uc758 \uc904\uac70\ub9ac\uc640 \uc9c8\ubb38\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/monte-cristo-revenge-and-hope/index.html", "image": "../media/monte-cristo-revenge-and-hope.png", "alt": "\uc80a\uc740 \uc120\uc6d0\uacfc \ubc14\ub2e4 \uac74\ub108 \uc12c\uc758 \uc131\ucc44\ub97c \uadf8\ub9b0 \ubaac\ud14c\ud06c\ub9ac\uc2a4\ud1a0 \ubc31\uc791 \uad00\ub828 \uc0bd\ud654", "text": "\ubaac\ud14c\ud06c\ub9ac\uc2a4\ud1a0 \ubc31\uc791 \u2014 \ubcf5\uc218\uac00 \ub05d\ub098\uba74 \uc0b6\uc740 \ub3cc\uc544\uc62c\uae4c \uac10\uc625\uc5d0\uc11c \uc5bb\uc740 \uc9c0\uc2dd\uacfc \ubcf4\ubb3c\uc774 \ub418\ub3cc\ub824 \uc8fc\uc9c0 \ubabb\ud55c \uac83 \ub2e8\ud14c\uc2a4\uc758 \ud22c\uc625\uacfc \ud0c8\ucd9c, \uc138 \uc0ac\ub78c\uc744 \ud5a5\ud55c \ubcf5\uc218\uc640 \ub73b\ubc16\uc758 \ud53c\ud574\ub97c \ub530\ub77c \uc791\ud488\uc758 \uc904\uac70\ub9ac\uc640 \uc9c8\ubb38\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \uc80a\uc740 \uc120\uc6d0\uc740 \uace7 \uc120\uc7a5\uc774 \ub418\uace0 \uc0ac\ub791\ud558\ub294 \uc0ac\ub78c\uacfc \uacb0\ud63c\ud558\ub9ac\ub77c \ubbff\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \uacb0\ud63c\uc744 \uc55e\ub454 \ub0a0 \uccb4\ud3ec\ub418\uc5b4 \uc12c\uc758 \uac10\uc625\uc73c\ub85c \ubcf4\ub0b4\uc9c4\ub2e4. \uc54c\ub809\uc0c1\ub4dc\ub974 \ub4a4\ub9c8\uc758 \u300e\ubaac\ud14c\ud06c\ub9ac\uc2a4\ud1a0 \ubc31\uc791\u300f\uc740 \ud55c \uc0ac\ub78c\uc5d0\uac8c\uc11c \ubbf8\ub798\ub97c \ube7c\uc557\ub294 \uc0ac\uac74\uc73c\ub85c \uc2dc\uc791\ud55c\ub2e4. \uc774 \uc18c\uc124\uc758 \ucf8c\uac10\uc740 \uc5b5\uc6b8\ud55c \uc0ac\ub78c\uc774 \ud798\uc744 \uc5bb\uc5b4 \ub3cc\uc544\uc624\ub294 \ub370 \uc788\ub2e4. \uadf8\ub7f0\ub370 \ub05d\uae4c\uc9c0 \uc77d\uc73c\uba74 \uc9c8\ubb38\uc774 \uc870\uae08 \ubc14\ub010\ub2e4. \uc6d0\uc218\ub97c \ubb34\ub108\ub728\ub9ac\ub294 \ud798\uc774 \uc783\uc5b4\ubc84\ub9b0 \uc0b6\uae4c\uc9c0 \ub3cc\ub824\uc904 \uc218 \uc788\uc744\uae4c. \uc544\ub798\uc5d0\ub294 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4. 1815\ub144 \ub9c8\ub974\uc138\uc720\uc758 \uc120\uc6d0 \uc5d0\ub4dc\ubabd \ub2e8\ud14c\uc2a4\ub294 \ud56d\ud574 \uc911 \ub9e1\uc740 \ud3b8\uc9c0 \ub54c\ubb38\uc5d0 \ub098\ud3f4\ub808\uc639\uc758 \ubcf5\uadc0\ub97c \ub3d5\ub294 \uc778\ubb3c\ub85c \ubab0\ub9b0\ub2e4. \ub3d9\ub8cc \ub2f9\uae00\ub77c\ub974\ub294 \uadf8\uc758 \uc2b9\uc9c4\uc744 \uc2dc\uae30\ud588\uace0, \ud398\ub974\ub0ad\uc740 \uc57d\ud63c\ub140 \uba54\ub974\uc138\ub370\uc2a4\ub97c \uc6d0\ud588\ub2e4. \uc774\ub4e4\uc740 \uc815\uce58\uc801 \uc758\uc2ec\uc744 \uac1c\uc778\uc758 \uc9c8\ud22c\uc5d0 \uc774\uc6a9\ud55c\ub2e4. \uac80\uc0ac \ube4c\ud3ec\ub974\ub294 \uc0ac\uc815\uc744 \ud655\uc778\ud558\uace0\ub3c4 \ub2e8\ud14c\uc2a4\ub97c \uad6c\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud3b8\uc9c0\uac00 \uc790\uc2e0\uc758 \uc544\ubc84\uc9c0\uc640 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc74c\uc744 \uc54c\uace0 \uacbd\ub825\uc744 \uc9c0\ud0a4\ub824 \ud55c\ub2e4. \uac19\uc740 \ud53c\ud574\uac00 \uc11c\ub85c \ub2e4\ub978 \uc0ac\ub78c\uc758 \uacc4\uc0b0\uc5d0\uc11c \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4. \ub2e8\ud14c\uc2a4\ub294 \uc790\uc2e0\uc774 \uc65c \ubc84\ub824\uc84c\ub294\uc9c0\uc870\ucc28 \uc54c\uae30 \uc5b4\ub835\ub2e4. \uc774\ud504\uc131\uc5d0 \uac07\ud78c \uadf8\ub294 \uc624\ub79c \uc808\ub9dd \ub05d\uc5d0 \ub2e4\ub978 \uc8c4\uc218 \ud30c\ub9ac\uc544 \uc2e0\ubd80\ub97c \ub9cc\ub09c\ub2e4. \ud0c8\ucd9c\uc744 \uc704\ud574 \ud30c\ub358 \ud1b5\ub85c\uac00 \ub450 \uc0ac\ub78c\uc744 \uc774\uc5b4 \uc900\ub2e4. \uc2e0\ubd80\ub294 \ub2e8\ud14c\uc2a4\uc5d0\uac8c \uc5b8\uc5b4\uc640 \ud559\ubb38\uc744 \uac00\ub974\uce58\uace0, \uadf8\uc758 \uc774\uc57c\uae30\ub97c \ub4e3\uace0 \ubc30\uc2e0\uc758 \uad6c\uc870\ub97c \uc9da\uc5b4 \uc900\ub2e4. \uc774 \ub9cc\ub0a8\uc740 \ubcf4\ubb3c\uc758 \uc704\uce58\ub97c \uc54c\ub824 \uc8fc\ub294 \uc7a5\uce58 \uc774\uc0c1\uc774\ub2e4. \ub2e8\ud14c\uc2a4\ub294 \uc0ac\uac74\uc744 \uc774\ud574\ud558\uace0 \ub2e4\ub978 \uc0ac\ud68c\uc5d0\uc11c \ud589\ub3d9\ud560 \uc9c0\uc2dd\uc744 \uc5bb\ub294\ub2e4. \ud6d7\ub0a0 \ubc31\uc791\uc73c\ub85c \ub098\ud0c0\ub0a0 \ub54c \ud544\uc694\ud55c \ud798\uc740 \ub3c8\ubfd0 \uc544\ub2c8\ub77c \uac10\uc625\uc5d0\uc11c \uc0c8\ub85c \ubc30\uc6b4 \ud310\ub2e8\uacfc \uc5b8\uc5b4\uc5d0\ub3c4 \uc788\uc5c8\ub2e4. \ud30c\ub9ac\uc544\uac00 \uc8fd\uc790 \ub2e8\ud14c\uc2a4\ub294 \uc2dc\uc2e0\uc744 \ub123\uc740 \uc790\ub8e8\uc5d0 \ub300\uc2e0 \ub4e4\uc5b4\uac04\ub2e4. \ubc14\ub2e4\uc5d0 \ub358\uc838\uc9c4 \ub4a4 \ube60\uc838\ub098\uc640 \ud0c8\ucd9c\uc5d0 \uc131\uacf5\ud55c\ub2e4. \uc774\ud6c4 \uc2e0\ubd80\uac00 \uc54c\ub824 \uc900 \ubaac\ud14c\ud06c\ub9ac\uc2a4\ud1a0\uc12c\uc758 \ubcf4\ubb3c\uc744 \ucc3e\ub294\ub2e4. \uac10\uc625\uc5d0\uc11c \ubb34\ub825\ud588\ub358 \uc0ac\ub78c\uc5d0\uac8c \ub9c9\ub300\ud55c \uc790\uc6d0\uc774 \uc0dd\uae34 \uac83\uc774\ub2e4. \ud558\uc9c0\ub9cc \uadc0\ud658\ud55c \uc138\uc0c1\uc740 \uae30\ub2e4\ub824 \uc8fc\uc9c0 \uc54a\uc558\ub2e4. \uc544\ubc84\uc9c0\ub294 \uc774\ubbf8 \uc8fd\uc5c8\uace0 \uba54\ub974\uc138\ub370\uc2a4\ub294 \ud398\ub974\ub0ad\uacfc \uacb0\ud63c\ud588\ub2e4. \ub2e8\ud14c\uc2a4\uac00 \ube7c\uc557\uae34 \uac83\uc740 \uc790\uc720\uc640 \uc7ac\uc0b0\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ubcf4\ubb3c\ub85c \uc0b4 \uc218 \uc5c6\ub294 \uc2dc\uac04\uacfc \uad00\uacc4\uac00 \uc0ac\ub77c\uc838 \uc788\uc5c8\ub2e4. \uadf8\ub294 \uc5ec\ub7ec \uc774\ub984\uacfc \uc2e0\ubd84\uc744 \uc0ac\uc6a9\ud558\uba70 \uacfc\uac70\uc758 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uc811\uadfc\ud55c\ub2e4. \ubaac\ud14c\ud06c\ub9ac\uc2a4\ud1a0 \ubc31\uc791\uc740 \uadf8 \uac00\uc6b4\ub370 \uac00\uc7a5 \ub208\ubd80\uc2e0 \uc5bc\uad74\uc774\ub2e4. \ub3c8\uacfc \uc815\ubcf4, \uce58\ubc00\ud55c \uc900\ube44 \ub355\ubd84\uc5d0 \ud30c\ub9ac \uc0ac\uad50\uacc4\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc758 \uad00\uc2ec\uc744 \ub04c \uc218 \uc788\uc5c8\ub2e4. \ubcf5\uc218\ub294 \ub2e8\uc21c\ud55c \uce7c\uc2f8\uc6c0\uc73c\ub85c \uc9c4\ud589\ub418\uc9c0 \uc54a\ub294\ub2e4. \ub204\uac00 \ubb34\uc5c7\uc744 \ub450\ub824\uc6cc\ud558\uace0 \uc5b4\ub514\uc5d0 \ud3c9\ud310\uacfc \uc7ac\uc0b0\uc744 \uac78\uc5c8\ub294\uc9c0 \uc54c\uc544\ub0b8 \ub4a4 \uadf8 \uc57d\uc810\uc744 \uc6c0\uc9c1\uc778\ub2e4. \ub3c8\uc774 \uc815\ubcf4\uc640 \uc2e0\ubd84\uc744 \uc5f4\uc5b4 \uc8fc\ub294 \uc0ac\ud68c \uc790\uccb4\uac00 \ubc31\uc791\uc758 \ubb34\ub300\uac00 \ub41c\ub2e4. \ud398\ub974\ub0ad\uc740 \ud6d7\ub0a0 \ubaa8\ub974\uc138\ub974 \ubc31\uc791\uc73c\ub85c \uba85\uc608\ub97c \uc5bb\uc5c8\uc9c0\ub9cc \uacfc\uac70\uc758 \ubc30\uc2e0\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\ub2e4. \uc54c\ub9ac \ud30c\uc0e4\uc758 \ub538 \uc5d0\ub370\uc758 \uc99d\uc5b8\uc740 \uadf8 \uba85\uc608\ub97c \ubb34\ub108\ub728\ub9b0\ub2e4. \ub2f9\uae00\ub77c\ub974\uc5d0\uac8c\ub294 \uc7ac\uc0b0\uacfc \uc2e0\uc6a9, \ube4c\ud3ec\ub974\uc5d0\uac8c\ub294 \uc228\uaca8 \ub454 \uac00\uc871\uc758 \ubc94\uc8c4\uac00 \ub3cc\uc544\uc628\ub2e4. \ub2e8\ud14c\uc2a4\ub294 \uc0c1\ub300\uac00 \uc5bb\uc740 \uc131\uacf5\uc758 \ubc14\ud0d5\uc744 \uaca8\ub0e5\ud55c\ub2e4. \uadf8\ub798\uc11c \ub3c5\uc790\ub294 \ud1b5\ucf8c\ud568\uacfc \ubd88\uc548\uc744 \ud568\uaed8 \ub290\ub080\ub2e4. \uc0ac\uc2e4\uc774 \ubc1d\ud600\uc9c0\ub294 \uc815\uc758\uc640 \ud55c \uc0ac\ub78c\uc774 \uacb0\uacfc\ub97c \uc124\uacc4\ud558\ub294 \ubcf5\uc218\ub294 \uc5b4\ub514\uae4c\uc9c0 \uac19\uc740 \uc77c\uc778\uac00. \ubc31\uc791\uc758 \uc900\ube44\uac00 \uc644\ubcbd\ud560\uc218\ub85d \uc774 \uc9c8\ubb38\ub3c4 \ucee4\uc9c4\ub2e4. \uc6d0\uc218\ub4e4\uc5d0\uac8c\ub3c4 \uc790\ub140\uc640 \uac00\uc871\uc774 \uc788\ub2e4. \uba54\ub974\uc138\ub370\uc2a4\ub294 \uc544\ub4e4 \uc54c\ubca0\ub974\ub97c \uc9c0\ud0a4\ub824 \ud558\uace0, \ubc31\uc791\uc740 \uacfc\uac70\uc758 \uc0ac\ub791\uacfc \ubcf5\uc218 \uacc4\ud68d\uc774 \ub9cc\ub098\ub294 \uc790\ub9ac\uc5d0 \uc120\ub2e4. \uc790\uc2e0\uc774 \uc815\ud55c \uc0c1\ub300\ub9cc \ubc8c\ud558\uace0 \uc8fc\ubcc0\uc740 \uadf8\ub300\ub85c \ub458 \uc218 \uc788\ub2e4\ub294 \ubbff\uc74c\uc774 \ud754\ub4e4\ub9b0\ub2e4. \ube4c\ud3ec\ub974 \uc9d1\uc548\uc758 \ube44\uadf9\uc5d0\uc11c \uc5b4\ub9b0 \uc5d0\ub450\uc544\ub974\uae4c\uc9c0 \uc8fd\uc790 \uadf8\ub294 \uc790\uae30 \uacc4\ud68d\uc774 \ubd88\ub7ec\uc628 \uacb0\uacfc \uc55e\uc5d0\uc11c \ucda9\uaca9\uc744 \ubc1b\ub294\ub2e4. \uc6d0\uc218\uc758 \ubab0\ub77d\uc744 \uacc4\uc0b0\ud558\ub294 \uc77c\uacfc \uadf8 \uc8fc\ubcc0 \uc0ac\ub78c\uc758 \uc0dd\uba85\uc744 \ucc45\uc784\uc9c0\ub294 \uc77c\uc740 \ubd84\ub9ac\ub418\uc9c0 \uc54a\uc558\ub2e4. \uc18c\uc124\uc740 \uc774 \uc9c0\uc810\uc5d0\uc11c \ubcf5\uc218\uc758 \uc18d\ub3c4\ub97c \ub2a6\ucd98\ub2e4. \ubc31\uc791\uc740 \uc790\uc2e0\uc744 \ud2b9\ubcc4\ud55c \uc2ec\ud310\uc758 \uc5ed\ud560\uc5d0 \ub193\uace0 \uc6c0\uc9c1\uc5ec \uc654\ub2e4. \ud558\uc9c0\ub9cc \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc6b4\uba85\uc744 \ub05d\uae4c\uc9c0 \uc544\ub294 \uc0ac\ub78c\uc740 \uc544\ub2c8\ub2e4. \ud53c\ud574\uc790\uac00 \uc5bb\uc740 \ud798\uc774 \uadf8\ub97c \uc5b8\uc81c\ub098 \uc633\uc740 \ud310\ub2e8\uc790\ub85c \ub9cc\ub4e4\uc5b4 \uc8fc\uc9c0\ub3c4 \uc54a\ub294\ub2e4. \uadf8\ub294 \ub2f9\uae00\ub77c\ub974\ub97c \ub05d\uae4c\uc9c0 \ud30c\uba78\uc2dc\ud0a4\ub294 \ub300\uc2e0 \uc0b4\uc544\uac08 \uc5ec\uc9c0\ub97c \ub0a8\uae34\ub2e4. \ubaa8\ub4e0 \uc798\ubabb\uc774 \uac00\ubcbc\uc6cc\uc84c\uae30 \ub54c\ubb38\uc740 \uc544\ub2c8\ub2e4. \ubcf5\uc218\uc758 \uc644\uc131\uc774 \uc790\uae30 \uc0b6\uc758 \uc644\uc131\uacfc \uac19\uc9c0 \uc54a\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub4dc\ub7ec\ub09c \uac83\uc774\ub2e4. \ud798\uc744 \uba48\ucd94\ub294 \uc120\ud0dd\ub3c4 \ud544\uc694\ud574\uc9c4\ub2e4. \uc791\ud488\uc5d0\ub294 \ub9c9\uc2dc\ubc00\ub9ac\uc559\uacfc \ubc1c\ub791\ud2f4\uc758 \uc0ac\ub791\ub3c4 \ud750\ub978\ub2e4. \uc774\ub4e4\uc758 \uad00\uacc4\ub294 \uacfc\uac70\uc5d0 \ubb36\uc778 \ubc31\uc791\uc758 \uc0b6\uacfc \ub2e4\ub978 \ubc29\ud5a5\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ubc31\uc791\uc774 \uc774\ub4e4\uc744 \ub3d5\ub294 \uc77c\uc740 \ub204\uad70\uac00\ub97c \ubc8c\ud558\ub294 \ub2a5\ub825\uc744 \ub118\uc5b4 \ub204\uad70\uac00\uc758 \ubbf8\ub798\ub97c \uc9c0\ud0a4\ub294 \ub2a5\ub825\uc744 \ubb3b\ub294\ub2e4. \uc5d0\ub370\uc640\uc758 \uad00\uacc4 \uc5ed\uc2dc \ub05d\uc5d0 \uac00\uc11c \uc0c8 \uc0b6\uc758 \uac00\ub2a5\uc131\uc744 \uc5f0\ub2e4. \uadf8\ub807\ub2e4\uace0 \uacb0\ub9d0\uc774 \uc624\ub798\ub41c \uc0c1\ucc98\ub97c \ubaa8\ub450 \uc9c0\uc6e0\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc774\ubbf8 \uc783\uc740 \uc2dc\uac04\uc744 \ub418\ub3cc\ub9ac\ub294 \ub300\uc2e0 \ub0a8\uc544 \uc788\ub294 \uc2dc\uac04\uc5d0 \ubb34\uc5c7\uc744 \ud560\uc9c0 \uace0\ub974\ub294 \ucabd\uc73c\ub85c \uc2dc\uc120\uc774 \uc62e\uaca8 \uac04\ub2e4. \ub9c8\uc9c0\ub9c9\uc5d0 \ub0a8\ub294 \ub9d0\uc740 \uae30\ub2e4\ub9bc\uacfc \ud76c\ub9dd\uc774\ub2e4. \uae34 \ubcf5\uc218\uadf9\uc744 \uc9c0\ub098 \ub3c4\ucc29\ud55c \uc774 \ub9d0\uc740 \uc544\ubb34 \uc77c\ub3c4 \ud558\uc9c0 \ub9d0\ub77c\ub294 \uad8c\uace0\ub85c\ub9cc \ub4e4\ub9ac\uc9c0 \uc54a\ub294\ub2e4. \uc138\uc0c1\uc744 \uc790\uae30 \ub73b\ub300\ub85c \ubaa8\ub450 \ud1b5\uc81c\ud558\ub824\ub358 \uc0ac\ub78c\uc774 \ubaa8\ub974\ub294 \ubbf8\ub798\ub97c \uc778\uc815\ud558\ub294 \ub9d0\ub85c\ub3c4 \uc77d\uc744 \uc218 \uc788\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ud0c8\ucd9c\uacfc \ubcc0\uc7a5, \ubc18\uaca9\uc758 \uc7ac\ubbf8\ub97c \ub530\ub77c \uc77d\uc5b4\ub3c4 \uc88b\ub2e4. \ub2e4\uc74c\uc5d0\ub294 \ub2e8\ud14c\uc2a4\uac00 \uc5b4\ub290 \uc21c\uac04\ubd80\ud130 \uc790\uc2e0\uc774 \ub9cc\ub4e0 \ubc31\uc791\uc774\ub77c\ub294 \uc5ed\ud560\uc5d0 \ubd99\uc7a1\ud788\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc774 \uc18c\uc124\uc758 \uae34 \uc5ec\uc815\uc740 \uc6d0\uc218\ub97c \ucc3e\ub294 \uae38\uacfc \uc790\uae30 \uc0b6\uc73c\ub85c \ub3cc\uc544\uc624\ub294 \uae38\uc774 \uc5bc\ub9c8\ub098 \ub2e4\ub978\uc9c0 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "moonlight-sonata-name", "title": "\uc6d4\uad11 \u2014 \ubca0\ud1a0\ubca4\uc774 \ubd99\uc778 \uc81c\ubaa9\uc740 \uc544\ub2c8\uc5c8\ub2e4", "summary": "\uc6d4\uad11\uc774\ub77c\ub294 \uc774\ub984\uacfc \uc18c\ub098\ud0c0 \uc790\uccb4\ub97c \ub098\ub204\uc5b4 \ub4e3\ub294 \ubc29\ubc95\uc744 \uc81c\uc548\ud569\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc74c\uc545", "categories": ["arts"], "url": "stories/moonlight-sonata-name/index.html", "image": "../media/moonlight-sonata-name.jpg", "alt": "1917\ub144 Romain Rolland, Beethoven \uc218\ub85d \uc6d4\uad11 \uc18c\ub098\ud0c0 \uc790\ud544 \uc545\ubcf4 \uc7ac\ud604\ub3c4\ud310", "text": "\uc6d4\uad11 \u2014 \ubca0\ud1a0\ubca4\uc774 \ubd99\uc778 \uc81c\ubaa9\uc740 \uc544\ub2c8\uc5c8\ub2e4 \ub2ec\ube5b\uc774\ub77c\ub294 \ubcc4\uba85 \ub4a4\uc5d0\uc11c \uc138 \uc545\uc7a5\uc744 \ub4e3\uae30 \uc6d4\uad11\uc774\ub77c\ub294 \uc774\ub984\uacfc \uc18c\ub098\ud0c0 \uc790\uccb4\ub97c \ub098\ub204\uc5b4 \ub4e3\ub294 \ubc29\ubc95\uc744 \uc81c\uc548\ud569\ub2c8\ub2e4. \uc74c\uc545 \ubb38\ud654\uc640 \uc608\uc220 \u3008\uc6d4\uad11\u3009\uc744 \ucc98\uc74c \ub4e3\ub294 \uc0ac\ub78c\ub3c4 \uccab \uc545\uc7a5\uc5d0\ub294 \uc27d\uac8c \uadc0\ub97c \uae30\uc6b8\uc778\ub2e4. \ub0ae\uc740 \uc74c \uc704\ub85c \uc794\uc794\ud55c \uc18c\ub9ac\uac00 \uc774\uc5b4\uc9c0\uace0, \uadf8 \uc704\uc5d0\uc11c \ub178\ub798\uac00 \ucc9c\ucc9c\ud788 \ubaa8\uc2b5\uc744 \ub4dc\ub7ec\ub0b8\ub2e4. \uc774\ub984\uc744 \uc54c\uace0 \ub4e4\uc73c\uba74 \ub2ec\ube5b\uc774 \ub5a0\uc624\ub974\uae30 \uc27d\ub2e4. \uadf8\ub7f0\ub370 \uc138 \uc545\uc7a5\uc744 \ubaa8\ub450 \ub4e4\uc73c\uba74 \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \uaf64 \ub2e4\ub978 \ud48d\uacbd\uc744 \ub9cc\ub098\uac8c \ub41c\ub2e4. \uc774 \uace1\uc740 \uc870\uc6a9\ud55c \uccab \uc545\uc7a5\uc73c\ub85c \uc2dc\uc791\ud574 \uaca9\ub82c\ud55c \ub05d\uc73c\ub85c \ub098\uc544\uac00\ub294 \ud53c\uc544\ub178 \uc18c\ub098\ud0c0\ub2e4. \ubcc4\uba85\uc758 \uc720\ub798\uc640 \uc791\ud488\uc758 \uc2e4\uc81c \uad6c\uc870\ub97c \ud568\uaed8 \uc54c\uba74, \uc720\uba85\ud55c \ubd80\ubd84\ub9cc \ubc18\ubcf5\ud574\uc11c \ub4e3\ub358 \uc74c\uc545\uc774 \uc870\uae08 \ub113\uc5b4\uc9c4\ub2e4. \uc6b0\ub9ac\uac00 \u3008\uc6d4\uad11\u3009\uc774\ub77c\uace0 \ubd80\ub974\ub294 \uace1\uc740 \ubca0\ud1a0\ubca4\uc758 \ud53c\uc544\ub178 \uc18c\ub098\ud0c0 \uc81c14\ubc88, \uc791\ud488\ubc88\ud638 27\uc758 2\ubc88\uc774\ub2e4. \uc791\ud488\uc5d0\ub294 \u2018\ud658\uc0c1\uace1\ud48d\uc758 \uc18c\ub098\ud0c0\u2019\ub77c\ub294 \ub73b\uc758 Sonata quasi una fantasia\ub77c\ub294 \ud45c\uc81c\uac00 \uc788\ub2e4. \ub2ec\ube5b\uc740 \uc774 \ubcf8\ub798 \ud45c\uc81c\uc5d0 \ub4e4\uc5b4 \uc788\uc9c0 \uc54a\ub2e4. \ub85c\ub9f9 \ub864\ub791\uc758 \uc804\uae30 \u300e\ubca0\ud1a0\ubca4\u300f\uc5d0 \ud568\uaed8 \uc2e4\ub9b0 \uc18c\ub098\ud0c0 \ud574\uc124\uc740 \u2018\uc6d4\uad11\u2019\uc774\ub77c\ub294 \ubcc4\uce6d\uc744 \uc2dc\uc778 \ub810\uc288\ud0c0\ud504\uc640 \uc5f0\uacb0\ud55c\ub2e4. \uc911\uc694\ud55c \uc810\uc740 \uc791\uace1\uac00\uc758 \ud45c\uc81c\uac00 \uc544\ub2c8\ub77c \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc74c\uc545\uc744 \ub4e3\uace0 \ubd99\uc778 \uc774\ub984\uc774\ub77c\ub294 \uac83\uc774\ub2e4. \ubcc4\uce6d\uc774 \ub110\ub9ac \uc4f0\uc778\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ubca0\ud1a0\ubca4\uc774 \ub2ec\ube5b\uc744 \ubb18\uc0ac\ud558\ub824 \uc791\uace1\ud588\ub2e4\ub294 \uc8fc\uc7a5\uc740 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \uac19\uc740 \uc790\ub8cc\ub294 \uc791\ud488\uc774 \uc904\ub9ac\uc5d0\ud0c0 \uadc0\ucc28\ub974\ub514\uc5d0\uac8c \ud5cc\uc815\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud5cc\uc815\uc740 \ucc45\uc758 \uccab\uba38\ub9ac\uc5d0 \uc774\ub984\uc744 \ubc14\uce58\ub294 \uac83\uacfc \ube44\uc2b7\ud558\uac8c, \ub204\uad6c\uc5d0\uac8c \uc791\ud488\uc744 \ub4dc\ub9ac\ub294\uc9c0 \ubc1d\ud788\ub294 \ubc29\uc2dd\uc774\ub2e4. \uadc0\ucc28\ub974\ub514\uc640\uc758 \uad00\uacc4\ub294 \uc774 \uc791\ud488\uc744 \ub458\ub7ec\uc2fc \uc804\uae30\uc801 \ubc30\uacbd\uc758 \ud55c \ubd80\ubd84\uc774\ub2e4. \ub2e4\ub9cc \ud5cc\uc815 \ub300\uc0c1\uc774 \uc788\ub2e4\ub294 \uc774\uc720\ub85c \ubaa8\ub4e0 \uc120\uc728\uc744 \ud2b9\uc815 \uc5f0\uc560 \uc7a5\uba74\uc758 \uc554\ud638\ub77c\uace0 \ud574\ub3c5\ud560 \uc218\ub294 \uc5c6\ub2e4. \uccab \uc545\uc7a5\uc740 \uace0\ubc31, \ub458\uc9f8\ub294 \ub9cc\ub0a8, \uc14b\uc9f8\ub294 \uc774\ubcc4\uc774\ub77c\ub294 \uc2dd\uc758 \uc774\uc57c\uae30\ub97c \uc791\uace1\uac00\uc758 \ud655\uc815\ub41c \uc124\uba85\ucc98\ub7fc \ubd99\uc774\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc0ac\ub78c\uc758 \uc0ac\uc5f0\uc744 \uc54c\uace0 \ub4e4\uc5b4\ub3c4, \uc74c\uc545\uc774 \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \ud750\ub984\uc744 \ub9cc\ub4dc\ub294\uc9c0\ub294 \ub530\ub85c \uc0b4\ud544 \uc218 \uc788\ub2e4. \uccab \uc545\uc7a5\uc758 \uc9c0\uc2dc\ub294 Adagio sostenuto, \ub290\ub9ac\uac8c \uc9c0\uc18d\ud558\uc5ec \uc5f0\uc8fc\ud558\ub77c\ub294 \ub73b\uc73c\ub85c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ub0ae\uc740 \uc74c\uc774 \ubc14\ud0d5\uc744 \uc7a1\uace0, \uc911\uac04\uc5d0\uc11c\ub294 \uc138 \uc74c\uc529 \uc774\uc5b4\uc9c0\ub294 \ubc18\uc8fc\uac00 \uafb8\uc900\ud788 \uc6c0\uc9c1\uc774\uba70, \uadf8 \uc704\uc5d0 \ube44\uad50\uc801 \uae34 \uc74c\uac00\uc758 \uc120\uc728\uc774 \ub098\ud0c0\ub09c\ub2e4. \uc794\uc794\ud558\ub2e4\uace0 \ud574\uc11c \uc544\ubb34 \uc6c0\uc9c1\uc784\ub3c4 \uc5c6\ub294 \uc74c\uc545\uc740 \uc544\ub2c8\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ub178\ub798\ud558\ub294 \uac00\uc7a5 \uc704\ucabd \uc18c\ub9ac\ub9cc \ub4e4\uc5b4 \ubcf4\uc790. \ub2e4\uc74c\uc5d0\ub294 \uadf8 \uc544\ub798\uc5d0\uc11c \uacc4\uc18d \uc774\uc5b4\uc9c0\ub294 \ubc18\uc8fc\ub97c \ub530\ub77c\uac00 \ubcf4\uc790. \uac19\uc740 \uace1 \uc548\uc5d0 \uba48\ucd98 \ub4ef\ud55c \uc2dc\uac04\uacfc \ud758\ub7ec\uac00\ub294 \uc2dc\uac04\uc774 \ud568\uaed8 \uc788\ub2e4\ub294 \ub290\ub08c\uc744 \ubc1b\uc744 \uc218 \uc788\ub2e4. \uc18c\ub9ac\uac00 \uc870\uae08\uc529 \uc313\uc774\uace0 \ud654\uc74c\uc774 \ub2ec\ub77c\uc9c8 \ub54c \uace0\uc694\ud568\uc5d0\ub3c4 \uc791\uc740 \uae34\uc7a5\uc774 \uc0dd\uae34\ub2e4. \ubc24\uc758 \ud48d\uacbd\uc744 \ub5a0\uc62c\ub9ac\uba70 \ub4e3\ub294 \uac83\uc740 \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \uac10\uc0c1\uc774\ub2e4. \ud558\uc9c0\ub9cc \uccab \uc545\uc7a5\uc774 \ud3b8\uc548\ud55c \ubc30\uacbd\uc74c\uc545\uc73c\ub85c\ub9cc \ub4e4\ub9ac\ub294\uc9c0, \uc5b4\ub518\uac00 \ubb34\uac70\uc6c0\uacfc \uae30\ub2e4\ub9bc\ub3c4 \uc788\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uba74 \uc88b\ub2e4. \ud2b9\uc815 \uc7a5\uba74\uc744 \uc815\ub2f5\uc73c\ub85c \uc0bc\uc9c0 \uc54a\uc744 \ub54c \uc74c\uc545 \uc548\uc758 \ubbf8\ubb18\ud55c \ubcc0\ud654\uac00 \ub354 \uc798 \ub4e4\ub9b4 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 1917\ub144 \uc804\uae30\uc5d0 \uc218\ub85d\ub41c \uc790\ud544 \uc545\ubcf4\uc758 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \ud604\ub300 \uc870\ud310 \uc545\ubcf4\ucc98\ub7fc \ubc18\ub4ef\ud558\uc9c0 \uc54a\uc740 \uc790\ub8cc\uc5d0\uc11c, \uc624\ub298\uc758 \uc720\uba85\ud55c \ubcc4\uba85 \ub4a4\uc5d0\ub294 \uad6c\uccb4\uc801\uc778 \uc74c\uacfc \uc5f0\uc8fc \uc9c0\uc2dc\ub97c \uc801\ub358 \uc791\uace1\uac00\uc758 \uc791\uc5c5\uc774 \uc788\uc5c8\ub2e4\ub294 \uc810\ub3c4 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uc61b \uc778\uc1c4 \ub3c4\ud310\uc774 \uc6d0\uace0 \uc2e4\ubb3c\uc758 \uc0c1\ud0dc\ub97c \ubaa8\ub450 \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub458\uc9f8 \uc545\uc7a5 Allegretto\ub294 \uccab \uc545\uc7a5\ubcf4\ub2e4 \uac00\ubccd\uace0 \uac78\uc74c\uc774 \ubd84\uba85\ud558\uac8c \ub290\uaef4\uc9c4\ub2e4. \uccab \uc545\uc7a5\uc5d0\uc11c \uae38\uac8c \uba38\ubb3c\ub358 \uc2dc\uac04\uc774 \uc9e7\uc740 \uc6c0\uc9c1\uc784\uc73c\ub85c \ud480\ub9ac\ub294 \ub4ef\ud558\ub2e4. \ucda4\uc744 \uc5f0\uc0c1\ud558\uba70 \ub4e4\uc5b4\ub3c4 \uc88b\uc9c0\ub9cc, \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \uc0ac\ub78c\uc774 \ucda4\ucd94\ub294 \uc7a5\uba74\uc744 \ubb18\uc0ac\ud55c \uac83\uc774\ub77c\uace0 \ub2e8\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc720\uba85\ud55c \uccab \uc545\uc7a5\uacfc \uac15\ub82c\ud55c \uc14b\uc9f8 \uc545\uc7a5 \uc0ac\uc774\uc5d0 \uc788\uc5b4 \uc774 \ubd80\ubd84\uc740 \uc9c0\ub098\uac00\ub294 \ub2e4\ub9ac\ucc98\ub7fc \ucde8\uae09\ub418\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uc774 \uc9e7\uc740 \uc804\ud658\uc774 \uc788\uae30 \ub54c\ubb38\uc5d0 \uc791\ud488 \uc804\uccb4\uc758 \ub300\ube44\uac00 \ub354 \uc120\uba85\ud574\uc9c4\ub2e4. \ub458\uc9f8 \uc545\uc7a5\uc774 \ub05d\ub098\uae30 \uc804 \uc7a0\uae50\uc758 \uac00\ubcbc\uc6c0\uc744 \uae30\uc5b5\ud574 \ub450\uba74 \ub9c8\uc9c0\ub9c9 \uc545\uc7a5\uc758 \uccab \uc6c0\uc9c1\uc784\uc774 \ud55c\uce35 \ud06c\uac8c \ub2e4\uac00\uc628\ub2e4. \ub9c8\uc9c0\ub9c9 \uc9c0\uc2dc\ub294 Presto agitato, \ub9e4\uc6b0 \ube60\ub974\uace0 \uaca9\ud558\uac8c\ub77c\ub294 \ub73b\uc774\ub2e4. \uc74c\ub4e4\uc774 \ube60\ub974\uac8c \uc19f\uc544\uc624\ub974\uace0, \uac15\ud55c \ud654\uc74c\uc774 \ubc15\ud788\uba70, \uc26c\uc9c0 \uc54a\uace0 \ubc00\uc5b4\ubd99\uc774\ub294 \ub4ef\ud55c \uc5d0\ub108\uc9c0\uac00 \ub098\uc628\ub2e4. \uccab \uc545\uc7a5\uc758 \ud45c\uc815\ub9cc \uc54c\uace0 \uc788\uc5c8\ub2e4\uba74 \uac19\uc740 \uc18c\ub098\ud0c0\uc758 \ub9c8\uc9c0\ub9c9\uc774\ub77c\ub294 \uc0ac\uc2e4\uc774 \ub180\ub77c\uc6b8 \uc218 \uc788\ub2e4. \ud55c\ud3b8 \uc55e\uc120 \uc18c\ub098\ud0c0 \ud574\uc124\uc740 \uccab \uc545\uc7a5\uacfc \ub9c8\uc9c0\ub9c9 \uc545\uc7a5\uc758 \uc74c\ud615 \uc0ac\uc774\uc5d0 \uc5f0\uacb0\uc744 \uc9da\uae30\ub3c4 \ud55c\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uace1 \uc138 \ud3b8\uc744 \uc784\uc758\ub85c \ubd99\uc5ec \ub193\uc558\ub2e4\uae30\ubcf4\ub2e4, \ub2e4\ub978 \uc18d\ub3c4\uc640 \ud798\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \ud55c \uc791\ud488\uc73c\ub85c \ub4e4\uc744 \uc5ec\uc9c0\uac00 \uc788\ub2e4\ub294 \ub73b\uc774\ub2e4. \ucc98\uc74c\ubd80\ud130 \uc545\ubcf4\uc758 \ub300\uc751 \uad00\uacc4\ub97c \ucc3e\uc9c0 \ubabb\ud574\ub3c4 \uad1c\ucc2e\ub2e4. \uace0\uc694\ud558\uac8c \uc2dc\uc791\ud55c \uc74c\uc545\uc774 \uc5b4\ub514\uae4c\uc9c0 \uc6c0\uc9c1\uc774\ub294\uc9c0\ub9cc \ub530\ub77c\uac00 \ubcf4\uc790. \ud658\uc0c1\uace1\ud48d\uc774\ub77c\ub294 \ub9d0\uc740 \uc544\ubb34\ub807\uac8c\ub098 \uc5f0\uc8fc\ud574\ub3c4 \ub41c\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \ud1b5\uc0c1\uc801\uc778 \ud2c0\uc744 \uc758\uc2dd\ud558\uba74\uc11c\ub3c4 \uc545\uc7a5\ub4e4\uc758 \uc131\uaca9\uacfc \uc5f0\uacb0\uc744 \uc790\uc720\ub86d\uac8c \uad6c\uc131\ud558\ub824\ub294 \ud45c\uc81c\ub85c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc774 \uc18c\ub098\ud0c0\uc5d0\uc11c\ub294 \ube60\ub974\uace0 \ud654\ub824\ud55c \uccab\uba38\ub9ac\ub85c \uccad\uc911\uc744 \ubd99\uc7a1\uae30\ubcf4\ub2e4 \ub290\ub9b0 \uccab \uc545\uc7a5\uc73c\ub85c \uc2dc\uac04\uc744 \uc5f4\uace0, \ub05d\uc5d0\uc11c \ud070 \ud798\uc744 \ud130\ub728\ub9b0\ub2e4. \u2018\uc6d4\uad11\u2019\uc774 \ud48d\uacbd\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uc774\ub984\uc774\ub77c\uba74 \u2018\ud658\uc0c1\uace1\ud48d\uc758 \uc18c\ub098\ud0c0\u2019\ub294 \uc791\ud488\uc758 \uc9dc\uc784\uc744 \uc0dd\uac01\ud558\uac8c \ud558\ub294 \uc774\ub984\uc774\ub2e4. \ub450 \uc774\ub984\uc744 \ud568\uaed8 \uc54c\uc544 \ub450\uba74 \ud558\ub098\ub294 \uc0c1\uc0c1\uc5d0, \ub2e4\ub978 \ud558\ub098\ub294 \ub4e3\ub294 \ubc29\ubc95\uc5d0 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uc720\uba85\ud55c \ubcc4\uba85\uc744 \ubc84\ub9b4 \uc774\uc720\ub3c4, \uadf8\uac83 \ud558\ub098\ub85c \uc804\ubd80\ub97c \uc124\uba85\ud560 \uc774\uc720\ub3c4 \uc5c6\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uccab \uc545\uc7a5\uc5d0\uc11c \ubc18\ubcf5\ub418\ub294 \ubc18\uc8fc\ub97c \ucc3e\uc544\ubcf4\uace0, \ub458\uc9f8\uc5d0\uc11c\ub294 \uac78\uc74c\uc758 \ubcc0\ud654\ub97c, \uc14b\uc9f8\uc5d0\uc11c\ub294 \uc19f\uad6c\uce58\ub294 \uc5d0\ub108\uc9c0\ub97c \ub290\uaef4 \ubcf4\uc790. \uc5f0\uc8fc\uc790\ub9c8\ub2e4 \ube60\ub974\uae30\uc640 \uc18c\ub9ac\uc758 \ubb34\uac8c\uac00 \ub2e4\ub974\ubbc0\ub85c \uc7ac\uc0dd \uc2dc\uac04 \ud558\ub098\ub97c \uc815\ub2f5\uc73c\ub85c \uc0dd\uac01\ud560 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ub9c8\uc9c0\ub9c9 \uc74c\uc744 \ub4e3\uace0 \ucc98\uc74c\uc744 \ub5a0\uc62c\ub9ac\uba74 \ub2ec\ube5b\uc774\ub77c\ub294 \uc81c\ubaa9\uacfc\ub294 \uc870\uae08 \ub2e4\ub978 \uae30\uc5b5\uc774 \ub0a8\uc744 \uc218 \uc788\ub2e4. \uc774 \uace1\uc758 \ub9e4\ub825\uc740 \uc870\uc6a9\ud568\ub9cc\ub3c4 \uaca9\ub82c\ud568\ub9cc\ub3c4 \uc544\ub2c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ud45c\uc815\uc774 \ud55c \uc791\ud488\uc758 \uc2dc\uac04 \uc548\uc5d0 \ub193\uc774\ub294 \uacbd\ud5d8\uc774\ub2e4. \uc775\uc219\ud55c \uccab \uc545\uc7a5\uc744 \ucd9c\ubc1c\uc810\uc73c\ub85c \uc0bc\ub418, \ub05d\uae4c\uc9c0 \uac78\uc5b4\uac00 \ubcf4\uba74 \uc18c\ub098\ud0c0 \uc804\uccb4\uac00 \ubcf4\uc774\uae30 \uc2dc\uc791\ud55c\ub2e4."}, {"id": "mountain-chief-recorded-song", "title": "\uc61b \ub179\uc74c \uc0ac\uc9c4\uc5d0\uc11c \uadf8\ub294 \ub178\ub798\ub97c \ub4e3\uace0 \uc788\uc5c8\ub2e4", "summary": "\uc18c\ub9ac\ub97c \ub2f4\ub294 \uae30\uacc4 \uacc1\uc5d0 \uc0ac\ub78c\uc758 \ud574\uc11d\ub3c4 \ud544\uc694\ud588\ub358 \uc7a5\uba74\uc744 \ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc74c\uc545", "categories": ["arts"], "url": "stories/mountain-chief-recorded-song/index.html", "image": "../media/mountain-chief-recorded-song.jpg", "alt": "1916\ub144 \ud504\ub79c\uc2dc\uc2a4 \ub374\uc2a4\ubaa8\uc5b4\uc640 \ub9c8\uc6b4\ud2f4 \uce58\ud504, \ub098\ud314 \ubaa8\uc591 \uc7a5\uce58\uac00 \ud568\uaed8 \uc788\ub294 \uc5ed\uc0ac \uc0ac\uc9c4. \uad50\uc7ac\ub294 \ub179\uc74c\ub41c \ub178\ub798\ub97c \ub4e3\uace0 \uc218\ud654\ub85c \ud574\uc11d\ud558\ub294 \uc7a5\uba74\uc774\ub77c\uace0 \uc124\uba85\ud569\ub2c8\ub2e4.", "text": "\uc61b \ub179\uc74c \uc0ac\uc9c4\uc5d0\uc11c \uadf8\ub294 \ub178\ub798\ub97c \ub4e3\uace0 \uc788\uc5c8\ub2e4 1916\ub144\uc758 \ub098\ud314\uacfc \uc0ac\ub78c \uc0ac\uc774\uc5d0 \ub193\uc778 \uc124\uba85 \uc18c\ub9ac\ub97c \ub2f4\ub294 \uae30\uacc4 \uacc1\uc5d0 \uc0ac\ub78c\uc758 \ud574\uc11d\ub3c4 \ud544\uc694\ud588\ub358 \uc7a5\uba74\uc744 \ubd05\ub2c8\ub2e4. \uc74c\uc545 \ubb38\ud654\uc640 \uc608\uc220 \ud751\ubc31 \uc0ac\uc9c4 \uc18d\uc5d0 \ucee4\ub2e4\ub780 \ub098\ud314 \ubaa8\uc591\uc758 \uc7a5\uce58\uac00 \uc788\ub2e4. \uc624\ub978\ucabd\uc5d0\ub294 \ud55c \uc0ac\ub78c\uc774 \uc549\uc544 \uc788\uace0 \uc67c\ucabd\uc5d0\ub294 \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc790\ub9ac\ud55c\ub2e4. \uc624\ub798\ub41c \ub179\uc74c \uc7a5\uba74\uc774\ub77c\uace0\ub9cc \uc0dd\uac01\ud558\uba74 \ub204\uad70\uac00 \ub178\ub798\ud558\ub294 \uc21c\uac04\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \ud558\uc9c0\ub9cc OpenStax\uac00 \uc18c\uac1c\ud558\ub294 \uc774 1916\ub144 \uc0ac\uc9c4\uc5d0\uc11c \ub9c8\uc6b4\ud2f4 \uce58\ud504\ub294 \ub179\uc74c\ub41c \ub178\ub798\ub97c \ub4e3\uace0 \uc788\uc5c8\ub2e4. \uadf8 \uacc1\uc5d0\ub294 \ubd81\ubbf8 \uc6d0\uc8fc\ubbfc \uc74c\uc545\uc744 \uc5f0\uad6c\ud55c \ud504\ub79c\uc2dc\uc2a4 \ub374\uc2a4\ubaa8\uc5b4\uac00 \uc788\ub2e4. \uad50\uc7ac\uc758 \ucea1\uc158\uc5d0 \ub530\ub974\uba74 \ub9c8\uc6b4\ud2f4 \uce58\ud504\ub294 \ub374\uc2a4\ubaa8\uc5b4\uac00 \ub179\uc74c\ud55c \ub178\ub798\ub97c \ub4e4\uc73c\uba70 \ubd81\ubbf8 \ud3c9\uc6d0 \uc9c0\uc5ed\uc758 \uc218\ud654\ub85c \ud574\uc11d\ud574 \uc8fc\uc5c8\ub2e4. \uc0ac\uc9c4\uc744 \ub2e8\uc21c\ud788 \uc18c\ub9ac\ub97c \uc800\uc7a5\ud558\ub294 \uae30\uacc4\uc758 \uae30\ub85d\uc73c\ub85c\ub9cc \uc77d\uae30 \uc5b4\ub824\uc6cc\uc9c0\ub294 \ub300\ubaa9\uc774\ub2e4. \ub178\ub798\uac00 \uc7a5\uce58 \uc548\uc5d0 \ub2f4\uaca8 \uc788\ub2e4\uace0 \uadf8 \ub178\ub798\uc758 \ub9e5\ub77d\uae4c\uc9c0 \uc800\uc808\ub85c \uc804\ub2ec\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub4e3\ub294 \uc0ac\ub78c\uacfc \uc124\uba85\ud558\ub294 \uc0ac\ub78c, \uc11c\ub85c \uc758\ubbf8\ub97c \ub098\ub204\ub294 \uacfc\uc815\ub3c4 \uadf8 \uacc1\uc5d0 \uc788\ub2e4. \uc774\uac83\uc740 \uc774 \uc7a5\uba74\uc5d0\uc11c \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub294 \uc810\uc774\ub2e4. \ub179\uc74c\ud55c\ub2e4\uace0 \uc124\uba85\ud560 \ub54c\uc640 \ub179\uc74c\uc744 \ub4e3\ub294\ub2e4\uace0 \uc124\uba85\ud560 \ub54c \uc0ac\uc9c4\uc758 \uc2dc\uac04\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ub204\uac00 \ubb34\uc5c7\uc744 \ud558\uace0 \uc788\uc5c8\ub294\uc9c0 \uc54c\ub824 \uc8fc\ub294 \uc9e7\uc740 \ucea1\uc158\uc774 \ubcf4\ub294 \ubc29\ud5a5\uc744 \ubc14\uafb8\ub294 \uac83\uc774\ub2e4. \uc774 \uc0ac\uc9c4\uc5d0\uc11c \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \uac00\uc0ac\uc758 \uc5b4\ub290 \ubd80\ubd84\uc744 \uc124\uba85\ud588\ub294\uc9c0\uae4c\uc9c0 \uc0c8\ub85c \ub9cc\ub4e4\uc5b4 \ubd99\uc774\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc790\ub8cc\uac00 \uc54c\ub824 \uc8fc\ub294 \ud589\ub3d9\uc744 \uba3c\uc800 \uc77d\uc73c\uba74, \uace0\uac1c\uc640 \uc190\uc758 \uc704\uce58\ub3c4 \uadf8 \uc7a5\uba74 \uc548\uc5d0\uc11c \ub2e4\uc2dc \uc0b4\ud3b4\ubcf4\uac8c \ub41c\ub2e4. \uc0ac\uc9c4 \uc18d\uc5d0 \ub179\uc74c \uc7a5\uce58\uac00 \ubcf4\uc774\uba74 \uc6b0\ub9ac\ub294 \ub204\uad70\uac00 \ub178\ub798\ub97c \ub179\uc74c\ud558\ub294 \uc21c\uac04\uc774\ub77c\uace0 \uc9d0\uc791\ud558\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \ucea1\uc158\uc740 \uc774\ubbf8 \ub179\uc74c\ud55c \ub178\ub798\ub97c \ub4e3\uace0 \ud574\uc11d\ud558\ub294 \uc7a5\uba74\uc774\ub77c\uace0 \uc54c\ub824 \uc900\ub2e4. \uac19\uc740 \ubb3c\uac74 \uc55e\uc5d0 \uc549\uc544 \uc788\uc5b4\ub3c4 \ubcf4\ub0b4\ub294 \uc18c\ub9ac\uc640 \ubc1b\uc544 \ub4e3\ub294 \uc18c\ub9ac\uc758 \uc2dc\uac04\uc740 \ub2e4\ub974\ub2e4. \uc0ac\uc9c4\uc758 \uc678\ud615\uacfc \ub0a8\uc740 \uc124\uba85\uc744 \ud568\uaed8 \uc77d\uc5b4\uc57c \ud558\ub294 \uc774\uc720\ub2e4. \uc0ac\uc9c4\uc744 \ubcf4\uc790\ub9c8\uc790 \ub5a0\uc62c\ub9b0 \uccab \uc774\uc57c\uae30\ub97c \uc9c0\uc6cc\uc57c \ud560 \ub54c\uc5d0\ub3c4 \uad00\ucc30\uc774 \uc2e4\ud328\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc124\uba85\uc744 \uc77d\uace0 \uc190\uc758 \ub3d9\uc791\uacfc \ubab8\uc758 \ubc29\ud5a5\uc744 \ub2e4\uc2dc \ubcf4\uac8c \ub418\uae30 \ub54c\ubb38\uc774\ub2e4. \ub2e4\ub9cc \uc5b4\ub5a4 \uac00\uc0ac\uc5d0 \ub9de\ucd94\uc5b4 \uc5b4\ub5a4 \ub73b\uc744 \uc804\ub2ec\ud588\ub294\uc9c0\uae4c\uc9c0\ub294 \uc774 \uc790\ub8cc\uc758 \ucea1\uc158\uc73c\ub85c \uc54c \uc218 \uc5c6\ub2e4. \ud655\uc778\ub418\ub294 \ud589\ub3d9\uc774 \ubb34\uc5c7\uc778\uc9c0\ubd80\ud130 \uc815\ud655\ud788 \uc138\uc6b0\uba74 \uc624\ud788\ub824 \ub354 \ub9ce\uc740 \uc9c8\ubb38\uc774 \uac00\ub2a5\ud574\uc9c4\ub2e4. \uc790\ub8cc\ub294 \ub9c8\uc6b4\ud2f4 \uce58\ud504\uac00 \ubd81\ubbf8 \ud3c9\uc6d0 \uc9c0\uc5ed\uc758 \uc218\ud654\ub85c \ub178\ub798\ub97c \ud574\uc11d\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud55c \uc7a5\uba74\uc5d0\uc11c \ub4e3\uae30\uc640 \ubab8\uc9d3, \uc758\ubbf8\ub97c \uc804\ud558\ub294 \uc77c\uc774 \ud568\uaed8 \uc774\ub8e8\uc5b4\uc84c\ub2e4. \uc18c\ub9ac\uac00 \ub179\uc74c \uc7a5\uce58 \uc548\uc5d0 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uadf8 \ubb38\ud654\uc758 \uc9c0\uc2dd\uc774 \uc804\ubd80 \uc800\uc7a5\ub41c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ub9e5\ub77d\uc744 \uc54c\uace0 \uc124\uba85\ud558\ub294 \uc0ac\ub78c\uc758 \uc5ed\ud560\uc774 \uadf8 \uacc1\uc5d0 \ub0a8\uc544 \uc788\ub2e4. \uc5ec\uae30\uc758 \uc218\ud654\ub97c \uc624\ub298\uc758 \ud2b9\uc815 \uc218\uc5b4 \uccb4\uacc4\uc640 \uc124\uba85 \uc5c6\uc774 \uac19\ub2e4\uace0 \ub193\uac70\ub098, \uc778\ubb3c\uc758 \uccad\uac01 \uc0c1\ud0dc\ub97c \ucd94\uce21\ud574\uc11c\ub3c4 \uc548 \ub41c\ub2e4. \uc0ac\uc9c4\uc758 \ud589\ub3d9\uc740 \uc790\ub8cc\uac00 \ubc1d\ud78c \uc9c0\uc5ed\uc801 \ub9e5\ub77d\uc5d0\uc11c \uc77d\uc744 \ubd80\ubd84\uc774\ub2e4. \ubab8\uc9d3\uc744 \ub2e8\uc21c\ud55c \uc7a5\uc2dd\ucc98\ub7fc \ubcf4\ub294 \ub300\uc2e0 \ub73b\uc744 \ub098\ub204\ub294 \ud65c\ub3d9\uc73c\ub85c \ubc14\ub77c\ubcf4\uba74 \ub178\ub798\uc640 \uc5b8\uc5b4\uc758 \uad00\uacc4\ub97c \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ub374\uc2a4\ubaa8\uc5b4\ub294 \ubd81\ubbf8 \uc6d0\uc8fc\ubbfc \uc74c\uc545\uc744 \uc5f0\uad6c\ud55c \uc778\ubb3c\uc774\ub2e4. \uadf8 \uc5ed\ud560\ub9cc \uac15\uc870\ud558\uba74 \ub9c8\uc6b4\ud2f4 \uce58\ud504\ub294 \uae30\ub85d\uc758 \ub300\uc0c1\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ucea1\uc158\uc5d0\ub294 \uadf8\uac00 \ub4e3\uace0 \ud574\uc11d\ud558\ub294 \ud589\ub3d9\uc774 \ubd84\uba85\ud788 \ub098\uc628\ub2e4. \uc5f0\uad6c\uc5d0 \uc4f0\uc774\ub294 \uc9c0\uc2dd\uc740 \uc7a5\uce58\ub97c \uc900\ube44\ud55c \uc0ac\ub78c\uc5d0\uac8c\ub9cc \uc788\uc5c8\ub358 \uac83\uc774 \uc544\ub2c8\ub2e4. \ub204\uac00 \ubb34\uc5c7\uc744 \uc54c\uace0 \uc804\ud574 \uc8fc\uc5c8\ub294\uc9c0 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc774 \uad00\uc810\uc740 \uc0ac\uc9c4 \uc18d \ubaa8\ub4e0 \uad00\uacc4\uac00 \ud3c9\ub4f1\ud588\ub2e4\uace0 \uc27d\uac8c \ub2e8\uc815\ud558\ub294 \uac83\uacfc\ub3c4 \ub2e4\ub974\ub2e4. \ub2f9\uc2dc \uc5f0\uad6c\uac00 \uc774\ub8e8\uc5b4\uc9c4 \uc0ac\ud68c\uc801 \uc870\uac74\uc740 \ubcc4\ub3c4\ub85c \ud655\uc778\ud560 \ubb38\uc81c\ub2e4. \uc5ec\uae30\uc11c\ub294 \ud55c \uc7a5\uba74\uc744 \uc124\uba85\ud560 \ub54c \uc9c0\uc2dd\uc744 \uc81c\uacf5\ud558\ub294 \uc0ac\ub78c\uc758 \ud589\ub3d9\uacfc \uc774\ub984\uc744 \uc9c0\uc6b0\uc9c0 \uc54a\ub294 \ub370 \ucd08\uc810\uc744 \ub9de\ucd98\ub2e4. \uc790\ub8cc\ub97c \ub9cc\ub4e4 \ub54c\uc758 \uad00\uacc4\ub97c \ubb3b\ub294 \uc77c\ub3c4 \uc0ac\uc9c4 \uc77d\uae30\uc758 \uc77c\ubd80\ub2e4. \uc74c\uc545\uc744 \ub4e3\ub294 \uc0ac\ub78c\uc740 \uc18c\ub9ac\uc758 \ub192\ub0ae\uc774\uc640 \ub9ac\ub4ec\uc744 \ub290\ub084 \uc218 \uc788\uc9c0\ub9cc \uc5b8\uc5b4\uc640 \uad00\uc2b5\uc744 \ubaa8\ub974\uba74 \ub193\uce58\ub294 \ub9e5\ub77d\uc774 \uc788\uc744 \uc218 \uc788\ub2e4. \uc774 \uc0ac\uc9c4\uc740 \uadf8 \uc0ac\uc774\uc5d0 \uc124\uba85\uacfc \ud574\uc11d\uc758 \uc2dc\uac04\uc774 \uc788\uc5c8\ub2e4\ub294 \uc810\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uae30\ub85d\uc740 \ud63c\uc790 \ubaa8\ub4e0 \ub73b\uc744 \ub9d0\ud574 \uc8fc\ub294 \ubb3c\uac74\uc774 \uc544\ub2c8\ub77c \ub2e4\uc2dc \ub4e3\uace0 \uc11c\ub85c \ud655\uc778\ud558\ub294 \ud65c\ub3d9\uc744 \uac00\ub2a5\ud558\uac8c \ud558\ub294 \ub9e4\uccb4\uc774\uae30\ub3c4 \ud558\ub2e4. \uc2e4\uc81c \uc0ac\uc9c4\uc740 \uc0c8\ub85c \ub9cc\ub4e0 \uc5ed\uc0ac \uc0bd\ud654\uc640 \ub2ec\ub9ac \ucd2c\uc601 \ub2f9\uc2dc\uc758 \uc778\ubb3c\uacfc \ubb3c\uac74\uc744 \uc804\ud55c\ub2e4. \uadf8\ub807\uc9c0\ub9cc \ud55c \uc7a5\uc758 \uc0ac\uc9c4\uc774 \uc55e\ub4a4\uc758 \ub300\ud654 \uc804\uccb4\ub97c \uc54c\ub824 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubcf4\uc774\ub294 \uac83\uacfc \uc804\ud574\uc9c0\ub294 \uc124\uba85\uc744 \uc624\uac00\uba70 \ub204\uac00 \ubb34\uc5c7\uc744 \ud558\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc624\ub798\ub41c \uc7a5\uce58\ubcf4\ub2e4 \uadf8 \uc55e\uc5d0\uc11c \uc758\ubbf8\ub97c \ub098\ub204\ub358 \uc0ac\ub78c\ub4e4\uc758 \ud589\ub3d9\uc774 \ub354 \ub610\ub837\ud574\uc9c8 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \uc2e4\uc81c \uc5ed\uc0ac \uc0ac\uc9c4\uc774\ub2e4. \ub2f9\uc2dc\uc758 \uc790\uc138\uc640 \uc7a5\uce58, \uc0ac\ub78c \uc0ac\uc774\uc758 \uac70\ub9ac\ub97c \uc0c1\uc0c1\uc73c\ub85c \uc7ac\ubc30\uce58\ud558\uc9c0 \uc54a\uace0 \uc790\ub8cc\uac00 \ub0a8\uae34 \ubaa8\uc2b5\uc744 \ubcf4\ub3c4\ub85d \ud588\ub2e4. \uc624\ub798\ub41c \uc7a5\ube44\uc5d0 \uc2dc\uc120\uc744 \ube7c\uc557\uae30\ub2e4\uac00\ub3c4 \uc0ac\ub78c \ucabd\uc73c\ub85c \ub2e4\uc2dc \ub3cc\uc544\uc624\uac8c \ub41c\ub2e4. \uc18c\ub9ac\ub97c \ub0a8\uae30\ub294 \uae30\uc220\uc740 \uc911\uc694\ud558\uc9c0\ub9cc \uc18c\ub9ac\uc758 \ub73b\uc744 \uc544\ub294 \uc0ac\ub78c\ub3c4 \uc911\uc694\ud558\ub2e4. \uc774 \uc791\uc740 \ub9cc\ub0a8\uc744 \ud1b5\ud574 \ub178\ub798\ub97c \uae30\ub85d\ud55c\ub2e4\ub294 \uac83\uc774 \uae30\uacc4\uc758 \uc77c\ub85c\ub9cc \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub2e4. \uc0ac\uc9c4 \uc18d\uc5d0\ub294 \ub4e3\ub294 \uc2dc\uac04\uacfc \uc124\uba85\ud558\ub294 \uc2dc\uac04\uc774 \ud568\uaed8 \uc788\ub2e4."}, {"id": "mozart-magic-flute-two-kinds-courage", "title": "\u300e\ub9c8\uc220\ud53c\ub9ac\u300f \u2014 \ub192\uc740 \uc5ec\uc655\uc758 \ubaa9\uc18c\ub9ac\uc640 \uc18c\ubc15\ud55c \uc0c8\uc7a1\uc774", "summary": "\ud0c0\ubbf8\ub178\uc640 \ud30c\ubbf8\ub098\uc758 \ubaa8\ud5d8, \ubc24\uc758 \uc5ec\uc655\uc758 \uc544\ub9ac\uc544, \ud30c\ud30c\uac8c\ub178\uc758 \uc791\uc740 \uc18c\ub9dd\uc744 \uc904\uac70\ub9ac\uc640 \ud568\uaed8 \uc18c\uac1c\ud569\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc74c\uc545", "categories": ["arts"], "url": "stories/mozart-magic-flute-two-kinds-courage/index.html", "image": "../media/mozart-magic-flute-two-kinds-courage.png", "alt": "\ud53c\ub9ac\ub97c \ub4e0 \uc655\uc790\uc640 \uacf5\uc8fc, \ubc29\uc6b8\uc744 \ub4e0 \uc0c8\uc7a1\uc774\uac00 \ud568\uaed8 \uc788\ub294 \ub9c8\uc220\ud53c\ub9ac\uc758 \uc0c1\uc0c1 \ubb34\ub300 \uc0bd\ud654", "text": "\u300e\ub9c8\uc220\ud53c\ub9ac\u300f \u2014 \ub192\uc740 \uc5ec\uc655\uc758 \ubaa9\uc18c\ub9ac\uc640 \uc18c\ubc15\ud55c \uc0c8\uc7a1\uc774 \ubaa8\ucc28\ub974\ud2b8\uc758 \ub3d9\ud654 \uac19\uc740 \uc624\ud398\ub77c\uc5d0\uc11c \uc11c\ub85c \ub2e4\ub978 \ud589\ubcf5\uc744 \ub4e3\ub2e4 \ud0c0\ubbf8\ub178\uc640 \ud30c\ubbf8\ub098\uc758 \ubaa8\ud5d8, \ubc24\uc758 \uc5ec\uc655\uc758 \uc544\ub9ac\uc544, \ud30c\ud30c\uac8c\ub178\uc758 \uc791\uc740 \uc18c\ub9dd\uc744 \uc904\uac70\ub9ac\uc640 \ud568\uaed8 \uc18c\uac1c\ud569\ub2c8\ub2e4. \uc74c\uc545 \ubb38\ud654\uc640 \uc608\uc220 \ubb34\uc11c\uc6b4 \uad34\ubb3c, \ub9c8\ubc95\uc758 \uc545\uae30, \uc783\uc5b4\ubc84\ub9b0 \uacf5\uc8fc. \u300e\ub9c8\uc220\ud53c\ub9ac\u300f\ub294 \ucc98\uc74c\uc5d0 \uc5b4\ub9b0 \uc2dc\uc808 \ub4e4\uc5c8\ub358 \ubaa8\ud5d8 \uc774\uc57c\uae30\ucc98\ub7fc \uc2dc\uc791\ud55c\ub2e4. \uadf8\ub7f0\ub370 \ubbff\uc5b4\uc57c \ud560 \uc778\ubb3c\uc774 \ubc14\ub00c\uace0, \uc601\uc6c5 \uacc1\uc758 \uc0c8\uc7a1\uc774\ub294 \uacc4\uc18d \ub2e4\ub978 \uc885\ub958\uc758 \ud589\ubcf5\uc744 \ubc14\ub780\ub2e4. \uac19\uc740 \ubb34\ub300\uc5d0\uc11c \ud070 \uc774\uc0c1\uacfc \uc18c\ubc15\ud55c \uc0dd\ud65c\uc774 \ub098\ub780\ud788 \ub178\ub798\ud55c\ub2e4. \ubaa8\ucc28\ub974\ud2b8\uac00 \uc0dd\uc560 \ub9c8\uc9c0\ub9c9 \ud574\uc778 1791\ub144\uc5d0 \uc644\uc131\ud55c \uc774 \uc791\ud488\uc740 \uc5d0\ub9c8\ub204\uc5d8 \uc2dc\uce74\ub124\ub354\uc758 \ub300\ubcf8\uc73c\ub85c \ube48\uc5d0\uc11c \ucd08\uc5f0\ub418\uc5c8\ub2e4. \ub300\uc0ac\uc640 \ub178\ub798\uac00 \uc624\uac00\ub294 \uc624\ud398\ub77c\uc774\ubbc0\ub85c \uc904\uac70\ub9ac\ub97c \uc870\uae08 \uc54c\uace0 \ub4e4\uc73c\uba74 \uc778\ubb3c\uc758 \ubaa9\uc18c\ub9ac\uac00 \ud6e8\uc52c \uc120\uba85\ud574\uc9c4\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc8fc\uc694 \uc0ac\uac74\uacfc \uacb0\ub9d0\uc744 \ud568\uaed8 \uc18c\uac1c\ud55c\ub2e4. \uc655\uc790 \ud0c0\ubbf8\ub178\ub294 \uc704\ud5d8\uc5d0\uc11c \uad6c\ud574\uc9c4 \ub4a4 \ubc24\uc758 \uc5ec\uc655\uc758 \ub538 \ud30c\ubbf8\ub098\ub97c \ucc3e\uc544 \ub2ec\ub77c\ub294 \ubd80\ud0c1\uc744 \ubc1b\ub294\ub2e4. \uadf8\ub140\uac00 \uc790\ub77c\uc2a4\ud2b8\ub85c\uc5d0\uac8c \ubd99\uc7a1\ud600 \uc788\ub2e4\ub294 \uc124\uba85\uc744 \ub4e3\ub294\ub2e4. \ucd08\uc0c1\ud654 \uc18d \ud30c\ubbf8\ub098\ub97c \ubcf8 \ud0c0\ubbf8\ub178\uac00 \ubd80\ub974\ub294 \uc544\ub9ac\uc544\uc5d0\ub294 \uc544\uc9c1 \ub9cc\ub098\uc9c0\ub3c4 \uc54a\uc740 \uc0ac\ub78c\uc5d0\uac8c \ub9c8\uc74c\uc774 \uae30\uc6b0\ub294 \uc124\ub818\uc774 \ub2f4\uae34\ub2e4. \uc791\ud488\uc740 \ucc98\uc74c\ubd80\ud130 \ubaa8\ub4e0 \uc0ac\uc815\uc744 \uc54c\ub824 \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \ud0c0\ubbf8\ub178\uac00 \ub4e3\ub294 \uc774\uc57c\uae30\ub9cc\ud07c \uad00\uac1d\ub3c4 \ubbff\uac8c \ub41c\ub2e4. \uadf8\ub798\uc11c \ub4a4\uc5d0 \uc790\ub77c\uc2a4\ud2b8\ub85c\uc758 \uacf5\uac04\uc5d0 \ub4e4\uc5b4\uc130\uc744 \ub54c \ud63c\ub780\uc774 \uc0dd\uae34\ub2e4. \uad6c\ud574\uc57c \ud560 \uc120\ud55c \ud3b8\uacfc \ubb3c\ub9ac\uccd0\uc57c \ud560 \uc545\ud55c \ud3b8\uc774 \uac04\ub2e8\ud788 \ub098\ub258\uc9c0 \uc54a\ub294\ub2e4. \ubaa8\ud5d8\uc740 \uc6a9\uae30\ub97c \uc2dc\ud5d8\ud558\uae30 \uc804\uc5d0 \uba3c\uc800 \ud310\ub2e8\uc744 \ud754\ub4e0\ub2e4. \ub3d9\ud589\ud558\ub294 \ud30c\ud30c\uac8c\ub178\ub294 \uc655\uc790\uac00 \uc544\ub2c8\ub2e4. \uc0c8\ub97c \uc7a1\uc544 \uc0b4\uc544\uac00\ub294 \uadf8\ub294 \uba39\uace0 \ub9c8\uc2dc\uace0 \uc790\uc2e0\uc744 \uc88b\uc544\ud574 \uc904 \uc9dd\uc744 \ub9cc\ub098\uace0 \uc2f6\uc5b4 \ud55c\ub2e4. \ub4f1\uc7a5\ud560 \ub54c\uc758 \u300c\ub098\ub294 \uc0c8\uc7a1\uc774\u300d\ub97c \ub4e4\uc73c\uba74 \ubcf5\uc7a1\ud55c \uc0ac\uba85\uc744 \ub9e1\uc740 \uc0ac\ub78c\ubcf4\ub2e4 \uc624\ub298 \ud558\ub8e8\uac00 \uc911\uc694\ud55c \uc774\uc6c3\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uac00\ubcbc\uc6b4 \uc120\uc728\uacfc \ub9d0\ud22c\uac00 \uadf8 \uc131\uaca9\uc744 \uc54c\ub824 \uc900\ub2e4. \ud0c0\ubbf8\ub178\uc5d0\uac8c\ub294 \ub9c8\uc220\ud53c\ub9ac\uac00, \ud30c\ud30c\uac8c\ub178\uc5d0\uac8c\ub294 \uc2e0\ube44\ud55c \ubc29\uc6b8\uc774 \uc8fc\uc5b4\uc9c4\ub2e4. \ub450 \uc545\uae30\ub294 \uc704\ud5d8\ud55c \uc0c1\ud669\uc5d0\uc11c \ud798\uc744 \ubc1c\ud718\ud558\uc9c0\ub9cc \ub611\uac19\uc740 \uc131\uaca9\uc758 \uc778\ubb3c\uc744 \ub9cc\ub4e4\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud30c\ud30c\uac8c\ub178\uac00 \ub298 \uc22d\uace0\ud55c \ubaa9\ud45c\uc5d0 \uc9d1\uc911\ud558\uc9c0 \ubabb\ud55c\ub2e4\uace0 \ud574\uc11c \uc2e4\ud328\ud55c \ud0c0\ubbf8\ub178\uac00 \ub418\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uc791\ud488\uc5d0\ub294 \ub2e4\ub978 \uc0b6\uc758 \uc790\ub9ac\uac00 \ub530\ub85c \ub9c8\ub828\ub418\uc5b4 \uc788\ub2e4. \ud30c\ubbf8\ub098\ub294 \uc790\uc2e0\uc744 \uad34\ub86d\ud788\ub294 \ubaa8\ub178\uc2a4\ud0c0\ud1a0\uc2a4\uc5d0\uac8c\uc11c \ubc97\uc5b4\ub098\ub824 \ud558\uace0, \ud30c\ud30c\uac8c\ub178\uc640 \ub9cc\ub098 \ub3c4\uc6c0\uc744 \uc5bb\ub294\ub2e4. \ud55c\ud3b8 \ud0c0\ubbf8\ub178\ub294 \uc0ac\uc6d0\uc5d0\uc11c \uc0c8\ub85c\uc6b4 \uc124\uba85\uc744 \ub4e3\ub294\ub2e4. \uc790\ub77c\uc2a4\ud2b8\ub85c\ub97c \ub2e8\uc21c\ud55c \uc545\uc778\uc73c\ub85c\ub9cc \ubcf4\uc558\ub358 \ud310\ub2e8\uc740 \uc218\uc815\ub418\uace0, \ub450 \uc80a\uc740\uc774\ub294 \uc9c0\ud61c\uc640 \uc808\uc81c\ub97c \ud5a5\ud55c \uc2dc\ud5d8\uc758 \uc138\uacc4\ub85c \ub4e4\uc5b4\uac04\ub2e4. \uc774 \ubcc0\ud654\uac00 \uc624\ub298\uc758 \uad00\uac1d\uc5d0\uac8c \ubaa8\ub450 \uc124\ub4dd\ub825 \uc788\uac8c \ub290\uaef4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc790\ub77c\uc2a4\ud2b8\ub85c\uc758 \uad8c\uc704\ub098 \uc5ec\uc131\uc744 \ub300\ud558\ub294 \ub9d0\uc5d0\ub294 \uc9c8\ubb38\ud560 \uc5ec\uc9c0\uac00 \uc788\ub2e4. \uc904\uac70\ub9ac\uac00 \uadf8\ub97c \uc88b\uc740 \ucabd\uc5d0 \ubc30\uce58\ud588\ub2e4\uace0 \ud574\uc11c \uadf8\uc758 \ubaa8\ub4e0 \ud310\ub2e8\uae4c\uc9c0 \uc6b0\ub9ac\uac00 \ubc1b\uc544\ub4e4\uc5ec\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc74c\uc545\uc744 \uc990\uae30\uba74\uc11c \uc778\ubb3c\uc758 \ub9d0\uc744 \ub530\uc838 \ub4e4\uc744 \uc218\ub3c4 \uc788\ub2e4. \uc2dc\ud5d8\uc5d0\ub294 \ub9d0\uc744 \uc0bc\uac00\uc57c \ud558\ub294 \uc870\uac74\uc774 \uc788\ub2e4. \ud0c0\ubbf8\ub178\uac00 \uce68\ubb35\ud558\uc790 \ud30c\ubbf8\ub098\ub294 \uc790\uc2e0\uc744 \ub354\ub294 \uc0ac\ub791\ud558\uc9c0 \uc54a\ub294\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4. \uad00\uac1d\uc740 \uc0ac\uc815\uc744 \uc54c\uc9c0\ub9cc \ud30c\ubbf8\ub098\ub294 \ubaa8\ub978\ub2e4. \uac00\uae4c\uc6b4 \uc0ac\ub78c\uc758 \uce68\ubb35\uc774 \uc5b4\ub5a4 \uc124\uba85\ubcf4\ub2e4 \uc794\uc778\ud558\uac8c \ub4e4\ub9b4 \uc218 \uc788\ub294 \uc21c\uac04\uc774\ub2e4. \uadf8\ub140\uc758 \uc2ac\ud514\uc744 \uac74\ub108\ub6f0\uba74 \ubaa8\ud5d8\uc758 \ubc18\ucabd\ub9cc \ub4e3\uac8c \ub41c\ub2e4. \ud30c\ubbf8\ub098\uc758 \uc544\ub9ac\uc544 \u300c\uc544, \ub098\ub294 \ub290\ub07c\ub124\u300d\uc5d0\uc11c\ub294 \ud654\ub824\ud55c \uae30\uad50\ubcf4\ub2e4 \uc0c1\uc2e4\uc758 \uac10\uc815\uc774 \uc55e\uc120\ub2e4. \ubc24\uc758 \uc5ec\uc655\ucc98\ub7fc \ub192\uc774 \uce58\uc19f\uc544 \uc0c1\ub300\ub97c \uc555\ub3c4\ud558\ub294 \ub178\ub798\uc640 \ub2e4\ub974\uac8c, \ub9c8\uc74c\uc774 \uc548\uc73c\ub85c \uac00\ub77c\uc549\ub294 \ub4ef\ud55c \uc2dc\uac04\uc744 \ub9cc\ub4e0\ub2e4. \uac19\uc740 \uc5ec\uc131\uc758 \ubaa9\uc18c\ub9ac\uc5ec\ub3c4 \uc778\ubb3c\uc758 \ucc98\uc9c0\uc5d0 \ub530\ub77c \uc74c\uc545\uc758 \ud45c\uc815\uc740 \uc804\ud600 \ub2ec\ub77c\uc9c4\ub2e4. \uc720\uba85\ud55c \u300c\uc9c0\uc625\uc758 \ubcf5\uc218\uac00 \ub0b4 \ub9c8\uc74c\uc5d0 \ub053\uc5b4\uc624\ub974\uace0\u300d\ub294 \ubc24\uc758 \uc5ec\uc655\uc774 \ub538\uc5d0\uac8c \uac15\ud55c \uc694\uad6c\ub97c \uc3df\uc544\ub0b4\ub294 \uc7a5\uba74\uc774\ub2e4. \uc81c\ubaa9\uc744 \ubaa8\ub974\ub354\ub77c\ub3c4 \uc544\uc8fc \ub192\uc740 \uc74c\uacfc \ub0a0\uce74\ub85c\uc6b4 \uc6c0\uc9c1\uc784\uc744 \ub4e4\uc73c\uba74 \uc54c\uc544\ucc28\ub9ac\ub294 \uc0ac\ub78c\uc774 \ub9ce\ub2e4. \ub2e8\uc21c\ud788 \uc608\uc05c \ubaa9\uc18c\ub9ac\ub97c \ubf50\ub0b4\ub294 \uace1\uc774 \uc544\ub2c8\ub77c \ubd84\ub178\uc640 \uba85\ub839\uc774 \ud615\uccb4\ub97c \uc5bb\ub294 \uc21c\uac04\uc774\ub2e4. \uc790\ub77c\uc2a4\ud2b8\ub85c\uc758 \ub0ae\uc740 \ubca0\uc774\uc2a4\uc640 \ub098\ub780\ud788 \ub4e4\uc73c\uba74 \ub300\ube44\uac00 \ub354\uc6b1 \ubd84\uba85\ud558\ub2e4. \ud55c\ucabd\uc740 \ubc88\uca4d \uce58\uc19f\uace0 \ub2e4\ub978 \ucabd\uc740 \ubb34\uac8c\ub97c \ub450\uba70 \uac00\ub77c\uc549\ub294\ub2e4. \ub2e4\ub9cc \ub192\uc740 \ubaa9\uc18c\ub9ac\ub294 \uc545\ud558\uace0 \ub0ae\uc740 \ubaa9\uc18c\ub9ac\ub294 \uc633\ub2e4\ub294 \uc77c\ubc18 \ubc95\uce59\uc740 \uc544\ub2c8\ub2e4. \ubaa8\ucc28\ub974\ud2b8\uac00 \uc774 \uadf9\uc758 \uc778\ubb3c\ub4e4\uc744 \ubc30\uce58\ud558\ub294 \uad6c\uccb4\uc801\uc778 \ubc29\ubc95\uc73c\ub85c \ub4e3\ub294 \ud3b8\uc774 \uc88b\ub2e4. \ud30c\ubbf8\ub098\ub294 \uc808\ub9dd\uc744 \uc9c0\ub098 \ub2e4\uc2dc \ud0c0\ubbf8\ub178\uc640 \ub9cc\ub09c\ub2e4. \uadf8\ub9ac\uace0 \ub9c8\uc9c0\ub9c9 \uc2dc\ud5d8\uc5d0\uc11c \ub4a4\uc5d0 \uc11c\uc11c \uad6c\ucd9c\uc744 \uae30\ub2e4\ub9ac\uae30\ub9cc \ud558\uc9c0 \uc54a\ub294\ub2e4. \ub450 \uc0ac\ub78c\uc740 \ud568\uaed8 \ubd88\uacfc \ubb3c\uc758 \uc2dc\ub828\uc744 \ud1b5\uacfc\ud55c\ub2e4. \ub9c8\uc220\ud53c\ub9ac\uc758 \uc74c\uc545\uc740 \uadf8 \uae38\uc744 \ub3d5\ub294\ub2e4. \uc81c\ubaa9\uc5d0 \ub2f4\uae34 \uc545\uae30\ub294 \uc7a5\uc2dd\ud488\uc774 \uc544\ub2c8\ub77c \ub450 \uc0ac\ub78c\uc774 \ub098\ub780\ud788 \uac77\ub294 \uc7a5\uba74\uc758 \uc911\uc2ec\uc774\ub2e4. \uc5ec\uae30\uc11c \uc6a9\uae30\ub294 \ud63c\uc790 \uc704\ud5d8\uc744 \uc774\uae30\ub294 \ub2a5\ub825\ub9cc\uc744 \ub73b\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc624\ud574\ub85c \uba40\uc5b4\uc84c\ub358 \ub450 \uc0ac\ub78c\uc774 \uac19\uc740 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc774\ub294 \ud798\uc774 \ub41c\ub2e4. \ud30c\ubbf8\ub098\ub97c \uacf5\uc8fc\ub97c \uad6c\ud558\ub294 \uc774\uc57c\uae30\uc758 \ubcf4\uc0c1\uc73c\ub85c\ub9cc \uae30\uc5b5\ud558\uba74 \uc774 \uc7a5\uba74\uc774 \uc791\uc544\uc9c4\ub2e4. \ub9c8\uc9c0\ub9c9\uc5d0 \uadf8\ub140\ub3c4 \uc120\ud0dd\ud558\uace0 \ud589\ub3d9\ud55c\ub2e4\ub294 \uc810\uc744 \ub193\uce58\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\ub2e4. \ud30c\ud30c\uac8c\ub178\ub294 \uc2dc\ud5d8\uc758 \ubaa8\ubc94\uc0dd\uc774 \ub418\uc9c0 \ubabb\ud55c\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubb34\ub300 \ubc16\uc73c\ub85c \ubc84\ub824\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \ubc29\uc6b8\uacfc \ub3c4\uc6c0\uc744 \ud1b5\ud574 \ud30c\ud30c\uac8c\ub098\ub97c \ub9cc\ub098\uace0, \ub450 \uc0ac\ub78c\uc774 \uc774\ub984\uc758 \uccab \uc74c\uc808\uc744 \uc8fc\uace0\ubc1b\ub294 \uc775\uc0b4\uc2a4\ub7ec\uc6b4 \uc774\uc911\ucc3d\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ud070 \uae68\ub2ec\uc74c\uc758 \uc138\uacc4 \uc606\uc5d0\uc11c \ud568\uaed8 \uc0b4\uc544\uac08 \uc0ac\ub78c\uc744 \ub9cc\ub098\ub294 \uae30\uc068\ub3c4 \uc644\uc131\ub41c\ub2e4. \uc791\ud488\uc5d0\ub294 \ub2f9\ub300\uc758 \uc131\ubcc4 \uad00\ub150\uacfc \uc778\uc885\uc801 \ud3b8\uacac\uc774 \ub0a8\uc544 \uc788\ub2e4. \uc624\ub298 \uacf5\uc5f0\ub4e4\uc774 \uadf8 \ud45c\ud604\uacfc \uc5f0\ucd9c\uc744 \uace0\ubbfc\ud558\ub294 \uc774\uc720\ub2e4. \uadf8\ub7f0 \ud55c\uacc4\ub97c \uc54c\uace0\ub3c4 \uc74c\uc545 \uc18d \uc778\ubb3c\uc758 \uac10\uc815\uc740 \uc0c8\ub86d\uac8c \ub4e4\uc744 \uc218 \uc788\ub2e4. \u300e\ub9c8\uc220\ud53c\ub9ac\u300f\uc758 \uc88b\uc740 \uc785\uad6c\ub294 \uc5b4\ub824\uc6b4 \uc0c1\uc9d5\uc744 \ubaa8\ub450 \ud478\ub294 \uc77c\uc774 \uc544\ub2c8\ub2e4. \uc624\ub298\uc740 \uc5ec\uc655\uc758 \ubd84\ub178\ub97c, \ub2e4\uc74c\uc5d0\ub294 \ud30c\ubbf8\ub098\uc758 \uc11c\uc6b4\ud568\uc744, \ub610 \ub2e4\ub978 \ub0a0\uc5d0\ub294 \uc0c8\uc7a1\uc774\uc758 \uc18c\ubc15\ud55c \ud589\ubcf5\uc744 \ub530\ub77c \ub4e4\uc5b4\uac00 \ubcf4\ub294 \uac83\uc774\ub2e4."}, {"id": "mozart-turkish-rondo", "title": "\ud130\ud0a4 \ud589\uc9c4\uace1 \u2014 \ud53c\uc544\ub178\uc5d0\uc11c \uad70\uc545\ub300\uac00 \ub4e4\ub9ac\ub294 \uc774\uc720", "summary": "\uc81c\ubaa9\uc758 \ub73b\uacfc \uc2dc\ub300\uc758 \uc74c\uc545 \ucde8\ud5a5, \uac00\ubcbc\uc6b4 \uc120\uc728\uacfc \ud798\ucc2c \uad6c\uac04\uc758 \ub300\ube44\ub97c \ub530\ub77c \ub4e3\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc74c\uc545", "categories": ["arts"], "url": "stories/mozart-turkish-rondo/index.html", "image": "../media/mozart-turkish-rondo-scene-20261030.png", "alt": "\ud587\uc0b4\uc774 \ub4e4\uc5b4\uc624\ub294 \ubc29\uc5d0\uc11c \uc61b \uac74\ubc18\uc545\uae30\ub97c \uc5f0\uc8fc\ud558\ub294 \uc190\uc758 \uc6c0\uc9c1\uc784\uc744 \ud45c\ud604\ud55c \uc0c1\uc0c1 \uc0bd\ud654.", "text": "\ud130\ud0a4 \ud589\uc9c4\uace1 \u2014 \ud53c\uc544\ub178\uc5d0\uc11c \uad70\uc545\ub300\uac00 \ub4e4\ub9ac\ub294 \uc774\uc720 \ubaa8\ucc28\ub974\ud2b8\uc758 \u2018\ud130\ud0a4\ud48d\u2019\uacfc \ud53c\uc544\ub178 \uc18c\ub098\ud0c0 K.331\uc758 \ub9c8\uc9c0\ub9c9 \uc545\uc7a5 \uc81c\ubaa9\uc758 \ub73b\uacfc \uc2dc\ub300\uc758 \uc74c\uc545 \ucde8\ud5a5, \uac00\ubcbc\uc6b4 \uc120\uc728\uacfc \ud798\ucc2c \uad6c\uac04\uc758 \ub300\ube44\ub97c \ub530\ub77c \ub4e3\uc2b5\ub2c8\ub2e4. \uc74c\uc545 \ubb38\ud654\uc640 \uc608\uc220 \ud53c\uc544\ub178\uac00 \uac00\ubccd\uac8c \uba87 \uc74c\uc744 \uad74\ub9ac\ub354\ub2c8 \uc5b4\ub290\uc0c8 \uc529\uc529\ud55c \uac78\uc74c\uc73c\ub85c \ubc14\ub010\ub2e4. \ubaa8\ucc28\ub974\ud2b8\uc758 \u3008\ud130\ud0a4 \ud589\uc9c4\uace1\u3009\uc740 \uc81c\ubaa9\uacfc \uc120\uc728\uc774 \ubaa8\ub450 \uce5c\uc219\ud558\ub2e4. \uadf8\ub7f0\ub370 \ud130\ud0a4 \uc0ac\ub78c\uc774 \ub9cc\ub4e0 \ud589\uc9c4\uace1\ub3c4, \uc6d0\ub798 \uad70\uc545\ub300\uac00 \uc5f0\uc8fc\ud558\ub3c4\ub85d \uc4f4 \uace1\ub3c4 \uc544\ub2c8\ub2e4. \ud53c\uc544\ub178 \ud55c \ub300\uac00 \uc11c\ub85c \ub2e4\ub978 \ud45c\uc815\uc744 \uc624\uac00\uba70 \ub4e4\ub824\uc8fc\ub294 \uc74c\uc545\uc774\ub2e4. \uc81c\ubaa9\uc744 \uc774\ud574\ud560 \uc2e4\ub9c8\ub9ac\ub294 \uc545\ubcf4\uc758 Alla Turca\uc5d0 \uc788\ub2e4. \u2018\ud130\ud0a4\ud48d\uc73c\ub85c\u2019\ub77c\ub294 \ub73b\uc774\ub2e4. \uc5b4\ub514\uc5d0\uc11c \ud0dc\uc5b4\ub09c \uace1\uc778\uac00\ubcf4\ub2e4 \uc5b4\ub5a4 \uc18c\ub9ac\uc640 \ubd84\uc704\uae30\ub97c \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294\uac00\ub97c \uc54c\ub824 \uc8fc\ub294 \uc774\ub984\uc774\ub2e4. \uc774 \uace1\uc740 \ubaa8\ucc28\ub974\ud2b8\uc758 \ud53c\uc544\ub178 \uc18c\ub098\ud0c0 K.331\uc5d0 \uc18d\ud55c\ub2e4. \uccab \uc545\uc7a5\uc740 \uc8fc\uc81c\uc640 \ubcc0\uc8fc, \ub458\uc9f8\ub294 \ubbf8\ub274\uc5d0\ud2b8, \ub9c8\uc9c0\ub9c9\uc774 \uc6b0\ub9ac\uac00 \ud589\uc9c4\uace1\uc73c\ub85c \ubd80\ub974\ub294 \ub860\ub3c4\ub2e4. \uc720\uba85\ud55c \ub9c8\uc9c0\ub9c9 \ubd80\ubd84\ub9cc \ub530\ub85c \uc5f0\uc8fc\ub418\uba74\uc11c \ud55c \uace1\uc758 \uc774\ub984\ucc98\ub7fc \uc775\uc219\ud574\uc84c\ub2e4. \uc791\ud488\ubc88\ud638 K.331\uc740 \ubaa8\ucc28\ub974\ud2b8\uc758 \uc74c\uc545\uc744 \uc815\ub9ac\ud55c \ubaa9\ub85d\uc758 \ubc88\ud638\ub2e4. \uccab \uc545\uc7a5\ubd80\ud130 \ub4e4\uc5b4 \ubcf4\uba74 \ub9c8\uc9c0\ub9c9\uc758 \uacbd\ucf8c\ud568\uc774 \uc55e\uc758 \uc74c\uc545\uacfc \uc5b4\ub5a4 \ub300\ube44\ub97c \uc774\ub8e8\ub294\uc9c0 \uc54c \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc138 \uc545\uc7a5\uc744 \ubaa8\ub450 \ub4e4\uc5b4\uc57c\ub9cc \uc774 \uace1\uc744 \uc990\uae38 \uc790\uaca9\uc774 \uc0dd\uae30\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9 \uc545\uc7a5\uc5d0\uc11c \uc2dc\uc791\ud574 \uc804\uccb4 \uc18c\ub098\ud0c0\ub85c \ub113\ud600 \uac00\ub3c4 \uc88b\ub2e4. \ub2f9\uc2dc \uc720\ub7fd \uc74c\uc545\uc5d0\ub294 \ud130\ud0a4\ud48d\uc744 \ub098\ud0c0\ub0b4\ub294 \ud45c\ud604\uc774 \uc0ac\uc6a9\ub418\uc5c8\ub2e4. \uad70\uc545\uc744 \uc5f0\uc0c1\uc2dc\ud0a4\ub294 \ud798 \uc788\ub294 \ubc15\uc790\uc640 \ud0c0\uc545\uae30 \uac19\uc740 \ud6a8\uacfc\uac00 \uadf8 \uc774\ubbf8\uc9c0\uc5d0 \ub4e4\uc5b4\uac04\ub2e4. \ubaa8\ucc28\ub974\ud2b8\uc758 \uc791\ud488\uc744 \ub2e4\ub8e8\ub294 \uc61b \uc804\uae30\ub3c4 \uc74c\uc545\uadf9\uc758 \ud130\ud0a4\ud48d \ub9ac\ub4ec\uacfc \uc74c\ud5a5\uc744 \uc124\uba85\ud558\uba74\uc11c \uadf8\uac83\uc774 \uc2e4\uc81c \ud130\ud0a4 \uc74c\uc545\uacfc \uaf2d \uac19\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub77c\uace0 \uc9da\ub294\ub2e4. \uadf8\ub7ec\ubbc0\ub85c \uc774 \uace1\uc744 \uc624\uc2a4\ub9cc \uc81c\uad6d\uc758 \uc0dd\ud65c\uacfc \uc74c\uc545\uc744 \uadf8\ub300\ub85c \uc62e\uae34 \uc18c\ub9ac \uae30\ub85d\ucc98\ub7fc \ub4e3\uc9c0\ub294 \ub9d0\uc790. \uc720\ub7fd\uc758 \uc791\uace1\uac00\uc640 \uccad\uc911\uc774 \uc790\uae30 \uc74c\uc545 \uc548\uc5d0\uc11c \ubc1b\uc544\ub4e4\uc778 \u2018\ud130\ud0a4\ud48d\u2019\uc774\ub77c\ub294 \uc591\uc2dd\uc73c\ub85c \ubcf4\ub294 \ud3b8\uc774 \uc801\uc808\ud558\ub2e4. \uc81c\ubaa9\uc5d0\ub294 \uc74c\uc545\uc758 \ud2b9\uc9d5\ubfd0 \uc544\ub2c8\ub77c \ub2e4\ub978 \ubb38\ud654\uac00 \uc5b4\ub5a4 \uc774\ubbf8\uc9c0\ub85c \uc804\ub2ec\ub418\uc5c8\ub294\uc9c0\uc5d0 \uad00\ud55c \uc5ed\uc0ac\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \uccab \ubd80\ubd84\uc740 \uc57d\ud55c \uc18c\ub9ac\ub85c \uc9e7\uc740 \uc74c\ub4e4\uc774 \uc6c0\uc9c1\uc778\ub2e4. \ubc14\ub85c \ud070 \uad70\uc545\ub300\uac00 \ub4f1\uc7a5\ud558\ub294 \ub300\uc2e0 \uc791\uc740 \ud68c\uc804\uacfc \uc7ac\ube60\ub978 \uac78\uc74c \uac19\uc740 \ub290\ub08c\uc744 \uc900\ub2e4. \uc545\ubcf4\ub97c \ubcf4\uc9c0 \uc54a\uc544\ub3c4 \uc74c\ub4e4\uc774 \uac00\uae4c\uc6b4 \uacf3\uc744 \uc624\uac00\ub294\uc9c0, \uae38\uac8c \ub178\ub798\ud558\ub294\uc9c0 \uadc0\ub97c \uae30\uc6b8\uc77c \uc218 \uc788\ub2e4. \ud53c\uc544\ub178\uc758 \ub0ae\uc740 \ucabd\uc5d0\uc11c\ub294 \ubc15\uc790\ub97c \uc7a1\ub294 \ubc18\uc8fc\uac00 \uc774\uc5b4\uc9c4\ub2e4. \uc704\ucabd\uc758 \uac00\ubcbc\uc6b4 \uc6c0\uc9c1\uc784\uacfc \uc544\ub798\ucabd\uc758 \uac78\uc74c\uc744 \ub530\ub85c \ub4e4\uc5b4 \ubcf4\uc790. \uc120\uc728\ub9cc \ub530\ub77c \ud765\uc5bc\uac70\ub9ac\ub358 \uace1\uc5d0\uc11c\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc5ed\ud560\uc758 \uc18c\ub9ac\uac00 \uc788\ub2e4\ub294 \uac83\uc744 \uc54c\uc544\ucc28\ub9ac\uac8c \ub41c\ub2e4. \uc791\uc740 \uc7a5\uba74\uc774\uc9c0\ub9cc \uc774\ubbf8 \ud63c\uc790 \ub178\ub798\ud558\ub294 \uc74c\uc545 \uc774\uc0c1\uc73c\ub85c \uc9dc\uc5ec \uc788\ub2e4. \uace1\uc774 \uc9c4\ud589\ub418\uba74 \ubc1d\uace0 \ud798\ucc2c \ubd80\ubd84\uc774 \ub098\ud0c0\ub098\uace0 \ud654\uc74c\uacfc \ubc18\ubcf5\ub418\ub294 \uc74c\uc774 \ub354 \ub450\ub4dc\ub7ec\uc9c4\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \ubcf4\ud1b5 \ud589\uc9c4\uace1\uc758 \uc131\uaca9\uc744 \uac15\ud558\uac8c \ub290\ub07c\ub294 \ub300\ubaa9\uc774\ub2e4. \uc55e\uc758 \uac00\ubcbc\uc6b4 \uc6c0\uc9c1\uc784\uacfc \ub098\ub780\ud788 \ub4e4\uc73c\uba74 \uac19\uc740 \ube60\ub974\uae30 \uc548\uc5d0\uc11c\ub3c4 \ubb34\uac8c\uc640 \ud45c\uc815\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \ubcf4\uc778\ub2e4. \uc5ec\uae30\uc11c \ud53c\uc544\ub178\ub294 \ubd81\uc774\ub098 \uc2ec\ubc8c\uc988\ub97c \uc2e4\uc81c\ub85c \ucd94\uac00\ud558\uc9c0 \uc54a\uace0\ub3c4 \ud0c0\uc545\uae30 \uac19\uc740 \ubd84\uba85\ud55c \ud0c0\uaca9\uac10\uc744 \ub9cc\ub4e4\uc5b4 \ub0bc \uc218 \uc788\ub2e4. \uc74c\uc744 \uc9e7\uac8c \uad6c\ubd84\ud558\uace0 \ud654\uc74c\uc744 \uac15\uc870\ud558\ub294 \ubc29\uc2dd\uc774 \ud6a8\uacfc\ub97c \ub0b8\ub2e4. \uc774 \uc18c\ub9ac\ub97c \ud2b9\uc815 \uad70\ub300\uc758 \uc2e4\uc81c \ud589\uc9c4 \uc7a5\uba74\uc73c\ub85c \ud655\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc545\uae30\uc758 \ud45c\ud604 \uac00\ub2a5\uc131\uc744 \ub4e3\ub294 \uae38\uc774\uae30\ub3c4 \ud558\ub2e4. \ub860\ub3c4\ub294 \uc911\uc694\ud55c \ubd80\ubd84\uc774 \ub2e4\ub978 \uad6c\uac04\uc744 \uc0ac\uc774\uc5d0 \ub450\uace0 \ub418\ub3cc\uc544\uc624\ub294 \ud615\uc2dd\uc744 \ub9d0\ud560 \ub54c \uc4f0\ub294 \uc774\ub984\uc774\ub2e4. \uc774 \uace1\uc5d0\uc11c\ub3c4 \uc775\uc219\ud55c \uc6c0\uc9c1\uc784\uc774 \ub3cc\uc544\uc624\uace0 \uc0c8\ub85c\uc6b4 \uc7a5\uba74\uc774 \ub07c\uc5b4\ub4e4\uba70 \uadc0\ub97c \ubd99\uc7a1\ub294\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uae00\uc790\ub85c \uc21c\uc11c\ub97c \uc678\uc6b0\uae30\ubcf4\ub2e4 \u2018\uc5ec\uae30 \ub2e4\uc2dc \ub098\uc654\ub124\u2019 \ud558\ub294 \uc21c\uac04\uc744 \ucc3e\uc73c\uba74 \ucda9\ubd84\ud558\ub2e4. \uac19\uc740 \ubd80\ubd84\uc774 \ub3cc\uc544\uc628\ub2e4\uace0 \uac10\uc0c1\uc774 \uc81c\uc790\ub9ac\ub9cc \ub3c4\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub978 \uc74c\uc0c9\uacfc \uac15\uc57d\uc744 \uc9c0\ub098 \ub2e4\uc2dc \ub9cc\ub098\ub294 \uc21c\uac04\uc740 \ucc98\uc74c\uacfc \ub2e4\ub974\uac8c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uc9d1 \uadfc\ucc98\uc758 \uc775\uc219\ud55c \uae38\ub3c4 \uba3c \uacf3\uc744 \ub2e4\ub140\uc628 \ub4a4\uc5d0\ub294 \uc870\uae08 \ub2e4\ub974\uac8c \ubcf4\uc774\ub294 \uac83\uacfc \ube44\uc2b7\ud558\ub2e4. \uc774\ub294 \uac10\uc0c1\uc744 \ub3d5\ub294 \ube44\uc720\uc774\uba70 \uc791\uace1\uac00\uac00 \uc815\ud574 \ub454 \uc774\uc57c\uae30\ub294 \uc544\ub2c8\ub2e4. \uc545\ubcf4\uc5d0\ub294 \ube60\ub974\uac8c \uc774\uc5b4\uc9c0\ub294 \uc74c\uacfc \uc190\uc758 \uc774\ub3d9, \uc9e7\uc740 \uac15\uc138\uc640 \ub300\ube44\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \uac00\ubccd\uac8c \ub4e4\ub9b0\ub2e4\uace0 \uc5f0\uc8fc\uc790\uc758 \uc190\uae4c\uc9c0 \ud3b8\uc548\ud558\uae30\ub9cc \ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc74c\ub4e4\uc774 \ubb49\uce58\uc9c0 \uc54a\ub3c4\ub85d \uc815\ub9ac\ud558\uba74\uc11c\ub3c4 \ubc15\uc790\uac00 \ub298\uc5b4\uc9c0\uc9c0 \uc54a\uc544\uc57c \uacbd\ucf8c\ud55c \uc778\uc0c1\uc774 \uc0b4\uc544\ub09c\ub2e4. \ub4e3\ub294 \uc0ac\ub78c\uc740 \uc5f0\uc8fc \uae30\uc220\uc744 \ud3c9\uac00\ud558\ub824 \uc560\uc4f0\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4. \uc9e7\uc740 \uc74c\uc774 \uc5bc\ub9c8\ub098 \ub610\ub837\ud558\uac8c \uc774\uc5b4\uc9c0\ub294\uc9c0, \uac15\ud55c \ubd80\ubd84\uc73c\ub85c \ub118\uc5b4\uac08 \ub54c \ub9ac\ub4ec\uc774 \uc5b4\ub5bb\uac8c \ub290\uaef4\uc9c0\ub294\uc9c0\ub9cc \uc0b4\ud3b4\ubcf4\uc790. \uac19\uc740 \uace1\uc758 \uc5f0\uc8fc \ub450 \uac1c\ub97c \ube44\uad50\ud558\uba74 \uc18c\ub9ac\uc758 \ubb34\uac8c\uc640 \uc7a5\ub09c\uc2a4\ub7ec\uc6b4 \ub290\ub08c\uc774 \uaf64 \ub2e4\ub97c \uc218 \uc788\ub2e4. \ucc98\uc74c\uc758 \uc8fc\uc81c\uc640 \ubcc0\uc8fc\uc5d0\uc11c\ub294 \ud558\ub098\uc758 \ub178\ub798\uac00 \uc5ec\ub7ec \ubaa8\uc2b5\uc73c\ub85c \ubc14\ub00c\uace0, \ubbf8\ub274\uc5d0\ud2b8\uc5d0\uc11c\ub294 \ucda4\uc758 \uac78\uc74c\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \ub9c8\uc9c0\ub9c9 \ub860\ub3c4\ub294 \ub610 \ub2e4\ub978 \ubc29\uc2dd\uc758 \ud65c\uae30\ub97c \ub9cc\ub4e0\ub2e4. \ud55c \uc18c\ub098\ud0c0 \uc548\uc5d0 \ubcc0\ud615, \ucda4, \ubc18\ubcf5\uacfc \ub300\ube44\ub77c\ub294 \uc11c\ub85c \ub2e4\ub978 \uc7ac\ubbf8\uac00 \uc788\ub294 \uc148\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \uac74\ubc18\uc744 \uc5f0\uc8fc\ud558\ub294 \uc190\uc758 \uc6c0\uc9c1\uc784\uc73c\ub85c \uace1\uc758 \uacbd\ucf8c\ud568\uc744 \ud45c\ud604\ud55c AI \uc0bd\ud654\ub2e4. \ubaa8\ucc28\ub974\ud2b8\uc758 \uc2e4\uc81c \uc5f0\uc8fc\ub098 \ub2f9\uc2dc \uad70\uc545\ub300\uc758 \ubaa8\uc2b5\uc744 \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc720\uba85\ud55c \ud589\uc9c4\uace1\uc744 \uc804\uccb4 \uc791\ud488\uc758 \uc9c0\ub3c4\uc5d0 \ud55c \ubc88 \uc62c\ub824 \ubcf4\uba74, \uc774 \uace1 \uc55e\ub4a4\uc758 \uc74c\uc545\uc744 \ucc3e\ub294 \uc77c\ub3c4 \uc26c\uc6cc\uc9c4\ub2e4. \ud55c \ubc88\uc740 \uc775\uc219\ud55c \uba5c\ub85c\ub514\ub97c \ud3b8\ud558\uac8c \ub4e3\uace0, \ub2e4\uc74c\uc5d0\ub294 \uc57d\ud558\uac8c \uc2dc\uc791\ud558\ub294 \ubd80\ubd84\uacfc \ud798\ucc28\uac8c \ub098\uc11c\ub294 \ubd80\ubd84\uc758 \ucc28\uc774\ub97c \ub4e4\uc5b4 \ubcf4\uc790. \uadf8\ub2e4\uc74c \uc804\uccb4 \uc18c\ub098\ud0c0\ub85c \ub3cc\uc544\uac00\uba74 \ub9c8\uc9c0\ub9c9 \uc545\uc7a5\uc758 \uc131\uaca9\uc774 \ub354 \ub610\ub837\ud574\uc9c4\ub2e4. \uc54c\uac8c \ub41c \uc9c0\uc2dd\uc774 \uc74c\uc545\uc744 \ubc29\ud574\ud558\uae30\ubcf4\ub2e4 \uadc0\uac00 \uba38\ubb3c \uc790\ub9ac\ub97c \ub298\ub9ac\ub294 \ubc29\uc2dd\uc774\ub2e4. \u3008\ud130\ud0a4 \ud589\uc9c4\uace1\u3009\uc758 \uc81c\ubaa9\uc740 \ud130\ud0a4\uc758 \ubaa8\ub4e0 \uc74c\uc545\uc744 \ub300\ud45c\ud55c\ub2e4\ub294 \uc120\uc5b8\uc774 \uc544\ub2c8\ub2e4. \uc720\ub7fd \uc74c\uc545 \uc548\uc5d0\uc11c \ubc1b\uc544\ub4e4\uc778 \ud55c \uc591\uc2dd\uacfc \ud53c\uc544\ub178\uc758 \ud45c\ud604\uc744 \ub9cc\ub098\ub294 \uc791\uc740 \ubb38\uc774\ub2e4. \uadf8 \ucc28\uc774\ub97c \uc54c\uace0 \ub098\uba74 \uc775\uc219\ud55c \uace1\uc744 \uc990\uae30\uba74\uc11c\ub3c4, \ub2e4\ub978 \ubb38\ud654\uc758 \uc774\ub984\uc774 \uc74c\uc545 \uc18d\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uc4f0\uc600\ub294\uc9c0 \ud568\uaed8 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4."}, {"id": "nara-todaiji-buddha-and-state", "title": "\ub098\ub77c\uc758 \ub3c4\ub2e4\uc774\uc9c0 \u2014 \uac70\ub300\ud55c \ubd88\uc0c1\uc5d0 \ub2f4\uae34 \uad6d\uac00\uc758 \ubc14\ub78c", "summary": "\uac70\ub300\ud55c \ubd88\uc0c1\uc758 \uc2e0\uc559\uc801 \uc758\ubbf8\uc640 \uad6d\uac00\uc801 \uc0ac\uc5c5, \uc81c\uc791\uacfc \uc720\uc9c0\uc758 \uc2dc\uac04\uc744 \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uac74\ucd95", "categories": ["arts"], "url": "stories/nara-todaiji-buddha-and-state/index.html", "image": "../media/nara-todaiji-buddha-and-state.png", "alt": "\ub3c4\ub2e4\uc774\uc9c0 \ub300\ubd88\uc804\uc744 \ub5a0\uc62c\ub9ac\ub294 \ud070 \ubaa9\uc870 \uc804\uac01\uacfc \uc791\uc740 \ubc29\ubb38\uac1d \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ub098\ub77c\uc758 \ub3c4\ub2e4\uc774\uc9c0 \u2014 \uac70\ub300\ud55c \ubd88\uc0c1\uc5d0 \ub2f4\uae34 \uad6d\uac00\uc758 \ubc14\ub78c \uc1fc\ubb34\uc758 \ubc1c\uc6d0\uacfc 752\ub144 \uac1c\uc548, \ubd88\uc0c1\uacfc \uac74\ucd95\uc744 \ub458\ub7ec\uc2fc \uc0ac\ub78c\ub4e4 \uac70\ub300\ud55c \ubd88\uc0c1\uc758 \uc2e0\uc559\uc801 \uc758\ubbf8\uc640 \uad6d\uac00\uc801 \uc0ac\uc5c5, \uc81c\uc791\uacfc \uc720\uc9c0\uc758 \uc2dc\uac04\uc744 \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4. \uac74\ucd95 \ubb38\ud654\uc640 \uc608\uc220 \uc77c\ubcf8 \ub098\ub77c\uc758 \ub3c4\ub2e4\uc774\uc9c0\uc5d0\uc11c\ub294 \uac74\ubb3c\uc758 \ud06c\uae30\ubd80\ud130 \ubab8\uc73c\ub85c \ub290\ub07c\uac8c \ub41c\ub2e4. \ud070 \ubaa9\uc870 \uc804\uac01 \uc548\uc5d0 \uac70\ub300\ud55c \ubd88\uc0c1\uc774 \uc790\ub9ac\ud55c\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc5bc\ub9c8\ub098 \ud070\uac00\ub77c\ub294 \uc9c8\ubb38\uc774 \uc55e\uc11c\uc9c0\ub9cc \uace7 \ub2e4\ub978 \uad81\uae08\uc99d\uc774 \uc0dd\uae34\ub2e4. \uc65c \uc774\ub9cc\ud55c \uaddc\ubaa8\uc758 \ubd88\uc0c1\uc744 \ub9cc\ub4e4\ub824 \ud588\uc744\uae4c. \ub204\uac00 \uadf8 \uc77c\uc744 \uacc4\ud68d\ud558\uace0 \ubb34\uc5c7\uc744 \uae30\ub300\ud588\uc744\uae4c. \ub3c4\ub2e4\uc774\uc9c0\uc758 \uc5ed\uc0ac\ub294 \ubd88\uad50 \ubbf8\uc220\uacfc \uad6d\uac00 \uc6b4\uc601\uc774 \ub9cc\ub09c 8\uc138\uae30\uc758 \uc138\uacc4\ub85c \uc774\uc5b4\uc9c4\ub2e4. \uc2e0\uc559\uc758 \ub300\uc0c1\uc778 \ubd88\uc0c1\uc740 \ub3d9\uc2dc\uc5d0 \ub9ce\uc740 \uc790\uc6d0\uacfc \ub178\ub3d9\uc744 \ubaa8\uc740 \uacb0\uacfc\uc600\ub2e4. \uac10\ud0c4\ud560 \ub9cc\ud55c \ud06c\uae30\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uadf8 \uc548\uc5d0 \ub2f4\uae34 \uc815\uce58\uc640 \uae30\uc220, \uc774\ud6c4\uc758 \uc2dc\uac04\uc744 \ud568\uaed8 \uc77d\uc5b4 \ubcf4\uc790. 8\uc138\uae30\uc758 \ub098\ub77c\ub294 \uc655\uc2e4\uacfc \uad00\ub8cc \uc870\uc9c1\uc774 \ubaa8\uc778 \uc911\uc694\ud55c \uc911\uc2ec\uc9c0\uc600\ub2e4. \uc911\uad6d \ub300\ub959\uacfc \ud55c\ubc18\ub3c4\ub97c \ud1b5\ud574 \ub4e4\uc5b4\uc628 \uc9c0\uc2dd\uacfc \uc81c\ub3c4, \ubd88\uad50\uc758 \uc5ec\ub7ec \uc804\ud1b5\uc774 \uc77c\ubcf8\uc758 \uad8c\ub825\uacfc \ubb38\ud654 \uc18d\uc5d0\uc11c \uc0c8\ub86d\uac8c \uc790\ub9ac \uc7a1\uc558\ub2e4. \uc678\ubd80\uc758 \uac83\uc744 \ub2e8\uc21c\ud788 \ubcf5\uc0ac\ud55c \uacf5\uac04\uc774\ub77c\uae30\ubcf4\ub2e4 \uadf8\uac83\uc744 \uc790\uae30 \uccb4\uacc4\uc640 \uacb0\ud569\ud55c \uacf3\uc774\uc5c8\ub2e4. \uc624\ub298\uc758 \uad6d\uacbd\uc744 \ub2f9\uc2dc\uc758 \uc774\ub3d9\uc5d0 \uadf8\ub300\ub85c \uc801\uc6a9\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\ub2e4. \uc0ac\ub78c\uacfc \uacbd\uc804, \uacf5\uc608\uc758 \uae30\uc220\uc740 \uc5ec\ub7ec \uacbd\ub85c\ub97c \uac70\ucce4\ub2e4. \ub3c4\ub2e4\uc774\uc9c0\ub97c \uc77c\ubcf8\uc758 \ub300\ud45c \uc0ac\ucc30\ub85c \uc77d\uc73c\uba74\uc11c\ub3c4 \uadf8 \ubc14\ud0d5\uc5d0 \uad6d\uacbd\uc744 \ub118\ub294 \uad50\ub958\uac00 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ud55c \uc7a5\uc18c\uc758 \ubb38\ud654\ub294 \uace0\ub9bd\ub41c \ucc44 \uc790\ub77c\uc9c0 \uc54a\uc558\ub2e4. \uc1fc\ubb34 \ucc9c\ud669\uc740 \uac70\ub300\ud55c \ubd88\uc0c1 \uc870\uc131\uc744 \ucd94\uc9c4\ud588\ub2e4. \uadf8 \ubc30\uacbd\uc5d0\ub294 \ubd88\uad50\uc758 \ud798\uc744 \ud1b5\ud574 \uad6d\uac00\uc758 \uc548\uc815\uacfc \ud3c9\uc548\uc744 \ubc14\ub77c\ub294 \uc0dd\uac01\uc774 \uc788\uc5c8\ub2e4. \uc624\ub298\uc758 \uad00\ub78c\uac1d\uc5d0\uac8c\ub294 \uc720\uc0b0\uacfc \uc608\uc220\uc774\uc9c0\ub9cc \ub2f9\uc2dc\uc5d0\ub294 \uc2e4\uc81c\ub85c \uc138\uacc4\uc5d0 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\ub294 \uc2e0\uc559\uc758 \ud589\uc704\uc600\ub2e4. \uc815\uce58\uc640 \uc885\uad50\ub97c \uc11c\ub85c \uba3c \uc601\uc5ed\uc73c\ub85c \ub098\ub204\uae30 \uc5b4\ub824\uc6b4 \uc2dc\ub300\ub2e4. \uc655\uc2e4\uc758 \uae30\uc6d0\uc774\ub77c\uace0 \ud574\uc11c \uac1c\uc778\uc801\uc778 \ub9c8\uc74c\ub9cc\uc73c\ub85c \uc124\uba85\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc9c0\ubc29 \uc0ac\ucc30\uc744 \ud3ec\ud568\ud55c \ubd88\uad50\uc758 \uc870\uc9c1\uacfc \uad6d\uac00\uc758 \uc9c8\uc11c\uac00 \uc5f0\uacb0\ub418\uc5c8\ub2e4. \ud070 \ubd88\uc0c1\uc740 \ud55c \uc0ac\ub78c\uc758 \uae4a\uc740 \ubbff\uc74c\uc744 \ubcf4\uc5ec \uc8fc\uba74\uc11c \ub3d9\uc2dc\uc5d0 \uadf8 \ubbff\uc74c\uc774 \uacf5\uc801\uc778 \uc0ac\uc5c5\uc774 \ub418\ub294 \uacfc\uc815\uc744 \ub4dc\ub7ec\ub0b8\ub2e4. \ud06c\uae30\uc5d0\ub294 \uc774\ub7f0 \uc81c\ub3c4\uc801 \ubc30\uacbd\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \ud070 \uccad\ub3d9\ubd88\uc744 \ub9cc\ub4e4\ub824\uba74 \uc7ac\ub8cc\ub97c \ubaa8\uc73c\uace0 \uc8fc\uc870\ud558\uba70 \uc5ec\ub7ec \ubd80\ubd84\uc744 \ub9de\ucd94\ub294 \uae30\uc220\uc774 \ud544\uc694\ud588\ub2e4. \uc791\uc740 \ubd88\uc0c1\uc744 \ud06c\uac8c \ud655\ub300\ud558\ub294 \uac83\ub9cc\uc73c\ub85c \ud574\uacb0\ub418\ub294 \uc77c\uc774 \uc544\ub2c8\ub2e4. \ud06c\uae30\uac00 \ubc14\ub00c\uba74 \ubb34\uac8c\uc640 \uc791\uc5c5\uc758 \ubc29\ubc95, \uc2e4\ud328\ud588\uc744 \ub54c\uc758 \ubd80\ub2f4\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc885\uad50\uc801 \ub73b\uc744 \uac00\uc9c4 \uc0ac\uc5c5\uc740 \uad6c\uccb4\uc801\uc778 \uae30\uc220\uc758 \ubb38\uc81c\ub97c \ub9cc\ub098\uc57c \ud588\ub2e4. \uc774\ub54c \ud654\ub824\ud55c \uc644\uc131\ud488\ub9cc \ubcf4\uba74 \uc7ac\ub8cc\ub97c \ub9c8\ub828\ud558\uace0 \ud604\uc7a5\uc5d0\uc11c \uc77c\ud55c \uc0ac\ub78c\ub4e4\uc740 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uad6d\uac00\uac00 \ud070 \uc790\uc6d0\uc744 \ubaa8\uc744 \uc218 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8 \uc77c\uc744 \uc218\ud589\ud55c \ub178\ub3d9\uc740 \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \uac70\ub300\ud55c \ubd88\uc0c1\uc740 \uc2e0\uc559\uc758 \uc774\ubbf8\uc9c0\uc774\uba74\uc11c \ub9ce\uc740 \uc0ac\ub78c\uc758 \uc77c\uc774 \uc9d1\uc911\ub41c \ubb3c\uc9c8\uc774\uae30\ub3c4 \ud588\ub2e4. \ubd88\uc0c1\uacfc \uad00\ub828\ub41c \uc911\uc694\ud55c \uc0ac\uac74\uc740 752\ub144\uc758 \uac1c\uc548 \uc758\ub840\ub2e4. \ub208\uc744 \uc5f0\ub2e4\ub294 \ud45c\ud604\uc740 \ub2e8\uc21c\ud788 \uc644\uc131\ud488\uc758 \ub36e\uac1c\ub97c \ubc97\uae30\ub294 \ud589\uc0ac\ub97c \ub118\uc5b4 \uc885\uad50\uc801 \uc758\ubbf8\ub97c \uac16\ub294\ub2e4. \ub9cc\ub4e0 \ubb3c\uac74\uc744 \uc608\ubc30\uc758 \ub300\uc0c1\uc73c\ub85c \ub300\ud558\ub294 \uacfc\uc815\uc5d0\uc11c \uc758\uc2dd\uc774 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud588\ub2e4. \uc81c\uc791\uc758 \uc644\ub8cc\uc640 \uc2e0\uc559\uc801 \uc2dc\uc791\uc740 \uc11c\ub85c \uad00\ub828\ub418\uba74\uc11c\ub3c4 \ub2e4\ub974\ub2e4. \uc655\uc2e4\uacfc \uc5ec\ub7ec \uc9c0\uc704\uc758 \uc0ac\ub78c\ub4e4\uc774 \ucc38\uc5ec\ud55c \ud070 \ud589\uc0ac\ub294 \ubd88\uc0c1\uc744 \uac1c\uc778\uc774 \ub530\ub85c \uac10\uc0c1\ud558\ub294 \uc870\uac01\uacfc \ub2e4\ub978 \uc790\ub9ac\uc5d0 \ub193\ub294\ub2e4. \uacf5\ub3d9\uccb4\uac00 \ud568\uaed8 \ubcf4\uba70 \ub73b\uc744 \ud655\uc778\ud558\ub294 \uc0ac\uac74\uc774\uc5c8\ub2e4. \uac74\ubb3c\uacfc \ubd88\uc0c1\uc758 \uc5ed\uc0ac\ub97c \uc5f0\ub300\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uc9c0 \uc54a\uace0 \uc5b4\ub5a4 \ud589\uc704\uac00 \uadf8 \uc8fc\uc704\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc84c\ub294\uc9c0 \ud568\uaed8 \ubcf4\uc544\uc57c \ud558\ub294 \uc774\uc720\ub2e4. \uac70\ub300\ud55c \ubd88\uc0c1\uc740 \uadf8\uac83\uc744 \ub458\ub7ec\uc2fc \uacf5\uac04\uacfc \ud568\uaed8 \uacbd\ud5d8\ub41c\ub2e4. \ubb38\uc744 \ud1b5\uacfc\ud574 \uc548\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \uacfc\uc815, \ube5b\uacfc \uadf8\ub9bc\uc790\uc758 \ucc28\uc774, \uc0ac\ub78c \ubab8\uacfc \ube44\uad50\ub418\ub294 \ud06c\uae30\uac00 \uac10\uc0c1\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4. \ubd88\uc0c1 \uc0ac\uc9c4 \ud55c \uc7a5\uacfc \uc804\uac01 \uc548\uc5d0 \uc11c \uc788\ub294 \uacbd\ud5d8\uc774 \ub2e4\ub978 \uc774\uc720\ub2e4. \uac74\ucd95\uc740 \uc870\uac01\uc758 \ubc30\uacbd\ub9cc\uc774 \uc544\ub2c8\ub2e4. \ubd88\uc0c1\uc758 \ud45c\uba74\ub9cc \ubcf4\ub2e4\uac00 \uc804\uac01\uc758 \uc9c0\uc9c0 \uad6c\uc870\uc640 \uc9c0\ubd95, \uc5f4\ub9b0 \uacf5\uac04\uc73c\ub85c \ub208\uc744 \uc62e\uaca8 \ubcf4\uc790. \ubb34\uc5c7\uc744 \ub2f4\uae30 \uc704\ud574 \uc774\ub9cc\ud55c \uacf5\uac04\uc774 \ud544\uc694\ud588\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uc870\uac01\uacfc \uac74\ucd95\uc744 \ubcc4\uac1c\uc758 \ud56d\ubaa9\uc73c\ub85c\ub9cc \ub098\ub204\uc9c0 \uc54a\uc744 \ub54c \uac70\ub300\ud55c \uc885\uad50 \uacf5\uac04\uc774 \uc0ac\ub78c\uc5d0\uac8c \uc8fc\ub294 \ub290\ub08c\ub3c4 \ub354 \uc798 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc0ac\ub78c\uc758 \uc5bc\uad74\uacfc \ube44\uad50\ub418\ub294 \ubd88\uc0c1\uc758 \ud070 \uc5bc\uad74, \uadf8 \uc55e\uc5d0\uc11c \uc6c0\uc9c1\uc774\ub294 \uc791\uc740 \ubab8\uc758 \ucc28\uc774\ub97c \ub290\uaef4 \ubcf4\uc790. \uaddc\ubaa8\ub97c \uc22b\uc790\ub85c \uc544\ub294 \uac83\uacfc \uc790\uae30 \ubab8\uc744 \uae30\uc900\uc73c\ub85c \uacbd\ud5d8\ud558\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uc885\uad50 \uacf5\uac04\uc740 \uadf8 \ucc28\uc774\ub97c \uac10\uac01\uc801\uc73c\ub85c \ub4dc\ub7ec\ub0b4\uae30\ub3c4 \ud55c\ub2e4. \uc624\ub798\ub41c \ubaa9\uc870 \uc0ac\ucc30\uc740 \ud654\uc7ac\uc640 \uc190\uc0c1, \uc218\ub9ac\uc640 \uc7ac\uac74\uc758 \uc2dc\uac04\uc744 \uac70\ucce4\ub2e4. \uadf8\ub798\uc11c \uc624\ub298 \ub208\uc55e\uc5d0 \uc788\ub294 \ubaa8\ub4e0 \uc694\uc18c\ub97c 8\uc138\uae30\uc758 \uc190\uae38\uc774 \uadf8\ub300\ub85c \uba48\ucd98 \ubaa8\uc2b5\uc73c\ub85c \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc2dc\uc791\uc758 \uc5f0\ub3c4\uc640 \ud604\uc874\ud558\ub294 \ubb3c\uc9c8\uc758 \uc5ed\uc0ac\ub294 \ub098\ub204\uc5b4 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc774 \ucc28\uc774\uac00 \uc720\uc0b0\uc758 \uac00\uce58\ub97c \uc904\uc774\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc624\ud788\ub824 \uadf8 \uc7a5\uc18c\ub97c \uacc4\uc18d \ub0a8\uae30\ub824 \ud55c \ud6c4\ub300 \uc0ac\ub78c\ub4e4\uc758 \uc77c\uc774 \ubcf4\uc778\ub2e4. \uc624\ub798\ub418\uc5c8\ub2e4\ub294 \uac83\uc740 \uc544\ubb34\ub3c4 \uc190\ub300\uc9c0 \uc54a\uc558\ub2e4\ub294 \ub73b\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uace0\uce58\uace0 \uc720\uc9c0\ud558\uace0 \ub2e4\uc2dc \uc758\ubbf8\ub97c \ubd80\uc5ec\ud55c \uc2dc\uac04\uc774 \uc313\uc600\ub2e4\ub294 \ub73b\uc774\uae30\ub3c4 \ud558\ub2e4. \ub3c4\ub2e4\uc774\uc9c0\uc758 \uc5ed\uc0ac\uc5d0\ub294 \uadf8 \uae34 \uc774\uc5b4\uc9d0\uc774 \uc788\ub2e4. \ub3c4\ub2e4\uc774\uc9c0\uc758 \uaddc\ubaa8\ub294 \uc655\uc2e4\uc758 \ud798\uacfc \uc885\uad50\uc801 \uc774\uc0c1\uc744 \ub290\ub07c\uac8c \ud55c\ub2e4. \uadf8\ub7ec\ub098 \uac10\ud0c4\uc774 \uac70\uae30\uc5d0\ub9cc \uba38\ubb3c \ud544\uc694\ub294 \uc5c6\ub2e4. \uc678\ubd80\uc5d0\uc11c \uc628 \uc9c0\uc2dd\uacfc \uc9c0\uc5ed\uc758 \uc120\ud0dd, \uc8fc\uc870\uc758 \uae30\uc220\uacfc \ubc18\ubcf5\ub418\ub294 \ubcf4\uc874\uc774 \ud55c \uc7a5\uc18c\uc5d0 \ubaa8\uc5ec \uc788\uc5c8\ub2e4. \uc138\uacc4\ub97c \uc124\uba85\ud558\ub294 \ubbff\uc74c\uc774 \uc2e4\uc81c \uac74\ubb3c\uacfc \ubb3c\uc9c8\ub85c \ub9cc\ub4e4\uc5b4\uc9c4 \uac83\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \ub098\ub77c\uc758 \ub300\ubd88\uc744 \ubcfc \ub54c\uc5d0\ub294 \uac70\ub300\ud55c \uc5bc\uad74 \uc606\uc5d0 \uadf8\uac83\uc744 \ubc14\ub77c\ubcf4\uace0 \ub9cc\ub4e4\uace0 \uc9c0\ucf1c \uc628 \uc0ac\ub78c\ub4e4\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ubd88\uc0c1\uc740 \uace0\uc694\ud558\uac8c \uc549\uc544 \uc788\uc9c0\ub9cc \uadf8 \uc8fc\ubcc0\uc758 \uc5ed\uc0ac\ub294 \uacc4\uc18d \uc6c0\uc9c1\uc600\ub2e4. \uc2e0\uc559\uacfc \uad6d\uac00, \uae30\uc220\uacfc \uc0ac\ub78c\uc758 \uc2dc\uac04\uc744 \ud568\uaed8 \uc77d\uc73c\uba74 \uc0ac\ucc30\uc758 \ud070 \uacf5\uac04\uc774 \ub354 \uad6c\uccb4\uc801\uc778 \uc774\uc57c\uae30\ub97c \ub4e4\ub824\uc900\ub2e4."}, {"id": "notre-dame-novel-and-misunderstood-love", "title": "\ub178\ud2b8\ub974\ub2f4 \ub4dc \ud30c\ub9ac \u2014 \uc131\ub2f9\uc758 \uc885\uc9c0\uae30\ub294 \ub204\uad6c\ub97c \uc0ac\ub791\ud588\uc744\uae4c", "summary": "\uc704\uace0 \uc6d0\uc791\uc758 \uc778\ubb3c \uad00\uacc4\uc640 \uacb0\ub9d0\ub85c \uc77d\ub294 \uc0ac\ub791\u00b7\ud3b8\uacac\u00b7\ud53c\ub09c\ucc98\uc744 \uc774\uc57c\uae30\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/notre-dame-novel-and-misunderstood-love/index.html", "image": "../media/notre-dame-novel-and-misunderstood-love.png", "alt": "\ud30c\ub9ac \uc131\ub2f9\uc758 \ub192\uc740 \uc885\ud0d1\uc5d0\uc11c \uc885 \uacc1\uc5d0 \uc120 \uc885\uc9c0\uae30 \uc0bd\ud654", "text": "\ub178\ud2b8\ub974\ub2f4 \ub4dc \ud30c\ub9ac \u2014 \uc131\ub2f9\uc758 \uc885\uc9c0\uae30\ub294 \ub204\uad6c\ub97c \uc0ac\ub791\ud588\uc744\uae4c \uc704\uace0 \uc6d0\uc791\uc758 \uc778\ubb3c \uad00\uacc4\uc640 \uacb0\ub9d0\ub85c \uc77d\ub294 \uc0ac\ub791\u00b7\ud3b8\uacac\u00b7\ud53c\ub09c\ucc98 \uc704\uace0 \uc6d0\uc791\uc758 \uc778\ubb3c \uad00\uacc4\uc640 \uacb0\ub9d0\ub85c \uc77d\ub294 \uc0ac\ub791\u00b7\ud3b8\uacac\u00b7\ud53c\ub09c\ucc98\uc744 \uc774\uc57c\uae30\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \ube45\ud1a0\ub974 \uc704\uace0\uc758 \u300e\ub178\ud2b8\ub974\ub2f4 \ub4dc \ud30c\ub9ac\u300f\ub294 \uc131\ub2f9\uc758 \uc885\uc9c0\uae30 \uce74\uc9c0\ubaa8\ub3c4\uac00 \ub4f1\uc7a5\ud558\ub294 \uc18c\uc124\uc774\ub2e4. \uadf8\ub7ec\ub098 \uadf8\ub97c \uae30\uc774\ud55c \uc678\ubaa8\uc758 \uc8fc\uc778\uacf5\uc73c\ub85c\ub9cc \uae30\uc5b5\ud558\uba74 \uc791\ud488\uc758 \ud070 \ubd80\ubd84\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc0ac\ub791\uacfc \uc695\ub9dd, \ud30c\ub9ac\uc758 \uad70\uc911\uacfc \uc7ac\ud310, \uadf8\ub9ac\uace0 \uac70\ub300\ud55c \uc131\ub2f9\uc774 \ube44\uadf9\uc744 \ud568\uaed8 \ub9cc\ub4e0\ub2e4. \uc774 \uae00\uc5d0\ub294 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc774 \ud3ec\ud568\ub41c\ub2e4. \uc775\uc219\ud55c \uacf5\uc5f0\uc774\ub098 \uc601\ud654\uc758 \ud589\ubcf5\ud55c \uc7a5\uba74\uc744 \uc6d0\uc791\uc758 \uacb0\ub9d0\uacfc \ud63c\ub3d9\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\ub2e4. \uc704\uace0\uac00 \uadf8\ub9b0 \uc774\uc57c\uae30\ub294 \ub204\uad70\uac00\ub97c \uc0ac\ub791\ud55c\ub2e4\ub294 \ub9d0\uacfc \uadf8 \uc0ac\ub78c\uc744 \uc2e4\uc81c\ub85c \uc774\ud574\ud558\ub294 \uc77c\uc774 \uc5bc\ub9c8\ub098 \ub2e4\ub97c \uc218 \uc788\ub294\uc9c0 \ubcf4\uc5ec \uc900\ub2e4. \uc18c\uc124\uc758 \uc8fc\uc694 \ubb34\ub300\ub294 1482\ub144\uc758 \ud30c\ub9ac\ub2e4. \uc704\uace0\ub294 \uc790\uc2e0\ubcf4\ub2e4 \uc55e\uc120 \uc2dc\ub300\uc758 \ub3c4\uc2dc\ub97c \ub418\uc0b4\ub9ac\uba70 \ub178\ud2b8\ub974\ub2f4 \ub300\uc131\ub2f9\uc744 \uc774\uc57c\uae30\uc758 \ud55c\uac00\uc6b4\ub370 \ub193\uc558\ub2e4. \uad11\uc7a5\uacfc \uace8\ubaa9, \uad81\uc815\uacfc \uc131\ub2f9\uc774 \uc11c\ub85c \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc758 \uc0b6\uc744 \uc5f0\uacb0\ud55c\ub2e4. \ub3c4\uc2dc\ub294 \uc0ac\uac74\uc758 \ubc30\uacbd\uc744 \uc81c\uacf5\ud558\ub294 \ube48 \ubb34\ub300\uac00 \uc544\ub2c8\ub2e4. \uc131\ub2f9\uc740 \ud2b9\ud788 \uc911\uc694\ud558\ub2e4. \uc885\uc744 \uc6b8\ub9ac\ub294 \uc77c\ud130\uc774\uc790 \uad70\uc911\uc744 \ub0b4\ub824\ub2e4\ubcf4\ub294 \ub192\uc740 \uc790\ub9ac\uc774\uba70, \ucad3\uae30\ub294 \uc0ac\ub78c\uc774 \ubab8\uc744 \uc758\ud0c1\ud558\ub294 \ud53c\ub09c\ucc98\uac00 \ub41c\ub2e4. \uac19\uc740 \ub3cc\ubcbd\uc774 \ub204\uad6c\uc5d0\uac8c\ub294 \uad8c\uc704\ub85c, \ub204\uad6c\uc5d0\uac8c\ub294 \ubcf4\ud638\ub9c9\uc73c\ub85c \ub290\uaef4\uc9c4\ub2e4. \uac74\ubb3c\uc744 \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud558\ub294\uc9c0\uac00 \uc778\ubb3c\uc758 \uc6b4\uba85\uc744 \ubc14\uafb8\ub294 \uc18c\uc124\uc774\ub2e4. \uce74\uc9c0\ubaa8\ub3c4\ub294 \ub178\ud2b8\ub974\ub2f4\uc758 \uc885\uc9c0\uae30\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \uadf8\uc758 \uc2e0\uccb4\uc801 \ud2b9\uc9d5\uc744 \uad6c\uacbd\uac70\ub9ac\ub85c \uc0bc\uace0 \uc870\ub871\ud55c\ub2e4. \ucda4\ucd94\ub294 \uc5d0\uc2a4\uba54\ub784\ub2e4\ub3c4 \uad70\uc911\uc758 \uc2dc\uc120\uc744 \ubc1b\uc9c0\ub9cc \uadf8 \uc2dc\uc120\uc740 \ub2e4\ub974\ub2e4. \uc544\ub984\ub2e4\uc6c0\uc5d0 \ub300\ud55c \ucc2c\ud0c4\uacfc \ub0af\uc120 \uc9d1\ub2e8\uc744 \ud5a5\ud55c \ud3b8\uacac\uc774 \ud568\uaed8 \ub530\ub77c\ubd99\ub294\ub2e4. \uc791\ud488\uc758 \ub85c\ub9c8\ub2c8 \uacf5\ub3d9\uccb4 \ubb18\uc0ac\uc5d0\ub294 \ub2f9\uc2dc\uc640 \uc791\uac00 \uc2dc\ub300\uc758 \uc2dc\uc120\ub3c4 \uc2a4\uba70 \uc788\ub2e4. \ub450 \uc0ac\ub78c\uc744 \ub458\ub7ec\uc2fc \uc2dc\uc120\uc740 \uc678\ubaa8\uac00 \uc0ac\ud68c\uc801 \ub300\uc6b0\uc640 \uc5bc\ub9c8\ub098 \uac15\ud558\uac8c \uc5f0\uacb0\ub418\ub294\uc9c0 \ub4dc\ub7ec\ub0b8\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ub3c5\uc790\uac00 \uad70\uc911\uacfc \ub611\uac19\uc774 \uc544\ub984\ub2e4\uc6c0\uacfc \ucd94\ud568\ub9cc\uc73c\ub85c \uc778\ubb3c\uc744 \ud310\ub2e8\ud558\uc9c0 \uc54a\ub294 \uc77c\uc774\ub2e4. \uc18c\uc124\uc774 \uc9c4\ud589\ub420\uc218\ub85d \ucc98\uc74c \ubcf4\uc774\ub358 \ubaa8\uc2b5\uacfc \uc2e4\uc81c \ud589\ub3d9\uc758 \ucc28\uc774\uac00 \ucee4\uc9c4\ub2e4. \uc131\uc9c1\uc790 \ud074\ub85c\ub4dc \ud504\ub864\ub85c\ub294 \uc5d0\uc2a4\uba54\ub784\ub2e4\uc5d0\uac8c \uac15\ud55c \uc695\ub9dd\uc744 \ud488\ub294\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uac10\uc815\uc740 \uc0c1\ub300\uc758 \ub73b\uc744 \uc874\uc911\ud558\uae30\ubcf4\ub2e4 \uc18c\uc720\ud558\ub824\ub294 \ubc29\ud5a5\uc73c\ub85c \ud750\ub978\ub2e4. \uc5d0\uc2a4\uba54\ub784\ub2e4\ub294 \uc7a5\uad50 \ud398\ubdd4\uc2a4\uc5d0\uac8c \ub9c8\uc74c\uc744 \uc8fc\uc9c0\ub9cc, \uadf8\uc758 \ub9e4\ub825\uc801\uc778 \uc678\uc591\uacfc \uadf8\ub140\ub97c \ud5a5\ud55c \ucc45\uc784\uac10\uc740 \uac19\uc740 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc774 \uad00\uacc4\ub97c \ubaa8\ub450 \uc0ac\ub791\uc774\ub77c\ub294 \ud55c \ub2e8\uc5b4\ub85c \ubb36\uc73c\uba74 \ube44\uadf9\uc758 \uc6d0\uc778\uc774 \ud750\ub824\uc9c4\ub2e4. \ub204\uad70\uac00\ub294 \uc0ac\ub791\ud55c\ub2e4\uace0 \uc8fc\uc7a5\ud558\uba74\uc11c \uc0c1\ub300\ub97c \uc704\ud611\ud558\uace0, \ub204\uad70\uac00\ub294 \uc0ac\ub791\ubc1b\uc73c\uba74\uc11c\ub3c4 \uadf8 \ub9c8\uc74c\uc758 \ubb34\uac8c\ub97c \uc678\uba74\ud55c\ub2e4. \uc704\uace0\ub294 \uac10\uc815\uc758 \uac15\ub3c4\ub9cc\uc73c\ub85c \uad00\uacc4\uac00 \uc120\ud574\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc744 \uc0ac\uac74\uc73c\ub85c \ubcf4\uc5ec \uc900\ub2e4. \ubc8c\uc744 \ubc1b\ub294 \uce74\uc9c0\ubaa8\ub3c4\uac00 \ubaa9\ub9c8\ub984\uc5d0 \uc2dc\ub2ec\ub9b4 \ub54c \uc5d0\uc2a4\uba54\ub784\ub2e4\uac00 \ubb3c\uc744 \uac74\ub128\ub2e4. \uc870\ub871\ud558\ub294 \uad70\uc911 \uc18d\uc5d0\uc11c \ub098\uc628 \uc791\uc740 \ub3cc\ubd04\uc774\ub2e4. \uce74\uc9c0\ubaa8\ub3c4\uc5d0\uac8c \uadf8\ub140\ub294 \uc678\ubaa8\ub97c \ubcf4\uace0 \uc6c3\uae30\ub9cc \ud55c \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uacfc \ub2ec\ub77c\uc9c4\ub2e4. \uc774 \uc7a5\uba74\uc740 \ud654\ub824\ud55c \uace0\ubc31\ubcf4\ub2e4 \ub354 \uae4a\uac8c \ub450 \uc778\ubb3c\uc758 \uad00\uacc4\ub97c \ubc14\uafbc\ub2e4. \uadf8\uac00 \ub4a4\uc5d0 \uc5d0\uc2a4\uba54\ub784\ub2e4\ub97c \ub3d5\ub294 \ud589\ub3d9\uc740 \uadf8 \uae30\uc5b5\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uadf8\ub140\uac00 \uadf8\uc758 \ub9c8\uc74c\uc5d0 \ubc18\ub4dc\uc2dc \uac19\uc740 \uac10\uc815\uc73c\ub85c \uc751\ub2f5\ud574\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub3c4\uc6c0\uc744 \ubc1b\uc558\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc0ac\ub791\uc758 \uc758\ubb34\ub97c \ub9cc\ub4e4\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc18c\uc124\uc758 \uad00\uacc4\ub97c \uc77d\uc744 \ub54c \uc774 \ucc28\uc774\ub97c \ub193\uce58\uc9c0 \uc54a\uc544\uc57c \ube44\uadf9\uc744 \ub354 \uc815\ud655\ud788 \ubcfc \uc218 \uc788\ub2e4. \ud504\ub864\ub85c\uac00 \ud398\ubdd4\uc2a4\ub97c \ucc0c\ub978 \uc0ac\uac74 \ub4a4 \uc5d0\uc2a4\uba54\ub784\ub2e4\ub294 \ubd80\ub2f9\ud55c \ud610\uc758\uc640 \uc7ac\ud310\uc5d0 \ud718\ub9d0\ub9b0\ub2e4. \uce74\uc9c0\ubaa8\ub3c4\ub294 \ucc98\ud615\ub420 \uc704\uae30\uc5d0 \ub193\uc778 \uadf8\ub140\ub97c \uad6c\ud574 \uc131\ub2f9\uc73c\ub85c \ub370\ub824\uac04\ub2e4. \ub192\uc740 \ub3cc\ubcbd \uc548\ucabd\uc740 \uc7a0\uc2dc \ubcf4\ud638\uc758 \uacf5\uac04\uc774 \ub418\uc9c0\ub9cc, \ubc14\uae65\uc758 \uad8c\ub825\uacfc \uc624\ud574\uac00 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud53c\ub09c\ucc98\ub97c \uc5bb\uc740 \uac83\uacfc \uc548\uc804\ud55c \uc0b6\uc744 \ud68c\ubcf5\ud55c \uac83\uc740 \ub2e4\ub974\ub2e4. \uc5d0\uc2a4\uba54\ub784\ub2e4\ub97c \ub458\ub7ec\uc2fc \uc0ac\ub78c\ub4e4\uc774 \uac01\uae30 \ub2e4\ub978 \ubaa9\uc801\uacfc \uc815\ubcf4\ub85c \uc6c0\uc9c1\uc774\uba74\uc11c \uc704\ud5d8\uc774 \ucee4\uc9c4\ub2e4. \ub3c5\uc790\ub294 \ub204\uac00 \ub204\uad6c\ub97c \uad6c\ud558\ub824 \ud558\ub294\uc9c0 \uc54c\uc9c0\ub9cc \uc778\ubb3c\ub4e4\uc740 \uc11c\ub85c\ub97c \ucda9\ubd84\ud788 \uc774\ud574\ud558\uc9c0 \ubabb\ud55c\ub2e4. \uc774 \uc815\ubcf4\uc758 \uc5b4\uae0b\ub0a8\uc774 \ud6c4\ubc18\ubd80\uc758 \uae34\uc7a5\uc744 \ub9cc\ub4e0\ub2e4. \uc5d0\uc2a4\uba54\ub784\ub2e4\uc640 \uad00\ub828\ub41c \uc0ac\ub78c\ub4e4\uc774 \uc131\ub2f9\uc73c\ub85c \ubab0\ub824\uc624\uc790 \uce74\uc9c0\ubaa8\ub3c4\ub294 \uadf8\ub4e4\uc758 \uc758\ub3c4\ub97c \uc624\ud574\ud558\uace0 \ub9de\uc120\ub2e4. \ubc14\uae65\uc758 \uc18c\ub3d9\uacfc \ud1b5\uce58 \uad8c\ub825\uc758 \uac1c\uc785, \ud504\ub864\ub85c\uc758 \ud589\ub3d9\uc774 \uacb9\uce58\uba74\uc11c \uc131\ub2f9\uc758 \ubcf4\ud638\ub3c4 \ubb34\ub108\uc9c4\ub2e4. \ud55c \uc0ac\ub78c\uc774 \ub354 \uac15\ud558\uac8c \uc2f8\uc6b4\ub2e4\uace0 \ubaa8\ub4e0 \uad00\uacc4\uac00 \ubc14\ub85c\uc7a1\ud788\uc9c0 \uc54a\ub294 \uc0c1\ud669\uc774\ub2e4. \ub4a4\ub2a6\uac8c \ub4dc\ub7ec\ub098\ub294 \ubaa8\ub140\uc758 \uad00\uacc4 \uc5ed\uc2dc \ube44\uadf9\uc744 \ub3cc\uc774\ud0ac \ub9cc\ud07c \ube60\ub974\uc9c0 \uc54a\ub2e4. \uac1c\uc778\uc758 \uc9c4\uc2ec\uc774 \uc874\uc7ac\ud574\ub3c4 \uc81c\ub3c4\uc640 \ud3ed\ub825, \uc624\ud574\uac00 \uadf8 \uc9c4\uc2ec\uc744 \uc555\ub3c4\ud560 \uc218 \uc788\ub2e4. \uc704\uace0\uac00 \uc5ec\ub7ec \uc778\ubb3c\uc744 \uae34 \uc11c\uc0ac \uc18d\uc5d0 \ud568\uaed8 \ubc30\uce58\ud55c \uc774\uc720\uac00 \uc5ec\uae30 \uc788\ub2e4. \ubd88\ud589\uc744 \ud55c \uc0ac\ub78c\uc758 \uc798\ubabb\uc73c\ub85c\ub9cc \uac04\ub2e8\ud788 \uc904\uc774\uae30 \uc5b4\ub835\ub2e4. \uc5d0\uc2a4\uba54\ub784\ub2e4\ub294 \uacb0\uad6d \ucc98\ud615\ub41c\ub2e4. \uc774\ub97c \uc9c0\ucf1c\ubcf4\ub294 \ud504\ub864\ub85c\uc758 \ubaa8\uc2b5\uc5d0 \uaca9\ubd84\ud55c \uce74\uc9c0\ubaa8\ub3c4\ub294 \uadf8\ub97c \uc131\ub2f9 \uc544\ub798\ub85c \ub5a8\uc5b4\ub728\ub9b0\ub2e4. \uc18c\uc124\uc758 \ub05d\uc5d0\ub294 \ud6d7\ub0a0 \ubc1c\uacac\ub41c \ub450 \uc0ac\ub78c\uc758 \uc720\uace8\uc774 \ub098\uc628\ub2e4. \ud568\uaed8 \ud589\ubcf5\ud558\uac8c \uc0ac\ub294 \uacb0\ub9d0 \ub300\uc2e0 \uc8fd\uc74c \uc18d\uc5d0\uc11c\uc57c \uac00\uae4c\uc774 \ub193\uc778 \ubaa8\uc2b5\uc774 \ub0a8\ub294\ub2e4. \uc131\ub2f9\uc740 \uc624\ub79c \uc2dc\uac04 \uac19\uc740 \uc790\ub9ac\uc5d0 \uc788\uc9c0\ub9cc \uadf8 \uc548\ud30e\uc758 \uc0ac\ub78c\uc740 \uc11c\ub85c \ub2e4\ub978 \ub73b\uc73c\ub85c \uc6c0\uc9c1\uc778\ub2e4. \uc81c\ubaa9\uc774 \ud55c \uc778\ubb3c\uc758 \uc774\ub984 \ub300\uc2e0 \uc7a5\uc18c\ub97c \ub0b4\uc138\uc6b4 \uc810\ub3c4 \uadf8\ub798\uc11c \uc758\ubbf8\uac00 \uc788\ub2e4. \uc5ec\ub7ec \uc778\ubb3c\uc758 \ube44\uadf9\uc744 \ud568\uaed8 \ub2f4\uc544\ub0bc \uc218 \uc788\ub294 \uc911\uc2ec\uc774 \ubc14\ub85c \uadf8 \uac74\ubb3c\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \uadf8\ub798\uc11c \uc774 \uc791\ud488\uc744 \uc544\ub984\ub2e4\uc6b4 \uc5ec\uc778\uacfc \uc885\uc9c0\uae30\uc758 \ub85c\ub9e8\uc2a4\ub85c\ub9cc \uc18c\uac1c\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \uc0ac\ub791\uc758 \uc5ec\ub7ec \uc5bc\uad74\uacfc \ud3b8\uacac, \ubcf4\ud638\ud560 \ud798\uc774 \ubd80\uc871\ud588\ub358 \uc0ac\ub78c\ub4e4\uc758 \uc774\uc57c\uae30\uac00 \uc131\ub2f9\uc5d0 \uacb9\uccd0 \uc788\ub2e4. \ub178\ud2b8\ub974\ub2f4\uc740 \ube44\uadf9\uc744 \uad6c\uacbd\ud558\ub294 \ubc30\uacbd\uc774 \uc544\ub2c8\ub77c \uc778\uac04\uc758 \uc5f0\ubbfc\uacfc \ud3ed\ub825\uc774 \ud568\uaed8 \uc9c0\ub098\uac04 \uae30\uc5b5\uc758 \uc7a5\uc18c\ub85c \ub0a8\ub294\ub2e4."}, {"id": "odysseus-cyclops-nobody-real-name", "title": "\uc624\ub514\uc138\uc6b0\uc2a4 \u2014 \uc544\ubb34\ub3c4 \uc544\ub2cc \uc0ac\ub78c\uc774 \uc774\ub984\uc744 \uc678\uce5c \uc21c\uac04", "summary": "\u300e\uc624\ub514\uc138\uc774\uc544\u300f \uc81c9\uad8c\uc758 \ud0a4\ud074\ub86d\uc2a4 \ubaa8\ud5d8\uc5d0\uc11c \uc774\ub984\uc744 \uac10\ucd94\ub294 \uc9c0\ud61c\uc640 \uc774\ub984\uc744 \ubc1d\ud788\ub294 \uc704\ud5d8\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc2e0\ud654\uc640 \ubbfc\uc18d", "categories": ["arts"], "url": "stories/odysseus-cyclops-nobody-real-name/index.html", "image": "../media/odysseus-cyclops-nobody-real-name.png", "alt": "\uc591\uc758 \ubab8 \uc544\ub798\uc5d0 \uc228\uc740 \uc0ac\ub78c\ub4e4\uc774 \uac70\uc778\uc758 \ub3d9\uad74 \uc785\uad6c\ub97c \ube60\uc838\ub098\uc624\ub294 \uc2e0\ud654 \uc7a5\uba74 \uc0bd\ud654", "text": "\uc624\ub514\uc138\uc6b0\uc2a4 \u2014 \uc544\ubb34\ub3c4 \uc544\ub2cc \uc0ac\ub78c\uc774 \uc774\ub984\uc744 \uc678\uce5c \uc21c\uac04 \uac70\uc778\uc758 \ub3d9\uad74\uc5d0\uc11c \ubc97\uc5b4\ub09c \uaf80\uac00 \uc790\ubd80\uc2ec \uc55e\uc5d0\uc11c \ud754\ub4e4\ub9ac\ub2e4 \u300e\uc624\ub514\uc138\uc774\uc544\u300f \uc81c9\uad8c\uc758 \ud0a4\ud074\ub86d\uc2a4 \ubaa8\ud5d8\uc5d0\uc11c \uc774\ub984\uc744 \uac10\ucd94\ub294 \uc9c0\ud61c\uc640 \uc774\ub984\uc744 \ubc1d\ud788\ub294 \uc704\ud5d8\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc2e0\ud654\uc640 \ubbfc\uc18d \ubb38\ud654\uc640 \uc608\uc220 \uc774\ub984\uc774 \ubb34\uc5c7\uc774\ub0d0\ub294 \ubb3c\uc74c\uc5d0 \uadf8\ub294 \uc544\ubb34\ub3c4 \uc544\ub2c8\ub77c\uace0 \ub300\ub2f5\ud55c\ub2e4. \ub098\uc911\uc5d0 \uac70\uc778\uc774 \ub3c4\uc6c0\uc744 \uccad\ud560 \ub54c \uc774 \uac70\uc9d3\ub9d0\uc740 \ub73b\ubc16\uc758 \ud798\uc744 \ubc1c\ud718\ud55c\ub2e4. \uc544\ubb34\ub3c4 \uc790\uc2e0\uc744 \ud574\uce58\uc9c0 \uc54a\ub294\ub2e4\uace0 \uc678\uce58\ub294 \uc18c\ub9ac\ub97c \ub4e3\uace0, \ub2e4\ub978 \uac70\uc778\ub4e4\uc740 \ub204\uad6c\uc640 \uc2f8\uc6cc\uc57c \ud558\ub294\uc9c0 \uc54c\uc9c0 \ubabb\ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \u300e\uc624\ub514\uc138\uc774\uc544\u300f\uc758 \uc624\ub514\uc138\uc6b0\uc2a4\ub294 \ud798\ub9cc\uc73c\ub85c \uc2f8\uc6b0\ub294 \uc601\uc6c5\uc774 \uc544\ub2c8\ub2e4. \uc0c1\ud669\uc744 \uc0b4\ud53c\uace0 \ub9d0\uc744 \ubc14\uafb8\uba70 \ube60\uc838\ub098\uac08 \uae38\uc744 \ucc3e\ub294\ub2e4. \ud558\uc9c0\ub9cc \ud0a4\ud074\ub86d\uc2a4\uc758 \ub3d9\uad74\uc5d0\uc11c \uc774\uc5b4\uc9c0\ub294 \uc774\uc57c\uae30\ub294 \uadf8\uc758 \uaf80\ub97c \uce6d\ucc2c\ud558\ub294 \ub370\uc11c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc81c9\uad8c\uc5d0 \ub2f4\uae34 \ubaa8\ud5d8\uacfc \uadf8 \ub4a4\uc758 \uc800\uc8fc\uae4c\uc9c0 \uc18c\uac1c\ud55c\ub2e4. \ud2b8\ub85c\uc774 \uc804\uc7c1 \ub4a4 \uc624\ub514\uc138\uc6b0\uc2a4\ub294 \ub3d9\ub8cc\ub4e4\uacfc \uace0\ud5a5\uc73c\ub85c \ub3cc\uc544\uac00\ub294 \uc911\uc774\ub2e4. \ub0af\uc120 \uc12c\uacfc \ud574\uc548\uc744 \uac70\uce58\ub2e4 \uc678\ub208\ubc15\uc774 \uac70\uc778 \ud0a4\ud074\ub86d\uc2a4\ub4e4\uc774 \uc0ac\ub294 \uacf3\uc5d0 \uc774\ub978\ub2e4. \uadf8 \uac00\uc6b4\ub370 \ud3f4\ub9ac\ud398\ubaa8\uc2a4\uc758 \ub3d9\uad74\uc5d0\ub294 \uac00\ucd95\uacfc \uce58\uc988 \uac19\uc740 \uba39\uc744 \uac83\uc774 \uc788\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \uc8fc\uc778\uc774 \uc5c6\ub294 \uacf5\uac04\uc5d0\uc11c \ubb34\uc5c7\uc744 \ud560\uc9c0 \ud310\ub2e8\ud574\uc57c \ud55c\ub2e4. \ub3d9\ub8cc\ub4e4\uc740 \ubb3c\uac74\uc744 \ucc59\uaca8 \ub5a0\ub098\uc790\uace0 \ud558\uc9c0\ub9cc \uc624\ub514\uc138\uc6b0\uc2a4\ub294 \uc8fc\uc778\uc744 \ub9cc\ub098\uae30\ub97c \uc6d0\ud55c\ub2e4. \uc5b4\ub5a4 \ub300\uc811\uc744 \ubc1b\uc744 \uc218 \uc788\uc744\uc9c0 \uc54c\uace0 \uc2f6\uc5b4 \ud55c\ub2e4. \ub4a4\uc758 \uc704\ud5d8\uc740 \uc6b0\uc5f0\ud788 \uae38\uc744 \uc783\uc5b4\uc11c\ub9cc \uc0dd\uae30\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \ub0af\uc120 \uc774\ub97c \ub9cc\ub098\ub824\ub294 \ud638\uae30\uc2ec\uacfc \uc190\ub2d8\uc5d0 \ub300\ud55c \uae30\ub300\ub3c4 \uadf8\ub4e4\uc744 \ub3d9\uad74 \uc548\uc5d0 \uba38\ubb3c\uac8c \ud55c\ub2e4. \ud3f4\ub9ac\ud398\ubaa8\uc2a4\uac00 \ub3cc\uc544\uc640 \ud070 \ubc14\uc704\ub85c \uc785\uad6c\ub97c \ub9c9\ub294\ub2e4. \uc624\ub514\uc138\uc6b0\uc2a4\ub294 \uc190\ub2d8\uc744 \ub300\ud558\ub294 \uc758\ubb34\uc640 \uc2e0\ub4e4\uc744 \uc774\uc57c\uae30\ud558\uc9c0\ub9cc \uac70\uc778\uc740 \uadf8 \ub9d0\uc744 \ub530\ub974\uc9c0 \uc54a\ub294\ub2e4. \uc0ac\ub78c\ub4e4\uc744 \ubd99\uc7a1\uc544 \uba39\uae30 \uc2dc\uc791\ud55c\ub2e4. \uc11c\uc0ac\uc2dc\ub294 \ub450\ub824\uc6b4 \uc0c1\ud669\uc744 \ubd84\uba85\ud558\uac8c \ubcf4\uc5ec \uc8fc\uc9c0\ub9cc, \uc5ec\uae30\uc11c\ub294 \uc794\ud639\ud55c \ub3d9\uc791\uc744 \uc790\uc138\ud788 \ub298\uc5b4\ub193\uc9c0 \uc54a\uace0 \ud0c8\ucd9c\uc758 \uc120\ud0dd\uc744 \ub530\ub77c\uac00 \ubcf4\uc790. \uac70\uc778\uc744 \uc8fd\uc77c \uc218 \uc788\ub354\ub77c\ub3c4 \ubb38\uc81c\uac00 \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc785\uad6c\ub97c \ub9c9\uc740 \ubc14\uc704\uac00 \ub108\ubb34 \ucee4\uc11c \uc0ac\ub78c\ub4e4\uc774 \uc62e\uae38 \uc218 \uc5c6\uae30 \ub54c\ubb38\uc774\ub2e4. \uc0c1\ub300\ub97c \uc4f0\ub7ec\ub728\ub9ac\ub294 \uc77c\uacfc \uc790\uc2e0\uc774 \uc0b4\uc544 \ub098\uc624\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uc624\ub514\uc138\uc6b0\uc2a4\ub294 \ubc14\ub85c \uadf8 \ucc28\uc774\ub97c \uacc4\uc0b0\ud574\uc57c \ud55c\ub2e4. \ud798\uc73c\ub85c \uc774\uae38 \uc218 \uc5c6\ub294 \uc774\uc720\uac00 \uacf5\uac04\uc758 \uad6c\uc870\uc5d0 \ub193\uc5ec \uc788\ub2e4. \uc624\ub514\uc138\uc6b0\uc2a4\ub294 \uac00\uc9c0\uace0 \uc628 \uac15\ud55c \ud3ec\ub3c4\uc8fc\ub97c \uac74\ub128\ub2e4. \uc220\uc5d0 \ucde8\ud55c \ud3f4\ub9ac\ud398\ubaa8\uc2a4\uac00 \uc774\ub984\uc744 \ubb3b\uc790 \uc790\uc2e0\uc740 \uc544\ubb34\ub3c4 \uc544\ub2c8\ub77c\ub294 \ub73b\uc758 \uc774\ub984\uc744 \ub304\ub2e4. \uc774 \uae00\uc774 \ucc38\uace0\ud55c \ud3ec\ud504 \uacc4\uc5f4\uc758 \uc601\uc5b4 \uc6b4\ubb38 \ubc88\uc5ed\uc740 \uc774\ub97c Noman\uc774\ub77c\uace0 \uc62e\uae34\ub2e4. \ubc88\uc5ed\uc758 \ub9d0\uc7a5\ub09c\uc744 \uc9c0\ub098 \uadf8\ub9ac\uc2a4 \uc11c\uc0ac\uc758 \uc774\ub984 \uc228\uae30\uae30\ub77c\ub294 \uc7a5\uce58\ub97c \uc77d\uc744 \uc218 \uc788\ub2e4. \uc774 \uc120\ud0dd\uc740 \uc21c\uac04\uc801\uc778 \ub18d\ub2f4\uc774 \uc544\ub2c8\ub77c \ub4a4\uc758 \uc704\uae30\ub97c \uc704\ud55c \uc900\ube44\uac00 \ub41c\ub2e4. \uac70\uc778\uc758 \ud798\uc740 \ub208\uc55e\uc5d0 \uc788\uc9c0\ub9cc, \ub2e4\ub978 \uac70\uc778\ub4e4\uc5d0\uac8c \ub3c4\uc6c0\uc744 \uccad\ud560 \ub54c\uc5d0\ub294 \ub9d0\uc774 \ud544\uc694\ud558\ub2e4. \uc624\ub514\uc138\uc6b0\uc2a4\ub294 \ubc14\ub85c \uadf8 \ub9d0\uc758 \ud1b5\ub85c\ub97c \ubbf8\ub9ac \ubc14\uafd4 \ub193\ub294\ub2e4. \ub3d9\uad74\uc744 \ube60\uc838\ub098\uac00\ub294 \uae38\uc774 \ubc14\uc704\uc5d0\uc11c\ub9cc \uc5f4\ub9ac\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac70\uc778\uc774 \uc7a0\ub4e4\uc790 \uc624\ub514\uc138\uc6b0\uc2a4\uc640 \ub3d9\ub8cc\ub4e4\uc740 \uc900\ube44\ud55c \ub098\ubb34\ub85c \uadf8\uc758 \ub208\uc744 \uba40\uac8c \ud55c\ub2e4. \ud3f4\ub9ac\ud398\ubaa8\uc2a4\uc758 \ube44\uba85\uc774 \uc6b8\ub9ac\uace0 \ub2e4\ub978 \uac70\uc778\ub4e4\uc774 \ucc3e\uc544\uc628\ub2e4. \uadf8\ub7ec\ub098 \uadf8\ub294 \uc544\ubb34\ub3c4 \uc790\uc2e0\uc744 \ud574\uce5c\ub2e4\uace0 \ub9d0\ud55c\ub2e4. \ub3c4\uc6c0\uc744 \uc904 \uc774\ub4e4\uc740 \ub9d0\uc758 \ub73b\uc744 \ub2e4\ub974\uac8c \ubc1b\uc544\ub4e4\uc774\uace0 \ub3cc\uc544\uac04\ub2e4. \uc228\uaca8 \ub454 \uc774\ub984\uc774 \uc5ec\uae30\uc5d0\uc11c \uc791\ub3d9\ud55c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc785\uad6c\uac00 \uc790\uc720\ub85c\uc6cc\uc9c4 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud3f4\ub9ac\ud398\ubaa8\uc2a4\ub294 \uac00\ucd95\ub4e4\uc774 \ub098\uac08 \ub54c \uadf8 \ub4f1\uc744 \ub9cc\uc838 \uc0ac\ub78c\uc774 \uc62c\ub77c\ud0c0\uc9c0 \uc54a\uc558\ub294\uc9c0 \ud655\uc778\ud55c\ub2e4. \ub208\uc744 \ud53c\ud588\ub2e4\uace0 \uc190\uae4c\uc9c0 \ud53c\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ud0c8\ucd9c\uc758 \ubb38\uc81c\ub294 \uc0c8 \uc870\uac74\uc73c\ub85c \uc774\uc5b4\uc9c0\uace0, \uaf80\ub3c4 \ud55c \ubc88\uc774 \uc544\ub2c8\ub77c \uc5ec\ub7ec \ubc88 \ud544\uc694\ud574\uc9c4\ub2e4. \uc624\ub514\uc138\uc6b0\uc2a4\ub294 \uc0ac\ub78c\ub4e4\uc744 \uc591\uc758 \ubab8 \uc544\ub798\uc5d0 \uc228\uae30\uace0 \uc790\uc2e0\ub3c4 \ud070 \uc22b\uc591 \uc544\ub798\uc5d0 \ub9e4\ub2ec\ub9b0\ub2e4. \uac70\uc778\uc774 \ub4f1\uc744 \ub354\ub4ec\ub294 \ub3d9\uc548 \uc0ac\ub78c\ub4e4\uc740 \ub2e4\ub978 \ucabd\uc73c\ub85c \ube60\uc838\ub098\uac04\ub2e4. \uc0c1\ub300\uac00 \uc5b4\ub514\ub97c \ud655\uc778\ud558\ub294\uc9c0 \uc54c\uc544\ub0b4\uace0 \uadf8 \uc608\uc0c1 \ubc16\uc758 \uc790\ub9ac\ub97c \uc774\uc6a9\ud558\ub294 \ubc29\ubc95\uc774\ub2e4. \uac00\ucd95\uc758 \uc77c\uc0c1\uc801\uc778 \uc774\ub3d9\uc774 \ub3c4\ub9dd\uc758 \ud589\ub82c\uc774 \ub41c\ub2e4. \ud3f4\ub9ac\ud398\ubaa8\uc2a4\uac00 \ub9c8\uc9c0\ub9c9 \uc22b\uc591\uc5d0\uac8c \ub9d0\uc744 \uac70\ub294 \ub300\ubaa9\uc740 \uc7a5\uba74\uc744 \ub354 \uae34\uc7a5\ub418\uac8c \ud55c\ub2e4. \ub3c5\uc790\ub294 \uadf8 \uc544\ub798 \ub204\uac00 \uc228\uc5b4 \uc788\ub294\uc9c0 \uc54c\uace0 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uac70\uc778\uc758 \ub9d0\uc774 \uae38\uc5b4\uc9c8\uc218\ub85d \uc544\uc9c1 \ub4e4\ud0a4\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc548\ub3c4\uc640 \uace7 \ub4e4\ud0ac\uc9c0 \ubaa8\ub978\ub2e4\ub294 \ubd88\uc548\uc774 \ud568\uaed8 \ub298\uc5b4\ub09c\ub2e4. \uc11c\uc0ac\ub294 \uac70\ub300\ud55c \uc804\ud22c\ubcf4\ub2e4 \ub290\ub9b0 \ud1b5\uacfc \ud55c \ubc88\uc73c\ub85c \uc190\uc5d0 \ub540\uc744 \uc950\uac8c \ud55c\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \ubc30\ub85c \ub3cc\uc544\uac00 \uba40\uc5b4\uc9c4\ub2e4. \uc5ec\uae30\uc11c \uc870\uc6a9\ud788 \ub5a0\ub0ac\ub2e4\uba74 \uc774\uc57c\uae30\ub294 \uae30\ub9c9\ud78c \ud0c8\ucd9c\ub2f4\uc73c\ub85c \ub05d\ub0a0 \uc218 \uc788\uc5c8\ub2e4. \ud558\uc9c0\ub9cc \uc624\ub514\uc138\uc6b0\uc2a4\ub294 \uac70\uc778\uc744 \uc870\ub871\ud55c\ub2e4. \ud3f4\ub9ac\ud398\ubaa8\uc2a4\uac00 \uc18c\ub9ac\uc758 \ubc29\ud5a5\uc73c\ub85c \ubc14\uc704\ub97c \ub358\uc9c0\uc790 \ubc30\ub294 \ub2e4\uc2dc \uc704\ud5d8\ud574\uc9c0\uace0, \ub3d9\ub8cc\ub4e4\uc740 \ub354 \uc790\uadf9\ud558\uc9c0 \ub9d0\ub77c\uace0 \uccad\ud55c\ub2e4. \uadf8\ub7f0\ub370 \uc624\ub514\uc138\uc6b0\uc2a4\ub294 \uc790\uae30 \uc774\ub984\uacfc \uace0\ud5a5, \uc544\ubc84\uc9c0\uc758 \uc774\ub984\uae4c\uc9c0 \ubc1d\ud78c\ub2e4. \uc544\ubb34\ub3c4 \uc544\ub2cc \uc0ac\ub78c\uc73c\ub85c \uc0b4\uc544 \ub098\uc628 \uc601\uc6c5\uc774 \ub204\uac00 \uc774\uacbc\ub294\uc9c0 \uc54c\uc544\uc8fc\uae30\ub97c \ubc14\ub77c\ub294 \uac83\uc774\ub2e4. \uc55e\uc5d0\uc11c\ub294 \uc774\ub984\uc744 \uac10\ucd98 \ub9d0\uc774 \uc0ac\ub78c\ub4e4\uc744 \uc0b4\ub838\uace0, \uc774\uc81c\ub294 \uc774\ub984\uc744 \ub4dc\ub7ec\ub0b8 \ub9d0\uc774 \uc704\ud5d8\uc744 \ubd88\ub7ec\uc628\ub2e4. \uac19\uc740 \ub2a5\ub825\uc774 \ub2e4\ub978 \uc695\ub9dd\uacfc \ub9cc\ub098\ub294 \uc21c\uac04\uc774\ub2e4. \ud3f4\ub9ac\ud398\ubaa8\uc2a4\ub294 \ubc14\ub2e4\uc758 \uc2e0 \ud3ec\uc138\uc774\ub3c8\uc5d0\uac8c \uae30\ub3c4\ud55c\ub2e4. \uc790\uc2e0\uc744 \ud574\uce5c \uc0ac\ub78c\uc774 \ub204\uad6c\uc778\uc9c0 \uc54c\uac8c \ub418\uc5c8\uc73c\ubbc0\ub85c \uc800\uc8fc\uc758 \ub300\uc0c1\uc744 \ubd84\uba85\ud788 \ubd80\ub97c \uc218 \uc788\ub2e4. \uc624\ub514\uc138\uc6b0\uc2a4\uac00 \uace0\ud5a5\uc5d0 \ub3cc\uc544\uac00\uc9c0 \ubabb\ud558\uac70\ub098, \ub3cc\uc544\uac00\ub354\ub77c\ub3c4 \uc624\ub798 \uace0\uc0dd\ud558\uace0 \ub3d9\ub8cc\ub4e4\uc744 \uc783\uc740 \ub4a4 \ub2e4\ub978 \ubc30\ub85c \uac00\uae30\ub97c \ube48\ub2e4. \ud0c8\ucd9c\uc758 \uc2b9\ub9ac\uac00 \uae34 \uadc0\ud5a5\uc758 \ubd88\uc548\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc774\uac83\uc744 \uc2e4\uc81c \ubc14\ub2e4 \uc0ac\uace0\uc758 \uacfc\ud559\uc801 \uc6d0\uc778\ucc98\ub7fc \ubc1b\uc544\ub4e4\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uc11c\uc0ac\uc2dc\ub294 \uc778\uac04\uc758 \uc790\ubd80\uc2ec\uacfc \uc2e0\ub4e4\uc758 \ud798\uc744 \ud55c \uc904\uac70\ub9ac \uc548\uc5d0 \ub193\ub294\ub2e4. \ub3c5\uc790\ub294 \uc774\ubbf8 \uc704\ud5d8\uc744 \ubc97\uc5b4\ub09c \ub4a4 \ubb34\uc5c7\uc744 \ub354 \uc5bb\uc73c\ub824 \ud588\ub294\uc9c0 \ub3cc\uc544\ubcf4\uac8c \ub41c\ub2e4. \uc0b4\uc544\ub0a8\ub294 \uac83\uacfc \uc2b9\ub9ac\ub97c \uc778\uc815\ubc1b\ub294 \uac83\uc740 \uc624\ub514\uc138\uc6b0\uc2a4\uc5d0\uac8c \uc11c\ub85c \ub2e4\ub978 \ub9cc\uc871\uc774\uc5c8\ub2e4. \uc774 \ubaa8\ud5d8\uc740 \uadc0\ud5a5\uc758 \uc5ec\uc815\uc744 \uc624\ub514\uc138\uc6b0\uc2a4\uac00 \ub2e4\ub978 \uc774\ub4e4\uc5d0\uac8c \ub4e4\ub824\uc8fc\ub294 \uc774\uc57c\uae30 \uc548\uc5d0 \ub4e4\uc5b4 \uc788\ub2e4. \uadf8\ub294 \uc790\uae30 \uaf80\ubfd0 \uc544\ub2c8\ub77c \uc790\uc2e0\uc774 \uc790\ub791\ud558\ub2e4 \uc704\uae30\ub97c \ud0a4\uc6b4 \uc21c\uac04\ub3c4 \ub9d0\ud55c\ub2e4. \ub3c5\uc790\ub294 \uc601\uc6c5\uc744 \ucc2c\ud0c4\ud558\uba74\uc11c \ub3d9\uc2dc\uc5d0 \uadf8\uc758 \ud310\ub2e8\uc744 \ub530\uc838 \ubcfc \uc218 \uc788\ub2e4. \ud55c \uc0ac\ub78c\uc774 \uc6a9\uac10\ud558\uace0 \uc601\ub9ac\ud558\ub2e4\uace0 \ubaa8\ub4e0 \uc21c\uac04\uc5d0 \ud604\uba85\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774\ub984\uc744 \uac10\ucd94\ub77c\ub294 \uc0dd\ud65c\uc758 \uad50\ud6c8\uc774 \uc774 \uc774\uc57c\uae30\uc758 \uc815\ub2f5\uc740 \uc544\ub2c8\ub2e4. \uc624\ud788\ub824 \uc5b4\ub5a4 \uc21c\uac04\uc5d0\ub294 \uc778\uc815\ubc1b\uace0 \uc2f6\uc740 \ub9c8\uc74c\uc774 \uc55e\uc11c \uc138\uc6b4 \uc88b\uc740 \ud310\ub2e8\uc744 \ud754\ub4e4 \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \uc624\ub798 \ub0a8\ub294\ub2e4. \ub3d9\uad74\uc744 \ube60\uc838\ub098\uc628 \uc601\uc6c5\uc5d0\uac8c \uac00\uc7a5 \uc5b4\ub824\uc6e0\ub358 \uc77c\uc740 \uac70\uc778\uc744 \uc774\uae30\ub294 \uac83 \ub2e4\uc74c\uc5d0 \uc788\uc5c8\ub2e4. \uc544\ubb34 \ub9d0 \uc5c6\uc774 \uc870\uae08 \ub354 \uba40\ub9ac \ub5a0\ub098\ub294 \uc77c\uc774\uc5c8\ub2e4."}, {"id": "okakura-book-tea-room-and-attention", "title": "\u300e\ucc28\uc758 \ucc45\u300f \u2014 \ucc3b\uc794 \ud558\ub098\ub97c \uc704\ud574 \ubc29\uc744 \ube44\uc6b4\ub2e4\ub294 \uac83", "summary": "\uc791\uc740 \uc785\uad6c\uc640 \uaf43 \ud55c \uc1a1\uc774, \ube44\uc5b4 \uc788\ub294 \uc790\ub9ac\ub97c \ub530\ub77c \uc77c\ubcf8\uc758 \ucc28 \ubb38\ud654\uc5d0 \uad00\ud55c \ud55c \uc791\uac00\uc758 \uc2dc\uc120\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/okakura-book-tea-room-and-attention/index.html", "image": "../media/okakura-book-tea-room-and-attention.png", "alt": "\uc791\uc740 \ucc3b\uc794\uacfc \uc8fc\uc804\uc790, \uaf43 \ud55c \uc1a1\uc774\uc640 \ube48 \uacf5\uac04\uc774 \ub193\uc778 \uc77c\ubcf8 \ucc3b\ubc29\uc758 \ubd84\uc704\uae30 \uc0bd\ud654", "text": "\u300e\ucc28\uc758 \ucc45\u300f \u2014 \ucc3b\uc794 \ud558\ub098\ub97c \uc704\ud574 \ubc29\uc744 \ube44\uc6b4\ub2e4\ub294 \uac83 \uc624\uce74\ucfe0\ub77c \uac00\ucfe0\uc870\uac00 \ucc28\ub97c \ud1b5\ud574 \uc124\uba85\ud55c \uc608\uc220\uacfc \uc77c\uc0c1 \uc791\uc740 \uc785\uad6c\uc640 \uaf43 \ud55c \uc1a1\uc774, \ube44\uc5b4 \uc788\ub294 \uc790\ub9ac\ub97c \ub530\ub77c \uc77c\ubcf8\uc758 \ucc28 \ubb38\ud654\uc5d0 \uad00\ud55c \ud55c \uc791\uac00\uc758 \uc2dc\uc120\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \ubc29\uc744 \uc798 \uafb8\ubbfc\ub2e4\uace0 \ud558\uba74 \uc88b\uc740 \ubb3c\uac74\uc744 \ub354 \ub193\ub294 \uc7a5\uba74\ubd80\ud130 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub9bc\uc744 \uac78\uace0 \uaf43\ubcd1\uc744 \ub4e4\uc774\uace0 \uba4b\uc9c4 \uadf8\ub987\uc744 \ubaa8\uc740\ub2e4. \uadf8\ub7f0\ub370 \ucc28\ub97c \ub9c8\uc2dc\ub294 \uc791\uc740 \ubc29\uc5d0\uc11c\ub294 \ubb34\uc5c7\uc744 \ub354\ud560\uc9c0\ubcf4\ub2e4 \ubb34\uc5c7\uc744 \ub0a8\uaca8 \ub458\uc9c0\uac00 \uc911\uc694\ud574\uc9c0\uae30\ub3c4 \ud55c\ub2e4. \ubb3c\uac74\uc774 \uc801\uc5b4\uc9c0\uba74 \ucc3b\uc794 \ud558\ub098\uc5d0 \uba38\ubb34\ub294 \uc2dc\uac04\uc774 \uae38\uc5b4\uc9c4\ub2e4. \uc624\uce74\ucfe0\ub77c \uac00\ucfe0\uc870\uc758 \u300e\ucc28\uc758 \ucc45\u300f\uc740 \ucc28\uc758 \uc885\ub958\ub97c \uc124\uba85\ud558\ub294 \uc2e4\uc6a9 \uc548\ub0b4\uc11c\ub9cc\uc740 \uc544\ub2c8\ub2e4. \ucc28\ub97c \ub458\ub7ec\uc2fc \uacf5\uac04\uacfc \uaf43, \uc608\uc220\uc744 \ub300\ud558\ub294 \ud0dc\ub3c4\ub85c \uc77c\ubcf8\uc758 \ubb38\ud654\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc774\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubcf5\uc7a1\ud55c \uc608\ubc95\uc744 \uc678\uc6b0\uae30\ubcf4\ub2e4 \uadf8\uac00 \ucc3b\ubc29\uc5d0\uc11c \ubb34\uc5c7\uc744 \ubcf4\ub824 \ud588\ub294\uc9c0 \ub530\ub77c\uac00 \ubcf8\ub2e4. \uc624\uce74\ucfe0\ub77c\ub294 \uc774 \ucc45\uc744 \uc601\uc5b4\ub85c \uc37c\ub2e4. \ucc28\uc5d0 \uc775\uc219\ud558\uc9c0 \uc54a\uc740 \ub3c5\uc790\uc5d0\uac8c \ucc3b\uc794\uc744 \ub9e4\uac1c\ub85c \uc608\uc220\uacfc \uc0dd\ud65c\uc758 \uad00\uacc4\ub97c \uc124\uba85\ud558\ub824 \ud588\ub2e4. \uc774\ubbf8 \uc798 \uc544\ub294 \ub3c5\uc790\ub97c \ud5a5\ud55c \ub0b4\ubd80\uc758 \uaddc\uce59\uc9d1\uacfc, \ub0af\uc120 \ub3c5\uc790\uc5d0\uac8c \uc758\ubbf8\ub97c \uc804\ub2ec\ud558\ub824\ub294 \ucc45\uc740 \ub9d0\uc758 \ubc29\ud5a5\uc774 \ub2e4\ub974\ub2e4. \uadf8\ub798\uc11c \u300e\ucc28\uc758 \ucc45\u300f\uc740 \ub2f9\uc2dc \uc77c\ubcf8 \uc0ac\ud68c \uc804\uccb4\ub97c \uadf8\ub300\ub85c \uc62e\uae34 \uc911\ub9bd\uc801\uc778 \ubcf4\uace0\uc11c\ub85c \uc77d\uae30\ubcf4\ub2e4 \ud55c \uc791\uac00\uc758 \uc8fc\uc7a5\uacfc \uac10\uc0c1\uc774 \ub2f4\uae34 \ubb38\ud654 \uc5d0\uc138\uc774\ub85c \uc77d\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uadf8\uc758 \ud45c\ud604\uc5d0 \uace0\uac1c\ub97c \ub044\ub355\uc77c \uc218\ub3c4 \uc788\uace0 \uac70\ub9ac\ub97c \ub458 \uc218\ub3c4 \uc788\ub2e4. \ucc45\uc774 \uc81c\uc2dc\ud558\ub294 \uc774\uc0c1\uacfc \uc2e4\uc81c \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \uc0dd\ud65c\uc740 \uac19\uc9c0 \uc54a\ub2e4. \ucc45\uc758 \ucc3b\ubc29 \uc124\uba85\uc5d0\ub294 \ubab8\uc744 \ub0ae\ucd94\uc5b4 \ub4e4\uc5b4\uac00\ub294 \uc791\uc740 \uc785\uad6c\uac00 \ub098\uc628\ub2e4. \ub4e4\uc5b4\uac00\ub294 \uc0ac\ub78c\uc740 \ub9d0\ub85c \uacb8\uc190\uc744 \uc120\uc5b8\ud558\uae30 \uc804\uc5d0 \ubab8\uc758 \uc790\uc138\ub97c \ubc14\uafb8\uac8c \ub41c\ub2e4. \uc624\uce74\ucfe0\ub77c\ub294 \ub192\uc740 \uc0ac\ub78c\uacfc \ub0ae\uc740 \uc0ac\ub78c \ubaa8\ub450\uc5d0\uac8c \uadf8\ub7f0 \uc6c0\uc9c1\uc784\uc774 \uc694\uad6c\ub41c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uacf5\uac04\uc774 \ud589\ub3d9\uc744 \ubd80\ud0c1\ud558\ub294 \uc148\uc774\ub2e4. \uc774\ub294 \uc2e0\ubd84 \ucc28\ubcc4\uc774 \uc5ed\uc0ac\uc5d0\uc11c \uc2e4\uc81c\ub85c \uc0ac\ub77c\uc84c\ub2e4\ub294 \uc99d\uac70\ub294 \uc544\ub2c8\ub2e4. \ucc3b\ubc29 \uc548\uc5d0\uc11c \uc9c0\ud5a5\ud55c \ud0dc\ub3c4\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc124\uba85\uc774\ub2e4. \uc0ac\ud68c\uc758 \ubaa8\ub4e0 \ubd88\ud3c9\ub4f1\uc774 \uc791\uc740 \ubb38 \ud558\ub098\ub85c \ud574\uacb0\ub420 \uc218\ub294 \uc5c6\ub2e4. \uadf8 \ud55c\uacc4\ub97c \uae30\uc5b5\ud558\uba74\uc11c\ub3c4, \uc77c\uc0c1\uc758 \uc790\uc138\ub97c \ubc14\uafb8\uc5b4 \ub2e4\ub978 \uad00\uacc4\ub97c \uc0c1\uc0c1\ud55c \uc7a5\uce58\ub97c \ubcfc \uc218 \uc788\ub2e4. \uc624\uce74\ucfe0\ub77c\uc758 \uae00\uc5d0\uc11c\ub294 \ubb34\uc0ac\uac00 \ucc3b\ubc29\uc5d0 \ub4e4\uc5b4\uac08 \ub54c \uce7c\uc744 \ubc14\uae65\uc5d0 \ub454\ub2e4. \uadf8\ub294 \uc774 \ubc29\uc744 \ud3c9\ud654\uc758 \uacf5\uac04\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \uc804\uc0ac\uc758 \ubb34\uae30\ub97c \ub0b4\ub824\ub193\ub294 \uc7a5\uba74\uc740 \ub9d0\ub85c \uae38\uac8c \uc124\uba85\ud558\uc9c0 \uc54a\uc544\ub3c4, \uc9c0\uae08\uc740 \ub2e4\ub978 \uaddc\uce59\uc73c\ub85c \ub9cc\ub098\ub824 \ud55c\ub2e4\ub294 \uc778\uc0c1\uc744 \uc900\ub2e4. \uc774 \ub300\ubaa9\uc744 \ubaa8\ub4e0 \ucc3b\uc790\ub9ac\uc5d0\uc11c \ud55c \ubc88\ub3c4 \uc5b4\uae40\uc5c6\uc774 \uc9c0\ucf1c\uc9c4 \uc5ed\uc0ac\uc801 \uc7a5\uba74\uc73c\ub85c \ud655\ub300\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ucc45\uc774 \uc804\ud558\ub824\ub294 \uc758\ubbf8\ub97c \uc77d\uc73c\uba74 \ub41c\ub2e4. \uc0c1\ub300\uc5d0\uac8c \ud798\uc744 \ubcf4\uc774\uae30 \uc704\ud55c \ubb3c\uac74\uc744 \uc7a0\uc2dc \ub0b4\ub824\ub193\uace0, \ud55c \uc794\uc744 \uc55e\uc5d0 \ub454 \uc0ac\ub78c\uc73c\ub85c \uc549\ub294\ub2e4\ub294 \uc0c1\uc0c1\uc774\ub2e4. \ucc45\uc740 \ucc3b\ubc29\uc758 \uc7a5\uc2dd\uc744 \uace0\uc815\ub41c \uc804\uc2dc\uc2e4\ucc98\ub7fc \ub2e4\ub8e8\uc9c0 \uc54a\ub294\ub2e4. \uadf8\ub0a0 \ub193\ub294 \uadf8\ub9bc\uacfc \uaf43, \uadf8\ub987\uacfc \uacf5\uac04\uc758 \uad00\uacc4\ub97c \uc911\uc2dc\ud55c\ub2e4. \ubaa8\ub4e0 \uc88b\uc740 \ubb3c\uac74\uc744 \ud55c \ubc88\uc5d0 \uaebc\ub0b4 \ub193\ub294 \ub300\uc2e0 \uc11c\ub85c\uac00 \uc11c\ub85c\ub97c \uac00\ub9ac\uc9c0 \uc54a\uac8c \ud558\ub294 \uc120\ud0dd\uc5d0 \uac00\uae5d\ub2e4. \ud604\ub300\uc758 \uc791\uc740 \ubc29\uc5d0\uc11c\ub3c4 \ube44\uc2b7\ud55c \uacbd\ud5d8\uc744 \ud560 \uc218 \uc788\ub2e4. \ucc45\uc0c1 \uc704\uc5d0 \ubb3c\uac74\uc744 \uc794\ub729 \uc62c\ub824 \ub450\uc5c8\uc744 \ub54c\ub294 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub358 \ucef5\uc774 \uc8fc\ubcc0\uc744 \uc815\ub9ac\ud558\uc790 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc774\uac83\uc774 \uace7 \uc804\ud1b5 \ub2e4\ub3c4\uc758 \uc804\ubd80\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub0af\uc120 \ubbf8\uac10\uc744 \uc774\ud574\ud558\uae30 \uc704\ud55c \uc791\uace0 \uc775\uc219\ud55c \ucd9c\ubc1c\uc810\uc77c \ubfd0\uc774\ub2e4. \uc624\uce74\ucfe0\ub77c\ub294 \ucc3b\ubc29\uc758 \uc7a5\uc2dd\uc5d0\uc11c \ube44\ub300\uce6d\uacfc \uc5ec\ubc31\uc744 \uc774\uc57c\uae30\ud55c\ub2e4. \ubaa8\ub450 \ub611\uac19\uc774 \ub9de\ucd94\uc5b4 \ucc44\uc6b0\ub294 \uac83\uacfc \ub2e4\ub978 \uade0\ud615\uc774\ub2e4. \ubcf4\ub294 \uc0ac\ub78c\uc5d0\uac8c \ub0a8\uc544 \uc788\ub294 \ube48 \uacf3\uc774 \ubc29\uc758 \ubd80\uc871\ud568\uc774 \uc544\ub2c8\ub77c, \uad00\uacc4\ub97c \uc0dd\uac01\ud558\uac8c \ud558\ub294 \uc790\ub9ac\uac00 \ub420 \uc218 \uc788\ub2e4\ub294 \uc124\uba85\uc774\ub2e4. \ub2e4\ub9cc \uc77c\ubcf8 \ubbf8\uc220\uc740 \uc5b8\uc81c\ub098 \ube44\ub300\uce6d\uc774\uace0 \ub2e4\ub978 \ubb38\ud654\ub294 \ub298 \ub300\uce6d\uc774\ub77c\ub294 \uc2dd\uc73c\ub85c \ub098\ub20c \uc218\ub294 \uc5c6\ub2e4. \ucc45 \uc790\uccb4\ub3c4 \uc2dc\ub300\uc640 \uc608\uc220\uc5d0 \ub530\ub77c \ub2e4\ub978 \uacbd\ud5a5\uc744 \uc5b8\uae09\ud55c\ub2e4. \ud55c \uc791\uac00\uac00 \uac15\uc870\ud55c \ubbf8\uac10\uc744 \uad6d\uac00 \uc804\uccb4\uc758 \ubcc0\ud558\uc9c0 \uc54a\ub294 \uc131\uaca9\uc73c\ub85c \ubc14\uafb8\uc9c0 \uc54a\uc744 \ub54c \uc624\ud788\ub824 \uadf8 \uc0dd\uac01\uc744 \ub354 \uc790\uc720\ub86d\uac8c \ubc1b\uc544\ub4e4\uc77c \uc218 \uc788\ub2e4. \uc624\uce74\ucfe0\ub77c\ub294 \ucc3b\uc790\ub9ac\ub97c \uc8fc\uc778 \ud63c\uc790 \uc644\uc131\ud558\ub294 \uc804\uc2dc\ub85c \uc124\uba85\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc8fc\uc778\uacfc \uc190\ub2d8\uc774 \uadf8\ub0a0\uc758 \uc870\ud654\ub97c \ud568\uaed8 \ub9cc\ub4e0\ub2e4\ub294 \uc0dd\uac01\uc774 \ucc45 \uacf3\uacf3\uc5d0 \ud750\ub978\ub2e4. \uadf8\ub9bc\uacfc \uaf43, \uc18c\ub9ac\uc640 \uc6c0\uc9c1\uc784\uc774 \uc11c\ub85c\ub97c \uac00\ub9ac\uc9c0 \uc54a\uac8c \ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \uadf8\ub987\uc774 \ube44\uc2f8\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc88b\uc740 \uc7a5\uba74\uc774 \uc800\uc808\ub85c \uc774\ub8e8\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \ub73b\uc73c\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \uc774\ub807\uac8c \ubcf4\uba74 \uc608\uc220\uc740 \ubc15\ubb3c\uad00 \ubcbd\uc5d0 \uac78\ub9b0 \ub300\uc0c1\ub9cc\uc744 \uac00\ub9ac\ud0a4\uc9c0 \uc54a\ub294\ub2e4. \ubb3c\uac74\uc744 \uace0\ub974\uace0 \ub193\ub294 \uc77c, \uc0ac\ub78c\uc744 \ub9de\uc774\ud558\uace0 \ud568\uaed8 \uc2dc\uac04\uc744 \ubcf4\ub0b4\ub294 \uc77c\uc5d0\ub3c4 \uac10\uc0c1\uc758 \ubb38\uc81c\uac00 \ub4e4\uc5b4\uc628\ub2e4. \ubb3c\ub860 \uc774\uac83\uc740 \uc800\uc790\uac00 \uac15\uc870\ud55c \uc774\uc0c1\uc774\ub2e4. \uc2e4\uc81c \ucc3b\uc790\ub9ac\uac00 \uc5b8\uc81c\ub098 \uc644\uc804\ud588\ub2e4\ub294 \uc99d\uc5b8\uc73c\ub85c \ubc14\uafb8\uae30\ubcf4\ub2e4, \uc77c\uc0c1\uc744 \uc608\uc220\uc758 \uc5b8\uc5b4\ub85c \uc124\uba85\ud558\ub824\ub358 \uadf8\uc758 \uc2dc\ub3c4\ub97c \uc77d\ub294 \ud3b8\uc774 \ucc45\uc5d0 \ub354 \uac00\uae5d\ub2e4. \u300e\ucc28\uc758 \ucc45\u300f\uc744 \uc77d\uc5c8\ub2e4\uace0 \ucc3b\uc790\ub9ac\ub97c \ubc14\ub85c \uc9c4\ud589\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ucc45\uc758 \ub9e4\ub825\uc740 \uc790\uaca9\uc744 \uc5bb\ub294 \ub370 \uc788\uc9c0 \uc54a\ub2e4. \uaf43\uc744 \ud55c \ubc88 \ub354 \ubcf4\uace0, \uc190\uc5d0 \ub2ff\ub294 \uadf8\ub987\uc744 \uc0b4\ud53c\uace0, \uac19\uc774 \uc549\uc740 \uc0ac\ub78c\uc5d0\uac8c \uc8fc\uc758\ub97c \uae30\uc6b8\uc774\ub294 \uc2dc\uac04\uc744 \uc0c1\uc0c1\ud558\uac8c \ud55c\ub2e4\ub294 \ub370 \uc788\ub2e4. \ud55c \uc794\uc758 \ucc28\uac00 \uc138\uc0c1\uc758 \ubaa8\ub4e0 \uc18c\ub780\uc744 \ud574\uacb0\ud558\uc9c0\ub294 \ubabb\ud55c\ub2e4. \uadf8\ub798\ub3c4 \ubb34\uc5c7\uc744 \ubcf4\ub290\ub77c \ubc14\ube74\ub294\uc9c0 \uc7a0\uae50 \ub3cc\uc544\ubcf4\uac8c \ud560 \uc218\ub294 \uc788\ub2e4. \ubc29\uc744 \uaf49 \ucc44\uc6b4 \ub4a4 \uac10\ud0c4\ud558\ub294 \ub300\uc2e0 \ud55c\ub450 \uac00\uc9c0\ub97c \ub0a8\uaca8 \ub450\uace0 \uc624\ub798 \ubc14\ub77c\ubcf4\ub294 \uc77c. \uc624\uce74\ucfe0\ub77c\uac00 \ucc3b\uc794\uc744 \ud1b5\ud574 \uc804\ud558\uace0 \uc2f6\uc5c8\ub358 \uc0dd\uac01\uc758 \ud55c \uac08\ub798\uac00 \uadf8\uacf3\uc5d0 \uc788\ub2e4. \uc61b \ucc45\uc758 \ubaa8\ub4e0 \uc8fc\uc7a5\uc5d0 \ub3d9\uc758\ud560 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ub9c8\uc74c\uc5d0 \ub0a8\ub294 \uc7a5\uba74 \ud558\ub098\ub97c \uac00\uc838\uc624\uace0 \ub2e4\ub978 \ubd80\ubd84\uc5d0\ub294 \uc9c8\ubb38\uc744 \ub0a8\uaca8 \ub458 \uc218 \uc788\ub2e4. \ubb38\ud654 \uc5d0\uc138\uc774\ub97c \uc77d\ub294 \uc77c\uc740 \ud55c \uad6d\uac00\ub97c \ud55c \ubc88\uc5d0 \uc774\ud574\ud558\ub294 \uc77c\ubcf4\ub2e4, \ud55c \uc0ac\ub78c\uc758 \uc2dc\uc120\uacfc \ucc9c\ucc9c\ud788 \ub300\ud654\ud558\ub294 \uc77c\uc5d0 \uac00\uae5d\ub2e4."}, {"id": "olympia-stadion-games-and-honor", "title": "\uc62c\ub9bc\ud53c\uc544\uc758 \ub2ec\ub9ac\uae30 \u2014 \uace0\ub300 \uc120\uc218\ub4e4\uc740 \ubb34\uc5c7\uc744 \uc704\ud574 \ub6f0\uc5c8\uc744\uae4c", "summary": "\uace0\ub300 \uc62c\ub9bc\ud53d\uc758 \uc885\uad50\uc801 \ubc30\uacbd\uacfc \ub3c4\uc2dc\uc758 \uc790\ubd80\uc2ec, \uc2b9\ub9ac\uc758 \ubcf4\uc0c1\uc744 \uacbd\uae30\uc7a5 \uc0ac\uc9c4\uacfc \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc2a4\ud3ec\uce20", "categories": ["arts"], "url": "stories/olympia-stadion-games-and-honor/index.html", "image": "../media/olympia-stadion-games-and-honor.png", "alt": "\ub098\ubb34\uc640 \ub0ae\uc740 \ub454\ub355 \uc0ac\uc774\uc5d0 \ub0a8\uc740 \uc62c\ub9bc\ud53c\uc544\uc758 \uace0\ub300 \ub2ec\ub9ac\uae30 \ud2b8\ub799", "text": "\uc62c\ub9bc\ud53c\uc544\uc758 \ub2ec\ub9ac\uae30 \u2014 \uace0\ub300 \uc120\uc218\ub4e4\uc740 \ubb34\uc5c7\uc744 \uc704\ud574 \ub6f0\uc5c8\uc744\uae4c \ub3c4\uc2dc\ub9c8\ub2e4 \ub2ec\ub790\ub358 \uadf8\ub9ac\uc2a4\uc778\ub4e4\uc774 \ud55c \uacbd\uae30\uc7a5\uc744 \ubc14\ub77c\ubcf8 \uc774\uc720 \uace0\ub300 \uc62c\ub9bc\ud53d\uc758 \uc885\uad50\uc801 \ubc30\uacbd\uacfc \ub3c4\uc2dc\uc758 \uc790\ubd80\uc2ec, \uc2b9\ub9ac\uc758 \ubcf4\uc0c1\uc744 \uacbd\uae30\uc7a5 \uc0ac\uc9c4\uacfc \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc2a4\ud3ec\uce20 \ubb38\ud654\uc640 \uc608\uc220 \uc0ac\uc9c4 \uc18d \uc62c\ub9bc\ud53c\uc544 \uacbd\uae30\uc7a5\uc740 \uc870\uc6a9\ud558\ub2e4. \ub113\uac8c \ube44\uc5b4 \uc788\ub294 \ud759\ubc14\ub2e5\uacfc \uc644\ub9cc\ud55c \uc8fc\ubcc0 \uc9c0\ud615\uc744 \ubcf4\uba74 \ud654\ub824\ud55c \ud604\ub300 \uacbd\uae30\uc7a5\uc758 \ubaa8\uc2b5\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc5b4\ub835\ub2e4. \ud558\uc9c0\ub9cc \uc774\uacf3\uc5d0\uc11c\ub294 \ub2ec\ub9ac\ub294 \uc0ac\ub78c\uc744 \uc9c0\ucf1c\ubcf4\uba70 \uba40\ub9ac \ub5a8\uc5b4\uc9c4 \ub3c4\uc2dc\uc758 \uc774\ub984\uae4c\uc9c0 \ud568\uaed8 \uae30\uc5b5\ud558\ub358 \uc2dc\uac04\uc774 \uc788\uc5c8\ub2e4. \uace0\ub300 \uc62c\ub9bc\ud53d\uc744 \uc624\ub298 \uc62c\ub9bc\ud53d\uc758 \uc791\uc740 \uc61b \ubaa8\uc2b5\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \uc758\uc678\uc758 \ucc28\uc774\ub97c \ub193\uce5c\ub2e4. \uc624\ud508\uc2a4\ud0dd\uc2a4\uc758 \uace0\ub300 \uadf8\ub9ac\uc2a4 \uc124\uba85\uc744 \ubc14\ud0d5\uc73c\ub85c, \uc120\uc218 \ud55c \uc0ac\ub78c\uc774 \ub6f0\ub294 \uc77c\uc5d0 \uc885\uad50\uc640 \uba85\uc608\uc640 \ub3c4\uc2dc\uc758 \uacbd\uc7c1\uc774 \uc5b4\ub5bb\uac8c \uc5bd\ud600 \uc788\uc5c8\ub294\uc9c0 \uc0b4\ud3b4\ubcf8\ub2e4. \uace0\ub300 \uadf8\ub9ac\uc2a4 \uc138\uacc4\ub294 \ud558\ub098\uc758 \ud1b5\uc77c \uad6d\uac00\ub85c\ub9cc \uc6c0\uc9c1\uc774\uc9c0 \uc54a\uc558\ub2e4. \uc5ec\ub7ec \ub3c4\uc2dc\uad6d\uac00\uac00 \uac01\uc790\uc758 \uc81c\ub3c4\uc640 \uc774\ud574\uad00\uacc4\ub97c \uac00\uc9c0\uace0 \uacbd\uc7c1\ud588\ub2e4. \ubc14\ub2e4\ub97c \uac74\ub108 \ub2e4\ub978 \uacf3\uc5d0 \uc815\ucc29\ud55c \uadf8\ub9ac\uc2a4\uc778\ub4e4\ub3c4 \uc788\uc5c8\ub2e4. \uc11c\ub85c\ub97c \uac19\uc740 \ud3b8\uc73c\ub85c \uc5ec\uae30\uac8c \ud558\ub294 \uc7a5\uce58\uc640, \uc2e4\uc81c\ub85c \ubd80\ub52a\uce58\ub294 \ud604\uc2e4\uc774 \ud568\uaed8 \uc874\uc7ac\ud588\ub2e4. \uadf8 \uc0ac\uc774\uc5d0\uc11c \uc5b8\uc5b4\uc640 \uc2e0\ub4e4\uc5d0 \ub300\ud55c \ubbff\uc74c, \ud568\uaed8 \ucc38\uc5ec\ud558\ub294 \ucd95\uc81c\ub294 \uc5f0\uacb0\uc758 \uc2e4\ub9c8\ub9ac\uac00 \ub418\uc5c8\ub2e4. \uc62c\ub9bc\ud53c\uc544\uc758 \uacbd\uae30\ub3c4 \uadf8\ub7f0 \uacf5\ud1b5\uc758 \uacf5\uac04\uc774\uc5c8\ub2e4. \ubaa8\ub4e0 \uac08\ub4f1\uc774 \uc0ac\ub77c\uc84c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc624\ud788\ub824 \uc11c\ub85c \ub2e4\ub978 \ub3c4\uc2dc\uc758 \uc0ac\ub78c\ub4e4\uc774 \uac19\uc740 \uaddc\uce59\uacfc \uba85\uc608\ub97c \ubc14\ub77c\ubcf8\ub2e4\ub294 \uc0ac\uc2e4 \uc790\uccb4\uac00 \uc911\uc694\ud588\ub2e4. \uc62c\ub9bc\ud53c\uc544\ub294 \uc81c\uc6b0\uc2a4\uc640 \uc5f0\uacb0\ub41c \uc131\uc5ed\uc774\uc5c8\ub2e4. \uacbd\uae30\ub294 \uc885\uad50\uc640 \ubb34\uad00\ud55c \uc5ec\uac00 \ud589\uc0ac\ub85c\ub9cc \uc5f4\ub9ac\uc9c0 \uc54a\uc558\ub2e4. \uc2e0\uc5d0\uac8c \ubc14\uce58\ub294 \ucd95\uc81c\uc758 \uc2dc\uac04\uc5d0 \uc778\uac04\uc758 \ud798\uacfc \uae30\ub7c9\uc774 \ub4dc\ub7ec\ub0ac\ub2e4. \uc6b4\ub3d9\uc7a5\uc744 \ub458\ub7ec\uc2fc \uc758\ubbf8\ub97c \ube7c\uba74, \uc65c \uba3c\uae38\uc744 \uc640\uc11c \uaca8\ub8e8\uace0 \uc2b9\ub9ac\ub97c \uae30\uc5b5\ud588\ub294\uc9c0 \ucda9\ubd84\ud788 \uc124\uba85\ud558\uae30 \uc5b4\ub835\ub2e4. \uc6b0\ub9ac\uac00 \ud754\ud788 \ub4e3\ub294 \uae30\uc6d0\uc804 776\ub144\uc740 \uace0\ub300 \uc62c\ub9bc\ud53d\uc758 \uc804\ud1b5\uc801\uc778 \uc5f0\ub300 \uae30\uc900\uc774\ub2e4. \uadf8\ub0a0 \ub204\uad70\uac00 \ucc98\uc74c\uc73c\ub85c \ub2ec\ub9ac\uae30\ub97c \uc0dd\uac01\ud574 \ub0c8\ub2e4\ub294 \ub73b\uc73c\ub85c \ubc1b\uc544\ub4e4\uc774\uc9c0\ub294 \ub9d0\uc544\uc57c \ud55c\ub2e4. \uae30\ub85d\uacfc \uc5f0\ub300\uc758 \ucd9c\ubc1c\uc810, \uadf8\ub9ac\uace0 \uc2e4\uc81c \uad00\uc2b5\uc774 \uc790\ub77c\ub09c \uacfc\uc815\uc740 \uc815\ud655\ud788 \uac19\uc740 \ubb38\uc81c\ub294 \uc544\ub2c8\ub2e4. \uc624\ub798\ub41c \ud589\uc0ac\ub97c \ub2e4\ub8f0 \ub54c \uc22b\uc790\ub294 \ud3b8\ub9ac\ud558\uc9c0\ub9cc \ubaa8\ub4e0 \uc0ac\uc815\uc744 \ub9d0\ud574 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \ucd08\uae30\uc758 \ud575\uc2ec \uacbd\uae30\uc5d0\ub294 \uc2a4\ud0c0\ub514\uc628 \ub2ec\ub9ac\uae30\uac00 \uc788\uc5c8\ub2e4. \uacbd\uae30\uc7a5\uc758 \ud55c \uad6c\uac04\uc744 \uc804\ub825\uc73c\ub85c \ub2ec\ub9ac\ub294 \uc9e7\uc740 \uacbd\uc8fc\ub2e4. \ud604\ub300\uc758 \ubcf5\uc7a1\ud55c \uacc4\uce21 \uc7a5\ube44\ub098 \uac70\ub300\ud55c \uc911\uacc4 \ud654\uba74\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc804\uc5d0, \ub204\uac00 \uac00\uc7a5 \uba3c\uc800 \ub2ff\ub294\uc9c0 \ubab8\uc73c\ub85c \ud655\uc778\ud558\ub294 \uc7a5\uba74\uc744 \uc0dd\uac01\ud574 \ubcf4\uba74 \ub41c\ub2e4. \ub2e8\uc21c\ud558\uae30\uc5d0 \uc2b9\ubd80\uc758 \uc21c\uac04\uc740 \ub354 \uc9c1\uc811\uc801\uc774\uc5c8\uc744 \uac83\uc774\ub2e4. \uc2a4\ud0c0\ub514\uc628\uc740 \ub2ec\ub9ac\ub294 \uac70\ub9ac\uc640 \uacf5\uac04\uc744 \uac00\ub9ac\ud0a4\ub294 \ub9d0\uc774\uc5c8\uace0, \uc624\ub298 \uacbd\uae30\uc7a5\uc744 \ub73b\ud558\ub294 \ub9d0\uc5d0\ub3c4 \uadf8 \ud754\uc801\uc774 \ub0a8\uc544 \uc788\ub2e4. \ub2e4\ub9cc \uc61b \ubaa8\ub4e0 \uacbd\uae30\uc7a5\uc758 \uae38\uc774\uac00 \ud604\ub300\uc758 \ub2e8\uc77c \uaddc\uaca9\uacfc \ub611\uac19\uc558\ub2e4\uace0 \uc0c1\uc0c1\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uac19\uc740 \uc885\ubaa9\uc758 \uc774\ub984 \uc544\ub798\uc5d0\uc11c\ub3c4 \uc7a5\uc18c\uc640 \uc2dc\ub300\uc758 \uad6c\uccb4\uc801\uc778 \ubaa8\uc2b5\uc740 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc2dc\uac04\uc774 \uc9c0\ub098\uba70 \ub2ec\ub9ac\uae30\ubfd0 \uc544\ub2c8\ub77c \ub6f0\uae30\uc640 \ub358\uc9c0\uae30, \ubab8\uc744 \ub9de\ub300\ub294 \uacbd\uae30, \uc804\ucc28 \uacbd\uc8fc \uac19\uc740 \uc885\ubaa9\ub3c4 \ucd95\uc81c \uc548\uc5d0\uc11c \uc790\ub9ac\ub97c \ucc28\uc9c0\ud588\ub2e4. \uacbd\uae30\ub9c8\ub2e4 \ud544\uc694\ud55c \ub2a5\ub825\uc740 \ub2ec\ub790\ub2e4. \ube60\ub978 \ubab8\uacfc \uac15\ud55c \ubab8, \ud6c8\ub828\uc758 \uae30\uc220\uacfc \ube44\uc6a9\uc774 \ub9ce\uc774 \ub4dc\ub294 \uc900\ube44\uac00 \ud55c \ud589\uc0ac \uc548\uc5d0 \ubaa8\uc600\ub2e4. \uc804\ucc28 \uacbd\uc8fc\uae4c\uc9c0 \uc0dd\uac01\ud558\uba74 \uc2b9\ub9ac\uac00 \uac1c\uc778\uc758 \uadfc\uc721\ub9cc\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc774 \uc120\uba85\ud574\uc9c4\ub2e4. \ub9d0\uacfc \uc7a5\ube44\uc640 \uc0ac\ub78c\uc744 \uc900\ube44\ud560 \uc218 \uc788\ub294 \uc790\uc6d0\uc774 \ud544\uc694\ud558\ub2e4. \uace0\ub300\uc758 \uc2a4\ud3ec\uce20\ub3c4 \uc0dd\ud65c\uc758 \uacbd\uc81c\uc640 \uc0ac\ud68c\uc801 \uc870\uac74\uc5d0\uc11c \ub530\ub85c \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\uc558\ub2e4. \ubaa8\ub4e0 \uc120\uc218\uac00 \uac19\uc740 \ucd9c\ubc1c \uc870\uac74\uc744 \uac00\uc84c\ub2e4\ub294 \ub0ad\ub9cc\uc801\uc778 \uadf8\ub9bc\uacfc\ub294 \uac70\ub9ac\uac00 \uc788\ub2e4. \uace0\ub300 \uc120\uc218\ub4e4\uc774 \uc624\uc9c1 \uc21c\uc218\ud55c \uba85\uc608\ub9cc\uc744 \uc704\ud574 \ub6f0\uc5c8\ub2e4\uace0 \uc0c1\uc0c1\ud558\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uad50\uc7ac\ub294 \uc804\ubb38\uc801\uc778 \ud6c8\ub828\uacfc \uc2b9\ub9ac \ub4a4\uc758 \ubcf4\uc0c1, \uace0\ud5a5 \ub3c4\uc2dc\uc758 \ud658\ub300\uc5d0 \uc8fc\ubaa9\ud55c\ub2e4. \uacbd\uae30\uc7a5\uc5d0\uc11c \ubc1b\ub294 \uc0c1\uc758 \ud615\ud0dc\uac00 \uac04\uc18c\ud558\ub2e4\uace0 \ud574\uc11c \uc6b0\uc2b9\uc758 \uc0ac\ud68c\uc801 \uac00\uce58\uae4c\uc9c0 \uc791\uc558\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2b9\uc790\ub294 \uc790\uc2e0\uc758 \uc774\ub984\uc744 \uc54c\ub9ac\uace0 \ub3c4\uc2dc\uc758 \uc790\ubd80\uc2ec\uc774 \ub420 \uc218 \uc788\uc5c8\ub2e4. \uc870\uac01\uc0c1\uc774 \uc138\uc6cc\uc9c0\uac70\ub098 \uc2b9\ub9ac\ub97c \uae30\ub9ac\ub294 \uc2dc\uac00 \uc9c0\uc5b4\uc84c\ub2e4. \ud540\ub2e4\ub85c\uc2a4\uc758 \uc2b9\ub9ac \uc1a1\uac00\uac00 \ubcf4\uc5ec \uc8fc\ub4ef, \ubab8\uc73c\ub85c \ub05d\ub09c \ud55c\uc21c\uac04\uc740 \ub9d0\uacfc \uc608\uc220\ub85c \ub354 \uc624\ub798 \uc774\uc5b4\uc84c\ub2e4. \uacbd\uc8fc\ub294 \uc9e7\uc558\uc9c0\ub9cc \uc6b0\uc2b9\uc790\uac00 \ub418\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc758 \uc218\uba85\uc740 \uae38\uc5c8\ub2e4. \ud55c \uc0ac\ub78c\uc774 \ub2e4\ub978 \uc0ac\ub78c\ubcf4\ub2e4 \uba3c\uc800 \uacb0\uc2b9\uc5d0 \ub2ff\ub294\ub2e4. \uacb0\uacfc\ub294 \uac1c\uc778\uc5d0\uac8c \uc18d\ud558\uc9c0\ub9cc \uadf8 \uc774\uc57c\uae30\ub294 \ub3c4\uc2dc\ub85c \ub3cc\uc544\uac04\ub2e4. \ub3c4\uc2dc\uac00 \uc120\uc218\ub97c \uc790\ub791\ud558\ub294 \ub3d9\uc548 \uc120\uc218\uc758 \uc774\ub984\ub3c4 \ub354 \ud070 \uad00\uacc4 \uc18d\uc5d0 \ub193\uc778\ub2e4. \uc6b4\ub3d9\uc758 \uae30\ub7c9\uc774 \uacf5\ub3d9\uccb4\ub97c \ub300\ud45c\ud558\ub294 \uc790\uc0b0\uc73c\ub85c \ubc14\ub00c\ub294 \ubaa8\uc2b5\uc774\ub2e4. \uc774\ub7f0 \uc5f0\uacb0\uc740 \uc624\ub298\uc5d0\ub3c4 \ub0af\uc124\uc9c0 \uc54a\ub2e4. \ub2e4\ub9cc \ud604\ub300\uc758 \uad6d\uac00\ub300\ud45c \uccb4\uacc4\uc640 \uace0\ub300 \ub3c4\uc2dc\uc758 \uad00\uacc4\ub97c \uadf8\ub300\ub85c \uacb9\uce58\uba74 \ucc28\uc774\uac00 \uc9c0\uc6cc\uc9c4\ub2e4. \ube44\uc2b7\ud55c \uac10\uc815\uc774 \uc788\ub2e4\uace0 \uc81c\ub3c4\uae4c\uc9c0 \uac19\uc9c0\ub294 \uc54a\ub2e4. \uc624\ub798\ub41c \uacbd\uae30\uc5d0\uc11c \uc775\uc219\ud568\uc744 \ubc1c\uacac\ud558\ub418 \uadf8 \uc2dc\ub300\uc758 \ub2e8\uc704\uc640 \uaddc\uce59\ub3c4 \ud568\uaed8 \uae30\uc5b5\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uace0\ub300 \ucd95\uc81c\uc758 \ucc38\uac00 \uc790\uaca9\uacfc \uc0ac\ud68c \uc9c8\uc11c\ub294 \uc624\ub298 \uc6b0\ub9ac\uac00 \ubc14\ub77c\ub294 \ubcf4\ud3b8\uc801\uc778 \ucc38\uc5ec\uc640 \uac19\uc9c0 \uc54a\uc558\ub2e4. \uc5ec\uc131\uc758 \uad00\ub78c\uacfc \ucc38\uc5ec \ubb38\uc81c\ub3c4 \ud589\uc0ac\uc640 \uc2e0\ubd84, \uc5ed\ud560\uc5d0 \ub530\ub978 \uad6c\ubcc4\uc744 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \ubaa8\ub4e0 \uc5ec\uc131\uc774 \ub611\uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uae08\uc9c0\ub418\uc5c8\ub2e4\ub294 \ud55c \ubb38\uc7a5\uc73c\ub85c \ubcf5\uc7a1\ud55c \uad00\uc2b5\uc744 \ub36e\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. 1896\ub144\uc5d0 \uc2dc\uc791\ub41c \uadfc\ub300 \uc62c\ub9bc\ud53d \uc5ed\uc2dc \uace0\ub300 \ud589\uc0ac\ub97c \uadf8\ub300\ub85c \ubcf5\uc6d0\ud55c \ubcf5\uc81c\ud488\uc740 \uc544\ub2c8\ub2e4. \uc61b \uc774\ub984\uacfc \uc0c1\uc9d5\uc744 \uc0c8 \uc2dc\ub300\uc758 \uad6d\uc81c \uacbd\uae30\ub85c \ubc14\uafb8\uc5b4 \ub9cc\ub4e0 \uc81c\ub3c4\ub2e4. \uc0ac\uc9c4\uc758 \ube48 \ud2b8\ub799\uc744 \ub2e4\uc2dc \ubcf4\uba74 \uadf8\ub798\uc11c \ub450 \uc2dc\ub300\uac00 \ud568\uaed8 \ub5a0\uc624\ub978\ub2e4. \uc624\ub298\uc758 \uacbd\uae30\uc7a5\uc744 \ub2ee\uc544\uc11c\uac00 \uc544\ub2c8\ub77c, \ud55c \uc0ac\ub78c\uc758 \ub2ec\ub9ac\uae30\uc5d0 \uc5bc\ub9c8\ub098 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uc758\ubbf8\ub97c \uc5b9\uc744 \uc218 \uc788\ub294\uc9c0 \uc624\ub798\uc804\ubd80\ud130 \ubcf4\uc5ec \uc8fc\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4."}, {"id": "orpheus-eurydice-last-look", "title": "\uc624\ub974\ud398\uc6b0\uc2a4\ub294 \uc65c \ub4a4\ub97c \ub3cc\uc544\ubcf4\uc558\uc744\uae4c", "summary": "\uc624\ube44\ub514\uc6b0\uc2a4\uc758 \u300e\ubcc0\uc2e0 \uc774\uc57c\uae30\u300f\ub97c \ub530\ub77c, \ub178\ub798\ub85c \uc5f4\ub9b0 \uae38\uacfc \ub9c8\uc9c0\ub9c9 \ud55c \ubc88\uc758 \uc2dc\uc120\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc2e0\ud654\uc640 \ubbfc\uc18d", "categories": ["arts"], "url": "stories/orpheus-eurydice-last-look/index.html", "image": "../media/orpheus-eurydice-last-look.png", "alt": "\ub9ac\ub77c\ub97c \ub4e0 \uc624\ub974\ud398\uc6b0\uc2a4\uc640 \ub4a4\uc5d0\uc11c \uc9c0\uc0c1\uc758 \ube5b\uc744 \ud5a5\ud574 \uc62c\ub77c\uc624\ub294 \uc5d0\uc6b0\ub9ac\ub514\ucf00\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uc624\ub974\ud398\uc6b0\uc2a4\ub294 \uc65c \ub4a4\ub97c \ub3cc\uc544\ubcf4\uc558\uc744\uae4c \uac70\uc758 \ub2e4 \uc654\uc744 \ub54c, \uc0ac\ub791\uc740 \uac00\uc7a5 \uc5b4\ub824\uc6b4 \uc2dc\ud5d8\uc744 \ub9cc\ub0ac\ub2e4 \uc624\ube44\ub514\uc6b0\uc2a4\uc758 \u300e\ubcc0\uc2e0 \uc774\uc57c\uae30\u300f\ub97c \ub530\ub77c, \ub178\ub798\ub85c \uc5f4\ub9b0 \uae38\uacfc \ub9c8\uc9c0\ub9c9 \ud55c \ubc88\uc758 \uc2dc\uc120\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc2e0\ud654\uc640 \ubbfc\uc18d \ubb38\ud654\uc640 \uc608\uc220 \uc9c0\uc0c1\uc73c\ub85c \uc62c\ub77c\uac00\ub294 \uae38\uc774\uc5c8\ub2e4. \uc55e\uc5d0\ub294 \uc624\ub974\ud398\uc6b0\uc2a4\uac00, \ub4a4\uc5d0\ub294 \uc8fd\uc74c\uc758 \uc138\uacc4\uc5d0\uc11c \ub3cc\uc544\uc624\ub294 \uc5d0\uc6b0\ub9ac\ub514\ucf00\uac00 \uc788\uc5c8\ub2e4. \uc774\uc81c \uc870\uae08\ub9cc \ub354 \uac78\uc73c\uba74 \ub41c\ub2e4. \uadf8\ub7f0\ub370 \uadf8\ub294 \ubc14\ub85c \uadf8 \uc21c\uac04 \ub4a4\ub97c \ub3cc\uc544\ubcf8\ub2e4. \uadf8\ub9ac\uc2a4 \uc2e0\ud654\ub97c \ub300\ud45c\ud558\ub294 \uc774 \uc7a5\uba74\uc740 \ud754\ud788 \uc57d\uc18d\uc744 \uc9c0\ud0a4\uc9c0 \ubabb\ud55c \uc0ac\ub78c\uc758 \uc774\uc57c\uae30\ub85c \uc18c\uac1c\ub41c\ub2e4. \ud558\uc9c0\ub9cc \uc0ac\uc815\uc744 \uc54c\uba74 \uadf8\ub807\uac8c \uac04\ub2e8\ud788 \uafb8\uc9d6\uae30 \uc5b4\ub835\ub2e4. \uc5ec\uae30\uc11c\ub294 \ub85c\ub9c8 \uc2dc\uc778 \uc624\ube44\ub514\uc6b0\uc2a4\uc758 \u300e\ubcc0\uc2e0 \uc774\uc57c\uae30\u300f \uc81c10\uad8c\uc5d0 \uc2e4\ub9b0 \uc804\uc2b9\uc744 \ub530\ub77c\uac00 \ubcf8\ub2e4. \uacb0\ub9d0\uc744 \ud3ec\ud568\ud55c\ub2e4. \uadf8 \ud55c \ubc88\uc758 \uc2dc\uc120 \uc55e\uc5d0\uc11c \ub178\ub798\uc758 \ud798\uacfc \uc0ac\ub78c\uc758 \ub9c8\uc74c\uc774 \uc5c7\uac08\ub9b0\ub2e4. \uc624\ub974\ud398\uc6b0\uc2a4\ub294 \ub9ac\ub77c\ub97c \ucf1c\uba70 \ub178\ub798\ud558\ub294 \uc0ac\ub78c\uc774\uc5c8\ub2e4. \uadf8\uc758 \uc74c\uc545\uc740 \uc778\uac04\uc758 \ub9c8\uc74c\uc744 \uc6c0\uc9c1\uc774\ub294 \ub370 \uadf8\uce58\uc9c0 \uc54a\uc558\ub2e4. \uc2e0\ud654 \uc18d\uc5d0\uc11c\ub294 \ud3c9\uc18c \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294 \uc874\uc7ac\ub4e4\ub9c8\uc800 \uadc0\ub97c \uae30\uc6b8\uc778\ub2e4. \uadf8\ub9cc\ud07c \ub180\ub77c\uc6b4 \uc7ac\ub2a5\uc744 \uac00\uc9c4 \uc74c\uc545\uac00\uc5d0\uac8c\ub3c4 \ub9c9\uc744 \uc218 \uc5c6\ub294 \uc77c\uc774 \uc0dd\uacbc\ub2e4. \uc5d0\uc6b0\ub9ac\ub514\ucf00\uc640\uc758 \ud63c\ub840\uc5d0\ub294 \ubd88\uae38\ud55c \uae30\uc6b4\uc774 \uac10\ub3c8\ub2e4. \uc774\uc5b4 \uadf8\ub140\uac00 \ub2e4\ub978 \uc694\uc815\ub4e4\uacfc \ud480\ubc2d\uc744 \uac77\ub2e4\uac00 \ubc40\uc5d0\uac8c \ubb3c\ub824 \uc8fd\ub294\ub2e4. \uc624\ub798\ub3c4\ub85d \ud568\uaed8 \uc0b4\uc544\uac08 \uc904 \uc54c\uc558\ub358 \ub450 \uc0ac\ub78c\uc740 \uacb0\ud63c\ud55c \uc9c0 \uc5bc\ub9c8 \ub418\uc9c0 \uc54a\uc544 \uac08\ub77c\uc9c4\ub2e4. \uc774 \ud310\ubcf8\uc5d0\ub294 \ub2e4\ub978 \ub0a8\uc790\uc758 \ucd94\uaca9\uc744 \ud53c\ud574 \ub2ec\ub838\ub2e4\ub294 \uc0ac\uc5f0\uc774 \ub098\uc624\uc9c0 \uc54a\ub294\ub2e4. \uc624\ub974\ud398\uc6b0\uc2a4\ub294 \uc2ac\ud514\uc744 \ub178\ub798\ud558\ub294 \ub370\uc11c \uba48\ucd94\uc9c0 \uc54a\ub294\ub2e4. \uc8fd\uc740 \uc774\ub4e4\uc774 \uba38\ubb34\ub294 \uc800\uc2b9\uc73c\ub85c \ub0b4\ub824\uac00 \uadf8\uacf3\uc758 \uc9c0\ubc30\uc790\ub4e4 \uc55e\uc5d0 \uc120\ub2e4. \uc5ec\uae30\uc11c \uc800\uc2b9\uc740 \uae30\ub3c5\uad50\uc758 \uc9c0\uc625\uacfc \ub611\uac19\uc740 \uacf5\uac04\uc774 \uc544\ub2c8\ub2e4. \uc5d0\uc6b0\ub9ac\ub514\ucf00 \uc5ed\uc2dc \uc8c4\ub97c \uc9c0\uc5b4 \ubc8c\uc744 \ubc1b\uc73c\ub7ec \uac04 \uc778\ubb3c\uc774 \uc544\ub2c8\ub2e4. \uadf8\uc758 \uccad\uc740 \uc8fd\uc74c\uc744 \uc601\uc6d0\ud788 \uc5c6\uc560 \ub2ec\ub77c\ub294 \uc694\uad6c\uac00 \uc544\ub2c8\ub2e4. \uc0ac\ub791\ud558\ub294 \uc0ac\ub78c\uc774 \ub108\ubb34 \uc77c\ucc0d \ub5a0\ub0ac\uc73c\ub2c8 \ud568\uaed8\ud560 \uc2dc\uac04\uc744 \uc870\uae08 \ub354 \ud5c8\ub77d\ud574 \ub2ec\ub77c\ub294 \ubd80\ud0c1\uc5d0 \uac00\uae5d\ub2e4. \uc5b8\uc820\uac00 \ub450 \uc0ac\ub78c \ubaa8\ub450 \uc8fd\uc74c\uc758 \uc138\uacc4\ub85c \ub3cc\uc544\uc62c \uac83\uc774\ub77c\ub294 \uc0ac\uc2e4\uae4c\uc9c0 \uc778\uc815\ud55c\ub2e4. \ubd88\uac00\ub2a5\ud55c \uc694\uad6c\ub97c \ub0ae\uc740 \ubaa9\uc18c\ub9ac\uc758 \uac04\uccad\uc73c\ub85c \ubc14\uafbc \uc148\uc774\ub2e4. \ub178\ub798\uac00 \uc6b8\ub9ac\uc790 \uc800\uc2b9\uc758 \uc77c\uc0c1\uc5d0 \ud2c8\uc774 \uc0dd\uae34\ub2e4. \ub05d\uc5c6\ub294 \ud615\ubc8c\uc5d0 \uc2dc\ub2ec\ub9ac\ub358 \uc874\uc7ac\ub4e4\uc774 \uc7a0\uc2dc \ud558\ub358 \uc77c\uc744 \uba48\ucd94\uace0, \ubb34\uc11c\uc6b4 \ubcf5\uc218\uc758 \uc5ec\uc2e0\ub4e4\uae4c\uc9c0 \ub208\ubb3c\uc744 \ubcf4\uc778\ub2e4. \ud55c \uc0ac\ub78c\uc758 \uc2ac\ud514\uc744 \ub4e3\ub290\ub77c \uac70\ub300\ud55c \uc8fd\uc74c\uc758 \uc9c8\uc11c\uac00 \uc7a0\uae50 \uba48\uce6b\ud558\ub294 \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c \uc74c\uc545\uc758 \ud6a8\ub2a5\uc744 \uc124\uba85\ud558\ub294 \ub300\ubaa9\uc740 \ubb3c\ub860 \uc544\ub2c8\ub2e4. \uc2dc\ub294 \ud3c9\uc18c\ub77c\uba74 \uacb0\ucf54 \uc6c0\uc9c1\uc774\uc9c0 \uc54a\uc744 \uc874\uc7ac\ub4e4\uc744 \ucc28\ub840\ub85c \uba48\ucd94\uac8c \ud558\uc5ec \uadf8 \ub178\ub798\uc758 \ud798\uc744 \ubcf4\uc5ec\uc900\ub2e4. \ubb34\uc2a8 \uc120\uc728\uc774\uc5c8\ub294\uc9c0 \uc545\ubcf4 \ud55c \uc904 \ub0a8\uae30\uc9c0 \uc54a\uace0\ub3c4, \ub3c5\uc790\ub294 \uc5bc\ub9c8\ub098 \uac04\uc808\ud55c \ub178\ub798\uc600\uc744\uc9c0 \uc0c1\uc0c1\ud558\uac8c \ub41c\ub2e4. \ub9c8\uce68\ub0b4 \uc5d0\uc6b0\ub9ac\ub514\ucf00\ub97c \ub370\ub824\uac00\ub3c4 \uc88b\ub2e4\ub294 \ud5c8\ub77d\uc774 \ub0b4\ub824\uc9c4\ub2e4. \ub2e4\ub9cc \uc9c0\ud558 \uc138\uacc4\ub97c \uc644\uc804\ud788 \ubc97\uc5b4\ub0a0 \ub54c\uae4c\uc9c0 \ub4a4\ub97c \ub3cc\uc544\ubcf4\uc544\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc624\ub974\ud398\uc6b0\uc2a4\ub294 \uc55e\uc7a5\uc11c\uace0, \uc5d0\uc6b0\ub9ac\ub514\ucf00\ub294 \uadf8\ub97c \ub530\ub77c \uc62c\ub77c\uac00\uc57c \ud55c\ub2e4. \uc783\uc5c8\ub358 \uc0ac\ub78c\uc744 \ub3cc\ub824\ubc1b\ub294 \uae30\uc068\uc5d0 \uc544\uc8fc \uc791\uc740 \uae08\uc9c0\uac00 \ubd99\ub294\ub2e4. \uc791\uc740 \uc870\uac74\ucc98\ub7fc \ubcf4\uc5ec\ub3c4, \uac78\uc5b4\uac00\ub294 \ub3d9\uc548\uc5d0\ub294 \ub9cc\ub9cc\uce58 \uc54a\uc558\uc744 \uac83\uc774\ub2e4. \uadf8\ub294 \uacc1\uc5d0\uc11c \uc190\uc744 \uc7a1\uace0 \uac77\ub294 \ub300\uc2e0 \uc55e\uc11c \uac00\uc57c \ud55c\ub2e4. \uc544\ub0b4\uac00 \uc815\ub9d0 \uc624\ub294\uc9c0 \ub208\uc73c\ub85c \ud655\uc778\ud560 \uc218 \uc5c6\ub2e4. \ub3c5\uc790\uc5d0\uac8c\ub294 \uc27d\uac8c \uc9c0\ud0a4\ub77c\uace0 \ub9d0\ud560 \uc218 \uc788\ub294 \uc57d\uc18d\uc774 \ub2f9\uc0ac\uc790\uc5d0\uac8c\ub294 \uae34 \uae30\ub2e4\ub9bc\uc774 \ub41c\ub2e4. \uc774\uac83\uc740 \uc7a5\uba74\uc5d0\uc11c \uc77d\uc5b4\ub0bc \uc218 \uc788\ub294 \ud574\uc11d\uc774\uc9c0 \uc2dc\uac00 \uae30\ub85d\ud55c \uc2e4\uc81c \uc2ec\ub9ac \uac80\uc0ac\ub294 \uc544\ub2c8\ub2e4. \ub450 \uc0ac\ub78c\uc740 \uc5b4\ub461\uace0 \uac00\ud30c\ub978 \uae38\uc744 \uc624\ub978\ub2e4. \uc9c0\uc0c1\uc758 \uacbd\uacc4\uac00 \uac00\uae4c\uc6cc\uc84c\uc744 \ub54c, \uc624\ub974\ud398\uc6b0\uc2a4\ub294 \uc5d0\uc6b0\ub9ac\ub514\ucf00\uac00 \uc9c0\ucce4\uc744\uae4c \uac71\uc815\ud558\uace0 \uadf8\ub140\ub97c \ubcf4\uace0 \uc2f6\uc740 \ub9c8\uc74c\uc744 \uc774\uae30\uc9c0 \ubabb\ud55c\ub2e4. \uc624\ube44\ub514\uc6b0\uc2a4\uc758 \uc11c\uc220\uc740 \uc774 \uc21c\uac04\uc744 \ub2e8\uc21c\ud55c \uc7a5\ub09c\uc774\ub098 \uc2eb\uc99d\uc73c\ub85c \ucc98\ub9ac\ud558\uc9c0 \uc54a\ub294\ub2e4. \uadf8\uac00 \uace0\uac1c\ub97c \ub3cc\ub9ac\uc790 \uc5d0\uc6b0\ub9ac\ub514\ucf00\ub294 \ub2e4\uc2dc \ubbf8\ub044\ub7ec\uc838 \ub0b4\ub824\uac04\ub2e4. \ub450 \uc0ac\ub78c\uc774 \uc11c\ub85c\ub97c \ud5a5\ud574 \ud314\uc744 \ubed7\uc9c0\ub9cc \ubd99\uc7a1\ub294 \uac83\uc740 \ud5c8\uacf5\ubfd0\uc774\ub2e4. \uadf8\ub140\uc758 \ud76c\ubbf8\ud55c \uc791\ubcc4\uc774 \ub4e4\ub9ac\uace0, \uc5b4\ub835\uac8c \uc5bb\uc5c8\ub358 \uadc0\ud658\uc740 \ub05d\ub09c\ub2e4. \ubb38\ud131\uae4c\uc9c0 \uc654\uae30 \ub54c\ubb38\uc5d0 \uc774 \uc2e4\ud328\ub294 \ucd9c\ubc1c\uc870\ucc28 \ud558\uc9c0 \ubabb\ud55c \uacbd\uc6b0\ubcf4\ub2e4 \ub354 \uc544\ud504\uac8c \ub0a8\ub294\ub2e4. \uc624\ub974\ud398\uc6b0\uc2a4\ub294 \ub2e4\uc2dc \uc800\uc2b9\uc73c\ub85c \ub4e4\uc5b4\uac00\ub824 \ud558\uc9c0\ub9cc \uac19\uc740 \uae38\uc740 \uc5f4\ub9ac\uc9c0 \uc54a\ub294\ub2e4. \ub6f0\uc5b4\ub09c \uc74c\uc545\ub3c4, \uc55e\uc120 \uc131\uacf5\ub3c4 \ub418\ud480\uc774\ub97c \ubcf4\uc7a5\ud574 \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \uc2e0\ud654\ub294 \ucc98\uc74c\uc5d0\ub294 \uc608\uc220\uc774 \uc8fd\uc74c\ub9c8\uc800 \uc774\uae38 \uc218 \uc788\uc744 \uac83\ucc98\ub7fc \uae38\uc744 \uc5f4\uc5b4 \ub193\uace0, \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \uadf8 \ud798\uc5d0\ub3c4 \uacbd\uacc4\uac00 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc900\ub2e4. \uc5d0\uc6b0\ub9ac\ub514\ucf00\uc5d0\uac8c\ub3c4 \uc2dc\uc120\uc744 \ub3cc\ub9b4 \ud544\uc694\uac00 \uc788\ub2e4. \uadf8\ub140\ub294 \ub3cc\uc544\uc624\ub294 \uae38\uc5d0\uc11c \uac70\uc758 \ub9d0\ud558\uc9c0 \ubabb\ud558\uace0 \ub2e4\uc2dc \uc0ac\ub77c\uc9c4\ub2e4. \uc774 \uc870\uc6a9\ud568\uc744 \uc544\ub0b4\uc758 \uc798\ubabb\uc73c\ub85c \ucc44\uc6cc \ub123\uac70\ub098 \uc624\ub974\ud398\uc6b0\uc2a4\ub97c \uc2dc\ud5d8\ud558\ub824 \ud55c \ud589\ub3d9\uc73c\ub85c \uc0c1\uc0c1\ud560 \uadfc\uac70\ub294 \uc5c6\ub2e4. \ub3c5\uc790\uac00 \ub354 \ub4e3\uace0 \uc2f6\uc5b4 \ud558\ub294 \ubc14\ub85c \uadf8 \ubaa9\uc18c\ub9ac\uac00 \ube44\uc5b4 \uc788\uc5b4 \uc7a5\uba74\uc740 \uc624\ub798 \ub0a8\ub294\ub2e4. \uc774 \uc2e0\ud654\ub97c \uc0ac\ub791 \ub54c\ubb38\uc5d0 \uaddc\uce59\uc744 \uc5b4\uae34 \uc774\uc57c\uae30\ub85c \uc77d\uc744 \uc218\ub3c4 \uc788\uace0, \ub208\uc55e\uc758 \ud655\uc778 \uc5c6\uc774\ub294 \ubbff\uae30 \uc5b4\ub824\uc6b4 \uc778\uac04\uc758 \uc774\uc57c\uae30\ub85c \uc77d\uc744 \uc218\ub3c4 \uc788\ub2e4. \uc5b4\ub5a4 \ub3c5\uc790\ub294 \uc74c\uc545\uc758 \ud55c\uacc4\ub97c, \ub2e4\ub978 \ub3c5\uc790\ub294 \ub108\ubb34 \uc131\uae09\ud55c \ub9c8\uc9c0\ub9c9 \uc21c\uac04\uc744 \uba3c\uc800 \ub5a0\uc62c\ub9b4 \uac83\uc774\ub2e4. \ud558\ub098\ub9cc \uc815\ub2f5\uc73c\ub85c \uace0\ub97c \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uc2e4\uc81c\ub85c \ub204\uad70\uac00\ub97c \uc783\uc740 \uc0ac\ub78c\uc5d0\uac8c \ub354 \ucc38\uc558\uc5b4\uc57c \ud588\ub2e4\ub294 \uad50\ud6c8\uc744 \ub4e4\uc774\ubc00 \uc774\uc57c\uae30\ub294 \uc544\ub2c8\ub2e4. \uc624\ub974\ud398\uc6b0\uc2a4\uc758 \ub178\ub798\uac00 \ubd99\uc7a1\uc73c\ub824 \ud55c \uac83\uc740 \ub204\uad6c\uc5d0\uac8c\ub098 \uc8fc\uc5b4\uc9c8 \uc218 \uc5c6\ub294 \ub450 \ubc88\uc9f8 \uc2dc\uac04\uc774\ub2e4. \uadf8\ub798\uc11c \uc6b0\ub9ac\ub294 \uadf8\uac00 \ub3cc\uc544\ubcfc \uac83\uc744 \uc54c\uba74\uc11c\ub3c4 \ub9e4\ubc88 \uac19\uc740 \uae38\uc744 \ub530\ub77c\uac04\ub2e4. \uc774\ubc88\ub9cc\ud07c\uc740 \uc870\uae08 \ub354 \uac78\uc5b4 \uc8fc\uae30\ub97c \ubc14\ub77c\uba74\uc11c."}, {"id": "oz-wizard-road-and-home", "title": "\uc624\uc988\uc758 \ub9c8\ubc95\uc0ac \u2014 \ud544\uc694\ud55c \uac83\uc740 \uc774\ubbf8 \uae38 \uc704\uc5d0 \uc788\uc5c8\uc744\uae4c", "summary": "\uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \ub530\ub77c\uac00\uba70 \uc9d1\uc73c\ub85c \ub3cc\uc544\uac00\ub294 \ubaa8\ud5d8\uacfc \ub3d9\ub8cc\ub4e4\uc758 \ubcc0\ud654\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/oz-wizard-road-and-home/index.html", "image": "../media/oz-wizard-road-and-home.png", "alt": "\ub178\ub780 \ubcbd\ub3cc\uae38\uc744 \ud568\uaed8 \uac77\ub294 \ub3c4\ub85c\uc2dc\uc640 \ud1a0\ud1a0, \ud5c8\uc218\uc544\ube44, \uc591\ucca0 \ub098\ubb34\uafbc\uacfc \uc0ac\uc790\ub97c \uadf8\ub9b0 \uc0c1\uc0c1 \uc0bd\ud654.", "text": "\uc624\uc988\uc758 \ub9c8\ubc95\uc0ac \u2014 \ud544\uc694\ud55c \uac83\uc740 \uc774\ubbf8 \uae38 \uc704\uc5d0 \uc788\uc5c8\uc744\uae4c \ub3c4\ub85c\uc2dc\uc640 \uc138 \ub3d9\ub8cc\uac00 \ucc3e\uc544 \ub098\uc120 \uc9c0\ud61c\uc640 \ub9c8\uc74c, \uc6a9\uae30 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \ub530\ub77c\uac00\uba70 \uc9d1\uc73c\ub85c \ub3cc\uc544\uac00\ub294 \ubaa8\ud5d8\uacfc \ub3d9\ub8cc\ub4e4\uc758 \ubcc0\ud654\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \uc9d1\uc774 \ud1b5\uc9f8\ub85c \ubc14\ub78c\uc5d0 \uc2e4\ub824 \ub0af\uc120 \ub098\ub77c\uc5d0 \ub0b4\ub824\uc549\ub294\ub2e4. \uce94\uc790\uc2a4\uc5d0\uc11c \uc0b4\ub358 \ub3c4\ub85c\uc2dc\uc5d0\uac8c \ud544\uc694\ud55c \uac83\uc740 \uac70\ub300\ud55c \ud798\uc774\ub098 \uc655\uad00\uc774 \uc544\ub2c8\ub2e4. \uc775\uc219\ud55c \uc9d1\uc73c\ub85c \ub3cc\uc544\uac00\ub294 \uae38\uc774\ub2e4. \uadf8\ub7f0\ub370 \uadf8 \uae38\uc5d0\uc11c \ub9cc\ub09c \ub3d9\ub8cc\ub4e4\uc740 \uc800\ub9c8\ub2e4 \uc790\uc2e0\uc5d0\uac8c \uaf2d \uc5c6\ub294 \uac83\uc774 \ud558\ub098\uc529 \uc788\ub2e4\uace0 \ub9d0\ud55c\ub2e4. L. \ud504\ub7ad\ud06c \ubc14\uc6c0\uc758 \u300e\uc624\uc988\uc758 \ub9c8\ubc95\uc0ac\u300f\ub294 1900\ub144 \uc11c\ubb38\uc744 \uac00\uc9c4 \ubaa8\ud5d8 \uc774\uc57c\uae30\ub2e4. \uc5b4\ub9b0\uc774\ub97c \uc704\ud55c \uc791\ud488\uc774\uc9c0\ub9cc \uc5b4\ub978\uc774 \uc77d\uc5b4\ub3c4 \ub0a8\ub294 \uc9c8\ubb38\uc774 \uc788\ub2e4. \ub0b4\uac00 \uc5c6\ub2e4\uace0 \uc0dd\uac01\ud558\ub294 \ub2a5\ub825\uc744 \ub2e4\ub978 \uc0ac\ub78c\uc740 \uc774\ubbf8 \ub0b4 \ud589\ub3d9\uc5d0\uc11c \ubcf4\uace0 \uc788\ub294 \uac83\uc740 \uc544\ub2d0\uae4c. \uc544\ub798\uc5d0\ub294 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4. \ud68c\uc624\ub9ac\ubc14\ub78c\uc5d0 \ub0a0\ub824 \uc628 \uc9d1\uc740 \ub3d9\ucabd\uc758 \ub098\uc05c \ub9c8\ub140 \uc704\uc5d0 \ub5a8\uc5b4\uc9c4\ub2e4. \ub3c4\ub85c\uc2dc\ub294 \ub9c8\ub140\uc758 \uc740\uad6c\ub450\ub97c \uc5bb\uace0, \uc5d0\uba54\ub784\ub4dc \uc2dc\uc758 \uc704\ub300\ud55c \uc624\uc988\ub97c \ucc3e\uc544\uac00\uba74 \uc9d1\uc73c\ub85c \ub3cc\uc544\uac08 \ubc29\ubc95\uc744 \uc54c \uc218 \uc788\uc73c\ub9ac\ub77c\ub294 \ub9d0\uc744 \ub4e3\ub294\ub2e4. \ud1a0\ud1a0\uc640 \ud568\uaed8 \ub178\ub780 \ubcbd\ub3cc\uae38\uc744 \ub530\ub77c \ub098\uc11c\ub294 \uc774\uc720\ub2e4. \uc6d0\uc791\uc758 \uad6c\ub450\ub294 \uc740\uc0c9\uc774\ub2e4. \ub2e4\ub978 \uac01\uc0c9\uc5d0\uc11c \uc775\uc219\ud574\uc9c4 \ubaa8\uc2b5\uacfc \uad6c\ubcc4\ud558\uba74 \uc791\uc740 \ubb3c\uac74 \ud558\ub098\ub3c4 \uc0c8\ub86d\uac8c \ubcf4\uc778\ub2e4. \ub2e4\ub9cc \uc0c9\uc744 \uc678\uc6b0\ub294 \uac83\uc774 \uac10\uc0c1\uc758 \ubaa9\uc801\uc740 \uc544\ub2c8\ub2e4. \ub0af\uc120 \uc138\uacc4\uc5d0 \ub4e4\uc5b4\uc628 \uc18c\ub140\uac00 \ub3c4\uc6c0\uc744 \uad6c\ud558\uba70 \ud55c \uac78\uc74c\uc529 \uc6c0\uc9c1\uc774\uae30 \uc2dc\uc791\ud588\ub2e4\ub294 \uc810\uc774 \uc774\uc57c\uae30\uc758 \ucd9c\ubc1c\uc774\ub2e4. \ud5c8\uc218\uc544\ube44\ub294 \uc790\uc2e0\uc5d0\uac8c \ub1cc\uac00 \uc5c6\uc5b4\uc11c \uc9c0\ud61c\ub86d\uc9c0 \ubabb\ud558\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4. \uc624\uc988\uc5d0\uac8c \ub1cc\ub97c \ub2ec\ub77c\uace0 \uccad\ud558\ub824\uace0 \ub3c4\ub85c\uc2dc\uc640 \ub3d9\ud589\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uae38\uc5d0\uc11c \uc704\ud5d8\uc744 \ud53c\ud558\uace0 \ubb38\uc81c\ub97c \ud480\uc5b4\uc57c \ud560 \ub54c \uadf8\ub294 \uc5ec\ub7ec \uc0dd\uac01\uc744 \ub0b4\ub193\ub294\ub2e4. \uc2a4\uc2a4\ub85c\uc758 \ud3c9\uac00\uc640 \uc2e4\uc81c \ud589\ub3d9 \uc0ac\uc774\uc5d0 \ud2c8\uc774 \uc0dd\uae34\ub2e4. \uc791\ud488\uc740 \u2018\uc0ac\uc2e4\uc740 \ub611\ub611\ud588\ub2e4\u2019\uace0 \uc124\uba85\ud558\uace0 \uace7\ubc14\ub85c \ub05d\ub0b4\uc9c0 \uc54a\ub294\ub2e4. \ub3c5\uc790\uac00 \ud5c8\uc218\uc544\ube44\uc758 \ub9d0\uc744 \ub4e3\uace0, \uc774\uc5b4\uc9c0\ub294 \ud589\ub3d9\uc744 \uc5ec\ub7ec \ubc88 \ubcf4\uac8c \ud55c\ub2e4. \ub204\uad70\uac00\ub97c \uc774\ud574\ud558\ub294 \ub370\uc5d0\ub294 \uadf8 \uc0ac\ub78c\uc774 \uc790\uae30\uc18c\uac1c\uc5d0\uc11c \ub9d0\ud55c \ubd80\uc871\ud568\ubfd0 \uc544\ub2c8\ub77c \uc2e4\uc81c\ub85c \uc5b4\ub5bb\uac8c \ubb38\uc81c\ub97c \ub300\ud558\ub294\uc9c0\ub3c4 \uc911\uc694\ud558\ub2e4\ub294 \uc77d\uae30\uac00 \uac00\ub2a5\ud574\uc9c4\ub2e4. \uc591\ucca0 \ub098\ubb34\uafbc\uc740 \uc2ec\uc7a5\uc744 \uc6d0\ud55c\ub2e4. \uc790\uc2e0\uc5d0\uac8c \ub530\ub73b\ud55c \ub9c8\uc74c\uc774 \uc5c6\ub2e4\uace0 \ub290\ub07c\uae30 \ub54c\ubb38\uc774\ub2e4. \uadf8\ub7f0\ub370 \uadf8\ub294 \ub2e4\ub978 \uc0dd\uba85\uc744 \uac71\uc815\ud558\uace0 \ub0a8\uc5d0\uac8c \ud574\ub97c \ub07c\uce60\uae4c \uc870\uc2ec\ud55c\ub2e4. \ubab8\uc774 \uc591\ucca0\ub85c \ub418\uc5b4 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ud0c0\uc778\uc744 \ub300\ud558\ub294 \ud0dc\ub3c4\ub294 \uac19\uc740 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc2ec\uc7a5\uc740 \ubab8\uc18d\uc758 \ubb3c\uac74\uc774\uba74\uc11c \uc0ac\ub791\ud558\uace0 \ub3cc\ubcfc \uc218 \uc788\ub2e4\ub294 \ud655\uc2e0\uc758 \uc0c1\uc9d5\ucc98\ub7fc \uc77d\ud78c\ub2e4. \ud5c8\uc218\uc544\ube44\uac00 \ub1cc\ub97c \ubc14\ub77c\ub294 \uac83\uacfc \ub098\ub780\ud788 \ubcf4\uba74 \ub3d9\ub8cc\ub4e4\uc758 \uc18c\ub9dd\uc774 \uc11c\ub85c \ub2e4\ub978 \uc9c8\ubb38\uc744 \uaebc\ub0b8\ub2e4. \ubb34\uc5c7\uc744 \uac00\uc84c\ub2e4\ub294 \uc99d\uba85\uacfc \uc2e4\uc81c\ub85c \uadf8\ub807\uac8c \uc0b4\uc544\uac00\ub294 \uc77c\uc740 \uc5b4\ub5a4 \uad00\uacc4\uc5d0 \uc788\uc744\uae4c. \uc0ac\uc790\ub294 \uc790\uc2e0\uc774 \uac81\uc7c1\uc774\ub77c\uace0 \ub9d0\ud55c\ub2e4. \uac15\ud55c \ubab8\uacfc \ud070 \ubaa9\uc18c\ub9ac\uac00 \uc788\uc73c\ub2c8 \ub450\ub824\uc6c0\ub3c4 \uc5c6\uc5b4\uc57c \ud55c\ub2e4\uace0 \uae30\ub300\ud558\uc9c0\ub9cc \uc2e4\uc81c\ub85c\ub294 \uadf8\ub807\uc9c0 \uc54a\ub2e4. \uadf8\ub294 \uc624\uc988\uc5d0\uac8c \uc6a9\uae30\ub97c \uc5bb\uace0 \uc2f6\uc5b4 \ud55c\ub2e4. \uc790\uae30\uc5d0\uac8c \ubaa8\uc790\ub780 \uac83\uc744 \ub2e4\ub978 \uc874\uc7ac\uac00 \ucc44\uc6cc \uc904 \uc218 \uc788\ub2e4\uace0 \ubbff\ub294 \uc148\uc774\ub2e4. \uc5ec\ud589\uc774 \uc774\uc5b4\uc9c0\uba74 \uc0ac\uc790\ub294 \ub450\ub824\uc6c0\uc744 \ub290\ub07c\uba74\uc11c\ub3c4 \ub3d9\ub8cc\ub4e4\uc744 \uc704\ud574 \ud589\ub3d9\ud55c\ub2e4. \uadf8\ub798\uc11c \uc6a9\uae30\ub294 \uc544\ubb34\uac83\ub3c4 \ubb34\uc12d\uc9c0 \uc54a\uc740 \uc0c1\ud0dc\ub9cc\uc744 \ub73b\ud558\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uc774 \uc5ed\uc2dc \uc791\ud488\uc774 \ud604\ub300\uc758 \uc2ec\ub9ac\ud559 \uc774\ub860\uc744 \uc124\uba85\ud558\ub824 \uc37c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc778\ubb3c\uc758 \ub9d0\uacfc \ud589\ub3d9\uc744 \ube44\uad50\ud558\uba70 \uc5bb\uc744 \uc218 \uc788\ub294 \uac10\uc0c1\uc758 \ud55c \ubc29\ud5a5\uc774\ub2e4. \uc5d0\uba54\ub784\ub4dc \uc2dc\uc5d0 \ub3c4\ucc29\ud574\ub3c4 \uc18c\uc6d0\uc740 \ubc14\ub85c \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uc624\uc988\ub294 \uc11c\ucabd\uc758 \ub098\uc05c \ub9c8\ub140\ub97c \ubb3c\ub9ac\uce58\ub77c\ub294 \uc870\uac74\uc744 \ub0b4\uac74\ub2e4. \ub3c4\uc6c0\uc744 \ubc1b\uc73c\ub824\uba74 \uc774\ubbf8 \ub450\ub824\uc6cc\ud558\ub358 \uc77c\uc744 \ud574\ub0b4\uc57c \ud558\ub294 \uc0c1\ud669\uc774\ub2e4. \uac89\uc73c\ub85c\ub294 \ud798\uc5c6\ub294 \uc0ac\ub78c\ub4e4\uc774 \uac70\ub300\ud55c \uad8c\uc704\ub97c \ucc3e\uc544\uac14\uc9c0\ub9cc, \uc2e4\uc81c\ub85c \uae38 \uc704\uc5d0\uc11c \uc704\ud5d8\uc744 \uac10\ub2f9\ud558\ub294 \uac83\uc740 \uc774 \ub3d9\ub8cc\ub4e4\uc774\ub2e4. \uc11c\ucabd \ub9c8\ub140\uc758 \uc190\uc5d0 \ubd99\uc7a1\ud78c \ub4a4 \ub3c4\ub85c\uc2dc\ub294 \ub73b\ubc16\uc758 \ubc29\uc2dd\uc73c\ub85c \ubc97\uc5b4\ub09c\ub2e4. \ubb3c\uc774 \ub9c8\ub140\ub97c \ub179\uc774\ub294 \uacb0\ub9d0\uc774\ub2e4. \uc774\ub97c \uce58\ubc00\ud558\uac8c \uacc4\ud68d\ud55c \uc601\uc6c5\uc758 \uc2b9\ub9ac\ub77c\uace0\ub9cc \uc77d\uae30\ubcf4\ub2e4, \ub0af\uc120 \uc138\uacc4\uc5d0\uc11c \ubab0\ub790\ub358 \uc870\uac74\uc744 \uacbd\ud5d8\ud558\uba70 \uae38\uc774 \uc5f4\ub9ac\ub294 \ubaa8\ud5d8\uc758 \uc131\uaca9\uc73c\ub85c \ubcfc \uc218 \uc788\ub2e4. \ub3cc\uc544\uc628 \ub3d9\ub8cc\ub4e4\uc740 \uc624\uc988\uc758 \uc815\uccb4\ub97c \uc54c\uac8c \ub41c\ub2e4. \ubb34\uc11c\uc6b4 \ubaa8\uc2b5\uacfc \uac70\ub300\ud55c \uad8c\uc704 \ub4a4\uc5d0 \uc788\uc5c8\ub358 \uac83\uc740 \uc0ac\ub78c\ub4e4\uc774 \uae30\ub300\ud55c \ucd08\uc6d4\uc801 \uc874\uc7ac\uc640 \ub2e4\ub978 \ud3c9\ubc94\ud55c \uc0ac\ub78c\uc774\uc5c8\ub2e4. \uadf8\uac00 \ubcf4\uc5ec \uc900 \uc704\uc5c4\uacfc \uc2e4\uc81c \ub2a5\ub825\uc758 \uac04\uaca9\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \ud558\uc9c0\ub9cc \uc774 \uc7a5\uba74\uc774 \ubaa8\ub4e0 \ub3c4\uc6c0\uc740 \uac70\uc9d3\uc774\ub77c\ub294 \uacb0\ub860\uc73c\ub85c\ub9cc \uc774\uc5b4\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud5c8\uc218\uc544\ube44\uc640 \ub098\ubb34\uafbc, \uc0ac\uc790\uc5d0\uac8c \uc8fc\ub294 \ubb3c\uac74\uacfc \ub9d0\uc740 \uadf8\ub4e4\uc774 \uc790\uc2e0\uc744 \ubc14\ub77c\ubcf4\ub294 \ubc29\uc2dd\uc744 \ubc14\uafb8\uae30\ub3c4 \ud55c\ub2e4. \uc774\ubbf8 \ud589\ub3d9\uc73c\ub85c \ubcf4\uc5ec \uc900 \ub2a5\ub825\uc744 \uc2a4\uc2a4\ub85c \uc778\uc815\ud558\ub824\uba74 \uc5b4\ub5a4 \uacc4\uae30\uac00 \ud544\uc694\ud55c\uac00\ub77c\ub294 \uc9c8\ubb38\uc774 \ub0a8\ub294\ub2e4. \uc624\uc988\uac00 \uc900\ube44\ud55c \uae30\uad6c\ub85c \ud568\uaed8 \ub5a0\ub098\ub824\ub358 \uacc4\ud68d\uc740 \uc5b4\uae0b\ub098\uace0, \ub3c4\ub85c\uc2dc\ub294 \ub2e4\uc2dc \uae38\uc744 \ucc3e\uc544\uc57c \ud55c\ub2e4. \ub05d\ub0b4 \uae00\ub9b0\ub2e4\ub97c \ub9cc\ub098 \uc740\uad6c\ub450\uac00 \uac00\uc9c4 \ud798\uc744 \uc54c\uac8c \ub41c\ub2e4. \uc9d1\uc73c\ub85c \ub3cc\uc544\uac08 \uc218 \uc788\ub294 \ubb3c\uac74\uc740 \uc0dd\uac01\ubcf4\ub2e4 \uc77c\ucc0d\ubd80\ud130 \uacc1\uc5d0 \uc788\uc5c8\uc9c0\ub9cc \uadf8 \uc0ac\uc2e4\uc744 \uc54c\uae30\uae4c\uc9c0 \uae34 \uc5ec\ud589\uc774 \ud544\uc694\ud588\ub2e4. \uc774\uac83\uc744 \ubaa8\ud5d8 \uc804\uccb4\uac00 \uc4f8\ub370\uc5c6\uc5c8\ub2e4\ub294 \ub73b\uc73c\ub85c \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5ec\ud589\ud558\ub294 \ub3d9\uc548 \ub3d9\ub8cc\ub4e4\uc774 \uc0dd\uae30\uace0 \uac01\uc790\uc758 \ubaa8\uc2b5\uc744 \ubcf4\uac8c \ub41c\ub2e4. \uc6d0\ud558\ub294 \uacb0\uacfc\uc5d0 \uac00\uc7a5 \ube68\ub9ac \ub3c4\ucc29\ud558\ub294 \uae38\uacfc, \uadf8 \uc0ac\uc774 \uc0ac\ub78c\uc744 \ub9cc\ub098\uace0 \ub2ec\ub77c\uc9c0\ub294 \uc2dc\uac04\uc740 \uc11c\ub85c \ub2e4\ub978 \uac00\uce58\ub97c \uac00\uc9c8 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \ub3c4\ub85c\uc2dc\uc640 \ud1a0\ud1a0, \uc138 \ub3d9\ub8cc\uac00 \uae38\uc744 \uac77\ub294 \ubaa8\uc2b5\uc744 \uc0c8\ub85c \uc0c1\uc0c1\ud55c AI \uc0bd\ud654\ub2e4. \uc6d0\uc791\uc5d0 \uc2e4\ub9b0 \uc61b \uadf8\ub9bc\uc774\ub098 \ud2b9\uc815 \uc601\ud654\uc758 \uc7a5\uba74\uc744 \ubcf5\uc81c\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc774\ub4e4\uc774 \ud568\uaed8 \uc6c0\uc9c1\uc774\ub294 \ubaa8\uc2b5\uc774 \uae00\ub85c \ub4e4\uc5b4\uac00\ub294 \uc785\uad6c\uac00 \ub418\ub3c4\ub85d \ub9cc\ub4e4\uc5c8\ub2e4. \uc791\ud488\uc744 \uc77d\uace0 \ub098\uba74 \ub204\uac00 \uac00\uc7a5 \uac15\ud588\ub294\uc9c0 \uace0\ub974\ub294 \ub300\uc2e0 \uac01\uc790\uac00 \uc5b4\ub5a4 \uc21c\uac04\uc5d0 \ub2e4\ub978 \uc774\ub97c \ub3c4\uc654\ub294\uc9c0 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ub1cc\uc640 \uc2ec\uc7a5, \uc6a9\uae30\ub77c\ub294 \uc18c\ub9dd\uc740 \uacb0\uad6d \uae38 \uc704\uc758 \uad6c\uccb4\uc801\uc778 \ud589\ub3d9\uacfc \uc774\uc5b4\uc9c4\ub2e4. \uc9d1\uc73c\ub85c \ub3cc\uc544\uac00\ub294 \uc774\uc57c\uae30 \uc548\uc5d0, \uc790\uc2e0\uc744 \uc870\uae08 \ub2e4\ub974\uac8c \ubcf4\uac8c \ub418\ub294 \uc774\uc57c\uae30\ub3c4 \ud568\uaed8 \ub193\uc5ec \uc788\ub2e4."}, {"id": "pandora-jar-hope-under-lid", "title": "\ud310\ub3c4\ub77c \u2014 \uc0c1\uc790\uac00 \uc544\ub2c8\ub77c \ud56d\uc544\ub9ac\uc600\ub2e4\ub294 \uc774\uc57c\uae30", "summary": "\ud5e4\uc2dc\uc624\ub3c4\uc2a4\uc758 \u300e\uc77c\uacfc \ub0a0\u300f\uc744 \ub530\ub77c \ud56d\uc544\ub9ac\uc640 \ud76c\ub9dd, \ud6c4\ub300\uc758 \uc775\uc219\ud55c \uc124\uba85\uc744 \uad6c\ubd84\ud569\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc2e0\ud654\uc640 \ubbfc\uc18d", "categories": ["arts"], "url": "stories/pandora-jar-hope-under-lid/index.html", "image": "../media/pandora-jar-hope-under-lid.png", "alt": "\ud070 \ud56d\uc544\ub9ac\uc758 \ub69c\uaed1\uc744 \uc5f0 \ud310\ub3c4\ub77c\uc640 \ud758\ub7ec\ub098\uc624\ub294 \uc5b4\ub450\uc6b4 \uae30\uc6b4\uc744 \uadf8\ub9b0 \uc2e0\ud654 \uc0bd\ud654", "text": "\ud310\ub3c4\ub77c \u2014 \uc0c1\uc790\uac00 \uc544\ub2c8\ub77c \ud56d\uc544\ub9ac\uc600\ub2e4\ub294 \uc774\uc57c\uae30 \ub9c8\uc9c0\ub9c9\uc5d0 \ub0a8\uc740 \ud76c\ub9dd\uc740 \uc120\ubb3c\uc774\uc5c8\uc744\uae4c, \ud480\ub9ac\uc9c0 \uc54a\uc740 \uc9c8\ubb38\uc77c\uae4c \ud5e4\uc2dc\uc624\ub3c4\uc2a4\uc758 \u300e\uc77c\uacfc \ub0a0\u300f\uc744 \ub530\ub77c \ud56d\uc544\ub9ac\uc640 \ud76c\ub9dd, \ud6c4\ub300\uc758 \uc775\uc219\ud55c \uc124\uba85\uc744 \uad6c\ubd84\ud569\ub2c8\ub2e4. \uc2e0\ud654\uc640 \ubbfc\uc18d \ubb38\ud654\uc640 \uc608\uc220 \ud310\ub3c4\ub77c\uc758 \uc0c1\uc790\ub77c\ub294 \ub9d0\uc740 \ub108\ubb34 \uc775\uc219\ud574\uc11c \uadf8 \uc548\uc758 \ubb3c\uac74\uae4c\uc9c0 \uc774\ubbf8 \ubcf8 \ub4ef\ud558\ub2e4. \uc5f4\uc5b4\uc11c\ub294 \uc548 \ub418\ub294 \uc0c1\uc790\ub97c \ud638\uae30\uc2ec\uc5d0 \uc5f4\uc5c8\uace0, \uc628\uac16 \uc7ac\uc559\uc774 \ub098\uac04 \ub4a4 \ud76c\ub9dd\ub9cc \ub0a8\uc558\ub2e4\ub294 \uc774\uc57c\uae30\ub2e4. \uadf8\ub7f0\ub370 \ud5e4\uc2dc\uc624\ub3c4\uc2a4\uc758 \uc2dc\ub97c \uc77d\uc73c\uba74 \uc190\uc548\uc758 \uc791\uc740 \uc0c1\uc790\uac00 \uc544\ub2c8\ub77c \ud070 \ud56d\uc544\ub9ac\uac00 \ub098\uc628\ub2e4. \uc774 \ucc28\uc774\ub294 \uc0ac\uc18c\ud55c \uc18c\ud488 \ubb38\uc81c\uac00 \uc544\ub2c8\ub2e4. \uc6b0\ub9ac\uac00 \uc624\ub798\ub41c \uc774\uc57c\uae30\ub77c\uace0 \uae30\uc5b5\ud558\ub294 \uac83\uc774 \uc5b4\ub290 \ud310\ubcf8\uc758 \uc5b4\ub5a4 \uc124\uba85\uc778\uc9c0 \uc0b4\ud3b4\ubcf4\uac8c \ud55c\ub2e4. \uc5ec\uae30\uc11c\ub294 \u300e\uc77c\uacfc \ub0a0\u300f\uc758 \ud310\ub3c4\ub77c \ub300\ubaa9\uc744 H. G. \uc5d0\ubc8c\ub9b0\ud654\uc774\ud2b8\uc758 \uc601\uc5b4 \ubc88\uc5ed\uc73c\ub85c \uc77d\uace0, \uc904\uac70\ub9ac\uc640 \ub9c8\uc9c0\ub9c9\uc758 \uc9c8\ubb38\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc2dc\uc5d0\uc11c \ud310\ub3c4\ub77c\uac00 \ub4f1\uc7a5\ud558\ub294 \ubc30\uacbd\uc740 \uc81c\uc6b0\uc2a4\uc640 \ud504\ub85c\uba54\ud14c\uc6b0\uc2a4\uc758 \ub2e4\ud23c\uc774\ub2e4. \uc778\uac04\uc5d0\uac8c \ubd88\uc744 \uac00\uc838\uc628 \uc77c\uc740 \uc2e0\ub4e4\uc758 \ub73b\uc5d0 \ub9de\uc120 \ud589\ub3d9\uc774 \ub418\uace0, \uc81c\uc6b0\uc2a4\ub294 \uadf8\uc5d0 \ub300\ud55c \ub300\uac00\ub97c \ub9c8\ub828\ud55c\ub2e4. \ud310\ub3c4\ub77c\ub294 \ud63c\uc790 \uae38\uc744 \uac00\ub2e4\uac00 \uc6b0\uc5f0\ud788 \uc704\ud5d8\ud55c \ubb3c\uac74\uc744 \ubc1c\uacac\ud55c \uc778\ubb3c\uc774 \uc544\ub2c8\ub2e4. \ucc98\uc74c\ubd80\ud130 \uad8c\ub825\uc744 \uac00\uc9c4 \uc2e0\uc758 \uacc4\ud68d \uc18d\uc5d0\uc11c \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4. \uadf8\ub7ec\ubbc0\ub85c \uc138\uc0c1\uc758 \uace0\ud1b5\uc774 \ud55c \uc5ec\uc790\uc758 \ud638\uae30\uc2ec \ub54c\ubb38\uc5d0 \uc2dc\uc791\ub418\uc5c8\ub2e4\uace0\ub9cc \uc124\uba85\ud558\uba74 \uadf8 \uc55e\uc758 \uacb0\uc815\uacfc \uc758\ub3c4\uac00 \uc9c0\uc6cc\uc9c4\ub2e4. \ub204\uac00 \uc0c1\ud669\uc744 \ub9cc\ub4e4\uc5c8\ub294\uc9c0\uae4c\uc9c0 \ud568\uaed8 \uc77d\uc5b4\uc57c \uc774\uc57c\uae30\uc758 \ud798\uc758 \uad00\uacc4\uac00 \ubcf4\uc778\ub2e4. \uc2dc\uac00 \uc5b4\ub514\uc5d0\uc11c \ucc45\uc784\uc744 \ub9d0\ud558\uace0 \ubb34\uc5c7\uc744 \ub2f9\uc5f0\ud558\uac8c \uc5ec\uae30\ub294\uc9c0\ub3c4 \uc0b4\ud544 \uc218 \uc788\ub2e4. \ud5e4\ud30c\uc774\uc2a4\ud1a0\uc2a4\uac00 \ud759\uacfc \ubb3c\ub85c \uc0ac\ub78c\uc758 \ud615\uc0c1\uc744 \ub9cc\ub4e4\uace0, \ub2e4\ub978 \uc2e0\ub4e4\uc740 \uae30\uc220\uacfc \uc544\ub984\ub2e4\uc6c0, \uc7a5\uc2dd\uacfc \ub9d0 \uac19\uc740 \uc5ec\ub7ec \uc694\uc18c\ub97c \ubcf4\ud0e0\ub2e4. \ud310\ub3c4\ub77c\uc758 \uc774\ub984\ub3c4 \uc5ec\ub7ec \uc2e0\uc774 \uc900 \uc120\ubb3c\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc124\uba85\ub41c\ub2e4. \ud654\ub824\ud55c \ub4f1\uc7a5\uc740 \uc790\ubc1c\uc801\uc778 \ucd95\ud558\ub9cc\uc774 \uc544\ub2c8\ub77c \uc81c\uc6b0\uc2a4\uac00 \uc900\ube44\ud55c \uacc4\ud68d\uc758 \ud55c \ubd80\ubd84\uc774\ub2e4. \uc5ec\uae30\uc5d0\ub294 \uc5ec\uc131\uc744 \ub0a8\uc131\uc5d0\uac8c \ub2e5\uce58\ub294 \uc7ac\uc559\uc73c\ub85c \ubcf4\ub294 \uace0\ub300 \uc2dc\uc758 \uc2dc\uc120\ub3c4 \ubd84\uba85\ud788 \ub0a8\uc544 \uc788\ub2e4. \uadf8 \ud45c\ud604\uc744 \uc61b\uc774\uc57c\uae30\ub2c8\uae4c \uadf8\ub300\ub85c \uc633\ub2e4\uace0 \ubc1b\uc544\ub4e4\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \ub3d9\uc2dc\uc5d0 \uc6d0\ub798 \uc2dc\uac00 \uadf8\ub7f0 \uae34\uc7a5\uc744 \ud488\uace0 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc9c0\uc6b0\uace0 \ucc98\uc74c\ubd80\ud130 \ud604\ub300\uc801\uc778 \ud3c9\ub4f1\uc758 \uc774\uc57c\uae30\uc600\ub2e4\uace0 \ubc14\uafb8\uc5b4\uc11c\ub3c4 \uc548 \ub41c\ub2e4. \uc77d\uae30\uc640 \ub3d9\uc758\ub294 \ub2e4\ub974\ub2e4. \ud504\ub85c\uba54\ud14c\uc6b0\uc2a4\ub294 \ud615\uc81c \uc5d0\ud53c\uba54\ud14c\uc6b0\uc2a4\uc5d0\uac8c \uc81c\uc6b0\uc2a4\uc758 \uc120\ubb3c\uc744 \ubc1b\uc544\ub4e4\uc774\uc9c0 \ub9d0\ub77c\uace0 \uacbd\uace0\ud55c\ub2e4. \ud558\uc9c0\ub9cc \uadf8\ub294 \ud310\ub3c4\ub77c\ub97c \ubc1b\uc544\ub4e4\uc778\ub2e4. \uc77c\uc774 \ubc8c\uc5b4\uc9c4 \ub4a4\uc5d0\uc57c \uadf8 \uc758\ubbf8\ub97c \uae68\ub2eb\ub294\ub2e4. \uc774\ubbf8 \ub4e4\uc5b4\uc628 \uc120\ubb3c\uc744 \ub0b4\ubcf4\ub0b4\ub294 \ub370\uc5d0\ub294 \ucc98\uc74c\ubd80\ud130 \ubc1b\uc9c0 \uc54a\ub294 \uac83\uacfc \ub2e4\ub978 \uc5b4\ub824\uc6c0\uc774 \uc788\ub2e4. \ud310\ub3c4\ub77c\uc5d0\uac8c\ub9cc \uc2dc\uc120\uc744 \uace0\uc815\ud558\uba74 \uc774 \ub0a8\uc131 \uc778\ubb3c\uc758 \ud310\ub2e8\ub3c4 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uacbd\uace0\ub97c \uc54c\uace0 \uc788\ub358 \uc0ac\ub78c\uc740 \ub204\uad6c\uc600\uace0, \ubc1b\uc544\ub4e4\uc778 \uc0ac\ub78c\uc740 \ub204\uad6c\uc600\ub294\uc9c0 \uc2dc\ub294 \ud568\uaed8 \ub9d0\ud55c\ub2e4. \uc774\uc57c\uae30\uc758 \uc778\uacfc\uad00\uacc4\ub97c \ub530\ub77c\uac00\ub294 \uc77c\uc740 \uc775\uc219\ud55c \uc8fc\uc778\uacf5 \ud558\ub098\uc5d0\uac8c \ubaa8\ub4e0 \uc5ed\ud560\uc744 \ubab0\uc544\uc8fc\uc9c0 \uc54a\ub294 \uc77c\uc774\uae30\ub3c4 \ud558\ub2e4. \uc2dc\ub294 \uc778\uac04\ub4e4\uc774 \uc774\uc804\uc5d0\ub294 \uc2ec\ud55c \uace0\ud1b5\uacfc \ud798\uaca8\uc6b4 \ub178\ub3d9, \ubcd1\uc5d0\uc11c \uba40\ub9ac \uc0b4\uc558\ub2e4\uace0 \ub4e4\ub824\uc900\ub2e4. \ud310\ub3c4\ub77c\uac00 \ud070 \ud56d\uc544\ub9ac\uc758 \ub69c\uaed1\uc744 \ub4e4\uc5b4 \uc62c\ub9ac\uc790 \uadf8 \uc548\uc758 \uac83\ub4e4\uc774 \uc138\uc0c1\uc73c\ub85c \ud37c\uc9c4\ub2e4. \uc778\uac04\uc758 \uc0b6\uc774 \uc65c \uc774\ub807\uac8c \uace0\ub2e8\ud55c\uc9c0 \uc124\uba85\ud558\ub294 \uc804\uc2b9\uc758 \ubc29\uc2dd\uc774\ub2e4. \ubcd1\uacfc \ub178\ub3d9\uc774 \ub4f1\uc7a5\ud558\ub294 \uc7a5\uba74\uc740 \ub3c5\uc790\uc758 \uc77c\uc0c1\uacfc\ub3c4 \uc774\uc5b4\uc9c4\ub2e4. \ub2e4\ub9cc \ud56d\uc544\ub9ac\uc758 \ub0b4\uc6a9\uc744 \uc2e4\uc81c \uc9c8\ubcd1\uc758 \uc6d0\uc778\uc774\ub098 \uc5ec\uc131\uc758 \ubcf8\uc131\uc5d0 \ub300\ud55c \uc99d\uac70\ub85c \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uc2e0\ud654\ub294 \uace0\ud1b5\uc758 \uae30\uc6d0\uc744 \uc774\uc57c\uae30\ub85c \ub2e4\ub8e8\ub294 \uac83\uc774\uc9c0 \uc758\ud559\uacfc \uc0ac\ud68c\uc758 \ubaa8\ub4e0 \uc6d0\uc778\uc744 \ubc1d\ud600 \ub193\uc740 \ubcf4\uace0\uc11c\uac00 \uc544\ub2c8\ub2e4. \uc624\ub298\uc758 \uc9c8\ubb38\uacfc \uc61b \uc2dc\uc758 \uc124\uba85\uc744 \uad6c\ubd84\ud560 \ub54c \uc624\ud788\ub824 \uadf8 \uc2dc\ub300\uc758 \ubd88\uc548\uc744 \ub354 \uc798 \uc77d\uac8c \ub41c\ub2e4. \ud56d\uc544\ub9ac\uc758 \uac00\uc7a5\uc790\ub9ac \uc544\ub798\uc5d0\ub294 \uc5d8\ud53c\uc2a4\uac00 \ub0a8\ub294\ub2e4. \ucc38\uace0\ud55c \ubc88\uc5ed\uc740 \uc774\ub97c Hope, \uace7 \ud76c\ub9dd\uc774\ub77c\uace0 \uc62e\uae34\ub2e4. \ub69c\uaed1\uc774 \ub2e4\uc2dc \ub2eb\ud614\uae30 \ub54c\ubb38\uc5d0 \ubc16\uc73c\ub85c \ub0a0\uc544\uac00\uc9c0 \ubabb\ud55c\ub2e4. \uc2dc\ub294 \uc774 \uc77c\ub3c4 \uc81c\uc6b0\uc2a4\uc758 \ub73b\uacfc \uc5f0\uacb0\ud55c\ub2e4. \ubaa8\ub4e0 \uc7ac\uc559\uc774 \ub098\uac04 \ub4a4 \ubc1d\uc740 \uc874\uc7ac\uac00 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \ub0a0\uc544\uc640 \uc704\ub85c\ud588\ub2e4\ub294 \uc7a5\uba74\uacfc\ub294 \ub2e4\ub974\ub2e4. \ubc14\ub85c \uc774 \uc704\uce58\uac00 \uc9c8\ubb38\uc744 \ub9cc\ub4e0\ub2e4. \ud76c\ub9dd\uc774 \uc548\uc5d0 \ub0a8\uc544 \uc778\uac04 \uacc1\uc5d0 \ubcf4\uad00\ub41c \uac83\uc77c\uae4c, \uc544\ub2c8\uba74 \ubc16\uc73c\ub85c \ub098\uc624\uc9c0 \ubabb\ud574 \uc778\uac04\uc5d0\uac8c \uc8fc\uc5b4\uc9c0\uc9c0 \uc54a\uc740 \uac83\uc77c\uae4c. \ub69c\uaed1\uc774 \ub2eb\ud78c \uc0c1\ud0dc\ub97c \uc5b4\ub5bb\uac8c \uc774\ud574\ud558\ub290\ub0d0\uc5d0 \ub530\ub77c \ub290\ub08c\uc774 \ubc14\ub010\ub2e4. \ubc88\uc5ed\uc5d0\uc11c \ud76c\ub9dd\uc774\ub77c\uace0 \uc77d\uc5c8\ub2e4\ub294 \uac83\uacfc \uadf8 \uc758\ubbf8\ub97c \uc644\uc804\ud788 \ud480\uc5c8\ub2e4\ub294 \uac83\uc740 \uac19\uc740 \ub9d0\uc774 \uc544\ub2c8\ub2e4. \uc6b0\ub9ac\ub294 \ud76c\ub9dd\uc744 \ub300\uccb4\ub85c \uc88b\uc740 \ub73b\uc73c\ub85c \uc4f4\ub2e4. \uc5b4\ub824\uc6b4 \uc2dc\uac04\uc744 \uacac\ub514\uac8c \ud558\uace0 \ub0b4\uc77c\uc744 \uc900\ube44\ud558\uac8c \ud558\ub294 \ud798\uc774\ub2e4. \ud558\uc9c0\ub9cc \uae30\ub300\uac00 \ud604\uc2e4\uc744 \ubcf4\uc9c0 \ubabb\ud558\uac8c \ud558\uac70\ub098 \ub05d\uc5c6\uc774 \uae30\ub2e4\ub9ac\uac8c \ud560 \ub54c\ub3c4 \uc788\ub2e4. \ud310\ub3c4\ub77c\uc758 \ub9c8\uc9c0\ub9c9 \uc7a5\uba74\uc774 \ud6c4\ub300\uc758 \ud574\uc11d\uc744 \ubd88\ub7ec\uc628 \uc774\uc720\ub97c \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub294 \uc9c0\uc810\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc774 \uc2dc\uac00 \uc5b4\ub5a4 \ucca0\ud559\uc801 \ub2f5\uc744 \uba85\ud655\ud558\uac8c \uc815\ud574 \uc8fc\uc5c8\ub2e4\uace0 \ub2e8\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud56d\uc544\ub9ac\uc5d0 \ub0a8\uc740 \uac83\uc758 \uc5ed\ud560\uc744 \ub450\uace0 \uc5ec\ub7ec \ub3c5\ud574\uac00 \uac00\ub2a5\ud558\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uace0\ub300\uc758 \ub2e8\uc5b4\uc640 \uc624\ub298\uc758 \ud55c\uad6d\uc5b4\uac00 \uac00\uc9c4 \ub290\ub08c\ub3c4 \uc644\uc804\ud788 \uac19\uc9c0\ub294 \uc54a\ub2e4. \uc775\uc219\ud55c \ubc88\uc5ed \ud558\ub098\uac00 \ubaa8\ub4e0 \ubb38\uc744 \ub2eb\uc544 \ubc84\ub9ac\uc9c0 \uc54a\ub3c4\ub85d \uc77d\ub294 \ud3b8\uc774 \uc88b\ub2e4. \ub9ce\uc740 \ud604\ub300 \uc7ac\ud654\uc5d0\uc11c\ub294 \ud56d\uc544\ub9ac\uac00 \uc0c1\uc790\uac00 \ub418\uace0, \uae08\uc9c0\uc640 \ud638\uae30\uc2ec\uc774 \uc0ac\uac74\uc758 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ub41c\ub2e4. \uadf8\ub798\uc11c \ud310\ub3c4\ub77c\uc758 \uc0c1\uc790\ub294 \uc190\ub300\uba74 \ub354 \ud070 \ubb38\uc81c\ub97c \ubd80\ub974\ub294 \uc77c\uc744 \ub73b\ud558\ub294 \ub9d0\ub85c \uc4f0\uc778\ub2e4. \uadf8\ub7f0 \ud45c\ud604\uc774 \uc0dd\ud65c \uc18d\uc5d0\uc11c \uc758\ubbf8\ub97c \uc5bb\uc5c8\ub2e4\uace0 \ud574\uc11c \ud5e4\uc2dc\uc624\ub3c4\uc2a4\uc758 \ud574\ub2f9 \ub300\ubaa9\uacfc \ubaa8\ub4e0 \uc138\ubd80\uac00 \uac19\uc544\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774 \uae00\uc740 \uc0c1\uc790\ub85c \ubc14\ub010 \uacfc\uc815\uc744 \ud2b9\uc815 \ud55c \uc0ac\ub78c\uc758 \uc2e4\uc218 \ud558\ub098\ub85c \ud655\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4. \uadf8 \uc124\uba85\uc744 \ud558\ub824\uba74 \ud6c4\ub300 \ubb38\ud5cc\uc744 \ub530\ub85c \ub300\uc870\ud574\uc57c \ud55c\ub2e4. \uc9c0\uae08 \ud655\uc778\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc120\ud0dd\ud55c \uace0\ub300 \uc2dc\uc758 \ubc88\uc5ed\uc5d0\uc11c \ud070 \ud56d\uc544\ub9ac\uc640 \ub69c\uaed1, \ub0a8\uc740 \ud76c\ub9dd\uc774 \uc5b4\ub5bb\uac8c \uc801\ud600 \uc788\ub294\uc9c0\ub2e4. \uc774\uc57c\uae30\uc758 \uc5b4\ub290 \uce35\uc704\ub97c \ub9d0\ud558\ub294\uc9c0 \ubc1d\ud788\uba74 \ud63c\ub3d9\uc744 \uc904\uc77c \uc218 \uc788\ub2e4. \ud310\ub3c4\ub77c\ub97c \ub2e4\uc2dc \uc77d\ub294 \uc7ac\ubbf8\ub294 \uc720\uba85\ud55c \ud45c\ud604\uc744 \ud2c0\ub838\ub2e4\uace0 \uc9c0\uc801\ud558\ub294 \ub370\uc5d0\ub9cc \uc788\uc9c0 \uc54a\ub2e4. \uc120\ubb3c\ucc98\ub7fc \ubcf4\uc774\ub294 \ud568\uc815, \ubbf8\ub9ac \ub4e4\uc740 \uacbd\uace0, \ub204\uad70\uac00\uc5d0\uac8c \ub3cc\uc544\uac04 \ucc45\uc784, \ud76c\ub9dd\uc758 \uc560\ub9e4\ud55c \uc790\ub9ac\uae4c\uc9c0 \uc0dd\uac01\ud560 \uac83\uc774 \ub298\uc5b4\ub09c\ub2e4. \uc9e7\uc740 \uc2e0\ud654 \uc548\uc5d0 \uc778\uac04\uc774 \uace0\ud1b5\uc744 \uc124\uba85\ud574 \uc628 \ubc29\uc2dd\uc774 \uacb9\uccd0 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \ud310\ub3c4\ub77c\uc758 \uc0c1\uc790\ub77c\ub294 \ub9d0\uc744 \ub4e3\ub354\ub77c\ub3c4 \uc77c\uc0c1 \ud45c\ud604\uc744 \uad73\uc774 \ubc14\uafc0 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uadf8 \ub4a4\uc5d0\ub294 \ud070 \ud56d\uc544\ub9ac\ub97c \ub193\uace0 \ub2e4\ub978 \uc9c8\ubb38\uc744 \ud558\ub358 \uc2dc\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uae30\uc5b5\ud558\uba74 \ub41c\ub2e4. \ub9c8\uc9c0\ub9c9\uc5d0 \ub0a8\uc740 \uac83\uc744 \uace7\ubc14\ub85c \uc815\ub2f5\uc73c\ub85c \uaebc\ub0b4\uae30\ubcf4\ub2e4, \uc65c \uadf8\uacf3\uc5d0 \ub0a8\uc544 \uc788\ub294\uc9c0 \uc7a0\uae50 \ubc14\ub77c\ubcf4\ub294 \uac83. \uadf8 \uc5ec\uc720\uac00 \uc624\ub798\ub41c \uc774\uc57c\uae30\ub97c \uc0c8\ub86d\uac8c \uc77d\uac8c \ud55c\ub2e4."}, {"id": "pinocchio-schoolbook-and-responsibility", "title": "\ud53c\ub178\ud0a4\uc624 \u2014 \ucf54\uac00 \uae38\uc5b4\uc9c0\ub294 \uc774\uc57c\uae30 \ub2e4\uc74c\uc5d0\ub294 \ubb34\uc5c7\uc774 \uc788\uc744\uae4c", "summary": "\ucf5c\ub85c\ub514 \uc6d0\uc791\uc758 \uc904\uac70\ub9ac\uc640 \ub3cc\ubd04\uc744 \ubc30\uc6b0\ub294 \ub098\ubb34 \uc778\ud615\uc758 \ubcc0\ud654\uc744 \uc774\uc57c\uae30\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/pinocchio-schoolbook-and-responsibility/index.html", "image": "../media/pinocchio-schoolbook-and-responsibility.png", "alt": "\ub098\ubb34 \uc778\ud615\uacfc \ucc45, \ubaa9\uacf5 \uc791\uc5c5\uc2e4\uc744 \uadf8\ub9b0 \ud53c\ub178\ud0a4\uc624 \uc774\uc57c\uae30 \uc0bd\ud654", "text": "\ud53c\ub178\ud0a4\uc624 \u2014 \ucf54\uac00 \uae38\uc5b4\uc9c0\ub294 \uc774\uc57c\uae30 \ub2e4\uc74c\uc5d0\ub294 \ubb34\uc5c7\uc774 \uc788\uc744\uae4c \ucf5c\ub85c\ub514 \uc6d0\uc791\uc758 \uc904\uac70\ub9ac\uc640 \ub3cc\ubd04\uc744 \ubc30\uc6b0\ub294 \ub098\ubb34 \uc778\ud615\uc758 \ubcc0\ud654 \ucf5c\ub85c\ub514 \uc6d0\uc791\uc758 \uc904\uac70\ub9ac\uc640 \ub3cc\ubd04\uc744 \ubc30\uc6b0\ub294 \ub098\ubb34 \uc778\ud615\uc758 \ubcc0\ud654\uc744 \uc774\uc57c\uae30\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \ud53c\ub178\ud0a4\uc624\uc758 \uc774\ub984\uc744 \ub4e4\uc73c\uba74 \uac70\uc9d3\ub9d0\uc744 \ud560 \ub54c \ub298\uc5b4\ub098\ub294 \ucf54\uac00 \uba3c\uc800 \ub5a0\uc624\ub978\ub2e4. \uadf8\ub7ec\ub098 \uce74\ub97c\ub85c \ucf5c\ub85c\ub514\uc758 \uc6d0\uc791\uc740 \uadf8 \ud55c \uac00\uc9c0 \uad50\ud6c8\ubcf4\ub2e4 \ud6e8\uc52c \uae38\uace0 \uac70\uce60\ub2e4. \ubc30\uace0\ud514\uacfc \uc18d\uc784\uc218, \ud559\uad50\uc5d0 \ub300\ud55c \uc57d\uc18d\uacfc \uc544\ubc84\uc9c0\ub97c \uad6c\ud558\ub294 \ubaa8\ud5d8\uc774 \uc774\uc5b4\uc9c4\ub2e4. \uc0ac\ub791\uc2a4\ub7ec\uc6b4 \uc778\ud615\uc758 \uc131\uc7a5\uae30\uc774\uba74\uc11c \uc27d\uac8c \ubbff\ub294 \uc544\uc774\uac00 \uc138\uc0c1\uc744 \ub9cc\ub098\ub294 \uc774\uc57c\uae30\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc6d0\uc791\uc758 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \ub530\ub77c\uac04\ub2e4. \uc775\uc219\ud55c \uc601\uc0c1\uc758 \uc7a5\uba74\uacfc \ucc45\uc758 \uc7a5\uba74\uc774 \uaf2d \uac19\uc9c0\ub294 \uc54a\ub2e4. \ud2b9\ud788 \ub9c8\uc9c0\ub9c9\uc5d0 \ud53c\ub178\ud0a4\uc624\uac00 \ub2ec\ub77c\uc9c0\ub294 \uc774\uc720\ub97c \uc0b4\ud3b4\ubcf4\uba74, \uc9c4\uc9dc \uc0ac\ub78c\uc774 \ub41c\ub2e4\ub294 \ub9d0\uc774 \uc678\ubaa8\uc758 \ubcc0\ud654\ub9cc\uc744 \ub73b\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c \uc218 \uc788\ub2e4. \uc81c\ud398\ud1a0\ub294 \ub098\ubb34\ub85c \uaf2d\ub450\uac01\uc2dc\ub97c \ub9cc\ub4e4\uc9c0\ub9cc \ud53c\ub178\ud0a4\uc624\ub294 \ucc98\uc74c\ubd80\ud130 \ub9d0\uc37d\uc744 \uc77c\uc73c\ud0a8\ub2e4. \ub9d0\uc744 \uc798 \ub4e3\ub294 \uc644\uc131\ud488\uc774 \uc544\ub2c8\ub77c \uc790\uae30 \ub73b\ub300\ub85c \uc6c0\uc9c1\uc774\ub294 \uc874\uc7ac\ub2e4. \uac00\ub09c\ud55c \uc81c\ud398\ud1a0\uc5d0\uac8c\ub294 \uc544\uc774\ub97c \ub3cc\ubcf4\ub294 \uc77c \uc790\uccb4\uac00 \ubd80\ub2f4\uc774\uc9c0\ub9cc \uadf8\ub294 \ud53c\ub178\ud0a4\uc624\uac00 \ubc30\uc6b0\ub3c4\ub85d \ucc45\uc744 \ub9c8\ub828\ud574 \uc900\ub2e4. \uc774 \uc2dc\uc791\uc5d0\ub294 \uc0ac\ub791\uacfc \uace4\uad81\uc774 \ud568\uaed8 \uc788\ub2e4. \uc544\ubc84\uc9c0\uac00 \uc900 \ucc45\uc744 \uac00\ubccd\uac8c \uc5ec\uae30\ub294 \ud589\ub3d9\uc740 \ub2e8\uc21c\ud788 \uacf5\ubd80\ub97c \uc2eb\uc5b4\ud558\ub294 \uc7a5\ub09c\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \ucc45 \ud55c \uad8c\uc744 \ub9c8\ub828\ud55c \uc0ac\ub78c\uc758 \ud76c\uc0dd\uc744 \uc544\uc9c1 \ucda9\ubd84\ud788 \uc774\ud574\ud558\uc9c0 \ubabb\ud55c\ub2e4\ub294 \ub73b\uc774\uae30\ub3c4 \ud558\ub2e4. \ud53c\ub178\ud0a4\uc624\uac00 \ubc30\uc6cc\uc57c \ud560 \uac83\uc740 \uae00\uc790\ub9cc\uc774 \uc544\ub2c8\ub2e4. \ud53c\ub178\ud0a4\uc624\ub294 \ud559\uad50\uc5d0 \uac00\uaca0\ub2e4\uace0 \ub9c8\uc74c\uba39\uc9c0\ub9cc \uc778\ud615\uadf9\uc758 \uc720\ud639\uc5d0 \ub04c\ub9b0\ub2e4. \uc0c8\ub85c\uc6b4 \uad6c\uacbd\uac70\ub9ac\uac00 \uc9c0\uae08\uc758 \uc57d\uc18d\ubcf4\ub2e4 \ud6e8\uc52c \ud06c\uac8c \ub290\uaef4\uc9c4\ub2e4. \uc6d0\uc791\uc740 \uc774\ub7f0 \ud754\ub4e4\ub9bc\uc744 \ubc18\ubcf5\ud574\uc11c \ubcf4\uc5ec \uc900\ub2e4. \uc798\ud558\uaca0\ub2e4\ub294 \uacb0\uc2ec\uc774 \uc5c6\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uacb0\uc2ec\uc744 \uc720\uc9c0\ud558\ub294 \ud798\uc774 \uc544\uc9c1 \uc57d\ud55c \uac83\uc774\ub2e4. \uadf8\ub798\uc11c \uc774\uc57c\uae30\ub294 \ub098\uc05c \uc544\uc774\uac00 \ud55c \ubc88 \ubc8c\uc744 \ubc1b\uace0 \uc989\uc2dc \ucc29\ud574\uc9c0\ub294 \ubc29\uc2dd\uc73c\ub85c \uc9c4\ud589\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc7a0\uae50\uc758 \ubc18\uc131\uacfc \ub610 \ub2e4\ub978 \uc720\ud639\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ub3c5\uc790\ub294 \ub2e4\uc74c \uc2e4\uc218\ub97c \uc608\uc0c1\ud558\uba74\uc11c\ub3c4 \uc774\ubc88\uc5d0\ub294 \uc57d\uc18d\uc744 \uc9c0\ud0a4\uae30\ub97c \ubc14\ub780\ub2e4. \uadf8 \ubc18\ubcf5\uc774 \ub54c\ub85c \ub2f5\ub2f5\ud558\uace0 \ub54c\ub85c \uc6c3\uae34 \uac83\uc774 \uc774 \ubaa8\ud5d8\uc758 \ub9ac\ub4ec\uc774\ub2e4. \uc5ec\uc6b0\uc640 \uace0\uc591\uc774\ub294 \ud53c\ub178\ud0a4\uc624\uc5d0\uac8c \ub3c8\uc744 \uc27d\uac8c \ubd88\ub9b4 \uc218 \uc788\ub2e4\ub294 \uc774\uc57c\uae30\ub97c \ub4e4\ub824\uc900\ub2e4. \uae08\ud654\ub97c \ub545\uc5d0 \ubb3b\uc73c\uba74 \ub354 \ub9ce\uc740 \ub3c8\uc744 \uc5bb\uc744 \uc218 \uc788\ub2e4\ub294 \uc720\ud639\uc774\ub2e4. \ud53c\ub178\ud0a4\uc624\ub294 \ub178\ub825 \uc5c6\uc774 \uc88b\uc740 \uacb0\uacfc\ub97c \uc5bb\uace0 \uc2f6\uc5b4 \ud558\ub294 \ub9c8\uc74c \ub54c\ubb38\uc5d0 \uadf8 \ub9d0\uc744 \ubbff\uace0 \uc190\ud574\ub97c \uc785\ub294\ub2e4. \uc774 \uc7a5\uba74\uc740 \uc544\uc774\uc758 \uc5b4\ub9ac\uc11d\uc74c\uc744 \ube44\uc6c3\ub294 \ub370\uc11c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc0c1\ub300\uac00 \ubb34\uc5c7\uc744 \ubc14\ub77c\ub294\uc9c0 \uc54c\uc544\ub0b8 \ub4a4 \uadf8 \uc695\ub9dd\uc744 \uc774\uc6a9\ud558\ub294 \uc18d\uc784\uc218\uc758 \uad6c\uc870\uac00 \ubcf4\uc778\ub2e4. \uc704\ud5d8\ud55c \uac83\uc740 \uc138\uc0c1\uc758 \ubaa8\ub4e0 \ub0af\uc120 \uc0ac\ub78c\uc774 \uc544\ub2c8\ub77c, \ucda9\ubd84\ud55c \uadfc\uac70 \uc5c6\uc774 \ub2ec\ucf64\ud55c \uc57d\uc18d\uc744 \ubbff\ub294 \ud0dc\ub3c4\ub2e4. \ub3d9\ud654 \uc18d \uae08\ud654\ub294 \uadf8\ub7f0 \uc120\ud0dd\uc758 \ubb34\uac8c\ub97c \ubcf4\uc5ec \uc900\ub2e4. \ud53c\ub178\ud0a4\uc624\uc758 \uac70\uc9d3\ub9d0\uc740 \ub208\uc5d0 \ubcf4\uc774\ub294 \ucf54\uc758 \ubcc0\ud654\ub85c \ub4dc\ub7ec\ub09c\ub2e4. \uac10\ucd94\uace0 \uc2f6\uc5c8\ub358 \ub9d0\uc774 \ubab8\uc5d0 \ud45c\uc2dc\ub41c\ub2e4\ub294 \ubc1c\uc0c1\uc740 \ub204\uad6c\ub098 \uae30\uc5b5\ud558\uae30 \uc27d\ub2e4. \ud558\uc9c0\ub9cc \uc6d0\uc791\uc5d0\uc11c \uacaa\ub294 \uace4\ub780\uc774 \ubaa8\ub450 \uac70\uc9d3\ub9d0 \ud55c \uac00\uc9c0\uc5d0\uc11c\ub9cc \uc0dd\uae30\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud5c8\uc601\uacfc \uc870\uae09\ud568, \uc26c\uc6b4 \uc774\uc775\uc5d0 \ub300\ud55c \uae30\ub300\ub3c4 \ubb38\uc81c\ub97c \ub9cc\ub4e0\ub2e4. \ud478\ub978 \uba38\ub9ac\uc758 \uc694\uc815\uc740 \ud53c\ub178\ud0a4\uc624\ub97c \ub3d5\uace0 \uac00\ub974\uce58\ub294 \uc874\uc7ac\ub85c \ub4f1\uc7a5\ud55c\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub300\uc2e0 \ubaa8\ub4e0 \uc120\ud0dd\uc744 \ud574 \uc8fc\uc9c0\ub294 \ubabb\ud55c\ub2e4. \ub204\uad70\uac00 \uad6c\ud574 \uc8fc\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc2a4\uc2a4\ub85c \ub2ec\ub77c\uc84c\ub2e4\ub294 \uc0ac\uc2e4 \uc0ac\uc774\uc5d0\ub294 \uac70\ub9ac\uac00 \uc788\ub2e4. \uadf8 \uac70\ub9ac\ub97c \uba54\uc6b0\ub294 \uacfc\uc815\uc774 \ucc45\uc758 \uae34 \ubaa8\ud5d8\uc744 \uc774\ub8e8\uace0 \uc788\ub2e4. \ud53c\ub178\ud0a4\uc624\ub294 \uacf5\ubd80\uc640 \uc758\ubb34 \uc5c6\uc774 \ub180 \uc218 \uc788\ub294 \uacf3\uc73c\ub85c \ud5a5\ud55c\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ub204\uad6c\ub098 \ud0d0\ub0bc \ub9cc\ud55c \uc790\uc720\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc \uadf8 \uacb0\uacfc\ub294 \ub2f9\ub098\uadc0\ub85c \ubcc0\ud558\ub294 \uc77c\uc774\ub2e4. \uc990\uac70\uc6c0\uc744 \uc5bb\uc73c\ub824\ub358 \uc544\uc774\uac00 \uc624\ud788\ub824 \ub2e4\ub978 \uc774\uc5d0\uac8c \uc774\uc6a9\ub418\ub294 \ucc98\uc9c0\uac00 \ub41c\ub2e4. \ub9c8\uc74c\ub300\ub85c \uc0b4\uace0 \uc2f6\ub2e4\ub294 \uc695\ub9dd\uc774 \ubab8\uc758 \uc790\uc720\ub97c \ube7c\uc557\ub294 \ubc29\ud5a5\uc73c\ub85c \ub4a4\uc9d1\ud78c\ub2e4. \uc6d0\uc791\uc758 \uc774\ub7f0 \uc7a5\uba74\uc740 \ud604\ub300\uc758 \ubd80\ub4dc\ub7ec\uc6b4 \uc5b4\ub9b0\uc774 \uc774\uc57c\uae30\ubcf4\ub2e4 \uac00\ud639\ud558\uac8c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uac70\uce5c \ubcc0\ud654\uac00 \uc774 \uc791\ud488\uc758 \uc131\uaca9\uc774\uae30\ub3c4 \ud558\ub2e4. \ucf5c\ub85c\ub514\ub294 \uc720\ud639\uc758 \ub300\uac00\ub97c \uc791\uc740 \ud6c8\uacc4\ub85c\ub9cc \ucc98\ub9ac\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud53c\ub178\ud0a4\uc624\ub294 \uc9c1\uc811 \uace4\ub780\uc744 \uacaa\uace0\uc11c\uc57c \uc790\uc2e0\uc758 \ud589\ub3d9\uc774 \uc5b4\ub514\ub85c \uc774\uc5b4\uc9c0\ub294\uc9c0 \ubc30\uc6b4\ub2e4. \ud070 \ubc14\ub2e4 \uc0dd\ubb3c\uc5d0\uac8c \uc0bc\ucf1c\uc9c4 \ud53c\ub178\ud0a4\uc624\ub294 \uadf8 \uc548\uc5d0\uc11c \uc81c\ud398\ud1a0\ub97c \ub9cc\ub09c\ub2e4. \ubc16\uc73c\ub85c \ub098\uc628 \ub4a4\uc5d0\ub294 \uae30\ub825\uc774 \uc57d\ud55c \uc544\ubc84\uc9c0\ub97c \ub3d5\ub294\ub2e4. \uc704\ud5d8\ud55c \ubc14\ub2e4\uc5d0\uc11c \ub458\ub9cc\uc758 \ud798\uc774 \ubd80\uc871\ud574\uc84c\uc744 \ub54c\uc5d0\ub294 \ud568\uaed8 \ud0c8\ucd9c\ud588\ub358 \ucc38\uce58\uc758 \ub3c4\uc6c0\ub3c4 \ubc1b\ub294\ub2e4. \uad6c\ucd9c\uc740 \ud55c \uc601\uc6c5\uc774 \ubaa8\ub4e0 \uac83\uc744 \ud574\ub0b4\ub294 \uc7a5\uba74\uc73c\ub85c\ub9cc \uad6c\uc131\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc774\uc804\uae4c\uc9c0 \ud53c\ub178\ud0a4\uc624\ub294 \uc8fc\ub85c \ub3c4\uc6c0\uc744 \ubc1b\ub294 \ucabd\uc774\uc5c8\ub2e4. \uc774\uc81c\ub294 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc57d\ud568\uc744 \ubcf4\uace0 \uc790\uc2e0\uc774 \uc6c0\uc9c1\uc778\ub2e4. \uac00\ub09c\uacfc \ud53c\ub85c\uac00 \uc0ac\ub77c\uc9c4 \ub4a4\uc5d0 \ucc45\uc784\uc744 \ub9e1\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc5b4\ub824\uc6b4 \uc0c1\ud669\uc5d0\uc11c \ub3cc\ubd04\uc744 \uc2dc\uc791\ud55c\ub2e4. \ub098\ubb34 \uc778\ud615\uc758 \ubcc0\ud654\ub294 \uc774\ucc98\ub7fc \uc544\ubc84\uc9c0\uc640\uc758 \uad00\uacc4\uac00 \ub2ec\ub77c\uc9c0\ub294 \ubaa8\uc2b5\uc5d0\uc11c \uba3c\uc800 \ub4dc\ub7ec\ub09c\ub2e4. \ub9c8\uc9c0\ub9c9\uc758 \ud53c\ub178\ud0a4\uc624\ub294 \uc77c\ud558\uba70 \uc544\ubc84\uc9c0\ub97c \ub3cc\ubcf4\uace0 \uacf5\ubd80\ud55c\ub2e4. \uc694\uc815\uc774 \uc5b4\ub824\uc6c0\uc5d0 \ucc98\ud588\ub2e4\ub294 \ub9d0\uc744 \ub4e3\uace0 \ubaa8\uc544 \ub454 \ub3c8\uc744 \ub0b4\ub193\uae30\ub3c4 \ud55c\ub2e4. \uadf8\ub7ec\uace0 \ub098\uc11c \uc9c4\uc9dc \uc18c\ub144\uc73c\ub85c \ubcc0\ud55c \uc790\uc2e0\uc744 \ubc1c\uacac\ud55c\ub2e4. \uac89\ubaa8\uc2b5\uc758 \uae30\uc801\ubcf4\ub2e4 \uba3c\uc800 \uc0dd\ud65c\uc758 \uc120\ud0dd\uc774 \ub2ec\ub77c\uc838 \uc788\uc5c8\ub2e4\ub294 \uc21c\uc11c\uac00 \uc911\uc694\ud558\ub2e4. \uc81c\ud398\ud1a0\uac00 \ucc98\uc74c \uc900 \ucc45\uacfc \ub9c8\uc9c0\ub9c9\uc5d0 \uc774\uc5b4\uc9c0\ub294 \uacf5\ubd80\ub97c \uc5f0\uacb0\ud574 \ubcf4\uba74 \uc6d0\uc791\uc758 \uae38\uc774\uac00 \uc774\ud574\ub41c\ub2e4. \ucc45\uc744 \uc190\uc5d0 \ub123\ub294 \uac83\uacfc \ubc30\uc6b8 \uc900\ube44\uac00 \ub418\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uae34 \uc6b0\ud68c\ub294 \ucd9c\ubc1c\uc810\uc73c\ub85c \ub3cc\uc544\uc624\ub294 \uacfc\uc815\uc774\uba74\uc11c \uadf8 \ucd9c\ubc1c\uc810\uc744 \uc804\uacfc \ub2e4\ub974\uac8c \ubc1b\uc544\ub4e4\uc774\uac8c \ub418\ub294 \uacfc\uc815\uc774\ub2e4. \uc6d0\uc791\uc744 \ub2e4\uc2dc \uc77d\uc73c\uba74 \ucf54\ubcf4\ub2e4 \ucc45\uacfc \uae08\ud654, \uc74c\uc2dd\uacfc \ub178\ub3d9\uc774 \uc790\uc8fc \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ubb34\uc5c7\uc744 \ubbff\uace0 \ubb34\uc5c7\uc744 \ubbf8\ub8e8\uba70 \ub204\uad6c\ub97c \uc704\ud574 \uc218\uace0\ud560 \uac83\uc778\uac00. \u300e\ud53c\ub178\ud0a4\uc624\u300f\ub294 \uac70\uc9d3\ub9d0\uc744 \ud558\uc9c0 \ub9d0\ub77c\ub294 \uad50\ud6c8\uc744 \ud488\uc73c\uba74\uc11c\ub3c4, \ub0a8\uc5d0\uac8c\uc11c \ubc1b\ub358 \uc0ac\ub791\uc744 \uc790\uc2e0\ub3c4 \ub3cc\ub824\uc904 \uc218 \uc788\uac8c \ub418\ub294 \uacfc\uc815\uc744 \uae38\uac8c \ub4e4\ub824\uc8fc\ub294 \uc791\ud488\uc774\ub2e4."}, {"id": "piri-reis-map-and-shared-seas", "title": "\ud53c\ub9ac \ub808\uc774\uc2a4\uc758 \uc9c0\ub3c4 \u2014 \uc624\uc2a4\ub9cc\uc758 \uc885\uc774 \uc704\uc5d0 \uc544\uba54\ub9ac\uce74\uac00 \ub098\ud0c0\ub098\ub2e4", "summary": "\uc624\uc2a4\ub9cc\uc758 \uc9c0\ub3c4\uc5d0 \ucf5c\ub7fc\ubc84\uc2a4\u00b7\ud3ec\ub974\ud22c\uac08\u00b7\uc544\ub78d\uad8c\uc758 \uc815\ubcf4\uac00 \ud568\uaed8 \ub2f4\uae34 \uacfc\uc815\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/piri-reis-map-and-shared-seas/index.html", "image": "../media/piri-reis-map-and-shared-seas.jpg", "alt": "\ud53c\ub9ac \ub808\uc774\uc2a4\uc758 1513\ub144 \uc138\uacc4 \uc9c0\ub3c4 \uc911 \ub300\uc11c\uc591\uacfc \uc8fc\ubcc0 \ub300\ub959\uc774 \ub0a8\uc740 \ubd80\ubd84", "text": "\ud53c\ub9ac \ub808\uc774\uc2a4\uc758 \uc9c0\ub3c4 \u2014 \uc624\uc2a4\ub9cc\uc758 \uc885\uc774 \uc704\uc5d0 \uc544\uba54\ub9ac\uce74\uac00 \ub098\ud0c0\ub098\ub2e4 1513\ub144 \ub300\uc11c\uc591 \uc9c0\ub3c4\uc5d0 \ubaa8\uc778 \uc5ec\ub7ec \ud56d\ud574\uc790\uc758 \uc815\ubcf4 \uc624\uc2a4\ub9cc\uc758 \uc9c0\ub3c4\uc5d0 \ucf5c\ub7fc\ubc84\uc2a4\u00b7\ud3ec\ub974\ud22c\uac08\u00b7\uc544\ub78d\uad8c\uc758 \uc815\ubcf4\uac00 \ud568\uaed8 \ub2f4\uae34 \uacfc\uc815\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \uc624\ub798\ub41c \uc9c0\ub3c4 \ud55c \uc7a5\uc5d0\ub294 \ud574\uc548\uc120\ub9cc \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \ubc14\ub2e4\ub97c \uac74\ub10c \uc0ac\ub78c\uc758 \uacbd\ud5d8, \ub2e4\ub978 \uacf3\uc5d0\uc11c \uac00\uc838\uc628 \uc815\ubcf4, \uc544\uc9c1 \ubaa8\ub974\ub294 \ubd80\ubd84\uc744 \uba54\uc6b0\ub824\ub294 \ud310\ub2e8\uc774 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4. \uc624\uc2a4\ub9cc\uc758 \ud574\uad70 \uc9c0\ud718\uad00\uc774\uc790 \uc9c0\ub3c4 \uc81c\uc791\uc790 \ud53c\ub9ac \ub808\uc774\uc2a4\uac00 1513\ub144\uc5d0 \ub9cc\ub4e0 \uc9c0\ub3c4\ub294 \uadf8 \ub9cc\ub0a8\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ud765\ubbf8\ub85c\uc6b4 \uc790\ub8cc\ub2e4. \uc9c0\uae08 \ub0a8\uc544 \uc788\ub294 \uac83\uc740 \uc6d0\ub798 \uc9c0\ub3c4\uc758 \uc77c\ubd80\ub2e4. \ub300\uc11c\uc591\uacfc \uadf8 \ub458\ub808\uc758 \uc720\ub7fd\u00b7\uc544\ud504\ub9ac\uce74\u00b7\ube0c\ub77c\uc9c8\uc774 \ubcf4\uc778\ub2e4. \uc644\ubcbd\ud55c \uc138\uacc4 \uc9c0\ub3c4\ub97c \uae30\ub300\ud558\uae30\ubcf4\ub2e4 \uc5b4\ub5bb\uac8c \uc11c\ub85c \ub2e4\ub978 \ubc14\ub2e4\uc758 \uc815\ubcf4\uac00 \uc624\uc2a4\ub9cc\uc758 \uc81c\uc791\uc790\uc5d0\uac8c \ubaa8\uc600\ub294\uc9c0 \ubb3b\ub294 \ud3b8\uc774 \uc774 \uc790\ub8cc\ub97c \ub354 \uc7ac\ubbf8\uc788\uac8c \uc77d\ub294 \ubc29\ubc95\uc774\ub2e4. \ub300\ud56d\ud574\uc2dc\ub300\ub77c\uace0 \ud558\uba74 \ud3ec\ub974\ud22c\uac08\uacfc \uc5d0\uc2a4\ud30c\ub0d0\uc758 \ubc30\ubd80\ud130 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \ud56d\ud574\uc640 \uad50\uc5ed\uc758 \uc815\ubcf4\ub294 \uadf8 \ub450 \ub098\ub77c \uc548\uc5d0\ub9cc \uba38\ubb3c\uc9c0 \uc54a\uc558\ub2e4. \uc9c0\uc911\ud574\uc640 \uc5ec\ub7ec \uad50\uc5ed\ub85c\ub97c \uc787\ub358 \uc774\uc2ac\ub78c \uc138\uacc4\uc5d0\uc11c\ub3c4 \uc9c0\ub3c4\uc640 \uc704\uce58\ub97c \uc544\ub294 \uae30\uc220\uc740 \uc911\uc694\ud55c \uc9c0\uc2dd\uc774\uc5c8\ub2e4. \ubc30\uac00 \uc6c0\uc9c1\uc774\ub294 \uacf3\uc5d0\ub294 \uae38\uc744 \ud310\ub2e8\ud560 \uc790\ub8cc\uac00 \ud544\uc694\ud588\ub2e4. \ud53c\ub9ac \ub808\uc774\uc2a4\ub294 \uc774\ub7f0 \ud658\uacbd\uc5d0\uc11c \ud65c\ub3d9\ud55c \uc778\ubb3c\uc774\ub2e4. \uc624\ub298\uc758 \uad6d\uac00\ubcc4 \uc77d\uc744\uac70\ub9ac\uc5d0\uc11c\ub294 \ud280\ub974\ud0a4\uc608\uc5d0 \ubc30\uce58\ud558\uc9c0\ub9cc \uadf8\uac00 \uc18d\ud55c \uc138\uacc4\ub294 \uc624\uc2a4\ub9cc\uc81c\uad6d\uc774\uc5c8\ub2e4. \ud604\ub300\uc758 \uad6d\uacbd\uacfc \ub2f9\uc2dc\uc758 \ud56d\ud574 \uacf5\uac04\uc744 \uad6c\ubd84\ud558\uba74, \ud55c \ub098\ub77c\uac00 \ub3c5\ub9bd\uc801\uc73c\ub85c \uc138\uacc4\ub97c \uc54c\uc544 \uac14\ub2e4\ub294 \uc124\uba85\ubcf4\ub2e4 \ub354 \ub113\uc740 \uc5f0\uacb0\uc774 \ubcf4\uc778\ub2e4. \uc9c0\ub3c4 \uc81c\uc791 \uc5f0\ub3c4\ub294 \uadf8 \uc9c0\ub3c4\uc5d0 \ub2f4\uae34 \uc9c0\uc2dd\uc758 \uc2dc\uc810\uc744 \uc54c\ub824 \uc900\ub2e4. \uc544\uba54\ub9ac\uce74\uac00 \uc720\ub7fd\uc758 \ud56d\ud574\uc640 \uad50\uc5ed\uc5d0 \uc0c8\ub86d\uac8c \uc5f0\uacb0\ub418\ub358 \uc2dc\uae30\uc600\uace0 \ubc14\ub2e4 \uac74\ub108 \ud574\uc548\uc5d0 \ub300\ud55c \uc815\ubcf4\uac00 \ube60\ub974\uac8c \ub298\uace0 \uc788\uc5c8\ub2e4. \uc624\ub298\uc758 \uc9c0\ub3c4\ub97c \uc606\uc5d0 \ub193\uc73c\uba74 \ud2c0\ub9b0 \ubd80\ubd84\uc774 \uba3c\uc800 \ubcf4\uc774\uaca0\uc9c0\ub9cc, \uc81c\uc791 \ub2f9\uc2dc \ubb34\uc5c7\uc744 \uc54c \uc218 \uc788\uc5c8\ub294\uc9c0\uac00 \uba3c\uc800\ub2e4. \uc9c0\ub3c4\ub294 \uad00\uce21\uc774 \ub05d\ub09c \ub4a4 \ub2e8\uc21c\ud788 \uc120\uc744 \uc62e\uae30\ub294 \uc791\uc5c5\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uc11c\ub85c \ub9de\uc9c0 \uc54a\ub294 \ubcf4\uace0\ub97c \ube44\uad50\ud558\uace0 \uc5b4\ub290 \uc815\ubcf4\ub97c \uc0ac\uc6a9\ud560\uc9c0 \uc815\ud574\uc57c \ud55c\ub2e4. \uc544\uc9c1 \ud655\uc778\ud558\uc9c0 \ubabb\ud55c \uacf3\ub3c4 \uc788\ub2e4. \uc644\uc131\ub41c \uc120 \ub4a4\uc5d0 \uc774\ub7f0 \uc120\ud0dd\uc758 \uacfc\uc815\uc774 \uc788\uc5c8\ub2e4\ub294 \uc810\uc744 \uae30\uc5b5\ud558\uba74 \uc624\ub798\ub41c \uc9c0\ub3c4\uc758 \ub0af\uc120 \ubaa8\uc591\ub3c4 \uc77d\uc744 \uc774\uc720\uac00 \uc0dd\uae34\ub2e4. \ud53c\ub9ac \ub808\uc774\uc2a4\ub294 \ucf5c\ub7fc\ubc84\uc2a4\uc758 \uad00\uce21\uacfc \uad00\ub828\ub41c \uc815\ubcf4, \uc778\ub3c4 \ubc29\uba74\uc744 \ud56d\ud574\ud55c \ud3ec\ub974\ud22c\uac08\uc778\ub4e4\uc758 \uc790\ub8cc, \uc544\ub78d\uad8c\uc758 \uc5ec\ub7ec \ucd9c\ucc98\ub97c \uc774\uc6a9\ud588\ub2e4. \uadf8 \uc790\uc2e0\uc774 \uc9c0\ub3c4\uc5d0 \ub098\uc628 \ubaa8\ub4e0 \ud574\uc548\uc744 \uc9c1\uc811 \ub2f5\uc0ac\ud588\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uc5ec\ub7ec \uacbd\ub85c\uc5d0\uc11c \uc5bb\uc740 \uc9c0\uc2dd\uc744 \ubaa8\uc544 \uc0c8\ub85c\uc6b4 \uacb0\uacfc\ubb3c\uc744 \ub9cc\ub4e0 \uac83\uc774\ub2e4. \uc9c0\ub3c4\uc758 \uac00\uce58\uac00 \uc9c1\uc811 \ubcf8 \uac83\uc5d0\ub9cc \ub2ec\ub824 \uc788\uc5c8\ub2e4\uba74 \uc774\ub7f0 \uc791\uc5c5\uc740 \ubd88\uac00\ub2a5\ud588\uc744 \uac83\uc774\ub2e4. \uc2e0\ub8b0\ud560 \ub9cc\ud55c \ud0c0\uc778\uc758 \uae30\ub85d\uc744 \ud655\ubcf4\ud558\uace0 \ube44\uad50\ud558\ub294 \ub2a5\ub825\ub3c4 \uc804\ubb38\uc131\uc774\ub2e4. \ub204\uac00 \uba3c\uc800 \ub3c4\ucc29\ud588\ub294\uc9c0\uc758 \uacbd\uc7c1\ub9cc\uc73c\ub85c \ud56d\ud574\uc0ac\ub97c \uc77d\uc73c\uba74, \uc815\ubcf4\uac00 \ubaa8\uc774\uace0 \ub2e4\uc2dc \ud3b8\uc9d1\ub418\ub294 \uc774 \uc911\uc694\ud55c \uacfc\uc815\uc744 \ub193\uce58\uac8c \ub41c\ub2e4. \ud604\uc7ac \uc804\ud558\ub294 \uac83\uc740 \uc9c0\ub3c4 \uc804\uccb4\uc758 \ub300\ub7b5 \uc0bc\ubd84\uc758 \uc77c\uc774\ub2e4. \ub530\ub77c\uc11c \uc774 \ud55c \uc7a5\uc5d0 \uc5c6\ub294 \uc9c0\uc5ed\uc774 \uc6d0\ub798\ubd80\ud130 \uadf8\ub824\uc9c0\uc9c0 \uc54a\uc558\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218 \uc5c6\ub2e4. \uc790\ub8cc\uac00 \ub9cc\ub4e4\uc5b4\uc9c4 \ub54c\uc758 \ubaa8\uc2b5\uacfc \uc624\ub298 \ub0a8\uc740 \ubaa8\uc2b5 \uc0ac\uc774\uc5d0 \ucc28\uc774\uac00 \uc788\ub294 \uac83\uc774\ub2e4. \uadf8\ub9bc\uc744 \ubcf4\ub294 \uc77c\uc5d0\ub3c4 \ubcf4\uc874 \uc0c1\ud0dc\ub97c \uc77d\ub294 \ub208\uc774 \ud544\uc694\ud558\ub2e4. \ubc15\ubb3c\uad00\uc774\ub098 \ucc45\uc5d0\uc11c\ub294 \ub0a8\uc740 \uc870\uac01\uc774 \ud55c \ud654\uba74\uc744 \ucc44\uc6b0\uae30 \ub54c\ubb38\uc5d0 \uc644\uc131\ub41c \ubb3c\uac74\ucc98\ub7fc \ubcf4\uc77c \ub54c\uac00 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc798\ub9b0 \uacbd\uacc4\ub294 \ud574\uc11d\uc758 \uc870\uac74\uc774\ub2e4. \uc9c0\ub3c4\uac00 \uc5b4\ub514\uae4c\uc9c0 \ub2f4\uc73c\ub824 \ud588\ub294\uc9c0\uc640 \uc9c0\uae08 \uc5b4\ub514\uae4c\uc9c0 \ud655\uc778\ud560 \uc218 \uc788\ub294\uc9c0\ub97c \ub098\ub204\uba74, \uc0ac\ub77c\uc9c4 \ubd80\ubd84\uc5d0 \ub300\ud55c \uc131\uae09\ud55c \ucd94\uce21\ub3c4 \uc904\uc5b4\ub4e0\ub2e4. \uc774 \uc9c0\ub3c4\uc5d0\ub294 \ud574\uc548\uc120\uacfc \ubc29\ud5a5\uc744 \ud30c\uc545\ud558\ub294 \uc120, \uc5ec\ub7ec \uadf8\ub9bc\uacfc \uc124\uba85\uc774 \ud568\uaed8 \ubcf4\uc778\ub2e4. \uc624\ub298\ub0a0 \uc0ac\uc6a9\ud558\ub294 \ub2e8\uc21c\ud55c \ub3c4\ub85c \uc9c0\ub3c4\uc640 \uc778\uc0c1\uc774 \ub2e4\ub974\ub2e4. \uadf8\ub7ec\ub098 \ub0af\uc120 \uadf8\ub9bc\uc774 \ub9ce\ub2e4\ub294 \uc774\uc720\ub85c \uc9c0\ub3c4 \uc804\uccb4\ub97c \uc0c1\uc0c1\ud654\ub85c \ucde8\uae09\ud574\uc11c\ub3c4 \uc548 \ub41c\ub2e4. \uc704\uce58 \uc815\ubcf4\uc640 \ud56d\ud574\uc758 \uc9c0\uc2dd\uc774 \uc2e4\uc81c \uae30\ub2a5\uc744 \uac16\uace0 \uc788\uc5c8\ub2e4. \ubc18\ub300\ub85c \ud654\uba74\uc5d0 \uadf8\ub824\uc838 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \ud45c\ud604\uc744 \uc815\ud655\ud55c \uad00\uce21\uc758 \uacb0\uacfc\ub85c \ubbff\uc5b4\uc11c\ub3c4 \uc548 \ub41c\ub2e4. \uc9c0\ub3c4\uc5d0\ub294 \uc815\ubcf4\uc758 \uc131\uaca9\uc774 \uc11c\ub85c \ub2e4\ub978 \uc694\uc18c\uac00 \uacb9\uce5c\ub2e4. \uc120\uacfc \uae00, \uadf8\ub9bc\uc774 \uac01\uac01 \ubb34\uc5c7\uc744 \ub9d0\ud558\ub824 \ud558\ub294\uc9c0 \ub098\ub204\uc5b4 \ubcf4\ub294 \uac83\uc774 \uc88b\ub2e4. \ud55c \ubc88\uc5d0 \uc815\ub2f5\uc744 \ucc3e\uae30\ubcf4\ub2e4 \ubd80\ubd84\ub9c8\ub2e4 \uc9c8\ubb38\uc744 \ub2ec\ub9ac\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc624\ub798\ub41c \uc9c0\ub3c4\uc5d0\uc11c \ud604\uc7ac\uc640 \ub2ee\uc544 \ubcf4\uc774\ub294 \ud615\uc0c1\uc744 \ucc3e\ub294 \uc77c\uc740 \ud765\ubbf8\ub86d\ub2e4. \ud558\uc9c0\ub9cc \ub2ee\uc558\ub2e4\ub294 \uc778\uc0c1\ub9cc\uc73c\ub85c \uc81c\uc791\uc790\uac00 \ud604\ub300\uc758 \uacfc\ud559\uc801 \uc9c0\uc2dd\uc744 \uc774\ubbf8 \uac00\uc84c\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ucd9c\ucc98\uc640 \uc81c\uc791 \uc2dc\uae30, \ub0a8\uc544 \uc788\ub294 \ubd80\ubd84\uc774\ub77c\ub294 \uc870\uac74\uc744 \uac74\ub108\ub6f0\uba74 \uc790\ub8cc\ubcf4\ub2e4 \uc0c1\uc0c1\uc774 \uc55e\uc11c\uac8c \ub41c\ub2e4. \uc774 \uc9c0\ub3c4\ub294 \uacfc\uc7a5\ub41c \uc218\uc218\uaed8\ub07c\ub97c \ubd99\uc774\uc9c0 \uc54a\uc544\ub3c4 \ucda9\ubd84\ud788 \ud2b9\ubcc4\ud558\ub2e4. \ub300\uc11c\uc591 \ub108\uba38\uc5d0\uc11c \uc0dd\uae34 \uc815\ubcf4\uac00 \uc774\uc2ac\ub78c\uad8c\uc758 \uc9c0\uc2dd\uacfc \ub9cc\ub098 \ud55c \uc7a5\uc5d0 \uc815\ub9ac\ub418\uc5c8\ub2e4\ub294 \uc0ac\uc2e4 \uc790\uccb4\uac00 \uc911\uc694\ud558\ub2e4. \uc9c0\ub3c4\uac00 \uc2e4\uc81c\ub85c \ubcf4\uc5ec \uc8fc\ub294 \uc5f0\uacb0\uc744 \uc77d\ub294 \ud3b8\uc774 \uadfc\uac70 \uc5c6\ub294 \uc2e0\ube44\ubcf4\ub2e4 \ub354 \ud48d\ubd80\ud55c \uc138\uacc4\uc0ac\ub97c \ub9cc\ub4e4\uc5b4 \uc900\ub2e4. \ud53c\ub9ac \ub808\uc774\uc2a4\uc758 \uc9c0\ub3c4\ub294 \uc624\uc2a4\ub9cc\uc758 \uc81c\uc791\ubb3c\uc774\uba74\uc11c \uc5ec\ub7ec \ud56d\ud574\uc790\uc640 \uae30\ub85d\uc758 \uacb0\uacfc\ub2e4. \ud55c \uc0ac\ub78c\uc774 \ub9cc\ub4e0 \ubb3c\uac74\uacfc \uc5ec\ub7ec \uc0ac\ub78c\uc774 \uc313\uc740 \uc9c0\uc2dd\uc740 \uc11c\ub85c \ubaa8\uc21c\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc624\ud788\ub824 \uc9c0\ub3c4\ub97c \ub9cc\ub4e0 \uc0ac\ub78c\uc758 \uc5ed\ud560\uc740 \uadf8 \ub113\uc740 \uc815\ubcf4\ub97c \uc120\ud0dd\ud558\uace0 \uc5f0\uacb0\ud558\ub294 \ub370\uc5d0\uc11c\ub3c4 \ub4dc\ub7ec\ub09c\ub2e4. \uc790\ub8cc\ub97c \ubaa8\uc558\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ubaa8\ub4e0 \ucd9c\ucc98\uc758 \uc815\ud655\ub3c4\uac00 \uac19\uc558\ub2e4\ub294 \ub73b\ub3c4 \uc544\ub2c8\ub2e4. \uad00\uce21\uc758 \ubc94\uc704\uc640 \ubcf4\uace0 \ubc29\uc2dd\uc740 \uc11c\ub85c \ub2ec\ub790\uc744 \uac83\uc774\ub2e4. \uc9c0\ub3c4\uc5d0 \ud558\ub098\uc758 \uc724\uacfd\uc73c\ub85c \uc815\ub9ac\ub41c \uacb0\uacfc\ub97c \ubcf4\uba74\uc11c\ub3c4, \uadf8 \uc55e\uc5d0 \uc5ec\ub7ec \uac08\ub798\uc758 \uae30\ub85d\uc774 \uc788\uc5c8\ub2e4\ub294 \uc810\uc744 \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \ud604\ub300\uc758 \uc9c0\ub3c4\uc5d0 \uc775\uc219\ud55c \ub3c5\uc790\ub77c\uba74 \uc6b0\uc120 \uc720\ub7fd\u00b7\uc544\ud504\ub9ac\uce74\u00b7\ube0c\ub77c\uc9c8\uc758 \ud574\uc548\uc744 \ucc3e\uc544\ubcf4\uc790. \uadf8\ub7f0 \ub2e4\uc74c \uadf8 \uc120\uc744 \uadf8\ub9ac\ub294 \ub370 \uc5b4\ub5a4 \uc815\ubcf4\uac00 \ud544\uc694\ud588\uc744\uc9c0 \uc0dd\uac01\ud574 \ubcf4\uc790. \uc624\ub798\ub41c \uc9c0\ub3c4\ub294 \uc138\uacc4\uac00 \uc5b8\uc81c \uc644\uc804\ud788 \uc54c\ub824\uc84c\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \uc815\ub2f5\uc9c0\uac00 \uc544\ub2c8\ub77c, \uc0ac\ub78c\ub4e4\uc774 \uc11c\ub85c\uc758 \uae30\ub85d\uc744 \ud1b5\ud574 \uc138\uacc4\ub97c \ub113\ud600 \uac04 \ud754\uc801\uc774\ub2e4."}, {"id": "poem-plaque-raised-letters", "title": "\uc774 \ud604\ud310\uc758 \uae00\uc790\ub294 \ub530\ub85c \ub9cc\ub4e4\uc5b4 \ubd99\uc600\ub2e4", "summary": "\uc2dc \ud55c \ud3b8\uacfc \uc785\uccb4\uc801\uc778 \uae00\uc790\uac00 \ud568\uaed8 \ub0a8\uc740 \ud604\ud310\uc744 \ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/poem-plaque-raised-letters/index.html", "image": "../media/poem-plaque-raised-letters.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \ubc30\ub9bc\ucd98\ubc29\uacbd\ucc28\uc5b4\uc81c \ud604\ud310 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc774 \ud604\ud310\uc758 \uae00\uc790\ub294 \ub530\ub85c \ub9cc\ub4e4\uc5b4 \ubd99\uc600\ub2e4 \uc138\uc790\uac00 \ub2f5\ud55c \uc2dc\uac00 \ub098\ubb34\ud310\uc5d0 \ub0a8\ub294 \uacfc\uc815 \uc2dc \ud55c \ud3b8\uacfc \uc785\uccb4\uc801\uc778 \uae00\uc790\uac00 \ud568\uaed8 \ub0a8\uc740 \ud604\ud310\uc744 \ubd05\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \ud604\ud310\uc774\ub77c\uace0 \ud558\uba74 \uac74\ubb3c \uc774\ub984\uc774 \ud06c\uac8c \uc801\ud78c \ud310\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7f0\ub370 \uc774 \ud604\ud310\uc5d0\ub294 \uc5ec\ub7ec \uc904\uc758 \uae00\uc774 \ub2f4\uaca8 \uc788\ub2e4. \uc774\ub984\ud45c\ub77c\uae30\ubcf4\ub2e4 \ubcbd\uc5d0 \uac78\uc5b4 \ub450\ub294 \ud55c \ud3b8\uc758 \uc2dc\uc5d0 \uac00\uae5d\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \ubc30\ub9bc\ucd98\ubc29\uacbd\ucc28\uc5b4\uc81c \ud604\ud310\uc774\ub2e4. \uc81c\ubaa9\uc740 \uae38\uace0 \ub0af\uc124\uc9c0\ub9cc \uadf8 \uc548\uc758 \uc0c1\ud669\uc740 \uc870\uae08 \uce5c\uc219\ud558\ub2e4. \ub204\uad70\uac00 \uba3c\uc800 \uc2dc\ub97c \uc9c0\uc5c8\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc774 \uadf8 \uc2dc\uc5d0 \ub2f5\ud588\ub2e4. \ubc15\ubb3c\uad00\uc5d0 \ub530\ub974\uba74 1886\ub144 3\uc6d4 15\uc77c \uace0\uc885\uc740 \uc138\uc790\uac00 \uacf5\ubd80\ud558\ub294 \uc790\ub9ac\uc5d0 \ub098\uc544\uac14\ub2e4. \uae30\uc05c \ub9c8\uc74c\uc5d0 \uad00\uc6d0\ub4e4\uc5d0\uac8c \uc220\uc744 \ub0b4\ub9ac\uace0 \uc2dc\ub97c \uc9c0\uc5c8\uc73c\uba70, \uc655\uc138\uc790\ub294 \uadf8 \uc2dc\uc5d0 \ud654\ub2f5\ud588\ub2e4. \ud6d7\ub0a0 \uc21c\uc885\uc774 \ub418\ub294 \uc138\uc790\ub2e4. \uc774 \ud604\ud310\uc5d0\ub294 \uadf8 \ub2f5\uc2dc\uac00 \uc0c8\uaca8\uc838 \uc788\ub2e4. \uae34 \uad00\uc9c1\uba85\uc774\ub098 \uc5b4\ub824\uc6b4 \uc758\ub840 \uc808\ucc28\ub97c \uba3c\uc800 \uc54c\uc544\uc57c\ub9cc \ubcf4\ub294 \ubb3c\uac74\uc740 \uc544\ub2c8\ub2e4. \ub204\uad70\uac00\uc758 \uae00\uc5d0 \ub2e4\ub978 \uae00\ub85c \uc751\ub2f5\ud55c \uc7a5\uba74\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \uc2dc\uc791\uc774 \ud55c\uacb0 \uac00\ubcbc\uc6cc\uc9c4\ub2e4. \ubc15\ubb3c\uad00\uc740 \uac19\uc740 \ub0b4\uc6a9\uc774 \uc21c\uc885\uc758 \ubb38\uc9d1\uc778 \uc815\ud5cc\uc9d1\uc5d0\ub3c4 \uae30\ub85d\ub418\uc5b4 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uae00\uc740 \ucc45 \uc548\uc5d0\ub3c4 \ub0a8\uc558\uace0, \ud604\ud310\uc774\ub77c\ub294 \ubb3c\uac74\uc5d0\ub3c4 \ub0a8\uc558\ub2e4. \uac19\uc740 \ubb38\uc7a5\uc774 \uba38\ubb34\ub294 \uc790\ub9ac\uac00 \ub2ec\ub77c\uc9c0\ub294 \uac83\uc774\ub2e4. \ucc45\uc5d0\uc11c\ub294 \ud398\uc774\uc9c0\ub97c \ub118\uaca8 \uc77d\uc9c0\ub9cc \ud604\ud310\uc740 \uacf5\uac04\uc5d0 \uac78\uc5b4 \ub454\ub2e4. \uadf8\ub798\uc11c \uc2dc\ub97c \uae30\uc5b5\ud558\ub294 \ubc29\uc2dd\ub3c4 \ub2e4\ub974\uac8c \uc0c1\uc0c1\ud560 \uc218 \uc788\ub2e4. \ubb3c\ub860 \uc2e4\uc81c\ub85c \ub204\uac00 \uc774 \uc55e\uc5d0\uc11c \uc2dc\ub97c \uc77d\uc5c8\ub294\uc9c0\ub294 \uc774 \ubb3c\uac74\ub9cc \ubcf4\uace0 \uc815\ud560 \uc218 \uc5c6\ub2e4. \ud654\ub2f5\uc740 \uc55e\uc120 \uae00\uc5d0 \ub2e4\ub978 \uae00\ub85c \uc751\ub2f5\ud558\ub294 \uc77c\uc774\ub2e4. \uace0\uc885\uc774 \uacf5\ubd80\ud558\ub294 \uc138\uc790\ub97c \ucc3e\uc544\uc640 \uc9c0\uc740 \uc2dc\uc640 \uc138\uc790\uc758 \ub2f5\uc2dc\ub97c \ud568\uaed8 \ub5a0\uc62c\ub9ac\uba74 \uc774 \ud604\ud310\uc740 \ud63c\uc790 \ub2eb\ud78c \ubb38\uc7a5\uc774 \uc544\ub2c8\uac8c \ub41c\ub2e4. \uae00\uc744 \uc8fc\uace0\ubc1b\uc740 \uad00\uacc4\uc640 \ud2b9\uc815\ud55c \ub0a0\uc758 \uc0c1\ud669\uc774 \uc791\ud488\uc758 \ubc30\uacbd\uc5d0 \uc788\ub2e4. \uae00\uc528\ub97c \ub2e4 \uc77d\uc9c0 \ubabb\ud574\ub3c4 \ub204\uad70\uac00\uc758 \ub9d0\uc5d0 \ub2e4\uc2dc \ub9d0\uc744 \uac74\ub128 \uc7a5\uba74\uc774\ub77c\ub294 \ud2c0\uc740 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc655\uacfc \uc138\uc790\ub77c\ub294 \uc9c0\uc704\ub3c4 \ub2e8\uc21c\ud55c \uac00\uc871\uc758 \ub300\ud654\uc640 \ub2e4\ub978 \ubb38\ub9e5\uc744 \ub9cc\ub4e0\ub2e4. \ud559\uc2b5\uc758 \uc790\ub9ac\uc640 \uad00\uc6d0\ub4e4\uc774 \ud568\uaed8 \uc788\ub294 \uc0c1\ud669\uc5d0\uc11c \uc2dc\uac00 \uc9c0\uc5b4\uc84c\ub2e4\ub294 \uae30\ub85d\uc774 \ub0a8\uc544 \uc788\ub2e4. \ub2e4\ub9cc \uadf8 \uc790\ub9ac\uc5d0 \uc788\ub358 \uc0ac\ub78c\ub4e4\uc758 \uc2e4\uc81c \ud45c\uc815\uacfc \ub300\uc0ac\ub97c \uc0c1\uc0c1\uc73c\ub85c \ucc44\uc6cc \ub123\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub0a8\uc740 \ub0a0\uc9dc\uc640 \ud589\ub3d9\uc744 \ub530\ub77c\uac00\uba74 \uae30\ub150\ud560 \uc77c\uc744 \uae00\ub85c \uc62e\uae30\ub294 \ub2f9\uc2dc\uc758 \uc120\ud0dd\uc774 \ubcf4\uc778\ub2e4. \uc774 \ud604\ud310\uc740 \ub098\ubb34 \uae00\uc790\ub97c \ub530\ub85c \uc870\uac01\ud574 \ud310\uc5d0 \ubd99\uc778 \ubc29\uc2dd\uc774\ub77c\uace0 \ubc15\ubb3c\uad00\uc740 \uc124\uba85\ud55c\ub2e4. \ud3c9\ud3c9\ud55c \uba74\uc744 \uba39\uc73c\ub85c \ucc44\uc6b0\uac70\ub098 \ubc14\ud0d5\uc744 \ud30c\ub0b4\ub294 \uac83\uacfc \uc81c\uc791 \uacfc\uc815\uc774 \ub2e4\ub974\ub2e4. \uae00\uc790\uc758 \ubaa8\uc591\uc744 \uac1c\ubcc4 \ubd80\ud488\uc73c\ub85c \ub9cc\ub4e4\uc5b4 \uc790\ub9ac\ub97c \ub9de\ucd94\ub294 \uc77c\uc774 \ud544\uc694\ud588\ub2e4. \uc644\uc131\ub41c \ubb38\uc7a5\uc744 \uc77d\uc744 \ub54c\uc5d0\ub294 \uc798 \ub4dc\ub7ec\ub098\uc9c0 \uc54a\ub294 \uc870\ub9bd\uc758 \uc2dc\uac04\uc774 \uc788\ub294 \uac83\uc774\ub2e4. \ubd99\uc778 \uae00\uc790\ub294 \uba74\uc5d0\uc11c \ub192\uc774\uac00 \uc0dd\uae34\ub2e4. \uadf8\ub798\uc11c \uae00\uc528\ub294 \ub73b\uc744 \uc804\ud558\ub294 \ud45c\uc9c0\uc774\uba74\uc11c \ub450\uaed8\uc640 \uadf8\ub9bc\uc790\ub97c \uac00\uc9c4 \ud615\uc0c1\uc774\uae30\ub3c4 \ud558\ub2e4. \uc2e4\uc81c \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uc815\uba74\ubfd0 \uc544\ub2c8\ub77c \uac00\uc7a5\uc790\ub9ac\uc640 \uae00\uc790 \uc8fc\ubcc0\uc744 \uc0b4\ud3b4\ubcf4\uba74 \uadf8 \uad6c\uc870\ub97c \uc0dd\uac01\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4\uc758 \ube5b\ub9cc\uc73c\ub85c \uc815\ud655\ud55c \ub450\uaed8\ub098 \uc811\ucc29 \ubc29\uc2dd\uc744 \uc0c8\ub85c \ud310\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc81c\uc791 \ubc29\uc2dd\uc740 \ubc15\ubb3c\uad00 \uc124\uba85\uc744 \uadfc\uac70\ub85c \uc77d\ub294\ub2e4. \uc815\ud5cc\uc9d1 \uc548\uc758 \uac19\uc740 \uc2dc\ub294 \uc800\uc220\uc758 \ud750\ub984 \uc18d\uc5d0 \ub193\uc778\ub2e4. \ud604\ud310\uc740 \ud55c \uacf5\uac04\uc5d0 \uac78\uc5b4 \uadf8 \ubb38\uc7a5\uc744 \uacc4\uc18d \ubcf4\uc774\uac8c \ud55c\ub2e4. \ub0b4\uc6a9\uc774 \uac19\uc544\ub3c4 \ud398\uc774\uc9c0\ub97c \ub118\uaca8 \ub9cc\ub098\ub294 \ubc29\uc2dd\uacfc \uace0\uac1c\ub97c \ub4e4\uc5b4 \ub9c8\uc8fc\ud558\ub294 \ubc29\uc2dd\uc740 \ub2e4\ub974\ub2e4. \uc5b4\ub290 \uac83\uc774 \ub354 \uc9c4\uc9dc \uae30\ub85d\uc778\uc9c0 \uace0\ub974\uae30\ubcf4\ub2e4 \uc11c\ub85c \ub2e4\ub978 \ud615\ud0dc\uac00 \ubb34\uc5c7\uc744 \ub0a8\uae30\ub294\uc9c0 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uacf5\uac04\uc5d0 \ub193\uc774\ub294 \uae00\uc740 \uc0ac\ub78c\ub4e4\uc758 \uc774\ub3d9\uacfc \uc2dc\uc120\uc758 \ub192\uc774\ub3c4 \ub9cc\ub098\uac8c \ub41c\ub2e4. \ub2e4\ub9cc \uc774 \uc720\ubb3c\ub9cc\uc73c\ub85c \uc6d0\ub798 \uac78\ub838\ub358 \ubaa8\ub4e0 \uc704\uce58\uc640 \uad00\ub78c \uc0c1\ud669\uc744 \uc54c \uc218\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubb38\uc7a5\uc744 \ub098\ubb34 \uae00\uc790\ub85c \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \uad6c\uccb4\uc801\uc778 \ubb3c\uc131\uc744 \uba3c\uc800 \ubcf8\ub2e4. \ubb38\ud559\uc774 \uc885\uc774\uc758 \ud398\uc774\uc9c0 \ubc16\uc73c\ub85c \ub098\uac00 \uac74\ucd95\uacfc \uc7a5\uc2dd\uc758 \uc77c\ubd80\uac00 \ub420 \uc218\ub3c4 \uc788\uc5c8\ub2e4\ub294 \uc810\uc774 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \ud55c\uc790\ub97c \ubaa8\ub450 \ud574\ub3c5\ud558\uc9c0 \ubabb\ud558\uba74 \uc720\ubb3c \uc55e\uc5d0\uc11c \ud560 \uc77c\uc774 \uc5c6\ub2e4\uace0 \ub290\ub07c\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uae00\uc790\ub97c \ubd99\uc778 \uad6c\uc870\uc640 \ubb38\uc7a5 \uc904\uc758 \ubc30\uc5f4, \uc81c\ubaa9\uacfc \uc124\uba85\uc758 \uad00\uacc4\ub97c \uba3c\uc800 \ubcfc \uc218 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc758 \ubc88\uc5ed\uacfc \ud574\uc124\uc744 \uacc1\ub4e4\uc774\uba74 \ub0b4\uc6a9\uc73c\ub85c \ub4e4\uc5b4\uac08 \uae38\ub3c4 \uc0dd\uae34\ub2e4. \uc77d\ub294 \ub2a5\ub825\uacfc \ubb3c\uac74\uc744 \ubcf4\ub294 \uacbd\ud5d8\uc774 \uc11c\ub85c \ub3c4\uc6b8 \uc218 \uc788\ub2e4. \ud604\ud310\uc740 \uc2dc\ub97c \uae30\uc5b5\ud558\uac8c \ud558\ub294 \ub9e4\uccb4\uc774\uba74\uc11c \uc7a5\uc778\uc758 \uc190\uc744 \uac70\uce5c \ub098\ubb34 \ubb3c\uac74\uc774\ub2e4. \uc655\uacfc \uc138\uc790\uc758 \uae00\uc4f0\uae30, \ucc45\uc73c\ub85c \ub0a8\uc740 \uae30\ub85d, \uac1c\ubcc4 \uae00\uc790\ub97c \uc870\uac01\ud55c \uc81c\uc791\uc774 \ud55c \ud45c\uba74\uc5d0 \uacb9\uce5c\ub2e4. \uae00\uc790 \ud558\ub098\uac00 \ud310\uc5d0\uc11c \uc870\uae08 \uc19f\uc544 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c\uba74 \ubb38\uc7a5\uc774 \ub2e8\uc21c\ud788 \uc801\ud600 \uc788\ub2e4\ub294 \ub9d0\ub3c4 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \ub4e4\ub9b0\ub2e4. \uc758\ubbf8\uc640 \uc7ac\ub8cc\ub97c \ud568\uaed8 \ub9cc\ub098\ub294 \uac10\uc0c1\uc774 \uac00\ub2a5\ud574\uc9c4\ub2e4. \ub9cc\ub4dc\ub294 \ubc29\ubc95\ub3c4 \ub208\uc5ec\uaca8\ubcfc \ub9cc\ud558\ub2e4. \ubc15\ubb3c\uad00\uc740 \uae00\uc790\ub97c \ub530\ub85c \ub098\ubb34\ub85c \uc870\uac01\ud55c \ub4a4 \ubd99\uc600\ub2e4\uace0 \ud55c\ub2e4. \ud3c9\ud3c9\ud55c \ud310\uc5d0 \ubd93\uc73c\ub85c \uc4f0\ub294 \ubc29\ubc95\uacfc \ub2ec\ub9ac \uae00\uc790 \uc790\uccb4\uac00 \uc791\uc740 \ubd80\ud488\uc774 \ub418\ub294 \uc148\uc774\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uae00\uc790 \ud558\ub098\uc758 \uac00\uc7a5\uc790\ub9ac\ub97c \ub530\ub77c\ubcf4\uc790. \uc2dc\uc758 \ub73b\uc744 \ubaa8\ub450 \ubc88\uc5ed\ud558\uc9c0 \uc54a\uc544\ub3c4, \ubb38\uc7a5\uc744 \uc785\uccb4\uc801\uc778 \ubb3c\uac74\uc73c\ub85c \ubc14\uafb8\ub294 \uc190\uae38\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ub204\uad70\uac00\uc758 \ub2f5\uc2dc\uac00 \ucc45\uc758 \ud55c \ud398\uc774\uc9c0\uc640 \ub098\ubb34\ud310\uc758 \ud55c \uc904\ub85c \uac01\uac01 \ub0a8\uc558\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc774 \ud604\ud310\uc744 \uc870\uae08 \ub2e4\ub974\uac8c \ubcf4\uac8c \ud55c\ub2e4."}, {"id": "pride-prejudice-first-impressions", "title": "\uc624\ub9cc\uacfc \ud3b8\uacac \u2014 \ucc98\uc74c \ubcf8 \uc778\uc0c1\uc744 \ubbff\uc5b4\ub3c4 \ub420\uae4c", "summary": "\uc5d8\ub9ac\uc790\ubca0\uc2a4\uc640 \ub2e4\uc544\uc2dc\uc758 \uad00\uacc4\ub97c \ud1b5\ud574 \uc624\uc2a4\ud2f4\uc774 \ubcf4\uc5ec \uc8fc\ub294 \uc0ac\ub791\uacfc \uc0ac\ud68c\uc758 \uc870\uac74\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/pride-prejudice-first-impressions/index.html", "image": "../media/pride-prejudice-first-impressions.jpg", "alt": "1913\ub144 Jane Austen: Her Life and Letters \uc218\ub85d \uc81c\uc778 \uc624\uc2a4\ud2f4 \ucd08\uc0c1 \uc7ac\ud604\ub3c4\ud310", "text": "\uc624\ub9cc\uacfc \ud3b8\uacac \u2014 \ucc98\uc74c \ubcf8 \uc778\uc0c1\uc744 \ubbff\uc5b4\ub3c4 \ub420\uae4c \uc0ac\ub791 \uc774\uc57c\uae30 \uc548\uc5d0 \ub4e4\uc5b4 \uc788\ub294 \ud310\ub2e8\uc758 \uc2b5\uad00 \uc5d8\ub9ac\uc790\ubca0\uc2a4\uc640 \ub2e4\uc544\uc2dc\uc758 \uad00\uacc4\ub97c \ud1b5\ud574 \uc624\uc2a4\ud2f4\uc774 \ubcf4\uc5ec \uc8fc\ub294 \uc0ac\ub791\uacfc \uc0ac\ud68c\uc758 \uc870\uac74\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \ubb34\ub3c4\ud68c\uc5d0\uc11c \ub204\uad70\uac00 \ub098\ub97c \ub300\uc218\ub86d\uc9c0 \uc54a\uac8c \uc5ec\uae30\ub294 \ub9d0\uc744 \ud588\ub2e4\uace0 \uc0dd\uac01\ud574 \ubcf4\uc790. \uadf8 \uc0ac\ub78c\uc758 \ub2e4\uc74c \ud589\ub3d9\ub3c4 \uc27d\uac8c \uc88b\uac8c \ubcf4\uc774\uc9c0 \uc54a\uc744 \uac83\uc774\ub2e4. \uc81c\uc778 \uc624\uc2a4\ud2f4\uc758 \u300e\uc624\ub9cc\uacfc \ud3b8\uacac\u300f\uc740 \uadf8\ub7f0 \uccab\uc778\uc0c1\uc774 \uad73\uc5b4\uc9c0\ub294 \uc18d\ub3c4\uc640, \uadf8\uac83\uc744 \uace0\uce58\ub294 \ub370 \ud544\uc694\ud55c \uc2dc\uac04\uc744 \uc0ac\ub791 \uc774\uc57c\uae30 \uc18d\uc5d0 \ub123\uc740 \uc791\ud488\uc774\ub2e4. 1813\ub144\uc5d0 \ucd9c\uac04\ub41c \uc18c\uc124\uc5d0\ub294 \uc804\uc7c1\ud130\ubcf4\ub2e4 \uac70\uc2e4\uacfc \uc2dd\ud0c1, \uc0b0\ucc45\uae38\uc774 \uc790\uc8fc \ub098\uc628\ub2e4. \ud558\uc9c0\ub9cc \uc870\uc6a9\ud55c \uc7a5\uc18c\ub77c\uace0 \uc774\ud574\uad00\uacc4\uae4c\uc9c0 \uc791\uc9c0\ub294 \uc54a\ub2e4. \uc0ac\ub791\uc744 \uace0\ub974\ub294 \uc77c\uc5d0 \uc7ac\uc0b0\uacfc \uc0c1\uc18d, \uac00\uc871\uc758 \ud3c9\ud310\uc774 \ub530\ub77c\ubd99\ub294\ub2e4. \uc544\ub798\uc5d0\ub294 \uc8fc\uc694 \uc0ac\uac74\uacfc \uacb0\ub9d0\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4. \ubca0\ub137 \ubd80\ubd80\uc5d0\uac8c\ub294 \uc81c\uc778, \uc5d8\ub9ac\uc790\ubca0\uc2a4, \uba54\ub9ac, \ud0a4\ud2f0, \ub9ac\ub514\uc544\ub77c\ub294 \ub2e4\uc12f \ub538\uc774 \uc788\ub2e4. \uac00\uae4c\uc6b4 \uc800\ud0dd\uc5d0 \ubd80\uc720\ud55c \ub3c5\uc2e0 \ub0a8\uc790 \ube59\ub9ac\uac00 \uc774\uc0ac \uc624\uc790 \uc5b4\uba38\ub2c8\ub294 \ub538\ub4e4\uc758 \uc7a5\ub798\ub97c \ub5a0\uc62c\ub9b0\ub2e4. \ubb34\ub3c4\ud68c\uc5d0\uc11c \ube59\ub9ac\uc640 \ub9cf\ub538 \uc81c\uc778\uc740 \uc11c\ub85c \ud638\uac10\uc744 \ub290\ub07c\uc9c0\ub9cc, \ube59\ub9ac\uc758 \uce5c\uad6c \ub2e4\uc544\uc2dc\ub294 \ucc28\uac11\uace0 \uac70\ub9cc\ud558\uac8c \ubcf4\uc778\ub2e4. \uc5d8\ub9ac\uc790\ubca0\uc2a4\ub294 \uc790\uc2e0\uc744 \ub0ae\uac8c \ud3c9\uac00\ud558\ub294 \ub2e4\uc544\uc2dc\uc758 \ub9d0\uc744 \ub4e3\uace0 \ubc18\uac10\uc744 \ud488\ub294\ub2e4. \uc774\ud6c4 \ub3c5\uc790\ub294 \uc7ac\uce58 \uc788\ub294 \uc5d8\ub9ac\uc790\ubca0\uc2a4\uc758 \ub208\uc73c\ub85c \ub2e4\uc544\uc2dc\ub97c \ubcf4\ub294 \uc77c\uc774 \ub9ce\ub2e4. \uc8fc\uc778\uacf5\uacfc \ud568\uaed8 \uc6c3\uace0 \ud310\ub2e8\ud558\ub2e4 \ubcf4\uba74, \uc6b0\ub9ac\uac00 \uac00\uc9c4 \uc815\ubcf4\ub3c4 \ud55c\ucabd\uc73c\ub85c \uae30\uc6b8\uc5b4 \uc788\uc744 \uc218 \uc788\ub2e4\ub294 \uc810\uc744 \uc78a\uae30 \uc27d\ub2e4. \ubca0\ub137\uac00\uc758 \uc7ac\uc0b0\uc740 \uc815\ud574\uc9c4 \uc0c1\uc18d \uc870\uac74 \ub54c\ubb38\uc5d0 \uc544\ub4e4\uc774 \uc5c6\ub294 \uacbd\uc6b0 \ub0a8\uc790 \uce5c\ucc99 \ucf5c\ub9b0\uc2a4\uc5d0\uac8c \ub118\uc5b4\uac00\uac8c \ub418\uc5b4 \uc788\ub2e4. \uc5b4\uba38\ub2c8\uc758 \ud638\ub4e4\uac11\uc5d0\ub294 \uc6b0\uc2a4\uc6b4 \uba74\ub3c4 \uc788\uc9c0\ub9cc \ub538\ub4e4\uc758 \uc0dd\ud65c \uae30\ubc18\uc744 \uac71\uc815\ud558\ub294 \ud604\uc2e4\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \ub2e4\ub9cc \uc774\ub97c \ub2f9\uc2dc \ubaa8\ub4e0 \uc5ec\uc131\uc774 \uc7ac\uc0b0\uc744 \uc0c1\uc18d\ubc1b\uc744 \uc218 \uc5c6\uc5c8\ub2e4\ub294 \ub73b\uc73c\ub85c \ud655\ub300\ud558\uba74 \uc548 \ub41c\ub2e4. \uc791\ud488 \uc18d \uc774 \uc9d1\uc548\uc5d0 \uac78\ub9b0 \uc870\uac74\uc774 \ubb38\uc81c\ub2e4. \ucf5c\ub9b0\uc2a4\uac00 \uccad\ud63c\ud588\uc744 \ub54c \uc5d8\ub9ac\uc790\ubca0\uc2a4\ub294 \uac70\uc808\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uce5c\uad6c \uc0ec\ub7ff\uc740 \uadf8\uc640 \uacb0\ud63c\ud55c\ub2e4. \uac19\uc740 \uc120\ud0dd\uc744 \ud558\uc9c0 \uc54a\uc558\ub2e4\uace0 \uc0ec\ub7ff\uc744 \ub2e8\uc9c0 \uacc4\uc0b0\uc801\uc778 \uc0ac\ub78c\uc73c\ub85c \uce58\ubd80\ud558\uba74 \uc791\ud488\uc774 \ubcf4\uc5ec \uc8fc\ub294 \ud3ed\uc774 \uc881\uc544\uc9c4\ub2e4. \uc0ac\ub791\uc744 \uae30\ub2e4\ub9b4 \uc5ec\uc720\uc640 \uc548\uc815\ub41c \uc0dd\ud65c\uc744 \ud655\ubcf4\ud560 \uae30\ud68c\uac00 \ub204\uad6c\uc5d0\uac8c\ub098 \ub611\uac19\uc774 \uc8fc\uc5b4\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4\ub294 \uac83\uc774\ub2e4. \uc7a5\uad50 \uc704\ucef4\uc740 \ub2e4\uc815\ud55c \ud0dc\ub3c4\ub85c \uc5d8\ub9ac\uc790\ubca0\uc2a4\uc5d0\uac8c \uc811\uadfc\ud558\uace0, \ub2e4\uc544\uc2dc\uc5d0\uac8c \ubd80\ub2f9\ud55c \ub300\uc6b0\ub97c \ubc1b\uc558\ub2e4\uace0 \ub9d0\ud55c\ub2e4. \uc774\ubbf8 \ub2e4\uc544\uc2dc\ub97c \uc2eb\uc5b4\ud558\ub358 \uc5d8\ub9ac\uc790\ubca0\uc2a4\uc5d0\uac8c\ub294 \ubbff\uae30 \uc26c\uc6b4 \uc774\uc57c\uae30\ub2e4. \ubc18\uba74 \ub2e4\uc544\uc2dc\ub294 \uc810\ucc28 \uadf8\uc5d0\uac8c \ub04c\ub9ac\uc9c0\ub9cc \uc790\uc2e0\uc758 \uacc4\uae09\uc758\uc2dd\uacfc \ubca0\ub137 \uac00\uc871\uc5d0 \ub300\ud55c \ud3c9\uac00\ub97c \ucda9\ubd84\ud788 \ub118\uc5b4\uc11c\uc9c0 \ubabb\ud55c\ub2e4. \ub2e4\uc544\uc2dc\uc758 \uccab \uccad\ud63c\uc740 \uc0ac\ub791 \uace0\ubc31\uc774\uba74\uc11c \ub3d9\uc2dc\uc5d0 \uc0c1\ub300 \uac00\uc871\uc758 \ub0ae\uc740 \uc9c0\uc704\ub97c \ub4e4\uba39\uc774\ub294 \ub9d0\uc774 \ub41c\ub2e4. \uc5d8\ub9ac\uc790\ubca0\uc2a4\ub294 \uac70\uc808\ud558\uace0, \uc81c\uc778\uacfc \ube59\ub9ac \uc0ac\uc774\ub97c \uac08\ub77c\ub193\uc740 \uc77c\uacfc \uc704\ucef4\uc5d0 \uad00\ud55c \uc77c\uae4c\uc9c0 \ube44\ub09c\ud55c\ub2e4. \ub2e4\uc544\uc2dc\ub294 \ud3b8\uc9c0\ub97c \uc368 \uc790\uc2e0\uc758 \ud589\ub3d9\uacfc \uc704\ucef4\uc758 \uacfc\uac70\ub97c \uc124\uba85\ud55c\ub2e4. \uc5ec\uae30\uc11c \ud3b8\uc9c0\ub294 \uac10\ub3d9\uc801\uc778 \uc7a5\uc2dd\ubcf4\ub2e4, \ub3c5\uc790\uac00 \uc54c\uace0 \uc788\ub358 \uc0ac\uc2e4\uc744 \ub2e4\uc2dc \uc810\uac80\ud558\uac8c \ud558\ub294 \uc790\ub8cc\uc5d0 \uac00\uae5d\ub2e4. \ud3b8\uc9c0\ub97c \uc77d\uc740 \uc5d8\ub9ac\uc790\ubca0\uc2a4\ub294 \uc704\ucef4\uc5d0 \ub300\ud55c \uc790\uc2e0\uc758 \ud310\ub2e8\uc774 \uc5bc\ub9c8\ub098 \ud638\uac10\uc5d0 \uae30\ub300\uace0 \uc788\uc5c8\ub294\uc9c0 \ub3cc\uc544\ubcf8\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub2e4\uc544\uc2dc\uc758 \ubd88\ucf8c\ud55c \ud0dc\ub3c4\uae4c\uc9c0 \ud55c\uaebc\ubc88\uc5d0 \uc815\ub2f9\ud654\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub294 \ub2e4\ub978 \uc0ac\ub78c\uc744 \ub300\ud558\ub294 \ubc29\uc2dd\uc744 \ubc14\uafb8\uc5b4\uc57c \ud558\uace0, \uc5d8\ub9ac\uc790\ubca0\uc2a4\ub3c4 \uc790\uc2e0\uc774 \ubcf4\uace0 \uc2f6\uc740 \uac83\ub9cc \ubcf4\uc558\uc744 \uac00\ub2a5\uc131\uc744 \ubc1b\uc544\ub4e4\uc5ec\uc57c \ud55c\ub2e4. \ud6c4\uc5d0 \ub2e4\uc544\uc2dc\uc758 \uc800\ud0dd \ud3a8\ubc8c\ub9ac\ub97c \ubc29\ubb38\ud558\uba74\uc11c \uc5d8\ub9ac\uc790\ubca0\uc2a4\ub294 \ud558\uc778\ub4e4\uc758 \ud3c9\uac00\uc640 \uadf8\uc758 \ub2ec\ub77c\uc9c4 \ud0dc\ub3c4\ub97c \uc811\ud55c\ub2e4. \ubd80\uc720\ud55c \uc9d1\uc744 \ubcf4\uc558\uc73c\ub2c8 \ub9c8\uc74c\uc774 \ubc14\ub00c\uc5c8\ub2e4\ub294 \uc124\uba85\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud558\ub2e4. \ucc98\uc74c\uc758 \ub9d0, \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc758 \uc99d\uc5b8, \uc2e4\uc81c \ud589\ub3d9\uc744 \ud568\uaed8 \ube44\uad50\ud558\uac8c \ub418\uc5c8\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uc0c1\ub300\ub97c \uc774\ud574\ud558\ub294 \uadfc\uac70\uac00 \ub113\uc5b4\uc9c0\ub294 \uac83\uc774\ub2e4. \ub9c9\ub0b4 \ub9ac\ub514\uc544\uac00 \uc704\ucef4\uacfc \ud568\uaed8 \ub5a0\ub098\ub294 \uc0ac\uac74\uc740 \ud55c \uc0ac\ub78c\uc758 \uc5f0\uc560 \ubb38\uc81c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uacb0\ud63c\ud558\uc9c0 \uc54a\uc740 \ub3d9\ud589\uc774 \uc54c\ub824\uc9c0\uba74 \uac00\uc871 \uc804\uccb4\uc758 \ud3c9\ud310\uacfc \ub2e4\ub978 \ub538\ub4e4\uc758 \ud63c\uc778\uc5d0\ub3c4 \ud070 \ud0c0\uaca9\uc774 \uc0dd\uae38 \uc218 \uc788\ub294 \uc0ac\ud68c\ub2e4. \ub2e4\uc544\uc2dc\ub294 \ubb38\uc81c\ub97c \uc218\uc2b5\ud558\uace0 \ub450 \uc0ac\ub78c\uc758 \uacb0\ud63c\uc774 \uc774\ub8e8\uc5b4\uc9c0\ub294 \ub370 \uac1c\uc785\ud558\uc9c0\ub9cc, \ucc98\uc74c\uc5d0\ub294 \uc790\uc2e0\uc758 \uc5ed\ud560\uc744 \ub4dc\ub7ec\ub0b4\uc9c0 \uc54a\ub294\ub2e4. \uc774 \ud589\ub3d9\uc740 \uc5d8\ub9ac\uc790\ubca0\uc2a4\uc5d0\uac8c \uadf8\uc758 \uc131\uaca9\uc744 \ub2e4\uc2dc \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uccab \uccad\ud63c\uc5d0\uc11c \uc790\uae30 \uac10\uc815\uc744 \uc55e\uc138\uc6b0\ub358 \uc0ac\ub78c\uacfc \uc9c0\uae08\uc758 \ud589\ub3d9 \uc0ac\uc774\uc5d0 \ucc28\uc774\uac00 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ub3d9\uc2dc\uc5d0 \uc18c\uc124\uc740 \uacb0\ud63c\uc774 \uc131\ub9bd\ud588\ub2e4\uace0 \ud574\uc11c \uc704\ucef4\uacfc \ub9ac\ub514\uc544\uc758 \uad00\uacc4\uac00 \ud6cc\ub96d\ud574\uc84c\ub2e4\uace0 \ud3ec\uc7a5\ud558\uc9c0\ub3c4 \uc54a\ub294\ub2e4. \ubaa8\ub4e0 \ud63c\uc778\uc774 \uac19\uc740 \ud589\ubcf5\uc758 \uc99d\uac70\ub294 \uc544\ub2c8\ub2e4. \uc81c\uc778\uacfc \ube59\ub9ac\ub294 \ub2e4\uc2dc \ub9cc\ub098 \uacb0\ud63c\ud558\uace0, \uc5d8\ub9ac\uc790\ubca0\uc2a4\uc640 \ub2e4\uc544\uc2dc \uc5ed\uc2dc \uc11c\ub85c\uc758 \ubcc0\ud654\ub97c \ud655\uc778\ud55c \ub4a4 \ud568\uaed8\ud558\uae30\ub85c \ud55c\ub2e4. \ub2e4\uc544\uc2dc\uc758 \uce5c\ucc99 \ub808\uc774\ub514 \uce90\uc11c\ub9b0\uc774 \uc2e0\ubd84 \ucc28\uc774\ub97c \ub0b4\uc138\uc6cc \ubc18\ub300\ud558\ub294 \uc7a5\uba74\uc5d0\uc11c\ub294, \ub204\uac00 \uacb0\ud63c\uc744 \uacb0\uc815\ud560 \uad8c\ub9ac\uac00 \uc788\ub294\uc9c0\ub3c4 \ubb38\uc81c\uac00 \ub41c\ub2e4. \uc0ac\ub791 \uc774\uc57c\uae30\uc758 \uacb0\ub9d0 \uc548\uc5d0 \uac1c\uc778\uc758 \ud310\ub2e8\uacfc \uc0ac\ud68c\uc801 \uc704\uacc4\uc758 \ucda9\ub3cc\uc774 \ub0a8\uc544 \uc788\ub2e4. \ub2e4\uc544\uc2dc\ub294 \uc624\ub9cc, \uc5d8\ub9ac\uc790\ubca0\uc2a4\ub294 \ud3b8\uacac\uc774\ub77c\uace0 \ub531 \ub098\ub204\uba74 \uc678\uc6b0\uae30 \ud3b8\ud558\ub2e4. \uadf8\ub7ec\ub098 \ub450 \uc0ac\ub78c\uc740 \uac01\uae30 \uc790\ubd80\uc2ec\uacfc \uc120\uc785\uacac\uc744 \ub4dc\ub7ec\ub0b8\ub2e4. \uc774 \uc791\ud488\uc758 \uc990\uac70\uc6c0\uc740 \ub2e8\uc810\uc744 \ud558\ub098\uc529 \ubc30\uc815\ud558\ub294 \ub370 \uc788\uae30\ubcf4\ub2e4, \ub611\ub611\ud55c \uc0ac\ub78c\ub3c4 \ud2c0\ub9ac\uace0 \uadf8\uac83\uc744 \uc778\uc815\ud558\uba70 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4\ub294 \uacfc\uc815\uc744 \uc9c0\ucf1c\ubcf4\ub294 \ub370 \uc788\ub2e4. \uc624\uc2a4\ud2f4\uc740 \ub204\uac00 \ub9d0\uc744 \ub3c5\ucc28\uc9c0\ud558\uace0 \ub204\uad6c\uc758 \ub9d0\uc744 \ubabb \uc54c\uc544\ub4e3\ub294\uc9c0, \uc608\uc758 \ubc14\ub978 \ubb38\uc7a5 \uc18d\uc5d0 \uc5b4\ub5a4 \ubb34\ub840\ud568\uc774 \uc228\uc5b4 \uc788\ub294\uc9c0 \ubcf4\uc5ec \uc900\ub2e4. \uc0ac\uac74\ub9cc \uc694\uc57d\ud558\uba74 \uc0ac\ub77c\uc9c0\ub294 \uc7ac\ubbf8\ub2e4. \ub2e4\uc74c\uc5d0 \uac70\uc2e4\uc758 \uae34 \ub300\ud654\uac00 \ub098\uc624\uba74 \uc815\ubcf4\ub97c \ube68\ub9ac \uc5bb\uc73c\ub824 \ud558\uae30\ubcf4\ub2e4, \uadf8 \ub9d0\uc774 \uc0c1\ub300\uc5d0\uac8c \uc5b4\ub5bb\uac8c \ub4e4\ub9b4\uc9c0 \ud55c \ubc88 \uc0dd\uac01\ud574 \ubcf4\uc790. \ud568\uaed8 \uc2e4\uc740 \ucd08\uc0c1\uc740 \uc5d8\ub9ac\uc790\ubca0\uc2a4\uac00 \uc544\ub2c8\ub77c \uc791\uac00 \uc81c\uc778 \uc624\uc2a4\ud2f4\uc758 \uc5ed\uc0ac\uc801 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \uc18c\uc124 \uc18d \uc778\ubb3c\uc758 \uc5bc\uad74\uc740 \ub3c5\uc790\uc758 \ubaab\uc73c\ub85c \ub0a8\uaca8 \ub450\uc5b4\ub3c4 \uc88b\ub2e4. \uccab\uc778\uc0c1\uc740 \ub204\uad6c\ub098 \uac16\uc9c0\ub9cc \uadf8\uac83\uc744 \ub05d\uae4c\uc9c0 \uc9c0\ucf1c\uc57c \ud560 \uc758\ubb34\ub294 \uc5c6\ub2e4\ub294 \uc0dd\uac01, \uc774 \uc624\ub798\ub41c \uc5f0\uc560\uc18c\uc124\uc774 \uc624\ub298\uc758 \ub9cc\ub0a8\uc5d0\ub3c4 \uac74\ub124\ub294 \uc77d\uc744\uac70\ub9ac\ub2e4."}, {"id": "queen-spades-three-cards-and-obsession", "title": "\uc2a4\ud398\uc774\ub4dc\uc758 \uc5ec\uc655 \u2014 \ud655\uc2e4\ud55c \uc138 \uc7a5\uc744 \uc54c\uba74 \uc0b6\ub3c4 \uc774\uae38 \uc218 \uc788\uc744\uae4c", "summary": "\uc548\uc804\ud558\uac8c \ubd80\uc790\uac00 \ub418\ub824\ub358 \uccad\ub144\uc774 \uc138 \uc7a5\uc758 \ube44\ubc00\uc744 \uc887\uc73c\uba70 \ud0c0\uc778\uc744 \uc774\uc6a9\ud558\uace0 \ubb34\ub108\uc9c0\ub294 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/queen-spades-three-cards-and-obsession/index.html", "image": "../media/queen-spades-three-cards-and-obsession.png", "alt": "\uce74\ub4dc \ud0c1\uc790 \uc55e\uc758 \uc7a5\uad50\uc640 \uc2a4\ud398\uc774\ub4dc \uc5ec\uc655\uc744 \uadf8\ub9b0 \ud478\uc2dc\ud0a8 \uc18c\uc124 \uad00\ub828 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uc2a4\ud398\uc774\ub4dc\uc758 \uc5ec\uc655 \u2014 \ud655\uc2e4\ud55c \uc138 \uc7a5\uc744 \uc54c\uba74 \uc0b6\ub3c4 \uc774\uae38 \uc218 \uc788\uc744\uae4c \uc138 \uc7a5\uc758 \ube44\ubc00\uacfc \ub9ac\uc790\ubca0\ud0c0\uc758 \ud3b8\uc9c0, \uc131\uacf5\uc774 \ud0a4\uc6b4 \ud655\uc2e0\uc758 \uacb0\ub9d0 \uc548\uc804\ud558\uac8c \ubd80\uc790\uac00 \ub418\ub824\ub358 \uccad\ub144\uc774 \uc138 \uc7a5\uc758 \ube44\ubc00\uc744 \uc887\uc73c\uba70 \ud0c0\uc778\uc744 \uc774\uc6a9\ud558\uace0 \ubb34\ub108\uc9c0\ub294 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \ud478\uc2dc\ud0a8\uc758 \u300c\uc2a4\ud398\uc774\ub4dc\uc758 \uc5ec\uc655\u300d\uc5d0\ub294 \ubc18\ub4dc\uc2dc \uc774\uae30\ub294 \uce74\ub4dc \uc138 \uc7a5\uc758 \ube44\ubc00\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc774 \uc9e7\uc740 \uc18c\uc124\uc5d0\uc11c \ub354 \ubb34\uc11c\uc6b4 \uac83\uc740 \uce74\ub4dc\uc758 \ub9c8\ubc95\ubcf4\ub2e4 \ube44\ubc00\uc744 \ubbff\ub294 \uc0ac\ub78c\uc774 \ubcc0\ud574 \uac00\ub294 \ubaa8\uc2b5\uc774\ub2e4. \uacc4\uc0b0\uc744 \uc911\uc2dc\ud558\ub358 \uccad\ub144\uc774 \ud0c0\uc778\uc758 \uc0b6\uc744 \uc218\ub2e8\uc73c\ub85c \uc0bc\uace0 \ub05d\ub0b4 \ubb34\ub108\uc9c0\ub294 \uacfc\uc815\uc744 \uacb0\ub9d0\uae4c\uc9c0 \ub530\ub77c\uac00 \ubcf4\uc790. \ud398\ud14c\ub974\ubd80\ub974\ud06c\uc758 \uc80a\uc740 \uc7a5\uad50 \uac8c\ub974\ub9cc\uc740 \ub3c4\ubc15\ud310\uc5d0 \uc624\ub798 \uc549\uc544 \uc788\uc73c\uba74\uc11c\ub3c4 \uc9c1\uc811 \ub3c8\uc744 \uac78\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub294 \ub0a8\uc758 \uacbd\uae30\ub97c \uc9c0\ucf1c\ubcf4\ub294 \ub370 \ud765\ubbf8\uac00 \uc788\uc9c0\ub9cc, \ud544\uc694\ud55c \uac83\uc744 \uc783\uc73c\uba74\uc11c \uc5ec\ubd84\uc744 \uc5bb\uc73c\ub824 \ud558\uc9c0\ub294 \uc54a\uaca0\ub2e4\ub294 \ud0dc\ub3c4\ub97c \ubcf4\uc778\ub2e4. \uc774 \uc2e0\uc911\ud568\uc740 \uc695\ub9dd\uc774 \uc5c6\ub2e4\ub294 \ub73b\uacfc \ub2e4\ub974\ub2e4. \uac8c\ub974\ub9cc\uc740 \ubd80\uc790\uac00 \ub418\uace0 \uc2f6\uc73c\uba74\uc11c \uc190\uc2e4\uc740 \ud53c\ud558\uace0 \uc2f6\ub2e4. \uadf8\ub7f0 \uadf8\uc5d0\uac8c \ud55c \uc7a5\uad50\uac00 \ub4e4\ub824\uc8fc\ub294 \ub299\uc740 \ubc31\uc791\ubd80\uc778\uc758 \uacfc\uac70\ub294 \uac15\ud55c \uc720\ud639\uc774 \ub41c\ub2e4. \uc704\ud5d8 \uc5c6\uc774 \uc774\uae38 \uc218 \uc788\ub2e4\ub294 \uc774\uc57c\uae30\uac00 \uacc4\uc0b0\uc758 \ubb38 \uc548\uc73c\ub85c \ub4e4\uc5b4\uc624\ub294 \uac83\uc774\ub2e4. \uc7a5\uad50 \ud1b0\uc2a4\ud0a4\uc5d0 \ub530\ub974\uba74 \uadf8\uc758 \ud560\uba38\ub2c8\ub294 \uc80a\uc740 \uc2dc\uc808 \ud30c\ub9ac\uc5d0\uc11c \ud070\ub3c8\uc744 \uc783\uc5c8\ub2e4. \uadf8\ub54c \uc0dd\uc81c\ub974\ub9f9 \ubc31\uc791\uc5d0\uac8c \uc774\uae30\ub294 \uce74\ub4dc\uc758 \ube44\ubc00\uc744 \ubc30\uc6cc \uc190\uc2e4\uc744 \ub9cc\ud68c\ud588\ub2e4\ub294 \uac83\uc774\ub2e4. \uc774\uc57c\uae30\ub294 \uae30\uc774\ud558\uc9c0\ub9cc \ud655\uc778\ud560 \uc218 \uc788\ub294 \uc2e4\ud5d8 \uacb0\uacfc\ub85c \uc81c\uc2dc\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \uac8c\ub974\ub9cc\uc740 \uc774 \uac04\uadf9\uc744 \uac74\ub108\ub6f4\ub2e4. \uadf8\ub294 \uc0ac\uc2e4 \uc5ec\ubd80\ub97c \ub530\uc9c0\ub294 \ub300\uc2e0 \ube44\ubc00\uc744 \uc54c\uc544\ub0bc \ubc29\ubc95\uc744 \uad81\ub9ac\ud55c\ub2e4. \uc791\ud488 \uc18d \uc0ac\ub78c\ub4e4\uc740 \uc0ac\uad50 \uc790\ub9ac\uc758 \ud765\ubbf8\ub85c\uc6b4 \uc77c\ud654\ub85c \ub4e3\uc9c0\ub9cc, \uadf8\uc5d0\uac8c\ub294 \uc0b6 \uc804\uccb4\ub97c \ubc14\uafc0 \uc124\uacc4\ub3c4\uac00 \ub41c\ub2e4. \uac19\uc740 \uc774\uc57c\uae30\uac00 \ub4e3\ub294 \uc774\uc758 \uc695\ub9dd\uc5d0 \ub530\ub77c \ub2e4\ub978 \ud798\uc744 \uac16\ub294\ub2e4. \ub3c4\ubc15\ud310\uc5d0\uc11c \uc624\ub798 \uad6c\uacbd\ud588\ub2e4\ub294 \uc0ac\uc2e4 \uc5ed\uc2dc \uc911\uc694\ud558\ub2e4. \uac8c\ub974\ub9cc\uc740 \uaddc\uce59\uc744 \uc804\ud600 \ubaa8\ub974\ub294 \uc21c\uc9c4\ud55c \uc678\ubd80\uc778\uc774 \uc544\ub2c8\ub2e4. \uc704\ud5d8\uc744 \uc54c\uace0\ub3c4 \uc608\uc678\uc801\uc778 \ube44\ubc00\ub9cc \uc5bb\uc73c\uba74 \uc790\uc2e0\uc740 \uadf8 \uc704\ud5d8\uc5d0\uc11c \ubc97\uc5b4\ub0a0 \uc218 \uc788\ub2e4\uace0 \ubbff\ub294 \uc0ac\ub78c\uc774\uae30 \ub54c\ubb38\uc5d0 \ud30c\uad6d\uc740 \ub354\uc6b1 \ub0a0\uce74\ub86d\uac8c \ub2e4\uac00\uc628\ub2e4. \ubc31\uc791\ubd80\uc778\uc758 \uc9d1\uc5d0\ub294 \uc758\ud0c1\ud574 \uc0ac\ub294 \uc80a\uc740 \uc5ec\uc131 \ub9ac\uc790\ubca0\ud0c0\uac00 \uc788\ub2e4. \uac8c\ub974\ub9cc\uc740 \ucc3d\uac00\uc758 \uadf8\ub140\uc5d0\uac8c \uc811\uadfc\ud558\uace0 \ud3b8\uc9c0\ub97c \ubcf4\ub0b4\uba70 \uc0ac\ub791\uc744 \ud638\uc18c\ud55c\ub2e4. \ub2f5\ub2f5\ud55c \uc0dd\ud65c\uc5d0\uc11c \ubc97\uc5b4\ub098\uace0 \uc2f6\uc5c8\ub358 \ub9ac\uc790\ubca0\ud0c0\ub294 \uadf8\ub97c \ubbff\uace0 \uc9d1\uc5d0 \ub4e4\uc5b4\uc62c \ubc29\ubc95\uc744 \uc54c\ub824 \uc900\ub2e4. \uadf8\ub7ec\ub098 \uac8c\ub974\ub9cc\uc774 \uc9c4\uc815\uc73c\ub85c \ub9cc\ub098\ub824\ub294 \uc0ac\ub78c\uc740 \ub9ac\uc790\ubca0\ud0c0\uac00 \uc544\ub2c8\ub77c \ubc31\uc791\ubd80\uc778\uc774\ub2e4. \ub3c5\uc790\ub294 \uc5f0\uc560\uc758 \ubb38\ubc95\uc73c\ub85c \ubcf4\uc600\ub358 \ud589\ub3d9\uc774 \ube44\ubc00\uc744 \uc5bb\uae30 \uc704\ud55c \uc808\ucc28\uc600\uc74c\uc744 \uc54c\uac8c \ub41c\ub2e4. \uc0c1\ub300\uc758 \uae30\ub300\ub97c \uc774\uc6a9\ud558\ub294 \uc21c\uac04, \ubd80\ub97c \ud5a5\ud55c \uc695\ub9dd\uc740 \uc774\ubbf8 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc190\ud574\ub97c \uc785\ud788\uace0 \uc788\ub2e4. \uac8c\ub974\ub9cc\uc740 \ubc31\uc791\ubd80\uc778\uc744 \uae30\ub2e4\ub838\ub2e4\uac00 \uce74\ub4dc\uc758 \ube44\ubc00\uc744 \uc694\uad6c\ud55c\ub2e4. \ubd80\ud0c1\uacfc \uc555\ubc15 \ub05d\uc5d0 \uad8c\ucd1d\uae4c\uc9c0 \uaebc\ub0b8\ub2e4. \ubc31\uc791\ubd80\uc778\uc740 \uacf5\ud3ec \uc18d\uc5d0\uc11c \uc8fd\uace0, \uadf8\ub294 \uc6d0\ud558\ub294 \ub300\ub2f5\uc744 \ub4e3\uc9c0 \ubabb\ud55c\ub2e4. \ub4a4\uc5d0 \uad8c\ucd1d\uc5d0 \ud0c4\ud658\uc774 \uc5c6\uc5c8\ub2e4\ub294 \uc124\uba85\uc774 \ub098\uc624\uc9c0\ub9cc \uadf8\uac83\uc774 \uc704\ud611\uc758 \uacb0\uacfc\ub97c \uc9c0\uc6b0\uc9c0\ub294 \ubabb\ud55c\ub2e4. \ub9ac\uc790\ubca0\ud0c0\ub294 \uc790\uc2e0\uc774 \uc774\uc6a9\ub2f9\ud588\uc74c\uc744 \uae68\ub2eb\ub294\ub2e4. \uc0ac\ub791\uc758 \ubaa8\ud5d8\uc73c\ub85c \uc0c1\uc0c1\ud588\ub358 \ub9cc\ub0a8\uc774 \uc8fd\uc74c\uacfc \uc5bd\ud78c \uc0ac\uac74\uc774 \ub41c \uac83\uc774\ub2e4. \uc774 \uc7a5\uba74\uc744 \uc77d\uc73c\uba74 \uac8c\ub974\ub9cc\uc774 \uc783\uc744 \uc704\ud5d8\uc774 \uc5c6\ub2e4\uace0 \uc0dd\uac01\ud55c \uc2b9\ubd80\uc5d0 \uc2e4\uc81c\ub85c\ub294 \ub204\uac00 \ub300\uac00\ub97c \uce58\ub974\uace0 \uc788\uc5c8\ub294\uc9c0 \ubcf4\uc778\ub2e4. \ub9ac\uc790\ubca0\ud0c0\uc758 \ucc98\uc9c0\ub3c4 \ub2e8\uc21c\ud55c \ubd80\uc720\ud55c \uc9d1 \uc544\uac00\uc528\uc640 \ub2e4\ub974\ub2e4. \ub0a8\uc758 \uc9d1\uc5d0 \uc758\uc9c0\ud558\uba70 \uae30\ubd84\uc744 \ub9de\ucd94\uc5b4\uc57c \ud558\ub294 \uc0dd\ud65c\uc740 \ud3b8\uc9c0\uc5d0 \uae30\ub300\ub97c \uac78\uac8c \ub9cc\ub4dc\ub294 \ubc30\uacbd\uc774\ub2e4. \uac8c\ub974\ub9cc\uc758 \ud589\ub3d9\uc740 \ubc14\ub85c \uadf8 \ubd88\ud3c9\ub4f1\uacfc \uace0\ub9bd\uc744 \ud1b5\ub85c\ub85c \uc0bc\ub294\ub2e4. \uc7a5\ub840 \ub4a4 \uac8c\ub974\ub9cc\uc5d0\uac8c \uc8fd\uc740 \ubc31\uc791\ubd80\uc778\uc774 \ub098\ud0c0\ub098 \uc138 \uc7a5\uc744 \uc54c\ub824 \uc900\ub2e4. \uc22b\uc790 3\uacfc 7, \uc5d0\uc774\uc2a4\ub2e4. \ud558\ub8e8\uc5d0 \ud55c \uc7a5\uc529 \uc0ac\uc6a9\ud558\uace0 \uadf8 \ub4a4\uc5d0\ub294 \ub2e4\uc2dc \ub3c4\ubc15\ud558\uc9c0 \ub9d0\ub77c\ub294 \uc870\uac74\uc774 \ubd99\uc73c\uba70, \ub9ac\uc790\ubca0\ud0c0\uc640 \uacb0\ud63c\ud558\ub77c\ub294 \uc694\uad6c\ub3c4 \ub098\uc628\ub2e4. \ub2e4\ub9cc \uc18c\uc124\uc740 \uc774 \ubc29\ubb38\uc744 \ub3c5\uc790\uac00 \uac80\uc99d\ud560 \uc218 \uc788\ub294 \uac1d\uad00\uc801 \uc0ac\uac74\uc73c\ub85c \ub2e8\ub2e8\ud788 \uace0\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc220\uacfc \ud765\ubd84, \uc9d1\ucc29\uc5d0 \ud729\uc2f8\uc778 \uac8c\ub974\ub9cc\uc758 \uacbd\ud5d8\uc744 \ud1b5\ud574 \uc804\ub2ec\ud55c\ub2e4. \uc720\ub839\uc758 \ubcf5\uc218\ub85c\ub3c4, \uc695\ub9dd\uc774 \ub9cc\ub4e4\uc5b4 \ub0b8 \ud655\uc2e0\uc758 \ubd95\uad34\ub85c\ub3c4 \uc77d\uc744 \uc5ec\uc9c0\uac00 \ub0a8\ub294\ub2e4. \uac8c\ub974\ub9cc\uc740 \ud070 \ud310\ub3c8\uc744 \uac78\uace0 \uccab\ub0a0 3\uc73c\ub85c, \ub2e4\uc74c \ub0a0 7\ub85c \uc774\uae34\ub2e4. \uc131\uacf5\uc774 \uac70\ub4ed\ub418\uba74\uc11c \ucc98\uc74c\uc758 \uae30\uc774\ud55c \uc774\uc57c\uae30\ub294 \uadf8\uc5d0\uac8c \ud655\uc2e4\ud55c \ubc95\uce59\uc774 \ub41c\ub2e4. \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \ubd88\uc5b4\ub09c \ub3c8\uae4c\uc9c0 \uac78\uace0 \uc5d0\uc774\uc2a4\uc758 \uc2b9\ub9ac\ub97c \uae30\ub2e4\ub9b0\ub2e4. \uadf8\ub7ec\ub098 \uc790\uc2e0\uc758 \ud328\ub97c \ub4a4\uc9d1\uc5c8\uc744 \ub54c \ub193\uc778 \uac83\uc740 \uc5d0\uc774\uc2a4\uac00 \uc544\ub2c8\ub77c \uc2a4\ud398\uc774\ub4dc\uc758 \uc5ec\uc655\uc774\ub2e4. \uadf8\ub294 \uce74\ub4dc \uc18d \uc5ec\uc655\uc5d0\uac8c\uc11c \ubc31\uc791\ubd80\uc778\uc758 \ud45c\uc815\uacfc \uc870\ub871\uc744 \ubcf8\ub2e4. \uc5b8\uc81c \uc5b4\ub5bb\uac8c \uc798\ubabb\ub41c \uce74\ub4dc\ub97c \uace8\ub790\ub294\uc9c0 \uba85\ucf8c\ud55c \uc124\uba85\uc740 \uc8fc\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \ud655\uc2e0\uc744 \ub5a0\ubc1b\uce58\ub358 \uacc4\uc0b0\uc774 \ub2e8 \ud55c \uc7a5\uc5d0\uc11c \ubb34\ub108\uc9c4\ub2e4. \uccab \ub450 \ubc88\uc758 \uc2b9\ub9ac\ub294 \ub3c5\uc790\uc5d0\uac8c\ub3c4 \uc720\ud639\uc774\ub2e4. \uadf8\uc804\uae4c\uc9c0 \uc758\uc2ec\uc2a4\ub7fd\ub358 \uc774\uc57c\uae30\uac00 \ub9de\ub294 \ub4ef \ubcf4\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \ud478\uc2dc\ud0a8\uc740 \uace7\ubc14\ub85c \ud2c0\ub9b0 \ubbff\uc74c\uc744 \uafb8\uc9d6\uae30\ubcf4\ub2e4 \uc131\uacf5\uc758 \uacbd\ud5d8\uc774 \ud655\uc2e0\uc744 \uc5bc\ub9c8\ub098 \ube60\ub974\uac8c \ud0a4\uc6b0\ub294\uc9c0 \uc11c\uc0ac\uc758 \uc21c\uc11c\ub85c \ubcf4\uc5ec \uc900\ub2e4. \uac8c\ub974\ub9cc\uc740 \uc815\uc2e0\uc774 \ubb34\ub108\uc9c4 \uc0c1\ud0dc\ub85c 3\uacfc 7, \uc5d0\uc774\uc2a4\uc640 \uc5ec\uc655\uc744 \uc911\uc5bc\uac70\ub9b0\ub2e4. \ubc18\uba74 \ub9ac\uc790\ubca0\ud0c0\uc640 \ud1b0\uc2a4\ud0a4\uc758 \uc774\ud6c4 \uc0dd\ud65c\uc740 \ube44\uad50\uc801 \uac74\uc870\ud558\uac8c \uc804\ud574\uc9c4\ub2e4. \uc138\uc0c1\uc774 \uc8fc\uc778\uacf5\uc758 \ube44\uadf9\uc744 \uc911\uc2ec\uc73c\ub85c \ubaa8\ub450 \uba48\ucd94\uc9c0\ub294 \uc54a\ub294\ub2e4\ub294 \uc810\uc774 \ub0c9\uc815\ud55c \uc5ec\uc6b4\uc744 \ub0a8\uae34\ub2e4. \uc774 \uc791\ud488\uc740 \ucc28\uc774\ucf65\uc2a4\ud0a4\uc758 \ub3d9\uba85 \uc624\ud398\ub77c\ub85c\ub3c4 \uc54c\ub824\uc84c\uc9c0\ub9cc \ub450 \uc791\ud488\uc758 \uc0ac\uac74\uacfc \uacb0\ub9d0\uc740 \uac19\uc9c0 \uc54a\ub2e4. \ud478\uc2dc\ud0a8\uc758 \uc18c\uc124\uc5d0\uc11c\ub294 \uc0ac\ub791\ubcf4\ub2e4 \ube44\ubc00\uc744 \ud0dd\ud55c \uc120\ud0dd, \ud0c0\uc778\uc744 \ubaa9\uc801\uc5d0 \uc885\uc18d\uc2dc\ud0a8 \ud0dc\ub3c4, \uc6b0\uc5f0\uc744 \uc9c0\ubc30\ud560 \uc218 \uc788\ub2e4\ub294 \ubbff\uc74c\uc744 \ud568\uaed8 \uc77d\uc744 \ud544\uc694\uac00 \uc788\ub2e4. \uce74\ub4dc\uc758 \uc5ec\uc655\uacfc \ub299\uc740 \ubc31\uc791\ubd80\uc778\uc758 \uc5bc\uad74\uc774 \uacb9\uce58\ub294 \uc21c\uac04\uc5d0\ub294 \ub3c8\uacfc \uc0ac\ub78c\uc774 \ub2e4\uc2dc \ub9cc\ub09c\ub2e4. \uac8c\ub974\ub9cc\uc740 \uc0ac\ub78c\uc5d0\uac8c\uc11c \ube44\ubc00\ub9cc \ub5bc\uc5b4 \uc5bb\uc73c\ub824 \ud588\uc9c0\ub9cc \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \uc0ac\ub78c\uc758 \ud45c\uc815\uc774 \uce74\ub4dc\uc758 \uc22b\uc790\ub97c \ubc00\uc5b4\ub0b8\ub2e4. \uc774 \uc5f0\uacb0\uc774 \uc81c\ubaa9\uc744 \uacb0\ub9d0\uae4c\uc9c0 \ub04c\uace0 \uac04\ub2e4."}, {"id": "raphael-belle-jardiniere", "title": "\uc544\ub984\ub2e4\uc6b4 \uc815\uc6d0\uc0ac \u2014 \uadf8\ub9bc \uc18d \uc5ec\uc778\uc740 \ub204\uad6c\uc77c\uae4c", "summary": "\ub8e8\ube0c\ub974 \uc791\ud488\uc758 \uc778\ubb3c\uacfc \ubab8\uc9d3\uc744 \uc54c\uc544\ubcf4\uba70 \uc885\uad50 \ud68c\ud654\uc5d0 \ub2e4\uac00\uac00 \ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/raphael-belle-jardiniere/index.html", "image": "../media/raphael-belle-jardiniere.jpg", "alt": "\ub77c\ud30c\uc5d8\ub85c, \uc544\ub984\ub2e4\uc6b4 \uc815\uc6d0\uc0ac \u00b7 \uc61b \ub8e8\ube0c\ub974 \ub3c4\ub85d Plate VII", "text": "\uc544\ub984\ub2e4\uc6b4 \uc815\uc6d0\uc0ac \u2014 \uadf8\ub9bc \uc18d \uc5ec\uc778\uc740 \ub204\uad6c\uc77c\uae4c \ub77c\ud30c\uc5d8\ub85c\uc758 \uc131\ubaa8\uc790\ud654\ub97c \ubcf4\ub294 \uc138 \uac00\uc9c0 \ub2e8\uc11c \ub8e8\ube0c\ub974 \uc791\ud488\uc758 \uc778\ubb3c\uacfc \ubab8\uc9d3\uc744 \uc54c\uc544\ubcf4\uba70 \uc885\uad50 \ud68c\ud654\uc5d0 \ub2e4\uac00\uac00 \ubd05\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \u2018\uc544\ub984\ub2e4\uc6b4 \uc815\uc6d0\uc0ac\u2019\ub77c\ub294 \uc81c\ubaa9\uc744 \ub4e4\uc73c\uba74 \uaf43\ubc2d\uc744 \uac00\uafb8\ub294 \uc5ec\uc778\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \ub77c\ud30c\uc5d8\ub85c\uc758 \uadf8\ub9bc\uc5d0\ub294 \uc131\ubaa8 \ub9c8\ub9ac\uc544\uc640 \uc544\uae30 \uc608\uc218, \uc5b4\ub9b0 \uc138\ub840 \uc694\ud55c\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \uc815\uc6d0 \uc77c\uc744 \uc124\uba85\ud558\ub294 \uadf8\ub9bc\uc774 \uc544\ub2c8\ub77c \ud480\uacfc \uaf43\uc774 \uc788\ub294 \ud48d\uacbd \uc18d\uc5d0 \uc885\uad50\uc801 \uc778\ubb3c\ub4e4\uc744 \ub193\uc740 \uc131\ubaa8\uc790\ud654\ub2e4. \uc885\uad50 \ud68c\ud654\uac00 \ub0af\uc124\uc5b4\ub3c4 \uc778\ubb3c \uc774\ub984\uc744 \uc870\uae08 \uc54c\uace0 \uc2dc\uc120\uacfc \ubab8\uc9d3\uc744 \ub530\ub77c\uac00\uba74 \ucda9\ubd84\ud788 \ub4e4\uc5b4\uac08 \uc218 \uc788\ub2e4. \uc774 \uadf8\ub9bc\uc5d0\uc11c\ub294 \uad50\ub9ac\uc758 \ubaa9\ub85d\ubcf4\ub2e4 \ud55c \uc5b4\ub978\uacfc \ub450 \uc544\uc774 \uc0ac\uc774\uc758 \uad00\uacc4\uac00 \uba3c\uc800 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uac00\uc6b4\ub370 \uc549\uc544 \uc788\ub294 \uc5ec\uc778\uc774 \ub9c8\ub9ac\uc544\uc774\uace0, \uacc1\uc5d0 \uc11c \uc788\ub294 \uc544\uc774\uac00 \uc608\uc218, \ub2e4\ub978 \ucabd\uc5d0\uc11c \ubb34\ub98e\uc744 \uad7d\ud78c \uc544\uc774\uac00 \uc138\ub840 \uc694\ud55c\uc774\ub2e4. \uc138\ub840 \uc694\ud55c\uc740 \uc131\uc11c\uc5d0\uc11c \uc608\uc218\uc758 \uae38\uc744 \uc900\ube44\ud558\ub294 \uc778\ubb3c\ub85c \ub4f1\uc7a5\ud55c\ub2e4. \uc5ec\uae30\uc11c\ub294 \ub450 \uc544\uc774\uac00 \uc5b4\ub9b0 \uc2dc\uc808 \ud55c \ud654\uba74 \uc548\uc5d0 \ud568\uaed8 \ub193\uc5ec \uc788\ub2e4. \uc774\ub294 \uc5b4\ub5a4 \uc21c\uac04\uc744 \uc0ac\uc9c4\ucc98\ub7fc \uae30\ub85d\ud55c \uc7a5\uba74\uc774\ub77c\uae30\ubcf4\ub2e4 \uae30\ub3c5\uad50 \ud68c\ud654\uac00 \uc778\ubb3c\ub4e4\uc758 \uad00\uacc4\ub97c \ubcf4\uc5ec \uc8fc\ub294 \ubc29\uc2dd\uc73c\ub85c \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc138 \uc0ac\ub78c\uc758 \uc774\ub984\uc744 \uc54c\uba74 \ub2e8\uc21c\ud788 \uc5ec\uc778\uacfc \uc544\uc774\ub4e4\uc774 \uc788\ub2e4\ub294 \uccab\uc778\uc0c1\uc5d0\uc11c \ud55c \uac78\uc74c \ub098\uc544\uac00, \uc65c \ubab8\uc9d3\uc774 \uc11c\ub85c\ub97c \ud5a5\ud558\ub294\uc9c0\ub3c4 \uc0b4\ud544 \uc218 \uc788\ub2e4. \ud504\ub791\uc2a4\uc5b4 \ud45c\uc81c \ub77c \ubca8 \uc790\ub974\ub514\ub2c8\uc5d0\ub974\ub294 \u2018\uc544\ub984\ub2e4\uc6b4 \uc815\uc6d0\uc0ac\u2019\ub77c\ub294 \ub73b\uc73c\ub85c \ubd88\ub9b0\ub2e4. \ud558\uc9c0\ub9cc \uc81c\ubaa9\uc5d0 \uc815\uc6d0\uc0ac\uac00 \uc788\ub2e4\uace0 \ud574\uc11c \ub9c8\ub9ac\uc544\uac00 \uc815\uc6d0 \uc77c\uc744 \ud558\ub294 \uc9c1\uc5c5\uc778\uc73c\ub85c \ub4f1\uc7a5\ud55c\ub2e4\uace0 \uc77d\uc73c\uba74 \uc7a5\uba74\uc744 \ub193\uce58\uac8c \ub41c\ub2e4. \uaf43\uacfc \ud480\uc774 \uc788\ub294 \ubc30\uacbd\uacfc \uc774 \uc81c\ubaa9\uc744 \ud568\uaed8 \ubc1b\uc544\ub4e4\uc774\ub294 \ud3b8\uc774 \uc790\uc5f0\uc2a4\ub7fd\ub2e4. \uc774\ubc88 \uc790\ub8cc\ub9cc\uc73c\ub85c \ub204\uac00 \uc5b8\uc81c \uc774 \ubcc4\uce6d\uc744 \ucc98\uc74c \ubd99\uc600\ub294\uc9c0\uae4c\uc9c0 \ud655\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc791\ud488\uc758 \ub0b4\uc6a9\uacfc \uc81c\ubaa9\uc758 \ub9d0\ub73b\uc740 \uc124\uba85\ud560 \uc218 \uc788\uc5b4\ub3c4 \ubcc4\uce6d\uc758 \ud0c4\uc0dd \uacbd\uc704\ub294 \ub610 \ub2e4\ub978 \uc99d\uac70\uac00 \ud544\uc694\ud55c \uc77c\uc774\ub2e4. \uc791\ud488 \uc774\ub984\uc744 \uc544\ub294 \uac83\uc774 \ubaa8\ub4e0 \ub0b4\ub825\uc744 \uc548\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub9c8\ub9ac\uc544\uc758 \uba38\ub9ac\ub97c \uc704\ucabd \uaf2d\uc9d3\uc810\ucc98\ub7fc \ubcf4\uace0 \uc591\uc606\uacfc \uc544\ub798\ub85c \ub208\uc744 \ub0b4\ub824 \ubcf4\uc790. \ub9c8\ub9ac\uc544\uc640 \ub450 \uc544\uc774\uac00 \uc774\ub8e8\ub294 \ub369\uc5b4\ub9ac\uac00 \ub113\uc5b4\uc9c0\uba70 \ud654\uba74 \uc544\ub798\uc5d0 \uc790\ub9ac\ub97c \uc7a1\ub294\ub2e4. \uc0bc\uac01\ud615 \uac19\uc740 \uad6c\uc131\uc774\ub77c\uace0 \uc124\uba85\ud558\ub294 \uc774\uc720\ub97c \ubcf5\uc7a1\ud55c \ub3c4\ud615 \uc5c6\uc774\ub3c4 \ub290\ub084 \uc218 \uc788\ub2e4. \uc774\ub294 \uc2e4\uc81c\ub85c \uc120\uc744 \uadf8\uc5b4 \uc815\ud655\ud55c \uc0bc\uac01\ud615\uc744 \uc99d\uba85\ud558\ub77c\ub294 \ubb38\uc81c\uac00 \uc544\ub2c8\ub2e4. \uc778\ubb3c\ub4e4\uc774 \ud769\uc5b4\uc9c0\uc9c0 \uc54a\uace0 \ud558\ub098\uc758 \ubb34\ub9ac\ub85c \ubcf4\uc774\ub294 \uc548\uc815\uac10\uc5d0 \uc8fc\ubaa9\ud558\ub294 \ubc29\ubc95\uc774\ub2e4. \uc544\uc774\ub4e4\uc758 \uc791\uc740 \uc6c0\uc9c1\uc784\uacfc \ub9c8\ub9ac\uc544\uc758 \ud070 \ubab8\uc774 \ud568\uaed8 \ud654\uba74\uc758 \uade0\ud615\uc744 \ub9cc\ub4e0\ub2e4. \ub9c8\ub9ac\uc544\ub294 \uad00\uac1d\uc5d0\uac8c \uc124\uba85\ud558\ub4ef \uc815\uba74\uc744 \ubc14\ub77c\ubcf4\uae30\ubcf4\ub2e4 \uc544\uc774\uc5d0\uac8c \ub208\uae38\uc744 \ub454\ub2e4. \uc608\uc218\uc640 \uc694\ud55c\uc758 \uc790\uc138 \uc5ed\uc2dc \uc11c\ub85c\uc758 \uc874\uc7ac\ub97c \uc758\uc2dd\ud558\ub294 \uad00\uacc4 \uc548\uc5d0 \ub193\uc5ec \uc788\ub2e4. \uba3c\uc800 \uac01\uc790\uc758 \uc5bc\uad74\uc744 \ubcf4\uace0, \ub2e4\uc74c\uc5d0\ub294 \uc5bc\uad74\ub4e4\uc774 \uc5b4\ub514\ub85c \ud5a5\ud558\ub294\uc9c0 \ub530\ub77c\uac00 \ubcf4\uc790. \uc774\ub984\ud45c \uc138 \uac1c\uc600\ub358 \uc7a5\uba74\uc774 \uad00\uacc4\ub97c \uac00\uc9c4 \uc0ac\ub78c\ub4e4\uc758 \ubaa8\uc2b5\uc73c\ub85c \ubc14\ub010\ub2e4. \ub9c8\ub9ac\uc544\uc758 \uc190\uacfc \uc544\uc774\uc758 \ubab8\uc774 \uac00\uae4c\uc774 \ub193\uc778 \ubd80\ubd84\uc5d0\uc11c\ub294 \ub3cc\ubd04\uc758 \ubab8\uc9d3\uc744 \ub290\ub084 \uc218 \uc788\ub2e4. \ubb3c\ub860 \uc774 \uadf8\ub9bc\uc758 \uc8fc\uc81c\ub294 \uc885\uad50\uc801\uc774\ub2e4. \uadf8\ub807\uc9c0\ub9cc \uc5b4\ub978\uc774 \uc544\uc774\ub97c \uc9c0\ucf1c\ubcf4\uace0 \uc544\uc774\uac00 \uac00\uae4c\uc774 \uae30\ub300\ub294 \uacbd\ud5d8\uc744 \ud1b5\ud574 \ub0af\uc120 \uc8fc\uc81c\uc5d0 \ub2e4\uac00\uac08 \uc218\ub3c4 \uc788\ub2e4. \uce5c\uc219\ud55c \ubab8\uc9d3\uacfc \uc885\uad50\uc801 \uc758\ubbf8\uac00 \ud568\uaed8 \uc874\uc7ac\ud55c\ub2e4. \uc5b4\ub9b0 \uc694\ud55c\uc774 \uc9c0\ub2cc \uc2ed\uc790\uac00 \ubaa8\uc591\uc758 \ud45c\uc9c0\ub294 \uc778\ubb3c\uc744 \uc54c\uc544\ubcf4\ub294 \ub2e8\uc11c\ub2e4. \uae30\ub3c5\uad50 \uadf8\ub9bc\uc5d0\ub294 \uc778\ubb3c\uacfc \uc5f0\uacb0\ub41c \ubb3c\uac74\uc774\ub098 \uc790\uc138\uac00 \uc790\uc8fc \uc0ac\uc6a9\ub41c\ub2e4. \uae00\ub85c \uc774\ub984\uc744 \uc801\uc9c0 \uc54a\uc544\ub3c4 \uad00\uac1d\uc774 \ub300\uc0c1\uc744 \uc54c\uc544\ubcf4\ub3c4\ub85d \ub3d5\ub294 \ud68c\ud654\uc758 \uc5b8\uc5b4\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \ub41c\ub2e4. \uc2ed\uc790\uac00\ub294 \uc608\uc218\uc758 \ud6d7\ub0a0 \uc218\ub09c\ub3c4 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \ud3c9\ud654\ub85c\uc6b4 \uc5b4\ub9b0 \uc2dc\uc808\uc758 \uc7a5\uba74 \uc548\uc5d0 \uc55e\uc73c\ub85c\uc758 \uc774\uc57c\uae30\ub97c \uc554\uc2dc\ud558\ub294 \ud45c\uc9c0\uac00 \ub4e4\uc5b4 \uc788\ub294 \uc148\uc774\ub2e4. \uadf8\ub9bc\uc774 \ucc28\ubd84\ud558\uace0 \uc544\ub984\ub2f5\ub2e4\uace0 \ud574\uc11c \uadf8 \uc758\ubbf8\uae4c\uc9c0 \uc624\uc9c1 \ud3c9\uc628\ud568\uc5d0 \uba38\ubb34\ub974\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc544\uc774\ub4e4\uc758 \ubaa8\uc2b5\uc744 \ubcf4\uba70 \uc774\ud6c4\uc758 \uc11c\uc0ac\ub97c \ud568\uaed8 \uc0dd\uac01\ud558\ub294 \uac10\uc0c1\ub3c4 \uac00\ub2a5\ud558\ub2e4. \ub9c8\ub9ac\uc544\uc758 \uc637\uc5d0\uc11c\ub294 \ubd89\uc740\uc0c9\uacfc \ud478\ub978\uc0c9\uc774 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc778\ubb3c\uc744 \ub610\ub837\ud558\uac8c \ubb36\uc5b4 \uc8fc\ub294 \uc0c9\uc758 \uc911\uc2ec\uc774\ub2e4. \ub4a4\ucabd\uc758 \ud48d\uacbd\uc73c\ub85c \uc2dc\uc120\uc744 \uc62e\uacbc\ub2e4\uac00 \ub2e4\uc2dc \uc637\uc73c\ub85c \ub3cc\uc544\uc624\uba74 \uac00\uae4c\uc6b4 \uc778\ubb3c\ub4e4\uc774 \uc5b4\ub5bb\uac8c \uc55e\uc5d0 \uc790\ub9ac \uc7a1\ub294\uc9c0 \ub290\ub084 \uc218 \uc788\ub2e4. \ub77c\ud30c\uc5d8\ub85c\ub294 \ub974\ub124\uc0c1\uc2a4\uc758 \ud654\uac00\uc774\uba70 \uc774 \uc791\ud488\uc5d0\uc11c\ub294 \uc778\ubb3c\uc758 \ubd80\ub4dc\ub7ec\uc6b4 \ubab8\uc9d3\uacfc \uc548\uc815\ub41c \ubc30\uce58\uac00 \uc798 \ub4dc\ub7ec\ub09c\ub2e4. \ub2e4\ub9cc \u2018\uade0\ud615 \uc7a1\ud614\ub2e4\u2019\ub294 \ud3c9\uac00\ub97c \uc678\uc6b4 \ub4a4 \uac10\uc0c1\uc744 \ub05d\ub0b4\uae30\ubcf4\ub2e4, \uc5b4\ub5a4 \ubd80\ubd84\uc774 \uadf8 \ub290\ub08c\uc744 \ub9cc\ub4dc\ub294\uc9c0 \uc9c1\uc811 \ucc3e\uc544\ubcf4\uc790. \uc778\ubb3c \uc0ac\uc774\uc758 \uac04\uaca9\uacfc \uc637\uc758 \ub113\uc740 \uc0c9\uba74\uc774 \uad6c\uccb4\uc801\uc778 \uae38\uc7a1\uc774\uac00 \ub41c\ub2e4. \ub9c8\ub9ac\uc544\uc640 \uc608\uc218, \uc138\ub840 \uc694\ud55c\uc774 \ub204\uad6c\uc778\uc9c0\ub9cc \uc54c\uc544\ub3c4 \ucc98\uc74c\ubcf4\ub2e4 \ud6e8\uc52c \ub9ce\uc740 \uac83\uc744 \uc77d\uc744 \uc218 \uc788\ub2e4. \ub354 \uc54c\uace0 \uc2f6\ub2e4\uba74 \uc138\ub840 \uc694\ud55c\uc758 \uc5ed\ud560\uc774\ub098 \uc131\ubaa8\uc790\ud654\uc758 \uc804\ud1b5\uc73c\ub85c \ub113\ud600 \uac08 \uc218 \uc788\uc9c0\ub9cc \ucc98\uc74c\ubd80\ud130 \ubaa8\ub450 \uc54c\uc544\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud544\uc694\ud55c \uc9c0\uc2dd\uc744 \ud558\ub098 \uc5bb\uace0 \ub2e4\uc2dc \uadf8\ub9bc\uc744 \ubcf4\ub294 \uc655\ubcf5\uc774 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uc61b \ub8e8\ube0c\ub974 \ub3c4\ub85d\uc5d0 \uc218\ub85d\ub41c \uc2e4\uc81c \uc791\ud488\uc758 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \ucd5c\uc2e0 \uc2e4\ubb3c \uc0ac\uc9c4\uacfc \uc0c9\u00b7\uc138\ubd80\uac00 \uac19\ub2e4\uace0 \ubcf4\uc9c0\ub294 \ub9d0\uc790. \uc624\ub298\uc740 \uc138 \uc0ac\ub78c\uc758 \uc774\ub984\uc744 \ud655\uc778\ud558\uace0, \uc2dc\uc120\uc758 \uae38\uc744 \ub530\ub77c\uac00\uace0, \ub9c8\uc9c0\ub9c9\uc5d0 \uc2ed\uc790\uac00\ub97c \ub2e4\uc2dc \ubcf4\ub294 \uc21c\uc11c\ub85c \uac10\uc0c1\ud574 \ubcf4\uc790. \ud3c9\ud654\ub85c\uc6b4 \uc7a5\uba74 \uc18d\uc5d0 \ub2f4\uae34 \uad00\uacc4\uc640 \uc55e\uc73c\ub85c\uc758 \uc774\uc57c\uae30\uac00 \uc870\uae08\uc529 \ub4dc\ub7ec\ub0a0 \uac83\uc774\ub2e4."}, {"id": "raven-boy-light-fragments-and-night", "title": "\uae4c\ub9c8\uadc0 \uc18c\ub144 \u2014 \ube5b\uc744 \uc870\uac01\ub0b4\uc5b4 \ub0ae\uacfc \ubc24\uc744 \ub9cc\ub4e4\ub2e4", "summary": "\uc18c\ub144\uc758 \ub0a8\ucabd \uc5ec\ud589\uacfc \ube5b\uc758 \uacf5, \uae4c\ub9c8\uadc0\uc758 \ube44\ud589\uc744 1911\ub144 \uc804\uc2b9\uc9d1\uc758 \uc720\ucf58\uac15 \ud558\ub958 \uc774\uc57c\uae30\ub85c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc2e0\ud654\uc640 \ubbfc\uc18d", "categories": ["arts"], "url": "stories/raven-boy-light-fragments-and-night/index.html", "image": "../media/raven-boy-light-fragments-and-night.png", "alt": "\ub208 \ub36e\uc778 \ubd81\ucabd \ud574\uc548 \uc704\ub85c \ube5b\uc758 \uacf5\uacfc \uc791\uc740 \uc870\uac01\uc744 \uac00\uc9c0\uace0 \ub0a0\uc544\uac00\ub294 \uae4c\ub9c8\uadc0\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uae4c\ub9c8\uadc0 \uc18c\ub144 \u2014 \ube5b\uc744 \uc870\uac01\ub0b4\uc5b4 \ub0ae\uacfc \ubc24\uc744 \ub9cc\ub4e4\ub2e4 \uc720\ucf58\uac15 \ud558\ub958 \uc774\uc57c\uae30\uc5d0\uc11c \ub9cc\ub098\ub294 \ub3cc\uc544\uc628 \ube5b\uacfc \uae34 \uc5b4\ub460 \uc18c\ub144\uc758 \ub0a8\ucabd \uc5ec\ud589\uacfc \ube5b\uc758 \uacf5, \uae4c\ub9c8\uadc0\uc758 \ube44\ud589\uc744 1911\ub144 \uc804\uc2b9\uc9d1\uc758 \uc720\ucf58\uac15 \ud558\ub958 \uc774\uc57c\uae30\ub85c \uc77d\uc2b5\ub2c8\ub2e4. \uc2e0\ud654\uc640 \ubbfc\uc18d \ubb38\ud654\uc640 \uc608\uc220 \ud558\ub298\uc5d0 \uc788\ub358 \ud574\uc640 \ub2ec\uc774 \uc0ac\ub77c\uc9c0\uace0 \ubcc4\ube5b\ub9cc \ub0a8\uc558\ub2e4. \ub9c8\uc744 \uc0ac\ub78c\ub4e4\uc740 \ube5b\uc744 \ub418\ucc3e\uc73c\ub824 \ud588\uc9c0\ub9cc \ub73b\ub300\ub85c \ub418\uc9c0 \uc54a\ub294\ub2e4. \ubaa8\ub450\uac00 \uae30\ub300\ud558\ub294 \uc778\ubb3c\uc774 \uc544\ub2c8\ub77c, \ubcc4 \ub300\uc811\uc744 \ubc1b\uc9c0 \ubabb\ud558\ub358 \uace0\uc544 \uc18c\ub144\uc774 \uc790\uae30\uac00 \ud574\ubcf4\uaca0\ub2e4\uace0 \ub098\uc120\ub2e4. \uc774 \uae00\uc740 \uce90\uc11c\ub9b0 \ubca0\ub9ac \uc800\ub4dc\uc2a8\uc758 1911\ub144 \u300e\uc54c\ub798\uc2a4\uce74 \uc2e0\ud654\uc640 \uc804\uc124\u300f \uac00\uc6b4\ub370 \uc720\ucf58\uac15 \ud558\ub958 \uc804\uc2b9\uc73c\ub85c \uc18c\uac1c\ub41c \u300c\uae4c\ub9c8\uadc0\uac00 \ube5b\uc744 \uac00\uc838\uc628 \uc774\uc57c\uae30\u300d\ub97c \ub530\ub978\ub2e4. \uc720\uba85\ud55c \ub2e4\ub978 \uae4c\ub9c8\uadc0 \uc774\uc57c\uae30\uc758 \uc0c1\uc790\ub098 \ubcc0\uc2e0 \uc7a5\uba74\uacfc\ub294 \uad6c\uc131\uc774 \ub2e4\ub974\ub2e4. \uc18c\ub144\uc740 \ud3c9\uc18c\uc5d0\ub294 \ub2e4\ub978 \uc544\uc774\uc640 \uac19\uc9c0\ub9cc \uae4c\ub9c8\uadc0 \uc637\uc744 \uc785\uc73c\uba74 \uae4c\ub9c8\uadc0\uac00 \ub41c\ub2e4. \uc0ac\ub78c\uc774 \uac00\uc9c4 \uc2dc\uc120\uacfc \uc0c8\uc758 \uc774\ub3d9 \ub2a5\ub825\uc744 \uc624\uac08 \uc218 \uc788\ub294 \uc778\ubb3c\uc774\ub2e4. \uc544\uc9c1 \ub9c8\uc744\uc740 \uadf8\uc5d0\uac8c \ud070 \uae30\ub300\ub97c \uac78\uc9c0 \uc54a\ub294\ub2e4. \ube5b\uc744 \ucc3e\ub294 \uc77c\uc5d0 \uc2e4\ud328\ud55c \uc774\ub4e4\uc744 \ub180\ub9ac\uc790 \uc18c\ub144\uc740 \ucad3\uaca8\ub09c\ub2e4. \uc790\uae30 \ub2a5\ub825\uc744 \ub9d0\ud558\ub294 \uac83\uacfc \ubbff\uc74c\uc744 \uc5bb\ub294 \uac83\uc740 \ub2e4\ub978 \ubb38\uc81c\uc600\ub2e4. \uadf8\ub294 \uace7\ubc14\ub85c \ud558\ub298\ub85c \ub0a0\uc544\uc62c\ub77c \uc815\ub2f5\uc744 \ucc3e\uae30\ubcf4\ub2e4 \uba3c\uc800 \uc544\ub294 \uc0ac\ub78c\uc744 \ucc3e\uc544\uac00 \ubb3b\ub294\ub2e4. \uc18c\ub144\uc740 \uce5c\ucc99 \uc544\uc8fc\uba38\ub2c8\uc5d0\uac8c \ube5b\uc774 \uc5b4\ub514 \uc788\ub294\uc9c0 \ubb3c\uc5b4\ubcf8\ub2e4. \uc544\uc8fc\uba38\ub2c8\ub294 \ubaa8\ub978\ub2e4\uace0 \ud558\uc9c0\ub9cc \uc18c\ub144\uc740 \uc798 \uc9c0\uc5b4\uc9c4 \uc637\uc744 \ubcf4\uba70 \uc54c\uace0 \uc788\uc73c\ub9ac\ub77c\uace0 \uac70\ub4ed \ub9d0\ud55c\ub2e4. \uc5b4\ub460\uacfc \uc815\uad50\ud55c \uc190\uc77c\uc744 \uc5f0\uacb0\ud558\ub294 \uadf8\uc758 \uace0\uc9d1\uc2a4\ub7ec\uc6b4 \uc9c8\ubb38\uc774\ub2e4. \ub9c8\uce68\ub0b4 \uc544\uc8fc\uba38\ub2c8\ub294 \ub0a8\ucabd\uc73c\ub85c \uba40\ub9ac \uac00 \ubcf4\ub77c\uace0 \ud55c\ub2e4. \ubaa9\uc801\uc9c0\uc758 \uc774\ub984\uacfc \uac70\ub9ac\ub97c \uc790\uc138\ud788 \uc54c\ub824 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc18c\ub144\uc740 \ub208 \uc704\ub97c \uac78\uc744 \uc2e0\uc744 \uc2e0\uace0 \uae38\uc744 \ub5a0\ub09c\ub2e4. \uc0c8\uac00 \ub420 \uc218 \uc788\uc5b4\ub3c4 \uc5ec\ud589\uc740 \ubc1c\ub85c \uc624\ub798 \uac77\ub294 \uc2dc\uac04\uc5d0\uc11c \uc2dc\uc791\ud55c\ub2e4. \uc624\ub7ab\ub3d9\uc548 \uac19\uc740 \uc5b4\ub460\uc744 \uc9c0\ub098\uc790 \uba40\ub9ac\uc11c \ud55c \uc904\uae30 \ube5b\uc774 \ub098\ud0c0\ub09c\ub2e4. \uadf8\ub7f0\ub370 \ubcf4\uc774\ub2e4\uac00 \ub2e4\uc2dc \uc0ac\ub77c\uc9c4\ub2e4. \uc18c\ub144\uc740 \uadf8 \ubcc0\ud654 \uc790\uccb4\ub97c \ub2e8\uc11c\ub85c \uc0bc\uc544 \uac00\uae4c\uc774 \uac04\ub2e4. \ubaa9\uc801\uc9c0\ub294 \uc815\ud574\uc9c4 \ud45c\uc9c0\ud310\ubcf4\ub2e4 \ube5b\uc758 \uc6c0\uc9c1\uc784\uc73c\ub85c \ub4dc\ub7ec\ub09c\ub2e4. \uc774\uc73d\uace0 \ud55c\ucabd\uc740 \ubc1d\uace0 \ub2e4\ub978 \ucabd\uc740 \uc5b4\ub450\uc6b4 \uc5b8\ub355\uacfc \uc9d1\uc774 \ubcf4\uc778\ub2e4. \uc9d1 \uc55e\uc758 \ub0a8\uc790\uac00 \ub208\uc744 \ub192\uc774 \ud37c \uc62c\ub9b4 \ub54c\ub9c8\ub2e4 \ube5b\uc774 \uac00\ub824\uc9c0\uace0, \ub208\uc774 \ub5a8\uc5b4\uc9c0\uba74 \ub2e4\uc2dc \ubc1d\uc544\uc9c4\ub2e4. \uc54c \uc218 \uc5c6\ub358 \uae5c\ube61\uc784\uc774 \uac00\uae4c\uc774\uc5d0\uc11c\ub294 \uad6c\uccb4\uc801\uc778 \ud589\ub3d9\uc774 \ub41c\ub2e4. \uc9d1 \uac00\uae4c\uc774\uc5d0\ub294 \ud070 \ube5b\uc758 \uacf5\uc774 \uc788\ub2e4. \uc18c\ub144\uc740 \ub0a8\uc790\uc5d0\uac8c \uc65c \ub208\uc744 \ud37c\uc11c \uc790\uae30 \ub9c8\uc744\uc744 \uc5b4\ub461\uac8c \ud558\ub290\ub0d0\uace0 \ubb3b\ub294\ub2e4. \ub0a8\uc790\ub294 \ub2e8\uc9c0 \ub208\uc744 \uce58\uc6b0\uace0 \uc788\ub2e4\uace0 \ub300\ub2f5\ud55c\ub2e4. \ub450 \uc0ac\ub78c\uc740 \ub208\uc55e\uc758 \uc77c\uc744 \uc804\ud600 \ub2e4\ub974\uac8c \uc124\uba85\ud55c\ub2e4. \uc18c\ub144\uc740 \uc5b4\ub450\uc6b4 \ub9c8\uc744\uc744 \ub5a0\ub098 \uc5ec\uae30\uc11c \uc0b4\uace0 \uc2f6\ub2e4\uace0 \ub9d0\ud55c\ub2e4. \ub0a8\uc790\ub294 \ud568\uaed8 \uc9d1\uc5d0 \ub4e4\uc5b4\uac00\uc790\uba70 \uc55e\uc7a5\uc120\ub2e4. \ub530\ub73b\ud55c \ucd08\ub300\ucc98\ub7fc \ubcf4\uc774\ub294 \uc21c\uac04\uc774\uc9c0\ub9cc \uc18c\ub144\uc740 \ube5b\uc744 \uac00\uc9c0\uace0 \ub3cc\uc544\uac08 \uae30\ud68c\ub97c \ub178\ub9ac\uace0 \uc788\ub2e4. \ub0a8\uc790\uac00 \uba3c\uc800 \uc9d1 \uc548\uc73c\ub85c \ub4e4\uc5b4\uac00\uc790 \uc18c\ub144\uc740 \ube5b\uc758 \uacf5\uc744 \uc637\uc5d0 \ub123\uace0 \ub208\uc0bd\uae4c\uc9c0 \uc9d1\uc5b4 \ub4e0\ub2e4. \uadf8\ub9ac\uace0 \ubd81\ucabd\uc73c\ub85c \ub2ec\ub9b0\ub2e4. \ubc1c\uc774 \uc9c0\uce58\uc790 \uae4c\ub9c8\uadc0 \uc637\uc744 \uc785\uc5b4 \uc0c8\uac00 \ub418\uc5b4 \ub0a0\uc544\uac04\ub2e4. \uac78\uc5b4\uc628 \uac70\ub9ac\ub97c \ub2e4\ub978 \ubab8\uc73c\ub85c \ub418\uc9da\ub294 \uac83\uc774\ub2e4. \ub0a8\uc790\ub294 \ub4a4\ucad3\uc73c\uba70 \ube5b\uc740 \uac00\uc838\uac00\ub3c4 \uc88b\uc73c\ub2c8 \uc0bd\uc744 \ub3cc\ub824 \ub2ec\ub77c\uace0 \ud55c\ub2e4. \uadf8\ub7ec\ub098 \uae4c\ub9c8\uadc0\ub294 \uc790\uae30 \ub9c8\uc744\uc744 \uc5b4\ub461\uac8c \ud588\ub2e4\ub294 \uc774\uc720\ub97c \ub4e4\uba70 \uac70\uc808\ud55c\ub2e4. \uc138\uc0c1\uc5d0 \ube5b\uc744 \ub418\ub3cc\ub9b4 \uc778\ubb3c\uc774\uc9c0\ub9cc \ubaa8\ub4e0 \ud589\ub3d9\uc774 \uc810\uc796\uc740 \uc601\uc6c5\uc740 \uc544\ub2c8\ub2e4. \uae4c\ub9c8\uadc0\ub294 \ub0a0\uc544\uac00\uba70 \uacf5\uc5d0\uc11c \uc791\uc740 \ube5b \uc870\uac01\uc744 \ub5bc\uc5b4 \ub0b8\ub2e4. \uadf8\ub7ec\uba74 \ub0ae\uc774 \ub41c\ub2e4. \ub2e4\uc2dc \ud55c\ub3d9\uc548 \uc5b4\ub460\uc744 \uc9c0\ub098 \ub2e4\uc74c \uc870\uac01\uc744 \ub5bc\uba74 \ub610 \ub0ae\uc774 \ucc3e\uc544\uc628\ub2e4. \uacf5\uc744 \ud1b5\uc9f8\ub85c \ud558\ub298\uc5d0 \uac78\uc5b4 \ub450\ub294 \uacb0\ub9d0\uacfc\ub294 \ub2e4\ub978 \uc0c1\uc0c1\uc774\ub2e4. \uae34 \uc774\ub3d9\uc758 \ub9ac\ub4ec\uc774 \ubc1d\uc74c\uacfc \uc5b4\ub460\uc758 \ub9ac\ub4ec\uc744 \ub9cc\ub4e0\ub2e4. \uae4c\ub9c8\uadc0\uac00 \ube5b\uc744 \ub5bc\uc9c0 \uc54a\uace0 \uc624\ub798 \ub0a0\uc544\uac04 \uad6c\uac04\uc774 \uc788\uae30\uc5d0 \uae34 \ubc24\ub3c4 \uc0dd\uacbc\ub2e4\uace0 \uc774\uc57c\uae30\ub294 \ub9d0\ud55c\ub2e4. \ub208\uc5d0 \uc775\uc740 \uc790\uc5f0\uc758 \ubcc0\ud654\uac00 \uc5ec\ud589\uc758 \uc18d\ub3c4\uc640 \uc5f0\uacb0\ub41c\ub2e4. \ub9c8\uc744\uc5d0 \ub3c4\ucc29\ud55c \uae4c\ub9c8\uadc0\ub294 \ube5b\uc744 \uac00\uc838\uc654\ub2e4\uace0 \uc54c\ub9b0\ub2e4. \uc774\uc81c \ubc1d\uc558\ub2e4 \uc5b4\ub450\uc6cc\uc9c0\uba70 \ub0ae\uacfc \ubc24\uc774 \uc774\uc5b4\uc9c8 \uac83\uc774\ub77c\uace0 \ud55c\ub2e4. \uc790\uc2e0\uc744 \ucad3\uc544\ub0c8\ub358 \uc774\ub4e4 \uc55e\uc5d0 \ub3cc\uc544\uc624\uc9c0\ub9cc \ub2e8\uc9c0 \uc790\ub791\uc73c\ub85c\ub9cc \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc0dd\ud65c\ud560 \uc138\uc0c1\uc758 \uc870\uac74\uc774 \ub2ec\ub77c\uc84c\ub2e4. \uc774\ud6c4\uc5d0\ub3c4 \uae4c\ub9c8\uadc0\uc758 \uc774\ub3d9\uc740 \uacc4\uc18d\ub41c\ub2e4. \ubc14\ub2f7\uac00\uc758 \uc5bc\uc74c \uc704\uc5d0 \uc788\ub2e4\uac00 \ubc14\ub78c\uc5d0 \ubc00\ub824 \ubc14\ub2e4 \uac74\ub108 \ub2e4\ub978 \ub545\uc73c\ub85c \uac00\ub294 \uc7a5\uba74\uc774 \ub4a4\ub530\ub978\ub2e4. \ube5b\uc744 \ub418\ucc3e\uc740 \uc0ac\uac74\uc740 \uc5ec\ub7ec \uae4c\ub9c8\uadc0 \uc774\uc57c\uae30 \uac00\uc6b4\ub370 \ud558\ub098\uc758 \uc5ec\uc815\uc73c\ub85c \ub0a8\ub294\ub2e4. \uae4c\ub9c8\uadc0\uac00 \ube5b\uc744 \uac00\uc838\uc624\ub294 \uc774\uc57c\uae30\ub294 \uc5ec\ub7ec \uc9c0\uc5ed\uc5d0 \uc788\ub2e4. \uc774 \ucc45 \uc548\uc5d0\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc9c0\uc5ed\uc758 \uc804\uc2b9\uc774 \ub098\ub780\ud788 \uc2e4\ub824 \uc788\ub2e4. \ube44\uc2b7\ud55c \uc0c8\uc640 \ube5b\uc774 \ub098\uc628\ub2e4\uace0 \uc0ac\uac74\ub4e4\uc744 \ud55c \uc904\uac70\ub9ac\ub85c \ud569\uce58\uba74 \uac01 \uc774\uc57c\uae30\uc758 \ud2b9\uc9d5\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \uc5ec\uae30\uc11c \uc911\uc694\ud55c \ubb3c\uac74\uc740 \uc0c1\uc790\uac00 \uc544\ub2c8\ub77c \ube5b\uc758 \uacf5\uacfc \ub208\uc0bd\uc774\ub2e4. 1911\ub144 \uc218\uc9d1\ubcf8\uc758 \uc9c0\uc5ed \ud45c\uae30\ub97c \ub530\ub77c \ubc94\uc704\ub97c \ubc1d\ud788\uace0, \uadf8 \ucc45\uc758 \ub0a1\uc740 \ubbfc\uc871 \ubd84\ub958\ub97c \uc624\ub298 \uc0ac\ub78c\ub4e4 \uc804\uccb4\uc758 \uc774\ub984\ucc98\ub7fc \uc4f0\uc9c0 \uc54a\uc558\ub2e4. \ud558\ub098\uc758 \uc774\uc57c\uae30\ub85c \ubaa8\ub4e0 \ubd81\ubc29 \ubb38\ud654\ub97c \ub300\ud45c\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc774 \uc774\uc57c\uae30\ub97c \ucc9c\ubb38\ud559 \ub300\uc2e0 \uc77d\uc744 \uc790\uc5f0\uacfc\ud559 \uc124\uba85\uc73c\ub85c \uc0ac\uc6a9\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ube5b\uc758 \ubcc0\ud654\ub97c \uc0ac\ub78c\uc774 \uac77\uace0 \ub0a0\uc544\uac00\ub294 \ub9ac\ub4ec\uc73c\ub85c \uc0c1\uc0c1\ud588\ub2e4\ub294 \uc810\uc5d0\uc11c \uc7ac\ubbf8\uc788\ub2e4. \uae34 \ubc24\uc740 \uba40\ub9ac \uac00\ub294 \uae4c\ub9c8\uadc0\uc758 \uc2dc\uac04\uacfc \uacb9\uccd0\uc9c4\ub2e4. \ucc98\uc74c \uc544\ubb34\ub3c4 \uae30\ub300\ud558\uc9c0 \uc54a\uc558\ub358 \uc18c\ub144\uc740 \ubb3b\uace0 \uac78\uc5b4\uac00\uace0 \ub2ec\uc544\ub098\uba70 \uc138\uc0c1\uc744 \ubc14\uafbc\ub2e4. \uad50\ud6c8\uc744 \ud558\ub098\ub85c \uc815\ud558\uae30\ubcf4\ub2e4 \uae5c\ube61\uc774\ub294 \ube5b\uc744 \ub530\ub77c\uac00\ub294 \uc7a5\uba74\uacfc \uc0bd\uc744 \ub3cc\ub824 \ub2ec\ub77c\ub294 \uc678\uce68\uae4c\uc9c0 \ud568\uaed8 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc775\uc0b4\uacfc \ud070 \ubcc0\ud654\uac00 \uac19\uc740 \ub0a0\uac2f\uc9d3 \uc548\uc5d0 \uc788\ub2e4."}, {"id": "rembrandt-emmaus-light", "title": "\uc5e0\ub9c8\uc624\uc758 \uc21c\ub840\uc790\ub4e4 \u2014 \uc2dd\ud0c1\uc5d0\uc11c \ub0af\uc120 \uc774\ub97c \uc54c\uc544\ubcf4\ub294 \uc21c\uac04", "summary": "\uc131\uc11c\uc758 \uc7a5\uba74\uacfc \ud654\uba74 \uc18d \uc190\u00b7\uc2dc\uc120\u00b7\ube48 \uacf5\uac04\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/rembrandt-emmaus-light/index.html", "image": "../media/rembrandt-emmaus-light.jpg", "alt": "\ub818\ube0c\ub780\ud2b8\uc758 \uc5e0\ub9c8\uc624\uc758 \uc21c\ub840\uc790\ub4e4. \uc608\uc218\uc640 \ub450 \uc81c\uc790\uac00 \uc2dd\ud0c1\uc5d0 \uc549\uace0 \uc624\ub978\ucabd\uc5d0\ub294 \uc74c\uc2dd\uc744 \ub098\ub974\ub294 \uc778\ubb3c\uc774 \uc788\uc2b5\ub2c8\ub2e4.", "text": "\uc5e0\ub9c8\uc624\uc758 \uc21c\ub840\uc790\ub4e4 \u2014 \uc2dd\ud0c1\uc5d0\uc11c \ub0af\uc120 \uc774\ub97c \uc54c\uc544\ubcf4\ub294 \uc21c\uac04 \ub818\ube0c\ub780\ud2b8\uac00 \ube75\uacfc \ube5b\uc73c\ub85c \ub9cc\ub4e0 \uc870\uc6a9\ud55c \uc774\uc57c\uae30 \uc131\uc11c\uc758 \uc7a5\uba74\uacfc \ud654\uba74 \uc18d \uc190\u00b7\uc2dc\uc120\u00b7\ube48 \uacf5\uac04\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \uc5b4\ub450\uc6b4 \ubc29 \ud55c\uac00\uc6b4\ub370 \uc791\uc740 \uc2dd\ud0c1\uc774 \uc788\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \uc549\uc544 \uc788\uace0 \uc606\uc5d0\uc11c\ub294 \uc74c\uc2dd\uc744 \uac00\uc838\uc628\ub2e4. \uadf8\ub7f0\ub370 \uc774 \ud3c9\ubc94\ud55c \uc2dd\uc0ac \uc548\uc5d0\uc11c \ud568\uaed8 \uc788\ub358 \uc0ac\ub78c\uc774 \ub204\uad6c\uc778\uc9c0 \uc54c\uc544\ubcf4\ub294 \uc0ac\uac74\uc774 \uc77c\uc5b4\ub09c\ub2e4. \ub818\ube0c\ub780\ud2b8\uc758 \u3008\uc5e0\ub9c8\uc624\uc758 \uc21c\ub840\uc790\ub4e4\u3009\uc774\ub2e4. \uc774 \uc791\ud488\uc740 \ud070 \ubab8\uc9d3\uacfc \uad70\uc911\uc73c\ub85c \uc774\uc57c\uae30\ub97c \uc804\ub2ec\ud558\uc9c0 \uc54a\ub294\ub2e4. \ube75\uc744 \uc7a1\uc740 \uc190\uacfc \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc758 \ubc18\uc751, \uc778\ubb3c \uc704\ub85c \ub0a8\uaca8\uc9c4 \ub113\uc740 \ubcbd\uc774 \uc7a5\uba74\uc758 \ud798\uc744 \ub9cc\ub4e0\ub2e4. \uba3c\uc800 \ubb34\uc2a8 \uc774\uc57c\uae30\uc778\uc9c0 \uc870\uae08 \uc54c\uace0 \uadf8\ub9bc\uc744 \ubcf4\uba74 \uc870\uc6a9\ud55c \uc2dd\ud0c1\uc758 \uae34\uc7a5\uc774 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc774 \uc7a5\uba74\uc740 \ubd80\ud65c\ud55c \uc608\uc218\uac00 \uc5e0\ub9c8\uc624\ub85c \uac00\ub294 \uc81c\uc790\ub4e4\uacfc \ub9cc\ub098\ub294 \uae30\ub3c5\uad50\uc758 \uc774\uc57c\uae30\uc640 \uc774\uc5b4\uc9c4\ub2e4. \uc81c\uc790\ub4e4\uc740 \uae38\uc5d0\uc11c \ud568\uaed8 \uac77\uace0 \uc774\uc57c\uae30\ud558\uba74\uc11c\ub3c4 \ub3d9\ud589\ud55c \uc0ac\ub78c\uc774 \ub204\uad6c\uc778\uc9c0 \uc54c\uc544\ubcf4\uc9c0 \ubabb\ud558\ub2e4\uac00 \uc2dd\ud0c1\uc5d0\uc11c \ube75\uc744 \ub098\ub204\ub294 \ud589\uc704\ub97c \ud1b5\ud574 \uc54c\uc544\ubcf8\ub2e4. \uc81c\ubaa9 \uc18d \ub0af\uc120 \uc9c0\uba85\uc744 \ubaa8\ub450 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \ud575\uc2ec\uc740 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uacc1\uc5d0 \uc788\uc73c\uba74\uc11c\ub3c4 \uc54c\uc544\ubcf4\uc9c0 \ubabb\ud588\ub358 \uc0ac\ub78c\uc744 \uc77c\uc0c1\uc801\uc778 \ud589\ub3d9 \ud558\ub098\uc5d0\uc11c \ub2e4\uc2dc \ubcf4\uac8c \ub418\ub294 \uc21c\uac04\uc774\ub2e4. \uadf8\ub9bc\uc758 \uc885\uad50\uc801 \uc8fc\uc81c\ub97c \uc9c0\uc6b0\uc9c0 \uc54a\uc73c\uba74\uc11c\ub3c4, \uac00\uae4c\uc6b4 \uc774\ub97c \uc774\ud574\ud558\ub294 \uc77c\uc774 \uc5b8\uc81c \uc77c\uc5b4\ub098\ub294\uc9c0\uc5d0 \uad00\ud55c \uac10\uac01\uc73c\ub85c \ub2e4\uac00\uac08 \uc218 \uc788\ub2e4. \ud654\uba74 \uac00\uc6b4\ub370\uc5d0\ub294 \uc608\uc218\uac00 \uc549\uc544 \uc788\uace0 \ub450 \uc81c\uc790\uac00 \uc88c\uc6b0\uc5d0 \ub193\uc5ec \uc788\ub2e4. \uc5bc\uad74\ub9cc \ubcf4\ub294 \ub370\uc11c \uadf8\uce58\uc9c0 \ub9d0\uace0 \uc190\uacfc \uc2dd\ud0c1\uc758 \ube75\uc73c\ub85c \ub208\uc744 \ub0b4\ub824 \ubcf4\uc790. \uc774\uc57c\uae30\uc5d0\uc11c \uc54c\uc544\ubd04\uc758 \uacc4\uae30\uac00 \ub418\ub294 \ud589\ub3d9\uc774 \ubc14\ub85c \uadf8\uacf3\uc5d0 \ub193\uc5ec \uc788\ub2e4. \uc0c1\uc9d5\uc744 \ub9ce\uc774 \uc54c\uc544\uc57c\ub9cc \uc774\ud574\ud560 \uc218 \uc788\ub294 \uadf8\ub9bc\ucc98\ub7fc \ub290\uaef4\uc84c\ub2e4\uba74 \uc778\ubb3c\uc758 \ubab8\uc9d3\ubd80\ud130 \ubcf4\uba74 \ub41c\ub2e4. \ub204\uac00 \uc190\uc744 \ubaa8\uc73c\uace0 \ub204\uac00 \ubab8\uc744 \uc6c0\uc9c1\uc774\ub294\uc9c0, \uadf8 \uc6c0\uc9c1\uc784\uc774 \uc911\uc559\uc744 \uc5b4\ub5bb\uac8c \ud5a5\ud558\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\ub294 \uac83\uc774\ub2e4. \uc774\ub984\ud45c\ub97c \ud655\uc778\ud558\ub358 \ud654\uba74\uc774 \uc0ac\ub78c \uc0ac\uc774\uc758 \ubc18\uc751\uc73c\ub85c \ubc14\ub010\ub2e4. \ubc29\uc758 \ubaa8\ub4e0 \uacf3\uc774 \uac19\uc740 \ubc1d\uae30\ub85c \uadf8\ub824\uc838 \uc788\uc9c0\ub294 \uc54a\ub2e4. \uc2dd\ud0c1\uacfc \uc911\uc559\uc758 \uc778\ubb3c, \uc8fc\ubcc0\uc758 \uc5b4\ub450\uc6b4 \uc790\ub9ac\ub97c \ubc88\uac08\uc544 \ubcf4\uba74 \ub208\uc774 \uc5b4\ub514\uc5d0 \uba38\ubb34\ub294\uc9c0 \ub290\ub084 \uc218 \uc788\ub2e4. \uc61b \ub3c4\ub85d\uc740 \uc67c\ucabd\uc5d0\uc11c \ub4e4\uc5b4\uc624\ub294 \ube5b\uc744 \uc124\uba85\ud55c\ub2e4. \uc2e4\uc81c \ub3c4\ud310\uc5d0\uc11c\ub3c4 \ubc1d\uc740 \ubd80\ubd84\uacfc \uadf8\ub298\uc758 \ucc28\uc774\uac00 \uc7a5\uba74\uc744 \ubb36\ub294\ub2e4. \uc774\ub97c \ube5b \ud558\ub098\ud558\ub098\uac00 \ud2b9\uc815 \uad50\ub9ac\ub97c \uac00\ub9ac\ud0a4\ub294 \uc554\ud638\ub77c\uace0\ub9cc \ud574\uc11d\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc6b0\uc120 \ubc1d\uae30 \ub54c\ubb38\uc5d0 \uc5b4\ub5a4 \uc190\uacfc \uc5bc\uad74\uc774 \uac00\uae4c\uc6cc\uc9c0\ub294\uc9c0 \ubcf4\uc790. \ub818\ube0c\ub780\ud2b8\uc758 \ud68c\ud654\uc5d0\uc11c \ube5b\uc740 \uc0ac\ubb3c\uc758 \ud45c\uba74\uc744 \ub4dc\ub7ec\ub0b4\uba74\uc11c \ub3d9\uc2dc\uc5d0 \uc778\ubb3c\ub4e4\uc758 \uad00\uacc4\ub97c \ubcf4\uac8c \ud558\ub294 \uae38\uc774 \ub420 \uc218 \uc788\ub2e4. \uc778\ubb3c\ub4e4 \uc704\uc5d0\ub294 \ub113\uace0 \uc5b4\ub450\uc6b4 \uacf5\uac04\uc774 \ub0a8\uc544 \uc788\ub2e4. \uc0ac\ub78c\ub9cc \uc798\ub77c \ud655\ub300\ud558\uba74 \ub193\uce58\uae30 \uc26c\uc6b4 \ubd80\ubd84\uc774\ub2e4. \uc2dd\ud0c1\uc758 \ub192\uc774\uc640 \ubc29\uc758 \ud06c\uae30\ub97c \ud568\uaed8 \ubcf4\uba74 \uc791\uc740 \ubaa8\uc784\uc774 \ud070 \uacf5\uac04 \uc548\uc5d0 \uc870\uc6a9\ud788 \ub193\uc600\ub2e4\ub294 \ub290\ub08c\uc744 \ubc1b\uac8c \ub41c\ub2e4. \uc774 \uc5ec\ubc31\uc744 \uc4f8\ubaa8\uc5c6\ub294 \ubc30\uacbd\uc73c\ub85c \uc0dd\uac01\ud558\uc9c0 \ub9d0\uace0 \uc7a0\uae50 \uba38\ubb3c\ub7ec \ubcf4\uc790. \uc8fc\ubcc0\uc774 \ub35c \ubcf5\uc7a1\ud560\uc218\ub85d \uc2dd\ud0c1 \uac00\uae4c\uc774\uc758 \uc6c0\uc9c1\uc784\uc740 \ub354 \uc911\uc694\ud558\uac8c \ubcf4\uc77c \uc218 \uc788\ub2e4. \ud070 \uc0ac\uac74\uc744 \ud06c\uac8c \uadf8\ub824\uc57c\ub9cc \uc911\uc694\ud574\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uac10\uc0c1\uc744 \uac00\ub2a5\ud558\uac8c \ud558\ub294 \uad6c\uc131\uc774\ub2e4. \uc624\ub978\ucabd\uc5d0\ub294 \uc811\uc2dc\ub97c \ub4e4\uace0 \ub4e4\uc5b4\uc624\ub294 \uc80a\uc740 \uc778\ubb3c\uc774 \uc788\ub2e4. \uc911\uc559\uc758 \uc885\uad50\uc801 \uc0ac\uac74\uacfc \ud568\uaed8 \uc74c\uc2dd\uc744 \ub098\ub974\ub294 \uad6c\uccb4\uc801\uc778 \uc77c\uc774 \uac19\uc740 \ud654\uba74 \uc548\uc5d0 \ub193\uc778\ub2e4. \ucd08\uc6d4\uc801\uc778 \uc8fc\uc81c\uac00 \ud604\uc2e4\uc758 \uc0dd\ud65c \uacf5\uac04 \uc18d\uc5d0\uc11c \ud45c\ud604\ub418\ub294 \uac83\uc774\ub2e4. \ub204\uad6c\ub098 \uac19\uc740 \uc815\ub3c4\ub85c \ubb34\uc2a8 \uc77c\uc774 \ubc8c\uc5b4\uc9c0\ub294\uc9c0 \uc54c\uc544\ucc28\ub9ac\uace0 \uc788\ub2e4\uace0 \ub2e8\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uac01\uc790\uc758 \uc790\uc138\uc640 \uc2dc\uc120\uc774 \ub2e4\ub974\ub2e4\ub294 \uc810\uc744 \ubcf4\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc6b0\ub9ac\uac00 \uc911\uc694\ud55c \uc21c\uac04\uc744 \uacaa\uc744 \ub54c\ub3c4 \uc8fc\ubcc0\uc758 \ubaa8\ub4e0 \uc77c\uc774 \ub3d9\uc2dc\uc5d0 \uba48\ucd94\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2dd\ud0c1\uc758 \uc0ac\uac74\uacfc \uc0dd\ud65c\uc758 \uc6c0\uc9c1\uc784\uc774 \uacb9\uccd0 \uc788\ub2e4. \uadf8\ub9bc\uc740 \ud55c \uc21c\uac04\uc744 \ubcf4\uc5ec \uc8fc\uc9c0\ub9cc, \uc774\uc57c\uae30\ub97c \uc54c\uace0 \ubcf4\uba74 \uadf8 \uc55e\ub4a4\uc758 \uc2dc\uac04\uc774 \ud568\uaed8 \ub5a0\uc624\ub978\ub2e4. \uc54c\uc544\ubcf4\uc9c0 \ubabb\ud588\ub358 \uae38 \uc704\uc758 \uc2dc\uac04, \ube75\uc744 \ub098\ub204\ub294 \uc9c0\uae08, \uadf8 \ub4a4 \ub2ec\ub77c\uc9c8 \uc774\ud574\uac00 \uac19\uc740 \ud654\uba74 \uc8fc\ubcc0\uc5d0 \ub193\uc774\ub294 \uc148\uc774\ub2e4. \ud68c\ud654\uac00 \uc815\uc9c0\ub41c \uc7a5\uba74\ub9cc \uc804\ub2ec\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub798\uc11c \ucc98\uc74c \ubcfc \ub54c\uc640 \uc904\uac70\ub9ac\ub97c \uc54c\uace0 \ub2e4\uc2dc \ubcfc \ub54c \uacbd\ud5d8\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc9c0\uc2dd\uc774 \uadf8\ub9bc\uc744 \ubcf4\ub294 \uc77c\uc744 \ub300\uc2e0\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uc790\uc138\uc640 \ubb3c\uac74\uc774 \uc5b4\ub5a4 \uc2dc\uac04\uacfc \uc5f0\uacb0\ub418\ub294\uc9c0 \uc54c\ub824 \uc900\ub2e4. \uc815\ubcf4\ub97c \ud558\ub098 \uc5bb\uace0 \ud654\uba74\uc73c\ub85c \ub3cc\uc544\uc624\ub294 \uc655\ubcf5\uc744 \uc990\uaca8 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc61b \ub3c4\ub85d\uc740 \uc791\ud488\uc758 \uc11c\uba85\uc5d0 1648\ub144\uc744 \uc81c\uc2dc\ud55c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \uadf8 \ub3c4\ub85d\uc5d0 \uc218\ub85d\ub41c \uc2e4\uc81c \ud68c\ud654\uc758 \uc0c9\ucc44 \uc7ac\ud604 \uc790\ub8cc\ub2e4. \ub2f9\uc2dc \uc131\uc11c \uc7a5\uba74\uc744 \uc0c8\ub85c \uc0c1\uc0c1\ud55c \ud604\ub300 \uc0bd\ud654\uac00 \uc544\ub2c8\ub77c \ub818\ube0c\ub780\ud2b8\uc758 \ud654\uba74 \uad6c\uc131\uc744 \ubcf4\ub294 \ub370 \uc4f0\ub294 \uc790\ub8cc\ub2e4. \ub2e4\ub9cc \uc61b \uc778\uc1c4\ubb3c\uc774\ubbc0\ub85c \ud604\uc7ac \uc2e4\ubb3c\uc758 \uc0c9\uacfc \ud45c\uba74\uc744 \uc644\uc804\ud788 \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8 \ucc28\uc774\ub97c \ubaa8\ub978 \ucc44 \uc138\ubd80 \uc0c9 \ud558\ub098\ub97c \ub2e8\uc815\ud558\uae30\ubcf4\ub2e4 \uc2dd\ud0c1\uc758 \ubc30\uce58\uc640 \ud070 \ubc1d\uae30, \uc0ac\ub78c \uc0ac\uc774\uc758 \uac70\ub9ac\ub97c \uc0b4\ud3b4\ubcf4\uba74 \uc88b\ub2e4. \ub3c4\ud310\uc774 \uac00\uc9c4 \uc870\uac74 \uc548\uc5d0\uc11c\ub3c4 \uac10\uc0c1\uc758 \uae38\uc740 \ucda9\ubd84\ud788 \uc5f4\ub9b0\ub2e4. \uadf8\ub9bc\uc744 \ud55c \ubc14\ud034 \ubcf4\uace0 \ub2e4\uc2dc \ube75\uc744 \ub098\ub204\ub294 \uc190\uc73c\ub85c \ub3cc\uc544\uc640 \ubcf4\uc790. \uc81c\uc790\ub4e4\uc774 \uc0ac\ub78c\uc744 \uc54c\uc544\ubcf4\ub294 \uacc4\uae30\ub294 \uc774\ub984\uc744 \uc0c8\ub85c \ub4e4\uc5c8\uae30 \ub54c\ubb38\ub9cc\uc774 \uc544\ub2c8\ub77c \uc775\uc219\ud55c \ud589\ub3d9\uc744 \ubcf4\uc558\uae30 \ub54c\ubb38\uc774\ub2e4. \uc774 \uc11c\uc0ac\ub294 \uadf8 \uc791\uc740 \uc778\uc2dd\uc758 \ubcc0\ud654\ub97c \uc911\uc2ec\uc5d0 \ub454\ub2e4. \ubaa8\ub4e0 \uad00\uac1d\uc774 \uc885\uad50\uc801 \ubbff\uc74c\uc744 \uacf5\uc720\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc7a5\uba74\uc744 \uc77d\uc744 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc791\ud488\uc774 \uac00\uc9c4 \uc885\uad50\uc801 \uc758\ubbf8\ub97c \uc5c6\uc560\uae30\ubcf4\ub2e4 \uadf8 \uc758\ubbf8\uac00 \uc5b4\ub5bb\uac8c \uad6c\uccb4\uc801\uc778 \uc190\uacfc \uc2dd\ud0c1\uc73c\ub85c \ud45c\ud604\ub418\uc5c8\ub294\uc9c0 \ubcf4\ub294 \uac83\uc774\ub2e4. \uc870\uc6a9\ud55c \ubc29\uc5d0\uc11c \ud55c \uc0ac\ub78c\uc744 \ub2e4\uc2dc \uc54c\uc544\ubcf4\ub294 \uc21c\uac04\uc774 \uc624\ub798 \ub0a8\ub294 \uadf8\ub9bc\uc774\ub2e4."}, {"id": "rembrandt-life-self-portraits", "title": "\ub818\ube0c\ub780\ud2b8\uc758 \uc0dd\uc560 \u2014 \uc5bc\uad74\uacfc \ube5b\uc744 \ub2e4\uc2dc \ubc14\ub77c\ubcf8 \uc2dc\uac04", "summary": "\ub300\ud45c\uc791\uacfc \uc0dd\ud65c\uc758 \ubcc0\ud654\ub97c \ud568\uaed8 \ub530\ub77c\uac00\uba70 \ube44\uadf9\uc758 \ucc9c\uc7ac\ub77c\ub294 \ub2e8\uc21c\ud55c \uadf8\ub9bc\uc744 \ub113\ud799\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/rembrandt-life-self-portraits/index.html", "image": "../media/rembrandt-life-self-portraits.jpg", "alt": "1640\ub144 \ub818\ube0c\ub780\ud2b8\uac00 \ub3cc \ub09c\uac04\uc5d0 \uae30\ub300 \uc120 \uc790\uc2e0\uc758 \ubaa8\uc2b5\uc744 \uadf8\ub9b0 \ucd08\uc0c1\uc758 \uc61b \uc7ac\ud604 \ub3c4\ud310.", "text": "\ub818\ube0c\ub780\ud2b8\uc758 \uc0dd\uc560 \u2014 \uc5bc\uad74\uacfc \ube5b\uc744 \ub2e4\uc2dc \ubc14\ub77c\ubcf8 \uc2dc\uac04 \ub808\uc774\ub358\uc5d0\uc11c \uc554\uc2a4\ud14c\ub974\ub2f4\uc73c\ub85c, \ucd08\uc0c1\uacfc \ud310\ud654\uc640 \uc790\ud654\uc0c1\uc758 \uae38 \ub300\ud45c\uc791\uacfc \uc0dd\ud65c\uc758 \ubcc0\ud654\ub97c \ud568\uaed8 \ub530\ub77c\uac00\uba70 \ube44\uadf9\uc758 \ucc9c\uc7ac\ub77c\ub294 \ub2e8\uc21c\ud55c \uadf8\ub9bc\uc744 \ub113\ud799\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \uc5b4\ub5a4 \uc790\ud654\uc0c1\uc5d0\uc11c\ub294 \ud654\ub824\ud55c \uc637\uc744 \uc785\uc740 \uc0ac\ub78c\uc774 \uad00\uac1d\uc744 \ubc14\ub77c\ubcf4\uace0, \ub2e4\ub978 \uc790\ud654\uc0c1\uc5d0\uc11c\ub294 \ub098\uc774 \ub4e0 \uc5bc\uad74\uc774 \uc5b4\ub450\uc6b4 \ubc14\ud0d5\uc5d0\uc11c \ub4dc\ub7ec\ub09c\ub2e4. \ud55c \uc0ac\ub78c\uc774 \uc790\uae30 \ubaa8\uc2b5\uc744 \uc5ec\ub7ec \ubc88 \uadf8\ub838\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c\ub3c4 \uc624\ub798 \ubcfc \uc774\uc57c\uae30\uac00 \uc0dd\uae34\ub2e4. \ub818\ube0c\ub780\ud2b8\uc758 \uc5bc\uad74\uc740 \uc0dd\uc560\ub97c \uc0dd\uac01\ud558\uac8c \ud558\ub294 \uc5ec\ub7ec \uc785\uad6c \uc911 \ud558\ub098\ub2e4. \uadf8\ub294 17\uc138\uae30 \ub124\ub35c\ub780\ub4dc\uc5d0\uc11c \ucd08\uc0c1\uacfc \uc885\uad50\ud654, \ud310\ud654 \ub4f1\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \uc131\uacf5\uacfc \uc0c1\uc2e4\uc774\ub77c\ub294 \ud070 \ub2e8\uc5b4\ub85c\ub9cc \uc815\ub9ac\ud558\uae30\ubcf4\ub2e4 \uc5b4\ub5a4 \uc0ac\ub78c\ub4e4\uc744 \uc5b4\ub5bb\uac8c \uadf8\ub838\uace0 \uc790\uae30 \ubaa8\uc2b5\uc744 \uc5b4\ub5bb\uac8c \ub2e4\uc2dc \ubcf4\uc558\ub294\uc9c0 \ub530\ub77c\uac00 \ubcf4\uc790. \uc5b4\ub450\uc6b4 \uadf8\ub9bc\uc744 \ub0a8\uae34 \uc2ac\ud508 \ud654\uac00\ub77c\ub294 \uc778\uc0c1\ubcf4\ub2e4 \ub113\uc740 \uc0b6\uc774 \ubcf4\uc778\ub2e4. \ub808\uc774\ub358\uc5d0\uc11c \uc790\ub780 \ub818\ube0c\ub780\ud2b8\ub294 \uadf8\ub9bc\uc744 \ubc30\uc6b0\uace0 \uc791\uc5c5\uc744 \uc2dc\uc791\ud588\ub2e4. \ucc98\uc74c\ubd80\ud130 \uc624\ub298\ub0a0\uc758 \uc774\ub984\uac12\uc744 \uac00\uc9c4 \uac70\uc7a5\uc774\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc7ac\ub8cc\uc640 \ud45c\ud604\uc744 \uc775\ud788\uace0 \ub2e4\ub978 \uadf8\ub9bc\uc744 \ubcf4\uba70 \uc5b4\ub5a4 \uc7a5\uba74\uc744 \ub9cc\ub4e4\uc9c0 \ucc3e\uc544\uac00\ub294 \uc2dc\uac04\uc774 \uc788\uc5c8\ub2e4. \uc804\uae30\ub294 \uc720\ub144\uc758 \uc77c\ud654\ub97c \uc7ac\ubbf8\uc788\uac8c \uc804\ud558\uc9c0\ub9cc \ubaa8\ub4e0 \uae30\uc5b5\uc744 \uc644\ubcbd\ud55c \ud604\uc7a5 \uae30\ub85d\uc73c\ub85c \ubcfc \uc218\ub294 \uc5c6\ub2e4. \ub300\uc2e0 \ucd08\uae30\uc758 \ubc30\uc6c0\uacfc \uc791\uc5c5\uc774\ub77c\ub294 \uc2e4\uc81c \uacfc\uc815\uc744 \uc0dd\uac01\ud558\uba74 \uc88b\ub2e4. \uc778\ubb3c\uc758 \ud45c\uc815\uacfc \ube5b, \uc774\uc57c\uae30\ub97c \ud55c \ud654\uba74\uc5d0 \ub193\ub294 \ub2a5\ub825\ub3c4 \uc5f0\uc2b5\uacfc \uad00\ucc30\uc744 \ud1b5\ud574 \ub2e4\ub4ec\uc5b4 \uac14\ub2e4. \uc554\uc2a4\ud14c\ub974\ub2f4\uc73c\ub85c \uc62e\uae34 \ub4a4\uc5d0\ub294 \uc758\ub8b0\uc778\uacfc \uc8fc\ubb38, \uacb0\ud63c\uacfc \uc0dd\ud65c\uc774 \uc774\uc5b4\uc9c4\ub2e4. \uc0ac\uc2a4\ud0a4\uc544\uc640\uc758 \uad00\uacc4\ub3c4 \uc774 \uc0b6\uc758 \uc911\uc694\ud55c \ubd80\ubd84\uc774\ub2e4. \ub3c4\uc2dc\uc5d0\uc11c \uc0ac\ub78c\uc758 \ucd08\uc0c1\uc744 \uadf8\ub9b0\ub2e4\ub294 \uac83\uc740 \uc5bc\uad74\uc744 \uc798 \ubb18\uc0ac\ud558\ub294 \uc77c\ubfd0 \uc544\ub2c8\ub77c \uadf8 \uc0ac\ud68c\uc758 \uad00\uacc4 \uc18d\uc5d0\uc11c \uc77c\ud558\ub294 \ubb38\uc81c\uc774\uae30\ub3c4 \ud588\ub2e4. \uc778\ubb3c\ub4e4\uc740 \uc790\uc2e0\uc758 \ubaa8\uc2b5\uc774 \uc5b4\ub5a4 \uadf8\ub9bc\uc73c\ub85c \ub0a8\uc744\uc9c0 \uae30\ub300\ud588\uc744 \uac83\uc774\ub2e4. \ud654\uac00\ub294 \uadf8\ub7f0 \uc694\uad6c\uc640 \uc790\uae30 \ud45c\ud604\uc758 \uc120\ud0dd \uc0ac\uc774\uc5d0\uc11c \ud654\uba74\uc744 \ub9cc\ub4e0\ub2e4. \uc791\ud488\uc774 \ud6cc\ub96d\ud558\ub2e4\ub294 \uc624\ub298\uc758 \ud3c9\uac00\ub9cc\uc73c\ub85c \ub2f9\uc2dc\uc758 \ubaa8\ub4e0 \uc758\ub8b0 \uad00\uacc4\uae4c\uc9c0 \uc21c\uc870\ub85c\uc6e0\ub2e4\uace0 \uc0dd\uac01\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc77c\uc758 \uc870\uac74\uacfc \uacb0\uacfc\ub294 \ud568\uaed8 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \u3008\ud288\ud504 \ubc15\uc0ac\uc758 \ud574\ubd80\ud559 \uac15\uc758\u3009\ub098 \ud754\ud788 \u3008\uc57c\uacbd\u3009\uc774\ub77c \ubd80\ub974\ub294 \uc2dc\ubbfc\uacbd\ube44\ub300\uc758 \uc9d1\ub2e8\ucd08\uc0c1\uc5d0\uc11c\ub294 \uc5ec\ub7ec \uc778\ubb3c\uc744 \ud55c \ud654\uba74\uc5d0 \ubb36\ub294\ub2e4. \ubaa8\ub450\uac00 \uac19\uc740 \ubc29\ud5a5\uc744 \ubc14\ub77c\ubcf4\uace0 \uac19\uc740 \uc790\uc138\ub97c \ucde8\ud558\ub294 \ubaa9\ub85d\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uad00\uc2ec\uacfc \uc6c0\uc9c1\uc784\uc758 \ucc28\uc774\uac00 \ubaa8\uc784\uc758 \uc131\uaca9\uc744 \ub9cc\ub4e0\ub2e4. \ud2b9\ud788 \u3008\uc57c\uacbd\u3009\uc774\ub77c\ub294 \uc774\ub984\ub9cc \ubcf4\uace0 \ud55c\ubc24\uc758 \uadfc\ubb34 \uc7a5\uba74\uc774\ub77c\uace0 \ud655\uc815\ud558\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc61b \uc791\ud488 \ud574\uc124\ub3c4 \uc774 \uc720\uba85\ud55c \ud638\uce6d\uc758 \ubb38\uc81c\ub97c \uc9da\ub294\ub2e4. \uc81c\ubaa9\uc744 \uc544\ub294 \uc77c\uc5d0\uc11c \ucd9c\ubc1c\ud574, \uc2e4\uc81c\ub85c \uc0ac\ub78c\ub4e4\uc758 \ubab8\uc774 \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc774\uace0 \ube5b\uc774 \uc5b4\ub514\uc5d0 \ub193\uc774\ub294\uc9c0 \ubcf4\ub294 \ucabd\uc73c\ub85c \ub098\uc544\uac08 \uc218 \uc788\ub2e4. \ub818\ube0c\ub780\ud2b8\ub294 \ud68c\ud654\ubfd0 \uc544\ub2c8\ub77c \uc5d0\uce6d \uac19\uc740 \ud310\ud654 \uc791\uc5c5\ub3c4 \ud588\ub2e4. \uae08\uc18d\ud310\uc5d0 \uc120\uc744 \ub9cc\ub4e4\uace0 \uc778\uc1c4\ud558\ub294 \uacfc\uc815\uc5d0\uc11c\ub294 \uc0c9\uc774 \ub113\uac8c \ub193\uc774\ub294 \uadf8\ub9bc\uacfc \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ube5b\uacfc \uacf5\uac04\uc744 \ud45c\ud604\ud55c\ub2e4. \uc791\uc740 \uc120\uacfc \ube44\uc5b4 \uc788\ub294 \uc790\ub9ac\uac00 \ud070 \uc5ed\ud560\uc744 \ud560 \uc218 \uc788\ub2e4. \uc720\uba85\ud55c \uc720\ud654 \uba87 \uc810\ub9cc \uae30\uc5b5\ud558\uba74 \uc774 \uc791\uc5c5\uc758 \ud3ed\uc744 \ub193\uce58\uae30 \uc27d\ub2e4. \ud55c \uc791\uac00\uac00 \uc5b8\uc81c\ub098 \uac19\uc740 \uc7ac\ub8cc\ub85c \uac19\uc740 \ud6a8\uacfc\ub9cc \ucc3e\uc740 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ud310\ud654\uc640 \uadf8\ub9bc\uc744 \ubc88\uac08\uc544 \ubcf4\uba74 \uc5bc\uad74\uacfc \ubab8, \uc0dd\ud65c\uacfc \uc131\uc11c \uc774\uc57c\uae30\ub97c \ub2e4\ub8e8\ub294 \uad00\uc2ec\uc774 \uc11c\ub85c \ub2e4\ub978 \uc7ac\ub8cc \uc548\uc5d0\uc11c \uc774\uc5b4\uc9c0\ub294 \ubaa8\uc2b5\uc744 \ubcfc \uc218 \uc788\ub2e4. \uc790\ud654\uc0c1\uc744 \uadf8\ub9b0\ub2e4\ub294 \uac83\uc740 \uc790\uae30 \uc778\uc0dd\uc744 \uae30\ub85d\ud558\ub294 \uc77c\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc \uadf8\uac83\ub9cc\uc73c\ub85c \uc124\uba85\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \uac00\uae4c\uc774 \uc788\ub294 \ubaa8\ub378\uc744 \ud1b5\ud574 \ud45c\uc815\uacfc \ube5b, \uc637\uacfc \uc790\uc138\ub97c \uc2e4\ud5d8\ud560 \uc218\ub3c4 \uc788\ub2e4. \uc624\ub298\uc758 \ub3c5\uc790\ub294 \uac19\uc740 \uc0ac\ub78c\uc774 \uc5ec\ub7ec \ubaa8\uc2b5\uc73c\ub85c \ub098\ud0c0\ub098\ub294 \uc2dc\uac04\uc744 \ud568\uaed8 \ubcf4\uac8c \ub41c\ub2e4. \uc80a\uc740 \uc790\ud654\uc0c1\uacfc \ub2a6\uc740 \uc790\ud654\uc0c1\uc744 \ube44\uad50\ud558\uba70 \uc0dd\uc560\uc758 \ucc28\uc774\ub97c \ub290\uaef4\ub3c4 \uc88b\ub2e4. \ub2e4\ub9cc \uc5bc\uad74\uc5d0 \ubcf4\uc774\ub294 \ubaa8\ub4e0 \uc8fc\ub984\uc744 \ud2b9\uc815\ud55c \uc0ac\uac74\uc758 \uacb0\uacfc\ub77c\uace0 \uc77d\uc744 \uc218\ub294 \uc5c6\ub2e4. \uc791\ud488\uc740 \ub0a0\uc9dc\uc640 \uc790\ub8cc\uc758 \ub3c4\uc6c0\uc744 \ubc1b\uc544 \uc774\ud574\ud558\ub294 \ud68c\ud654\uc774\uc9c0, \uacfc\uac70\uc758 \uac10\uc815\uacfc \ubcd1\uc744 \ubaa8\ub450 \ud310\ub3c5\ud560 \uc218 \uc788\ub294 \uac80\uc0ac\ud45c\ub294 \uc544\ub2c8\ub2e4. \uc0ac\uc2a4\ud0a4\uc544\ub97c \ube44\ub86f\ud55c \uac00\uae4c\uc6b4 \uc0ac\ub78c\ub4e4\uc758 \uc0c1\uc2e4\uacfc \uc7ac\uc815\uc758 \uc5b4\ub824\uc6c0\uc740 \uadf8\uc758 \uc0dd\uc560\uc5d0\uc11c \uc911\uc694\ud55c \uc0ac\uac74\uc774\ub2e4. \ud2f0\ud22c\uc2a4\uc640 \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4 \uc5ed\uc2dc \uc791\ud488\uacfc \uc0dd\ud65c \uc18d\uc5d0 \uc790\ub9ac\ub97c \uac00\uc9c4\ub2e4. \uc0ac\ub78c\uc744 \uadf8\ub9ac\ub294 \uc791\uc5c5\uacfc \uadf8 \uc0ac\ub78c\ub4e4\uacfc \uc0b4\uc544\uac00\ub294 \uc77c\uc740 \uac19\uc740 \uc2dc\uac04 \uc548\uc5d0 \uc788\uc5c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc5b4\ub5a4 \ub300\ud45c\uc791\uc774 \uc2e4\ud328\ud574 \uace7\ubc14\ub85c \ubaa8\ub4e0 \uac83\uc744 \uc783\uc5c8\ub2e4\ub294 \ub2e8\uc21c\ud55c \ucd94\ub77d\uc758 \uc774\uc57c\uae30\ub85c \uc815\ub9ac\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud6c4\ub300 \uc804\uae30\uc5d0\ub294 \uadf9\uc801\uc778 \uc77c\ud654\uac00 \ub367\ubd99\uae30\ub3c4 \ud55c\ub2e4. \ud655\uc778\ub418\ub294 \uc0ac\uac74\uc744 \ubcf4\ub418 \uc791\ud488 \uc804\uccb4\uac00 \ubd88\ud589 \ud558\ub098\uc5d0\uc11c \uc790\ub3d9\uc73c\ub85c \ub098\uc654\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc0ac\ub78c\uacfc \uadf8\ub9bc\uc744 \ub354 \uc798 \uc774\ud574\ud558\uac8c \ud55c\ub2e4. \ub2a6\uc740 \uc2dc\uae30\uc5d0\ub3c4 \uadf8\ub294 \ucd08\uc0c1\uacfc \uc5ec\ub7ec \uc774\uc57c\uae30\ub97c \uadf8\ub838\ub2e4. \ud070 \uc774\ub984\uc73c\ub85c \uc54c\ub824\uc9c4 \uc791\ud488\ub4e4\ub9cc\uc774 \uc544\ub2c8\ub77c \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc5bc\uad74\uc744 \uc5b4\ub5bb\uac8c \ubcf4\uc774\uac8c \ud560\uc9c0 \ud310\ub2e8\ud558\ub294 \uc791\uc5c5\uc774 \uc774\uc5b4\uc84c\ub2e4. \uc0b6\uc774 \uc5b4\ub824\uc6cc\uc84c\ub2e4\ub294 \ud55c \uc904\uc774 \uadf8 \ub4a4\uc758 \ubaa8\ub4e0 \uc2dc\uac04\uc744 \uc124\uba85\ud558\uc9c0\ub294 \ubabb\ud55c\ub2e4. \uadf8\ub294 1669\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub0ac\ub2e4. \uc624\ub298\uc758 \uba85\uc131\uacfc \ub2f9\ub300\uc758 \uc0dd\ud65c\uc744 \uc644\uc804\ud788 \uac19\uc740 \uac83\uc73c\ub85c \ub193\uc744 \uc218\ub294 \uc5c6\uc9c0\ub9cc, \uc78a\ud78c \ucc9c\uc7ac\ub77c\ub294 \ud45c\ud604 \ud558\ub098\ub85c\ub3c4 \uc791\uc5c5\uc758 \uad00\uacc4\uac00 \ub2e4 \ub2f4\uae30\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub0a8\uc740 \uadf8\ub9bc\uacfc \ud310\ud654\uac00 \uac01\uac01 \uc5b4\ub5a4 \uc2dc\uac04\uc744 \ubcf4\uc5ec \uc8fc\ub294\uc9c0 \ucc28\ub840\ub85c \ubcf4\ub294 \ud3b8\uc774 \ub354 \ud48d\ubd80\ud558\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 1640\ub144 \ub818\ube0c\ub780\ud2b8\uac00 \ub3cc \ub09c\uac04\uc5d0 \uae30\ub300 \uc120 \ubaa8\uc2b5\uc744 \uadf8\ub9b0 \uc790\ud654\uc0c1\uc758 \uc61b \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \ubaa8\uc790\uc640 \uc637, \ud314\uc758 \uc704\uce58\uac00 \uc5bc\uad74\uacfc \ud568\uaed8 \uad00\uac1d\uc744 \ud5a5\ud558\ub294 \uc778\uc0c1\uc744 \ub9cc\ub4e0\ub2e4. \uc2e4\uc81c \uc791\ud488\uc758 \uad6c\uc131\uc744 \ubcf4\ub294 \uc790\ub8cc\uc774\uba70 \uc0c8\ub85c \uc0c1\uc0c1\ud55c \ucd08\uc0c1\uc774 \uc544\ub2c8\ub2e4. \ud55c \uc0ac\ub78c\uc758 \uc0dd\uc560\ub97c \uc77d\uc740 \ub4a4 \uc774 \uc5bc\uad74\ub85c \ub3cc\uc544\uc624\uba74 \uc131\uacf5\uc774\ub098 \ube44\uadf9 \uac00\uc6b4\ub370 \ud558\ub098\ub9cc \uace0\ub97c \ud544\uc694\uac00 \uc5c6\uc5b4\uc9c4\ub2e4. \uc77c\ud558\uace0 \uad00\ucc30\ud558\uace0 \uc790\uae30 \ubaa8\uc2b5\uc744 \ub2e4\uc2dc \uadf8\ub9b0 \uc2dc\uac04\uc774 \ud568\uaed8 \ub5a0\uc624\ub978\ub2e4. \ub818\ube0c\ub780\ud2b8\uc758 \uad50\uc591\uc740 \uc5b4\ub450\uc6b4 \ubc14\ud0d5\uc758 \ud654\uac00\ub77c\ub294 \uc774\ub984\uc744 \uc678\uc6b0\ub294 \uac83\uc5d0\uc11c, \uc5ec\ub7ec \uc5bc\uad74\uacfc \ube5b\uc744 \uad6c\uccb4\uc801\uc73c\ub85c \ubcf4\ub294 \ucabd\uc73c\ub85c \ub113\uc5b4\uc9c8 \uc218 \uc788\ub2e4."}, {"id": "rembrandt-night-watch-light-and-company", "title": "\ub818\ube0c\ub780\ud2b8\uc758 \uc57c\uacbd \u2014 \ubc24\uc758 \uc21c\ucc30\ub85c\ub9cc \ubcf4\uba74 \ub193\uce58\ub294 \uc0ac\ub78c\ub4e4", "summary": "1642\ub144 \uc9d1\ub2e8 \ucd08\uc0c1\uc758 \ube5b\uacfc \uc190, \uc18c\ub140\uc640 \ubb34\uae30\uc758 \ubc30\uc5f4\ub85c \uc0ac\ub78c\ub4e4\uc744 \ud55c \uc7a5\uba74\uc5d0 \ubb36\ub294 \ubc29\uc2dd\uc744 \ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/rembrandt-night-watch-light-and-company/index.html", "image": "../media/rembrandt-night-watch-light-and-company.jpg", "alt": "\ub818\ube0c\ub780\ud2b8\uc758 \uc57c\uacbd \uc18d \uc55e\ucabd \ub450 \uc9c0\ud718\uc790\uc640 \uc5ec\ub7ec \uc778\ubb3c\uc774 \ubcf4\uc774\ub294 \uc5ed\uc0ac \uceec\ub7ec \ub3c4\ud310", "text": "\ub818\ube0c\ub780\ud2b8\uc758 \uc57c\uacbd \u2014 \ubc24\uc758 \uc21c\ucc30\ub85c\ub9cc \ubcf4\uba74 \ub193\uce58\ub294 \uc0ac\ub78c\ub4e4 \uc9d1\ub2e8 \ucd08\uc0c1\uc744 \uc6c0\uc9c1\uc774\ub294 \uc7a5\uba74\uc73c\ub85c \ub9cc\ub4e0 \ube5b\uacfc \uacf5\uac04\uc758 \uad6c\uc131 1642\ub144 \uc9d1\ub2e8 \ucd08\uc0c1\uc758 \ube5b\uacfc \uc190, \uc18c\ub140\uc640 \ubb34\uae30\uc758 \ubc30\uc5f4\ub85c \uc0ac\ub78c\ub4e4\uc744 \ud55c \uc7a5\uba74\uc5d0 \ubb36\ub294 \ubc29\uc2dd\uc744 \ubd05\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \ub818\ube0c\ub780\ud2b8\uc758 \u300c\uc57c\uacbd\u300d\uc744 \ucc98\uc74c \ubcf4\uba74 \uac80\uace0 \ud070 \ud654\uba74 \uc18d\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc774 \uac11\uc790\uae30 \uc6c0\uc9c1\uc774\ub294 \ub4ef\ud558\ub2e4. \uc81c\ubaa9 \ub54c\ubb38\uc5d0 \uc57c\uac04 \uc21c\ucc30 \uc7a5\uba74\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc27d\uc9c0\ub9cc, \uc774 \uadf8\ub9bc\uc744 \ubc24\uc758 \uae30\ub85d\uc73c\ub85c\ub9cc \uc774\ud574\ud558\uba74 \ube5b\uacfc \uc778\ubb3c\uc758 \uad00\uacc4\ub97c \ub193\uce5c\ub2e4. 1642\ub144\uc5d0 \uadf8\ub824\uc9c4 \uc9d1\ub2e8 \ucd08\uc0c1\uc740 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc5bc\uad74\uc744 \ud558\ub098\uc758 \uc0ac\uac74\ucc98\ub7fc \ubb36\uc5b4 \ub193\ub294\ub2e4. \uc774 \uc791\ud488\uc740 \ud504\ub780\uc2a4 \ubc14\ub2dd \ucf54\ud06c\uac00 \uc774\ub044\ub294 \ubbfc\ubcd1\ub300\uc758 \uc9d1\ub2e8 \ucd08\uc0c1\uc73c\ub85c \uc124\uba85\ub41c\ub2e4. \u300c\uc57c\uacbd\u300d\uc774\ub77c\ub294 \ub110\ub9ac \uc54c\ub824\uc9c4 \uc774\ub984\uc740 \uadf8\ub9bc\uc758 \ubaa8\ub4e0 \ub0b4\uc6a9\uc744 \uc815\ud655\ud788 \uc54c\ub824 \uc8fc\ub294 \ud45c\uc9c0\uac00 \uc544\ub2c8\ub2e4. \uc81c\ubaa9\uc744 \uc54c\uace0 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ud654\uba74\uc744 \uc774\ud574\ud588\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc624\ub798\ub41c \ubbf8\uc220 \ud574\uc124\uc5d0\uc11c\ub3c4 \uc2e4\uc81c\ub85c\ub294 \ub0ae\uc758 \uc7a5\uba74\uc774\ub77c\ub294 \uc810\uc774 \uc9c0\uc801\ub418\uc5c8\ub2e4. \ube5b\uc774 \uc801\uac8c \ubcf4\uc774\uace0 \uc5b4\ub450\uc6b4 \ubc14\ud0d5\uc774 \ub113\ub2e4\uace0 \ud574\uc11c \ubc18\ub4dc\uc2dc \ubc24\uc778 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc791\ud488 \uc55e\uc5d0\uc11c\ub294 \uba3c\uc800 \uc5b4\ub514\uac00 \ubc1d\uace0 \uc5b4\ub514\uac00 \uc5b4\ub450\uc6b4\uc9c0 \ubcf4\uace0, \uadf8 \ucc28\uc774\uac00 \ubb34\uc5c7\uc744 \uac15\uc870\ud558\ub294\uc9c0 \uc0b4\ud3b4\ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \uc5ec\ub7ec \uc0ac\ub78c\uc774 \ud568\uaed8 \ub3c8\uc744 \ub0b4\uace0 \uadf8\ub9bc\uc5d0 \ub4f1\uc7a5\ud558\uba74 \uc790\uae30 \uc5bc\uad74\uc774 \uc798 \ubcf4\uc774\uae30\ub97c \ubc14\ub784 \uac83\uc774\ub2e4. \uc9d1\ub2e8 \ucd08\uc0c1\uc5d0\ub294 \uac1c\uc778\uc758 \uccb4\uba74\uacfc \uacf5\ub3d9\uccb4\uc758 \ubaa8\uc2b5\uc744 \ud568\uaed8 \ubcf4\uc5ec \uc8fc\uc5b4\uc57c \ud558\ub294 \uc5b4\ub824\uc6c0\uc774 \uc788\ub2e4. \ubaa8\ub450\ub97c \uac19\uc740 \ud06c\uae30\uc640 \uac19\uc740 \ubc1d\uae30\ub85c \ub193\uc73c\uba74 \uacf5\ud3c9\ud560 \uc218 \uc788\uc9c0\ub9cc \uc7a5\uba74\uc740 \uc815\uc9c0\ud558\uae30 \uc27d\ub2e4. \ub818\ube0c\ub780\ud2b8\ub294 \uc778\ubb3c\ub4e4\uc744 \uc11c\ub85c \ub2e4\ub978 \ubc29\ud5a5\uacfc \uae4a\uc774\uc5d0 \ubc30\uce58\ud55c\ub2e4. \uc5b4\ub5a4 \uc5bc\uad74\uc740 \uc55e\uc5d0 \ub098\uc624\uace0 \uc5b4\ub5a4 \ubab8\uc740 \ub2e4\ub978 \uc0ac\ub78c \ub4a4\uc5d0 \uac78\ub9b0\ub2e4. \ubcf4\ub294 \uc0ac\ub78c\uc740 \uc5bc\uad74 \uba85\ub2e8\uc744 \ucc28\ub840\ub85c \ud655\uc778\ud558\uae30\ubcf4\ub2e4 \uc55e\ub4a4\ub85c \uc774\ub3d9\ud558\ub294 \uc6c0\uc9c1\uc784\uc744 \ub290\ub080\ub2e4. \ucd08\uc0c1\uc774\uba74\uc11c \uc7a5\uba74\uc774 \ub418\ub294 \uad6c\uc131\uc774\ub2e4. \uac80\uc740 \uc637\uacfc \ubd89\uc740 \ub760\uc758 \ub300\uc7a5, \ubc1d\uc740 \uc637\ucc28\ub9bc\uc758 \ubd80\uad00\uc774 \uc55e\ucabd\uc5d0\uc11c \uc2dc\uc120\uc744 \ubaa8\uc740\ub2e4. \uc774\ub4e4\uc774 \uc11c \uc788\ub294 \uc790\ub9ac\ub294 \ub2e8\uc21c\ud788 \uc911\uc559\uc774\ub77c\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \uc911\uc694\ud558\uc9c0 \uc54a\ub2e4. \uc0c9\uc758 \ucc28\uc774\uc640 \ube5b, \ud314\uacfc \uc190\uc758 \ubc29\ud5a5\uc774 \uc8fc\ubcc0\uc758 \uc6c0\uc9c1\uc784\uc744 \uc815\ub9ac\ud55c\ub2e4. \uc190\uc744 \ub0b4\ubbf8\ub294 \ubab8\uc9d3\uc740 \uadf8\ub824\uc9c4 \uacf5\uac04\uc744 \uad00\uac1d \ucabd\uc73c\ub85c \uc5f4\uc5b4 \uc8fc\ub294 \ub4ef\ud558\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \ud55c\uc790\ub9ac\uc5d0 \ubaa8\uc5ec \uc788\uc9c0\ub9cc \ubaa8\ub450 \uac19\uc740 \uc77c\uc744 \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uba85\ub839\uc744 \uc8fc\ub294 \uc0ac\ub78c\uacfc \uc900\ube44\ud558\ub294 \uc0ac\ub78c, \uc606\uc73c\ub85c \ubcf4\ub294 \uc0ac\ub78c\uc758 \ucc28\uc774\uac00 \uc9d1\ub2e8\uc758 \ud65c\ub3d9\uc744 \uad6c\uccb4\uc801\uc778 \ud589\ub3d9\uc73c\ub85c \ub098\ub208\ub2e4. \uc791\uc740 \uc18c\ub140\uc758 \ubc1d\uc740 \ubaa8\uc2b5\uc740 \uc5b4\ub450\uc6b4 \uc778\ubb3c\ub4e4 \uc0ac\uc774\uc5d0\uc11c \uac15\ud558\uac8c \ub4dc\ub7ec\ub09c\ub2e4. \uc774\ub97c \uc6b0\uc5f0\ud788 \uc9c0\ub098\uac00\ub358 \uc2dc\ubbfc\uc758 \ucd08\uc0c1\uc774\ub77c\uace0\ub9cc \uc0dd\uac01\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \uadf8\ub140\ub294 \ud654\uba74\uc758 \uc0c1\uc9d5\uc801\uc778 \uc5ed\ud560\uc744 \uc0dd\uac01\ud558\uac8c \ud558\ub294 \uc874\uc7ac\ub2e4. \ud5c8\ub9ac\uc5d0 \ub2ec\ub9b0 \uc0c8\uc758 \ubc1c\ud1b1 \uac19\uc740 \uc694\uc18c\ub3c4 \ubbfc\ubcd1\ub300\uc758 \ud45c\uc9c0\uc640 \uc5f0\uacb0\ub418\uc5b4 \ud574\uc11d\ub41c\ub2e4. \ub2e4\ub9cc \uc0c1\uc9d5\uc758 \uc138\ubd80 \ud574\uc11d\uc744 \uadf8\ub9bc \uc18d \ubaa8\ub4e0 \ubb3c\uac74\uc744 \ud478\ub294 \uc720\uc77c\ud55c \uc554\ud638\ud45c\ub85c \ub9cc\ub4e4 \ud544\uc694\ub294 \uc5c6\ub2e4. \uba3c\uc800 \ubc1d\uc740 \uc778\ubb3c\uc774 \uc2dc\uc120\uc744 \uc5b4\ub514\ub85c \ub04c\uace0 \uac00\ub294\uc9c0 \ud655\uc778\ud574 \ubcf4\uc790. \ucd08\uc0c1\uc758 \uc8fc\uc778\uacf5\ucc98\ub7fc \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc791\uc740 \uc0ac\ub78c\uc774 \uc804\uccb4 \ud654\uba74\uc758 \uade0\ud615\uc5d0 \ud070 \uc5ed\ud560\uc744 \ud55c\ub2e4. \uc774 \uc7a5\uba74\uc5d0\uc11c \ubc1d\uc74c\uc740 \uc870\uba85\uc744 \ub9ce\uc774 \ubc1b\uc740 \uc790\ub9ac \uc774\uc0c1\uc758 \uc5ed\ud560\uc744 \ud55c\ub2e4. \uba40\ub9ac \uc788\ub294 \uad00\uac1d\uc5d0\uac8c \ub204\uad6c\ub97c \uba3c\uc800 \ubcf4\uc544\uc57c \ud558\ub294\uc9c0 \uc548\ub0b4\ud558\ub294 \uc21c\uc11c\uac00 \ub41c\ub2e4. \ud654\uba74\uc758 \ubaa8\ub4e0 \uc5bc\uad74\uc744 \ud55c\uaebc\ubc88\uc5d0 \ub610\ub837\ud558\uac8c \uae30\uc5b5\ud558\uae30\ub294 \uc5b4\ub835\uc9c0\ub9cc, \ube5b\uc744 \ub530\ub77c \uba87 \uad70\ub370\ub97c \uc5f0\uacb0\ud558\uba74 \ud070 \uad6c\uc131\uc744 \ub2e4\uc2dc \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \ub2e8\uccb4 \uc0ac\uc9c4\uacfc \ube44\uad50\ud574 \ubcf4\ub294 \uac83\ub3c4 \uc88b\uc740 \ubc29\ubc95\uc774\ub2e4. \uc0ac\ub78c\uc758 \uc5bc\uad74\uc744 \uac00\ub9ac\uc9c0 \uc54a\uace0 \ubaa8\ub450\ub97c \uc54c\uc544\ubcf4\uac8c \ucc0d\uc73c\ub824\ub294 \ubaa9\uc801\uacfc, \uc9d1\ub2e8\uc774 \uc6c0\uc9c1\uc774\ub294 \uc21c\uac04\uc744 \ub9cc\ub4e4\ub824\ub294 \ubaa9\uc801\uc740 \ub2e4\ub974\ub2e4. \uc5b4\ub290 \ubc29\uc2dd\uc774 \ub354 \ub0ab\ub2e4\uace0 \uacb0\ub860\ub0b4\ub9ac\uae30\ubcf4\ub2e4 \uc774 \uadf8\ub9bc\uc774 \ubb34\uc5c7\uc744 \uc6b0\uc120\ud588\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uba74 \uc9d1\ub2e8 \ucd08\uc0c1\uc774\ub77c\ub294 \uc7a5\ub974\uc758 \uac00\ub2a5\uc131\uc774 \ubcf4\uc778\ub2e4. \uae38\uac8c \ubed7\uc740 \ucc3d\uacfc \ucd1d, \uae43\ubc1c\uc740 \uc11c\ub85c \ub2e4\ub978 \ubc29\ud5a5\uc744 \ub9cc\ub4e0\ub2e4. \uace7\uc740 \uc120\ub4e4\uc774 \uc0ac\ub78c\ub4e4\uc758 \ubab8\uacfc \uacb9\uce58\uba74\uc11c \ub208\uc740 \ud654\uba74\uc758 \uc704\uc544\ub798\uc640 \uc88c\uc6b0\ub97c \uc624\uac04\ub2e4. \uc6c0\uc9c1\uc784\uc758 \ub290\ub08c\uc740 \uc778\ubb3c\uc758 \uc790\uc138\ub9cc\uc774 \uc544\ub2c8\ub77c \uc774\ub7f0 \uae38\ucb49\ud55c \ubb3c\uac74\uc758 \ubc30\uce58\uc5d0\uc11c\ub3c4 \ub098\uc628\ub2e4. \uc2dc\uc120\uc774 \ud769\uc5b4\uc9c8 \ub9cc\ud55c \uc694\uc18c\uac00 \ub9ce\uc9c0\ub9cc \uc55e\uc758 \ubc1d\uc740 \uc778\ubb3c\uacfc \uc190\uc758 \ubc29\ud5a5\uc774 \ub2e4\uc2dc \uc911\uc2ec\uc744 \uc7a1\ub294\ub2e4. \uac00\uae4c\uc774\uc11c \uc138\ubd80\ub97c \ubcf8 \ub4a4 \uba40\ub9ac\uc11c \ud070 \ub369\uc5b4\ub9ac\ub97c \ubcf4\uba74, \ubcf5\uc7a1\ud568\uc774 \uc544\ubb34\ub807\uac8c\ub098 \uc313\uc778 \uac83\uc774 \uc544\ub2d8\uc744 \uc54c \uc218 \uc788\ub2e4. \ub9ce\uc740 \uc0ac\ub78c\uc744 \uadf8\ub9ac\ub294 \uc77c\uacfc \ub9ce\uc740 \uc2dc\uc120\uc744 \uc870\uc9c1\ud558\ub294 \uc77c\uc774 \ud568\uaed8 \uc774\ub8e8\uc5b4\uc84c\ub2e4. \uc61b \uc804\uae30\uc5d0\ub294 \uc774 \uc791\ud488\uc774 \uc8fc\ubb38\uc790\ub4e4\uc758 \ubd84\ub178\ub97c \ubd88\ub7ec \ub818\ube0c\ub780\ud2b8\uc758 \uc0b6\uc744 \uace7\ubc14\ub85c \ubb34\ub108\ub728\ub838\ub2e4\ub294 \uc2dd\uc758 \uc774\uc57c\uae30\ub3c4 \uc788\ub2e4. \uadf9\uc801\uc778 \uc124\uba85\uc740 \uae30\uc5b5\ud558\uae30 \uc27d\uc9c0\ub9cc \ud55c \uc791\uac00\uc758 \uacbd\uc81c\uc801 \ubb38\uc81c\uc640 \uc778\uac04\uad00\uacc4\ub97c \ud55c \uc7a5\uc758 \uadf8\ub9bc \ub54c\ubb38\uc774\ub77c\uace0 \ub2e8\uc815\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \uc791\ud488\uc758 \uc0c8\ub85c\uc6b4 \uad6c\uc131\uc774 \uc5b4\ub5a4 \ubc18\uc751\uc744 \ub0b3\uc558\ub294\uc9c0\uc640 \uc774\ud6c4 \uc0dd\uc560\uc758 \ubcf5\uc7a1\ud55c \ubcc0\ud654\ub294 \uad6c\ubd84\ud574\uc11c \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc720\uba85\ud55c \ubbf8\uc220 \uc77c\ud654\uc77c\uc218\ub85d \ucd9c\ucc98\uc640 \ucd94\uc815\uc758 \ubc94\uc704\ub97c \uc0b4\ud53c\ub294 \ud0dc\ub3c4\uac00 \ud544\uc694\ud558\ub2e4. \uac10\ub3d9\uc801\uc778 \uc804\uc124\uc744 \ubc18\ubcf5\ud558\ub294 \ub300\uc2e0 \uc2e4\uc81c \ud654\uba74\uc5d0 \ub0a8\uc740 \uc120\ud0dd\uc73c\ub85c \ub3cc\uc544\uc62c \uc218 \uc788\ub2e4. \u300c\uc57c\uacbd\u300d\uc744 \ub2e4\uc2dc \ubcfc \ub54c\uc5d0\ub294 \ub204\uad6c\uc758 \uc5bc\uad74\uc774 \uac00\uc7a5 \uc798 \ubcf4\uc774\ub294\uc9c0\uc5d0\uc11c \uc2dc\uc791\ud574 \ubcf4\uc790. \ub2e4\uc74c\uc5d0\ub294 \ubc1d\uc740 \ubd80\ubd84\ub4e4\uc744 \uc5f0\uacb0\ud558\uace0, \uadf8 \uc0ac\uc774\uc758 \uc5b4\ub450\uc6b4 \uacf5\uac04\uc774 \uc5bc\ub9c8\ub098 \uae4a\uc774\ub97c \ub9cc\ub4dc\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uba74 \uc88b\ub2e4. \uc81c\ubaa9\uc774 \ubbf8\ub9ac \uc815\ud55c \ubd84\uc704\uae30\uc640 \ub208\uc73c\ub85c \ud655\uc778\ud55c \ud6a8\uacfc\ub97c \ube44\uad50\ud558\ub294 \uac83\uc774\ub2e4. \uc774 \uadf8\ub9bc\uc740 \ubbfc\ubcd1\ub300\ub77c\ub294 \uc9d1\ub2e8\uc758 \uae30\uc5b5\uc774\uba74\uc11c \ub818\ube0c\ub780\ud2b8\uac00 \uc0ac\ub78c\ub4e4\uc744 \ud558\ub098\uc758 \uc7a5\uba74\uc73c\ub85c \uc870\uc9c1\ud55c \uacb0\uacfc\ub2e4. \ubaa8\ub450\ub97c \ub611\uac19\uc774 \ubcf4\uc5ec \uc8fc\uc9c0 \uc54a\uc73c\uba74\uc11c \ud568\uaed8 \uc788\ub2e4\ub294 \ub290\ub08c\uc744 \ub9cc\ub4dc\ub294 \ubc29\ubc95\uc774 \ub2f4\uaca8 \uc788\ub2e4. \uac19\uc740 \uc0ac\ub78c\ub3c4 \ud654\uba74\uc758 \uc5b4\ub290 \uc790\ub9ac\uc5d0 \ub193\uc774\ub294\uac00\uc5d0 \ub530\ub77c \ub2e4\ub974\uac8c \uae30\uc5b5\ub41c\ub2e4. \ubc24\uc778\uc9c0 \uc544\ub2cc\uc9c0\ub97c \ubb3b\ub294 \ub370\uc11c \ucd9c\ubc1c\ud55c \uac10\uc0c1\uc740 \uacf5\ub3d9\uccb4\ub97c \uc5b4\ub5bb\uac8c \ubcf4\uc774\uac8c \ud560 \uac83\uc778\uac00 \ud558\ub294 \uc9c8\ubb38\uc73c\ub85c \ub113\uc5b4\uc9c4\ub2e4."}, {"id": "robinson-crusoe-tools-footprint-friday", "title": "\u300e\ub85c\ube48\uc2a8 \ud06c\ub8e8\uc18c\u300f \u2014 \ubb34\uc778\ub3c4\uc5d0\ub294 \uc815\ub9d0 \ud63c\uc790\uc600\uc744\uae4c", "summary": "\uc904\uac70\ub9ac\uc640 \ud568\uaed8 \uc0dd\uc874\uc758 \uc138\ubd80, \ud0c0\uc778\uc5d0 \ub300\ud55c \ub450\ub824\uc6c0, \uc791\ud488\uc5d0 \ub0a8\uc740 \uc2dd\ubbfc\uc8fc\uc758\uc758 \uc2dc\uc120\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/robinson-crusoe-tools-footprint-friday/index.html", "image": "../media/robinson-crusoe-tools-footprint-friday.png", "alt": "\uc12c\uc758 \uac70\ucc98 \uc606\uc5d0\uc11c \ub3c4\uad6c\ub97c \uc815\ub9ac\ud558\ub294 \ud45c\ub958\uc790\uc640 \uc5fc\uc18c\u00b7\uc791\uc740 \ubc2d\uc758 \uc18c\uc124 \uc7a5\uba74 \uc0bd\ud654", "text": "\u300e\ub85c\ube48\uc2a8 \ud06c\ub8e8\uc18c\u300f \u2014 \ubb34\uc778\ub3c4\uc5d0\ub294 \uc815\ub9d0 \ud63c\uc790\uc600\uc744\uae4c \ub09c\ud30c\uc120\uc758 \uc5f0\uc7a5, \ubaa8\ub798 \uc704 \ubc1c\uc790\uad6d, \ud504\ub77c\uc774\ub370\uc774\uac00 \ubc14\uafbc \uc0dd\uc874 \uc774\uc57c\uae30 \uc904\uac70\ub9ac\uc640 \ud568\uaed8 \uc0dd\uc874\uc758 \uc138\ubd80, \ud0c0\uc778\uc5d0 \ub300\ud55c \ub450\ub824\uc6c0, \uc791\ud488\uc5d0 \ub0a8\uc740 \uc2dd\ubbfc\uc8fc\uc758\uc758 \uc2dc\uc120\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \ubb34\uc778\ub3c4\uc5d0 \ub5a8\uc5b4\uc9c4 \uc0ac\ub78c\uc740 \ubb34\uc5c7\ubd80\ud130 \ud574\uc57c \ud560\uae4c. \ud754\ud788 \ubd88\uc744 \ud53c\uc6b0\uac70\ub098 \uc9d1\uc744 \uc9c0\uc73c\ub9ac\ub77c \uc0dd\uac01\ud55c\ub2e4. \uadf8\ub7f0\ub370 \u300e\ub85c\ube48\uc2a8 \ud06c\ub8e8\uc18c\u300f\uc758 \uc8fc\uc778\uacf5\uc740 \uba3c\uc800 \ub09c\ud30c\uc120\uc73c\ub85c \ub3cc\uc544\uac04\ub2e4. \uc0b4\uc544\ub0a8\uae30 \uc704\ud574 \ud544\uc694\ud55c \uac83\uc740 \uc6a9\uae30\ubfd0 \uc544\ub2c8\ub77c \uc774\ubbf8 \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc774 \ub9cc\ub4e4\uc5b4 \ub454 \uc5f0\uc7a5\uacfc \ubb3c\uac74\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \ub300\ub2c8\uc5bc \ub514\ud3ec\uc758 \uc18c\uc124\uc744 \ub9c9\uc5f0\ud788 \ud63c\uc790\uc11c \ubaa8\ub4e0 \uac83\uc744 \uc774\ub8ec \ub0a8\uc790\uc758 \uc774\uc57c\uae30\ub85c \uae30\uc5b5\ud558\uba74 \uc911\uc694\ud55c \uc7a5\uba74\ub4e4\uc744 \ub193\uce5c\ub2e4. \uc774 \uae00\uc740 \uc12c\uc5d0 \uc774\ub974\uae30 \uc804\uc758 \uc0ac\uc5f0\ubd80\ud130 \uadc0\ud658\uae4c\uc9c0 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \ud3ec\ud568\ud55c\ub2e4. \ud06c\ub8e8\uc18c\ub294 \uc548\uc815\ub41c \uc0dd\ud65c\uc744 \ubc14\ub77c\ub294 \uac00\uc871\uc758 \ub73b\uc744 \uac70\uc2a4\ub974\uace0 \ubc14\ub2e4\ub85c \ub098\uac04\ub2e4. \ud56d\ud574\uc5d0\ub294 \uc704\ud5d8\uacfc \uac70\ub798\uac00 \ud568\uaed8 \ub530\ub77c\uc628\ub2e4. \uadf8\ub294 \ube0c\ub77c\uc9c8\uc5d0\uc11c \ub18d\uc7a5\uc744 \uc6b4\uc601\ud558\uac8c \ub418\uace0, \ub354 \ub9ce\uc740 \ub178\ub3d9\ub825\uc744 \uc5bb\uae30 \uc704\ud574 \uc544\ud504\ub9ac\uce74\ub85c \uc0ac\ub78c\uc744 \uc0ac\ub7ec \uac00\ub294 \ud56d\ud574\uc5d0 \ucc38\uc5ec\ud55c\ub2e4. \uadf8 \uae38\uc5d0\uc11c \ubc30\uac00 \ub09c\ud30c\ud55c\ub2e4. \uc774 \ucd9c\ubc1c\uc740 \ub2e8\uc21c\ud788 \ub0af\uc120 \uc138\uc0c1\uc744 \uad6c\uacbd\ud558\ub824 \ub5a0\ub09c \uc5ec\ud589\uacfc \ub2e4\ub974\ub2e4. \uc791\ud488\uc758 \uacbd\uc81c \ud65c\ub3d9\uc5d0\ub294 \ub178\uc608\uc81c\uac00 \uae4a\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ud06c\ub8e8\uc18c \uc790\uc2e0\uc774 \ud55c\ub54c \ubd99\uc7a1\ud600 \uc5b5\ub958\ub41c \uacbd\ud5d8\uacfc, \uc774\ud6c4 \ud0c0\uc778\uc744 \uc0ac\uace0\ud30c\ub294 \uccb4\uacc4\uc5d0 \ucc38\uc5ec\ud558\ub294 \uc77c\ub3c4 \ud568\uaed8 \ub4f1\uc7a5\ud55c\ub2e4. \uc8fc\uc778\uacf5\uc744 \uc751\uc6d0\ud558\uba74\uc11c\ub3c4 \uadf8\uac00 \uc11c \uc788\ub294 \uc138\uacc4\ub97c \ube7c\ub193\uc9c0\ub294 \ub9d0\uc544\uc57c \ud55c\ub2e4. \ud640\ub85c \ud574\ubcc0\uc5d0 \uc0b4\uc544\ub0a8\uc740 \ud06c\ub8e8\uc18c\ub294 \ubc30\uac00 \uc644\uc804\ud788 \uc0ac\ub77c\uc9c0\uae30 \uc804\uc5d0 \uc5ec\ub7ec \ucc28\ub840 \ubb3c\uac74\uc744 \uc62e\uae34\ub2e4. \ucd1d\uacfc \ud654\uc57d, \uba39\uc744 \uac83, \uc637\uacfc \ub3c4\uad6c\uac00 \uadf8\uc758 \uc0dd\uc874 \uae30\ubc18\uc774 \ub41c\ub2e4. \ubb3c\uac74\uc744 \uc2e3\uace0 \ub098\ub97c \ub5cf\ubaa9\ub3c4 \ub9cc\ub4e0\ub2e4. \uc12c\uc5d0\uc11c \uc2dc\uc791\ud558\ub294 \uc0c8 \uc0dd\ud65c\uc740 \uc774\uc804 \uc0ac\ud68c\uc640 \uc644\uc804\ud788 \ub04a\uc5b4\uc9c4 \ucd9c\ubc1c\uc774 \uc544\ub2c8\ub2e4. \uc774 \uc810\uc744 \uc54c\uba74 \ubaa8\ud5d8\uc774 \ub35c \ub300\ub2e8\ud574\uc9c0\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ub354 \uad6c\uccb4\uc801\uc774 \ub41c\ub2e4. \ub9e8\uc190\uc758 \uc758\uc9c0\ub9cc\uc73c\ub85c \ub3c4\ub07c\uc640 \ucd1d\uc744 \ub9cc\ub4e4 \uc218\ub294 \uc5c6\ub2e4. \uadf8\uac00 \uc758\uc9c0\ud558\ub294 \ubb3c\uac74\uc5d0\ub294 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc7a5\uc778\uacfc \uc120\uc6d0\ub4e4\uc758 \ub178\ub3d9\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ud63c\uc790 \uc0b4\uc544\uac00\ub294 \uc7a5\uba74 \ud55c\uac00\uc6b4\ub370 \uc774\ubbf8 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \ud754\uc801\uc774 \ub193\uc5ec \uc788\ub294 \uc148\uc774\ub2e4. \ud06c\ub8e8\uc18c\ub294 \uac70\ucc98\ub97c \ub9c8\ub828\ud558\uace0 \ub458\ub808\ub97c \ub9c9\uc73c\uba70 \uba39\uc744 \uac83\uc744 \ubcf4\uad00\ud55c\ub2e4. \ub0a0\uc9dc\ub97c \uc138\uace0, \ud574\uc57c \ud560 \uc77c\uc744 \ub098\ub204\uace0, \ubab8\uc774 \uc544\ud504\uba74 \ud63c\uc790 \uacac\ub518\ub2e4. \ub3c5\uc790\uac00 \uc77d\ub294 \uac83\uc740 \uba4b\uc9c4 \ud0c8\ucd9c \uc7a5\uba74\ub9cc\uc774 \uc544\ub2c8\ub77c \uac19\uc740 \uc77c\uc744 \ub418\ud480\uc774\ud574\uc57c \uc720\uc9c0\ub418\ub294 \ud558\ub8e8\ub2e4. \uc0dd\uc874\uc740 \ub04a\uc784\uc5c6\uc774 \ubb3c\uac74\uc744 \uc190\uc9c8\ud558\ub294 \uc0dd\ud65c\ub85c \ud3bc\uccd0\uc9c4\ub2e4. \ub18d\uc0ac\ub3c4 \ud55c \ubc88\uc5d0 \uc131\uacf5\ud558\uc9c0 \uc54a\ub294\ub2e4. \uace1\uc2dd\uc774 \uc790\ub77c\ub294 \uac83\uc744 \ubc1c\uacac\ud588\ub2e4\uace0 \ubc14\ub85c \ube75\uc774 \uc0dd\uae30\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc528\uc557\uc744 \ub0a8\uae30\uace0 \uc218\ud655\uc744 \uae30\ub2e4\ub9ac\uace0 \uc800\uc7a5\ud558\ub294 \uacfc\uc815\uc774 \ub4a4\ub530\ub978\ub2e4. \uadf8\ub987\uc744 \ub9cc\ub4e4\uac70\ub098 \ubb3c\uac74\uc744 \uc62e\uae30\ub294 \uc77c\uc5d0\uc11c\ub3c4 \uc2e4\ud328\uac00 \ub098\uc628\ub2e4. \uc18c\uc124\uc758 \uc790\uc138\ud55c \uc124\uba85\uc740 \ud3b8\ub9ac\ud55c \uc77c\uc0c1\uc774 \uc5bc\ub9c8\ub098 \ub9ce\uc740 \ub2e8\uacc4 \uc704\uc5d0 \uc11c \uc788\ub294\uc9c0 \ubcf4\uc5ec \uc900\ub2e4. \uc5fc\uc18c\ub97c \uae30\ub974\uace0 \uc0dd\ud65c\uc774 \uc548\uc815\ub418\uc5b4\ub3c4 \uc678\ub85c\uc6c0\uae4c\uc9c0 \ud574\uacb0\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc77c\uae30\ub97c \uc4f0\uace0 \uc131\uacbd\uc744 \uc77d\uc73c\uba70 \uc790\uc2e0\uc758 \uc0b6\uc5d0 \uc758\ubbf8\ub97c \ucc3e\uc73c\ub824 \ud55c\ub2e4. \uc791\ud488 \uc18d \uc2e0\uc559\uc740 \uc12c \uc0dd\ud65c\uc5d0 \ub367\ubd99\uc778 \uc7a5\uc2dd\uc774 \uc544\ub2c8\ub77c \uc8fc\uc778\uacf5\uc774 \ubd88\uc6b4\uacfc \uc0dd\uc874\uc744 \uc774\ud574\ud558\ub294 \ubc29\uc2dd\uc758 \uc911\uc694\ud55c \ubd80\ubd84\uc774\ub2e4. \ud604\ub300 \ub3c5\uc790\uac00 \uac19\uc740 \ubbff\uc74c\uc744 \uac00\uc838\uc57c \uc774\uc57c\uae30\ub97c \uc77d\uc744 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ud06c\ub8e8\uc18c\uc5d0\uac8c \uba39\uc744 \uac83\uacfc \uc7a0\uc790\ub9ac\ub9cc\ud07c \uc0b6\uc744 \uc124\uba85\ud560 \ub9d0\ub3c4 \ud544\uc694\ud588\ub2e4\ub294 \uc810\uc774\ub2e4. \uc77c\uacfc \uae30\ub85d\uacfc \uc2e0\uc559\uc774 \ud568\uaed8 \uc2dc\uac04\uc744 \ucc44\uc6b4\ub2e4. \uad6c\uc870\ub420 \ub54c\uae4c\uc9c0 \uba48\ucdb0 \uc788\ub294 \uc0ac\ub78c\uc774 \uc544\ub2c8\ub77c, \uadf8 \uae30\ub2e4\ub9bc \uc548\uc5d0 \ud558\ub098\uc758 \uc0dd\ud65c\uc744 \ub9cc\ub4e0 \uc0ac\ub78c\uc73c\ub85c \ubc14\ub010\ub2e4. \uc5b4\ub290 \ub0a0 \ubaa8\ub798 \uc704\uc5d0\uc11c \uc0ac\ub78c\uc758 \ubc1c\uc790\uad6d\uc744 \ubc1c\uacac\ud55c\ub2e4. \uc624\ub798 \ubc14\ub77c\ub358 \ud0c0\uc778\uc758 \ud754\uc801\uc774\uc5b4\uc57c \ud560 \uac83 \uac19\uc740\ub370 \ud06c\ub8e8\uc18c\uc758 \uccab \ubc18\uc751\uc740 \uacf5\ud3ec\ub2e4. \uc9d1\uc744 \ub4e4\ud0a4\uc9c0\ub294 \uc54a\uc744\uae4c, \ub204\uac00 \ub2e4\uac00\uc624\ub294 \uac83\uc740 \uc544\ub2d0\uae4c \uac71\uc815\ud558\uba70 \uc790\uc2e0\uc774 \ub9cc\ub4e0 \uc548\uc804\uc744 \ub2e4\uc2dc \uc810\uac80\ud55c\ub2e4. \uc12c\uc740 \uadf8\ub300\ub85c\uc778\ub370 \uadf8 \uc12c\uc744 \ubcf4\ub294 \ub208\uc774 \ubc14\ub010\ub2e4. \uc678\ub86d\ub2e4\uace0 \ud574\uc11c \ub0af\uc120 \uc0ac\ub78c\uc774 \uace7\ubc14\ub85c \ubc18\uac00\uc6b4 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc0ac\uc2e4\uc774 \uc774 \uc7a5\uba74\uc744 \uac15\ud558\uac8c \ub9cc\ub4e0\ub2e4. \uc790\uc2e0\uc774 \ud1b5\uc81c\ud560 \uc218 \uc788\ub358 \uc138\uacc4\uc5d0 \ub2e4\ub978 \uc758\uc9c0\uac00 \ub4e4\uc5b4\uc628\ub2e4. \ud06c\ub8e8\uc18c\uac00 \uc12c\uc758 \uc8fc\uc778\ucc98\ub7fc \ub290\ub07c\uac8c \ub41c \uacfc\uc815\ub3c4 \ub4dc\ub7ec\ub09c\ub2e4. \ubc1c\uc790\uad6d\uc740 \ud0c0\uc778\uc758 \uc874\uc7ac\uc778 \ub3d9\uc2dc\uc5d0 \uc18c\uc720\uc640 \uacbd\uacc4\uc5d0 \uad00\ud55c \ubd88\uc548\uc774\ub2e4. \ud06c\ub8e8\uc18c\ub294 \uc704\uae30\uc5d0 \ub193\uc778 \ud55c \uc0ac\ub78c\uc744 \uad6c\ud558\uace0 \ud504\ub77c\uc774\ub370\uc774\ub77c\ub294 \uc774\ub984\uc744 \ubd99\uc778\ub2e4. \ud568\uaed8 \uc77c\ud558\uace0 \ub9d0\uc744 \uc775\ud788\uba70 \uad00\uacc4\ub97c \ub9fa\ub294 \uacfc\uc815\uc740 \uace0\ub3c5\ud55c \uc12c\uc758 \ubd84\uc704\uae30\ub97c \ubc14\uafbc\ub2e4. \ud06c\ub8e8\uc18c\uc5d0\uac8c\ub294 \ud611\ub825\uc790\uac00 \uc0dd\uae30\uace0, \ub3c5\uc790\uc5d0\uac8c\ub294 \ub300\ud654\uc640 \uc0c8\ub85c\uc6b4 \uc2dc\uc120\uc774 \ub4e4\uc5b4\uc628\ub2e4. \uadf8\ub7ec\ub098 \uc774\ub984\uc744 \uc815\ud558\ub294 \ucabd\ub3c4, \uc790\uc2e0\uc744 \uc8fc\uc778\uc774\ub77c\uace0 \ubd80\ub974\ub3c4\ub85d \uac00\ub974\uce58\ub294 \ucabd\ub3c4 \ud06c\ub8e8\uc18c\ub2e4. \ud504\ub77c\uc774\ub370\uc774\ub294 \uc12c\uc5d0\uc11c \ud0dc\uc5b4\ub09c \ube48 \uc885\uc774\uac00 \uc544\ub2c8\ub77c \uc774\uc804\uc758 \uc5b8\uc5b4\uc640 \uad00\uacc4\ub97c \uac00\uc9c4 \uc0ac\ub78c\uc774\ub2e4. \uad6c\uc870\uc640 \uc6b0\uc815\uc774 \uc788\ub2e4\ub294 \uc774\uc720\ub85c \uc774 \ubd88\uade0\ud615\uc774 \uc0ac\ub77c\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub458\uc758 \uad00\uacc4\ub97c \uc77d\ub294 \uc77c\uc740 \ubaa8\ud5d8\ub2f4\uc758 \uc7ac\ubbf8\uc640 \uc2dd\ubbfc\uc8fc\uc758\uc758 \uc2dc\uc120\uc744 \ud568\uaed8 \ubcf4\ub294 \uc77c\uc774\ub2e4. \ub9c8\uce68\ub0b4 \ub2e4\ub978 \ubc30\uc640 \uc120\uc6d0\ub4e4\uc774 \uc774\uc57c\uae30 \uc548\uc73c\ub85c \ub4e4\uc5b4\uc624\uace0, \uc120\uc0c1 \ubc18\ub780\uc744 \ub458\ub7ec\uc2fc \uc0ac\uac74\uc774 \ud0c8\ucd9c\uc758 \uae30\ud68c\uac00 \ub41c\ub2e4. \ud06c\ub8e8\uc18c\ub294 \uc120\uc7a5\uc744 \ub3c4\uc6b0\uba70 \uc12c\uc744 \ub5a0\ub0a0 \uae38\uc744 \uc5bb\ub294\ub2e4. \uadf8\ub7ec\ub098 \uc18c\uc124\uc740 \ud574\ubcc0\uc5d0\uc11c \ubc30\ub97c \ubc1c\uacac\ud558\ub294 \ud658\ud638 \ud558\ub098\ub85c \ubaa8\ub4e0 \ubb38\uc81c\ub97c \uc9c0\uc6cc \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \ubc14\uae65\uc5d0\ub294 \uadf8\uac00 \ub5a0\ub098\uc628 \uacbd\uc81c\uc640 \uc778\uac04\uad00\uacc4\uac00 \uc5ec\uc804\ud788 \uae30\ub2e4\ub9b0\ub2e4. \u300e\ub85c\ube48\uc2a8 \ud06c\ub8e8\uc18c\u300f\ub294 \uc2e4\uc81c \uc778\ubb3c\uc758 \uc77c\uae30\ub97c \uadf8\ub300\ub85c \uc62e\uae34 \ucc45\uc774 \uc544\ub2c8\ub77c \ud5c8\uad6c\uc758 \uc778\ubb3c\uc774 \uc790\uc2e0\uc758 \uc0b6\uc744 \ub9d0\ud558\ub294 \uc18c\uc124\uc774\ub2e4. \uadf8 \ubaa9\uc18c\ub9ac\uac00 \uc6cc\ub099 \uad6c\uccb4\uc801\uc774\ub77c \uc6b0\ub9ac\ub294 \uc5f0\uc7a5\uacfc \ubc1c\uc790\uad6d\uc744 \uc2e4\uc81c \uae30\uc5b5\ucc98\ub7fc \uac04\uc9c1\ud55c\ub2e4. \ub2e4\uc2dc \uc77d\uc744 \ub9cc\ud55c \uc774\uc720\ub3c4 \uac70\uae30\uc5d0 \uc788\ub2e4. \ud63c\uc790 \uc0b4\uc544\ub0a8\uc558\ub2e4\ub294 \uc775\uc219\ud55c \ud55c \ubb38\uc7a5 \ub4a4\uc5d0\uc11c, \uadf8\ub97c \uc0b4\uac8c \ud55c \ubb3c\uac74\uacfc \ud0c0\uc778\ub4e4\uc758 \ubaa8\uc2b5\uc744 \uc0c8\ub86d\uac8c \ubc1c\uacac\ud560 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4."}, {"id": "romeo-juliet-names-and-missed-letter", "title": "\ub85c\ubbf8\uc624\uc640 \uc904\ub9ac\uc5e3 \u2014 \ub450 \uc0ac\ub78c \uc0ac\uc774\uc5d0 \uc774\ub984\uacfc \ud3b8\uc9c0\uac00 \ub193\uc774\ub2e4", "summary": "\uac00\ubb38\uc758 \uac08\ub4f1\uacfc \ube44\ubc00 \uacb0\ud63c, \uc804\ud574\uc9c0\uc9c0 \uc54a\uc740 \ud3b8\uc9c0\uc640 \uacb0\ub9d0\uc744 \ub530\ub77c \ube44\uadf9\uc758 \uc870\uac74\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/romeo-juliet-names-and-missed-letter/index.html", "image": "../media/romeo-juliet-names-and-missed-letter.png", "alt": "\ubca0\ub85c\ub098\uc758 \uc815\uc6d0\uacfc \ubc1c\ucf54\ub2c8\uc5d0\uc11c \ub9cc\ub09c \ub450 \uc5f0\uc778\uc744 \uadf8\ub9b0 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ub85c\ubbf8\uc624\uc640 \uc904\ub9ac\uc5e3 \u2014 \ub450 \uc0ac\ub78c \uc0ac\uc774\uc5d0 \uc774\ub984\uacfc \ud3b8\uc9c0\uac00 \ub193\uc774\ub2e4 \uc0ac\ub791\ubcf4\ub2e4 \uba3c\uc800 \uc788\uc5c8\ub358 \uac00\ubb38\uc758 \ub2e4\ud23c\uc5d0\uc11c \uc2dc\uc791\ud558\ub294 \uc5ed\uc0ac\uc640 \uc791\ud488 \uc77d\uae30 \uac00\ubb38\uc758 \uac08\ub4f1\uacfc \ube44\ubc00 \uacb0\ud63c, \uc804\ud574\uc9c0\uc9c0 \uc54a\uc740 \ud3b8\uc9c0\uc640 \uacb0\ub9d0\uc744 \ub530\ub77c \ube44\uadf9\uc758 \uc870\uac74\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \uc11c\ub85c \uc0ac\ub791\ud558\ub294 \ub450 \uc0ac\ub78c\uc774 \uc788\ub294\ub370 \uac00\uc871\ub4e4\uc740 \uc6d0\uc218 \uc0ac\uc774\ub2e4. \u300e\ub85c\ubbf8\uc624\uc640 \uc904\ub9ac\uc5e3\u300f\uc758 \ucd9c\ubc1c\uc740 \ub110\ub9ac \uc54c\ub824\uc838 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc170\uc775\uc2a4\ud53c\uc5b4\uc758 \ube44\uadf9\uc744 \ub05d\uae4c\uc9c0 \ub530\ub77c\uac00\uba74 \uc0ac\ub791\uacfc \uc99d\uc624\ub9cc\uc73c\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\ub294 \uc77c\ub4e4\uc774 \ubcf4\uc778\ub2e4. \uacb0\ud63c\uc758 \uacb0\uc815, \uac70\ub9ac\uc758 \ud3ed\ub825, \uc5b4\ub978\ub4e4\uc758 \ub3c4\uc6c0\uacfc \uc804\ub2ec\ub418\uc9c0 \ubabb\ud55c \ud3b8\uc9c0\uac00 \uc11c\ub85c \uc5bd\ud78c\ub2e4. \ubb34\ub300\ub294 \uc774\ud0c8\ub9ac\uc544 \ubca0\ub85c\ub098\uc9c0\ub9cc \uc5ec\uae30\uc11c\ub294 \uc601\ubb38\ud559 \uc791\ud488\uc758 \ub9e5\ub77d\uc73c\ub85c \uc77d\ub294\ub2e4. \uc544\ub798\uc5d0\ub294 \uc8fc\uc694 \uc0ac\uac74\uacfc \uacb0\ub9d0\uc774 \ud3ec\ud568\ub41c\ub2e4. \uc720\uba85\ud55c \ubc1c\ucf54\ub2c8 \uc7a5\uba74\uc5d0\uc11c \uc7a0\uc2dc \ub354 \ub098\uc544\uac00 \ub450 \uc0ac\ub78c\uc744 \ub458\ub7ec\uc2fc \ub3c4\uc2dc\uc640 \uad00\uacc4\uac00 \uc5b4\ub5bb\uac8c \ube44\uadf9\uc744 \ub9cc\ub4e4\uc5c8\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \ubaac\ud130\uaddc\uc640 \uce90\ud480\ub81b \ub450 \uc9d1\uc548\uc758 \ub300\ub9bd\uc740 \uac70\ub9ac\uc758 \uc2f8\uc6c0\uc73c\ub85c \ubc88\uc9c4\ub2e4. \uac08\ub4f1\uc740 \uc9d1 \uc548\uc758 \ub9d0\ub2e4\ud23c\ub9cc\uc774 \uc544\ub2c8\ub77c \ub3c4\uc2dc\uc758 \uc548\uc804\uacfc \uc9c8\uc11c\ub97c \ud754\ub4dc\ub294 \ubb38\uc81c\ub2e4. \ub85c\ubbf8\uc624\uc640 \uc904\ub9ac\uc5e3\uc740 \uc790\uc2e0\ub4e4\uc774 \uc2dc\uc791\ud558\uc9c0 \uc54a\uc740 \uc801\ub300 \uc18d\uc5d0\uc11c \ub9cc\ub09c\ub2e4. \uac1c\uc778\uc5d0\uac8c \uc8fc\uc5b4\uc9c4 \uc774\ub984\uc774 \uc774\ubbf8 \uad00\uacc4\uc758 \uc870\uac74\uc744 \uc815\ud574 \ub193\uc740 \uc148\uc774\ub2e4. \ub85c\ubbf8\uc624\ub294 \uce90\ud480\ub81b \uc9d1\uc548\uc758 \uc794\uce58\uc5d0 \ub4e4\uc5b4\uac14\ub2e4\uac00 \uc904\ub9ac\uc5e3\uc744 \ub9cc\ub09c\ub2e4. \uc11c\ub85c\uc5d0\uac8c \ub04c\ub9b0 \ub4a4\uc5d0 \uc0c1\ub300\uac00 \uc5b4\ub5a4 \uac00\ubb38\uc5d0 \uc18d\ud558\ub294\uc9c0\uc758 \ubb38\uc81c\uac00 \ub530\ub77c\uc628\ub2e4. \uc791\ud488\uc5d0\uc11c \uc0ac\ub791\uc758 \uac15\ub3c4\ub9cc\ud07c \uc911\uc694\ud55c \uac83\uc740 \ud55c \uc0ac\ub78c\uc744 \uc9d1\ub2e8\uc758 \uc774\ub984\uc73c\ub85c \uba3c\uc800 \ud310\ub2e8\ud558\ub294 \uc9c8\uc11c\ub2e4. \ub450 \uc0ac\ub78c\uc740 \uadf8 \uc9c8\uc11c\ub97c \uc27d\uac8c \ubc97\uc5b4\ub0a0 \uc218 \uc5c6\ub2e4. \ub450 \uc0ac\ub78c\uc740 \uc11c\ub85c\uc758 \ub73b\uc744 \ud655\uc778\ud558\uace0 \ub85c\ub7f0\uc2a4 \uc218\uc0ac\uc758 \ub3c4\uc6c0\uc73c\ub85c \ube44\ubc00\ub9ac\uc5d0 \uacb0\ud63c\ud55c\ub2e4. \uc218\uc0ac\ub294 \uc774 \uacb0\ud569\uc774 \ub450 \uac00\ubb38\uc758 \uac08\ub4f1\uc744 \ub204\uadf8\ub7ec\ub728\ub9b4 \uac00\ub2a5\uc131\ub3c4 \uc0dd\uac01\ud55c\ub2e4. \uc0ac\ub791\uc740 \uac1c\uc778\uc758 \uc120\ud0dd\uc774\uba74\uc11c \ud654\ud574\ub97c \uc704\ud55c \ubc29\uc548\uc774 \ub41c\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uae30\ub300\ub97c \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc774 \ud568\uaed8 \uc54c\uace0 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc720\ubaa8 \uc5ed\uc2dc \uc904\ub9ac\uc5e3\uacfc \ubc14\uae65\uc138\uacc4\ub97c \uc787\ub294 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud55c\ub2e4. \ub450 \uc0ac\ub78c\uc758 \ub9cc\ub0a8\uc740 \uadf8\ub4e4\ub9cc\uc758 \ud798\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uc815\ubcf4\ub97c \uc804\ud558\uace0 \uc790\ub9ac\ub97c \ub9c8\ub828\ud558\ub294 \uc5b4\ub978\ub4e4\uc774 \ud544\uc694\ud588\ub2e4. \ube44\ubc00\uc744 \uc9c0\ud0a4\ub294 \ub3c4\uc6c0\uc774 \uc788\ub294 \ub3d9\uc2dc\uc5d0, \uadf8 \ube44\ubc00 \ub54c\ubb38\uc5d0 \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc774 \ud589\ub3d9\uc744 \uc798\ubabb \ud574\uc11d\ud560 \uc5ec\uc9c0\ub3c4 \ucee4\uc9c4\ub2e4. \ud2f0\ubcfc\ud2b8\uc640\uc758 \uac08\ub4f1\uc5d0\uc11c \ub85c\ubbf8\uc624\uc758 \ud0dc\ub3c4\ub294 \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uc774\uc0c1\ud558\uac8c \ubcf4\uc778\ub2e4. \uadf8\ub294 \uc774\ubbf8 \uc904\ub9ac\uc5e3\uacfc \uacb0\ud63c\ud588\uae30 \ub54c\ubb38\uc5d0 \uad00\uacc4\ub97c \ub2ec\ub9ac \uc0dd\uac01\ud558\uc9c0\ub9cc \uadf8 \uc774\uc720\ub97c \ubaa8\ub450\uc5d0\uac8c \uc124\uba85\ud560 \uc218 \uc5c6\ub2e4. \uba38\ud050\uc1fc\uac00 \uc2f8\uc6c0\uc5d0 \ud718\ub9d0\ub824 \uc8fd\uace0, \ub85c\ubbf8\uc624\ub294 \ud2f0\ubcfc\ud2b8\ub97c \uc8fd\uc778\ub2e4. \uc0ac\ub791\uc744 \ud1b5\ud574 \ud53c\ud558\ub824\ub358 \ud3ed\ub825\uc774 \ub354 \ud06c\uac8c \ub3cc\uc544\uc628\ub2e4. \uadf8 \uacb0\uacfc \ub85c\ubbf8\uc624\ub294 \ucd94\ubc29\ub41c\ub2e4. \ube44\ubc00 \uacb0\ud63c\uc774 \uc774\ub8e8\uc5b4\uc84c\ub2e4\uace0 \uc548\uc804\ud55c \ubbf8\ub798\uac00 \uc0dd\uae34 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uac19\uc740 \ud589\ub3d9\ub3c4 \ub204\uac00 \ubb34\uc5c7\uc744 \uc54c\uace0 \uc788\ub294\uc9c0\uc5d0 \ub530\ub77c \ub2e4\ub978 \uc758\ubbf8\uac00 \ub41c\ub2e4. \uc791\ud488\uc758 \uae34\uc7a5\uc740 \uac15\ud55c \uac10\uc815\uc5d0\uc11c\ub9cc \ub098\uc624\uc9c0 \uc54a\uace0 \uc11c\ub85c \ub2e4\ub974\uac8c \ub098\ub204\uc5b4 \uac00\uc9c4 \uc815\ubcf4\uc5d0\uc11c\ub3c4 \ub098\uc628\ub2e4. \uc904\ub9ac\uc5e3\uc758 \uac00\uc871\uc740 \ud30c\ub9ac\uc2a4\uc640\uc758 \uacb0\ud63c\uc744 \ucd94\uc9c4\ud55c\ub2e4. \uadf8\ub140\ub294 \uc774\ubbf8 \uacb0\ud63c\ud55c \uc0ac\uc2e4\uc744 \ub4dc\ub7ec\ub0b4\uae30 \uc5b4\ub835\uace0 \uac00\uc871\uc758 \uc694\uad6c\ub97c \ubc1b\uc544\ub4e4\uc77c \uc218\ub3c4 \uc5c6\ub2e4. \uac89\uc73c\ub85c \ubcf4\uc774\ub294 \uc21c\uc885\uacfc \uc2e4\uc81c \ub9c8\uc74c \uc0ac\uc774\uc758 \uac70\ub9ac\uac00 \ucee4\uc9c4\ub2e4. \uc9d1\uc774 \uac00\uc7a5 \uac00\uae4c\uc6b4 \uc7a5\uc18c\uc774\uba74\uc11c \uac00\uc7a5 \ub9d0\ud558\uae30 \uc5b4\ub824\uc6b4 \uacf5\uac04\uc774 \ub41c\ub2e4. \ub85c\ub7f0\uc2a4 \uc218\uc0ac\ub294 \uc8fd\uc740 \uac83\ucc98\ub7fc \ubcf4\uc774\uac8c \ud55c \ub4a4 \ub2e4\uc2dc \ub85c\ubbf8\uc624\uc640 \ub9cc\ub098\uac8c \ud560 \uacc4\ud68d\uc744 \uc138\uc6b4\ub2e4. \uc5ec\uae30\uc5d0\ub294 \uc815\ud655\ud55c \uc2dc\uac04\uacfc \uc804\ub2ec\uc774 \ud544\uc694\ud558\ub2e4. \uacc4\ud68d\uc758 \ub0b4\uc6a9\uc744 \uc54c\uace0 \uc788\ub294 \uc0ac\ub78c\uacfc \uc2dc\uc2e0\ucc98\ub7fc \ubcf4\uc774\ub294 \ubaa8\uc2b5\ub9cc \ubcf4\uac8c \ub420 \uc0ac\ub78c\uc758 \ucc28\uc774\uac00 \uacb0\uc815\uc801\uc774\ub2e4. \ud76c\ub9dd\uc740 \uc810\uc810 \ub354 \uc881\uc740 \uc870\uac74 \uc704\uc5d0 \ub193\uc778\ub2e4. \ud3b8\uc9c0\uac00 \ub2ff\uc9c0 \uc54a\ub294 \uc77c\uc740 \uc624\ub298\uc758 \ub3c5\uc790\uc5d0\uac8c \uc6b0\uc5f0\ud55c \uc0ac\uace0\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc778\ubb3c\ub4e4\uc740 \ucda9\ubd84\ud55c \uc815\ubcf4\ub97c \uacf5\uc720\ud558\uc9c0 \ubabb\ud55c \ucc44 \ube60\ub974\uac8c \uacb0\uc815\ud55c\ub2e4. \uad00\uac1d\uc740 \uc774 \uac04\uaca9\uc744 \ubbf8\ub9ac \uc54c\uae30\uc5d0 \ub9c8\uc9c0\ub9c9 \uc7a5\uba74\uc744 \ub2e8\uc21c\ud55c \ubc18\uc804\ubcf4\ub2e4 \ub9c9\uc744 \uc218 \uc788\uc5c8\ub358 \ube44\uadf9\uc73c\ub85c \uacbd\ud5d8\ud55c\ub2e4. \ub85c\ubbf8\uc624\uc5d0\uac8c \uacc4\ud68d\uc744 \uc54c\ub824\uc57c \ud560 \ud3b8\uc9c0\ub294 \uc804\ub2ec\ub418\uc9c0 \ubabb\ud55c\ub2e4. \uadf8\ub294 \uc904\ub9ac\uc5e3\uc774 \uc8fd\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc744 \ub4e3\uace0 \ub3cc\uc544\uc628\ub2e4. \ub3c5\uc790\ub294 \uc2e4\uc81c \uc0ac\uc815\uc744 \uc54c\uc9c0\ub9cc \uc778\ubb3c\uc740 \ubaa8\ub978\ub2e4. \ubc14\ub85c \uadf8 \ucc28\uc774 \ub54c\ubb38\uc5d0 \ub2e4\uc74c \uc7a5\uba74\uc744 \uc9c0\ucf1c\ubcf4\ub294 \uc77c\uc774 \ub354\uc6b1 \uace0\ud1b5\uc2a4\ub7ec\uc6cc\uc9c4\ub2e4. \ubb34\ub364\uc5d0\uc11c \ub85c\ubbf8\uc624\ub294 \uc904\ub9ac\uc5e3\uc774 \uae68\uc5b4\ub098\uae30 \uc804\uc5d0 \uc8fd\uace0, \ub4a4\uc774\uc5b4 \uae68\uc5b4\ub09c \uc904\ub9ac\uc5e3\ub3c4 \ubaa9\uc228\uc744 \uc783\ub294\ub2e4. \uc57d\uc18d\ud55c \uc7ac\ud68c\uc640 \uc2e4\uc81c \ub3c4\ucc29\uc758 \uc2dc\uac04\uc774 \uc5b4\uae0b\ub09c\ub2e4. \ube44\uadf9\uc740 \ub204\uad70\uac00\uc758 \uc545\uc758 \ud558\ub098\uac00 \uacc4\ud68d\ub300\ub85c \uc131\uacf5\ud574\uc11c\ub9cc \uc77c\uc5b4\ub09c \uac83\uc774 \uc544\ub2c8\ub2e4. \uc11c\ub85c\ub97c \uad6c\ud558\ub824\ub358 \ubc29\uc548\ub3c4 \uc804\ub2ec\uc774 \ubb34\ub108\uc9c0\uba74 \ub3cc\uc774\ud0ac \uc218 \uc5c6\ub294 \uacb0\uacfc\uac00 \ub41c\ub2e4. \uc218\uc0ac\uc640 \uc720\ubaa8\ub294 \uc911\uc694\ud55c \uc870\ub825\uc790\uc9c0\ub9cc \ubaa8\ub4e0 \uc0c1\ud669\uc744 \ud1b5\uc81c\ud558\uc9c0\ub294 \ubabb\ud55c\ub2e4. \uac01\uc790\uc758 \ud310\ub2e8\uc774 \ubc14\ub00c\uac70\ub098 \uacc4\ud68d\uc774 \uc5b4\uae0b\ub098\uba74\uc11c \ub450 \uc0ac\ub78c\uc740 \ub354 \uace0\ub9bd\ub41c\ub2e4. \uadf8\ub798\uc11c \uc791\ud488\uc744 \uc544\ubb34 \uc5b4\ub978\ub3c4 \ub3c4\uc640\uc8fc\uc9c0 \uc54a\uc740 \uc0ac\ub791 \uc774\uc57c\uae30\ub85c\ub9cc \uae30\uc5b5\ud558\uba74 \uc2e4\uc81c \uad00\uacc4\uc758 \ubcf5\uc7a1\ud568\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \ub3c4\uc6c0\uc758 \uc758\ub3c4\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8 \ub3c4\uc6c0\uc774 \ucda9\ubd84\ud558\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub974\ub2e4. \uac1c\uc778\uc801\uc778 \uc911\uc7ac\ub9cc\uc73c\ub85c \uac00\ubb38\uc758 \uad8c\ub825\uacfc \ub3c4\uc2dc\uc758 \ud3ed\ub825\uc744 \ud574\uacb0\ud558\uae30 \uc5b4\ub824\uc6e0\ub2e4. \ub450 \uc0ac\ub78c\uc758 \uc120\ud0dd\uc744 \uc874\uc911\ud560 \uacf5\uac1c\uc801\uc778 \uae38\uc774 \uc881\uc558\ub2e4\ub294 \ubb38\uc81c\ub3c4 \ub0a8\ub294\ub2e4. \ube44\ubc00\uc774 \ubcf4\ud638\ub9c9\uc774 \ub418\ub294 \ub3d9\uc548 \ub3d9\uc2dc\uc5d0 \uc704\ud5d8\uc758 \uc870\uac74\uc774 \ub41c \uac83\uc774\ub2e4. \ub9c8\uc9c0\ub9c9\uc5d0 \ub450 \uac00\ubb38\uc740 \uc790\ub140\ub4e4\uc758 \uc8fd\uc74c \uc55e\uc5d0\uc11c \ub300\ub9bd\uc744 \ub3cc\uc544\ubcf8\ub2e4. \uadf8\ub7ec\ub098 \ud654\ud574\uac00 \uc774\ub8e8\uc5b4\uc838\ub3c4 \ub450 \uc0ac\ub78c\uc758 \uc0b6\uc774 \ud68c\ubcf5\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc624\ub798\ub41c \uc99d\uc624\uc758 \ube44\uc6a9\uc774 \ub204\uac00 \uac10\ub2f9\ud55c \uc190\uc2e4\uc778\uc9c0 \ubd84\uba85\ud574\uc9c0\ub294 \uacb0\ub9d0\uc774\ub2e4. \ub3c4\uc2dc\uc758 \uc9c8\uc11c\ub3c4 \uadf8 \ube44\uadf9\uc744 \uc678\uba74\ud560 \uc218 \uc5c6\ub2e4. \u300e\ub85c\ubbf8\uc624\uc640 \uc904\ub9ac\uc5e3\u300f\uc740 \uc0ac\ub791\uc774 \uac15\ud588\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc624\ub798 \uc77d\ud788\ub294 \uc791\ud488\uc774 \uc544\ub2c8\ub2e4. \uc774\ub984\uacfc \uad8c\ub825, \ub3c4\uc6c0\uacfc \uc815\ubcf4, \uc2dc\uac04\uc758 \uc5b4\uae0b\ub0a8\uc774 \ud568\uaed8 \uc778\uac04\uc758 \uc6b4\uba85\uc744 \ub9cc\ub4e0\ub2e4. \ub450 \uc0ac\ub78c\uc758 \uc5f4\uc815\uc744 \ub530\ub77c \uc77d\uc73c\uba74\uc11c \uadf8\ub4e4\uc744 \ub458\ub7ec\uc2fc \uad00\uacc4\uae4c\uc9c0 \ubcf4\uba74 \uc775\uc219\ud55c \ube44\uadf9\uc774 \ub354 \ub113\uace0 \uad6c\uccb4\uc801\uc778 \uc774\uc57c\uae30\ub85c \ub2e4\uac00\uc628\ub2e4."}, {"id": "rostam-sohrab-token-and-recognition", "title": "\ub85c\uc2a4\ud0d0\uacfc \uc18c\ud750\ub77c\ube0c \u2014 \uc11c\ub85c\ub97c \uc54c\uc544\ubcf4\uc9c0 \ubabb\ud55c \ubd80\uc790\uc758 \uacb0\ud22c", "summary": "\uc0e4\ub098\uba54\uc758 \ud55c \uc5d0\ud53c\uc18c\ub4dc\uc5d0\uc11c \uc544\ubc84\uc9c0\ub97c \ucc3e\ub294 \uc544\ub4e4\uacfc \ub108\ubb34 \ub2a6\uc740 \uc778\uc9c0\uc758 \ube44\uadf9\uc744 \ub530\ub77c\uac11\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/rostam-sohrab-token-and-recognition/index.html", "image": "../media/rostam-sohrab-token-and-recognition.png", "alt": "\ud3c9\uc6d0\uc5d0\uc11c \ub9c8\uc8fc \uc120 \ub450 \ud398\ub974\uc2dc\uc544 \uc804\uc0ac\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ub85c\uc2a4\ud0d0\uacfc \uc18c\ud750\ub77c\ube0c \u2014 \uc11c\ub85c\ub97c \uc54c\uc544\ubcf4\uc9c0 \ubabb\ud55c \ubd80\uc790\uc758 \uacb0\ud22c \uc5ed\uc0ac\uac00 \uc544\ub2cc \uc11c\uc0ac\uc2dc\ub97c \uc77d\ub294 \uc790\ub9ac\uc5d0\uc11c \uc2dc\uc791\ud558\ub294 \uc5ed\uc0ac\uc640 \uc791\ud488 \uc77d\uae30 \uc0e4\ub098\uba54\uc758 \ud55c \uc5d0\ud53c\uc18c\ub4dc\uc5d0\uc11c \uc544\ubc84\uc9c0\ub97c \ucc3e\ub294 \uc544\ub4e4\uacfc \ub108\ubb34 \ub2a6\uc740 \uc778\uc9c0\uc758 \ube44\uadf9\uc744 \ub530\ub77c\uac11\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \ud398\ub974\uc2dc\uc544\uc758 \ub300\uc11c\uc0ac\uc2dc \u300e\uc0e4\ub098\uba54\u300f\uc5d0\ub294 \uc655\uacfc \uc601\uc6c5\uc758 \uc774\uc57c\uae30\uac00 \uae38\uac8c \uc774\uc5b4\uc9c4\ub2e4. \uadf8 \uc804\uccb4\ub97c \uba87 \uc7a5\uba74\uc73c\ub85c \uc124\uba85\ud558\uae30\ubcf4\ub2e4, \uc5ec\uae30\uc11c\ub294 \ub85c\uc2a4\ud0d0\uacfc \uc18c\ud750\ub77c\ube0c\uc758 \ube44\uadf9\uc5d0 \uc9d1\uc911\ud55c\ub2e4. \uc544\ubc84\uc9c0\ub97c \ucc3e\ub294 \uc544\ub4e4\uacfc \uc0c1\ub300\uc758 \uc815\uccb4\ub97c \uc54c\uc9c0 \ubabb\ud55c \uc544\ubc84\uc9c0\uac00 \uc804\uc7a5\uc5d0\uc11c \ub9cc\ub098\ub294 \uc774\uc57c\uae30\ub2e4. \ud798\uc774 \uac15\ud558\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc774\ub4e4\uc744 \uad6c\ud558\uc9c0 \ubabb\ud55c\ub2e4. \ud53c\ub974\ub2e4\uc6b0\uc2dc\uc758 \u300e\uc0e4\ub098\uba54\u300f\ub294 \uc2e0\ud654\uc801 \uae30\uc6d0\uacfc \uc804\uc124\uc801\uc778 \uc655\uc870, \uc5ed\uc0ac\uc640 \uc5f0\uacb0\ub418\ub294 \uc774\uc57c\uae30\ub97c \ud568\uaed8 \ud488\uc740 \uc791\ud488\uc774\ub2e4. \ub85c\uc2a4\ud0d0\uc758 \ud65c\uc57d\uc744 \uc2e4\uc81c \uc804\uc7c1\uc758 \uc0ac\uc2e4 \uae30\ub85d\ucc98\ub7fc \uc77d\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc624\ub79c \uae30\uc5b5\uacfc \uc774\uc0c1, \ub450\ub824\uc6c0\uc774 \uc2dc\uc758 \ud615\ud0dc\ub85c \uc870\uc9c1\ub41c \uc138\uacc4\ub2e4. \uc774 \uae00\uc740 \uadf8\uc911 \ud55c \uc5d0\ud53c\uc18c\ub4dc\uc758 \uc778\ubb3c \uad00\uacc4\uc640 \uacb0\ub9d0\uc744 \ub530\ub77c\uac04\ub2e4. \ubc88\uc5ed\uacfc \uc7ac\ud654\uc5d0 \ub530\ub77c \ud45c\uae30\uc640 \uc138\ubd80 \ud45c\ud604\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ub85c\uc2a4\ud0d0\uc744 \ub8e8\uc2a4\ud15c\uc73c\ub85c \uc801\uc740 \uc624\ub798\ub41c \uc601\uc5b4 \ubc88\uc5ed\ub3c4 \uac19\uc740 \uc601\uc6c5\uc744 \uac00\ub9ac\ud0a8\ub2e4. \uc774\ub984\uc758 \ucc28\uc774 \ub54c\ubb38\uc5d0 \uc11c\ub85c \ub2e4\ub978 \uc778\ubb3c\ub85c \uc624\ud574\ud558\uc9c0 \uc54a\uc73c\uba74 \uc88b\ub2e4. \ub85c\uc2a4\ud0d0\uacfc \ud0c0\ud750\ubbf8\ub124\uc758 \ub9cc\ub0a8 \ub4a4\uc5d0 \uc18c\ud750\ub77c\ube0c\uac00 \ud0dc\uc5b4\ub09c\ub2e4. \uc544\ub4e4\uc740 \uc544\ubc84\uc9c0 \uacc1\uc5d0\uc11c \ud568\uaed8 \uc790\ub77c\uc9c0 \uc54a\ub294\ub2e4. \uc544\ubc84\uc9c0\uc758 \uc774\ub984\uacfc \uadf8\ub97c \ud655\uc778\ud560 \ud45c\uc9c0\ub294 \ub0a8\uc544 \uc788\uc9c0\ub9cc, \uc77c\uc0c1\uc5d0\uc11c \uc5bc\uad74\uacfc \ubaa9\uc18c\ub9ac\ub97c \uc775\ud790 \uc2dc\uac04\uc740 \uc5c6\uc5c8\ub2e4. \uc774 \uac04\uaca9\uc774 \ub4a4\uc758 \ube44\uadf9\uc744 \uc900\ube44\ud55c\ub2e4. \ubd80\uc790 \uad00\uacc4\ub294 \ub3c5\uc790\uc5d0\uac8c \uc54c\ub824\uc838 \uc788\uc73c\ub098 \ub2f9\uc0ac\uc790\ub4e4\uc774 \uac19\uc740 \uc815\ubcf4\ub97c \ucda9\ubd84\ud788 \uacf5\uc720\ud558\uc9c0 \ubabb\ud55c\ub2e4. \uc774\uc57c\uae30\ub97c \uc77d\ub294 \uc0ac\ub78c\uc740 \ub9cc\ub0a8\uc774 \uac00\uae4c\uc6cc\uc9c8\uc218\ub85d \uae30\ubed0\ud558\uae30\ubcf4\ub2e4 \ubd88\uc548\ud574\uc9c4\ub2e4. \ub9cc\ub0a0 \uc218 \uc788\ub2e4\ub294 \uac00\ub2a5\uc131\uacfc \uc81c\ub300\ub85c \uc54c\uc544\ubcf4\uc9c0 \ubabb\ud560 \uc218 \uc788\ub2e4\ub294 \uc704\ud5d8\uc774 \ud568\uaed8 \ucee4\uc9c0\uae30 \ub54c\ubb38\uc774\ub2e4. \uc18c\ud750\ub77c\ube0c\ub294 \uc80a\uace0 \uac15\ud55c \uc804\uc0ac\ub85c \uc131\uc7a5\ud55c\ub2e4. \uadf8\ub294 \uc774\ub984\ub09c \uc544\ubc84\uc9c0\ub97c \ucc3e\uc73c\ub824 \ud558\uc9c0\ub9cc \uadf8 \ubc14\ub78c\uc740 \uc801\ub300\ud558\ub294 \uc138\ub825\ub4e4\uc758 \uc804\uc7c1\uacfc \uc5bd\ud78c\ub2e4. \uac00\uc871\uc744 \ucc3e\ub294 \uac1c\uc778\uc758 \ubaa9\uc801\uc774 \uad70\ub300\uc640 \uc655\uc758 \uc774\ud574\uad00\uacc4 \uc18d\uc5d0 \ub4e4\uc5b4\uac04 \uac83\uc774\ub2e4. \uadf8\uc5d0\uac8c \ud544\uc694\ud55c \uac83\uc740 \uc6a9\uae30\ub9cc\uc774 \uc544\ub2c8\ub77c \uc815\ud655\ud55c \uc815\ubcf4\ub2e4. \uadf8\ub7ec\ub098 \uc804\uc7a5\uc5d0\uc11c\ub294 \uc0c1\ub300\uc758 \uc774\ub984\uacfc \uc704\uce58\ub97c \uc54c\ub824 \uc8fc\ub294 \ub9d0\ub3c4 \uc804\ub7b5\uc774 \ub41c\ub2e4. \ub204\uad70\uac00 \uc0ac\uc2e4\uc744 \uac10\ucd94\uac70\ub098 \ub2e4\ub978 \uc124\uba85\uc744 \ud558\uba74 \uac1c\uc778\uc774 \uac00\uc9c4 \ud798\ub9cc\uc73c\ub85c \uadf8 \uc7a5\ubcbd\uc744 \ub118\uae30 \uc5b4\ub835\ub2e4. \uc18c\ud750\ub77c\ube0c\uc758 \uac15\ud568\uacfc \ucde8\uc57d\ud568\uc740 \ubc14\ub85c \uadf8 \uc9c0\uc810\uc5d0\uc11c \uacb9\uce5c\ub2e4. \ub450 \uc0ac\ub78c\uc774 \ub9c8\uc8fc\ud560 \ub54c \ub3c5\uc790\ub294 \uc774\ub4e4\uc774 \ubd80\uc790\ub77c\ub294 \uc0ac\uc2e4\uc744 \uc54c\uace0 \uc788\ub2e4. \uadf8\ub798\uc11c \ubb34\uc608\ub97c \uaca8\ub8e8\ub294 \uc7a5\uba74\uc740 \ub204\uac00 \uc774\uae38\uc9c0 \uad81\uae08\ud55c \uacbd\uae30\uc640 \ub2e4\ub974\ub2e4. \uc5b4\ub290 \ucabd\uc774 \uc774\uae30\ub354\ub77c\ub3c4 \ub054\ucc0d\ud55c \uacb0\uacfc\uac00 \uc0dd\uae38 \uc218 \uc788\uc74c\uc744 \ubbf8\ub9ac \uc54c\uace0 \ubcf4\uae30 \ub54c\ubb38\uc774\ub2e4. \uc0c1\ub300\ub97c \uc54c\uc544\ubcf4\ub824\ub294 \uc9c8\ubb38\uacfc \uac10\ucd94\uc5b4\uc9c4 \uc774\ub984\uc740 \uc804\ud22c\uc758 \uc77c\ubd80\uac00 \ub41c\ub2e4. \uc9c4\uc2e4\uc740 \uc5b4\ub518\uac00\uc5d0 \uc874\uc7ac\ud558\uc9c0\ub9cc \ud544\uc694\ud55c \uc0ac\ub78c\uc5d0\uac8c \uc81c\ub54c \uc804\ub2ec\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc774 \uc11c\uc0ac\uc5d0\uc11c \ubb34\uc9c0\ub294 \ub2e8\uc21c\ud788 \uba38\ub9ac\uac00 \ub098\uc058\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uacbd\uc7c1\uacfc \ubd88\uc2e0\uc774 \uc815\ubcf4\ub97c \uac00\ub85c\ub9c9\ub294 \uc0c1\ud669\uc744 \ub73b\ud55c\ub2e4. \uc18c\ud750\ub77c\ube0c\ub97c \uae30\ub2e4\ub9ac\ub294 \uc5b4\uba38\ub2c8\uc758 \uc704\uce58\ub3c4 \uc78a\uc9c0 \ub9d0\uc790. \uc804\uc7a5\uc5d0 \uc9c1\uc811 \ub098\uc11c\uc9c0 \uc54a\ub294 \uc0ac\ub78c\ub3c4 \uc804\uc7c1\uc758 \uacb0\uacfc\ub97c \uac10\ub2f9\ud55c\ub2e4. \uc601\uc6c5\uc758 \uacb0\ud22c\uc5d0 \uc2dc\uc120\uc744 \ubaa8\uc73c\ub294 \ub3d9\uc548 \uadf8 \ub4a4\uc5d0 \ub0a8\uaca8\uc9c4 \uac00\uc871\uc758 \uc2dc\uac04\uc774 \uc0ac\ub77c\uc838\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc8fd\uc74c\uc758 \uc18c\uc2dd\uc740 \ubb34\ub300 \ubc16\uc758 \uad00\uacc4\uae4c\uc9c0 \ubc14\uafb8\uba70 \ube44\uadf9\uc758 \ubc94\uc704\ub97c \ub113\ud78c\ub2e4. \uc774\uc57c\uae30\uc758 \ud45c\uc9c0\ub294 \ub204\uad6c\ub098 \uc989\uc2dc \ub73b\uc744 \uc54c\uc544\ubcfc \uc218 \uc788\ub294 \uc2e0\ubd84\uc99d\uacfc \ub2e4\ub974\ub2e4. \uadf8\uac83\uc744 \uae30\uc5b5\ud558\uace0 \uad00\uacc4\ub97c \uc544\ub294 \uc0ac\ub78c\uc774 \uc801\uc808\ud55c \ub54c\uc5d0 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ubb3c\uac74 \uc790\uccb4\uc5d0 \uc9c4\uc2e4\uc774 \ub4e4\uc5b4 \uc788\uc5b4\ub3c4 \ud574\uc11d\uacfc \uc804\ub2ec\uc774 \uc5c6\uc73c\uba74 \uae30\ub2a5\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc774 \uc810\uc5d0\uc11c \ud314\uc5d0 \uc9c0\ub2cc \uc791\uc740 \ud45c\uc9c0\ub294 \uac70\ub300\ud55c \uad70\ub300\ubcf4\ub2e4 \uacb0\uc815\uc801\uc778 \uc758\ubbf8\ub97c \uac16\ub294\ub2e4. \uc544\ubc84\uc9c0\uc758 \uc774\ub984\uc744 \ucc3e\ub294 \uc5ec\uc815\uc774 \uadf8 \uc544\ubc84\uc9c0\uc758 \uc190\uc5d0\uc11c \ub05d\ub09c\ub2e4\ub294 \uc5ed\uc804\uc740 \uadf8\ub798\uc11c \uc624\ub798 \uae30\uc5b5\ub41c\ub2e4. \ucc98\uc74c \ub9de\ubd99\uc5c8\uc744 \ub54c \uc18c\ud750\ub77c\ube0c\ub294 \ub85c\uc2a4\ud0d0\uc744 \uc81c\uc555\ud560 \uae30\ud68c\ub97c \uc5bb\ub294\ub2e4. \uadf8\ub7ec\ub098 \uc0c1\ub300\uac00 \ub0b4\uc138\uc6b0\ub294 \ub9d0\uacfc \uaddc\uce59\uc744 \ubc1b\uc544\ub4e4\uc774\uba70 \uce58\uba85\uc801\uc778 \uacb0\ub9d0\uc744 \ub2a6\ucd98\ub2e4. \uc80a\uc740 \uc804\uc0ac\ub294 \ud798\uc5d0\uc11c \uc55e\uc11c\uba74\uc11c\ub3c4 \uacbd\ud5d8\uacfc \ub9d0\uc758 \uc791\uc6a9\uc5d0\uc11c\ub294 \ub2e4\ub978 \uc704\uce58\uc5d0 \ub193\uc5ec \uc788\ub2e4. \ub2e4\uc2dc \uc774\uc5b4\uc9c4 \uc2f8\uc6c0\uc5d0\uc11c\ub294 \ub85c\uc2a4\ud0d0\uc774 \uc18c\ud750\ub77c\ube0c\uc5d0\uac8c \uce58\uba85\uc0c1\uc744 \uc785\ud78c\ub2e4. \uc774 \uc7a5\uba74\uc758 \ube44\uadf9\uc740 \uac15\uc790\uac00 \uc57d\uc790\ub97c \uc774\uacbc\ub2e4\ub294 \ub2e8\uc21c\ud55c \uacb0\uacfc\uc5d0 \uc788\uc9c0 \uc54a\ub2e4. \uc790\uc2e0\uc774 \uc9c0\ucf1c\uc57c \ud560 \uad00\uacc4\ub97c \ubaa8\ub974\ub294 \ucc44, \uc2b9\ubd80\uc5d0\uc11c \uc774\uae30\uae30 \uc704\ud574 \uac00\uc9c4 \ub2a5\ub825\uc744 \uc0ac\uc6a9\ud588\ub2e4\ub294 \ub370 \uc788\ub2e4. \uc18c\ud750\ub77c\ube0c\uc758 \ub9d0\uacfc \ubab8\uc5d0 \uc9c0\ub2cc \ud45c\uc9c0\ub97c \ud1b5\ud574 \ub85c\uc2a4\ud0d0\uc740 \uc0c1\ub300\uac00 \uc790\uae30 \uc544\ub4e4\uc784\uc744 \uae68\ub2eb\ub294\ub2e4. \ub450 \uc0ac\ub78c\uc758 \uad00\uacc4\ub97c \uc99d\uba85\ud560 \ubb3c\uac74\uc740 \ucc98\uc74c\ubd80\ud130 \uc758\ubbf8\uac00 \uc788\uc5c8\uc9c0\ub9cc, \uadf8\uac83\uc774 \uc77d\ud788\ub294 \uc2dc\uc810\uc740 \ub3cc\uc774\ud0ac \uc218 \uc5c6\ub294 \ub4a4\ub2e4. \uc9c4\uc2e4\uc744 \uc544\ub294 \uac83\uacfc \uc9c4\uc2e4\uc744 \uc81c\ub54c \uc544\ub294 \uac83\uc740 \uac19\uc9c0 \uc54a\ub2e4. \ub85c\uc2a4\ud0d0\uc758 \uc2ac\ud514\uc740 \uc601\uc6c5\uc758 \uba85\uc131\uc744 \ubb34\ub825\ud558\uac8c \ub9cc\ub4e0\ub2e4. \uc774\ub984\ub09c \uc804\uc0ac\uac00 \ub418\uc5b4 \uc218\ub9ce\uc740 \uc0c1\ub300\ub97c \uc774\uaca8\ub3c4 \uc774 \ud55c \ubc88\uc758 \ud589\ub3d9\uc744 \ucde8\uc18c\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc11c\uc0ac\uc2dc\ub294 \uc601\uc6c5\uc744 \ucc2c\uc591\ud558\ub294 \ub370\uc11c \uba48\ucd94\uc9c0 \uc54a\uace0 \uadf8 \ud798\uc774 \uacaa\ub294 \ud55c\uacc4\uc640 \ucc45\uc784\ub3c4 \ub4dc\ub7ec\ub0b8\ub2e4. \uc774 \uc5d0\ud53c\uc18c\ub4dc\ub97c \uc6b4\uba85\uc774 \ub098\ube74\ub2e4\ub294 \ub9d0\ub85c\ub9cc \ub9c8\ubb34\ub9ac\ud558\uba74 \uc778\ubb3c \uc8fc\ubcc0\uc758 \uc870\uac74\uc744 \ub193\uce5c\ub2e4. \uc774\ub984\uc744 \uc228\uae30\ub294 \uad00\ud589\uacfc \uc801\ub300\ud558\ub294 \uc9c4\uc601, \uc655\uacfc \uc9c0\ud718\uad00\uc758 \ubaa9\uc801\uc774 \uac00\uc871\uc758 \ub9cc\ub0a8\uc744 \ubc29\ud574\ud55c\ub2e4. \uac1c\uc778\uc801\uc778 \ube44\uadf9\uacfc \uc815\uce58\uc801\uc778 \uc138\uacc4\uac00 \uc11c\ub85c \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\ub2e4. \uc624\ub298 \uc77d\uc5b4\ub3c4 \uc774 \uc774\uc57c\uae30\uac00 \uc544\ud508 \uac83\uc740 \uc11c\ub85c\ub97c \uc0ac\ub791\ud560 \uac00\ub2a5\uc131\uc774 \uc788\uc5c8\ub358 \uc0ac\ub78c\ub4e4\uc774 \uc801\uc73c\ub85c \ub9cc\ub0ac\uae30 \ub54c\ubb38\uc774\ub2e4. \ud544\uc694\ud55c \ud45c\uc9c0\uc640 \ub9d0\uc740 \uc874\uc7ac\ud588\uc9c0\ub9cc \uc774\ud574\uc758 \uc21c\uac04\uc774 \ub2a6\uc5c8\ub2e4. \ub3c5\uc790\ub294 \uacb0\ub9d0\uc744 \uc54c\uace0 \ub2e4\uc2dc \uc77d\uc73c\uba70 \uc55e\uc120 \uc9c8\ubb38\uacfc \uce68\ubb35\uc758 \uc758\ubbf8\ub97c \uc0c8\ub86d\uac8c \ubc1c\uacac\ud560 \uc218 \uc788\ub2e4. \ub85c\uc2a4\ud0d0\uacfc \uc18c\ud750\ub77c\ube0c\ub294 \ud798\uc744 \uac16\ucd94\ub294 \uc77c\ub9cc\ud07c \uc0c1\ub300\uac00 \ub204\uad6c\uc778\uc9c0 \uc54c\uc544\ubcf4\ub294 \uc77c\uc774 \uc911\uc694\ud558\ub2e4\ub294 \uc9c8\ubb38\uc744 \ub0a8\uae34\ub2e4."}, {"id": "samothrace-nike-wind-and-prow", "title": "\uc0ac\ubaa8\ud2b8\ub77c\ucf00\uc758 \ub2c8\ucf00 \u2014 \uba38\ub9ac \uc5c6\ub294 \uc5ec\uc2e0\uc5d0\uac8c \ubc14\ub78c\uc774 \ubcf4\uc774\ub294 \uc774\uc720", "summary": "\uc637\uacfc \ub0a0\uac1c, \ubc30\uc758 \uc120\uc218\uc640 \ubc1c\uacac\uc758 \uc5ed\uc0ac\ub97c \ud1b5\ud574 \uc2b9\ub9ac\uc640 \ubc14\ub78c\uc744 \ud45c\ud604\ud55c \uc870\uac01\uc744 \ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/samothrace-nike-wind-and-prow/index.html", "image": "../media/samothrace-nike-wind-and-prow.jpg", "alt": "\ub0a0\uac1c\uc640 \uc637\uc758 \uc8fc\ub984\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc0ac\ubaa8\ud2b8\ub77c\ucf00\uc758 \ub2c8\ucf00 \uc5ed\uc0ac \ub3c4\ud310", "text": "\uc0ac\ubaa8\ud2b8\ub77c\ucf00\uc758 \ub2c8\ucf00 \u2014 \uba38\ub9ac \uc5c6\ub294 \uc5ec\uc2e0\uc5d0\uac8c \ubc14\ub78c\uc774 \ubcf4\uc774\ub294 \uc774\uc720 \uc2b9\ub9ac\uac00 \uc0ac\ub78c\uc758 \ubaa8\uc2b5\uc744 \uc5bb\ub2e4\uc5d0\uc11c \uc2dc\uc791\ud558\ub294 \uc5ed\uc0ac\uc640 \uc791\ud488 \uc77d\uae30 \uc637\uacfc \ub0a0\uac1c, \ubc30\uc758 \uc120\uc218\uc640 \ubc1c\uacac\uc758 \uc5ed\uc0ac\ub97c \ud1b5\ud574 \uc2b9\ub9ac\uc640 \ubc14\ub78c\uc744 \ud45c\ud604\ud55c \uc870\uac01\uc744 \ubd05\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \ub8e8\ube0c\ub974\uc758 \uacc4\ub2e8 \uc704\uc5d0\uc11c \ub0a0\uac1c \ub2ec\ub9b0 \uc870\uac01\uc744 \ub9cc\ub098\uba74, \uc5c6\ub294 \ubd80\ubd84\ubcf4\ub2e4 \ub2e4\uac00\uc624\ub294 \ud798\uc744 \uba3c\uc800 \ub290\ub084 \uc218 \uc788\ub2e4. \uc0ac\ubaa8\ud2b8\ub77c\ucf00\uc758 \ub2c8\ucf00\ub294 \uba38\ub9ac\uc640 \ud314\uc774 \uc628\uc804\ud788 \ub0a8\uc544 \uc788\uc9c0 \uc54a\uc9c0\ub9cc \ubab8\uacfc \uc637, \ub0a0\uac1c\ub85c \uc6c0\uc9c1\uc784\uc744 \uc804\ub2ec\ud55c\ub2e4. \uc774 \uc791\ud488\uc744 \uadf8\ub9ac\uc2a4\uc758 \uc774\uc57c\uae30\ub85c \uc77d\ub294 \uac83\uc740 \ud604\uc7ac\uc758 \uc804\uc2dc \uc7a5\uc18c\uc640 \ub9cc\ub4e4\uc5b4\uc9c4 \ubb38\ud654\uc758 \ub9e5\ub77d\uc744 \uad6c\ubd84\ud558\uae30 \uc704\ud574\uc11c\ub2e4. \ub2c8\ucf00\ub294 \uadf8\ub9ac\uc2a4 \uc2e0\ud654\uc5d0\uc11c \uc2b9\ub9ac\ub97c \uc758\uc778\ud654\ud55c \uc874\uc7ac\ub2e4. \uc2b9\ub9ac\ub77c\ub294 \ucd94\uc0c1\uc801\uc778 \uacb0\uacfc\uac00 \ub0a0\uac1c\ub97c \uac00\uc9c4 \ud615\uc0c1\uc73c\ub85c \ub098\ud0c0\ub098\uba74, \uadf8\uac83\uc740 \uc0ac\ub78c\uc5d0\uac8c \ucc3e\uc544\uc624\uac70\ub098 \uba38\ubb34\ub294 \ubb34\uc5c7\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uc2e0\ud654\uc758 \uc778\ubb3c\uc740 \uc7a5\uc2dd\ub9cc\uc774 \uc544\ub2c8\ub77c \uc778\uac04\uc774 \uacbd\ud5d8\ud558\ub294 \uc0ac\uac74\uc744 \ub208\uc5d0 \ubcf4\uc774\ub294 \ud615\ud0dc\ub85c \ubc14\uafb8\ub294 \ubc29\ubc95\uc774\uc5c8\ub2e4. \uc774 \uc870\uac01\uc740 \ud5ec\ub808\ub2c8\uc998 \uc2dc\ub300\uc758 \uc791\ud488\uc73c\ub85c \uc774\ud574\ub41c\ub2e4. \ub2e4\ub9cc \uc815\ud655\ud788 \uc5b4\ub290 \uc804\ud22c\ub97c \uae30\ub150\ud588\ub294\uc9c0, \uc0ac\ub77c\uc9c4 \ud314\uc774 \ubb34\uc5c7\uc744 \ub4e4\uc5c8\ub294\uc9c0\ub294 \ub0a8\uc740 \ubab8\ub9cc\uc73c\ub85c \ud655\uc815\ud558\uae30 \uc5b4\ub835\ub2e4. \ud2b9\uc815 \ud574\uc804\uc758 \uc774\ub984\uc744 \uc678\uc6b0\ub294 \uac83\ubcf4\ub2e4 \ud655\uc2e4\ud788 \ubcf4\uc774\ub294 \uc694\uc18c\uc640 \ud559\uc790\ub4e4\uc758 \uac00\uc124\uc744 \ub098\ub204\uc5b4 \ubcf4\ub294 \uc77c\uc774 \uba3c\uc800\ub2e4. \uc5ec\uc2e0 \uc544\ub798\uc758 \ubc1b\uce68\uc740 \ud3c9\ubc94\ud55c \ub124\ubaa8\ub09c \ub3cc\uc774 \uc544\ub2c8\ub77c \ubc30\uc758 \uc55e\ubd80\ubd84\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uc774 \uad6c\uc131\uc740 \ubc14\ub2e4\uc640 \ud574\uad70\uc758 \uc2b9\ub9ac\ub97c \uc5f0\uacb0\ud574\uc11c \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ubab8\uc758 \uc790\uc138\uc640 \ubc1b\uce68\uc744 \ub530\ub85c \ubcf4\uc9c0 \uc54a\uc544\uc57c \uc870\uac01\uc774 \ub9cc\ub4e4\uc5b4 \ub0b4\ub294 \uc7a5\uba74\uc774 \ub113\uc5b4\uc9c4\ub2e4. \ub545\uc5d0 \ub2e8\ub2e8\ud788 \uc11c \uc788\ub294 \uc778\ubb3c\uacfc \ubc30 \uc704\uc5d0 \ub098\ud0c0\ub09c \uc5ec\uc2e0\uc740 \ub2e4\ub974\uac8c \ubcf4\uc778\ub2e4. \ubc30\ub294 \uc774\ub3d9\uacfc \ud30c\ub3c4, \ubc14\ub78c\uc744 \uc554\uc2dc\ud55c\ub2e4. \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294 \ub3cc \ubc1b\uce68\ub3c4 \uad00\uac1d\uc758 \uacbd\ud5d8 \uc18d\uc5d0\uc11c\ub294 \ubc14\ub2e4\uc758 \uc77c\ubd80\uac00 \ub41c\ub2e4. \uc804\uc2dc\uc2e4\uc5d0\uc11c \ubc14\ub2e4\ub97c \uc9c1\uc811 \ubcf4\uc9c0 \ubabb\ud574\ub3c4 \ud574\uc0c1\uc758 \uac10\uac01\uc744 \uc0c1\uc0c1\ud558\uac8c \ud558\ub294 \uc7a5\uce58\ub2e4. \uac00\uc2b4\uacfc \ubc30\uc758 \uc637\uc740 \ubab8\uc5d0 \ubc00\ucc29\ub418\uc5b4 \uad74\uace1\uc744 \ub4dc\ub7ec\ub0b4\uace0, \ub2e4\ub978 \ubd80\ubd84\uc5d0\uc11c\ub294 \ub450\uaecd\uac8c \ubaa8\uc774\uac70\ub098 \ubc14\uae65\uc73c\ub85c \ud754\ub4e4\ub9b0\ub2e4. \uac19\uc740 \uc637\uac10\uc774 \uc5b4\ub5a4 \uacf3\uc5d0\uc11c\ub294 \ud53c\ubd80\ucc98\ub7fc \uc587\uace0 \ub2e4\ub978 \uacf3\uc5d0\uc11c\ub294 \ubb34\uac8c\ub97c \uac00\uc9c4 \ub369\uc5b4\ub9ac\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uc774 \ucc28\uc774\uac00 \uc870\uac01\uc744 \ud3c9\ud3c9\ud55c \ud45c\uba74\uc5d0\uc11c \ubc97\uc5b4\ub098\uac8c \ud55c\ub2e4. \uc637\uc758 \uc8fc\ub984\uc744 \ub2e8\uc21c\ud788 \uc815\uad50\ud55c \uc7a5\uc2dd\uc73c\ub85c \ubcf4\uba74 \uc911\uc694\ud55c \ud6a8\uacfc\ub97c \ub193\uce5c\ub2e4. \uc8fc\ub984\uc740 \ubc14\ub78c\uc774 \uc5b4\ub290 \ucabd\uc5d0\uc11c \uc624\ub294\uc9c0, \ubab8\uc774 \uc5b4\ub290 \ubc29\ud5a5\uc73c\ub85c \ud798\uc744 \ubc1b\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uacf5\uae30\ub97c \uc9c1\uc811 \uc870\uac01\ud560 \uc218 \uc5c6\uae30 \ub54c\ubb38\uc5d0 \uc870\uac01\uac00\ub294 \uacf5\uae30\uc5d0 \ubc18\uc751\ud558\ub294 \ubb3c\uc9c8\uc744 \ubcf4\uc5ec \uc900 \uc148\uc774\ub2e4. \ub0a0\uac1c\ub294 \uc778\ubb3c\uc744 \uc54c\uc544\ubcf4\uac8c \ud558\ub294 \ud45c\uc9c0\uc774\uba74\uc11c \uacf5\uac04\uc744 \ub113\ud788\ub294 \ud070 \ud615\ud0dc\ub2e4. \ubab8\uc5d0 \ubd99\uc5b4 \uc788\ub294 \ud314\ub2e4\ub9ac\uc640 \ub2ec\ub9ac \uc88c\uc6b0\ub85c \ud3bc\uccd0\uc838 \uc870\uac01\uc774 \ucc28\uc9c0\ud558\ub294 \ubc94\uc704\ub97c \ud655\uc7a5\ud55c\ub2e4. \uad00\uac1d\uc774 \ud55c\ucabd\uc73c\ub85c \uc6c0\uc9c1\uc774\uba74 \ubab8\uacfc \ub0a0\uac1c\uc758 \uacb9\uce68\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc0ac\uc9c4 \ud55c \uc7a5\uc740 \ud2b9\uc815\ud55c \uac01\ub3c4\ub97c \uace0\uc815\ud558\uc9c0\ub9cc \uc870\uac01\uc740 \uc5ec\ub7ec \ubc29\ud5a5\uc5d0\uc11c \uacbd\ud5d8\ud558\ub3c4\ub85d \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4. \uc815\uba74\uc758 \uac15\ud55c \uc778\uc0c1\ub9cc \ubcf4\uace0 \ub05d\ub0b4\uae30\ubcf4\ub2e4 \uc606\uba74\uc5d0\uc11c \uc637\uacfc \ub0a0\uac1c\uc758 \uae4a\uc774\ub97c \ube44\uad50\ud574 \ubcf4\uc790. \uc2e0\uccb4\uc758 \ubc29\ud5a5\uacfc \ubc14\ub78c\uc758 \ubc29\ud5a5\uc774 \uc644\uc804\ud788 \uac19\uc740 \uc120\uc73c\ub85c \uc815\ub9ac\ub418\uc9c0 \uc54a\ub294 \ub370\uc11c \uae34\uc7a5\uc774 \uc0dd\uae34\ub2e4. \uc870\uac01\uc758 \ud070 \ub369\uc5b4\ub9ac\uc640 \uc791\uc740 \uc8fc\ub984\uc744 \ubc88\uac08\uc544 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uba40\ub9ac\uc11c\ub294 \uc55e\uc73c\ub85c \ud5a5\ud558\ub294 \ud615\uc0c1\uacfc \ub0a0\uac1c\uc758 \ud3ed\uc774 \uba3c\uc800 \uc77d\ud788\uace0 \uac00\uae4c\uc774\uc11c\ub294 \uc637\uac10\uc758 \uc587\uace0 \ub450\uaebc\uc6b4 \ucc28\uc774\uac00 \ubcf4\uc778\ub2e4. \uc2dc\uc120\uc744 \uc62e\uae30\ub294 \ub3d9\uc548 \ud558\ub098\uc758 \ud798\ucc2c \uc7a5\uba74\uc774 \uc138\ubd80\uc801\uc778 \uc81c\uc791\uc758 \uc120\ud0dd\uc73c\ub85c \ub098\ub25c\ub2e4. \uac10\ub3d9\uacfc \uad00\ucc30\uc740 \uc11c\ub85c \ub2e4\ub978 \uac10\uc0c1\uc774 \uc544\ub2c8\ub77c \uc774\uc5b4\uc9c0\ub294 \uacfc\uc815\uc774\ub2e4. \uc2b9\ub9ac\ub97c \ud45c\ud604\ud55c \uc791\ud488\uc5d0\ub294 \uc2b9\ub9ac\ud55c \ucabd\uc774 \uae30\uc5b5\ud558\uace0 \uc2f6\uc5c8\ub358 \uc138\uacc4\uac00 \ub2f4\uae34\ub2e4. \uc5ec\uc2e0\uc758 \uc544\ub984\ub2e4\uc6c0\uc5d0 \uac10\ud0c4\ud558\uba74\uc11c\ub3c4 \ub204\uad6c\uc758 \uc2b9\ub9ac\uac00 \uae30\ub150\ub418\uc5c8\uace0 \ub204\uac00 \uadf8\uac83\uc744 \ubc14\ub77c\ubcf4\uc558\uc744\uc9c0 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \uc774\ub984\uc774 \uc804\ud574\uc9c0\uc9c0 \uc54a\ub294 \uad00\uac1d\uae4c\uc9c0 \ub5a0\uc62c\ub9ac\uba74 \uae30\ub150\ubb3c\uc758 \uc0ac\ud68c\uc801 \uc5ed\ud560\uc774 \ub354 \ub113\uac8c \ubcf4\uc778\ub2e4. \uc791\ud488\uc740 1863\ub144 \uc0ac\ubaa8\ud2b8\ub77c\ucf00\uc5d0\uc11c \ubc1c\uacac\ub418\uc5c8\uace0, \uc870\uac01\uacfc \ubc1b\uce68\uc744 \uc774\ud574\ud558\uace0 \ub2e4\uc2dc \uc870\ud569\ud558\ub294 \uc791\uc5c5\uc774 \uc774\uc5b4\uc84c\ub2e4. \uc6b0\ub9ac\uac00 \ubcf4\ub294 \ud615\uc0c1\uc740 \ub545\uc18d\uc5d0\uc11c \uc644\uc131\ub41c \ud55c \ub369\uc5b4\ub9ac\ub85c \ub098\uc628 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc5ec\ub7ec \uc870\uac01\uc758 \uc704\uce58\ub97c \ud310\ub2e8\ud558\uace0 \uc5f0\uacb0\ud55c \uc5f0\uad6c\uc640 \ubcf4\uc874\uc758 \uacb0\uacfc\uac00 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4. 19\uc138\uae30 \ubc1c\uad74\uacfc \uc720\ubb3c\uc758 \uc774\ub3d9\uc740 \uc720\ub7fd \ubc15\ubb3c\uad00\uc758 \uc218\uc9d1 \uc5ed\uc0ac\uc640\ub3c4 \uc5f0\uacb0\ub41c\ub2e4. \uc624\ub298 \ud504\ub791\uc2a4\uc758 \ubc15\ubb3c\uad00\uc5d0 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8\ub9ac\uc2a4\uc758 \uc131\uc18c\uc5d0\uc11c \ub9cc\ub4e4\uc5b4\uc9c0\uace0 \ubd09\ud5cc\ub418\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ud568\uaed8 \uae30\uc5b5\ud560 \ud544\uc694\uac00 \uc788\ub2e4. \ud604\uc7ac \uc8fc\uc18c\ub9cc\uc73c\ub85c \uc791\ud488\uc758 \ubb38\ud654\uc801 \uc18c\uc18d\uc744 \ubaa8\ub450 \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc624\ub798\ub41c \ubbf8\uc220\uc0ac \ucc45\uc5d0\ub294 \uc774 \uc870\uac01\uc758 \uc5f0\ub300\ub098 \uc190\uc5d0 \ub4e4\uc5c8\ub358 \ubb3c\uac74\uc744 \uc624\ub298\uacfc \ub2e4\ub974\uac8c \uc124\uba85\ud55c \uacbd\uc6b0\ub3c4 \uc788\ub2e4. \uadf8 \uc124\uba85\uc744 \uadf8\ub300\ub85c \ubc18\ubcf5\ud558\uba74 \uc5f0\uad6c\uc758 \ubcc0\ud654\ub97c \uc9c0\uc6b0\uac8c \ub41c\ub2e4. \ube44\uad50\ud560 \ub9cc\ud55c \ub3d9\uc804\uc774\ub098 \ub2e4\ub978 \uc870\uac01\uc774 \uc788\ub2e4\ub294 \uac83\uacfc \uadf8\uac83\uc774 \uc720\uc77c\ud55c \ubcf5\uc6d0\uc758 \uc815\ub2f5\uc774\ub77c\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uba38\ub9ac\uac00 \uc5c6\ub2e4\ub294 \uc774\uc720\ub85c \uc0c1\uc0c1 \uc18d \uc5bc\uad74\uc744 \uc815\ub2f5\ucc98\ub7fc \ub367\ubd99\uc77c \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ud604\uc7ac\uc758 \uac15\ub82c\ud55c \uc778\uc0c1\uc774 \uc6d0\ub798 \uad00\uac1d\uc758 \uacbd\ud5d8\uacfc \uc644\uc804\ud788 \uac19\uc9c0\ub294 \uc54a\ub2e4\ub294 \uc810\uc744 \uc778\uc815\ud558\uba74 \ub41c\ub2e4. \uc190\uc2e4\uc744 \uac10\ucd94\uc9c0 \uc54a\ub294 \ud0dc\ub3c4\ub294 \uc791\ud488\uc744 \ub35c \uc774\ud574\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc99d\uac70\uc758 \ubc94\uc704\ub97c \ub354 \uc815\ud655\ud788 \uc544\ub294 \ubc29\ubc95\uc774\ub2e4. \uacc4\ub2e8\uc744 \uc624\ub974\ub294 \uad00\uac1d\uc740 \uc870\uac01\uc744 \uc544\ub798\uc5d0\uc11c \uc704\ub85c \ubc14\ub77c\ubcf8\ub2e4. \ub192\uc774\uc640 \uc811\uadfc \ubc29\ud5a5\uc740 \uc5ec\uc2e0\uc774 \ub2e4\uac00\uc624\ub294 \ub4ef\ud55c \uacbd\ud5d8\uc744 \ub9cc\ub4e0\ub2e4. \uc774\ub7f0 \ud604\ub300\uc758 \uc804\uc2dc \uc5f0\ucd9c\ub3c4 \uc791\ud488\uc744 \uc77d\ub294 \ubc29\uc2dd\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4. \uc6d0\ub798 \uc131\uc18c\uc758 \uacf5\uac04\uacfc \uc624\ub298\uc758 \uacc4\ub2e8\uc744 \uac19\uc740 \uc7a5\uba74\uc73c\ub85c \uc0dd\uac01\ud558\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \ub2c8\ucf00\ub294 \uc644\ubcbd\ud788 \ubcf4\uc874\ub41c \ud615\uc0c1\ub9cc\uc774 \uac10\ub3d9\uc744 \uc900\ub2e4\ub294 \uc0dd\uac01\uc744 \ud754\ub4e0\ub2e4. \ub0a8\uc740 \uc637\uacfc \ubab8, \ubc1b\uce68\ub9cc\uc73c\ub85c\ub3c4 \ubc14\ub78c\uacfc \ub3c4\ucc29, \uc2b9\ub9ac\uc758 \uac10\uac01\uc774 \uc804\ub2ec\ub41c\ub2e4. \ubb34\uc5c7\uc774 \uc0ac\ub77c\uc84c\ub294\uc9c0\ub97c \uc544\ub294 \ub208\uacfc \ubb34\uc5c7\uc774 \uc5ec\uc804\ud788 \uc791\ub3d9\ud558\ub294\uc9c0\ub97c \ubcf4\ub294 \ub208\uc744 \ud568\uaed8 \uac00\uc9c8 \ub54c, \uc774 \uc870\uac01\uc740 \ub354 \ud48d\ubd80\ud574\uc9c4\ub2e4."}, {"id": "sampo-forging-plenty-and-fragments", "title": "\uc0bc\ud3ec \u2014 \ubc00\uac00\ub8e8\uc640 \uc18c\uae08, \ub3c8\uc744 \ub0b4\ub358 \ubcf4\ubb3c\uc740 \uc65c \uae68\uc84c\uc744\uae4c", "summary": "\uc0bc\ud3ec\uc758 \uc81c\uc791\uacfc \uc18c\uc720, \ud0c8\ucde8\uc640 \ud30c\uc190\uc744 \ud06c\ub85c\ud37c\ub4dc\uc758 \u300e\uce7c\ub808\ubc1c\ub77c\u300f \ubc88\uc5ed \uc81c10\u00b742\u00b743\ub178\ub798\uc5d0 \ub530\ub77c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc2e0\ud654\uc640 \ubbfc\uc18d", "categories": ["arts"], "url": "stories/sampo-forging-plenty-and-fragments/index.html", "image": "../media/sampo-forging-plenty-and-fragments.png", "alt": "\uc2e0\ube44\ud55c \uc0bc\ud3ec\uc640 \ubc00\uac00\ub8e8\u00b7\uc18c\uae08 \ub4f1\uc758 \ubb3c\ud488\uc744 \ub300\uc7a5\uac04\uc5d0\uc11c \uc0b4\ud53c\ub294 \ub300\uc7a5\uc7a5\uc774\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uc0bc\ud3ec \u2014 \ubc00\uac00\ub8e8\uc640 \uc18c\uae08, \ub3c8\uc744 \ub0b4\ub358 \ubcf4\ubb3c\uc740 \uc65c \uae68\uc84c\uc744\uae4c \u300e\uce7c\ub808\ubc1c\ub77c\u300f\uc758 \ub300\uc7a5\uc7a5\uc774\uc640 \ud48d\uc694\ub97c \ub458\ub7ec\uc2fc \ub2e4\ud23c \uc0bc\ud3ec\uc758 \uc81c\uc791\uacfc \uc18c\uc720, \ud0c8\ucde8\uc640 \ud30c\uc190\uc744 \ud06c\ub85c\ud37c\ub4dc\uc758 \u300e\uce7c\ub808\ubc1c\ub77c\u300f \ubc88\uc5ed \uc81c10\u00b742\u00b743\ub178\ub798\uc5d0 \ub530\ub77c \uc77d\uc2b5\ub2c8\ub2e4. \uc2e0\ud654\uc640 \ubbfc\uc18d \ubb38\ud654\uc640 \uc608\uc220 \uba39\uc744 \ubc00\uac00\ub8e8\uc640 \uc18c\uae08, \uc4f8 \ub3c8\uc774 \uacc4\uc18d \ub098\uc628\ub2e4\uba74 \uc0dd\ud65c\uc740 \uc5bc\ub9c8\ub098 \ud3b8\ud574\uc9c8\uae4c. \u300e\uce7c\ub808\ubc1c\ub77c\u300f\uc5d0 \ub098\uc624\ub294 \uc0bc\ud3ec\ub294 \uadf8\ub7f0 \ud48d\uc694\ub97c \ub0b4\ub294 \uc2e0\ube44\ud55c \ubb3c\uac74\uc774\ub2e4. \ub9cc\ub4e4\uae30\ub9cc \ud558\uba74 \ubaa8\ub450\uac00 \ud589\ubcf5\ud560 \ub4ef\ud558\uc9c0\ub9cc \uc774\uc57c\uae30\ub294 \uadf8 \ub4a4\uc5d0 \ub354 \ubcf5\uc7a1\ud574\uc9c4\ub2e4. \ub204\uac00 \uac00\uc9c0\uace0 \ub204\uac00 \ub098\ub220 \uac00\uc9c8\uc9c0 \ub2e4\ud22c\ub294 \ub3d9\uc548 \ubcf4\ubb3c\uc740 \ub05d\ub0b4 \ubd80\uc11c\uc9c4\ub2e4. \uc774 \uae00\uc740 \uc874 \ub9c8\ud2f4 \ud06c\ub85c\ud37c\ub4dc\uc758 1888\ub144 \uc601\ubb38 \ubc88\uc5ed\uc5d0\uc11c \uc0bc\ud3ec\ub97c \ub9cc\ub4e4\uace0 \uac00\uc838\uc624\ub2e4 \uc783\ub294 \ub300\ubaa9\uc744 \ub530\ub77c \uc77d\ub294\ub2e4. \ud48d\uc694\uc758 \uae30\uc220\ubcf4\ub2e4 \uadf8\uac83\uc744 \ub458\ub7ec\uc2fc \uad00\uacc4\uac00 \uc911\uc694\ud55c \uc774\uc57c\uae30\ub2e4. \ud3ec\ud750\uc69c\ub77c\uc758 \uc8fc\uc778 \ub8e8\ud788\ub294 \uc19c\uc528 \uc88b\uc740 \ub300\uc7a5\uc7a5\uc774 \uc77c\ub9c8\ub9ac\ub128\uc5d0\uac8c \uc0bc\ud3ec\ub97c \ub9cc\ub4e4\uc5b4 \ub2ec\ub77c\uace0 \ud55c\ub2e4. \uadf8 \ub300\uac00\ub85c \ub538\uacfc\uc758 \ud63c\uc778\uc744 \ub0b4\uac74\ub2e4. \ub178\ub798\uc640 \uc9c0\ud61c\ub85c \uc54c\ub824\uc9c4 \ubca0\uc774\ub124\ubafc\uc774\ub128\ub3c4 \uc774 \uc57d\uc18d\uacfc \ub300\uc7a5\uc7a5\uc774\uc758 \uc774\ub3d9\uc5d0 \uad00\uc5ec\ud55c\ub2e4. \ud558\uc9c0\ub9cc \ub300\uc7a5\uc7a5\uc774\uac00 \ucc98\uc74c\ubd80\ud130 \uae30\uaebc\uc774 \ucc3e\uc544\uac04 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2e0\ube44\ud55c \ub098\ubb34\ub97c \ubcf4\ub824\ub2e4\uac00 \ubc14\ub78c\uc5d0 \uc2e4\ub824 \ubd81\ucabd\uc73c\ub85c \uac00\ub294 \uc7a5\uba74\uc774 \uc788\ub2e4. \uc601\uc6c5\ub4e4\ub3c4 \uc11c\ub85c\uc758 \ud798\uacfc \uc7ac\uc8fc\ub97c \uc790\uae30 \ud544\uc694\uc5d0 \uc774\uc6a9\ud55c\ub2e4. \ubd80\ud0c1 \ud558\ub098\uc5d0 \uc774\ubbf8 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uae30\ub300\uac00 \uc5bd\ud600 \uc788\ub2e4. \uc77c\ub9c8\ub9ac\ub128\uc740 \ub3c4\ucc29\ud558\uc790\ub9c8\uc790 \uc644\uc131\ud488\uc744 \uaebc\ub0b4\uc9c0 \uc54a\ub294\ub2e4. \ub3c4\uad6c\uc640 \uc77c\ud560 \uacf3\uc744 \ucc3e\uace0 \ub300\uc7a5\uac04\uacfc \ud654\ub355\uc744 \uc900\ube44\ud55c\ub2e4. \uc2e0\ube44\ud55c \uc7ac\ub8cc\uc640 \uc8fc\ubb38\uc774 \ub4f1\uc7a5\ud558\ub294 \uc138\uacc4\uc774\uc9c0\ub9cc \uc77c\uc758 \uc790\ub9ac\ub97c \ub9cc\ub4dc\ub294 \uacfc\uc815\ub3c4 \ub178\ub798\uc5d0 \ub4e4\uc5b4 \uc788\ub2e4. \uc5f4\uc744 \ub9cc\ub4e4\uace0 \ud480\ubb34\ub97c \uc6c0\uc9c1\uc774\uba70 \ubb34\uc5c7\uc774 \uc0dd\uae30\ub294\uc9c0 \uc0b4\ud540\ub2e4. \ub9c8\ubc95\uc758 \ubcf4\ubb3c\uc5d0\ub3c4 \ub178\ub3d9\uc758 \ub9ac\ub4ec\uc774 \ubd99\ub294 \uc810\uc774 \ud765\ubbf8\ub86d\ub2e4. \uc190\uc744 \ud55c \ubc88 \ud754\ub4e4\uba74 \uc18c\uc6d0\uc774 \uc774\ub8e8\uc5b4\uc9c0\ub294 \ubb3c\uac74\ubcf4\ub2e4 \uae30\ub2e4\ub9ac\uace0 \uc2e4\ud328\ud558\ub294 \uc2dc\uac04\uc774 \uc788\ub294 \uc81c\uc791\uc774\ub2e4. \ud654\ub355\uc5d0\uc11c\ub294 \ud65c\uacfc \ubc30, \uc18c\uc640 \uc7c1\uae30\uac00 \ucc28\ub840\ub85c \ub098\uc628\ub2e4. \uac89\ubaa8\uc2b5\uc740 \uba4b\uc9c0\uc9c0\ub9cc \uc131\uc9c8\uc774 \uc0ac\ub0a9\uac70\ub098 \uc4f8\ubaa8\uac00 \uc5b4\uae0b\ub09c\ub2e4. \uc2f8\uc6c0\uc744 \ucc3e\uace0 \uc790\uae30 \ubaab\uc744 \ub0ad\ube44\ud558\uba70 \uc88b\uc740 \ubc2d\uae4c\uc9c0 \ub9dd\uce5c\ub2e4. \uc77c\ub9c8\ub9ac\ub128\uc740 \ub9c8\uc74c\uc5d0 \ub4e4\uc9c0 \uc54a\uc544 \ub2e4\uc2dc \ud654\ub355\uc5d0 \ub123\ub294\ub2e4. \ub9cc\ub4e4 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc88b\uc740 \ubb3c\uac74\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc5b4\ub5a4 \ud589\ub3d9\uacfc \uacb0\uacfc\ub97c \ub0b4\ub294\uc9c0\ub3c4 \uc0b4\ud3b4\uc57c \ud588\ub2e4. \ubc88\uca4d\uc774\ub294 \uc7ac\ub8cc\uc640 \uc19c\uc528\ubcf4\ub2e4 \uadf8 \ubb3c\uac74\uc774 \uc0dd\ud65c\uc5d0 \ubb34\uc5c7\uc744 \uac00\uc838\uc62c\uc9c0\uac00 \uc911\uc694\ud55c \ud310\ub2e8\uc73c\ub85c \ub4f1\uc7a5\ud55c\ub2e4. \ub9c8\uce68\ub0b4 \uc0bc\ud3ec\uac00 \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4. \uc774 \ubc88\uc5ed\uc5d0\uc11c\ub294 \ud55c\ucabd\uc5d0\uc11c \ubc00\uac00\ub8e8, \ub2e4\ub978 \ucabd\uc5d0\uc11c \uc18c\uae08, \ub610 \ub2e4\ub978 \ucabd\uc5d0\uc11c \ub3c8\uc774 \ub098\uc628\ub2e4. \uc5ec\ub7ec \uc0c9\uc758 \ub69c\uaed1\ub3c4 \ubb18\uc0ac\ub41c\ub2e4. \uba39\uace0 \uac70\ub798\ud558\uba70 \ub0a8\uaca8 \ub458 \uc790\uc6d0\uc744 \ub9cc\ub4dc\ub294 \ubb3c\uac74\uc774\ub2e4. \ub178\ub798\ub294 \uba39\uc744 \ubaab\uacfc \uc2dc\uc7a5\uc5d0 \ub0bc \ubaab, \uc800\uc7a5\ud560 \ubaab\uc744 \ub098\ub780\ud788 \ub4e4\ub824\uc900\ub2e4. \ubb34\ud55c\ud55c \uc0ac\uce58\ubcf4\ub2e4 \uc0dd\ud65c\uc744 \uc774\uc5b4 \uac08 \ud48d\uc694\uac00 \uad6c\uccb4\uc801\uc778 \ubb3c\ud488\uc73c\ub85c \ub098\ud0c0\ub09c \uc148\uc774\ub2e4. \ub2e4\ub9cc \uc0bc\ud3ec\uc758 \ubaa8\uc2b5\uc744 \uc2e4\uc81c \uae30\uacc4\uc758 \uc124\uacc4\ub3c4\ucc98\ub7fc \ud655\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub8e8\ud788\ub294 \uc0bc\ud3ec\ub97c \uc18c\uc911\ud788 \uac04\uc9c1\ud55c\ub2e4. \uae4a\uc740 \uacf3\uc5d0 \ub450\uace0 \uc27d\uac8c \uac00\uc838\uac08 \uc218 \uc5c6\uac8c \ud55c\ub2e4. \ubcf4\ubb3c\uc740 \ub9cc\ub4e4\uc5b4\uc9c4 \ub4a4 \ubaa8\ub450\uc5d0\uac8c \uc800\uc808\ub85c \ub098\ub258\uc9c0 \uc54a\ub294\ub2e4. \uadf8\uac83\uc744 \uac00\uc9c4 \ucabd\uacfc \ubc14\uae65\uc5d0 \uc788\ub294 \ucabd\uc758 \ucc28\uc774\uac00 \uc0dd\uae34\ub2e4. \uc77c\ub9c8\ub9ac\ub128\ub3c4 \uc0bc\ud3ec\ub97c \ub9cc\ub4e4\uc5c8\ub2e4\uace0 \ubaa8\ub4e0 \uc57d\uc18d\uc744 \uc989\uc2dc \uc774\ub8e8\uace0 \ub3cc\uc544\uac00\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub8e8\ud788\uc758 \ub538 \uc5ed\uc2dc \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc758 \uacc4\uc0b0\ub300\ub85c\ub9cc \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc81c\uc791\uc758 \uc131\uacf5\uacfc \uac01\uc790\uac00 \uc6d0\ud558\ub294 \uc0b6\uc740 \uc11c\ub85c \ub2e4\ub978 \ubb38\uc81c\ub85c \ub0a8\ub294\ub2e4. \ub4a4\uc5d0 \ubca0\uc774\ub124\ubafc\uc774\ub128\uacfc \uc77c\ub9c8\ub9ac\ub128, \ub808\ubbfc\uce90\uc774\ub128\uc774 \uc0bc\ud3ec\ub97c \ucc3e\uc544\uac04\ub2e4. \ud48d\uc694\ub97c \ub098\ub204\uc790\ub294 \uc694\uad6c\ub97c \ub8e8\ud788\uac00 \ubc1b\uc544\ub4e4\uc774\uc9c0 \uc54a\uc790 \uac00\uc838\uac00\uae30\ub85c \ud55c\ub2e4. \ub178\ub798\ub85c \uc0ac\ub78c\ub4e4\uc744 \uc7a0\ub4e4\uac8c \ud558\uace0 \ubcf4\ubb3c\uc744 \uaebc\ub0b4 \ubc30\uc5d0 \uc2e3\ub294\ub2e4. \uc774 \uc7a5\uba74\uc744 \ub2e8\uc21c\ud788 \ucc29\ud55c \uc601\uc6c5\ub4e4\uc774 \uc545\ub2f9\uc5d0\uac8c\uc11c \ubb3c\uac74\uc744 \ub3cc\ub824\ubc1b\ub294 \uc77c\ub85c\ub9cc \ubcfc \ud544\uc694\ub294 \uc5c6\ub2e4. \ub9cc\ub4e0 \uc0ac\ub78c\uacfc \uac00\uc9c4 \uc0ac\ub78c, \uadf8\uac83\uc774 \ud544\uc694\ud55c \uc0ac\ub78c\uc758 \uc0dd\uac01\uc774 \uc5b4\uae0b\ub09c\ub2e4. \ub8e8\ud788\uc5d0\uac8c\ub294 \uc790\uae30 \ub545\uc758 \ud48d\uc694\ub97c \ube7c\uc557\uc544 \uac00\ub294 \uc0ac\uac74\uc774\ub2e4. \uc7a0\uc5d0\uc11c \uae68\uc5b4\ub09c \ub8e8\ud788\ub294 \uc77c\ud589\uc744 \ub4a4\ucad3\ub294\ub2e4. \ubc30\uc640 \ubc14\ub2e4, \uac70\ub300\ud55c \uc0c8\ub85c \ubcc0\ud55c \ucd94\uaca9\uc790\uac00 \ubd80\ub52a\uce58\ub294 \uc7a5\uba74\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ud48d\uc694\ub97c \uc62e\uae30\ub294 \uae38\uc740 \uc870\uc6a9\ud55c \uadc0\ud658\uc774 \ub418\uc9c0 \ubabb\ud55c\ub2e4. \ubcf4\ubb3c\uc744 \uac00\uc9c4\ub2e4\ub294 \uc77c\uc774 \uc2f8\uc6c0\uc758 \uc6d0\uc778\uc774 \ub418\uc5c8\ub2e4. \ub2e4\ud22c\ub294 \ub3d9\uc548 \uc0bc\ud3ec\ub294 \ubd80\uc11c\uc838 \ubc14\ub2e4\uc5d0 \ub5a8\uc5b4\uc9c4\ub2e4. \ubaa8\ub450\uc758 \ubb38\uc81c\ub97c \ud574\uacb0\ud560 \uac83 \uac19\uc558\ub358 \ubb3c\uac74\uc774 \uc190\uc5d0\uc11c \uc0ac\ub77c\uc9c4\ub2e4. \ub204\uac00 \ub3c5\ucc28\uc9c0\ud560 \uac83\uc778\uc9c0\uc5d0 \uc9d1\uc911\ud558\ub358 \uc0ac\ub78c\ub4e4\uc774 \uc628\uc804\ud55c \ubcf4\ubb3c\uc744 \ud568\uaed8 \uc783\ub294 \uacb0\ub9d0\uc774\ub2e4. \uc774\uc57c\uae30\ub294 \ud30c\uc190\uc73c\ub85c \uc644\uc804\ud788 \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc77c\ubd80 \uc870\uac01\uc740 \ubc14\ub2e4\uc5d0 \ub0a8\uace0 \uc77c\ubd80\ub294 \ud574\uc548\uc73c\ub85c \ub5a0\uc628\ub2e4. \ubca0\uc774\ub124\ubafc\uc774\ub128\uc740 \uadf8\uac83\uc744 \ubaa8\uc73c\uba70 \uc790\uae30 \ub545\uc758 \uace1\uc2dd\uacfc \ud48d\uc694\ub85c \uc774\uc5b4\uc9c0\ub9ac\ub77c\uace0 \uae30\ub300\ud55c\ub2e4. \uc644\uc804\ud55c \ud615\ud0dc\ub97c \uc783\uc5b4\ub3c4 \ud798\uc774 \ub0a8\ub294 \uac83\uc774\ub2e4. \uc774 \ub300\ubaa9\uc744 \ubaa8\ub4e0 \ubc14\ub2f7\ubb3c\uc758 \uc9e0\ub9db\uc744 \uc124\uba85\ud558\ub294 \uc774\uc57c\uae30\ub85c \ubc14\uafb8\uc9c0\ub294 \uc54a\uc558\ub2e4. \uc120\ud0dd\ud55c \ub178\ub798\ub294 \uc870\uac01\uc774 \uac00\uc838\uc62c \uc790\uc6d0\uacfc \ubc88\uc601\uc744 \ub9d0\ud55c\ub2e4. \uc775\uc219\ud55c \ub2e4\ub978 \ubbfc\ub2f4\uc758 \ub9c8\ubc95 \ub9f7\ub3cc\uacfc \ub2ee\uc558\uc5b4\ub3c4 \uacb0\ub9d0\uc744 \uadf8\ub300\ub85c \uc62e\uaca8 \ubd99\uc77c \uc218\ub294 \uc5c6\ub2e4. \u300e\uce7c\ub808\ubc1c\ub77c\u300f\ub294 19\uc138\uae30\uc5d0 \uc5ec\ub7ec \uad6c\uc804 \ub178\ub798\ub97c \ubaa8\uc544 \uc5ee\uc740 \uc11c\uc0ac\uc2dc\ub2e4. \uae34 \uc804\uc2b9\uacfc \ud3b8\uc9d1\uc758 \uacfc\uc815\uc744 \uac70\ucce4\uc73c\uba70 \uc624\ub298 \uc77d\ub294 \uc601\ubb38 \ubc88\uc5ed\ub3c4 \uadf8 \uc0ac\uc774\uc5d0 \uc788\ub2e4. \ub4f1\uc7a5\ud558\ub294 \ubd81\ucabd \ub545\uc758 \uc778\ubb3c\uc744 \uc2e4\uc81c \uc9c0\uc5ed \uc0ac\ub78c \uc804\uccb4\uc758 \uc131\uaca9\uc73c\ub85c \ubcfc \ud544\uc694\ub294 \uc5c6\ub2e4. \uc0bc\ud3ec\ub97c \ub5a0\uc62c\ub9ac\uba74 \ub04a\uc784\uc5c6\uc774 \ub098\uc624\ub294 \ubb3c\uac74\ubcf4\ub2e4 \uadf8\uac83\uc744 \ub458\ub7ec\uc2fc \uc190\ub4e4\uc744 \ubcf4\uac8c \ub41c\ub2e4. \ub9cc\ub4dc\ub294 \uc190, \uc7a0\uac00 \ub450\ub294 \uc190, \uac00\uc838\uc624\ub294 \uc190, \ubd80\uc11c\uc9c4 \uc870\uac01\uc744 \uc90d\ub294 \uc190. \ud48d\uc694\uac00 \uc0dd\uae30\ub294 \uac83\uacfc \ud568\uaed8 \ub204\ub9ac\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4\ub294 \uc9c8\ubb38\uc774 \uc2e0\ube44\ud55c \ub69c\uaed1 \uc544\ub798\uc5d0 \ub0a8\uc544 \uc788\ub2e4."}, {"id": "sanchi-stupa-gates-and-circling-path", "title": "\uc0b0\uce58 \ub300\ud0d1 \u2014 \ub4e4\uc5b4\uac00\ub294 \ub300\uc2e0 \uc8fc\uc704\ub97c \ub3c4\ub294 \uac74\ucd95", "summary": "\uc548\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \ub300\uc2e0 \uc8fc\ubcc0\uc744 \uac77\ub294 \ud0d1\uacfc \uc870\uac01 \ubb38\uc744 \ud1b5\ud574 \uac74\ucd95\uacfc \ubab8\uc758 \uad00\uacc4\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uac74\ucd95", "categories": ["arts"], "url": "stories/sanchi-stupa-gates-and-circling-path/index.html", "image": "../media/sanchi-stupa-gates-and-circling-path.jpg", "alt": "\uc0b0\uce58 \ub300\ud0d1 \ubd81\ubb38\uc758 \uae30\ub465\uacfc \uacb9\uce5c \uac00\ub85c \ubd80\uc7ac, \ubd80\uc870\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc5ed\uc0ac \ub3c4\ud310", "text": "\uc0b0\uce58 \ub300\ud0d1 \u2014 \ub4e4\uc5b4\uac00\ub294 \ub300\uc2e0 \uc8fc\uc704\ub97c \ub3c4\ub294 \uac74\ucd95 \ub3d4\uacfc \ub458\ub808\uae38, \ud1a0\ub77c\ub098\uc758 \uc870\uac01\uc73c\ub85c \uacbd\ud5d8\ud558\ub294 \ubd88\uad50 \uac74\ucd95 \uc548\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \ub300\uc2e0 \uc8fc\ubcc0\uc744 \uac77\ub294 \ud0d1\uacfc \uc870\uac01 \ubb38\uc744 \ud1b5\ud574 \uac74\ucd95\uacfc \ubab8\uc758 \uad00\uacc4\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uac74\ucd95 \ubb38\ud654\uc640 \uc608\uc220 \uc885\uad50 \uac74\ucd95\uc744 \ubcf4\uba74 \ubb38\uc744 \uc5f4\uace0 \ub0b4\ubd80\ub85c \ub4e4\uc5b4\uac00\ub294 \uc7a5\uba74\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uc778\ub3c4 \uc0b0\uce58\uc758 \ub300\ud0d1\uc740 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ubab8\uc744 \uc6c0\uc9c1\uc774\uac8c \ud55c\ub2e4. \ub465\uadfc \ub369\uc5b4\ub9ac\uc640 \ub458\ub808\uae38, \uc870\uac01\uc73c\ub85c \ucc44\uc6b4 \ubb38\uc774 \ud568\uaed8 \uacbd\ud5d8\uc744 \ub9cc\ub4e0\ub2e4. \uc548\uc5d0 \uc5b4\ub5a4 \ubc29\uc774 \uc788\ub294\uc9c0 \ubb3b\uae30 \uc804\uc5d0 \uadf8 \uc8fc\ubcc0\uc5d0\uc11c \ubb34\uc5c7\uc744 \ud558\ub3c4\ub85d \ud588\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc0b0\uce58\uc758 \ud070 \ub465\uadfc \ud615\ud0dc\ub294 \uc608\ubc30\ub2f9\uc758 \ub113\uc740 \ub0b4\ubd80\ub97c \ub36e\uc740 \uc9c0\ubd95\uacfc \ub2e4\ub974\ub2e4. \uc2a4\ud22c\ud30c\ub294 \uc0ac\ub9ac\uc640 \uae30\uc5b5, \uc2e0\uc559\uc758 \uc758\ubbf8\ub97c \ub2f4\uc740 \uae30\ub150 \uad6c\uc870\ub85c \uc774\ud574\ud574\uc57c \ud55c\ub2e4. \uac89\uc758 \ubaa8\uc591\ub9cc \ubcf4\uace0 \uc624\ub298\uc758 \uacf5\uc5f0\uc7a5\uc774\ub098 \uc131\ub2f9 \uac19\uc740 \uc2e4\ub0b4\ub97c \uc0c1\uc0c1\ud558\uba74 \ubaa9\uc801\uc744 \ub193\uce5c\ub2e4. \ubb34\uc5c7\uc774 \ubcf4\uad00\ub418\uc5c8\ub294\uc9c0\ub97c \uc544\ub294 \uac83\uacfc \uadf8\uac83\uc744 \ubaa8\ub450 \uc9c1\uc811 \ubcf4\ub294 \uc77c\ub3c4 \uac19\uc9c0 \uc54a\ub2e4. \uc131\uc2a4\ub7ec\uc6b4 \ub300\uc0c1\uc744 \ub458\ub7ec\uc2fc \uacf5\uac04\uc744 \uacbd\ud5d8\ud558\ub294 \ubc29\ubc95\uc774 \uc788\uc5c8\ub2e4. \uac74\ucd95\uc758 \uae30\ub2a5\uc744 \ubc29\uacfc \ubb38\uc73c\ub85c\ub9cc \uc124\uba85\ud560 \uc218 \uc5c6\uc74c\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ucd9c\ubc1c\uc810\uc774\ub2e4. \uc0b0\uce58\uc758 \ucd08\uae30 \uc5ed\uc0ac\ub294 \uc544\uc1fc\uce74\uc640 \uc5f0\uacb0\ub418\uc9c0\ub9cc \uc9c0\uae08 \ubcf4\uc774\ub294 \ubaa8\ub4e0 \uc694\uc18c\uac00 \uadf8\ub54c \ud55c\uaebc\ubc88\uc5d0 \uc644\uc131\ub418\uc5c8\ub2e4\uace0 \ud560 \uc218\ub294 \uc5c6\ub2e4. \uaddc\ubaa8\uc640 \ud45c\uba74, \ub458\ub808\uc758 \uc2dc\uc124\uacfc \ubb38\uc5d0 \uc5ec\ub7ec \uc2dc\uae30\uc758 \uc791\uc5c5\uc774 \uacb9\uccd0 \uc788\ub2e4. \uc624\ub798\ub41c \uc720\uc801\uc740 \ud55c \uc2dc\ub300\uc758 \ubaa8\uc2b5\uc774 \uadf8\ub300\ub85c \uad73\uc740 \ubb3c\uac74\ubcf4\ub2e4 \uae34 \ubcc0\ud654\uc758 \uacb0\uacfc\uc5d0 \uac00\uae5d\ub2e4. 19\uc138\uae30 \uac74\ucd95\uc0ac\uac00 \uc81c\uc784\uc2a4 \ud37c\uac70\uc2a8\ub3c4 \uc0b0\uce58\uc758 \uad6c\uc870\uc640 \ubb38\uc744 \ub098\ub204\uc5b4 \uc124\uba85\ud588\ub2e4. \ub2e4\ub9cc \ub2f9\uc2dc\uc758 \uc815\ud655\ud55c \uc5f0\ub300 \ucd94\uc815\uacfc \ubb38\ud654 \ud3c9\uac00\ub97c \ubaa8\ub450 \uc624\ub298\uc758 \ud655\uc815 \uc0ac\uc2e4\ub85c \uc62e\uae38 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub0a8\uc740 \ud615\uc0c1\uc5d0\uc11c \uad00\ucc30\ud560 \uc218 \uc788\ub294 \uac83\uacfc \ud6c4\ub300 \uc5f0\uad6c\uc758 \ud310\ub2e8\uc744 \uad6c\ubcc4\ud560 \uc218 \uc788\ub2e4. \ub09c\uac04\uacfc \ub458\ub808\uc758 \ud1b5\ub85c\ub294 \uc6c0\uc9c1\uc784\uc758 \ubc94\uc704\ub97c \ub9cc\ub4e0\ub2e4. \ud0d1\uc758 \uc911\uc2ec\uc744 \uace7\ubc14\ub85c \ud1b5\uacfc\ud558\ub294 \ub300\uc2e0 \uadf8 \uc8fc\uc704\ub97c \ub530\ub77c \uac77\uac8c \ub41c\ub2e4. \uacc4\ub2e8\uacfc \uc704\ucabd\uc758 \uae38\ub3c4 \ub192\uc774\uc640 \ub3d9\uc120\uc744 \ub098\ub208\ub2e4. \uac00\ub9cc\ud788 \uc11c\uc11c \uc815\uba74\ub9cc \ubcf4\ub294 \uacbd\ud5d8\uacfc\ub294 \ub2e4\ub974\ub2e4. \uc0ac\ub78c\uc774 \uc6c0\uc9c1\uc774\uba74 \uc870\uac01\uacfc \ub465\uadfc \ud0d1\uc758 \uacb9\uce68\ub3c4 \uacc4\uc18d \ub2ec\ub77c\uc9c4\ub2e4. \uac19\uc740 \uad6c\uc870\uac00 \ub2e4\ub978 \uac01\ub3c4\uc5d0\uc11c \ubc18\ubcf5\ud574\uc11c \ub098\ud0c0\ub09c\ub2e4. \uacf5\uac04\uc744 \uc774\ud574\ud558\ub294 \ub370\uc5d0\ub294 \ub208\ubfd0 \uc544\ub2c8\ub77c \uac77\ub294 \ubab8\uacfc \uc2dc\uac04\uc774 \ud544\uc694\ud558\ub2e4. \uac74\ucd95\uc758 \uc758\ubbf8\uac00 \ud55c \uc7a5\uc758 \uc815\uba74 \uc0ac\uc9c4\uc73c\ub85c \ub2e4 \ub2f4\uae30\uc9c0 \uc54a\ub294 \uc774\uc720\ub2e4. \ud1a0\ub77c\ub098\ub77c\uace0 \ubd80\ub974\ub294 \ubb38\uc740 \uae30\ub465\uacfc \uac00\ub85c \ubd80\uc7ac\ub85c \uc774\ub8e8\uc5b4\uc838 \uc870\uac01\uc744 \ub2f4\ub294\ub2e4. \ub3c4\uc2dc\uc758 \ubc29\uc5b4\ubb38\ucc98\ub7fc \uc548\uc744 \uc9c0\ud0a4\ub294 \uc7a5\uce58\ub85c\ub9cc \uc774\ud574\ud558\uae30 \uc5b4\ub835\ub2e4. \uc811\uadfc\uacfc \ud1b5\uacfc\ub97c \uac15\uc870\ud558\uba74\uc11c \ub3d9\uc2dc\uc5d0 \uc5ec\ub7ec \uc7a5\uba74\uc744 \ubc14\ub77c\ubcf4\uac8c \ud55c\ub2e4. \uac00\ub85c \ubd80\uc7ac\uac00 \uacb9\uce58\uace0 \uadf8 \uc704\uc544\ub798\ub85c \ud615\uc0c1\ub4e4\uc774 \uc774\uc5b4\uc9c0\uba74\uc11c \uc2dc\uc120\uc740 \ud55c\uacf3\uc5d0 \uba48\ucd94\uc9c0 \uc54a\ub294\ub2e4. \uba40\ub9ac\uc11c\ub294 \ubb38 \uc804\uccb4\uc758 \uc724\uacfd\uc744 \ubcf4\uace0 \uac00\uae4c\uc774\uc11c\ub294 \uc138\ubd80\uc758 \ub3d9\ubb3c\uacfc \uc0ac\ub78c, \uc7a5\uc2dd\uc744 \uc77d\uac8c \ub41c\ub2e4. \uc791\uc740 \uc870\uac01\uacfc \ud070 \uad6c\uc870\uac00 \ub2e4\ub978 \uac70\ub9ac\uc758 \uad00\uac1d\uc744 \ud568\uaed8 \uc0c1\ub300\ud55c\ub2e4. \ubb38\uc740 \uae30\ub465 \uc0ac\uc774\uc5d0 \ube44\uc5b4 \uc788\ub294 \ubd80\ubd84\ub3c4 \uac16\ub294\ub2e4. \uc870\uac01\uc73c\ub85c \uac00\ub4dd \ucc2c \ud45c\uba74\uacfc \ud1b5\uacfc\ud560 \uc218 \uc788\ub294 \ube48 \ud2c0\uc774 \ud568\uaed8 \uc788\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uad00\uac1d\uc740 \uc774\uc57c\uae30\ub97c \ubc14\ub77c\ubcf4\uba74\uc11c \ub3d9\uc2dc\uc5d0 \uadf8 \uc544\ub798\ub97c \uc9c0\ub098\ub294 \uc0ac\ub78c\uc774\ub2e4. \uadf8\ub9bc\uc744 \ubcbd\uc5d0 \uac78\uc5b4 \uba40\ub9ac\uc11c\ub9cc \ubcf4\ub294 \uacbd\ud5d8\uacfc\ub294 \ub2e4\ub978 \uad00\uacc4\uac00 \uc0dd\uae34\ub2e4. \uac19\uc740 \uc870\uac01\ub3c4 \ubcf4\ub294 \ub192\uc774\uc640 \uac70\ub9ac, \uac77\ub294 \ubc29\ud5a5\uc5d0 \ub530\ub77c \uba3c\uc800 \ub208\uc5d0 \ub4e4\uc5b4\uc624\ub294 \ubd80\ubd84\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ubb38\uc744 \ub2e8\ub3c5 \uc791\ud488\uc758 \uc0ac\uc9c4\uc73c\ub85c \ub5bc\uc5b4 \ub193\uc73c\uba74 \uc774\ub7f0 \ubab8\uc758 \uc870\uac74\uc774 \uc904\uc5b4\ub4e0\ub2e4. \uadf8\ub798\uc11c \uc138\ubd80\ub97c \ud655\ub300\ud574 \ubcf8 \ub2e4\uc74c \ud0d1\uacfc \ubb38\uc758 \uc804\uccb4 \uad00\uacc4\ub85c \ub2e4\uc2dc \ub3cc\uc544\uac00 \ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \uc870\uac01\uc744 \uac10\uc0c1\ud558\ub294 \uc77c\uacfc \uacf5\uac04\uc744 \uacbd\ud5d8\ud558\ub294 \uc77c\uc774 \uc774\uacf3\uc5d0\uc11c\ub294 \uc11c\ub85c \ub098\ub258\uc9c0 \uc54a\ub294\ub2e4. \uac74\ucd95\uc740 \uc11c \uc788\ub294 \ubb3c\uccb4\uc774\uc9c0\ub9cc \uadf8 \uc758\ubbf8\ub294 \uc6c0\uc9c1\uc774\ub294 \uc0ac\ub78c\uacfc\uc758 \ub9cc\ub0a8 \uc18d\uc5d0\uc11c \uc774\uc5b4\uc9c4\ub2e4. \uc774 \uc810\uc744 \uc0dd\uac01\ud558\uba74 \uc7a5\uc2dd\uc774\ub77c\ub294 \ub9d0\ub85c \uc9c0\ub098\uce58\ub358 \ubd80\uc870\ub3c4 \ud65c\ub3d9\uc758 \uc77c\ubd80\ub85c \uc77d\ud78c\ub2e4. \uc0b0\uce58\uc758 \ubd80\uc870\uc5d0\uc11c\ub294 \ub098\ubb34\ub098 \uc790\ub9ac, \uc5ec\ub7ec \uc0c1\uc9d5\uc744 \ud1b5\ud574 \ubd88\uad50\uc758 \uc774\uc57c\uae30\ub97c \uc554\uc2dc\ud558\ub294 \uc7a5\uba74\uc744 \ubcfc \uc218 \uc788\ub2e4. \uc0ac\ub78c\uc758 \uc5bc\uad74\uc744 \ud06c\uac8c \ubcf4\uc5ec \uc8fc\ub294 \ubc29\uc2dd\ub9cc\uc774 \uc774\uc57c\uae30\ub97c \uc804\ub2ec\ud558\ub294 \ubc29\ubc95\uc740 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc774 \uadf8 \uc790\ub9ac\uc5d0 \uc788\uace0 \ubb34\uc5c7\uc774 \ube44\uc5b4 \uc788\ub294\uc9c0\ub3c4 \uc758\ubbf8\ub97c \ub9cc\ub4e0\ub2e4. \uc774\ub97c \ucd08\uae30 \ubd88\uad50 \uc804\uccb4\uac00 \uc5b8\uc81c\ub098 \uac19\uc740 \uaddc\uce59\uc744 \ub530\ub790\ub2e4\ub294 \ub2e8\uc815\uc73c\ub85c \ub113\ud790 \ud544\uc694\ub294 \uc5c6\ub2e4. \uad6c\uccb4\uc801\uc778 \uc7a5\uba74\uacfc \ud45c\ud604\uc744 \uc0b4\ud53c\ub294 \uac83\uc774 \uba3c\uc800\ub2e4. \uad00\uac1d\uc740 \uc775\uc219\ud55c \uc0c1\uc9d5\uacfc \uc774\uc57c\uae30\ub97c \uc54c\uace0 \uc788\uc744\uc218\ub85d \uadf8 \uad00\uacc4\ub97c \ub354 \ud48d\ubd80\ud558\uac8c \uc77d\uc744 \uc218 \uc788\uc5c8\uc744 \uac83\uc774\ub2e4. \ub09c\uac04\uacfc \ubb38\uc758 \uad6c\uc131\uc5d0\ub294 \ubaa9\uc870 \uad6c\uc870\ub97c \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \ud615\uc2dd\uc774 \ubcf4\uc778\ub2e4. \ub3cc\uc744 \uc0ac\uc6a9\ud558\uba74\uc11c\ub3c4 \ub2e4\ub978 \uc7ac\ub8cc\uc5d0\uc11c \uc775\uc219\ud588\ub358 \uc9dc\uc784\uacfc \ubaa8\uc591\uc774 \uc774\uc5b4\uc9c8 \uc218 \uc788\ub2e4. \uac74\ucd95\uc758 \uc7ac\ub8cc\uac00 \ubc14\ub00c\uc5c8\ub2e4\uace0 \ud615\ud0dc\uc758 \ubaa8\ub4e0 \uc0dd\uac01\uc774 \uc0c8\ub85c \uc2dc\uc791\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud37c\uac70\uc2a8\uc758 \ub3c4\ud310\uc740 \uc774\ub7f0 \uad00\uacc4\ub97c \ube44\uad50\ud558\ub294 \ub370 \ub3c4\uc6c0\uc744 \uc900\ub2e4. \ub2e4\ub9cc \uc61b \ub3c4\uba74\uacfc \uc0ac\uc9c4\uc5d0\uc11c \ub9cc\ub4e0 \uc7ac\ud604\uc740 \uc624\ub298 \ud604\uc7a5\uc758 \ud45c\uba74\uc744 \uadf8\ub300\ub85c \ubcf4\uc5ec \uc8fc\ub294 \ud604\ub300 \ucd2c\uc601\uc774 \uc544\ub2c8\ub2e4. \uc6d0\uc790\ub8cc\uc758 \uc2dc\ub300\ub97c \ud45c\uc2dc\ud558\uba74 \uc720\uc801\uc758 \uc5ed\uc0ac\uc640 \uadf8\uac83\uc744 \uc870\uc0ac\ud55c \uc5ed\uc0ac\ub97c \ud568\uaed8 \uc77d\uc744 \uc218 \uc788\ub2e4. \uc0b0\uce58 \ub300\ud0d1\uc744 \ubcfc \ub54c\uc5d0\ub294 \uc911\uc559\uc758 \ud06c\uae30\uc640 \ubb38\uc5d0 \uc0c8\uae34 \uc138\ubd80\ub97c \ubc88\uac08\uc544 \ubcf4\uc790. \ub2e4\uc74c\uc5d0\ub294 \uadf8 \uc0ac\uc774\ub97c \uac78\uc5b4\uac00\ub294 \uc0ac\ub78c\uc758 \ub192\uc774\ub97c \uc0c1\uc0c1\ud574 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc911\uc2ec\uc744 \uc9c1\uc811 \ubcf4\uc9c0 \ubabb\ud574\ub3c4 \uc8fc\ubcc0\uc5d0\uc11c\uc758 \ud589\ub3d9\uc774 \uc758\ubbf8\ub97c \uac00\uc9c4\ub2e4\ub294 \uc810\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \uc774\uacf3\uc758 \uac74\ucd95\uc740 \ub0b4\ubd80\ub85c \ub4e4\uc5b4\uac00\uc57c\ub9cc \uae4a\uc740 \uacbd\ud5d8\uc774 \uac00\ub2a5\ud558\ub2e4\ub294 \uc0dd\uac01\uc744 \ub113\ud78c\ub2e4. \ub3cc\uc758 \ub369\uc5b4\ub9ac\uc640 \uae38, \uc870\uac01\uacfc \ubab8\uc758 \uc6c0\uc9c1\uc784\uc774 \ud568\uaed8 \uc2e0\uc559\uc758 \uc7a5\uc18c\ub97c \ub9cc\ub4e0\ub2e4. \ucd9c\uc785\ud558\uc9c0 \ubabb\ud558\ub294 \uc911\uc2ec\uc744 \ub458\ub7ec\uc2fc \ud589\ub3d9\uc5d0\ub3c4 \uae4a\uc774\uac00 \uc788\uc744 \uc218 \uc788\ub2e4. \uacf5\uac04\uc744 \ub9cc\ub4e0 \uc0ac\ub78c\uc774 \ubb34\uc5c7\uc744 \ubcf4\uac8c \ud558\uace0 \uc5b4\ub5a4 \uc6c0\uc9c1\uc784\uc744 \uc720\ub3c4\ud588\ub294\uc9c0 \ubb3b\uac8c \ub41c\ub2e4. \uc0b0\uce58\ub294 \ub208\uc5d0 \ub744\ub294 \uae30\ub150\ubb3c\ubfd0 \uc544\ub2c8\ub77c \uadf8 \uc8fc\uc704\ub97c \ub3c4\ub294 \uc2dc\uac04\uae4c\uc9c0 \uac74\ucd95\uc758 \uc77c\ubd80\ub85c \ubcf4\uac8c \ud55c\ub2e4."}, {"id": "savitri-words-along-yamas-road", "title": "\uc0ac\ube44\ud2b8\ub9ac \u2014 \uc8fd\uc74c\uc758 \uc2e0\uc744 \ub530\ub77c \uac78\uc73c\uba70 \ub098\ub208 \ub9d0", "summary": "\uc0ac\ube44\ud2b8\ub9ac\uc758 \uacb0\ud63c\uacfc \uc0ac\ud2f0\uc544\ubc18\uc758 \uc8fd\uc74c, \uc57c\ub9c8\uc640\uc758 \ub3d9\ud589\uc744 \ud1a0\ub8e8 \ub354\ud2b8\uc758 \uc601\ubb38 \uc2dc \uc7ac\ud654\ubcf8\uc73c\ub85c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc2e0\ud654\uc640 \ubbfc\uc18d", "categories": ["arts"], "url": "stories/savitri-words-along-yamas-road/index.html", "image": "../media/savitri-words-along-yamas-road.png", "alt": "\uc5b4\ub450\uc6cc\uc9c0\ub294 \uc232\uc5d0\uc11c \uc0ac\ube44\ud2b8\ub9ac\uac00 \uc57c\ub9c8\uc640 \ud568\uaed8 \uac78\uc73c\uba70 \ub300\ud654\ud558\ub294 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uc0ac\ube44\ud2b8\ub9ac \u2014 \uc8fd\uc74c\uc758 \uc2e0\uc744 \ub530\ub77c \uac78\uc73c\uba70 \ub098\ub208 \ub9d0 \ud1a0\ub8e8 \ub354\ud2b8\uc758 \uc2dc\uc5d0\uc11c \uc77d\ub294 \uc120\ud0dd\uacfc \uc608\uc5b8, \ub05d\ub098\uc9c0 \uc54a\ub294 \ub300\ud654 \uc0ac\ube44\ud2b8\ub9ac\uc758 \uacb0\ud63c\uacfc \uc0ac\ud2f0\uc544\ubc18\uc758 \uc8fd\uc74c, \uc57c\ub9c8\uc640\uc758 \ub3d9\ud589\uc744 \ud1a0\ub8e8 \ub354\ud2b8\uc758 \uc601\ubb38 \uc2dc \uc7ac\ud654\ubcf8\uc73c\ub85c \uc77d\uc2b5\ub2c8\ub2e4. \uc2e0\ud654\uc640 \ubbfc\uc18d \ubb38\ud654\uc640 \uc608\uc220 \uc8fd\uc74c\uc758 \uc2e0\uc774 \uc0ac\ub791\ud558\ub294 \uc0ac\ub78c\uc758 \uc601\ud63c\uc744 \ub370\ub9ac\uace0 \ub5a0\ub09c\ub2e4. \uc0ac\ube44\ud2b8\ub9ac\ub294 \uadf8 \ub4a4\ub97c \ub530\ub978\ub2e4. \ub3cc\uc544\uac00\ub77c\ub294 \ub9d0\uc744 \ub4e4\uc5b4\ub3c4 \uac77\uae30\ub97c \uba48\ucd94\uc9c0 \uc54a\uace0 \ub300\ud654\ub97c \uc774\uc5b4 \uac04\ub2e4. \ud070 \ubb34\uae30\ub85c \uc2e0\uc744 \uacf5\uaca9\ud558\ub294 \ub300\uc2e0 \ub9d0\uacfc \ub3d9\ud589\uc73c\ub85c \uc774\uc57c\uae30\ub97c \uc6c0\uc9c1\uc774\ub294 \uc778\ubb3c\uc774\ub2e4. \uc0ac\ube44\ud2b8\ub9ac\uc640 \uc0ac\ud2f0\uc544\ubc18\uc740 \uc778\ub3c4\uc758 \uc11c\uc0ac \uc804\ud1b5\uc5d0 \uc804\ud558\ub294 \uc778\ubb3c\ub4e4\uc774\ub2e4. \uc774 \uae00\uc740 \ud1a0\ub8e8 \ub354\ud2b8\uac00 \uc601\uc5b4 \uc2dc\ub85c \ub2e4\uc2dc \uc4f4 \u300c\uc0ac\ube44\ud2b8\ub9ac\u300d\ub97c \ub530\ub978\ub2e4. \ub110\ub9ac \uc54c\ub824\uc9c4 \ub2e4\ub978 \uc7ac\ud654\ubcf8\uacfc \uc18c\uc6d0\uc758 \uc21c\uc11c\ub098 \ub9c8\uc9c0\ub9c9 \ub300\ud654\uac00 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc0ac\ube44\ud2b8\ub9ac\ub294 \uc0ac\ud2f0\uc544\ubc18\uc744 \ub9cc\ub098 \ub9c8\uc74c\uc744 \uc815\ud55c\ub2e4. \uadf8\ub294 \uc655\uac00\uc758 \uc544\ub4e4\uc774\uc9c0\ub9cc \uc544\ubc84\uc9c0\uac00 \uc655\uad6d\uacfc \uc2dc\ub825\uc744 \uc783\uc740 \ub4a4 \uc232\uc5d0\uc11c \uc0b4\uace0 \uc788\ub2e4. \uc0ac\ube44\ud2b8\ub9ac\uc758 \uc120\ud0dd\uc740 \ud654\ub824\ud55c \uad81\uc804\uacfc \ubd80\ub97c \uace0\ub974\ub294 \uc77c\uacfc\ub294 \uac70\ub9ac\uac00 \uc788\uc5c8\ub2e4. \uadf8\uc758 \uc544\ubc84\uc9c0\uc640 \ud604\uc790\ub294 \uc0ac\ud2f0\uc544\ubc18\uc758 \ud6cc\ub96d\ud568\uc744 \uc778\uc815\ud55c\ub2e4. \ubb38\uc81c\ub294 \ud488\uc131\uc774\ub098 \uac00\ubb38\uc774 \uc544\ub2c8\ub2e4. \ud604\uc790\uac00 \ubc1d\ud78c \uc608\uc5b8\uc5d0 \ub530\ub974\uba74 \uc0ac\ud2f0\uc544\ubc18\uc740 \uadf8\ub0a0\ub85c\ubd80\ud130 \ud55c \ud574 \ub4a4\uc5d0 \uc8fd\uc744 \uc6b4\uba85\uc774\uc5c8\ub2e4. \ucd95\ubcf5\ud560 \ub9cc\ud55c \ub9cc\ub0a8\uc774 \ub450\ub824\uc6b4 \uc120\ud0dd\uc73c\ub85c \ubc14\ub010\ub2e4. \uc544\ubc84\uc9c0\ub294 \ub2e4\ub978 \uc0ac\ub78c\uc744 \uace0\ub974\ub77c\uace0 \uc124\ub4dd\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc0ac\ube44\ud2b8\ub9ac\ub294 \uc774\ubbf8 \ub9c8\uc74c\uc744 \uc8fc\uc5c8\uace0 \uadf8 \uc120\ud0dd\uc744 \ub418\ub3cc\ub9b4 \uc218 \uc5c6\ub2e4\uace0 \ub9d0\ud55c\ub2e4. \ub204\uad70\uac00 \ub300\uc2e0 \uc815\ud55c \uacb0\ud63c\uc744 \uc21c\uc21c\ud788 \ub530\ub974\ub294 \uc778\ubb3c\ub85c\ub9cc \ubcf4\uba74 \uc774 \uc2dc\uc791\uc744 \ub193\uce5c\ub2e4. \ubb3c\ub860 \uadf8 \uc2dc\ub300\uc758 \ud63c\uc778\uacfc \uc758\ubb34\uc5d0 \uad00\ud55c \uc0dd\uac01\uc774 \uc2dc\uc758 \ub9d0 \uc18d\uc5d0 \ub4e4\uc5b4 \uc788\ub2e4. \uc624\ub298\uc758 \ubaa8\ub4e0 \uc0ac\ub78c\uc5d0\uac8c \uac19\uc740 \uacb0\uc815\uc744 \uc694\uad6c\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c\ub294 \ud55c \uc778\ubb3c\uc774 \ubd88\ud589\uc744 \ubbf8\ub9ac \uc54c\uac8c \ub41c \ub4a4 \uc790\uae30 \uc120\ud0dd\uc744 \uc5b4\ub5bb\uac8c \uc0b4\uc544\uac00\ub294\uc9c0\uac00 \uc774\uc57c\uae30\uc758 \uc911\uc2ec\uc774\ub2e4. \uacb0\ud63c \ub4a4 \uc0ac\ube44\ud2b8\ub9ac\ub294 \ub0a8\ud3b8\uacfc \uadf8 \uac00\uc871\uc774 \uc0ac\ub294 \uacf3\uc73c\ub85c \uac04\ub2e4. \uad81\uc804\uc5d0\uc11c\uc758 \uc0dd\ud65c\uacfc \ub2ec\ub9ac \uc232\uc758 \uc77c\uc0c1\uc744 \uc0b4\uc544\uac04\ub2e4. \uc0ac\ud2f0\uc544\ubc18\uc5d0\uac8c \ub2e4\uac00\uc62c \ub0a0\uc744 \uc54c\uace0 \uc788\ub294 \uc0ac\ub78c\uc758 \uc2dc\uac04\uc740 \ub2e4\ub978 \uc774\ub4e4\uc758 \uc2dc\uac04\uacfc \uac19\uc9c0 \uc54a\ub2e4. \uadf8\ub140\ub294 \uc608\uc815\ub41c \ub0a0\uc744 \uae30\uc5b5\ud558\uba70 \uc900\ube44\ud55c\ub2e4. \uc774\uc57c\uae30\uc758 \uae34\uc7a5\uc740 \ud070 \uc0ac\uac74\uc774 \uc544\uc9c1 \uc77c\uc5b4\ub098\uc9c0 \uc54a\uc740 \ub54c\ubd80\ud130 \uc0dd\uae34\ub2e4. \ub3c5\uc790\ub294 \ud55c \ud574\uc758 \ub05d\uc744 \uc54c\uace0 \uc788\uc73c\ubbc0\ub85c \ud3c9\ubc94\ud55c \ub3d9\ud589\uacfc \ub300\ud654\ub3c4 \ub2e4\ub974\uac8c \uc77d\uac8c \ub41c\ub2e4. \ub0a8\uc740 \ub0a0\uc758 \uae38\uc774\uac00 \uc7a5\uba74\ub9c8\ub2e4 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4. \uadf8\ub0a0 \uc0ac\ube44\ud2b8\ub9ac\ub294 \ub0a8\ud3b8\uc744 \ub530\ub77c \uc232\uc73c\ub85c \uac04\ub2e4. \uc0ac\ud2f0\uc544\ubc18\uc740 \uc77c\ud558\ub2e4 \uace0\ud1b5\uc744 \ub290\ub07c\uace0 \uadf8\ub140 \uacc1\uc5d0 \uc4f0\ub7ec\uc9c4\ub2e4. \uc608\uc5b8\uc744 \ub9d0\ub85c \ub4e4\uc744 \ub54c\uc640 \ub208\uc55e\uc758 \ubab8\uc774 \uc6c0\uc9c1\uc774\uc9c0 \uc54a\uc744 \ub54c\uc758 \uac70\ub9ac\ub294 \ud06c\ub2e4. \uadf8\ub140\ub294 \uacc1\uc744 \ub5a0\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc57c\ub9c8\uac00 \ub098\ud0c0\ub098 \uc0ac\ud2f0\uc544\ubc18\uc758 \uc601\ud63c\uc744 \ub370\ub824\uac04\ub2e4. \uc2dc\ub294 \uc778\uac04\uc758 \ub208\uc5d0 \uc7a1\ud788\uae30 \uc5b4\ub824\uc6b4 \uc774\ubcc4\uc744 \uad6c\uccb4\uc801\uc778 \ub9cc\ub0a8\uacfc \uae38\ub85c \uadf8\ub9b0\ub2e4. \uc0ac\ube44\ud2b8\ub9ac\ub294 \ub0a8\uaca8\uc9c4 \ubab8 \uc606\uc5d0\ub9cc \uba38\ubb34\ub974\uc9c0 \uc54a\uace0 \ub5a0\ub098\ub294 \uc2e0\uc744 \ub530\ub77c \ubc1c\uc744 \uc62e\uae34\ub2e4. \uc57c\ub9c8\ub294 \ub3cc\uc544\uac00\ub77c\uace0 \ud55c\ub2e4. \uc0ac\ube44\ud2b8\ub9ac\ub294 \ud568\uaed8\ud55c \uad00\uacc4\uc640 \uc57d\uc18d, \uc120\ud568\uc5d0 \uad00\ud574 \ub9d0\ud55c\ub2e4. \uadf8\ub140\ub294 \uc2e0\uc744 \ub2e8\uc21c\ud788 \ub098\uc05c \uc801\uc73c\ub85c\ub9cc \ubd80\ub974\uc9c0 \uc54a\uace0 \uadf8\uc758 \uad8c\ud55c\uacfc \uc131\uaca9\uc5d0 \ud638\uc18c\ud55c\ub2e4. \ub300\ud654\uac00 \uacc4\uc18d\ub420 \uc218 \uc788\ub294 \uc5b8\uc5b4\ub97c \ucc3e\ub294 \uac83\uc774\ub2e4. \uc57c\ub9c8\ub294 \uadf8 \ub9d0\uc5d0 \ub9c8\uc74c\uc774 \uc6c0\uc9c1\uc5ec \uc18c\uc6d0\uc744 \ub4e4\uc5b4\uc8fc\uaca0\ub2e4\uace0 \ud55c\ub2e4. \uadf8\ub7ec\ub098 \ucc98\uc74c\uc5d0\ub294 \uc0ac\ud2f0\uc544\ubc18\uc758 \uc0dd\uba85\uc744 \ub3cc\ub824 \ub2ec\ub77c\ub294 \uc694\uad6c\ub97c \uc81c\uc678\ud55c\ub2e4. \ub2f5\uc744 \uc5bb\uc744 \uae30\ud68c\uac00 \uc0dd\uacbc\uc5b4\ub3c4 \uac00\uc7a5 \uc6d0\ud558\ub294 \uac83\uc744 \uace7\ubc14\ub85c \ub9d0\ud560 \uc218\ub294 \uc5c6\uc5c8\ub2e4. \uc0ac\ube44\ud2b8\ub9ac\ub294 \uc2dc\uc544\ubc84\uc9c0\uac00 \uc2dc\ub825\uc744 \ub418\ucc3e\uace0 \uc655\uad6d\uc73c\ub85c \ub3cc\uc544\uac08 \uc218 \uc788\uac8c \ud574\ub2ec\ub77c\uace0 \ud55c\ub2e4. \ub4a4\uc5d0\ub294 \uc790\uae30 \uc544\ubc84\uc9c0\uc5d0\uac8c \uc790\uc190\uc774 \uc0dd\uae30\uae30\ub97c \uccad\ud55c\ub2e4. \uc790\uae30 \uc55e\uc758 \uace0\ud1b5 \uc18d\uc5d0\uc11c\ub3c4 \ub450 \uac00\uc871\uc758 \ubbf8\ub798\ub97c \uc774\uc57c\uae30\ud558\ub294 \uc18c\uc6d0\ub4e4\uc774\ub2e4. \uc57c\ub9c8\ub294 \uc18c\uc6d0\uc744 \ub4e4\uc5b4\uc8fc\uba70 \ub2e4\uc2dc \ub3cc\uc544\uac00\ub77c\uace0 \ud558\uc9c0\ub9cc \ub300\ud654\ub294 \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc2e0\uc774 \ud5c8\ub77d\ud560 \uc218 \uc788\ub294 \uac83\uc758 \ubc94\uc704\uac00 \uc870\uae08\uc529 \ub2ec\ub77c\uc9c4\ub2e4. \uac19\uc740 \uae38\uc744 \uacc4\uc18d \uac77\ub294 \ub3d9\uc548 \uad8c\uc704\ub97c \uac00\uc9c4 \uc874\uc7ac\uc640 \ubd80\ud0c1\ud558\ub294 \uc0ac\ub78c\uc758 \uad00\uacc4\ub3c4 \ubc14\ub010\ub2e4. \ud1a0\ub8e8 \ub354\ud2b8\uc758 \uc2dc\uc5d0\uc11c \uc57c\ub9c8\ub294 \ub9c8\uc9c0\ub9c9\uc5d0 \ub2e4\uc2dc \uc18c\uc6d0\uc744 \uccad\ud558\ub77c\uace0 \ud558\uba74\uc11c \uc55e\uc120 \uc81c\uc678 \uc870\uac74\uc744 \ubd99\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc0ac\ube44\ud2b8\ub9ac\ub294 \uadf8 \ud2c8\uc5d0\uc11c \uc0ac\ud2f0\uc544\ubc18\uc774 \uc0b4\uc544\ub098\uace0 \uc790\uc2e0\ub4e4\uc5d0\uac8c \uc790\ub140\uac00 \uc0dd\uae30\uae30\ub97c \uccad\ud55c\ub2e4. \uc57c\ub9c8\ub294 \uadf8 \ub9d0\uc744 \ubc1b\uc544\ub4e4\uc778\ub2e4. \ub2e4\ub978 \uc720\uba85\ud55c \ud310\ubcf8\uc758 \ub17c\ub9ac \ubb38\uc81c\ucc98\ub7fc \uc18c\uc6d0\ub4e4\uc744 \ub9de\ucd94\uc5b4 \uc4f0\uc9c0 \uc54a\uc558\ub2e4. \uc774 \uc2dc\ub294 \uc120\ud55c \ub9d0\uacfc \ub3d9\ud589, \uc790\ube44\uac00 \uc774\uc5b4\uc9c0\ub294 \ud750\ub984\uc744 \uac15\uc870\ud55c\ub2e4. \uac19\uc740 \uc778\ubb3c\uc774 \ub098\uc640\ub3c4 \uc791\uac00\uc640 \ud310\ubcf8\uc5d0 \ub530\ub77c \ub9c8\uc9c0\ub9c9 \ubb38\uc744 \uc5ec\ub294 \ubc29\uc2dd\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc0ac\ud2f0\uc544\ubc18\uc774 \uae68\uc5b4\ub098\uc790 \ubd80\ubd80\ub294 \uc5b4\ub450\uc6b4 \uc232\uae38\uc744 \uc9c0\ub098 \uac00\uc871\uc5d0\uac8c \ub3cc\uc544\uac00\uc57c \ud55c\ub2e4. \uc0ac\ube44\ud2b8\ub9ac\ub294 \ud798\uc744 \ub418\ucc3e\ub294 \ub0a8\ud3b8\uc744 \ubd80\ucd95\ud55c\ub2e4. \uc8fd\uc74c\uc758 \uc2e0\uacfc \ub9c8\uc8fc\ud558\ub358 \ud070 \uc7a5\uba74 \ub4a4\uc5d0 \ub2e4\uc2dc \uc0ac\ub78c\uc758 \ubab8\uacfc \ubc24\uae38\uc774 \ub098\ud0c0\ub09c\ub2e4. \uadf8\ub140\ub294 \ub0a8\ud3b8\uc758 \ub450\ub824\uc6c0\uacfc \ud63c\ub780\uc744 \ub2ec\ub798\uba70 \ud568\uaed8 \uac77\ub294\ub2e4. \uc774\uc57c\uae30\uc758 \uadc0\ud658\uc740 \uc2e0\uc5d0\uac8c \ud5c8\ub77d\ubc1b\ub294 \uc21c\uac04\uc5d0\ub9cc \uc788\uc9c0 \uc54a\ub2e4. \ub3cc\uc544\uc628 \uc0ac\ub78c\uacfc \uc2e4\uc81c\ub85c \uc9d1\uae4c\uc9c0 \uac00\ub294 \uc2dc\uac04\uc774 \uc788\ub2e4. \uc2dc\uc758 \ub2e4\uc815\ud568\uc740 \uc774\ub7f0 \uc791\uc740 \ud589\ub3d9\uc5d0\uc11c\ub3c4 \ub4dc\ub7ec\ub09c\ub2e4. \uc0ac\ube44\ud2b8\ub9ac\ub97c \uc624\uc9c1 \ud76c\uc0dd\ud558\ub294 \uc544\ub0b4\uc758 \ubaa8\ubc94\uc73c\ub85c\ub9cc \uc77d\uc73c\uba74 \uc2a4\uc2a4\ub85c \uace0\ub974\uace0 \uc9c8\ubb38\ud558\uace0 \ub9d0\ud558\ub294 \uc778\ubb3c\uc774 \ud750\ub824\uc9c4\ub2e4. \uc8fd\uc74c\uc744 \ub418\ub3cc\ub9ac\uc9c0 \ubabb\ud55c \uc0ac\ub78c\uc758 \uc0ac\ub791\uc774 \ubd80\uc871\ud558\ub2e4\ub294 \uad50\ud6c8\uc73c\ub85c \uc0bc\uc744 \uc218\ub3c4 \uc5c6\ub2e4. \ud604\uc2e4\uc758 \uc0c1\uc2e4\uc744 \ud3c9\uac00\ud558\ub294 \uae30\uc900\uc740 \uc544\ub2c8\ub2e4. \uc774 \uc774\uc57c\uae30\uc5d0\uc11c \uc624\ub798 \ub0a8\ub294 \uac83\uc740 \uae38 \uc704\uc758 \ub300\ud654\ub2e4. \uc0ac\ube44\ud2b8\ub9ac\ub294 \uac70\uc808\uc744 \ub4e3\uace0\ub3c4 \uc0c1\ub300\uac00 \uc54c\uc544\ub4e4\uc744 \ub9d0\ub85c \uad00\uacc4\ub97c \uc774\uc5b4 \uac04\ub2e4. \uc6b4\uba85\uc744 \ub9cc\ub098\ub294 \uc778\ubb3c\uc774 \ubc18\ub4dc\uc2dc \uce7c\uc744 \ub4e4\uc5b4\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc0c1\uc0c1, \ub9d0\uacfc \ub048\uae30\uac00 \uc11c\uc0ac\ub97c \uc6c0\uc9c1\uc774\ub294 \uc7a5\uba74\uc744 \uc77d\uc5b4\ub3c4 \uc88b\ub2e4."}, {"id": "schubert-erlking-four-voices", "title": "\uc288\ubca0\ub974\ud2b8 \ub9c8\uc655 \u2014 \ud55c \uac00\uc218\uac00 \ub124 \uc0ac\ub78c\uc744 \ub178\ub798\ud560 \ub54c", "summary": "\uad34\ud14c\uc758 \uc2dc\uc5d0 \ubd99\uc778 \uac00\uace1\uc758 \uc904\uac70\ub9ac\uc640 \uac01 \uc778\ubb3c\uc758 \uc18c\ub9ac\ub97c \ub530\ub77c \ub4e3\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc74c\uc545", "categories": ["arts"], "url": "stories/schubert-erlking-four-voices/index.html", "image": "../media/schubert-erlking-four-voices.jpg", "alt": "\uc288\ubca0\ub974\ud2b8 \ub9c8\uc655\uc758 \uc81c2\ud310\uc744 \uc704\ud574 \uc81c\uc791\ub41c \uc61b \ud310\ud654. \ub9d0\uc744 \ud0c0\uace0 \ub2ec\ub9ac\ub294 \uc778\ubb3c\uacfc \uc8fc\uc704\uc758 \ud658\uc0c1\uc801 \ud615\uc0c1\uc774 \ud45c\ud604\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.", "text": "\uc288\ubca0\ub974\ud2b8 \ub9c8\uc655 \u2014 \ud55c \uac00\uc218\uac00 \ub124 \uc0ac\ub78c\uc744 \ub178\ub798\ud560 \ub54c \ub2ec\ub9ac\ub294 \ub9d0\uacfc \ub124 \ubaa9\uc18c\ub9ac, \ud53c\uc544\ub178\uac00 \ub9cc\ub4dc\ub294 \ub610 \ud558\ub098\uc758 \uc774\uc57c\uae30 \uad34\ud14c\uc758 \uc2dc\uc5d0 \ubd99\uc778 \uac00\uace1\uc758 \uc904\uac70\ub9ac\uc640 \uac01 \uc778\ubb3c\uc758 \uc18c\ub9ac\ub97c \ub530\ub77c \ub4e3\uc2b5\ub2c8\ub2e4. \uc74c\uc545 \ubb38\ud654\uc640 \uc608\uc220 \ubc24\uae38\uc744 \ub9d0\uc744 \ud0c0\uace0 \ub2ec\ub9ac\ub294 \uc544\ubc84\uc9c0\uac00 \uc788\ub2e4. \ud488 \uc548\uc758 \uc544\uc774\ub294 \ubb34\uc5b8\uac00\ub97c \ubcf4\uace0 \ub450\ub824\uc6cc\ud558\uace0, \uc544\ubc84\uc9c0\ub294 \uc544\uc774\ub97c \ub2ec\ub798\uba70 \uacc4\uc18d \ub098\uc544\uac04\ub2e4. \uc5ec\uae30\uc5d0 \ub204\uad70\uac00 \ub2ec\ucf64\ud55c \ub9d0\ub85c \uc544\uc774\ub97c \ubd80\ub978\ub2e4. \ub124 \uc0ac\ub78c\uc774 \uc11c\ub85c \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ub9d0\ud558\ub294 \uc774\uc57c\uae30\uc778\ub370, \ubb34\ub300\uc5d0\ub294 \uac00\uc218 \ud55c \uba85\uacfc \ud53c\uc544\ub2c8\uc2a4\ud2b8 \ud55c \uba85\uc774 \uc788\uc744 \uc218 \uc788\ub2e4. \uc288\ubca0\ub974\ud2b8\uc758 \uac00\uace1 \u3008\ub9c8\uc655\u3009\uc774\ub2e4. \uad34\ud14c\uc758 \uc2dc\uc5d0 \uc74c\uc545\uc744 \ubd99\uc778 \uc791\ud488\uc73c\ub85c, \ud655\uc778\ud55c \uc545\ubcf4\ub294 1815\ub144\uacfc D.328\uc774\ub77c\ub294 \ubc88\ud638\ub97c \uc81c\uc2dc\ud55c\ub2e4. \uc774 \uae00\uc5d0\ub294 \ub178\ub798\uc758 \ub9c8\uc9c0\ub9c9 \uc7a5\uba74\uae4c\uc9c0 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4. \ub3c5\uc77c\uc5b4 \uc81c\ubaa9\uc740 Erlk\u00f6nig\ub2e4. \uc288\ubca0\ub974\ud2b8\ub294 \uad34\ud14c\uc758 \uc2dc\uac00 \uac00\uc9c4 \uc774\uc57c\uae30\ub97c \uc131\uc545\uacfc \ud53c\uc544\ub178\uc758 \uc2dc\uac04\uc73c\ub85c \uc62e\uacbc\ub2e4. \ub178\ub798\uac00 \ub2e8\uc21c\ud788 \uc2dc\ub97c \uc608\uc05c \uba5c\ub85c\ub514\ub85c \uc77d\uc5b4 \uc8fc\ub294 \uac83\ub9cc\uc740 \uc544\ub2c8\ub2e4. \ub4f1\uc7a5\uc778\ubb3c\uc758 \ucc28\uc774\uc640 \uae34\ubc15\ud55c \uc9c4\ud589\uc744 \uc18c\ub9ac\uc758 \uad00\uacc4\ub85c \ub9cc\ub4e0\ub2e4. \ud55c\uad6d\uc5b4 \uc81c\ubaa9\uc758 \ub9c8\uc655\uc744 \ub4e3\uace0 \uc5b4\ub5a4 \uc885\uad50\uc758 \uc545\ub9c8\ub97c \uba3c\uc800 \ub5a0\uc62c\ub9b4 \uc218\ub3c4 \uc788\uc9c0\ub9cc, \uc5ec\uae30\uc11c\ub294 \uc544\uc774\ub97c \ubd80\ub974\ub294 \ucd08\uc6d4\uc801\uc778 \uc874\uc7ac\uac00 \uc2dc \uc18d\uc5d0\uc11c \uc5b4\ub5a4 \uc5ed\ud560\uc744 \ud558\ub294\uc9c0\ubd80\ud130 \ubcf4\uba74 \uc88b\ub2e4. \uc774\ub984\uc5d0 \uad00\ud55c \uc0c1\uc0c1\uc744 \ub113\ud788\uae30 \uc804\uc5d0, \ud55c \ud3b8\uc758 \uc774\uc57c\uae30 \uc548\uc5d0\uc11c \uc2e4\uc81c\ub85c \ubb34\uc2a8 \uc77c\uc774 \ubc8c\uc5b4\uc9c0\ub294\uc9c0 \ub530\ub77c\uac00\ub294 \uac83\uc774\ub2e4. \uccab\uba38\ub9ac\uc758 \ud53c\uc544\ub178\uc5d0\uc11c\ub294 \uc74c\ub4e4\uc774 \ucd18\ucd18\ud558\uac8c \ubc18\ubcf5\ub41c\ub2e4. \ub9d0\uc744 \ud0c0\uace0 \uae09\ud788 \ub2ec\ub9ac\ub294 \uc6c0\uc9c1\uc784\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uc18c\ub9ac\ub2e4. \uc131\uc545\uc774 \uc5c6\uc744 \ub54c\uc5d0\ub3c4 \uc774\ubbf8 \uc7a5\uba74\uc758 \uc18d\ub3c4\uc640 \uae34\uc7a5\uc774 \ud615\uc131\ub41c\ub2e4. \ubc18\uc8fc\ub77c\ub294 \ub9d0\ub9cc \ub4e3\uace0 \ub4a4\uc5d0 \uae54\ub9ac\ub294 \uc7a5\uc2dd\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \ub193\uce58\ub294 \ubd80\ubd84\uc774\ub2e4. \uac19\uc740 \uc74c\uc744 \ubc18\ubcf5\ud558\ub294 \uac83\uc740 \uc5f0\uc8fc\uc790\uc5d0\uac8c\ub3c4 \uc26c\uc6b4 \uc77c\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uacc4\uc18d \uc6c0\uc9c1\uc774\ub294 \ud798\uc744 \uc720\uc9c0\ud558\uba74\uc11c \ub178\ub798\uc640 \uc5b4\uc6b8\ub824\uc57c \ud55c\ub2e4. \ub4e3\ub294 \uc0ac\ub78c\uc740 \uae30\uc220\uc744 \ud3c9\uac00\ud558\ub824 \uc560\uc4f0\uc9c0 \uc54a\uace0, \uc774 \ubc18\ubcf5\uc774 \uba48\ucd94\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc5d0 \ubaa9\uc18c\ub9ac\ub4e4\uc774 \uc5b4\ub5a4 \uc0c1\ud669 \uc18d\uc5d0\uc11c \ub4e4\ub9ac\ub294\uc9c0 \ub290\uaef4 \ubcf4\uba74 \ub41c\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ud654\uc790\uac00 \ubc24\uae38\uc758 \uc7a5\uba74\uc744 \uc81c\uc2dc\ud55c\ub2e4. \ub204\uac00 \ub2ec\ub9ac\uace0 \ub204\uad6c\ub97c \uc548\uace0 \uc788\ub294\uc9c0 \uc54c\ub824 \uc8fc\uba70 \uccad\uc911\uc744 \uc774\uc57c\uae30 \uc548\uc73c\ub85c \ub4e4\uc778\ub2e4. \uac00\uc218\ub294 \uc774 \ubaa9\uc18c\ub9ac\uc5d0\uc11c \uc544\ubc84\uc9c0\uc640 \uc544\uc774\uc758 \ub9d0\ub85c \uace7 \uc62e\uaca8 \uac00\uc57c \ud55c\ub2e4. \uc5ec\ub7ec \ubc30\uc5ed\uc774 \ub098\ub204\uc5b4 \ub4f1\uc7a5\ud558\ub294 \uc5f0\uadf9\uacfc\ub294 \ub2e4\ub978 \ubc29\uc2dd\uc774\ub2e4. \uac00\uc0ac\ub97c \ubbf8\ub9ac \uc77d\uc5b4 \ub450\uba74 \uac00\uc218\uac00 \ubc14\ub00c\uc9c0 \uc54a\ub294\ub370\ub3c4 \uc5ed\ud560\uc774 \ub2ec\ub77c\uc9c0\ub294 \uc21c\uac04\uc744 \ub354 \uc27d\uac8c \ub4e3\uac8c \ub41c\ub2e4. \ub3c5\uc77c\uc5b4\ub97c \ubaa8\ub974\ub354\ub77c\ub3c4 \uba3c\uc800 \uc774\uc57c\uae30\uc758 \uc21c\uc11c\ub97c \uc54c\uace0 \ub4e3\ub294 \uac83\uc774 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uc74c \ud558\ub098\ub9c8\ub2e4 \ubc88\uc5ed\uc744 \ubd99\uc774\ub824 \ud558\uae30\ubcf4\ub2e4 \uc9c0\uae08 \ub204\uad6c\uc758 \ub9d0\uc778\uac00\ub97c \ucc3e\uc544\ubcf4\ub294 \uac83\uc774\ub2e4. \uc544\uc774\uc5d0\uac8c\ub294 \ub450\ub824\uc6b4 \uc874\uc7ac\uac00 \ubcf4\uc778\ub2e4. \uc544\ubc84\uc9c0\ub294 \uc548\uac1c\ub098 \ubc14\ub78c, \uc790\uc5f0\uc758 \ubaa8\uc2b5\uc73c\ub85c \uc124\uba85\ud558\uba70 \uc9c4\uc815\uc2dc\ud0a4\ub824 \ud55c\ub2e4. \ub450 \uc0ac\ub78c\uc740 \uac19\uc740 \uae38\uc744 \uac00\uc9c0\ub9cc \uac19\uc740 \uc138\uacc4\ub97c \uacbd\ud5d8\ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub2e4. \uc774 \ucc28\uc774\uac00 \ub300\ud654\ub97c \uacc4\uc18d \uc6c0\uc9c1\uc778\ub2e4. \uc544\ubc84\uc9c0\uc758 \ucc28\ubd84\ud558\uac8c \ub2ec\ub798\ub294 \uc18c\ub9ac\uc640 \uc544\uc774\uc758 \ubd88\uc548\ud55c \uc678\uce68\uc744 \ube44\uad50\ud574 \ubcf4\uc790. \ud55c \uac00\uc218\uac00 \ub192\uc774\uc640 \ud798, \ub9d0\ud22c\ub97c \ubc14\uafb8\uba70 \ub450 \uc0ac\ub78c\uc744 \uad6c\ubd84\ud55c\ub2e4. \uc544\ubc84\uc9c0\uac00 \uc544\uc774\ub97c \uc0ac\ub791\ud558\uc9c0 \uc54a\uc544 \uc774\ud574\ud558\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uace7\ubc14\ub85c \ud310\ub2e8\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub3cc\ubcf4\ub824\ub294 \ub9c8\uc74c\uacfc \uc0c1\ub300\uac00 \ub290\ub07c\ub294 \uacf5\ud3ec\uac00 \uaf2d \uac19\uc740 \uc124\uba85\uc73c\ub85c \ub9cc\ub098\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc544\uc774\ub97c \ubd80\ub974\ub294 \uc874\uc7ac\ub294 \ucc98\uc74c\ubd80\ud130 \ud070 \uc18c\ub9ac\ub85c \uc704\ud611\ud558\uae30\ub9cc \ud558\uc9c0 \uc54a\ub294\ub2e4. \ub354 \ubd80\ub4dc\ub7fd\uace0 \ub9e4\ub825\uc801\uc73c\ub85c \ub4e4\ub9ac\ub294 \ub9d0\ub85c \uc720\ud639\ud55c\ub2e4. \ubc14\uae65\uc758 \uae34\ubc15\ud55c \ud53c\uc544\ub178\uc640 \ub2e4\ub978 \uc131\uaca9\uc758 \ub178\ub798\uac00 \uc7a0\uc2dc \uacb9\uce58\uba74 \uc74c\uc545\uc758 \ubd88\ud3b8\ud568\uc740 \uc624\ud788\ub824 \ucee4\uc9c8 \uc218 \uc788\ub2e4. \ubb34\uc11c\uc6b4 \uc7a5\uba74\uc740 \ubc18\ub4dc\uc2dc \uac70\uce60\uace0 \uc2dc\ub044\ub7ec\uc6b4 \uc18c\ub9ac\ub85c\ub9cc \ub9cc\ub4e4\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc774 \ud765\ubbf8\ub86d\ub2e4. \ub2e4\uc815\ud55c \ub9d0\ud22c\uac00 \uc5b4\ub5a4 \uc0c1\ud669\uc5d0\uc11c \ub098\uc624\uace0 \ub204\uad6c\ub97c \ud5a5\ud558\ub294\uc9c0\uc5d0 \ub530\ub77c \uc758\ubbf8\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \ud55c \uace1 \uc548\uc5d0\uc11c \uc18c\ub9ac\uc758 \uc544\ub984\ub2e4\uc6c0\uacfc \uc774\uc57c\uae30\uc758 \uc704\ud5d8\uc774 \uac19\uc740 \ubc29\ud5a5\uc73c\ub85c\ub9cc \uc6c0\uc9c1\uc774\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc544\uc774\ub294 \uc544\ubc84\uc9c0\ub97c \ubd80\ub974\uba70 \uc790\uc2e0\uc774 \uacaa\ub294 \uc77c\uc744 \uc54c\ub9ac\ub824 \ud55c\ub2e4. \uadf8 \ud638\uc18c\uac00 \ubc18\ubcf5\ub420\uc218\ub85d \uccad\uc911\uc740 \uac19\uc740 \ub300\ub2f5\ub9cc\uc73c\ub85c\ub294 \uc0c1\ud669\uc774 \ud480\ub9ac\uc9c0 \uc54a\ub294\ub2e4\ub294 \uac83\uc744 \ub290\ub080\ub2e4. \uc55e\uc11c \ub4e4\uc5c8\ub358 \uc720\ud639\uc758 \ubd80\ub4dc\ub7ec\uc6c0\uacfc \uc544\uc774\uc758 \uc678\uce68\uc744 \uae30\uc5b5\ud574 \ub450\uba74 \uc778\ubb3c\ub4e4\uc758 \ucc28\uc774\uac00 \ub354 \ub69c\ub837\ud574\uc9c4\ub2e4. \uc5ec\uae30\uc11c \uc6d0\uc778\uc744 \ud558\ub098\uc758 \uc9c4\ub2e8\uc73c\ub85c \ud655\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc2dc\uc640 \uac00\uace1\uc740 \uc544\uc774\uac00 \ubb34\uc5c7\uc744 \ubcf4\uace0 \uc544\ubc84\uc9c0\uac00 \uc5b4\ub5bb\uac8c \ubc18\uc751\ud558\ub294\uc9c0 \ubcf4\uc5ec \uc900\ub2e4. \uc791\ud488 \ubc16\uc758 \ubcd1\uba85\uc774\ub098 \ucd08\uc790\uc5f0\uc801 \uc0ac\uc2e4\uc744 \uc99d\uba85\ud558\ub294 \uae30\ub85d\uc73c\ub85c \uc77d\uae30\ubcf4\ub2e4, \uc11c\ub85c \ub2e4\ub978 \uacbd\ud5d8\uc774 \ub05d\ub0b4 \ub9cc\ub098\uc9c0 \ubabb\ud558\ub294 \uc7a5\uba74\uc73c\ub85c \ub4e4\uc744 \uc218 \uc788\ub2e4. \uc544\ubc84\uc9c0\ub294 \uc544\uc774\ub97c \uc548\uace0 \ubaa9\uc801\uc9c0\uc5d0 \ub3c4\ucc29\ud558\uc9c0\ub9cc \uc544\uc774\ub294 \uc774\ubbf8 \uc8fd\uc5b4 \uc788\ub2e4. \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \uc55e\uc11c \ub2ec\ub9ac\ub358 \ud750\ub984\uacfc \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uc0ac\uc2e4\uc774 \uc804\ub2ec\ub41c\ub2e4. \ud53c\uc544\ub178\uc640 \ubaa9\uc18c\ub9ac\uac00 \ub9cc\ub4e4\uc5b4 \uc628 \uae34\ubc15\ud568\uc744 \uae30\uc5b5\ud558\uae30 \ub54c\ubb38\uc5d0 \uadf8 \uba48\ucda4\uc740 \ub354 \ud06c\uac8c \ub4e4\ub9b4 \uc218 \uc788\ub2e4. \uc774 \uacb0\ub9d0\uc744 \ub180\ub77c\uc6b4 \ubc18\uc804\uc73c\ub85c\ub9cc \uae30\ub2e4\ub9ac\uae30\ubcf4\ub2e4 \uadf8\uc804\uc758 \ubaa8\ub4e0 \ub9d0\uc774 \uc5b4\ub5a4 \uad00\uacc4\uc5d0 \uc788\uc5c8\ub294\uc9c0 \ub3cc\uc544\ubcf4\uba74 \uc88b\ub2e4. \ub2ec\ub798\ub294 \ub9d0, \uc720\ud639\ud558\ub294 \ub9d0, \ub3c4\uc6c0\uc744 \uad6c\ud558\ub294 \ub9d0\uc774 \uac19\uc740 \uc2dc\uac04\uc5d0 \uc774\uc5b4\uc84c\uc9c0\ub9cc \uacb0\uacfc\ub294 \ub9c9\uc9c0 \ubabb\ud588\ub2e4. \uac00\uace1\uc740 \uc9e7\uc740 \ubd84\ub7c9 \uc548\uc5d0 \uadf8 \uc5b4\uae0b\ub0a8\uc744 \uc751\ucd95\ud55c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \ub9c8\uc655\uc758 \uc81c2\ud310\uc744 \uc704\ud574 \uc81c\uc791\ub41c \ud504\ub780\uce20 \ubc14\uc774\uae00\uc758 \uc5ed\uc0ac\uc801 \ud310\ud654\uac00 \uc804\uae30\uc5d0 \uc7ac\uc218\ub85d\ub41c \uc790\ub8cc\ub2e4. \ub9d0\uc744 \ud0c4 \uc778\ubb3c\uacfc \ud658\uc0c1\uc801 \ud615\uc0c1\uc744 \ud45c\ud604\ud55c \ucd9c\ud310 \uc0bd\ud654\uc774\uba70, \uc288\ubca0\ub974\ud2b8\uac00 \ubaa9\uaca9\ud55c \uc2e4\uc81c \uc0ac\uac74\uc758 \uadf8\ub9bc\uc740 \uc544\ub2c8\ub2e4. \ub178\ub798\uac00 \ub2e4\ub8e8\ub294 \ubc24\uae38\uc758 \ubd84\uc704\uae30\ub85c \ub4e4\uc5b4\uac00\ub294 \ubb38\uc73c\ub85c \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc904\uac70\ub9ac\ub97c \uc54c\uace0 \ud3b8\ud558\uac8c \ub4e3\uace0, \ub2e4\uc74c\uc5d0\ub294 \ud654\uc790\uc640 \uc544\ubc84\uc9c0, \uc544\uc774\uc640 \ub9c8\uc655\uc744 \ub098\ub204\uc5b4 \ucc3e\uc544\ubcf4\uc790. \ub9c8\uc9c0\ub9c9\uc73c\ub85c \ud53c\uc544\ub178\ub9cc \uadc0\ub85c \ub530\ub77c\uac00 \ubcf4\uba74 \ud55c \ubc88 \ub354 \ub2e4\ub978 \uace1\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ud55c \uac00\uc218\uc758 \ub124 \ubaa9\uc18c\ub9ac \uacc1\uc5d0\uc11c \ud53c\uc544\ub178 \uc5ed\uc2dc \uc774\uc57c\uae30\ub97c \ub9d0\ud558\uace0 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub4e4\ub9ac\uae30 \uc2dc\uc791\ud55c\ub2e4."}, {"id": "schubert-trout-clear-water", "title": "\uc288\ubca0\ub974\ud2b8 \uc1a1\uc5b4 \u2014 \ub9d1\uc740 \ubb3c\uc740 \uc65c \ud750\ub824\uc84c\uc744\uae4c", "summary": "\uac00\uace1 D.550\uc758 \uc138 \uc5f0\uacfc \ubc18\uc8fc\ub97c \ub530\ub77c\uac00\uba70 \ubb3c\uace0\uae30\ub97c \ubc14\ub77c\ubcf4\ub358 \ud654\uc790\uc758 \uac10\uc815 \ubcc0\ud654\ub97c \ub4e3\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc74c\uc545", "categories": ["arts"], "url": "stories/schubert-trout-clear-water/index.html", "image": "../media/schubert-trout-clear-water.png", "alt": "\ub9d1\uc740 \uc2dc\ub0c7\ubb3c\uc5d0\uc11c \uc1a1\uc5b4\uac00 \ud5e4\uc5c4\uce58\uace0 \uba3c \uac15\uac00\uc5d0 \uc791\uc740 \uc0ac\ub78c\uc774 \uc11c \uc788\ub294 \uc0c1\uc0c1 \ud48d\uacbd.", "text": "\uc288\ubca0\ub974\ud2b8 \uc1a1\uc5b4 \u2014 \ub9d1\uc740 \ubb3c\uc740 \uc65c \ud750\ub824\uc84c\uc744\uae4c \uac00\ubcbc\uc6b4 \ud53c\uc544\ub178 \ubc18\uc8fc \ub4a4\uc5d0\uc11c \ub2ec\ub77c\uc9c0\ub294 \uc9e7\uc740 \uc774\uc57c\uae30 \uac00\uace1 D.550\uc758 \uc138 \uc5f0\uacfc \ubc18\uc8fc\ub97c \ub530\ub77c\uac00\uba70 \ubb3c\uace0\uae30\ub97c \ubc14\ub77c\ubcf4\ub358 \ud654\uc790\uc758 \uac10\uc815 \ubcc0\ud654\ub97c \ub4e3\uc2b5\ub2c8\ub2e4. \uc74c\uc545 \ubb38\ud654\uc640 \uc608\uc220 \ud53c\uc544\ub178\uac00 \uac00\ubccd\uac8c \uc6c0\uc9c1\uc774\uba74 \ubb3c\uc774 \ubc18\uc9dd\uc774\ub294 \uac83 \uac19\ub2e4. \uadf8 \uc704\ub85c \ub204\uad70\uac00\uac00 \ub9d1\uc740 \uc2dc\ub0c7\ubb3c\uc5d0\uc11c \ud5e4\uc5c4\uce58\ub294 \uc1a1\uc5b4\ub97c \ub178\ub798\ud55c\ub2e4. \uc288\ubca0\ub974\ud2b8\uc758 \uac00\uace1 \u3008\uc1a1\uc5b4\u3009\ub294 \ucc98\uc74c \uba87 \ub9c8\ub514\ub9cc \ub4e4\uc73c\uba74 \uae30\ubd84 \uc88b\uc740 \uc790\uc5f0\uc758 \uc18c\ud488\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uadf8\ub7ec\ub098 \uac00\uc0ac\ub97c \ub530\ub77c\uac00\uba74 \ubb3c\uc758 \ube5b\uacfc \ud568\uaed8 \uc774\uc57c\uae30\uc758 \ud45c\uc815\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc5ec\uae30\uc11c \ub2e4\ub8e8\ub294 \uc791\ud488\uc740 \ubaa9\uc18c\ub9ac\uc640 \ud53c\uc544\ub178\ub97c \uc704\ud55c \uac00\uace1 D.550, \ub3c5\uc77c\uc5b4 \uc81c\ubaa9\uc73c\ub85c \u3008Die Forelle\u3009\ub2e4. \uc545\ubcf4\uc5d0 \uc2e4\ub9b0 \uc2dc\uc758 \uc138 \uc5f0\uc744 \ucc28\ub840\ub85c \uc0b4\ud3b4\ubcf4\uc790. \uc74c\uc545\uc744 \uc77d\uc9c0 \ubabb\ud574\ub3c4 \ub204\uac00 \ubb34\uc5c7\uc744 \ubcf4\uace0 \uc788\ub294\uc9c0 \uc54c\uba74 \uadc0\uac00 \uba38\ubb34\ub294 \uc790\ub9ac\uac00 \ub298\uc5b4\ub09c\ub2e4. Forelle\ub294 \uc1a1\uc5b4\ub97c \ub73b\ud55c\ub2e4. \uac00\uc0ac\uc758 \ubc14\ud0d5\uc740 \ud06c\ub9ac\uc2a4\ud2f0\uc548 \ud504\ub9ac\ub4dc\ub9ac\ud788 \ub2e4\ub2c8\uc5d8 \uc288\ubc14\ub974\ud2b8\uc758 \uc2dc\ub2e4. \uc288\ubca0\ub974\ud2b8\uac00 \uc2dc\uc758 \ub9d0\uc744 \uc74c\uc545\uc73c\ub85c \uc62e\uacbc\ub2e4\ub294 \uc810\uc744 \uc54c\uba74 \uace1\uc744 \ub530\ub77c\uac00\ub294 \uc77c\uc774 \uc870\uae08 \uc26c\uc6cc\uc9c4\ub2e4. \uc74c\uc545 \ubc16\uc758 \uc774\uc57c\uae30\ub97c \uc5b5\uc9c0\ub85c \ub9cc\ub4e4\uc5b4 \ubd99\uc77c \ud544\uc694 \uc5c6\uc774 \uc774\ubbf8 \ub178\ub7ab\ub9d0 \uc548\uc5d0 \uc0ac\uac74\uc774 \uc788\ub2e4. \uc81c\ubaa9\ub9cc \ubcf4\uace0 \uc1a1\uc5b4 \uc790\uc2e0\uc774 \ubd80\ub974\ub294 \ub178\ub798\ub77c\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\uc9c0\ub9cc \ud654\uc790\ub294 \uac15\uac00\uc5d0\uc11c \uadf8 \ubb3c\uace0\uae30\ub97c \uc9c0\ucf1c\ubcf4\ub294 \uc0ac\ub78c\uc774\ub2e4. \ubb3c\uc758 \uc0c1\ud0dc\ub97c \ubcf4\uace0 \ub09a\uc2dc\uafbc\uc758 \ud589\ub3d9\uc744 \ud310\ub2e8\ud558\uba70 \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \uc18d\uc784\uc218\ub97c \ub2f9\ud55c \ubb3c\uace0\uae30\ub97c \ubc14\ub77c\ubcf8\ub2e4. \ud48d\uacbd\uc740 \uc774 \uad00\ucc30\uc790\uc758 \uac10\uc815\uc744 \uac70\uccd0 \uc6b0\ub9ac\uc5d0\uac8c \uc804\ud574\uc9c4\ub2e4. \ub178\ub798\uac00 \ub098\uc624\uae30 \uc804\ubd80\ud130 \ud53c\uc544\ub178\uc5d0\ub294 \uc791\uace0 \ube60\ub978 \uc74c\uc758 \uc6c0\uc9c1\uc784\uc774 \uc788\ub2e4. \ubb3c\uacb0\uc774\ub098 \ubb3c\uace0\uae30\uc758 \ub0a0\ub835\ud568\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc88b\uc740 \ubc18\uc8fc\ub2e4. \uc2e4\uc81c \uc2dc\ub0c7\ubb3c\uc758 \uc18c\ub9ac\ub97c \ub179\uc74c\ud55c \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc, \ubc18\ubcf5\ub418\ub294 \uc6c0\uc9c1\uc784\uacfc \uac00\ubcbc\uc6b4 \ub9ac\ub4ec\uc774 \ub4e3\ub294 \uc0ac\ub78c\uc758 \uc0c1\uc0c1\uc744 \ub3d5\ub294\ub2e4. \uc774\ub54c \uc120\uc728\ub9cc \uae30\ub2e4\ub9ac\uc9c0 \ub9d0\uace0 \ubc18\uc8fc\uc758 \ubaa8\uc591\uc744 \uc7a0\uc2dc \ub4e4\uc5b4 \ubcf4\uc790. \ubaa9\uc18c\ub9ac\uac00 \ub098\ud0c0\ub09c \ub4a4\uc5d0\ub3c4 \uc544\ub798\uc5d0\uc11c \uc5b4\ub5a4 \uc6c0\uc9c1\uc784\uc774 \uc774\uc5b4\uc9c0\ub294\uc9c0 \uc54c\uba74 \ud53c\uc544\ub178\uac00 \ub2e8\uc21c\ud788 \uc74c\uc815\uc744 \ub9de\ucdb0 \uc8fc\ub294 \ubc30\uacbd\uc774 \uc544\ub2c8\ub77c\ub294 \uc810\uc774 \ubcf4\uc778\ub2e4. \ub178\ub798\uc640 \ubc18\uc8fc\ub294 \uac19\uc740 \uc7a5\uba74\uc744 \uc11c\ub85c \ub2e4\ub978 \ubc29\ubc95\uc73c\ub85c \ub4e4\ub824\uc900\ub2e4. \uccab \uc5f0\uc5d0\uc11c \uc1a1\uc5b4\ub294 \ub9d1\uc740 \uc2dc\ub0c7\ubb3c \uc18d\uc744 \ud654\uc0b4\ucc98\ub7fc \uc7ac\ube60\ub974\uac8c \uc6c0\uc9c1\uc778\ub2e4. \uac15\uac00\uc758 \ud654\uc790\ub294 \uadf8 \ubaa8\uc2b5\uc744 \uc990\uac81\uace0 \ud3c9\uc628\ud558\uac8c \ubc14\ub77c\ubcf8\ub2e4. \uc544\uc9c1\uc740 \ubd99\uc7a1\ud790 \uc704\ud5d8\ubcf4\ub2e4 \uc6c0\uc9c1\uc774\ub294 \uc0dd\uba85\uc744 \uc9c0\ucf1c\ubcf4\ub294 \uae30\uc068\uc774 \uc55e\uc5d0 \uc788\ub2e4. \uc9e7\uc740 \ub9d0\ub4e4 \uc548\uc5d0 \ubb3c\uace0\uae30\uc640 \uad00\ucc30\uc790\uc758 \uc790\ub9ac\uac00 \ud568\uaed8 \ub193\uc778\ub2e4. \ub178\ub798\uac00 \uac00\ubccd\uac8c \uc774\uc5b4\uc9c0\ub294 \ub290\ub08c\uacfc \ubc18\uc8fc\uc758 \uc6c0\uc9c1\uc784\uc744 \ud568\uaed8 \ub4e4\uc5b4 \ubcf4\uc790. \ubb3c\uace0\uae30\uc758 \uc18d\ub3c4\uc640 \ubcf4\ub294 \uc0ac\ub78c\uc758 \ub290\uae0b\ud568\uc774 \ud55c \uc7a5\uba74 \uc548\uc5d0 \uc788\ub2e4. \uc74c\uc545\uc758 \ubaa8\ub4e0 \uc74c\uc744 \ubb3c\ubc29\uc6b8 \ud558\ub098\uc5d0 \ub9de\ucd9c \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5b4\ub5a4 \uc6c0\uc9c1\uc784\uc774 \uacc4\uc18d\ub418\uace0 \ubb34\uc5c7\uc774 \uadf8 \uc704\uc5d0\uc11c \ub178\ub798\ud558\ub294\uc9c0 \ub290\ub07c\uba74 \ucda9\ubd84\ud558\ub2e4. \ub2e4\uc74c\uc5d0\ub294 \ub09a\uc2ef\ub300\ub97c \ub4e0 \uc0ac\ub78c\uc774 \uac15\uac00\uc5d0 \uc11c \uc788\ub2e4. \ud654\uc790\ub294 \ubb3c\uc774 \ub9d1\uc740 \ub3d9\uc548\uc5d0\ub294 \uc1a1\uc5b4\uac00 \uc27d\uac8c \ub09a\uc774\uc9c0 \uc54a\uc744 \uac83\uc774\ub77c\uace0 \uc0dd\uac01\ud55c\ub2e4. \uac19\uc740 \ub9d1\uc74c\uc774 \ucc98\uc74c\uc5d0\ub294 \uc544\ub984\ub2e4\uc6b4 \ud48d\uacbd\uc774\uc5c8\uc9c0\ub9cc \uc774\uc81c\ub294 \ubb3c\uace0\uae30\ub97c \uc9c0\ucf1c \uc8fc\ub294 \uc870\uac74\uc73c\ub85c \ubc14\ub010\ub2e4. \ucc98\uc74c\uacfc \ube44\uc2b7\ud55c \uc74c\uc545\uc744 \ub2e4\uc2dc \ub4e3\ub354\ub77c\ub3c4 \ub73b\uc774 \uc644\uc804\ud788 \uac19\uc9c0\ub294 \uc54a\ub2e4. \ub3c5\uc790\ub294 \uc774\ubbf8 \ub09a\uc2dc\uafbc\uc744 \ubcf4\uc558\ub2e4. \ubc30\uacbd\uc5d0\uc11c \uc791\uc740 \uc704\ud611\uc774 \uc0dd\uacbc\ub294\ub370 \uc775\uc219\ud55c \uc6c0\uc9c1\uc784\uc740 \uacc4\uc18d\ub41c\ub2e4. \ubc18\ubcf5\uc740 \uc0ac\uac74\uc774 \uc5c6\ub294 \uc0c1\ud0dc\uac00 \uc544\ub2c8\ub77c \uac19\uc740 \ud48d\uacbd\uc744 \uc0c8 \uc815\ubcf4\uc640 \ud568\uaed8 \ub2e4\uc2dc \ubcf4\ub294 \uc2dc\uac04\uc774 \ub420 \uc218 \uc788\ub2e4. \ub09a\uc2dc\uafbc\uc740 \uae30\ub2e4\ub9bc\uc774 \uae38\uc5b4\uc9c0\uc790 \ubb3c\uc744 \uc77c\ubd80\ub7ec \ud750\ub9b0\ub2e4. \ub9d1\uc740 \ubb3c\uc5d0\uc11c \uc790\uc720\ub86d\uac8c \uc6c0\uc9c1\uc774\ub358 \uc1a1\uc5b4\ub294 \ub2ec\ub77c\uc9c4 \uc870\uac74\uc5d0\uc11c \uc7a1\ud78c\ub2e4. \ud654\uc790\ub294 \uc18d\uc784\uc218\ub97c \ub2f9\ud55c \ubb3c\uace0\uae30\ub97c \ubcf4\uace0 \ub9c8\uc74c\uc774 \uaca9\ud574\uc9c4\ub2e4. \uac00\uc0ac\ub294 \ud55c\uac00\ud55c \uad00\ucc30\uc5d0\uc11c \ub204\uad70\uac00\uc758 \ud589\ub3d9\uc744 \ud310\ub2e8\ud558\ub294 \ub9d0\ub85c \uc774\ub3d9\ud55c\ub2e4. \uadf8 \ubcc0\ud654\uc5d0 \ub9de\ucd94\uc5b4 \uc74c\uc545\ub3c4 \ucc98\uc74c\uc758 \uac00\ubcbc\uc6c0\ub9cc \uc720\uc9c0\ud558\uc9c0 \uc54a\ub294\ub2e4. \ubc18\uc8fc\uc640 \ub178\ub798\uc758 \ud798, \ub9d0\uc774 \ub193\uc774\ub294 \ub9ac\ub4ec\uc5d0\uc11c \uae34\uc7a5\uc774 \ucee4\uc9c0\ub294 \ubd80\ubd84\uc744 \ub4e4\uc5b4 \ubcf4\uc790. \ub2e8\uc21c\ud788 \ube60\ub974\uac70\ub098 \ub290\ub9b0\uc9c0\ub97c \ub118\uc5b4 \uac19\uc740 \ubaa9\uc18c\ub9ac\uac00 \uc5b4\ub5a4 \uc0c1\ud669\uc5d0\uc11c \ub2e4\ub978 \ubb34\uac8c\ub97c \uac16\uac8c \ub418\ub294\uc9c0 \ub290\ub084 \uc218 \uc788\ub2e4. \uc775\uc219\ud55c \ubc18\uc8fc\uc758 \uc6c0\uc9c1\uc784\uc774 \ub2e4\uc2dc \ub4e4\ub9b4 \ub54c \ucc98\uc74c\uc758 \ud3c9\uc628\uc774 \ubaa8\ub450 \ubcf5\uc6d0\ub418\uc5c8\ub2e4\uace0 \ub290\uaef4\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub4e3\ub294 \uc0ac\ub78c\uc740 \uc774\ubbf8 \uc1a1\uc5b4\uac00 \uc7a1\ud78c \uc77c\uc744 \uc548\ub2e4. \uc55e\uc5d0\uc11c \uc990\uac70\uc6e0\ub358 \uc6c0\uc9c1\uc784\uc744 \ub2e4\uc2dc \ub9cc\ub098\ub3c4 \uac00\uc0ac\uc758 \uae30\uc5b5\uc774 \uadf8 \uc18c\ub9ac\ub97c \ub2ec\ub9ac \ub4e3\uac8c \ud560 \uc218 \uc788\ub2e4. \uc9e7\uc740 \uac00\uace1\uc5d0\uc11c \uc74c\uc545\uacfc \ub9d0\uc774 \ud568\uaed8 \ub9cc\ub4dc\ub294 \ud6a8\uacfc\ub2e4. \uae30\uc545 \ubc18\uc8fc\ub9cc \ub4e4\uc744 \ub54c\uc640 \uac00\uc0ac\ub97c \uc54c\uace0 \ub4e4\uc744 \ub54c\uc758 \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc5b4\ub290 \ucabd\uc774 \uc720\uc77c\ud558\uac8c \uc633\ub2e4\uae30\ubcf4\ub2e4, \ubb34\uc5c7\uc744 \ub4e3\uace0 \uc788\uc5c8\ub294\uc9c0 \uc54c\uc544\ucc28\ub9ac\ub294 \uacfc\uc815\uc5d0 \uac00\uae5d\ub2e4. \ud55c \uace1 \uc548\uc5d0\ub3c4 \uc5ec\ub7ec \ubc88 \uc0c8\ub86d\uac8c \ub4e4\uc5b4\uac08 \uae38\uc774 \uc788\ub2e4. \uc774 \ub178\ub798\ub97c \uace7\ubc14\ub85c \ud558\ub098\uc758 \uc815\uce58\uc801 \uc0ac\uac74\uc774\ub098 \uc791\uace1\uac00\uc758 \ube44\ubc00 \uacbd\ud5d8\uacfc \ub300\uc751\uc2dc\ud0ac \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774\ubc88\uc5d0 \ud655\uc778\ud55c \uadfc\uac70\ub294 \uc545\ubcf4\uc640 \uac70\uae30\uc5d0 \uc2e4\ub9b0 \uac00\uc0ac\ub2e4. \ubd84\uba85\ud788 \uc77d\uc744 \uc218 \uc788\ub294 \uac83\uc740 \ubb3c\uc758 \uc870\uac74\uc744 \ubc14\uafbc \uc0ac\ub78c\uc758 \ud589\ub3d9\uacfc \uadf8 \uacb0\uacfc\ub97c \ubcf8 \ud654\uc790\uc758 \ubc18\uc751\uc774\ub2e4. \uc5ec\uae30\uc11c \uc790\uc5f0\uc758 \ud48d\uacbd\uacfc \uc778\uac04\uc758 \uc120\ud0dd\uc774 \ub9cc\ub09c\ub2e4. \uc790\uc720\ub86d\uac8c \uc6c0\uc9c1\uc774\ub358 \uc874\uc7ac\ub97c \uc7a1\uae30 \uc704\ud574 \ud658\uacbd\uc744 \ubc14\uafb8\ub294 \uc77c\uc740 \ub2e8\uc21c\ud55c \ud48d\uacbd \ubb18\uc0ac\ubcf4\ub2e4 \ub0a0\uce74\ub86d\ub2e4. \ubc1d\uc740 \uc74c\uc545\uc774\ub77c\uace0 \ud574\uc11c \uadf8 \uc548\uc758 \uc774\uc57c\uae30\ub3c4 \ub05d\uae4c\uc9c0 \uc544\ubb34 \uac71\uc815\uc774 \uc5c6\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc744 \uae30\uc5b5\ud560 \uc218 \uc788\ub2e4. \ud55c \ubc88\uc740 \ud53c\uc544\ub178\uc758 \uc6c0\uc9c1\uc784\uc744, \ub2e4\uc74c\uc5d0\ub294 \uccab \uc5f0\uacfc \ub458\uc9f8 \uc5f0\uc758 \ube44\uc2b7\ud55c \ud750\ub984\uc744, \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \ubb3c\uc744 \ud750\ub9ac\ub294 \uc14b\uc9f8 \uc5f0\uc758 \ubcc0\ud654\ub97c \ub530\ub77c\uac00 \ubcf4\uc790. \uc131\uc545\uac00\uac00 \ub3c5\uc77c\uc5b4\uc758 \ub9d0\uc744 \uc5b4\ub5bb\uac8c \uac15\uc870\ud558\ub294\uc9c0 \ubab0\ub77c\ub3c4 \ubaa9\uc18c\ub9ac\uc758 \ud798\uacfc \ubc18\uc8fc\uc758 \ucc28\uc774\ub294 \ub290\ub084 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \ub9d1\uc740 \ubb3c\uc5d0\uc11c \ud5e4\uc5c4\uce58\ub294 \uc1a1\uc5b4\ub97c \uc0c1\uc0c1\ud55c AI \uc0bd\ud654\ub2e4. \uc2e4\uc81c \uc791\uace1 \uc7a5\uc18c\ub098 \uace1\uc758 \uc545\ubcf4\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uadf8\ub9bc\uc758 \ud3c9\uc628\ud568\uc744 \uc785\uad6c\ub85c \uc0bc\uace0 \uac00\uc0ac\uac00 \uc5b4\ub514\ub85c \uc6c0\uc9c1\uc774\ub294\uc9c0 \ub05d\uae4c\uc9c0 \ub4e4\uc5b4 \ubcf4\uba74, \uc775\uc219\ud55c \uc81c\ubaa9 \uc548\uc5d0\uc11c \uc0dd\uac01\ubcf4\ub2e4 \ub610\ub837\ud55c \uc9e7\uc740 \ub4dc\ub77c\ub9c8\ub97c \ub9cc\ub0a0 \uc218 \uc788\ub2e4."}, {"id": "schumann-traumerei-memory", "title": "\ud2b8\ub85c\uc774\uba54\ub77c\uc774 \u2014 \uc9e7\uc740 \ud53c\uc544\ub178\uace1\uc774 \uc624\ub798\ub41c \uae30\uc5b5\ucc98\ub7fc \ub4e4\ub9b4 \ub54c", "summary": "\uc81c\ubaa9\uc758 \ub73b\uacfc \uc120\uc728\uc758 \ud638\ud761, \ubaa8\uc74c\uace1 \uc548\uc758 \uc790\ub9ac\ub97c \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc74c\uc545", "categories": ["arts"], "url": "stories/schumann-traumerei-memory/index.html", "image": "../media/schumann-traumerei-memory.png", "alt": "\ud53c\uc544\ub178\uc640 \ucc3d\uac00\uc758 \uc791\uc740 \uc7a5\ub09c\uac10, \uc815\uc6d0\uc744 \ubc14\ub77c\ubcf4\ub294 \uc778\ubb3c\uc744 \uadf8\ub9b0 \ubabd\uc0c1\uc758 \ubd84\uc704\uae30 \uc0bd\ud654.", "text": "\ud2b8\ub85c\uc774\uba54\ub77c\uc774 \u2014 \uc9e7\uc740 \ud53c\uc544\ub178\uace1\uc774 \uc624\ub798\ub41c \uae30\uc5b5\ucc98\ub7fc \ub4e4\ub9b4 \ub54c \uc288\ub9cc \uc5b4\ub9b0\uc774 \uc815\uacbd\uc758 \uc77c\uacf1 \ubc88\uc9f8 \uace1\uc744 \ucc9c\ucc9c\ud788 \ub4e3\uae30 \uc81c\ubaa9\uc758 \ub73b\uacfc \uc120\uc728\uc758 \ud638\ud761, \ubaa8\uc74c\uace1 \uc548\uc758 \uc790\ub9ac\ub97c \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc74c\uc545 \ubb38\ud654\uc640 \uc608\uc220 \ucc98\uc74c\ubd80\ud130 \ub05d\uae4c\uc9c0 \uae38\uac8c \uc18c\ub9ac\uce58\uc9c0 \uc54a\ub294 \uc74c\uc545\uc774 \uc788\ub2e4. \ub204\uad70\uac00 \uc870\uc6a9\ud788 \ub9d0\uc744 \uaebc\ub0b4\uace0 \uc7a0\uc2dc \uc0dd\uac01\ud558\ub2e4\uac00 \ub2e4\uc2dc \uc787\ub294 \uac83\ucc98\ub7fc \ub4e4\ub9b0\ub2e4. \uc288\ub9cc\uc758 \u3008\ud2b8\ub85c\uc774\uba54\ub77c\uc774\u3009\ub294 \uc9e7\uc740 \ud53c\uc544\ub178\uace1\uc774\uc9c0\ub9cc \uc5b4\ub5a4 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc624\ub798\ub41c \uae30\uc5b5\uc758 \uae38\uc774\ub97c \uac00\uc9c4 \uc74c\uc545\uc73c\ub85c \ub0a8\ub294\ub2e4. \ub3c5\uc77c\uc5b4 \uc81c\ubaa9 Tr\u00e4umerei\ub294 \uafc8\uafb8\uae30, \ubabd\uc0c1\uc774\ub77c\ub294 \ub73b\uc73c\ub85c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ud2b9\uc815\ud55c \uafc8\uc758 \ub0b4\uc6a9\uc744 \uc124\uba85\ud558\ub294 \uc81c\ubaa9\uc774\ub77c\uae30\ubcf4\ub2e4 \uc7a0\uc2dc \ub9c8\uc74c\uc774 \ub2e4\ub978 \uacf3\uc5d0 \uba38\ubb34\ub294 \uc0c1\ud0dc\ub97c \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uadf8 \uc774\ub984\uc744 \uc54c\uace0 \ub098\uba74 \ubb34\uc5c7\uc744 \uc0c1\uc0c1\ud574\uc57c \ud558\ub290\ub0d0\ubcf4\ub2e4 \uc18c\ub9ac\uac00 \uc5b4\ub5bb\uac8c \ud750\ub974\ub294\uc9c0 \ub4e3\ub294 \uae38\uc774 \uc5f4\ub9b0\ub2e4. \uc774 \uace1\uc740 \uc791\ud488\ubc88\ud638 15\uc758 \u300a\uc5b4\ub9b0\uc774 \uc815\uacbd\u300b\uc5d0 \ub4e4\uc5b4 \uc788\ub2e4. \ub530\ub85c \uc5f0\uc8fc\ub418\ub294 \uc77c\uc774 \ub9ce\uc9c0\ub9cc \uc6d0\ub798\ub294 \uc5ec\ub7ec \uc81c\ubaa9\uc758 \uc9e7\uc740 \uace1\ub4e4\uc774 \uc774\uc5b4\uc9c0\ub294 \ubaa8\uc74c\uace1\uc758 \ud55c \ubd80\ubd84\uc774\ub2e4. \uadf8 \uc548\uc5d0\ub294 \ub0af\uc120 \ub098\ub77c\uc758 \uc774\uc57c\uae30\uc640 \ub180\uc774, \uc791\uc740 \uc0ac\uac74\uacfc \uc7a0\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uc81c\ubaa9\ub4e4\uc774 \ub193\uc778\ub2e4. \uc81c\ubaa9\uc5d0 \uc5b4\ub9b0\uc774\uac00 \uc788\ub2e4\uace0 \uc5b4\ub9b0\uc774\uc758 \ub2e8\uc21c\ud55c \uc5f0\uc2b5\uace1 \ubaa9\ub85d\uc73c\ub85c\ub9cc \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5b4\ub978\ub3c4 \uc5b4\ub9b0 \uc2dc\uc808\uc758 \uac10\uac01\uacfc \uae30\uc5b5\uc744 \ub5a0\uc62c\ub9ac\uba70 \ub4e4\uc744 \uc218 \uc788\ub2e4. \uc791\uc740 \uc7a5\uba74\uc744 \uc9e7\uc740 \uc74c\uc545\uc73c\ub85c \ub098\ub204\uc5c8\uae30 \ub54c\ubb38\uc5d0, \ud55c \uace1\uc529 \ub4e3\uace0 \ub2e4\uc2dc \uc804\uccb4\uc758 \uc21c\uc11c\ub97c \uc0b4\ud53c\ub294 \ubc29\ubc95\ub3c4 \uac00\ub2a5\ud558\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uac00\uc7a5 \uc704\uc5d0\uc11c \ub4e4\ub9ac\ub294 \uc120\uc728\uc744 \ud55c \uc904\uc758 \ub178\ub798\ucc98\ub7fc \ub530\ub77c\uac00 \ubcf4\uc790. \uc74c\uc774 \uc5b4\ub514\uc5d0\uc11c \uc62c\ub77c\uac00\uace0 \uc5b4\ub514\uc5d0\uc11c \uba38\ubb34\ub294\uc9c0, \ub9c8\uce68\ud45c\ucc98\ub7fc \ub290\uaef4\uc9c0\ub294 \uacf3\uc774 \uc5b4\ub514\uc778\uc9c0 \ub4e4\uc5b4 \ubcf4\ub294 \uac83\uc774\ub2e4. \uc545\ubcf4\ub97c \uc77d\uc9c0 \ubabb\ud574\ub3c4 \ub178\ub798\uc758 \ud638\ud761\uc740 \ub290\ub084 \uc218 \uc788\ub2e4. \ub108\ubb34 \uc720\uba85\ud55c \uace1\uc740 \uc774\ubbf8 \uc54c\uace0 \uc788\ub294 \uac10\uc815\uc73c\ub85c \ubc14\ub85c \ub36e\uae30 \uc27d\ub2e4. \uc2ac\ud504\ub2e4\uac70\ub098 \ud3b8\uc548\ud558\ub2e4\ub294 \ub9d0\uc774 \uba3c\uc800 \ub098\uc640\ub3c4 \uad1c\ucc2e\uc9c0\ub9cc, \uadf8\ub2e4\uc74c\uc5d0\ub294 \uc5b4\ub5a4 \uc6c0\uc9c1\uc784 \ub54c\ubb38\uc5d0 \uadf8\ub807\uac8c \ub4e4\ub838\ub294\uc9c0 \ubb3c\uc5b4\ubcfc \uc218 \uc788\ub2e4. \uac10\uc0c1\uc744 \uad6c\uccb4\uc801\uc778 \uc18c\ub9ac\uc640 \uc5f0\uacb0\ud558\uba74 \uc775\uc219\ud55c \uba5c\ub85c\ub514\ub3c4 \uc870\uae08 \uc0c8\ub85c\uc6cc\uc9c4\ub2e4. \ud53c\uc544\ub178\uc5d0\ub294 \uc55e\uc5d0 \ub098\uc624\ub294 \ub178\ub798\ub9cc \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uadf8 \uc544\ub798\uc758 \uc74c\ub4e4\uc774 \uc774\uc5b4\uc9c0\uba70 \ubc14\ud0d5\uc744 \ub9cc\ub4e4\uace0, \ub54c\ub85c\ub294 \uc548\ucabd\uc758 \uc18c\ub9ac\ub3c4 \uc6c0\uc9c1\uc778\ub2e4. \ud55c \uc0ac\ub78c\uc774 \uac74\ubc18\uc744 \ub204\ub974\uc9c0\ub9cc \uadc0\uc5d0\ub294 \uc5ec\ub7ec \uce35\uc758 \uad00\uacc4\uac00 \uc0dd\uae34\ub2e4. \uc870\uc6a9\ud55c \uace1\uc5d0\uc11c\ub3c4 \ubcfc\ub968 \ud558\ub098\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\ub294 \uc9dc\uc784\uc774 \uc788\ub2e4. \ub450 \ubc88\uc9f8\ub85c \ub4e4\uc744 \ub54c\uc5d0\ub294 \ub192\uc740 \uc120\uc728\uc744 \ub193\uce58\uc9c0 \uc54a\uc73c\ub824 \uc560\uc4f0\uae30\ubcf4\ub2e4 \ub0ae\uc740 \ucabd\uc774 \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc774\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \ubc30\uacbd\ucc98\ub7fc \ub4e4\ub9ac\ub358 \ubd80\ubd84\uc774 \uc120\uc728\uc744 \uc5b4\ub514\ub85c \uc774\ub044\ub294\uc9c0 \uc54c\uc544\ucc28\ub9b4 \uc218 \uc788\ub2e4. \ud55c \ubc88\uc758 \uac10\uc0c1\uc5d0 \ubaa8\ub4e0 \uac83\uc744 \uc7a1\uc73c\ub824 \ud558\uc9c0 \uc54a\uc73c\uba74 \ubc18\ubcf5\ud574\uc11c \ub4e3\ub294 \uc774\uc720\ub3c4 \uc0dd\uae34\ub2e4. \uc774 \uace1\uc744 \uc5ec\ub7ec \uc5f0\uc8fc\ub85c \ub4e4\uc73c\uba74 \ube60\ub974\uae30\uc640 \uba38\ubb34\ub294 \uc704\uce58\uac00 \ub2e4\ub974\uac8c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uc74c\uc744 \ub04a\uc9c0 \uc54a\uace0 \uc774\uc5b4 \uac00\ub294 \ubc29\uc2dd, \uc18c\ub9ac\ub97c \uc870\uae08 \ub113\ud788\uac70\ub098 \uac00\ubccd\uac8c \ub193\ub294 \ubc29\uc2dd\uc774 \ub178\ub798\uc758 \ub9d0\ud22c\ub97c \ubc14\uafbc\ub2e4. \uac19\uc740 \ubb38\uc7a5\ub3c4 \uc77d\ub294 \ud638\ud761\uc5d0 \ub530\ub77c \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c0\ub294 \uac83\uacfc \ube44\uc2b7\ud558\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc544\ubb34 \uacf3\uc5d0\uc11c\ub098 \uc624\ub798 \uba48\ucd94\uba74 \ub354 \uae4a\uc740 \uc74c\uc545\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud55c \uad6c\uc808\uc774 \uc5b4\ub514\ub85c \ud5a5\ud558\uace0 \ub2e4\uc74c \uad6c\uc808\uacfc \uc5b4\ub5bb\uac8c \uc774\uc5b4\uc9c0\ub294\uc9c0\uac00 \ud568\uaed8 \uc788\uc5b4\uc57c \ud55c\ub2e4. \ub290\ub9b0 \uc74c\uc545\uc758 \ud45c\ud604\ub3c4 \ub9c9\uc5f0\ud788 \uc2dc\uac04\uc744 \ub298\ub9ac\ub294 \uc77c\ubcf4\ub2e4 \uad00\uacc4\ub97c \ub9cc\ub4dc\ub294 \uc77c\uc5d0 \uac00\uae5d\ub2e4. \uc74c\uc758 \uc218\uac00 \ud654\ub824\ud55c \uace1\ubcf4\ub2e4 \uc801\uac8c \ub290\uaef4\uc838\ub3c4 \uac01 \uc18c\ub9ac\ub97c \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ud560\uc9c0\ub294 \uc138\uc2ec\ud55c \ubb38\uc81c\ub2e4. \uc120\uc728\uc774 \ubc18\uc8fc\uc5d0 \uac00\ub824\uc9c0\uc9c0 \uc54a\uac8c \ud558\uba74\uc11c \ub2e4\ub978 \uc131\ubd80\ub97c \uc9c0\uc6b0\uc9c0 \uc54a\uace0, \uc791\uc740 \ucc28\uc774\ub85c \ud750\ub984\uc744 \ub9cc\ub4dc\ub294 \uc77c\uc774 \ud544\uc694\ud558\ub2e4. \ub4e3\uae30 \ud3b8\ud55c \uc778\uc0c1 \ub4a4\uc5d0 \uc5f0\uc8fc\uc758 \ud310\ub2e8\uc774 \uc788\ub2e4. \uad00\uac1d\uc774 \uadf8 \ub09c\ub3c4\ub97c \ubaa8\ub450 \uacc4\uc0b0\ud574\uc57c \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uc26c\uc6cc \ubcf4\uc774\ub294 \uc74c\uc545\uc744 \uac00\uce58\uac00 \uc791\ub2e4\uace0 \ud310\ub2e8\ud558\uc9c0 \uc54a\ub294 \uc5ec\uc720\ub294 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ub208\uc5d0 \uc798 \ubcf4\uc774\ub294 \ud070 \uc6c0\uc9c1\uc784\ub9cc\uc774 \uc608\uc220\uc758 \uc5b4\ub824\uc6c0\uacfc \uae4a\uc774\ub97c \ub9cc\ub4dc\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc0ac\uc2e4\uc744 \uc774 \uace1\uc5d0\uc11c\ub3c4 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \u300a\uc5b4\ub9b0\uc774 \uc815\uacbd\u300b\uc758 \uc81c\ubaa9\ub4e4\uc744 \ub530\ub77c\uac00\uba74 \ub180\uc774\uc640 \uc0ac\uac74, \ubabd\uc0c1\uacfc \ud734\uc2dd\uc758 \ud45c\uc815\uc774 \uc774\uc6c3\ud55c\ub2e4. \u3008\ud2b8\ub85c\uc774\uba54\ub77c\uc774\u3009\ub97c \ub530\ub85c \ub4e4\uc744 \ub54c\uc758 \uace0\uc694\uc640 \ubaa8\uc74c\uace1 \uc548\uc5d0\uc11c \ub9cc\ub0a0 \ub54c\uc758 \uace0\uc694\ub294 \ub2e4\ub974\uac8c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uc5b4\ub514\uc5d0 \ub193\uc600\ub294\uc9c0\uac00 \ub4e3\ub294 \uacbd\ud5d8\uc744 \ubc14\uafbc\ub2e4. \uc61b \uc288\ub9cc \ud574\uc124\ub3c4 \uc774 \uc81c\ubaa9\ub4e4\uc758 \uc774\uc5b4\uc9d0\uc744 \uc0b4\ud53c\uba70 \uc544\uc774\uc758 \ubc14\uae65 \ud65c\ub3d9\uc5d0\uc11c \uc548\ucabd \ub9c8\uc74c\uc73c\ub85c \uc2dc\uc120\uc774 \uc62e\uaca8 \uac00\ub294 \ub4ef\ud55c \uac10\uc0c1\uc744 \uc804\ud55c\ub2e4. \uadf8\uac83\uc744 \ubaa8\ub4e0 \uad00\uac1d\uc758 \uc815\ub2f5\uc73c\ub85c \uc0bc\uc744 \ud544\uc694\ub294 \uc5c6\uc9c0\ub9cc, \uc21c\uc11c\ub97c \ubc14\uafb8\uc9c0 \uc54a\uace0 \ubaa8\uc74c\uace1\uc744 \ub9cc\ub098 \ubcfc \uc774\uc720\ub294 \ub41c\ub2e4. \uc791\uc740 \uace1\ub4e4\uc774 \uc11c\ub85c\uc758 \ubd84\uc704\uae30\ub97c \ubc1d\ud600 \uc904 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\uc5d0\ub294 \ud53c\uc544\ub178\uc640 \uc5f4\ub9b0 \ucc3d, \uc791\uc740 \uc7a5\ub09c\uac10\uacfc \uc815\uc6d0\uc744 \ubc14\ub77c\ubcf4\ub294 \uc0ac\ub78c\uc774 \uc788\ub2e4. \uc81c\ubaa9\uc774 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \ud68c\uc0c1\uacfc \ubabd\uc0c1\uc758 \ubd84\uc704\uae30\ub97c \uc0c8\ub85c \uadf8\ub9b0 \uadf8\ub9bc\uc774\ub2e4. \uc288\ub9cc\uc774\ub098 \ud074\ub77c\ub77c\uc758 \uc2e4\uc81c \ubc29\uc744 \ubcf5\uc6d0\ud558\uac70\ub098 \uc791\uace1 \uc21c\uac04\uc744 \uc7ac\ud604\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ub3c5\uc790\ub294 \uadf8\ub9bc\uc5d0\uc11c \uc790\uae30\ub9cc\uc758 \uae30\uc5b5\uc744 \ub5a0\uc62c\ub824\ub3c4 \uc88b\uace0, \uc774\ubbf8\uc9c0\ub97c \uc7a0\uc2dc \ub36e\uace0 \uc74c\uc545\uc744 \ub4e4\uc5b4\ub3c4 \uc88b\ub2e4. \ud55c \uc7a5\uc18c\uc640 \uc0ac\uc5f0\uc744 \uc815\ub2f5\uc73c\ub85c \ubd99\uc774\uc9c0 \uc54a\uae30 \uc704\ud574 \uc545\ubcf4\uc758 \uac00\uc9dc \uc74c\ud45c\ub098 \ud2b9\uc815 \uc778\ubb3c\uc758 \uc5bc\uad74\uc740 \ub123\uc9c0 \uc54a\uc558\ub2e4. \uc74c\uc545\uc744 \ub4e3\ub294 \uc790\uc720\ub97c \ub3d5\ub294 \uad00\ub828 \uc774\ubbf8\uc9c0\ub85c \uc900\ube44\ud588\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc120\uc728\uc744, \ub2e4\uc74c\uc5d0\ub294 \uc544\ub798\uc758 \uc18c\ub9ac\ub97c, \uadf8\ub2e4\uc74c\uc5d0\ub294 \uad6c\uc808\uc774 \uc26c\ub294 \uacf3\uc744 \ub4e4\uc5b4 \ubcf4\uc790. \ubaa8\ub450 \ub2e4\ub974\ub2e4\uace0 \ub290\ub07c\uc9c0 \ubabb\ud574\ub3c4 \uad1c\ucc2e\ub2e4. \uc7a0\uae50 \uc9d1\uc911\ud560 \ub300\uc0c1\uc744 \ubc14\uafb8\ub294 \uac83\ub9cc\uc73c\ub85c \uac19\uc740 \uace1\uc744 \ub4e3\ub294 \uc790\uc138\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \u3008\ud2b8\ub85c\uc774\uba54\ub77c\uc774\u3009\uc5d0\uc11c \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uac19\uc740 \uc5b4\ub9b0 \uc2dc\uc808\uc744 \ub5a0\uc62c\ub9b4 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc624\ub798\ub41c \uae30\uc5b5\ucc98\ub7fc \ub4e4\ub9b0\ub2e4\ub294 \uac10\uc0c1\ub3c4 \ud55c \uac00\uc9c0 \uac00\ub2a5\uc131\uc774\ub2e4. \uc9e7\uc740 \uc74c\uc545\uc774 \uac01\uc790\uc758 \uc2dc\uac04\uacfc \ub9cc\ub098\uba70 \uc624\ub798 \ub0a8\uc744 \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \uc774 \uc791\ud488\uc744 \uac70\ub4ed \ucc3e\uac8c \ud55c\ub2e4. \uc791\uc740 \uace1 \ud558\ub098\ub97c \ucda9\ubd84\ud788 \ub4e4\uc740 \uacbd\ud5d8\ub3c4 \uad50\uc591\uc758 \ud55c \ud615\ud0dc\uac00 \ub420 \uc218 \uc788\ub2e4."}, {"id": "secret-garden-key-and-shared-work", "title": "\u300e\ube44\ubc00\uc758 \ud654\uc6d0\u300f \u2014 \ubb38\uc744 \uc5f0 \ub4a4\uc5d0\ub294 \ub204\uac00 \uc815\uc6d0\uc744 \ub3cc\ubcf4\uc558\uc744\uae4c", "summary": "\uba54\ub9ac\uc640 \ucf5c\ub9b0, \ub514\ucf58\uc774 \uc7a0\uae34 \uc815\uc6d0\uc744 \uac00\uafb8\ub294 \uc904\uac70\ub9ac\uc640 \uc791\ud488\uc758 \ud68c\ubcf5 \uc774\uc57c\uae30\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/secret-garden-key-and-shared-work/index.html", "image": "../media/secret-garden-key-and-shared-work.png", "alt": "\ub2f4\uc7a5 \uc815\uc6d0\uc5d0\uc11c \uc544\uc774\ub4e4\uacfc \uc815\uc6d0\uc0ac\uac00 \ud654\ub2e8\uc744 \uac00\uafb8\uace0 \ud720\uccb4\uc5b4\ub97c \uacc1\uc5d0 \ub454 \uc18c\uc124 \uc7a5\uba74 \uc0bd\ud654", "text": "\u300e\ube44\ubc00\uc758 \ud654\uc6d0\u300f \u2014 \ubb38\uc744 \uc5f0 \ub4a4\uc5d0\ub294 \ub204\uac00 \uc815\uc6d0\uc744 \ub3cc\ubcf4\uc558\uc744\uae4c \ud63c\uc790 \uba85\ub839\ud558\ub358 \uc544\uc774\ub4e4\uc774 \ud568\uaed8 \uae30\ub2e4\ub9ac\ub294 \ubc95\uc744 \ubc30\uc6b0\ub2e4 \uba54\ub9ac\uc640 \ucf5c\ub9b0, \ub514\ucf58\uc774 \uc7a0\uae34 \uc815\uc6d0\uc744 \uac00\uafb8\ub294 \uc904\uac70\ub9ac\uc640 \uc791\ud488\uc758 \ud68c\ubcf5 \uc774\uc57c\uae30\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \uc624\ub7ab\ub3d9\uc548 \uc7a0\uaca8 \uc788\ub358 \ubb38\uc744 \uc5f4\uba74 \ubb34\uc5c7\uc774 \ub098\uc62c\uae4c. \u300e\ube44\ubc00\uc758 \ud654\uc6d0\u300f\uc758 \uba54\ub9ac\ub294 \ubcf4\ubb3c \uc0c1\uc790 \ub300\uc2e0 \ub3cc\ubd10\uc57c \ud560 \uc815\uc6d0\uc744 \ubc1c\uacac\ud55c\ub2e4. \uadf8\ub9ac\uace0 \uadf8\uacf3\uc5d0\uc11c \ub204\uac00 \ub098\ub97c \uc990\uac81\uac8c \ud574 \uc904 \uac83\uc778\uc9c0 \uae30\ub2e4\ub9ac\ub358 \uc0dd\ud65c\uc744 \ubc97\uc5b4\ub098, \uc790\uc2e0\uc774 \ubb34\uc5c7\uc744 \ud560 \uc218 \uc788\ub294\uc9c0 \ubc30\uc6b0\uae30 \uc2dc\uc791\ud55c\ub2e4. \ud504\ub79c\uc2dc\uc2a4 \ud638\uc9c0\uc2a8 \ubc84\ub137\uc758 \uc18c\uc124\uc740 \uc815\uc6d0\uc758 \ube44\ubc00\uc744 \ucc3e\ub294 \uc774\uc57c\uae30\uc774\uba74\uc11c \uace0\ub9bd\ub41c \uc0ac\ub78c\ub4e4\uc774 \ub2e4\uc2dc \uad00\uacc4\ub97c \ub9fa\ub294 \uc774\uc57c\uae30\ub2e4. \uc774 \uae00\uc740 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \ub9c8\uc9c0\ub9c9 \uc7ac\ud68c\uae4c\uc9c0 \ud3ec\ud568\ud55c\ub2e4. \uc791\ud488 \uc18d \ud68c\ubcf5\uc744 \uc2e4\uc81c \uc9c8\ubcd1\uc758 \uce58\ub8cc\ubc95\uacfc \ud63c\ub3d9\ud558\uc9c0 \uc54a\uace0 \uc77d\uc5b4 \ubcf4\uc790. \uba54\ub9ac \ub808\ub179\uc2a4\ub294 \uc601\uad6d \uc9c0\ubc30 \uc544\ub798\uc758 \uc778\ub3c4\uc5d0\uc11c \uc790\ub77c\uc9c0\ub9cc \uc8fc\ubcc0 \uc0ac\ub78c\uacfc \ub530\ub73b\ud55c \uad00\uacc4\ub97c \ub9fa\uc9c0 \ubabb\ud55c\ub2e4. \ubd80\ubaa8\ub97c \ucf5c\ub808\ub77c\ub85c \uc783\uc740 \ub4a4 \uc601\uad6d \uc694\ud06c\uc154\uc758 \uce5c\ucc99 \uc9d1\uc73c\ub85c \ubcf4\ub0b4\uc9c4\ub2e4. \ub0af\uc120 \uc800\ud0dd\uc5d0\ub294 \ub9ce\uc740 \ubc29\uc774 \uc788\uace0, \uc9d1\uc758 \uc8fc\uc778\uc778 \ud06c\ub808\uc774\ube10\uc740 \uc624\ub798 \uba38\ubb3c\uc9c0 \uc54a\ub294\ub2e4. \ubb3c\uc9c8\uc801\uc73c\ub85c \ud070 \uc9d1\uc774 \uc544\uc774\uc5d0\uac8c \ub4e0\ub4e0\ud55c \uc0dd\ud65c\uc744 \ubc14\ub85c \uc8fc\uc9c0\ub294 \ubabb\ud55c\ub2e4. \ucc98\uc74c\uc758 \uba54\ub9ac\ub294 \ub0a8\uc5d0\uac8c \uba85\ub839\ud558\ub294 \ud0dc\ub3c4\uc5d0 \uc775\uc219\ud558\ub2e4. \uc18c\uc124\uc758 \ucd9c\ubc1c\uc5d0\ub294 \uc2dd\ubbfc\uc9c0 \uc0ac\ud68c\uc758 \uc704\uacc4\uc640 \uace0\uc6a9 \uad00\uacc4\uac00 \ub193\uc5ec \uc788\ub2e4. \uadf8 \ubc30\uacbd\uc744 \ubaa8\ub450 \uc9c0\uc6b0\uace0 \uc6d0\ub798\ubd80\ud130 \uc2ec\uc220\uad82\uc5c8\ub358 \uc544\uc774\ub85c\ub9cc \ubcf4\uba74, \uba54\ub9ac\uac00 \ubc30\uc6b4 \uad00\uacc4\uc758 \ubc29\uc2dd\ub3c4 \ubcf4\uc774\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \ub3d9\uc2dc\uc5d0 \uadf8 \ubc30\uacbd\uc774 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ud568\ubd80\ub85c \ud574\ub3c4 \ub418\ub294 \uc774\uc720\ub294 \uc544\ub2c8\ub2e4. \ud558\ub140 \ub9c8\uc0ac\ub294 \uba54\ub9ac\uc758 \uba85\ub839\uc744 \uc775\uc219\ud55c \ubc29\uc2dd\uc73c\ub85c \ubc1b\uc544 \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \ud63c\uc790 \uc637\uc744 \uc785\uace0 \ubc16\uc73c\ub85c \ub098\uac00 \ubcf4\ub3c4\ub85d \ud55c\ub2e4. \uba54\ub9ac\ub294 \ubc14\ub78c\uc774 \ubd80\ub294 \ub4e4\ud310\uacfc \uc815\uc6d0\uc744 \ub9cc\ub098\uace0, \uc0ac\ub78c\uc758 \ub208\uce58\ub97c \ubcf4\uc9c0 \uc54a\ub294 \uc0c8\uc5d0\uac8c \uad00\uc2ec\uc744 \uac16\ub294\ub2e4. \ucc98\uc74c\uc73c\ub85c \ub2e4\ub978 \uc874\uc7ac\uac00 \ubb34\uc5c7\uc744 \ud558\ub294\uc9c0 \uac00\ub9cc\ud788 \uc9c0\ucf1c\ubcf4\ub294 \uc2dc\uac04\uc774 \uc0dd\uae34\ub2e4. \ub113\uc740 \uc9d1 \uc548\uc5d0\uc11c \ud560 \uc77c\uc774 \uc5c6\ub358 \uc0dd\ud65c\uacfc \ud759 \uc704\uc5d0\uc11c \uc6c0\uc9c1\uc774\ub294 \uc0dd\ud65c\uc740 \ub2e4\ub974\ub2e4. \uac77\uace0 \uad00\ucc30\ud558\uba70 \ubc30\uac00 \uace0\ud30c\uc9c0\ub294 \ubcc0\ud654\uac00 \uc870\uae08\uc529 \uc774\uc5b4\uc9c4\ub2e4. \uc791\uac00\ub294 \ucee4\ub2e4\ub780 \ud6c8\uacc4 \ud55c \ubc88\uc73c\ub85c \uc544\uc774\ub97c \ubc14\uafb8\uc9c0 \uc54a\ub294\ub2e4. \ub9e4\uc77c \ubab8\uc744 \uc6c0\uc9c1\uc774\uace0 \ud0c0\uc778\uc5d0\uac8c \uad00\uc2ec\uc744 \uae30\uc6b8\uc774\ub294 \ubc18\ubcf5\uc774 \uc0c8 \uc2b5\uad00\uc744 \ub9cc\ub4e0\ub2e4. \uba54\ub9ac\ub294 \uc815\uc6d0\uc0ac \ubca4 \uc6e8\ub354\uc2a4\ud0dc\ud504\ub97c \ub9cc\ub098\uace0 \uc6b8\uc0c8\ub97c \uc9c0\ucf1c\ubcf8\ub2e4. \ub545\uc5d0\uc11c \uc5f4\uc1e0\ub97c \ubc1c\uacac\ud558\uace0, \ub2f4\uc7c1\uc774\uc5d0 \uac00\ub824\uc9c4 \ubb38\ub3c4 \ucc3e\uc544\ub0b8\ub2e4. \uadf8 \ub108\uba38\uc5d0\ub294 \uc9d1\uc548\uc758 \uc2ac\ud514 \ub54c\ubb38\uc5d0 \uc624\ub7ab\ub3d9\uc548 \ub2eb\ud600 \uc788\ub358 \uc815\uc6d0\uc774 \uc788\ub2e4. \ub204\uad70\uac00\uc5d0\uac8c\ub294 \uae30\uc5b5\uc744 \ud53c\ud558\ub824 \uc7a0\uadfc \uacf5\uac04\uc774 \ub2e4\ub978 \uc544\uc774\uc5d0\uac8c\ub294 \uc2dc\uc791\ud560 \uc7a5\uc18c\uac00 \ub41c\ub2e4. \uc548\uc5d0\ub294 \uc8fd\uc740 \uac83\ucc98\ub7fc \ubcf4\uc774\ub294 \uac00\uc9c0\uc640 \uc0b4\uc544 \uc788\ub294 \uc2f9\uc774 \uc11e\uc5ec \uc788\ub2e4. \uba54\ub9ac\ub294 \ubb34\uc5c7\uc744 \ub0a8\uae30\uace0 \ubb34\uc5c7\uc744 \ub3c4\uc640\uc57c \ud560\uc9c0 \uc54c\uace0 \uc2f6\uc5b4\uc9c4\ub2e4. \ube44\ubc00\uc744 \ubc1c\uacac\ud55c \ub4a4 \uace7\ubc14\ub85c \ud0d0\ud5d8\uc774 \ub05d\ub098\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc77c\uc774 \uc2dc\uc791\ub41c\ub2e4\ub294 \uc810\uc774 \uc7ac\ubbf8\uc788\ub2e4. \ubb38\uc744 \uc5ec\ub294 \ub2a5\ub825\uacfc \uc815\uc6d0\uc744 \uc720\uc9c0\ud558\ub294 \ub2a5\ub825\uc740 \ub2e4\ub974\ub2e4. \ub9c8\uc0ac\uc758 \ub3d9\uc0dd \ub514\ucf58\uc740 \uc790\uc5f0\uacfc \ub3d9\ubb3c\uc5d0 \uc775\uc219\ud55c \uc18c\ub144\uc774\ub2e4. \uba54\ub9ac\uc640 \ud568\uaed8 \uc528\uc557\uacfc \ub545\uc744 \uc0b4\ud53c\uba70 \uc815\uc6d0\uc744 \uac00\uafbc\ub2e4. \uadf8\ub294 \uc2e0\uae30\ud55c \ud798\uc73c\ub85c \uaf43\uc744 \ud55c\uaebc\ubc88\uc5d0 \ud53c\uc6b0\ub294 \ub9c8\ubc95\uc0ac\uac00 \uc544\ub2c8\ub2e4. \uc5b8\uc81c \uc2ec\uace0 \ubb34\uc5c7\uc744 \uc870\uc2ec\ud574\uc57c \ud558\ub294\uc9c0 \uc544\ub294, \uc190\uc744 \ud568\uaed8 \uc6c0\uc9c1\uc77c \uc218 \uc788\ub294 \uce5c\uad6c\ub2e4. \uba54\ub9ac\uc5d0\uac8c \ube44\ubc00\uc744 \ub098\ub208\ub2e4\ub294 \uac83\uc740 \uc911\uc694\ud55c \ubcc0\ud654\ub2e4. \ubaa8\ub4e0 \uac83\uc744 \ub3c5\ucc28\uc9c0\ud558\ub824\ub358 \ub9c8\uc74c\uc5d0\uc11c \ub2e4\ub978 \uc0ac\ub78c\uc774 \ub4e4\uc5b4\uc62c \uc790\ub9ac\uac00 \uc0dd\uae34\ub2e4. \uac8c\ub2e4\uac00 \uce5c\uad6c\ub97c \uba85\ub839\uc73c\ub85c \ubd99\uc7a1\uc544 \ub458 \uc218\ub294 \uc5c6\ub2e4. \uc815\uc6d0\uc774 \uc790\ub77c\uae30\uae4c\uc9c0 \uae30\ub2e4\ub824\uc57c \ud558\ub4ef \uad00\uacc4\ub3c4 \uc790\uae30 \ub73b\ub300\ub85c\ub9cc \uc11c\ub450\ub97c \uc218 \uc5c6\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubc30\uc6b0\uac8c \ub41c\ub2e4. \uc800\ud0dd\uc5d0\uc11c \uba54\ub9ac\ub294 \uc6b8\uc74c\uc18c\ub9ac\ub97c \ub4e3\uace0 \uc228\uc5b4 \uc9c0\ub0b4\ub358 \ucf5c\ub9b0\uc744 \ub9cc\ub09c\ub2e4. \ud06c\ub808\uc774\ube10\uc758 \uc544\ub4e4\uc778 \uadf8\ub294 \ubcd1\uacfc \uc8fd\uc74c\uc5d0 \ub300\ud55c \ub450\ub824\uc6c0 \uc18d\uc5d0\uc11c \uc0dd\ud65c\ud55c\ub2e4. \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\uc740 \uadf8\uc758 \ubd84\ub178\ub97c \uc870\uc2ec\ud558\uace0, \uadf8\ub294 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uba85\ub839\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c \uc790\uae30 \ubd88\uc548\uc744 \ub2e4\ub8ec\ub2e4. \uba54\ub9ac\ub294 \uadf8\uc5d0\uac8c\uc11c \ub0af\uc775\uc740 \ubaa8\uc2b5\uc744 \ubcf8\ub2e4. \ub450 \uc544\uc774\uac00 \ucc98\uc74c\ubd80\ud130 \ubd80\ub4dc\ub7fd\uac8c \uc11c\ub85c\ub97c \uc704\ub85c\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ud22c\uace0 \ub9de\uc11c\uba70 \uc0c1\ub300\ub3c4 \ub73b\ub300\ub85c \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294 \uc0ac\ub78c\uc774\ub77c\ub294 \uc0ac\uc2e4\uc744 \uc54c\uac8c \ub41c\ub2e4. \uadf8 \ubd88\ud3b8\ud55c \ub9cc\ub0a8\uc774 \uc624\ud788\ub824 \uad00\uacc4\ub97c \uc2dc\uc791\ud55c\ub2e4. \uc9d1\uc548\uc758 \ubaa8\ub450\uac00 \uc790\uc2e0\uc744 \ud2b9\ubcc4\ud788 \ucde8\uae09\ud558\ub294 \uc0dd\ud65c\ubcf4\ub2e4, \uc790\uae30 \ub9d0\uc5d0 \ubc18\ubc15\ud558\ub294 \uce5c\uad6c\uac00 \ucf5c\ub9b0\uc5d0\uac8c \uc0c8\ub85c\uc6b4 \uc790\uadf9\uc774 \ub41c\ub2e4. \uba54\ub9ac\uc640 \ub514\ucf58\uc740 \ucf5c\ub9b0\uc744 \uc815\uc6d0\uc73c\ub85c \ub370\ub824\uac04\ub2e4. \ud720\uccb4\uc5b4\uc5d0 \uc549\uc544 \ubc14\ub77c\ubcf4\ub294 \ud48d\uacbd\uc740 \ubc29 \uc548\uc5d0\uc11c \uc0c1\uc0c1\ud558\ub358 \uc138\uacc4\uc640 \ub2e4\ub974\ub2e4. \uc815\uc6d0\uc740 \uc774\uc81c \uba54\ub9ac \ud63c\uc790 \ubc1c\uacac\ud55c \uc7a5\uc18c\ub97c \ub118\uc5b4 \uc138 \uc544\uc774\uac00 \ud568\uaed8 \uc0b4\uc544 \uc788\ub294 \ubcc0\ud654\ub97c \uc0b4\ud53c\ub294 \uacf5\uac04\uc774 \ub41c\ub2e4. \uc5b4\ub978\ub4e4\uc758 \ub3c4\uc6c0\uacfc \ub3cc\ubd04\ub3c4 \uadf8 \uc2dc\uac04\uc744 \ubc1b\uce5c\ub2e4. \uc774\ud6c4 \ucf5c\ub9b0\uc740 \uc11c\uace0 \uac77\ub294 \uc2dc\ub3c4\ub97c \ud558\uba70 \uc790\uc2e0\uc774 \ud560 \uc218 \uc788\ub294 \uc77c\uc744 \uc0c8\ub85c \uacbd\ud5d8\ud55c\ub2e4. \uc18c\uc124\uc740 \uadf8 \ubcc0\ud654\uc5d0 \ub180\ub77c\uc6c0\uacfc \uae30\uc068\uc744 \uc900\ub2e4. \ub2e4\ub9cc \uc544\uc774\uac00 \ub9c8\uc74c\uc744 \uace0\uccd0\uba39\uc73c\uba74 \ub204\uad6c\ub098 \uc7a5\uc560\ub098 \uc9c8\ubcd1\uc744 \uc774\uae34\ub2e4\ub294 \uc77c\ubc18 \ubc95\uce59\uc73c\ub85c \ubc1b\uc544\ub4e4\uc774\uc9c0\ub294 \ub9d0\uc544\uc57c \ud55c\ub2e4. \uc791\ud488\uc774 \uc120\ud0dd\ud55c \ud55c \uc778\ubb3c\uc758 \uc804\uac1c\uc640 \uc2e4\uc81c \ub2e4\uc591\ud55c \ubab8\uc758 \uacbd\ud5d8\uc740 \uac19\uc9c0 \uc54a\ub2e4. \uc544\uc774\ub4e4\uc740 \uc0b4\uc544 \uc788\ub294 \uac83\ub4e4\uc774 \uc790\ub77c\ub294 \ud798\uc744 \ub9c8\ubc95\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \ubd04\uc758 \ubcc0\ud654\uc640 \uc815\uc6d0\uc758 \ub178\ub3d9, \ud568\uaed8\ud558\ub294 \uc2dd\uc0ac\uc640 \uae30\ub300\uac00 \uadf8 \ub9d0\uc5d0 \ubaa8\uc778\ub2e4. \ub3c5\uc790\ub294 \uc2e4\uc81c \ub9c8\ubc95\uc0ac\uac00 \ub098\uc624\uc9c0 \uc54a\uc544\ub3c4 \uc65c \uadf8 \ub9d0\uc744 \uc4f0\uace0 \uc2f6\uc740\uc9c0 \uc774\ud574\ud558\uac8c \ub41c\ub2e4. \ub2eb\ud600 \uc788\ub358 \uc0dd\ud65c\uc774 \uc5f4\ub9ac\ub294 \ub290\ub08c\uc744 \uc124\uba85\ud558\ub294 \uc774\ub984\uc774\ub2e4. \uc791\ud488\uc5d0\ub294 \uc0dd\uac01\uc774 \ubab8\uc5d0 \ubbf8\uce58\ub294 \ud798\uc744 \ud06c\uac8c \uac15\uc870\ud558\ub294 \ub2f9\uc2dc\uc758 \uad00\ub150\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \uadf8\uac83\uc744 \uc624\ub298\uc758 \uc758\ud559\uc801 \uc870\uc5b8\uc73c\ub85c \uc62e\uae30\uae30\ubcf4\ub2e4 \ubb38\ud559\uc758 \ud45c\ud604\uc73c\ub85c \uc77d\ub294 \ud3b8\uc774 \uc88b\ub2e4. \ubab8\uc774 \uc544\ud508 \uc0ac\ub78c\uc5d0\uac8c \uae0d\uc815\uc801\uc73c\ub85c \uc0dd\uac01\ud558\uc9c0 \uc54a\uc544 \uadf8\ub807\ub2e4\uace0 \ucc45\uc784\uc744 \ub3cc\ub9b4 \uadfc\uac70\uac00 \ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc774\uc57c\uae30\ub97c \uc0ac\ub791\ud558\ub294 \uc77c\uacfc \ubaa8\ub4e0 \uc8fc\uc7a5\uc744 \uadf8\ub300\ub85c \ubbff\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \ub9c8\uc9c0\ub9c9\uc5d0 \ud06c\ub808\uc774\ube10\uc740 \ub3cc\uc544\uc640 \uc544\ub4e4\uc758 \ub2ec\ub77c\uc9c4 \ubaa8\uc2b5\uc744 \ub9cc\ub09c\ub2e4. \uc0c1\uc2e4\uc758 \uae30\uc5b5 \ub54c\ubb38\uc5d0 \uba40\ub9ac\ud558\ub358 \uc815\uc6d0\uc5d0\uc11c \uc0c8\ub85c\uc6b4 \uad00\uacc4\uac00 \uc790\ub77c\uace0 \uc788\uc5c8\ub2e4. \ub2eb\ud78c \ubb38\uc740 \uc2ac\ud514\uc774 \uc0ac\ub77c\uc84c\ub2e4\ub294 \uc99d\uac70\uac00 \uc544\ub2c8\ub77c \uc2ac\ud514\uacfc \ud568\uaed8 \ub2e4\uc2dc \uc0dd\ud65c\ud560 \uc218 \uc788\ub294 \uac00\ub2a5\uc131\uc774 \ub41c\ub2e4. \uacfc\uac70\uc758 \uc0ac\ub78c\uc744 \uc78a\uc9c0 \uc54a\uace0\ub3c4 \ubb38\uc744 \uc5f4 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \u300e\ube44\ubc00\uc758 \ud654\uc6d0\u300f\uc5d0\uc11c \uac00\uc7a5 \uc624\ub798 \ub0a8\ub294 \uac83\uc740 \uc5f4\uc1e0 \ud558\ub098\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uadf8 \uc5f4\uc1e0\ub85c \ub4e4\uc5b4\uac04 \ub4a4 \ub9e4\uc77c \ub3cc\uc744 \uce58\uc6b0\uace0 \uc528\uc557\uc744 \uc0b4\ud53c\ub358 \uc190\ub4e4\uc774 \ud568\uaed8 \ub0a8\ub294\ub2e4. \ube44\ubc00\uc744 \ucc3e\uc740 \ud55c \uc0ac\ub78c\uc774 \ubaa8\ub4e0 \uac83\uc744 \ud574\uacb0\ud55c \uac83\uc774 \uc544\ub2c8\ub2e4. \uce5c\uad6c\uc640 \uc774\uc6c3, \ub3cc\ubcf4\ub294 \uc5b4\ub978\ub4e4\uc774 \ub4e4\uc5b4\uc62c \uc790\ub9ac\ub97c \ub9cc\ub4e4\uba74\uc11c \uc815\uc6d0\ub3c4 \uc544\uc774\ub4e4\uc758 \uc0b6\ub3c4 \uc870\uae08\uc529 \ub113\uc5b4\uc9c4 \uac83\uc774\ub2e4."}, {"id": "sherlock-red-headed-league", "title": "\ubd89\uc740 \uba38\ub9ac \uc5f0\ub9f9 \u2014 \ub108\ubb34 \uc88b\uc740 \uc544\ub974\ubc14\uc774\ud2b8\uc758 \ube44\ubc00", "summary": "\ubc31\uacfc\uc0ac\uc804\uc744 \ubca0\ub07c\ub294 \uc77c\uacfc \uc804\ub2f9\ud3ec\uc758 \uc9c0\ud558\uc2e4\uc774 \uc5b4\ub5bb\uac8c \uc774\uc5b4\uc9c0\ub294\uc9c0 \uc0ac\uac74\uc758 \ud574\uacb0\uae4c\uc9c0 \ub530\ub77c\uac11\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/sherlock-red-headed-league/index.html", "image": "../media/sherlock-red-headed-league.png", "alt": "\ubd89\uc740 \uba38\ub9ac\uc758 \uc70c\uc2a8\uc774 \ub7f0\ub358 \uc0ac\ubb34\uc2e4\uc5d0\uc11c \ucee4\ub2e4\ub780 \ubc31\uacfc\uc0ac\uc804\uc744 \uc190\uc73c\ub85c \ubca0\ub07c\ub294 \uc6d0\uc791 \uae30\ubc18 \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ubd89\uc740 \uba38\ub9ac \uc5f0\ub9f9 \u2014 \ub108\ubb34 \uc88b\uc740 \uc544\ub974\ubc14\uc774\ud2b8\uc758 \ube44\ubc00 \uc15c\ub85d \ud648\uc988\ub294 \uc774\uc0c1\ud55c \uc77c\uc790\ub9ac\uc5d0\uc11c \ubb34\uc5c7\uc744 \ubcf4\uc558\uc744\uae4c \ubc31\uacfc\uc0ac\uc804\uc744 \ubca0\ub07c\ub294 \uc77c\uacfc \uc804\ub2f9\ud3ec\uc758 \uc9c0\ud558\uc2e4\uc774 \uc5b4\ub5bb\uac8c \uc774\uc5b4\uc9c0\ub294\uc9c0 \uc0ac\uac74\uc758 \ud574\uacb0\uae4c\uc9c0 \ub530\ub77c\uac11\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \uba38\ub9ac\uce74\ub77d\uc774 \ubd89\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \ub3c8\uc744 \ubc1b\ub294 \uc790\ub9ac\uac00 \uc788\ub2e4. \ud574\uc57c \ud560 \uc77c\uc740 \uc815\ud574\uc9c4 \uc2dc\uac04\uc5d0 \uc0ac\ubb34\uc2e4\uc5d0 \uc640\uc11c \ubc31\uacfc\uc0ac\uc804\uc744 \ubca0\ub07c\ub294 \uac83\ubfd0\uc774\ub2e4. \uc774\uc0c1\ud558\uc9c0\ub9cc \ub3c8\uc740 \uc81c\ub300\ub85c \uc9c0\uae09\ub41c\ub2e4. \uc544\uc11c \ucf54\ub10c \ub3c4\uc77c\uc758 \uc15c\ub85d \ud648\uc988 \uc774\uc57c\uae30 \u300c\ubd89\uc740 \uba38\ub9ac \uc5f0\ub9f9\u300d\uc740 \uc774\ub807\uac8c \uc6b0\uc2a4\uc6b4 \uad6c\uc778 \uad11\uace0\ub85c \ub3c5\uc790\ub97c \ubd88\ub7ec\ub4e4\uc778\ub2e4. \uc0ac\uc18c\ud558\uace0 \uae30\ubb18\ud574 \ubcf4\uc774\ub294 \uc870\uac74\uc774 \uc0ac\uc2e4\uc740 \ub204\uad70\uac00\uc5d0\uac8c \ub9e4\uc6b0 \uc911\uc694\ud55c \uc7a5\uce58\uc600\ub2e4. \ubb34\uc5c7\uc774 \uc774\uc0c1\ud55c\uac00\ub97c \uc54c\uc544\ucc28\ub9ac\ub294 \uc77c\uacfc \uadf8 \uc774\uc0c1\ud568\uc774 \ub204\uad6c\uc5d0\uac8c \ub3c4\uc6c0\uc774 \ub418\ub294\uc9c0 \ubb3b\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uc544\ub798\uc5d0\ub294 \uc0ac\uac74\uc758 \ud574\uacb0\uacfc \uacb0\ub9d0\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4. \uc81c\uc774\ubca0\uc988 \uc70c\uc2a8\uc740 \ub7f0\ub358\uc5d0\uc11c \uc791\uc740 \uc804\ub2f9\ud3ec\ub97c \uc6b4\uc601\ud55c\ub2e4. \uadf8\uc758 \uc870\uc218 \ube48\uc13c\ud2b8 \uc2a4\ud3f4\ub529\uc740 \uc2e0\ubb38 \uad11\uace0\ub97c \ubcf4\uc5ec \uc8fc\uba70 \ubd89\uc740 \uba38\ub9ac \ub0a8\uc131\ub4e4\uc744 \uc704\ud55c \uc790\ub9ac\ub97c \uad8c\ud55c\ub2e4. \uc70c\uc2a8\uc5d0\uac8c\ub294 \ud3c9\ubc94\ud55c \uc601\uc5c5 \uc678\uc5d0 \uc548\uc815\uc801\uc778 \uc218\uc785\uc774 \uc0dd\uae38 \uae30\ud68c\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uc774\uc57c\uae30\ub294 \uc758\uc0ac \uc653\uc2a8\uc774 \ud648\uc988\uc640 \ud568\uaed8 \uc70c\uc2a8\uc758 \ub9d0\uc744 \ub4e3\ub294 \ubc29\uc2dd\uc73c\ub85c \uc9c4\ud589\ub41c\ub2e4. \ub3c5\uc790\ub3c4 \uc190\ub2d8\uacfc \uac19\uc740 \uc815\ubcf4\ub97c \uc804\ub2ec\ubc1b\uc9c0\ub9cc \ud648\uc988\ub294 \ubb34\uc5c7\uc744 \ub530\ub85c \uae30\uc5b5\ud558\ub294\uc9c0 \ucda9\ubd84\ud788 \uc54c\ub824 \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \uac19\uc740 \uc124\uba85\uc744 \ub4e4\uc73c\uba74\uc11c \uc11c\ub85c \ub2e4\ub978 \uac83\uc5d0 \uc8fc\ubaa9\ud558\ub294 \uc0ac\ub78c\ub4e4\uc758 \ucc28\uc774\uac00 \ucd94\ub9ac\uc758 \uc7ac\ubbf8\ub97c \ub9cc\ub4e0\ub2e4. \uc9c0\uc6d0 \uc7a5\uc18c\uc5d0\ub294 \ubd89\uc740 \uba38\ub9ac\uc758 \ub0a8\uc790\ub4e4\uc774 \ub9ce\uc774 \ubaa8\uc5ec \uc788\ub2e4. \uc70c\uc2a8\uc740 \uc790\uc2e0\uc758 \uba38\ub9ac\uc0c9\uc744 \ud655\uc778\ubc1b\uace0 \uc790\ub9ac\ub97c \uc5bb\ub294\ub2e4. \ubcc4\uac83 \uc544\ub2cc \uc870\uac74\uc774 \uc5c4\uaca9\ud558\uac8c \uac80\uc0ac\ub418\uace0 \uacbd\uc7c1\uae4c\uc9c0 \ubc8c\uc5b4\uc9c0\uc790, \uc774\uc0c1\ud55c \uc77c\uc740 \uc624\ud788\ub824 \uc81c\ub300\ub85c \uc6b4\uc601\ub418\ub294 \uc81c\ub3c4\ucc98\ub7fc \ubcf4\uc774\uae30 \uc2dc\uc791\ud55c\ub2e4. \uc774\ub7f0 \uc7a5\uba74\uc740 \uc0ac\ub78c\uc758 \ubbff\uc74c\uc744 \ub9cc\ub4dc\ub294 \ubc29\uc2dd\ub3c4 \ubcf4\uc5ec \uc900\ub2e4. \uc904\uc744 \uc120 \uc0ac\ub78c\uc774 \ub9ce\uace0 \ub2f4\ub2f9\uc790\uac00 \uae4c\ub2e4\ub86d\uac8c \uad74\uba74 \uae30\ud68c\uac00 \ud76c\uadc0\ud558\uace0 \uc911\uc694\ud558\ub2e4\uace0 \ub290\ub07c\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \ub9ce\uc740 \uc9c0\uc6d0\uc790\uc640 \uc815\uad50\ud55c \uc808\ucc28\uac00 \uc788\ub2e4\uace0 \ud574\uc11c \uc77c\uc790\ub9ac\uc758 \ubaa9\uc801\uae4c\uc9c0 \uc815\ub2f9\ud558\ub2e4\ub294 \ubcf4\uc7a5\uc740 \uc5c6\ub2e4. \uc18c\uc124\uc740 \uadf8 \ud2c8\uc744 \uc7a5\ub09c\uc2a4\ub7fd\uac8c \uc774\uc6a9\ud55c\ub2e4. \uc70c\uc2a8\uc774 \ud558\ub294 \uc77c\uc740 \ubc31\uacfc\uc0ac\uc804\uc744 \uc190\uc73c\ub85c \uc62e\uaca8 \uc4f0\ub294 \uac83\uc774\ub2e4. \uadfc\ubb34 \uc2dc\uac04\uc740 \uc624\uc804 \uc5f4 \uc2dc\ubd80\ud130 \uc624\ud6c4 \ub450 \uc2dc\uae4c\uc9c0\uc774\uace0, \uadf8\ub3d9\uc548 \uc0ac\ubb34\uc2e4\uc744 \ub5a0\ub098\uba74 \uc548 \ub41c\ub2e4. \ubcf4\uc218\ub294 \uc8fc\ub2f9 4\ud30c\uc6b4\ub4dc\ub2e4. \ubc18\ubcf5\ud574\uc11c \uc798 \uc9c0\uae09\ub418\ub2c8 \ucc98\uc74c\uc758 \uc758\uc2ec\uc740 \ub204\uadf8\ub7ec\uc9c4\ub2e4. \ub3c5\uc790\ub294 \ubb34\uc5c7\uc744 \uc65c \ubca0\ub07c\ub294\uc9c0\uc5d0 \uad00\uc2ec\uc744 \uac16\uac8c \ub418\uc9c0\ub9cc \ub2e4\ub978 \uc9c8\ubb38\ub3c4 \uac00\ub2a5\ud558\ub2e4. \uc774 \uc77c\uc774 \uc2e4\uc81c\ub85c \uc0dd\uc0b0\ud558\ub294 \uac83\uc740 \uae00\uc758 \uc0ac\ubcf8\ubfd0\uc77c\uae4c. \uadfc\ubb34 \uc2dc\uac04 \ub3d9\uc548 \uc70c\uc2a8\uc774 \uc5b4\ub514\uc5d0 \uc5c6\uac8c \ub418\ub294\uc9c0 \uc0dd\uac01\ud558\uba74 \uc0ac\uac74\uc758 \ubc29\ud5a5\uc774 \ubc14\ub010\ub2e4. \ub178\ub3d9\uc758 \uacb0\uacfc\ubcf4\ub2e4 \uc0ac\ub78c\uc758 \uc790\ub9ac\ub97c \uc77c\uc815\ud558\uac8c \ube44\uc6cc \ub450\ub294 \uc77c\uc774 \uc911\uc694\ud560 \uc218 \uc788\ub2e4. \uc77c\uc774 \uacc4\uc18d\ub418\ub358 \uc5b4\ub290 \ub0a0 \uc70c\uc2a8\uc740 \uc5f0\ub9f9\uc774 \ud574\uc0b0\ub418\uc5c8\ub2e4\ub294 \uc548\ub0b4\ub97c \ubc1c\uacac\ud55c\ub2e4. \uc124\uba85\ud574 \uc904 \uc0ac\ub78c\uc740 \uc5c6\uace0 \ub2f4\ub2f9\uc790\uc758 \uc815\uccb4\ub3c4 \ubd84\uba85\ud558\uc9c0 \uc54a\ub2e4. \uc790\uc2e0\uc774 \uc77c\ud55c \uc774\uc720\ubcf4\ub2e4 \uac11\uc790\uae30 \uc218\uc785\uc744 \uc783\uc5c8\ub2e4\ub294 \ub2f9\ud639\uac10\uc774 \uba3c\uc800 \ub4e0\ub2e4. \uadf8\ub294 \uc774 \uc774\uc0c1\ud55c \uc77c\uc744 \ud648\uc988\uc5d0\uac8c \uac00\uc838\uc628\ub2e4. \uc774\ubbf8 \ub3c8\uc744 \ubc1b\uc558\uc73c\ub2c8 \uc18d\uc740 \uac83\uc774 \uc5c6\ub2e4\uace0 \uc0dd\uac01\ud560 \uc218\ub3c4 \uc788\ub2e4. \ud558\uc9c0\ub9cc \ub204\uad70\uac00\uac00 \ubcf4\uc218\ub97c \uc9c0\uae09\ud574\uc11c\ub77c\ub3c4 \uc5bb\uace0 \uc2f6\uc5c8\ub358 \uac83\uc774 \ubb34\uc5c7\uc778\uc9c0\uac00 \ub0a8\ub294\ub2e4. \uac89\uc73c\ub85c \ubcf4\uc774\ub294 \uac70\ub798\uac00 \uc190\ud574\ucc98\ub7fc \ubcf4\uc774\uc9c0 \uc54a\uc544\ub3c4, \uadf8 \uac70\ub798 \ub4a4\uc5d0 \ub2e4\ub978 \uacc4\ud68d\uc774 \uc788\uc744 \uc218 \uc788\ub2e4. \ud648\uc988\ub294 \uad11\uace0\uc758 \uae30\ubb18\ud568\uc744 \uac10\uc0c1\ud558\ub294 \ub370\uc11c \uba48\ucd94\uc9c0 \uc54a\ub294\ub2e4. \ud648\uc988\ub294 \uc804\ub2f9\ud3ec \uc8fc\ubcc0\uc744 \uc0b4\ud53c\uace0 \uc870\uc218\uc640\ub3c4 \ub9c8\uc8fc\uce5c\ub2e4. \uc70c\uc2a8\uc774 \ub9d0\ud55c \uc870\uc218\uc758 \uc0ac\uc9c4 \ucde8\ubbf8\uc640 \uc9c0\ud558\uc2e4\uc5d0 \uba38\ubb34\ub294 \uc2b5\uad00\uc740 \ub2e4\ub978 \ub73b\uc744 \uc5bb\ub294\ub2e4. \ud648\uc988\uac00 \uc8fc\ubaa9\ud55c \ubc14\uc9c0 \ubb34\ub98e\uc758 \ud754\uc801\ub3c4 \uadf8 \uc0ac\ub78c\uc774 \ubab8\uc744 \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud588\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ud558\ub294 \ub2e8\uc11c\ub2e4. \uac70\ub9ac\uc5d0\uc11c \ubcf4\uc774\ub294 \uac74\ubb3c\uc758 \uc55e\uba74\ub9cc\uc73c\ub85c\ub294 \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4. \uc804\ub2f9\ud3ec \ub4a4\ucabd\uc774 \uc5b4\ub5a4 \uc7a5\uc18c\uc640 \uc774\uc5b4\uc9c0\ub294\uc9c0 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \ud648\uc988\uac00 \uace8\ubaa9\uacfc \uc8fc\ubcc0\uc744 \ud655\uc778\ud558\ub294 \uc7a5\uba74\uc740 \uc791\uc740 \uc810\ud3ec\ub97c \ub354 \ud070 \uacf5\uac04 \uc548\uc5d0 \ub193\ub294\ub2e4. \uc774\uc57c\uae30\uc758 \uc9c0\ub3c4\ub294 \uc885\uc774\uc5d0\ub9cc \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uac74\ubb3c\uc758 \ubc30\uce58 \uc18d\uc5d0\ub3c4 \uc788\ub2e4. \ubaa9\ud45c\ub294 \uac00\uae4c\uc6b4 \uc740\ud589\uc758 \uc9c0\ud558\uc5d0 \ubcf4\uad00\ub41c \uae08\uc774\uc5c8\ub2e4. \ubc94\uc778\ub4e4\uc740 \uc804\ub2f9\ud3ec \uc9c0\ud558\uc5d0\uc11c \uc740\ud589 \ucabd\uc73c\ub85c \ud1b5\ub85c\ub97c \ub9cc\ub4e4\ub824 \ud588\ub2e4. \uc774\ub97c \uc704\ud574 \uc8fc\uc778\uc778 \uc70c\uc2a8\uc744 \ub9e4\uc77c \uc77c\uc815\ud55c \uc2dc\uac04 \uac00\uac8c \ubc16\uc5d0 \ub450\ub294 \uc7a5\uce58\uac00 \ud544\uc694\ud588\ub2e4. \uc870\uc218\uac00 \uc0c1\ub300\uc801\uc73c\ub85c \uc801\uc740 \ubcf4\uc218\ub85c \uc77c\ud558\ub358 \uc774\uc720\ub3c4 \uc774 \uacc4\ud68d \uc18d\uc5d0\uc11c \ub2ec\ub77c \ubcf4\uc778\ub2e4. \ubd89\uc740 \uba38\ub9ac\ub77c\ub294 \uc870\uac74\uacfc \ubc31\uacfc\uc0ac\uc804 \ud544\uc0ac\ub294 \uc70c\uc2a8\uc744 \ud2b9\ubcc4\ud788 \uc120\ud0dd\ub41c \uc0ac\ub78c\ucc98\ub7fc \ub290\ub07c\uac8c \ud558\ub294 \ubb34\ub300\uc600\ub2e4. \uc784\uae08\uc744 \uc2e4\uc81c\ub85c \uc9c0\uae09\ud55c \uac83\ub3c4 \uacc4\ud68d\uc744 \uc720\uc9c0\ud558\uae30 \uc704\ud55c \ube44\uc6a9\uc774\uc5c8\ub2e4. \uc774\uc0c1\ud55c \uc77c\uc790\ub9ac\uc640 \uc9c4\uc9c0\ud55c \ubc94\uc8c4\uac00 \uc11c\ub85c \ubb34\uad00\ud55c \uc774\uc57c\uae30\uac00 \uc544\ub2c8\uc5c8\ub358 \uac83\uc774\ub2e4. \uc5f0\ub9f9\uc774 \uc0ac\ub77c\uc9c4 \uc2dc\uc810\uc740 \uc900\ube44\uac00 \ub05d\ub0ac\ub2e4\ub294 \uc2e0\ud638\ub85c \uc77d\ud78c\ub2e4. \ud648\uc988\uc640 \ub3d9\ub8cc\ub4e4\uc740 \uc740\ud589 \uc9c0\ud558\uc5d0\uc11c \ubc94\uc778\ub4e4\uc774 \ub098\ud0c0\ub098\uae30\ub97c \uae30\ub2e4\ub9b0\ub2e4. \ubc1d\uc740 \uc0ac\ubb34\uc2e4\uc5d0\uc11c \uc6b0\uc2a4\uc6b4 \uc0ac\uc5f0\uc744 \ub4e3\ub358 \ubd84\uc704\uae30\ub294 \uc5b4\ub450\uc6b4 \uacf5\uac04\uc758 \uae34\uc7a5\uc73c\ub85c \ubc14\ub010\ub2e4. \uc870\uc218\ub85c \ud589\uc138\ud55c \uc778\ubb3c\uc758 \uc815\uccb4\uc640 \uacc4\ud68d\uc774 \ub4dc\ub7ec\ub098\uace0 \ubc94\ud589\uc740 \uc800\uc9c0\ub41c\ub2e4. \ud648\uc988\ub294 \ub098\uc911\uc5d0 \uc790\uc2e0\uc774 \uc5b4\ub5a4 \ub2e8\uc11c\ub97c \uc5f0\uacb0\ud588\ub294\uc9c0 \uc124\uba85\ud55c\ub2e4. \ub3c5\uc790\ub294 \uc55e\uc5d0\uc11c \uc774\ubbf8 \uc77d\uc5c8\ub358 \uc815\ubcf4\ub97c \ub2e4\uc2dc \ubcf4\uac8c \ub41c\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc9c0\ub098\uce5c \uba38\ub9ac\uc0c9 \uac80\uc0ac\ub098 \uadfc\ubb34 \uaddc\uc815\uc774 \uc6c3\uc74c\uc758 \uc7ac\ub8cc\uc600\uc9c0\ub9cc, \uacb0\ub9d0 \ub4a4\uc5d0\ub294 \ubaa9\uc801\uc744 \ub2ec\uc131\ud558\uae30 \uc704\ud574 \uc9dc\uc778 \uc870\uac74\uc73c\ub85c \ubc14\ub010\ub2e4. \ub2e4\uc2dc \uc77d\uc744 \ub54c \uc7ac\ubbf8\uac00 \ub0a8\ub294 \uc774\uc720\ub2e4. \uc774 \uc774\uc57c\uae30\ub294 \uc138\uc0c1\uc5d0\uc11c \ub108\ubb34 \uc88b\uc740 \uc81c\uc548\uc744 \ub9cc\ub098\uba74 \ubaa8\ub450 \ubc94\uc8c4\ub77c\uace0 \uc0dd\uac01\ud558\ub77c\ub294 \uc124\uba85\uc11c\uac00 \uc544\ub2c8\ub2e4. \uc18c\uc124\uc758 \uc990\uac70\uc6c0\uc740 \uad00\ucc30\ud55c \uac83\ub4e4\uc774 \ud558\ub098\uc758 \ubaa9\uc801\uacfc \uacf5\uac04 \uc548\uc5d0\uc11c \ub9de\ubb3c\ub9ac\ub294 \uc21c\uac04\uc5d0 \uc788\ub2e4. \ub2e8\uc11c\ub97c \ub9ce\uc774 \ubcf4\ub294 \uc77c\ubfd0 \uc544\ub2c8\ub77c \uc5b4\ub290 \uc9c8\ubb38\uc744 \ub358\uc9c8\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \ubc31\uacfc\uc0ac\uc804\uc744 \ubca0\ub07c\ub294 \uc70c\uc2a8\uc758 \uc0c1\ud669\uc744 \uc0c8\ub85c \uc0c1\uc0c1\ud588\ub2e4. \uc0ac\uac74\uc758 \uc9c0\ub3c4\ub97c \uadf8\ub824 \uc815\ub2f5\uc744 \uba3c\uc800 \uc54c\ub824 \uc8fc\ub294 \uadf8\ub9bc\uc740 \uc544\ub2c8\ub2e4. \ud3c9\ubc94\ud558\uac8c \ucc45\uc0c1 \uc55e\uc5d0 \uc549\uc740 \uc0ac\ub78c\uc774 \uc5b4\ub5a4 \uacc4\ud68d\uc758 \uc77c\ubd80\uac00 \ub418\uc5b4 \uc788\ub294\uc9c0, \ubcf8\ubb38\uc744 \ub530\ub77c\uac00\uba70 \uc870\uae08 \ub2a6\uac8c \uc54c\uc544\ucc28\ub9ac\ub294 \uc7ac\ubbf8\ub97c \ub0a8\uaca8 \ub450\uc5c8\ub2e4."}, {"id": "silas-marner-gold-child-and-neighbors", "title": "\uc0ac\uc77c\ub7ec\uc2a4 \ub9c8\ub108 \u2014 \uc783\uc5b4\ubc84\ub9b0 \uae08\ud654 \ub300\uc2e0 \uc544\uc774\uac00 \ub4e4\uc5b4\uc628 \ubc24", "summary": "\uc9c1\uc870\uacf5\uc774 \uae08\ud654\ub97c \uc783\uace0 \uc544\uc774\ub97c \ub3cc\ubcf4\uba70 \uc774\uc6c3\uacfc \ub2e4\uc2dc \uad00\uacc4\ub97c \ub9fa\ub294 \uacfc\uc815\uc744 \uacb0\ub9d0\uae4c\uc9c0 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/silas-marner-gold-child-and-neighbors/index.html", "image": "../media/silas-marner-gold-child-and-neighbors.png", "alt": "\ubca0\ud2c0\uacfc \ub09c\ub85c\uac00 \uc788\ub294 \uc9d1\uc5d0\uc11c \uae08\ubc1c\uc758 \uc5b4\ub9b0\uc544\uc774\ub97c \ub3cc\ubcf4\ub294 \uc0ac\uc77c\ub7ec\uc2a4 \ub9c8\ub108 \uad00\ub828 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uc0ac\uc77c\ub7ec\uc2a4 \ub9c8\ub108 \u2014 \uc783\uc5b4\ubc84\ub9b0 \uae08\ud654 \ub300\uc2e0 \uc544\uc774\uac00 \ub4e4\uc5b4\uc628 \ubc24 \ub204\uba85\uacfc \uace0\ub9bd\uc5d0\uc11c \ub3cc\ubd04\uacfc \uc774\uc6c3, \uc2a4\uc2a4\ub85c \uc120\ud0dd\ud558\ub294 \uac00\uc871\uc73c\ub85c \uc9c1\uc870\uacf5\uc774 \uae08\ud654\ub97c \uc783\uace0 \uc544\uc774\ub97c \ub3cc\ubcf4\uba70 \uc774\uc6c3\uacfc \ub2e4\uc2dc \uad00\uacc4\ub97c \ub9fa\ub294 \uacfc\uc815\uc744 \uacb0\ub9d0\uae4c\uc9c0 \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \uc870\uc9c0 \uc5d8\ub9ac\uc5c7\uc758 \u300e\uc0ac\uc77c\ub7ec\uc2a4 \ub9c8\ub108\u300f\ub294 \ub3c8\uc744 \ube7c\uc557\uae34 \uc9c1\uc870\uacf5\uc5d0\uac8c \uc5b4\ub9b0\uc544\uc774\uac00 \ucc3e\uc544\uc624\ub294 \uc774\uc57c\uae30\ub2e4. \uc904\uac70\ub9ac\ub9cc \ub4e4\uc73c\uba74 \uc120\ud589\uc5d0 \ubcf4\uc0c1\uc774 \ub530\ub974\ub294 \ub3d9\ud654 \uac19\uc9c0\ub9cc, \uc791\ud488\uc740 \ubbff\uc74c\uc744 \uc783\uc740 \uc0ac\ub78c\uc774 \ub2e4\uc2dc \uc774\uc6c3\uacfc \uad00\uacc4\ub97c \ub9fa\ub294 \uacfc\uc815\uc744 \uc624\ub798 \ub530\ub77c\uac04\ub2e4. \ub3c8\uacfc \ud608\ud1b5\ub9cc\uc73c\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\ub294 \uac00\uc871\uc758 \uc774\uc57c\uae30\ub97c \uacb0\ub9d0\uae4c\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc0ac\uc77c\ub7ec\uc2a4\ub294 \ucc98\uc74c\ubd80\ud130 \uc678\ud1a8\uc774\uc600\ub358 \uc0ac\ub78c\uc774 \uc544\ub2c8\ub2e4. \uc80a\uc740 \uc2dc\uc808\uc5d0\ub294 \ub79c\ud134 \uc57c\ub4dc\uc758 \uc885\uad50 \uacf5\ub3d9\uccb4\uc5d0 \uc18d\ud588\uace0 \uc57d\ud63c\ub140\ub3c4 \uc788\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \uce5c\uad6c \uc70c\ub9ac\uc5c4 \ub370\uc778\uc758 \ubc30\uc2e0\uc73c\ub85c \ub3c4\ub451\uc774\ub77c\ub294 \ub204\uba85\uc744 \uc4f4\ub2e4. \uc9c4\uc2e4\uc744 \ubc1d\ud600 \uc904 \uac83\uc774\ub77c \ubbff\uc5c8\ub358 \uacf5\ub3d9\uccb4\uc758 \ud310\ub2e8\ub9c8\uc800 \uadf8\ub97c \uc800\ubc84\ub9b0\ub2e4. \uadf8\ub294 \uace0\ud5a5\uc744 \ub5a0\ub098 \ub798\ubc8c\ub85c\ub77c\ub294 \ub9c8\uc744\uc5d0 \uc815\ucc29\ud55c\ub2e4. \ub0af\uc120 \uc8fc\ubbfc\ub4e4\uc5d0\uac8c \uc9c1\uc870\uacf5\uc740 \uc0dd\ud65c \ubc29\uc2dd\ub3c4 \ubab8\uc758 \uc774\uc0c1 \uc99d\uc0c1\ub3c4 \uc774\ud574\ud558\uae30 \uc5b4\ub824\uc6b4 \uc0ac\ub78c\uc774\ub2e4. \uc0ac\uc77c\ub7ec\uc2a4 \uc5ed\uc2dc \uba3c\uc800 \ub9c8\uc74c\uc744 \uc5f4\uc9c0 \uc54a\ub294\ub2e4. \uc11c\ub85c\ub97c \uc798 \ubaa8\ub974\ub294 \uac70\ub9ac\uac10\uc774 \uc624\ub7ab\ub3d9\uc548 \uad73\uc5b4 \uac04\ub2e4. \uc0ac\uc77c\ub7ec\uc2a4\ub294 \ubca0\ud2c0 \uc55e\uc5d0\uc11c \uc77c\ud558\uace0 \ubc1b\uc740 \ub3c8\uc744 \ubaa8\uc740\ub2e4. \ubc24\ub9c8\ub2e4 \uae08\ud654\ub97c \uaebc\ub0b4 \ub9cc\uc9c0\uace0 \uc138\ub294 \ud589\ub3d9\uc740 \ub2e8\uc21c\ud55c \uc7ac\uc0b0 \uad00\ub9ac\uac00 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\uc758 \uc57d\uc18d\uc740 \ubb34\ub108\uc84c\uc9c0\ub9cc \uae08\ud654\uc758 \ubb34\uac8c\uc640 \ube5b\uc740 \ubcc0\ud558\uc9c0 \uc54a\ub294 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c0\uae30 \ub54c\ubb38\uc774\ub2e4. \uadf8\uc5d0\uac8c \ub3c8\uc740 \ubb34\uc5c7\uc744 \uc0ac\uae30 \uc704\ud55c \uc218\ub2e8\ubcf4\ub2e4 \uad00\uacc4\uc758 \ub300\uccb4\ubb3c\uc5d0 \uac00\uae5d\ub2e4. \uc774 \ub54c\ubb38\uc5d0 \uc800\ucd95\uc774 \ub298\uc5b4\ub3c4 \uc0dd\ud65c\uc740 \ub113\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uc5d8\ub9ac\uc5c7\uc740 \ubd80\uc720\ud574\uc9c0\ub294 \uc77c\uacfc \ucda9\ub9cc\ud574\uc9c0\ub294 \uc77c\uc774 \ubc18\ub4dc\uc2dc \ud568\uaed8 \uac00\uc9c0\ub294 \uc54a\ub294\ub2e4\ub294 \uc0ac\uc2e4\uc744, \ubc18\ubcf5\ub418\ub294 \ud558\ub8e8\uc758 \ubaa8\uc2b5\uc73c\ub85c \ubcf4\uc5ec \uc900\ub2e4. \ub204\uba85\uc744 \uacaa\uc740 \uacfc\uac70\ub294 \uc0ac\uc77c\ub7ec\uc2a4\uac00 \uc65c \ub9c8\uc744\uc758 \ud638\uc758\ub97c \uc27d\uac8c \ubc1b\uc544\ub4e4\uc774\uc9c0 \ubabb\ud558\ub294\uc9c0 \uc124\uba85\ud55c\ub2e4. \uc0c8\ub85c \ub9cc\ub09c \uc774\uc6c3\uc774 \uce5c\uc808\ud558\ub2e4\uace0 \ud574\uc11c \uc624\ub798\ub41c \uc0c1\ucc98\uac00 \uae08\ubc29 \uc0ac\ub77c\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc18c\uc124\uc740 \ud68c\ubcf5\uc758 \ucd9c\ubc1c\uc810\uc744 \uc774\ub7f0 \ubd88\uc2e0\uc758 \uc2dc\uac04\uc5d0 \ub454\ub2e4. \ub9c8\uc744\uc758 \uc9c0\uc8fc \uc9d1\uc548\uc5d0\ub294 \ud615\uc81c \uace0\ub4dc\ud504\ub9ac\uc640 \ub358\uc2a4\ud134 \uce90\uc2a4\uac00 \uc788\ub2e4. \uace0\ub4dc\ud504\ub9ac\ub294 \ub0b8\uc2dc\ub97c \uc0ac\ub791\ud558\uc9c0\ub9cc \ubab0\ub9ac\uc640 \ub9fa\uc740 \uacb0\ud63c\uacfc \uc544\uc774\uc758 \uc874\uc7ac\ub97c \uc228\uae34\ub2e4. \ub3d9\uc0dd \ub358\uc2a4\ud134\uc740 \ud615\uc758 \uc57d\uc810\uc744 \uc54c\uace0 \uc774\uc6a9\ud558\uba70, \uc0ac\uc77c\ub7ec\uc2a4\uc758 \uc9d1\uc5d0 \ub4e4\uc5b4\uac00 \ubaa8\uc544 \ub454 \ub3c8\uae4c\uc9c0 \ud6d4\uce5c\ub2e4. \uae08\ud654\uac00 \uc0ac\ub77c\uc9c0\uc790 \uc0ac\uc77c\ub7ec\uc2a4\ub294 \uc808\ub9dd \uc18d\uc5d0\uc11c \ub9c8\uc744 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \ub3c4\uc6c0\uc744 \uccad\ud55c\ub2e4. \ubbff\uc744 \uc218 \uc788\ub294 \ubb3c\uac74\uc744 \uc783\uc740 \uc77c\uc774 \uc5ed\uc124\uc801\uc73c\ub85c \uc0ac\ub78c\uc744 \ucc3e\uc544 \ub098\uc11c\ub294 \uacc4\uae30\uac00 \ub41c\ub2e4. \uc0ac\uac74\uc740 \uc9c1\uc870\uacf5\uc758 \uc791\uc740 \uc9d1\uacfc \uc9c0\uc8fc\uc758 \uccb4\uba74 \uc788\ub294 \uc9d1\uc744 \ud55c \uc774\uc57c\uae30 \uc548\uc5d0 \ubb36\ub294\ub2e4. \ucd94\uc6b4 \ubc24 \ubab0\ub9ac\ub294 \uc5b4\ub9b0 \ub538\uc744 \ub370\ub9ac\uace0 \uae38\uc744 \uac00\ub2e4 \uc4f0\ub7ec\uc838 \uc8fd\ub294\ub2e4. \uc544\uc774\ub294 \ubd88\ube5b\uc744 \ub530\ub77c \uc0ac\uc77c\ub7ec\uc2a4\uc758 \uc9d1\uc73c\ub85c \ub4e4\uc5b4\uc628\ub2e4. \uc0ac\uc77c\ub7ec\uc2a4\uac00 \ub09c\ub86f\uac00\uc5d0\uc11c \ucc98\uc74c \ubc1c\uacac\ud558\ub294 \ud669\uae08\ube5b\uc740 \ub3cc\uc544\uc628 \uae08\ud654\uac00 \uc544\ub2c8\ub77c \uc544\uc774\uc758 \uba38\ub9ac\uce74\ub77d\uc774\ub2e4. \uadf8\ub294 \uc544\uc774\ub97c \uc5d0\ud53c\ub77c\uace0 \ubd80\ub974\uace0 \uc9c1\uc811 \uae30\ub974\uae30\ub85c \ud55c\ub2e4. \uc544\uc774\ub294 \uac00\ub9cc\ud788 \ubcf4\uad00\ud560 \uc218 \uc788\ub294 \ubcf4\ubb3c\uc774 \uc544\ub2c8\ub2e4. \uba39\uc774\uace0 \uc53b\uae30\uace0 \uc704\ud5d8\ud55c \uacf3\uc5d0 \uac00\uc9c0 \uc54a\uac8c \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uae08\ud654\ub97c \uc138\ub358 \uc190\uc5d0 \uc0c8\ub85c\uc6b4 \uc77c\uc774 \uc0dd\uae30\uace0, \uc9d1\uc758 \uc2dc\uac04\ud45c\ub3c4 \uc544\uc774\uc758 \uc131\uc7a5\uc5d0 \ub9de\ucd94\uc5b4 \ubc14\ub010\ub2e4. \uc81c\ubaa9\uc5d0 \uc544\uc774\ubcf4\ub2e4 \uc9c1\uc870\uacf5\uc758 \uc774\ub984\uc774 \ub193\uc778 \uac83\ub3c4 \uc0dd\uac01\ud574 \ubcfc \ub9cc\ud558\ub2e4. \uc5d0\ud53c\uac00 \uad6c\uc6d0\uc758 \uc0c1\uc9d5\uc73c\ub85c\ub9cc \uba38\ubb34\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc131\uc7a5\ud558\uba70 \uc790\uae30 \ubaa9\uc18c\ub9ac\ub97c \uac16\ub294 \ub3d9\uc548, \uc0ac\uc77c\ub7ec\uc2a4\uc758 \uc0dd\ud65c \uc5ed\uc2dc \uc218\ub3d9\uc801\uc778 \uc0c1\uc2e4\uc5d0\uc11c \ub2a5\ub3d9\uc801\uc778 \ub3cc\ubd04\uc73c\ub85c \ub2ec\ub77c\uc9c4\ub2e4. \ub3cc\ub9ac \uc708\uc2a4\ub7fd\uc740 \uc0ac\uc77c\ub7ec\uc2a4\uc5d0\uac8c \uc721\uc544\uc640 \uc0dd\ud65c\uc758 \ub3c4\uc6c0\uc744 \uc900\ub2e4. \uadf8\ub294 \ubaa8\ub4e0 \uac83\uc744 \ud63c\uc790 \uc54c\uc544\ub0b4\uc9c0 \ubabb\ud558\uba70, \uc11c\ud230 \uc591\uc721\uc744 \ud1b5\ud574 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uacbd\ud5d8\uc5d0 \uae30\ub300\ub294 \ubc95\uc744 \uc775\ud78c\ub2e4. \uc5d0\ud53c\ub97c \ub370\ub9ac\uace0 \ub098\uac00\ub294 \uae38\uc5d0\uc11c \ub9c8\uc744 \uc0ac\ub78c\ub4e4\uacfc\ub3c4 \ub2e4\uc2dc \ub9cc\ub09c\ub2e4. \uc791\ud488\uc774 \uad00\uacc4\uc758 \ud68c\ubcf5\uc744 \uc124\ub4dd\ub825 \uc788\uac8c \uadf8\ub9ac\ub294 \uc774\uc720\uac00 \uc5ec\uae30\uc5d0 \uc788\ub2e4. \uc0ac\uc77c\ub7ec\uc2a4\uac00 \uac11\uc790\uae30 \uc778\uac04 \uc804\uccb4\ub97c \ubbff\uae30\ub85c \uacb0\uc2ec\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc791\uc740 \ub3c4\uc6c0\uc744 \ubc1b\uace0 \ub3cc\ub824\uc8fc\ub294 \uc77c\uc774 \uc313\uc778\ub2e4. \uc544\uc774\uc640 \uc9c1\uc870\uacf5\ub9cc\uc758 \uc544\ub984\ub2e4\uc6b4 \uc9d1 \ub4a4\uc5d0\ub294 \uc774\uc6c3\uc758 \uc190\ub3c4 \ud568\uaed8 \uc788\ub2e4. \uc624\ub79c \ub4a4 \ubb3c\uc774 \ube60\uc9c4 \ucc44\uc11d\uc7a5\uc5d0\uc11c \ub358\uc2a4\ud134\uc758 \uc720\ud574\uc640 \ud6d4\uce5c \uae08\ud654\uac00 \ubc1c\uacac\ub41c\ub2e4. \uc228\uaca8\uc84c\ub358 \uacfc\uac70\uac00 \ub4dc\ub7ec\ub098\uc790 \uace0\ub4dc\ud504\ub9ac\ub294 \ub0b8\uc2dc\uc5d0\uac8c \uacb0\ud63c\uacfc \ub538\uc758 \uc874\uc7ac\ub97c \uace0\ubc31\ud55c\ub2e4. \ub450 \uc0ac\ub78c\uc740 \uc5d0\ud53c\ub97c \uc790\uae30 \uc9d1\uc73c\ub85c \ub370\ub824\uc640 \ub354 \uc88b\uc740 \uc0dd\ud65c\uc744 \uc8fc\ub824 \ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc131\uc7a5\ud55c \uc5d0\ud53c\ub294 \uc0ac\uc77c\ub7ec\uc2a4 \uacc1\uc5d0 \ub0a8\uaca0\ub2e4\uace0 \ub9d0\ud55c\ub2e4. \ud608\uc5f0\uc0c1\uc758 \uc544\ubc84\uc9c0\uac00 \uc904 \uc218 \uc788\ub294 \uc548\ub77d\ud568\uacfc, \uc790\uc2e0\uc744 \ub3cc\ubcf4\uba70 \ud568\uaed8 \uc0b4\uc544\uc628 \uc544\ubc84\uc9c0 \uc0ac\uc774\uc5d0\uc11c \uc120\ud0dd\ud558\ub294 \uac83\uc774\ub2e4. \uc774 \uc7a5\uba74\uc758 \uc911\uc2ec\uc740 \uace0\ub4dc\ud504\ub9ac\uc758 \uad8c\ub9ac \uc8fc\uc7a5\uc774 \uc544\ub2c8\ub77c \uc5d0\ud53c \uc790\uc2e0\uc758 \uc758\uc0ac\ub2e4. \uace0\ub4dc\ud504\ub9ac\uac00 \uc9c4\uc2e4\uc744 \ub2a6\uac8c \ub9d0\ud55c \ub370\uc5d0\ub294 \uccb4\uba74\uacfc \ubbf8\ub798\uc5d0 \ub300\ud55c \ub450\ub824\uc6c0\uc774 \uc788\ub2e4. \uc18c\uc124\uc740 \uadf8\uc758 \ud6c4\ud68c\ub97c \ubcf4\uc5ec \uc8fc\uc9c0\ub9cc \ud6c4\ud68c\ub9cc\uc73c\ub85c \uc9c0\ub098\uac04 \uc2dc\uac04\uc744 \ub418\ub3cc\ub824 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5d0\ud53c\uac00 \ud544\uc694\ub85c \ud588\ub358 \ub3cc\ubd04\uc740 \uc774\ubbf8 \ub2e4\ub978 \uc0ac\ub78c\uc774 \ub9e4\uc77c \ud574 \uc628 \uc77c\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \uc0ac\uc77c\ub7ec\uc2a4\ub294 \uc5d0\ud53c\uc640 \uc61b \uace0\ud5a5\uc744 \ucc3e\uc544\uac00\uc9c0\ub9cc \ub79c\ud134 \uc57c\ub4dc\ub294 \ubcc0\ud574 \ubc84\ub838\ub2e4. \uc624\ub798\uc804 \ub204\uba85\uc744 \uc628\uc804\ud788 \ubc14\ub85c\uc7a1\uc744 \uae30\ud68c\ub294 \uc5bb\uc9c0 \ubabb\ud55c\ub2e4. \uc18c\uc124\uc740 \uc9c4\uc0c1\uc774 \ubaa8\ub450 \ubc1d\ud600\uc9c0\uace0 \uc798\ubabb\ud55c \uc774\uac00 \uc0ac\uacfc\ud574\uc57c\ub9cc \ud589\ubcf5\ud574\uc9c4\ub2e4\ub294 \uc2dd\uc73c\ub85c \ub9c8\ubb34\ub9ac\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc5d0\ud53c\ub294 \ub3cc\ub9ac\uc758 \uc544\ub4e4 \uc5d0\ub7f0\uacfc \uacb0\ud63c\ud558\uace0 \uc0ac\uc77c\ub7ec\uc2a4\uc640 \uac00\uae4c\uc774 \uc0b4\uc544\uac08 \ubbf8\ub798\ub97c \ud0dd\ud55c\ub2e4. \ub3cc\uc544\uc628 \uae08\uc740 \uc608\uc804\ucc98\ub7fc \uc0b6\uc758 \uc911\uc2ec\uc774 \ub418\uc9c0 \ubabb\ud55c\ub2e4. \u300e\uc0ac\uc77c\ub7ec\uc2a4 \ub9c8\ub108\u300f\uac00 \ub0a8\uae30\ub294 \uac83\uc740 \ub3c8\uc744 \ubc84\ub9ac\ub77c\ub294 \uad50\ud6c8\ubcf4\ub2e4, \ubb34\uc5c7\uc774 \ud55c \uc0ac\ub78c\uc758 \ud558\ub8e8\ub97c \uc0b4\uc544 \uc788\ub294 \uad00\uacc4\ub85c \ucc44\uc6b0\ub294\uac00\ub77c\ub294 \uc9c8\ubb38\uc774\ub2e4. \ucc98\uc74c\uc758 \ud669\uae08\uacfc \ub4a4\uc758 \ud669\uae08\ube5b \uba38\ub9ac\uce74\ub77d\uc740 \uc11c\ub85c\ub97c \ub5a0\uc62c\ub9ac\uac8c \ud558\uc9c0\ub9cc \uac19\uc740 \uc885\ub958\uc758 \uc18c\uc720\uac00 \uc544\ub2c8\ub2e4. \uae08\ud654\ub294 \uac10\ucdb0 \ub458 \uc218 \uc788\uc5b4\ub3c4 \uc544\uc774\ub294 \ub2e4\ub978 \uc0ac\ub78c\uacfc \uad00\uacc4\ub97c \ub9fa\uace0 \uc2a4\uc2a4\ub85c \uc120\ud0dd\ud55c\ub2e4. \uc0ac\uc77c\ub7ec\uc2a4\uac00 \uc5bb\uc740 \uac00\uc871\uc5d0\ub294 \uadf8 \ucc28\uc774\ub97c \ubc1b\uc544\ub4e4\uc774\ub294 \ubcc0\ud654\uac00 \ud3ec\ud568\ub41c\ub2e4."}, {"id": "sistine-ceiling-adam-and-painted-architecture", "title": "\uc2dc\uc2a4\ud2f0\ub098 \ucc9c\uc7a5\ud654 \u2014 \ub450 \uc190\uac00\ub77d \uc0ac\uc774\uc5d0\ub294 \ucc9c\uc7a5 \uc804\uccb4\uac00 \uc788\ub2e4", "summary": "\uc720\uba85\ud55c \uc190\ub05d\uc758 \uac04\uaca9\uc744 \ucc9c\uc7a5 \uc804\uccb4\uc758 \uc774\uc57c\uae30\uc640 \uc778\ubb3c, \uc791\uc5c5 \uc870\uac74 \uc18d\uc5d0\uc11c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/sistine-ceiling-adam-and-painted-architecture/index.html", "image": "../media/sistine-ceiling-adam-and-painted-architecture.jpg", "alt": "\ubbf8\ucf08\ub780\uc824\ub85c\uc758 \uc544\ub2f4\uc758 \ucc3d\uc870\uc5d0\uc11c \ub450 \uc778\ubb3c\uc774 \uc190\uc744 \ubed7\ub294 \ubaa8\uc2b5\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc2e4\uc81c \uc791\ud488 \uceec\ub7ec \ub3c4\ud310", "text": "\uc2dc\uc2a4\ud2f0\ub098 \ucc9c\uc7a5\ud654 \u2014 \ub450 \uc190\uac00\ub77d \uc0ac\uc774\uc5d0\ub294 \ucc9c\uc7a5 \uc804\uccb4\uac00 \uc788\ub2e4 \uc544\ub2f4\uc758 \uc190\ub05d\uc5d0\uc11c \ucc3d\uc138\uae30\uc640 \uc608\uc5b8\uc790, \ube44\uacc4\uc758 \ub178\ub3d9\uae4c\uc9c0 \uc720\uba85\ud55c \uc190\ub05d\uc758 \uac04\uaca9\uc744 \ucc9c\uc7a5 \uc804\uccb4\uc758 \uc774\uc57c\uae30\uc640 \uc778\ubb3c, \uc791\uc5c5 \uc870\uac74 \uc18d\uc5d0\uc11c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \ubbf8\ucf08\ub780\uc824\ub85c\uc758 \u300c\uc544\ub2f4\uc758 \ucc3d\uc870\u300d\ub294 \uac70\uc758 \ub9de\ub2ff\uc744 \ub4ef\ud55c \ub450 \uc190\uc73c\ub85c \uc720\uba85\ud558\ub2e4. \uadf8\ub7ec\ub098 \uc190\uac00\ub77d\ub9cc \uc798\ub77c \ubcf4\uba74 \uadf8\ub9bc\uc774 \ub193\uc778 \ucc9c\uc7a5\uacfc \uc8fc\ubcc0 \uc778\ubb3c\ub4e4\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \uc2dc\uc2a4\ud2f0\ub098 \uc608\ubc30\ub2f9 \ucc9c\uc7a5\ud654\ub294 \ud55c \uc7a5\uc758 \uadf8\ub9bc\uc744 \ud06c\uac8c \ub298\uc778 \uac83\uc774 \uc544\ub2c8\ub77c, \uc5ec\ub7ec \uc7a5\uba74\uacfc \uc778\ubb3c\uc744 \uac74\ucd95\ucc98\ub7fc \uc870\uc9c1\ud55c \uac70\ub300\ud55c \ud68c\ud654\ub2e4. \uc775\uc219\ud55c \ubd80\ubd84\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc804\uccb4\ub97c \ubc14\ub77c\ubcf4\uc790. \ubbf8\ucf08\ub780\uc824\ub85c\ub294 \uc2a4\uc2a4\ub85c \uc870\uac01\uc744 \uc911\uc694\ud55c \uc77c\ub85c \uc5ec\uacbc\uc9c0\ub9cc \uad50\ud669 \uc728\ub9ac\uc6b0\uc2a4 2\uc138\uc758 \uc8fc\ubb38\uc73c\ub85c \ucc9c\uc7a5 \uc791\uc5c5\uc744 \ub9e1\uc558\ub2e4. 1508\ub144\ubd80\ud130 1512\ub144\uae4c\uc9c0 \uc9c4\ud589\ud55c \uc791\uc5c5\uc740 \uae30\uc874 \uc608\ubc30\ub2f9 \uacf5\uac04 \uc704\uc5d0 \uc0c8\ub85c\uc6b4 \uadf8\ub9bc\uc758 \uc9c8\uc11c\ub97c \uc138\uc6b0\ub294 \uc77c\uc774\uc5c8\ub2e4. \uc774\ubbf8 \uc788\ub358 \ubcbd\ud654\uc640 \ucc9c\uc7a5\uc744 \uad6c\ubd84\ud574\uc11c \ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \ub2f9\uc2dc\uc758 \uc608\ubc30\ub2f9\uc740 \uad50\ud669\uccad\uc758 \uc911\uc694\ud55c \uc758\ub840 \uacf5\uac04\uc774\uc5c8\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \uac78\uc5b4 \ub4e4\uc5b4\uc640 \uc704\ub97c \uc62c\ub824\ub2e4\ubcf4\ub294 \uc7a5\uc18c\uc774\uc9c0, \uadf8\ub9bc \uc55e\uc5d0 \uac19\uc740 \ub192\uc774\ub85c \uc11c\ub294 \uc804\uc2dc\uc2e4\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uba40\ub9ac \uc788\ub294 \uc778\ubb3c\uc744 \uc5b4\ub5bb\uac8c \uc77d\ud788\uac8c \ud560\uc9c0, \uad7d\uc740 \uba74\uc5d0 \ub193\uc778 \uc7a5\uba74\uc744 \uc5b4\ub5bb\uac8c \uc774\uc5b4 \uc904\uc9c0\uac00 \ucc98\uc74c\ubd80\ud130 \ud070 \uacfc\uc81c\uc600\ub2e4. \ucc9c\uc7a5\uc758 \uac00\uc6b4\ub370\uc5d0\ub294 \ube5b\uacfc \uc5b4\ub460, \ud574\uc640 \ub2ec, \uc778\uac04\uc758 \ucc3d\uc870, \ud0c0\ub77d\uacfc \ud64d\uc218 \ub4f1 \ucc3d\uc138\uae30\uc5d0\uc11c \uac00\uc838\uc628 \uc7a5\uba74\ub4e4\uc774 \ub193\uc600\ub2e4. \uc774 \uc7a5\uba74\ub4e4\uc744 \ubaa8\ub450 \uac19\uc740 \ud06c\uae30\uc758 \ub9cc\ud654 \uce78\ucc98\ub7fc \uc0dd\uac01\ud558\uba74 \uc2e4\uc81c \uad6c\uc131\uc744 \ub193\uce5c\ub2e4. \ud06c\uae30\uc640 \uc778\ubb3c \uc218, \ubab8\uc758 \ubc29\ud5a5\uc774 \uc11c\ub85c \ub2e4\ub974\ub2e4. \ud55c\uacf3\uc5d0\ub294 \ub113\uc740 \ubab8\uc9d3\uc774 \uc2dc\uc120\uc744 \ubd99\uc7a1\uace0 \ub2e4\ub978 \uacf3\uc5d0\ub294 \ub9ce\uc740 \uc778\ubb3c\uc774 \uae34\ubc15\ud558\uac8c \uc6c0\uc9c1\uc778\ub2e4. \uad00\ub78c\uc790\ub294 \ud55c \uc7a5\uba74\uc744 \uc77d\ub2e4\uac00 \uc8fc\ubcc0\uc758 \uc778\ubb3c\uacfc \ub2e4\uc74c \uc7a5\uba74\uc73c\ub85c \ub208\uc744 \uc62e\uae34\ub2e4. \ucc9c\uc7a5\uc740 \uc0ac\uac74\uc744 \ucc28\ub840\ub85c \uc54c\ub824 \uc8fc\uba74\uc11c\ub3c4 \ud558\ub098\uc758 \ud070 \uacf5\uac04\uc73c\ub85c \ub290\uaef4\uc9c0\ub3c4\ub85d \uc124\uacc4\ub418\uc5b4 \uc788\ub2e4. \uc911\uc559\uc758 \uc774\uc57c\uae30\ub9cc \ucc3e\uc73c\uba74 \uc0ac\ub78c\ub4e4\uc740 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ucc9c\uc7a5\uc758 \ub2e4\ub978 \ubd80\ubd84\uc744 \ubc30\uacbd\uc73c\ub85c \ubc00\uc5b4\ub0b4\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uacbd\uacc4\uc758 \ud2c0\uacfc \uc8fc\ubcc0 \uc778\ubb3c\uc774 \uc788\uc5b4\uc57c \uac00\uc6b4\ub370 \uc7a5\uba74\uc758 \ud06c\uae30\uc640 \uc704\uce58\ub3c4 \uac10\uac01\ub41c\ub2e4. \uc544\ub2f4\uc758 \uc190\uc740 \ube48 \uacf5\uac04\uc5d0 \ub3c5\ub9bd\ud574 \uc788\ub294 \ud45c\uc9c0\uac00 \uc544\ub2c8\ub2e4. \u300c\uc544\ub2f4\uc758 \ucc3d\uc870\u300d\uc5d0\uc11c \uc544\ub2f4\uc740 \ub545\uc5d0 \ubab8\uc744 \uae30\ub300\uace0 \ud55c\ucabd \ud314\uc744 \ubed7\ub294\ub2e4. \uac74\uc7a5\ud55c \ubab8\uc740 \uc774\ubbf8 \ubcf4\uc774\uc9c0\ub9cc \uc190\uacfc \ubab8\uc758 \ud798\uc740 \uc624\ub978\ud3b8\uc5d0\uc11c \ub2e4\uac00\uc624\ub294 \uc874\uc7ac\uc640 \ub2e4\ub974\ub2e4. \uc2e0\uc744 \ub458\ub7ec\uc2fc \uc778\ubb3c\uacfc \ucc9c\uc758 \ub369\uc5b4\ub9ac\ub294 \uc55e\uc73c\ub85c \uc6c0\uc9c1\uc774\uace0, \uc544\ub2f4\uc758 \ubab8\uc740 \ub300\uc9c0\uc5d0 \uba38\ubb38\ub2e4. \ub450 \uc190 \uc0ac\uc774\uc758 \uc791\uc740 \ube48\ud2c8\uc740 \uc6c0\uc9c1\uc784\uc744 \uba48\ucd98\ub2e4. \uc774\ubbf8 \uc811\ucd09\ud55c \uc21c\uac04\ubcf4\ub2e4 \uace7 \ubb34\uc5b8\uac00 \uc77c\uc5b4\ub0a0 \uc21c\uac04\uc744 \ud0dd\ud588\uae30 \ub54c\ubb38\uc5d0 \ubcf4\ub294 \uc0ac\ub78c\uc740 \uadf8 \uac04\uaca9\uc744 \uc624\ub798 \ubc14\ub77c\ubcf8\ub2e4. \uc0dd\uba85\uacfc \uad00\uacc4\ub77c\ub294 \uc8fc\uc81c\ub97c \ubab8\uc758 \uae30\uc6b8\uae30\uc640 \uc190\ub05d\uc758 \uac70\ub9ac\ub85c \uc0dd\uac01\ud558\uac8c \ud558\ub294 \uc7a5\uba74\uc774\ub2e4. \uc7a5\uba74\ub4e4\uc744 \ub098\ub204\ub294 \ud2c0\uacfc \ubc1b\uce68, \uc778\ubb3c\ub4e4\uc774 \uc549\uc740 \uc790\ub9ac\uc758 \ub9ce\uc740 \ubd80\ubd84\uc740 \uc2e4\uc81c \uc870\uac01\uc774\ub098 \ub3cc\uc774 \uc544\ub2c8\ub77c \uadf8\ub9bc\uc774\ub2e4. \uac74\ucd95\uc744 \uadf8\ub824 \ub123\uc740 \uad6c\uc870\uac00 \ucc9c\uc7a5\uc758 \uc778\ubb3c\ub4e4\uc744 \uc9c0\ud0f1\ud558\ub294 \uac83\ucc98\ub7fc \ubcf4\uc778\ub2e4. \ud45c\uba74\uc5d0 \uce60\ud55c \uc548\ub8cc\uac00 \ub9c8\uce58 \ub2e4\ub978 \uae4a\uc774\uc758 \uacf5\uac04\uc744 \ub9cc\ub4dc\ub294 \uc148\uc774\ub2e4. \uc774\uac83\uc744 \ub208\uc18d\uc784\uc758 \uc19c\uc528\ub85c\ub9cc \ubcf4\uae30\ub294 \uc544\uae5d\ub2e4. \ud070 \uc774\uc57c\uae30\uc640 \uc791\uc740 \uc778\ubb3c\uad70\uc744 \ubb36\uace0 \ub098\ub204\ub294 \uc7a5\uce58\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \uc561\uc790 \ud558\ub098\ub97c \ubcf8\ub2e4\ub294 \uac10\uac01\uc5d0\uc11c \ubc97\uc5b4\ub098, \uadf8\ub9bc \uc18d \uac74\ucd95\uacfc \uc608\ubc30\ub2f9\uc758 \uc2e4\uc81c \uac74\ucd95\uc774 \uc5b4\ub5bb\uac8c \uacb9\uccd0\uc9c0\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uba74 \ucc9c\uc7a5\uc758 \ud06c\uae30\uac00 \uc0c8\ub86d\uac8c \ub290\uaef4\uc9c4\ub2e4. \uc778\ubb3c\uc758 \ud06c\uae30\ub97c \ubab8\uc73c\ub85c \uac00\ub2a0\ud574 \ubcf4\ub294 \uac83\ub3c4 \uc88b\uc740 \uac10\uc0c1\ubc95\uc774\ub2e4. \uc544\ub798\uc5d0\uc11c \uc62c\ub824\ub2e4\ubcf4\uc544\ub3c4 \uc790\uc138\uc640 \ubab8\uc9d3\uc774 \uc77d\ud600\uc57c \ud588\uc73c\ubbc0\ub85c \ud654\uba74 \uc18d \ubab8\uc740 \uba40\ub9ac \uc788\ub294 \uad00\ub78c\uc790\ub97c \uc5fc\ub450\uc5d0 \ub454\ub2e4. \ucc45\uc758 \uc791\uc740 \ubcf5\uc81c \ub3c4\ud310\uc5d0\uc11c \ub290\ub080 \ube44\ub840\uac00 \ud604\uc7a5 \uacbd\ud5d8 \uc804\ubd80\ub294 \uc544\ub2c8\ub2e4. \uc911\uc559 \uc774\uc57c\uae30\uc758 \uc8fc\ubcc0\uc5d0\ub294 \uc608\uc5b8\uc790\ub4e4\uacfc \uace0\ub300\uc758 \ubb34\ub140\uc778 \uc2dc\ube4c\ub77c\ub4e4\uc774 \uc549\uc544 \uc788\ub2e4. \ucc45\uc744 \uc77d\uac70\ub098 \ubab8\uc744 \ub3cc\ub9ac\uac70\ub098 \uae4a\uc740 \uc0dd\uac01\uc5d0 \uc7a0\uae34 \ubaa8\uc2b5\uc740 \ubaa8\ub450 \ub2e4\ub974\ub2e4. \ubbf8\ub798\ub97c \uc608\uace0\ud558\ub294 \uc778\ubb3c\ub4e4\uc744 \ud55c \uc904\uc758 \uc124\uba85\ubb38 \ub300\uc2e0 \uc11c\ub85c \ub2e4\ub978 \ubab8\uacfc \ud45c\uc815\uc73c\ub85c \ubc30\uce58\ud55c \uac83\uc774\ub2e4. \uc131\uc11c\uc758 \uc608\uc5b8\uc790\uc640 \uace0\uc804 \uc138\uacc4\uc758 \uc2dc\ube4c\ub77c\uac00 \ud568\uaed8 \uc788\ub2e4\ub294 \uc810\uc5d0\ub294 \ub2f9\uc2dc \uadf8\ub9ac\uc2a4\ub3c4\uad50\uc640 \uace0\ub300 \ubb38\ud654\uc758 \uad00\uacc4\uac00 \ubc18\uc601\ub41c\ub2e4. \ucc9c\uc7a5\uc744 \ucc3d\uc138\uae30\uc758 \ub2e8\uc21c\ud55c \uc0bd\ud654 \ubaa8\uc74c\uc73c\ub85c \ubcf4\uc9c0 \uc54a\uac8c \ud558\ub294 \ub300\ubaa9\uc774\ub2e4. \uc8fc\ubcc0\uc758 \uc778\ubb3c \uc5ed\uc2dc \uac00\uc6b4\ub370 \uc0ac\uac74\uc744 \ubc14\ub77c\ubcf4\ub294 \ud070 \ud574\uc11d\uc758 \ud2c0\uc744 \uc774\ub8ec\ub2e4. \ubbf8\ucf08\ub780\uc824\ub85c\uac00 \ub0b4\ub0b4 \ub4f1\uc744 \ubc14\ub2e5\uc5d0 \ub300\uace0 \ub204\uc6cc \uadf8\ub838\ub2e4\uace0 \uc0c1\uc0c1\ud558\uae30 \uc27d\ub2e4. \uc2e4\uc81c\ub85c\ub294 \ube44\uacc4 \uc704\uc5d0\uc11c \ucc9c\uc7a5\uc744 \ud5a5\ud574 \ubab8\uc744 \uc138\uc6b0\uace0 \uace0\uac1c\ub97c \uc816\ud788\ub294 \ub4f1 \ud798\ub4e0 \uc790\uc138\ub85c \uc791\uc5c5\ud588\ub2e4. \uc624\ub798 \uace0\uac1c\ub97c \ub4e4\uace0 \uc77c\ud55c \uace0\ud1b5\uc740 \uadf8\uac00 \ub0a8\uae34 \uae00\uacfc \uadf8\ub9bc\uc5d0\uc11c\ub3c4 \uc77d\ud78c\ub2e4. \ud504\ub808\uc2a4\ucf54\ub294 \uc816\uc740 \ud68c\ubcbd\uc5d0 \uc548\ub8cc\ub97c \uc62c\ub9ac\ub294 \ubc29\uc2dd\uc774\ubbc0\ub85c \ud55c \ubc88\uc5d0 \uc791\uc5c5\ud560 \uba74\uc801\uacfc \uc2dc\uac04\uc744 \uacc4\ud68d\ud574\uc57c \ud55c\ub2e4. \ubc11\uadf8\ub9bc\uacfc \ud68c\ubcbd \uc900\ube44, \ube44\uacc4\uc640 \uc7ac\ub8cc\ub3c4 \ud544\uc694\ud558\ub2e4. \uc911\uc2ec \uc778\ubb3c\uc744 \ub9cc\ub4e0 \ud654\uac00\uc758 \uc5ed\ub7c9\uc744 \uc778\uc815\ud558\uba74\uc11c\ub3c4, \uac70\ub300\ud55c \ud604\uc7a5\uc744 \uc9c0\ud0f1\ud55c \uc791\uc5c5 \uc870\uac74\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ucc9c\uc7a5\ud654\uac00 \uc54c\ub824 \uc8fc\ub294 \uc885\uad50\uc801 \uc758\ubbf8\ub97c \ubaa8\ub450 \ud55c \ubc88\uc5d0 \ud574\ub3c5\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ucc45\uc744 \ubd99\ub4e0 \uc190, \ubab8\uc744 \ub3cc\ub9ac\ub294 \ud5c8\ub9ac, \uc11c\ub85c \ub2e4\ub978 \uc549\uc740 \uc790\uc138\ubd80\ud130 \uc0b4\ud3b4\ub3c4 \ud654\uba74\uc758 \ucc28\uc774\ub97c \uc77d\uc744 \uc218 \uc788\ub2e4. \uc9c0\uc2dd\uc740 \uc774\ub7f0 \uad6c\uccb4\uc801\uc778 \uad00\ucc30 \uc704\uc5d0 \ub367\ubd99\uc77c \ub54c \ub354 \uc624\ub798 \ub0a8\ub294\ub2e4. \uc81c\ub2e8 \ucabd \ubcbd\uc744 \ucc44\uc6b0\ub294 \u300c\ucd5c\ud6c4\uc758 \uc2ec\ud310\u300d\uc740 \ucc9c\uc7a5\ud654\ubcf4\ub2e4 \ud6d7\ub0a0\uc778 1530\ub144\ub300\uc640 1540\ub144\ub300\uc5d0 \uadf8\ub9b0 \uc791\uc5c5\uc774\ub2e4. \uac19\uc740 \uc608\ubc30\ub2f9, \uac19\uc740 \ud654\uac00\ub77c\ub294 \uc774\uc720\ub85c \ud55c \ubc88\uc5d0 \uc644\uc131\ud588\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \ud654\uac00\uc640 \ub85c\ub9c8\uac00 \uacaa\uc740 \uae34 \uc2dc\uac04\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \ucc9c\uc7a5\uacfc \ubcbd\uc740 \uc11c\ub85c \ub2e4\ub978 \uc2dc\uae30\uc758 \ub300\ud654\ub2e4. \uc5ec\uae30\uc5d0 \uc0ac\uc6a9\ud55c \uc774\ubbf8\uc9c0\ub294 \uc624\ub798\ub41c \ucd9c\ud310\ubb3c\uc5d0 \uc2e4\ub9b0 \uc2e4\uc81c \uc791\ud488\uc758 \uceec\ub7ec \ub3c4\ud310\uc774\ub2e4. \ud604\uc7ac \uc608\ubc30\ub2f9\uc758 \ud604\uc7a5 \ucd2c\uc601\uc740 \uc544\ub2c8\ubbc0\ub85c \ud654\uba74\uc758 \uc0c9\uacfc \ubcf4\uc874 \uc0c1\ud0dc\ub97c \uc624\ub298\uc758 \uc6d0\ud654\uc640 \ub3d9\uc77c\ud558\uac8c \ubcf4\uc544\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc775\uc219\ud55c \uc190\uac00\ub77d\uc744 \ucc3e\uc740 \ub4a4\uc5d0\ub294 \uc544\ub2f4\uc758 \uc790\uc138, \ub2e4\uac00\uc624\ub294 \ubb34\ub9ac, \uadf8\ub9bc\uc758 \ud2c0\uae4c\uc9c0 \uc2dc\uc120\uc744 \ub113\ud600 \ubcf4\uc790. \uc791\uc740 \ube48\ud2c8\uc774 \ud070 \ucc9c\uc7a5 \uc18d\uc5d0\uc11c \uc791\ub3d9\ud558\ub294 \ubc29\uc2dd\uc774 \ubcf4\uc77c \uac83\uc774\ub2e4."}, {"id": "sleepy-hollow-story-and-rumor", "title": "\uc2ac\ub9ac\ud53c \ud560\ub85c\uc758 \uc804\uc124 \u2014 \uba38\ub9ac \uc5c6\ub294 \uae30\uc0ac\ub294 \uc815\ub9d0 \ub098\ud0c0\ub0ac\uc744\uae4c", "summary": "\uc774\ucee4\ubcf4\ub4dc\uc758 \ubc24\uae38 \ucd94\uaca9\uc744 \ub530\ub77c \uc18c\ubb38\uacfc \uc695\ub9dd\uc774 \ub450\ub824\uc6c0\uc744 \ub9cc\ub4dc\ub294 \ubc29\uc2dd\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/sleepy-hollow-story-and-rumor/index.html", "image": "../media/sleepy-hollow-story-and-rumor.png", "alt": "\ub2ec\ube5b\uc758 \uc232\uae38\uacfc \ub2e4\ub9ac\ub97c \ud5a5\ud574 \ub9d0\uc744 \ud0c0\uace0 \uac00\ub294 \uac81\uba39\uc740 \uc120\uc0dd\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uc2ac\ub9ac\ud53c \ud560\ub85c\uc758 \uc804\uc124 \u2014 \uba38\ub9ac \uc5c6\ub294 \uae30\uc0ac\ub294 \uc815\ub9d0 \ub098\ud0c0\ub0ac\uc744\uae4c \uc6cc\uc2f1\ud134 \uc5b4\ube59\uc758 \uc6d0\uc791\uc744 \ub530\ub77c \uc77d\ub294 \ud5c8\ub4dc\uc2a8 \ub9c8\uc744\uc758 \uc18c\ubb38\uacfc \uacbd\uc7c1 \uc774\ucee4\ubcf4\ub4dc\uc758 \ubc24\uae38 \ucd94\uaca9\uc744 \ub530\ub77c \uc18c\ubb38\uacfc \uc695\ub9dd\uc774 \ub450\ub824\uc6c0\uc744 \ub9cc\ub4dc\ub294 \ubc29\uc2dd\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \ubc24\uae38\uc744 \ub2ec\ub9ac\ub294 \ub9d0 \ub4a4\ub85c \uc815\uccb4 \ubaa8\ub97c \uae30\uc218\uac00 \ub530\ub77c\uc628\ub2e4. \uba38\ub9ac\uac00 \uc5c6\ub294 \uc720\ub839\uc774\ub77c\ub294 \uc18c\ubb38\uc744 \uc54c\uace0 \uc788\ub294 \uc0ac\ub78c\uc774\ub77c\uba74 \uc791\uc740 \uadf8\ub9bc\uc790\ub3c4 \ub2e4\ub974\uac8c \ubcf4\uc77c \uac83\uc774\ub2e4. \uc6cc\uc2f1\ud134 \uc5b4\ube59\uc758 \u300e\uc2ac\ub9ac\ud53c \ud560\ub85c\uc758 \uc804\uc124\u300f\uc740 \uc774\ucc98\ub7fc \uc774\ubbf8 \ub4e4\uc740 \uc774\uc57c\uae30\uac00 \ub208\uc55e\uc758 \ud48d\uacbd\uc744 \ubc14\uafb8\ub294 \uacfc\uc815\uc744 \ub2a5\uc219\ud558\uac8c \uc774\uc6a9\ud55c\ub2e4. \ubb34\uc11c\uc6b4 \uadc0\uc2e0 \uc774\uc57c\uae30\ub85c \uc720\uba85\ud558\uc9c0\ub9cc \uc6d0\uc791\uc5d0\ub294 \uc2dd\uc695\uacfc \uacb0\ud63c, \uacbd\uc7c1\uc2ec\uacfc \ub9c8\uc744 \uc0ac\ub78c\ub4e4\uc758 \uc6c3\uc74c\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \uacb0\ub9d0\uae4c\uc9c0 \ub530\ub77c\uac00 \ubcf4\uba74 \uc791\uac00\ub294 \uc720\ub839\uc758 \uc874\uc7ac\ub97c \uae54\ub054\ud558\uac8c \uc99d\uba85\ud574 \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \ub3c5\uc790\uac00 \ubb34\uc5c7\uc744 \ubbff\uac8c \ub418\ub294\uc9c0 \uc790\uccb4\uac00 \uc774 \uc9e7\uc740 \uc774\uc57c\uae30\uc758 \uc7ac\ubbf8\ub2e4. \ubb34\ub300\ub294 \ub274\uc695 \ud5c8\ub4dc\uc2a8\uac15 \uc8fc\ubcc0\uc758 \uc2ac\ub9ac\ud53c \ud560\ub85c\ub2e4. \uc6d0\uc791\uc774 \uadf8\ub9ac\ub294 \uc9c0\uc5ed\uc5d0\ub294 \ub124\ub35c\ub780\ub4dc\uacc4 \uc815\ucc29\ubbfc\uc758 \ud48d\uc2b5\uacfc \uc774\uc57c\uae30\uac00 \ub0a8\uc544 \uc788\ub2e4. \ubbf8\uad6d\uc774\ub77c\ub294 \ud604\uc7ac\uc758 \uad6d\uac00 \uc774\ub984\ub9cc\uc73c\ub85c\ub294 \ub4dc\ub7ec\ub098\uc9c0 \uc54a\ub294 \uc2dd\ubbfc\uc9c0 \uc2dc\ub300\uc758 \ud754\uc801\uc774\ub2e4. \uc5b4\ube59\uc740 \uadf8 \uc9c0\uc5ed\uc801 \uc0c9\ucc44\ub97c \uc778\ubb3c\uacfc \uc74c\uc2dd, \uc9d1\uacfc \uc18c\ubb38\uc758 \ubd84\uc704\uae30\uc5d0 \ub2f4\ub294\ub2e4. \ub9c8\uc744\uc740 \ub290\ub9ac\uace0 \ubabd\uc0c1\uc801\uc778 \uacf3\ucc98\ub7fc \ubb18\uc0ac\ub41c\ub2e4. \ud558\uc9c0\ub9cc \uc774\uac83\uc744 \uac1d\uad00\uc801\uc778 \uc9c0\uc5ed \uc548\ub0b4\ub85c\ub9cc \uc77d\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc774\uc57c\uae30\uafbc\uc774 \ud2b9\ubcc4\ud55c \ubd84\uc704\uae30\ub97c \ub9cc\ub4e4\uae30 \uc704\ud574 \uc120\ud0dd\ud55c \ud45c\ud604\uc774\ub2e4. \uc5b4\ub5a4 \uc7a5\uc18c\uac00 \uae30\ubb18\ud55c \uc804\uc124\uc5d0 \uc5b4\uc6b8\ub9ac\ub294 \uacf3\uc73c\ub85c \uc18c\uac1c\ub418\ub294 \uc21c\uac04\ubd80\ud130 \ub3c5\uc790\uc758 \uae30\ub300\ub3c4 \uc774\ubbf8 \ubc29\ud5a5\uc744 \uc7a1\ub294\ub2e4. \uc774\ucee4\ubcf4\ub4dc \ud06c\ub808\uc778\uc740 \ub9c8\uc744\uc758 \ud559\uad50 \uc120\uc0dd\uc774\ub2e4. \uccb4\uaca9\uacfc \ud589\ub3d9\uc774 \uc6b0\uc2a4\uaf5d\uc2a4\ub7fd\uac8c \ubb18\uc0ac\ub418\uace0, \ub2e4\ub978 \uc9d1\uc5d0\uc11c \ub300\uc811\ubc1b\ub294 \uc74c\uc2dd\uc5d0 \ud070 \uad00\uc2ec\uc744 \ubcf4\uc778\ub2e4. \ucc45\uc744 \uc77d\uace0 \uc774\uc57c\uae30\ub97c \uc544\ub294 \uc0ac\ub78c\uc774\uc9c0\ub9cc \uadf8\ub7f0 \uc9c0\uc2dd\uc774 \uc5b8\uc81c\ub098 \uce68\ucc29\ud568\uc744 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc624\ud788\ub824 \ucd08\uc790\uc5f0\uc801\uc778 \uc18c\ubb38\uc744 \ud48d\ubd80\ud558\uac8c \uc0c1\uc0c1\ud558\ub294 \uc7ac\ub8cc\uac00 \ub41c\ub2e4. \uadf8\uc758 \uc695\ub9dd\ub3c4 \uc21c\uc218\ud55c \uc0ac\ub791 \ud55c \uac00\uc9c0\uac00 \uc544\ub2c8\ub2e4. \uce74\ud2b8\ub9ac\ub098\uc758 \uc9d1\uacfc \ud48d\uc694\ub85c\uc6b4 \uc0dd\ud65c\uc744 \ubcf4\uba74\uc11c \uacb0\ud63c \ub4a4\uc758 \ubbf8\ub798\ub97c \uc0c1\uc0c1\ud55c\ub2e4. \uc778\ubb3c\uc744 \uc624\uc9c1 \uac81 \ub9ce\uc740 \ud53c\ud574\uc790\ub85c\ub9cc \ubcf4\uba74 \uc774 \uc0dd\ud65c\uc801\uc778 \uba74\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \uc5b4\ube59\uc740 \uadf8\uac00 \ubb34\uc5c7\uc744 \ub450\ub824\uc6cc\ud558\ub294\uc9c0\uc640 \ubb34\uc5c7\uc744 \ud0d0\ub0b4\ub294\uc9c0\ub97c \ud568\uaed8 \ubcf4\uc5ec \uc900\ub2e4. \uce74\ud2b8\ub9ac\ub098\ub97c \ub458\ub7ec\uc2fc \uacbd\uc7c1\uc790 \ube0c\ub86c \ubcf8\uc2a4\ub294 \ubab8\uc774 \uac74\uc7a5\ud558\uace0 \ub9d0\ud0c0\uae30\uc5d0 \ub2a5\ud558\ub2e4. \uc774\ucee4\ubcf4\ub4dc\uc758 \uac00\ub298\uace0 \uc5b4\uc124\ud508 \ubaa8\uc2b5\uacfc \ub300\uc870\ub41c\ub2e4. \uadf8\ub294 \ub9c8\uc744\uc758 \uc7a5\ub09c\uacfc \uc774\uc57c\uae30\uc5d0 \uc801\uadf9\uc801\uc73c\ub85c \ucc38\uc5ec\ud558\ub294 \uc778\ubb3c\uc774\ub2e4. \ub450 \uc0ac\ub78c\uc758 \uacbd\uc7c1\uc740 \uc678\ubaa8\uc758 \ucc28\uc774\ubfd0 \uc544\ub2c8\ub77c \uadf8 \uc9c0\uc5ed\uc5d0\uc11c \ud798\uc744 \ubc1c\ud718\ud558\ub294 \ubc29\uc2dd\uc758 \ucc28\uc774\uc774\uae30\ub3c4 \ud558\ub2e4. \uadf8\ub7ec\ub098 \uce74\ud2b8\ub9ac\ub098\uc758 \ub9c8\uc74c\uae4c\uc9c0 \ub3c5\uc790\uac00 \uc804\ubd80 \uc548\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774\ucee4\ubcf4\ub4dc\uac00 \ubc14\ub77c\ub294 \ubbf8\ub798\uc640 \uc2e4\uc81c \uc0c1\ub300\uc758 \ub73b\uc740 \uac19\uc740 \uac83\uc774 \uc544\ub2c8\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc9d1\uacfc \uc7ac\uc0b0\uc744 \uc790\uc138\ud788 \uc0c1\uc0c1\ud558\ub294 \ub3d9\uc548, \uc815\uc791 \uadf8 \uc0ac\ub78c\uc758 \uc758\uc0ac\ub97c \ucda9\ubd84\ud788 \uc544\ub294\uc9c0\ub294 \ubcc4\uac1c\uc758 \ubb38\uc81c\ub85c \ub0a8\ub294\ub2e4. \uce74\ud2b8\ub9ac\ub098\uc758 \uc9d1\uc5d0\uc11c \uc5f4\ub9b0 \ubaa8\uc784\uc5d0\ub294 \uc74c\uc2dd\uacfc \ucda4, \uc804\uc7c1\uacfc \uc720\ub839\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\uac00 \uc774\uc5b4\uc9c4\ub2e4. \uadf8\uc911 \uc911\uc694\ud55c \uac83\uc774 \uba38\ub9ac \uc5c6\ub294 \uae30\uc218\uc758 \uc18c\ubb38\uc774\ub2e4. \uc804\uc7c1 \uc911 \uba38\ub9ac\ub97c \uc783\uc740 \ubcd1\uc0ac\uac00 \ubc24\uc5d0 \ub3cc\uc544\ub2e4\ub2cc\ub2e4\ub294 \uc804\uc124\uc774 \ub4e3\ub294 \uc0ac\ub78c\uc758 \uc0c1\uc0c1\ub825\uc744 \uc790\uadf9\ud55c\ub2e4. \uadc0\uac00\ud558\uae30 \uc804\ubd80\ud130 \uc774\ucee4\ubcf4\ub4dc\ub294 \uc774\ubbf8 \uadf8 \uc774\uc57c\uae30\ub97c \uc54c\uace0 \uc788\ub2e4. \uadf8\ub798\uc11c \ubc24\uae38\uc758 \uc18c\ub9ac\uc640 \ub098\ubb34, \uc5b4\ub460 \uc18d \ud615\uc0c1\uc774 \uc911\ub9bd\uc801\uc778 \ud48d\uacbd\uc73c\ub85c \ub0a8\uc9c0 \uc54a\ub294\ub2e4. \ub0ae\uc5d0 \ubcf4\uc558\ub2e4\uba74 \uc9c0\ub098\ucce4\uc744 \uc0ac\ubb3c\uc774 \uc804\uc124\uc744 \ud655\uc778\ud558\ub294 \uc99d\uac70\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uacf5\ud3ec\ub294 \uac11\uc790\uae30 \ub098\ud0c0\ub09c \ub300\uc0c1\ub9cc\uc774 \uc544\ub2c8\ub77c \uc55e\uc11c \ub4e4\uc740 \ub9d0\uc5d0\uc11c \uc790\ub77c\ub09c\ub2e4. \ub3cc\uc544\uac00\ub294 \uae38\uc5d0 \uc774\ucee4\ubcf4\ub4dc\ub294 \uc815\uccb4 \ubaa8\ub97c \uae30\uc218\ub97c \ub9cc\ub09c\ub2e4. \uc0c1\ub300\uc758 \uba38\ub9ac\uac00 \uc788\uc5b4\uc57c \ud560 \uc790\ub9ac\uac00 \uc774\uc0c1\ud558\ub2e4\ub294 \uac83\uc744 \uc54c\uc544\ucc28\ub9ac\uba74\uc11c \ub450\ub824\uc6c0\uc774 \ucee4\uc9c4\ub2e4. \ub9d0\uc744 \ubab0\uc544 \ub2ec\uc544\ub098\ub294 \uc7a5\uba74\uc5d0\uc11c\ub294 \uadf8\uac00 \uae30\uc5b5\ud558\ub294 \uc804\uc124\uc774 \ud589\ub3d9\uc758 \ubc29\ud5a5\uc744 \uc815\ud55c\ub2e4. \ub2e4\ub9ac\uc640 \uacbd\uacc4\uac00 \ub2e8\uc21c\ud55c \uc9c0\ud615 \uc774\uc0c1\uc758 \uc758\ubbf8\ub97c \uac16\ub294\ub2e4. \uae30\uc218\ub294 \ub05d\ub0b4 \ubb34\uc5c7\uc778\uac00\ub97c \ub358\uc9c0\uace0 \uc774\ucee4\ubcf4\ub4dc\ub294 \uc4f0\ub7ec\uc9c4\ub2e4. \ub2e4\uc74c \ub0a0 \uadf8 \uc790\uc2e0\uc740 \uc0ac\ub77c\uc838 \uc788\uace0 \ubaa8\uc790\uc640 \uae68\uc9c4 \ud638\ubc15\uc774 \ubc1c\uacac\ub41c\ub2e4. \ubb34\uc11c\uc6b4 \ubc24\uc758 \uc0ac\uac74\uacfc \uc6b0\uc2a4\uc6b4 \ubb3c\uac74\uc774 \ub098\ub780\ud788 \ub193\uc778\ub2e4. \ub3c5\uc790\ub294 \uc790\uc2e0\uc774 \ubc29\uae08 \uc77d\uc740 \ucd94\uaca9 \uc7a5\uba74\uc744 \ucc98\uc74c\uacfc \ub611\uac19\uc774 \ubbff\uc744 \uc218 \uc788\ub294\uc9c0 \ub2e4\uc2dc \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \ube0c\ub86c\uc758 \ubc18\uc751\uc740 \uc0ac\uac74\uc5d0 \uc7a5\ub09c\uc774 \uac1c\uc785\ud588\uc744 \uac00\ub2a5\uc131\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \ub2e4\ub978 \uc18c\uc2dd\uc5d0\uc11c\ub294 \uc774\ucee4\ubcf4\ub4dc\uac00 \uc0b4\uc544\uc11c \ub2e4\ub978 \uacf3\uc73c\ub85c \uac14\ub2e4\uace0 \uc804\ud558\uae30\ub3c4 \ud55c\ub2e4. \ud558\uc9c0\ub9cc \ub9c8\uc744\uc758 \uc720\ub839 \uc774\uc57c\uae30\uac00 \uadf8 \ub54c\ubb38\uc5d0 \uc644\uc804\ud788 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac19\uc740 \ud754\uc801\uc744 \ub450\uace0\ub3c4 \uc0ac\ub78c\ub9c8\ub2e4 \ub2e4\ub978 \uc124\uba85\uc744 \ud0dd\ud55c\ub2e4. \uc6d0\uc791\uc740 \uc218\uc0ac \ubcf4\uace0\uc11c\ucc98\ub7fc \uc9c4\uc0c1\uc744 \ub9c8\uc9c0\ub9c9 \ubb38\uc7a5\uc5d0 \uc815\ub9ac\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub204\uad6c\uc5d0\uac8c\uc11c \ub4e4\uc740 \ub9d0\uc778\uc9c0, \ub204\uac00 \uc6c3\ub294\uc9c0, \uc5b4\ub5a4 \uc99d\uac70\uac00 \ub0a8\uc558\ub294\uc9c0\ub97c \ubc30\uc5f4\ud55c\ub2e4. \ub3c5\uc790\ub294 \ucd08\uc790\uc5f0\uc801\uc778 \uc124\uba85\uacfc \ud604\uc2e4\uc801\uc778 \uc18d\uc784\uc218 \uc0ac\uc774\ub97c \uc624\uac04\ub2e4. \uacb0\ub860\uc744 \ubbf8\ub8e8\ub294 \ubc29\uc2dd\uc774\uc57c\ub9d0\ub85c \uc804\uc124\uc774 \uacc4\uc18d \uc804\ud574\uc9c8 \uc5ec\uc9c0\ub97c \ub9cc\ub4e0\ub2e4. \u300e\uc2ac\ub9ac\ud53c \ud560\ub85c\uc758 \uc804\uc124\u300f\uc744 \ub2e8\uc21c\ud55c \uadc0\uc2e0\uc758 \ucd9c\ud604 \uae30\ub85d\uc73c\ub85c \uc77d\uc73c\uba74 \ub9c8\uc9c0\ub9c9\uc758 \uc7a5\ub09c\uc2a4\ub7ec\uc6b4 \ubd84\uc704\uae30\ub97c \ub193\uce5c\ub2e4. \uc5b4\ube59\uc740 \ub450\ub824\uc6c0\uc5d0 \ube60\uc9c4 \uc0ac\ub78c\uc744 \uc6c3\uae30\uac8c \uadf8\ub9ac\uba74\uc11c\ub3c4 \uadf8 \ub450\ub824\uc6c0\uc774 \uc5b4\ub5bb\uac8c \uc124\ub4dd\ub825\uc744 \uc5bb\ub294\uc9c0 \uc138\ubc00\ud558\uac8c \ubcf4\uc5ec \uc900\ub2e4. \uc9c0\uc2dd\uc744 \uac00\uc9c4 \uc120\uc0dd\ub3c4 \uc790\uc2e0\uc774 \ubbff\uace0 \uc2f6\uc740 \uac83\uacfc \ubb34\uc11c\uc6cc\ud558\ub294 \uac83\uc5d0\uc11c \uc790\uc720\ub86d\uc9c0 \uc54a\ub2e4. \uc774\ucee4\ubcf4\ub4dc\uac00 \ud0c0\ub294 \ub9d0\uc758 \uc774\ub984\uc740 \uac74\ud30c\uc6b0\ub354\ub2e4. \uc774\ub984\uacfc \ub2ec\ub9ac \uadf8 \ub9d0\uc758 \ubaa8\uc2b5\uc740 \uc601\uc6c5\uc758 \ud798\ucc2c \ub9d0\uacfc \uac70\ub9ac\uac00 \uc788\ub2e4. \uae34\ubc15\ud55c \ucd94\uaca9\uc5d0\uc11c\ub3c4 \uc774\ub7f0 \uc6b0\uc2a4\uc6b4 \ub300\ube44\uac00 \ub0a8\ub294\ub2e4. \ub3c5\uc790\ub294 \ubb34\uc11c\uc6cc\ud558\ub294 \ub3d9\uc2dc\uc5d0 \uc774 \uc7a5\uba74\uc774 \uc774\uc57c\uae30\uafbc\uc758 \uc6c3\uc74c \uc18d\uc5d0 \uc788\ub2e4\ub294 \uac83\uc744 \ub290\ub084 \uc218 \uc788\ub2e4. \uc624\ub298\uc758 \ub3c5\uc790\ub3c4 \ub0af\uc120 \uc7a5\uc18c\uc5d0 \ub300\ud55c \uc18c\ubb38\uc744 \uba3c\uc800 \ub4e4\uc73c\uba74 \ud48d\uacbd\uc744 \ub2e4\ub974\uac8c \uc77d\uace4 \ud55c\ub2e4. \uc774 \uc791\ud488\uc758 \uc624\ub798\ub41c \ubc24\uae38\uc740 \uadf8\ub7f0 \uacbd\ud5d8\uc744 \ub418\ub3cc\uc544\ubcf4\uac8c \ud55c\ub2e4. \uba38\ub9ac \uc5c6\ub294 \uae30\uc0ac\uac00 \uc788\uc5c8\ub294\uac00\ub77c\ub294 \uc9c8\ubb38 \uacc1\uc5d0, \uc0ac\ub78c\ub4e4\uc740 \uc65c \uc5b4\ub5a4 \uc774\uc57c\uae30\ub97c \ubbff\uace0 \ubc18\ubcf5\ud558\ub294\uac00\ub77c\ub294 \uc9c8\ubb38\uc774 \uc624\ub798 \ub0a8\ub294\ub2e4."}, {"id": "socrates-life-and-questions", "title": "\uc18c\ud06c\ub77c\ud14c\uc2a4\uc758 \uc0dd\uc560 \u2014 \uc9c8\ubb38\uc744 \uba48\ucd94\uc9c0 \uc54a\uc740 \uc0ac\ub78c", "summary": "\uc9c1\uc811 \ub0a8\uae34 \uc800\uc220 \uc5c6\uc774\ub3c4 \uc624\ub798 \uae30\uc5b5\ub418\ub294 \ucca0\ud559\uc790\ub97c \uc9c8\ubb38\uacfc \uc7ac\ud310\uc758 \uc7a5\uba74\uc5d0\uc11c \ub9cc\ub098 \ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ucca0\ud559", "categories": ["arts"], "url": "stories/socrates-life-and-questions/index.html", "image": "../media/socrates-life-and-questions.jpg", "alt": "\uc790\ud06c \ub8e8\uc774 \ub2e4\ube44\ub4dc, \uc18c\ud06c\ub77c\ud14c\uc2a4\uc758 \uc8fd\uc74c(1787) \u00b7 Metropolitan Museum of Art / Wikimedia Commons, CC0 1.0; OpenStax \uc218\ub85d\ubcf8", "text": "\uc18c\ud06c\ub77c\ud14c\uc2a4\uc758 \uc0dd\uc560 \u2014 \uc9c8\ubb38\uc744 \uba48\ucd94\uc9c0 \uc54a\uc740 \uc0ac\ub78c \uc544\ud14c\ub124\uc758 \ub300\ud654\uc5d0\uc11c \ubc95\uc815\uc758 \ubcc0\ub860\uae4c\uc9c0 \uc9c1\uc811 \ub0a8\uae34 \uc800\uc220 \uc5c6\uc774\ub3c4 \uc624\ub798 \uae30\uc5b5\ub418\ub294 \ucca0\ud559\uc790\ub97c \uc9c8\ubb38\uacfc \uc7ac\ud310\uc758 \uc7a5\uba74\uc5d0\uc11c \ub9cc\ub098 \ubd05\ub2c8\ub2e4. \ucca0\ud559 \ubb38\ud654\uc640 \uc608\uc220 \ub204\uad70\uac00\uc5d0\uac8c \u2018\uc88b\uc740 \uc0ac\ub78c\uc740 \uc5b4\ub5a4 \uc0ac\ub78c\uc778\uac00\uc694?\u2019\ub77c\ub294 \uc9c8\ubb38\uc744 \ubc1b\uc558\ub2e4\uace0 \ud574 \ubcf4\uc790. \uce5c\uc808\ud55c \uc0ac\ub78c\uc774\ub77c\uace0 \ub2f5\ud558\uba74 \uace7 \ub2e4\uc74c \uc9c8\ubb38\uc774 \uc628\ub2e4. \uc0c1\ub300\ub97c \uc704\ud574 \uac70\uc9d3\ub9d0\ud558\ub294 \uac83\ub3c4 \uce5c\uc808\ud55c\uac00, \ub098\uc05c \uc77c\uc744 \ub3c4\uc640\uc8fc\ub294 \uce5c\uc808\uc740 \uc5b4\ub5a4\uac00. \uc775\uc219\ud55c \ub9d0 \ud558\ub098\uac00 \uac11\uc790\uae30 \ub0af\uc124\uc5b4\uc9c4\ub2e4. \uae30\uc6d0\uc804 5\uc138\uae30 \uc544\ud14c\ub124\uc5d0\uc11c \ud65c\ub3d9\ud55c \uc18c\ud06c\ub77c\ud14c\uc2a4\ub294 \uc774\ub7f0 \uc2dd\uc73c\ub85c \uc0ac\ub78c\ub4e4\uc774 \uc548\ub2e4\uace0 \uc0dd\uac01\ud55c \uac83\uc758 \uadfc\uac70\ub97c \ub2e4\uc2dc \uc0b4\ud53c\uac8c \ud558\ub294 \uc778\ubb3c\ub85c \uc804\ud574\uc9c4\ub2e4. \uc704\uc758 \ubb38\ub2f5\uc740 \uadf8\uc758 \uc2e4\uc81c \ubc1c\uc5b8\uc744 \uc778\uc6a9\ud55c \uac83\uc774 \uc544\ub2c8\ub77c \uc9c8\ubb38\uc758 \ubc29\uc2dd\uc744 \uc124\uba85\ud558\uae30 \uc704\ud574 \ub9cc\ub4e0 \uc608\ub2e4. \ucca0\ud559\uc790\uc758 \uc0dd\uc560\ub3c4 \uba85\uc5b8\uc744 \uba87 \uac1c \uc678\uc6b0\ub294 \uac83\ubcf4\ub2e4 \uadf8\uac00 \ub204\uad6c\uc5d0\uac8c \ubb34\uc5c7\uc744 \ubb3c\uc5c8\uace0 \uc65c \uac08\ub4f1\uc744 \uacaa\uc5c8\ub294\uc9c0 \ub530\ub77c\uac00\uba74 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \uc18c\ud06c\ub77c\ud14c\uc2a4\ub294 \ucca0\ud559 \uc800\uc220\uc744 \ub0a8\uae30\uc9c0 \uc54a\uc558\ub2e4. \uc6b0\ub9ac\ub294 \uc8fc\ub85c \ud50c\ub77c\ud1a4\uc744 \ube44\ub86f\ud55c \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc758 \uae00\uc744 \ud1b5\ud574 \uadf8\ub97c \ub9cc\ub09c\ub2e4. \ub530\ub77c\uc11c \uc804\ud574\uc9c0\ub294 \ubaa8\ub4e0 \ubb38\uc7a5\uc744 \uadf8\uac00 \uc2e4\uc81c\ub85c \uadf8 \uc790\ub9ac\uc5d0\uc11c \ud55c \ub9d0\uacfc \ub611\uac19\ub2e4\uace0 \uc77d\uc744 \uc218\ub294 \uc5c6\ub2e4. \uc5ed\uc0ac \uc18d \uc778\ubb3c\uacfc \uc791\uac00\uac00 \uadf8\ub9b0 \uc778\ubb3c\uc744 \uad6c\ubcc4\ud558\ub294 \uc8fc\uc758\uac00 \ud544\uc694\ud558\ub2e4. \uc774\ub294 \uc18c\ud06c\ub77c\ud14c\uc2a4\ub97c \uc54c \uc218 \uc5c6\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uc885\ub958\uc758 \uc790\ub8cc\ub85c \uadf8\ub97c \ub9cc\ub098\ub294\uc9c0 \uc54c\uace0 \uc77d\uc790\ub294 \ub73b\uc774\ub2e4. \ud50c\ub77c\ud1a4\uc758 \ub300\ud654\ud3b8\uc5d0\uc11c\ub294 \uc18c\ud06c\ub77c\ud14c\uc2a4\uac00 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ubb3b\uace0 \uc0c1\ub300\uc758 \ub300\ub2f5\uc744 \uac80\ud1a0\ud55c\ub2e4. \ud55c \ucca0\ud559\uc790\uc758 \uc8fc\uc7a5\uc744 \ud56d\ubaa9\ubcc4\ub85c \uc815\ub9ac\ud55c \uad50\uacfc\uc11c\uc640 \ub2ec\ub9ac, \uc0dd\uac01\uc774 \ub9c9\ud788\uace0 \ubc14\ub00c\ub294 \uacfc\uc815\uae4c\uc9c0 \ubb38\ud559\uc801 \ud615\uc2dd\uc73c\ub85c \ubcf4\uc5ec \uc900\ub2e4. \uc544\ud14c\ub124\uc5d0\uc11c\ub294 \uc2dc\ubbfc\ub4e4\uc774 \uc815\uce58\uc640 \uc7ac\ud310\uc5d0 \ucc38\uc5ec\ud588\uace0 \uacf5\uac1c\uc801\uc73c\ub85c \ub9d0\ud558\ub294 \ub2a5\ub825\uc774 \uc911\uc694\ud588\ub2e4. \ubb3c\ub860 \uc624\ub298\ub0a0\uc758 \ubcf4\ud1b5\uc120\uac70 \uc0ac\ud68c\uc640 \uac19\uc9c0\ub294 \uc54a\uc73c\uba70 \uc5ec\uc131\uacfc \ub178\uc608 \ub4f1 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uc2dc\ubbfc \uc815\uce58\uc5d0\uc11c \ubc30\uc81c\ub418\uc5c8\ub2e4. \uc774\ub7f0 \ub3c4\uc2dc\uc5d0\uc11c \uc9c0\ud61c\uc640 \ub355\uc744 \uc548\ub2e4\uace0 \ub9d0\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c \uacc4\uc18d \uc9c8\ubb38\ud558\ub294 \uc77c\uc740 \ub2e8\uc21c\ud55c \ub9d0\ub180\uc774\uc5d0 \uba38\ubb3c\uc9c0 \uc54a\ub294\ub2e4. \ud6cc\ub96d\ud55c \uc2dc\ubbfc, \uc815\uc758, \uacbd\uac74\ud568\uc774 \ubb34\uc5c7\uc778\uc9c0 \ubb3b\ub294 \uc21c\uac04 \uc0ac\ub78c\ub4e4\uc774 \uc758\uc9c0\ud558\ub294 \ud310\ub2e8\uc758 \uae30\uc900\uc774 \ud754\ub4e4\ub9b4 \uc218 \uc788\ub2e4. \ub9ce\uc740 \uc0ac\ub78c \uc55e\uc5d0\uc11c \uc124\uba85\uc774 \ub9c9\ud788\ub294 \uacbd\ud5d8\uc740 \ubd88\ud3b8\ud558\ub2e4. \uc18c\ud06c\ub77c\ud14c\uc2a4\uc758 \uc9c8\ubb38\uc740 \ubc30\uc6c0\uc758 \uacc4\uae30\uac00 \ub420 \uc218 \uc788\uc5c8\uc9c0\ub9cc \ubc18\uac10\uacfc \uc758\uc2ec\ub3c4 \ubd88\ub7ec\uc62c \uc218 \uc788\ub294 \ud65c\ub3d9\uc774\uc5c8\ub2e4. \ud50c\ub77c\ud1a4\uc758 \u300e\uc18c\ud06c\ub77c\ud14c\uc2a4\uc758 \ubcc0\uba85\u300f\uc5d0\uc11c \uc18c\ud06c\ub77c\ud14c\uc2a4\ub294 \ub378\ud3ec\uc774\uc758 \uc2e0\ud0c1\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\ub97c \ub4e4\ub824\uc900\ub2e4. \uce5c\uad6c \uce74\uc774\ub808\ud3f0\uc774 \uc790\uc2e0\ubcf4\ub2e4 \uc9c0\ud61c\ub85c\uc6b4 \uc0ac\ub78c\uc774 \uc788\ub294\uc9c0 \ubb3c\uc5c8\uace0 \uc5c6\ub2e4\ub294 \ub2f5\uc744 \ubc1b\uc558\ub2e4\uace0 \ud55c\ub2e4. \uc18c\ud06c\ub77c\ud14c\uc2a4\ub294 \uc790\uc2e0\uc774 \ub300\ub2e8\ud55c \uc9c0\uc2dd\uc744 \uac00\uc84c\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\uc558\uae30\uc5d0 \uadf8 \ub73b\uc744 \uc54c\uc544\ubcf4\ub824 \ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\ub294 \uc815\uce58\uac00\uc640 \uc2dc\uc778, \uc7a5\uc778\ub4e4\uc744 \ucc3e\uc544\uac00 \ubb3b\ub294\ub2e4. \uadf8\uc911\uc5d0\ub294 \uc2e4\uc81c\ub85c \ub6f0\uc5b4\ub09c \uc19c\uc528\ub97c \uac00\uc9c4 \uc0ac\ub78c\ub3c4 \uc788\uc9c0\ub9cc, \uc790\uae30 \ubd84\uc57c\uc758 \ub2a5\ub825\uc744 \uc774\uc720\ub85c \ub2e4\ub978 \uc911\uc694\ud55c \uc77c\uae4c\uc9c0 \ubaa8\ub450 \uc548\ub2e4\uace0 \uc0dd\uac01\ud558\ub294 \uacbd\uc6b0\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \ud55c \uac00\uc9c0\ub97c \uc798\ud55c\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ubaa8\ub4e0 \ud310\ub2e8\uc5d0 \uad8c\uc704\ub97c \uac00\uc9c4\ub2e4\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4\ub294 \ubb38\uc81c\ub2e4. \uc774 \uc774\uc57c\uae30\uc5d0\uc11c \uc911\uc694\ud55c \uac83\uc740 \uc790\uc2e0\uc774 \ubaa8\ub974\ub294 \uac83\uc744 \uc548\ub2e4\uace0 \uc5ec\uae30\uc9c0 \uc54a\uc73c\ub824\ub294 \ud0dc\ub3c4\ub2e4. \uadf8\ub798\uc11c \uc18c\ud06c\ub77c\ud14c\uc2a4\uc758 \ubb34\uc9c0\ub294 \uc544\ubb34\uac83\ub3c4 \ubc30\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4\ub294 \uba74\ud5c8\uac00 \uc544\ub2c8\ub2e4. \uc790\uc2e0\uc774 \uac00\uc9c4 \ub300\ub2f5\uc774 \uc5b4\ub514\uae4c\uc9c0 \uc720\ud6a8\ud55c\uc9c0 \uc0b4\ud53c\ub294 \ucd9c\ubc1c\uc810\uc5d0 \uac00\uae5d\ub2e4. \uc6a9\uae30\ub97c \ub450\ub824\uc6c0 \uc5c6\ub294 \ud589\ub3d9\uc774\ub77c\uace0 \uc815\uc758\ud574 \ubcf4\uc790. \uadf8\ub807\ub2e4\uba74 \uc704\ud5d8\uc744 \ubab0\ub77c \ubb34\ubaa8\ud558\uac8c \ub6f0\uc5b4\ub4e0 \uc0ac\ub78c\ub3c4 \uc6a9\uac10\ud55c\uac00. \ucc98\uc74c \ub2f5\uc774 \ubd80\uc871\ud558\ub2e4\ub294 \uac83\uc744 \uc54c\uba74 \uc704\ud5d8\uc744 \uc774\ud574\ud558\ub294 \ub2a5\ub825\uacfc \ud589\ub3d9\uc758 \uc774\uc720\ub97c \ub354 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uc774\uac83 \uc5ed\uc2dc \uc2e4\uc81c \ub300\ud654\ud3b8\uc758 \uc778\uc6a9\uc774 \uc544\ub2c8\ub77c \ubc29\ubc95\uc744 \ud480\uc5b4 \uc4f4 \uc608\ub2e4. \uc9c8\ubb38\uc740 \ub2f5\uc744 \uc5c6\uc560\uae30\ubcf4\ub2e4 \ub2f5\uc744 \ub354 \uc815\uad50\ud558\uac8c \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \uc18c\ud06c\ub77c\ud14c\uc2a4\ub294 \uae30\uc6d0\uc804 399\ub144 \ubd88\uacbd\uacfc \uc80a\uc740\uc774\ub4e4\uc744 \ud0c0\ub77d\uc2dc\ud0a8\ub2e4\ub294 \ud610\uc758\ub85c \uc7ac\ud310\uc744 \ubc1b\ub294\ub2e4. \uc80a\uc740 \uc0ac\ub78c\ub4e4\uc774 \uadf8\ub97c \ub530\ub77c \uc9c8\ubb38\ud558\ub294 \ud65c\ub3d9\uc744 \ud749\ub0b4 \ub0b4\uace0, \uadf8 \ub54c\ubb38\uc5d0 \uc6d0\ub9dd\uc774 \uc0dd\uacbc\ub2e4\ub294 \uc124\uba85\ub3c4 \u300e\ubcc0\uba85\u300f\uc5d0 \ub098\uc628\ub2e4. \uadf8\ub7ec\ub098 \uace0\ub300 \uc7ac\ud310\uc744 \uc624\ub298\uc758 \ud45c\ud604\uc758 \uc790\uc720 \uc0ac\uac74 \ud558\ub098\ub85c\ub9cc \ub2e8\uc21c\ud654\ud558\uba74 \ub2f9\uc2dc\uc758 \uc885\uad50\uc640 \uc2dc\ubbfc \uacf5\ub3d9\uccb4\uc758 \uad00\uacc4\ub97c \ub193\uce58\uac8c \ub41c\ub2e4. \u300e\ubcc0\uba85\u300f\uc758 \uc81c\ubaa9\ub3c4 \uc774\ud574\ud574 \ub450\uba74 \uc88b\ub2e4. \uc5ec\uae30\uc11c \ubcc0\uba85\uc740 \uc798\ubabb\uc744 \ud53c\ud558\ub824\uace0 \ud551\uacc4\ub97c \ub298\uc5b4\ub193\ub294\ub2e4\ub294 \uc77c\uc0c1\uc801 \ub73b\ubcf4\ub2e4 \ubc95\uc815\uc758 \uc790\uae30 \ubcc0\ub860\uc744 \uac00\ub9ac\ud0a8\ub2e4. \uc18c\ud06c\ub77c\ud14c\uc2a4\ub294 \ubc95\uc815\uc5d0\uc11c \uc790\uc2e0\uc774 \uc5b4\ub5a4 \uc77c\uc744 \ud574 \uc654\uc73c\uba70 \uc65c \uadf8 \ud65c\ub3d9\uc5d0 \uac00\uce58\uac00 \uc788\ub2e4\uace0 \ubcf4\ub294\uc9c0 \uc124\uba85\ud55c\ub2e4. \ud50c\ub77c\ud1a4\uc758 \uc791\ud488\uc744 \uc7ac\ud310\uc758 \ub179\uc74c\uc774\ub098 \uc18d\uae30\ub85d\ucc98\ub7fc \ucde8\uae09\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc791\ud488 \uc18d \uc18c\ud06c\ub77c\ud14c\uc2a4\ub294 \uccad\uc911\uc758 \ub3d9\uc815\uc2ec\uc744 \uc790\uadf9\ud558\ub294 \uac83\ub9cc\uc73c\ub85c \uc790\uc2e0\uc744 \uc0b4\ub9ac\ub824 \ud558\uc9c0 \uc54a\ub294\ub2e4. \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uc7ac\uc0b0\uacfc \ud3c9\ud310 \ubabb\uc9c0\uc54a\uac8c \uc790\uc2e0\uc758 \uc0b6\uacfc \ub9c8\uc74c\uc744 \ub3cc\ubcf4\ub77c\uace0 \uc694\uad6c\ud574 \uc654\ub2e4\uace0 \uc8fc\uc7a5\ud55c\ub2e4. \ubaa9\uc228\uc744 \uad6c\ud558\uae30 \uc704\ud574 \uadf8 \ud65c\ub3d9\uc744 \ubc84\ub9ac\ub294 \uac83\uc774 \uacfc\uc5f0 \uc633\uc740\uc9c0\ub3c4 \ubb3b\ub294\ub2e4. \uc774 \ud0dc\ub3c4\ub294 \ud6cc\ub96d\ud558\uac8c \ubcf4\uc77c \uc218 \uc788\uc9c0\ub9cc \ub2f9\uc2dc \ubc30\uc2ec\uc6d0 \ubaa8\ub450\uc5d0\uac8c \uc124\ub4dd\ub825 \uc788\uac8c \ub4e4\ub838\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uacb0\uad6d \uadf8\ub294 \uc720\uc8c4 \ud310\ub2e8\uacfc \uc0ac\ud615 \uc120\uace0\ub97c \ubc1b\ub294\ub2e4. \uc774\ub97c \u2018\ub611\ub611\ud55c \ud55c \uc0ac\ub78c\uacfc \uc5b4\ub9ac\uc11d\uc740 \ubaa8\ub4e0 \uc2dc\ubbfc\u2019\uc758 \uc2f8\uc6c0\uc73c\ub85c\ub9cc \uc77d\uae30\ubcf4\ub2e4, \uacf5\ub3d9\uccb4\uc758 \uc758\uc2ec \uc18d\uc5d0\uc11c\ub3c4 \uac1c\uc778\uc774 \uc9c0\ucf1c\uc57c \ud55c\ub2e4\uace0 \uc0dd\uac01\ud55c \uc6d0\uce59\uc774 \ubb34\uc5c7\uc774\uc5c8\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\ub294 \ud3b8\uc774 \uc791\ud488\uc744 \ub354 \uae4a\uac8c \uc77d\uac8c \ud55c\ub2e4. \ud50c\ub77c\ud1a4\uc758 \u300e\ud30c\uc774\ub3c8\u300f\uc740 \uac10\uc625\uc5d0\uc11c \ub9c8\uc9c0\ub9c9 \uc2dc\uac04\uc744 \ubcf4\ub0b4\ub294 \uc18c\ud06c\ub77c\ud14c\uc2a4\ub97c \ub300\ud654\uc758 \ud615\uc2dd\uc73c\ub85c \uc804\ud55c\ub2e4. \uc601\ud63c\uacfc \uc8fd\uc74c\uc5d0 \uad00\ud55c \ub17c\uc758 \ub05d\uc5d0 \ub3c5\uc57d\uc744 \ub9c8\uc2dc\ub294 \uc7a5\uba74\uc774 \ub098\uc628\ub2e4. \uc774 \uc5ed\uc2dc \ucca0\ud559\uc801 \ubaa9\uc801\uc744 \uac00\uc9c4 \uc791\ud488\uc774\ubbc0\ub85c \ub9c8\uc9c0\ub9c9 \ud558\ub8e8\ub97c \ube60\uc9d0\uc5c6\uc774 \uae30\ub85d\ud55c \ud604\uc7a5 \uc77c\uc9c0\uc640\ub294 \ub2e4\ub974\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc790\ud06c \ub8e8\uc774 \ub2e4\ube44\ub4dc\uc758 \u3008\uc18c\ud06c\ub77c\ud14c\uc2a4\uc758 \uc8fd\uc74c\u3009\uc740 1787\ub144\uc5d0 \uadf8\ub9b0 \ud6c4\ub300\uc758 \ud68c\ud654\ub2e4. \uace7\uac8c \uc549\uc740 \uc911\uc2ec \uc778\ubb3c\uacfc \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\uc758 \ubab8\uc9d3\uc744 \ube44\uad50\ud558\uba74, \ud654\uac00\uac00 \ucca0\ud559\uc790\uc758 \ub9c8\uc9c0\ub9c9\uc744 \uc5b4\ub5a4 \ud0dc\ub3c4\ub85c \ubcf4\uc774\uac8c \ud588\ub294\uc9c0 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uace0\ub300\uc778\uc758 \uc2e4\uc81c \uc5bc\uad74\uacfc \ud604\uc7a5\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc0ac\uc9c4 \uc790\ub8cc\ub85c \uc77d\uc9c0\ub294 \ub9d0\uc790. \uc18c\ud06c\ub77c\ud14c\uc2a4\uac00 \uc9c8\ubb38\ud588\ub2e4\ub294 \uc0ac\uc2e4\ub9cc \ubc30\uc6b0\uace0 \ub0a8\uc744 \ubab0\uc544\ubd99\uc774\ub294 \uae30\uc220\ub85c \uc4f0\uba74 \uc911\uc694\ud55c \ubd80\ubd84\uc744 \ub193\uce60 \uc218 \uc788\ub2e4. \uc790\uc2e0\uc758 \ub2f5 \uc5ed\uc2dc \uac80\ud1a0 \ub300\uc0c1\uc774\ub77c\ub294 \uc810\uc744 \ud568\uaed8 \uae30\uc5b5\ud574\uc57c \ud55c\ub2e4. \uc0c1\ub300\uc758 \ube48\ud2c8\uc744 \ucc3e\ub294 \uac83\uacfc \ub354 \ub098\uc740 \ud310\ub2e8\uc5d0 \ud568\uaed8 \uc774\ub974\ub294 \uac83\uc740 \uac19\uc9c0 \uc54a\ub2e4. \uc624\ub298 \uc790\uc2e0\uc774 \uc790\uc8fc \uc4f0\ub294 \ub9d0 \ud558\ub098\ub97c \uace8\ub77c \ubcf4\uc790. \uc131\uacf5, \ud589\ubcf5, \uc815\uc758 \uac19\uc740 \ub9d0\ub3c4 \uc88b\uace0 \uc88b\uc740 \uce5c\uad6c\ub77c\ub294 \ub9d0\ub3c4 \uc88b\ub2e4. \ub73b\uc744 \ud55c \ubb38\uc7a5\uc73c\ub85c \uc801\uace0 \uadf8 \uc815\uc758\uac00 \ub9de\uc9c0 \uc54a\ub294 \uacbd\uc6b0\ub97c \ud558\ub098 \ub5a0\uc62c\ub824 \ubcf4\uba74 \ub41c\ub2e4. \uace0\ub300 \ucca0\ud559\uc790\uc758 \uc0b6\uc740 \uadf8\ub807\uac8c \uc791\uc740 \uc9c8\ubb38\uc73c\ub85c \uc624\ub298\uc758 \uc0b6\uc5d0 \uc774\uc5b4\uc9c8 \uc218 \uc788\ub2e4. \uadf8\uc758 \uc8fd\uc74c\ub9cc \uae30\uc5b5\ud558\ub294 \uac83\uc5d0\uc11c, \uc0b4\uc544 \uc788\ub294 \ub3d9\uc548 \uacc4\uc18d\ud588\ub358 \uac80\ud1a0\ub97c \uc870\uae08 \ud574 \ubcf4\ub294 \ucabd\uc73c\ub85c \ub098\uc544\uac00\ub294 \uac83\uc774\ub2e4."}, {"id": "stone-chime-thickness", "title": "\uc774 \ub3cc\uc740 \ub450\ub4dc\ub9ac\uba74 \uc74c\uc774 \ub41c\ub2e4", "summary": "\uaebe\uc778 \ub3cc \ud55c \uc7a5\uc774 \uc545\uae30\uac00 \ub418\ub294 \ubc29\ubc95\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc74c\uc545", "categories": ["arts"], "url": "stories/stone-chime-thickness/index.html", "image": "../media/stone-chime-thickness.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \ud3b8\uacbd \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc774 \ub3cc\uc740 \ub450\ub4dc\ub9ac\uba74 \uc74c\uc774 \ub41c\ub2e4 \ud3b8\uacbd \ud55c \uc870\uac01\uc5d0\uc11c \uc2dc\uc791\ud558\ub294 \uc74c\uc545 \uc774\uc57c\uae30 \uaebe\uc778 \ub3cc \ud55c \uc7a5\uc774 \uc545\uae30\uac00 \ub418\ub294 \ubc29\ubc95\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc74c\uc545 \ubb38\ud654\uc640 \uc608\uc220 \uc0ac\uc9c4 \uc18d \ub3cc\uc740 \ud55c\ucabd\uc774 \uaebe\uc5ec \uc788\ub2e4. \ub05d\ubd80\ubd84\uc5d0 \uad6c\uba4d\ub3c4 \ud558\ub098 \ubcf4\uc778\ub2e4. \ub530\ub85c \ub193\uc73c\uba74 \ubb34\uc5c7\uc744 \ub9cc\ub4e4\ub2e4 \ub0a8\uae34 \uc870\uac01\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\uc9c0\ub9cc, \uc774\uac83\uc740 \uc18c\ub9ac\ub97c \ub0b4\ub294 \uc545\uae30\uc758 \ud55c \ubd80\ubd84\uc774\ub2e4. \uc774\ub984\uc740 \ud3b8\uacbd\uc774\ub2e4. \ud53c\uc544\ub178\uc758 \uac74\ubc18\uc774\ub098 \ubc14\uc774\uc62c\ub9b0\uc758 \uc904\ucc98\ub7fc \uc774 \uc545\uae30\uc5d0\uc11c\ub294 \ub3cc\uc774 \uc74c\uc744 \ub9e1\ub294\ub2e4. \ubb34\ub300 \uc704 \uc545\uae30\ub97c \ub5a0\uc62c\ub9ac\ub2e4\uac00 \uac11\uc790\uae30 \ub3cc\uc744 \ub9cc\ub098\ub2c8 \uc74c\uc545\uc758 \uc7ac\ub8cc\uac00 \uc0dd\uac01\ubcf4\ub2e4 \ub113\uac8c \ub290\uaef4\uc9c4\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc740 \uc625\uc11d\uc744 \uae4e\uc544 \ub9cc\ub4e0 \uacbd \uc5f4\uc5ec\uc12f \uac1c\ub97c \ub450 \ub2e8\uc758 \ud2c0\uc5d0 \uc5ec\ub35f \uac1c\uc529 \ub9e4\ub2ec\uc544 \uc5f0\uc8fc\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc0ac\uc9c4\uc758 \ud55c \uc870\uac01\uc744 \ubcf4\ub294 \uac83\uacfc \uc804\uccb4 \uc545\uae30\ub97c \uc0c1\uc0c1\ud558\ub294 \uc77c \uc0ac\uc774\uc5d0 \uc791\uc740 \uac04\uaca9\uc774 \uc788\ub2e4. \uad6c\uba4d\uc740 \uadf8 \uc870\uac01\uc774 \ud63c\uc790 \ub193\uc774\ub294 \ubb3c\uac74\uc774 \uc544\ub2c8\ub77c \ub9e4\ub2ec\ub9ac\ub294 \ubb3c\uac74\uc774\ub77c\ub294 \uc0ac\uc2e4\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uc774\ub984 \ubaa8\ub97c \ub3cc\uc774 \uc904\uc9c0\uc5b4 \uc18c\ub9ac\ub97c \ub0b4\ub294 \uc545\uae30\uc758 \ud55c \uc790\ub9ac\ub85c \uc62e\uaca8 \uac00\ub294 \uc21c\uac04\uc774\ub2e4. \uc774 \uc545\uae30\uc5d0\uc11c \uc7ac\ubbf8\uc788\ub294 \ubd80\ubd84\uc740 \uc74c\ub192\uc774\ub97c \ub3cc\uc758 \ub450\uaed8\ub85c \uc870\uc808\ud588\ub2e4\ub294 \uc810\uc774\ub2e4. \uc904\uc744 \ud33d\ud33d\ud558\uac8c \ub2f9\uae30\uac70\ub098 \uad00\uc758 \uad6c\uba4d\uc744 \ub9c9\ub294 \ubc29\uc2dd\uacfc\ub294 \ub2e4\ub974\ub2e4. \uae4e\uc544 \ub9cc\ub4e0 \ub3cc\uc758 \ub450\uaed8\uac00 \uc74c\uc545\uc744 \uc900\ube44\ud558\ub294 \uc77c\uc774 \ub418\ub294 \uac83\uc774\ub2e4. \uc5f0\uc8fc\ud560 \ub54c\ub294 \uc18c\ubfd4\ub85c \ub9cc\ub4e0 \ub3c4\uad6c\uc778 \uac01\ud1f4\ub85c \uacbd\uc758 \uc544\ub7ab\ubd80\ubd84\uc744 \ucce4\ub2e4\uace0 \ud55c\ub2e4. \ub3cc\uc774\ub77c\uace0 \uc544\ubb34 \ub9c9\ub300\ub098 \uac00\uc838\uc640 \ub450\ub4dc\ub9ac\ub294 \ubc29\uc2dd\uc740 \uc544\ub2c8\ub2e4. \uc18c\ub9ac\ub97c \ub0bc \ubb3c\uac74\uacfc \uadf8\uac83\uc744 \uce58\ub294 \ub3c4\uad6c\uac00 \ud568\uaed8 \uac16\ucd94\uc5b4\uc9c4\ub2e4. \uc0ac\uc9c4 \uc18d \uacbd \ud558\ub098\ub9cc \ubcf4\uba74 \ubaa8\uc591\uc774 \ub3c5\ud2b9\ud55c \ub3cc \uc870\uac01\uc73c\ub85c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc804\uccb4 \ud3b8\uacbd\uc5d0\uc11c\ub294 \uc5ec\ub7ec \uc74c\uc744 \ub9e1\ub294 \uacbd\ub4e4\uc774 \ud2c0\uc5d0 \ub098\ub780\ud788 \uac78\ub9b0\ub2e4. \uac01\uac01\uc758 \ubb3c\uac74\uacfc \uadf8 \ubb3c\uac74\ub4e4\uc774 \uc774\ub8e8\ub294 \ubc30\uc5f4\uc744 \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \uc4f0\uc784\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \uac19\uc740 \uc885\ub958\uc758 \uc7ac\ub8cc\uac00 \uc5ec\ub7ec \ub192\uc774\uc758 \uc18c\ub9ac\ub97c \ub0b4\ub3c4\ub85d \uc900\ube44\ub41c \uccb4\uacc4\uc600\ub2e4. \uc5f4\uc5ec\uc12f \uacbd\uc744 \ub450 \ub2e8\uc5d0 \uc5ec\ub35f \uac1c\uc529 \uac74\ub2e4\ub294 \uc124\uba85\uc740 \ub2e8\uc21c\ud55c \uac1c\uc218 \uc815\ubcf4 \uc774\uc0c1\uc774\ub2e4. \uc5f0\uc8fc\uc790\uac00 \uc18c\ub9ac\ub97c \uc120\ud0dd\ud560 \uc218 \uc788\ub294 \uc790\ub9ac\uac00 \ub9c8\ub828\ub418\uc5b4 \uc788\ub2e4\ub294 \ub73b\uc774\ub2e4. \ub2e4\ub9cc \uc774 \uc0ac\uc9c4\uc5d0\uc11c \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc804\uccb4 \ud2c0\uc758 \uc815\ud655\ud55c \uce58\uc218\ub97c \uc0c8\ub85c \ubcf5\uc6d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud55c \uc810\uc758 \uc18c\uc7a5\ud488\uacfc \uc545\uae30 \uc804\uccb4\uc758 \uad6c\uc131\uc744 \uae30\uad00 \uc124\uba85\uc744 \ud1b5\ud574 \uc5f0\uacb0\ud574 \uc77d\ub294 \uac83\uc774 \ucd9c\ubc1c\uc810\uc774\ub2e4. \ud3b8\uacbd\uc5d0\uc11c\ub294 \ub3cc\uc758 \ub450\uaed8\ub97c \uc870\uc808\ud574 \uc74c\ub192\uc774\ub97c \ub2e4\ub8e8\uc5c8\ub2e4\uace0 \uc790\ub8cc\ub294 \uc124\uba85\ud55c\ub2e4. \uc904\uc758 \uc7a5\ub825\uc744 \ubc14\uafb8\ub294 \uc545\uae30\uc640\ub294 \ub2e4\ub978 \uc900\ube44\ub2e4. \uc644\uc131\ub41c \uc870\uac01\uc758 \ubaa8\uc591\uc744 \uac10\uc0c1\ud558\ub294 \uc77c \uc606\uc5d0, \uc18c\ub9ac\uc758 \uc870\uac74\uc744 \ub9de\ucd94\uae30 \uc704\ud574 \uc7ac\ub8cc\ub97c \ub2e4\ub4ec\ub294 \uc77c\uc744 \ub193\uc744 \uc218 \uc788\ub2e4. \uacf5\uc608\uc640 \uc74c\uc545\uc774 \ubd84\ub9ac\ub418\uc5b4 \uc788\uc9c0 \uc54a\uc740 \ub300\ubaa9\uc774\ub2e4. \uc774\ub54c \ub450\uaed8 \ud558\ub098\ub9cc \ubcf4\uace0 \uc0ac\uc9c4 \uc18d \uacbd\uc774 \uc815\ud655\ud788 \uc5b4\ub5a4 \uc74c\uc744 \ub0b4\ub294\uc9c0 \uc54c\uc544\ub0bc \uc218\ub294 \uc5c6\ub2e4. \uc2e4\uc81c \uce58\uc218\uc640 \uc0c1\ud0dc, \uc5f0\uc8fc \uc870\uac74\uc744 \ud655\uc778\ud574\uc57c \ud560 \ubb38\uc81c\ub2e4. \uc18c\uc7a5\ud488 \uc0ac\uc9c4\uc744 \ubcf8 \uac10\uc0c1\uacfc \uc74c\ud5a5 \uce21\uc815\uc740 \ub2e4\ub978 \uc791\uc5c5\uc774\ub2e4. \ub2e4\ub9cc \uc190\uc73c\ub85c \uc7ac\ub8cc\ub97c \uae4e\uace0 \ud655\uc778\ud558\ub294 \uacfc\uc815\uc774 \uc74c\uc545\uc758 \ucd9c\ubc1c\uc810\uc774\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub208\uc55e\uc758 \ub3cc\uc744 \ub2e4\ub974\uac8c \ubcf4\uac8c \ud55c\ub2e4. \uac01\ud1f4\ub294 \uc18c\ubfd4\ub85c \ub9cc\ub4e0 \ud0c0\uaca9 \ub3c4\uad6c\ub85c \uc18c\uac1c\ub41c\ub2e4. \uc5f0\uc8fc\uc5d0\uc11c\ub294 \ubb34\uc5c7\uc744 \uce58\ub294\uc9c0\ub9cc \uc544\ub2c8\ub77c \ubb34\uc5c7\uc73c\ub85c \uc5b4\ub290 \ubd80\ubd84\uc744 \uce58\ub294\uc9c0\ub3c4 \uc911\uc694\ud558\ub2e4. \uae30\uad00\uc740 \uacbd\uc758 \uc544\ub7ab\ubd80\ubd84\uc744 \ucce4\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc18c\ub9ac \ub098\ub294 \ubb3c\uac74\uc744 \uc544\ubb34 \ubc29\uc2dd\uc73c\ub85c\ub098 \ub450\ub4dc\ub9ac\ub294 \uac83\uacfc, \uc815\ud574\uc9c4 \ub3c4\uad6c\uc640 \ub3d9\uc791\uc73c\ub85c \uc5f0\uc8fc\ud558\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uc624\ub298\uc758 \uad00\ub78c\uc790\ub294 \uc2e4\uc81c \uc720\ubb3c\uc744 \uc2dc\ud5d8 \uc0bc\uc544 \uccd0 \ubcfc \uc218 \uc5c6\ub2e4. \uc18c\ub9ac\ub97c \uc54c\uace0 \uc2f6\ub2e4\uba74 \uc801\uc808\ud55c \uc5f0\uc8fc \uc790\ub8cc\uc640 \ud574\uc124\uc744 \ucc3e\uc544\uc57c \ud55c\ub2e4. \ub300\uc2e0 \uad6c\uba4d\uacfc \ud615\ud0dc\ub97c \ubcf4\uba70 \ub9e4\ub2e4\ub294 \ubc29\uc2dd\uacfc \uc18c\ub9ac \ub0b4\ub294 \uc790\ub9ac\ub97c \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ubb3c\uac74\uc744 \uc190\uc0c1\uc2dc\ud0a4\uc9c0 \uc54a\uc73c\uba74\uc11c\ub3c4 \uc4f0\uc784\uc73c\ub85c \uc0c1\uc0c1\ud558\ub294 \uae38\uc774 \uc788\ub294 \uac83\uc774\ub2e4. \uc545\uae30\ub294 \ubcf4\uad00\ud560 \ub300\uc0c1\uc774\uba74\uc11c \uc6d0\ub798 \ud589\ub3d9\uc744 \uc704\ud574 \ub9cc\ub4e0 \ub3c4\uad6c\uc600\ub2e4. \ubc15\ubb3c\uad00\uc740 \ud3b8\uacbd\uc774 \uc870\uc120\uc2dc\ub300 \uc81c\ub840\uc640 \uc5f0\ub840\uc5d0 \uc0ac\uc6a9\ub418\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc18c\ub9ac\ub9cc\uc744 \ub530\ub85c \ub5bc\uc5b4 \ub4e3\ub294 \uacbd\ud5d8\uacfc \uc815\ud574\uc9c4 \uc790\ub9ac\uc5d0\uc11c \ub2e4\ub978 \uc545\uae30\uc640 \ud568\uaed8 \uc6b8\ub9ac\ub294 \uacbd\ud5d8\uc740 \ub2ec\ub790\uc744 \uac83\uc774\ub2e4. \uc74c\uc545\uc740 \uc74c\uc758 \ub192\uc774\ubfd0 \uc544\ub2c8\ub77c \uc5b8\uc81c \uc5b4\ub514\uc5d0\uc11c \ub204\uad6c\uc640 \ud568\uaed8 \ub0b4\ub294\uc9c0\uc758 \uc57d\uc18d\ub3c4 \uac00\uc9c4\ub2e4. \ub3cc\uc744 \ub2e4\ub4ec\uc740 \uae30\uc220\uc774 \uacf5\ub3d9\uc758 \ud589\uc0ac \uc548\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \uc21c\uac04\uc774\ub2e4. \uc774 \ud55c \uc810\uc758 \uc774\ub825\ub9cc\uc73c\ub85c \ud2b9\uc815\ud55c \ub0a0\uc758 \uc5f0\uc8fc\ub97c \uc7ac\ud604\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uac1c\ubcc4 \uacbd\uc758 \ubcf4\uc874 \uc0c1\ud0dc\uc640 \ud3b8\uacbd\uc774\ub77c\ub294 \uc545\uae30\uc758 \uc77c\ubc18\uc801\uc778 \uc4f0\uc784\uc740 \uad6c\ubd84\ud574\uc11c \uc54c \uc218 \uc788\ub2e4. \uc774\ub984 \uc5c6\ub294 \ub3cc\ucc98\ub7fc \ubcf4\uc774\ub358 \ubb3c\uac74\uc774 \uc5ec\ub7ec \uc74c \uac00\uc6b4\ub370 \ud55c \uc790\ub9ac\ub97c \ub9e1\uc558\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uae30\uc5b5\ud574 \ubcf4\uc790. \uc870\uc6a9\ud55c \uc804\uc2dc\uc7a5\uc5d0\uc11c\ub3c4 \uadf8 \ubc30\uc5f4\uacfc \uc18c\ub9ac\uc758 \uac00\ub2a5\uc131\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc740 \ud3b8\uacbd\uc774 \uc870\uc120\uc2dc\ub300\uc758 \uc5ec\ub7ec \uc81c\ub840\uc640 \uc5f0\ub840\uc5d0 \uc0ac\uc6a9\ub418\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc624\ub298 \uc0ac\uc9c4\uc5d0\uc11c \ubcf4\uc774\ub294 \uac83\uc740 \uc870\uc6a9\ud55c \ub3cc \ud55c \uc7a5\uc774\uc9c0\ub9cc, \uc6d0\ub798\ub294 \ub2e4\ub978 \uc545\uae30\uc640 \ud568\uaed8 \uc18c\ub9ac\ub97c \ub0b4\ub358 \uc790\ub9ac\uc758 \uc77c\ubd80\uc600\ub358 \uc148\uc774\ub2e4. \uc0ac\uc9c4\uc744 \ub2e4\uc2dc \ubcfc \ub54c \ubaa8\ub4e0 \uc74c\uc758 \uc774\ub984\uc744 \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uad6c\uba4d \ud558\ub098\uc640 \uaebe\uc778 \ubaa8\uc591, \ub450\uaed8\ub97c \ub5a0\uc62c\ub9ac\ub294 \uac83\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4. \uc545\uae30\ub294 \uaf2d \uc904\uc774 \uc788\uac70\ub098 \uc18d\uc774 \ube48 \uad00\uc774\uc5b4\uc57c \ud55c\ub2e4\ub294 \uc0dd\uac01\ub3c4 \uc7a0\uc2dc \ub0b4\ub824\ub193\uc744 \uc218 \uc788\ub2e4. \ub3cc\uc5d0\ub3c4 \uc74c\uc545\uc744 \ub9e1\uae34 \uc0ac\ub78c\ub4e4\uc774 \uc788\uc5c8\ub2e4."}, {"id": "surrender-breda-keys-and-victory", "title": "\ube0c\ub808\ub2e4\uc758 \ud56d\ubcf5 \u2014 \uc2b9\ub9ac\ubcf4\ub2e4 \uba3c\uc800 \ubcf4\uc774\ub294 \ub450 \uc0ac\ub78c\uc758 \uc190", "summary": "\uc5f4\uc1e0\ub97c \uac74\ub124\ub294 \ub450 \uc7a5\uad70\uacfc \ucc3d\uc758 \ubc30\uc5f4, \uc804\uc7c1\uc758 \ubc30\uacbd\uc5d0\uc11c \uc2b9\ub9ac\ub97c \ud45c\ud604\ud558\ub294 \ubc29\uc2dd\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/surrender-breda-keys-and-victory/index.html", "image": "../media/surrender-breda-keys-and-victory.jpg", "alt": "\ubca8\ub77c\uc2a4\ucf00\uc2a4 \ube0c\ub808\ub2e4\uc758 \ud56d\ubcf5 \uc18d \uc5f4\uc1e0\ub97c \uac74\ub124\ub294 \ub450 \uc7a5\uad70\uacfc \uc8fc\ubcc0 \uad70\ub300\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc5ed\uc0ac \ud751\ubc31 \ub3c4\ud310", "text": "\ube0c\ub808\ub2e4\uc758 \ud56d\ubcf5 \u2014 \uc2b9\ub9ac\ubcf4\ub2e4 \uba3c\uc800 \ubcf4\uc774\ub294 \ub450 \uc0ac\ub78c\uc758 \uc190 \ubca8\ub77c\uc2a4\ucf00\uc2a4\uc758 \ud56d\ubcf5 \uc7a5\uba74\uc5d0\uc11c \uad00\ub300\ud55c \ubab8\uc9d3\uacfc \uc655\uc2e4\uc758 \uae30\uc5b5\uc744 \uc77d\uae30 \uc5f4\uc1e0\ub97c \uac74\ub124\ub294 \ub450 \uc7a5\uad70\uacfc \ucc3d\uc758 \ubc30\uc5f4, \uc804\uc7c1\uc758 \ubc30\uacbd\uc5d0\uc11c \uc2b9\ub9ac\ub97c \ud45c\ud604\ud558\ub294 \ubc29\uc2dd\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \uad70\uc778\ub4e4\uc774 \ub9c8\uc8fc \uc120 \uac00\uc6b4\ub370 \ud55c \uc0ac\ub78c\uc774 \uc5f4\uc1e0\ub97c \uac74\ub128\ub2e4. \uc2b9\ub9ac\ud55c \uc7a5\uad70\uc740 \ubab8\uc744 \uae30\uc6b8\uc5ec \uc0c1\ub300\ub97c \ub9de\ub294\ub2e4. \ub514\uc5d0\uace0 \ubca8\ub77c\uc2a4\ucf00\uc2a4\uc758 \u300e\ube0c\ub808\ub2e4\uc758 \ud56d\ubcf5\u300f\uc740 \uc804\uc7c1\uc758 \uacb0\uacfc\ub97c \uadf8\ub838\uc9c0\ub9cc \ud654\uba74\uc758 \uc911\uc2ec\uc5d0\ub294 \uce7c\uc744 \ud718\ub450\ub974\ub294 \uc21c\uac04\uc774 \uc5c6\ub2e4. \uc791\uc740 \uc5f4\uc1e0\uc640 \ub450 \uc0ac\ub78c\uc758 \uc190\uc774 \uba3c\uc800 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc774 \uadf8\ub9bc\uc740 \uc2e4\uc81c \uc0ac\uac74\uc744 \uae30\ub150\ud558\ub294 \ub3d9\uc2dc\uc5d0 \uc2b9\ub9ac\ub97c \uc5b4\ub5a4 \ubaa8\uc2b5\uc73c\ub85c \uae30\uc5b5\ud558\uac8c \ud560\uc9c0 \uc120\ud0dd\ud55c \uc791\ud488\uc774\ub2e4. \ud328\uc790\ub97c \ub300\ud558\ub294 \uc790\uc138\uc640 \uc218\ub9ce\uc740 \ucc3d, \ub4a4\ucabd\uc758 \uc5f0\uae30\ub97c \ucc28\ub840\ub85c \ubcf4\uba74 \uad00\ub300\ud55c \uc7a5\uba74\uacfc \uc655\uc2e4\uc758 \uad8c\ub825\uc744 \ub4dc\ub7ec\ub0b4\ub294 \uadf8\ub9bc\uc774 \uc5b4\ub5bb\uac8c \ud55c \ud654\uba74\uc5d0 \uc788\ub294\uc9c0 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ube0c\ub808\ub2e4\ub294 \uc624\ub298\ub0a0 \ub124\ub35c\ub780\ub4dc\uc5d0 \uc788\ub294 \ub3c4\uc2dc\ub2e4. 1625\ub144 \uc2a4\ud53c\ub180\ub77c\uac00 \uc774\ub048 \uc2a4\ud398\uc778 \uce21 \uad70\ub300\uc5d0 \ud56d\ubcf5\ud588\ub2e4. \uadf8\ub9bc\uc740 \uc774 \uc0ac\uac74\uc744 \ub2e4\ub8ec\ub2e4. \uc9c0\uc5ed\uacfc \ud1b5\uce58\uad8c, \uad70\ub300\uc758 \uad00\uacc4\uac00 \ud604\uc7ac\uc758 \uad6d\uacbd\uacfc \uac19\uc9c0 \uc54a\uc558\ub358 \uc2dc\uae30\uc774\ubbc0\ub85c \uc624\ub298\uc758 \uad6d\uac00 \uc9c0\ub3c4\ub9cc\uc73c\ub85c \ub2f9\uc2dc \uc804\uc7c1\uc744 \ub2e8\uc21c\ud654\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc2a4\ud398\uc778 \uad81\uc815\ud654\uac00\uac00 \uc2b9\ub9ac\ub97c \uc5b4\ub5bb\uac8c \ud45c\ud604\ud588\ub294\uc9c0\uc5d0 \uc911\uc2ec\uc744 \ub454\ub2e4. \uc0ac\uac74\uc758 \uc7a5\uc18c\uc640 \uc791\ud488\uc758 \ubb38\ud654\uc801 \ub9e5\ub77d\uc740 \uad6c\ubd84\ud560 \uc218 \uc788\ub2e4. \uac19\uc740 \ub3c4\uc2dc\uc758 \ud568\ub77d\ub3c4 \uc5b4\ub290 \ucabd\uc774 \uae30\ub150\ud558\uace0 \uc5b4\ub5a4 \uad00\ub78c\uac1d\uc5d0\uac8c \ubcf4\uc5ec \uc8fc\ub294\uc9c0\uc5d0 \ub530\ub77c \uc804\ud600 \ub2e4\ub978 \uc774\ubbf8\uc9c0\ub85c \ub0a8\uc744 \uc218 \uc788\ub2e4. \ubca8\ub77c\uc2a4\ucf00\uc2a4\ub294 \ud3a0\ub9ac\ud398 4\uc138\uc758 \uad81\uc815\uc5d0\uc11c \ud65c\ub3d9\ud588\ub2e4. \u300e\ube0c\ub808\ub2e4\uc758 \ud56d\ubcf5\u300f\uc740 \ubd80\uc5d4 \ub808\ud2f0\ub85c \uad81\uc804\uc744 \uc704\ud55c \uc791\ud488\uc774\uc5c8\ub2e4. \uac1c\uc778\uc774 \uc804\ud22c\uc758 \uae30\uc5b5\uc744 \ud63c\uc790 \uac04\uc9c1\ud558\ub824\uace0 \uc8fc\ubb38\ud55c \uc791\uc740 \uae30\ub150\ubb3c\uacfc\ub294 \ub2e4\ub974\ub2e4. \uc655\uc2e4\uc758 \uc704\uc0c1\uacfc \uad70\uc0ac\uc801 \uc131\uacfc\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uacf5\uac04\uc5d0 \ub193\uc77c \ud68c\ud654\uc600\ub2e4. \uc774 \ubc30\uacbd\uc744 \uc54c\uba74 \uadf8\ub9bc\uc758 \uad00\ub300\ud568\ub3c4 \ub354 \ubcf5\uc7a1\ud558\uac8c \uc77d\ud78c\ub2e4. \uc778\uac04\uc801\uc778 \ud45c\uc815\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc815\uce58\uc801 \ubaa9\uc801\uc744 \uac00\uc9c4 \uc791\ud488\uc774\ub77c\ub294 \uc0ac\uc2e4\uc740 \ud568\uaed8 \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4. \uc2b9\ub9ac\ub97c \uc5b4\ub5bb\uac8c \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc774 \uc2b9\uc790\uc758 \ud488\uaca9\uc744 \ub192\uc77c\uc9c0 \uc0dd\uac01\ud55c \uad6c\uc131\uc77c \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc791\ud488\uc774 \uac78\ub9b4 \uc790\ub9ac\ub3c4 \uc758\ubbf8\uc758 \uc77c\ubd80\ub2e4. \uc911\uc559\uc5d0\uc11c\ub294 \ud328\ud55c \ucabd\uc758 \uc9c0\ud718\uad00 \uc720\uc2a4\ud2f0\ub204\uc2a4 \ud310 \ub098\uc0ac\uc6b0\uac00 \uc2a4\ud53c\ub180\ub77c\uc5d0\uac8c \uc5f4\uc1e0\ub97c \uac74\ub128\ub2e4. \uc5f4\uc1e0\ub294 \uc791\uc740 \ubb3c\uac74\uc774\uc9c0\ub9cc \ub3c4\uc2dc\uc758 \ud1b5\uc81c\uad8c\uc774 \uc62e\uaca8 \uac00\ub294 \uc77c\uc744 \ub098\ud0c0\ub0b8\ub2e4. \ucee4\ub2e4\ub780 \uc0ac\uac74\uc744 \ud55c \uc190\uc5d0 \ub4e4 \uc218 \uc788\ub294 \uc0ac\ubb3c\ub85c \uc555\ucd95\ud55c \uac83\uc774\ub2e4. \uad70\ub300\uc640 \ud48d\uacbd \uc0ac\uc774\uc5d0\uc11c \uc774 \uc791\uc740 \ub3d9\uc791\uc774 \uc911\uc2ec\uc774 \ub41c\ub2e4. \uc2a4\ud53c\ub180\ub77c\ub294 \uc0c1\ub300\uac00 \ubab8\uc744 \ub0ae\ucd94\ub294 \ub3d9\uc791\uc5d0 \ubc18\uc751\ud558\uba70 \uc5b4\uae68 \ucabd\uc73c\ub85c \uc190\uc744 \ub0b4\ubbfc\ub2e4. \uad00\ub78c\uac1d\uc740 \uc2b9\uc790\uc758 \uc790\uc138\ub97c \ud1b5\ud574 \ud328\uc790\uac00 \uc5b4\ub5bb\uac8c \ub300\uc6b0\ubc1b\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uad74\uc695\uc744 \ud06c\uac8c \uacfc\uc2dc\ud558\ub294 \ub2e4\ub978 \uc2b9\uc804 \uc7a5\uba74\uacfc \ube44\uad50\ud558\uba74 \uc774 \uc120\ud0dd\uc758 \ud2b9\uc9d5\uc774 \ub354\uc6b1 \ub69c\ub837\ud558\ub2e4. \ud798\uc740 \uc5ec\uae30\uc11c \uc5b5\ub204\ub974\ub294 \ubaa8\uc2b5\ub9cc\uc73c\ub85c \ud45c\ud604\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc791\ud488\uc740 \u300e\ucc3d\ub4e4\u300f\uc774\ub77c\ub294 \uc774\ub984\uc73c\ub85c\ub3c4 \uc54c\ub824\uc84c\ub2e4. \uc624\ub978\ucabd\uc5d0 \uae38\uac8c \uc120 \ub9ce\uc740 \ucc3d\uc774 \uac15\ud55c \uc2dc\uac01\uc801 \ub9ac\ub4ec\uc744 \ub9cc\ub4e0\ub2e4. \uc0ac\ub78c\ub4e4\uc758 \uc5bc\uad74\uacfc \ub3d9\uc791\uc740 \uc11c\ub85c \ub2ec\ub77c\ub3c4 \uc704\ub85c \ubc18\ubcf5\ub418\ub294 \uc120\uc774 \uc9d1\ub2e8\uc758 \uc870\uc9c1\uc744 \ub290\ub07c\uac8c \ud55c\ub2e4. \uad70\uc0ac\uc801 \ud798\uc774 \uac1c\uc778\uc758 \ubab8\ubfd0 \uc544\ub2c8\ub77c \uc9c8\uc11c\uc758 \ubaa8\uc2b5\uc73c\ub85c \ub098\ud0c0\ub09c\ub2e4. \ubc18\ub300\ucabd\uc758 \ubb34\ub9ac\uc640 \ubb34\uae30\ub97c \ud568\uaed8 \ubcf4\uba74 \ud654\uba74\uc774 \uc644\uc804\ud788 \ub300\uce6d\uc778 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\ub3c4 \ubcf4\uc778\ub2e4. \ucc28\uc774\ub97c \ub9cc\ub4dc\ub294 \uc120\uacfc \ube48 \uacf5\uac04\uc774 \uc911\uc559\uc758 \uad50\ud658\uc744 \ub354 \ub450\ub4dc\ub7ec\uc9c0\uac8c \ud55c\ub2e4. \ub2e4\ub9cc \uadf8 \ubc30\uc5f4\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \ubcd1\uc0ac\uc758 \uc2e4\uc81c \uc0dd\uac01\uc744 \ud655\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud654\uac00\ub294 \uc11c\ub85c \ub2e4\ub978 \uc0ac\ub78c\uc744 \ud558\ub098\uc758 \uc7a5\uba74\uc73c\ub85c \uc870\uc9c1\ud558\uace0 \uc788\ub2e4. \ub9ce\uc740 \ubb34\uae30 \uc0ac\uc774\uc5d0\ub3c4 \uc5bc\uad74\uacfc \uc190, \uc11c\ub85c\ub97c \ubc14\ub77c\ubcf4\ub294 \ubc29\ud5a5\uc774 \ub0a8\uc544 \uc788\ub2e4. \uc9d1\ub2e8\uc758 \ud798\uc744 \ub4dc\ub7ec\ub0b4\uba74\uc11c \uac1c\uc778\uc758 \ucc28\uc774\ub97c \uc0b4\ub9b0 \uad6c\uc131\uc774\ub2e4. \ub450 \uc7a5\uad70\uc5d0\uac8c \uc2dc\uc120\uc744 \ubaa8\uc740 \ub2e4\uc74c \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\uc744 \ub2e4\uc2dc \uc0b4\ud53c\uba74, \uc2b9\ub9ac\ub77c\ub294 \ud55c \ub2e8\uc5b4\uac00 \uc5ec\ub7ec \ubab8\uc758 \uc790\uc138\ub85c \ub098\ub258\uc5b4 \ud45c\ud604\ub418\uc5b4 \uc788\uc74c\uc744 \ubcfc \uc218 \uc788\ub2e4. \ub450 \uc7a5\uad70\ub9cc \ubcf4\uba74 \uc6b0\uc544\ud55c \ub9cc\ub0a8\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218 \uc788\uc9c0\ub9cc \ub4a4\ucabd\uc5d0\ub294 \uc804\uc7c1\uc758 \ud48d\uacbd\uacfc \uc5f0\uae30\uac00 \ud3bc\uccd0\uc9c4\ub2e4. \uc5f4\uc1e0\ub97c \ub118\uae30\uae30\uae4c\uc9c0 \uc544\ubb34 \uc77c\ub3c4 \uc5c6\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud654\uba74\uc740 \uc911\uc2ec\uc758 \uc608\uc758\uc640 \ub354 \ub113\uc740 \ucda9\ub3cc\uc758 \ud754\uc801\uc744 \ud568\uaed8 \ub193\ub294\ub2e4. \uc2dc\uc120\uc744 \uba40\ub9ac \ubcf4\ub0b4\uba74 \uac00\uae4c\uc6b4 \ubab8\uc9d3\uc758 \uc758\ubbf8\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uad00\ub300\ud568\uc744 \ud45c\ud604\ud55c \uc7a5\uba74\uc774 \uc804\uc7c1\uc758 \ud53c\ud574 \uc804\uccb4\ub97c \uc124\uba85\ud574 \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub9bc \ubc16\uc5d0 \uc788\ub294 \ub3c4\uc2dc \uc8fc\ubbfc\uacfc \uc7a5\uae30\uac04\uc758 \ud3ec\uc704, \uac01\uc790\uc758 \uc190\uc2e4\ub3c4 \uc9c8\ubb38\uc73c\ub85c \ub0a8\ub294\ub2e4. \ud68c\ud654\uac00 \ubcf4\uc5ec \uc8fc\uae30\ub85c \uc120\ud0dd\ud55c \uc21c\uac04\uacfc \uc0ac\uac74 \uc804\uccb4\ub97c \uad6c\ubd84\ud558\uba74 \uc778\uac04\uc801\uc778 \uac10\ub3d9\uc744 \ub290\ub07c\uba74\uc11c\ub3c4 \uc5ed\uc0ac\uc801 \ud310\ub2e8\uc744 \uba48\ucd94\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \ubca8\ub77c\uc2a4\ucf00\uc2a4\uc758 \uc778\ubb3c\ub4e4\uc740 \uc2b9\uc790\uc640 \ud328\uc790\ub77c\ub294 \ud45c\uc9c0\ub9cc \ub2ec\uace0 \uc11c \uc788\uc9c0 \uc54a\ub2e4. \uc5bc\uad74\uc758 \ubc29\ud5a5\uacfc \ubab8\uc758 \ubb34\uac8c, \uc11c\ub85c\ub97c \ubc14\ub77c\ubcf4\ub294 \uc790\uc138\uc5d0 \ucc28\uc774\uac00 \uc788\ub2e4. \ub9ce\uc740 \ucd08\uc0c1\uc744 \uadf8\ub9b0 \ud654\uac00\uc758 \ub208\uc744 \uc5ec\uae30\uc11c\ub3c4 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc9d1\ub2e8\uc744 \uadf8\ub9ac\uba74\uc11c \ud55c \uc0ac\ub78c\uc758 \uc874\uc7ac\uac10\uc774 \uc644\uc804\ud788 \uc0ac\ub77c\uc9c0\uc9c0 \uc54a\uac8c \ud588\ub2e4. \ubb3c\ub860 \uc774 \uc0dd\uc0dd\ud568\uc774 \ud604\uc7a5\uc5d0\uc11c \uac19\uc740 \uc21c\uac04\uc744 \uadf8\ub300\ub85c \uadf8\ub838\ub2e4\ub294 \uc99d\uba85\uc740 \uc544\ub2c8\ub2e4. \uc791\ud488\uc740 \ud68c\ud654\uc801 \uc7ac\uad6c\uc131\uc774\ub2e4. \uae30\ub85d\ucc98\ub7fc \ubcf4\uc774\uac8c \ud558\ub294 \ub2a5\ub825\uacfc \uc0ac\uac74\uc744 \uc120\ud0dd\ud558\uace0 \ubc30\uc5f4\ud558\ub294 \ub2a5\ub825\uc774 \ud568\uaed8 \uc791\ub3d9\ud55c\ub2e4. \uc5ed\uc0ac\ud654\uc758 \uc0ac\uc2e4\uac10\uc744 \uac10\ud0c4\ud558\uba74\uc11c\ub3c4 \uadf8 \uc548\uc758 \ud3b8\uc9d1\uc744 \uc54c\uc544\ucc28\ub9b4 \ud544\uc694\uac00 \uc788\ub2e4. \u300e\ube0c\ub808\ub2e4\uc758 \ud56d\ubcf5\u300f\uc740 \uc804\uc7c1\uc758 \uc2b9\ub9ac\ub97c \uc778\uc815\ud558\uba74\uc11c \uc2b9\uc790\uc758 \uad00\ub300\ud568\ub3c4 \uae30\uc5b5\ud558\uac8c \ud55c\ub2e4. \uadf8\ub798\uc11c \uadf8\ub9bc\uc744 \uc88b\uc740 \uc0ac\ub78c\ub4e4\uc758 \ub9cc\ub0a8\uc73c\ub85c\ub9cc \uc77d\uac70\ub098 \ucc28\uac00\uc6b4 \uc120\uc804\uc73c\ub85c\ub9cc \uc904\uc774\uba74 \uc5b4\ub290 \ud55c\ucabd\uc744 \ub193\uce5c\ub2e4. \uc778\uac04\uc801\uc778 \ubab8\uc9d3\uacfc \uc655\uc2e4\uc758 \uc790\uae30\ud45c\ud604\uc774 \uac19\uc740 \ud654\uba74\uc5d0 \uacb9\uccd0 \uc788\ub2e4. \ub9c8\uc9c0\ub9c9\uc73c\ub85c \uc911\uc559\uc758 \uc5f4\uc1e0\uc640 \uc190\uc744 \ub2e4\uc2dc \ubcf4\uc790. \uc791\uc740 \uc0ac\ubb3c\uc774 \ub3c4\uc2dc\uc758 \uad8c\ub825\uc744 \ub300\uc2e0\ud558\uace0 \ud55c \ub3d9\uc791\uc774 \uc2b9\uc790\uc758 \uc131\uaca9\uc744 \uc124\uba85\ud55c\ub2e4. \ubca8\ub77c\uc2a4\ucf00\uc2a4\ub294 \ud070 \uad70\uc0ac\uc801 \uacb0\uacfc\ub97c \uac00\uae4c\uc6b4 \uc0ac\ub78c\uc758 \uad00\uacc4\ub85c \ubcf4\uc774\uac8c \ub9cc\ub4e4\uc5c8\ub2e4. \uadf8 \uc120\ud0dd\uc744 \uc77d\uc744 \ub54c \uc791\ud488\uc740 \uc804\uc7c1\uc758 \uc0bd\ud654\ubcf4\ub2e4 \ub354 \ub9ce\uc740 \uc9c8\ubb38\uc744 \ub0a8\uae30\ub294 \ud68c\ud654\uac00 \ub41c\ub2e4."}, {"id": "thor-thrym-bridal-veil-and-hammer", "title": "\ud1a0\ub974 \u2014 \ub9dd\uce58\ub97c \ucc3e\uc73c\ub7ec \uc2e0\ubd80\uac00 \ub41c \ub0a0", "summary": "\ub3c4\ub451\ub9de\uc740 \ubb20\ub2c8\ub974\uc640 \ud504\ub808\uc774\uc57c\uc758 \uac70\uc808, \uc2e0\ubd80 \ubcc0\uc7a5\uacfc \uc794\uce58\uc758 \uc704\uae30\ub97c \uc2dc\uc758 \uc804\uac1c\uc5d0 \ub530\ub77c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc2e0\ud654\uc640 \ubbfc\uc18d", "categories": ["arts"], "url": "stories/thor-thrym-bridal-veil-and-hammer/index.html", "image": "../media/thor-thrym-bridal-veil-and-hammer.png", "alt": "\uc2e0\ubd80 \uc637\uacfc \uba74\uc0ac\ud3ec\ub97c \uc4f4 \ud1a0\ub974, \uacc1\uc758 \ub85c\ud0a4\uc640 \uc794\uce58 \uc190\ub2d8\uc744 \uadf8\ub9b0 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ud1a0\ub974 \u2014 \ub9dd\uce58\ub97c \ucc3e\uc73c\ub7ec \uc2e0\ubd80\uac00 \ub41c \ub0a0 \u300c\ud2b8\ub94c\uc758 \ub178\ub798\u300d\uc758 \uc794\uce58\uc640 \ub85c\ud0a4\uc758 \uc7ac\uce58 \ub3c4\ub451\ub9de\uc740 \ubb20\ub2c8\ub974\uc640 \ud504\ub808\uc774\uc57c\uc758 \uac70\uc808, \uc2e0\ubd80 \ubcc0\uc7a5\uacfc \uc794\uce58\uc758 \uc704\uae30\ub97c \uc2dc\uc758 \uc804\uac1c\uc5d0 \ub530\ub77c \uc77d\uc2b5\ub2c8\ub2e4. \uc2e0\ud654\uc640 \ubbfc\uc18d \ubb38\ud654\uc640 \uc608\uc220 \uac70\uc778\uc758 \uc794\uce58\uc5d0 \uc2e0\ubd80\uac00 \ub3c4\ucc29\ud588\ub2e4. \uadf8\ub7f0\ub370 \uba39\ub294 \uc591\uc774 \uc5c4\uccad\ub098\ub2e4. \uc18c \ud55c \ub9c8\ub9ac\uc640 \uc5f0\uc5b4 \uc5ec\ub35f \ub9c8\ub9ac\ub97c \uba39\uc5b4 \uce58\uc6b0\uace0 \uc220\ub3c4 \uac70\uce68\uc5c6\uc774 \ub9c8\uc2e0\ub2e4. \uac70\uc778\uc774 \uc774\uc0c1\ud574\ud558\uc790 \uacc1\uc758 \uc2dc\ub140\uac00 \uc7ac\ube68\ub9ac \uc124\uba85\ud55c\ub2e4. \uc2e0\ubd80\uac00 \uc774\uacf3\uc5d0 \uc624\uace0 \uc2f6\uc5b4 \uc624\ub798 \uad76\uc5c8\ub2e4\ub294 \uac83\uc774\ub2e4. \uc2e0\ubd80\uc758 \uc815\uccb4\ub294 \ucc9c\ub465\uc758 \uc2e0 \ud1a0\ub974, \uc2dc\ub140\ub294 \ub85c\ud0a4\ub2e4. \u300e\uc2dc \uc5d0\ub2e4\u300f\uc758 \u300c\ud2b8\ub94c\uc758 \ub178\ub798\u300d\ub294 \ud798\uc13c \uc2e0\uc744 \ub0af\uc120 \uc790\ub9ac\uc5d0 \uc549\ud600 \ub193\uace0 \uc6c3\uc74c\uc744 \ub9cc\ub4e0\ub2e4. \ubaa9\uc801\uc740 \uacb0\ud63c\uc774 \uc544\ub2c8\ub77c \ub3c4\ub451\ub9de\uc740 \ub9dd\uce58\ub97c \ub418\ucc3e\ub294 \uac83\uc774\ub2e4. \ud1a0\ub974\ub294 \uae68\uc5b4\ub098 \uc790\uae30 \ub9dd\uce58\uac00 \uc5c6\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc548\ub2e4. \ubb20\ub2c8\ub974\ub294 \uadf8\uc800 \uc190\uc5d0 \uc775\uc740 \ubb3c\uac74\uc774 \uc544\ub2c8\ub2e4. \uc2e0\ub4e4\uc758 \uc138\uacc4\ub97c \uc9c0\ud0ac \ud798\uacfc \uc5f0\uacb0\ub418\ub294 \uc911\uc694\ud55c \ub3c4\uad6c\ub2e4. \ud798\uc774 \uc138\ub354\ub77c\ub3c4 \uadf8\uac83\uc774 \uc5b4\ub514\uc5d0 \uc788\ub294\uc9c0 \ubaa8\ub974\uba74 \ubc14\ub85c \ub418\ucc3e\uc744 \uc218 \uc5c6\ub2e4. \uadf8\ub294 \ub85c\ud0a4\uc640 \ud568\uaed8 \ud504\ub808\uc774\uc57c\ub97c \ucc3e\uc544\uac04\ub2e4. \ub85c\ud0a4\uac00 \ub0a0\uc544\ub2e4\ub2c8\uba70 \uc18c\uc2dd\uc744 \uc54c\uc544\ubcfc \uc218 \uc788\ub3c4\ub85d \uae43\ud138 \uc637\uc744 \ube4c\ub9ac\ub824\ub294 \uac83\uc774\ub2e4. \uc0ac\uac74\uc758 \uccab \ud574\uacb0\ucc45\uc740 \uc8fc\uba39\uc774 \uc544\ub2c8\ub77c \ub2e4\ub978 \uc2e0\uc758 \ub3c4\uc6c0\uc744 \uc5bb\uc5b4 \uc815\ubcf4\ub97c \ucc3e\ub294 \uc77c\uc774\ub2e4. \ub85c\ud0a4\ub294 \uac70\uc778 \ud2b8\ub94c\uc744 \ub9cc\ub098 \ub9dd\uce58\uc758 \ud589\ubc29\uc744 \uc54c\uc544\ub0b8\ub2e4. \ud2b8\ub94c\uc740 \uc790\uc2e0\uc774 \uae4a\uc774 \uc228\uaca8 \ub450\uc5c8\ub2e4\uace0 \ub9d0\ud55c\ub2e4. \ub3cc\ub824\uc8fc\ub294 \uc870\uac74\uc73c\ub85c \ud504\ub808\uc774\uc57c\ub97c \uc544\ub0b4\ub85c \ub9de\uaca0\ub2e4\uace0 \uc694\uad6c\ud55c\ub2e4. \ubb3c\uac74\uc744 \ube7c\uc557\uc544 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uacb0\ud63c\uc744 \uac70\ub798\ud558\ub824\ub294 \uc148\uc774\ub2e4. \ub85c\ud0a4\uac00 \uc18c\uc2dd\uc744 \uc804\ud558\uc790 \uc2e0\ub4e4\uc740 \ud504\ub808\uc774\uc57c\uc5d0\uac8c \ud568\uaed8 \uac00\uc790\uace0 \ud55c\ub2e4. \uadf8\ub7ec\ub098 \uadf8\ub140\ub294 \ubd84\uba85\ud788 \uac70\uc808\ud55c\ub2e4. \uc2e0\ub4e4\uc758 \uace4\ub780\uc744 \ud574\uacb0\ud558\uae30 \uc704\ud574 \uc790\uae30 \ub73b\uc744 \ub0b4\ub193\uc9c0 \uc54a\ub294\ub2e4. \uc774\uc57c\uae30\ub294 \uadf8 \uac70\uc808\uc744 \uc9c0\uc6b4 \ucc44 \uacb0\ud63c\uc73c\ub85c \ub118\uc5b4\uac00\uc9c0 \uc54a\ub294\ub2e4. \uc2e0\ub4e4\uc774 \uc758\ub17c\ud558\ub294 \uc790\ub9ac\uc5d0\uc11c \ud5e4\uc784\ub2ec\uc740 \ud1a0\ub974\uc5d0\uac8c \uc2e0\ubd80\uc758 \uc637\uacfc \uc7a5\uc2e0\uad6c\ub97c \uc785\ud788\uc790\uace0 \uc81c\uc548\ud55c\ub2e4. \uc5bc\uad74\uc744 \uac00\ub9ac\uace0 \ud504\ub808\uc774\uc57c\uc778 \uac83\ucc98\ub7fc \uac70\uc778\uc758 \uc9d1\uc5d0 \ub4e4\uc5b4\uac00\uc790\ub294 \uacc4\ud68d\uc774\ub2e4. \ub9dd\uce58\uac00 \uc788\ub294 \uacf3\uc73c\ub85c \uc811\uadfc\ud560 \uae38\uc774 \uc0dd\uae34\ub2e4. \ud1a0\ub974\ub294 \ub0a8\ub4e4\uc774 \uc790\uc2e0\uc744 \uc5b4\ub5bb\uac8c \ubcfc\uc9c0 \uac71\uc815\ud558\uba70 \ub0b4\ucf1c \ud558\uc9c0 \uc54a\ub294\ub2e4. \ub85c\ud0a4\ub294 \ub9dd\uce58\ub97c \ub418\ucc3e\uc9c0 \ubabb\ud558\uba74 \uac70\uc778\ub4e4\uc774 \uc2e0\ub4e4\uc758 \uc138\uacc4\ub97c \ucc28\uc9c0\ud560 \uc218 \uc788\ub2e4\uace0 \uc7ac\ucd09\ud55c\ub2e4. \uc790\uc874\uc2ec\uacfc \uae34\uae09\ud55c \ud544\uc694\uac00 \ubd80\ub52a\uce58\uace0 \uacb0\uad6d \ubcc0\uc7a5\uc774 \uc774\ub8e8\uc5b4\uc9c4\ub2e4. \ub85c\ud0a4\ub294 \uc2dc\ub140 \uc5ed\ud560\ub85c \ud1a0\ub974\uc640 \ub3d9\ud589\ud55c\ub2e4. \uc2e0\ubd80 \ud63c\uc790 \uc794\uce58\uc5d0 \ub4e4\uc5b4\uac14\ub2e4\uba74 \uacc4\ud68d\uc740 \ud6e8\uc52c \ube68\ub9ac \ub4e4\ud1b5\ub0ac\uc744\uc9c0 \ubaa8\ub978\ub2e4. \uc2dc\ub294 \ud1a0\ub974\uc758 \ubab8\uc9d3\uacfc \ub85c\ud0a4\uc758 \ub9d0\uc744 \uc11c\ub85c \ub2e4\ub978 \uc5ed\ud560\ub85c \ubc30\uce58\ud55c\ub2e4. \ud1a0\ub974\uac00 \ucc38\uae30 \uc5b4\ub824\uc6b4 \uac83\uc744 \ud589\ub3d9\uc73c\ub85c \ub4dc\ub7ec\ub0b4\uba74 \ub85c\ud0a4\ub294 \uadf8 \ud589\ub3d9\uc744 \ub2e4\ub978 \uc774\uc57c\uae30\ub85c \ubc14\uafd4 \ub4e4\ub824\uc900\ub2e4. \ud798\uacfc \uc7ac\uce58\uac00 \uc9dd\uc744 \uc774\ub8ec \uc148\uc774\ub2e4. \ub450 \uc778\ubb3c\uc774 \uac19\uc740 \uac83\uc744 \uc798\ud558\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc5d0 \uc794\uce58 \uc7a5\uba74\uc758 \uae34\uc7a5\uc774 \uc0dd\uae34\ub2e4. \uac70\uc778\uc740 \uc6d0\ud558\ub294 \uc2e0\ubd80\ub97c \uc5bb\uc5c8\ub2e4\uace0 \uae30\ubed0\ud558\uba70 \uc794\uce58\ub97c \uc5f0\ub2e4. \ud558\uc9c0\ub9cc \uc2e0\ubd80\ub294 \ud1a0\ub974\uc758 \uc2dd\uc695\uc744 \uc228\uae30\uc9c0 \ubabb\ud55c\ub2e4. \uc18c\uc640 \uc5f0\uc5b4, \uc220\uc744 \ube60\ub974\uac8c \ube44\uc6b0\ub294 \ubaa8\uc2b5\uc740 \uacc4\ud68d\uc744 \uc704\ud0dc\ub86d\uac8c \ud55c\ub2e4. \uad00\uac1d\uc740 \uc815\uccb4\ub97c \uc54c\uae30\uc5d0 \uac70\uc778\uc758 \ub180\ub78c\uc774 \ub354 \uc6b0\uc2b5\ub2e4. \ub85c\ud0a4\ub294 \uc2e0\ubd80\uac00 \uc2e0\ub791\uc744 \uadf8\ub9ac\uc6cc\ud574 \uc5ec\ub7ec \ub0a0 \uc74c\uc2dd\uc744 \uba39\uc9c0 \ubabb\ud588\ub2e4\uace0 \ub458\ub7ec\ub304\ub2e4. \ubc14\ub85c \ub208\uc55e\uc758 \uc218\uc0c1\ud568\uc744 \uc0ac\ub791\uc758 \uc99d\uac70\ub85c \ubc14\uafb8\ub294 \uc7ac\uce58\ub2e4. \ud2b8\ub94c\uc740 \uc790\uc2e0\uc774 \ub4e3\uace0 \uc2f6\uc740 \uc124\uba85\uc744 \ub4e3\uace0 \uc758\uc2ec\uc744 \uc7a0\uc2dc \ub0b4\ub824\ub193\ub294\ub2e4. \ud2b8\ub94c\uc774 \uc5bc\uad74 \uac00\uae4c\uc774 \ub2e4\uac00\uac00\uc790 \uc2e0\ubd80\uc758 \ub208\uc774 \ubb34\uc12d\uac8c \ube5b\ub09c\ub2e4. \ud3c9\uc18c\uc758 \ud1a0\ub974\ub77c\uba74 \uc774\uc0c1\ud560 \uac83\uc774 \uc5c6\uc9c0\ub9cc \uc9c0\uae08\uc758 \uc5ed\ud560\uacfc\ub294 \ub9de\uc9c0 \uc54a\ub294\ub2e4. \uc2dd\uc0ac\uc5d0 \uc774\uc5b4 \ub450 \ubc88\uc9f8 \uc704\uae30\uac00 \uc628\ub2e4. \ub85c\ud0a4\ub294 \ub610 \ud55c \ubc88 \ub2f5\ud55c\ub2e4. \uc2e0\ubd80\uac00 \uc774\uacf3\uc5d0 \uc624\uace0 \uc2f6\uc740 \ub9c8\uc74c\uc5d0 \uc5ec\ub7ec \ubc24\uc744 \uc790\uc9c0 \ubabb\ud588\ub2e4\ub294 \uac83\uc774\ub2e4. \uad76\uc8fc\ub9bc\uacfc \uc7a0 \ubabb \ub4e6\uc774\ub77c\ub294 \ub450 \uc124\uba85\uc774 \uc9dd\uc744 \uc774\ub8ec\ub2e4. \uac19\uc740 \ubc29\uc2dd\uc774 \ubc18\ubcf5\ub420\uc218\ub85d \uc18d\ub294 \uac70\uc778\uc758 \uae30\ub300\ub3c4 \uc120\uba85\ud574\uc9c4\ub2e4. \ub9c8\uce68\ub0b4 \ud2b8\ub94c\uc740 \ud63c\ub840\ub97c \ucd95\ubcf5\ud558\ub824\uace0 \ub9dd\uce58\ub97c \uac00\uc838\uc624\uac8c \ud55c\ub2e4. \uc2e0\ubd80\uc758 \ubb34\ub98e\uc5d0 \ubb20\ub2c8\ub974\ub97c \uc62c\ub824\ub193\uc73c\ub77c\ub294 \uba85\ub839\uc774\ub2e4. \uc228\uaca8 \ub450\uc5c8\ub358 \ubb3c\uac74\uc774 \uac00\uc7a5 \uac00\uae4c\uc6b4 \uc790\ub9ac\uae4c\uc9c0 \uc62e\uaca8 \uc628\ub2e4. \ud1a0\ub974\uac00 \uae30\ub2e4\ub9b0 \uc21c\uac04\uc774\ub2e4. \ub9dd\uce58\ub97c \ub418\ucc3e\uc740 \ud1a0\ub974\ub294 \uac70\uc778\ub4e4\uc744 \uacf5\uaca9\ud558\uace0 \uc774\uc57c\uae30\ub294 \ud3ed\ub825\uc801\uc778 \uc2b9\ub9ac\ub85c \ub05d\ub09c\ub2e4. \uc55e\ubd80\ubd84\uc774 \uc6b0\uc2a4\uc6b4 \uc794\uce58\ub77c\uace0 \ud574\uc11c \uacb0\ub9d0\uae4c\uc9c0 \ud3c9\ud654\ub85c\uc6b4 \ud76c\uadf9\uc740 \uc544\ub2c8\ub2e4. \uc6c3\uc74c\uacfc \uc704\ud611\uc774 \ud55c \ub178\ub798 \uc548\uc5d0\uc11c \ube60\ub974\uac8c \uc790\ub9ac\ub97c \ubc14\uafbc\ub2e4. \uc2dc\ub294 \ub9dd\uce58\ub97c \ubcf8 \ud1a0\ub974\uc758 \ub9c8\uc74c\uc774 \uc6c3\ub294\ub2e4\uace0 \ud45c\ud604\ud55c\ub2e4. \uc794\uce58 \ub0b4\ub0b4 \uc5b5\ub204\ub974\ub358 \ud798\uc774 \ub3cc\uc544\uc654\ub2e4\ub294 \uc9e7\uace0 \uc120\uba85\ud55c \uc804\ud658\uc774\ub2e4. \uc774\uc57c\uae30\uc758 \uc7ac\ubbf8\ub97c \uc5ec\uc131\uc758 \uc637\uc774 \uc5f4\ub4f1\ud558\ub2e4\ub294 \ud310\ub2e8\uc73c\ub85c \uc62e\uae38 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc790\uae30 \uc5ed\ud560\uacfc \uba85\uc131\uc5d0 \uc775\uc219\ud55c \uc2e0\uc774 \ub2e4\ub978 \uc5ed\ud560\uc758 \uaddc\uce59\uc744 \uc9c0\ud0a4\uc9c0 \ubabb\ud558\ub294 \uc0c1\ud669\uc774 \uc6c3\uc74c\uc744 \ub9cc\ub4e0\ub2e4. \uc61b \uc2dc \uc18d \uc778\ubb3c\uc758 \uc131\ubcc4 \uad00\ub150\uacfc \uc624\ub298\uc758 \ub3c5\uc790 \ud310\ub2e8\uc740 \uad6c\ubd84\ud560 \uc218 \uc788\ub2e4. \ubb20\ub2c8\ub974\ub3c4 \ud765\ubbf8\ub86d\ub2e4. \uc2f8\uc6c0\uc758 \ubb34\uae30\uc774\uba74\uc11c \ud63c\ub840\ub97c \ucd95\ubcf5\ud558\ub294 \ubb3c\uac74\uc73c\ub85c \ub4f1\uc7a5\ud55c\ub2e4. \ub2e4\ub9cc \uc774 \uc7a5\uba74 \ud558\ub098\ub85c \ub2f9\uc2dc \ubd81\uc720\ub7fd\uc758 \ubaa8\ub4e0 \ud63c\ub840\uac00 \ub611\uac19\uc558\ub2e4\uace0 \ubcf5\uc6d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc2dc\uac00 \ubb3c\uac74\uc5d0 \uc8fc\ub294 \uc5ec\ub7ec \uc5ed\ud560\uc744 \uc77d\uc744 \uc218 \uc788\uc744 \ubfd0\uc774\ub2e4. \ud1a0\ub974\ub294 \ub9c8\uc9c0\ub9c9\uc5d0 \ud798\uc744 \uc4f0\uc9c0\ub9cc \uadf8 \uc21c\uac04\uae4c\uc9c0 \ub370\ub824\ub2e4\uc900 \uac83\uc740 \uc815\ubcf4\uc640 \ubcc0\uc7a5, \ub85c\ud0a4\uc758 \ub9d0\uc774\uc5c8\ub2e4. \ud798\uc774 \uc788\ub2e4\uace0 \ubaa8\ub4e0 \uc0c1\ud669\uc5d0\uc11c \ubc14\ub85c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ub9dd\uce58\ub97c \ub418\ucc3e\uae30 \uc804\uc758 \uae30\ub2e4\ub9bc\uc774 \uc774\uc57c\uae30\ub97c \uc6c0\uc9c1\uc778\ub2e4. \uc774 \ub178\ub798\ub97c \ub2e4\uc2dc \uc77d\uc744 \ub54c\ub294 \uac70\uc778\uc774 \uc5b8\uc81c \uc758\uc2ec\ud558\uace0 \uc5b4\ub5a4 \ub9d0\uc5d0 \uc548\uc2ec\ud558\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc18d\uc784\uc218\ub294 \ud1a0\ub974\uc758 \ubcc0\uc7a5\ub9cc\uc73c\ub85c \uc131\uacf5\ud558\uc9c0 \uc54a\ub294\ub2e4. \ubcf4\uace0 \uc2f6\uc740 \uc2e0\ubd80\ub9cc \ubcf4\ub824\ub294 \ud2b8\ub94c\uc758 \uae30\ub300\ub3c4 \ud568\uaed8 \uc77c\uc744 \ud55c\ub2e4. \uadf8 \uc5b4\uae0b\ub0a8\uc774 \uc624\ub798\ub41c \uc794\uce58\ub97c \uc0dd\uc0dd\ud558\uac8c \ub9cc\ub4e0\ub2e4."}, {"id": "titian-man-with-glove", "title": "\uc7a5\uac11\uc744 \ub080 \ub0a8\uc790 \u2014 \uc5bc\uad74\ubcf4\ub2e4 \uc190\uc774 \uba3c\uc800 \uc54c\ub824 \uc8fc\ub294 \uac83", "summary": "\ubaa8\ub378\uc758 \uc774\ub984\uc744 \ub9de\ud788\ub294 \ub300\uc2e0 \uc5bc\uad74\u00b7\uc190\u00b7\uc7a5\uac11\uc774 \uc774\ub8e8\ub294 \uad00\uacc4\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/titian-man-with-glove/index.html", "image": "../media/titian-man-with-glove.jpg", "alt": "\ud2f0\uce58\uc544\ub178\uc758 \uc7a5\uac11\uc744 \ub080 \ub0a8\uc790. \uac80\uc740 \uc637\uacfc \ud770 \uc154\uce20\ub97c \uc785\uc740 \uc778\ubb3c\uc774 \uc606\uc744 \ubc14\ub77c\ubcf4\uace0 \ud55c \uc190\uc5d0\ub294 \uc7a5\uac11\uc744 \ub07c\uace0 \uc788\uc2b5\ub2c8\ub2e4.", "text": "\uc7a5\uac11\uc744 \ub080 \ub0a8\uc790 \u2014 \uc5bc\uad74\ubcf4\ub2e4 \uc190\uc774 \uba3c\uc800 \uc54c\ub824 \uc8fc\ub294 \uac83 \ud2f0\uce58\uc544\ub178\uc758 \ucd08\uc0c1\uc5d0\uc11c \uac80\uc740 \uc637\uacfc \uc791\uc740 \ubb3c\uac74 \uc77d\uae30 \ubaa8\ub378\uc758 \uc774\ub984\uc744 \ub9de\ud788\ub294 \ub300\uc2e0 \uc5bc\uad74\u00b7\uc190\u00b7\uc7a5\uac11\uc774 \uc774\ub8e8\ub294 \uad00\uacc4\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \ud55c \ub0a8\uc790\uac00 \uac80\uc740 \uc637\uc744 \uc785\uace0 \uc11c \uc788\ub2e4. \ud770 \uc154\uce20\uc640 \ubaa9\uae43, \uc5bc\uad74\uacfc \uc190\uc774 \uc5b4\ub450\uc6b4 \ud654\uba74\uc5d0\uc11c \uba3c\uc800 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uadf8\uac00 \ubb34\uc5c7\uc744 \ud588\uace0 \uc5b4\ub5a4 \uc774\ub984\uc744 \uac00\uc84c\ub294\uc9c0 \ubab0\ub77c\ub3c4 \uc5b4\ub5a4 \ud0dc\ub3c4\ub85c \uc6b0\ub9ac \uc55e\uc5d0 \ub193\uc600\ub294\uc9c0\ub294 \ub290\ub084 \uc218 \uc788\ub2e4. \ud2f0\uce58\uc544\ub178\uc758 \u3008\uc7a5\uac11\uc744 \ub080 \ub0a8\uc790\u3009\ub2e4. \ucd08\uc0c1\ud654\ub97c \ubcf4\uba74 \ubaa8\ub378\uc758 \uc2e0\uc6d0\uc744 \uba3c\uc800 \uc54c\uace0 \uc2f6\uc5b4\uc9c4\ub2e4. \ud558\uc9c0\ub9cc \uc774 \uc791\ud488\uc5d0\uc11c\ub294 \uc81c\ubaa9\uc774 \uac00\ub9ac\ud0a4\ub294 \uc791\uc740 \ubb3c\uac74\uc744 \ub530\ub77c\uac00 \ubcf4\ub294 \uac83\ub3c4 \uc88b\uc740 \uc2dc\uc791\uc774\ub2e4. \uc5bc\uad74\uc744 \ubcf4\uace0 \uc190\uc73c\ub85c \ub0b4\ub824\uc624\uba74, \uc778\ubb3c\uc758 \uc874\uc7ac\uac10\uc774 \ud55c \ubd80\ubd84\ub9cc\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc9c4 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc774 \ubcf4\uc778\ub2e4. \uc778\ubb3c\uc758 \uc637\uc740 \ub113\uace0 \uc5b4\ub450\uc6b4 \uba74\uc744 \uc774\ub8ec\ub2e4. \uba40\ub9ac\uc11c \ubcf4\uba74 \uc0c9\uc774 \ub2e8\uc870\ub86d\ub2e4\uace0 \ub290\ub084 \uc218 \uc788\uc9c0\ub9cc, \uadf8 \uc5b4\ub450\uc6c0 \ub54c\ubb38\uc5d0 \uc5bc\uad74\uacfc \ud770 \uc637\uae43, \ub450 \uc190\uc758 \ucc28\uc774\uac00 \ub354 \ub610\ub837\ud574\uc9c4\ub2e4. \ubaa8\ub4e0 \ubd80\ubd84\uc774 \uac19\uc740 \uc815\ub3c4\ub85c \uc2dc\uc120\uc744 \ub04c\uc9c0 \uc54a\ub294 \uad6c\uc131\uc774 \uc778\ubb3c\uc758 \uc911\uc2ec\uc744 \uc7a1\uc544 \uc900\ub2e4. \ud654\ub824\ud55c \uc637\uc758 \ubb34\ub2ac\uac00 \ub9ce\uc9c0 \uc54a\uc544\ub3c4 \ucd08\uc0c1\uc740 \ud48d\ubd80\ud560 \uc218 \uc788\ub2e4. \uc5b4\ub514\uac00 \ubc1d\uace0 \uc5b4\ub514\uac00 \uac00\ub77c\uc549\uc544 \uc788\ub294\uc9c0, \uc5b4\uae68\uc640 \ubab8\uc758 \uc724\uacfd\uc774 \ubc30\uacbd\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uad6c\ubcc4\ub418\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uac80\uc740\uc0c9\uc744 \uadf8\ub9bc\uc758 \ube48\uce78\uc73c\ub85c \ucde8\uae09\ud558\uc9c0 \uc54a\uc73c\uba74 \ubcfc \ubd80\ubd84\uc774 \ub298\uc5b4\ub09c\ub2e4. \uc778\ubb3c\uc740 \uc5bc\uad74\uacfc \ub208\uae38\uc744 \uc815\uba74\uc5d0 \uace0\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc57d\uac04 \uc606\uc744 \ubc14\ub77c\ubcf4\ub294 \ub4ef\ud55c \uc790\uc138\ub2e4. \uad00\uac1d\uc744 \ud5a5\ud574 \ubaa8\ub4e0 \uac83\uc744 \uc124\uba85\ud558\ub824\ub294 \ubaa8\uc2b5\ubcf4\ub2e4, \ud654\uba74 \ubc16\uc5d0\ub3c4 \uc790\uae30 \uad00\uc2ec\uc774 \uc788\ub294 \uc0ac\ub78c\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uadf8 \ubc29\ud5a5\uc5d0 \ubb34\uc5c7\uc774 \uc2e4\uc81c\ub85c \uc788\uc5c8\ub294\uc9c0 \uc6b0\ub9ac\uac00 \ud655\uc778\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub9bc \ubc16\uc758 \uc0ac\ub78c\uc774\ub098 \ub300\ud654\ub97c \uc9c0\uc5b4\ub0b4\ub294 \ub300\uc2e0, \uc815\uba74\uc744 \ubcfc \ub54c\uc640 \uc774 \uc2dc\uc120\uc774 \uc8fc\ub294 \uc778\uc0c1\uc774 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0 \uc0dd\uac01\ud574 \ubcf4\uc790. \ud55c \uc0ac\ub78c\uc758 \ub0b4\uba74\uc744 \ubaa8\ub450 \uc548\ub2e4\uace0 \uc8fc\uc7a5\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc790\uc138\uc758 \ud6a8\uacfc\ub294 \ub290\ub084 \uc218 \uc788\ub2e4. \uc67c\uc190 \ucabd\uc5d0\ub294 \uc7a5\uac11\uacfc \ub2e4\ub978 \ud55c \uc9dd\uc758 \uc7a5\uac11\uc774 \ubcf4\uc778\ub2e4. \uc190\uc740 \ubc1b\uce68\ub300 \uac00\uae4c\uc774 \ub193\uc5ec \uc788\uc5b4 \ubab8\uc758 \uc704\uce58\ub97c \uc548\uc815\uc2dc\ud0a4\ub294 \uc5ed\ud560\ub3c4 \ud55c\ub2e4. \uc81c\ubaa9\uc744 \uc54c\uace0 \ub098\uba74 \uadf8 \ubd80\ubd84\uc774 \uba3c\uc800 \ubcf4\uc774\uc9c0\ub9cc, \ud55c \ubc88 \ucc3e\uc740 \ub4a4\uc5d0\ub294 \uc5bc\uad74\uacfc\uc758 \uac70\ub9ac\ub97c \ud568\uaed8 \uc0b4\ud53c\uba74 \uc88b\ub2e4. \uc7a5\uac11\uc740 \uc190\uc744 \ub36e\ub294 \ubb3c\uac74\uc774\uba74\uc11c \ucd08\uc0c1 \uc18d \ucc28\ub9bc\uc0c8\uc758 \uc77c\ubd80\ub2e4. \uc637\uacfc \uc7a5\uc2e0\uad6c, \ubab8\uc758 \ud0dc\ub3c4\ub97c \ud568\uaed8 \ubcf4\uba74 \uc778\ubb3c\uc774 \uc5b4\ub5a4 \uc0ac\ud68c\uc801 \uc774\ubbf8\uc9c0\ub97c \ubcf4\uc5ec \uc8fc\ub3c4\ub85d \uad6c\uc131\ub418\uc5c8\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \ub2e4\ub9cc \uc7a5\uac11 \ud558\ub098\ub85c \uc815\ud655\ud55c \uc9c1\uc5c5\uc774\ub098 \uc2e0\ubd84\uc744 \ud655\uc815\ud558\ub294 \uac83\uc740 \ub2e4\ub978 \uc99d\uac70\uac00 \ud544\uc694\ud55c \uc77c\uc774\ub2e4. \uadf8\ub9bc\uc5d0\ub294 \uc7a5\uac11\uc73c\ub85c \ub36e\uc778 \uc190\uacfc \uadf8\ub807\uc9c0 \uc54a\uc740 \uc190\uc758 \ucc28\uc774\uac00 \uc788\ub2e4. \ub9e8\uc190 \ucabd\uc5d0\ub294 \ubc18\uc9c0\ub3c4 \ubcf4\uc778\ub2e4. \uc5bc\uad74\uacfc \ud568\uaed8 \ud53c\ubd80\uac00 \ub4dc\ub7ec\ub098\ub294 \ubd80\ubd84, \ucc9c\uacfc \uac00\uc8fd\uc73c\ub85c \ub36e\uc778 \ubd80\ubd84\uc744 \ubc88\uac08\uc544 \ubcf4\uba74 \ucd08\uc0c1 \uc548\uc758 \uc7ac\ub8cc\uac00 \ub2e4\uc591\ud558\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ub290\ub084 \uc218 \uc788\ub2e4. \uc190\uc740 \uc5bc\uad74\uc5d0 \ub367\ubd99\uc740 \ubd80\uc18d\ud488\uc774 \uc544\ub2c8\ub2e4. \uc5b4\ub5bb\uac8c \ub193\uc5ec \uc788\ub290\ub0d0\uc5d0 \ub530\ub77c \uc778\ubb3c\uc758 \uae34\uc7a5\uacfc \ud3b8\uc548\ud568\uc774 \ub2e4\ub974\uac8c \ubcf4\uc77c \uc218 \uc788\ub2e4. \uc785\uac00\uc758 \ud45c\uc815\ub9cc \uad00\ucc30\ud558\ub358 \uac10\uc0c1\uc744 \uc190\uacfc \ud314\ub85c \ub113\ud788\ub294 \uc88b\uc740 \uc791\ud488\uc774\ub2e4. \ub204\uad70\uac00\uc758 \uc131\uaca9\uc744 \uc190 \ud558\ub098\ub85c \uc9c4\ub2e8\ud558\ub294 \ub300\uc2e0 \ud654\uba74\uc774 \ub9cc\ub4dc\ub294 \uc790\uc138\ub97c \uc0b4\ud3b4\ubcf4\uc790. \uac80\uc740 \uc637 \uc0ac\uc774\uc758 \ud770 \uc154\uce20\ub294 \uc5bc\uad74 \uc544\ub798\uc5d0\uc11c \ubc1d\uc740 \uae38\uc744 \ub9cc\ub4e0\ub2e4. \ubaa9 \uadfc\ucc98\uc758 \uae08\ube5b\uacfc \uc190\uc758 \uc791\uc740 \uc7a5\uc2dd\uc740 \uc2dc\uc120\uc744 \ub2e4\uc2dc \uba48\ucd94\uac8c \ud55c\ub2e4. \ud070 \uc7a5\uc2dd\ubcf4\ub2e4 \uc791\uc740 \ucc28\uc774\uac00 \ub450\ub4dc\ub7ec\uc9c0\ub294 \ud654\uba74\uc774\ub2e4. \uc5b4\ub514\uc5d0 \ub208\uc774 \uba3c\uc800 \uac00\ub294\uc9c0 \uc2a4\uc2a4\ub85c \ub530\ub77c\uac00 \ubcf4\uba74 \uad6c\uc131\uc744 \uad6c\uccb4\uc801\uc73c\ub85c \ub290\ub084 \uc218 \uc788\ub2e4. \uc5bc\uad74\uc5d0\uc11c \ud770 \uc637\uc73c\ub85c, \uc190\uacfc \uc7a5\uac11\uc73c\ub85c \ub0b4\ub824\uc654\ub2e4\uac00 \ub2e4\uc2dc \uc5bc\uad74\ub85c \uc62c\ub77c\uac00 \ubcf4\uc790. \uc775\uc219\ud55c \ucd08\uc0c1\ub3c4 \ub208\uae38\uc758 \uc21c\uc11c\ub97c \ubc14\uafb8\uba74 \ub2e4\ub978 \uad00\uacc4\uac00 \ubcf4\uc778\ub2e4. \uc774 \uc21c\uc11c\uac00 \uc815\ub2f5\uc774\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc791\ud488\uc744 \ud55c \ubc88 \ub354 \ubcf4\ub294 \uc791\uc740 \ubc29\ubc95\uc73c\ub85c \uc0ac\uc6a9\ud558\uba74 \ub41c\ub2e4. \ud2f0\uce58\uc544\ub178\ub294 \ubca0\ub124\uce58\uc544 \ud68c\ud654\uc758 \uc911\uc694\ud55c \ud654\uac00\ub85c, \uc778\ubb3c\uacfc \uc637, \ud53c\ubd80\uc640 \ube5b\uc758 \uad00\uacc4\ub97c \ub2e4\ub8e8\ub294 \ucd08\uc0c1\ub4e4\uc744 \ub0a8\uacbc\ub2e4. \uc774 \uc791\ud488\uc5d0\uc11c\ub3c4 \uc8fc\uc778\uacf5\uc758 \uc774\uc57c\uae30\ub97c \uae00\ub85c \uae38\uac8c \ubd99\uc774\uc9c0 \uc54a\uace0 \ud654\uba74 \uc790\uccb4\ub85c \uc874\uc7ac\uac10\uc744 \ub9cc\ub4e0\ub2e4. \uc0ac\ub78c\uc758 \uc5bc\uad74\ubfd0 \uc544\ub2c8\ub77c \uc8fc\ubcc0 \uc7ac\ub8cc\ub97c \uadf8\ub9ac\ub294 \uc77c\uc774 \ud568\uaed8 \uc791\uc6a9\ud55c\ub2e4. \ubaa8\ub378\uc758 \uc774\ub984\uc744 \ud655\uc778\ud558\ub294 \uc5f0\uad6c\ub294 \uc911\uc694\ud558\uc9c0\ub9cc, \uad00\uac1d\uc758 \uac10\uc0c1\uc774 \uadf8 \ud655\uc778 \uc804\uae4c\uc9c0 \uc815\uc9c0\ud574\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc544\ub294 \uc0ac\uc2e4\uc774 \uc801\uc744 \ub54c\uc5d0\ub3c4 \uc0c9\uacfc \uc790\uc138, \ubb3c\uac74\uc758 \uad00\uacc4\ub97c \ubcfc \uc218 \uc788\ub2e4. \ub098\uc911\uc5d0 \ub354 \uc815\ud655\ud55c \uc815\ubcf4\ub97c \uc5bb\uc73c\uba74 \uadf8\ub54c \ub2e4\uc2dc \uadf8\ub9bc\uc73c\ub85c \ub3cc\uc544\uc624\uba74 \ub41c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uc61b \ub8e8\ube0c\ub974 \ub3c4\ub85d\uc5d0 \uc2e4\ub9b0 \uc2e4\uc81c \ud68c\ud654 \uc7ac\ud604 \uc790\ub8cc\ub2e4. \uac80\uc740 \uc637\uacfc \ubc30\uacbd\uc758 \ubbf8\ubb18\ud55c \ucc28\uc774\ub294 \uc61b \uc778\uc1c4\uc5d0\uc11c \uc2e4\ubb3c\uacfc \ub2e4\ub974\uac8c \ubcf4\uc77c \uc218 \uc788\ub2e4. \uadf8\ub7ec\ubbc0\ub85c \ubaa8\ub4e0 \uc5b4\ub450\uc6b4 \ubd80\ubd84\uc758 \ud45c\uba74\uae4c\uc9c0 \ud655\uc815\ud558\uae30\ubcf4\ub2e4 \ud070 \ubc1d\uae30\uc640 \uc778\ubb3c\uc758 \ubc30\uce58\ub97c \uc911\uc2ec\uc73c\ub85c \uc0b4\ud3b4\ubcf4\uc558\ub2e4. \uc6d0\uc791\uc744 \ub2ee\uac8c \uc0c8\ub85c \ub9cc\ub4e0 AI \ucd08\uc0c1\uc774 \uc544\ub2c8\ub77c \uc2e4\uc81c \uc791\ud488\uc758 \ub3c4\ud310\uc774\ub77c\ub294 \uc810\uc740 \uad6c\ubd84\ud574 \ub450\uba74 \uc88b\ub2e4. \ud604\ub300\uc778\uc774 \uc0c1\uc0c1\ud55c \ub0a8\uc790\uc758 \uc637\ucc28\ub9bc\uc744 \ud2f0\uce58\uc544\ub178\uc758 \uc120\ud0dd\uc774\ub77c\uace0 \uc124\uba85\ud558\uc9c0 \uc54a\uae30 \uc704\ud574\uc11c\ub2e4. \uc774\ubbf8\uc9c0\uc758 \uc885\ub958\ub97c \uc54c\uace0 \ubcf4\ub294 \uac83\uc774 \uc791\ud488\uc5d0 \uad00\ud55c \uc9c0\uc2dd\uc744 \ub354 \ub2e8\ub2e8\ud558\uac8c \ud574 \uc900\ub2e4. \uadf8\ub9bc\uc744 \ubcf8 \ub4a4 \uc81c\ubaa9\uc744 \ub2e4\uc2dc \uc77d\uc73c\uba74 \uc7a5\uac11\uc774\ub77c\ub294 \uc791\uc740 \ubb3c\uac74\uc774 \ub2e4\ub978 \ubb34\uac8c\ub97c \uac00\uc9c4\ub2e4. \uc5bc\uad74\uacfc \uc190, \ucc28\ub9bc\uc0c8\ub97c \uc5f0\uacb0\ud574 \uae30\uc5b5\ud558\uac8c \ud558\ub294 \ud45c\uc9c0\uac00 \ub418\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4. \ud3c9\ubc94\ud55c \ubb3c\uac74\ub3c4 \ud654\uba74 \uc18d \uc704\uce58\uc640 \uad00\uacc4\uc5d0 \ub530\ub77c \uc0ac\ub78c\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc5f4\uc1e0\uac00 \ub420 \uc218 \uc788\ub2e4. \uc624\ub298\uc740 \uc774 \ub0a8\uc790\uc758 \ubaa8\ub4e0 \uc0ac\uc5f0\uc744 \uc54c\uc544\ub0b4\ub824 \ud558\uc9c0 \uc54a\uc544\ub3c4 \uc88b\ub2e4. \uc5b4\ub5a4 \ubd80\ubd84\uc740 \ubc1d\uac8c \ub4dc\ub7ec\ub098\uace0 \uc5b4\ub5a4 \ubd80\ubd84\uc740 \uc5b4\ub460\uc5d0 \ub0a8\ub294\uc9c0 \ubcf4\uba70 \ud55c \uc0ac\ub78c\uc758 \uc55e\uc5d0 \uc7a0\uc2dc \uba38\ubb3c\ub7ec \ubcf4\uc790. \ucd08\uc0c1\ud654\uc758 \uad50\uc591\uc740 \uc774\ub984\uc744 \uc678\uc6b0\ub294 \uc77c\ubfd0 \uc544\ub2c8\ub77c \uc0ac\ub78c\uc744 \ubcf4\ub294 \uc790\uc2e0\uc758 \uc2b5\uad00\uc744 \uc870\uae08 \ub113\ud788\ub294 \ub370\uc11c\ub3c4 \uc0dd\uae34\ub2e4."}, {"id": "tolstoy-pahom-land-and-sunset", "title": "\uc0ac\ub78c\uc5d0\uac8c\ub294 \uc5bc\ub9c8\ub9cc\ud07c\uc758 \ub545\uc774 \ud544\uc694\ud55c\uac00 \u2014 \ud574\uac00 \uc9c0\uae30 \uc804\uc5d0 \ub3cc\uc544\uc640\uc57c \ud588\ub358 \uc0ac\ub78c", "summary": "\ud30c\ud648\uc758 \uc774\uc8fc\uc640 \ub545 \uac70\ub798, \uc77c\ubab0\uc758 \uadc0\ud658\uc744 \ub530\ub77c \ucda9\ubd84\ud568\uc758 \uae30\uc900\uacfc \uc0b6\uc758 \uc2dc\uac04\uc744 \ubb3b\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/tolstoy-pahom-land-and-sunset/index.html", "image": "../media/tolstoy-pahom-land-and-sunset.png", "alt": "\ub113\uc740 \ucd08\uc6d0\uacfc \ub18d\uacbd\uc9c0\ub97c \ubc14\ub77c\ubcf4\ub294 \ud30c\ud648\uc744 \uc5f0\uc0c1\ud558\ub294 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uc0ac\ub78c\uc5d0\uac8c\ub294 \uc5bc\ub9c8\ub9cc\ud07c\uc758 \ub545\uc774 \ud544\uc694\ud55c\uac00 \u2014 \ud574\uac00 \uc9c0\uae30 \uc804\uc5d0 \ub3cc\uc544\uc640\uc57c \ud588\ub358 \uc0ac\ub78c \ud1a8\uc2a4\ud1a0\uc774\uc758 \uc9e7\uc740 \uc6b0\ud654\uc5d0\uc11c \uacbd\uacc4\uc640 \uc77c\ubab0, \ub9c8\uc9c0\ub9c9 \uadc0\ud658\uc744 \uc77d\uae30 \ud30c\ud648\uc758 \uc774\uc8fc\uc640 \ub545 \uac70\ub798, \uc77c\ubab0\uc758 \uadc0\ud658\uc744 \ub530\ub77c \ucda9\ubd84\ud568\uc758 \uae30\uc900\uacfc \uc0b6\uc758 \uc2dc\uac04\uc744 \ubb3b\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \ub545\uc774 \uc870\uae08\ub9cc \ub354 \uc788\ub2e4\uba74 \uac71\uc815 \uc5c6\uc774 \uc0b4 \uc218 \uc788\uc744 \uac83 \uac19\ub2e4. \ud1a8\uc2a4\ud1a0\uc774\uc758 \uc9e7\uc740 \uc774\uc57c\uae30 \u300c\uc0ac\ub78c\uc5d0\uac8c\ub294 \uc5bc\ub9c8\ub9cc\ud07c\uc758 \ub545\uc774 \ud544\uc694\ud55c\uac00\u300d\ub294 \uc774\ud574\ud558\uae30 \uc26c\uc6b4 \ubc14\ub78c\uc5d0\uc11c \ucd9c\ubc1c\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc5bb\uc744 \uc218 \uc788\ub294 \ub545\uc758 \ubc94\uc704\uac00 \ucee4\uc9c8\uc218\ub85d \uc8fc\uc778\uacf5\uc758 \ubd88\uc548\ub3c4 \ucee4\uc9c4\ub2e4. \uc544\ub798\uc5d0\ub294 \ud30c\ud648\uc758 \uc5ec\uc815\uacfc \uacb0\ub9d0\uc774 \ud3ec\ud568\ub41c\ub2e4. \uc774\uc57c\uae30\ub294 \ub3c4\uc2dc\uc758 \uc0dd\ud65c\uacfc \ub18d\ucd0c\uc758 \uc0dd\ud65c\uc744 \ube44\uad50\ud558\ub294 \uc790\ub9e4\uc758 \ub300\ud654\ub85c \uc2dc\uc791\ud55c\ub2e4. \ub18d\ubd80 \ud30c\ud648\uc740 \ub545\ub9cc \ucda9\ubd84\ud558\uba74 \ub450\ub824\uc6b8 \uac83\uc774 \uc5c6\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4. \ubd80\uc871\ud568\uc758 \uc6d0\uc778\uc744 \ud55c \uac00\uc9c0\ub85c \uc881\ud788\uba74 \ud574\uacb0\ucc45\ub3c4 \ub2e8\uc21c\ud574 \ubcf4\uc778\ub2e4. \uc18c\uc720\ud560 \ub545\uc744 \ub298\ub9ac\uba74 \uc0b6\uc758 \ubb38\uc81c\uac00 \ub05d\ub0a0 \uac83\uc774\ub77c\ub294 \uae30\ub300\ub2e4. \uadf8\uc758 \ub9d0\uc744 \ub4e3\ub294 \uc545\ub9c8\uc758 \uc874\uc7ac\ub294 \uc774 \uc774\uc57c\uae30\uac00 \uc77c\uc0c1\uc801\uc778 \ub18d\ucd0c \uae30\ub85d\ub9cc\uc740 \uc544\ub2d8\uc744 \uc54c\ub824 \uc900\ub2e4. \ub3c4\ub355\uc801 \uc6b0\ud654\uc758 \uc7a5\uce58\uac00 \uc791\ub3d9\ud55c\ub2e4. \ud558\uc9c0\ub9cc \uc8fc\uc778\uacf5\uc758 \ucd9c\ubc1c\uc744 \ud130\ubb34\ub2c8\uc5c6\ub294 \ud0d0\uc695\uc73c\ub85c\ub9cc \ubcfc \ud544\uc694\ub294 \uc5c6\ub2e4. \uc0dd\ud65c \uae30\ubc18\uc744 \uc548\uc815\uc2dc\ud0a4\uace0 \uc2f6\uc740 \uc695\uad6c \uc790\uccb4\ub294 \ub3c5\uc790\ub3c4 \uc27d\uac8c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ud30c\ud648\uc740 \uae30\ud68c\ub97c \uc5bb\uc5b4 \ub545\uc744 \uc0b0\ub2e4. \ub0a8\uc758 \ucc98\ubd84\uc5d0 \uae30\ub300\ub358 \ucc98\uc9c0\uc5d0\uc11c \uc790\uae30 \uc18c\uc720\ub97c \uac00\uc9c4 \uc0ac\ub78c\uc73c\ub85c \ubc14\ub010\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uae30\uc058\uc9c0\ub9cc \uc774\uc6c3\uc758 \uac00\ucd95\uacfc \uacbd\uacc4 \ubb38\uc81c, \uc190\ud574\ub97c \ub458\ub7ec\uc2fc \ub2e4\ud23c\uc774 \uc0dd\uae34\ub2e4. \uc18c\uc720\uac00 \uac08\ub4f1\uc758 \ubc14\uae65\uc73c\ub85c \uadf8\ub97c \uc62e\uaca8 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc774\uc804\uc5d0\ub294 \uc790\uc2e0\ub3c4 \uacaa\uc5c8\ub358 \ubb38\uc81c\uac00 \uc774\uc81c\ub294 \uc7ac\uc0b0\uc744 \uc9c0\ucf1c\uc57c \ud558\ub294 \uc8fc\uc778\uc758 \uad00\uc810\uc5d0\uc11c \ubcf4\uc778\ub2e4. \uad00\uacc4\uac00 \ub2ec\ub77c\uc9c0\uc790 \uac19\uc740 \uc0c1\ud669\uc744 \ud310\ub2e8\ud558\ub294 \ubc29\uc2dd\ub3c4 \ubc14\ub010\ub2e4. \ub545\uc758 \uba74\uc801\uc774 \ub298\uc5b4\ub098\ub294 \uc774\uc57c\uae30\uc778 \ub3d9\uc2dc\uc5d0 \ud30c\ud648\uc774 \uc8fc\ubcc0 \uc0ac\ub78c\uc744 \ubc14\ub77c\ubcf4\ub294 \ud0dc\ub3c4\uac00 \ubc14\ub00c\ub294 \uc774\uc57c\uae30\ub2e4. \uc0c8\ub85c\uc6b4 \ub545\uc758 \uc18c\uc2dd\uc774 \ucc3e\uc544\uc628\ub2e4. \uc9c0\uae08\ubcf4\ub2e4 \ub113\uace0 \uac12\uc774 \uc2fc \uacf3\uc774 \uc788\ub2e4\ub294 \ub9d0\uc740 \uc774\ubbf8 \uc5bb\uc740 \uac83\uc744 \ucda9\ubd84\ud558\uc9c0 \uc54a\uac8c \ub9cc\ub4e0\ub2e4. \ud30c\ud648\uc740 \uc62e\uaca8 \uac00\uace0 \ub610 \ub2e4\ub978 \uae30\ud68c\ub97c \ucc3e\ub294\ub2e4. \ube44\uad50 \ub300\uc0c1\uc774 \ubc14\ub014 \ub54c\ub9c8\ub2e4 \ub9cc\uc871\ud574\uc57c \ud560 \uae30\uc900\ub3c4 \ub4a4\ub85c \ubc00\ub9b0\ub2e4. \uc5ec\uae30\uc11c \uc695\ub9dd\uc740 \uc5b8\uc81c\ub098 \uc870\uae08\ub9cc \ub354\ub77c\ub294 \ud615\ud0dc\ub97c \ucde8\ud55c\ub2e4. \ucc98\uc74c\ubd80\ud130 \ub05d\uc5c6\ub294 \uc7ac\uc0b0\uc744 \uc6d0\ud55c\ub2e4\uace0 \uc120\uc5b8\ud558\uc9c0 \uc54a\uc544\ub3c4 \ucda9\ubd84\ud568\uc758 \uacbd\uacc4\ub294 \uacc4\uc18d \uba40\uc5b4\uc9c8 \uc218 \uc788\ub2e4. \ud604\uc7ac\uc758 \uc0b6\uc744 \ub3cc\ubcf4\ub294 \uc2dc\uac04\ubcf4\ub2e4 \ub2e4\uc74c\uc758 \ub354 \uc88b\uc740 \uc870\uac74\uc744 \ucc3e\ub294 \uc77c\uc774 \uc911\uc694\ud574\uc9c4\ub2e4. \ud30c\ud648\uc740 \ubc14\uc2dc\ud0a4\ub974\uc778\ub4e4\uc774 \uc0ac\ub294 \uacf3\uc5d0\uc11c \ud2b9\ubcc4\ud55c \uc870\uac74\uc744 \uc81c\uc548\ubc1b\ub294\ub2e4. \uc77c\uc815\ud55c \ub3c8\uc744 \ub0b4\uace0 \ud558\ub8e8 \ub3d9\uc548 \uac78\uc5b4 \uacbd\uacc4\ub97c \uc815\ud55c \ub545\uc744 \uac00\uc9c8 \uc218 \uc788\uc9c0\ub9cc, \ud574\uac00 \uc9c0\uae30 \uc804\uc5d0 \ucd9c\ubc1c\uc810\uc73c\ub85c \ub3cc\uc544\uc640\uc57c \ud55c\ub2e4. \uba74\uc801\uc774 \uc815\ud574\uc9c4 \ubb3c\uac74\uc744 \uc0ac\ub294 \uc77c\uacfc \ub2ec\ub9ac \uc790\uae30 \uac78\uc74c\uc774 \uc18c\uc720\uc758 \ud06c\uae30\ub97c \uacb0\uc815\ud55c\ub2e4. \uc870\uac74\uc5d0\ub294 \uc2dc\uc791\ubd80\ud130 \uc81c\ud55c\uc774 \uc788\ub2e4. \uadf8\ub7f0\ub370 \ud30c\ud648\uc5d0\uac8c\ub294 \ub3cc\uc544\uc640\uc57c \ud55c\ub2e4\ub294 \uc758\ubb34\ubcf4\ub2e4 \ub354 \uba40\ub9ac \uac08 \uc218 \uc788\ub2e4\ub294 \uac00\ub2a5\uc131\uc774 \ud06c\uac8c \ubcf4\uc778\ub2e4. \ubb34\uc5c7\uc744 \uc5bb\ub294\uc9c0\uc640 \ubb34\uc5c7\uc744 \uc9c0\ucf1c\uc57c \ud558\ub294\uc9c0\ub97c \uac19\uc740 \ubb34\uac8c\ub85c \ubcf4\uc9c0 \uc54a\ub294 \ud0dc\ub3c4\uac00 \ub9c8\uc9c0\ub9c9 \ud558\ub8e8\uc758 \ubc29\ud5a5\uc744 \uc815\ud55c\ub2e4. \uacc4\uc57d\uc744 \uc815\ud558\ub294 \uc7a5\uba74\uc5d0\ub294 \ud1b5\uc5ed\uacfc \uc120\ubb3c, \ub300\ud45c\uc790\uc640\uc758 \ub300\ud654\uac00 \ub4f1\uc7a5\ud55c\ub2e4. \ud30c\ud648\uc740 \uc790\uc2e0\uc774 \uc775\uc219\ud55c \uc0dd\ud65c\uad8c\uc744 \ub5a0\ub098 \ub2e4\ub978 \uad00\uacc4 \uc18d\uc73c\ub85c \ub4e4\uc5b4\uac04\ub2e4. \uadf8\ub7f0\ub370\ub3c4 \uadf8\uac00 \uacc4\uc0b0\ud558\ub294 \uac83\uc740 \uc8fc\ub85c \uc5bb\uc744 \ub545\uc758 \ub113\uc774\ub2e4. \uac70\ub798\uac00 \uc774\ub8e8\uc5b4\uc9c0\ub294 \uc0ac\ud68c\uc801\uc778 \uc0c1\ud669\uacfc \uc790\uae30\uac00 \uac00\uc9c8 \ubaab \uc0ac\uc774\uc758 \ucc28\uc774\ub3c4 \uc77d\uc744 \uc218 \uc788\ub2e4. \uc804\ub0a0 \ubc24\uc758 \uafc8\uc740 \ub9c8\uc9c0\ub9c9 \uacb0\ub9d0\uc744 \ubbf8\ub9ac \ube44\ucd94\ub294 \uc7a5\uce58\ub2e4. \ud30c\ud648 \uc55e\uc5d0 \ub098\ud0c0\ub098\ub294 \uc5bc\uad74\uc774 \ubc14\ub00c\uba70 \uadf8\ub97c \ub2e4\uc74c \uae30\ud68c\ub85c \uc774\ub04c\uc5c8\ub358 \uc0ac\ub78c\ub4e4\uc774 \uc5f0\uacb0\ub41c\ub2e4. \uae68\uc5b4\ub09c \uadf8\ub294 \ubd88\uae38\ud55c \ub290\ub08c\uc744 \uc7a0\uae50 \ub0a8\uae30\uc9c0\ub9cc \uae38\uc744 \ub5a0\ub09c\ub2e4. \uc774\uc57c\uae30\ub294 \uacbd\uace0\uac00 \uc874\uc7ac\ud574\ub3c4 \ud589\ub3d9\uc774 \ubc14\ub00c\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ud30c\ud648\uc740 \uc774\ub978 \uc544\uce68 \uae38\uc744 \ub098\uc120\ub2e4. \uc5b4\ub290 \uc815\ub3c4 \uac78\uc73c\uba74 \ub418\ub3cc\uc544\uac08 \uc218\ub3c4 \uc788\uc9c0\ub9cc \ub208\uc55e\uc758 \uc88b\uc740 \ub545\uc744 \ub193\uce58\uae30 \uc544\uae5d\ub2e4. \uacbd\uacc4\ub97c \uc870\uae08 \ub354 \ub113\ud788\uace0 \ub2e4\uc2dc \ubc29\ud5a5\uc744 \ubc14\uafb8\uba74\uc11c \ucd9c\ubc1c\uc810\uacfc\uc758 \uac70\ub9ac\ub294 \ucee4\uc9c4\ub2e4. \ud48d\uc694\ub85c\uc6cc \ubcf4\uc774\ub294 \uc7a5\uc18c\uac00 \uac78\uc74c\uc744 \uc7ac\ucd09\ud558\ub294 \uc720\ud639\uc774 \ub41c\ub2e4. \ubab8\uc740 \uc9c0\uce58\uace0 \ud587\ube5b\uc740 \uac15\ud574\uc9c4\ub2e4. \ub3c5\uc790\ub294 \uadf8\uac00 \ub545\uc744 \uc5bb\ub294 \ub370 \uc4f0\ub294 \ubab8\uc774 \ubc14\ub85c \uc55e\uc73c\ub85c \uadf8 \ub545\uc5d0\uc11c \uc0b4\uc544\uc57c \ud560 \ubab8\uc784\uc744 \ubcf8\ub2e4. \uadf8\ub7ec\ub098 \ud30c\ud648\uc740 \ubbf8\ub798\uc758 \uc18c\uc720\ub97c \uacc4\uc0b0\ud558\ub294 \ub3d9\uc548 \ud604\uc7ac\uc758 \uccb4\ub825\uacfc \uc2dc\uac04\uc744 \uc18c\ubaa8\ud55c\ub2e4. \ub458\uc740 \ub530\ub85c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \uc790\uc6d0\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ub2a6\uc5c8\ub2e4\uace0 \uae68\ub2ec\uc740 \ub4a4\uc5d0\ub294 \ub3cc\uc544\uc624\ub294 \uae38\uc744 \uc11c\ub450\ub97c \uc218\ubc16\uc5d0 \uc5c6\ub2e4. \ucd9c\ubc1c\uc810\uc740 \ub208\uc55e\uc5d0 \ubcf4\uc774\uc9c0\ub9cc \uc9c0\uce5c \ubab8\uc73c\ub85c \ub3c4\ucc29\ud558\uae30\ub294 \uc27d\uc9c0 \uc54a\ub2e4. \ud30c\ud648\uc5d0\uac8c \ub354 \uc774\uc0c1 \uc88b\uc740 \ub545\uc740 \uc911\uc694\ud558\uc9c0 \uc54a\ub2e4. \ubc29\uae08\uae4c\uc9c0 \ub113\ud788\ub824\ub358 \uacbd\uacc4\ub97c \ubc97\uc5b4\ub098 \uc81c\uc2dc\uac04\uc5d0 \ub3cc\uc544\uc624\ub294 \uac83\ub9cc\uc774 \ubaa9\ud45c\uac00 \ub41c\ub2e4. \uadf8\ub294 \ub9c8\uce68\ub0b4 \ub3cc\uc544\uc624\uc9c0\ub9cc \uace7 \uc4f0\ub7ec\uc838 \uc8fd\ub294\ub2e4. \uaddc\uce59\uc744 \ub9cc\uc871\uc2dc\ud0a4\ub294 \uc77c\uacfc \uc0b6\uc744 \uc9c0\ud0a4\ub294 \uc77c\uc774 \ub9c8\uc9c0\ub9c9\uc5d0 \uac08\ub77c\uc9c4\ub2e4. \ud558\uc778\uc740 \uadf8\ub97c \ubb3b\uc744 \ub545\uc744 \ud310\ub2e4. \uc81c\ubaa9\uc758 \uc9c8\ubb38\uc5d0 \ub3cc\uc544\uc624\ub294 \ub2f5\uc740 \uadf8\uac00 \ud558\ub8e8 \ub3d9\uc548 \ud655\ubcf4\ud558\ub824 \ud55c \uba74\uc801\uc774 \uc544\ub2c8\ub77c \ud55c \uc0ac\ub78c\uc758 \ubb34\ub364\uc5d0 \ud544\uc694\ud55c \uae38\uc774\ub2e4. \uc774 \uc791\ud488\uc744 \ub545\uc744 \uac00\uc9c0\ub294 \uc77c\uc774 \ubaa8\ub450 \uc798\ubabb\uc774\ub77c\ub294 \uc8fc\uc7a5\uc73c\ub85c \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud30c\ud648\uc5d0\uac8c \uacbd\uc791\uc9c0\uc640 \uc548\uc815\ub41c \uc0dd\ud65c\uc740 \uc2e4\uc81c\ub85c \uc911\uc694\ud588\ub2e4. \ubb38\uc81c\ub294 \uc5bc\ub9c8\uac00 \ucda9\ubd84\ud55c\uc9c0 \ud310\ub2e8\ud558\uc9c0 \ubabb\ud55c \ucc44 \uc18c\uc720\uc758 \ud655\ub300\ub97c \uc0b6\uc758 \uc548\uc804\uacfc \uac19\uc740 \uac83\uc73c\ub85c \uc0dd\uac01\ud588\ub2e4\ub294 \ub370 \uc788\ub2e4. \ub610\ud55c \ubc14\uc2dc\ud0a4\ub974\uc778\uc5d0 \ub300\ud55c \uc774\uc57c\uae30 \uc18d \ubb18\uc0ac\ub97c \uc2e4\uc81c \uacf5\ub3d9\uccb4 \uc804\uccb4\uc758 \uc131\uaca9\uc73c\ub85c \uc77c\ubc18\ud654\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc6b0\ud654\uac00 \uc778\ubb3c\uc744 \ubc30\uce58\ud55c \ubc29\uc2dd\uacfc \ud604\uc2e4\uc758 \uc0ac\ub78c\ub4e4\uc740 \ub2e4\ub974\ub2e4. \uc81c\ubaa9\uc740 \uba74\uc801\uc744 \ubb3b\uc9c0\ub9cc \uacb0\ub9d0\uc740 \uc0b4\uc544\uac08 \uc2dc\uac04\uc744 \uc5b4\ub5bb\uac8c \uc4f8 \uac83\uc778\uc9c0 \ub2e4\uc2dc \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ub0a8\uc740 \uc9c8\ubb38\uc740 \ub3c5\uc790 \ucabd\uc73c\ub85c \ud5a5\ud55c\ub2e4. \ub354 \uc5bb\uc744 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ub354 \uc5bb\uc5b4\uc57c \ud558\ub294\uc9c0, \ub3cc\uc544\uac08 \uc2dc\uac04\uc744 \uc5b8\uc81c \ub0a8\uaca8 \ub458 \uac83\uc778\uc9c0 \ubb3b\ub294 \uac83\uc774\ub2e4."}, {"id": "topkapi-courts-gates-and-government", "title": "\ud1b1\uce74\ud504 \uad81\uc804 \u2014 \ubb38\uc744 \uc9c0\ub0a0 \ub54c \uc81c\uad6d\uc758 \uc77c\uc740 \uc5b4\ub5bb\uac8c \ub098\ub258\uc5c8\uc744\uae4c", "summary": "\ubb38\uc744 \uc9c0\ub098\ub294 \uaddc\uce59\uacfc \ud68c\uc758\u00b7\uc811\uacac\u00b7\uc0dd\ud65c \uacf5\uac04\uc73c\ub85c \uad81\uc804\uc744 \ud558\ub098\uc758 \uc870\uc9c1\uc73c\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uac74\ucd95", "categories": ["arts"], "url": "stories/topkapi-courts-gates-and-government/index.html", "image": "../media/topkapi-courts-gates-and-government.jpg", "alt": "\ud1b1\uce74\ud504 \uad81\uc804\uc758 \uc61b \ubaa8\ud241\uc774 \uac74\ubb3c\uacfc \ub098\ubb34\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc5ed\uc0ac \uc120\ubb18 \ub3c4\ud310", "text": "\ud1b1\uce74\ud504 \uad81\uc804 \u2014 \ubb38\uc744 \uc9c0\ub0a0 \ub54c \uc81c\uad6d\uc758 \uc77c\uc740 \uc5b4\ub5bb\uac8c \ub098\ub258\uc5c8\uc744\uae4c \ud1b1\uce74\ud504\uc758 \ubb38\u00b7\ub730\u00b7\ud68c\uc758\u00b7\ubd80\uc5cc\uc5d0\uc11c \uc77d\ub294 \uad8c\ub825\uacfc \uc0dd\ud65c\uc758 \ubc30\uce58 \ubb38\uc744 \uc9c0\ub098\ub294 \uaddc\uce59\uacfc \ud68c\uc758\u00b7\uc811\uacac\u00b7\uc0dd\ud65c \uacf5\uac04\uc73c\ub85c \uad81\uc804\uc744 \ud558\ub098\uc758 \uc870\uc9c1\uc73c\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uac74\ucd95 \ubb38\ud654\uc640 \uc608\uc220 \uad81\uc804\uc774\ub77c\uace0 \ud558\uba74 \uac00\uc7a5 \ud06c\uace0 \ud654\ub824\ud55c \ud55c \uac74\ubb3c\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uc774\uc2a4\ud0c4\ubd88\uc758 \ud1b1\uce74\ud504\ub294 \ubb38\uacfc \ub730, \uc5ec\ub7ec \uc804\uac01\uacfc \uc0dd\ud65c \uacf5\uac04\uc774 \uc774\uc5b4\uc9c0\ub294 \uc7a5\uc18c\ub2e4. \ub204\uad6c\ub098 \uac19\uc740 \uae38\uacfc \uac19\uc740 \uc790\ub9ac\ub97c \uc774\uc6a9\ud558\uc9c0\ub294 \uc54a\uc558\ub2e4. \uacf5\uac04\uc744 \ub530\ub77c\uac00\uba74 \uc81c\uad6d\uc758 \uad8c\ub825\uacfc \uc77c\uc0c1\uc774 \uc5b4\ub5bb\uac8c \ub098\ub258\uc5c8\ub294\uc9c0 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \ud1b1\uce74\ud504\uc5d0\ub294 \uc5ec\ub7ec \uc2dc\uae30\uc5d0 \ub9c8\ub828\ub418\uace0 \ubc14\ub010 \uacf5\uac04\uc774 \uacb9\uccd0 \uc788\ub2e4. \ubc14\ub2e4\uc640 \ub3c4\uc2dc\ub97c \ubc14\ub77c\ubcf4\ub294 \ubc18\ub3c4 \uc704\uc758 \uc704\uce58\ub3c4 \uad81\uc804\uc758 \uacbd\ud5d8\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uac1c\ubcc4 \uc804\uac01\uc758 \ud654\ub824\ud568\ub9cc\uc73c\ub85c \uc7a5\uc18c \uc804\uccb4\ub97c \uc774\ud574\ud558\uae30 \uc5b4\ub835\ub2e4. \uac74\ubb3c \uc0ac\uc774\uc758 \uac70\ub9ac\uc640 \uc811\uadfc \uc21c\uc11c\uac00 \uc911\uc694\ud558\ub2e4. \uc61b \uc5ec\ud589 \uae30\ub85d\uc5d0\ub294 \uc774\uacf3\uc744 \uc62c\ub4dc \uc138\ub77c\uae00\ub9ac\uc624\ub77c\uace0 \ubd80\ub974\ub294 \ud45c\ud604\uc774 \uc790\uc8fc \ub098\uc628\ub2e4. \uc624\ub298\uc758 \uba85\uce6d\uacfc \uacfc\uac70\uc758 \ud638\uce6d\uc744 \uc5f0\uacb0\ud558\ub418, \ub3c4\uc2dc\uc758 \ub2e4\ub978 \uc61b \uad81\uc804\uacfc \ud63c\ub3d9\ud558\uc9c0 \uc54a\uc744 \ud544\uc694\uac00 \uc788\ub2e4. \uc774\ub984\uc774 \uac00\ub9ac\ud0a4\ub294 \uacf5\uac04\ub3c4 \uc2dc\ub300\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ubc14\uae65\ubb38\uacfc \uc911\uac04\ubb38\uc740 \uc774\ub3d9\uc744 \ub098\ub208\ub2e4. \uac19\uc740 \ub3c4\uc2dc \uc548\uc5d0\uc11c\ub3c4 \ubb38\uc744 \uc9c0\ub0a0\uc218\ub85d \ub4e4\uc5b4\uac08 \uc218 \uc788\ub294 \uc0ac\ub78c\uacfc \ud589\ub3d9\uc758 \uc870\uac74\uc774 \ub2ec\ub77c\uc84c\ub2e4. \uacbd\uacc4\ub294 \ubcbd\uc758 \ub450\uaed8\ubfd0 \uc544\ub2c8\ub77c \ud5c8\ub77d\uacfc \uaddc\uce59\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc84c\ub2e4. \uad81\uc804\uc740 \uc811\uadfc\uc744 \uc870\uc808\ud558\ub294 \uacf5\uac04\uc774\uae30\ub3c4 \ud588\ub2e4. \uc70c\ub9ac\uc5c4 \ud640\ub4e0 \ud5c8\ud134\uc758 \uc61b \uc548\ub0b4\uc11c\ub294 \uc911\uac04\ubb38\uc744 \uc9c0\ub09c \ubc29\ubb38\uc5d0 \ubcc4\ub3c4\uc758 \ud5c8\ub77d\uc774 \ud544\uc694\ud558\ub358 \uc77c\uc744 \uc804\ud55c\ub2e4. \uc774\ub97c \uc624\ub298\uc758 \uc785\uc7a5 \uc808\ucc28\uc640 \uac19\ub2e4\uace0 \uc124\uba85\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uadf8 \uae30\ub85d\uc740 \ub2f9\uc2dc \uc678\uad6d \ubc29\ubb38\uac1d\uc774 \uad81\uc804\uc744 \uacbd\ud5d8\ud55c \uc870\uac74\uacfc \uad8c\uc704\ub97c \ud568\uaed8 \ubcf4\uc5ec \uc900\ub2e4. \ud5c8\ud134\uc740 \uc911\uac04\ubb38 \uc548\uc5d0\uc11c \uc220\ud0c4\ub9cc \ub9d0\uc744 \ud0c4 \ucc44 \ub4e4\uc5b4\uac08 \uc218 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc774\ub3d9 \ubc29\uc2dd\uc758 \ucc28\uc774\uac00 \uc2e0\ubd84\uc758 \ucc28\uc774\ub97c \ub4dc\ub7ec\ub0b4\ub294 \uc148\uc774\ub2e4. \ub9d0\uacfc \ubc1c\uc758 \ub192\uc774\uac00 \uad8c\ub825\uc758 \uc9c8\uc11c\uc640 \uc5f0\uacb0\ub41c\ub2e4. \uacf5\uac04\uc758 \uaddc\uce59\uc740 \ubab8\uc744 \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc77c\uc9c0\ub3c4 \uc815\ud588\ub2e4. \uc678\uad6d \uc0ac\uc808\uc744 \uae30\ub2e4\ub9ac\uac8c \ud558\uace0 \uc5b4\ub5a4 \ucc28\ub9bc\uc73c\ub85c \ub098\ud0c0\ub098\uac8c \ud558\ub294\uc9c0\ub3c4 \uc758\ub840\uc758 \uc77c\ubd80\uc600\ub2e4. \uc811\uacac\uc740 \ub9d0\uc744 \ub098\ub204\ub294 \uc21c\uac04\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uae30\ub2e4\ub9bc\uacfc \uc774\ub3d9, \uc637\uacfc \uc790\ub9ac\uc758 \ubc30\uce58\uac00 \ub9cc\ub0a8\uc758 \uc758\ubbf8\ub97c \ubbf8\ub9ac \uc815\ud55c\ub2e4. \uac74\ucd95\uacfc \uc758\ub840\uac00 \uc11c\ub85c\ub97c \ub4b7\ubc1b\uce68\ud55c \uac83\uc774\ub2e4. \ub514\ubc18\uc758 \uacf5\uac04\uc5d0\uc11c\ub294 \ub300\uc2e0\ub4e4\uc774 \uc77c\uc744 \ub17c\ud588\ub2e4. \uc61b \uc124\uba85\uc5d0\ub294 \uc220\ud0c4\uc774 \uaca9\uc790 \ub4a4\uc5d0\uc11c \ub4e4\uc744 \uc218 \uc788\ub294 \uc704\uce58\ub3c4 \ub4f1\uc7a5\ud55c\ub2e4. \ub204\uac00 \ub9d0\ud558\uace0 \ub204\uac00 \ub4e3\ub294\uc9c0\uac00 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ubcf4\uc774\uc9c0 \uc54a\uc744 \uc218 \uc788\uc5c8\ub2e4. \uc5bc\uad74\uc744 \ub4dc\ub7ec\ub0b4\ub294 \uac83\uacfc \uc601\ud5a5\ub825\uc744 \uac16\ub294 \uac83\uc740 \ub2e4\ub978 \ubb38\uc81c\ub2e4. \uc774\uac83\uc744 \uc5b8\uc81c\ub098 \ub611\uac19\uc774 \uc791\ub3d9\ud55c \uac10\uc2dc \uc7a5\uce58\ub85c\ub9cc \ub2e8\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uad6c\uccb4\uc801\uc778 \uc2dc\ub300\uc640 \ud589\uc0ac\uc5d0 \ub530\ub77c \uc0ac\uc6a9\uc740 \ub2ec\ub790\uc744 \uac83\uc774\ub2e4. \ub2e4\ub9cc \uacf5\uac04\uc774 \uc815\uce58\uc801 \uad00\uacc4\ub97c \ud45c\ud604\ud55c\ub2e4\ub294 \uc810\uc740 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ud68c\uc758\uc2e4\uc758 \ubcbd\uacfc \ucc3d\ub3c4 \uad8c\ub825\uc774 \uc6c0\uc9c1\uc774\ub294 \uc870\uac74\uc774\uc5c8\ub2e4. \ud654\ub824\ud55c \uc811\uacac\uc2e4 \uacc1\uc5d0\ub294 \ub9ce\uc740 \uc0ac\ub78c\uc758 \uc0dd\ud65c\uc744 \uc720\uc9c0\ud558\ub294 \uc2dc\uc124\uc774 \uc788\uc5c8\ub2e4. \ud070 \ubd80\uc5cc\uc740 \uad81\uc804\uc774 \ubcf4\ub294 \uc7a5\uc18c\ubfd0 \uc544\ub2c8\ub77c \uba39\uace0 \uc77c\ud558\ub294 \uc7a5\uc18c\uc600\uc74c\uc744 \uc54c\ub824 \uc900\ub2e4. \uad8c\ub825\uc758 \uc77c\uc0c1\uc5d0\ub294 \ubc18\ubcf5\ud574\uc11c \uc900\ube44\ud574\uc57c \ud558\ub294 \uc74c\uc2dd\uacfc \ubb3c\uc790\uac00 \ud544\uc694\ud588\ub2e4. \uc220\ud0c4\uacfc \ubcf4\ubb3c\ub9cc \uae30\uc5b5\ud558\uba74 \uadf8\ub7f0 \uc77c\uc744 \ud55c \uc0ac\ub78c\ub4e4\uc740 \uc0ac\ub77c\uc9c0\uae30 \uc27d\ub2e4. \uac74\ucd95\uc744 \uae30\ub2a5\uc73c\ub85c \uc77d\uc73c\uba74 \ub2e4\ub978 \uc9c8\ubb38\uc774 \ub098\uc628\ub2e4. \ub204\uac00 \uc7ac\ub8cc\ub97c \ubc1b\uace0 \ub204\uac00 \uc74c\uc2dd\uc744 \ub9cc\ub4e4\uba70 \uc5b4\ub5a4 \uae38\ub85c \uc62e\uacbc\uc744\uae4c. \uad81\uc804\uc758 \uaddc\ubaa8\ub294 \ub113\uc740 \uc9c0\ubd95\uc758 \ud06c\uae30\ub9cc\uc774 \uc544\ub2c8\ub77c \uc774\ub7f0 \uc5c5\ubb34\uc758 \ubc94\uc704\uc774\uae30\ub3c4 \ud588\ub2e4. \ud589\ubcf5\uc758 \ubb38\uc73c\ub85c \uc54c\ub824\uc9c4 \uacbd\uacc4\ub97c \uc9c0\ub098\uba74 \uc811\uacac\uacfc \uc0dd\ud65c, \uc18c\uc7a5\ud488\uacfc \uc815\uc6d0\uc758 \uacf5\uac04\uc774 \ub354 \uc774\uc5b4\uc9c4\ub2e4. \uc548\ucabd\uc774\ub77c\uace0 \ubaa8\ub450 \ud558\ub098\uc758 \uc131\uaca9\uc744 \uac00\uc9c4 \ubc29\uc740 \uc544\ub2c8\ub2e4. \ud5c8\ud134\uc740 \uc655\uc88c\uc758 \ubc29\uacfc \uc11c\uace0, \ubcf4\ubb3c\uc758 \uacf5\uac04\uc744 \ucc28\ub840\ub85c \uc124\uba85\ud55c\ub2e4. \uc624\ub298\uc758 \ubc15\ubb3c\uad00\uc2dd \ubd84\ub958\uc640 \ub2f9\uc2dc\uc758 \uc0ac\uc6a9\uc740 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ud2b9\ud788 \uac00\uc871\uc758 \uc0dd\ud65c \uacf5\uac04\uc744 \uc774\uad6d\uc801\uc778 \ud638\uae30\uc2ec\uc758 \ub300\uc0c1\uc73c\ub85c\ub9cc \ub2e4\ub8e8\uba74 \uad81\uc804\uc758 \uad6c\uc870\uac00 \ub2e8\uc21c\ud574\uc9c4\ub2e4. \uc811\uadfc\uc774 \uc81c\ud55c\ub41c \uac70\ucc98\uc640 \uacf5\uc801\uc778 \uc5c5\ubb34\uac00 \uc5b4\ub5bb\uac8c \ubd84\ub9ac\ub418\uace0 \uc774\uc5b4\uc84c\ub294\uc9c0 \uc0b4\ud544 \uc218 \uc788\ub2e4. \uc0ac\uc801\uc778 \uc0dd\ud65c\uacfc \uc815\uce58\uac00 \uc644\uc804\ud788 \ub5a8\uc5b4\uc9c0\uc9c0 \uc54a\ub294 \uc7a5\uc18c\uc600\ub2e4. \ubcf4\ubb3c \uacf5\uac04\uc758 \ubb3c\uac74\ub4e4\uc740 \ud55c \uc81c\uad6d \uc548\uc5d0\uc11c\ub3c4 \uc5ec\ub7ec \uc7a5\uc18c\uc640 \uc2dc\uae30\uc758 \uad00\uacc4\ub97c \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ud5c8\ud134\uc740 \ud398\ub974\uc2dc\uc544\uc758 \uc625\uc88c\ub77c\uace0 \uc124\uba85\ud55c \ubb3c\uac74\uacfc \uc220\ud0c4\uc758 \uac00\uad6c\ub97c \ud568\uaed8 \uc18c\uac1c\ud55c\ub2e4. \ub2e4\ub9cc \uc61b \uc548\ub0b4\uc11c\uc758 \uba85\uce6d\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc81c\uc791\uc9c0\uc640 \uc774\ub3d9 \uacbd\ub85c\ub97c \ud655\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc18c\uc7a5 \uc7a5\uc18c\uc640 \ub9cc\ub4e4\uc5b4\uc9c4 \uc7a5\uc18c\ub97c \uac19\uc740 \uac83\uc73c\ub85c \ubcf4\uc9c0 \uc54a\ub294 \ud0dc\ub3c4\uac00 \ud544\uc694\ud558\ub2e4. \uc811\uacac\uc2e4\uacfc \uc11c\uace0, \ubcf4\ubb3c\uc758 \ubc29\uc744 \uc9c0\ub098\uac00\ub294 \uad00\ub78c\uac1d\uc758 \uc21c\uc11c\ub3c4 \uc2e4\uc81c \uad81\uc804\uc5d0\uc11c \uc77c\ud558\ub358 \uc0ac\ub78c\uc758 \uc77c\uacfc \uac19\uc9c0 \uc54a\ub2e4. \uc9c0\uae08 \ub208\uc5d0 \ub744\ub294 \ubb3c\uac74\uc744 \ub530\ub77c \uac77\ub294 \uae38\uacfc \uc5c5\ubb34\ub97c \uc218\ud589\ud558\ub824 \uc774\ub3d9\ud558\ub358 \uae38\uc740 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uad00\ub78c\uc758 \ud3b8\ub9ac\ud568\uc774 \uacfc\uac70\uc758 \uacf5\uac04 \uc0ac\uc6a9\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\uc73c\uba74, \uc804\uc2dc\uac00 \ub4dc\ub7ec\ub0b4\ub294 \uac83\uacfc \uac10\ucd94\ub294 \uac83\uc744 \ud568\uaed8 \ubcfc \uc218 \uc788\ub2e4. \uad81\uc804\uc744 \ud604\uc7ac\uc758 \uc804\uc2dc\uc2e4\uacfc \uacfc\uac70\uc758 \uc870\uc9c1\uc774\ub77c\ub294 \ub450 \ud06c\uae30\ub85c \uc77d\uc5b4 \ubcf4\ub294 \ubc29\ubc95\uc774\ub2e4. \uc0ac\uc6a9\ud55c \uc5ed\uc0ac \ub3c4\ud310\uc740 \uad81\uc804\uc758 \ud55c \ubd80\ubd84\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uadf8 \ud55c \uc7a5\uc774 \uc804\uccb4 \ub3d9\uc120\uacfc \ubaa8\ub4e0 \uc2dc\ub300\ub97c \ub300\ud45c\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc0ac\uc9c4\uc774\ub098 \uadf8\ub9bc\uc758 \uc815\uba74\uc744 \uac10\uc0c1\ud55c \ub4a4, \uadf8\uacf3\uc5d0 \uc774\ub974\uae30\uae4c\uc9c0 \uc5b4\ub5a4 \ubb38\uc744 \uc9c0\ub098\uc57c \ud588\ub294\uc9c0 \uc0dd\uac01\ud558\uba74 \uc7a5\uc18c\uac00 \ub354 \uc785\uccb4\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4. \ud1b1\uce74\ud504\ub294 \ud55c \uc655\uc774 \uc0b4\ub358 \ud070\uc9d1\ubcf4\ub2e4 \ub9ce\uc740 \uc5ed\ud560\uc774 \uc5f0\uacb0\ub41c \uc870\uc9c1\uc758 \uacf5\uac04\uc774\uc5c8\ub2e4. \ub4e4\uc5b4\uac08 \uc218 \uc788\ub294 \ubc94\uc704\uc640 \uae30\ub2e4\ub9ac\ub294 \uc790\ub9ac, \uba39\uace0 \uc77c\ud558\ub294 \uc2dc\uc124\uc774 \ud568\uaed8 \uc81c\uad6d\uc758 \uc77c\uc0c1\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \ubcf4\ub294 \uc21c\uc11c\uc640 \uc77c\ud558\ub294 \uc21c\uc11c\uc758 \ucc28\uc774\ub3c4 \uad81\uc804\uc744 \uc774\ud574\ud558\ub294 \uc911\uc694\ud55c \ub2e8\uc11c\uac00 \ub41c\ub2e4. \ubb38\uc744 \uc9c0\ub098\ub294 \uc791\uc740 \ud589\ub3d9\uc744 \ub530\ub77c\uac00\uba74 \uad81\uc804\uc758 \uc544\ub984\ub2e4\uc6c0 \uc18d\uc5d0\uc11c \uad8c\ub825\uacfc \ub178\ub3d9\uc758 \uad00\uacc4\uac00 \ub4dc\ub7ec\ub09c\ub2e4."}, {"id": "treasure-island-trust-and-map", "title": "\ubcf4\ubb3c\uc12c \u2014 \uc9c0\ub3c4\ubcf4\ub2e4 \uc5b4\ub824\uc6b4 \uac83\uc740 \uc0ac\ub78c\uc744 \uc77d\ub294 \uc77c", "summary": "\ubcf4\ubb3c\uc744 \ucc3e\ub294 \ubaa8\ud5d8\uc758 \uc904\uac70\ub9ac\uc640 \uc778\ubb3c\uc758 \uc120\ud0dd\uc744 \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubb38\ud559", "categories": ["arts"], "url": "stories/treasure-island-trust-and-map/index.html", "image": "../media/treasure-island-trust-and-map.png", "alt": "\uc9d0 \ud638\ud0a8\uc2a4\uac00 \ubc30 \uc704\uc5d0\uc11c \uc9c0\ub3c4\ub97c \ub4e4\uace0 \uc678\ub2e4\ub9ac\uc758 \ub871 \uc874 \uc2e4\ubc84\uc640 \uc12c\uc744 \ubc14\ub77c\ubcf4\ub294 \uc0c1\uc0c1 \uc0bd\ud654.", "text": "\ubcf4\ubb3c\uc12c \u2014 \uc9c0\ub3c4\ubcf4\ub2e4 \uc5b4\ub824\uc6b4 \uac83\uc740 \uc0ac\ub78c\uc744 \uc77d\ub294 \uc77c \uc9d0 \ud638\ud0a8\uc2a4\uc640 \ub871 \uc874 \uc2e4\ubc84, \ubbff\uc74c\uc774 \ud754\ub4e4\ub9ac\ub294 \ubc14\ub2e4 \ubcf4\ubb3c\uc744 \ucc3e\ub294 \ubaa8\ud5d8\uc758 \uc904\uac70\ub9ac\uc640 \uc778\ubb3c\uc758 \uc120\ud0dd\uc744 \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4. \ubb38\ud559 \ubb38\ud654\uc640 \uc608\uc220 \uc624\ub798\ub41c \uc9c0\ub3c4\uc5d0\ub294 \ubcf4\ubb3c\uc774 \ubb3b\ud78c \uc790\ub9ac\uac00 \ud45c\uc2dc\ub418\uc5b4 \uc788\ub2e4. \ubaa9\uc801\uc9c0\ub9cc \uc54c\uba74 \uae38\uc744 \ucc3e\uc744 \uc218 \uc788\uc744 \uac83 \uac19\uc9c0\ub9cc, \ud568\uaed8 \ubc30\ub97c \ud0c4 \uc0ac\ub78c\ub4e4 \uc911 \ub204\uad6c\ub97c \ubbff\uc5b4\uc57c \ud558\ub294\uc9c0\ub294 \uc9c0\ub3c4\uc5d0 \ub098\uc624\uc9c0 \uc54a\ub294\ub2e4. \u300e\ubcf4\ubb3c\uc12c\u300f\uc758 \ubaa8\ud5d8\uc740 \uadf8 \ub450 \uc885\ub958\uc758 \uc5b4\ub824\uc6c0\uc744 \ud568\uaed8 \uc6c0\uc9c1\uc778\ub2e4. \uc18c\ub144 \uc9d0 \ud638\ud0a8\uc2a4\ub294 \uc5b4\ub978\ub4e4\uc758 \ube44\ubc00\uacfc \ud0d0\uc695, \uc6a9\uae30\uc640 \uacc4\uc0b0\uc774 \uc5bd\ud78c \ubc14\ub2e4\ub85c \ub4e4\uc5b4\uac04\ub2e4. \uac00\uc7a5 \uc778\uc0c1\uc801\uc778 \uc5b4\ub978\uc740 \uce5c\uadfc\ud55c \ub9d0\ud22c\uc640 \uc704\ud5d8\ud55c \uc18d\ub0b4\ub97c \ud568\uaed8 \uac00\uc9c4 \ub871 \uc874 \uc2e4\ubc84\ub2e4. \uc544\ub798\uc5d0\ub294 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4. \uc9d0\uc758 \uc9d1\uc774 \uc6b4\uc601\ud558\ub294 \uc5ec\uad00\uc5d0 \ube4c\ub9ac \ubcf8\uc988\ub77c\ub294 \ub299\uc740 \uc120\uc6d0\uc774 \uba38\ubb38\ub2e4. \uadf8\ub97c \ucc3e\uc544\uc624\ub294 \uc218\uc0c1\ud55c \uc778\ubb3c\ub4e4\uacfc \uac80\uc740 \ud45c\uc2dd\uc740 \ud3c9\ubc94\ud55c \uc0dd\ud65c\uc744 \uc704\ud611\ud55c\ub2e4. \ubcf8\uc988\uac00 \uc8fd\uc740 \ub4a4 \uc9d0\uc740 \ubb3c\uac74\ub4e4 \uc0ac\uc774\uc5d0\uc11c \ubcf4\ubb3c \uc9c0\ub3c4\ub97c \ubc1c\uacac\ud55c\ub2e4. \uc77c\uc0c1\uc5d0\uc11c \uaebc\ub0b8 \uc885\uc774 \ud55c \uc7a5\uc774 \uba3c \uc12c\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \ubb38\uc774 \ub41c\ub2e4. \uc9d0\uc740 \ucc98\uc74c\ubd80\ud130 \ub2a5\uc219\ud55c \ubaa8\ud5d8\uac00\ub294 \uc544\ub2c8\ub2e4. \ubb34\uc2a8 \uc77c\uc774 \ubc8c\uc5b4\uc9c0\ub294\uc9c0 \uc644\uc804\ud788 \uc54c\uc9c0 \ubabb\ud558\ub294 \uc0c1\ud0dc\uc5d0\uc11c \uc6c0\uc9c1\uc778\ub2e4. \ub3c5\uc790\ub294 \uc18c\ub144\uc774 \ub4e3\uace0 \ubcf4\uace0 \uc624\ud574\ud558\ub294 \uacfc\uc815\uc744 \ub530\ub77c\uac00\ubbc0\ub85c, \uc774\ubbf8 \ubaa8\ub4e0 \uac83\uc744 \uc544\ub294 \uc601\uc6c5\uc758 \uc2b9\ub9ac\ubcf4\ub2e4 \uc0c8\ub85c\uc6b4 \uc138\uacc4\ub97c \ubc30\uc6cc \uac00\ub294 \uae34\uc7a5\uc744 \uacbd\ud5d8\ud558\uac8c \ub41c\ub2e4. \ub9ac\ube0c\uc9c0 \uc758\uc0ac\uc640 \ud2b8\ub9b4\ub85c\ub2c8 \uc9c0\uc8fc\uac00 \uc6d0\uc815\uc5d0 \ub098\uc11c\uace0 \ud788\uc2a4\ud30c\ub2c8\uc62c\ub77c\ud638\uac00 \uc900\ube44\ub41c\ub2e4. \ud544\uc694\ud55c \uac83\uc740 \ubc30\uc640 \uc2dd\ub7c9\ubfd0 \uc544\ub2c8\ub77c \ud568\uaed8 \uc77c\ud560 \uc0ac\ub78c\ub4e4\uc774\ub2e4. \uc774 \uacfc\uc815\uc5d0\uc11c \uc694\ub9ac\uc0ac \ub871 \uc874 \uc2e4\ubc84\uac00 \uc911\uc694\ud55c \uc790\ub9ac\ub97c \ucc28\uc9c0\ud55c\ub2e4. \uc0ac\ub78c\uc744 \ucd94\ucc9c\ud558\uace0 \ubd84\uc704\uae30\ub97c \ub9cc\ub4e4\uba70 \uc2e0\ub8b0\ub97c \uc5bb\ub294\ub2e4. \ub3c8\uacfc \uc9c0\uc704\uac00 \uc788\ub2e4\uace0 \ud574\uc11c \uc0ac\ub78c\uc744 \ubcf4\ub294 \ud310\ub2e8\uae4c\uc9c0 \uc800\uc808\ub85c \uc88b\uc544\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc900\ube44\ub294 \uac89\uc73c\ub85c \uc21c\uc870\ub85c\uc6cc\ub3c4 \uadf8 \uc548\uc5d0 \ub2e4\ub978 \ubaa9\uc801\uc744 \uac00\uc9c4 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc778\ub2e4. \ubcf4\ubb3c \uc9c0\ub3c4\ub97c \uc190\uc5d0 \ub123\ub294 \uac83\uacfc \ubaa8\ud5d8\uc744 \uc81c\ub300\ub85c \uc774\ud574\ud558\ub294 \uac83\uc740 \uc11c\ub85c \ub2e4\ub978 \uc77c\uc774\ub77c\ub294 \uc0ac\uc2e4\uc774 \uc11c\uc11c\ud788 \ub4dc\ub7ec\ub09c\ub2e4. \uc2e4\ubc84\ub294 \ud55c\ucabd \ub2e4\ub9ac\uac00 \uc5c6\uace0 \ubaa9\ubc1c\uc744 \uc0ac\uc6a9\ud55c\ub2e4. \ub110\ub9ac \ub5a0\uc62c\ub9ac\ub294 \ud574\uc801\uc758 \uc0c1\uc9d5\uc744 \ubaa8\ub450 \ud55c\uaebc\ubc88\uc5d0 \ubd99\uc774\uae30\ubcf4\ub2e4 \uc6d0\uc791\uc758 \uc774 \uad6c\uccb4\uc801\uc778 \ubaa8\uc2b5\uc744 \uc54c\uc544 \ub450\uba74 \uc88b\ub2e4. \uadf8\uc758 \ud798\uc740 \uac70\uce5c \uc678\ubaa8\ub9cc\uc774 \uc544\ub2c8\ub77c \uc0ac\ub78c\uc744 \ub300\ud558\uace0 \uc0c1\ud669\uc744 \uc77d\ub294 \ub2a5\ub825\uc5d0\ub3c4 \uc788\ub2e4. \uc9d0\uc5d0\uac8c \ub9d0\uc744 \uac78\uace0 \uce5c\uadfc\ud558\uac8c \ud589\ub3d9\ud558\ub294 \ubaa8\uc2b5\uacfc, \ub2e4\ub978 \ubaa9\uc801\uc744 \uc704\ud574 \uacc4\uc0b0\ud558\ub294 \ubaa8\uc2b5\uc774 \uac19\uc740 \uc778\ubb3c \uc548\uc5d0 \uc788\ub2e4. \uadf8\ub798\uc11c \uc2e4\ubc84\ub97c \ucc98\uc74c\ubd80\ud130 \ub05d\uae4c\uc9c0 \ub2e8\uc21c\ud55c \uc545\ub2f9\uc758 \uc5bc\uad74\ub85c\ub9cc \uc77d\uae30 \uc5b4\ub835\ub2e4. \ub204\uad70\uac00\uac00 \ub098\uc5d0\uac8c \uce5c\uc808\ud588\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uadf8\uc758 \ubaa8\ub4e0 \ud589\ub3d9\uc744 \uc124\uba85\ud558\uac70\ub098 \ubcf4\uc99d\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4\ub294 \ubb38\uc81c\ub3c4 \uc0dd\uae34\ub2e4. \uc9d0\uc740 \uc0ac\uacfc \ud1b5\uc5d0 \ub4e4\uc5b4\uac00 \uc788\ub2e4\uac00 \uc2e4\ubc84\uc640 \ub2e4\ub978 \uc120\uc6d0\ub4e4\uc758 \ub300\ud654\ub97c \ub4e3\ub294\ub2e4. \ubbff\uc5c8\ub358 \ub3d9\ud589 \uc18d\uc5d0 \ubc18\ub780\uacfc \ubcf4\ubb3c \ud0c8\ucde8\uc758 \uacc4\ud68d\uc774 \uc788\uc5c8\uc74c\uc744 \uc54c\uac8c \ub418\ub294 \uc7a5\uba74\uc774\ub2e4. \uac89\uc73c\ub85c \ubcf4\uc774\ub358 \uc5ec\ud589\uacfc \uc2e4\uc81c\ub85c \uc9c4\ud589\ub418\ub358 \uacc4\ud68d\uc774 \ub2ec\ub790\ub2e4. \uc0c8\ub85c\uc6b4 \uc0ac\uc2e4\uc744 \uc54c\uc558\ub2e4\uace0 \uace7\ubc14\ub85c \uc548\uc804\ud574\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub204\uad6c\uc5d0\uac8c \uc54c\ub9ac\uace0 \uc5b4\ub5bb\uac8c \ud589\ub3d9\ud574\uc57c \ud560\uc9c0 \ud310\ub2e8\ud574\uc57c \ud55c\ub2e4. \uc9d0\uc774 \uac00\uc9c4 \uc815\ubcf4\ub294 \ud798\uc774 \ub418\uc9c0\ub9cc \uc704\ud5d8\ub3c4 \ud568\uaed8 \uac00\uc838\uc628\ub2e4. \ubaa8\ud5d8\uc758 \uc7ac\ubbf8\ub294 \ube44\ubc00\uc744 \ub4e3\ub294 \ub370\uc11c \ub05d\ub098\uc9c0 \uc54a\uace0 \uadf8 \uc9c0\uc2dd\uc744 \uac00\uc9c0\uace0 \ub2e4\uc74c \ud589\ub3d9\uc744 \uace0\ub974\ub294 \ub370 \uc774\uc5b4\uc9c4\ub2e4. \uc12c\uc5d0 \ub3c4\ucc29\ud55c \ub4a4 \uc77c\ud589\uc740 \uac08\ub77c\uc9c0\uace0 \ucda9\ub3cc\ud55c\ub2e4. \uc9d0\uc740 \ubca4 \uac74\uc744 \ub9cc\ub098\uace0, \ubc30\ub97c \ub458\ub7ec\uc2fc \uc704\ud5d8 \uc18d\uc5d0\ub3c4 \ub6f0\uc5b4\ub4e0\ub2e4. \ud63c\uc790 \ud589\ub3d9\ud558\ub294 \uc120\ud0dd\uc774 \uc911\uc694\ud55c \ubcc0\ud654\ub97c \ub9cc\ub4e4\uc9c0\ub9cc \uc5b8\uc81c\ub098 \ubbf8\ub9ac \uc0dd\uac01\ud55c \ub300\ub85c \uc798\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud2b9\ud788 \ubc30 \uc704\uc5d0\uc11c \uc774\uc2a4\ub77c\uc5d8 \ud578\uc988\uc640 \ub9c8\uc8fc\ud558\ub294 \ub300\ubaa9\uc740 \ubaa8\ud5d8\uc758 \uc704\ud5d8\uc744 \uad6c\uccb4\uc801\uc73c\ub85c \ubcf4\uc5ec \uc900\ub2e4. \uc774\ub97c \uba4b\uc9c4 \uc6a9\uae30\uc758 \uc21c\uac04\uc73c\ub85c\ub9cc \uc77d\uc73c\uba74 \uc18c\ub144\uc774 \uac10\ub2f9\ud574\uc57c \ud558\ub294 \uacf5\ud3ec\uac00 \uc9c0\uc6cc\uc9c0\uae30 \uc27d\ub2e4. \uc18c\uc124\uc758 \uae34\uc7a5\uc740 \ub300\ub2f4\ud568\uacfc \ubd88\uc548, \uc6b0\uc5f0\uacfc \ud310\ub2e8\uc774 \ud568\uaed8 \uc788\ub2e4\ub294 \ub370 \uc788\ub2e4. \ud574\uc801\ub4e4\uc774 \uae30\ub300\ud55c \uacf3\uc5d0\ub294 \ubcf4\ubb3c\uc774 \uadf8\ub300\ub85c \ub0a8\uc544 \uc788\uc9c0 \uc54a\ub2e4. \ubca4 \uac74\uc774 \uc774\ubbf8 \uadf8\uac83\uc744 \uc62e\uaca8 \ub193\uc558\uae30 \ub54c\ubb38\uc774\ub2e4. \uc9c0\ub3c4\ub294 \uacfc\uac70\uc758 \uc815\ubcf4\ub97c \ub2f4\uace0 \uc788\uc5c8\uc9c0\ub9cc \uc774\ud6c4\uc5d0 \uc77c\uc5b4\ub09c \uc77c\uae4c\uc9c0 \uc790\ub3d9\uc73c\ub85c \uc54c\ub824 \uc8fc\uc9c0\ub294 \uc54a\uc558\ub2e4. \uc885\uc774\uc5d0 \ud655\uc2e0\uc744 \uac78\uc5c8\ub358 \uc0ac\ub78c\ub4e4\uc758 \uacc4\ud68d\uc774 \ud754\ub4e4\ub9b0\ub2e4. \uc774 \uc7a5\uba74\uc5d0\uc11c\ub294 \ubb3c\uac74\uc758 \uac00\uce58\ubfd0 \uc544\ub2c8\ub77c \uc815\ubcf4\uac00 \uc5b8\uc81c\uc758 \uac83\uc778\uc9c0\ub3c4 \uc911\uc694\ud574\uc9c4\ub2e4. \uc815\ub2f5\ucc98\ub7fc \ubcf4\uc774\ub358 \ud45c\uc2dc\ub294 \uc0c1\ud669\uc774 \ub2ec\ub77c\uc9c0\uba74 \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4. \ubcf4\ubb3c\uc774 \uc788\ub294 \uc7a5\uc18c\ub97c \uc548\ub2e4\ub294 \ubbff\uc74c\uacfc \uc2e4\uc81c\ub85c \uadf8\uacf3\uc5d0 \ub3c4\ucc29\ud574 \ub9cc\ub098\ub294 \ud604\uc2e4 \uc0ac\uc774\uc758 \ucc28\uc774\uac00 \uacb0\ub9d0\uc744 \uc6c0\uc9c1\uc778\ub2e4. \uc2e4\ubc84\ub294 \uc704\ud5d8\ud574\uc9c4 \uc0c1\ud669\uc5d0\uc11c\ub3c4 \uc0b4\uc544\ub0a8\uc744 \uae38\uc744 \ucc3e\ub294\ub2e4. \uc9d0\uc744 \uc9c0\ucf1c \uc8fc\ub294 \ud589\ub3d9\uc744 \ud558\uba74\uc11c\ub3c4 \uc790\uc2e0\uc758 \uc774\uc775\uc744 \ub193\uc9c0 \uc54a\ub294\ub2e4. \ub3c4\uc6c0\uc744 \uc8fc\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ubbff\uc744 \uc218 \uc788\ub294 \uc0ac\ub78c\uc73c\ub85c \uc644\uc804\ud788 \ubc14\ub00c\uc5c8\ub2e4\ub294 \ud310\ub2e8\uc744 \uace7\ubc14\ub85c \uac19\uac8c \ub9cc\ub4e4\uae30\ub294 \uc5b4\ub835\ub2e4. \ub9c8\uce68\ub0b4 \ubcf4\ubb3c\uc744 \uac00\uc9c0\uace0 \ub5a0\ub098\ub294 \uc5ec\uc815\uc5d0\uc11c\ub3c4 \uadf8\ub294 \ub05d\uae4c\uc9c0 \uae54\ub054\ud558\uac8c \uc815\ub9ac\ub418\uc9c0 \uc54a\ub294\ub2e4. \ub3c8\uc758 \uc77c\ubd80\ub97c \uac00\uc9c0\uace0 \uc0ac\ub77c\uc9c0\ub294 \uc2e4\ubc84\ub294 \ub3c5\uc790\uc5d0\uac8c\ub3c4 \ubaa8\ud638\ud55c \uae30\uc5b5\uc744 \ub0a8\uae34\ub2e4. \uc9c8\uc11c\uac00 \ud68c\ubcf5\ub418\uba74 \uc545\uc778\uc740 \uc815\ud574\uc9c4 \ubc8c\uc744 \ubc1b\uace0 \ubaa8\ub4e0 \ubb38\uc81c\uac00 \ub05d\ub09c\ub2e4\ub294 \ub2e8\uc21c\ud55c \ub9c8\ubb34\ub9ac\uc640 \uac70\ub9ac\uac00 \uc788\ub2e4. \uc9d0\uc740 \ubaa8\ud5d8\uc5d0\uc11c \ub3cc\uc544\uc624\uc9c0\ub9cc \uc12c\uacfc \ubc14\ub2e4\uc758 \uc18c\ub9ac\ub97c \uc644\uc804\ud788 \uc78a\uc9c0 \ubabb\ud55c\ub2e4. \ubcf4\ubb3c\uc744 \uc5bb\uc5c8\ub2e4\ub294 \uc131\uacf5\ub9cc\uc73c\ub85c \uacbd\ud5d8\uc774 \ubaa8\ub450 \ud658\ud55c \ucd94\uc5b5\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb34\uc11c\uc6e0\ub358 \uc7a5\uba74\uacfc \ubbff\uc74c\uc774 \ud754\ub4e4\ub9b0 \uc21c\uac04\ub3c4 \ud568\uaed8 \ub0a8\ub294\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc9d0\uacfc \ubaa9\ubc1c\uc744 \uc9da\uc740 \uc678\ub2e4\ub9ac\uc758 \uc2e4\ubc84\uac00 \uc12c\uc744 \ubc14\ub77c\ubcf4\ub294 \uc7a5\uba74\uc744 \uc0c1\uc0c1\ud588\ub2e4. \uc6d0\uc791 \uc9c0\ub3c4\ub098 \uc2e4\uc81c \ubc30\uc758 \ubcf5\uc6d0\ub3c4\ub294 \uc544\ub2c8\ub2e4. \ub450 \uc0ac\ub78c\uc774 \uac19\uc740 \uacf3\uc744 \ubc14\ub77c\ubcf4\uba74\uc11c\ub3c4 \uac19\uc740 \ubaa9\uc801\uc744 \uac00\uc84c\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218 \uc5c6\ub2e4\ub294 \uad00\uacc4\ub97c \ub2f4\uc558\ub2e4. \uc9c0\ub3c4\uc5d0 \uc5c6\ub294 \uc0ac\ub78c\uc758 \uc18d\ub0b4\ub97c \uc77d\ub294 \uc77c\uc774 \uc65c \ub354 \uc5b4\ub824\uc6e0\ub294\uc9c0 \uc0dd\uac01\ud558\uba70 \uc18c\uc124\ub85c \ub3cc\uc544\uac00 \ubcf4\uc790."}, {"id": "urashima-taro-box-and-lost-time", "title": "\uc6b0\ub77c\uc2dc\ub9c8 \ud0c0\ub85c \u2014 \uace0\ud5a5\uc73c\ub85c \ub3cc\uc544\uc654\ub294\ub370 \uc2dc\uac04\uc774 \ub2ec\ub790\ub2e4", "summary": "\uac70\ubd81\uc744 \uad6c\ud55c \uc5b4\ubd80\uc758 \uadc0\ud5a5\uacfc \uae08\uc9c0\ub41c \uc0c1\uc790\ub97c \ub530\ub77c \ub3cc\uc544\uac08 \uc218 \uc5c6\ub294 \uc2dc\uac04\uc758 \uc774\uc57c\uae30\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc2e0\ud654\uc640 \ubbfc\uc18d", "categories": ["arts"], "url": "stories/urashima-taro-box-and-lost-time/index.html", "image": "../media/urashima-taro-box-and-lost-time.png", "alt": "\ub0af\uc124\uc5b4\uc9c4 \ud574\ubcc0\uc5d0\uc11c \ub2eb\ud78c \uce60\uae30 \uc0c1\uc790\ub97c \ub4e4\uace0 \uc11c \uc788\ub294 \uc6b0\ub77c\uc2dc\ub9c8\uc640 \uc595\uc740 \ubc14\ub2e4\uc758 \uac70\ubd81 \uc0bd\ud654", "text": "\uc6b0\ub77c\uc2dc\ub9c8 \ud0c0\ub85c \u2014 \uace0\ud5a5\uc73c\ub85c \ub3cc\uc544\uc654\ub294\ub370 \uc2dc\uac04\uc774 \ub2ec\ub790\ub2e4 \ubc14\ub2f7\uc18d \uad81\uc804\uc758 \uba70\uce60\uacfc \ud574\ubcc0\uc758 \uc218\ubc31 \ub144 \uc0ac\uc774 \uac70\ubd81\uc744 \uad6c\ud55c \uc5b4\ubd80\uc758 \uadc0\ud5a5\uacfc \uae08\uc9c0\ub41c \uc0c1\uc790\ub97c \ub530\ub77c \ub3cc\uc544\uac08 \uc218 \uc5c6\ub294 \uc2dc\uac04\uc758 \uc774\uc57c\uae30\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uc2e0\ud654\uc640 \ubbfc\uc18d \ubb38\ud654\uc640 \uc608\uc220 \uba40\ub9ac \uc5ec\ud589\ud55c \ub4a4 \uc9d1\uc73c\ub85c \ub3cc\uc544\uc654\ub294\ub370 \uac00\uc871\ub3c4 \uc774\uc6c3\ub3c4 \ub098\ub97c \ubaa8\ub978\ub2e4. \ub0b4\uac00 \uae30\uc5b5\ud558\ub294 \uc9d1\uc870\ucc28 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc798\ubabb \ucc3e\uc544\uc628 \uac83 \uac19\uc9c0\ub9cc \ub9c8\uc744 \uc774\ub984\uc740 \ub9de\ub2e4. \uc77c\ubcf8\uc758 \uc61b\uc774\uc57c\uae30 \uc6b0\ub77c\uc2dc\ub9c8 \ud0c0\ub85c\uc5d0\uc11c \uac00\uc7a5 \ub0af\uc120 \uc7a5\uba74\uc740 \ubc14\ub2f7\uc18d \uad81\uc804\ubcf4\ub2e4 \uc774 \uadc0\ud5a5\uc77c\uc9c0\ub3c4 \ubaa8\ub978\ub2e4. \uc6b0\ub77c\uc2dc\ub9c8\ub294 \uc7a0\uc2dc \ub2e4\ub140\uc654\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4. \uadf8\ub7f0\ub370 \uc721\uc9c0\uc5d0\uc11c\ub294 \uc804\ud600 \ub2e4\ub978 \uc2dc\uac04\uc774 \ud758\ub800\ub2e4. \uac70\ubd81\uc744 \uad6c\ud55c \uce5c\uc808\uacfc \uc2e0\ube44\ud55c \ubc29\ubb38\uc73c\ub85c \uc2dc\uc791\ud55c \uc774\uc57c\uae30\uac00, \uc5b4\ub290 \uc21c\uac04 \ub3cc\uc774\ud0ac \uc218 \uc5c6\ub294 \uc0c1\uc2e4\uc758 \uc774\uc57c\uae30\ub85c \ubc14\ub010\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc624\uc790\ud0a4 \uc608\uc774 \ub370\uc624\ub3c4\ub77c\uc758 \uc7ac\uc11c\uc220\uc744 \ub530\ub77c \uacb0\ub9d0\uae4c\uc9c0 \uc77d\ub294\ub2e4. \uc6b0\ub77c\uc2dc\ub9c8\ub294 \ubc14\ub2f7\uac00\uc5d0 \uc0ac\ub294 \uc80a\uc740 \uc5b4\ubd80\ub2e4. \ucc38\uace0 \ud310\ubcf8\uc5d0\uc11c \uadf8\ub294 \uc544\uc774\ub4e4\uc774 \uad34\ub86d\ud788\ub358 \uac70\ubd81\uc744 \ub3c8\uc744 \uc8fc\uace0 \ub118\uaca8\ubc1b\uc544 \ubc14\ub2e4\ub85c \ub193\uc544\uc900\ub2e4. \ub2f9\uc7a5 \uc790\uae30\uc5d0\uac8c \uc4f8\ubaa8\uac00 \uc788\ub294\uc9c0\ubcf4\ub2e4 \ub2e4\ub978 \uc0dd\uba85\uc758 \uc55e\ub0a0\uc744 \uc0dd\uac01\ud55c \ud589\ub3d9\uc774\ub2e4. \uc774 \uc791\uc740 \uc120\ud0dd\uc774 \uc774\uc57c\uae30\uc758 \ubb38\uc744 \uc5f0\ub2e4. \uc120\ud589\uc5d0 \ubcf4\uc0c1\uc774 \ub3cc\uc544\uc624\ub294 \uc61b\uc774\uc57c\uae30\ub294 \uc5ec\ub7ec \ubb38\ud654\uc5d0 \uc788\ub2e4. \ub2e4\ub9cc \uc774 \uc774\uc57c\uae30\uc5d0\uc11c\ub294 \ubcf4\uc0c1\uc744 \ubc1b\uc558\ub2e4\ub294 \uc21c\uac04\uc774 \uacb0\ub9d0\uc774 \uc544\ub2c8\ub2e4. \uac70\ubd81\uacfc \uc774\uc5b4\uc9c4 \ub9cc\ub0a8\uc740 \uc6b0\ub77c\uc2dc\ub9c8\ub97c \uc775\uc219\ud55c \ubc14\ub2e4\uc758 \ud45c\uba74 \uc544\ub798, \ub2e4\ub978 \uaddc\uce59\uc73c\ub85c \uc6c0\uc9c1\uc774\ub294 \uc138\uacc4\ub85c \ub370\ub824\uac04\ub2e4. \uc88b\uc740 \uc77c\uc774 \uace7 \uc548\uc804\ud55c \uc77c\uc778 \uac83\uc740 \uc544\ub2c8\uac8c \ub41c\ub2e4. \uc6b0\ub77c\uc2dc\ub9c8\uac00 \ub3c4\ucc29\ud55c \uacf3\uc740 \uc544\ub984\ub2e4\uc6b4 \uad81\uc804\uc774\ub2e4. \uacf5\uc8fc\uc640\uc758 \ub9cc\ub0a8, \ud48d\uc694\ub85c\uc6b4 \ub300\uc811\uacfc \uacbd\uc774\ub85c\uc6b4 \ud48d\uacbd\uc774 \uc77c\uc0c1\uc744 \uba40\uc5b4\uc9c0\uac8c \ud55c\ub2e4. \ucc38\uace0 \ud310\ubcf8\uc740 \ubc14\ub2f7\uc18d \uc138\uacc4\ub97c \ub2e8\uc9c0 \ub0af\uc120 \uc7a5\uc18c\uac00 \uc544\ub2c8\ub77c, \ub5a0\ub098\uc628 \uc9d1\uc744 \uc7a0\uc2dc \uc78a\uc744 \ub9cc\ud07c \ub9e4\ub825\uc801\uc778 \uacf5\uac04\uc73c\ub85c \uadf8\ub9b0\ub2e4. \ubc14\ub2f7\uc18d \uad81\uc804\uc744 \uc2e4\uc81c \uc9c0\ub9ac\ucc98\ub7fc \ucc3e\uc544 \ub098\uc124 \ud544\uc694\ub294 \uc5c6\ub2e4. \ubbfc\ub2f4\uc740 \uc775\uc219\ud55c \uc138\uacc4\uc640 \ub2e4\ub978 \uc2dc\uac04\uc744 \uc0c1\uc0c1\ud558\uae30 \uc704\ud574 \ud2b9\ubcc4\ud55c \uacf5\uac04\uc744 \ub9c8\ub828\ud560 \uc218 \uc788\ub2e4. \ubc14\ub2e4\ub294 \uc721\uc9c0\uc640 \uc774\uc5b4\uc838 \uc788\uc73c\uba74\uc11c\ub3c4 \ub208\uc73c\ub85c\ub294 \uae4a\uc774\ub97c \ub2e4 \uc54c \uc218 \uc5c6\ub294 \uacf3\uc774\ub2e4. \uc774\uc57c\uae30\uc758 \uacbd\uacc4\ub85c \uc0bc\uae30\uc5d0 \ucda9\ubd84\ud788 \uc2e0\ube44\ub86d\ub2e4. \uc6b0\ub77c\uc2dc\ub9c8\ub294 \ubb38\ub4dd \ubd80\ubaa8\ub97c \ub5a0\uc62c\ub9ac\uace0 \ub3cc\uc544\uac00\uae30\ub97c \uc6d0\ud55c\ub2e4. \uadf8\uc5d0\uac8c \ubc14\ub2f7\uc18d\uc5d0\uc11c\uc758 \uc2dc\uac04\uc740 \uae38\uc9c0 \uc54a\uc558\ub2e4. \uc88b\uc740 \ub300\uc811\uc744 \ubc1b\ub354\ub77c\ub3c4 \ub5a0\ub098\uc628 \uad00\uacc4\uac00 \uc644\uc804\ud788 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub3cc\uc544\uac00\uc57c \ud560 \uc0ac\ub78c\uc774 \uc788\ub2e4\ub294 \uae30\uc5b5\uc774 \uc5ec\ud589\uc758 \ubc29\ud5a5\uc744 \ubc14\uafbc\ub2e4. \uacf5\uc8fc\ub294 \uadf8\ub97c \ubcf4\ub0b4\uba70 \uc0c1\uc790\ub97c \uac74\ub128\ub2e4. \uadf8\ub9ac\uace0 \uc5b4\ub5a4 \uc77c\uc774 \uc788\uc5b4\ub3c4 \uc5f4\uc9c0 \ub9d0\ub77c\uace0 \ub2f9\ubd80\ud55c\ub2e4. \uc120\ubb3c\uc778\ub370 \uc5f4\uc5b4 \ubcfc \uc218 \uc5c6\ub2e4\ub294 \ubaa8\uc21c\uc774 \uc0dd\uae34\ub2e4. \uc5ec\ud589\uc5d0\uc11c \uac00\uc838\uc628 \uae30\ub150\ud488\ucc98\ub7fc \ubcf4\uc774\ub294 \uc791\uc740 \ubb3c\uac74\uc774 \uc0ac\uc2e4\uc740 \ub450 \uc138\uacc4\ub97c \uc787\ub294 \uc704\ud5d8\ud55c \uacbd\uacc4\uac00 \ub41c\ub2e4. \ud574\ubcc0\uc73c\ub85c \ub3cc\uc544\uc654\uc9c0\ub9cc \uc6b0\ub77c\uc2dc\ub9c8\uac00 \uc54c\ub358 \uc0ac\ub78c\uacfc \uc9d1\uc740 \uc5c6\ub2e4. \ub9c8\uc744 \uc0ac\ub78c\uc5d0\uac8c \ubb3b\uc790 \uc790\uae30 \uc774\ub984\uc774 \uc544\uc8fc \uc624\ub798\uc804\uc5d0 \uc0ac\ub77c\uc9c4 \uc5b4\ubd80\uc758 \uc774\uc57c\uae30\ub85c \ub3cc\uc544\uc628\ub2e4. \ucc38\uace0 \ud310\ubcf8\uc5d0\uc11c\ub294 \uc218\ubc31 \ub144\uc774\ub77c\ub294 \uac04\uaca9\uc774 \uc81c\uc2dc\ub41c\ub2e4. \uc790\uc2e0\uc5d0\uac8c\ub294 \uba70\uce60\uc774\uc5c8\ub358 \uc2dc\uac04\uc774 \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc5d0\uac8c\ub294 \uc5ec\ub7ec \uc138\ub300\uc758 \uc5ed\uc0ac\uc600\ub358 \uac83\uc774\ub2e4. \uc774 \uc7a5\uba74\uc774 \uc2ac\ud508 \uc774\uc720\ub294 \ub2e8\uc9c0 \ub098\uc774\ub97c \uacc4\uc0b0\ud558\uae30 \uc5b4\ub835\uae30 \ub54c\ubb38\uc774 \uc544\ub2c8\ub2e4. \uace0\ud5a5\uc740 \uac19\uc740 \uc704\uce58\uc758 \ub545\ub9cc\uc744 \ub73b\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub098\ub97c \uc54c\uc544\ubcf4\ub294 \uc0ac\ub78c\uacfc \ud568\uaed8 \uc0b4\uc544\uc628 \uae30\uc5b5\uc774 \uc788\uc5b4\uc57c \ub3cc\uc544\uc654\ub2e4\ub294 \uac10\uac01\uc774 \uc0dd\uae34\ub2e4. \uc6b0\ub77c\uc2dc\ub9c8\ub294 \uc7a5\uc18c\ub97c \ub418\ucc3e\uace0\ub3c4 \uad00\uacc4\uc758 \uc2dc\uac04\uc744 \ub418\ucc3e\uc9c0 \ubabb\ud55c\ub2e4. \ud63c\ub780\uacfc \uc2ac\ud514 \uc18d\uc5d0\uc11c \uc6b0\ub77c\uc2dc\ub9c8\ub294 \uacb0\uad6d \uc0c1\uc790\ub97c \uc5f0\ub2e4. \ucc38\uace0 \ud310\ubcf8\uc5d0\uc11c\ub294 \uadf8 \uc548\uc5d0\uc11c \uc548\uac1c \uac19\uc740 \uac83\uc774 \ud53c\uc5b4\ub098\uace0, \uadf8\ub294 \uac11\uc790\uae30 \ub299\uc5b4 \ud574\ubcc0\uc5d0\uc11c \uc8fd\ub294\ub2e4. \ub2e4\ub978 \uc7ac\uc11c\uc220\uacfc \uc138\ubd80\uac00 \ub2e4\ub97c \uc218 \uc788\uc73c\ubbc0\ub85c \uc774 \uacb0\ub9d0\uc744 \ubaa8\ub4e0 \uc804\uc2b9\uc758 \uc720\uc77c\ud55c \ubaa8\uc2b5\uc774\ub77c\uace0 \ud560 \uc218\ub294 \uc5c6\ub2e4. \uc774\uac83\uc744 \ud638\uae30\uc2ec\uc744 \ubd80\ub9ac\uba74 \ubc8c\uc744 \ubc1b\ub294\ub2e4\ub294 \ud55c \uc904\ub85c\ub9cc \uc77d\uc73c\uba74 \uc55e\uc11c \uc313\uc778 \uc0c1\uc2e4\uc774 \ud76c\ubbf8\ud574\uc9c4\ub2e4. \uc774\ubbf8 \uc544\ub294 \uc138\uacc4\ub97c \uc783\uc740 \uc0ac\ub78c\uc774 \ub9c8\uc9c0\ub9c9 \ub0a8\uc740 \ubb3c\uac74\uc5d0\uc11c \ub2f5\uc744 \ucc3e\uace0 \uc2f6\uc5b4 \ud588\ub2e4\uace0\ub3c4 \uc77d\uc744 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc774\ub294 \uc6b0\ub9ac\uac00 \ub354\ud574 \ubcf4\ub294 \ud574\uc11d\uc774\uba70, \uc6d0\uc804\uc758 \uad50\ud6c8\uacfc \uad6c\ubd84\ud574 \uc0dd\uac01\ud558\uba74 \uc88b\ub2e4. \uc624\uc790\ud0a4\uc758 \ud310\ubcf8\uc5d0\uc11c \uacf5\uc8fc\ub294 \uc790\uc2e0\uc774 \uc6b0\ub77c\uc2dc\ub9c8\uac00 \uad6c\ud574 \uc900 \uac70\ubd81\uc774\uc5c8\ub2e4\uace0 \ubc1d\ud78c\ub2e4. \uadf8\ub9ac\uace0 \ub450 \uc0ac\ub78c\uc740 \ubc14\ub2f7\uc18d \uc138\uacc4\uc5d0\uc11c \ubd80\ubd80\uac00 \ub41c\ub2e4. \uadf8\uc5d0\uac8c \uad81\uc804\uc740 \uc88b\uc740 \uc74c\uc2dd\uc744 \ub300\uc811\ubc1b\ub294 \ub0af\uc120 \uc219\uc18c\ub9cc\uc774 \uc544\ub2c8\ub77c \uc0c8\ub85c\uc6b4 \uad00\uacc4\ub97c \ub9fa\uc740 \uacf3\uc774\uc5c8\ub2e4. \uc774 \ub0b4\uc6a9\uc744 \uc54c\uace0 \ub098\uba74 \ubd80\ubaa8\ub97c \ucc3e\uc544 \ub3cc\uc544\uac00\ub294 \uc120\ud0dd\ub3c4 \ub2e8\uc21c\ud55c \uad00\uad11\uc758 \uc885\ub8cc\uc640\ub294 \ub2e4\ub974\uac8c \ub290\uaef4\uc9c4\ub2e4. \uadf8\ub798\uc11c \uc721\uc9c0\uc5d0\uc11c \ubaa8\ub4e0 \uad00\uacc4\ub97c \uc783\uc740 \ub4a4 \uc6b0\ub77c\uc2dc\ub9c8\ub294 \ubc14\ub2f7\uc18d\uc758 \uc544\ub0b4\uc5d0\uac8c \ub3cc\uc544\uac00\uace0 \uc2f6\uc5b4 \ud55c\ub2e4. \uc0c1\uc790\ub97c \uc5ec\ub294 \ud589\ub3d9\uc5d0\ub3c4 \uadf8\uacf3\uc73c\ub85c \ub3cc\uc544\uac08 \uc2e4\ub9c8\ub9ac\ub97c \ucc3e\uc73c\ub824\ub294 \ub9c8\uc74c\uc774 \uc11e\uc5ec \uc788\ub2e4. \ud558\uc9c0 \ub9d0\ub77c\ub294 \ub9d0\uc744 \uc78a\uc740 \uc0ac\ub78c\uc73c\ub85c\ub9cc \ubcf4\uba74 \uc124\uba85\ub418\uc9c0 \uc54a\ub294 \uc808\ubc15\ud568\uc774\ub2e4. \ub450 \uc138\uacc4 \uac00\uc6b4\ub370 \uc5b4\ub514\uc5d0\ub3c4 \uc27d\uac8c \ub3c4\ucc29\ud560 \uc218 \uc5c6\uac8c \ub418\uc5c8\ub2e4\ub294 \uc810\uc774 \uacb0\ub9d0\uc758 \uc2ac\ud514\uc744 \ub354\ud55c\ub2e4. \uc624\uc790\ud0a4\uc758 \uc7ac\uc11c\uc220\uc740 \ub05d\uc5d0\uc11c \uae08\uc9c0\uc5d0 \ub530\ub974\uc9c0 \uc54a\uc740 \uc77c\uc744 \uad50\ud6c8\uc73c\ub85c \uac15\uc870\ud55c\ub2e4. \ub2f9\uc2dc \uc5b4\ub9b0 \ub3c5\uc790\ub97c \ud5a5\ud55c \ud654\uc790\uc758 \ubaa9\uc18c\ub9ac\uac00 \ub4dc\ub7ec\ub098\ub294 \ubd80\ubd84\uc774\ub2e4. \uc624\ub298\uc758 \ub3c5\uc790\ub294 \uadf8 \uc124\uba85\uc744 \uc77d\uc73c\uba74\uc11c\ub3c4 \ubc18\ub4dc\uc2dc \uac19\uc740 \ubb38\uc7a5\uc73c\ub85c \uc774\uc57c\uae30\uc758 \ub73b\uc744 \ub2eb\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub204\uad70\uac00\ub97c \uadf8\ub9ac\uc6cc\ud574 \ub3cc\uc544\uc654\uc9c0\ub9cc \ub3cc\uc544\uac08 \uc2dc\uac04\uc744 \uc783\uc5b4\ubc84\ub9b0 \uc0ac\ub78c, \ud589\ubcf5\ud55c \uc21c\uac04\uc5d0 \uba38\ubb38 \ub300\uac00\ub97c \ub4a4\ub2a6\uac8c \uc54c\uac8c \ub41c \uc0ac\ub78c\uc758 \uc774\uc57c\uae30\ub85c\ub3c4 \ub0a8\ub294\ub2e4. \ubc14\ub2f7\uc18d \uad81\uc804\uc740 \uc2e0\ube44\ub86d\uc9c0\ub9cc \uc6b0\ub9ac\uac00 \uc624\ub798 \uae30\uc5b5\ud558\ub294 \uac83\uc740 \ud574\ubcc0\uc758 \uc791\uc740 \uc0c1\uc790\uc77c \uc218 \uc788\ub2e4. \uc5f4\uba74 \ub05d\ub098\uace0, \uc5f4\uc9c0 \uc54a\uc544\ub3c4 \uc27d\uac8c \ud480\ub9ac\uc9c0 \uc54a\ub294 \uc2dc\uac04\uc774 \uadf8 \uc548\uc5d0 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc774 \uc774\uc57c\uae30\ub97c \ud604\ub300 \uacfc\ud559\uc758 \uc2dc\uac04 \uc774\ub860\uc744 \ubbf8\ub9ac \uc54c\uc544\ub0b8 \uc99d\uac70\ub85c \ubcfc \ud544\uc694\ub294 \uc5c6\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc2dc\uac04\uc774\ub77c\ub294 \uc0c1\uc0c1\uc740 \uc774\ubcc4\uacfc \uadc0\ud5a5\uc744 \ub354 \uae4a\uac8c \ub290\ub07c\uac8c \ud558\ub294 \uc7a5\uce58\ub85c\ub3c4 \ucda9\ubd84\ud558\ub2e4. \uc2e0\ube44\ud55c \uc124\uba85\ubcf4\ub2e4 \ub3cc\uc544\uac08 \uacf3\uc744 \ucc3e\ub294 \uc0ac\ub78c\uc758 \ub9c8\uc74c\uc774 \uba3c\uc800 \ub0a8\uc744 \uc218 \uc788\ub2e4."}, {"id": "van-eyck-rolin-window", "title": "\ub864\ub7ad \uc7ac\uc0c1\uc758 \uc131\ubaa8 \u2014 \uc791\uc740 \ubc29 \ub108\uba38\uc5d0 \ub3c4\uc2dc\uac00 \ud3bc\uccd0\uc9c4\ub2e4", "summary": "\uc580 \ubc18 \uc5d0\uc774\ud06c\uc758 \uadf8\ub9bc\uc5d0\uc11c \uac00\uae4c\uc6b4 \uc778\ubb3c\uacfc \uba3c \uc138\uacc4\uac00 \ub9cc\ub098\ub294 \ubc29\uc2dd\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/van-eyck-rolin-window/index.html", "image": "../media/van-eyck-rolin-window.jpg", "alt": "\uc580 \ubc18 \uc5d0\uc774\ud06c\uc758 \ub864\ub7ad \uc7ac\uc0c1\uc758 \uc131\ubaa8. \uae30\ub3c4\ud558\ub294 \ub0a8\uc131\uacfc \uc131\ubaa8\uc790, \ucc9c\uc0ac, \ucc3d\ubb38 \ub108\uba38\uc758 \ub3c4\uc2dc\uc640 \uac15\uc774 \ubcf4\uc785\ub2c8\ub2e4.", "text": "\ub864\ub7ad \uc7ac\uc0c1\uc758 \uc131\ubaa8 \u2014 \uc791\uc740 \ubc29 \ub108\uba38\uc5d0 \ub3c4\uc2dc\uac00 \ud3bc\uccd0\uc9c4\ub2e4 \uae30\ub3c4\ud558\ub294 \ud6c4\uc6d0\uc790\uc640 \uc131\ubaa8\uc790, \ucc3d\ubc16 \ud48d\uacbd\uc744 \ud568\uaed8 \uc77d\uae30 \uc580 \ubc18 \uc5d0\uc774\ud06c\uc758 \uadf8\ub9bc\uc5d0\uc11c \uac00\uae4c\uc6b4 \uc778\ubb3c\uacfc \uba3c \uc138\uacc4\uac00 \ub9cc\ub098\ub294 \ubc29\uc2dd\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \uc67c\ucabd\uc5d0\ub294 \ud654\ub824\ud55c \uc637\uc744 \uc785\uc740 \ub0a8\uc790\uac00 \uc190\uc744 \ubaa8\uc73c\uace0, \uc624\ub978\ucabd\uc5d0\ub294 \uc544\uc774\ub97c \uc548\uc740 \uc5ec\uc778\uc774 \uc549\uc544 \uc788\ub2e4. \ub4a4\uc5d0\uc11c\ub294 \ucc9c\uc0ac\uac00 \uc655\uad00\uc744 \ub4e4\uace0 \uc788\ub2e4. \uadf8\ub7f0\ub370 \uc778\ubb3c\ub4e4\ub9cc \ubcf4\uace0 \ub05d\ub0b4\uae30\uc5d0\ub294 \ucc3d \ub108\uba38\uc758 \ud48d\uacbd\uc774 \ub108\ubb34 \uba40\ub9ac \ud3bc\uccd0\uc9c4\ub2e4. \ubc29 \uc548\uacfc \ubc14\uae65\uc758 \ub3c4\uc2dc\uac00 \ud55c \ud654\uba74\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc580 \ubc18 \uc5d0\uc774\ud06c\uc758 \u3008\ub864\ub7ad \uc7ac\uc0c1\uc758 \uc131\ubaa8\u3009\ub2e4. \ub0af\uc120 \uc774\ub984\uacfc \uc885\uad50\uc801 \uc778\ubb3c \ub54c\ubb38\uc5d0 \uc5b4\ub835\uac8c \ub290\uaef4\uc9c4\ub2e4\uba74, \uba3c\uc800 \uc55e\uc758 \uc0ac\ub78c\ub4e4\uacfc \ub4a4\uc758 \uac15\uc744 \ubc88\uac08\uc544 \ubcf4\uc790. \uadf8\ub9bc\uc740 \uac00\uae4c\uc6b4 \uad00\uacc4\uc640 \ub113\uc740 \uc138\uacc4\ub97c \ud568\uaed8 \ubcf4\ub3c4\ub85d \ub9cc\ub4e0\ub2e4. \uc67c\ucabd\uc5d0\uc11c \uae30\ub3c4\ud558\ub294 \uc778\ubb3c\uc740 \ub864\ub7ad \uc7ac\uc0c1\uc73c\ub85c \uc2dd\ubcc4\ub41c\ub2e4. \uc774 \uc791\ud488\uc740 \uc131\ubaa8\uc790\uc640 \uae30\uc99d\uc790\uc758 \ubaa8\uc2b5\uc744 \ud568\uaed8 \ub2f4\uc740 \ud68c\ud654\ub2e4. \uc885\uad50\uc801 \ub300\uc0c1\ub9cc\uc744 \ub530\ub85c \uadf8\ub9ac\ub294 \ub300\uc2e0, \uadf8 \uc55e\uc5d0 \uae30\ub3c4\ud558\ub294 \uc2e4\uc81c \uc0ac\ud68c\uc758 \uc778\ubb3c\uc774 \ud568\uaed8 \ub098\ud0c0\ub09c\ub2e4. \ucc98\uc74c\ubd80\ud130 \uae30\uc99d\uc790\uc758 \ubaa8\ub4e0 \uacbd\ub825\uacfc \uc9c0\uc704\ub97c \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uc774 \uadf8\ub9bc \uc548\uc5d0\ub294 \uc2e0\uc559\uc758 \uc138\uacc4\uc640 \uadf8 \uadf8\ub9bc\uc744 \ub9c8\ub828\ud55c \uc0ac\ub78c\uc758 \uc138\uacc4\uac00 \ub3d9\uc2dc\uc5d0 \ub4e4\uc5b4 \uc788\ub2e4\ub294 \uc810\uc744 \uc54c\uc544 \ub450\uba74 \uc88b\ub2e4. \uc778\ubb3c\uc758 \ubc30\uce58\ub97c \ubcf4\uba74 \ub2e8\uc21c\ud55c \uc131\ubaa8\uc790\ud654\uc640\ub294 \ub2e4\ub978 \uad00\uacc4\uac00 \ubcf4\uc778\ub2e4. \uc624\ub978\ucabd\uc740 \uc131\ubaa8 \ub9c8\ub9ac\uc544\uc640 \uc544\uae30 \uc608\uc218\ub2e4. \ucc9c\uc0ac\uac00 \uc655\uad00\uc744 \ub4e4\uace0 \ub098\ud0c0\ub098\ub294 \ubaa8\uc2b5\uc740 \ud654\uba74\uc774 \uc77c\uc0c1\uc801\uc778 \ubaa8\uc790 \ucd08\uc0c1\ub9cc\uc740 \uc544\ub2c8\ub77c\ub294 \ud45c\uc9c0\ub2e4. \uc544\uc774\uc640 \uc5b4\uba38\ub2c8\ub77c\ub294 \uce5c\uc219\ud55c \uad00\uacc4 \uc18d\uc5d0 \uae30\ub3c5\uad50 \ud68c\ud654\uc758 \uc758\ubbf8\uac00 \uacb9\uce5c\ub2e4. \uc774\ub984\uc744 \uc870\uae08 \uc54c\uace0 \ub098\uba74 \ub450 \uc0ac\ub78c\uc758 \uc790\uc138\uc640 \ub0a8\uc790\ub97c \ud5a5\ud55c \uad00\uacc4\ub97c \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uc885\uad50\uc801 \uc9c0\uc2dd\uc774 \uac10\uc0c1\uc744 \ub300\uc2e0\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \ub208\uc55e\uc758 \ubab8\uc9d3\uc744 \uc77d\ub294 \ub2e8\uc11c\ub97c \uc8fc\ub294 \uac83\uc774\ub2e4. \uc655\uad00\uacfc \uc637, \uc190\uc758 \ubc29\ud5a5\uc774 \ubb34\uc5c7\uc744 \ub354 \ubcf4\uac8c \ud558\ub294\uc9c0 \ucc9c\ucc9c\ud788 \ub530\ub77c\uac00 \ubcf4\uc790. \uae30\ub3c4\ud558\ub294 \ub0a8\uc131\uacfc \uc131\ubaa8\uc790\ub294 \uc11c\ub85c \ub9c8\uc8fc\ud55c \ub4ef \uac19\uc740 \ud68c\ub791 \uc548\uc5d0 \ub193\uc5ec \uc788\ub2e4. \ud06c\uae30\uc640 \uac70\ub9ac \ub54c\ubb38\uc5d0 \uad00\uac1d\uc740 \ub450 \uc138\uacc4\uac00 \uc544\uc8fc \uba40\ub9ac \ub5a8\uc5b4\uc838 \uc788\ub2e4\uace0\ub9cc \ub290\ub07c\uc9c0 \uc54a\ub294\ub2e4. \uc2e0\uc559\uc758 \ub300\uc0c1\uacfc \uae30\ub3c4\ud558\ub294 \uc0ac\ub78c\uc774 \uac00\uae4c\uc774 \ub9cc\ub098\ub294 \ubc29\uc2dd\uc73c\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc2e4\uc81c\ub85c \uadf8\ub4e4\uc774 \uac19\uc740 \ubc29\uc5d0\uc11c \ub9cc\ub0ac\ub2e4\ub294 \uc5ed\uc0ac\uc801 \uc7a5\uba74\uc744 \uae30\ub85d\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ud68c\ud654\uac00 \uc11c\ub85c \ub2e4\ub978 \ucc28\uc6d0\uc758 \uc778\ubb3c\uacfc \uc758\ubbf8\ub97c \ud55c \uacf5\uac04\uc5d0 \uad6c\uc131\ud558\ub294 \uac83\uc774\ub2e4. \ud654\uba74\uc744 \uc0ac\uc2e4\uc758 \uc0ac\uc9c4\uc73c\ub85c \uc624\ud574\ud558\uc9c0 \uc54a\uc744 \ub54c \uc774\ub7f0 \ubc30\uce58\uac00 \uc8fc\ub294 \ud798\ub3c4 \ub354 \uc798 \uc774\ud574\ub41c\ub2e4. \uac00\uae4c\uc6b4 \uc778\ubb3c\ub4e4 \uc0ac\uc774\uc640 \uc544\ub798\uc5d0\ub294 \ubc14\ub2e5\uc758 \ubb34\ub2ac\uac00 \uc788\uace0, \ub4a4\uc5d0\ub294 \uae30\ub465\uacfc \uc544\uce58\uac00 \uc774\uc5b4\uc9c4\ub2e4. \uc774\ub7f0 \uad6c\uc870\ub97c \ub530\ub77c\uac00\uba74 \ubc29\uc774 \ud3c9\ud3c9\ud55c \ubb34\ub2ac\ub85c \ub05d\ub098\uc9c0 \uc54a\uace0 \uae4a\uc774\ub97c \uac00\uc9c4 \uacf5\uac04\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uc0ac\ub78c\uc744 \ub458\ub7ec\uc2fc \uac74\ucd95\ub3c4 \uac10\uc0c1\uc758 \uc911\uc694\ud55c \ubd80\ubd84\uc774\ub2e4. \ubaa8\ub4e0 \uc7a5\uc2dd\uc744 \uc815\ud655\ud788 \uc7ac\uc5b4\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2dc\uc120\uc774 \uc5b4\ub514\uc5d0\uc11c \uba48\ucd94\uace0 \uc5b4\ub514\ub85c \uba40\uc5b4\uc9c0\ub294\uc9c0 \ub530\ub77c\uac00 \ubcf4\uba74 \ub41c\ub2e4. \uc778\ubb3c\uc758 \ubab8\uc774 \ud070 \uc790\ub9ac\ub97c \ucc28\uc9c0\ud558\uba74\uc11c\ub3c4 \ucc3d\ubc16\uc73c\ub85c \ub208\uc744 \uc5f4\uc5b4 \ub450\ub294 \ubc29\uc2dd\uc774, \uac00\uae4c\uc6b4 \uc7a5\uba74\uacfc \uba3c \ud48d\uacbd\uc744 \ud55c\uaebc\ubc88\uc5d0 \ubcf4\uac8c \ub9cc\ub4e0\ub2e4. \ub4a4\ucabd\uc758 \uc791\uc740 \uc815\uc6d0\uc744 \uc9c0\ub098\uba74 \uac15\uacfc \ub2e4\ub9ac, \uba40\ub9ac\uc758 \uac74\ubb3c\ub4e4\uc774 \ubcf4\uc778\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc0ac\uc18c\ud55c \ubc30\uacbd\ucc98\ub7fc \ub290\uaef4\uc84c\ub358 \ubd80\ubd84\uc5d0 \uc138\uacc4\uac00 \ud558\ub098 \ub354 \ub4e4\uc5b4 \uc788\ub294 \uc148\uc774\ub2e4. \uac00\uae4c\uc774 \ud655\ub300\ud574 \ubcf4\uace0 \ub2e4\uc2dc \uc804\uccb4\ub85c \ub3cc\uc544\uc624\uba74 \uadf8\ub9bc\uc774 \ud488\uc740 \uac70\ub9ac\uc758 \ucc28\uc774\uac00 \ub290\uaef4\uc9c4\ub2e4. \uc5b4\ub5a4 \uc2e4\uc81c \ub3c4\uc2dc\ub97c \uadf8\ub300\ub85c \uc62e\uacbc\ub294\uc9c0 \uc774 \uae00\uc5d0\uc11c \ud55c \uacf3\uc73c\ub85c \ud655\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc9c0\uae08 \ub208\uc73c\ub85c \ud655\uc778\ud558\ub294 \uac83\uc740 \uc0ac\ub78c\uc774 \uc788\ub294 \ubc29\uacfc \uc774\uc5b4\uc9c0\ub294 \ud48d\uacbd\uc774\ub2e4. \uc815\ud655\ud55c \uc9c0\uba85\uc744 \ub9de\ud788\ub294 \uc77c\ub9cc\uc774 \uac10\uc0c1\uc758 \ubaa9\ud45c\ub294 \uc544\ub2c8\ub2e4. \uc791\uc740 \ud654\uba74 \uc548\uc5d0\uc11c \uc5bc\ub9c8\ub098 \ub113\uc740 \uacf3\uc744 \ubcf4\uac8c \ub418\ub294\uc9c0 \ub290\uaef4\ub3c4 \uc88b\ub2e4. \ub0a8\uc790\uc758 \ubb34\ub2ac \uc788\ub294 \uc637\uacfc \uc131\ubaa8\uc758 \ub113\uc740 \ubd89\uc740 \uc637, \ucc9c\uc0ac\uc758 \uc655\uad00\uc740 \uac00\uae4c\uc6b4 \uacf3\uc5d0\uc11c \uc2dc\uc120\uc744 \ubd99\uc7a1\ub294\ub2e4. \uac15\uacfc \ub3c4\uc2dc\uc758 \uc791\uc740 \ubaa8\uc2b5\uc740 \ub354 \uba40\ub9ac \ub208\uc744 \uc6c0\uc9c1\uc774\uac8c \ud55c\ub2e4. \uc138\ubd80\uac00 \ub9ce\ub2e4\ub294 \uc0ac\uc2e4\ubcf4\ub2e4 \uadf8 \uc138\ubd80\ub4e4\uc774 \uc11c\ub85c \ub2e4\ub978 \uac70\ub9ac\ub97c \ub9cc\ub4e0\ub2e4\ub294 \uc810\uc5d0 \uc8fc\ubaa9\ud574 \ubcf4\uc790. \ubc18 \uc5d0\uc774\ud06c\ub97c \uc720\ud654\ub97c \ud63c\uc790 \ucc98\uc74c \ubc1c\uba85\ud55c \uc0ac\ub78c\uc774\ub77c\uace0 \uac04\ub2e8\ud788 \uc815\ub9ac\ud558\uc9c0\ub294 \ub9d0\uc790. \uc774 \uc791\ud488\uc5d0\uc11c \uc9c1\uc811 \ubcfc \uc218 \uc788\ub294 \uac83\uc740 \uc0c9\uacfc \ubb3c\uc9c8\uc758 \ud45c\ud604, \uc791\uc740 \uac83\ub4e4\uc744 \ud654\uba74\uc758 \uacf5\uac04 \uc548\uc5d0 \ub193\uc740 \uc19c\uc528\ub2e4. \uc720\uba85\ud55c \ubc1c\uba85 \uc774\uc57c\uae30\ubcf4\ub2e4 \uc2e4\uc81c\ub85c \uadf8\ub824\uc9c4 \uad00\uacc4\ub97c \ubcf4\ub294 \ud3b8\uc774 \uadf8\ub9bc\uc5d0 \ub354 \uac00\uae4c\uc774 \uac04\ub2e4. \uae30\ub3c4\ud558\ub294 \ud6c4\uc6d0\uc790\uac00 \uc790\uc2e0\uc758 \ubaa8\uc2b5\uc744 \uc885\uad50\uc801 \uc7a5\uba74\uc5d0 \ud568\uaed8 \ub0a8\uae34\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ud765\ubbf8\ub86d\ub2e4. \uac1c\uc778\uc758 \uc2e0\uc559\ubfd0 \uc544\ub2c8\ub77c \uc0ac\ud68c\uc801 \uc704\uce58\uc640 \uc790\uae30 \ubaa8\uc2b5\uc744 \ubcf4\uc774\ub294 \ubc29\uc2dd\ub3c4 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ub2e4\ub9cc \uadf8 \ub9c8\uc74c\uc18d \ub3d9\uae30\ub97c \uc624\uc9c1 \uacfc\uc2dc\ub098 \uc624\uc9c1 \uc21c\uc218\ud55c \ubbff\uc74c \ud558\ub098\ub85c \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uadf8\ub9bc\uc744 \ubcfc \ub54c\ub3c4 \ub458 \uc911 \ud558\ub098\ub9cc \uace0\ub974\ub824 \uc560\uc4f8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \uc911\uc694\ud55c \ub300\uc0c1\uc744 \uc5b4\ub5bb\uac8c \ud45c\ud604\ud558\uace0 \uc790\uae30 \uc0b6\uacfc \uc5f0\uacb0\ud588\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\ub294 \uac83\uc774\ub2e4. \uc791\ud488\uc740 \uc131\ubaa8\uc640 \uc544\uc774\ub9cc\uc744 \uc124\uba85\ud558\ub294 \ub370\uc11c \ub098\uc544\uac00, \uadf8\uac83\uc744 \ubc14\ub77c\ubcf4\ub294 \uc0ac\ub78c\uc758 \uc790\ub9ac\uae4c\uc9c0 \ud568\uaed8 \ub2f4\ub294\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \uc61b \ub8e8\ube0c\ub974 \ub3c4\ub85d\uc758 \uc2e4\uc81c \ud68c\ud654 \uc0c9\ucc44 \uc7ac\ud604 \uc790\ub8cc\ub2e4. \ucd5c\uc2e0 \uace0\ud574\uc0c1\ub3c4 \uc0ac\uc9c4\ucc98\ub7fc \ubaa8\ub4e0 \ud45c\uba74\uc744 \ubcf4\uc5ec \uc8fc\uc9c0\ub294 \uc54a\uc9c0\ub9cc \uc778\ubb3c\uacfc \uac74\ucd95, \uba3c \ud48d\uacbd\uc758 \ud070 \uad00\uacc4\ub97c \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \uc0c1\uc0c1\uc73c\ub85c \uc0c8\ub85c \ub9cc\ub4e0 \uc131\ubaa8 \uc7a5\uba74\uacfc\ub294 \uad6c\ubd84\ub41c\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc55e\uc758 \uc138 \uc778\ubb3c\uacfc \ucc9c\uc0ac\ub97c \uc54c\uc544\ubcf4\uace0, \ub2e4\uc74c\uc5d0\ub294 \uc778\ubb3c \uc0ac\uc774\ub85c \ucc3d\ubc16\uc744 \ubc14\ub77c\ubcf4\uc790. \ub2e4\uc2dc \ucc98\uc74c\uc73c\ub85c \ub3cc\uc544\uc624\uba74 \uae30\ub3c4\ud558\ub294 \uc0ac\ub78c\ub3c4 \ub354 \ub113\uc740 \uc138\uacc4 \uc548\uc5d0 \ub193\uc778\ub2e4. \ud55c \uadf8\ub9bc\uc758 \uad50\uc591\uc740 \uc791\uc740 \uc0c1\uc9d5\uc744 \ub9ce\uc774 \uc678\uc6b0\ub294 \ub370\ub9cc \uc788\uc9c0 \uc54a\ub2e4. \ud654\uba74 \uc18d \uac70\ub9ac\uc640 \uad00\uacc4\ub97c \ucc28\ub840\ub85c \uc54c\uc544\ubcf4\ub294 \ub370\uc11c\ub3c4 \uc2dc\uc791\ub41c\ub2e4."}, {"id": "van-gogh-life-and-letters", "title": "\ubc18 \uace0\ud750\uc758 \uc0dd\uc560 \u2014 \uadf8\ub9bc \uacc1\uc5d0\ub294 \ud3b8\uc9c0\uac00 \uc788\uc5c8\ub2e4", "summary": "\uc11c\uac04\uc9d1\uacfc \uc790\ud654\uc0c1\uc744 \ud1b5\ud574 \ubc30\uc6b0\uace0 \uc77c\ud558\uace0 \uad00\uacc4\ub97c \ub9fa\ub358 \ud654\uac00\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/van-gogh-life-and-letters/index.html", "image": "../media/van-gogh-life-and-letters.jpg", "alt": "\ubc18 \uace0\ud750 \uc790\ud654\uc0c1 \u00b7 1913\ub144 The Letters of a Post-Impressionist \uc218\ub85d \uc7ac\ud604\ub3c4\ud310", "text": "\ubc18 \uace0\ud750\uc758 \uc0dd\uc560 \u2014 \uadf8\ub9bc \uacc1\uc5d0\ub294 \ud3b8\uc9c0\uac00 \uc788\uc5c8\ub2e4 \ucc9c\uc7ac\ub77c\ub294 \ud55c\ub9c8\ub514 \ubc16\uc5d0\uc11c \ub9cc\ub098\ub294 \ud55c \uc0ac\ub78c \uc11c\uac04\uc9d1\uacfc \uc790\ud654\uc0c1\uc744 \ud1b5\ud574 \ubc30\uc6b0\uace0 \uc77c\ud558\uace0 \uad00\uacc4\ub97c \ub9fa\ub358 \ud654\uac00\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \ubc18 \uace0\ud750\uc758 \uc0dd\uc560\ub97c \uc774\uc57c\uae30\ud560 \ub54c\ub294 \u2018\uace0\ud1b5\ubc1b\uc740 \ucc9c\uc7ac\u2019\ub77c\ub294 \ub9d0\uc774 \uba3c\uc800 \ub098\uc624\uae30 \uc27d\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \ub9d0\ub9cc\uc73c\ub85c\ub294 \uc5b4\ub450\uc6b4 \ub18d\ubbfc\uc758 \uc5bc\uad74\uc744 \uadf8\ub9ac\ub358 \uc0ac\ub78c\uc774 \uc5b4\ub5bb\uac8c \uc544\ub97c\uc758 \ubc1d\uc740 \ubc29\uacfc \uc0dd\ub808\ubbf8\uc758 \ubc24\ud558\ub298\uc744 \uadf8\ub9ac\uac8c \ub418\uc5c8\ub294\uc9c0 \uc54c\uae30 \uc5b4\ub835\ub2e4. \uadf8\uc758 \uadf8\ub9bc\uc5d0\ub294 \uc11c\ub85c \ub2e4\ub978 \uc7a5\uc18c\uc640 \uacf5\ubd80, \uc0ac\ub78c\uacfc \uc0dd\ud65c\uc774 \ub4e4\uc5b4 \uc788\ub2e4. 1853\ub144\uc5d0 \ud0dc\uc5b4\ub098 1890\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub09c \ub124\ub35c\ub780\ub4dc \ud654\uac00 \ube48\uc13c\ud2b8 \ubc18 \uace0\ud750\ub97c, \uc774\ubc88\uc5d0\ub294 \uc791\ud488\uacfc \ud3b8\uc9c0\uac00 \ub9cc\ub098\ub294 \uba87 \uac1c\uc758 \uc804\ud658\uc810\uc73c\ub85c \ub530\ub77c\uac00 \ubcf4\uc790. \ud3b8\uc9c0\ub294 \uc804\uae30\uc758 \ube48\uce78\uc744 \ubaa8\ub450 \ucc44\uc6b0\uc9c0\ub294 \uc54a\uc9c0\ub9cc \uadf8\uac00 \uc2e4\uc81c\ub85c \ubb34\uc5c7\uc744 \uace0\ubbfc\ud558\uba70 \uc77c\ud588\ub294\uc9c0 \uc54c\ub824 \uc900\ub2e4. \uc9c0\uae08\uc758 \uc6b0\ub9ac\ub294 \uc720\uba85\ud55c \uadf8\ub9bc\ubd80\ud130 \ub9cc\ub09c\ub2e4. \uadf8\ub798\uc11c \ubc18 \uace0\ud750\uac00 \ucc98\uc74c\ubd80\ud130 \uc790\uc2e0\ub9cc\uc758 \uc0c9\uacfc \ubd93\uc9c8\uc744 \uac00\uc9c0\uace0 \uc788\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \ud3b8\uc9c0\uc5d0\ub294 \ubb34\uc5c7\uc744 \uadf8\ub9b4\uc9c0 \uc815\ud558\uace0, \ubaa8\ub378\uc744 \uad6c\ud558\uace0, \uba38\ub9ac\uc640 \uc190\uc744 \uac70\ub4ed \uc5f0\uc2b5\ud558\ub294 \uc2dc\uac04\uc774 \ub0a8\uc544 \uc788\ub2e4. \uc791\ud488\uc758 \uacb0\uacfc\uc640 \uc791\uc5c5\uc758 \uacfc\uc815\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \uc0b6\uc758 \uc6c0\uc9c1\uc784\uc774 \ubcf4\uc778\ub2e4. \ud2b9\ud788 \ub3d9\uc0dd \ud14c\uc624\ub294 \uc911\uc694\ud55c \ud3b8\uc9c0 \uc0c1\ub300\uc600\ub2e4. \ud615\uc740 \ubb3c\uac10\uacfc \ub3c8, \uadf8\ub9bc\uc5d0 \ub300\ud55c \uacc4\ud68d\uacfc \ubd88\uc548\uc744 \ub3d9\uc0dd\uc5d0\uac8c \uc774\uc57c\uae30\ud55c\ub2e4. \ud14c\uc624\ub294 \uc0dd\ud65c\uacfc \uc791\uc5c5\uc744 \uc9c0\uc6d0\ud588\uace0, \ud615\uc740 \uadf8 \uad00\uacc4 \uc18d\uc5d0\uc11c \uacc4\uc18d \uc77c\uc744 \uc774\uc5b4 \uac14\ub2e4. \ud654\uac00\uc758 \uc0b6\uc744 \uace0\ub3c5\ud55c \uc601\uc6c5\uc758 \uc774\uc57c\uae30\ub85c\ub9cc \ub9cc\ub4e4\uba74 \uc774\ub7f0 \uad6c\uccb4\uc801\uc778 \uc5f0\uacb0\uc774 \uc0ac\ub77c\uc9c4\ub2e4. 1880\ub144 6\uc6d4\uacbd \ubca8\uae30\uc5d0 \ubcf4\ub9ac\ub098\uc8fc\uc758 \ud034\uc5e0\uc5d0\uc11c \ud14c\uc624\uc5d0\uac8c \uc4f4 \ud3b8\uc9c0\uc5d0\ub294 \uc9c4\ub85c\uc640 \uac00\uc871 \uad00\uacc4\uc758 \uc5b4\ub824\uc6c0\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \ubc18 \uace0\ud750\ub294 \ub3d9\uc0dd\uc774 \ubcf4\ub0b4 \uc900 \ub3c8\uc5d0 \uac10\uc0ac\ub97c \uc804\ud558\uba74\uc11c\ub3c4, \uc790\uc2e0\uc774 \uac00\uc871\uc5d0\uac8c \uc2e0\ub8b0\ubc1b\uc9c0 \ubabb\ud55c\ub2e4\uace0 \ub290\ub07c\ub294 \uc0ac\uc815\uc744 \uc774\uc57c\uae30\ud55c\ub2e4. \ud6d7\ub0a0\uc758 \uba85\uc131\uc744 \uc7a0\uc2dc \ub0b4\ub824\ub193\uc73c\uba74 \uc55e\ub0a0\uc774 \ubd88\ud655\uc2e4\ud588\ub358 \uc2a4\ubb3c\uc77c\uacf1 \uc0b4\uc758 \uc0ac\ub78c\uc774 \ubcf4\uc778\ub2e4. \uadf8 \ud3b8\uc9c0\uc5d0\ub294 \uc131\uc11c\uc640 \ubb38\ud559\uc744 \uc77d\uace0 \ubbf8\uc220\uc744 \uc0dd\uac01\ud558\ub294 \uc2dc\uac04\ub3c4 \ub0a8\uc544 \uc788\ub2e4. \ubc29\ud5a5\uc774 \uc7a1\ud788\uc9c0 \uc54a\uc558\ub2e4\ub294 \uac83\uc774 \uc544\ubb34 \uad00\uc2ec\ub3c4 \ub178\ub825\ub3c4 \uc5c6\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub110\ub9ac \uc54c\ub824\uc9c4 \uc791\ud488\uc774 \ub098\uc624\uae30 \uc804\uc758 \uc774\ub7f0 \uc2dc\uae30\ub97c \uc54c\uace0 \ub098\uba74, \uadf8\uc758 \uc0dd\uc560\uac00 \ucc9c\uc7ac\uc758 \ud0c4\uc0dd\uacfc \ube44\uadf9\uc801\uc778 \uc8fd\uc74c \uc0ac\uc774\ub97c \uace7\uc7a5 \ub2ec\ub9b0 \uc774\uc57c\uae30\ub294 \uc544\ub2c8\uc5c8\ub2e4\ub294 \uac83\uc744 \uc54c \uc218 \uc788\ub2e4. 1885\ub144 4\uc6d4 30\uc77c \ub258\ub10c\uc5d0\uc11c \ud14c\uc624\uc5d0\uac8c \ubcf4\ub0b8 \ud3b8\uc9c0\uc5d0\uc11c \ubc18 \uace0\ud750\ub294 \u3008\uac10\uc790 \uba39\ub294 \uc0ac\ub78c\ub4e4\u3009\uc744 \uc124\uba85\ud55c\ub2e4. \uadf8\ub294 \uc644\uc131\ub41c \uadf8\ub9bc\uc758 \uc791\uc5c5 \uae30\uac04\ub9cc\uc774 \uc544\ub2c8\ub77c \uadf8\uc804 \uaca8\uc6b8 \ub0b4\ub0b4 \uba38\ub9ac\uc640 \uc190\uc744 \uadf8\ub9b0 \uc2b5\uc791\uc774 \uc788\uc5c8\ub2e4\uace0 \uc54c\ub9b0\ub2e4. \uc9e7\uc740 \uc2dc\uac04\uc5d0 \uadf8\ub9b0 \uac83\ucc98\ub7fc \ubcf4\uc5ec\ub3c4 \uadf8 \uc55e\uc5d0\ub294 \uae34 \uc900\ube44\uac00 \ub193\uc5ec \uc788\ub2e4\ub294 \ub73b\uc774\ub2e4. \uad00\uc2ec\uc744 \ub454 \uac83\uc740 \uc608\uc058\uac8c \uafb8\ubbfc \ub18d\ubbfc\uc758 \ubaa8\uc2b5\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uac10\uc790\ub97c \uc9d1\ub294 \uc190\uc774 \uc2e4\uc81c\ub85c \ub545\uc744 \uc77c\uad70 \uc190\uc774\ub77c\ub294 \uc810, \uadf8 \uc74c\uc2dd\uacfc \ub178\ub3d9\uc774 \uc774\uc5b4\uc838 \uc788\ub2e4\ub294 \uc810\uc744 \ubcf4\uc5ec \uc8fc\uace0 \uc2f6\uc5b4 \ud588\ub2e4. \uc774 \ucd08\uae30\uc758 \uad00\uc2ec\uc744 \uc54c\uc544 \ub450\uba74 \uc774\ud6c4\uc758 \ubc1d\uc740 \uc0c9\ucc44\ub9cc\uc73c\ub85c \ubc18 \uace0\ud750 \uc804\uccb4\ub97c \uc124\uba85\ud558\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uc0ac\ub78c\uc744 \uc5b4\ub5bb\uac8c \uadf8\ub9b4 \uac83\uc778\uac00\ub77c\ub294 \uc9c8\ubb38\uc774 \uc774\ubbf8 \uc791\uc5c5\uc758 \uc911\uc2ec\uc5d0 \uc788\uc5c8\ub2e4. \uadf8\uc758 \uc791\uc5c5 \uc5ec\uc815\uc5d0\ub294 \ub124\ub35c\ub780\ub4dc\uc640 \ud30c\ub9ac, \ub0a8\ud504\ub791\uc2a4\uc758 \uc544\ub97c, \uc0dd\ub808\ubbf8, \ub9c8\uc9c0\ub9c9 \uc2dc\uae30\uc758 \uc624\ubca0\ub974\uc26c\ub974\uc6b0\uc544\uc988\uac00 \uc774\uc5b4\uc9c4\ub2e4. \uc774 \uc774\ub984\ub4e4\uc744 \uba85\ud654\uac00 \ud0c4\uc0dd\ud55c \uad00\uad11\uc9c0\ub85c\ub9cc \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc7a5\uc18c\uac00 \ub2ec\ub77c\uc9c8 \ub54c \ub9cc\ub098\ub294 \uc0ac\ub78c\uacfc \ube5b, \uadf8\ub9bc\uc744 \ubcfc \uae30\ud68c\uc640 \uc791\uc5c5 \uc870\uac74\ub3c4 \ud568\uaed8 \ubc14\ub010\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc911\uc694\ud558\ub2e4. \ud30c\ub9ac \uc2dc\uae30\uc640 \ub0a8\ud504\ub791\uc2a4 \uc2dc\uae30\ub97c \ub5a0\uc62c\ub9b4 \ub54c\ub3c4 \uc5b4\ub450\uc6b4 \uadf8\ub9bc\uc774 \uc5b4\ub290 \ub0a0 \ud55c\uc21c\uac04\uc5d0 \ubc1d\uc544\uc84c\ub2e4\uace0 \uc815\ub9ac\ud558\uae30\ubcf4\ub2e4, \ubb34\uc5c7\uc744 \uad00\ucc30\ud558\uace0 \uc5b4\ub5a4 \uc0c9\uc744 \uc4f0\ub824 \ud588\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uba74 \uc88b\ub2e4. \ud3b8\uc9c0\ub294 \uadf8\uac00 \ub2e4\ub978 \ud654\uac00\ub97c \uc758\uc2dd\ud558\uace0 \uc790\uc2e0\uc758 \uc791\ud488\uc744 \ube44\uad50\ud558\uba70 \ubc29\ud5a5\uc744 \ucc3e\uc558\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uace0\uac31\uacfc \ubca0\ub974\ub098\ub974 \uac19\uc740 \ub3d9\ub8cc\uc758 \uc774\ub984\ub3c4 \uc774\ub7f0 \uc791\uc5c5\uc758 \ub300\ud654 \uc18d\uc5d0 \ub4f1\uc7a5\ud55c\ub2e4. 1888\ub144 10\uc6d4 16\uc77c \uc544\ub97c\uc5d0\uc11c \uc4f4 \ud3b8\uc9c0\ub294 \u3008\uce68\uc2e4\u3009\uc744 \uc124\uba85\ud55c\ub2e4. \ubc18 \uace0\ud750\ub294 \ubc29 \uc548\uc758 \ubb3c\uac74\uc744 \uc790\uc138\ud788 \ub098\uc5f4\ud558\uba74\uc11c \uc0c9\uacfc \ub2e8\uc21c\ud55c \ud615\ud0dc\ub97c \ud1b5\ud574 \ud734\uc2dd\uc758 \ub290\ub08c\uc744 \uc804\ud558\ub824\uace0 \ud55c\ub2e4. \uce68\ub300\uc640 \uc758\uc790, \ubb38\uacfc \ubcbd\uc744 \uadf8\ub0e5 \ubcf4\uc774\ub294 \ub300\ub85c \uc62e\uae30\ub294 \uac83\ub9cc\uc774 \ubaa9\uc801\uc740 \uc544\ub2c8\uc5c8\ub358 \uc148\uc774\ub2e4. \uc774\ub97c \uc54c\uace0 \ub098\uba74 \ubc18 \uace0\ud750\uc758 \uac15\ud55c \uc0c9\uc744 \ubb34\uc870\uac74 \ud765\ubd84\uc774\ub098 \ubd88\uc548\uc758 \ud45c\uc2dc\ub85c \ubcfc \uc218 \uc5c6\uac8c \ub41c\ub2e4. \uadf8\uac00 \uc870\uc6a9\ud55c \uc27c\uc744 \ud45c\ud604\ud558\ub824\uace0 \uc120\ud0dd\ud55c \uc0c9\ub3c4 \uc788\uc5c8\ub2e4. \uc5b4\ub5a4 \uadf8\ub9bc\uc758 \uc0c9\uc774 \uac15\ud558\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \ud654\uac00\uc758 \uc815\uc2e0 \uc0c1\ud0dc\ub97c \ubc14\ub85c \uc9c4\ub2e8\ud558\uc9c0 \ub9d0\uc544\uc57c \ud558\ub294 \uae4c\ub2ed\uc774\ub2e4. \uc791\ud488\uc758 \uc2e4\uc81c \uc124\uba85\uacfc \ud654\uba74\uc744 \ud568\uaed8 \uc0b4\ud53c\ub294 \ud3b8\uc774 \ub0ab\ub2e4. \ubc18 \uace0\ud750\ub294 \ub3d9\ub8cc \ud654\uac00\ub4e4\uacfc\uc758 \uad00\uacc4\ub97c \uc911\uc694\ud558\uac8c \uc5ec\uacbc\ub2e4. \ud3b8\uc9c0\uc5d0\ub294 \uace0\uac31\uacfc \ubca0\ub974\ub098\ub974\uc758 \uc791\ud488\uc744 \ud3c9\uac00\ud558\uace0, \uc790\uc2e0\uc758 \uadf8\ub9bc\uacfc \uc5b4\ub5a4 \uc810\uc5d0\uc11c \ud1b5\ud560 \uc218 \uc788\uc744\uc9c0 \uc0dd\uac01\ud558\ub294 \ub0b4\uc6a9\uc774 \uc788\ub2e4. \ud63c\uc790\ub9cc\uc758 \uba38\ub9bf\uc18d \uc138\uacc4\ub97c \uadf8\ub300\ub85c \uc3df\uc544 \ub0b8 \ud654\uac00\ub77c\ub294 \uc778\uc0c1\uacfc\ub294 \ub2e4\ub978 \ubaa8\uc2b5\uc774\ub2e4. \uadf8\ub294 \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc790\uc2e0\uc758 \uadf8\ub9bc\uc744 \uc5b4\ub5bb\uac8c \ubcfc\uc9c0\ub3c4 \uace0\ubbfc\ud588\ub2e4. \uc0dd\ud65c\uc774 \ub298 \uc548\uc815\uc801\uc774\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uacbd\uc81c\uc801 \uc758\uc874\uacfc \uad00\uacc4\uc758 \uc5b4\ub824\uc6c0, \uac74\uac15\uc0c1\uc758 \uc704\uae30\uac00 \uc791\uc5c5\uacfc \ud568\uaed8 \uc774\uc5b4\uc84c\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubd88\ud589\uc774 \ub9ce\uc744\uc218\ub85d \uc704\ub300\ud55c \uc608\uc220\uc774 \ub098\uc628\ub2e4\ub294 \uacf5\uc2dd\uc744 \ub9cc\ub4e4 \uc218\ub294 \uc5c6\ub2e4. \uc5b4\ub824\uc6c0 \uc18d\uc5d0\uc11c\ub3c4 \uc791\uc5c5\uc744 \uc9c0\uc18d\ud558\ub824 \ud588\ub2e4\ub294 \uc0ac\uc2e4\uacfc, \uc5b4\ub824\uc6c0\uc774 \uc791\ud488\uc758 \uac00\uce58\ub97c \ub9cc\ub4e4\uc5b4 \uc8fc\uc5c8\ub2e4\ub294 \uc8fc\uc7a5\uc740 \ub2e4\ub974\ub2e4. \uc0dd\ub808\ubbf8 \uc2dc\uae30\uc758 1889\ub144 6\uc6d4 \ud3b8\uc9c0\uc5d0\uc11c \uadf8\ub294 \uc0dd\ud65c\uc758 \uc808\uc81c\uc640 \uce58\ub8cc, \uc791\uc5c5\uc774 \uc790\uc2e0\uc5d0\uac8c \uc5b4\ub5a4 \uc5ed\ud560\uc744 \ud558\ub294\uc9c0 \ud14c\uc624\uc5d0\uac8c \uc54c\ub9b0\ub2e4. \uc0c8\ub85c \uadf8\ub9b0 \uc62c\ub9ac\ube0c\ub098\ubb34 \ud48d\uacbd\uacfc \ubcc4\uc774 \uc788\ub294 \ubc24\ud558\ub298\uc744 \uc774\uc57c\uae30\ud558\uace0, \ub3d9\ub8cc\ub4e4\uacfc \ub098\ub208 \ud68c\ud654\uc758 \uc0dd\uac01\ub3c4 \ub3cc\uc544\ubcf8\ub2e4. \uac74\uac15\uc758 \uc5b4\ub824\uc6c0\uacfc \uad6c\uccb4\uc801\uc778 \uc791\uc5c5 \uacc4\ud68d\uc774 \uac19\uc740 \ud3b8\uc9c0 \uc548\uc5d0 \ub193\uc5ec \uc788\ub2e4. \ubc24\ud558\ub298\uc758 \uadf8\ub9bc\uc744 \uc8fd\uc74c\uc758 \uc608\uace0\ub098 \uc99d\uc0c1\uc758 \ub3c4\uc2dd\uc73c\ub85c\ub9cc \uc77d\uc73c\uba74 \uc774\ub7f0 \uc791\uc5c5\uc758 \uc5b8\uc5b4\uac00 \uc0ac\ub77c\uc9c4\ub2e4. \ubb34\uc5c7\uc744 \ubcf4\uc558\uace0 \uc0c9\uacfc \uc120\uc73c\ub85c \ubb34\uc5c7\uc744 \ud45c\ud604\ud558\ub824 \ud588\ub294\uc9c0 \uba3c\uc800 \ubb3c\uc5b4\ubcf4\uc790. \uc774 \uae00\uc740 \uc624\ub798\ub41c \uc11c\uac04\uc9d1\uc758 \ub0a0\uc9dc\uac00 \ubd80\uc815\ud655\ud55c \uacf3\uc744 \uadf8\ub300\ub85c \uc62e\uae30\uc9c0 \uc54a\uace0, \ud604\ub300 \ud3b8\uc9c0 \uc815\ub9ac\ubcf8\uc758 \ud574\ub2f9 \uae30\ub85d\uacfc \ub300\uc870\ud588\ub2e4. \ud604\ub300 \ubc88\uc5ed\ubb38 \uc790\uccb4\ub97c \uc62e\uaca8 \uc2e3\uc9c0\ub294 \uc54a\uc558\ub2e4. 1890\ub144 7\uc6d4\uacbd \uc624\ubca0\ub974\uc26c\ub974\uc6b0\uc544\uc988\uc5d0\uc11c \ubcf4\ub0b8 \ud3b8\uc9c0\uc5d0\ub294 \ub113\uc740 \ubc00\ubc2d\uacfc \uac70\uce5c \ud558\ub298\uc744 \uadf8\ub9b0 \uc791\uc5c5, \uac00\uc871\uc758 \uc0dd\ud65c\uc5d0 \ub300\ud55c \uac71\uc815\uc774 \ud568\uaed8 \ub098\uc628\ub2e4. \uc774 \ud3b8\uc9c0\ub294 \uc0b6\uc758 \ub9c8\uc9c0\ub9c9 \uc2dc\uae30\uc5d0 \uc18d\ud558\uc9c0\ub9cc, \ubb38\uc7a5 \ud558\ub098\ub97c \uace7\ubc14\ub85c \uc8fd\uc74c\uc758 \uc608\uc5b8\ucc98\ub7fc \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8\ub9bc\uc744 \uc644\uc131\ud558\uace0 \uac00\uc871\uc5d0\uac8c \ubcf4\uc5ec \uc8fc\ub824\ub294 \uc77c\uc0c1\uc801\uc778 \ubc14\ub78c\ub3c4 \uc548\uc5d0 \uc788\ub2e4. \ubc18 \uace0\ud750\ub294 \uac19\uc740 \ud574\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub0ac\ub2e4. \uc5ec\uae30\uc11c\ub294 \uadf8\ub9bc\uc758 \ud2b9\uc815 \uc0c8\ub098 \ud558\ub298\uc744 \uc0ac\ub9dd \uacbd\uc704\uc758 \uc99d\uac70\ub85c \uc0bc\uac70\ub098, \ud3b8\uc9c0\ub9cc\uc73c\ub85c \ubcd1\uba85\uc744 \ud655\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc0b6\uc758 \ub05d\uc744 \uc548\ub2e4\ub294 \uc774\uc720\ub85c \uadf8\uc804\uc758 \ubaa8\ub4e0 \uc791\uc5c5\uc744 \uc8fd\uc74c\uc73c\ub85c\ub9cc \ud5a5\ud558\ub294 \uae38\ub85c \ub9cc\ub4e4\uba74 \ud654\uac00\uac00 \uc2e4\uc81c\ub85c \ud574 \uc628 \ud0d0\uad6c\ub97c \ub193\uce58\uae30 \uc27d\ub2e4. \ucc98\uc74c \uc77d\ub294\ub2e4\uba74 \u3008\uac10\uc790 \uba39\ub294 \uc0ac\ub78c\ub4e4\u3009\uc5d0\uc11c\ub294 \uc190\uacfc \ub178\ub3d9\uc744, \u3008\uce68\uc2e4\u3009\uc5d0\uc11c\ub294 \uc0c9\uacfc \ud734\uc2dd\uc744, \uc0dd\ub808\ubbf8\uc758 \ubc24\ud558\ub298\uc5d0\uc11c\ub294 \ud48d\uacbd\uacfc \ud45c\ud604\uc744 \ube44\uad50\ud574 \ubcf4\uc790. \uc11c\ub85c \ub2e4\ub978 \uc2dc\uae30\uc758 \uc791\ud488\uc744 \ub098\ub780\ud788 \ub193\uc73c\uba74 \u2018\ud56d\uc0c1 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uadf8\ub9b0 \ud654\uac00\u2019\uac00 \uc544\ub2c8\ub77c \uacc4\uc18d \ubcc0\ud654\ub97c \uc2dc\ub3c4\ud55c \uc0ac\ub78c\uc774 \ubcf4\uc778\ub2e4. \uc774\ubc88 \uae00\uc5d0 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 1913\ub144 \uc11c\uac04\uc9d1\uc5d0 \uc218\ub85d\ub41c \uc790\ud654\uc0c1\uc758 \uc7ac\ud604 \ub3c4\ud310\uc774\uba70 \uc774 \uc138 \uc791\ud488\uc758 \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \ubc18 \uace0\ud750\uc758 \uadf8\ub9bc \uacc1\uc5d0\ub294 \ub3c8\uacfc \ubb3c\uac10, \uacf5\ubd80\uc640 \uac00\uc871, \ud734\uc2dd\uacfc \uce58\ub8cc\ub97c \ub9d0\ud558\ub294 \ud3b8\uc9c0\uac00 \ub0a8\uc544 \uc788\ub2e4. \uadf8\uac83\uc744 \uc54c\uace0 \ub2e4\uc2dc \uc790\ud654\uc0c1\uc744 \ubcf4\uba74 \uc720\uba85\ud55c \ube44\uadf9\uc758 \uc5bc\uad74\ub9cc \ubcf4\uc774\uc9c0\ub294 \uc54a\uc744 \uac83\uc774\ub2e4. \uc9e7\uc740 \uc0dd\uc560 \uc548\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uc77c\ud560\uc9c0 \uac70\ub4ed \uc0dd\uac01\ud588\ub358 \uc0ac\ub78c, \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc790\uc2e0\uc758 \uadf8\ub9bc\uc744 \uc774\ud574\uc2dc\ud0a4\ub824 \ud588\ub358 \uc0ac\ub78c\uc744 \ud568\uaed8 \ub9cc\ub0a0 \uc218 \uc788\ub2e4."}, {"id": "vermeer-lacemaker-looking-guide", "title": "\ub808\uc774\uc2a4 \ub728\ub294 \uc5ec\uc778 \u2014 \uc791\uc740 \uc77c\uc5d0 \uc2dc\uc120\uc774 \ubaa8\uc77c \ub54c", "summary": "\ub8e8\ube0c\ub974\uc758 \uc870\uc6a9\ud55c \uc791\uc5c5 \uc7a5\uba74\uc5d0\uc11c \uc778\ubb3c\uc758 \uc190\uacfc \uc2e4, \uc0c9\uc744 \ub530\ub77c\uac00 \ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/vermeer-lacemaker-looking-guide/index.html", "image": "../media/vermeer-lacemaker-looking-guide.jpg", "alt": "\uc694\ud558\ub124\uc2a4 \ubca0\ub974\uba54\ub974, \ub808\uc774\uc2a4 \ub728\ub294 \uc5ec\uc778 \u00b7 \uc61b \ub8e8\ube0c\ub974 \ub3c4\ub85d Plate XXXVI", "text": "\ub808\uc774\uc2a4 \ub728\ub294 \uc5ec\uc778 \u2014 \uc791\uc740 \uc77c\uc5d0 \uc2dc\uc120\uc774 \ubaa8\uc77c \ub54c \ubca0\ub974\uba54\ub974\uac00 \ubcf4\uc5ec \uc8fc\ub294 \uc190\uacfc \uc9d1\uc911\uc758 \uc7a5\uba74 \ub8e8\ube0c\ub974\uc758 \uc870\uc6a9\ud55c \uc791\uc5c5 \uc7a5\uba74\uc5d0\uc11c \uc778\ubb3c\uc758 \uc190\uacfc \uc2e4, \uc0c9\uc744 \ub530\ub77c\uac00 \ubd05\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \ud55c \uc5ec\uc778\uc774 \uace0\uac1c\ub97c \uc219\uc774\uace0 \uc190\ub05d\uc5d0 \uc9d1\uc911\ud558\uace0 \uc788\ub2e4. \uc601\uc6c5\uc758 \uc2b9\ub9ac\ub3c4 \uc655\uc758 \uc989\uc704\ub3c4 \uc544\ub2cc, \uc791\uc740 \uc791\uc5c5\uc774 \uadf8\ub9bc\uc758 \uc804\ubd80\uc778 \uac83\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uc694\ud558\ub124\uc2a4 \ubca0\ub974\uba54\ub974\uc758 \u3008\ub808\uc774\uc2a4 \ub728\ub294 \uc5ec\uc778\u3009\uc744 \ucc98\uc74c \ub9cc\ub098\uba74 \ubb34\uc5c7\uc744 \uc624\ub798 \ubcf4\uc544\uc57c \ud560\uc9c0 \ub9c9\ub9c9\ud560 \uc218\ub3c4 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uadf8\ub9bc \uc18d \uc0ac\ub78c\uc774 \ubc14\ub77c\ubcf4\ub294 \ubc29\ud5a5\uc744 \ub530\ub77c\uac00\uba74 \ud654\uba74\uc758 \uc911\uc2ec\uc744 \ucc3e\uc744 \uc218 \uc788\ub2e4. \uc774 \uc791\ud488\uc740 \ud070 \uc0ac\uac74 \uc5c6\uc774\ub3c4 \uc0ac\ub78c\uc758 \uc2dc\uac04\uc744 \ubd99\uc7a1\uc744 \uc218 \uc788\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ud504\ub791\uc2a4\uc5b4 \uc81c\ubaa9 \ub77c \ub2f9\ud154\ub9ac\uc5d0\ub974\ub294 \ub808\uc774\uc2a4\ub97c \ub9cc\ub4dc\ub294 \uc5ec\uc778\uc744 \uac00\ub9ac\ud0a8\ub2e4. \uc5ec\uc778\uc740 \ubcf4\ube48\uc774\ub77c\ub294 \uc791\uc740 \ub3c4\uad6c\uc5d0 \uac10\uae34 \uc2e4\uc744 \ub2e4\ub8e8\uba70 \ub808\uc774\uc2a4\ub97c \ub9cc\ub4e4\uace0 \uc788\ub2e4. \uc2e4\uc758 \uad50\ucc28\ub85c \ubb34\ub2ac\ub97c \uc9dc\ub294 \uc77c\uc774\ub2e4. \uae34 \ub300\ubc14\ub298\ub85c \ud138\uc637\uc744 \ub728\ub294 \uc7a5\uba74\uc744 \uba3c\uc800 \ub5a0\uc62c\ub838\ub2e4\uba74 \uc190 \uc8fc\ubcc0\uc758 \uc791\uc740 \ub3c4\uad6c\uc640 \uc791\uc5c5 \uc790\ub9ac\ub97c \ub2e4\uc2dc \ubcf4\uc790. \uadf8\ub9bc\uc758 \uc81c\ubaa9\uc744 \uc544\ub294 \uac83\uacfc \uadf8 \uc77c\uc774 \ubb34\uc5c7\uc778\uc9c0 \uc544\ub294 \uac83\uc740 \uc870\uae08 \ub2e4\ub978 \uacbd\ud5d8\uc774\ub2e4. \ub3c4\ud310\uc5d0\uc11c\ub294 \uc2e4\uacfc \ub3c4\uad6c\uc758 \uc138\ubd80\ub97c \ubaa8\ub450 \uad6c\ubcc4\ud558\uae30 \uc5b4\ub835\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc791\uc740 \uc810 \ud558\ub098\ub97c \uc5b5\uc9c0\ub85c \ud2b9\uc815 \ub3c4\uad6c\ub77c\uace0 \ud310\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub450 \uc190\uc774 \uc544\uc8fc \uc881\uc740 \uc790\ub9ac\uc5d0 \ubaa8\uc5ec \uc788\uace0 \uc2dc\uc120\uc774 \uadf8\uacf3\uc744 \ud5a5\ud55c\ub2e4\ub294 \uad00\uacc4\ubd80\ud130 \ubcf4\uba74 \ub41c\ub2e4. \uc7a5\uba74\uc744 \uc774\ud574\ud558\ub294 \ub370 \ud544\uc694\ud55c \ud575\uc2ec\uc740 \uc774\ubbf8 \ubcf4\uc778\ub2e4. \ucd08\uc0c1\ud654\uc5d0\uc11c\ub294 \uc778\ubb3c\uc774 \uad00\uac1d\uc744 \uc815\uba74\uc73c\ub85c \ubc14\ub77c\ubcf4\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4. \uc5ec\uae30\uc758 \uc5ec\uc778\uc740 \uc6b0\ub9ac\ub97c \ud5a5\ud574 \ud3ec\uc988\ub97c \ucde8\ud558\uae30\ubcf4\ub2e4 \uc790\uae30 \uc77c\uc744 \ud558\uace0 \uc788\ub2e4. \uadf8\ub798\uc11c \uad00\uac1d\uc740 \ub204\uad70\uac00\uc758 \ubc29\uc5d0 \uc7a0\uae50 \ub4e4\uc5b4\uc640 \uc870\uc6a9\ud788 \uadf8 \uc2dc\uac04\uc744 \uc9c0\ucf1c\ubcf4\ub294 \ub4ef\ud55c \uc704\uce58\uc5d0 \ub193\uc778\ub2e4. \uc778\ubb3c\uc758 \ub208\uc5d0\uc11c \uc190\uc73c\ub85c \ub0b4\ub824\uc624\ub294 \uae38\uc744 \ub530\ub77c\uac00 \ubcf4\uc790. \uc6b0\ub9ac\uac00 \ubcf4\ub294 \ubc29\ud5a5\uacfc \uadf8\ub9bc \uc18d \uc0ac\ub78c\uc774 \ubcf4\ub294 \ubc29\ud5a5\uc774 \uacb9\uce58\uba74\uc11c \uc791\uc740 \uc791\uc5c5\uc774 \ub354 \uc911\uc694\ud558\uac8c \ub290\uaef4\uc9c4\ub2e4. \ubb34\uc2a8 \uc0ac\uac74\uc778\uc9c0 \ubab0\ub77c\uc11c \ube44\uc5b4 \uc788\ub294 \uadf8\ub9bc\uc774 \uc544\ub2c8\ub77c, \ud55c \uc0ac\ub78c\uc774 \uc9d1\uc911\ud558\uace0 \uc788\ub2e4\ub294 \uc0ac\uac74\uc774 \uc774\ubbf8 \uc77c\uc5b4\ub098\uace0 \uc788\ub294 \uadf8\ub9bc\uc73c\ub85c \ubcfc \uc218 \uc788\ub2e4. \uc5ec\uc778\uc740 \ubc1d\uc740 \ub178\ub780\ube5b \uc0c1\uc758\ub97c \uc785\uc5c8\ub2e4. \uc8fc\ubcc0\uc758 \ube44\uad50\uc801 \uc5b4\ub450\uc6b4 \ubd80\ubd84\uacfc \uad6c\ubcc4\ub418\uba74\uc11c \ubab8\uc774 \uac00\uae4c\uc774 \ub290\uaef4\uc9c4\ub2e4. \uba3c\uc800 \uc0c9\uc5d0 \uc774\ub04c\ub9ac\uace0, \uadf8 \uc0c9\uc744 \uc785\uc740 \uc0ac\ub78c\uc758 \uc790\uc138\ub97c \ub530\ub77c\uac00\uba70 \uc190\ub05d\uc5d0 \uc774\ub974\ub294 \uc2dd\uc73c\ub85c \uac10\uc0c1\ud574 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc774\ub294 \ud55c \uac00\uc9c0 \uc77d\ub294 \ubc29\ubc95\uc774\uba70 \ubaa8\ub4e0 \uad00\uac1d\uc774 \uac19\uc740 \uc21c\uc11c\ub85c \ubcf4\uc544\uc57c \ud55c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uba38\ub9ac\uc640 \uc5b4\uae68, \ub450 \ud314\uc774 \ub9cc\ub4dc\ub294 \ubaa8\uc591\uc744 \uc0b4\ud53c\uba74 \uc778\ubb3c\uc774 \ud06c\uac8c \uc6c0\uc9c1\uc774\uc9c0 \uc54a\uc544\ub3c4 \ud654\uba74\uc5d0 \ubc29\ud5a5\uc774 \uc788\ub2e4\ub294 \uac83\uc744 \ub290\ub084 \uc218 \uc788\ub2e4. \uc190\uc774 \uc5b4\ub514\uc5d0 \ubaa8\uc774\ub294\uc9c0, \ud314\uc774 \uadf8 \uc790\ub9ac\ub97c \uc5b4\ub5bb\uac8c \uac10\uc2f8\ub294\uc9c0 \ubcf4\ub294 \uac83\uc774\ub2e4. \uc0c9\ub9cc \ub530\ub85c \ubcf4\ub294 \uac83\uc5d0\uc11c \ubab8\uc758 \uad6c\uc870\ub85c \ub118\uc5b4\uac00\uba74 \uadf8\ub9bc\uc774 \uc870\uae08 \ub354 \uc785\uccb4\uc801\uc73c\ub85c \ub2e4\uac00\uc628\ub2e4. \ud654\uba74 \uc55e\uc5d0\ub294 \ucfe0\uc158\uacfc \uc2e4, \ucc45\ucc98\ub7fc \ubcf4\uc774\ub294 \ubb3c\uac74\uc774 \ub193\uc5ec \uc788\ub2e4. \ub178\ub780 \uc637\uc758 \ub113\uc740 \uc0c9\uba74\uacfc \ub2ec\ub9ac \uc55e\ucabd\uc758 \ubd89\uc740 \uc2e4\uc740 \ud480\uc5b4\uc9c4 \uac00\ub2e5\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uc774 \uc5b4\uc218\uc120\ud55c \ubd80\ubd84\uacfc \uc190 \uc8fc\ubcc0\uc758 \uc9d1\uc911\ub41c \uc790\uc138\ub97c \ubc88\uac08\uc544 \ubcf4\uc544\ub3c4 \uc7ac\ubbf8\uc788\ub2e4. \ubaa8\ub4e0 \uacf3\uc774 \uac19\uc740 \uc815\ub3c4\ub85c \ub610\ub837\ud558\uac8c \uc815\ub9ac\ub418\uc5b4\uc57c\ub9cc \uadf8\ub9bc\uc774 \uc0dd\uc0dd\ud574\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc791\uc5c5\ud558\ub294 \uc7a5\uba74\uc5d0 \ub2e4\ub978 \ubb3c\uac74\ub4e4\uc774 \ub07c\uc5b4 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub3c4 \uc911\uc694\ud558\ub2e4. \uc0ac\ub78c\uc740 \ubc30\uacbd \uc5c6\ub294 \uacf5\uac04\uc5d0\uc11c \uc190\ub9cc \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc8fc\ubcc0\uc758 \ubb3c\uac74\uacfc \uac70\ub9ac\ub97c \ub9cc\ub4e4\uba70 \uc77c\ud55c\ub2e4. \ub2e4\ub9cc \ucc45\uc774 \uc788\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \uc5ec\uc778\uc758 \uc2e0\uc559\uc774\ub098 \uc131\uaca9\uc744 \uace7\ubc14\ub85c \ub2e8\uc815\ud558\uc9c0\ub294 \ub9d0\uc790. \ubb3c\uac74\uc758 \uc874\uc7ac\ub97c \ud655\uc778\ud558\ub294 \uac83\uacfc \uadf8 \uc0c1\uc9d5\uc744 \ud655\uc815\ud558\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \ubca0\ub974\uba54\ub974\ub294 17\uc138\uae30 \ub124\ub35c\ub780\ub4dc \ud654\uac00\uc774\uba70 \uc870\uc6a9\ud55c \uc2e4\ub0b4\uc758 \uc778\ubb3c\uc744 \uadf8\ub9b0 \uc791\ud488\ub4e4\ub85c \uc54c\ub824\uc838 \uc788\ub2e4. \uc655\uc2e4\uc758 \ud070 \uc0ac\uac74\ubcf4\ub2e4 \ubc29 \uc548\uc758 \uc77c\uc0c1, \ud3b8\uc9c0\ub97c \uc77d\uac70\ub098 \uc77c\uc744 \ud558\ub294 \uc778\ubb3c \uac19\uc740 \uc7a5\uba74\uc5d0\uc11c \ud68c\ud654\uc758 \uc8fc\uc81c\ub97c \ucc3e\uc558\ub2e4. \uc774 \uc791\ud488\ub3c4 \uadf8\ub7f0 \uac10\uc0c1\uc758 \uc785\uad6c\uac00 \ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uadf8\ub9bc\uc744 \ub2f9\uc2dc \ub124\ub35c\ub780\ub4dc\uc758 \ubaa8\ub4e0 \uac00\uc815\uc774 \uc774\ub7ac\ub2e4\ub294 \uc0ac\uc9c4 \uc99d\uac70\ucc98\ub7fc \uc77d\uc744 \uc218\ub294 \uc5c6\ub2e4. \ud654\uac00\ub294 \uc2e4\uc81c \uc0dd\ud65c\uc5d0\uc11c \ubcfc \uc218 \uc788\ub294 \uc18c\uc7ac\ub97c \uace0\ub974\uace0 \ubc30\uce58\ud558\uc5ec \ud654\uba74\uc744 \ub9cc\ub4e0\ub2e4. \uc77c\uc0c1\uc758 \uc7a5\uba74\uc774\uba74\uc11c \ub3d9\uc2dc\uc5d0 \uc798 \uad6c\uc131\ub41c \ud68c\ud654\ub77c\ub294 \ub450 \uc131\uaca9\uc744 \ud568\uaed8 \uc0dd\uac01\ud558\uba74 \uc88b\ub2e4. \uadf8\ub9bc \uc18d \uc5ec\uc778\uc774 \ud654\uac00\uc758 \uac00\uc871 \uc911 \ub204\uad6c\ub77c\uace0 \uc5ec\uae30\uc11c \ud655\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc5bc\uad74\uc744 \ubcf4\uace0 \uc774\ub984\uc744 \uc54c\uc544\ub9de\ud600\uc57c \uc791\ud488\uc744 \uc774\ud574\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\uae68\ub97c \ub465\uae00\uac8c \ubaa8\uc73c\uace0 \uc2dc\uc120\uc744 \ub0ae\ucd94\ub294 \uc790\uc138\ub9cc\uc73c\ub85c\ub3c4 \uc6b0\ub9ac\ub294 \uc9d1\uc911\ud558\ub294 \ubab8\uc758 \uacbd\ud5d8\uc744 \uc54c\uc544\ubcfc \uc218 \uc788\ub2e4. \ubc14\ub290\uc9c8\uc774\ub098 \uae00\uc4f0\uae30, \uc791\uc740 \ubb3c\uac74\uc744 \uace0\uce58\ub294 \uc77c\uc744 \ud574 \ubcf8 \uae30\uc5b5\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ub0a8\uc774 \ubd80\ub974\uba74 \uc7a0\uae50 \uace0\uac1c\ub97c \ub4e4\uc9c0\ub9cc \uace7 \ub2e4\uc2dc \ub3cc\uc544\uac00\uace0 \uc2f6\uc740 \uadf8\ub7f0 \uc2dc\uac04\uc774 \uc788\ub2e4. \uc61b \uadf8\ub9bc \uc18d \uc0ac\ub78c\uc744 \uc624\ub298\uc758 \uc6b0\ub9ac\uc640 \ub611\uac19\ub2e4\uace0 \ub2e8\uc21c\ud654\ud558\uc9c0 \uc54a\uc73c\uba74\uc11c\ub3c4, \ubab8\uc758 \uc790\uc138\ub97c \ud1b5\ud574 \uac00\uae4c\uc6cc\uc9c8 \uc218\ub294 \uc788\ub2e4. \uc774 \uc791\ud488\uc744 \ubcfc \ub54c\ub294 \ubaa8\ub4e0 \ubd80\ubd84\uc758 \uc124\uba85\uc744 \ube60\uc9d0\uc5c6\uc774 \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc138 \ubc88 \uc2dc\uc120\uc744 \uc62e\uaca8 \ubcf4\uc790. \ub178\ub780 \uc637\uc744 \ubcf4\uace0, \uc5bc\uad74\uacfc \uc190\uc758 \uc5f0\uacb0\uc744 \ubcf4\uace0, \ub9c8\uc9c0\ub9c9\uc73c\ub85c \uc8fc\ubcc0 \ubb3c\uac74\uacfc\uc758 \uad00\uacc4\ub97c \ubcf4\ub294 \uac83\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc61b \uc0c9\ucc44 \uc7ac\ud604 \ub3c4\ud310\uc5d0\uc11c\ub294 \ubbf8\uc138\ud55c \ud45c\uba74\ubcf4\ub2e4 \uc804\uccb4 \uad6c\uc131\uacfc \ud070 \uc0c9\uc758 \uad00\uacc4\ub97c \uc911\uc2ec\uc73c\ub85c \uc0b4\ud3b4\ubcf4\ub294 \ud3b8\uc774 \uc801\uc808\ud558\ub2e4. \ud55c \uc0ac\ub78c\uc758 \uc791\uc740 \uc77c\uc774 \uadf8\ub9bc\uc758 \uc911\uc2ec\uc5d0 \ub193\uc600\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uae30\uc5b5\ud558\uace0 \ub098\uba74 \uc870\uc6a9\ud55c \uc7a5\uba74\uc774 \uc2ec\uc2ec\ud558\uac8c\ub9cc \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ud070 \uc0ac\uac74\uc744 \uadf8\ub9b0 \uadf8\ub9bc\uc740 \uc0ac\uac74\uc758 \uacb0\uacfc\ub97c \uad81\uae08\ud558\uac8c \ud55c\ub2e4. \uc774 \uadf8\ub9bc\uc740 \ud55c \uc0ac\ub78c\uc774 \uc9c0\uae08 \ubcf4\ub0b4\uace0 \uc788\ub294 \uc2dc\uac04\uc744 \uc870\uae08 \ub354 \ubc14\ub77c\ubcf4\uac8c \ud55c\ub2e4. \uadf8 \ucc28\uc774\ub97c \ub290\ub07c\ub294 \uac83\uc774 \ubca0\ub974\uba54\ub974\ub97c \ub9cc\ub098\ub294 \uc88b\uc740 \uc2dc\uc791\uc774\ub2e4."}, {"id": "vermeer-milkmaid-light-and-pouring", "title": "\uc6b0\uc720 \ub530\ub974\ub294 \uc5ec\uc778 \u2014 \uc791\uc740 \ub3d9\uc791\uc740 \uc5b4\ub5bb\uac8c \uc624\ub798 \ub0a8\uc744\uae4c", "summary": "\ud070 \uc0ac\uac74 \uc5c6\ub294 \uc2e4\ub0b4\uc5d0\uc11c \ube5b\uacfc \ud750\ub974\ub294 \uc6b0\uc720, \ubb3c\uac74\uacfc \ube48 \uacf5\uac04\uc774 \uc9d1\uc911\uc744 \ub9cc\ub4dc\ub294 \ubc29\uc2dd\uc744 \ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/vermeer-milkmaid-light-and-pouring/index.html", "image": "../media/vermeer-milkmaid-light-and-pouring.jpg", "alt": "\ucc3d\uc5d0\uc11c \ub4e4\uc5b4\uc628 \ube5b \uc544\ub798 \uc2dd\ud0c1\uc758 \uadf8\ub987\uc5d0 \uc6b0\uc720\ub97c \ub530\ub974\ub294 \uc5ec\uc778\uc758 \uc2e4\uc81c \uc791\ud488 \uc5ed\uc0ac \ub3c4\ud310", "text": "\uc6b0\uc720 \ub530\ub974\ub294 \uc5ec\uc778 \u2014 \uc791\uc740 \ub3d9\uc791\uc740 \uc5b4\ub5bb\uac8c \uc624\ub798 \ub0a8\uc744\uae4c \uc67c\ucabd \ucc3d\uc758 \ube5b\uacfc \uc190\uc758 \ub3d9\uc791, \uc0ac\ubb3c\uacfc \ube48 \ubcbd\uc758 \uad00\uacc4 \ud070 \uc0ac\uac74 \uc5c6\ub294 \uc2e4\ub0b4\uc5d0\uc11c \ube5b\uacfc \ud750\ub974\ub294 \uc6b0\uc720, \ubb3c\uac74\uacfc \ube48 \uacf5\uac04\uc774 \uc9d1\uc911\uc744 \ub9cc\ub4dc\ub294 \ubc29\uc2dd\uc744 \ubd05\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \ud070 \uc0ac\uac74\uc774 \uc77c\uc5b4\ub098\uc9c0 \uc54a\ub294\ub2e4. \ud55c \uc5ec\uc778\uc774 \uadf8\ub987\uc5d0 \uc6b0\uc720\ub97c \ub530\ub974\uace0, \ucc3d\uc73c\ub85c \ub4e4\uc5b4\uc624\ub294 \ube5b\uc774 \ubc29\uc744 \ube44\ucd98\ub2e4. \ud398\ub974\uba54\uc774\ub974\uc758 \u300c\uc6b0\uc720 \ub530\ub974\ub294 \uc5ec\uc778\u300d\uc740 \uc774\ub7f0 \uc791\uc740 \ub3d9\uc791\uc744 \uc624\ub798 \ubc14\ub77c\ubcf4\uac8c \ub9cc\ub4e0\ub2e4. \ubb34\uc5c7\uc744 \ub9ce\uc774 \ub123\uc5c8\ub294\uc9c0\ubcf4\ub2e4 \ubb34\uc5c7\uc744 \uc870\uc6a9\ud788 \ub0a8\uacbc\ub294\uc9c0 \uc0b4\ud53c\uba74, \uc77c\uc0c1\uc758 \uc7a5\uba74\uc774 \ud68c\ud654\uac00 \ub418\ub294 \ubc29\uc2dd\uc744 \ubcfc \uc218 \uc788\ub2e4. \uc791\ud488\uc740 \u300c\uc6b0\uc720 \ub530\ub974\ub294 \uc5ec\uc778\u300d \ub610\ub294 \u300c\uc6b0\uc720\ub97c \ub530\ub974\ub294 \ud558\ub140\u300d \uac19\uc740 \uc774\ub984\uc73c\ub85c \ubd88\ub9b0\ub2e4. \uc624\ub798\ub41c \ub3c4\ub85d\uc5d0\ub294 \uc694\ub9ac\ud558\ub294 \uc0ac\ub78c\uc774\ub77c\ub294 \uc81c\ubaa9\ub3c4 \ubcf4\uc778\ub2e4. \uc81c\ubaa9\uc740 \ud589\ub3d9\uacfc \uc5ed\ud560\uc744 \uc548\ub0b4\ud558\uc9c0\ub9cc \ubaa8\ub378\uc758 \uc815\ud655\ud55c \uc774\ub984\uacfc \ud558\ub8e8 \uc804\uccb4\ub97c \uc54c\ub824 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub9bc\uc744 \uace7\ubc14\ub85c \ud2b9\uc815\uc778\uc758 \uc0dd\ud65c \uae30\ub85d\uc73c\ub85c \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uad00\uac1d\uc740 \ud55c \uc7a5\uba74\uc5d0\uc11c \uc9c1\uc5c5\uacfc \uac10\uc815, \uac00\uc815\uc758 \uad00\uacc4\uae4c\uc9c0 \ucd94\uc815\ud558\uae30 \uc27d\uc9c0\ub9cc \uc2e4\uc81c\ub85c \ubcf4\uc774\ub294 \ubc94\uc704\ub97c \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ud654\uba74\uc5d0 \ub0a8\uc740 \ub3d9\uc791\uacfc \ubb3c\uac74\uc5d0\uc11c \uc2dc\uc791\ud558\ub294 \ud3b8\uc774 \uac10\uc0c1\uc744 \ub354 \ub2e8\ub2e8\ud558\uac8c \ud55c\ub2e4. \ube5b\uc740 \uc67c\ucabd \ucc3d\uc744 \ud1b5\ud574 \ub4e4\uc5b4\uc640 \uc778\ubb3c\uacfc \ubcbd, \uc2dd\ud0c1\uc758 \uc77c\ubd80\ub97c \ub4dc\ub7ec\ub0b8\ub2e4. \ubc29 \uc804\uccb4\ub97c \uac19\uc740 \ubc1d\uae30\ub85c \ub9cc\ub4e4\uc9c0 \uc54a\ub294\ub2e4. \ubc1d\uace0 \uc5b4\ub450\uc6b4 \ucc28\uc774 \ub355\ubd84\uc5d0 \ubab8\uc758 \ubd80\ud53c\uc640 \uc7ac\ub8cc\uc758 \ud45c\uba74\uc774 \ub098\ud0c0\ub09c\ub2e4. \uc5b4\ub514\uc5d0\uc11c \ube5b\uc774 \uc624\ub294\uc9c0 \uc544\ub294 \uac83\ub9cc\uc73c\ub85c \uacf5\uac04\uc758 \uc9c8\uc11c\uac00 \ubcf4\uc774\uae30 \uc2dc\uc791\ud55c\ub2e4. \ube5b\uc740 \ubb3c\uac74\uc744 \uc124\uba85\ud558\ub294 \ub3d9\uc2dc\uc5d0 \uc2dc\uc120\uc744 \uba38\ubb3c\uac8c \ud55c\ub2e4. \ucc3d\ubb38 \uc790\uccb4\ubcf4\ub2e4 \uadf8 \ube5b\uc744 \ubc1b\uc740 \uc5bc\uad74\uacfc \ud314, \ube75\uacfc \uadf8\ub987\uc744 \ubcf4\uac8c \ub41c\ub2e4. \uc77c\uc0c1\uc758 \ud3c9\ubc94\ud55c \uc7ac\ub8cc\uac00 \uc138\uc2ec\ud558\uac8c \ubcf4\uc774\ub294 \uc774\uc720\ub2e4. \ud06c\uac8c \uafb8\ubbfc \ubb34\ub300\ubcf4\ub2e4 \uc81c\ud55c\ub41c \ubc29 \uc548\uc758 \ucc28\uc774\uac00 \uc911\uc694\ud558\ub2e4. \uc6b0\uc720\ub294 \uac00\ub294 \ud750\ub984\uc73c\ub85c \ub5a8\uc5b4\uc9c0\uace0 \uc778\ubb3c\uc758 \ubab8\uc740 \uc548\uc815\ub41c \uc790\uc138\ub97c \ucde8\ud55c\ub2e4. \uc6c0\uc9c1\uc774\ub294 \ubd80\ubd84\uacfc \uba48\ucd98 \ubd80\ubd84\uc774 \ub300\ube44\ub41c\ub2e4. \ucee4\ub2e4\ub780 \ubab8\uc9d3 \uc5c6\uc774\ub3c4 \uc2dc\uac04\uc758 \ud750\ub984\uc744 \ub290\ub07c\uac8c \ud558\ub294 \uad6c\uc131\uc774\ub2e4. \uc561\uccb4\uac00 \uacc4\uc18d \ub5a8\uc5b4\uc9c8 \uac83 \uac19\uc9c0\ub9cc \uadf8\ub9bc\uc5d0\uc11c\ub294 \uadf8 \uc21c\uac04\uc774 \uba48\ucd94\uc5b4 \uc788\ub2e4. \uc5ec\uc778\uc740 \uad00\uac1d\uc5d0\uac8c \uc2dc\uc120\uc744 \ubcf4\ub0b4\uc9c0 \uc54a\uace0 \ud558\ub294 \uc77c\uc5d0 \uc9d1\uc911\ud55c\ub2e4. \ubcf4\ub294 \uc0ac\ub78c\uc774 \uc788\ub2e4\uace0 \ud589\ub3d9\uc744 \ubc14\uafb8\ub294 \ub4ef\ud55c \ubaa8\uc2b5\uc774 \uc544\ub2c8\ub2e4. \uad00\uac1d\uc740 \uc7a5\uba74\uc744 \ubc29\ud574\ud558\uc9c0 \uc54a\uace0 \uc7a0\uc2dc \uc9c0\ucf1c\ubcf4\ub294 \uc790\ub9ac\uc5d0 \ub193\uc778\ub2e4. \uc778\ubb3c\uc774 \ub098\ub97c \ubcf4\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc624\ud788\ub824 \ub354 \uac00\uae4c\uc774 \uad00\ucc30\ud558\uac8c \ud55c\ub2e4. \uc2dd\ud0c1 \uc704\uc758 \ube75\uacfc \ubc14\uad6c\ub2c8, \uc5ec\ub7ec \uc6a9\uae30\ub294 \ubb34\uc5c7\uc744 \ud558\ub294 \uacf3\uc778\uc9c0 \uc54c\ub824 \uc900\ub2e4. \ub3d9\uc2dc\uc5d0 \ud45c\uba74\uacfc \uc9c8\uac10\uc758 \ucc28\uc774\ub97c \ub9cc\ub4e0\ub2e4. \uac70\uce5c \ube75\uacfc \ub2e8\ub2e8\ud55c \uadf8\ub987, \ucc9c\uc758 \ubd80\ub4dc\ub7ec\uc6c0\uc740 \uac19\uc740 \ube5b\uc744 \uc11c\ub85c \ub2e4\ub974\uac8c \ubc1b\ub294\ub2e4. \ubb3c\uac74\uc774 \ub9ce\uc9c0 \uc54a\uc544\ub3c4 \uac10\uac01\uc758 \ucc28\uc774\ub294 \ud48d\ubd80\ud558\ub2e4. \uc774\ub7f0 \ucc28\uc774\ub97c \uc0b4\ud53c\uba74 \uadf8\ub9bc\uc744 \uc8fc\uc778\uacf5 \ud55c \uba85\uc758 \ucd08\uc0c1\uc73c\ub85c\ub9cc \ubcfc \uc218 \uc5c6\uac8c \ub41c\ub2e4. \uc190\uc758 \ud589\ub3d9\uacfc \ub3c4\uad6c\uc758 \uc704\uce58, \uc2dd\ud0c1\uc758 \ub192\uc774\uac00 \ud568\uaed8 \uc77c\uc744 \uac00\ub2a5\ud558\uac8c \ud55c\ub2e4. \uc778\ubb3c\uacfc \uc0ac\ubb3c\uc758 \uad00\uacc4\uac00 \uc7a5\uba74\uc758 \uc911\uc2ec\uc774\ub2e4. \uac00\uae4c\uc6b4 \ubb3c\uac74\ub4e4\uc758 \ubc30\uce58\uac00 \uc0ac\ub78c\uc758 \uc2dc\uac04\uc744 \uc124\uba85\ud55c\ub2e4. \ube75\uc758 \ud45c\uba74\uacfc \uc791\uc740 \ube5b\uc758 \uc810\uc744 \uac00\uae4c\uc774 \ubcf4\uace0 \ub2e4\uc2dc \ubab8 \uc804\uccb4\ub85c \ubb3c\ub7ec\ub098 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uac00\uae4c\uc6b4 \uac70\ub9ac\uc758 \uac10\uac01\uacfc \uba40\ub9ac\uc11c \uc77d\ud788\ub294 \uc548\uc815\ub41c \uad6c\uc131\uc774 \ub2e4\ub974\uac8c \ub290\uaef4\uc9c4\ub2e4. \uc138\ubd80\ub97c \ub9ce\uc774 \uadf8\ub838\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc0dd\uc0dd\ud568\uc774 \uc0dd\uae30\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uadf8 \uc138\ubd80\uac00 \ud070 \ub369\uc5b4\ub9ac\uc640 \uc5b4\ub5a4 \uad00\uacc4\ub97c \uc774\ub8e8\ub294\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \uc190\uacfc \uadf8\ub987\uc744 \uc911\uc2ec\uc73c\ub85c \ubcf4\ub2e4\uac00 \ucc3d\ubb38\uacfc \ube48 \ubcbd\uc73c\ub85c \ub3cc\uc544\uac00\uba74, \uac19\uc740 \ubb3c\uac74\ub4e4\uc774 \uc11c\ub85c\ub97c \uc5bc\ub9c8\ub098 \uc870\uc6a9\ud788 \ubc1b\uccd0 \uc8fc\ub294\uc9c0 \uc54c \uc218 \uc788\ub2e4. \ud654\uba74\uc5d0\uc11c \ub35c \uac15\uc870\ub41c \ubd80\ubd84\uc774 \uc788\uc5b4\uc57c \uac15\uc870\ub41c \ubd80\ubd84\ub3c4 \uc791\ub3d9\ud55c\ub2e4. \uc774 \uadf8\ub9bc\uc758 \uc808\uc81c\ub294 \uc544\ubb34 \uc77c\ub3c4 \ud558\uc9c0 \uc54a\uc740 \uacb0\uacfc\uac00 \uc544\ub2c8\ub77c \uad00\uac1d\uc758 \uad00\uc2ec\uc774 \ud769\uc5b4\uc9c0\uc9c0 \uc54a\ub3c4\ub85d \uc870\uc815\ud55c \uc120\ud0dd\uc73c\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \uc544\uc8fc \uc791\uc740 \ud589\ub3d9\uc774 \uc624\ub798 \ub0a8\ub294 \uc774\uc720\ub97c \uc774\uc57c\uae30\uc758 \ud06c\uae30\ubcf4\ub2e4 \uadf8\ub9bc\uc758 \uad00\uacc4\uc5d0\uc11c \ucc3e\uac8c \ub41c\ub2e4. \ub4a4\ucabd \ubcbd\uc758 \ub113\uc740 \uba74\uc740 \uc2dc\uc120\uc744 \uc26c\uac8c \ud558\uba74\uc11c \uc778\ubb3c\uc744 \ub610\ub837\ud558\uac8c \ud55c\ub2e4. \uc544\ubb34\uac83\ub3c4 \uc5c6\uc73c\ub2c8 \uc911\uc694\ud558\uc9c0 \uc54a\ub2e4\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\uc9c0\ub9cc, \ubcf5\uc7a1\ud55c \ubc30\uacbd\uc774 \uc904\uc5b4\ub4e0 \ub9cc\ud07c \uc791\uc740 \ub3d9\uc791\uc774 \uac15\ud574\uc9c4\ub2e4. \ud654\uba74\uc758 \uc758\ubbf8\ub294 \ucc44\uc6b4 \ubd80\ubd84\uacfc \ub0a8\uaca8 \ub454 \ubd80\ubd84\uc774 \ud568\uaed8 \ub9cc\ub4e0\ub2e4. \ubcbd\uc758 \uc791\uc740 \ud754\uc801\ub3c4 \uc644\uc804\ud788 \ucd94\uc0c1\uc801\uc778 \ud770 \uba74\uacfc \ub2e4\ub978 \ub290\ub08c\uc744 \uc900\ub2e4. \uc774\uacf3\uc740 \uc0ac\ub78c\uc758 \uc0ac\uc6a9\uacfc \uc2dc\uac04\uc774 \uc788\uc5c8\ub358 \ubc29\ucc98\ub7fc \ubcf4\uc778\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \ud754\uc801\ub9c8\ub2e4 \ud558\ub098\uc758 \ud655\uc815\ub41c \uc774\uc57c\uae30\ub97c \ubd99\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uad00\ucc30\ud55c \uac83\uc744 \ub118\uc5b4\uc11c \uacfc\uac70\ub97c \uc9c0\ub098\uce58\uac8c \uc644\uc131\ud558\uc9c0 \uc54a\ub294 \ud0dc\ub3c4\ub3c4 \uc911\uc694\ud558\ub2e4. \uc774 \uc7a5\uba74\uc740 \ud654\ub824\ud55c \uc190\ub2d8\uc774\ub098 \uad8c\ub825\uc790\uc758 \ud589\uc0ac \ub300\uc2e0 \uc0dd\ud65c\uc744 \uc720\uc9c0\ud558\ub294 \uc77c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uadf8\ub7f0\ub370 \ud3c9\ubc94\ud55c \ub178\ub3d9\uc744 \ucc28\ubd84\ud558\uac8c \uadf8\ub838\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub2f9\uc2dc\uc758 \ubaa8\ub4e0 \ub178\ub3d9\uc774 \ud3b8\uc548\ud588\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc544\ub984\ub2e4\uc6b4 \ud68c\ud654\uc640 \uc2e4\uc81c \uc0dd\ud65c\uc758 \uc870\uac74\uc740 \uad6c\ubd84\ud574\uc11c \ubcf4\uc544\uc57c \ud55c\ub2e4. \uadf8\ub9bc\uc740 \ud55c \uc0ac\ub78c\uc758 \uc77c\uc744 \uc9c4\uc9c0\ud558\uac8c \ubc14\ub77c\ubcf4\uac8c \ud55c\ub2e4. \ud06c\uace0 \uc601\uc6c5\uc801\uc778 \ud589\ub3d9\ub9cc\uc774 \uc8fc\ubaa9\ud560 \uac00\uce58\uac00 \uc788\ub2e4\ub294 \uae30\uc900\uc5d0\uc11c \ubc97\uc5b4\ub09c\ub2e4. \ub3d9\uc2dc\uc5d0 \uc778\ubb3c\uc744 \ub2e8\uc21c\ud788 \uc544\ub984\ub2e4\uc6b4 \ud48d\uacbd\uc758 \uc77c\ubd80\ub85c\ub9cc \ubcf4\uc9c0 \uc54a\uc744 \uc218\ub3c4 \uc788\ub2e4. \uc6b0\uc720\ub97c \ub530\ub974\ub294 \ub3d9\uc791\uc5d0\ub294 \uc9d1\uc911\uacfc \uc190\uc758 \uc870\uc808\uc774 \ud544\uc694\ud558\ub2e4. \uc0ac\uc6a9\ud55c \uc774\ubbf8\uc9c0\ub294 \uc624\ub798\ub41c \ucd9c\ud310\ubb3c\uc758 \uc2e4\uc81c \uc791\ud488 \ub3c4\ud310\uc774\ub2e4. \uc624\ub298\uc758 \uace0\ud574\uc0c1\ub3c4 \ucd2c\uc601\uc774\ub098 \uc6d0\uc791 \uc55e\uc5d0\uc11c \ub290\ub07c\ub294 \ud45c\uba74\uacfc \uac19\uc9c0\ub294 \uc54a\uc9c0\ub9cc \uad6c\uc131\uc744 \ube44\uad50\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ucc3d\uc5d0\uc11c \uc190\uc73c\ub85c, \ud750\ub974\ub294 \uc6b0\uc720\uc5d0\uc11c \uc2dd\ud0c1\uc73c\ub85c \uc2dc\uc120\uc744 \uc62e\uaca8 \ubcf4\uc790. \ud398\ub974\uba54\uc774\ub974\uc758 \uadf8\ub9bc\uc740 \ud070 \uc904\uac70\ub9ac\ub97c \ubab0\ub77c\ub3c4 \uc624\ub798 \ubcfc \uc218 \uc788\ub2e4. \ube5b\uacfc \uc6c0\uc9c1\uc784, \ubb3c\uc9c8\uacfc \ube48 \uacf5\uac04\uc758 \uad00\uacc4\ub97c \ub530\ub77c\uac00\uba74 \uc791\uc740 \ubc29\uc774 \ub113\uc740 \uac10\uc0c1\uc758 \uc7a5\uc18c\uac00 \ub41c\ub2e4. \uc77c\uc0c1\uc744 \uadf8\ub9b0\ub2e4\ub294 \uac83\uc740 \uc0ac\uc18c\ud55c \uac83\uc744 \uadf8\ub300\ub85c \ubcf5\uc0ac\ud558\ub294 \uc77c\uc774 \uc544\ub2c8\ub77c \ubb34\uc5c7\uc744 \uc624\ub798 \ubcf4\uac8c \ud560\uc9c0 \uc120\ud0dd\ud558\ub294 \uc77c\uc774\uc5c8\ub2e4."}, {"id": "victorian-paper-lace-valentine", "title": "\uc61b \uc5f0\uc560\ud3b8\uc9c0\uc5d0\ub294 \uc885\uc774\ub85c \ub9cc\ub4e0 \ub808\uc774\uc2a4\uac00 \uc788\uc5c8\ub2e4", "summary": "\uaf43\uacfc \ucc9c, \uc885\uc774 \ub808\uc774\uc2a4\ub97c \uacb9\uccd0 \ub9cc\ub4e0 \ubc38\ub7f0\ud0c0\uc778 \uce74\ub4dc\uc758 \ubaa8\uc2b5\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc2e0\ud654\uc640 \ubbfc\uc18d", "categories": ["arts"], "url": "stories/victorian-paper-lace-valentine/index.html", "image": "../media/victorian-paper-lace-valentine.jpg", "alt": "\uc61b \uc5f0\uc560\ud3b8\uc9c0\uc5d0\ub294 \uc885\uc774\ub85c \ub9cc\ub4e0 \ub808\uc774\uc2a4\uac00 \uc788\uc5c8\ub2e4\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\uc61b \uc5f0\uc560\ud3b8\uc9c0\uc5d0\ub294 \uc885\uc774\ub85c \ub9cc\ub4e0 \ub808\uc774\uc2a4\uac00 \uc788\uc5c8\ub2e4 \ubbf8\uad6d\uc758 \uce74\ub4dc \uc81c\uc791\uc790\uac00 \uafb8\ubbfc \uc791\uc740 \uaf43\ubc14\uad6c\ub2c8 \uaf43\uacfc \ucc9c, \uc885\uc774 \ub808\uc774\uc2a4\ub97c \uacb9\uccd0 \ub9cc\ub4e0 \ubc38\ub7f0\ud0c0\uc778 \uce74\ub4dc\uc758 \ubaa8\uc2b5\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc2e0\ud654\uc640 \ubbfc\uc18d \ubb38\ud654\uc640 \uc608\uc220 \ucd95\ud558 \uce74\ub4dc \ud55c \uc7a5\uc744 \uc5f4\uc5c8\ub294\ub370 \uc885\uc774\uaf43\uacfc \ucc9c \uc870\uac01\uc774 \uce35\uce35\uc774 \ubd99\uc5b4 \uc788\ub2e4\uba74 \uc5b4\ub5a8\uae4c. \ud3b8\uc9c0\ub97c \uc77d\uae30 \uc804\uc5d0 \uba3c\uc800 \uc791\uc740 \uacf5\uc608\ud488\uc744 \ud3bc\uccd0 \ubcf4\ub294 \ub290\ub08c\uc77c \uac83\uc774\ub2e4. 19\uc138\uae30 \ubc38\ub7f0\ud0c0\uc778 \uce74\ub4dc \uc911\uc5d0\ub294 \uc2e4\uc81c\ub85c \uadf8\ub7f0 \ubb3c\uac74\ub4e4\uc774 \uc788\uc5c8\ub2e4. \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc740 \ube45\ud1a0\ub9ac\uc544 \uc2dc\ub300\uc758 \ubc38\ub7f0\ud0c0\uc778 \uce74\ub4dc\ub97c 2\ucc9c \uc810 \ub118\uac8c \uc18c\uc7a5\ud55c \uceec\ub809\uc158\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc778\uc1c4\ub41c \ud55c \uc904\ub9cc \uc788\ub294 \uce74\ub4dc\uac00 \uc544\ub2c8\ub77c \uc885\uc774 \ub808\uc774\uc2a4\uc640 \ucc9c, \uc778\uc870 \uaf43\uc744 \ub354\ud55c \uce74\ub4dc\ub4e4\uc774 \ud568\uaed8 \uc788\ub2e4. \ub2f9\uc2dc\uc758 \uce74\ub4dc\ub294 \ud615\ud0dc\uac00 \ub2e4\uc591\ud588\ub2e4. \uc775\uc0b4\uc2a4\ub7ec\uc6b4 \uc8fc\uc81c\ub97c \uc778\uc1c4\ud55c \uac12\uc2fc \uce74\ub4dc\ub3c4 \uc788\uc5c8\uace0, \uc5ec\ub7ec \uc7ac\ub8cc\ub97c \ubd99\uc5ec \uc785\uccb4\uc801\uc73c\ub85c \ub9cc\ub4e0 \uce74\ub4dc\ub3c4 \uc788\uc5c8\ub2e4\uace0 \ud55c\ub2e4. \ub204\uad6c\ub098 \uac19\uc740 \ubaa8\uc591\uc73c\ub85c \ub9c8\uc74c\uc744 \uc804\ud588\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc885\uc774\ub97c \uc624\ub824 \ub9cc\ub4e0 \ub808\uc774\uc2a4\ub294 \ube48 \uacf5\uac04\uae4c\uc9c0 \uc7a5\uc2dd\uc774 \ub41c\ub2e4. \uaf43\uc744 \ud3c9\uba74\uc5d0 \uadf8\ub9ac\ub294 \ub300\uc2e0 \uc885\uc774\uc640 \ucc9c\uc73c\ub85c \ub9cc\ub4e4\uc5b4 \ubd99\uc774\uba74 \uce74\ub4dc\uc758 \ud45c\uba74\uc5d0\ub3c4 \ub192\ub0ae\uc774\uac00 \uc0dd\uae34\ub2e4. \ubc1b\ub294 \uc0ac\ub78c\uc740 \ubb38\uc7a5\ub9cc \uc77d\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uacb9\uce5c \uc7ac\ub8cc\ub97c \ud568\uaed8 \ubcf4\uac8c \ub41c\ub2e4. \ubbf8\uc220\uad00\uc758 \uc124\uba85\uc740 \ubbf8\uad6d \ub9e4\uc0ac\ucd94\uc138\uce20\uc8fc \uc6b0\uc2a4\ud130\uc5d0\uc11c \uc77c\ud55c \uce74\ub4dc \uc81c\uc791\uc790 \uc5d0\uc2a4\ud130 \ud558\uc6b8\ub79c\ub4dc\ub97c \uc18c\uac1c\ud55c\ub2e4. \uadf8\ub294 1849\ub144\uc5d0 \uc790\uc2e0\uc758 \ud68c\uc0ac\ub97c \uc5f4\uc5c8\uace0 \uc5ec\uc131\ub4e4\uc744 \uace0\uc6a9\ud588\ub2e4\uace0 \ud55c\ub2e4. \ud2b9\ud788 \uc778\uae30\ub97c \ub048 \uac83\uc740 \uba54\uc774 \ubc14\uc2a4\ucf13\uc774\ub77c\ub294 \uaf43\ubc14\uad6c\ub2c8 \ud615\ud0dc\uc758 \uce74\ub4dc\uc600\ub2e4. \uc885\uc774 \ub808\uc774\uc2a4 \uac00\uc6b4\ub370 \ucee4\ub2e4\ub780 \uc624\ub824 \ub0b8 \ubc14\uad6c\ub2c8\ub97c \ub450\uace0, \uc548\uc5d0\ub294 \uc885\uc774\uc640 \ucc9c\uc73c\ub85c \ub9cc\ub4e0 \uaf43\ub4e4\uc744 \ube7d\ube7d\ud558\uac8c \ubaa8\uc558\ub2e4. \ubbf8\uc220\uad00\uc740 \uc774\ub7f0 \uce74\ub4dc \ub450 \uc810\uc744 \uc18c\uc7a5\ud558\uace0 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc885\uc774 \ub808\uc774\uc2a4\ub294 \uc120\uc744 \ub0a8\uae30\ub294 \uac83\ub9cc \uc544\ub2c8\ub77c \uc0ac\uc774\ub97c \uc624\ub824 \ube44\uc6b0\uba74\uc11c \ubb34\ub2ac\ub97c \ub9cc\ub4e0\ub2e4. \ubc1d\uc740 \uba74\uc744 \ucc44\uc6b4 \uadf8\ub9bc\uacfc \ub2ec\ub9ac \ube48\uacf3 \ub108\uba38\ub85c \ub2e4\ub978 \uc7ac\ub8cc\uac00 \ubcf4\uc77c \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \uc5ec\ub7ec \uce35\uc774 \uacb9\uce58\uba74 \uc791\uc740 \uadf8\ub9bc\uc790\uc640 \ub192\ub0ae\uc774\uac00 \uc0dd\uae34\ub2e4. \uce74\ub4dc\ub294 \uc190\uc5d0 \ub4e4\uace0 \uc77d\ub294 \ubb38\uc7a5\uc774\uba74\uc11c \uacf5\uac04\uc744 \uac00\uc9c4 \uacf5\uc608\ud488\uc774 \ub41c\ub2e4. \uc774\ub7f0 \ud45c\uba74\uc744 \uc0ac\uc9c4\uc73c\ub85c \ubcfc \ub54c\uc5d0\ub294 \uaf43\ubd80\ud130 \ucc3e\uc740 \ub4a4 \uac00\uc7a5\uc790\ub9ac\ub97c \ub530\ub77c\uac00 \ubcf4\uc790. \ubb34\uc5c7\uc744 \uc778\uc1c4\ud588\uace0 \ubb34\uc5c7\uc744 \uc798\ub77c \ubd99\uc600\ub294\uc9c0 \uad6c\ubcc4\ud560 \uc218 \uc788\ub2e4\uba74 \uc81c\uc791 \uacfc\uc815\uc774 \uc870\uae08 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \ub290\uaef4\uc9c4\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc811\ucc29 \uc21c\uc11c\uc640 \uc791\uc5c5 \uc2dc\uac04\uc744 \ud655\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc644\uc131\ub41c \ud615\ud0dc\uc5d0\uc11c \ub0a8\uc740 \uce35\uc758 \uad00\uacc4\ub97c \uc0b4\ud53c\ub294 \uac83\uc774 \uba3c\uc800\ub2e4. \uc5ec\ub7ec \uc7ac\ub8cc\ub97c \ubd99\uc5ec \ud310\ub9e4\ud55c \uce74\ub4dc\ub294 \uc644\uc804\ud788 \uac1c\uc778\uc801\uc778 \ud3b8\uc9c0\uc640 \uae30\uc131 \uc0c1\ud488\uc758 \uacbd\uacc4\uc5d0 \ub193\uc778\ub2e4. \uac19\uc740 \ubaa8\uc591\uc744 \uc5ec\ub7ec \uc0ac\ub78c\uc774 \uad6c\uc785\ud560 \uc218 \uc788\uc5b4\ub3c4 \ubc1b\uc740 \uc0ac\ub78c\uc740 \uadf8\uac83\uc744 \uc790\uae30\uc5d0\uac8c \uc628 \ubb3c\uac74\uc73c\ub85c \uc77d\ub294\ub2e4. \uc0c1\ud488\uc73c\ub85c \uc81c\uc791\ud558\ub294 \uacfc\uc815\uacfc \uad00\uacc4 \uc548\uc5d0\uc11c \uc0ac\uc6a9\ud558\ub294 \uacbd\ud5d8\uc774 \uacb9\uce5c\ub2e4. \ub9c8\uc74c\uc744 \uc804\ud558\ub294 \uc77c\uc5d0 \ubb3c\uac74\uc744 \ub9cc\ub4dc\ub294 \uc0b0\uc5c5\uc774 \ucc38\uc5ec\ud55c \uac83\uc774\ub2e4. \ud558\uc6b8\ub79c\ub4dc\uac00 \ud68c\uc0ac\ub97c \uc138\uc6b0\uace0 \uc5ec\uc131\uc744 \uace0\uc6a9\ud588\ub2e4\ub294 \uc124\uba85\ub3c4 \uc774 \uad00\uc810\uc5d0\uc11c \ubcfc \uc218 \uc788\ub2e4. \ud55c \uc0ac\ub78c\uc774 \uc9d1\uc5d0\uc11c \uc6b0\uc5f0\ud788 \ub9cc\ub4e0 \uce74\ub4dc\ub9cc\uc758 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub77c \uc870\uc9c1\ud574\uc11c \uc5ec\ub7ec \uc7a5\uc744 \uc81c\uc791\ud55c \uc5ed\uc0ac\ub2e4. \ub2e4\ub9cc \uc774 \uc815\ubcf4\ub9cc\uc73c\ub85c \uace0\uc6a9\ud55c \ubaa8\ub4e0 \uc5ec\uc131\uc758 \uacbd\ud5d8\uc774\ub098 \uadfc\ubb34 \uc870\uac74\uc744 \ubbf8\ud654\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud655\uc778\ub41c \uc0ac\uc5c5\uc758 \ud615\ud0dc\uc640 \uc544\uc9c1 \uc54c\uc544\ubcf4\uc544\uc57c \ud560 \ub178\ub3d9\uc758 \uc5ed\uc0ac\ub97c \ub098\ub204\uc5b4 \uc77d\ub294\ub2e4. \uc885\uc774 \ub808\uc774\uc2a4 \uac00\uc6b4\ub370 \ucee4\ub2e4\ub780 \ubc14\uad6c\ub2c8 \ubaa8\uc591\uc744 \ub193\uace0 \uadf8 \uc548\uc5d0 \uaf43\uc744 \ucc44\uc6b4 \uad6c\uc131\uc740 \ud45c\uba74\uc744 \ub2e8\uc21c\ud55c \uae00\uc758 \ubc30\uacbd\uc73c\ub85c \ub450\uc9c0 \uc54a\ub294\ub2e4. \uaf43\uc744 \ubc14\uce58\ub294 \ubab8\uc9d3\uacfc \uc77d\uc744 \ubb38\uc7a5\uc774 \uac19\uc740 \uce74\ub4dc \uc548\uc5d0 \uc788\ub2e4. \uc2e4\uc81c \uaf43\ub2e4\ubc1c\uc744 \uadf8\ub300\ub85c \ubcf4\ub0b8 \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc \uc885\uc774\uc640 \ucc9c\uc774 \uadf8 \ud48d\uacbd\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uc7ac\ub8cc\uac00 \ub2e4\ub978 \uc120\ubb3c\uc758 \ud615\uc0c1\uc744 \ub9cc\ub4dc\ub294 \uc148\uc774\ub2e4. \ubbf8\uc220\uad00\uc774 \uc774\ub7f0 \uce74\ub4dc \ub450 \uc810\uc744 \uc18c\uc7a5\ud55c\ub2e4\ub294 \uc0ac\uc2e4\ub3c4 \ud765\ubbf8\ub86d\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uac1c\uc778\uc5d0\uac8c \ubcf4\ub0b4\uae30 \uc704\ud55c \uc0c1\ud488\uc774\uc5c8\uc9c0\ub9cc \ub098\uc911\uc5d0\ub294 \ub2f9\uc2dc\uc758 \uc81c\uc791\uacfc \ucde8\ud5a5\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc790\ub8cc\uac00 \ub41c\ub2e4. \uc0ac\uc801\uc778 \uae30\uc5b5\uacfc \uacf5\uc801\uc778 \uc218\uc9d1\uc774 \ubb3c\uac74\uc758 \uc11c\ub85c \ub2e4\ub978 \uc2dc\uac04\uc744 \ub9cc\ub4e0\ub2e4. \ud2b9\uc815 \uc218\uc2e0\uc790\uc758 \uc774\uc57c\uae30\uac00 \ud655\uc778\ub418\uc9c0 \uc54a\uc544\ub3c4 \ud615\ud0dc\uc640 \uc7ac\ub8cc\uc5d0\uc11c \uc77d\uc744 \ubd80\ubd84\uc740 \ub0a8\uc544 \uc788\ub2e4. \ube45\ud1a0\ub9ac\uc544 \uc2dc\ub300\ub77c\ub294 \uc774\ub984\uc744 \ub4e4\uc5c8\ub2e4\uace0 \uc5ec\uae30\uc758 \ubaa8\ub4e0 \uce74\ub4dc\uac00 \uc601\uad6d\uc5d0\uc11c \ub9cc\ub4e4\uc5b4\uc84c\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ud558\uc6b8\ub79c\ub4dc\uc758 \uc0ac\ub840\ub294 \ubbf8\uad6d \ub9e4\uc0ac\ucd94\uc138\uce20\uc8fc \uc6b0\uc2a4\ud130\uc758 \uc0ac\uc5c5\uc744 \uc774\uc57c\uae30\ud55c\ub2e4. \uc2dc\ub300\ub97c \ubd80\ub974\ub294 \uc774\ub984\uacfc \uac1c\ubcc4 \ubb3c\uac74\uc758 \uc81c\uc791\uc9c0\ub294 \uad6c\ubd84\ud574\uc11c \ud655\uc778\ud560 \uc815\ubcf4\ub2e4. \ube44\uc2b7\ud55c \ucde8\ud5a5\uc774 \uc5ec\ub7ec \uc9c0\uc5ed\uc744 \uc624\uac08 \uc218 \uc788\ub2e4\ub294 \uad00\uc810\ub3c4 \uc0dd\uae34\ub2e4. \ub530\ub77c\uc11c \ud55c \uc885\ub958\uc758 \uce74\ub4dc\uac00 \uadf8 \uc2dc\ub300\uc758 \ubaa8\ub4e0 \uc0ac\ub791 \ud45c\ud604\uc744 \ub300\ud45c\ud55c\ub2e4\uace0 \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc11c\ub85c \ub2e4\ub978 \ud615\uc2dd \uc911 \ud55c \uc0ac\ub840\ub85c \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc775\uc0b4\uc2a4\ub7ec\uc6b4 \uc778\uc1c4 \uce74\ub4dc\uc640 \uc815\uad50\ud55c \uc785\uccb4 \uce74\ub4dc\uac00 \ud568\uaed8 \uc788\uc5c8\ub2e4\ub294 \uc124\uba85\uc774 \ub2e4\uc591\ud568\uc744 \uc54c\ub824 \uc900\ub2e4. \uc885\uc774 \ub808\uc774\uc2a4\uc758 \uc791\uc740 \ud2c8\uc5d0\uc11c \uac1c\uc778\uc758 \ub9d0\uacfc \uc0c1\ud488, \uc7a5\uc778\uc758 \uc190\uacfc \uc2dc\ub300\uc758 \ucde8\ud5a5\uc774 \uc11c\ub85c \ub9cc\ub09c\ub2e4. \uc9c0\uae08\uc740 \uadf8\ub9bc\uacfc \ubb38\uad6c\ub97c \uace8\ub77c \uc804\uc1a1\ud558\uba74 \uba87 \ucd08 \uc548\uc5d0 \ub9c8\uc74c\uc744 \uc804\ud560 \uc218 \uc788\ub2e4. \uc774\ub7f0 \uce74\ub4dc\ub294 \uadf8 \uc8fc\ubcc0\uc744 \ub9cc\ub4dc\ub294 \ub370\uc5d0\ub3c4 \uc190\uc774 \ub9ce\uc774 \uac14\uc744 \uac83\uc774\ub2e4. \ub9d0 \ub300\uc2e0 \uc5b4\ub5a4 \uc7ac\ub8cc\ub97c \uace0\ub974\uace0 \uc5b4\ub5bb\uac8c \uacb9\ucce4\ub294\uc9c0\uac00 \uc778\uc0ac\uc5d0 \ub354\ud574\uc9c4\ub2e4. \uc61b \uce74\ub4dc\ub97c \ubaa8\ub450 \uac70\ucc3d\ud55c \uc0ac\ub791\uc758 \uc99d\uac70\ub85c \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc624\ub298\uc740 \uc885\uc774 \ub808\uc774\uc2a4\uc640 \uaf43\ubc14\uad6c\ub2c8\ub9cc \ub5a0\uc62c\ub824 \ubcf4\uc790. \ud55c \uc7a5\uc758 \uc885\uc774\ub97c \ub354 \uc608\uc058\uac8c \uafb8\uba70 \ub204\uad70\uac00\uc5d0\uac8c \uac74\ub124\uace0 \uc2f6\uc5c8\ub358 \ub9c8\uc74c\uc740 \uc9c0\uae08\uc758 \uce74\ub4dc \uace0\ub974\uae30\uc640\ub3c4 \ud06c\uac8c \uba40\uc9c0 \uc54a\ub2e4."}, {"id": "vigee-lebrun-mother-daughter", "title": "\ub538\uc744 \uc548\uc740 \uc790\ud654\uc0c1 \u2014 \ube44\uc81c \ub974 \ube0c\ub8c5\uc774 \ub0a8\uae34 \ub450 \uac00\uc9c0 \uc5bc\uad74", "summary": "\uc5c4\ub9c8\uc640 \uc544\uc774\uc758 \ubab8\uc9d3\uc744 \uc77d\uace0 \uc655\uc2e4\uc758 \ucd08\uc0c1\ud654\uac00\uc600\ub358 \uc5ec\uc131\uc758 \uc791\uc5c5\uacfc \uc774\ub3d9\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/vigee-lebrun-mother-daughter/index.html", "image": "../media/vigee-lebrun-mother-daughter.jpg", "alt": "\ube44\uc81c \ub974 \ube0c\ub8c5\uc774 \ub538\uc744 \ub450 \ud314\ub85c \uc548\uc740 \uc790\ud654\uc0c1. \ub450 \uc0ac\ub78c\uc758 \uc5bc\uad74\uc774 \uad00\uac1d\uc744 \ud5a5\ud569\ub2c8\ub2e4.", "text": "\ub538\uc744 \uc548\uc740 \uc790\ud654\uc0c1 \u2014 \ube44\uc81c \ub974 \ube0c\ub8c5\uc774 \ub0a8\uae34 \ub450 \uac00\uc9c0 \uc5bc\uad74 \uadf8\ub9bc \uc18d \uc5b4\uba38\ub2c8\ub97c \ub118\uc5b4, \uadf8\ub9bc\uc744 \uadf8\ub9b0 \uc0ac\ub78c\uc758 \uc0dd\uc560\uae4c\uc9c0 \uc5c4\ub9c8\uc640 \uc544\uc774\uc758 \ubab8\uc9d3\uc744 \uc77d\uace0 \uc655\uc2e4\uc758 \ucd08\uc0c1\ud654\uac00\uc600\ub358 \uc5ec\uc131\uc758 \uc791\uc5c5\uacfc \uc774\ub3d9\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \uc544\uc774\ub97c \ud488\uc5d0 \uc548\uc740 \uc5ec\uc778\uc774 \uc6b0\ub9ac\ub97c \ubc14\ub77c\ubcf8\ub2e4. \uc544\uc774\ub3c4 \uace0\uac1c\ub97c \ub3cc\ub824 \uad00\uac1d\uc744 \ud5a5\ud55c\ub2e4. \ub450 \ud314\uc740 \uc544\uc774\ub97c \ub2e8\ub2e8\ud788 \uac10\uc2f8\uace0 \uc637\uc758 \ub113\uc740 \uc8fc\ub984\uc740 \ub450 \ubab8\uc744 \ud558\ub098\ub85c \ubb36\ub294\ub2e4. \ucc98\uc74c \ubcf4\uba74 \ub2e4\uc815\ud55c \ubaa8\ub140\uc758 \ucd08\uc0c1\uc774\ub2e4. \uadf8\ub7f0\ub370 \uadf8\ub9bc \uc18d \uc5ec\uc778\uc740 \uc774 \uc791\ud488\uc744 \uadf8\ub9b0 \ud654\uac00 \uc790\uc2e0\uc774\ub2e4. \uc5d8\ub9ac\uc790\ubca0\ud2b8 \ub8e8\uc774\uc988 \ube44\uc81c \ub974 \ube0c\ub8c5\uc740 \uc790\uc2e0\uc744 \uadf8\ub9ac\uba74\uc11c \uc5b4\uba38\ub2c8\uc758 \ubaa8\uc2b5\ub3c4 \ud568\uaed8 \ub0a8\uacbc\ub2e4. \ubaa8\ub378\uacfc \uc791\uac00\uac00 \uac19\uc740 \uc0ac\ub78c\uc774\ub77c\ub294 \uc0ac\uc2e4\uc744 \uc54c\uace0 \ub098\uba74, \ud488 \uc548\uc758 \uad00\uacc4\ubfd0 \uc544\ub2c8\ub77c \uc774 \ud654\uba74\uc744 \ub9cc\ub4e4\uace0 \ub0b4\ub193\uc740 \uc0ac\ub78c\uc758 \uc0b6\uc5d0\ub3c4 \uad00\uc2ec\uc774 \uc0dd\uae34\ub2e4. \uba3c\uc800 \uc5b4\ub978\uacfc \uc544\uc774\uc758 \uc5bc\uad74\uc744 \uac01\uac01 \ubcf4\uace0 \uadf8 \uc0ac\uc774\uc758 \uac70\ub9ac\ub97c \uc0b4\ud3b4\ubcf4\uc790. \uc11c\ub85c \uae30\ub300\uace0 \uc788\uc73c\uba74\uc11c\ub3c4 \uc5bc\uad74\uc758 \ubc29\ud5a5\uc740 \uad00\uac1d\uc5d0\uac8c \uc5f4\ub824 \uc788\ub2e4. \ubcf4\ub294 \uc0ac\ub78c\uc740 \ub458\ub9cc\uc758 \uad00\uacc4\ub97c \ubc29\ud574\ud558\uae30\ubcf4\ub2e4 \uadf8 \uad00\uacc4\ub97c \ud568\uaed8 \ubcf4\ub3c4\ub85d \ucd08\ub300\ubc1b\ub294 \ub4ef\ud55c \ub290\ub08c\uc744 \ubc1b\uc744 \uc218 \uc788\ub2e4. \uadf8\ub2e4\uc74c\uc5d0\ub294 \uc5bc\uad74\uc5d0\uc11c \ud314\ub85c \ub208\uc744 \ub0b4\ub824 \ubcf4\uc790. \uc548\ucabd\uc73c\ub85c \ubaa8\uc774\ub294 \uc190\uacfc \ud314\uc774 \uc544\uc774\ub97c \ub458\ub7ec\uc2f8\uba70 \ud070 \ub369\uc5b4\ub9ac\ub97c \ub9cc\ub4e0\ub2e4. \ud45c\uc815\ub9cc \ub5bc\uc5b4 \ub193\uace0 \ubcfc \ub54c\ubcf4\ub2e4 \ubab8 \uc804\uccb4\uc758 \uc5f0\uacb0\uc774 \ubd84\uba85\ud574\uc9c4\ub2e4. \ub2e4\uc815\ud558\ub2e4\ub294 \uac10\uc815\uc774 \uc5bc\uad74\uc758 \ubbf8\uc18c \ud558\ub098\ub85c\ub9cc \ub9cc\ub4e4\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc1d\uc740 \uc0c1\uc758\uc640 \ubcf4\ub78f\ube5b \uc18c\ub9e4, \ub178\ub780\ube5b \uce58\ub9c8\uac00 \uc5b4\ub450\uc6b4 \ubc30\uacbd\uc5d0\uc11c \uad6c\ubcc4\ub41c\ub2e4. \uc544\uc774\uc758 \ubc1d\uc740 \uc637\uc740 \uc5b4\ub978\uc758 \ubab8 \uac00\uae4c\uc774\uc5d0 \ub193\uc774\uba74\uc11c \ub450 \uc0ac\ub78c\uc744 \ub354 \ubc00\uc811\ud558\uac8c \ubcf4\uc774\uac8c \ud55c\ub2e4. \uc0c9\uc740 \uc758\uc0c1\uc744 \uc124\uba85\ud558\ub294 \uc815\ubcf4\uc774\uba74\uc11c \ud654\uba74\uc758 \uad00\uacc4\ub97c \ub9cc\ub4dc\ub294 \uc7ac\ub8cc\uc774\uae30\ub3c4 \ud558\ub2e4. \uc8fc\ub984\uc744 \ubaa8\ub450 \uc138\ubc00\ud558\uac8c \ud574\ub3c5\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub113\uc740 \ucc9c\uc758 \ud750\ub984\uc774 \uc5b4\ub514\ub85c \ud5a5\ud558\ub294\uc9c0, \uc190\uacfc \uc544\uc774\uc758 \ubab8\uc774 \uc5b4\ub5a4 \uc0c9\uba74 \uc704\uc5d0 \ub193\uc774\ub294\uc9c0 \ub530\ub77c\uac00 \ubcf4\uc790. \ucd08\uc0c1\ud654\uc5d0\uc11c \uc778\ubb3c\uc758 \uc5bc\uad74\uc744 \uc774\ud574\ud558\ub294 \uc77c\uacfc \ubab8\uc744 \ub458\ub7ec\uc2fc \uc0ac\ubb3c\uc744 \ubcf4\ub294 \uc77c\uc740 \ub530\ub85c \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\ub2e4. \ud654\uac00\uac00 \uc790\uae30 \ubaa8\uc2b5\uc744 \uadf8\ub9ac\uba74 \uc6b0\ub9ac\ub294 \uadf8 \uc0ac\ub78c\uc758 \uc2e4\uc81c \uc5bc\uad74\uc744 \uc54c \uc218 \uc788\uc744 \uac83\uc774\ub77c \uae30\ub300\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc790\ud654\uc0c1\uc5d0\ub294 \uc5b4\ub5bb\uac8c \ubcf4\uc77c\uc9c0 \uace0\ub974\ub294 \uc120\ud0dd\ub3c4 \ub4e4\uc5b4\uac04\ub2e4. \uc5b4\ub5a4 \uc637\uc744 \uc785\uace0 \ub204\uad6c\uc640 \ud568\uaed8 \uc788\uc73c\uba70 \uad00\uac1d\uc744 \uc5b4\ub290 \ubc29\ud5a5\uc73c\ub85c \ubcfc \uac83\uc778\uac00. \ud654\uba74\uc740 \uadf8\ub7f0 \ud310\ub2e8\uc758 \uacb0\uacfc\ub2e4. \uc774 \uc791\ud488\uc5d0\uc11c \ud654\uac00\ub294 \ud63c\uc790 \ubd93\uc744 \ub4e0 \ubaa8\uc2b5 \ub300\uc2e0 \ub538\uacfc \ud568\uaed8 \ub098\ud0c0\ub09c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc791\uc5c5\ud558\ub294 \uc0ac\ub78c\uc758 \uc815\uccb4\uc131\uc774 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ud788\ub824 \uc5b4\uba38\ub2c8\uc758 \ubaa8\uc2b5\uc744 \uc774\ucc98\ub7fc \uad6c\uc131\ud574 \ubcf4\uc5ec \uc900 \uc8fc\uccb4\uac00 \ubc14\ub85c \ud654\uac00\ub77c\ub294 \uc0ac\uc2e4\uc774 \ub450 \uc5ed\ud560\uc744 \ud568\uaed8 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc5b4\ub290 \ud55c\ucabd\ub9cc\uc774 \uadf8 \uc0ac\ub78c\uc758 \uc9c4\uc9dc \ubaa8\uc2b5\uc774\ub77c\uace0 \uace0\ub97c \ud544\uc694\ub294 \uc5c6\ub2e4. \ube44\uc81c \ub974 \ube0c\ub8c5\uc740 1755\ub144 \ud30c\ub9ac\uc5d0\uc11c \ud0dc\uc5b4\ub0ac\uace0 \uc544\ubc84\uc9c0\ub3c4 \ud654\uac00\uc600\ub2e4. \ud68c\uace0\ub85d\uc5d0\ub294 \uadf8\ub9bc\uc744 \ubc30\uc6b0\ub358 \uc77c\uacfc \ucd08\uc0c1 \uc8fc\ubb38\uc744 \ubc1b\uc73c\uba70 \uc0dd\ud65c\uc744 \uafb8\ub9ac\ub358 \uacbd\ud5d8\uc774 \ub0a8\uc544 \uc788\ub2e4. \uc7ac\ub2a5 \uc788\ub294 \uc544\uc774\uac00 \uace7\ubc14\ub85c \uc720\uba85\ud55c \uc655\uc2e4 \ud654\uac00\uac00 \ub418\uc5c8\ub2e4\ub294 \ud55c \uc904 \uc0ac\uc774\uc5d0\ub294 \uc0ac\ub78c\uc744 \ub9cc\ub098\uace0 \uadf8\ub9bc\uc744 \uc644\uc131\ud558\uba70 \uc2e0\ub8b0\ub97c \uc5bb\ub294 \uc77c\uc774 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \uadf8\ub294 \ub9c8\ub9ac \uc559\ud22c\uc544\ub124\ud2b8\ub97c \ube44\ub86f\ud55c \uc655\uc2e4\uacfc \uadc0\uc871\uc758 \ucd08\uc0c1\uc744 \uadf8\ub838\uace0 \uc544\uce74\ub370\ubbf8\uc5d0\ub3c4 \ubc1b\uc544\ub4e4\uc5ec\uc84c\ub2e4. \ud68c\uace0\ub85d\uc740 \uadf8 \uacfc\uc815\uc5d0 \ub2e4\ub978 \ud654\uac00\ub4e4\uc758 \uc9c0\uc9c0\uc640 \ubc18\ub300\uac00 \uc788\uc5c8\ub2e4\uace0 \uc804\ud55c\ub2e4. \uc804\ubb38 \ud654\uac00\ub85c \uc778\uc815\ubc1b\ub294 \uc77c\uc740 \uc88b\uc740 \uadf8\ub9bc\uc744 \uadf8\ub9ac\ub294 \ub2a5\ub825\ub9cc\uc73c\ub85c \uc800\uc808\ub85c \ub05d\ub098\ub294 \ubb38\uc81c\uac00 \uc544\ub2c8\uc5c8\ub2e4. \uc655\uc2e4\uc758 \uc8fc\ubb38\uc740 \uc131\uacf5\uacfc \uba85\uc131\uc744 \uac00\uc838\ub2e4\uc8fc\uc5c8\uc9c0\ub9cc \uc815\uce58\uc801 \uaca9\ubcc0 \uc18d\uc5d0\uc11c\ub294 \uc704\ud5d8\ud55c \uad00\uacc4\uac00 \ub420 \uc218\ub3c4 \uc788\uc5c8\ub2e4. \ud504\ub791\uc2a4\ud601\uba85\uae30\uc758 \ubd88\uc548 \uc18d\uc5d0\uc11c \uadf8\ub294 \ub538\uc744 \ub370\ub9ac\uace0 \ud30c\ub9ac\ub97c \ub5a0\ub09c\ub2e4. \ud68c\uace0\ub85d\uc740 \ub2f9\uc2dc\uc758 \ub450\ub824\uc6c0\uacfc \uc774\ub3d9\uc744 \uc790\uc2e0\uc758 \uc2dc\uc120\uc73c\ub85c \uc790\uc138\ud788 \uc804\ud55c\ub2e4. \uc774 \uae30\ub85d\uc744 \uc77d\uc744 \ub54c\ub294 \uc791\uac00\uac00 \ud2b9\uc815 \uc0ac\ud68c\uc801 \uad00\uacc4\uc640 \uacbd\ud5d8\uc744 \uac00\uc9c4 \uc0ac\ub78c\uc774\uc5c8\ub2e4\ub294 \uc810\ub3c4 \uae30\uc5b5\ud558\uba74 \uc88b\ub2e4. \ud68c\uace0\ub85d\uc740 \uc911\uc694\ud55c \uc9c1\uc811 \uae30\ub85d\uc774\uc9c0\ub9cc \ud601\uba85 \uc804\uccb4\ub97c \uc911\ub9bd\uc801\uc73c\ub85c \uc815\ub9ac\ud55c \uad50\uacfc\uc11c\ub294 \uc544\ub2c8\ub2e4. \uc790\uae30 \uc0b6\uc744 \uc124\uba85\ud558\ub294 \ubaa9\uc18c\ub9ac\uc640 \ub354 \ub113\uc740 \uc5ed\uc0ac\ub97c \uac19\uc740 \uac83\uc73c\ub85c \ub9cc\ub4e4\uc9c0 \uc54a\uace0 \uc77d\uc744 \uc218 \uc788\ub2e4. \uc774\ud0c8\ub9ac\uc544\uc640 \uc624\uc2a4\ud2b8\ub9ac\uc544, \ub7ec\uc2dc\uc544 \ub4f1 \uc5ec\ub7ec \uacf3\uc744 \uac70\uce58\ub294 \ub3d9\uc548\uc5d0\ub3c4 \uadf8\ub294 \ucd08\uc0c1\ud654\ub97c \uadf8\ub838\ub2e4. \ub5a0\ub0a8\uc774 \uace7 \uc791\uc5c5\uc758 \ub05d\uc774 \ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc758\ub8b0\uc778\uc744 \ub9cc\ub098\uace0 \uc790\uc2e0\uc758 \ud3c9\ud310\uc744 \uc774\uc5b4 \uac00\ub294 \ub2a5\ub825\uc740 \uadf8\uc758 \uc0dd\uc560\uc5d0\uc11c \ud070 \ube44\uc911\uc744 \ucc28\uc9c0\ud55c\ub2e4. \uc608\uc220\uac00\uc758 \uc0b6\uc5d0 \uc774\ub3d9\uacfc \uc77c\uc758 \uc870\uac74\uc774 \ud568\uaed8 \ub4e4\uc5b4 \uc788\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \uc774\ub3d9\uc744 \ud654\ub824\ud55c \uc5ec\ud589\uc73c\ub85c\ub9cc \uc77d\uc744 \uc218\ub294 \uc5c6\ub2e4. \uc815\uce58\uc801 \ubd88\uc548\uacfc \uac00\uc871\uc758 \uc0ac\uc815, \ud0c0\uc9c0\uc758 \uc0dd\ud65c\ub3c4 \uadf8 \uc548\uc5d0 \uc788\ub2e4. \uc131\uacf5\ud55c \ud654\uac00\ub77c\ub294 \ub9d0\uacfc \ubd88\uc548\uc815\ud55c \uc2dc\uac04\uc744 \ubcf4\ub0b8 \uc0ac\ub78c\uc774\ub77c\ub294 \ub9d0\uc740 \ud55c \uc0dd\uc560 \uc548\uc5d0\uc11c \ud568\uaed8 \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4. \ub530\ub73b\ud55c \ud3ec\uc639\uc744 \ubcf4\uace0 \ub450 \uc0ac\ub78c\uc758 \uad00\uacc4\uac00 \ud3c9\uc0dd \uc5b8\uc81c\ub098 \uac19\uc558\uc744 \uac83\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \ud558\uc9c0\ub9cc \ud55c \uc7a5\uc758 \ucd08\uc0c1\uc740 \ud55c \uc0dd\uc560 \uc804\uccb4\uc758 \uae30\ub85d\uc774 \uc544\ub2c8\ub2e4. \ud68c\uace0\ub85d\uc5d0\ub294 \ub538\uc758 \uc131\uc7a5\uacfc \uacb0\ud63c, \uac00\uc871 \uad00\uacc4\uc758 \uc5b4\ub824\uc6c0\ub3c4 \ub4f1\uc7a5\ud55c\ub2e4. \ud654\uba74\uc758 \ub2e4\uc815\ud568\uc744 \uc0ac\uc2e4\uc774 \uc544\ub2cc \uac83\uc73c\ub85c \uc9c0\uc6b8 \ud544\uc694\ub3c4, \uadf8\uac83\uc73c\ub85c \ubaa8\ub4e0 \uc2dc\uac04\uc744 \uc124\uba85\ud560 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \uc624\ud788\ub824 \uadf8\ub9bc\uacfc \uc0dd\uc560\ub97c \ud568\uaed8 \ubcf4\uba74 \ucd08\uc0c1\ud654\uac00 \ubb34\uc5c7\uc744 \ubcf4\uc5ec \uc8fc\uace0 \ubb34\uc5c7\uc744 \ub0a8\uaca8 \ub450\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uadf8\ub9bc\uc744 \ubcf4\uace0 \ub9c8\uc74c\uc744 \ub290\ub080 \ub2e4\uc74c, \uadf8 \ub290\ub08c\uacfc \uc5ed\uc0ac\uc801 \uc0ac\uc2e4\uc774 \uc11c\ub85c \ub2e4\ub978 \uce35\uc704\uc784\uc744 \uc544\ub294 \uac83\uc740 \uac10\uc0c1\uc744 \ucc28\uac11\uac8c \ub9cc\ub4dc\ub294 \uc77c\uc774 \uc544\ub2c8\ub2e4. \ud55c \uc0ac\ub78c\uc744 \uc9c0\ub098\uce58\uac8c \ub2e8\uc21c\ud558\uac8c \ub9cc\ub4e4\uc9c0 \uc54a\ub294 \ubc29\ubc95\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 \ub3c4\ud310\uc740 \uc61b \ub8e8\ube0c\ub974 \ub3c4\ub85d\uc5d0 \uc218\ub85d\ub41c \uc791\uac00\uc640 \ub538\uc758 \uc790\ud654\uc0c1 \uc911 \ud55c \uc810\uc774\ub2e4. \ube44\uc2b7\ud55c \uc8fc\uc81c\uc758 \ub2e4\ub978 \uc790\ud654\uc0c1\uacfc\ub294 \uad6c\ubd84\ud574\uc57c \ud558\uba70, \uc61b \uc778\uc1c4\uc758 \uc0c9\uc774 \ud604\uc7ac\uc758 \uc2e4\ubb3c\uacfc \uc644\uc804\ud788 \uac19\ub2e4\uace0 \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c\ub294 \ub450 \uc5bc\uad74\uacfc \ud314, \uc637\uc774 \ub9cc\ub4dc\ub294 \uc804\uccb4 \uad00\uacc4\ub97c \uc0b4\ud3b4\ubcf4\uc558\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc544\uc774\ub97c \uc548\uc740 \uc5b4\uba38\ub2c8\uac00 \ubcf4\uc600\ub2e4\uba74, \ub2e4\uc2dc \ubcfc \ub54c\ub294 \uadf8 \uc7a5\uba74\uc744 \uc124\uacc4\ud558\uace0 \uc9c1\uc811 \uadf8\ub824 \ub2e4\ub978 \uc0ac\ub78c \uc55e\uc5d0 \ub0b4\ub193\uc740 \ud654\uac00\ub3c4 \ubcf4\uc77c \uac83\uc774\ub2e4. \ub2e4\uc815\ud55c \uad00\uacc4\uc640 \uc804\ubb38\uc801\uc778 \uc791\uc5c5\uc740 \ud55c \ud654\uba74 \uc548\uc5d0 \ud568\uaed8 \uc788\ub2e4. \ube44\uc81c \ub974 \ube0c\ub8c5\uc758 \uc790\ud654\uc0c1\uc740 \uc0ac\ub78c\uc744 \ud55c \uac00\uc9c0 \uc5ed\ud560\ub85c\ub9cc \uae30\uc5b5\ud558\uc9c0 \uc54a\ub3c4\ub85d \uc2dc\uc120\uc744 \ub113\ud600 \uc900\ub2e4."}, {"id": "vivaldi-four-seasons-spring", "title": "\ube44\ubc1c\ub514 \uc0ac\uacc4 \u2014 \uc0c8\uc18c\ub9ac\uc5d0\uc11c \ud3ed\ud48d\uacfc \uaca8\uc6b8\uc758 \ubd88\uac00\uae4c\uc9c0", "summary": "\ubd04\u00b7\uc5ec\ub984\u00b7\uac00\uc744\u00b7\uaca8\uc6b8\uc758 \uc2dc\uc640 \uc545\uc7a5\ubcc4 \uc7a5\uba74\uc744 \ub530\ub77c \ube44\ubc1c\ub514\uc758 \ub124 \ud611\uc8fc\uace1\uc744 \ub4e3\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc74c\uc545", "categories": ["arts"], "url": "stories/vivaldi-four-seasons-spring/index.html", "image": "../media/vivaldi-four-seasons-spring-scene-20261030.png", "alt": "\ucc3d\uac00\uc758 \ubc14\uc774\uc62c\ub9b0\uacfc \ud65c \ub108\uba38\ub85c \ubd04\uaf43\u00b7\uc5ec\ub984\uc758 \ube44\u00b7\uac00\uc744 \ub2e8\ud48d\u00b7\uaca8\uc6b8 \ub208\uc774 \uc774\uc5b4\uc9c0\ub294 \uc2dc\uc801\uc778 \uc0c1\uc0c1 \ud48d\uacbd.", "text": "\ube44\ubc1c\ub514 \uc0ac\uacc4 \u2014 \uc0c8\uc18c\ub9ac\uc5d0\uc11c \ud3ed\ud48d\uacfc \uaca8\uc6b8\uc758 \ubd88\uac00\uae4c\uc9c0 \uc5f4\ub450 \uc545\uc7a5 \uc18d \ub124 \uacc4\uc808\uc744 \uc2dc\uc640 \ud568\uaed8 \ub4e3\ub294 \uae38\uc7a1\uc774 \ubd04\u00b7\uc5ec\ub984\u00b7\uac00\uc744\u00b7\uaca8\uc6b8\uc758 \uc2dc\uc640 \uc545\uc7a5\ubcc4 \uc7a5\uba74\uc744 \ub530\ub77c \ube44\ubc1c\ub514\uc758 \ub124 \ud611\uc8fc\uace1\uc744 \ub4e3\uc2b5\ub2c8\ub2e4. \uc74c\uc545 \ubb38\ud654\uc640 \uc608\uc220 \ubd04\uc5d0\ub294 \uc0c8\uac00 \uc6b8\uace0, \uc5ec\ub984\uc5d0\ub294 \ud3ed\ud48d\uc774 \ubab0\ub824\uc624\uba70, \uac00\uc744\uc5d0\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc220\uc744 \ub9c8\uc2dc\uace0 \ucda4\ucd98\ub2e4. \uaca8\uc6b8\uc5d0\ub294 \ucd94\uc704\uc5d0 \uc774\ub97c \ub5a8\ub2e4\uac00 \ub530\ub73b\ud55c \ubd88\uac00\ub85c \ub4e4\uc5b4\uac04\ub2e4. \ube44\ubc1c\ub514\uc758 \u300a\uc0ac\uacc4\u300b\ub294 \uc544\ub984\ub2e4\uc6b4 \uc790\uc5f0 \ud48d\uacbd\ub9cc \ubaa8\uc544 \ub193\uc740 \uc74c\uc545\uc774 \uc544\ub2c8\ub2e4. \uadf8 \uacc4\uc808\uc744 \uc0b4\uc544\uac00\ub294 \ubab8\uacfc \uc0dd\ud65c\uc774 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4. \uacc4\uc808\uc758 \uc81c\ubaa9\uc744 \uc54c\uace0 \ub4e3\ub294 \uac83\uc5d0\uc11c \ud55c \uac78\uc74c \ub354 \ub098\uc544\uac00, \uac01 \uace1\uacfc \ud568\uaed8 \uc804\ud574\uc9c0\ub294 \uc9e7\uc740 \uc2dc\ub97c \uae38\uc7a1\uc774\ub85c \uc0bc\uc544 \ubcf4\uc790. \uc18c\ub9ac\uc758 \ubaa8\ub4e0 \uc815\ub2f5\uc744 \ub9de\ud788\ub294 \uacf5\ubd80\uac00 \uc544\ub2c8\ub77c, \uc775\uc219\ud55c \uc120\uc728 \uc18d\uc5d0\uc11c \uc7a5\uba74\uc744 \uc870\uae08 \ub354 \ubc1c\uacac\ud558\ub294 \uac10\uc0c1\uc774\ub2e4. \ubd04\u00b7\uc5ec\ub984\u00b7\uac00\uc744\u00b7\uaca8\uc6b8\uc740 \uac01\uac01 \ub3c5\ub9bd\ub41c \ubc14\uc774\uc62c\ub9b0 \ud611\uc8fc\uace1\uc774\ub2e4. \uc791\ud488\ubc88\ud638 8\uc758 \uccab \ub124 \uace1\uc774\uba70, \uc545\ubcf4 \uc790\ub8cc\ub294 1725\ub144\uc744 \uc81c\uc2dc\ud55c\ub2e4. \uac01 \ud611\uc8fc\uace1\uc740 \uc138 \uc545\uc7a5\uc73c\ub85c \uc774\ub8e8\uc5b4\uc838 \uc788\uc73c\ubbc0\ub85c \ubaa8\ub450 \ud569\ud558\uba74 \uc5f4\ub450 \uc545\uc7a5\uc774\ub2e4. \ubcf4\ud1b5 \ube60\ub978 \ud750\ub984, \ub290\ub9b0 \ud750\ub984, \ub2e4\uc2dc \ube60\ub978 \ud750\ub984\uc744 \ub530\ub77c \ud55c \uacc4\uc808\uc774 \ud3bc\uccd0\uc9c4\ub2e4. \ud611\uc8fc\uace1\uc5d0\uc11c\ub294 \ub3c5\uc8fc \uc545\uae30\uc640 \ud569\uc8fc\uac00 \uc11c\ub85c \uad00\uacc4\ub97c \ub9fa\ub294\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubc14\uc774\uc62c\ub9b0 \ub3c5\uc8fc\uc758 \ub0a0\ub835\ud55c \uc6c0\uc9c1\uc784\uacfc \uc5ec\ub7ec \ud604\uc545\uae30\uac00 \ud568\uaed8 \ub9cc\ub4dc\ub294 \ub369\uc5b4\ub9ac\ub97c \ubc88\uac08\uc544 \ub4e4\uc5b4 \ubcf4\uc790. \ud63c\uc790 \ub098\uc11c\ub294 \uc18c\ub9ac\uc640 \ud568\uaed8 \ub418\ub3cc\uc544\uc624\ub294 \uc18c\ub9ac\uc758 \ucc28\uc774\ub97c \uc54c\uc544\ucc28\ub9ac\uae30\ub9cc \ud574\ub3c4 \uc74c\uc545\uc758 \uae38\uc774 \uaf64 \ubd84\uba85\ud574\uc9c4\ub2e4. \ub124 \uacc4\uc808\uc5d0\ub294 \uc18c\ub124\ud2b8\ub77c\ub294 \ud615\uc2dd\uc758 \uc9e7\uc740 \uc2dc\uac00 \ud568\uaed8 \uc804\ud574\uc9c0\uace0, \ud655\uc778\ud55c \uc545\ubcf4 \uc790\ub8cc\ub294 \uc2dc\uc758 \uad6c\uc808\uc744 \uc545\uc7a5\uc758 \ud2b9\uc815 \ubd80\ubd84\uc5d0 \ubc30\uce58\ud55c\ub2e4. \uc0c8, \ubc14\ub78c, \ucc9c\ub465, \ucda4, \uc5bc\uc74c\uae38 \uac19\uc740 \uc7a5\uba74\uc774 \ub9c9\uc5f0\ud55c \uc0c1\uc0c1\ub9cc\uc740 \uc544\ub2c8\ub77c\ub294 \ub73b\uc774\ub2e4. \uc74c\uc545\uacfc \uc5f0\uacb0\ub41c \uae00\uc758 \ub2e8\uc11c\uac00 \uc2e4\uc81c\ub85c \ub0a8\uc544 \uc788\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \uc2dc\ub97c \ube44\ubc1c\ub514\uac00 \uc9c1\uc811 \uc9c0\uc5c8\ub2e4\uace0 \uc5ec\uae30\uc11c \ud655\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc774\ubc88\uc5d0 \ud655\uc778\ud55c \uadfc\uac70\ub294 \uc2dc\uc758 \ub0b4\uc6a9\uacfc \uc545\ubcf4 \uc548\uc758 \ub300\uc751\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \ubc14\uc774\uc62c\ub9b0\uacfc \uc0ac\uacc4\uc808\uc758 \ud48d\uacbd\uc744 \uc2dc\uc801\uc73c\ub85c \uc5f0\uacb0\ud55c AI \uc0bd\ud654\ub2e4. \ud2b9\uc815 \uacf5\uc5f0\uc774\ub098 \uc2e4\uc81c \ud55c \uc7a5\uc18c\ub97c \uc7ac\ud604\ud55c \uadf8\ub9bc\uc740 \uc544\ub2c8\ub2e4. \ub124 \uacc4\uc808\uc758 \uc774\uc57c\uae30\ub294 \uc544\ub798\uc5d0\uc11c \ucc28\ub840\ub85c \ub9cc\ub098 \ubcf4\uc790. \uccab \uc545\uc7a5\uc758 \uc2dc\ub294 \ubd04\uc758 \ub3c4\ucc29\uacfc \uc0c8\ub4e4\uc758 \ub178\ub798, \uc2dc\ub0c7\ubb3c\uc758 \ud750\ub984\uc73c\ub85c \uc2dc\uc791\ud55c\ub2e4. \ubc14\uc774\uc62c\ub9b0\uc758 \uc9e7\uc740 \uc6c0\uc9c1\uc784\uc744 \uc0c8\uc18c\ub9ac\ucc98\ub7fc \ub4e4\uc5b4 \ubcf4\uace0, \ud569\uc8fc\uac00 \ub3cc\uc544\uc62c \ub54c\ub9c8\ub2e4 \ubc1d\uc740 \ubc14\uae65 \ud48d\uacbd\uc774 \ub2e4\uc2dc \uc5f4\ub9ac\ub294 \ub290\ub08c\uc744 \ubc1b\uc544\ub3c4 \uc88b\ub2e4. \uc774\ub54c \ubc18\ubcf5\ub418\ub294 \ubd80\ubd84\uc740 \uc0c8\ub85c\uc6b4 \uc7a5\uba74 \uc0ac\uc774\uc5d0\uc11c \uae38\uc744 \uc783\uc9c0 \uc54a\uac8c \ud574 \uc8fc\ub294 \ud45c\uc9c0\ucc98\ub7fc \ub4e4\uc744 \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \ud558\ub298\uc740 \uacc4\uc18d \ub9d1\uc9c0 \uc54a\ub2e4. \uc2dc\uc5d0\ub294 \uad6c\ub984\uacfc \ubc88\uac1c, \ucc9c\ub465\uc774 \ub098\ud0c0\ub098\uace0 \uadf8 \ub4a4 \uc0c8\ub4e4\uc774 \ub2e4\uc2dc \ub178\ub798\ud55c\ub2e4. \uadf8\ub798\uc11c \uac11\uc790\uae30 \uc74c\uc545\uc774 \uae34\ubc15\ud574\uc9c8 \ub54c \u2018\ubd04\uc778\ub370 \uc65c \uc774\ub807\uac8c \uac70\uce60\uae4c\u2019\ub77c\uace0 \uc0dd\uac01\ud558\uae30\ubcf4\ub2e4 \ud55c \uacc4\uc808 \uc548\uc5d0\ub3c4 \ub0a0\uc528\uc758 \ubcc0\ud654\uac00 \uc788\ub2e4\ub294 \uc810\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ubc1d\uc740 \uc7a5\uba74\uc774 \ub3cc\uc544\uc62c \ub54c\uc758 \ubc18\uac00\uc6c0\ub3c4 \ub354 \ucee4\uc9c4\ub2e4. \ub458\uc9f8 \uc545\uc7a5\uc758 \uc2dc\uc5d0\ub294 \ud480\uacfc \ub098\ubb47\uc78e\uc758 \uc6c0\uc9c1\uc784, \uc7a0\ub4e0 \ubaa9\ub3d9, \uacc1\uc758 \uac1c\uac00 \ub4f1\uc7a5\ud55c\ub2e4. \ud070 \uc0ac\uac74\uc774 \ubc8c\uc5b4\uc9c0\ub358 \ubc14\uae65\uc5d0\uc11c \ud55c \uc0ac\ub78c\uc758 \ud734\uc2dd\uc73c\ub85c \uc2dc\uc120\uc774 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \uc74c\uc545\uc744 \ub4e4\uc744 \ub54c\ub3c4 \uacc4\uc18d \uc0c8 \uc7a5\uba74\uc744 \ucc3e\uc73c\ub824 \ud558\uae30\ubcf4\ub2e4 \uc704\ucabd \uc120\uc728\uacfc \uadf8 \uc544\ub798 \uc774\uc5b4\uc9c0\ub294 \uc18c\ub9ac\uc758 \uce35\uc744 \ucc28\ubd84\ud788 \ub4e4\uc5b4 \ubcf4\uc790. \uc14b\uc9f8 \uc545\uc7a5\uc740 \ubaa9\ub3d9\ub4e4\uacfc \ub2d8\ud504\ub4e4\uc758 \ubaa9\uac00\uc801\uc778 \ucda4\uc73c\ub85c \uc774\uc5b4\uc9c4\ub2e4. \ubd04\uc740 \uc790\uc5f0\uc774 \uae68\uc5b4\ub098\ub294 \uc7a5\uba74\uc5d0\uc11c \uc2dc\uc791\ud574 \uc26c\ub294 \uc2dc\uac04\uacfc \uc0ac\ub78c\ub4e4\uc758 \uc6c0\uc9c1\uc784\uae4c\uc9c0 \ud488\ub294\ub2e4. \uccab \uc545\uc7a5\uc758 \uc720\uba85\ud55c \ubd80\ubd84\ub9cc \ub4e3\uace0 \uba48\ucd94\uba74 \uc774 \uacc4\uc808\uc758 \ud558\ub8e8 \uac00\uc6b4\ub370 \uc0c1\ub2f9\ud55c \ubd80\ubd84\uc744 \ub193\uce58\ub294 \uc148\uc774\ub2e4. \uc5ec\ub984\uc758 \uc2dc\ub294 \ub728\uac70\uc6b4 \ud587\ube5b \uc544\ub798 \uc0ac\ub78c\uacfc \uac00\ucd95\uc774 \uc9c0\uce58\ub294 \ubaa8\uc2b5\uc73c\ub85c \uc2dc\uc791\ud55c\ub2e4. \uc0c8\ub4e4\uc758 \uc18c\ub9ac\uc640 \ubd80\ub4dc\ub7ec\uc6b4 \ubc14\ub78c\uc774 \ub098\ud0c0\ub098\uc9c0\ub9cc \uac11\uc791\uc2a4\ub7ec\uc6b4 \ubd81\ud48d\uc774 \ubd88\uace0, \ubaa9\ub3d9\uc740 \ub2e4\uac00\uc62c \ud3ed\ud48d\uc744 \uac71\uc815\ud55c\ub2e4. \uc624\ub298 \uc6b0\ub9ac\uac00 \uc5ec\ub984\uc774\ub77c\ub294 \ub9d0\uc5d0\uc11c \ub5a0\uc62c\ub9ac\ub294 \ud574\ubcc0\uc758 \ud734\uac00\uc640\ub294 \ub2e4\ub978 \uc0dd\ud65c\uc758 \uac10\uac01\uc774\ub2e4. \ub290\ub9b0 \ub458\uc9f8 \uc545\uc7a5\uc5d0\uc11c\ub3c4 \uc644\uc804\ud788 \uc274 \uc218\ub294 \uc5c6\ub2e4. \ubc88\uac1c\uc640 \ucc9c\ub465\uc5d0 \ub300\ud55c \ub450\ub824\uc6c0, \ud30c\ub9ac\uc640 \ubc8c\ub808\ub4e4\uc774 \ud734\uc2dd\uc744 \ubc29\ud574\ud55c\ub2e4. \uc14b\uc9f8 \uc545\uc7a5\uc5d0\uc11c\ub294 \uacb0\uad6d \ud3ed\ud48d\uc774 \ud130\uc9c0\uace0 \uc6b0\ubc15\uc774 \uace1\uc2dd\uc744 \ud574\uce5c\ub2e4. \ube60\ub978 \uc74c\ub4e4\uc774 \uc3df\uc544\uc9c0\ub294 \uc21c\uac04\uc758 \ud654\ub824\ud568\uacfc \ud568\uaed8, \uadf8 \ub0a0\uc528\ub97c \uacac\ub38c\uc57c \ud558\ub294 \uc0ac\ub78c\uc758 \uac71\uc815\uc744 \uc0dd\uac01\ud558\uba74 \uc74c\uc545\uc758 \ud45c\uc815\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uac00\uc744\uc740 \uc218\ud655\uc744 \uae30\ubed0\ud558\ub294 \ub178\ub798\uc640 \ucda4\uc73c\ub85c \uc2dc\uc791\ud55c\ub2e4. \uc220\uc5d0 \ucde8\ud55c \uc0ac\ub78c\ub4e4\uc774 \uc7a0\uc5d0 \ube60\uc838\ub4dc\ub294 \ubaa8\uc2b5\ub3c4 \uc2dc\uc5d0 \ub098\uc628\ub2e4. \uc74c\uc545\uc758 \ud65c\uae30\uc640 \uc6c0\uc9c1\uc784\uc774 \uac00\ub77c\uc549\ub294 \ubd80\ubd84\uc744 \ubc88\uac08\uc544 \ub4e4\uc73c\uba74 \ub2e8\uc9c0 \u2018\ud48d\uc694\ub85c\uc6b4 \uac00\uc744\u2019\uc774\ub77c\ub294 \ud55c \ub2e8\uc5b4\ubcf4\ub2e4 \uad6c\uccb4\uc801\uc778 \uc0dd\ud65c \uc7a5\uba74\uc774 \ub5a0\uc624\ub978\ub2e4. \ub458\uc9f8 \uc545\uc7a5\uc5d0\ub294 \uc7a0\uc758 \uc2dc\uac04\uc774 \uc774\uc5b4\uc9c0\uace0, \uc14b\uc9f8\uc5d0\uc11c\ub294 \uc0c8\ubcbd\uc758 \uc0ac\ub0e5\uc774 \uc2dc\uc791\ub41c\ub2e4. \ubfd4\ud53c\ub9ac\uc640 \ucd1d, \uac1c\uc640 \ucad3\uae30\ub294 \uc9d0\uc2b9\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \ub9c8\uc9c0\ub9c9\uae4c\uc9c0 \ud3c9\ud654\ub85c\uc6b4 \uc804\uc6d0 \ud48d\uacbd\ub9cc \uc774\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ub298\uc758 \uac10\uac01\uc73c\ub85c \ubd88\ud3b8\ud558\uac8c \ub290\ub084 \uc218 \uc788\ub294 \uc7a5\uba74\ub3c4 \ud3ec\ud568\ud574, \ub2f9\uc2dc\uc758 \uacc4\uc808 \uc0dd\ud65c\uc744 \ub2f4\uc740 \uc74c\uc545\uc73c\ub85c \ub9cc\ub098\uba74 \uc88b\ub2e4. \uccab \uc545\uc7a5\uc758 \uc2dc\uc5d0\ub294 \ucc28\uac00\uc6b4 \ubc14\ub78c \uc18d\uc5d0\uc11c \ubab8\uc744 \ub5a8\uace0 \ubc1c\uc744 \uad6c\ub974\uba70 \uc774\ub97c \ub5a0\ub294 \uc0ac\ub78c\uc774 \ub098\uc628\ub2e4. \ubc18\ubcf5\ub418\ub294 \uc9e7\uc740 \uc18c\ub9ac\ub97c \ub4e4\uc73c\uba74 \ucd94\uc704\uc5d0 \uc6c0\uce20\ub7ec\ub4e0 \ubab8\uc758 \uc6c0\uc9c1\uc784\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uc7a5\uba74\uc744 \uc54c\uace0 \ub098\uba74 \uaca8\uc6b8\uc774 \ub208\uc758 \uc544\ub984\ub2e4\uc6c0\ub9cc\uc740 \uc544\ub2c8\ub77c\ub294 \uc0ac\uc2e4\uc774 \uadc0\ub85c\ub3c4 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \ub458\uc9f8 \uc545\uc7a5\uc5d0\uc11c\ub294 \ubd88\uac00\uc5d0\uc11c \uc870\uc6a9\ud558\uace0 \ud3b8\uc548\ud55c \uc2dc\uac04\uc744 \ubcf4\ub0b4\ub294 \ubc18\uba74 \ubc16\uc5d0\ub294 \ube44\uac00 \ub0b4\ub9b0\ub2e4. \uc2e4\ub0b4\uc640 \uc2e4\uc678\uc758 \ub300\ube44\uac00 \uc774 \uc9e7\uc740 \uc545\uc7a5\uc758 \uc990\uac70\uc6c0\uc774\ub2e4. \uc14b\uc9f8\uc5d0\uc11c\ub294 \uc5bc\uc74c \uc704\ub97c \uc870\uc2ec\ud788 \uac77\ub2e4\uac00 \ubbf8\ub044\ub7ec\uc9c0\uace0, \ub2e4\uc2dc \ub2ec\ub9ac\ub2e4\uac00 \uc5bc\uc74c\uc774 \uac08\ub77c\uc9c0\uba70 \ubc14\ub78c\ub4e4\uc774 \ub9de\uc120\ub2e4. \uaca8\uc6b8\uc740 \uac00\ub9cc\ud788 \uc5bc\uc5b4\ubd99\uc740 \ud48d\uacbd\uc774 \uc544\ub2c8\ub77c \uc870\uc2ec\uc2a4\ub7ec\uc6b4 \uac78\uc74c\uacfc \uac11\uc791\uc2a4\ub7ec\uc6b4 \uc6c0\uc9c1\uc784\uc73c\ub85c \ub05d\uc744 \ud5a5\ud55c\ub2e4. \ubaa8\ub4e0 \uc74c\uc774 \uc5b4\ub5a4 \uc0ac\ubb3c \ud558\ub098\uc640 \uc815\ud655\ud788 \ub300\uc751\ud55c\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uac10\uc0c1\uc774 \ud034\uc988\uac00 \ub418\uae30 \uc27d\ub2e4. \uba3c\uc800 \ub3c5\uc8fc\uc640 \ud569\uc8fc\uc758 \ucc28\uc774, \ube60\ub974\uae30\uc758 \ubcc0\ud654, \uac19\uc740 \ubd80\ubd84\uc774 \ub418\ub3cc\uc544\uc624\ub294 \uc21c\uac04\uc744 \ub4e4\uc5b4 \ubcf4\uc790. \uadf8 \uc704\uc5d0 \uc2dc\uc758 \uc7a5\uba74\uc744 \uc5b9\uc73c\uba74 \uc74c\uc545\uc744 \ub4e3\ub294 \uae38\uc7a1\uc774\uac00 \uc0dd\uae34\ub2e4. \ube44\ubc1c\ub514\ub294 1678\ub144\uc5d0 \ud0dc\uc5b4\ub098 1741\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub09c \uc791\uace1\uac00\ub2e4. \u300a\uc0ac\uacc4\u300b\uc758 \uc7ac\ubbf8\ub294 \uba3c \uc2dc\ub300\uc758 \uc74c\uc545\uc774\ub77c\ub294 \uc0ac\uc2e4\uc5d0\ub9cc \uc788\uc9c0 \uc54a\ub2e4. \uc0c8\uc18c\ub9ac\ub97c \ubc18\uae30\uace0 \ud3ed\ud48d\uc744 \uac71\uc815\ud558\uba70 \ucd94\uc704\ub97c \ud53c\ud574 \ubd88\uac00\uc5d0 \uc549\ub294 \ubab8\uc758 \uacbd\ud5d8\uc740 \uc624\ub298\uc758 \uc6b0\ub9ac\uc5d0\uac8c\ub3c4 \ub0af\uc124\uc9c0 \uc54a\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ubd04 \ud558\ub098\ub97c, \ub2e4\uc74c\uc5d0\ub294 \uac00\uc7a5 \uad81\uae08\ud55c \uacc4\uc808\uc744 \uace8\ub77c \ub4e4\uc5b4\ub3c4 \ucda9\ubd84\ud558\ub2e4. \uc5f4\ub450 \uc545\uc7a5\uc744 \ud55c\uaebc\ubc88\uc5d0 \uacf5\ubd80\ud574\uc57c \uc2dc\uc791\ud560 \uc218 \uc788\ub294 \uc74c\uc545\uc740 \uc544\ub2c8\ub2e4."}, {"id": "vulcan-forge-apollo-and-interrupted-work", "title": "\ubd88\uce74\ub204\uc2a4\uc758 \ub300\uc7a5\uac04 \u2014 \uc2e0\uc758 \uc18c\uc2dd\uc774 \ub9dd\uce58\uc9c8\uc744 \uba48\ucd98 \uc21c\uac04", "summary": "\uc544\ud3f4\ub860\uc758 \uc18c\uc2dd\uc5d0 \ub300\uc7a5\uac04 \uc0ac\ub78c\ub4e4\uc774 \ubc18\uc751\ud558\ub294 \uc21c\uac04\uc744 \ub3c4\uad6c\uc640 \uc190, \uc2dc\uc120\uc73c\ub85c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/vulcan-forge-apollo-and-interrupted-work/index.html", "image": "../media/vulcan-forge-apollo-and-interrupted-work.jpg", "alt": "\ubca8\ub77c\uc2a4\ucf00\uc2a4\uc758 \ubd88\uce74\ub204\uc2a4\uc758 \ub300\uc7a5\uac04\uc5d0\uc11c \uc544\ud3f4\ub860\uc744 \ub3cc\uc544\ubcf4\ub294 \uc791\uc5c5\uc790\ub4e4\uacfc \ub3c4\uad6c\uc758 \uc2e4\uc81c \uc791\ud488 \ub3c4\ud310", "text": "\ubd88\uce74\ub204\uc2a4\uc758 \ub300\uc7a5\uac04 \u2014 \uc2e0\uc758 \uc18c\uc2dd\uc774 \ub9dd\uce58\uc9c8\uc744 \uba48\ucd98 \uc21c\uac04 \ub9d0\ud558\ub294 \uc190\uacfc \uba48\ucd98 \ub3c4\uad6c, \uc2dc\uc120\uc73c\ub85c \uc77d\ub294 \uc2e0\ud654\uc758 \ud55c\uc21c\uac04 \uc544\ud3f4\ub860\uc758 \uc18c\uc2dd\uc5d0 \ub300\uc7a5\uac04 \uc0ac\ub78c\ub4e4\uc774 \ubc18\uc751\ud558\ub294 \uc21c\uac04\uc744 \ub3c4\uad6c\uc640 \uc190, \uc2dc\uc120\uc73c\ub85c \uc77d\uc2b5\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \ubca8\ub77c\uc2a4\ucf00\uc2a4\uc758 \u300c\ubd88\uce74\ub204\uc2a4\uc758 \ub300\uc7a5\uac04\u300d\uc740 \uc2e0\ud654\uc758 \uc7a5\uba74\uc778\ub370\ub3c4 \uc0ac\ub78c\ub4e4\uc758 \uc791\uc5c5\uc7a5\uc744 \ub4e4\uc5ec\ub2e4\ubcf4\ub294 \ub4ef\ud558\ub2e4. \ub204\uad70\uac00\ub294 \ub9dd\uce58\ub97c \ub4e4\uace0 \ub204\uad70\uac00\ub294 \ub728\uac70\uc6b4 \uae08\uc18d\uc744 \ub2e4\ub8e8\ub2e4\uac00, \uac11\uc790\uae30 \ucc3e\uc544\uc628 \uc190\ub2d8\uc5d0\uac8c \uc2dc\uc120\uc744 \ub3cc\ub9b0\ub2e4. \uc774 \uadf8\ub9bc\uc758 \uc0ac\uac74\uc740 \ubc88\uac1c\ub098 \uc804\ud22c\ubcf4\ub2e4 \ub9d0 \ud55c\ub9c8\ub514\uc5d0 \uac00\uae5d\ub2e4. \uc18c\uc2dd\uc774 \uc804\ud574\uc9c0\ub294 \uc21c\uac04 \ubab8\uc774 \uc5b4\ub5bb\uac8c \ub2ec\ub77c\uc9c0\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \ub85c\ub9c8 \uc2e0\ud654\uc5d0\uc11c \ubd88\uce74\ub204\uc2a4\ub294 \ubd88\uacfc \uae08\uc18d \uc791\uc5c5\uc5d0 \uad00\uacc4\ub41c \uc2e0\uc774\ub2e4. \uadf8\uc758 \uc544\ub0b4\ub294 \ube44\ub108\uc2a4\uc774\uba70, \uc544\ud3f4\ub860\uc740 \ube44\ub108\uc2a4\uc640 \ub9c8\ub974\uc2a4\uc758 \uad00\uacc4\ub97c \uc54c\ub9ac\ub294 \uc778\ubb3c\ub85c \ub4f1\uc7a5\ud55c\ub2e4. \uadf8\ub9ac\uc2a4 \uc2e0\ud654\uc758 \ud5e4\ud30c\uc774\uc2a4\ud1a0\uc2a4\uc640 \uc544\ud504\ub85c\ub514\ud14c, \uc544\ub808\uc2a4\uc5d0 \ub300\uc751\ud558\ub294 \uc774\ub984\ub4e4\uc744 \uc11e\uc5b4 \uc77d\uc9c0 \uc54a\uc73c\uba74 \uc774\ud574\uac00 \uc27d\ub2e4. \uadf8\ub9bc\uc740 \uc18c\uc2dd\uc774 \uc804\ud574\uc9c4 \ub4a4\uc758 \ubcf5\uc218\ub098 \ub2e4\ub978 \uc2e0\ub4e4\uc758 \uc6c3\uc74c\uc744 \ubcf4\uc5ec \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \uc791\uc5c5\uc7a5\uc5d0 \uc544\ud3f4\ub860\uc774 \ub4e4\uc5b4\uc640 \ub9d0\ud558\uace0 \ubd88\uce74\ub204\uc2a4\uc640 \ub3d9\ub8cc\ub4e4\uc774 \ub4e3\ub294 \uc21c\uac04\uc744 \ud0dd\ud588\ub2e4. \ud070 \uc2e0\ud654\uc758 \uc0ac\uac74\uc744 \uc791\uc740 \uc778\uac04\uc801 \ubc18\uc751\uc73c\ub85c \uc555\ucd95\ud55c \uc120\ud0dd\uc774\ub2e4. \uc67c\ucabd\uc758 \uc544\ud3f4\ub860\uc740 \uba38\ub9ac \uc8fc\ubcc0\uc758 \uad11\ucc44\uc640 \uac78\uce5c \ucc9c, \uc190\uc758 \ub3d9\uc791\uc73c\ub85c \ub2e4\ub978 \uc778\ubb3c\uacfc \uad6c\ubd84\ub41c\ub2e4. \ubab8\uc744 \ub4dc\ub7ec\ub0b8 \uc77c\uafbc\ub4e4\uc740 \ub9dd\uce58\uc640 \uc9d1\uac8c, \ubaa8\ub8e8\uc640 \uc791\uc5c5\ubb3c \uc0ac\uc774\uc5d0 \ub193\uc5ec \uc788\ub2e4. \ub204\uac00 \ub4e4\uc5b4\uc654\ub294\uc9c0 \uc54c\ub824 \uc8fc\ub294 \ud45c\uc2dd\uacfc \ubb34\uc5c7\uc744 \ud558\ub358 \uc911\uc778\uc9c0 \uc54c\ub824 \uc8fc\ub294 \ub3c4\uad6c\uac00 \ud568\uaed8 \uc791\ub3d9\ud55c\ub2e4. \ub208\ubd80\uc2e0 \uc2e0\ub9cc\uc774 \ud654\uba74\uc744 \ub3c5\uc810\ud558\uc9c0 \uc54a\ub294 \uc810\uc774 \ud765\ubbf8\ub86d\ub2e4. \ubd88\uce74\ub204\uc2a4\uc640 \ub3d9\ub8cc\ub4e4\uc758 \ubab8\ub3c4 \uac01\uc790\uc758 \ubb34\uac8c\uc640 \uadfc\uc721, \uc790\uc138\ub97c \uac16\ub294\ub2e4. \uc2e0\ud654\ub97c \uadf8\ub838\uc9c0\ub9cc \ub178\ub3d9\uc758 \uad6c\uccb4\uc801\uc778 \ub3d9\uc791\uc744 \uc9c0\uc6b0\uc9c0 \uc54a\uc558\uae30 \ub54c\ubb38\uc5d0, \ub0af\uc120 \ubc29\ubb38\uc774 \ud3c9\uc18c\uc758 \ub9ac\ub4ec\uc744 \ub04a\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ubd84\uba85\ud574\uc9c4\ub2e4. \uadf8\ub9bc \uc55e\uc5d0\uc11c \uba3c\uc800 \uc2e0\ub4e4\uc758 \uc774\ub984\uc744 \ubaa8\ub978\ub2e4\uace0 \ud574\uc11c \uc7a5\uba74\uc744 \uc77d\uc9c0 \ubabb\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc77c\ud558\ub358 \uc0ac\ub78c\uc774 \ub204\uad70\uac00\uc758 \ub9d0\uc5d0 \uc8fc\uc758\ub97c \ube7c\uc557\uae30\ub294 \uacbd\ud5d8\uc740 \uc775\uc219\ud558\ub2e4. \uadf8 \uc791\uc740 \uacbd\ud5d8\uc744 \ubd99\uc7a1\uc740 \ub4a4 \uc2e0\ud654\uc758 \ubc30\uacbd\uc744 \ub354\ud558\uba74 \ud654\uba74\uc758 \uc758\ubbf8\uac00 \ub450 \uacb9\uc73c\ub85c \uc5f4\ub9b0\ub2e4. \uc544\ud3f4\ub860\uc758 \uc190\uc740 \ub9d0\uc744 \uc124\uba85\ud558\ub294 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc778\ub2e4. \ubc18\uba74 \ubd88\uce74\ub204\uc2a4\uc758 \uc190\uc740 \ub3c4\uad6c\ub97c \uc7a1\uc740 \ucc44 \uc791\uc5c5\uc758 \ud750\ub984\uc5d0\uc11c \uba48\ucd98\ub2e4. \ud55c\ucabd\uc740 \uc815\ubcf4\ub97c \ub0b4\ubcf4\ub0b4\uace0 \ub2e4\ub978 \ucabd\uc740 \ubc1b\uc544\ub4e4\uc774\ub294 \ubab8\uc774\ub2e4. \ub450 \uc885\ub958\uc758 \uc190\uc744 \ube44\uad50\ud558\uba74 \ub300\uc0ac \uc5c6\uc774\ub3c4 \uc7a5\uba74\uc744 \uc77d\uc744 \uc218 \uc788\ub2e4. \ubd88\uce74\ub204\uc2a4\ub294 \ubab8\uc744 \ub3cc\ub9ac\uace0 \uc785\uc744 \ubc8c\ub9b0 \ucc44 \uc18c\uc2dd\uc744 \ub4e3\ub294\ub2e4. \uadf8\ub7ec\ub098 \uadf8\ub9bc\uc774 \uc815\ud655\ud788 \uc5b4\ub5a4 \uac10\uc815 \ud558\ub098\ub97c \uc801\uc5b4 \ub193\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub180\ub78c\uacfc \ubd88\uc2e0, \ubd84\ub178\uac00 \uc11e\uc600\ub2e4\uace0 \uc77d\uc744 \uc218 \uc788\uc9c0\ub9cc, \ubaa8\ub4e0 \uc778\ubb3c\uc758 \uc18d\ub9c8\uc74c\uc744 \ud55c \uac00\uc9c0\ub85c \ub2e8\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud45c\uc815\uc758 \ucc28\uc774\ub97c \uc0b4\ud53c\ub294 \ud3b8\uc774 \ub354 \ud48d\ubd80\ud558\ub2e4. \ub300\uc7a5\uac04\uc758 \uc0ac\ub78c\ub4e4\uc740 \uc544\ud3f4\ub860\uc744 \ud5a5\ud574 \uc77c\uc81c\ud788 \uac19\uc740 \ud3ec\uc988\ub97c \ucde8\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc11c \uc788\ub294 \uc704\uce58\uc640 \ub9e1\uc740 \uc77c\uc774 \ub2e4\ub974\ubbc0\ub85c \ubab8\uc744 \ub3cc\ub9ac\ub294 \ubc29\uc2dd\ub3c4 \ub2e4\ub974\ub2e4. \uac00\uae4c\uc774\uc5d0\uc11c \ub4e3\ub294 \uc0ac\ub78c\uacfc \ub4a4\ud3b8\uc758 \uc0ac\ub78c\uc774 \ub9cc\ub4dc\ub294 \uc2dc\uc120\uc758 \uc5f0\uacb0\uc774 \uc0ac\uac74\uc744 \uc791\uc5c5\uc7a5 \uc804\uccb4\ub85c \ud37c\ub728\ub9b0\ub2e4. \uc774 \ucc28\uc774\uac00 \ud654\uba74\uc744 \uc5f0\uadf9\uc758 \ub2e8\uccb4 \uae30\ub150\uc0ac\uc9c4\uacfc \ub2e4\ub974\uac8c \ub9cc\ub4e0\ub2e4. \ud55c\uc21c\uac04\uc744 \uace8\ub790\uc9c0\ub9cc \uadf8 \uc804\uae4c\uc9c0\uc758 \uc6c0\uc9c1\uc784\uc774 \ub0a8\uc544 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc0ac\ub78c\ub4e4\uc758 \ub208\uc774 \uc5b4\ub514\ub85c \ud5a5\ud558\ub294\uc9c0 \ub530\ub77c\uac00 \ubcf4\uba74 \uad00\ub78c\uc790\uc758 \uc2dc\uc120 \uc5ed\uc2dc \ubc29\ubb38\uc790\uc640 \ubd88\uce74\ub204\uc2a4 \uc0ac\uc774\ub97c \uc655\ubcf5\ud558\uac8c \ub41c\ub2e4. \ub3c4\uad6c\ub97c \uc954 \uc190\uc744 \uacc4\uc18d \ubcf4\uba74 \ub2e4\uc74c \ub3d9\uc791\ub3c4 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \ub9dd\uce58\ub97c \ub0b4\ub9ac\uce60 \uac83 \uac19\ub358 \ud314\uc774 \uba48\ucd94\uc5c8\uae30 \ub54c\ubb38\uc5d0 \uad00\ub78c\uc790\ub294 \uadf8\uc804\uc758 \uc18c\ub9ac\ub97c \uc0c1\uc0c1\ud55c\ub2e4. \uc2e4\uc81c\ub85c \uc18c\ub9ac\uac00 \uc5c6\ub294 \uadf8\ub9bc\uc5d0\uc11c \uc791\uc5c5\uc758 \uc18c\uc74c\uacfc \uac11\uc791\uc2a4\ub7ec\uc6b4 \uce68\ubb35\uc774 \uc0dd\uae30\ub294 \ubc29\uc2dd\uc774\ub2e4. \ub3c4\uad6c\uc640 \uae08\uc18d, \uadf8\ub987\uacfc \uc791\uc5c5\ub300\ub294 \uc7a5\uba74\uc5d0 \ubb3c\uc9c8\uc758 \uac10\uac01\uc744 \uc900\ub2e4. \ud654\uac00\ub294 \ucd08\uc790\uc5f0\uc801\uc778 \uc778\ubb3c\uc744 \uadf8\ub9ac\uba74\uc11c\ub3c4 \uc8fc\ubcc0 \uc0ac\ubb3c\uc758 \ud615\ud0dc\ub97c \uc18c\ud640\ud788 \ud558\uc9c0 \uc54a\uc558\ub2e4. \ub9e8\ubab8\uc758 \uadfc\uc721\ub9cc \ubcf4\ub294 \uac83\ubcf4\ub2e4 \ubab8\uc774 \uc5b4\ub5a4 \ubb3c\uac74\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\ub294\uc9c0 \uc0b4\ud3b4\ubcfc \ub54c \ub178\ub3d9\uc758 \uc7a5\uba74\uc774 \ub610\ub837\ud574\uc9c4\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc2e4\uc81c \ub300\uc7a5\uac04\uc744 \uadf8\ub300\ub85c \uae30\ub85d\ud55c \uc0ac\uc9c4\uc73c\ub85c \ubc1b\uc544\ub4e4\uc774\uba74 \uace4\ub780\ud558\ub2e4. \uc778\ubb3c\uacfc \uc0ac\ubb3c\uc740 \uc0ac\uac74\uc744 \uc77d\ud788\uac8c \ud558\uae30 \uc704\ud574 \ubc30\uce58\ub418\uc5c8\ub2e4. \ud604\uc2e4\uc744 \uc790\uc138\ud788 \ubcf4\ub294 \ub2a5\ub825\uacfc \uc2e0\ud654\ub97c \uad6c\uc131\ud558\ub294 \ub2a5\ub825\uc774 \ud55c \ud654\uba74\uc5d0\uc11c \ub9cc\ub098\ub294 \uac83\uc774 \uc774 \uc791\ud488\uc758 \uc7ac\ubbf8\ub2e4. \uc791\ud488\uc740 \ubca8\ub77c\uc2a4\ucf00\uc2a4\uac00 \uccab \uc774\ud0c8\ub9ac\uc544 \uc5ec\ud589\uc744 \ud558\ub358 1630\ub144 \ubb34\ub835\uc5d0 \uc81c\uc791\ud588\ub2e4. \uc2a4\ud398\uc778 \uad81\uc815\uc758 \ucd08\uc0c1\ud654\ub85c \uc775\uc219\ud55c \ud654\uac00\uac00 \uc5ec\ub7ec \uc778\ubb3c\uc744 \uc5f0\uacb0\ud558\uace0 \ubab8\uacfc \uacf5\uac04\uc744 \uc870\uc9c1\ud558\ub294 \uc2e0\ud654 \ud68c\ud654\uc5d0\ub3c4 \uad00\uc2ec\uc744 \uae30\uc6b8\uc600\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uad81\uc815 \ud654\uac00\ub77c\ub294 \uc9c1\ud568\uc774 \uc18c\uc7ac \uc804\uccb4\ub97c \uc124\uba85\ud558\uc9c0\ub294 \ubabb\ud55c\ub2e4. \ub2e4\ub978 \ud654\uac00\uc758 \uadf8\ub9bc\uacfc \uace0\uc804\uc801 \uc778\uccb4 \ud45c\ud604\uc744 \uc811\ud55c \uacbd\ud5d8\uc740 \uc774\ub7f0 \uc2e4\ud5d8\uc744 \uc774\ud574\ud558\ub294 \ubc30\uacbd\uc774 \ub41c\ub2e4. \ub2e4\ub9cc \ud2b9\uc815 \uc778\ubb3c\uc758 \uc790\uc138\ub97c \uc5b4\ub290 \uc791\ud488\uc5d0\uc11c \uadf8\ub300\ub85c \uac00\uc838\uc654\ub2e4\uace0 \uc27d\uac8c \uacb0\ub860 \ub0b4\ub9b4 \uc218\ub294 \uc5c6\ub2e4. \uc6b0\uc120 \ub208\uc55e\uc758 \ubab8\uacfc \uc2dc\uc120\uc774 \uc5b4\ub5bb\uac8c \uc0ac\uac74\uc744 \uc870\uc9c1\ud558\ub294\uc9c0 \ubcf4\ub294 \uac83\uc774 \uc88b\ub2e4. \ubca8\ub77c\uc2a4\ucf00\uc2a4\ub294 \uc18c\uc2dd\uc744 \ub4e4\uc740 \uc774\ud6c4\ub97c \uae38\uac8c \uc124\uba85\ud558\uc9c0 \uc54a\ub294\ub2e4. \uacb0\ub9d0\uc744 \ubaa8\ub450 \uc54c\ub824 \uc8fc\ub294 \uc5f0\uc18d \uadf8\ub9bc \ub300\uc2e0 \ud558\ub098\uc758 \uc7a5\uba74\uc5d0 \uc9d1\uc911\ud55c\ub2e4. \ubcf4\ub294 \uc0ac\ub78c\uc740 \uc55e\ub4a4\uc758 \uc2e0\ud654\ub97c \uc54c\uace0 \uc788\ub354\ub77c\ub3c4 \ub208\uc55e\uc5d0\uc11c \uc11c\ub85c \ub2e4\ub978 \uc18d\ub3c4\ub85c \ubc18\uc751\ud558\ub294 \uc778\ubb3c\ub4e4\uc744 \ub2e4\uc2dc \ub9cc\ub098\uac8c \ub41c\ub2e4. \uc774 \uadf8\ub9bc\uc758 \uc778\ubb3c\ub4e4\uc740 \ub192\uc740 \uad8c\ub2a5\uc744 \uac00\uc9c4 \uc874\uc7ac\uc774\uba74\uc11c \ub3d9\uc2dc\uc5d0 \ub0a8\uc758 \ub9d0\uc5d0 \ub180\ub77c\ub294 \ubab8\uc744 \uac16\ub294\ub2e4. \uc2e0\ud654\uac00 \uc778\uac04\uacfc \uba40\ub9ac \ub5a8\uc5b4\uc9c4 \uc138\uacc4\ub85c\ub9cc \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc774\uc720\ub2e4. \ud654\uba74\uc758 \uae34\uc7a5\ub3c4 \uac70\ub300\ud55c \ubb34\uae30\uac00 \uc544\ub2c8\ub77c \ub9d0\uc774 \uc804\ub2ec\ub418\ub294 \uc9e7\uc740 \uc2dc\uac04\uc5d0\uc11c \uc0dd\uae34\ub2e4. \uc0ac\uc6a9\ud55c \uc774\ubbf8\uc9c0\ub294 \uc2e4\uc81c \uc791\ud488\uc744 \uc218\ub85d\ud55c \uc5ed\uc0ac \ud751\ubc31 \ub3c4\ud310\uc774\ubbc0\ub85c \uc6d0\ud654\uc758 \uc0c9\ucc44\ub97c \ucda9\ubd84\ud788 \ubcf4\uc5ec \uc8fc\uc9c0 \ubabb\ud55c\ub2e4. \ub300\uc2e0 \ubc29\ubb38\uc790\uc758 \uc190\uc5d0\uc11c \uc2dc\uc791\ud574 \ubd88\uce74\ub204\uc2a4\uc758 \uc5bc\uad74, \uba48\ucd98 \ub3c4\uad6c\uc640 \uc606 \uc0ac\ub78c\ub4e4\uc758 \ub208\uc73c\ub85c \uc2dc\uc120\uc744 \uc62e\uaca8 \ubcf4\uc790. \ub300\uc7a5\uac04\uc758 \uc18c\ub9ac\uac00 \uc7a0\uc2dc \ub04a\uae34 \ub4ef\ud55c \uc21c\uac04\uc744 \uad6c\ub3c4 \uc548\uc5d0\uc11c \uc77d\uc744 \uc218 \uc788\ub2e4."}, {"id": "watteau-cythera-pilgrimage", "title": "\uc2dc\ud14c\ub77c \uc12c\uc73c\ub85c\uc758 \uc21c\ub840 \u2014 \uc5f0\uc778\ub4e4\uc740 \uc5b4\ub514\ub85c \uac00\ub294 \uac78\uae4c", "summary": "\ube44\ub108\uc2a4\uc758 \ud45c\uc9c0\uc640 \uc5f0\uc778\ub4e4\uc758 \uc6c0\uc9c1\uc784\uc744 \ub530\ub77c \ub8e8\ube0c\ub974\uc758 \ud68c\ud654\ub97c \ucc9c\ucc9c\ud788 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\ubbf8\uc220", "categories": ["arts"], "url": "stories/watteau-cythera-pilgrimage/index.html", "image": "../media/watteau-cythera-pilgrimage.jpg", "alt": "\uc640\ud1a0\uc758 \uc2dc\ud14c\ub77c \uc12c\uc73c\ub85c\uc758 \uc21c\ub840. \uc624\ub978\ucabd \ub098\ubb34 \uc544\ub798\uc5d0\uc11c \uc67c\ucabd \ubc30 \ucabd\uc73c\ub85c \uc5f0\uc778\ub4e4\uc758 \uc6c0\uc9c1\uc784\uc774 \uc774\uc5b4\uc9d1\ub2c8\ub2e4.", "text": "\uc2dc\ud14c\ub77c \uc12c\uc73c\ub85c\uc758 \uc21c\ub840 \u2014 \uc5f0\uc778\ub4e4\uc740 \uc5b4\ub514\ub85c \uac00\ub294 \uac78\uae4c \uc640\ud1a0\uc758 \uadf8\ub9bc\uc5d0\uc11c \uc190\uc9d3\uacfc \ubc1c\uac78\uc74c, \ud589\ubcf5 \uc18d\uc758 \uba38\ubb47\uac70\ub9bc\uc744 \uc77d\uae30 \ube44\ub108\uc2a4\uc758 \ud45c\uc9c0\uc640 \uc5f0\uc778\ub4e4\uc758 \uc6c0\uc9c1\uc784\uc744 \ub530\ub77c \ub8e8\ube0c\ub974\uc758 \ud68c\ud654\ub97c \ucc9c\ucc9c\ud788 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ubbf8\uc220 \ubb38\ud654\uc640 \uc608\uc220 \uc798 \ucc28\ub824\uc785\uc740 \uc0ac\ub78c\ub4e4\uc774 \ub098\ubb34 \uc544\ub798\uc5d0 \ubaa8\uc5ec \uc788\ub2e4. \uc5b4\ub5a4 \uc774\ub294 \uc549\uc544 \uc788\uace0 \uc5b4\ub5a4 \uc774\ub294 \uc77c\uc5b4\uc11c\uba70, \ub610 \ub2e4\ub978 \uc774\ub4e4\uc740 \ubc30 \ucabd\uc73c\ub85c \uac78\uc5b4\uac04\ub2e4. \ucd95\uc81c\uc758 \ud55c \uc7a5\uba74 \uac19\uc9c0\ub9cc \ubb34\uc5c7\uc774 \ub9c9 \uc2dc\uc791\ub418\ub294\uc9c0 \ub05d\ub098\ub294\uc9c0 \ubd84\uba85\ud558\uac8c \ub9d0\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \uc559\ud22c\uc548 \uc640\ud1a0\uc758 \u3008\uc2dc\ud14c\ub77c \uc12c\uc73c\ub85c\uc758 \uc21c\ub840\u3009\ub2e4. \uc2dc\ud14c\ub77c \uc12c\uc73c\ub85c\uc758 \ucd9c\ud56d\uc774\ub77c\ub294 \uc774\ub984\uc73c\ub85c\ub3c4 \uc54c\ub824\uc9c4 \uc774 \uadf8\ub9bc\uc740 \uc0ac\ub791\uc758 \ud48d\uacbd\uc744 \ubcf4\uc5ec \uc8fc\uba74\uc11c\ub3c4 \ub5a0\ub0a8\uacfc \uba38\ubb34\ub984 \uc0ac\uc774\uc758 \uc2dc\uac04\uc744 \ub290\ub07c\uac8c \ud55c\ub2e4. \uc778\ubb3c\ub4e4\uc758 \uc791\uc740 \ubab8\uc9d3\uc744 \ub530\ub77c\uac00\uba74 \uc81c\ubaa9\ub9cc \uc77d\uc744 \ub54c\ubcf4\ub2e4 \ud6e8\uc52c \ub9ce\uc740 \uc77c\uc774 \ubcf4\uc778\ub2e4. \uadf8\ub9ac\uc2a4\uc758 \uc12c \uc2dc\ud14c\ub77c\ub294 \uc0ac\ub791\uc758 \uc5ec\uc2e0 \uc544\ud504\ub85c\ub514\ud14c\uc640 \uc5f0\uacb0\ub418\uc5b4 \uc628 \uc774\ub984\uc774\ub2e4. \ub85c\ub9c8\uc2dd \uc774\ub984\uc73c\ub85c\ub294 \ube44\ub108\uc2a4\ub2e4. \uadf8\ub9bc \uc624\ub978\ucabd \ub098\ubb34 \uacc1\uc5d0\ub3c4 \ube44\ub108\uc2a4\uc758 \ubaa8\uc2b5\uc744 \ud55c \ud45c\uc9c0\uac00 \uc788\uace0 \uaf43\uc7a5\uc2dd\uc774 \ub354\ud574\uc838 \uc788\ub2e4. \uacf5\uac04\uc758 \uc131\uaca9\uc744 \uc54c\ub824 \uc8fc\ub294 \ub2e8\uc11c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc774 \uadf8\ub9bc\uc744 \uc12c\uc758 \uc2e4\uc81c \uc9c0\ud615\uc744 \uc548\ub0b4\ud558\ub294 \uc5ec\ud589 \uc9c0\ub3c4\ub85c \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uc0ac\ub791\uc744 \uc5f0\uc0c1\uc2dc\ud0a4\ub294 \uc7a5\uc18c\uc758 \uc774\ub984\uacfc \uc0c1\uc0c1 \uc18d \ud48d\uacbd\uc744 \uc5ee\uc740 \ud68c\ud654\ub85c \ub9cc\ub098\ub294 \ud3b8\uc774 \uc88b\ub2e4. \ubb34\uc5c7\uc774 \uc0ac\uc2e4\uc758 \uc9c0\uba85\uc774\uace0 \ubb34\uc5c7\uc774 \uadf8\ub9bc\uc758 \uad6c\uc131\uc778\uc9c0 \uad6c\ubd84\ud558\uba74 \uc0c1\uc0c1\uc744 \ub354 \uc790\uc720\ub86d\uac8c \uc990\uae38 \uc218 \uc788\ub2e4. \uc624\ub978\ucabd \ub098\ubb34 \uc544\ub798\uc5d0\ub294 \uc544\uc9c1 \uc790\ub9ac\ub97c \ub728\uc9c0 \uc54a\uc740 \ub0a8\ub140\uac00 \ubcf4\uc778\ub2e4. \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\uc774 \uc774\ub3d9\ud558\ub294\ub370\ub3c4 \uc774\ub4e4\uc740 \uc7a0\uc2dc \uc790\uae30\ub4e4\ub9cc\uc758 \uc2dc\uac04\uc744 \ubcf4\ub0b4\ub294 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uc870\uc6a9\ud55c \ub300\ud654\uac00 \uc774\uc5b4\uc9c0\ub294\uc9c0, \ub9c8\uc9c0\ub9c9\uc73c\ub85c \uba38\ubb3c\ub7ec \uc788\ub294\uc9c0 \ubab8\uc758 \ubc29\ud5a5\uc744 \ubcf4\uba70 \uc0c1\uc0c1\ud574 \ubcfc \uc218 \uc788\ub2e4. \uc774\ub54c \uc778\ubb3c\ub4e4\uc758 \ub9c8\uc74c\uc18d \ub300\uc0ac\ub97c \ud655\uc815\ud574 \uc904 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8\ub9bc\uc774 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \uc790\uc138\uc640 \uac70\ub9ac, \uc190\uacfc \uc5bc\uad74\uc758 \ubc29\ud5a5\uc774\ub2e4. \ubcf4\ub294 \uc0ac\ub78c\uc740 \uadf8 \ub2e8\uc11c\ub97c \uc5f0\uacb0\ud574 \uad00\uacc4\ub97c \uc77d\ub294\ub2e4. \uc0ac\ub791\uc774\ub77c\ub294 \ud070 \uc8fc\uc81c\uac00 \uac70\ucc3d\ud55c \uc120\uc5b8\ubcf4\ub2e4 \uc791\uc740 \ubab8\uc9d3\uc5d0\uc11c \uba3c\uc800 \uc2dc\uc791\ub418\ub294 \uc148\uc774\ub2e4. \uc870\uae08 \uc67c\ucabd\uc73c\ub85c \ub208\uc744 \uc62e\uae30\uba74 \ub0a8\uc790\uac00 \uc5ec\uc790\uc758 \uc190\uc744 \uc7a1\uc544 \uc77c\uc73c\ud0a4\ub294 \ub4ef\ud55c \ubaa8\uc2b5\uc774 \ub098\uc628\ub2e4. \ub354 \uac00\uc6b4\ub370\uc5d0\uc11c\ub294 \ub2e4\ub978 \ub450 \uc0ac\ub78c\uc774 \ubab8\uc744 \uac00\uae4c\uc774\ud55c \ucc44 \uc774\ub3d9\ud55c\ub2e4. \uc549\uc544 \uc788\uc74c, \uc77c\uc5b4\ub0a8, \uac77\uae30\ub77c\ub294 \ub2e4\ub978 \ub2e8\uacc4\uac00 \ud55c \ud654\uba74\uc5d0 \ub098\ub780\ud788 \ub193\uc778 \uac83\uc774\ub2e4. \uc774\ub4e4\uc744 \uc2dc\uac04\uc758 \ud750\ub984\ucc98\ub7fc \uc77d\uc73c\uba74 \uc815\uc9c0\ub41c \uadf8\ub9bc\uc774 \ucc9c\ucc9c\ud788 \uc6c0\uc9c1\uc774\uae30 \uc2dc\uc791\ud55c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uac19\uc740 \uc778\ubb3c \ud55c \uc30d\uc774 \uc5ec\ub7ec \ubc88 \uadf8\ub824\uc84c\ub2e4\uace0 \ud655\uc815\ud558\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc790\uc138\ub97c \uc774\uc5b4 \ubcf4\uba74\uc11c \uadf8\ub9bc \uc548\uc5d0 \ub9cc\ub4e4\uc5b4\uc9c4 \ub9ac\ub4ec\uc744 \ub290\ub07c\ub294 \uac10\uc0c1 \ubc29\ubc95\uc774\ub2e4. \uc624\ub978\ucabd\uc5d0\uc11c \uc2dc\uc791\ud55c \uc2dc\uc120\uc740 \uc0ac\ub78c\ub4e4\uc744 \ub530\ub77c \uc67c\ucabd\uc758 \ubc30 \ucabd\uc73c\ub85c \uc774\uc5b4\uc9c4\ub2e4. \uc8fc\ubcc0\uc5d0\ub294 \ub0a0\uac1c \ub2ec\ub9b0 \uc791\uc740 \uc0ac\ub791\uc758 \uc2e0\ub4e4\uc774 \ub5a0\ub2e4\ub2cc\ub2e4. \uc778\uac04\uc758 \ubab8\uc9d3\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c4 \ud604\uc2e4\uc801 \uc7a5\uba74\uc5d0 \uc2e0\ud654\uc801 \ud45c\uc9c0\uac00 \uc11e\uc774\uba74\uc11c, \uc774 \ubaa8\uc784\uc774 \ud3c9\ubc94\ud55c \uc678\ucd9c \uc774\uc0c1\uc758 \uc0c1\uc0c1 \uc18d \uacf5\uac04\uc784\uc744 \uc54c\ub824 \uc900\ub2e4. \uc778\ubb3c\ub9cc \ud655\ub300\ud574\uc11c \ubcf4\uba74 \ub193\uce58\uae30 \uc26c\uc6b4 \ubd80\ubd84\uc774\ub2e4. \uc804\uccb4 \ub3c4\ud310\uc73c\ub85c \ub3cc\uc544\uc640 \ubc30\uc640 \ub098\ubb34, \uba3c \ubb3c\uacfc \uc0b0\uc744 \ud568\uaed8 \ubcf4\uc790. \uac00\uae4c\uc6b4 \uc0ac\ub78c\ub4e4\uc758 \uc774\uc57c\uae30\uac00 \ub113\uc740 \ud48d\uacbd \uc18d\uc5d0 \ub193\uc77c \ub54c \uae30\ubd84\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc791\uc740 \uad00\uacc4\uc640 \ud070 \uacf5\uac04\uc774 \uc11c\ub85c\ub97c \ubc1b\uccd0 \uc900\ub2e4. \uc81c\ubaa9\uc740 \uae38\uc744 \uac00\ub9ac\ud0a4\uc9c0\ub9cc \ud654\uba74\uc758 \ubaa8\ub4e0 \uc0ac\ub78c\uc744 \ud55c \uac00\uc9c0 \ud589\ub3d9\uc73c\ub85c \uc815\ub9ac\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \ubc30 \ucabd\uc73c\ub85c \ud5a5\ud558\ub294 \uc6c0\uc9c1\uc784\uc744 \ub530\ub77c\uac00\uba74 \ub5a0\ub0a8\ucc98\ub7fc \ub290\uaef4\uc9c0\uace0, \uc0ac\ub791\uc758 \uc12c\uc774\ub77c\ub294 \uc81c\ubaa9\uc744 \uba3c\uc800 \ub5a0\uc62c\ub9ac\uba74 \ub3c4\ucc29\uc758 \uc7a5\uba74\uc744 \uc0c1\uc0c1\ud560 \uc218\ub3c4 \uc788\ub2e4. \uadf8\ub9bc \uc18d \uba38\ubb47\uac70\ub9bc\uc740 \uc774\ub7f0 \uc9c8\ubb38\uc744 \uc624\ub798 \ub0a8\uae34\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubaa8\ub4e0 \uc778\ubb3c\uc774 \uac19\uc740 \ubc29\ud5a5\uc758 \uac10\uc815\uc744 \uac00\uc9c0\uace0 \uc788\ub2e4\uace0 \ub2e8\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud568\uaed8 \uc788\uc5b4\ub3c4 \ub204\uad70\uac00\ub294 \ub354 \uba38\ubb3c\uace0 \uc2f6\uace0 \ub204\uad70\uac00\ub294 \uba3c\uc800 \uc77c\uc5b4\ub0a0 \uc218 \uc788\ub2e4. \ubaa9\uc801\uc9c0\ub97c \uc54c\uc544\uc57c\ub9cc \uc77d\uc744 \uc218 \uc788\ub294 \uadf8\ub9bc\uc774 \uc544\ub2c8\ub77c, \uc6c0\uc9c1\uc784\uacfc \ub9dd\uc124\uc784\uc744 \ubcf4\ub294 \uac83 \uc790\uccb4\uac00 \uac10\uc0c1\uc758 \ub0b4\uc6a9\uc774 \ub418\ub294 \uadf8\ub9bc\uc774\ub2e4. \ubd80\ub4dc\ub7ec\uc6b4 \uc0c9\uacfc \uac00\uae4c\uc6b4 \ubab8\uc9d3\uc740 \uc990\uac70\uc6b4 \uae30\ubd84\uc744 \uc900\ub2e4. \uadf8\ub7ec\ub098 \uc990\uac70\uc6c0\uc774 \ub05d\uc5c6\uc774 \uacc4\uc18d\ub420 \uac83 \uac19\uc740 \ud655\uc2e0\ub9cc \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc790\ub9ac\ub97c \uc815\ub9ac\ud558\uace0 \uae38\uc744 \ub098\uc11c\ub294 \uc0ac\ub78c\uc744 \ubcf4\uba74 \uc88b\uc740 \uc2dc\uac04\uc774 \uc9c0\ub098\uac00\uace0 \uc788\ub2e4\ub294 \ub290\ub08c\uc744 \ubc1b\uc744 \uc218\ub3c4 \uc788\ub2e4. \uc774\ub294 \uc791\ud488\uc744 \uc77d\ub294 \ud55c \ubc29\ubc95\uc774\uba70 \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \uac10\uc815\uc774 \uac19\uc544\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uce5c\uad6c\ub4e4\uacfc \uc990\uac70\uc6b4 \uc2dc\uac04\uc744 \ubcf4\ub0b8 \ub4a4 \ud5e4\uc5b4\uc9c0\ub294 \uc21c\uac04\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc2e4\uc81c \uadf8\ub9bc\uc758 \uc778\ubb3c\ub4e4\uc744 \uc624\ub298\uc758 \uc6b0\ub9ac\uc640 \ub611\uac19\ub2e4\uace0 \ub9d0\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \ub0af\uc120 \uc637\uacfc \uc2e0\ud654\uc758 \uc774\ub984\uc744 \ub118\uc5b4 \uac00\uae4c\uc6cc\uc9c8 \uac10\uac01\uc744 \ucc3e\ub294 \uac83\uc774\ub2e4. \uc791\uc740 \ubab8\uc9d3\uc774 \uc624\ub798 \ub0a8\ub294 \uc774\uc720\ub3c4 \uadf8\ub7f0 \uacbd\ud5d8\uacfc \uc5f0\uacb0\ub420 \uc218 \uc788\ub2e4. \uc61b \ub8e8\ube0c\ub974 \ub3c4\ub85d\uc740 \uc774 \uc791\ud488\uc744 \uc640\ud1a0\uac00 \uc544\uce74\ub370\ubbf8\uc5d0 \uc81c\ucd9c\ud55c 1717\ub144 \uc791\ud488\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \ube44\uc2b7\ud55c \uc8fc\uc81c\uc758 \ub2e4\ub978 \ud310\ubcf8\ub3c4 \uc5b8\uae09\ud55c\ub2e4. \uac19\uc740 \uc81c\ubaa9\uc774\ub098 \ube44\uc2b7\ud55c \uad6c\ub3c4\uac00 \ubcf4\uc778\ub2e4\uace0 \ubaa8\ub450 \uac19\uc740 \uadf8\ub9bc\uc758 \ub2e4\ub978 \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc744 \uc54c\uc544 \ub450\uba74 \uc88b\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \uadf8 \ub3c4\ub85d\uc758 \ub8e8\ube0c\ub974 \ud310\ubcf8 \uc0c9\ucc44 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \uc61b \uc778\uc1c4\ubb3c\uc774\ub77c \uc624\ub298 \uc2e4\ubb3c\uc758 \uc0c9\uc744 \uc644\uc804\ud788 \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud604\uc7ac\uc758 \uc804\uc2dc \uc704\uce58\ub97c \uc54c\ub824 \uc8fc\ub294 \uc548\ub0b4\ub3c4\ub85c \uc4f0\uae30\ubcf4\ub2e4 \uc778\ubb3c\ub4e4\uc758 \ubc30\uce58\uc640 \ud070 \uc0c9\uc758 \uad00\uacc4\ub97c \ubcf4\ub294 \uc790\ub8cc\ub85c \ud65c\uc6a9\ud588\ub2e4. \uc624\ub978\ucabd\uc758 \uc549\uc740 \uc0ac\ub78c, \uc77c\uc5b4\ub098\ub294 \uc0ac\ub78c, \uac00\uc6b4\ub370 \uac77\ub294 \uc0ac\ub78c, \uc67c\ucabd \ubc30\uc758 \uc21c\uc11c\ub85c \ucc9c\ucc9c\ud788 \uc2dc\uc120\uc744 \uc62e\uaca8 \ubcf4\uc790. \ub2e4\uc74c\uc5d0\ub294 \ubc18\ub300 \ubc29\ud5a5\uc73c\ub85c \ub3cc\uc544\uc640 \ub098\ubb34 \uc544\ub798\uc758 \uc870\uc6a9\ud55c \ub450 \uc0ac\ub78c\uc744 \ub2e4\uc2dc \ubcf4\uba74 \uc88b\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc0ac\ub78c \uc218\uac00 \ub9ce\uc544 \ubcf5\uc7a1\ud558\ub358 \uadf8\ub9bc\uc5d0 \uc791\uc740 \uc774\uc57c\uae30\ub4e4\uc774 \uc0dd\uae34\ub2e4. \uc640\ud1a0\ub294 \uc0ac\ub791\uc744 \uc124\uba85\ud558\ub294 \ubb38\uc7a5 \ud558\ub098 \ub300\uc2e0 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc790\uc138\uc640 \ud48d\uacbd\uc744 \ub0a8\uacbc\ub2e4. \ucd9c\ubc1c\uc778\uc9c0 \ub3c4\ucc29\uc778\uc9c0 \ud55c \ubc88\uc5d0 \uacb0\ub860 \ub0b4\ub9ac\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4. \uadf8\ub9bc \uc18d \uc2dc\uac04\uc774 \uc5b4\ub514\uc5d0\uc11c \uba38\ubb3c\uace0 \uc5b4\ub514\uc5d0\uc11c \uc6c0\uc9c1\uc774\ub294\uc9c0 \ubcf4\uace0 \ub098\uba74, \uc12c\uc758 \uc774\ub984\ubcf4\ub2e4 \uadf8\uacf3\uc744 \ub5a0\ub098\uac70\ub098 \ucc3e\uc544\uac00\ub294 \uc0ac\ub78c\ub4e4\uc758 \ub9c8\uc74c\uc774 \ub354 \uc624\ub798 \ub0a8\uc744 \uc218 \uc788\ub2e4."}, {"id": "zal-simurgh-white-hair-and-feather", "title": "\uc798\uacfc \uc2dc\ubb34\ub974\uadf8 \u2014 \ud770 \uba38\ub9ac\uc758 \uc544\uc774\ub97c \ud488\uc740 \uac70\ub300\ud55c \uc0c8", "summary": "\uc798\uc758 \ubc84\ub824\uc9d0\uacfc \uc2dc\ubb34\ub974\uadf8\uc758 \uc591\uc721, \uc544\ubc84\uc9c0\uc758 \ud6c4\ud68c\uc640 \uadc0\ud658\uc744 1909\ub144 \uc601\ubb38 \uc120\uc9d1\uc758 \uc7ac\ud654\uc5d0 \ub530\ub77c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "arts", "category_title": "\ubb38\ud654\uc640 \uc608\uc220", "subcategory": "\uc2e0\ud654\uc640 \ubbfc\uc18d", "categories": ["arts"], "url": "stories/zal-simurgh-white-hair-and-feather/index.html", "image": "../media/zal-simurgh-white-hair-and-feather.png", "alt": "\uc0b0\uc758 \ub465\uc9c0\uc5d0\uc11c \ud770 \uba38\ub9ac \uc544\uc774\ub97c \ub0a0\uac1c\ub85c \uac10\uc2fc \uc2dc\ubb34\ub974\uadf8\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uc798\uacfc \uc2dc\ubb34\ub974\uadf8 \u2014 \ud770 \uba38\ub9ac\uc758 \uc544\uc774\ub97c \ud488\uc740 \uac70\ub300\ud55c \uc0c8 \u300e\uc0e4\ub098\uba54\u300f\uc5d0\uc11c \uc77d\ub294 \ubc84\ub824\uc9d0\uacfc \ub3cc\ubd04, \ub3cc\uc544\uac08 \ub54c \ubc1b\uc740 \uae43\ud138 \uc798\uc758 \ubc84\ub824\uc9d0\uacfc \uc2dc\ubb34\ub974\uadf8\uc758 \uc591\uc721, \uc544\ubc84\uc9c0\uc758 \ud6c4\ud68c\uc640 \uadc0\ud658\uc744 1909\ub144 \uc601\ubb38 \uc120\uc9d1\uc758 \uc7ac\ud654\uc5d0 \ub530\ub77c \uc77d\uc2b5\ub2c8\ub2e4. \uc2e0\ud654\uc640 \ubbfc\uc18d \ubb38\ud654\uc640 \uc608\uc220 \uc544\uc774\uac00 \ud0dc\uc5b4\ub0ac\ub294\ub370 \uba38\ub9ac\uce74\ub77d\uc774 \ud76c\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \uadf8\uac83\uc744 \ubd88\uae38\ud55c \uc9d5\uc870\ub85c \ubcf4\uace0 \uc544\ubc84\uc9c0\ub294 \ub450\ub824\uc6c0\uc5d0 \uc0ac\ub85c\uc7a1\ud78c\ub2e4. \uadf8 \uc544\uc774\ub97c \uc0b0\uc5d0 \ub450\uace0 \ub5a0\ub0ac\uc744 \ub54c, \uc0ac\ub78c \ub300\uc2e0 \uac70\ub300\ud55c \uc0c8\uac00 \ub2e4\uac00\uc628\ub2e4. \uc7a1\uc544\uba39\uc73c\ub824\ub294 \uad34\ubb3c\uc774 \uc544\ub2c8\ub77c \ud488\uc5b4 \uae30\ub97c \uc874\uc7ac\uc600\ub2e4. \ud398\ub974\uc2dc\uc544\uc758 \uc11c\uc0ac\uc2dc \u300e\uc0e4\ub098\uba54\u300f\uc5d0 \uc804\ud558\ub294 \uc798\uacfc \uc2dc\ubb34\ub974\uadf8\uc758 \ub9cc\ub0a8\uc774\ub2e4. \uc774 \uae00\uc740 1909\ub144 \uac1c\uc815\ud310 \u300e\ud398\ub974\uc2dc\uc544 \ubb38\ud559\u300f \uc120\uc9d1\uc5d0 \uc2e4\ub9b0 \uc601\ubb38 \uc7ac\ud654\ub97c \ub530\ub978\ub2e4. \ub098\uc911\uc5d0 \uc601\uc6c5\uc758 \uc544\ubc84\uc9c0\uac00 \ub420 \uc778\ubb3c\ub3c4 \uc774 \uc2dc\uc791\uc5d0\uc11c\ub294 \ubcf4\ud638\uac00 \ud544\uc694\ud55c \uc544\uc774\ub85c \ub4f1\uc7a5\ud55c\ub2e4. \uc804\uc0ac \uc0bc\uc740 \uc544\ub4e4\uc758 \ud770 \uba38\ub9ac\ub97c \ubcf4\uace0 \uae30\ubed0\ud558\uc9c0 \ubabb\ud55c\ub2e4. \uc8fc\ubcc0\uc5d0\uc11c\ub294 \ub098\uc05c \uc77c\uc774 \uc0dd\uae38 \uc9d5\uc870\ub77c\uba70 \uc544\uc774\ub97c \uc228\uae30\ub294 \ud3b8\uc774 \ub0ab\ub2e4\uace0 \ub9d0\ud55c\ub2e4. \uc544\uc774\uc758 \uc5bc\uad74\uacfc \ubab8\uc740 \uac74\uac15\ud558\uac8c \uadf8\ub824\uc9c0\uc9c0\ub9cc \uba38\ub9ac\uc0c9 \ud558\ub098\uac00 \uc0ac\ub78c\ub4e4\uc758 \ud310\ub2e8\uc744 \ubd99\uc7a1\ub294\ub2e4. \uc774\uac83\uc740 \ub3c5\uc790\uc5d0\uac8c \uadf8 \ud310\ub2e8\uc774 \uc633\ub2e4\uace0 \uac00\ub974\uce58\ub294 \uc124\uba85\uc774 \uc544\ub2c8\ub2e4. \uc774\uc57c\uae30 \uc18d \uc0ac\ub78c\ub4e4\uc774 \ubb34\uc5c7\uc744 \ub450\ub824\uc6cc\ud588\uace0 \uadf8 \ub450\ub824\uc6c0\uc774 \uc5b4\ub5a4 \ud589\ub3d9\uc73c\ub85c \uc774\uc5b4\uc84c\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \uc2dc\uc791\uc774\ub2e4. \uc544\uc774\uc758 \uc798\ubabb\ubcf4\ub2e4 \uc5b4\ub978\uc774 \ubc1b\uc544\ub4e4\uc774\uc9c0 \ubabb\ud55c \ucc28\uc774\uac00 \uba3c\uc800 \uc788\uc5c8\ub2e4. \uc0bc\uc740 \uc544\uc774\ub97c \uc54c\ubcf4\ub974\uc988\uc0b0\uc5d0 \ubc84\ub9b0\ub2e4. \uadf8\uacf3\uc5d0\ub294 \uc2dc\ubb34\ub974\uadf8\uac00 \uc0b4\uace0 \uc788\uc5c8\ub2e4. \uc0c8\ub07c\uc758 \uba39\uc774\ub97c \ucc3e\ub358 \uac70\ub300\ud55c \uc0c8\ub294 \ud63c\uc790 \ub193\uc778 \uc544\uc774\ub97c \ubc1c\uacac\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uba39\uc787\uac10\uc73c\ub85c \uc0bc\uc9c0 \uc54a\uace0 \uc790\uae30 \ub465\uc9c0\ub85c \ub370\ub824\uac04\ub2e4. \uc0c8\ub07c\ub4e4\ub3c4 \uc544\uc774\ub97c \ubc1b\uc544\ub4e4\uc774\uace0 \ud568\uaed8 \uc790\ub780\ub2e4. \uc0ac\ub78c\uc758 \uc0ac\ud68c\uc5d0\uc11c \uc704\ud5d8\uc73c\ub85c \uc5ec\uae34 \uc874\uc7ac\uac00 \ub2e4\ub978 \uc0dd\uba85\uacfc\uc758 \uad00\uacc4\uc5d0\uc11c\ub294 \ub3cc\ubd04\uc744 \uc5bb\ub294\ub2e4. \uac89\ubaa8\uc2b5\uc774 \ubb34\uc11c\uc6cc \ubcf4\uc77c \uc218 \uc788\ub294 \ud070 \uc0c8\uc640 \uc774\ub984\ub09c \uc804\uc0ac \uac00\uc6b4\ub370 \ub204\uac00 \ubcf4\ud638\uc790\uac00 \ub418\ub294\uc9c0 \uc608\uc0c1\uc774 \ubc14\ub010\ub2e4. \uc2dc\ubb34\ub974\uadf8\ub294 \uc544\uc774\uac00 \uc0b4\uc544\ub0a8\ub3c4\ub85d \uba39\uc774\uae30\ub9cc \ud558\uc9c0 \uc54a\ub294\ub2e4. \uc774 \uc7ac\ud654\uc5d0\uc11c\ub294 \uc0ac\ub78c\uc758 \uc5b8\uc5b4\uc640 \uc774\ud574\ub825\ub3c4 \uae38\ub7ec \uc8fc\uc5c8\ub2e4\uace0 \ud55c\ub2e4. \uc0ac\ub78c \uacc1\uc744 \ub5a0\ub098 \uc790\ub790\uc9c0\ub9cc \ub098\uc911\uc5d0 \uc0ac\ud68c\ub85c \ub3cc\uc544\uac00 \uc0b4\uc544\uac08 \uc900\ube44\uac00 \uc774\ub8e8\uc5b4\uc9c0\ub294 \uac83\uc774\ub2e4. \uc798\uc5d0\uac8c \uadf8 \ub465\uc9c0\ub294 \uc784\uc2dc\ub85c \uc228\uc740 \uacf3\uc744 \ub118\uc5b4 \uc9d1\uc774 \ub41c\ub2e4. \uc790\uae30\ub97c \ub370\ub824\uac04 \uc874\uc7ac\ub97c \ub450\ub824\uc6b4 \uc9d0\uc2b9\uc73c\ub85c\ub9cc \ubcf4\uc9c0 \uc54a\ub294\ub2e4. \ud6d7\ub0a0 \ub5a0\ub098\uc57c \ud55c\ub2e4\ub294 \ub9d0\uc744 \ub4e4\uc5c8\uc744 \ub54c \uae30\ubed0\ud558\uae30\ub9cc \ud558\uc9c0 \uc54a\uace0 \uc6b8\uc74c\uc744 \ud130\ub728\ub9ac\ub294 \uae4c\ub2ed\ub3c4 \uc5ec\uae30\uc5d0 \uc788\ub2e4. \uc0bc\uc740 \uc2dc\uac04\uc774 \ud750\ub978 \ub4a4 \uc544\uc774\uac00 \uc0b4\uc544 \uc788\uc744\uc9c0 \ubaa8\ub978\ub2e4\ub294 \uafc8\uacfc \ud574\uc11d\uc744 \ub4e3\ub294\ub2e4. \ub2e4\uc2dc \uafbc \uafc8\uc5d0\uc11c\ub294 \uc544\uc774\ub97c \ubc84\ub9b0 \ud589\ub3d9\uc744 \uafb8\uc9d6\ub294 \ub9d0\uc774 \ub098\ud0c0\ub09c\ub2e4. \ud770 \uba38\ub9ac\uac00 \uc798\ubabb\uc774\ub77c\uba74 \ub098\uc774 \ub4e4\uc5b4 \uc790\uae30 \uba38\ub9ac\uac00 \ud76c\uc5b4\uc9c4 \uac83\uc740 \uc5b4\ub5bb\uac8c \ubcf4\uc544\uc57c \ud558\ub290\ub0d0\ub294 \uc9c8\ubb38\ub3c4 \uc788\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ubd80\ub044\ub7ec\uc6cc \uc228\uae30\uace0 \uc2f6\uc5c8\ub358 \uc544\uc774\uac00 \uc774\ubc88\uc5d0\ub294 \uc790\uae30 \ud310\ub2e8\uc744 \ub3cc\uc544\ubcf4\uac8c \ud558\ub294 \uc874\uc7ac\uac00 \ub41c\ub2e4. \ub098\uc05c \uc9d5\uc870\uac00 \uc788\uc73c\ub2c8 \ud53c\ud55c\ub2e4\ub294 \uacc4\uc0b0\ub9cc\uc73c\ub85c\ub294 \uc774 \uc77c\uc744 \uc124\uba85\ud560 \uc218 \uc5c6\uc5c8\ub2e4. \uadf8\uac00 \uc800\uc9c0\ub978 \uc77c\uc758 \ucc45\uc784\uc774 \uafc8\uc744 \ud1b5\ud574 \ub418\ub3cc\uc544\uc628\ub2e4. \uc0bc\uc740 \ub2e4\ub978 \uc0ac\ub78c\uc744 \ubcf4\ub0b4\ub294 \ub370\uc11c \uadf8\uce58\uc9c0 \uc54a\uace0 \uc2a4\uc2a4\ub85c \uc0b0\uc744 \uc624\ub978\ub2e4. \uc544\uc774\ub97c \ub3cc\ub824 \ub2ec\ub77c\uace0 \uac04\uccad\ud558\uace0 \uc790\uc2e0\uc758 \ud589\ub3d9\uc744 \ub258\uc6b0\uce5c\ub2e4. \uadf8\ub7ec\ub098 \uc544\uc774\uac00 \uc774\ubbf8 \uc790\ub790\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc2dc\uac04\uc744 \ub418\ub3cc\ub9b4 \uc218 \uc5c6\uc74c\uc744 \uc54c\ub824 \uc900\ub2e4. \uadf8\uac00 \ub3cc\uc544\uc654\ub2e4\uace0 \ub465\uc9c0\uc5d0\uc11c \uc313\uc778 \uad00\uacc4\uac00 \uac00\uc9dc\uac00 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2dc\ubb34\ub974\uadf8\ub294 \uc798\uc5d0\uac8c \uc544\ubc84\uc9c0\uac00 \uc654\uace0 \uc774\uc81c \ub5a0\ub0a0 \ub54c\uac00 \ub418\uc5c8\ub2e4\uace0 \ub9d0\ud55c\ub2e4. \uc0ac\ub78c\uc758 \uc9d1\uc73c\ub85c \uac00\ub294 \uae38\uc740 \ub2e4\ub978 \uc9d1\uacfc \ud5e4\uc5b4\uc9c0\ub294 \uae38\uc774\uae30\ub3c4 \ud588\ub2e4. \uc798\uc740 \uc790\uae30\ub97c \uae38\ub7ec \uc900 \uc874\uc7ac\uc640 \ud5e4\uc5b4\uc838\uc57c \ud55c\ub2e4\ub294 \ub9d0\uc5d0 \uc6b4\ub2e4. \uc0dd\ubb3c\ud559\uc801 \uc544\ubc84\uc9c0\ub97c \ub9cc\ub09c \uae30\uc068 \ud558\ub098\ub85c \uc774 \uc7a5\uba74\uc744 \uc124\uba85\ud558\uae30 \uc5b4\ub835\ub2e4. \uc790\uc2e0\uc744 \ubc1b\uc544\ub4e4\uc778 \uc2dc\uac04\uacfc \ubcf4\uc0b4\ud54c\uc774 \uadf8\uc5d0\uac8c \ub354 \uac00\uae4c\uc6b4 \uae30\uc5b5\uc77c \uc218 \uc788\uc5c8\ub2e4. \uc2dc\ubb34\ub974\uadf8\ub294 \ub5a0\ub098\ub294 \uc77c\uc774 \ubc84\ub9bc\ubc1b\ub294 \uac83\uacfc \uac19\uc9c0 \uc54a\ub2e4\uace0 \ub2ec\ub79c\ub2e4. \ub354 \ub113\uc740 \uacf3\uc5d0\uc11c \uc0b4\uc544\uac08 \uae30\ud68c\ub97c \uc8fc\ub824\ub294 \uac83\uc774\ub2e4. \ucc98\uc74c \uc0b0\uc5d0 \ub193\uc600\uc744 \ub54c\uc640 \uc774\ubc88\uc5d0 \uc0b0\uc744 \ub5a0\ub0a0 \ub54c\ub294 \ubaa8\ub450 \uc774\ub3d9\uc774\uc9c0\ub9cc \uadf8 \uc548\uc758 \ub73b\uc740 \uc815\ubc18\ub300\ub2e4. \uc2dc\ubb34\ub974\uadf8\ub294 \uc790\uae30 \uae43\ud138\uc744 \uc798\uc5d0\uac8c \uc900\ub2e4. \uc5b4\ub824\uc6c0\uc5d0 \ucc98\ud558\uba74 \ub3c4\uc6c0\uc744 \uccad\ud560 \uc218 \uc788\ub3c4\ub85d \ub0a8\uae30\ub294 \ud45c\uc2dd\uc774\ub2e4. \ub465\uc9c0\ub97c \ub5a0\ub09c \ub4a4\uc5d0\ub3c4 \uad00\uacc4\uac00 \ub04a\uae30\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc57d\uc18d\uc774 \ubb3c\uac74 \ud558\ub098\uc5d0 \ub2f4\uae34\ub2e4. \uae43\ud138\uc740 \uc55e\uc73c\ub85c\uc758 \uc774\uc57c\uae30\uc5d0\uc11c\ub3c4 \uc2dc\ubb34\ub974\uadf8\uc640\uc758 \uc5f0\uacb0\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \ubd80\uc640 \ubb34\uae30\ub97c \uc8fc\ub294 \uc120\ubb3c\uacfc \ub2e4\ub974\uac8c \ub204\uad70\uac00 \uc751\ub2f5\ud574 \uc904 \uc218 \uc788\ub2e4\ub294 \ubcf4\uc99d\uc774\ub2e4. \uc2e4\uc81c \uc0c8\uc758 \uae43\ud138\uc5d0 \uadf8\ub7f0 \ud798\uc774 \uc788\ub2e4\ub294 \uc0dd\ud65c\uc758 \uc694\ub839\uc774 \uc544\ub2c8\ub77c \uc11c\uc0ac \uc18d \uc57d\uc18d\uc758 \ubb3c\uac74\uc774\ub2e4. \uc798\uc740 \uc544\ubc84\uc9c0\uc640 \ud568\uaed8 \uc0ac\ub78c\ub4e4\uc758 \uc138\uacc4\ub85c \ub4e4\uc5b4\uac00 \uad50\uc721\uc744 \ubc1b\uace0 \uc5ed\ud560\uc744 \ub9e1\uac8c \ub41c\ub2e4. \ub4a4\uc5d0\ub294 \ub8e8\ub2e4\ubca0\uc640\uc758 \uad00\uacc4\uc640 \uc601\uc6c5 \ub85c\uc2a4\ud0d0\uc758 \ud0c4\uc0dd\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uae34 \uc774\uc57c\uae30\uac00 \uc788\ub2e4. \uc0b0\uc5d0\uc11c\uc758 \uc2dc\uc808\uc740 \uadf8 \ub4a4 \uc0b6\uc758 \ucd9c\ubc1c\uc810\uc73c\ub85c \ub0a8\ub294\ub2e4. \uadf8\ub7ec\ub098 \ub098\uc911\uc5d0 \uc911\uc694\ud55c \uc0ac\ub78c\uc774 \ub418\uc5c8\uc73c\ub2c8 \ubc84\ub824\uc11c\ub294 \uc548 \ub418\uc5c8\ub2e4\ub294 \uc2dd\uc73c\ub85c\ub9cc \uc77d\uc73c\uba74 \uace4\ub780\ud558\ub2e4. \uc544\uc774\ub97c \ub3cc\ubcfc \uc774\uc720\ub97c \ubbf8\ub798\uc758 \uacf5\ub85c\uc5d0\uc11c\ub9cc \ucc3e\uac8c \ub418\uae30 \ub54c\ubb38\uc774\ub2e4. \uc2dc\ubb34\ub974\uadf8\uac00 \ucc98\uc74c \ubc1b\uc544\ub4e4\uc778 \uac83\uc740 \uc544\uc9c1 \uc544\ubb34 \uc5c5\uc801\ub3c4 \uc5c6\ub294 \uc544\uc774\uc600\ub2e4. \uc798\uc758 \uc774\uc57c\uae30\ub294 \uc778\uac04 \uc0ac\ud68c\uc758 \ud3b8\uacac\uacfc \ub2e4\ub978 \uc874\uc7ac\uc758 \ub3cc\ubd04\uc744 \ub098\ub780\ud788 \ub193\ub294\ub2e4. \uc720\uba85\ud55c \uc804\uc0ac\uac00 \ubcf4\ud638\ud558\uc9c0 \ubabb\ud55c \uc790\ub9ac\ub97c \uac70\ub300\ud55c \uc0c8\uac00 \ucc44\uc6b4\ub2e4. \uc5b4\ub290 \ucabd\uc774 \ubb38\uba85\uc774\uace0 \uc57c\uc0dd\uc778\uc9c0 \uc27d\uac8c \uad6c\ubd84\ud558\ub358 \ub208\uc774 \uc7a0\uae50 \uba48\ucd98\ub2e4. \uae43\ud138\uc744 \ub2e4\uc2dc \ub5a0\uc62c\ub9ac\uba74 \uadf8 \ub2e4\uc815\ud55c \uc5ed\uc804\uc774 \ubcf4\uc778\ub2e4. \ud488\uc5b4 \uc900 \uc874\uc7ac\ub294 \uc790\uae30 \uacc1\uc5d0\ub9cc \ub0a8\uc73c\ub77c\uace0 \ubd99\uc7a1\uc9c0 \uc54a\uace0 \ub5a0\ub09c \ub4a4\uc5d0\ub3c4 \ub3cc\uc544\ubcfc \uae38\uc744 \ub0a8\uae34\ub2e4. \uc798\uc758 \ud770 \uba38\ub9ac\ubcf4\ub2e4 \uc624\ub798 \uc0dd\uac01\ud558\uac8c \ub418\ub294 \uac83\uc740 \ub204\uac00 \uadf8 \uc544\uc774\uc758 \uc9d1\uc774 \ub418\uc5b4 \uc8fc\uc5c8\ub290\ub0d0\ub294 \uc9c8\ubb38\uc774\ub2e4."}, {"id": "airbnb-room-and-neighborhood", "title": "\uc5d0\uc5b4\ube44\uc564\ube44 \u2014 \ube48\ubc29\uc744 \uc5f0\uacb0\ud558\uba74 \uc0dd\uae30\ub294 \uc77c", "summary": "\ucd08\uae30\uc758 \uc5d0\uc5b4 \ub9e4\ud2b8\ub9ac\uc2a4 \uc0ac\ub840\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc628\ub77c\uc778 \uc911\uac1c, \ub3d9\ub124 \uc815\ubcf4\uc640 \uaddc\uce59\uc758 \ubb38\uc81c\uae4c\uc9c0 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\uc0c1\uc5c5\uacfc \uc720\ud1b5", "categories": ["industry"], "url": "stories/airbnb-room-and-neighborhood/index.html", "image": "../media/airbnb-room-and-neighborhood.png", "alt": "\uc5ec\ud589 \uac00\ubc29\uc744 \ub4e0 \ubc29\ubb38\uac1d\uacfc \ubc29\uc758 \ubb38\uc744 \uc5f4\uc5b4 \ub9de\uc774\ud558\ub294 \uc9d1\uc8fc\uc778\uc758 \uc0c1\uc0c1 \uc18d \ub9cc\ub0a8.", "text": "\uc5d0\uc5b4\ube44\uc564\ube44 \u2014 \ube48\ubc29\uc744 \uc5f0\uacb0\ud558\uba74 \uc0dd\uae30\ub294 \uc77c \uc9d1\uc8fc\uc778\uacfc \uc5ec\ud589\uc790 \uc0ac\uc774\uc5d0 \uc0c8\ub85c\uc6b4 \uc2dc\uc7a5\uc774 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4 \ucd08\uae30\uc758 \uc5d0\uc5b4 \ub9e4\ud2b8\ub9ac\uc2a4 \uc0ac\ub840\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc628\ub77c\uc778 \uc911\uac1c, \ub3d9\ub124 \uc815\ubcf4\uc640 \uaddc\uce59\uc758 \ubb38\uc81c\uae4c\uc9c0 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc0c1\uc5c5\uacfc \uc720\ud1b5 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \uc5ec\ud589\uc744 \uc55e\ub450\uace0 \uc798 \uacf3\uc744 \ucc3e\ub294 \uc0ac\ub78c\uc774 \uc788\ub2e4. \ub2e4\ub978 \ud55c\ucabd\uc5d0\ub294 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294 \ubc29\uc774 \uc788\ub2e4. \ub450 \uc0ac\uc815\uc774 \uc11c\ub85c\ub97c \uc54c\uc9c0 \ubabb\ud558\uba74 \uc544\ubb34 \uc77c\ub3c4 \uc0dd\uae30\uc9c0 \uc54a\ub294\ub2e4. \ud558\uc9c0\ub9cc \ucc3e\uace0 \uc5f0\ub77d\ud558\uace0 \uac70\ub798\ud560 \uc218 \uc788\ub294 \uae38\uc774 \ub9cc\ub4e4\uc5b4\uc9c0\uba74 \ub0a8\ub294 \uacf5\uac04\uc740 \ub2e4\ub978 \uc4f0\uc784\uc744 \uc5bb\uc744 \uc218 \uc788\ub2e4. \uc5d0\uc5b4\ube44\uc564\ube44\uc758 \ucd9c\ubc1c \uc774\uc57c\uae30\ub294 \uc774 \ub2e8\uc21c\ud55c \uc5f0\uacb0\uc5d0\uc11c \uc2dc\uc791\ud55c\ub2e4. \ub2e4\ub9cc \uc571 \ud654\uba74\uc5d0\uc11c \ube48\ubc29\uc744 \ucc3e\ub294 \uc77c\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uacfc\uc815\uc774 \uc124\uba85\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub204\uad70\uac00\uc758 \uc9d1\uc774 \uc5ec\ud589\uc790\uc758 \uc219\uc18c\uac00 \ub418\uba74 \uc2e0\ub8b0\uc640 \uc0dd\ud65c, \ub3d9\ub124\uc758 \uaddc\uce59\uae4c\uc9c0 \ud568\uaed8 \uc5f0\uacb0\ub418\uae30 \ub54c\ubb38\uc774\ub2e4. \uad50\uc7ac\ub294 \ube0c\ub77c\uc774\uc5b8 \uccb4\uc2a4\ud0a4\uc640 \uc870 \uac8c\ube44\uc544\uac00 \uc9d1\uc138 \ubd80\ub2f4\uc744 \uacaa\ub358 \ub54c \uc790\uc2e0\uc758 \uacf5\uac04\uc5d0 \uc190\ub2d8\uc744 \ubc1b\uace0 \uc5d0\uc5b4 \ub9e4\ud2b8\ub9ac\uc2a4\uc5d0\uc11c \uc790\uac8c \ud55c \uc0ac\ub840\ub97c \uc18c\uac1c\ud55c\ub2e4. \uc9c0\uae08\uc758 \uac70\ub300\ud55c \uc11c\ube44\uc2a4\ub97c \ub5a0\uc62c\ub9ac\uae30 \uc804\uc5d0 \uc0dd\ud65c \uc18d\uc758 \uad6c\uccb4\uc801\uc778 \uc0ac\uc815\uc774 \uc788\uc5c8\ub2e4\ub294 \uac83\uc774\ub2e4. \ucc98\uc74c\uc758 \ud544\uc694\ub294 \uc790\uc2e0\uc774 \uac00\uc9c4 \uacf5\uac04\uc73c\ub85c \uc218\uc785\uc744 \uc5bb\ub294 \uc77c\uc774\uc5c8\ub2e4. \uc774 \uc0ac\ub840\ub97c \ubbf8\ub798\uc758 \ubaa8\ub4e0 \uc131\uacf5\uc774 \uc608\uc815\ub41c \uc21c\uac04\uc73c\ub85c \uafb8\ubc00 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc8fc\ubcc0\uc5d0\uc11c \uc0dd\uae34 \ubd88\ud3b8\uc744 \ub2e4\ub978 \uc0ac\ub78c\uc758 \ud544\uc694\uc640 \uc5f0\uacb0\ud574 \ubcf4\uc558\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uadf8\ub807\ub2e4\uace0 \uac19\uc740 \uc77c\uc744 \ud574 \ubcf4\uba74 \ub204\uad6c\ub098 \uac19\uc740 \uae30\uc5c5\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4\ub294 \ub73b\ub3c4 \uc544\ub2c8\ub2e4. \uc791\uc740 \uc2dc\ub3c4\uc640 \uc9c0\uc18d \uac00\ub2a5\ud55c \uc0ac\uc5c5 \uc0ac\uc774\uc5d0\ub294 \ub9ce\uc740 \uc900\ube44\uac00 \ub0a8\uc544 \uc788\uc5c8\ub2e4. \uc804\ud1b5\uc801\uc778 \uc219\ubc15 \uc0ac\uc5c5\uc744 \uc0dd\uac01\ud558\uba74 \uac74\ubb3c\uc744 \ub9c8\ub828\ud558\uace0 \ubc29\uc744 \uad00\ub9ac\ud558\ub294 \ubaa8\uc2b5\uc774 \uba3c\uc800 \ub5a0\uc624\ub978\ub2e4. \uc628\ub77c\uc778 \uc911\uac1c\ub294 \uc774\ubbf8 \uc874\uc7ac\ud558\ub294 \uacf5\uac04\uc758 \uc81c\uacf5\uc790\uc640 \uc774\uc6a9\uc790\ub97c \uc5f0\uacb0\ud558\ub294 \ub370 \ubb34\uac8c\uac00 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc774\ub7f0 \uc720\ud615\uc744 \uc811\uadfc \uacbd\uc81c \ub610\ub294 \uc628\ub77c\uc778 \ud50c\ub7ab\ud3fc \uacbd\uc81c\uc758 \uc0ac\ub840\ub85c \uc124\uba85\ud55c\ub2e4. \uc790\uc0b0\uc744 \uc18c\uc720\ud558\ub294 \uc77c\uacfc \uc77c\uc815 \uae30\uac04 \uc774\uc6a9\ud560 \uad8c\ub9ac\ub97c \uc5f0\uacb0\ud558\ub294 \uc77c\uc774 \uad6c\ubd84\ub418\ub294 \uac83\uc774\ub2e4. \ub2e4\ub9cc \ud50c\ub7ab\ud3fc\uc774 \uacf5\uac04\uc744 \uc9c1\uc811 \uc18c\uc720\ud558\uc9c0 \uc54a\ub294\ub2e4\uace0 \uc11c\ube44\uc2a4\uc5d0 \uad00\ud55c \ucc45\uc784\uc758 \uc9c8\ubb38\uae4c\uc9c0 \uc5c6\uc5b4\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uac80\uc0c9 \ud654\uba74\uc744 \ub9cc\ub4e0 \ub4a4\uc5d0\ub3c4 \uc2e4\uc81c \ub9cc\ub0a8\uacfc \uac70\ub798\ub294 \uc0ac\ub78c\uc758 \uc0dd\ud65c \uacf5\uac04\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c4\ub2e4. \uc5ec\ud589\uc790\ub294 \ubc29\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ubfd0 \uc544\ub2c8\ub77c \uadf8\uacf3\uc774 \uc5b4\ub5a4 \uacf3\uc778\uc9c0 \uc54c\uace0 \uc2f6\uc5b4 \ud55c\ub2e4. \uc704\uce58\uc640 \uc8fc\ubcc0 \ud658\uacbd\uc774 \uc790\uae30 \uc77c\uc815\uc5d0 \ub9de\ub294\uc9c0\ub3c4 \uc911\uc694\ud558\ub2e4. \uc9d1\uc8fc\uc778\uc5d0\uac8c\ub3c4 \ub0af\uc120 \uc0ac\ub78c\uc774 \ubc29\ubb38\ud55c\ub2e4\ub294 \uc810\uc740 \ubcc4\ub3c4\uc758 \ubb38\uc81c\ub2e4. \uc591\ucabd\uc758 \ud544\uc694\uac00 \ub9de\ub294\uc9c0 \ud655\uc778\ud560 \uc815\ubcf4\uac00 \uc788\uc5b4\uc57c \uac70\ub798\uac00 \uc131\ub9bd\ud55c\ub2e4. \uc774 \ub54c\ubb38\uc5d0 \uc628\ub77c\uc778 \uc2dc\uc7a5\uc740 \ub2e8\uc21c\ud788 \ubaa9\ub85d\uc744 \uae38\uac8c \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \ubb34\uc5c7\uc744 \uac19\uc740 \uae30\uc900\uc73c\ub85c \ube44\uad50\ud558\uace0 \uc5b4\ub5a4 \ub0b4\uc6a9\uc744 \ubd84\uba85\ud558\uac8c \uc54c\ub824 \uc904\uc9c0 \uacb0\uc815\ud574\uc57c \ud55c\ub2e4. \ubcf4\uae30 \uc88b\uc740 \uc0ac\uc9c4\uacfc \uc2e4\uc81c \uc774\uc6a9 \uc870\uac74 \uc0ac\uc774\uc758 \uac04\uaca9\uc774 \ud06c\uba74 \ud3b8\ub9ac\ud55c \uac80\uc0c9\uc774 \uace7 \uc88b\uc740 \uacbd\ud5d8\uc73c\ub85c \uc774\uc5b4\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uad50\uc7ac\ub294 \uc5d0\uc5b4\ube44\uc564\ube44\uac00 2012\ub144 \ub3d9\ub124 \uc548\ub0b4 \uc11c\ube44\uc2a4 \ub124\uc774\ube0c\uc640\uc774\uc988\ub97c \uc778\uc218\ud55c \uc0ac\ub840\ub97c \uc18c\uac1c\ud55c\ub2e4. \ub0af\uc120 \uc9c0\uc5ed\uc758 \uc219\uc18c\ub97c \uace0\ub974\ub294 \uc0ac\ub78c\uc5d0\uac8c \uc8fc\ubcc0\uc744 \uc774\ud574\ud560 \uc815\ubcf4\ub97c \uc81c\uacf5\ud558\ub294 \ubc29\ud5a5\uc774\uc5c8\ub2e4. \uc5ec\ud589\uc790\uc758 \uc9c8\ubb38\uc740 \uce68\ub300\uac00 \uc788\ub294\uac00\uc5d0\uc11c \uc5b4\ub5a4 \ub3d9\ub124\uc5d0 \uba38\ubb3c \uac83\uc778\uac00\ub85c \ub113\uc5b4\uc9c8 \uc218 \uc788\ub2e4. \uc774\ubc88 \uae00\uc740 \ub2f9\uc2dc\uc758 \uc0ac\uc5c5 \uc120\ud0dd\uc744 \uc124\uba85\ud558\ub294 \uac83\uc73c\ub85c \uadf8 \uc11c\ube44\uc2a4\uac00 \ud604\uc7ac \uac19\uc740 \uc774\ub984\uacfc \ud615\ud0dc\ub85c \uc6b4\uc601\ub41c\ub2e4\ub294 \uc548\ub0b4\ub294 \uc544\ub2c8\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ubc29\uc758 \uc815\ubcf4\uc640 \uc9c0\uc5ed\uc758 \uc815\ubcf4\ub97c \ud568\uaed8 \ubcf4\ub824 \ud588\ub2e4\ub294 \uc810\uc774\ub2e4. \uc0c1\ud488\uc758 \uacbd\uacc4\ub97c \uc5b4\ub514\uae4c\uc9c0 \uc7a1\ub294\uc9c0\uc5d0 \ub530\ub77c \uae30\uc5c5\uc774 \ub9c8\ub828\ud574\uc57c \ud558\ub294 \uc815\ubcf4\uc640 \ud611\ub825\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uac70\ub798 \ud654\uba74\uc5d0\ub294 \uc9d1\uc8fc\uc778\uacfc \uc5ec\ud589\uc790\uac00 \uc911\uc2ec\uc73c\ub85c \ub4f1\uc7a5\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc2e4\uc81c \uacf5\uac04\uc5d0\ub294 \uc774\uc6c3\uacfc \uac74\ubb3c\uc758 \ub2e4\ub978 \uc774\uc6a9\uc790\ub3c4 \uc788\ub2e4. \ub4dc\ub098\ub4dc\ub294 \uc0ac\ub78c\uc774 \ubc14\ub00c\uba74 \uc0dd\ud65c\uc758 \uc870\uac74\uc5d0 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\ub2e4. \uad50\uc7ac\uac00 \uaddc\uc81c\uc640 \uc2e0\ub8b0\ub97c \uc911\uc694\ud55c \uc9c8\ubb38\uc73c\ub85c \ub2e4\ub8e8\ub294 \uc774\uc720\ub2e4. \ud55c \uc0ac\ub78c\uc5d0\uac8c\ub294 \ub0a8\ub294 \uacf5\uac04\uc744 \ud65c\uc6a9\ud558\ub294 \uc88b\uc740 \uae30\ud68c\uac00 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc0c8\ub85c\uc6b4 \uad00\ub9ac \ubb38\uc81c\uc77c \uc218 \uc788\ub2e4. \uae30\uc220\uc774 \ub450 \ub2f9\uc0ac\uc790\ub97c \uc27d\uac8c \uc774\uc5b4 \uc8fc\uc5b4\ub3c4 \uc8fc\ubcc0\uc758 \uc774\ud574\uad00\uacc4\uae4c\uc9c0 \uc790\ub3d9\uc73c\ub85c \uc77c\uce58\uc2dc\ud0a4\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc628\ub77c\uc778\uc5d0\uc11c \uac04\ub2e8\ud574 \ubcf4\uc774\ub294 \uac70\ub798\uac00 \uc624\ud504\ub77c\uc778\uc5d0\uc11c\ub294 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \ubb38\uc81c\ub77c\ub294 \uc810\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uad50\uc7ac\ub294 \uac1c\uc778\uc758 \ubc29 \ub300\uc5ec\ub97c \ud638\ud154\uacfc \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ubcfc \uac83\uc778\uc9c0, \uc5b4\ub5a4 \uc138\uae08\uacfc \uc548\uc804 \uaddc\uce59\uc744 \uc801\uc6a9\ud560 \uac83\uc778\uc9c0 \ub17c\uc758\ud55c\ub2e4. \uc9c0\uc5ed\uc5d0 \ub530\ub77c \ub2e8\uae30 \uc784\ub300\uc758 \ud5c8\uc6a9 \uc870\uac74\uacfc \uaddc\uc81c\uac00 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc219\ubc15\uc758 \uc81c\uacf5 \ubc29\uc2dd\uc774 \ub2ec\ub77c\uc9c0\uba74 \uae30\uc874 \uc81c\ub3c4\ub97c \uc5b4\ub514\uae4c\uc9c0 \uc801\uc6a9\ud560\uc9c0\ub3c4 \uc9c8\ubb38\uc774 \ub41c\ub2e4. \ub530\ub77c\uc11c \uc774 \uae00\uc5d0\uc11c \uc5b4\ub290 \ub3c4\uc2dc\uc758 \ud604\uc7ac \uc601\uc5c5 \ud5c8\uc6a9 \uc5ec\ubd80\ub97c \uc548\ub0b4\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc2e4\uc81c \uc774\uc6a9\uc774\ub098 \uc6b4\uc601\uc5d0\ub294 \ud574\ub2f9 \uc2dc\uc810\uacfc \uc9c0\uc5ed\uc758 \uaddc\uc815\uc744 \ub530\ub85c \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uc5ec\uae30\uc11c\ub294 \uae30\uc5c5\uc758 \uc0c8\ub85c\uc6b4 \ubc29\uc2dd\uc774 \uae30\uc874 \uaddc\uce59\uacfc \ub9cc\ub098\uba70 \uc0ac\ud68c\uc801 \ub17c\uc758\ub3c4 \ud568\uaed8 \ub9cc\ub4e0\ub2e4\ub294 \uc810\uc744 \uc77d\ub294 \uac83\uc774 \uc54c\ub9de\ub2e4. \uacf5\uc720\ub77c\ub294 \ub9d0\uc5d0\ub294 \uc11c\ub85c \ub3d5\ub294 \uac00\ubcbc\uc6b4 \ub290\ub08c\uc774 \uc788\ub2e4. \ud558\uc9c0\ub9cc \ub3c8\uc744 \ubc1b\uace0 \uacf5\uac04\uc744 \uc81c\uacf5\ud558\ub294 \ud65c\ub3d9\uc5d0\ub294 \uc0ac\uc5c5\uc758 \uc131\uaca9\ub3c4 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc774\ub7f0 \uac70\ub798\ub97c \ubaa8\ub450 \uac19\uc740 \uc885\ub958\uc758 \uacf5\ub3d9 \uc0ac\uc6a9\uc73c\ub85c\ub9cc \ubcf4\uc9c0 \uc54a\uace0 \uc628\ub77c\uc778 \ud50c\ub7ab\ud3fc\uc774\ub77c\ub294 \ud2c0\uc5d0\uc11c \uc77d\uc744 \ud544\uc694\uac00 \uc788\uc74c\uc744 \uc124\uba85\ud55c\ub2e4. \ub9d0\uc758 \uc778\uc0c1\uacfc \uc2e4\uc81c \uc6b4\uc601\uc744 \ub098\ub204\uba74 \uc7a5\uc810\uacfc \uc9c8\ubb38\uc744 \ud568\uaed8 \ubcfc \uc218 \uc788\ub2e4. \uacf5\uac04\uc744 \ub354 \ub2e4\uc591\ud558\uac8c \ud65c\uc6a9\ud560 \uae30\ud68c\uac00 \uc0dd\uae30\ub294 \ud55c\ud3b8 \ucc45\uc784\uacfc \ubcf4\ud638\uc758 \uae30\uc900\ub3c4 \ud544\uc694\ud558\ub2e4. \uc0c8\ub85c\uc6b4 \uc2dc\uc7a5\uc774\ub77c\ub294 \uc774\uc720\ub85c \ubb34\uc870\uac74 \uc88b\uc740 \uac83\uc73c\ub85c \ubcf4\uac70\ub098 \uae30\uc874\uacfc \ub2e4\ub974\ub2e4\ub294 \uc774\uc720\ub85c \uc758\ubbf8\ub97c \uc9c0\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc9d1\uc8fc\uc778\uacfc \uc5ec\ud589\uc790\uac00 \ubb38 \uc55e\uc5d0\uc11c \ub9cc\ub098\ub294 \uc0c1\uc0c1 \uc18d \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c \ucc3d\uc5c5\uc790\ub098 \ub4f1\ub85d \uc219\uc18c, \uc774\uc6a9\uc790\uc758 \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \ub0af\uc120 \uc0ac\ub78c\ub07c\ub9ac \uacf5\uac04\uc744 \ub098\ub208\ub2e4\ub294 \uad6c\uc0c1\uc758 \ucd9c\ubc1c\uc810\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc774\ubbf8\uc9c0\ub2e4. \uc5d0\uc5b4\ube44\uc564\ube44\uc758 \uc0ac\ub840\ub294 \uae30\uc220\uc774 \ub0a8\ub294 \uc790\uc6d0\uacfc \ud544\uc694\ud55c \uc0ac\ub78c\uc744 \ub9cc\ub098\uac8c \ud560 \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub3d9\uc2dc\uc5d0 \uc5f0\uacb0 \uc774\ud6c4\uc5d0\ub294 \uc124\uba85\uacfc \uc57d\uc18d, \uc0dd\ud65c\uc758 \uaddc\uce59\uc774 \ub0a8\ub294\ub2e4. \ube48\ubc29 \ud558\ub098\uac00 \uc2dc\uc7a5\uc774 \ub418\ub294 \uacfc\uc815\uc740 \ubc84\ud2bc\uc758 \ud3b8\ub9ac\ud568\ubfd0 \uc544\ub2c8\ub77c \uadf8 \ubc84\ud2bc \ubc16\uc5d0\uc11c \ub9cc\ub098\ub294 \uc0ac\ub78c\ub4e4\uae4c\uc9c0 \ud568\uaed8 \uc124\uacc4\ud558\ub294 \uc774\uc57c\uae30\ub2e4."}, {"id": "amazon-order-and-warehouse", "title": "\uc544\ub9c8\uc874 \u2014 \uc8fc\ubb38 \ubc84\ud2bc \ub4a4\uc5d0\ub294 \ubb34\uc5c7\uc774 \ub0a8\uc544 \uc788\uc744\uae4c", "summary": "2010\ub144\ub300 \uc544\ub9c8\uc874 \uc0ac\ub840\ub97c \ud1b5\ud574 \uc628\ub77c\uc778 \uc8fc\ubb38\uacfc \ubb3c\ub958\u00b7\ud68c\uc6d0\uc81c\u00b7\ub178\ub3d9\uc758 \uc5f0\uacb0\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\uc0c1\uc5c5\uacfc \uc720\ud1b5", "categories": ["industry"], "url": "stories/amazon-order-and-warehouse/index.html", "image": "../media/amazon-order-and-warehouse.png", "alt": "\uc0c1\uc790\ub97c \ud655\uc778\ud558\ub294 \uc0ac\ub78c\uacfc \uc120\ubc18\uc744 \uc815\ub9ac\ud558\ub294 \uc0ac\ub78c\uc774 \uc788\ub294 \ubc30\uc1a1 \uc791\uc5c5\uc7a5\uc758 AI \uc7a5\uba74.", "text": "\uc544\ub9c8\uc874 \u2014 \uc8fc\ubb38 \ubc84\ud2bc \ub4a4\uc5d0\ub294 \ubb34\uc5c7\uc774 \ub0a8\uc544 \uc788\uc744\uae4c \ud654\uba74\uc5d0\uc11c \uc0ac\ub294 \ubb3c\uac74\uc740 \uacb0\uad6d \ud604\uc2e4\uc758 \uae38\uc744 \uc9c0\ub098\uc628\ub2e4 2010\ub144\ub300 \uc544\ub9c8\uc874 \uc0ac\ub840\ub97c \ud1b5\ud574 \uc628\ub77c\uc778 \uc8fc\ubb38\uacfc \ubb3c\ub958\u00b7\ud68c\uc6d0\uc81c\u00b7\ub178\ub3d9\uc758 \uc5f0\uacb0\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc0c1\uc5c5\uacfc \uc720\ud1b5 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \ubb3c\uac74\uc744 \uace0\ub974\uace0 \uc8fc\ubb38 \ubc84\ud2bc\uc744 \ub204\ub978\ub2e4. \ud654\uba74\uc5d0 \ud655\uc778 \uba54\uc2dc\uc9c0\uac00 \ub728\uba74 \uad6c\ub9e4\ub294 \ub05d\ub09c \uac83\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uadf8\ub7ec\ub098 \ubb3c\uac74\uc774 \uc6b0\ub9ac \uc9d1\uc5d0 \uc624\ub824\uba74 \uadf8\ub54c\ubd80\ud130 \ub9ce\uc740 \uc77c\uc774 \uc2dc\uc791\ub418\uc5b4\uc57c \ud55c\ub2e4. \ub204\uad70\uac00\ub294 \uc0c1\ud488\uc744 \ucc3e\uace0 \ud3ec\uc7a5\ud558\uace0 \uc6b4\ubc18\ud574\uc57c \ud55c\ub2e4. \uc544\ub9c8\uc874\uc740 \uc774\ub7f0 \ud654\uba74\uacfc \ud604\uc2e4\uc758 \uc5f0\uacb0\uc744 \uc0dd\uac01\ud558\uae30 \uc88b\uc740 \uae30\uc5c5\uc774\ub2e4. OpenStax\uc758 \uacbd\uc601\ud559 \uad50\uc7ac\ub294 2010\ub144\ub300 \uc544\ub9c8\uc874\uc758 \uc628\ub77c\uc778 \ud310\ub9e4 \uc804\ub7b5\uacfc \ubb3c\ub958 \uac70\uc810, \ud68c\uc6d0\uc81c \uc11c\ube44\uc2a4\ub97c \ud568\uaed8 \uc124\uba85\ud55c\ub2e4. \uc778\ud130\ub137 \uae30\uc5c5\uc774\ub77c\uace0 \ud574\uc11c \uc911\uc694\ud55c \uc77c\uc774 \ubaa8\ub450 \uc778\ud130\ub137 \uc548\uc5d0\uc11c\ub9cc \uc774\ub8e8\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uad50\uc7ac\uac00 \uc18c\uac1c\ud558\ub294 \uace0\uac1d\uc758 \ud575\uc2ec \uc9c8\ubb38\uc740 \ub450 \uac00\uc9c0\ub85c \uc815\ub9ac\ub41c\ub2e4. \ub0b4\uac00 \uc6d0\ud558\ub294 \uac83\uc774 \uc788\ub294\uac00, \uadf8\ub9ac\uace0 \ud544\uc694\ud560 \ub54c \ubc1b\uc744 \uc218 \uc788\ub294\uac00. \uc0c1\ud488\uc744 \ub9ce\uc774 \ubcf4\uc5ec \uc8fc\ub294 \ub2a5\ub825\uacfc \uc2e4\uc81c\ub85c \uc804\ub2ec\ud558\ub294 \ub2a5\ub825\uc774 \ud568\uaed8 \ud544\uc694\ud558\ub2e4\ub294 \ub73b\uc774\ub2e4. \uccab \uc9c8\ubb38\uc5d0\ub9cc \ub2f5\ud558\uba74 \ubaa9\ub85d\uc774 \ud6cc\ub96d\ud55c \uc804\uc2dc\uc7a5\uc774 \ub420 \uc218 \uc788\ub2e4. \ub450 \ubc88\uc9f8 \uc9c8\ubb38\uc744 \ud574\uacb0\ud558\ub824\uba74 \uc7ac\uace0\uc640 \ubc30\uc1a1, \ub3c4\ucc29\ud560 \uc2dc\uc810\uc744 \ub2e4\ub8e8\uc5b4\uc57c \ud55c\ub2e4. \uace0\uac1d\uc774 \ud3b8\ub9ac\ud558\ub2e4\uace0 \ub290\ub07c\ub294 \uacbd\ud5d8\uc740 \uc774 \ub450 \uac00\uc9c0\uac00 \uc5b4\uae0b\ub098\uc9c0 \uc54a\uc744 \ub54c \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4. \ud654\uba74\uc758 \uac04\uacb0\ud568 \ub4a4\uc5d0\ub294 \ub2e4\ub978 \uc885\ub958\uc758 \ubcf5\uc7a1\ud568\uc774 \uc788\ub2e4. \uc544\ub9c8\uc874\uc758 \ub514\uc9c0\ud138 \ud310\ub9e4\ub294 \uc721\uc9c0\uc758 \ubb3c\ub958 \uac70\uc810\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \ubb3c\ub9ac\uc801\uc778 \uc0c1\ud488\uc744 \ubcf4\uad00\ud558\uace0 \uc8fc\ubb38\uc5d0 \ub9de\ucd94\uc5b4 \ub0b4\ubcf4\ub0b4\uc57c \ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \uace0\uac1d\uc774 \ub9e4\uc7a5 \uc548\uc744 \uac78\uc5b4 \ub2e4\ub2c8\uc9c0 \uc54a\ub294 \ub300\uc2e0 \uc0c1\ud488\uc744 \uc900\ube44\ud558\ub294 \uacf5\uac04\uc740 \ub2e4\ub978 \uacf3\uc5d0 \uc874\uc7ac\ud55c\ub2e4. \uc774 \uc810\uc744 \uc54c\uba74 \uc628\ub77c\uc778\uacfc \uc624\ud504\ub77c\uc778\uc744 \uc644\uc804\ud788 \uac08\ub77c \uc0dd\uac01\ud558\uae30 \uc5b4\ub835\ub2e4. \uc6f9\uc0ac\uc774\ud2b8\uac00 \ubc14\ub00c\ub294 \uc18d\ub3c4\uc640 \ucc3d\uace0\u00b7\uc6b4\uc1a1\uc758 \uc870\uac74\uc740 \ub2e4\ub974\ub2e4. \ud654\uba74\uc5d0\uc11c \ud310\ub9e4 \uc9c0\uc5ed\uc744 \ub113\ud788\ub294 \uac83\uacfc \uadf8 \uc9c0\uc5ed\uc5d0 \uc548\uc815\uc801\uc73c\ub85c \ubb3c\uac74\uc744 \ubcf4\ub0bc \uc218 \uc788\ub294 \uac83\uc740 \uac19\uc740 \uc791\uc5c5\uc774 \uc544\ub2c8\ub2e4. \uad50\uc7ac\ub294 \ud504\ub77c\uc784 \ud68c\uc6d0\uc81c\ub97c \uc544\ub9c8\uc874 \uc804\ub7b5\uc758 \uc911\uc694\ud55c \uc77c\ubd80\ub85c \uc124\uba85\ud55c\ub2e4. \uace0\uac1d\uc774 \uad6c\ub9e4\ud560 \ub54c\ub9c8\ub2e4 \uac1c\ubcc4\uc801\uc73c\ub85c\ub9cc \ud310\ub2e8\ud558\ub294 \uad00\uacc4\uc5d0\uc11c, \uc77c\uc815\ud55c \uc870\uac74\uc758 \uc11c\ube44\uc2a4\ub97c \uacc4\uc18d \uc774\uc6a9\ud558\ub294 \uad00\uacc4\ub85c \ubc14\uafb8\ub294 \ubc29\uc2dd\uc774\ub2e4. \uae30\uc5c5\uc740 \ubc18\ubcf5\ud574\uc11c \ucc3e\uc544\uc624\ub294 \uace0\uac1d\uacfc\uc758 \uc5f0\uacb0\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \uc5ec\uae30\uc11c \ub2f9\uc2dc \ud68c\uc6d0\ube44\ub098 \uc81c\uacf5 \ud61c\ud0dd\uc744 \uc624\ub298\uc758 \uc548\ub0b4\ub85c \uc62e\uae38 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774\ubc88 \uae00\uc740 \uc5ed\uc0ac\uc801 \uacbd\uc601 \uc0ac\ub840\ub97c \ub2e4\ub8ec\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ud68c\uc6d0\uc81c\uac00 \ud654\uba74 \uc704\uc5d0 \ubd99\uc740 \ud560\uc778 \ud45c\uc2dc\ub9cc\uc774 \uc544\ub2c8\ub77c \ubc18\ubcf5 \uc774\uc6a9\uacfc \ubb3c\ub958 \uc11c\ube44\uc2a4\ub97c \ud568\uaed8 \uc0dd\uac01\ud558\uac8c \ud558\ub294 \uc0ac\uc5c5 \uad6c\uc870\uc600\ub2e4\ub294 \uc810\uc774\ub2e4. \ubb3c\uac74\uc744 \ube68\ub9ac \ubc1b\ub294 \uacbd\ud5d8\uc740 \ud3b8\ub9ac\ud558\ub2e4. \ud558\uc9c0\ub9cc \uc18d\ub3c4\ub97c \ub192\uc774\ub824\uba74 \uc6b4\uc601\uc5d0 \ud544\uc694\ud55c \uc790\uc6d0\uacfc \ube44\uc6a9\uc774 \uc0dd\uae34\ub2e4. \uad50\uc7ac\ub294 \uc544\ub9c8\uc874\uc758 \uacfc\uc81c\ub85c \ub192\uc740 \ubc30\uc1a1 \ube44\uc6a9\ub3c4 \ud568\uaed8 \uc18c\uac1c\ud55c\ub2e4. \uc8fc\ubb38\uc774 \ub9ce\uc544\uc84c\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc8fc\ubb38\uc774 \uac19\uc740 \ub9cc\ud07c \uc774\uc775\uc744 \ub0a8\uae34\ub2e4\uace0 \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uace0\uac1d\uc774 \ub290\ub07c\ub294 \uc9e7\uc740 \uae30\ub2e4\ub9bc\uc740 \uae30\uc5c5\uc774 \ubbf8\ub9ac \uc900\ube44\ud55c \uacf5\uac04\uacfc \uc791\uc5c5\uc758 \uacb0\uacfc\uc77c \uc218 \uc788\ub2e4. \uc774\uac83\uc740 \ud2b9\uc815 \ubc30\uc1a1\uc758 \ub0b4\ubd80 \uc6d0\uac00\ub97c \uacc4\uc0b0\ud55c \uc124\uba85\uc740 \uc544\ub2c8\ub2e4. \ud3b8\ub9ac\ud568\uc758 \uac00\uaca9\uc774 \uc5b4\ub514\uc5d0 \ub193\uc774\ub294\uc9c0 \uc9c8\ubb38\ud558\ub294 \uad00\uc810\uc774\ub2e4. \ud654\uba74\uc5d0\uc11c \ubb34\ub8cc\ub85c \ubcf4\uc774\ub294 \uc11c\ube44\uc2a4\uc640 \ud604\uc2e4\uc5d0\uc11c \ube44\uc6a9\uc774 \ub4e4\uc9c0 \uc54a\ub294 \uc11c\ube44\uc2a4\ub294 \ub2e4\ub974\ub2e4. \ud574\ub2f9 \uc0ac\ub840\ub294 \ubb3c\ub958 \uacf5\uac04\uc5d0\uc11c \uc0ac\ub78c\uacfc \ub85c\ubd07\uc774 \ud568\uaed8 \uc77c\ud558\ub294 \ubaa8\uc2b5\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc790\ub3d9\ud654\uac00 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud558\ub354\ub77c\ub3c4 \uc8fc\ubb38 \ud558\ub098\uac00 \uc544\ubb34\ub7f0 \uc0ac\ub78c\uc758 \uc77c \uc5c6\uc774 \ucc98\ub9ac\ub41c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc744 \uae30\uacc4\uac00 \ub9e1\uace0 \ubb34\uc5c7\uc744 \uc0ac\ub78c\uc774 \ub9e1\ub294\uc9c0 \ubcc4\ub3c4\ub85c \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uae30\uc220\uc744 \ub3c4\uc785\ud588\ub2e4\ub294 \uc18c\uc2dd\ub9cc \ub4e4\uc73c\uba74 \uc804\uccb4 \uacfc\uc815\uc774 \ud55c \ubc88\uc5d0 \ubc14\ub010 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uc2e4\uc81c\ub85c\ub294 \uae30\uc874 \uc791\uc5c5\uacfc \uc0c8\ub85c\uc6b4 \uc7a5\uce58\uac00 \ud568\uaed8 \ub3cc\uc544\uac08 \uc218 \uc788\ub2e4. \uc5b4\ub290 \ud55c \ucc3d\uace0\uc758 \uc124\ube44\ub97c \ub2e4\ub978 \ubaa8\ub4e0 \uacf3\uc5d0 \uc801\uc6a9\ud558\ub294 \uc2dd\uc73c\ub85c \ub113\ud600 \ub9d0\ud560 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \uc774\ubc88 \uadf8\ub9bc \uc5ed\uc2dc \ud2b9\uc815 \ud604\uc7a5\uc744 \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uad50\uc7ac\ub294 \ub2f9\uc2dc \ubb3c\ub958 \ud604\uc7a5\uc758 \ub178\ub3d9 \uc870\uac74\uacfc \ubc30\uc1a1 \uacc4\uc57d\uc790\ub4e4\uc758 \ubd80\ub2f4\uc5d0 \ub300\ud55c \ube44\ud310\ub3c4 \ub2e4\ub8ec\ub2e4. \uc11c\ube44\uc2a4\uc758 \uc18d\ub3c4\ub97c \ud3c9\uac00\ud560 \ub54c \uace0\uac1d\uc774 \uae30\ub2e4\ub9b0 \uc2dc\uac04\ub9cc \ubcfc \uc218\ub294 \uc5c6\ub2e4\ub294 \ub73b\uc774\ub2e4. \uadf8 \uc2dc\uac04\uc744 \uc904\uc774\ub294 \uacfc\uc815\uc5d0\uc11c \uc77c\ud558\ub294 \uc0ac\ub78c\uc758 \uacbd\ud5d8\ub3c4 \uc0dd\uae34\ub2e4. \uc774\uac83\uc740 \uae30\uc5c5\uc758 \ubaa8\ub4e0 \ud65c\ub3d9\uc744 \ud55c \uac00\uc9c0 \ud3c9\uac00\ub85c \ub05d\ub0b4\ub824\ub294 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \ub9e4\ucd9c\uacfc \uc774\uc6a9\uc790\uc758 \ub9cc\uc871\uc774 \ub192\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uadfc\ubb34 \uc870\uac74\uc5d0 \uad00\ud55c \uc9c8\ubb38\uc744 \uc790\ub3d9\uc73c\ub85c \ud574\uacb0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uac19\uc740 \uc0ac\uc5c5\uc744 \uace0\uac1d\uacfc \uc9c1\uc6d0, \uc8fc\ubcc0\uc758 \ub2e4\ub978 \uae30\uc5c5\uc774 \uc11c\ub85c \ub2e4\ub978 \uc790\ub9ac\uc5d0\uc11c \uacbd\ud5d8\ud560 \uc218 \uc788\ub2e4. \uc628\ub77c\uc778 \ud310\ub9e4\uac00 \ucee4\uc9c0\uba74 \uace0\uac1d\ubfd0 \uc544\ub2c8\ub77c \ub2e4\ub978 \ud310\ub9e4\uc790\uc758 \ud658\uacbd\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uad50\uc7ac\ub294 \ub3c5\ub9bd \uc0ac\uc5c5\uc790\ub4e4\uc774 \uc544\ub9c8\uc874\uacfc\uc758 \uacbd\uc7c1\uc744 \uc911\uc694\ud55c \ubb38\uc81c\ub85c \ubcf4\uc558\ub358 \uc0ac\ub840\ub97c \uc18c\uac1c\ud55c\ub2e4. \ud55c \uae30\uc5c5\uc758 \ud3b8\ub9ac\ud55c \uc11c\ube44\uc2a4\uac00 \uc2dc\uc7a5\uc758 \ub2e4\ub978 \ucc38\uc5ec\uc790\uc5d0\uac8c\ub294 \uc0c8\ub85c\uc6b4 \ub300\uc751\uc744 \uc694\uad6c\ud560 \uc218 \uc788\uc5c8\ub2e4. \uc774 \uad00\uacc4\ub97c \uc131\uacf5\ud55c \ud68c\uc0ac\uc640 \ub4a4\ucc98\uc9c4 \uac00\uac8c\ub77c\ub294 \ub450 \uce78\uc73c\ub85c\ub9cc \uc815\ub9ac\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uaddc\ubaa8\uc640 \ubc30\uc1a1 \uccb4\uacc4, \uace0\uac1d\uc774 \ucc3e\uc544\uc624\ub294 \uacbd\ub85c\uac00 \ub2e4\ub974\uba74 \uc120\ud0dd\ud560 \uc218 \uc788\ub294 \ubc29\ubc95\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uae30\uc5c5 \uc774\uc57c\uae30\ub97c \uc77d\ub294 \uc7ac\ubbf8\ub294 \ud55c \ud68c\uc0ac\uc758 \uc131\uc7a5\ubfd0 \uc544\ub2c8\ub77c \uadf8 \uc8fc\ubcc0\uc758 \uad00\uacc4\uac00 \ubc14\ub00c\ub294 \ub370\ub3c4 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc0c1\ud488\uc744 \ud655\uc778\ud558\uace0 \ud3ec\uc7a5\ud558\ub294 \uc791\uc5c5\uc7a5\uc758 \ubd84\uc704\uae30\ub97c \ud45c\ud604\ud588\ub2e4. \uc544\ub9c8\uc874\uc758 \uc2e4\uc81c \uc9c1\uc6d0\u00b7\ucc3d\uace0\u00b7\ud604\uc7ac \ud45c\uc900 \uc791\uc5c5\uc744 \uc7ac\ud604\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ud654\uba74\uc5d0\uc11c \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc900\ube44\uc640 \uc0ac\ub78c\uc758 \uc190\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc704\ud55c \uadf8\ub9bc\uc774\ub2e4. \uc774 \uc0ac\ub840\ub294 \uc778\ud130\ub137 \uae30\uc5c5\uc758 \uacbd\uc7c1\ub825\uc774 \ud654\uba74 \ub514\uc790\uc778\uc5d0\ub9cc \uc788\uc9c0 \uc54a\ub2e4\ub294 \uc810\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc8fc\ubb38\uc774 \ud604\uc2e4\uc758 \ubb3c\uac74\uacfc \ub9cc\ub098\ub294 \uc5f0\uacb0\ub3c4 \uc124\uacc4\ud574\uc57c \ud588\ub2e4. \ub2e4\uc74c\uc5d0 \uc791\uc740 \uc0c1\uc790\ub97c \ubc1b\uc744 \ub54c\ub294 \uc7ac\uc0dd\ub418\ub294 \uc54c\ub9bc\ubfd0 \uc544\ub2c8\ub77c, \uadf8 \uc0c1\uc790\uac00 \ud654\uba74\uc5d0\uc11c \ubb38 \uc55e\uae4c\uc9c0 \uc624\ub294 \ub3d9\uc548 \uac70\ucce4\uc744 \uc77c\ub4e4\ub3c4 \uc7a0\uae50 \uc0dd\uac01\ud574 \ubcfc \ub9cc\ud558\ub2e4."}, {"id": "away-suitcase-and-travel-book", "title": "\uc5b4\uc6e8\uc774 \u2014 \uc5ec\ud589\uac00\ubc29\ubcf4\ub2e4 \uc5ec\ud589 \ucc45\uc774 \uba3c\uc800 \ub3c4\ucc29\ud588\ub2e4", "summary": "\uc5b4\uc6e8\uc774\uc758 2015~2016\ub144 \ucd08\uae30 \uc0ac\ub840\ub97c \ud1b5\ud574 \uace0\uac1d \uc870\uc0ac\u00b7\uc81c\uc870 \uc120\ud0dd\u00b7\uc608\uc57d \ud310\ub9e4\uc640 \uc2a4\ud1a0\ub9ac\ud154\ub9c1\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\ube0c\ub79c\ub4dc\uc640 \uc18c\ube44", "categories": ["industry"], "url": "stories/away-suitcase-and-travel-book/index.html", "image": "../media/away-suitcase-and-travel-book.png", "alt": "\uc5ec\ud589\uac00\ubc29\uacfc \ucc45 \uacc1\uc5d0\uc11c \ub450 \uc0ac\ub78c\uc774 \uac00\ubc29 \uc2dc\uc81c\ud488\uc744 \uc758\ub17c\ud558\ub294 AI \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\uc5b4\uc6e8\uc774 \u2014 \uc5ec\ud589\uac00\ubc29\ubcf4\ub2e4 \uc5ec\ud589 \ucc45\uc774 \uba3c\uc800 \ub3c4\ucc29\ud588\ub2e4 \uace0\uc7a5 \ub09c \uac00\ubc29\uc5d0\uc11c \uc81c\ud488\uacfc \uc774\uc57c\uae30\ub97c \ud568\uaed8 \ub9cc\ub4e4\uae30\uae4c\uc9c0 \uc5b4\uc6e8\uc774\uc758 2015~2016\ub144 \ucd08\uae30 \uc0ac\ub840\ub97c \ud1b5\ud574 \uace0\uac1d \uc870\uc0ac\u00b7\uc81c\uc870 \uc120\ud0dd\u00b7\uc608\uc57d \ud310\ub9e4\uc640 \uc2a4\ud1a0\ub9ac\ud154\ub9c1\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ube0c\ub79c\ub4dc\uc640 \uc18c\ube44 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \uc5ec\ud589\uc744 \ub5a0\ub0ac\ub294\ub370 \uac00\ubc29\uc774 \uace0\uc7a5 \ub09c\ub2e4. \ubc14\ud034\ub098 \uc190\uc7a1\uc774 \ub54c\ubb38\uc5d0 \uc9d0\uc744 \uc62e\uae30\ub294 \uc77c\uc774 \uac11\uc790\uae30 \ud798\ub4e4\uc5b4\uc9c0\uba74, \ud3c9\uc18c\uc5d0\ub294 \ubcc4\uc0dd\uac01 \uc5c6\ub358 \uc5ec\ud589\uac00\ubc29\uc758 \uc911\uc694\uc131\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \uc81c\ub2c8\ud37c \ub8e8\ube44\uc624\uc5d0\uac8c\ub294 \uc774\ub7f0 \ubd88\ud3b8\uc774 \uc0c8\ub85c\uc6b4 \uc0ac\uc5c5\uc744 \uc0dd\uac01\ud558\ub294 \uacc4\uae30\uac00 \ub418\uc5c8\ub2e4. \ub8e8\ube44\uc624\ub294 \uc2a4\ud14c\ud37c\ub2c8 \ucf54\ub9ac\uc640 \ud568\uaed8 \uc5b4\uc6e8\uc774\ub77c\ub294 \uc5ec\ud589\uac00\ubc29 \ud68c\uc0ac\ub97c \uc900\ube44\ud588\ub2e4. \uadf8\ub7f0\ub370 \ucd08\uae30 \uace0\uac1d \uc911\uc5d0\ub294 \uac00\ubc29\ubcf4\ub2e4 \uba3c\uc800 \uc5ec\ud589 \uc774\uc57c\uae30\ub97c \ub2f4\uc740 \ucc45\uc744 \ubc1b\uc740 \uc0ac\ub78c\ub4e4\uc774 \uc788\uc5c8\ub2e4. \uc544\uc9c1 \ubcf4\ub0b4 \uc904 \uc81c\ud488\uc774 \uc5c6\uc744 \ub54c \ubb34\uc5c7\uc73c\ub85c \uae30\ub300\ub97c \ub9cc\ub4e4 \uac83\uc778\uac00\ub77c\ub294 \uc9c8\ubb38\uc5d0\uc11c \ub098\uc628 \uc120\ud0dd\uc774\uc5c8\ub2e4. OpenStax \uacbd\uc601\ud559 \uad50\uc7ac\ub294 \ub450 \uc0ac\ub78c\uc774 2015\ub144\uc5d0 \uac00\ubc29 \uc2dc\uc7a5\uc744 \uc870\uc0ac\ud558\uae30 \uc2dc\uc791\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub2f9\uc2dc \ub8e8\ube44\uc624\ub294 \uc800\ub834\ud558\uc9c0\ub9cc \ud488\uc9c8\uc774 \uc544\uc26c\uc6b4 \uc81c\ud488\uacfc \ub192\uc740 \ud488\uc9c8\uc774\uc9c0\ub9cc \ube44\uc2fc \uc81c\ud488 \uc0ac\uc774\uc5d0 \uc5ec\uc9c0\uac00 \uc788\ub2e4\uace0 \ubcf4\uc558\ub2e4. \uc774\uac83\uc740 \ucc3d\uc5c5\uc790\uac00 \ubc1c\uacac\ud55c \uc2dc\uc7a5\uc758 \uae30\ud68c\uc774\uc9c0 \ubaa8\ub4e0 \uac00\ubc29\uc758 \uac1d\uad00\uc801\uc778 \ub4f1\uae09\ud45c\ub294 \uc544\ub2c8\ub2e4. \ub450 \uc0ac\ub78c\uc740 \uac00\uaca9\uc758 \uc774\uc720\ub97c \uc81c\ud488 \uc790\uccb4\uc5d0\uc11c\ub9cc \ucc3e\uc9c0 \uc54a\uc558\ub2e4. \uc804\ubb38\uc810\uacfc \ubc31\ud654\uc810 \ub4f1\uc744 \uac70\uce58\ub294 \uc720\ud1b5 \uad6c\uc870\uac00 \ucd5c\uc885 \uac00\uaca9\uc5d0 \uc5b4\ub5a4 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294\uc9c0\ub3c4 \uc0b4\ud3c8\ub2e4. \uc18c\ube44\uc790\uc5d0\uac8c \uc9c1\uc811 \ud310\ub9e4\ud558\uba74 \ub2e4\ub978 \uac00\uaca9\ub300\uc758 \uc81c\ud488\uc744 \uc81c\uc548\ud560 \uc218 \uc788\uaca0\ub2e4\ub294 \uad6c\uc0c1\uc774 \uc5ec\uae30\uc11c \ub098\uc654\ub2e4. \ucc3d\uc5c5 \uacc4\uae30\uac00 \uc0dd\uacbc\ub2e4\uace0 \ubc14\ub85c \uc81c\ud488\uc744 \ub9cc\ub4e4\uc9c0\ub294 \uc54a\uc558\ub2e4. \ub450 \uc0ac\ub78c\uc740 \uc218\ubc31 \uba85\uc5d0\uac8c \uae30\uc874 \uac00\ubc29\uc5d0\uc11c \ubb34\uc5c7\uc774 \uc88b\uace0 \ubb34\uc5c7\uc774 \uac00\uc7a5 \uc131\uac00\uc2e0\uc9c0 \ubb3c\uc5c8\ub2e4. \uc790\uc2e0\uc758 \uc5ec\ud589 \uacbd\ud5d8\uc744 \ucd9c\ubc1c\uc810\uc73c\ub85c \uc0bc\ub418 \ub2e4\ub978 \uc0ac\ub78c\uc758 \ud544\uc694\ub3c4 \uc54c\uc544\ubcf4\ub824 \ud55c \uac83\uc774\ub2e4. \uc774 \ucc28\uc774\ub294 \uc0dd\uac01\ubcf4\ub2e4 \uc911\uc694\ud558\ub2e4. \ub098\uc5d0\uac8c \ub2f5\ub2f5\ud55c \uc810\uc774 \ub9ce\uc740 \uace0\uac1d\uc5d0\uac8c\ub3c4 \uc911\uc694\ud55c \ubb38\uc81c\uc778\uc9c0 \ud655\uc778\ud574\uc57c \ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \uc5b4\ub5a4 \ubc14\ud034\ub97c \uc4f8\uc9c0, \ubb34\uac8c\uc640 \uc678\ud615\uc744 \uc5b4\ub5bb\uac8c \ub9de\ucd9c\uc9c0 \uac19\uc740 \uacb0\uc815\uc740 \uace0\uac1d\uc758 \ub9d0\uc744 \uc2e4\uc81c \ubb3c\uac74\uc758 \uc120\ud0dd\uc73c\ub85c \uc62e\uae30\ub294 \uacfc\uc815\uc774\uc5c8\ub2e4. \uc778\ud130\ubdf0\ub294 \uc81c\ud488\uc744 \ub300\uc2e0 \ub9cc\ub4e4\uc5b4 \uc8fc\uc9c0 \uc54a\uc9c0\ub9cc \uacb0\uc815\uc758 \uadfc\uac70\uac00 \ub420 \uc218 \uc788\ub2e4. \ub8e8\ube44\uc624\ub294 \ube0c\ub79c\ub4dc\uc640 \ub9c8\ucf00\ud305 \ucabd, \ucf54\ub9ac\ub294 \uc6b4\uc601\uacfc \uacf5\uae09\ub9dd \ucabd\uc758 \uacbd\ud5d8\uc744 \uac16\uace0 \uc788\uc5c8\ub2e4. \ub450 \uc0ac\ub78c \ubaa8\ub450 \uc804\uc790\uc0c1\uac70\ub798 \uae30\uc5c5\uc5d0\uc11c \uc77c\ud55c \uacbd\ud5d8\ub3c4 \uc788\uc5c8\ub2e4. \uac19\uc740 \uc81c\ud488\uc744 \ubcf4\uba74\uc11c \ubb34\uc5c7\uc744 \uace0\uac1d\uc5d0\uac8c \ub9d0\ud560\uc9c0\uc640 \uc5b4\ub5bb\uac8c \ub9cc\ub4e4\uc5b4 \uc804\ub2ec\ud560\uc9c0\ub97c \ub2e4\ub978 \uac01\ub3c4\uc5d0\uc11c \uc0dd\uac01\ud560 \uc218 \uc788\uc5c8\ub2e4. \uac00\ubc29\uc744 \ub9cc\ub4dc\ub294 \ud68c\uc0ac\ub77c\uace0 \ub514\uc790\uc778\ub9cc \uc798\ud558\uba74 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0dd\uc0b0\ud560 \uacf3\uc744 \ucc3e\uace0 \ube44\uc6a9\uc744 \ub9c8\ub828\ud558\uba70 \uace0\uac1d\uc744 \ub9cc\ub098\uc57c \ud55c\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ub2a5\ub825\uc744 \ud568\uaed8 \uc4f0\ub294 \uc77c\uc740 \ucc3d\uc5c5\uc790\uc758 \uac1c\uc778\uc801\uc778 \uc601\uac10\ub9cc\ud07c \uc911\uc694\ud588\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \ubb3c\uac74 \ud558\ub098\uc758 \ub4a4\uc5d0\ub294 \uc5ec\ub7ec \uc885\ub958\uc758 \ud310\ub2e8\uc774 \ud544\uc694\ud558\ub2e4. \ub450 \uc0ac\ub78c\uc740 \uc81c\uc870 \ud30c\ud2b8\ub108\ub3c4 \uc870\uc0ac\ud588\ub2e4. \ub2e8\ub2e8\ud55c \ud3f4\ub9ac\uce74\ubcf4\ub124\uc774\ud2b8 \uc678\uc7a5\uc744 \ub9cc\ub4dc\ub294 \ud6c4\ubcf4 \uc5c5\uccb4\ub4e4\uc774 \uc544\uc2dc\uc544\uc5d0 \ub9ce\uc558\uace0, \uc5ec\ub7ec \uacf3\uc744 \ube44\uad50\ud55c \ub4a4 \uc9c1\uc811 \ubc29\ubb38\ud588\ub2e4. \uc790\ub8cc\uc5d0\uc11c \uc88b\uc740 \uc778\uc0c1\uc744 \uc8fc\ub294 \uc5c5\uccb4\uac00 \ud604\uc7a5\uc5d0\uc11c\ub3c4 \ubc18\ub4dc\uc2dc \uac19\uc740 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4\uace0 \uad50\uc7ac\ub294 \uc124\uba85\ud55c\ub2e4. \uacb0\uad6d \uc911\uad6d\uc758 \uc81c\uc870 \ud30c\ud2b8\ub108\uc640 \ud611\ub825\ud588\uc73c\uba70 \uad00\uacc4\ub97c \uc720\uc9c0\ud558\ub294 \ub370\ub3c4 \uc2dc\uac04\uc744 \ub4e4\uc600\ub2e4. \uc81c\ud488\uc744 \uc678\ubd80 \uacf5\uc7a5\uc5d0\uc11c \ub9cc\ub4e0\ub2e4\uace0 \ucc3d\uc5c5\uc790\uc758 \uc77c\uc774 \ub05d\ub098\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uae30\uc900\uc744 \uacf5\uc720\ud558\uace0 \ubb38\uc81c\uac00 \uc0dd\uae38 \ub54c \uc5b4\ub5bb\uac8c \uc18c\ud1b5\ud560\uc9c0\ub3c4 \uc0ac\uc5c5\uc758 \uc77c\ubd80\ub2e4. \ube0c\ub79c\ub4dc\uc758 \uac89\ubaa8\uc2b5\uacfc \uc0dd\uc0b0\uc758 \uc870\uac74\uc774 \uc5ec\uae30\uc11c \uc5f0\uacb0\ub41c\ub2e4. 2015\ub144 \ub9d0\uc5d0\ub294 \uccab \uc81c\ud488\uc774 \uc900\ube44\ub418\ub294 \uc911\uc774\uc5c8\uc9c0\ub9cc \uc5f0\ub9d0 \uc120\ubb3c \uc2dc\uae30\uc5d0 \ub9de\ucd94\uc5b4 \uac00\ubc29\uc744 \uacf5\uae09\ud558\uae30 \uc5b4\ub824\uc6e0\ub2e4. \uc544\uc9c1 \uc5c6\ub294 \ubb3c\uac74\uc744 \uc774\ubbf8 \uc788\ub294 \uac83\ucc98\ub7fc \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub450 \uc0ac\ub78c\uc740 \uc608\uc57d \uad6c\ub9e4\uc640 \ud568\uaed8 \uc81c\uacf5\ud560 \ub2e4\ub978 \ud615\ud0dc\uc758 \uacbd\ud5d8\uc744 \uc0dd\uac01\ud588\ub2e4. \uadf8 \uacb0\uacfc\uac00 \uc5ec\ud589\uc744 \uc8fc\uc81c\ub85c \ud55c \ucc45\uc774\uc5c8\ub2e4. \uc5ec\ub7ec \ucc3d\uc791\uc790\uc5d0\uac8c \uc5ec\ud589 \uacbd\ud5d8\uc744 \uc778\ud130\ubdf0\ud574 \u300aThe Places We Return To\u300b\ub77c\ub294 \ud558\ub4dc\ucee4\ubc84 \ucc45\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \uad50\uc7ac\uc5d0 \ub530\ub974\uba74 40\uba85\uc758 \uc774\uc57c\uae30\ub97c \ub2f4\uc558\ub2e4. \uc5ec\ud589\uac00\ubc29\uc744 \ubc14\ub85c \ud3bc\uce60 \uc218 \uc5c6\ub294 \uace0\uac1d\uc5d0\uac8c \uc5ec\ud589\uc774\ub77c\ub294 \uc8fc\uc81c\uc758 \uc77d\uc744\uac70\ub9ac\ub97c \uba3c\uc800 \uac74\ub128 \uc148\uc774\ub2e4. \ub2f9\uc2dc \uc81c\uc548\uc740 \uac00\ubc29 \uc790\uccb4\ub97c \uc989\uc2dc \ubc1b\ub294 \ubc29\uc2dd\uc774 \uc544\ub2c8\uc5c8\ub2e4. 2015\ub144 11\uc6d4\ubd80\ud130 \ud5a5\ud6c4 \uac00\ubc29\uc744 \ubc1b\uc744 \uc218 \uc788\ub294 \uae30\ud504\ud2b8\uce74\ub4dc\ub97c \uad6c\uc785\ud558\uba74 \uc5ec\ud589 \ucc45\uc744 \ud568\uaed8 \ubc1b\uc558\uace0, \uac00\ubc29\uc73c\ub85c \uad50\ud658\ud560 \uc2dc\uc810\uc740 2016\ub144 2\uc6d4\ub85c \uc548\ub0b4\ub418\uc5c8\ub2e4. \ubb3c\uac74\uacfc \uc57d\uc18d\uc758 \uc2dc\uac04\uc744 \uad6c\ubd84\ud574 \uc124\uba85\ud55c \ubc29\uc2dd\uc774\ub2e4. \ucc45\uc740 \uac00\ubc29\uc758 \ubc14\ud034 \uc131\ub2a5\uc744 \uc99d\uba85\ud558\ub294 \uc2dc\ud5d8 \uc131\uc801\uc11c\ub294 \uc544\ub2c8\ub2e4. \ub300\uc2e0 \ube0c\ub79c\ub4dc\uac00 \uc5b4\ub5a4 \uc5ec\ud589\uc744 \uc774\uc57c\uae30\ud558\uace0 \uc2f6\uc740\uc9c0 \ubcf4\uc5ec \uc8fc\uace0, \uc81c\ud488\uc744 \uae30\ub2e4\ub9ac\ub294 \ub3d9\uc548 \uad00\uc2ec\uc744 \uc774\uc5b4 \uc8fc\uc5c8\ub2e4. \uc0ac\ub78c\ub4e4\uc5d0\uac8c \ub9d0\uc744 \uac70\ub294 \ubc29\uc2dd\uacfc \uc2e4\uc81c\ub85c \ubc30\uc1a1\ud574\uc57c \ud558\ub294 \uc758\ubb34\ub294 \uac01\uac01 \uc874\uc7ac\ud588\ub2e4. \uc774 \uc0ac\ub840\ub97c \uc2a4\ud1a0\ub9ac\ud154\ub9c1\ub9cc \uc798\ud558\uba74 \ubb3c\uac74 \uc5c6\uc774\ub3c4 \uc131\uacf5\ud55c\ub2e4\ub294 \uacf5\uc2dd\uc73c\ub85c \uc77d\uc73c\uba74 \uc911\uc694\ud55c \ubd80\ubd84\uc774 \ube60\uc9c4\ub2e4. \uadf8\uc804\uc5d0 \uace0\uac1d \uc870\uc0ac\uc640 \uc2dc\uc81c\ud488 \uac1c\ubc1c, \uc81c\uc870 \ud30c\ud2b8\ub108 \uc120\ud0dd\uc774 \uc788\uc5c8\ub2e4. \ucc45\uc774 \uad00\uc2ec\uc744 \ub9cc\ub4e4\ub354\ub77c\ub3c4 \ub098\uc911\uc5d0 \ubc1b\uc744 \uac00\ubc29\uc774 \uace0\uac1d\uc758 \uae30\ub300\uc5d0 \ub9de\uc544\uc57c \uad00\uacc4\uac00 \uc774\uc5b4\uc9c8 \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 \ucd08\uae30 \ucc45 1,200\ubd80\uac00 \ubaa8\ub450 \ud310\ub9e4\ub418\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc774\ub294 \ub2f9\uc2dc \ucd9c\ubc1c\uc744 \uc124\uba85\ud558\ub294 \uc218\uce58\uc774\uba70 \uc624\ub298\ub0a0 \ud68c\uc0ac\uc758 \uc804\uccb4 \uc131\uacfc\ub97c \ub73b\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc774\ubc88 \uae00\ub3c4 2015~2016\ub144 \ucd08\uae30 \uc0ac\ub840\ub97c \uc77d\ub294 \uac83\uc73c\ub85c, \ud604\uc7ac \uc81c\ud488\uc758 \uac00\uaca9\uc774\ub098 \uae30\ub2a5, \ubc30\uc1a1 \uc870\uac74\uc744 \uc548\ub0b4\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uac00\ubc29\uacfc \uc5ec\ud589 \ucc45, \uc81c\ud488\uc744 \uc758\ub17c\ud558\ub294 \uc0ac\ub78c\uc758 \ubaa8\uc2b5\uc744 \ub2f4\uc558\ub2e4. \uc2e4\uc81c \ucc3d\ub9bd\uc790\uc758 \ucd08\uc0c1\uc774\ub098 \ucd08\uae30 \uac00\ubc29\uacfc \ucc45\uc758 \uc815\ud655\ud55c \ub514\uc790\uc778\uc744 \uc7ac\ud604\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ubb3c\uac74\uc744 \ub9cc\ub4e4\uae30 \uc804\ud6c4\uc5d0 \uc5b4\ub5a4 \uc0dd\uac01\uc774 \uc624\uac14\uc744\uc9c0 \ub5a0\uc62c\ub9ac\ub294 \ubd84\uc704\uae30 \uadf8\ub9bc\uc774\ub2e4. \uc5b4\uc6e8\uc774\uc758 \ucd08\uae30 \uc774\uc57c\uae30\ub294 \uc88b\uc740 \uc81c\ud488\uacfc \uc88b\uc740 \uc774\uc57c\uae30\uac00 \uacbd\uc7c1\ud574\uc57c \ud558\ub294 \uac83\uc774 \uc544\ub2d8\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uac00\ubc29\uc740 \uc5ec\ud589\uc758 \uc9d0\uc744 \ub2f4\uace0 \ucc45\uc740 \uc5ec\ud589\uc758 \uae30\uc5b5\uc744 \ub2f4\uc558\ub2e4. \ub458\uc744 \uc5f0\uacb0\ud55c \uc120\ud0dd\uc774 \ud765\ubbf8\ub85c\uc6b4 \uc774\uc720\ub294 \ubb3c\uac74 \ud558\ub098\ub97c \ud314\uae30 \uc704\ud574\uc11c\ub3c4 \uc0ac\ub78c\uc758 \ubd88\ud3b8\uacfc \uae30\ub300, \uae30\ub2e4\ub9ac\ub294 \uc2dc\uac04\uae4c\uc9c0 \uc0dd\uac01\ud574\uc57c \ud588\uae30 \ub54c\ubb38\uc774\ub2e4."}, {"id": "bessemer-converter-air-and-steel-production", "title": "\ubca0\uc11c\uba38 \uc804\ub85c \u2014 \uacf5\uae30\ub97c \ubd88\uc5b4\ub123\uc790 \ucca0\uac15 \uacf5\uc7a5\uc758 \uc2dc\uac04\uc774 \ub2ec\ub77c\uc84c\ub2e4", "summary": "\uacf5\uae30\uc640 \uae08\uc18d\uc758 \ubc18\uc751, \uae30\uc6b8\uc774\ub294 \uc804\ub85c\uc640 \ud6c4\uc18d \uac1c\uc120\uc73c\ub85c \uac15\ucca0 \uc0dd\uc0b0\uc774 \ub2ec\ub77c\uc9c4 \uacfc\uc815\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\uacf5\uc7a5\uacfc \uc0dd\uc0b0", "categories": ["industry"], "url": "stories/bessemer-converter-air-and-steel-production/index.html", "image": "../media/bessemer-converter-air-and-steel-production.jpg", "alt": "\uacf5\uae30\ub97c \ubd88\uc5b4\ub123\ub294 \ubca0\uc11c\uba38 \uc804\ub85c\uc640 \uc704\ub85c \uc19f\ub294 \ubd88\uaf43\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc5ed\uc0ac \ub3c4\ud310", "text": "\ubca0\uc11c\uba38 \uc804\ub85c \u2014 \uacf5\uae30\ub97c \ubd88\uc5b4\ub123\uc790 \ucca0\uac15 \uacf5\uc7a5\uc758 \uc2dc\uac04\uc774 \ub2ec\ub77c\uc84c\ub2e4 \uc804\ub85c\uc758 \uad6c\uc870\uc640 \ubc18\uc751, \uc131\ubd84 \uc870\uc815\uc774 \ubc14\uafbc \uacf5\uc7a5\uc758 \uc2dc\uac04 \uacf5\uae30\uc640 \uae08\uc18d\uc758 \ubc18\uc751, \uae30\uc6b8\uc774\ub294 \uc804\ub85c\uc640 \ud6c4\uc18d \uac1c\uc120\uc73c\ub85c \uac15\ucca0 \uc0dd\uc0b0\uc774 \ub2ec\ub77c\uc9c4 \uacfc\uc815\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uacf5\uc7a5\uacfc \uc0dd\uc0b0 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \ucca0\uacfc \uac15\ucca0\uc740 \ubaa8\ub450 \uae08\uc18d\uc774\uc9c0\ub9cc \uc131\ubd84\uacfc \uc131\uc9c8\uc774 \uac19\uc9c0 \uc54a\ub2e4. \uc6d0\ud558\ub294 \uc131\uc9c8\uc758 \uac15\ucca0\uc744 \ub9ce\uc774, \uc77c\uc815\ud558\uac8c \ub9cc\ub4dc\ub294 \uc77c\uc740 \ud070 \uc0b0\uc5c5\uc801 \uacfc\uc81c\uc600\ub2e4. \ubca0\uc11c\uba38 \uc804\ub85c\ub294 \ub179\uc740 \uae08\uc18d\uc5d0 \uacf5\uae30\ub97c \ubd88\uc5b4\ub123\ub294 \ubc29\uc2dd\uc73c\ub85c \uadf8 \uacfc\uc815\uc744 \ubc14\uafb8\uc5c8\ub2e4. \uac70\ub300\ud55c \ubd88\uaf43 \ub4a4\uc5d0\uc11c \uc5b4\ub5a4 \uc0dd\uc0b0\uc758 \ubb38\uc81c\uac00 \ud574\uacb0\ub418\uc5c8\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uace0\ub85c\uc5d0\uc11c \ub098\uc628 \uc120\ucca0\uc5d0\ub294 \ud0c4\uc18c\uc640 \uc5ec\ub7ec \uc131\ubd84\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uc774\ub97c \uc5b4\ub5a4 \uc0c1\ud0dc\ub85c \uc870\uc815\ud558\ub290\ub0d0\uc5d0 \ub530\ub77c \ub2e4\ub978 \uc131\uc9c8\uc758 \uc7ac\ub8cc\uac00 \ub41c\ub2e4. \uac15\ucca0 \uc0dd\uc0b0\uc740 \ucca0\uc744 \ub354 \ub728\uac81\uac8c \ub9cc\ub4e4\uae30\ub9cc \ud558\ub294 \uc77c\ubcf4\ub2e4 \uc131\ubd84\uc744 \ub2e4\ub8e8\ub294 \uc77c\uc5d0 \uac00\uae5d\ub2e4. \uc7ac\ub8cc\uc758 \uc774\ub984\uc740 \uc0dd\uc0b0 \uacfc\uc815\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uac19\uc740 \ubaa9\uc801\uc758 \uc81c\ud488\uc744 \ub9ce\uc774 \ub9cc\ub4e4\ub824\uba74 \ud55c \ubc88 \uc88b\uc740 \uae08\uc18d\uc744 \uc5bb\ub294 \uac83\uc73c\ub85c \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4. \ub2e4\uc74c \uc0dd\uc0b0\uc5d0\uc11c\ub3c4 \uc4f8 \ub9cc\ud55c \uacb0\uacfc\uac00 \ub098\uc640\uc57c \ud55c\ub2e4. \uc591\uacfc \uc18d\ub3c4, \ud488\uc9c8\uc758 \ubc18\ubcf5\uc131\uc744 \ud568\uaed8 \uc5bb\ub294 \uac83\uc774 \uacf5\uc7a5\uc758 \uacfc\uc81c\uc600\ub2e4. \uc0c8\ub85c\uc6b4 \uacf5\uc815\uc740 \uc774 \uc870\uac74\ub4e4\uc758 \uad00\uacc4\ub97c \ubc14\uafb8\uc5c8\ub2e4. \uc804\ub85c\ub294 \ub0b4\ud654 \uc7ac\ub8cc\ub85c \uc548\uc744 \ubcf4\ud638\ud55c \ud070 \uc6a9\uae30\ub2e4. \ub179\uc740 \uae08\uc18d\uc744 \ub2f4\uace0 \ucc98\ub9ac\ud55c \ub4a4 \ub2e4\uc2dc \uc3df\uc544\uc57c \ud558\ubbc0\ub85c \uae30\uc6b8\uc77c \uc218 \uc788\ub294 \uad6c\uc870\uac00 \uc911\uc694\ud588\ub2e4. \uc61b \ub3c4\ud310\uc5d0\uc11c \ubcf4\uc774\ub294 \ud070 \ubab8\uccb4\uc640 \ud68c\uc804 \uc7a5\uce58\ub294 \uc7a5\uc2dd\uc774 \uc544\ub2c8\ub77c \uc791\uc5c5 \uc21c\uc11c\ub97c \uc704\ud55c \ud615\ud0dc\ub2e4. \ucc44\uc6b0\uace0 \ubc18\uc751\uc2dc\ud0a4\uace0 \ube44\uc6b0\ub294 \uc77c\uc740 \ud558\ub098\uc758 \ud750\ub984\uc744 \uc774\ub8ec\ub2e4. \uc5b4\ub290 \ub2e8\uacc4\uac00 \ub2a6\uac70\ub098 \ub2e4\ub8e8\uae30 \uc5b4\ub824\uc6b0\uba74 \uc804\uccb4\uc758 \ud6a8\uacfc\uac00 \uc904\uc5b4\ub4e0\ub2e4. \uc6a9\uae30\uc758 \uc0dd\uae40\uc0c8\ub97c \ubcf4\uba74 \ud654\ud559 \ubc18\uc751\uacfc \ubb3c\uc9c8\uc744 \uc6b4\ubc18\ud558\ub294 \uae30\uacc4\uac00 \uc11c\ub85c \ub5a8\uc5b4\uc9c0\uc9c0 \uc54a\uc558\uc74c\uc744 \uc54c \uc218 \uc788\ub2e4. \ub728\uac70\uc6b4 \uae08\uc18d\uc5d0 \uacf5\uae30\ub97c \ubd88\uc5b4\ub123\ub294\ub2e4\uace0 \ud558\uba74 \uba3c\uc800 \uc2dd\ud788\ub294 \ubaa8\uc2b5\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uacf5\uae30 \uc911 \uc0b0\uc18c\uac00 \uc131\ubd84\uacfc \ubc18\uc751\ud558\uba74\uc11c \uc5f4\uc774 \uc0dd\uae34\ub2e4. \uacf5\uae30\ub97c \ud1b5\uacfc\uc2dc\ud0a4\ub294 \uc77c\uc774 \ubc18\uc751\uc744 \uc9c4\ud589\uc2dc\ud0a4\uace0 \ud544\uc694\ud55c \uc0c1\ud0dc\ub97c \uc720\uc9c0\ud558\ub294 \ub370 \uc5f0\uacb0\ub41c\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubc14\ub78c\uc758 \uc138\uae30\ub9cc \uc911\uc694\ud55c \uac83\uc774 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc774 \uc5bc\ub9c8\ub098 \ub4e4\uc5b4 \uc788\ub294 \uae08\uc18d\uc744 \ucc98\ub9ac\ud558\ub294\uc9c0, \uc5b4\ub5a4 \ubc18\uc751\uc774 \uc77c\uc5b4\ub098\ub294\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \uacf5\uc815\uc758 \uc6d0\ub9ac\ub97c \ube7c\uace0 \uac70\ub300\ud55c \uc1a1\ud48d \uc7a5\uce58\ub9cc \ubcf4\uba74 \uae30\uc220\uc758 \ud575\uc2ec\uc744 \ub193\uce5c\ub2e4. \uac19\uc740 \uacf5\uae30\ub3c4 \ubb3c\uc9c8\uc758 \uc870\uac74\uc5d0 \ub530\ub77c \ub2e4\ub978 \uc77c\uc744 \ud560 \uc218 \uc788\ub2e4. \uacfc\uc815\uc774 \ube68\ub77c\uc9c0\uba74 \uc791\uc5c5\uc790\uac00 \uc0c1\ud0dc\ub97c \ud310\ub2e8\ud560 \uc2dc\uac04\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc6d0\ud558\ub294 \uc131\ubd84\uc758 \ubc94\uc704\ub97c \uc5bb\uace0 \ub2e4\uc74c \uacf5\uc815\uc73c\ub85c \ub118\uaca8\uc57c \ud55c\ub2e4. \ubd88\uaf43\uacfc \uc791\uc5c5\uc758 \ubcc0\ud654\ub294 \ub2f9\uc2dc\uc758 \uc911\uc694\ud55c \uad00\ucc30 \ub300\uc0c1\uc774\uc5c8\ub2e4. \uc18d\ub3c4\ub97c \ub192\uc774\ub294 \uae30\uc220\uc740 \ubb34\uc5c7\uc744 \uc5b8\uc81c \uba48\ucd9c\uc9c0 \ud310\ub2e8\ud558\ub294 \uc77c\ub3c4 \ubc14\uafb8\uc5c8\ub2e4. \ub300\ub7c9 \uc0dd\uc0b0\uc744 \ubb34\uc870\uac74 \uc0ac\ub78c\uc758 \ud310\ub2e8\uc774 \uc0ac\ub77c\uc9c0\ub294 \uacfc\uc815\uc73c\ub85c \ubcf4\uc544\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc790\ub3d9\uc73c\ub85c \uc9c4\ud589\ub418\ub294 \ubd80\ubd84\uc774 \ucee4\uc838\ub3c4 \uc2dc\uc791 \uc870\uac74\uacfc \uc885\ub8cc \uc2dc\uc810\uc744 \ub2e4\ub8e8\ub294 \uc219\ub828\uc774 \ud544\uc694\ud558\ub2e4. \uacf5\uc7a5\uc774 \uc5bb\uc740 \uc18d\ub3c4 \ub4a4\uc5d0\ub294 \uc0c8\ub85c\uc6b4 \ubc29\uc2dd\uc73c\ub85c \uc9d1\uc911\ud574\uc57c \ud558\ub294 \ub178\ub3d9\uc774 \ub193\uc778\ub2e4. \uacf5\uc815\uc758 \ud6a8\uacfc\ub294 \uc6d0\ub8cc\uc758 \uc131\ubd84\uacfc \uc804\ub85c \ub0b4\ubd80\uc758 \uc870\uac74\uc5d0 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4. \ud2b9\ud788 \ubd88\uc21c\ubb3c\uc744 \uc5b4\ub5bb\uac8c \ub2e4\ub8f0\uc9c0\uc5d0 \ub530\ub77c \uc801\uc6a9 \ubc94\uc704\uac00 \ub2ec\ub77c\uc84c\ub2e4. \ub4a4\uc758 \uac1c\uc120\uc740 \ucc98\uc74c \ubc29\ubc95\uc758 \ud55c\uacc4\ub97c \ubcf4\uc644\ud558\ub294 \uacfc\uc815\uc774\uae30\ub3c4 \ud588\ub2e4. \ud55c \ubc88 \uc6d0\ub9ac\uac00 \uc81c\uc2dc\ub418\uc5c8\ub2e4\uace0 \ubaa8\ub4e0 \uc81c\ucca0\uc18c\uc758 \ubb38\uc81c\uac00 \ub05d\ub09c \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc1c\uba85\uc758 \uc6b0\uc120\uad8c\uc744 \ub458\ub7ec\uc2fc \uacbd\uc7c1\ub3c4 \uc788\uc5c8\ub2e4. \uc61b \uae30\uc220\uc0ac \ucc45\uc740 \ubca0\uc11c\uba38\uc640 \ud568\uaed8 \uc70c\ub9ac\uc5c4 \ucf08\ub9ac \ub4f1 \ub2e4\ub978 \uc2dc\ub3c4\ub97c \uc5b8\uae09\ud55c\ub2e4. \uc0b0\uc5c5\uc758 \ubcc0\ud654\ub97c \ud55c \uc0ac\ub78c\uc758 \ub3c5\ub9bd\uc801\uc778 \ubc88\ub729\uc784\uc73c\ub85c\ub9cc \uc124\uba85\ud558\uba74 \ube44\uc2b7\ud55c \ubb38\uc81c\ub97c \ud480\ub358 \uc5ec\ub7ec \uc791\uc5c5\uacfc \ud6c4\uc18d \uac1c\uc120\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \ub85c\ubc84\ud2b8 \ubb34\uc170\ud2b8\uac00 \uc81c\uc548\ud55c \uc131\ubd84 \uc870\uc815\uc758 \uac1c\uc120\ub3c4 \uc774\ub7f0 \uacfc\uc815\uc758 \uc77c\ubd80\uc600\ub2e4. \uacf5\uae30\ub97c \ubd88\uc5b4\ub123\uc5b4 \ubd88\ud544\uc694\ud55c \uc131\ubd84\uc744 \uc904\uc774\ub294 \uc77c\ub9cc\uc73c\ub85c \ub05d\ub098\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc6d0\ud558\ub294 \uae08\uc18d\uc758 \uc0c1\ud0dc\ub97c \ub2e4\uc2dc \ub9de\ucd94\uc5b4\uc57c \ud588\ub2e4. \ube7c\ub294 \uae30\uc220\uacfc \ub354\ud558\ub294 \uae30\uc220\uc774 \uacb0\ud569\ud574 \uc4f8 \ub9cc\ud55c \uc7ac\ub8cc\ub97c \ub9cc\ub4dc\ub294 \uac83\uc774\ub2e4. \uc774\ub54c \ucc98\uc74c \uc544\uc774\ub514\uc5b4\uc758 \uc6b0\uc120\uad8c\uacfc \uc2e4\uc81c \uacf5\uc7a5\uc5d0\uc11c \uc774\uc5b4 \uc4f0\uac8c \ub9cc\ub4e0 \uacf5\ud5cc\uc740 \uc11c\ub85c \ub2e4\ub978 \uc9c8\ubb38\uc774 \ub41c\ub2e4. \uc5b4\ub290 \ud55c\ucabd\ub9cc\uc758 \uc774\ub984\uc744 \uae30\uc5b5\ud558\uba74 \ub098\uba38\uc9c0 \ub2e8\uacc4\uac00 \uac00\ub824\uc9c4\ub2e4. \uc804\ub85c\ub77c\ub294 \ud070 \uc7a5\uce58 \uc548\uc5d0\uc11c\ub3c4 \ubc18\uc751\uc744 \uc2dc\uc791\ud558\ub294 \ubc29\ubc95, \uc6a9\uae30\ub97c \ub2e4\ub8e8\ub294 \uad6c\uc870, \uc131\ubd84\uc744 \uc870\uc815\ud558\ub294 \ubc29\ubc95\uc774 \ud568\uaed8 \uc791\ub3d9\ud588\ub2e4. \uc0dd\uc0b0 \uacf5\uc815\uc758 \ud601\uc2e0\uc740 \ubb38\uc81c\ub97c \ud55c \ubc88\uc5d0 \ud480\uc5b4 \ubc84\ub9b0 \uc0ac\uac74\ubcf4\ub2e4 \uc5ec\ub7ec \ud574\uacb0\ucc45\uc744 \uc5f0\uacb0\ud55c \uacb0\uacfc\ub85c \ubcfc \uc218 \uc788\ub2e4. \uac15\ucca0\uc744 \ub354 \ub9ce\uc774 \uacf5\uae09\ud560 \uc218 \uc788\uc73c\uba74 \uac00\uaca9\uacfc \uc0ac\uc6a9\ucc98\ub3c4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ucca0\ub3c4 \ub808\uc77c\uacfc \ud070 \uad6c\uc870\ubb3c\ucc98\ub7fc \ub9ce\uc740 \uae08\uc18d\uc744 \ud544\uc694\ub85c \ud558\ub294 \ubd84\uc57c\ub294 \uc774\ub7f0 \ubcc0\ud654\uc640 \uc5f0\uacb0\ub41c\ub2e4. \ub2e4\ub9cc \ud2b9\uc815 \uacf5\uc815 \ud558\ub098\uac00 \ubaa8\ub4e0 \uac74\ucd95\uacfc \ucca0\ub3c4\ub97c \ud63c\uc790 \uac00\ub2a5\ud558\uac8c \ud588\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc124\uacc4\uc640 \uc6b4\uc1a1, \ub2e4\ub978 \uac00\uacf5 \uae30\uc220\uc774 \ud568\uaed8 \ubc1c\uc804\ud574\uc57c \uc7ac\ub8cc\uac00 \uc2e4\uc81c \uc81c\ud488\uc774 \ub41c\ub2e4. \uacf5\uc7a5\uc758 \ucd9c\uad6c\uc5d0\uc11c \ub05d\ub098\ub294 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\uc5c8\ub2e4. \uc0c8\ub85c\uc6b4 \uae08\uc18d\uc744 \ubc1b\uc544 \uc4f8 \uc0b0\uc5c5\uc774 \uc788\uace0, \ub298\uc5b4\ub09c \uc218\uc694\ub294 \ub2e4\uc2dc \uc0dd\uc0b0\uc758 \ud655\ub300\ub97c \uc694\uad6c\ud55c\ub2e4. \uc7ac\ub8cc\uc640 \uc2dc\uc7a5\uc740 \uc11c\ub85c\uc758 \ubcc0\ud654\ub97c \uc774\ub04c\uc5c8\ub2e4. \uc624\ub298\uc758 \uc81c\uac15\uc744 \ubaa8\ub450 \uc61b \ubca0\uc11c\uba38 \uacf5\uc815\uacfc \uac19\ub2e4\uace0 \ubd80\ub97c \uc218\ub294 \uc5c6\ub2e4. \uc774\ud6c4 \ub2e4\ub978 \uacf5\uc815\uacfc \uc81c\uc5b4 \uae30\uc220\uc774 \ubc1c\uc804\ud588\uace0 \uc6d0\ub8cc\uc640 \uc5d0\ub108\uc9c0\uc758 \uc870\uac74\ub3c4 \ub2ec\ub77c\uc84c\ub2e4. \uc5ed\uc0ac\uc801 \uc804\ub85c\ub294 \ud604\ub300 \uacf5\uc7a5\uc758 \ubcf4\ud3b8\uc801\uc778 \uc124\uacc4\ub3c4\uac00 \uc544\ub2c8\ub77c \uc911\uc694\ud55c \uc804\ud658\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc790\ub8cc\ub2e4. \ubca0\uc11c\uba38 \uc804\ub85c\ub97c \ubcf4\uba74 \uc0b0\uc5c5 \ud601\uc2e0\uc740 \uae30\uacc4\uc758 \ud06c\uae30\ub9cc \ud0a4\uc6b0\ub294 \uc77c\uc774 \uc544\ub2c8\uc5c8\uc74c\uc744 \uc54c \uc218 \uc788\ub2e4. \ubb3c\uc9c8\uc758 \ubc18\uc751\uc744 \uc0dd\uc0b0\uc758 \uc18d\ub3c4\uc640 \ubc18\ubcf5\uc131\uc73c\ub85c \ubc14\uafb8\ub294 \uc77c\uc774\uc5c8\ub2e4. \uac19\uc740 \uc7ac\ub8cc\ub97c \ubc18\ubcf5\ud574\uc11c \uc5bb\ub294 \ub2a5\ub825\ub3c4 \uc7ac\ub8cc\ub97c \ucc98\uc74c \ub9cc\ub4dc\ub294 \ub2a5\ub825\ub9cc\ud07c \uc911\uc694\ud588\ub2e4. \uac70\ub300\ud55c \uc6a9\uae30\uc640 \ubd88\uaf43\uc744 \ub118\uc5b4 \uc131\ubd84\uacfc \uc2dc\uac04, \uc219\ub828\uacfc \uacf5\uae09\uc774 \uc5b4\ub5bb\uac8c \uc774\uc5b4\uc84c\ub294\uc9c0 \ubcfc \ub54c \uac15\ucca0\uc758 \uc5ed\uc0ac\uac00 \ub113\uc5b4\uc9c4\ub2e4."}, {"id": "bmw-car-made-across-borders", "title": "BMW \u2014 \ub3c5\uc77c \uc790\ub3d9\ucc28\ub97c \ubbf8\uad6d\uc5d0\uc11c \ub9cc\ub4e4\uba74", "summary": "BMW\uc758 \ubbf8\uad6d \uc0dd\uc0b0 \uc0ac\ub840\ub85c \ud574\uc678 \uacf5\uc7a5\u00b7\ubb3c\ub958\u00b7\uc2dc\uc7a5\uacfc \ube0c\ub79c\ub4dc\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\uacf5\uc7a5\uacfc \uc0dd\uc0b0", "categories": ["industry"], "url": "stories/bmw-car-made-across-borders/index.html", "image": "../media/bmw-car-made-across-borders.png", "alt": "\uc77c\ubc18\uc801\uc778 \uc790\ub3d9\ucc28 \uc870\ub9bd \uacf5\uac04\uc5d0\uc11c \ucc28\uccb4\ub97c \uc0b4\ud53c\ub294 \uc791\uc5c5\uc790\ub4e4\uc758 \uc0bd\ud654.", "text": "BMW \u2014 \ub3c5\uc77c \uc790\ub3d9\ucc28\ub97c \ubbf8\uad6d\uc5d0\uc11c \ub9cc\ub4e4\uba74 \ube0c\ub79c\ub4dc\uc758 \uace0\ud5a5\uacfc \uacf5\uc7a5\uc758 \uc8fc\uc18c\ub294 \uc65c \ub2e4\ub97c\uae4c BMW\uc758 \ubbf8\uad6d \uc0dd\uc0b0 \uc0ac\ub840\ub85c \ud574\uc678 \uacf5\uc7a5\u00b7\ubb3c\ub958\u00b7\uc2dc\uc7a5\uacfc \ube0c\ub79c\ub4dc\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uacf5\uc7a5\uacfc \uc0dd\uc0b0 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \uc790\ub3d9\ucc28\ub97c \ubcf4\uba70 \ub3c5\uc77c \ube0c\ub79c\ub4dc\ub77c\uace0 \ub9d0\ud55c\ub2e4. \uadf8\ub7f0\ub370 \uadf8 \ucc28\ub97c \ub9cc\ub4e0 \uacf5\uc7a5\uc740 \ubbf8\uad6d\uc5d0 \uc788\uc744 \uc218 \uc788\ub2e4. \uc774\ub984\uc744 \uc775\uc219\ud558\uac8c \uc54c\uace0 \uc788\uc744\uc218\ub85d \ucc98\uc74c\uc5d0\ub294 \ub73b\ubc16\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \ube0c\ub79c\ub4dc\uc758 \uace0\ud5a5\uacfc \uc870\ub9bd\ub41c \uc7a5\uc18c\ub294 \uc65c \uac19\uc740 \uc8fc\uc18c\uac00 \uc544\ub2d0\uae4c. BMW\uc758 \ubbf8\uad6d \uc0dd\uc0b0\uc740 \uacbd\uc601\ud559 \uad50\uc7ac\uac00 \ud574\uc678 \uc9c1\uc811\ud22c\uc790\ub97c \uc124\uba85\ud558\ub294 \uc0ac\ub840 \uac00\uc6b4\ub370 \ud558\ub098\ub2e4. \uc790\ub3d9\ucc28\uac00 \uad6d\uacbd\uc744 \ub118\ub294\ub2e4\ub294 \uac83\uc740 \uc644\uc131\ub41c \ucc28\ub97c \ubc30\uc5d0 \uc2e3\ub294 \uc77c\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uae30\uc5c5\uc774 \uacf5\uc7a5\uc744 \ub2e4\ub978 \ub098\ub77c\uc5d0 \uc138\uc6b0\ub294 \ubc29\uc2dd\uc73c\ub85c \uc0dd\uc0b0\uc758 \uc9c0\ub3c4\ub97c \ubc14\uafb8\uae30\ub3c4 \ud55c\ub2e4. \ube0c\ub79c\ub4dc\uc5d0\ub294 \uc5ed\uc0ac\uc640 \ub514\uc790\uc778, \uc0ac\ub78c\ub4e4\uc774 \uc313\uc544 \uc628 \uc774\ubbf8\uc9c0\uac00 \ubd99\ub294\ub2e4. BMW\ub97c \ub3c5\uc77c \uc790\ub3d9\ucc28 \ud68c\uc0ac\ub77c\uace0 \ubd80\ub974\ub294 \ub9d0\uc5d0\ub294 \uadf8\ub7f0 \ubc30\uacbd\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \ud45c\ud604\uc774 \ubaa8\ub4e0 \uc81c\ud488\uc758 \ubd80\ud488\uacfc \uc791\uc5c5\uc774 \ud55c \ub098\ub77c \uc548\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c4\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc644\uc131\ucc28\uc758 \uc0dd\uc0b0\uc9c0\uc640 \uc124\uacc4\u00b7\uae30\uc5c5\uc758 \ubcf8\uac70\uc9c0, \ubd80\ud488\uc744 \uacf5\uae09\ubc1b\ub294 \uacf3\uc740 \uc11c\ub85c \ub2e4\ub978 \uc9c8\ubb38\uc774\ub2e4. \uc790\ub3d9\ucc28 \ud55c \ub300\uc758 \uad6d\uc801\uc774\ub77c\ub294 \ud45c\ud604\uc740 \uc77c\uc0c1\uc801\uc73c\ub85c \ud3b8\ub9ac\ud558\uc9c0\ub9cc \uadf8 \uc548\uc5d0 \uc5ec\ub7ec \uc885\ub958\uc758 \uc5f0\uacb0\uc744 \ubb36\uc5b4 \ub193\uae30\ub3c4 \ud55c\ub2e4. \ubb34\uc5c7\uc744 \uc54c\uace0 \uc2f6\uc740\uc9c0 \ub098\ub204\uc5b4 \ubcf4\uba74 \ub2f5\ub3c4 \ub354 \ubd84\uba85\ud574\uc9c4\ub2e4. \uad50\uc7ac\ub294 \ubbf8\uad6d \uc0ac\uc6b0\uc2a4\uce90\ub864\ub77c\uc774\ub098\uc8fc \uc2a4\ud30c\ud134\ubc84\uadf8\uc758 BMW \uacf5\uc7a5\uc5d0\uc11c SUV\uac00 \uc0dd\uc0b0\ub418\ub294 \uc0ac\ub840\ub97c \uc124\uba85\ud55c\ub2e4. \ub2f9\uc2dc X3\uc640 X5 \uac19\uc740 \ubaa8\ub378\uc744 \ub4e4\uc5c8\ub2e4. \uc774\ub294 \uadf8 \uc2dc\uae30\uc758 \uc0ac\ub840\uc774\uba70 \ud604\uc7ac \ubaa8\ub4e0 \ubaa8\ub378\uc758 \uc0dd\uc0b0\uc9c0\ub97c \uc815\ub9ac\ud55c \ubaa9\ub85d\uc740 \uc544\ub2c8\ub2e4. \uc911\uc694\ud55c \uc810\uc740 \uc678\uad6d \uae30\uc5c5\uc774 \uc644\uc131\ucc28\ub97c \uc218\ucd9c\ub9cc \ud558\ub294 \ub300\uc2e0 \ud604\uc9c0\uc5d0\uc11c \uc0dd\uc0b0 \uc2dc\uc124\uc744 \uc6b4\uc601\ud588\ub2e4\ub294 \uac83\uc774\ub2e4. \uc18c\ube44\uc790\ub294 \ub3c5\uc77c \ud68c\uc0ac\uc758 \ube0c\ub79c\ub4dc\ub97c \uc120\ud0dd\ud558\uba74\uc11c \ubbf8\uad6d\uc5d0\uc11c \uc870\ub9bd\ub41c \uc81c\ud488\uc744 \uc0b4 \uc218 \uc788\ub2e4. \ucc98\uc74c\uc758 \ubaa8\uc21c\uc740 \uc11c\ub85c \ub2e4\ub978 \uc8fc\uc18c\ub97c \uac19\uc740 \uc885\ub958\uc758 \uc815\ubcf4\ub85c \ubcf4\uc558\uc744 \ub54c \uc0dd\uae34 \uc148\uc774\ub2e4. \uae30\uc5c5\uc774 \ud574\uc678 \uacf5\uc7a5\uc744 \uc138\uc6b0\ub294 \uc774\uc720 \uac00\uc6b4\ub370 \ud558\ub098\ub294 \uace0\uac1d\uc5d0\uac8c \ub354 \uac00\uae4c\uc6cc\uc9c0\ub294 \uac83\uc774\ub2e4. \uc81c\ud488\uc744 \uba40\ub9ac\uc11c \uc644\uc131\ud574 \ubcf4\ub0b4\ub294 \ubc29\uc2dd\uacfc \ud604\uc9c0\uc5d0\uc11c \ub9cc\ub4dc\ub294 \ubc29\uc2dd\uc740 \ubb3c\ub958\uc640 \uc77c\uc815\uc758 \uc870\uac74\uc774 \ub2e4\ub974\ub2e4. \ucee4\ub2e4\ub780 \uc790\ub3d9\ucc28\ub97c \uc5b4\ub5bb\uac8c \uc774\ub3d9\uc2dc\ud0ac\uc9c0\ub3c4 \ube44\uc6a9\uacfc \uc5f0\uacb0\ub41c\ub2e4. \ubb3c\ub860 \uacf5\uc7a5\uc774 \uac00\uae5d\ub2e4\uace0 \ubaa8\ub4e0 \ubd80\ud488\uae4c\uc9c0 \uac00\uae4c\uc6b4 \uacf3\uc5d0\uc11c \uc624\uac70\ub098 \ubaa8\ub4e0 \ubc30\uc1a1\uc774 \ube68\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0dd\uc0b0\uc9c0\uc758 \uc774\ub3d9\uc740 \uacf5\uae09\ub9dd \uc804\uccb4\uc758 \uad00\uacc4\ub97c \ub2e4\uc2dc \uc9dc\ub294 \ubb38\uc81c\ub2e4. \ud55c \uad6c\uac04\uc744 \uc904\uc774\uba74\uc11c \ub2e4\ub978 \uad6c\uac04\uc758 \uc774\ub3d9\uc774 \uc0dd\uae38 \uc218\ub3c4 \uc788\ub2e4. \ud604\uc9c0 \uc0dd\uc0b0\uc774\ub77c\ub294 \ub9d0 \ub4a4\uc758 \uad6c\uccb4\uc801\uc778 \uc5f0\uacb0\uc744 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uad50\uc7ac\ub294 \ud604\uc9c0 \uc0dd\uc0b0\uc774 \uc218\uc785\ud488\uc5d0 \ubd80\uacfc\ub418\ub294 \uad00\uc138\ub098 \ubb34\uc5ed \uc7a5\ubcbd\uacfc \uad00\ub828\ub420 \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubb3c\uac74\uc744 \ud310\ub9e4\ud560 \uc2dc\uc7a5\uc5d0 \uacf5\uc7a5\uc744 \ub450\uba74 \uc644\uc131\ud488 \uc218\uc785\uacfc \ub2e4\ub978 \uc870\uac74\uc744 \ub9cc\ub0a0 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uae30\uc5c5\uc758 \uc785\uc9c0 \uc120\ud0dd\uc740 \uae30\uc220 \ubb38\uc81c\ub9cc\uc774 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uc774 \uc124\uba85\uc744 \ud604\uc7ac\uc758 \ud2b9\uc815 \uad00\uc138\uc728\uc774\ub098 \uc815\ucc45\uc5d0 \ubc14\ub85c \uc801\uc6a9\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc81c\ub3c4\ub294 \uc2dc\uae30\uc640 \ub098\ub77c, \ud488\ubaa9\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c4\ub2e4. \uc774\ubc88 \uc6d0\uace0\ub294 \uc5b4\ub5a4 \uc815\uce58\uc801 \uacb0\uc815\uc774 \ucd5c\uc2e0\uc73c\ub85c \ub0b4\ub824\uc84c\ub294\uc9c0 \uc54c\ub824 \uc8fc\uae30\ubcf4\ub2e4, \uacf5\uc7a5 \uc8fc\uc18c\ub97c \uc815\ud560 \ub54c \uc81c\ub3c4\ub3c4 \uace0\ub824\ud55c\ub2e4\ub294 \uc6d0\ub9ac\ub97c \uc77d\ub294 \uae00\uc774\ub2e4. \uc0dd\uc0b0 \uc2dc\uc124\uc5d0\ub294 \uc124\ube44\ubfd0 \uc544\ub2c8\ub77c \uae30\uc220\uc744 \uac00\uc9c4 \uc0ac\ub78c\uacfc \uacf5\uae09\uc790, \uad00\ub9ac\uc758 \uad00\uacc4\uac00 \ud544\uc694\ud558\ub2e4. \ud604\uc9c0\uc758 \uc804\ubb38\uc131\uacfc \ube44\uc6a9 \uc870\uac74\ub3c4 \ud574\uc678 \uc9c1\uc811\ud22c\uc790\uc758 \uc774\uc720\uac00 \ub420 \uc218 \uc788\ub2e4\uace0 \uad50\uc7ac\ub294 \uc124\uba85\ud55c\ub2e4. \uae30\uc5c5\uc740 \ub545 \uc704\uc5d0 \uacf5\uc7a5 \uac74\ubb3c \ud55c \ucc44\ub9cc \uc62e\uae30\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc0dd\uc0b0 \uae30\uc900\uacfc \ud6c8\ub828, \ubd80\ud488\uc758 \ud488\uc9c8\uacfc \uc791\uc5c5\uc758 \uc5f0\uacb0\uc744 \ub9c8\ub828\ud574\uc57c \ud55c\ub2e4. \uc774 \ubd80\ubd84\uc740 \uc6d0\ub9ac\ub97c \uc124\uba85\ud558\ub294 \uac83\uc774\uba70 \ud2b9\uc815 BMW \uacf5\uc7a5\uc758 \ud604\uc7ac \uad50\uc721 \uacfc\uc815\uc744 \ucde8\uc7ac\ud55c \uae30\ub85d\uc740 \uc544\ub2c8\ub2e4. \uac19\uc740 \uc0c1\ud45c\uc758 \uc81c\ud488\uc744 \uc5ec\ub7ec \uc7a5\uc18c\uc5d0\uc11c \ub9cc\ub4e0\ub2e4\ub294 \ubaa9\ud45c\uc5d0\ub294 \uadf8\ub7f0 \uae30\uc900\uc744 \uc774\uc5b4 \uac00\ub294 \uacfc\uc81c\uac00 \uc0dd\uae34\ub2e4. \uc0dd\uc0b0 \uad6d\uac00\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc81c\ud488\uc758 \ud488\uc9c8\uc744 \uc815\ud558\uba74 \uc911\uc694\ud55c \ucc28\uc774\ub97c \ub193\uce60 \uc218 \uc788\ub2e4. \uc5b4\ub5a4 \uc124\uacc4\uc640 \uae30\uc900\uc744 \uc801\uc6a9\ud558\uace0 \uc5b4\ub5a4 \ubd80\ud488\uc744 \uc4f0\uba70 \uc5b4\ub5bb\uac8c \ud655\uc778\ud588\ub294\uc9c0\uac00 \ud568\uaed8 \uad00\uc5ec\ud55c\ub2e4. \uc88b\uc740 \uc81c\ud488\uc744 \ub9cc\ub4e0\ub2e4\ub294 \uc57d\uc18d\uc740 \uad6d\uae30\uc758 \ubaa8\uc591\ub9cc\uc73c\ub85c \uc2e4\ud589\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc774\uac83\uc740 \uc5b4\ub290 \ub098\ub77c \uacf5\uc7a5\uc774 \ub354 \ub0ab\ub2e4\ub294 \ube44\uad50\uac00 \uc544\ub2c8\ub2e4. \ube0c\ub79c\ub4dc\uc758 \uc774\ubbf8\uc9c0\uc640 \uc2e4\uc81c \uc0dd\uc0b0\uc758 \uc870\uac74\uc744 \ub098\ub204\uc5b4 \uc77d\uc790\ub294 \ub73b\uc774\ub2e4. \uae30\uc5c5\uc774 \ud574\uc678\uc5d0\uc11c \uc0dd\uc0b0\ud574\ub3c4 \uace0\uac1d\uc740 \uc775\uc219\ud55c \uc0c1\ud45c\uc5d0 \uae30\ub300\ub97c \uac16\ub294\ub2e4. \uadf8 \uae30\ub300\uc640 \ud604\uc7a5\uc758 \uacb0\uacfc\ub97c \uc5f0\uacb0\ud558\ub294 \uc77c\uc774 \uae30\uc5c5\uc758 \ucc45\uc784\uc73c\ub85c \ub0a8\ub294\ub2e4. \ud070 \uc0dd\uc0b0 \uc2dc\uc124\uc740 \ub178\ub3d9\uacfc \uacf5\uae09, \uc6b4\uc1a1\uc758 \uad00\uacc4\ub97c \uc8fc\ubcc0\uc5d0 \ub9cc\ub4e0\ub2e4. \ud68c\uc0ac\uac00 \uc2dc\uc7a5 \uac00\uae4c\uc774 \uac14\ub2e4\ub294 \uc124\uba85\uacfc \ud604\uc9c0 \uc0ac\ud68c\uac00 \uacf5\uc7a5\uc744 \ub9de\uc774\ud55c \uacbd\ud5d8\uc740 \ub2e4\ub978 \uac01\ub3c4\uc5d0\uc11c \ubcfc \uc218 \uc788\ub2e4. \ubb34\uc5c7\uc774 \uc774\uc775\uc774\uace0 \uc5b4\ub5a4 \uc900\ube44\uac00 \ud544\uc694\ud55c\uc9c0\ub294 \ucc38\uc5ec\uc790\uc5d0 \ub530\ub77c \ub2e4\ub974\ub2e4. \uc774\ubc88 \uae00\uc740 \uc2a4\ud30c\ud134\ubc84\uadf8 \uc9c0\uc5ed\uc758 \ud604\uc7ac \uace0\uc6a9 \uc218\ub098 \uacbd\uc81c \ud6a8\uacfc\ub97c \uacc4\uc0b0\ud558\uc9c0 \uc54a\ub294\ub2e4. \uadf8\ub7f0 \ud3c9\uac00\ub294 \ubcc4\ub3c4\uc758 \uc9c0\uc5ed \uc790\ub8cc\uac00 \ud544\uc694\ud558\ub2e4. \ub300\uc2e0 \ud574\uc678 \uc9c1\uc811\ud22c\uc790\ub97c \uae30\uc5c5\uc758 \uacb0\uc815\uc73c\ub85c\ub9cc \ub05d\ub0b4\uc9c0 \uc54a\uace0 \uadf8\uacf3\uc5d0\uc11c \ud568\uaed8 \uc77c\ud558\ub294 \uc0ac\ub78c\uacfc \uc5c5\uccb4\uc758 \uad00\uacc4\ub85c\ub3c4 \ubc14\ub77c\ubcfc \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc791\uc5c5\uc790\ub4e4\uc774 \uc790\ub3d9\ucc28\uc758 \uc77c\ubd80\ub97c \ud655\uc778\ud558\ub294 \uacf5\uc7a5 \ubd84\uc704\uae30\ub2e4. \uc2e4\uc81c BMW \ubaa8\ub378\uacfc \ubbf8\uad6d \uacf5\uc7a5\uc758 \uc124\ube44\ub97c \ubcf5\uc6d0\ud55c \uc0ac\uc9c4\uc774 \uc544\ub2c8\ub2e4. \uc790\ub3d9\ucc28\uac00 \uc5b4\ub5a4 \uc7a5\uc18c\uc758 \uc0dd\uc0b0\uacfc \uc5f0\uacb0\ub418\ub294\uc9c0 \ub5a0\uc62c\ub9ac\uae30 \uc704\ud55c \uc774\ubbf8\uc9c0\ub2e4. \uc774\uc81c \ub3c5\uc77c \ube0c\ub79c\ub4dc\ub77c\ub294 \ub9d0\uacfc \ubbf8\uad6d\uc5d0\uc11c \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \ub9d0\uc774 \uc11c\ub85c \ub2e4\ub974\uac8c \ub2f5\ud558\uace0 \uc788\ub2e4\ub294 \uac83\uc744 \uc54c \uc218 \uc788\ub2e4. \ud558\ub098\ub294 \uae30\uc5c5\uacfc \ube0c\ub79c\ub4dc\uc758 \ubc30\uacbd\uc744, \ub2e4\ub978 \ud558\ub098\ub294 \uc0dd\uc0b0\uc758 \uc7a5\uc18c\ub97c \uac00\ub9ac\ud0a8\ub2e4. \uc790\ub3d9\ucc28 \ud55c \ub300\ub97c \ubcfc \ub54c \uc8fc\uc18c\ub97c \ud558\ub098\ub9cc \ubb3b\uc9c0 \uc54a\uc73c\uba74, \uc138\uacc4\uc758 \uc0b0\uc5c5\uc774 \uc5f0\uacb0\ub418\ub294 \ubc29\uc2dd\ub3c4 \uc870\uae08 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4."}, {"id": "bombas-socks-and-giving", "title": "\ubd04\ubc14\uc2a4 \u2014 \uc65c \ud558\ud544 \uc591\ub9d0\uc774\uc5c8\uc744\uae4c", "summary": "2013~2017\ub144 \ubd04\ubc14\uc2a4 \uc0ac\ub840\uc5d0\uc11c \ud310\ub9e4 \uc0c1\ud488\u00b7\uae30\ubd80 \uc57d\uc18d\u00b7\uc2e4\uc81c \ud544\uc694\ub97c \ud568\uaed8 \uc0dd\uac01\ud569\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\ube0c\ub79c\ub4dc\uc640 \uc18c\ube44", "categories": ["industry"], "url": "stories/bombas-socks-and-giving/index.html", "image": "../media/bombas-socks-and-giving.png", "alt": "\uc0c1\uc790\uc5d0 \uae68\ub057\ud55c \uc591\ub9d0\uc744 \uc815\ub9ac\ud558\ub294 \ub450 \uc0ac\ub78c\uc758 AI \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ubd04\ubc14\uc2a4 \u2014 \uc65c \ud558\ud544 \uc591\ub9d0\uc774\uc5c8\uc744\uae4c \uc77c\uc0c1\uc801\uc778 \ubb3c\uac74\uc744 \ud30c\ub294 \ud68c\uc0ac\uac00 \ubc1c\uacac\ud55c \ub2e4\ub978 \ud544\uc694 2013~2017\ub144 \ubd04\ubc14\uc2a4 \uc0ac\ub840\uc5d0\uc11c \ud310\ub9e4 \uc0c1\ud488\u00b7\uae30\ubd80 \uc57d\uc18d\u00b7\uc2e4\uc81c \ud544\uc694\ub97c \ud568\uaed8 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ube0c\ub79c\ub4dc\uc640 \uc18c\ube44 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \uc591\ub9d0\uc740 \uc120\ubb3c\uc758 \uc8fc\uc778\uacf5\uc774 \ub418\uae30\ubcf4\ub2e4 \uc11c\ub78d \uc18d\uc5d0\uc11c \uc790\uae30 \ucc28\ub840\ub97c \uae30\ub2e4\ub9ac\ub294 \ubb3c\uac74\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \ub9e4\uc77c \uc4f0\uc9c0\ub9cc \ud2b9\ubcc4\ud788 \uc774\uc57c\uae30\ud560 \uc77c\uc774 \ub9ce\uc9c0\ub294 \uc54a\ub2e4. \uadf8\ub7f0\ub370 \uc5b4\ub5a4 \ud658\uacbd\uc5d0\uc11c\ub294 \uc774 \ud3c9\ubc94\ud55c \ubb3c\uac74\uc744 \ucda9\ubd84\ud788 \uac16\ucd94\ub294 \uc77c\uc774 \uc911\uc694\ud558\ub2e4. \ubd04\ubc14\uc2a4\ub77c\ub294 \uc591\ub9d0 \ud68c\uc0ac\uc758 \ucd9c\ubc1c\uc5d0\ub294 \uc774\ub7f0 \uad00\ucc30\uc774 \uc788\uc5c8\ub2e4. \uacbd\uc601\ud559 \uad50\uc7ac\ub294 \ucc3d\uc5c5\uc790\ub4e4\uc774 \ub178\uc219\uc778\uc744 \uc9c0\uc6d0\ud558\ub294 \ubcf4\ud638\uc2dc\uc124\uc5d0\uc11c \uc591\ub9d0 \uc694\uccad\uc774 \ub9ce\ub2e4\ub294 \uc810\uc5d0 \uc8fc\ubaa9\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubb34\uc5c7\uc744 \ud314 \uc218 \uc788\uc744\uae4c\ub77c\ub294 \uc9c8\ubb38 \uc606\uc5d0 \ub204\uac00 \uc5b4\ub5a4 \ubb3c\uac74\uc744 \ud544\uc694\ub85c \ud558\ub294\uac00\ub77c\ub294 \uc9c8\ubb38\uc774 \ub193\uc600\ub2e4. \uc0ac\ub78c\uc744 \ub3d5\ub294 \uc77c\uc744 \ub5a0\uc62c\ub9b4 \ub54c \ud070 \uac74\ubb3c\uc774\ub098 \ub9ce\uc740 \uc2dd\ub7c9\ubd80\ud130 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \ub9e4\uc77c \ubab8\uc5d0 \ub2ff\uace0 \uc790\uc8fc \uc4f0\ub294 \uc791\uc740 \ubb3c\uac74\uc5d0\ub3c4 \ubd80\uc871\uc774 \uc0dd\uae38 \uc218 \uc788\ub2e4. \ub204\uad70\uac00\uc5d0\uac8c \ud754\ud55c \ubb3c\uac74\uc774\ub77c\ub294 \uc0ac\uc2e4\uc774 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c\ub3c4 \ucda9\ubd84\ud788 \uc788\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ubd04\ubc14\uc2a4 \ucc3d\uc5c5 \uc0ac\ub840\uc758 \ud765\ubbf8\ub85c\uc6b4 \uc810\uc740 \ud544\uc694\uc758 \uaddc\ubaa8\ub97c \ubb3c\uac74\uc758 \ud06c\uae30\ub85c \ud310\ub2e8\ud558\uc9c0 \uc54a\uc558\ub2e4\ub294 \ub370 \uc788\ub2e4. \ub2e4\ub9cc \ud2b9\uc815 \uad50\uc7ac\uac00 \uc18c\uac1c\ud55c \uad00\ucc30\uc744 \uc804 \uc138\uacc4 \ubaa8\ub4e0 \uc2dc\uc124\uc758 \ud604\uc7ac \uc6b0\uc120\uc21c\uc704\ub85c \ub113\ud790 \uc218\ub294 \uc5c6\ub2e4. \uc2e4\uc81c \uc9c0\uc6d0\uc5d0\uc11c\ub294 \uadf8 \uc9c0\uc5ed\uacfc \uae30\uad00\uc774 \uc694\uccad\ud558\ub294 \ub0b4\uc6a9\uc744 \ud655\uc778\ud558\ub294 \uc77c\uc774 \uba3c\uc800\ub2e4. \ub79c\ub514 \uace8\ub4dc\ubc84\uadf8\uc640 \ub370\uc774\ube44\ub4dc \ud788\uc2a4\ub294 2013\ub144 \ubd04\ubc14\uc2a4\ub97c \uc2dc\uc791\ud588\ub2e4. \uad50\uc7ac\ub294 \uc774\ub4e4\uc774 \uc591\ub9d0\uc744 \uac1c\uc120\ud55c \uc81c\ud488\uc73c\ub85c \uc81c\uc548\ud558\uba74\uc11c \ub3c4\uc6c0\uc774 \ud544\uc694\ud55c \uc0ac\ub78c\uc5d0\uac8c \uc591\ub9d0\uc744 \uc81c\uacf5\ud558\ub294 \uad6c\uc0c1\uc744 \ud568\uaed8 \ub9cc\ub4e4\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud310\ub9e4\uc640 \uc9c0\uc6d0\uc744 \uc11c\ub85c \ub2e4\ub978 \ub450 \ud65c\ub3d9\uc73c\ub85c\ub9cc \ub0a8\uaca8 \ub450\uc9c0 \uc54a\uc73c\ub824 \ud55c \uac83\uc774\ub2e4. \ubb3c\ub860 \ud68c\uc0ac\uac00 \uc591\ub9d0\uc744 \uc0c8\ub86d\uac8c \ub9cc\ub4e4\uc5c8\ub2e4\uace0 \ud45c\ud604\ud558\ub294 \uac83\uacfc \uadf8 \ud488\uc9c8\uc774 \ubaa8\ub4e0 \uacbd\uc7c1 \uc81c\ud488\ubcf4\ub2e4 \uc6b0\uc6d4\ud558\ub2e4\ub294 \ud3c9\uac00\ub294 \ub2e4\ub974\ub2e4. \uc774\ubc88 \uc774\uc57c\uae30\ub294 \uc81c\ud488\uc758 \ucc29\uc6a9 \uc2dc\ud5d8\uc774\ub098 \uad6c\ub9e4 \ucd94\ucc9c\uc774 \uc544\ub2c8\ub2e4. \ud3c9\ubc94\ud55c \uc18c\ube44\uc7ac\uc5d0 \uc5b4\ub5a4 \uc0ac\uc5c5\uc758 \uc57d\uc18d\uc744 \ubd99\uc600\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\ub294 \uc0ac\ub840\ub2e4. \ub2f9\uc2dc \ubd04\ubc14\uc2a4\uac00 \ub0b4\uc138\uc6b4 \ubc29\uc2dd\uc740 \uace0\uac1d\uc774 \uc591\ub9d0 \ud55c \ucf24\ub808\ub97c \uc0ac\uba74 \ud55c \ucf24\ub808\ub97c \ub3c4\uc6c0\uc774 \ud544\uc694\ud55c \uc0ac\ub78c\uc5d0\uac8c \uae30\ubd80\ud558\ub294 \uac83\uc774\uc5c8\ub2e4. \uace0\uac1d\uc740 \uc790\uc2e0\uc774 \uc4f8 \ubb3c\uac74\uc744 \uad6c\uc785\ud558\uba74\uc11c \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc81c\uacf5\ud560 \ubb3c\uac74\uacfc\ub3c4 \uc5f0\uacb0\ub418\ub294 \uad6c\uc870\ub97c \ub9cc\ub0ac\ub2e4. \uc774 \uc57d\uc18d\uc774 \uc774\ud574\ud558\uae30 \uc26c\uc6b4 \uc774\uc720\ub294 \uacc4\uc0b0\uc758 \ub2e8\uc704\uac00 \uac19\uae30 \ub54c\ubb38\uc774\ub2e4. \ud55c \ucf24\ub808\uc640 \ud55c \ucf24\ub808\ub77c\ub294 \ub300\uc751\uc744 \uae08\ubc29 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc26c\uc6b4 \uc124\uba85\uacfc \uc2e4\uc81c \uc6b4\uc601\uc774 \ub2e8\uc21c\ud558\ub2e4\ub294 \ub9d0\uc740 \ub2e4\ub974\ub2e4. \uc5b4\ub514\uc5d0\uc11c \uc5b4\ub5a4 \ubb3c\uac74\uc744 \uc900\ube44\ud558\uace0 \uc5b4\ub5bb\uac8c \uc804\ub2ec\ud560\uc9c0\ub294 \ubcc4\ub3c4\uc758 \uc77c\uc744 \ud544\uc694\ub85c \ud55c\ub2e4. \ubb3c\uac74\uc744 \uc81c\uacf5\ud558\ub824\uba74 \ubc1b\ub294 \uacf3\uacfc\uc758 \uc5f0\uacb0\uc774 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uc5b4\ub5a4 \uc218\ub7c9\uacfc \uc885\ub958\uac00 \ud544\uc694\ud55c\uc9c0 \ud655\uc778\ud558\uace0 \ubcf4\uad00\uacfc \uc804\ub2ec\uc758 \uc870\uac74\uc744 \ub9de\ucd94\uc5b4\uc57c \ud55c\ub2e4. \uc774\ub294 \ubd04\ubc14\uc2a4\uc758 \uac1c\ubcc4 \ubc30\uc1a1\uc744 \ucde8\uc7ac\ud55c \uae30\ub85d\uc774 \uc544\ub2c8\ub77c \ubb3c\ud488 \uc9c0\uc6d0\uc744 \uc77d\uc744 \ub54c \ud544\uc694\ud55c \uae30\ubcf8\uc801\uc778 \uc9c8\ubb38\uc774\ub2e4. \ud310\ub9e4\ud55c \uc218\ub7c9\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc9c0\uc6d0\uc758 \uacb0\uacfc\uac00 \uc124\uba85\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubb3c\uac74\uc774 \uc2e4\uc81c\ub85c \ud544\uc694\ud55c \uacf3\uc5d0 \ub3c4\ucc29\ud588\ub294\uc9c0, \uadf8\uacf3\uc5d0\uc11c \uc0ac\uc6a9\ud560 \uc218 \uc788\uc5c8\ub294\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \uae30\ubd80\ub77c\ub294 \ub9d0\uc758 \uc88b\uc740 \uc778\uc0c1 \ub4a4\ub97c \uc870\uae08 \ub354 \uc0b4\ud3b4\ubcf4\uba74 \ubb3c\ub958\uc640 \ud611\ub825, \uc9c0\uc18d\uc801\uc778 \ud655\uc778\uc758 \uc77c\uc774 \ub098\ud0c0\ub09c\ub2e4. \uae30\uc5c5\uc758 \uc0ac\ud68c\uc801 \ubaa9\ud45c\ub294 \uc5b4\ub5a4 \uace0\uac1d\uc5d0\uac8c \uad6c\ub9e4 \uc774\uc720\uac00 \ub420 \uc218 \uc788\ub2e4. \uc591\ub9d0\uc758 \uae30\ub2a5\uacfc \uac00\uaca9\uc744 \ub530\uc9c0\uba74\uc11c \uadf8 \ud68c\uc0ac\uac00 \ubb34\uc5c7\uc744 \ud558\ub824\ub294\uc9c0\ub3c4 \uc0b4\ud3b4\ubcf4\ub294 \uac83\uc774\ub2e4. \uc18c\ube44\uac00 \uac1c\uc778\uc758 \uc0ac\uc6a9 \uacbd\ud5d8 \ubc14\uae65\uc758 \ubb38\uc81c\uc640 \uc5f0\uacb0\ub418\ub294 \uc9c0\uc810\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \uae30\ubd80 \uc57d\uc18d\uc774 \uc788\ub294 \uc0c1\ud488\uc744 \uc0ac\ub294 \uac83\ub9cc\uc774 \uc720\uc77c\ud558\uac8c \uc88b\uc740 \uc120\ud0dd\uc740 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\ub9c8\ub2e4 \ud544\uc694\ud55c \ubb3c\uac74\uacfc \uc608\uc0b0, \ub2e4\ub978 \uc9c0\uc6d0 \ubc29\ubc95\uc774 \uc788\ub2e4. \uae30\uc5c5\uc758 \ud65c\ub3d9\uc744 \uc774\ud574\ud558\ub294 \uac83\uacfc \ub3c5\uc790\uc5d0\uac8c \ud2b9\uc815 \uad6c\ub9e4\ub97c \uad8c\ud558\ub294 \uc77c\uc740 \uad6c\ubd84\ud560 \uc218 \uc788\ub2e4. \uc774\uc57c\uae30\ub97c \uc548\ub2e4\uace0 \ubc18\ub4dc\uc2dc \uac19\uc740 \uc18c\ube44\ub97c \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uad50\uc7ac\ub294 \ud68c\uc0ac\uac00 \ubc1d\ud78c \uc790\ub8cc\ub97c \ubc14\ud0d5\uc73c\ub85c 2017\ub144 10\uc6d4\uae4c\uc9c0 \uc591\ub9d0 400\ub9cc \ucf24\ub808 \uc774\uc0c1\uc744 \uae30\ubd80\ud588\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ub2f9\uc2dc \uaddc\ubaa8\ub97c \uc774\ud574\ud558\ub294 \ub2e8\uc11c\uc774\uc9c0\ub9cc \ud604\uc7ac\uae4c\uc9c0\uc758 \uc2e4\uc801\uc774\ub098 \ub3c5\ub9bd\uc801\uc778 \ud6a8\uacfc \ud3c9\uac00\ub97c \ub73b\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud68c\uc0ac\uc758 \uc9d1\uacc4\ub77c\ub294 \ucd9c\ucc98\ub3c4 \ud568\uaed8 \uae30\uc5b5\ud574\uc57c \ud55c\ub2e4. \ub9ce\uc740 \uc218\ub7c9\uc744 \uc81c\uacf5\ud588\ub2e4\ub294 \uc8fc\uc7a5\uacfc \ubc1b\ub294 \uc0ac\ub78c\uc758 \uc0dd\ud65c\uc774 \uc5b4\ub5bb\uac8c \ub2ec\ub77c\uc84c\ub294\uc9c0\ub294 \uad00\ub828\ub418\uc9c0\ub9cc \uac19\uc740 \uc9c8\ubb38\uc740 \uc544\ub2c8\ub2e4. \uc804\uc790\ub294 \uc804\ub2ec\ud55c \ubb3c\uac74\uc758 \uc591\uc744, \ud6c4\uc790\ub294 \uc2e4\uc81c \uacbd\ud5d8\uacfc \ubcc0\ud654\ub97c \ubb3b\ub294\ub2e4. \uc22b\uc790\ub97c \uc874\uc911\ud558\uba74\uc11c\ub3c4 \uc22b\uc790\uac00 \ub2f5\ud558\uc9c0 \uc54a\uc740 \uc9c8\ubb38\uc744 \ub0a8\uaca8 \ub458 \uc218 \uc788\ub2e4. \uc774\ud574\uad00\uacc4\uc790\ub77c\ub294 \ub9d0\uc740 \uae30\uc5c5\uc758 \uacb0\uc815\uc5d0 \uc601\ud5a5\uc744 \ubc1b\ub294 \uc5ec\ub7ec \ub300\uc0c1\uc744 \uac00\ub9ac\ud0a8\ub2e4. \uace0\uac1d\uacfc \uc8fc\uc8fc\ubfd0 \uc544\ub2c8\ub77c \uc9c1\uc6d0\uacfc \uacf5\uae09\uc790, \uc9c0\uc5ed\uc0ac\ud68c\ub3c4 \ud3ec\ud568\ub41c\ub2e4. \ubd04\ubc14\uc2a4 \uc0ac\ub840\uc5d0\uc11c\ub294 \uc81c\ud488\uc744 \uad6c\ub9e4\ud558\uc9c0 \uc54a\ub294 \uc9c0\uc6d0 \ub300\uc0c1\ub3c4 \ud68c\uc0ac\uc758 \ud65c\ub3d9\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc774\ub807\uac8c \ubcf4\uba74 \uae30\uc5c5\uc758 \ubaa9\uc801\uc744 \ub3c8\uc744 \ubc84\ub294\uac00 \uc544\ub2c8\uba74 \ub3d5\ub294\uac00\uc758 \uc591\uc790\ud0dd\uc77c\ub85c\ub9cc \uc815\ub9ac\ud558\uae30 \uc5b4\ub835\ub2e4. \ud310\ub9e4\uc640 \uc9c0\uc6d0\uc774 \ud568\uaed8 \ub3cc\uc544\uac00\ub3c4\ub85d \ub9cc\ub4e0 \uad6c\uc870\uc5d0\uc11c\ub294 \ub450 \ud65c\ub3d9\uc758 \uad00\uacc4\ub97c \uacc4\uc18d \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \ubaa9\ud45c\uac00 \uc88b\ub2e4\ub294 \uc120\uc5b8\uacfc \uadf8 \ubaa9\ud45c\ub97c \uafb8\uc900\ud788 \uc2e4\ud589\ud558\ub294 \uc6b4\uc601\uc740 \uc11c\ub85c\ub97c \ud544\uc694\ub85c \ud55c\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc591\ub9d0\uc744 \uc815\ub9ac\ud558\ub294 \ubd84\uc704\uae30\ub97c \ud45c\ud604\ud588\ub2e4. \ubd04\ubc14\uc2a4\uc758 \uc2e4\uc81c \ubd09\uc0ac\uc790\ub098 \uc9c0\uc6d0 \uc2dc\uc124, \uae30\ubd80 \ud589\uc0ac\ub97c \ucd2c\uc601\ud55c \uc790\ub8cc\uac00 \uc544\ub2c8\ub2e4. \uc774 \uc6d0\uace0\ub3c4 \ucc3d\uc5c5 \ucd08\uae30\uc758 \uad50\uc7ac \uc0ac\ub840\ub97c \ub2e4\ub8e8\uba70 \ud604\uc7ac \uc0c1\ud488\uacfc \uae30\ubd80 \uc815\ucc45\uc744 \uc548\ub0b4\ud558\uc9c0 \uc54a\ub294\ub2e4. \ubd04\ubc14\uc2a4\uc758 \uc774\uc57c\uae30\ub97c \uc77d\uace0 \ub098\uba74 \uc11c\ub78d \uc18d \uc591\ub9d0\uc774 \uc870\uae08 \ub2e4\ub974\uac8c \ubcf4\uc77c \uc218 \uc788\ub2e4. \ubb3c\uac74\uc758 \ud3c9\ubc94\ud568\uacfc \uadf8 \ud544\uc694\uc758 \ud06c\uae30\ub294 \uac19\uc740 \uae30\uc900\uc774 \uc544\ub2c8\uae30 \ub54c\ubb38\uc774\ub2e4. \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub358 \ud544\uc694\ub97c \uc54c\uc544\ucc28\ub9ac\ub294 \uc77c\uc740 \ucee4\ub2e4\ub780 \ubc1c\uba85\ubcf4\ub2e4 \uc791\uc544 \ubcf4\uc77c\uc9c0 \ubab0\ub77c\ub3c4, \uc5b4\ub5a4 \uc0ac\uc5c5\uc744 \ub9cc\ub4e4\uc9c0 \uc815\ud558\ub294 \uc911\uc694\ud55c \ucd9c\ubc1c\uc810\uc774 \ub420 \uc218 \uc788\ub2e4."}, {"id": "boulton-watt-fuel-savings-business", "title": "\ubcfc\ud134\uacfc \uc640\ud2b8 \u2014 \uc808\uc57d\ud55c \uc11d\ud0c4\uc774 \ud68c\uc0ac\uc758 \uc218\uc785\uc774 \ub418\ub2e4", "summary": "\ubcfc\ud134\uacfc \uc640\ud2b8\uc758 \uc5ed\ud560 \ubd84\ub2f4\uacfc \ud2b9\ud5c8, \uc5f0\ub8cc \uc808\uac10\uc5d0 \uc5f0\uacb0\ub41c \ubcf4\uc218\ub85c \ubc1c\uba85\uc774 \uc0ac\uc5c5\uc774 \ub418\ub294 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\uacbd\uc601\uacfc \uc870\uc9c1", "categories": ["industry"], "url": "stories/boulton-watt-fuel-savings-business/index.html", "image": "../media/boulton-watt-fuel-savings-business.png", "alt": "\uae30\uad00 \ubd80\ud488\uacfc \ub3c4\uba74\u00b7\uc7a5\ubd80\ub97c \ub450\uace0 \ub17c\uc758\ud558\ub294 \ub450 \ub3d9\uc5c5\uc790\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ubcfc\ud134\uacfc \uc640\ud2b8 \u2014 \uc808\uc57d\ud55c \uc11d\ud0c4\uc774 \ud68c\uc0ac\uc758 \uc218\uc785\uc774 \ub418\ub2e4 \uc640\ud2b8\uc758 \uac1c\uc120\uc744 \uc218\uc785\uc73c\ub85c \ubc14\uafbc \ub3d9\uc5c5\u00b7\ud2b9\ud5c8\u00b7\uc131\ub2a5 \uacc4\uc57d \ubcfc\ud134\uacfc \uc640\ud2b8\uc758 \uc5ed\ud560 \ubd84\ub2f4\uacfc \ud2b9\ud5c8, \uc5f0\ub8cc \uc808\uac10\uc5d0 \uc5f0\uacb0\ub41c \ubcf4\uc218\ub85c \ubc1c\uba85\uc774 \uc0ac\uc5c5\uc774 \ub418\ub294 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uacbd\uc601\uacfc \uc870\uc9c1 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \uc88b\uc740 \ubc1c\uba85\uc774 \uace7\ubc14\ub85c \uc88b\uc740 \uc0ac\uc5c5\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc99d\uae30\uae30\uad00\uc744 \uac1c\uc120\ud55c \uc81c\uc784\uc2a4 \uc640\ud2b8\uc5d0\uac8c\ub3c4 \ub3c8\uacfc \ubd80\ud488, \ud604\uc7a5\uc5d0\uc11c \uae30\uacc4\ub97c \uc124\uce58\ud560 \uc0ac\ub78c\uc774 \ud544\uc694\ud588\ub2e4. \ub9e4\uc288 \ubcfc\ud134\uacfc\uc758 \ub3d9\uc5c5\uc744 \ubcf4\uba74 \ubc1c\uba85\uc758 \uc5ed\uc0ac\uac00 \uc124\uacc4\ub3c4\uc5d0\uc11c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \uc5ec\uae30\uc11c\ub294 \uae30\uad00\uc758 \uc791\ub3d9 \uc6d0\ub9ac\ubcf4\ub2e4 \uadf8\uac83\uc744 \ud310\ub9e4\ud558\uace0 \uc720\uc9c0\ud55c \uc0ac\uc5c5\uc758 \uad6c\uc870\ub97c \uc0b4\ud3b4\ubcf8\ub2e4. \uc640\ud2b8\ub294 \uae30\uc874 \uc99d\uae30\uae30\uad00\uc758 \uc5f4 \ub0ad\ube44\ub97c \uc904\uc774\ub824 \ud588\ub2e4. \uadf8\ub7ec\ub098 \uc6d0\ub9ac\ub97c \uc0dd\uac01\ud574 \ub0b8 \uac83\uacfc \uad11\uc0b0\uc5d0\uc11c \ub9e4\uc77c \uc791\ub3d9\ud560 \uae30\uacc4\ub97c \uacf5\uae09\ud558\ub294 \uac83\uc740 \ub2e4\ub978 \ub2e8\uacc4\uc600\ub2e4. \uc2e4\ub9b0\ub354\ub97c \uc815\ubc00\ud558\uac8c \ub9cc\ub4e4\uace0 \ubd80\ud488\uc744 \ub9de\ucd94\uba70 \uace0\uc7a5\uc5d0 \ub300\uc751\ud574\uc57c \ud588\ub2e4. \uace0\uac1d\uc740 \uc88b\uc740 \uc774\ub860\ubcf4\ub2e4 \uc2e4\uc81c\ub85c \ubb3c\uc744 \ud37c\ub0bc \ub2a5\ub825\uc744 \uc6d0\ud588\ub2e4. \uc5f0\uad6c\uc640 \uc2dc\ud5d8\uc5d0\ub294 \uc218\uc785\uc774 \uc0dd\uae30\uae30 \uc804\ubd80\ud130 \ube44\uc6a9\uc774 \ub4e4\uc5c8\ub2e4. \ubc1c\uba85\uac00\ub294 \uc131\ub2a5\uc744 \uc785\uc99d\ud560 \uae30\ud68c\ub97c \uc5bb\uc73c\ub824\uba74 \uc774\ubbf8 \uc790\uc6d0\uc744 \uac00\uc838\uc57c \ud558\ub294 \uc5b4\ub824\uc6c0\uc5d0 \ubd80\ub52a\ud78c\ub2e4. \ub3d9\uc5c5\uc790\uc758 \uc874\uc7ac\ub294 \uc774\ub7f0 \uac04\uaca9\uc744 \uba54\uc6b0\ub294 \ubc29\ubc95\uc774\uc5c8\ub2e4. \ub3c8\uacfc \uae30\uc220\uc740 \uc644\uc131\ud488\uc744 \ub9cc\ub4dc\ub294 \uc11c\ub85c \ub2e4\ub978 \uc870\uac74\uc774\uc5c8\ub2e4. \ubcfc\ud134\uc740 \uc18c\ud638\uc758 \uc81c\uc870 \uc0ac\uc5c5\uc744 \uc6b4\uc601\ud558\uba70 \uc0ac\ub78c\uacfc \uc124\ube44, \uac70\ub798 \uad00\uacc4\ub97c \uac00\uc9c0\uace0 \uc788\uc5c8\ub2e4. \uc640\ud2b8\uac00 \ubaa8\ub4e0 \uc5c5\ubb34\ub97c \ud63c\uc790 \ub9e1\ub294 \ub300\uc2e0 \uac01\uc790\uac00 \ub2e4\ub978 \uac15\uc810\uc744 \uc81c\uacf5\ud560 \uc218 \uc788\uc5c8\ub2e4. \ubc1c\uba85\uac00\uc640 \uc0ac\uc5c5\uac00\ub77c\ub294 \uad6c\ubd84\ub3c4 \uc2e4\uc81c \uc77c\uc744 \uc5f0\uacb0\ud558\ub294 \uad00\uacc4 \uc18d\uc5d0\uc11c \uc758\ubbf8\uac00 \uc0dd\uae34\ub2e4. \ub3d9\uc5c5\uc740 \uc5ed\ud560\uc744 \uc815\ud558\ub294 \uc77c\uc774\ub2e4. \uc124\uacc4\ub97c \ub204\uac00 \ud558\uace0 \ube44\uc6a9\uc744 \ub204\uac00 \ubd80\ub2f4\ud558\uba70 \uc7a5\ubd80\ub97c \ub204\uac00 \uad00\ub9ac\ud558\ub294\uc9c0\uac00 \ud544\uc694\ud558\ub2e4. \uce74\ub124\uae30\uc758 \uc640\ud2b8 \uc804\uae30\uc5d0\ub294 \uc774\ub7f0 \uc5c5\ubb34\ub97c \uad6c\uccb4\uc801\uc73c\ub85c \uc815\ud558\ub824\ub294 \ud3b8\uc9c0\uc640 \ud611\uc758\uac00 \ub098\uc628\ub2e4. \ub0ad\ub9cc\uc801\uc778 \uc6b0\uc815\ubcf4\ub2e4 \uba3c\uc800 \uc9c0\uc18d\ud560 \uc218 \uc788\ub294 \uc77c\uc758 \ubc30\uce58\uac00 \uc788\uc5c8\ub2e4. 1775\ub144 \ud2b9\ud5c8 \uae30\uac04\uc744 \ub298\ub9ac\ub294 \ubc95\uc548\uc740 \uc0ac\uc5c5\uc758 \uc911\uc694\ud55c \uc804\ud658\uc810\uc774\uc5c8\ub2e4. \uc774\ubbf8 \ube44\uc6a9\uc744 \ub4e4\uc778 \ucabd\uc5d0\ub294 \ud68c\uc218\ud560 \uc2dc\uac04\uc774 \ud544\uc694\ud588\uc9c0\ub9cc, \uad11\uc0b0\uc5c5\uc790\uc5d0\uac8c\ub294 \ud2b9\ud5c8\ub8cc \uc5c6\uc774 \uae30\uc220\uc744 \uc4f0\ub294 \ub0a0\uc774 \ub2a6\uc5b4\uc9c4 \uc77c\uc774\uae30\ub3c4 \ud588\ub2e4. \uac19\uc740 \uc81c\ub3c4\ub97c \uc11c\ub85c \ub2e4\ub978 \uc704\uce58\uc5d0\uc11c \ubc14\ub77c\ubcf8 \uac83\uc774\ub2e4. \ub530\ub77c\uc11c \ud2b9\ud5c8\ub97c \ubc1c\uba85\uac00\uc5d0\uac8c \uc8fc\uc5b4\uc9c4 \uc0c1\uc73c\ub85c\ub9cc \ubcf4\uba74 \ub17c\uc7c1\uc758 \uc808\ubc18\uc744 \ub193\uce5c\ub2e4. \uc0c8\ub85c\uc6b4 \uae30\uc220\uc5d0 \ud22c\uc790\ud560 \uc720\uc778\uacfc \uc0ac\uc6a9\uc790\uac00 \ubd80\ub2f4\ud560 \ube44\uc6a9\uc774 \ud568\uaed8 \uac78\ub824 \uc788\uc5c8\ub2e4. \uce74\ub124\uae30\uc758 \uc804\uae30\ub294 \uc640\ud2b8\uc758 \uc131\ucde8\ub97c \ub192\uc774 \ud3c9\uac00\ud558\uc9c0\ub9cc, \uadf8 \uc548\uc5d0 \uae30\ub85d\ub41c \ubc18\ub300 \uc758\uacac\ub3c4 \uc0ac\uc5c5\uc758 \uc0ac\ud68c\uc801 \uc870\uac74\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ubcfc\ud134\uacfc \uc640\ud2b8\uc758 \ubcf4\uc218\ub294 \uae30\uad00\uc774 \uc808\uc57d\ud558\ub294 \uc5f0\ub8cc\uc758 \uac00\uce58\uc640 \uc5f0\uacb0\ub418\uc5c8\ub2e4. \uc885\uc804 \uae30\uad00\uacfc \ube44\uad50\ud574 \uc544\ub080 \uc5f0\ub8cc \ube44\uc6a9\uc758 3\ubd84\uc758 1\uc744 \ubc1b\ub294 \ubc29\uc2dd\uc774\ub2e4. \uace0\uac1d\uc740 \ubb3c\uac74\uc744 \uc0c0\ub2e4\ub294 \uc0ac\uc2e4\ubfd0 \uc544\ub2c8\ub77c \uc55e\uc73c\ub85c \uc6b4\uc601\ube44\uac00 \uc5bc\ub9c8\ub098 \ub2ec\ub77c\uc9c0\ub294\uc9c0\ub97c \ubcf4\uac8c \ub41c\ub2e4. \uc774 \ubc29\uc2dd\uc5d0\uc11c\ub294 \uc131\ub2a5\uc744 \ub9d0\ub85c \uc790\ub791\ud558\ub294 \uac83\ub9cc\uc73c\ub85c \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4. \ube44\uad50 \uae30\uc900\uacfc \uce21\uc815, \uc5b4\ub5a4 \uc808\uac10\uc744 \ud68c\uc0ac\uc758 \uc131\uacfc\ub85c \ubcfc\uc9c0 \uc815\ud574\uc57c \ud55c\ub2e4. \ubc1c\uba85\ud488\uc774 \uc0ac\uc5c5\uc774 \ub418\uba74\uc11c \uc22b\uc790\uc758 \uc758\ubbf8\uac00 \ub298\uc5b4\ub09c\ub2e4. \uae30\uacc4\uac00 \uc798 \uc6c0\uc9c1\uc778\ub2e4\ub294 \uad00\ucc30\uc774 \ub3c8\uc744 \uc5bc\ub9c8 \uc9c0\uae09\ud574\uc57c \ud558\ub294\uac00 \ud558\ub294 \uacc4\uc57d\uc758 \ubb38\uc81c\ub85c \uc774\uc5b4\uc9c4\ub2e4. \uc808\uac10\uc561\uc5d0 \ub530\ub77c \ub3c8\uc744 \ubc1b\ub294 \uacc4\uc57d\uc740 \uc774\uc804\uc5d0 \ubb34\uc5c7\uc744 \uc37c\ub294\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \ube44\uad50 \ub300\uc0c1\uc774 \ubc14\ub00c\uba74 \uac19\uc740 \uae30\uad00\uc758 \uacbd\uc81c\uc801 \ud6a8\uacfc\ub3c4 \ub2e4\ub974\uac8c \ubcf4\uc77c \uc218 \uc788\ub2e4. \uc131\ub2a5\uc740 \uae30\uacc4 \uc548\uc758 \uace0\uc815\ub41c \uc22b\uc790\ub9cc\uc774 \uc544\ub2c8\ub77c \uace0\uac1d\uc758 \uc870\uac74\uacfc \ube44\uad50\ud574 \uacc4\uc0b0\ub418\ub294 \uac12\uc774\uc5c8\ub2e4. \uc774\ub7f0 \uad6c\uc870\uc5d0\uc11c\ub294 \uae30\uad00\uc744 \uc124\uce58\ud55c \ub4a4\uc5d0\ub3c4 \uad00\uacc4\uac00 \uacc4\uc18d\ub41c\ub2e4. \ucc98\uc74c \uac00\uaca9\uc744 \ubc1b\uace0 \ub05d\ub098\ub294 \ud310\ub9e4\uc640 \ub2ec\ub9ac \uc5bc\ub9c8\ub098 \uc791\ub3d9\ud588\uace0 \ubb34\uc5c7\uc774 \uc808\uc57d\ub418\uc5c8\ub294\uc9c0 \uc54c\uc544\uc57c \ud55c\ub2e4. \uc0ac\uc5c5\uc758 \uc218\uc785\uc774 \uc7a5\uae30\uc801\uc778 \uc0ac\uc6a9\uc5d0 \uc5f0\uacb0\ub418\uba74\uc11c, \uc124\uacc4\uc790\uc758 \uad00\uc2ec\ub3c4 \uc81c\uc791\uc18c \ubc16\uc758 \uad11\uc0b0\uc73c\ub85c \uc774\uc5b4\uc84c\ub2e4. \uc124\uce58 \uc7a5\uc18c\uac00 \ub298\uc5b4\ub098\uba74 \uc81c\uc870\uc18c \uc548\uc5d0\uc11c \ubaa8\ub4e0 \uc77c\uc744 \ubcfc \uc218 \uc5c6\ub2e4. \ud604\uc7a5\uc758 \uae30\uc220\uc790\uc640 \uad11\uc0b0 \uad00\ub9ac\uc778, \ud68c\uc0ac \uc0ac\uc774\uc5d0 \uc815\ubcf4\uac00 \uc624\uac00\uc57c \ud55c\ub2e4. \uae30\uacc4\uc758 \uc0c1\ud0dc\ub97c \uc54c\uc544\ub0b4\uace0 \uc815\ube44\ud558\uba70 \uc57d\uc18d\ud55c \uc870\uac74\uc744 \ud655\uc778\ud558\ub294 \uad00\uacc4\uac00 \ud544\uc694\ud588\ub2e4. \ud310\ub9e4 \uc774\ud6c4\uc758 \uc77c\uc774 \uc624\ud788\ub824 \ub354 \uae38 \uc218 \uc788\uc5c8\ub2e4. \uc5f0\ub8cc\ub97c \uc544\ub080\ub2e4\ub294 \ubc29\uc2dd\uc73c\ub85c \ubcf4\uc218\ub97c \ubc1b\uc73c\uba74 \uace0\uac1d\uacfc \ud310\ub9e4\uc790\uc758 \uc774\ud574\uac00 \uc77c\ubd80 \uc5f0\uacb0\ub41c\ub2e4. \ub3d9\uc2dc\uc5d0 \uc808\uac10\uc561\uc758 \uacc4\uc0b0\uc744 \ub458\ub7ec\uc2fc \ub2e4\ud23c\ub3c4 \uc0dd\uae38 \uc218 \uc788\ub2e4. \uc804\uae30\uc5d0\ub294 \uc131\ub2a5\uc774 \uc785\uc99d\ub41c \ub4a4\uc5d0\ub3c4 \uc9c0\uae09 \uc870\uac74\uc744 \ub193\uace0 \uac08\ub4f1\ud55c \uc0ac\ub840\uac00 \ub098\uc628\ub2e4. \uc88b\uc740 \uae30\uc220\uc774 \uacc4\uc57d\uc758 \uac08\ub4f1\uae4c\uc9c0 \uc5c6\uc560 \uc8fc\uc9c0\ub294 \uc54a\uc558\ub2e4. \uae30\uad00\uc758 \uc131\ub2a5\uc740 \ub3c4\uba74\uc758 \uc544\uc774\ub514\uc5b4\ubfd0 \uc544\ub2c8\ub77c \uc81c\uc791\uc758 \uc815\ud655\ub3c4\uc5d0 \ub2ec\ub824 \uc788\uc5c8\ub2e4. \uc2e4\ub9b0\ub354\uc640 \uc6c0\uc9c1\uc774\ub294 \ubd80\ubd84\uc774 \uae30\ub300\ud55c \uc0c1\ud0dc\ub85c \ub9de\uc544\uc57c \ud588\ub2e4. \ubc1c\uba85\uac00\uc758 \uc774\ub984 \ub4a4\uc5d0\ub294 \uae08\uc18d\uc744 \uac00\uacf5\ud558\uace0 \ud604\uc7a5\uc5d0\uc11c \uc870\ub9bd\ud55c \uc0ac\ub78c\ub4e4\uc758 \ub2a5\ub825\uc774 \ub193\uc778\ub2e4. \ub3d9\uc5c5 \ud68c\uc0ac\ub294 \uadf8\ub7f0 \ub2a5\ub825\uc744 \uc5f0\uacb0\ud558\ub294 \uc870\uc9c1\uc774\uae30\ub3c4 \ud588\ub2e4. \uacf5\uc7a5 \uc548\uc758 \uc81c\uc791\uacfc \ubc14\uae65\uc758 \uc124\uce58\ub97c \uc774\uc5b4\uc57c \ud588\uace0, \ud55c\ubc88 \ud574\uacb0\ud55c \ubb38\uc81c\ub97c \ub2e4\uc74c \uae30\uad00\uc5d0\ub3c4 \uc801\uc6a9\ud574\uc57c \ud588\ub2e4. \ud558\ub098\uc758 \uc131\uacf5\uc744 \ubc18\ubcf5 \uac00\ub2a5\ud55c \uacf5\uae09\uc73c\ub85c \ubc14\uafb8\ub294 \uc77c\uc774 \uae30\uc5c5\uc758 \ubaab\uc774\uc5c8\ub2e4. \ubc1c\uba85\uc744 \ubcf5\uc81c\ud55c\ub2e4\ub294 \ub9d0\uc5d0\ub294 \uc0ac\ub78c\uacfc \uc791\uc5c5 \uc21c\uc11c\ub97c \uc900\ube44\ud558\ub294 \uc77c\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \ubcfc\ud134\uacfc \uc640\ud2b8\ub294 \ucca0\uacfc \ubd80\ud488\ub9cc \ud310 \uac83\uc774 \uc544\ub2c8\ub2e4. \uace0\uac1d\uc758 \ube44\uc6a9\uc744 \uc904\uc77c \uc218 \uc788\ub2e4\ub294 \uac00\ub2a5\uc131\uacfc \uadf8 \uac00\ub2a5\uc131\uc744 \uc2e4\ud604\ud560 \uae30\uc220\uc744 \ud568\uaed8 \uc81c\uacf5\ud588\ub2e4. \ubb3c\ub860 \ubaa8\ub4e0 \uacb0\uacfc\uac00 \uacc4\ud68d\ub300\ub85c \ub41c \uac83\uc740 \uc544\ub2c8\uba70, \ud2b9\ud5c8\uc640 \uacc4\uc0b0\uc758 \ub2e4\ud23c\ub3c4 \uc0ac\uc5c5\uc758 \uc77c\ubd80\uc600\ub2e4. \uc774 \uc0ac\ub840\ub294 \ubc1c\uba85\uac00 \ud55c \uc0ac\ub78c\uc758 \ubc88\ub729\uc784\uc73c\ub85c \uc0b0\uc5c5\uc758 \ubcc0\ud654\ub97c \ubaa8\ub450 \uc124\uba85\ud558\uae30 \uc5b4\ub835\uac8c \ub9cc\ub4e0\ub2e4. \uc124\uacc4\uc640 \uc790\uae08, \uc81c\uc791\uacfc \ud604\uc7a5 \uad00\ub9ac, \uc131\ub2a5\uc744 \uac00\uaca9\uc73c\ub85c \ubc14\uafb8\ub294 \uacc4\uc57d\uc774 \ud544\uc694\ud588\ub2e4. \uc99d\uae30\uae30\uad00\uc758 \uc5ed\uc0ac\ub97c \uae30\uacc4 \ubc16\uc73c\ub85c \ub113\ud788\uba74, \uc808\uc57d\ud55c \uc11d\ud0c4\uc774 \ud68c\uc0ac\uc758 \uc218\uc785\uc774 \ub418\ub294 \uacfc\uc815\uc5d0\uc11c \uae30\uc5c5\uc774\ub77c\ub294 \uc870\uc9c1\uc774 \ubcf4\uc778\ub2e4."}, {"id": "boxed-bulk-shopping-without-car", "title": "\ubc15\uc2a4\ub4dc \u2014 \ucc28 \uc5c6\uc774\ub3c4 \ucc3d\uace0\ud615 \uc1fc\ud551\uc744 \ud560 \uc218 \uc788\uc744\uae4c", "summary": "2016\ub144 \ucc3d\uc5c5\uc790 \uc778\ud130\ubdf0\ub97c \uc778\uc6a9\ud55c \uad50\uc7ac \uc0ac\ub840\ub85c \ub300\uc6a9\ub7c9 \uc0c1\ud488\uacfc \ubaa8\ubc14\uc77c \uc8fc\ubb38, \ubc30\uc1a1\uc758 \uc5f0\uacb0\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\uc0c1\uc5c5\uacfc \uc720\ud1b5", "categories": ["industry"], "url": "stories/boxed-bulk-shopping-without-car/index.html", "image": "../media/boxed-bulk-shopping-without-car.png", "alt": "\ub3c4\uc2dc\uc758 \uc9d1 \uc55e\uc5d0\uc11c \ud070 \ubb36\uc74c\uc758 \uc0dd\ud65c\uc6a9\ud488\uc744 \ubc1b\ub294 \uc77c\ubc18\uc801\uc778 \ubc30\uc1a1 \uc7a5\uba74\uc758 \uc0bd\ud654.", "text": "\ubc15\uc2a4\ub4dc \u2014 \ucc28 \uc5c6\uc774\ub3c4 \ucc3d\uace0\ud615 \uc1fc\ud551\uc744 \ud560 \uc218 \uc788\uc744\uae4c \ub3c4\uc2dc \uc0dd\ud65c\uc758 \uc791\uc740 \ubd88\ud3b8\uc5d0\uc11c \uc2dc\uc791\ud55c 2010\ub144\ub300\uc758 \uc0ac\uc5c5 \uad6c\uc0c1 2016\ub144 \ucc3d\uc5c5\uc790 \uc778\ud130\ubdf0\ub97c \uc778\uc6a9\ud55c \uad50\uc7ac \uc0ac\ub840\ub85c \ub300\uc6a9\ub7c9 \uc0c1\ud488\uacfc \ubaa8\ubc14\uc77c \uc8fc\ubb38, \ubc30\uc1a1\uc758 \uc5f0\uacb0\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc0c1\uc5c5\uacfc \uc720\ud1b5 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \ud070 \ubb36\uc74c\uc758 \ud734\uc9c0\ub098 \uc0dd\ud65c\uc6a9\ud488\uc740 \ub0b1\uac1c\ubcf4\ub2e4 \uc800\ub834\ud558\uac8c \ub290\uaef4\uc9c8 \ub54c\uac00 \uc788\ub2e4. \ubb38\uc81c\ub294 \uc0ac\ub294 \uc21c\uac04\ubcf4\ub2e4 \uc9d1\uae4c\uc9c0 \uac00\uc838\uc624\ub294 \uae38\uc774\ub2e4. \ucc28\uac00 \uc5c6\uace0 \ub9e4\uc7a5\uc774 \uba40\ub2e4\uba74 \uc88b\uc740 \uac00\uaca9 \uc55e\uc5d0\ub3c4 \ub2e4\ub978 \ube44\uc6a9\uc774 \uc0dd\uae34\ub2e4. \ubb3c\uac74\uc758 \uac12\uacfc \uadf8\uac83\uc744 \uc5bb\ub294 \ub370 \ub4dc\ub294 \uc218\uace0\ub294 \uac19\uc740 \ud56d\ubaa9\uc774 \uc544\ub2c8\ub2e4. \ubbf8\uad6d \uae30\uc5c5 \ubc15\uc2a4\ub4dc\uc758 \ucd08\uae30 \uad6c\uc0c1\uc740 \uc774\ub7f0 \ubd88\ud3b8\uc744 \uaca8\ub0e5\ud588\ub2e4. \uc5ec\uae30\uc11c\ub294 \uacbd\uc601 \uad50\uc7ac\uac00 2016\ub144 \ucc3d\uc5c5\uc790 \uc778\ud130\ubdf0 \ub4f1\uc744 \ubc14\ud0d5\uc73c\ub85c \uc18c\uac1c\ud55c \ub2f9\uc2dc\uc758 \uc0ac\ub840\ub97c \uc77d\ub294\ub2e4. \ud604\uc7ac\uc758 \uc11c\ube44\uc2a4\uc640 \uae30\uc5c5 \uc0c1\ud0dc\ub97c \uc548\ub0b4\ud558\uac70\ub098 \uc774\ud6c4\uc758 \uacbd\uc601 \uc131\uacfc\ub97c \ud3c9\uac00\ud558\ub294 \uae00\uc740 \uc544\ub2c8\ub2e4. \uad50\uc7ac\uc5d0 \ub530\ub974\uba74 \ucc3d\uc5c5\uc790 \uce58\uc5d0 \ud669\uc740 \uad50\uc678\uc5d0\uc11c \uc0b4 \ub54c \ucc3d\uace0\ud615 \ub9e4\uc7a5\uc744 \uc774\uc6a9\ud588\uc9c0\ub9cc \ub3c4\uc2dc\ub85c \uc62e\uaca8 \ucc28\uac00 \uc5c6\uc5b4\uc9c0\uc790 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc7a5\uc744 \ubcf4\uae30 \uc5b4\ub824\uc6cc\uc84c\ub2e4. \uac00\uaca9\uc744 \uc544\ub294 \uac83\uacfc \uc2e4\uc81c\ub85c \uadf8 \uac00\uaca9\uc5d0 \ubb3c\uac74\uc744 \uc0b4 \uc218 \uc788\ub294 \uac83\uc740 \ub2ec\ub790\ub2e4. \uc0dd\ud65c \uc7a5\uc18c\uc758 \ubcc0\ud654\uac00 \uc0c8\ub85c\uc6b4 \ubb38\uc81c\ub97c \ub4dc\ub7ec\ub0b8 \uac83\uc774\ub2e4. \uc774 \uc7a5\uba74\uc5d0\ub294 \ud2b9\ubcc4\ud55c \ucca8\ub2e8 \uc81c\ud488\uc758 \ubc1c\uba85\uc774 \ub4f1\uc7a5\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc774\ubbf8 \uc788\ub358 \uc0c1\ud488\uacfc \ub9e4\uc7a5\uc774 \uc788\uc5c8\ub2e4. \ub2ec\ub77c\uc9c4 \uac83\uc740 \uc774\uc6a9\uc790\uc758 \uad50\ud1b5\uc218\ub2e8\uacfc \uc0dd\ud65c \ubc29\uc2dd\uc774\uc5c8\ub2e4. \uc775\uc219\ud55c \ubb3c\uac74\ub3c4 \uc5b4\ub5a4 \uc0ac\ub78c\uc5d0\uac8c \uc5b4\ub5a4 \uacbd\ub85c\ub85c \uc804\ub2ec\ub418\ub294\uc9c0\ub97c \ubc14\uafb8\uba74 \uc0ac\uc5c5\uc758 \uc9c8\ubb38\uc774 \uc0c8\ub85c \uc0dd\uae38 \uc218 \uc788\ub2e4. \ubc15\uc2a4\ub4dc\ub294 \ud734\uc9c0\uc640 \uc5d0\ub108\uc9c0\ubc14 \uac19\uc740 \ub300\uc6a9\ub7c9 \uc0c1\ud488\uc744 \uc571\uc73c\ub85c \uc8fc\ubb38\ud558\uace0 \uc9d1\uc73c\ub85c \ubc1b\ub294 \uad6c\uc0c1\uc744 \uc81c\uc2dc\ud588\ub2e4. \ud734\ub300\uc804\ud654 \ud654\uba74\uc5d0\uc11c\ub294 \uc190\uac00\ub77d\uc73c\ub85c \uace0\ub974\uc9c0\ub9cc \ud654\uba74 \ubc16\uc5d0\uc11c\ub294 \ud070 \ubd80\ud53c\uc758 \ubb3c\uac74\uc774 \uc774\ub3d9\ud574\uc57c \ud55c\ub2e4. \uc791\uc740 \uc8fc\ubb38 \uc7a5\uce58\uc640 \ud070 \ubb3c\ub958\uac00 \uc5f0\uacb0\ub418\ub294 \ubc29\uc2dd\uc774\ub2e4. \uace0\uac1d\uc5d0\uac8c \ud3b8\ub9ac\ud574\uc9c4 \uc77c\uc774 \uc0ac\ud68c \uc804\uccb4\uc5d0\uc11c \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uace0\uac1d\uc774 \ub9e4\uc7a5\uc5d0 \uac00\uc11c \ubb3c\uac74\uc744 \ub098\ub974\ub294 \uc218\uace0\uc758 \uc77c\ubd80\uac00 \uae30\uc5c5\uc758 \ubcf4\uad00\uacfc \ud3ec\uc7a5, \ubc30\uc1a1\uc73c\ub85c \uc62e\uaca8 \uac04\ub2e4. \uc628\ub77c\uc778 \uc0ac\uc5c5\uc744 \ud654\uba74\uc758 \uc774\uc57c\uae30\ub85c\ub9cc \ubcf4\uba74 \uc774 \uc774\ub3d9\uc774 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ud3b8\ub9ac\ud568 \ub4a4\uc5d0\ub294 \ub204\uad70\uac00\uc758 \uad6c\uccb4\uc801\uc778 \uc791\uc5c5\uc774 \uc788\ub2e4. \ubb3c\uac74\uc758 \ub2e8\uac00\uac00 \ub0ae\uc544\ub3c4 \ubaa8\ub4e0 \uc0ac\ub78c\uc5d0\uac8c \uac19\uc740 \uac00\uce58\uac00 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc9d1\uc5d0 \ub458 \uacf5\uac04\uacfc \ud544\uc694\ud55c \uc591, \uc8fc\ubb38 \uc870\uac74\uc744 \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \ud63c\uc790 \uc0ac\ub294 \uc0ac\ub78c\uc5d0\uac8c \ud070 \ubb36\uc74c\uc740 \ubcf4\uad00\uc758 \ubd80\ub2f4\uc77c \uc218\ub3c4 \uc788\ub2e4. \uc774\ubc88\uc5d0\ub294 \ud2b9\uc815 \uc0c1\ud488\uc758 \uc2e4\uc81c \uac00\uaca9\uc744 \ube44\uad50\ud558\ub294 \ub300\uc2e0 \uc120\ud0dd\uc5d0 \ub4e4\uc5b4\uac00\ub294 \uc870\uac74\uc744 \uc0b4\ud3b4\ubcf4\uc790. \ucc3d\uc5c5\uc790\uc758 \ubd88\ud3b8\uc774 \uc88b\uc740 \ucd9c\ubc1c\uc810\uc774 \ub420 \uc218\ub294 \uc788\uc9c0\ub9cc \uadf8\uac83\uc774 \ubaa8\ub4e0 \uace0\uac1d\uc758 \ud544\uc694\ub97c \ub300\ud45c\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub204\uad6c\uc5d0\uac8c \ubb38\uc81c\ub97c \ud480\uc5b4 \uc8fc\ub294\uc9c0 \ubc94\uc704\ub97c \uc815\ud574\uc57c \ud55c\ub2e4. \ub3c4\uc2dc\uc758 \ucc28 \uc5c6\ub294 \uc774\uc6a9\uc790\ub77c\ub294 \uad00\ucc30\uc774 \uc758\ubbf8 \uc788\uc5c8\ub358 \uc774\uc720\ub3c4 \ub9c9\uc5f0\ud788 \ubaa8\ub450\uc5d0\uac8c \uc88b\ub2e4\uace0 \ub9d0\ud558\uae30\ubcf4\ub2e4 \uad6c\uccb4\uc801\uc778 \uc0dd\ud65c \uc7a5\uba74\uc5d0\uc11c \uc2dc\uc791\ud588\uae30 \ub54c\ubb38\uc774\ub2e4. \uad50\uc7ac\ub294 \ucd08\uae30 \uc131\uc7a5 \uacfc\uc815\uc5d0\uc11c \uc790\uae08\uc744 \ub9c8\ub828\ud558\uace0 \ubb3c\ub958\uc13c\ud130\ub97c \uc138\uc6b0\uba70 \uc9c1\uc6d0\uc744 \ucc44\uc6a9\ud55c \uc77c\uc744 \uc18c\uac1c\ud55c\ub2e4. \uacf5\uae09\uc790\uc640\uc758 \uad00\uacc4\ub97c \ub113\ud788\uace0 \uc790\uccb4 \uc0c1\ud45c \uc0c1\ud488\ub3c4 \uac1c\ubc1c\ud588\ub2e4. \uc8fc\ubb38\uc744 \ubc1b\ub294 \uae30\ub2a5 \ub4a4\uc5d0 \ubb3c\uac74\uc744 \ud655\ubcf4\ud558\uace0 \uc6c0\uc9c1\uc77c \uc900\ube44\uac00 \ud544\uc694\ud588\ub358 \uac83\uc774\ub2e4. \uc8fc\ubb38\uc774 \ub298\uc5b4\ub098\ub294 \uac83\uacfc \uc8fc\ubb38\uc744 \uc81c\ub300\ub85c \ucc98\ub9ac\ud560 \uc218 \uc788\ub294 \ub2a5\ub825\uc774 \ub298\uc5b4\ub098\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uc7ac\uace0\uc640 \uc791\uc5c5, \ubc30\uc1a1\uc758 \uc18d\ub3c4\ub97c \ub9de\ucd94\uc5b4\uc57c \ud55c\ub2e4. \ud2b9\ud788 \ud070 \ubb36\uc74c\uc758 \uc0dd\ud65c\uc6a9\ud488\uc740 \ud654\uba74\uc5d0\uc11c\ub294 \uac19\uc740 \ud06c\uae30\uc758 \uc0ac\uc9c4\uc774\uc5b4\ub3c4 \uc2e4\uc81c \uacf5\uac04\uc5d0\uc11c\ub294 \ubd80\ud53c\uac00 \ud06c\ub2e4. \ub514\uc9c0\ud138\uc758 \ud3b8\ub9ac\ud568\uc740 \ubb3c\ub9ac\uc801 \uc870\uac74\uacfc \ub530\ub85c \uc6c0\uc9c1\uc77c \uc218 \uc5c6\ub2e4. \uad50\uc7ac\uac00 \uc778\uc6a9\ud55c \ub2f9\uc2dc \ud669\uc758 \uc124\uba85\uc5d0\ub294 \uac00\uce58\uc640 \ud3b8\ub9ac\ud568, \ube0c\ub79c\ub4dc\uc758 \uc911\uc694\uc131\uc774 \ud568\uaed8 \ub098\uc628\ub2e4. \uacbd\uc7c1\uc790\ub4e4\ub3c4 \ube44\uc2b7\ud55c \uac00\uaca9\uacfc \ubc30\uc1a1\uc744 \uc81c\uacf5\ud558\uba74 \uace0\uac1d\uc740 \ub2e4\ub978 \uae30\uc900\uc73c\ub85c \ud68c\uc0ac\ub97c \uad6c\ubcc4\ud560 \uc218 \uc788\ub2e4. \ucc98\uc74c\uc758 \uc88b\uc740 \uc544\uc774\ub514\uc5b4\uac00 \uacc4\uc18d \ub3c5\uc810\uc801\uc778 \uc7a5\uc810\uc73c\ub85c \ub0a8\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774 \uc9c8\ubb38\uc740 \ubc15\uc2a4\ub4dc\uc5d0\ub9cc \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub530\ub77c \ud558\uae30 \uc26c\uc6b4 \uae30\ub2a5\uacfc \uc624\ub798 \uc313\uc544\uc57c \ud558\ub294 \uc2e0\ub8b0\ub294 \uc11c\ub85c \ub2e4\ub978 \uc790\uc0b0\uc774\ub2e4. \ud55c \ubc88\uc758 \uc8fc\ubb38\uc744 \uc5bb\ub294 \ubc29\ubc95\uacfc \ub2e4\uc2dc \uc120\ud0dd\ubc1b\ub294 \uc774\uc720\ub97c \ub098\ub204\uc5b4 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uac00\uaca9\ud45c\uac00 \ube44\uc2b7\ud574\uc9c4 \ub2e4\uc74c\uc5d0\ub3c4 \uace0\uac1d\uc758 \uacbd\ud5d8\uc740 \uac19\uc740 \ubaa8\uc591\uc77c \ud544\uc694\uac00 \uc5c6\ub2e4. \uad50\uc7ac\ub294 \ub2f9\uc2dc \ud669\uc774 \uc9c1\uc6d0 \uc790\ub140\uc758 \ub300\ud559 \uad50\uc721\uacfc \uacb0\ud63c \ube44\uc6a9\uc744 \uc9c0\uc6d0\ud55c \uc0ac\ub840\uac00 \ud68c\uc0ac \uc774\ubbf8\uc9c0\uc640 \uc5f0\uacb0\ub418\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc77c\ubd80 \uace0\uac1d\uc5d0\uac8c\ub294 \uae30\uc5c5\uc774 \uc0ac\ub78c\uc744 \ub300\ud558\ub294 \ubc29\uc2dd\ub3c4 \uc120\ud0dd \uae30\uc900\uc774 \ub420 \uc218 \uc788\ub2e4\ub294 \uc124\uba85\uc774\ub2e4. \uc0c1\ud488\uc758 \uac00\uce58\uc640 \uae30\uc5c5\uc774 \ub0b4\uc138\uc6b0\ub294 \uac00\uce58\uac00 \ub9cc\ub098\ub294 \uc9c0\uc810\uc774\ub2e4. \ub2e4\ub9cc \uacfc\uac70 \uc0ac\ub840\ub97c \ud604\uc7ac \ubaa8\ub4e0 \uc9c1\uc6d0\uc758 \ubcf5\uc9c0 \uaddc\uc815\uc73c\ub85c \uc77d\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uae30\uc5c5\uc5d0 \uad00\ud55c \uc88b\uc740 \uc774\uc57c\uae30 \ud55c \uac00\uc9c0\uac00 \uc7ac\ubb34\uc640 \uc6b4\uc601 \uc804\uccb4\ub97c \ud3c9\uac00\ud574 \uc8fc\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uc2dc\uae30\uc758 \uc5b4\ub5a4 \ud589\ub3d9\uc744 \uadfc\uac70\ub85c \ud558\ub294\uc9c0 \ub098\ub204\uc5b4 \ubcf4\uba74 \ud638\uac10\uacfc \ud655\uc778\uc744 \ud568\uaed8 \uc720\uc9c0\ud560 \uc218 \uc788\ub2e4. \uacbd\uc601 \uad50\uc7ac\ub294 \uae30\uc5c5\uc758 \ud55c \uc7a5\uba74\uc744 \uace8\ub77c \ud2b9\uc815 \uc6d0\ub9ac\ub97c \uc124\uba85\ud55c\ub2e4. \uadf8 \uae30\uc5c5\uc758 \uc774\ud6c4 \uc5ed\uc0ac\ub97c \uc804\ubd80 \ub530\ub77c\uac00\ub294 \uc790\ub8cc\ub294 \uc544\ub2d0 \uc218 \uc788\ub2e4. \ubc15\uc2a4\ub4dc\uc758 \uc774 \uc0ac\ub840\ub3c4 \ubaa8\ubc14\uc77c \uc8fc\ubb38\uacfc \ub300\uc6a9\ub7c9 \ubc30\uc1a1\uc744 \uc5f0\uacb0\ud55c \ucd08\uae30 \uc804\ub7b5\uc744 \uc774\ud574\ud558\ub294 \ub370 \ucd08\uc810\uc744 \ub450\uc5b4\uc57c \ud55c\ub2e4. \ub530\ub77c\uc11c \uacfc\uac70\uc5d0 \uad00\uc2ec\uc744 \ubaa8\uc558\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ud604\uc7ac\uae4c\uc9c0 \uac19\uc740 \uc131\uacfc\uac00 \uc774\uc5b4\uc84c\ub2e4\ub294 \ub9d0\ub85c \ubc14\uafb8\uc9c0 \uc54a\ub294\ub2e4. \uc88b\uc740 \ubb38\uc81c\ub97c \ucc3e\ub294 \uc77c\uacfc \uc7a5\uae30\uac04 \uc0ac\uc5c5\uc744 \uc720\uc9c0\ud558\ub294 \uc77c\uc5d0\ub294 \ub2e4\ub978 \uc870\uac74\ub3c4 \ud544\uc694\ud558\ub2e4. \uc0ac\ub840\uac00 \ubcf4\uc5ec \uc8fc\ub294 \ud1b5\ucc30\uc744 \uc77d\uc73c\uba74\uc11c \ub3d9\uc2dc\uc5d0 \uc790\ub8cc\uac00 \ub2e4\ub8e8\ub294 \uc2dc\uac04\uc758 \ub05d\uc744 \uc54c\uc544 \ub450\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \ub3c4\uc2dc\uc758 \uc9d1 \uc55e\uc5d0 \uc0dd\ud65c\uc6a9\ud488\uc774 \ub3c4\ucc29\ud558\ub294 \uc77c\ubc18\uc801\uc778 \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c \ubc15\uc2a4\ub4dc\uc758 \ud3ec\uc7a5\uacfc \ubc30\uc1a1 \ubc29\uc2dd, \uc9c1\uc6d0\uc774\ub098 \uace0\uac1d\uc744 \uc7ac\ud604\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc0c1\ud488\uc774 \uc9d1\uae4c\uc9c0 \uc774\ub3d9\ud55c\ub2e4\ub294 \uad6c\uc0c1\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc704\ud55c \uadf8\ub9bc\uc774\ub2e4. \uc774 \ucd08\uae30 \uc0ac\ub840\ub294 \uc0c8\ub85c\uc6b4 \uc0ac\uc5c5\uc774 \uaf2d \uc0c8\ub85c\uc6b4 \ubb3c\uac74\uc5d0\uc11c \uc2dc\uc791\ud558\ub294 \uac83\uc740 \uc544\ub2d8\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc774\ubbf8 \uc788\ub294 \ubb3c\uac74\uc744 \uc5b4\ub5a4 \uc0dd\ud65c \uc870\uac74\uc758 \uc0ac\ub78c\uc5d0\uac8c \uc5b4\ub5bb\uac8c \uc804\ub2ec\ud560\uc9c0\ub3c4 \uc9c8\ubb38\uc774 \ub41c\ub2e4. \ucc3d\uace0\ud615 \uc1fc\ud551\uc758 \ud070 \ubb36\uc74c\uacfc \ucc28 \uc5c6\ub294 \ub3c4\uc2dc\uc778\uc758 \uc791\uc740 \uc9d1 \uc0ac\uc774\uc5d0\ub294 \uac00\uaca9\ud45c\ub9cc\uc73c\ub85c \ubcf4\uc774\uc9c0 \uc54a\ub294 \uae38\uc774 \uc788\uc5c8\ub2e4."}, {"id": "carnegie-steel-chain-and-homestead", "title": "\uce74\ub124\uae30 \u2014 \ucca0\uac15 \uacf5\uc7a5\ubcf4\ub2e4 \uae38\uc5c8\ub358 \uc0dd\uc0b0\uc758 \uc0ac\uc2ac", "summary": "\uce74\ub124\uae30 \ucca0\uac15\uc758 \uc218\uc9c1 \ud1b5\ud569\uacfc \ud648\uc2a4\ud14c\ub4dc \ubd84\uc7c1\uc744 \ud1b5\ud574 \uae30\uc5c5\uc758 \uc131\uc7a5\uc744 \uc5ec\ub7ec \uc2dc\uc120\uc73c\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\uacf5\uc7a5\uacfc \uc0dd\uc0b0", "categories": ["industry"], "url": "stories/carnegie-steel-chain-and-homestead/index.html", "image": "../media/carnegie-steel-chain-and-homestead.png", "alt": "\ucca0\ub3c4 \ud654\ucc28\uc640 \uc81c\ucca0 \uc124\ube44, \ub178\ub3d9\uc790\uac00 \ud568\uaed8 \ubcf4\uc774\ub294 19\uc138\uae30 \ucca0\uac15 \uc0b0\uc5c5\uc758 \ud574\uc11d\uc801 \uc0bd\ud654", "text": "\uce74\ub124\uae30 \u2014 \ucca0\uac15 \uacf5\uc7a5\ubcf4\ub2e4 \uae38\uc5c8\ub358 \uc0dd\uc0b0\uc758 \uc0ac\uc2ac \uad11\uc0b0\uc5d0\uc11c \uc6b4\uc1a1\uacfc \uc81c\ucca0\uae4c\uc9c0, \ud6a8\uc728\uc758 \uc5ed\uc0ac\uc5d0 \ub178\ub3d9\uc758 \uc2dc\uac04\uc744 \ub354\ud558\ub2e4 \uce74\ub124\uae30 \ucca0\uac15\uc758 \uc218\uc9c1 \ud1b5\ud569\uacfc \ud648\uc2a4\ud14c\ub4dc \ubd84\uc7c1\uc744 \ud1b5\ud574 \uae30\uc5c5\uc758 \uc131\uc7a5\uc744 \uc5ec\ub7ec \uc2dc\uc120\uc73c\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uacf5\uc7a5\uacfc \uc0dd\uc0b0 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \ucca0\uc744 \ub9cc\ub4dc\ub294 \uacf5\uc7a5\uc744 \uac00\uc84c\ub2e4\uba74 \ub2e4\uc74c\uc5d0\ub294 \ubb34\uc5c7\uc744 \uc0ac\uc57c \ud560\uae4c. \ub354 \ud070 \uc6a9\uad11\ub85c\uac00 \uba3c\uc800 \ub5a0\uc624\ub974\uc9c0\ub9cc \uc564\ub4dc\ub8e8 \uce74\ub124\uae30\uc758 \uc0ac\uc5c5\uc740 \uacf5\uc7a5 \ubc14\uae65\uc73c\ub85c\ub3c4 \ubed7\uc5c8\ub2e4. \uc6d0\ub8cc\ub97c \uc5bb\ub294 \uacf3\uacfc \uc62e\uae30\ub294 \uae38, \uc2e4\uc81c \uc81c\ud488\uc744 \ub9cc\ub4dc\ub294 \uc2dc\uc124\uc744 \ud568\uaed8 \ub2e4\ub8e8\ub824 \ud588\ub2e4. \ucca0\uac15\uc740 \uacf5\uc7a5\uc758 \ub2f4\uc7a5 \uc548\uc5d0\uc11c\ub9cc \ub9cc\ub4e4\uc5b4\uc9c0\ub294 \uc0c1\ud488\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uce74\ub124\uae30\ub97c \ub3c4\uc11c\uad00\uc744 \uae30\ubd80\ud55c \ubd80\uc790\ub85c \uae30\uc5b5\ud558\ub294 \uc0ac\ub78c\ub3c4 \uc788\uace0, \uac00\ub09c\uc5d0\uc11c \ucd9c\ubc1c\ud55c \uc131\uacf5\uc758 \uc778\ubb3c\ub85c \ub5a0\uc62c\ub9ac\ub294 \uc0ac\ub78c\ub3c4 \uc788\ub2e4. \uadf8 \uc774\uc57c\uae30\ub4e4\uc744 \uc870\uae08 \uc606\uc5d0 \ub450\uace0 \uc0dd\uc0b0\uc774 \uc774\uc5b4\uc9c0\ub294 \uae38\uc744 \ubcf4\uba74 \uadf8\uc758 \uc131\uc7a5 \ubc29\uc2dd\uacfc \uadf8 \uc548\uc758 \uac08\ub4f1\uc774 \ud568\uaed8 \ubcf4\uc778\ub2e4. 19\uc138\uae30 \ud6c4\ubc18 \ucca0\ub3c4\uc640 \ub3c4\uc2dc, \uc0b0\uc5c5 \uc2dc\uc124\uc774 \ucee4\uc9c0\uba74\uc11c \uac15\ucca0\uc744 \uc0ac\uc6a9\ud560 \uc790\ub9ac\uac00 \ub113\uc5b4\uc84c\ub2e4. \ucca0\uac15\uc744 \ub9cc\ub4dc\ub294 \uae30\uc220\uc758 \ubc1c\uc804\uc740 \uae30\uc5c5\uac00\uc5d0\uac8c \uc0c8\ub85c\uc6b4 \uae30\ud68c\ub97c \uc81c\uacf5\ud588\ub2e4. \ud558\uc9c0\ub9cc \uc88b\uc740 \uae30\uc220\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ud070 \uc0ac\uc5c5\uc774 \uc800\uc808\ub85c \ub9cc\ub4e4\uc5b4\uc9c0\uc9c0\ub294 \uc54a\uc558\ub2e4. \uc124\ube44\uc640 \uc790\uae08, \uc6d0\ub8cc\uc640 \ud310\ub9e4\uc758 \uc870\uac74\ub3c4 \ub9de\ubb3c\ub824\uc57c \ud588\ub2e4. \uce74\ub124\uae30\uc758 \uc131\uc7a5\uc744 \uc774\ud574\ud558\ub824\uba74 \uadf8\uac00 \ud2b9\ubcc4\ud788 \uc601\ub9ac\ud588\ub2e4\ub294 \ud3c9\uac00\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud558\ub2e4. \uac15\ucca0\uc774 \ud544\uc694\ud55c \uc0b0\uc5c5\uc774 \ucee4\uc9c0\uace0 \uc788\uc5c8\uace0 \ud070 \uc124\ube44\ub97c \uc6b4\uc601\ud560 \uc218 \uc788\ub294 \uc790\ubcf8\ub3c4 \uc6c0\uc9c1\uc600\ub2e4. \uac1c\uc778\uc758 \uc120\ud0dd\uacfc \uc2dc\ub300\uc758 \uc218\uc694\ub97c \ud568\uaed8 \ubcf4\uc544\uc57c \uc131\uacf5\uc744 \ub204\uad6c\ub098 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ubc18\ubcf5\ud560 \uc218 \uc788\ub294 \uac04\ub2e8\ud55c \uacf5\uc2dd\uc73c\ub85c \uc624\ud574\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc81c\ucca0\uc18c\uc5d0 \uc6d0\ub8cc\uac00 \uc81c\ub54c \ub3c4\ucc29\ud558\uc9c0 \uc54a\uac70\ub098 \uc6b4\uc1a1\ube44\uac00 \ud754\ub4e4\ub9ac\uba74 \uacf5\uc7a5 \uc548\uc758 \ud6a8\uc728\ub9cc\uc73c\ub85c \ubb38\uc81c\ub97c \ud574\uacb0\ud558\uae30 \uc5b4\ub835\ub2e4. \uce74\ub124\uae30\ub294 \uc0dd\uc0b0\uc5d0 \ud544\uc694\ud55c \uc5ec\ub7ec \ub2e8\uacc4\ub97c \uc790\uae30 \uc0ac\uc5c5\uc758 \ubc94\uc704 \uc548\uc73c\ub85c \uac00\uc838\uc654\ub2e4. \uad11\uc0b0\uacfc \uc6b4\uc1a1, \uc81c\uc870 \uc2dc\uc124\uc774 \uc774\uc5b4\uc9c0\uba74 \ubc14\uae65 \uac70\ub798\uc5d0 \uc758\uc874\ud558\ub358 \ubd80\ubd84\uc744 \uc9c1\uc811 \uc870\uc815\ud560 \uc218 \uc788\ub2e4. \uc774\ub97c \uc218\uc9c1 \ud1b5\ud569\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \uc774\ub984\uc740 \uc5b4\ub835\uc9c0\ub9cc \uc6d0\ub9ac\ub294 \uc0dd\uc0b0\uc758 \uc55e\uacfc \ub4a4\ub97c \ud568\uaed8 \uad00\ub9ac\ud55c\ub2e4\ub294 \uac83\uc774\ub2e4. \ube75\uc9d1\uc774 \ubc00\uac00\ub8e8\ub97c \ub9cc\ub4dc\ub294 \uacf5\uc815\uc774\ub098 \ubc30\ub2ec\uc744 \ud568\uaed8 \ub2e4\ub8e8\ub294 \uacbd\uc6b0\ub97c \uc0dd\uac01\ud558\uba74 \uc870\uae08 \uac00\uae5d\ub2e4. \ub2e4\ub9cc \ucca0\uac15\uc740 \uaddc\ubaa8\uc640 \ube44\uc6a9\uc774 \ud6e8\uc52c \ud06c\uba70, \uc5f0\uacb0\ub41c \uc2dc\uc124\uc744 \uc6b4\uc601\ud558\ub294 \ucc45\uc784\ub3c4 \uadf8\ub9cc\ud07c \ubb34\uac70\uc6e0\ub2e4. \uc5ec\ub7ec \ub2e8\uacc4\ub97c \uc870\uc815\ud558\uba74 \ub0ad\ube44\ub97c \uc904\uc774\uace0 \uc6d0\uac00\ub97c \uad00\ub9ac\ud560 \uc5ec\uc9c0\uac00 \uc0dd\uae34\ub2e4. \ub354 \uc2fc \uac12\uc73c\ub85c \uacf5\uae09\ud560 \uc218 \uc788\ub2e4\uba74 \ub9ce\uc740 \uc8fc\ubb38\uc744 \uc5bb\ub294 \ub370 \uc720\ub9ac\ud574\uc9c4\ub2e4. \uae30\uc5c5\uc774 \ucee4\uc9c0\ub294 \uacfc\uc815\uc5d0\ub294 \ub2e8\uc9c0 \ub0a8\uc758 \ubaab\uc744 \ube7c\uc557\ub294 \uc77c\ub9cc \uc544\ub2c8\ub77c \uc0dd\uc0b0\uacfc \uc720\ud1b5\uc758 \uc2e4\uc81c \ubcc0\ud654\ub3c4 \uc788\uc5c8\ub2e4. \uc131\uc7a5\uc758 \uae30\uc220\uc801 \uce21\uba74\uc744 \uc9c0\uc6cc\uc11c\ub294 \uc548 \ub41c\ub2e4. \uadf8\ub7ec\ub098 \uc6d0\uac00\ub97c \ub0ae\ucd94\uc5c8\ub2e4\ub294 \ub9d0\uc740 \uadf8 \uc790\uccb4\ub85c \ubaa8\ub450\uac00 \uac19\uc740 \uc774\uc775\uc744 \uc5bb\uc5c8\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \ube44\uc6a9\uc744 \uc904\uc600\ub294\uc9c0, \uadf8 \uacb0\uc815\uc774 \ub178\ub3d9\uc790\uc5d0\uac8c \uc5b4\ub5a4 \ubd80\ub2f4\uc744 \uc8fc\uc5c8\ub294\uc9c0\ub3c4 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uac12\uc2fc \uc0c1\ud488\uacfc \uc88b\uc740 \uc77c\uc790\ub9ac\ub294 \uc790\ub3d9\uc73c\ub85c \uac19\uc740 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294\ub2e4. \ud6a8\uc728\uc744 \ud3c9\uac00\ud560 \ub54c \ub0a8\uaca8 \ub450\uc5b4\uc57c \ud558\ub294 \uc9c8\ubb38\uc774\ub2e4. \uacbd\uc601\uc790\uc5d0\uac8c \uacf5\uc7a5\uc740 \ud22c\uc785\ud55c \uc790\ubcf8\uc744 \ud68c\uc218\ud558\uace0 \uc8fc\ubb38\uc744 \ub9de\ucd94\ub294 \uc7a5\uc18c\ub2e4. \ub178\ub3d9\uc790\uc5d0\uac8c\ub294 \uc2dc\uac04\uc744 \ubcf4\ub0b4\uace0 \uc784\uae08\uc744 \ubc1b\uc544 \uc0dd\ud65c\uc744 \uc774\uc5b4\uac00\ub294 \uc7a5\uc18c\ub2e4. \uac19\uc740 \uc0dd\uc0b0\ub7c9\uacfc \uac19\uc740 \uc124\ube44\ub97c \ubcf4\uace0 \uc788\uc5b4\ub3c4 \ubb34\uc5c7\uc744 \uba3c\uc800 \uac71\uc815\ud558\ub294\uc9c0\ub294 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uacf5\uc7a5\uc758 \uc5ed\uc0ac\ub294 \uc774 \ub450 \uc2dc\uc120\uc774 \uc5b8\uc81c\ub098 \uc77c\uce58\ud558\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uadf8\ub798\uc11c \uc791\uc5c5\uc758 \uc9c8\uc11c\ub97c \ubc14\uafb8\ub294 \uacb0\uc815\uc740 \uae30\uacc4\uc758 \ubc30\uce58\ub9cc \ubc14\uafb8\ub294 \uc77c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \ub178\ub3d9\uc2dc\uac04\uacfc \ud611\uc0c1\ub825, \uc77c\uc790\ub9ac\uc758 \uc548\uc815\ub3c4 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4. \uc5b4\ub5a4 \uc120\ud0dd\uc744 \ubaa8\ub450\uc5d0\uac8c \uc774\ub85c\uc6b4 \uc9c4\ubcf4\ub77c\uace0 \ubd80\ub974\uae30 \uc804\uc5d0 \ub204\uad6c\uc5d0\uac8c \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0 \ub098\ub204\uc5b4 \ubb3b\ub294 \ud3b8\uc774 \uae30\uc5c5\uc758 \uc131\uc7a5\uc744 \ub354 \uc815\ud655\ud788 \ubcf4\uac8c \ud55c\ub2e4. 1892\ub144 \uce74\ub124\uae30 \ucca0\uac15\uc758 \ud648\uc2a4\ud14c\ub4dc \uacf5\uc7a5\uc5d0\uc11c \ub178\uc0ac \ubd84\uc7c1\uc774 \ubc8c\uc5b4\uc84c\ub2e4. \ud5e8\ub9ac \ud504\ub9ad\uc774 \uacbd\uc601\uc744 \ub9e1\uc740 \uc0c1\ud669\uc5d0\uc11c \uacc4\uc57d \ud611\uc0c1\uc774 \uacb0\ub82c\ub418\uc5c8\uace0 \uc9c1\uc7a5 \ud3d0\uc1c4\uc640 \ucda9\ub3cc\ub85c \uc774\uc5b4\uc84c\ub2e4. \ubb34\uc7a5 \uc778\ub825\uacfc \ub178\ub3d9\uc790 \uc0ac\uc774\uc5d0 \uc0ac\ub9dd\uc790\uac00 \ubc1c\uc0dd\ud588\uc73c\uba70, \uc8fc \ubc29\uc704\uad70\uc774 \ub4e4\uc5b4\uc628 \ub4a4 \uc0dd\uc0b0\uc774 \uc7ac\uac1c\ub418\uc5c8\ub2e4. \ub178\ub3d9\uc870\ud569\uc740 \ud328\ubc30\ud588\ub2e4. \uce74\ub124\uae30\uac00 \ub2f9\uc2dc \ud604\uc7a5 \ubc16\uc5d0 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ud68c\uc0ac\uc758 \uacb0\uc815\uacfc \uadf8\uc758 \uad00\uacc4\uac00 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc18\ub300\ub85c \ubcf5\uc7a1\ud55c \ubd84\uc7c1\uc744 \ud55c \uc0ac\ub78c\uc758 \uc131\uaca9 \ud558\ub098\ub85c \ubaa8\ub450 \uc124\uba85\ud560 \uc218\ub3c4 \uc5c6\ub2e4. \uae30\uc5c5\uc758 \uc18c\uc720\uc640 \uacbd\uc601, \ub178\ub3d9\uc790\uc758 \ud611\uc0c1\uc774 \uc5b4\ub5a4 \uad6c\uc870 \uc18d\uc5d0 \ub193\uc600\ub294\uc9c0 \ud568\uaed8 \ubcfc \ub54c \uacf5\uc7a5 \ub2f4\uc7a5 \uc548\uc758 \uc774\uc57c\uae30\uac00 \uc870\uae08 \ub354 \ubd84\uba85\ud574\uc9c4\ub2e4. \uce74\ub124\uae30\uc758 \uc774\ub984\uc740 \ubb38\ud654 \uc2dc\uc124\uacfc \uad50\uc721\uc744 \uc704\ud55c \uae30\ubd80\uc5d0\ub3c4 \ub0a8\uc558\ub2e4. \uc774\ub7f0 \uacf5\uc801 \uc0ac\uc6a9\uc758 \uc758\ubbf8\ub97c \uc778\uc815\ud558\uba74\uc11c\ub3c4 \uadf8\uac83\uc774 \uc0ac\uc5c5 \uacfc\uc815\uc758 \uac08\ub4f1\uc744 \uc5c6\uc5c8\ub358 \uc77c\ub85c \ub9cc\ub4dc\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc744 \uae30\uc5b5\ud560 \uc218 \uc788\ub2e4. \ud55c \uc778\ubb3c\uc758 \uc0dd\uc560\uc5d0\ub294 \uc11c\ub85c \uae34\uc7a5\ud558\ub294 \uc5ec\ub7ec \ubaa8\uc2b5\uc774 \ud568\uaed8 \uc874\uc7ac\ud55c\ub2e4. \uce6d\ucc2c\uc774\ub098 \ube44\ub09c \uc911 \ud55c \uac00\uc9c0\ub9cc \uace8\ub77c\uc57c \ud55c\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uc77d\uae30\uac00 \uc624\ud788\ub824 \ub2e8\uc21c\ud574\uc9c4\ub2e4. \uc5b4\ub5a4 \uc81c\ub3c4\ub97c \ub9cc\ub4e4\uc5c8\uace0 \ubb34\uc5c7\uc744 \ubc14\uafb8\uc5c8\ub294\uc9c0 \uc0b4\ud53c\ub418, \uadf8 \uc131\uacfc\ub97c \uc704\ud574 \ub204\uac00 \uc5b4\ub5a4 \uc870\uac74\uc5d0\uc11c \uc77c\ud588\ub294\uc9c0\ub3c4 \ub0a8\uaca8 \ub450\uba74 \ub41c\ub2e4. \uae30\uc5c5\uac00\ub97c \uc785\uccb4\uc801\uc73c\ub85c \uc774\ud574\ud55c\ub2e4\ub294 \uac83\uc740 \uacb0\ub860\uc744 \ud53c\ud558\ub294 \uc77c\uc774 \uc544\ub2c8\ub77c \ud3c9\uac00\ud560 \uadfc\uac70\ub97c \ub298\ub9ac\ub294 \uc77c\uc774\ub2e4. \ucc98\uc74c\uc758 \uc9c8\ubb38\uc73c\ub85c \ub3cc\uc544\uc624\uc790. \ucca0\uac15 \uacf5\uc7a5 \ubc14\uae65\uc758 \uc2dc\uc124\uc744 \ud568\uaed8 \uac16\ub294 \uac83\uc740 \uc0dd\uc0b0\uc758 \ubd88\ud655\uc2e4\uc131\uc744 \uc904\uc774\ub824\ub294 \uc120\ud0dd\uc774\uc5c8\ub2e4. \uce74\ub124\uae30\uc758 \uc0ac\uc5c5\uc740 \uadf8 \uc5f0\uacb0\uc744 \ud06c\uac8c \ub9cc\ub4e4\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \uae38\uc744 \ub530\ub77c \uc6d0\ub8cc\ub9cc \uc6c0\uc9c1\uc778 \uac83\uc774 \uc544\ub2c8\ub77c \ub9ce\uc740 \uc0ac\ub78c\uc758 \ub178\ub3d9\uacfc \uad8c\ud55c\ub3c4 \ud568\uaed8 \uc870\uc9c1\ub418\uc5c8\ub2e4. \uc0ac\uc9c4\uc774\ub098 \uc0bd\ud654\uc5d0\uc11c \ucee4\ub2e4\ub780 \uacf5\uc7a5\uc744 \ub9cc\ub09c\ub2e4\uba74 \uad74\ub69d\uacfc \uc124\ube44\ub97c \ubcf8 \ub4a4 \ub4e4\uc5b4\uc624\ub294 \uae38\uacfc \ub098\uac00\ub294 \uae38\ub3c4 \uc0b4\ud3b4\ubcf4\uc790. \uadf8\ub9ac\uace0 \uadf8 \uc0ac\uc774\uc5d0\uc11c \uc77c\ud558\ub294 \uc0ac\ub78c\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uacf5\uc7a5 \ud55c \uacf3\uc774 \uc544\ub2c8\ub77c \uc0dd\uc0b0\uc758 \uc0ac\uc2ac\uc744 \ubcf4\ub294 \uc21c\uac04, \uce74\ub124\uae30\uc758 \ucca0\uac15\uc740 \ubd80\uc790\uc758 \uc131\uacf5\ub2f4\ubcf4\ub2e4 \ud6e8\uc52c \ub113\uc740 \uc774\uc57c\uae30\ub85c \ub0a8\ub294\ub2e4."}, {"id": "dell-order-before-computer", "title": "\ub378 \u2014 \uc8fc\ubb38\uc744 \uba3c\uc800 \ub4e3\uace0 \ucef4\ud4e8\ud130\ub97c \ub9cc\ub4e4\uba74", "summary": "\ub378\uc758 \ub9de\ucda4\ud615 \ucef4\ud4e8\ud130 \uc0ac\ub840\ub85c \uace0\uac1d\uc758 \uc120\ud0dd\uacfc \uc2e4\uc81c \uc0dd\uc0b0\uc774 \uc5f0\uacb0\ub418\ub294 \ubc29\uc2dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\uacf5\uc7a5\uacfc \uc0dd\uc0b0", "categories": ["industry"], "url": "stories/dell-order-before-computer/index.html", "image": "../media/dell-order-before-computer.png", "alt": "\uc791\uc5c5\ub300 \uc704 \ucef4\ud4e8\ud130 \ubd80\ud488\uc744 \ubcf4\uba70 \uad6c\uc131\uc5d0 \uad00\ud574 \uc774\uc57c\uae30\ud558\ub294 \ub450 \uc0ac\ub78c\uc758 \uc0bd\ud654.", "text": "\ub378 \u2014 \uc8fc\ubb38\uc744 \uba3c\uc800 \ub4e3\uace0 \ucef4\ud4e8\ud130\ub97c \ub9cc\ub4e4\uba74 \uc120\ud0dd\ub780 \ub4a4\uc5d0\uc11c \uc774\uc5b4\uc9c0\ub294 \ubd80\ud488\uacfc \uacf5\uae09\uc758 \uc774\uc57c\uae30 \ub378\uc758 \ub9de\ucda4\ud615 \ucef4\ud4e8\ud130 \uc0ac\ub840\ub85c \uace0\uac1d\uc758 \uc120\ud0dd\uacfc \uc2e4\uc81c \uc0dd\uc0b0\uc774 \uc5f0\uacb0\ub418\ub294 \ubc29\uc2dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uacf5\uc7a5\uacfc \uc0dd\uc0b0 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \ucef4\ud4e8\ud130\ub97c \uace0\ub97c \ub54c \uba54\ubaa8\ub9ac\ub97c \uc5bc\ub9c8\ub098 \ub123\uc744\uc9c0, \uc800\uc7a5 \uacf5\uac04\uc740 \uc5b4\ub290 \uc815\ub3c4\ub85c \ud560\uc9c0 \uc120\ud0dd\ud558\ub294 \ud654\uba74\uc744 \ub9cc\ub09c\ub2e4. \ud074\ub9ad\uc740 \uac04\ub2e8\ud558\ub2e4. \uadf8\ub7ec\ub098 \uc120\ud0dd\uc774 \ub2ec\ub77c\uc9c0\uba74 \uc548\uc5d0 \ub4e4\uc5b4\uac08 \ubd80\ud488\ub3c4 \ub2ec\ub77c\uc838\uc57c \ud55c\ub2e4. \uc8fc\ubb38\uc758 \ub9d0\uc774 \uc2e4\uc81c \ubb3c\uac74\uc73c\ub85c \ubc14\ub00c\ub294 \uacfc\uc815\uc774 \uc788\ub294 \uac83\uc774\ub2e4. \ub378\uc758 \uc0ac\uc5c5 \uc774\uc57c\uae30\ub294 \uc774\ub7f0 \uc5f0\uacb0\uc5d0\uc11c \ucd9c\ubc1c\ud55c\ub2e4. \ub9c8\uc774\ud074 \ub378\uc758 \ucd08\uae30 \uc0ac\ub840\ub294 \uace0\uac1d\uc5d0\uac8c \ub9de\ucd98 \ucef4\ud4e8\ud130\ub97c \ub9cc\ub4e4\uace0 \uc9c1\uc811 \uc804\ub2ec\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c \uacbd\uc601 \uad50\uc7ac\uc5d0 \uc18c\uac1c\ub41c\ub2e4. \ub354 \uc0c8\ub85c\uc6b4 \ubd80\ud488\uc744 \ubc1c\uba85\ud558\ub294 \uac83\uacfc \uc774\ubbf8 \uc788\ub294 \ubd80\ud488\uc744 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uc870\ud569\ud574 \ud310\ub9e4\ud558\ub294 \uac83\uc740 \ub2e4\ub978 \uc885\ub958\uc758 \ud601\uc2e0\uc774\ub2e4. \uad50\uc7ac\ub294 \ud14d\uc0ac\uc2a4\ub300\ud559\uad50 \ud559\uc0dd\uc774\ub358 \ub9c8\uc774\ud074 \ub378\uc774 \ubd80\ud488\uc744 \uc0ac\uc11c \uc6d0\ud558\ub294 \ucef4\ud4e8\ud130\ub97c \uc9c1\uc811 \uc870\ub9bd\ud588\uace0, \uce5c\uad6c\ub4e4\uc774 \uc790\uc2e0\ub4e4\uc758 \uac83\ub3c4 \ub9cc\ub4e4\uc5b4 \ub2ec\ub77c\uace0 \ud588\ub358 \uc77c\ud654\ub97c \uc18c\uac1c\ud55c\ub2e4. \uc790\uc2e0\uc758 \ud544\uc694\ub97c \ud574\uacb0\ud558\ub358 \ud65c\ub3d9\uc774 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc694\uccad\uacfc \ub9cc\ub09c \uac83\uc774\ub2e4. \uc774 \uc124\uba85\uc744 \ubaa8\ub4e0 \uc131\uacf5\uc744 \uc608\uace0\ud55c \uc644\ubcbd\ud55c \uc0ac\uc5c5 \uacc4\ud68d\uc73c\ub85c \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \ucd9c\ubc1c\uc810\uc5d0\uc11c \uc911\uc694\ud588\ub358 \uac83\uc740 \uc0ac\ub78c\ub9c8\ub2e4 \uc6d0\ud558\ub294 \uad6c\uc131\uc774 \ub2e4\ub97c \uc218 \uc788\ub2e4\ub294 \uad00\ucc30\uc774\uc5c8\ub2e4. \uc644\uc131\ud488\uc744 \uace0\ub974\ub294 \uace0\uac1d\ub9cc \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc6d0\ud558\ub294 \ubd80\ud488\uc758 \uc870\ud569\uc744 \ub9d0\ud558\ub294 \uace0\uac1d\ub3c4 \uc788\uc5c8\ub2e4. \uc5b4\ub5a4 \uc0ac\ub78c\uc740 \uc5ec\ub7ec \ud504\ub85c\uadf8\ub7a8\uc744 \ub3d9\uc2dc\uc5d0 \uc4f0\ub824 \ud558\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc740 \uc790\ub8cc\ub97c \ub9ce\uc774 \ubcf4\uad00\ud558\ub824 \ud55c\ub2e4. \uc774\ub7f0 \uac00\uc0c1 \uc608\ub97c \ub5a0\uc62c\ub9ac\uba74 \uba54\ubaa8\ub9ac\uc640 \uc800\uc7a5 \uc7a5\uce58\uc758 \uc120\ud0dd\uc774 \uc65c \ub2ec\ub77c\uc9c0\ub294\uc9c0 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ubaa8\ub450\uc5d0\uac8c \uac00\uc7a5 \uc88b\uc740 \ud55c \uac00\uc9c0 \uc0ac\uc591\uc744 \uc815\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \ub9de\ucda4\ud615 \ud310\ub9e4\ub294 \uace0\uac1d\uc758 \ucc28\uc774\ub97c \uc81c\ud488 \uad6c\uc131\uc5d0 \ubc18\uc601\ud558\ub824\ub294 \ubc29\uc2dd\uc774\ub2e4. \ud558\uc9c0\ub9cc \uace0\uac1d\uc774 \ub9d0\ud558\ub294 \ubaa8\ub4e0 \uc870\ud569\uc744 \ubb34\ud55c\ud788 \ub9cc\ub4e4\uc5b4 \uc8fc\ub294 \uac83\uacfc\ub294 \ub2e4\ub974\ub2e4. \uc2e4\uc81c\ub85c \uc0dd\uc0b0\ud558\uace0 \uc81c\uacf5\ud560 \uc218 \uc788\ub294 \uc120\ud0dd\uc758 \ubc94\uc704\ub97c \uba3c\uc800 \uc900\ube44\ud574\uc57c \ud55c\ub2e4. \uc120\ud0dd\ub780\uc758 \uc218\uc5d0\ub3c4 \uc6b4\uc601\uc758 \uc870\uac74\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uc81c\uc870 \ucabd\uc774 \uace0\uac1d\uc758 \uc8fc\ubb38\uc744 \uc9c1\uc811 \ubc1b\uc73c\uba74 \uc5b4\ub5a4 \uad6c\uc131\uc744 \uc6d0\ud558\ub294\uc9c0 \ub354 \uac00\uae4c\uc774\uc5d0\uc11c \ud30c\uc545\ud560 \uc218 \uc788\ub2e4. \uc5ec\ub7ec \uc720\ud1b5 \ub2e8\uacc4\ub97c \uac70\uce58\uba70 \uc644\uc131\ud488\uc744 \ubcf4\ub0b4\ub294 \ubc29\uc2dd\uacfc \ub2e4\ub978 \uc815\ubcf4\uc758 \ud750\ub984\uc774 \uc0dd\uae34\ub2e4. \uace0\uac1d\uc758 \uc120\ud0dd\uc774 \uc0dd\uc0b0\ud560 \ubb3c\uac74\uc744 \uc815\ud558\ub294 \ub370 \uad00\uc5ec\ud558\ub294 \uac83\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc911\uac04 \uc720\ud1b5\uc744 \uc904\uc600\uc73c\ub2c8 \ud544\uc694\ud55c \uc77c\ub3c4 \ubaa8\ub450 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc8fc\ubb38\uc744 \uc774\ud574\ud558\uace0 \uc81c\ud488\uc744 \uc548\ub0b4\ud558\uba70 \uc804\ub2ec\ud558\ub294 \uc77c\uc744 \ub204\uad70\uac00\ub294 \ud574\uc57c \ud55c\ub2e4. \uae30\uc874\uc758 \uc77c\uc744 \uc5c6\uc560\ub294 \ubd80\ubd84\uacfc \uae30\uc5c5 \uc548\uc73c\ub85c \uac00\uc838\uc624\ub294 \ubd80\ubd84\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud310\ub9e4 \ubc29\uc2dd\uc758 \ubcc0\ud654\ub97c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 \ub378\uc744 \uace0\uac1d \uc0ac\uc591\uc5d0 \ub9de\ucd94\uc5b4 \ucef4\ud4e8\ud130\ub97c \ub9cc\ub4dc\ub294 \uc0ac\ub840\ub85c \uc124\uba85\ud55c\ub2e4. \uc774\ub97c \uac00\ub2a5\ud558\uac8c \ud558\ub824\uba74 \uba54\ubaa8\ub9ac\uc640 \uc800\uc7a5 \uc7a5\uce58 \ub4f1 \ud544\uc694\ud55c \ubd80\ud488\uc744 \ub9c8\ub828\ud558\uace0 \uc870\ub9bd\uc758 \ud750\ub984\uc744 \ub9de\ucd94\uc5b4\uc57c \ud55c\ub2e4. \uc8fc\ubb38 \ud654\uba74\uacfc \uc0dd\uc0b0 \ud604\uc7a5\uc758 \uc815\ubcf4\uac00 \ub5a8\uc5b4\uc838 \uc788\uc73c\uba74 \uc120\ud0dd\uc740 \uc57d\uc18d\uc5d0\ub9cc \uba38\ubb34\ub97c \uc218 \uc788\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \ud2b9\uc815 \ubd80\ud488\uc744 \ub9ce\uc774 \uc6d0\ud558\ub294 \uc2dc\uae30\uc5d0\ub294 \uacf5\uae09\uacfc \uc791\uc5c5\uc758 \uade0\ud615\ub3c4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc774\uac83\uc740 \uc2e4\uc81c \uc5b4\ub290 \ub0a0\uc758 \ub378 \uacf5\uc7a5 \uc0c1\ud669\uc744 \uc7ac\ud604\ud55c \uac83\uc774 \uc544\ub2c8\ub77c \uc6d0\ub9ac\ub97c \uc0dd\uac01\ud558\ub294 \uc608\ub2e4. \uace0\uac1d\uc758 \uc120\ud0dd\uad8c\uc740 \uadf8 \ub4a4\uc5d0\uc11c \uc5ec\ub7ec \uc900\ube44\uac00 \ud568\uaed8 \uc6c0\uc9c1\uc77c \ub54c \uc2e4\uc81c \uacbd\ud5d8\uc774 \ub41c\ub2e4. \uc81c\ud488\uc758 \uc774\ub984\uc740 \ub378\uc774\uc9c0\ub9cc \uc81c\uc870\uc640 \ubd80\ud488\uc758 \uc5f0\uacb0\uc5d0\ub294 \ub2e4\ub978 \uae30\uc5c5\ub4e4\ub3c4 \ucc38\uc5ec\ud55c\ub2e4. \uad50\uc7ac\ub294 \uacc4\uc57d \uc81c\uc870\uc5c5\uccb4\uc640\uc758 \ud611\ub825\uc744 \uc124\uba85\ud55c\ub2e4. \ud558\ub098\uc758 \uc0c1\ud45c\uac00 \ubd99\uc740 \ubb3c\uac74\uc774 \ud55c \ud68c\uc0ac \uc548\uc758 \ubaa8\ub4e0 \uacfc\uc815\ub9cc\uc73c\ub85c \uc644\uc131\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc81c\ud488\uc744 \ub9cc\ub4dc\ub294 \uc77c\uc744 \uc870\ub9bd\ub300 \uc704\uc758 \uc791\uc5c5\uc73c\ub85c\ub9cc \ubcfc \uc218 \uc5c6\ub2e4. \uc5b4\ub5a4 \uae30\uc900\uc744 \uacf5\uae09\uc790\uc640 \uacf5\uc720\ud558\uace0 \ubd80\ud488\uc774 \uc5b8\uc81c \ub4e4\uc5b4\uc624\uba70 \ub9c8\uc9c0\ub9c9 \ud655\uc778\uacfc \ubc30\uc1a1\uc744 \uc5b4\ub5bb\uac8c \uc774\uc5b4 \uac08\uc9c0\ub3c4 \uc911\uc694\ud558\ub2e4. \ub9de\ucda4\ud615 \ud310\ub9e4\ub294 \uac1c\uc778\uc758 \uc120\ud0dd\uc744 \uac15\uc870\ud558\uc9c0\ub9cc \uc2e4\ud589\uc740 \uc624\ud788\ub824 \ub9ce\uc740 \uc870\uc9c1\uc758 \ud611\ub825\uc744 \ud544\uc694\ub85c \ud55c\ub2e4. \ub0b4\uac8c \ub9de\ub294 \ucef4\ud4e8\ud130\ub97c \uace0\ub97c \uc218 \uc788\ub2e4\ub294 \uc124\uba85\uc740 \ub9e4\ub825\uc801\uc774\ub2e4. \ud558\uc9c0\ub9cc \ubb34\uc5c7\uc744 \uace0\ub974\uba74 \uc88b\uc740\uc9c0 \ubaa8\ub974\ub294 \uace0\uac1d\uc5d0\uac8c\ub294 \uc120\ud0dd\uc774 \ub9ce\uc544\uc9c0\ub294 \uac83 \uc790\uccb4\uac00 \ubd80\ub2f4\uc77c \uc218 \uc788\ub2e4. \uc81c\ud488\uc758 \ucc28\uc774\ub97c \uc54c\uc544\ubcf4\uae30 \uc27d\uac8c \uc548\ub0b4\ud558\ub294 \uc77c\ub3c4 \uc0ac\uc5c5\uc758 \uc77c\ubd80\uac00 \ub41c\ub2e4. \uc774\uac83\uc740 \ub378\uc758 \ud604\uc7ac \uc8fc\ubb38 \ud654\uba74\uc744 \ud3c9\uac00\ud55c \ub0b4\uc6a9\uc740 \uc544\ub2c8\ub2e4. \ub9de\ucda4\ud615 \uc81c\ud488\uc744 \uc77d\uc744 \ub54c \ub367\ubd99\uc77c \uc218 \uc788\ub294 \uc9c8\ubb38\uc774\ub2e4. \uace0\uac1d\uc774 \ucc28\uc774\ub97c \uc774\ud574\ud558\uace0 \uc120\ud0dd\uc758 \uacb0\uacfc\ub97c \uc608\uc0c1\ud560 \uc218 \uc788\uc5b4\uc57c \uc120\ud0dd\uad8c\uc774 \ud3b8\ub9ac\ud568\uc774 \ub41c\ub2e4. \ub9ce\uc740 \ud56d\ubaa9\uacfc \uc88b\uc740 \uc548\ub0b4\ub294 \uac19\uc740 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uad50\uc7ac\uac00 \uc18c\uac1c\ud55c \uc0ac\ub840\ub97c \ub378\uc758 \ubaa8\ub4e0 \uc2dc\ub300\uc640 \ubaa8\ub4e0 \ud310\ub9e4 \uacbd\ub85c\uc5d0 \uc801\uc6a9\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc774\ubc88 \uae00\uc740 \ub9de\ucda4\ud615 \uc870\ub9bd\uacfc \uc9c1\uc811 \ud310\ub9e4\ub77c\ub294 \uad6c\uc0c1\uc774 \uac16\ub294 \uc758\ubbf8\uc5d0 \ucd08\uc810\uc744 \ub9de\ucd98\ub2e4. \ud604\uc7ac \ubaa8\ub378\uc758 \uc0ac\uc591\uacfc \ub0a9\uae30, \uc81c\uc870 \uad6d\uac00\ub97c \uc548\ub0b4\ud558\ub294 \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ub610 \uc774\ub7f0 \ubc29\uc2dd\uc774 \ubaa8\ub4e0 \uc81c\ud488\uc5d0 \ucd5c\uc120\uc774\ub77c\ub294 \uacb0\ub860\ub3c4 \ud544\uc694\ud558\uc9c0 \uc54a\ub2e4. \uace0\uac1d\uc774 \uad6c\uc131\uc744 \ubc14\uafc0 \uc774\uc720\uac00 \uc801\uac70\ub098 \ube60\ub978 \uc644\uc131\ud488 \uad6c\ub9e4\ub97c \uc6d0\ud55c\ub2e4\uba74 \ub2e4\ub978 \ubc29\uc2dd\uc774 \ub9de\uc744 \uc218 \uc788\ub2e4. \ud601\uc2e0\uc740 \uc5b8\uc81c\ub098 \uac19\uc740 \uacf5\uc2dd\uc774 \uc544\ub2c8\ub77c \uc81c\ud488\uacfc \uace0\uac1d\uc758 \uc870\uac74\uc5d0 \ub9de\ucd94\uc5b4 \ud310\ub2e8\ud560 \ubb38\uc81c\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \ubd80\ud488\uc744 \ubcf4\uba70 \uad6c\uc131\uc744 \uc758\ub17c\ud558\ub294 \uc791\uc5c5\ub300\uc758 \ubd84\uc704\uae30\ub2e4. \ub9c8\uc774\ud074 \ub378\uc758 \uc2e4\uc81c \uae30\uc219\uc0ac\uc640 \uc778\ubb3c, \ud2b9\uc815 \uc81c\ud488\uc774\ub098 \uacf5\uc7a5\uc744 \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc120\ud0dd\uacfc \uc870\ub9bd\uc774 \ub9cc\ub098\ub294 \uc7a5\uba74\uc744 \ub5a0\uc62c\ub9ac\ub294 \uadf8\ub9bc\uc774\ub2e4. \ub378\uc758 \uc0ac\ub840\ub294 \uae30\uc220 \uae30\uc5c5\uc758 \ubcc0\ud654\uac00 \uc0c8\ub85c\uc6b4 \uce69\uc744 \ub9cc\ub4dc\ub294 \ub370\uc11c\ub9cc \uc2dc\uc791\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uace0\uac1d\uc774 \uc6d0\ud558\ub294 \uac83\uc744 \ub4e3\uace0 \ubd80\ud488\uacfc \uc0dd\uc0b0\uc744 \uc5f0\uacb0\ud558\ub294 \ubc29\uc2dd\ub3c4 \ubc14\uafc0 \uc218 \uc788\uc5c8\ub2e4. \uc791\uc740 \uc120\ud0dd\ub780\uc744 \ub204\ub974\ub294 \uc21c\uac04 \ub4a4\uc5d0\uc11c \uc5b4\ub5a4 \uc900\ube44\uac00 \uc6c0\uc9c1\uc774\ub294\uc9c0 \uc0dd\uac01\ud558\uba74 \uc775\uc219\ud55c \ucef4\ud4e8\ud130 \uad6c\ub9e4\ub3c4 \ub2e4\ub978 \uc774\uc57c\uae30\ub85c \ubcf4\uc778\ub2e4."}, {"id": "department-stores-window-shopping", "title": "\ubc31\ud654\uc810 \u2014 \uc0ac\uc9c0 \uc54a\uc544\ub3c4 \uad6c\uacbd\ud558\ub7ec \ub4e4\uc5b4\uac00\ub294 \uac00\uac8c", "summary": "19\uc138\uae30 \ubc31\ud654\uc810\uc758 \uc9c4\uc5f4\uacfc \ud734\uac8c \uacf5\uac04, \uc5ec\uc131\uc758 \uc18c\ube44\uc640 \uc77c\uc790\ub9ac\uc5d0\uc11c \ub3c4\uc2dc \uc18c\ube44\ubb38\ud654\uc758 \ubcc0\ud654\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\uc0c1\uc5c5\uacfc \uc720\ud1b5", "categories": ["industry"], "url": "stories/department-stores-window-shopping/index.html", "image": "../media/department-stores-window-shopping.jpg", "alt": "\uc67c\ucabd\uc740 \ud30c\ub9ac \ubd09\ub9c8\ub974\uc170\uc758 \ub0b4\ubd80 \ub3c4\ud310, \uc624\ub978\ucabd\uc740 \ud544\ub77c\ub378\ud53c\uc544 \uc6cc\ub108\uba54\uc774\ucee4 \uc0c1\uc810\uc758 \uc678\uad00 \ub3c4\ud310", "text": "\ubc31\ud654\uc810 \u2014 \uc0ac\uc9c0 \uc54a\uc544\ub3c4 \uad6c\uacbd\ud558\ub7ec \ub4e4\uc5b4\uac00\ub294 \uac00\uac8c \ubd09\ub9c8\ub974\uc170\uc640 \ub3c4\uc2dc\uc758 \uc1fc\ud551\uc774 \ubc14\uafbc \ud558\ub8e8 19\uc138\uae30 \ubc31\ud654\uc810\uc758 \uc9c4\uc5f4\uacfc \ud734\uac8c \uacf5\uac04, \uc5ec\uc131\uc758 \uc18c\ube44\uc640 \uc77c\uc790\ub9ac\uc5d0\uc11c \ub3c4\uc2dc \uc18c\ube44\ubb38\ud654\uc758 \ubcc0\ud654\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uc0c1\uc5c5\uacfc \uc720\ud1b5 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \ubb3c\uac74\uc744 \uc0ac\ub7ec \uac04 \uac83\ub3c4 \uc544\ub2cc\ub370 \uc1fc\uc708\ub3c4 \uc55e\uc5d0\uc11c \ubc1c\uac78\uc74c\uc774 \uba48\ucd98\ub2e4. \uc548\uc73c\ub85c \ub4e4\uc5b4\uac00 \uba87 \uce35\uc744 \ub458\ub7ec\ubcf4\uace0 \uc544\ubb34\uac83\ub3c4 \uc0ac\uc9c0 \uc54a\uc740 \ucc44 \ub098\uc624\uae30\ub3c4 \ud55c\ub2e4. \uc624\ub298\ub0a0\uc5d0\ub294 \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \uc774 \uad6c\uacbd\uc774 \ud55c\ub54c\ub294 \uc0c8\ub85c\uc6b4 \ub3c4\uc2dc\uc758 \uc990\uac70\uc6c0\uc774\uc5c8\ub2e4. 19\uc138\uae30 \uc0b0\uc5c5\ub3c4\uc2dc\uc5d0 \ucee4\ub2e4\ub780 \ubc31\ud654\uc810\ub4e4\uc774 \ub4f1\uc7a5\ud588\ub2e4. \ud30c\ub9ac\uc758 \ubd09\ub9c8\ub974\uc170, \ub7f0\ub358\uc758 \uc140\ud504\ub9ac\uc9c0\uc2a4, \ub274\uc695\uc758 \uba54\uc774\uc2dc\uc2a4 \uac19\uc740 \uac00\uac8c\ub294 \ubb3c\uac74\uc744 \ubaa8\uc544 \ud314\uba74\uc11c \uc0ac\ub78c\ub4e4\uc774 \uc2dc\uac04\uc744 \ubcf4\ub0b4\ub294 \ubc29\uc2dd\ub3c4 \ubc14\uafb8\uc5c8\ub2e4. \uc637\uacfc \uc0dd\ud65c\uc6a9\ud488\uc744 \uc5ec\ub7ec \uacf3\uc5d0\uc11c \ucc3e\uc544\ub2e4\ub2c8\ub294 \ub300\uc2e0 \ud070 \uac00\uac8c\uc5d0\uc11c \ud568\uaed8 \ubcfc \uc218 \uc788\uac8c \ub418\uc5c8\ub2e4. \ub300\ub7c9\uc73c\ub85c \uc0dd\uc0b0\ub418\ub294 \uc0c1\ud488\uacfc \ucee4\uc9c4 \ub3c4\uc2dc\uc758 \uc18c\ube44\uac00 \ub9cc\ub09c \uacb0\uacfc\uc600\ub2e4. \uc1fc\ud551\uc758 \ub300\uc0c1\uc740 \ub298\uc5b4\ub0ac\uace0 \uad6c\uacbd\uc758 \uacbd\ub85c\ub3c4 \uae38\uc5b4\uc84c\ub2e4. \uc774 \ubcc0\ud654\ub294 \ucee4\ub2e4\ub780 \uac74\ubb3c \ud558\ub098\ub9cc\uc73c\ub85c \uc0dd\uae30\uc9c0 \uc54a\uc558\ub2e4. \uc0c1\ud488\uc744 \ucda9\ubd84\ud788 \uacf5\uae09\ud560 \uc0dd\uc0b0\uacfc \uc6b4\uc1a1, \uac00\uac8c\uae4c\uc9c0 \ub370\ub824\ub2e4\uc904 \uad50\ud1b5\uc774 \ud544\uc694\ud588\ub2e4. \ubc31\ud654\uc810\uc758 \uc9c4\uc5f4\ub300 \ub4a4\uc5d0\ub294 \ub3c4\uc2dc \uc804\uccb4\uc758 \uc6c0\uc9c1\uc784\uc774 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \ubcf4\uae30 \uc88b\uac8c \ub193\uc778 \uc0c1\ud488\uc740 \uc9c0\ub098\uac00\ub294 \uc0ac\ub78c\uc5d0\uac8c \uba3c\uc800 \ub9d0\uc744 \uac78\uc5c8\ub2e4. \uc637\uac10\uc774\ub098 \uc18c\ud488\uc744 \ub2f9\uc7a5 \uc0b4 \ud544\uc694\uac00 \uc5c6\uc5b4\ub3c4 \uc0c9\uacfc \ubaa8\uc591\uc744 \ubcf4\uace0 \uc2f6\uc5b4\uc84c\ub2e4. \uc0c1\uc810\uc758 \ucc3d\uc740 \uc548\uacfc \ubc16\uc744 \uac00\ub974\ub294 \uc720\ub9ac\uc774\uba74\uc11c \uc0c8\ub85c\uc6b4 \ucde8\ud5a5\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ubb34\ub300\uc600\ub2e4. \ubc31\ud654\uc810\uc740 \ubc29\ubb38\uac1d\uc5d0\uac8c \ubb34\uc5c7\uc774 \uc720\ud589\ud558\ub294\uc9c0\ub3c4 \uc54c\ub824 \uc8fc\uc5c8\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \ubb3c\uac74\uc744 \uc0ac\ub294 \uac83\ub9cc \uc544\ub2c8\ub77c \uc9c0\uae08 \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc774 \ubb34\uc5c7\uc744 \uc6d0\ud558\ub294\uc9c0 \ubc30\uc6e0\ub2e4. \uad6c\ub9e4\ud558\uc9c0 \uc54a\uc740 \ub0a0\uc5d0\ub3c4 \ub9c8\uc74c\uc18d\uc758 \ubaa9\ub85d\uc740 \uc870\uae08\uc529 \ubc14\ub014 \uc218 \uc788\uc5c8\ub2e4. \uac70\ub9ac\uc640 \uac00\uac8c\ub97c \ub458\ub7ec\ubcf4\ub294 \uc2dc\uac04\uc740 \ub3c4\uc2dc\uc758 \uc5ec\uac00\uc5d0 \ub4e4\uc5b4\uc654\ub2e4. \uadf9\uc7a5\uc774\ub098 \uacf5\uc6d0\ucc98\ub7fc \ubc31\ud654\uc810\ub3c4 \uc678\ucd9c\uc758 \ubaa9\uc801\uc9c0\uac00 \ub418\uc5c8\ub2e4. \ube44\uad50\uc801 \uc801\uc740 \ube44\uc6a9\uc73c\ub85c \uc0c8\ub85c\uc6b4 \ubb3c\uac74\uacfc \ud654\ub824\ud55c \uacf5\uac04\uc744 \uc811\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\ub3c4 \ub9e4\ub825\uc774\uc5c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub204\uad6c\ub098 \ub611\uac19\uc774 \ubb3c\uac74\uc744 \uc0b4 \uc218 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uad6c\uacbd\ud560 \uc218 \uc788\ub294 \uc790\uc720\uc640 \uad6c\ub9e4\ud560 \uc218 \uc788\ub294 \ud615\ud3b8 \uc0ac\uc774\uc5d0\ub294 \ucc28\uc774\uac00 \uc788\uc5c8\ub2e4. \ucc3d\ubb38\uc740 \uc0ac\ub78c\ub4e4\uc744 \ub04c\uc5b4\ub4e4\uc774\ub294 \ub3d9\uc2dc\uc5d0 \uac01\uc790\uc758 \uc8fc\uba38\ub2c8 \uc0ac\uc815\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud588\ub2e4. \uac00\uac8c\ub294 \uace0\uac1d\uc774 \uc624\ub798 \uba38\ubb3c \uc218 \uc788\ub3c4\ub85d \ud734\uc2dd \uacf5\uac04\uacfc \ucc28\ub97c \ub9c8\uc2e4 \uacf3\uc744 \ub9c8\ub828\ud588\ub2e4. \ubb3c\uac74\uc744 \uace0\ub974\ub294 \ub3d9\uc548 \uc26c\uc5b4 \uac08 \uc218 \uc788\ub2e4\uba74 \uc1fc\ud551\uc740 \uae09\ud788 \uc6a9\uac74\uc744 \ub9c8\uce58\ub294 \uc77c\uc774 \uc544\ub2c8\ub77c \ubc18\ub098\uc808\uc758 \ud65c\ub3d9\uc774 \ub420 \uc218 \uc788\uc5c8\ub2e4. \uc774\ub7f0 \uacf5\uac04\uc740 \uc911\uc0b0\uce35 \uc5ec\uc131\uc758 \ub3c4\uc2dc \uc0dd\ud65c\uacfc \ud2b9\ud788 \ubc00\uc811\ud588\ub2e4. \uac00\uc815\uc758 \uc18c\ube44\ub97c \ub9e1\uc740 \uc5ec\uc131\ub4e4\uc774 \uc678\ucd9c\ud574 \ubb3c\uac74\uc744 \ube44\uad50\ud558\uace0 \uc7a0\uc2dc \uc26c\ub294 \uc7a5\uc18c\uac00 \ub418\uc5c8\ub2e4. \ub2e4\ub9cc \ub2f9\uc2dc \uc5ec\uc131 \ubaa8\ub450\uc758 \uc0dd\ud65c\uc744 \ud55c \uac00\uc9c0 \uc1fc\ud551 \uacbd\ud5d8\uc73c\ub85c \ubb36\uc744 \uc218\ub294 \uc5c6\ub2e4. \uac19\uc740 \ubc31\ud654\uc810\uc5d0\uc11c\ub3c4 \ub204\uad70\uac00\ub294 \uc190\ub2d8\uc73c\ub85c, \ub204\uad70\uac00\ub294 \uc9c1\uc6d0\uc73c\ub85c \ud558\ub8e8\ub97c \ubcf4\ub0c8\ub2e4. \ub3c4\uc2dc\uc758 \uc80a\uc740 \uc5ec\uc131\ub4e4\uc5d0\uac8c \ud310\ub9e4\uc640 \uc811\uac1d\uc740 \uc77c\uc790\ub9ac\uc758 \ud55c \uae38\uc774 \ub418\uc5c8\ub2e4. \uc18c\ube44\ubb38\ud654\uac00 \ucee4\uc9c0\uba74\uc11c \uadf8\uac83\uc744 \uc720\uc9c0\ud558\ub294 \ub178\ub3d9\ub3c4 \ub298\uc5c8\ub2e4. \uae68\ub057\ud558\uace0 \ubc1d\uc740 \ub9e4\uc7a5\uc774 \uace7 \ub178\ub3d9\uc758 \ubaa8\ub4e0 \uc5b4\ub824\uc6c0\uc744 \uc5c6\uc574\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc190\ub2d8\uc5d0\uac8c \ud3b8\uc548\ud55c \uacf5\uac04\uc744 \ub9cc\ub4e4\ub824\uba74 \ub2e4\ub978 \ub204\uad70\uac00\ub294 \uc11c\uc11c \uc77c\ud558\uace0 \uc0c1\ud488\uc744 \uc815\ub9ac\ud574\uc57c \ud588\ub2e4. \uad6c\uacbd\uc758 \uc990\uac70\uc6c0\uc740 \uadf8 \uc218\uace0\uc640 \ud568\uaed8 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \ub450 \uc0c1\uc810\uc744 \ub098\ub780\ud788 \ubcf4\uc5ec \uc900\ub2e4. \ud55c\ucabd\uc740 \ud30c\ub9ac\uc758 \ubd09\ub9c8\ub974\uc170, \ub2e4\ub978 \ucabd\uc740 \ud544\ub77c\ub378\ud53c\uc544\uc758 \uc6cc\ub108\uba54\uc774\ucee4\ub2e4. \uac19\uc740 \uac74\ubb3c\uc758 \uc11c\ub85c \ub2e4\ub978 \uce35\uc774\ub098 \uc2dc\uae30\ub97c \uadf8\ub9b0 \uc790\ub8cc\uac00 \uc544\ub2c8\ub2e4. \ub3c4\ud310\uc740 \uc0c1\uc810\uc774 \uc5bc\ub9c8\ub098 \ub113\uace0 \ubcfc\uac70\ub9ac\uac00 \ub9ce\uc740 \uacf3\uc73c\ub85c \uc81c\uc2dc\ub418\uc5c8\ub294\uc9c0 \uc0b4\ud53c\uac8c \ud55c\ub2e4. \uc774\ub7f0 \uc774\ubbf8\uc9c0\ub294 \uac74\ubb3c\uc758 \uc2e4\uc81c \ubaa8\uc2b5\ubfd0 \uc544\ub2c8\ub77c \uadf8\uacf3\uc774 \uc5b4\ub5a4 \uc7a5\uc18c\ub85c \uae30\uc5b5\ub418\uae30\ub97c \ubc14\ub790\ub294\uc9c0\ub3c4 \ubcf4\uc5ec \uc900\ub2e4. \uc190\ub2d8\uc758 \uacbd\ud5d8 \uc804\uccb4\ub97c \ub2f4\uc740 \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \ubc31\ud654\uc810\uc758 \uacbd\uc7c1\uc740 \uc0c1\ud488 \ud558\ub098\uc758 \ud488\uc9c8\uacfc \uac12\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6cc\uc84c\ub2e4. \ucc3e\uc544\uc624\uae30 \uc26c\uc6b4\uac00, \ub458\ub7ec\ubcf4\ub294 \ub3d9\uc548 \uc990\uac70\uc6b4\uac00, \uc26c\uc5b4 \uac08 \uacf3\uc774 \uc788\ub294\uac00\ub3c4 \ubc29\ubb38\uc758 \uc774\uc720\uac00 \ub418\uc5c8\ub2e4. \uac00\uac8c \uc804\uccb4\uac00 \uacbd\ud5d8\uc744 \uc81c\uacf5\ud558\uae30 \uc2dc\uc791\ud588\ub2e4. \uadf8\ub807\uc9c0\ub9cc \uc774 \ubcc0\ud654\ub97c \ud2b9\uc815 \uc0c1\uc810 \ud55c \uacf3\uc758 \ubc1c\uba85\uc73c\ub85c\ub9cc \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uc5ec\ub7ec \ub3c4\uc2dc\uc758 \uc0ac\uc5c5\uc790\uc640 \uc18c\ube44\uc790, \uc9c1\uc6d0\uc774 \uac01\uae30 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uc0c8\ub85c\uc6b4 \uad00\ud589\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \ub3c4\uc2dc\ub294 \uc11c\ub85c\ub97c \ucc38\uace0\ud558\uba70 \uc1fc\ud551\uc758 \ud48d\uacbd\uc744 \ubc14\uafb8\uc5c8\ub2e4. \ub9e4\uc7a5\uc744 \uadf8\ub9b0 \uc624\ub798\ub41c \uadf8\ub9bc\uc5d0\ub294 \uacf5\uac04\uc744 \ub3cb\ubcf4\uc774\uac8c \ud558\ub294 \uc120\ud0dd\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ub113\uc774\uc640 \uc7a5\uc2dd, \ubaa8\uc5ec\ub4e0 \uc190\ub2d8\uc740 \uc798 \ubcf4\uc774\uc9c0\ub9cc \ubb3c\uac74\uc744 \uc62e\uae30\uace0 \uc815\ub9ac\ud55c \uc2dc\uac04\uc740 \uc798 \ub4dc\ub7ec\ub098\uc9c0 \uc54a\ub294\ub2e4. \ud654\ub824\ud55c \uc0c1\uc810\uc758 \uc778\uc0c1\uacfc \uadf8\uacf3\uc758 \ud558\ub8e8 \uc804\uccb4\ub97c \uad6c\ubcc4\ud558\uba70 \ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \uadf8\ub9bc \uc18d \ubaa8\ub4e0 \ubc29\ubb38\uac1d\uc758 \uc18c\ub4dd\uacfc \uad6c\ub9e4 \ub0b4\uc5ed\ub3c4 \uc54c \uc218 \uc5c6\ub2e4. \ub9ce\uc740 \uc0ac\ub78c\uc774 \ubaa8\uc600\ub2e4\ub294 \ubaa8\uc2b5\ub9cc\uc73c\ub85c \ub204\uad6c\ub098 \ud48d\uc694\ub85c\uc6e0\ub2e4\uace0 \ud310\ub2e8\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \uac19\uc740 \uc0c1\ud488\uc744 \uc55e\uc5d0 \ub450\uace0\ub3c4 \ub204\uad70\uac00\ub294 \uc120\ubb3c\uc744, \ub204\uad70\uac00\ub294 \ud544\uc694\ud55c \uc0dd\ud65c\ube44\ub97c \uc0dd\uac01\ud588\uc744 \uc218 \uc788\ub2e4. \uc774\ub7f0 \uc810\uc744 \uc0b4\ud53c\uba74 \uc61b \uc0c1\uc810 \uadf8\ub9bc\uc774 \ub354 \uc7ac\ubbf8\uc788\uc5b4\uc9c4\ub2e4. \uac74\ucd95\uc758 \uc7a5\uc2dd\ub9cc \uc138\ub294 \ub300\uc2e0 \ub204\uac00 \uc5b4\ub514\uc5d0 \uc11c \uc788\uace0 \uc5b4\ub5a4 \ud65c\ub3d9\uc774 \uc911\uc2ec\uc5d0 \ub193\uc600\ub294\uc9c0 \ubcf4\uac8c \ub41c\ub2e4. \uc18c\ube44\uc758 \uc5ed\uc0ac\ub294 \uba4b\uc9c4 \uc9c4\uc5f4\uc744 \ubc14\ub77c\ubcf4\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc11c\ub85c \ub2e4\ub978 \uc0dd\ud65c\uacfc \uc774\uc5b4\uc9c4\ub2e4. \ubc31\ud654\uc810\uc5d0\uc11c \uc544\ubb34\uac83\ub3c4 \uc0ac\uc9c0 \uc54a\uc558\ub2e4\uace0 \uc544\ubb34 \uc77c\ub3c4 \uc5c6\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubcf8 \ubb3c\uac74\uacfc \uc0c8\ub85c \uc54c\uac8c \ub41c \ucde8\ud5a5, \uac16\uace0 \uc2f6\uc740 \uc0dd\ud65c\uc758 \ubaa8\uc2b5\uc774 \ub0a8\ub294\ub2e4. \uc1fc\ud551\uc758 \uc5ed\uc0ac\ub294 \uad6c\ub9e4 \uc601\uc218\uc99d\ub9cc\uc73c\ub85c \ub2e4 \ub2f4\uae30\uc9c0 \uc54a\ub294\ub2e4. \uc1fc\uc708\ub3c4 \uc55e\uc5d0\uc11c \uc7a0\uae50 \uba48\ucd94\ub294 \uc624\ub298\uc758 \ubc1c\uac78\uc74c\uc5d0\ub3c4 \uadf8 \uc5ed\uc0ac\uac00 \uc774\uc5b4\uc9c4\ub2e4. \uac00\uac8c\ub294 \ubb3c\uac74\uc744 \ud30c\ub294 \uacf3\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc774 \uc6d0\ud558\ub294 \uc0b6\uc744 \ub458\ub7ec\ubcf4\ub294 \uacf3\uc73c\ub85c \ub113\uc5b4\uc84c\ub2e4. \uadf8 \ubcc0\ud654\uc758 \ud55c\uac00\uc6b4\ub370\uc5d0, \uc0ac\uc9c0 \uc54a\uc544\ub3c4 \ub4e4\uc5b4\uac00\ub294 \ubc29\ubb38\uac1d\uc774 \uc788\uc5c8\ub2e4."}, {"id": "east-india-company-trade-and-taxes", "title": "\ub3d9\uc778\ub3c4\ud68c\uc0ac \u2014 \uc7a5\uc0ac\ud558\ub7ec \uac04 \ud68c\uc0ac\ub294 \uc65c \uc138\uae08\uc744 \uac77\uc5c8\uc744\uae4c", "summary": "\uc601\uad6d \ub3d9\uc778\ub3c4\ud68c\uc0ac\uac00 \ubb34\uc5ed\uacfc \uad70\uc0ac\ub825, \ud604\uc9c0 \uad8c\ub825\uacfc\uc758 \ud611\uc0c1\uc744 \ud1b5\ud574 \ud1b5\uce58\uc758 \uc8fc\uccb4\uac00 \ub41c \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\uc0c1\uc5c5\uacfc \uc720\ud1b5", "categories": ["industry"], "url": "stories/east-india-company-trade-and-taxes/index.html", "image": "../media/east-india-company-trade-and-taxes.jpg", "alt": "\uc57d 1810\ub144 \ub9c8\ub4dc\ub77c\uc2a4 \ubcf4\ubcd1\ub300 \uc138\ud3ec\uc774 \ubcd1\uc0ac\uc640 \uc544\ub0b4\ub97c \uadf8\ub9b0 \uc218\ucc44\ud654", "text": "\ub3d9\uc778\ub3c4\ud68c\uc0ac \u2014 \uc7a5\uc0ac\ud558\ub7ec \uac04 \ud68c\uc0ac\ub294 \uc65c \uc138\uae08\uc744 \uac77\uc5c8\uc744\uae4c 1600\ub144\uc758 \ubb34\uc5ed \ud5c8\uac00\uc5d0\uc11c \ubcb5\uace8\uc758 \uc9d5\uc138\uad8c\uacfc \uc2dd\ubbfc \ud1b5\uce58\uae4c\uc9c0 \uc601\uad6d \ub3d9\uc778\ub3c4\ud68c\uc0ac\uac00 \ubb34\uc5ed\uacfc \uad70\uc0ac\ub825, \ud604\uc9c0 \uad8c\ub825\uacfc\uc758 \ud611\uc0c1\uc744 \ud1b5\ud574 \ud1b5\uce58\uc758 \uc8fc\uccb4\uac00 \ub41c \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc0c1\uc5c5\uacfc \uc720\ud1b5 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \ud68c\uc0ac\ub77c\uba74 \ubb3c\uac74\uc744 \ud314\uace0 \uc774\uc775\uc744 \ub0a8\uae30\ub294 \uacf3\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7f0\ub370 \uad70\ub300\ub97c \uac70\ub290\ub9ac\uace0 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uc138\uae08\uc744 \uac77\ub294 \ud68c\uc0ac\uac00 \uc788\uc5c8\ub2e4. \uc601\uad6d \ub3d9\uc778\ub3c4\ud68c\uc0ac\ub294 \uc778\ub3c4\uc591 \ubb34\uc5ed\uc744 \uc704\ud574 \ucd9c\ubc1c\ud588\uc9c0\ub9cc \ud6d7\ub0a0 \ub113\uc740 \uc9c0\uc5ed\uc744 \uc9c0\ubc30\ud558\ub294 \uad8c\ub825\uc73c\ub85c \ubc14\ub00c\uc5c8\ub2e4. \uadf8 \ubcc0\ud654\ub97c \uc0ac\uc5c5\uc774 \uc798\ub418\uc5b4 \uaddc\ubaa8\uac00 \ucee4\uc84c\ub2e4\ub294 \ub9d0\ub85c\ub9cc \uc124\uba85\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \ubb3c\uac74\uac12\uc744 \ud611\uc0c1\ud558\ub294 \ud798\uacfc \uc0ac\ub78c\uc758 \uc0dd\ud65c\uc744 \uacb0\uc815\ud558\ub294 \ud798 \uc0ac\uc774\uc5d0\uc11c \ubb34\uc2a8 \uc77c\uc774 \uc77c\uc5b4\ub0ac\ub294\uc9c0 \uc0b4\ud3b4\ubcfc \ud544\uc694\uac00 \uc788\ub2e4. 1600\ub144 \uc789\uae00\ub79c\ub4dc\uc5d0\uc11c \ud5c8\uac00\ub97c \ubc1b\uc740 \ub3d9\uc778\ub3c4\ud68c\uc0ac\ub294 \uba3c \ubc14\ub2e4\uc758 \ubb34\uc5ed\uc744 \ubaa9\uc801\uc73c\ub85c \ud588\ub2e4. \uc5ec\ub7ec \ud22c\uc790\uc790\uc758 \ub3c8\uc744 \ubaa8\uc544 \uc120\ubc15\uacfc \uac70\ub798\ub97c \uc900\ube44\ud588\ub2e4. \uc624\ub79c \ud56d\ud574\uc640 \uc190\uc2e4\uc758 \uc704\ud5d8\uc744 \ud55c \uc0ac\ub78c\uc774 \ubaa8\ub450 \uac10\ub2f9\ud558\uae30 \uc5b4\ub824\uc6b4 \uc0ac\uc5c5\uc774\uc5c8\ub2e4. \ucc98\uc74c \uc911\uc694\ud55c \ubb3c\ud488\uc740 \ud5a5\uc2e0\ub8cc\uc600\ub2e4. \ud558\uc9c0\ub9cc \uc218\uc775\uc758 \uc870\uac74\uc740 \uacc4\uc18d \ub2ec\ub77c\uc84c\ub2e4. \ud68c\uc0ac\ub294 \uc778\ub3c4\uc758 \uc9c1\ubb3c \uac19\uc740 \uc0c1\ud488\uc5d0 \uad00\uc2ec\uc744 \ub113\ud600 \uac14\ub2e4. \uc5b4\ub5a4 \ubb3c\uac74\uc774 \uc798 \ud314\ub9ac\ub294\uc9c0\uc5d0 \ub530\ub77c \uac70\ub798\ub97c \ubc14\uafb8\ub294 \ubaa8\uc2b5\uc740 \uc0c1\uc5c5 \ud68c\uc0ac\ub77c\ub294 \ucd9c\ubc1c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc778\ub3c4\ub294 \ube48 \ub545\uc774\ub098 \ub2e8\uc21c\ud55c \uc6d0\ub8cc \ucc3d\uace0\uac00 \uc544\ub2c8\uc5c8\ub2e4. \uc219\ub828\ub41c \uc9c1\ubb3c \uc0dd\uc0b0\uc790\uc640 \uc0c1\uc778, \uc5ec\ub7ec \ud1b5\uce58 \uc138\ub825\uc774 \uc788\uc5c8\ub2e4. \ud68c\uc0ac\ub294 \uadf8\ub4e4\uc774 \ub9cc\ub4e0 \uc0dd\uc0b0\uacfc \uad50\uc5ed\uc758 \uc138\uacc4\uc5d0 \ub4e4\uc5b4\uac00 \ud5c8\uac00\uc640 \ubb3c\uac74\uc744 \uc5bb\uc5b4\uc57c \ud588\ub2e4. \uc678\uad6d\uc758 \ud68c\uc0ac\uac00 \uc654\ub2e4\uace0 \uace7\ubc14\ub85c \ubaa8\ub4e0 \uad00\uacc4\ub97c \uc9c0\ubc30\ud560 \uc218 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud604\uc9c0\uc758 \uc774\ud574\uad00\uacc4\uc640 \uc815\uce58\uc801 \uacbd\uc7c1\uc744 \uc54c\uc544\uc57c \ud588\ub2e4. \ubb34\uc5ed\uc758 \uae38\uc774 \uad8c\ub825\uc758 \uae38\ub85c \ubc14\ub00c\ub294 \ub370\uc5d0\ub294 \uae30\uc874 \uc9c8\uc11c\uc640\uc758 \ud611\uc0c1\uacfc \ucda9\ub3cc\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. 18\uc138\uae30 \uc601\uad6d\uacfc \ud504\ub791\uc2a4\uc758 \uacbd\uc7c1\uc740 \uc720\ub7fd\uc5d0\ub9cc \uba38\ubb3c\uc9c0 \uc54a\uc558\ub2e4. \uc778\ub3c4\uc5d0\uc11c\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc138\ub825\uacfc \uad00\uacc4\ub97c \ub9fa\uace0 \uad70\uc0ac\uc801\uc73c\ub85c \ucda9\ub3cc\ud588\ub2e4. \uc0c1\uc5c5\uc758 \uc774\uc775\uacfc \uad6d\uac00 \uac04 \uacbd\uc7c1, \ud604\uc9c0\uc758 \uad8c\ub825 \ub2e4\ud23c\uc774 \uacb9\ucce4\ub2e4. 1757\ub144 \ubcb5\uace8\uc5d0\uc11c \ud68c\uc0ac\uad70\uc774 \uac70\ub454 \uc2b9\ub9ac\ub294 \uc601\ud5a5\ub825\uc744 \ub113\ud788\ub294 \uc911\uc694\ud55c \uacc4\uae30\uac00 \ub418\uc5c8\ub2e4. \uc774\ub97c \uc720\ub7fd\uc778\uc774 \uc77c\ubc29\uc801\uc73c\ub85c \uc778\ub3c4\ub97c \uc815\ubcf5\ud55c \ub2e8\uc21c\ud55c \uc7a5\uba74\uc73c\ub85c \uc904\uc774\uba74 \ud604\uc9c0 \ubcd1\uc0ac\uc640 \uc815\uce58 \uc138\ub825\uc758 \uc5ed\ud560\uc774 \uac00\ub824\uc9c4\ub2e4. \ud68c\uc0ac\uc758 \ud798\uc740 \uadf8\ub7f0 \uad00\uacc4 \uc18d\uc5d0\uc11c \ucee4\uc84c\ub2e4. 1765\ub144 \ud68c\uc0ac\ub294 \ubcb5\uace8\uc5d0\uc11c \uc138\uae08\uc744 \uac70\ub458 \uad8c\ub9ac\ub97c \uc5bb\uc5c8\ub2e4. \ubb3c\uac74\uc744 \uc0ac\uace0\ud314\uc544 \ub0a8\uae30\ub294 \uc774\uc775 \uc678\uc5d0 \uc9c0\uc5ed\uc758 \uc870\uc138 \uc218\uc785\uc744 \ud655\ubcf4\ud558\uac8c \ub41c \uac83\uc774\ub2e4. \ubb34\uc5ed\uc758 \uc131\uacf5 \uc5ec\ubd80\uc640\ub294 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ub9ce\uc740 \uc0ac\ub78c\uc758 \uc0dd\ud65c\uc5d0 \uad00\uc5ec\ud560 \uc218 \uc788\uc5c8\ub2e4. \uc9d5\uc138\uad8c\uc740 \ud589\uc815\uc801\uc778 \uc9c1\ud568 \ud558\ub098\uac00 \uc544\ub2c8\uc5c8\ub2e4. \ub3c8\uc744 \uc5b4\ub5bb\uac8c \ud655\ubcf4\ud558\uace0 \ub204\uad6c\uc5d0\uac8c \ubb34\uc5c7\uc744 \uc694\uad6c\ud560\uc9c0 \uacb0\uc815\ud558\ub294 \ud798\uc774\uc5c8\ub2e4. \ud68c\uc0ac\uc758 \uad70\uc0ac\ub825\uacfc \uc7ac\uc815\uc740 \uc11c\ub85c\ub97c \ub5a0\ubc1b\ucce4\uace0, \ud22c\uc790\uc790\uc758 \uae30\ub300\uc640 \uc8fc\ubbfc\uc758 \ubd80\ub2f4\uc774 \uac19\uc740 \uccb4\uacc4\uc5d0 \ubb36\uc774\uae30 \uc2dc\uc791\ud588\ub2e4. \ud68c\uc0ac\uc758 \uad70\ub300\uc5d0\ub294 \uc138\ud3ec\uc774\ub77c\uace0 \ubd80\ub978 \uc778\ub3c4\uc778 \ubcd1\uc0ac\ub4e4\uc774 \uc788\uc5c8\ub2e4. \uc774\ub4e4\uc740 \uc601\uad6d\uc778 \uc7a5\uad50\ub4e4\uacfc \ud568\uaed8 \uc9c0\uc5ed\uc744 \uc9c0\ud0a4\uace0 \ud1b5\uce58\ub97c \uac15\uc81c\ud558\ub294 \uc77c\uc5d0 \ub3d9\uc6d0\ub418\uc5c8\ub2e4. \uadf8\ub9bc\uc5d0 \uc2e4\uc740 \uac83\uc740 \uc57d 1810\ub144 \ub9c8\ub4dc\ub77c\uc2a4 \ubcf4\ubcd1\ub300 \ubcd1\uc0ac\uc640 \uc544\ub0b4\uc758 \uc218\ucc44\ud654\ub2e4. \uadf8\ub9bc \uc18d \uc778\ubb3c\uc774 1757\ub144 \uc804\ud22c\uc758 \ud2b9\uc815 \ucc38\uac00\uc790\ub77c\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \ud68c\uc0ac\uc758 \uad8c\ub825\uc774 \uc778\ub3c4\uc778\uc758 \ub178\ub3d9\uacfc \ubcf5\ubb34\uc5d0\ub3c4 \uc758\uc9c0\ud588\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uac70\ub300\ud55c \ud68c\uc0ac\ub77c\ub294 \uc774\ub984 \uc544\ub798 \uc2e4\uc81c\ub85c \ubcf5\ubb34\ud558\uace0 \uc0b4\uc544\uac04 \uc0ac\ub78c\ub4e4\uc774 \uc788\uc5c8\ub2e4. \ud68c\uc0ac\ub294 \ubaa8\ub4e0 \uacf3\uc744 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc9c1\uc811 \ub2e4\uc2a4\ub9ac\uc9c0 \uc54a\uc558\ub2e4. \uae30\uc874 \uc9c0\ubc30\uc790\uc640 \ud611\ub825\ud558\uace0 \uadf8 \uad8c\uc704\ub97c \uc778\uc815\ud558\ub294 \ub300\uc2e0 \uc138\uae08\uacfc \ubcd1\ub825, \uc815\ucc45\uc758 \ud611\uc870\ub97c \uc5bb\uae30\ub3c4 \ud588\ub2e4. \ud604\uc9c0\uc758 \uc81c\ub3c4\ub97c \ud65c\uc6a9\ud558\ub294 \uac04\uc811 \ud1b5\uce58\uc600\ub2e4. \uc774\ub7f0 \ubc29\uc2dd\uc740 \uc8fc\ubbfc\uc5d0\uac8c \uc2dd\ubbfc \uc9c0\ubc30\uac00 \uc5c6\uc5c8\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uac89\uc73c\ub85c \uc775\uc219\ud55c \ud1b5\uce58\uc790\uac00 \ub0a8\uc544 \uc788\uc5b4\ub3c4 \uc911\uc694\ud55c \uacb0\uc815\uc740 \ud68c\uc0ac\uc758 \uc774\ud574\uc5d0 \ub9de\ucdb0\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \ub204\uad6c\uc758 \uc774\ub984\uc73c\ub85c \uba85\ub839\ud558\ub294\uc9c0\uc640 \ub204\uac00 \uacb0\uc815\uc758 \ud798\uc744 \uac00\uc9c0\ub294\uc9c0\ub294 \ud568\uaed8 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc774\uc775\uc744 \ub298\ub9ac\ub824\ub294 \ud68c\uc0ac\uc758 \ubaa9\ud45c\uc640 \uc8fc\ubbfc\uc758 \uc0dd\ud65c\uc744 \uc548\uc815\uc2dc\ud0a4\ub294 \ud1b5\uce58\uc758 \ucc45\uc784\uc740 \uc27d\uac8c \uc77c\uce58\ud558\uc9c0 \uc54a\ub294\ub2e4. \uac19\uc740 \uc218\uc785\ub3c4 \ud22c\uc790\uc790\uc5d0\uac8c\ub294 \uc131\uacfc\uc774\uc9c0\ub9cc \uadf8\uac83\uc744 \ub0b8 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ubd80\ub2f4\uc774\ub2e4. \uad70\ub300\uc640 \ud589\uc815\uc744 \uc720\uc9c0\ud560 \ube44\uc6a9\ub3c4 \uacc4\uc18d \ud544\uc694\ud588\ub2e4. \ud68c\uc0ac\ub294 \uc778\ub3c4\uc5d0\uc11c \uc0dd\uc0b0\ud55c \uc544\ud3b8\uc744 \uc911\uad6d\uc758 \ucc28\uc640 \uc5f0\uacb0\ud558\ub294 \ubb34\uc5ed\uc5d0\ub3c4 \uad00\uc5ec\ud588\ub2e4. \ub2e8\uc21c\ud788 \uc778\uae30 \uc0c1\ud488\uc744 \ubc14\uafe8\ub2e4\uace0 \ub05d\ub0bc \uc218 \uc5c6\ub294 \uc120\ud0dd\uc774\uc5c8\ub2e4. \uc0c1\uc5c5\uc758 \uc218\uc775\uc774 \ub2e4\ub978 \uc0ac\ud68c\uc5d0 \ub0a8\uae30\ub294 \ud53c\ud574\uae4c\uc9c0 \ubb3b\uae30 \uc2dc\uc791\ud558\uba74 \ud68c\uc0ac\uc758 \uc774\uc57c\uae30\ub294 \ud6e8\uc52c \ub113\uc5b4\uc9c4\ub2e4. 1857\ub144 \ud68c\uc0ac \uc18c\uc18d \ubcd1\uc0ac\ub4e4\uc758 \ubd09\uae30\ub97c \ube44\ub86f\ud574 \ud070 \uc800\ud56d\uc774 \uc77c\uc5b4\ub0ac\ub2e4. \uc9c4\uc555 \ub4a4 1858\ub144 \ud68c\uc0ac\uac00 \ub9e1\ub358 \ud1b5\uce58 \uad8c\ud55c\uc740 \uc601\uad6d \uc655\uc2e4 \ucabd\uc73c\ub85c \ub118\uc5b4\uac14\ub2e4. \ud68c\uc0ac \ud1b5\uce58\uc758 \ubc29\uc2dd\uc740 \ub05d\ub0ac\uc9c0\ub9cc \uc778\ub3c4\uc758 \uc2dd\ubbfc \uc9c0\ubc30\uac00 \ud568\uaed8 \ub05d\ub09c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uad8c\ub825\uc758 \uc8fc\uccb4\uac00 \ubc14\ub010 \uc0ac\uc2e4\uacfc \uc8fc\ubbfc\uc774 \uc790\uce58\ub97c \uc5bb\uc740 \uc0ac\uc2e4\uc744 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ud68c\uc0ac\uc758 \ubc95\uc801 \uc874\uc18d\uacfc \ud1b5\uce58 \uad8c\ud55c\uc758 \uc885\ub8cc\ub3c4 \uac19\uc740 \ub0a0\uc9dc\uc758 \uc0ac\uac74\uc73c\ub85c \ub2e8\uc21c\ud654\ud560 \uc218 \uc5c6\ub2e4. \uc774 \uae00\uc740 \ud68c\uc0ac\uac00 \ub2e4\uc2a4\ub9ac\ub294 \uccb4\uc81c\uac00 \ubc14\ub010 \uc9c0\uc810\uc5d0 \ucd08\uc810\uc744 \ub9de\ucd98\ub2e4. \ub3d9\uc778\ub3c4\ud68c\uc0ac\uc758 \uc5ed\uc0ac\ub294 \ucee4\ub2e4\ub780 \uae30\uc5c5\uc758 \uc131\uacf5\ub2f4\ub9cc\uc73c\ub85c \uc77d\uae30 \uc5b4\ub835\ub2e4. \uacf5\ub3d9 \ud22c\uc790\uc640 \ubb34\uc5ed\uc5d0\uc11c \ucd9c\ubc1c\ud55c \uc870\uc9c1\uc774 \ubb34\uc5c7\uc744 \ud560 \uad8c\ub9ac\ub97c \uc5bb\uc5c8\ub294\uc9c0, \uadf8 \ud798\uc744 \ub204\uac00 \ud1b5\uc81c\ud588\ub294\uc9c0 \ubb3b\uac8c \ud55c\ub2e4. \ud310\ub9e4\ub7c9\ubcf4\ub2e4 \uad70\ub300\uc640 \uc138\uae08\uc774 \uc911\uc694\ud55c \uc9c8\ubb38\uc73c\ub85c \ub098\ud0c0\ub09c\ub2e4. \uc6b0\ub9ac\uac00 \ud68c\uc0ac\ub77c\uace0 \ubd80\ub974\ub294 \uc870\uc9c1\ub3c4 \uc2dc\ub300\uc640 \uc81c\ub3c4\uc5d0 \ub530\ub77c \uc804\ud600 \ub2e4\ub978 \uad8c\ud55c\uc744 \uac00\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \ud56d\uad6c\uc5d0\uc11c \uc2dc\uc791\ud55c \uc7a5\uc0ac\uc758 \uae38\uc744 \ub530\ub77c\uac00\ub2e4 \ubcf4\uba74 \ub3c8\uc744 \ubc84\ub294 \uc77c\uacfc \ud0c0\uc778\uc758 \uc0b6\uc744 \ub2e4\uc2a4\ub9ac\ub294 \uc77c\uc758 \uacbd\uacc4\uac00 \uc5bc\ub9c8\ub098 \uc911\uc694\ud588\ub294\uc9c0 \ubcf4\uc778\ub2e4."}, {"id": "edison-lighting-network-beyond-bulb", "title": "\uc804\uad6c \ub2e4\uc74c\uc758 \ubc1c\uba85 \u2014 \uc5d0\ub514\uc2a8\uc740 \uc65c \uc804\uc120\uc744 \uac70\ub9ac\ub85c \ub0b4\ubcf4\ub0c8\uc744\uae4c", "summary": "\uc804\uad6c \ud558\ub098\ub97c \ub9cc\ub4dc\ub294 \uc77c\uc5d0\uc11c \uc5ec\ub7ec \uace0\uac1d\uc5d0\uac8c \ube5b\uc744 \uacc4\uc18d \uacf5\uae09\ud558\ub294 \uc0ac\uc5c5\uc73c\ub85c \ub118\uc5b4\uac04 \uc870\uac74\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\ucc3d\uc5c5\uacfc \uc131\uc7a5", "categories": ["industry"], "url": "stories/edison-lighting-network-beyond-bulb/index.html", "image": "../media/edison-lighting-network-beyond-bulb.png", "alt": "\uc804\uad6c\ub97c \uc2dc\ud5d8\ud558\ub294 \uc791\uc5c5\uc7a5\uacfc \ubc1c\uc804 \uc124\ube44\ub97c \ud568\uaed8 \ub5a0\uc62c\ub9ac\ub294 \uc804\uae30 \uc870\uba85 \uc0ac\uc5c5\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uc804\uad6c \ub2e4\uc74c\uc758 \ubc1c\uba85 \u2014 \uc5d0\ub514\uc2a8\uc740 \uc65c \uc804\uc120\uc744 \uac70\ub9ac\ub85c \ub0b4\ubcf4\ub0c8\uc744\uae4c \uc804\uad6c\uc758 \uc131\ub2a5\uc5d0\uc11c \ubc30\uc804\u00b7\uacc4\ub7c9\u00b7\uacf5\uae09 \uc0ac\uc5c5\uc73c\ub85c \ub113\uc5b4\uc9c4 \ubc1c\uba85 \uc804\uad6c \ud558\ub098\ub97c \ub9cc\ub4dc\ub294 \uc77c\uc5d0\uc11c \uc5ec\ub7ec \uace0\uac1d\uc5d0\uac8c \ube5b\uc744 \uacc4\uc18d \uacf5\uae09\ud558\ub294 \uc0ac\uc5c5\uc73c\ub85c \ub118\uc5b4\uac04 \uc870\uac74\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ucc3d\uc5c5\uacfc \uc131\uc7a5 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \uc804\uad6c \ud558\ub098\uac00 \ucf1c\uc9c0\ub294 \uc7a5\uba74\uc740 \uc804\uae30\uc758 \uc5ed\uc0ac\ub97c \uc0c1\uc9d5\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc218\ub9ce\uc740 \uc9d1\uc5d0\uc11c \ub9e4\uc77c \ubd88\uc744 \ucf1c\ub824\uba74 \uc804\uad6c\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud558\ub2e4. \uc804\uae30\ub97c \ub9cc\ub4e4\uace0 \ubcf4\ub0b4\uba70 \uc0ac\uc6a9\ub7c9\uc744 \uacc4\uc0b0\ud558\uace0 \uace0\uc7a5\uc744 \uace0\uce60 \uccb4\uacc4\uac00 \ud544\uc694\ud558\ub2e4. \uc5d0\ub514\uc2a8\uc758 \uc870\uba85 \uc0ac\uc5c5\uc744 \ud1b5\ud574 \uc81c\ud488\uc744 \ubc1c\uba85\ud558\ub294 \uc77c\uacfc \uc11c\ube44\uc2a4\ub97c \uacf5\uae09\ud558\ub294 \uc77c \uc0ac\uc774\uc758 \uac70\ub9ac\ub97c \uc0b4\ud3b4\ubcf4\uc790. \uc804\uae30\ub85c \ubb3c\uc9c8\uc744 \ub728\uac81\uac8c \ub9cc\ub4e4\uc5b4 \ube5b\uc744 \ub0b4\ub294 \uc2dc\ub3c4\ub294 \uc5d0\ub514\uc2a8 \uc774\uc804\uc5d0\ub3c4 \uc788\uc5c8\ub2e4. \ucd08\uae30 \uc804\uad6c\uc758 \ubb38\uc81c\ub294 \ucf1c\uc9c0\ub294\uac00\ubfd0 \uc544\ub2c8\ub77c \uc5bc\ub9c8\ub098 \ubc84\ud2f0\uace0 \uc5b4\ub5a4 \uc870\uac74\uc5d0\uc11c \uc4f8 \uc218 \uc788\ub294\uac00\uc600\ub2e4. \uc5f0\uad6c\uc758 \ucd9c\ubc1c\uacfc \uc2e4\uc6a9\uc801\uc778 \ubcf4\uae09\uc744 \ud55c \uc0ac\ub78c\uc758 \ud55c\uc21c\uac04\uc73c\ub85c \ud569\uce58\uba74 \uae34 \uac1c\uc120 \uacfc\uc815\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \ubc31\uc5f4\ub4f1\uc740 \ub2f9\uc2dc \uc804\uae30 \uc870\uba85\uc758 \uc720\uc77c\ud55c \ubc29\uc2dd\ub3c4 \uc544\ub2c8\uc5c8\ub2e4. \uac15\ud55c \ube5b\uc744 \ub0b4\ub294 \uc544\ud06c\ub4f1\uacfc \uc791\uc740 \uacf5\uac04\uc744 \ube44\ucd94\ub824\ub294 \ubc31\uc5f4\ub4f1\uc740 \uc4f0\uc784\uacfc \uc694\uad6c\uac00 \ub2ec\ub790\ub2e4. \ubb34\uc5c7\uc774 \ub354 \ubc1d\uc740\uac00\ub9cc\uc73c\ub85c \uc88b\uc740 \uc870\uba85\uc744 \uc815\ud560 \uc218\ub294 \uc5c6\uc5c8\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \uc0dd\ud65c\ud558\ub294 \ubc29 \uc548\uc5d0\uc11c \ub2e4\ub8f0 \uc218 \uc788\uc5b4\uc57c \ud588\ub2e4. \ud544\ub77c\uba58\ud2b8\uc758 \uc7ac\ub8cc\uc640 \ubaa8\uc591, \ub0b4\ubd80 \uc0c1\ud0dc\ub294 \uc804\uad6c\uc758 \uc131\ub2a5\uc5d0 \uc601\ud5a5\uc744 \uc8fc\uc5c8\ub2e4. \uc624\ub798 \ubc84\ud2f4\ub2e4\uace0 \ub9cc\ub4e4\uae30 \ub108\ubb34 \ube44\uc2f8\uba74 \ub110\ub9ac \uc4f0\uae30 \uc5b4\ub835\uace0, \uc2f8\uc9c0\ub9cc \uc790\uc8fc \ub04a\uc5b4\uc838\ub3c4 \uc6b4\uc601\uc758 \ubd80\ub2f4\uc774 \ucee4\uc9c4\ub2e4. \uae30\uc220\uc801\uc778 \uc120\ud0dd\uc774 \uc0ac\uc6a9\uc790\uc758 \ube44\uc6a9\uacfc \uace7\ubc14\ub85c \uc5f0\uacb0\ub41c\ub2e4. \uc774\ub7f0 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub294 \uacfc\uc815\uc5d0\ub294 \uc7ac\ub8cc\ub97c \uc2dc\ud5d8\ud558\uace0 \uac19\uc740 \ud488\uc9c8\ub85c \ub9cc\ub4dc\ub294 \uc77c\uc774 \ud544\uc694\ud588\ub2e4. \uc131\uacf5\ud55c \uc2dc\uc81c\ud488 \ud55c \uac1c\uc640 \ub300\ub7c9\uc73c\ub85c \uacf5\uae09\ud560 \uc81c\ud488\uc740 \ub2e4\ub974\ub2e4. \uc804\uad6c\uc758 \ubc1c\uba85\uc0ac\ub294 \ube5b\uc744 \ubc1c\uacac\ud558\ub294 \uc774\uc57c\uae30\uc774\uba74\uc11c \uc0dd\uc0b0\uacfc \uad50\uccb4\uc758 \uc870\uac74\uc744 \uc870\uc815\ud558\ub294 \uc774\uc57c\uae30\uc774\uae30\ub3c4 \ud558\ub2e4. \uc804\uae30\ub97c \uc4f0\ub294 \uacf3\uacfc \ub9cc\ub4dc\ub294 \uacf3\uc744 \ubd84\ub9ac\ud558\uba74 \uc5ec\ub7ec \uace0\uac1d\uc5d0\uac8c \uacf5\uae09\ud560 \uac00\ub2a5\uc131\uc774 \uc0dd\uae34\ub2e4. \ub300\uc2e0 \ubc1c\uc804\uc18c\uc640 \uc9d1 \uc0ac\uc774\uc758 \uc804\uc120\uc774 \uc0c8\ub85c\uc6b4 \uacfc\uc81c\uac00 \ub41c\ub2e4. \uac70\ub9ac\uac00 \ub298\uc5b4\ub098\ub3c4 \ud544\uc694\ud55c \uc0c1\ud0dc\uc758 \uc804\uae30\ub97c \ubcf4\ub0bc \uc218 \uc788\uc5b4\uc57c \ud588\ub2e4. \ubc29 \uc548\uc758 \uc804\uad6c\uac00 \ub3c4\uc2dc\uc758 \uae30\ubc18 \uc2dc\uc124\uacfc \uc5f0\uacb0\ub418\ub294 \uc21c\uac04\uc774\ub2e4. \ubc1c\uc804 \ub2a5\ub825\uacfc \ubc30\uc120, \uc5f0\uacb0 \uc7a5\uce58\uc758 \uad00\uacc4\ub97c \ub9de\ucd94\uc9c0 \uc54a\uc73c\uba74 \ubd80\ud488 \ud558\ub098\uac00 \uc88b\uc544\ub3c4 \uc804\uccb4\ub294 \uc791\ub3d9\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc81c\ud488\uc744 \ud30c\ub294 \ud68c\uc0ac\uc640 \uacf5\uae09\ub9dd\uc744 \uc6b4\uc601\ud558\ub294 \ud68c\uc0ac\uac00 \ub9e1\uc544\uc57c \ud560 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uc870\uba85 \uc0ac\uc5c5\uc740 \ub450 \uc5ed\ud560\uc744 \ud568\uaed8 \uc0dd\uac01\ud558\uac8c \ub9cc\ub4e4\uc5c8\ub2e4. \uc0ac\uc6a9\uc790\ub294 \uc790\uae30 \ubc29\uc758 \ubd88\uc744 \ucf1c\uace0 \ub044\uace0 \uc2f6\uc5b4 \ud55c\ub2e4. \uadf8\ub7f0\ub370 \uc5b4\ub5a4 \uc5f0\uacb0\uc5d0\uc11c\ub294 \ud55c \uacf3\uc758 \ubcc0\ud654\uac00 \ub2e4\ub978 \uacf3\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc900\ub2e4. \uc5ec\ub7ec \uc870\uba85\uc744 \ud568\uaed8 \uacf5\uae09\ud558\ub824\uba74 \uac01 \uace0\uac1d\uc758 \uc0ac\uc6a9\uacfc \uc804\uccb4 \ud68c\ub85c\uc758 \uad00\uacc4\ub97c \uc124\uacc4\ud574\uc57c \ud588\ub2e4. \ubc30\uc120\uc740 \uc804\uad6c\ub97c \uc787\ub294 \ub2e8\uc21c\ud55c \ub048\uc774 \uc544\ub2c8\uc5c8\ub2e4. 1900\ub144 \uae30\uc220\uc0ac \ucc45\uc5d0\ub294 \uc5d0\ub514\uc2a8\uc758 \ubc30\uc804 \ubc29\uc2dd\uacfc \uc5ec\ub7ec \uc804\uad6c\ub97c \uc5f0\uacb0\ud558\ub294 \ud68c\ub85c\uac00 \uc124\uba85\ub41c\ub2e4. \ub2e4\ub9cc \uadf8 \ucc45\uc758 \ub2f9\uc2dc \uc804\ub958 \ubc29\uc2dd\uc5d0 \uad00\ud55c \uc124\uba85\uc744 \uc624\ub298\uc758 \ubcf4\ud3b8 \ubc95\uce59\uc73c\ub85c \uc62e\uae30\uba74 \uc548 \ub41c\ub2e4. \uc5ec\uae30\uc11c\ub294 \ud2b9\uc815 \ubc29\uc2dd\uc758 \uc6b0\uc5f4\ubcf4\ub2e4 \uc5ec\ub7ec \uc0ac\uc6a9\uc790\ub97c \ub3d9\uc2dc\uc5d0 \uc5f0\uacb0\ud558\ub824\ub358 \uc2dc\uc2a4\ud15c\uc758 \ubb38\uc81c\uc5d0 \uc8fc\ubaa9\ud55c\ub2e4. \ud68c\ub85c\uc758 \uad6c\uc131\uc740 \uc804\uc120\uc5d0 \ub4e4\uc5b4\uac00\ub294 \uc7ac\ub8cc\uc758 \uc591\uacfc\ub3c4 \uad00\uacc4\ub41c\ub2e4. \uac19\uc740 \uc11c\ube44\uc2a4\ub97c \uacf5\uae09\ud558\ub354\ub77c\ub3c4 \ud544\uc694\ud55c \uad6c\ub9ac\uc640 \uc124\uce58 \ube44\uc6a9\uc774 \ub2ec\ub77c\uc9c0\uba74 \uc0ac\uc5c5\uc758 \uac00\ub2a5\uc131\ub3c4 \ubc14\ub010\ub2e4. \uae30\uc220\uc0ac \ucc45\uc774 \uc804\uad6c\uc640 \ud568\uaed8 \ubc30\uc804 \ubc29\uc2dd\uc744 \uc124\uba85\ud558\ub294 \uac83\uc740 \uc774\ub7f0 \uc774\uc720\ub2e4. \uace0\uac1d\uc5d0\uac8c\ub294 \uac19\uc740 \ubd88\ube5b\uc774\uc5b4\ub3c4 \uadf8 \ubd88\ube5b\uc744 \uc81c\uacf5\ud558\ub294 \uad6c\uc870\uc758 \ube44\uc6a9\uc740 \uac19\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \ub530\ub77c\uc11c \ubc1c\uba85\uc744 \ubd80\ud488 \ud558\ub098\uc758 \uacbd\uc7c1\uc73c\ub85c\ub9cc \ubcf4\uba74 \uc2dc\uc2a4\ud15c\uc758 \uac1c\uc120\uc744 \ub193\uce5c\ub2e4. \ub208\uc5d0 \ub744\ub294 \uc804\uad6c\uc758 \ubcc0\ud654\uc640 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc804\uc120\uc758 \uc7ac\ubc30\uce58\uac00 \ud568\uaed8 \uc758\ubbf8\ub97c \uac00\uc9c4\ub2e4. \uc88b\uc740 \uc81c\ud488\uc758 \uc870\uac74\uc5d0\ub294 \uc81c\ud488 \ubc16\uc5d0\uc11c \uadf8\uac83\uc744 \ub4b7\ubc1b\uce68\ud558\ub294 \uc790\uc6d0\uacfc \uc124\ube44\ub3c4 \ud3ec\ud568\ub41c\ub2e4. \ub110\ub9ac \uacf5\uae09\ud558\ub294 \uc77c\uc740 \uc7a5\uce58\uc758 \uc131\ub2a5\uc744 \uace0\uac1d\uc758 \ube44\uc6a9\uacfc \uc6b4\uc601\uc758 \uaddc\ubaa8\uc5d0 \uc5f0\uacb0\ud558\ub294 \uc77c\uc774\uc5c8\ub2e4. \uacf5\uae09 \uc0ac\uc5c5\uc5d0\ub294 \uc5bc\ub9c8\ub098 \uc0ac\uc6a9\ud588\ub294\uc9c0 \uacc4\uc0b0\ud558\ub294 \uc77c\uc774 \ub530\ub978\ub2e4. \uc804\uae30\uac00 \ub208\uc5d0 \ubcf4\uc774\ub294 \uafb8\ub7ec\ubbf8\ub85c \ubc30\ub2ec\ub418\ub294 \ubb3c\uac74\uc740 \uc544\ub2c8\uae30 \ub54c\ubb38\uc774\ub2e4. \uacc4\ub7c9\uacfc \uc694\uae08\uc758 \uad00\uacc4\ub97c \uc815\ud574\uc57c \uc9c0\uc18d\uc801\uc73c\ub85c \uacf5\uae09\ud560 \uc218 \uc788\uc5c8\ub2e4. \uc804\uc120\uacfc \ud568\uaed8 \uacc4\uc57d\uacfc \uacc4\uc0b0\uc758 \uad6c\uc870\ub3c4 \ud544\uc694\ud588\ub2e4. \uace0\uac1d\uc5d0\uac8c\ub294 \ubd88\uc774 \ucf1c\uc9c0\ub294\uc9c0\uac00 \uc911\uc694\ud558\uc9c0\ub9cc \ud68c\uc0ac\uc5d0\ub294 \uacf5\uae09 \ub2a5\ub825\uacfc \ube44\uc6a9\uc758 \uade0\ud615\ub3c4 \uc911\uc694\ud558\ub2e4. \uc218\uc694\uac00 \ub2ec\ub77c\uc9c8 \ub54c \ubb34\uc5c7\uc744 \uc900\ube44\ud574\uc57c \ud558\ub294\uc9c0, \uace0\uc7a5\uc774 \ub098\uba74 \ub204\uac00 \uac00\uc57c \ud558\ub294\uc9c0\ub3c4 \uc815\ud574\uc57c \ud55c\ub2e4. \uc0ac\uc5c5\uc758 \uac00\uce58\ub294 \uc7a5\uce58\uc758 \ud310\ub9e4 \ub4a4\uc5d0 \uc774\uc5b4\uc9c0\ub294 \ubc18\ubcf5\uc801\uc778 \uc6b4\uc601\uc5d0\uc11c \ub9cc\ub4e4\uc5b4\uc84c\ub2e4. \ub3c4\uc2dc\uc5d0 \uc804\uc120\uc744 \ub193\ub294 \uc77c\uc740 \ud63c\uc790 \uc18c\uc720\ud55c \ud0c1\uc790 \uc704\uc5d0\uc11c \ud558\ub294 \uc2dc\ud5d8\uacfc \ub2e4\ub974\ub2e4. \ub3c4\ub85c\uc640 \uac74\ubb3c, \ub2e4\ub978 \uc2dc\uc124\uacfc\uc758 \uad00\uacc4\uac00 \uc0dd\uae34\ub2e4. \uacf5\uae09\ub9dd\uc758 \ud655\uc7a5\uc740 \uae30\uc220\ubfd0 \uc544\ub2c8\ub77c \uacf5\uc0ac\uc640 \ud589\uc815, \uace0\uac1d\uc744 \uc124\ub4dd\ud558\ub294 \uc77c\uae4c\uc9c0 \uc694\uad6c\ud588\ub2e4. \uc644\uc131\ub41c \uc804\uae30 \uc81c\ud488\uc758 \uc0ac\uc9c4\ub9cc\uc73c\ub85c\ub294 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uacfc\uc815\uc774\ub2e4. \uc804\uae30 \uc870\uba85\uc774 \ub4f1\uc7a5\ud588\ub2e4\uace0 \uae30\uc874 \uc870\uba85 \ubc29\uc2dd\uc774 \uc989\uc2dc \ubaa8\ub450 \uc0ac\ub77c\uc9c4 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \ube44\uc6a9\uacfc \uc9c0\uc5ed\uc758 \uc870\uac74\uc5d0 \ub530\ub77c \uc5ec\ub7ec \ubc29\uc2dd\uc774 \ud568\uaed8 \uc4f0\uc600\ub2e4. \uc0c8 \uae30\uc220\uc758 \ubc1c\ud45c\uc640 \uc77c\uc0c1\uc5d0\uc11c\uc758 \uad50\uccb4 \uc0ac\uc774\uc5d0\ub294 \uc2dc\uac04\uc774 \uc788\ub2e4. \uc0ac\uc5c5\uc758 \uc131\uacf5\uc744 \ud55c \ubc88\uc758 \uc2dc\uc5f0\uc73c\ub85c\ub9cc \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b4 \uc774\uc720\ub2e4. \uc804\uae30 \uc870\uba85\uc758 \uc5ed\uc0ac\ub97c \uc2dc\uc2a4\ud15c\uc73c\ub85c \ubcf4\uba74 \ubc1c\uba85\uc758 \uc8fc\uc5b4\ub3c4 \ub113\uc5b4\uc9c4\ub2e4. \uc804\uad6c\ub97c \uc2dc\ud5d8\ud55c \uc0ac\ub78c\uacfc \ubc1c\uc804\uae30\ub97c \ub2e4\ub8ec \uc0ac\ub78c, \uc804\uc120\uc744 \uae54\uace0 \uace0\uce5c \uc0ac\ub78c\uc774 \ud568\uaed8 \ud544\uc694\ud588\ub2e4. \ud55c \uc0ac\ub78c\uc758 \uc774\ub984\uc774 \ub300\ud45c\ud55c\ub2e4\uace0 \uc2e4\uc81c \uc791\uc5c5\uae4c\uc9c0 \ud55c \uc0ac\ub78c\uc758 \uac83\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774 \uc0ac\ub840\ub294 \uc624\ub298\uc758 \uae30\uc220 \uae30\uc5c5\uc744 \uc77d\ub294 \ub370\uc5d0\ub3c4 \uc9c8\ubb38\uc744 \uc900\ub2e4. \uace0\uac1d\uc774 \uad6c\uc785\ud558\ub294 \uac83\uc740 \uc81c\ud488 \ud55c \uac1c\uc77c \uc218\ub3c4 \uc788\uc9c0\ub9cc, \uadf8 \uc81c\ud488\uc774 \uacc4\uc18d \uc791\ub3d9\ud560 \ud658\uacbd\uc77c \uc218\ub3c4 \uc788\ub2e4. \ubc29 \uc548\uc758 \uc791\uc740 \ubd88\ube5b \ub4a4\uc5d0 \ub3c4\uc2dc\uc640 \ud68c\uc0ac\ub97c \uc5f0\uacb0\ud55c \uad6c\uc870\ub97c \ubcf4\uba74, \ubc1c\uba85\uc774 \uc0dd\ud65c\uc774 \ub418\ub294 \uacfc\uc815\uc774 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \ub4dc\ub7ec\ub09c\ub2e4."}, {"id": "ford-moving-assembly", "title": "\ud3ec\ub4dc\uc758 \uc870\ub9bd\ub77c\uc778 \u2014 \uc0ac\ub78c\uc774 \ucc28\ub97c \ucc3e\uc544\ub2e4\ub2c8\uc9c0 \uc54a\uac8c \ub418\uc790", "summary": "\uc77c\ud558\ub294 \uc790\ub9ac\uc640 \ubd80\ud488\uc758 \uc774\ub3d9\uc744 \ubc14\uafbc \uacf5\uc7a5 \uc2e4\ud5d8\uc5d0\uc11c \uc0dd\uc0b0\uc131\uacfc \ub178\ub3d9\uc758 \ub450 \uc5bc\uad74\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\uacf5\uc7a5\uacfc \uc0dd\uc0b0", "categories": ["industry"], "url": "stories/ford-moving-assembly/index.html", "image": "../media/ford-moving-assembly.png", "alt": "20\uc138\uae30 \ucd08 \uc790\ub3d9\ucc28 \uacf5\uc7a5\uc5d0\uc11c \uc791\uc5c5\uc790\ub4e4\uc774 \uc774\ub3d9\ud558\ub294 \uc100\uc2dc\uc758 \uc5ec\ub7ec \ubd80\ubd84\uc744 \uc870\ub9bd\ud558\ub294 \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ud3ec\ub4dc\uc758 \uc870\ub9bd\ub77c\uc778 \u2014 \uc0ac\ub78c\uc774 \ucc28\ub97c \ucc3e\uc544\ub2e4\ub2c8\uc9c0 \uc54a\uac8c \ub418\uc790 \uc790\ub3d9\ucc28\ub97c \ubc14\uafbc \uac83\uc740 \uc5d4\uc9c4\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4 \uc77c\ud558\ub294 \uc790\ub9ac\uc640 \ubd80\ud488\uc758 \uc774\ub3d9\uc744 \ubc14\uafbc \uacf5\uc7a5 \uc2e4\ud5d8\uc5d0\uc11c \uc0dd\uc0b0\uc131\uacfc \ub178\ub3d9\uc758 \ub450 \uc5bc\uad74\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uacf5\uc7a5\uacfc \uc0dd\uc0b0 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \uc790\ub3d9\ucc28 \ud55c \ub300\ub97c \ub9cc\ub4e4\ub824\uba74 \uc0ac\ub78c\uc774 \ucc28 \uc8fc\uc704\ub97c \uba87 \ubc14\ud034\ub098 \ub3cc\uc544\uc57c \ud560\uae4c. \uacf5\uad6c\ub97c \ucc3e\uace0, \ubb34\uac70\uc6b4 \ubd80\ud488\uc744 \uc62e\uae30\uace0, \ub2e4\uc74c \uc791\uc5c5\uc744 \uae30\ub2e4\ub9b0\ub2e4. \uc644\uc131\ub41c \uc790\ub3d9\ucc28\uc5d0\ub294 \ubcf4\uc774\uc9c0 \uc54a\uc9c0\ub9cc \uacf5\uc7a5\uc758 \ud558\ub8e8\uc5d0\ub294 \uc774\ub7f0 \uc2dc\uac04\uc774 \uac00\ub4dd\ud558\ub2e4. \ud3ec\ub4dc\uc758 \uc870\ub9bd\ub77c\uc778 \uc774\uc57c\uae30\ub294 \ub354 \ud798\uc13c \uc5d4\uc9c4\ubcf4\ub2e4 \uc774 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc6c0\uc9c1\uc784\uc5d0\uc11c \uc2dc\uc791\ud55c\ub2e4. \ud5e8\ub9ac \ud3ec\ub4dc\uac00 \uc0c8\ubba4\uc5bc \ud06c\ub77c\uc6b0\ub354\uc640 \ud568\uaed8 \uc4f4 \ud68c\uace0\ub85d \u300a\ub098\uc758 \uc0b6\uacfc \uc77c\u300b\uc5d0\ub294 \uacf5\uc7a5 \ubc30\uce58\ub97c \uc870\uae08\uc529 \ubc14\uafb8\ub358 \uacfc\uc815\uc774 \ub098\uc628\ub2e4. \uacbd\uc601\uc790\uac00 \uc790\uc2e0\uc758 \uc131\uacfc\ub97c \uc124\uba85\ud55c \ucc45\uc774\ub77c\ub294 \uc810\uc744 \uae30\uc5b5\ud558\uba70 \uc77d\uc73c\uba74, \uc720\uba85\ud55c \ubc1c\uba85\ub2f4 \ub4a4\uc758 \uc2e4\ud5d8\uacfc \uadf8 \uc2e4\ud5d8\uc774 \uc0ac\ub78c\uc5d0\uac8c \ub358\uc9c0\ub294 \uc9c8\ubb38\uc774 \ud568\uaed8 \ubcf4\uc778\ub2e4. \ud68c\uace0\ub85d\uc5d0\uc11c \ud3ec\ub4dc\ub294 \uc870\ub9bd \ubc29\uc2dd\uc744 \ubc14\uafb8\ub294 \uccab\uac78\uc74c\uc744 \uc774\ub807\uac8c \uc124\uba85\ud55c\ub2e4. \uc0ac\ub78c\uc774 \uc77c\uc744 \ucc3e\uc544\ub2e4\ub2c8\ub294 \ub300\uc2e0 \uc77c\uc774 \uc0ac\ub78c\uc5d0\uac8c \uc624\uac8c \ud588\ub2e4\ub294 \uac83\uc774\ub2e4. \ubd80\ud488\uc774 \ud544\uc694\ud55c \uc21c\uc11c\ub300\ub85c \ub193\uc774\uace0, \ub2e4\uc74c \uc791\uc5c5\uc790\uc5d0\uac8c \ub118\uc5b4\uac00\ub294 \uac70\ub9ac\uac00 \uc9e7\uc544\uc9c0\ub3c4\ub85d \uc791\uc5c5\uc7a5\uc744 \ub2e4\uc2dc \ubc30\uc5f4\ud588\ub2e4. \ubabb \ud558\ub098\ub97c \uc870\uc774\ub294 \uc19c\uc528\ub9cc \ube68\ub77c\uc838\uc11c\ub294 \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4. \ubabb\uc744 \uac00\uc838\uc624\ub294 \ub370 \ub4dc\ub294 \uc2dc\uac04\uc774 \uadf8\ub300\ub85c\ub77c\uba74 \ud558\ub8e8 \uc804\uccb4\ub294 \ud06c\uac8c \ub2ec\ub77c\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \ud3ec\ub4dc\ub294 \uc0ac\ub78c\uc774 \uac77\uace0 \ubab8\uc744 \uc219\uc774\ub294 \ub3d9\uc791\uae4c\uc9c0 \uc0dd\uc0b0 \uacfc\uc815\uc73c\ub85c \ubcf4\uc558\ub2e4. \uc6b0\ub9ac\uac00 \uac00\uad6c\ub97c \uc870\ub9bd\ud558\ub2e4\uac00 \ub4dc\ub77c\uc774\ubc84\ub97c \ucc3e\ub290\ub77c \uc790\ub9ac\ub97c \ub728\ub294 \uc77c\uc744 \uacf5\uc7a5 \uc804\uccb4\uc758 \ud06c\uae30\ub85c \ud655\ub300\ud55c \uc148\uc774\ub2e4. \ucc45\uc740 1913\ub144 \ubd04, \ud50c\ub77c\uc774\ud720 \ub9c8\uadf8\ub124\ud1a0\ub77c\ub294 \uc810\ud654 \uad00\ub828 \ubd80\ud488\uc758 \uc870\ub9bd\uc5d0 \uc774\ub3d9\uc2dd \ub77c\uc778\uc744 \uc2dc\ud5d8\ud588\ub2e4\uace0 \uc804\ud55c\ub2e4. \uc790\ub3d9\ucc28 \ud55c \ub300\ub97c \ucc98\uc74c\ubd80\ud130 \ub05d\uae4c\uc9c0 \uc6c0\uc9c1\uc774\ub294 \uac70\ub300\ud55c \uc124\ube44\ub97c \ub2e8\ubc88\uc5d0 \uc644\uc131\ud588\ub2e4\ub294 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \uba3c\uc800 \uc791\uc740 \ubd80\ud488 \ud558\ub098\ub85c \uc0c8\ub85c\uc6b4 \ubc29\uc2dd\uc744 \uc2dc\ud5d8\ud588\ub2e4. \ud55c \uc0ac\ub78c\uc774 \uc5ec\ub7ec \uc791\uc5c5\uc744 \uc774\uc5b4 \ud558\ub358 \uacfc\uc815\uc744 \uc5ec\ub7ec \ub2e8\uacc4\ub85c \ub098\ub204\uace0, \uc791\uc5c5\uc758 \ub192\uc774\uc640 \uc774\ub3d9 \uc18d\ub3c4\ub97c \uc870\uc815\ud588\ub2e4. \ud68c\uace0\ub85d\uc5d0\ub294 \uc2dc\uce74\uace0 \uc721\uac00\uacf5\uc7a5\uc758 \uc774\ub3d9 \uc7a5\uce58\uac00 \ubc1c\uc0c1\uc5d0 \ucc38\uace0\uac00 \ub418\uc5c8\ub2e4\ub294 \uc124\uba85\ub3c4 \uc788\ub2e4. \ud3ec\ub4dc\uac00 \uc138\uc0c1\uc758 \ubd84\uc5c5\uacfc \uc774\ub3d9\uc2dd \uc0dd\uc0b0\uc744 \ud63c\uc790 \ucc98\uc74c \ubc1c\uba85\ud588\ub2e4\uace0 \ub113\ud600 \ub9d0\ud558\uba74 \uc774 \ubc30\uacbd\uc744 \ub193\uce58\uac8c \ub41c\ub2e4. \ubd80\ud488\uc5d0\uc11c \ud6a8\uacfc\ub97c \ubcf8 \ub4a4\uc5d0\ub294 \uc790\ub3d9\ucc28\uc758 \ubf08\ub300\uc778 \uc100\uc2dc\uc5d0\ub3c4 \uc2dc\ub3c4\ud588\ub2e4. \ud68c\uace0\ub85d\uc5d0 \ub530\ub974\uba74 \ucd08\uae30 \uc2e4\ud5d8\uc5d0\uc11c\ub294 \ubc27\uc904\uacfc \uad8c\uc591\uae30\ub85c \uc100\uc2dc\ub97c \ub04c\uc5c8\uace0, \uc870\ub9bd\uacf5\ub4e4\uc774 \ud568\uaed8 \uc6c0\uc9c1\uc774\uba70 \ud544\uc694\ud55c \ubd80\ud488\uc744 \uc9d1\uc5c8\ub2e4. \uc624\ub298\ub0a0 \uc0ac\uc9c4\uc5d0\uc11c \ubcf4\ub294 \uc815\ub3c8\ub41c \uacf5\uc7a5\ubcf4\ub2e4 \ud6e8\uc52c \uac70\uce5c \uc2dc\ud5d8\uc774\uc5c8\ub2e4. \uadf8\ub2e4\uc74c\uc5d0\ub294 \uc791\uc5c5 \ub192\uc774\ub97c \ubc14\uafb8\uace0 \uac01 \uc0ac\ub78c\uc774 \ub9e1\ub294 \ub3d9\uc791\uc744 \ub354 \uc138\ubd84\ud654\ud588\ub2e4. \uc5b4\ub290 \uc7a5\uce58 \ud558\ub098\ub97c \ub4e4\uc5ec\ub193\uc790 \ubaa8\ub4e0 \ubb38\uc81c\uac00 \uc0ac\ub77c\uc9c4 \uac83\uc774 \uc544\ub2c8\ub2e4. \uacf5\uad6c\uac00 \ub193\uc774\ub294 \uc704\uce58, \ubd80\ud488\uc774 \ub3c4\ucc29\ud558\ub294 \uc21c\uc11c, \uc0ac\ub78c\uc774 \uc190\uc744 \ubed7\ub294 \ub192\uc774\uac00 \ud568\uaed8 \ub9de\uc544\uc57c \ucc28\uac00 \uc77c\uc815\ud558\uac8c \uc55e\uc73c\ub85c \ub098\uac08 \uc218 \uc788\uc5c8\ub2e4. \ud3ec\ub4dc\ub294 \uc774\ub3d9 \uc18d\ub3c4\ub97c \uc5ec\ub7ec \ubc88 \ubc14\uafb8\uc5c8\ub2e4\uace0 \uc801\uc5c8\ub2e4. \ube68\ub9ac \uc6c0\uc9c1\uc774\uae30\ub9cc \ud558\uba74 \uc88b\uc740 \ub77c\uc778\uc774\ub77c\uba74 \uc774\ub7f0 \uc870\uc815\uc740 \ud544\uc694\ud558\uc9c0 \uc54a\uc558\uc744 \uac83\uc774\ub2e4. \uc791\uc5c5\uc744 \ub05d\ub0b4\uae30\ub3c4 \uc804\uc5d0 \ubd80\ud488\uc774 \uc9c0\ub098\uac00\uba74 \ub2e4\uc74c \ub2e8\uacc4\uc5d0 \ubb38\uc81c\uac00 \uc313\uc774\uace0, \ub108\ubb34 \ub290\ub9ac\uba74 \uc55e\uc5d0\uc11c \uc904\uc778 \uc2dc\uac04\uc744 \ub4a4\uc5d0\uc11c \ub2e4\uc2dc \uc783\ub294\ub2e4. \uc870\ub9bd\ub77c\uc778\uc758 \ud575\uc2ec\uc740 \ud55c \uc0ac\ub78c\uc758 \ub208\ubd80\uc2e0 \uc190\ub180\ub9bc\ubcf4\ub2e4 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc18d\ub3c4\ub97c \uc11c\ub85c \ub9de\ucd94\ub294 \ub370 \uc788\uc5c8\ub2e4. \uc870\ub9bd \uc911\uac04\uc5d0 \uc798\ubabb\ub41c \ubd80\ud488\uc774 \ub07c\uac70\ub098 \uc791\uc5c5\uc774 \ub2a6\uc5b4\uc9c8 \ub54c\uc758 \uc601\ud5a5\ub3c4 \ucee4\uc9c4\ub2e4. \uacf5\uc7a5\uc740 \uac01\uac01\uc758 \uc7a5\uc778\uc774 \ub3c5\ub9bd\ud574\uc11c \uc77c\ud558\ub294 \uacf5\uac04\uc5d0\uc11c \uc11c\ub85c\uc758 \ubc15\uc790\uc5d0 \uc601\ud5a5\uc744 \ubc1b\ub294 \uc5f0\uacb0\ub41c \uacf5\uac04\uc73c\ub85c \ubc14\ub00c\uc5c8\ub2e4. \uc774 \ubc29\uc2dd\uc740 \ube44\uc2b7\ud55c \ubd80\ud488\uc744 \uc815\ud574\uc9c4 \uc21c\uc11c\ub85c \ubc18\ubcf5\ud574\uc11c \uc870\ub9bd\ud560 \ub54c \ud798\uc744 \ubc1c\ud718\ud55c\ub2e4. \uc8fc\ubb38\ub9c8\ub2e4 \uad6c\uc870\uac00 \uc644\uc804\ud788 \ub2ec\ub77c\uc9c4\ub2e4\uba74 \uac19\uc740 \ubc30\uce58\uc640 \uc18d\ub3c4\ub97c \uc720\uc9c0\ud558\uae30 \uc5b4\ub835\ub2e4. \uc0dd\uc0b0 \ubc29\uc2dd\uc758 \ubcc0\ud654\ub294 \uc81c\ud488\uc744 \uc5bc\ub9c8\ub098 \ub2e4\uc591\ud558\uac8c \ub9cc\ub4e4 \uac83\uc778\uc9c0\ub77c\ub294 \uacbd\uc601\uc758 \uc120\ud0dd\uacfc \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\uc558\ub2e4. \uc791\uc5c5 \uc2dc\uac04\uc774 \uc904\uc5b4\ub4e4\uba74 \ud55c \ub300\ub97c \ub9cc\ub4dc\ub294 \ube44\uc6a9\uc744 \ub0ae\ucd9c \uac00\ub2a5\uc131\uc774 \uc0dd\uae34\ub2e4. \uadf8\ub7ec\ub098 \uc790\ub3d9\ucc28 \uac00\uaca9\uc758 \ubcc0\ud654 \uc804\uccb4\ub97c \uc870\ub9bd\ub77c\uc778 \ud55c \uac00\uc9c0\ub85c \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \ubd80\ud488 \uc0dd\uc0b0, \uc7ac\ub8cc \uad6c\uc785, \ud310\ub9e4 \uaddc\ubaa8\ub3c4 \ud568\uaed8 \uc791\uc6a9\ud55c\ub2e4. \uc5ec\uae30\uc11c \ubd84\uba85\ud788 \ubcfc \uc218 \uc788\ub294 \uac83\uc740 \uc6c0\uc9c1\uc784\uc744 \uc904\uc774\ub294 \uc77c\uc774 \uae30\uc5c5\uc758 \uacbd\uc7c1\ub825\uacfc \uc5f0\uacb0\ub418\uc5c8\ub2e4\ub294 \uc810\uc774\ub2e4. \ubb34\uac70\uc6b4 \uac83\uc744 \uba40\ub9ac \ub098\ub974\uac70\ub098 \uc790\uc8fc \ubab8\uc744 \uc219\uc774\ub294 \uc77c\uc744 \uc904\uc774\ub294 \uac83\uc740 \ubd84\uba85 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\ub2e4. \ubc18\uba74 \uac19\uc740 \uc9e7\uc740 \ub3d9\uc791\uc744 \uc624\ub798 \ubc18\ubcf5\ud558\uace0 \uc815\ud574\uc9c4 \uc18d\ub3c4\uc5d0 \ub9de\ucd94\ub294 \ubd80\ub2f4\ub3c4 \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub2e4. \uc0dd\uc0b0\ub7c9\uc774 \ub298\uc5c8\ub2e4\ub294 \uc218\uce58\ub9cc\uc73c\ub85c \uc77c\ud558\ub294 \uc0ac\ub78c\uc758 \uacbd\ud5d8\uc774 \ubaa8\ub450 \uc88b\uc544\uc84c\ub2e4\uace0 \ud310\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc774 \uc9c8\ubb38\uc740 \ud68c\uace0\ub85d\uc744 \uc77d\ub294 \ud0dc\ub3c4\uc640\ub3c4 \uc5f0\uacb0\ub41c\ub2e4. \uacbd\uc601\uc790\ub294 \uc790\uc2e0\uc774 \uc870\uc9c1\ud55c \uc0dd\uc0b0\uc758 \ud6a8\uc728\uc744 \uc55e\uc138\uc6b4\ub2e4. \uadf8 \uc124\uba85\uc740 \uc911\uc694\ud55c \uc790\ub8cc\uc774\uc9c0\ub9cc \ub178\ub3d9\uc790 \ubaa8\ub450\uc758 \ubaa9\uc18c\ub9ac\ub97c \ub300\uc2e0\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud68c\uace0\ub85d\uc5d0 \uc801\ud78c \uc2dc\uac04 \ub2e8\ucd95\uc740 \uc800\uc790\uc758 \ubcf4\uace0\ub85c \uc77d\uace0, \uac70\uae30\uc11c \uace7\ubc14\ub85c \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \ub9cc\uc871\uc744 \ucd94\ub860\ud558\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \uc790\ub3d9\ucc28\uac00 \uc904\uc9c0\uc5b4 \uc788\ub294 \uc61b \uacf5\uc7a5 \uc0ac\uc9c4\uc744 \ubcf4\uba74 \uc644\uc131\ud488\ubcf4\ub2e4 \uadf8 \uc0ac\uc774\ub97c \uc0b4\ud3b4\ubcf4\uc790. \ubd80\ud488\uc774 \uc5b4\ub290 \ucabd\uc5d0\uc11c \ub4e4\uc5b4\uc624\uace0 \uc0ac\ub78c\uc774 \uc5b4\ub514\uc5d0 \uc11c \uc788\ub294\uc9c0, \ub2e4\uc74c \uc0ac\ub78c\uc5d0\uac8c \ubb34\uc5c7\uc744 \ub118\uae30\ub294\uc9c0 \uc0dd\uac01\ud558\uba74 \uc870\ub9bd\ub77c\uc778\uc774 \ucd94\uc0c1\uc801\uc778 \uc6a9\uc5b4\uc5d0\uc11c \uad6c\uccb4\uc801\uc778 \uacf5\uac04\uc73c\ub85c \ubc14\ub010\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \uc774 \uc6d0\ub9ac\ub97c \ub5a0\uc62c\ub9ac\uae30 \uc704\ud55c AI \uc0bd\ud654\ub2e4. \ud2b9\uc815 \uacf5\uc7a5\uc758 \uc2e4\uc81c \uc124\ube44\ub97c \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc2e4\uc81c \uacf5\uc815\uc758 \uc815\ud655\ud55c \ubaa8\uc591\uacfc \uc5ec\uae30\uc11c \uc124\uba85\ud55c \uc0dd\uc0b0 \uc6d0\ub9ac\ub97c \uad6c\ubcc4\ud558\uba74 \uadf8\ub9bc\uc744 \ud3b8\ud558\uac8c \ubcf4\uba74\uc11c\ub3c4 \uc0c1\uc0c1\uc73c\ub85c \ucc44\uc6b4 \uc7a5\uba74\uc744 \uc0ac\ub8cc\uc640 \ud63c\ub3d9\ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \ud3ec\ub4dc\uc758 \uc774\uc57c\uae30\ub294 \uc88b\uc740 \ubb3c\uac74\uc744 \ub9cc\ub4dc\ub294 \uc77c\uc774 \uadf8 \ubb3c\uac74\uc758 \uc124\uacc4\ub3c4 \uc548\uc5d0\uc11c\ub9cc \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uac19\uc740 \ubd80\ud488\uc774\ub77c\ub3c4 \uc5b4\ub514\uc5d0 \ub193\uace0 \uc5b4\ub5a4 \uc21c\uc11c\ub85c \ub118\uae30\ub294\uc9c0\uc5d0 \ub530\ub77c \uacf5\uc7a5 \uc804\uccb4\uc758 \ud558\ub8e8\uac00 \ub2ec\ub77c\uc84c\ub2e4. \ub208\uc5d0 \uc798 \ub744\uc9c0 \uc54a\ub358 \uc774\ub3d9\uc774 \uc911\uc694\ud55c \uc124\uacc4\uc758 \ub300\uc0c1\uc774 \ub41c \uac83\uc774\ub2e4. \ub3d9\uc2dc\uc5d0 \ud6a8\uc728\uc744 \ub204\uad6c\uc758 \uad00\uc810\uc5d0\uc11c \ud310\ub2e8\ud560\uc9c0\ub3c4 \ubb3b\uac8c \ud55c\ub2e4. \ub354 \ub9ce\uc740 \uc790\ub3d9\ucc28\uc640 \ub354 \uc9e7\uc740 \uc791\uc5c5 \uc2dc\uac04, \ubc18\ubcf5\ub418\ub294 \ub178\ub3d9\uc758 \uacbd\ud5d8\uc740 \ud55c \uc7a5\uba74 \uc548\uc5d0 \ud568\uaed8 \uc788\ub2e4. \uc870\ub9bd\ub77c\uc778\uc744 \uc54c\uace0 \ub098\uba74 \uc624\ub798\ub41c \uc790\ub3d9\ucc28 \ud55c \ub300\uc5d0\uc11c\ub3c4 \uc5d4\uc9c4\ubfd0 \uc544\ub2c8\ub77c \uc218\ub9ce\uc740 \uc0ac\ub78c\uc758 \uc790\ub9ac\uc640 \uc6c0\uc9c1\uc784\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4."}, {"id": "harley-davidson-riders-and-community", "title": "\ud560\ub9ac\ub370\uc774\ube44\uc2a8 \u2014 \uc624\ud1a0\ubc14\uc774 \ub2e4\uc74c\uc5d0\ub294 \ubb34\uc5c7\uc744 \ud314\uae4c", "summary": "\uc18c\uc720\uc790 \ubaa8\uc784\uacfc \ucd08\ubcf4\uc790\ub97c \ub3d5\ub294 \uacbd\ud5d8\uc744 \ud1b5\ud574 \uc81c\ud488 \uc774\ud6c4\uc758 \uad00\uacc4\uac00 \ube0c\ub79c\ub4dc\ub97c \ub9cc\ub4dc\ub294 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\ube0c\ub79c\ub4dc\uc640 \uc18c\ube44", "categories": ["industry"], "url": "stories/harley-davidson-riders-and-community/index.html", "image": "../media/harley-davidson-riders-and-community.png", "alt": "\uae38\uac00\uc5d0 \uc138\uc6b4 \uc77c\ubc18\uc801\uc778 \uc624\ud1a0\ubc14\uc774 \uc606\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc774 \uc9c0\ub3c4\ub97c \ubcf4\uba70 \uacbd\ud5d8\uc744 \ub098\ub204\ub294 \uc0bd\ud654.", "text": "\ud560\ub9ac\ub370\uc774\ube44\uc2a8 \u2014 \uc624\ud1a0\ubc14\uc774 \ub2e4\uc74c\uc5d0\ub294 \ubb34\uc5c7\uc744 \ud314\uae4c \ubb3c\uac74\uc744 \uc0b0 \ub4a4\uc5d0 \uc2dc\uc791\ub418\ub294 \uc0ac\ub78c\ub4e4\uc758 \uad00\uacc4 \uc18c\uc720\uc790 \ubaa8\uc784\uacfc \ucd08\ubcf4\uc790\ub97c \ub3d5\ub294 \uacbd\ud5d8\uc744 \ud1b5\ud574 \uc81c\ud488 \uc774\ud6c4\uc758 \uad00\uacc4\uac00 \ube0c\ub79c\ub4dc\ub97c \ub9cc\ub4dc\ub294 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ube0c\ub79c\ub4dc\uc640 \uc18c\ube44 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \uac19\uc740 \uc624\ud1a0\ubc14\uc774\ub97c \ud0c0\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc8fc\ub9d0 \uc544\uce68\uc5d0 \ubaa8\uc778\ub2e4. \ucc98\uc74c \ub9cc\ub09c \uc0ac\uc774\uc778\ub370\ub3c4 \uc7a5\ube44\uc640 \uae38 \uc774\uc57c\uae30\uac00 \uace7 \uc774\uc5b4\uc9c4\ub2e4. \ud55c \uc0ac\ub78c\uc740 \uba3c \uac70\ub9ac\ub97c \ub2ec\ub9b4 \uc900\ube44\ub97c \ubb3b\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc740 \uc790\uc2e0\uc758 \uacbd\ud5d8\uc744 \ub4e4\ub824\uc900\ub2e4. \uc774\ub7f0 \uac00\uc0c1\uc758 \uc7a5\uba74\uc744 \ub5a0\uc62c\ub9ac\uba74 \uc81c\ud488\uc744 \uc0b0 \ub2e4\uc74c\uc5d0 \ubb34\uc5c7\uc774 \uc2dc\uc791\ub418\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \ud560\ub9ac\ub370\uc774\ube44\uc2a8\uc740 \uacbd\uc601 \uad50\uc7ac\uc5d0\uc11c \uc774\ub7f0 \uacbd\ud5d8\uacfc \uad00\uacc4\ub97c \uc124\uba85\ud558\ub294 \uc0ac\ub840\ub85c \ub4f1\uc7a5\ud55c\ub2e4. \uc5d4\uc9c4\uacfc \ubc14\ud034\ub9cc\uc774 \uc544\ub2c8\ub77c \uc18c\uc720\uc790\uac00 \ub2e4\ub978 \uc0ac\ub78c\uacfc \ub098\ub204\ub294 \uc2dc\uac04\uc774 \ube0c\ub79c\ub4dc\uc758 \uc77c\ubd80\uac00 \ub418\ub294 \uac83\uc774\ub2e4. \uc624\ud1a0\ubc14\uc774\ub97c \uc798 \ubaa8\ub974\ub294 \ub3c5\uc790\ub3c4 \ubb3c\uac74\uacfc \uacf5\ub3d9\uccb4\uc758 \uad00\uacc4\ub85c \uc77d\uc5b4 \ubcfc \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 \ud560\ub9ac\ub370\uc774\ube44\uc2a8\uc758 \uace0\uac1d\ub4e4\uc774 \ubaa8\ub450 \uac19\uc740 \uacbd\ud5d8\uc744 \uc6d0\ud558\uc9c0 \uc54a\ub294\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc5b4\ub5a4 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc77c\uc0c1\uc5d0\uc11c \ubc97\uc5b4\ub098\ub294 \uc5ec\ud589\uc774\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc774\ub3d9 \uc218\ub2e8\uc774\ub098 \uc0dd\ud65c \ubc29\uc2dd\uc758 \uc77c\ubd80\ub2e4. \ud558\ub098\uc758 \uc0c1\ud45c\ub97c \uc120\ud0dd\ud574\ub3c4 \uadf8 \ubb3c\uac74\uc5d0 \uae30\ub300\ud558\ub294 \uac83\uc740 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uad11\uace0\uc5d0\uc11c \uc790\uc8fc \ubcf4\uc774\ub294 \uc790\uc720\ub77c\ub294 \ub2e8\uc5b4\ub3c4 \ubaa8\ub4e0 \uc0ac\ub78c\uc5d0\uac8c \uac19\uc740 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud63c\uc790 \uc870\uc6a9\ud788 \ub2ec\ub9ac\ub294 \uc77c\uacfc \uc0ac\ub78c\ub4e4\uacfc \ud568\uaed8 \ub5a0\ub098\ub294 \uc77c\uc740 \ub2e4\ub978 \uc990\uac70\uc6c0\uc774\ub2e4. \uae30\uc5c5\uc774 \uc81c\uc2dc\ud55c \uc774\ubbf8\uc9c0\uc640 \uc18c\uc720\uc790\uac00 \uc2e4\uc81c\ub85c \ub9cc\ub4dc\ub294 \uacbd\ud5d8\uc744 \ub098\ub204\uc5b4 \ubcf4\uba74 \uace0\uac1d\uc740 \ub2e8\uc21c\ud788 \uad11\uace0\ub97c \ub530\ub77c \ud558\ub294 \uc874\uc7ac\ub85c\ub9cc \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uad50\uc7ac\ub294 \uc77c\ubd80 \ud310\ub9e4\uc810\uc5d0\uc11c \ubd80\ud488\uacfc \uc561\uc138\uc11c\ub9ac\ub97c \uace8\ub77c \ucc28\ub97c \uafb8\ubbf8\ub294 \uc77c\uc744 \ub3d5\ub294 \uc804\ubb38 \uc0c1\ub2f4\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc0c1\ud45c\uac00 \uac19\uc544\ub3c4 \uc18c\uc720\uc790\uac00 \uc138\ubd80\ub97c \ubc14\uafb8\uba70 \uc790\uae30 \ucde8\ud5a5\uc744 \ub4dc\ub7ec\ub0bc \uc218 \uc788\ub294 \uac83\uc774\ub2e4. \uc758\ubcf5\uacfc \uc7a5\ube44 \uac19\uc740 \uc8fc\ubcc0 \uc0c1\ud488\ub3c4 \uc774 \uacbd\ud5d8\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc774\uac83\uc740 \ud2b9\uc815\ud55c \uac1c\uc870\ub97c \uad8c\ud558\uac70\ub098 \ubaa8\ub4e0 \ud310\ub9e4\uc810\uc758 \ud604\uc7ac \uc11c\ube44\uc2a4\ub97c \uc548\ub0b4\ud558\ub294 \ub9d0\uc740 \uc544\ub2c8\ub2e4. \uc6d0\ub798\uc758 \uc81c\ud488\uacfc \ub098\uc5d0\uac8c \ub9de\ucd94\ub294 \uacfc\uc815\uc774 \ud568\uaed8 \uc0c1\ud488\uc774 \ub420 \uc218 \uc788\ub2e4\ub294 \uc0ac\ub840\ub2e4. \uac19\uc740 \uae30\ub2a5\uc744 \uac00\uc9c4 \ubb3c\uac74 \uc0ac\uc774\uc5d0\uc11c\ub3c4 \ub0b4\uac00 \ucc38\uc5ec\ud574 \uc120\ud0dd\ud588\ub2e4\ub294 \ub290\ub08c\uc740 \ub2e4\ub978 \uc885\ub958\uc758 \uc560\ucc29\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \ud560\ub9ac \uc624\ub108\uc2a4 \uadf8\ub8f9, \ud754\ud788 H.O.G.\ub77c\uace0 \ubd80\ub974\ub294 \uc18c\uc720\uc790 \ubaa8\uc784\ub3c4 \uad50\uc7ac\uc5d0 \uc18c\uac1c\ub41c\ub2e4. \ud589\uc0ac\uc640 \ud568\uaed8 \ub2ec\ub9ac\ub294 \ubaa8\uc784\uc740 \uc624\ud1a0\ubc14\uc774\ub97c \uc0b0 \uc0ac\ub78c\uc774 \ub2e4\ub978 \uc18c\uc720\uc790\ub97c \ub9cc\ub0a0 \uae30\ud68c\ub97c \uc900\ub2e4. \ub9e4\uc7a5\uacfc \uc9d1\uc744 \uc624\uac00\ub294 \uad00\uacc4 \ubc16\uc5d0 \uc0c8\ub85c\uc6b4 \uc7a5\uc18c\uac00 \ub9cc\ub4e4\uc5b4\uc9c0\ub294 \uc148\uc774\ub2e4. \ub2e4\ub9cc \ud68c\uc6d0\uc774\ub77c\ub294 \uc774\ub984\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uc5b8\uc81c\ub098 \uac19\uc740 \uc0dd\uac01\uc744 \uac16\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ucc38\uc5ec\ud558\ub294 \uc815\ub3c4\uc640 \uc5ec\ud589\uc758 \ucde8\ud5a5\ub3c4 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uacf5\ub3d9\uccb4\uac00 \uc788\ub2e4\ub294 \ub9d0\uc740 \uac1c\uc778\ucc28\uac00 \uc0ac\ub77c\uc84c\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \ub2e4\uc591\ud55c \uc0ac\ub78c\uc774 \uc81c\ud488 \ud558\ub098\ub97c \uacf5\ud1b5\uc758 \ub300\ud654 \uc18c\uc7ac\ub85c \uc0bc\uc744 \uc218 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c \uc77d\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uad50\uc7ac\uac00 \ud2b9\ud788 \uac15\uc870\ud558\ub294 \uac83\uc740 \uacbd\ud5d8 \ub9ce\uc740 \uc18c\uc720\uc790\uac00 \uc0c8 \uc18c\uc720\uc790\ub97c \ub3d5\ub294 \uc5ed\ud560\uc774\ub2e4. \ub354 \uae34 \uc5ec\ud589\uc744 \uc5b4\ub5bb\uac8c \uc900\ube44\ud560\uc9c0, \uc9d0\uc744 \uc5b4\ub5bb\uac8c \ucc59\uae38\uc9c0 \uac19\uc740 \uacbd\ud5d8\uc744 \ub098\ub208\ub2e4. \uc81c\ud488 \uc124\uba85\uc11c\uac00 \ub2f4\uae30 \uc5b4\ub824\uc6b4 \uc0dd\ud65c\uc758 \uc9c0\uc2dd\uc774 \uc0ac\ub78c \uc0ac\uc774\ub97c \ud1b5\ud574 \uc804\ub2ec\ub418\ub294 \uac83\uc774\ub2e4. \uc774\ub54c \uc548\ub0b4\uc790\ub294 \ud68c\uc0ac \uc9c1\uc6d0\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uc790\uc2e0\uc774 \ud574 \ubcf8 \uc77c\uc744 \ubc14\ud0d5\uc73c\ub85c \uc870\uc5b8\ud558\ub294 \ub2e4\ub978 \uc774\uc6a9\uc790\ub2e4. \ubb3c\ub860 \uac1c\uc778\uc758 \uacbd\ud5d8\uc774 \uacf5\uc2dd \uc548\uc804 \uc9c0\uce68\uc774\ub098 \uc804\ubb38 \uad50\uc721\uc744 \ub300\uc2e0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \ubb3c\uac74\uc744 \uc0ac\uc6a9\ud558\ub294 \ub370 \ud544\uc694\ud55c \uc815\ubcf4\uac00 \ud310\ub9e4 \uc2dc\uc810\uc758 \uc124\uba85\ub9cc\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc740 \ubd84\uba85\ud574\uc9c4\ub2e4. \ub0af\uc120 \uad11\uace0\uc758 \uc88b\uc740 \ub9d0\ubcf4\ub2e4 \uc544\ub294 \uc0ac\ub78c\uc758 \uc0ac\uc6a9 \uacbd\ud5d8\uc5d0 \ub9c8\uc74c\uc774 \uc6c0\uc9c1\uc77c \ub54c\uac00 \uc788\ub2e4. \uadf8 \uc0ac\ub78c\uc758 \ucde8\ud5a5\uacfc \uc0c1\ud669\uc744 \uc54c\uba74 \ub0b4 \uacbd\uc6b0\uc640 \ube44\uad50\ud558\uae30\ub3c4 \uc27d\ub2e4. \uad50\uc7ac\ub294 \uc18c\uc720\uc790\ub4e4\uc758 \uc774\ub7f0 \ub300\ud654\uc640 \ucd94\ucc9c\uc774 \ube0c\ub79c\ub4dc\uc758 \uc911\uc694\ud55c \uc804\ub2ec \uacbd\ub85c\uac00 \ub41c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc774\uc6a9\uc790\uc758 \ub9d0\uc774 \ubaa8\ub450 \uac1d\uad00\uc801\uc774\uac70\ub098 \ubaa8\ub4e0 \uad6c\ub9e4\uc790\uc5d0\uac8c \ub9de\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc88b\uc544\ud558\ub294 \ube0c\ub79c\ub4dc\uc5d0\ub294 \uc560\uc815\uacfc \uae30\ub300\uac00 \ud568\uaed8 \uc791\uc6a9\ud55c\ub2e4. \uce5c\uadfc\ud55c \ucd94\ucc9c\uc744 \ub4e3\ub294 \uc77c\uacfc \uc81c\ud488\uc758 \uc870\uac74\uc744 \ubcc4\ub3c4\ub85c \ud655\uc778\ud558\ub294 \uc77c\uc740 \ud568\uaed8 \ud560 \uc218 \uc788\ub2e4. \uacbd\ud5d8\uc774 \uc124\ub4dd\ub825\uc744 \uac16\ub294 \uc774\uc720\ub97c \uc774\ud574\ud558\ub418 \uadf8\uac83\uc744 \ubcf4\uc99d\uc11c\ucc98\ub7fc \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud55c \ubc88 \uad6c\ub9e4\uac00 \uc774\ub8e8\uc5b4\uc84c\ub2e4\uace0 \uacf5\ub3d9\uccb4\uac00 \uc800\uc808\ub85c \uc624\ub798 \uc774\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \ub2e4\uc2dc \ub9cc\ub098\uace0 \uc815\ubcf4\ub97c \ub098\ub20c \uc790\ub9ac\uac00 \ud544\uc694\ud558\ub2e4. \uad50\uc7ac\ub294 \ud589\uc0ac\uc640 \uc628\ub77c\uc778 \ubaa8\uc784, \uad00\ub828 \uac04\ud589\ubb3c\uc774 \uacbd\ud5d8\uc744 \uc774\uc5b4 \uc8fc\ub294 \ud1b5\ub85c\ub77c\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc81c\ud488 \ubc14\uae65\uc5d0\ub3c4 \uad00\uacc4\ub97c \uc720\uc9c0\ud558\ub294 \uc77c\uc774 \uc874\uc7ac\ud55c\ub2e4. \uc774\ub7f0 \ud65c\ub3d9\uc5d0\ub294 \uc2dc\uac04\uacfc \ube44\uc6a9\uc774 \ub4e0\ub2e4. \ub9e4\ub825\uc801\uc778 \uad6c\ud638\ub97c \ubd99\uc774\ub294 \uc77c\uacfc \uc2e4\uc81c\ub85c \uc0c8 \uc774\uc6a9\uc790\uac00 \ud3b8\ud558\uac8c \ucc38\uc5ec\ud560 \uc218 \uc788\ub3c4\ub85d \ub3d5\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \ube0c\ub79c\ub4dc\ub97c \uc88b\uc544\ud558\ub294 \uc0ac\ub78c\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uae30\uc5c5\uc758 \ubaa8\ub4e0 \ubb38\uc81c\uac00 \ud574\uacb0\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc88b\uc740 \uad00\uacc4\ub294 \uacc4\uc18d \ub3cc\ubcf4\uc544\uc57c \ud558\ub294 \ud65c\ub3d9\uc5d0 \uac00\uae5d\ub2e4. \uc624\ud1a0\ubc14\uc774\uc758 \ub0ad\ub9cc\uc740 \uc0ac\uc9c4\uacfc \uc774\uc57c\uae30\ub85c \uc804\ud574\uc9c0\uae30 \uc88b\ub2e4. \ud558\uc9c0\ub9cc \uc2e4\uc81c \uc120\ud0dd\uc5d0\ub294 \uc548\uc804\uacfc \ube44\uc6a9, \uc774\uc6a9 \ud658\uacbd\uc774 \ud568\uaed8 \ub4e4\uc5b4\uac04\ub2e4. \uc774\ubc88 \uc6d0\uace0\ub294 \uad50\uc7ac\uac00 \uc18c\uac1c\ud55c \ube0c\ub79c\ub4dc \uacf5\ub3d9\uccb4\uc758 \uc0ac\ub840\ub97c \ub2e4\ub8e8\uba70 \ud2b9\uc815 \ubaa8\ub378\uc758 \uc131\ub2a5\uc774\ub098 \ud604\uc7ac \ud310\ub9e4 \uc2e4\uc801\uc744 \ud3c9\uac00\ud55c \uae00\uc740 \uc544\ub2c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub3c4 \uc77c\ubc18\uc801\uc778 \ub77c\uc774\ub354\ub4e4\uc758 \ub9cc\ub0a8\uc744 \ud45c\ud604\ud588\ub2e4. \uc2e4\uc81c \ubaa8\uc784\uc758 \ucc38\uac00\uc790\ub098 \ud560\ub9ac\ub370\uc774\ube44\uc2a8\uc758 \ud2b9\uc815 \ucc28\uc885\uc744 \uc7ac\ud604\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc774\ubbf8\uc9c0\uc5d0\uc11c\ub294 \uc5ec\ud589\uc744 \ub098\ub204\ub294 \ubd84\uc704\uae30\ub97c \ubcf4\uace0, \uae30\uc5c5\uc758 \uc0ac\ub840\uc5d0\uc11c\ub294 \ubb3c\uac74 \uc774\ud6c4\uc758 \uad00\uacc4\ub77c\ub294 \uc9c8\ubb38\uc744 \uc77d\uc73c\uba74 \ub41c\ub2e4. \ud560\ub9ac\ub370\uc774\ube44\uc2a8\uc758 \uc0ac\ub840\uc5d0\uc11c \ud765\ubbf8\ub85c\uc6b4 \uac83\uc740 \uc624\ud1a0\ubc14\uc774\ub97c \ub118\uaca8\ubc1b\uc740 \ub4a4\uc758 \uc2dc\uac04\uc774\ub2e4. \uc0ac\uc6a9\ud558\ub294 \ubc95\uc744 \ubc30\uc6b0\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc744 \ub9cc\ub098\uba70 \uc790\uae30 \uacbd\ud5d8\uc744 \ub9d0\ud558\uac8c \ub41c\ub2e4. \ubb3c\uac74\uc774 \ub300\ud654\uc758 \uc2dc\uc791\uc810\uc774 \ub418\uace0 \uadf8 \ub300\ud654\uac00 \ube0c\ub79c\ub4dc\uc758 \uc758\ubbf8\ub97c \ub2e4\uc2dc \ub9cc\ub4e0\ub2e4. \ub2e4\uc74c\uc5d0 \uc5b4\ub5a4 \ubb3c\uac74\uc744 \uc624\ub798 \uc88b\uc544\ud558\ub294 \uc0ac\ub78c\ub4e4\uc744 \ub9cc\ub098\uba74 \ubb34\uc5c7\uc774 \uc88b\uc740\uc9c0\ubfd0 \uc544\ub2c8\ub77c \ub204\uad6c\uc640 \ubb34\uc5c7\uc744 \ub098\ub204\ub294\uc9c0\ub3c4 \ubb3c\uc5b4\ubcf4\uc790. \uae30\ub2a5\uacfc \uac00\uaca9 \ubc16\uc758 \uc774\uc57c\uae30\uac00 \ub098\uc62c \uc218 \uc788\ub2e4. \uae30\uc5c5\uc774 \ub9cc\ub4dc\ub294 \uac83\uc740 \uc81c\ud488\uc774\uc9c0\ub9cc \uadf8 \uc81c\ud488\uc774 \uc0b4\uc544\uac00\ub294 \uc138\uacc4\ub294 \uc774\uc6a9\uc790\ub4e4\uc758 \uad00\uacc4 \uc18d\uc5d0\uc11c\ub3c4 \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4."}, {"id": "kodak-camera-and-lessons", "title": "\ucf54\ub2e5\uc740 \uce74\uba54\ub77c\uc640 \ud568\uaed8 \ubb34\uc5c7\uc744 \ud314\uc558\uc744\uae4c", "summary": "\ube0c\ub77c\uc6b0\ub2c8 \uce74\uba54\ub77c\uc640 \uc548\ub0b4 \ucc45\uc790, \uc7a1\uc9c0\ub97c \ud1b5\ud574 \uc0ac\uc9c4\uc744 \uc77c\uc0c1\uc758 \ucde8\ubbf8\ub85c \ub9cc\ub4e4\ub824\ub358 \uae30\uc5c5\uc758 \ubc29\uc2dd\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\ube0c\ub79c\ub4dc\uc640 \uc18c\ube44", "categories": ["industry"], "url": "stories/kodak-camera-and-lessons/index.html", "image": "../media/kodak-camera-and-lessons.jpg", "alt": "1914\ub144 \ucf54\ub2e5 \uce74\ud0c8\ub85c\uadf8\uc758 No. 1 \ube0c\ub77c\uc6b0\ub2c8 \uc0c1\uc790\ud615 \uce74\uba54\ub77c \uc2e4\uc81c \ub3c4\ud310.", "text": "\ucf54\ub2e5\uc740 \uce74\uba54\ub77c\uc640 \ud568\uaed8 \ubb34\uc5c7\uc744 \ud314\uc558\uc744\uae4c 1914\ub144 \uce74\ud0c8\ub85c\uadf8\uc5d0\uc11c \ub9cc\ub098\ub294 \uc0ac\uc9c4\uc744 \ubc30\uc6b0\ub294 \uc0ac\ub78c\ub4e4 \ube0c\ub77c\uc6b0\ub2c8 \uce74\uba54\ub77c\uc640 \uc548\ub0b4 \ucc45\uc790, \uc7a1\uc9c0\ub97c \ud1b5\ud574 \uc0ac\uc9c4\uc744 \uc77c\uc0c1\uc758 \ucde8\ubbf8\ub85c \ub9cc\ub4e4\ub824\ub358 \uae30\uc5c5\uc758 \ubc29\uc2dd\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ube0c\ub79c\ub4dc\uc640 \uc18c\ube44 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \uce74\uba54\ub77c\ub97c \uc0c0\ub2e4\uace0 \uace7\ubc14\ub85c \uc88b\uc740 \uc0ac\uc9c4\uc744 \ucc0d\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc544\uc774\uac00 \uc6c0\uc9c1\uc774\uace0, \ud587\ube5b\uc740 \ub108\ubb34 \uac15\ud558\uace0, \ud070 \uac74\ubb3c\uc740 \uc0ac\uc9c4 \uc548\uc5d0 \ub2e4 \ub4e4\uc5b4\uc624\uc9c0 \uc54a\ub294\ub2e4. \uc624\ub298\ub0a0\uc5d0\ub3c4 \uc775\uc219\ud55c \uc774 \ub09c\uac10\ud568\uc744 1914\ub144 \ucf54\ub2e5\uc758 \uce74\ud0c8\ub85c\uadf8\uac00 \uae38\uac8c \uc774\uc57c\uae30\ud55c\ub2e4. \ubb3c\uac74 \ubaa9\ub85d\uc758 \uccab\uba38\ub9ac\uc5d0 \ub193\uc778 \ub9d0\uc740 \ub73b\ubc16\uc5d0\ub3c4 \ub2e8\uc21c\ud588\ub2e4. \ub354 \uc27d\uac8c \ub9cc\ub4e4\ub77c\ub294 \uac83\uc774\uc5c8\ub2e4. \u300aKodaks and Kodak Supplies, 1914\u300b\ub294 \ud310\ub9e4\ub97c \uc704\ud55c \uc778\uc1c4\ubb3c\uc774\ub2e4. \uc81c\ud488\uc758 \uc7a5\uc810\uc740 \uac15\uc870\ud558\uace0 \uc57d\uc810\uc740 \ub35c \ub9d0\ud560 \uc218 \uc788\ub2e4. \uadf8\ub807\uc9c0\ub9cc \uc5b4\ub5a4 \uc0ac\ub78c\uc744 \uace0\uac1d\uc73c\ub85c \uc0c1\uc0c1\ud588\ub294\uc9c0, \uce74\uba54\ub77c\ub97c \uc0b0 \ub4a4 \ubb34\uc5c7\uc744 \ub3c4\uc640\uc8fc\uaca0\ub2e4\uace0 \uc57d\uc18d\ud588\ub294\uc9c0\ub97c \uc77d\uae30\uc5d0\ub294 \ud765\ubbf8\ub85c\uc6b4 \uc790\ub8cc\ub2e4. \uce74\ud0c8\ub85c\uadf8\ub294 \ucf54\ub2e5\uc774 \uc0ac\uc9c4\uc744 \uc27d\uac8c \ub9cc\ub4dc\ub294 \uae30\uad6c\ubfd0 \uc544\ub2c8\ub77c \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uc0ac\uc9c4 \ucc0d\ub294 \ubc29\ubc95\uc744 \uc124\uba85\ud574 \uc654\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uccab \ucf54\ub2e5\uc774 \ub098\uc628 1888\ub144\uc758 \uc124\uba85\uc11c\ub3c4 \ub2e8\uc21c\ud55c \uae30\uacc4 \uc870\uc791 \uc548\ub0b4\ub97c \ub118\uc5b4 \uac74\ubb3c\uacfc \uc5b4\ub9b0\uc544\uc774\ub97c \uc5b4\ub5bb\uac8c \ucc0d\uc744\uc9c0 \ub2e4\ub8e8\uc5c8\ub2e4\ub294 \uac83\uc774 \ud68c\uc0ac \uce21\uc758 \uc124\uba85\uc774\ub2e4. \uc5ec\uae30\uc5d0\ub294 \uc0c8\ub85c\uc6b4 \uace0\uac1d\uc5d0 \ub300\ud55c \uc0dd\uac01\uc774 \ub2f4\uaca8 \uc788\ub2e4. \uc774\ubbf8 \uc0ac\uc9c4\uc744 \uc798 \uc544\ub294 \uc804\ubb38\uac00\uc5d0\uac8c\ub9cc \ubb3c\uac74\uc744 \ud314\ub824\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc88b\uc740 \uc7a5\uba74\uc744 \ub0a8\uae30\uace0 \uc2f6\uc9c0\ub9cc \ub178\ucd9c \uc2dc\uac04\uc774\ub098 \ube5b\uc744 \uc798 \ubaa8\ub974\ub294 \uc0ac\ub78c\ub3c4 \uace0\uac1d\uc774 \ub420 \uc218 \uc788\ub2e4. \uae30\uc220\uc758 \uc0ac\uc6a9\uc790\ub97c \ub113\ud788\ub824\uba74 \uae30\uacc4\uc640 \ud568\uaed8 \ubc30\uc6b8 \uc218 \uc788\ub294 \uae38\ub3c4 \ub9c8\ub828\ud574\uc57c \ud588\ub2e4. \uc2e4\uc81c \ub3c4\ud310\uc5d0 \ubcf4\uc774\ub294 No. 1 \ube0c\ub77c\uc6b0\ub2c8\ub294 \ud654\ub824\ud55c \uc7a5\ube44\ubcf4\ub2e4 \uc190\uc5d0 \ub4e4\uace0 \ub2e4\ub2d0 \uc218 \uc788\ub294 \uc0c1\uc790\uc5d0 \uac00\uae5d\ub2e4. \uce74\ud0c8\ub85c\uadf8\ub294 \uc774 \uc81c\ud488\uc774 \uc6d0\ub798 \uc5b4\ub9b0\uc774\ub97c \uc5fc\ub450\uc5d0 \ub450\uc5c8\uc9c0\ub9cc \uc5b4\ub978\ub3c4 \uc0ac\uc6a9\ud558\uac8c \ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc774\uac83 \uc5ed\uc2dc \ub2f9\uc2dc \ud310\ub9e4\uc790\uac00 \ub0b4\uc138\uc6b4 \uc81c\ud488 \uc774\uc57c\uae30\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \uae30\ub2a5\uc744 \ub9ce\uc774 \ub123\ub294 \uac83\ub9cc\uc774 \uc81c\ud488\uc758 \ub9e4\ub825\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc7a5\uce58\ub97c \ub0af\uc124\uc5b4\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ubb34\uc5c7\uc744 \ud574\uc57c \ud560\uc9c0 \uc27d\uac8c \uc54c \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \ube44\uad50\uc801 \ub2e8\uc21c\ud55c \uce74\uba54\ub77c\ub85c \uc77c\ub2e8 \uc0ac\uc9c4\uc744 \ucc0d\uc5b4 \ubcf4\ub294 \uacbd\ud5d8\uc740, \uc0ac\uc9c4\uc744 \ud2b9\ubcc4\ud55c \uc804\ubb38\uac00\uc758 \uc791\uc5c5\uc5d0\uc11c \uac00\uae4c\uc6b4 \uc0dd\ud65c\uc758 \ud65c\ub3d9\uc73c\ub85c \uc62e\uae30\ub294 \ud55c \ubc29\ubc95\uc774\uc5c8\ub2e4. \uc774 \ud310\ubcf8\uc5d0\ub294 No. 1 \ube0c\ub77c\uc6b0\ub2c8 \ubcf8\uccb4\uc758 \uac00\uaca9\uc774 1\ub2ec\ub7ec\ub85c \uc801\ud600 \uc788\ub2e4. \uc606\uc5d0\ub294 \ud734\ub300\uc6a9 \ucf00\uc774\uc2a4\uc640 \ubcc4\ub3c4 \ud30c\uc778\ub354 \ub4f1\uc758 \uac00\uaca9\ub3c4 \ubcf4\uc778\ub2e4. \uc624\ub298\uc758 \uac00\uaca9 \uac10\uac01\uc73c\ub85c \uc544\uc8fc \uc2f8\ub2e4\uace0 \ub2e8\uc815\ud558\uae30 \uc804\uc5d0, \uadf8 \uc22b\uc790\uac00 1914\ub144 \uce74\ud0c8\ub85c\uadf8\uc758 \ud45c\uc2dc \uac00\uaca9\uc774\ub77c\ub294 \uc0ac\uc2e4\uc744 \uba3c\uc800 \ubd99\uc7a1\uc544\uc57c \ud55c\ub2e4. \uad6c\uc785 \ube44\uc6a9\uc5d0\ub294 \ubcf8\uccb4\ub9cc \uc788\ub294 \uac83\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ud544\ub984\uacfc \ud604\uc0c1, \uc778\ud654\uc5d0 \ub4e4\uc5b4\uac00\ub294 \ube44\uc6a9\ub3c4 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \uc774 \uc790\ub8cc\ub294 \ud1a0\ub860\ud1a0\uc758 \uc8fc\uc18c\ub97c \uc0ac\uc6a9\ud558\ub294 \ud310\ubcf8\uc774\ubbc0\ub85c \ubaa8\ub4e0 \ub098\ub77c\uc5d0\uc11c \uac19\uc740 \uc870\uac74\uc73c\ub85c \uc0b4 \uc218 \uc788\uc5c8\ub2e4\uace0 \ub113\ud600 \ub9d0\ud560 \uc218\ub3c4 \uc5c6\ub2e4. \uc791\uc740 \uac00\uaca9\ud45c \ud558\ub098\uc5d0\ub3c4 \uc2dc\ub300\uc640 \ud310\ub9e4 \uc9c0\uc5ed\uc774\ub77c\ub294 \ubb38\ub9e5\uc774 \ubd99\ub294\ub2e4. \uc9c0\uae08\uc740 \ud654\uba74\uc5d0\uc11c \uacb0\uacfc\ub97c \ubc14\ub85c \ud655\uc778\ud558\uc9c0\ub9cc, \ub2f9\uc2dc \ud544\ub984 \uc0ac\uc9c4\uc5d0\uc11c\ub294 \ucd2c\uc601\uacfc \uacb0\uacfc\ub97c \ubcf4\ub294 \uc21c\uac04 \uc0ac\uc774\uc5d0 \ub2e4\ub978 \uacfc\uc815\uc774 \uc788\uc5c8\ub2e4. \ud544\ub984\uc744 \ub2e4\ub8e8\uace0 \ud604\uc0c1\ud558\uace0 \uc778\ud654\ud574\uc57c \ud588\ub2e4. \uc774 \uce74\ud0c8\ub85c\uadf8\uc5d0\ub294 \uce74\uba54\ub77c\ubfd0 \uc544\ub2c8\ub77c \ud544\ub984, \uc778\ud654\uc9c0, \ud604\uc0c1 \ub3c4\uad6c\uc640 \uad00\ub828 \uc6a9\ud488\uc774 \uc774\uc5b4\uc9c4\ub2e4. \uce74\uba54\ub77c\ub97c \uc911\uc2ec\uc73c\ub85c \uc5ec\ub7ec \uc0c1\ud488\uacfc \uc11c\ube44\uc2a4\uac00 \uc5f0\uacb0\ub418\ub294 \ubaa8\uc2b5\uc744 \ubcfc \uc218 \uc788\ub2e4. \uace0\uac1d\uc740 \uae30\uacc4 \ud558\ub098\ub97c \uac16\ub294 \ub3d9\uc2dc\uc5d0 \uacc4\uc18d \uc18c\ubaa8\ub418\ub294 \uc7ac\ub8cc\ub97c \uc4f0\ub294 \ud65c\ub3d9\uc5d0 \ub4e4\uc5b4\uac14\ub2e4. \uc774\uac83\uc744 \uc624\ub298\uc758 \ubaa8\ub4e0 \uad6c\ub3c5 \uc0ac\uc5c5\uacfc \uac19\ub2e4\uace0 \ud560 \ud544\uc694\ub294 \uc5c6\uc9c0\ub9cc, \uccab \ud310\ub9e4 \ub4a4\uc5d0\ub3c4 \uae30\uc5c5\uacfc \uc774\uc6a9\uc790\uc758 \uad00\uacc4\uac00 \uc774\uc5b4\uc9c4\ub2e4\ub294 \uc810\uc740 \ub208\uc5ec\uaca8\ubcfc \ub9cc\ud558\ub2e4. \uc88b\uc740 \uc21c\uac04\uc744 \ub193\uce58\uac70\ub098 \uc0ac\uc9c4\uc774 \uc81c\ub300\ub85c \ub098\uc624\uc9c0 \uc54a\uc73c\uba74 \uc0ac\ub78c\uc740 \uce74\uba54\ub77c\ub97c \uc4f0\uc9c0 \uc54a\uac8c \ub420 \uc218\ub3c4 \uc788\ub2e4. \ud68c\uc0ac\uac00 \uc0ac\uc6a9\ubc95\uc744 \uac00\ub974\uce58\ub294 \uc77c\uc740 \uce5c\uc808\ud55c \ubd80\ub85d\uc774\uba74\uc11c \uc0c1\ud488\uc744 \uacc4\uc18d \uc0ac\uc6a9\ud558\ub3c4\ub85d \ub3d5\ub294 \uc77c\uc774\uae30\ub3c4 \ud558\ub2e4. \uace0\uac1d\uc758 \uc131\uacf5\uc801\uc778 \uacbd\ud5d8\uacfc \uae30\uc5c5\uc758 \ubc18\ubcf5 \ud310\ub9e4\uac00 \uac19\uc740 \ubc29\ud5a5\uc744 \ud5a5\ud560 \uc218 \uc788\uc5c8\ub2e4. \uce74\ud0c8\ub85c\uadf8\ub294 \ubb34\uc5c7\uc744 \ud558\ub77c\ub294 \uc9c0\uc2dc\ubfd0 \uc544\ub2c8\ub77c \uc65c \uadf8\ub807\uac8c \ud574\uc57c \ud558\ub294\uc9c0\ub3c4 \uc124\uba85\ud574 \uc654\ub2e4\uace0 \uac15\uc870\ud55c\ub2e4. \uad11\uace0 \ubb38\uad6c\ub97c \uadf8\ub300\ub85c \uc131\uacfc\ub85c \ubc1b\uc544\ub4e4\uc77c \uc218\ub294 \uc5c6\uc9c0\ub9cc, \uc801\uc5b4\ub3c4 \uc0ac\uc6a9\uc790\uc758 \uc5b4\ub824\uc6c0\uc744 \ud310\ub9e4\uc758 \uc911\uc694\ud55c \ubb38\uc81c\ub85c \uc778\uc2dd\ud588\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc77d\uc744 \uc218 \uc788\ub2e4. \uc0ac\uc9c4\uc744 \ubaa8\ub974\ub294 \uc0ac\ub78c\uc774 \ub298\uc5b4\ub09c\ub2e4\ub294 \uac83\uc740 \uc548\ub0b4\uc758 \ud544\uc694\ub3c4 \ucee4\uc9c4\ub2e4\ub294 \ub73b\uc774\uc5c8\ub2e4. 1914\ub144 5\uc6d4 1\uc77c \uc774\ud6c4 \ucf54\ub2e5\uc774\ub098 \ube0c\ub77c\uc6b0\ub2c8\ub97c \uad6c\ub9e4\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c \u300aKodakery\u300b\ub77c\ub294 \uc7a1\uc9c0\ub97c 1\ub144 \ub3d9\uc548 \ubb34\ub8cc\ub85c \ubcf4\ub0b4\uaca0\ub2e4\ub294 \uc548\ub0b4\ub3c4 \uc788\ub2e4. \uce74\ud0c8\ub85c\uadf8\ub294 \uc774\ub97c \ub9e4\ub2ec \uc0ac\uc9c4 \uc2e4\ub825\uc744 \ub3d5\ub294 \uc791\uc740 \uc7a1\uc9c0\ub85c \uc18c\uac1c\ud55c\ub2e4. \uacc4\uc18d \ubc1b\uc544 \ubcf4\ub824\uba74 \ubcc4\ub3c4\ub85c \uad6c\ub3c5\ud560 \uc218 \uc788\ub2e4\ub294 \uc870\uac74\ub3c4 \ubd99\uc5c8\ub2e4. \ud55c \ubc88 \uac74\ub124\ub294 \uc124\uba85\uc11c\uc640 \uc815\uae30\uc801\uc73c\ub85c \ub3c4\ucc29\ud558\ub294 \uc7a1\uc9c0\ub294 \ub2e4\ub978 \uc5ed\ud560\uc744 \ud55c\ub2e4. \uc7a1\uc9c0\uc5d0\ub294 \uc0c8\ub85c\uc6b4 \ucd2c\uc601 \uc544\uc774\ub514\uc5b4\ub97c \uc18c\uac1c\ud558\uace0 \uc5b4\ub824\uc6b4 \uc810\uc744 \ub2e4\uc2dc \uc124\uba85\ud560 \uae30\ud68c\uac00 \uc788\ub2e4. \uad6c\ub9e4\uac00 \ub05d\ub09c \ub4a4\uc5d0\ub3c4 \uace0\uac1d\uc758 \ucc45\uc0c1 \uc704\uc5d0 \ud68c\uc0ac\uac00 \ub9cc\ub4e0 \uc774\uc57c\uae30\uac00 \ucc3e\uc544\uc624\ub294 \uac83\uc774\ub2e4. \uc0c1\ud488 \uc124\uba85\uc774 \ud558\ub098\uc758 \uc791\uc740 \ub3c5\uc11c \uacbd\ud5d8\uc73c\ub85c \uc774\uc5b4\uc84c\ub2e4. \uce74\ud0c8\ub85c\uadf8\ub97c \ubcf4\uba74 \uc0ac\uc9c4\uc744 \ucc0d\ub294 \uc77c\uc774 \uc5b4\ub5a4 \uc990\uac70\uc6c0\uc73c\ub85c \uc81c\uc2dc\ub418\ub294\uc9c0\ub3c4 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uc5ec\ud589\uacfc \uac00\uc871, \uc791\uc740 \uc77c\uc0c1\uc758 \uc7a5\uba74\uc744 \ub0a8\uae30\uace0 \uc2f6\uc740 \ub9c8\uc74c\uc774 \uae30\uad6c\uc640 \uc6a9\ud488\uc744 \uc18c\uac1c\ud558\ub294 \ubb38\uc7a5 \uc0ac\uc774\uc5d0 \uc788\ub2e4. \uce74\uba54\ub77c\uc758 \uc5ed\uc0ac\uc5d0\ub294 \ub80c\uc988\uc640 \uc154\ud130\uc758 \ubc1c\uc804\ubfd0 \uc544\ub2c8\ub77c \ubb34\uc5c7\uc744 \uae30\uc5b5\ud558\uace0 \uc2f6\uc5c8\ub294\uac00\ub77c\ub294 \uc9c8\ubb38\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \ub2e4\ub9cc \uce74\ud0c8\ub85c\uadf8\uac00 \uc57d\uc18d\ud558\ub294 \uc26c\uc6c0\uacfc \uc2e4\uc81c \uc0ac\uc6a9\uc790\uc758 \uacbd\ud5d8\uc740 \uac19\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uce74\uba54\ub77c\ub97c \uc0b4 \uc218 \uc788\uc5c8\ub358 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \ud310\ub9e4 \uc790\ub8cc\uac00 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \ub2f9\uc2dc \uc0ac\ud68c \uc804\uccb4\uc758 \uc644\uc804\ud55c \ubaa8\uc2b5\ubcf4\ub2e4 \uae30\uc5c5\uc774 \ub113\ud788\uace0 \uc2f6\uc5c8\ub358 \uace0\uac1d\uc758 \uc138\uacc4\uc5d0 \uac00\uae5d\ub2e4. \uadf8 \ucc28\uc774\ub97c \uc54c\uace0 \uc77d\uc73c\uba74 \uad11\uace0\ub3c4 \uc88b\uc740 \uc5ed\uc0ac \uc790\ub8cc\uac00 \ub41c\ub2e4. \ucf54\ub2e5\uc758 \uc774 \uc778\uc1c4\ubb3c\uc5d0\uc11c \ud765\ubbf8\ub85c\uc6b4 \uac83\uc740 \uce74\uba54\ub77c\ub97c \uc544\uc8fc \uac04\ub2e8\ud55c \ubb3c\uac74\uc73c\ub85c \ubcf4\uc774\uac8c \ud558\ub824\uba74\uc11c\ub3c4 \ub9ce\uc740 \uc124\uba85\uc744 \uc81c\uacf5\ud55c\ub2e4\ub294 \uc810\uc774\ub2e4. \uc27d\ub2e4\ub294 \ub9d0\uc774 \uc544\ubb34\uac83\ub3c4 \ubc30\uc6b8 \ud544\uc694\uac00 \uc5c6\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc0ac\uc6a9\uc790\uac00 \uc791\uc740 \uc2e4\ud328\ub97c \ub118\uae30\uace0 \ub2e4\uc74c \uc0ac\uc9c4\uc744 \ucc0d\uac8c \ub3d5\ub294 \uc77c\uc774 \ud568\uaed8 \ud544\uc694\ud588\ub2e4. \uc0ac\uc9c4 \uc18d \ube0c\ub77c\uc6b0\ub2c8\ub97c \ub2e4\uc2dc \ubcf4\uba74 \ub2e8\uc21c\ud55c \uc0c1\uc790 \ub4a4\uc5d0 \uc124\uba85\uc11c\uc640 \uc7a1\uc9c0, \ud544\ub984\uacfc \uc778\ud654\uc9c0, \ud310\ub9e4\uc810\uc774 \ub530\ub77c \ub098\uc628\ub2e4. \uae30\uc5c5\uc740 \ubb3c\uac74 \ud558\ub098\ub97c \ub9cc\ub4e4\uc9c0\ub9cc \uc0ac\ub78c\uc740 \uadf8\uac83\uc744 \uc0ac\uc6a9\ud558\ub294 \uc2dc\uac04\uc744 \uc0b4\uc544\uac04\ub2e4. \uc88b\uc740 \uc0c1\ud488\uc744 \uc774\ud574\ud558\ub824\uba74 \uadf8 \uc2dc\uac04\uc774 \uc5b4\ub5bb\uac8c \uc900\ube44\ub418\uc5c8\ub294\uc9c0\ub3c4 \ubcfc \ud544\uc694\uac00 \uc788\ub2e4."}, {"id": "lego-play-well", "title": "\ub808\uace0\ub77c\ub294 \uc774\ub984\uc740 \uc6d0\ub798 \ubb34\uc2a8 \ub73b\uc77c\uae4c", "summary": "\uc775\uc219\ud55c \ub124 \uae00\uc790 \uc548\uc5d0 \ub374\ub9c8\ud06c\uc5b4\ub85c \ub180\uc774\uc5d0 \uad00\ud55c \ub73b\uc774 \uc228\uc5b4 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub984\ubd80\ud130 \uba3c\uc800 \ub4e4\uc5ec\ub2e4\ubcf4\ub294 \ub808\uace0 \uc774\uc57c\uae30.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\ube0c\ub79c\ub4dc\uc640 \uc18c\ube44", "categories": ["industry"], "url": "stories/lego-play-well/index.html", "image": "../media/lego-play-well.jpg", "alt": "\ub808\uace0\ub77c\ub294 \uc774\ub984\uc740 \uc6d0\ub798 \ubb34\uc2a8 \ub73b\uc77c\uae4c \u2014 \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ub808\uace0\ub77c\ub294 \uc774\ub984\uc740 \uc6d0\ub798 \ubb34\uc2a8 \ub73b\uc77c\uae4c \uc791\uc740 \ube14\ub85d\ubcf4\ub2e4 \uba3c\uc800 \uc788\uc5c8\ub358 \u2018\uc798 \ub180\uc790\u2019\ub77c\ub294 \ub9d0 \uc775\uc219\ud55c \ub124 \uae00\uc790 \uc548\uc5d0 \ub374\ub9c8\ud06c\uc5b4\ub85c \ub180\uc774\uc5d0 \uad00\ud55c \ub73b\uc774 \uc228\uc5b4 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub984\ubd80\ud130 \uba3c\uc800 \ub4e4\uc5ec\ub2e4\ubcf4\ub294 \ub808\uace0 \uc774\uc57c\uae30. \ube0c\ub79c\ub4dc\uc640 \uc18c\ube44 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \ub808\uace0 \uc0c1\uc790\ub97c \uc5f4\uba74 \uba3c\uc800 \uc124\uba85\uc11c\ub97c \ucc3e\ub294 \uc0ac\ub78c\uc774 \uc788\ub2e4. \ubc18\ub300\ub85c \ubd80\ud488\ubd80\ud130 \uc3df\uc544 \ub193\uace0 \ub9c8\uc74c\ub300\ub85c \uc313\ub294 \uc0ac\ub78c\ub3c4 \uc788\ub2e4. \uac19\uc740 \ube14\ub85d\uc744 \ubc1b\uc544\ub3c4 \ub178\ub294 \ubc29\ubc95\uc740 \uc870\uae08\uc529 \ub2e4\ub974\ub2e4. \uadf8\ub7f0\ub370 \ub808\uace0\ub77c\ub294 \uc774\ub984 \uc790\uccb4\uc5d0\ub3c4 \ub180\uc774\uc5d0 \uad00\ud55c \ub9d0\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ub374\ub9c8\ud06c\uc5b4 \u2018leg godt\u2019\uc5d0\uc11c \uac00\uc838\uc628 \uc774\ub984\uc73c\ub85c, \ud754\ud788 \u2018\uc798 \ub180\uc544\ub77c\u2019 \ub610\ub294 \u2018\uc798 \ub180\uc790\u2019\ub77c\ub294 \ub73b\uc73c\ub85c \ud480\uc774\ub41c\ub2e4. \ubcf5\uc7a1\ud55c \uc6b0\uc8fc\uc120\uc774\ub098 \ucee4\ub2e4\ub780 \uc131\uc744 \ub9cc\ub4e4\uae30 \uc804\uc5d0, \uc774\ub984\uc774 \uba3c\uc800 \uac74\ub124\ub294 \ub9d0\uc740 \uc758\uc678\ub85c \uac04\ub2e8\ud588\ub358 \uc148\uc774\ub2e4. \ub808\uace0\uc758 \ucc3d\uc5c5\uc790 \uc62c\ub808 \ud0a4\ub974\ud06c \ud06c\ub9ac\uc2a4\ud2f0\uc548\uc13c\uc740 \ub374\ub9c8\ud06c \ube4c\ub8ec\uc5d0\uc11c \ubaa9\uacf5 \uc77c\uc744 \ud558\uba70 \uc7a5\ub09c\uac10\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \ucd08\uae30\uc758 \uc81c\ud488\uc740 \uc624\ub298\ub0a0 \uc6b0\ub9ac\uac00 \ub5a0\uc62c\ub9ac\ub294 \ud50c\ub77c\uc2a4\ud2f1 \ube14\ub85d\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c4 \uc138\uacc4\uc640 \ub2ec\ub790\ub2e4. \ub098\ubb34 \uc7a5\ub09c\uac10\uc774 \uc788\uc5c8\ub2e4. \ub808\uace0\ub77c\ub294 \uc774\ub984\uc740 \uc624\ub298\ub0a0\uc758 \ud50c\ub77c\uc2a4\ud2f1 \ube14\ub85d \ubaa8\uc591\uc744 \ubcf4\uace0 \uadf8 \ud2b9\uc9d5\uc5d0 \ub9de\ucd94\uc5b4 \uc9c0\uc740 \uac83\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uacf5\uc2dd \uc5f0\ud601\uc740 \ubaa9\uc7ac \uc7a5\ub09c\uac10\uc744 \ub9cc\ub4e4\ub358 \uc2dc\uae30\uc5d0 \ub374\ub9c8\ud06c\uc5b4 LEG GODT\ub97c \uc870\ud569\ud574 \uc774\ub984\uc744 \uc815\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub180\uc774\uc5d0 \uad00\ud55c \uc774\ub984\uc744 \uba3c\uc800 \uac16\uace0, \uadf8 \uc544\ub798\uc5d0\uc11c \uc7a5\ub09c\uac10\uc774 \ub2ec\ub77c\uc838 \uac04 \uac83\uc774\ub2e4. \uc774 \uc0ac\uc2e4\uc744 \uc54c\uba74 \uc775\uc219\ud55c \uc774\ub984\uc774 \uc870\uae08 \uc0c8\ub86d\uac8c \ub4e4\ub9b0\ub2e4. \uc6b0\ub9ac\ub294 \ubcf4\ud1b5 \ub808\uace0\ub97c \ubcf4\uba74 \ubc14\ub85c \ube14\ub85d\uc744 \ub5a0\uc62c\ub9b0\ub2e4. \ud558\uc9c0\ub9cc \uc774\ub984\uc774 \uc0dd\uacbc\uc744 \ub54c\ubd80\ud130 \uc9c0\uae08\uc758 \ubaa8\ub4e0 \uc81c\ud488\uc774 \uc815\ud574\uc838 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ub7ab\ub3d9\uc548 \uc4f0\uc778 \uc774\ub984\uc5d0\ub294 \uadf8\ub7f0 \uc2dc\uac04\uc774 \uc811\ud600 \uc788\ub2e4. \uc624\ub298\uc758 \ubb3c\uac74\ub9cc \ubcf4\uace0 \uacfc\uac70\uae4c\uc9c0 \uac19\uc740 \ubaa8\uc2b5\uc774\uc5c8\uc744 \uac83\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \ub193\uce58\ub294 \ubd80\ubd84\uc774\ub2e4. \ub808\uace0\uc758 \uacbd\uc6b0\uc5d0\ub294 \uc774\ub984\uc774 \uc7a5\ub09c\uac10\uc758 \uc7ac\ub8cc \ubcc0\ud654\ubcf4\ub2e4 \uc624\ub798 \ub0a8\uc558\ub2e4. \uc9c0\uae08\uc758 \ub808\uace0\ub97c \ub5a0\uc62c\ub9ac\uba74 \uc11c\ub85c \ub9de\ubb3c\ub9ac\ub294 \ub3cc\uae30\uc640 \uad6c\uba4d\uc774 \uc0dd\uac01\ub09c\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ube14\ub85d \ud55c \uac1c\uc758 \ubaa8\uc591\ub9cc\uc774 \uc544\ub2c8\ub77c, \uc5ec\ub7ec \uac1c\uac00 \uc5f0\uacb0\ub41c\ub2e4\ub294 \uc810\uc774\ub2e4. \ud63c\uc790 \uc788\uc744 \ub54c\ub294 \uc791\uc740 \ubd80\ud488\uc774\uc9c0\ub9cc \ub2e4\ub978 \ubd80\ud488\uc744 \ub9cc\ub098\uba74 \uc9d1\ub3c4 \ub418\uace0 \uc790\ub3d9\ucc28\ub3c4 \ub41c\ub2e4. \ubb3c\ub860 \uc544\ubb34 \uc870\ud569\uc774\ub098 \ub2e4 \uc798 \ub9de\ub294\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc81c\ud488\uc5d0 \ub530\ub77c \uc4f0\ub294 \ubc29\ubc95\uacfc \ud638\ud658 \ubc94\uc704\uac00 \ub2e4\ub974\ub2e4. \uadf8\ub798\ub3c4 \ub9ce\uc740 \ube14\ub85d\uc744 \ub2e4\uc2dc \ub5bc\uace0 \uc0c8\ub85c \uc870\ub9bd\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc740 \uc774 \ub180\uc774\uc758 \ud070 \ud2b9\uc9d5\uc774\ub2e4. \uc124\uba85\uc11c\ub300\ub85c \uc644\uc131\ud558\ub294 \uc7ac\ubbf8\uc640, \uc644\uc131\ud55c \uac83\uc744 \ub2e4\uc2dc \ubc14\uafb8\ub294 \uc7ac\ubbf8\uac00 \ud568\uaed8 \uc788\ub2e4. \uc9c0\ubd95\uc744 \ub5bc\uc5b4 \ub2e4\ub978 \uacf3\uc5d0 \ubd99\uc5ec \ubcf4\uac70\ub098 \ub0a8\uc740 \ubd80\ud488\uc73c\ub85c \ucc98\uc74c \uacc4\ud68d\uc5d0 \uc5c6\ub358 \ubb3c\uac74\uc744 \ub9cc\ub4e4 \uc218\ub3c4 \uc788\ub2e4. \uc0c1\uc790\uc5d0 \uadf8\ub824\uc9c4 \ubaa8\uc2b5\uc774 \ub180\uc774\uc758 \uc720\uc77c\ud55c \uacb0\ub9d0\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub798\uc11c \u2018\uc798 \ub180\uc790\u2019\ub77c\ub294 \uc774\ub984\uc740 \uaf64 \ub113\uac8c \ub4e4\ub9b0\ub2e4. \uc5ec\uae30\uc11c \uc798\ud55c\ub2e4\ub294 \uac83\uc744 \ub204\uac00 \ub354 \ube68\ub9ac \uc644\uc131\ud588\ub294\uc9c0\ub85c\ub9cc \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uc774\uac83\uc740 \uc774\ub984\uc744 \uc624\ub298\uc758 \uc6b0\ub9ac\uac00 \uc990\uae30\ub294 \ubc29\uc2dd\uc774\ub2e4. \ucc3d\uc5c5\uc790\uac00 \ubaa8\ub4e0 \uc0ac\uc6a9\uc790\uc758 \ub180\uc774\ub97c \ubbf8\ub9ac \uc0c1\uc0c1\ud588\ub2e4\uace0 \ub9d0\ud558\ub824\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubaa9\uc7ac \uc7a5\ub09c\uac10\uacfc \uc624\ub298\ub0a0\uc758 \uc870\ub9bd \ube14\ub85d\uc740 \uc7ac\ub8cc\uc640 \uc0ac\uc6a9 \uacbd\ud5d8\uc774 \ub2e4\ub974\ub2e4. \uadf8\ub7f0\ub370 \ub180\uc774\ub97c \ub73b\ud558\ub294 \uc774\ub984\uc740 \uadf8 \ubcc0\ud654\ub97c \uac74\ub108 \uc774\uc5b4\uc84c\ub2e4. \ud68c\uc0ac\uac00 \uc5b4\ub5a4 \uc81c\ud488\uc744 \ub9cc\ub4e4\uace0 \uc788\ub294\uc9c0\uc640 \ube0c\ub79c\ub4dc\uac00 \uc5b4\ub5a4 \ub9d0\ub85c \uae30\uc5b5\ub418\ub294\uc9c0\ub294 \uaf2d \uac19\uc740 \uc18d\ub3c4\ub85c \ubc14\ub00c\uc9c0 \uc54a\ub294\ub2e4. \uc774\ub984\uc758 \uc720\ub798\ub294 \uae30\uc5c5\uc758 \ucd9c\ubc1c\uc810\uacfc \uc9c0\uae08\uc758 \ubaa8\uc2b5\uc744 \ub098\ub780\ud788 \ubcf4\uac8c \ud55c\ub2e4. \uc774\ub984\uc744 \ub73b\ud480\uc774\ud558\ub294 \ub370\uc11c \uba48\ucd94\uc9c0 \uc54a\uace0 \uc2e4\uc81c \uc81c\ud488\uc758 \uad00\uacc4\ub97c \ubcf4\uba74 \ub354 \uc7ac\ubbf8\uc788\ub2e4. \ub3cc\uae30\uc640 \uc548\ucabd \ud29c\ube0c\uac00 \ub9de\ubb3c\ub9ac\ub294 \ubc29\uc2dd\uc740 \ubd80\ud488\uc744 \uc5f0\uacb0\ud55c \uc0c1\ud0dc\uc5d0\uc11c \ud615\ud0dc\ub97c \uc720\uc9c0\ud558\ub3c4\ub85d \ub3d5\ub294\ub2e4. \uc644\uc131\ud55c \ub4a4 \ub2e4\uc2dc \ub5bc\uc5b4 \uc4f0\ub294 \uacbd\ud5d8\ub3c4 \uc774\ub7f0 \uacb0\ud569\uc758 \uc131\uc9c8\uacfc \uad00\uacc4\uac00 \uc788\ub2e4. \ub180\uc774\uc5d0 \uad00\ud55c \ub9d0\uacfc \ubb3c\uac74\uc744 \ub2e4\ub8e8\ub294 \uc190\uc758 \uacbd\ud5d8\uc774 \ub9cc\ub098\ub294 \uc9c0\uc810\uc774\ub2e4. \uc124\uba85\uc11c\ub97c \ub530\ub77c \ub9cc\ub4e0 \ubaa8\ud615\uc740 \ud558\ub098\uc758 \ud574\ub2f5\uc774\uc9c0\ub9cc \ubd80\ud488\uc758 \uac00\ub2a5\ud55c \uc4f0\uc784\uc744 \ubaa8\ub450 \uc18c\uc9c4\ud55c \uacb0\uacfc\ub294 \uc544\ub2c8\ub2e4. \ubaa8\uc591\uc744 \ubc14\uafc0 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc644\uc131\uc744 \ub05d\uc774 \uc544\ub2c8\ub77c \ub2e4\uc74c \uc120\ud0dd\uc758 \ucd9c\ubc1c\uc810\uc73c\ub85c \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \uc5b4\ub978\uc774 \uace0\ub978 \uc815\ub2f5\uacfc \ub2e4\ub978 \ubaa8\uc591\uc744 \ub9cc\ub4e4\ub354\ub77c\ub3c4 \ubd80\ud488\ub4e4\uc774 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \uacb0\ud569\ub418\ub294\uc9c0 \uc2dc\ud5d8\ud558\ub294 \uacbd\ud5d8\uc740 \ub0a8\ub294\ub2e4. \uc774\uac83\uc744 \ubaa8\ub4e0 \uc81c\ud488\uc758 \uacf5\uc2dd \uad50\uc721 \ud6a8\uacfc\ub77c\uace0 \ub2e8\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774\ub984\uc744 \uc624\ub298\uc758 \ub180\uc774\uc5d0 \uc5f0\uacb0\ud574 \uc77d\uc5b4 \ubcf4\ub294 \uad00\uc810\uc774\ub2e4. \uc798 \ub17c\ub2e4\ub294 \ub9d0\uc774 \ube60\ub974\uace0 \uc815\ud655\ud558\uac8c \ubcf5\uc81c\ud55c\ub2e4\ub294 \ub73b\ub9cc\uc740 \uc544\ub2d0 \uc218 \uc788\ub2e4\ub294 \uc0dd\uac01\uc744 \ub3d5\ub294\ub2e4. \uac19\uc740 \ub124 \uae00\uc790\ub97c \uc54c\uace0\ub3c4 \uc0ac\ub78c\ub9c8\ub2e4 \ub2e4\ub978 \ub180\uc774\uc758 \uc7a5\uba74\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \uc774 \uc774\ub984\uc758 \uc5ec\uc720\ub2e4. \ube0c\ub79c\ub4dc \uc774\ub984\uc744 \ub108\ubb34 \uc790\uc8fc \ubcf4\uba74 \ub73b\uc744 \uc0dd\uac01\ud558\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uac04\ud310\ucc98\ub7fc \uc54c\uc544\ubcf4\uba74 \ucda9\ubd84\ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \uadf8\ub7f0\ub370 \uac00\ub054 \uadf8 \uc774\ub984\uc744 \ucc98\uc74c \ub4e3\ub294 \ub9d0\ucc98\ub7fc \ud480\uc5b4 \ubcf4\uba74 \ubb3c\uac74\uc758 \ub2e4\ub978 \uba74\uc774 \ubcf4\uc778\ub2e4. \ub808\uace0\ub294 \ub374\ub9c8\ud06c\uc758 \uc791\uc740 \uc791\uc5c5\uc7a5\uc5d0\uc11c \ucd9c\ubc1c\ud55c \uc7a5\ub09c\uac10 \ud68c\uc0ac\uc774\uba74\uc11c, \uc9c0\uae08\uc740 \uc5ec\ub7ec \ub098\ub77c\uc758 \uc0ac\ub78c\ub4e4\uc774 \uac01\uc790\uc758 \ubc29\uc2dd\uc73c\ub85c \uac00\uc9c0\uace0 \ub178\ub294 \uc774\ub984\uc774 \ub418\uc5c8\ub2e4. \uadf8 \ubcc0\ud654\ub97c \ub124 \uae00\uc790\ub9cc \ubcf4\uace0 \uc9d0\uc791\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \ub2e4\uc74c\uc5d0 \ube14\ub85d\uc744 \uc870\ub9bd\ud560 \uc77c\uc774 \uc0dd\uae34\ub2e4\uba74 \uc774\ub984\uc744 \ud55c \ubc88 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc124\uba85\uc11c\uc758 \ub9c8\uc9c0\ub9c9 \uc7a5\uc5d0 \ub3c4\ucc29\ud574\uc57c\ub9cc \ub180\uc774\uac00 \uc644\uc131\ub418\ub294 \uac83\uc740 \uc544\ub2d0\uc9c0\ub3c4 \ubaa8\ub978\ub2e4. \uc791\uc740 \ubd80\ud488 \ud558\ub098\uac00 \ub0a8\uc544\uc11c \uc5c9\ub6b1\ud55c \ubb3c\uac74\uc744 \ub9cc\ub4dc\ub294 \uc21c\uac04\ub3c4 \ucda9\ubd84\ud788 \uc7ac\ubbf8\uc788\ub2e4. \ud68c\uc0ac \uc774\ub984\uc744 \uacf5\ubd80\ud558\ub7ec \uc2dc\uc791\ud55c \uc774\uc57c\uae30\ub294 \uc544\ub2c8\uc5c8\ub294\ub370, \uc774\ub984\uc744 \ud480\uace0 \ub098\ub2c8 \uacb0\uad6d \ub2e4\uc2dc \ub178\ub294 \uc774\uc57c\uae30\ub85c \ub3cc\uc544\uc654\ub2e4. \ub808\uace0\ub77c\ub294 \ub9d0\uc5d0\ub294 \ucc98\uc74c\ubd80\ud130 \uadf8 \ub2e8\uc11c\uac00 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4."}, {"id": "linotype-matrices-and-newspaper-time", "title": "\ub9ac\ub178\ud0c0\uc774\ud504 \u2014 \uae00\uc790 \ud558\ub098 \ub300\uc2e0 \ud55c \uc904\uc744 \ub9cc\ub4e4\ub2e4", "summary": "\ud65c\uc790 \uc8fc\ud615\uc744 \ubaa8\uc544 \ud55c \uc904\uc744 \uc8fc\uc870\ud558\uace0 \ub418\ub3cc\ub9ac\ub294 \uad6c\uc870\uac00 \uc2e0\ubb38\uc758 \uc0dd\uc0b0\uacfc \uc219\ub828\uc744 \uc5b4\ub5bb\uac8c \ubc14\uafe8\ub294\uc9c0 \ubd05\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\uacf5\uc7a5\uacfc \uc0dd\uc0b0", "categories": ["industry"], "url": "stories/linotype-matrices-and-newspaper-time/index.html", "image": "../media/linotype-matrices-and-newspaper-time.jpg", "alt": "\ud0a4\ubcf4\ub4dc\uc640 \uc8fc\ud615 \uc800\uc7a5\ubd80, \uc8fc\uc870 \uc7a5\uce58\uac00 \uc788\ub294 \ub9ac\ub178\ud0c0\uc774\ud504 \uae30\uacc4\uc758 \uc5ed\uc0ac \ub3c4\ud310", "text": "\ub9ac\ub178\ud0c0\uc774\ud504 \u2014 \uae00\uc790 \ud558\ub098 \ub300\uc2e0 \ud55c \uc904\uc744 \ub9cc\ub4e4\ub2e4 \ubb38\uc790 \uc8fc\ud615\uc758 \uc774\ub3d9\u00b7\uc8fc\uc870\u00b7\ud68c\uc218\uac00 \uc5f0\uacb0\ud55c \uc2e0\ubb38\uc758 \uc0dd\uc0b0 \ud65c\uc790 \uc8fc\ud615\uc744 \ubaa8\uc544 \ud55c \uc904\uc744 \uc8fc\uc870\ud558\uace0 \ub418\ub3cc\ub9ac\ub294 \uad6c\uc870\uac00 \uc2e0\ubb38\uc758 \uc0dd\uc0b0\uacfc \uc219\ub828\uc744 \uc5b4\ub5bb\uac8c \ubc14\uafe8\ub294\uc9c0 \ubd05\ub2c8\ub2e4. \uacf5\uc7a5\uacfc \uc0dd\uc0b0 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \uc2e0\ubb38 \ud55c \uba74\uc744 \ub9cc\ub4e4\uae30 \uc704\ud574 \uae00\uc790\ub97c \ud558\ub098\uc529 \uace8\ub77c \uc904\uc744 \uc138\uc6b0\ub358 \ub54c\uac00 \uc788\uc5c8\ub2e4. \uc778\uc1c4\uae30\uc758 \uc18d\ub3c4\uac00 \ube68\ub77c\uc838\ub3c4 \uadf8 \uc55e\uc5d0\uc11c \ubb38\uc7a5\uc744 \uc870\ub9bd\ud558\ub294 \uc77c\uc774 \uc624\ub798 \uac78\ub9ac\uba74 \uc9c0\uba74\uc740 \uc900\ube44\ub418\uc9c0 \uc54a\ub294\ub2e4. \ub9ac\ub178\ud0c0\uc774\ud504\ub294 \ubc14\ub85c \uadf8 \uacfc\uc815\uc744 \ubc14\uafb8\uc5c8\ub2e4. \uc774\ub984\ucc98\ub7fc \ud55c \uc904\uc758 \ud65c\uc790\ub97c \ub9cc\ub4dc\ub294 \uae30\uacc4\ub97c \ud1b5\ud574 \uc778\uc1c4\uc758 \uc5ed\uc0ac\ub97c \uc0b4\ud3b4\ubcf4\uc790. \uae08\uc18d \ud65c\uc790\ub97c \uc0ac\uc6a9\ud558\ub294 \uc778\uc1c4\uc5d0\uc11c\ub294 \uae00\uc790 \ubaa8\uc591\uc774 \ub4e4\uc5b4\uac04 \uc791\uc740 \ubd80\ud488\uc744 \uace8\ub77c \ubb38\uc7a5\uc744 \uad6c\uc131\ud588\ub2e4. \ud55c \uc904\uc744 \uc77c\uc815\ud55c \uae38\uc774\uc5d0 \ub9de\ucd94\uace0, \uc778\uc1c4 \ub4a4\uc5d0\ub294 \ud65c\uc790\ub97c \ub2e4\uc2dc \uc4f8 \uc218 \uc788\ub3c4\ub85d \uc81c\uc790\ub9ac\ub85c \ub3cc\ub824\ub193\uc544\uc57c \ud588\ub2e4. \uc885\uc774\uc5d0 \ucc0d\ub294 \uc21c\uac04\ubcf4\ub2e4 \uc55e\ub4a4\uc758 \uc900\ube44\uac00 \ubcf5\uc7a1\ud588\ub2e4. \ubb38\uc790\uac00 \ub9ce\uace0 \ub0b4\uc6a9\uc774 \uc790\uc8fc \ubc14\ub00c\ub294 \uc2e0\ubb38\uc5d0\uc11c \uc774 \uc2dc\uac04\uc740 \ud2b9\ud788 \uc911\uc694\ud588\ub2e4. \ub354 \ub2a6\uac8c \ub4e4\uc5b4\uc628 \uc18c\uc2dd\uc744 \uc2e3\uace0 \uc2f6\uc5b4\ub3c4 \uc9c0\uba74\uc744 \ub9cc\ub4e4 \uc2dc\uac04\uc774 \ud544\uc694\ud588\ub2e4. \uae30\uc0ac \uc791\uc131\uacfc \uc870\ud310, \uc778\uc1c4\uc640 \ubc30\ub2ec\uc774 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\uae30\uc5d0 \ud55c \ub2e8\uacc4\uc758 \ubcc0\ud654\uac00 \ub2e4\ub978 \ub2e8\uacc4\uc758 \uc77c\uc815\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc8fc\uc5c8\ub2e4. \uba54\ub974\uac90\ud0c8\ub7ec\uc758 \ub9ac\ub178\ud0c0\uc774\ud504\uc5d0\uc11c\ub294 \ud0a4\ubcf4\ub4dc\ub97c \ub204\ub974\uba74 \ud574\ub2f9 \ubb38\uc790\uc758 \uc8fc\ud615\uc774 \ubaa8\uc600\ub2e4. \uc5ec\uae30\uc11c \uc8fc\ud615\uc740 \uc885\uc774\uc5d0 \uc9c1\uc811 \ucc0d\uc744 \ud65c\uc790\uc640 \ub2e4\ub974\ub2e4. \uae00\uc790\uc758 \ubaa8\uc591\uc744 \ub9cc\ub4e4\uae30 \uc704\ud55c \uc791\uc740 \ud2c0\uc774\ub2e4. \uc0ac\uc6a9\uc790\ub294 \uacb0\uacfc\ubb3c \uc790\uccb4\ubcf4\ub2e4 \uacb0\uacfc\ub97c \ub9cc\ub4dc\ub294 \ud2c0\uc744 \uc21c\uc11c\ub300\ub85c \ubc30\uc5f4\ud55c\ub2e4. \ubb38\uc790\ub9c8\ub2e4 \ud544\uc694\ud55c \uc8fc\ud615\uc774 \uc800\uc7a5\ub41c \uacf3\uc5d0\uc11c \ub0b4\ub824\uc640 \ud55c \uc904\uc744 \uc774\ub8ec\ub2e4. \uc190\uc73c\ub85c \uae00\uc790\ub97c \uace0\ub974\ub358 \ud589\ub3d9\uc774 \ud0a4\ub97c \ub204\ub974\ub294 \uc77c\uacfc \uae30\uacc4 \ub0b4\ubd80\uc758 \uc774\ub3d9\uc73c\ub85c \ubc14\ub010 \uac83\uc774\ub2e4. \uadf8\ub7ec\ub098 \uc785\ub825\ud560 \ubb38\uc790\ub97c \ud310\ub2e8\ud558\ub294 \uc0ac\ub78c\uc758 \uc77c\uae4c\uc9c0 \uc0ac\ub77c\uc9c4 \uac83\uc740 \uc544\ub2c8\ub2e4. \uae30\uacc4\ub294 \ubb38\uc7a5\uc758 \ub73b\uc744 \uc54c\uc544\uc11c \uc644\uc131\ud558\ub294 \uc791\uac00\uac00 \uc544\ub2c8\uc5c8\ub2e4. \uc2e0\ubb38\uc758 \uce7c\ub7fc\uc744 \ubcf4\uba74 \uc904\uc758 \uc624\ub978\ucabd \ub05d\uc774 \uc77c\uc815\ud558\uac8c \ub9de\ub294\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ubb38\uc7a5\uc744 \uac19\uc740 \ud3ed\uc5d0 \ub123\uc73c\ub824\uba74 \uae00\uc790\uc640 \ub2e8\uc5b4 \uc0ac\uc774\uc758 \uac04\uaca9\uc744 \uc870\uc808\ud574\uc57c \ud55c\ub2e4. \uc870\ud310\uc758 \uc5b4\ub824\uc6c0\uc740 \ubb38\uc790\ub4e4\uc744 \uc21c\uc11c\ub300\ub85c \ub193\ub294 \uc77c\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ub9ac\ub178\ud0c0\uc774\ud504\ub294 \uc8fc\ud615 \uc0ac\uc774\uc758 \uac04\uaca9\uc744 \uc870\uc808\ud558\ub294 \uc7a5\uce58\ub97c \ud3ec\ud568\ud588\ub2e4. \ud55c \uc904\uc774 \uc900\ube44\ub418\uba74 \uae08\uc18d\uc744 \ubd80\uc5b4 \uc644\uc131\ub41c \uc904 \ud65c\uc790\ub97c \ub9cc\ub4e4\uc5c8\ub2e4. \uc5ec\uae30\uc11c \uc790\ub3d9\ud654\ub294 \uae00\uc790\uc758 \uc120\ud0dd\uacfc \uac04\uaca9\uc758 \uc870\uc815, \uc8fc\uc870\ub97c \ud558\ub098\uc758 \uc791\uc5c5 \ud750\ub984\uc73c\ub85c \uc5f0\uacb0\ud558\ub294 \uc77c\uc774\uc5c8\ub2e4. \uac01 \uae30\ub2a5\uc774 \ub530\ub85c \uc88b\uc544\ub3c4 \uc11c\ub85c \ub9de\uc9c0 \uc54a\uc73c\uba74 \uc9c0\uba74\uc740 \ub9cc\ub4e4\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uc644\uc131\ub41c \uc904\uc740 \uc778\uc1c4\uc5d0 \uc0ac\uc6a9\ud560 \uc218 \uc788\uc9c0\ub9cc \uc8fc\ud615\uae4c\uc9c0 \uc9c0\uba74\uc73c\ub85c \uac00\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc8fc\ud615\uc740 \ub2e4\uc2dc \ubd84\ub958\ub418\uc5b4 \uc800\uc7a5 \uc704\uce58\ub85c \ub3cc\uc544\uac00 \ub2e4\uc74c \uc785\ub825\uc5d0 \uc0ac\uc6a9\ub41c\ub2e4. \uacb0\uacfc\ubb3c\uc744 \uaebc\ub0b4\ub294 \uc77c\uacfc \ub3c4\uad6c\ub97c \ub418\ub3cc\ub9ac\ub294 \uc77c\uc774 \ud568\uaed8 \uc774\uc5b4\uc838\uc57c \uc5f0\uc18d \uc791\uc5c5\uc774 \uac00\ub2a5\ud558\ub2e4. 1900\ub144 \ubc88\uc758 \uae30\uc220\uc0ac \ucc45\uc740 \uc774 \ubcf5\uc7a1\ud55c \uadc0\ud658 \uacfc\uc815\uc744 \uc124\uba85\ud55c\ub2e4. \uc791\uc740 \ubd80\ud488\ub4e4\uc774 \uc801\uc808\ud55c \uc790\ub9ac\uc5d0 \ubaa8\uc774\uace0 \ud769\uc5b4\uc9c0\ub294 \uad6c\uc870\ub294 \uae30\uacc4\ub97c \uac70\ub300\ud55c \ubb38\uc790 \ucc3d\uace0\ucc98\ub7fc \ubcf4\uac8c \ud55c\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \ud0a4\ubcf4\ub4dc \ub4a4\uc5d0 \uc774\ub3d9\uacfc \ubd84\ub958\uc758 \uc2dc\uc2a4\ud15c\uc774 \uc228\uc5b4 \uc788\uc5c8\ub2e4. \uc8fc\ud615\uc774 \ud55c \ubc88 \uc4f0\uc774\uace0 \ubc84\ub824\uc9c4\ub2e4\uba74 \uc800\uc7a5 \uacf5\uac04\uacfc \ubd80\ud488\uc758 \uc591\uc774 \ud06c\uac8c \ub298\uc5b4\ub0a0 \uac83\uc774\ub2e4. \uac19\uc740 \uc8fc\ud615\uc744 \ub418\ub3cc\ub824 \uc4f0\ub294 \uad6c\uc870\ub294 \ub2e8\uc21c\ud55c \ubd80\uc18d \uae30\ub2a5\ubcf4\ub2e4 \uc5f0\uc18d \uc0dd\uc0b0\uc758 \ud575\uc2ec\uc5d0 \uac00\uae4c\uc6e0\ub2e4. \uae30\uacc4\ub97c \uc774\ud574\ud560 \ub54c \uacb0\uacfc\ubb3c\uc774 \ub098\uc624\ub294 \uc55e\ucabd\ub9cc\ud07c \ubd80\ud488\uc774 \ub3cc\uc544\uac00\ub294 \ub4a4\ucabd\ub3c4 \uc0b4\ud3b4\uc57c \ud558\ub294 \uc774\uc720\ub2e4. \ud55c \uc904\uc529 \ub9cc\ub4e0\ub2e4\ub294 \uc120\ud0dd\uc5d0\ub294 \uc218\uc815 \ubc29\uc2dd\uc758 \ucc28\uc774\ub3c4 \ub530\ub77c\uc628\ub2e4. \uc885\uc774\uc5d0 \ucc0d\uae30 \uc804\uc5d0 \uc798\ubabb\ub41c \ubb38\uc790\ub97c \ucc3e\ub294 \uc77c\uc740 \uc5ec\uc804\ud788 \uc911\uc694\ud558\ub2e4. \uae30\uacc4\uac00 \ube60\ub974\uac8c \ubc18\ubcf5\ud560 \uc218 \uc788\ub2e4\uace0 \ud3b8\uc9d1\uacfc \uad50\uc815\uc758 \ud310\ub2e8\uc774 \ubd88\ud544\uc694\ud574\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc815\ubcf4\uc758 \uc0dd\uc0b0\uc740 \uc785\ub825\uc758 \uc18d\ub3c4\uc640 \ub0b4\uc6a9\uc758 \uc815\ud655\uc131\uc744 \ud568\uaed8 \uc694\uad6c\ud55c\ub2e4. \uc2e0\ubb38\uc744 \ube68\ub9ac \ub0b4\ub294 \ub2a5\ub825\uc740 \uc77d\uc744 \ub9cc\ud55c \uc2e0\ubb38\uc744 \ub9cc\ub4dc\ub294 \uc5ec\ub7ec \uc870\uac74 \uc911 \ud558\ub098\uc600\ub2e4. \ucd08\uae30 \ub9ac\ub178\ud0c0\uc774\ud504\ub294 1886\ub144 \ub274\uc695 \ud2b8\ub9ac\ubdf4\uc5d0 \ub4e4\uc5b4\uac14\uace0 \uc774\ud6c4 \uac1c\uc120\uc774 \uc774\uc5b4\uc84c\ub2e4. \uc5b4\ub290 \ub0a0 \uc644\ubcbd\ud55c \ucd5c\uc885\ud615\uc774 \ub098\ud0c0\ub098 \ubaa8\ub4e0 \uc870\ud310\uc744 \ubc14\uafbc \uac83\uc73c\ub85c \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc0c8\ub85c\uc6b4 \uae30\uacc4\uac00 \uc2e4\uc81c \uc0dd\uc0b0 \ud658\uacbd\uc5d0\uc11c \uc4f8 \ub9cc\ud574\uc9c0\ub294 \uacfc\uc815\uc5d0\ub294 \uc870\uc815\uacfc \ud22c\uc790\ub3c4 \ud544\uc694\ud588\ub2e4. \uc2e0\ubb38\uc0ac\uc5d0\ub294 \uae30\uacc4 \uad6c\uc785\ube44\uc640 \uacf5\uac04, \uc6b4\uc601\ud560 \uc0ac\ub78c\uc774 \uc694\uad6c\ub418\uc5c8\ub2e4. \uc18d\ub3c4\uac00 \ube68\ub77c\uc9c8 \uac00\ub2a5\uc131\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uacf3\uc774 \uac19\uc740 \ub54c \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ucc44\ud0dd\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubc1c\uba85\uc758 \uc5f0\ub3c4\uc640 \uc0b0\uc5c5 \uc804\uccb4\uc5d0 \ud37c\uc9c0\ub294 \uc2dc\uac04 \uc0ac\uc774\uc758 \ucc28\uc774\ub97c \ubcf4\uba74 \uae30\uc220 \ubcc0\ud654\uac00 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4. \uc774 \uae30\uacc4\ub294 \uc219\ub828\ub41c \uc870\ud310\uacf5\uc758 \uc791\uc5c5\uc744 \ubc14\uafb8\uc5c8\ub2e4. \uc190\uc73c\ub85c \ud65c\uc790\ub97c \uace0\ub974\ub358 \ub2a5\ub825\uacfc \ud0a4\ubcf4\ub4dc \uc785\ub825, \uae30\uacc4\uc758 \uc0c1\ud0dc\ub97c \ub2e4\ub8e8\ub294 \ub2a5\ub825\uc740 \uac19\uc9c0 \uc54a\ub2e4. \uc0dd\uc0b0\ub7c9\uc758 \uc99d\uac00\ub97c \ub9d0\ud558\uba74\uc11c\ub3c4 \ub204\uac00 \uc0c8 \uc77c\uc744 \ubc30\uc6b0\uace0 \uc5b4\ub5a4 \uacbd\ud5d8\uc774 \ub35c \uc911\uc694\ud574\uc84c\ub294\uc9c0 \ubb3c\uc744 \uc218 \uc788\ub2e4. \uc61b \uae30\uc220\uc0ac \ucc45\uc758 \ub180\ub77c\uc6b4 \uc0dd\uc0b0\uc131 \ubb18\uc0ac\ub97c \ubaa8\ub4e0 \uc778\uc1c4\uc18c\uc758 \uc815\ud655\ud55c \uc131\uacfc\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc791\uc5c5\uc758 \uc885\ub958\uc640 \uc6b4\uc601 \uc870\uac74\uc5d0 \ub530\ub77c \uacb0\uacfc\ub294 \ub2ec\ub77c\uc9c4\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uae30\uacc4\uac00 \ube68\ub77c\uc84c\ub2e4\ub294 \ud55c\ub9c8\ub514 \ub4a4\uc5d0 \ub178\ub3d9\uc758 \uc21c\uc11c\uc640 \ud544\uc694\ud55c \uc219\ub828\uc774 \uc7ac\ud3b8\ub418\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc774\ub2e4. \uc624\ub298 \ubb38\uc11c\ub97c \uc785\ub825\ud558\uba74 \uc904\ubc14\uafc8\uacfc \uac04\uaca9 \uc870\uc815\uc774 \ud654\uba74\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c4\ub2e4. \uadf8 \ubaa8\uc2b5\uacfc \ub9ac\ub178\ud0c0\uc774\ud504\uc758 \uc8fc\uc870\ub294 \ub2e4\ub974\uc9c0\ub9cc, \uc785\ub825\ud55c \ubb38\uc790\ub97c \uc778\uc1c4 \uac00\ub2a5\ud55c \ud615\ud0dc\ub85c \ubc14\uafb8\uc5b4\uc57c \ud55c\ub2e4\ub294 \uacfc\uc81c\ub294 \uc774\uc5b4\uc9c4\ub2e4. \uacfc\uac70\uc758 \uae30\uacc4\ub294 \uadf8 \ubb38\uc81c\ub97c \uae08\uc18d\uacfc \uc774\ub3d9 \uc7a5\uce58\ub85c \ud480\uc5c8\ub2e4. \ub9ac\ub178\ud0c0\uc774\ud504\ub97c \ubcf4\uba74 \uc790\ub3d9\ud654\ub294 \uc0ac\ub78c\uc758 \uc190\uc744 \uc904\uc774\ub294 \uc77c\uc5d0 \uadf8\uce58\uc9c0 \uc54a\ub294\ub2e4. \uc900\ube44\uc640 \uc0dd\uc0b0, \ub3c4\uad6c\uc758 \ud68c\uc218\uae4c\uc9c0 \ud558\ub098\uc758 \ud750\ub984\uc73c\ub85c \ubb36\ub294 \uc77c\uc774\ub2e4. \ub3c5\uc790\uc758 \uc544\uce68\ub3c4 \uc774 \uc0dd\uc0b0\uc758 \uc21c\uc11c\uc640 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc2e0\ubb38 \ud55c \uc7a5\uc758 \uc2dc\uac04\uc744 \ubc14\uafbc \uac83\uc740 \ube60\ub978 \uc778\uc1c4\uae30\ub9cc\uc774 \uc544\ub2c8\ub77c \ubb38\uc7a5\uc774 \ub9cc\ub4e4\uc5b4\uc838 \uc778\uc1c4\uae30\ub85c \ub3c4\ucc29\ud558\ub294 \uae38\uc758 \ubcc0\ud654\uc774\uae30\ub3c4 \ud588\ub2e4."}, {"id": "mccormick-reaper-and-harvest-window", "title": "\ub9e5\ucf54\ubbf9 \u2014 \uc218\ud655\ucca0\uc758 \uc9e7\uc740 \uc2dc\uac04\uc744 \uae30\uacc4\ub85c \ubc14\uafb8\ub2e4", "summary": "\ud5c8\uc2dc\uc640 \ub9e5\ucf54\ubbf9\uc758 \uacbd\uc7c1, \uace1\uc2dd\uc744 \ubca0\uace0 \ucc98\ub9ac\ud558\ub294 \uc791\uc5c5\uc758 \uc5f0\uacb0\uc5d0\uc11c \ub18d\uae30\uacc4 \uc0b0\uc5c5\uc758 \uc131\uc7a5\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\uacf5\uc7a5\uacfc \uc0dd\uc0b0", "categories": ["industry"], "url": "stories/mccormick-reaper-and-harvest-window/index.html", "image": "../media/mccormick-reaper-and-harvest-window.jpg", "alt": "1847\ub144\ud615 \ub9e5\ucf54\ubbf9 \uc218\ud655\uae30\ub97c \ubcf4\uc5ec \uc8fc\ub294 1900\ub144 \ucc45\uc758 \uc5ed\uc0ac \uadf8\ub9bc", "text": "\ub9e5\ucf54\ubbf9 \u2014 \uc218\ud655\ucca0\uc758 \uc9e7\uc740 \uc2dc\uac04\uc744 \uae30\uacc4\ub85c \ubc14\uafb8\ub2e4 \uacbd\uc7c1\ud558\ub294 \uc218\ud655\uae30\uc640 \uc791\uc5c5\uc758 \uc5f0\uacb0\uc5d0\uc11c \uc77d\ub294 \ub18d\uae30\uacc4 \uc0b0\uc5c5 \ud5c8\uc2dc\uc640 \ub9e5\ucf54\ubbf9\uc758 \uacbd\uc7c1, \uace1\uc2dd\uc744 \ubca0\uace0 \ucc98\ub9ac\ud558\ub294 \uc791\uc5c5\uc758 \uc5f0\uacb0\uc5d0\uc11c \ub18d\uae30\uacc4 \uc0b0\uc5c5\uc758 \uc131\uc7a5\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uacf5\uc7a5\uacfc \uc0dd\uc0b0 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \uace1\uc2dd\uc774 \uc798 \uc790\ub790\ub2e4\uace0 \ub18d\uc0ac\uac00 \ub05d\ub09c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc775\uc740 \uace1\uc2dd\uc744 \uc81c\ub54c \ubca0\uace0 \uac70\ub450\uc5b4\uc57c \ud55c\ub2e4. \ub113\uc740 \ubc2d \uc55e\uc5d0\uc11c \uc77c\uc190\uacfc \uc2dc\uac04\uc774 \ubaa8\uc790\ub77c\uba74 \ud48d\ub144\uc774 \uace7\ubc14\ub85c \uc88b\uc740 \uc218\uc785\uc73c\ub85c \uc774\uc5b4\uc9c0\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uc218\ud655\uae30\ub294 \uc774 \uc9e7\uc740 \uc2dc\uac04\uc758 \ubb38\uc81c\ub97c \uae30\uacc4\ub85c \ud480\ub824\ub294 \uc2dc\ub3c4\uc600\ub2e4. \uc0ac\uc774\ub7ec\uc2a4 \ub9e5\ucf54\ubbf9\uc758 \uc774\ub984\uc740 \uadf8 \uc5ed\uc0ac\uc5d0\uc11c \uc720\uba85\ud558\uc9c0\ub9cc \ud63c\uc790 \uac11\uc790\uae30 \uc644\uc131\ud488\uc744 \ub0b4\ub193\uc740 \uc774\uc57c\uae30\ub294 \uc544\ub2c8\ub2e4. \uc55e\uc120 \uc2e4\ud5d8\uacfc \uacbd\uc7c1\uc790\uc758 \uae30\uacc4, \uc2e4\uc81c \ubc2d\uc5d0\uc11c \ud544\uc694\ud55c \uac1c\uc120\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \ub0ab\uc73c\ub85c \ubca0\ub358 \uc791\uc5c5\uc774 \uc5b4\ub5bb\uac8c \uae30\uc5c5\uc774 \uc0dd\uc0b0\ud558\ub294 \uae30\uacc4\uc758 \uc77c\uc774 \ub418\uc5c8\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \ub18d\uc0ac\uc5d0\ub294 \uc5b4\ub5a4 \uc791\uc5c5\uc744 \ud560 \uc218 \uc788\ub294 \uc2dc\uae30\uac00 \uc788\ub2e4. \uc218\ud655\ub3c4 \uadf8\ub807\ub2e4. \ud544\uc694\ud55c \uc77c\uc744 \uc544\ubb34 \ub54c\ub098 \uc870\uae08\uc529 \ub098\ub204\uc5b4 \ucc98\ub9ac\ud560 \uc218 \uc5c6\ub2e4\uba74 \ud2b9\uc815\ud55c \ub54c\uc5d0 \ub9ce\uc740 \ub178\ub3d9\uc774 \ubab0\ub9b0\ub2e4. \uace1\uc2dd\uc744 \ubca0\ub294 \uc791\uc5c5\uc744 \ube60\ub974\uac8c \ud558\ub294 \uae30\uacc4\ub294 \ubc14\ub85c \uc774 \uc2dc\uac04\uc758 \uc555\ub825\uc744 \ubc14\uafb8\ub824 \ud588\ub2e4. \uadf8\ub798\uc11c \uc218\ud655\uae30\uc758 \uc758\ubbf8\ub97c \uc0ac\ub78c\ubcf4\ub2e4 \ud798\uc774 \uc138\ub2e4\ub294 \ub9d0\ub85c\ub9cc \uc124\uba85\ud558\uae30 \uc5b4\ub835\ub2e4. \uac19\uc740 \uae30\uac04\uc5d0 \uc5bc\ub9c8\ub098 \ub113\uc740 \uba74\uc801\uc744 \ucc98\ub9ac\ud560 \uc218 \uc788\ub294\uc9c0\uac00 \uc911\uc694\ud588\ub2e4. \uae30\uacc4\ub294 \ub178\ub3d9\ub7c9\ub9cc\uc774 \uc544\ub2c8\ub77c \ub18d\uc7a5\uc744 \uc6b4\uc601\ud560 \uc218 \uc788\ub294 \uaddc\ubaa8\uc640 \uc791\uc5c5 \uc21c\uc11c\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc8fc\uc5c8\ub2e4. \uc218\ud655\ucca0\uc758 \uc2dc\uac04\ud45c\uac00 \uae30\uc220\uc758 \uacbd\uc81c\uc801 \uac00\uce58\ub97c \ub9cc\ub4e0 \uc148\uc774\ub2e4. 19\uc138\uae30 \ucd08 \uc218\ud655\uae30\ub97c \ub9cc\ub4e4\ub824\ub294 \uc2dc\ub3c4\ub294 \uc5ec\ub7ec \uacf3\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc84c\ub2e4. \uc601\uad6d\uc758 \uc2e4\ud5d8\uacfc \ud328\ud2b8\ub9ad \ubca8\uc758 \uae30\uacc4\ub3c4 \uadf8 \ud750\ub984\uc5d0 \uc788\ub2e4. \uace1\uc2dd\uc744 \uc790\ub974\ub294 \ubd80\ubd84\ubfd0 \uc544\ub2c8\ub77c \ubca0\uc778 \uace1\uc2dd\uc744 \uc5b4\ub514\uc5d0 \ub193\uc744\uc9c0, \ub9d0\uc744 \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ud560\uc9c0\ub3c4 \ud574\uacb0\ud574\uc57c \ud588\ub2e4. \ub0ab\uc758 \uc6c0\uc9c1\uc784 \ud558\ub098\ub97c \ud06c\uac8c \ub9cc\ub4e4\uba74 \ub05d\ub098\ub294 \ubb38\uc81c\uac00 \uc544\ub2c8\uc5c8\ub2e4. \ub9e5\ucf54\ubbf9\uacfc \uac19\uc740 \uc2dc\uae30\uc5d0 \uc624\ubca0\ub4dc \ud5c8\uc2dc\ub3c4 \uc2e4\uc6a9\uc801\uc778 \uc218\ud655\uae30\ub97c \ubc1c\uc804\uc2dc\ucf30\ub2e4. \ub450 \uc774\ub984\uc744 \ud568\uaed8 \uae30\uc5b5\ud558\uba74 \uae30\uc220\uc758 \uc5ed\uc0ac\uac00 \ub354 \uc815\ud655\ud574\uc9c4\ub2e4. \ube44\uc2b7\ud55c \ud544\uc694\uac00 \uc5ec\ub7ec \uc0ac\ub78c\uc744 \uc6c0\uc9c1\uc774\uace0 \uc11c\ub85c \ub2e4\ub978 \ud574\ubc95\uc774 \uacbd\uc7c1\ud588\ub2e4. \ub098\uc911\uc5d0 \uc720\uba85\ud574\uc9c4 \uc0c1\ud45c\uac00 \uc55e\uc120 \uc2e4\ud5d8\uc758 \ud754\uc801\uae4c\uc9c0 \ubaa8\ub450 \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud5c8\uc2dc\ub294 1833\ub144, \ub9e5\ucf54\ubbf9\uc740 1834\ub144\uc5d0 \uad00\ub828 \ud2b9\ud5c8\ub97c \ubc1b\uc558\ub2e4. \uac01\uc790\uc758 \uae30\uacc4\uc5d0\ub294 \uace1\uc2dd\uc744 \uc790\ub974\uace0 \uc9c0\uc9c0\ud558\uace0 \ub098\ub204\ub294 \ubc29\uc2dd\uc758 \ucc28\uc774\uac00 \uc788\uc5c8\ub2e4. \ub9e5\ucf54\ubbf9\uc758 \ucd08\uae30 \ub3c4\uba74\uc5d0\ub294 \uace1\uc2dd\uc744 \uce7c\ub0a0 \ucabd\uc73c\ub85c \uc774\ub044\ub294 \ud68c\uc804 \uc7a5\uce58\uc640 \uc790\ub97c \ubd80\ubd84\uc744 \ub098\ub204\ub294 \uad6c\uc870 \ub4f1\uc774 \ub098\ud0c0\ub09c\ub2e4. \ub3c4\uba74\uc744 \uc77d\uc744 \ub54c\uc5d0\ub294 \uccab \uae30\uacc4\uac00 \ub098\uc911\uc758 \uc644\uc131\ud488\uacfc \ub611\uac19\uc558\ub2e4\uace0 \uc0c1\uc0c1\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\ub2e4. \ucd08\uae30\uc758 \uc77c\ubd80 \ubc29\uc2dd\uc740 \uc774\ud6c4 \ubc14\ub00c\uc5c8\ub2e4. \ud2b9\ud5c8\ub294 \uadf8 \uc2dc\uc810\uc758 \ud574\ubc95\uc744 \uae30\ub85d\ud55c\ub2e4. \uc2e4\uc81c \ud604\uc7a5\uc5d0\uc11c \uc4f0\uace0 \uace0\uce58\ub294 \uacfc\uc815\uae4c\uc9c0 \ud568\uaed8 \ubcf4\uc544\uc57c \uae30\uacc4\uac00 \uc65c \uadf8\ub7f0 \ubaa8\uc591\uc73c\ub85c \uc815\ucc29\ud588\ub294\uc9c0 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc2dc\uc5f0\uc5d0\uc11c \uc791\ub3d9\ud55c \uae30\uacc4\uac00 \uc5ec\ub7ec \ub18d\uc7a5\uc758 \uc870\uac74\uc5d0 \uc798 \ub9de\ub294\uc9c0\ub294 \ubcc4\ub3c4\uc758 \ubb38\uc81c\ub2e4. \uc791\ubb3c\uc758 \uc0c1\ud0dc\uc640 \uc9c0\ud615, \uc791\uc5c5\uc790\uac00 \ub2e4\ub8e8\ub294 \ubc29\uc2dd\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc790\ub974\ub294 \uae30\ub2a5\uc774 \uc88b\uc544\ub3c4 \uace1\uc2dd\uc774 \ucc98\ub9ac\ub418\ub294 \uc21c\uc11c\uac00 \ub9de\uc9c0 \uc54a\uc73c\uba74 \ub4a4\uc758 \uc77c\uc774 \ub9c9\ud790 \uc218 \uc788\ub2e4. \ub18d\uae30\uacc4\ub294 \uc804\uccb4 \uc791\uc5c5 \uc18d\uc5d0 \ub4e4\uc5b4\uac00\uc57c \ud588\ub2e4. \uc774\ub7f0 \uc870\uac74\uc740 \uae30\uacc4\ub97c \uacc4\uc18d \uac1c\uc120\ud560 \uc774\uc720\uac00 \ub41c\ub2e4. \uc131\uacf5\uc744 \ud55c \ubc88\uc758 \ubc1c\uba85 \ub0a0\uc9dc\ub85c\ub9cc \ud45c\uc2dc\ud558\uba74 \uc774\ud6c4\uc5d0 \uc313\uc778 \uc791\uc740 \ubcc0\uacbd\ub4e4\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \uc2dc\uc7a5\uc5d0\uc11c \uc0b4\uc544\ub0a8\uc740 \uae30\uacc4\ub294 \uc6d0\ub9ac\ub9cc\uc774 \uc544\ub2c8\ub77c \ubc18\ubcf5\ud574\uc11c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \ud615\ud0dc\ub97c \uac16\ucdb0\uc57c \ud588\ub2e4. \ubc1c\uba85\uc758 \uc5ed\uc0ac\uc640 \uc81c\ud488\uc758 \uc5ed\uc0ac\ub294 \uacb9\uce58\uba74\uc11c\ub3c4 \uac19\uc9c0 \uc54a\ub2e4. \uc218\ud655\uc740 \uace1\uc2dd\uc744 \ubca0\ub294 \uac83\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \ubaa8\uc73c\uace0 \ubb36\uace0 \ub2e4\uc74c \uc791\uc5c5\uc73c\ub85c \ub118\uaca8\uc57c \ud55c\ub2e4. \uc774\ud6c4\uc758 \ubc1c\uc804\uc5d0\ub294 \uc774\ub7f0 \ub3d9\uc791\uc744 \uae30\uacc4\uc640 \uacb0\ud569\ud558\ub294 \uc2dc\ub3c4\ub3c4 \ud3ec\ud568\ub41c\ub2e4. \ud55c \ubd80\ubd84\uc758 \uc18d\ub3c4\uac00 \ube68\ub77c\uc9c0\uba74 \ub2e4\ub978 \ubd80\ubd84\uc774 \uc0c8\ub85c\uc6b4 \ubcd1\ubaa9\uc73c\ub85c \ub4dc\ub7ec\ub098\ub294 \uac83\uc774\ub2e4. \uc774 \ud750\ub984\uc740 \uc0dd\uc0b0\uc758 \uc5ed\uc0ac\ub97c \uc77d\ub294 \ub370 \uc720\uc6a9\ud558\ub2e4. \uc77c\uc744 \ud558\ub098 \uc790\ub3d9\ud654\ud588\ub2e4\uace0 \uc804\uccb4\uac00 \ub611\uac19\uc774 \ube68\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc55e\ub4a4\uc758 \uc791\uc5c5\uc744 \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ud558\ub294\uc9c0\uc5d0 \ub530\ub77c \ud6a8\uacfc\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uc218\ud655\uae30\ub97c \ubcf4\uba74 \uae30\uacc4 \ud55c \ub300\uc758 \uae30\ub2a5\uacfc \uadf8 \uae30\uacc4\uac00 \ub4e4\uc5b4\uac00\ub294 \uc791\uc5c5 \uccb4\uacc4\ub97c \ud568\uaed8 \uc0b4\ud3b4\uc57c \ud55c\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c \uc218 \uc788\ub2e4. \uc88b\uc740 \uc7a5\uce58\ub97c \uc0dd\uac01\ud574 \ub0b8 \ub4a4\uc5d0\ub294 \uadf8\uac83\uc744 \ubc18\ubcf5\ud574\uc11c \ub9cc\ub4e4\uace0 \ud310\ub9e4\ud574\uc57c \ud55c\ub2e4. \uc81c\ud488\uc774 \ub41c \uae30\uacc4\ub294 \ud55c \ubc88\uc758 \uc2e4\ud5d8\uacfc \ub2ec\ub9ac \uc5ec\ub7ec \uc0ac\uc6a9\uc790\uac00 \ub2e4\ub8ec\ub2e4. \uc81c\uc791\uc758 \uc77c\uad00\uc131\uacfc \uac1c\uc120\uc774 \uae30\uc5c5\uc758 \uc77c\uc774 \ub41c\ub2e4. \ub9e5\ucf54\ubbf9\uc758 \uc774\ub984\uc774 \ubc1c\uba85\uc0ac\uc640 \uae30\uc5c5\uc0ac \uc591\ucabd\uc5d0 \ub4f1\uc7a5\ud558\ub294 \uc774\uc720\ub3c4 \uc774 \uacfc\uc815\uacfc \uc5f0\uacb0\ub41c\ub2e4. \ub18d\uc7a5\uc740 \uae30\uacc4\ub97c \uc2e4\uc81c \uc218\ud655\uc5d0 \uc0ac\uc6a9\ud560 \uc218 \uc788\uc744 \ub54c \uac12\uc744 \uce58\ub97c \uc774\uc720\ub97c \uc5bb\ub294\ub2e4. \uc81c\uc870\uc5c5\uccb4\uc758 \uc2dc\uac04\uacfc \ub18d\ubd80\uc758 \uc2dc\uac04\uc774 \ub9cc\ub098\ub294 \uac83\uc774\ub2e4. \uc218\ud655\uc774 \uae09\ud55c \uacc4\uc808\uc5d0 \uc81c\ub300\ub85c \uc6c0\uc9c1\uc5ec\uc57c \ud558\ub294 \ubb3c\uac74\uc774\ub77c\ub294 \ud2b9\uc131\uc774 \uc81c\ud488\uc758 \uc758\ubbf8\ub97c \uc815\ud55c\ub2e4. \ub18d\uae30\uacc4\uc758 \uc0b0\uc5c5\uc740 \ubc2d\uacfc \ub5a8\uc5b4\uc9c4 \uacf5\uc7a5 \uc548\uc5d0\uc11c\ub9cc \uc644\uc131\ub418\uc9c0 \uc54a\uc558\ub2e4. \uc218\ud655\uae30\uc758 \ubc1c\uc804\uc740 \ud55c \uc0ac\ub78c\uc774 \ud560 \uc218 \uc788\ub294 \uc77c\uc758 \ubc94\uc704\ub97c \ubc14\uafb8\uace0 \ub300\uaddc\ubaa8 \uace1\ubb3c \uc0dd\uc0b0\uacfc \uc5f0\uacb0\ub418\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \uc774\ub97c \ubaa8\ub4e0 \ub18d\ubbfc\uc774 \uac19\uc740 \ud61c\ud0dd\uc744 \uc5bb\uc740 \uc774\uc57c\uae30\ub85c \ub2e8\uc21c\ud654\ud560 \uc218\ub294 \uc5c6\ub2e4. \uae30\uacc4\ub97c \ub9c8\ub828\ud558\uace0 \uc0ac\uc6a9\ud560 \uc870\uac74, \ub18d\uc7a5\uc758 \uaddc\ubaa8\uc640 \ub2e4\ub978 \uc791\uc5c5\uc758 \ub2a5\ub825\uc774 \uc11c\ub85c \ub2ec\ub790\ub2e4. \uce7c\ub0a0 \uc55e\uc5d0 \uace1\uc2dd\uc744 \ubaa8\uc73c\uace0 \uc790\ub97c \ubd80\ubd84\uc744 \ub098\ub204\ub294 \uad6c\uc870\ub97c \ubcf4\uba74, \uc218\ud655\uae30\uc758 \uacfc\uc81c\uac00 \ub2e8\uc21c\ud55c \ud798\uaca8\ub8e8\uae30\uac00 \uc544\ub2c8\uc5c8\uc74c\uc744 \uc54c \uc218 \uc788\ub2e4. \uc791\ubb3c\uc774 \uae30\uacc4\uc5d0 \ub4e4\uc5b4\uc624\ub294 \uc21c\uc11c\ub97c \uc815\ub9ac\ud574\uc57c \ud588\ub2e4. \ubc2d\uc758 \ubd88\uaddc\uce59\ud55c \ub300\uc0c1\uc744 \ubc18\ubcf5 \uac00\ub2a5\ud55c \uc791\uc5c5\uc73c\ub85c \ubc14\uafb8\ub294 \uc124\uacc4\uac00 \uc911\uc694\ud588\ub358 \uac83\uc774\ub2e4. \ub9e5\ucf54\ubbf9\uc744 \uae30\uc5b5\ud560 \ub54c\uc5d0\ub294 \uc720\uba85\ud55c \ubc1c\uba85\uac00\uc758 \uc5bc\uad74 \uc606\uc5d0 \uc218\ud655\ucca0\uc758 \ubc2d\uc744 \ub193\uc544 \ubcf4\uc790. \uace1\uc2dd\uc774 \uc775\ub294 \uc18d\ub3c4\uc640 \uc0ac\ub78c\uc758 \uc77c\uc190, \uae30\uacc4 \uc81c\uc791\uacfc \uae30\uc5c5\uc758 \uc131\uc7a5\uc774 \ud568\uaed8 \ubcf4\uc778\ub2e4. \uae30\uc220\uc740 \uc790\uc5f0\uc758 \uc2dc\uac04\uc744 \uc5c6\uc564 \uac83\uc774 \uc544\ub2c8\ub77c \uadf8 \uc2dc\uac04 \uc548\uc5d0\uc11c \uc0ac\ub78c\uc774 \ud560 \uc218 \uc788\ub294 \uc77c\uc744 \ub2e4\uc2dc \uc870\uc9c1\ud588\ub2e4."}, {"id": "netflix-envelope-to-streaming", "title": "\ub137\ud50c\ub9ad\uc2a4 \u2014 \uc601\ud654\uac00 \uc6b0\ud3b8\ud568\uc5d0\uc11c \ud654\uba74\uc73c\ub85c \uc62e\uaca8 \uc624\uae30\uae4c\uc9c0", "summary": "DVD \uc6b0\ud3b8 \ub300\uc5ec\uc5d0\uc11c \uc2a4\ud2b8\ub9ac\ubc0d\uc73c\ub85c \uc62e\uaca8 \uac04 \uc0ac\ub840\ub97c \ud1b5\ud574 \uc11c\ube44\uc2a4\uc758 \ubcc0\ud654\uc640 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc870\uac74\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\uc0c1\uc5c5\uacfc \uc720\ud1b5", "categories": ["industry"], "url": "stories/netflix-envelope-to-streaming/index.html", "image": "../media/netflix-envelope-to-streaming.png", "alt": "\uc6b0\ud3b8 \ubd09\ud22c \uc18d DVD\uc640 \ub178\ud2b8\ubd81, TV\uac00 \ub193\uc778 \uac70\uc2e4\uc5d0\uc11c \uc601\ud654\ub97c \uace0\ub974\ub294 AI \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ub137\ud50c\ub9ad\uc2a4 \u2014 \uc601\ud654\uac00 \uc6b0\ud3b8\ud568\uc5d0\uc11c \ud654\uba74\uc73c\ub85c \uc62e\uaca8 \uc624\uae30\uae4c\uc9c0 \uac19\uc740 \uc601\ud654\ub97c \ubcf4\ub294 \uc77c\ub3c4 \ub3c4\ucc29\ud558\ub294 \ubc29\ubc95\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c4\ub2e4 DVD \uc6b0\ud3b8 \ub300\uc5ec\uc5d0\uc11c \uc2a4\ud2b8\ub9ac\ubc0d\uc73c\ub85c \uc62e\uaca8 \uac04 \uc0ac\ub840\ub97c \ud1b5\ud574 \uc11c\ube44\uc2a4\uc758 \ubcc0\ud654\uc640 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc870\uac74\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc0c1\uc5c5\uacfc \uc720\ud1b5 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \uc624\ub298 \uc800\ub141 \uc601\ud654\ub97c \uace0\ub978 \ub4a4 \uc7ac\uc0dd \ubc84\ud2bc\uc744 \ub204\ub978\ub2e4. \uc7a0\uc2dc \ud6c4 \ud654\uba74\uc774 \uc6c0\uc9c1\uc774\uba74 \uc601\ud654\uac00 \ub3c4\ucc29\ud588\ub2e4\ub294 \uc0dd\uac01\uc870\ucc28 \ud558\uc9c0 \uc54a\ub294\ub2e4. \ud558\uc9c0\ub9cc \uac19\uc740 \uc601\ud654\ub97c \ubcf4\uae30 \uc704\ud574 \uc791\uc740 \uc6d0\ubc18\uc774 \uc9d1\uae4c\uc9c0 \uc624\uae30\ub97c \uae30\ub2e4\ub9ac\ub358 \ubc29\uc2dd\ub3c4 \uc788\uc5c8\ub2e4. \ub137\ud50c\ub9ad\uc2a4\uc758 \ucd9c\ubc1c\uc740 \uc9c0\uae08\uc758 \ud654\uba74\ubcf4\ub2e4 \uc6b0\ud3b8\ud568\uc5d0 \uac00\uae4c\uc6e0\ub2e4. 1997\ub144 \uc124\ub9bd\ub41c \ub137\ud50c\ub9ad\uc2a4\ub294 \uc628\ub77c\uc778 DVD \ub300\uc5ec\uc5d0\uc11c \ucd9c\ubc1c\ud588\ub2e4. \uc778\ud130\ub137\uc5d0\uc11c \uace0\ub974\uace0 \ubb3c\ub9ac\uc801\uc778 \ub514\uc2a4\ud06c\ub97c \ubc1b\uc544 \ubcf4\ub294 \uc0ac\uc5c5\uc774\ub2e4. \uc774 \ud68c\uc0ac\uc758 \ubcc0\ud654\ub294 \uc601\ud654 \ubaa9\ub85d\uc774 \ub9ce\uc544\uc9c4 \uc774\uc57c\uae30\uc774\uae30\ub3c4 \ud558\uc9c0\ub9cc, \ub354 \ud765\ubbf8\ub85c\uc6b4 \uc9c8\ubb38\uc740 \ub530\ub85c \uc788\ub2e4. \uace0\uac1d\uc774 \ubb34\uc5c7\uc744 \uae30\ub2e4\ub824\uc57c \ud558\ub294\uc9c0\uac00 \uc5b4\ub5bb\uac8c \ub2ec\ub77c\uc84c\uc744\uae4c. \uc628\ub77c\uc778\uc774\ub77c\ub294 \ub9d0\uc774 \ubd99\uc5c8\ub2e4\uace0 \ucc98\uc74c\ubd80\ud130 \ubaa8\ub4e0 \uac83\uc774 \ud654\uba74 \uc548\uc5d0\uc11c \ub05d\ub09c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc120\ud0dd\uacfc \uc8fc\ubb38\uc740 \uc778\ud130\ub137\uc73c\ub85c \ud560 \uc218 \uc788\uc5b4\ub3c4 \uc601\uc0c1\uc744 \ub2f4\uc740 DVD\ub294 \uc2e4\uc81c \uc7a5\uc18c\uc5d0 \ubcf4\uad00\ud574\uc57c \ud588\ub2e4. \ud3ec\uc7a5\ud558\uace0 \ubcf4\ub0b4\ub294 \uc77c, \uace0\uac1d\uc5d0\uac8c \ub3c4\ucc29\ud558\ub294 \ub370 \uac78\ub9ac\ub294 \uc2dc\uac04\uc774 \uc11c\ube44\uc2a4\uc758 \uc77c\ubd80\uc600\ub2e4. \uc774 \ubc29\uc2dd\uc5d0\uc11c\ub294 \uc601\ud654\uc758 \ub0b4\uc6a9\ub9cc\ud07c \uc774\ub3d9\ub3c4 \uc911\uc694\ud558\ub2e4. \ubcf4\uace0 \uc2f6\uc740 \uc791\ud488\uc744 \ubc1c\uacac\ud558\ub294 \uac83\uacfc \uc624\ub298 \ubc14\ub85c \ubcfc \uc218 \uc788\ub294 \uac83\uc740 \ub2e4\ub978 \ubb38\uc81c\ub2e4. \uace0\uac1d\uc758 \uacbd\ud5d8\uc744 \ubc14\uafb8\ub824\uba74 \uc88b\uc740 \ubaa9\ub85d\ubfd0 \uc544\ub2c8\ub77c \ubb3c\uac74\uc774 \uc624\uac00\ub294 \ud750\ub984\ub3c4 \uc798 \ub9cc\ub4e4\uc5b4\uc57c \ud588\ub2e4. \ub514\uc9c0\ud138 \uc8fc\ubb38\uacfc \ubb3c\ub9ac\uc801\uc778 \uc720\ud1b5\uc774 \uacb9\uccd0 \uc788\ub294 \uc0ac\uc5c5\uc774\uc5c8\ub358 \uc148\uc774\ub2e4. \ub137\ud50c\ub9ad\uc2a4\ub294 2007\ub144 \uc2a4\ud2b8\ub9ac\ubc0d \uc11c\ube44\uc2a4\ub97c \uc2dc\uc791\ud588\ub2e4. \uc778\ud130\ub137\uc744 \ud1b5\ud574 \uc601\uc0c1 \ub370\uc774\ud130\ub97c \ubc1b\uc544 \ubcf4\uac8c \ub41c \uac83\uc774\ub2e4. \uc0ac\uc6a9\uc790\uc758 \uc785\uc7a5\uc5d0\uc11c\ub294 \ub514\uc2a4\ud06c\uac00 \ub3c4\ucc29\ud574\uc57c \ubcfc \uc218 \uc788\ub358 \uc0c1\ud669\uc5d0\uc11c, \uc5f0\uacb0 \uc0c1\ud0dc\uac00 \ud5c8\ub77d\ud558\uba74 \uace7\ubc14\ub85c \uc7ac\uc0dd\ud560 \uc218 \uc788\ub294 \ubc29\uc2dd\uc73c\ub85c \ubc14\ub00c\uc5c8\ub2e4. \uc774 \ubcc0\ud654\uac00 \uac00\ub2a5\ud55c \ubc30\uacbd\uc5d0\ub294 \ud1b5\uc2e0 \uc18d\ub3c4\uc640 \uae30\uc220\uc758 \ubc1c\uc804\uc774 \uc788\uc5c8\ub2e4. \uc544\uc774\ub514\uc5b4\uac00 \uba3c\uc800 \uc874\uc7ac\ud574\ub3c4 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uc548\uc815\uc801\uc73c\ub85c \uc774\uc6a9\ud560 \uc870\uac74\uc774 \uac16\ucd94\uc5b4\uc9c0\uc9c0 \uc54a\uc73c\uba74 \uc11c\ube44\uc2a4\uac00 \ub418\uae30 \uc5b4\ub835\ub2e4. \uae30\uc5c5\uc758 \uc120\ud0dd\uacfc \uadf8 \ubc14\uae65\uc5d0\uc11c \ubc1c\uc804\ud558\ub294 \uae30\uc220\uc774 \uc5b4\ub290 \uc2dc\uc810\uc5d0 \ub9cc\ub0ac\ub294\uc9c0\ub97c \ud568\uaed8 \ubcf4\uc544\uc57c \ud558\ub294 \uc774\uc720\ub2e4. \uc2a4\ud2b8\ub9ac\ubc0d\uc73c\ub85c \ubc14\uafb8\uba74 \ud3ec\uc7a5\uacfc \ubc30\uc1a1\uc5d0 \uad00\ud55c \uc77c\ubd80 \ubb38\uc81c\uac00 \uc904\uc5b4\ub4e0\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc601\ud654\uac00 \uc544\ubb34\ub7f0 \uc900\ube44 \uc5c6\uc774 \ud558\ub298\uc5d0\uc11c \ub0b4\ub824\uc624\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc601\uc0c1\uc744 \uc804\ub2ec\ud558\ub294 \uc124\ube44\uc640 \ud1b5\uc2e0\ub9dd, \uc7ac\uc0dd\ud558\ub294 \uae30\uae30\uc640 \uc18c\ud504\ud2b8\uc6e8\uc5b4\uac00 \uc0c8\ub85c\uc6b4 \uc870\uac74\uc774 \ub41c\ub2e4. \uac00\ub839 \uc6b0\ud3b8\uc744 \uae30\ub2e4\ub9ac\ub294 \uc2dc\uac04\uc740 \uc5c6\uc5b4\uc84c\uc5b4\ub3c4 \uc5f0\uacb0\uc774 \ubd88\uc548\uc815\ud558\uba74 \uc7ac\uc0dd\uc774 \ub04a\uae38 \uc218 \uc788\ub2e4. \ubc14\ub010 \uac83\uc740 \ubd88\ud3b8\ud568\uc774 \ubaa8\ub450 \uc0ac\ub77c\uc84c\ub2e4\ub294 \uc0ac\uc2e4\ubcf4\ub2e4, \uc5b4\ub5a4 \ubd80\ubd84\uc744 \uc798 \uc900\ube44\ud574\uc57c \uace0\uac1d\uc774 \ud3b8\ub9ac\ud568\uc744 \ub290\ub07c\ub294\uc9c0\ub2e4. \uc81c\ud488\uc744 \ub2f4\ub294 \uadf8\ub987\uc774 \ubc14\ub00c\uba74 \uc11c\ube44\uc2a4\uc758 \uc77c\uac70\ub9ac\ub3c4 \ud568\uaed8 \uc774\ub3d9\ud55c\ub2e4. \ub137\ud50c\ub9ad\uc2a4\ub294 2010\ub144 \uce90\ub098\ub2e4\uc5d0 \uc2a4\ud2b8\ub9ac\ubc0d \uc11c\ube44\uc2a4\ub97c \uc81c\uacf5\ud558\uba70 \ud574\uc678 \uc9c4\ucd9c\uc744 \uc2dc\uc791\ud588\ub2e4. \ub514\uc2a4\ud06c\ub97c \uba3c \uacf3\uae4c\uc9c0 \ubcf4\ub0b4\ub294 \ubc29\uc2dd\uacfc \ub2ec\ub9ac \uc628\ub77c\uc778 \uc11c\ube44\uc2a4\ub294 \ub2e4\ub978 \uc2dc\uc7a5\uc73c\ub85c \ud655\uc7a5\ud560 \uc5ec\uc9c0\uac00 \ucef8\ub2e4. \uadf8\ub7ec\ub098 \uad6d\uacbd\uc744 \ub118\ub294 \uc77c\uc774 \ub2e8\uc21c\ud788 \uc6f9\uc0ac\uc774\ud2b8\uc758 \ubb38\uc744 \uc5f4\uc5b4 \ub450\ub294 \uac83\uacfc \uac19\uc9c0\ub294 \uc54a\uc558\ub2e4. \ud604\uc9c0\uc758 \uc778\ud130\ub137 \ud658\uacbd\uacfc \uaddc\uc81c, \uc0ac\ub78c\ub4e4\uc774 \uc88b\uc544\ud558\ub294 \uc791\ud488\uc774 \ub2ec\ub790\ub2e4. \uad50\uc7ac\ub294 \ud604\uc9c0 \ucf58\ud150\uce20 \uc81c\uc791\uacfc \uc791\ud488\uc758 \uad8c\ub9ac \ud655\ubcf4, \ud1b5\uc2e0\uc5c5\uccb4\uc640\uc758 \ud611\ub825, \uac00\uaca9\uacfc \uc694\uae08\uc81c \uc870\uc815\uc744 \uc774\ub7f0 \ubb38\uc81c\uc5d0 \ub300\uc751\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \uace0\uac1d\uc740 \ube44\uc2b7\ud55c \uc7ac\uc0dd \ubc84\ud2bc\uc744 \ub20c\ub7ec\ub3c4 \uadf8 \ub4a4\uc758 \uc900\ube44\ub294 \uc9c0\uc5ed\ub9c8\ub2e4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \uc628\ub77c\uc778\uc5d0\uc11c \uc804\ub2ec\ud560 \uc218 \uc788\ub2e4\ub294 \uac83\uacfc \uc5b4\ub290 \ub098\ub77c\uc5d0\uc11c\ub098 \uac19\uc740 \uc791\ud488\uc744 \uc81c\uacf5\ud560 \uad8c\ub9ac\uac00 \uc788\ub2e4\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uc791\ud488\uc758 \uc774\uc6a9 \uad8c\ub9ac\ub97c \ud655\ubcf4\ud558\ub294 \uc77c\uc774 \ubcc4\ub3c4\ub85c \ud544\uc694\ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \uc138\uacc4\ub85c \ud655\uc7a5\ud558\ub294 \uc11c\ube44\uc2a4\uac00 \uae30\uc220 \ubb38\uc81c\ub9cc \ud574\uacb0\ud558\uba74 \ub41c\ub2e4\uace0 \uc0dd\uac01\ud560 \ub54c \ub193\uce58\uae30 \uc26c\uc6b4 \ub300\ubaa9\uc774\ub2e4. \uc5b8\uc5b4\uc640 \ubb38\ud654\uc758 \ubb38\uc81c\ub3c4 \uc788\ub2e4. \ub2e4\ub978 \ub098\ub77c\uc5d0\uc11c \uc778\uae30 \uc788\ub294 \uc791\ud488\uc744 \uadf8\ub300\ub85c \ubaa8\uc544 \ub193\ub294 \uac83\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc9c0\uc5ed\uc758 \uad00\uac1d\uc774 \uac19\uc740 \uad00\uc2ec\uc744 \ubcf4\uc774\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc9c0\uc5ed\uc758 \uc774\uc57c\uae30\ub97c \uc81c\uc791\ud558\uac70\ub098 \ud655\ubcf4\ud558\ub294 \uc120\ud0dd\uc740 \ubc88\uc5ed\uc744 \ud55c \uc904 \ub354 \ubd99\uc774\ub294 \uc77c\ubcf4\ub2e4 \ub113\ub2e4. \ubb34\uc5c7\uc744 \ubcf4\uc5ec \uc904 \uac83\uc778\uc9c0 \uc790\uccb4\uac00 \uc2dc\uc7a5\uacfc \ud568\uaed8 \ubc14\ub010\ub2e4. \uc774 \uc0ac\ub840\uc5d0\uc11c \ud68c\uc0ac\ub294 \uacc4\uc18d \uc601\ud654\ub97c \ubcf4\ub294 \uacbd\ud5d8\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc6b0\ud3b8 \ub300\uc5ec\uc640 \uc2a4\ud2b8\ub9ac\ubc0d\uc5d0\ub294 \ub2e4\ub978 \uae30\uc220\uacfc \uc6b4\uc601 \ub2a5\ub825\uc774 \ud544\uc694\ud558\ub2e4. \uace0\uac1d\uc774 \uc5bb\uc73c\ub824\ub294 \uc990\uac70\uc6c0\uc774 \ube44\uc2b7\ud574\ub3c4, \ud68c\uc0ac\uac00 \uadf8 \uc990\uac70\uc6c0\uc744 \ub9cc\ub4e4\uc5b4 \ub0b4\ub294 \ubc29\ubc95\uc740 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \uae30\uc5c5\uc744 \uc9c0\uae08 \ud30c\ub294 \ubb3c\uac74\uc758 \uc774\ub984\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uba74 \ubcc0\ud654\uac00 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. DVD\ub97c \ubcf4\ub0b4\ub294 \ud68c\uc0ac\ub77c\uace0\ub9cc \uc0dd\uac01\ud558\uba74 \uc2a4\ud2b8\ub9ac\ubc0d\uc740 \ub0af\uc120 \uc77c\uc774\uc9c0\ub9cc, \uc9d1\uc5d0\uc11c \ubcf4\uace0 \uc2f6\uc740 \uc601\ud654\ub97c \uace0\ub974\uac8c \ud558\ub294 \uc11c\ube44\uc2a4\ub85c \ubcf4\uba74 \uc774\uc5b4\uc9c0\ub294 \ubd80\ubd84\ub3c4 \ubcf4\uc778\ub2e4. \ubb34\uc5c7\uc744 \uc720\uc9c0\ud558\uace0 \ubb34\uc5c7\uc744 \ubc14\uafc0\uc9c0 \uc815\ud558\ub294 \uac83\uc774 \uc0ac\uc5c5 \uc804\ud658\uc758 \ud575\uc2ec \uc9c8\ubb38\uc774 \ub41c\ub2e4. \ud604\uc7ac\uc758 \ubaa8\uc2b5\uc5d0\uc11c \uacfc\uac70\ub97c \uac70\uafb8\ub85c \ubcf4\uba74 \uc2a4\ud2b8\ub9ac\ubc0d \uc804\ud658\uc774 \ub108\ubb34 \ub2f9\uc5f0\ud574 \ubcf4\uc77c \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ud55c \uc0b0\uc5c5\uc758 \ubcc0\ud654\ub294 \uae30\uc220, \ube44\uc6a9\uacfc \uad8c\ub9ac, \uace0\uac1d\uc758 \uc2b5\uad00\uc774 \ud568\uaed8 \uc6c0\uc9c1\uc774\ub294 \uacfc\uc815\uc774\ub2e4. \uae30\uc5c5\uc774 \ud55c \ubc88\uc758 \uba4b\uc9c4 \uacb0\ub2e8\uc73c\ub85c \ubaa8\ub4e0 \ubb38\uc81c\ub97c \ub05d\ub0c8\ub2e4\ub294 \uc774\uc57c\uae30\ub85c \uc904\uc77c \uc218\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c\ub294 \ud655\uc778\ud55c \ucd08\ucc3d\uae30\uc640 \uc804\ud658 \uacfc\uc815\uc5d0 \ucd08\uc810\uc744 \ub9de\ucdc4\ub2e4. \ud604\uc7ac \uac00\uc785\uc790 \uc218\ub098 \uad6d\uac00\ubcc4 \uc791\ud488 \ubaa9\ub85d, \uc694\uae08\uc740 \ubcc4\ub3c4\uc758 \ucd5c\uc2e0 \uc790\ub8cc\uac00 \ud544\uc694\ud55c \uc815\ubcf4\ub2e4. \uc5ed\uc0ac\uc801 \uc0ac\ub840\ub97c \uc774\ud574\ud558\ub294 \uac83\uacfc \uc624\ub298 \uac00\uc785\ud560 \uc11c\ube44\uc2a4\ub97c \ube44\uad50\ud558\ub294 \uac83\uc740 \ub2e4\ub978 \uc791\uc5c5\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc2e4\uc81c \ub137\ud50c\ub9ad\uc2a4 \ubd09\ud22c\ub098 \ub2f9\uc2dc \ud654\uba74\uc744 \ubcf5\uc6d0\ud55c \uc790\ub8cc\uac00 \uc544\ub2c8\ub2e4. \ub514\uc2a4\ud06c\uc640 \uc6b0\ud3b8, \uc9d1 \uc548\uc758 \uc2dc\uccad \uacbd\ud5d8\uc774 \uc774\uc5b4\uc9c0\ub358 \ubd84\uc704\uae30\ub97c \ud45c\ud604\ud588\ub2e4. \uadf8\ub9bc\uc744 \ubcf4\uba70 \uc6d0\ubc18 \ud55c \uc7a5\uc774 \uc6c0\uc9c1\uc774\ub358 \uac70\ub9ac\uc640, \uc9c0\uae08 \uc7ac\uc0dd \ubc84\ud2bc \ub4a4\uc5d0\uc11c \uc6c0\uc9c1\uc774\ub294 \ub370\uc774\ud130\ub97c \ubc88\uac08\uc544 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ub137\ud50c\ub9ad\uc2a4\uc758 \ubcc0\ud654\ub294 \ubb3c\uac74\uc744 \uc5c6\uc564 \ud68c\uc0ac\uc758 \uc774\uc57c\uae30\ub85c\ub9cc \ub0a8\uc9c0 \uc54a\ub294\ub2e4. \uac19\uc740 \uc800\ub141\uc758 \uc990\uac70\uc6c0\uc744 \uc704\ud574 \uc5b4\ub5a4 \uc900\ube44\uac00 \ud544\uc694\ud55c\uc9c0\uac00 \ub2ec\ub77c\uc9c4 \uc774\uc57c\uae30\ub2e4. \ub2e4\uc74c\uc5d0 \uc601\ud654\ub97c \uc7ac\uc0dd\ud560 \ub54c\ub294 \uc791\ud488\uc758 \uccab \uc7a5\uba74\uacfc \ud568\uaed8, \uadf8 \uc7a5\uba74\uc774 \ub0b4 \uc55e\uc5d0 \ub3c4\ucc29\ud558\ub294 \ubc29\ubc95\ub3c4 \uc7a0\uae50 \uc0dd\uac01\ud574 \ubcfc \ub9cc\ud558\ub2e4."}, {"id": "patagonia-climbing-gear-and-rock", "title": "\ud30c\ud0c0\uace0\ub2c8\uc544 \u2014 \uc798 \ud314\ub9ac\ub294 \uc7a5\ube44\ub97c \uc65c \ubc14\uafb8\ub824 \ud588\uc744\uae4c", "summary": "\uc774\ubcf8 \uc26c\ub098\ub4dc\uc758 \ub4f1\ubc18 \uc7a5\ube44 \uc0ac\uc5c5\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc81c\ud488\uc758 \uc131\uacf5\uacfc \ud658\uacbd\uc758 \ubd80\ub2f4\uc744 \ud568\uaed8 \uc0dd\uac01\ud569\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\ube0c\ub79c\ub4dc\uc640 \uc18c\ube44", "categories": ["industry"], "url": "stories/patagonia-climbing-gear-and-rock/index.html", "image": "../media/patagonia-climbing-gear-and-rock.png", "alt": "\ub4f1\ubc18\uc6a9 \uae08\uc18d \uc7a5\ube44\uc640 \ubc27\uc904, \uc57c\uc678 \uc758\ub958\uac00 \ub193\uc778 \uc791\uc5c5\ub300\uc758 AI \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ud30c\ud0c0\uace0\ub2c8\uc544 \u2014 \uc798 \ud314\ub9ac\ub294 \uc7a5\ube44\ub97c \uc65c \ubc14\uafb8\ub824 \ud588\uc744\uae4c \ubc14\uc704\ub97c \uc88b\uc544\ud558\ub294 \uc0ac\ub78c\uc774 \ubc14\uc704\uc5d0 \ub0a8\uae34 \ud754\uc801\uc744 \ubcf4\uac8c \ub418\ub2e4 \uc774\ubcf8 \uc26c\ub098\ub4dc\uc758 \ub4f1\ubc18 \uc7a5\ube44 \uc0ac\uc5c5\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc81c\ud488\uc758 \uc131\uacf5\uacfc \ud658\uacbd\uc758 \ubd80\ub2f4\uc744 \ud568\uaed8 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ube0c\ub79c\ub4dc\uc640 \uc18c\ube44 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \uc88b\uc544\ud558\ub294 \uc77c\uc744 \uacc4\uc18d\ud558\uae30 \uc704\ud574 \uc791\uc740 \ub3c4\uad6c\ub97c \ub9cc\ub4e4\uc5b4 \ud310\ub2e4. \uadf8 \ub3c4\uad6c\uac00 \uc798 \ud314\ub9ac\uae30 \uc2dc\uc791\ud558\uba74 \ubcf4\ud1b5\uc740 \uae30\ubed0\ud560 \uc77c\uc774\ub2e4. \uadf8\ub7f0\ub370 \ub354 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uc0ac\uc6a9\ud560\uc218\ub85d \uc790\uc2e0\uc774 \uc88b\uc544\ud558\ub294 \uc7a5\uc18c\uac00 \uc190\uc0c1\ub41c\ub2e4\uba74 \uc5b4\ub5a8\uae4c. \uc81c\ud488\uc774 \uc131\uacf5\ud558\uace0 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub9c8\uc74c \ud3b8\ud55c \uc18c\uc2dd\ub9cc\uc740 \uc544\ub2c8\uac8c \ub41c\ub2e4. \ud30c\ud0c0\uace0\ub2c8\uc544\uc758 \ucc3d\ub9bd\uc790 \uc774\ubcf8 \uc26c\ub098\ub4dc\uc758 \uc774\uc57c\uae30\uc5d0\ub294 \uc774\ub7f0 \uc7a5\uba74\uc774 \uc788\ub2e4. \uc57c\uc678 \uc758\ub958 \ube0c\ub79c\ub4dc\ub85c \uc775\uc219\ud558\uc9c0\ub9cc \uadf8 \ucd9c\ubc1c\uc744 \uac70\uc2ac\ub7ec \uc62c\ub77c\uac00\uba74 \uc637\ubcf4\ub2e4 \uba3c\uc800 \ubc14\uc704\uc640 \ub4f1\ubc18 \uc7a5\ube44\ub97c \ub9cc\ub09c\ub2e4. \uc774 \uc0ac\ub840\uac00 \ud765\ubbf8\ub85c\uc6b4 \uae4c\ub2ed\uc740 \ud658\uacbd\uc744 \uc544\ub07c\uc790\ub294 \ub9d0\uc774 \uc2e4\uc81c\ub85c \ubb34\uc5c7\uc744 \ud314\uc9c0\uc5d0 \uad00\ud55c \uc120\ud0dd\uc73c\ub85c \uc774\uc5b4\uc84c\uae30 \ub54c\ubb38\uc774\ub2e4. \uc26c\ub098\ub4dc\ub294 \ucc98\uc74c\ubd80\ud130 \ud328\uc158 \uae30\uc5c5\uc744 \uc138\uc6b0\uaca0\ub2e4\ub294 \uacc4\ud68d\ub9cc\uc73c\ub85c \uc6c0\uc9c1\uc778 \uc0ac\ub78c\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ub4f1\ubc18\uc744 \uc88b\uc544\ud588\uace0 \uadf8 \uc0dd\ud65c\uc744 \uc774\uc5b4 \uac00\ub294 \uacfc\uc815\uc5d0\uc11c \uac15\ucca0 \ud53c\ud1a4\uc744 \ub9cc\ub4e4\uc5b4 \ud314\uc558\ub2e4. \ud53c\ud1a4\uc740 \ubc14\uc704 \ud2c8\uc5d0 \ubc15\uc544 \uc4f0\ub294 \uae08\uc18d \uc7a5\ube44\ub2e4. \uae30\ub2a5\uc744 \uc774\ud574\ud558\ub294 \ub370\ub294 \uc774 \uc815\ub3c4 \uc124\uba85\uc774\uba74 \ucda9\ubd84\ud558\ub2e4. \uadf8 \uc0ac\uc5c5\uc740 \uc131\uc7a5\ud574 \uc26c\ub098\ub4dc \uc774\ud045\uba3c\ud2b8\uac00 \ub418\uc5c8\ub2e4. \uad50\uc7ac\ub294 \ubbf8\uad6d\uc758 \uc911\uc694\ud55c \ub4f1\ubc18 \uc7a5\ube44 \uacf5\uae09\uc5c5\uccb4\ub85c \ubc1c\uc804\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc790\uc2e0\uc774 \uc9c1\uc811 \uc0ac\uc6a9\ud558\ub294 \ub3c4\uad6c\ub97c \uc798 \ub9cc\ub4e4 \uc218 \uc788\ub2e4\ub294 \ub2a5\ub825\uc774 \uc0ac\uc5c5\uc73c\ub85c \uc774\uc5b4\uc9c4 \uac83\uc774\ub2e4. \uace0\uac1d\uc774 \uc6d0\ud558\ub294 \uac83\uc744 \uc774\ud574\ud558\ub294 \uacbd\ud5d8\uacfc \uc81c\uc791 \uae30\uc220\uc774 \uac00\uae4c\uc774 \uc788\uc5c8\ub2e4. \ub4f1\ubc18\ud558\ub294 \uc0ac\ub78c\uc774 \ub298\uace0 \ud53c\ud1a4 \uc0ac\uc6a9\ub3c4 \ub9ce\uc544\uc9c0\uba74\uc11c \ubc14\uc704\uc5d0 \uc190\uc0c1\uc774 \uc0dd\uacbc\ub2e4. \ubc18\ubcf5\ud574\uc11c \uc7a5\ube44\ub97c \ubc15\uc544 \ub123\ub294 \ud589\ub3d9\uc774 \uc790\uc5f0\ud658\uacbd\uc5d0 \ud754\uc801\uc744 \ub0a8\uacbc\uae30 \ub54c\ubb38\uc774\ub2e4. \uc0b0\uacfc \ubc14\uc704\ub97c \uc88b\uc544\ud574 \uc2dc\uc791\ud55c \uc77c\uc774 \uadf8 \ub300\uc0c1\uc744 \ud574\uce60 \uc218 \uc788\ub2e4\ub294 \ubaa8\uc21c\uc774 \ub4dc\ub7ec\ub0ac\ub2e4. \uc81c\ud488\uc744 \ud314\uc558\ub2e4\ub294 \ub2e8\uacc4\uc5d0\uc11c\ub9cc \uacc4\uc0b0\ud558\uba74 \uc774 \uacb0\uacfc\uac00 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uadf8\ub7ec\ub098 \ubb3c\uac74\uc740 \ub9e4\uc7a5\uc744 \ub5a0\ub09c \ub4a4\uc5d0\ub3c4 \uc0ac\uc6a9\ub41c\ub2e4. \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \uc4f0\uc774\uace0 \ubb34\uc5c7\uc744 \ubc14\uafb8\ub294\uc9c0\uae4c\uc9c0 \uc0b4\ud53c\uba74 \uae30\uc5c5\uc758 \ucc45\uc784 \ubc94\uc704\uac00 \ub113\uc5b4\uc9c4\ub2e4. \uc26c\ub098\ub4dc\uac00 \ub9c8\uc8fc\ud55c \uc9c8\ubb38\ub3c4 \uc0dd\uc0b0\ud55c \uc218\ub7c9 \ubc14\uae65\uc5d0 \uc788\uc5c8\ub2e4. \uadf8\ub294 \ud53c\ud1a4\uc5d0 \ub300\ud55c \uc758\uc874\uc744 \uc904\uc774\uace0 \ubc14\uc704\uc5d0 \ubbf8\uce58\ub294 \ubd80\ub2f4\uc774 \ub354 \uc801\uc740 \uc54c\ub8e8\ubbf8\ub284 \ucd08\ud06c\ub97c \ud310\ub9e4\ud558\ub294 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc600\ub2e4. \uc5ec\uae30\uc11c \ucd08\ud06c\ub294 \uc190\uc5d0 \ubc14\ub974\ub294 \uac00\ub8e8\ub97c \ub73b\ud558\uc9c0 \uc54a\uace0 \ub4f1\ubc18\uc6a9 \uae08\uc18d \uc7a5\ube44\ub97c \uac00\ub9ac\ud0a8\ub2e4. \uc791\uc740 \uc774\ub984 \ucc28\uc774\uac00 \uc804\ud600 \ub2e4\ub978 \ubb3c\uac74\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud560 \uc218 \uc788\ub2e4. \uc774 \uae00\uc740 \uc7a5\ube44 \uc124\uce58\ubc95\uc774\ub098 \uc548\uc804 \uc131\ub2a5\uc744 \ube44\uad50\ud558\ub294 \uc548\ub0b4\uac00 \uc544\ub2c8\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uc774\ubbf8 \ud314\ub9ac\ub294 \uc81c\ud488\uc774 \uc788\uc5b4\ub3c4 \ub2e4\ub978 \ubc29\uc2dd\uc744 \ucc3e\uc558\ub2e4\ub294 \uc810\uc774\ub2e4. \uc774\uc775\uc774 \uc0dd\uae30\ub294 \uae30\uc874 \ud65c\ub3d9\uc758 \uc77c\ubd80\ub97c \uc2a4\uc2a4\ub85c \ubc14\uafb8\ub824\ub294 \uc120\ud0dd\uc740 \ud658\uacbd\uc744 \uac71\uc815\ud55c\ub2e4\ub294 \uc120\uc5b8\ubcf4\ub2e4 \ud6e8\uc52c \uad6c\uccb4\uc801\uc778 \uacbd\uc601\uc758 \ubb38\uc81c\uac00 \ub41c\ub2e4. \uc26c\ub098\ub4dc\ub294 \uc57c\uc678 \ud65c\ub3d9\uc5d0 \uc4f0\ub294 \uc758\ub958\ub3c4 \uc2e4\ud5d8\ud588\ub2e4. \uad50\uc7ac\ub294 \uc758\ub958 \ubd80\ubb38\uc774 \uc7a5\ube44 \ubd80\ubb38\ubcf4\ub2e4 \ucee4\uc9c0\uba74\uc11c \ud30c\ud0c0\uace0\ub2c8\uc544 \uc758\ub958 \ube0c\ub79c\ub4dc\ub85c \uc774\uc5b4\uc84c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc624\ub298\uc758 \uc720\uba85\ud55c \ubaa8\uc2b5\uc774 \ucc98\uc74c \uc0ac\uc5c5\uc758 \uc804\ubd80\ub294 \uc544\ub2c8\uc5c8\ub358 \uc148\uc774\ub2e4. \uc637\uc740 \ub4f1\ubc18 \uc7a5\ube44\uc640 \ub2e4\ub978 \uc81c\ud488\uc774\uc9c0\ub9cc \uc57c\uc678\uc5d0\uc11c \ubb34\uc5c7\uc774 \ud544\uc694\ud55c\uc9c0 \uacbd\ud5d8\ud55c \uc0ac\ub78c\uc774\ub77c\ub294 \ubc30\uacbd\uc740 \uc774\uc5b4\uc9c4\ub2e4. \ub3d9\uc2dc\uc5d0 \uc758\ub958\uc5d0\ub294 \uc6d0\uc7ac\ub8cc\uc640 \uc5fc\uc0c9, \uc0dd\uc0b0\uacfc \uc720\ud1b5\uc774\ub77c\ub294 \uc0c8\ub85c\uc6b4 \uc9c8\ubb38\uc774 \uc0dd\uae34\ub2e4. \uc790\uc5f0\uc744 \uc88b\uc544\ud558\ub294 \ucc3d\ub9bd\uc790\uc758 \ub9c8\uc74c\ub9cc\uc73c\ub85c \uc637 \ud55c \ubc8c\uc758 \ud658\uacbd \ubd80\ub2f4\uae4c\uc9c0 \uc790\ub3d9\uc73c\ub85c \ud574\uacb0\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uad50\uc7ac\ub294 \ud30c\ud0c0\uace0\ub2c8\uc544\uac00 \uc7ac\ud65c\uc6a9 \uc6d0\ub8cc\uc640 \uc5fc\ub8cc, \uc5d0\ub108\uc9c0 \uc0ac\uc6a9\uc5d0 \uad00\uc2ec\uc744 \ub450\uc5c8\uace0 \uba74 \uc81c\ud488\uc758 \uc6d0\ub8cc\ub97c \uc720\uae30\ub18d \uba74\uc73c\ub85c \ubc14\uafb8\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc774\ub294 \ubaa8\ub4e0 \uc637\uc758 \ubaa8\ub4e0 \uc18c\uc7ac\uac00 \uc720\uae30\ub18d\uc774\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc5d0 \uc801\uc6a9\ub41c \uc120\ud0dd\uc778\uc9c0 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ud55c \ubc8c\uc758 \uc637\uc5d0\ub294 \uc5ec\ub7ec \ub2e8\uacc4\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \uc18c\uc7ac\uac00 \ub2ec\ub77c\uc84c\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc804\uccb4 \uc0dd\uc0b0\uc774 \uc5b4\ub290 \uc815\ub3c4 \uc601\ud5a5\uc744 \uc904\uc600\ub294\uc9c0\ub294 \ubcc4\ub3c4\uc758 \uc9c8\ubb38\uc774\ub2e4. \uad6c\uccb4\uc801\uc778 \uc120\ud0dd\uc744 \uc0b4\ud53c\uba74\uc11c\ub3c4 \uc644\uc804\ud788 \ubb34\ud574\ud55c \uc81c\ud488\uc774\ub77c\ub294 \uc774\ubbf8\uc9c0\ub85c \ub113\ud788\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uae30\uc5c5\uc758 \ub178\ub825\uc744 \ud3c9\uac00\ud558\ub294 \ub370\ub3c4 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ube44\uc988\ub2c8\uc2a4 \uc724\ub9ac\uc5d0\uc11c \uc774\ud574\uad00\uacc4\uc790\ub294 \uc8fc\uc8fc\ub098 \uace0\uac1d\ub9cc\uc744 \ub73b\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc9c1\uc6d0\uacfc \uacf5\uae09\uc790, \uc9c0\uc5ed\uc0ac\ud68c, \ud658\uacbd\ucc98\ub7fc \uae30\uc5c5\uc758 \uacb0\uc815\uc73c\ub85c \uc601\ud5a5\uc744 \ubc1b\ub294 \ub300\uc0c1\uae4c\uc9c0 \uc0dd\uac01\ud55c\ub2e4. \ud53c\ud1a4\uc758 \uc0ac\ub840\uc5d0\uc11c\ub294 \ub9e4\ucd9c\uc744 \ub9cc\ub4dc\ub294 \uace0\uac1d\uacfc \ubc14\uc704\uac00 \uc11c\ub85c \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uc81c\ud488\uc758 \uacb0\uacfc\ub97c \uacbd\ud5d8\ud588\ub2e4. \uc774 \uad00\uc810\uc740 \uae30\uc5c5\uc744 \ub098\uc058\uac70\ub098 \ucc29\ud558\ub2e4\ub294 \ub450 \uce78\uc73c\ub85c \ub098\ub204\uae30 \uc704\ud55c \uc7a5\uce58\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uc120\ud0dd\uc5d0\uc11c \ub204\uac00 \uc774\uc775\uc744 \uc5bb\uace0 \ub204\uac00 \ubd80\ub2f4\uc744 \uc9c0\ub294\uc9c0 \uad6c\uccb4\uc801\uc73c\ub85c \uc9c8\ubb38\ud558\uac8c \ud55c\ub2e4. \ud658\uacbd \ud65c\ub3d9\uc744 \ud558\ub294 \ud68c\uc0ac\ub3c4 \uc81c\ud488\uc744 \ub9cc\ub4e4\uace0 \ud310\ub9e4\ud558\uba70 \uc790\uc6d0\uc744 \uc0ac\uc6a9\ud55c\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ud568\uaed8 \uc77d\uc744 \uc218 \uc788\ub2e4. \ud68c\uc0ac\uc758 \ucc3d\uc5c5 \uc774\uc57c\uae30\ub294 \uac00\uce58\uad00\uc744 \uc774\ud574\ud558\ub294 \ub370 \uc720\uc6a9\ud558\ub2e4. \uadf8\ub807\ub2e4\uace0 \uadf8 \uc77c\ud654 \ud558\ub098\ub85c \ud604\uc7ac\uc758 \ubaa8\ub4e0 \uc0c1\ud488\uacfc \uacf5\uae09\ub9dd\uc744 \ud3c9\uac00\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc774\ubc88 \uc6d0\uace0\ub294 \uad50\uc7ac\uac00 \uc18c\uac1c\ud55c \uc7a5\ube44 \uc804\ud658\uacfc \ud658\uacbd\uc801 \uc120\ud0dd\uc758 \uc0ac\ub840\uc5d0 \ucd08\uc810\uc744 \ub9de\ucdc4\ub2e4. \ud604\uc7ac \uacbd\uc601\uc9c4\uc774\ub098 \uac1c\ubcc4 \uc81c\ud488\uc758 \uc778\uc99d\uc744 \uc548\ub0b4\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc624\ud788\ub824 \uc88b\uc740 \ucd9c\ubc1c \uc774\uc57c\uae30\ub97c \uc54c\uc218\ub85d \uc774\ud6c4\uc5d0\ub3c4 \uac19\uc740 \uc9c8\ubb38\uc744 \uacc4\uc18d\ud560 \uc218 \uc788\ub2e4. \ubb34\uc5c7\uc744 \ub9cc\ub4e4\uace0 \uc5b4\ub5a4 \uc790\uc6d0\uc744 \uc4f0\ub294\uc9c0, \uc904\uc774\uaca0\ub2e4\uace0 \ud55c \ubd80\ub2f4\uc740 \uc2e4\uc81c\ub85c \uc5b4\ub5bb\uac8c \ub2ec\ub77c\uc84c\ub294\uc9c0 \ud655\uc778\ud558\ub294 \uac83\uc774\ub2e4. \ucc3d\ub9bd\uc790\uc758 \uacb0\ub2e8\uc740 \ub2f5\ubcc0\uc758 \ub05d\ubcf4\ub2e4 \uae30\uc5c5\uc744 \uc77d\ub294 \uc9c8\ubb38\uc758 \ucd9c\ubc1c\uc810\uc774 \ub420 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\uc5d0\ub294 \ud53c\ud1a4\uacfc \ub2e4\ub978 \uae08\uc18d \uc7a5\ube44, \ubc27\uc904\uacfc \uc57c\uc678 \uc758\ub958\uac00 \ub193\uc5ec \uc788\ub2e4. \uc2e4\uc81c \uc5ed\uc0ac\uc801 \uc81c\ud488\uc744 \uc815\ubc00\ud558\uac8c \ubcf5\uc6d0\ud588\uac70\ub098 \uc7a5\ube44 \uc0ac\uc6a9\uc744 \uac00\ub974\uce58\ub294 \uadf8\ub9bc\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \ubb3c\uac74\uc744 \uacc4\uc18d \ub9cc\ub4e4 \uac83\uc778\uc9c0 \ub2e4\uc2dc \uc0dd\uac01\ud558\ub294 \uc791\uc5c5\ub300\uc758 \ubd84\uc704\uae30\ub97c \ud45c\ud604\ud588\ub2e4. \ud30c\ud0c0\uace0\ub2c8\uc544\uc758 \ucd9c\ubc1c\uc740 \uc790\uc5f0\uc744 \uc88b\uc544\ud558\uba74 \uc0ac\uc5c5\ub3c4 \uc800\uc808\ub85c \uce5c\ud658\uacbd\uc801\uc774 \ub41c\ub2e4\ub294 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \uc88b\uc544\ud558\ub294 \uc7a5\uc18c\uc5d0 \uc790\uae30 \uc81c\ud488\uc774 \ub0a8\uae30\ub294 \uacb0\uacfc\ub97c \ubcf4\uc558\uace0, \uadf8 \ub54c\ubb38\uc5d0 \uc0ac\uc5c5\uc758 \uc77c\ubd80\ub97c \ubc14\uafb8\ub824 \ud588\ub2e4\ub294 \uc774\uc57c\uae30\ub2e4. \uc798 \ud314\ub9ac\ub294 \ub3c4\uad6c\ub97c \ubc14\ub77c\ubcf4\ub2e4\uac00 \uadf8 \ub3c4\uad6c\uac00 \ub2ff\ub294 \ubc14\uc704\ub97c \ubcf4\uac8c \ub41c \uc21c\uac04\uc774 \uc624\ub798 \ub0a8\ub294\ub2e4."}, {"id": "pixar-openusd-many-artists", "title": "\ud53d\uc0ac \u2014 \ud55c \uc7a5\uba74\uc744 \uc5ec\ub7ec \uc0ac\ub78c\uc774 \ud568\uaed8 \ub9cc\ub4e4\ub824\uba74", "summary": "\ud53d\uc0ac\uc758 OpenUSD \uacf5\uc2dd \uc124\uba85\uc744 \ud1b5\ud574 \uc560\ub2c8\uba54\uc774\uc158 \uc7a5\uba74\uc744 \ud568\uaed8 \ub9cc\ub4dc\ub294 \ud611\uc5c5\uc758 \ubb38\uc81c\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\uacbd\uc601\uacfc \uc870\uc9c1", "categories": ["industry"], "url": "stories/pixar-openusd-many-artists/index.html", "image": "../media/pixar-openusd-many-artists.png", "alt": "\uadf8\ub9bc\uacfc \uc791\uc740 \ub098\ubb34 \ubaa8\ud615, \ud654\uba74\uc744 \ub193\uace0 \ud568\uaed8 \uc791\uc5c5\ud558\ub294 \ucc3d\uc791\uc790\ub4e4\uc758 AI \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ud53d\uc0ac \u2014 \ud55c \uc7a5\uba74\uc744 \uc5ec\ub7ec \uc0ac\ub78c\uc774 \ud568\uaed8 \ub9cc\ub4e4\ub824\uba74 \ub098\ubb34\ub97c \ub9cc\ub4e0 \uc0ac\ub78c\uacfc \ube5b\uc744 \ube44\ucd98 \uc0ac\ub78c\uc774 \ub9cc\ub098\ub294 \uacf5\ud1b5 \uc5b8\uc5b4 \ud53d\uc0ac\uc758 OpenUSD \uacf5\uc2dd \uc124\uba85\uc744 \ud1b5\ud574 \uc560\ub2c8\uba54\uc774\uc158 \uc7a5\uba74\uc744 \ud568\uaed8 \ub9cc\ub4dc\ub294 \ud611\uc5c5\uc758 \ubb38\uc81c\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uacbd\uc601\uacfc \uc870\uc9c1 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \uc560\ub2c8\uba54\uc774\uc158 \uc601\ud654\uc5d0\uc11c \ub098\ubb34 \ud55c \uadf8\ub8e8\uac00 \ubc14\ub78c\uc5d0 \ud754\ub4e4\ub9b0\ub2e4. \uad00\uac1d\uc740 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ud55c \uc7a5\uba74\uc73c\ub85c \ubcf4\uc9c0\ub9cc, \uadf8 \ub098\ubb34\uc758 \ubaa8\uc591\uacfc \ud45c\uba74\uc758 \ub290\ub08c, \uc6c0\uc9c1\uc784\uacfc \ube5b\uc740 \uc11c\ub85c \ub2e4\ub978 \uc791\uc5c5\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc9c8 \uc218 \uc788\ub2e4. \uc774 \ubaa8\ub4e0 \uac83\uc744 \ub9c8\uc9c0\ub9c9\uc5d0 \uc5b4\ub5bb\uac8c \uac19\uc740 \uc138\uacc4 \uc548\uc5d0 \ub193\uc744\uae4c. \ud53d\uc0ac\uc758 \uacf5\uac1c \ud504\ub85c\uc81d\ud2b8 OpenUSD\ub294 \uc774\ub7f0 \uc9c8\ubb38\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc774\ub984\uc744 \uc678\uc6b0\uac70\ub098 \ud504\ub85c\uadf8\ub7a8\uc744 \ubc30\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5ec\ub7ec \uc0ac\ub78c\uc774 \ub2e4\ub978 \ub3c4\uad6c\ub85c \ub9cc\ub4e0 \uc791\uc5c5\uc744 \ud55c \uc7a5\uba74\uc73c\ub85c \ubaa8\uc73c\ub824\uba74 \uacf5\ud1b5\uc758 \uc57d\uc18d\uc774 \ud544\uc694\ud558\ub2e4\ub294 \uc810\uc5d0\uc11c, \uc601\ud654 \uc81c\uc791\uc758 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc7ac\ubbf8\ub97c \ubc1c\uacac\ud560 \uc218 \uc788\ub2e4. \ud53d\uc0ac\uc758 \uacf5\uc2dd \ubb38\uc11c\ub294 \ubaa8\ub378\ub9c1\uacfc \uc7ac\uc9c8 \ud45c\ud604, \uc560\ub2c8\uba54\uc774\uc158\uacfc \uc870\uba85 \ub4f1 \ub2e4\uc591\ud55c \uc791\uc5c5\uc744 \uc18c\uac1c\ud55c\ub2e4. \ubaa8\uc591\uc744 \ub9cc\ub4dc\ub294 \ub3c4\uad6c\uc640 \uc6c0\uc9c1\uc784\uc744 \ub9cc\ub4dc\ub294 \ub3c4\uad6c\uac00 \uaf2d \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc815\ubcf4\ub97c \uc800\uc7a5\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac01 \ub3c4\uad6c\ub294 \uc790\uc2e0\uc774 \uc798\ud558\ub294 \uc77c\uc5d0 \ub9de\ub294 \ud45c\ud604\uc744 \uac16\ub294\ub2e4. \uadf8\ub7f0\ub370 \ub2e4\uc74c \uc0ac\ub78c\uc774 \uadf8 \uc815\ubcf4\ub97c \uc81c\ub300\ub85c \uc77d\uc9c0 \ubabb\ud558\uba74 \uc791\uc5c5\uc744 \uc774\uc5b4 \uac00\uae30 \uc5b4\ub835\ub2e4. \uba4b\uc9c4 \ub098\ubb34\ub97c \ub9cc\ub4e4\uc5c8\uc5b4\ub3c4 \ub2e4\ub978 \ub3c4\uad6c\uc5d0\uc11c \uc704\uce58\ub098 \uc7ac\uc9c8\uc774 \uae30\ub300\uc640 \ub2e4\ub974\uac8c \ub098\ud0c0\ub098\uba74 \ubb38\uc81c\uac00 \ub41c\ub2e4. \uc791\ud488\uc744 \uc798 \ub9cc\ub4dc\ub294 \ub2a5\ub825\uacfc \uc791\uc5c5\uc744 \uc798 \uc804\ub2ec\ud558\ub294 \ub2a5\ub825\uc774 \ud568\uaed8 \ud544\uc694\ud588\ub358 \uac83\uc774\ub2e4. USD\ub294 Universal Scene Description\uc758 \uc57d\uc790\ub2e4. \uc7a5\uba74\uc744 \uad6c\uc131\ud558\ub294 \uc815\ubcf4\ub97c \uacf5\ud1b5\uc758 \ubc29\uc2dd\uc73c\ub85c \uc124\uba85\ud558\uace0 \uc870\ud569\ud558\ub294 \uae30\uc220\ub85c \uc774\ud574\ud558\uba74 \ub41c\ub2e4. \ub098\ubb34\uc758 \ubaa8\uc591\uacfc \uc704\uce58, \uc7ac\uc9c8\uacfc \ube5b\ucc98\ub7fc \uc7a5\uba74\uc744 \ub9cc\ub4dc\ub294 \uc694\uc18c\ub4e4\uc744 \ud568\uaed8 \ub2e4\ub8e8\uae30 \uc704\ud55c \uae30\ubc18\uc774\ub2e4. \uc774\ub294 \uc601\ud654\uc758 \uc904\uac70\ub9ac\ub97c \ubb38\uc7a5\uc73c\ub85c \uc694\uc57d\ud558\ub294 \ud504\ub85c\uadf8\ub7a8\uc774 \uc544\ub2c8\ub2e4. \ucef4\ud4e8\ud130\uac00 \ub2e4\ub8f0 \uc218 \uc788\ub294 3\ucc28\uc6d0 \uc7a5\uba74\uc758 \uc815\ubcf4\ub97c \uc870\uc9c1\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4. \uac89\uc73c\ub85c \ubcf4\uc774\ub294 \uc644\uc131 \uc601\uc0c1\ubcf4\ub2e4 \uadf8 \uc601\uc0c1\uc774 \ub9cc\ub4e4\uc5b4\uc9c0\uae30 \uc804 \uc5ec\ub7ec \uc791\uc5c5\uc744 \uc5f0\uacb0\ud558\ub294 \ucabd\uc5d0 \uad00\uc2ec\uc744 \ub454\ub2e4. \uacf5\uc2dd \ubb38\uc11c\ub294 \uc5ec\ub7ec \uc791\uc5c5\uc790\uac00 \uac01\uc790\uc758 \ud30c\uc77c\uc5d0\uc11c \uc791\uc5c5\ud558\uace0 \uadf8 \uacb0\uacfc\ub97c \ud569\uce58\ub294 \ubc29\uc2dd\uc744 \uc124\uba85\ud55c\ub2e4. \ud30c\uc77c\uc758 \ub2e8\uc704\ub97c \ub808\uc774\uc5b4\ub77c\uace0 \ubd80\ub978\ub2e4. \uac19\uc740 \uc7a5\uba74\uc744 \ub2e4\ub8e8\uba74\uc11c\ub3c4 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc791\uc5c5\uc744 \ubc14\ub85c \uc9c0\uc6b0\uac70\ub098 \uace0\uce58\uc9c0 \uc54a\uace0 \uc790\uc2e0\uc758 \ubcc0\uacbd\uc744 \ub354\ud560 \uc218 \uc788\ub2e4. \ud3b8\uc9d1\uc790\uac00 \uc6d0\ubb38 \uc704\uc5d0 \uc218\uc815 \uc758\uacac\uc744 \ubcc4\ub3c4\ub85c \uc801\ub294 \ubaa8\uc2b5\uc744 \ub5a0\uc62c\ub9ac\uba74 \uccab \uc774\ud574\uc5d0 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ubb3c\ub860 \uc2e4\uc81c \uc7a5\uba74 \ud569\uc131\uc740 \uba54\ubaa8\ub97c \ubd99\uc774\ub294 \uc77c\ubcf4\ub2e4 \ubcf5\uc7a1\ud558\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ud611\uc5c5\uc744 \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \ud558\ub098\uc758 \ud30c\uc77c\uc744 \ubc88\uac08\uc544 \uc218\uc815\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c\ub9cc \uc0dd\uac01\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc774\ub2e4. \uac19\uc740 \uc704\uce58\ub098 \uc18d\uc131\uc5d0 \uc11c\ub85c \ub2e4\ub978 \uac12\uc774 \ub4e4\uc5b4\uc624\uba74 \uc5b4\ub290 \ucabd\uc744 \uc801\uc6a9\ud560\uc9c0 \uc815\ud574\uc838 \uc788\uc5b4\uc57c \ud55c\ub2e4. USD\ub294 \uc774\ub7f0 \uc870\ud569\uc758 \uc21c\uc11c\ub97c \uba85\uc2dc\ud558\ub294 \uad6c\uc870\ub97c \uc81c\uacf5\ud55c\ub2e4. \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc791\uc5c5\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc77c\uad00\ub41c \uacb0\uacfc\uac00 \uc800\uc808\ub85c \ub9cc\ub4e4\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uae30 \ub54c\ubb38\uc774\ub2e4. \uc774\uac83\uc740 \uac00\uc7a5 \ub192\uc740 \uc9c1\uae09\uc758 \uc0ac\ub78c\uc774 \uc5b8\uc81c\ub098 \uc774\uae34\ub2e4\ub294 \uc870\uc9c1 \uaddc\uce59\uacfc\ub294 \ub2e4\ub974\ub2e4. \ud30c\uc77c\uacfc \uc7a5\uba74 \uc815\ubcf4\ub97c \uc5b4\ub5a4 \uc6b0\uc120\uc21c\uc704\ub85c \uc77d\uc744\uc9c0\uc5d0 \uad00\ud55c \uae30\uc220\uc801 \uc57d\uc18d\uc774\ub2e4. \uc0ac\ub78c\uc774 \ubbf8\ub9ac \uc815\ud55c \uc791\uc5c5 \uad00\uacc4\uac00 \uae30\uacc4\uac00 \uc77d\uc744 \uc218 \uc788\ub294 \uad6c\uc870 \uc548\uc5d0\ub3c4 \ud45c\ud604\ub418\ub294 \uc148\uc774\ub2e4. \uacf5\uc2dd \ubb38\uc11c\ub294 \uc774\ub7f0 \ud611\uc5c5\uc774 \ubaa8\ub4e0 \ubb38\uc81c\ub97c \uc790\ub3d9\uc73c\ub85c \ud574\uacb0\ud558\ub294 \ub9cc\ub2a5 \uc7a5\uce58\ub294 \uc544\ub2c8\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \ubaa8\uc591\uc744 \ub9cc\ub4dc\ub294 \uc791\uc5c5\uc790\uac00 \ub098\ubb34 \uad6c\uc870\ub97c \ubc14\uafb8\uba74, \uc55e\uc11c \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc124\uc815\ud55c \ud45c\uba74 \ud45c\ud604\uacfc \ub9de\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \ud30c\uc77c\uc744 \ud569\uce60 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc218\uc815 \ub4a4\uc5d0\ub3c4 \ubaa8\ub4e0 \uc608\uc220\uc801 \uc120\ud0dd\uc774 \uc801\uc808\ud558\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub974\ub2e4. \uc774\ub54c\ub294 \ubb34\uc5c7\uc774 \ubc14\ub00c\uc5c8\ub294\uc9c0 \ucd94\uc801\ud558\uace0 \uad00\uacc4\ub41c \uc791\uc5c5\uc744 \ub2e4\uc2dc \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uacf5\ud1b5 \uc5b8\uc5b4\ub294 \ub300\ud654\ub97c \uc5c6\uc560\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc11c\ub85c\uc758 \ubcc0\uacbd\uc744 \uc774\ud574\ud558\ub294 \uae30\ubc18\uc744 \ub9cc\ub4e0\ub2e4. \uae30\uc220\uc774 \uc88b\uc544\uc838\ub3c4 \ud568\uaed8 \ud310\ub2e8\ud574\uc57c \ud558\ub294 \uc790\ub9ac\ub294 \ub0a8\ub294\ub2e4. \ud53d\uc0ac\ub294 \uc218\uc815\ud55c \uacb0\uacfc\ub97c \ube60\ub974\uac8c \ud655\uc778\ud558\uace0 \ubc18\ubcf5\ud558\ub294 \ub2a5\ub825\uc744 \uc911\uc694\ud558\uac8c \uc124\uba85\ud55c\ub2e4. \ud55c \ubc88\uc5d0 \uc644\ubcbd\ud55c \ub2f5\uc744 \uc5bb\uae30\ubcf4\ub2e4 \uc5ec\ub7ec \ubc88 \ubcf4\uace0 \uace0\uce58\uba70 \uc7a5\uba74\uc744 \ub2e4\ub4ec\ub294 \uac83\uc774\ub2e4. \ubc14\uafbc \uacb0\uacfc\ub97c \ud655\uc778\ud558\ub294 \ub370 \uc624\ub798 \uac78\ub9ac\uba74 \uc2dc\ub3c4\ud560 \uc218 \uc788\ub294 \ud69f\uc218\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc900\ub2e4. \uc774\ub7f0 \uad00\uc810\uc5d0\uc11c \uc791\uc5c5 \uc18d\ub3c4\ub294 \uc0ac\ub78c\uc744 \ub354 \uc7ac\ucd09\ud558\ub294 \ubb38\uc81c\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uacb0\uacfc\ub97c \uae30\ub2e4\ub9ac\ub294 \uc2dc\uac04\uc744 \uc904\uc5ec \ub2e4\ub978 \uc120\ud0dd\uc744 \uc2dc\ud5d8\ud560 \uc5ec\uc720\ub97c \uc8fc\ub294 \ubb38\uc81c\uac00 \ub420 \uc218 \uc788\ub2e4. \uad00\uac1d\uc5d0\uac8c\ub294 \uc9e7\uac8c \uc9c0\ub098\uac00\ub294 \uc7a5\uba74\uc5d0\ub3c4 \uc5ec\ub7ec \ubc88\uc758 \uad00\ucc30\uacfc \uc218\uc815\uc774 \ub4e4\uc5b4\uac08 \uc218 \uc788\ub2e4. USD\ub294 \ud53d\uc0ac\uc758 \uc81c\uc791 \ud658\uacbd\uc5d0\uc11c \uc911\uc694\ud55c \uae30\ubc18\uc73c\ub85c \uc4f0\uc774\uba70 \uacf5\uac1c \ud504\ub85c\uc81d\ud2b8\ub85c\ub3c4 \uc81c\uacf5\ub41c\ub2e4. \ub2e4\ub978 \ub3c4\uad6c\uc640 \uc791\uc5c5\uc790\uac00 \ud568\uaed8 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \ubc29\uc2dd\uc774\ub77c\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uc18c\uc2a4\uac00 \uacf5\uac1c\ub418\uc5c8\ub2e4\uace0 \ud53d\uc0ac\uc758 \ubaa8\ub4e0 \uc791\ud488 \ud30c\uc77c\uacfc \uce90\ub9ad\ud130\uac00 \ud568\uaed8 \uc790\uc720\ub86d\uac8c \ud480\ub9ac\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub610 \uc774 \uae30\uc220 \ud558\ub098\uac00 \uc774\uc57c\uae30\ub97c \uc4f0\uace0 \uc5f0\uae30\ub97c \ub9cc\ub4e4\uba70 \uc644\uc131 \uc601\ud654\ub97c \ub300\uc2e0 \uc81c\uc791\ud558\uc9c0\ub3c4 \uc54a\ub294\ub2e4. \uc7a5\uba74\uc744 \uc5f0\uacb0\ud558\ub294 \uae30\ubc18\uacfc \uac1c\ubcc4 \uc791\ud488\uc758 \ucc3d\uc791\uc740 \uad6c\ubcc4\ub41c\ub2e4. \uacf5\uac1c \uae30\uc220\uc744 \uc774\ud574\ud558\ub294 \uc77c\uc740 \uc601\ud654\uc758 \ube44\ubc00\uc744 \ubaa8\ub450 \uc54c\uc544\ub0b4\ub294 \uc77c\ubcf4\ub2e4, \ud611\uc5c5\uc744 \uac00\ub2a5\ud558\uac8c \ud55c \uc57d\uc18d\uc744 \uc0b4\ud53c\ub294 \ub370 \uac00\uae5d\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uadf8\ub9bc\uacfc \uc791\uc740 \ubaa8\ud615\uc744 \ub193\uace0 \uc758\ub17c\ud558\ub294 \ucc3d\uc791\uc790\ub4e4\uc744 \ud45c\ud604\ud588\ub2e4. \uc2e4\uc81c \ud53d\uc0ac \uc9c1\uc6d0\uc774\ub098 \uc0ac\ubb34\uc2e4, \ud2b9\uc815 \uc601\ud654\uc758 \uc791\uc5c5 \uc7a5\uba74\uc774 \uc544\ub2c8\ub2e4. \uc798 \uc54c\ub824\uc9c4 \uce90\ub9ad\ud130 \ub300\uc2e0 \uc5ec\ub7ec \uc885\ub958\uc758 \ucc3d\uc791\uc774 \ub9cc\ub09c\ub2e4\ub294 \ubd84\uc704\uae30\ub97c \ub2f4\uc558\ub2e4. \ub2e4\uc74c\uc5d0 \uc560\ub2c8\uba54\uc774\uc158\uc758 \uc232\uc744 \ubcf4\uba74 \ub098\ubb34\uc758 \uc0dd\uae40\uc0c8\ubfd0 \uc544\ub2c8\ub77c \ube5b\uacfc \uc6c0\uc9c1\uc784\ub3c4 \ub530\ub85c \ub290\uaef4 \ubcf4\uc790. \uadf8\ub7f0 \ub4a4 \ub2e4\uc2dc \ud55c \uc7a5\uba74\uc73c\ub85c \ubc14\ub77c\ubcf4\uba74 \uc5ec\ub7ec \uc120\ud0dd\uc774 \uc5b4\ub5bb\uac8c \uc5b4\uc6b8\ub9ac\ub294\uc9c0 \ubcf4\uc778\ub2e4. \ud53d\uc0ac\uc758 \uacf5\uac1c \uae30\uc220 \uc774\uc57c\uae30\ub294 \uad00\uac1d\uc774 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ubcf4\ub294 \uc138\uacc4\ub97c \ub9cc\ub4e4\uae30 \uc704\ud574, \ubcf4\uc774\uc9c0 \uc54a\ub294 \uacf3\uc5d0\uc11c \uc5bc\ub9c8\ub098 \ub9ce\uc740 \uc57d\uc18d\uc774 \ud544\uc694\ud588\ub294\uc9c0 \uc54c\ub824 \uc900\ub2e4."}, {"id": "postit-weak-glue-new-use", "title": "3M \u2014 \uc798 \ubd99\uc9c0 \uc54a\ub294 \uc811\ucc29\uc81c\uc758 \uc4f8\ubaa8", "summary": "\ud3ec\uc2a4\ud2b8\uc787\uc758 \ud0c4\uc0dd \uc0ac\ub840\ub85c \uc18c\uc7ac\uc758 \uc131\ub2a5\uacfc \uc0c8\ub85c\uc6b4 \uc4f0\uc784, \uc0ac\ub78c \uc0ac\uc774\uc758 \uc9c0\uc2dd \uc5f0\uacb0\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\ucc3d\uc5c5\uacfc \uc131\uc7a5", "categories": ["industry"], "url": "stories/postit-weak-glue-new-use/index.html", "image": "../media/postit-weak-glue-new-use.png", "alt": "\ud3bc\uce5c \ucc2c\uc1a1\uac00 \ucc45\uc5d0 \uc791\uc740 \ub178\ub780 \uc885\uc774 \ud45c\uc2dc\ub97c \ubd99\uc774\ub294 \uc190\uc758 \uc0bd\ud654.", "text": "3M \u2014 \uc798 \ubd99\uc9c0 \uc54a\ub294 \uc811\ucc29\uc81c\uc758 \uc4f8\ubaa8 \ub5a8\uc5b4\uc9c0\ub294 \ucc45\uac08\ud53c\uac00 \uc0c8\ub85c\uc6b4 \uc9c8\ubb38\uc744 \ub9cc\ub4e4\ub2e4 \ud3ec\uc2a4\ud2b8\uc787\uc758 \ud0c4\uc0dd \uc0ac\ub840\ub85c \uc18c\uc7ac\uc758 \uc131\ub2a5\uacfc \uc0c8\ub85c\uc6b4 \uc4f0\uc784, \uc0ac\ub78c \uc0ac\uc774\uc758 \uc9c0\uc2dd \uc5f0\uacb0\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ucc3d\uc5c5\uacfc \uc131\uc7a5 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \uc811\ucc29\uc81c\ub77c\uba74 \ub2e8\ub2e8\ud788 \ubd99\uc5b4\uc57c \uc88b\ub2e4\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \uadf8\ub7f0\ub370 \ubd99\uc600\ub2e4\uac00 \ub5bc\uc5b4\ub3c4 \uc885\uc774\uac00 \ub9dd\uac00\uc9c0\uc9c0 \uc54a\ub294\ub2e4\uba74 \uc5b4\ub5a8\uae4c. \uc624\ub798 \uace0\uc815\ud558\ub294 \ub370\ub294 \uc544\uc26c\uc6b4 \uc131\uc9c8\uc774 \uc7a0\uae50 \ud45c\uc2dc\ud574 \ub450\ub294 \uc77c\uc5d0\ub294 \uc7a5\uc810\uc774 \ub420 \uc218 \uc788\ub2e4. \uc131\ub2a5\uc740 \ubb34\uc5c7\uc5d0 \uc4f0\ub294\uc9c0\uc5d0 \ub530\ub77c \ub2e4\ub978 \ub73b\uc774 \ub41c\ub2e4. 3M\uc758 \ud3ec\uc2a4\ud2b8\uc787 \uc774\uc57c\uae30\ub294 \uc774\ub7f0 \uc804\ud658\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc0ac\ub840\ub2e4. \ucc98\uc74c\ubd80\ud130 \uc644\uc131\ub41c \uba54\ubaa8\uc9c0\ub97c \ud55c \ubc88\uc5d0 \ubc1c\uba85\ud55c \uc7a5\uba74\uc774 \uc544\ub2c8\ub2e4. \uc0c8\ub85c\uc6b4 \uc18c\uc7ac\ub97c \ub2e4\ub8e8\ub358 \uc0ac\ub78c\uacfc \ucc45\uac08\ud53c\uc758 \ubd88\ud3b8\uc744 \uacaa\ub358 \uc0ac\ub78c\uc758 \uc0dd\uac01\uc774 \uc774\uc5b4\uc84c\ub2e4. \uc720\uba85\ud55c \ub178\ub780 \uba54\ubaa8\uc9c0\ub294 \uc11c\ub85c \ub2e4\ub978 \uc9c8\ubb38\uc774 \ub9cc\ub09c \uacb0\uacfc\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 3M \uc5f0\uad6c\uc2e4\uc5d0\uc11c \uc0c8\ub85c\uc6b4 \uc811\ucc29 \uc18c\uc7ac\ub97c \uc5f0\uad6c\ud558\ub358 \uc911 \uc2a4\ud39c\uc11c \uc2e4\ubc84\uac00 \uc57d\ud558\uac8c \ubd99\ub294 \uc131\uc9c8\uc758 \uc18c\uc7ac\ub97c \ub9cc\ub4e4\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub2f9\uc2dc\uc5d0\ub294 \ubd84\uba85\ud55c \uc4f0\uc784\uc744 \ucc3e\uc9c0 \ubabb\ud588\ub2e4. \uc0c8\ub85c\uc6b4 \ubb3c\uc9c8\uc774 \uc0dd\uacbc\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc0ac\ub78c\ub4e4\uc774 \uc0b4 \uc81c\ud488\uc774 \uc0dd\uacbc\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2ec\ub790\ub2e4. \uc774 \ub300\ubaa9\uc744 \uac15\ud55c \uc811\ucc29\uc81c \ub9cc\ub4e4\uae30\uc5d0 \uc2e4\ud328\ud588\uc73c\ub2c8 \ubb34\uc5c7\uc774\ub4e0 \uad1c\ucc2e\ub2e4\ub294 \uad50\ud6c8\uc73c\ub85c \ubc14\uafb8\uba74 \ub108\ubb34 \uac04\ub2e8\ud558\ub2e4. \uad6c\uccb4\uc801\uc73c\ub85c \uc5b4\ub5a4 \uc131\uc9c8\uc774 \uc788\uc5c8\uace0 \uadf8 \uc131\uc9c8\uc744 \uc5b4\ub5a4 \ud544\uc694\uc640 \uc5f0\uacb0\ud560 \uc218 \uc788\ub294\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \uacb0\uacfc\ub97c \ub2e4\uc2dc \ubc14\ub77c\ubcfc \uadfc\uac70\uac00 \uc788\uc5b4\uc57c \uc0c8\ub85c\uc6b4 \uc4f0\uc784\ub3c4 \ucc3e\uc744 \uc218 \uc788\ub2e4. \uc544\ud2b8 \ud504\ub77c\uc774\ub294 \uad50\ud68c \ucc2c\uc1a1\uac00 \ucc45\uc758 \ud45c\uc2dc\uac00 \uc790\uafb8 \ub5a8\uc5b4\uc9c0\ub294 \ubd88\ud3b8\uc744 \uacaa\uc5c8\ub2e4\uace0 \uad50\uc7ac\ub294 \uc18c\uac1c\ud55c\ub2e4. \ud3bc\uce60 \uc790\ub9ac\ub97c \uc54c\ub824 \uc8fc\uc5b4\uc57c \ud558\ub294\ub370 \uc885\uc774 \ud45c\uc2dc\uac00 \uadf8 \uc5ed\ud560\uc744 \uc81c\ub300\ub85c \ud558\uc9c0 \ubabb\ud588\ub358 \uac83\uc774\ub2e4. \ubb3c\uac74\uc740 \uc791\uc544\ub3c4 \ubc18\ubcf5\ub418\ub294 \ubd88\ud3b8\uc740 \ubd84\uba85\ud588\ub2e4. \uadf8\ub294 \uc2e4\ubc84\uc758 \uc18c\uc7ac\uac00 \uc885\uc774\uc5d0 \ubd99\uc5b4 \uc788\uc73c\uba74\uc11c \ud544\uc694\ud560 \ub54c \uc885\uc774\ub97c \uc190\uc0c1\uc2dc\ud0a4\uc9c0 \uc54a\uace0 \ub5a8\uc5b4\uc9c8 \uc218 \uc788\ub2e4\ub294 \uc810\uc5d0 \uc8fc\ubaa9\ud588\ub2e4. \uac19\uc740 \uc131\uc9c8\uc774 \uc5f0\uad6c\uc2e4\uc758 \uc6a9\ub3c4 \uc5c6\ub294 \uacb0\uacfc\uc5d0\uc11c \ucc45\uc744 \uc77d\ub294 \uc0ac\ub78c\uc758 \ud574\uacb0\ucc45\uc73c\ub85c \ubc14\ub00c\uc5c8\ub2e4. \uc18c\uc7ac\uc640 \ud544\uc694\uac00 \ub9cc\ub098\ub294 \uc21c\uac04\uc774\ub2e4. \ucc45\uac08\ud53c\uc5d0\ub294 \uc11c\ub85c \ub2e4\ub978 \uc694\uad6c\uac00 \ud568\uaed8 \uc788\ub2e4. \uc27d\uac8c \ub5a8\uc5b4\uc9c0\uc9c0 \uc54a\uc544\uc57c \ud558\uc9c0\ub9cc \ud544\uc694\ud55c \ub54c\uc5d0\ub294 \uc62e\uae38 \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uac15\ud558\uac8c \uace0\uc815\ud558\ub294 \ub2a5\ub825\ub9cc \ub192\uc774\uba74 \uc624\ud788\ub824 \ucc45\uc744 \uc190\uc0c1\uc2dc\ud0a4\uac70\ub098 \uc704\uce58\ub97c \ubc14\uafb8\uae30 \uc5b4\ub824\uc6cc\uc9c8 \uc218 \uc788\ub2e4. \uc81c\ud488\uc744 \uc0dd\uac01\ud560 \ub54c \ud55c \uac00\uc9c0 \uc131\ub2a5\uc744 \ucd5c\uace0\ub85c \ub9cc\ub4dc\ub294 \uac83\uacfc \uc804\uccb4 \uc6a9\ub3c4\uc5d0 \ub9de\ucd94\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uc774 \uacbd\uc6b0\uc5d0\ub294 \uc801\uc808\ud788 \ubd99\uace0 \uc798 \ub5a8\uc5b4\uc9c0\ub294 \uad00\uacc4\uac00 \uc911\uc694\ud588\ub2e4. \uc88b\uc9c0 \uc54a\uc740 \uc131\ub2a5\uc73c\ub85c \ubcf4\uc600\ub358 \ubd80\ubd84\uc774 \ub2e4\ub978 \uc0ac\uc6a9\uc5d0\uc11c\ub294 \ud544\uc694\ud55c \uade0\ud615\uc774 \ub420 \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \ud765\ubbf8\ub86d\ub2e4. \ud504\ub77c\uc774\ub294 \uadf8 \uc18c\uc7ac\ub97c \ud398\uc774\uc9c0 \ud45c\uc2dc\uc640 \uba54\ubaa8\uc9c0\uc5d0 \uc801\uc6a9\ud574 \ubcf4\uc558\ub2e4. \uad50\uc7ac\ub294 \uc774\ub7f0 \uc2e4\ud5d8\uc774 \ud3ec\uc2a4\ud2b8\uc787 \uc81c\ud488\uc73c\ub85c \uc774\uc5b4\uc84c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub5a0\uc624\ub978 \uc0dd\uac01\uc744 \ubc14\ub85c \uc644\uc131\ud488\uc774\ub77c\uace0 \ubd80\ub974\ub294 \ub300\uc2e0 \uc2e4\uc81c\ub85c \uc5b4\ub5bb\uac8c \uc4f8 \uc218 \uc788\ub294\uc9c0 \uc2dc\ud5d8\ud55c \uacfc\uc815\uc774 \uc788\uc5c8\ub2e4. \ucc45\uac08\ud53c\uc640 \uc9e7\uc740 \uba54\ubaa8\ub294 \ub2ee\uc558\uc9c0\ub9cc \uac19\uc740 \ubb3c\uac74\uc740 \uc544\ub2c8\ub2e4. \ud558\ub098\ub294 \uc704\uce58\ub97c \uc54c\ub824 \uc8fc\uace0 \ub2e4\ub978 \ud558\ub098\ub294 \ub0b4\uc6a9\uc744 \uc7a0\uc2dc \ub0a8\uae34\ub2e4. \ub5bc\uc5b4 \uc62e\uae38 \uc218 \uc788\ub2e4\ub294 \uc131\uc9c8\uc774 \ub450 \uc0ac\uc6a9\uc744 \uc5f0\uacb0\ud588\ub2e4. \uc0c8 \uc81c\ud488\uc740 \uc18c\uc7ac \ud558\ub098\ubfd0 \uc544\ub2c8\ub77c \ud06c\uae30\uc640 \uc4f0\ub294 \ubc29\uc2dd, \uc0ac\uc6a9\ud558\ub294 \uc0ac\ub78c\uc774 \uc774\ud574\ud558\ub294 \ubaa9\uc801\uae4c\uc9c0 \ud544\uc694\ub85c \ud55c\ub2e4. \uc774 \uc0ac\ub840\ub97c \ud55c \uba85\uc758 \ucc9c\uc7ac\uac00 \uc6b0\uc5f0\ud788 \uc138\uc0c1\uc744 \ubc14\uafbc \uc7a5\uba74\uc73c\ub85c\ub9cc \uc124\uba85\ud558\uba74 \uc911\uc694\ud55c \uad00\uacc4\uac00 \ube60\uc9c4\ub2e4. \uc18c\uc7ac\ub97c \ub9cc\ub4e0 \uc0ac\ub78c\uacfc \uadf8\uac83\uc758 \uc4f0\uc784\uc744 \ucc3e\uc740 \uc0ac\ub78c\uc774 \uc11c\ub85c \ub2e4\ub978 \ubb38\uc81c\ub97c \ubcf4\uace0 \uc788\uc5c8\ub2e4. \ud55c \uc0ac\ub78c\uc774 \uc54c\uace0 \uc788\ub358 \uac83\uc774 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc758\ubbf8\uac00 \ub418\uc5c8\ub2e4. \uadf8\ub798\uc11c \uae30\uc5c5\uc758 \ud601\uc2e0\uc744 \uc0dd\uac01\ud560 \ub54c \uc544\uc774\ub514\uc5b4\ub97c \ud63c\uc790 \uc798 \ub0b4\ub294 \ub2a5\ub825\ub9cc \ubcfc \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\uc774 \ud55c \uc77c\uc744 \uc54c\uc544\ubcf4\uace0 \ud544\uc694\ud55c \uacf3\uc5d0 \uc5f0\uacb0\ud558\ub294 \ud658\uacbd\ub3c4 \uc911\uc694\ud558\ub2e4. \uc0c8\ub85c\uc6b4 \ubc1c\uacac\uc774 \ubcf4\uad00\ub9cc \ub418\uace0 \ub204\uad6c\uc5d0\uac8c\ub3c4 \uc54c\ub824\uc9c0\uc9c0 \uc54a\uc558\ub2e4\uba74 \ub2e4\ub978 \uacb0\uacfc\uac00 \ub098\uc654\uc744 \uc218 \uc788\ub2e4\ub294 \uc9c8\ubb38\uc744 \ud574 \ubcfc \uc218 \uc788\ub2e4. \ub2e4\ub978 \uacbd\uc601\ud559 \uc124\uba85\uc5d0\uc11c \uad50\uc7ac\ub294 3M\uc758 \ud601\uc2e0 \ud65c\ub3d9\uc5d0 \uc9c1\uc6d0\uc774 \uc790\uae30 \uc544\uc774\ub514\uc5b4\ub97c \ud0d0\uc0c9\ud560 \uc5ec\uc720\uac00 \uc911\uc694\ud588\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ubc1c\uacac\uc744 \uc2e4\uc81c \uc81c\ud488\uc73c\ub85c \uc62e\uae30\ub824\uba74 \uc2e4\ud5d8\ud558\uace0 \ub2e4\uc2dc \ud655\uc778\ud558\ub294 \uc2dc\uac04\uc774 \ud544\uc694\ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \uc774\uac83\uc740 \ud604\uc7ac \ubaa8\ub4e0 \ubd80\uc11c\uc758 \uc815\ud655\ud55c \uadfc\ubb34 \uaddc\uce59\uc744 \uc548\ub0b4\ud558\ub294 \ub9d0\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \ub2f9\uc7a5 \uc815\ud574\uc9c4 \uc791\uc5c5\ub9cc\uc73c\ub85c \ud3c9\uac00\ud558\uba74 \uc544\uc9c1 \uc6a9\ub3c4\uac00 \ubd84\uba85\ud558\uc9c0 \uc54a\uc740 \uacb0\uacfc\ub97c \uc0b4\ud53c\uae30 \uc5b4\ub835\ub2e4\ub294 \uc810\uc740 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ubc18\ub300\ub85c \uc2dc\uac04\uc744 \uc8fc\uc5c8\ub2e4\uace0 \ubaa8\ub4e0 \uc2dc\ub3c4\uac00 \uc81c\ud488\uc774 \ub418\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \ud0d0\uc0c9\uc744 \ud5c8\uc6a9\ud558\ub294 \uac83\uacfc \uc5b4\ub5a4 \uc544\uc774\ub514\uc5b4\ub97c \uacc4\uc18d\ud560\uc9c0 \ud310\ub2e8\ud558\ub294 \uc77c\uc740 \ud568\uaed8 \ud544\uc694\ud558\ub2e4. \ud3ec\uc2a4\ud2b8\uc787\uc744 \uc6b0\uc5f0\uc758 \ubc1c\uba85\uc774\ub77c\uace0 \ubd80\ub974\ub294 \ub9d0\uc5d0\ub294 \uae30\uc5b5\ud558\uae30 \uc88b\uc740 \ubd80\ubd84\uc774 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \ub4a4\uc5d0\ub294 \uc18c\uc7ac\uc758 \uc131\uc9c8\uc744 \uc774\ud574\ud558\uace0 \ub2e4\ub978 \uc0ac\uc6a9\uc744 \ub5a0\uc62c\ub9ac\uba70 \uc2dc\ud5d8\ud55c \uc0ac\ub78c\ub4e4\uc774 \uc788\ub2e4. \uc6b0\uc5f0\ud788 \uc5bb\uc740 \uacb0\uacfc\uc640 \uadf8\uac83\uc744 \uc0ac\ub78c\uc758 \ubb3c\uac74\uc73c\ub85c \ubc14\uafb8\ub294 \uacfc\uc815\uc740 \ub098\ub204\uc5b4 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc774\ubc88 \uc6d0\uace0\ub294 \uad50\uc7ac\uc5d0 \uc18c\uac1c\ub41c \ud0c4\uc0dd \uc0ac\ub840\ub97c \uc77d\ub294 \uac83\uc774\ub2e4. \ud2b9\uc815 \ud604\uc7ac \uc81c\ud488\uc758 \uc811\ucc29\ub825\uc774\ub098 \ubaa8\ub4e0 \uc885\uc774\uc5d0\uc11c\uc758 \uc131\ub2a5\uc744 \ubcf4\uc99d\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc0dd\ud65c \uc18d\uc758 \ubc1c\uba85\ub2f4\uc744 \uc81c\ud488 \uc0ac\uc6a9 \uc2dc\ud5d8\uacfc \uad6c\ubcc4\ud558\uba74, \uc88b\uc740 \uc774\uc57c\uae30 \ub54c\ubb38\uc5d0 \ud655\uc778\ud558\uc9c0 \uc54a\uc740 \uae30\ub2a5\uae4c\uc9c0 \ub367\ubd99\uc774\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \ucc45\uc5d0 \ubd99\uc778 \uc791\uc740 \ud45c\uc2dc\ub97c \ub4e4\uc5b4 \uc62c\ub9ac\ub294 \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c \ud504\ub77c\uc774\uc758 \ucd08\uc0c1\uc774\ub098 \ub2f9\uc2dc\uc758 \ucc2c\uc1a1\uac00, \ucd5c\ucd08 \uc2dc\uc81c\ud488\uc744 \uc7ac\ud604\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ubd99\uc774\ub294 \uc77c\uacfc \ub5bc\ub294 \uc77c\uc774 \ud568\uaed8 \ud544\uc694\ud55c \uc0c1\ud669\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ubd84\uc704\uae30 \uadf8\ub9bc\uc774\ub2e4. \ud3ec\uc2a4\ud2b8\uc787\uc758 \ucd9c\ubc1c\uc740 \ubaa8\ub4e0 \uc2e4\ud328\ub97c \ubb34\uc870\uac74 \uc131\uacf5\uc774\ub77c \ubd80\ub974\uc790\ub294 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc5d0 \uc4f8 \ub54c \uc88b\uc740 \uc131\uc9c8\uc778\uc9c0 \ub2e4\uc2dc \ubb3b\ub294 \uc774\uc57c\uae30\ub2e4. \uc885\uc774\uac00 \ub5a8\uc5b4\uc9c0\ub294 \ubd88\ud3b8\uacfc \uc57d\ud558\uac8c \ubd99\ub294 \uc18c\uc7ac\uac00 \ub9cc\ub0ac\uc744 \ub54c, \ub530\ub85c \ubcf4\uba74 \uc544\uc26c\uc6e0\ub358 \ub450 \uc0c1\ud669\uc774 \uc775\uc219\ud55c \uba54\ubaa8\uc9c0\uc758 \uc2dc\uc791\uc774 \ub418\uc5c8\ub2e4."}, {"id": "pullman-town-wages-and-rent", "title": "\ud480\uba3c \u2014 \ud68c\uc0ac\uac00 \uc9d1\uae4c\uc9c0 \ub9c8\ub828\ud574 \uc8fc\uba74 \ud589\ubcf5\ud560\uae4c", "summary": "\uc88b\uc740 \uc8fc\uac70 \ud658\uacbd\uc744 \uc81c\uacf5\ud55c \ud480\uba3c\uc758 \ud68c\uc0ac \ub9c8\uc744\uc774 \uc784\uae08\uacfc \uc9d1\uc138, \uc0dd\ud65c \ud1b5\uc81c\uc758 \uac08\ub4f1\uc744 \ub9cc\ub09c \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\uacbd\uc601\uacfc \uc870\uc9c1", "categories": ["industry"], "url": "stories/pullman-town-wages-and-rent/index.html", "image": "../media/pullman-town-wages-and-rent.png", "alt": "\ubd89\uc740 \ubcbd\ub3cc \uc8fc\ud0dd\uac00\uc640 \ucca0\ub3c4\ucc28\ub7c9 \uacf5\uc7a5, \uc8fc\ubbfc\ub4e4\uc744 \uadf8\ub9b0 19\uc138\uae30 \ud68c\uc0ac \ub9c8\uc744\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ud480\uba3c \u2014 \ud68c\uc0ac\uac00 \uc9d1\uae4c\uc9c0 \ub9c8\ub828\ud574 \uc8fc\uba74 \ud589\ubcf5\ud560\uae4c \uce68\ub300\ucc28 \uacf5\uc7a5 \uc606\uc758 \ubaa8\ubc94 \ub9c8\uc744\uc5d0\uc11c 1894\ub144 \ud30c\uc5c5\uae4c\uc9c0 \uc88b\uc740 \uc8fc\uac70 \ud658\uacbd\uc744 \uc81c\uacf5\ud55c \ud480\uba3c\uc758 \ud68c\uc0ac \ub9c8\uc744\uc774 \uc784\uae08\uacfc \uc9d1\uc138, \uc0dd\ud65c \ud1b5\uc81c\uc758 \uac08\ub4f1\uc744 \ub9cc\ub09c \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uacbd\uc601\uacfc \uc870\uc9c1 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \uacf5\uc7a5 \uadfc\ucc98\uc5d0 \uc9d1\uc774 \uc788\uace0, \uc9d1\uc5d0\ub294 \uc218\ub3c4\uc640 \uac00\uc2a4\ub4f1\uc774 \ub4e4\uc5b4\uc628\ub2e4. \uacf5\uc6d0\uacfc \ub3c4\uc11c\uad00, \uadf9\uc7a5\ub3c4 \ub9c8\ub828\ub418\uc5b4 \uc788\ub2e4. 19\uc138\uae30 \ub178\ub3d9\uc790\uc5d0\uac8c \uc774\ub7f0 \ub3d9\ub124\ub294 \uaf64 \ub9e4\ub825\uc801\uc778 \uc81c\uc548\uc774\uc5c8\uc744 \uac83\uc774\ub2e4. \uadf8\ub7f0\ub370 \uc9d1\uc8fc\uc778\uacfc \uace0\uc6a9\uc8fc\uac00 \uac19\uc740 \uc0ac\ub78c\uc774\ub77c\uba74 \uc5b4\ub5a8\uae4c. \ubbf8\uad6d\uc758 \ucca0\ub3c4 \uce68\ub300\ucc28 \uc81c\uc870\uc5c5\uc790 \uc870\uc9c0 \ud480\uba3c\uc740 \ub178\ub3d9\uc790\ub4e4\uc744 \uc704\ud55c \ub9c8\uc744\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \uc88b\uc740 \uc9d1\uc744 \uc9d3\ub294 \uad6c\uc0c1\uc740 \ubd84\uba85\ud55c \uc7a5\uc810\uc774 \uc788\uc5c8\ub2e4. \ubb38\uc81c\ub294 \uadf8\uacf3\uc5d0\uc11c \uc88b\uc740 \uc0dd\ud65c\uc744 \ub204\ub9b4 \uc870\uac74\uc744 \ub204\uac00 \uacb0\uc815\ud558\ub290\ub0d0\uc600\ub2e4. \ud480\uba3c\uc740 \uc2dc\uce74\uace0 \ub0a8\ucabd\uc758 \uacf5\uc7a5 \uacc1\uc5d0 \uacc4\ud68d\uc801\uc778 \uc8fc\uac70\uc9c0\ub97c \ub9c8\ub828\ud588\ub2e4. \uc0b0\uc5c5\ub3c4\uc2dc\uc5d0 \uc0ac\ub78c\uc774 \ube60\ub974\uac8c \ubaa8\uc774\ub358 \uc2dc\ub300\uc600\ub2e4. \ub178\ub3d9\uc790\uc5d0\uac8c \uc77c\uc790\ub9ac\ub9cc\ud07c \uae09\ud55c \uac83\uc740 \uac00\uc871\uacfc \uba38\ubb3c \uc9d1\uc744 \uad6c\ud558\ub294 \uc77c\uc774\uc5c8\ub2e4. \ub2f9\uc2dc \ub3c4\uc2dc\uc758 \ub178\ub3d9\uc790 \uc8fc\uac70\ub294 \ube44\uc881\uace0 \ud658\uae30\ub098 \uc704\uc0dd \uc0c1\ud0dc\uac00 \ub098\uc05c \uacbd\uc6b0\uac00 \ub9ce\uc558\ub2e4. \uc774\ub7f0 \ubc30\uacbd\uc5d0\uc11c \uc815\ub3c8\ub41c \uac70\ub9ac\uc640 \uc2dc\uc124\uc744 \uac16\ucd98 \ud68c\uc0ac \ub9c8\uc744\uc740 \ub2e8\uc21c\ud55c \uc7a5\uc2dd\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc2e4\uc81c \uc0dd\ud65c\uc758 \ubd80\uc871\ud55c \ubd80\ubd84\uc744 \ucc44\uc6b0\ub294 \uc81c\uc548\uc774\uc5c8\ub2e4. \ub9c8\uc744\uc5d0\ub294 \uc0c1\uc810\uacfc \ud559\uad50, \ub3c4\uc11c\uad00\uacfc \uadf9\uc7a5, \uad50\ud68c\uac00 \uc788\uc5c8\ub2e4. \uc9d1\uc758 \uc218\ub3c4\uc640 \uac00\uc2a4\ub4f1\ubfd0 \uc544\ub2c8\ub77c \uc4f0\ub808\uae30 \uc218\uac70\uc640 \uacf5\uc6d0\ub3c4 \uc0dd\ud65c\uc758 \uc9c8\uc744 \ubc14\uafb8\ub294 \uc694\uc18c\uc600\ub2e4. \uacf5\uc7a5 \uc548\uc758 \uc0dd\uc0b0\uacfc \uacf5\uc7a5 \ubc16\uc758 \uc77c\uc0c1\uc744 \ud568\uaed8 \uc124\uacc4\ud55c \uc148\uc774\ub2e4. \ub178\ub3d9\uc790\uac00 \uc26c\uace0 \ubc30\uc6b0\uba70 \uac00\uc871\uacfc \uc9c0\ub0bc \ud658\uacbd\uc744 \ub9c8\ub828\ud558\uba74 \uc77c\ub3c4 \uc798\ud558\uace0 \uac08\ub4f1\ub3c4 \uc904\uc5b4\ub4e4 \uac83\uc774\ub77c\ub294 \uae30\ub300\uac00 \uc788\uc5c8\ub2e4. \uace0\uc6a9\uc8fc\uc5d0\uac8c\ub294 \ubcf5\uc9c0\uc640 \uc0dd\uc0b0\uc131\uc774 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc88b\uc740 \uc2dc\uc124\uc740 \ud638\uc758\uc778 \ub3d9\uc2dc\uc5d0 \uacbd\uc601\uc758 \ubc29\ubc95\uc774\uc5c8\ub2e4. \ub178\ub3d9\uc790\ub294 \uc784\uae08\uc744 \ubc1b\uc544 \uc9d1\uc138\ub97c \ub0b4\uace0 \uc0dd\ud65c\uc5d0 \ud544\uc694\ud55c \ubb3c\uac74\uc744 \uc0c0\ub2e4. \uadf8\ub7f0\ub370 \uadf8 \uc9d1\uc740 \ud68c\uc0ac\uac00 \uc81c\uacf5\ud55c \uc8fc\ud0dd\uc774\uc5c8\ub2e4. \ud68c\uc0ac\ub294 \uc0ac\ub78c\uc744 \uace0\uc6a9\ud558\ub294 \uacf3\uc774\uba74\uc11c \ub3d9\uc2dc\uc5d0 \ub9e4\ub2ec \uc8fc\uac70\ube44\ub97c \ubc1b\ub294 \ucabd\uc774\uae30\ub3c4 \ud588\ub2e4. \uc774 \uad6c\uc870\uc5d0\uc11c\ub294 \uc784\uae08\uacfc \uc9d1\uc138\ub97c \ub530\ub85c \ubcf4\uae30 \uc5b4\ub835\ub2e4. \uc77c\ud130\uc5d0\uc11c \ubc1b\ub294 \ub3c8\uc774 \uc904\uc5b4\ub3c4 \uc0b4 \uacf3\uc758 \ube44\uc6a9\uc774 \uadf8\ub300\ub85c\ub77c\uba74 \uc0dd\ud65c\uc740 \ube60\ub974\uac8c \uc5b4\ub824\uc6cc\uc9c4\ub2e4. \uac19\uc740 \uc561\uc218\uc758 \uc9d1\uc138\ub77c\ub3c4 \uc77c\uc790\ub9ac\uc640 \ubb36\uc77c \ub54c \ub178\ub3d9\uc790\uc5d0\uac8c \uc8fc\ub294 \uc555\ubc15\uc740 \ub2ec\ub77c\uc9c4\ub2e4. \uc9d1\uc744 \uad00\ub9ac\ud558\ub294 \ubc29\uc2dd\uc5d0\ub3c4 \uac08\ub4f1\uc758 \uc528\uc557\uc774 \uc788\uc5c8\ub2e4. \ud68c\uc0ac \uce21\uc740 \uc8fc\ud0dd\uc774 \uae68\ub057\ud558\uac8c \uc720\uc9c0\ub418\ub294\uc9c0 \uac80\uc0ac\ud588\ub2e4. \ub178\ub3d9\uc790\ub294 \uc9d1\uc744 \uc790\uae30 \uc18c\uc720\ub85c \uc0b4 \uc218 \uc5c6\uc5c8\uace0, \uc77c\uc790\ub9ac\ub97c \uc783\uc73c\uba74 \uac00\uc871\uc758 \uac70\ucc98\ub3c4 \uc704\ud0dc\ub85c\uc6cc\uc84c\ub2e4. \uc9d1\uc744 \uc798 \uad00\ub9ac\ud55c\ub2e4\ub294 \uba85\ubd84\uc774 \uac70\uc8fc\uc790\uc758 \uc0dd\ud65c\uc744 \uc0b4\ud53c\ub294 \uad8c\ud55c\uc73c\ub85c \uc774\uc5b4\uc9c4 \uac83\uc774\ub2e4. \uace0\uc6a9\uc8fc\uac00 \ubc14\ub77c\ub294 \uc815\ub3c8\ub41c \ub3d9\ub124\uc640 \uc8fc\ubbfc\uc774 \uc6d0\ud558\ub294 \uc0ac\uc801\uc778 \uacf5\uac04\uc740 \uaf2d \uac19\uc740 \ubaa8\uc2b5\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ubb38\uc744 \ub2eb\uc740 \ub4a4\uc5d0\ub3c4 \ud68c\uc0ac\uc758 \uc601\ud5a5\uc740 \ub0a8\uc558\ub2e4. \ud480\uba3c\uc740 \ub3c4\uc11c\uad00\uc5d0 \ub458 \ucc45\uacfc \uadf9\uc7a5\uc5d0\uc11c \uacf5\uc5f0\ud560 \uc791\ud488\uc758 \uc120\ud0dd\uc5d0\ub3c4 \uad00\uc5ec\ud588\ub2e4. \ub9c8\uc744\uc5d0 \uc5b4\ub5a4 \uc624\ub77d\uc744 \ub458 \uac83\uc778\uc9c0\uae4c\uc9c0 \ud68c\uc0ac\uac00 \ud310\ub2e8\ud588\ub2e4. \uad50\uc721\uacfc \ud734\uc2dd\uc758 \uae30\ud68c\ub97c \uc81c\uacf5\ud558\uba74\uc11c \uadf8 \ub0b4\uc6a9\ub3c4 \uad00\ub9ac\ud55c \uc148\uc774\ub2e4. \uc5ec\uae30\uc11c \ubcf5\uc9c0\uc758 \ub2e4\ub978 \uc9c8\ubb38\uc774 \ub098\uc628\ub2e4. \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uc88b\uc740 \uac83\uc744 \ub9c8\ub828\ud574 \uc8fc\ub294 \uc77c\uacfc, \ubb34\uc5c7\uc774 \uc88b\uc740\uc9c0 \uc2a4\uc2a4\ub85c \uace0\ub974\uac8c \ud558\ub294 \uc77c\uc740 \uac19\uc9c0 \uc54a\ub2e4. \uc2dc\uc124\uc774 \ud6cc\ub96d\ud558\ub354\ub77c\ub3c4 \uc120\ud0dd\uc758 \uc5ec\uc9c0\uac00 \uc881\uc73c\uba74 \ubd88\ub9cc\uc774 \uc0dd\uae38 \uc218 \uc788\uc5c8\ub2e4. \uacbd\uae30 \uce68\uccb4 \uc18d\uc5d0\uc11c \ud480\uba3c\uc740 \ub178\ub3d9\uc790\uc758 \uc784\uae08\uc744 \uc904\uc774\uace0 \uc77c\ubd80\ub97c \ud574\uace0\ud588\ub2e4. \uadf8\ub7ec\ub098 \uc9d1\uc138\ub294 \uadf8\uc5d0 \ub9de\ucdb0 \ub0ae\ucd94\uc9c0 \uc54a\uc558\ub2e4. \uc77c\ud130\uc758 \uc0ac\uc815\uc774 \uc5b4\ub835\ub2e4\ub294 \uc124\uba85\uc774 \uac00\uacc4\uc758 \uc8fc\uac70\ube44 \ubd80\ub2f4\uc744 \uc904\uc5ec \uc8fc\uc9c0\ub294 \uc54a\uc558\ub2e4. \ub178\ub3d9\uc790\ub4e4\uc740 \ud30c\uc5c5\uc73c\ub85c \ub9de\uc130\ub2e4. \ub9c8\uc744\uc744 \ub9cc\ub4e4\uba74 \uac08\ub4f1\uc744 \uc608\ubc29\ud560 \uc218 \uc788\uc73c\ub9ac\ub77c\ub294 \uae30\ub300\uc640 \ub2ec\ub9ac, \ud68c\uc0ac\uac00 \uc77c\uacfc \uc9d1\uc744 \ud568\uaed8 \uc9c0\ubc30\ud558\ub294 \uad6c\uc870\uac00 \uac08\ub4f1\uc758 \ud575\uc2ec\uc774 \ub418\uc5c8\ub2e4. \uc608\uc05c \uac70\ub9ac\ub9cc\uc73c\ub85c \ubd09\ud569\ud558\uae30 \uc5b4\ub824\uc6b4 \ubb38\uc81c\uc600\ub2e4. \uc774 \uc0ac\uac74\uc744 \ubcf4\uace0 \uc88b\uc740 \uc8fc\ud0dd\uacfc \uacf5\uc6d0\uc740 \uc18c\uc6a9\uc5c6\uc5c8\ub2e4\uace0 \uacb0\ub860\ub0bc \ud544\uc694\ub294 \uc5c6\ub2e4. \uc704\uc0dd\uc801\uc778 \uc9d1\uacfc \uad50\uc721 \uc2dc\uc124\uc758 \uac00\uce58\ub294 \ubd84\uba85\ud558\ub2e4. \ub2e4\ub9cc \uadf8\uac83\uc744 \uc774\uc6a9\ud560 \uc870\uac74\uacfc \uad8c\ud55c\uc758 \uad00\uacc4\ub3c4 \ud568\uaed8 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc9c1\uc7a5\uc774 \uc0ac\ub77c\uc9c0\ub294 \uc21c\uac04 \uc8fc\uac70\uae4c\uc9c0 \ud754\ub4e4\ub9b0\ub2e4\uba74 \ub178\ub3d9\uc790\uac00 \ud611\uc0c1\ud560 \uc5ec\uc9c0\ub294 \uc904\uc5b4\ub4e0\ub2e4. \ud480\uba3c\uc758 \uc774\uc57c\uae30\ub294 \ud61c\ud0dd\uc758 \uac1c\uc218\ubfd0 \uc544\ub2c8\ub77c \uadf8 \ud61c\ud0dd\uc774 \ub204\uad6c\uc758 \uacb0\uc815\uc5d0 \ub2ec\ub824 \uc788\ub294\uc9c0 \ubb3b\ub294\ub2e4. \ubcf5\uc9c0\uc758 \ubaa8\uc591\uacfc \uc548\uc815\uc131\uc740 \ubcc4\uac1c\uc758 \uc9c8\ubb38\uc774\uc5c8\ub2e4. \uacc4\ud68d\ub41c \uac70\ub9ac\uc640 \uac00\uc9c0\ub7f0\ud55c \uc8fc\ud0dd\uc740 \ubc29\ubb38\uac1d\uc774 \uc27d\uac8c \uc54c\uc544\ubcfc \uc218 \uc788\ub294 \uc131\uacfc\uc600\ub2e4. \ubc18\uba74 \uc9d1\uc138\ub97c \ub0b4\ub294 \uac00\uacc4\uc758 \ubd80\ub2f4\uc774\ub098 \uac80\uc0ac\ubc1b\ub294 \uc8fc\ubbfc\uc758 \uae30\ubd84\uc740 \uc678\uad00\ub9cc \ubcf4\uc544\uc11c\ub294 \uc54c\uae30 \uc5b4\ub835\ub2e4. \uac19\uc740 \ub9c8\uc744\uc774 \ubcf4\ub294 \uc0ac\ub78c\uc758 \uc704\uce58\uc5d0 \ub530\ub77c \ub2e4\ub974\uac8c \ubcf4\uc77c \uc218 \uc788\uc5c8\ub2e4. \uace0\uc6a9\uc8fc\uac00 \uc815\ud574 \uc900 \uc0dd\ud65c\uc744 \uc9c1\uc6d0\uc774 \uace0\ub9d9\uac8c \uc5ec\uae38 \uc218\ub3c4, \uac04\uc12d\uc73c\ub85c \ub290\ub084 \uc218\ub3c4 \uc788\ub2e4. \uc774 \ucc28\uc774\ub97c \uac1c\uc778\uc758 \uc131\uaca9 \ubb38\uc81c\ub85c\ub9cc \ub3cc\ub9ac\uba74 \ub204\uac00 \uaddc\uce59\uc744 \ubc14\uafc0 \uc218 \uc788\uc5c8\ub294\uc9c0 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ud68c\uc0ac\uc758 \ud310\ub2e8\uc5d0 \uc774\uc758\ub97c \uc81c\uae30\ud560 \ubc29\ubc95\ub3c4 \uc911\uc694\ud588\ub2e4. \uadf8\ub798\uc11c \ud480\uba3c \ub9c8\uc744\uc758 \uc2dc\uc124 \ubaa9\ub85d\uacfc 1894\ub144\uc758 \uac08\ub4f1\uc744 \ud568\uaed8 \uc77d\uc5b4\uc57c \ud55c\ub2e4. \ud3b8\uc758\uac00 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uac08\ub4f1\uc774 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ud568\uaed8 \uc131\ub9bd\ud55c\ub2e4. \ud55c\ucabd\uc744 \uc9c0\uc6cc\uc57c\ub9cc \ub2e4\ub978 \ucabd\uc744 \uc774\ud574\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud480\uba3c\uc740 \ub2f9\uc2dc\uc758 \ub2e4\ub978 \uc0b0\uc5c5\uac00\ub4e4\uc5d0\uac8c\ub3c4 \uc911\uc694\ud55c \ube44\uad50 \ub300\uc0c1\uc774 \ub418\uc5c8\ub2e4. \ub178\ub3d9\uc790\ub97c \uc704\ud55c \ub9c8\uc744\uc740 \ubbf8\uad6d\uacfc \uc720\ub7fd\uc758 \uc5ec\ub7ec \uacf3\uc5d0\uc11c \ub9cc\ub4e4\uc5b4\uc84c\ub2e4. \uc0b0\uc5c5\uc758 \uc131\uc7a5\uc740 \uacf5\uc7a5 \ub0b4\ubd80\ubfd0 \uc544\ub2c8\ub77c \uc0ac\ub78c\ub4e4\uc774 \uc0ac\ub294 \uc7a5\uc18c\uae4c\uc9c0 \ubc14\uafb8\uace0 \uc788\uc5c8\ub2e4. \uc774 \ub9c8\uc744\uc744 \ub3cc\uc544\ubcf4\uba70 \ub5a0\uc62c\ub9b4 \uac83\uc740 \uc9d1\uc758 \uc608\uc05c \uc678\uad00\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uc798 \ub9c8\ub828\ub41c \uc0dd\ud65c\uacfc \uc2a4\uc2a4\ub85c \uacb0\uc815\ud560 \uc0dd\ud65c\uc774 \uc5b4\ub5bb\uac8c \ud568\uaed8 \uac08 \uc218 \uc788\ub294\uac00. \uce68\ub300\ucc28 \uacf5\uc7a5 \uc606\uc758 \ub3d9\ub124\ub294 \uadf8 \uc624\ub798\ub41c \uc9c8\ubb38\uc744 \ub208\uc5d0 \ubcf4\uc774\ub294 \uac70\ub9ac\ub85c \ub0a8\uacbc\ub2e4."}, {"id": "sears-catalog-price-and-rural-door", "title": "\uc2dc\uc5b4\uc2a4 \u2014 \uc2dc\uace8\uc9d1 \uc2dd\ud0c1\uc5d0 \ubc31\ud654\uc810 \ud55c \uad8c\uc774 \ub3c4\ucc29\ud588\ub2e4", "summary": "19\uc138\uae30 \ub9d0 \uc6b0\ud3b8 \ud310\ub9e4\uc640 \uac00\uaca9\ud45c\ub97c \ub530\ub77c, \uac00\uac8c\uc5d0\uc11c \uba40\ub9ac \uc0b4\ub358 \uc0ac\ub78c\ub4e4\uc758 \uc18c\ube44\uac00 \ub2ec\ub77c\uc9c4 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\uc0c1\uc5c5\uacfc \uc720\ud1b5", "categories": ["industry"], "url": "stories/sears-catalog-price-and-rural-door/index.html", "image": "../media/sears-catalog-price-and-rural-door.png", "alt": "\uc2dc\uace8\uc9d1 \uc2dd\ud0c1 \uc704\uc5d0 \uc5f4\ub9b0 \uc6b0\ud3b8 \ud310\ub9e4 \uce74\ud0c8\ub85c\uadf8\uc640 \ubc30\ub2ec \uc18c\ud3ec\uac00 \ub193\uc778 \uc5ed\uc0ac\uc801 \ubd84\uc704\uae30 \uc0bd\ud654", "text": "\uc2dc\uc5b4\uc2a4 \u2014 \uc2dc\uace8\uc9d1 \uc2dd\ud0c1\uc5d0 \ubc31\ud654\uc810 \ud55c \uad8c\uc774 \ub3c4\ucc29\ud588\ub2e4 \uc6b0\ud3b8 \uce74\ud0c8\ub85c\uadf8\uac00 \ubb3c\uac74\uc744 \uace0\ub974\uace0 \uac00\uaca9\uc744 \ube44\uad50\ud558\ub294 \ubc29\uc2dd\uc744 \ubc14\uafb8\ub2e4 19\uc138\uae30 \ub9d0 \uc6b0\ud3b8 \ud310\ub9e4\uc640 \uac00\uaca9\ud45c\ub97c \ub530\ub77c, \uac00\uac8c\uc5d0\uc11c \uba40\ub9ac \uc0b4\ub358 \uc0ac\ub78c\ub4e4\uc758 \uc18c\ube44\uac00 \ub2ec\ub77c\uc9c4 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc0c1\uc5c5\uacfc \uc720\ud1b5 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \ub9c8\uc744\uc758 \uac00\uac8c\uc5d0\ub294 \uc5c6\ub294 \ubb3c\uac74\uc778\ub370 \ucc45 \uc18d\uc5d0\ub294 \uc788\ub2e4. \uc0dd\ud65c\uc6a9\ud488 \uc606\uc5d0 \uc790\uc804\uac70\uac00 \uc788\uace0, \ub18d\uc0ac\uc5d0 \uc4f8 \ubb3c\uac74\uc744 \ub118\uae30\ub2e4 \ubcf4\uba74 \uc9d1\uc5d0 \ub4e4\uc774\uace0 \uc2f6\uc740 \uc545\uae30\ub3c4 \ub098\uc628\ub2e4. 19\uc138\uae30 \ub9d0 \ubbf8\uad6d\uc758 \uc2dc\uace8\uc9d1\uc5d0 \ub3c4\ucc29\ud55c \uc2dc\uc5b4\uc2a4 \uce74\ud0c8\ub85c\uadf8\ub294 \uc77d\uc744\uac70\ub9ac\uc774\uba74\uc11c \uba3c \uacf3\uc758 \uc9c4\uc5f4\uc7a5\uc774\uc5c8\ub2e4. \uc624\ub298\uc758 \uc628\ub77c\uc778 \uc1fc\ud551\uc744 \uadf8\ub300\ub85c \uc61b\ub0a0\ub85c \uc62e\uaca8 \ub193\uc744 \uc218\ub294 \uc5c6\ub2e4. \uc8fc\ubb38\uacfc \uc6b4\uc1a1\uc5d0\ub294 \uc2dc\uac04\uc774 \uac78\ub838\uace0 \uc0c1\ud488\uc744 \uc190\uc73c\ub85c \ub9cc\uc838 \ubcf4\uae30\ub3c4 \uc5b4\ub824\uc6e0\ub2e4. \uadf8\ub798\ub3c4 \uc885\uc774\uc5d0 \ucc0d\ud78c \ubb3c\uac74\uacfc \uac00\uaca9\uc774 \ub3d9\ub124 \uac00\uac8c\ub9cc \ubc14\ub77c\ubcf4\ub358 \uc18c\ube44\uc790\uc5d0\uac8c \ub2e4\ub978 \uc120\ud0dd\uc744 \uc5f4\uc5b4 \uc8fc\uc5c8\ub2e4\ub294 \uc810\uc740 \ubd84\uba85\ud558\ub2e4. \ub3c4\uc2dc\uc5d0 \ud070 \uc0c1\uc810\uc774 \ub298\uc5b4\ub098\ub294 \ub3d9\uc548 \ub18d\ucd0c\uc758 \uc18c\ube44 \ud658\uacbd\uc740 \ub2ec\ub790\ub2e4. \uba3c \uac70\ub9ac\ub97c \uc774\ub3d9\ud574 \ubb3c\uac74\uc744 \ube44\uad50\ud558\ub294 \ub370\uc5d0\ub294 \uc2dc\uac04\uacfc \ube44\uc6a9\uc774 \ub4e4\uc5c8\ub2e4. \uac00\uae4c\uc6b4 \uc0c1\uc810\uc758 \ud488\ubaa9\uacfc \uac70\ub798 \uc870\uac74\uc774 \uc77c\uc0c1\uc5d0\uc11c \ub354 \uc911\uc694\ud560 \uc218\ubc16\uc5d0 \uc5c6\uc5c8\ub2e4. \uc2f8\uac8c \uc0b4 \uacf3\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c\uc544\ub3c4 \uc27d\uac8c \uac08 \uc218 \uc5c6\ub2e4\uba74 \uc120\ud0dd\uc9c0\ub294 \uc881\ub2e4. \uc6b0\ud3b8 \ud310\ub9e4\ub294 \uc774\ub7f0 \uac70\ub9ac\uc758 \uc870\uac74\uc5d0 \ub4e4\uc5b4\uc654\ub2e4. \uc190\ub2d8\uc774 \uc9c4\uc5f4\uc7a5\uae4c\uc9c0 \uc6c0\uc9c1\uc774\ub294 \ub300\uc2e0 \uc9c4\uc5f4\uc7a5\uc758 \uc124\uba85\uc774 \uc190\ub2d8\uc5d0\uac8c \uac04\ub2e4. \ubb3c\ub860 \ubc30\ub2ec\uc774\ub77c\ub294 \ub610 \ub2e4\ub978 \uac70\ub9ac\uac00 \ub0a8\uc9c0\ub9cc, \ubb34\uc5c7\uc744 \uc0b4 \uc218 \uc788\ub294\uc9c0 \uc54c\uc544\ubcf4\ub294 \ub2e8\uacc4\ubd80\ud130 \ub2ec\ub77c\uc9c4\ub2e4. \uc1fc\ud551\uc758 \ucd9c\ubc1c\uc810\uc774 \uac00\uac8c\uc758 \ubb38\uc5d0\uc11c \uc9d1 \uc548\uc758 \uc2dd\ud0c1\uc73c\ub85c \uc62e\uaca8\uc62c \uc218 \uc788\uc5c8\ub2e4. \uc6b0\ud3b8 \uc8fc\ubb38\uc758 \uc5ed\uc0ac\ub97c \uc2dc\uc5b4\uc2a4 \ud55c \ud68c\uc0ac\uac00 \ucc98\uc74c\ubd80\ud130 \ub9cc\ub4e4\uc5c8\ub2e4\uace0 \uc124\uba85\ud558\uba74 \uc55e\uc120 \uc2e4\ud5d8\ub4e4\uc774 \uc0ac\ub77c\uc9c4\ub2e4. 1872\ub144\uc5d0 \uc0ac\uc5c5\uc744 \uc2dc\uc791\ud55c \ubabd\uace0\uba54\ub9ac \uc6cc\ub4dc\ub3c4 \uc911\uc694\ud55c \uc120\uad6c\uc790\uc600\ub2e4. \uc2dc\uc5b4\uc2a4\ub294 \ub4a4\uc774\uc5b4 \uc131\uc7a5\ud558\uba70 \ud070 \uaddc\ubaa8\uc758 \uce74\ud0c8\ub85c\uadf8 \uc0ac\uc5c5\uc744 \ud3bc\ucce4\ub2e4. \ud55c \ud68c\uc0ac\uc758 \uc131\uacf5\uc740 \uc774\ubbf8 \uc0dd\uaca8\ub098\ub358 \uc2dc\uc7a5\uc758 \ubcc0\ud654 \uc18d\uc5d0 \uc788\uc5c8\ub2e4. \uce74\ud0c8\ub85c\uadf8\ub97c \ub110\ub9ac \ubcf4\ub0b4\ub824\uba74 \uc778\uc1c4\ub9cc \uc798\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ub2e4\uc591\ud55c \ubb3c\uac74\uc744 \ub9c8\ub828\ud558\uace0 \uc8fc\ubb38\uc744 \uc815\ub9ac\ud558\uba70 \uc2e4\uc81c\ub85c \ubcf4\ub0b4\ub294 \uccb4\uacc4\uac00 \ud568\uaed8 \ud544\uc694\ud558\ub2e4. \ucc45 \uc18d\uc5d0 \ub9ce\uc740 \uc0c1\ud488\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uadf8 \ub4a4\uc5d0\uc11c \ub9ce\uc740 \uc885\ub958\uc758 \uac70\ub798\ub97c \uad00\ub9ac\ud558\uace0 \uc788\ub2e4\ub294 \ub73b\uc774\uae30\ub3c4 \ud588\ub2e4. \uc885\uc774\ucc45\uc758 \ub450\uaed8\ub294 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc6b4\uc601\uc758 \ub450\uaed8\uc640 \uc5f0\uacb0\ub41c\ub2e4. \uce74\ud0c8\ub85c\uadf8\uc5d0\ub294 \ubb3c\uac74\uc758 \uc124\uba85\uacfc \uac00\uaca9\uc774 \ud568\uaed8 \uc2e4\ub838\ub2e4. \uc18c\ube44\uc790\ub294 \uc0c1\uc810 \uc8fc\uc778\uacfc \ubc14\ub85c \ub300\ud654\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub2e4\ub978 \uc0c1\ud488\uc758 \uac12\uc744 \ube44\uad50\ud560 \uc218 \uc788\uc5c8\ub2e4. \ud2b9\ud788 \uac00\uae4c\uc6b4 \uac00\uac8c\uc758 \ub192\uc740 \uac00\uaca9\uc774\ub098 \uc678\uc0c1 \uac70\ub798\uc5d0 \uc758\uc874\ud558\ub358 \uc0ac\ub78c\uc5d0\uac8c, \ub2e4\ub978 \ud310\ub9e4\uc790\uac00 \uc81c\uc2dc\ud55c \uc870\uac74\uc744 \ubbf8\ub9ac \uc544\ub294 \uc77c\uc740 \uc758\ubbf8\uac00 \uc788\uc5c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc22b\uc790\uac00 \uc801\ud600 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ucd5c\uc885 \ube44\uc6a9\uc774 \ubaa8\ub450 \uac19\uc544\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc6b4\uc1a1\uacfc \uc8fc\ubb38\uc758 \uc870\uac74\ub3c4 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc911\uc694\ud55c \ubcc0\ud654\ub294 \ubaa8\ub4e0 \ubb3c\uac74\uc774 \ubb34\uc870\uac74 \uc2f8\uc84c\ub2e4\ub294 \uc8fc\uc7a5\uc774 \uc544\ub2c8\ub77c \ube44\uad50\ud560 \uc790\ub8cc\uac00 \uc9d1\uc73c\ub85c \ub4e4\uc5b4\uc654\ub2e4\ub294 \ub370 \uc788\ub2e4. \uac00\uaca9\uc744 \uc544\ub294 \uc18c\ube44\uc790\uc640 \ubaa8\ub974\ub294 \uc18c\ube44\uc790\uc758 \ud611\uc0c1 \uc790\ub9ac\ub294 \uac19\uc9c0 \uc54a\ub2e4. \uce74\ud0c8\ub85c\uadf8\uc758 \ub9e4\ub825\uc740 \ub2f9\uc7a5 \ud544\uc694\ud55c \uc18c\ubaa8\ud488\ub9cc \ubcf4\uc5ec \uc8fc\uc9c0 \uc54a\ub294\ub2e4\ub294 \ub370 \uc788\uc5c8\ub2e4. \ub18d\uae30\uad6c\uc640 \uc77c\uc0c1\uc6a9\ud488\uc744 \ucc3e\ub2e4\uac00 \uc5ec\uac00\uc640 \ucde8\ud5a5\uc758 \ubb3c\uac74\uc744 \ub9cc\ub0a0 \uc218 \uc788\ub2e4. \ubb3c\uac74\uc744 \ub9c8\ub828\ud558\ub294 \ucc45\uc778 \ub3d9\uc2dc\uc5d0, \uc5b4\ub5a4 \uc0dd\ud65c\uc744 \ud574 \ubcfc \uc218 \uc788\uc744\uc9c0 \uc0c1\uc0c1\ud558\uac8c \ud558\ub294 \ucc45\uc774 \ub41c\ub2e4. \uad6c\ub9e4 \uc774\uc804\uc5d0 \uad6c\uacbd\uc774 \uc2dc\uc791\ub418\ub294 \uac83\uc774\ub2e4. \uc774\ub7f0 \ubcc0\ud654\ub294 \uae30\ud68c\uc774\uba74\uc11c \uc720\ud639\uc774\uae30\ub3c4 \ud558\ub2e4. \uc120\ud0dd\uc774 \ub113\uc5b4\uc9c0\ub294 \uac83\uacfc \ud544\uc694 \uc774\uc0c1\uc758 \uc18c\ube44\uac00 \ub298\uc5b4\ub098\ub294 \uc77c\uc740 \ud568\uaed8 \uc77c\uc5b4\ub0a0 \uc218 \uc788\ub2e4. \uce74\ud0c8\ub85c\uadf8\ub97c \uc0dd\ud65c\uc758 \ud574\ubc29\uc790\ub85c\ub9cc \uce6d\ucc2c\ud558\uac70\ub098 \uc18c\ube44\uc758 \ud568\uc815\uc73c\ub85c\ub9cc \ubcf4\ub294 \ub300\uc2e0, \uc0c8\ub85c\uc6b4 \uc9c4\uc5f4\uc7a5\uc774 \uc0ac\ub78c\uc758 \uae30\ub300\ub97c \uc5b4\ub5bb\uac8c \ubc14\uafb8\uc5c8\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uba74 \uc88b\ub2e4. \ub3d9\ub124 \uac00\uac8c\uc5d0\uc11c\ub294 \ubb3c\uac74\uc744 \ub208\uc55e\uc5d0 \ub193\uace0 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uce74\ud0c8\ub85c\uadf8 \uc8fc\ubb38\uc5d0\uc11c\ub294 \uadf8\ub9bc\uacfc \uc124\uba85\uc744 \ubbff\uc5b4\uc57c \ud55c\ub2e4. \ub450 \ud310\ub9e4 \ubc29\uc2dd\uc740 \uc2e0\ub8b0\ub97c \ub9cc\ub4dc\ub294 \ubc29\ubc95\uc774 \ub2e4\ub974\ub2e4. \uc124\uba85\uc774 \uc815\ud655\ud55c\uc9c0, \uc8fc\ubb38\ud55c \uac83\uc774 \uc81c\ub300\ub85c \uc624\ub294\uc9c0\uc5d0 \ub300\ud55c \uacbd\ud5d8\uc774 \uc313\uc5ec\uc57c \ub2e4\uc74c \uc8fc\ubb38\uc73c\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \uc774 \uc0ac\uc5c5\uc758 \ud575\uc2ec\uc744 \ub450\uaebc\uc6b4 \ucc45 \ud55c \uad8c\uc73c\ub85c\ub9cc \uc904\uc774\uae30\ub294 \uc5b4\ub835\ub2e4. \uad11\uace0\uac00 \ub9cc\ub4e0 \uae30\ub300\uc640 \uc2e4\uc81c\ub85c \ubc1b\uc740 \ubb3c\uac74 \uc0ac\uc774\uc758 \ucc28\uc774\ub97c \uad00\ub9ac\ud574\uc57c \ud588\ub2e4. \uc624\ub298\uc758 \ub3c5\uc790\ub294 \uc138\ubd80 \uc81c\ub3c4\ub97c \ubaa8\ub450 \uc54c\uc9c0 \ubabb\ud574\ub3c4 \uadf8 \ubb38\uc81c\ub97c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uba40\ub9ac \uc788\ub294 \ud310\ub9e4\uc790\ub97c \ubbff\ub294 \uc77c\uc740 \ubb3c\uac74\uc758 \uac00\uaca9\ub9cc\uc73c\ub85c \ud574\uacb0\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc0c8\ub85c\uc6b4 \ud310\ub9e4\uc790\ub294 \uae30\uc874 \uc0c1\uc810\uacfc \uacbd\uc7c1\ud588\ub2e4. \uc2dc\uace8 \uc18c\ube44\uc790\uc5d0\uac8c \uc120\ud0dd\uc774 \ub298\uc5c8\ub2e4\ub294 \ubc18\uac00\uc6b4 \ub9d0\uc758 \ubc18\ub300\ud3b8\uc5d0\ub294 \uac70\ub798\ub97c \ube7c\uc557\uae38 \uc218 \uc788\ub294 \uc9c0\uc5ed \uc0c1\uc778\uc758 \uac71\uc815\ub3c4 \uc788\uc5c8\ub2e4. \uac19\uc740 \uce74\ud0c8\ub85c\uadf8\ub97c \ub204\uad70\uac00\ub294 \ud3b8\ub9ac\ud55c \uc548\ub0b4\uc11c\ub85c, \ub2e4\ub978 \ub204\uad70\uac00\ub294 \uba3c \uacf3\uc5d0\uc11c \ub4e4\uc5b4\uc628 \uacbd\uc7c1\uc790\ub85c \ubcf4\uc558\uc744 \uac83\uc774\ub2e4. \uc774\uac83\uc744 \uc0c8\uac83\uc740 \uc5b8\uc81c\ub098 \uc633\uace0 \uc61b\uac83\uc740 \uc5b8\uc81c\ub098 \ub4a4\ucc98\uc84c\ub2e4\ub294 \uc774\uc57c\uae30\ub85c \ub9cc\ub4e4 \ud544\uc694\ub294 \uc5c6\ub2e4. \uac00\uae4c\uc6b4 \uac00\uac8c\uac00 \uc81c\uacf5\ud558\ub358 \uc11c\ube44\uc2a4\uc640 \uad00\uacc4\ub3c4 \uc788\uc5c8\ub2e4. \uc6b0\ud3b8 \ud310\ub9e4\uc758 \uc131\uc7a5\uc740 \uc0ac\ub78c\ub4e4\uc774 \ubb34\uc5c7\uc744 \uc5b4\ub290 \uacbd\ub85c\ub85c \uc0ac\ub294\uc9c0 \ub2e4\uc2dc \ub098\ub204\ub294 \uacfc\uc815\uc774\uc5c8\ub2e4. \uc18c\ube44\uc758 \uc5ed\uc0ac\ub294 \ud3b8\ub9ac\ud568\uacfc \ud568\uaed8 \uac70\ub798\uc758 \uc790\ub9ac\uac00 \ubc14\ub00c\ub294 \uc5ed\uc0ac\ub2e4. \ub2e4\uc2dc \uc2dd\ud0c1 \uc704\uc758 \ucc45\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ud398\uc774\uc9c0\ub97c \ub118\uae30\ub294 \uc190\uc740 \uac00\ubccd\uc9c0\ub9cc \uadf8 \ub4a4\uc5d0\uc11c\ub294 \uc0c1\ud488\uacfc \uc8fc\ubb38, \ud3ec\uc7a5\uacfc \uc6b4\uc1a1\uc774 \uc6c0\uc9c1\uc778\ub2e4. \uc2dc\uc5b4\uc2a4\uc758 \uc774\uc57c\uae30\ub294 \ubb3c\uac74\uc744 \uc798 \uace0\ub974\ub294 \ud310\ub9e4\uc790\uc758 \uac10\uac01\ub9cc\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc57d\uc18d\ud55c \ubb3c\uac74\uc744 \uba3c \uc18c\ube44\uc790\uc5d0\uac8c \ubcf4\ub0b4\ub294 \uc77c\uc744 \ubc18\ubcf5\ud560 \uc218 \uc788\uc5b4\uc57c \ud588\ub2e4. \ud654\uba74\uc73c\ub85c \uc0c1\ud488\uc744 \uace0\ub974\ub294 \uc624\ub298\uc5d0\ub3c4 \ube44\uc2b7\ud55c \uc9c8\ubb38\uc740 \ub0a8\ub294\ub2e4. \ubb34\uc5c7\uc774 \ubcf4\uc774\ub294\uac00, \uc870\uac74\uc740 \ucda9\ubd84\ud788 \uc124\uba85\ub418\uc5c8\ub294\uac00, \uc120\ud0dd\ud55c \ubb3c\uac74\uc740 \uc5b4\ub5bb\uac8c \uc624\ub294\uac00. \uc2dc\uc5b4\uc2a4 \uce74\ud0c8\ub85c\uadf8\ub294 \uc778\ud130\ub137\uc744 \ubbf8\ub9ac \ubc1c\uba85\ud55c \ubb3c\uac74\uc774 \uc544\ub2c8\ub2e4. \uadf8\ubcf4\ub2e4 \uc624\ub798\ub41c \ubb38\uc81c, \uba40\ub9ac \uc0ac\ub294 \uc0ac\ub78c\uacfc \uc5b4\ub5bb\uac8c \uac70\ub798\ud560 \uac83\uc778\uac00\uc5d0 \ub300\ud55c \ud55c \uc2dc\ub300\uc758 \ub2f5\uc774\uc5c8\ub2e4."}, {"id": "singer-sewing-machine-and-installments", "title": "\uc2f1\uc5b4 \u2014 \uc7ac\ubd09\ud2c0\uc740 \uc5b4\ub5bb\uac8c \uc9d1 \uc548\uc73c\ub85c \ub4e4\uc5b4\uc654\uc744\uae4c", "summary": "\uc7ac\ubd09\ud2c0\uc758 \uc5ec\ub7ec \uae30\uc220\uacfc \ud2b9\ud5c8, \ubc29\ubb38 \ud310\ub9e4\uc640 \ud560\ubd80\uac00 \uc0dd\ud65c \uc18d \ubcf4\uae09\uc73c\ub85c \uc774\uc5b4\uc9c4 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\uc0c1\uc5c5\uacfc \uc720\ud1b5", "categories": ["industry"], "url": "stories/singer-sewing-machine-and-installments/index.html", "image": "../media/singer-sewing-machine-and-installments.jpg", "alt": "\uc2f1\uc5b4\uc758 \ucd08\uae30 \uc7ac\ubd09\ud2c0 \uad6c\uc870\ub97c \ubcf4\uc5ec \uc8fc\ub294 1900\ub144 \ucc45\uc758 \uc5ed\uc0ac \uadf8\ub9bc", "text": "\uc2f1\uc5b4 \u2014 \uc7ac\ubd09\ud2c0\uc740 \uc5b4\ub5bb\uac8c \uc9d1 \uc548\uc73c\ub85c \ub4e4\uc5b4\uc654\uc744\uae4c \ubcf5\uc218\uc758 \ubc1c\uba85\uacfc \ud2b9\ud5c8, \ubc29\ubb38 \ud310\ub9e4\uc640 \ud560\ubd80\uac00 \ub9cc\ub4e0 \uc7ac\ubd09\ud2c0 \uc2dc\uc7a5 \uc7ac\ubd09\ud2c0\uc758 \uc5ec\ub7ec \uae30\uc220\uacfc \ud2b9\ud5c8, \ubc29\ubb38 \ud310\ub9e4\uc640 \ud560\ubd80\uac00 \uc0dd\ud65c \uc18d \ubcf4\uae09\uc73c\ub85c \uc774\uc5b4\uc9c4 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc0c1\uc5c5\uacfc \uc720\ud1b5 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \ubc1c\ub85c \ud310\uc744 \ubc1f\uc73c\uba74 \ubc14\ub298\uc774 \uc6c0\uc9c1\uc774\uace0, \uc190\uc73c\ub85c \ubc00\uc5b4 \uc8fc\ub294 \ucc9c \uc704\uc5d0 \ubc14\ub290\uc9c8\uc774 \uc774\uc5b4\uc9c4\ub2e4. \uc624\ub798\ub41c \uc7ac\ubd09\ud2c0\uc744 \ubcf4\uba74 \uae30\uacc4\uc758 \uad6c\uc870\ubcf4\ub2e4 \uba3c\uc800 \uc775\uc219\ud55c \uc0dd\ud65c\uc758 \ud48d\uacbd\uc774 \ub5a0\uc624\ub978\ub2e4. \uadf8\ub7ec\ub098 \uc7ac\ubd09\ud2c0\uc774 \ub9ce\uc740 \uc9d1\uc5d0 \ub193\uc774\uae30\uae4c\uc9c0\ub294 \uc88b\uc740 \ubc1c\uba85\ub9cc\uc73c\ub85c \ud574\uacb0\ub418\uc9c0 \uc54a\ub294 \ubb38\uc81c\uac00 \uc788\uc5c8\ub2e4. \ub9cc\ub4e4\uace0 \uc54c\ub9ac\uace0 \ud314\uace0 \uac12\uc744 \ubc1b\ub294 \uc77c\uc774 \ud568\uaed8 \ud544\uc694\ud588\ub2e4. \uc2f1\uc5b4\uc758 \uc5ed\uc0ac\ub294 \uc774 \uacfc\uc815\uc744 \uc0b4\ud3b4\ubcf4\uae30 \uc88b\uc740 \uc0ac\ub840\ub2e4. \ud55c \uc0ac\ub78c\uc774 \ubc14\ub290\uc9c8 \uae30\uacc4\uc758 \ubaa8\ub4e0 \uac83\uc744 \ucc98\uc74c \ubc1c\uba85\ud588\ub2e4\ub294 \uc601\uc6c5\ub2f4\uc73c\ub85c \uc77d\uae30\ubcf4\ub2e4 \uc5ec\ub7ec \uae30\uc220\uacfc \ud2b9\ud5c8, \ud310\ub9e4 \ubc29\uc2dd\uc774 \ub9cc\ub09c \uc2dc\uc7a5\uc73c\ub85c \ubcf4\uba74 \uae30\uc5c5\uc774 \uc131\uc7a5\ud558\ub294 \uacfc\uc815\uc774 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4. \uc7ac\ubd09\ud2c0\uc740 \ubc14\ub298\uc744 \uc704\uc544\ub798\ub85c \ube60\ub974\uac8c \uc6c0\uc9c1\uc774\ub294 \uc7a5\uce58\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uc2e4\uc744 \uac78\uc5b4 \ub540\uc744 \ub9cc\ub4e4\uace0 \ucc9c\uc744 \uc77c\uc815\ud558\uac8c \ubcf4\ub0b4\uba70 \ub2e4\uc74c \ubc14\ub298\ub540\uc774 \ub193\uc77c \uc704\uce58\ub97c \ub9de\ucdb0\uc57c \ud55c\ub2e4. \uc774 \ub3d9\uc791\ub4e4\uc774 \ud568\uaed8 \ubc18\ubcf5\ub418\uc5b4\uc57c \uc2e4\uc81c\ub85c \uc4f8 \uc218 \uc788\ub294 \uae30\uacc4\uac00 \ub41c\ub2e4. \uac01\uac01\uc758 \ubd80\ud488\uc774 \uc88b\uc544\ub3c4 \uc804\uccb4\uac00 \ub9de\uc9c0 \uc54a\uc73c\uba74 \ubc14\ub290\uc9c8\uc740 \uc774\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. 19\uc138\uae30\uc5d0\ub294 \uc5ec\ub7ec \ubc1c\uba85\uc790\uac00 \uc774 \ubb38\uc81c\ub97c \uc11c\ub85c \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ud480\uc5c8\ub2e4. \uc5d8\ub9ac\uc5b4\uc2a4 \ud558\uc6b0\uc640 \uc568\ub7f0 \uc70c\uc2a8, \uc2f1\uc5b4 \ub4f1 \uc5ec\ub7ec \uc774\ub984\uc774 \uc7ac\ubd09\ud2c0\uc758 \uc5ed\uc0ac\uc5d0 \ub4f1\uc7a5\ud558\ub294 \uc774\uc720\ub2e4. \ud68c\uc0ac\uc758 \uc0c1\ud45c\uac00 \ub110\ub9ac \uc54c\ub824\uc84c\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8 \ud68c\uc0ac\uac00 \ubaa8\ub4e0 \ud575\uc2ec \uc6d0\ub9ac\ub97c \ud63c\uc790 \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \uc8fc\uc7a5\uc740 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \uc544\uc774\uc791 \uc2f1\uc5b4\ub294 1851\ub144 \uc7ac\ubd09\ud2c0 \ud2b9\ud5c8\ub97c \ubc1b\uc558\ub2e4. \ub2f9\uc2dc \uc2f1\uc5b4 \uae30\uacc4\ub294 \uc7ac\ub2e8\uacfc \uac00\uc8fd \uc791\uc5c5\ucc98\ub7fc \ub354 \ud798 \uc788\ub294 \uae30\uacc4\ub97c \uc694\uad6c\ud558\ub294 \uc791\uc5c5\uc5d0 \ub300\uc751\ud588\ub2e4. \uc791\uc5c5\ub300 \uc704\ub85c \ubed7\uc740 \uac00\ub85c \ud314\uacfc \uc774\ub97c \ubc1b\uce58\ub294 \uad6c\uc870\ub3c4 \uc911\uc694\ud55c \ud2b9\uc9d5\uc774\uc5c8\ub2e4. \uc624\ub298\uc758 \ub3c5\uc790\uac00 \uc7ac\ubd09\ud2c0\ub2f5\ub2e4\uace0 \ub290\ub07c\ub294 \ubaa8\uc591\uc5d0\ub3c4 \uc774\ub7f0 \uac1c\ubc1c\uc758 \uc2dc\uac04\uc774 \uc788\ub2e4. \uae30\uacc4\uac00 \uc131\uacf5\ud558\ub824\uba74 \uc6c0\uc9c1\uc778\ub2e4\ub294 \uc2dc\uc5f0\uc744 \ub118\uc5b4 \uc2e4\uc81c \uc791\uc5c5\uc5d0\uc11c \uc4f8 \ub9cc\ud574\uc57c \ud588\ub2e4. \uc5b4\ub5a4 \ucc9c\uacfc \uc7ac\ub8cc\ub97c \ub2e4\ub8e8\ub294\uc9c0, \uc0ac\uc6a9\uc790\uac00 \uc5bc\ub9c8\ub098 \uc548\uc815\uc801\uc73c\ub85c \ub2e4\ub8f0 \uc218 \uc788\ub294\uc9c0\uac00 \uc911\uc694\ud588\ub2e4. \uae30\uc220\uc758 \uc131\ub2a5\uc740 \ucd94\uc0c1\uc801\uc778 \ucd5c\uace0 \uc18d\ub3c4\ub9cc\uc73c\ub85c \uc815\ud574\uc9c0\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uad6c\uccb4\uc801\uc778 \uc77c\ud130\uc758 \uc694\uad6c\uc640 \ub9cc\ub098 \ud3c9\uac00\ub418\uc5c8\ub2e4. \uc7ac\ubd09\ud2c0\uc5d0\ub294 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc911\uc694\ud55c \uae30\uc220\uc774 \ub4e4\uc5b4\uac14\ub2e4. \uadf8\ub9cc\ud07c \ud2b9\ud5c8\ub97c \ub458\ub7ec\uc2fc \uad8c\ub9ac \ubb38\uc81c\ub3c4 \ubcf5\uc7a1\ud588\ub2e4. 1856\ub144\uc5d0\ub294 \uc8fc\uc694 \ud2b9\ud5c8\uad8c\uc790\ub4e4\uc774 \uc774\ub978\ubc14 \uc7ac\ubd09\ud2c0 \uacb0\ud569\uc744 \uc774\ub8e8\uc5b4 \uacf5\ud1b5\uc758 \ud5c8\uac00\ub8cc\uc640 \uad8c\ub9ac \ubcf4\ud638\ub97c \ub2e4\ub8e8\uc5c8\ub2e4. \uc11c\ub85c \uacbd\uc7c1\ud558\ub358 \uae30\uc5c5\ub4e4\uc774 \uc77c\uc815\ud55c \uaddc\uce59 \uc544\ub798 \uae30\uc220 \uc0ac\uc6a9\uc744 \uc870\uc815\ud55c \uac83\uc774\ub2e4. \uc774 \uc77c\uc740 \ubc1c\uba85\uc774 \ub05d\ub098\uba74 \uace7\ubc14\ub85c \uc790\uc720\ub85c\uc6b4 \uc0dd\uc0b0\uc774 \uc2dc\uc791\ub41c\ub2e4\ub294 \uc0dd\uac01\uc744 \ubc14\uafbc\ub2e4. \uae30\uacc4\ub97c \ub9cc\ub4dc\ub294 \ub2a5\ub825\uacfc \uadf8\uac83\uc744 \ubc95\uc801\uc73c\ub85c \ud310\ub9e4\ud560 \uc218 \uc788\ub294 \uc870\uac74\uc740 \uc11c\ub85c \ub2e4\ub978 \ubb38\uc81c\ub2e4. \uc0dd\uc0b0\ud488 \ud558\ub098\uc758 \ub4a4\uc5d0 \uc5ec\ub7ec \uad8c\ub9ac\uac00 \uc5bd\ud790 \ub54c \uae30\uc5c5\uc740 \uae30\uc220\uc790\ubfd0 \uc544\ub2c8\ub77c \ud611\uc0c1\uacfc \uacc4\uc57d\uc758 \ub2a5\ub825\ub3c4 \ud544\uc694\ub85c \ud55c\ub2e4. \uc7ac\ubd09\ud2c0 \uc2dc\uc7a5\uc5d0\uc11c\ub294 \ud310\ub9e4\uc6d0\uc774 \ub3c4\uc2dc\uc640 \ub9c8\uc744, \ub18d\uac00\ub97c \ucc3e\uc544\ub2e4\ub2c8\uba70 \uc81c\ud488\uc744 \uc54c\ub838\ub2e4. \uad6c\uacbd\ud558\ub294 \uc0ac\ub78c\uc774 \uae30\uacc4\ub97c \uc775\ud788\uace0 \uc790\uae30 \uc0dd\ud65c\uc5d0 \uc5b4\ub5a4 \ub3c4\uc6c0\uc774 \ub420\uc9c0 \uc774\ud574\ud574\uc57c \uc8fc\ubb38\uc73c\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \uc774\ubbf8 \ud544\uc694\uac00 \ub69c\ub837\ud55c \uc18c\ubaa8\ud488\uacfc \ub2ec\ub9ac \uc0c8\ub85c\uc6b4 \uae30\uacc4\ub294 \uc4f8\ubaa8\ub97c \uc124\uba85\ud558\ub294 \uacfc\uc815\ub3c4 \ud310\ub9e4\uc758 \uc77c\ubd80\uc600\ub2e4. \uc774\ub7f0 \ubc29\ubb38 \ud310\ub9e4\uc5d0\ub294 \ube44\uc6a9\uc774 \ub4e4\uc5c8\ub2e4. \ud310\ub9e4\uc6d0\uc758 \uc218\uc218\ub8cc\uc640 \uc601\uc5c5 \ud65c\ub3d9\uc740 \uc18c\ube44\uc790\uac00 \uce58\ub974\ub294 \uac00\uaca9\uc5d0\ub3c4 \ubc18\uc601\ub41c\ub2e4. \uacf5\uc7a5\uc5d0\uc11c \ub9cc\ub4dc\ub294 \ub370 \ub4e0 \ub3c8\ub9cc \uc54c\uba74 \ud310\ub9e4 \uac00\uaca9\uc744 \ubaa8\ub450 \uc124\uba85\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2f1\uc5b4\uac00 \uacbd\uc7c1\ud558\ub358 \uc2dc\uc7a5\uc744 \ubcf4\uba74 \ubb3c\uac74\uacfc \ud568\uaed8 \uc0ac\uc6a9\ubc95\uacfc \uad6c\ub9e4\uc758 \uae30\ud68c\ub3c4 \uc804\ub2ec\ub418\uc5c8\ub2e4. \ud55c \ubc88\uc5d0 \ud070\ub3c8\uc744 \ub0b4\uae30 \uc5b4\ub824\uc6b4 \uac00\uc815\uc5d0 \ud560\ubd80\ub294 \uc911\uc694\ud55c \ud310\ub9e4 \ubc29\uc2dd\uc774\uc5c8\ub2e4. \ud544\uc694\ud55c \uae30\uacc4\ub97c \uba3c\uc800 \uc0ac\uc6a9\ud558\uace0 \ub300\uae08\uc744 \ub098\ub204\uc5b4 \ub0b4\ub294 \uad6c\uc870\ub2e4. \uae30\uacc4\uac00 \uc720\uc6a9\ud558\ub2e4\uace0 \uc0dd\uac01\ud558\ub294 \uc77c\uacfc \uc9c0\uae08 \ub2f9\uc7a5 \uc804\uc561\uc744 \ub9c8\ub828\ud560 \uc218 \uc788\ub294 \uc77c \uc0ac\uc774\uc758 \uac70\ub9ac\ub97c \uc904\uc5ec \uc8fc\uc5c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \ud560\ubd80\uac00 \uae30\uacc4\uc758 \uac00\uaca9\uc744 \uc5c6\uc560 \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc9c0\ubd88\uc744 \uc5ec\ub7ec \uc2dc\uc810\uc73c\ub85c \uc62e\uae34\ub2e4. \uae30\uc5c5\uc5d0\ub294 \uad6c\ub9e4 \uac00\ub2a5\ud55c \uace0\uac1d\uce35\uc744 \ub113\ud788\ub294 \ubc29\uc2dd\uc774\uc5c8\uace0 \uad6c\ub9e4\uc790\uc5d0\uac8c\ub294 \uc55e\uc73c\ub85c\uc758 \uc18c\ub4dd\uacfc \uc9c0\ucd9c\uc744 \ubb36\ub294 \uc57d\uc18d\uc774\uc5c8\ub2e4. \uc7ac\ubd09\ud2c0\uc758 \ubcf4\uae09\uc740 \uc0dd\uc0b0 \uae30\uc220\uc758 \uc5ed\uc0ac\uc774\uba74\uc11c \uac00\uc815\uc758 \uc608\uc0b0\uc774 \uc0c8\ub85c\uc6b4 \ubb3c\uac74\uc744 \ubc1b\uc544\ub4e4\uc774\ub294 \uc5ed\uc0ac\uc774\uae30\ub3c4 \ud558\ub2e4. \uc7ac\ubd09\ud2c0\uc740 \uac00\uc815\uc5d0\uc11c \uc637\uc744 \ub9cc\ub4e4\uace0 \uc190\uc9c8\ud558\ub294 \ub370 \uc4f0\uc600\uc9c0\ub9cc \uae30\uc131\ubcf5\uacfc \uc5ec\ub7ec \uc81c\ud488\uc744 \ub9cc\ub4dc\ub294 \uacf5\uc7a5\uc5d0\uc11c\ub3c4 \uc911\uc694\ud588\ub2e4. \uacf5\uc7a5\uc5d0\uc11c\ub294 \ub3d9\ub825\uc744 \uc5f0\uacb0\ud558\uace0 \ub354 \ube60\ub978 \uc791\uc5c5\uc744 \uc870\uc9c1\ud558\ub294 \ubc29\ud5a5\uc73c\ub85c \ubc1c\uc804\ud588\ub2e4. \uac19\uc740 \ubc14\ub290\uc9c8 \uc6d0\ub9ac\ub3c4 \uc5b4\ub5a4 \uc0dd\uc0b0 \uccb4\uacc4 \uc548\uc5d0 \ub193\uc774\ub294\uc9c0\uc5d0 \ub530\ub77c \uc4f0\uc784\uc774 \ub2ec\ub77c\uc84c\ub2e4. \ubc14\ub290\uc9c8\uc774 \ube68\ub77c\uc84c\ub2e4\uace0 \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \ub178\ub3d9\uc774 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc904\uc5b4\ub4e0 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc9d1\uc5d0\uc11c \ub9cc\ub4e4\ub358 \uc637\uc774 \uacf5\uc7a5\uc5d0\uc11c \ub9cc\ub4e4\uc5b4\uc9c0\uace0, \ub2e4\ub978 \uc885\ub958\uc758 \uc77c\uc774 \ub298\uae30\ub3c4 \ud588\ub2e4. \uc0c8\ub85c\uc6b4 \uae30\uacc4\ub97c \uc0dd\ud65c\uc758 \ud574\ubc29\uc790\ub85c\ub9cc \uc18c\uac1c\ud558\uae30\ubcf4\ub2e4 \uc77c\uc774 \uc5b4\ub514\ub85c \uc62e\uaca8 \uac00\uace0 \uc5b4\ub5bb\uac8c \uc870\uc9c1\ub418\uc5c8\ub294\uc9c0\uae4c\uc9c0 \ubcf4\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc2f1\uc5b4\ub77c\ub294 \uc774\ub984\uc740 \uc7ac\ubd09\ud2c0\uc758 \uc5ed\uc0ac \uc804\uccb4\uc640 \uac70\uc758 \uac19\uc740 \ub73b\uc73c\ub85c \ub290\uaef4\uc9c8 \ub9cc\ud07c \ub110\ub9ac \uc54c\ub824\uc84c\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \ub4a4\uc5d0\ub294 \uc5ec\ub7ec \ubc1c\uba85\uacfc \ud2b9\ud5c8\uc758 \ud611\uc0c1, \uc0dd\uc0b0\uacfc \uc601\uc5c5, \ub300\uae08\uc744 \ub098\ub204\uc5b4 \ubc1b\ub294 \uccb4\uacc4\uac00 \uc788\uc5c8\ub2e4. \uc0c1\ud45c \ud558\ub098\ub85c \uae30\uc5b5\ud558\ub294 \uc131\uacf5\uc744 \uc5ec\ub7ec \ub2e8\uacc4\ub85c \ud480\uc5b4 \ubcfc \uc218 \uc788\ub294 \uac83\uc774\ub2e4. \uc624\ub798\ub41c \uc7ac\ubd09\ud2c0\uc744 \ub2e4\uc2dc \ubcfc \ub54c\uc5d0\ub294 \ubc14\ub298\uc774 \uc6c0\uc9c1\uc774\ub294 \ubaa8\uc2b5 \uc606\uc5d0 \uadf8\uac83\uc744 \uc9d1\uc73c\ub85c \uac00\uc838\uc628 \uacfc\uc815\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc88b\uc740 \uae30\uacc4\ub97c \ub9cc\ub4dc\ub294 \uc77c\uacfc \ub9ce\uc740 \uc0ac\ub78c\uc774 \uc2e4\uc81c\ub85c \uc4f8 \uc218 \uc788\uac8c \ud558\ub294 \uc77c\uc740 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc2f1\uc5b4\uc758 \uc774\uc57c\uae30\ub294 \uae30\uc5c5\uc758 \uc5ed\uc0ac\ub97c \uc81c\ud488\uacfc \uc2dc\uc7a5, \uc0dd\ud65c\uc744 \ud568\uaed8 \uc77d\ub294 \ubc29\ubc95\uc744 \uc54c\ub824 \uc900\ub2e4."}, {"id": "sony-vinyl-records-return", "title": "\uc18c\ub2c8 \u2014 \ud3b8\ub9ac\ud55c \uc74c\uc545 \uc2dc\ub300\uc5d0 \ub808\ucf54\ub4dc\ub97c \ub2e4\uc2dc \ub9cc\ub4e4\uaca0\ub2e4\uace0 \ud55c \uc774\uc720", "summary": "2017\ub144 \uc18c\ub2c8\uc758 \ub808\ucf54\ub4dc \uc0dd\uc0b0 \uc7ac\uac1c \ubc1c\ud45c\ub97c \ucd9c\ubc1c\uc810\uc73c\ub85c \uc74c\uc545\uc744 \ub4e3\ub294 \ubc29\uc2dd\uacfc \uc81c\ud488 \uac00\uce58\uc758 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\ube0c\ub79c\ub4dc\uc640 \uc18c\ube44", "categories": ["industry"], "url": "stories/sony-vinyl-records-return/index.html", "image": "../media/sony-vinyl-records-return.png", "alt": "\ub808\ucf54\ub4dc \uac00\uac8c\uc5d0\uc11c \ud070 \ubc14\uc774\ub2d0 \uc74c\ubc18\uc744 \uc870\uc2ec\uc2a4\ub7fd\uac8c \ub4e4\uace0 \ud134\ud14c\uc774\ube14\uc5d0 \ub193\uc73c\ub824\ub294 AI \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\uc18c\ub2c8 \u2014 \ud3b8\ub9ac\ud55c \uc74c\uc545 \uc2dc\ub300\uc5d0 \ub808\ucf54\ub4dc\ub97c \ub2e4\uc2dc \ub9cc\ub4e4\uaca0\ub2e4\uace0 \ud55c \uc774\uc720 \ub0a1\uc740 \ub9e4\uccb4\uac00 \uc0c8\ub85c\uc6b4 \uc120\ud0dd\uc774 \ub420 \ub54c 2017\ub144 \uc18c\ub2c8\uc758 \ub808\ucf54\ub4dc \uc0dd\uc0b0 \uc7ac\uac1c \ubc1c\ud45c\ub97c \ucd9c\ubc1c\uc810\uc73c\ub85c \uc74c\uc545\uc744 \ub4e3\ub294 \ubc29\uc2dd\uacfc \uc81c\ud488 \uac00\uce58\uc758 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ube0c\ub79c\ub4dc\uc640 \uc18c\ube44 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \ub178\ub798\ub97c \ub4e3\uae30 \uc704\ud574 \ucee4\ub2e4\ub780 \uc6d0\ubc18\uc744 \uaebc\ub0b8\ub2e4. \ubaa8\uc11c\ub9ac\ub97c \uc870\uc2ec\ud574\uc11c \uc7a1\uace0 \ud134\ud14c\uc774\ube14 \uc704\uc5d0 \uc62c\ub9b0 \ub2e4\uc74c \ubc14\ub298\uc744 \ub0b4\ub9b0\ub2e4. \uc2a4\ub9c8\ud2b8\ud3f0\uc5d0\uc11c \uace1\uc744 \uace0\ub974\ub294 \uac83\uacfc \ube44\uad50\ud558\uba74 \uc190\uc774 \ub9ce\uc774 \uac04\ub2e4. \uadf8\ub7f0\ub370 \ubc14\ub85c \uadf8 \ubc88\uac70\ub85c\uc6b4 \uacfc\uc815 \ub54c\ubb38\uc5d0 \ub808\ucf54\ub4dc\ub97c \ucc3e\ub294 \uc0ac\ub78c\ub3c4 \uc788\ub2e4. \uc18c\ub2c8\ub294 2017\ub144 \ubc14\uc774\ub2d0 \ub808\ucf54\ub4dc \uc0dd\uc0b0\uc744 \ub2e4\uc2dc \uc2dc\uc791\ud558\uaca0\ub2e4\uace0 \ubc1c\ud45c\ud588\ub2e4. OpenStax\uc758 \uacbd\uc601\ud559 \uad50\uc7ac\ub294 1989\ub144 \uc774\ud6c4 \uc774\uc5b4\uc9c4 \uc0dd\uc0b0 \uacf5\ubc31\uacfc \uc774 \uc7ac\uac1c \ubc1c\ud45c\ub97c \uc624\ub798\ub41c \ub9e4\uccb4\uc758 \uadc0\ud658 \uc0ac\ub840\ub85c \uc18c\uac1c\ud55c\ub2e4. \ub354 \ud3b8\ub9ac\ud55c \uae30\uc220\uc774 \ub4f1\uc7a5\ud588\ub294\ub370\ub3c4 \uc608\uc804 \ubc29\uc2dd\uc774 \ub3cc\uc544\uc628 \uae4c\ub2ed\uc740 \ubb34\uc5c7\uc774\uc5c8\uc744\uae4c. \uc74c\uc545 \ub9e4\uccb4\uc758 \ubcc0\ud654\ub97c \ud55c \uc904\ub85c \uadf8\ub9ac\uba74 \ub808\ucf54\ub4dc\uc5d0\uc11c CD, \ub514\uc9c0\ud138 \ud30c\uc77c\uacfc \uc2a4\ud2b8\ub9ac\ubc0d\uc73c\ub85c \uc774\ub3d9\ud55c \uac83\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uc774 \ud750\ub984\ub9cc \ubcf4\uba74 \uc55e\uc120 \ubc29\uc2dd\uc740 \ub4a4\uc758 \ubc29\uc2dd\uc5d0 \uc790\ub9ac\ub97c \ub0b4\uc8fc\uace0 \uc0ac\ub77c\uc838\uc57c \ud560 \uac83 \uac19\ub2e4. \ud558\uc9c0\ub9cc \uc0ac\ub78c\ub4e4\uc758 \uc120\ud0dd\uc740 \ud56d\uc0c1 \uadf8\ub807\uac8c \ub2e8\uc21c\ud558\uac8c \uc815\ub9ac\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc0c8 \ubc29\uc2dd\uc774 \uc774\ub3d9\uacfc \uac80\uc0c9, \ubcf4\uad00\uc5d0\uc11c \ud3b8\ub9ac\ud574\uc838\ub3c4 \uae30\uc874 \ubb3c\uac74\uc5d0\uc11c \uc88b\uc544\ud558\ub358 \uacbd\ud5d8\uae4c\uc9c0 \ubaa8\ub450 \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\uc744 \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 \ubc14\uc774\ub2d0\uc758 \uc778\uae30\ub97c \uc124\uba85\ud558\uba70 \uc2e4\ubb3c \ub9e4\uccb4\ub97c \ub2e4\ub8e8\ub294 \uac10\uac01\uacfc \uc74c\uc545\uc744 \ub4e3\ub294 \uacbd\ud5d8\uc5d0 \uad00\uc2ec\uc744 \ub3cc\ub9b0\ub2e4. \ubb34\uc5c7\uc774 \ub354 \uc0c8\ub85c\uc6b4\uac00\uc640 \ubb34\uc5c7\uc744 \uc990\uae30\ub294\uac00\ub294 \uac19\uc740 \uc9c8\ubb38\uc774 \uc544\ub2c8\ub2e4. \ub808\ucf54\ub4dc\uc5d0\ub294 \uc18c\ub9ac\ub9cc \ub4e4\uc5b4 \uc788\uc9c0 \uc54a\ub2e4. \ucee4\ub2e4\ub780 \uc7ac\ud0b7\uc744 \ud3bc\uccd0 \uadf8\ub9bc\uacfc \uae00\uc744 \ubcf4\uace0, \uc190\uc5d0 \ub4e0 \ubb3c\uac74\uc744 \uc120\ubc18\uc5d0 \uaf42\ub294 \uacbd\ud5d8\uc774 \uc788\ub2e4. \uac19\uc740 \uace1\uc744 \ub4e4\uc5b4\ub3c4 \uc568\ubc94\uc744 \ud558\ub098\uc758 \ubb3c\uac74\uc73c\ub85c \ub9cc\ub098\uac8c \ub41c\ub2e4. \ud654\uba74\uc758 \uc791\uc740 \ud45c\uc9c0 \uadf8\ub9bc\uacfc\ub294 \ub2e4\ub978 \ud06c\uae30\uc640 \ucd09\uac10\uc774 \uc0dd\uae34\ub2e4. \ubb3c\ub860 \ubaa8\ub4e0 \uad6c\ub9e4\uc790\uac00 \uac19\uc740 \uc774\uc720\ub85c \ub808\ucf54\ub4dc\ub97c \uc88b\uc544\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uc0ac\ub78c\uc740 \uc18c\uc7a5\uc744 \uc990\uae30\uace0 \uc5b4\ub5a4 \uc0ac\ub78c\uc740 \ub4e3\ub294 \uc7a5\uce58\ub97c \ub9cc\uc9c0\ub294 \uacfc\uc815\uc744 \uc88b\uc544\ud560 \uc218 \uc788\ub2e4. \uae30\uc5c5\uc774 \uad00\ucc30\ud574\uc57c \ud558\ub294 \uac83\uc740 \uc61b \ub9e4\uccb4\uac00 \ubb34\uc870\uac74 \uc6b0\uc6d4\ud558\ub2e4\ub294 \uacb0\ub860\ubcf4\ub2e4, \uadf8 \ubb3c\uac74\uc744 \ud1b5\ud574 \uace0\uac1d\uc774 \uc5b4\ub5a4 \uc990\uac70\uc6c0\uc744 \uc5bb\uace0 \uc788\ub294\uc9c0\ub2e4. \uc74c\ubc18\uc744 \uaebc\ub0b4\uace0 \ud134\ud14c\uc774\ube14\uc744 \uc900\ube44\ud558\ub294 \uc2dc\uac04\uc740 \ud6a8\uc728\ub9cc \uc0dd\uac01\ud558\uba74 \uc904\uc5ec\uc57c \ud560 \uacfc\uc815\uc774\ub2e4. \uadf8\ub7ec\ub098 \ucde8\ubbf8\uc5d0\uc11c\ub294 \uc900\ube44 \uc790\uccb4\uac00 \uacbd\ud5d8\uc758 \uc77c\ubd80\uac00 \ub418\uae30\ub3c4 \ud55c\ub2e4. \ucc28\ub97c \uc6b0\ub9ac\ub294 \ub3c4\uad6c\ub97c \uace0\ub974\ub294 \uc77c\uc774\ub098 \ucc45\uc758 \uccab \uc7a5\uc744 \ud3bc\uce58\ub294 \uc77c\uc744 \ub5a0\uc62c\ub9ac\uba74 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \uc774\uac83\uc740 \ubb3c\uac74\uc744 \uc624\ub798 \uc900\ube44\ud560\uc218\ub85d \ubc18\ub4dc\uc2dc \ub354 \uae4a\uac8c \uac10\uc0c1\ud55c\ub2e4\ub294 \ub9d0\uc740 \uc544\ub2c8\ub2e4. \uc774\ub3d9 \uc911\uc5d0 \ud3b8\ud558\uac8c \ub4e3\ub294 \uc74c\uc545\uc5d0\ub3c4 \uc790\uae30\ub9cc\uc758 \uac00\uce58\uac00 \uc788\ub2e4. \ub2e4\ub9cc \uc5b4\ub5a4 \ub54c\uc5d0\ub294 \uc989\uc2dc \uc7ac\uc0dd\ud558\ub294 \ud3b8\ub9ac\ud568\ubcf4\ub2e4 \uc74c\uc545\uc744 \ub4e3\uae30\ub85c \ub9c8\uc74c\uba39\ub294 \uc808\ucc28\uac00 \uc18c\uc911\ud574\uc9c8 \uc218 \uc788\ub2e4. \uac19\uc740 \uc0ac\ub78c\ub3c4 \uc0c1\ud669\uc5d0 \ub530\ub77c \ub2e4\ub978 \ubc29\uc2dd\uc744 \uace0\ub978\ub2e4. \uad50\uc7ac\uac00 \uc18c\uac1c\ud558\ub294 \uc18c\ub2c8\uc758 2017\ub144 \ubc1c\ud45c\ub294 \uc774\ub7f0 \uc18c\ube44 \ubcc0\ud654\uc5d0 \uae30\uc5c5\uc774 \ubc18\uc751\ud55c \uc0ac\ub840\ub2e4. \uc774\uc804\uc5d0 \uba48\ucd94\uc5c8\ub358 \uc81c\ud488\uc744 \ub2e4\uc2dc \uc0dd\uc0b0\ud558\ub824\uba74 \uc218\uc694\uac00 \uc788\ub294\uc9c0 \uc0b4\ud53c\uace0 \uc0dd\uc0b0 \ub2a5\ub825\uc744 \uc900\ube44\ud574\uc57c \ud55c\ub2e4. \uace0\uac1d\uc758 \uad00\uc2ec\uc744 \uc2e4\uc81c \ubb3c\uac74\uc73c\ub85c \ubc14\uafb8\ub294 \ub2e8\uacc4\uac00 \ub530\ub85c \uc788\ub294 \uac83\uc774\ub2e4. \uc624\ub798\ub41c \ud615\uc2dd\uc774\ub77c\uace0 \ub2e4\uc2dc \ub9cc\ub4dc\ub294 \uc77c\uc774 \uc800\uc808\ub85c \uc26c\uc6cc\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc81c\uc870 \uae30\uc220\uacfc \uc124\ube44, \ud568\uaed8 \uc77c\ud560 \uc0ac\ub78c\uacfc \uacf5\uae09 \uacfc\uc815\uc774 \ud544\uc694\ud558\ub2e4. \uc5ec\uae30\uc11c \ud655\uc778\ud55c \uac83\uc740 \uc0dd\uc0b0 \uc7ac\uac1c\ub97c \uc54c\ub9b0 \ub2f9\uc2dc\uc758 \ubc1c\ud45c\ub2e4. \uc774 \uae00\uc5d0\uc11c \ud2b9\uc815 \uacf5\uc7a5\uc758 \ud604\uc7ac \uac00\ub3d9 \uc0c1\ud669\uc774\ub098 \ucd5c\uc2e0 \ud310\ub9e4\ub7c9\uae4c\uc9c0 \ud655\uc778\ud55c \uac83\uc73c\ub85c \ub113\ud600 \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub808\ucf54\ub4dc\uc758 \uc778\uae30\ub97c \uacfc\uac70\uc5d0 \ub300\ud55c \ud5a5\uc218 \ud558\ub098\ub85c\ub9cc \uc124\uba85\ud558\uba74 \uc80a\uc740 \uad6c\ub9e4\uc790\ub97c \uc774\ud574\ud558\uae30 \uc5b4\ub835\ub2e4. \uc790\uc2e0\uc774 \uacbd\ud5d8\ud558\uc9c0 \ubabb\ud55c \ubc29\uc2dd\uc774\uc5b4\uc11c \uc624\ud788\ub824 \uc0c8\ub86d\uac8c \ub290\ub084 \uc218\ub3c4 \uc788\ub2e4. \uc190\uc73c\ub85c \ub2e4\ub8e8\ub294 \ub9e4\uccb4\ub97c \ucc98\uc74c \ub9cc\ub098\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc624\ub798\ub41c \ubb3c\uac74\uacfc \uc0c8\ub85c\uc6b4 \uacbd\ud5d8\uc774 \uac19\uc740 \ub300\uc0c1\uc774\ub2e4. \uad50\uc7ac\ub3c4 \ub514\uc9c0\ud138 \ud658\uacbd\uc5d0 \uc775\uc219\ud55c \uc138\ub300\uac00 \uc2e4\ubb3c \uc74c\ubc18\uc744 \ucc3e\ub294 \ud604\uc0c1\uc5d0 \uc8fc\ubaa9\ud55c\ub2e4. \uc5b4\ub5a4 \ub9e4\uccb4\ub97c \uc0ac\uc6a9\ud55c \uc2dc\uc808\uc758 \uae30\uc5b5\uacfc \uadf8 \ub9e4\uccb4\ub97c \uc9c0\uae08 \uc120\ud0dd\ud558\ub294 \uc774\uc720\ub294 \uc77c\uce58\ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uae30\uc5c5 \uc785\uc7a5\uc5d0\uc11c\ub294 \uae30\uc874 \uace0\uac1d\uc774 \ub3cc\uc544\uc624\ub294 \uc2dc\uc7a5\uacfc \uc0c8 \uace0\uac1d\uc774 \ucc98\uc74c \ub4e4\uc5b4\uc624\ub294 \uc2dc\uc7a5\uc744 \ud568\uaed8 \uc0b4\ud3b4\uc57c \ud558\ub294 \uc148\uc774\ub2e4. \ub808\ucf54\ub4dc\ub97c \ub450\uace0\ub294 \ub530\ub73b\ud55c \uc18c\ub9ac\ub77c\ub294 \ud45c\ud604\uc774 \uc790\uc8fc \ub4f1\uc7a5\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uadf8\ub7f0 \uac10\uc0c1\uc744 \ubaa8\ub4e0 \uc7a5\uce58\uc640 \uc74c\uc6d0\uc5d0 \ub300\ud55c \uac1d\uad00\uc801\uc778 \uc6b0\uc5f4 \ud310\uc815\uc73c\ub85c \ubc14\uafc0 \uc218\ub294 \uc5c6\ub2e4. \ub179\uc74c\uacfc \uc81c\uc791, \uc7ac\uc0dd \uae30\uae30\uc640 \uc74c\ubc18 \uc0c1\ud0dc\uc5d0 \ub530\ub77c \uc2e4\uc81c\ub85c \ub4e3\ub294 \uacb0\uacfc\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uc774 \uc774\uc57c\uae30\ub294 \ub808\ucf54\ub4dc\uac00 \uc5b8\uc81c\ub098 \ub354 \uc815\ud655\ud55c \uc18c\ub9ac\ub97c \ub0b8\ub2e4\ub294 \uc8fc\uc7a5\uc774 \uc544\ub2c8\ub2e4. \uc18c\ub9ac\ub97c \ud3ec\ud568\ud574 \ud45c\uc9c0\uc640 \uc18c\uc7a5, \uc900\ube44\ud558\ub294 \ub3d9\uc791\uae4c\uc9c0 \ud55c\ub370 \ubb36\uc778 \uacbd\ud5d8\uc774 \ub2e4\uc2dc \uc120\ud0dd\ub420 \uc218 \uc788\ub2e4\ub294 \uc124\uba85\uc774\ub2e4. \uae30\uc220\uc758 \uc131\ub2a5\uacfc \uc81c\ud488\uc774 \uc8fc\ub294 \uc990\uac70\uc6c0\uc744 \uad6c\ubd84\ud558\uba74 \uc88b\uc544\ud558\ub294 \ucde8\ud5a5\uc744 \uacfc\uc7a5\ub41c \uacfc\ud559 \uc124\uba85\uc73c\ub85c \ubc29\uc5b4\ud560 \ud544\uc694\ub3c4 \uc904\uc5b4\ub4e0\ub2e4. \uc5b4\ub5a4 \ub0a1\uc740 \uc81c\ud488\uc774\ub4e0 \ub2e4\uc2dc \ub9cc\ub4e4\uae30\ub9cc \ud558\uba74 \uc131\uacf5\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2e4\uc81c\ub85c \uc6d0\ud558\ub294 \uc0ac\ub78c\uc774 \uc788\uc5b4\uc57c \ud558\uace0, \uadf8 \uc0ac\ub78c\uc5d0\uac8c \uac00\uaca9\uacfc \ud488\uc9c8, \uad6c\ud560 \uc218 \uc788\ub294 \ubb3c\ub7c9\uc774 \ub9de\uc544\uc57c \ud55c\ub2e4. \ub808\ucf54\ub4dc\uc758 \uadc0\ud658\uc740 \ubaa8\ub4e0 \ubcf5\uace0 \uc0c1\ud488\uc5d0 \ud1b5\ud558\ub294 \ub9c8\ubc95\uc758 \uacf5\uc2dd\uc774 \uc544\ub2c8\ub2e4. \ub300\uc2e0 \uc81c\ud488\uc758 \uac00\uce58\ub294 \uae30\ub2a5 \ubaa9\ub85d\ub9cc\uc73c\ub85c \ub2e4 \uc124\uba85\ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc74c\uc545\uc744 \ub4e4\uc744 \uc218 \uc788\ub2e4\ub294 \uae30\ubcf8 \uae30\ub2a5\uc774 \uac19\uc544\ub3c4, \uace0\uac1d\uc774 \uace0\ub974\ub294 \uac83\uc740 \uc11c\ub85c \ub2e4\ub978 \uc804\uccb4 \uacbd\ud5d8\uc77c \uc218 \uc788\ub2e4. \uae30\uc5c5\uc774 \uae30\uc220\uc758 \uc21c\uc11c\ub9cc \ubcf4\uace0 \uace0\uac1d\uc758 \ucde8\ud5a5\uc744 \ub300\uc2e0 \uacb0\uc815\ud560 \uc218 \uc5c6\ub294 \uc774\uc720\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \ub808\ucf54\ub4dc\ub97c \uace0\ub974\uace0 \ub2e4\ub8e8\ub294 \uc7a5\uba74\uc744 \ud45c\ud604\ud55c AI \uc0bd\ud654\ub2e4. \ud2b9\uc815 \uc18c\ub2c8 \uc81c\ud488\uc774\ub098 \uc2e4\uc81c \uc0dd\uc0b0 \ud604\uc7a5\uc744 \uc7ac\ud604\ud558\uc9c0 \uc54a\uc558\ub2e4. \uae30\uae30 \uc774\ub984\ubcf4\ub2e4 \uc74c\ubc18\uc744 \uc7a1\uc740 \uc190, \ucee4\ub2e4\ub780 \ud45c\uc9c0, \ub4e3\uae30 \uc804\uc5d0 \ube44\uc6cc \ub454 \uc7a0\uae50\uc758 \uc2dc\uac04\uc744 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc18c\ub2c8\uc758 \uc7ac\uac1c \ubc1c\ud45c\uac00 \ud765\ubbf8\ub85c\uc6b4 \uae4c\ub2ed\uc740 \uc138\uc0c1\uc774 \uacfc\uac70\ub85c \ub3cc\uc544\uac14\uae30 \ub54c\ubb38\uc774 \uc544\ub2c8\ub2e4. \ud3b8\ub9ac\ud55c \ubc29\uc2dd\uc774 \ub110\ub9ac \uc4f0\uc774\ub294 \uac00\uc6b4\ub370 \ub2e4\ub978 \ubc29\uc2dd\uc758 \uc990\uac70\uc6c0\ub3c4 \uc0b4\uc544\ub0a8\uc558\uae30 \ub54c\ubb38\uc774\ub2e4. \uc624\ub798\ub41c \ub9e4\uccb4\ub294 \ub54c\ub85c \uae30\uc220 \uacbd\uc7c1\uc758 \ud328\uc790\uac00 \uc544\ub2c8\ub77c, \uc74c\uc545\uc744 \uc870\uae08 \ub2e4\ub974\uac8c \ub9cc\ub098\ub824\ub294 \uc0ac\ub78c\uc758 \uc0c8\ub85c\uc6b4 \uc120\ud0dd\uc774 \ub41c\ub2e4."}, {"id": "standard-oil-octopus-and-competition", "title": "\uc2a4\ud0e0\ub354\ub4dc\uc624\uc77c \u2014 \uc11d\uc720 \ud68c\uc0ac\ub294 \uc65c \ubb38\uc5b4\ub85c \uadf8\ub824\uc84c\uc744\uae4c", "summary": "\uc815\uc720 \uc0ac\uc5c5\uc758 \ud1b5\ud569\uacfc \ucca0\ub3c4 \uc6b4\uc784, \ub3c5\uc810 \ube44\ud310\uc744 \ub2f9\ub300 \ud48d\uc790\ud654\uc640 \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\uacbd\uc601\uacfc \uc870\uc9c1", "categories": ["industry"], "url": "stories/standard-oil-octopus-and-competition/index.html", "image": "../media/standard-oil-octopus-and-competition.jpg", "alt": "\uc2a4\ud0e0\ub354\ub4dc\uc624\uc77c\uc744 \uc5ec\ub7ec \ubc29\ud5a5\uc73c\ub85c \ub2e4\ub9ac\ub97c \ubed7\ub294 \ubb38\uc5b4\ub85c \uadf8\ub9b0 \ub2f9\ub300 \ud48d\uc790\ud654", "text": "\uc2a4\ud0e0\ub354\ub4dc\uc624\uc77c \u2014 \uc11d\uc720 \ud68c\uc0ac\ub294 \uc65c \ubb38\uc5b4\ub85c \uadf8\ub824\uc84c\uc744\uae4c \ud55c \uae30\uc5c5\uc758 \uc131\uc7a5\uc774 \uacbd\uc7c1\uc758 \uaddc\uce59\uc744 \ubb3b\ub294 \uc77c\uc774 \ub418\uae30\uae4c\uc9c0 \uc815\uc720 \uc0ac\uc5c5\uc758 \ud1b5\ud569\uacfc \ucca0\ub3c4 \uc6b4\uc784, \ub3c5\uc810 \ube44\ud310\uc744 \ub2f9\ub300 \ud48d\uc790\ud654\uc640 \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4. \uacbd\uc601\uacfc \uc870\uc9c1 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \ud68c\uc0ac \uc774\ub984\uc744 \ub2e8 \ubb38\uc5b4\uac00 \uc5ec\ub7ec \uacf3\uc73c\ub85c \ub2e4\ub9ac\ub97c \ubed7\ub294\ub2e4. \uacf5\uc7a5\uacfc \uac70\ub798\uc758 \uc138\uacc4\ub97c \ub118\uc5b4 \uad8c\ub825\uc758 \uacf5\uac04\uae4c\uc9c0 \uac10\uc2f8\ub824\ub294 \ub4ef\ud558\ub2e4. \uc2a4\ud0e0\ub354\ub4dc\uc624\uc77c\uc744 \ube44\ud310\ud55c \uc61b \ud48d\uc790\ud654\uc5d0\uc11c \uc11d\uc720\ud1b5\uc774 \ubb38\uc5b4\uc758 \ubab8\uc774 \ub41c \uc774\uc720\ub294 \uadc0\uc5ec\uc6b4 \ub3d9\ubb3c \ub9c8\uc2a4\ucf54\ud2b8\uac00 \ud544\uc694\ud574\uc11c\uac00 \uc544\ub2c8\uc5c8\ub2e4. \uae30\uc5c5\uc774 \ucee4\uc9c0\ub294 \uac83\uc740 \uc5b8\uc81c\ubd80\ud130 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc120\ud0dd\uc744 \uc881\ud788\ub294 \ubb38\uc81c\uac00 \ub420\uae4c. \uc874 D. \ub85d\ud3a0\ub7ec\uc758 \uc815\uc720 \uc0ac\uc5c5\uc744 \ub530\ub77c\uac00\uba74 \uc0dd\uc0b0\uc744 \ud6a8\uc728\uc801\uc73c\ub85c \ub9cc\ub4dc\ub294 \ub2a5\ub825\uacfc \uacbd\uc7c1\uc744 \uc81c\ud55c\ud558\ub294 \ud798\uc774 \uc5b4\ub5bb\uac8c \uc5bd\ud790 \uc218 \uc788\ub294\uc9c0 \ubcf4\uc778\ub2e4. \ud48d\uc790\ud654\uc758 \ub2e4\ub9ac\ub9c8\ub2e4 \uadf8 \uc2dc\ub300\uc758 \uac71\uc815\uc774 \ub9e4\ub2ec\ub824 \uc788\ub2e4. \uc11d\uc720 \uc0b0\uc5c5\uc774\ub77c\uace0 \ud558\uba74 \ub545\uc5d0\uc11c \uae30\ub984\uc744 \ub04c\uc5b4\uc62c\ub9ac\ub294 \uc7a5\uba74\ubd80\ud130 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uc6d0\uc720\ub97c \uc5bb\ub294 \uac83\uacfc \uc2e4\uc81c\ub85c \uc0ac\uc6a9\ud560 \uc81c\ud488\uc744 \ub9cc\ub4e4\uc5b4 \ud310\ub9e4\ud558\ub294 \uac83\uc740 \uc11c\ub85c \ub2e4\ub978 \ub2e8\uacc4\ub2e4. \ub85d\ud3a0\ub7ec\uac00 \ud0a4\uc6b4 \uc0ac\uc5c5\uc5d0\uc11c\ub294 \uc815\uc720\uac00 \uc911\uc694\ud55c \uc704\uce58\ub97c \ucc28\uc9c0\ud588\ub2e4. \uc0dd\uc0b0\uacfc \uacf5\uae09\uc758 \ud750\ub984 \uc911 \uc5b4\ub290 \uacf3\uc744 \ubd99\uc7a1\uc744\uc9c0\ub3c4 \uae30\uc5c5\uc758 \uc120\ud0dd\uc774\uc5c8\ub2e4. \ubbf8\uad6d\uc5d0\uc11c \uc11d\uc720 \uc0ac\uc5c5\uc774 \ud33d\ucc3d\ud558\ub358 \ub54c\uc5d0\ub294 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uae30\ud68c\ub97c \ucc3e\uc544\ub4e4\uc5c8\ub2e4. \uc0c8\ub85c\uc6b4 \uc218\uc694\uac00 \uc788\ub2e4\ub294 \uac83\uc740 \uc218\uc775\uc758 \uac00\ub2a5\uc131\uc774\uba74\uc11c \uacbd\uc7c1\uacfc \uac00\uaca9 \ubcc0\ub3d9\uc774 \uc788\ub2e4\ub294 \ub73b\uc774\uae30\ub3c4 \ud588\ub2e4. \uacbd\uc7c1\uc790\uac00 \ub9ce\ub2e4\ub294 \uc870\uac74\uc744 \uc5b4\ub5bb\uac8c \ubc14\uafb8\ub290\ub0d0\uac00 \ub85d\ud3a0\ub7ec\uc758 \uc131\uc7a5 \uc804\ub7b5\uc5d0\uc11c \uc810\uc810 \uc911\uc694\ud574\uc84c\ub2e4. 1870\ub144\uc5d0 \ucd9c\ubc94\ud55c \uc2a4\ud0e0\ub354\ub4dc\uc624\uc77c\uc740 \uc815\uc720 \uc0ac\uc5c5\ub4e4\uc744 \uacb0\ud569\ud558\uba70 \uc601\ud5a5\ub825\uc744 \ub113\ud614\ub2e4. \uac19\uc740 \ub2e8\uacc4\uc5d0\uc11c \uacbd\uc7c1\ud558\ub358 \uae30\uc5c5\uc744 \ubb36\ub294 \ubc29\uc2dd\uc744 \uc218\ud3c9 \ud1b5\ud569\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \uc6d0\ub8cc\uc5d0\uc11c \uc644\uc81c\ud488\uae4c\uc9c0 \uc5ec\ub7ec \ub2e8\uacc4\ub97c \uc787\ub294 \uc218\uc9c1 \ud1b5\ud569\uacfc\ub294 \ucd08\uc810\uc774 \ub2e4\ub974\ub2e4. \uacbd\uc7c1\ud558\ub358 \uc790\ub9ac\ub97c \ud558\ub098\uc758 \uc870\uc9c1 \uc548\uc73c\ub85c \uac00\uc838\uc624\ub294 \uac83\uc774\ub2e4. \ubaa8\ub4e0 \uacb0\ud569\uc774 \uace7\ubc14\ub85c \ubd88\ubc95\uc778 \uac83\uc740 \uc544\ub2c8\ub2e4. \uaddc\ubaa8\ub97c \ud0a4\uc6b0\uba74 \uc2dc\uc124\uacfc \uc6b4\uc1a1, \ud310\ub9e4\ub97c \ub354 \ud6a8\uc728\uc801\uc73c\ub85c \uc6b4\uc601\ud560 \uc218\ub3c4 \uc788\ub2e4. \ubb38\uc81c\ub294 \uadf8 \ud798\uc774 \uc2dc\uc7a5\uc758 \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uc5b4\ub5a4 \uc870\uac74\uc744 \uac15\uc694\ud560 \uc218 \uc788\uac8c \ub418\ub294\uc9c0\ub2e4. \uacbd\uc7c1\uc790\uac00 \uc120\ud0dd\ud560 \uc218 \uc788\ub294 \uae38\uc774 \uc904\uc5b4\ub4e4 \ub54c \ub2e8\uc21c\ud55c \uaddc\ubaa8\uc758 \ubb38\uc81c\uac00 \uaddc\uce59\uc758 \ubb38\uc81c\ub85c \ub118\uc5b4\uac04\ub2e4. \uc815\uc720\uc18c\uc5d0\uc11c \ub9cc\ub4e0 \uc81c\ud488\uc740 \uc18c\ube44\uc790\uc5d0\uac8c \uc774\ub3d9\ud574\uc57c \ud55c\ub2e4. \uadf8\ub798\uc11c \ucca0\ub3c4 \ud68c\uc0ac\uc640 \uc5b4\ub5a4 \uc870\uac74\uc73c\ub85c \uac70\ub798\ud558\ub294\uc9c0\ub3c4 \uc911\uc694\ud588\ub2e4. OpenStax\ub294 \uc2a4\ud0e0\ub354\ub4dc\uc624\uc77c\uc774 \uc720\ub9ac\ud55c \uc6b4\uc784 \uc870\uac74\uc744 \ud655\ubcf4\ud558\uace0 \uadf8\uac83\uc744 \uacbd\uc7c1\uc5d0\uc11c \ud65c\uc6a9\ud55c \uacfc\uc815\uc744 \uc124\uba85\ud55c\ub2e4. \uacf5\uc7a5 \uc548\uc758 \uae30\uc220\ub9cc\uc73c\ub85c \uc0ac\uc5c5\uc758 \uc2b9\ud328\uac00 \uc815\ud574\uc9c4 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc6b4\uc1a1\ub7c9\uc774 \ub9ce\uc740 \uace0\uac1d\uc774 \ud560\uc778\uc744 \ubc1b\ub294 \uc77c \uc790\uccb4\ub294 \ub0af\uc124\uc9c0 \uc54a\ub2e4. \uadf8\ub7ec\ub098 \uc720\ub9ac\ud55c \uac70\ub798 \uc870\uac74\uacfc \uacbd\uc7c1\uc790\ub97c \ubc30\uc81c\ud558\ub294 \uac70\ub798\ub294 \uac19\uc740 \ud3c9\uac00\ub97c \ubc1b\uc9c0 \uc54a\ub294\ub2e4. \ubb34\uc5c7\uc774 \ud6a8\uc728\uc5d0 \ub300\ud55c \ubcf4\uc0c1\uc774\uace0 \ubb34\uc5c7\uc774 \ud0c0\uc778\uc758 \uc9c4\uc785\uc744 \uc5b4\ub835\uac8c \ud558\ub294 \uc7a5\uce58\uc778\uc9c0 \ub530\uc838\uc57c \ud55c\ub2e4. \ucca0\ub85c \uc704\uc758 \uac00\uaca9\ud45c\uc5d0\ub3c4 \uc2dc\uc7a5\uc758 \uad8c\ub825\uad00\uacc4\uac00 \ub2f4\uae38 \uc218 \uc788\uc5c8\ub2e4. \uac89\uc73c\ub85c\ub294 \ubc95\uc778\uc774 \ub098\ub258\uc5b4 \uc788\uc5b4\ub3c4 \uc9c0\ubc30\uc640 \uc758\uc0ac \uacb0\uc815\uc774 \uc5f0\uacb0\ub418\uc5b4 \uc788\ub2e4\uba74 \uacbd\uc7c1\uc758 \ubaa8\uc2b5\uc740 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ub2f9\uc2dc\uc758 \ud2b8\ub7ec\uc2a4\ud2b8\ub77c\ub294 \uc870\uc9c1 \ubc29\uc2dd\uc740 \uc774\ub7f0 \uae30\uc5c5 \ud1b5\ud569\uc744 \uc774\ud574\ud558\ub294 \uc911\uc694\ud55c \ub2e8\uc5b4\uac00 \ub418\uc5c8\ub2e4. \uc77c\ubc18 \ub3c5\uc790\ub294 \ubcf5\uc7a1\ud55c \ubc95\uc801 \uad6c\uc870\ub97c \ubaa8\ub450 \uc678\uc6b0\uae30\ubcf4\ub2e4 \ub204\uac00 \uc2e4\uc81c\ub85c \ubc29\ud5a5\uc744 \uacb0\uc815\ud558\ub294\uc9c0 \ubb3c\uc5b4\ubcf4\uba74 \ub41c\ub2e4. \uc0c1\ud45c\ub098 \uac04\ud310\uc758 \uc218\uac00 \uc18c\ube44\uc790\uc758 \uc120\ud0dd\uc9c0\ub97c \uadf8\ub300\ub85c \uc54c\ub824 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4\ub294 \ub73b\uc774\ub2e4. \uc5ec\ub7ec \ud310\ub9e4\uc790\uac00 \uc788\uc5b4 \ubcf4\uc774\ub294 \uac83\uacfc \uc11c\ub85c \ub3c5\ub9bd\uc801\uc73c\ub85c \uac00\uaca9\uacfc \uacf5\uae09\uc744 \uc815\ud558\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uc2a4\ud0e0\ub354\ub4dc\uc624\uc77c\uc744 \ub458\ub7ec\uc2fc \ub17c\uc7c1\uc740 \ud070 \uae30\uc5c5\uc758 \uc874\uc7ac\ub9cc\uc774 \uc544\ub2c8\ub77c \uae30\uc5c5\ub4e4 \uc0ac\uc774\uc758 \uad00\uacc4\ub97c \uc0b4\ud3b4\uc57c \ud55c\ub2e4\ub294 \ubb38\uc81c\ub97c \ub4dc\ub7ec\ub0c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 \ud48d\uc790\ud654\ub294 \ud68c\uc0ac\uac00 \uc2a4\uc2a4\ub85c \ub0b4\ub193\uc740 \uc124\uba85\uc774 \uc544\ub2c8\ub2e4. \uae30\uc5c5 \uad8c\ub825\uc774 \ub108\ubb34 \ub113\uc5b4\uc84c\ub2e4\uace0 \ubcf8 \ube44\ud310\uc790\uc758 \uadf8\ub9bc\uc774\ub2e4. \ud55c\ub208\uc5d0 \uc54c\uc544\ubcfc \uc218 \uc788\ub294 \ub3d9\ubb3c\uacfc \uacfc\uc7a5\ub41c \uc7a5\uba74\uc744 \uc774\uc6a9\ud574 \ubcf5\uc7a1\ud55c \uacbd\uc81c \ubb38\uc81c\ub97c \ub3c5\uc790\uc758 \uac10\uc815 \uac00\uae4c\uc774 \uac00\uc838\uc654\ub2e4. \uadf8\ub9bc\uc740 \uc124\uba85\uc778 \ub3d9\uc2dc\uc5d0 \uc124\ub4dd\uc774\uc5c8\ub2e4. \uadf8\ub798\uc11c \ub2e4\ub9ac\uac00 \ub2ff\ub294 \ubaa8\ub4e0 \uc7a5\uba74\uc744 \uadf8 \uc790\uccb4\ub85c \uc785\uc99d\ub41c \ubd80\ud328 \uc0ac\uac74\uc774\ub77c\uace0 \uc77d\uc744 \uc218\ub294 \uc5c6\ub2e4. \uc0ac\uc2e4 \ud655\uc778\uc5d0 \ud544\uc694\ud55c \uc790\ub8cc\uc640 \ud48d\uc790\uc758 \ud45c\ud604 \ubc29\uc2dd\uc740 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uadf8\ub9bc\uc758 \uc5ed\uc0ac\uc801 \uac00\uce58\uac00 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc774 \ubb34\uc5c7\uc744 \ub450\ub824\uc6cc\ud588\uace0 \uc5b4\ub5a4 \uc5b8\uc5b4\ub85c \ube44\ud310\ud588\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\uae30 \ub54c\ubb38\uc774\ub2e4. \uac70\ub300\ud55c \uae30\uc5c5\uc758 \ud798\uc744 \uc5b4\ub514\uae4c\uc9c0 \ud5c8\uc6a9\ud560\uc9c0 \ub450\uace0 \uc815\ubd80\uc758 \uc5ed\ud560\uc774 \ub17c\uc7c1\uac70\ub9ac\uac00 \ub418\uc5c8\ub2e4. \ubc18\ub3c5\uc810 \uc815\ucc45\uc740 \ubaa8\ub4e0 \ud070 \ud68c\uc0ac\ub97c \ubb34\uc870\uac74 \uc5c6\uc560\uc790\ub294 \ub9d0\uacfc \uac19\uc9c0 \uc54a\uc558\ub2e4. \uaddc\ubaa8\uac00 \uc8fc\ub294 \uc774\uc775\uacfc \uc2dc\uc7a5 \uc9c0\ubc30\uac00 \uc8fc\ub294 \ud53c\ud574\ub97c \uad6c\ubd84\ud558\uace0, \ubc95\uc73c\ub85c \uc5b4\ub5a4 \ud589\uc704\ub97c \uc81c\ud55c\ud560\uc9c0 \uc815\ud574\uc57c \ud588\ub2e4. \uc774 \uacfc\uc815\uc740 \uae30\uc5c5\uac00\uac00 \uc6d0\ud558\uba74 \uc5b8\uc81c\ub4e0 \uacbd\uc7c1\uc758 \uaddc\uce59\uc744 \uc815\ud560 \uc218 \uc788\ub294\uc9c0 \ubb3b\ub294 \uc77c\uc774\uae30\ub3c4 \ud588\ub2e4. \uacf5\uae09\uc774 \uc2f8\uc9c0\uace0 \ud3b8\ub9ac\ud574\uc84c\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc218\ub2e8\uc774 \uc815\ub2f9\ud574\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubc18\ub300\ub85c \uae30\uc5c5\uc758 \ud06c\uae30 \ud558\ub098\ub9cc \ubcf4\uace0 \ubaa8\ub4e0 \uac70\ub798\ub97c \ub611\uac19\uc774 \ud310\ub2e8\ud560 \uc218\ub3c4 \uc5c6\ub2e4. \ub17c\uc7c1\uc774 \uae38\uc5b4\uc9c4 \uc774\uc720\ub3c4 \uadf8 \uc0ac\uc774\uc5d0 \uc788\uc5c8\ub2e4. \uc624\ub298\uc758 \ub3c5\uc790\ub294 \ubb38\uc5b4\uc758 \ub2e4\ub9ac\uac00 \uc870\uae08 \uc6b0\uc2a4\uaf5d\uc2a4\ub7fd\uac8c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uadf8\ub9bc\uc774 \ubd99\uc7a1\uc740 \uc9c8\ubb38\uc740 \ub2e8\uc21c\ud558\uc9c0 \uc54a\ub2e4. \ub0b4\uac00 \uc0b4 \ubb3c\uac74\uc758 \uac00\uaca9\uc774 \ub0ae\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc55e\uc73c\ub85c\ub3c4 \ub2e4\ub978 \ud310\ub9e4\uc790\ub97c \uace0\ub97c \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc11c\ub85c \ub2e4\ub978 \ubb38\uc81c\ub2e4. \ud604\uc7ac\uc758 \ud61c\ud0dd\ub9cc\uc73c\ub85c \uacbd\uc7c1\uc758 \uc870\uac74\uc744 \ubaa8\ub450 \uc54c \uc218\ub294 \uc5c6\ub2e4. \uc2a4\ud0e0\ub354\ub4dc\uc624\uc77c\uc758 \uc5ed\uc0ac\ub294 \uc131\uacf5\uc758 \uaddc\ubaa8\ub97c \uc22b\uc790\ub85c \uc678\uc6b0\ub294 \ub370\uc11c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uae30\uc5c5\uc758 \ud798\uc774 \uc5b4\ub514\uc11c \uc0dd\uacbc\uace0 \uadf8 \ud798\uc744 \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud588\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uac8c \ud55c\ub2e4. \uc624\ub798\ub41c \ud48d\uc790\ud654 \uc55e\uc5d0\uc11c \ub2e4\ub9ac\uc758 \uac1c\uc218\ubcf4\ub2e4 \ubed7\ub294 \ubc29\ud5a5\uc744 \ubcf4\uc790. \uadf8 \ubc29\ud5a5\uc5d0 \ud55c \uc2dc\ub300\uc758 \uacbd\uc81c\uc801 \ubd88\uc548\uc774 \ub0a8\uc544 \uc788\ub2e4."}, {"id": "tass-stencil-posters", "title": "\ud3ec\uc2a4\ud130\ub97c \ud55c \uc7a5\uc529 \ubd93\uc73c\ub85c \uce60\ud558\ub358 \uc791\uc5c5\uc7a5", "summary": "\uc804\uc7c1\uae30 \uc18c\ub828\uc758 \ud0c0\uc2a4 \ud3ec\uc2a4\ud130\uac00 \uc5ec\ub7ec \uc7a5\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc9c0\ub358 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\ube0c\ub79c\ub4dc\uc640 \uc18c\ube44", "categories": ["industry"], "url": "stories/tass-stencil-posters/index.html", "image": "../media/tass-stencil-posters.jpg", "alt": "\ud3ec\uc2a4\ud130\ub97c \ud55c \uc7a5\uc529 \ubd93\uc73c\ub85c \uce60\ud558\ub358 \uc791\uc5c5\uc7a5\uc758 \ub0b4\uc6a9\uc744 \ub3d5\ub294 \uc124\uba85\uc6a9 \uc774\ubbf8\uc9c0", "text": "\ud3ec\uc2a4\ud130\ub97c \ud55c \uc7a5\uc529 \ubd93\uc73c\ub85c \uce60\ud558\ub358 \uc791\uc5c5\uc7a5 \ubaa8\uc2a4\ud06c\ubc14\uc758 \ubcbd\uae4c\uc9c0 \uc774\uc5b4\uc9c4 \uc885\uc774\uc640 \ud2c0 \uc804\uc7c1\uae30 \uc18c\ub828\uc758 \ud0c0\uc2a4 \ud3ec\uc2a4\ud130\uac00 \uc5ec\ub7ec \uc7a5\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc9c0\ub358 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ube0c\ub79c\ub4dc\uc640 \uc18c\ube44 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \uac19\uc740 \ud3ec\uc2a4\ud130\ub97c \uc5ec\ub7ec \uc7a5 \ub9cc\ub4e0\ub2e4\uace0 \ud558\uba74 \uc778\uc1c4\uae30\ub97c \uba3c\uc800 \uc0dd\uac01\ud55c\ub2e4. \uadf8\ub7f0\ub370 \uc81c2\ucc28 \uc138\uacc4\ub300\uc804\uae30\uc758 \uc18c\ub828 \ud0c0\uc2a4 \ud3ec\uc2a4\ud130 \uc911\uc5d0\ub294 \uc798\ub77c \ub9cc\ub4e0 \ud2c0\uc744 \ub300\uace0 \ud55c \uc7a5\uc529 \uc0c9\uc744 \uce60\ud55c \uac83\ub4e4\uc774 \uc788\uc5c8\ub2e4. \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc740 \ubaa8\uc2a4\ud06c\ubc14\uc758 \uc791\uc5c5\uc7a5\uc5d0\uc11c \uc774\ub7f0 \ud3ec\uc2a4\ud130\ub97c \uc81c\uc791\ud55c \uacfc\uc815\uc744 \uc18c\uac1c\ud55c\ub2e4. \uadf8\ub9bc\uc744 \uadf8\ub9ac\ub294 \uc77c\uacfc \uc5ec\ub7ec \uc0ac\ub78c\uc5d0\uac8c \uac19\uc740 \uc774\ubbf8\uc9c0\ub97c \ubcf4\ub0b4\ub294 \uc77c\uc774 \ud55c \uc791\uc5c5\uc7a5 \uc548\uc5d0\uc11c \ub9cc\ub0ac\ub2e4. \ud0c0\uc2a4\ub294 \ub2f9\uc2dc \uc18c\ub828\uc758 \uc911\uc559 \ud1b5\uc2e0 \uae30\uad00\uc774\uc5c8\ub2e4. \uc804\uc7c1 \uc18c\uc2dd\uc744 \uc0b4\ud53c\ub358 \ud654\uac00\uc640 \uc0bd\ud654\uac00, \uc2dc\uc778\uacfc \uc791\uac00\ub4e4\uc774 \ud3ec\uc2a4\ud130 \uc81c\uc791\uc5d0 \ucc38\uc5ec\ud588\ub2e4. \uc804\ud669\uc744 \uc804\ub2ec\ud558\ub294 \ub3d9\uc2dc\uc5d0 \uc0ac\ub78c\ub4e4\uc744 \uc124\ub4dd\ud558\uace0 \uc0ac\uae30\ub97c \ubd81\ub3cb\uc6b0\ub824\ub294 \uc120\uc804 \ub9e4\uccb4\uc774\uae30\ub3c4 \ud588\ub2e4. \ub514\uc790\uc778\uc774 \uc815\ud574\uc9c0\uba74 \uadf8\uac83\uc744 \ubc14\ud0d5\uc73c\ub85c \uc190\uc73c\ub85c \uc790\ub978 \uc2a4\ud150\uc2e4\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \uc2a4\ud150\uc2e4\uc740 \uc0c9\uc744 \ub123\uc744 \ubd80\ubd84\uc774 \ub6ab\ub9b0 \ud2c0\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \ub41c\ub2e4. \uac19\uc740 \ud2c0\uc744 \ubc18\ubcf5\ud574 \ub300\uba74 \ube44\uc2b7\ud55c \ubaa8\uc591\uc744 \uc5ec\ub7ec \uc885\uc774\uc5d0 \uc62e\uae38 \uc218 \uc788\ub2e4. \ubbf8\uc220\uad00\uc758 \uc124\uba85\uc5d0 \ub530\ub974\uba74 \uc791\uc5c5\uc790\ub4e4\uc740 \ud2c0\uc744 \uc0ac\uc6a9\ud574 \uc0c9 \ubd80\ubd84\uc744 \uce60\ud558\uace0 \ub354 \ub2e4\ub4ec\uc5c8\ub2e4. \uc644\uc131\ud55c \uc885\uc774 \uc870\uac01\ub4e4\uc740 \uae00\uc774 \uc801\ud78c \ud328\ub110\uacfc \ud0c0\uc2a4 \ubc88\ud638\ub97c \ub354\ud574 \ubd99\uc600\ub2e4. \uac70\ub300\ud55c \ud55c \uc7a5\ucc98\ub7fc \ubcf4\uc774\ub294 \uc774\ubbf8\uc9c0\uc5d0\ub3c4 \uc774\uc5b4 \ubd99\uc774\ub294 \uacfc\uc815\uc774 \uc788\uc5c8\ub2e4. \uadf8\ub798\uc11c \ud3ec\uc2a4\ud130\ub294 \ud654\uac00 \ud63c\uc790 \uadf8\ub9bc \ud55c \uc810\uc744 \ub05d\ub0b4\ub294 \uc77c\uacfc\ub294 \ub2e4\ub978 \uc81c\uc791 \uccb4\uacc4\ub97c \uac00\uc84c\ub2e4. \ud2c0\uc744 \uc790\ub974\ub294 \uc77c, \uce60\ud558\ub294 \uc77c, \uc870\uac01\uc744 \ub9de\ucd94\ub294 \uc77c\uc774 \uc5f0\uacb0\ub418\uba70 \uc5ec\ub7ec \uc7a5\uc758 \uacb0\uacfc\ubb3c\uc774 \ub098\uc654\ub2e4. \uc2a4\ud150\uc2e4\uc740 \uad6c\uba4d\uc774 \ub09c \ud2c0\uc744 \ud1b5\ud574 \uc0c9\uc744 \uc885\uc774\uc5d0 \uc62e\uae30\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc0c9\uc744 \ub2ec\ub9ac\ud558\ub824\uba74 \ud544\uc694\ud55c \ubd80\ubd84\uc744 \uad6c\ubd84\ud558\uace0 \ud2c0\uc744 \ub9de\ucd94\uc5b4\uc57c \ud55c\ub2e4. \ud55c \uc7a5\uc5d0 \uce60\ud55c \ud615\uc0c1\uc744 \ub2e4\uc74c \uc7a5\uc5d0\uc11c\ub3c4 \ube44\uc2b7\ud55c \uc790\ub9ac\uc5d0 \ub193\uc73c\ub824\uba74 \uc791\uc5c5 \uc21c\uc11c\uac00 \uc911\uc694\ud574\uc9c4\ub2e4. \uac19\uc740 \uadf8\ub9bc\uc744 \uc5ec\ub7ec \uc7a5 \ub9cc\ub4e0\ub2e4\ub294 \ub9d0 \uc548\uc5d0 \ubc18\ubcf5\ud574\uc11c \uc190\uc744 \uc6c0\uc9c1\uc774\ub294 \uc77c\uc774 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \uc774\ub7f0 \uc81c\uc791\uc5d0\uc11c\ub294 \ub514\uc790\uc778\uc744 \uace0\uc548\ud558\ub294 \uc0ac\ub78c\uacfc \uc2e4\uc81c \uc885\uc774\uc5d0 \uc0c9\uc744 \uc62c\ub9ac\ub294 \uc0ac\ub78c\uc758 \uc5ed\ud560\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ud654\uac00 \ud55c \uba85\uc758 \uc774\ub984\uc73c\ub85c\ub9cc \uae30\uc5b5\ud558\uba74 \ud2c0\uc744 \uc790\ub974\uace0 \uc704\uce58\ub97c \ub9de\ucd94\uace0 \uc885\uc774\ub97c \ubd99\uc778 \uc791\uc5c5\uc774 \ubcf4\uc774\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uc644\uc131\ud55c \ud3ec\uc2a4\ud130\uc758 \ud070 \ud654\uba74 \ub4a4\uc5d0 \uc791\uc740 \uacf5\uc815\ub4e4\uc774 \uc5f0\uacb0\ub418\uc5b4 \uc788\ub2e4\ub294 \uc810\uc744 \uc54c\uace0 \ubcf4\uba74 \uc190\uc73c\ub85c \ub9cc\ub4e0 \ubcf5\uc81c\ub77c\ub294 \ub9d0\ub3c4 \uc870\uae08 \uad6c\uccb4\uc801\uc73c\ub85c \ub4e4\ub9b0\ub2e4. \ubbf8\uc220\uad00 \uc124\uba85\uc5d0\ub294 \uc2dc\uc778\uacfc \uc791\uac00\uc758 \ucc38\uc5ec\uac00 \ud568\uaed8 \ub098\uc628\ub2e4. \uc774\ubbf8\uc9c0\ub97c \ub9cc\ub4e4\uace0 \ub098\uc11c \uae00\uc774 \ub0a8\ub294 \uc790\ub9ac\ub97c \uc544\ubb34 \ub9d0\ub85c \ucc44\uc6b4 \uac83\uc774 \uc544\ub2c8\ub2e4. \uadf8\ub9bc\uc758 \uc7a5\uba74\uacfc \ubb38\uc7a5\uc758 \uc5b4\uc870\uac00 \ud568\uaed8 \uad00\ub78c\uc790\uc758 \ubc18\uc751\uc744 \uc774\ub048\ub2e4. \uc6c3\uc74c\uc774\ub098 \ubd84\ub178, \uacbd\uacc4\uc2ec\uc744 \uc5b4\ub5a4 \ub300\uc0c1\uc73c\ub85c \ud5a5\ud558\uac8c \ud560\uc9c0 \uc815\ud558\ub294 \ub370\uc5d0\ub294 \ub9d0\uacfc \uc774\ubbf8\uc9c0 \ubaa8\ub450 \uc5ed\ud560\uc744 \ud560 \uc218 \uc788\ub2e4. \uc804\uc7c1\uae30\uc758 \uc120\uc804\ubb3c\uc774\ub77c\ub294 \uc131\uaca9\ub3c4 \uc5ec\uae30\uc11c \uc911\uc694\ud574\uc9c4\ub2e4. \uc2e4\uc81c \uc804\ud669\uc744 \uc54c\ub9ac\ub294 \uae30\ub2a5\uacfc \uc0ac\ub78c\uc744 \ud2b9\uc815\ud55c \ubc29\ud5a5\uc73c\ub85c \uc124\ub4dd\ud558\ub294 \uae30\ub2a5\uc740 \ud568\uaed8 \uc788\uc744 \uc218 \uc788\ub2e4. \ud3ec\uc2a4\ud130\uc5d0 \uc801\ud600 \uc788\ub2e4\uace0 \ubaa8\ub4e0 \uc8fc\uc7a5\uc744 \uc911\ub9bd\uc801\uc778 \ub274\uc2a4\ucc98\ub7fc \ubc1b\uc544\ub4e4\uc77c \uc218\ub294 \uc5c6\ub2e4. \ub204\uac00 \ub9cc\ub4e4\uc5c8\uace0 \ub204\uad6c\ub97c \ud5a5\ud588\uc73c\uba70 \uc5b4\ub5a4 \uac10\uc815\uc744 \uc694\uad6c\ud558\ub294\uc9c0 \ud568\uaed8 \uc77d\uc73c\uba74 \uc608\uc220\uacfc \uc815\ubcf4\uc758 \uad00\uacc4\uac00 \ub354 \uc120\uba85\ud574\uc9c4\ub2e4. \ucee4\ub2e4\ub780 \uc774\ubbf8\uc9c0\uac00 \uc5ec\ub7ec \uc885\uc774 \uc870\uac01\uacfc \uae00 \ud328\ub110, \ubc88\ud638\uc758 \uacb0\ud569\uc73c\ub85c \uc644\uc131\ub418\uc5c8\ub2e4\ub294 \uc810\uc740 \ubb3c\uac74\uc744 \ubcf4\ub294 \uc21c\uc11c\ub97c \ubc14\uafbc\ub2e4. \uba40\ub9ac\uc11c\ub294 \ud558\ub098\uc758 \uc7a5\uba74\uc774\uc9c0\ub9cc \uac00\uae4c\uc774\uc5d0\uc11c\ub294 \uc774\uc5b4 \ubd99\uc778 \ubd80\ubd84\uacfc \uc0c9\uc744 \ub098\ub208 \ud754\uc801\uc744 \ucc3e\uc744 \uc218 \uc788\ub2e4. \uadf8\ub9bc\uc758 \ub0b4\uc6a9\ubfd0 \uc544\ub2c8\ub77c \uadf8\uac83\uc774 \uc5b4\ub5a4 \ub2e8\uc704\ub85c \ub9cc\ub4e4\uc5b4\uc84c\ub294\uc9c0\ub3c4 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \uc5ec\uae30\uc758 \uc0bd\ud654\ub294 \uc774 \uacf5\uc815\uc744 \uc774\ud574\ud558\uae30 \uc704\ud55c \uac1c\ub150 \uadf8\ub9bc\uc774\ub2e4. \ud2b9\uc815 \uc6d0\ubcf8 \ud3ec\uc2a4\ud130\uc758 \uc811\ud569 \uc704\uce58\ub098 \ubd93 \uc790\uad6d\uc744 \ud655\uc778\ud558\ub294 \uc790\ub8cc\ub85c \uc0ac\uc6a9\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc2e4\uc81c \uc791\ud488\uc758 \uc0ac\uc9c4\uc744 \ubcfc \ub54c\uc5d0\ub294 \uc778\ubb3c\uacfc \ubb38\uc7a5\ubd80\ud130 \ubcf8 \ub4a4 \uc885\uc774\uc758 \uac00\uc7a5\uc790\ub9ac\ub85c \ub208\uc744 \uc62e\uaca8 \ubcf4\uc790. \uba54\uc2dc\uc9c0\uc758 \ud070 \ubaa9\uc18c\ub9ac \uc544\ub798\uc5d0 \uc190\uc73c\ub85c \uc870\ub9bd\ud55c \ubb3c\uac74\uc758 \uad6c\uc870\uac00 \ub0a8\uc544 \uc788\uc744 \uc218 \uc788\ub2e4. \uc0c1\uc810\uacfc \uacf5\uc7a5, \uacf5\uacf5 \uac74\ubb3c\uc740 \uc0ac\ub78c\ub4e4\uc774 \uc774\ubbf8 \ub2e4\ub978 \ubaa9\uc801\uc744 \uac00\uc9c0\uace0 \ub2e4\ub2c8\ub358 \uc7a5\uc18c\ub2e4. \uadf8\uacf3\uc758 \ud3ec\uc2a4\ud130\ub294 \ubbf8\uc220\uad00\uc758 \uc791\ud488\ucc98\ub7fc \uac10\uc0c1 \uc2dc\uac04\uc744 \ub530\ub85c \ub9c8\ub828\ud55c \uad00\ub78c\uc790\ub9cc \ub9cc\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc77c\uc744 \ud558\uac70\ub098 \ubb3c\uac74\uc744 \uc0ac\ub7ec \uac00\ub294 \uae38\uc5d0 \uc7a0\uc2dc \uc2dc\uc120\uc744 \ubd99\uc7a1\uc544\uc57c \ud55c\ub2e4. \uba54\uc2dc\uc9c0\uac00 \uc5b4\ub514\uc5d0 \ub193\uc774\ub294\uc9c0\uac00 \ud45c\ud604\uc758 \uc131\uaca9\uacfc \uc5f0\uacb0\ub418\ub294 \uc774\uc720\ub2e4. \uc791\uc5c5\uc7a5\uc758 \uc81c\uc791 \ubc29\uc2dd\uacfc \uac70\ub9ac\uc758 \ubc30\ud3ec\ub97c \uc774\uc5b4 \uc0dd\uac01\ud558\uba74 \uc608\uc220\uc774 \uc0ac\ud68c \uc548\uc5d0\uc11c \uc6c0\uc9c1\uc774\ub294 \uacbd\ub85c\uac00 \ubcf4\uc778\ub2e4. \ud55c \uc7a5\uc758 \uc774\ubbf8\uc9c0\ub97c \ub9cc\ub4dc\ub294 \ub370\uc11c \ub05d\ub098\uc9c0 \uc54a\uace0 \uc5ec\ub7ec \uc7a5\uc73c\ub85c \ub098\ub258\uc5b4 \ub2e4\ub978 \uc7a5\uc18c\uc758 \uc0ac\ub78c\uc5d0\uac8c \ub3c4\ucc29\ud55c\ub2e4. \uc5b4\ub5a4 \uc8fc\uc7a5\uc744 \ub2f4\uc558\ub294\uc9c0 \ube44\ud310\uc801\uc73c\ub85c \uc77d\ub294 \uc77c\uacfc, \uadf8 \uc8fc\uc7a5\uc744 \ud37c\ub728\ub9b0 \ubb3c\uac74\uc758 \ud615\ud0dc\ub97c \uc0b4\ud53c\ub294 \uc77c\uc740 \ud568\uaed8 \ud560 \uc218 \uc788\ub2e4. \uc774\ub807\uac8c \ub9cc\ub4e0 \ud3ec\uc2a4\ud130\ub294 \ubaa8\uc2a4\ud06c\ubc14\uc758 \uc0c1\uc810\uacfc \uacf5\uc7a5, \uacf5\uacf5 \uac74\ubb3c \ub4f1\uc73c\ub85c \ubcf4\ub0b4\uc84c\ub2e4. \uac10\uc0c1\ud558\ub824\uace0 \ucc3e\uc544\uc624\ub294 \uc804\uc2dc\uc7a5\ub9cc\uc774 \uc544\ub2c8\ub77c \uc0ac\ub78c\ub4e4\uc774 \uc9c0\ub098\ub294 \uc0dd\ud65c \uacf5\uac04\uc744 \ub9cc\ub098\ub294 \ub9e4\uccb4\uc600\ub2e4. \uc5ec\uae30\uc11c\ub294 \ud2b9\uc815 \ud3ec\uc2a4\ud130\ub97c \ubaa8\uc0ac\ud558\uc9c0 \uc54a\uace0 \uc81c\uc791 \uacfc\uc815\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc0bd\ud654\ub97c \ud568\uaed8 \uc2e4\uc5c8\ub2e4. \uadf8\ub9bc\uc774 \ubb34\uc5c7\uc744 \uc8fc\uc7a5\ud588\ub294\uc9c0\uc640 \ud568\uaed8 \uc5b4\ub5bb\uac8c \ub9cc\ub4e4\uc5b4\uc838 \uc5b4\ub514\ub85c \uac14\ub294\uc9c0\ub3c4 \ubb3c\uc5b4\ubcfc \uc218 \uc788\ub2e4. \uc885\uc774 \ud55c \uc7a5\uc758 \uc774\uc57c\uae30\uac00 \uc791\uc5c5\uc7a5\uc758 \uc190\uacfc \ub3c4\uc2dc\uc758 \ubcbd\uae4c\uc9c0 \ub113\uc5b4\uc9c0\ub294 \uc21c\uac04\uc774\ub2e4."}, {"id": "toyota-inventory-and-timing", "title": "\ud1a0\uc694\ud0c0 \u2014 \ucc3d\uace0\uac00 \uac00\ub4dd \ucc28\uba74 \uc548\uc2ec\ud574\ub3c4 \ub420\uae4c", "summary": "\ub9b0 \uc0dd\uc0b0\uacfc \uc801\uc2dc \uacf5\uae09\uc758 \uc6d0\ub9ac\uc5d0\uc11c \uc7ac\uace0\u00b7\ud611\ub825\u00b7\ud488\uc9c8\uc744 \ud568\uaed8 \uc124\uacc4\ud558\ub294 \ubb38\uc81c\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\uacf5\uc7a5\uacfc \uc0dd\uc0b0", "categories": ["industry"], "url": "stories/toyota-inventory-and-timing/index.html", "image": "../media/toyota-inventory-and-timing.png", "alt": "\uc790\ub3d9\ucc28 \uc870\ub9bd \uc791\uc5c5\uc7a5\uc5d0\uc11c \uc791\uc740 \ubd80\ud488\uc744 \ud568\uaed8 \ud655\uc778\ud558\ub294 \ub450 \uc791\uc5c5\uc790\uc758 AI \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ud1a0\uc694\ud0c0 \u2014 \ucc3d\uace0\uac00 \uac00\ub4dd \ucc28\uba74 \uc548\uc2ec\ud574\ub3c4 \ub420\uae4c \ub9ce\uc774 \uc313\uc544 \ub450\ub294 \uc77c\uacfc \uc798 \ub9cc\ub4dc\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4 \ub9b0 \uc0dd\uc0b0\uacfc \uc801\uc2dc \uacf5\uae09\uc758 \uc6d0\ub9ac\uc5d0\uc11c \uc7ac\uace0\u00b7\ud611\ub825\u00b7\ud488\uc9c8\uc744 \ud568\uaed8 \uc124\uacc4\ud558\ub294 \ubb38\uc81c\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uacf5\uc7a5\uacfc \uc0dd\uc0b0 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \uc790\ub3d9\ucc28 \uacf5\uc7a5 \uc606 \ucc3d\uace0\uc5d0 \ubd80\ud488\uc774 \ucc9c\uc7a5 \uac00\uae4c\uc774 \uc313\uc5ec \uc788\ub2e4. \uc774 \uc815\ub3c4\uba74 \ud55c\ub3d9\uc548 \uac71\uc815 \uc5c6\uc774 \ucc28\ub97c \ub9cc\ub4e4 \uc218 \uc788\uc744 \uac83 \uac19\ub2e4. \uadf8\ub7f0\ub370 \uacf5\uc7a5\uc744 \uc6b4\uc601\ud558\ub294 \uc0ac\ub78c\uc740 \ub2e4\ub978 \uc9c8\ubb38\uc744 \ud560 \uc218\ub3c4 \uc788\ub2e4. \uc9c0\uae08 \ud544\uc694\ud55c \uac83\uc740 \uc774 \uac00\uc6b4\ub370 \ubb34\uc5c7\uc774\uace0, \uc65c \ub098\uba38\uc9c0\ub294 \uae30\ub2e4\ub9ac\uace0 \uc788\uc744\uae4c. \ud1a0\uc694\ud0c0\ub294 \ubd88\ud544\uc694\ud55c \uacfc\uc815\uc744 \uc904\uc774\ub294 \ub9b0 \uc0dd\uc0b0\uc744 \ubc1c\uc804\uc2dc\ud0a8 \uc120\ub3c4 \uae30\uc5c5\uc73c\ub85c \uc54c\ub824\uc838 \uc788\ub2e4. \uc5b4\ub824\uc6b4 \uacbd\uc601 \uc6a9\uc5b4\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc \ucd9c\ubc1c\uc810\uc740 \uc77c\uc0c1\uc801\uc774\ub2e4. \ub354 \ub9ce\uc774 \uc0ac \ub450\uace0 \ub354 \ube68\ub9ac \uc6c0\uc9c1\uc774\ub294 \uac83\ub9cc\uc73c\ub85c \uc88b\uc740 \ubb3c\uac74\uc774 \uc81c\ub54c \ub9cc\ub4e4\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc0dd\uac01\uc774\ub2e4. \uc11c\ub78d\uc5d0 \uac74\uc804\uc9c0\uac00 \uac00\ub4dd\ud55c\ub370 \ub9ac\ubaa8\ucee8\uc5d0 \ub9de\ub294 \uaddc\uaca9\uc740 \uc5c6\ub294 \uc0c1\ud669\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc218\ub7c9\uc740 \ub9ce\uc544\ub3c4 \ub2f9\uc7a5 \ud544\uc694\ud55c \uc77c\uc744 \ud574\uacb0\ud558\uc9c0 \ubabb\ud55c\ub2e4. \uacf5\uc7a5\uc5d0\uc11c\ub3c4 \ubd80\ud488 \uc804\uccb4\uc758 \uc591\uacfc \uc2e4\uc81c\ub85c \uc9c0\uae08 \uc870\ub9bd\ud574\uc57c \ud558\ub294 \ubb3c\uac74\uc758 \ud544\uc694\ub294 \uad6c\ubcc4\ub41c\ub2e4. \uc774\uac83\uc740 \uc6d0\ub9ac\ub97c \uc774\ud574\ud558\uae30 \uc704\ud55c \uac00\uc0c1 \ube44\uc720\ub2e4. \ud2b9\uc815 \ud1a0\uc694\ud0c0 \uacf5\uc7a5\uc758 \uc0ac\ub840\ub97c \uc7ac\ud604\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uc0dd\uc0b0\uc744 \uc900\ube44\ud55c\ub2e4\ub294 \uc77c\uc774 \ubb34\uc5c7\uc774\ub4e0 \ub9ce\uc774 \ud655\ubcf4\ud558\ub294 \uac83\uacfc \uac19\uc9c0 \uc54a\ub2e4\ub294 \uc810\uc740 \ubd84\uba85\ud558\ub2e4. \uc885\ub958\uc640 \uc218\ub7c9\ubfd0 \uc544\ub2c8\ub77c \ud544\uc694\ud55c \ub54c\ub97c \ub9de\ucd94\ub294 \ubb38\uc81c\uac00 \ud568\uaed8 \uc788\ub2e4. OpenStax\uc758 \uacbd\uc601 \uad50\uc7ac\ub294 \ub9b0 \uc0dd\uc0b0\uc744 \uace0\uac1d\uc774 \uc6d0\ud558\ub294 \uc774\uc775\uc5d0 \ubcf4\ud0ec\uc774 \ub418\uc9c0 \uc54a\ub294 \ub2e8\uacc4\ub97c \uc904\uc774\ub294 \ubc29\uc2dd\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \uc81c\ud488\uc744 \ub9cc\ub4dc\ub294 \uacfc\uc815 \uac00\uc6b4\ub370 \ubb34\uc5c7\uc774 \uac00\uce58\ub97c \ub354\ud558\ub294\uc9c0 \uc0b4\ud53c\ub294 \uac83\uc774\ub2e4. \uc791\uc5c5\uc790\uac00 \uc26c\uc9c0 \uc54a\uace0 \uc6c0\uc9c1\uc774\ub294 \ubaa8\uc2b5\ub9cc\uc744 \ubaa9\ud45c\ub85c \uc0bc\ub294 \uc124\uba85\uacfc\ub294 \ub2e4\ub974\ub2e4. \ubb3c\uac74\uc744 \ubd88\ud544\uc694\ud558\uac8c \uc62e\uae30\uace0 \uae30\ub2e4\ub9ac\uac70\ub098, \uc798\ubabb \ub9cc\ub4e4\uc5b4 \ub2e4\uc2dc \uc190\ubcf4\ub294 \uacfc\uc815\uc740 \uc790\uc6d0\uc744 \uc0ac\uc6a9\ud55c\ub2e4. \uadf8\ub7f0 \uc6c0\uc9c1\uc784\uc744 \uc904\uc774\uba74 \uac19\uc740 \uacb0\uacfc\ub97c \uc5bb\ub294 \ub370 \ub4dc\ub294 \ubd80\ub2f4\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ub3d9\uc791\uc774 \ub9ce\uc544 \ubcf4\uc774\ub294\uac00\ubcf4\ub2e4 \uadf8 \ub3d9\uc791\uc774 \uace0\uac1d\uc5d0\uac8c \ud544\uc694\ud55c \uacb0\uacfc\uc640 \uc5f0\uacb0\ub418\ub294\uac00\ub2e4. \ubd80\ud488\uc744 \ubcf4\uad00\ud558\ub294 \ub3d9\uc548\uc5d0\ub3c4 \ucc3d\uace0\uc640 \uad00\ub9ac\uac00 \ud544\uc694\ud558\ub2e4. \uc544\uc9c1 \uc81c\ud488\uc73c\ub85c \ud314\ub9ac\uc9c0 \uc54a\uc740 \uc7ac\ub8cc\uc5d0 \uc790\uae08\uc774 \ubb36\uc774\uae30\ub3c4 \ud55c\ub2e4. \ub530\ub77c\uc11c \uc7ac\uace0\ub97c \ucda9\ubd84\ud788 \ub450\ub294 \uc120\ud0dd\uc5d0\ub294 \uc548\uc2ec\ud560 \uc218 \uc788\ub294 \uc774\uc810\uacfc \uacc4\uc18d \ubd80\ub2f4\ud574\uc57c \ud558\ub294 \ube44\uc6a9\uc774 \ud568\uaed8 \uc788\ub2e4. \uc7ac\ub8cc\uac00 \ub9ce\uc774 \uc313\uc5ec \uc788\ub2e4\uace0 \uc5b8\uc81c\ub098 \uacf5\uc7a5\uc774 \uc798 \uc6b4\uc601\ub418\ub294 \uc99d\uac70\ub294 \uc544\ub2c8\ub2e4. \ubc18\ub300\ub85c \uc7ac\uace0\uac00 \uc801\ub2e4\uace0 \uc800\uc808\ub85c \ud6a8\uc728\uc801\uc778 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \ud544\uc694\ud55c \ubd80\ud488\uc774 \ubaa8\uc790\ub77c \uc870\ub9bd\uc774 \uba48\ucd98\ub2e4\uba74 \ub2e4\ub978 \ubb38\uc81c\uac00 \uc0dd\uae34\ub2e4. \uc801\uc815\ud55c \uc7ac\uace0\ub97c \uc0dd\uac01\ud558\ub294 \uc77c\uc740 \ubb34\uc870\uac74 \ub9ce\uac70\ub098 \uc801\uc740 \ud55c\ucabd\uc744 \uace0\ub974\ub294 \uac83\ubcf4\ub2e4 \uc12c\uc138\ud558\ub2e4. \uc774\ub7f0 \uc0dd\uc0b0 \ucca0\ud559\uacfc \uc5f0\uacb0\ub418\ub294 \uac1c\ub150\uc774 \uc801\uc2dc \uacf5\uae09, \uc989 JIT\ub2e4. \uc7ac\ub8cc\ub97c \uc624\ub7ab\ub3d9\uc548 \ud604\uc7a5\uc5d0 \uc313\uc544 \ub450\uae30\ubcf4\ub2e4 \uc0dd\uc0b0\uc5d0 \ud544\uc694\ud560 \ub54c \ub9de\ucd94\uc5b4 \ub4e4\uc5b4\uc624\uac8c \ud558\ub824\ub294 \ubc29\uc2dd\uc774\ub2e4. \uad50\uc7ac\ub294 \uc218\uc694\uc5d0 \ub300\uc751\ud574 \uc0dd\uc0b0 \uacfc\uc815\uc73c\ub85c \ubb3c\uc790\uac00 \ub04c\ub824 \ub4e4\uc5b4\uc624\ub294 \ud750\ub984\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \uadf8\ub7ec\ub824\uba74 \uc55e\uc73c\ub85c \ubb34\uc5c7\uc744 \ub9cc\ub4e4\uace0 \uc5b4\ub290 \ub2e8\uacc4\uc5d0\uc11c \uc5b4\ub5a4 \ubd80\ud488\uc744 \uc0ac\uc6a9\ud560\uc9c0 \uc54c\uc544\uc57c \ud55c\ub2e4. \ucef4\ud4e8\ud130\ub85c \uc77c\uc815\uacfc \uc790\uc7ac \uc815\ubcf4\ub97c \uad00\ub9ac\ud558\ub294 \uc77c\ub3c4 \uc911\uc694\ud574\uc9c4\ub2e4. \uc7ac\uace0\ub97c \uc904\uc774\ub77c\ub294 \uad6c\ud638\ub9cc \uc678\uce5c\ub2e4\uace0 \uac00\ub2a5\ud55c \ubcc0\ud654\uac00 \uc544\ub2c8\ub2e4. \ub35c \uc313\uc544 \ub450\ub294 \ub9cc\ud07c \ub354 \uc798 \uc54c\uace0 \ub354 \uc815\ud655\ud558\uac8c \ub9de\ucd94\uc5b4\uc57c \ud55c\ub2e4. \ubd80\ud488 \uacf5\uae09\uc790\uc640 \uad6c\ub9e4 \ub2f4\ub2f9\uc790, \uc0dd\uc0b0 \ud604\uc7a5\uc740 \uc11c\ub85c \ub530\ub85c \uc6c0\uc9c1\uc77c \uc218 \uc5c6\ub2e4. \uc5b4\ub290 \ubb3c\uac74\uc774 \uc5b8\uc81c \ub3c4\ucc29\ud560\uc9c0\uc5d0 \ub300\ud55c \uc815\ubcf4\uac00 \uc5b4\uae0b\ub098\uba74 \ub2e4\uc74c \uc791\uc5c5\ub3c4 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4. \uc801\uc2dc \uacf5\uae09\uc740 \ucc3d\uace0 \uc548\uc758 \uc815\ub9ac\ubc95\ub9cc\uc774 \uc544\ub2c8\ub77c \uc5ec\ub7ec \ud68c\uc0ac\uc640 \uc0ac\ub78c\uc774 \uc77c\uc815\uc744 \ub9de\ucd94\ub294 \uad00\uacc4\ub2e4. \ub530\ub77c\uc11c \ud55c \uae30\uc5c5 \uc548\uc758 \ud6a8\uc728\ub9cc \ubcf4\uace0 \ub05d\ub0bc \uc218 \uc5c6\ub2e4. \uac11\uc791\uc2a4\ub7ec\uc6b4 \ubcc0\uacbd\uc758 \ubd80\ub2f4\uc744 \uacf5\uae09\uc790\uc5d0\uac8c \ubb34\uc791\uc815 \ub118\uae34\ub2e4\uba74 \uc804\uccb4 \ud750\ub984\uc740 \ubd88\uc548\uc815\ud574\uc9c8 \uc218 \uc788\ub2e4. \ub204\uad70\uac00\uc758 \uae30\ub2e4\ub9bc\uc744 \uc5c6\uc574\ub294\ub370 \ub2e4\ub978 \uacf3\uc5d0 \ub300\uae30\uac00 \uc313\uc778 \uac83\uc740 \uc544\ub2cc\uc9c0 \uc0b4\ud53c\ub294 \uad00\uc810\uc774 \ud544\uc694\ud558\ub2e4. \uc774\ub294 \uc6d0\ub9ac\ub97c \ud3c9\uac00\ud560 \ub54c \ub367\ubd99\uc77c \uc218 \uc788\ub294 \uc9c8\ubb38\uc774\ub2e4. \uad50\uc7ac\ub294 \uc790\uc5f0\uc7ac\ud574 \uac19\uc740 \uc0ac\uac74\uc774 \uacf5\uae09\ub9dd\uc744 \ud754\ub4e4 \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud544\uc694\ud55c \uc2dc\uc810\uc5d0 \ub9de\ucd94\uc5b4 \ub3c4\ucc29\ud560 \uac83\uc744 \uc804\uc81c\ub85c \ud55c \uc0dd\uc0b0\uc740 \uacf5\uae09\uc774 \ub04a\uae30\uba74 \uba48\ucd9c \uc704\ud5d8\uc774 \uc788\ub2e4. \ud3c9\uc18c\uc5d0 \uc798 \ub9de\ub358 \uacc4\ud68d\uacfc \ube44\uc0c1 \uc0c1\ud669\uc744 \uacac\ub514\ub294 \uacc4\ud68d\uc740 \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \uc774\uac83\uc774 \uc801\uc2dc \uacf5\uae09\uc740 \ud2c0\ub838\ub2e4\ub294 \uacb0\ub860\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uac00\uc7a5 \uc801\uc740 \uc7ac\uace0\uac00 \uc5b8\uc81c\ub098 \uac00\uc7a5 \uc88b\uc740 \uc7ac\uace0\ub77c\ub294 \ub2e8\uc21c\ud55c \uacf5\uc2dd\uc744 \ud53c\ud558\uac8c \ud55c\ub2e4. \ubd80\ud488\uc744 \ub2e4\uc2dc \uad6c\ud558\ub294 \ub370 \uac78\ub9ac\ub294 \uc2dc\uac04\uacfc \ub300\uccb4 \uac00\ub2a5\uc131, \uc911\ub2e8\ud588\uc744 \ub54c\uc758 \uc601\ud5a5\uc744 \uace0\ub824\ud574\uc57c \ud55c\ub2e4. \ud6a8\uc728\uacfc \uc5ec\uc720\ub97c \uc5b4\ub514\uc5d0 \ub458\uc9c0\uac00 \uc6b4\uc601\uc758 \uc120\ud0dd\uc774 \ub41c\ub2e4. \uac19\uc740 \uad50\uc7ac\ub294 \ud488\uc9c8\uacfc \uc0dd\uc0b0\uc131\uc744 \ub530\ub85c \ubcf4\uc9c0 \uc54a\ub294\ub2e4. \uacb0\ud568 \uc788\ub294 \uc81c\ud488\uc740 \uc7ac\ub8cc\uc640 \uc2dc\uac04\uc744 \ub0ad\ube44\ud558\uace0 \uace0\uac1d\uc758 \ubd88\ub9cc\uc744 \ub9cc\ub4e0\ub2e4. \ub9c8\uc9c0\ub9c9 \ub2e8\uacc4\uc5d0\uc11c \ubb38\uc81c\ub97c \ubc1c\uacac\ud574 \uace0\uce58\ub294 \uac83\ubfd0 \uc544\ub2c8\ub77c \uc0dd\uc0b0 \uc804\ubc18\uc5d0\uc11c \ud488\uc9c8\uc744 \uad00\ub9ac\ud574\uc57c \ud55c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc774 \uc810\uc744 \uc78a\uc73c\uba74 \uc0dd\uc0b0 \ucca0\ud559\uc774 \uc18d\ub3c4 \uacbd\uc7c1\uc73c\ub85c\ub9cc \ub0a8\ub294\ub2e4. \ub9cc\ub4dc\ub294 \uc218\ub7c9\uc774 \ub298\uc5b4\ub3c4 \uc7ac\uc791\uc5c5\uacfc \ud3d0\uae30\uac00 \ud568\uaed8 \ub298\uba74 \uacb0\uacfc\ub294 \ub2ec\ub77c\uc9c4\ub2e4. \uc9c0\uae08\uc758 \uae00\uc740 \ud1a0\uc694\ud0c0\uc758 \ud2b9\uc815 \ubaa8\ub378\uc774\ub098 \ucd5c\uadfc \uacf5\uc7a5\uc758 \uc131\uc801\ud45c\uac00 \uc544\ub2c8\ub77c, \uadf8 \ud68c\uc0ac\uac00 \ubc1c\uc804\uc2dc\ud0a8 \uac83\uc73c\ub85c \uc18c\uac1c\ub418\ub294 \uc0dd\uc0b0 \uc6d0\ub9ac\ub97c \uc774\ud574\ud558\ub294 \uc774\uc57c\uae30\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \ubd80\ud488\uc744 \uc0b4\ud3b4\ubcf4\ub294 \uc791\uc5c5\uc790\uc758 \ubaa8\uc2b5\uc744 \ud45c\ud604\ud588\ub2e4. \ud1a0\uc694\ud0c0\uc758 \uc2e4\uc81c \uacf5\uc7a5\uc774\ub098 \ud45c\uc900 \uc791\uc5c5\uc744 \ubcf5\uc6d0\ud55c \ub3c4\uba74\uc740 \uc544\ub2c8\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \uc313\uc778 \ubb3c\uac74\ubcf4\ub2e4 \ud544\uc694\ud55c \uac83\uc744 \ud568\uaed8 \ud655\uc778\ud558\ub294 \uc0ac\ub78c\uc758 \uad00\uacc4\ub97c \ub5a0\uc62c\ub9ac\uba74 \ub41c\ub2e4. \ud1a0\uc694\ud0c0\uc758 \uc0dd\uc0b0 \uc774\uc57c\uae30\ub294 \uc801\uac8c \uac00\uc9c0\ub77c\ub294 \uc0dd\ud65c \ud6c8\uacc4\uc640 \ub2e4\ub974\ub2e4. \ud544\uc694\ud55c \ubb3c\uac74\uc774 \ud544\uc694\ud55c \ub54c\uc5d0 \uc624\uace0 \uc81c\ub300\ub85c \ub9cc\ub4e4\uc5b4\uc9c0\ub3c4\ub85d \uc804\uccb4\ub97c \uc5f0\uacb0\ud558\ub294 \ubb38\uc81c\ub2e4. \ucc3d\uace0\uac00 \uac00\ub4dd\ud55c\uc9c0\ub97c \ubcf4\ub358 \ub208\uc774 \ubb3c\uac74\uc758 \ud750\ub984\uacfc \uc815\ubcf4\uc758 \ud750\ub984\uc744 \ud568\uaed8 \ubcf4\uac8c \ub418\ub294 \uc21c\uac04, \uacf5\uc7a5\uc740 \uc870\uae08 \ub2e4\ub978 \uc7a5\uc18c\ub85c \ubcf4\uc778\ub2e4."}, {"id": "zappos-circles-and-responsibility", "title": "\uc790\ud3ec\uc2a4 \u2014 \uc0c1\uc0ac\ub97c \uc5c6\uc560\uba74 \uc77c\uc740 \ub204\uac00 \uc815\ud560\uae4c", "summary": "\uc790\ud3ec\uc2a4\uc758 2013~2015\ub144 \uc870\uc9c1 \uc2e4\ud5d8\uc744 \ud1b5\ud574 \uc790\uc728\uc131\uacfc \ucc45\uc784\uc744 \ud568\uaed8 \uc124\uacc4\ud558\ub294 \uc5b4\ub824\uc6c0\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "industry", "category_title": "\uae30\uc5c5\uacfc \uc0b0\uc5c5", "subcategory": "\uacbd\uc601\uacfc \uc870\uc9c1", "categories": ["industry"], "url": "stories/zappos-circles-and-responsibility/index.html", "image": "../media/zappos-circles-and-responsibility.png", "alt": "\uc2e0\ubc1c\uacfc \ubc30\uc1a1 \uc0c1\uc790\uac00 \ub193\uc778 \uc0ac\ubb34\uc2e4\uc5d0\uc11c \ub3d9\ub8cc\ub4e4\uc774 \ub465\uadfc \uc2dd\ud0c1\uc5d0 \ubaa8\uc5ec \uc758\ub17c\ud558\ub294 AI \uc7a5\uba74.", "text": "\uc790\ud3ec\uc2a4 \u2014 \uc0c1\uc0ac\ub97c \uc5c6\uc560\uba74 \uc77c\uc740 \ub204\uac00 \uc815\ud560\uae4c \uc9c1\ud568\ubcf4\ub2e4 \uc5ed\ud560\uc744 \uc55e\uc138\uc6b4 \uc2e0\ubc1c \ud68c\uc0ac\uc758 \uc2e4\ud5d8 \uc790\ud3ec\uc2a4\uc758 2013~2015\ub144 \uc870\uc9c1 \uc2e4\ud5d8\uc744 \ud1b5\ud574 \uc790\uc728\uc131\uacfc \ucc45\uc784\uc744 \ud568\uaed8 \uc124\uacc4\ud558\ub294 \uc5b4\ub824\uc6c0\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uacbd\uc601\uacfc \uc870\uc9c1 \uae30\uc5c5\uacfc \uc0b0\uc5c5 \ud68c\uc758\uc5d0\uc11c \ub204\uad70\uac00 \ub9d0\ud55c\ub2e4. \uc55e\uc73c\ub85c\ub294 \ud300\uc7a5\uc774\ub77c\ub294 \uc9c1\ud568\uc744 \uc5c6\uc560\uaca0\uc2b5\ub2c8\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc0ac\ubb34\uc2e4\uc774 \uc870\uae08 \uc790\uc720\ub85c\uc6cc\uc9c8 \uac83 \uac19\ub2e4. \uadf8\ub7f0\ub370 \uace7 \ub2e4\uc74c \uc9c8\ubb38\uc774 \ub530\ub77c\uc628\ub2e4. \uadf8\ub7ec\uba74 \ubb34\uc5c7\uc744 \uba3c\uc800 \ud560\uc9c0, \uc758\uacac\uc774 \ub2e4\ub97c \ub54c \uc5b4\ub5bb\uac8c \uacb0\uc815\ud560\uc9c0, \uc77c\uc758 \uacb0\uacfc\ub294 \ub204\uac00 \ub9e1\uc744\uae4c. \uc628\ub77c\uc778 \uc2e0\ubc1c \ud310\ub9e4\ub85c \uc54c\ub824\uc9c4 \uc790\ud3ec\uc2a4\ub294 2010\ub144\ub300\uc5d0 \uc774\ub7f0 \uc9c8\ubb38\uc744 \uc2e4\uc81c \uc870\uc9c1 \uc6b4\uc601\uc758 \ubb38\uc81c\ub85c \ub2e4\ub8e8\uc5c8\ub2e4. \ub2f9\uc2dc \uacbd\uc601\uc790 \ud1a0\ub2c8 \uc170\uc774\ub294 \uae30\uc874 \uc9c1\ud568\uacfc \uace0\uc815\ub41c \uad00\ub9ac \uad6c\uc870\ub97c \ubc14\uafb8\ub294 \uc2e4\ud5d8\uc5d0 \ub098\uc130\ub2e4. \ubaa8\ub4e0 \ud68c\uc0ac\uac00 \ub530\ub77c\uc57c \ud560 \uc815\ub2f5\uc774\ub77c\uae30\ubcf4\ub2e4, \uc790\uc720\ub85c\uc6b4 \uc77c\ud130\ub97c \ub9cc\ub4e4\ub824 \ud560 \ub54c \ubb34\uc5c7\uae4c\uc9c0 \ubc14\uafb8\uc5b4\uc57c \ud558\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \uc0ac\ub840\ub2e4. OpenStax \uacbd\uc601\ud559 \uad50\uc7ac\ub294 2013\ub144 \ubb34\ub835 \uc790\ud3ec\uc2a4\uac00 \uc0ac\uc5c5\uc744 \uc798\ud558\uace0 \uc788\uc5c8\uc9c0\ub9cc, \uc170\uc774\uac00 \uc870\uc9c1\uacfc \ubb38\ud654\uc5d0 \uc0c8\ub85c\uc6b4 \ubcc0\ud654\ub97c \uc2dc\ub3c4\ud558\ub824 \ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\uac00 \ub3c4\uc785\ud55c \ubc29\uc2dd\uc758 \uc774\ub984\uc740 \ud640\ub77c\ud06c\ub77c\uc2dc\uc600\ub2e4. \uc774\ub984\uc740 \ub0af\uc124\uc9c0\ub9cc \uad00\uc2ec\uc744 \ub450\uc5b4\uc57c \ud560 \uc9c8\ubb38\uc740 \uac04\ub2e8\ud558\ub2e4. \uc0ac\ub78c\uacfc \uc77c\uc758 \uad00\uacc4\ub97c \uc5b4\ub5bb\uac8c \uc815\ud560 \uac83\uc778\uac00. \uc77c\ubc18\uc801\uc778 \uc870\uc9c1\uc5d0\uc11c\ub294 \ubd80\uc11c\uc640 \uc9c1\ud568\uc744 \ud1b5\ud574 \ucc45\uc784\uacfc \ubcf4\uace0 \uc21c\uc11c\ub97c \uc815\ud55c\ub2e4. \ud640\ub77c\ud06c\ub77c\uc2dc\ub294 \uace0\uc815\ub41c \uc9c1\ubb34 \ub300\uc2e0 \ud544\uc694\ud55c \uc5ed\ud560\uacfc \uc774\ub97c \uc218\ud589\ud558\ub294 \uc791\uc740 \ub2e8\uc704\ub4e4\uc744 \uc911\uc2ec\uc73c\ub85c \uc77c\ud558\ub824\ub294 \ubc29\uc2dd\uc774\uc5c8\ub2e4. \ub204\uac00 \ub204\uad6c\ubcf4\ub2e4 \ub192\uc740\uac00\ub9cc \ubcf4\uc9c0 \uc54a\uace0 \uc5b4\ub5a4 \uc77c\uc774 \ud544\uc694\ud558\uba70 \ub204\uac00 \ub9e1\uc744\uc9c0\ub97c \ub2e4\uc2dc \ubc30\uc5f4\ud558\ub294 \uad6c\uc0c1\uc774\ub2e4. \uc774 \uccb4\uacc4\uc5d0\uc11c \uae30\ubcf8 \ub2e8\uc704\ub97c \uc11c\ud074\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \ubaa9\ud45c\uc640 \ud544\uc694\uc5d0 \ub530\ub77c \ub9cc\ub4e4\uc5b4\uc9c0\uace0 \ubc14\ub00c\ub294 \ud300\uc73c\ub85c \uc0dd\uac01\ud558\uba74 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \uad50\uc7ac\ub294 \uc0ac\ub78c\ub4e4\uc774 \uad00\uc2ec\uacfc \ub2a5\ub825\uc5d0 \ub9de\ub294 \ud504\ub85c\uc81d\ud2b8\uc5d0 \ucc38\uc5ec\ud558\ub3c4\ub85d \ud558\ub824\ub294 \uc758\ub3c4\uac00 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc11c\ud074\uc774\ub77c\ub294 \ub9d0\uc774 \ubd99\uc5c8\ub2e4\uace0 \ubaa8\ub450\uac00 \ub611\uac19\uc740 \uc77c\uc744 \ub098\ub204\uc5b4 \ud558\uac70\ub098 \ubaa8\ub4e0 \ud310\ub2e8\uc744 \uc804\uc6d0\uc774 \ud22c\ud45c\ud55c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc5ed\ud560\uacfc \ucc45\uc784\uc744 \ubd84\uba85\ud558\uac8c \ubc30\uc815\ud558\ub294 \uc77c\uc774 \uc5ec\uc804\ud788 \ud544\uc694\ud558\ub2e4. \uc9c1\ud568\uc744 \uc904\uc774\ub294 \uac83\uacfc \uc5c5\ubb34\uc758 \uad6c\ubd84\uc744 \uc5c6\uc560\ub294 \uac83\uc740 \ub2e4\ub978 \ubcc0\ud654\ub2e4. \uc774 \ucc28\uc774\ub97c \ub193\uce58\uba74 \uc790\uc720\ub85c\uc6b4 \uc870\uc9c1\uc744 \ub9c9\uc5f0\ud788 \uaddc\uce59 \uc5c6\ub294 \uc0ac\ubb34\uc2e4\ub85c \uc0c1\uc0c1\ud558\uac8c \ub41c\ub2e4. \uae30\uc874 \uad00\ub9ac\uc790\uc758 \uc5ed\ud560\uc740 \ub2e4\ub978 \uc5ed\ud560\ub4e4\ub85c \ub098\ub258\uc5c8\ub2e4. \uad50\uc7ac\uc758 \uc124\uba85\uc5d0 \ub530\ub974\uba74 \uc77c\uc758 \ubc29\ud5a5\uc744 \uc548\ub0b4\ud558\ub294 \uc5ed\ud560, \uc9c1\uc6d0\uc758 \uc131\uc7a5\uc744 \ub3d5\ub294 \uba58\ud1a0, \ubcf4\uc0c1\uc744 \ud3c9\uac00\ud558\ub294 \uc5ed\ud560 \ub4f1\uc774 \ub530\ub85c \uc0dd\uacbc\ub2e4. \ub204\uad70\uac00 \ub9e1\uc544\uc57c \ud560 \uc77c\uc774 \uc5c6\uc5b4\uc84c\ub2e4\uae30\ubcf4\ub2e4 \ud55c \uc9c1\ud568 \uc544\ub798 \ubb36\uc5ec \uc788\ub358 \uc77c\uc744 \ub2e4\uc2dc \uad6c\ubd84\ud55c \uac83\uc774\ub2e4. \uc774 \ub300\ubaa9\uc5d0\uc11c \uc2e4\ud5d8\uc758 \ud575\uc2ec\uc774 \ubcf4\uc778\ub2e4. \uc9c1\ud568 \ud55c \uce78\uc744 \uc9c0\uc6b0\ub294 \uac83\uc740 \uc27d\uc9c0\ub9cc \uadf8 \uc0ac\ub78c\uc774 \ud574 \uc624\ub358 \ud310\ub2e8\uacfc \uc9c0\uc6d0\uae4c\uc9c0 \uc9c0\uc6b8 \uc218\ub294 \uc5c6\ub2e4. \uc790\uc720\ub97c \ub298\ub9ac\ub294 \ubcc0\ud654\ub294 \ubb34\uc5c7\uc744 \ud558\uc9c0 \uc54a\uc744\uc9c0\ubfd0 \uc544\ub2c8\ub77c \ud544\uc694\ud55c \uc77c\uc744 \ub204\uac00 \uacc4\uc18d \ud574 \uc904\uc9c0\ub3c4 \uc124\uacc4\ud574\uc57c \ud55c\ub2e4. \uc0ac\ub78c\uc744 \uc904 \uc138\uc6b0\ub294 \ubc29\uc2dd\uacfc \uc77c\uc744 \uc5f0\uacb0\ud558\ub294 \ubc29\uc2dd\uc740 \uac19\uc9c0 \uc54a\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc2e0\ubc1c\uc5d0 \uad00\ud55c \uace0\uac1d \ubb38\uc758\ub97c \ucc98\ub9ac\ud558\ub294 \uc0ac\ub78c\uc774 \ub2e4\ub978 \uac1c\uc120 \ud504\ub85c\uc81d\ud2b8\uc5d0\ub3c4 \ucc38\uc5ec\ud55c\ub2e4\uace0 \uc0dd\uac01\ud574 \ubcf4\uc790. \ud55c \uc0ac\ub78c\uc774 \uc5ec\ub7ec \uc5ed\ud560\uc744 \ub9e1\uc73c\uba74 \uc790\uc2e0\uc758 \ub2a5\ub825\uc744 \ub354 \ub2e4\uc591\ud558\uac8c \uc4f8 \uc218 \uc788\ub2e4. \uc774\uac83\uc740 \uc6d0\ub9ac\ub97c \uc124\uba85\ud558\uae30 \uc704\ud55c \uac00\uc0c1 \uc608\uc774\uba70 \uc2e4\uc81c \uc790\ud3ec\uc2a4 \uc9c1\uc6d0\uc758 \uc77c\uacfc\ub97c \uae30\ub85d\ud55c \uc7a5\uba74\uc740 \uc544\ub2c8\ub2e4. \ubc18\ub300\ub85c \ub450 \uc5ed\ud560\uc758 \uc77c\uc774 \ub3d9\uc2dc\uc5d0 \uae09\ud574\uc9c0\uba74 \uc6b0\uc120\uc21c\uc704\ub97c \uc815\ud574\uc57c \ud55c\ub2e4. \ub204\uad70\uac00\uc758 \uc790\uc728\uc801\uc778 \uc120\ud0dd\uc774 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc77c\uc815\uc5d0 \uc601\ud5a5\uc744 \uc8fc\uae30 \ub54c\ubb38\uc774\ub2e4. \uc9c1\ud568\uc774 \ub2e8\uc21c\ud558\uc9c0 \uc54a\uc744\uc218\ub85d \uc5ed\ud560 \uc0ac\uc774\uc758 \uc57d\uc18d\uc740 \ub354 \ubd84\uba85\ud574\uc57c \ud560 \uc218 \uc788\ub2e4. \uc790\uc720\uc640 \uc870\uc815\uc740 \uc11c\ub85c \ubc18\ub300\ub418\ub294 \uac83\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uc790\ud3ec\uc2a4\ub294 2015\ub144\uc5d0 \uc5ec\ub7ec \uae30\ub2a5\uc758 \uad6c\ubd84\uc744 \ub354 \ubc14\uafb8\uba70 \ubcc0\ud654\ub97c \ud655\ub300\ud588\ub2e4. \uad50\uc7ac\ub294 \uc9c0\uce68\uc774 \ub418\ub294 \ud5cc\uc7a5\ub3c4 \ub9c8\ub828\ud588\uc9c0\ub9cc \uc9c1\uc6d0\ub4e4\uc774 \uc0c8\ub85c\uc6b4 \ubc29\uc2dd\uc744 \uc775\ud788\ub294 \ub370 \uc5b4\ub824\uc6c0\uc774 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc0ac\ub78c\uc744 \ubbff\uc790\ub294 \ub73b\uc774 \ubd84\uba85\ud574\ub3c4 \uc2e4\uc81c\ub85c \uc77c\ud558\ub294 \uaddc\uce59\uc740 \ub0af\uc124 \uc218 \uc788\ub2e4. \uc0c8\ub85c\uc6b4 \uc870\uc9c1\uc5d0\uc11c\ub294 \ub204\uad6c\uc5d0\uac8c \ubb34\uc5c7\uc744 \ubb3c\uc5b4\ubd10\uc57c \ud558\ub294\uc9c0\ubd80\ud130 \ub2e4\uc2dc \ubc30\uc6cc\uc57c \ud55c\ub2e4. \uc790\uc2e0\uc774 \ub9e1\uc744 \uc218 \uc788\ub294 \ubc94\uc704, \ub2e4\ub978 \uc5ed\ud560\uacfc\uc758 \uad00\uacc4, \ubcf4\uc0c1\uc5d0 \uad00\ud55c \ud310\ub2e8\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc775\uc219\ud55c \ubcf4\uace0 \uc21c\uc11c\ub97c \uc5c6\uc560\ub294 \uc77c\uc774 \ubaa8\ub4e0 \uc0ac\ub78c\uc5d0\uac8c \uace7\ubc14\ub85c \ud3b8\uc548\ud568\uc744 \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ubcc0\ud654\uc758 \uc18d\ub3c4\ub3c4 \uc9c1\uc6d0\uc758 \uacbd\ud5d8\uc5d0 \uc601\ud5a5\uc744 \ubbf8\ucce4\ub2e4. \uad50\uc7ac\ub294 \ubcc0\ud654 \uacfc\uc815\uc5d0\uc11c \uc9c1\uc6d0 \uc774\ud0c8\uc774 \ub098\ud0c0\ub0ac\uace0 \uc77c\ubd80\uac00 \ube60\ub974\uace0 \ud070 \ubcc0\ud654\uc5d0 \uc9c0\ucce4\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc774\ud0c8\ud55c \uc0ac\ub78c \ubaa8\ub450\uc758 \uc774\uc720\ub97c \ud558\ub098\ub85c \ud655\uc815\ud558\uac70\ub098, \uadf8 \uc22b\uc790\ub9cc\uc73c\ub85c \uc81c\ub3c4 \uc804\uccb4\uc758 \uc131\uacf5\uacfc \uc2e4\ud328\ub97c \uc120\uc5b8\ud560 \uc218\ub294 \uc5c6\ub2e4. \uac1c\ubcc4 \uc0ac\ub78c\uc758 \uc120\ud0dd\uacfc \uae30\uc5c5 \uc804\uccb4\uc758 \uc131\uacfc\ub294 \ub2e4\ub978 \uc790\ub8cc\uac00 \ud544\uc694\ud55c \uc9c8\ubb38\uc774\ub2e4. \uc5ec\uae30\uc11c \ubd84\uba85\ud788 \uc77d\uc744 \uc218 \uc788\ub294 \uac83\uc740 \uc870\uc9c1\uc758 \uc774\uc0c1\uacfc \uc801\uc751\uc758 \uacbd\ud5d8 \uc0ac\uc774\uc5d0 \uac70\ub9ac\uac00 \uc788\uc5c8\ub2e4\ub294 \uc810\uc774\ub2e4. \uc124\uacc4\ud55c \uc0ac\ub78c\uc5d0\uac8c\ub294 \uba85\ud655\ud55c \ubc29\ud5a5\uc774 \ucc38\uc5ec\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ubcf5\uc7a1\ud55c \uc0c8 \uaddc\uce59\uc73c\ub85c \ubcf4\uc77c \uc218 \uc788\ub2e4. \uad6c\uc131\uc6d0\uc774 \uc774\ud574\ud558\uace0 \uc775\ud790 \uc2dc\uac04\uc744 \uc5b4\ub5bb\uac8c \ub9c8\ub828\ud560\uc9c0\ub3c4 \ubcc0\ud654\uc758 \uc77c\ubd80\uc600\ub2e4. \uc0c1\uc0ac\uac00 \uacb0\uc815\uc744 \ub300\uc2e0 \ub0b4\ub824 \uc8fc\uc9c0 \uc54a\ub294\ub2e4\uba74 \uc790\uc2e0\uc758 \ud310\ub2e8\uc774 \uc911\uc694\ud574\uc9c4\ub2e4. \ub3d9\uc2dc\uc5d0 \ub2e4\ub978 \uc0ac\ub78c\uacfc \uc57d\uc18d\uc744 \ub9de\ucd94\uace0 \uacb0\uacfc\ub97c \uc124\uba85\ud560 \ucc45\uc784\ub3c4 \uc0dd\uae34\ub2e4. \uc790\uc728\uc131\uc740 \ud558\uace0 \uc2f6\uc740 \uc77c\ub9cc \uace8\ub77c \ud558\ub294 \ud5c8\uac00\uc99d\ubcf4\ub2e4, \uc2a4\uc2a4\ub85c \ud310\ub2e8\ud560 \uc815\ubcf4\uc640 \ubc94\uc704\ub97c \uac16\ub294 \uc870\uac74\uc5d0 \uac00\uae5d\ub2e4. \uadf8\ub798\uc11c \uc790\ud3ec\uc2a4 \uc0ac\ub840\ub97c \uc77d\uc744 \ub54c\ub294 \uc0c1\uc0ac\ub97c \uc5c6\uc574\ub2e4\ub294 \ubb38\uc7a5 \ub4a4\ub97c \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc5ed\ud560\uc744 \uc5b4\ub5bb\uac8c \uc815\ud558\uace0 \uc77c\uc774 \uacb9\uce60 \ub54c \uc5b4\ub5bb\uac8c \ud480\uba70 \uc131\uc7a5\uacfc \ud3c9\uac00\ub97c \ub204\uac00 \ub3c4\uc6b8\uc9c0 \uac19\uc740 \ubb38\uc81c\uac00 \ub0a8\uc544 \uc788\ub2e4. \uc870\uc9c1\uc744 \uc218\ud3c9\uc801\uc73c\ub85c \ub9cc\ub4e4\ub824\ub294 \uc2dc\ub3c4\ub3c4 \uc2e4\uc81c\ub85c \uc791\ub3d9\ud558\ub824\uba74 \uaf64 \uad6c\uccb4\uc801\uc778 \uc7a5\uce58\uac00 \ud544\uc694\ud588\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc790\ud3ec\uc2a4\uc758 \uc2e4\uc81c \uc0ac\ubb34\uc2e4\uc774\ub098 \uc9c1\uc6d0\uc758 \ubaa8\uc2b5\uc744 \uc7ac\ud604\ud558\uc9c0 \uc54a\uc558\ub2e4. \uc5ed\ud560\uc744 \ub098\ub204\uae30 \uc704\ud574 \uc0ac\ub78c\ub4e4\uc774 \ub300\ud654\ud558\ub294 \uc7a5\uba74\uc744 \ud45c\ud604\ud588\ub2e4. \uc774 \uae00 \uc5ed\uc2dc 2013~2015\ub144\uc744 \uc911\uc2ec\uc73c\ub85c \uc18c\uac1c\ub41c \uc0ac\ub840\ub97c \uc77d\ub294 \uac83\uc774\uba70 \ud604\uc7ac \ud68c\uc0ac\uc758 \uc870\uc9c1\ub3c4\ub97c \uc548\ub0b4\ud558\ub294 \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc790\ud3ec\uc2a4\uc758 \uc2e4\ud5d8\uc740 \uc88b\uc740 \uc77c\ud130\ub97c \ud2b9\uc815\ud55c \uc9c1\ud568\uc758 \uc720\ubb34\ub85c \ud310\ub2e8\ud558\uae30 \uc5b4\ub835\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc790\uc720\ub86d\uac8c \uc77c\ud55c\ub2e4\ub294 \ub9d0\uc5d0\ub294 \uacb0\uc815\uc744 \ub3d5\ub294 \uc815\ubcf4\uc640 \ucc45\uc784\uc744 \ub098\ub204\ub294 \uc57d\uc18d\uc774 \ud568\uaed8 \ud544\uc694\ud558\ub2e4. \ub204\uac00 \uc0c1\uc0ac\uc778\uac00\ub97c \ubb3b\ub358 \uc790\ub9ac\uc5d0\uc11c, \uc77c\uc744 \uc798\ud558\ub824\uba74 \uc11c\ub85c\uc5d0\uac8c \ubb34\uc5c7\uc774 \ud544\uc694\ud55c\uac00\ub97c \ubb3b\uac8c \ub418\ub294 \uc774\uc57c\uae30\ub2e4."}, {"id": "ai-clothing-labels", "title": "AI\ub294 \uc637 \uc0ac\uc9c4\uc73c\ub85c \ubb34\uc5c7\uc744 \uc5f0\uc2b5\ud560\uae4c", "summary": "AI\uc758 \uc774\ubbf8\uc9c0 \ud559\uc2b5\uc744 \uc637\uc7a5 \uc815\ub9ac\ucc98\ub7fc \ub4e4\uc5ec\ub2e4\ubd05\ub2c8\ub2e4. \uc791\uc740 \ud751\ubc31 \uc0ac\uc9c4\uc5d0\ub3c4 \uc5f0\uc2b5\uacfc \uc2dc\ud5d8\uc774 \ub530\ub85c \uc788\uc2b5\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\uc778\uacf5\uc9c0\ub2a5", "categories": ["digital"], "url": "stories/ai-clothing-labels/index.html", "image": "../media/ai-clothing-labels.jpg", "alt": "\ud2f0\uc154\uce20\uc640 \ubc14\uc9c0, \uc6b4\ub3d9\ud654 \uc606\uc5d0 \ud53d\uc140 \uaca9\uc790\ub97c \uadf8\ub9b0 \uc124\uba85\uc6a9 AI \uc0bd\ud654", "text": "AI\ub294 \uc637 \uc0ac\uc9c4\uc73c\ub85c \ubb34\uc5c7\uc744 \uc5f0\uc2b5\ud560\uae4c \ud2f0\uc154\uce20\uc640 \uc6b4\ub3d9\ud654\uc5d0 \uc774\ub984\uc744 \ubd99\uc774\ub294 \uc791\uc740 \uc608\uc81c AI\uc758 \uc774\ubbf8\uc9c0 \ud559\uc2b5\uc744 \uc637\uc7a5 \uc815\ub9ac\ucc98\ub7fc \ub4e4\uc5ec\ub2e4\ubd05\ub2c8\ub2e4. \uc791\uc740 \ud751\ubc31 \uc0ac\uc9c4\uc5d0\ub3c4 \uc5f0\uc2b5\uacfc \uc2dc\ud5d8\uc774 \ub530\ub85c \uc788\uc2b5\ub2c8\ub2e4. \uc778\uacf5\uc9c0\ub2a5 \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \uc0ac\uc9c4\uc744 \ubcf4\uace0 \ud2f0\uc154\uce20\uc778\uc9c0 \uc6b4\ub3d9\ud654\uc778\uc9c0 \uace0\ub974\ub294 \uc77c\uc740 \uc0ac\ub78c\uc5d0\uac8c \ub300\uac1c \uc5b4\ub835\uc9c0 \uc54a\ub2e4. \uadf8\ub7f0\ub370 \ucef4\ud4e8\ud130\uc5d0\uac8c \uac19\uc740 \uc77c\uc744 \ub9e1\uae30\ub824\uba74 \ubb34\uc5c7\uc744 \ubcf4\uc5ec\uc8fc\uc5b4\uc57c \ud560\uae4c. TensorFlow\uc758 \uacf5\uc2dd \uc785\ubb38 \uc608\uc81c\ub294 \uc637\uacfc \uc2e0\ubc1c \ub4f1\uc758 \uc0ac\uc9c4\uc744 \ubd84\ub958\ud558\ub294 \uacfc\uc815\uc744 \uc18c\uac1c\ud55c\ub2e4. \uac70\ucc3d\ud55c \ud48d\uacbd \uc0ac\uc9c4 \ub300\uc2e0 \uc791\uc740 \ud751\ubc31 \uc774\ubbf8\uc9c0\uac00 \ub4f1\uc7a5\ud55c\ub2e4. \ud2f0\uc154\uce20, \ubc14\uc9c0, \uac00\ubc29, \uc6b4\ub3d9\ud654\ucc98\ub7fc \uc775\uc219\ud55c \ubb3c\uac74\ub4e4\uc774\ub2e4. \uc5b4\ub824\uc6b4 \ucf54\ub4dc\ub97c \ub530\ub77c \ud558\uc9c0 \uc54a\uace0\ub3c4 \uc774 \uc608\uc81c\uac00 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \uc900\ube44\ub418\uc5b4 \uc788\ub294\uc9c0\ub294 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uc608\uc81c\uc5d0\uc11c \uc0ac\uc6a9\ud558\ub294 Fashion-MNIST\uc5d0\ub294 \uc774\ubbf8\uc9c0\uc640 \ud568\uaed8 \uc885\ub958\ub97c \ub098\ud0c0\ub0b4\ub294 \ud45c\uc9c0\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \uc0ac\ub78c\uc758 \ub208\uc5d0\ub294 \uc637\uc73c\ub85c \ubcf4\uc774\ub294 \uc0ac\uc9c4\uc5d0, \ucef4\ud4e8\ud130\uac00 \ucc98\ub9ac\ud560 \uc218 \uc788\ub294 \uc815\ub2f5\uc744 \ubd99\uc5ec \ub454 \uc148\uc774\ub2e4. \uc774\ubbf8\uc9c0\ub294 \uac00\ub85c\uc640 \uc138\ub85c\uac00 \uac01\uac01 28\uce78\uc778 \uc791\uc740 \uaca9\uc790\ub85c \ud45c\ud604\ub41c\ub2e4. \uac01 \uce78\uc5d0\ub294 \ubc1d\uae30\ub97c \ub098\ud0c0\ub0b4\ub294 \uc22b\uc790\uac00 \ub4e4\uc5b4\uac04\ub2e4. \ud654\uba74\uc5d0 \ubcf4\uc774\ub294 \uadf8\ub9bc\uc744 \uacc4\uc0b0\ud560 \uc218 \uc788\ub294 \uac12\uc73c\ub85c \ub2e4\ub8e8\ub294 \uac83\uc774\ub2e4. \ubd84\ub958 \ub300\uc0c1\uc740 \uc5f4 \uc885\ub958\ub2e4. \uc774 \uc608\uc81c\uc758 \ubaa8\ub378\uc740 \uba3c\uc800 \uc815\ud574\uc9c4 \uc885\ub958\ub4e4 \uac00\uc6b4\ub370 \uc5b4\ub290 \ucabd\uc5d0 \uac00\uae4c\uc6b4\uc9c0 \uc5f0\uc2b5\ud55c\ub2e4. \uc138\uc0c1\uc758 \ubaa8\ub4e0 \uc637\uc744 \uc790\uc720\ub86d\uac8c \uc124\uba85\ud558\ub294 \uc2dc\uc2a4\ud15c\uc744 \ub9cc\ub4dc\ub294 \uac83\uacfc\ub294 \ubc94\uc704\uac00 \ub2e4\ub974\ub2e4. \uacf5\uc2dd \uc608\uc81c\ub294 \ud559\uc2b5\uc5d0 \uc4f0\ub294 \uc774\ubbf8\uc9c0 6\ub9cc \uc7a5\uacfc \ud3c9\uac00\uc5d0 \uc4f0\ub294 \uc774\ubbf8\uc9c0 1\ub9cc \uc7a5\uc744 \uad6c\ubd84\ud55c\ub2e4. \uc5f0\uc2b5\ud560 \ub54c \ubcf4\ub358 \uc0ac\uc9c4\uacfc \ub2e4\ub978 \uc0ac\uc9c4\uc5d0\uc11c\ub3c4 \ubd84\ub958\uac00 \uc798 \ub418\ub294\uc9c0 \ud655\uc778\ud558\ub824\ub294 \uad6c\uc131\uc774\ub2e4. \uc774\ubbf8 \ubcf8 \ubb38\uc81c\uc5d0\uc11c \uc798\ud588\ub2e4\uace0 \uc0c8\ub85c\uc6b4 \ubb38\uc81c\uc5d0\uc11c\ub3c4 \uac19\uc740 \uacb0\uacfc\ub97c \ub0b8\ub2e4\uace0 \uc7a5\ub2f4\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc608\uc81c\ub294 \uc774 \ucc28\uc774\uc640 \uacfc\uc801\ud569\uc774\ub77c\ub294 \ubb38\uc81c\ub3c4 \uc124\uba85\ud55c\ub2e4. \uc5ec\uae30\uc11c\ub294 \ud559\uc2b5\uc6a9 \uc0ac\uc9c4\uc744 \uc798 \ub9de\ud788\ub294 \uc77c\uacfc \uc0c8\ub85c\uc6b4 \uc0ac\uc9c4\uc744 \uc798 \ub9de\ud788\ub294 \uc77c\uc774 \ub2e4\ub974\ub2e4\ub294 \uc815\ub3c4\ub85c \uc774\ud574\ud558\uba74 \ub41c\ub2e4. \uc774 \uae00\uc5d0\uc11c \ubaa8\ub378\uc744 \uc9c1\uc811 \uc2e4\ud589\ud574 \uc131\ub2a5\uc744 \uce21\uc815\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uacf5\uc2dd \ubb38\uc11c\uac00 \uc5b4\ub5a4 \uc5f0\uc2b5\uacfc \ud3c9\uac00\ub97c \uc548\ub0b4\ud558\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uac83\uc774\ub2e4. \ub530\ub77c\uc11c \uc5ec\uae30\uc758 \uc124\uba85\uc774\ub098 \uc0bd\ud654\ub97c \uc2e4\uc81c \uc2e4\ud5d8 \uacb0\uacfc\ub85c \ubc1b\uc544\ub4e4\uc774\uba74 \uc548 \ub41c\ub2e4. \uc791\uc740 \uc774\ubbf8\uc9c0 \ud55c \uc7a5\uc740 \ubc1d\uae30\uc758 \uc22b\uc790\ub4e4\ub85c \ud45c\ud604\ub418\uace0, \uc815\ub2f5\ud45c\uc5d0\ub294 \uadf8 \uc774\ubbf8\uc9c0\uac00 \uc5b4\ub290 \uc885\ub958\uc5d0 \uc18d\ud558\ub294\uc9c0 \uc801\ud600 \uc788\ub2e4. \uc774 \ub458\uc774 \ud568\uaed8 \uc788\uc5b4\uc57c \uc5b4\ub5a4 \uc785\ub825\uc5d0 \uc5b4\ub5a4 \ub2f5\uc744 \uc5f0\uacb0\ud558\ub824\ub294\uc9c0 \uc54c \uc218 \uc788\ub2e4. \uc0ac\uc9c4 \uc18d \ubb3c\uac74\uc758 \uc774\ub984\uc744 \ucef4\ud4e8\ud130\uac00 \ucc98\uc74c\ubd80\ud130 \uc0ac\ub78c\ucc98\ub7fc \uc54c\uace0 \uc788\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc900\ube44\ub41c \uc608\ub97c \ud1b5\ud574 \uad6c\ubd84\ud558\ub294 \ubc29\uc2dd\uc744 \uc870\uc815\ud558\ub294 \uac83\uc774\ub2e4. \uac00\ub85c 28\uce78\uacfc \uc138\ub85c 28\uce78\uc744 \uacf1\ud558\uba74 784\uac1c\uc758 \uc704\uce58\uac00 \ub41c\ub2e4. \uc0ac\ub78c\uc740 \uc791\uc740 \uc2e4\ub8e8\uc5e3\uc744 \ud55c\ub208\uc5d0 \uc637\uc73c\ub85c \ubcfc \uc218 \uc788\uc9c0\ub9cc, \uacc4\uc0b0\uc5d0\uc11c\ub294 \uc774 \ubc1d\uae30\ub4e4\uc758 \uad00\uacc4\ub97c \ub2e4\ub8ec\ub2e4. \uc18c\ub9e4\uc640 \uad7d\uc774\ub77c\ub294 \ub9d0\uc744 \ucc98\uc74c\ubd80\ud130 \ubd99\uc5ec \ub193\uc9c0 \uc54a\uc544\ub3c4 \uc774\ubbf8\uc9c0\uc5d0 \ub098\ud0c0\ub09c \ubaa8\uc591\uc758 \ucc28\uc774\uac00 \ubd84\ub958\uc5d0 \uc4f0\uc77c \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ubb34\uc5c7\uc744 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \uad6c\ubd84\ud588\ub294\uc9c0\ub294 \uc2e4\uc81c \ubaa8\ub378\uacfc \uacb0\uacfc\ub97c \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uac19\uc740 \uc0ac\uc9c4\uc744 \ubc18\ubcf5\ud574\uc11c \ubcf8 \ub4a4 \ub2f5\uc744 \uc798 \ub9de\ud788\ub294 \uc77c\ub9cc\uc73c\ub85c\ub294 \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4. \uc2dc\ud5d8\uc5d0 \uc4f8 \uc774\ubbf8\uc9c0\ub97c \ub530\ub85c \ub450\ub294 \uae4c\ub2ed\uc740 \ucc98\uc74c \ubcf4\ub294 \uc790\ub8cc\uc5d0\uc11c\ub3c4 \ubc30\uc6b4 \uad6c\ubd84\uc774 \ud1b5\ud558\ub294\uc9c0 \ud655\uc778\ud558\uae30 \uc704\ud574\uc11c\ub2e4. \ud559\uad50\uc5d0\uc11c \uc5f0\uc2b5 \ubb38\uc81c\uc758 \ub2f5\uc744 \uc678\uc6b0\ub294 \uc77c\uacfc \uc870\uae08 \ub2ec\ub77c\uc9c4 \ubb38\uc81c\ub97c \uc774\ud574\ud558\ub294 \uc77c\uc744 \ub098\ub204\ub294 \ube44\uc720\ub85c \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc0ac\ub78c\uc758 \uc2dc\ud5d8\uacfc \uae30\uacc4\uc758 \ud559\uc2b5\uc774 \uac19\uc740 \uc6d0\ub9ac\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c \uc911\uc694\ud55c \uac83\uc740 \ud3c9\uac00\ud560 \uc790\ub8cc\ub97c \uc5f0\uc2b5 \uc790\ub8cc\uc640 \uad6c\ubcc4\ud55c\ub2e4\ub294 \uc124\uacc4\ub2e4. \ud559\uc2b5\uc6a9 6\ub9cc \uc7a5\uc774\ub77c\ub294 \ud070 \uc22b\uc790\ubcf4\ub2e4 \uadf8 \uc22b\uc790\uac00 \uc5b4\ub5a4 \uc5ed\ud560\ub85c \ub098\ub258\uc5c8\ub294\uc9c0 \ubcf4\uba74 \uc608\uc81c\uc758 \ubaa9\uc801\uc774 \uc120\uba85\ud574\uc9c4\ub2e4. \uc790\ub8cc\uac00 \ub9ce\ub2e4\ub294 \ub9d0\ub9cc\uc73c\ub85c \uac80\uc99d\uc774 \ucda9\ubd84\ud588\ub2e4\uace0 \uacb0\ub860\ub0b4\ub9b4 \uc218\ub294 \uc5c6\ub2e4. \uc774 \uc608\uc81c\ub294 \uc5f4 \uc885\ub958 \uac00\uc6b4\ub370 \ud558\ub098\ub97c \uace0\ub978\ub2e4. \uc0ac\ub78c\uc774 \uc0ac\uc9c4\uc744 \ubcf4\uace0 \uc0c9\uc774\ub098 \uc7ac\uc9c8, \uc5b4\uc6b8\ub9ac\ub294 \uacc4\uc808\uc744 \uc790\uc720\ub86d\uac8c \ub9d0\ud558\ub294 \uc77c\uacfc \ubc94\uc704\uac00 \ub2e4\ub974\ub2e4. \ubaa8\ub378\uc774 \uc120\ud0dd\ud560 \uc218 \uc788\ub294 \ub2f5\uc758 \ubaa9\ub85d\uc774 \uba3c\uc800 \uc815\ud574\uc838 \uc788\ub2e4. \uc9c8\ubb38\uc774 \uc5b4\ub5bb\uac8c \ub9cc\ub4e4\uc5b4\uc84c\ub294\uc9c0 \uc54c\uba74 AI\uac00 \uc637\uc744 \uc774\ud574\ud55c\ub2e4\ub294 \ud45c\ud604\uc744 \uc870\uae08 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \uc608\uc81c \ubc16\uc758 \ub0af\uc120 \ubb3c\uac74\uc774 \ub4e4\uc5b4\uc624\ub354\ub77c\ub3c4 \ub2f5\uc758 \ud615\uc2dd\uc774 \uc790\ub3d9\uc73c\ub85c \ub113\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub290 \ubc94\uc704\uc758 \uc0ac\uc9c4\uacfc \ubd84\ub958\ub97c \uc704\ud574 \uc900\ube44\ud55c \ubaa8\ub378\uc778\uc9c0 \ud655\uc778\ud558\ub294 \uc77c\uc774 \ud544\uc694\ud558\ub2e4. \ud55c \uc2dc\ud5d8\uc5d0\uc11c\uc758 \uacb0\uacfc\ub97c \uc138\uc0c1\uc758 \ubaa8\ub4e0 \uc0c1\ud488 \uc778\uc2dd \ub2a5\ub825\uc73c\ub85c \ud655\ub300\ud558\uc9c0 \uc54a\uc73c\uba74 \uc791\uc740 \uc2e4\ud5d8\uc744 \ub354 \uc815\ud655\ud558\uac8c \ud3c9\uac00\ud560 \uc218 \uc788\ub2e4. \uc881\uc740 \ubc94\uc704\ub97c \uc798 \uc815\ud55c \uc608\uc81c\ub3c4 \ucda9\ubd84\ud788 \uc720\uc6a9\ud558\ub2e4. \ubaa8\ub378\uc774 \uc5b4\ub5a4 \uc885\ub958\ub97c \uac15\ud558\uac8c \uc120\ud0dd\ud588\ub2e4\uace0 \uc2e4\uc81c \uc815\ub2f5\ub3c4 \ubc18\ub4dc\uc2dc \uadf8 \uc885\ub958\uc778 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb38\uc11c\ub294 \ub192\uc740 \ud655\uc2e0\uc73c\ub85c \uc798\ubabb \uace0\ub97c \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub2f5\uc5d0 \ubd99\uc740 \uc218\uce58\uc640 \uc2e4\uc81c \uc815\ud655\uc131\uc740 \ub098\ub780\ud788 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc218\uce58\ub97c \uc0ac\ub78c\uc774 \ub290\ub07c\ub294 \uc790\uc2e0\uac10\uacfc \uc644\uc804\ud788 \uac19\uc740 \ub9c8\uc74c \uc0c1\ud0dc\ub85c \ud574\uc11d\ud560 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \uc774 \uc810\uc740 \uacb0\uacfc\ub97c \uc0ac\uc6a9\ud558\ub294 \uc0ac\ub78c\uc758 \uc5ed\ud560\uacfc \uc774\uc5b4\uc9c4\ub2e4. \uc5b4\ub5a4 \uc885\ub958\uc5d0\uc11c \uc798\ubabb \uace0\ub974\ub294\uc9c0, \uc0c8 \uc0ac\uc9c4\uc774 \uc6d0\ub798 \uc790\ub8cc\uc640 \uc5bc\ub9c8\ub098 \ub2e4\ub978\uc9c0 \ubb3c\uc5b4\ubcf4\uc544\uc57c \ud55c\ub2e4. AI\uc758 \ub2f5\uc744 \uc77d\uc744 \ub54c\uc5d0\ub294 \ub9de\ud614\ub290\ub0d0\ub294 \uc9c8\ubb38 \uc606\uc5d0 \uc5b4\ub5a4 \ubb38\uc81c\uc5d0\uc11c \ud655\uc778\ud588\ub290\ub0d0\ub97c \ub193\uc544 \ubcf4\uc790. \uc791\uc740 \ud68c\uc0c9 \ud2f0\uc154\uce20 \uc0ac\uc9c4\uc73c\ub85c \uc2dc\uc791\ud55c \uc774\uc57c\uae30\uac00 \uc790\ub8cc\uc640 \uac80\uc99d\uc758 \uc870\uac74\uc744 \uc77d\ub294 \uc5f0\uc2b5\uc774 \ub41c\ub2e4. \uc608\uc81c\uc5d0\uc11c\ub294 \ubaa8\ub378\uc774 \uac01 \uc885\ub958\uc5d0 \ub300\ud574 \ub0b4\ub193\uc740 \uac12\uc744 \ube44\uad50\ud574 \ub2f5\uc744 \uc0b4\ud540\ub2e4. \ubb38\uc11c\uac00 \ud568\uaed8 \uac15\uc870\ud558\ub294 \uac83\uc740 \uc790\uc2e0 \uc788\uac8c \uace0\ub978 \ub2f5\ub3c4 \ud2c0\ub9b4 \uc218 \uc788\ub2e4\ub294 \uc810\uc774\ub2e4. \uc774 \uc0ac\uc2e4\uc744 \uc54c\uba74 AI\uac00 \uc774\ubbf8\uc9c0\ub97c \ubd84\ub958\ud55c\ub2e4\ub294 \ub9d0\uc744 \uc870\uae08 \uad6c\uccb4\uc801\uc73c\ub85c \uc774\ud574\ud558\uac8c \ub41c\ub2e4. \uc5b4\ub5a4 \uc0ac\uc9c4\uc73c\ub85c \ubb34\uc5c7\uc744 \uc5f0\uc2b5\ud588\uace0, \uc5b4\ub5a4 \uc885\ub958 \uc911\uc5d0\uc11c \ub2f5\uc744 \uace8\ub790\uc73c\uba70, \uc0c8 \uc0ac\uc9c4\uc73c\ub85c \uc5b4\ub5bb\uac8c \ud655\uc778\ud588\ub294\uc9c0\uae4c\uc9c0 \ubcf4\uac8c \ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc637 \uc0ac\uc9c4\uc744 \ubcfc \ub54c\ub9c8\ub2e4 \uc22b\uc790 \uaca9\uc790\ub97c \ub5a0\uc62c\ub9b4 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc0ac\ub78c\uc5d0\uac8c \uc775\uc219\ud55c \ubb3c\uac74\ub3c4 \ucef4\ud4e8\ud130\uc758 \uc5f0\uc2b5 \ubb38\uc81c\uac00 \ub420 \uc218 \uc788\ub2e4\ub294 \uac83\ub9cc\uc73c\ub85c \uc7ac\ubbf8\uc788\ub294 \uc2dc\uc791\uc774\ub2e4. \ub2e4\uc74c\uc5d0 AI\uac00 \uc0ac\uc9c4\uc5d0 \uc774\ub984\uc744 \ubd99\uc774\ub294 \ubaa8\uc2b5\uc744 \ubcf4\uba74 \ub2f5 \ud558\ub098\ub9cc \ubcf4\uc9c0 \ub9d0\uace0 \uadf8 \ub4a4\uc758 \uc5f0\uc2b5 \ubb38\uc81c\ub3c4 \uc0dd\uac01\ud574 \ubcf4\uc790. \uc791\uc740 \ud2f0\uc154\uce20 \uc0ac\uc9c4 \ud55c \uc7a5\uc774 \uc758\uc678\ub85c \ub9ce\uc740 \uc900\ube44\ub97c \ud488\uace0 \uc788\ub2e4."}, {"id": "alt-text-image-in-words", "title": "\ub300\uccb4 \ud14d\uc2a4\ud2b8 \u2014 \uadf8\ub9bc\uc744 \ub9d0\ub85c \uc804\ud55c\ub2e4\uba74", "summary": "\uc0ac\uc9c4\uc758 \ubaa9\uc801\uc5d0 \ub530\ub77c \uc124\uba85\uc774 \ub2ec\ub77c\uc9c0\ub294 \uc774\uc720\ub97c \ud1b5\ud574 \uc6f9 \uc774\ubbf8\uc9c0\uc758 \ub300\uccb4 \ud14d\uc2a4\ud2b8\uc640 \uc811\uadfc\uc131\uc744 \uc27d\uac8c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\ub514\uc9c0\ud138 \uc0dd\ud65c\uacfc \ubcf4\uc548", "categories": ["digital"], "url": "stories/alt-text-image-in-words/index.html", "image": "../media/alt-text-image-in-words.png", "alt": "\uac00\uc0c1\uc758 \ud48d\uacbd\ud654\ub97c \uc55e\uc5d0 \ub450\uace0 \uadf8\ub9bc \uc124\uba85\uc744 \ub098\ub204\ub294 \ub450 \uc0ac\ub78c\uacfc \uc606\uc758 \ud0dc\ube14\ub9bf\u00b7\ud5e4\ub4dc\ud3f0.", "text": "\ub300\uccb4 \ud14d\uc2a4\ud2b8 \u2014 \uadf8\ub9bc\uc744 \ub9d0\ub85c \uc804\ud55c\ub2e4\uba74 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc774\ubbf8\uc9c0\uc5d0\uc11c \ubb34\uc5c7\uc774 \ube60\uc9c0\ub294\uc9c0 \ubb3b\uae30 \uc0ac\uc9c4\uc758 \ubaa9\uc801\uc5d0 \ub530\ub77c \uc124\uba85\uc774 \ub2ec\ub77c\uc9c0\ub294 \uc774\uc720\ub97c \ud1b5\ud574 \uc6f9 \uc774\ubbf8\uc9c0\uc758 \ub300\uccb4 \ud14d\uc2a4\ud2b8\uc640 \uc811\uadfc\uc131\uc744 \uc27d\uac8c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ub514\uc9c0\ud138 \uc0dd\ud65c\uacfc \ubcf4\uc548 \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \uc778\ud130\ub137\uc5d0\uc11c \uc774\ubbf8\uc9c0\ub97c \uae30\ub2e4\ub9ac\ub294\ub370 \ube48\uc790\ub9ac\uc5d0 \uc9e7\uc740 \ubb38\uc7a5\ub9cc \ubcf4\uc778 \uc801\uc774 \uc788\uc744 \uac83\uc774\ub2e4. \ud30c\uc77c\uc774 \uc624\uc9c0 \uc54a\uc558\uc744 \ub54c \uc0ac\uc9c4 \ub300\uc2e0 \ub098\ud0c0\ub098\ub294 \ub9d0\uc77c \uc218 \uc788\ub2e4. \uadf8\ub7f0\ub370 \uc774 \ubb38\uc7a5\uc740 \uace0\uc7a5 \ub09c \ud654\uba74\uc744 \uc704\ud55c \uc784\uc2dc \uc548\ub0b4\uc5d0\ub9cc \uc4f0\uc774\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uadf8\ub9bc\uc744 \uc9c1\uc811 \ubcfc \uc218 \uc5c6\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub3c4 \ub0b4\uc6a9\uc744 \uc804\ub2ec\ud55c\ub2e4. \uc6f9\uc5d0\uc11c\ub294 \uc774\ub7f0 \uc124\uba85\uc744 \ub300\uccb4 \ud14d\uc2a4\ud2b8\ub77c\uace0 \ubd80\ub978\ub2e4. \uc911\uc694\ud55c \uc9c8\ubb38\uc740 \uadf8\ub9bc\uc5d0 \ubb34\uc5c7\uc774 \uc788\ub294\uac00\uc5d0\uc11c \ud55c \uac78\uc74c \ub354 \ub098\uc544\uac04\ub2e4. \uc774 \ud398\uc774\uc9c0\uc5d0\uc11c \uadf8 \uadf8\ub9bc\uc774 \uc5b4\ub5a4 \uc77c\uc744 \ud558\uace0 \uc788\uc73c\uba70, \ubcf4\uc774\uc9c0 \uc54a\uc73c\uba74 \uc5b4\ub5a4 \uc815\ubcf4\uac00 \uc0ac\ub77c\uc9c0\ub294\uac00\ub97c \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \uc5b4\ub5a4 \ub3c5\uc790\ub294 \ud654\uba74 \uc77d\uae30 \ud504\ub85c\uadf8\ub7a8\uc73c\ub85c \uc6f9\uc744 \uc774\uc6a9\ud55c\ub2e4. \uc5b4\ub5a4 \ub3c5\uc790\ub294 \ud1b5\uc2e0 \ud658\uacbd \ub54c\ubb38\uc5d0 \uc774\ubbf8\uc9c0\uac00 \ub2a6\uac8c \uc624\uac70\ub098 \ud45c\uc2dc\ub418\uc9c0 \uc54a\ub294\ub2e4. MDN\uc740 \ub300\uccb4 \ud14d\uc2a4\ud2b8\uac00 \uc774\ub7f0 \uc0c1\ud669\uc5d0\uc11c \ub3c4\uc6c0\uc774 \ub41c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc6f9\ud398\uc774\uc9c0\uc758 \ub3c5\uc790\uac00 \ubaa8\ub450 \uac19\uc740 \ud654\uba74\uc744 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ub9cc\ub098\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub530\ub77c\uc11c \ub300\uccb4 \ud14d\uc2a4\ud2b8\ub294 \ud2b9\uc815\ud55c \ud55c \uacbd\uc6b0\uc5d0\ub9cc \ub367\ubd99\uc774\ub294 \uc7a5\uc2dd\uc774 \uc544\ub2c8\ub2e4. \ub0b4\uc6a9\uc5d0 \uc811\uadfc\ud558\ub294 \ub2e4\ub978 \uae38\uc744 \ub9c8\ub828\ud558\ub294 \uc77c\uc774\ub2e4. \uc0ac\uc9c4\uc744 \ucda9\ubd84\ud788 \ud06c\uac8c \ub123\uc5c8\ub2e4\uace0 \ubaa8\ub4e0 \ub3c5\uc790\uc5d0\uac8c \uc815\ubcf4\uac00 \uc804\ub2ec\ub41c \uac83\uc740 \uc544\ub2d0 \uc218 \uc788\ub2e4. \ubb34\uc5c7\uc744 \ubcf4\uc774\uac8c \ud588\ub294\uc9c0\uc640 \ub204\uac00 \uadf8\uac83\uc744 \ubc1b\uc544\ub4e4\uc77c \uc218 \uc788\ub294\uc9c0\ub294 \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \uac00\uc0c1\uc758 \ub3c4\uc2dc \uc0b0\ucc45 \uae00\uc5d0 \ub2e4\ub9ac \uc0ac\uc9c4\uc744 \ub123\uc5c8\ub2e4\uace0 \ud574 \ubcf4\uc790. \ub300\uccb4 \ud14d\uc2a4\ud2b8\uac00 \uc0ac\uc9c4 \ud55c \uc7a5\uc774\ub77c\uace0\ub9cc \ub418\uc5b4 \uc788\ub2e4\uba74 \ub3c5\uc790\ub294 \uc5b4\ub5a4 \ub2e4\ub9ac\uc778\uc9c0, \ubb34\uc5c7\uc744 \uc0b4\ud3b4\ubcf4\uc544\uc57c \ud558\ub294\uc9c0 \uc54c\uae30 \uc5b4\ub835\ub2e4. \ud30c\uc77c\uc774 \uc774\ubbf8\uc9c0\ub77c\ub294 \uc0ac\uc2e4\ubcf4\ub2e4 \uc774\ubbf8\uc9c0\uac00 \uc804\ub2ec\ud558\ub294 \ub0b4\uc6a9\uc774 \ub354 \ud544\uc694\ud560 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubcf4\uc774\ub294 \ubaa8\ub4e0 \uc0c9\uacfc \ub3cc\uc758 \uc218\ub97c \ub05d\uc5c6\uc774 \uc801\ub294 \uac83\ub3c4 \ud56d\uc0c1 \uc88b\uc740 \ub2f5\uc740 \uc544\ub2c8\ub2e4. \uc0ac\uc9c4\uc774 \ub4e4\uc5b4\uac04 \ubaa9\uc801\uc5d0 \ub9de\ucd94\uc5b4 \uc911\uc694\ud55c \uc815\ubcf4\ub97c \uac04\uacb0\ud558\uac8c \uc804\ud574\uc57c \ud55c\ub2e4. \ub3c5\uc790\uc5d0\uac8c \ub3c4\uc6c0\uc774 \ub418\ub294 \uc124\uba85\uc740 \uc0ac\ubb3c\uc758 \ubaa9\ub85d\uc744 \uae38\uac8c \ub098\uc5f4\ud558\ub294 \uc77c\uacfc \ub2e4\ub974\ub2e4. \uc7a5\uba74\uc758 \ud575\uc2ec\uc744 \uace0\ub974\ub294 \ud3b8\uc9d1\uc774 \ub4e4\uc5b4\uac04\ub2e4. \ud55c \ub2e4\ub9ac \uc0ac\uc9c4\uc774 \uc5ec\ud589\uae30\uc5d0\uc11c\ub294 \ub3c4\uc2dc\uc758 \ubd84\uc704\uae30\ub97c \uc804\ud560 \uc218 \uc788\ub2e4. \uac74\ucd95 \ud574\uc124\uc5d0\uc11c\ub294 \uc544\uce58\uc758 \ud615\ud0dc\ub97c \uc124\uba85\ud558\ub294 \uc790\ub8cc\uc77c \uc218 \uc788\ub2e4. \uac19\uc740 \ud30c\uc77c\uc774\uc5b4\ub3c4 \ud398\uc774\uc9c0\uc5d0\uc11c \ub9e1\uc740 \uc5ed\ud560\uc774 \ub2e4\ub974\uba74 \ube60\uc838\uc11c\ub294 \uc548 \ub418\ub294 \uc815\ubcf4\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \ub300\uccb4 \ud14d\uc2a4\ud2b8\ub294 \uc774\ubbf8\uc9c0\uc640 \ubb38\ub9e5\uc744 \ud568\uaed8 \uc77d\uc5b4\uc57c \ud558\ub294 \uc774\uc720\ub2e4. \uc774\ub54c \uc0ac\uc9c4\uc73c\ub85c \ud655\uc778\ud558\uc9c0 \ubabb\ud55c \uc0ac\uc5f0\uc744 \uc124\uba85\uc5d0 \ubcf4\ud0dc\uba74 \uc548 \ub41c\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \uad6c\uc870\uc640 \uc790\ub8cc\ub85c \ud655\uc778\ud55c \uc0ac\uc2e4\uc744 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ub300\uccb4 \ud14d\uc2a4\ud2b8\ub3c4 \ub3c5\uc790\uac00 \ub0b4\uc6a9\uc744 \ubc1b\uc544\ub4e4\uc774\ub294 \ud1b5\ub85c\uc774\ubbc0\ub85c \uc815\ud655\uc131\uc774 \ud544\uc694\ud558\ub2e4. \uc9e7\uac8c \uc801\ub294\ub2e4\uace0 \uadfc\uac70\uc758 \uae30\uc900\uc774 \uac00\ubcbc\uc6cc\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubaa8\ub4e0 \uc774\ubbf8\uc9c0\uac00 \uc0c8\ub85c\uc6b4 \uc815\ubcf4\ub97c \ub2f4\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb38\ub2e8 \uc606\uc758 \ub2e8\uc21c\ud55c \uc7a5\uc2dd\ucc98\ub7fc \uc5c6\uc5b4\ub3c4 \ubcf8\ubb38\uc758 \uc758\ubbf8\uac00 \ub2ec\ub77c\uc9c0\uc9c0 \uc54a\ub294 \uacbd\uc6b0\uac00 \uc788\ub2e4. MDN\uc740 \uc774\ub7f0 \uc774\ubbf8\uc9c0\uc5d0 \ube48 \ub300\uccb4 \ud14d\uc2a4\ud2b8\ub97c \uc0ac\uc6a9\ud558\ub294 \ubc29\ubc95\uc744 \uc124\uba85\ud55c\ub2e4. \ud654\uba74 \uc77d\uae30 \ud504\ub85c\uadf8\ub7a8\uc774 \ubd88\ud544\uc694\ud55c \uc124\uba85\uc744 \ubc18\ubcf5\ud558\uc9c0 \uc54a\ub3c4\ub85d \ud558\uae30 \uc704\ud574\uc11c\ub2e4. \uc5ec\uae30\uc11c \ube44\uc6cc \ub454 \uac12\uacfc \uc124\uba85\uc744 \uc0dd\uac01\ud558\uc9c0 \uc54a\uace0 \ub204\ub77d\ud55c \uc0c1\ud0dc\ub294 \uac19\uc9c0 \uc54a\ub2e4. \uc804\uc790\ub294 \uc5ed\ud560\uc744 \ud310\ub2e8\ud55c \uacb0\uacfc\ub2e4. \ubb34\uc5c7\uc774\ub4e0 \ub9ce\uc774 \uc77d\uc5b4 \uc8fc\uba74 \ub354 \uce5c\uc808\ud560 \uac83\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc \uc911\uc694\ud55c \uc815\ubcf4 \uc0ac\uc774\uc5d0 \uc4f8\ubaa8\uc5c6\ub294 \uc18c\ub9ac\uac00 \uacc4\uc18d \ub07c\uba74 \uc774\uc6a9\uc774 \uc5b4\ub824\uc6cc\uc9c8 \uc218 \uc788\ub2e4. \ub35c \ub9d0\ud558\ub294 \uc120\ud0dd\ub3c4 \ub3c5\uc790\ub97c \uc704\ud55c \ud310\ub2e8\uc774 \ub41c\ub2e4. \uc774\ubbf8\uc9c0\ub97c \ub20c\ub7ec \ub2e4\ub978 \ud398\uc774\uc9c0\ub85c \uc774\ub3d9\ud558\uac8c \ub9cc\ub4e4 \uc218\ub3c4 \uc788\ub2e4. \uc774\ub54c\ub294 \uadf8\ub9bc\uc758 \uc0dd\uae40\uc0c8\ub9cc\ud07c \uadf8 \ub9c1\ud06c\uc758 \ubaa9\uc801\uc744 \uc544\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc9d1 \ubaa8\uc591 \uadf8\ub9bc\uc774 \uccab \ud654\uba74\uc73c\ub85c \uac00\ub294 \uae30\ub2a5\uc774\ub77c\uba74 \ub3c5\uc790\ub294 \uc9d1\uc758 \uc9c0\ubd95 \uc0c9\ubcf4\ub2e4 \uc5b4\ub514\ub85c \uc774\ub3d9\ud558\ub294\uc9c0 \uc54c\uace0 \uc2f6\uc744 \uc218 \uc788\ub2e4. MDN\uc740 \uc774\ubbf8\uc9c0 \ub9c1\ud06c\uc5d0\ub3c4 \uc811\uadfc \uac00\ub2a5\ud55c \ub9c1\ud06c \uc124\uba85\uc774 \ud544\uc694\ud558\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\ub9bc\uc758 \ubb18\uc0ac\uc640 \uae30\ub2a5\uc758 \uc548\ub0b4\uac00 \ub9cc\ub098\ub294 \ub300\ubaa9\uc774\ub2e4. \uac19\uc740 \uc791\uc740 \uc544\uc774\ucf58\ub3c4 \ubcf8\ubb38\uc758 \uc0bd\ud654\uc778\uc9c0 \uc6c0\uc9c1\uc774\ub294 \uae38\uc7a1\uc774\uc778\uc9c0\uc5d0 \ub530\ub77c \ud544\uc694\ud55c \ub9d0\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc758\ubbf8\ub294 \ud30c\uc77c \uc548\uc5d0\ub9cc \ub4e4\uc5b4 \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \ubcf5\uc7a1\ud55c \ub3c4\ud45c\ub098 \uc911\uc694\ud55c \uc124\uba85\uc744 \uadf8\ub9bc \ud558\ub098\uc5d0\ub9cc \ub2f4\uc73c\uba74 \uc9e7\uc740 \ub300\uccb4 \ud14d\uc2a4\ud2b8\ub85c \ucda9\ubd84\ud788 \uc62e\uae30\uae30 \uc5b4\ub824\uc6b8 \uc218 \uc788\ub2e4. MDN\uc740 \ud544\uc694\ud55c \uc815\ubcf4\ub97c \ubaa8\ub450\uac00 \uc77d\ub294 \ubcf8\ubb38\uc5d0\uc11c\ub3c4 \uc81c\uacf5\ud558\ub294 \ubc29\uc2dd\uc744 \uad8c\ud55c\ub2e4. \uc774\ubbf8\uc9c0\uc758 \ub0b4\uc6a9\uc744 \ub2e4\ub978 \uacbd\ub85c\ub85c \uc804\ud558\ub294 \uac83\uc774 \ud575\uc2ec\uc774\uc9c0 \ud55c \uce78\uc5d0 \ubaa8\ub4e0 \ubb38\uc7a5\uc744 \ubc00\uc5b4 \ub123\ub294 \uac83\uc774 \ubaa9\uc801\uc740 \uc544\ub2c8\ub2e4. \ubcf8\ubb38\uc774 \uc774\ubbf8 \ucda9\ubd84\ud788 \uc124\uba85\ud55c \ub0b4\uc6a9\uc744 \uadf8\ub300\ub85c \ubc18\ubcf5\ud558\uba74 \uc624\ud788\ub824 \uc9c0\ub8e8\ud558\uace0 \ud63c\ub780\uc2a4\ub7ec\uc6b8 \uc218 \uc788\ub2e4. \ubb34\uc5c7\uc744 \uc5b4\ub514\uc5d0\uc11c \uc804\ub2ec\ud588\ub294\uc9c0 \ud568\uaed8 \uc0b4\ud53c\ub294 \uc77c\uc774 \ud544\uc694\ud558\ub2e4. \uadf8\ub798\uc11c \ub300\uccb4 \ud14d\uc2a4\ud2b8\ub294 \ud30c\uc77c\uc744 \ub9c8\uc9c0\ub9c9\uc5d0 \uc62c\ub9b4 \ub54c\ub9cc \uc4f0\ub294 \ud56d\ubaa9\ubcf4\ub2e4 \uae00\uacfc \uadf8\ub9bc\uc744 \ud568\uaed8 \ud3b8\uc9d1\ud558\ub294 \uacfc\uc815\uc5d0 \uac00\uae5d\ub2e4. \uadf8\ub9bc \uc544\ub798\uc758 \ucea1\uc158\uc740 \ubcf4\ud1b5 \ubaa8\ub4e0 \ub3c5\uc790\uac00 \ud654\uba74\uc5d0\uc11c \uc77d\ub294 \uc124\uba85\uc774\ub2e4. \uc791\uac00\uc640 \uc5f0\ub3c4, \ucd9c\ucc98\uc640 \ub9e5\ub77d\uc744 \uc54c\ub824 \uc904 \uc218\ub3c4 \uc788\ub2e4. \ub300\uccb4 \ud14d\uc2a4\ud2b8\ub294 \uc774\ubbf8\uc9c0\ub97c \uc9c1\uc811 \ubcfc \uc218 \uc5c6\ub294 \uc0c1\ud669\uc5d0\uc11c \uadf8 \uc5ed\ud560\uc744 \ub300\uc2e0\ud560 \uc815\ubcf4\ub97c \uc81c\uacf5\ud55c\ub2e4. \ubaa9\uc801\uc774 \uc77c\ubd80 \uacb9\uccd0\ub3c4 \uc5b8\uc81c\ub098 \uac19\uc740 \ubb38\uc7a5\uc744 \ubcf5\uc0ac\ud558\ub294 \uac83\uc774 \uc815\ub2f5\uc740 \uc544\ub2c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uac00\uc0c1\uc758 \uadf8\ub9bc\uc744 \ub450\uace0 \uc124\uba85\uc744 \ub098\ub204\ub294 \uc7a5\uba74\uc774\ub2e4. \ud2b9\uc815 \ubc15\ubb3c\uad00\uc758 \uc2e4\uc81c \uc791\ud488\uc774\ub098 \ud604\uc7a5 \uc548\ub0b4\ub97c \uc7ac\ud604\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc791\ud488\uc744 \uc9c1\uc811 \ubcf4\ub294 \uae38\uacfc \ub9d0\ub85c \uc124\uba85\uc744 \ub4e3\ub294 \uae38\uc774 \ud568\uaed8 \uc788\uc744 \uc218 \uc788\ub2e4\ub294 \uc0dd\uac01\uc744 \ud45c\ud604\ud588\ub2e4. \uc774\ubbf8\uc9c0\ub97c \ubd99\uc774\ub294 \uc21c\uac04 \uae00\uc740 \ub354 \ud48d\ubd80\ud574\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uc774\ubbf8\uc9c0\uac00 \ubcf4\uc774\uc9c0 \uc54a\ub294 \ub3c5\uc790\uc5d0\uac8c\ub3c4 \uc911\uc694\ud55c \ub0b4\uc6a9\uc774 \ub0a8\uc544 \uc788\ub294\uc9c0 \ud55c \ubc88 \ub354 \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uadf8\ub9bc\uc744 \uace0\ub974\ub294 \uc77c\uacfc \uadf8\ub9bc\uc758 \uc5ed\ud560\uc744 \uc124\uba85\ud558\ub294 \uc77c\uc740 \uac19\uc740 \ud3b8\uc9d1\uc758 \ub2e4\ub978 \ub2e8\uacc4\ub2e4. \ub2e4\uc74c\uc5d0 \uc0ac\uc9c4\uc744 \ub123\uc744 \ub54c \uc7a0\uae50 \ub208\uc744 \uac10\uace0 \uc774 \uadf8\ub9bc\uc774 \ube60\uc9c0\uba74 \ubb34\uc5c7\uc744 \ub193\uce58\ub294\uc9c0 \uc0dd\uac01\ud574 \ubcf4\uc790. \ub2f5\uc774 \uc7a5\uc2dd\uc774\ub77c\uba74 \uc870\uc6a9\ud788 \uc9c0\ub098\uac00\uac8c \ud560 \uc218 \uc788\uace0, \ub2f5\uc774 \uc911\uc694\ud55c \uc815\ubcf4\ub77c\uba74 \uadf8 \ub0b4\uc6a9\uc744 \ub2e4\ub978 \uae38\ub85c\ub3c4 \uc804\ud574\uc57c \ud55c\ub2e4. \ub300\uccb4 \ud14d\uc2a4\ud2b8\ub294 \uc6f9\uc758 \uc791\uc740 \uc124\uba85\uc774 \uc5b4\ub5bb\uac8c \ub354 \ub9ce\uc740 \uc0ac\ub78c\uc5d0\uac8c \uc77d\uc744\uac70\ub9ac\ub97c \uc5f4\uc5b4 \uc8fc\ub294\uc9c0 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "arpanet-first-node", "title": "\uc778\ud130\ub137\uc5d0\ub3c4 \uccab \ubc88\uc9f8 \uc815\uac70\uc7a5\uc774 \uc788\uc5c8\ub2e4", "summary": "\uc5b4\ub514\uc5d0\ub098 \uc788\ub294 \uc778\ud130\ub137\ub3c4 \ucc98\uc74c\uc5d0\ub294 \uba87\uba87 \ucef4\ud4e8\ud130\ub97c \uc787\ub294 \uc2e4\ud5d8\uc5d0\uc11c \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\uc778\ud130\ub137\uacfc \ud1b5\uc2e0", "categories": ["digital"], "url": "stories/arpanet-first-node/index.html", "image": "../media/arpanet-first-node.jpg", "alt": "\ub450 \uc5f0\uad6c\uc2e4\uc758 \uc77c\ubc18\ud654\ud55c \ucd08\uae30 \ucef4\ud4e8\ud130\ub97c \uc120\uc73c\ub85c \uc5f0\uacb0\ud55c \uc124\uba85\uc6a9 AI \uc0bd\ud654", "text": "\uc778\ud130\ub137\uc5d0\ub3c4 \uccab \ubc88\uc9f8 \uc815\uac70\uc7a5\uc774 \uc788\uc5c8\ub2e4 1969\ub144, \uc5f0\uad6c\uc2e4\uc758 \ucef4\ud4e8\ud130\uac00 \uc5f0\uacb0\ub418\ub358 \ub54c \uc5b4\ub514\uc5d0\ub098 \uc788\ub294 \uc778\ud130\ub137\ub3c4 \ucc98\uc74c\uc5d0\ub294 \uba87\uba87 \ucef4\ud4e8\ud130\ub97c \uc787\ub294 \uc2e4\ud5d8\uc5d0\uc11c \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4. \uc778\ud130\ub137\uacfc \ud1b5\uc2e0 \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \uc778\ud130\ub137\uc740 \ub208\uc5d0 \ubcf4\uc774\ub294 \uac74\ubb3c \ud558\ub098\uac00 \uc544\ub2c8\uc5b4\uc11c \ucd9c\ubc1c\uc810\uc744 \uc0c1\uc0c1\ud558\uae30 \uc5b4\ub835\ub2e4. \ud734\ub300\uc804\ud654\uc758 \ud654\uba74\uc744 \uc5f4\uba74 \uc774\ubbf8 \uadf8 \uc548\uc5d0 \uc788\uace0, \ub2e4\ub978 \ub098\ub77c\uc758 \uc18c\uc2dd\ub3c4 \uae08\uc138 \ub3c4\ucc29\ud55c\ub2e4. \uadf8\ub7f0\ub370 \uc624\ub298\uc758 \uc778\ud130\ub137\uc73c\ub85c \uc774\uc5b4\uc9c4 \ucd08\uae30 \ub124\ud2b8\uc6cc\ud06c\uc5d0\ub294 \uc2e4\uc81c \ucef4\ud4e8\ud130\uac00 \ub193\uc778 \uc5f0\uad6c\uc2e4\ub4e4\uc774 \uc788\uc5c8\ub2e4. \uadf8\uc911 \uccab \ubc88\uc9f8 \uc9c0\uc810\uc740 \ubbf8\uad6d UCLA\uc758 \ub808\ub108\ub4dc \ud074\ub77c\uc778\ub85d \uc5f0\uad6c\uc2e4\uc774\uc5c8\ub2e4. \uc778\ud130\ub137 \uba85\uc608\uc758 \uc804\ub2f9\uc740 \uadf8 \uc5f0\uad6c\uc2e4\uc758 \ucef4\ud4e8\ud130\uac00 1969\ub144 9\uc6d4 ARPANET\uc758 \uccab \ub178\ub4dc\uac00 \ub418\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ub178\ub4dc\ub294 \uc5ec\uae30\uc11c \ub124\ud2b8\uc6cc\ud06c\uc5d0 \uc5f0\uacb0\ub418\ub294 \uc9c0\uc810\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \ub41c\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294 \uae38\uc758 \uccab \uc815\uac70\uc7a5\uc5d0 \uc8fc\uc18c\uc9c0\uac00 \uc788\uc5c8\ub358 \uc148\uc774\ub2e4. ARPANET\uc740 \uc624\ub298\uc758 \uc778\ud130\ub137\uc73c\ub85c \uc774\uc5b4\uc9c4 \ucd08\uae30 \ub124\ud2b8\uc6cc\ud06c\ub2e4. \uc9c0\uae08\uc758 \uc6f9\uc0ac\uc774\ud2b8\uc640 \uba54\uc2e0\uc800\uac00 \ubaa8\ub450 \uac16\ucd94\uc5b4\uc9c4 \uc0c1\ud0dc\ub85c \uc2dc\uc791\ud55c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc6b0\uc120 \uc11c\ub85c \ub5a8\uc5b4\uc9c4 \ucef4\ud4e8\ud130\uac00 \uc815\ubcf4\ub97c \uc8fc\uace0\ubc1b\uc744 \uc218 \uc788\uc5b4\uc57c \ud588\ub2e4. \ud074\ub77c\uc778\ub85d\uc758 \uc5f0\uad6c\uc2e4\uc5d0\uc11c\ub294 \uccab \uc5f0\uacb0 \uc9c0\uc810\uc744 \ub9c8\ub828\ud55c \ub2e4\uc74c \ub2ec, \ub124\ud2b8\uc6cc\ud06c\ub97c \ud1b5\ud55c \uccab \uc804\uc1a1\uc774 \uc774\ub8e8\uc5b4\uc84c\ub2e4. \ub2e4\ub978 \ub05d\uc5d0\ub294 \uce98\ub9ac\ud3ec\ub2c8\uc544 SRI\uc758 \uc5f0\uad6c\ud300\uc774 \uc788\uc5c8\ub2e4. \uc778\ud130\ub137 \uba85\uc608\uc758 \uc804\ub2f9\uc740 \ub354\uae00\ub7ec\uc2a4 \uc5e5\uac94\ubc14\ud2b8\uac00 \uc774\ub04c\ub358 \uc5f0\uad6c\uc18c\uac00 \ub450 \ubc88\uc9f8 \ud638\uc2a4\ud2b8\uac00 \ub418\uc5b4 UCLA\uc640 \ucd08\uae30 \uc804\uc1a1\uc744 \uc8fc\uace0\ubc1b\uc558\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc7a5\uc18c\uc758 \uc5f0\uad6c\uac00 \ud558\ub098\uc758 \uc5f0\uacb0 \uc548\uc5d0\uc11c \ub9cc\ub09c \uac83\uc774\ub2e4. \uc624\ub298\uc758 \uac10\uac01\uc73c\ub85c \ubcf4\uba74 \ucef4\ud4e8\ud130 \ub450 \uacf3\uc774 \ub300\ud654\ud558\ub294 \uc77c\uc740 \uc791\uc740 \uc131\uacfc\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc5f0\uacb0\uc774 \ub2f9\uc5f0\ud558\uc9c0 \uc54a\uc558\ub358 \uc2dc\uc810\uc5d0\ub294, \uadf8 \ub300\ud654\uac00 \uc774\ub8e8\uc5b4\uc9c0\ub3c4\ub85d \uc870\uac74\uc744 \ub9cc\ub4dc\ub294 \uc77c\ubd80\ud130 \ud544\uc694\ud588\ub2e4. \uc778\ud130\ub137\uc758 \uc2dc\uc791\uc744 \ud55c \uc0ac\ub78c\uc758 \uc0ac\uc9c4\uc73c\ub85c \uc124\uba85\ud558\ub824 \ud558\uba74 \uae08\uc138 \ub2e4\ub978 \uc774\ub984\ub4e4\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \uc5f0\uacb0\uc758 \uc6d0\ub9ac\ub97c \uc5f0\uad6c\ud55c \uc0ac\ub78c, \ucef4\ud4e8\ud130\ub97c \uc900\ube44\ud55c \uc0ac\ub78c, \uc18c\ud504\ud2b8\uc6e8\uc5b4\uc640 \ud1b5\uc2e0 \uaddc\uce59\uc744 \ub9cc\ub4e0 \uc0ac\ub78c\ub4e4\uc774 \uc788\uc5c8\ub2e4. \ud074\ub77c\uc778\ub85d\uc740 \ud328\ud0b7 \ub124\ud2b8\uc6cc\ud06c\uc758 \uc218\ud559\uc801 \uc5f0\uad6c\ub85c\ub3c4 \uc18c\uac1c\ub41c\ub2e4. \uc815\ubcf4\ub97c \uc77c\uc815\ud55c \ub2e8\uc704\ub85c \ub098\ub204\uc5b4 \ubcf4\ub0b4\ub294 \ubc29\uc2dd\uc774 \ub124\ud2b8\uc6cc\ud06c\ub97c \uc774\ud574\ud558\ub294 \uc911\uc694\ud55c \ubc14\ud0d5\uc774 \ub418\uc5c8\ub2e4\ub294 \uac83\uc774\ub2e4. \uc5ec\uae30\uc11c \uc5b4\ub824\uc6b4 \uc218\uc2dd\uc744 \ub530\ub77c\uac08 \ud544\uc694\ub294 \uc5c6\ub2e4. \ucef4\ud4e8\ud130\ub97c \uc5f0\uacb0\ud558\ub294 \ub370\uc5d0\ub3c4 \uc5f0\uad6c\uac00 \ud544\uc694\ud588\ub2e4\ub294 \uc815\ub3c4\uba74 \ucda9\ubd84\ud558\ub2e4. \uccab \ubc88\uc9f8 \uc9c0\uc810\uc5d0 \uad00\uc2ec\uc744 \ub450\ub294 \uac83\uc740 \uadf8 \ud55c \uacf3\uc774 \ubaa8\ub4e0 \uac83\uc744 \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uc5f0\uacb0\uc740 \uc0c1\ub300\uac00 \uc788\uc5b4\uc57c \uc131\ub9bd\ud55c\ub2e4. \uccab \uc815\uac70\uc7a5\uc774\ub77c\ub294 \ud45c\ud604\ub3c4 \ub450 \ubc88\uc9f8 \uc815\uac70\uc7a5\uc774 \uc0dd\uacbc\uc744 \ub54c \ube44\ub85c\uc18c \uc2e4\uac10\uc774 \ub09c\ub2e4. \ud55c \uc7a5\uc18c\uc5d0 \uc7a5\ube44\ub97c \ub9c8\ub828\ud558\ub294 \uc77c\uacfc \ub2e4\ub978 \uc7a5\uc18c\uc640 \uc815\ubcf4\ub97c \uc8fc\uace0\ubc1b\ub294 \uc77c\uc740 \uc774\uc5b4\uc9c0\uc9c0\ub9cc \ub2e4\ub974\ub2e4. \uc5f0\uad6c\uc2e4\uc758 \uccab \ub178\ub4dc\ub77c\ub294 \uae30\ub85d\uc740 \uadf8\uacf3\ub9cc\uc73c\ub85c \ub124\ud2b8\uc6cc\ud06c\uac00 \uc644\uc131\ub418\uc5c8\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uc0c1\ub300\ud3b8\uc758 \uc7a5\ube44\uc640 \uc18c\ud504\ud2b8\uc6e8\uc5b4, \uc11c\ub85c \uc774\ud574\ud560 \ud1b5\uc2e0 \ubc29\uc2dd\ub3c4 \ud544\uc694\ud588\ub2e4. \uccab \uc815\uac70\uc7a5\uc774\ub77c\ub294 \ube44\uc720\ub294 \ud568\uaed8 \uc774\uc5b4\uc9c0\ub294 \ub2e4\ub978 \uc9c0\uc810\uc774 \uc788\uc744 \ub54c \uad6c\uccb4\uc801\uc778 \uc758\ubbf8\ub97c \uc5bb\ub294\ub2e4. \uadf8\ub798\uc11c UCLA\uc640 SRI\uc758 \uc774\ub984\uc744 \ud568\uaed8 \uae30\uc5b5\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc778\ud130\ub137\uc758 \uc5ed\uc0ac\ub97c \ud55c \uc5f0\uad6c\uc790\uc758 \uc5c5\uc801\uc73c\ub85c\ub9cc \uc904\uc774\uba74 \uc2e4\uc81c \uc5f0\uacb0\uc744 \uac00\ub2a5\ud558\uac8c \ud55c \uc5ec\ub7ec \uc5ed\ud560\uc774 \ubc30\uacbd\uc73c\ub85c \ubb3c\ub7ec\ub09c\ub2e4. \ub204\uac00 \ucc98\uc74c\uc774\ub0d0\ub294 \uc9c8\ubb38 \uc606\uc5d0 \uc5b4\ub290 \uacf3\uacfc \ubb34\uc5c7\uc744 \uc8fc\uace0\ubc1b\uc558\ub290\ub0d0\ub97c \ub193\uc73c\uba74 \uc0ac\uac74\uc758 \uc131\uaca9\uc774 \ub354 \ubd84\uba85\ud574\uc9c4\ub2e4. \ub124\ud2b8\uc6cc\ud06c\ub294 \uad00\uacc4\ub97c \ub9cc\ub4dc\ub294 \uae30\uc220\uc774\uae30\ub3c4 \ud558\ub2e4. \ud328\ud0b7\uc774\ub77c\ub294 \ub9d0\uc740 \uc815\ubcf4\ub97c \uc804\uc1a1\ud560 \ub54c \uc77c\uc815\ud55c \ub2e8\uc704\ub85c \ub098\ub204\uc5b4 \ub2e4\ub8e8\ub294 \uac1c\ub150\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uae34 \ub0b4\uc6a9\uc744 \ud558\ub098\uc758 \ub369\uc5b4\ub9ac\ub85c\ub9cc \uc0dd\uac01\ud558\uc9c0 \uc54a\uace0 \uc804\ub2ec\ud560 \ub2e8\uc704\uc640 \uaddc\uce59\uc744 \uc900\ube44\ud558\ub294 \uac83\uc774\ub2e4. \uc6b0\ud3b8\uc758 \ubd09\ud22c\uc5d0 \ube57\ub300\uba74 \uc774\ud574\ub97c \ub3c4\uc6b8 \uc218 \uc788\uc9c0\ub9cc \uc2e4\uc81c \ucef4\ud4e8\ud130\uc758 \ud1b5\uc2e0\uc774 \uc885\uc774 \uc6b4\ubc18\uacfc \ub611\uac19\uc740 \uc6d0\ub9ac\ub85c \uc774\ub8e8\uc5b4\uc9c4\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub824\uc6b4 \uc218\ud559\uc744 \ubab0\ub77c\ub3c4 \uc5f0\uad6c\uac00 \ud544\uc694\ud55c \uc774\uc720\ub294 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc5ec\ub7ec \uc7a5\uce58\uac00 \uc815\ubcf4\ub97c \ubcf4\ub0b4\ub824 \ud560 \ub54c \ubb34\uc5c7\uc744 \uc5b4\ub5a4 \uc21c\uc11c\uc640 \uaddc\uce59\uc73c\ub85c \ub2e4\ub8f0\uc9c0 \uc815\ud574\uc57c \ud55c\ub2e4. \uc120\uc744 \uc5f0\uacb0\ud558\ub294 \uc77c\ub9cc\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294 \ubb38\uc81c\ub2e4. \ud074\ub77c\uc778\ub85d\uc758 \ud328\ud0b7 \ub124\ud2b8\uc6cc\ud06c \uc5f0\uad6c\uac00 \ud568\uaed8 \uc18c\uac1c\ub418\ub294 \uac83\uc740 \uc7a5\ube44 \ub4a4\uc5d0 \uc774\ub7f0 \uc774\ub860\uacfc \uc124\uacc4\uc758 \uc9c8\ubb38\uc774 \uc788\uc5c8\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc624\ub298\uc740 \uc778\ud130\ub137\uc744 \uc5f4\uc5c8\ub2e4\uace0 \ub9d0\ud558\uba70 \ube0c\ub77c\uc6b0\uc800\ubd80\ud130 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \ucd08\uae30 \uc5f0\uacb0\uc758 \uc2dc\uae30\uc5d0\ub294 \ud604\uc7ac\uc758 \uc6f9 \ud658\uacbd\uc774 \uac16\ucd94\uc5b4\uc838 \uc788\uc9c0 \uc54a\uc558\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ucef4\ud4e8\ud130\uac00 \uc790\ub8cc\ub97c \uc8fc\uace0\ubc1b\ub294 \uae30\ubc18\uc758 \uc5ed\uc0ac\uc640 \uadf8 \uc704\uc5d0\uc11c \ubb38\uc11c\ub97c \uc77d\ub294 \uc6f9\uc758 \uc5ed\uc0ac\ub294 \uad6c\ubd84\ud560 \uc218 \uc788\ub2e4. \ud55c \uae30\uc220\uc774 \ub098\uc628 \ub0a0 \ubaa8\ub4e0 \uc11c\ube44\uc2a4\uac00 \ud568\uaed8 \uc0dd\uae34 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc61b \uc5f0\uad6c\uc2e4\uc744 \ubcfc \ub54c \uc624\ub298\uc758 \ud654\uba74\uc744 \uadf8\ub300\ub85c \ub367\uc50c\uc6b0\uc9c0 \uc54a\uc73c\uba74 \uc791\uc740 \uc131\ucde8\uac00 \ub2e4\ub974\uac8c \ub290\uaef4\uc9c4\ub2e4. \uc775\uc219\ud55c \uadf8\ub9bc\uc774\ub098 \uac80\uc0c9\ucc3d\uc774 \uc5c6\ub354\ub77c\ub3c4 \uc815\ubcf4\ub97c \ubcf4\ub0b4\uace0 \ubc1b\ub294 \uc77c\uc774 \uac00\ub2a5\ud574\uc9c0\uba74 \ub2e4\uc74c\uc758 \uc2e4\ud5d8\uc744 \ud560 \uc218 \uc788\uc5c8\ub2e4. \uae30\uc220\uc758 \uc2dc\uc791\uc744 \uc77d\ub294 \uc7ac\ubbf8\ub294 \uc9c0\uae08\ubcf4\ub2e4 \ubd80\uc871\ud55c \uac83\uc744 \ucc3e\ub294 \ub370\ubcf4\ub2e4, \ub2f9\uc2dc \ubb34\uc5c7\uc744 \uc0c8\ub85c \ud560 \uc218 \uc788\uc5c8\ub294\uc9c0 \uc54c\uc544\ubcf4\ub294 \ub370 \uc788\ub2e4. \uc774 \ucd08\uae30 \uc2e4\ud5d8\uacfc \uc9c0\uae08 \uc6b0\ub9ac\uac00 \uc0ac\uc6a9\ud558\ub294 \uc778\ud130\ub137 \uc0ac\uc774\uc5d0\ub294 \uc624\ub79c \uac1c\ubc1c \uacfc\uc815\uc774 \uc788\ub2e4. \uadf8 \uc0ac\uc774\ub97c \ud55c \ubc88\uc758 \uc804\uc1a1\uc73c\ub85c \uac74\ub108\ub6f0\uba74 \uc791\uc740 \uc2dc\uc791\uc774 \uc624\ud788\ub824 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ub124\ud2b8\uc6cc\ud06c\uac00 \uc810\uc810 \ub113\uc5b4\uc9c0\uae30 \uc804, \ub204\uad70\uac00\ub294 \ub2e4\ub978 \uc5f0\uad6c\uc2e4\uae4c\uc9c0 \uc2e0\ud638\uac00 \uc804\ub2ec\ub418\ub294\uc9c0 \ud655\uc778\ud558\uace0 \uc788\uc5c8\ub2e4. \uadf8\ub54c\uc758 \ucef4\ud4e8\ud130\uc640 \uc624\ub298\uc758 \ud734\ub300\uc804\ud654\ub294 \ubaa8\uc2b5\uc774 \ud06c\uac8c \ub2e4\ub974\uc9c0\ub9cc, \ub5a8\uc5b4\uc9c4 \uacf3\uc73c\ub85c \uc815\ubcf4\ub97c \ubcf4\ub0b8\ub2e4\ub294 \uc77c\uc740 \uc774\uc5b4\uc838 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \uba40\ub9ac \uc788\ub294 \uc0ac\ub78c\uc5d0\uac8c \uba54\uc2dc\uc9c0\ub97c \ubcf4\ub0b8\ub2e4\uba74 \uc7a0\uae50 \uc61b \uc5f0\uad6c\uc2e4\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc544\ub3c4 \uc88b\uaca0\ub2e4. \uc6b0\ub9ac\uac00 \uc7a5\uc18c\ub97c \uc758\uc2dd\ud558\uc9c0 \uc54a\uace0 \uac74\ub108\uac00\ub294 \uae38\ub3c4, \ucc98\uc74c\uc5d0\ub294 \ucef4\ud4e8\ud130\uac00 \ub193\uc778 \uad6c\uccb4\uc801\uc778 \uc7a5\uc18c\uc5d0\uc11c \uc2dc\uc791\ub418\uc5c8\ub2e4."}, {"id": "atlantic-cable-failures-and-connection", "title": "\ub300\uc11c\uc591 \ud574\uc800\uc804\uc120 \u2014 \uc18c\uc2dd\uc774 \ubc14\ub2e4\ubcf4\ub2e4 \ube68\ub77c\uc9c0\uae30\uae4c\uc9c0", "summary": "1858\ub144\uc758 \uc5f0\uacb0\uacfc \uace0\uc7a5, 1866\ub144\uc758 \uac1c\uc120\uc744 \ub530\ub77c \ubc14\ub2e4 \uc544\ub798 \ud1b5\uc2e0\ub9dd\uc744 \ub9cc\ub4dc\ub294 \uc5b4\ub824\uc6c0\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\uc778\ud130\ub137\uacfc \ud1b5\uc2e0", "categories": ["digital"], "url": "stories/atlantic-cable-failures-and-connection/index.html", "image": "../media/atlantic-cable-failures-and-connection.jpg", "alt": "\ucd08\uae30 \ub300\uc11c\uc591 \uc804\uc120\uc758 \ub3c4\uccb4\u00b7\uc808\uc5f0\u00b7\ubcf4\ud638\uce35\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc5ed\uc0ac \ub2e8\uba74 \uadf8\ub9bc", "text": "\ub300\uc11c\uc591 \ud574\uc800\uc804\uc120 \u2014 \uc18c\uc2dd\uc774 \ubc14\ub2e4\ubcf4\ub2e4 \ube68\ub77c\uc9c0\uae30\uae4c\uc9c0 1858\ub144\uc758 \ucd95\ud558 \uc804\ubb38\uacfc \uc2e4\ud328, \ub2e4\uc2dc \uc774\uc5b4\uc9c4 \ubc14\ub2e4\uc758 \ud1b5\uc2e0\ub9dd 1858\ub144\uc758 \uc5f0\uacb0\uacfc \uace0\uc7a5, 1866\ub144\uc758 \uac1c\uc120\uc744 \ub530\ub77c \ubc14\ub2e4 \uc544\ub798 \ud1b5\uc2e0\ub9dd\uc744 \ub9cc\ub4dc\ub294 \uc5b4\ub824\uc6c0\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc778\ud130\ub137\uacfc \ud1b5\uc2e0 \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \ubc30\uac00 \ud3b8\uc9c0\ub97c \uc2e3\uace0 \ubc14\ub2e4\ub97c \uac74\ub108\ub294 \ub3d9\uc548 \uc138\uc0c1\uc740 \uacc4\uc18d \ub2ec\ub77c\uc9c4\ub2e4. \uc591\ucabd \ud574\uc548\uc758 \uc0ac\ub78c\ub4e4\uc774 \uc804\uc2e0\uc73c\ub85c \uace7\ubc14\ub85c \uc18c\uc2dd\uc744 \uc8fc\uace0\ubc1b\uc744 \uc218 \uc788\ub2e4\uba74 \ubb34\uc5c7\uc774 \ubc14\ub014\uae4c. 19\uc138\uae30 \ub300\uc11c\uc591 \ud574\uc800\uc804\uc120 \uc0ac\uc5c5\uc740 \uadf8 \uae30\ub300\ub97c \uac70\ub300\ud55c \ubb3c\ub9ac\uc801 \uc791\uc5c5\uc73c\ub85c \ubc14\uafb8\ub824 \ud588\ub2e4. \uc804\uc2e0\uc740 \uc774\ubbf8 \uc721\uc9c0\uc5d0\uc11c \uc4f0\uc774\uace0 \uc788\uc5c8\uc9c0\ub9cc \uae4a\uc740 \ubc14\ub2e4 \uc544\ub798\ub85c \uc120\uc744 \uc787\ub294 \uc77c\uc740 \ub2e4\ub978 \ubb38\uc81c\uc600\ub2e4. 1858\ub144 \uc5f0\uacb0\uc758 \uae30\uc068 \ub4a4\uc5d0 \uace0\uc7a5\uc774 \uc654\uace0 \ub2e4\uc2dc \uc2dc\ub3c4\uac00 \uc774\uc5b4\uc84c\ub2e4. \uc2e4\ud328\uc640 \uac1c\uc120\uc758 \uacfc\uc815\uc744 \ub530\ub77c\uac00\uba74 \ud1b5\uc2e0\ub9dd\uc758 \uc5ed\uc0ac\uac00 \ubc1c\uba85\ub41c \uae30\ud638\ub9cc\ud07c\uc774\ub098 \uc7ac\ub8cc\uc640 \ubc30, \uc2e0\ub8b0\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\uc784\uc744 \uc54c \uc218 \uc788\ub2e4. \uc721\uc9c0\uc5d0\uc11c\ub294 \uc804\uc120\uc744 \uc9c0\uc9c0\ud558\uace0 \ud544\uc694\ud560 \ub54c \uc811\uadfc\ud574 \uc218\ub9ac\ud560 \uc218 \uc788\ub2e4. \ubc14\ub2e4\uc5d0\uc11c\ub294 \uc804\uc120\uc774 \ubb3c\uacfc \uc555\ub825, \uc120\uc744 \ub0b4\ub9ac\ub294 \ub3d9\uc548\uc758 \ud798\uc744 \uacac\ub38c\uc57c \ud55c\ub2e4. \uc804\uae30\uac00 \ud1b5\ud558\ub294 \uc7ac\ub8cc\ub97c \uace0\ub974\ub294 \uac83\uacfc \uadf8 \uc7ac\ub8cc\ub97c \ubc14\ub2e4 \ubc11\uc5d0 \uc624\ub798 \ub450\ub294 \uac83\uc740 \ub2e4\ub978 \uae30\uc220\uc774\uc5c8\ub2e4. \ucd08\uae30\uc758 \uc804\uc120\uc740 \ub3c4\uccb4\uc640 \uc808\uc5f0\uc7ac, \ubc14\uae65\uc744 \ubcf4\ud638\ud558\ub294 \uce35\uc774 \uacb0\ud569\ub41c \uad6c\uc870\uc600\ub2e4. \uac00\uc6b4\ub370 \uad6c\ub9ac\uc120\ub9cc\uc73c\ub85c\ub294 \uc5f0\uacb0\uc774 \uc644\uc131\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc804\ub2ec\ud560 \uc804\uae30 \uc2e0\ud638\uc640 \ubc14\uae65\uc758 \ud658\uacbd\uc744 \ub098\ub204\uc5b4\uc57c \ud588\ub2e4. \uc9c0\uae08\uc758 \ub3c5\uc790\uac00 \ud1b5\uc2e0\uc744 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc815\ubcf4\ub77c\uace0 \ub290\ub07c\ub354\ub77c\ub3c4 \uadf8 \uc815\ubcf4\uc5d0\ub294 \uacac\uace0\ud55c \ubb3c\uc9c8\uc758 \uae38\uc774 \ud544\uc694\ud588\ub2e4. \uc5c4\uccad\ub098\uac8c \uae34 \uc804\uc120\uc744 \ubc30\uc5d0 \uac10\uc544 \uc2e3\uace0 \ubc14\ub2e4\ub85c \ub0b4\ub9ac\ub294 \uc77c\uc5d0\ub294 \uc0c8\ub85c\uc6b4 \uc7a5\uce58\uc640 \uc808\ucc28\uac00 \ud544\uc694\ud588\ub2e4. \ub108\ubb34 \ud070 \ud798\uc774 \uac78\ub9ac\uba74 \ub04a\uc5b4\uc9c0\uace0 \uc791\uc5c5\uc774 \uba48\ucd98\ub2e4. \uc120\uc744 \uc2e3\ub294 \ubc29\ubc95\uacfc \ud480\uc5b4 \ub0b4\ub294 \uc18d\ub3c4, \ubc30\uc758 \uc6c0\uc9c1\uc784\uc774 \uc11c\ub85c \ub9de\uc544\uc57c \ud588\ub2e4. \ud1b5\uc2e0 \uc0ac\uc5c5\uc774\uba74\uc11c \ud574\uc591 \uacf5\ud559\uc758 \uc0ac\uc5c5\uc774\uc5c8\ub2e4. 1857\ub144\uc758 \uc2dc\ub3c4\uc5d0\uc11c\ub294 \uc804\uc120\uc774 \ub04a\uc5b4\uc84c\ub2e4. \uc774\ub4ec\ud574\uc5d0\ub3c4 \ud3ed\ud48d\uacfc \ubc18\ubcf5\ub418\ub294 \ub2e8\uc808\uc744 \uacaa\uc5c8\ub2e4. \uc2e4\ud328\ub294 \ub2e8\uc21c\ud788 \ucda9\ubd84\ud788 \uc5f4\uc2ec\ud788 \ud558\uc9c0 \uc54a\uc558\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc774\uc804\uc5d0 \uc54c\uae30 \uc5b4\ub824\uc6e0\ub358 \uc870\uac74\uc774 \uc2e4\uc81c \ubc14\ub2e4\uc5d0\uc11c \ub4dc\ub7ec\ub098\ub294 \uacfc\uc815\uc774\uc5c8\ub2e4. \ub2e4\uc2dc \uc2dc\ub3c4\ud558\ub824\uba74 \uc7a5\ube44\uc640 \ubc29\ubc95\uc744 \ubc14\uafb8\uc5b4\uc57c \ud588\ub2e4. 1858\ub144 \uc0ac\uc5c5\uc5d0\uc11c\ub294 \ubc30\ub4e4\uc774 \ubc14\ub2e4 \ud55c\uac00\uc6b4\ub370\uc5d0\uc11c \uc804\uc120\uc744 \uc774\uc5b4 \uac01\uae30 \ubc18\ub300 \ud574\uc548\uc73c\ub85c \ud5a5\ud558\ub294 \ubc29\uc2dd\ub3c4 \uc0ac\uc6a9\ud588\ub2e4. \ud55c \uc120\ubc15\uc774 \uc804 \uad6c\uac04\uc744 \ud63c\uc790 \ucc98\ub9ac\ud558\ub294 \uadf8\ub9bc\uacfc \ub2e4\ub974\ub2e4. \uc5ec\ub7ec \ubc30\uc640 \uc5ec\ub7ec \uc9d1\ub2e8\uc774 \uac19\uc740 \uc5f0\uacb0\uc744 \uc704\ud574 \uc2dc\uac04\uacfc \uc791\uc5c5\uc744 \ub9de\ucdb0\uc57c \ud588\ub2e4. \uae38\uc744 \ub9cc\ub4dc\ub294 \uacfc\uc815 \uc790\uccb4\uac00 \ud611\uc5c5\uc774\uc5c8\ub2e4. \uc5b4\ub290 \ud55c\ucabd\uc758 \uc791\uc5c5\ub9cc \uc798\ub418\uc5b4\ub3c4 \ubc18\ub300\ucabd\uc774 \uc2e4\ud328\ud558\uba74 \ud1b5\uc2e0\uc740 \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \ub9dd\uc774\ub77c\ub294 \ub9d0\uc5d0\ub294 \uc774\ub7f0 \uc0c1\ud638 \uc758\uc874\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uc644\uc131\ub41c \uc120 \ud558\ub098\ub9cc \ubcf4\uba74 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc870\uc815\uacfc \uae30\ub2e4\ub9bc\uc774 \ubc14\ub2e4 \uc704\uc5d0\uc11c \uacc4\uc18d \uc77c\uc5b4\ub0ac\ub2e4. 1858\ub144 8\uc6d4 \uc5f0\uacb0\uc774 \uc774\ub8e8\uc5b4\uc84c\uace0 \ube45\ud1a0\ub9ac\uc544 \uc5ec\uc655\uacfc \ubbf8\uad6d \ub300\ud1b5\ub839 \uc81c\uc784\uc2a4 \ubdf0\uce90\ub10c \uc0ac\uc774\uc5d0 \ucd95\ud558 \uc804\ubb38\uc774 \uc624\uac14\ub2e4. \uba40\ub9ac \ub5a8\uc5b4\uc9c4 \uc591\ucabd\uc774 \uc804\uae30\ub85c \ub9d0\uc744 \uc8fc\uace0\ubc1b\ub294 \uc7a5\uba74\uc740 \ud070 \uae30\ub300\ub97c \ub9cc\ub4e4\uc5c8\ub2e4. \uc644\uc131\ub418\uc5c8\ub2e4\ub294 \uc120\uc5b8\uc774 \uc0ac\ub78c\ub4e4\uc758 \uad00\uc2ec\uc744 \ubaa8\uc73c\uae30\uc5d0 \ucda9\ubd84\ud588\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \uc804\uc120\uc740 \uc624\ub798 \uc548\uc815\uc801\uc73c\ub85c \uc791\ub3d9\ud558\uc9c0 \ubabb\ud588\ub2e4. \uccab \uc2e0\ud638\uac00 \uc804\ub2ec\ub41c \uc0ac\uc2e4\uacfc \uc9c0\uc18d\ud574\uc11c \uc4f8 \uc218 \uc788\ub294 \ud1b5\uc2e0\ub9dd\uc774 \uc0dd\uacbc\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uac19\uc9c0 \uc54a\uc558\ub2e4. \uc774 \ucc28\uc774\ub294 \uc0c8\ub85c\uc6b4 \uae30\uc220\uc744 \ud3c9\uac00\ud560 \ub54c \uc911\uc694\ud558\ub2e4. \ud55c \ubc88\uc758 \uc778\uc0c1\uc801\uc778 \uc2dc\uc5f0\uc740 \uac00\ub2a5\uc131\uc744 \ubcf4\uc5ec \uc8fc\uc9c0\ub9cc \uc77c\uc0c1\uc801\uc778 \uc11c\ube44\uc2a4\ub294 \ub2e4\ub978 \uc218\uc900\uc758 \ubc18\ubcf5\uc744 \uc694\uad6c\ud55c\ub2e4. \uc120\uc774 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5b4\ub3c4 \ubc18\ub300\ud3b8\uc758 \uc2e0\ud638\ub97c \uc81c\ub300\ub85c \uc54c\uc544\uc57c \ud55c\ub2e4. \uae34 \uc804\uc120\uc5d0\uc11c\ub294 \uc2e0\ud638\ub97c \ubcf4\ub0b4\uace0 \uac10\uc9c0\ud558\ub294 \ubc29\ubc95 \uc5ed\uc2dc \uc911\uc694\ud574\uc84c\ub2e4. \uc70c\ub9ac\uc5c4 \ud1b0\uc2a8\uacfc \uad00\ub828\ub41c \uc218\uc2e0 \uc7a5\uce58\uc758 \uac1c\uc120\ucc98\ub7fc, \uc804\uc120 \uc790\uccb4\ub97c \ub9cc\ub4dc\ub294 \uc77c\uacfc \ub3c4\ucc29\ud55c \ubcc0\ud654\ub97c \uc77d\ub294 \uc77c\uc774 \ud568\uaed8 \ubc1c\uc804\ud588\ub2e4. \uc774 \uc810\uc5d0\uc11c \ud1b5\uc2e0\uc740 \uae38\ub9cc \ub6ab\uc73c\uba74 \ub05d\ub098\ub294 \uc0ac\uc5c5\uc774 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc744 \ubcf4\ub0c8\ub294\uc9c0 \ubd84\uac04\ud558\uace0 \uae30\ub85d\ud560 \uc218 \uc788\uc5b4\uc57c \uc815\ubcf4\uac00 \ub41c\ub2e4. \uc190\uc5d0 \uc7a1\ud788\ub294 \uad75\uc740 \uc804\uc120\uacfc \uc791\uace0 \uc12c\uc138\ud55c \uce21\uc815 \uc7a5\uce58\uac00 \uac19\uc740 \ub9dd\uc758 \uc77c\ubd80\uc600\ub2e4. \ub300\uc11c\uc591\uc744 \uac74\ub108\ub294 \uae30\uc220\uc5d0\ub294 \uac70\ub300\ud55c \uaddc\ubaa8\uc640 \ubbf8\uc138\ud55c \uac10\ub3c4\uac00 \ub3d9\uc2dc\uc5d0 \ud544\uc694\ud588\ub2e4. \ucd08\uae30 \uc5f0\uacb0\uc758 \uc2e4\ud328 \ub4a4\uc5d0\ub3c4 \uc0ac\uc5c5\uc740 \uacc4\uc18d\ub418\uc5c8\ub2e4. 1860\ub144\ub300\uc5d0 \uc0c8\ub85c\uc6b4 \uc2dc\ub3c4\uc640 \uc7a5\ube44 \uac1c\uc120\uc774 \uc774\uc5b4\uc84c\uace0 1866\ub144\uc5d0\ub294 \ub354 \uc548\uc815\uc801\uc778 \uc5f0\uacb0\uc758 \uae30\ubc18\uc774 \ub9c8\ub828\ub418\uc5c8\ub2e4. \uc9e7\uc740 \uc131\uacf5\uacfc \uc624\ub79c \uc11c\ube44\uc2a4 \uc0ac\uc774\ub97c \uc5ec\ub7ec \ucc28\ub840\uc758 \uc791\uc5c5\uc774 \uba54\uc6b4 \uac83\uc774\ub2e4. \uc804\uc120 \uc0ac\uc5c5\uc740 \ud55c \ubc88\uc758 \uc6a9\uac10\ud55c \ucd9c\ud56d\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\uc558\ub2e4. \uadf8 \uacfc\uc815\uc5d0\ub294 \ube44\uc6a9\uacfc \ud22c\uc790\uc790\uc758 \ud310\ub2e8, \uc2e4\ud328\ub97c \ubc14\ub77c\ubcf4\ub294 \uc5ec\ub860\ub3c4 \uc601\ud5a5\uc744 \uc8fc\uc5c8\ub2e4. \uc774\ubbf8 \ub3c8\uc744 \uc37c\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \ub2e4\uc74c \uc131\uacf5\uc774 \ubcf4\uc7a5\ub418\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uae30\uc220\uc744 \uace0\uce60 \uc218 \uc788\ub2e4\ub294 \uadfc\uac70\uc640 \ub2e4\uc2dc \uc790\uc6d0\uc744 \ubaa8\uc744 \uc218 \uc788\ub294 \uc2e0\ub8b0\uac00 \ud568\uaed8 \ud544\uc694\ud588\ub2e4. \ud1b5\uc2e0\uc758 \uc5ed\uc0ac\uc640 \uae08\uc735\uc758 \uc2dc\uac04\uc774 \ub9cc\ub098\ub294 \uc9c0\uc810\uc774\ub2e4. \uc774 \uc804\uc120\uc740 \uc624\ub298\uc758 \uc778\ud130\ub137\uacfc \ub611\uac19\uc740 \uc7a5\uce58\uac00 \uc544\ub2c8\ub2e4. \uadf8\ub7ec\ub098 \uba40\ub9ac \uc788\ub294 \uc0ac\ub78c\uc744 \uc5f0\uacb0\ud558\ub824\uba74 \ubc14\ub2e4\ub97c \uac74\ub108\ub294 \ubb3c\ub9ac\uc801 \uae30\ubc18\uacfc \uc720\uc9c0\uc758 \uccb4\uacc4\uac00 \ud544\uc694\ud558\ub2e4\ub294 \uc810\uc740 \uc774\uc5b4\uc9c4\ub2e4. \ud654\uba74\uc5d0\uc11c \uc21c\uc2dd\uac04\uc5d0 \uc624\uac00\ub294 \uc815\ubcf4 \ub4a4\uc5d0\ub3c4 \uc124\uce58\ud558\uace0 \uc810\uac80\ud560 \uc2dc\uc124\uc774 \uc788\ub2e4. \ucd08\uae30 \uc804\uc120\uc758 \uad6c\ud0c0\ud398\ub974\uce74\ub77c\ub294 \uc808\uc5f0\uc7ac\uc640 \ubc14\uae65\uc758 \uae08\uc18d \ubcf4\ud638\uce35\uc744 \uad6c\ubd84\ud574 \ubcf4\ub294 \uac83\ub3c4 \uc88b\ub2e4. \uc548\ucabd\uc740 \uc804\uae30 \uc2e0\ud638\ub97c \uc804\ub2ec\ud558\uace0 \ub2e4\ub978 \uce35\uc740 \uadf8\uac83\uc744 \ud658\uacbd\uc5d0\uc11c \uc9c0\ud0a8\ub2e4. \ud558\ub098\uc758 \uc120\uc774\ub77c\uace0 \ubd80\ub974\uc9c0\ub9cc \uc2e4\uc81c\ub85c\ub294 \uc11c\ub85c \ub2e4\ub978 \uc5ed\ud560\uc744 \ud558\ub294 \uc7ac\ub8cc\uac00 \uacb9\uce5c \ubb3c\uac74\uc774\uc5c8\ub2e4. \ub300\uc11c\uc591 \ud574\uc800\uc804\uc120\uc758 \uc774\uc57c\uae30\ub294 \uc5f0\uacb0\uc744 \ud55c\uc21c\uac04\uc758 \uae30\uc801\uc5d0\uc11c \uae34 \uc6b4\uc601\uc758 \ubb38\uc81c\ub85c \ubc14\uafb8\uc5b4 \ubcf4\uac8c \ud55c\ub2e4. \uc18c\uc2dd\uc744 \ubcf4\ub0b4\ub294 \uae30\ud638\uc640 \uadf8\uac83\uc744 \uc804\ub2ec\ud558\ub294 \uc7ac\ub8cc, \uc2e4\ud328 \ub4a4\uc758 \uc218\ub9ac\uac00 \ud568\uaed8 \uc788\uc5c8\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc815\ubcf4\uc758 \uc18d\ub3c4\ub97c \uc774\ud574\ud558\ub824\uba74 \uadf8 \uc544\ub798 \ub193\uc778 \ubb34\uac70\uc6b4 \uc120\uc758 \uc5ed\uc0ac\ub97c \uc77d\ub294 \uc77c\ub3c4 \ud544\uc694\ud558\ub2e4."}, {"id": "babbage-jacquard-cards-and-calculation", "title": "\ubc30\ube44\uc9c0 \u2014 \ubca0\ud2c0\uc758 \uce74\ub4dc\uc5d0\uc11c \uacc4\uc0b0\uc758 \uc21c\uc11c\ub97c \ubcf4\ub2e4", "summary": "\ubc30\ube44\uc9c0\uc758 1864\ub144 \ud68c\uace0\ub85d\uc5d0\uc11c \uc790\uce74\ub4dc \uc9c1\uae30\uc758 \uce74\ub4dc\uc640 \ud574\uc11d\uae30\uad00 \uad6c\uc0c1\uc744 \uc77d\uace0 \ucc28\ubd84\uae30\uad00 \uc2e4\uc81c \ub3c4\ud310\uacfc \uad6c\ubcc4\ud569\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\ucef4\ud4e8\ud130\uc758 \uc5ed\uc0ac", "categories": ["digital"], "url": "stories/babbage-jacquard-cards-and-calculation/index.html", "image": "../media/babbage-jacquard-cards-and-calculation.jpg", "alt": "\ubc30\ube44\uc9c0\uc758 1864\ub144 \ud68c\uace0\ub85d \uad8c\ub450\uc5d0 \uc2e4\ub9b0 \ucc28\ubd84\uae30\uad00 1\ud638 \uc77c\ubd80\uc758 \ubaa9\ud310 \ub3c4\ud310", "text": "\ubc30\ube44\uc9c0 \u2014 \ubca0\ud2c0\uc758 \uce74\ub4dc\uc5d0\uc11c \uacc4\uc0b0\uc758 \uc21c\uc11c\ub97c \ubcf4\ub2e4 \ubb34\ub2ac\ub97c \uc9dc\ub294 \uc885\uc774\uc640 \uae30\uacc4\uc5d0 \uc804\ud558\ub294 \uc791\uc5c5 \ubc30\ube44\uc9c0\uc758 1864\ub144 \ud68c\uace0\ub85d\uc5d0\uc11c \uc790\uce74\ub4dc \uc9c1\uae30\uc758 \uce74\ub4dc\uc640 \ud574\uc11d\uae30\uad00 \uad6c\uc0c1\uc744 \uc77d\uace0 \ucc28\ubd84\uae30\uad00 \uc2e4\uc81c \ub3c4\ud310\uacfc \uad6c\ubcc4\ud569\ub2c8\ub2e4. \ucef4\ud4e8\ud130\uc758 \uc5ed\uc0ac \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \uc815\uad50\ud55c \ucd08\uc0c1\uc744 \ubcf4\uace0 \ud310\ud654\ub77c\uace0 \uc0dd\uac01\ud588\ub2e4. \uadf8\ub7f0\ub370 \uac00\uae4c\uc774\uc11c \ubcf4\uba74 \uc120\uc774 \uc544\ub2c8\ub77c \uc2e4\ub85c \uc9e0 \ucc9c\uc774\ub2e4. \ucc30\uc2a4 \ubc30\ube44\uc9c0\ub294 \uc790\uc2e0\uc758 \uc9d1\uc5d0 \uac78\ub9b0 \uc790\uce74\ub4dc\uc758 \ucd08\uc0c1\uc774 \uc0ac\ub78c\ub4e4\uc744 \uc774\ub807\uac8c \ub180\ub77c\uac8c \ud588\ub2e4\uace0 \ud68c\uace0\ud588\ub2e4. \ubca0\ud2c0\uc774 \ub9cc\ub4e4 \uc218 \uc788\ub294 \ubb34\ub2ac\ub294 \uc0dd\uac01\ubcf4\ub2e4 \ud6e8\uc52c \ubcf5\uc7a1\ud588\ub2e4. \ubc30\ube44\uc9c0\uac00 \uadf8 \ucd08\uc0c1\uc744 \uacc4\uc0b0 \uae30\uacc4\uc758 \uc124\uba85\uacfc \uc5f0\uacb0\ud55c \uc774\uc720\ub294 \ubb34\uc5c7\uc77c\uae4c. \uc2e4\uc744 \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc77c\uc9c0 \uc54c\ub824 \uc8fc\ub294 \uce74\ub4dc\uc758 \uad6c\uc0c1\uc5d0\uc11c \uacc4\uc0b0\uc758 \uc21c\uc11c\ub97c \uae30\uacc4\uc5d0 \uc804\ub2ec\ud558\ub294 \ubc29\ubc95\uc744 \ubcf4\uc558\uae30 \ub54c\ubb38\uc774\ub2e4. \ucef4\ud4e8\ud130\uc758 \uc5ed\uc0ac\ub294 \uc22b\uc790\ub9cc\uc774 \uc544\ub2c8\ub77c \uc9c1\ubb3c\uacfc \uc885\uc774, \uae30\uacc4\uc758 \ub9cc\ub0a8\uc5d0\uc11c\ub3c4 \uc77d\uc744 \uc218 \uc788\ub2e4. \ubc30\ube44\uc9c0\ub294 1864\ub144 \ud68c\uace0\ub85d\uc5d0\uc11c \uc790\uce74\ub4dc \uc9c1\uae30\ub97c \uc124\uba85\ud55c\ub2e4. \uba3c\uc800 \ubb34\ub2ac\ub97c \uc124\uacc4\ud558\uace0 \uadf8\uac83\uc744 \uc77c\uc815\ud55c \ubc29\uc2dd\uc73c\ub85c \uad6c\uba4d \ub6ab\ub9b0 \uce74\ub4dc\uc5d0 \uc62e\uae34\ub2e4. \uce74\ub4dc\ub4e4\uc744 \uc9c1\uae30\uc5d0 \uac78\uba74 \uadf8 \ubc30\uc5f4\uc5d0 \ub530\ub77c \ubb34\ub2ac\ub97c \uc9e4 \uc218 \uc788\ub2e4\ub294 \uc124\uba85\uc774\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \uadf8\ub9bc\uc744 \uae30\uacc4\uac00 \ub530\ub97c \uc218 \uc788\ub294 \ub2e4\ub978 \ud615\uc2dd\uc73c\ub85c \ubc14\uafb8\ub294 \uacfc\uc815\uc774\uc5c8\ub2e4. \uc774\uac83\uc740 \uc624\ub298\uc758 \uc804\uc790\uc2dd \ud30c\uc77c\uacfc \uac19\uc740 \ubb3c\uac74\uc740 \uc544\ub2c8\ub2e4. \ub450\uaebc\uc6b4 \uc885\uc774\uc5d0 \uad6c\uba4d\uc744 \ub0b4\uace0 \uae30\uacc4\uc640 \ub9de\ubb3c\ub9ac\uac8c \ud558\ub294 \ubb3c\ub9ac\uc801 \uc791\uc5c5\uc774\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \ubb34\uc5c7\uc744 \ud560\uc9c0\uc5d0 \uad00\ud55c \uc815\ubcf4\ub97c \uc7a5\uce58\uc640 \ubcc4\ub3c4\ub85c \uc900\ube44\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc740 \uc911\uc694\ud558\ub2e4. \uae30\uacc4\uc758 \ubab8\uccb4\uc640 \uc791\uc5c5\uc744 \uc9c0\uc2dc\ud558\ub294 \ubc30\uc5f4\uc744 \ub098\ub204\uc5b4 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ubc30\ube44\uc9c0\ub294 \uac19\uc740 \uce74\ub4dc\ub97c \uc4f0\uba74\uc11c \uc2e4\uc758 \uc0c9\uc744 \ub2ec\ub9ac\ud558\ub294 \uc608\ub97c \ub4e0\ub2e4. \ubaa8\ub4e0 \uc2e4\uc774 \ud55c \uc0c9\uc774\uac70\ub098 \uc5ec\ub7ec \uc0c9\uc774\uc5b4\ub3c4 \ubb34\ub2ac\uc758 \ud615\ud0dc\ub294 \uc720\uc9c0\ub420 \uc218 \uc788\ub2e4\ub294 \uac83\uc774\ub2e4. \uc791\uc5c5\uc758 \uaddc\uce59\uacfc \uadf8 \uaddc\uce59\uc5d0 \ub123\ub294 \uc7ac\ub8cc\uc758 \uad6c\uccb4\uc801\uc778 \uac12\uc774 \ub2e4\ub978 \uc885\ub958\uc758 \uc815\ubcf4\ub85c \ubcf4\uc778\ub2e4. \uc774 \ube44\uc720\ub294 \uacc4\uc0b0\uc73c\ub85c \uc774\uc5b4\uc9c4\ub2e4. \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \uc218\ub97c \ucc98\ub9ac\ud560\uc9c0 \uc815\ud55c \ub4a4, \uc2e4\uc81c\ub85c \ub123\ub294 \uc218\ub97c \ubc14\uafb8\uc5b4 \ub2e4\uc2dc \uacc4\uc0b0\ud560 \uc218 \uc788\ub2e4. \ud55c \uac00\uc9c0 \uc22b\uc790\uc758 \uacb0\uacfc\ub9cc \ub9cc\ub4dc\ub294 \uc7a5\uce58\ubcf4\ub2e4 \uc5ec\ub7ec \uac12\uc744 \uac19\uc740 \uc808\ucc28\ub85c \ub2e4\ub8e8\ub294 \uad6c\uc0c1\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ubca0\ud2c0\uc758 \ubb34\ub2ac\uac00 \uc218\ud559\uc801 \uc791\uc5c5\uc744 \uc124\uba85\ud558\ub294 \ub3c4\uad6c\uac00 \ub418\uc5c8\ub2e4. \ubc30\ube44\uc9c0\ub294 \ud574\uc11d\uae30\uad00\uc744 \uc124\uba85\ud558\uba70 \uc218\uc640 \uc911\uac04 \uacb0\uacfc\ub97c \ub450\ub294 \uacf3, \uc2e4\uc81c\ub85c \uc5f0\uc0b0\ud558\ub294 \uacf3\uc744 \ub098\ub204\uc5c8\ub2e4. \ud68c\uace0\ub85d\uc5d0\uc11c\ub294 \uc774\ub97c \uc800\uc7a5\uc18c\uc640 \ubc00\uc774\ub77c\uace0 \ubd88\ub800\ub2e4. \ub3c5\uc790\ub294 \ubcf5\uc7a1\ud55c \uae30\uacc4 \uc124\uacc4\ubcf4\ub2e4 \uc22b\uc790\ub97c \ubcf4\uad00\ud558\ub294 \uc77c\uacfc \uadf8 \uc22b\uc790\ub85c \uc791\uc5c5\ud558\ub294 \uc77c\uc774 \uad6c\ubd84\ub41c\ub2e4\ub294 \uc810\uc744 \uc774\ud574\ud558\uba74 \ub41c\ub2e4. \uac19\uc740 \uc22b\uc790\ub4e4\uc744 \uac16\uace0 \uc788\uc5b4\ub3c4 \ub354\ud560\uc9c0 \uacf1\ud560\uc9c0, \uc5b4\ub5a4 \uc21c\uc11c\ub85c \ucc98\ub9ac\ud560\uc9c0\uc5d0 \ub530\ub77c \uacb0\uacfc\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uadf8\ub798\uc11c \uc218\ub97c \ub193\ub294 \uc790\ub9ac\ub9cc\ud07c \ubb34\uc5c7\uc744 \ud558\ub77c\ub294 \uc9c0\uc2dc\ub3c4 \ud544\uc694\ud588\ub2e4. \uacc4\uc0b0 \uae30\uacc4\uc758 \uad6c\uc0c1\uc740 \ud1b1\ub2c8\ubc14\ud034\ub97c \ub9ce\uc774 \ub2ec\uba74 \ub05d\ub098\ub294 \ubb38\uc81c\uac00 \uc544\ub2c8\uc5c8\ub2e4. \ud68c\uace0\ub85d\uc5d0\ub294 \uc5f0\uc0b0\uc744 \uc9c0\uc2dc\ud558\ub294 \uce74\ub4dc\uc640 \ub2e4\ub8f0 \ubcc0\uc218\ub97c \uc9c0\uc815\ud558\ub294 \uce74\ub4dc\uac00 \uad6c\ubd84\ub418\uc5b4 \uc788\ub2e4. \uc5b4\ub5a4 \uacc4\uc0b0\uc744 \ud560\uc9c0\uc640 \uc5b4\ub290 \uac12\uc744 \uac00\uc838\uc62c\uc9c0\ub97c \uae30\uacc4\uc5d0 \uc804\ub2ec\ud558\ub824 \ud55c \uac83\uc774\ub2e4. \ud558\ub098\uc758 \uc7a5\uce58\uac00 \ub2e4\ub978 \uacc4\uc0b0\uc744 \uc218\ud589\ud558\ub824\uba74 \uc774\ub7f0 \uc21c\uc11c\uc640 \ub300\uc0c1\uc758 \uc815\ubcf4\uac00 \ubc14\ub014 \uc218 \uc788\uc5b4\uc57c \ud588\ub2e4. \uc5ec\uae30\uc11c\ub294 \uce74\ub4dc\uc758 \uc815\ud655\ud55c \uc7a5\uc218\ub098 \uad6c\uba4d \ubc30\uc5f4\uc744 \uc678\uc6b8 \ud544\uc694\uac00 \uc5c6\ub2e4. \uacc4\uc0b0\uc740 \uc22b\uc790\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\uace0 \uc808\ucc28\ub3c4 \ud544\uc694\ud558\ub2e4\ub294 \uc810\uc774 \ud575\uc2ec\uc774\ub2e4. \uc9c1\ubb3c\uc5d0\uc11c \ubb34\ub2ac\ub97c \uc9c0\uc2dc\ud558\ub358 \uce74\ub4dc\uc758 \uc0dd\uac01\uc774 \uc218\ud559\uc758 \uc791\uc5c5\uc744 \uc9c0\uc2dc\ud558\ub294 \uad6c\uc0c1\uacfc \ub9cc\ub0ac\ub2e4. \ubc30\ube44\uc9c0\ub294 \uc54c\ubc84\ud2b8 \uacf5\uc5d0\uac8c \uacc4\uc0b0 \uae30\uacc4\ub97c \uc124\uba85\ud558\uae30 \uc804\uc5d0 \uc790\uce74\ub4dc\uc758 \uc9e0 \ucd08\uc0c1\uc744 \ubcf4\uc5ec \uc8fc\uc5c8\ub2e4\uace0 \uc37c\ub2e4. \ud568\uaed8 \uc788\ub358 \uc0ac\ub78c\uc774 \ud310\ud654\ub85c \uc5ec\uae38 \ub9cc\ud07c \uc815\uad50\ud588\uc9c0\ub9cc, \uc54c\ubc84\ud2b8 \uacf5\uc740 \ub2e4\ub978 \uacf3\uc5d0\uc11c \ubcf8 \uc801\uc774 \uc788\uc5b4 \uc2e4\ub85c \uc9e0 \uac83\uc784\uc744 \uc54c\uc544\ubcf4\uc558\ub2e4\uace0 \ud68c\uace0\ud55c\ub2e4. \uc774 \uc77c\ud654\ub294 \ubc30\ube44\uc9c0\uac00 \uc4f4 \uc790\uc2e0\uc758 \uae30\uc5b5\uc774\ub77c\ub294 \uc131\uaca9\uc744 \uac00\uc9c4\ub2e4. \ub300\ud654\uc758 \uc815\ud655\ud55c \ub9d0\ud22c\uc640 \ud604\uc7a5\uc758 \ud45c\uc815\uae4c\uc9c0 \uc6b0\ub9ac\uac00 \ubcf5\uc6d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uadf8\uac00 \uc9c1\ubb3c\uc758 \uc815\uad50\ud568\uc744 \uc124\uba85\uc758 \ucd9c\ubc1c\uc810\uc73c\ub85c \uc0bc\uc558\ub2e4\ub294 \uc810\uc740 \ubd84\uba85\ud558\ub2e4. \ub0af\uc120 \uacc4\uc0b0 \uae30\uacc4\ub97c \uc774\ud574\uc2dc\ud0a4\uae30 \uc704\ud574 \uc774\ubbf8 \uc874\uc7ac\ud558\ub294 \ub2e4\ub978 \uae30\uc220\uc744 \uac00\uc838\uc628 \uac83\uc774\ub2e4. \uc774 \uae00\uc758 \uc2e4\uc81c \uc5ed\uc0ac \ub3c4\ud310\uc740 \ubc30\ube44\uc9c0\uc758 \ucc45 \uc55e\uc5d0 \uc2e4\ub9b0 \ucc28\ubd84\uae30\uad00 1\ud638\uc758 \uc77c\ubd80\ubd84\uc744 \uadf8\ub9b0 \ubaa9\ud310\ub3c4\ub2e4. \uc124\uba85\uc5d0\ub294 \uc774 \ubd80\ubd84\uc774 1833\ub144\uc5d0 \uc870\ub9bd\ub418\uc5c8\uace0 \ub3c4\ud310\uc774 1853\ub144\uc5d0 \uc778\uc1c4\ub418\uc5c8\ub2e4\uace0 \uc801\ud600 \uc788\ub2e4. \uc790\uce74\ub4dc \uc9c1\uae30\ub098 \ube44\ub2e8 \ucd08\uc0c1, \ud574\uc11d\uae30\uad00\uc758 \uc644\uc131 \ubaa8\uc2b5\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uadf8\ub9bc\uc774 \uc544\ub2c8\ub2e4. \ucc28\ubd84\uae30\uad00\uacfc \ud574\uc11d\uae30\uad00\uc740 \ubc30\ube44\uc9c0\uc758 \uc11c\ub85c \ub2e4\ub978 \uacc4\uc0b0 \uae30\uacc4 \uad6c\uc0c1\uc774\ub2e4. \ube44\uc2b7\ud55c \ud1b1\ub2c8\ubc14\ud034\uc640 \uc22b\uc790 \ub54c\ubb38\uc5d0 \ubaa8\ub450 \uac19\uc740 \ubb3c\uac74\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\uc9c0\ub9cc \ubaa9\uc801\uacfc \uad6c\uc0c1\uc774 \ub2e4\ub974\ub2e4. \uc5ed\uc0ac \ub3c4\ud310\uc744 \uc0ac\uc6a9\ud558\ub294 \uc77c\uc5d0\ub294 \ubb34\uc5c7\uc744 \ubcf4\uc5ec \uc8fc\uace0 \ubb34\uc5c7\uc740 \ubcf4\uc5ec \uc8fc\uc9c0 \uc54a\ub294\uc9c0 \uc124\uba85\ud558\ub294 \uacfc\uc815\ub3c4 \ud544\uc694\ud558\ub2e4. \ubc30\ube44\uc9c0\uc758 \ud68c\uace0\ub85d\uc5d0\ub294 \ub3c4\uba74\uacfc \uc791\uc5c5\uc7a5, \uc219\ub828\ub41c \uae30\uc220\uc790\uc640 \ube44\uc6a9\uc758 \uc774\uc57c\uae30\uac00 \ub098\uc628\ub2e4. \uc544\uc774\ub514\uc5b4\ub97c \uc801\ub294 \uc77c\uacfc \ub9ce\uc740 \ubd80\ud488\uc774 \ub9de\ubb3c\ub824 \uc815\ud655\ud558\uac8c \uc791\ub3d9\ud558\ub3c4\ub85d \ub9cc\ub4dc\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uadf8\ub294 \uc0ac\ub78c\uc744 \uace0\uc6a9\ud558\uace0 \uc81c\uc791\uc744 \uc774\uc5b4 \uac00\ub294 \ub370\ub3c4 \uc5b4\ub824\uc6c0\uc744 \uacaa\uc5c8\ub2e4. \ub530\ub77c\uc11c \uce74\ub4dc\uc758 \uad6c\uc0c1\uc744 \uc774\ud574\ud588\ub2e4\uace0 \uadf8 \uc2dc\uc810\uc5d0 \ud604\ub300\uc758 \ucef4\ud4e8\ud130\uac00 \uc644\uc131\ub418\uc5b4 \ubcf4\uae09\ub418\uc5c8\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ucc45\uc5d0\ub294 \uc55e\uc73c\ub85c \ud574\uc11d\uae30\uad00\uc774 \uc874\uc7ac\ud558\uac8c \ub420 \uacbd\uc6b0\ub97c \uc124\uba85\ud558\ub294 \ubb38\uc7a5\ub3c4 \uc788\ub2e4. \uacc4\ud68d\uacfc \uad6c\ud604\uc758 \uac70\ub9ac\ub97c \uc77d\uc744 \ub54c \uae30\uc220\uc758 \uc5ed\uc0ac\uac00 \ub354 \uc2e4\uc81c\uc801\uc778 \uc791\uc5c5\uc73c\ub85c \ubcf4\uc778\ub2e4. \uc624\ub298\uc758 \ub3c5\uc790\uc5d0\uac8c \ubca0\ud2c0\uacfc \ucef4\ud4e8\ud130\ub294 \ub2e4\ub978 \ubb3c\uac74\uc774\ub2e4. \uadf8\ub7ec\ub098 \uc815\ud574\uc9c4 \uc808\ucc28\ub97c \uc678\ubd80\uc758 \uc815\ubcf4\ub85c \uc804\ub2ec\ud558\uace0 \uac19\uc740 \uc7a5\uce58\ub97c \ub2e4\ub978 \uac12\uc5d0 \ub2e4\uc2dc \uc4f0\ub824\ub294 \uc0dd\uac01\uc5d0\uc11c\ub294 \uc5f0\uacb0\uc744 \ucc3e\uc744 \uc218 \uc788\ub2e4. \uc774 \uc5f0\uacb0\uc774 \ub450 \uae30\uc220\uc758 \ubaa8\ub4e0 \uad6c\uc870\uac00 \uac19\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ubc30\ube44\uc9c0\uc758 \uae00\uc744 \uc77d\uc73c\uba74 \ucef4\ud4e8\ud130\uc0ac\ub294 \uc644\uc131\ub41c \uae30\uacc4\ub4e4\uc774 \uc904\uc9c0\uc5b4 \ub4f1\uc7a5\ud55c \ubaa9\ub85d\ubcf4\ub2e4 \ub113\uc5b4\uc9c4\ub2e4. \ubb34\ub2ac\ub97c \uc9dc\ub294 \uae30\uc220\uc744 \ubcf4\uace0 \uacc4\uc0b0\uc744 \uc124\uba85\ud558\ub824 \ud55c \uc0ac\ub78c\uc774 \uc788\uc5c8\ub2e4. \uc791\uc740 \uce74\ub4dc\uac00 \ubb34\uc5c7\uc744 \uc2dc\ud0a4\ub294\uc9c0 \ubb3b\ub294 \uc9c8\ubb38\uc740 \uc9c1\ubb3c\uc758 \uc791\uc5c5\uc7a5\uc5d0\uc11c \uc22b\uc790\uc758 \uc138\uacc4\ub85c \uac74\ub108\uac00\uba70 \uc0c8\ub85c\uc6b4 \uac00\ub2a5\uc131\uc744 \uc5f4\uc5c8\ub2e4."}, {"id": "computer-time-repeated-hour", "title": "\ucef4\ud4e8\ud130\uc758 \uc2dc\uacc4 \u2014 \uc624\uc804 1\uc2dc\uac00 \ub450 \ubc88 \uc624\ub294 \ub0a0", "summary": "\ub85c\uc2a4\uc564\uc824\ub808\uc2a4\uc758 \uacfc\uac70 \uc11c\uba38\ud0c0\uc784 \uc0ac\ub840\ub85c UTC\u00b7\uc2dc\uac04\ub300\u00b7\ud604\uc9c0 \uc2dc\uac01\uc758 \ucc28\uc774\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\ub514\uc9c0\ud138 \uc0dd\ud65c\uacfc \ubcf4\uc548", "categories": ["digital"], "url": "stories/computer-time-repeated-hour/index.html", "image": "../media/computer-time-repeated-hour.png", "alt": "\uc5ec\ud589 \uac00\ubc29\uacfc \uc77c\uc815\ud45c \uc606\uc5d0\uc11c \ud734\ub300\uc804\ud654\ub97c \uc0b4\ud53c\ub294 \uc0ac\ub78c\uc758 \uc0bd\ud654.", "text": "\ucef4\ud4e8\ud130\uc758 \uc2dc\uacc4 \u2014 \uc624\uc804 1\uc2dc\uac00 \ub450 \ubc88 \uc624\ub294 \ub0a0 \uac19\uc740 \uc21c\uac04\uacfc \uac19\uc740 \uc2dc\uac01 \ud45c\uc2dc\ub294 \ub2e4\ub97c \uc218 \uc788\ub2e4 \ub85c\uc2a4\uc564\uc824\ub808\uc2a4\uc758 \uacfc\uac70 \uc11c\uba38\ud0c0\uc784 \uc0ac\ub840\ub85c UTC\u00b7\uc2dc\uac04\ub300\u00b7\ud604\uc9c0 \uc2dc\uac01\uc758 \ucc28\uc774\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ub514\uc9c0\ud138 \uc0dd\ud65c\uacfc \ubcf4\uc548 \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \uae30\ub85d\uc5d0 \uc624\uc804 1\uc2dc\uac00 \ucc0d\ud600 \uc788\ub2e4. \ud55c \uc2dc\uac04 \ub4a4\uc758 \uae30\ub85d\uc5d0\ub3c4 \uc624\uc804 1\uc2dc\uac00 \ucc0d\ud600 \uc788\ub2e4. \uc2dc\uacc4\uac00 \uace0\uc7a5 \ub09c \uac83\uc77c\uae4c. \uc11c\uba38\ud0c0\uc784\uc774 \ub05d\ub098\uba70 \uc2dc\uacc4\ub97c \ub418\ub3cc\ub9ac\ub294 \uc9c0\uc5ed\uc5d0\uc11c\ub294 \uc2e4\uc81c\ub85c \uac19\uc740 \ud604\uc9c0 \uc2dc\uac01\uc774 \ub450 \ubc88 \ub098\ud0c0\ub0a0 \uc218 \uc788\ub2e4. \uc0ac\ub78c\uc5d0\uac8c\ub3c4 \ud5f7\uac08\ub9ac\ub294 \uc77c\uc740 \ucef4\ud4e8\ud130\uc5d0\uac8c\ub3c4 \ub530\ub85c \uad6c\ubd84\ud560 \ubc29\ubc95\uc774 \ud544\uc694\ud558\ub2e4. \uc22b\uc790\ub85c \uc800\uc7a5\ud558\ub2c8 \uc2dc\uac04\uc740 \uc5b8\uc81c\ub098 \ub2e8\uc21c\ud560 \uac83 \uac19\uc9c0\ub9cc, \uc5b4\ub290 \uc9c0\uc5ed\uc5d0\uc11c \uc5b4\ub5a4 \uaddc\uce59\uc73c\ub85c \ud45c\uc2dc\ud588\ub294\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \uc2dc\uacc4\uc758 \uc774\uc57c\uae30\ub294 \uc815\ud655\ud55c \uae30\uacc4\uc640 \uc0ac\ub78c\uc774 \uc815\ud55c \uc57d\uc18d\uc774 \ub9cc\ub098\ub294 \uc790\ub9ac\ub2e4. \uc11c\uc6b8\uacfc \ub85c\uc2a4\uc564\uc824\ub808\uc2a4\uc5d0 \uc788\ub294 \uc0ac\ub78c\uc774 \ub3d9\uc2dc\uc5d0 \ud1b5\ud654\ud574\ub3c4 \ud654\uba74\uc758 \uc2dc\uac01\uc740 \ub2e4\ub97c \uc218 \uc788\ub2e4. \ud55c \uc21c\uac04\uc5d0 \uc11c\ub85c \ub2e4\ub978 \uc9c0\uc5ed\uc758 \uc2dc\uacc4\uac00 \ub2e4\ub978 \uc22b\uc790\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc774\ub2e4. \uc774\uac83\uc740 \ub458 \uc911 \ud55c\ucabd\uc774 \ud2c0\ub838\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc624\ud6c4 \uc138 \uc2dc\uc5d0 \ub9cc\ub098\uc790\ub77c\ub294 \ub9d0\uc5d0\ub294 \uc5b4\ub290 \uacf3\uc758 \uc624\ud6c4 \uc138 \uc2dc\uc778\uc9c0\uac00 \ud544\uc694\ud558\ub2e4. \ucef4\ud4e8\ud130\uc758 \uc77c\uc815\uc774\ub098 \uae30\ub85d\uc5d0\uc11c\ub3c4 \ube44\uc2b7\ud55c \ubb38\uc81c\uac00 \uc0dd\uae34\ub2e4. \ub0a0\uc9dc\uc640 \uc2dc\uac01\uc758 \uc22b\uc790\ub9cc \uc788\uc73c\uba74 \ucda9\ubd84\ud574 \ubcf4\uc774\uc9c0\ub9cc, \uadf8 \uc22b\uc790\uac00 \uac00\ub9ac\ud0a4\ub294 \ub9e5\ub77d\uc774 \ube60\uc838 \uc788\uc744 \uc218 \uc788\ub2e4. UTC\ub294 \ud611\uc815\uc138\uacc4\uc2dc\ub2e4. \uc5ec\ub7ec \uc9c0\uc5ed\uc758 \uc2dc\uac01\uc744 \ube44\uad50\ud560 \ub54c \uae30\uc900\uc73c\ub85c \uc4f8 \uc218 \uc788\ub2e4. \ud604\uc9c0 \uc2dc\uac01\uc774 UTC\ubcf4\ub2e4 \uc5bc\ub9c8\ub098 \uc55e\uc11c\uac70\ub098 \ub4a4\uc11c\ub294\uc9c0\ub97c \ud568\uaed8 \uc54c\uba74 \uac19\uc740 \uc21c\uac04\uc744 \uc5f0\uacb0\ud560 \uc218 \uc788\ub2e4. \uc774 \ucc28\uc774\ub97c \uc624\ud504\uc14b\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \uc5ec\uae30\uc11c \ubaa8\ub4e0 \uc9c0\uc5ed\uc774 \uae30\uc900\uc5d0\uc11c \uba87 \uc2dc\uac04 \ucc28\uc774\uc778\uc9c0\ub9cc \uc601\uc6d0\ud788 \uace0\uc815\ud574 \ub450\uba74 \ub05d\ub098\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac19\uc740 \uc9c0\uc5ed\uc5d0\uc11c\ub3c4 \ub0a0\uc9dc\uc5d0 \ub530\ub77c \ucc28\uc774\uac00 \ubc14\ub014 \uc218 \uc788\ub2e4. \uc2dc\uac04\uc744 \ub2e4\ub8e8\ub294 \ud504\ub85c\uadf8\ub7a8\uc740 \uc22b\uc790 \ud558\ub098\ubfd0 \uc544\ub2c8\ub77c \uadf8 \ubcc0\ud654\uc758 \uaddc\uce59\ub3c4 \uace0\ub824\ud574\uc57c \ud55c\ub2e4. \ud30c\uc774\uc36c \uacf5\uc2dd \ubb38\uc11c\ub294 2020\ub144 \ub85c\uc2a4\uc564\uc824\ub808\uc2a4\uc758 \uc608\ub97c \ubcf4\uc5ec \uc900\ub2e4. 10\uc6d4 31\uc77c\uc5d0\ub294 UTC\ubcf4\ub2e4 7\uc2dc\uac04 \ub2a6\ub294 \uc2dc\uac01\uc744 \uc4f0\ub2e4\uac00, 11\uc6d4 1\uc77c\uc5d0\ub294 \uc11c\uba38\ud0c0\uc784\uc774 \ub05d\ub098\uba70 8\uc2dc\uac04 \ub2a6\ub294 \uc2dc\uac01\uc73c\ub85c \ubc14\ub010\ub2e4. \uc774\ub294 \uacfc\uac70\uc758 \uad6c\uccb4\uc801\uc778 \uc0ac\ub840\uc774\uc9c0 \uc62c\ud574\uc758 \uc77c\uc815 \uc548\ub0b4\uac00 \uc544\ub2c8\ub2e4. \ubc14\ub85c \uadf8 \uc804\ud658 \ub54c\ubb38\uc5d0 \ud558\ub8e8 \uc911 \uc77c\ubd80 \uc2dc\uac01\uc774 \ub2e4\uc2dc \ub098\ud0c0\ub09c\ub2e4. \ub2e8\uc21c\ud788 \ub0a0\uc9dc\uc5d0 24\uc2dc\uac04\uc744 \ub354\ud558\ub294 \uc77c\uacfc \ud604\uc9c0 \ub2ec\ub825\uc5d0\uc11c \ub2e4\uc74c \ub0a0 \uac19\uc740 \uc2dc\uac01\uc744 \ucc3e\ub294 \uc77c\uc774 \ud56d\uc0c1 \uac19\uc740 \uacb0\uacfc\uac00 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc775\uc219\ud55c \ud558\ub8e8\ub77c\ub294 \ub9d0\uc5d0\ub3c4 \uc5b4\ub5a4 \uae30\uc900\uc73c\ub85c \uacc4\uc0b0\ud588\ub294\uc9c0\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \uc774 \uc0ac\ub840\uc5d0\uc11c 2020\ub144 11\uc6d4 1\uc77c \uc624\uc804 1\uc2dc\ub294 \uc804\ud658 \uc804\uacfc \ud6c4\uc5d0 \uac01\uac01 \uc874\uc7ac\ud55c\ub2e4. \ud558\ub098\ub294 UTC\ubcf4\ub2e4 7\uc2dc\uac04 \ub2a6\uace0 \ub2e4\ub978 \ud558\ub098\ub294 8\uc2dc\uac04 \ub2a6\ub2e4. \uc2dc\uacc4\uc758 \uc22b\uc790\ub294 \uac19\uc9c0\ub9cc \uac00\ub9ac\ud0a4\ub294 \uc21c\uac04\uc740 \ud55c \uc2dc\uac04 \ub2e4\ub974\ub2e4. \uacf5\uc2dd \ubb38\uc11c\ub294 \uac19\uc740 \ud604\uc9c0 \uc2dc\uac01\uc758 \uc55e\uc120 \uacbd\uc6b0\uc640 \ub098\uc911 \uacbd\uc6b0\ub97c \uad6c\ubd84\ud558\ub294 \ubc29\ubc95\uc744 \uc124\uba85\ud55c\ub2e4. \ub3c5\uc790\uac00 \ud504\ub85c\uadf8\ub7a8\uc758 \uc635\uc158\uc744 \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uac19\uc740 \ud45c\uae30\ub9cc\uc73c\ub85c\ub294 \ud55c \uc21c\uac04\uc744 \ud655\uc815\ud558\uc9c0 \ubabb\ud558\ub294 \ub54c\uac00 \uc788\uc5b4\uc11c \ucd94\uac00 \uc815\ubcf4\uac00 \ud544\uc694\ud558\ub2e4\ub294 \uc810\uc744 \uc54c\uba74 \ub41c\ub2e4. \uc2dc\uac04\ub300 \ub370\uc774\ud130\ub294 \uc5b4\ub290 \uc9c0\uc5ed\uc774 \uc5b8\uc81c \uc5b4\ub5a4 \uc2dc\uac01 \uaddc\uce59\uc744 \uc37c\ub294\uc9c0 \ub2e4\ub8ec\ub2e4. \ud30c\uc774\uc36c\uc758 zoneinfo\ub294 IANA \uc2dc\uac04\ub300 \ub370\uc774\ud130\ubca0\uc774\uc2a4\ub97c \uc774\uc6a9\ud55c\ub2e4. \ub85c\uc2a4\uc564\uc824\ub808\uc2a4\ub77c\ub294 \uc9c0\uc5ed\uc744 \uc120\ud0dd\ud558\ub294 \uac83\uacfc \ubb34\uc870\uac74 UTC\ubcf4\ub2e4 8\uc2dc\uac04 \ub2a6\ub2e4\uace0 \uc815\ud558\ub294 \uac83\uc740 \uac19\uc740 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uc55e\uc758 \uc0ac\ub840\uc5d0\uc11c \ubcf4\uc558\ub4ef \uac19\uc740 \uc9c0\uc5ed\uc758 \ucc28\uc774\uac00 \uc2dc\uae30\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c8 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ud504\ub85c\uadf8\ub7a8\uc774 \uc9c0\uc5ed\uc758 \uc774\ub984\uc744 \ub2e4\ub8ec\ub2e4\ub294 \uac83\uc740 \uc9c0\uba85 \ud558\ub098\ub97c \uc7a5\uc2dd\uc73c\ub85c \ubd99\uc774\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ub0a0\uc9dc\uc640 \uc5f0\uacb0\ub41c \uaddc\uce59\uc744 \ucc3e\ub294 \uc77c\uc5d0 \uac00\uae5d\ub2e4. \ud45c\uc2dc\ud560 \uc774\ub984\uacfc \uacc4\uc0b0\ud560 \uc870\uac74\uc774 \ud568\uaed8 \uc788\ub2e4. \uc774\ubbf8 \uc77c\uc5b4\ub09c \uc0ac\uac74\uc758 \uc21c\uc11c\ub97c \ub0a8\uae30\ub294 \uc77c\uacfc \ub9e4\uc8fc \ud604\uc9c0\uc758 \uac19\uc740 \uc2dc\uac01\uc5d0 \ub9cc\ub098\ub294 \uc57d\uc18d\uc744 \uc815\ud558\ub294 \uc77c\uc740 \ubaa9\uc801\uc774 \ub2e4\ub974\ub2e4. \uc804\uc790\ub294 \uc5b4\ub5a4 \uc21c\uac04\uc774\uc5c8\ub294\uc9c0\uac00 \uc911\uc694\ud558\uace0 \ud6c4\uc790\ub294 \uc9c0\uc5ed\uc758 \uc0dd\ud65c \uc2dc\uac01\uc744 \uc720\uc9c0\ud558\ub294 \uac83\uc774 \uc911\uc694\ud560 \uc218 \uc788\ub2e4. \ub530\ub77c\uc11c \ubaa8\ub4e0 \uc2dc\uac04\uc744 \ud55c \ubc29\uc2dd\uc73c\ub85c\ub9cc \uc800\uc7a5\ud558\uba74 \ubaa8\ub4e0 \ubb38\uc81c\uac00 \ud574\uacb0\ub41c\ub2e4\ub294 \uacb0\ub860\uc740 \ud544\uc694\ud558\uc9c0 \uc54a\ub2e4. \ud504\ub85c\uadf8\ub7a8\uc740 \ubb34\uc5c7\uc744 \uae30\ub85d\ud558\uace0 \uc5b4\ub5a4 \uc57d\uc18d\uc744 \uc720\uc9c0\ud560\uc9c0\uc5d0 \ub9de\ucd94\uc5b4 \ud544\uc694\ud55c \uc815\ubcf4\ub97c \uac16\ucd94\uc5b4\uc57c \ud55c\ub2e4. \uc774 \uad6c\ubd84\uc740 \ucf54\ub4dc\ubcf4\ub2e4 \uc11c\ube44\uc2a4\uac00 \ubb34\uc5c7\uc744 \ub73b\ud558\ub824\ub294\uc9c0\uc758 \ubb38\uc81c\uc5d0\uc11c \uc2dc\uc791\ud55c\ub2e4. \uc5b4\ub5a4 \uae30\ub85d\uc5d0\uc11c \uc624\uc804 1\uc2dc\ub77c\ub294 \ubd80\ubd84\ub9cc \ub530\ub85c \uc62e\uae30\uba74 \uc6d0\ub798 \ubd99\uc5b4 \uc788\ub358 \ub0a0\uc9dc\uc640 \uc9c0\uc5ed \uc815\ubcf4\uac00 \uc0ac\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ub3c5\uc790\ub294 \ub2e4\ub978 \uc21c\uac04\uc744 \uac19\uc740 \uac83\uc73c\ub85c \uc77d\uac70\ub098, \uac19\uc740 \uc0ac\uac74\uc744 \uc11c\ub85c \ub2e4\ub978 \uac83\uc73c\ub85c \ubcfc \uc218 \uc788\ub2e4. \uc2dc\uac04 \ud45c\uc2dc\ub3c4 \ucd9c\ucc98\uc758 \uc77c\ubd80\ub77c\ub294 \uc810\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc774 \uc6d0\uace0\uc758 \ub450 \uc624\uc804 1\uc2dc\ub294 \uacf5\uc2dd \ubb38\uc11c\uc758 \uacfc\uac70 \uc608\ub97c \ubcc4\ub3c4\ub85c \uc7ac\ud604\ud574 \ud655\uc778\ud588\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uc608\ub97c \ubaa8\ub4e0 \ub098\ub77c\uc758 \ud604\uc7ac \uaddc\uce59\uc73c\ub85c \ud655\ub300\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc9c0\uc5ed\uacfc \ub0a0\uc9dc\ub97c \ud568\uaed8 \ubcf4\ub294 \uac04\ub2e8\ud55c \uc2b5\uad00\uc774 \uc2dc\uac04\uc744 \uc774\ud574\ud558\ub294 \ub370 \uc911\uc694\ud55c \uc774\uc720\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc5ec\ud589 \uc77c\uc815\uc744 \uc0dd\uac01\ud558\ub294 \uc0ac\ub78c\uc758 \ubd84\uc704\uae30\ub97c \ud45c\ud604\ud588\ub2e4. \ud2b9\uc815 \ud56d\uacf5\uad8c\uc774\ub098 \uc2e4\uc81c \uc2dc\uac01 \ucc28\uc774\ub97c \ube44\uad50\ud55c \ub3c4\ud45c\ub294 \uc544\ub2c8\ub2e4. \uadf8\ub9bc \uc18d\uc758 \ubb3c\uac74\uc774 \uc774 \uae00\uc758 \uacc4\uc0b0 \uacb0\uacfc\ub97c \uc99d\uba85\ud558\ub294 \uc790\ub8cc\ub3c4 \uc544\ub2c8\ub2e4. \ucef4\ud4e8\ud130\ub294 \uc2dc\uac01\uc744 \uc815\ud655\ud558\uac8c \uacc4\uc0b0\ud560 \uc218 \uc788\uc9c0\ub9cc \ubb34\uc5c7\uc744 \uac19\uc740 \uc2dc\uac04\uc774\ub77c\uace0 \ubd80\ub97c\uc9c0\uc5d0 \uad00\ud55c \uc57d\uc18d\uae4c\uc9c0 \uc800\uc808\ub85c \uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc21c\uac04\uacfc \ud604\uc9c0 \ud45c\uc2dc, \ub0a0\uc9dc\uc640 \uc9c0\uc5ed\uc758 \uaddc\uce59\uc744 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ub450 \ubc88 \uc624\ub294 \uc624\uc804 1\uc2dc\ub294 \ub0af\uc120 \uc624\ub958\ubcf4\ub2e4, \uc77c\uc0c1\uc758 \uc2dc\uacc4 \ub4a4\uc5d0 \uc788\ub294 \uc5ec\ub7ec \uc57d\uc18d\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc7ac\ubbf8\uc788\ub294 \uc0ac\ub840\ub2e4."}, {"id": "cookies-browser-memory", "title": "\ucfe0\ud0a4 \u2014 \uc6f9\uc0ac\uc774\ud2b8\ub294 \ub0b4\uac00 \uc654\ub358 \uac83\uc744 \uc5b4\ub5bb\uac8c \uae30\uc5b5\ud560\uae4c", "summary": "\ub85c\uadf8\uc778\uacfc \uc5b8\uc5b4 \uc124\uc815\uc744 \uc774\uc5b4 \uc8fc\ub294 \ucfe0\ud0a4\uc758 \uc5ed\ud560\uacfc \uc800\uc7a5\u00b7\ucd94\uc801\uc758 \ucc28\uc774\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\ub514\uc9c0\ud138 \uc0dd\ud65c\uacfc \ubcf4\uc548", "categories": ["digital"], "url": "stories/cookies-browser-memory/index.html", "image": "../media/cookies-browser-memory.png", "alt": "\ub178\ud2b8\uc640 \ub178\ud2b8\ubd81\uc774 \uc788\ub294 \uc775\uc219\ud55c \ucc45\uc0c1\uc73c\ub85c \ub3cc\uc544\uc624\ub294 \uc0ac\ub78c\uc758 AI \ubd84\uc704\uae30 \uc7a5\uba74.", "text": "\ucfe0\ud0a4 \u2014 \uc6f9\uc0ac\uc774\ud2b8\ub294 \ub0b4\uac00 \uc654\ub358 \uac83\uc744 \uc5b4\ub5bb\uac8c \uae30\uc5b5\ud560\uae4c \uc791\uc740 \uba54\ubaa8\uac00 \ud3b8\ub9ac\ud568\uacfc \ucd94\uc801\uc758 \uc774\uc57c\uae30\ub97c \ud568\uaed8 \ub9cc\ub4dc\ub294 \uc774\uc720 \ub85c\uadf8\uc778\uacfc \uc5b8\uc5b4 \uc124\uc815\uc744 \uc774\uc5b4 \uc8fc\ub294 \ucfe0\ud0a4\uc758 \uc5ed\ud560\uacfc \uc800\uc7a5\u00b7\ucd94\uc801\uc758 \ucc28\uc774\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ub514\uc9c0\ud138 \uc0dd\ud65c\uacfc \ubcf4\uc548 \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \uc5b4\uc81c \ud55c\uad6d\uc5b4\ub85c \ubc14\uafb8\uc5b4 \ub454 \uc0ac\uc774\ud2b8\ub97c \uc624\ub298 \ub2e4\uc2dc \uc5f4\uc5c8\ub354\ub2c8 \uc5ec\uc804\ud788 \ud55c\uad6d\uc5b4\ub2e4. \uc7a5\ubc14\uad6c\ub2c8\uc5d0 \ub123\uc5b4 \ub454 \ubb3c\uac74\uc774 \ub2e4\uc74c \ud398\uc774\uc9c0\uc5d0\uc11c\ub3c4 \ub0a8\uc544 \uc788\uae30\ub3c4 \ud55c\ub2e4. \ud654\uba74\uc744 \uc0c8\ub85c \ubc1b\ub294\ub370\ub3c4 \uc0ac\uc774\ud2b8\ub294 \uc5b4\ub5bb\uac8c \uc6b0\ub9ac\uac00 \ud558\ub358 \uc77c\uc744 \uc774\uc5b4 \uc8fc\ub294 \uac78\uae4c. \uc774\ub7f4 \ub54c \uc4f0\uc774\ub294 \ubc29\ubc95 \uac00\uc6b4\ub370 \ud558\ub098\uac00 \ucfe0\ud0a4\ub2e4. \uba39\ub294 \uacfc\uc790\ub294 \uc544\ub2c8\uace0 \ube0c\ub77c\uc6b0\uc800\uc5d0 \uc800\uc7a5\ud558\ub294 \uc791\uc740 \ub370\uc774\ud130\ub2e4. \uc0ac\uc774\ud2b8\uc640 \ube0c\ub77c\uc6b0\uc800\uac00 \uc774 \uc815\ubcf4\ub97c \uc8fc\uace0\ubc1b\uc73c\uba70 \uc55e\uc120 \ubc29\ubb38\uc774\ub098 \uc0c1\ud0dc\ub97c \uc774\uc5b4 \uac08 \uc218 \uc788\ub2e4. \uc791\uc740 \uae30\uc5b5\uc774 \uc5b4\ub5a4 \ud3b8\ub9ac\ud568\uc744 \ub9cc\ub4e4\uace0 \ubb34\uc5c7\uae4c\uc9c0 \ub73b\ud558\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc6f9\uc5d0\uc11c \uc4f0\ub294 HTTP\ub294 \uae30\ubcf8\uc801\uc73c\ub85c \uc774\uc804 \uc694\uccad\uc758 \uc0c1\ud0dc\ub97c \uc2a4\uc2a4\ub85c \uae30\uc5b5\ud558\uc9c0 \uc54a\ub294\ub2e4. \uccab \ud398\uc774\uc9c0\ub97c \ubc1b\uc558\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ub2e4\uc74c \ud398\uc774\uc9c0 \uc694\uccad\uc774 \uc790\ub3d9\uc73c\ub85c \uac19\uc740 \ub85c\uadf8\uc778 \uc0c1\ud0dc\uac00 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc11c\ube44\uc2a4\uac00 \uc774\ub97c \uc774\uc5b4 \uc8fc\ub294 \ubc29\ubc95\uc744 \ub530\ub85c \ub9c8\ub828\ud574\uc57c \ud55c\ub2e4. \uac00\uac8c\uc5d0\uc11c \uc8fc\ubb38\uc11c\ub97c \uc5ec\ub7ec \uc7a5 \ub530\ub85c \ubc1b\ub294 \uc0c1\ud669\uc744 \uc0dd\uac01\ud558\uba74 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \uac19\uc740 \uc190\ub2d8\uc758 \uc8fc\ubb38\uc778\uc9c0 \uc54c\uc544\ubcfc \ud45c\uc2dc\uac00 \uc788\uc73c\uba74 \uc55e\uc758 \uc8fc\ubb38\uacfc \uc5f0\uacb0\ud560 \uc218 \uc788\ub2e4. \ucfe0\ud0a4\ub294 \uc774\ub7f0 \uc5f0\uacb0\uc744 \ub3d5\ub294 \ub3c4\uad6c\ub2e4. \uc2e4\uc81c\ub85c \uc0ac\ub78c\uc758 \uc5bc\uad74\uc744 \uae30\uc5b5\ud558\ub294 \uc810\uc6d0\uacfc \ub611\uac19\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc11c\ubc84\ub294 \uc751\ub2f5\uacfc \ud568\uaed8 \ube0c\ub77c\uc6b0\uc800\uac00 \ubcf4\uad00\ud560 \ucfe0\ud0a4\ub97c \ubcf4\ub0bc \uc218 \uc788\ub2e4. \ube0c\ub77c\uc6b0\uc800\ub294 \ud574\ub2f9 \uc870\uac74\uc5d0 \ub9de\ub294 \ub2e4\uc74c \uc694\uccad\uc744 \ud560 \ub54c \uadf8 \uac12\uc744 \ud568\uaed8 \uc804\ud55c\ub2e4. \uc11c\ubc84\ub294 \uc774\ub97c \ubcf4\uace0 \uc5b4\ub290 \uc0c1\ud0dc\uc640 \uc5f0\uacb0\ud560\uc9c0 \ud310\ub2e8\ud560 \uc218 \uc788\ub2e4. \uc5ec\uae30\uc5d0\ub294 \ucfe0\ud0a4\uc758 \uc801\uc6a9 \ubc94\uc704\uc640 \uc720\uc9c0 \uae30\uac04 \uac19\uc740 \uc870\uac74\uc774 \uc788\ub2e4. \uc544\ubb34 \uc0ac\uc774\ud2b8\uc5d0\uc11c\ub098 \ub2e4\ub978 \ubaa8\ub4e0 \uc0ac\uc774\ud2b8\uc758 \ucfe0\ud0a4\ub97c \uadf8\ub300\ub85c \ubc1b\ub294 \uad6c\uc870\ub85c \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud06c\uace0 \ubcf5\uc7a1\ud55c \uae30\uc5b5 \ud558\ub098\ubcf4\ub2e4 \uc815\ud574\uc9c4 \uc870\uac74\uc5d0\uc11c \uc8fc\uace0\ubc1b\ub294 \uc791\uc740 \uc815\ubcf4\ub4e4\uc774 \uc788\ub2e4\ub294 \ud3b8\uc774 \uc6d0\ub9ac\uc5d0 \uac00\uae5d\ub2e4. \ub85c\uadf8\uc778 \uc0c1\ud0dc\ub97c \uc774\uc5b4 \uc904 \ub54c \ucfe0\ud0a4\uc5d0 \uc138\uc158 \uc2dd\ubcc4\uc790\ub97c \ub2f4\ub294 \ubc29\uc2dd\uc774 \uc4f0\uc778\ub2e4. \uc11c\ubc84\uac00 \uc774 \uac12\uc744 \ud655\uc778\ud574 \uc774\ubbf8 \ub85c\uadf8\uc778\ud55c \uc0c1\ud0dc\uc778\uc9c0 \ud310\ub2e8\ud558\ub294 \uac83\uc774\ub2e4. \uc2dd\ubcc4\uc790\ub294 \uc5b4\ub5a4 \uae30\ub85d\uacfc \uc5f0\uacb0\ud560\uc9c0 \uc54c\ub824 \uc8fc\ub294 \ud45c\uc9c0\ub85c \uc774\ud574\ud558\uba74 \ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \ucfe0\ud0a4\uc758 \ub0b4\uc6a9\uc774 \uac19\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b8\uc5b4 \uc124\uc815\ucc98\ub7fc \uc9c1\uc811\uc801\uc778 \uac12\uc774 \ub4e4\uc5b4\uac08 \uc218\ub3c4 \uc788\uace0 \uc11c\ubc84 \ucabd \uae30\ub85d\uc744 \uac00\ub9ac\ud0a4\ub294 \uac12\uc774 \ub4e4\uc5b4\uac08 \uc218\ub3c4 \uc788\ub2e4. \ucfe0\ud0a4\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ub0b4 \uc774\ub984\uacfc \ube44\ubc00\ubc88\ud638\uac00 \uadf8\ub300\ub85c \ub4e4\uc5b4 \uc788\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub3c4, \uc544\ubb34 \uc911\uc694\ud55c \uc815\ubcf4\uac00 \uc5c6\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \uc77c\ubd80 \ucfe0\ud0a4\ub294 \uc815\ud574\uc9c4 \ub9cc\ub8cc \uc2dc\uc810\uc774\ub098 \uc720\uc9c0 \uc2dc\uac04\uae4c\uc9c0 \ub0a8\ub3c4\ub85d \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4. \ub2e4\ub978 \ucfe0\ud0a4\ub294 \uc138\uc158 \ub3d9\uc548 \uc0ac\uc6a9\ud558\ub294 \uac83\uc744 \ubaa9\uc801\uc73c\ub85c \ud55c\ub2e4. \ube0c\ub77c\uc6b0\uc800\uc758 \uc138\uc158 \ubcf5\uc6d0 \uae30\ub2a5\uacfc \uc124\uc815\uc5d0 \ub530\ub77c\uc11c\ub3c4 \uc0ac\uc6a9\uc790\uac00 \uacbd\ud5d8\ud558\ub294 \uacb0\uacfc\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ub530\ub77c\uc11c \ucc3d\uc744 \ub2eb\uc558\uc73c\ub2c8 \ubaa8\ub4e0 \uae30\ub85d\uc774 \uc989\uc2dc \uc0ac\ub77c\uc84c\ub2e4\uace0 \ub2e8\uc21c\ud558\uac8c \uacb0\ub860 \ub0b4\ub9ac\uae30 \uc5b4\ub835\ub2e4. \ubc18\ub300\ub85c \uc624\ub798 \ub0a8\ub294 \ucfe0\ud0a4\ub77c\uace0 \uc601\uc6d0\ud788 \uc720\uc9c0\ub418\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uc800\uc7a5\ub41c \uae30\uc5b5\uc5d0\ub3c4 \uc218\uba85\uc774 \uc788\uace0 \uadf8\uac83\uc744 \uc815\ud558\ub294 \uc5ec\ub7ec \uc870\uac74\uc774 \uc788\ub2e4\ub294 \uc815\ub3c4\ub85c \uc774\ud574\ud558\uba74 \ub41c\ub2e4. \ucfe0\ud0a4\ub294 \ub85c\uadf8\uc778\uc774\ub098 \uac1c\uc778\ud654\uc5d0 \uc4f0\uc77c \uc218 \uc788\uc9c0\ub9cc \uc774\uc6a9 \ud589\ud0dc\ub97c \uae30\ub85d\ud558\uace0 \ubd84\uc11d\ud558\ub294 \ub370\ub3c4 \uc4f0\uc778\ub2e4. \uac19\uc740 \uae30\uc220\uc774 \ub2e4\ub978 \ubaa9\uc801\uc744 \uac16\ub294 \uac83\uc774\ub2e4. \uc5b8\uc5b4 \uc124\uc815\uc744 \uae30\uc5b5\ud558\ub294 \uc77c\uacfc \uc5ec\ub7ec \ubc29\ubb38\uc744 \uc5f0\uacb0\ud574 \ud589\ub3d9\uc744 \uc0b4\ud3b4\ubcf4\ub294 \uc77c\uc740 \ub3c5\uc790\uac00 \ub290\ub07c\uae30\uc5d0\ub3c4 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc5b4\ub5a4 \uacf3\uc5d0\uc11c\ub294 \ub2e4\ub978 \uc11c\ube44\uc2a4\uac00 \uc81c\uacf5\ud558\ub294 \uc694\uc18c\uc640 \ud568\uaed8 \uad50\ucc28 \uc0ac\uc774\ud2b8 \ucfe0\ud0a4\uac00 \uad00\uc5ec\ud558\uae30\ub3c4 \ud55c\ub2e4. \ub2e4\ub9cc \uc624\ub298\ub0a0 \ube0c\ub77c\uc6b0\uc800\uac00 \uc774\ub97c \ud5c8\uc6a9\ud558\uac70\ub098 \uc81c\ud55c\ud558\ub294 \ubc29\uc2dd\uc740 \uc11c\ub85c \ub2e4\ub974\uace0 \uacc4\uc18d \ub2ec\ub77c\uc9c4\ub2e4. \ubaa8\ub4e0 \ucd94\uc801\uc774 \ucfe0\ud0a4 \ud558\ub098\ub85c \uc774\ub8e8\uc5b4\uc9c4\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uc2e4\uc81c\uc758 \uc5ec\ub7ec \uae30\uc220\uc744 \ub193\uce58\uac8c \ub41c\ub2e4. \ucfe0\ud0a4\ub97c \uc0ad\uc81c\ud558\uba74 \uc0ac\uc774\ud2b8\uac00 \uc55e\uc120 \ub85c\uadf8\uc778 \uc0c1\ud0dc\ub098 \uc124\uc815\uacfc \uc5f0\uacb0\ud558\uc9c0 \ubabb\ud574 \ub2e4\uc2dc \ub85c\uadf8\uc778\uc744 \uc694\uad6c\ud560 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc774\uac83\uc774 \uc11c\ubc84\uc5d0 \uc788\ub294 \uacc4\uc815\uacfc \uc8fc\ubb38 \ub0b4\uc5ed\uae4c\uc9c0 \uc790\ub3d9\uc73c\ub85c \uc9c0\uc6b4\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uae30\uae30 \ucabd \ud45c\uc9c0\ub97c \uc9c0\uc6b0\ub294 \uc77c\uacfc \ud68c\uc0ac\uac00 \ubcf4\uad00\ud55c \uae30\ub85d\uc744 \uc9c0\uc6b0\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uc774 \ucc28\uc774\ub294 \uc0ac\uc9c4\uad00\uc758 \ubcf4\uad00 \ubc88\ud638\ud45c\ub97c \ub5a0\uc62c\ub9ac\uba74 \uc27d\ub2e4. \ubc88\ud638\ud45c\ub97c \ubc84\ub838\ub2e4\uace0 \uc0ac\uc9c4\uad00\uc758 \uc6d0\ubcf8\uc774 \ud568\uaed8 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ube44\uc720\uac00 \uc2e4\uc81c \uacc4\uc815 \uad00\ub9ac \uc808\ucc28\ub97c \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\uc9c0\ub9cc, \uc5b4\ub290 \ucabd\uc758 \uc815\ubcf4\ub97c \uc9c0\uc6e0\ub294\uc9c0 \ub098\ub204\uc5b4 \uc0dd\uac01\ud558\uac8c \ud574 \uc900\ub2e4. \ube0c\ub77c\uc6b0\uc800\uc5d0\ub294 \ucfe0\ud0a4 \uc678\uc5d0\ub3c4 \ub370\uc774\ud130\ub97c \uc800\uc7a5\ud558\ub294 \ubc29\ubc95\uc774 \uc788\ub2e4. MDN\uc740 \ud070 \uc591\uc758 \uc6f9 \ub370\uc774\ud130\ub97c \uc800\uc7a5\ud558\ub294 \ub370 \ubcc4\ub3c4\uc758 \uc800\uc7a5 \uae30\uc220\uc744 \uc0ac\uc6a9\ud558\ub294 \uacbd\uc6b0\ub97c \uc124\uba85\ud55c\ub2e4. \uc0ac\uc774\ud2b8\uac00 \uc5b4\ub5a4 \uac12\uc744 \uae30\uc5b5\ud55c\ub2e4\uace0 \ud574\uc11c \ubc18\ub4dc\uc2dc \ucfe0\ud0a4\ub97c \uc37c\ub2e4\ub294 \uc99d\uac70\ub294 \uc544\ub2c8\ub2e4. \uadf8\ub798\uc11c \ucfe0\ud0a4\ub97c \ubaa8\ub450 \uc9c0\uc6e0\ub294\ub370 \uc5b4\ub5a4 \uc124\uc815\uc774 \ub0a8\uc544 \uc788\uac70\ub098, \ub2e4\ub978 \uae30\uae30\uc5d0\uc11c\ub294 \uae30\ub85d\uc774 \uc774\uc5b4\uc9c0\uc9c0 \uc54a\ub294 \ud604\uc0c1\ub3c4 \uc788\uc744 \uc218 \uc788\ub2e4. \uacc4\uc815\uc758 \uc11c\ubc84 \uae30\ub85d\uc778\uc9c0 \ube0c\ub77c\uc6b0\uc800\uc758 \uc800\uc7a5 \uc815\ubcf4\uc778\uc9c0\uc5d0 \ub530\ub77c \uc870\uac74\uc774 \ub2e4\ub974\ub2e4. \ud558\ub098\uc758 \ub2e8\uc5b4\ub85c \uc6f9\uc758 \uae30\uc5b5 \uc804\uccb4\ub97c \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc775\uc219\ud55c \ucc45\uc0c1\uacfc \ub178\ud2b8\ub85c \ub3cc\uc544\uc624\ub294 \ubd84\uc704\uae30\ub97c \ud45c\ud604\ud588\ub2e4. \uc2e4\uc81c \ucfe0\ud0a4 \ud30c\uc77c\uc774\ub098 \ube0c\ub77c\uc6b0\uc800 \ud654\uba74\uc758 \uae30\uc220 \ub3c4\ud310\uc740 \uc544\ub2c8\ub2e4. \ub2e4\uc2dc \ucc3e\uc544\uc654\uc744 \ub54c \uc55e\uc120 \uc120\ud0dd\uc744 \uc774\uc5b4 \uc8fc\ub294 \uacbd\ud5d8\uc744 \ub5a0\uc62c\ub9ac\ub294 \uadf8\ub9bc\uc774\ub2e4. \ucfe0\ud0a4\uc758 \uc6d0\ub9ac\ub97c \uc54c\uba74 \uc0ac\uc774\ud2b8\uac00 \ub098\ub97c \uae30\uc5b5\ud55c\ub2e4\ub294 \ub9d0\uc744 \uc870\uae08 \ub098\ub204\uc5b4 \ubcfc \uc218 \uc788\ub2e4. \ubb34\uc5c7\uc744, \uc5bc\ub9c8 \ub3d9\uc548, \uc5b4\ub5a4 \ubc94\uc704\uc5d0\uc11c \uae30\uc5b5\ud560\uae4c. \uc774 \uc9c8\ubb38\uc740 \uc791\uc740 \ub370\uc774\ud130\uac00 \ub9cc\ub4dc\ub294 \ud3b8\ub9ac\ud568\uc744 \uc774\ud574\ud558\uba74\uc11c \ub3d9\uc2dc\uc5d0 \uadf8 \uc0ac\uc6a9 \ubaa9\uc801\ub3c4 \uc0b4\ud53c\uac8c \ud55c\ub2e4. \uc6f9\uc758 \uae30\uc5b5\uc740 \ub9c9\uc5f0\ud55c \ub9c8\ubc95\ubcf4\ub2e4 \uad6c\uccb4\uc801\uc778 \uc57d\uc18d\uc5d0 \uac00\uae5d\ub2e4."}, {"id": "crc-checksum-detecting-changed-data", "title": "CRC \u2014 \ud30c\uc77c\uc774 \ub2ec\ub77c\uc84c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc5b4\ub5bb\uac8c \uc54c\uc544\ub0bc\uae4c", "summary": "\uc9e7\uc740 \uac80\uc0ac\uac12\uc774 \ud30c\uc77c\uc758 \ubcc0\ud654\ub97c \ucc3e\ub294 \ubc29\uc2dd\uacfc \ub3d9\uc77c\uc131\u00b7\ubcf5\uad6c\u00b7\ucd9c\ucc98 \uc778\uc99d\uc744 \uad6c\ubd84\ud574 \uc774\ud574\ud569\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\ub370\uc774\ud130\uc640 \uae30\ub85d", "categories": ["digital"], "url": "stories/crc-checksum-detecting-changed-data/index.html", "image": "../media/crc-checksum-detecting-changed-data.png", "alt": "\uc11c\ub85c \ub2e4\ub978 \ub370\uc774\ud130 \ud45c\uc2dc\ub97c \ube44\uad50\ud558\ub294 \uae30\uc220\uc790\uc640 \uae30\ub85d \uc7a5\uce58\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "CRC \u2014 \ud30c\uc77c\uc774 \ub2ec\ub77c\uc84c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc5b4\ub5bb\uac8c \uc54c\uc544\ub0bc\uae4c RFC 1952\uc758 CRC32\ub85c \uc77d\ub294 \uc624\ub958 \uac80\ucd9c\uc758 \uc5ed\ud560\uacfc \ud55c\uacc4 \uc9e7\uc740 \uac80\uc0ac\uac12\uc774 \ud30c\uc77c\uc758 \ubcc0\ud654\ub97c \ucc3e\ub294 \ubc29\uc2dd\uacfc \ub3d9\uc77c\uc131\u00b7\ubcf5\uad6c\u00b7\ucd9c\ucc98 \uc778\uc99d\uc744 \uad6c\ubd84\ud574 \uc774\ud574\ud569\ub2c8\ub2e4. \ub370\uc774\ud130\uc640 \uae30\ub85d \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \uc624\ub798 \ubcf4\uad00\ud558\uac70\ub098 \ub2e4\ub978 \uacf3\uc73c\ub85c \uc62e\uae34 \ud30c\uc77c\uc774 \uc6d0\ub798\uc640 \uac19\uc740\uc9c0 \ud655\uc778\ud558\uace0 \uc2f6\uc744 \ub54c\uac00 \uc788\ub2e4. \ub450 \ud30c\uc77c\uc758 \ubaa8\ub4e0 \ube44\ud2b8\ub97c \uc9c1\uc811 \ube44\uad50\ud560 \uc218\ub3c4 \uc788\uc9c0\ub9cc, \uc9e7\uc740 \uac80\uc0ac\uac12\uc744 \uacc4\uc0b0\ud574 \ubcc0\ud654\uc758 \ub2e8\uc11c\ub97c \uc5bb\ub294 \ubc29\ubc95\ub3c4 \uc788\ub2e4. CRC\ub294 \uc774\ub7f0 \uc624\ub958 \uac80\ucd9c\uc5d0 \ub110\ub9ac \uc4f0\uc774\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc9e7\uc740 \uac12\uc774 \uc54c\ub824 \uc8fc\ub294 \uac83\uacfc \uc54c\ub824 \uc8fc\uc9c0 \ubabb\ud558\ub294 \uac83\uc744 \uad6c\ubd84\ud574 \ubcf4\uc790. \ubb38\uc11c\uc758 \ub73b\uc744 \uc774\ud574\ud558\uc9c0 \ubabb\ud558\ub294 \uc7a5\uce58\ub3c4 \ube44\ud2b8\uac00 \ub2ec\ub77c\uc84c\ub294\uc9c0\ub294 \ub2e4\ub8f0 \uc218 \uc788\ub2e4. \uc800\uc7a5\uacfc \uc804\uc1a1\uc758 \uacfc\uc815\uc5d0\uc11c \uc77c\ubd80\uac00 \ubc14\ub00c\uc5c8\ub2e4\uba74 \uc751\uc6a9\ud504\ub85c\uadf8\ub7a8\uc774 \uc6d0\ud558\uc9c0 \uc54a\ub294 \uacb0\uacfc\ub97c \ub0bc \uc218 \uc788\ub2e4. \uc555\ucd95 \ud30c\uc77c\ucc98\ub7fc \uc5ec\ub7ec \ub2e8\uacc4\ub97c \uac70\uce58\ub294 \ud615\uc2dd\uc5d0\uc11c\ub294 \uac80\uc0ac\uac00 \ud2b9\ud788 \uc911\uc694\ud574\uc9c4\ub2e4. \uc624\ub958 \uac80\ucd9c\uc740 \ubb38\uc81c\uac00 \uc804\ud600 \uc0dd\uae30\uc9c0 \uc54a\ub3c4\ub85d \ub9c9\ub294 \uae30\ub2a5\uacfc \ub2e4\ub974\ub2e4. \uc774\ubbf8 \ubc1b\uc740 \uc790\ub8cc\uac00 \uae30\ub300\ud55c \uc0c1\ud0dc\uc778\uc9c0 \ud310\ub2e8\ud558\ub294 \ub2e8\uc11c\ub97c \ub9cc\ub4e0\ub2e4. \ubcc0\ud654\uac00 \uc5c6\uc744 \uac83\uc774\ub77c\uace0 \ubbff\ub294 \ub300\uc2e0 \ubcc0\ud654\ud560 \uac00\ub2a5\uc131\uc744 \uc804\uc81c\ub85c \ud655\uc778 \uc808\ucc28\ub97c \ub454\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. CRC \uacc4\uc0b0\uc740 \uc785\ub825\ub41c \ube44\ud2b8\ub4e4\uc5d0 \uc815\ud574\uc9c4 \uaddc\uce59\uc744 \uc801\uc6a9\ud574 \uc9e7\uc740 \uacb0\uacfc\ub97c \ub9cc\ub4e0\ub2e4. \ubc1b\ub294 \ucabd\uc774 \uac19\uc740 \uaddc\uce59\uc73c\ub85c \ub2e4\uc2dc \uacc4\uc0b0\ud558\uace0 \uae30\ub300\ud55c \uac12\uacfc \ube44\uad50\ud558\uba74 \ucc28\uc774\ub97c \ucc3e\uc744 \uc218 \uc788\ub2e4. \uc5ec\uae30\uc11c \uacc4\uc0b0 \ubc29\ubc95\ubfd0 \uc544\ub2c8\ub77c \uc5b4\ub290 \ubc94\uc704\uc758 \ub370\uc774\ud130\ub97c \uacc4\uc0b0\ud558\ub294\uc9c0\ub3c4 \uac19\uc544\uc57c \ud55c\ub2e4. \ud30c\uc77c \uc774\ub984\uc774 \uac19\ub2e4\ub294 \uc0ac\uc2e4\uc774\ub098 \uac89\uc73c\ub85c \ubcf4\uc774\ub294 \ud06c\uae30\uac00 \uac19\ub2e4\ub294 \uc0ac\uc2e4\ubcf4\ub2e4 \uad6c\uccb4\uc801\uc778 \ud655\uc778\uc774 \uac00\ub2a5\ud574\uc9c4\ub2e4. \uadf8\ub7ec\ub098 \uc9e7\uc740 \uacb0\uacfc\uac00 \uc6d0\ubcf8\uc758 \ubaa8\ub4e0 \uc815\ubcf4\ub97c \ub2f4\uc740 \uc791\uc740 \ubcf5\uc81c\ud488\uc778 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8 \uac12\uc744 \uc77d\uc5b4 \uc6d0\ub798 \ubb38\uc11c\ub97c \ubcf5\uc6d0\ud560 \uc218\ub294 \uc5c6\ub2e4. CRC\ub294 \ube44\ud2b8\uc5f4\uc744 \ub2e4\ud56d\uc2dd\ucc98\ub7fc \ub2e4\ub8e8\uace0 \uc815\ud574\uc9c4 \uacc4\uc0b0\uc758 \ub098\uba38\uc9c0\ub97c \uc5bb\ub294 \ubc29\uc2dd\uc73c\ub85c \uc124\uba85\ud560 \uc218 \uc788\ub2e4. \uc77c\uc0c1\uc801\uc778 \uc2ed\uc9c4\uc218\uc758 \ub098\ub217\uc148\uacfc \uc644\uc804\ud788 \uac19\uc9c0\ub294 \uc54a\ub2e4. \ube44\ud2b8\uc758 \uc5f0\uc0b0 \uaddc\uce59\uc5d0 \ub530\ub77c \uacc4\uc0b0\ud558\ubbc0\ub85c \uad6c\ud604\uc5d0\uc11c\ub294 \uadf8 \uaddc\uce59\uc744 \uc815\ud655\ud788 \ub9de\ucdb0\uc57c \ud55c\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uc5b4\ub824\uc6b4 \uc218\uc2dd\uc744 \uc678\uc6b0\ub294 \uc77c\uc774 \uc544\ub2c8\ub2e4. \uac19\uc740 \uc785\ub825\uacfc \uac19\uc740 \uc870\uac74\uc5d0\uc11c \uac19\uc740 \uac80\uc0ac\uac12\uc774 \ub098\uc624\uace0, \ud2b9\uc815\ud55c \uc624\ub958 \ud615\ud0dc\ub97c \uc798 \ucc3e\uc544\ub0b4\ub3c4\ub85d \uaddc\uce59\uc774 \uc815\ud574\uc84c\ub2e4\ub294 \uc810\uc774\ub2e4. \uc9e7\uc740 \uc22b\uc790\ub97c \uc544\ubb34\ub807\uac8c\ub098 \uace0\ub974\ub294 \uac83\uacfc \uac80\uc0ac\uc5d0 \uc801\ud569\ud55c \uad6c\uc870\ub97c \uc124\uacc4\ud558\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uac19\uc740 CRC\ub77c\ub294 \uc774\ub984 \uc544\ub798\uc5d0\ub3c4 \uacc4\uc0b0\uc5d0 \uc0ac\uc6a9\ud558\ub294 \uaddc\uce59\uacfc \uc2dc\uc791\uac12, \ube44\ud2b8\ub97c \ub2e4\ub8e8\ub294 \uc21c\uc11c \ub4f1\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ubcc0\ud615\uc73c\ub85c \uacc4\uc0b0\ud55c \uac12\uc744 \ube44\uad50\ud558\uba74 \ub0b4\uc6a9\uc774 \uac19\uc544\ub3c4 \ub2e4\ub974\uac8c \ub098\uc62c \uc218 \uc788\ub2e4. \uac80\uc0ac\uc758 \uc591\ucabd\uc774 \ubb34\uc5c7\uc744 \uacf5\uc720\ud574\uc57c \ud558\ub294\uc9c0 \uba85\uc138\uac00 \ud544\uc694\ud55c \uc774\uc720\ub2e4. RFC 1952\uc5d0\ub294 \uacc4\uc0b0\uc744 \uc774\ud574\ud560 \uc218 \uc788\ub3c4\ub85d \uc608\uc81c \ucf54\ub4dc\ub3c4 \uc2e4\ub824 \uc788\ub2e4. \ud615\uc2dd\uc758 \uc124\uba85\uacfc \uc2e4\uc81c\ub85c \uacb0\uacfc\ub97c \ub9cc\ub4dc\ub294 \uc808\ucc28\uac00 \ud568\uaed8 \uc81c\uacf5\ub41c \uac83\uc774\ub2e4. \ubb38\uc11c\ub9cc \uc77d\uace0 \uad6c\ud604\ud55c \ub450 \ud504\ub85c\uadf8\ub7a8\uc774 \uac19\uc740 \uac12\uc5d0 \ub3c4\ub2ec\ud574\uc57c \ud30c\uc77c \uad50\ud658\uc774 \uac00\ub2a5\ud558\ub2e4. \ub370\uc774\ud130\uc758 \uc2e0\ub8b0\ub294 \uac80\uc0ac \uacf5\uc2dd\ubfd0 \uc544\ub2c8\ub77c \uadf8 \uacf5\uc2dd\uc744 \ud574\uc11d\ud558\ub294 \uc0ac\ub78c\ub4e4\uc774 \uac19\uc740 \uc138\ubd80\ub97c \uc9c0\ud0a4\ub294 \ub370\uc5d0\ub3c4 \ub2ec\ub824 \uc788\ub2e4. \ud45c\uc900\uc740 \uc774\ub7f0 \ucc28\uc774\uac00 \uc0ac\uc6a9\uc790\uc758 \ubb38\uc81c\ub85c \ub098\ud0c0\ub098\uae30 \uc804\uc5d0 \uacf5\ud1b5\uc758 \uae30\uc900\uc744 \ub9c8\ub828\ud55c\ub2e4. 1996\ub144 RFC 1952\uac00 \uc124\uba85\ud558\ub294 gzip \ud615\uc2dd\uc5d0\ub294 CRC32\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \uc774 \uac12\uc740 \uc555\ucd95\ub41c \ubc14\uc774\ud2b8\ub4e4 \uc790\uccb4\uac00 \uc544\ub2c8\ub77c \uc555\ucd95\uc744 \ud480\uc5c8\uc744 \ub54c\uc758 \uc6d0\ub798 \ub370\uc774\ud130\uc5d0 \ub300\ud574 \uacc4\uc0b0\ub41c\ub2e4. \ud655\uc778\ud558\ub294 \ub300\uc0c1\uc774 \uc5b4\ub514\uc5d0 \uc788\ub294\uc9c0 \uc54c\uc544\uc57c \uac80\uc0ac\uc758 \uc758\ubbf8\uac00 \uc815\ud655\ud574\uc9c4\ub2e4. \ud615\uc2dd\uc5d0\ub294 \uc555\ucd95 \uc804 \ud06c\uae30\ub97c \ub098\ud0c0\ub0b4\ub294 \uac12\ub3c4 \ud3ec\ud568\ub41c\ub2e4. \ub2e4\ub9cc \ud06c\uae30 \uac12\uc5d0\ub294 \uc815\ud574\uc9c4 \ube44\ud2b8 \uc218\uc5d0 \ub530\ub978 \ubc94\uc704\uac00 \uc788\ub2e4. \uac80\uc0ac\uac12\uacfc \ud06c\uae30\ub97c \ud568\uaed8 \uac16\uace0 \uc788\ub2e4\uace0 \uc6d0\ubcf8\uc758 \ubaa8\ub4e0 \uc815\ubcf4\ub97c \uc644\ubcbd\ud788 \ubcf4\uad00\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ud30c\uc77c \ud615\uc2dd\uc740 \ud544\uc694\ud55c \uc815\ubcf4\ub97c \uc81c\ud55c\ub41c \uad6c\uc870\uc5d0 \ubc30\uce58\ud55c\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uae34 \ub370\uc774\ud130\uac00 \uac19\uc740 \uc9e7\uc740 \uacb0\uacfc\ub97c \ub9cc\ub4e4 \uac00\ub2a5\uc131\uc740 \uc788\ub2e4. \uac00\ub2a5\ud55c \uc785\ub825\uc758 \uc218\uac00 \uacb0\uacfc\uc758 \uc218\ubcf4\ub2e4 \ub9ce\uae30 \ub54c\ubb38\uc774\ub2e4. CRC32\ub77c\ub294 \uc774\ub984\uc5d0\uc11c 32\ub294 \uacb0\uacfc\uc758 \uae38\uc774\uc640 \uc5f0\uacb0\ub418\uba70, \ubb34\ud55c\ud788 \ub2e4\uc591\ud55c \ud30c\uc77c\uc744 \ubaa8\ub450 \uace0\uc720\ud558\uac8c \uad6c\ubd84\ud558\ub294 \ubc88\ud638\ub77c\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \ub530\ub77c\uc11c \uac12\uc774 \ub2e4\ub974\uba74 \uc790\ub8cc\uac00 \ub2ec\ub77c\uc84c\ub2e4\ub294 \uc911\uc694\ud55c \ub2e8\uc11c\uac00 \ub418\uc9c0\ub9cc, \uac19\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc5b4\ub5a4 \uc0c1\ud669\uc5d0\uc11c\ub3c4 \uc644\uc804\ud55c \ub3d9\uc77c\uc131\uc744 \uc99d\uba85\ud55c\ub2e4\uace0 \ub9d0\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uac80\uc0ac\uc758 \ubaa9\uc801\uacfc \uc624\ub958\uc758 \ud615\ud0dc\ub97c \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \uc720\uc6a9\ud55c \uac80\uc0ac\uc640 \ubb34\uc81c\ud55c\uc758 \uc99d\uba85\uc740 \ub2e4\ub974\ub2e4. CRC\ub294 \uc6b0\uc5f0\ud55c \ubcc0\ud654\uc758 \uac80\ucd9c\uc5d0 \uc720\uc6a9\ud558\uc9c0\ub9cc \uc790\ub8cc\ub97c \uace0\uc758\ub85c \ubc14\uafb8\ub294 \uc0ac\ub78c\uc758 \uc2e0\uc6d0\uc744 \ud655\uc778\ud558\ub294 \uc7a5\uce58\ub294 \uc544\ub2c8\ub2e4. \ub0b4\uc6a9\uc744 \ubc14\uafbc \uc0ac\ub78c\uc774 \uac80\uc0ac\uac12\ub3c4 \ub2e4\uc2dc \ub9cc\ub4e4 \uc218 \uc788\ub2e4\uba74 \ub2e8\uc21c\ud55c \ube44\uad50\ub9cc\uc73c\ub85c \uc815\ub2f9\ud55c \uc6d0\ubcf8\uc774\ub77c\uace0 \ud310\ub2e8\ud560 \uc218 \uc5c6\ub2e4. \uacf5\uac1c\ub41c \uacc4\uc0b0 \uaddc\uce59 \uc790\uccb4\uac00 \ube44\ubc00 \uc11c\uba85\uc740 \uc544\ub2c8\ub2e4. \uc774 \uad6c\ubd84\uc740 \uac80\uc0ac\ub97c \ub0ae\uac8c \ud3c9\uac00\ud558\uc790\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \ub9e1\uae34 \uc5ed\ud560 \uc548\uc5d0\uc11c \uc774\ud574\ud558\uc790\ub294 \ub73b\uc774\ub2e4. \uc624\ub958\ub97c \uc54c\uc544\ub0b4\ub294 \uae30\ub2a5\uacfc \ucd9c\ucc98\ub97c \uc778\uc99d\ud558\ub294 \uae30\ub2a5\uc740 \ud574\uacb0\ud558\ub824\ub294 \ubb38\uc81c\uac00 \ub2e4\ub974\ub2e4. \ud55c \uac00\uc9c0 \uac80\uc0ac\uac12\uc73c\ub85c \ubaa8\ub4e0 \uc694\uad6c\ub97c \ub300\uc2e0\ud558\ub824 \ud558\uba74 \uc798 \uc791\ub3d9\ud558\ub294 \ub3c4\uad6c\ub3c4 \uc798\ubabb \uc4f0\uc774\uac8c \ub41c\ub2e4. \uc790\ub8cc\uac00 \ub2e4\ub974\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c\uc558\ub2e4\uace0 \uc62c\ubc14\ub978 \ub0b4\uc6a9\uc774 \uc800\uc808\ub85c \ubcf5\uad6c\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub2e4\uc2dc \ub0b4\ub824\ubc1b\uac70\ub098 \ub2e4\ub978 \uc0ac\ubcf8\uc744 \ud655\uc778\ud558\ub294 \ub4f1 \ubcc4\ub3c4\uc758 \uacfc\uc815\uc774 \ud544\uc694\ud558\ub2e4. CRC\ub294 \uadf8\ub2e4\uc74c \ud589\ub3d9\uc744 \uc2dc\uc791\ud560 \uc774\uc720\ub97c \uc81c\uacf5\ud558\uc9c0\ub9cc \ubcf5\uad6c \uc808\ucc28 \uc804\uccb4\ub97c \ud3ec\ud568\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud30c\uc77c\uc744 \uc77d\ub294 \uac04\ub2e8\ud55c \uacbd\ud5d8 \ub4a4\uc5d0\ub294 \uc774\ub807\uac8c \uc791\uac8c \ub098\ub25c \ucc45\uc784\uc774 \uc788\ub2e4. \uc790\ub8cc\ub97c \uc555\ucd95\ud558\ub294 \ubc29\ubc95\uacfc \ud615\uc2dd\uc744 \ud574\uc11d\ud558\ub294 \ubc29\ubc95, \uc624\ub958\ub97c \uac80\ucd9c\ud558\uace0 \ub300\uc751\ud558\ub294 \ubc29\ubc95\uc774 \uc5f0\uacb0\ub41c\ub2e4. CRC\uc758 \uc5ed\uc0ac\ub294 \ub514\uc9c0\ud138\uc758 \uc2e0\ub8b0\uac00 \ud558\ub098\uc758 \ub9cc\ub2a5 \uc7a5\uce58\ubcf4\ub2e4 \uc5ed\ud560\uc744 \uad6c\ubd84\ud55c \uc5ec\ub7ec \uc57d\uc18d\uc5d0\uc11c \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "css-same-words-different-page", "title": "CSS \u2014 \uac19\uc740 \uae00\uc774 \ub2e4\ub978 \uc5bc\uad74\ub85c \ubcf4\uc774\ub294 \uc774\uc720", "summary": "\uc6f9 \ubb38\uc11c\uc758 \ub0b4\uc6a9\uacfc \ud45c\ud604 \uaddc\uce59\uc744 \uad6c\ubd84\ud558\uba70 \uae00\uc790\u00b7\uc5ec\ubc31\u00b7\ubc30\uce58\uac00 \ub3c5\uc11c \uacbd\ud5d8\uc744 \ubc14\uafb8\ub294 \uc6d0\ub9ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\uc18c\ud504\ud2b8\uc6e8\uc5b4", "categories": ["digital"], "url": "stories/css-same-words-different-page/index.html", "image": "../media/css-same-words-different-page.png", "alt": "\uac19\uc740 \uc6d0\uace0\ub97c \uc11c\ub85c \ub2e4\ub978 \uc5ec\ubc31\uacfc \ubc30\uce58\ub85c \ub193\uc740 \uc9c0\uba74 \ub450 \uc7a5\uc744 \ube44\uad50\ud558\ub294 \ud3b8\uc9d1\uc790\uc758 \uc0bd\ud654.", "text": "CSS \u2014 \uac19\uc740 \uae00\uc774 \ub2e4\ub978 \uc5bc\uad74\ub85c \ubcf4\uc774\ub294 \uc774\uc720 \ub0b4\uc6a9\uc758 \uad6c\uc870\uc640 \uc77d\ub294 \ubaa8\uc2b5\uc744 \ub098\ub204\uc5b4 \uc0dd\uac01\ud558\uae30 \uc6f9 \ubb38\uc11c\uc758 \ub0b4\uc6a9\uacfc \ud45c\ud604 \uaddc\uce59\uc744 \uad6c\ubd84\ud558\uba70 \uae00\uc790\u00b7\uc5ec\ubc31\u00b7\ubc30\uce58\uac00 \ub3c5\uc11c \uacbd\ud5d8\uc744 \ubc14\uafb8\ub294 \uc6d0\ub9ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uc18c\ud504\ud2b8\uc6e8\uc5b4 \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \uac19\uc740 \uae00\uc778\ub370 \ud55c\ucabd\uc5d0\uc11c\ub294 \uc77d\uae30 \ud3b8\ud558\uace0 \ub2e4\ub978 \ucabd\uc5d0\uc11c\ub294 \ub2f5\ub2f5\ud558\ub2e4. \ubb38\uc7a5\uc740 \ubc14\ub00c\uc9c0 \uc54a\uc558\ub2e4. \uae00\uc790 \ud06c\uae30\uc640 \uc904 \uc0ac\uc774, \ubcf8\ubb38\uc774 \ucc28\uc9c0\ud558\ub294 \ud3ed\uc774 \ub2ec\ub77c\uc84c\uc744 \ubfd0\uc774\ub2e4. \ub0b4\uc6a9\uc744 \uc774\ud574\ud558\ub294 \ub370 \ub514\uc790\uc778\uc774 \uc5bc\ub9c8\ub098 \uad00\uc5ec\ud558\ub294\uc9c0 \uc774\ub7f0 \uc21c\uac04\uc5d0 \uc2e4\uac10\ud558\uac8c \ub41c\ub2e4. \uc6f9\ud398\uc774\uc9c0\uc5d0\uc11c\ub294 \uc774 \ud45c\ud604\uc758 \uc0c1\ub2f9 \ubd80\ubd84\uc744 CSS\ub77c\ub294 \uae30\uc220\uc774 \ub9e1\ub294\ub2e4. \uc774\ub984\uc740 \ub0af\uc124\uc5b4\ub3c4 \ub3c5\uc790\uac00 \ub9cc\ub098\ub294 \uacb0\uacfc\ub294 \ub9e4\uc77c \uc775\uc219\ud558\ub2e4. \ucf54\ub4dc\ub97c \ubc30\uc6b0\uae30\ubcf4\ub2e4 \ucc45\uc758 \ud3b8\uc9d1\uacfc \ube44\uad50\ud574 \ubcf4\uba74 \uac19\uc740 \ubb38\uc11c\uac00 \uc5ec\ub7ec \uc5bc\uad74\uc744 \uac16\ub294 \uc774\uc720\ub97c \uc27d\uac8c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc6f9 \ubb38\uc11c\uc5d0 \uc4f0\uc774\ub294 HTML\uc740 \uc81c\ubaa9\uacfc \ubb38\ub2e8, \ub9c1\ud06c \uac19\uc740 \ub0b4\uc6a9\uc758 \uad6c\uc870\ub97c \ud45c\uc2dc\ud55c\ub2e4. CSS\ub294 \uadf8\ub7f0 \uc694\uc18c\uac00 \ud654\uba74\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ud45c\ud604\ub420\uc9c0 \uaddc\uce59\uc744 \uc815\ud55c\ub2e4. \uc81c\ubaa9\uc774\ub77c\ub294 \uc5ed\ud560\uacfc \uc81c\ubaa9\uc758 \uae00\uc790\ub97c \ud30c\ub780\uc0c9\uc73c\ub85c \ubcf4\uc774\uac8c \ud558\ub294 \uc120\ud0dd\uc740 \uad6c\ubd84\ub418\ub294 \uac83\uc774\ub2e4. \ucc45\uc73c\ub85c \ube44\uc720\ud558\uba74 \uc6d0\uace0\uc758 \ud070\uc81c\ubaa9\uacfc \ubb38\ub2e8\uc744 \uad6c\ubd84\ud558\ub294 \uc77c, \uadf8\ub9ac\uace0 \uae00\uaf34\uacfc \ud06c\uae30\uc640 \uac04\uaca9\uc744 \uc815\ud558\ub294 \uc77c\uc774 \ub2ee\uc544 \uc788\ub2e4. \uc644\uc804\ud788 \uac19\uc740 \uc81c\uc791 \uacfc\uc815\uc740 \uc544\ub2c8\uc9c0\ub9cc \ub450 \uc885\ub958\uc758 \ud310\ub2e8\uc744 \ub098\ub204\uc5b4 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uad6c\uc870\ub97c \uc720\uc9c0\ud55c \ucc44 \ud45c\ud604\uc744 \ubc14\uafc0 \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud55c \ucd9c\ubc1c\uc810\uc774\ub2e4. \uc791\uc131\uc790\uac00 \ubcc4\ub3c4\uc758 \ud45c\ud604\uc744 \uc9c0\uc815\ud558\uc9c0 \uc54a\uc544\ub3c4 \ube0c\ub77c\uc6b0\uc800\ub294 \uc81c\ubaa9\uc744 \ud06c\uac8c, \ub9c1\ud06c\ub97c \ub2e4\ub978 \uc0c9\uacfc \ubc11\uc904\ub85c \ubcf4\uc5ec \uc8fc\uace4 \ud55c\ub2e4. MDN\uc740 \uc774\ub97c \ube0c\ub77c\uc6b0\uc800\uc758 \uae30\ubcf8 \uc2a4\ud0c0\uc77c\uc774\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \uc815\ub9d0 \uc544\ubb34 \uaddc\uce59\ub3c4 \uc5c6\uc774 \uae00\uc790\ub9cc \ud769\uc5b4 \ub193\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774 \ub355\ubd84\uc5d0 \ud2b9\ubcc4\ud55c \ub514\uc790\uc778\uc774 \uc5c6\ub294 \ubb38\uc11c\ub3c4 \uc5b4\ub290 \uc815\ub3c4 \uad6c\ubd84\ud574 \uc77d\uc744 \uc218 \uc788\ub2e4. \uc775\uc219\ud574\uc11c \uc790\uc5f0\ucc98\ub7fc \ub290\ub07c\ub358 \ubaa8\uc2b5\uc5d0\ub3c4 \ub204\uad70\uac00 \uc815\ud55c \uae30\ubcf8\uac12\uc774 \uc788\uc5c8\ub358 \uc148\uc774\ub2e4. \uc6f9\ud398\uc774\uc9c0\uc758 \ud45c\ud604\uc744 \uc774\ud574\ud558\ub824\uba74 \ubcf4\uc774\ub294 \uc0c9\ubfd0 \uc544\ub2c8\ub77c \uc9c0\uc815\ud558\uc9c0 \uc54a\uc558\uc744 \ub54c \ubb34\uc5c7\uc774 \uc801\uc6a9\ub418\ub294\uc9c0\ub3c4 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. CSS\ub294 \uc5b4\ub5a4 \uc694\uc18c\uc5d0 \uc5b4\ub5a4 \ud45c\ud604\uc744 \uc801\uc6a9\ud560\uc9c0 \uaddc\uce59\uc73c\ub85c \uc801\ub294\ub2e4. \ubaa8\ub4e0 \ubcf8\ubb38 \ubb38\ub2e8\uc758 \uae00\uc790\uc640 \ubc30\uacbd, \uc5ec\ubc31\uc744 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc815\ud560 \uc218 \uc788\ub2e4. \ubb38\ub2e8\uc774 \ub298\uc5b4\ub0a0 \ub54c\ub9c8\ub2e4 \ud55c \uc904\uc529 \uc218\ub3d9\uc73c\ub85c \uc0c9\uce60\ud558\ub294 \ubc29\uc2dd\uacfc\ub294 \ub2e4\ub974\ub2e4. \uacf5\ud1b5\uc758 \uc5ed\ud560\uc744 \uac00\uc9c4 \uc694\uc18c\ub4e4\uc744 \ud568\uaed8 \ub2e4\ub8e8\ub294 \uac83\uc774\ub2e4. MDN\uc758 \uc608\uc5d0\uc11c\ub3c4 \uc0c8 \ubb38\ub2e8\uc744 \ucd94\uac00\ud558\uba74 \uae30\uc874 \ubb38\ub2e8 \uaddc\uce59\uc774 \uc801\uc6a9\ub41c\ub2e4. \ub3c5\uc790\ub294 \ubb38\ubc95\uc744 \uc678\uc6b8 \ud544\uc694\uac00 \uc5c6\ub2e4. \uac19\uc740 \uc885\ub958\uc758 \ub0b4\uc6a9\uc5d0 \uac19\uc740 \ud45c\ud604\uc744 \uc8fc\ub294 \uc57d\uc18d\uc774 \uc788\ub2e4\ub294 \uc810\ub9cc \uc774\ud574\ud558\uba74 \ub41c\ub2e4. \uc5ec\ub7ec \ud398\uc774\uc9c0\uac00 \ud55c \uc0ac\uc774\ud2b8\ucc98\ub7fc \ub290\uaef4\uc9c0\ub294 \ub370\ub3c4 \uc774\ub7f0 \ubc18\ubcf5\uc758 \uc9c8\uc11c\uac00 \ub3c4\uc6c0\uc744 \uc900\ub2e4. CSS\ub294 \uae00\uc790 \ud06c\uae30\uc640 \uc0c9\ubfd0 \uc544\ub2c8\ub77c \ud654\uba74\uc758 \ubc30\uce58\ub3c4 \ub2e4\ub8ec\ub2e4. \ub0b4\uc6a9\uc744 \uc5ec\ub7ec \uce78\uc73c\ub85c \uc815\ub82c\ud558\uac70\ub098 \uc694\uc18c \uc0ac\uc774\uc758 \uac04\uaca9\uc744 \uc815\ud558\uace0 \uc6c0\uc9c1\uc784\uc744 \uc904 \uc218\ub3c4 \uc788\ub2e4. \uadf8\ub798\uc11c \uc6f9 \ub514\uc790\uc778\uc744 \ub2e8\uc21c\ud788 \uae00\uc5d0 \uc608\uc05c \uc0c9\uc744 \uce60\ud558\ub294 \uc77c\ub85c\ub9cc \ubcf4\uba74 \uc911\uc694\ud55c \ubd80\ubd84\uc744 \ub193\uce5c\ub2e4. \uc77d\ub294 \uc21c\uc11c\uc640 \uc2dc\uc120\uc774 \uc26c\ub294 \uc790\ub9ac\ub3c4 \ud45c\ud604\uc758 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4. \uc81c\ubaa9\uc774 \uc9c0\ub098\uce58\uac8c \uc791\uc73c\uba74 \uad6c\uc870\ub97c \ub193\uce58\uae30 \uc27d\uace0, \uc5ec\ubc31\uc774 \uc5c6\uc73c\uba74 \uc11c\ub85c \ub2e4\ub978 \ub0b4\uc6a9\uc774 \ubd99\uc5b4 \ubcf4\uc77c \uc218 \uc788\ub2e4. \uc774\uac83\uc740 \ud2b9\uc815 \uc218\uce58 \ud558\ub098\uac00 \uc5b8\uc81c\ub098 \uc815\ub2f5\uc774\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \ub0b4\uc6a9\uc744 \uc5b4\ub5a4 \ud658\uacbd\uc5d0\uc11c \uc77d\ub294\uc9c0\uac00 \ud568\uaed8 \uc911\uc694\ud558\ub2e4. CSS\ub294 HTML \uc548\uc5d0 \uc801\uc744 \uc218\ub3c4 \uc788\uace0 \ubcc4\ub3c4\uc758 \ud30c\uc77c\ub85c \uc5f0\uacb0\ud560 \uc218\ub3c4 \uc788\ub2e4. MDN\uc740 \ube0c\ub77c\uc6b0\uc800\uac00 \uc774\ub7f0 \ud45c\ud604 \uaddc\uce59\uc744 \ucc3e\uc544 \ubb38\uc11c\uc5d0 \uc801\uc6a9\ud55c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc5ec\ub7ec \ubb38\uc11c\uac00 \uacf5\ud1b5\uc758 \ud45c\ud604 \ud30c\uc77c\uc744 \uc0ac\uc6a9\ud558\uba74 \uc6d0\uace0 \uc804\uccb4\ub97c \ub2e4\uc2dc \uc4f0\uc9c0 \uc54a\uace0\ub3c4 \ubaa8\uc2b5\uc744 \uc870\uc815\ud560 \uc218 \uc788\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \ubcf8\ubb38 \uac04\uaca9\uc744 \ub113\ud788\ub294 \uc120\ud0dd\uc740 \uc774\uc57c\uae30\uc758 \uc0ac\uc2e4\uad00\uacc4\ub97c \ubc14\uafb8\ub294 \uc77c\uacfc \ub2e4\ub974\ub2e4. \ub0b4\uc6a9 \uc218\uc815\uacfc \ub514\uc790\uc778 \uc218\uc815\uc758 \ubc94\uc704\ub97c \ub098\ub20c \uc218 \uc788\ub294 \uac83\uc774\ub2e4. \ub2e4\ub9cc \uad6c\uc870\uac00 \ubd80\uc2e4\ud55c \ubb38\uc11c\ub97c \uac89\ubaa8\uc591\ub9cc\uc73c\ub85c \uc798 \uc815\ub9ac\ub41c \ubb38\uc11c\ub85c \ub9cc\ub4e4 \uc218\ub294 \uc5c6\ub2e4. \ud45c\ud604\uacfc \ub0b4\uc6a9\uc774 \uc5ed\ud560\uc744 \ub098\ub204\ub354\ub77c\ub3c4 \uc11c\ub85c\uc758 \uc0c1\ud0dc\ub294 \ub3c5\uc11c\uc5d0 \ud568\uaed8 \uc601\ud5a5\uc744 \uc900\ub2e4. \ube0c\ub77c\uc6b0\uc800\ub294 \ubb38\uc11c\uc758 \uad6c\uc870\ub97c \uc77d\uace0 \uc5b4\ub5a4 \ubd80\ubd84\uc5d0 \uc5b4\ub5a4 CSS \uaddc\uce59\uc774 \ud574\ub2f9\ud558\ub294\uc9c0 \uc815\ub9ac\ud55c\ub2e4. \uadf8 \uacb0\uacfc\ub97c \ubc14\ud0d5\uc73c\ub85c \ud654\uba74\uc5d0 \uadf8\ub9b0\ub2e4. \ub3c5\uc790\uac00 \ubcf4\ub294 \uc644\uc131\ub41c \ud398\uc774\uc9c0 \ub4a4\uc5d0\ub294 \ubb38\uc11c\uc640 \ud45c\ud604\uc744 \uc5f0\uacb0\ud558\ub294 \uacfc\uc815\uc774 \uc788\ub294 \uc148\uc774\ub2e4. \ud30c\uc77c\uc5d0 \uc801\ud78c \uae00\uc790\uac00 \uace7\ubc14\ub85c \uac19\uc740 \ubaa8\uc591\uc758 \ud654\uba74\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc6f9\ud398\uc774\uc9c0\uac00 \ud56d\uc0c1 \uac19\uc740 \uc21c\uac04\uc5d0 \ub611\uac19\uc774 \uc644\uc131\ub41c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud544\uc694\ud55c \uc790\ub8cc\uac00 \ub3c4\ucc29\ud558\ub294 \uc870\uac74\uacfc \ud504\ub85c\uadf8\ub7a8\uc758 \uc9c0\uc6d0\ub3c4 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\ub2e4. \uc774\ubc88 \uae00\uc740 \uc791\ub3d9\uc758 \ud070 \uad6c\ubd84\uc744 \uc774\ud574\ud558\ub294 \uc774\uc57c\uae30\ub2e4. \ubcf5\uc7a1\ud55c \ud45c\uc2dc \ubb38\uc81c\ub97c \ud55c \uac00\uc9c0 \uc6d0\uc778\uc73c\ub85c \uc9c4\ub2e8\ud558\ub294 \uc124\uba85\uc740 \uc544\ub2c8\ub2e4. \ud45c\ud604\uc740 \ub208\uae38\uc744 \ub04c\uae30 \uc704\ud55c \uc7a5\uc2dd\uc77c \uc218\ub3c4 \uc788\uc9c0\ub9cc \uc77d\ub294 \uc0ac\ub78c\uc744 \ub3d5\ub294 \uc77c\uc77c \uc218\ub3c4 \uc788\ub2e4. \ub0b4\uc6a9\uc758 \uc911\uc694\ub3c4\uac00 \uad6c\ubd84\ub418\uace0 \ubb38\ub2e8\uc758 \uacbd\uacc4\uac00 \ub290\uaef4\uc9c0\uba74 \ub3c5\uc790\ub294 \uae00\uc758 \uae38\uc744 \ucc3e\uae30 \uc26c\uc6cc\uc9c4\ub2e4. \ud654\ub824\ud568\uacfc \uac00\ub3c5\uc131\uc740 \uac19\uc740 \uae30\uc900\uc774 \uc544\ub2c8\ubbc0\ub85c \ubaa9\uc801\uc744 \ub098\ub204\uc5b4 \ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uac19\uc740 \uc6d0\uace0\uc758 \uc11c\ub85c \ub2e4\ub978 \uc9c0\uba74\uc744 \uc0b4\ud53c\ub294 \ud3b8\uc9d1 \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c \ube0c\ub77c\uc6b0\uc800\uc758 \ud45c\uc2dc \uc2e4\ud5d8\uc774\ub098 \ud2b9\uc815 CSS \ucf54\ub4dc\uc758 \uacb0\uacfc \ud654\uba74\uc740 \uc544\ub2c8\ub2e4. \uae00\uc758 \ub0b4\uc6a9\uacfc \uadf8\uac83\uc744 \ub193\ub294 \ubc29\uc2dd \uc0ac\uc774\uc758 \uad00\uacc4\ub97c \ub5a0\uc62c\ub9ac\ub294 \ubd84\uc704\uae30 \uadf8\ub9bc\uc774\ub2e4. CSS\ub97c \uc54c\uba74 \uc6f9\ud398\uc774\uc9c0\ub97c \ubcfc \ub54c \ubb38\uc7a5\uacfc \ub514\uc790\uc778\uc744 \uc870\uae08 \ub098\ub204\uc5b4 \uc77d\uac8c \ub41c\ub2e4. \uae00\uc774 \uc5b4\ub824\uc6cc\uc11c \uc77d\uae30 \ud798\ub4e0\uc9c0, \ud45c\ud604 \ub54c\ubb38\uc5d0 \uae38\uc744 \uc783\ub294\uc9c0 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \uac19\uc740 \ub0b4\uc6a9\uc774\ub77c\ub3c4 \uadf8\uac83\uc744 \ub9cc\ub098\ub294 \uacbd\ud5d8\uc740 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4. \ub2e4\uc74c\uc5d0 \ub9c8\uc74c\uc5d0 \ub4dc\ub294 \uc77d\uae30 \ud654\uba74\uc744 \ub9cc\ub098\uba74 \uc0c9\ub9cc \ubcf4\uc9c0 \ub9d0\uace0 \uc81c\ubaa9\uc758 \ud06c\uae30\uc640 \uc5ec\ubc31, \ubb38\ub2e8\uc758 \ud3ed\ub3c4 \uc0b4\ud3b4\ubcf4\uc790. \uadf8\uacf3\uc5d0\ub294 \ub3c5\uc790\uc758 \ub208\uc744 \uc5b4\ub5bb\uac8c \uc774\ub04c\uc9c0\uc5d0 \uad00\ud55c \uc120\ud0dd\uc774 \ub4e4\uc5b4 \uc788\ub2e4. CSS\ub294 \uc6f9\uc758 \uae00\uc774 \uc5b4\ub5a4 \uc5bc\uad74\ub85c \uc0ac\ub78c\uc744 \ub9cc\ub0a0\uc9c0 \uc815\ud558\ub294 \uc5ec\ub7ec \uc57d\uc18d \uac00\uc6b4\ub370 \ud558\ub098\ub2e4."}, {"id": "csv-comma-inside-a-cell", "title": "CSV \u2014 \uc27c\ud45c\uac00 \ub4e4\uc5b4 \uc788\ub294 \uce78\uc740 \uc5b4\ub5bb\uac8c \ub098\ub20c\uae4c", "summary": "\ub3c4\uc11c \ubaa9\ub85d\uc758 \uac00\uc0c1 \uc608\ub85c \uad6c\ubd84\uc790\u00b7\ub530\uc634\ud45c\u00b7\ubb38\uc790\uc5f4\uacfc \uc22b\uc790\uc758 \ucc28\uc774\ub97c \uc774\ud574\ud558\uba70 CSV\uc758 \uc6d0\ub9ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\ub370\uc774\ud130\uc640 \uae30\ub85d", "categories": ["digital"], "url": "stories/csv-comma-inside-a-cell/index.html", "image": "../media/csv-comma-inside-a-cell.png", "alt": "\uc0c9\ubcc4\ub85c \ub098\ub208 \uae30\ub85d \uce74\ub4dc\ub97c \uc815\ub9ac\ud558\ub294 \uc0ac\ub78c\uacfc \ub178\ud2b8\ubd81\uc774 \uc788\ub294 \ucc45\uc0c1\uc758 \uc0bd\ud654.", "text": "CSV \u2014 \uc27c\ud45c\uac00 \ub4e4\uc5b4 \uc788\ub294 \uce78\uc740 \uc5b4\ub5bb\uac8c \ub098\ub20c\uae4c \uac04\ub2e8\ud55c \ud45c\ub97c \uc8fc\uace0\ubc1b\uc744 \ub54c \ud544\uc694\ud55c \uc791\uc740 \uc57d\uc18d\ub4e4 \ub3c4\uc11c \ubaa9\ub85d\uc758 \uac00\uc0c1 \uc608\ub85c \uad6c\ubd84\uc790\u00b7\ub530\uc634\ud45c\u00b7\ubb38\uc790\uc5f4\uacfc \uc22b\uc790\uc758 \ucc28\uc774\ub97c \uc774\ud574\ud558\uba70 CSV\uc758 \uc6d0\ub9ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ub370\uc774\ud130\uc640 \uae30\ub85d \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \ub3c4\uc11c \ubaa9\ub85d\uc744 \ub2e4\ub978 \ud504\ub85c\uadf8\ub7a8\uc73c\ub85c \uc62e\uacbc\ub354\ub2c8 \uc81c\ubaa9\uc774 \ub450 \uce78\uc73c\ub85c \uac08\ub77c\uc84c\ub2e4. \uc81c\ubaa9 \uc548\uc5d0 \uc788\ub358 \uc27c\ud45c\uac00 \uce78\uc744 \ub098\ub204\ub294 \ud45c\uc2dc\ucc98\ub7fc \ucc98\ub9ac\ub41c \uac83\uc774\ub2e4. \ub208\uc73c\ub85c \ubcf4\uba74 \ud55c \uc81c\ubaa9\uc778\ub370 \ucef4\ud4e8\ud130\uc5d0\uac8c\ub294 \uc5b4\ub514\uc11c \ud56d\ubaa9\uc774 \ub05d\ub098\ub294\uc9c0 \ubd84\uba85\ud558\uc9c0 \uc54a\uc558\ub358 \uc148\uc774\ub2e4. \ud45c\ub97c \uc8fc\uace0\ubc1b\uc744 \ub54c \uc790\uc8fc \ub9cc\ub098\ub294 CSV\ub294 \uc774 \ubb38\uc81c\ub97c \uc0dd\uac01\ud558\uae30 \uc88b\uc740 \ud615\uc2dd\uc774\ub2e4. \ubcf5\uc7a1\ud55c \uacc4\uc0b0\uc744 \ubc30\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4. \uc27c\ud45c\uc640 \ub530\uc634\ud45c\ub97c \uc5b4\ub5a4 \uc5ed\ud560\ub85c \uc4f8\uc9c0 \uc57d\uc18d\ud558\ub294 \uc791\uc740 \ubb38\uc81c\uac00 \uc5ec\ub7ec \ud504\ub85c\uadf8\ub7a8 \uc0ac\uc774\uc758 \ud611\ub825\uacfc \uc5f0\uacb0\ub41c\ub2e4\ub294 \uc810\uc744 \uc0b4\ud3b4\ubcf4\uc790. CSV\ub294 \uc27c\ud45c\ub85c \uad6c\ubd84\ud55c \uac12\uc774\ub77c\ub294 \ub73b\uc758 \uc774\ub984\uc774\ub2e4. \uc2a4\ud504\ub808\ub4dc\uc2dc\ud2b8\ub098 \ub370\uc774\ud130\ubca0\uc774\uc2a4\uc758 \uc815\ubcf4\ub97c \ub0b4\ubcf4\ub0b4\uace0 \uac00\uc838\uc62c \ub54c \ub110\ub9ac \uc4f0\uc778\ub2e4. \uc5ec\ub7ec \uce78\uc5d0 \ub4e4\uc5b4 \uc788\ub358 \ub0b4\uc6a9\uc744 \uc77c\uc815\ud55c \uad6c\ubd84 \ud45c\uc2dc\ub97c \uc0ac\uc6a9\ud574 \ud14d\uc2a4\ud2b8\ub85c \uc801\ub294 \ubc29\uc2dd\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \uccab \uc774\ud574\uc5d0 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ud654\uba74\uc5d0\uc11c \ubcf8 \ud45c\uc758 \ud14c\ub450\ub9ac\uc640 \uc0c9\uc744 \uadf8\ub300\ub85c \uc62e\uae30\ub294 \uac83\uc774 \ud575\uc2ec\uc740 \uc544\ub2c8\ub2e4. \uac01 \uc904\uacfc \ud56d\ubaa9\uc5d0 \uc5b4\ub5a4 \uac12\uc774 \uc788\ub294\uc9c0\ub97c \uc8fc\uace0\ubc1b\ub294 \ub370 \ucd08\uc810\uc774 \uc788\ub2e4. \ubcf4\uae30 \uc88b\uc740 \uc9c0\uba74\uacfc \uc815\ubcf4\uc758 \uc804\ub2ec\uc740 \ub2e4\ub978 \ubaa9\uc801\uc77c \uc218 \uc788\ub2e4. \uac19\uc740 \ubaa9\ub85d\ub3c4 \uc5b4\ub5a4 \ubd80\ubd84\uc744 \ubcf4\uad00\ud558\ub824\ub294\uc9c0\uc5d0 \ub530\ub77c \ud30c\uc77c\uc758 \ud615\ud0dc\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uac00\uc0c1\uc758 \ucc45 \uc81c\ubaa9\uc744 \u300a\ubc14\ub2e4, \uadf8\ub9ac\uace0 \uc9d1\u300b\uc774\ub77c\uace0 \ud574 \ubcf4\uc790. \uadf8 \ub2e4\uc74c \uce78\uc5d0\ub294 \ub3c4\uc2dc \uc774\ub984 \uc11c\uc6b8\uc744 \ub123\uace0 \uc2f6\ub2e4. \uc81c\ubaa9 \uc18d\uc758 \uc27c\ud45c\uc640 \uce78 \uc0ac\uc774\uc758 \uc27c\ud45c\uac00 \ub611\uac19\uc774 \uc0dd\uacbc\uc73c\ubbc0\ub85c \ub2e8\uc21c\ud788 \uc27c\ud45c\ub97c \ub9cc\ub0a0 \ub54c\ub9c8\ub2e4 \ub098\ub204\uba74 \uc81c\ubaa9\uc774 \ub458\ub85c \uac08\ub77c\uc9c4\ub2e4. \uc774\ub984\ud45c\ub97c \ub530\uc634\ud45c\ub85c \ubb36\ub294 \uc57d\uc18d\uc744 \uc0ac\uc6a9\ud558\uba74 \uadf8 \uc548\ucabd\uc758 \uc27c\ud45c\ub97c \uac12\uc758 \uc77c\ubd80\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \uc774 \uc608\ub97c \uc2e4\uc81c CSV \ud55c \uc904\ub85c \uc801\uc73c\uba74 \"\ubc14\ub2e4, \uadf8\ub9ac\uace0 \uc9d1\",\uc11c\uc6b8\uc774 \ub41c\ub2e4. \uc77d\ub294 \ud504\ub85c\uadf8\ub7a8\uc774 \uac19\uc740 \uc57d\uc18d\uc744 \ub530\ub97c \ub54c \uccab \ud56d\ubaa9\uc740 \uc81c\ubaa9 \uc804\uccb4, \ub450 \ubc88\uc9f8 \ud56d\ubaa9\uc740 \uc11c\uc6b8\ub85c \ub098\ub25c\ub2e4. \ubb38\uc81c\ub294 \ud55c \ub2e8\uacc4 \ub354 \uc774\uc5b4\uc9c4\ub2e4. \ud56d\ubaa9\uc758 \ub0b4\uc6a9\uc5d0 \ub530\uc634\ud45c\uac00 \ub4e4\uc5b4\uac08 \uc218\ub3c4 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uac12\uc758 \uacbd\uacc4\ub97c \uc54c\ub9ac\ub294 \ub530\uc634\ud45c\uc640 \uc2e4\uc81c \ubb38\uc7a5 \uc18d\uc758 \ub530\uc634\ud45c\ub97c \uad6c\ubd84\ud560 \ubc29\ubc95\uc774 \ud544\uc694\ud558\ub2e4. \uac19\uc740 \ud45c\uc2dc\uac00 \ub450 \uc5ed\ud560\uc744 \uac16\uac8c \ub418\uba74 \uc608\uc678\ub97c \ucc98\ub9ac\ud558\ub294 \uc57d\uc18d\ub3c4 \uc0dd\uae34\ub2e4. \ud30c\uc774\uc36c\uc758 CSV \ubb38\uc11c\ub294 \ub530\uc634\ud45c\ub97c \uacb9\uccd0 \uc4f0\ub294 \ubc29\uc2dd\uc774\ub098 \ubcc4\ub3c4\uc758 \ucc98\ub9ac \ud45c\uc2dc\ub97c \uc0ac\uc6a9\ud558\ub294 \uc124\uc815\uc744 \uc124\uba85\ud55c\ub2e4. \ubaa8\ub4e0 \uc138\ubd80\ub97c \uc678\uc6b0\ub294 \uac83\ubcf4\ub2e4 \uc65c \uaddc\uce59\uc774 \ud544\uc694\ud55c\uc9c0 \uc774\ud574\ud558\uba74 \ub41c\ub2e4. \uc0ac\ub78c\uc774 \ubb38\ub9e5\uc73c\ub85c \uc54c\uc544\ubcf4\ub294 \uad6c\ubd84\uc744 \ucef4\ud4e8\ud130\uc5d0\uac8c \ub9e1\uae30\ub824\uba74 \uadf8 \ubb38\ub9e5\uc744 \ub354 \uba85\uc2dc\uc801\uc73c\ub85c \ud45c\ud604\ud574\uc57c \ud558\ub294 \uac83\uc774\ub2e4. \uacf5\uc2dd \ubb38\uc11c\ub294 \ud504\ub85c\uadf8\ub7a8\ub9c8\ub2e4 \uad6c\ubd84\uc790\uc640 \ub530\uc634\ud45c \ub4f1\uc758 \uc138\ubd80\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. CSV\ub77c\ub294 \uc774\ub984\uc744 \uc37c\ub2e4\uace0 \ubaa8\ub4e0 \ud30c\uc77c\uc774 \ud55c \uac00\uc9c0 \ubc29\uc2dd\uc73c\ub85c\ub9cc \ub9cc\ub4e4\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ube44\uc2b7\ud55c \ubaa8\uc591 \uc548\uc5d0\ub3c4 \uc5ec\ub7ec \uad00\ub840\uac00 \uc788\uc5b4\uc11c \uc77d\ub294 \ucabd\uacfc \uc4f0\ub294 \ucabd\uc758 \uc124\uc815\uc774 \ub9de\uc544\uc57c \ud55c\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc5b4\ub5a4 \uc790\ub8cc\ub294 \ud56d\ubaa9 \uad6c\ubd84\uc5d0 \ub2e4\ub978 \ubb38\uc790\ub97c \uc0ac\uc6a9\ud55c\ub2e4. \ud30c\uc774\uc36c\uc740 \uc774\ub7f0 \ucc28\uc774\ub97c \ub2e4\ub8e8\uae30 \uc704\ud55c \uc124\uc815 \ubb36\uc74c\uc744 \uc81c\uacf5\ud55c\ub2e4. \ub3c5\uc790\uac00 \uadf8 \uc124\uc815 \uc774\ub984\uc744 \ubc30\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud30c\uc77c\uc744 \ubc1b\uc558\ub294\ub370 \ud55c \uce78\uc5d0 \ub0b4\uc6a9\uc774 \ubab0\ub9ac\uac70\ub098 \uc5c9\ub6b1\ud558\uac8c \uac08\ub77c\uc9c4\ub2e4\uba74 \uc790\ub8cc\uac00 \uc804\ubd80 \uc0ac\ub77c\uc84c\ub2e4\uace0 \uc0dd\uac01\ud558\uae30 \uc804\uc5d0 \uad6c\ubd84\uc758 \uc57d\uc18d\uc744 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ud45c\uc5d0 0012\uac00 \uc801\ud600 \uc788\ub2e4. \uc774\uac83\uc774 \uc218\ub7c9\uc774\ub77c\uba74 \uc22b\uc790 12\uc640 \uac19\uc740 \uac12\uc744 \ub73b\ud560 \uc218 \uc788\uc9c0\ub9cc, \ubb3c\uac74\uc758 \uc2dd\ubcc4 \ubc88\ud638\ub77c\uba74 \uc55e\uc758 0\uae4c\uc9c0 \uc911\uc694\ud560 \uc218 \uc788\ub2e4. \uac19\uc740 \ubaa8\uc591\uc744 \uc77d\ub294 \ubc29\ubc95\uc5d0 \ub530\ub77c \ub0a8\uaca8\uc57c \ud560 \uc815\ubcf4\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \ubb38\uc790\ub97c \uc22b\uc790\ub85c \ubc14\uafb8\ub294 \uc77c\uc5d0\ub3c4 \ud310\ub2e8\uc774 \ub4e4\uc5b4\uac04\ub2e4. \uacf5\uc2dd \ubb38\uc11c\ub294 \uae30\ubcf8 CSV \uc77d\uae30\uac00 \uac01 \ud56d\ubaa9\uc744 \ubb38\uc790\uc5f4\ub85c \ub3cc\ub824\uc8fc\uba70, \ud2b9\uc815 \uc635\uc158 \uc5c6\uc774 \uc790\ub3d9\uc73c\ub85c \uc790\ub8cc\ud615\uc744 \ubc14\uafb8\uc9c0 \uc54a\ub294\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub2e4\ub978 \ud504\ub85c\uadf8\ub7a8\uc740 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ud574\uc11d\ud560 \uc218 \uc788\ub2e4. \ub530\ub77c\uc11c \uc5b4\ub5a4 \uac12\uc774 \ubcf4\uc600\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8\uac83\uc774 \uc5b4\ub5a4 \uc885\ub958\uc758 \uc815\ubcf4\ub85c \uc77d\ud614\ub294\uc9c0\ub97c \uad6c\ubd84\ud558\ub294 \uc2b5\uad00\uc774 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ub3c4\uc11c \ubaa9\ub85d\uc758 \uccab \uc904\uc5d0 \uc81c\ubaa9\uacfc \ub3c4\uc2dc\ub77c\ub294 \ud56d\ubaa9 \uc774\ub984\uc744 \ub123\uc744 \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \uc904\uc774 \uc124\uba85\uc778\uc9c0 \uc2e4\uc81c \uc790\ub8cc\uc758 \uccab \ud589\uc778\uc9c0\ub294 \uc77d\ub294 \ubc29\uc2dd\uc5d0 \ub2ec\ub824 \uc788\ub2e4. \ud30c\uc774\uc36c\uc758 \uc0ac\uc804 \ud615\ud0dc \uc77d\uae30\ub294 \uccab \ud589\uc744 \ud56d\ubaa9 \uc774\ub984\uc73c\ub85c \uc0ac\uc6a9\ud558\ub294 \ubc29\ubc95 \ub4f1\uc744 \uc81c\uacf5\ud55c\ub2e4. \ub2e8\uc21c\ud55c \uc904\uc5d0\ub3c4 \uc5ed\ud560\uc744 \uc815\ud558\ub294 \uc120\ud0dd\uc774 \uc788\ub294 \uac83\uc774\ub2e4. \ubaa9\ub85d\uc744 \uc798 \uc804\ub2ec\ud558\ub824\uba74 \ud30c\uc77c \ud558\ub098\ubfd0 \uc544\ub2c8\ub77c \uc5f4\uc758 \uc758\ubbf8\ub3c4 \ubd84\uba85\ud574\uc57c \ud55c\ub2e4. \uac19\uc740 \ub3c4\uc2dc\ub77c\ub294 \uce78\uc5d0 \ucd9c\uc0dd\uc9c0\uc640 \ucd9c\ud310\uc9c0\ub97c \uc11e\uc73c\uba74 \ud615\uc2dd\uc774 \uc815\uc0c1\uc774\uc5b4\ub3c4 \ub0b4\uc6a9\uc740 \uc624\ud574\ub420 \uc218 \uc788\ub2e4. \ucef4\ud4e8\ud130\uac00 \uc798 \ub098\ub204\uc5b4 \uc77d\ub294 \uc77c\uacfc \uc0ac\ub78c\uc774 \uac19\uc740 \ub73b\uc73c\ub85c \uc774\ud574\ud558\ub294 \uc77c\uc740 \uc11c\ub85c \ub2e4\ub978 \ud655\uc778\uc774\ub2e4. \uc774 \uc6d0\uace0\uc758 \uac00\uc0c1 \uc81c\ubaa9\uacfc \uc11c\uc6b8\uc744 \ub123\uc740 \ud55c \uc904\uc740 \ud30c\uc774\uc36c CSV \uc77d\uae30\ub85c \uc9c1\uc811 \ud655\uc778\ud588\ub2e4. \uccab \ud56d\ubaa9\uc774 \ubc14\ub2e4, \uadf8\ub9ac\uace0 \uc9d1\uc73c\ub85c \uc720\uc9c0\ub418\ub294\uc9c0, \ub450 \ubc88\uc9f8\uac00 \uc11c\uc6b8\uc778\uc9c0 \ube44\uad50\ud588\ub2e4. \uc544\uc8fc \uc791\uc740 \uac80\uc0b0\uc774\uc9c0\ub9cc \ub9d0\ub85c \uc124\uba85\ud55c \uaddc\uce59\uc774 \uc2e4\uc81c \uc608\uc640 \ub9de\ub294\uc9c0 \uc0b4\ud53c\ub294 \uacfc\uc815\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uae30\ub85d \uce74\ub4dc\ub97c \uc815\ub9ac\ud558\ub294 \ubd84\uc704\uae30\ub97c \ud45c\ud604\ud55c\ub2e4. \uc2e4\uc81c CSV \ud30c\uc77c\uc774\ub098 \ud504\ub85c\uadf8\ub7a8\uc758 \uc2e4\ud589 \uacb0\uacfc\ub97c \uadf8\ub9b0 \ub3c4\uc2dd\uc740 \uc544\ub2c8\ub2e4. \uce74\ub4dc\uac00 \ub098\ub258\uc5b4 \uc788\uc5b4\uc57c \uc815\ub9ac\ud558\uae30 \uc26c\uc6b4 \uac83\ucc98\ub7fc, \ud14d\uc2a4\ud2b8\uc758 \uac12\uc5d0\ub3c4 \uc11c\ub85c \ud569\uc758\ud55c \uacbd\uacc4\uac00 \ud544\uc694\ud558\ub2e4\ub294 \uc0dd\uac01\uc744 \ub5a0\uc62c\ub9ac\ub294 \uadf8\ub9bc\uc774\ub2e4. CSV\uc758 \ub9e4\ub825\uc740 \ube44\uad50\uc801 \ub2e8\uc21c\ud55c \ud14d\uc2a4\ud2b8\ub85c \uc5ec\ub7ec \ub3c4\uad6c \uc0ac\uc774\uc5d0 \ud45c\uc758 \uac12\uc744 \uc62e\uae38 \uc218 \uc788\ub2e4\ub294 \ub370 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ub2e8\uc21c\ud558\ub2e4\ub294 \ub9d0\uc774 \uc544\ubb34 \uaddc\uce59\ub3c4 \uc5c6\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc27c\ud45c\uc640 \ub530\uc634\ud45c, \uccab \uc904\uacfc \uc790\ub8cc\ud615\uc5d0 \uad00\ud55c \uc120\ud0dd\uc774 \uc11c\ub85c \ub9de\uc544\uc57c \ud55c\ub2e4. \ub2e4\uc74c\uc5d0 \ub0b4\ub824\ubc1b\uc740 \ubaa9\ub85d\uc774 \uc5c9\ucf1c \ubcf4\uc774\uba74 \uc774 \uc791\uc740 \uc57d\uc18d\ub4e4\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ub0b4\uc6a9\uc774 \ud2c0\ub838\ub294\uc9c0, \ub098\ub204\uc5b4 \uc77d\ub294 \ubc29\uc2dd\uc774 \ub2ec\ub790\ub294\uc9c0 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \uc27c\ud45c \ud558\ub098\uc758 \uc790\ub9ac\ub97c \uc774\ud574\ud558\ub294 \uc77c\uc740 \ucef4\ud4e8\ud130\uac00 \uc815\ubcf4\ub97c \uc8fc\uace0\ubc1b\uc744 \ub54c \uc5bc\ub9c8\ub098 \uad6c\uccb4\uc801\uc778 \ud569\uc758\uac00 \ud544\uc694\ud55c\uc9c0 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "dns-names-and-addresses", "title": "DNS \u2014 \uc0ac\uc774\ud2b8\ub294 \uc774\uc0ac\ud574\ub3c4 \uc774\ub984\uc744 \uc720\uc9c0\ud560 \uc218 \uc788\uc744\uae4c", "summary": "\ub3c4\uba54\uc778 \uc774\ub984\uacfc \uc11c\ubc84 \uc8fc\uc18c, \uc784\uc2dc \uc800\uc7a5\uc744 \ud1b5\ud574 \uc6f9\uc0ac\uc774\ud2b8 \uc774\ub984\uc774 \uc5f0\uacb0\ub418\ub294 \uc6d0\ub9ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\uc778\ud130\ub137\uacfc \ud1b5\uc2e0", "categories": ["digital"], "url": "stories/dns-names-and-addresses/index.html", "image": "../media/dns-names-and-addresses.png", "alt": "\uc8fc\uc18c \uce74\ub4dc\ub97c \ub4e4\uace0 \ub178\ud2b8\ubd81\uacfc \ucc3d\ubc16\uc758 \uac70\ub9ac \ud48d\uacbd\uc744 \ubc14\ub77c\ubcf4\ub294 \uc0ac\ub78c\uc758 AI \ube44\uc720 \uc7a5\uba74.", "text": "DNS \u2014 \uc0ac\uc774\ud2b8\ub294 \uc774\uc0ac\ud574\ub3c4 \uc774\ub984\uc744 \uc720\uc9c0\ud560 \uc218 \uc788\uc744\uae4c \uc678\uc6b0\uae30 \uc26c\uc6b4 \uc774\ub984 \ub4a4\uc5d0\uc11c \uc8fc\uc18c\ub97c \ucc3e\uc544 \uc8fc\ub294 \uc57d\uc18d \ub3c4\uba54\uc778 \uc774\ub984\uacfc \uc11c\ubc84 \uc8fc\uc18c, \uc784\uc2dc \uc800\uc7a5\uc744 \ud1b5\ud574 \uc6f9\uc0ac\uc774\ud2b8 \uc774\ub984\uc774 \uc5f0\uacb0\ub418\ub294 \uc6d0\ub9ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uc778\ud130\ub137\uacfc \ud1b5\uc2e0 \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \uc88b\uc544\ud558\ub358 \uac00\uac8c\uac00 \ub2e4\ub978 \uac74\ubb3c\ub85c \uc774\uc0ac\ud588\ub2e4. \uac04\ud310\uc758 \uc774\ub984\uc740 \uadf8\ub300\ub85c\uc9c0\ub9cc \ucc3e\uc544\uac08 \uc8fc\uc18c\ub294 \ub2ec\ub77c\uc84c\ub2e4. \uc6f9\uc0ac\uc774\ud2b8\uc5d0\ub3c4 \ube44\uc2b7\ud55c \uad6c\ubd84\uc774 \uc788\ub2e4. \uc6b0\ub9ac\uac00 \uae30\uc5b5\ud558\ub294 \uc774\ub984\uacfc \uc2e4\uc81c\ub85c \uc811\uc18d\ud560 \uc11c\ubc84\uc758 \uc8fc\uc18c\uac00 \ubc18\ub4dc\uc2dc \uac19\uc740 \uc885\ub958\uc758 \uc815\ubcf4\ub294 \uc544\ub2c8\ub77c\ub294 \uc810\uc774\ub2e4. knowledgewalk.net\ucc98\ub7fc \uc77d\uace0 \uae30\uc5b5\ud558\uae30 \uc26c\uc6b4 \uc774\ub984\uc744 \ub3c4\uba54\uc778 \uc774\ub984\uc774\ub77c\uace0 \ud55c\ub2e4. \ucef4\ud4e8\ud130\uac00 \ud1b5\uc2e0\ud560 \ub54c \uc4f0\ub294 IP \uc8fc\uc18c\ub294 \ubcc4\ub3c4\ub85c \uc788\ub2e4. DNS\ub294 \uc774 \ub458\uc744 \uc5f0\uacb0\ud574 \ud544\uc694\ud55c \uc815\ubcf4\ub97c \ucc3e\ub3c4\ub85d \ub3d5\ub294 \uccb4\uacc4\ub2e4. \uc790\uc8fc \uc811\ud558\ub294 \uc774\ub984 \ud558\ub098\uc758 \ub4a4\uc5d0 \uc5b4\ub5a4 \uc77c\uc774 \uc788\ub294\uc9c0 \ucc9c\ucc9c\ud788 \ub530\ub77c\uac00 \ubcf4\uc790. IP \uc8fc\uc18c\ub294 \uc778\ud130\ub137\uc5d0\uc11c \ub370\uc774\ud130\ub97c \uc8fc\uace0\ubc1b\ub294 \ub370 \ud544\uc694\ud55c \uc8fc\uc18c\ub2e4. \ucef4\ud4e8\ud130\ub294 \uc774\ub7f0 \uac12\uc744 \ub2e4\ub8e8\uc9c0\ub9cc \uc0ac\ub78c\uc774 \ubc29\ubb38\ud558\uace0 \uc2f6\uc740 \uc0ac\uc774\ud2b8\ub9c8\ub2e4 \uae34 \uc22b\uc790\ub098 \uae30\ud638\ub97c \uc678\uc6b0\ub294 \uac83\uc740 \ubd88\ud3b8\ud558\ub2e4. \uc8fc\uc18c\uac00 \ubc14\ub014 \ub54c\ub9c8\ub2e4 \ub2e4\uc2dc \uae30\uc5b5\ud574\uc57c \ud55c\ub2e4\uba74 \ub354 \ubc88\uac70\ub86d\ub2e4. \ub3c4\uba54\uc778 \uc774\ub984\uc740 \uc774 \ubb38\uc81c\ub97c \uc904\uc5ec \uc900\ub2e4. \uc0ac\ub78c\uc740 \uc775\uc219\ud55c \uc774\ub984\uc744 \uc0ac\uc6a9\ud558\uace0 \uae30\uacc4\ub294 \uc5f0\uacb0\ub41c \uc8fc\uc18c \uc815\ubcf4\ub97c \ucc3e\uc544 \ud1b5\uc2e0\ud560 \uc218 \uc788\ub2e4. \uc774\ub984\uc774 \uace7\ubc14\ub85c \uc6f9\ud398\uc774\uc9c0\uc758 \ub0b4\uc6a9\uc744 \ub2f4\uace0 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub514\ub85c \ucc3e\uc544\uac08\uc9c0\uc5d0 \uad00\ud55c \uc815\ubcf4\ub97c \uc5bb\ub294 \uc785\uad6c\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \ub41c\ub2e4. DNS\ub97c \uc804\ud654\ubc88\ud638\ubd80\uc5d0 \ube44\uc720\ud558\uba74 \uccab \uc774\ud574\uc5d0\ub294 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uc774\ub984\uc744 \ubcf4\uace0 \ud544\uc694\ud55c \uc8fc\uc18c\ub97c \uc5bb\uae30 \ub54c\ubb38\uc774\ub2e4. \ud558\uc9c0\ub9cc \uc804 \uc138\uacc4\uc758 \ubaa8\ub4e0 \uc815\ubcf4\uac00 \ud55c \uad8c\uc758 \ucc45\ucc98\ub7fc \ud55c \ucef4\ud4e8\ud130\uc5d0\ub9cc \ub4e4\uc5b4 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. DNS\ub294 \uacc4\uce35\uc801\uc73c\ub85c \ub098\ub25c \ubd84\uc0b0 \uccb4\uacc4\ub2e4. \uc5ec\ub7ec \uc11c\ubc84\uac00 \uac01\uc790\uc758 \uc5ed\ud560\uc744 \ub9e1\uc544 \uc774\ub984\uacfc \uad00\ub828\ub41c \uc815\ubcf4\ub97c \uc81c\uacf5\ud55c\ub2e4. \ub2e4\ub978 \uc885\ub958\uc758 \uc815\ubcf4\ub3c4 \ub2e4\ub8e8\uc9c0\ub9cc, \uc5ec\uae30\uc11c\ub294 \uc0ac\uc774\ud2b8\uc758 \uc774\ub984\uc73c\ub85c \uc811\uc18d \uc8fc\uc18c\ub97c \ucc3e\ub294 \uae30\ub2a5\uc744 \uc911\uc2ec\uc73c\ub85c \ubcf4\uba74 \ucda9\ubd84\ud558\ub2e4. \uc804\ud654\ubc88\ud638\ubd80\ub77c\ub294 \ube44\uc720\ub294 \ucc3e\ub294 \ud589\uc704\ub97c \uc124\uba85\ud560 \ubfd0 \uc2e4\uc81c \uad6c\uc870 \uc804\uccb4\ub97c \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub3c4\uba54\uc778\uc740 \uc810\uc73c\ub85c \ub098\ub25c \ubd80\ubd84\ub4e4\ub85c \uad6c\uc131\ub41c\ub2e4. \uc608\ub97c \ub4e4\uc5b4 knowledgewalk.net\uc5d0\uc11c\ub294 \uc624\ub978\ucabd\uc758 net\uc774 \ucd5c\uc0c1\uc704 \ub3c4\uba54\uc778\uc774\ub2e4. \uadf8 \uc55e\uc758 \uc774\ub984\uacfc \uacb0\ud569\ud574 \uc6b0\ub9ac\uac00 \uc774\uc6a9\ud558\ub294 \ub3c4\uba54\uc778\uc774 \ub41c\ub2e4. \ub354 \uc55e\uc5d0 \ub2e4\ub978 \ubd80\ubd84\uc744 \ubd99\uc5ec \ud558\uc704 \ub3c4\uba54\uc778\uc744 \ub9cc\ub4e4 \uc218\ub3c4 \uc788\ub2e4. \uc624\ub978\ucabd\uc5d0\uc11c \uc67c\ucabd\uc73c\ub85c \ubc94\uc704\ub97c \uc881\ud600 \ubcf8\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uad6c\uc870\uac00 \uc870\uae08 \ud3b8\ud574\uc9c4\ub2e4. \ub2e4\ub9cc net\uc774\ub77c\ub294 \ub05d\ubd80\ubd84\uc774 \uc788\ub2e4\uace0 \uadf8 \uc0ac\uc774\ud2b8\uac00 \ud2b9\uc815\ud55c \ud488\uc9c8\uc774\ub098 \ubaa9\uc801\uc744 \ubcf4\uc99d\ubc1b\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774\ub984\uc744 \uad00\ub9ac\ud558\ub294 \uccb4\uacc4\uc640 \uc0ac\uc774\ud2b8\uc5d0 \uc2e4\ub9b0 \ub0b4\uc6a9\uc758 \uc2e0\ub8b0\uc131\uc740 \ubcc4\ub3c4\uc758 \ubb38\uc81c\ub2e4. \ube0c\ub77c\uc6b0\uc800\uc5d0 \uc0ac\uc774\ud2b8 \uc774\ub984\uc744 \uc785\ub825\ud588\uc744 \ub54c \uc8fc\uc18c \uc815\ubcf4\ub97c \uc774\ubbf8 \uc54c\uace0 \uc788\ub2e4\uba74 \uc800\uc7a5\ud574 \ub454 \uacb0\uacfc\ub97c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4. \ubaa8\ub978\ub2e4\uba74 DNS \uc870\ud68c\ub97c \ud1b5\ud574 \ud544\uc694\ud55c \uc815\ubcf4\ub97c \uad6c\ud55c\ub2e4. \uc774\ub984\uacfc \uc8fc\uc18c\uc758 \uc5f0\uacb0\uc744 \ucc3e\uc740 \ub4a4\uc5d0\uc57c \uadf8 \uc8fc\uc18c\uc758 \uc11c\ubc84\uc640 \ub0b4\uc6a9\uc744 \uc8fc\uace0\ubc1b\ub294 \ub2e4\uc74c \ub2e8\uacc4\ub85c \uc774\uc5b4\uc9c4\ub2e4. \uc6b0\ub9ac\ub294 \uc774 \uacfc\uc815 \ub300\ubd80\ubd84\uc744 \ubcf4\uc9c0 \uc54a\ub294\ub2e4. \ud654\uba74\uc5d0\ub294 \uc8fc\uc18c \uc785\ub825\uacfc \ud398\uc774\uc9c0 \ud45c\uc2dc\ub9cc \uc774\uc5b4\uc838 \ubcf4\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \uadf8\ub7ec\ub098 \uc774\ub984\uc744 \ucc3e\ub294 \uc77c\uacfc \uc2e4\uc81c \ud398\uc774\uc9c0\ub97c \ubc1b\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uac04\ud310\uc758 \uc8fc\uc18c\ub97c \uc54c\uc544\ub0b4\ub294 \uac83\uacfc \uac00\uac8c \uc548\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \uac83\uc744 \uad6c\ubd84\ud558\uba74 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \uc6f9\uc0ac\uc774\ud2b8\uc758 \ud30c\uc77c\uc744 \ub2e4\ub978 \uc11c\ubc84\ub85c \uc62e\uaca8\ub3c4 \ub3c4\uba54\uc778 \uc774\ub984\uc744 \uacc4\uc18d \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4. \uc774\ub984\uacfc \uc5f0\uacb0\ub418\ub294 \uc8fc\uc18c \uc815\ubcf4\ub97c \uc0c8 \ud658\uacbd\uc5d0 \ub9de\ucd94\ub294 \ubc29\uc2dd\uc774\ub2e4. \ubc29\ubb38\uc790\ub294 \uc775\uc219\ud55c \uc774\ub984\uc744 \uc785\ub825\ud558\uc9c0\ub9cc \uc2e4\uc81c \ud398\uc774\uc9c0\ub97c \uc81c\uacf5\ud558\ub294 \uc7a5\uc18c\ub294 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 DNS \uc124\uc815\ub9cc \ubc14\uafb8\uba74 \uae00\uacfc \uc0ac\uc9c4\uc774 \uc800\uc808\ub85c \ubcf5\uc0ac\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0c8 \uc11c\ubc84\uc5d0 \uc0ac\uc774\ud2b8\ub97c \uc900\ube44\ud558\ub294 \uc791\uc5c5\uacfc \uc774\ub984\uc774 \uadf8\uacf3\uc744 \uac00\ub9ac\ud0a4\uac8c \ud558\ub294 \uc791\uc5c5\uc774 \uac01\uac01 \ud544\uc694\ud558\ub2e4. \uc774 \ucc28\uc774\ub97c \uc54c\uba74 \ub3c4\uba54\uc778\uc744 \uc0c0\ub2e4\ub294 \ub9d0\uacfc \ud648\ud398\uc774\uc9c0\ub97c \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \ub9d0\uc774 \uc65c \uac19\uc740 \ub73b\uc774 \uc544\ub2cc\uc9c0\ub3c4 \ubcf4\uc778\ub2e4. DNS \uc815\ubcf4\ub294 \ub9e4\ubc88 \ubaa8\ub4e0 \ub2e8\uacc4\ub97c \uc0c8\ub85c \uc870\ud68c\ud558\uc9c0 \uc54a\ub3c4\ub85d \uc77c\uc815 \uc2dc\uac04 \uc800\uc7a5\ub418\uae30\ub3c4 \ud55c\ub2e4. \uc774\ub97c \uce90\uc2dc\ub77c\uace0 \ud55c\ub2e4. \uc8fc\uc18c\ub97c \ubc14\uafbc \ub4a4\uc5d0\ub3c4 \uc5b4\ub5a4 \uacf3\uc5d0\uc11c\ub294 \uc774\uc804\uc5d0 \uc800\uc7a5\ud574 \ub454 \ub2f5\uc744 \uc7a0\uc2dc \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \uc0ac\ub78c\ub9c8\ub2e4 \uc0c8 \uc5f0\uacb0\uc744 \ud655\uc778\ud558\ub294 \uc2dc\uc810\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc774\ub97c \uc804 \uc138\uacc4\uc758 \ubaa8\ub4e0 DNS \uc11c\ubc84\uac00 \ud55c\uaebc\ubc88\uc5d0 \uac19\uc740 \ud30c\uc77c\uc744 \ub0b4\ub824\ubc1b\ub294 \uacfc\uc815\uc73c\ub85c \uc0c1\uc0c1\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc800\uc7a5\ub41c \uacb0\uacfc\uc758 \uc720\uc9c0 \uc2dc\uac04\uacfc \uc870\ud68c \uacbd\ub85c\uac00 \uc601\ud5a5\uc744 \uc900\ub2e4. \ub610\ud55c \uc608\uc804 \ud654\uba74\uc774 \ubcf4\uc774\ub294 \uc6d0\uc778\uc740 \uc6f9\ud398\uc774\uc9c0 \uc790\uccb4\uc758 \uc784\uc2dc \uc800\uc7a5 \ub4f1 \ub2e4\ub978 \ub370 \uc788\uc744 \uc218\ub3c4 \uc788\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \ud604\uc0c1 \ud558\ub098\uac00 \uc6d0\uc778 \ud558\ub098\ub97c \ubc14\ub85c \uc54c\ub824 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. DNS\uac00 \uc8fc\uc18c\ub97c \uc54c\ub824 \uc8fc\uc5c8\ub2e4\uace0 \uadf8 \uc0ac\uc774\ud2b8\uac00 \ud56d\uc0c1 \uc815\uc0c1\uc801\uc73c\ub85c \uc6b4\uc601\ub41c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc8fc\uc18c\ub97c \ucc3e\uc740 \ub4a4\uc5d0\ub3c4 \uc11c\ubc84\uac00 \uc751\ub2f5\ud574\uc57c \ud558\uace0 \ud544\uc694\ud55c \ud30c\uc77c\uc774 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uc2e4\uc81c \uc11c\ube44\uc2a4\ub97c \uc774\ub8e8\ub294 \uc5ec\ub7ec \uc870\uac74 \uac00\uc6b4\ub370 \uc774\ub984\uc744 \uc5f0\uacb0\ud558\ub294 \uc5ed\ud560\uc774 \ub530\ub85c \uc788\ub294 \uac83\uc774\ub2e4. \ubc18\ub300\ub85c \ub3c4\uba54\uc778 \uc774\ub984\uc744 \uc774\uc6a9\ud560 \uad8c\ub9ac\ub97c \uc720\uc9c0\ud558\ub294 \uc77c\ub3c4 \ud544\uc694\ud558\ub2e4. MDN\uc740 \ud754\ud788 \ub3c4\uba54\uc778\uc744 \uc0b0\ub2e4\uace0 \ub9d0\ud558\uc9c0\ub9cc, \uc2e4\uc81c\ub85c\ub294 \uc77c\uc815 \uae30\uac04 \uc0ac\uc6a9\ud558\ub3c4\ub85d \ub4f1\ub85d\ud558\uace0 \uac31\uc2e0\ud558\ub294 \uac83\uc774\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \uc774\ub984\uc744 \uae30\uc5b5\ud558\ub294 \ubc29\ubb38\uc790\uc640 \uadf8 \uc774\ub984\uc744 \uacc4\uc18d \uc0ac\uc6a9\ud560 \uc218 \uc788\uac8c \uad00\ub9ac\ud558\ub294 \uc6b4\uc601\uc790\uc758 \uc77c\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc8fc\uc18c \uce74\ub4dc\ub97c \ubcf4\uace0 \uc7a5\uc18c\ub97c \ucc3e\ub294 \ubd84\uc704\uae30\ub97c \ud45c\ud604\ud588\ub2e4. \uc2e4\uc81c DNS \uc11c\ubc84\uc758 \uad6c\uc870\ub098 \ud504\ub85c\uadf8\ub7a8 \ud654\uba74\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ub3c4\uc2dd\uc740 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\uc774 \uae30\uc5b5\ud558\ub294 \uc774\ub984\uacfc \ucc3e\uc544\uac08 \uacf3\uc744 \uc5f0\uacb0\ud55c\ub2e4\ub294 \uc0dd\uac01\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc704\ud55c \uadf8\ub9bc\uc774\ub2e4. \uc6b0\ub9ac\ub294 \uc8fc\uc18c\ub85d\uc758 \uc6d0\ub9ac\ub97c \ub9e4\ubc88 \uc0dd\uac01\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc0ac\ub78c\uc744 \ucc3e\uc544 \uc5f0\ub77d\ud55c\ub2e4. \uc0ac\uc774\ud2b8 \uc774\ub984\ub3c4 \ube44\uc2b7\ud558\ub2e4. \uc811\uc18d\ud558\ub294 \uc7a5\uc18c\uac00 \ubc14\ub014 \uc218 \uc788\uc5b4\ub3c4 \uc775\uc219\ud55c \uc774\ub984\uc744 \uacc4\uc18d \uc0ac\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d \uc911\uac04\uc758 \uc57d\uc18d\uc774 \uc791\ub3d9\ud55c\ub2e4. DNS\ub294 \ub208\uc5d0 \uc798 \ubcf4\uc774\uc9c0 \uc54a\uc9c0\ub9cc, \uc6f9\uc5d0\uc11c \uc6b0\ub9ac\uac00 \uc774\ub984\uc744 \uae30\uc5b5\ud558\ub294 \ubc29\uc2dd\uc744 \uac00\ub2a5\ud558\uac8c \ud55c\ub2e4."}, {"id": "email-at-sign", "title": "\uc774\uba54\uc77c \uc8fc\uc18c\uc5d0\ub294 \uc65c \uace8\ubc45\uc774\uac00 \ub4e4\uc5b4\uac08\uae4c", "summary": "\uba54\uc77c \uc8fc\uc18c\ub97c \ub9d0\ud560 \ub54c \uaf2d \ub4f1\uc7a5\ud558\ub294 @. \uc774\uba54\uc77c\uc744 \uc704\ud574 \uc0c8\ub85c \uadf8\ub9b0 \uae30\ud638\ub294 \uc544\ub2d9\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\uc778\ud130\ub137\uacfc \ud1b5\uc2e0", "categories": ["digital"], "url": "stories/email-at-sign/index.html", "image": "../media/email-at-sign.jpg", "alt": "\uc774\uba54\uc77c \uc8fc\uc18c\uc5d0\ub294 \uc65c \uace8\ubc45\uc774\uac00 \ub4e4\uc5b4\uac08\uae4c \u2014 \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\uc774\uba54\uc77c \uc8fc\uc18c\uc5d0\ub294 \uc65c \uace8\ubc45\uc774\uac00 \ub4e4\uc5b4\uac08\uae4c \uc775\uc219\ud55c \uae30\ud638 \ud558\ub098\uac00 \uc0ac\ub78c\uacfc \ucef4\ud4e8\ud130\ub97c \ub098\ub204\uac8c \ub41c \uc0ac\uc5f0 \uba54\uc77c \uc8fc\uc18c\ub97c \ub9d0\ud560 \ub54c \uaf2d \ub4f1\uc7a5\ud558\ub294 @. \uc774\uba54\uc77c\uc744 \uc704\ud574 \uc0c8\ub85c \uadf8\ub9b0 \uae30\ud638\ub294 \uc544\ub2d9\ub2c8\ub2e4. \uc778\ud130\ub137\uacfc \ud1b5\uc2e0 \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \uc804\ud654\ubc88\ud638\ub97c \ubd88\ub7ec\uc904 \ub54c\ub294 \uc22b\uc790\ub97c \uc774\uc5b4 \ub9d0\ud558\uba74 \ub41c\ub2e4. \uc774\uba54\uc77c \uc8fc\uc18c\ub97c \uc54c\ub824\uc904 \ub54c\ub294 \uc911\uac04\uc5d0 \uac11\uc790\uae30 \uc74c\uc2dd \uc774\ub984 \uac19\uc740 \ub9d0\uc774 \ub07c\uc5b4\ub4e0\ub2e4. \uace8\ubc45\uc774. \uc6b0\ub9ac\uac00 \uace8\ubc45\uc774\ub77c\uace0 \ubd80\ub974\ub294 @\ub294 \uba54\uc77c \uc8fc\uc18c\uc5d0\uc11c \uc544\uc8fc \uc775\uc219\ud55c \uae30\ud638\ub2e4. \uc18c\ubb38\uc790 a\ub97c \uc120 \ud558\ub098\uac00 \uac10\uc2f8\uace0 \uc788\ub294 \ubaa8\uc591\uc774\ub2e4. \ucef4\ud4e8\ud130 \ud654\uba74\uc5d0\uc11c\ub9cc \ubcf4\ub358 \uc0ac\ub78c\uc774\ub77c\uba74 \uc774\uba54\uc77c\uacfc \ud568\uaed8 \ud0dc\uc5b4\ub09c \uadf8\ub9bc\ucc98\ub7fc \ub290\ub084 \uc218\ub3c4 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc774 \uae30\ud638\ub294 \uc774\uba54\uc77c\ubcf4\ub2e4 \ub098\uc774\uac00 \ub9ce\ub2e4. \ub204\uad70\uac00 \uc0c8\ub85c \ub514\uc790\uc778\ud55c \uc791\uc740 \uc778\ud130\ub137 \ub85c\uace0\uac00 \uc544\ub2c8\uc5c8\ub2e4. \ud1b0\ub9b0\uc2a8\uc774 \uc4f0\ub358 \ubaa8\ub378 33 \ud154\ub808\ud0c0\uc774\ud504\uc758 \ud0a4\ubcf4\ub4dc\uc5d0\ub294 \uc774\ubbf8 @\uac00 \uc788\uc5c8\ub2e4. \uc778\ud130\ub137 \uba85\uc608\uc758 \uc804\ub2f9\uc758 \uc5f0\ud601\uc740 \uadf8\uac00 \uc774 \uae30\uacc4\uc758 \ubb38\uc7a5\ubd80\ud638 \ud0a4 \uac00\uc6b4\ub370\uc11c @\ub97c \uace8\ub790\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc0c8\ub85c\uc6b4 \ud1b5\uc2e0 \ubc29\ubc95\uc744 \ub9cc\ub4e4\uba74\uc11c \ubaa8\ub4e0 \ud45c\uc2dc\uae4c\uc9c0 \uc0c8\ub85c \uadf8\ub9b4 \ud544\uc694\ub294 \uc5c6\uc5c8\ub358 \uac83\uc774\ub2e4. 1971\ub144, \uc11c\ub85c \ub2e4\ub978 \ucef4\ud4e8\ud130 \uc0ac\uc774\uc5d0\uc11c \uc804\uc790\uc6b0\ud3b8\uc744 \ubcf4\ub0b4\ub294 \uc77c\uc744 \uac1c\ubc1c\ud558\ub358 \ub808\uc774 \ud1b0\ub9b0\uc2a8\uc740 \uc8fc\uc18c \uc548\uc5d0\uc11c \uc0ac\ub78c\uc758 \uc774\ub984\uacfc \ucef4\ud4e8\ud130\uc758 \uc774\ub984\uc744 \uad6c\ubd84\ud560 \ud45c\uc2dc\uac00 \ud544\uc694\ud588\ub2e4. \uadf8\uac00 \uace0\ub978 \uac83\uc774 @\uc600\ub2e4. \ud0a4\ubcf4\ub4dc\uc5d0 \uc774\ubbf8 \uc788\uc5c8\uace0, \uc774\ub984\uacfc \uae30\uacc4\uc758 \uc704\uce58\ub97c \ub098\ub204\ub294 \ub370 \uc54c\ub9de\uc558\ub2e4. \uc601\uc5b4\uc758 at\uc774 \uc8fc\ub294 \ub73b\ub3c4 \uc798 \uc5b4\uc6b8\ub838\ub2e4. \uc5b4\ub290 \ucef4\ud4e8\ud130\uc5d0 \uc788\ub294 \ub204\uad6c\ub77c\ub294 \uad00\uacc4\ub97c \ud45c\ud604\ud560 \uc218 \uc788\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4. \ubcf5\uc7a1\ud55c \uc0c8 \uae30\ud638\ub97c \ub9cc\ub4e4\uc9c0 \uc54a\uace0 \uc788\ub294 \uac83\uc744 \uace8\ub790\ub2e4\ub294 \uc810\uc774 \uc7ac\ubbf8\uc788\ub2e4. \uc9c0\uae08\uc740 \uc778\ud130\ub137\uc744 \ub300\ud45c\ud558\ub294 \uac83\ucc98\ub7fc \ubcf4\uc774\ub294 \ud45c\uc2dc\ub3c4 \ucc98\uc74c\uc5d0\ub294 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud55c \uc791\uc740 \uc120\ud0dd\uc774\uc5c8\ub2e4. \uc544\uc8fc \ub2e8\uc21c\ud55c \uc608\ub85c user@example.org\ub77c\ub294 \uc8fc\uc18c\ub97c \uc0dd\uac01\ud574 \ubcf4\uc790. @ \uc55e\ucabd\uc740 \uba54\uc77c\uc744 \ubc1b\uc744 \uacc4\uc815\uc5d0 \ud574\ub2f9\ud558\uace0, \ub4a4\ucabd\uc740 \uba54\uc77c \uc2dc\uc2a4\ud15c\uc758 \ub3c4\uba54\uc778\uc5d0 \ud574\ub2f9\ud55c\ub2e4. \uc0c1\uc138\ud55c \uae30\uc220\uc740 \ub354 \ubcf5\uc7a1\ud558\uc9c0\ub9cc, \uc8fc\uc18c\ub97c \uc77d\ub294 \uccab\uac78\uc74c\uc73c\ub85c\ub294 \uc774 \uad6c\ubd84\uc774\uba74 \ucda9\ubd84\ud558\ub2e4. \uadf8\ub807\ub2e4\uace0 @ \ub4a4\uc5d0 \uc2e4\uc81c \uc0ac\ubb34\uc2e4\uc774\ub098 \uac70\ub9ac \uc8fc\uc18c\uac00 \ub4e4\uc5b4 \uc788\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc6b0\ub9ac\uac00 \uc6f9\uc0ac\uc774\ud2b8 \uc774\ub984\uc73c\ub85c \uc775\uc219\ud558\uac8c \ubcf4\ub294 \uac83\uacfc \uac19\uc740 \uc885\ub958\uc758 \uc774\ub984\uc774\ub2e4. \uc6b0\ud3b8\ubc88\ud638\ub97c \uc801\ub4ef \ud604\uc2e4\uc758 \uc704\uce58\ub97c \uadf8\ub300\ub85c \uc368 \ub123\ub294 \ubc29\uc2dd\uc740 \uc544\ub2c8\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ud55c \ucef4\ud4e8\ud130\uc640 \ub2e4\ub978 \ucef4\ud4e8\ud130 \uc0ac\uc774\ub97c \uad6c\ubd84\ud558\ub294 \uc120\ud0dd\uc774\uc5c8\uc9c0\ub9cc, \uc624\ub298\uc758 \uba54\uc77c\uc740 \ud6e8\uc52c \ud070 \uc2dc\uc2a4\ud15c \uc18d\uc5d0\uc11c \uc6c0\uc9c1\uc778\ub2e4. \uadf8\ub7fc\uc5d0\ub3c4 \uc774 \uc791\uc740 \ud45c\uc2dc\uac00 \uc8fc\uc18c\uc758 \ub450 \ubd80\ubd84\uc744 \ub098\ub204\ub294 \uc5ed\ud560\uc740 \uc54c\uc544\ubcf4\uae30 \uc27d\uac8c \ub0a8\uc544 \uc788\ub2e4. \ubb3c\ub860 \uc774\uba54\uc77c \uc8fc\uc18c\uc758 \uc138\ubd80 \uaddc\uce59\uae4c\uc9c0 \ubaa8\ub450 \uc774 \ud55c \uc904\ub85c \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c\ub294 \uba54\uc77c\uc744 \ubcf4\ub0b4\ub294 \uae30\uc220\ubcf4\ub2e4, \uc775\uc219\ud55c \ubaa8\uc591\uc774 \uc65c \uadf8 \uc790\ub9ac\uc5d0 \ub193\uc600\ub294\uc9c0\ub97c \ubcf4\ub294 \uac83\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4. \uac19\uc740 \uc774\ub984\uc758 \uc0ac\uc6a9\uc790\uac00 \uc11c\ub85c \ub2e4\ub978 \ucef4\ud4e8\ud130\uc5d0 \uc788\uc744 \uc218 \uc788\ub2e4\uba74 \uc774\ub984 \ud558\ub098\ub9cc\uc73c\ub85c \ubc1b\ub294 \uacf3\uc744 \uad6c\ubd84\ud558\uae30 \uc5b4\ub835\ub2e4. \ub204\uad6c\uc5d0\uac8c\uc640 \uc5b4\ub290 \ucabd\uc73c\ub85c\ub97c \ud568\uaed8 \ud45c\ud604\ud574\uc57c \ud55c\ub2e4. \ud1b0\ub9b0\uc2a8\uc774 @\ub97c \uc120\ud0dd\ud55c \uc774\uc57c\uae30\ub294 \uc0c8\ub85c\uc6b4 \ud1b5\uc2e0 \uae30\ub2a5\uc744 \ub9cc\ub4e4\uba74\uc11c \uadf8 \uae30\ub2a5\uc5d0 \ub9de\ub294 \uc8fc\uc18c\uc758 \ubb38\ubc95\ub3c4 \ud544\uc694\ud588\ub2e4\ub294 \uc810\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uae30\ud638\uc758 \ubaa8\uc591\ub9cc \ub3c5\ud2b9\ud574\uc11c \uc624\ub298\uae4c\uc9c0 \ub0a8\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub450 \ubd80\ubd84 \uc0ac\uc774\uc5d0 \ub193\uc600\uc744 \ub54c \uacbd\uacc4\ub97c \uc27d\uac8c \uc54c\uc544\ubcfc \uc218 \uc788\ub2e4\ub294 \uc5ed\ud560\uc774 \uc788\uc5c8\ub2e4. \uc774\ubbf8 \uc788\ub358 \ubb38\uc7a5\ubd80\ud638\uac00 \uc0c8\ub85c\uc6b4 \ub9e5\ub77d\uc5d0\uc11c \uc4f0\uc774\uba74\uc11c \ub110\ub9ac \uc54c\ub824\uc9c4 \uac83\uc774\ub2e4. \uc774\ub984\uc758 \uc720\ub798\ub97c \uc77d\ub294 \uc77c\ub3c4 \uc0ac\uc6a9\uc790\uac00 \uc2e4\uc81c\ub85c \ud480\uc5b4\uc57c \ud588\ub358 \ubb38\uc81c\ub97c \uc0b4\ud53c\uba74 \ub354 \uad6c\uccb4\uc801\uc778 \uc774\uc57c\uae30\uac00 \ub41c\ub2e4. \uc774\uba54\uc77c \uc8fc\uc18c \ub4a4\ucabd\uc744 \uc5b4\ub514\ub77c\uace0 \uc124\uba85\ud574\ub3c4 \uadf8\uac83\uc774 \uace7 \uc9d1\uc758 \uc704\uce58\ub098 \ud604\uc7ac \uc0ac\uc6a9\uc790\uc758 \ub3c4\uc2dc\ub97c \ub73b\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud1b5\uc2e0 \uc2dc\uc2a4\ud15c \uc548\uc5d0\uc11c \uc4f0\uc774\ub294 \uc774\ub984\uacfc \uc2e4\uc81c \uac70\ucc98\ub294 \ub2e4\ub978 \uc815\ubcf4\ub2e4. \ud3b8\uc9c0\ub97c \ubcf4\ub0b4\uba70 \ub3d9\uacfc \ud638\uc218\ub97c \uc801\ub294 \uacbd\ud5d8\uc740 \uc8fc\uc18c\uc758 \ud544\uc694\ub97c \uc774\ud574\ud558\ub294 \ube44\uc720\uc774\uc9c0\ub9cc \ubaa8\ub4e0 \uc694\uc18c\ub97c \uadf8\ub300\ub85c \ub300\uc751\uc2dc\ud0ac \uc218\ub294 \uc5c6\ub2e4. \uc774 \ucc28\uc774\ub97c \uc54c\uba74 \uc791\uc740 \uc8fc\uc18c\uc5d0 \uc9c0\ub098\uce58\uac8c \ub9ce\uc740 \ub73b\uc744 \uc77d\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uac19\uc740 \uc870\uc9c1\uc758 \uc8fc\uc18c\ub97c \uc4f4\ub2e4\uace0 \ub298 \uac19\uc740 \uac74\ubb3c \uc548\uc5d0 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\uace0, \uc8fc\uc18c \ud558\ub098\ub9cc\uc73c\ub85c \uadf8 \uc0ac\ub78c\uc774 \uc5b4\ub514\uc5d0\uc11c \uba54\uc2dc\uc9c0\ub97c \uc77d\ub294\uc9c0\ub3c4 \uc54c \uc218 \uc5c6\ub2e4. \uc8fc\uc18c\ub294 \ud544\uc694\ud55c \uc804\ub2ec \uad00\uacc4\ub97c \ud45c\ud604\ud558\uc9c0\ub9cc \uc0ac\uc6a9\uc790\uc758 \uc0dd\ud65c \uc804\uccb4\ub97c \uc124\uba85\ud558\ub294 \uc18c\uac1c\ubb38\uc740 \uc544\ub2c8\ub2e4. \ud55c\uad6d\uc5b4\uc5d0\uc11c\ub294 \uc774 \uae30\ud638\ub97c \uace8\ubc45\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \ubaa8\uc591\uc744 \ubcf4\uace0 \ubd99\uc778 \uc774\ub984\uc774\ub77c \ud55c \ubc88 \ub4e4\uc73c\uba74 \uc5b4\ub290 \ud45c\uc2dc\uc778\uc9c0 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uc601\uc5b4\uc5d0\uc11c\ub294 \ubcf4\ud1b5 at\uc774\ub77c\uace0 \uc77d\ub294\ub2e4. \uc8fc\uc18c\ub97c \ub9d0\ub85c \uc804\ub2ec\ud560 \ub54c \uae30\ud638\uc758 \uc815\uc2dd \uc774\ub984\ubcf4\ub2e4 \ubcc4\uba85\uc774 \ub354 \uc790\uc5f0\uc2a4\ub7ec\uc6b8 \ub54c\uac00 \uc788\ub2e4. \ub208\uc73c\ub85c \ubcf8 \ubaa8\uc591\uc744 \ub9d0\ub85c \uc62e\uae30\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc791\uc740 \uae30\ud638 \ud558\ub098\ub3c4 \uc0ac\uc6a9\ud558\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc5b8\uc5b4 \uc18d\uc73c\ub85c \ub4e4\uc5b4\uc624\uba74 \uc0c8\ub85c\uc6b4 \ud638\uce6d\uc744 \uc5bb\ub294\ub2e4. \uc6b0\ub9ac\ub294 \uba54\uc77c \uc8fc\uc18c\ub97c \uc4f8 \ub54c\ub9c8\ub2e4 \uc774 \ud45c\uc2dc\ub97c \uc9c0\ub098\uac00\uc9c0\ub9cc, \ub9e4\ubc88 \uadf8 \uc5ed\uc0ac\ub97c \uc0dd\uac01\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub7f4 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \uc798 \uc791\ub3d9\ud558\ub294 \ub3c4\uad6c\ub294 \uc0ac\uc6a9\uc790\uac00 \uc624\ub798 \uace0\ubbfc\ud558\uc9c0 \uc54a\uace0 \uc9c0\ub098\uac08 \uc218 \uc788\uac8c \ud574 \uc900\ub2e4. \ub2e4\uc74c\uc5d0 \uace8\ubc45\uc774\ub97c \uc785\ub825\ud560 \ub54c \uc190\uac00\ub77d\uc744 \uc7a0\uae50 \uba48\ucdb0\ub3c4 \uc88b\uaca0\ub2e4. \uc6d0\ub798 \ub2e4\ub978 \uc77c\uc744 \ud558\ub358 \ud45c\uc2dc\uac00 \uc790\ub9ac\ub97c \uc62e\uaca8, \uc9c0\uae08\uc740 \uc804 \uc138\uacc4 \uc0ac\ub78c\ub4e4\uc758 \uc6b0\ud3b8\ud568\uc744 \ucc3e\uc544\uc8fc\ub294 \uc77c\uc744 \ub3d5\uace0 \uc788\ub2e4. \ud0a4\ubcf4\ub4dc \uc548\uc5d0\uc11c \uaf64 \uc131\uacf5\uc801\uc73c\ub85c \uc804\uc5c5\ud55c \uae30\ud638\ub2e4."}, {"id": "emoji-number-tags", "title": "\uc6c3\ub294 \uc774\ubaa8\uc9c0\uc5d0\ub3c4 \ubc88\ud638\ud45c\uac00 \uc788\ub2e4", "summary": "\ub300\ud654\ucc3d\uc758 \uc6c3\ub294 \uc5bc\uad74\uc744 \ub530\ub77c\uac00\uba74 \uadf8\ub9bc \ub300\uc2e0 \uc22b\uc790\uc640 \uc774\ub984\uc774 \ub098\ub780\ud788 \uc801\ud78c \ubaa9\ub85d\uc744 \ub9cc\ub098\uac8c \ub429\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\ub370\uc774\ud130\uc640 \uae30\ub85d", "categories": ["digital"], "url": "stories/emoji-number-tags/index.html", "image": "../media/emoji-number-tags.jpg", "alt": "\uc6c3\ub294 \uc5bc\uad74\uacfc \uc5c4\uc9c0\uc190 \uc544\uc774\ucf58, \ube48 \ud45c\uc9c0\ub97c \ud568\uaed8 \ub193\uc740 AI \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\uc6c3\ub294 \uc774\ubaa8\uc9c0\uc5d0\ub3c4 \ubc88\ud638\ud45c\uac00 \uc788\ub2e4 \uc791\uc740 \uc5bc\uad74 \uadf8\ub9bc \ub4a4\uc5d0 \ub193\uc778 \ubb38\uc790 \ubaa9\ub85d \ub300\ud654\ucc3d\uc758 \uc6c3\ub294 \uc5bc\uad74\uc744 \ub530\ub77c\uac00\uba74 \uadf8\ub9bc \ub300\uc2e0 \uc22b\uc790\uc640 \uc774\ub984\uc774 \ub098\ub780\ud788 \uc801\ud78c \ubaa9\ub85d\uc744 \ub9cc\ub098\uac8c \ub429\ub2c8\ub2e4. \ub370\uc774\ud130\uc640 \uae30\ub85d \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \uba54\uc2dc\uc9c0 \ub05d\uc5d0 \uc6c3\ub294 \uc5bc\uad74 \ud558\ub098\ub97c \ubd99\uc778\ub2e4. \ub9d0\ub85c \uc4f0\uba74 \uc870\uae08 \ub531\ub531\ud560 \uac83 \uac19\uc740 \ubb38\uc7a5\uc774, \uc791\uc740 \ud45c\uc815 \ud558\ub098\ub85c \ubd80\ub4dc\ub7ec\uc6cc\uc9c4\ub2e4. \ud654\uba74\uc5d0\uc11c\ub294 \uadf8\ub9bc\uc774\uc9c0\ub9cc \uae00 \uc0ac\uc774\uc5d0 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ub4e4\uc5b4\uac04\ub2e4. \uadf8 \uc5bc\uad74\uc744 \uc815\ub9ac\ud55c \uacf5\uc2dd \uc790\ub8cc\ub97c \uc5f4\uba74 \uc608\uc0c1\uacfc \ub2e4\ub978 \ubaa8\uc2b5\uc774 \ub098\uc628\ub2e4. \uc608\uc05c \uc2a4\ud2f0\ucee4 \ubaa8\uc74c\ubcf4\ub2e4 \uc22b\uc790\uc640 \uc774\ub984\uc774 \uc774\uc5b4\uc9c4 \ubaa9\ub85d\uc5d0 \uac00\uae5d\ub2e4. \uc720\ub2c8\ucf54\ub4dc\uac00 \uacf5\uac1c\ud55c \uc774\ubaa8\uc9c0 \uc2dc\ud5d8 \uc790\ub8cc\uc5d0\ub294 \ud45c\uc815\ub9c8\ub2e4 \ucf54\ub4dc\uc640 \uc124\uba85\uc774 \ubd99\uc5b4 \uc788\ub2e4. \uc720\ub2c8\ucf54\ub4dc\uc758 \uc774\ubaa8\uc9c0 16.0 \uc2dc\ud5d8 \uc790\ub8cc\uc5d0\uc11c \ud06c\uac8c \uc6c3\ub294 \uc5bc\uad74 \ud558\ub098\ub294 \u20181F600\u2019\uc774\ub77c\ub294 \ucf54\ub4dc\ub85c \uc801\ud600 \uc788\ub2e4. \ub4a4\uc5d0\ub294 \ud65c\uc9dd \uc6c3\ub294 \uc5bc\uad74\uc774\ub77c\ub294 \ub73b\uc758 \uc601\uc5b4 \uc774\ub984\uc774 \ub530\ub77c\uc628\ub2e4. \uc774 \uc22b\uc790\ub97c \uc678\uc6cc\uc11c \uba54\uc2dc\uc9c0\ub97c \uc4f8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc6b0\ub9ac\uac00 \uadf8\ub9bc\uc744 \uace0\ub974\uba74, \uadf8 \ub4a4\uc5d0\uc11c\ub294 \uc5b4\ub5a4 \ubb38\uc790\ub97c \uace0\ub978 \uac83\uc778\uc9c0 \uad6c\ubd84\ud560 \uc218 \uc788\ub294 \uae30\uc900\uc774 \ud544\uc694\ud558\ub2e4\ub294 \uc815\ub3c4\ub85c \ubcf4\uba74 \ub41c\ub2e4. \ud45c\uc815\uc774 \ube44\uc2b7\ud558\ub2e4\uace0 \ubaa8\ub450 \uac19\uc740 \ud56d\ubaa9\ub3c4 \uc544\ub2c8\ub2e4. \uc6c3\ub294 \uc5bc\uad74, \ub208\uae4c\uc9c0 \uc6c3\ub294 \uc5bc\uad74, \uc6c3\ub2e4\uac00 \ub208\ubb3c\uc774 \ub098\ub294 \uc5bc\uad74\uc774 \uac01\uac01\uc758 \uc774\ub984\uc73c\ub85c \ub098\ub25c\ub2e4. \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc791\uc740 \ud45c\uc815 \ucc28\uc774\uc9c0\ub9cc \ubaa9\ub85d\uc5d0\uc11c\ub294 \uad6c\ubd84\ud574\uc57c \ud560 \ucc28\uc774\ub2e4. \ubaa8\ub4e0 \uc774\ubaa8\uc9c0\uac00 \ucf54\ub4dc \ud558\ub098\ub85c\ub9cc \uc774\ub8e8\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac19\uc740 \uc790\ub8cc\uc5d0\ub294 \uc5c4\uc9c0\ub97c \uc62c\ub9b0 \uc190\uc758 \ucf54\ub4dc \ub4a4\uc5d0 \ud53c\ubd80\uc0c9\uc744 \ub098\ud0c0\ub0b4\ub294 \ucf54\ub4dc\uac00 \ub354\ud574\uc9c4 \ud56d\ubaa9\ub3c4 \ub098\uc628\ub2e4. \ud654\uba74\uc5d0\uc11c\ub294 \ud558\ub098\uc758 \uc190\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc, \uc790\ub8cc\uc5d0\ub294 \ub458 \uc774\uc0c1\uc758 \ucf54\ub4dc\ub97c \uc774\uc5b4 \uc801\uc744 \uc218 \uc788\ub294 \uac83\uc774\ub2e4. \uacf5\uc2dd \ud30c\uc77c\ub3c4 \ud56d\ubaa9\uc758 \ucf54\ub4dc\uac00 \ud558\ub098 \uc774\uc0c1\uc77c \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\ub7ec\ub2c8 \ub208\uc55e\uc758 \uadf8\ub9bc \uac1c\uc218\uc640 \ub4a4\uc5d0 \uc801\ud78c \ucf54\ub4dc \uac1c\uc218\uac00 \ud56d\uc0c1 \uac19\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc791\uc740 \uadf8\ub9bc \ud558\ub098\ub97c \ud45c\uc2dc\ud558\uae30 \uc704\ud574 \uc5b4\ub5a4 \uc815\ubcf4\ub97c \ud568\uaed8 \ub450\ub294\uc9c0 \uc5ff\ubcf4\ub294 \ub300\ubaa9\uc774\ub2e4. \ud734\ub300\uc804\ud654\uc5d0\uc11c \uc5bc\uad74\uc744 \ub204\ub974\uba74 \uc6b0\ub9ac\ub294 \uadf8\ub9bc\uc744 \uc120\ud0dd\ud588\ub2e4\uace0 \ub290\ub080\ub2e4. \uacf5\uc2dd \ubaa9\ub85d\uc740 \uc5b4\ub5a4 \ud56d\ubaa9\uc744 \uc120\ud0dd\ud588\ub294\uc9c0 \uad6c\ubcc4\ud558\ub294 \ucf54\ub4dc\uc640 \uc774\ub984\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub204\ub974\ub294 \ud654\uba74\uacfc \uc804\ub2ec\ud558\ub294 \uc815\ubcf4\uac00 \uc11c\ub85c \ub2e4\ub978 \uce35\uc5d0 \uc788\ub294 \uc148\uc774\ub2e4. \uac19\uc740 \ud45c\uc2dc\ub97c \uc54c\uc544\ubcf4\ub824\uba74 \ubaa8\uc591\uc5d0\ub9cc \uc758\uc874\ud558\uc9c0 \uc54a\ub294 \uad6c\ubd84 \uae30\uc900\uc774 \ud544\uc694\ud558\ub2e4. 1F600\uc774\ub77c\ub294 \ud45c\uae30\ub294 \uadf8 \uae30\uc900\uc744 \uc0ac\ub78c\uc774 \uc77d\uc744 \uc218 \uc788\uac8c \uc801\uc740 \uc608\ub2e4. \uc2ed\uc721\uc9c4\uc218 \ud45c\uae30\ubc95\uc744 \uacf5\ubd80\ud574\uc57c\ub9cc \uc774\ubaa8\uc9c0\ub97c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ucc45\uc5d0 \ubd99\uc740 \ub3c4\uc11c \ubc88\ud638\ucc98\ub7fc \ud56d\ubaa9\uc744 \uad6c\ubcc4\ud558\ub294 \ud45c\uc9c0\uac00 \uc788\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \ucda9\ubd84\ud558\ub2e4. \ub2e4\ub9cc \ucc45\uc758 \ud45c\uc9c0 \uadf8\ub9bc\uacfc \uad00\ub9ac \ubc88\ud638\uac00 \uac19\uc740 \uac83\uc774 \uc544\ub2c8\ub4ef \ucf54\ub4dc\uc640 \ub208\uc5d0 \ubcf4\uc774\ub294 \uc5bc\uad74\ub3c4 \uad6c\ubd84\ud560 \uc218 \uc788\ub2e4. \uc5c4\uc9c0\uc190 \ud45c\uc2dc \ub4a4\uc5d0 \ud53c\ubd80\uc0c9 \ucf54\ub4dc\uac00 \ubd99\ub294 \uc608\uc5d0\uc11c\ub294 \uae30\ubcf8 \ub3d9\uc791\uacfc \ucd94\uac00 \ud2b9\uc131\uc774 \ud568\uaed8 \ud45c\ud604\ub41c\ub2e4. \uc0ac\uc6a9\uc790\ub294 \ud558\ub098\uc758 \uc190\uc744 \ubcf4\uc9c0\ub9cc \uc790\ub8cc\uc5d0\ub294 \uc774\uc5b4\uc9c4 \ucf54\ub4dc\ub4e4\uc774 \ub0a8\ub294\ub2e4. \uadf8\ub9bc \ud558\ub098\uc5d0 \uc815\ubcf4 \ud558\ub098\ub77c\ub294 \uc9c1\uad00\uc774 \ub298 \ub9de\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud45c\uc2dc\ub97c \uc138\ub294 \uc77c\uacfc \uc815\ubcf4\ub97c \uc774\ub8e8\ub294 \ub2e8\uc704\ub97c \uc138\ub294 \uc77c\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc774\ub7f0 \uc870\ud569\uc744 \uc548\ub2e4\uace0 \ubaa8\ub4e0 \uc774\ubaa8\uc9c0\uac00 \uac19\uc740 \uad6c\uc870\ub77c\uace0 \uc678\uc6b0\uc9c0\ub294 \ub9d0\uc790. \uacf5\uc2dd \uc2dc\ud5d8 \ubaa9\ub85d\uc740 \ucf54\ub4dc \ud558\ub098\uc778 \ud56d\ubaa9\uacfc \uc5ec\ub7ec \ucf54\ub4dc\ub85c \uc774\ub8e8\uc5b4\uc9c4 \ud56d\ubaa9\uc744 \uc2e4\uc81c \uc0ac\ub840\ub85c \ubcf4\uc5ec \uc900\ub2e4. \ubcf5\uc7a1\ud55c \uc870\ud569 \uaddc\uce59\uc744 \ubaa8\ub450 \ubc30\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uba54\uc2dc\uc9c0 \uc18d \uc791\uc740 \ud45c\uc815\uc5d0\ub3c4 \ub2e8\uc21c\ud55c \uadf8\ub9bc \ud30c\uc77c \ud558\ub098\uc640 \ub2e4\ub978 \uad6c\uc870\uac00 \uc788\uc744 \uc218 \uc788\ub2e4\ub294 \uc810\ub9cc \uc54c\uc544\ub3c4 \ubcf4\uae30\uc758 \ud3ed\uc774 \ub113\uc5b4\uc9c4\ub2e4. \ubaa9\ub85d\uc758 \uc774\ub984\uc740 \uc5b4\ub290 \ud56d\ubaa9\uc744 \ub9d0\ud558\ub294\uc9c0 \uc2dd\ubcc4\ud558\ub3c4\ub85d \ub3d5\ub294\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uc774\ubaa8\uc9c0\ub97c \ubcf4\ub0b8 \uc0ac\ub78c\uc758 \ub9c8\uc74c \uc804\uccb4\ub97c \uace0\uc815\ud574 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc6c3\ub294 \uc5bc\uad74\uc744 \ubd99\uc600\uc5b4\ub3c4 \uc778\uc0ac\uc77c \uc218\ub3c4, \uae34\uc7a5\uc744 \ud480\ub824\ub294 \ud45c\ud604\uc77c \uc218\ub3c4 \uc788\ub2e4. \uacf5\uc2dd \ud56d\ubaa9\uc758 \uc774\ub984\uacfc \uc2e4\uc81c \ub300\ud654\uc5d0\uc11c \uc5bb\ub294 \ub258\uc559\uc2a4\ub294 \uc11c\ub85c \uad00\ub828\ub418\uc9c0\ub9cc \uac19\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub798\uc11c \ucf54\ub4dc\ub97c \uc815\ud655\ud788 \uc804\ub2ec\ud558\ub294 \uae30\uc220\uacfc \ub9d0\ub73b\uc774 \uc798 \ud1b5\ud558\ub294 \ub300\ud654\ub294 \ubcc4\uac1c\uc758 \ub178\ub825\uc774 \ud544\uc694\ud558\ub2e4. \uac19\uc740 \ud45c\uc2dc\ub97c \uc54c\uc544\ubcf4\ub294 \uacf5\ud1b5 \uae30\uc900\uc774 \uc788\uc5b4\ub3c4 \ubb38\ub9e5\uacfc \uad00\uacc4\ub294 \uc0ac\ub78c\uc5d0\uac8c \ub0a8\ub294\ub2e4. \uc791\uc740 \uc5bc\uad74\uc774 \ubb38\uc7a5\uc744 \ubd80\ub4dc\ub7fd\uac8c \ub9cc\ub4dc\ub294 \uae4c\ub2ed\uc744 \uc0dd\uac01\ud558\uba74\uc11c\ub3c4, \uc624\ud574\uac00 \uc0dd\uacbc\uc744 \ub54c \uc22b\uc790\ud45c\ub9cc\uc73c\ub85c \uc0c1\ub300\uc758 \uc758\ub3c4\ub97c \ud310\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4\ub294 \uc810\uc744 \uae30\uc5b5\ud560 \uc218 \uc788\ub2e4. \uc774 \uae00\uc740 \uc774\ubaa8\uc9c0 16.0\uc758 \uc2dc\ud5d8 \uc790\ub8cc\ub97c \uadfc\uac70\ub85c \ud55c\ub2e4. \ubc84\uc804\uc774 \ubd99\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ubaa9\ub85d\uc774 \uc5b8\uc81c\ub098 \ud55c \ubc88 \uc815\ud574\uc9c4 \uc0c1\ud0dc\ub85c \uba48\ucd94\uc5b4 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub2e4\ub978 \uc2dc\uc810\uc758 \uc790\ub8cc\ub098 \ud658\uacbd\uc744 \ube44\uad50\ud560 \ub54c\uc5d0\ub294 \uc5b4\ub5a4 \ubaa9\ub85d\uc744 \uae30\uc900\uc73c\ub85c \uc0bc\uc558\ub294\uc9c0 \uc54c\uc544\uc57c \ud55c\ub2e4. \uadf8 \uc22b\uc790\ub97c \uace7 \uac1c\uc778 \uae30\uae30\uc758 \uc9c0\uc6d0 \uc0c1\ud0dc\uc640 \uac19\ub2e4\uace0 \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uc790\ub8cc\uc758 \uc21c\uc11c\uc640 \ubb36\uc74c\ub3c4 \uad00\uc2ec\uc744 \ub048\ub2e4. \uc22b\uc790 \ud06c\uae30\ub300\ub85c\ub9cc \ub298\uc5b4\ub193\ub294 \ub300\uc2e0 \uc0ac\ub78c\ub4e4\uc774 \ud56d\ubaa9\uc744 \ucc3e\ub294 \ubd84\ub958\ub97c \uace0\ub824\ud55c \ubc30\uc5f4\uc774 \uc788\ub2e4. \uc774\ubaa8\uc9c0\uac00 \ubb38\uc790\ub85c \ucc98\ub9ac\ub418\ub294 \uccb4\uacc4\uc640 \uc190\uac00\ub77d\uc73c\ub85c \uace0\ub974\ub294 \uacbd\ud5d8\uc774 \ub9cc\ub098\ub294 \uc9c0\uc810\uc774\ub2e4. \uba54\uc2dc\uc9c0 \ud55c \uc904\uc744 \uc990\uae30\uba74\uc11c \uadf8 \ub4a4\uc758 \ubaa9\ub85d\uc744 \ud55c \ubc88 \ub4e4\uc5ec\ub2e4\ubcf4\uba74, \uac00\ubcbc\uc6b4 \ud45c\ud604\uc744 \uc704\ud574 \ud544\uc694\ud55c \uaf3c\uaf3c\ud55c \ud569\uc758\uac00 \ubcf4\uc778\ub2e4. \uc774 \uc790\ub8cc\ub294 \uc774\ubaa8\uc9c0\uac00 \ud0a4\ubcf4\ub4dc\uc5d0 \ub098\uc624\uace0 \ud654\uba74\uc5d0\uc11c \ucc98\ub9ac\ub418\ub294\uc9c0\ub97c \uc2dc\ud5d8\ud558\uae30 \uc704\ud574 \uacf5\uac1c\ub41c \ubaa9\ub85d\uc774\ub2e4. \ud45c\uc815\ubfd0 \uc544\ub2c8\ub77c \uc0ac\ub78c\uacfc \uc0ac\ubb3c \ub4f1 \uc5ec\ub7ec \ubb36\uc74c\uc73c\ub85c \ub098\ub258\uc5b4 \uc788\ub2e4. \uc790\ub8cc\uc758 \uc124\uba85\uc5d0\ub294 \ubaa9\ub85d\uc774 \ucf54\ub4dc \uc22b\uc790 \uc21c\uc11c\uac00 \uc544\ub2c8\ub77c CLDR\uc758 \uc774\ubaa8\uc9c0 \uc21c\uc11c\ub97c \ub530\ub978\ub2e4\ub294 \ub0b4\uc6a9\ub3c4 \uc788\ub2e4. \ud654\uba74\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc774 \uace0\ub974\ub294 \uc21c\uc11c\ub97c \uc0dd\uac01\ud558\uba70 \uc815\ub9ac\ud55c \ud754\uc801\uc774 \uacf5\uc2dd \ubaa9\ub85d \uc548\uc5d0\ub3c4 \uc788\ub294 \uc148\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \uba54\uc2dc\uc9c0\uc5d0 \uc6c3\ub294 \uc5bc\uad74\uc744 \ud558\ub098 \ubd99\uc778\ub2e4\uba74, \uadf8 \ub4a4\uc5d0 \ubc88\ud638\ud45c\uc640 \uc774\ub984\ud45c\uac00 \uc788\ub2e4\ub294 \uac83\ub9cc \uc7a0\uae50 \ub5a0\uc62c\ub824 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc791\uace0 \uac00\ubcbc\uc6b4 \ud45c\uc815\uc744 \uc11c\ub85c \uad6c\ubd84\ud558\uae30 \uc704\ud574, \ubcf4\uc774\uc9c0 \uc54a\ub294 \uacf3\uc5d0\uc11c\ub294 \uaf64 \uaf3c\uaf3c\ud55c \uc815\ub9ac\uac00 \uc774\ub8e8\uc5b4\uc9c0\uace0 \uc788\ub2e4."}, {"id": "engelbart-mouse-demo", "title": "\uc791\uc740 \ub9c8\uc6b0\uc2a4\uac00 \ud568\uaed8 \ub4f1\uc7a5\ud55c \ud070 \uc2dc\uc5f0", "summary": "\ud654\uba74\uc744 \uac00\ub9ac\ud0a4\ub294 \uc791\uc740 \ub3c4\uad6c\ub294 \ud568\uaed8 \uc77c\ud558\ub294 \ucef4\ud4e8\ud130\ub97c \ubcf4\uc5ec\uc8fc\ub294 \ub354 \ud070 \uad6c\uc0c1\uc758 \uc77c\ubd80\uc600\uc2b5\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\ucef4\ud4e8\ud130\uc758 \uc5ed\uc0ac", "categories": ["digital"], "url": "stories/engelbart-mouse-demo/index.html", "image": "../media/engelbart-mouse-demo.jpg", "alt": "\uc77c\ubc18\ud654\ud55c \uc720\uc120 \ub9c8\uc6b0\uc2a4\uc640 \ud654\uc0b4\ud45c \ucee4\uc11c\uac00 \uc788\ub294 \ud654\uba74\uc758 \uc124\uba85\uc6a9 AI \uc0bd\ud654", "text": "\uc791\uc740 \ub9c8\uc6b0\uc2a4\uac00 \ud568\uaed8 \ub4f1\uc7a5\ud55c \ud070 \uc2dc\uc5f0 1968\ub144\uc758 \ucef4\ud4e8\ud130 \uc2dc\uc5f0\uc744 \uc870\uae08 \ub2e4\ub974\uac8c \ub5a0\uc62c\ub9ac\uae30 \ud654\uba74\uc744 \uac00\ub9ac\ud0a4\ub294 \uc791\uc740 \ub3c4\uad6c\ub294 \ud568\uaed8 \uc77c\ud558\ub294 \ucef4\ud4e8\ud130\ub97c \ubcf4\uc5ec\uc8fc\ub294 \ub354 \ud070 \uad6c\uc0c1\uc758 \uc77c\ubd80\uc600\uc2b5\ub2c8\ub2e4. \ucef4\ud4e8\ud130\uc758 \uc5ed\uc0ac \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \ucef4\ud4e8\ud130 \ub9c8\uc6b0\uc2a4\ub294 \ub108\ubb34 \uc775\uc219\ud574\uc11c \ucc98\uc74c \ub4f1\uc7a5\ud588\uc744 \ub54c\ub97c \uc0c1\uc0c1\ud558\uae30 \uc5b4\ub835\ub2e4. \uc190\uc73c\ub85c \uc870\uae08 \uc6c0\uc9c1\uc774\uba74 \ud654\uba74\uc758 \ud45c\uc2dc\ub3c4 \uc6c0\uc9c1\uc778\ub2e4. \ucc45\uc0c1\uc5d0\uc11c \uc77c\uc5b4\ub098\ub294 \uc791\uc740 \ub3d9\uc791\uc774\ub2e4. \uadf8 \uc791\uc740 \ub3c4\uad6c\uc758 \uc5ed\uc0ac\uc5d0\uc11c \uc790\uc8fc \ub9cc\ub098\ub294 \uc774\ub984\uc774 \ub354\uae00\ub7ec\uc2a4 \uc5e5\uac94\ubc14\ud2b8\ub2e4. \uc778\ud130\ub137 \uba85\uc608\uc758 \uc804\ub2f9\uc740 \uadf8\uac00 \uc774\ub048 \uc5f0\uad6c\ud300\uc758 \uc2dc\uc2a4\ud15c\uc5d0 \ucef4\ud4e8\ud130 \ub9c8\uc6b0\uc2a4 \uac19\uc740 \ucd08\uae30 \ud654\uba74 \uc870\uc791 \ub3c4\uad6c\uac00 \ud3ec\ud568\ub418\uc5b4 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud558\uc9c0\ub9cc \ub2f9\uc2dc\uc758 \uad6c\uc0c1\uc740 \ucc45\uc0c1 \uc704\uc758 \ub3c4\uad6c \ud558\ub098\uc5d0\uc11c \ub05d\ub098\uc9c0 \uc54a\uc558\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \ucef4\ud4e8\ud130\ub97c \ud1b5\ud574 \ud568\uaed8 \uc77c\ud558\ub294 \ubc29\uc2dd\uae4c\uc9c0 \ubcf4\uc5ec\uc8fc\ub824 \ud588\ub2e4. \uc5e5\uac94\ubc14\ud2b8\ub294 \ubbf8\uad6d SRI\uc758 \uc5f0\uad6c\uc18c\uc5d0\uc11c \uc0ac\ub78c\uc758 \uc9c0\uc801 \ud65c\ub3d9\uc744 \ub3d5\ub294 \uc2dc\uc2a4\ud15c\uc744 \uc5f0\uad6c\ud588\ub2e4. \uc5ec\ub7ec \uc0ac\uc6a9\uc790\uac00 \ud654\uba74 \uc55e\uc5d0\uc11c \uc815\ubcf4\ub97c \ub2e4\ub8e8\uba70 \ubb38\uc81c\ub97c \ud568\uaed8 \ud574\uacb0\ud558\ub294 \ubaa8\uc2b5\uc774 \uadf8 \uad6c\uc0c1\uc5d0 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \uadf8\uc758 \ud300\uc774 \uac1c\ubc1c\ud55c NLS\uc5d0\ub294 \ud611\uc5c5 \uc18c\ud504\ud2b8\uc6e8\uc5b4\uc640 \ud558\uc774\ud37c\ud14d\uc2a4\ud2b8, \ucd08\uae30 \ud654\uba74 \uc778\ud130\ud398\uc774\uc2a4 \uc694\uc18c\uac00 \ud568\uaed8 \ud3ec\ud568\ub418\uc5c8\ub2e4. \ud558\uc774\ud37c\ud14d\uc2a4\ud2b8\ub294 \uc815\ubcf4\ub97c \uc5f0\uacb0\ud574 \ub530\ub77c\uac00\uac8c \ud558\ub294 \ubc29\uc2dd\uc73c\ub85c \uc774\ud574\ud558\uba74 \ub41c\ub2e4. \uc5b4\ub824\uc6b4 \uae30\uc220 \uc774\ub984\uc744 \uc804\ubd80 \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc624\ub298 \uc6b0\ub9ac\uac00 \ucef4\ud4e8\ud130\uc5d0\uc11c \ud558\ub294 \uc77c\ub3c4 \ud55c \uac00\uc9c0 \ub3d9\uc791\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub300\uc0c1\uc744 \uac00\ub9ac\ud0a4\uace0, \ub2e4\ub978 \uc815\ubcf4\ub85c \uc774\ub3d9\ud558\uace0, \ub2e4\ub978 \uc0ac\ub78c\uacfc \ub0b4\uc6a9\uc744 \ub098\ub208\ub2e4. \ub9c8\uc6b0\uc2a4\ub294 \uadf8\ub7f0 \ud070 \uc791\uc5c5\uc744 \ub3d5\ub294 \ud55c \ubd80\ubd84\uc774\uc5c8\ub2e4. 1968\ub144 \uc5e5\uac94\ubc14\ud2b8\uc640 \uc5f0\uad6c\ud300\uc740 \ucef4\ud4e8\ud130 \ud559\ud68c\uc5d0\uc11c \uc2dc\uc2a4\ud15c\uc744 \uc2dc\uc5f0\ud588\ub2e4. \ub4a4\uc5d0 \uc774 \ubc1c\ud45c\ub294 \u2018\ubaa8\ub4e0 \ub370\ubaa8\uc758 \uc5b4\uba38\ub2c8\u2019\ub77c\ub294 \ubcc4\uba85\uc73c\ub85c \ub110\ub9ac \uc54c\ub824\uc84c\ub2e4. \uc774\ub984\uc774 \uac70\ucc3d\ud574\uc11c \ubaa8\ub4e0 \ud604\ub300 \uae30\uc220\uc774 \uadf8\ub0a0 \uc644\uc131\ub418\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uc0ac\ub78c\ub4e4\uc774 \ucef4\ud4e8\ud130\uc640 \uc0c1\ud638\uc791\uc6a9\ud558\ub294 \uc5ec\ub7ec \uc544\uc774\ub514\uc5b4\ub97c \uc791\ub3d9\ud558\ub294 \uc2dc\uc2a4\ud15c\uc73c\ub85c \ubcf4\uc5ec\uc8fc\uc5c8\ub2e4\ub294 \uc810\uc774\ub2e4. \uc778\ud130\ub137 \uba85\uc608\uc758 \uc804\ub2f9\uc740 \uc5e5\uac94\ubc14\ud2b8\uac00 \ub9c8\uc6b0\uc2a4\ub97c \ube44\ub86f\ud55c \uc5ec\ub7ec \ud2b9\ud5c8\ub3c4 \ubcf4\uc720\ud588\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ub2e4\ub9cc \uadf8\uc758 \uc791\uc5c5\uc744 \uc791\uc740 \uc7a5\uce58 \ud558\ub098\uc758 \ubc1c\uba85\uc73c\ub85c\ub9cc \uc904\uc774\uba74, \ud611\uc5c5\uacfc \uc815\ubcf4 \uc5f0\uacb0\uc5d0 \uad00\ud55c \uad6c\uc0c1\uc774 \ubc30\uacbd\uc73c\ub85c \ubb3c\ub7ec\ub09c\ub2e4. \ubb38\uc11c\uc5d0\uc11c \ud2b9\uc815 \ubb38\uc7a5\uc744 \uace0\ub974\uace0 \uc2f6\uc744 \ub54c \uadf8 \uc704\uce58\ub97c \ub9d0\ub85c \uae38\uac8c \uc124\uba85\ud560 \uc218\ub3c4 \uc788\ub2e4. \uc190\uc758 \uc6c0\uc9c1\uc784\uc73c\ub85c \ud654\uba74\uc758 \ud55c \uc9c0\uc810\uc744 \uac00\ub9ac\ud0ac \uc218 \uc788\ub2e4\uba74 \ub2e4\ub978 \uae38\uc774 \uc5f4\ub9b0\ub2e4. \ub9c8\uc6b0\uc2a4\ub294 \uadf8\ub7f0 \uad00\uacc4\ub97c \uc775\uc219\ud558\uac8c \ub9cc\ub4e0 \ub3c4\uad6c\ub2e4. \ucc45\uc0c1\uc5d0\uc11c\uc758 \uc9e7\uc740 \uc774\ub3d9\uc744 \ud654\uba74\uc758 \uc704\uce58 \ubcc0\ud654\uc640 \uc5f0\uacb0\ud574 \uc0ac\ub78c\uc758 \uc758\ub3c4\ub97c \uc804\ub2ec\ud55c\ub2e4. \uadf8\ub798\uc11c \ub9c8\uc6b0\uc2a4\uc758 \uc758\ubbf8\ub97c \ub2e8\uc21c\ud788 \uc791\uc740 \uc0c1\uc790\uc758 \ud615\ud0dc\uc5d0\uc11c\ub9cc \ucc3e\uc744 \uc218\ub294 \uc5c6\ub2e4. \ud654\uba74\uc5d0 \ubb34\uc5c7\uc774 \ubcf4\uc774\uace0, \uac00\ub9ac\ud0a8 \ub4a4 \uc5b4\ub5a4 \uc791\uc5c5\uc744 \ud560 \uc218 \uc788\ub294\uc9c0\uac00 \ud568\uaed8 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uc624\ub298\uc758 \uc0ac\uc6a9 \uacbd\ud5d8\uc744 \uadf8\ub300\ub85c \ucd08\uae30 \uc7a5\uce58\uc5d0 \ub300\uc785\ud558\uc9c0 \uc54a\ub354\ub77c\ub3c4, \uc785\ub825 \ub3c4\uad6c\uc640 \ud654\uba74 \ud45c\ud604\uc744 \ud55c \ud658\uacbd\uc73c\ub85c \uc124\uacc4\ud574\uc57c \ud55c\ub2e4\ub294 \uae30\ubcf8\uc801\uc778 \ubb38\uc81c\ub294 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ud558\uc774\ud37c\ud14d\uc2a4\ud2b8\ub294 \ub0b4\uc6a9\uc744 \uc904\uc9c0\uc5b4 \ub193\ub294 \uac83 \uc678\uc5d0 \ub2e4\ub978 \uc815\ubcf4\ub85c \uc774\uc5b4\uc9c0\ub294 \uae38\uc744 \ub9c8\ub828\ud55c\ub2e4. \uc77d\ub358 \uacf3\uc5d0\uc11c \uad00\ub828\ub41c \ub2e4\ub978 \ubd80\ubd84\uc73c\ub85c \uc62e\uaca8 \uac08 \uc218 \uc788\ub2e4\uba74 \uc790\ub8cc\ub97c \ub2e4\ub8e8\ub294 \uc21c\uc11c\uac00 \ud558\ub098\ub85c \uace0\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc5e5\uac94\ubc14\ud2b8\uc758 \ud300\uc774 \ubcf4\uc5ec \uc900 \ud658\uacbd\uc5d0\uc11c \uc815\ubcf4 \uc5f0\uacb0\uacfc \ud654\uba74 \uc870\uc791\uc774 \ud568\uaed8 \uc911\uc694\ud588\ub358 \uae4c\ub2ed\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ud604\uc7ac\uc758 \uc6f9\uacfc NLS\ub97c \uac19\uc740 \uc2dc\uc2a4\ud15c\uc774\ub77c\uace0 \ub9d0\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc2dc\ub300\uc640 \uae30\uc220\uc758 \uad6c\uccb4\uc801\uc778 \uc791\ub3d9 \ubc29\uc2dd\uc740 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ub2e4\ub9cc \ud654\uba74\uc5d0\uc11c \ub300\uc0c1\uc744 \uace0\ub974\uace0 \uc5f0\uacb0\ub41c \uc815\ubcf4\ub97c \ucc3e\uc544\uac00\uba70 \uc791\uc5c5\ud55c\ub2e4\ub294 \uacbd\ud5d8\uc758 \ubb36\uc74c\uc744 \ub5a0\uc62c\ub9ac\uba74, \ub9c8\uc6b0\uc2a4\uac00 \uc65c \ub3c5\ub9bd\ub41c \uc7a5\ub09c\uac10\uc774 \uc544\ub2c8\ub77c \uc815\ubcf4 \ud658\uacbd\uc758 \ub3c4\uad6c\uc600\ub294\uc9c0 \uc54c \uc218 \uc788\ub2e4. \uc5ec\ub7ec \uc0ac\ub78c\uc774 \ud558\ub098\uc758 \ubb38\uc81c\ub97c \ub2e4\ub8f0 \ub54c\uc5d0\ub294 \uac01\uc790\uc758 \uc0dd\uac01\uc744 \uae30\ub85d\ud558\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ubcf4\uc5ec \uc904 \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4. \ubb38\uc11c\uc758 \ub0b4\uc6a9\uacfc \uc704\uce58\ub97c \uacf5\uc720\ud558\uace0 \uc218\uc815\ud560 \ub300\uc0c1\uc744 \uac00\ub9ac\ud0a4\ub294 \ud589\ub3d9\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ud611\uc5c5\uc740 \uc0ac\ub78c\uc774 \ub3d9\uc2dc\uc5d0 \uc790\ub9ac\uc5d0 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \ud568\uaed8 \ubcfc \ub300\uc0c1\uacfc \uc11c\ub85c\uc758 \ud589\ub3d9\uc744 \uc774\ud574\ud560 \ubc29\ubc95\ub3c4 \ud544\uc694\ud558\ub2e4. 1968\ub144 \uc2dc\uc5f0\uc758 \uc758\ubbf8\ub294 \uc774\ub7f0 \uc544\uc774\ub514\uc5b4\ub97c \uc2e4\uc81c\ub85c \uc791\ub3d9\ud558\ub294 \ud658\uacbd\uc5d0\uc11c \ubcf4\uc5ec \uc8fc\uc5c8\ub2e4\ub294 \ub370 \uc788\ub2e4. \ubbf8\ub798\uc5d0\ub294 \uc774\ub807\uac8c \ub420 \uac83\uc774\ub77c\ub294 \ub9d0\uacfc \ub208\uc55e\uc5d0\uc11c \uc870\uc791\ud574 \ubcf4\uc774\ub294 \uc77c\uc740 \ub2e4\ub978 \uc124\ub4dd\ub825\uc744 \uac00\uc9c4\ub2e4. \uadf8\ub807\ub2e4\uace0 \uadf8\ub0a0 \ub4a4\uc758 \ubaa8\ub4e0 \ud611\uc5c5 \uae30\uc220\uc774 \uc644\uc131\ub418\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc5ec\ub7ec \uae30\ub2a5\uc744 \ud568\uaed8 \uc0ac\uc6a9\ud558\ub294 \uc7a5\uba74\uc774 \ud558\ub098\uc758 \uad6c\uc0c1\uc73c\ub85c \ub4dc\ub7ec\ub0ac\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \ucef4\ud4e8\ud130\uc758 \uc5ed\uc0ac\ub97c \ucc98\ub9ac \uc18d\ub3c4\uc640 \uc800\uc7a5 \uc6a9\ub7c9\uc73c\ub85c\ub9cc \uc815\ub9ac\ud558\uba74 \uc0ac\uc6a9\uc790\uc758 \ubab8\uc740 \ubc30\uacbd\uc73c\ub85c \ubb3c\ub7ec\ub09c\ub2e4. \ub9c8\uc6b0\uc2a4 \uc774\uc57c\uae30\ub294 \ubb34\uc5c7\uc744 \uc785\ub825\ud588\uace0 \uc190\uc744 \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc600\ub294\uc9c0\ub97c \ubb3b\uac8c \ud55c\ub2e4. \uae30\uacc4\uc758 \ub2a5\ub825\uc774 \ucee4\uc838\ub3c4 \uc0ac\ub78c\uc774 \uc6d0\ud558\ub294 \uc77c\uc744 \ud45c\ud604\ud558\uae30 \uc5b4\ub835\ub2e4\uba74 \uadf8 \ub2a5\ub825\uc744 \ucda9\ubd84\ud788 \uc4f0\uae30 \uc5b4\ub835\ub2e4. \uc778\ud130\ud398\uc774\uc2a4\ub294 \uadf8 \uc0ac\uc774\ub97c \ub2e4\ub8e8\ub294 \uc120\ud0dd\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \ubb38\uc7a5\uc744 \uc120\ud0dd\ud558\uac70\ub098 \ucc3d\uc744 \uc62e\uae38 \ub54c\uc5d0\ub294 \ud589\ub3d9\uc774 \uba87 \ub2e8\uacc4\ub85c \uc774\uc5b4\uc9c0\ub294\uc9c0 \uc7a0\uae50 \uc0b4\ud3b4\ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uac00\ub9ac\ud0a4\uace0 \ub204\ub974\uace0 \ud655\uc778\ud558\ub294 \uc21c\uc11c\uac00 \uc790\uc5f0\uc2a4\ub7ec\uc6cc\uc11c \ud3c9\uc18c\uc5d0\ub294 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc5e5\uac94\ubc14\ud2b8\uc758 \uc791\uc5c5\uc744 \uc54c\uba74 \uc774 \uc775\uc219\ud568\ub3c4 \ub204\uad70\uac00 \uc5f0\uad6c\ud558\uace0 \uc2dc\ud5d8\ud55c \uacb0\uacfc\uc600\uc74c\uc744 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uc791\uc740 \ub3c4\uad6c\uc758 \uc5ed\uc0ac\uc5d0\uc11c \ub354 \ud070 \uc77c\ud558\ub294 \ubc29\uc2dd\uc774 \ubcf4\uc778\ub2e4. \ub9c8\uc6b0\uc2a4\ub294 \uc0ac\ub78c\uc758 \uc190\uacfc \ud654\uba74 \uc0ac\uc774\ub97c \uc5f0\uacb0\ud558\ub294 \ub3c4\uad6c\ub2e4. \ub108\ubb34 \uc775\uc219\ud574\uc9c4 \ub355\ubd84\uc5d0 \ud3c9\uc18c\uc5d0\ub294 \uadf8 \uad00\uacc4\ub97c \ud2b9\ubcc4\ud788 \uc0dd\uac01\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud3b8\ud558\uac8c \uc4f0\uc774\ub294 \ub3c4\uad6c\uc77c\uc218\ub85d \uc0ac\uc6a9 \uc911\uc5d0\ub294 \uc874\uc7ac\ub97c \ub35c \uc758\uc2dd\ud558\uac8c \ub41c\ub2e4. \uc61b \ucef4\ud4e8\ud130\ub97c \ubcfc \ub54c \ud070 \ubcf8\uccb4\uc640 \ud654\uba74\uc5d0 \uba3c\uc800 \ub208\uc774 \uac00\uc9c0\ub9cc, \uc791\uc740 \uc785\ub825 \ub3c4\uad6c\ub3c4 \ud568\uaed8 \uc0b4\ud3b4\ubcfc \ub9cc\ud558\ub2e4. \uc0ac\uc6a9\uc790\uac00 \uc5b4\ub5a4 \ub3d9\uc791\uc73c\ub85c \ucef4\ud4e8\ud130\uc5d0 \uc758\uc0ac\ub97c \uc804\ud588\ub294\uc9c0\ub97c \ubcf4\uc5ec\uc8fc\uae30 \ub54c\ubb38\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \ub9c8\uc6b0\uc2a4\ub85c \ucc3d \ud558\ub098\ub97c \uc62e\uae30\uac70\ub098 \ubb38\uc11c\ub97c \uac00\ub9ac\ud0ac \ub54c \uc7a0\uae50 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc774 \uc791\uc740 \uc6c0\uc9c1\uc784\uc5d0\ub3c4 \uc0ac\ub78c\ub4e4\uc774 \ucef4\ud4e8\ud130\uc640 \uc77c\ud558\ub294 \ubc29\uc2dd\uc744 \ubc14\uafb8\ub824\ub358 \uae34 \uad6c\uc0c1\uc774 \uc774\uc5b4\uc838 \uc788\ub2e4."}, {"id": "eniac-changing-problem-and-human-work", "title": "\uc5d0\ub2c8\uc545 \u2014 \uacc4\uc0b0\uc740 \ube68\ub77c\uc84c\ub294\ub370 \ubb38\uc81c\ub97c \ubc14\uafb8\ub294 \ub370\ub294 \uc2dc\uac04\uc774 \uac78\ub838\ub2e4", "summary": "\uc5d0\ub2c8\uc545\uc758 \uc7a5\uce58\uc640 \uc124\uc815\u00b7\uc2dc\ud5d8 \uc808\ucc28\ub97c \ub530\ub77c, \ube60\ub978 \uacc4\uc0b0 \ub4a4\uc5d0 \ud544\uc694\ud588\ub358 \uc900\ube44 \uc791\uc5c5\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\ucef4\ud4e8\ud130\uc758 \uc5ed\uc0ac", "categories": ["digital"], "url": "stories/eniac-changing-problem-and-human-work/index.html", "image": "../media/eniac-changing-problem-and-human-work.png", "alt": "1940\ub144\ub300 \ucd08\uae30 \ucef4\ud4e8\ud130\uc758 \ud328\ub110 \uc55e\uc5d0\uc11c \uc5f0\uacb0\uacfc \uc791\uc5c5 \ub178\ud2b8\ub97c \ud655\uc778\ud558\ub294 \uc775\uba85\uc758 \uc791\uc5c5\uc790\ub4e4 \uc0bd\ud654", "text": "\uc5d0\ub2c8\uc545 \u2014 \uacc4\uc0b0\uc740 \ube68\ub77c\uc84c\ub294\ub370 \ubb38\uc81c\ub97c \ubc14\uafb8\ub294 \ub370\ub294 \uc2dc\uac04\uc774 \uac78\ub838\ub2e4 1946\ub144 \uc6b4\uc6a9 \uc124\uba85\uc11c\uc5d0\uc11c \ub9cc\ub098\ub294 \ucef4\ud4e8\ud130 \uc55e\uc758 \uc0ac\ub78c\ub4e4 \uc5d0\ub2c8\uc545\uc758 \uc7a5\uce58\uc640 \uc124\uc815\u00b7\uc2dc\ud5d8 \uc808\ucc28\ub97c \ub530\ub77c, \ube60\ub978 \uacc4\uc0b0 \ub4a4\uc5d0 \ud544\uc694\ud588\ub358 \uc900\ube44 \uc791\uc5c5\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ucef4\ud4e8\ud130\uc758 \uc5ed\uc0ac \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \uc544\uc8fc \ube60\ub974\uac8c \uacc4\uc0b0\ud558\ub294 \uae30\uacc4\uac00 \uc788\ub2e4. \uadf8\ub7f0\ub370 \uc774\ubc88 \ubb38\uc81c\ub97c \ub05d\ub0b4\uace0 \ub2e4\ub978 \ubb38\uc81c\ub97c \ub9e1\uae30\ub824 \ud558\uc790 \uc0ac\ub78c\ub4e4\uc774 \ub2e4\uc2dc \uae30\uacc4 \uc55e\uc5d0 \ubaa8\uc778\ub2e4. \uc5f0\uacb0\uacfc \uc2a4\uc704\uce58\ub97c \uc0b4\ud53c\uace0 \uc22b\uc790\ub97c \uc900\ube44\ud558\uba70 \uacb0\uacfc\uac00 \uc81c\ub300\ub85c \ub098\uc624\ub294\uc9c0 \uc2dc\ud5d8\ud574\uc57c \ud55c\ub2e4. \uacc4\uc0b0\uc774 \ube68\ub77c\uc9c0\ub294 \uac83\uacfc \ubaa8\ub4e0 \uc900\ube44\uac00 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uac19\uc740 \uc77c\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ucd08\uae30 \uc804\uc790\uc2dd \ucef4\ud4e8\ud130 \uc5d0\ub2c8\uc545\uc744 \ubcfc \ub54c \uac70\ub300\ud55c \ud06c\uae30\uc640 \uc18d\ub3c4\ubd80\ud130 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 1946\ub144\uc758 \uc6b4\uc6a9 \uc124\uba85\uc11c\ub97c \uc77d\uc73c\uba74 \uadf8 \uc55e\uc5d0\uc11c \uc77c\ud558\ub358 \uc0ac\ub78c\ub4e4\uc758 \uacfc\uc81c\uac00 \ubcf4\uc778\ub2e4. \uc22b\uc790\ub97c \ucc98\ub9ac\ud558\ub294 \uc7a5\uce58\ub9cc\ud07c\uc774\ub098 \uadf8 \uc7a5\uce58\ub97c \uc77c\ud558\uac8c \ub9cc\ub4dc\ub294 \uc21c\uc11c\uac00 \uc911\uc694\ud588\ub2e4. \uc624\ub298\uc740 \ud504\ub85c\uadf8\ub7a8\uc744 \uc5f4\uace0 \ud30c\uc77c\uc744 \uc120\ud0dd\ud558\ub294 \ub3d9\uc791\uc73c\ub85c \uae30\uacc4\uc5d0 \ud560 \uc77c\uc744 \uc904 \uc218 \uc788\ub2e4. \uc5d0\ub2c8\uc545\uc758 \ucd08\uae30 \uc6b4\uc6a9\uc744 \uc774 \uacbd\ud5d8\uacfc \ub611\uac19\uc774 \uc0c1\uc0c1\ud558\uba74 \ub9ce\uc740 \ubd80\ubd84\uc744 \ub193\uce5c\ub2e4. \uc5ec\ub7ec \uacc4\uc0b0 \uc7a5\uce58\uac00 \uc5b4\ub5bb\uac8c \uc22b\uc790\ub97c \uc8fc\uace0\ubc1b\uace0 \uc5b4\ub5a4 \uc2e0\ud638\ub85c \ub2e4\uc74c \uc77c\uc744 \uc2dc\uc791\ud560\uc9c0 \uc815\ud558\ub294 \uc791\uc5c5\uc774 \ud6e8\uc52c \uc9c1\uc811\uc801\uc73c\ub85c \ub4dc\ub7ec\ub098 \uc788\uc5c8\ub2e4. \uc5ec\uae30\uc11c \ucc38\uace0\ud558\ub294 \uc790\ub8cc\ub294 \ubbf8\uad6d \uc721\uad70\uc758 \uac10\ub3c5 \uc544\ub798 \ud39c\uc2e4\ubca0\uc774\ub2c8\uc544 \ub300\ud559\uad50 \ubb34\uc5b4 \uc2a4\ucfe8\uc774 \uc791\uc131\ud55c 1946\ub144 6\uc6d4\uc758 \uc6b4\uc6a9 \uc124\uba85\uc11c\ub2e4. \uc5d0\ub2c8\uc545\uc758 \ubaa8\ub4e0 \uc2dc\uae30\uc640 \uac1c\uc120\uc744 \ud55c\uaebc\ubc88\uc5d0 \uc124\uba85\ud558\ub294 \uc790\ub8cc\ub85c \uc4f0\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud55c \uae30\uacc4\ub3c4 \uc6b4\uc6a9 \ubc29\uc2dd\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc73c\ubbc0\ub85c \uc5b4\ub290 \ub54c\uc758 \ubaa8\uc2b5\uc744 \uc77d\ub294\uc9c0 \uba3c\uc800 \uc815\ud574\uc57c \ud55c\ub2e4. \uc124\uba85\uc11c\uc758 \ubaa9\ucc28\uc5d0\ub294 \ub204\uc0b0\uae30\uc640 \uace0\uc18d \uacf1\uc148\uae30, \ud568\uc218\ud45c\uc640 \uc8fc \uc81c\uc5b4 \uc7a5\uce58, \uc77d\uace0 \ucd9c\ub825\ud558\ub294 \uc7a5\uce58 \ub4f1\uc774 \ub530\ub85c \ub4f1\uc7a5\ud55c\ub2e4. \ub204\uc0b0\uae30\ub294 \uacc4\uc0b0 \uc911\uc758 \uc218\ub97c \ubcf4\uad00\ud558\uace0 \ub354\ud558\ub294 \uc5ed\ud560\ub85c \uc774\ud574\ud558\uba74 \ub41c\ub2e4. \uc775\uc219\ud558\uc9c0 \uc54a\uc740 \uc774\ub984\uc744 \ubaa8\ub450 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uae30\uacc4 \uc548\uc5d0\uc11c \uc5ed\ud560\uc774 \ub098\ub258\uc5b4 \uc788\uc5c8\ub2e4\ub294 \uc810\uc744 \ubcfc \uc218 \uc788\ub2e4. \uc0ac\ub78c\uc774 \uae34 \uacc4\uc0b0\uc744 \ud560 \ub54c\ub3c4 \uc911\uac04 \uacb0\uacfc\ub97c \uc801\uc5b4 \ub450\uace0 \ub2e4\uc74c \ub2e8\uacc4\uc5d0\uc11c \ub2e4\uc2dc \uc0ac\uc6a9\ud55c\ub2e4. \uae30\uacc4\uc5d0\uc11c\ub3c4 \uc5b4\ub5a4 \uc22b\uc790\ub97c \uc5b4\ub514\uc5d0 \ub450\uace0 \uc5b8\uc81c \ubcf4\ub0b4\ub294\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \ube60\ub978 \ubd80\ud488\uc744 \ubaa8\uc558\ub2e4\uace0 \uc6d0\ud558\ub294 \ub2f5\uc774 \uc800\uc808\ub85c \uc0dd\uae30\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5ec\ub7ec \uc5ed\ud560\uc774 \uc54c\ub9de\uc740 \uc21c\uc11c\ub85c \uc5f0\uacb0\ub418\uc5b4\uc57c \ud558\ub098\uc758 \uacc4\uc0b0\uc774 \ub41c\ub2e4. \uc77c\uc0c1 \uc5b8\uc5b4\ub85c \uc801\uc740 \ubb38\uc81c\ub294 \uae30\uacc4\uac00 \ubc14\ub85c \uc218\ud589\ud560 \ub3d9\uc791 \ubaa9\ub85d\uacfc \ub2e4\ub974\ub2e4. \uc5b4\ub5a4 \uac12\uc744 \uba3c\uc800 \uc77d\uace0 \ubb34\uc5c7\uc744 \ub354\ud558\uba70 \uc5b8\uc81c \ubc18\ubcf5\uc744 \uba48\ucd9c\uc9c0 \uc815\ud574\uc57c \ud55c\ub2e4. \ubcf5\uc7a1\ud55c \ubb38\uc81c\ub97c \uc791\uc740 \ub2e8\uacc4\ub85c \ud480\uc5b4 \ub193\ub294 \uc77c\uc740 \uc804\uc790 \uc7a5\uce58\uc758 \uc18d\ub3c4\uc640 \ubcc4\uac1c\ub85c \uc0ac\ub78c\uc758 \ud310\ub2e8\uc744 \uc694\uad6c\ud588\ub2e4. \ubb34\uc5c7\uc744 \uacc4\uc0b0\ud560\uc9c0 \uc774\ud574\ud558\ub294 \uc791\uc5c5\uc774 \uba3c\uc800\uc600\ub2e4. \uc774\ub7f0 \uacfc\uc815\uc744 \uc624\ub298\uc758 \ud504\ub85c\uadf8\ub798\ubc0d\uacfc \uc5f0\uacb0\ud574 \ubcfc \uc218 \uc788\uc9c0\ub9cc \ub3c4\uad6c\uc640 \ubc29\ubc95\uae4c\uc9c0 \uac19\uc558\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ucd08\uae30 \uc5d0\ub2c8\uc545\uc5d0\uc11c\ub294 \uc124\uc815\uacfc \uc5f0\uacb0\uc774 \ub208\uc55e\uc758 \ud558\ub4dc\uc6e8\uc5b4\uc640 \uae34\ubc00\ud558\uac8c \uc774\uc5b4\uc84c\ub2e4. \ucd94\uc0c1\uc801\uc778 \uacc4\uc0b0 \uc21c\uc11c\uac00 \uc2e4\uc81c \uc7a5\uce58\uc758 \ub3d9\uc791\uc73c\ub85c \uc62e\uaca8\uc9c0\ub294 \uacfc\uc815\uc774 \uae30\uacc4 \uc55e\uc758 \uc77c\ub85c \ub098\ud0c0\ub0ac\ub2e4. \uc124\uba85\uc11c\ub294 \uc7a5\uce58 \uc0ac\uc774\uc758 \uc5f0\uacb0\uacfc \uc5ec\ub7ec \uc2a4\uc704\uce58\uc758 \uc124\uc815\uc744 \uc790\uc138\ud788 \ub2e4\ub8ec\ub2e4. \ud544\uc694\ud55c \uacbd\ub85c\ub97c \ub9de\ucd94\uace0 \uc2e0\ud638\uac00 \uae30\ub300\ud55c \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc774\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud588\ub2e4. \uadf8\ub9bc\uc774\ub098 \uc0ac\uc9c4 \uc18d \ubcf5\uc7a1\ud55c \uc120\uc744 \ub2e8\uc21c\ud55c \uc7a5\uc2dd\ucc98\ub7fc \ubcf4\uba74 \uc5d0\ub2c8\uc545\uc744 \uc0ac\uc6a9\ud558\ub294 \ub178\ub3d9\uc774 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc120\uacfc \uc124\uc815\uc740 \uae30\uacc4\uac00 \ud560 \uc77c\uc744 \uad6c\uc131\ud558\ub294 \uc77c\ubd80\uc600\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \uacc4\uc0b0\uc758 \ubaa8\ub4e0 \ub3d9\uc791\ub9c8\ub2e4 \uc0ac\ub78c\uc774 \uc120\uc744 \ubc14\uafb8\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc801\uc808\ud788 \uc900\ube44\ub41c \ub4a4\uc5d0\ub294 \uae30\uacc4\uac00 \ube60\ub974\uac8c \uc5f0\uc18d \uc791\uc5c5\uc744 \uc218\ud589\ud560 \uc218 \uc788\uc5c8\ub2e4. \uc900\ube44 \uacfc\uc815\uacfc \uc2e4\ud589 \uacfc\uc815\uc744 \uad6c\ubd84\ud574\uc57c \uc18d\ub3c4\uac00 \uc758\ubbf8\ud558\ub294 \ubc14\ub97c \uc81c\ub300\ub85c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ub290\ub9b0 \uc900\ube44\uc640 \ube60\ub978 \uacc4\uc0b0\uc774 \uac19\uc740 \uc791\uc5c5 \uc548\uc5d0 \ud568\uaed8 \uc874\uc7ac\ud588\ub2e4. \uc124\uba85\uc11c\uc5d0\ub294 \uc7a5\uce58\ub97c \ud655\uc778\ud558\uace0 \uacb0\uacfc\ub97c \ube44\uad50\ud558\ub294 \uc808\ucc28\uac00 \ub4f1\uc7a5\ud55c\ub2e4. \uae30\ub300\ud55c \uac12\uacfc \uc2e4\uc81c \ucd9c\ub825\uc774 \ub9de\ub294\uc9c0 \uc0b4\ud53c\ub294 \uc77c\uc740 \ubd80\uc218\uc801\uc778 \uc815\ub9ac\uac00 \uc544\ub2c8\uc5c8\ub2e4. \uacc4\uc0b0\uc774 \ube60\ub97c\uc218\ub85d \uc798\ubabb\ub41c \uc124\uc815\ub3c4 \ube60\ub974\uac8c \ub9ce\uc740 \uacb0\uacfc\ub97c \ub9cc\ub4e4\uc5b4 \ub0bc \uc218 \uc788\ub2e4. \uc2e4\ud589\ub418\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc62c\ubc14\ub974\uac8c \uc2e4\ud589\ub418\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub974\ub2e4. \uc2dc\ud5d8\uc6a9 \ub370\uc774\ud130\ub97c \uc0ac\uc6a9\ud558\uace0 \ubd80\ubd84 \uacb0\uacfc\ub97c \uc810\uac80\ud558\ub294 \ud0dc\ub3c4\ub294 \uc624\ub298\uc758 \ucef4\ud4e8\ud130 \uc791\uc5c5\uc5d0\ub3c4 \ub0af\uc124\uc9c0 \uc54a\ub2e4. \ub2e4\ub9cc \ud604\uc7ac\uc758 \ub3c4\uad6c\ub97c \uacfc\uac70\uc5d0 \uadf8\ub300\ub85c \ud22c\uc0ac\ud558\uae30\ubcf4\ub2e4 \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc774 \uac00\uc9c4 \uc218\ub2e8\uc73c\ub85c \uc5b4\ub5bb\uac8c \uc2e0\ub8b0\ub97c \ub9cc\ub4e4\uc5c8\ub294\uc9c0 \ubcf4\uba74 \uc88b\ub2e4. \uae30\uacc4\uc758 \ubbff\uc744 \ub9cc\ud568\uc740 \uc18d\ub3c4\ub9cc\uc774 \uc544\ub2c8\ub77c \ud655\uc778\ud558\ub294 \uc808\ucc28\uc5d0\uc11c\ub3c4 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4. \uac70\ub300\ud55c \ucef4\ud4e8\ud130\uc758 \uc5ed\uc0ac\ub97c \uc774\ub984 \uc788\ub294 \ubc1c\uba85\uac00 \uba87 \uba85\uc758 \uc774\uc57c\uae30\ub85c\ub9cc \uae30\uc5b5\ud558\uba74 \uc7a5\uce58\ub97c \uc124\uc815\ud558\uace0 \uc790\ub8cc\ub97c \uc900\ube44\ud558\uace0 \uc774\uc0c1\uc744 \ucc3e\uc544\ub0b4\ub358 \uc5ec\ub7ec \uc5ed\ud560\uc774 \ud750\ub824\uc9c4\ub2e4. \uc6b4\uc6a9 \uc124\uba85\uc11c\ub294 \uac1c\uc778\uc758 \uc0dd\uc560\ub97c \ubaa8\ub450 \uc54c\ub824 \uc8fc\uc9c0\ub294 \uc54a\uc9c0\ub9cc \ud574\uc57c \ud560 \uc77c\uc774 \uc5bc\ub9c8\ub098 \ub9ce\uc558\ub294\uc9c0 \ubcf4\uc5ec \uc900\ub2e4. \uadf8 \uc791\uc5c5\ub4e4\uc744 \ub204\uad70\uac00\ub294 \uc2e4\uc81c\ub85c \uc218\ud589\ud588\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\ub3c4 \ud2b9\uc815 \uc778\ubb3c\uc758 \uc2e4\uc81c \ubaa8\uc2b5\uc744 \uc7ac\ud604\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ucd08\uae30 \ucef4\ud4e8\ud130 \uc55e\uc758 \uc778\uac04 \ub178\ub3d9\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc704\ud55c \ud574\uc11d\uc801 \uc7a5\uba74\uc774\ub2e4. \uc0ac\uc9c4\ucc98\ub7fc \ubc1b\uc544\ub4e4\uc774\uc9c0 \uc54a\uc73c\uba74\uc11c\ub3c4 \uae30\uacc4\ub97c \uc0ac\ub78c \uc5c6\ub294 \ubc29\uc73c\ub85c \uc0c1\uc0c1\ud558\uc9c0 \uc54a\ub294 \ub370 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4. \uae30\uc220\uc758 \uc5ed\uc0ac\ub294 \uc791\ub3d9\ud558\ub294 \uc7a5\uce58\uc640 \uadf8\uac83\uc744 \ub2e4\ub8e8\ub294 \uc190\uc774 \ub9cc\ub098\ub294 \uacf3\uc5d0 \uc788\ub2e4. \uc5d0\ub2c8\uc545\uc744 \ub9cc\ub0ac\uc744 \ub54c \uc911\uc694\ud55c \uc22b\uc790 \uba87 \uac1c\ub97c \uc678\uc6b0\ub294 \ub300\uc2e0 \ud55c \ubc88\uc758 \uc791\uc5c5\uc744 \uc0c1\uc0c1\ud574 \ubcf4\uc790. \ubb38\uc81c\ub97c \uc774\ud574\ud558\uace0 \uc808\ucc28\ub97c \ub098\ub204\uace0 \uc124\uc815\uc744 \uc900\ube44\ud55c \ub4a4 \uc2dc\ud5d8\uc744 \uac70\uccd0 \uacb0\uacfc\ub97c \uc5bb\ub294\ub2e4. \uae30\uacc4\uac00 \uc22b\uc790\ub97c \ucc98\ub9ac\ud55c \uc2dc\uac04\uc740 \uadf8 \uacfc\uc815 \uc804\uccb4\uc758 \ud55c \ubd80\ubd84\uc774\uc5c8\ub2e4. \uc131\ub2a5\uc758 \uc22b\uc790\ub9cc\uc73c\ub85c \uc0ac\ub78c\uc758 \uc2dc\uac04\uc774 \ubaa8\ub450 \uc124\uba85\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc624\ub298\ub3c4 \ube60\ub978 \ucef4\ud4e8\ud130\ub97c \uac16\ucd94\uc5c8\ub2e4\uace0 \ud574\uc57c \ud560 \uc77c\uc774 \uc2a4\uc2a4\ub85c \uc815\ud574\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc9c8\ubb38\uacfc \uc785\ub825, \ud655\uc778\uc758 \ubc29\uc2dd\uc740 \uc5ec\uc804\ud788 \uc911\uc694\ud558\ub2e4. \uc5d0\ub2c8\uc545\uc758 \uc624\ub798\ub41c \uc124\uba85\uc11c\ub294 \ub0a1\uc740 \uc2a4\uc704\uce58\uc758 \uc0ac\uc6a9\ubc95\uc744 \ub118\uc5b4 \uadf8 \ucc28\uc774\ub97c \ubcf4\uac8c \ud55c\ub2e4. \ub354 \ube68\ub9ac \uacc4\uc0b0\ud558\ub294 \uc77c\uacfc \ubb34\uc5c7\uc744 \uc5b4\ub5bb\uac8c \uacc4\uc0b0\ud560\uc9c0 \uc815\ud558\ub294 \uc77c\uc740 \uc11c\ub85c \uc5f0\uacb0\ub418\uc9c0\ub9cc \uac19\uc740 \uc77c\uc740 \uc544\ub2c8\ub2e4."}, {"id": "git-saving-many-versions", "title": "\ucd5c\uc885\ubcf8, \uc9c4\uc9dc \ucd5c\uc885\ubcf8 \u2014 \uae43\uc740 \ubb34\uc5c7\uc744 \uae30\uc5b5\ud560\uae4c", "summary": "2005\ub144\uc758 \uac1c\ubc1c \ubc30\uacbd\uacfc \uc6d0\uace0 \ud3b8\uc9d1\uc758 \ube44\uc720\ub97c \ud1b5\ud574 \ubc84\uc804 \uad00\ub9ac\uac00 \ud544\uc694\ud55c \uc774\uc720\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\uc18c\ud504\ud2b8\uc6e8\uc5b4", "categories": ["digital"], "url": "stories/git-saving-many-versions/index.html", "image": "../media/git-saving-many-versions.png", "alt": "\ub450 \ud3b8\uc9d1\uc790\uac00 \uc5ec\ub7ec \uc6d0\uace0\uc640 \ub178\ud2b8\ubd81\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubcf4\uba70 \ub2e4\ub978 \ud310\ubcf8\uc744 \ube44\uad50\ud558\ub294 \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ucd5c\uc885\ubcf8, \uc9c4\uc9dc \ucd5c\uc885\ubcf8 \u2014 \uae43\uc740 \ubb34\uc5c7\uc744 \uae30\uc5b5\ud560\uae4c \uc5ec\ub7ec \uc0ac\ub78c\uc774 \uace0\uccd0\ub3c4 \uc791\uc5c5\uc758 \ud750\ub984\uc744 \uc783\uc9c0 \uc54a\ub294 \ubc29\ubc95 2005\ub144\uc758 \uac1c\ubc1c \ubc30\uacbd\uacfc \uc6d0\uace0 \ud3b8\uc9d1\uc758 \ube44\uc720\ub97c \ud1b5\ud574 \ubc84\uc804 \uad00\ub9ac\uac00 \ud544\uc694\ud55c \uc774\uc720\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uc18c\ud504\ud2b8\uc6e8\uc5b4 \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \uc6d0\uace0\ub97c \uace0\uce5c \ub4a4 \uc774\ub984\uc744 \ucd5c\uc885\ubcf8\uc73c\ub85c \uc800\uc7a5\ud55c\ub2e4. \ub2e4\uc2dc \uace0\uce58\uba74 \uc9c4\uc9dc \ucd5c\uc885\ubcf8\uc774 \ub418\uace0, \ub2e4\uc74c\uc5d0\ub294 \ucd5c\uc885\ubcf8 \uc218\uc815\uc774 \ub41c\ub2e4. \ub450 \uc0ac\ub78c\uc774 \uac01\uc790 \ubc1b\uc740 \ud30c\uc77c\uc744 \uace0\uce58\uae30 \uc2dc\uc791\ud558\uba74 \uc5b4\ub5a4 \ubb38\uc7a5\uc774 \ucd5c\uc2e0\uc778\uc9c0\ub3c4 \ud5f7\uac08\ub9b0\ub2e4. \uc18c\ud504\ud2b8\uc6e8\uc5b4\ub97c \ub9cc\ub4dc\ub294 \uc0ac\ub78c\ub4e4\ub3c4 \ube44\uc2b7\ud55c \ubb38\uc81c\ub97c \ud6e8\uc52c \ud070 \uaddc\ubaa8\ub85c \uacaa\ub294\ub2e4. \uae43\uc740 \uc774\ub7f0 \uc791\uc5c5\uc758 \uc0c1\ud0dc\uc640 \uc774\ub825\uc744 \uad00\ub9ac\ud558\ub294 \ub3c4\uad6c\ub2e4. \uba85\ub839\uc5b4\ub97c \ubc30\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uc65c \ud544\uc694\ud55c\uc9c0\ub294 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ubb34\uc5c7\uc744 \ubc14\uafb8\uc5c8\ub294\uc9c0 \uae30\uc5b5\ud558\uace0 \uc11c\ub85c \ub2e4\ub978 \uc791\uc5c5\uc744 \ube44\uad50\ud558\uba70 \ub2e4\uc2dc \uc774\uc5b4 \ubd99\uc77c \uc218 \uc788\uc5b4\uc57c \uc5ec\ub7ec \uc0ac\ub78c\uc774 \ud558\ub098\uc758 \uacb0\uacfc\ubb3c\uc744 \ub9cc\ub4e4 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ud30c\uc77c \uc774\ub984\uc744 \ubc14\uafb8\uc5b4 \ubcf4\uad00\ud558\uba74 \uba87 \uac1c\uc758 \uacfc\uac70 \uc0c1\ud0dc\ub294 \ub0a8\uae38 \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc218\ubc31 \uac1c\uc758 \ud30c\uc77c\uc774 \ud568\uaed8 \ubc14\ub00c\ub294 \ud504\ub85c\uc81d\ud2b8\ub77c\uba74 \uc774\uc57c\uae30\uc758 \ub2e8\uc704\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uc5b4\ub290 \ubb38\uc11c\uc640 \uc5b4\ub290 \uc774\ubbf8\uc9c0\uac00 \uac19\uc740 \uc2dc\uc810\uc758 \ud55c \ubb36\uc74c\uc778\uc9c0\ub3c4 \uc54c\uc544\uc57c \ud55c\ub2e4. \uae43\uc5d0\uc11c \uc791\uc5c5 \uc0c1\ud0dc\ub97c \uae30\ub85d\ud558\ub294 \ucee4\ubc0b\uc740 \uc774\ub7f0 \ubb36\uc74c\uc744 \ub0a8\uae30\ub294 \ud589\uc704\ub2e4. \u300aPro Git\u300b\uc740 \uc774\ub97c \ud504\ub85c\uc81d\ud2b8\uc758 \uc2a4\ub0c5\uc20f\uc774\ub77c\ub294 \ub9d0\ub85c \uc124\uba85\ud55c\ub2e4. \uc2e4\uc81c \ud654\uba74 \uc0ac\uc9c4\uc744 \ucc0d\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uadf8\ub54c\uc758 \ud30c\uc77c \uc0c1\ud0dc\ub97c \uac00\ub9ac\ud0a8\ub2e4. \ubc14\ub00c\uc9c0 \uc54a\uc740 \ud30c\uc77c\uae4c\uc9c0 \ub9e4\ubc88 \uc0c8\ub85c \ud1b5\uc9f8\ub85c \uc911\ubcf5 \uc800\uc7a5\ud55c\ub2e4\ub294 \ub73b\ub3c4 \uc544\ub2c8\ub2e4. \uae43\uc758 \uc5ed\uc0ac \uc548\ub0b4\ub294 \ub9ac\ub205\uc2a4 \ucee4\ub110 \uac1c\ubc1c\uc5d0\uc11c \ucd9c\ubc1c\ud55c \ubc30\uacbd\uc744 \uc124\uba85\ud55c\ub2e4. \ub9ac\ub205\uc2a4 \uac1c\ubc1c\uc790\ub4e4\uc740 2002\ub144\ubd80\ud130 \ube44\ud2b8\ud0a4\ud37c\ub77c\ub294 \ub3c4\uad6c\ub97c \uc0ac\uc6a9\ud588\uc9c0\ub9cc, 2005\ub144 \uac1c\ubc1c \uacf5\ub3d9\uccb4\uc640 \uadf8 \ud68c\uc0ac\uc758 \uad00\uacc4\uac00 \ud2c0\uc5b4\uc9c0\uace0 \ubb34\ub8cc \uc0ac\uc6a9\uc774 \uc911\ub2e8\ub418\uc5c8\ub2e4. \ub9ac\ub204\uc2a4 \ud1a0\ub974\ubc1c\uc2a4 \ub4f1\uc744 \uc911\uc2ec\uc73c\ub85c \uc0c8 \ub3c4\uad6c\ub97c \ub9cc\ub4e4\uac8c \ub41c \uacc4\uae30\uc600\ub2e4. \ube60\ub974\uac8c \uc791\ub3d9\ud558\uace0, \ud070 \ud504\ub85c\uc81d\ud2b8\ub97c \ub2e4\ub8e8\uba70, \uc5ec\ub7ec \uac08\ub798\uc758 \uc791\uc5c5\uc744 \uc9c0\uc6d0\ud558\uace0, \ud55c\uacf3\uc5d0\ub9cc \uc758\uc874\ud558\uc9c0 \uc54a\ub294 \ubc29\uc2dd\uc774 \ubaa9\ud45c\uc5d0 \ub4e4\uc5b4\uac14\ub2e4. \ucc98\uc74c\ubd80\ud130 \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \uc77c\uc0c1 \ud30c\uc77c\uc744 \uc704\ud55c \uc11c\ube44\uc2a4\ub85c \uae30\ud68d\ub418\uc5c8\ub2e4\uae30\ubcf4\ub2e4 \ud070 \uacf5\ub3d9 \uac1c\ubc1c\uc758 \ud544\uc694\uc5d0\uc11c \ub098\uc628 \uac83\uc774\ub2e4. \uc6d0\uace0\uc5d0\uc11c \ubb38\uc7a5 \ud558\ub098\uac00 \ubc14\ub00c\uc5c8\ub2e4\uba74 \uc774\uc804\uacfc \uc774\ud6c4\ub97c \ube44\uad50\ud574 \ubcfc \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uc791\uc5c5\uc758 \uae30\ub85d\uc5d0\ub294 \ub0b4\uc6a9\ubfd0 \uc544\ub2c8\ub77c \ubcc0\uacbd\uc744 \uc124\uba85\ud558\ub294 \ub9d0\ub3c4 \uc911\uc694\ud558\ub2e4. \uc65c \uace0\ucce4\ub294\uc9c0 \ub0a8\uaca8 \ub450\uba74 \ub098\uc911\uc758 \ub3c5\uc790\uac00 \uadf8\ub54c\uc758 \uc758\ub3c4\ub97c \uc9d0\uc791\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ucef4\ud4e8\ud130\uac00 \ubcc0\uacbd \uc790\uccb4\ub97c \uae30\uc5b5\ud558\ub294 \uac83\uacfc \uc0ac\ub78c\uc774 \ubcc0\uacbd\uc744 \uc774\ud574\ud558\ub294 \uac83\uc740 \ub2e4\ub978 \ubb38\uc81c\ub2e4. \uae30\ub85d\uc744 \ub0a8\uacbc\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc88b\uc740 \uc124\uba85\uc774 \uc0dd\uae30\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5b4\ub290 \ubb38\uc7a5\uc744 \ubc14\uafb8\uc5c8\ub294\uc9c0\ub294 \ubcf4\uc5ec\ub3c4 \uc65c \uc0ac\uc2e4\uad00\uacc4\ub97c \uc218\uc815\ud588\ub294\uc9c0 \uc4f0\uc9c0 \uc54a\uc73c\uba74 \ub2e4\uc2dc \uc790\ub8cc\ub97c \ucc3e\uc544\uc57c \ud560 \uc218 \uc788\ub2e4. \ub3c4\uad6c\uc758 \uae30\uc5b5 \uc704\uc5d0 \uc0ac\ub78c\uc758 \uc124\uba85\uc774 \ud544\uc694\ud558\ub2e4. \ud55c \uc6d0\uace0\uc758 \ub3c4\uc785\ubd80\ub97c \ub450 \uac00\uc9c0\ub85c \uace0\uccd0 \ubcf4\uace0 \uc2f6\ub2e4\uace0 \ud574 \ubcf4\uc790. \uc9c0\uae08\uc758 \uc6d0\uace0\ub97c \ubc14\ub85c \ub36e\uc5b4\uc4f0\uc9c0 \uc54a\uace0 \ub2e4\ub978 \ud750\ub984\uc5d0\uc11c \uc2e4\ud5d8\ud560 \uc218 \uc788\ub2e4\uba74 \ub9c8\uc74c\uc774 \uac00\ubcbc\uc6cc\uc9c4\ub2e4. \uae43\uc758 \ube0c\ub79c\uce58\ub294 \uc5ec\ub7ec \uac08\ub798\uc758 \uc791\uc5c5\uc744 \ub2e4\ub8f0 \uc218 \uc788\uac8c \ud558\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc774\uac83\uc740 \ub2e8\uc21c\ud788 \ud3f4\ub354\ub97c \ud558\ub098 \ub354 \ubcf5\uc0ac\ud574 \ub450\ub294 \uac83\uacfc \uc791\ub3d9 \uc6d0\ub9ac\uac00 \uac19\uc9c0\ub294 \uc54a\uc9c0\ub9cc, \ub3c5\uc790\uac00 \ubaa9\uc801\uc744 \uc774\ud574\ud558\uae30\uc5d0\ub294 \ub3c4\uc6c0\uc774 \ub418\ub294 \ube44\uc720\ub2e4. \ud55c \uac08\ub798\uc5d0\uc11c\ub294 \ud45c\ud604\uc744 \uace0\uce58\uace0 \ub2e4\ub978 \uac08\ub798\uc5d0\uc11c\ub294 \uc790\ub8cc\ub97c \ubcf4\uc644\ud55c \ub4a4 \uacb0\uacfc\ub97c \ube44\uad50\ud560 \uc218 \uc788\ub2e4. \uc120\ud0dd\ud558\uc9c0 \uc54a\uc740 \uc2e4\ud5d8\uacfc \ud604\uc7ac \uc0ac\uc6a9\ud560 \uacb0\uacfc\ub97c \uad6c\ubcc4\ud558\uae30 \uc26c\uc6cc\uc9c4\ub2e4. \ub450 \uc0ac\ub78c\uc774 \uc11c\ub85c \ub2e4\ub978 \ubb38\ub2e8\uc744 \uace0\ucce4\ub2e4\uba74 \ubcc0\uacbd\uc744 \ud568\uaed8 \ubc18\uc601\ud558\uae30\uac00 \ube44\uad50\uc801 \uc27d\ub2e4. \uadf8\ub7f0\ub370 \uac19\uc740 \ubb38\uc7a5\uc744 \uc11c\ub85c \ub2e4\ub974\uac8c \uace0\uce58\uba74 \uc5b4\ub290 \ucabd\uc774 \ub9de\ub294\uc9c0 \uc0ac\ub78c\uc774 \uacb0\uc815\ud574\uc57c \ud560 \uc218 \uc788\ub2e4. \uc774\ub7f0 \ucda9\ub3cc\uc744 \ubc1c\uacac\ud558\ub294 \uc77c\uacfc \ub0b4\uc6a9\uc758 \uc815\ub2f5\uc744 \ud310\ub2e8\ud558\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uae43\uc740 \uc5ed\uc0ac\uc801 \uc0ac\uc2e4\uc744 \uc544\ub294 \ud3b8\uc9d1\uc790\uac00 \uc544\ub2c8\ub2e4. \ubb38\uc7a5\uc774 \ub354 \uc815\ud655\ud55c\uc9c0, \uc791\ud488 \uc81c\ubaa9\uc744 \uc798\ubabb \uc801\uc5c8\ub294\uc9c0\uae4c\uc9c0 \uc2a4\uc2a4\ub85c \ubcf4\uc7a5\ud558\uc9c0 \uc54a\ub294\ub2e4. \ubcc0\uacbd\uc744 \ube44\uad50\ud558\uace0 \uc120\ud0dd\ud560 \uc790\ub9ac\ub97c \uc81c\uacf5\ud560 \ubfd0\uc774\ub2e4. \ud611\uc5c5\uc758 \uc218\uace0\ub97c \uc904\uc774\uba74\uc11c\ub3c4 \uc911\uc694\ud55c \ud310\ub2e8\uc740 \uc0ac\ub78c\uacfc \ud3b8\uc9d1 \uacfc\uc815\uc5d0 \ub0a8\ub294\ub2e4. \ubd84\uc0b0\ub41c \ubc29\uc2dd\uc774\ub77c\ub294 \ub9d0\uc740 \uac01 \uc791\uc5c5 \uacf5\uac04\uc774 \uc0c1\ub2f9\ud55c \uc774\ub825\uc744 \ud568\uaed8 \uac00\uc9c8 \uc218 \uc788\ub2e4\ub294 \ub73b\uc774\ub2e4. \u300aPro Git\u300b\uc740 \ub9ce\uc740 \uc791\uc5c5\uc744 \uc790\uae30 \ucef4\ud4e8\ud130\uc758 \uc790\ub8cc\ub85c \ucc98\ub9ac\ud560 \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc5f0\uacb0\uc774 \ub04a\uaca8\ub3c4 \ubcc0\uacbd\uc744 \uae30\ub85d\ud558\uace0 \uacfc\uac70 \uc0c1\ud0dc\ub97c \uc0b4\ud3b4\ubcf4\ub294 \uc77c\uc774 \uac00\ub2a5\ud558\ub2e4. \ub2e4\ub9cc \uc790\uae30 \ucef4\ud4e8\ud130\uc5d0 \uae30\ub85d\ud55c \ub0b4\uc6a9\uc774 \uc790\ub3d9\uc73c\ub85c \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc804\ub2ec\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud568\uaed8 \uc4f0\ub294 \uc800\uc7a5\uc18c\uc640 \ub0b4\uc6a9\uc744 \uc8fc\uace0\ubc1b\ub294 \uacfc\uc815\uc774 \ubcc4\ub3c4\ub85c \ud544\uc694\ud558\ub2e4. \uac1c\uc778\uc758 \uae30\ub85d\uacfc \uacf5\ub3d9 \uacf5\uac04\uc758 \ubc18\uc601\uc744 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \ub0b4 \ucc45\uc0c1 \uc704\uc5d0\uc11c \uc6d0\uace0\ub97c \uace0\uce5c \uac83\uacfc \ud3b8\uc9d1\ubd80 \uc804\uccb4\uc5d0 \uc0c8 \uc6d0\uace0\ub97c \uc804\ub2ec\ud55c \uac83\uc774 \ub2e4\ub978 \uac83\uacfc \ube44\uc2b7\ud558\ub2e4. \uae43\uc740 \ubc84\uc804 \uad00\ub9ac\ub97c \ud558\ub294 \ub3c4\uad6c\uc774\uace0, GitHub\ub294 \uae43 \uc800\uc7a5\uc18c\ub97c \uc628\ub77c\uc778\uc5d0\uc11c \ubcf4\uad00\ud558\uace0 \ud611\uc5c5\ud560 \uc218 \uc788\uac8c \ud558\ub294 \uc11c\ube44\uc2a4\ub2e4. \uc774\ub984\uc774 \ube44\uc2b7\ud558\uace0 \ud568\uaed8 \ub9ce\uc774 \uc4f0\uc774\uc9c0\ub9cc \ud558\ub098\uac00 \uace7 \ub2e4\ub978 \ud558\ub098\ub294 \uc544\ub2c8\ub2e4. \uae43\uc744 \uc4f0\ub294 \ubaa8\ub4e0 \uc77c\uc774 \ubc18\ub4dc\uc2dc GitHub\ub97c \uac70\uccd0\uc57c \ud558\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \ub458\uc744 \uad6c\ubcc4\ud558\uba74 \uc628\ub77c\uc778 \uc11c\ube44\uc2a4\uac00 \uc81c\uacf5\ud558\ub294 \uac80\ud1a0\uc640 \uac8c\uc2dc \uae30\ub2a5\ub3c4 \ub354 \uc798 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ud30c\uc77c\uc758 \uc774\ub825\uc744 \ub0a8\uae30\ub294 \uc77c, \ub3d9\ub8cc\uc5d0\uac8c \uc218\uc815\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc77c, \uc2e4\uc81c \ud648\ud398\uc774\uc9c0\uc5d0 \ubc18\uc601\ud558\ub294 \uc77c\uc740 \uc5f0\uacb0\ub420 \uc218 \uc788\uc9c0\ub9cc \uac01\uac01\uc758 \ub2e8\uacc4\ub2e4. \uc800\uc7a5\uc18c\uc5d0 \uc6d0\uace0\uac00 \uc788\ub2e4\uace0 \uace7\ubc14\ub85c \ub3c5\uc790\uc5d0\uac8c \uac8c\uc2dc\ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. \uae30\ub85d\ud558\uc9c0 \uc54a\uc740 \ubcc0\uacbd\uc740 \uc783\uc744 \uc218 \uc788\uace0, \uae30\ub85d\ud55c \ub0b4\uc6a9\uc744 \uc9c0\uc6b0\uac70\ub098 \uc798\ubabb \ub2e4\ub8e8\ub294 \uc77c\ub3c4 \uac00\ub2a5\ud558\ub2e4. \ubc84\uc804 \uad00\ub9ac\uac00 \ubaa8\ub4e0 \uc0ac\uace0\ub97c \ub9c9\ub294 \ub9c8\ubc95\uc758 \ubcf4\ud5d8\uc740 \uc544\ub2c8\ub2e4. \uc911\uc694\ud55c \uae30\ub85d\uc744 \ub0a8\uae30\uace0 \ub2e4\ub978 \ubcf4\uad00\ucc98\uc640 \uacf5\uc720\ud558\ub294 \uc2b5\uad00\uae4c\uc9c0 \uc788\uc5b4\uc57c \uadf8 \uc7a5\uc810\uc774 \uc0b4\uc544\ub09c\ub2e4. \uae43\uc758 \uc774\uc57c\uae30\ub294 \uacb0\uad6d \ud568\uaed8 \uace0\uce58\ub294 \uc77c\uc758 \uc5ed\uc0ac\ub2e4. \ud30c\uc77c \uc774\ub984 \ub05d\uc5d0 \ucd5c\uc885\uc774\ub77c\ub294 \ub9d0\uc744 \uba87 \ubc88 \ubd99\uc774\ub294 \ub300\uc2e0 \uc5b4\ub5a4 \uc0c1\ud0dc\uc5d0\uc11c \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0\ub97c \uc774\uc5b4 \ub0a8\uae34\ub2e4. \ub355\ubd84\uc5d0 \uc6b0\ub9ac\ub294 \uacfc\uac70\ub97c \ubaa8\ub450 \uc678\uc6b0\ub294 \ub370 \uc4f0\ub358 \ud798\uc744 \uc9c0\uae08\uc758 \ubb38\uc7a5\uc744 \ub354 \uc88b\uac8c \ub9cc\ub4dc\ub294 \ub370 \uc4f8 \uc218 \uc788\ub2e4."}, {"id": "gnu-manifesto-sharing-and-conditions", "title": "GNU \uc120\uc5b8\ubb38 \u2014 \ud504\ub85c\uadf8\ub7a8\uc744 \ub098\ub204\ub294 \uc870\uac74\ub3c4 \uc124\uacc4\ud558\ub2e4", "summary": "GNU \uc120\uc5b8\ubb38\uc758 \uacf5\uc720 \ubaa9\ud45c\uc640 \uac00\uaca9\u00b7\uc790\uc720\uc758 \ucc28\uc774, \ub2f9\uc2dc \uac1c\ubc1c \ub3c4\uad6c\uc640 \ub178\ub3d9\uc758 \ubcf4\uc218\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\uc18c\ud504\ud2b8\uc6e8\uc5b4", "categories": ["digital"], "url": "stories/gnu-manifesto-sharing-and-conditions/index.html", "image": "../media/gnu-manifesto-sharing-and-conditions.png", "alt": "1980\ub144\ub300 \ucef4\ud4e8\ud130\uc2e4\uc5d0\uc11c \uc18c\uc2a4 \ubb38\uc11c\ub97c \ud568\uaed8 \ubcf4\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "GNU \uc120\uc5b8\ubb38 \u2014 \ud504\ub85c\uadf8\ub7a8\uc744 \ub098\ub204\ub294 \uc870\uac74\ub3c4 \uc124\uacc4\ud558\ub2e4 \uae30\ub2a5\uc758 \uac1c\ubc1c\uacfc \uc218\uc815\u00b7\uc7ac\ubc30\ud3ec\uc758 \uc790\uc720\uac00 \ub9cc\ub098\ub294 \uc5ed\uc0ac GNU \uc120\uc5b8\ubb38\uc758 \uacf5\uc720 \ubaa9\ud45c\uc640 \uac00\uaca9\u00b7\uc790\uc720\uc758 \ucc28\uc774, \ub2f9\uc2dc \uac1c\ubc1c \ub3c4\uad6c\uc640 \ub178\ub3d9\uc758 \ubcf4\uc218\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc18c\ud504\ud2b8\uc6e8\uc5b4 \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \ud504\ub85c\uadf8\ub7a8\uc744 \uc5bb\uc5c8\ub2e4\uace0 \ub9c8\uc74c\ub300\ub85c \uace0\uce58\uac70\ub098 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc904 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc744 \ud5c8\uc6a9\ud558\ub294\uc9c0\ub294 \ubc30\ud3ec \uc870\uac74\uc5d0 \ub2ec\ub824 \uc788\ub2e4. \ub9ac\ucc98\ub4dc \uc2a4\ud1a8\uba3c\uc758 GNU \uc120\uc5b8\ubb38\uc740 \uc88b\uc740 \ud504\ub85c\uadf8\ub7a8\uc744 \ub9cc\ub4e4\uc790\ub294 \uc81c\uc548\uc5d0 \ub354\ud574, \uc0ac\ub78c\ub4e4\uc774 \uadf8 \ud504\ub85c\uadf8\ub7a8\uc73c\ub85c \ubb34\uc5c7\uc744 \ud560 \uc218 \uc788\uc5b4\uc57c \ud558\ub294\uc9c0\ub97c \ubb3b\ub294\ub2e4. \uae30\uc220\uc758 \uc5ed\uc0ac\uc5d0\uc11c \uc0ac\uc6a9 \uc870\uac74\ub3c4 \ud558\ub098\uc758 \uc124\uacc4\uc600\ub2e4. GNU\ub294 \uc720\ub2c9\uc2a4\uc640 \ud638\ud658\ub418\ub294 \uc790\uc720 \uc18c\ud504\ud2b8\uc6e8\uc5b4 \uc2dc\uc2a4\ud15c\uc744 \ub9cc\ub4e4\ub824\ub294 \ud504\ub85c\uc81d\ud2b8\ub85c \uc18c\uac1c\ub41c\ub2e4. \uc774\ub984\ub3c4 GNU\ub294 \uc720\ub2c9\uc2a4\uac00 \uc544\ub2c8\ub77c\ub294 \uc7ac\uadc0\uc801\uc778 \ud45c\ud604\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc775\uc219\ud55c \uc0ac\uc6a9 \ud658\uacbd\uc744 \ubaa9\ud45c\ub85c \ud558\uba74\uc11c \ub2e4\ub978 \ubc30\ud3ec \uad00\uacc4\ub97c \ub9cc\ub4e4\ub824 \ud588\ub358 \uac83\uc774\ub2e4. \ud638\ud658\ub41c\ub2e4\ub294 \ub9d0\uc740 \uae30\uc874 \ud504\ub85c\uadf8\ub7a8\uc758 \ucf54\ub4dc\ub97c \ubab0\ub798 \uac00\uc838\ub2e4 \uc368\ub3c4 \ub41c\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uc0ac\uc6a9\uc790\uac00 \ube44\uc2b7\ud55c \ubc29\uc2dd\uc73c\ub85c \uc791\uc5c5\ud560 \uc218 \uc788\ub294 \ud658\uacbd\uc744 \uc0c8\ub85c \ub9c8\ub828\ud558\ub824\ub294 \uacfc\uc81c\uc600\ub2e4. \uae30\ub2a5\uc758 \uc720\uc0ac\uc131\uacfc \ucf54\ub4dc\uc758 \ucd9c\ucc98, \ubc30\ud3ec \uad8c\ub9ac\ub294 \uc11c\ub85c \ub2e4\ub978 \ubb38\uc81c\ub2e4. \uc120\uc5b8\ubb38\uc740 \ud504\ub85c\uadf8\ub7a8\uc744 \ud568\uaed8 \uace0\uce58\ub358 \ud658\uacbd\uacfc \uacf5\uc720\ub97c \ub9c9\ub294 \uc870\uac74 \uc0ac\uc774\uc758 \uac08\ub4f1\uc744 \uc124\uba85\ud55c\ub2e4. \ud544\uc694\ud55c \uc218\uc815\uc744 \ud560 \uc218 \uc5c6\uac70\ub098 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ub3c4\uc6c0\uc744 \uc904 \uc218 \uc5c6\ub2e4\ub294 \uc0c1\ud669\uc744 \ub2e8\uc21c\ud55c \ubd88\ud3b8\ubcf4\ub2e4 \uacf5\ub3d9\uccb4\uc758 \ubb38\uc81c\ub85c \ubcf8\ub2e4. \uc0ac\uc6a9\uc790 \uc0ac\uc774\uc758 \uad00\uacc4\uac00 \uc18c\ud504\ud2b8\uc6e8\uc5b4\uc758 \uac00\uce58\uc640 \uc5f0\uacb0\ub41c\ub2e4. \uc774\ub7f0 \uad00\uc810\uc5d0 \ubaa8\ub450\uac00 \ub3d9\uc758\ud574\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uc18c\ud504\ud2b8\uc6e8\uc5b4\uc758 \ubc1c\uc804\uc744 \uc2e4\ud589 \uc18d\ub3c4\uc640 \uae30\ub2a5 \uc218\ub85c\ub9cc \uc124\uba85\ud558\uba74 \ub2f9\uc2dc\uc758 \ub17c\uc7c1\uc744 \ub193\uce5c\ub2e4. \ub204\uad6c\uc5d0\uac8c \uc218\uc815\ud560 \uad8c\ud55c\uc774 \uc788\ub294\uc9c0, \uc5bb\uc740 \uac1c\uc120\uc744 \ub2e4\uc2dc \ub098\ub20c \uc218 \uc788\ub294\uc9c0\uac00 \uc911\uc694\ud55c \uc7c1\uc810\uc774\uc5c8\ub2e4. \uc120\uc5b8\ubb38\uc758 \ud6c4\ub300 \uc8fc\uc11d\uc740 \uc790\uc720\uc640 \uac00\uaca9\uc744 \ud63c\ub3d9\ud558\uc9c0 \ub9d0\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \ube44\uc6a9\uc744 \ub0b4\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc0ac\uc6a9\u00b7\uc218\uc815\u00b7\ubc30\ud3ec\uc758 \uc790\uc720\ub97c \uac00\uc84c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uac19\uc9c0 \uc54a\ub2e4. \ubb34\ub8cc\ub85c \ub0b4\ub824\ubc1b\uc544\ub3c4 \uace0\uce60 \uc218 \uc5c6\ub294 \ud504\ub85c\uadf8\ub7a8\uc774 \uc788\uc744 \uc218 \uc788\uace0, \ube44\uc6a9\uc744 \ubc1b\uace0 \uc790\uc720 \uc18c\ud504\ud2b8\uc6e8\uc5b4\ub97c \uc81c\uacf5\ud558\ub294 \uc77c\ub3c4 \uac00\ub2a5\ud558\ub2e4. \uc774 \uad6c\ubd84\uc740 \uc9c0\uae08\ub3c4 \uc720\uc6a9\ud558\ub2e4. \ub2e4\uc6b4\ub85c\ub4dc \ubc84\ud2bc\uc758 \uac00\uaca9\ub9cc \ubcf4\uba74 \ud504\ub85c\uadf8\ub7a8\uc744 \uc5bb\uc740 \ub4a4 \ud560 \uc218 \uc788\ub294 \uc77c\uc744 \uc54c \uc218 \uc5c6\ub2e4. \uc18c\ud504\ud2b8\uc6e8\uc5b4\ub97c \uc0ac\uc6a9\ud558\ub294 \uad00\uacc4\uc5d0\ub294 \uae08\uc561 \uc678\uc5d0\ub3c4 \uc870\uac74\uc774 \uc788\ub2e4. \uc120\uc5b8\ubb38\uc740 \uadf8 \uc870\uac74\uc744 \uae30\ub2a5 \uc124\uba85\ub9cc\ud07c \uc9c4\uc9c0\ud558\uac8c \ubcf4\uc790\uace0 \uc694\uad6c\ud55c\ub2e4. GNU \uc120\uc5b8\ubb38\uc740 GNU\ub97c \ud37c\ube14\ub9ad\ub3c4\uba54\uc778\uc73c\ub85c \ub9cc\ub4e4\uaca0\ub2e4\uace0 \uc124\uba85\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc218\uc815\uacfc \uc7ac\ubc30\ud3ec\ub97c \ud5c8\uc6a9\ud558\uba74\uc11c\ub3c4, \ubc1b\uc740 \uc0ac\ub78c\uc774 \ub2e4\uc2dc \ub2e4\ub978 \uc0ac\ub78c\uc758 \uacf5\uc720\ub97c \ub9c9\ub294 \uac83\uc744 \uc81c\ud55c\ud558\ub824\ub294 \ucde8\uc9c0\ub97c \ubc1d\ud78c\ub2e4. \uad8c\ub9ac\ub97c \ud3ec\uae30\ud558\ub294 \ubc29\uc2dd\uacfc \uad8c\ub9ac\ub97c \uc774\uc6a9\ud574 \uc870\uac74\uc744 \uc720\uc9c0\ud558\ub294 \ubc29\uc2dd\uc774 \ub2e4\ub974\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc778\ud130\ub137\uc5d0 \uacf5\uac1c\ub41c \ucf54\ub4dc\uac00 \ubaa8\ub450 \uac19\uc740 \uc870\uac74\uc744 \uac00\uc9c4 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubcfc \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ubcf5\uc81c\uc640 \uc218\uc815, \uc7ac\ubc30\ud3ec\uc758 \ubc94\uc704\ub97c \ud310\ub2e8\ud558\uba74 \uc548 \ub41c\ub2e4. \uad6c\uccb4\uc801\uc778 \ud504\ub85c\uadf8\ub7a8\uc5d0 \uc801\uc6a9\ub418\ub294 \ub77c\uc774\uc120\uc2a4\ub97c \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uc120\uc5b8\ubb38\uc740 \uc6b4\ub3d9\uc758 \ubaa9\ud45c\ub97c \uc124\uba85\ud558\ub294 \uae00\uc774\uc9c0 \ubaa8\ub4e0 \uc18c\ud504\ud2b8\uc6e8\uc5b4\uc5d0 \ub300\uc2e0 \uc801\uc6a9\ub418\ub294 \uacc4\uc57d\uc11c\ub294 \uc544\ub2c8\ub2e4. \uac1c\uc120\ud55c \ucf54\ub4dc\ub97c \ub2e4\uc74c \uc0ac\ub78c\uc5d0\uac8c \uc804\ud560 \uc218 \uc788\ub2e4\uba74 \ubb38\uc81c\ub97c \ud574\uacb0\ud55c \uacb0\uacfc\uac00 \ud55c \uc870\uc9c1\uc758 \ub0b4\ubd80\uc5d0\ub9cc \uba38\ubb3c\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \ubc18\ub300\ub85c \uacf5\uac1c\ub41c \ucf54\ub4dc\ub97c \uc0ac\uc6a9\ud558\ub354\ub77c\ub3c4 \ubc30\ud3ec\ud560 \ub54c \uc5b4\ub5a4 \uc758\ubb34\uac00 \uc0dd\uae30\ub294\uc9c0\ub294 \ub530\ub85c \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \ud611\ub825\uc744 \ub113\ud788\ub294 \ubaa9\uc801\uacfc \uc2e4\uc81c \uc801\uc6a9 \uc870\uac74\uc744 \ud568\uaed8 \uc77d\ub294 \ud0dc\ub3c4\uac00 \ud544\uc694\ud558\ub2e4. \uc790\uc720 \uc18c\ud504\ud2b8\uc6e8\uc5b4\ub97c \ub2e8\uc21c\ud788 \uc8fc\uc778\uc774 \uc5c6\ub294 \ud504\ub85c\uadf8\ub7a8\uc774\ub77c\uace0 \ubd80\ub974\uba74 \uc774 \ucc28\uc774\uac00 \uc0ac\ub77c\uc9c4\ub2e4. \uc800\uc791\uad8c\uc790\uc640 \uae30\uc5ec\uc790\uc758 \uc5ed\ud560\uc774 \uc788\uace0 \uadf8 \uad8c\ud55c \uc704\uc5d0 \ud5c8\uc6a9\uc758 \ubc94\uc704\uac00 \ub193\uc778\ub2e4. GNU \uc120\uc5b8\ubb38\uc740 \ud1b5\uc81c\uc758 \ubd80\uc7ac\ubcf4\ub2e4 \ud2b9\uc815\ud55c \uc790\uc720\uac00 \ub2e4\uc74c \uc0ac\ub78c\uc5d0\uac8c\ub3c4 \uc774\uc5b4\uc9c0\ub294 \uad00\uacc4\ub97c \uc0c1\uc0c1\ud588\ub2e4. \uc774 \ubaa9\ud45c\uac00 \ubb34\uc5c7\uc778\uc9c0 \uc774\ud574\ud55c \ub2e4\uc74c\uc5d0 \uac1c\ubcc4 \ub77c\uc774\uc120\uc2a4\uc758 \ubb38\uc7a5\uc73c\ub85c \ub3cc\uc544\uac00\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc120\uc5b8\ubb38\uc5d0\ub294 \ud3b8\uc9d1\uae30\uc640 \ub514\ubc84\uac70, \ucef4\ud30c\uc77c\ub7ec\uc640 \uc5ec\ub7ec \ub3c4\uad6c, \uc544\uc9c1 \uc644\uc131\ud574\uc57c \ud560 \ubd80\ubd84\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \ud558\ub098\uc758 \ub6f0\uc5b4\ub09c \uc751\uc6a9\ud504\ub85c\uadf8\ub7a8\uacfc \uc644\uc804\ud55c \uc791\uc5c5 \ud658\uacbd\uc740 \ub2e4\ub974\ub2e4. \ud504\ub85c\uadf8\ub7a8\uc744 \uc791\uc131\ud558\uace0 \uace0\uce58\uace0 \uc2e4\ud589\ud558\ub294 \ub3c4\uad6c\ub4e4\uc774 \ud568\uaed8 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uc774 \ubaa9\ub85d\uc744 \uc624\ub298\uc758 \uc644\uc131 \ud604\ud669\uc73c\ub85c \uc77d\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uae00\uc5d0\ub294 \ub2f9\uc2dc \uc9c4\ud589 \uc0c1\ud669\uacfc \uacc4\ud68d\uc774 \ub2f4\uaca8 \uc788\uace0, \uc8fc\uc11d\uacfc \ud6c4\ub300 \uc124\uba85\ub3c4 \ub367\ubd99\uc5b4 \uc788\ub2e4. \ud55c \ubb38\uc11c \uc548\uc5d0\uc11c\ub3c4 \uc2dc\uac04\uc774 \uc5ec\ub7ec \uce35\uc73c\ub85c \ub0a8\ub294\ub2e4. \uc18c\ud504\ud2b8\uc6e8\uc5b4\uc0ac\uc758 \ubb38\uc11c\ub294 \uc5b4\ub5a4 \uc2dc\uc810\uc758 \ud604\uc7ac\ub97c \ub9d0\ud558\ub294\uc9c0 \uc0b4\ud53c\uba70 \uc77d\uc5b4\uc57c \ud55c\ub2e4. \uc120\uc5b8\ubb38\uc740 \ud504\ub85c\uadf8\ub798\uba38\uc758 \ubcf4\uc218\uac00 \uc0ac\ub77c\uc838\uc57c \ud55c\ub2e4\uace0 \ub2e8\uc21c\ud788 \uc8fc\uc7a5\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc720\uc9c0\uc640 \uad50\uc721, \uc9c0\uc6d0 \uac19\uc740 \uc77c\uc5d0\uc11c \uc218\uc785\uc774 \uc0dd\uae38 \uac00\ub2a5\uc131\uc744 \ub17c\ud55c\ub2e4. \ubcf5\uc81c\ubcf8\uc744 \ud1b5\uc81c\ud558\ub294 \ubc29\uc2dd \uc678\uc5d0 \uc5b4\ub5a4 \ub178\ub3d9\uc5d0 \ub300\uac00\ub97c \uc9c0\uae09\ud560 \uc218 \uc788\ub294\uc9c0 \uc0dd\uac01\ud55c \uac83\uc774\ub2e4. \ub2e4\ub9cc \uc774\ub7f0 \uc8fc\uc7a5\uc744 \ubaa8\ub4e0 \uc0ac\uc5c5\uc774 \uc131\uacf5\ud55c\ub2e4\ub294 \uacbd\uc81c \ubc95\uce59\uc73c\ub85c \ubc1b\uc544\ub4e4\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uc120\uc5b8\ubb38\uc740 \ud558\ub098\uc758 \ubc29\ud5a5\uc744 \uc124\ub4dd\ud558\ub294 \uae00\uc774\ub2e4. \ud604\uc2e4\uc758 \uc870\uc9c1\uc740 \uac1c\ubc1c\uacfc \uc9c0\uc6d0\uc758 \ube44\uc6a9\uc744 \uac10\ub2f9\ud560 \ubc29\ubc95\uc744 \ucc3e\uc544\uc57c \ud55c\ub2e4. \uacf5\uc720\uc758 \uac00\uce58\uc640 \uc9c0\uc18d \uac00\ub2a5\ud55c \ub178\ub3d9\uc744 \uc5f0\uacb0\ud558\ub294 \uacfc\uc81c\ub294 \ub0a8\ub294\ub2e4. GNU \uc120\uc5b8\ubb38\uc744 \uc77d\uc73c\uba74 \uae30\uc220\uc740 \ucf54\ub4dc \uc548\uc5d0\ub9cc \uc788\uc9c0 \uc54a\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \ud611\ub825\ud560 \uc218 \uc788\ub294 \ubc94\uc704\uc640 \ub2e4\uc74c \uc0ac\ub78c\uc5d0\uac8c \ubb34\uc5c7\uc744 \ub118\uae38 \uc218 \uc788\ub294\uc9c0\uac00 \uac1c\ubc1c\uc758 \uc870\uac74\uc744 \ubc14\uafbc\ub2e4. \ubc30\ud3ec \uaddc\uce59\uc740 \uc644\uc131 \ub4a4 \ubd99\uc774\ub294 \uc791\uc740 \uc548\ub0b4\ubb38 \uc774\uc0c1\uc758 \uc758\ubbf8\ub97c \uac00\uc84c\ub2e4. \uc624\ub298 \ud504\ub85c\uadf8\ub7a8\uc744 \uace0\ub974\uace0 \ucf54\ub4dc\ub97c \uacf5\uc720\ud560 \ub54c\ub3c4 \uc774 \uc9c8\ubb38\uc740 \uc774\uc5b4\uc9c4\ub2e4. \ubb34\uc5c7\uc744 \ud560 \uc218 \uc788\ub294 \uc81c\ud488\uc778\uac00\uc640 \uc5b4\ub5a4 \uad00\uacc4\ub85c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294\uac00\ub97c \ud568\uaed8 \ubcfc \uc218 \uc788\ub2e4. GNU\uc758 \uc5ed\uc0ac\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc18c\ud504\ud2b8\uc6e8\uc5b4\uc758 \uae30\ub2a5\ubfd0 \uc544\ub2c8\ub77c \ub098\ub204\ub294 \uc870\uac74\uae4c\uc9c0 \uc124\uacc4\ud558\ub824 \ud588\ub358 \uc2dc\ub3c4\ub97c \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "http-404-410", "title": "404\uc640 410\uc740 \uac19\uc740 \ube48 \ud398\uc774\uc9c0\uac00 \uc544\ub2c8\ub2e4", "summary": "\ucc3e\uc744 \uc218 \uc5c6\ub2e4\ub294 \uc751\ub2f5\uacfc \uc0ac\ub77c\uc84c\ub2e4\ub294 \uc751\ub2f5\uc758 \ucc28\uc774\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\uc778\ud130\ub137\uacfc \ud1b5\uc2e0", "categories": ["digital"], "url": "stories/http-404-410/index.html", "image": "../media/http-404-410.jpg", "alt": "404\uc640 410\uc740 \uac19\uc740 \ube48 \ud398\uc774\uc9c0\uac00 \uc544\ub2c8\ub2e4\uc758 \ub0b4\uc6a9\uc744 \ub3d5\ub294 \uc124\uba85\uc6a9 \uc774\ubbf8\uc9c0", "text": "404\uc640 410\uc740 \uac19\uc740 \ube48 \ud398\uc774\uc9c0\uac00 \uc544\ub2c8\ub2e4 \uc6f9\uc0ac\uc774\ud2b8\uac00 \uc5c6\uc5b4\uc9c4 \uc790\ub9ac\uc5d0 \ub0a8\uae30\ub294 \ub450 \uac00\uc9c0 \ub9d0 \ucc3e\uc744 \uc218 \uc5c6\ub2e4\ub294 \uc751\ub2f5\uacfc \uc0ac\ub77c\uc84c\ub2e4\ub294 \uc751\ub2f5\uc758 \ucc28\uc774\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uc778\ud130\ub137\uacfc \ud1b5\uc2e0 \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \uc624\ub798 \uc800\uc7a5\ud574 \ub454 \ub9c1\ud06c\ub97c \ub20c\ub800\ub294\ub370 \ud398\uc774\uc9c0 \ub300\uc2e0 404\ub77c\ub294 \uc22b\uc790\uac00 \ub098\uc628\ub2e4. \ubb38\uc774 \ub2eb\ud78c \uacf3\uc744 \ucc3e\uc544\uac04 \uae30\ubd84\uc774\ub2e4. \uadf8\ub7f0\ub370 \uc6f9\uc5d0\ub294 410\uc774\ub77c\ub294 \uc751\ub2f5\ub3c4 \uc788\ub2e4. \ub458 \ub2e4 \uc6d0\ud558\ub294 \ub0b4\uc6a9\uc744 \ubcfc \uc218 \uc5c6\uc9c0\ub9cc \ub73b\uc774 \uc644\uc804\ud788 \uac19\uc9c0\ub294 \uc54a\ub2e4. \uc6f9\uc758 \ud1b5\uc2e0 \uaddc\uce59\uc744 \uc815\ub9ac\ud55c RFC 9110\uc740 \uc774 \ub450 \uc751\ub2f5\uc744 \uad6c\ubd84\ud55c\ub2e4. \uc22b\uc790\ub97c \uc678\uc6b0\uae30\ubcf4\ub2e4 \ube48\uc790\ub9ac\uc5d0 \ub0a8\uae30\ub294 \ub9d0\uc774 \ub2e4\ub974\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. 404\ub294 \uc694\uccad\ud55c \ub300\uc0c1\uc758 \ud604\uc7ac \ub0b4\uc6a9\uc744 \ucc3e\uc9c0 \ubabb\ud588\ub2e4\ub294 \uc751\ub2f5\uc774\ub2e4. \uc11c\ubc84\uac00 \uadf8 \ub300\uc0c1\uc774 \uc874\uc7ac\ud55c\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uacf5\uac1c\ud558\uc9c0 \uc54a\uc73c\ub824 \ud560 \ub54c\ub3c4 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c 404 \ud558\ub098\ub9cc \ubcf4\uace0 \uc0ac\ub77c\uc9c4 \uc0ac\uc815\uc744 \ubaa8\ub450 \uc54c\uc544\ub0bc \uc218\ub294 \uc5c6\ub2e4. \ud2b9\ud788 \uc774 \uc751\ub2f5 \uc790\uccb4\ub294 \uc0c1\ud0dc\uac00 \uc77c\uc2dc\uc801\uc778\uc9c0 \uc601\uad6c\uc801\uc778\uc9c0 \ub9d0\ud574 \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \uc8fc\uc18c\ub97c \uc798\ubabb \uc801\uc5c8\uc744 \uc218\ub3c4 \uc788\uaca0\uc9c0\ub9cc, \uc5b8\uc81c\ub098 \uadf8\uac83\ub9cc\uc774 \uc774\uc720\ub77c\uace0 \uc815\ud560 \uc218\ub294 \uc5c6\ub294 \uac83\uc774\ub2e4. 410\uc740 \uadf8 \ub300\uc0c1\uc5d0 \ub354\ub294 \uc811\uadfc\ud560 \uc218 \uc5c6\uace0 \uadf8 \uc0c1\ud0dc\uac00 \uc624\ub798 \uc774\uc5b4\uc9c8 \uac83\uc73c\ub85c \ubcf4\uc778\ub2e4\ub294 \uc751\ub2f5\uc774\ub2e4. \uc6b4\uc601\uc790\uac00 \uadf8 \ucc28\uc774\ub97c \uc54c\uace0 \uc54c\ub9ac\ub824 \ud560 \ub54c \uc4f8 \uc218 \uc788\ub2e4. \uaddc\uce59\uc740 \uae30\uac04\uc774 \ub05d\ub09c \ud64d\ubcf4 \uc11c\ube44\uc2a4 \uac19\uc740 \uc608\ub3c4 \uc18c\uac1c\ud55c\ub2e4. \uac00\uac8c \uc55e\uc5d0 \ubb38\uc744 \ucc3e\uc744 \uc218 \uc5c6\ub2e4\ub294 \uc548\ub0b4\uac00 \uc788\ub294 \uac83\uacfc, \uc774\uacf3\uc740 \uc601\uc5c5\uc744 \ub9c8\ucce4\ub2e4\ub294 \uc548\ub0b4\uac00 \uc788\ub294 \uc0c1\ud669\uc744 \ub098\ub780\ud788 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc815\ud655\ud788 \uac19\uc740 \uc0ac\uc815\uc740 \uc544\ub2c8\uc9c0\ub9cc \ub450 \uc751\ub2f5\uc758 \ub2e4\ub978 \ud0dc\ub3c4\ub97c \uc774\ud574\ud558\ub294 \ube44\uc720\uac00 \ub41c\ub2e4. \uc6f9\uc758 \ub9c1\ud06c\ub294 \uc5b4\ub5a4 \uc8fc\uc18c\ub85c \uc694\uccad\uc744 \ubcf4\ub0b4\uac8c \ud55c\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uc8fc\uc18c\uc758 \ub0b4\uc6a9\uc774 \uc5b8\uc81c\ub098 \uadf8\ub300\ub85c \ub0a8\uc544 \uc788\uc73c\ub9ac\ub77c\ub294 \ubcf4\uc99d\uae4c\uc9c0 \ub2f4\uace0 \uc788\uc9c0\ub294 \uc54a\ub2e4. \ud398\uc774\uc9c0\uac00 \ubc14\ub00c\uac70\ub098 \uc6b4\uc601 \ubc29\uc2dd\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc624\ub798\ub41c \ub9c1\ud06c\ub97c \ub20c\ub800\uc744 \ub54c \uc751\ub2f5\uc744 \uc77d\ub294 \uc77c\uc740 \uc8fc\uc18c\ub77c\ub294 \uc57d\uc18d\uacfc \ud604\uc7ac \uc81c\uacf5\ud558\ub294 \uc0c1\ud0dc\ub97c \ub098\ub204\uc5b4 \ubcf4\ub294 \uacfc\uc815\uc774\ub2e4. \uc774\ub54c 404 \ud654\uba74\uc744 \ubc1b\uc558\ub2e4\ub294 \uac83\uacfc \ud1b5\uc2e0 \uc790\uccb4\uac00 \uc804\ud600 \ub418\uc9c0 \uc54a\uc558\ub2e4\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uc751\ub2f5\uc740 \uc694\uccad\uc5d0 \ub300\ud574 \uc5b4\ub5a4 \uc2dc\uc2a4\ud15c\uc774 \uc0c1\ud0dc\ub97c \uc54c\ub824 \uc900 \uac83\uc774\ub2e4. \ub2e4\ub9cc \uadf8 \uc22b\uc790\ub9cc\uc73c\ub85c \uc5b4\ub290 \uc9c0\uc810\uc758 \uc124\uc815\uc774 \uc798\ubabb\ub418\uc5c8\ub294\uc9c0\ub098 \uc6d0\ub798 \uc791\uc131\uc790\uc758 \uc758\ub3c4\uae4c\uc9c0 \uc54c\uc544\ub0bc \uc218\ub294 \uc5c6\ub2e4. \ubcf4\uc5ec \uc8fc\ub294 \uba54\uc2dc\uc9c0\uc758 \ubc94\uc704\ub97c \uba3c\uc800 \uad6c\ubd84\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4. 404\uac00 \uc601\uad6c\uc131\uacfc \uc77c\uc2dc\uc131\uc744 \ud655\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc740 \ub2f5\uc774 \ubd88\uce5c\uc808\ud558\ub2e4\ub294 \ub73b\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uc11c\ubc84\uac00 \ud655\uc778\ud558\uac70\ub098 \uacf5\uac1c\ud560 \uc218 \uc788\ub294 \uc815\ubcf4\uc758 \ubc94\uc704\uac00 \uac70\uae30\uae4c\uc9c0\uc77c \uc218 \uc788\ub2e4. \uc6b4\uc601\uc790\ub294 \uc0ac\ub77c\uc9c4 \uc774\uc720\ub97c \uc815\ud655\ud788 \ubaa8\ub97c \uc218\ub3c4 \uc788\uace0, \uc874\uc7ac \uc5ec\ubd80\ub97c \ub4dc\ub7ec\ub0b4\uc9c0 \uc54a\uc73c\ub824 \ud560 \uc218\ub3c4 \uc788\ub2e4. \uac19\uc740 \uc0c1\ud0dc \ucf54\ub4dc \ub4a4\uc5d0 \uc5ec\ub7ec \uc0ac\uc815\uc774 \ub193\uc77c \uc218 \uc788\ub2e4. \uc0ac\ub78c \uc0ac\uc774\uc5d0\uc11c\ub3c4 \ucc3e\uc744 \uc218 \uc5c6\ub2e4\ub294 \ub9d0\uacfc \uc5c6\uc574\ub2e4\ub294 \ub9d0\uc740 \ub2e4\ub974\ub2e4. \uc804\uc790\ub294 \ud604\uc7ac\uc758 \ud655\uc778 \uacb0\uacfc\ub97c, \ud6c4\uc790\ub294 \uc774\ub825\uc5d0 \uad00\ud55c \ub354 \ub9ce\uc740 \ud310\ub2e8\uc744 \ud3ec\ud568\ud55c\ub2e4. \ub450 \uc751\ub2f5\uc744 \uc774\ub7f0 \ub9d0\uc758 \ucc28\uc774\ub85c \uc77d\uc73c\uba74 \uc22b\uc790\uac00 \ub2e8\uc21c\ud55c \uc2e4\ud328 \ud45c\uc2dc\ub9cc\uc740 \uc544\ub2c8\uac8c \ub41c\ub2e4. \uc6f9\uc740 \uc131\uacf5\ud55c \ub0b4\uc6a9\ubfd0 \uc544\ub2c8\ub77c \ubb34\uc5c7\uc744 \uc5b4\ub290 \uc815\ub3c4\ub85c \uc54c\ub9ac\ub294\uc9c0\ub3c4 \uacf5\ud1b5 \ud615\uc2dd\uc73c\ub85c \ub2e4\ub8ec\ub2e4. \uc5b4\ub5a4 \uc11c\ube44\uc2a4\uc758 \uc81c\uacf5 \uae30\uac04\uc774 \ub05d\ub0ac\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc6b4\uc601\uc790\uac00 \uc54c\uace0 \uc788\ub2e4\uba74 \ub354\ub294 \uc81c\uacf5\ud558\uc9c0 \uc54a\ub294 \uc0c1\ud0dc\ub97c \uc54c\ub9b4 \uc218 \uc788\ub2e4. 410\uc740 \uadf8\ub7f0 \uc120\ud0dd\uc744 \ud45c\ud604\ud558\ub294 \uc751\ub2f5\uc774\ub2e4. \ub2e8\uc21c\ud788 \ub0b4\uc6a9\uc774 \ube44\uc5b4 \uc788\ub2e4\ub294 \uac83\ubcf4\ub2e4 \uadf8 \ubd80\uc7ac\ub97c \uc5b4\ub5bb\uac8c \uc774\ud574\ud558\uba74 \ub418\ub294\uc9c0 \uc815\ubcf4\ub97c \ub354\ud558\ub294 \uc148\uc774\ub2e4. \uc624\ub798\ub41c \ub9c1\ud06c\ub97c \uad00\ub9ac\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub3c4 \uad6c\ubcc4\uc758 \uc774\uc720\uac00 \uc0dd\uae34\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubc29\ubb38\uc790\uac00 \uc774 \uc22b\uc790\ub97c \ubcf4\ub294 \uc989\uc2dc \ubaa8\ub4e0 \ub9c1\ud06c\ub97c \uc9c0\uc6cc\uc57c \ud55c\ub2e4\uac70\ub098 \uae30\ub85d\uc744 \ubc84\ub824\uc57c \ud55c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc6d0\ub798\uc758 \ub0b4\uc6a9\uc774 \ub2e4\ub978 \uc8fc\uc18c\ub098 \ubcf4\uc874 \uc790\ub8cc\uc5d0 \ub0a8\uc544 \uc788\uc744 \uac00\ub2a5\uc131\uc740 \ubcc4\ub3c4 \ubb38\uc81c\ub2e4. \uc0c1\ud0dc \uc751\ub2f5\uc740 \uc9c0\uae08 \uc694\uccad\ud55c \ub300\uc0c1\uc758 \uc811\uadfc\uc5d0 \uad00\ud574 \ub9d0\ud55c\ub2e4. \uc790\ub8cc\uc758 \uc5ed\uc0ac \uc804\uccb4\uc640 \ubcf4\uc874 \uac00\uce58\ub97c \ub300\uc2e0 \ud310\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud654\uba74\uc5d0\ub294 \uc7ac\ubbf8\uc788\ub294 \uadf8\ub9bc\uacfc \ubb38\uad6c\uac00 \ub098\uc62c \uc218 \uc788\uc9c0\ub9cc, \uadf8 \ub514\uc790\uc778\uc774 \uc22b\uc790\uc758 \ub73b\uc744 \uc0c8\ub85c \uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubc18\ub300\ub85c \uac19\uc740 404\ub77c\ub3c4 \uc0ac\uc774\ud2b8\ub9c8\ub2e4 \ubc29\ubb38\uc790\uc5d0\uac8c \ubcf4\uc5ec \uc8fc\ub294 \ud654\uba74\uc740 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc0c1\ud0dc\ub97c \uc804\ud558\ub294 \uaddc\uce59\uacfc \uadf8\uac83\uc744 \ub208\uc5d0 \ubcf4\uc774\uac8c \ud45c\ud604\ud55c \ud398\uc774\uc9c0\ub294 \uc5f0\uacb0\ub418\uc9c0\ub9cc \uad6c\ubd84\ud560 \uc218 \uc788\ub294 \ubd80\ubd84\uc774\ub2e4. \uadf8\ub798\uc11c \uc7ac\uce58 \uc788\ub294 \uc624\ub958 \ud654\uba74\uc744 \ubcf4\ub354\ub77c\ub3c4 \uba3c\uc800 \ubb34\uc5c7\uc774 \ud655\uc778\ub418\uc9c0 \uc54a\uc558\ub294\uc9c0 \uc54c\uba74 \ub41c\ub2e4. \ub3cc\uc544\uac08 \uccab \ud654\uba74\uc774\ub098 \uac80\uc0c9\uc73c\ub85c \ub2e4\ub978 \uae38\uc744 \ucc3e\ub294 \uc77c\uc740 \uadf8\ub2e4\uc74c\uc758 \uc774\uc6a9 \uacbd\ud5d8\uc774\ub2e4. \uc2e4\ud328\ud55c \uc694\uccad\uc744 \uc5b4\ub5bb\uac8c \uc548\ub0b4\ud560\uc9c0\ub3c4 \uc6f9\uc0ac\uc774\ud2b8\uc758 \ud3b8\uc9d1\uacfc \uc124\uacc4\uc5d0 \ub4e4\uc5b4\uac04\ub2e4. \ube48 \ud654\uba74\ucc98\ub7fc \ubcf4\uc774\ub358 \uc790\ub9ac\uc5d0\ub3c4 \uc815\ubcf4\uc758 \uc815\ub3c4\uc640 \ubc29\ubb38\uc790\ub97c \ub300\ud558\ub294 \ud0dc\ub3c4\uac00 \ud568\uaed8 \ub0a8\uc544 \uc788\ub2e4. \ubaa8\ub4e0 \uc6f9\uc0ac\uc774\ud2b8\uac00 \uc5c6\uc5b4\uc9c4 \ud398\uc774\uc9c0\uc5d0 \ubc18\ub4dc\uc2dc 410\uc744 \ubd99\uc774\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uaddc\uce59\ub3c4 \ubaa8\ub4e0 \uc601\uad6c\uc801\uc778 \uc0ad\uc81c\ub97c \uc774 \uc751\ub2f5\uc73c\ub85c \ud45c\uc2dc\ud574\uc57c \ud55c\ub2e4\uace0 \uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud604\uc2e4\uc758 \uc0ac\uc774\ud2b8\ub4e4\uc740 \uc5ec\ub7ec \uc774\uc720\ub85c \ub2e4\ub978 \uc120\ud0dd\uc744 \ud55c\ub2e4. \uadf8\ub798\uc11c 404\ub098 410\uc774 \ub208\uc5d0 \ub4e4\uc5b4\uc624\uba74 \ubaa8\ub4e0 \uc0ac\uc815\uc744 \ucd94\uce21\ud558\uae30\ubcf4\ub2e4 \uc751\ub2f5\uc774 \ub9d0\ud574 \uc8fc\ub294 \ubc94\uc704\ub9cc \uc77d\uc73c\uba74 \ub41c\ub2e4. \ub0b4\uc6a9\uc774 \uc5c6\ub294 \ud654\uba74\uc5d0\ub3c4, \uc544\uc9c1 \ubaa8\ub978\ub2e4\ub294 \ub9d0\uacfc \ub5a0\ub0ac\uc74c\uc744 \uc54c\ub9ac\ub294 \ub9d0\uc758 \ucc28\uc774\ub294 \ub0a8\uc544 \uc788\ub2e4."}, {"id": "https-small-s-and-connection", "title": "HTTPS \u2014 \uc6f9 \uc8fc\uc18c\uc758 \uc791\uc740 s\uac00 \ud558\ub294 \uc77c", "summary": "\uc554\ud638\ud654\u00b7\ubcc0\uc870 \ud0d0\uc9c0\u00b7\uc11c\ubc84 \ud655\uc778\uc744 \ub098\ub204\uc5b4 \ubcf4\uace0 HTTPS\uac00 \ubcf4\ud638\ud558\ub294 \ubc94\uc704\ub97c \uc774\ud574\ud569\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\ub514\uc9c0\ud138 \uc0dd\ud65c\uacfc \ubcf4\uc548", "categories": ["digital"], "url": "stories/https-small-s-and-connection/index.html", "image": "../media/https-small-s-and-connection.png", "alt": "\uacf5\uc720 \ub3c5\uc11c \uacf5\uac04\uc5d0\uc11c \ubd09\ud22c\ub97c \ub4e4\uace0 \ub9d0\uacfc \uc815\ubcf4\ub97c \ub098\ub204\ub294 \ub450 \uc0ac\ub78c\uc758 AI \ube44\uc720 \uc7a5\uba74.", "text": "HTTPS \u2014 \uc6f9 \uc8fc\uc18c\uc758 \uc791\uc740 s\uac00 \ud558\ub294 \uc77c \uc5f0\uacb0\uc744 \ubcf4\ud638\ud55c\ub2e4\ub294 \ub9d0\uacfc \ub0b4\uc6a9\uc744 \ubbff\ub294\ub2e4\ub294 \ub9d0 \uc0ac\uc774 \uc554\ud638\ud654\u00b7\ubcc0\uc870 \ud0d0\uc9c0\u00b7\uc11c\ubc84 \ud655\uc778\uc744 \ub098\ub204\uc5b4 \ubcf4\uace0 HTTPS\uac00 \ubcf4\ud638\ud558\ub294 \ubc94\uc704\ub97c \uc774\ud574\ud569\ub2c8\ub2e4. \ub514\uc9c0\ud138 \uc0dd\ud65c\uacfc \ubcf4\uc548 \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \uc6f9 \uc8fc\uc18c\ub97c \uc790\uc138\ud788 \ubcf4\uba74 http \ub4a4\uc5d0 \uc791\uc740 s\uac00 \ubd99\uc5b4 \uc788\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4. \ud654\uba74\uc758 \uae00\uacfc \uc0ac\uc9c4\uc740 \ube44\uc2b7\ud558\uac8c \ubcf4\uc774\ub294\ub370 \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc9c0\ub294 \uac78\uae4c. \uc774 \ucc28\uc774\ub294 \uc0ac\uc774\ud2b8\uc758 \ub514\uc790\uc778\ubcf4\ub2e4 \ube0c\ub77c\uc6b0\uc800\uc640 \uc11c\ubc84 \uc0ac\uc774\uc5d0\uc11c \uc815\ubcf4\uac00 \uc624\uac00\ub294 \ubc29\uc2dd\uc5d0 \uc788\ub2e4. HTTPS\ub294 HTTP \ud1b5\uc2e0\uc744 TLS\ub77c\ub294 \ubcf4\uc548 \ud504\ub85c\ud1a0\ucf5c\ub85c \ubcf4\ud638\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc774\ub984\uc774 \uc870\uae08 \uae38\uc9c0\ub9cc \uc138 \uac00\uc9c0 \uc9c8\ubb38\uc73c\ub85c \ub098\ub204\uba74 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \uc911\uac04\uc5d0\uc11c \ub0b4\uc6a9\uc744 \uc77d\uae30 \uc5b4\ub835\uac8c \ud558\ub294\uac00, \ubab0\ub798 \ubc14\uafb8\uba74 \uc54c\uc544\ucc4c \uc218 \uc788\ub294\uac00, \uc5f0\uacb0\ud55c \uc11c\ubc84\uac00 \ud574\ub2f9 \uc774\ub984\uc758 \uc11c\ubc84\uc778\uc9c0 \ud655\uc778\ud558\ub294\uac00. \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \ud398\uc774\uc9c0\ub97c \uc5f4\uba74 \uc694\uccad\uacfc \uc751\ub2f5\uc774 \ub124\ud2b8\uc6cc\ud06c\ub97c \uac70\uce5c\ub2e4. \uc911\uac04\uc758 \uc5f0\uacb0\uc744 \ubaa8\ub450 \ubbff\uc744 \uc218 \uc788\ub294 \uc0c1\ud669\ub9cc \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubbfc\uac10\ud55c \uc815\ubcf4\ubfd0 \uc544\ub2c8\ub77c \uc77c\ubc18\uc801\uc778 \ud398\uc774\uc9c0\ub3c4 \uc774\ub3d9 \uc911\uc758 \ubcf4\ud638\uac00 \ud544\uc694\ud560 \uc218 \uc788\ub2e4. HTTPS\ub294 \uc774 \ud1b5\uc2e0 \uad6c\uac04\uc5d0\uc11c \uc8fc\uace0\ubc1b\ub294 \ub370\uc774\ud130\ub97c \uc554\ud638\ud654\ud55c\ub2e4. \uc804\ub2ec \uc911\uc778 \ub0b4\uc6a9\uc744 \ud5c8\ub77d \uc5c6\uc774 \uc77d\uae30 \uc5b4\ub835\uac8c \ub9cc\ub4dc\ub294 \uac83\uc774\ub2e4. \ud3b8\uc9c0\ub97c \ubd09\ud22c\uc5d0 \ub123\ub294 \ube44\uc720\uac00 \uccab \uc774\ud574\uc5d0\ub294 \ub3c4\uc6c0\uc774 \ub418\uc9c0\ub9cc \uc2e4\uc81c \uae30\uc220\uc740 \uc885\uc774 \ubd09\ud22c\uc758 \ubb3c\ub9ac\uc801 \ubcf4\ud638\uc640 \uac19\uc9c0 \uc54a\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubb34\uc5c7\uc744 \ubcf4\ud638\ud558\ub824\ub294\uc9c0\uc5d0 \ucd08\uc810\uc744 \ub9de\ucd94\uba74 \ub41c\ub2e4. \uc815\ubcf4\ub97c \uc228\uae30\ub294 \uae30\ub2a5\ub9cc\uc73c\ub85c\ub294 \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4. \uc911\uac04\uc5d0\uc11c \uc751\ub2f5 \ub0b4\uc6a9\uc744 \ubab0\ub798 \ubc14\uafb8\uc5c8\uc744 \ub54c\ub3c4 \uc774\ub97c \uc54c\uc544\ucc4c \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4. MDN\uc740 \uc774\ub97c \ubb34\uacb0\uc131\uc758 \ubb38\uc81c\ub85c \uc124\uba85\ud55c\ub2e4. \uc804\ub2ec\ud558\ub294 \ub370\uc774\ud130\uac00 \ub208\uc5d0 \ub744\uc9c0 \uc54a\uac8c \ubcc0\uc870\ub418\ub294 \uc77c\uc744 \ub9c9\uae30 \uc704\ud55c \uc131\uc9c8\uc774\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \ubc1b\uc740 \ubb38\uc7a5\uc5d0 \ub2e4\ub978 \ub2e8\uc5b4\uac00 \ub07c\uc5b4\ub4e4\uc5c8\ub2e4\uba74 \uc6d0\ub798 \uc11c\ubc84\uc758 \ub9d0\uc778\uc9c0 \uc54c\uae30 \uc5b4\ub835\ub2e4. \uc815\ubcf4\uc758 \ub0b4\uc6a9\uc774 \uc798 \ubcf4\uc774\uc9c0 \uc54a\uac8c \ud558\ub294 \uc77c\uacfc \uc815\ubcf4\uac00 \ubc14\ub00c\uc5c8\ub294\uc9c0 \ud655\uc778\ud558\ub294 \uc77c\uc740 \ub2e4\ub978 \uc5ed\ud560\uc774\ub2e4. TLS\ub294 \uc774\ub7f0 \uc5ec\ub7ec \ubcf4\ud638\ub97c \ud568\uaed8 \uc81c\uacf5\ud558\ub3c4\ub85d \uc124\uacc4\ub418\uc5b4 \uc788\ub2e4. \uc544\ubb34 \uc0c1\ub300\uc640 \uc548\uc804\ud558\uac8c \uc774\uc57c\uae30\ud55c\ub2e4\uace0 \ucda9\ubd84\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ub0b4\uac00 \uc811\uc18d\ud558\ub824\ub358 \uc774\ub984\uc758 \uc11c\ubc84\uc778\uc9c0 \ud655\uc778\ud558\ub294 \ub2e8\uacc4\ub3c4 \ud544\uc694\ud558\ub2e4. \uc6f9\uc5d0\uc11c\ub294 \ubcf4\ud1b5 \uc11c\ubc84\uac00 \ube0c\ub77c\uc6b0\uc800\uc5d0 \uc790\uc2e0\uc744 \uc778\uc99d\ud55c\ub2e4. \ubc29\ubb38\uc790 \uac1c\uc778\uc774 TLS \uc778\uc99d\uc11c\ub85c \ub9e4\ubc88 \uc790\uc2e0\uc744 \uc99d\uba85\ud558\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc778 \ubc29\uc2dd\uc740 \uc544\ub2c8\ub2e4. \uc774\ub54c \ub514\uc9c0\ud138 \uc778\uc99d\uc11c\ub294 \uc0ac\uc774\ud2b8\uc758 \ub3c4\uba54\uc778 \uc774\ub984\uacfc \uc554\ud638 \ud1b5\uc2e0\uc5d0 \uc4f0\ub294 \ud0a4\ub97c \uc5f0\uacb0\ud55c\ub2e4. \ube0c\ub77c\uc6b0\uc800\ub294 \uc774\ub97c \uac80\uc0ac\ud574 \uc5f0\uacb0\uc758 \uc0c1\ub300\ub97c \ud655\uc778\ud55c\ub2e4. \uc0ac\uc774\ud2b8\uc758 \uc774\ub984\uc744 \ud655\uc778\ud558\ub294 \uc77c\uacfc \uadf8\uacf3\uc5d0 \uc4f0\uc778 \ubaa8\ub4e0 \uae00\uc774 \uc0ac\uc2e4\uc778\uc9c0 \ud3c9\uac00\ud558\ub294 \uc77c\uc740 \uc5ec\uc804\ud788 \ub2e4\ub974\ub2e4. TLS \ud1b5\uc2e0\uc740 \ucc98\uc74c\ubd80\ud130 \uc544\ubb34 \uc900\ube44 \uc5c6\uc774 \uc774\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uc5f0\uacb0 \ucd08\uae30\uc5d0 \uc0ac\uc6a9\ud560 \ubc29\uc2dd\uacfc \ud544\uc694\ud55c \ubcf4\uc548 \uc870\uac74\uc744 \uc815\ud558\ub294 \uacfc\uc815\uc774 \uc788\ub2e4. \uc774\ub97c \ud578\ub4dc\uc170\uc774\ud06c\ub77c\uace0 \ud55c\ub2e4. \uc545\uc218\ub97c \ud55c\ub2e4\ub294 \uc774\ub984\uc774\uc9c0\ub9cc \uc0ac\ub78c\ub07c\ub9ac \uc778\uc0ac\ud558\ub294 \ubaa8\uc2b5\uacfc \uc815\ud655\ud788 \uac19\uc740 \uc808\ucc28\ub294 \uc544\ub2c8\ub2e4. \uc774 \uacfc\uc815\uc744 \uac70\uccd0 \ud1b5\uc2e0\uc5d0 \uc0ac\uc6a9\ud560 \uc870\uac74\uacfc \ud0a4\ub97c \ub9c8\ub828\ud55c\ub2e4. \ub3c5\uc790\uac00 \uc554\ud638 \uc54c\uace0\ub9ac\uc998\uc758 \uc774\ub984\uc744 \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uacf5\ud1b5\uc758 \ubcf4\ud638 \ubc29\uc2dd\uc5d0 \ud569\uc758\ud558\uace0 \uc2e4\uc81c \ub370\uc774\ud130\ub97c \uc8fc\uace0\ubc1b\uae30 \uc704\ud55c \uc900\ube44\uac00 \uc788\ub2e4\ub294 \uc815\ub3c4\uba74 \uc791\uc740 s\uac00 \ub73b\ud558\ub294 \ubcc0\ud654\uac00 \uc880 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \ub290\uaef4\uc9c4\ub2e4. HTTPS\ub294 \ube0c\ub77c\uc6b0\uc800\uc640 \uc11c\ubc84 \uc0ac\uc774\ub85c \uc774\ub3d9\ud558\ub294 \uc815\ubcf4\ub97c \ubcf4\ud638\ud55c\ub2e4. \ub530\ub77c\uc11c \uc11c\ubc84\uc5d0 \ub3c4\ucc29\ud55c \ub4a4 \uadf8 \ud68c\uc0ac\uac00 \uc815\ubcf4\ub97c \uc5b4\ub5bb\uac8c \ubcf4\uad00\ud558\uace0 \uc0ac\uc6a9\ud558\ub294\uc9c0\uae4c\uc9c0 \uac19\uc740 \uae30\uc220\uc774 \uc790\ub3d9\uc73c\ub85c \ubcf4\uc99d\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub0b4 \uae30\uae30\uc5d0\uc11c \uc774\ubbf8 \ub204\uad70\uac00\uac00 \ud654\uba74\uc744 \ubcfc \uc218 \uc788\ub294 \ubb38\uc81c\ub3c4 \ubcc4\ub3c4\ub85c \uc788\ub2e4. \uc774\uac83\uc740 HTTPS\uac00 \ubd80\uc871\ud558\ub2c8 \uc758\ubbf8 \uc5c6\ub2e4\ub294 \ub9d0\uc774 \uc544\ub2c8\ub2e4. \uc6b0\ud3b8\uc774 \uc6b4\uc1a1 \uc911\uc5d0 \uc548\uc804\ud55c \uac83\uacfc \ubc1b\uc740 \uc0ac\ub78c\uc774 \ud3b8\uc9c0\ub97c \uc5b4\ub5bb\uac8c \ubcf4\uad00\ud558\ub294\uc9c0\uac00 \ub2e4\ub978 \uc9c8\ubb38\uc778 \uac83\ucc98\ub7fc, \uc5ed\ud560\uc758 \ubc94\uc704\uac00 \ub2e4\ub978 \uac83\uc774\ub2e4. \ubcf4\ud638\ud558\ub294 \uad6c\uac04\uc744 \uc54c\uba74 \ud55c \uae30\uc220\uc5d0 \ubaa8\ub4e0 \ucc45\uc784\uc744 \uae30\ub300\ud558\uc9c0 \uc54a\uace0 \uadf8 \uac00\uce58\ub97c \uc815\ud655\ud788 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uac00\uc9dc \uc124\uba85\uc744 \uc4f0\uac70\ub098 \uc798\ubabb\ub41c \ubb3c\uac74\uc744 \ud30c\ub294 \uc0ac\uc774\ud2b8\ub3c4 \uc554\ud638\ud654\ub41c \uc5f0\uacb0\uc744 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4. \ud574\ub2f9 \ub3c4\uba54\uc778\uacfc \ud1b5\uc2e0 \uc911\uc774\ub77c\ub294 \ud655\uc778\uc740 \uc6b4\uc601\uc790\uc758 \ubaa8\ub4e0 \ud589\ub3d9\uc744 \uc2e0\ub8b0\ud558\ub77c\ub294 \ucd94\ucc9c\uc774 \uc544\ub2c8\ub2e4. \uc548\uc804\ud55c \uc5f0\uacb0\uacfc \ubbff\uc744 \ub9cc\ud55c \uc0c1\ub300\ub294 \ub098\ub204\uc5b4 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc8fc\uc18c\uc758 \uc791\uc740 s\ub97c \uc911\uc694\ud55c \uae30\ubcf8 \uc870\uac74\uc73c\ub85c \ubcf4\uba74\uc11c\ub3c4 \uae00\uc758 \ucd9c\ucc98\uc640 \uc11c\ube44\uc2a4\uc758 \uc6b4\uc601 \uc815\ubcf4\ub294 \ubcc4\ub3c4\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. HTTPS\uc758 \ub73b\uc744 \uc774\ud574\ud558\ub294 \uc77c\uc740 \ubd88\uc548\uc744 \ud0a4\uc6b0\ub294 \uae30\uc220 \uacf5\ubd80\ubcf4\ub2e4, \uc11c\ub85c \ub2e4\ub978 \ud655\uc778\uc774 \ubb34\uc5c7\uc744 \uc54c\ub824 \uc8fc\ub294\uc9c0 \uad6c\ubcc4\ud558\ub294 \ub370 \uac00\uae5d\ub2e4. \ud55c \ud398\uc774\uc9c0\uc5d0\ub294 \ubcf8\ubb38\ubfd0 \uc544\ub2c8\ub77c \uc774\ubbf8\uc9c0\uc640 \ud504\ub85c\uadf8\ub7a8 \ud30c\uc77c \ub4f1 \uc5ec\ub7ec \uc790\ub8cc\uac00 \ud3ec\ud568\ub41c\ub2e4. \ubcf8\ubb38\uc740 HTTPS\ub85c \ubc1b\uc544\ub3c4 \ub2e4\ub978 \uc790\ub8cc\ub97c \ubcf4\ud638\ub418\uc9c0 \uc54a\uc740 \uc5f0\uacb0\ub85c \uac00\uc838\uc624\uba74 \ud398\uc774\uc9c0 \uc804\uccb4\uc758 \ubcf4\ud638\uc5d0 \ubb38\uc81c\uac00 \uc0dd\uae38 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \ube0c\ub77c\uc6b0\uc800\ub294 \uc774\ub7f0 \ud63c\ud569 \ucf58\ud150\uce20\ub97c \uc81c\ud55c\ud55c\ub2e4. \uc774 \uc6d0\ub9ac\ub294 \uc911\uc694\ud55c \uc11c\ub958 \ud55c \uc7a5\ub9cc \ubd09\ud558\uace0 \ub098\uba38\uc9c0\ub294 \uadf8\ub300\ub85c \ubcf4\ub0b4\ub294 \uc0c1\ud669\uc744 \ub5a0\uc62c\ub9ac\uba74 \uc27d\ub2e4. \ud654\uba74\uc5d0\uc11c \ud55c \uc7a5\uc758 \ud398\uc774\uc9c0\ub85c \ubcf4\uc774\ub354\ub77c\ub3c4 \uc5ec\ub7ec \ud1b5\uc2e0\uc774 \ubaa8\uc778 \uacb0\uacfc\ub2e4. \uc0ac\uc774\ud2b8\ub97c \ub9cc\ub4dc\ub294 \ucabd\uc740 \uadf8 \uc790\ub8cc\ub4e4\uae4c\uc9c0 \ud568\uaed8 \ubcf4\ud638\ub418\ub3c4\ub85d \uc900\ube44\ud574\uc57c \ud55c\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uacf5\uc720 \uacf5\uac04\uc5d0\uc11c \ubd09\ud22c\uc5d0 \ub2f4\uae34 \ub9d0\uc744 \ub098\ub204\ub294 \ubd84\uc704\uae30\ub97c \ud45c\ud604\ud588\ub2e4. \uc2e4\uc81c \ub124\ud2b8\uc6cc\ud06c\ub098 \uc554\ud638\ud654 \uad6c\uc870\ub97c \ubcf4\uc5ec \uc8fc\ub294 \ub3c4\uc2dd\uc740 \uc544\ub2c8\ub2e4. \ube0c\ub77c\uc6b0\uc800\uc758 \ud45c\uc2dc \ubaa8\uc591\ub3c4 \uc81c\ud488\uacfc \ubc84\uc804\uc5d0 \ub530\ub77c \ubc14\ub014 \uc218 \uc788\uc73c\ubbc0\ub85c \uadf8\ub9bc\uc744 \uc124\uc815 \uc548\ub0b4\ucc98\ub7fc \uc0ac\uc6a9\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc791\uc740 s\ub294 \uc6f9\ud398\uc774\uc9c0\uc758 \ub0b4\uc6a9\uc774 \uc544\ub2c8\ub77c \uc624\uac00\ub294 \uae38\uc744 \ub2e4\ub974\uac8c \ub9cc\ub4e0\ub2e4. \uc77d\uae30 \uc5b4\ub835\uac8c \ud558\uace0, \ubc14\ub010 \uac83\uc744 \uc54c\uc544\ucc44\uba70, \ud574\ub2f9 \uc774\ub984\uc758 \uc11c\ubc84\uc640 \uc5f0\uacb0\ud588\ub294\uc9c0 \ud655\uc778\ud558\ub294 \uc57d\uc18d\uc774\ub2e4. \ub73b\uc744 \ub098\ub204\uc5b4 \uc54c\uba74 \uc775\uc219\ud55c \uc6f9 \uc8fc\uc18c\uc5d0\uc11c\ub3c4 \ud3b8\ub9ac\ud568\uc744 \uac00\ub2a5\ud558\uac8c \ud558\ub294 \uc870\uc6a9\ud55c \uae30\uc220\uc774 \ubcf4\uc778\ub2e4."}, {"id": "jpeg-small-photo-file", "title": "\uc0ac\uc9c4 \ud30c\uc77c\uc740 \uc5b4\ub5bb\uac8c \uac00\ubcbc\uc6cc\uc84c\uc744\uae4c \u2014 JPEG\uc758 \uc791\uc740 \ud0c0\ud611", "summary": "\uc0ac\uc9c4\uc744 \uc904\uc5ec \ubcf4\ub0b4\ub294 \uc555\ucd95\uc758 \uc6d0\ub9ac\uc640 \uc120\uba85\ud55c \uae00\uc528\uc5d0 \uc0dd\uae30\ub294 \ud754\uc801\uc744 \uc77c\uc0c1\uc758 \uc774\ubbf8\uc9c0\uc5d0\uc11c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\ub370\uc774\ud130\uc640 \uae30\ub85d", "categories": ["digital"], "url": "stories/jpeg-small-photo-file/index.html", "image": "../media/jpeg-small-photo-file.png", "alt": "\uc0ac\uc9c4\uac00\uc758 \ucc45\uc0c1 \uc704 \ud48d\uacbd \uc0ac\uc9c4 \uac00\uc7a5\uc790\ub9ac\uc5d0 \uc0c9 \uc870\uac01\uc774 \ud45c\ud604\ub41c \uc0c1\uc0c1 \uc0bd\ud654.", "text": "\uc0ac\uc9c4 \ud30c\uc77c\uc740 \uc5b4\ub5bb\uac8c \uac00\ubcbc\uc6cc\uc84c\uc744\uae4c \u2014 JPEG\uc758 \uc791\uc740 \ud0c0\ud611 \ub35c \ub0a8\uae30\uba74\uc11c\ub3c4 \uc0ac\uc9c4\ucc98\ub7fc \ubcf4\uc774\uac8c \ub9cc\ub4dc\ub294 \ubc29\ubc95 \uc0ac\uc9c4\uc744 \uc904\uc5ec \ubcf4\ub0b4\ub294 \uc555\ucd95\uc758 \uc6d0\ub9ac\uc640 \uc120\uba85\ud55c \uae00\uc528\uc5d0 \uc0dd\uae30\ub294 \ud754\uc801\uc744 \uc77c\uc0c1\uc758 \uc774\ubbf8\uc9c0\uc5d0\uc11c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ub370\uc774\ud130\uc640 \uae30\ub85d \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \uc5ec\ud589 \uc0ac\uc9c4 \ud55c \uc7a5\uc744 \ubcf4\ub0b4\ub824\ub294\ub370 \ud30c\uc77c\uc774 \ub108\ubb34 \ud06c\ub2e4\ub294 \uc548\ub0b4\uac00 \ub72c\ub2e4. \ud06c\uae30\ub97c \uc904\uc600\ub354\ub2c8 \ud654\uba74\uc5d0\uc11c\ub294 \ubcc4 \ucc28\uc774\uac00 \uc5c6\uc5b4 \ubcf4\uc778\ub2e4. \uadf8\ub7f0\ub370 \uae00\uc528\uac00 \uc788\ub294 \ubd80\ubd84\uc744 \ud655\ub300\ud558\uba74 \uac00\uc7a5\uc790\ub9ac\uac00 \uc870\uae08 \ud750\ub9bf\ud558\ub2e4. \uac19\uc740 \uc774\ubbf8\uc9c0\ub97c \uac00\ubccd\uac8c \ub9cc\ub4dc\ub294 \uc77c\uc5d0\ub3c4 \uc5b4\ub5a4 \uc815\ubcf4\ub294 \ub0a8\uae30\uace0 \uc5b4\ub5a4 \uc815\ubcf4\ub294 \ub35c \ub0a8\uae38\uc9c0\uc758 \uc120\ud0dd\uc774 \uc228\uc5b4 \uc788\ub2e4. JPEG\ub294 \ub514\uc9c0\ud138 \uc0ac\uc9c4\uc5d0\uc11c \ub110\ub9ac \ub9cc\ub098\ub294 \uc774\ub984\uc774\ub2e4. \uc0ac\uc9c4\uc744 \uc791\uac8c \ub9cc\ub4dc\ub294 \ub9c8\uc220 \uc0c1\uc790\ub77c\uae30\ubcf4\ub2e4, \uc0ac\ub78c\uc758 \ub208\uc774 \ubb34\uc5c7\uc5d0 \ubbfc\uac10\ud558\uace0 \uc5b4\ub5a4 \ucc28\uc774\ub294 \ub35c \uc54c\uc544\ucc28\ub9ac\ub294\uc9c0\ub97c \uc774\uc6a9\ud558\ub294 \uc5ec\ub7ec \uc57d\uc18d\uc758 \ubb36\uc74c\uc774\ub2e4. \ubcf5\uc7a1\ud55c \uc218\uc2dd\uc744 \ubab0\ub77c\ub3c4 \uadf8 \ud0c0\ud611\uc758 \uc131\uaca9\uc740 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ud654\uba74 \uc18d \uc0ac\uc9c4\uc740 \ub9ce\uc740 \ud654\uc18c, \uace7 \uc791\uc740 \uc810\uc758 \uc815\ubcf4\ub85c \ud45c\ud604\ub41c\ub2e4. \uc0ac\uc9c4\uc774 \ucee4\uc9c0\uace0 \uc0c9\uc758 \uc815\ubcf4\ub97c \uc790\uc138\ud788 \ub0a8\uae38\uc218\ub85d \ub2e4\ub8e8\uc5b4\uc57c \ud560 \ub370\uc774\ud130\ub3c4 \ub9ce\uc544\uc9c4\ub2e4. \ud30c\uc77c\uc744 \uac00\ubccd\uac8c \ub9cc\ub4e4\ub824\uba74 \uac19\uc740 \uc815\ubcf4\ub97c \ub354 \ud6a8\uc728\uc801\uc73c\ub85c \uc801\uac70\ub098 \uc815\ubcf4\uc758 \uc77c\ubd80\ub97c \ub35c \ub0a8\uae30\ub294 \ubc29\ubc95\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ub450 \ubc29\ubc95\uc740 \uacb0\uacfc\uac00 \ub2e4\ub974\ub2e4. \uc6d0\ub798 \ub0b4\uc6a9\uc744 \uc815\ud655\ud788 \ub2e4\uc2dc \ub9cc\ub4e4 \uc218 \uc788\uac8c \uc904\uc774\ub294 \ubc29\uc2dd\ub3c4 \uc788\uace0, \ubcf5\uc6d0\ud588\uc744 \ub54c \ucc98\uc74c\uacfc \uc644\uc804\ud788 \uac19\uc740 \ud654\uc18c\uac00 \ub418\uc9c0\ub294 \uc54a\ub294 \ubc29\uc2dd\ub3c4 \uc788\ub2e4. \uc77c\uc0c1\uc5d0\uc11c \ub110\ub9ac \uc4f0\ub294 JPEG \uc0ac\uc9c4 \uc555\ucd95\uc740 \ubcf4\ud1b5 \ub4a4\ucabd\uc5d0 \ud574\ub2f9\ud55c\ub2e4. \uc774\ub97c \uc190\uc2e4 \uc555\ucd95\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \uc0ac\ub78c\uc758 \uc2dc\uac01\uc740 \ubc1d\uae30\uc758 \uc138\ubd80\uc640 \uc0c9\uc758 \uc138\ubd80\ub97c \ub611\uac19\uc774 \ubc1b\uc544\ub4e4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc77c\ubc18\uc801\uc778 JPEG \ucc98\ub9ac\uc5d0\uc11c\ub294 \uc774\ub7f0 \ucc28\uc774\ub97c \uc774\uc6a9\ud574 \uc0c9 \uc815\ubcf4\uc758 \uc815\ubc00\ub3c4\ub97c \ub0ae\ucd94\uae30\ub3c4 \ud55c\ub2e4. \ub35c \ubbfc\uac10\ud558\uac8c \ub290\ub07c\ub294 \ubd80\ubd84\uc744 \uc904\uc5ec \uc804\uccb4 \ud06c\uae30\ub97c \uc904\uc774\ub294 \uac83\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc0ac\uc9c4\uc5d0\uc11c \ubcc4\ub85c \uc911\uc694\ud558\uc9c0 \uc54a\uc740 \ubb3c\uac74\uc744 \uc54c\uc544\ubcf4\uace0 \uc9c0\uc6b4\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc5ec\ud589 \uc0ac\uc9c4\uc758 \uc8fc\uc778\uacf5\uacfc \ubc30\uacbd\uc744 \uc0ac\ub78c\ucc98\ub7fc \uc774\ud574\ud574 \uace0\ub974\ub294 \uacfc\uc815\uacfc\ub294 \ub2e4\ub974\ub2e4. \uc0c9\uacfc \ubc1d\uae30\uc758 \ubcc0\ud654 \uac19\uc740 \uc218\uce58\uc758 \uc131\uc9c8\uc744 \ub2e4\ub8ec\ub2e4. \uc758\ubbf8\uac00 \uc911\uc694\ud574 \ubcf4\uc774\ub294 \uae00\uc528\ub3c4 \uc555\ucd95 \ubc29\uc2dd\uc5d0 \ub530\ub77c \uc120\uba85\ud568\uc744 \uc783\uc744 \uc218 \uc788\ub2e4. \uc0ac\uc9c4\uc758 \uc77c\uc815\ud55c \uc601\uc5ed\uc5d0\uc11c \uc0c9\uacfc \ubc1d\uae30\uac00 \ubcc0\ud558\ub294 \ubaa8\uc2b5\uc744 \ub2e4\ub978 \ud615\ud0dc\uc758 \uc218\uce58\ub85c \ud45c\ud604\ud558\uace0, \uadf8\uc911 \uc77c\ubd80\ub97c \ub35c \uc815\ubc00\ud558\uac8c \ub0a8\uae30\ub294 \uacfc\uc815\uc774 \uc788\ub2e4. \uc5ec\uae30\uc11c \ud30c\uc77c\uc758 \ud06c\uae30\uc640 \uc2dc\uac01\uc801 \ucda9\uc2e4\ub3c4 \uc0ac\uc774\uc758 \ud0c0\ud611\uc774 \uc0dd\uae34\ub2e4. \ubaa8\ub4e0 \uacc4\uc0b0\uc744 \ub530\ub77c\uac00\uae30\ubcf4\ub2e4 \uc815\ubcf4\ub97c \uac70\uce60\uac8c \uae30\ub85d\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc744 \uae30\uc5b5\ud558\uba74 \ub41c\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \ube44\uc2b7\ud55c \ud558\ub298\uc0c9\uc774 \uc774\uc5b4\uc9c0\ub294 \ub113\uc740 \ubd80\ubd84\uacfc \uac80\uc740 \uae00\uc528\uc758 \ub0a0\uce74\ub85c\uc6b4 \uacbd\uacc4\ub294 \uc131\uc9c8\uc774 \ub2e4\ub974\ub2e4. \uc555\ucd95\uc5d0 \uc798 \ub9de\ub294 \uc0ac\uc9c4\uc5d0\uc11c\ub294 \ub370\uc774\ud130\ub97c \ub9ce\uc774 \uc904\uc5ec\ub3c4 \ubcc0\ud654\uac00 \ub208\uc5d0 \uc798 \ub744\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \ubc18\ub300\ub85c \uc791\uc740 \uc138\ubd80\uc640 \uac15\ud55c \uacbd\uacc4\uac00 \ub9ce\uc740 \uacf3\uc5d0\uc11c\ub294 \uadf8 \ud754\uc801\uc774 \ub354 \uc27d\uac8c \ub4dc\ub7ec\ub09c\ub2e4. \uc0ac\uc9c4\uc744 \uc544\uc8fc \uc791\uac8c \ub9cc\ub4e4\uba74 \uae00\uc790\uc758 \ud14c\ub450\ub9ac\ub098 \ubb3c\uccb4\uc758 \uac00\uc7a5\uc790\ub9ac \uc8fc\ubcc0\uc5d0 \ubc88\uc9c0\ub294 \ub4ef\ud55c \ud754\uc801\uc774 \ubcf4\uc774\uae30\ub3c4 \ud55c\ub2e4. \ud655\ub300\ud588\uc744 \ub54c \uc791\uc740 \ube14\ub85d\uc758 \uacbd\uacc4\uac00 \ub4dc\ub7ec\ub0a0 \uc218\ub3c4 \uc788\ub2e4. \uc555\ucd95 \uacfc\uc815\uc5d0\uc11c \ub35c \ub0a8\uae34 \uc815\ubcf4\uac00 \uacb0\uacfc \ud654\uba74\uc5d0 \ub098\ud0c0\ub098\ub294 \ubaa8\uc2b5\uc774\ub2e4. JPEG \uad6c\ud604 \ubb38\uc11c\ub3c4 \ubd80\ub4dc\ub7fd\uac8c \uc0c9\uacfc \ubc1d\uae30\uac00 \ubc14\ub00c\ub294 \uc0ac\uc9c4\uc774 \uac15\uc810\uc774\uace0, \ub0a0\uce74\ub85c\uc6b4 \uc120\uc774\ub098 \uac11\uc790\uae30 \ubc14\ub00c\ub294 \ubd80\ubd84\uc5d0\uc11c\ub294 \ub208\uc5d0 \ub744\ub294 \ud754\uc801\uc744 \ud53c\ud558\uae30 \uc704\ud574 \ub354 \ub192\uc740 \ud488\uc9c8\uc774 \ud544\uc694\ud560 \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc120\uba85\ud55c \ub3c4\ud45c\uc640 \uc791\uc740 \uae00\uc528\uac00 \uc911\uc2ec\uc778 \ud654\uba74\uc740 \ud48d\uacbd \uc0ac\uc9c4\uacfc \ub2e4\ub974\uac8c \ub2e4\ub8f0 \uc774\uc720\uac00 \uc788\ub294 \uc148\uc774\ub2e4. \uc774\ubbf8\uc9c0\ub97c \uc800\uc7a5\ud560 \ub54c \ud488\uc9c8\uc744 \uc22b\uc790\ub85c \uace0\ub974\ub294 \ud504\ub85c\uadf8\ub7a8\uc774 \uc788\ub2e4. \ubcf4\ud1b5 \ub354 \ub192\uc740 \uc124\uc815\uc740 \uc815\ubcf4\ub97c \ub354 \ucda9\uc2e4\ud788 \ub0a8\uae30\uace0 \ud30c\uc77c\ub3c4 \ucee4\uc9c0\uac8c \ud558\uc9c0\ub9cc, \uc11c\ub85c \ub2e4\ub978 \ud504\ub85c\uadf8\ub7a8\uc758 \uac19\uc740 \uc22b\uc790\uac00 \uc644\uc804\ud788 \uac19\uc740 \uacb0\uacfc\ub97c \ubcf4\uc7a5\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8 \uc22b\uc790\ub9cc \ubcf4\uace0 \ubaa8\ub4e0 \ud30c\uc77c\uc744 \uacf5\ud1b5 \uae30\uc900\uc73c\ub85c \ube44\uad50\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \uc6d0\ub798\ubd80\ud130 \uc791\uc740 \uc0ac\uc9c4\uc744 \ub192\uc740 \ud488\uc9c8\ub85c \uc800\uc7a5\ud55c\ub2e4\uace0 \ucd2c\uc601\ud558\uc9c0 \uc54a\uc740 \uc138\ubd80\uac00 \ub418\uc0b4\uc544\ub098\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \ubcf4\uad00\ub41c \uc815\ubcf4\ubcf4\ub2e4 \ub354 \ub9ce\uc740 \uc2e4\uc81c \ub0b4\uc6a9\uc744 \uc790\ub3d9\uc73c\ub85c \ub418\ucc3e\uc744 \uc218\ub294 \uc5c6\ub2e4. \uc800\uc7a5 \uc124\uc815\uc740 \ub0a8\uc544 \uc788\ub294 \uc790\ub8cc\ub97c \uc5b4\ub5bb\uac8c \ucc98\ub9ac\ud560\uc9c0\uc758 \uc120\ud0dd\uc774\uc9c0 \uc774\ubbf8 \uc783\uc5b4\ubc84\ub9b0 \uc7a5\uba74\uc744 \ub418\ub3cc\ub9ac\ub294 \uc2dc\uac04 \uc5ec\ud589\uc774 \uc544\ub2c8\ub2e4. \uc0ac\uc9c4\uc744 \uc5f4\uc5b4 \ub0b4\uc6a9\uc744 \ubc14\uafbc \ub4a4 \ub2e4\uc2dc \uc190\uc2e4 \uc555\ucd95\ud558\uba74 \uc774\ubbf8 \ud55c \ubc88 \ub2ec\ub77c\uc9c4 \uc815\ubcf4\ub97c \ubc14\ud0d5\uc73c\ub85c \ub610 \uae30\ub85d\ud55c\ub2e4. \uc5ec\ub7ec \ucc28\ub840\uc758 \uc7ac\uc555\ucd95\uc740 \uc6d0\ubcf8\uacfc\uc758 \ucc28\uc774\ub97c \ub354 \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ud30c\uc77c\uc744 \uadf8\ub0e5 \ubcf5\uc0ac\ud558\uac70\ub098 \uc62e\uae34\ub2e4\uace0 \ub9e4\ubc88 \uc0ac\uc9c4\uc774 \ud750\ub824\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub2e4\uc2dc \uc555\ucd95\ud558\ub294 \uacfc\uc815\uc774 \uc788\ub294\uc9c0\ub97c \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. JPEG\ub77c\ub294 \uc774\ub984 \uc544\ub798\uc5d0\ub3c4 \uc5ec\ub7ec \uae30\ub2a5\uacfc \ubcc0\ud615\uc774 \uc788\ub2e4. \uad6c\ud604 \ubb38\uc11c\ub294 \uc190\uc2e4 \uc5c6\uc774 \ucc98\ub9ac\ud558\ub294 \uae30\ub2a5\ub3c4 \uc124\uba85\ud55c\ub2e4. \ub530\ub77c\uc11c \uc774\ub984\ub9cc \ubcf4\uace0 \uac00\ub2a5\ud55c \ubaa8\ub4e0 \ucc98\ub9ac \uacfc\uc815\uc744 \ud558\ub098\ub85c \ub2e8\uc815\ud558\uae30\ubcf4\ub2e4, \uc5ec\uae30\uc11c\ub294 \ud754\ud788 \uc4f0\uc774\ub294 \uc190\uc2e4 \uc555\ucd95 \uc0ac\uc9c4\uc758 \uacbd\ud5d8\uc744 \uc774\uc57c\uae30\ud558\uace0 \uc788\ub2e4\ub294 \ubc94\uc704\ub97c \uae30\uc5b5\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc774\ubbf8\uc9c0\uac00 \ub108\ubb34 \ud06c\uba74 \uc800\uc7a5\ud560 \uacf5\uac04\uacfc \ubcf4\ub0b4\ub294 \uc2dc\uac04\uc774 \ub9ce\uc774 \ud544\uc694\ud558\ub2e4. \uc0ac\uc9c4\uc758 \uc77c\ubd80 \uc815\ubcf4\ub97c \ub35c \ub0a8\uae30\ub294 \ud0c0\ud611\uc740 \ub354 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uc0ac\uc9c4\uc744 \uc8fc\uace0\ubc1b\uace0 \uc6f9\uc5d0\uc11c \ubcfc \uc218 \uc788\uac8c \ud558\ub294 \ub370 \uc758\ubbf8\uac00 \uc788\uc5c8\ub2e4. \uc815\ud655\ud788 \uac19\uc740 \ud654\uc18c\ub97c \uc720\uc9c0\ud558\ub294 \ubaa9\uc801\uacfc \uc77c\uc0c1\uc5d0\uc11c \ube60\ub974\uac8c \ubcf4\ub294 \ubaa9\uc801\uc774 \uc5b8\uc81c\ub098 \uc77c\uce58\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc18\uba74 \uc791\uc740 \uae00\uc528\uac00 \ub2f4\uae34 \uae30\ub85d\uc774\ub098 \uc815\ubc00\ud55c \uad00\ucc30 \uc790\ub8cc\uc5d0\uc11c\ub294 \uc0ac\uc18c\ud574 \ubcf4\uc774\ub294 \ud754\uc801\ub3c4 \ubb38\uc81c\uac00 \ub420 \uc218 \uc788\ub2e4. \uc5b4\ub5a4 \ud615\uc2dd\uc774 \uc5b8\uc81c\ub098 \ucd5c\uace0\ub77c\uace0 \uc678\uc6b0\uae30\ubcf4\ub2e4 \ubb34\uc5c7\uc744 \ubcf4\uc874\ud574\uc57c \ud558\ub294 \uc0ac\uc9c4\uc778\uc9c0 \ubb3b\ub294 \ud3b8\uc774 \uc774\ud574\uc5d0 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uc88b\uc740 \uc555\ucd95\uc740 \ubaa9\uc801\uacfc \ub9de\ub294 \ud0c0\ud611\uc77c \ub54c \uc88b\uc740 \uacb0\uacfc\uac00 \ub41c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \uc0ac\uc9c4\uacfc \uc555\ucd95\uc758 \uad00\uacc4\ub97c \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 AI \uc0bd\ud654\ub2e4. \uac00\uc7a5\uc790\ub9ac\uc758 \uc0c9 \uc870\uac01\uc740 \uc2e4\uc81c JPEG \uc2e4\ud5d8 \uacb0\uacfc\ub098 \uac19\uc740 \uc6d0\ubcf8\uc758 \ud488\uc9c8 \ube44\uad50 \uc790\ub8cc\uac00 \uc544\ub2c8\ub2e4. \uc815\ud655\ud55c \uc131\ub2a5\uc744 \ube44\uad50\ud558\ub294 \ub3c4\ud45c\ucc98\ub7fc \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\uc74c\uc5d0 \uc791\uc740 \uc0ac\uc9c4 \ud30c\uc77c\uc744 \uc5f4 \ub54c\ub294 \uadf8 \uc548\uc758 \ud48d\uacbd\ubfd0 \uc544\ub2c8\ub77c \ub0a8\uaca8\uc9c4 \uc815\ubcf4\uc640 \ub35c \ub0a8\uaca8\uc9c4 \uc815\ubcf4\ub3c4 \uc0dd\uac01\ud574 \ubcf4\uc790. \ud654\uba74\uc5d0\uc11c \ucda9\ubd84\ud788 \uc790\uc5f0\uc2a4\ub7ec\uc6cc \ubcf4\uc778\ub2e4\ub294 \uac83\uc740 \ubaa8\ub4e0 \uc815\ubcf4\uac00 \uadf8\ub300\ub85c\ub77c\ub294 \ub73b\uacfc \ub2e4\ub974\ub2e4. \ub514\uc9c0\ud138 \uae30\uc220\uc758 \ud765\ubbf8\ub85c\uc6b4 \ubd80\ubd84\uc740 \uc885\uc885 \uc644\ubcbd\ud558\uac8c \ub611\uac19\uc740 \uac83\ubcf4\ub2e4 \uc0c1\ud669\uc5d0 \ub9de\uac8c \ucda9\ubd84\ud788 \uc88b\uc740 \uac83\uc744 \ub9cc\ub4dc\ub294 \ub370 \uc788\ub2e4."}, {"id": "linux-shared-kernel", "title": "\ub9ac\ub205\uc2a4 \u2014 \ud3ad\uadc4 \ub4a4\uc5d0\ub294 \ub204\uac00 \uc77c\ud558\uace0 \uc788\uc744\uae4c", "summary": "\ucee4\ub110\uc758 \uc5ed\ud560\uacfc \uc2e4\uc81c \uac1c\ubc1c \ubb38\uc11c\ub97c \ud1b5\ud574 \uc5f4\ub9b0 \ud611\uc5c5\uc5d0 \ud544\uc694\ud55c \uac80\ud1a0\uc640 \ucc45\uc784\uc758 \uad6c\uc870\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\uc18c\ud504\ud2b8\uc6e8\uc5b4", "categories": ["digital"], "url": "stories/linux-shared-kernel/index.html", "image": "../media/linux-shared-kernel.png", "alt": "\ub798\ub9ac \uc720\uc789\uc758 \uc6d0\uc791\uc744 \uac1c\ub9bf \ub974\uc0ac\uc8fc\uac00 \uc7ac\uc791\uc5c5\ud558\uace0 IFo Hancroft\uac00 \ub2e4\ub4ec\uc740 \ub9ac\ub205\uc2a4 \ud3ad\uadc4 \ud131\uc2a4\uc758 \uc2e4\uc81c \uacf5\uac1c \uc774\ubbf8\uc9c0.", "text": "\ub9ac\ub205\uc2a4 \u2014 \ud3ad\uadc4 \ub4a4\uc5d0\ub294 \ub204\uac00 \uc77c\ud558\uace0 \uc788\uc744\uae4c \ud568\uaed8 \uace0\uce58\ub418 \uc544\ubb34\ub807\uac8c\ub098 \ubc14\uafb8\uc9c0\ub294 \uc54a\ub294 \uc18c\ud504\ud2b8\uc6e8\uc5b4 \ucee4\ub110\uc758 \uc5ed\ud560\uacfc \uc2e4\uc81c \uac1c\ubc1c \ubb38\uc11c\ub97c \ud1b5\ud574 \uc5f4\ub9b0 \ud611\uc5c5\uc5d0 \ud544\uc694\ud55c \uac80\ud1a0\uc640 \ucc45\uc784\uc758 \uad6c\uc870\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc18c\ud504\ud2b8\uc6e8\uc5b4 \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \ub178\ub780 \ubd80\ub9ac\ub97c \uac00\uc9c4 \ud3ad\uadc4 \uadf8\ub9bc\uc744 \ubcf4\uba74 \ucef4\ud4e8\ud130\ub97c \ub5a0\uc62c\ub9ac\ub294 \uc0ac\ub78c\uc774 \uc788\ub2e4. \ub9ac\ub205\uc2a4\uc640 \ud568\uaed8 \ub110\ub9ac \uc54c\ub824\uc9c4 \ud131\uc2a4\ub2e4. \uadf8\ub9bc\uc740 \uce5c\uadfc\ud558\uc9c0\ub9cc \uadf8 \ub4a4\uc5d0 \uc788\ub294 \uc18c\ud504\ud2b8\uc6e8\uc5b4\ub294 \uc218\ub9ce\uc740 \uc7a5\uce58\uc640 \uc791\uc5c5\uc744 \uc870\uc815\ud574\uc57c \ud55c\ub2e4. \uc5ec\ub7ec \uc0ac\ub78c\uc774 \ud568\uaed8 \ub9cc\ub4e0\ub2e4\uace0 \ud558\ub294\ub370, \ubaa8\ub450\uac00 \ub9c8\uc74c\ub300\ub85c \uace0\uce58\uba74 \uc5b4\ub5bb\uac8c \ud558\ub098\uc758 \ud504\ub85c\uadf8\ub7a8\uc73c\ub85c \uc6c0\uc9c1\uc77c \uc218 \uc788\uc744\uae4c. \ub9ac\ub205\uc2a4\ub97c \uc774\ud574\ud558\ub294 \uccab\uac78\uc74c\uc740 \uc5b4\ub824\uc6b4 \uba85\ub839\uc5b4\ubcf4\ub2e4 \ud568\uaed8 \uc77c\ud558\ub294 \ubc29\uc2dd\uc744 \ubcf4\ub294 \ub370 \uc788\ub2e4. \uc2e4\uc81c \uac1c\ubc1c \uc548\ub0b4\uc5d0\ub294 \ubb34\uc5c7\uc744 \ub9cc\ub4e4\uc9c0\ubfd0 \uc544\ub2c8\ub77c \uc5b4\ub5bb\uac8c \uc81c\uc548\ud558\uace0 \ub204\uad6c\uc5d0\uac8c \ubcf4\uc5ec \uc8fc\uba70 \uc5b4\ub5a4 \uac80\ud1a0\ub97c \uac70\uce60\uc9c0\uac00 \uae38\uac8c \uc801\ud600 \uc788\ub2e4. \uc5f4\ub9b0 \ud611\uc5c5\uc5d0\ub3c4 \uc9c8\uc11c\uc640 \ucc45\uc784\uc774 \ud544\uc694\ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \ub9ac\ub205\uc2a4 \ucee4\ub110\uc758 \uacf5\uc2dd \uc18c\uac1c\ub294 \ucee4\ub110\uc744 \uc6b4\uc601\uccb4\uc81c\uc758 \ud575\uc2ec\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \uae30\uacc4\uc758 \uc790\uc6d0\uacfc \uc7a5\uce58\ub97c \uad00\ub9ac\ud558\uace0 \ub2e4\ub978 \uc18c\ud504\ud2b8\uc6e8\uc5b4\uac00 \uc774\uc6a9\ud560 \uae30\ubcf8 \uc11c\ube44\uc2a4\ub97c \uc81c\uacf5\ud55c\ub2e4. \ubb38\uc11c \uc791\uc131 \ud504\ub85c\uadf8\ub7a8\uc774 \ud654\uba74\uc5d0\uc11c \uac00\uc7a5 \ub208\uc5d0 \ub744\uc5b4\ub3c4 \uadf8 \uc544\ub798\uc5d0\uc11c\ub294 \uba54\ubaa8\ub9ac\uc640 \uc7a5\uce58\ub97c \ub2e4\ub8e8\ub294 \uc77c\uc774 \uacc4\uc18d\ub41c\ub2e4. \ucee4\ub110\uc744 \uc77c\uc0c1\uc5d0 \ube44\uc720\ud558\uba74 \uc5ec\ub7ec \ud65c\ub3d9\uc774 \uac19\uc740 \uc2dc\uc124\uc744 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d \uc870\uc815\ud558\ub294 \uae30\ucd08 \uc6b4\uc601\uc5d0 \uac00\uae5d\ub2e4. \ub2e4\ub9cc \ube44\uc720\uac00 \uc815\ud655\ud55c \uc124\uacc4\ub3c4\ub294 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c \uc911\uc694\ud55c \uac83\uc740 \ud654\uba74\uc758 \ubaa8\uc591\uc744 \uc815\ud558\ub294 \ud504\ub85c\uadf8\ub7a8\uacfc \ucef4\ud4e8\ud130\uc758 \uae30\ubcf8 \uc791\ub3d9\uc744 \ub9e1\ub294 \ubd80\ubd84\uc774 \uac19\uc9c0 \uc54a\ub2e4\ub294 \uc810\uc774\ub2e4. \uc77c\uc0c1\uc5d0\uc11c\ub294 \ub9ac\ub205\uc2a4\ub77c\ub294 \ub9d0\uc744 \ud558\ub098\uc758 \uc644\uc131\ub41c \uc6b4\uc601\uccb4\uc81c\ucc98\ub7fc \uc4f0\uae30\ub3c4 \ud55c\ub2e4. \uc5c4\ubc00\ud558\uac8c \ucee4\ub110\uc744 \uac00\ub9ac\ud0a4\ub294 \uacbd\uc6b0\uc640, \ucee4\ub110\uc5d0 \uc5ec\ub7ec \ud504\ub85c\uadf8\ub7a8\uc744 \ub354\ud574 \uc0ac\uc6a9\ud560 \uc218 \uc788\uac8c \ubb36\uc740 \ubc30\ud3ec\ud310\uc744 \uac00\ub9ac\ud0a4\ub294 \uacbd\uc6b0\ub97c \uad6c\ubd84\ud558\uba74 \ud63c\ub3d9\uc774 \uc904\uc5b4\ub4e0\ub2e4. \uac19\uc740 \ud575\uc2ec \uc704\uc5d0 \uc11c\ub85c \ub2e4\ub978 \uad6c\uc131\uc774 \ub193\uc77c \uc218 \uc788\ub2e4. \ub530\ub77c\uc11c \ub9ac\ub205\uc2a4\ub77c\ub294 \uc774\ub984\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \ucef4\ud4e8\ud130\uc758 \ud654\uba74\uacfc \uc0ac\uc6a9\ubc95\uc774 \uac19\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5b4\ub5a4 \ud504\ub85c\uadf8\ub7a8\uc744 \ud568\uaed8 \ubb36\uace0 \uc5b4\ub5bb\uac8c \uc5c5\ub370\uc774\ud2b8\ud558\uba70 \uc5b4\ub5a4 \uc0ac\uc6a9\uc790\ub97c \ub3d5\ub294\uc9c0\uc5d0 \ub530\ub77c \uacbd\ud5d8\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ud558\ub098\uc758 \uae30\uc220\uacfc \uadf8\uac83\uc744 \uc0ac\uc6a9\ud558\uae30 \uc88b\uc740 \uc0c1\ud0dc\ub85c \uafb8\ub9ac\ub294 \uc77c\uc740 \uc774\uc5b4\uc838 \uc788\uc9c0\ub9cc \uac19\uc740 \uc791\uc5c5\uc740 \uc544\ub2c8\ub2e4. \ub9ac\ub205\uc2a4\uc758 \ucd08\uae30 \uc5ed\uc0ac\ub294 \ub9ac\ub204\uc2a4 \ud1a0\ub974\ubc1c\uc2a4\uc640 \uc5f0\uacb0\ub41c\ub2e4. \uae43\uc758 \uc5ed\uc0ac \uc548\ub0b4\ub294 1991\ub144\ubd80\ud130 \uc774\uc5b4\uc9c4 \ucd08\uae30 \ub9ac\ub205\uc2a4 \ucee4\ub110 \uac1c\ubc1c\uc5d0\uc11c \uc218\uc815 \ub0b4\uc6a9\uc744 \ud328\uce58\uc640 \ud30c\uc77c\ub85c \uc8fc\uace0\ubc1b\uc558\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ucc98\uc74c\uc758 \uc2dc\uc791\uc744 \uae30\uc5b5\ud558\ub294 \uac83\uacfc \uc624\ub298\uc758 \uacb0\uacfc\ub97c \ud55c \uc0ac\ub78c\uc758 \uc791\uc5c5\uc73c\ub85c \uc124\uba85\ud558\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uacf5\uc2dd \uc548\ub0b4\uc5d0\ub294 \uc5ec\ub7ec \ubd84\uc57c\uc758 \uad00\ub9ac\uc790\uac00 \ub4f1\uc7a5\ud55c\ub2e4. \uc7a5\uce58\uc640 \uae30\ub2a5\uc774 \ub9ce\uc544\uc9c0\uba74 \ubaa8\ub4e0 \ubcc0\uacbd\uc744 \ud55c \uc0ac\ub78c\uc774 \uac19\uc740 \uae4a\uc774\ub85c \uc0b4\ud53c\uae30 \uc5b4\ub835\ub2e4. \ub2f4\ub2f9 \ubd80\ubd84\uc744 \uc798 \uc544\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc81c\uc548\uc744 \uc77d\uace0 \ub354 \ud070 \ud750\ub984\uc73c\ub85c \uc5f0\uacb0\ud55c\ub2e4. \ud070 \ud611\uc5c5\uc740 \ucc38\uc5ec\uc790\uc758 \uc218\ubfd0 \uc544\ub2c8\ub77c \uac80\ud1a0\uc758 \uacbd\ub85c\ub3c4 \ud568\uaed8 \ucee4\uc838\uc57c \ud55c\ub2e4. \uc18c\uc2a4 \ucf54\ub4dc\uac00 \uacf5\uac1c\ub418\uc5b4 \uc788\uc73c\uba74 \uad00\uc2ec \uc788\ub294 \uc0ac\ub78c\uc774 \uc2e4\uc81c \ub0b4\uc6a9\uc744 \uc0b4\ud3b4\ubcf4\uace0 \ubb38\uc81c\ub97c \uc870\uc0ac\ud558\uac70\ub098 \uc218\uc815\uc548\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \uac1c\ubc1c \uc548\ub0b4\ub294 \ub9ac\ub205\uc2a4 \ucee4\ub110\uc758 \ucf54\ub4dc\uac00 GPL\uc5d0 \ub530\ub77c \uc81c\uacf5\ub41c\ub2e4\uace0 \ubc1d\ud78c\ub2e4. \uacf5\uac1c\ub294 \uc774\uc6a9\uacfc \ubc30\ud3ec\uc758 \uc870\uac74\uc744 \uac00\uc9c4 \ud615\ud0dc\uc774\uba70 \uc870\uac74\uc774 \uc804\ud600 \uc5c6\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub204\uad6c\ub098 \ub0b4\uc6a9\uc744 \ubcfc \uc218 \uc788\ub2e4\ub294 \uc810\uc740 \uc911\uc694\ud558\uc9c0\ub9cc \uadf8\uac83\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc624\ub958\uac00 \uc989\uc2dc \uc0ac\ub77c\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc77d\uc744 \uc0ac\ub78c\uc758 \uc9c0\uc2dd\uacfc \uc2dc\uac04\ub3c4 \ud544\uc694\ud558\uace0 \uc218\uc815 \ub4a4\uc5d0 \ub2e4\ub978 \ubb38\uc81c\uac00 \uc0dd\uae30\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uacf5\uac1c \uc5ec\ubd80\uc640 \uac80\ud1a0\uc758 \ucda9\ubd84\ud568\uc744 \uac19\uc740 \ub9d0\ub85c \ucde8\uae09\ud558\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \uac1c\ubc1c \ubb38\uc11c\ub294 \ucf54\ub4dc\uc758 \ud615\uc2dd\uacfc \uc218\uc815\uc548 \uc81c\ucd9c \ubc29\ubc95\uc744 \uc124\uba85\ud55c\ub2e4. \uc81c\uc548\ud55c \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc544\uc8fc \uc791\uc740 \ubcc0\ud654\ub77c\ub3c4 \uac80\ud1a0\ud558\ub294 \uc0ac\ub78c\uc740 \uc774\uc720\uc640 \uc601\ud5a5\uc744 \uc54c\uc544\uc57c \ud55c\ub2e4. \uc815\ud574\uc9c4 \ubc29\uc2dd\uc73c\ub85c \uc124\uba85\ud558\uace0 \ubcf4\ub0b4\ub294 \uac83\uc740 \ud615\uc2dd\ub9cc\uc744 \uc704\ud55c \uc608\uc808\uc774 \uc544\ub2c8\ub77c \uc5ec\ub7ec \uc0ac\ub78c\uc774 \ub0b4\uc6a9\uc744 \ube44\uad50\ud560 \uc218 \uc788\uac8c \ud558\ub294 \ub3c4\uad6c\ub2e4. \uc88b\uc740 \uc81c\uc548\uc774\ub77c\uace0 \ud574\uc11c \uc790\ub3d9\uc73c\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc9c0\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uae30\uc874 \uae30\ub2a5\uacfc \ucda9\ub3cc\ud558\uac70\ub098 \ub2e4\ub978 \ud658\uacbd\uc5d0 \ubb38\uc81c\uac00 \uc0dd\uae38 \uc218 \uc788\ub2e4. \ud568\uaed8 \uace0\uce5c\ub2e4\ub294 \ub9d0\uc5d0\ub294 \ud568\uaed8 \uac70\uc808\ud558\uace0 \ub2e4\uc2dc \uc124\uba85\ud558\uba70 \ub354 \ub098\uc740 \uc81c\uc548\uc744 \uae30\ub2e4\ub9ac\ub294 \uc77c\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \uc5f4\ub9b0 \ubb38\uc740 \uac80\ud1a0\uac00 \uc5c6\ub294 \ubb38\uacfc \ub2e4\ub974\ub2e4. \uacf5\uc2dd \uc548\ub0b4\ub294 \ud070 \ubcc0\uacbd\uc744 \ubc1b\uc544\ub4e4\uc774\ub294 \uc2dc\uae30\uc640 \uadf8 \ub4a4\uc758 \ud6c4\ubcf4 \ubc84\uc804\uc744 \uc124\uba85\ud55c\ub2e4. \uc0c8\ub85c\uc6b4 \uae30\ub2a5\uc744 \ubaa8\uc73c\ub294 \uc77c\ub9cc \uacc4\uc18d\ud558\uba74 \uae30\uc874\uc5d0 \ub418\ub358 \uac83\uc774 \uac11\uc790\uae30 \uc548 \ub418\ub294 \ubb38\uc81c\ub97c \ub193\uce60 \uc218 \uc788\ub2e4. \ubcc0\ud654\uac00 \uc5b4\ub290 \uc815\ub3c4 \ubaa8\uc774\uba74 \uc81c\ub300\ub85c \uc791\ub3d9\ud558\ub294\uc9c0 \ub2e4\ub4ec\ub294 \uc2dc\uac04\uc774 \ud544\uc694\ud558\ub2e4. \uc774\uc804\uc5d0\ub294 \uc798\ub418\ub358 \uae30\ub2a5\uc774 \ubcc0\uacbd \ub4a4\uc5d0 \ub9dd\uac00\uc9c0\ub294 \uc77c\uc744 \ud68c\uadc0 \ubb38\uc81c\ub77c\uace0 \ubd80\ub978\ub2e4. \uc0c8\ub85c \ubb34\uc5b8\uac00\ub97c \ub354\ud588\ub2e4\ub294 \uc18c\uc2dd\ub9cc\ud07c \ud558\ub358 \uc77c\uc774 \uacc4\uc18d \ub41c\ub2e4\ub294 \uc0ac\uc2e4\ub3c4 \uc911\uc694\ud558\ub2e4. \uc0ac\uc6a9\uc790\ub294 \uac1c\ubc1c\uc790\uc758 \uc758\uc695\ubcf4\ub2e4 \uc790\uae30 \uc791\uc5c5\uc774 \uba48\ucd94\uc9c0 \uc54a\ub294 \uac83\uc744 \uba3c\uc800 \uc6d0\ud560 \uc218 \uc788\ub2e4. \uc548\uc815\uc131\ub3c4 \ud611\uc5c5\uc774 \ub9cc\ub4e4\uc5b4\uc57c \ud560 \uacb0\uacfc\ub2e4. \ud568\uaed8 \uc2e4\uc740 \ud131\uc2a4\ub294 \uc0c8\ub85c \uc0c1\uc0c1\ud55c \ud3ad\uadc4\uc774 \uc544\ub2c8\ub77c \uc6d0\uc791\uc744 \ubca1\ud130\ub85c \ub2e4\uc2dc \uadf8\ub9b0 \uc81c\uc791\uc790\uac00 \uacf5\uac1c\ud55c PNG \ud30c\uc77c\uc774\ub2e4. \ub9ac\ub205\uc2a4 \uacf5\uc2dd \uc800\uc7a5\uc18c\uc758 \uc548\ub0b4\uc640 \uc81c\uc791\uc790 \uc124\uba85\uc744 \ud568\uaed8 \ud655\uc778\ud588\ub2e4. \uc6d0\uc791\uc740 \ub798\ub9ac \uc720\uc789, \uc7ac\uc791\uc5c5\uc740 \uac1c\ub9bf \ub974\uc0ac\uc8fc, \ub2e4\ub4ec\uae30\ub294 IFo Hancroft\uc758 \uc791\uc5c5\uc73c\ub85c \ud45c\uc2dc\ub418\uc5b4 \uc788\ub2e4. \uacf5\uc2dd \uc800\uc7a5\uc18c\uc758 \uc774\uc6a9 \uc548\ub0b4\ub294 \uc6d0\uc791\uc790\uc640 \ubca1\ud130 \uc791\uc5c5\uc790\ub97c \ubc1d\ud788\ub3c4\ub85d \ud558\uace0, \uc81c\uc791\uc790 \uc800\uc7a5\uc18c\ub294 \ud37c\ube14\ub9ad \ub3c4\uba54\uc778\u00b7CC0\ub85c \ud45c\uc2dc\ud55c\ub2e4. \uc774 \uae00\ub3c4 \uc138 \uc81c\uc791\uc790\ub97c \ud06c\ub808\ub527\uc5d0 \uc801\uc5c8\ub2e4. \uce5c\uadfc\ud55c \uc0c1\uc9d5\uc5d0\ub3c4 \ucd9c\ucc98\uac00 \uc788\ub2e4. \ub2e4\ub9cc \ud3ad\uadc4 \uadf8\ub9bc\uc774 \uc788\ub2e4\uace0 \ubaa8\ub450 \uac19\uc740 \uc81c\ud488\uc774\uac70\ub098 \uac19\uc740 \uc870\uc9c1\uc758 \ubcf4\uc99d\uc744 \ubc1b\uc558\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub9ac\ub205\uc2a4\uc758 \ud765\ubbf8\ub85c\uc6b4 \uc810\uc740 \ub2e8\uc21c\ud788 \ub9ce\uc740 \uc0ac\ub78c\uc774 \ucc38\uc5ec\ud588\ub2e4\ub294 \uc22b\uc790\uc5d0 \uc788\uc9c0 \uc54a\ub2e4. \uc218\uc815\uc758 \uc774\uc720\ub97c \uc4f0\uace0, \ub2f4\ub2f9\uc790\uc5d0\uac8c \ubcf4\ub0b4\uace0, \uac80\ud1a0\ud558\uace0, \uae30\uc874 \uae30\ub2a5\uc744 \uc9c0\ud0a4\uba70 \ubb36\uc5b4 \ub0b4\ub294 \uacfc\uc815\uc774 \uc788\ub2e4\ub294 \uc810\uc774\ub2e4. \uacf5\uc720\ub294 \uacb0\uacfc\ub97c \ub098\ub204\ub294 \uc77c\uc774\uba74\uc11c \uc791\uc5c5\uc758 \uaddc\uce59\uc744 \ud568\uaed8 \uc138\uc6b0\ub294 \uc77c\uc774\uae30\ub3c4 \ud558\ub2e4. \ud3ad\uadc4 \ub4a4\uc5d0\ub294 \ub208\uc5d0 \ub744\ub294 \ucc3d\uc2dc\uc790\ubfd0 \uc544\ub2c8\ub77c \uc791\uc740 \ubb38\uc81c\ub97c \ucc3e\uc544 \uc54c\ub9ac\ub294 \uc0ac\ub78c\uacfc \uc124\uba85\uc744 \uace0\uce58\ub294 \uc0ac\ub78c, \ubcc0\uacbd\uc744 \uac80\ud1a0\ud558\ub294 \uc0ac\ub78c\uc774 \uc788\ub2e4. \ucef4\ud4e8\ud130\uac00 \uc870\uc6a9\ud788 \uc81c \uc77c\uc744 \ud558\ub294 \uc21c\uac04\uc5d0\ub3c4 \uadf8 \uc5f0\uacb0\uc774 \uc791\ub3d9\ud558\uace0 \uc788\ub2e4. \uae30\uc220\uc744 \uc774\ud574\ud558\ub294 \uc77c\uc774 \uc0ac\ub78c\ub4e4\uc758 \ud611\uc5c5\uc744 \uc77d\ub294 \uc77c\uc774 \ub418\ub294 \ub300\ubaa9\uc774\ub2e4."}, {"id": "markdown-readable-source-and-commonmark", "title": "\ub9c8\ud06c\ub2e4\uc6b4 \u2014 \uafb8\ubbf8\uae30 \uc804\uc758 \uae00\ub3c4 \uc77d\uae30 \uc88b\uac8c \ub9cc\ub4e4\ub824\uba74", "summary": "2004\ub144\uc758 \ud3c9\ubb38 \ud615\uc2dd\uc5d0\uc11c \ucee4\uba3c\ub9c8\ud06c\uc758 \uc0c1\uc138\ud55c \uc608\uc2dc\uae4c\uc9c0 \ubb38\uc11c\ub97c \ub098\ub204\ub294 \uc57d\uc18d\uc758 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\uc18c\ud504\ud2b8\uc6e8\uc5b4", "categories": ["digital"], "url": "stories/markdown-readable-source-and-commonmark/index.html", "image": "../media/markdown-readable-source-and-commonmark.png", "alt": "\ud3c9\ubb38 \uc6d0\uace0\uc640 \uc815\ub3c8\ub41c \ucc45\uc744 \ud568\uaed8 \ub193\uc740 \uae00\uc4f0\uae30 \ucc45\uc0c1\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ub9c8\ud06c\ub2e4\uc6b4 \u2014 \uafb8\ubbf8\uae30 \uc804\uc758 \uae00\ub3c4 \uc77d\uae30 \uc88b\uac8c \ub9cc\ub4e4\ub824\uba74 \ud3c9\ubb38\uc758 \uac00\ub3c5\uc131\uacfc \ubb38\uc11c \uad6c\uc870, \uba85\uc138\uc640 \uad6c\ud604\uc758 \ud569\uc758 2004\ub144\uc758 \ud3c9\ubb38 \ud615\uc2dd\uc5d0\uc11c \ucee4\uba3c\ub9c8\ud06c\uc758 \uc0c1\uc138\ud55c \uc608\uc2dc\uae4c\uc9c0 \ubb38\uc11c\ub97c \ub098\ub204\ub294 \uc57d\uc18d\uc758 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uc18c\ud504\ud2b8\uc6e8\uc5b4 \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \ubb38\uc11c\ub97c \ubcf4\uae30 \uc88b\uac8c \ub9cc\ub4e4\uae30 \uc704\ud574 \ubcf5\uc7a1\ud55c \uba85\ub839\uc744 \uc794\ub729 \ub123\uc73c\uba74, \uc815\uc791 \uc6d0\ub798 \ud30c\uc77c\uc740 \uc77d\uae30 \uc5b4\ub824\uc6cc\uc9c8 \uc218 \uc788\ub2e4. \ub9c8\ud06c\ub2e4\uc6b4\uc740 \ud3c9\ubc94\ud55c \ud14d\uc2a4\ud2b8\ub85c \uad6c\uc870\ub97c \ud45c\ud604\ud558\uba74\uc11c\ub3c4 \uc0ac\ub78c\uc774 \uadf8 \ud30c\uc77c \uc790\uccb4\ub97c \uc77d\uae30 \uc27d\uac8c \ud558\ub824\ub294 \ubc29\uc2dd\uc774\ub2e4. \uae00\uacfc \ubaa8\uc591\uc744 \uc5f0\uacb0\ud558\ub294 \uc791\uc740 \uc57d\uc18d\uc774 \uc65c \ub110\ub9ac \uc4f0\uc774\uac8c \ub418\uc5c8\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \ub9c8\ud06c\ub2e4\uc6b4\uc740 \uc774\uba54\uc77c\uacfc \uc628\ub77c\uc778 \uae00\uc5d0\uc11c \uac15\uc870\uc640 \ubaa9\ub85d\uc744 \ud45c\ud604\ud558\ub358 \uad00\uc2b5\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc874 \uadf8\ub8e8\ubc84\uac00 \uc5d0\ub7f0 \uc2a4\uc6cc\uce20\uc758 \ub3c4\uc6c0\uc744 \ubc1b\uc544 \uac1c\ubc1c\ud588\uace0 2004\ub144 \uc124\uba85\uacfc \ubcc0\ud658 \ud504\ub85c\uadf8\ub7a8\uc774 \uacf5\uac1c\ub418\uc5c8\ub2e4. \ucc98\uc74c\ubd80\ud130 \ud654\ub824\ud55c \uc804\uc6a9 \ud3b8\uc9d1 \ud654\uba74\ub9cc\uc744 \ubaa9\ud45c\ub85c \ud55c \ubc29\uc2dd\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ud654\uba74\uc5d0 \uadf8\ub7f4\ub4ef\ud558\uac8c \ubcf4\uc774\ub294 \uacb0\uacfc\ubfd0 \uc544\ub2c8\ub77c \uc6d0\ubcf8\uc758 \uac00\ub3c5\uc131\uc774\uc5c8\ub2e4. \ubcc4\ub3c4 \ud504\ub85c\uadf8\ub7a8\uc774 \uc5c6\uc5b4\ub3c4 \ub300\ub7b5\uc758 \uad6c\uc870\ub97c \uc54c\uc544\ubcfc \uc218 \uc788\ub294 \uae00\uc744 \ub9cc\ub4e4\ub824 \ud588\ub2e4. \ubb38\uc11c\ub97c \uad50\ud658\ud560 \ub54c \ud2b9\uc815\ud55c \ud3b8\uc9d1 \ub3c4\uad6c\uc5d0 \uae30\ub300\ub294 \uc815\ub3c4\ub97c \uc904\uc77c \uac00\ub2a5\uc131\uc774 \uc0dd\uae34\ub2e4. \uc81c\ubaa9\uacfc \ubaa9\ub85d, \uc778\uc6a9 \uac19\uc740 \uc694\uc18c\ub294 \uac04\ub2e8\ud55c \ubb38\uc790 \uaddc\uce59\uc73c\ub85c \ub098\ud0c0\ub0bc \uc218 \uc788\ub2e4. \ubcc0\ud658 \ud504\ub85c\uadf8\ub7a8\uc740 \uc774\ub97c \ud574\uc11d\ud574 \uc6f9 \ubb38\uc11c \ub4f1\uc758 \uad6c\uc870\ub85c \ubc14\uafbc\ub2e4. \uac19\uc740 \ubb38\uc11c\uac00 \uc6d0\ubcf8\uc5d0\uc11c\ub294 \ud3c9\ubb38\uc73c\ub85c, \uacb0\uacfc\uc5d0\uc11c\ub294 \ub2e4\ub978 \ubaa8\uc591\uc73c\ub85c \ubcf4\uc774\ub294 \uac83\uc774\ub2e4. \uc774\ub54c \uc81c\ubaa9\uc744 \ud45c\uc2dc\ud55c\ub2e4\ub294 \uac83\uacfc \uae00\uc790\ub97c \ubb34\uc870\uac74 \ud2b9\uc815 \ud06c\uae30\ub85c \uace0\uc815\ud55c\ub2e4\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uc2e4\uc81c \ubaa8\uc591\uc740 \uacb0\uacfc\ub97c \ubcf4\uc5ec \uc8fc\ub294 \ud658\uacbd\uc5d0\ub3c4 \ub2ec\ub824 \uc788\ub2e4. \ubb38\uc11c\uc5d0 \ubb34\uc5c7\uc774 \ub4e4\uc5b4 \uc788\ub294\uc9c0\uc640 \uadf8\uac83\uc744 \uc5b4\ub5bb\uac8c \uafb8\ubc00\uc9c0\ub97c \uc5b4\ub290 \uc815\ub3c4 \ub098\ub204\uc5b4 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ubb38\uc11c\uc5d0\ub294 \uba85\ub839\uc774\ub098 \ud504\ub85c\uadf8\ub7a8 \ucf54\ub4dc \uc790\uccb4\ub97c \uc124\uba85\ud558\ub294 \ubd80\ubd84\ub3c4 \uc788\ub2e4. \uc774\ub7f0 \ub0b4\uc6a9\uae4c\uc9c0 \ubaa8\ub450 \uc11c\uc2dd \uae30\ud638\ub85c \ud574\uc11d\ud558\uba74 \uace4\ub780\ud558\ub2e4. \ub9c8\ud06c\ub2e4\uc6b4\uc758 \ucf54\ub4dc \ud45c\uc2dc\ub294 \uc5b4\ub5a4 \ubb38\uc790\ub97c \ubb38\uc11c \uad6c\uc870\uac00 \uc544\ub2cc \uc124\uba85 \ub300\uc0c1\uc758 \ub0b4\uc6a9\uc73c\ub85c \ubcf4\uc5ec \uc904\uc9c0 \uad6c\ubd84\ud558\uac8c \ud55c\ub2e4. \uc5ec\uae30\uc11c \uc0ac\ub78c\uc774 \ubcf4\ub294 \ud45c\uae30\uc640 \ud574\uc11d\ud558\ub294 \uaddc\uce59\uc758 \uad00\uacc4\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \uae30\ud638 \ud55c \uac1c\ub3c4 \ubb38\ub9e5\uc5d0 \ub530\ub77c \uad6c\uc870\ub97c \ub9cc\ub4dc\ub294 \uc9c0\uc2dc\uac00 \ub418\uac70\ub098 \uadf8\ub300\ub85c \ucd9c\ub825\ud560 \ubb38\uc790\uac00 \ub420 \uc218 \uc788\ub2e4. \uc77d\uae30 \uc26c\uc6cc \ubcf4\uc774\ub294 \ud615\uc2dd\uc774\ub77c\uace0 \ud574\uc11d\uc774 \uc804\ud600 \ud544\uc694 \uc5c6\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \ubcc4\ud45c\ub294 \ub193\uc778 \uc790\ub9ac\uc5d0 \ub530\ub77c \uac15\uc870\uc758 \ud45c\uc9c0\uac00 \ub418\uac70\ub098 \ubaa9\ub85d\uc744 \uc2dc\uc791\ud558\ub294 \uae30\ud638\uac00 \ub420 \uc218 \uc788\ub2e4. \ucf54\ub4dc\ub85c \ubcf4\uc5ec \uc8fc\uace0 \uc2f6\uc740 \ubb38\uc7a5 \uc548\uc5d0 \uac19\uc740 \uae30\ud638\uac00 \ub4e4\uc5b4 \uc788\ub2e4\uba74 \ub2e4\ub978 \ucc98\ub9ac\ub3c4 \ud544\uc694\ud558\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \ubaa8\uc591 \ud558\ub098\uc640 \ubb38\uc11c\uc5d0\uc11c \ub9e1\uc740 \uc5ed\ud560\uc774 \uc5b8\uc81c\ub098 \uc77c\ub300\uc77c\ub85c \ub300\uc751\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ube48 \uc904\ub85c \ubb38\ub2e8\uc744 \ub098\ub204\ub294 \uc77c\uacfc \ubb38\ub2e8 \uc548\uc5d0\uc11c \uc904\uc744 \ubc14\uafb8\ub294 \uc77c\ub3c4 \uad6c\ubd84\ud560 \uc218 \uc788\ub2e4. \uc791\uc131 \ud654\uba74\uc5d0\uc11c \uc904\uc774 \ub0b4\ub824\uac14\ub2e4\uace0 \uacb0\uacfc\uc5d0\uc11c \ubb34\uc870\uac74 \uc0c8 \ubb38\ub2e8\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774\ub7f0 \ucc28\uc774\ub294 \ucc98\uc74c\uc5d0 \ub0af\uc124\uc9c0\ub9cc \uad6c\uc870\ub97c \ud45c\ud604\ud558\ub294 \ud615\uc2dd\uc774\ub77c\ub294 \uc810\uc744 \uc54c\uba74 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \uc0ac\uc6a9\uc790\ub294 \ubaa8\uc591\uc744 \uc9c1\uc811 \uce60\ud558\ub294 \ub300\uc2e0 \uc81c\ubaa9\uacfc \ubb38\ub2e8, \uc778\uc6a9\uc758 \uad00\uacc4\ub97c \ud45c\uc2dc\ud55c\ub2e4. \uc6d0\ubcf8\uc744 \uc77d\ub294 \uc0ac\ub78c\uacfc \uacb0\uacfc\ub97c \uc77d\ub294 \uc0ac\ub78c\uc774 \uac19\uc740 \uad6c\uc870\ub97c \uc54c\uc544\ubcfc \uc218 \uc788\uac8c \ud558\ub294 \uc57d\uc18d\uc774\ub2e4. \ub9c8\ud06c\ub2e4\uc6b4\uc774 \uc5ec\ub7ec \uc5b8\uc5b4\uc640 \ud504\ub85c\uadf8\ub7a8\uc73c\ub85c \uad6c\ud604\ub418\uba74\uc11c \uc560\ub9e4\ud55c \ubd80\ubd84\uc774 \ub4dc\ub7ec\ub0ac\ub2e4. \ubaa9\ub85d\uc744 \uc5bc\ub9c8\ub098 \ub4e4\uc5ec\uc4f8\uc9c0, \uc904\ubc14\uafc8\uc774\ub098 \uae30\ud638\uac00 \ud2b9\uc815 \uc0c1\ud669\uc5d0\uc11c \ubb34\uc5c7\uc744 \ub73b\ud560\uc9c0 \ubaa8\ub450 \uc644\uc804\ud788 \ubd84\uba85\ud588\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\uc774 \ubcf4\uae30\uc5d0\ub294 \ube44\uc2b7\ud574\ub3c4 \ud504\ub85c\uadf8\ub7a8\uc740 \uacb0\uc815\ud574\uc57c \ud55c\ub2e4. \uadf8 \uacb0\uacfc \uac19\uc740 \uc6d0\ubb38\uc774 \ub3c4\uad6c\uc5d0 \ub530\ub77c \ub2e4\ub978 \uad6c\uc870\ub85c \ubc14\ub014 \uc218 \uc788\uc5c8\ub2e4. \uc774\ub294 \ub2e8\uc21c\ud788 \uc5b4\ub290 \ud504\ub85c\uadf8\ub7a8 \ud558\ub098\uac00 \uace0\uc7a5 \ub0ac\ub2e4\ub294 \ubb38\uc81c\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uacf5\uc720\ud558\ub294 \uaddc\uce59\uc774 \ucda9\ubd84\ud788 \uc790\uc138\ud55c\uc9c0\uc758 \ubb38\uc81c\uc774\uae30\ub3c4 \ud588\ub2e4. \ub110\ub9ac \uc4f0\uc774\ub294 \ud615\uc2dd\uc77c\uc218\ub85d \ubaa8\ud638\ud568\uc744 \ub2e4\ub8e8\ub294 \uc77c\uc774 \uc911\uc694\ud574\uc9c4\ub2e4. \ucee4\uba3c\ub9c8\ud06c\ub294 \ub9c8\ud06c\ub2e4\uc6b4\uc744 \ub354 \uba85\ud655\ud558\uac8c \uaddc\uc815\ud558\ub824\ub294 \uc791\uc5c5\uc774\ub2e4. \uba85\uc138\uc5d0\ub294 \uc124\uba85\uacfc \ud568\uaed8 \uc218\ub9ce\uc740 \uc785\ub825\u00b7\ucd9c\ub825 \uc608\uc2dc\uac00 \uc788\ub2e4. \uc560\ub9e4\ud55c \uacbd\uc6b0\ub97c \uae00\ub85c\ub9cc \uc124\uba85\ud558\ub294 \ub300\uc2e0 \uc2e4\uc81c \ubb38\uc790\uc5f4\uc744 \uc5b4\ub5bb\uac8c \ud574\uc11d\ud560\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc774\ub2e4. \uc608\uc2dc\ub294 \uad6c\ud604\uc790\uac00 \uac19\uc740 \uacb0\uacfc\ub97c \ub9cc\ub4dc\ub294\uc9c0 \ud655\uc778\ud558\ub294 \ub370\ub3c4 \uc4f0\uc77c \uc218 \uc788\ub2e4. \ubb38\uc11c\uc758 \uaddc\uce59\uc774 \ub3c5\uc790\ub97c \uc704\ud55c \uc548\ub0b4\uc640 \ud504\ub85c\uadf8\ub7a8\uc744 \ub9cc\ub4dc\ub294 \uc0ac\ub78c\uc758 \uae30\uc900\uc774 \ub41c\ub2e4. \ub2e8\uc21c\ud55c \ud615\uc2dd\uc744 \uc9c0\uc18d\ud574\uc11c \uc4f0\uae30 \uc704\ud574\uc11c\ub3c4 \uc815\ubc00\ud55c \ud569\uc758\uc640 \uc2dc\ud5d8\uc774 \ud544\uc694\ud558\ub2e4\ub294 \uc810\uc774 \ud765\ubbf8\ub86d\ub2e4. \ud45c\ub098 \uc791\uc5c5 \ubaa9\ub85d, \uac01\uc8fc \uac19\uc740 \uae30\ub2a5\uc740 \uc11c\ube44\uc2a4\uc640 \ud655\uc7a5 \ubc29\uc2dd\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc5b4\ub5a4 \uc0ac\uc774\ud2b8\uc5d0\uc11c \ud3b8\ub9ac\ud558\uac8c \uc4f0\ub358 \ubb38\uc11c\ub97c \ub2e4\ub978 \uacf3\uc73c\ub85c \uc62e\uacbc\uc744 \ub54c \uacb0\uacfc\uac00 \ub2ec\ub77c\uc9c0\ub294 \uc774\uc720\ub2e4. \ub9c8\ud06c\ub2e4\uc6b4\uc774\ub77c\ub294 \uc774\ub984\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \ud655\uc7a5\uc758 \ud638\ud658\uc131\uc774 \ubcf4\uc7a5\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub530\ub77c\uc11c \uc624\ub798 \ubcf4\uad00\ud558\uac70\ub098 \uc5ec\ub7ec \uacf3\uc5d0\uc11c \uc0ac\uc6a9\ud560 \ubb38\uc11c\ub294 \uc5b4\ub5a4 \uae30\ub2a5\uc5d0 \uae30\ub300\uace0 \uc788\ub294\uc9c0 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ub2e8\uc21c\ud558\uac8c \uc4f0\ub77c\ub294 \uc808\ub300\uc801\uc778 \uaddc\uce59\uc774\ub77c\uae30\ubcf4\ub2e4 \ubaa9\uc801\uc5d0 \ub9de\ub294 \uc120\ud0dd\uc758 \ubb38\uc81c\ub2e4. \uc791\uc131\uc758 \ud3b8\uc758\uc640 \uc774\ub3d9\uc758 \ud3b8\uc758\ub97c \ud568\uaed8 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ub9c8\ud06c\ub2e4\uc6b4\uc758 \ub9e4\ub825\uc740 \uc815\ubc00\ud55c \uaddc\uce59\uacfc \ud3b8\ud55c \uae00\uc4f0\uae30\uac00 \ubc18\ub300\uac00 \uc544\ub2c8\ub77c\ub294 \uc810\uc5d0 \uc788\ub2e4. \uc0ac\uc6a9\uc790\ub294 \uac04\ub2e8\ud55c \ud45c\uae30\ub85c \uc4f0\uace0, \uad6c\ud604\uc790\ub294 \ub354 \uc790\uc138\ud55c \uaddc\uce59\uc744 \uc9c0\ucf1c \uadf8 \ub73b\uc744 \uc62e\uae34\ub2e4. \uac89\uc758 \ub2e8\uc21c\ud568\uc744 \uac00\ub2a5\ud558\uac8c \ud558\ub294 \uc77c\uc774 \uc548\ucabd\uc5d0\uc11c\ub294 \uacc4\uc18d \uc774\ub8e8\uc5b4\uc9c4\ub2e4. \uc9c0\uae08 \ubcf4\uace0 \uc788\ub294 \uae00\ub3c4 \uc6d0\ubcf8\uacfc \uac8c\uc2dc \ud654\uba74\uc758 \ubaa8\uc591\uc774 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc81c\ubaa9\uacfc \ubb38\ub2e8, \ubaa9\ub85d\uc758 \uad6c\uc870\uac00 \ub2e4\ub978 \ud658\uacbd\uc73c\ub85c \uc804\ub2ec\ub418\uae30 \ub54c\ubb38\uc774\ub2e4. \ubb38\uc11c\uac00 \ub2e4\ub978 \ud504\ub85c\uadf8\ub7a8\uc73c\ub85c \uc774\ub3d9\ud560 \ub54c \uc6d0\ub798 \uad6c\uc870\uac00 \uc5bc\ub9c8\ub098 \uc774\uc5b4\uc9c0\ub294\uc9c0\ub3c4 \ud615\uc2dd\uc758 \uac00\uce58\uac00 \ub41c\ub2e4. \ub208\uc5d0 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294 \ud569\uc758\uac00 \uadf8 \uc774\ub3d9\uc744 \ub3d5\ub294\ub2e4. \ub9c8\ud06c\ub2e4\uc6b4\uc758 \uc5ed\uc0ac\ub294 \uae00\uc744 \uafb8\ubbf8\ub294 \uae30\uc220\ub9cc\uc774 \uc544\ub2c8\ub77c \uc0ac\ub78c\uacfc \ud504\ub85c\uadf8\ub7a8\uc774 \uac19\uc740 \ubb38\uc11c\uc758 \ub73b\uc744 \uc5b4\ub5bb\uac8c \ub098\ub220 \uc774\ud574\ud560\uc9c0 \uace0\ubbfc\ud55c \uc5ed\uc0ac\uc774\uae30\ub3c4 \ud558\ub2e4."}, {"id": "microsoft-dos-open-archive", "title": "\ub9c8\uc774\ud06c\ub85c\uc18c\ud504\ud2b8\uac00 \uc61b \ud504\ub85c\uadf8\ub7a8\uc744 \uacf5\uac1c\ud55c \uae4c\ub2ed", "summary": "\uc61b \uc6b4\uc601\uccb4\uc81c\uc758 \uc124\uacc4 \ub0b4\uc6a9\uc744 \uacf5\uac1c\ud55c \uacf5\uc2dd \uc800\uc7a5\uc18c\uc5d0\uc11c \uc18c\ud504\ud2b8\uc6e8\uc5b4\ub97c \ubcf4\uc874\ud558\ub294 \uc758\ubbf8\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\uc18c\ud504\ud2b8\uc6e8\uc5b4", "categories": ["digital"], "url": "stories/microsoft-dos-open-archive/index.html", "image": "../media/microsoft-dos-open-archive.png", "alt": "\uc61b \uac1c\uc778\uc6a9 \ucef4\ud4e8\ud130\uc640 \ud50c\ub85c\ud53c \ub514\uc2a4\ud06c, \uc778\uc1c4 \uae30\ub85d\uc744 \ubcf4\uad00 \uc0c1\uc790\uc640 \ud568\uaed8 \uc0b4\ud3b4\ubcf4\ub294 \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ub9c8\uc774\ud06c\ub85c\uc18c\ud504\ud2b8\uac00 \uc61b \ud504\ub85c\uadf8\ub7a8\uc744 \uacf5\uac1c\ud55c \uae4c\ub2ed MS-DOS\uc758 \uc18c\uc2a4 \ucf54\ub4dc\ub97c \uc5ed\uc0ac \uc790\ub8cc\ub85c \uc77d\ub294 \uc2dc\uac04 \uc61b \uc6b4\uc601\uccb4\uc81c\uc758 \uc124\uacc4 \ub0b4\uc6a9\uc744 \uacf5\uac1c\ud55c \uacf5\uc2dd \uc800\uc7a5\uc18c\uc5d0\uc11c \uc18c\ud504\ud2b8\uc6e8\uc5b4\ub97c \ubcf4\uc874\ud558\ub294 \uc758\ubbf8\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc18c\ud504\ud2b8\uc6e8\uc5b4 \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \ubc15\ubb3c\uad00\uc5d0\uc11c \uc624\ub798\ub41c \ucef4\ud4e8\ud130\ub97c \ub9cc\ub098\uba74 \ubca0\uc774\uc9c0\uc0c9 \ubcf8\uccb4\uc640 \ucee4\ub2e4\ub780 \ubaa8\ub2c8\ud130\uac00 \uba3c\uc800 \ubcf4\uc778\ub2e4. \ud558\uc9c0\ub9cc \uc804\uc6d0\uc744 \ucf1c\ub3c4 \ub2f9\uc2dc\uc758 \uacbd\ud5d8\uc774 \ubaa8\ub450 \ub3cc\uc544\uc624\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc548\uc5d0\uc11c \uc5b4\ub5a4 \ud504\ub85c\uadf8\ub7a8\uc774 \uc6c0\uc9c1\uc600\ub294\uc9c0, \uadf8 \ud504\ub85c\uadf8\ub7a8\uc774 \uc5b4\ub5a4 \uc0dd\uac01\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc84c\ub294\uc9c0 \uc54c\uc544\uc57c \ucef4\ud4e8\ud130\uc758 \uacfc\uac70\uac00 \uc870\uae08 \ub354 \uc120\uba85\ud574\uc9c4\ub2e4. \ub9c8\uc774\ud06c\ub85c\uc18c\ud504\ud2b8\ub294 \uacf5\uc2dd GitHub \uc800\uc7a5\uc18c\uc5d0 \ucd08\uae30 MS-DOS\uc758 \uc18c\uc2a4 \ucf54\ub4dc\uc640 \uc77c\ubd80 \uc2e4\ud589 \ud30c\uc77c\uc744 \uacf5\uac1c\ud574 \ub193\uc558\ub2e4. \uc775\uc219\ud558\uc9c0 \uc54a\uc740 \ucf54\ub4dc\uac00 \uc794\ub729 \uc788\ub294 \uacf5\uac04\uc774\uc9c0\ub9cc, \ud504\ub85c\uadf8\ub798\ubc0d\uc744 \ud558\uc9c0 \uc54a\ub294 \uc0ac\ub78c\ub3c4 \uadf8 \uacf5\uac1c\uc758 \uc758\ubbf8\ub294 \uc77d\uc744 \uc218 \uc788\ub2e4. \uae30\uacc4\uc758 \uac89\ubaa8\uc2b5 \uc606\uc5d0 \uc791\ub3d9 \ubc29\uc2dd\uc758 \uae30\ub85d\uc744 \ub193\uc740 \uc148\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \uc18c\uc2a4 \ucf54\ub4dc\ub294 \uc0ac\ub78c\uc774 \ud504\ub85c\uadf8\ub7a8\uc744 \ub9cc\ub4e4 \ub54c \uc791\uc131\ud558\ub294 \uc9c0\uc2dc\uc758 \uae30\ub85d\uc774\ub2e4. \uc2e4\uc81c\ub85c \uc2e4\ud589\ub418\ub294 \ud30c\uc77c\uacfc\ub294 \ud615\uc2dd\uacfc \uc5ed\ud560\uc774 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc644\uc131\ub41c \uc74c\uc2dd\uc744 \uba39\ub294 \uac83\uacfc \uc694\ub9ac\uc758 \uc7ac\ub8cc\u00b7\uc21c\uc11c\ub97c \uc77d\ub294 \uc77c\uc774 \ub2e4\ub974\ub4ef, \uc791\ub3d9 \uacb0\uacfc\ub9cc \ubcf4\ub294 \uac83\uacfc \uadf8 \uacb0\uacfc\ub97c \ub9cc\ub4dc\ub294 \ub0b4\uc6a9\uc744 \uc0b4\ud3b4\ubcf4\ub294 \uc77c\ub3c4 \ub2e4\ub974\ub2e4. \ubb3c\ub860 \ucf54\ub4dc\uac00 \uacf5\uac1c\ub418\uc5c8\ub2e4\uace0 \ub204\uad6c\ub098 \uace7\ubc14\ub85c \ubaa8\ub4e0 \ub0b4\uc6a9\uc744 \uc774\ud574\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc61b \uae30\uacc4\uc758 \uad6c\uc870\uc640 \ub2f9\uc2dc\uc758 \ub3c4\uad6c\ub97c \uc54c\uc544\uc57c \uc77d\ud788\ub294 \ubd80\ubd84\ub3c4 \ub9ce\ub2e4. \uadf8\ub798\ub3c4 \uc9c8\ubb38\ud560 \uc218 \uc788\ub294 \uadfc\uac70\uac00 \uc0dd\uae34\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uc791\ub3d9 \ubc29\uc2dd\uc774 \uc624\uc9c1 \uae30\uc5b5\uc774\ub098 \ud68c\uace0\uc5d0\ub9cc \uc758\uc874\ud558\uc9c0 \uc54a\uac8c \ub418\ub294 \uac83\uc774\ub2e4. \uc6b4\uc601\uccb4\uc81c\ub294 \ub2e4\ub978 \ud504\ub85c\uadf8\ub7a8\uc774 \ucef4\ud4e8\ud130\uc758 \uc7a5\uce58\uc640 \ud30c\uc77c\uc744 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d \uae30\ubcf8\uc801\uc778 \uc77c\uc744 \ub9e1\ub294\ub2e4. MS-DOS\ub77c\ub294 \uc774\ub984\uc740 \ucd08\uae30 \uac1c\uc778\uc6a9 \ucef4\ud4e8\ud130\uc758 \uc5ed\uc0ac\uc5d0\uc11c \uc790\uc8fc \ub4f1\uc7a5\ud55c\ub2e4. \uc624\ub298\uc758 \uadf8\ub9bc \uc911\uc2ec \ud654\uba74\uacfc \ub2e4\ub978 \uc2dc\ub300\uc758 \ucef4\ud4e8\ud130 \uc0ac\uc6a9\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uc774\ub984\uc774\uae30\ub3c4 \ud558\ub2e4. \uc774 \uae00\uc758 \uc911\uc2ec\uc740 \ud2b9\uc815 \uba85\ub839\uc5b4\ub97c \ubc30\uc6b0\ub294 \ub370 \uc788\uc9c0 \uc54a\ub2e4. \uc5b4\ub5a4 \ud504\ub85c\uadf8\ub7a8\uc774 \uc2e4\ud589\ub418\uae30 \uc804\uc5d0 \uadf8 \ubc14\ud0d5\uc744 \ub9c8\ub828\ud558\ub294 \uc18c\ud504\ud2b8\uc6e8\uc5b4\uac00 \ud544\uc694\ud558\ub2e4\ub294 \uc810\uc744 \uc774\ud574\ud558\uba74 \ucda9\ubd84\ud558\ub2e4. \ub208\uc5d0 \uc798 \ub744\ub294 \ubb38\uc11c \uc791\uc131 \ud504\ub85c\uadf8\ub7a8\uc774\ub098 \uac8c\uc784 \uc544\ub798\uc5d0\ub3c4 \uc0ac\uc6a9\uc790\uac00 \uc9c1\uc811 \uc758\uc2dd\ud558\uc9c0 \uc54a\ub294 \uae30\ubcf8 \uc791\uc5c5\uc774 \ub193\uc5ec \uc788\ub2e4. \ud604\uc7ac \uacf5\uc2dd \uc548\ub0b4\ub294 MS-DOS 1.25\uc640 2.0\uc758 \uc6d0\ubcf8 \uc18c\uc2a4 \ucf54\ub4dc \ubc0f \uc2e4\ud589 \ud30c\uc77c, \uadf8\ub9ac\uace0 IBM\uacfc \ub9c8\uc774\ud06c\ub85c\uc18c\ud504\ud2b8\uac00 \ud568\uaed8 \uac1c\ubc1c\ud55c 4.00\uc758 \uc18c\uc2a4 \ucf54\ub4dc\ub97c \uc124\uba85\ud55c\ub2e4. \uc61b MS-DOS\uc758 \ubaa8\ub4e0 \ubc84\uc804\uc774 \ube60\uc9d0\uc5c6\uc774 \ub4e4\uc5b4 \uc788\ub294 \uc644\uc804\ud55c \ubc15\ubb3c\uad00\uc774\ub77c\uace0 \uc18c\uac1c\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc548\ub0b4\ubb38\uc740 1.25\uc640 2.0 \uc790\ub8cc\uac00 2014\ub144 3\uc6d4 25\uc77c \ucef4\ud4e8\ud130 \uc5ed\uc0ac \ubc15\ubb3c\uad00\uc744 \ud1b5\ud574 \uba3c\uc800 \uacf5\uc720\ub418\uc5c8\ub2e4\uace0 \ubc1d\ud78c\ub2e4. \uc774\ud6c4 \uc774 \uc800\uc7a5\uc18c\uc5d0\uc11c \ub2e4\uc2dc \uc81c\uacf5\ud558\ub294 \uc774\uc720\ub85c \uc790\ub8cc\ub97c \ub354 \uc27d\uac8c \ucc3e\uace0 \ub2e4\ub978 \uae00\uc5d0\uc11c \ucc38\uc870\ud558\uba70 \uc0b4\ud3b4\ubcfc \uc218 \uc788\uac8c \ud55c\ub2e4\ub294 \uc810\uc744 \ub4e0\ub2e4. \uc624\ub798\ub41c \uc790\ub8cc\uc758 \uc811\uadfc\uc131\ub3c4 \ubcf4\uc874\uc758 \uc77c\ubd80\uc778 \uac83\uc774\ub2e4. \uc61b \ud504\ub85c\uadf8\ub7a8\uc758 \ub0b4\uc6a9\uc774 \uacf5\uac1c\ub418\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc740 \uc0c8 \ubc84\uc804\uc774 \ub098\uc654\ub2e4\ub294 \uc18c\uc2dd\uacfc \uc131\uaca9\uc774 \ub2e4\ub974\ub2e4. \uc774 \uc800\uc7a5\uc18c\ub294 \uc5ed\uc0ac\uc801 \ucc38\uace0\ub97c \ubaa9\uc801\uc73c\ub85c \uc790\ub8cc\ub97c \uc720\uc9c0\ud55c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc9c0\uae08 \uc0ac\uc6a9\ud558\ub294 \ucef4\ud4e8\ud130\ub97c \ubaa8\ub450 \uc774 \ud504\ub85c\uadf8\ub7a8\uc73c\ub85c \ubc14\uafb8\ub77c\ub294 \uad8c\uc720\uac00 \uc544\ub2c8\ub2e4. \uc61b \ubb38\uc11c\uac00 \ud604\uc7ac\uc758 \uc124\uba85\uc11c\uac00 \ub420 \uc218 \uc5c6\ub4ef \uc61b \uc18c\ud504\ud2b8\uc6e8\uc5b4\ub3c4 \ub2f9\uc2dc\uc758 \ud658\uacbd\uc5d0\uc11c \uc774\ud574\ud574\uc57c \ud55c\ub2e4. \ud638\ud658\ub418\ub294 \uc7a5\uce58\ub098 \uc2e4\ud589 \uc870\uac74\uc744 \ub530\uc838\uc57c \ud558\ub294 \ubb38\uc81c\ub294 \ubcc4\ub3c4\ub85c \ub0a8\ub294\ub2e4. \uacf5\uac1c \uc0ac\uc2e4\uc744 \uace7\ubc14\ub85c \uc624\ub298\uc758 \uc77c\uc0c1 \uc0ac\uc6a9\uc5d0 \uc801\ud569\ud558\ub2e4\ub294 \ubcf4\uc99d\uc73c\ub85c \ubc1b\uc544\ub4e4\uc774\uba74 \uc790\ub8cc\uac00 \uac00\uc9c4 \ubaa9\uc801\uc744 \ub193\uce58\uac8c \ub41c\ub2e4. \ud765\ubbf8\ub86d\uac8c\ub3c4 \uacf5\uc2dd \uc548\ub0b4\ub294 \uc18c\uc2a4 \ucf54\ub4dc\uc758 \uc218\uc815\uc744 \uc81c\uc548\ud558\ub294 \uc694\uccad\uc744 \ubcf4\ub0b4\uc9c0 \ub9d0\uc544 \ub2ec\ub77c\uace0 \ud55c\ub2e4. \uc5ed\uc0ac \uc790\ub8cc\ub85c \ubcf4\uad00\ud558\uae30 \ub54c\ubb38\uc5d0 \uadf8\ub300\ub85c \uc720\uc9c0\ud558\uaca0\ub2e4\ub294 \ub73b\uc774\ub2e4. \ubcf4\ud1b5 \uc18c\ud504\ud2b8\uc6e8\uc5b4\uc758 \uc624\ub958\ub97c \ubc1c\uacac\ud558\uba74 \uace0\uce58\ub824 \ud558\ub294\ub370, \uc5ec\uae30\uc11c\ub294 \ubcf4\uc874\uc774\ub77c\ub294 \ub2e4\ub978 \ubaa9\uc801\uc774 \uc55e\uc5d0 \ub193\uc778\ub2e4. \uc624\ub798\ub41c \uc6d0\uace0\uc758 \ub9de\ucda4\ubc95\uc744 \uc624\ub298\uc758 \uae30\uc900\uc73c\ub85c \ubaa8\ub450 \uace0\uccd0 \ub193\uc73c\uba74 \ub2f9\uc2dc \ud45c\uae30\ub97c \uc5f0\uad6c\ud558\uae30 \uc5b4\ub824\uc6cc\uc9c8 \uc218 \uc788\ub2e4. \uc18c\ud504\ud2b8\uc6e8\uc5b4\uc5d0\ub3c4 \ube44\uc2b7\ud55c \ubb38\uc81c\uac00 \uc788\ub2e4. \ud6c4\ub300\uc758 \uac1c\uc120\uc774 \uc544\ubb34\ub9ac \uc720\uc775\ud574\ub3c4 \uc6d0\ub798 \uae30\ub85d\uacfc \uc11e\uc774\uba74 \uacfc\uac70\uc758 \uc120\ud0dd\uc744 \uc77d\uae30 \uc5b4\ub824\uc6cc\uc9c4\ub2e4. \uc0ac\uc6a9\ud558\uae30 \ud3b8\ud55c \uac83\uacfc \uc5ed\uc0ac \uc790\ub8cc\ub85c \uc815\ud655\ud55c \uac83\uc740 \uac19\uc740 \uae30\uc900\uc774 \uc544\ub2c8\ub2e4. \uc6d0\ubcf8\uc744 \uc720\uc9c0\ud558\uaca0\ub2e4\ub294 \ubc29\uce68\uc774 \ubaa8\ub4e0 \uc2e4\ud5d8\uc744 \ub9c9\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc548\ub0b4\ubb38\uc740 \uc790\ub8cc\ub97c \ubcf5\uc81c\ud55c \ubcc4\ub3c4\uc758 \uacf5\uac04\uc5d0\uc11c \uc0b4\ud3b4\ubcf4\uace0 \uc2e4\ud5d8\ud560 \uc218 \uc788\ub2e4\uace0 \ub367\ubd99\uc778\ub2e4. \uc6d0\ub798 \uae30\ub85d\uacfc \ud6c4\ub300\uc758 \uc2dc\ub3c4\ub97c \uad6c\ubd84\ud558\uba74 \ubcf4\uc874\uacfc \ud0d0\uad6c\uac00 \ud568\uaed8 \uac00\ub2a5\ud574\uc9c4\ub2e4. \uacf5\uc2dd \uc800\uc7a5\uc18c\ub294 \ud30c\uc77c\uc744 MIT \ub77c\uc774\uc120\uc2a4\ub85c \uc81c\uacf5\ud55c\ub2e4\uace0 \ubc1d\ud78c\ub2e4. \uc774\uc6a9 \uc870\uac74\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub3c4 \uacf5\uac1c\uc758 \uc911\uc694\ud55c \ubd80\ubd84\uc774\ub2e4. \ub204\uad6c\ub098 \ubcfc \uc218 \uc788\ub2e4\ub294 \uac83\uacfc \uc544\ubb34 \uc870\uac74\ub3c4 \uc5c6\ub2e4\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uc800\uc791\uad8c \uc548\ub0b4\uc758 \ubcf4\uc874 \uac19\uc740 \uc870\uac74\uc744 \ud655\uc778\ud558\ub294 \uc77c\uacfc \uae30\uc5c5\uc758 \uc0c1\ud45c\ub97c \ub9c8\uc74c\ub300\ub85c \uc4f0\ub294 \uc77c\ub3c4 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \uae30\uc5c5\uc758 \uc5ed\uc0ac\ub97c \ub85c\uace0\ub098 \ucc3d\uc5c5\uc790\uc758 \ub9d0\ub85c\ub9cc \uc811\ud558\uba74 \uc2e4\uc81c\ub85c \ubb34\uc5c7\uc744 \ub9cc\ub4e4\uc5c8\ub294\uc9c0\uac00 \uba40\uc5b4\uc9c8 \uc218 \uc788\ub2e4. \uc18c\uc2a4 \ucf54\ub4dc\ub294 \uc774\ub984 \ub4a4\uc5d0 \uc788\ub294 \uad6c\uccb4\uc801\uc778 \uc791\uc5c5\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc81c\ud55c\ub41c \ud658\uacbd\uc5d0\uc11c \uc5b4\ub5a4 \uae30\ub2a5\uc744 \uad6c\ud604\ud558\uace0 \uc5b4\ub5a4 \uc21c\uc11c\ub85c \ubb38\uc81c\ub97c \ub2e4\ub8e8\uc5c8\ub294\uc9c0 \uc5f0\uad6c\ud560 \uc218 \uc788\ub294 \ucd9c\ubc1c\uc810\uc774 \ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \ucf54\ub4dc\ub9cc\uc73c\ub85c \uae30\uc5c5\uc758 \ubaa8\ub4e0 \uacb0\uc815\uc744 \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \uacc4\uc57d\uacfc \uc2dc\uc7a5, \uc774\uc6a9\uc790\uc758 \uacbd\ud5d8\uc740 \ub2e4\ub978 \uae30\ub85d\uc774 \ud544\uc694\ud558\ub2e4. \uacf5\uac1c \uc790\ub8cc\uc758 \uc7a5\uc810\uc740 \ubaa8\ub4e0 \ub2f5\uc744 \uac16\ucd94\uc5c8\ub2e4\ub294 \ub370 \uc788\uc9c0 \uc54a\ub2e4. \ub2e4\ub978 \uc790\ub8cc\uc640 \ub300\uc870\ud558\uba70 \ubb3c\uc744 \uc218 \uc788\ub294 \uc2e4\uc81c \ub300\uc0c1\uc774 \uc0dd\uacbc\ub2e4\ub294 \ub370 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \uc61b \uac1c\uc778\uc6a9 \ucef4\ud4e8\ud130\uc640 \uae30\ub85d \ubcf4\uad00\uc758 \ubd84\uc704\uae30\ub97c \ub2f4\uc740 AI \uc0bd\ud654\uc774\uba70 \uc2e4\uc81c MS-DOS \ud654\uba74\uc744 \uc7ac\ud604\ud55c \uac83\uc774 \uc544\ub2c8\ub2e4. \uc18c\ud504\ud2b8\uc6e8\uc5b4\uc758 \uc815\ud655\ud55c \ub0b4\uc6a9\uc740 \uadf8\ub9bc \uc18d \uac00\uc0c1\uc758 \ud654\uba74 \ub300\uc2e0 \uacf5\uc2dd \uc800\uc7a5\uc18c\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \ub0a1\uc740 \ucef4\ud4e8\ud130\uc758 \uc5ed\uc0ac\ub97c \ub0a8\uae30\ub294 \uc77c\uc740 \ubcf8\uccb4\ub97c \ubc84\ub9ac\uc9c0 \uc54a\ub294 \uac83\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \ud504\ub85c\uadf8\ub7a8\uacfc \uc124\uba85\uc11c, \ub9cc\ub4dc\ub294 \ub370 \uc4f4 \uae30\ub85d\uae4c\uc9c0 \uc11c\ub85c \uc774\uc5b4\uc838\uc57c \ud55c\ub2e4. MS-DOS \uacf5\uac1c \uc790\ub8cc\ub294 \uc6b0\ub9ac\uc5d0\uac8c \ucef4\ud4e8\ud130\uac00 \uc5b4\ub5a4 \ubaa8\uc591\uc774\uc5c8\ub294\uc9c0\ub97c \ub118\uc5b4, \uadf8 \uc548\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5a4 \uc77c\uc744 \uac00\ub2a5\ud558\uac8c \ud588\ub294\uc9c0 \ubb3c\uc744 \uae30\ud68c\ub97c \uc900\ub2e4."}, {"id": "morse-wire-signals-and-distance", "title": "\ubaa8\uc2a4 \u2014 \uc18c\uc2dd\uc740 \uc5b8\uc81c\ubd80\ud130 \uae30\ucc28\ubcf4\ub2e4 \ube68\ub9ac \uac14\uc744\uae4c", "summary": "\ubaa8\uc2a4\uc758 \uc804\uc2e0 \uc2e4\uc6a9\ud654\uc640 \uacf5\uacf5 \uc790\uae08, \uc804\uc120\uacfc \ubd80\ud638\ub97c \ud1b5\ud574 \uc815\ubcf4\uac00 \uc0ac\ub78c\uc758 \uc774\ub3d9\uacfc \ubd84\ub9ac\ub41c \ubcc0\ud654\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\uc778\ud130\ub137\uacfc \ud1b5\uc2e0", "categories": ["digital"], "url": "stories/morse-wire-signals-and-distance/index.html", "image": "../media/morse-wire-signals-and-distance.png", "alt": "\uc804\uc2e0 \uc7a5\uce58\ub97c \ub2e4\ub8e8\ub294 \uc0ac\ub78c\uacfc \ucc3d\ubc16\uc758 \ucca0\uae38\u00b7\uc804\uc120\uc744 \uadf8\ub9b0 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ubaa8\uc2a4 \u2014 \uc18c\uc2dd\uc740 \uc5b8\uc81c\ubd80\ud130 \uae30\ucc28\ubcf4\ub2e4 \ube68\ub9ac \uac14\uc744\uae4c \ud654\uac00\uc758 \uc804\uc2e0 \uc2e4\ud5d8\uacfc 1844\ub144 \uc6cc\uc2f1\ud134\u00b7\ubcfc\ud2f0\ubaa8\uc5b4\uc758 \uc5f0\uacb0 \ubaa8\uc2a4\uc758 \uc804\uc2e0 \uc2e4\uc6a9\ud654\uc640 \uacf5\uacf5 \uc790\uae08, \uc804\uc120\uacfc \ubd80\ud638\ub97c \ud1b5\ud574 \uc815\ubcf4\uac00 \uc0ac\ub78c\uc758 \uc774\ub3d9\uacfc \ubd84\ub9ac\ub41c \ubcc0\ud654\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uc778\ud130\ub137\uacfc \ud1b5\uc2e0 \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \ud3b8\uc9c0\ub97c \ubcf4\ub0c8\ub2e4\uba74 \ub204\uad70\uac00 \uadf8\uac83\uc744 \uc2e4\uc5b4 \ub098\ub974\uae30\ub97c \uae30\ub2e4\ub824\uc57c \ud588\ub2e4. \ub9d0\uacfc \ub9c8\ucc28, \ubc30\uc640 \uae30\ucc28\uac00 \ube68\ub77c\uc9c0\uba74 \uc18c\uc2dd\ub3c4 \ube68\ub9ac \uac14\ub2e4. \uc804\uc2e0\uc740 \uc5ec\uae30\uc5d0\uc11c \ub2e4\ub978 \uae38\uc744 \uc5f4\uc5c8\ub2e4. \ub0b4\uc6a9\uc744 \uc2e0\ud638\ub85c \ubc14\uafb8\uc5b4 \uc804\uc120\uc73c\ub85c \ubcf4\ub0b4\uba74 \ud3b8\uc9c0 \uc790\uccb4\uac00 \uc774\ub3d9\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub418\uc5c8\ub2e4. \uc0c8\ubba4\uc5bc \ubaa8\uc2a4\uc758 \uc774\ub984\uc740 \uadf8 \ubcc0\ud654\uc640 \ud568\uaed8 \ub0a8\uc558\ub2e4. 1844\ub144 \uc6cc\uc2f1\ud134\uacfc \ubcfc\ud2f0\ubaa8\uc5b4\ub97c \uc787\ub294 \uc804\uc2e0\uc120\uc740 \ubbf8\uad6d\uc5d0\uc11c \uc804\uae30 \ud1b5\uc2e0\uc744 \uc2e4\uc6a9\ud654\ud558\ub294 \uc911\uc694\ud55c \uc7a5\uba74\uc774\uc5c8\ub2e4. \uc791\uc740 \uc7a5\uce58\ub9cc\ud07c \ub450 \ub3c4\uc2dc \uc0ac\uc774\uc758 \uae34 \uc120\ub3c4 \uc911\uc694\ud55c \uc774\uc57c\uae30\ub2e4. 1791\ub144 \ub9e4\uc0ac\ucd94\uc138\uce20\uc5d0\uc11c \ud0dc\uc5b4\ub09c \ubaa8\uc2a4\ub294 \uba3c\uc800 \ud654\uac00\ub85c \uc774\ub984\uc744 \uc54c\ub838\ub2e4. \uadf8\uc758 \uacbd\ub825\uc744 \ub098\uc911\uc758 \uc804\uc2e0\uc5d0\uc11c \uac70\uafb8\ub85c\ub9cc \ubcf4\uba74 \uc774 \uc2dc\uac04\uc774 \uc9c0\uc6cc\uc9c4\ub2e4. \uae30\uc220\uc758 \uc5ed\uc0ac\uc5d0\ub3c4 \ub2e4\ub978 \uc77c\uc744 \ud558\ub2e4\uac00 \uc0c8\ub85c\uc6b4 \ubb38\uc81c\uc5d0 \uad00\uc2ec\uc744 \uac16\uac8c \ub41c \uc0ac\ub78c\ub4e4\uc774 \uc788\ub2e4. \uadf8\ub294 1830\ub144\ub300\uc5d0 \uc804\uae30\ub85c \ube60\ub974\uac8c \uc18c\ud1b5\ud558\ub294 \ubc29\ubc95\uc744 \uac1c\ubc1c\ud558\ub294 \ub370 \ud798\uc744 \uc3df\uc558\ub2e4. \ucc98\uc74c\ubd80\ud130 \uc624\ub298\uc758 \ud1b5\uc2e0 \uae30\uae30\ub97c \ub5a0\uc62c\ub9b0 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc804\uae30 \uc2e0\ud638\ub97c \ubcf4\ub0b4\uace0 \ubc1b\uc544\uc11c \uc0ac\ub78c\uc774 \uc77d\uc744 \uc218 \uc788\ub294 \uc758\ubbf8\ub85c \ubc14\uafb8\ub294 \uc2e4\uc81c \ubc29\ubc95\uc774 \ud544\uc694\ud588\ub2e4. \uc804\uc2e0\uc740 \uc0ac\ub78c\uc774 \ud55c \ub9d0\uc744 \uadf8\ub300\ub85c \uba3c \uacf3\uc5d0 \ub4e4\ub824\uc8fc\ub294 \uc804\ud654\uc640 \ub2e4\ub974\ub2e4. \ubcf4\ub0b4\ub824\ub294 \ub0b4\uc6a9\uc744 \ubd80\ud638\ub85c \ubc14\uafb8\uace0 \uc804\uae30 \uc2e0\ud638\ub85c \uc804\ub2ec\ud55c\ub2e4. \ubc1b\ub294 \ucabd\uc740 \uadf8 \uc2e0\ud638\ub97c \ub2e4\uc2dc \uae00\ub85c \uc77d\uc5b4\uc57c \ud55c\ub2e4. \uc591\ucabd\uc774 \uac19\uc740 \uc57d\uc18d\uc744 \uc54c\uc544\uc57c \uc758\ubbf8\uac00 \uc774\uc5b4\uc84c\ub2e4. \uc810\uacfc \uc120\uc73c\ub85c \uce5c\uc219\ud55c \ubd80\ud638 \uc5ed\uc2dc \uc774\ub7f0 \ud544\uc694\uc640 \uc5f0\uacb0\ub41c\ub2e4. \ub2e8\uc21c\ud55c \uc2e0\ud638 \uba87 \uac00\uc9c0\ub97c \uc870\ud569\ud574 \uc5ec\ub7ec \ubb38\uc790\ub97c \ub098\ud0c0\ub0bc \uc218 \uc788\ub2e4. \uc7a5\uce58\uac00 \ubc18\uc751\ud558\ub294 \uac83\ub9cc\uc73c\ub85c\ub294 \ub300\ud654\uac00 \ub418\uc9c0 \uc54a\uc73c\uba70 \uadf8 \ubc18\uc751\uc744 \uc77d\ub294 \uaddc\uce59\uc774 \ud568\uaed8 \uc788\uc5b4\uc57c \ud588\ub2e4. 1838\ub144 \ubaa8\uc2a4\ub294 \uc790\uc2e0\uc758 \ubc29\uc2dd\uc744 \uacf5\uac1c\uc801\uc73c\ub85c \uc2dc\uc5f0\ud588\ub2e4. \uadf8\ub7ec\ub098 \uc0ac\ub78c\ub4e4 \uc55e\uc5d0\uc11c \uc2e0\ud638\uac00 \uc804\ub2ec\ub41c\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc77c\uacfc \uc5ec\ub7ec \ub3c4\uc2dc\uc5d0\uc11c \uacc4\uc18d \uc774\uc6a9\ud560 \uc218 \uc788\uac8c \ub9cc\ub4dc\ub294 \uc77c \uc0ac\uc774\uc5d0\ub294 \uac70\ub9ac\uac00 \uc788\uc5c8\ub2e4. \uc2e4\uc81c \uad6c\uac04\uc5d0 \uc804\uc120\uc744 \ub193\uace0 \uc7a5\ube44\ub97c \uc720\uc9c0\ud558\uba70 \uba54\uc2dc\uc9c0\ub97c \ucc98\ub9ac\ud560 \uc0ac\ub78c\uc774 \ud544\uc694\ud588\ub2e4. \ubc1c\uba85\ud488\uc744 \ubc1b\uce68\ub300 \uc704\uc5d0 \ub193\uc740 \uc0ac\uc9c4\ub9cc \ubcf4\uba74 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc77c\uc774\ub2e4. \ud1b5\uc2e0\uc758 \uc5ed\uc0ac\ub294 \uae30\uacc4\ub97c \ub9cc\ub4dc\ub294 \uacfc\uc815\uacfc \uadf8\uac83\uc744 \uc6b4\uc601\ud560 \ud658\uacbd\uc744 \ub9cc\ub4dc\ub294 \uacfc\uc815\uc774 \ud568\uaed8 \uac04\ub2e4. 1843\ub144 \ubbf8\uad6d \uc758\ud68c\ub294 \uc6cc\uc2f1\ud134\uacfc \ubcfc\ud2f0\ubaa8\uc5b4\ub97c \uc5f0\uacb0\ud560 \uc804\uc2e0\uc120\uc5d0 3\ub9cc \ub2ec\ub7ec\ub97c \ubc30\uc815\ud588\ub2e4. \uba3c \uacf3\uc5d0\uc11c\ub3c4 \uc4f8\ubaa8\uac00 \uc788\ub294\uc9c0 \ud655\uc778\ud558\ub824\uba74 \uc791\uc740 \uc791\uc5c5\uc2e4\uc758 \uc2e4\ud5d8\ubcf4\ub2e4 \uae34 \uc2e4\uc81c \uad6c\uac04\uc774 \ud544\uc694\ud588\ub2e4. \uacf5\uc801 \uc790\uae08\uc740 \uadf8 \uc2dc\ud5d8\uc744 \uac00\ub2a5\ud558\uac8c \ud588\ub2e4. \ud1b5\uc2e0 \uc2dc\uc124\uc758 \ucc98\uc74c\uc744 \ud55c \uc0ac\ub78c\uc758 \uc5f4\uc815\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b4 \uae4c\ub2ed\uc774\ub2e4. \uc0c8\ub85c\uc6b4 \uae30\uc220\uc744 \uc5b4\ub514\uc5d0 \uc2dc\ud5d8\ud558\uace0 \ub204\uac00 \ube44\uc6a9\uc744 \uac10\ub2f9\ud560\uc9c0 \uacb0\uc815\ud558\ub294 \uc815\uce58\uc640 \uc81c\ub3c4\uac00 \uc788\uc5c8\ub2e4. \ubaa8\uc2a4\uc758 \uc7a5\uce58\uac00 \uc54c\ub824\uc9c8 \uae30\ud68c\ub3c4 \uc774\ub7f0 \uc120\ud0dd\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc804\uc2e0\uc120\uc740 \ubcfc\ud2f0\ubaa8\uc5b4\u00b7\uc624\ud558\uc774\uc624 \ucca0\ub3c4 \ub178\uc120\uc744 \ub530\ub77c \ub450 \ub3c4\uc2dc\ub97c \uc5f0\uacb0\ud588\ub2e4. \uc774\ubbf8 \uc0ac\ub78c\uacfc \ubb3c\uac74\uc774 \uc624\uac00\ub294 \uae38 \uc606\uc5d0 \uc2e0\ud638\uc758 \uae38\uc774 \ub193\uc778 \uac83\uc774\ub2e4. \uad50\ud1b5\uacfc \ud1b5\uc2e0\uc740 \ucc98\uc74c\ubd80\ud130 \uc11c\ub85c \uc644\uc804\ud788 \ub5a8\uc5b4\uc9c4 \uc138\uacc4\uac00 \uc544\ub2c8\uc5c8\ub2e4. \uae30\ucc28\uac00 \uc18c\uc2dd\uc744 \uc2e4\uc5b4 \ub098\ub974\ub294 \uc18d\ub3c4\ub97c \ub192\uc600\ub2e4\uba74 \uc804\uc2e0\uc740 \uba54\uc2dc\uc9c0\uc758 \uc774\ub3d9\uc744 \uae30\ucc28\uc758 \ub3c4\ucc29\uacfc \ubd84\ub9ac\ud588\ub2e4. \uc774\uac83\uc774 \uc911\uc694\ud55c \ucc28\uc774\ub2e4. \uc120\uc774 \ub2ff\uc740 \uacf3 \uc0ac\uc774\uc5d0\uc11c\ub294 \uac19\uc740 \ub0b4\uc6a9\uc744 \uc804\ud558\uae30 \uc704\ud574 \ubb3c\ub9ac\uc801\uc778 \ud3b8\uc9c0 \ud55c \uc7a5\uc774 \uad6c\uac04 \uc804\uccb4\ub97c \ub2ec\ub9b4 \ud544\uc694\uac00 \uc904\uc5c8\ub2e4. 1844\ub144 \uc0c8 \uad6c\uac04\uc5d0\uc11c \uba54\uc2dc\uc9c0\uac00 \uc804\ub2ec\ub418\uc5c8\ub2e4. \uc774\uac83\uc744 \uc778\ub958 \ucd5c\ucd08\uc758 \ubaa8\ub4e0 \uc804\uae30 \ud1b5\uc2e0\uc774\ub77c\uace0 \ubd80\ub97c \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\ub978 \uacf3\uc5d0\uc11c\ub3c4 \uc5ec\ub7ec \uc2e4\ud5d8\uacfc \uac1c\ubc1c\uc774 \uc9c4\ud589\ub418\uace0 \uc788\uc5c8\ub2e4. \uc774 \uc0ac\uac74\uc758 \uc758\ubbf8\ub294 \ubbf8\uad6d\uc758 \uad6c\uccb4\uc801\uc778 \uad6c\uac04\uc5d0\uc11c \uc2e4\uc6a9\uc131\uc744 \ubcf4\uc5ec \uc900 \ub370 \uc788\ub2e4. \uc804\uc2e0\uc744 \uc4f8 \uc218 \uc788\ub294 \uc0ac\ub78c\uc740 \uc18c\uc2dd\uc774 \ub3c4\ucc29\ud558\ub294 \uc2dc\uac04\uc744 \ub2e4\ub974\uac8c \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uc5b8\uc81c \uc0ac\ub78c\uc774 \ucd9c\ubc1c\ud558\ub294\uc9c0\ubcf4\ub2e4 \uc120\uc774 \uc5f0\uacb0\ub418\uc5b4 \uc788\uace0 \uba54\uc2dc\uc9c0\ub97c \ucc98\ub9ac\ud560 \uc218 \uc788\ub294\uc9c0\uac00 \uc911\uc694\ud574\uc9c4\ub2e4. \uac70\ub9ac\uac00 \uc815\ubcf4\uc5d0 \uc8fc\ub294 \uc81c\uc57d\uc774 \ub2ec\ub77c\uc9c0\uae30 \uc2dc\uc791\ud588\ub2e4. \uc0ac\uc5c5\uacfc \uc815\uce58, \uc2e0\ubb38\uc758 \uc18c\uc2dd \uc804\ub2ec\uc5d0 \uc0c8\ub85c\uc6b4 \uac00\ub2a5\uc131\uc774 \uc5f4\ub838\ub2e4. \ubb34\uc5c7\uc774 \uc77c\uc5b4\ub0ac\ub294\uc9c0 \uba3c\uc800 \uc544\ub294 \uac83\uc740 \uac00\uaca9\uacfc \ud310\ub2e8, \uc0ac\ub78c\ub4e4\uc758 \ud589\ub3d9\uc5d0 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\ub2e4. \ud1b5\uc2e0 \uc18d\ub3c4\ub294 \ud3b8\ub9ac\ud568\uc744 \ub118\uc5b4 \ud798\uc758 \ucc28\uc774\uc640\ub3c4 \uc5f0\uacb0\ub418\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uac19\uc740 \uc870\uac74\uc73c\ub85c \uc804\uc2e0\uc744 \uc774\uc6a9\ud560 \uc218 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2dc\uc124\uc774 \uc788\ub294 \uacf3\uacfc \uc5c6\ub294 \uacf3, \ube44\uc6a9\uacfc \uc6b4\uc601 \uc2dc\uac04, \uba54\uc2dc\uc9c0\ub97c \ucc98\ub9ac\ud558\ub294 \uc0ac\ub78c\uc758 \uc218\uac00 \uacbd\ud5d8\uc744 \ubc14\uafb8\uc5c8\ub2e4. \uc18d\ub3c4\uac00 \ube68\ub77c\uc84c\ub2e4\ub294 \ud55c \ubb38\uc7a5 \uc548\uc5d0\ub3c4 \uc811\uadfc\uc758 \ucc28\uc774\uac00 \uc788\uc5c8\ub2e4. \uc804\uc2e0\uc774 \uc18c\uc2dd\uc744 \ube60\ub974\uac8c \ub9cc\ub4e4\uc5c8\ub2e4\uace0 \uc804\ub2ec \uacfc\uc815\uc5d0\uc11c \uc0ac\ub78c\uc774 \uc0ac\ub77c\uc9c4 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub0b4\uc6a9\uc744 \ubd80\ud638\ub85c \ub9cc\ub4e4\uace0 \ubc1b\uc544 \uc801\uc73c\uba70 \uc798\ubabb \uc77d\uc9c0 \uc54a\uc558\ub294\uc9c0 \uc0b4\ud53c\ub294 \uc77c\uc774 \ud544\uc694\ud588\ub2e4. \uc7a5\uce58\uc758 \uc815\ud655\ud568\uacfc \uc6b4\uc601\uc790\uc758 \uae30\uc220\uc774 \ud568\uaed8 \uc791\ub3d9\ud574\uc57c \ud588\ub2e4. \ub530\ub77c\uc11c \uc790\ub3d9\uc73c\ub85c \ubaa8\ub4e0 \uc758\ubbf8\uac00 \uc804\ub2ec\ub418\ub294 \uae30\uacc4\ucc98\ub7fc \uc0dd\uac01\ud558\uba74 \ub2f9\uc2dc\uc758 \uacbd\ud5d8\uc744 \ub193\uce5c\ub2e4. \ube68\ub77c\uc9c4 \uac83\uc740 \uba54\uc2dc\uc9c0\uac00 \uad6c\uac04\uc744 \uac74\ub108\ub294 \ubc29\uc2dd\uc774\uc5c8\ub2e4. \ubb34\uc5c7\uc744 \ubcf4\ub0b4\uace0 \uc5b4\ub5bb\uac8c \uc77d\uc73c\uba70 \ub204\uad6c\uc5d0\uac8c \uc804\ub2ec\ud560\uc9c0\uc5d0\ub294 \uc5ec\uc804\ud788 \uc0ac\ub78c\uc758 \ud310\ub2e8\uacfc \uaddc\uce59\uc774 \uc788\uc5c8\ub2e4. \uc804\uc2e0\uc744 \uc778\ud130\ub137\uacfc \uac19\uc740 \uae30\uc220\uc774\ub77c\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc5f0\uacb0 \ubc29\uc2dd\uacfc \uc7a5\uce58, \uc6b4\uc6a9\uc758 \uccb4\uacc4\uac00 \ud06c\uac8c \ub2e4\ub974\ub2e4. \ub2e4\ub9cc \uba40\ub9ac \uc788\ub294 \uc0ac\ub78c\uc5d0\uac8c \ub0b4\uc6a9\uc744 \uc804\ub2ec\ud558\ub824\uba74 \ubb34\uc5c7\uc744 \uc2e0\ud638\ub85c \ub9cc\ub4e4\uace0 \uc5b4\ub5a4 \uc57d\uc18d\uc744 \ud568\uaed8 \uc368\uc57c \ud558\ub294\uc9c0\ub77c\ub294 \uc9c8\ubb38\uc740 \ube44\uad50\ud574 \ubcfc \uc218 \uc788\ub2e4. \ubaa8\uc2a4\uc758 \uc774\uc57c\uae30\ub97c \uc791\uc740 \uc804\uc2e0\uae30 \ud558\ub098\uc5d0\uc11c \ub05d\ub0b4\uc9c0 \ub9d0\uace0 \ucc3d\ubc16\uc758 \uc804\uc120\uacfc \ucca0\uae38\uae4c\uc9c0 \ub113\ud600 \ubcf4\uc790. \ube60\ub978 \uc18c\uc2dd\uc740 \uc7a5\uce58\uc640 \ubd80\ud638, \ube44\uc6a9\uc744 \ub304 \uc81c\ub3c4\uc640 \uc6b4\uc601\uc790\uc758 \uc77c\uc774 \ub9cc\ub0a0 \ub54c \uac00\ub2a5\ud588\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \ubc84\ud2bc \ub4a4\uc5d0\ub3c4 \uae34 \uae38\uc774 \uc788\uc5c8\ub2e4."}, {"id": "ocr-picture-to-searchable-text", "title": "\ubb38\uc790\uc778\uc2dd \u2014 \uc0ac\uc9c4 \uc18d \uae00\uc790\ub294 \uc65c \ubcf5\uc0ac\uac00 \uc548 \ub420\uae4c", "summary": "\uc2a4\uce94 \uc774\ubbf8\uc9c0\uc640 \ud14d\uc2a4\ud2b8\uc758 \ucc28\uc774\uc5d0\uc11c \ucd9c\ubc1c\ud574 OCR\uc758 \uc4f0\uc784\uacfc \uc624\ub958\u00b7\uac80\ud1a0\uc758 \ud544\uc694\uc131\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\ub370\uc774\ud130\uc640 \uae30\ub85d", "categories": ["digital"], "url": "stories/ocr-picture-to-searchable-text/index.html", "image": "../media/ocr-picture-to-searchable-text.png", "alt": "\uc624\ub798\ub41c \ucc45 \uacc1\uc5d0\uc11c \uc778\uc1c4 \ud398\uc774\uc9c0\uc640 \uc2a4\uce90\ub108\ub97c \uc0b4\ud3b4\ubcf4\ub294 \uc0ac\ub78c\uc758 AI \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ubb38\uc790\uc778\uc2dd \u2014 \uc0ac\uc9c4 \uc18d \uae00\uc790\ub294 \uc65c \ubcf5\uc0ac\uac00 \uc548 \ub420\uae4c \ub208\uc73c\ub85c \uc77d\ub294 \ud398\uc774\uc9c0\ub97c \ucef4\ud4e8\ud130\uac00 \ucc3e\uc744 \uc218 \uc788\ub294 \uae00\ub85c \ubc14\uafb8\uae30 \uc2a4\uce94 \uc774\ubbf8\uc9c0\uc640 \ud14d\uc2a4\ud2b8\uc758 \ucc28\uc774\uc5d0\uc11c \ucd9c\ubc1c\ud574 OCR\uc758 \uc4f0\uc784\uacfc \uc624\ub958\u00b7\uac80\ud1a0\uc758 \ud544\uc694\uc131\uc744 \uc774\ud574\ud569\ub2c8\ub2e4. \ub370\uc774\ud130\uc640 \uae30\ub85d \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \uc624\ub798\ub41c \uc2e0\ubb38\uc744 \uc2a4\uce94\ud574 \ud654\uba74\uc73c\ub85c \uc5f4\uc5c8\ub2e4. \uae00\uc790\ub294 \ub610\ub837\ud55c\ub370 \ubb38\uc7a5\uc744 \ub04c\uc5b4 \uc120\ud0dd\ud558\ub824 \ud558\uba74 \ud398\uc774\uc9c0 \uc804\uccb4\uac00 \uc6c0\uc9c1\uc778\ub2e4. \uc0ac\ub78c\uc5d0\uac8c\ub294 \ubd84\uba85 \uae00\uc778\ub370 \ucef4\ud4e8\ud130\uc5d0\ub294 \uc65c \ubcf5\uc0ac\ud560 \uc218 \uc788\ub294 \ubb38\uc7a5\uc73c\ub85c \ubcf4\uc774\uc9c0 \uc54a\uc744\uae4c. \ub2f5\uc740 \uac19\uc740 \ubaa8\uc591\uc774 \uc11c\ub85c \ub2e4\ub978 \uc815\ubcf4\uc77c \uc218 \uc788\ub2e4\ub294 \ub370 \uc788\ub2e4. \uc0ac\uc9c4\uc5d0\ub294 \uae00\uc790 \ubaa8\uc591\uc758 \ud53d\uc140\uc774 \uc788\uace0, \ud14d\uc2a4\ud2b8\uc5d0\ub294 \uc5b4\ub5a4 \uae00\uc790\uc778\uc9c0 \uad6c\ubcc4\ud558\ub294 \uc815\ubcf4\uac00 \uc788\ub2e4. OCR, \uc989 \uad11\ud559 \ubb38\uc790 \uc778\uc2dd\uc740 \uc774\ubbf8\uc9c0\uc5d0\uc11c \uae00\uc790\ub97c \ucc3e\uc544 \ucef4\ud4e8\ud130\uac00 \ub2e4\ub8f0 \uc218 \uc788\ub294 \ud14d\uc2a4\ud2b8\ub85c \uc62e\uae30\ub294 \uae30\uc220\uc774\ub2e4. \uc885\uc774 \ubb38\uc11c\uac00 \uac80\uc0c9 \uac00\ub2a5\ud55c \uc790\ub8cc\uac00 \ub418\ub294 \uae38\ubaa9\uc5d0 \uc788\ub2e4. \uc885\uc774\uc5d0 \uc778\uc1c4\ub41c \uc774\ub984\uc744 \ucd2c\uc601\ud558\uba74 \uc0ac\uc9c4 \ud30c\uc77c\uc5d0\ub294 \ubc1d\uae30\uc640 \uc0c9\uc758 \ubc30\uc5f4\uc774 \ub4e4\uc5b4\uac04\ub2e4. \uc0ac\ub78c\uc740 \uc775\uc219\ud55c \ubaa8\uc591\uc5d0\uc11c \uae00\uc790\ub97c \uc77d\uc9c0\ub9cc, \ud30c\uc77c \uc790\uccb4\uac00 \uc774\ub984\uc758 \ucca0\uc790\ub97c \ubb38\uc790 \ub370\uc774\ud130\ub85c \uac16\uace0 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc778\uc1c4\ubb3c\uc744 \uc2a4\uce94\ud588\ub2e4\uace0 \uc790\ub3d9\uc73c\ub85c \uc6cc\ub4dc\ud504\ub85c\uc138\uc11c \ubb38\uc11c\uac00 \ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubc18\ub300\ub85c \ucc98\uc74c\ubd80\ud130 \ucef4\ud4e8\ud130\uc5d0\uc11c \uc791\uc131\ud55c PDF\uc5d0\ub294 \ud14d\uc2a4\ud2b8\uc640 \uae00\uaf34 \uc815\ubcf4\uac00 \ub4e4\uc5b4 \uc788\uc744 \uc218 \uc788\ub2e4. \uac19\uc740 PDF \ud655\uc7a5\uc790\ub77c\ub3c4 \ud55c\ucabd\uc740 \ud398\uc774\uc9c0 \uc774\ubbf8\uc9c0\uac00 \uc911\uc2ec\uc774\uace0 \ub2e4\ub978 \ucabd\uc740 \uc2e4\uc81c \ud14d\uc2a4\ud2b8\ub97c \ud3ec\ud568\ud55c\ub2e4. \uac89\ubaa8\uc2b5\ub9cc \ube44\uc2b7\ud558\ub2e4\uace0 \ub0b4\ubd80\uc5d0\uc11c \ud560 \uc218 \uc788\ub294 \uc791\uc5c5\uae4c\uc9c0 \uac19\uc9c0\ub294 \uc54a\ub2e4. OCR\uc740 \uc6d0\ub798 \uae00\uc744 \ub2e4\ub978 \uc5b8\uc5b4\ub85c \ubc14\uafb8\ub294 \uc791\uc5c5\uc774 \uc544\ub2c8\ub2e4. \uc774\ubbf8\uc9c0 \uc18d \ubaa8\uc591\uc744 \uc5b4\ub5a4 \ubb38\uc790\ub85c \uc77d\uc744\uc9c0 \uc54c\uc544\ub0b4\ub824\ub294 \uc791\uc5c5\uc774\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc885\uc774\uc5d0 \uc4f0\uc778 \uc11c\uc6b8\uc774\ub77c\ub294 \ub450 \uae00\uc790\ub97c \uc11c\uc6b8\uc774\ub77c\ub294 \ud14d\uc2a4\ud2b8\ub85c \uc62e\uae30\ub294 \uac83\uc774 \uba3c\uc800\ub2e4. \uadf8 \ub73b\uc744 \uc601\uc5b4\ub85c \uc804\ub2ec\ud558\ub294 \ubc88\uc5ed\uc740 \ub2e4\ub978 \ub2e8\uacc4\ub2e4. \ubb3c\ub860 \uc778\uc2dd\uc5d0\ub294 \uc5b8\uc5b4\uc640 \ubb38\ub9e5\uc5d0 \uad00\ud55c \uc815\ubcf4\uac00 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\ub2e4. Tesseract\uc758 \ubb38\uc11c\ub294 \uc0ac\uc804\uacfc \ub2e8\uc5b4 \ubaa9\ub85d, \uc5b8\uc5b4 \uc124\uc815\uc774 \uacb0\uacfc\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud615\ud0dc\ub9cc \ud558\ub098\uc529 \uc644\ubcbd\ud558\uac8c \ud310\ub3c5\ud558\uba74 \ub05d\ub098\ub294 \ubb38\uc81c\ub77c\uae30\ubcf4\ub2e4, \uc774\ubbf8\uc9c0\uc640 \ubb38\uc790 \uccb4\uacc4\uc758 \uc870\uac74\uc774 \ud568\uaed8 \uad00\uc5ec\ud55c\ub2e4. \ud750\ub9bf\ud55c \ucd08\uc810\uacfc \uc5bc\ub8e9, \ubc30\uacbd\uc758 \uadf8\ub9bc\uc790\ub294 \uc778\uc2dd\uc744 \uc5b4\ub835\uac8c \ud560 \uc218 \uc788\ub2e4. \uae30\uc6b8\uc5b4\uc9c4 \uc904\uc774\ub098 \uc9c0\ub098\uce58\uac8c \uc791\uac8c \ucd2c\uc601\ub41c \uae00\uc790\ub3c4 \uc601\ud5a5\uc744 \uc900\ub2e4. \uc0ac\ub78c\uc774\ub77c\uba74 \uc8fc\ubcc0 \ub0b4\uc6a9\uc744 \ubcf4\uace0 \ucd94\uce21\ud574 \ub118\uc5b4\uac08 \ubd80\ubd84\uc5d0\uc11c \ud504\ub85c\uadf8\ub7a8\uc740 \ub2e4\ub978 \uae00\uc790\ub97c \ub0b4\ub193\uc744 \uc218 \uc788\ub2e4. Tesseract\uc758 \uacf5\uc2dd \uc548\ub0b4\ub294 \ud574\uc0c1\ub3c4\uc640 \uae30\uc6b8\uae30 \ubcf4\uc815, \ubd88\uade0\uc77c\ud55c \ubc30\uacbd\uacfc \uc7a1\uc74c \ub4f1\uc744 \ub2e4\ub8ec\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4\uc744 \ud06c\uac8c \ub298\ub9ac\uae30\ub9cc \ud558\uba74 \ubaa8\ub4e0 \uc815\ubcf4\uac00 \ub418\uc0b4\uc544\ub098\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ucc98\uc74c\ubd80\ud130 \uae00\uc790\uc758 \uc138\ubd80\uac00 \ucda9\ubd84\ud788 \ub0a8\ub3c4\ub85d \uc900\ube44\ud558\ub294 \uac83\uacfc \ub098\uc911\uc5d0 \ud654\uba74\uc744 \ud655\ub300\ud558\ub294 \uac83\uc740 \ub2e4\ub978 \ubb38\uc81c\ub2e4. \uc61b \uc2e0\ubb38\ucc98\ub7fc \ud55c \ud398\uc774\uc9c0\uc5d0 \uc5ec\ub7ec \ub2e8\uc774 \uc788\ub294 \uc790\ub8cc\ub294 \uae00\uc790\ub9cc \uc54c\uc544\ubcf4\uc544\uc11c\ub294 \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4. \uc5b4\ub290 \uc904 \ub2e4\uc74c\uc5d0 \uc5b4\ub290 \uc904\uc744 \uc77d\uc5b4\uc57c \ud558\ub294\uc9c0\ub3c4 \ud30c\uc545\ud574\uc57c \ud55c\ub2e4. \uc67c\ucabd \ub2e8\uc758 \uc911\uac04\uacfc \uc624\ub978\ucabd \ub2e8\uc758 \uc911\uac04\uc744 \uc774\uc5b4 \ubd99\uc774\uba74 \uae00\uc790\ub294 \ub9de\uc544\ub3c4 \ubb38\uc7a5\uc740 \uc774\uc0c1\ud574\uc9c4\ub2e4. \ud45c\uc5d0\uc11c\ub3c4 \uc22b\uc790\uc640 \uc81c\ubaa9\uc758 \uad00\uacc4\uac00 \uc911\uc694\ud558\ub2e4. \uac12 \uc790\uccb4\ub97c \uc81c\ub300\ub85c \uc77d\uc5b4\ub3c4 \ub2e4\ub978 \ud589\uc5d0 \ubd99\uc774\uba74 \ub73b\uc774 \ub2ec\ub77c\uc9c4\ub2e4. OCRmyPDF\ub294 \ubb38\uc11c\uc758 \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \uc77d\uae30 \uc21c\uc11c\uc5d0 \ud55c\uacc4\uac00 \uc788\uc744 \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc798 \uc77d\ud788\ub294 \uae00\uc790\uc640 \uc81c\ub300\ub85c \uc774\ud574\ud560 \uc218 \uc788\ub294 \ubb38\uc11c \uad6c\uc870\ub294 \ubcc4\ub3c4\uc758 \uc5b4\ub824\uc6c0\uc744 \uac16\ub294\ub2e4. OCRmyPDF \uac19\uc740 \ub3c4\uad6c\ub294 \uc2a4\uce94\ud55c PDF\uc5d0 \uc778\uc2dd\ud55c \ud14d\uc2a4\ud2b8 \uce35\uc744 \ub354\ud55c\ub2e4. \ud654\uba74\uc5d0\ub294 \uae30\uc874\uc758 \ud398\uc774\uc9c0 \ubaa8\uc2b5\uc774 \ubcf4\uc774\uba74\uc11c \uac80\uc0c9\uacfc \uc120\ud0dd\uc5d0 \uc0ac\uc6a9\ud560 \uae00\uc790 \uc815\ubcf4\uac00 \ud568\uaed8 \ub4e4\uc5b4\uac08 \uc218 \uc788\ub2e4. \uc774\ubbf8\uc9c0\ub97c \uc804\ubd80 \uc0c8 \ud65c\uc790\ub85c \ub2e4\uc2dc \uc870\ud310\ud558\uc9c0 \uc54a\uc544\ub3c4 \ucc3e\uc744 \uc218 \uc788\uac8c \ub9cc\ub4dc\ub294 \ubc29\uc2dd\uc774\ub2e4. \uadf8\ub798\uc11c \uac80\uc0c9\uc774 \ub41c\ub2e4\uace0 \ubb38\uc11c \uc804\uccb4\uac00 \uc790\uc720\ub86d\uac8c \ud3b8\uc9d1\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac80\uc0c9\uc744 \uc704\ud55c \uae00\uc790 \uc815\ubcf4\uac00 \uc0dd\uacbc\ub2e4\ub294 \uac83\uacfc \uc6d0\ub798\uc758 \ud45c\u00b7\ubb38\ub2e8\u00b7\uc11c\uccb4\ub97c \uc644\ubcbd\ud558\uac8c \ubcf5\uc6d0\ud588\ub2e4\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uc5b4\ub5a4 \uae30\ub2a5\uc774 \ucd94\uac00\ub418\uc5c8\ub294\uc9c0 \uad6c\ubcc4\ud558\uba74 \uacb0\uacfc\ub97c \ub354 \uc54c\ub9de\uac8c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4. \uc778\uc2dd\uc774 \ud2c0\ub9ac\uba74 \ud398\uc774\uc9c0\uc5d0 \uc2e4\uc81c\ub85c \uc788\ub294 \ub2e8\uc5b4\ub97c \uac80\uc0c9\uc73c\ub85c \ucc3e\uc9c0 \ubabb\ud560 \uc218 \uc788\ub2e4. \uc624\ub798\ub41c \uc2e0\ubb38\uc5d0\uc11c \ud2b9\uc815 \uc774\ub984\uc774 \uc548 \ub098\uc628\ub2e4\uace0 \uace7\ubc14\ub85c \uae30\ub85d\uc774 \uc5c6\uc5c8\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218 \uc5c6\ub294 \uc774\uc720\ub2e4. \uac80\uc0c9\uc740 \ub9ce\uc740 \uc790\ub8cc\ub97c \ube68\ub9ac \uc0b4\ud53c\uac8c \ud558\uc9c0\ub9cc \uadf8 \uae30\ubc18\uc774 \ub418\ub294 \ud14d\uc2a4\ud2b8\uc5d0 \uc624\ub958\uac00 \uc788\uc744 \uc218 \uc788\ub2e4. \ubc18\ub300\ub85c \ube44\uc2b7\ud55c \ubaa8\uc591\uc744 \uc798\ubabb \uc77d\uc5b4\uc11c \uc5c6\ub358 \ub2e8\uc5b4\uac00 \uc0dd\uae38 \uc218\ub3c4 \uc788\ub2e4. \uc778\uc6a9\ud558\uac70\ub098 \uc0ac\uc2e4\uc744 \ud655\uc778\ud560 \ub54c\ub294 \ud574\ub2f9 \ud398\uc774\uc9c0\uc758 \uc6d0\ub798 \ubaa8\uc2b5\uc744 \ud568\uaed8 \ub300\uc870\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4. \ud3b8\ub9ac\ud574\uc9c4 \ucc3e\uae30 \uae30\ub2a5\uc774 \uadfc\uac70 \ud655\uc778\uc744 \ub300\uc2e0\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \ud655\uc778\ud560 \uc790\ub9ac\ub97c \ub354 \ube68\ub9ac \ucc3e\uc544 \uc8fc\ub294 \uc5ed\ud560\uc744 \ud55c\ub2e4. \uc790\ub8cc\ub97c \ub514\uc9c0\ud138\ud654\ud560 \ub54c\ub294 \uc2a4\uce94\ud55c \uc774\ubbf8\uc9c0\uc640 \uc778\uc2dd \uacb0\uacfc\ub97c \uad6c\ubd84\ud574 \ubcf4\uad00\ud558\uace0 \ud2c0\ub9b0 \uae00\uc790\ub97c \uac80\ud1a0\ud558\ub294 \uacfc\uc815\uc774 \ud544\uc694\ud560 \uc218 \uc788\ub2e4. \uae30\uc220\uc774 \ubb38\uc790\ub97c \uc790\ub3d9\uc73c\ub85c \ub0b4\ub193\ub294 \uc77c\uacfc \ubbff\uace0 \uc778\uc6a9\ud560 \uc218 \uc788\ub294 \uc790\ub8cc\ub97c \ub9cc\ub4dc\ub294 \uc77c \uc0ac\uc774\uc5d0\ub294 \ud3b8\uc9d1\uc774 \ub0a8\ub294\ub2e4. \uc774 \uae00\uc5d0\uc11c \ucc38\uace0\ud55c Tesseract\uc640 OCRmyPDF\ub294 \uc778\uc1c4 \ubb38\uc790\ub97c \uc911\uc2ec\uc73c\ub85c \uc124\uba85\ud55c \uacf5\uac1c \ub3c4\uad6c\ub4e4\uc774\ub2e4. OCR\uc774\ub77c\ub294 \ub113\uc740 \ubd84\uc57c \uc804\uccb4\uc758 \uc131\ub2a5\uc744 \ud55c \ud504\ub85c\uadf8\ub7a8\uc758 \uacb0\uacfc\ub85c \ud310\ub2e8\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud2b9\ud788 \uc190\uae00\uc528\ub098 \ubcf5\uc7a1\ud55c \ubb38\uc11c\uac00 \uac19\uc740 \uc218\uc900\uc73c\ub85c \uc77d\ud78c\ub2e4\uace0 \uae30\ub300\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ub300\uc0c1\uacfc \ub3c4\uad6c\uc5d0 \ub530\ub77c \uac00\ub2a5\ud55c \ubc94\uc704\uac00 \ub2e4\ub974\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc2a4\uce90\ub108\uc640 \uc624\ub798\ub41c \ucc45\uc744 \uc0b4\ud53c\ub294 \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c \uc7a5\ube44 \uc0ac\uc6a9 \uc21c\uc11c\ub97c \uac00\ub974\uce58\uac70\ub098 \uc778\uc2dd \uc804\ud6c4\uc758 \uc815\ud655\ub3c4\ub97c \ube44\uad50\ud55c \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \uc885\uc774\uc758 \ubaa8\uc2b5\uacfc \uac80\uc0c9 \uac00\ub2a5\ud55c \uae00\uc744 \ud568\uaed8 \ubcf4\uc874\ud558\ub824\ub294 \uc791\uc5c5\uc758 \ubd84\uc704\uae30\ub97c \ub2f4\uc558\ub2e4. \ubb38\uc790\uc778\uc2dd\uc758 \ub9e4\ub825\uc740 \uc0ac\ub78c \ub300\uc2e0 \ucc45\uc744 \uc644\ubcbd\ud558\uac8c \uc774\ud574\ud55c\ub2e4\ub294 \ub370 \uc788\uc9c0 \uc54a\ub2e4. \ub208\uc73c\ub85c\ub9cc \ub118\uae30\ub358 \ub9ce\uc740 \ud398\uc774\uc9c0\uc5d0\uc11c \ud544\uc694\ud55c \ub9d0\uc758 \uc704\uce58\ub97c \ucc3e\ub3c4\ub85d \ub3d5\ub294 \ub370 \uc788\ub2e4. \uadf8\ub9ac\uace0 \uadf8 \uc790\ub9ac\ub97c \ucc3e\uc740 \ub4a4 \ub2e4\uc2dc \uc6d0\ubcf8\uc744 \uc77d\ub294 \uc21c\uac04, \uae30\uacc4\uc758 \ud3b8\ub9ac\ud568\uacfc \uc0ac\ub78c\uc758 \uac80\ud1a0\uac00 \uac19\uc740 \uc791\uc5c5 \uc548\uc5d0\uc11c \ub9cc\ub09c\ub2e4."}, {"id": "png-transparent-background", "title": "PNG \u2014 \ubc30\uacbd\uc774 \uc5c6\ub294 \uadf8\ub9bc\uc740 \uc5b4\ub5bb\uac8c \uac00\ub2a5\ud55c\uac00", "summary": "\ub514\uc9c0\ud138 \uc774\ubbf8\uc9c0\uc758 \ud22c\uba85\ub3c4\uc640 \ubb34\uc190\uc2e4 \uc555\ucd95\uc744 \ud1b5\ud574 \ud30c\uc77c \ud615\uc2dd\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c0\ub294 \uadf8\ub9bc\uc758 \uc131\uc9c8\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\ub370\uc774\ud130\uc640 \uae30\ub85d", "categories": ["digital"], "url": "stories/png-transparent-background/index.html", "image": "../media/png-transparent-background.png", "alt": "\uc78e \ubaa8\uc591\uc774 \ubd99\uc740 \ud22c\uba85\ud55c \ud310 \ub4a4\ub85c \ud30c\ub780 \uc0c9\uc9c0\uac00 \ubcf4\uc774\ub294 \uc791\uc5c5\uc2e4\uc758 AI \ube44\uc720 \uc7a5\uba74.", "text": "PNG \u2014 \ubc30\uacbd\uc774 \uc5c6\ub294 \uadf8\ub9bc\uc740 \uc5b4\ub5bb\uac8c \uac00\ub2a5\ud55c\uac00 \ud770\uc0c9\uc744 \uc9c0\uc6b4 \uac83\uacfc \ud22c\uba85\ud55c \uac83\uc740 \ub2e4\ub974\ub2e4 \ub514\uc9c0\ud138 \uc774\ubbf8\uc9c0\uc758 \ud22c\uba85\ub3c4\uc640 \ubb34\uc190\uc2e4 \uc555\ucd95\uc744 \ud1b5\ud574 \ud30c\uc77c \ud615\uc2dd\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c0\ub294 \uadf8\ub9bc\uc758 \uc131\uc9c8\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ub370\uc774\ud130\uc640 \uae30\ub85d \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \uc791\uc740 \uadf8\ub9bc\uc744 \ubb38\uc11c\uc5d0 \ub123\uc5c8\ub294\ub370 \ud770 \ub124\ubaa8\uac00 \ub530\ub77c\uc628\ub2e4. \ubd84\uba85 \ud770 \uc885\uc774 \uc704\uc5d0\uc11c\ub294 \ubc30\uacbd\uc774 \uc5c6\ub294 \uac83\ucc98\ub7fc \ubcf4\uc600\ub294\ub370, \ud30c\ub780 \ubc14\ud0d5 \uc704\uc5d0 \uc62c\ub9ac\uc790 \ub124\ubaa8\uc758 \uc724\uacfd\uc774 \uc120\uba85\ud558\ub2e4. \uadf8\ub9bc\uc758 \uc0c9\uc740 \ub9de\ub294\ub370 \uc5b4\uca50\uc9c0 \uc624\ub824 \ubd99\uc778 \uc790\uad6d\uc774 \ub0a8\ub294 \uac83\uc774\ub2e4. \ubc18\uba74 \uc5b4\ub5a4 \ud30c\uc77c\uc740 \ub098\ubb47\uc78e\uc774\ub098 \ub85c\uace0\uc758 \ubaa8\uc591\ub9cc \uae54\ub054\ud558\uac8c \ub193\uc778\ub2e4. \uc8fc\ubcc0\uc758 \ubc14\ud0d5\uc0c9\uc774 \uadf8\ub300\ub85c \ub4dc\ub7ec\ub09c\ub2e4. \uc774 \ucc28\uc774\ub97c \uc774\ud574\ud560 \ub54c \uc790\uc8fc \ub9cc\ub098\ub294 \uc774\ub984\uc774 PNG\ub2e4. \uadf8\ub9bc\uc744 \uc608\uc058\uac8c \ub9cc\ub4dc\ub294 \ub9c8\ubc95\uc774\ub77c\uae30\ubcf4\ub2e4, \uc0c9\uacfc \ud568\uaed8 \ubb34\uc5c7\uc744 \uc5bc\ub9c8\ub098 \ub4dc\ub7ec\ub0bc\uc9c0\ub3c4 \uc800\uc7a5\ud560 \uc218 \uc788\ub294 \ud30c\uc77c \ud615\uc2dd\uc774\ub2e4. \ub514\uc9c0\ud138 \uadf8\ub9bc\uc740 \uc791\uc740 \uc810, \uc989 \ud53d\uc140\ub4e4\uc758 \uac12\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c4\ub2e4. \ubc30\uacbd\uc774 \ud770\uc0c9\uc774\ub77c\ub294 \uac83\uc740 \uadf8 \uc790\ub9ac\uc5d0 \uc544\ubb34 \uc815\ubcf4\ub3c4 \uc5c6\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \ud770\uc0c9\uc73c\ub85c \ud45c\uc2dc\ud558\ub77c\ub294 \uc0c9 \uc815\ubcf4\uac00 \ub4e4\uc5b4 \uc788\ub294 \uac83\uc774\ub2e4. \uadf8\ub798\uc11c \ub2e4\ub978 \uc0c9 \ubc14\ud0d5 \uc704\uc5d0 \ub193\uc544\ub3c4 \uadf8 \ubd80\ubd84\uc740 \uacc4\uc18d \ud558\uc597\uac8c \ub0a8\ub294\ub2e4. \ud22c\uba85\uc740 \ub2e4\ub978 \uc870\uac74\uc774\ub2e4. \uadf8 \uc704\uce58\uc5d0\uc11c \uc544\ub798\ucabd\uc5d0 \ub193\uc778 \ub0b4\uc6a9\uc744 \uc5bc\ub9c8\ub098 \ubcf4\uc5ec \uc904\uc9c0\uc640 \uad00\uacc4\uac00 \uc788\ub2e4. \ud770\uc0c9 \ubb3c\uac10\uc744 \uce60\ud55c \uc720\ub9ac\uc640 \uc544\ubb34\uac83\ub3c4 \uce60\ud558\uc9c0 \uc54a\uc740 \uc720\ub9ac\ub97c \ube44\uad50\ud574 \ubcf4\uba74 \uc27d\ub2e4. \ub458 \ub2e4 \ubc1d\uac8c \ubcf4\uc77c \uc218 \uc788\uc9c0\ub9cc \ub4a4\uc5d0 \uc0c9\uc9c0\ub97c \ub300\ub294 \uc21c\uac04 \uc11c\ub85c \ub2e4\ub974\uac8c \ubcf4\uc778\ub2e4. \uc774\ubbf8\uc9c0\uc758 \ud53d\uc140\uc5d0\ub294 \ube68\uac15\u00b7\ucd08\ub85d\u00b7\ud30c\ub791\uc758 \uc815\ub3c4\ub97c \ub098\ud0c0\ub0b4\ub294 \uc815\ubcf4\uac00 \ub4e4\uc5b4\uac08 \uc218 \uc788\ub2e4. \uc5ec\uae30\uc5d0 \ubd88\ud22c\uba85\ub3c4\ub97c \ub098\ud0c0\ub0b4\ub294 \uc54c\ud30c \uac12\uc774 \ub354\ud574\uc9c0\uba74, \uadf8 \ud53d\uc140\uc774 \uc5bc\ub9c8\ub098 \uac00\ub824 \ubcf4\uc77c\uc9c0 \ud45c\ud604\ud560 \uc218 \uc788\ub2e4. PNG\ub294 \uc774\ub7f0 \ud22c\uba85\ub3c4 \ud45c\ud604\uc744 \uc9c0\uc6d0\ud55c\ub2e4. \uc54c\ud30c\uac00 \uc644\uc804\ud788 \ud22c\uba85\ud55c \uac12\uc774\ub77c\uba74 \ubc14\ud0d5\uc774 \ub4dc\ub7ec\ub098\uace0, \uc644\uc804\ud788 \ubd88\ud22c\uba85\ud55c \uac12\uc774\ub77c\uba74 \uc774\ubbf8\uc9c0\uc758 \uc0c9\uc774 \ubcf4\uc778\ub2e4. \uadf8 \uc0ac\uc774\uc758 \uac12\uc740 \ub450 \ubaa8\uc2b5\uc774 \uc11e\uc774\ub3c4\ub85d \ud55c\ub2e4. \ubcf5\uc7a1\ud55c \uacc4\uc0b0\uc2dd\ubcf4\ub2e4 \uc587\uc740 \uc0c9\uc885\uc774\uc640 \uc9d9\uac8c \uce60\ud55c \uc885\uc774\ub97c \ub5a0\uc62c\ub9ac\uba74, \ub2e8\uc21c\ud788 \ubcf4\uc774\uac70\ub098 \uc548 \ubcf4\uc774\ub294 \ub450 \uc0c1\ud0dc\ub9cc \ud544\uc694\ud55c \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc744 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uace1\uc120\uc73c\ub85c \ub41c \ub098\ubb47\uc78e\uc744 \ud654\uba74\uc5d0 \ub193\ub294\ub2e4\uace0 \uc0dd\uac01\ud574 \ubcf4\uc790. \ud53d\uc140\uc740 \ub124\ubaa8\uc778\ub370 \uc724\uacfd\uc740 \ube44\uc2a4\ub4ec\ud558\uace0 \ub465\uae00\ub2e4. \uacbd\uacc4\uc758 \uc810\ub4e4\uc744 \ubaa8\ub450 \uc644\uc804\ud788 \ubcf4\uc774\uac70\ub098 \uc548 \ubcf4\uc774\uac8c\ub9cc \uc815\ud558\uba74 \uacc4\ub2e8\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\ub2e4. \uc911\uac04 \ud22c\uba85\ub3c4\ub294 \uc774\ub7f0 \uacbd\uacc4\uac00 \ubc30\uacbd\uacfc \ubd80\ub4dc\ub7fd\uac8c \uc774\uc5b4\uc9c0\ub3c4\ub85d \ud45c\ud604\ud558\ub294 \ub370 \uc4f0\uc77c \uc218 \uc788\ub2e4. \uadf8\ub9bc \uc8fc\uc704\uc758 \uadf8\ub9bc\uc790\ub3c4 \ube44\uc2b7\ud558\ub2e4. \ud55c \ub369\uc5b4\ub9ac\uc758 \ud68c\uc0c9 \uba74\ubcf4\ub2e4 \uc810\ucc28 \uc605\uc5b4\uc9c0\ub294 \ubd80\ubd84\uc774 \uc788\uc73c\uba74 \uc790\uc5f0\uc2a4\ub7fd\ub2e4. \uc774\ub54c \ud544\uc694\ud55c \uac83\uc740 \ud770\uc0c9\uc744 \uc798 \uce60\ud558\ub294 \uae30\uc220\ub9cc\uc774 \uc544\ub2c8\ub2e4. \ubc14\ud0d5\uc774 \uc5b4\ub5a4 \uc0c9\uc774\ub4e0 \ud568\uaed8 \uc5b4\uc6b8\ub9ac\ub3c4\ub85d, \uadf8\ub9bc\uc774 \uadf8 \uc790\ub9ac\ub97c \uc5bc\ub9c8\ub098 \uac00\ub9b4\uc9c0 \ud45c\ud604\ud558\ub294 \uc815\ubcf4\ub2e4. PNG\ub294 \ud22c\uba85\ub3c4\ub97c \uc9c0\uc6d0\ud558\uc9c0\ub9cc \ubaa8\ub4e0 PNG \ud30c\uc77c\uc5d0 \ud22c\uba85\ud55c \ubd80\ubd84\uc774 \ub4e4\uc5b4 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ucc98\uc74c\ubd80\ud130 \ud770 \ubc30\uacbd\uc744 \ud3ec\ud568\ud574 \uc800\uc7a5\ud588\ub2e4\uba74 \uadf8\ub300\ub85c \ud770\uc0c9\uc774 \ubcf4\uc778\ub2e4. \ud30c\uc77c \ud615\uc2dd\uc774 \uc5b4\ub5a4 \uae30\ub2a5\uc744 \uc81c\uacf5\ud558\ub294\uc9c0\uc640 \uc2e4\uc81c \ud30c\uc77c\uc5d0 \uadf8 \uae30\ub2a5\uc774 \uc0ac\uc6a9\ub418\uc5c8\ub294\uc9c0\ub294 \ub2e4\ub974\ub2e4. \ub610 \ud770 \ubc30\uacbd\uc774 \uc788\ub294 \uc0ac\uc9c4\uc758 \ud655\uc7a5\uc790\ub9cc PNG\ub85c \ubc14\uafbc\ub2e4\uace0 \uc778\ubb3c \uc8fc\ubcc0\uc774 \uc790\ub3d9\uc73c\ub85c \uc624\ub824\uc9c0\uc9c0\ub3c4 \uc54a\ub294\ub2e4. \ubc30\uacbd\uc744 \uad6c\ubd84\ud558\uace0 \ud22c\uba85\ud55c \uc601\uc5ed\uc73c\ub85c \ub9cc\ub4dc\ub294 \ud3b8\uc9d1\uc774 \ub530\ub85c \ud544\uc694\ud558\ub2e4. \uadf8\ub987\uc774 \ubb34\uc5c7\uc744 \ub2f4\uc744 \uc218 \uc788\ub294\uc9c0\uc640 \uc548\uc5d0 \ubb34\uc5c7\uc774 \ub2f4\uacbc\ub294\uc9c0\ub97c \ub098\ub204\uba74 \ud754\ud55c \uc624\ud574\uac00 \uc904\uc5b4\ub4e0\ub2e4. PNG\uc758 \uc911\uc694\ud55c \ud2b9\uc9d5\uc740 \ubb34\uc190\uc2e4 \uc555\ucd95\uc774\ub2e4. \uc800\uc7a5\ud560 \uc774\ubbf8\uc9c0 \uc815\ubcf4\ub97c \uc555\ucd95\ud588\ub2e4\uac00 \ub2e4\uc2dc \ud480 \ub54c \uadf8 \uc815\ubcf4\ub97c \ubcf4\uc874\ud558\ub3c4\ub85d \ud558\ub294 \ubc29\uc2dd\uc774\ub2e4. \uac19\uc740 \ub0b4\uc6a9\uc744 \ub354 \ud6a8\uc728\uc801\uc73c\ub85c \uc801\ub294 \uac83\uc5d0 \uac00\uae5d\ub2e4. \uc0ac\uc9c4\uc758 \uc138\ubd80\ub97c \uc77c\ubd80 \ubc84\ub824 \ud06c\uae30\ub97c \uc904\uc774\ub294 \uc77c\ubc18\uc801\uc778 \uc190\uc2e4 \uc555\ucd95\uacfc\ub294 \uc6d0\ub9ac\uac00 \ub2e4\ub974\ub2e4. \uadf8\ub807\ub2e4\uace0 PNG\uac00 \uc774\uc804 \ud3b8\uc9d1\uc5d0\uc11c \uc0ac\ub77c\uc9c4 \ub0b4\uc6a9\uc744 \ub418\uc0b4\ub9b0\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc774\ubbf8 \uc791\uac8c \uc904\uc774\uac70\ub098 \uc190\uc2e4 \uc555\ucd95\uc73c\ub85c \ubb49\uac1c\uc9c4 \uc774\ubbf8\uc9c0\ub97c PNG\ub85c \uc800\uc7a5\ud574\ub3c4 \uc5c6\uc5b4\uc9c4 \uc138\ubd80\ub294 \ub3cc\uc544\uc624\uc9c0 \uc54a\ub294\ub2e4. \ubb34\uc5c7\uc744 \ubcf4\uc874\ud558\ub294\uc9c0\uc758 \ucd9c\ubc1c\uc810\uc740 \uc9c0\uae08 \uc800\uc7a5\ud558\ub294 \uc774\ubbf8\uc9c0\uc774\uc9c0, \uc624\ub798\uc804 \ucd2c\uc601\ud588\ub358 \uc6d0\ub798 \uc7a5\uba74 \uc804\uccb4\uac00 \uc544\ub2c8\ub2e4. PNG\uac00 \ubaa8\ub4e0 \uc6a9\ub3c4\uc5d0\uc11c \uac00\uc7a5 \uc791\uc740 \ud30c\uc77c\uc744 \ub9cc\ub4dc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0ac\uc9c4\ucc98\ub7fc \ubcf5\uc7a1\ud55c \uc0c9 \ubcc0\ud654\uac00 \ub9ce\uc740 \uc790\ub8cc\uc5d0\uc11c\ub294 \ub2e4\ub978 \ud615\uc2dd\uc774 \ub354 \uc801\uc740 \uc6a9\ub7c9\uc73c\ub85c \uc6d0\ud558\ub294 \ud488\uc9c8\uc744 \uc81c\uacf5\ud560 \uc218 \uc788\ub2e4. \uc6f9\uc5d0\uc11c\ub294 \uc804\uc1a1 \ud06c\uae30\uc640 \uc9c0\uc6d0 \ud658\uacbd, \uc774\ubbf8\uc9c0\uc758 \uc131\uaca9\uc744 \ud568\uaed8 \uace0\ub824\ud55c\ub2e4. \ubc18\uba74 \uae00\uc790\uc640 \uc120\uc774 \ub610\ub837\ud55c \ud654\uba74 \uc790\ub8cc\ub098 \ud22c\uba85\ud55c \uac00\uc7a5\uc790\ub9ac\uac00 \ud544\uc694\ud55c \uadf8\ub9bc\uc740 \uc190\uc2e4\uacfc \ud22c\uba85\ub3c4\uc5d0 \ub300\ud55c \uc694\uad6c\uac00 \ub2e4\ub974\ub2e4. \uc5b4\ub5a4 \ud615\uc2dd\uc774 \ucd5c\uace0\uc778\uac00\ubcf4\ub2e4 \uc774 \uadf8\ub9bc\uc744 \uc5b4\ub514\uc5d0 \uc4f0\ub294\uac00\uac00 \uba3c\uc800\ub2e4. PNG\ub97c \uc548\ub2e4\ub294 \uac83\uc740 \ud655\uc7a5\uc790 \ud558\ub098\ub97c \uace0\uc9d1\ud558\ub294 \uc77c\uc774 \uc544\ub2c8\ub77c \ud544\uc694\ud55c \uc131\uc9c8\uc744 \uad6c\ubcc4\ud558\ub294 \uc77c\uc5d0 \uac00\uae5d\ub2e4. \uc774\ubbf8\uc9c0 \ud3b8\uc9d1 \ud504\ub85c\uadf8\ub7a8\uc5d0\uc11c\ub294 \ud22c\uba85\ud55c \ubd80\ubd84\uc744 \ud68c\uc0c9\uacfc \ud770\uc0c9 \uccb4\ud06c\ubb34\ub2ac\ub85c \ubcf4\uc5ec \uc8fc\uae30\ub3c4 \ud55c\ub2e4. \ubc30\uacbd\uc774 \uc5c6\ub294 \uc790\ub9ac\ub97c \ub208\uc73c\ub85c \uad6c\ubd84\ud558\uac8c \ud558\ub294 \uc548\ub0b4\ub2e4. \uc2e4\uc81c\ub85c \uccb4\ud06c\ubb34\ub2ac \uc790\uccb4\ub97c \uadf8\ub824 \uc800\uc7a5\ud55c \uc774\ubbf8\uc9c0\ub77c\uba74 \ub2e4\ub978 \uacf3\uc5d0\uc11c\ub3c4 \ubb34\ub2ac\uac00 \ubcf4\uc774\ubbc0\ub85c, \ud654\uba74\uc5d0\uc11c \ubcf4\uc774\ub294 \ubaa8\uc591\ub9cc\uc73c\ub85c\ub294 \uad6c\ubcc4\uc774 \ud544\uc694\ud558\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \ud22c\uba85\ud55c \ud310 \ub4a4\uc5d0 \uc0c9\uc9c0\uac00 \ubcf4\uc774\ub294 \ubb3c\ub9ac\uc801\uc778 \ube44\uc720\ub2e4. \uc774 \uc0bd\ud654 \ud30c\uc77c \uc790\uccb4\uac00 \ud22c\uba85\ud55c PNG\uc758 \uc2e4\ud5d8 \ud45c\ubcf8\uc774\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uac1c\ub150\uc744 \ub5a0\uc62c\ub9ac\ub294 \uadf8\ub9bc\uacfc \uc2e4\uc81c \ud30c\uc77c \uc18d \uc54c\ud30c \uac12\uc740 \uad6c\ubcc4\ud574\uc11c \ubcf4\uba74 \ub41c\ub2e4. PNG\uc5d0\ub294 \ud22c\uba85\ub3c4 \ud45c\ud604\uc744 \uc800\uc7a5\ud558\ub294 \ubc29\ubc95\ub3c4 \uc5ec\ub7ec \uac00\uc9c0\uac00 \uc788\uc9c0\ub9cc \uc6d0\ub9ac\ub97c \uc774\ud574\ud558\ub294 \ub370 \ubaa8\ub450 \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8\ub9bc\uc5d0\uc11c \uc911\uc694\ud55c \uac83\uc740 \ubb34\uc5c7\uc744 \ubcf4\uc5ec \uc8fc\ub294\uac00\ubfd0\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \ubc30\uacbd\uc774 \ub4dc\ub7ec\ub098\ub3c4\ub85d \ube44\uc6cc \ub450\ub294 \uc815\ub3c4\ub3c4 \ud30c\uc77c\uc5d0 \ub2f4\uc744 \uc218 \uc788\ub294 \uc815\ubcf4\ub2e4. \ub208\uc5d0 \uc798 \ub744\ub294 \uc0c9 \uc606\uc5d0\uc11c \ubcf4\uc774\uc9c0 \uc54a\uc74c\uc758 \ubc29\uc2dd\uc774 \ud568\uaed8 \uc791\ub3d9\ud558\uace0 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \uadf8\ub9bc \uc8fc\uc704\uc5d0 \ud770 \ub124\ubaa8\uac00 \ub098\ud0c0\ub098\uba74 \ud30c\uc77c\uc774 \ubb34\uc870\uac74 \uc798\ubabb\ub418\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud558\uae30\ubcf4\ub2e4, \uadf8 \uc790\ub9ac\uac00 \ud770\uc0c9\uc778\uc9c0 \ud22c\uba85\uc778\uc9c0 \uba3c\uc800 \ubb3c\uc5b4\ubcf4\uc790. \uac04\ub2e8\ud55c \uc9c8\ubb38 \ud558\ub098\ub85c \uc774\ubbf8\uc9c0\uc758 \uc131\uaca9\uc774 \ub2ec\ub77c \ubcf4\uc778\ub2e4. PNG\uc758 \uc7ac\ubbf8\ub294 \ud2b9\ubcc4\ud55c \ud6a8\uacfc\ubcf4\ub2e4, \ubcf4\uc774\ub294 \uac83\uacfc \ube44\uc6cc \ub454 \uac83\uc744 \ud568\uaed8 \uae30\ub85d\ud55c\ub2e4\ub294 \ub370 \uc788\ub2e4."}, {"id": "python-comedy-name", "title": "\ud30c\uc774\uc36c\uc774\ub77c\ub294 \uc774\ub984\uc740 \ucf54\ubbf8\ub514\uc5d0\uc11c \uc654\ub2e4", "summary": "\ucef4\ud4e8\ud130 \uc5b8\uc5b4\uc758 \uc774\ub984\uc744 \ub530\ub77c\uac00\ub2e4 \ubcf4\uba74 \uc601\uad6d \ucf54\ubbf8\ub514 \ud504\ub85c\uadf8\ub7a8\uc744 \ub9cc\ub098\uac8c \ub429\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\uc18c\ud504\ud2b8\uc6e8\uc5b4", "categories": ["digital"], "url": "stories/python-comedy-name/index.html", "image": "../media/python-comedy-name.jpg", "alt": "\ubb34\ub300 \ucee4\ud2bc\uc774 \ubcf4\uc774\ub294 \uc61b \ud154\ub808\ube44\uc804\uacfc \ube48 \ub300\ubcf8\uc758 \uc124\uba85\uc6a9 AI \uc0bd\ud654", "text": "\ud30c\uc774\uc36c\uc774\ub77c\ub294 \uc774\ub984\uc740 \ucf54\ubbf8\ub514\uc5d0\uc11c \uc654\ub2e4 \ud504\ub85c\uadf8\ub798\ubc0d \uc5b8\uc5b4\uc758 \uc774\ub984\uc5d0 \ub0a8\uc740 \uac1c\ubc1c\uc790\uc758 \ucde8\ud5a5 \ucef4\ud4e8\ud130 \uc5b8\uc5b4\uc758 \uc774\ub984\uc744 \ub530\ub77c\uac00\ub2e4 \ubcf4\uba74 \uc601\uad6d \ucf54\ubbf8\ub514 \ud504\ub85c\uadf8\ub7a8\uc744 \ub9cc\ub098\uac8c \ub429\ub2c8\ub2e4. \uc18c\ud504\ud2b8\uc6e8\uc5b4 \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \ud30c\uc774\uc36c\uc774\ub77c\ub294 \uc774\ub984\uc744 \ucc98\uc74c \ub4e4\uc73c\uba74 \ubc40\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uc601\uc5b4\ub85c\ub3c4 \ud070 \ubc40\uc744 \uac00\ub9ac\ud0a4\ub294 \ub9d0\uc774\ub2e4. \ucef4\ud4e8\ud130\ub97c \uc798 \ubaa8\ub974\ub294 \uc0ac\ub78c\uc774\ub77c\ub3c4 \uc5b4\ub514\uc120\uac00 \ud55c \ubc88\ucbe4 \ub4e4\uc5b4\ubcf8 \uc774\ub984\uc77c \uc218 \uc788\ub2e4. \uadf8\ub7f0\ub370 \ud504\ub85c\uadf8\ub798\ubc0d \uc5b8\uc5b4 Python\uc758 \uacf5\uc2dd FAQ\ub294 \uc774\ub984\uc758 \ucd9c\ubc1c\uc810\uc744 \uc870\uae08 \ub2e4\ub974\uac8c \uc124\uba85\ud55c\ub2e4. \uac1c\ubc1c\uc790 \uadc0\ub3c4 \ud310 \ub85c\uc12c\uc774 \uc77d\uace0 \uc788\ub358 \uc601\uad6d \ucf54\ubbf8\ub514 \ud504\ub85c\uadf8\ub7a8\uc758 \ub300\ubcf8\uc5d0\uc11c \uac00\uc838\uc654\ub2e4\ub294 \uac83\uc774\ub2e4. \ud504\ub85c\uadf8\ub7a8\uc758 \uc774\ub984\uc740 \u300c\ubaac\ud2f0 \ud30c\uc774\uc120\uc758 \ud50c\ub77c\uc789 \uc11c\ucee4\uc2a4\u300d\uc600\ub2e4. \ucef4\ud4e8\ud130 \uc5b8\uc5b4 \uc774\ub984\uc744 \ub530\ub77c\uc654\ub294\ub370 \uac11\uc790\uae30 \ud154\ub808\ube44\uc804\uc758 \ucf54\ubbf8\ub514 \ubb34\ub300\uac00 \ub098\ud0c0\ub09c\ub2e4. \uacf5\uc2dd \uc124\uba85\uc5d0 \ub530\ub974\uba74 \ud310 \ub85c\uc12c\uc740 \ud30c\uc774\uc36c\uc744 \uad6c\ud604\ud558\ub358 \ubb34\ub835 \uadf8 \ucf54\ubbf8\ub514\uc758 \ucd9c\ud310\ub41c \ub300\ubcf8\uc744 \uc77d\uace0 \uc788\uc5c8\ub2e4. \uc0c8 \uc5b8\uc5b4\uc5d0\ub294 \uc9e7\uace0 \ub3c5\ud2b9\ud558\uba70 \uc870\uae08\uc740 \uc2e0\ube44\ub85c\uc6b4 \ub290\ub08c\uc758 \uc774\ub984\uc774 \ud544\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud588\ub2e4. \uadf8\ub798\uc11c Python\uc774\ub77c\ub294 \uc774\ub984\uc744 \uace8\ub790\ub2e4. \ubaa8\ub4e0 \uc774\ub984\uc774 \uae30\ub2a5\uc744 \uc904\uc5ec \ubd99\uc778 \uc57d\uc790\ub098 \uae30\uc220 \uc6a9\uc5b4\uc5d0\uc11c \ub098\uc624\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub9cc\ub4dc\ub294 \uc0ac\ub78c\uc774 \uc990\uae30\ub358 \ubb38\ud654\uac00 \uc774\ub984\uc758 \uc7ac\ub8cc\uac00 \ub418\uae30\ub3c4 \ud55c\ub2e4. \uc5ec\uae30\uc11c \ucf54\ubbf8\ub514\uac00 \ud504\ub85c\uadf8\ub798\ubc0d\uc758 \uc6d0\ub9ac\ub97c \uacb0\uc815\ud588\ub2e4\uace0 \uc124\uba85\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc9c0\uae08 \ud655\uc778\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc774\ub984\uc744 \uc815\ud55c \uc0ac\uc5f0\uc774\ub2e4. \uc9e7\uc740 \uc774\ub984 \ud558\ub098\uc5d0\ub3c4 \uae30\uc220 \ubc16\uc758 \uacbd\ud5d8\uc774 \ub4e4\uc5b4\uac08 \uc790\ub9ac\uac00 \uc788\uc5c8\ub2e4. \ud765\ubbf8\ub85c\uc6b4 \uac83\uc740 \uc774 \uc0ac\uc5f0\uc774 \ub5a0\ub3c4\ub294 \uc18c\ubb38\uc73c\ub85c\ub9cc \uc804\ud574\uc9c0\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uacf5\uc2dd \uc9c8\ubb38\uacfc \ub2f5\ubcc0 \ubaa9\ub85d\uc5d0 \ub4e4\uc5b4 \uc788\ub2e4\ub294 \uc810\uc774\ub2e4. \uc774\ub984\uc758 \uc720\ub798\ub97c \ubb3b\ub294 \uc9c8\ubb38 \ub2e4\uc74c\uc5d0\ub294 \uadf8 \ucf54\ubbf8\ub514\ub97c \uaf2d \uc88b\uc544\ud574\uc57c \ud558\ub294\uc9c0\ub3c4 \ubb3b\ub294\ub2e4. \ub2f5\ubcc0\ub3c4 \uac00\ubccd\ub2e4. \ubc18\ub4dc\uc2dc \uc88b\uc544\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4\ub294 \ucde8\uc9c0\ub85c \uc9e7\uc740 \ub18d\ub2f4\uc744 \ub367\ubd99\uc778\ub2e4. \uae30\uc220\uc744 \uc124\uba85\ud558\ub294 \ubb38\uc11c \uc548\uc5d0\uc11c\ub3c4 \ub9cc\ub4e0 \uc0ac\ub78c\ub4e4\uc758 \ub9d0\ud22c\uc640 \ucde8\ud5a5\uc774 \uc7a0\uae50 \ub4dc\ub7ec\ub098\ub294 \ub300\ubaa9\uc774\ub2e4. \ubb3c\ub860 \ud504\ub85c\uadf8\ub7a8\uc744 \uc4f0\uae30 \uc704\ud574 \ucf54\ubbf8\ub514\ub97c \ubcf4\uc544\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774\ub984\uc758 \ubc30\uacbd\uc744 \ubab0\ub77c\ub3c4 \ub3c4\uad6c\ub294 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ub0af\uc124\uace0 \uc804\ubb38\uc801\uc73c\ub85c \ubcf4\uc774\ub358 \uc774\ub984\uc5d0 \uc0dd\ud65c\uc758 \uc791\uc740 \ub2e8\uc11c\uac00 \uc0dd\uae34\ub2e4. \uc5b4\ub5a4 \ub2e8\uc5b4\uac00 \uc0ac\uc804\uc5d0 \uc5b4\ub5a4 \ub73b\uc73c\ub85c \ub098\uc624\ub294\uc9c0\uc640 \uac1c\ubc1c\uc790\uac00 \uc65c \uadf8 \ub2e8\uc5b4\ub97c \uace8\ub790\ub294\uc9c0\ub294 \ub2e4\ub978 \uc9c8\ubb38\uc774\ub2e4. Python\uc774 \ubc40\uc758 \uc774\ub984\uc774\ub77c\ub294 \uc0ac\uc2e4\uc740 \ub9de\uc9c0\ub9cc, \uacf5\uc2dd \ubb38\uc11c\uac00 \uc124\uba85\ud558\ub294 \uc791\uba85\uc758 \uacc4\uae30\ub294 \ucf54\ubbf8\ub514 \ub300\ubcf8\uc774\ub2e4. \ub450 \uc0ac\uc2e4\uc744 \uacbd\uc7c1\ud558\ub294 \uc815\ub2f5\uc73c\ub85c \ubcfc \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e8\uc5b4\uac00 \uc6d0\ub798 \uac00\uc9c4 \ub73b\uacfc \uadf8 \uc774\ub984\uc5d0 \ub2f4\uc740 \uac1c\uc778\uc801\uc778 \uacbd\ud5d8\uc774 \ud568\uaed8 \ub0a8\uc544 \uc788\ub294 \uacbd\uc6b0\ub2e4. \uc774 \ucc28\uc774\ub294 \ub2e4\ub978 \uae30\uc220 \uc774\ub984\uc744 \ub9cc\ub0a0 \ub54c\uc5d0\ub3c4 \uc720\uc6a9\ud558\ub2e4. \ub208\uc55e\uc758 \ub85c\uace0\uac00 \uc5b4\ub5a4 \ubaa8\uc591\uc774\ub77c\uace0 \ud574\uc11c \uadf8\uac83\uc774 \ubc18\ub4dc\uc2dc \ucd5c\ucd08 \uc791\uba85\uc758 \uc774\uc720\uc600\ub2e4\uace0 \uac70\uafb8\ub85c \ucd94\ub860\ud560 \uc218\ub294 \uc5c6\ub2e4. \uba3c\uc800 \ub9cc\ub4e4\uc5b4\uc9c4 \uc774\ub984\uc774 \ub098\uc911\uc758 \uc2dc\uac01\uc801 \ud45c\ud604\uacfc \ub9cc\ub098 \ub354 \ub110\ub9ac \uae30\uc5b5\ub418\uae30\ub3c4 \ud55c\ub2e4. \ud30c\uc774\uc36c\uc758 \uacbd\uc6b0\uc5d0\ub294 \uc774\ub984\uc744 \uace0\ub978 \uc0ac\uc815\uc744 \uc124\uba85\ud55c \uacf5\uc2dd \ub2f5\ubcc0\uc744 \ud1b5\ud574 \uc21c\uc11c\ub97c \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \ub9ce\uc740 \uae30\uc220 \uc6a9\uc5b4\ub294 \uae34 \uc804\ubb38 \ud45c\ud604\uc758 \uc55e\uae00\uc790\ub97c \ubaa8\uc544 \ub9cc\ub4e0\ub2e4. \uadf8\ub798\uc11c \ucc98\uc74c \ubcf4\ub294 \uc774\ub984\uc744 \ub9cc\ub098\uba74 \uc5b4\ub5a4 \uae30\ub2a5\uc758 \uc57d\uc790\uc778\uc9c0 \ubb3b\uac8c \ub41c\ub2e4. \ud558\uc9c0\ub9cc \ud30c\uc774\uc36c\uc774\ub77c\ub294 \uc774\ub984\uc740 \uadf8\ub7f0 \ubc29\uc2dd\uc758 \uae30\ub2a5 \uc694\uc57d\uc73c\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc9e7\uace0 \uad6c\ubcc4\ub418\uba70 \uc778\uc0c1\uc5d0 \ub0a8\ub294 \uc774\ub984\uc744 \ucc3e\ub294 \uacfc\uc815\uc5d0 \ucde8\ud5a5\uc774 \ub4e4\uc5b4\uac04 \uac83\uc774\ub2e4. \uc774 \uc0ac\uc2e4\uc744 \uc548\ub2e4\uace0 \uadf8 \uc5b8\uc5b4\uc758 \ubb38\ubc95\uc774 \ub354 \uc27d\uac70\ub098 \ube60\ub974\ub2e4\ub294 \uacb0\ub860\uc744 \ub0bc \uc218\ub294 \uc5c6\ub2e4. \uc774\ub984\uacfc \uc131\ub2a5\uc758 \uadfc\uac70\ub294 \ub530\ub85c \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \ub2e4\ub9cc \uae30\uc220\uc744 \ub9cc\ub4dc\ub294 \uc0ac\ub78c\uc758 \uc120\ud0dd\uc774 \uc5b8\uc81c\ub098 \uacc4\uc0b0 \ud6a8\uc728\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc740 \ubcfc \uc218 \uc788\ub2e4. \ub3c4\uad6c\uc5d0\ub294 \uae30\ub2a5\uc758 \uc124\uacc4\uc640 \uc0ac\ub78c\ub4e4\uc774 \uadf8\uac83\uc744 \ubd80\ub974\uace0 \uae30\uc5b5\ud558\ub294 \ubc29\uc2dd\uc774 \ud568\uaed8 \uc788\ub2e4. \uc9c8\ubb38\uacfc \ub2f5\ubcc0\uc758 \ubaa9\ub85d\uc740 \ucc98\uc74c \uc811\ud55c \uc0ac\ub78c\uc774 \uc790\uc8fc \uad81\uae08\ud574\ud558\ub294 \uac83\uc744 \ubaa8\uc740\ub2e4. \uc0ac\uc6a9\ubc95\uacfc \ubb38\uc81c \ud574\uacb0\ub9cc\uc774 \uc544\ub2c8\ub77c \uc65c \uadf8\ub7f0 \uc774\ub984\uc778\uc9c0 \uac19\uc740 \uc9c8\ubb38\ub3c4 \ud3ec\ud568\ub420 \uc218 \uc788\ub2e4. \ubb38\uc11c\uac00 \uc774\ub984\uc758 \uc720\ub798\uc640 \ucf54\ubbf8\ub514\uc5d0 \uad00\ud55c \uac00\ubcbc\uc6b4 \ub18d\ub2f4\uc744 \ud568\uaed8 \uc2e3\ub294\ub2e4\ub294 \uc810\uc740 \ub3c4\uad6c \uc8fc\ubcc0\uc758 \ubb38\ud654\uac00 \uc804\ub2ec\ub418\ub294 \ubc29\uc2dd\uc73c\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \ubb3c\ub860 \uc791\uc131\uc790\uc758 \ubaa8\ub4e0 \ub18d\ub2f4\uc744 \uc5b8\uc5b4\uc758 \uacf5\uc2dd \ucca0\ud559\uc73c\ub85c \ud06c\uac8c \ud574\uc11d\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ubb38\ubc95 \uaddc\uce59\uc740 \ubb38\ubc95 \uaddc\uce59\ub300\ub85c \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc804\ubb38\uc801\uc778 \uc124\uba85 \uc0ac\uc774\uc5d0\ub3c4 \uc0ac\ub78c\uc758 \ub9d0\ud22c\uac00 \ub0a8\uc544 \uc788\ub2e4\ub294 \uac83\uc744 \ubcf4\ub294 \uac83\uc774\ub2e4. \uae30\uc220 \ubb38\uc11c\uac00 \uac10\uc815 \uc5c6\ub294 \uae30\uacc4\uc758 \ubb38\uc7a5\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c4\ub2e4\ub294 \uc778\uc0c1\ub3c4 \uc870\uae08 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc5b4\ub5a4 \uc0ac\ub78c\uc5d0\uac8c \ud30c\uc774\uc36c\uc740 \uc77c\ud558\ub294 \ub3c4\uad6c\uc774\uace0 \uc5b4\ub5a4 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ucc98\uc74c \ub4e3\ub294 \uc804\ubb38 \uc6a9\uc5b4\ub2e4. \ucf54\ubbf8\ub514\uc758 \ubc30\uacbd\uc744 \uc544\ub294 \uc0ac\ub78c\uc740 \uc774\ub984\uc5d0\uc11c \ub610 \ub2e4\ub978 \uc5f0\uacb0\uc744 \ub290\ub084 \uc218 \uc788\ub2e4. \ud558\ub098\uc758 \uc774\ub984\uc774 \uc11c\ub85c \ub2e4\ub978 \uacbd\ud5d8\uc744 \uac00\uc9c4 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uac01\uae30 \ub2e4\ub978 \uc785\uad6c\ub97c \ub9cc\ub4dc\ub294 \uc148\uc774\ub2e4. \uacf5\ud1b5\uc758 \uae30\ub2a5\uc744 \uc4f0\uba74\uc11c\ub3c4 \uc8fc\ubcc0 \uc774\uc57c\uae30\ub97c \ub611\uac19\uc774 \uc54c\uc544\uc57c \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8\ub807\uae30\uc5d0 \uc774 \uae00\uc740 \ub300\ubcf8\uc744 \uc77d\uc5b4\uc57c\ub9cc \uae30\uc220\uc744 \uc774\ud574\ud560 \uc218 \uc788\ub2e4\ub294 \uc0c8\ub85c\uc6b4 \uc219\uc81c\ub97c \uc8fc\ub824\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \ub3c4\uad6c\uc758 \uc791\uc740 \uc720\ub798\ub97c \ud1b5\ud574 \ub9cc\ub4dc\ub294 \uc0ac\ub78c\uacfc \uc4f0\ub294 \uc0ac\ub78c \uc0ac\uc774\uc758 \uac70\ub9ac\ub97c \uc904\uc774\ub294 \uc77d\uae30\ub2e4. \ub0af\uc120 \uae30\uc220\uc744 \ubaa8\ub450 \ubc30\uc6b8 \ud544\uc694 \uc5c6\uc774\ub3c4 \uadf8 \uc774\ub984 \ub4a4\uc5d0 \uc5b4\ub5a4 \uc120\ud0dd\uc774 \uc788\uc5c8\ub294\uc9c0 \uad6c\uacbd\ud560 \uc218 \uc788\ub2e4. \ucf54\ub529 \ubc16\uc5d0\uc11c \ucef4\ud4e8\ud130 \ubb38\ud654\ub97c \ub9cc\ub098\ub294 \ud55c \ubc29\ubc95\uc774\ub2e4. \ud504\ub85c\uadf8\ub798\ubc0d \uc5b8\uc5b4\ub294 \ucef4\ud4e8\ud130\uc5d0\uac8c \ud560 \uc77c\uc744 \ud45c\ud604\ud558\ub294 \ub3c4\uad6c\ub2e4. \ucc98\uc74c \uc811\ud558\uba74 \ubb38\ubc95\uacfc \uae30\ud638\uac00 \uba3c\uc800 \ubcf4\uc5ec \uc5b4\ub835\uac8c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \ub3c4\uad6c\ub97c \ub9cc\ub4e0 \uc0ac\ub78c\ub4e4\ub3c4 \ucc45\uc744 \uc77d\uace0 \ud154\ub808\ube44\uc804\uc744 \ubcf4\uba70 \uc774\ub984\uc744 \uace8\ub790\ub2e4. \uc774\uc57c\uae30\ub97c \uc548\ub2e4\uace0 \uace7\ubc14\ub85c \ucf54\ub4dc\ub97c \uc4f8 \uc218 \uc788\uac8c \ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub7f4 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \uc774\ubc88\uc5d0\ub294 \uae30\uc220\uc758 \uc0ac\uc6a9\ubc95\ubcf4\ub2e4, \uc775\uc219\ud55c \uc774\ub984 \ud558\ub098\uac00 \ub9cc\ub4e4\uc5b4\uc9c4 \uacfc\uc815\uc744 \uad6c\uacbd\ud558\ub294 \uac83\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4. \ub2e4\uc74c\uc5d0 \ud30c\uc774\uc36c\uc774\ub77c\ub294 \ub9d0\uc744 \ub9cc\ub098\uba74 \ubc40 \uc606\uc5d0 \uc791\uc740 \ucf54\ubbf8\ub514 \ubb34\ub300\ub3c4 \ud568\uaed8 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ucef4\ud4e8\ud130 \uc138\uacc4\uc758 \uc774\ub984\uc5d0\ub3c4 \ub204\uad70\uac00 \uc7ac\ubbf8\uc788\uac8c \uc77d\ub358 \ub300\ubcf8\uc758 \ud754\uc801\uc774 \ub0a8\uc544 \uc788\ub2e4."}, {"id": "qr-code-three-corners", "title": "QR \ucf54\ub4dc \u2014 \uc65c \uc138 \ubaa8\uc11c\ub9ac\uc5d0 \ud070 \ub124\ubaa8\uac00 \uc788\uc744\uae4c", "summary": "QR \ucf54\ub4dc\uc758 \uc704\uce58 \ud45c\uc2dc\uc640 \ub370\uc774\ud130, \uc624\ub958 \uc815\uc815\uc744 \ud1b5\ud574 \uc791\uc740 \ubb34\ub2ac\uac00 \uc77d\ud788\ub294 \uc6d0\ub9ac\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\ub370\uc774\ud130\uc640 \uae30\ub85d", "categories": ["digital"], "url": "stories/qr-code-three-corners/index.html", "image": "../media/qr-code-three-corners.png", "alt": "\uce74\ud398\uc5d0\uc11c \uc190\ub2d8\uc774 \ud734\ub300\uc804\ud654\ub97c \ub4e4\uace0 \uce74\ub4dc \ucabd\uc744 \ubc14\ub77c\ubcf4\uba70 \uc74c\ub8cc\ub97c \ubc1b\ub294 AI \uc7a5\uba74.", "text": "QR \ucf54\ub4dc \u2014 \uc65c \uc138 \ubaa8\uc11c\ub9ac\uc5d0 \ud070 \ub124\ubaa8\uac00 \uc788\uc744\uae4c \uc791\uc740 \uac80\uc740 \uce78\ub4e4\uc774 \uce74\uba54\ub77c\uc5d0\uac8c \uae38\uc744 \uc54c\ub824 \uc8fc\ub294 \ubc29\ubc95 QR \ucf54\ub4dc\uc758 \uc704\uce58 \ud45c\uc2dc\uc640 \ub370\uc774\ud130, \uc624\ub958 \uc815\uc815\uc744 \ud1b5\ud574 \uc791\uc740 \ubb34\ub2ac\uac00 \uc77d\ud788\ub294 \uc6d0\ub9ac\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ub370\uc774\ud130\uc640 \uae30\ub85d \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \uce74\ud398\uc5d0\uc11c \uba54\ub274\ub97c \ubcf4\ub824\uace0 \uc791\uc740 \ubb34\ub2ac\ub97c \ud734\ub300\uc804\ud654\ub85c \ube44\ucd98\ub2e4. \uac80\uc740 \uce78\ub4e4\uc774 \ube7c\uace1\ud55c\ub370 \ud654\uba74\uc740 \uace7 \uc8fc\uc18c\ub97c \uc54c\uc544\ubcf8\ub2e4. \uc0ac\ub78c \ub208\uc5d0\ub294 \ube44\uc2b7\ube44\uc2b7\ud55c \ubb34\ub2ac\uac00 \uae30\uacc4\uc5d0\ub294 \uc77d\uc744 \uc218 \uc788\ub294 \uc815\ubcf4\uc778 \uc148\uc774\ub2e4. QR \ucf54\ub4dc\ub97c \uc790\uc8fc \uc368\ub3c4 \uadf8 \uc548\uc758 \ud070 \ub124\ubaa8\ub4e4\uc740 \uadf8\ub0e5 \uc9c0\ub098\uce58\uae30 \uc27d\ub2e4. \ub2e4\uc74c\uc5d0 \ubcfc \ub54c\ub294 \ubaa8\uc11c\ub9ac \uc138 \uacf3\uc744 \uba3c\uc800 \uc0b4\ud3b4\ubcf4\uc790. \ubcf4\ud1b5\uc758 QR \ucf54\ub4dc\uc5d0\ub294 \uc791\uc740 \uce78\ubcf4\ub2e4 \ud6e8\uc52c \ud070 \ub124\ubaa8 \ubb34\ub2ac\uac00 \uc788\ub2e4. \uc7a5\uc2dd\uc774 \uc544\ub2c8\ub77c \ucf54\ub4dc\ub97c \ucc3e\uace0 \uc77d\ub294 \ub370 \ud544\uc694\ud55c \ud45c\uc9c0\ub2e4. \ubaa8\ub4e0 \uac80\uc740 \uce78\uc774 \uac19\uc740 \uc885\ub958\uc758 \uc815\ubcf4\ub97c \ub2f4\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc0ac\uc2e4\uc774 \uc774 \uc774\uc57c\uae30\uc758 \ucd9c\ubc1c\uc810\uc774\ub2e4. \ud734\ub300\uc804\ud654\ub85c \ube44\ucd98 \uc7a5\uba74\uc5d0\ub294 \ucf54\ub4dc\ub9cc \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc885\uc774\uc758 \ud14c\ub450\ub9ac\uc640 \uc2dd\ud0c1, \uadf8\ub9bc\uc790\ub3c4 \ud568\uaed8 \ub4e4\uc5b4\uc628\ub2e4. \uae30\uacc4\ub294 \uba3c\uc800 \uc5b4\ub290 \ubd80\ubd84\uc744 \uc77d\uc744 \ub300\uc0c1\uc778\uc9c0 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ud070 \uc704\uce58 \uac80\ucd9c \ubb34\ub2ac\ub294 \uadf8 \uc2dc\uc791\uc744 \ub3d5\ub294\ub2e4. \ud568\uaed8 \uc0b4\ud3b4\ubcf8 \uacf5\uac1c \uad6c\ud604\uc740 \uc77c\ubc18\uc801\uc778 QR \ucf54\ub4dc\uc758 \ub124 \ubaa8\uc11c\ub9ac \uac00\uc6b4\ub370 \uc624\ub978\ucabd \uc544\ub798\ub97c \uc81c\uc678\ud55c \uc138 \uacf3\uc5d0 \uc774 \ubb34\ub2ac\ub97c \uadf8\ub9b0\ub2e4. \uc11c\ub85c \ub5a8\uc5b4\uc838 \uc788\ub294 \ud45c\uc9c0\ub97c \ucc3e\uc73c\uba74 \ucf54\ub4dc\uc758 \uc790\ub9ac\uc640 \ubc29\ud5a5\uc744 \ud30c\uc545\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uc774 \uae00\uc740 \uc77c\ubc18\uc801\uc778 QR \ucf54\ub4dc\ub97c \ub2e4\ub8e8\uba70, \ubaa8\uc591\uc774 \ub2e4\ub978 \ubaa8\ub4e0 \ubcc0\ud615 \ucf54\ub4dc\uc5d0 \uac19\uc740 \uc124\uba85\uc744 \uc801\uc6a9\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud070 \ub124\ubaa8\ub294 \uac80\uc740\uc0c9\uacfc \ud770\uc0c9\uc774 \uc77c\uc815\ud55c \uad6c\uc870\ub85c \uacb9\uccd0 \uc788\ub2e4. \uc8fc\ubcc0\uc758 \uc791\uc740 \ub370\uc774\ud130 \ubb34\ub2ac\uc640 \uad6c\ubcc4\ub418\ub294 \ubaa8\uc591\uc744 \uac16\ub3c4\ub85d \ub9cc\ub4e0 \uac83\uc774\ub2e4. \uc0ac\ub78c\uc5d0\uac8c \uc81c\ubaa9\uacfc \ubcf8\ubb38\uc744 \ub2e4\ub978 \ud06c\uae30\ub85c \ubcf4\uc5ec \uc8fc\ub294 \uac83\ucc98\ub7fc, \uc77d\uae30 \uc704\ud55c \ud45c\uc9c0\ub97c \ub0b4\uc6a9\uacfc \uad6c\ubd84\ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uadf8 \uc606\uc5d0\ub294 \uce78\uc758 \uac04\uaca9\uc744 \uc77d\ub294 \ub370 \uc4f0\uc774\ub294 \ubc18\ubcf5 \ubb34\ub2ac\ub3c4 \uc788\ub2e4. \ud06c\uae30\uc5d0 \ub530\ub77c \ucd94\uac00\uc801\uc778 \uc815\ub82c \ubb34\ub2ac\ub3c4 \ub4e4\uc5b4\uac04\ub2e4. \uc0ac\uc9c4 \uc18d \uae30\ud638\ub97c \ub2e8\uc21c\ud55c \uac80\uc740\uc0c9 \uadf8\ub9bc\uc73c\ub85c \uc778\uc2dd\ud55c \ub4a4 \ub05d\ub0b4\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uc5b4\ub290 \uc704\uce58\uc758 \uce78\uc744 \uc5b4\ub5a4 \uc21c\uc11c\ub85c \uc77d\uc744\uc9c0 \ud30c\uc545\ud558\ub294 \uc5ec\ub7ec \uc7a5\uce58\uac00 \uc788\ub294 \uc148\uc774\ub2e4. QR \ucf54\ub4dc\uc758 \uce78 \ud558\ub098\ub97c \ubaa8\ub4c8\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \uc5ec\ub7ec \uce78\uc5d0 \uac78\uccd0 \ub370\uc774\ud130\ub97c \ubc30\uce58\ud558\uba74 \uae00\uacfc \uc22b\uc790 \ub4f1\uc744 \ub098\ud0c0\ub0bc \uc218 \uc788\ub2e4. \uc0ac\ub78c\uc774 \ud55c \uce78\uc744 \ubcf4\uace0 \uae00\uc790 \ud558\ub098\ub97c \uc77d\ub294 \ubc29\uc2dd\uc740 \uc544\ub2c8\ub2e4. \uc815\ud574\uc9c4 \uaddc\uce59\uc5d0 \ub530\ub77c \ubaa8\uc778 \uac12\ub4e4\uc744 \ud574\uc11d\ud574\uc57c \ud55c\ub2e4. \uc8fc\uc18c\uac00 \ub4e4\uc5b4 \uc788\ub294 \ucf54\ub4dc\ub77c\uba74 \uc77d\uc740 \uacb0\uacfc\ub294 \ubcf4\ud1b5 \uc9e7\uc740 \uc6f9 \uc8fc\uc18c \uac19\uc740 \ubb38\uc790\uc5f4\uc774\ub2e4. \ucf54\ub4dc \uc548\uc5d0 \uc6f9\uc0ac\uc774\ud2b8\uc758 \ubaa8\ub4e0 \ud654\uba74\uc774 \uc555\ucd95\ub418\uc5b4 \ub4e4\uc5b4 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc8fc\uc18c\ub97c \uc801\uc740 \uc885\uc774\ub97c \ubc1b\uc740 \ub4a4 \uadf8 \uc7a5\uc18c\ub85c \ucc3e\uc544\uac00\ub294 \uac83\ucc98\ub7fc, \ubb38\uc790\uc5f4\uc744 \uc77d\ub294 \ub2e8\uacc4\uc640 \uc778\ud130\ub137\uc73c\ub85c \uc2e4\uc81c \ub0b4\uc6a9\uc744 \uc5ec\ub294 \ub2e8\uacc4\uac00 \uc774\uc5b4\uc9c4\ub2e4. QR \ucf54\ub4dc\uc5d0\ub294 \ud06c\uae30\uc758 \ub2e8\uacc4\uac00 \uc788\ub2e4. \ub2f4\uc744 \ub370\uc774\ud130\uac00 \ub9ce\uc544\uc9c0\uac70\ub098 \ub354 \ub9ce\uc740 \uc624\ub958 \uc815\uc815 \uc815\ubcf4\ub97c \ub123\uc5b4\uc57c \ud558\uba74 \ud544\uc694\ud55c \uce78 \uc218\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc791\uc740 \ub3c4\ud615 \ud558\ub098\uc5d0 \ubb34\uc5c7\uc774\ub4e0 \ubb34\ud55c\ud788 \ub123\uc744 \uc218\ub294 \uc5c6\ub2e4. \uc77d\uae30 \uc27d\uac8c \uc778\uc1c4\ud560 \ud06c\uae30\uc640\ub3c4 \uad00\uacc4\uac00 \uc788\ub2e4. \uac19\uc740 \uc885\uc774 \uba74\uc801\uc5d0 \uce78\uc744 \ub354 \ucd18\ucd18\ud558\uac8c \ub123\uc73c\uba74 \uce74\uba54\ub77c\uac00 \uac01 \uce78\uc744 \uad6c\ubcc4\ud558\uae30 \uc5b4\ub824\uc6cc\uc9c8 \uc218 \uc788\ub2e4. \ud734\ub300\uc804\ud654\uc758 \uc131\ub2a5\uacfc \ube5b, \uc778\uc1c4 \uc0c1\ud0dc\ub3c4 \uc601\ud5a5\uc744 \uc900\ub2e4. \ub370\uc774\ud130\uac00 \ub4e4\uc5b4\uac08 \uc774\ub860\uc801\uc778 \uacf5\uac04\uacfc \uc0ac\ub78c\uc774 \ud3b8\ud558\uac8c \ube44\ucd94\uc5b4 \uc77d\ub294 \uc2e4\uc81c \uc870\uac74\uc744 \ud568\uaed8 \uace0\ub824\ud574\uc57c \ud55c\ub2e4. QR \ucf54\ub4dc\uc5d0\ub294 \uc6d0\ub798 \ub370\uc774\ud130\uc640 \ud568\uaed8 \uc624\ub958 \uc815\uc815\uc744 \uc704\ud55c \uc815\ubcf4\uac00 \ub4e4\uc5b4\uac04\ub2e4. \ud655\uc778\ud55c \uad6c\ud604\uc740 \ub9ac\ub4dc-\uc194\ub85c\ubaac\uc774\ub77c\ub294 \uc624\ub958 \uc815\uc815 \ubc29\ubc95\uc744 \uc0ac\uc6a9\ud55c\ub2e4. \uc774\ub984\uc744 \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc77c\ubd80 \uc815\ubcf4\uac00 \uc190\uc0c1\ub418\uc5b4\ub3c4 \uc6d0\ub798 \uac12\uc744 \ubcf5\uc6d0\ud560 \uc5ec\uc9c0\ub97c \ub450\ub294 \uc7a5\uce58\ub85c \uc774\ud574\ud558\uba74 \ub41c\ub2e4. \uc815\uc815\uc758 \uc218\uc900\ub3c4 \uc5ec\ub7ec \ub2e8\uacc4\ub2e4. \ubcf5\uc6d0\uc5d0 \ud544\uc694\ud55c \uc815\ubcf4\ub97c \ub354 \ub2f4\uc73c\uba74 \uadf8\ub9cc\ud07c \uc0ac\uc6a9\ud560 \uacf5\uac04\uacfc\uc758 \uad00\uacc4\uac00 \uc0dd\uae34\ub2e4. \ub530\ub77c\uc11c \ucf54\ub4dc\ub294 \uc870\uae08 \uac00\ub824\uc838\ub3c4 \ubc18\ub4dc\uc2dc \uc77d\ud78c\ub2e4\ub294 \ubcf4\uc99d\uc11c\ub294 \uc544\ub2c8\ub2e4. \uc5b4\ub290 \ubd80\ubd84\uc774 \uc5bc\ub9c8\ub098 \uc190\uc0c1\ub418\uc5c8\ub294\uc9c0, \uc0ac\uc9c4\uc774 \uc5b4\ub5a4 \uc0c1\ud0dc\uc778\uc9c0\uc5d0 \ub530\ub77c \uacb0\uacfc\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \ud070 \uc704\uce58 \ud45c\uc9c0\ub97c \ubaa8\ub450 \uc9c0\uc6cc\ub3c4 \uad1c\ucc2e\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ub370\uc774\ud130\ub97c \uadf8\ub300\ub85c \uce78\uc5d0 \ub193\uc73c\uba74 \uc6b0\uc5f0\ud788 \uc77d\uae30 \uae4c\ub2e4\ub85c\uc6b4 \ubb34\ub2ac\uac00 \uc0dd\uae38 \uc218 \uc788\ub2e4. \ud655\uc778\ud55c \ud504\ub85c\uadf8\ub7a8\uc740 \uc5ec\ub7ec \ub9c8\uc2a4\ud06c\ub97c \uc801\uc6a9\ud574 \ubcf4\uace0, \ud070 \ub369\uc5b4\ub9ac\ub098 \ubc18\ubcf5 \ub4f1 \ubd88\ub9ac\ud55c \ud328\ud134\uc5d0 \uc810\uc218\ub97c \ub9e4\uaca8 \ub354 \uc801\ud569\ud55c \uacb0\uacfc\ub97c \uace0\ub978\ub2e4. \uc5ec\uae30\uc11c \ub9c8\uc2a4\ud06c\ub294 \ub370\uc774\ud130\ub97c \uc815\ud574\uc9c4 \uaddc\uce59\uc73c\ub85c \ubc14\uafb8\ub294 \uacfc\uc815\uc774\ub2e4. \ube44\ubc00\ubc88\ud638\ub85c \ub0b4\uc6a9\uc744 \uac10\ucd94\ub294 \uc554\ud638\ud654\uc640\ub294 \ubaa9\uc801\uc774 \ub2e4\ub974\ub2e4. \uc77d\ub294 \ucabd\ub3c4 \uc815\ud574\uc9c4 \uc815\ubcf4\ub97c \ubcf4\uace0 \uaddc\uce59\uc744 \ub418\ub3cc\ub9b4 \uc218 \uc788\ub2e4. \uac80\uc740 \uce78\uc774 \ub4a4\uc11e\uc778 \uac83\ucc98\ub7fc \ubcf4\uc5ec\ub3c4 \uc544\ubb34\ub807\uac8c\ub098 \ud769\ubfcc\ub9b0 \uadf8\ub9bc\uc774 \uc544\ub2cc \uc774\uc720\ub2e4. \ub0b4\uc6a9\uc744 \ub2f4\ub294 \uc77c\uacfc \uadf8 \ub0b4\uc6a9\uc744 \uc798 \uc77d\ud788\ub3c4\ub85d \ubc30\uc5f4\ud558\ub294 \uc77c\uc774 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4. \uae30\uacc4\uac00 \ucf54\ub4dc\ub97c \uc815\ud655\ud788 \uc77d\uc5c8\ub2e4\uace0 \uc5f0\uacb0\ub41c \uc8fc\uc18c\uae4c\uc9c0 \uc88b\uc740 \uacf3\uc774\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc624\ub958 \uc815\uc815\uc740 \ubb34\ub2ac\uac00 \ub9dd\uac00\uc838 \uc0dd\uae30\ub294 \ubb38\uc81c\ub97c \ub2e4\ub8e8\uc9c0, \uc8fc\uc18c\ub97c \ub9cc\ub4e0 \uc0ac\ub78c\uc758 \uc758\ub3c4\ub97c \uc2ec\uc0ac\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uae00\uc528\uac00 \uc120\uba85\ud55c \uc548\ub0b4\ubb38\ub3c4 \ub0b4\uc6a9\uc740 \ub530\ub85c \uc0b4\ud3b4\uc57c \ud558\ub294 \uac83\uacfc \uac19\ub2e4. \uc8fc\uc18c\ub97c \ud655\uc778\ud558\ub294 \uae30\ub2a5\uc774 \ubcf4\uc774\uba74 \uc5b4\ub514\ub85c \uc5f0\uacb0\ub418\ub294\uc9c0 \ubcf4\uace0 \uc5f4\uba74 \ub41c\ub2e4. \uc774\uac83\uc740 QR \ucf54\ub4dc\uac00 \ud2b9\ubcc4\ud788 \uc218\uc0c1\ud558\ub2e4\ub294 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub77c \uc77d\uae30\uc640 \uc2e0\ub8b0\ub97c \uad6c\ubd84\ud558\ub294 \uae30\ubcf8\uc801\uc778 \ud0dc\ub3c4\ub2e4. \ud654\uba74\uc5d0\uc11c \ubb38\uc790\uc5f4\uc744 \uc5bb\ub294 \uae30\uc220\uacfc \uadf8 \ub4a4\uc758 \uc11c\ube44\uc2a4\ub294 \uc11c\ub85c \ub2e4\ub978 \uc5ed\ud560\uc744 \ub9e1\ub294\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uce74\ud398\uc5d0\uc11c \ud734\ub300\uc804\ud654\ub85c \uba54\ub274\ub97c \ud655\uc778\ud558\ub294 \ubd84\uc704\uae30\ub97c \ub2f4\uc558\ub2e4. \uac00\uc9dc QR \ubb34\ub2ac\ub97c \uc2e4\uc81c \uc791\ub3d9\ud558\ub294 \ucf54\ub4dc\ucc98\ub7fc \uc81c\uc2dc\ud558\uc9c0 \uc54a\ub3c4\ub85d \uce74\ub4dc\uc758 \ub4b7\uba74\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ucf54\ub4dc\uc758 \uc0dd\uae40\uc0c8\ub97c \uc7ac\ud604\ud55c \uae30\uc220 \ub3c4\ud310\uc774 \uc544\ub2c8\ub77c \uc4f0\uc784\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc7a5\uba74\uc774\ub2e4. \uc774\uc81c QR \ucf54\ub4dc\ub97c \ub9cc\ub098\uba74 \uc138 \ubaa8\uc11c\ub9ac\uc758 \ud070 \ub124\ubaa8\uc640 \ub098\uba38\uc9c0 \uc791\uc740 \uce78\ub4e4\uc744 \ub098\ub204\uc5b4 \ubcf4\uc790. \uc5b4\ub514\uc5d0 \uc788\ub294\uc9c0 \uc54c\ub824 \uc8fc\ub294 \ud45c\uc9c0\uc640 \ub0b4\uc6a9\uc744 \ub2f4\ub294 \ubd80\ubd84, \uc190\uc0c1\uc744 \uacac\ub514\uae30 \uc704\ud55c \uc815\ubcf4\uac00 \ud568\uaed8 \uc788\ub2e4. \uc791\uc740 \ubb34\ub2ac \ud558\ub098\ub97c \uc77d\ub294 \uc21c\uac04\uc5d0\ub3c4 \uae30\uacc4\uac00 \uae38\uc744 \uc783\uc9c0 \uc54a\uac8c \ud558\ub294 \uc5ec\ub7ec \uc57d\uc18d\uc774 \uc870\uc6a9\ud788 \uc791\ub3d9\ud558\uace0 \uc788\ub2e4."}, {"id": "sqlite-small-database", "title": "SQLite \u2014 \uc571\uc758 \uae30\ub85d\uc740 \uc5b4\ub514\uc5d0 \ubaa8\uc5ec \uc788\uc744\uae4c", "summary": "\uac00\uc0c1\uc758 \uc694\ub9ac \uae30\ub85d \uc571\uc744 \ud1b5\ud574 \ud45c\u00b7\uc9c8\uc758\u00b7\ubcc0\uacbd \ud655\uc815\uacfc \ub85c\uceec \ub370\uc774\ud130\ubca0\uc774\uc2a4\uc758 \uc5ed\ud560\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\ub370\uc774\ud130\uc640 \uae30\ub85d", "categories": ["digital"], "url": "stories/sqlite-small-database/index.html", "image": "../media/sqlite-small-database.png", "alt": "\uc2dd\uc7ac\ub8cc\uc640 \uc694\ub9ac \ub178\ud2b8, \uae30\uae30 \uacc1\uc5d0\uc11c \uae30\ub85d\uc744 \uc815\ub9ac\ud558\ub294 \uc0ac\ub78c\uc758 AI \ube44\uc720 \uc7a5\uba74.", "text": "SQLite \u2014 \uc571\uc758 \uae30\ub85d\uc740 \uc5b4\ub514\uc5d0 \ubaa8\uc5ec \uc788\uc744\uae4c \uc791\uc740 \ub370\uc774\ud130\ubca0\uc774\uc2a4\uac00 \uc815\ubcf4\ub97c \uc815\ub9ac\ud558\uace0 \ub2e4\uc2dc \ucc3e\ub294 \ubc29\ubc95 \uac00\uc0c1\uc758 \uc694\ub9ac \uae30\ub85d \uc571\uc744 \ud1b5\ud574 \ud45c\u00b7\uc9c8\uc758\u00b7\ubcc0\uacbd \ud655\uc815\uacfc \ub85c\uceec \ub370\uc774\ud130\ubca0\uc774\uc2a4\uc758 \uc5ed\ud560\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ub370\uc774\ud130\uc640 \uae30\ub85d \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \uc694\ub9ac \uae30\ub85d \uc571\uc5d0 \uc88b\uc544\ud558\ub294 \uba54\ub274\ub97c \ud558\ub098 \uc800\uc7a5\ud55c\ub2e4. \ub2e4\uc74c\uc5d0\ub294 \uc774\ub984\uc73c\ub85c \ucc3e\uace0, \uc870\ub9ac \uc2dc\uac04\uc774 \uc9e7\uc740 \uac83\ub9cc \uace8\ub77c \ubcf8\ub2e4. \ud654\uba74\uc5d0\ub294 \uba87 \ubc88\uc758 \ud130\uce58\ub9cc \uc788\uc9c0\ub9cc \uadf8 \ub4a4\uc5d0\uc11c\ub294 \uae30\ub85d\uc744 \uc815\ub9ac\ud558\uace0 \ub2e4\uc2dc \uaebc\ub0b4\ub294 \uc77c\uc774 \ud544\uc694\ud558\ub2e4. \uc571\uc758 \uae30\uc5b5\uc740 \uc5b4\ub5bb\uac8c \uad00\ub9ac\ub420\uae4c. SQLite\ub294 \uc774\ub7f0 \ub0b4\ubd80 \uc800\uc7a5\uc5d0 \uc4f0\uc77c \uc218 \uc788\ub294 \uc791\uc740 \ub370\uc774\ud130\ubca0\uc774\uc2a4 \uae30\uc220\uc774\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc2e4\uc81c \ud2b9\uc815 \uc694\ub9ac \uc571\uc744 \ubd84\uc11d\ud55c \uac83\uc774 \uc544\ub2c8\ub77c \uac00\uc0c1\uc758 \uae30\ub85d\uc7a5\uc744 \ud1b5\ud574 \uc6d0\ub9ac\ub97c \uc0b4\ud3b4\ubcf8\ub2e4. \ucf54\ub4dc\ub97c \ubc30\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uc800\uc7a5\ub41c \uc790\ub8cc\uc5d0 \uc9c8\ubb38\uc744 \ub358\uc9c0\ub294 \ubc29\uc2dd\uc774\ub77c\ub294 \uc810\uc740 \ucda9\ubd84\ud788 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ub178\ud2b8\uc5d0 \ub41c\uc7a5\uad6d, 20\ubd84\uc774\ub77c\uace0 \uc801\uc73c\uba74 \uc0ac\ub78c\uc740 \uc774\ub984\uacfc \uc2dc\uac04\uc744 \uc54c\uc544\uc11c \ub098\ub208\ub2e4. \ucef4\ud4e8\ud130\uc5d0\uc11c \uac19\uc740 \uc77c\uc744 \ud558\ub824\uba74 \uc5b4\ub5a4 \uac12\uc774 \uc774\ub984\uc774\uace0 \uc5b4\ub5a4 \uac12\uc774 \uc870\ub9ac \uc2dc\uac04\uc778\uc9c0 \uc815\ub9ac\ud574\uc57c \ud55c\ub2e4. \ub370\uc774\ud130\ubca0\uc774\uc2a4\uc5d0\uc11c\ub294 \ud45c\uc758 \uc5f4\uc744 \uc774\uc6a9\ud574 \uc774\ub7f0 \ud56d\ubaa9\uc744 \uad6c\ubd84\ud560 \uc218 \uc788\ub2e4. \ud55c \ud589\uc5d0 \ud558\ub098\uc758 \uae30\ub85d\uc744 \ub123\uc73c\uba74 \ube44\uc2b7\ud55c \ud615\uc2dd\uc758 \uc815\ubcf4\uac00 \uacc4\uc18d \uc313\uc778\ub2e4. \ubb3c\ub860 \uc5b4\ub5a4 \ud56d\ubaa9\uc744 \ub458\uc9c0\ub294 \uc571\uc744 \uc124\uacc4\ud558\ub294 \uc0ac\ub78c\uc758 \uc120\ud0dd\uc774\ub2e4. SQLite\uac00 \uc694\ub9ac\uc5d0 \ud544\uc694\ud55c \ubaa8\ub4e0 \uc815\ubcf4\ub97c \uc2a4\uc2a4\ub85c \uc815\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc798 \uc815\ub9ac\ud560 \uad6c\uc870\uc640 \uadf8 \uc548\uc5d0 \ub123\uc744 \ub0b4\uc6a9\uc740 \uc0ac\ub78c\uc774 \ub9c8\ub828\ud574\uc57c \ud55c\ub2e4. \uc0ac\uc6a9\uc790\ub294 \uc608\uc05c \uce74\ub4dc\ub098 \ubaa9\ub85d\uc73c\ub85c \uae30\ub85d\uc744 \ubcfc \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \ub0b4\ubd80\uc758 \uc800\uc7a5 \ubc29\uc2dd\uc774 \ud654\uba74\uc758 \uce74\ub4dc\uc640 \ub611\uac19\uc740 \ubaa8\uc591\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uae30\ub85d\uc744 \ud45c\ub85c \uad00\ub9ac\ud558\uace0 \ud544\uc694\ud55c \uacb0\uacfc\ub9cc \uaebc\ub0b4 \uc6d0\ud558\ub294 \ud654\uba74\uc73c\ub85c \ubcf4\uc5ec \uc904 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \ub370\uc774\ud130\ubca0\uc774\uc2a4\ub77c\ub294 \ub9d0\uc774 \ubd99\uc5c8\ub2e4\uace0 \ud56d\uc0c1 \ucee4\ub2e4\ub780 \ud45c \ud654\uba74\uc744 \uc9c1\uc811 \ub2e4\ub8e8\uc5b4\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub9ce\uc740 \uacbd\uc6b0 \uc0ac\uc6a9\uc790\ub294 \uc800\uc7a5\uacfc \uac80\uc0c9 \ubc84\ud2bc\ub9cc \ub9cc\ub09c\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \ub514\uc790\uc778\uacfc \uadf8 \ub4a4\uc758 \uc815\ubcf4 \uc870\uc9c1\uc740 \uc11c\ub85c \ub2e4\ub978 \uc5ed\ud560\uc744 \ub9e1\uace0 \uc788\ub2e4. \ub370\uc774\ud130\ubca0\uc774\uc2a4\uc5d0\ub294 \uc5b4\ub5a4 \uae30\ub85d\uc744 \uc6d0\ud558\ub294\uc9c0 \uc9c8\uc758\ud560 \uc218 \uc788\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc870\ub9ac \uc2dc\uac04\uc774 20\ubd84 \uc774\ud558\uc778 \uba54\ub274\ub97c \ucc3e\uc544 \ub2ec\ub77c\uace0 \ud558\ub294 \uc2dd\uc774\ub2e4. \uc2e4\uc81c \ud504\ub85c\uadf8\ub7a8\uc740 \uc774\ub97c SQL\uc774\ub77c\ub294 \uc5b8\uc5b4\uc758 \uc815\ud574\uc9c4 \ud615\ud0dc\ub85c \uc804\ub2ec\ud560 \uc218 \uc788\ub2e4. \uc5ec\uae30\uc11c \uc911\uc694\ud55c \uac83\uc740 \ubb38\ubc95\uc744 \uc678\uc6b0\ub294 \uc77c\uc774 \uc544\ub2c8\ub2e4. \uc800\uc7a5\ud55c \ubaa8\ub4e0 \uae30\ub85d\uc744 \uc0ac\ub78c\uc5d0\uac8c \ubcf4\uc5ec \uc8fc\uace0 \ud558\ub098\uc529 \uace8\ub77c\ub0b4\uac8c \ud558\ub294 \ub300\uc2e0, \ud544\uc694\ud55c \uc870\uac74\uc744 \ub370\uc774\ud130\uc5d0 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc774\ub2e4. \uae30\ub85d\uc774 \ub9ce\uc544\uc9c8\uc218\ub85d \uc774\ub7f0 \uc815\ub9ac\uc640 \uc9c8\ubb38\uc758 \ubc29\uc2dd\uc774 \uc0ac\uc6a9 \uacbd\ud5d8\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4. \ud30c\uc774\uc36c\uc758 \uacf5\uc2dd \ubb38\uc11c\ub294 SQLite\ub97c \ubcc4\ub3c4\uc758 \uc11c\ubc84 \ud504\ub85c\uc138\uc2a4\uac00 \ud544\uc694\ud558\uc9c0 \uc54a\uc740 \uac00\ubcbc\uc6b4 \ub514\uc2a4\ud06c \uae30\ubc18 \ub370\uc774\ud130\ubca0\uc774\uc2a4\ub85c \uc18c\uac1c\ud55c\ub2e4. \ub370\uc774\ud130\ubca0\uc774\uc2a4\ub97c \ub5a0\uc62c\ub9b4 \ub54c \ubc18\ub4dc\uc2dc \uba40\ub9ac \ub5a8\uc5b4\uc9c4 \ud070 \uc11c\ubc84\uc2e4\ubd80\ud130 \uc0c1\uc0c1\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4\ub294 \ub73b\uc774\ub2e4. \uc571\uc774 \uc790\uccb4 \uae30\ub85d\uc744 \uad00\ub9ac\ud558\ub294 \ub370 \uc774\ub97c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4. \ub370\uc774\ud130\uc640 \ud544\uc694\ud55c \uae30\ub2a5\uc774 \uae30\uae30\uc5d0 \uc900\ube44\ub418\uc5b4 \uc788\ub2e4\uba74 \uc778\ud130\ub137\uc774 \uc5c6\ub294 \uc0c1\ud669\uc5d0\uc11c\ub3c4 \uc77c\ubd80 \uae30\ub2a5\uc744 \uc81c\uacf5\ud558\ub294 \uad6c\uc870\ub97c \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \uc571\uc774 SQLite\ub97c \uc4f0\uac70\ub098 \uc5b8\uc81c\ub098 \uc624\ud504\ub77c\uc778\uc73c\ub85c \uc791\ub3d9\ud55c\ub2e4\ub294 \ub9d0\uc740 \uc544\ub2c8\ub2e4. \uc571\uc758 \uc124\uacc4\uc640 \ub2e4\ub978 \uc11c\ube44\uc2a4 \uc758\uc874\uc131\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c4\ub2e4. \ub370\uc774\ud130\ub97c \uace0\uce58\ub294 \uacfc\uc815\uc5d0\ub294 \uc5ec\ub7ec \ubcc0\uacbd\uc744 \ud558\ub098\uc758 \uc791\uc5c5 \ub2e8\uc704\ub85c \ub2e4\ub8e8\ub294 \uacbd\uc6b0\uac00 \uc788\ub2e4. \ud2b8\ub79c\uc7ad\uc158\uc774\ub77c\ub294 \ub9d0\uc774\ub2e4. \uc900\ube44\ud55c \ubcc0\uacbd\uc744 \ud655\uc815\ud558\uac70\ub098, \uc544\uc9c1 \ud655\uc815\ud558\uc9c0 \uc54a\uc740 \uc791\uc5c5\uc744 \ub418\ub3cc\ub9ac\ub294 \uae30\ub2a5\uc744 \uc774\uc6a9\ud560 \uc218 \uc788\ub2e4. \ubb38\uc11c\uc758 \ucd08\uc548\uc744 \ud655\uc778\ud55c \ub4a4 \uc800\uc7a5\ud558\ub294 \uacbd\ud5d8\uacfc \ub2ee\uc740 \ubd80\ubd84\uc774 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc774 \ube44\uc720\uac00 \ud504\ub85c\uadf8\ub7a8\uc758 \ubaa8\ub4e0 \ub3d9\uc791\uc744 \uc124\uba85\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5b4\ub5a4 \uc2dc\uc810\uc5d0 \ubb34\uc5c7\uc744 \ud655\uc815\ud560\uc9c0\ub294 \uc0ac\uc6a9\ud558\ub294 \ubc29\uc2dd\uacfc \uc124\uc815\uc5d0 \uad00\uacc4\uac00 \uc788\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ubcc0\uacbd\uc744 \uc815\ub9ac\ud558\uace0 \uc801\uc6a9\ud560 \uaddc\uce59\uc774 \uc788\uc73c\uba70, \ud654\uba74\uc5d0 \ud55c \ubc88 \uac12\uc744 \ub123\ub294 \ud589\uc704\uc640 \ub0b4\ubd80 \uae30\ub85d\uc744 \uc77c\uad00\ub418\uac8c \uad00\ub9ac\ud558\ub294 \uc77c\uc774 \uac19\uc9c0 \uc54a\ub2e4\ub294 \uc810\uc774\ub2e4. \uc694\ub9ac \uc774\ub984\uacfc \uc2dd\uc7ac\ub8cc \uc815\ubcf4\ub97c \uac01\uac01 \uad00\ub9ac\ud558\uace0 \uad00\uacc4\ub97c \ub9fa\ub294 \ubc29\uc2dd\ub3c4 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uac19\uc740 \uc7ac\ub8cc\uc758 \uc774\ub984\uc744 \ub9e4\ubc88 \ub2e4\ub978 \ucca0\uc790\ub85c \uc801\ub294 \ubb38\uc81c\ub97c \uc904\uc774\uace0, \uc5b4\ub5a4 \uba54\ub274\uc5d0 \uc4f0\uc600\ub294\uc9c0 \ucc3e\uc544\ubcfc \uc218 \uc788\ub2e4. \uc774\uac83\uc740 \ub370\uc774\ud130 \uad6c\uc870\ub97c \uc124\uba85\ud558\uae30 \uc704\ud55c \uac00\uc0c1 \uc608\ub2e4. \uc2e4\uc81c \uc571\uc5d0\uc11c \ud45c\ub97c \uc5b4\ub5bb\uac8c \ub098\ub20c\uc9c0\ub294 \uc790\ub8cc\uc758 \uc131\uaca9\uacfc \ud544\uc694\uc5d0 \ub530\ub77c \uc815\ud55c\ub2e4. \ubaa8\ub4e0 \uae30\ub85d\uc744 \uc798\uac8c \ub098\ub204\ub294 \uac83\uc774 \uc5b8\uc81c\ub098 \ucd5c\uc120\uc740 \uc544\ub2c8\uace0, \ud55c \ud45c\uc5d0 \uc804\ubd80 \uc801\ub294 \uac83\uc774 \uc5b8\uc81c\ub098 \uac04\ud3b8\ud55c \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uc798 \uc4f0\ub294 \ub370\uc774\ud130\ubca0\uc774\uc2a4 \ub4a4\uc5d0\ub294 \ubb34\uc5c7\uc744 \uac19\uac8c \ubcf4\uace0 \uc5b4\ub5a4 \uad00\uacc4\ub97c \ub0a8\uae38\uc9c0\uc5d0 \ub300\ud55c \ud310\ub2e8\uc774 \uc788\ub2e4. \ub0b4 \uae30\uae30\uc5d0 \uae30\ub85d\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ub2e4\ub978 \uae30\uae30\uc5d0\ub3c4 \uc790\ub3d9\uc73c\ub85c \ub098\ud0c0\ub098\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5ec\ub7ec \uae30\uae30\uc5d0\uc11c \ud568\uaed8 \uc4f0\ub824\uba74 \ub3d9\uae30\ud654 \uac19\uc740 \ubcc4\ub3c4\uc758 \uc124\uacc4\uac00 \ud544\uc694\ud558\ub2e4. \ub370\uc774\ud130\ubca0\uc774\uc2a4 \uae30\uc220\uc758 \uc774\ub984 \ud558\ub098\uac00 \uc774\ub7f0 \ubaa8\ub4e0 \uc11c\ube44\uc2a4\ub97c \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub610 \ud30c\uc77c\uc5d0 \uae30\ub85d\uc774 \uc788\ub2e4\ub294 \uac83\uacfc \uc548\uc804\ud55c \ubc31\uc5c5\uc774 \ub530\ub85c \uc788\ub2e4\ub294 \uac83\ub3c4 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ud30c\uc774\uc36c \uacf5\uc2dd \ubb38\uc11c\uc5d0\ub294 \ub370\uc774\ud130\ubca0\uc774\uc2a4 \ubc31\uc5c5 \uae30\ub2a5\ub3c4 \uc124\uba85\ub418\uc5b4 \uc788\ub2e4. \uc774\ub294 \ubc31\uc5c5\uc744 \ub9c8\ub828\ud560 \uc218 \uc788\ub294 \ubc29\ubc95\uc774 \uc788\ub2e4\ub294 \ub73b\uc774\uc9c0, SQLite\ub97c \uc0ac\uc6a9\ud558\ub294 \ubaa8\ub4e0 \uc571\uc774 \uac19\uc740 \ubcf4\uad00 \uc815\ucc45\uc744 \uc790\ub3d9\uc73c\ub85c \uac16\ub294\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc694\ub9ac \ub178\ud2b8\uc640 \uae30\uae30\ub97c \ub193\uace0 \uae30\ub85d\uc744 \uc815\ub9ac\ud558\ub294 \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c SQLite\uc758 \ud654\uba74\uc774\ub098 \ud2b9\uc815 \uc571\uc758 \uae30\ub2a5\uc744 \uc7ac\ud604\ud558\uc9c0 \uc54a\uc558\ub2e4. \uc870\uc6a9\ud788 \uc790\ub8cc\ub97c \ubaa8\uc73c\uace0 \ub2e4\uc2dc \ucc3e\ub294 \uc77c\uc758 \ubd84\uc704\uae30\ub97c \ub2f4\uc558\ub2e4. SQLite\uc758 \uc7ac\ubbf8\ub294 \ud06c\uace0 \ubcf5\uc7a1\ud55c \uae30\uc220\uc774 \uc788\uc5b4\uc57c\ub9cc \ub370\uc774\ud130\ubca0\uc774\uc2a4\ub77c\ub294 \uc0dd\uac01\uc744 \ubc14\uafb8\uc5b4 \uc900\ub2e4\ub294 \ub370 \uc788\ub2e4. \uc791\uc740 \uae30\ub85d\uc5d0\ub3c4 \uad6c\uc870\uc640 \uc9c8\ubb38, \ubcc0\uacbd\uc744 \ub2e4\ub8e8\ub294 \uc57d\uc18d\uc774 \ud544\uc694\ud558\ub2e4. \ub2e4\uc74c\uc5d0 \uc571\uc5d0\uc11c \uc624\ub798\uc804 \uc800\uc7a5\ud55c \ud56d\ubaa9\uc744 \ucc3e\uc73c\uba74 \uadf8 \uac04\ub2e8\ud55c \uacb0\uacfc \ub4a4\uc5d0 \uc815\ubcf4\ub97c \uc815\ub9ac\ud574 \ub454 \ubc29\uc2dd\ub3c4 \uc7a0\uae50 \ub5a0\uc62c\ub824 \ubcfc \uc218 \uc788\ub2e4."}, {"id": "svg-shapes-not-fixed-pixels", "title": "SVG \u2014 \uc810 \ub300\uc2e0 \uc120\uc758 \ubaa8\uc591\uc744 \uae30\ub85d\ud558\uba74", "summary": "\ubca1\ud130 \ub3c4\ud615\uacfc \ud53d\uc140 \uc774\ubbf8\uc9c0\uc758 \ucc28\uc774\uc5d0\uc11c SVG\uc758 \ud655\ub300\u00b7\uad6c\uc131\u00b7\ud55c\uacc4\ub97c \uc27d\uac8c \uc774\ud574\ud569\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\ub370\uc774\ud130\uc640 \uae30\ub85d", "categories": ["digital"], "url": "stories/svg-shapes-not-fixed-pixels/index.html", "image": "../media/svg-shapes-not-fixed-pixels.png", "alt": "\uc885\uc774 \uc704 \ub3c4\ud615\uacfc \uace1\uc120\uc744 \uc0b4\ud3b4\ubcf4\uba70 \uadf8\ub9bc\uc744 \ub9cc\ub4dc\ub294 \uc791\uc5c5 \uc7a5\uba74\uc758 \uc0bd\ud654.", "text": "SVG \u2014 \uc810 \ub300\uc2e0 \uc120\uc758 \ubaa8\uc591\uc744 \uae30\ub85d\ud558\uba74 \uc791\uc740 \uc544\uc774\ucf58\uc744 \ud06c\uac8c \uc368\ub3c4 \uc120\uc774 \uc774\uc5b4\uc9c0\ub294 \uc774\uc720 \ubca1\ud130 \ub3c4\ud615\uacfc \ud53d\uc140 \uc774\ubbf8\uc9c0\uc758 \ucc28\uc774\uc5d0\uc11c SVG\uc758 \ud655\ub300\u00b7\uad6c\uc131\u00b7\ud55c\uacc4\ub97c \uc27d\uac8c \uc774\ud574\ud569\ub2c8\ub2e4. \ub370\uc774\ud130\uc640 \uae30\ub85d \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \uc791\uc740 \uc544\uc774\ucf58\uc744 \ud06c\uac8c \ub298\ub838\ub354\ub2c8 \uac00\uc7a5\uc790\ub9ac\uac00 \ub124\ubaa8 \uacc4\ub2e8\ucc98\ub7fc \ubcf4\uc778\ub2e4. \ubc18\uba74 \uc5b4\ub5a4 \uadf8\ub9bc\uc740 \uac19\uc740 \uc77c\uc744 \ud574\ub3c4 \uc120\uc774 \ub9e4\ub048\ud558\uac8c \uc774\uc5b4\uc9c4\ub2e4. \ub458 \ub2e4 \ud654\uba74\uc758 \uadf8\ub9bc\uc778\ub370 \uc65c \ud655\ub300\ud588\uc744 \ub54c \ub2e4\ub974\uac8c \ubcf4\uc77c\uae4c. \uc774\ubbf8\uc9c0\uac00 \ubb34\uc5c7\uc744 \uae30\ub85d\ud558\uace0 \uc788\ub294\uc9c0\uac00 \ub2e4\ub974\uae30 \ub54c\ubb38\uc774\ub2e4. \ud53d\uc140\ub9c8\ub2e4\uc758 \uc0c9\uc744 \uc800\uc7a5\ud558\ub294 \ubc29\uc2dd\uacfc \uc120\uacfc \ub3c4\ud615\uc744 \uc124\uba85\ud558\ub294 \ubc29\uc2dd\uc774 \uc788\ub2e4. SVG\ub294 \ud6c4\uc790\uc5d0 \uc4f0\uc774\ub294 \ud615\uc2dd\uc774\ub2e4. \uadf8 \uc774\ub984\uc744 \uc54c\uba74 \uc778\ud130\ub137\uc758 \uc791\uc740 \uadf8\ub9bc\uc744 \ubcf4\ub294 \ub208\ub3c4 \uc870\uae08 \ub2ec\ub77c\uc9c4\ub2e4. \uc0ac\uc9c4 \uac19\uc740 \ub798\uc2a4\ud130 \uc774\ubbf8\uc9c0\ub294 \uc815\ud574\uc9c4 \uc218\uc758 \ud53d\uc140\uc5d0 \uc0c9 \uc815\ubcf4\ub97c \ub2f4\ub294\ub2e4. \ucda9\ubd84\ud788 \ud06c\uac8c \ud45c\uc2dc\ud558\uba74 \uc6d0\ub798\uc758 \uc791\uc740 \uc810\ub4e4\uc744 \ub354 \ub113\uc740 \ud654\uba74\uc5d0 \ud45c\ud604\ud574\uc57c \ud55c\ub2e4. \ud504\ub85c\uadf8\ub7a8\uc774 \uc0ac\uc774\uc758 \uac12\uc744 \uacc4\uc0b0\ud574 \ubd80\ub4dc\ub7fd\uac8c \ubcf4\uc774\uac8c \ud560 \uc218\ub294 \uc788\uc5b4\ub3c4 \ucc98\uc74c\uc5d0 \uc5c6\ub358 \ubaa8\ub4e0 \uc138\ubd80\ub97c \ub418\ucc3e\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774\uac83\uc740 \uc0ac\uc9c4\uc774 \ub098\uc05c \ud615\uc2dd\uc774\ub77c\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \ube5b\uacfc \uc9c8\uac10\uc758 \ubcf5\uc7a1\ud55c \ubcc0\ud654\ub97c \ub2f4\ub294 \ub370\ub294 \ud53d\uc140\uc758 \uc0c9\uc744 \uae30\ub85d\ud558\ub294 \ubc29\uc2dd\uc774 \uc798 \ub9de\ub294\ub2e4. \uc5b4\ub5a4 \uadf8\ub9bc\uc778\uc9c0\uc5d0 \ub530\ub77c \ud544\uc694\ud55c \ud45c\ud604\uc774 \ub2e4\ub974\ub2e4. \ud655\ub300\uc758 \uacb0\uacfc \ud558\ub098\ub85c \ubaa8\ub4e0 \uc774\ubbf8\uc9c0\uc758 \uc88b\uace0 \ub098\uc068\uc744 \uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc6d0 \ud55c \uac1c\ub97c \uadf8\ub9b0\ub2e4\uace0 \uc0dd\uac01\ud574 \ubcf4\uc790. \ud654\uba74\uc758 \uc810\ub9c8\ub2e4 \uc0c9\uc744 \ub0a8\uae38 \uc218\ub3c4 \uc788\uc9c0\ub9cc, \uc911\uc2ec\uc774 \uc5b4\ub514\uc774\uace0 \ubc18\uc9c0\ub984\uc774 \uc5bc\ub9c8\uc778\uc9c0 \uc124\uba85\ud560 \uc218\ub3c4 \uc788\ub2e4. \ud6c4\uc790\uc758 \uc815\ubcf4\ub97c \uc54c\uba74 \ub354 \ud070 \ud06c\uae30\uc5d0 \ub9de\ucd94\uc5b4 \uc6d0\uc744 \ub2e4\uc2dc \uadf8\ub9b4 \uc218 \uc788\ub2e4. \uc774\ub294 \ubca1\ud130 \ubc29\uc2dd\uc758 \uccab \uc774\ud574\ub97c \uc704\ud55c \uc608\ub2e4. \uc2e4\uc81c \ub3c4\ud615\uc5d0\ub294 \uc120\uc758 \ub450\uaed8\uc640 \uc0c9, \uc704\uce58 \uac19\uc740 \uc815\ubcf4\ub3c4 \ub4e4\uc5b4\uac04\ub2e4. \uc815\ud574\uc9c4 \uc791\uc740 \uadf8\ub9bc\uc744 \ub2e8\uc21c\ud788 \uc7a1\uc544\ub2f9\uae30\ub294 \ub300\uc2e0, \ubaa8\uc591\uc744 \uc124\uba85\ud55c \ub0b4\uc6a9\uc744 \ub2e4\ub978 \ud06c\uae30\ub85c \uadf8\ub824 \ub0b4\ub294 \ucc28\uc774\uac00 \uc788\ub2e4. \uc774 \ub54c\ubb38\uc5d0 \uc544\uc774\ucf58\uacfc \ub3c4\ud615\uc5d0\uc11c \uc7a5\uc810\uc774 \ub098\ud0c0\ub0a0 \uc218 \uc788\ub2e4. SVG\ub294 XML\uc744 \ubc14\ud0d5\uc73c\ub85c \ud558\ub294 \uc5b8\uc5b4\ub2e4. \uc6d0\uacfc \uc0ac\uac01\ud615, \uac04\ub2e8\ud558\uac70\ub098 \ubcf5\uc7a1\ud55c \uace1\uc120 \uac19\uc740 \uc694\uc18c\ub97c \ud45c\ud604\ud560 \uc218 \uc788\ub2e4. \uc5ec\ub7ec \ub3c4\ud615\uc744 \ubb36\uc5b4 \ud558\ub098\uc758 \uadf8\ub9bc\uc73c\ub85c \uc870\uc9c1\ud558\ub294 \ubc29\ubc95\ub3c4 \uc788\ub2e4. \uc0ac\ub78c\uc774 \ucf54\ub4dc\ub85c \uc9c1\uc811 \uc791\uc131\ud574\uc57c\ub9cc \ud558\ub294 \uac83\uc740 \uc544\ub2c8\uace0 \uc774\ub97c \ub2e4\ub8e8\ub294 \uadf8\ub9bc \ud504\ub85c\uadf8\ub7a8\ub3c4 \uc788\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubb38\ubc95\uc744 \ubc30\uc6b8 \ud544\uc694\uac00 \uc5c6\ub2e4. \uadf8\ub9bc \ud30c\uc77c\uc758 \uc548\ucabd\uc5d0 \uc791\uc740 \uc0c9\uc810\ub9cc \ub4e4\uc5b4 \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ubaa8\uc591\uacfc \uad00\uacc4\ub97c \uc124\uba85\ud558\ub294 \uc815\ubcf4\uac00 \uc788\uc744 \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uac19\uc740 \ud654\uba74\uc758 \uadf8\ub9bc\ub3c4 \uadf8 \uc548\uc5d0 \uc801\uc5b4 \ub454 \ub0b4\uc6a9\uc740 \ub2e4\ub97c \uc218 \uc788\ub2e4. SVG\uc758 \ub3c4\ud615\uc740 \ud45c\uc2dc\ud560 \ud06c\uae30\uc5d0 \ub9de\ucd94\uc5b4 \ub2e4\uc2dc \uadf8\ub9b4 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \ubca1\ud130\ub85c \uc815\uc758\ud55c \uc120\uacfc \uc724\uacfd\uc740 \ub798\uc2a4\ud130 \uc774\ubbf8\uc9c0\ub97c \ub2e8\uc21c\ud788 \ub298\ub9ac\ub294 \uacbd\uc6b0\uc640 \ub2e4\ub974\uac8c \ud655\ub300\ud560 \uc218 \uc788\ub2e4. \uac19\uc740 \ud45c\uc9c0\ub97c \uc791\uc740 \ubc84\ud2bc\uacfc \ud070 \ud654\uba74\uc5d0 \uc0ac\uc6a9\ud560 \ub54c \uc774\ub7f0 \ucc28\uc774\uac00 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc5b4\ub5a4 \ud06c\uae30\uc5d0\uc11c\ub3c4 \ubaa8\ub4e0 \ub514\ud14c\uc77c\uc774 \ub611\uac19\uc774 \ubcf4\uae30 \uc88b\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc544\uc8fc \uc791\uc740 \ud06c\uae30\uc5d0\uc11c\ub294 \ubcf5\uc7a1\ud55c \uc120\uc774 \uad6c\ubcc4\ub418\uc9c0 \uc54a\uc744 \uc218 \uc788\uace0, \ud45c\uc2dc \uc7a5\uce58\uc640 \uadf8\ub9ac\ub294 \ubc29\uc2dd\ub3c4 \uacb0\uacfc\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4. \ub3c4\ud615 \uc815\ubcf4\ub97c \uc720\uc9c0\ud558\ub294 \uc77c\uacfc \uc77d\uae30 \uc88b\uc740 \ub514\uc790\uc778\uc740 \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. MDN\uc740 SVG\uac00 \uc0c9\uc758 \uc810\uc9c4\uc801\uc778 \ubcc0\ud654\uc640 \ud68c\uc804, \ud544\ud130 \ud6a8\uacfc, \uc560\ub2c8\uba54\uc774\uc158 \ub4f1\ub3c4 \uc9c0\uc6d0\ud55c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub2e8\uc21c\ud55c \uc6d0 \uba87 \uac1c\ub9cc \uadf8\ub9ac\ub294 \ud615\uc2dd\uc740 \uc544\ub2cc \uac83\uc774\ub2e4. \uc5ec\ub7ec \uae30\ub2a5\uc744 \uc870\ud569\ud558\uba74 \uadf8\ub9bc\uc740 \uaf64 \ubcf5\uc7a1\ud574\uc9c8 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uae30\ub2a5\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ubaa8\ub4e0 \ud658\uacbd\uc774 \uac19\uc740 \uc218\uc900\uc73c\ub85c \uc9c0\uc6d0\ud55c\ub2e4\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \ubcf4\ub294 \ud504\ub85c\uadf8\ub7a8\uc5d0 \ub530\ub77c \uacb0\uacfc\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc774\ubc88 \uc774\uc57c\uae30\ub294 \uc791\uc740 \ub3c4\ud615\uc758 \uc6d0\ub9ac\ub97c \uc911\uc2ec\uc73c\ub85c \uc77d\ub294 \uac83\uc774\uba70 \ubaa8\ub4e0 \uc18c\ud504\ud2b8\uc6e8\uc5b4\uc5d0\uc11c \uac19\uc740 \ubaa8\uc2b5\uc774 \ubcf4\uc7a5\ub41c\ub2e4\ub294 \uc548\ub0b4\uac00 \uc544\ub2c8\ub2e4. SVG\ub294 \ub798\uc2a4\ud130 \uc774\ubbf8\uc9c0\uc640 \ub3c4\ud615\uc744 \ud568\uaed8 \ub2e4\ub8f0 \uc218\ub3c4 \uc788\ub2e4. \uadf8\ub798\uc11c \ud30c\uc77c \uc774\ub984\uc774 SVG\ub77c\uace0 \ub0b4\ubd80\uc758 \ubaa8\ub4e0 \ubd80\ubd84\uc774 \uc790\ub3d9\uc73c\ub85c \ubca1\ud130\uac00 \ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0ac\uc9c4\uc744 \ud3ec\ud568\ud55c \ubd80\ubd84\uc740 \uadf8 \uc0ac\uc9c4\uc774 \uac16\uace0 \uc788\ub294 \uc815\ubcf4\uc758 \ud55c\uacc4\ub97c \uc774\uc5b4\ubc1b\uc744 \uc218 \uc788\ub2e4. \uc774\ub294 PNG \ud30c\uc77c\uc774\ub77c\uace0 \ubaa8\ub450 \ud22c\uba85\ud55c \ubc30\uacbd\uc744 \uac16\uc9c0\ub294 \uc54a\ub294 \uac83\uacfc \ube44\uc2b7\ud55c \uad6c\ubd84\uc774\ub2e4. \ud615\uc2dd\uc774 \ud560 \uc218 \uc788\ub294 \uae30\ub2a5\uacfc \uc2e4\uc81c \ud30c\uc77c\uc5d0 \ub4e4\uc5b4 \uc788\ub294 \ub0b4\uc6a9\uc740 \ub2e4\ub974\ub2e4. \ud655\uc7a5\uc790\ub9cc \ubc14\uafb8\uc5b4 \ub0ae\uc740 \ud574\uc0c1\ub3c4\uc758 \uc0ac\uc9c4\uc744 \ub123\uc5c8\ub2e4\uace0 \uc5c6\ub294 \uc138\ubd80\uac00 \uc0c8\ub85c \uc0dd\uae30\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub2e8\uc21c\ud55c \ub3c4\ud615\uc740 \uc801\uc740 \uc124\uba85\uc73c\ub85c \ud45c\ud604\ud560 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ubaa8\uc591\uc774 \ub9e4\uc6b0 \ubcf5\uc7a1\ud558\uace0 \ud6a8\uacfc\uac00 \ub9ce\uc73c\uba74 \ud544\uc694\ud55c \uc815\ubcf4\uc640 \ud45c\uc2dc \uc791\uc5c5\ub3c4 \ub298\uc5b4\ub0a0 \uc218 \uc788\ub2e4. SVG\uac00 \ubaa8\ub4e0 \uc0ac\uc9c4\uacfc \ubaa8\ub4e0 \uadf8\ub9bc\ubcf4\ub2e4 \uc791\uace0 \ube60\ub978 \ud615\uc2dd\uc774\ub77c\uace0 \uc815\ub9ac\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc5b4\ub5a4 \uc774\ubbf8\uc9c0\uc778\uc9c0\uc640 \uc5b4\ub514\uc5d0 \uc4f8\uc9c0\uac00 \uba3c\uc800\ub2e4. \ud654\uba74\uc758 \uc544\uc774\ucf58\uacfc \uc5ec\ud589 \uc0ac\uc9c4\uc740 \ud544\uc694\ud55c \uc131\uc9c8\uc774 \ub2e4\ub974\ub2e4. \uac00\uc7a5 \uc88b\uc740 \ud655\uc7a5\uc790 \ud558\ub098\ub97c \uace0\ub974\ub294 \ubb38\uc81c\ubcf4\ub2e4, \uadf8\ub9bc\uc774 \uc5b4\ub5a4 \uc815\ubcf4\ub97c \ub2f4\uace0 \uc5b4\ub5a4 \ud06c\uae30\uc5d0\uc11c \uc77d\ud600\uc57c \ud558\ub294\uc9c0\uc5d0 \ub9de\ucd94\uc5b4 \uc120\ud0dd\ud558\ub294 \ubb38\uc81c\uc5d0 \uac00\uae5d\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uace1\uc120\uacfc \ud06c\uae30\uac00 \ub2e4\ub978 \uc885\uc774 \ubaa8\uc591\uc744 \uc0b4\ud53c\ub294 \uc791\uc5c5 \uc7a5\uba74\uc774\ub2e4. \uc774 \uc0bd\ud654 \ud30c\uc77c \uc790\uccb4\uac00 SVG\uc774\uac70\ub098 \uc2e4\uc81c \ubca1\ud130\u00b7\ub798\uc2a4\ud130 \ud655\ub300\ub97c \ube44\uad50\ud55c \uc2e4\ud5d8 \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ubaa8\uc591\uc744 \uc124\uba85\ud574 \ub2e4\uc2dc \uadf8\ub9b0\ub2e4\ub294 \uc0dd\uac01\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc774\ubbf8\uc9c0\ub2e4. \ub2e4\uc74c\uc5d0 \uc791\uc740 \uc544\uc774\ucf58\uc744 \ud06c\uac8c \ubcf4\uac8c \ub418\uba74 \uadf8 \uadf8\ub9bc\uc774 \uc810\uc744 \uc800\uc7a5\ud588\ub294\uc9c0 \ub3c4\ud615\uc744 \uc124\uba85\ud588\ub294\uc9c0 \uad81\uae08\ud574\ud574 \ubcf4\uc790. \ub208\uc55e\uc758 \uacb0\uacfc\ub294 \ube44\uc2b7\ud574\ub3c4 \ud06c\uae30\ub97c \ubc14\uafc0 \ub54c \ub2e4\ub978 \uc131\uc9c8\uc774 \ub098\ud0c0\ub0a0 \uc218 \uc788\ub2e4. SVG\ub294 \uadf8\ub9bc\uc744 \ubcf4\uad00\ud558\ub294 \ubc29\uc2dd\uc5d0\ub3c4 \uc5ec\ub7ec \uc885\ub958\uc758 \uc5b8\uc5b4\uac00 \uc788\ub2e4\ub294 \uac83\uc744 \uc54c\ub824 \uc900\ub2e4."}, {"id": "tcp-byte-stream-and-retransmission", "title": "TCP \u2014 \ub098\ub204\uc5b4 \ubcf4\ub0b8 \ub370\uc774\ud130\ub294 \uc5b4\ub5bb\uac8c \ub2e4\uc2dc \uc774\uc5b4\uc9c8\uae4c", "summary": "\ubc14\uc774\ud2b8\uc758 \uc21c\uc11c\uc640 \ud655\uc778 \uc751\ub2f5, \uc7ac\uc804\uc1a1\uacfc \uc81c\uc5b4\ub85c \ubd88\uc644\uc804\ud55c \ub124\ud2b8\uc6cc\ud06c\uc5d0\uc11c \ud750\ub984\uc744 \uc9c0\ud0a4\ub294 \ubc29\ubc95\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\uc778\ud130\ub137\uacfc \ud1b5\uc2e0", "categories": ["digital"], "url": "stories/tcp-byte-stream-and-retransmission/index.html", "image": "../media/tcp-byte-stream-and-retransmission.png", "alt": "\uc8fc\uace0\ubc1b\uc740 \ub370\uc774\ud130\uac00 \ub2e4\uc2dc \ubaa8\uc774\ub294 \uc0c1\ud669\uc744 \ubd09\ud22c\uc640 \ucef4\ud4e8\ud130\ub85c \ud45c\ud604\ud55c \uc0c1\uc0c1 \uc0bd\ud654", "text": "TCP \u2014 \ub098\ub204\uc5b4 \ubcf4\ub0b8 \ub370\uc774\ud130\ub294 \uc5b4\ub5bb\uac8c \ub2e4\uc2dc \uc774\uc5b4\uc9c8\uae4c RFC 9293\uc73c\ub85c \uc77d\ub294 \uc21c\uc11c\u00b7\ud655\uc778\u00b7\uc7ac\uc804\uc1a1\u00b7\uc18d\ub3c4 \uc870\uc808 \ubc14\uc774\ud2b8\uc758 \uc21c\uc11c\uc640 \ud655\uc778 \uc751\ub2f5, \uc7ac\uc804\uc1a1\uacfc \uc81c\uc5b4\ub85c \ubd88\uc644\uc804\ud55c \ub124\ud2b8\uc6cc\ud06c\uc5d0\uc11c \ud750\ub984\uc744 \uc9c0\ud0a4\ub294 \ubc29\ubc95\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc778\ud130\ub137\uacfc \ud1b5\uc2e0 \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \uc778\ud130\ub137\uc5d0\uc11c \ubcf4\ub0b8 \ubb38\uc11c\ub294 \ud55c \ub369\uc5b4\ub9ac \uadf8\ub300\ub85c \uae38\uc744 \ub530\ub77c \ubbf8\ub044\ub7ec\uc838 \uac00\uc9c0 \uc54a\ub294\ub2e4. \ub370\uc774\ud130\ub294 \ub098\ub258\uc5b4 \uc804\ub2ec\ub420 \uc218 \uc788\uace0, \uc77c\ubd80\uac00 \ub2a6\uac70\ub098 \ube60\uc9c8 \uc218\ub3c4 \uc788\ub2e4. TCP\ub294 \uc774\ub7f0 \ud658\uacbd\uc5d0\uc11c \uc751\uc6a9\ud504\ub85c\uadf8\ub7a8\uc5d0 \uc21c\uc11c \uc788\ub294 \ubc14\uc774\ud2b8 \ud750\ub984\uc744 \uc81c\uacf5\ud558\ub824\ub294 \uaddc\uce59\uc774\ub2e4. \ub124\ud2b8\uc6cc\ud06c\uac00 \ud56d\uc0c1 \uc644\ubcbd\ud558\ub2e4\ub294 \uac00\uc815 \ub300\uc2e0 \ubd88\uc644\uc804\ud568\uc5d0 \ub300\uc751\ud558\ub294 \uc57d\uc18d\uc744 \uc0b4\ud3b4\ubcf4\uc790. \uc778\ud130\ub137\uc758 \uc5ec\ub7ec \uae30\ub2a5\uc740 \ub098\ub258\uc5b4 \uc788\ub2e4. \uc8fc\uc18c\ub97c \ubcf4\uace0 \ub370\uc774\ud130\ub97c \uc804\ub2ec\ud558\ub294 IP\uc758 \uc5ed\ud560\uacfc, \uc5f0\uacb0\uc744 \ub9fa\uc740 \uc591\ucabd\uc774 \ubc1b\uc740 \ub370\uc774\ud130\ub97c \ud655\uc778\ud558\ub294 TCP\uc758 \uc5ed\ud560\uc740 \uac19\uc9c0 \uc54a\ub2e4. \uae38\uc744 \ucc3e\uc544 \ubcf4\ub0b8\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc0c1\ub300\uac00 \ubaa8\ub4e0 \ub0b4\uc6a9\uc744 \uc81c\ub300\ub85c \ubc1b\uc558\ub2e4\uace0 \uc54c \uc218\ub294 \uc5c6\ub2e4. \uc774 \uad6c\ubd84\uc740 \uc778\ud130\ub137\uc744 \ud558\ub098\uc758 \uac70\ub300\ud55c \uae30\uacc4\ubcf4\ub2e4 \uc5ec\ub7ec \uce35\uc758 \ud611\uc5c5\uc73c\ub85c \uc774\ud574\ud558\uac8c \ud55c\ub2e4. \uc544\ub798\ucabd\uc774 \ubaa8\ub4e0 \ubb38\uc81c\ub97c \uc644\ubcbd\ud558\uac8c \ud574\uacb0\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc704\ucabd\uc5d0\uc11c \ud544\uc694\ud55c \uaddc\uce59\uc744 \ub354\ud560 \uc218 \uc788\ub2e4. \ub2e4\ub9cc TCP \ud558\ub098\uac00 \ud1b5\uc2e0\uc758 \ubaa8\ub4e0 \ubaa9\uc801\uc744 \ud574\uacb0\ud558\ub294 \ub9cc\ub2a5 \uaddc\uce59\uc778 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc751\uc6a9\ud504\ub85c\uadf8\ub7a8\uc740 TCP\ub97c \ud1b5\ud574 \ubc14\uc774\ud2b8\uc758 \ud750\ub984\uc744 \uc8fc\uace0\ubc1b\ub294\ub2e4. TCP\ub294 \uadf8 \ub0b4\uc6a9\uc774 \uc18c\uc124\uc778\uc9c0 \uc0ac\uc9c4\uc778\uc9c0 \ud310\ub2e8\ud558\uc9c0 \uc54a\ub294\ub2e4. \ubcf4\ub0b4\ub294 \ucabd\uc774 \ub450 \ubc88 \ub098\ub204\uc5b4 \uc37c\ub2e4\uace0 \ubc1b\ub294 \ucabd\uc5d0\ub3c4 \uaf2d \ub450 \ub369\uc5b4\ub9ac\ub85c \ubcf4\uc774\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc6d0\ub798 \uba54\uc2dc\uc9c0\uc758 \uacbd\uacc4\ub294 \uc751\uc6a9 \ucabd\uc5d0\uc11c \ub530\ub85c \uc815\ud574\uc57c \ud55c\ub2e4. \uc774\ub294 \ubd09\ud22c \ud558\ub098\uc640 \ud3b8\uc9c0 \ud55c \ud1b5\uc744 \uc5b8\uc81c\ub098 \uac19\uc740 \uac83\uc73c\ub85c \ubcf4\uba74 \uc548 \ub41c\ub2e4\ub294 \ub73b\uc774\ub2e4. \ud654\uba74\uc5d0\uc11c \ubcf4\uc774\ub294 \ud30c\uc77c\uc774\ub098 \ub300\ud654\uc640 \uc804\uc1a1 \uaddc\uce59\uc774 \ub2e4\ub8e8\ub294 \ub2e8\uc704\ub294 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc0ac\uc6a9\uc790\uc758 \uacbd\ud5d8\uacfc \ud1b5\uc2e0\uc758 \ub0b4\ubd80 \ub2e8\uc704\ub97c \uad6c\ubd84\ud558\uba74 \ub370\uc774\ud130\uac00 \ub098\ub25c\ub2e4\ub294 \ub9d0\uc744 \ub354 \uc815\ud655\ud788 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. TCP\uc758 \uc21c\uc11c \ubc88\ud638\ub294 \ud750\ub984 \uc18d \ubc14\uc774\ud2b8\uc758 \uc704\uce58\uc640 \uc5f0\uacb0\ub41c\ub2e4. \ub2e8\uc21c\ud788 \uccab \ubc88\uc9f8 \ubd09\ud22c, \ub450 \ubc88\uc9f8 \ubd09\ud22c\uc5d0 \ubc88\ud638\ub97c \ubd99\uc774\ub294 \uadf8\ub9bc\ub9cc\uc73c\ub85c\ub294 \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4. \uc804\uc1a1\ud560 \ub54c \ub098\ub258\ub294 \ud06c\uae30\uac00 \ub2ec\ub77c\uc838\ub3c4 \ud750\ub984 \uc548\uc758 \uc704\uce58\ub97c \uc54c\uc544\uc57c \ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \ubc1b\ub294 \ucabd\uc740 \uc774 \uc815\ubcf4\ub97c \uc774\uc6a9\ud574 \uc55e\ub4a4\ub97c \ub9de\ucd94\uace0 \uc911\ubcf5\ub41c \ub370\uc774\ud130\ub97c \uad6c\ubcc4\ud560 \uc218 \uc788\ub2e4. \ub2a6\uac8c \uc628 \ubd80\ubd84\uc744 \uc5b4\ub514\uc5d0 \ub193\uc744\uc9c0 \uc815\ud558\ub294 \uae30\uc900\uc774 \uc0dd\uae34\ub2e4. \uc9c8\uc11c\ub294 \uae38 \uc704\uc5d0\uc11c \ubaa8\ub4e0 \uc870\uac01\uc774 \ud55c \uc904\ub85c \ub3c4\ucc29\ud574\uc11c\uac00 \uc544\ub2c8\ub77c \ub3c4\ucc29\ud55c \ub4a4 \uc704\uce58\ub97c \uc54c\uc544\ubcfc \uc218 \uc788\uc5b4\uc11c \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4. \ubc1b\ub294 \ucabd\uc740 \ud655\uc778 \uc751\ub2f5\uc744 \ubcf4\ub0b8\ub2e4. \uc774 \uc751\ub2f5\uc740 \ubcf4\ub0b8 \ucabd\uc774 \ub370\uc774\ud130\uc758 \ub3c4\ucc29 \uc0c1\ud0dc\ub97c \ud310\ub2e8\ud558\ub294 \ub2e8\uc11c\ub2e4. \ubcf4\ud1b5 \ub2e4\uc74c\uc5d0 \uae30\ub300\ud558\ub294 \uc704\uce58\ub97c \uc54c\ub824 \uc8fc\ub294 \ubc29\uc2dd\uc73c\ub85c, \ud750\ub984\uc5d0\uc11c \uc5b4\ub514\uae4c\uc9c0 \uc774\uc5b4\uc84c\ub294\uc9c0\ub97c \ub098\ud0c0\ub0b8\ub2e4. \ub2e4\ub9cc \uc774 \ud655\uc778\uc744 \uc0ac\uc6a9\uc790\uac00 \ubb38\uc11c\ub97c \uc77d\uc5c8\ub2e4\ub294 \uc54c\ub9bc\uc73c\ub85c \uc774\ud574\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ub124\ud2b8\uc6cc\ud06c\uc758 \ud55c \ub2e8\uacc4\uc5d0\uc11c \ubc1b\uc558\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ud504\ub85c\uadf8\ub7a8\uc774 \ucc98\ub9ac\ud588\ub2e4\ub294 \uc0ac\uc2e4, \uc0ac\ub78c\uc774 \ub0b4\uc6a9\uc744 \ud655\uc778\ud588\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc11c\ub85c \ub2e4\ub974\ub2e4. TCP\uc758 \uc2e0\ub8b0\uc131\uc740 \uc790\uae30 \uc5ed\ud560\uc758 \ubc94\uc704 \uc548\uc5d0\uc11c \uc815\uc758\ub41c\ub2e4. \uc1a1\uae08 \uac19\uc740 \uc751\uc6a9\uc758 \uc644\ub8cc\ub97c \ud310\ub2e8\ud558\ub824\uba74 \uadf8 \uc704\uc758 \ubcc4\ub3c4 \uaddc\uce59\uacfc \uc751\ub2f5\uc774 \ud544\uc694\ud558\ub2e4. \uc77c\ubd80 \ub370\uc774\ud130\ub098 \ud655\uc778 \uc751\ub2f5\uc774 \uc0ac\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ubcf4\ub0b8 \ucabd\uc740 \uc2dc\uac04\uacfc \ub3c4\ucc29 \uc815\ubcf4\ub97c \uc774\uc6a9\ud574 \ub2e4\uc2dc \uc804\uc1a1\ud560 \ud544\uc694\ub97c \ud310\ub2e8\ud55c\ub2e4. \uac19\uc740 \ub370\uc774\ud130\ub97c \ubc18\ubcf5\ud574\uc11c \ubcf4\ub0bc \uc218 \uc788\uc73c\ubbc0\ub85c \ubc1b\ub294 \ucabd\ub3c4 \uc911\ubcf5\uc744 \ub2e4\ub8f0 \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uc7ac\uc804\uc1a1\uacfc \uc21c\uc11c \ubc88\ud638\ub294 \ub530\ub85c \ub5a8\uc5b4\uc9c4 \uae30\ub2a5\uc774 \uc544\ub2c8\ub2e4. \ub108\ubb34 \uc131\uae09\ud55c \uc7ac\uc804\uc1a1\uc740 \uc544\uc9c1 \uc774\ub3d9 \uc911\uc778 \ub370\uc774\ud130\uae4c\uc9c0 \uc911\ubcf5\uc2dc\ud0ac \uc218 \uc788\ub2e4. \ub108\ubb34 \uc624\ub798 \uae30\ub2e4\ub9ac\uba74 \ubcf5\uad6c\uac00 \ub2a6\uc5b4\uc9c4\ub2e4. \uae30\ub2e4\ub9ac\ub294 \uc2dc\uac04\uc744 \uc815\ud558\ub294 \uc77c\ub3c4 \uaddc\uce59\uc758 \uc911\uc694\ud55c \ubd80\ubd84\uc774\ub2e4. \ud1b5\uc2e0\uc740 \ubcf4\ub0b4\uac70\ub098 \ud3ec\uae30\ud558\ub294 \ub450 \uc120\ud0dd \uc0ac\uc774\uc5d0 \uce21\uc815\uacfc \uc870\uc815\uc758 \uacfc\uc815\uc744 \uac00\uc9c4\ub2e4. \uc7ac\uc804\uc1a1\ub41c \ub370\uc774\ud130\uac00 \uc0c8\ub85c\uc6b4 \ub0b4\uc6a9\uc778\uc9c0 \uc774\ubbf8 \ubc1b\uc740 \ub0b4\uc6a9\uc778\uc9c0\ub294 \ubc1b\ub294 \ucabd\uc774 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \uc21c\uc11c \uc815\ubcf4\ub97c \uac00\uc9c0\uace0 \uc788\uae30 \ub54c\ubb38\uc5d0 \ub2a6\uac8c \uc628 \uac19\uc740 \ubd80\ubd84\uc744 \ub450 \ubc88\uc758 \uc0c8 \ub0b4\uc6a9\uc73c\ub85c \ucc98\ub9ac\ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \ube60\uc9c4 \uac83\uc744 \uba54\uc6b0\ub294 \uae30\ub2a5\uacfc \uc911\ubcf5\uc744 \uc81c\uac70\ud558\ub294 \uae30\ub2a5\uc740 \uac19\uc740 \ud750\ub984\uc744 \uc9c0\ud0a4\uae30 \uc704\ud55c \ud611\ub825\uc774\ub2e4. \uc804\uc1a1\uc774 \ud655\uc778\ub418\uae30 \uc804\uc758 \ub370\uc774\ud130\ub294 \ubcf4\ub0b8 \ucabd\uc5d0\uc11c\ub3c4 \ub2e4\uc2dc \ubcf4\ub0bc \uc218 \uc788\ub3c4\ub85d \uad00\ub9ac\ub418\uc5b4\uc57c \ud55c\ub2e4. \ud55c \ubc88 \uae38\uc5d0 \ub0b4\ubcf4\ub0c8\uc73c\ub2c8 \ub05d\ub0ac\ub2e4\ub294 \ubc29\uc2dd\uc774 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc774 \uc544\uc9c1 \ud655\uc778\ub418\uc9c0 \uc54a\uc558\ub294\uc9c0 \uae30\uc5b5\ud558\ub294 \uc77c\ub3c4 \uc2e0\ub8b0\uc131\uc758 \uc77c\ubd80\ub2e4. \uc6b0\ub9ac\uac00 \ub290\ub07c\ub294 \ub9e4\ub044\ub7ec\uc6b4 \uc5f0\uacb0 \ub4a4\uc5d0\ub294 \uc591\ucabd\uc774 \uc0c1\ud0dc\ub97c \uc720\uc9c0\ud558\uba70 \ub300\ud654\ud558\ub294 \uc2dc\uac04\uc774 \uc788\ub2e4. \ubc1b\ub294 \ud504\ub85c\uadf8\ub7a8\uc774 \ucc98\ub9ac\ud560 \uc218 \uc788\ub294 \uc591\uc5d0\ub294 \ud55c\uacc4\uac00 \uc788\ub2e4. TCP\uc758 \ud750\ub984 \uc81c\uc5b4\ub294 \ubc1b\ub294 \ucabd\uc758 \uc5ec\uc720\ub97c \uace0\ub824\ud55c\ub2e4. \ud55c\ud3b8 \uae38 \uc790\uccb4\uac00 \ud63c\uc7a1\ud574\uc9c0\ub294 \ubb38\uc81c\ub3c4 \uc788\ub2e4. \uc0c1\ub300 \ucef4\ud4e8\ud130\uac00 \uc900\ube44\ub418\uc5b4 \uc788\uc5b4\ub3c4 \uc911\uac04 \ub124\ud2b8\uc6cc\ud06c\uac00 \uac19\uc740 \uc18d\ub3c4\ub97c \uac10\ub2f9\ud558\uc9c0 \ubabb\ud560 \uc218 \uc788\ub2e4. \ub530\ub77c\uc11c \ub9ce\uc774 \ube68\ub9ac \ubcf4\ub0b4\ub294 \uac83\uc774 \uc5b8\uc81c\ub098 \uc804\uccb4\uc758 \uc18d\ub3c4\ub97c \ub192\uc774\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ud55c\uacc4\ub97c \uad6c\ubd84\ud574 \uc870\uc808\ud574\uc57c \ud55c\ub2e4. \uc790\uc138\ud55c \ud63c\uc7a1 \uc81c\uc5b4 \ubc29\uc2dd\uc740 \ubcc4\ub3c4 \uaddc\uce59\uacfc \ubc1c\uc804\uc758 \uc5ed\uc0ac\ub97c \uac00\uc9c0\uba70, TCP\uc758 \uae30\ubcf8 \uc124\uba85 \ud558\ub098\ub85c \ubaa8\ub4e0 \uc54c\uace0\ub9ac\uc998\uc774 \uac19\ub2e4\uace0 \ubcfc \uc218\ub294 \uc5c6\ub2e4. TCP\uc758 \uc911\uc694\ud55c \ucd08\uae30 \uba85\uc138\uc778 RFC 793\uc740 1981\ub144\uc5d0 \ub098\uc654\uace0, 2022\ub144\uc758 RFC 9293\uc740 \ucd95\uc801\ub41c \uc218\uc815\uacfc \uc124\uba85\uc744 \uc815\ub9ac\ud588\ub2e4. \uc624\ub798 \uc4f0\uc778 \uaddc\uce59\uc774\ub77c\ub294 \uc0ac\uc2e4\uc774 \ucc98\uc74c\uc758 \ubb38\uc7a5\ub4e4\uc774 \uc601\uc6d0\ud788 \uadf8\ub300\ub85c \uc720\uc9c0\ub418\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub9ce\uc740 \uad6c\ud604\uacfc \uacbd\ud5d8\uc774 \uba85\uc138\ub97c \ub2e4\ub4ec\ub294 \ub370 \uc5f0\uacb0\ub41c\ub2e4. TCP\ub97c \uc774\ud574\ud558\uba74 \uc778\ud130\ub137\uc758 \uc2e0\ub8b0\uc131\uc774 \uc644\ubcbd\ud55c \uae38\uc5d0\uc11c\ub9cc \ub098\uc624\uc9c0 \uc54a\uc74c\uc744 \uc54c \uc218 \uc788\ub2e4. \uc21c\uc11c\uc640 \ud655\uc778, \uc7ac\uc804\uc1a1\uacfc \uc18d\ub3c4 \uc870\uc808\uc774 \ud568\uaed8 \uc791\ub3d9\ud55c\ub2e4. \uc5f0\uacb0\uc774 \uc788\uc5b4 \ubcf4\uc778\ub2e4\ub294 \ub290\ub08c \ub4a4\uc5d0\ub294 \ub370\uc774\ud130\uac00 \ube60\uc9c8 \uac00\ub2a5\uc131\uc744 \uc804\uc81c\ub85c \uc124\uacc4\ud55c \uc624\ub79c \uc57d\uc18d\uc774 \ub193\uc5ec \uc788\ub2e4."}, {"id": "typewriter-keys-and-office-records", "title": "\ud0c0\uc790\uae30 \u2014 \uae00\uc528\ub97c \uc798 \uc4f0\ub294 \uc190\ubcf4\ub2e4 \ud544\uc694\ud55c \uac83\uc774 \uc0dd\uacbc\ub2e4", "summary": "\ucd08\uae30 \ud0c0\uc790\uae30\uc640 \uc0c1\uc6a9\ud654, \ubcf5\uc0ac\uc640 \uad50\uc815\uc758 \ubcc0\ud654\ub97c \ub530\ub77c \ud0a4\ubcf4\ub4dc \uc774\uc804\uc758 \uc0ac\ubb34\uc2e4\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\ucef4\ud4e8\ud130\uc758 \uc5ed\uc0ac", "categories": ["digital"], "url": "stories/typewriter-keys-and-office-records/index.html", "image": "../media/typewriter-keys-and-office-records.jpg", "alt": "19\uc138\uae30 \ub9d0 \ud0c0\uc790\uae30\uc758 \ubc14\uae65 \ud615\ud0dc\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc61b \ub3c4\ud310", "text": "\ud0c0\uc790\uae30 \u2014 \uae00\uc528\ub97c \uc798 \uc4f0\ub294 \uc190\ubcf4\ub2e4 \ud544\uc694\ud55c \uac83\uc774 \uc0dd\uacbc\ub2e4 \uc190\uae00\uc528\uc640 \uc778\uc1c4 \uc0ac\uc774\uc5d0\uc11c \uc790\ub77c\ub09c \uc0c8\ub85c\uc6b4 \uc0ac\ubb34\uc758 \ub3c4\uad6c \ucd08\uae30 \ud0c0\uc790\uae30\uc640 \uc0c1\uc6a9\ud654, \ubcf5\uc0ac\uc640 \uad50\uc815\uc758 \ubcc0\ud654\ub97c \ub530\ub77c \ud0a4\ubcf4\ub4dc \uc774\uc804\uc758 \uc0ac\ubb34\uc2e4\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ucef4\ud4e8\ud130\uc758 \uc5ed\uc0ac \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \ud3b8\uc9c0\uc758 \ub0b4\uc6a9\ubcf4\ub2e4 \uae00\uc528\ub97c \uc54c\uc544\ubcf4\ub294 \uc77c\uc774 \ub354 \uc624\ub798 \uac78\ub9b4 \ub54c\uac00 \uc788\ub2e4. \ub204\uac00 \uc37c\ub294\uc9c0 \uc54c\uba74 \uc9d0\uc791\ud560 \uc218 \uc788\uc9c0\ub9cc \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc77d\uc73c\uba74 \uc5b4\ub824\uc6cc\uc9c0\ub294 \uae00\uc528\ub2e4. \ubb38\uc11c\uac00 \ub298\uc5b4\ub098\ub358 19\uc138\uae30\uc758 \uc0ac\ubb34\uc2e4\uc5d0\uc11c\ub294 \uc774\ub7f0 \ubb38\uc81c\uac00 \uac1c\uc778\uc758 \ud544\uccb4\ub97c \ub118\uc5b4 \uc77c\uc758 \uc18d\ub3c4\uc640 \uc815\ud655\uc131\uc5d0 \uad00\uacc4\ub418\uc5c8\ub2e4. \ud0c0\uc790\uae30\ub294 \uc190\uae00\uc528\ub97c \uc778\uc1c4\ub41c \uae00\uc790 \uac19\uc740 \ubaa8\uc591\uc73c\ub85c \ubc14\uafb8\ub294 \ub3c4\uad6c\uc600\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc778\uc1c4\uc18c\uac00 \ucc45\uc744 \ucc0d\ub4ef \uac19\uc740 \ud398\uc774\uc9c0\ub97c \ub300\ub7c9 \uc0dd\uc0b0\ud558\ub294 \uae30\uacc4\ub3c4 \uc544\ub2c8\uc5c8\ub2e4. \ud55c \uae00\uc790\uc529 \ub204\ub974\uba70 \ubb38\uc7a5\uc744 \ub9cc\ub4dc\ub294 \ubc29\uc2dd\uc774 \uc190\uc73c\ub85c \uc4f0\uae30\uc640 \uc778\uc1c4 \uc0ac\uc774\uc5d0 \uc0c8\ub85c\uc6b4 \uc790\ub9ac\ub97c \ucc28\uc9c0\ud588\ub2e4. \uac1c\uc778\uc758 \ud544\uccb4\uc5d0\ub294 \uc800\ub9c8\ub2e4\uc758 \uc2b5\uad00\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \ubc18\uba74 \uacc4\uc57d\uacfc \uc8fc\ubb38, \uc7a5\ubd80\uc640 \ud3b8\uc9c0\ub294 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ube60\ub974\uace0 \uc815\ud655\ud558\uac8c \uc77d\ud600\uc57c \ud588\ub2e4. \ub9ce\uc740 \ubb38\uc11c\ub97c \uc8fc\uace0\ubc1b\uc744\uc218\ub85d \ubcf4\uae30 \uc88b\uc740 \uae00\uc528\ubcf4\ub2e4 \ubc18\ubcf5\ud574\uc11c \uc77c\uc815\ud55c \uae00\uc790\ub97c \ub0a8\uae38 \uc218 \uc788\ub294 \ubc29\uc2dd\uc774 \uc911\uc694\ud574\uc84c\ub2e4. \ud0c0\uc790\uae30\uc758 \uc218\uc694\uc5d0\ub294 \uc774\ub7f0 \uc0ac\ubb34\uc758 \uc870\uac74\uc774 \uc788\uc5c8\ub2e4. \uc18d\uae30 \uc5ed\uc2dc \ube60\ub974\uac8c \uae30\ub85d\ud558\uae30 \uc704\ud55c \ubc29\ubc95\uc774\uc5c8\uc9c0\ub9cc \uc801\ud78c \uac83\uc744 \ub204\uad6c\ub098 \ubc14\ub85c \uc77d\uc744 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc18d\ub3c4\ub97c \uc5bb\uc740 \ub4a4\uc5d0\ub3c4 \ub2e4\uc2dc \uc62e\uaca8 \uc4f0\ub294 \uc77c\uc774 \ub0a8\uc744 \uc218 \uc788\ub2e4. \ud0c0\uc790\uae30\ub294 \uc77d\uae30 \uc26c\uc6b4 \ud615\ud0dc\ub85c \ubb38\uc7a5\uc744 \ub9cc\ub4e4\uc5b4 \ub0b4\ub294 \ub2e4\ub978 \uacbd\ub85c\ub97c \uc81c\uacf5\ud588\ub2e4. \ud544\uc694\ud55c \uac83\uc740 \ube68\ub9ac \ub204\ub974\ub294 \uc190\ub9cc\uc774 \uc544\ub2c8\ub77c \uc791\uc5c5 \uc804\uccb4\ub97c \ubc14\uafb8\ub294 \ub3c4\uad6c\uc600\ub2e4. 1900\ub144\uc5d0 \ucd9c\uac04\ub41c E. W. \ubc88\uc758 \ubc1c\uba85\uc0ac\uc5d0\ub294 \uc5ec\ub7ec \ucd08\uae30 \ud0c0\uc790\uae30\uc758 \uc2dc\ub3c4\uac00 \ub4f1\uc7a5\ud55c\ub2e4. \ucc45\uc740 \uc204\uc2a4\uc758 \uae30\uacc4\uc640 \uadf8\uac83\uc744 \uc0c1\uc6a9 \uc81c\ud488\uc73c\ub85c \ubc1c\uc804\uc2dc\ud0a8 \ub808\ubc0d\ud134\ub3c4 \uc18c\uac1c\ud55c\ub2e4. \ud55c \ubc1c\uba85\uac00\uac00 \uc5b4\ub290 \ub0a0 \uc644\uc131\ud488\uc744 \ub0b4\ub193\uc558\ub2e4\ub294 \uc774\uc57c\uae30\ubcf4\ub2e4 \ub2e4\uc591\ud55c \uad6c\uc0c1\uacfc \uac1c\uc120, \uc81c\uc870\uc640 \ud310\ub9e4\uac00 \uc774\uc5b4\uc9c0\ub294 \uacfc\uc815\uc5d0 \uac00\uae5d\ub2e4. \uc791\ub3d9\ud558\ub294 \uc2dc\uc81c\ud488\uc774 \uc788\ub2e4\ub294 \uac83\uacfc \uc0ac\ubb34\uc2e4\uc5d0\uc11c \ub9e4\uc77c \uc4f8 \uc218 \uc788\ub2e4\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uc27d\uac8c \uace0\uc7a5 \ub098\uc9c0 \uc54a\uace0 \uc77c\uc815\ud55c \uae00\uc790\ub97c \ucc0d\uc73c\uba70 \uc0ac\uc6a9\uc790\uac00 \ubc30\uc6b8 \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uc81c\ud488\uc744 \ub9cc\ub4e4\uace0 \ubcf4\uae09\ud560 \ud68c\uc0ac\uc758 \ub2a5\ub825\ub3c4 \ud544\uc694\ud558\ub2e4. \uc775\uc219\ud55c \ubb3c\uac74\uc758 \uc2dc\uc791\uc5d0\ub294 \ubc1c\uba85\uc758 \uc21c\uac04\uacfc \uc0c1\ud488\uc774 \ub418\ub294 \uc2dc\uac04\uc774 \ub530\ub85c \uc788\uc5c8\ub2e4. \uae30\uacc4\uc2dd \ud0c0\uc790\uae30\ub294 \uc790\ud310\uc744 \ub204\ub974\ub294 \uc6c0\uc9c1\uc784\uc744 \uae00\uc790\uac00 \uc885\uc774\uc5d0 \ub0a8\ub294 \ub3d9\uc791\uc73c\ub85c \uc5f0\uacb0\ud55c\ub2e4. \uc885\uc774\ub97c \uc7a1\uace0 \uc704\uce58\ub97c \uc62e\uae30\ub294 \uc77c, \uae00\uc790\ub9c8\ub2e4 \uc790\ub9ac\ub97c \ub9de\ucd94\ub294 \uc77c\uc774 \ud568\uaed8 \uc774\ub8e8\uc5b4\uc838\uc57c \ubb38\uc7a5\uc774 \ub41c\ub2e4. \uc624\ub298\uc758 \ud0a4\ubcf4\ub4dc\ub97c \ub204\ub97c \ub54c \ubcf4\uc774\uc9c0 \uc54a\ub294 \uacfc\uc815\uc774 \uc61b \uae30\uacc4\uc5d0\uc11c\ub294 \ud6e8\uc52c \ubb3c\ub9ac\uc801\uc778 \uc6c0\uc9c1\uc784\uc73c\ub85c \ub4dc\ub7ec\ub09c\ub2e4. \ubb38\uc7a5\uc744 \uc4f0\uba74\uc11c \ub3d9\uc2dc\uc5d0 \uc7a5\uce58\uc758 \ub9ac\ub4ec\uc5d0 \ub9de\ucd94\ub294 \uc791\uc5c5\uc774\uae30\ub3c4 \ud588\ub2e4. \uc190\uac00\ub77d\uc758 \uc18d\ub3c4\uc640 \uae30\uacc4\uc758 \ubc18\uc751\uc774 \uc5b4\uae0b\ub098\uba74 \uc6d0\ud558\ub358 \uacb0\uacfc\uac00 \ub098\uc624\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \ud0c0\uc790\uae30\ub97c \uc775\ud788\ub294 \uac83\uc740 \uae00\uc790\uc758 \uc704\uce58\ub97c \uc678\uc6b0\ub294 \uc77c\uc5d0 \ub354\ud574 \uc815\ud655\ud55c \ubc18\ubcf5 \ub3d9\uc791\uc744 \ubc30\uc6b0\ub294 \uc77c\uc774\uc5c8\ub2e4. \uc0c8\ub85c\uc6b4 \ub3c4\uad6c\ub294 \uadf8 \ub3c4\uad6c\ub97c \ub2e4\ub8f0 \uc219\ub828\ub3c4 \ub9cc\ub4e4\uc5c8\ub2e4. \ud654\uba74\uc5d0\uc11c \uc4f0\ub294 \uae00\uc740 \uc9c0\uc6b0\uace0 \ub2e4\uc2dc \uc801\uae30\uac00 \uc27d\ub2e4. \uc885\uc774\uc5d0 \uc774\ubbf8 \ucc0d\ud78c \uae00\uc790\ub294 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ub418\ub3cc\ub9b4 \uc218 \uc5c6\ub2e4. \ud0c0\uc790\uae30\uc758 \uc791\uc5c5\uc744 \uc0dd\uac01\ud560 \ub54c \ube60\ub974\uac8c \uc4f0\ub294 \uc7a5\uc810\ub9cc \ubcf4\uba74 \uad50\uc815\uacfc \ub2e4\uc2dc \uc791\uc131\ud558\ub294 \ubd80\ub2f4\uc744 \ub193\uce5c\ub2e4. \ub3c4\uad6c\uac00 \ud3b8\ud574\uc84c\ub2e4\ub294 \ub9d0 \uc18d\uc5d0\uc11c\ub3c4 \uc5b4\ub5a4 \uc77c\uc740 \uc5ec\uc804\ud788 \uc5b4\ub824\uc6e0\ub2e4. \uadf8\ub798\uc11c \uc815\ud655\uc131\uacfc \uc791\uc5c5 \uc21c\uc11c\ub97c \uc0dd\uac01\ud558\ub294 \uc2b5\uad00\uc774 \uc911\uc694\ud574\uc9c4\ub2e4. \ubb38\uc7a5\uc744 \uba3c\uc800 \uc815\ub9ac\ud55c \ub4a4 \uc62e\uaca8 \uc801\uac70\ub098 \ud2c0\ub9b0 \ubd80\ubd84\uc744 \ud655\uc778\ud558\ub294 \uc77c\uc744 \ub098\ub20c \uc218 \uc788\ub2e4. \ud2b9\uc815 \uc0ac\ubb34\uc2e4\uc758 \uc791\uc5c5\uc744 \ubaa8\ub450 \uac19\uc740 \uaddc\uce59\uc73c\ub85c \uc77c\ubc18\ud654\ud560 \uc218\ub294 \uc5c6\uc9c0\ub9cc, \uc885\uc774\ub77c\ub294 \ub9e4\uccb4\uac00 \uc81c\uacf5\ud558\ub294 \uc870\uac74\uc740 \ubd84\uba85\ud588\ub2e4. \ud55c \ubc88 \ucc0d\ud78c \uacb0\uacfc\ub294 \ub208\uc55e\uc5d0 \ub0a8\uc544 \uc788\uc5c8\ub2e4. \uce74\ubcf8\uc9c0\ub97c \uc774\uc6a9\ud558\uba74 \uae00\uc790\ub97c \uce58\ub294 \uc555\ub825\uc73c\ub85c \uc5ec\ub7ec \uc7a5\uc5d0 \ub0b4\uc6a9\uc744 \ub0a8\uae38 \uc218 \uc788\uc5c8\ub2e4. \ubc1c\uba85\uc0ac\ub294 \uc774\ub7f0 \ubcf5\uc0ac \uae30\ub2a5\uc744 \uc0ac\ubb34\uc758 \ubcc0\ud654\uc640 \uc5f0\uacb0\ud55c\ub2e4. \ubcf4\ub0b8 \ud3b8\uc9c0\uc758 \ub0b4\uc6a9\uc744 \ub2e4\uc2dc \ud655\uc778\ud558\ub824\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc0c1\ub300\uc5d0\uac8c \uac04 \uc885\uc774\uc640 \ubcc4\uac1c\ub85c \uc790\uae30 \ucabd \uae30\ub85d\uc774 \ud544\uc694\ud588\ub2e4. \ubb38\uc11c\ub97c \uc791\uc131\ud558\ub294 \uc77c\uacfc \ubcf4\uad00\ud558\ub294 \uc77c\uc774 \ud568\uaed8 \ub2e4\ub904\uc9c4 \uac83\uc774\ub2e4. \ubcf5\uc0ac\ubcf8\uc774 \uc788\ub2e4\uace0 \ubaa8\ub4e0 \uc2e4\uc218\uac00 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud2c0\ub9b0 \uae00\uc790\ub3c4 \ud568\uaed8 \uc62e\uaca8\uc9c8 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uac19\uc740 \ub0b4\uc6a9\uc744 \ubcc4\ub3c4\ub85c \ubca0\uaef4 \uc4f0\ub294 \ubd80\ub2f4\uc744 \uc904\uc778\ub2e4\ub294 \uc758\ubbf8\uac00 \uc788\uc5c8\ub2e4. \uc815\ubcf4\uac00 \uc774\ub3d9\ud55c \ub4a4\uc5d0\ub3c4 \ud754\uc801\uc744 \ubcf4\uc720\ud558\ub294 \uc77c\uc740, \ub9ce\uc740 \uc0ac\ub78c\uc774 \uac70\ub798\ud558\ub294 \uc870\uc9c1\uc5d0\uc11c \uc810\uc810 \uc911\uc694\ud55c \uc0ac\ubb34\uac00 \ub418\uc5c8\ub2e4. \ud0c0\uc790\uae30\uc758 \ubcf4\uae09\uc740 \uc774\ub97c \ub2a5\uc219\ud558\uac8c \ub2e4\ub8e8\ub294 \uc77c\uc744 \uc9c1\uc5c5\uc73c\ub85c \ub9cc\ub4e4\uc5c8\ub2e4. \uc61b \ubc1c\uba85\uc11c\ub294 \uc5ec\uc131\uc758 \uc0ac\ubb34\uc9c1 \uc9c4\ucd9c\uc744 \ub099\uad00\uc801\uc73c\ub85c \uc124\uba85\ud558\uc9c0\ub9cc \uadf8 \ud45c\ud604\uc744 \uadf8\ub300\ub85c \ubc1b\uc544\ub4e4\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uc77c\uc790\ub9ac\uac00 \ub113\uc5b4\uc9c0\ub294 \uac83\uacfc \uc784\uae08\uacfc \ub300\uc6b0, \uc2b9\uc9c4\uc758 \uae30\ud68c\uac00 \uac19\uc544\uc9c0\ub294 \uac83\uc740 \ub2e4\ub978 \ubb38\uc81c\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \uc774 \ub3c4\uad6c\uac00 \uc0c8\ub85c\uc6b4 \uae30\ud68c\ub97c \uc81c\uacf5\ud588\ub2e4\ub294 \uc810\uacfc \ub2f9\uc2dc\uc758 \uc131\ubcc4 \uaddc\ubc94 \uc18d\uc5d0\uc11c \uc0ac\uc6a9\ub418\uc5c8\ub2e4\ub294 \uc810\uc744 \ud568\uaed8 \uc77d\uc744 \uc218 \uc788\ub2e4. \ubc1c\uba85\uc758 \uc5ed\uc0ac\ub294 \uae30\uacc4\uc758 \uc131\ub2a5\ub9cc\uc774 \uc544\ub2c8\ub77c \ub204\uac00 \uc5b4\ub5a4 \uc790\ub9ac\uc5d0\uc11c \uc77c\ud558\uac8c \ub418\uc5c8\ub294\uc9c0\uc758 \uc5ed\uc0ac\uc774\uae30\ub3c4 \ud558\ub2e4. \uc61b \uc800\uc790\uc758 \ucc2c\uc0ac\ub97c \uc624\ub298\uc758 \ud3c9\uac00\ub85c \ubb34\uc2ec\ucf54 \uc62e\uae30\uc9c0 \uc54a\uc73c\uba74 \ub354 \ub9ce\uc740 \uc9c8\ubb38\uc774 \ub0a8\ub294\ub2e4. \uc624\ub298\uc758 \ucef4\ud4e8\ud130 \ud0a4\ubcf4\ub4dc\ub294 \uc885\uc774\uc5d0 \ubc14\ub85c \ud65c\uc790\ub97c \ucc0d\ub294 \ud0c0\uc790\uae30\uc640 \uc791\ub3d9 \ubc29\uc2dd\uc774 \ub2e4\ub974\ub2e4. \uadf8\ub798\ub3c4 \uc190\uac00\ub77d\uc73c\ub85c \uae00\uc790\ub97c \uace8\ub77c \ubb38\uc7a5\uc744 \ub9cc\ub4e0\ub2e4\ub294 \uc6c0\uc9c1\uc784\uc5d0\ub294 \uc774\uc5b4\uc9c0\ub294 \uae30\uc5b5\uc774 \uc788\ub2e4. \uc775\uc219\ud55c \uc785\ub825 \ub3c4\uad6c\ub97c \uc0c8\ub86d\uac8c \ubcf4\uba74 \ud654\uba74 \ub4a4\uc758 \uae30\uc220\ub9cc\uc774 \uc544\ub2c8\ub77c \uadf8 \uc55e\uc5d0 \uc549\uc544 \ubb38\uc11c\ub97c \ub9cc\ub4e4\ub358 \uc0ac\ub78c\ub3c4 \ub5a0\uc624\ub978\ub2e4. \ud0c0\uc790\uae30\uc758 \uc5ed\uc0ac\ub97c \uc790\ud310 \ubc30\uc5f4\uc5d0 \uc5bd\ud78c \ud765\ubbf8\ub85c\uc6b4 \uc18c\ubb38 \ud558\ub098\ub85c \ub05d\ub0bc \ud544\uc694\ub294 \uc5c6\ub2e4. \uc77d\uae30 \uc26c\uc6b4 \uae00\uc790\uc640 \ube60\ub978 \uae30\ub85d, \ubcf5\uc0ac\uc640 \ubcf4\uad00\uc774\ub77c\ub294 \uc0ac\ubb34\uc758 \uc694\uad6c\uac00 \ubaa8\uc778 \ubb3c\uac74\uc774\uc5c8\ub2e4. \uc791\uc740 \uae08\uc18d \uc7a5\uce58\uc758 \ubc18\ubcf5 \uc18c\ub9ac \uc18d\uc5d0\uc11c \uac1c\uc778\uc758 \ud544\uccb4\ub85c \uc6c0\uc9c1\uc774\ub358 \uae30\ub85d\uc774 \uc870\uc9c1\uc758 \uc77c\ub85c \ubc14\ub00c\uace0 \uc788\uc5c8\ub2e4."}, {"id": "unicode-letters-shared-numbers", "title": "\uc720\ub2c8\ucf54\ub4dc \u2014 \ub2e4\ub978 \ucef4\ud4e8\ud130\uc5d0\uc11c\ub3c4 \uac19\uc740 \uae00\uc790\ub97c \uc77d\ub294 \uc57d\uc18d", "summary": "\uae00\uc790\uc758 \uacf5\ud1b5 \ubc88\ud638\uc640 \uc800\uc7a5 \ubc29\uc2dd, \uae00\uaf34\uacfc \uc815\uaddc\ud654\uc758 \ucc28\uc774\ub97c \ud55c\uae00 \uc0ac\ub840\ub85c \uc27d\uac8c \uc774\ud574\ud569\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\ub370\uc774\ud130\uc640 \uae30\ub85d", "categories": ["digital"], "url": "stories/unicode-letters-shared-numbers/index.html", "image": "../media/unicode-letters-shared-numbers.png", "alt": "\uc11c\ub85c \ub2e4\ub978 \uae30\uae30\ub97c \uc0ac\uc6a9\ud558\ub294 \ub450 \uc0ac\ub78c\uc774 \ucc45\uc774 \uaf42\ud78c \uacf5\uac04\uc5d0\uc11c \ub9c8\uc8fc \uc549\uc544 \ub300\ud654\ud558\ub294 AI \uc7a5\uba74.", "text": "\uc720\ub2c8\ucf54\ub4dc \u2014 \ub2e4\ub978 \ucef4\ud4e8\ud130\uc5d0\uc11c\ub3c4 \uac19\uc740 \uae00\uc790\ub97c \uc77d\ub294 \uc57d\uc18d \ud55c\uae00 \ud55c \uae00\uc790\uac00 \ud654\uba74\uc5d0 \ub3c4\ucc29\ud558\uae30\uae4c\uc9c0 \uae00\uc790\uc758 \uacf5\ud1b5 \ubc88\ud638\uc640 \uc800\uc7a5 \ubc29\uc2dd, \uae00\uaf34\uacfc \uc815\uaddc\ud654\uc758 \ucc28\uc774\ub97c \ud55c\uae00 \uc0ac\ub840\ub85c \uc27d\uac8c \uc774\ud574\ud569\ub2c8\ub2e4. \ub370\uc774\ud130\uc640 \uae30\ub85d \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \ud734\ub300\uc804\ud654\ub85c \uc548\ub155\ud558\uc138\uc694\ub77c\uace0 \ubcf4\ub0b4\uba74 \uc0c1\ub300\ubc29\uc740 \ub2e4\ub978 \uae30\uae30\uc5d0\uc11c\ub3c4 \uac19\uc740 \ub9d0\uc744 \uc77d\ub294\ub2e4. \ub108\ubb34 \uc775\uc219\ud574\uc11c \uc2e0\uae30\ud558\uac8c \ub290\uaef4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \ud558\uc9c0\ub9cc \uc11c\ub85c \ub2e4\ub978 \uae30\uacc4\uac00 \uac19\uc740 \uae00\uc790\ub97c \uc54c\uc544\ubcf4\ub824\uba74 \uc5b4\ub5a4 \uc57d\uc18d\uc774 \ud544\uc694\ud560\uae4c. \ucef4\ud4e8\ud130\uac00 \uc6b0\ub9ac\uac00 \uc4f4 \ubb38\uc7a5\uc744 \uc0ac\uc9c4\uc73c\ub85c \ucc0d\uc5b4 \ubcf4\ub0b4\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc720\ub2c8\ucf54\ub4dc\ub294 \uc774\ub7f0 \ubb38\uc81c\ub97c \ub2e4\ub8e8\ub294 \uacf5\ud1b5 \ud45c\uc900\uc774\ub2e4. \ud575\uc2ec\uc740 \uc138\uacc4\uc758 \uc5ec\ub7ec \ubb38\uc790\uc5d0 \uacf5\ud1b5\uc758 \ubc88\ud638\ub97c \ubd80\uc5ec\ud558\ub294 \ub370 \uc788\ub2e4. \ubcf5\uc7a1\ud55c \uc22b\uc790\ud45c\ub97c \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uae00\uc790\uc758 \ubc88\ud638\uc640 \ud654\uba74\uc5d0 \uadf8\ub824\uc9c0\ub294 \ubaa8\uc591\uc774 \uc11c\ub85c \ub2e4\ub978 \uc77c\uc774\ub77c\ub294 \uc0ac\uc2e4\ub9cc \uc54c\uba74, \ud3c9\uc18c\uc758 \uc791\uc740 \ubd88\ud3b8\ub3c4 \uaf64 \uc798 \uc124\uba85\ub41c\ub2e4. \uc5b4\ub5a4 \uc0c1\uc790\uc758 17\ubc88 \uce78\uc5d0\ub294 \uc5f0\ud544\uc774, \ub2e4\ub978 \uc0c1\uc790\uc758 17\ubc88 \uce78\uc5d0\ub294 \uc9c0\uc6b0\uac1c\uac00 \uc788\ub2e4\uace0 \uc0dd\uac01\ud574 \ubcf4\uc790. \uc0c1\uc790 \uc774\ub984\uc744 \ube7c\uace0 17\ubc88\ub9cc \uc54c\ub824 \uc8fc\uba74 \uc5c9\ub6b1\ud55c \ubb3c\uac74\uc744 \uaebc\ub0bc \uc218 \uc788\ub2e4. \uc774\ub294 \uc774\ud574\ub97c \uc704\ud55c \ube44\uc720\uc9c0\ub9cc \uacfc\uac70\uc758 \uc5ec\ub7ec \ubb38\uc790 \ubd80\ud638 \uccb4\uacc4\uac00 \uc65c \ud63c\ub780\uc744 \uc77c\uc73c\ud0ac \uc218 \uc788\uc5c8\ub294\uc9c0 \ubcf4\uc5ec \uc900\ub2e4. \uc22b\uc790\uc640 \uae00\uc790\ub97c \uc5f0\uacb0\ud558\ub294 \ubc29\uc2dd\uc774 \ub2e4\ub974\uba74 \uac19\uc740 \ub370\uc774\ud130\ub97c \ub2e4\ub978 \ubb38\uc790\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \ubb38\uc790 \uae68\uc9d0\uc740 \uc6d0\ub798 \ubb38\uc7a5\uc5d0 \uc774\uc0c1\ud55c \uc678\uad6d\uc5b4\ub97c \uc37c\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub77c, \uc800\uc7a5\ud558\uac70\ub098 \uc804\ub2ec\ud55c \uc22b\uc790\ub97c \ud574\uc11d\ud558\ub294 \uc57d\uc18d\uc774 \uc5b4\uae0b\ub09c \uacb0\uacfc\uc77c \uc218 \uc788\ub2e4. \ubb38\uc81c\ub294 \uae00\uc758 \ub73b\ubcf4\ub2e4 \uadf8 \uc55e \ub2e8\uacc4\uc5d0 \uc788\ub294 \uc148\uc774\ub2e4. \uc720\ub2c8\ucf54\ub4dc\uc5d0\uc11c \ud55c\uae00 \uc74c\uc808 \uac00\uc5d0\ub294 U+AC00\uc774\ub77c\ub294 \ubc88\ud638\uac00 \ubd99\uc5b4 \uc788\ub2e4. \uc774 \ubc88\ud638\ub97c \ucf54\ub4dc \ud3ec\uc778\ud2b8\ub77c\uace0 \ud55c\ub2e4. \ub0af\uc120 \uae30\ud638\ucc98\ub7fc \ubcf4\uc5ec\ub3c4 \uc774 \uae00\uc790\ub97c \uac00\ub9ac\ud0a4\ub294 \ud45c\uc900 \ubc88\ud638\ub77c\ub294 \ub73b\uc774\ub2e4. \ubc88\ud638 \uc55e\uc758 U+ \ud45c\uae30\ub294 \uc720\ub2c8\ucf54\ub4dc\uc758 \uac12\uc744 \uc801\uc744 \ub54c \uc4f0\ub294 \uad00\ub840\ub2e4. \uc774 \uacf5\ud1b5 \ubc88\ud638 \ub355\ubd84\uc5d0 \ud504\ub85c\uadf8\ub7a8\uc740 \uc5b4\ub5a4 \uae00\uc790\ub97c \ub2e4\ub8e8\uace0 \uc788\ub294\uc9c0 \uac19\uc740 \uae30\uc900\uc73c\ub85c \uc774\uc57c\uae30\ud560 \uc218 \uc788\ub2e4. \ud55c\uad6d\uc5b4\uc640 \uc601\uc5b4, \ub2e4\ub978 \uc5b8\uc5b4\uc758 \ubb38\uc790\uac00 \ud55c \ubb38\uc11c \uc548\uc5d0 \uc788\uc5b4\ub3c4 \uac01 \uae00\uc790\ub97c \uacf5\ud1b5 \uccb4\uacc4\uc5d0\uc11c \uc2dd\ubcc4\ud55c\ub2e4. \uae00\uc790\ub9c8\ub2e4 \uac19\uc740 \uadf8\ub9bc \ud30c\uc77c\uc744 \uc8fc\uace0\ubc1b\ub294 \uac83\uacfc\ub294 \ub2e4\ub978 \ubc29\uc2dd\uc774\ub2e4. \ubc88\ud638\uac00 \uc815\ud574\uc84c\uc5b4\ub3c4 \uadf8\uac83\uc744 \ud30c\uc77c\uacfc \ud1b5\uc2e0\uc5d0\uc11c \uc5b4\ub5a4 \ubc14\uc774\ud2b8 \ubc30\uc5f4\ub85c \ud45c\ud604\ud560\uc9c0\ub294 \ub530\ub85c \uc815\ud574\uc57c \ud55c\ub2e4. \ubc14\uc774\ud2b8\ub294 \ucef4\ud4e8\ud130\uac00 \ub370\uc774\ud130\ub97c \uc800\uc7a5\ud558\ub294 \uc791\uc740 \ub2e8\uc704\ub2e4. UTF-8\uc774\ub098 UTF-16\uc740 \uc774 \ud45c\ud604 \ubc29\uc2dd\uc758 \uc774\ub984\uc774\ub2e4. \uc720\ub2c8\ucf54\ub4dc\ub77c\ub294 \ud45c\uc900\uacfc \uc774\ub97c \uc800\uc7a5\ud558\ub294 \ubc29\ubc95\uc744 \uad6c\ubcc4\ud558\uba74 \ub0af\uc120 \uc6a9\uc5b4\uac00 \uc870\uae08 \uc815\ub9ac\ub41c\ub2e4. UTF-8\uc5d0\uc11c\ub294 \ucf54\ub4dc \ud3ec\uc778\ud2b8\uc5d0 \ub530\ub77c \ud544\uc694\ud55c \ubc14\uc774\ud2b8 \uc218\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \ub530\ub77c\uc11c \uae00\uc790 \uc218\uac00 \uac19\ub2e4\uace0 \ud30c\uc77c\uc5d0\uc11c \ucc28\uc9c0\ud558\ub294 \ud06c\uae30\uae4c\uc9c0 \uac19\uc9c0\ub294 \uc54a\ub2e4. \ud654\uba74\uc5d0 \ub450 \uae00\uc790\uac00 \ub098\ub780\ud788 \ub193\uc774\ub294 \uc77c\uacfc \uc800\uc7a5 \uc7a5\uce58\uc5d0 \uac19\uc740 \uc591\uc758 \uacf5\uac04\uc744 \uc0ac\uc6a9\ud558\ub294 \uc77c\uc740 \uc11c\ub85c \ub2e4\ub978 \ubb38\uc81c\ub2e4. \uce5c\uad6c\uc758 \ud734\ub300\uc804\ud654\uc5d0\uc11c \ubcf8 \uae00\uc790\uac00 \ub0b4 \ud654\uba74\uc5d0\uc11c\ub294 \uc870\uae08 \ub2e4\ub974\uac8c \ubcf4\uc77c \uc218 \uc788\ub2e4. \ubc88\ud638\uac00 \uac19\uc544\ub3c4 \uae00\uaf34\uc774 \ub2e4\ub974\uba74 \ud68d\uacfc \uad75\uae30, \uade0\ud615\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc720\ub2c8\ucf54\ub4dc\ub294 \uae00\uc790\ub97c \uc2dd\ubcc4\ud558\ub294 \uc57d\uc18d\uc774\uc9c0 \ubaa8\ub4e0 \uae30\uae30\uc5d0 \ub611\uac19\uc740 \uc11c\uccb4\ub97c \uc124\uce58\ud558\ub294 \uc81c\ub3c4\ub294 \uc544\ub2c8\ub2e4. ICU\uc758 \uacf5\uc2dd \ubb38\uc11c\ub294 \ubb38\uc790\uc640 \uae00\ub9ac\ud504\ub97c \uad6c\ubcc4\ud55c\ub2e4. \uae00\ub9ac\ud504\ub294 \uc2e4\uc81c\ub85c \uadf8\ub824\uc9c0\ub294 \ubaa8\uc591\uc744 \ub73b\ud55c\ub2e4. \uc6b0\ub9ac\uac00 \uc77d\ub294 \ucd94\uc0c1\uc801\uc778 \uae00\uc790\uc640 \uadf8 \uae00\uc790\ub97c \ud45c\ud604\ud558\ub294 \uc2dc\uac01\uc801 \ud615\ud0dc\uac00 \ubc18\ub4dc\uc2dc \uc77c\ub300\uc77c\ub85c\ub9cc \ub300\uc751\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uacf5\ud1b5 \ubc88\ud638\uc640 \ub514\uc790\uc778\uc758 \uc790\uc720\uac00 \ub3d9\uc2dc\uc5d0 \uc874\uc7ac\ud560 \uc218 \uc788\ub294 \uc774\uc720\ub2e4. \uc870\uae08 \ub354 \ud765\ubbf8\ub85c\uc6b4 \uc77c\ub3c4 \uc788\ub2e4. \uac00\ub97c \uc644\uc131\ub41c \ud55c \uc74c\uc808\uc758 \ubc88\ud638\ub85c \ub098\ud0c0\ub0bc \uc218\ub3c4 \uc788\uace0, \uc870\ud569\uc6a9 \ucd08\uc131 \u1100\uacfc \uc911\uc131 \u1161\ub97c \uc774\uc5b4 \ub098\ud0c0\ub0bc \uc218\ub3c4 \uc788\ub2e4. \ud654\uba74\uc5d0\uc11c\ub294 \ube44\uc2b7\ud558\uac8c \uc77d\ud788\uc9c0\ub9cc \ub0b4\ubd80\uc758 \ucf54\ub4dc \ud3ec\uc778\ud2b8 \ubc30\uc5f4\uc740 \ub2e4\ub974\ub2e4. \uc774\uac83\uc774 \ud55c\uae00\uc774 \uc798\ubabb\ub418\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc774\ucc98\ub7fc \ud45c\uc900\uc774 \ub3d9\ub4f1\ud55c \uac83\uc73c\ub85c \ub2e4\ub8e8\ub294 \ud45c\ud604\uc744 \uc77c\uc815\ud55c \ud615\uc2dd\uc73c\ub85c \ub9de\ucd94\ub294 \uc791\uc5c5\uc744 \uc815\uaddc\ud654\ub77c\uace0 \ud55c\ub2e4. \uac00\uc758 \uacbd\uc6b0 \uc870\ud569\ub41c \ud615\ud0dc\uc640 \ubd84\ud574\ub41c \ud615\ud0dc \uc0ac\uc774\ub97c \uc815\ub9ac\ud560 \uc218 \uc788\ub2e4. \uc774\ub984\uc740 \uc5b4\ub835\uc9c0\ub9cc \uc11c\ub85c \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uc801\ud78c \uac19\uc740 \uae00\uc790\ub97c \ube44\uad50\ud558\uae30 \uc88b\uac8c \ub9de\ucd94\ub294 \uacfc\uc815\uc73c\ub85c \uc774\ud574\ud558\uba74 \ub41c\ub2e4. \ud30c\uc77c \uc774\ub984\uc744 \ubcf5\uc0ac\ud588\ub294\ub370 \uac80\uc0c9\uc774 \uae30\ub300\ub300\ub85c \ub418\uc9c0 \uc54a\ub294 \uc0c1\ud669\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc6d0\uc778\uc774 \uc5b8\uc81c\ub098 \uc815\uaddc\ud654\uc5d0 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc, \ub208\uc5d0 \ube44\uc2b7\ud558\uac8c \ubcf4\uc774\ub294 \ubb38\uc790\uc5f4\uc758 \ub0b4\ubd80 \ubc30\uc5f4\uc774 \ub2e4\ub974\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ud504\ub85c\uadf8\ub7a8\uc774 \uace0\ub824\ud574\uc57c \ud560 \ubb38\uc81c\ub2e4. \uc0ac\ub78c\uc758 \ub208\uc73c\ub85c \uac19\uc740 \uae00\uc790\ub77c\uace0 \ub290\ub07c\ub294 \uac83\ub9cc\uc73c\ub85c \ube44\uad50\uac00 \ub05d\ub098\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \ubc18\ub300\ub85c \ubaa8\uc591\uc774 \ube44\uc2b7\ud55c \ubaa8\ub4e0 \ubb38\uc790\ub97c \uac19\uc740 \uac83\uc73c\ub85c \ubc14\uafb8\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \ub2e4\ub978 \uc5b8\uc5b4\uc758 \uae00\uc790\ub098 \ub2e4\ub978 \uc758\ubbf8\uc758 \uae30\ud638\ub3c4 \ub2ee\uac8c \ubcf4\uc77c \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc815\uaddc\ud654\ub294 \uc0ac\ub78c \ub9c8\uc74c\ub300\ub85c \ub2ee\uc740 \uae00\uc790\ub97c \ud55c\ub370 \ubb36\ub294 \uc77c\uc774 \uc544\ub2c8\ub77c \ud45c\uc900\uc5d0\uc11c \uc815\ud55c \uad00\uacc4\ub97c \ub530\ub77c\uc57c \ud55c\ub2e4. \uad6c\ubd84\ud574\uc57c \ud560 \ucc28\uc774\uc640 \ub9de\ucd94\uc5b4\ub3c4 \ub418\ub294 \ucc28\uc774\ub97c \ub098\ub204\ub294 \uc148\uc774\ub2e4. \ubb38\uc11c\uc758 \uc77c\ubd80\uac00 \ube48 \ub124\ubaa8\ub85c \ub098\ud0c0\ub098\ub294 \uacbd\uc6b0\ub3c4 \uc788\ub2e4. \uae00\uc790\uc758 \uc815\ubcf4\uac00 \uc804\ud600 \uc5c6\uc5b4\uc11c\uc77c \uc218\ub3c4 \uc788\uc9c0\ub9cc, \uae00\uaf34\uc5d0 \ud544\uc694\ud55c \ubaa8\uc591\uc774 \uc5c6\uc5b4 \ud45c\uc2dc\ud558\uc9c0 \ubabb\ud558\ub294 \uacbd\uc6b0\ub3c4 \uc788\ub2e4. \uc5b4\ub5a4 \uae00\uc790\uc778\uc9c0 \uc544\ub294 \uc77c\uacfc \uadf8 \uae00\uc790\ub97c \ud654\uba74\uc5d0 \uadf8\ub9b4 \uc218 \uc788\ub294 \uc77c\uc740 \ubcc4\uac1c\ub2e4. \uc774 \ucc28\uc774\ub97c \uc54c\uba74 \uae00\uc790\uac00 \uc774\uc0c1\ud558\ub2e4\ub294 \ud55c\ub9c8\ub514 \ub4a4\uc5d0\ub3c4 \uc5ec\ub7ec \uc6d0\uc778\uc774 \uc788\uc74c\uc744 \uc774\ud574\ud558\uac8c \ub41c\ub2e4. \ubc88\ud638\ub97c \uc77d\ub294 \ubc29\uc2dd, \ubb38\uc790\uc758 \ubc30\uc5f4, \uae00\uaf34\uc758 \uc900\ube44\uac00 \uac01\uac01 \uad00\uc5ec\ud55c\ub2e4. \uc0ac\uc6a9\uc790\uac00 \ub9e4\ubc88 \uc774\ub97c \uace0\uce60 \uc804\ubb38\uac00\uac00 \ub420 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uacf5\ud1b5 \ud45c\uc900 \ud558\ub098\uac00 \ud654\uba74\uc758 \ubaa8\ub4e0 \ubb38\uc81c\ub97c \uc790\ub3d9\uc73c\ub85c \uc5c6\uc560 \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc815\ub3c4\uba74 \ucda9\ubd84\ud558\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \ub2e4\ub978 \uae30\uae30\ub97c \uc0ac\uc6a9\ud558\ub294 \uc0ac\ub78c\ub4e4\uc774 \ub9c8\uc8fc \uc549\uc740 AI \ubd84\uc704\uae30 \uc0bd\ud654\ub2e4. \uc2e4\uc81c \ubb38\uc790\ud45c\ub098 \uae00\uc790 \ucc98\ub9ac \uacfc\uc815\uc744 \uc124\uba85\ud558\ub294 \ub3c4\uc2dd\uc740 \uc544\ub2c8\ub2e4. \uc720\ub2c8\ucf54\ub4dc\uc758 \ubc88\ud638\ub294 \ubcf4\uc774\uc9c0 \uc54a\uc544\ub3c4, \uc11c\ub85c \ub2e4\ub978 \ud658\uacbd\uc5d0\uc11c \ub9d0\uc744 \ub098\ub204\ub294 \uc77c\uc758 \ubc30\uacbd\uc5d0 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \ud55c\uae00\ub85c \uc778\uc0ac\ub97c \ubcf4\ub0bc \ub54c \uacf5\ud1b5 \ubc88\ud638\ub97c \ub5a0\uc62c\ub9b4 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc624\ud788\ub824 \uc758\uc2dd\ud558\uc9c0 \uc54a\uace0 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \uc774\ub7f0 \uc57d\uc18d\uc758 \uc131\uacfc\ub2e4. \uc6b0\ub9ac\uac00 \uc77d\uace0 \uc2f6\uc740 \uac83\uc740 \ubb38\uc7a5\uc774\uace0, \ud45c\uc900\uc774 \ud558\ub294 \uc77c\uc740 \uadf8 \ubb38\uc7a5\uc774 \ub2e4\ub978 \uae30\uacc4\uc5d0\uc11c\ub3c4 \uac19\uc740 \uae00\uc790\ub85c \ub9cc\ub0a0 \uc218 \uc788\ub3c4\ub85d \uae38\uc744 \ub9de\ucd94\ub294 \uac83\uc774\ub2e4."}, {"id": "web-links-shared-knowledge", "title": "\uc6f9\uc758 \uc2dc\uc791 \u2014 \ub17c\ubb38\uc5d0\uc11c \ub2e4\ub978 \ub17c\ubb38\uc73c\ub85c \uac74\ub108\uac00\uace0 \uc2f6\uc5c8\ub2e4", "summary": "\ud300 \ubc84\ub108\uc2a4\ub9ac\uc758 \uc81c\uc548\uc5d0\uc11c \uc2dc\uc791\ud574 \uc6f9\uacfc \uc778\ud130\ub137\uc758 \ucc28\uc774, \ub9c1\ud06c\uc640 \uc5f4\ub9b0 \ud45c\uc900\uc758 \uc758\ubbf8\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\uc778\ud130\ub137\uacfc \ud1b5\uc2e0", "categories": ["digital"], "url": "stories/web-links-shared-knowledge/index.html", "image": "../media/web-links-shared-knowledge.png", "alt": "\ucd08\uae30 \uac1c\uc778\uc6a9 \ucef4\ud4e8\ud130\uc640 \uc5ec\ub7ec \ubb38\uc11c\uac00 \ub193\uc778 \uc5f0\uad6c\uc2e4\uc5d0\uc11c \ud30c\ub780 \ub9ac\ubcf8\uc774 \uc790\ub8cc\ub97c \uc787\ub294 \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\uc6f9\uc758 \uc2dc\uc791 \u2014 \ub17c\ubb38\uc5d0\uc11c \ub2e4\ub978 \ub17c\ubb38\uc73c\ub85c \uac74\ub108\uac00\uace0 \uc2f6\uc5c8\ub2e4 \uc8fc\uc18c\uc640 \ub9c1\ud06c\uac00 \ub9cc\ub4e0 \uc0c8\ub85c\uc6b4 \uc77d\uae30 \ubc29\uc2dd \ud300 \ubc84\ub108\uc2a4\ub9ac\uc758 \uc81c\uc548\uc5d0\uc11c \uc2dc\uc791\ud574 \uc6f9\uacfc \uc778\ud130\ub137\uc758 \ucc28\uc774, \ub9c1\ud06c\uc640 \uc5f4\ub9b0 \ud45c\uc900\uc758 \uc758\ubbf8\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uc778\ud130\ub137\uacfc \ud1b5\uc2e0 \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \ud55c \ubb38\uc11c\ub97c \uc77d\ub2e4\uac00 \uac70\uae30\uc5d0 \ub098\uc624\ub294 \ub2e4\ub978 \uc790\ub8cc\ub97c \ucc3e\uc544\uc57c \ud55c\ub2e4. \ucc45\uc774\ub77c\uba74 \uc11c\uac00\ub85c \uac00\uace0, \ubcf5\uc0ac\ubb3c\uc774\ub77c\uba74 \uc11c\ub958\ucca0\uc744 \ub4a4\uc9c4\ub2e4. \uc9c0\uae08\uc740 \ubb38\uc7a5 \uc548\uc758 \ub9c1\ud06c\ub97c \ub204\ub974\uba74 \ub418\uc9c0\ub9cc, \uc774 \ub2f9\uc5f0\ud55c \uc6c0\uc9c1\uc784\ub3c4 \ub204\uad70\uac00\uac00 \ub9cc\ub4e4\uc5b4 \ub193\uc740 \uae38\uc774\ub2e4. \uc6f9\uc758 \uc774\uc57c\uae30\ub97c \uac70\ub300\ud55c \uae30\uc220 \ud601\uba85\ubcf4\ub2e4 \uc77d\ub294 \uc0ac\ub78c\uc758 \uc791\uc740 \ubd88\ud3b8\uc5d0\uc11c \uc2dc\uc791\ud574 \ubcf4\uc790. \uc6f9\uc740 \uc815\ubcf4\ub97c \ud55c\uacf3\uc5d0 \ubaa8\uc544 \ub450\ub294 \uac83\uc5d0 \uadf8\uce58\uc9c0 \uc54a\uace0 \uc11c\ub85c \ub2e4\ub978 \ubb38\uc11c\ub97c \uc774\uc5b4 \uc77d\uc744 \uc218 \uc788\uac8c \ud588\ub2e4. \ucef4\ud4e8\ud130 \uc0ac\uc774\uc5d0 \uc790\ub8cc\uac00 \uc624\uac08 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc, \ud3c9\ubc94\ud55c \ub3c5\uc790\uac00 \uadf8 \uc790\ub8cc\ub97c \ucc3e\uc544 \uc77d\uae30 \uc27d\ub2e4\ub294 \uc0ac\uc2e4 \uc0ac\uc774\uc5d0\ub294 \uc0dd\uac01\ubcf4\ub2e4 \uae34 \uac70\ub9ac\uac00 \uc788\uc5c8\ub2e4. 1989\ub144 CERN\uc5d0\uc11c \uc77c\ud558\ub358 \ud300 \ubc84\ub108\uc2a4\ub9ac\ub294 \uc815\ubcf4 \uad00\ub9ac\uc5d0 \uad00\ud55c \uc81c\uc548\uc744 \uc791\uc131\ud588\ub2e4. \uc5ec\ub7ec \uc790\ub8cc\uc640 \uad00\uacc4\ub97c \ud558\uc774\ud37c\ud14d\uc2a4\ud2b8\ub85c \uc5f0\uacb0\ud558\ub294 \uad6c\uc0c1\uc774 \uc6f9\uc758 \ubc30\uacbd\uc774 \ub418\uc5c8\ub2e4. \ud558\uc774\ud37c\ud14d\uc2a4\ud2b8\ub77c\ub294 \ub9d0\uc774 \ub0af\uc124\ub2e4\uba74, \uc77d\ub358 \uacf3\uc5d0\uc11c \uad00\ub828\ub41c \ub2e4\ub978 \uacf3\uc73c\ub85c \uac74\ub108\uac08 \uc218 \uc788\ub294 \ubb38\uc11c\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \ub41c\ub2e4. \ucc45\uc758 \uac01\uc8fc\ub294 \ub2e4\ub978 \uae00\uc744 \uac00\ub9ac\ud0a4\uc9c0\ub9cc \ub3c5\uc790\uac00 \uc9c1\uc811 \uadf8 \uae00\uc744 \ucc3e\uc544\uc57c \ud55c\ub2e4. \ub9c1\ud06c\ub294 \uadf8 \uc774\ub3d9\uc744 \ubb38\uc11c\uc758 \uae30\ub2a5\uc73c\ub85c \ub9cc\ub4e0\ub2e4. \ud55c \ud398\uc774\uc9c0\uc758 \uc800\uc790\uac00 \uc138\uacc4\uc758 \ubaa8\ub4e0 \uc815\ubcf4\ub97c \ub2f4\uc9c0 \uc54a\uc544\ub3c4 \ub2e4\ub978 \ud398\uc774\uc9c0\ub97c \uac00\ub9ac\ud0ac \uc218 \uc788\ub2e4. \ubb38\uc11c\ub294 \uc644\uacb0\ub41c \ud55c \uad8c\uc778 \ub3d9\uc2dc\uc5d0 \ub354 \ud070 \ub3c5\uc11c\uc758 \uc785\uad6c\uac00 \ub41c\ub2e4. \uc5f0\uacb0\ud558\uace0 \uc2f6\uc740 \ub9c8\uc74c\uc774 \uc788\uc5b4\ub3c4 \ubb38\uc11c\ub97c \uc8fc\uace0\ubc1b\uc744 \uacf5\ud1b5 \ubc29\ubc95\uc774 \uc5c6\uc73c\uba74 \ub2e4\ub978 \ucef4\ud4e8\ud130\uc5d0\uc11c\ub294 \uc77d\uae30 \uc5b4\ub835\ub2e4. \uc790\ub8cc\uc758 \uc704\uce58\ub97c \uac00\ub9ac\ud0a4\ub294 \uc8fc\uc18c, \ubb38\uc11c\uc758 \uad6c\uc870\ub97c \ud45c\ud604\ud558\ub294 \ubc29\uc2dd, \uadf8 \ubb38\uc11c\ub97c \uc694\uccad\ud558\uace0 \ubc1b\ub294 \uc57d\uc18d\uc774 \ud568\uaed8 \ud544\uc694\ud588\ub2e4. 1990~1991\ub144 \ubb34\ub835 \ubc84\ub108\uc2a4\ub9ac\ub294 \ucd08\uae30 \uc6f9\uc744 \uc774\ub8e8\ub294 HTML\uacfc HTTP, \ube0c\ub77c\uc6b0\uc800\uc640 \uc11c\ubc84, \uc6f9 \ud398\uc774\uc9c0\ub97c \ub9c8\ub828\ud588\ub2e4. \uc6a9\uc5b4\ub97c \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc5ed\ud560\uc744 \ub098\ub204\uc5b4 \ubcf4\uc790. \ubb38\uc11c\uac00 \uc788\uace0, \uadf8\uac83\uc744 \ubcf4\ub0b4\ub294 \ucabd\uc774 \uc788\uc73c\uba70, \ubc1b\uc544\uc11c \ubcf4\uc5ec \uc8fc\ub294 \ucabd\uc774 \uc788\ub2e4. \uadf8 \uc0ac\uc774\uac00 \uac19\uc740 \uc57d\uc18d\uc73c\ub85c \uc774\uc5b4\uc9c8 \ub54c \ub9c1\ud06c\uac00 \uc2e4\uc81c \uae38\uc774 \ub41c\ub2e4. \uc778\ud130\ub137\uc740 \uc5ec\ub7ec \ucef4\ud4e8\ud130\uc640 \ub124\ud2b8\uc6cc\ud06c\uac00 \uc815\ubcf4\ub97c \uc8fc\uace0\ubc1b\uc744 \uc218 \uc788\uac8c \ud558\ub294 \uae30\ubc18\uc774\ub2e4. \uc6f9\uc740 \uadf8 \uae30\ubc18 \uc704\uc5d0\uc11c \ubb38\uc11c\uc640 \uc5ec\ub7ec \ucf58\ud150\uce20\ub97c \uc8fc\uc18c\ub85c \ucc3e\uace0 \uc5f0\uacb0\ud574 \uc774\uc6a9\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc6f9\uc774 \uc0dd\uacbc\uae30 \ub54c\ubb38\uc5d0 \uc778\ud130\ub137 \uc790\uccb4\uac00 \ucc98\uc74c \uc0dd\uae34 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc804\uc790\uc6b0\ud3b8\uc744 \ub5a0\uc62c\ub9ac\uba74 \ucc28\uc774\uac00 \uc870\uae08 \uc26c\uc6cc\uc9c4\ub2e4. \uc6f9 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \uba54\uc77c\uc744 \ubcfc \uc218\ub3c4 \uc788\uc9c0\ub9cc \uc804\uc790\uc6b0\ud3b8\uacfc \uc6f9\uc774 \uc6d0\ub798 \uac19\uc740 \uae30\uc220\uc778 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud558\ub098\uc758 \uae38 \uc704\uc5d0 \uc5ec\ub7ec \uc885\ub958\uc758 \uc11c\ube44\uc2a4\uac00 \ub193\uc77c \uc218 \uc788\ub2e4. \uc778\ud130\ub137\uc744 \uae38\uc5d0 \ube44\uc720\ud55c\ub2e4\uba74 \uc6f9\uc740 \uadf8 \uae38\uc744 \uc0ac\uc6a9\ud558\ub294 \uc911\uc694\ud55c \ud65c\ub3d9 \ud558\ub098\ub77c\uace0 \ud560 \uc218 \uc788\ub2e4. \ube0c\ub77c\uc6b0\uc800\ub294 \uba40\ub9ac \uc788\ub294 \uc790\ub8cc\ub97c \uc694\uccad\ud558\uace0 \ud654\uba74\uc5d0 \ubcf4\uc5ec \uc8fc\ub294 \ucc3d\uc774\ub2e4. \ub3c5\uc790\uac00 \ubb38\uc11c\ub97c \ub9cc\ub4e0 \uc0ac\ub78c\uacfc \uac19\uc740 \ucef4\ud4e8\ud130\ub97c \uc4f0\uac70\ub098 \uac19\uc740 \ubc29\uc5d0 \uc788\uc744 \ud544\uc694\uac00 \uc904\uc5b4\ub4e0\ub2e4. \uc8fc\uc18c\ub97c \uc54c\uac70\ub098 \ub2e4\ub978 \ud398\uc774\uc9c0\uc758 \ub9c1\ud06c\ub97c \ub530\ub77c\uac00\uba74 \uc0c8\ub85c\uc6b4 \uc77d\uc744\uac70\ub9ac\uc5d0 \ub3c4\ucc29\ud560 \uc218 \uc788\ub2e4. \ucd08\uae30\uc758 \uc6f9\uc744 \uc624\ub298\ub0a0\uc758 \ubcf5\uc7a1\ud55c \ud654\uba74\uacfc \ub611\uac19\uc774 \uc0c1\uc0c1\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc911\uc694\ud55c \ubcc0\ud654\ub294 \ud654\ub824\ud55c \uc0c9\uc774\ub098 \uc601\uc0c1\ubcf4\ub2e4 \uc11c\ub85c \ub2e4\ub978 \ubb38\uc11c\ub97c \ud55c \ud750\ub984 \uc18d\uc5d0\uc11c \ub9cc\ub0a0 \uc218 \uc788\ub2e4\ub294 \ub370 \uc788\uc5c8\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc18c\ubc15\ud55c \ud654\uba74\uc774\uc5b4\ub3c4 \uadf8 \ud654\uba74 \ubc16\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uae38\uc740 \ub9e4\uc6b0 \ub113\uc5b4\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \uc6f9\uc744 \ud55c \ud68c\uc0ac\uc758 \uc81c\ud488 \uc548\uc5d0\uc11c\ub9cc \uc77d\uc744 \uc218 \uc788\ub2e4\uba74 \uc5f0\uacb0\uc758 \ubc94\uc704\ub3c4 \uadf8 \uc81c\ud488\uc758 \uacbd\uacc4\uc5d0 \ubb36\uc778\ub2e4. \uc5ec\ub7ec \ube0c\ub77c\uc6b0\uc800\uac00 \ubb38\uc11c\ub97c \ube44\uc2b7\ud55c \ub73b\uc73c\ub85c \ubc1b\uc544\ub4e4\uc774\ub824\uba74 \uacf5\uac1c\ub41c \uacf5\ud1b5 \uaddc\uce59\uc774 \uc911\uc694\ud574\uc9c4\ub2e4. \uc6f9 \ud45c\uc900\uc740 \uc774\ub7f0 \uc57d\uc18d\uc744 \ub2e4\ub8e8\ub294 \ud2c0\uc774\ub2e4. 1994\ub144 \ubc84\ub108\uc2a4\ub9ac\ub294 W3C\ub97c \uc124\ub9bd\ud588\ub2e4. \uc5ec\ub7ec \uc870\uc9c1\uc774 \uc6f9 \uae30\uc220\uc758 \uacf5\ud1b5 \uae30\uc900\uc744 \ub17c\uc758\ud558\ub294 \uacf5\uac04\uc774\ub2e4. \uc6f9\uc758 \ubc1c\uc804\uc744 \ud55c \uc0ac\ub78c\uc774 \uacc4\uc18d \ud63c\uc790 \ub9cc\ub4e4\uc5b4 \ub0b8 \uacb0\uacfc\ub85c \uc124\uba85\ud574\uc11c\ub294 \uace4\ub780\ud558\ub2e4. \uc2dc\uc791\uc758 \uc81c\uc548\uacfc \uad6c\ud604 \ub4a4\uc5d0\ub294 \uc5ec\ub7ec \uae30\uad00\uacfc \uac1c\ubc1c\uc790\uac00 \ud569\uc758\ud558\uace0 \uad6c\ud604\ud558\uba70 \uace0\uce58\ub294 \uae34 \uacfc\uc815\uc774 \uc774\uc5b4\uc84c\ub2e4. \uc6b0\ub9ac\ub294 \uac80\uc0c9\ucc3d\uc744 \uc6f9\uc758 \uc785\uad6c\ucc98\ub7fc \ub290\ub07c\uc9c0\ub9cc \uc6f9 \uc804\uccb4\uac00 \ud558\ub098\uc758 \uac80\uc0c9 \uc11c\ube44\uc2a4 \uc548\uc5d0 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac80\uc0c9\uc740 \uc5ec\ub7ec \ud398\uc774\uc9c0\ub97c \ucc3e\ub3c4\ub85d \ub3d5\ub294 \ubc29\ubc95\uc774\uace0, \ub9c1\ud06c\ub294 \ud398\uc774\uc9c0\uc5d0\uc11c \ub2e4\ub978 \uc8fc\uc18c\ub97c \uac00\ub9ac\ud0a4\ub294 \uae30\ub2a5\uc774\ub2e4. \ub204\uad70\uac00\uc758 \ucd94\ucc9c \uae00\uc774\ub098 \uae30\uad00\uc758 \uc548\ub0b4 \ubaa9\ub85d\uc744 \ub530\ub77c\uac00\ub294 \uac83\ub3c4 \uc6f9\uc744 \uc77d\ub294 \ubc29\uc2dd\uc774\ub2e4. \uadf8\ub798\uc11c \ud55c \ud398\uc774\uc9c0\ub97c \uc798 \ub9cc\ub4dc\ub294 \uc77c\uc5d0\ub294 \ub0b4\uc6a9\ubfd0 \uc544\ub2c8\ub77c \uc5b4\ub514\ub85c \ub3c5\uc790\ub97c \ubcf4\ub0b4 \uc904\uc9c0\ub3c4 \ud3ec\ud568\ub41c\ub2e4. \uadfc\uac70\uc790\ub8cc\uc758 \uc6d0\ubb38, \ub354 \uc790\uc138\ud55c \uc124\uba85, \ub2e4\uc74c \uc774\uc57c\uae30\ub85c \uc774\uc5b4\uc9c0\ub294 \uc8fc\uc18c\ub97c \ub193\uc73c\uba74 \ub3c5\uc790\ub294 \uc800\uc790\uc758 \uc694\uc57d \ubc16\uc73c\ub85c \ub098\uac00 \uc9c1\uc811 \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \uc5f0\uacb0\uc740 \ud3b8\ub9ac\ud568\uacfc \ud568\uaed8 \uac80\uc99d\uc758 \uae30\ud68c\ub3c4 \ub9cc\ub4e0\ub2e4. \ub9c1\ud06c\ub294 \ubb38\uc11c\ub97c \uc774\uc5b4 \uc8fc\uc9c0\ub9cc \uadf8 \ubb38\uc11c\uc758 \uc815\ud655\uc131\uc744 \uc790\ub3d9\uc73c\ub85c \ubcf4\uc99d\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc5c9\ub6b1\ud55c \uc790\ub8cc\ub97c \uc5f0\uacb0\ud558\uac70\ub098 \uc624\ub798\ub41c \uc8fc\uc18c\uac00 \uc0ac\ub77c\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \ub3c5\uc790\ub294 \ub204\uac00 \uc4f4 \uae00\uc778\uc9c0, \uc5b8\uc81c \ub9cc\ub4e4\uc5b4\uc84c\ub294\uc9c0, \uc5f0\uacb0\ud55c \uc790\ub8cc\uac00 \uc2e4\uc81c \uc8fc\uc7a5\uc744 \ub4b7\ubc1b\uce68\ud558\ub294\uc9c0 \uc5ec\uc804\ud788 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc5f4\ub9b0 \uae38\uc774 \ub9ce\uc544\uc9c8\uc218\ub85d \uc88b\uc740 \uc548\ub0b4\uc758 \uac00\uce58\ub3c4 \ucee4\uc9c4\ub2e4. \uc790\ub8cc\ub97c \ub9ce\uc774 \uc5f0\uacb0\ud558\ub294 \uac83\ubcf4\ub2e4 \uc801\uc808\ud55c \uacf3\uc73c\ub85c \uc5f0\uacb0\ud558\ub294 \uc77c\uc774 \uc911\uc694\ud558\ub2e4. \uae30\uc220\uc774 \ubb38\uc11c \uc0ac\uc774\uc758 \uac70\ub9ac\ub97c \uc904\uc600\ub2e4\uace0 \ud574\uc11c \ud3b8\uc9d1\uc790\uc758 \ud310\ub2e8\uc774 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ud788\ub824 \ub3c5\uc790\uac00 \ubbff\uace0 \ub530\ub77c\uac08 \uc218 \uc788\ub294 \uae38\uc744 \uace0\ub974\ub294 \uc77c\uc774 \ub0a8\ub294\ub2e4. \uc774 \uae00\uc744 \uc77d\ub2e4\uac00 \uadfc\uac70\uc790\ub8cc\ub97c \ub204\ub974\uba74 \ub2e4\ub978 \uae30\uad00\uacfc \ub2e4\ub978 \uc791\uc131\uc790\uc758 \ubb38\uc11c\ub85c \uc774\ub3d9\ud55c\ub2e4. \ub108\ubb34 \uc790\uc5f0\uc2a4\ub7ec\uc6cc\uc11c \uc78a\uae30 \uc27d\uc9c0\ub9cc, \uc774\uac83\uc740 \uc8fc\uc18c\uc640 \uc804\uc1a1 \uaddc\uce59, \ubb38\uc11c \ud615\uc2dd\uacfc \ube0c\ub77c\uc6b0\uc800\uac00 \ud568\uaed8 \uc791\ub3d9\ud55c \uacb0\uacfc\ub2e4. \uc791\uc740 \ud074\ub9ad \ud558\ub098\uc5d0 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc624\ub79c \ud569\uc758\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc5f0\uad6c\uc2e4 \uadf8\ub9bc\uc740 \ub2f9\uc2dc\uc758 \ubd84\uc704\uae30\ub97c \ub5a0\uc62c\ub9ac\uae30 \uc704\ud55c AI \uc0bd\ud654\ub2e4. \uc2e4\uc81c \uc5f0\uad6c\uc790\uc758 \ubc29\uc774\ub098 \ucd5c\ucd08 \uc6f9 \ud654\uba74\uc744 \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc6f9\uc758 \ud0c4\uc0dd\uc5d0\uc11c \uae30\uc5b5\ud560 \uac83\uc740 \uadf8\ub9bc \uc18d \uae30\uacc4\uc758 \uc0dd\uae40\uc0c8\ubcf4\ub2e4, \uc9c0\uc2dd\uc744 \uc11c\ub85c \uac00\ub9ac\ud0a4\uac8c \ud558\uc5ec \uc77d\ub294 \uae38\uc744 \ub113\ud614\ub2e4\ub294 \uc0dd\uac01\uc774\ub2e4."}, {"id": "western-union-pasted-message", "title": "\uc804\ubcf4 \ud55c \uc7a5\uc5d0\ub294 \uc885\uc774\uac00 \ud55c \ubc88 \ub354 \ubd99\uc5b4 \uc788\ub2e4", "summary": "1959\ub144 \uc6e8\uc2a4\ud134\uc720\ub2c8\uc5b8 \uc804\ubcf4\uc5d0\uc11c \uc778\uc1c4\ub41c \uc591\uc2dd\uacfc \ub367\ubd99\uc778 \uba54\uc2dc\uc9c0\ub97c \uad6c\ubd84\ud574 \ubd05\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\uc778\ud130\ub137\uacfc \ud1b5\uc2e0", "categories": ["digital"], "url": "stories/western-union-pasted-message/index.html", "image": "../media/western-union-pasted-message.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc804\ubcf4 (Western Union Telegram) \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc804\ubcf4 \ud55c \uc7a5\uc5d0\ub294 \uc885\uc774\uac00 \ud55c \ubc88 \ub354 \ubd99\uc5b4 \uc788\ub2e4 \ud68c\uc0ac \uc774\ub984 \uc544\ub798\uc5d0 \ub193\uc778 \uc9e7\uc740 \uc18c\uc2dd 1959\ub144 \uc6e8\uc2a4\ud134\uc720\ub2c8\uc5b8 \uc804\ubcf4\uc5d0\uc11c \uc778\uc1c4\ub41c \uc591\uc2dd\uacfc \ub367\ubd99\uc778 \uba54\uc2dc\uc9c0\ub97c \uad6c\ubd84\ud574 \ubd05\ub2c8\ub2e4. \uc778\ud130\ub137\uacfc \ud1b5\uc2e0 \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \ud654\uba74\uc5d0 \ub72c \uba54\uc2dc\uc9c0\ub294 \uc190\uac00\ub77d\uc73c\ub85c \ub204\ub974\uba74 \uc5f4\ub9b0\ub2e4. \uc885\uc774\ub85c \ubc1b\uc740 \uc18c\uc2dd\uc774\ub77c\uba74 \ubcf4\ud1b5 \ud3b8\uc9c0 \ubd09\ud22c\ub97c \ub5a0\uc62c\ub9b4 \uac83\uc774\ub2e4. \uadf8\ub7f0\ub370 \uc774 \uc624\ub798\ub41c \uc804\ubcf4\ub294 \ub610 \ub2e4\ub974\ub2e4. \ud68c\uc0ac \uc774\ub984\uc774 \uc778\uc1c4\ub41c \uc885\uc774\uc5d0 \uba54\uc2dc\uc9c0 \uc885\uc774\uac00 \ud55c \ubc88 \ub354 \ubd99\uc5b4 \uc788\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc18c\uc7a5\ud55c \uc6e8\uc2a4\ud134\uc720\ub2c8\uc5b8 \uc804\ubcf4\ub2e4. \ub0a0\uc9dc\ub294 1959\ub144 4\uc6d4 13\uc77c\uc774\ub2e4. \ud55c \uc7a5\uc758 \ud1b5\uc2e0\ubb38\uc5d0\ub3c4 \ubbf8\ub9ac \ub9cc\ub4e4\uc5b4 \ub454 \ubd80\ubd84\uacfc \ub098\uc911\uc5d0 \ub354\ud574\uc9c4 \ubd80\ubd84\uc774 \ub098\ub258\uc5b4 \uc788\ub2e4. \uc0ac\uc9c4 \uc704\ucabd\uc5d0\ub294 WESTERN UNION\uc774\ub77c\ub294 \ud68c\uc0ac \uc774\ub984\uc774 \ud06c\uac8c \ubcf4\uc778\ub2e4. \uadf8 \uc544\ub798\ub85c \uae00\uc790\uac00 \uc774\uc5b4\uc9c4\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc740 \ube48\uce78\uc5d0 \uc804\ubcf4 \ub0b4\uc6a9\uc774 \uc801\ud78c \uc885\uc774\uac00 \ubd99\uc5b4 \uc788\ub2e4\uace0 \uc54c\ub824 \uc900\ub2e4. \uc591\uc2dd\uc740 \ud1b5\uc2e0\ud68c\uc0ac\uac00 \ub9c8\ub828\ud55c \uacf5\ud1b5\uc758 \ud2c0\uc774\uace0, \uadf8 \uc548\uc758 \uc18c\uc2dd\uc740 \uac01\uac01 \ub2e4\ub974\ub2e4. \uc624\ub298\ub0a0 \uac19\uc740 \uba54\uc2e0\uc800 \ud654\uba74\uc73c\ub85c \uc11c\ub85c \ub2e4\ub978 \uba54\uc2dc\uc9c0\ub97c \uc8fc\uace0\ubc1b\ub294 \ubaa8\uc2b5\uc744 \ub5a0\uc62c\ub9b4 \uc218\ub3c4 \uc788\ub2e4. \ud654\uba74 \ub300\uc2e0 \uc885\uc774\uac00 \ub0a8\uc544 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c \uc190\uc5d0 \uc7a1\ud788\ub294 \ub290\ub08c\uc740 \uc0ac\ubb47 \ub2e4\ub974\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc774 \uc804\ubcf4\uac00 \ub274\uc695 \ube0c\ub8e8\ud074\ub9b0\uc5d0 \uc788\ub358 \uc774\uad6c\uc5d0\uac8c \ubcf4\ub0b8 \uac83\uc73c\ub85c \ubcf4\uc778\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc5ec\uae30\uc11c \uc7a5\uc18c\uc640 \uc774\ub984\uc740 \ud55c \uc904\uc758 \uc8fc\uc18c \uc774\uc0c1\uc774\ub2e4. \uc791\uc740 \uc885\uc774\ub97c \ud2b9\uc815\ud55c \uc0ac\ub78c\uc758 \uc0dd\ud65c\uacfc \uc774\uc5b4 \uc8fc\ub294 \ub2e8\uc11c\uac00 \ub41c\ub2e4. \ub2e4\ub9cc \u2018\ubcf4\uc778\ub2e4\u2019\ub294 \ud310\ub2e8\uc744 \ud655\uc815\ub41c \ubc1c\uc1a1 \uacbd\uc704\ub85c \ubc14\uafb8\uc5b4 \uc77d\uc9c0\ub294 \ub9d0\uc790. \uc774 \uc790\ub8cc\ub294 \uc218\uc2e0\uc790\ub97c \ucd94\uc815\ud558\uace0 \uc788\ub2e4. \ub204\uac00 \uc5b4\ub5a4 \ub9c8\uc74c\uc73c\ub85c \ubcf4\ub0c8\ub294\uc9c0\uae4c\uc9c0 \ub300\ud654\ub97c \ub9cc\ub4e4\uc5b4 \ubd99\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \ub0a0\uc9dc\uc640 \uc218\uc2e0\uc9c0, \ub0a8\uc544 \uc788\ub294 \ud615\uc2dd\ub9cc\uc73c\ub85c\ub3c4 \ucda9\ubd84\ud788 \ubcfc\uac70\ub9ac\uac00 \uc788\ub2e4. \uc804\ubcf4\uc758 \ubc14\ud0d5 \uc885\uc774\uc5d0\ub294 \ud1b5\uc2e0\ud68c\uc0ac\uc758 \uc774\ub984\uacfc \uc815\ud574\uc9c4 \uce78\uc774 \uba3c\uc800 \uc778\uc1c4\ub418\uc5b4 \uc788\ub2e4. \uc804\ub2ec\ud560 \ub9d0\uc740 \uadf8 \ub4a4\uc5d0 \ubcc4\ub3c4\uc758 \uc885\uc774\ub85c \ub4e4\uc5b4\uc628\ub2e4. \uac1c\uc778\uc758 \uc18c\uc2dd\uc774 \ud68c\uc0ac\uc758 \uacf5\ud1b5 \uc591\uc2dd\uc744 \uac70\uccd0 \uc804\ub2ec\ub418\ub294 \uad6c\uc870\ub2e4. \uc0ac\uc9c4\uc744 \ubcfc \ub54c \uc778\uc1c4\ub41c \ubd80\ubd84\uacfc \ub367\ubd99\uc778 \ubd80\ubd84\uc744 \uad6c\ubcc4\ud558\uba74, \ud55c \uc7a5\uc758 \uc885\uc774\ub97c \ub9cc\ub4dc\ub294 \uc2dc\uac04\uc774 \ubaa8\ub450 \uac19\uc9c0 \uc54a\uc558\uc74c\uc744 \uc54c \uc218 \uc788\ub2e4. \uc774\uac83\uc740 \uc7a5\uc2dd\uc758 \ucc28\uc774\ubcf4\ub2e4 \uc5c5\ubb34\uc758 \ud750\ub984\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ud68c\uc0ac\ub294 \ub9ce\uc740 \uba54\uc2dc\uc9c0\ub97c \ub2e4\ub8e8\uae30 \uc704\ud574 \uac19\uc740 \ud2c0\uc744 \uc4f0\uace0, \ubc1b\ub294 \uc0ac\ub78c\uc740 \uadf8 \uc548\uc5d0\uc11c \uc790\uae30\uc5d0\uac8c \uc628 \ub9d0\uc744 \uc77d\ub294\ub2e4. \uc624\ub298\uc758 \uba54\uc2dc\uc9c0 \ucc3d\uc5d0\uc11c\ub3c4 \ubc14\ub00c\uc9c0 \uc54a\ub294 \ud654\uba74\uacfc \ub9e4\ubc88 \ub2e4\ub978 \ub0b4\uc6a9\uc774 \ud568\uaed8 \uc788\uc9c0\ub9cc, \uc885\uc774\uc5d0\uc11c\ub294 \uadf8 \ub450 \uce35\uc774 \uc2e4\uc81c\ub85c \uacb9\uccd0 \ubd99\uc5b4 \uc788\ub2e4\ub294 \uc810\uc774 \ub208\uc5d0 \ubcf4\uc778\ub2e4. \ud3b8\uc9c0\uc5d0\uc11c\ub294 \uc4f4 \uc0ac\ub78c\uc774 \uc0ac\uc6a9\ud55c \uc885\uc774\uac00 \uc774\ub3d9\ud574 \ubc1b\ub294 \uc0ac\ub78c\uc5d0\uac8c \uac08 \uc218 \uc788\ub2e4. \uc804\ubcf4\uc5d0\uc11c\ub294 \uc804\ub2ec\ubc1b\uc740 \ub0b4\uc6a9\uc744 \ud604\uc9c0\uc758 \uc591\uc2dd\uc5d0 \uc62e\uaca8 \ub0b4\uc5b4 \uc8fc\ub294 \uacfc\uc815\uc774 \uc911\uc694\ud588\ub2e4. \uc774 \uc720\ubb3c\uc758 \ubd99\uc778 \uc885\uc774\ub294 \uadf8 \uc804\ub2ec \ubc29\uc2dd\uc758 \ud754\uc801\uc744 \uc0b4\ud3b4\ubcfc \ub2e8\uc11c\ub2e4. \ud55c\ucabd\uc5d0\uc11c \uc791\uc131\ud55c \uc6d0\ubcf8 \uc885\uc774 \uc804\uccb4\uac00 \uadf8\ub300\ub85c \ub2e4\ub978 \ucabd\uc5d0 \ub3c4\ucc29\ud588\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc774 \ubb3c\uac74\ub9cc\uc73c\ub85c \uc0ac\uc6a9\ud55c \uae30\uacc4\uc640 \uc804\uc1a1 \uacbd\ub85c\ub97c \ubaa8\ub450 \uc54c \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub290 \uad50\ud658 \uc9c0\uc810\uc744 \uac70\uccd0 \uc5bc\ub9c8\ub098 \ube68\ub9ac \uc804\ub2ec\ub418\uc5c8\ub294\uc9c0\ub294 \ubcc4\ub3c4\uc758 \uae30\ub85d\uc774 \ud544\uc694\ud55c \ubb38\uc81c\ub2e4. \uc5ec\uae30\uc11c\ub294 \ub0a8\uc740 \ud615\ud0dc\uc5d0\uc11c \ubd84\uba85\ud788 \uc77d\uc744 \uc218 \uc788\ub294 \uc591\uc2dd\uacfc \uba54\uc2dc\uc9c0\uc758 \uacb0\ud569\uc744 \uba3c\uc800 \ubcf8\ub2e4. \ud1b5\uc2e0\uc758 \uc5ed\uc0ac\uac00 \uc7a5\uce58\uc758 \ubc1c\uba85\ubfd0 \uc544\ub2c8\ub77c \ubc1b\uc740 \ub9d0\uc758 \ubaa8\uc591\uc5d0\ub3c4 \ub0a8\uc544 \uc788\ub2e4. 1959\ub144 4\uc6d4 13\uc77c\uc774\ub77c\ub294 \ub0a0\uc9dc\ub294 \ubb3c\uac74\uc744 \ud2b9\uc815\ud55c \uc2dc\uac04\uc5d0 \ubb36\uc5b4 \uc900\ub2e4. \ube0c\ub8e8\ud074\ub9b0\uc758 \uc774\uad6c\ub77c\ub294 \uc218\uc2e0 \ucd94\uc815\uc740 \uadf8 \uc2dc\uac04\uc744 \ud55c \uc0ac\ub78c\uc758 \uac70\ucc98\uc640 \uc5f0\uacb0\ud55c\ub2e4. \uc9e7\uc740 \ud1b5\uc2e0\ubb38\uc774 \uc788\uc5b4\ub3c4 \ub204\uac00 \uc77d\uc5c8\ub294\uc9c0 \ubaa8\ub974\uba74 \uc774\uc57c\uae30\ub294 \ub9e4\uc6b0 \ub113\uac8c \uc5f4\ub824 \uc788\ub2e4. \ubc18\ub300\ub85c \uc774\ub984\uacfc \uc7a5\uc18c\uac00 \ub0a8\uc73c\uba74 \ub2e4\ub978 \uc790\ub8cc\uc640 \ub300\uc870\ud574 \ubcfc \uae38\uc774 \uc0dd\uae34\ub2e4. \uc774\ub54c \ucd94\uc815\uc774\ub77c\ub294 \ub9d0\uc744 \uc9c0\uc6b0\uc9c0 \uc54a\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \ud655\uc2e4\ud558\uc9c0 \uc54a\uc740 \uc218\uc2e0\uc790\ub97c \ud655\uc815\ud558\uace0 \uadf8 \uc0ac\ub78c\uc758 \uae30\uc068\uacfc \uc2ac\ud514\uae4c\uc9c0 \uc368 \ubc84\ub9ac\uba74 \ub0a8\uc740 \uc790\ub8cc\ubcf4\ub2e4 \uc774\uc57c\uae30\uac00 \uc55e\uc11c \ub098\uac04\ub2e4. \uc804\ubcf4\ub97c \uc77d\ub294 \uc7ac\ubbf8\ub294 \ubaa8\ub4e0 \ube48\uce78\uc744 \uc18c\uc124\ub85c \ucc44\uc6b0\ub294 \ub370\ub9cc \uc788\uc9c0 \uc54a\ub2e4. \uc5b4\ub514\uae4c\uc9c0 \uc5f0\uacb0\ub418\uace0 \ubb34\uc5c7\uc774 \uc544\uc9c1 \ub0a8\ub294\uc9c0 \ucc28\ubd84\ud558\uac8c \ub530\ub77c\uac00\ub294 \ub370\ub3c4 \uc788\ub2e4. \uc804\ubcf4\ub97c \ub9cc\ub4e4\uace0 \uc804\ub2ec\ud55c \ud68c\uc0ac\uc5d0\ub294 \uc218\ub9ce\uc740 \ud1b5\uc2e0\ubb38 \uac00\uc6b4\ub370 \ud558\ub098\uc600\uc744 \uc218 \uc788\ub2e4. \ubc1b\uc740 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ub2e4\uc2dc \ubcf4\uae30 \uc704\ud574 \ubcf4\uad00\ud560 \ub2e8 \ud55c \ubc88\uc758 \uc18c\uc2dd\uc774\uc5c8\uc744 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc65c \uc774 \uc790\ub8cc\ub97c \uac04\uc9c1\ud588\ub294\uc9c0\ub294 \ub0a8\uc740 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ub2e8\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4. \uac19\uc740 \uc885\uc774\uac00 \ud68c\uc0ac\uc758 \uc5c5\ubb34\uc640 \uac1c\uc778\uc758 \uc0dd\ud65c\uc744 \ub3d9\uc2dc\uc5d0 \uc9c0\ub098\uc654\ub2e4\ub294 \uc810\uc744 \ubcfc \uc218 \uc788\ub2e4. \uae30\uc99d \ub4a4\uc5d0\ub294 \uadf8 \uc885\uc774\uac00 \uc5ec\ub7ec \uc0ac\ub78c\uc774 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub294 \uc790\ub8cc\uac00 \ub41c\ub2e4. \ub0a0\uc9dc\uc640 \uc8fc\uc18c, \uc885\uc774\ub97c \ubd99\uc778 \uacbd\uacc4\uae4c\uc9c0 \uad00\ucc30\uc758 \ub300\uc0c1\uc774 \ubc14\ub010\ub2e4. \ub0b4\uc6a9\uc774 \uc9e7\ub2e4\uace0 \uc790\ub8cc\ub85c\uc11c\uc758 \uc9c8\ubb38\ub3c4 \uc801\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc804\ubcf4 \ud55c \uc7a5\uc740 \ub204\uad70\uac00\uc758 \ub9d0\uc744 \ub2f4\uc73c\uba74\uc11c, \ub2f9\uc2dc \uc0ac\ud68c\uac00 \ub9d0\uc744 \uba40\ub9ac \ubcf4\ub0b4\uace0 \ubc1b\uc544 \uc801\uace0 \uac74\ub124\ub358 \ubc29\uc2dd\ub3c4 \ud568\uaed8 \ubcf4\uc874\ud558\uace0 \uc788\ub2e4. \uc774 \uc804\ubcf4\ub294 \uc904\ub9ac\uc544 \uba40\ub85d\uc774 \uc77c\uad04 \uae30\uc99d\ud55c \uc790\ub8cc\uc5d0 \ud3ec\ud568\ub41c\ub2e4. \uac1c\uc778\uc774 \uac04\uc9c1\ud558\ub358 \ud1b5\uc2e0\ubb38\uc774 \ubc15\ubb3c\uad00\uc758 \uae30\ub85d\uc774 \ub41c \uac83\uc774\ub2e4. \ud68c\uc0ac\uc758 \uc778\uc1c4 \uc591\uc2dd\uc774 \uc5b4\ub290 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc790\uc2e0\uc758 \uc18c\uc2dd\uc744 \ub2f4\uc740 \ubb3c\uac74\uc774\uae30\ub3c4 \ud588\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub290\uaef4\uc9c4\ub2e4. \ub2e4\uc2dc \uc0ac\uc9c4\uc744 \ubcf4\uba74 \ud68c\uc0ac \uc774\ub984\ubcf4\ub2e4 \ub367\ubd99\uc778 \uc885\uc774 \ucabd\uc5d0 \ub208\uc774 \uac08 \uc218 \uc788\ub2e4. \ub611\uac19\uc740 \uc591\uc2dd\uc744 \ub2e8 \ud55c \ubc88\uc758 \uc18c\uc2dd\uc73c\ub85c \ubc14\uafb8\ub294 \ubd80\ubd84\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \uc9e7\uac8c \uc804\ub2ec\ub41c \ub9d0\ub3c4 \ubb3c\uac74\uc73c\ub85c \ub0a8\uc73c\uba74, \uc18c\uc2dd\uc744 \uc8fc\uace0\ubc1b\ub358 \ubc29\uc2dd\uae4c\uc9c0 \ud568\uaed8 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "wifi-connected-without-internet", "title": "\uc640\uc774\ud30c\uc774 \u2014 \uc5f0\uacb0\ub410\ub294\ub370 \uc778\ud130\ub137\uc774 \uc548 \ub418\ub294 \uae4c\ub2ed", "summary": "\uae30\uae30\uc640 \uac00\uae4c\uc6b4 \ub124\ud2b8\uc6cc\ud06c, \uc778\ud130\ub137\uacfc \uc6f9\uc744 \ub098\ub204\uc5b4 \ubcf4\uba70 \uc640\uc774\ud30c\uc774 \uc5f0\uacb0\uc758 \uc758\ubbf8\ub97c \uc774\ud574\ud569\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\uc778\ud130\ub137\uacfc \ud1b5\uc2e0", "categories": ["digital"], "url": "stories/wifi-connected-without-internet/index.html", "image": "../media/wifi-connected-without-internet.png", "alt": "\ub178\ud2b8\ubd81\uacfc \uc791\uc740 \ubb34\uc120 \uc7a5\uce58\uac00 \uc788\ub294 \uc9d1 \uc548\uc5d0\uc11c \uc5f0\uacb0\uc744 \uc0dd\uac01\ud558\ub294 \uc0ac\ub78c\uc758 \uc0bd\ud654.", "text": "\uc640\uc774\ud30c\uc774 \u2014 \uc5f0\uacb0\ub410\ub294\ub370 \uc778\ud130\ub137\uc774 \uc548 \ub418\ub294 \uae4c\ub2ed \uc9d1 \uc548\uc758 \uae38\uacfc \ubc14\uae65\uc73c\ub85c \ub098\uac00\ub294 \uae38\uc740 \ub2e4\ub974\ub2e4 \uae30\uae30\uc640 \uac00\uae4c\uc6b4 \ub124\ud2b8\uc6cc\ud06c, \uc778\ud130\ub137\uacfc \uc6f9\uc744 \ub098\ub204\uc5b4 \ubcf4\uba70 \uc640\uc774\ud30c\uc774 \uc5f0\uacb0\uc758 \uc758\ubbf8\ub97c \uc774\ud574\ud569\ub2c8\ub2e4. \uc778\ud130\ub137\uacfc \ud1b5\uc2e0 \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \ud734\ub300\uc804\ud654\uc5d0\ub294 \uc640\uc774\ud30c\uc774\uac00 \uc5f0\uacb0\ub418\uc5c8\ub2e4\uace0 \ub098\uc628\ub2e4. \uadf8\ub7f0\ub370 \uc6f9\ud398\uc774\uc9c0\ub294 \uc5f4\ub9ac\uc9c0 \uc54a\ub294\ub2e4. \uc5f0\uacb0\ub418\uc5c8\ub2e4\ub294 \ub9d0\uc774 \ud2c0\ub9b0 \uac83\uc77c\uae4c. \uc774 \uc0c1\ud669\uc740 \uae30\uc220\uc774 \ub9d0\uc7a5\ub09c\uc744 \ud574\uc11c\uac00 \uc544\ub2c8\ub77c \uc6b0\ub9ac\uac00 \uc11c\ub85c \ub2e4\ub978 \uc5f0\uacb0\uc744 \ud55c \ub2e8\uc5b4\ub85c \ubd80\ub974\uae30 \ub54c\ubb38\uc5d0 \ud5f7\uac08\ub9b4 \uc218 \uc788\ub2e4. \uc640\uc774\ud30c\uc774\ub85c \uc8fc\ubcc0\uc758 \ub124\ud2b8\uc6cc\ud06c\uc5d0 \ucc38\uc5ec\ud558\ub294 \uc77c\uacfc \uc778\ud130\ub137 \ub108\uba38\uc758 \uc0ac\uc774\ud2b8\uc5d0 \ub2ff\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uc9d1 \uc548 \ubcf5\ub3c4\uc5d0 \ub098\uc654\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ubc16\uc73c\ub85c \ub098\uac00\ub294 \ubb38\uc774 \uc5f4\ub838\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ub098\ub204\uc5b4 \uc0dd\uac01\ud558\uba74 \uc870\uae08 \uc27d\ub2e4. \uc2e4\uc81c \ub124\ud2b8\uc6cc\ud06c\ub97c \ubcf5\ub3c4\uc640 \ub611\uac19\ub2e4\uace0 \ubcf4\ub294 \uac83\uc740 \uc544\ub2c8\uace0 \uc5f0\uacb0\uc758 \ub2e8\uacc4\ub97c \ub5a0\uc62c\ub9ac\ub294 \ube44\uc720\ub2e4. \ub450 \ucef4\ud4e8\ud130\uac00 \uc815\ubcf4\ub97c \uc8fc\uace0\ubc1b\uc73c\ub824\uba74 \uc5f0\uacb0\uc774 \ud544\uc694\ud558\ub2e4. \ucf00\uc774\ube14\uc744 \uc4f0\ub294 \ubc29\ubc95\ub3c4 \uc788\uace0 \uc640\uc774\ud30c\uc774 \uac19\uc740 \ubb34\uc120 \ubc29\uc2dd\uc744 \uc4f0\ub294 \ubc29\ubc95\ub3c4 \uc788\ub2e4. \uc640\uc774\ud30c\uc774\ub294 \uc774\ub807\uac8c \uae30\uae30\ub4e4\uc744 \ub124\ud2b8\uc6cc\ud06c\uc5d0 \uc5f0\uacb0\ud558\ub294 \ubc29\ubc95 \uac00\uc6b4\ub370 \ud558\ub098\ub2e4. \uc774\ub984\uc774 \uc775\uc219\ud558\ub2e4\uace0 \uc778\ud130\ub137 \uc804\uccb4\uc640 \uac19\uc740 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uac00\uae4c\uc6b4 \ub124\ud2b8\uc6cc\ud06c \uc548\uc5d0\uc11c \ud1b5\uc2e0\ud560 \uc218 \uc788\ub294 \uc0c1\ud0dc\uc640 \ub2e4\ub978 \uc9c0\uc5ed\uc758 \ub9dd\uae4c\uc9c0 \uc774\uc5b4\uc9c4 \uc0c1\ud0dc\ub294 \uad6c\ubd84\ub41c\ub2e4. \uac19\uc740 \uce74\ud398\uc5d0 \uc788\ub294 \uae30\uae30\uac00 \uadf8\uacf3\uc758 \ubb34\uc120 \uc811\uc18d \uc7a5\uce58\uc5d0 \uc5f0\uacb0\ub418\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc678\ubd80\uc758 \ubaa8\ub4e0 \uc11c\ube44\uc2a4\uae4c\uc9c0 \ub2ff\uc558\ub2e4\uace0 \ud560 \uc218\ub294 \uc5c6\ub2e4. \uc9d1\uc5d0\uc11c \uacf5\uc720\uae30\ub77c\uace0 \ubd80\ub974\ub294 \uc791\uc740 \uc0c1\uc790\uc5d0\ub294 \uc5ec\ub7ec \uae30\ub2a5\uc774 \ud568\uaed8 \ub4e4\uc5b4\uac08 \uc218 \uc788\ub2e4. \ubb34\uc120 \uae30\uae30\ub97c \uc5f0\uacb0\ud558\ub294 \uae30\ub2a5\uacfc \ub124\ud2b8\uc6cc\ud06c \uc0ac\uc774\ub85c \ub370\uc774\ud130\ub97c \ubcf4\ub0b4\ub294 \uae30\ub2a5\uc774 \ud55c \uae30\uae30\uc5d0 \ubaa8\uc774\uae30\ub3c4 \ud55c\ub2e4. \ud1b5\uc2e0 \uc7a5\ube44\uc758 \uad6c\uc131\uc740 \uc774\uc6a9 \ud658\uacbd\uc5d0 \ub530\ub77c \ub2e4\ub974\ub2e4. \ud55c \uc0c1\uc790 \uc548\uc5d0 \ub4e4\uc5b4 \uc788\ub2e4\uace0 \ubaa8\ub4e0 \uc5ed\ud560\uc774 \uac19\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\uc911 \uc77c\ubd80\uc758 \uc5f0\uacb0\uc774 \ub418\uc5b4 \uc788\uc5b4\ub3c4 \ub2e4\ub978 \ubd80\ubd84\uc5d0\ub294 \ubb38\uc81c\uac00 \uc788\uc744 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \uc640\uc774\ud30c\uc774 \uc5f0\uacb0\uacfc \uc778\ud130\ub137 \uc774\uc6a9\uc774 \uac19\uc740 \uc21c\uac04\uc5d0 \ud56d\uc0c1 \uc131\uacf5\ud558\uac70\ub098 \uc2e4\ud328\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubcf4\uc774\ub294 \ubb3c\uac74 \ud558\ub098\uc640 \ub0b4\ubd80 \uae30\ub2a5 \ud558\ub098\ub97c \uac19\uc740 \uac83\uc73c\ub85c \uc0dd\uac01\ud558\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc774\ud574\uc5d0 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. MDN\uc740 \uc5ec\ub7ec \ub124\ud2b8\uc6cc\ud06c\ub97c \uc5f0\uacb0\ud558\ub294 \uc7a5\uce58\ub85c \ub77c\uc6b0\ud130\ub97c \uc124\uba85\ud55c\ub2e4. \uac19\uc740 \ub9dd \uc548\uc758 \uae30\uae30 \uc0ac\uc774\uc5d0\uc11c \uc804\ub2ec\ud558\ub294 \uc77c\uacfc \ub2e4\ub978 \ub9dd\uc73c\ub85c \ubcf4\ub0b4\ub294 \uc77c\uc5d0\ub294 \uc5ed\ud560\uc758 \ucc28\uc774\uac00 \uc788\ub2e4. \ub370\uc774\ud130\ub97c \ubaa9\uc801\uc9c0\ub85c \ub118\uae30\ub294 \uae38\uc774 \ud544\uc694\ud558\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc8fc\uc18c\uc640 \uc7a5\ube44\uc758 \uae30\uc220 \uc774\ub984\uc744 \ubaa8\ub450 \uc678\uc6b8 \ud544\uc694\uac00 \uc5c6\ub2e4. \uac00\uae4c\uc6b4 \uc5f0\uacb0\ub9cc \uc644\uc131\ud574\uc11c\ub294 \uba3c \uacf3\uc5d0 \uc788\ub294 \uc0c1\ub300\uc5d0\uac8c \ub2ff\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4\ub294 \uc6d0\ub9ac\ub97c \ubcf4\uba74 \ub41c\ub2e4. \uc9d1 \uc548\uc758 \uae38\uc744 \ub9cc\ub4e0 \ub4a4\uc5d0\ub3c4 \uadf8 \uae38\uc744 \ubc14\uae65\uacfc \uc787\ub294 \uc900\ube44\uac00 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uac00\uc815\uc758 \ub124\ud2b8\uc6cc\ud06c\ub294 \uc778\ud130\ub137 \uc11c\ube44\uc2a4 \uc81c\uacf5\uc790\uc758 \ub9dd\uacfc \uc5f0\uacb0\ub418\uc5b4 \ub354 \ub113\uc740 \uc138\uacc4\uc5d0 \ub2ff\ub294\ub2e4. \uc5ec\ub7ec \uc81c\uacf5\uc790\uc758 \ub9dd\uc774 \uc11c\ub85c \uc774\uc5b4\uc9c4 \uac83\uc774 \uc778\ud130\ub137\uc758 \uc911\uc694\ud55c \ubc14\ud0d5\uc774\ub2e4. \uc9d1\uc5d0 \uc7a5\ube44\ub97c \uc124\uce58\ud588\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc678\ubd80 \uc5f0\uacb0 \uc11c\ube44\uc2a4\uac00 \uc815\uc0c1\uc801\uc73c\ub85c \uc81c\uacf5\ub41c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub978 \uc870\uac74\uc774\ub2e4. \uc5b4\ub5a4 \uad6c\uac04\uc5d0\uc11c \ud1b5\uc2e0\uc774 \ub04a\uae30\uba74 \uac00\uae4c\uc6b4 \uc7a5\uce58\uc640\uc758 \ubb34\uc120 \uc5f0\uacb0\uc774 \ub0a8\uc544 \uc788\uc5b4\ub3c4 \uc6f9\uc0ac\uc774\ud2b8\ub97c \uc774\uc6a9\ud558\uc9c0 \ubabb\ud560 \uc218 \uc788\ub2e4. \uc774\uac83\uc740 \ud2b9\uc815 \ub3c5\uc790\uc758 \uae30\uae30\ub97c \uc9c4\ub2e8\ud55c \uacb0\uacfc\uac00 \uc544\ub2c8\ub2e4. \uac19\uc740 \ud654\uba74 \ud45c\uc2dc \ub4a4\uc5d0 \uc5ec\ub7ec \uc5f0\uacb0 \ub2e8\uacc4\uac00 \uc788\ub2e4\ub294 \uc124\uba85\uc774\ub2e4. \uace0\uc7a5 \uc6d0\uc778\uc744 \ud558\ub098\uc758 \ud45c\uc2dc\ub9cc\uc73c\ub85c \ud655\uc815\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \uad6c\uc131\uacfc \ud5c8\uc6a9 \uc870\uac74\uc774 \ub9de\uc73c\uba74 \uac19\uc740 \ub124\ud2b8\uc6cc\ud06c\uc758 \uae30\uae30\ub4e4\ub07c\ub9ac \uc790\ub8cc\ub97c \uc8fc\uace0\ubc1b\uc744 \uc218 \uc788\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \ub0b4\ubd80\uc758 \uacf5\uc720 \uc790\ub8cc\ub098 \ub124\ud2b8\uc6cc\ud06c \ud504\ub9b0\ud130\ub97c \uc0ac\uc6a9\ud558\ub294 \ubc29\uc2dd\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc774\ub7f0 \ud1b5\uc2e0\uc774 \ubc18\ub4dc\uc2dc \uba3c \uc678\ubd80 \uc11c\ubc84\ub97c \uac70\uccd0\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb3c\ub860 \ubaa8\ub4e0 \uae30\uae30\uac00 \uc11c\ub85c \uc790\ub3d9\uc73c\ub85c \ubcf4\uc774\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub124\ud2b8\uc6cc\ud06c\uc758 \uc124\uc815\uacfc \uc571\uc758 \ub3d9\uc791, \uc811\uadfc \uad8c\ud55c\ub3c4 \ud544\uc694\ud558\ub2e4. \uc911\uc694\ud55c \uc810\uc740 \uc640\uc774\ud30c\uc774\ub97c \uc778\ud130\ub137\uc758 \ub2e4\ub978 \uc774\ub984\uc73c\ub85c\ub9cc \uc0dd\uac01\ud558\uba74 \uc774\ub7f0 \uac00\uae4c\uc6b4 \ud1b5\uc2e0\uc758 \uc5ed\ud560\uc744 \ub193\uce58\uac8c \ub41c\ub2e4\ub294 \uac83\uc774\ub2e4. \ub124\ud2b8\uc6cc\ud06c\uc5d0\ub294 \uc5ec\ub7ec \ubc94\uc704\uac00 \uc788\ub2e4. \uc778\ud130\ub137\uc740 \uc5ec\ub7ec \uae30\uae30\ub97c \uc5f0\uacb0\ud558\ub294 \uae30\ubc18\uc774\ub2e4. \uc6f9\uc740 \uadf8 \uc704\uc5d0\uc11c \uc774\uc6a9\ud558\ub294 \uc11c\ube44\uc2a4 \uac00\uc6b4\ub370 \ud558\ub098\ub2e4. \uc6f9\ud398\uc774\uc9c0\ub97c \ubc1b\ub294 \uac83 \uc678\uc5d0\ub3c4 \uc804\uc790\uc6b0\ud3b8\uc774\ub098 \ub2e4\ub978 \ud1b5\uc2e0 \uc11c\ube44\uc2a4\uac00 \uc774 \uae30\ubc18\uc744 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4. \uc6b0\ub9ac\uac00 \uc790\uc8fc \uc4f0\ub294 \uc11c\ube44\uc2a4\uac00 \uc804\uccb4\uc758 \uc774\ub984\ucc98\ub7fc \ub290\uaef4\uc9c8 \ub54c\uac00 \uc788\ub294 \uc148\uc774\ub2e4. \ub530\ub77c\uc11c \uc6f9\ud398\uc774\uc9c0 \ud558\ub098\uac00 \uc548 \uc5f4\ub9b0\ub2e4\uace0 \ubaa8\ub4e0 \uc778\ud130\ub137 \uc5f0\uacb0\uc774 \ub04a\uacbc\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud574\ub2f9 \uc11c\ubc84\ub098 \uc8fc\uc18c\ub97c \ucc3e\ub294 \uacfc\uc815, \ud398\uc774\uc9c0 \uc790\uccb4\uc758 \ubb38\uc81c\ub3c4 \uc788\uc744 \uc218 \uc788\ub2e4. \uc774\ubc88 \uae00\uc740 \ubb38\uc81c \ud574\uacb0 \ubaa9\ub85d\uc744 \uc8fc\uae30\ubcf4\ub2e4 \uc5b4\ub5a4 \uc9c8\ubb38\ub4e4\uc774 \uc11c\ub85c \ub2e4\ub978\uc9c0\ub97c \uc54c\ub824 \uc8fc\ub294 \uc774\uc57c\uae30\ub2e4. \uc640\uc774\ud30c\uc774\uc5d0 \uc5f0\uacb0\ub418\uc5c8\ub2e4\ub294 \ud45c\uc2dc\uac00 \uc54c\ub824 \uc8fc\ub294 \uac83\uacfc \ud2b9\uc815 \uc11c\ube44\uc2a4\uac00 \uc751\ub2f5\ud588\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub974\ub2e4. \uae30\uae30\ub294 \uc790\uc2e0\uc774 \ud655\uc778\ud560 \uc218 \uc788\ub294 \uc5f0\uacb0 \uc0c1\ud0dc\ub97c \ud45c\uc2dc\ud558\uc9c0\ub9cc \uc0ac\uc6a9\uc790\ub294 \uadf8 \ud45c\uc2dc\ub97c \uc778\ud130\ub137 \uc804\uccb4\uac00 \uc798\ub41c\ub2e4\ub294 \ub9d0\ub85c \ubc1b\uc544\ub4e4\uc774\uae30 \uc27d\ub2e4. \uc774 \ucc28\uc774\ub97c \uc54c\uba74 \uc5f0\uacb0\ub410\ub294\ub370 \uc548 \ub41c\ub2e4\ub294 \ub9d0\uc774 \uaf2d \ubaa8\uc21c\uc740 \uc544\ub2c8\ub77c\ub294 \uac83\uc744 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uac00\uae4c\uc6b4 \ubb34\uc120 \uc5f0\uacb0\uc740 \ub418\uc5b4 \uc788\uace0 \ub2e4\uc74c \uad6c\uac04\uc740 \ud655\uc778\ub418\uc9c0 \uc54a\uc558\uc744 \uc218 \uc788\ub2e4. \uc5b4\ub5a4 \uc0c1\ud0dc\uac00 \ud655\uc778\ub418\uc5c8\ub294\uc9c0\ub97c \ub098\ub204\uba74 \ubd88\ud3b8\ud55c \uc0c1\ud669\ub3c4 \uc870\uae08 \ub354 \uad6c\uccb4\uc801\uc778 \uc9c8\ubb38\uc73c\ub85c \ubc14\ub010\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \ucc45\uc0c1\uacfc \uc791\uc740 \ubb34\uc120 \uc7a5\uce58\uac00 \uc788\ub294 \uc9d1 \uc548\uc758 \ubd84\uc704\uae30\ub97c \ud45c\ud604\ud588\ub2e4. \uc2e4\uc81c \uacf5\uc720\uae30\uc758 \uc131\ub2a5 \ud45c\uc2dc\ub098 \ud1b5\uc2e0 \ubc94\uc704\ub97c \uce21\uc815\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \uae30\uae30\uc640 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc5f0\uacb0\uc758 \ucc28\uc774\ub97c \ub5a0\uc62c\ub9ac\uae30 \uc704\ud55c \uadf8\ub9bc\uc774\ub2e4. \uc640\uc774\ud30c\uc774\ub294 \ud3b8\ub9ac\ud574\uc11c \uc5f0\uacb0\uc758 \uacfc\uc815\uc744 \uc78a\uac8c \ub9cc\ub4e0\ub2e4. \uadf8\ub7ec\ub098 \ubb34\uc120\uc774\ub77c\ub294 \ub9d0\uc774 \uae38\uc774 \uc5c6\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uae30\uae30\uc5d0\uc11c \uac00\uae4c\uc6b4 \uc7a5\uce58\ub85c, \ub2e4\ub978 \ub124\ud2b8\uc6cc\ud06c\ub97c \uc9c0\ub098 \uc11c\ube44\uc2a4\uc5d0 \ub2ff\ub294 \uc5ec\ub7ec \uad00\uacc4\uac00 \uc788\ub2e4. \uc775\uc219\ud55c \uc5f0\uacb0 \ud45c\uc2dc\ub97c \ud55c \ubc88 \ub098\ub204\uc5b4 \uc77d\uc73c\uba74 \uc778\ud130\ub137\uc774 \uc870\uae08 \ub35c \ub9c9\uc5f0\ud55c \uac83\uc774 \ub41c\ub2e4."}, {"id": "zip-files-and-repetition", "title": "ZIP \u2014 \uc5ec\ub7ec \ud30c\uc77c\uc740 \uc5b4\ub5bb\uac8c \ud55c \ubd09\ud22c\uc5d0 \ub4e4\uc5b4\uac08\uae4c", "summary": "ZIP\uc758 \ud30c\uc77c \ubb36\uc74c\uacfc \ubb34\uc190\uc2e4 \uc555\ucd95\uc744 \ub098\ub204\uc5b4 \ubcf4\uace0 \ubc18\ubcf5 \uc815\ubcf4\ub97c \uc904\uc5ec \uc801\ub294 \uc6d0\ub9ac\ub97c \uc774\ud574\ud569\ub2c8\ub2e4.", "category": "digital", "category_title": "\ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138", "subcategory": "\ub370\uc774\ud130\uc640 \uae30\ub85d", "categories": ["digital"], "url": "stories/zip-files-and-repetition/index.html", "image": "../media/zip-files-and-repetition.png", "alt": "\uc5ec\ub7ec \ubb38\uc11c\ub97c \uc815\ub9ac\ud558\ub294 \uc0ac\ub78c \uacc1\uc5d0 \uc9c0\ud37c \ud30c\uc6b0\uce58\uac00 \ub193\uc778 AI \ube44\uc720 \uc7a5\uba74.", "text": "ZIP \u2014 \uc5ec\ub7ec \ud30c\uc77c\uc740 \uc5b4\ub5bb\uac8c \ud55c \ubd09\ud22c\uc5d0 \ub4e4\uc5b4\uac08\uae4c \ud55c\ub370 \ubb36\ub294 \uc77c\uacfc \ud06c\uae30\ub97c \uc904\uc774\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4 ZIP\uc758 \ud30c\uc77c \ubb36\uc74c\uacfc \ubb34\uc190\uc2e4 \uc555\ucd95\uc744 \ub098\ub204\uc5b4 \ubcf4\uace0 \ubc18\ubcf5 \uc815\ubcf4\ub97c \uc904\uc5ec \uc801\ub294 \uc6d0\ub9ac\ub97c \uc774\ud574\ud569\ub2c8\ub2e4. \ub370\uc774\ud130\uc640 \uae30\ub85d \ucef4\ud4e8\ud130\uc640 \ub514\uc9c0\ud138 \uc0ac\uc9c4 \uc5f4 \uc7a5\uc744 \ubcf4\ub0b4\ub824\ub294\ub370 \ud55c \uc7a5\uc529 \ucca8\ubd80\ud558\uae30\uac00 \ubc88\uac70\ub86d\ub2e4. \ud3f4\ub354\ub97c \uc555\ucd95\ud558\uc790 ZIP \ud30c\uc77c \ud558\ub098\uac00 \uc0dd\uae34\ub2e4. \uc548\uc5d0\ub294 \ubd84\uba85 \uc5ec\ub7ec \ud30c\uc77c\uc774 \ub4e4\uc5b4 \uc788\ub294\ub370 \uac89\uc5d0\uc11c\ub294 \ud558\ub098\ub85c \ubcf4\uc778\ub2e4. \uc5ec\uae30\uae4c\uc9c0\ub294 \uc775\uc219\ud55c\ub370, \uc65c \uc5b4\ub5a4 \ub54c\ub294 \uc6a9\ub7c9\uc774 \ud06c\uac8c \uc904\uace0 \uc5b4\ub5a4 \ub54c\ub294 \uac70\uc758 \uadf8\ub300\ub85c\uc77c\uae4c. \uc774 \uc9c8\ubb38\uc744 \ud480\ub824\uba74 \ub450 \uac00\uc9c0 \uc77c\uc744 \ub098\ub204\uc5b4\uc57c \ud55c\ub2e4. \uc5ec\ub7ec \ud30c\uc77c\uc744 \ud55c\ub370 \ub2f4\ub294 \uac83\uacfc \uac01 \ud30c\uc77c\uc758 \ub370\uc774\ud130\ub97c \ub354 \uc9e7\uac8c \ud45c\ud604\ud558\ub294 \uac83\uc774\ub2e4. \ubcf4\ud1b5 \uc555\ucd95\uc774\ub77c\ub294 \ub9d0 \ud55c\ub9c8\ub514\ub85c \ubd80\ub974\uc9c0\ub9cc \uac19\uc740 \uc791\uc5c5\uc740 \uc544\ub2c8\ub2e4. ZIP\uc740 \uc774 \ub458\uc744 \ud568\uaed8 \uc0dd\uac01\ud558\uae30 \uc88b\uc740 \ud30c\uc77c \ud615\uc2dd\uc774\ub2e4. ZIP\uc5d0\ub294 \ud30c\uc77c\uc758 \ub370\uc774\ud130\uc640 \ud568\uaed8 \uc774\ub984 \ub4f1 \ud30c\uc77c\uc744 \uad6c\ubcc4\ud560 \uc815\ubcf4\uac00 \ub4e4\uc5b4\uac04\ub2e4. \uc5ec\ub7ec \ubb38\uc11c\ub97c \ud55c \ubd09\ud22c\uc5d0 \ub123\uc5c8\ub354\ub77c\ub3c4 \ub2e4\uc2dc \uaebc\ub0bc \ub54c \uc5b4\ub290 \ubb38\uc11c\uac00 \ubb34\uc5c7\uc778\uc9c0 \uc54c\uc544\uc57c \ud55c\ub2e4. \ud3f4\ub354\uc758 \uad6c\uc870\ub97c \ub2f4\uc73c\uba74 \ud30c\uc77c \uc0ac\uc774\uc758 \uc704\uce58 \uad00\uacc4\ub3c4 \uc774\uc5b4 \uac08 \uc218 \uc788\ub2e4. \ub530\ub77c\uc11c ZIP\uc740 \ub2e8\uc21c\ud788 \uc6d0\ub798 \ud30c\uc77c\ub4e4\uc744 \ud2c8 \uc5c6\uc774 \ubd99\uc5ec \ub193\uc740 \ub369\uc5b4\ub9ac\uac00 \uc544\ub2c8\ub2e4. \ud504\ub85c\uadf8\ub7a8\uc774 \ub0b4\uc6a9\uc744 \ucc3e\uace0 \ud480 \uc218 \uc788\ub3c4\ub85d \uc815\ud574\uc9c4 \uad6c\uc870\ub97c \uac00\uc9c4\ub2e4. libarchive\uc758 \ud615\uc2dd \uc124\uba85\uc740 ZIP\uc758 \uc911\uc559 \ub514\ub809\ud130\ub9ac\ub3c4 \ub2e4\ub8ec\ub2e4. \uc804\uccb4 \ub0b4\uc6a9\uc758 \ubaa9\ub85d\uc744 \ucc3e\uc544 \uc77d\ub294 \ubc29\uc2dd\uc774 \uc788\ub2e4\ub294 \uc815\ub3c4\ub85c \uc774\ud574\ud558\uba74 \ub41c\ub2e4. ZIP \uc548\uc758 \uac01 \ud56d\ubaa9\uc740 \uc555\ucd95\ud558\uc9c0 \uc54a\uc740 \uc0c1\ud0dc\ub85c \uc800\uc7a5\ub420 \uc218\ub3c4 \uc788\ub2e4. \uc5ec\ub7ec \ud30c\uc77c\uc744 \ud558\ub098\ub85c \uc804\ub2ec\ud558\ub294 \ud3b8\ub9ac\ud568\uc740 \ud06c\uae30\ub97c \uc904\uc774\ub294 \uc791\uc5c5 \uc5c6\uc774\ub3c4 \uc5bb\uc744 \uc218 \uc788\ub2e4. \ub367\ubd99\uc5ec\uc57c \ud560 \uad00\ub9ac \uc815\ubcf4 \ub54c\ubb38\uc5d0 \uc6d0\ub798 \ud30c\uc77c\ub4e4\uc758 \ud569\ubcf4\ub2e4 \uc870\uae08 \ucee4\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \uc774 \uc0ac\uc2e4\uc744 \uc54c\uba74 ZIP \ud30c\uc77c\uc774 \uc608\uc0c1\ub9cc\ud07c \uc791\uc544\uc9c0\uc9c0 \uc54a\uc558\ub2e4\uace0 \uace7\ubc14\ub85c \uc2e4\ud328\ub77c\uace0 \uc0dd\uac01\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4. \ud558\ub098\uc758 \uafb8\ub7ec\ubbf8\ub97c \ub9cc\ub4dc\ub294 \ubaa9\uc801\uacfc \uc800\uc7a5 \uacf5\uac04\uc744 \uc904\uc774\ub294 \ubaa9\uc801\uc774 \ub530\ub85c \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ud558\ub098\ub97c \uc798\ud588\ub2e4\uace0 \ub2e4\ub978 \ud558\ub098\uae4c\uc9c0 \uc5b8\uc81c\ub098 \uc774\ub8e8\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc555\ucd95\uc758 \uc6d0\ub9ac\ub97c \uc774\ud574\ud558\ub824\uba74 \ubc18\ubcf5\ub418\ub294 \ubb38\uc7a5\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uac19\uc740 \uad6c\uc808\uc774 \uc5ec\ub7ec \ubc88 \ub098\uc624\uba74 \ub9e4\ubc88 \uc804\ubd80 \uc801\ub294 \ub300\uc2e0 \uc55e\uc758 \uc5b4\ub290 \ubd80\ubd84\uc744 \ub2e4\uc2dc \uc77d\uc73c\ub77c\ub294 \uc9e7\uc740 \uc57d\uc18d\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \uc774\ud574\ub97c \uc704\ud55c \ube44\uc720\uc774\uba70 \uc2e4\uc81c ZIP\uc774 \ubb38\uc7a5\uc758 \ub73b\uc744 \uc694\uc57d\ud55c\ub2e4\ub294 \ub9d0\uc740 \uc544\ub2c8\ub2e4. ZIP\uc5d0\uc11c \ub110\ub9ac \uc4f0\uc774\ub294 DEFLATE \ubc29\uc2dd\uc740 \uc774\ub7f0 \ubc18\ubcf5\uc744 \ud65c\uc6a9\ud55c\ub2e4. \uc55e\uc11c \ub098\uc628 \ubc14\uc774\ud2b8 \ubc30\uc5f4\uacfc \uac19\uc740 \ubd80\ubd84\uc744 \ucc3e\uc73c\uba74 \uae38\uc774\uc640 \ub4a4\ub85c \ub3cc\uc544\uac08 \uac70\ub9ac\ub97c \uae30\ub85d\ud558\ub294 \uc2dd\uc774\ub2e4. \ucef4\ud4e8\ud130\ub294 \ubb38\uc7a5\uc758 \uac10\ub3d9\uc774\ub098 \uc911\uc694\ub3c4\ub97c \ud310\ub2e8\ud574 \ub35c\uc5b4 \ub0b4\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ub418\ub3cc\ub9b4 \uc218 \uc788\ub294 \uaddc\uce59\uc73c\ub85c \ub370\uc774\ud130\ub97c \ud45c\ud604\ud55c\ub2e4. DEFLATE\uc5d0\ub294 \ud5c8\ud504\uba3c \ubd80\ud638\ud654\ub3c4 \uc0ac\uc6a9\ub41c\ub2e4. \ub370\uc774\ud130 \uac12\uc744 \ud45c\ud604\ud558\ub294 \uae30\ud638\uc758 \uae38\uc774\ub97c \uc870\uc815\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc774 \uc774\ub984\uc744 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4, \ubc18\ubcf5\ub418\ub294 \ubd80\ubd84\uc744 \uac00\ub9ac\ud0a4\ub294 \uc77c\uacfc \uac1c\ubcc4 \uac12\uc744 \ud6a8\uc728\uc801\uc73c\ub85c \uc801\ub294 \uc77c\uc774 \ud568\uaed8 \uc555\ucd95\uc5d0 \uc4f0\uc778\ub2e4\ub294 \uc810\uc740 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc2e4\uc81c \ud615\uc2dd\uc5d0\ub294 \uc774\ub97c \ub2e4\uc2dc \ud480 \ub54c \ud544\uc694\ud55c \uc57d\uc18d\ub3c4 \ub4e4\uc5b4\uac04\ub2e4. \uc904\uc5ec \uc801\uc740 \ubb38\uc11c\uc640 \uadf8 \ubb38\uc11c\ub97c \uc77d\ub294 \uaddc\uce59\uc774 \ud568\uaed8 \uc788\uc5b4\uc57c \ud558\ub294 \uc148\uc774\ub2e4. \uadf8\ub798\uc11c \ub0b4\uc6a9\uc5d0 \ub530\ub77c \uc904\uc5b4\ub4dc\ub294 \uc815\ub3c4\uac00 \ub2e4\ub974\uace0, \uc555\ucd95 \uc790\uccb4\uc5d0 \ud544\uc694\ud55c \uc815\ubcf4\ub3c4 \uacf5\uac04\uc744 \uc0ac\uc6a9\ud55c\ub2e4. \ubb34\uc870\uac74 \uac19\uc740 \ube44\uc728\ub85c \uc791\uc544\uc9c0\ub294 \ub9c8\ubc95\uc740 \uc544\ub2c8\ub2e4. \uc774 \ubc29\uc2dd\uc740 \uc555\ucd95\uc744 \ud480\uc5c8\uc744 \ub54c \uc6d0\ub798\uc758 \ubc14\uc774\ud2b8\ub97c \ub418\ucc3e\ub294 \ubb34\uc190\uc2e4 \uc555\ucd95\uc774\ub2e4. \uc0ac\uc9c4\uc758 \uc138\ubd80\ub098 \ubb38\uc11c\uc758 \ub2e8\uc5b4\ub97c \uc77c\ubd80 \ubc84\ub824\uc11c \ud06c\uae30\ub97c \uc904\uc774\ub294 \uc694\uc57d\uacfc \ub2e4\ub974\ub2e4. \ud3b8\uc9c0 \uc5f4 \uc7a5\uc744 \ubcf4\ub0b4\uba70 \ub2e4\uc12f \uc7a5\uc758 \ub0b4\uc6a9\ub9cc \ub0a8\uae30\ub294 \ubc29\uc2dd\uc774 \uc544\ub2cc \uac83\uc774\ub2e4. \ubb3c\ub860 ZIP\uc744 \ub9cc\ub4e4\uae30 \uc804\uc5d0 \uc0ac\uc9c4\uc774 \uc774\ubbf8 \uc190\uc2e4 \uc555\ucd95\ub418\uc5b4 \uc788\uc5c8\ub2e4\uba74 \uadf8 \uc774\uc804\uc758 \uc138\ubd80\uae4c\uc9c0 \ubcf5\uc6d0\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubcf4\uc874\ud558\ub294 \ub300\uc0c1\uc740 ZIP\uc5d0 \ub123\uc740 \ud30c\uc77c\uc758 \ub370\uc774\ud130\ub2e4. \uc5b4\ub290 \ub2e8\uacc4\uc758 \uc6d0\ubcf8\uc744 \ub9d0\ud558\ub294\uc9c0 \uad6c\ubd84\ud558\uba74 \ubb34\uc190\uc2e4\uc774\ub77c\ub294 \ub9d0\uc744 \uacfc\uc7a5\ud558\uc9c0 \uc54a\uace0 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. JPEG \uc0ac\uc9c4\uc774\ub098 \uc774\ubbf8 \uc555\ucd95\ub41c \ub3d9\uc601\uc0c1\uc740 \uc55e\uc120 \uc800\uc7a5 \uacfc\uc815\uc5d0\uc11c \ubc18\ubcf5\uacfc \ud328\ud134\uc744 \uc904\uc5ec \ub193\uc558\uc744 \uc218 \uc788\ub2e4. \uac19\uc740 \ub370\uc774\ud130\ub97c \ub2e4\uc2dc \ub2e4\ub978 \uc555\ucd95\uae30\uc5d0 \ub123\uc5b4\ub3c4 \ub354 \uc904\uc77c \uc5ec\uc9c0\uac00 \uc801\uc744 \uc218 \uc788\ub2e4. \ubc18\uba74 \ubc18\ubcf5\uc774 \ub9ce\uc740 \ub2e8\uc21c\ud55c \uc790\ub8cc\ub294 \ud070 \ucc28\uc774\ub97c \ubcf4\uc77c \uc218 \uc788\ub2e4. RFC 1951\uc740 \uc5b4\ub5a4 \ubb34\uc190\uc2e4 \uc555\ucd95\ubc95\ub3c4 \uac00\ub2a5\ud55c \ubaa8\ub4e0 \uc785\ub825\uc744 \ubc18\ub4dc\uc2dc \ub354 \uc791\uac8c \ub9cc\ub4e4 \uc218\ub294 \uc5c6\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubaa8\ub4e0 \ud30c\uc77c\uc774 \ubc18\uc73c\ub85c \uc904\uc5b4\ub4e0\ub2e4\ub294 \uae30\ub300 \uc790\uccb4\uac00 \ub9de\uc9c0 \uc54a\ub294 \uac83\uc774\ub2e4. ZIP\uc5d0 \ub2f4\uc558\ub294\ub370 \ud06c\uae30\uac00 \ube44\uc2b7\ud558\ub2e4\uba74 \uc548\uc5d0 \ub123\uc740 \uc790\ub8cc\uc758 \uc131\uaca9\ub3c4 \ud568\uaed8 \ubcfc \ud544\uc694\uac00 \uc788\ub2e4. ZIP \ud615\uc2dd\uc5d0\ub294 \uc554\ud638\ud654 \uae30\ub2a5\uc744 \uc4f0\ub294 \uacbd\uc6b0\ub3c4 \uc788\uc9c0\ub9cc, ZIP\uc774\ub77c\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \ub0b4\uc6a9\uc744 \ubcf4\ud638\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5ec\ub7ec \ud30c\uc77c\uc744 \ubb36\uac70\ub098 \uc555\ucd95\ud588\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc554\ud638\ub85c \uc811\uadfc\uc744 \uc81c\ud55c\ud588\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub974\ub2e4. \uc9c0\ud37c\uac00 \ub2ec\ub9b0 \uc8fc\uba38\ub2c8\uac00 \uace7 \uae08\uace0\uac00 \ub418\uc9c0\ub294 \uc54a\ub294 \uac83\uacfc \ube44\uc2b7\ud558\ub2e4. \ub610 ZIP\uc740 \uc5b8\uc81c\ub098 DEFLATE \ud55c \uc885\ub958\ub9cc \uc0ac\uc6a9\ud558\ub294 \ud615\uc2dd\ub3c4 \uc544\ub2c8\ub2e4. \uad6c\ud604\uacfc \uc120\ud0dd\uc5d0 \ub530\ub77c \ub2e4\ub978 \uc555\ucd95 \ubc29\uc2dd\uc774\ub098 \uc555\ucd95\ud558\uc9c0 \uc54a\ub294 \uc800\uc7a5\uc774 \uac00\ub2a5\ud558\ub2e4. \uc774\ubc88 \uae00\uc5d0\uc11c\ub294 \uac00\uc7a5 \uc775\uc219\ud55c \uc6d0\ub9ac\ub97c \uc124\uba85\ud588\uc73c\uba70 \ubaa8\ub4e0 \ud504\ub85c\uadf8\ub7a8\uc758 \uae30\ub2a5\uc774 \uac19\ub2e4\uace0 \uc548\ub0b4\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub2f4\ub294 \ud615\uc2dd\uacfc \uc548\ucabd\uc758 \ucc98\ub9ac \ubc29\ubc95\uc744 \uad6c\ubcc4\ud558\uba74 \ub41c\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \ubb38\uc11c\ub97c \ubaa8\uc73c\ub294 \uc0ac\ub78c\uacfc \uc9c0\ud37c \ud30c\uc6b0\uce58\uc758 \ube44\uc720\ub2e4. \uc2e4\uc81c \uc555\ucd95 \uc804\ud6c4\uc758 \ud06c\uae30\ub97c \ube44\uad50\ud55c \uc2e4\ud5d8 \uadf8\ub9bc\uc740 \uc544\ub2c8\ub2e4. \ubd09\ud22c\ub77c\ub294 \uc774\ubbf8\uc9c0\ub294 \uc5ec\ub7ec \ud30c\uc77c\uc744 \ud568\uaed8 \uc804\ub2ec\ud55c\ub2e4\ub294 \ub73b\uc744 \ub5a0\uc62c\ub9ac\ub294 \ub370\ub9cc \uc0ac\uc6a9\ud558\uba74 \ub41c\ub2e4. \ub2e4\uc74c\uc5d0 ZIP \ud30c\uc77c\uc744 \ub9cc\ub4e4 \ub54c\ub294 \ub450 \uc9c8\ubb38\uc744 \ub098\ub204\uc5b4 \ubcf4\uc790. \ud30c\uc77c\ub4e4\uc774 \ud3b8\ud558\uac8c \ud55c\ub370 \ubaa8\uc600\ub294\uac00, \uadf8\ub9ac\uace0 \ub370\uc774\ud130\ub294 \uc5bc\ub9c8\ub098 \uc904\uc5c8\ub294\uac00. \ub458\uc758 \ub2f5\uc774 \ub2ec\ub77c\ub3c4 \uc774\uc0c1\ud55c \uc77c\uc740 \uc544\ub2c8\ub2e4. \uc775\uc219\ud55c \uc555\ucd95 \ubc84\ud2bc \ub4a4\uc5d0\ub294 \ub0b4\uc6a9\uc744 \uc798 \ubcf4\uad00\ud558\ub294 \uc77c\uacfc \uac19\uc740 \ub0b4\uc6a9\uc744 \ub354 \ud6a8\uc728\uc801\uc73c\ub85c \uc801\ub294 \uc77c\uc774 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4."}, {"id": "athens-owl-silver-coin", "title": "\uc544\ud14c\ub124 \u2014 \ubd80\uc5c9\uc774\ub294 \uc5b4\ub5bb\uac8c \ub3c8 \uc704\uc5d0 \uc549\uc558\uc744\uae4c", "summary": "\uae30\uc6d0\uc804 5\uc138\uae30 \uc544\ud14c\ub124 \uc740\ud654\uc758 \uc2e4\uc81c \uc0ac\uc9c4\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc8fc\uc870\ub41c \ub3c8\uacfc \ub3c4\uc2dc\uc758 \uc0c1\uc9d5\uc774 \ub9cc\ub098\ub294 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "finance", "category_title": "\ub3c8\uacfc \uae08\uc735", "subcategory": "\ub3c8\uacfc \ud654\ud3d0", "categories": ["finance"], "url": "stories/athens-owl-silver-coin/index.html", "image": "../media/athens-owl-silver-coin.jpg", "alt": "\uae30\uc6d0\uc804 5\uc138\uae30 \uc544\ud14c\ub124 \uc740\ud654 \uc591\uba74. \uc67c\ucabd\uc758 \ud22c\uad6c \uc4f4 \uc544\ud14c\ub098\uc640 \uc624\ub978\ucabd\uc758 \ubd80\uc5c9\uc774.", "text": "\uc544\ud14c\ub124 \u2014 \ubd80\uc5c9\uc774\ub294 \uc5b4\ub5bb\uac8c \ub3c8 \uc704\uc5d0 \uc549\uc558\uc744\uae4c \uc740\ud654 \ud55c \ub2e2\uc5d0\uc11c \ub9cc\ub098\ub294 \uc2dc\uc7a5\uacfc \ub3c4\uc2dc\uc758 \uc5bc\uad74 \uae30\uc6d0\uc804 5\uc138\uae30 \uc544\ud14c\ub124 \uc740\ud654\uc758 \uc2e4\uc81c \uc0ac\uc9c4\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc8fc\uc870\ub41c \ub3c8\uacfc \ub3c4\uc2dc\uc758 \uc0c1\uc9d5\uc774 \ub9cc\ub098\ub294 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ub3c8\uacfc \ud654\ud3d0 \ub3c8\uacfc \uae08\uc735 \uc740\ud654 \ud55c \ub2e2\uc5d0 \ubd80\uc5c9\uc774\uac00 \uc11c \uc788\ub2e4. \ud070 \ub208\uc740 \uc815\uba74\uc744 \ubcf4\ub294 \ub4ef\ud558\uace0 \ubab8\uc740 \uc606\uc73c\ub85c \ub193\uc600\ub2e4. \ubc18\ub300\ucabd\uc5d0\ub294 \ud22c\uad6c\ub97c \uc4f4 \uc5ec\uc2e0\uc758 \uc5bc\uad74\uc774 \uc788\ub2e4. \uc624\ub298\uc758 \ub3d9\uc804\uc5d0 \uad6d\uc801\uc744 \uc54c\ub824 \uc8fc\ub294 \ubb38\uc591\uc774 \uc788\ub4ef, \uc774 \uc791\uc740 \uc740 \uc870\uac01\uc5d0\ub3c4 \uc5b4\ub290 \ub3c4\uc2dc\uc758 \uc138\uacc4\uc778\uc9c0 \uc54c\uc544\ubcfc \uc218 \uc788\ub294 \ud45c\uc9c0\uac00 \uc0c8\uaca8\uc84c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \uae30\uc6d0\uc804 5\uc138\uae30 \uc544\ud14c\ub124 \uc740\ud654\uc758 \uc2e4\uc81c \uc0ac\uc9c4\uc774\ub2e4. \uc544\ud14c\ub098\uc640 \uadf8 \uc5ec\uc2e0\uc758 \uc0c1\uc9d5\uc778 \ubd80\uc5c9\uc774\uac00 \uc591\uba74\uc5d0 \ub4f1\uc7a5\ud55c\ub2e4. \uba4b\uc9c4 \uc870\uac01\uc744 \uac10\uc0c1\ud558\ub294 \ub370\uc11c \uc2dc\uc791\ud574, \uc65c \uc0ac\ub78c\ub4e4\uc740 \uadc0\ud55c \uae08\uc18d\uc5d0 \ubc18\ubcf5\ub418\ub294 \uadf8\ub9bc\uc744 \ucc0d\uc5b4 \ub3c8\uc73c\ub85c \uc0ac\uc6a9\ud588\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uace0\ub300\uc758 \uac70\ub798\uc5d0\uc11c\ub294 \uadc0\uae08\uc18d\uc758 \ubb34\uac8c\uc640 \uac00\uce58\ub97c \ud655\uc778\ud558\ub294 \uc77c\uc774 \uc911\uc694\ud588\ub2e4. \uc8fc\uc870\ub41c \ub3c8\uc740 \uc77c\uc815\ud55c \uae08\uc18d \uc870\uac01\uc5d0 \uc54c\uc544\ubcfc \uc218 \uc788\ub294 \ud45c\uc9c0\ub97c \ub0a8\uae30\ub294 \ubc29\ubc95\uc774\uc5c8\ub2e4. \uad50\uc7ac\ub294 \uadf8\ub9ac\uc2a4 \ub3c4\uc2dc\ub4e4\uc774 \uc18c\uc544\uc2dc\uc544 \uc11c\ubd80 \ub9ac\ub514\uc544\uc758 \uc8fc\uc870 \uad00\ud589\uc744 \ubc1b\uc544\ub4e4\uc778 \ud750\ub984 \uc18d\uc5d0\uc11c \uc544\ud14c\ub124\uc758 \uc740\ud654\ub97c \uc124\uba85\ud55c\ub2e4. \ub2e4\ub9cc \ub3c8\uc774 \uc5c6\ub358 \uc138\uacc4\uac00 \uc5b4\ub290 \ub0a0 \ub3d9\uc804 \ud558\ub098\ub85c \uc644\uc804\ud788 \ubc14\ub00c\uc5c8\ub2e4\uace0 \uc0c1\uc0c1\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ubb3c\uac74\uc758 \uad50\ud658\uacfc \uc5ec\ub7ec \uc9c0\uae09 \ubc29\uc2dd\uc740 \ud568\uaed8 \uc874\uc7ac\ud560 \uc218 \uc788\uc5c8\ub2e4. \ub3d9\uc804\uc740 \uadf8 \uac00\uc6b4\ub370 \ubc18\ubcf5\ub418\ub294 \uac70\ub798\uc5d0\uc11c \uae08\uc18d\uc758 \uac00\uce58\uc640 \ud45c\uc9c0\ub97c \uc5f0\uacb0\ud558\ub294 \uc0c8\ub85c\uc6b4 \ub3c4\uad6c\ub85c \uc790\ub9ac \uc7a1\uc558\ub2e4. \uc740\ud654\uc758 \ud55c\ucabd\uc5d0 \uc788\ub294 \uc544\ud14c\ub098\ub294 \uc544\ud14c\ub124\uc640 \ud2b9\ubcc4\ud55c \uad00\uacc4\ub97c \uac00\uc9c4 \uc5ec\uc2e0\uc774\uc5c8\ub2e4. \ub192\uc740 \uc5b8\ub355\uc758 \uc2e0\uc804\uc5d0\uc11c \ub9cc\ub098\ub358 \ub3c4\uc2dc\uc758 \uc0c1\uc9d5\uc774 \uc791\uc740 \ubb3c\uac74 \uc704\uc5d0\ub3c4 \ub193\uc778 \uac83\uc774\ub2e4. \uc0ac\ub78c\uc740 \ub3c8\uc744 \uc8fc\uace0\ubc1b\uc73c\uba70 \uc2e0\uc804\uae4c\uc9c0 \uac00\uc9c0 \uc54a\uace0\ub3c4 \uc5ec\uc2e0\uc758 \ubaa8\uc2b5\uc744 \uc190\uc5d0 \uc958 \uc218 \uc788\uc5c8\ub2e4. \uc624\ub298\ub0a0 \uc6b0\ub9ac\ub294 \uc9c0\ud3d0\uc640 \ub3d9\uc804\uc758 \ucd08\uc0c1\uc744 \ub108\ubb34 \uc790\uc8fc \ubcf4\uc544 \uac70\uc758 \uc758\uc2dd\ud558\uc9c0 \uc54a\uae30\ub3c4 \ud55c\ub2e4. \uadf8\ub7ec\ub098 \ub204\uad6c\uc758 \uc5bc\uad74\uacfc \uc5b4\ub5a4 \uc0c1\uc9d5\uc744 \ub123\uc744\uc9c0\ub294 \uc120\ud0dd\uc758 \uacb0\uacfc\ub2e4. \uace0\ub300 \uc544\ud14c\ub124\uc758 \ub3c8\ub3c4 \uc21c\uc218\ud55c \uad50\ud658 \ub3c4\uad6c\uc778 \ub3d9\uc2dc\uc5d0 \ub3c4\uc2dc\uac00 \uc790\uae30 \ubaa8\uc2b5\uc744 \ub4dc\ub7ec\ub0b4\ub294 \uc791\uc740 \ud654\uba74\uc774\uc5c8\ub2e4. \uad50\uc7ac\ub294 \ubd80\uc5c9\uc774\ub97c \uc544\ud14c\ub098\uc640 \uc5f0\uacb0\ub418\ub294 \uc9c0\ud61c\uc758 \uc0c1\uc9d5\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \uc5ec\uc2e0\uc758 \uc5bc\uad74\uacfc \ubd80\uc5c9\uc774\ub294 \uc11c\ub85c \ub5a8\uc5b4\uc9c4 \ub450 \uadf8\ub9bc\uc774 \uc544\ub2c8\ub77c \uac19\uc740 \ub3c4\uc2dc\uc758 \uc2e0\uc559\uacfc \uc815\uccb4\uc131\uc744 \uc787\ub294 \ud45c\ud604\uc774\uc5c8\ub2e4. \uae00\uc744 \uae38\uac8c \uc77d\uc9c0 \uc54a\uc544\ub3c4 \ubb38\uc591\uc744 \uc54c\uc544\ubcf4\ub294 \uae38\uc774 \uc788\uc5c8\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c\ub294 \ubd80\uc5c9\uc774\uc758 \ud070 \ub208\uacfc \ub0a0\uac1c, \ubab8\uc758 \uc724\uacfd\uc744 \ucc9c\ucc9c\ud788 \uc0b4\ud3b4\ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc791\uc740 \uae08\uc18d \uba74 \uc548\uc5d0\uc11c \ud2b9\uc9d5\uc744 \uc54c\uc544\ubcf4\uac8c \ub9cc\ub4dc\ub294 \ud45c\ud604\uc774 \ud544\uc694\ud588\ub2e4. \uc774 \uadf8\ub9bc\ub9cc\uc73c\ub85c \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc774 \ubaa8\ub450 \uac19\uc740 \uc2e0\uc559\uc2ec\uc744 \ud488\uc5c8\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\uc9c0\ub9cc, \uc5b4\ub5a4 \uc0c1\uc9d5\uc774 \uacf5\uc801\uc778 \ubb3c\uac74 \uc704\uc5d0 \uc120\ud0dd\ub418\uc5c8\ub294\uc9c0\ub294 \ubcfc \uc218 \uc788\ub2e4. \uadf8\ub9ac\uc2a4 \ub3c4\uc2dc\uc758 \uc544\uace0\ub77c\ub294 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc774\ub294 \uc790\ub9ac\uc774\uba74\uc11c \ubb3c\uac74\uc744 \uc0ac\uace0\ud30c\ub294 \uc7a5\uc18c\uc600\ub2e4. \uad50\uc7ac\ub294 \uc8fc\ud654\uc758 \uc0ac\uc6a9\uc774 \uac70\ub798\ub97c \ud3b8\ub9ac\ud558\uac8c \ud558\ub294 \ud750\ub984\uacfc \uc2dc\uc7a5\uc758 \uc131\uc7a5\uc744 \ud568\uaed8 \uc124\uba85\ud55c\ub2e4. \ub18d\ubd80\uc640 \uc7a5\uc778, \uc0c1\uc778\uc740 \uc790\uc2e0\uc774 \ub9cc\ub4e0 \uac83\uc744 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ub118\uae30\uace0 \ud544\uc694\ud55c \uac83\uc744 \uad6c\ud588\ub2e4. \uac01\uc790\uac00 \uac00\uc9c4 \ubb3c\uac74\uc774 \uc0c1\ub300\uc758 \ud544\uc694\uc640 \uc815\ud655\ud788 \ub9de\uc544\uc57c\ub9cc \ud558\ub294 \uac70\ub798\ubcf4\ub2e4 \uad50\ud658\uc758 \uc911\uac04 \uc218\ub2e8\uc744 \uc4f0\ub294 \uac70\ub798\uac00 \ud3b8\ub9ac\ud560 \ub54c\uac00 \uc788\ub2e4. \ud558\uc9c0\ub9cc \ub3d9\uc804\uc774 \uc0dd\uacbc\ub2e4\uace0 \uac00\uaca9\uc744 \ub458\ub7ec\uc2fc \ud765\uc815\uacfc \uc9c8\uc758 \ud655\uc778\uc774 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0c8\ub85c\uc6b4 \ub3c4\uad6c\ub294 \uac70\ub798\uc758 \uc77c\ubd80\ub97c \ubc14\uafb8\uba74\uc11c \uae30\uc874\uc758 \ud310\ub2e8\uacfc \ud568\uaed8 \uc6c0\uc9c1\uc600\ub2e4. \uc775\uc219\ud55c \ub3c4\uc548\uc740 \ubb34\uc5c7\uc744 \ubc1b\uc558\ub294\uc9c0 \ud310\ub2e8\ud558\ub294 \ub2e8\uc11c\uac00 \ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc0c8\uaca8\uc9c4 \uadf8\ub9bc\ub9cc\uc73c\ub85c \uae08\uc18d\uc758 \uc591\uacfc \uc0c1\ud0dc\uc5d0 \uad00\ud55c \ubaa8\ub4e0 \ubb38\uc81c\uac00 \ud574\uacb0\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub3c8\uc758 \ud45c\uc9c0\uc640 \uadf8\uac83\uc744 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5bb\uac8c \ubc1b\uc544\ub4e4\uc600\ub294\uc9c0\ub294 \ud568\uaed8 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc774 \uc740\ud654\uc758 \uc758\ubbf8\ub3c4 \ubd80\uc5c9\uc774\uac00 \uc608\ubed0\uc11c \ubaa8\ub450\uac00 \ubbff\uc5c8\ub2e4\ub294 \uc2dd\uc73c\ub85c \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub3c4\uc2dc\uc640 \uc2dc\uc7a5, \uadc0\uae08\uc18d\uc758 \uac00\uce58\uc640 \uac70\ub798\uc758 \uad00\ud589\uc774 \ubc30\uacbd\uc5d0 \uc788\uc5c8\ub2e4. \ub3c8\uc740 \ubb3c\uc9c8 \ud55c \uc870\uac01\uc774\uba74\uc11c \uadf8 \uc870\uac01\uc744 \uc5b4\ub5a4 \uad00\uacc4 \uc548\uc5d0\uc11c \uc8fc\uace0\ubc1b\ub294\uc9c0\uc5d0 \uad00\ud55c \uc57d\uc18d\uc774\uae30\ub3c4 \ud588\ub2e4. \uac19\uc740 \uc544\ud14c\ub098\uac00 \ub3d9\uc804\uc5d0\ub3c4 \ub098\ud0c0\ub098\uace0 \ud30c\ub974\ud14c\ub17c \uac19\uc740 \ud070 \uc2e0\uc804\uc758 \uc911\uc2ec\uc5d0\ub3c4 \ub193\uc600\ub2e4. \uaddc\ubaa8\ub294 \ub2e4\ub974\uc9c0\ub9cc \ub3c4\uc2dc\uc758 \uc790\uc6d0\uacfc \uae30\uc220, \uc0c1\uc9d5\uc774 \ub450 \ubb3c\uac74\uc744 \ubaa8\ub450 \ub9cc\ub4e4\uc5c8\ub2e4. \uc544\ud14c\ub124\ub97c \uac74\ucd95\uc73c\ub85c \ubcfc \ub54c\uc640 \ub3c8\uc73c\ub85c \ubcfc \ub54c \uc11c\ub85c \ub2e4\ub978 \ud06c\uae30\uc758 \ud48d\uacbd\uc774 \uc5f4\ub9b0\ub2e4. \ub3c4\uc2dc\uc758 \ubc88\uc601\uc774 \ubaa8\ub450\uc5d0\uac8c \uac19\uc740 \uc0dd\ud65c\uc744 \ub73b\ud588\ub358 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uad50\uc7ac\uac00 \uc124\uba85\ud558\ub4ef \uc544\ud14c\ub124\uc758 \uc815\uce58\uc801 \ucc38\uc5ec\uc5d0\ub294 \uc5ec\uc131\uacfc \ub178\uc608, \uac70\uc8fc \uc678\uad6d\uc778\uc744 \ubc30\uc81c\ud558\ub294 \uacbd\uacc4\uac00 \uc788\uc5c8\ub2e4. \ud6cc\ub96d\ud55c \uc870\uac01\uacfc \uc2dc\uc7a5\uc758 \uc131\uc7a5\uc744 \uac10\uc0c1\ud558\uba74\uc11c\ub3c4 \uadf8 \ubb3c\uac74\uc744 \uc0ac\uc6a9\ud55c \uc0ac\ud68c\uc758 \ucc28\uc774\ub97c \ud568\uaed8 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc0ac\uc9c4\uc740 \ud55c \uc740\ud654\uc758 \uc591\uba74\uc744 \ub098\ub780\ud788 \ubcf4\uc5ec \uc900\ub2e4. \ub450 \ub3c4\uc2dc\uc758 \ub3c8\uc774\ub098 \uc2dc\ub300\uac00 \ub2e4\ub978 \ub450 \ubb3c\uac74\uc744 \ube44\uad50\ud55c \uadf8\ub9bc\uc774 \uc544\ub2c8\ub2e4. \uc544\ud14c\ub098\uc640 \ubd80\uc5c9\uc774\uac00 \uac19\uc740 \ubb3c\uac74\uc758 \uc55e\ub4a4\uc5d0 \ub193\uc600\ub2e4\ub294 \uc810\uc744 \uc54c\uba74 \uc791\uc740 \ub3d9\uc804\uc758 \uad6c\uc131\ub3c4 \ub354 \ub610\ub837\ud558\uac8c \ubcf4\uc778\ub2e4. \ud604\uc7ac \uc0ac\uc9c4\uc774 \uae30\uc6d0\uc804 5\uc138\uae30\uc758 \uc2dc\uc7a5\uc744 \uc9c1\uc811 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc720\ubb3c\uc758 \ud45c\uba74\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uad50\uc7ac\uc758 \uac70\ub798\uc640 \ub3c4\uc2dc \uc124\uba85\uc744 \ud568\uaed8 \uc77d\ub294 \uac83\uc774\ub2e4. \uc740\ud654 \ud55c \ub2e2\uc744 \uc5bc\ub9c8\uc758 \ud604\ub300 \ud654\ud3d0\uc640 \uac19\ub2e4\uace0 \ub2e8\uc21c\ud788 \ud658\uc0b0\ud558\uc9c0 \uc54a\uc544\ub3c4 \uadf8 \uc2dc\ub300 \uc0ac\ub78c\ub4e4\uc758 \uacbd\uc81c\uc640 \uc0c1\uc9d5\uc744 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uc544\ud14c\ub124\uc758 \ubd80\uc5c9\uc774\ub294 \uae08\uc735\uc758 \uc5ed\uc0ac\uac00 \uc22b\uc790\uc640 \uacc4\uc0b0\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\uc558\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uac70\ub798\ub97c \uc704\ud55c \uae08\uc18d\uc5d0 \uc5ec\uc2e0\uacfc \ub3d9\ubb3c\uc744 \uc0c8\uae30\uace0, \uadf8\uac83\uc744 \uc0ac\ub78c\ub4e4\uc774 \uc54c\uc544\ubcf4\ub294 \ubb3c\uac74\uc73c\ub85c \ub9cc\ub4dc\ub294 \uacfc\uc815\uc5d0\ub294 \uae30\uc220\uacfc \uc2e0\uc559, \ub3c4\uc2dc\uc758 \uc815\uccb4\uc131\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \ub2e4\uc74c\uc5d0 \uc624\ub798\ub41c \ub3d9\uc804\uc744 \ub9cc\ub098\uba74 \uac12\uc774 \uc5bc\ub9c8\uc600\ub294\uc9c0\uc640 \ud568\uaed8 \ubb34\uc5c7\uc774 \uadf8\ub824\uc84c\ub294\uc9c0\ub3c4 \ubcf4\uc544 \ub450\uc790. \uc190\ubc14\ub2e5\uc758 \uc791\uc740 \uba74\uc5d0\ub294 \uc5b4\ub290 \uc0ac\ud68c\uac00 \uc790\uc2e0\uc744 \uc5b4\ub5bb\uac8c \ud45c\ud604\ud588\ub294\uc9c0\uac00 \ub0a8\ub294\ub2e4. \ubd80\uc5c9\uc774 \ud55c \ub9c8\ub9ac\ub294 \uc544\ud14c\ub124\uc758 \uc2dc\uc7a5\uacfc \uc2e0\uc804\uc744 \uc774\uc5b4 \uc8fc\ub294 \ub73b\ubc16\uc758 \uc5ed\uc0ac \uc548\ub0b4\uc790\uac00 \ub41c\ub2e4."}, {"id": "bank-england-1694-government-credit", "title": "\uc789\uae00\ub79c\ub4dc\uc740\ud589 1694 \u2014 \uc655\uc758 \uc804\uc7c1 \uc790\uae08\uc5d0\uc11c \uc790\ub77c\ub09c \uc740\ud589", "summary": "\uc804\uc7c1 \uc790\uae08\uc744 \ud544\uc694\ub85c \ud55c \uc815\ubd80\uc640 \ucd9c\uc790\uc790\uc758 \uac70\ub798\uc5d0\uc11c \uc624\ub798\uac00\ub294 \uc740\ud589\uc774 \ud0dc\uc5b4\ub09c \uacfc\uc815\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "finance", "category_title": "\ub3c8\uacfc \uae08\uc735", "subcategory": "\uc740\ud589\uacfc \uc2e0\uc6a9", "categories": ["finance"], "url": "stories/bank-england-1694-government-credit/index.html", "image": "../media/bank-england-1694-government-credit.png", "alt": "17\uc138\uae30 \ub9d0 \ub7f0\ub358\uc758 \uc7a5\ubd80\uc640 \ub3d9\uc804, \uae08\uc735 \ubb38\uc11c\ub97c \uadf8\ub9b0 \uc5ed\uc0ac\uc801 \ubd84\uc704\uae30 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uc789\uae00\ub79c\ub4dc\uc740\ud589 1694 \u2014 \uc655\uc758 \uc804\uc7c1 \uc790\uae08\uc5d0\uc11c \uc790\ub77c\ub09c \uc740\ud589 \uc815\ubd80\uc758 \ucc28\uc785\uacfc \ud22c\uc790\uc790\uc758 \uae30\ub300\uac00 \ubc95\uc778\u00b7\ud2b9\uad8c\uc73c\ub85c \uacb0\ud569\ud55c \uacfc\uc815 \uc804\uc7c1 \uc790\uae08\uc744 \ud544\uc694\ub85c \ud55c \uc815\ubd80\uc640 \ucd9c\uc790\uc790\uc758 \uac70\ub798\uc5d0\uc11c \uc624\ub798\uac00\ub294 \uc740\ud589\uc774 \ud0dc\uc5b4\ub09c \uacfc\uc815\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc740\ud589\uacfc \uc2e0\uc6a9 \ub3c8\uacfc \uae08\uc735 \uc911\uc559\uc740\ud589\uc774\ub77c\uace0 \ud558\uba74 \uae30\uc900\uae08\ub9ac\ub97c \uc815\ud558\uace0 \ud654\ud3d0\uc758 \uc548\uc815\uc744 \ucc45\uc784\uc9c0\ub294 \uae30\uad00\uc744 \ub5a0\uc62c\ub9b0\ub2e4. \uadf8\ub7ec\ub098 \uc624\ub798\ub41c \uc911\uc559\uc740\ud589\uc758 \ucd9c\ubc1c\uc744 \uc0b4\ud3b4\ubcf4\uba74 \ucc98\uc74c\ubd80\ud130 \uc624\ub298\uc758 \uc5ed\ud560\uc744 \uc644\uc131\ud55c \ucc44 \ud0dc\uc5b4\ub09c \uac83\uc740 \uc544\ub2c8\ub2e4. 1694\ub144 \uc138\uc6cc\uc9c4 \uc789\uae00\ub79c\ub4dc\uc740\ud589\uc758 \uc5ed\uc0ac\uc5d0\ub294 \uc804\uc7c1\uacfc \uc815\ubd80\uc758 \uc790\uae08 \ubd80\uc871, \ub3c8\uc744 \ube4c\ub824 \uc8fc\ub294 \uc0ac\ub78c\ub4e4\uc758 \uacc4\uc0b0\uc774 \uc788\uc5c8\ub2e4. \uc774 \uc0ac\ub840\ub294 \ud55c \ub098\ub77c\uc758 \uae30\uad00 \uc18c\uac1c\ub97c \ub118\uc5b4 \uacf5\uacf5\uc758 \ube5a\uacfc \ubbfc\uac04\uc758 \uc2e0\uc6a9\uc774 \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ub418\ub294\uc9c0 \ubcf4\uc5ec \uc900\ub2e4. \uc740\ud589\uc758 \uc774\ub984\uc774 \uc0dd\uae34 \uc21c\uac04\ubcf4\ub2e4 \ub204\uac00 \ub204\uad6c\uc5d0\uac8c \uc5b4\ub5a4 \uc57d\uc18d\uc73c\ub85c \ub3c8\uc744 \uc81c\uacf5\ud588\ub294\uc9c0\ubd80\ud130 \ub530\ub77c\uac00 \ubcf4\uc790. \uc70c\ub9ac\uc5c4 3\uc138\uc758 \uc815\ubd80\ub294 \ud504\ub791\uc2a4\uc640\uc758 \uc804\uc7c1\uc744 \uce58\ub974\uba70 \ub9ce\uc740 \uc790\uae08\uc744 \ud544\uc694\ub85c \ud588\ub2e4. \ud544\uc694\ud55c \ub3c8\uc774 \ud06c\ub2e4\uace0 \ube4c\ub9b4 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc815\uad8c\uc758 \uc548\uc815\uc131\uacfc \uc0c1\ud658\uc5d0 \ub300\ud55c \uae30\ub300\uac00 \uc57d\ud558\uba74 \ub3c8\uc744 \uac00\uc9c4 \uc0ac\ub78c\uc740 \ub9dd\uc124\uc778\ub2e4. \uc655\uacfc \uc815\ubd80\uc758 \uad8c\uc704\uac00 \uace7\ubc14\ub85c \uae08\uc735\uc2dc\uc7a5\uc758 \uc2e0\ub8b0\uac00 \ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubc30\uc800\ud2b8\ub294 \u300e\ub86c\ubc14\ub4dc \uc2a4\ud2b8\ub9ac\ud2b8\u300f\uc5d0\uc11c \uc774 \uc2dc\uae30 \uc815\ubd80\uc758 \uc2e0\uc6a9 \ubb38\uc81c\ub97c \uc124\uba85\ud55c\ub2e4. \uc5ec\uae30\uc5d0\ub294 \ub3c8\uc774 \uc5bc\ub9c8\ub098 \ud544\uc694\ud55c\uac00\ub77c\ub294 \uc9c8\ubb38\uacfc \uadf8 \uc57d\uc18d\uc744 \uc0ac\ub78c\ub4e4\uc774 \uc5bc\ub9c8\ub098 \ubbff\ub294\uac00\ub77c\ub294 \uc9c8\ubb38\uc774 \ud568\uaed8 \uc788\ub2e4. \uc804\uc7c1\uc740 \uad70\ub300\uc640 \ubb34\uae30\ubfd0 \uc544\ub2c8\ub77c \uba3c \ubbf8\ub798\uc758 \uc9c0\ubd88\uc744 \ud604\uc7ac\uc758 \uc790\uae08\uc73c\ub85c \ubc14\uafb8\ub294 \ub2a5\ub825\ub3c4 \uc694\uad6c\ud588\ub2e4. 1694\ub144\uc758 \uacc4\ud68d\uc740 120\ub9cc \ud30c\uc6b4\ub4dc\ub97c \ubaa8\uc544 \uc815\ubd80\uc5d0 \ube4c\ub824 \uc8fc\uace0 \uc5f0 8\ud37c\uc13c\ud2b8\uc758 \uc774\uc790\ub97c \ubc1b\ub294 \uad6c\uc870\uc600\ub2e4. \uadf8 \ub3c8\uc744 \ub0b8 \uc0ac\ub78c\ub4e4\uc740 \uc789\uae00\ub79c\ub4dc\uc740\ud589\uc774\ub77c\ub294 \ubc95\uc778\uc73c\ub85c \uacb0\ud569\ud588\ub2e4. \uc740\ud589\uc758 \ucd9c\ubc1c\uc5d0\ub294 \uc815\ubd80\uac00 \ud544\uc694\ub85c \ud55c \uc790\uae08\uacfc \ud22c\uc790\uc790\uac00 \uae30\ub300\ud55c \uc218\uc775\uc774 \ud568\uaed8 \ub193\uc778\ub2e4. \uc774 \uc22b\uc790\ub97c \uc624\ub298\uc758 \uae08\uc735\uc0c1\ud488\uacfc \ub2e8\uc21c \ube44\uad50\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2f9\uc2dc\uc758 \uc870\uac74\uc5d0\uc11c \ub3c8\uc744 \ub0b4\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5a4 \ubcf4\uc0c1\uc744 \uc694\uad6c\ud588\ub294\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \ud070\ub3c8\uc744 \ubaa8\uc73c\ub824\uba74 \uac1c\uc778 \uba87 \uc0ac\ub78c\uc758 \ud638\uc758\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud588\ub2e4. \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc790\uae08\uc744 \ubc95\uc801 \uc870\uc9c1\uacfc \uc57d\uc18d\uc73c\ub85c \ubb36\ub294 \ubc29\uc2dd\uc774 \uc120\ud0dd\ub418\uc5c8\ub2e4. \ud55c \uc0ac\ub78c\uc5d0\uac8c \ub3c8\uc744 \ube4c\ub824 \uc900 \ub4a4 \uadf8\uac00 \uac1a\uae30\ub97c \uae30\ub2e4\ub9ac\ub294 \uac70\ub798\uc640, \ub9ce\uc740 \ud22c\uc790\uc790\uac00 \ud558\ub098\uc758 \uc870\uc9c1\uc744 \ud1b5\ud574 \uc815\ubd80\uc5d0 \uc790\uae08\uc744 \uc81c\uacf5\ud558\ub294 \uac70\ub798\ub294 \ub2e4\ub974\ub2e4. \uc870\uc9c1\uc758 \uc9c0\uc18d\uc131\uacfc \uac70\ub798\uc758 \uaddc\uce59\uc774 \uc911\uc694\ud574\uc9c4\ub2e4. \uc740\ud589\uc740 \ub2e8\uc21c\ud788 \ub3c8\uc744 \ud55c \uc7a5\uc18c\uc5d0 \uc313\uc544 \ub450\ub294 \uc0c1\uc790\ubcf4\ub2e4 \ub113\uc740 \uc5ed\ud560\uc744 \uac16\uac8c \ub41c\ub2e4. \uc815\ubd80 \uc5ed\uc2dc \uc774\ub7f0 \uc870\uc9c1\uc758 \uc2e0\uc6a9\uc744 \uc774\uc6a9\ud560 \uc218 \uc788\uc5c8\ub2e4. \uc138\uae08\uc774 \ub4e4\uc5b4\uc624\ub294 \ub54c\uc640 \ub3c8\uc744 \uc368\uc57c \ud558\ub294 \ub54c\uac00 \ub2e4\ub97c \ub54c, \ubbf8\ub798\uc758 \uc218\uc785\uc5d0 \ub300\ud55c \uae30\ub300\ub97c \ud604\uc7ac\uc758 \uc9c0\ucd9c\ub85c \uc5f0\uacb0\ud55c\ub2e4. \uc5ec\uae30\uc11c \uacf5\uacf5\uc758 \uc7ac\uc815\uacfc \uc740\ud589\uc758 \uc0ac\uc5c5\uc774 \ub9de\ubb3c\ub9b0\ub2e4. \uad6d\uac00\uc640 \uc2dc\uc7a5\uc744 \uc644\uc804\ud788 \ub5a8\uc5b4\uc9c4 \ub450 \uc138\uacc4\ub85c\ub9cc \ubcf4\uae30 \uc5b4\ub824\uc6b4 \uc774\uc720\ub2e4. \uc789\uae00\ub79c\ub4dc\uc740\ud589\uc740 \uc815\ubd80\uc640\uc758 \uad00\uacc4 \uc18d\uc5d0\uc11c \uc911\uc694\ud55c \uad8c\ub9ac\ub97c \uc5bb\uace0 \uc131\uc7a5\ud588\ub2e4. \ubc30\uc800\ud2b8\ub294 \uadf8 \ud2b9\uad8c\uacfc \uacbd\uc7c1 \uc870\uac74\uc744 \uc740\ud589\uc758 \uc5ed\uc0ac\uc5d0\uc11c \uac15\uc870\ud55c\ub2e4. \ucc98\uc74c\ubd80\ud130 \uc544\ubb34\ub7f0 \uc81c\ub3c4\uc801 \ucc28\uc774 \uc5c6\uc774 \uac19\uc740 \uc870\uac74\uc758 \ud68c\uc0ac\ub4e4\uc774 \uaca8\ub8e8\uae30\ub9cc \ud55c \uc2dc\uc7a5\uc73c\ub85c \uc0c1\uc0c1\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ud2b9\uad8c\uc774\ub77c\ub294 \ub9d0\ub9cc\uc73c\ub85c \uc131\uacf5\uc758 \uc804\ubd80\ub97c \uc124\uba85\ud560 \uc218\ub3c4 \uc5c6\ub2e4. \uadf8\uac83\uc744 \ubc14\ud0d5\uc73c\ub85c \uc2e4\uc81c \uac70\ub798\uc640 \uc2e0\ub8b0\ub97c \uc720\uc9c0\ud574\uc57c \ud588\ub2e4. \ub2e4\ub9cc \uc5b4\ub290 \uae30\uad00\uc774 \ud2b9\ubcc4\ud55c \uc704\uce58\uc5d0 \uc624\ub974\ub294 \uacfc\uc815\uc744 \uc774\ud574\ud558\ub824\uba74 \uc0c1\ud488\uc774\ub098 \uacbd\uc601\uc790\uc758 \ub2a5\ub825\ubfd0 \uc544\ub2c8\ub77c \ubc95\uacfc \uc815\ubd80\uc758 \uc120\ud0dd\ub3c4 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uae08\uc735\uc758 \uc5ed\uc0ac\ub294 \uc81c\ub3c4\uc758 \uc5ed\uc0ac\uc640 \uac00\uae5d\ub2e4. \ub3c8\uc744 \ube4c\ub824 \uc900 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ub204\uac00 \ud1b5\uce58\ud558\ub294\uc9c0\ub3c4 \uc911\uc694\ud588\ub2e4. \ub2e4\ub978 \uc815\uad8c\uc774 \ub4e4\uc5b4\uc120 \ub4a4 \uc774\uc804\uc758 \ubd80\ucc44\ub97c \uc778\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4\uba74 \uc0c1\ud658\uc758 \uc804\ub9dd\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ubc30\uc800\ud2b8\uc758 \uc124\uba85\uc5d0\uc11c\ub294 \uc774\ucc98\ub7fc \uc815\ubd80\uc758 \ubd80\ucc44\uc640 \uc815\uce58\uc801 \uc774\ud574\uad00\uacc4\uac00 \uc5f0\uacb0\ub41c\ub2e4. \uad6d\ucc44\ub294 \uacbd\uc81c\uc758 \uc22b\uc790\uc774\uba74\uc11c \uc815\uce58\uc801 \uc57d\uc18d\uc774\uae30\ub3c4 \ud588\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \ud22c\uc790\uc790\uc758 \ud589\ub3d9\uc744 \ud558\ub098\uc758 \uc815\uce58\uc801 \uc2e0\ub150\uc73c\ub85c \uc904\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uc790\uae30 \ub3c8\uc744 \ub3cc\ub824\ubc1b\uc744 \uc870\uac74\uc744 \uc9c0\ud0a4\ub824\ub294 \uc774\ud574\uac00 \uc788\uc744 \uc218 \uc788\ub2e4. \uc81c\ub3c4\uc758 \uc9c0\uc18d\uc774 \uae08\uc804\uc801 \uc774\ud574\uc640 \ub9cc\ub098\uba74\uc11c \uc9c0\uc9c0\uc758 \uae30\ubc18\uc774 \uc0dd\uae34\ub2e4. \uad6d\uac00\uc758 \uc2e0\uc6a9\uc740 \ucd94\uc0c1\uc801\uc778 \uba85\uc608\ub9cc\uc73c\ub85c \uc720\uc9c0\ub418\ub294 \uac83\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc815\ubd80\uc5d0 \uc790\uae08\uc744 \uc81c\uacf5\ud558\ub294 \uc77c\uc774 \uacf5\uacf5\uc758 \ubaa9\uc801\uacfc \uc5f0\uacb0\ub41c\ub2e4\uace0 \ud574\uc11c \uc740\ud589\uc774 \ucc98\uc74c\ubd80\ud130 \uc21c\uc218\ud55c \uacf5\uc775 \uc870\uc9c1\uc774\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ucd9c\uc790\uc790\ub294 \uc774\uc775\uc744 \uae30\ub300\ud588\uace0 \uc815\ubd80\ub294 \ud544\uc694\ud55c \ub3c8\uc744 \uc5bb\uc73c\ub824 \ud588\ub2e4. \uc11c\ub85c\uc758 \ubaa9\uc801\uc774 \ub9cc\ub0ac\uc9c0\ub9cc \uc644\uc804\ud788 \ud558\ub098\uac00 \ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774 \ucc28\uc774\ub97c \uc54c\uba74 \uc624\ub298\uc758 \uc911\uc559\uc740\ud589\uc774\ub77c\ub294 \uc774\ub984\uc744 \uacfc\uac70\uc5d0 \uadf8\ub300\ub85c \ud22c\uc601\ud558\ub294 \uc77c\uc744 \ud53c\ud560 \uc218 \uc788\ub2e4. \uc2dc\uac04\uc774 \uc9c0\ub098\uba70 \uc5b4\ub5a4 \uc5ed\ud560\uc774 \ub354\ud574\uc84c\ub294\uc9c0\ub97c \ubcc4\ub3c4\ub85c \ubcf4\uc544\uc57c \ud55c\ub2e4. \ud55c \uae30\uad00\uc758 \uc624\ub79c \uc5ed\uc0ac\ub294 \ucc3d\ub9bd \ub54c\uc758 \ubaa9\uc801\uc774 \ubcc0\ud568\uc5c6\uc774 \uc720\uc9c0\ub41c \uacb0\uacfc\ub9cc\uc774 \uc544\ub2c8\ub77c, \ud658\uacbd\uacfc \uc81c\ub3c4\uac00 \ub2ec\ub77c\uc9c0\uba70 \uc704\uce58\ub97c \ubc14\uafbc \uacfc\uc815\uc774\uae30\ub3c4 \ud558\ub2e4. \uc789\uae00\ub79c\ub4dc\uc740\ud589\uc758 \ucd9c\ubc1c\uc744 \uae30\uc900\uae08\ub9ac\uc758 \uc5ed\uc0ac\ub85c\ub9cc \uc77d\uc73c\uba74 \uc911\uc694\ud55c \uc55e\ubd80\ubd84\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \uc815\ubd80\uc758 \ucc28\uc785\uacfc \ud22c\uc790\uc790\uc758 \uae30\ub300, \ubc95\uc778\uacfc \ud2b9\uad8c, \uc815\uce58\uc758 \uc9c0\uc18d\uc131\uc774\ub77c\ub294 \ubb38\uc81c\ub4e4\uc774 \uba3c\uc800 \uc788\uc5c8\ub2e4. \uc624\ub298\uc758 \uc775\uc219\ud55c \uae30\ub2a5\uc744 \uc774\ud574\ud558\ub824\uba74 \uadf8 \uc774\uc804\uc758 \uac70\ub798\ub97c \ubcf4\ub294 \uc77c\uc774 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc815\ubd80\uc5d0 \ub3c8\uc744 \ube4c\ub824 \uc8fc\ub294 \uacc4\uc57d\uacfc \uc740\ud589\uc5d0 \uc790\uae08\uc744 \ubaa8\uc73c\ub294 \uad00\uacc4\ub3c4 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \uac19\uc740 120\ub9cc \ud30c\uc6b4\ub4dc\uac00 \uc5ec\ub7ec \uc0ac\ub78c\uc744 \uc5f0\uacb0\ud558\uc9c0\ub9cc \uac01\uc790\uc758 \uc9c0\uc704\uac00 \ubaa8\ub450 \uac19\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc790\uae08\uc774 \uc5b4\ub290 \uacbd\ub85c\ub85c \ubaa8\uc5ec \ub204\uad6c\uc5d0\uac8c \uc81c\uacf5\ub418\ub294\uc9c0 \uadf8\ub824 \ubcf4\uba74 \uae30\uad00\uc758 \ucd9c\ubc1c\uc774 \ub354 \uba85\ud655\ud574\uc9c4\ub2e4. \uc774 \uc0ac\ub840\uac00 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \uad6d\uac00\uac00 \ub3c8\uc744 \ud544\uc694\ub85c \ud588\ub2e4\ub294 \ud3c9\ubc94\ud55c \uc0ac\uc2e4 \uc774\uc0c1\uc774\ub2e4. \uadf8 \ud544\uc694\ub97c \ub204\uac00 \uc5b4\ub5a4 \uc870\uac74\uc73c\ub85c \ud574\uacb0\ud588\ub294\uc9c0\uc5d0 \ub530\ub77c \uc624\ub798\uac00\ub294 \uae08\uc735 \uae30\uad00\uc774 \ub9cc\ub4e4\uc5b4\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \uc740\ud589\uc758 \ud0c4\uc0dd\uc744 \ub530\ub77c\uac00\uba74 \uc2e0\uc6a9\uc740 \ubbff\uc74c\uc774\ub77c\ub294 \uac10\uc815\uc778 \ub3d9\uc2dc\uc5d0 \ubc95\uacfc \uc774\uc775, \uc9c0\uc18d \uac00\ub2a5\ud55c \uc57d\uc18d\uc758 \uad6c\uc870\ub77c\ub294 \uc810\uc774 \ub4dc\ub7ec\ub09c\ub2e4."}, {"id": "bank-run-lombard-street", "title": "\uc740\ud589 \uc55e\uc5d0 \uc904\uc774 \uae38\uc5b4\uc9c0\uba74 \u2014 \ub3c8\uacfc \ubbff\uc74c\uc758 \uc2dc\uac04\ucc28", "summary": "19\uc138\uae30 \ub7f0\ub358 \uae08\uc735\uc2dc\uc7a5\uc758 \uae30\ub85d\uc5d0\uc11c \ub2f9\uc7a5 \uc9c0\uae09\ud560 \ub3c8\uacfc \uc790\uc0b0 \uac00\uce58\uc758 \ucc28\uc774, \uc704\uae30 \ub54c\uc758 \ub300\ucd9c \uc6d0\uce59\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "finance", "category_title": "\ub3c8\uacfc \uae08\uc735", "subcategory": "\uc740\ud589\uacfc \uc2e0\uc6a9", "categories": ["finance"], "url": "stories/bank-run-lombard-street/index.html", "image": "../media/bank-run-lombard-street.png", "alt": "19\uc138\uae30 \ub7f0\ub358\uc758 \uc740\ud589 \ubb38 \uc55e\uc5d0 \uc0ac\ub78c\ub4e4\uc774 \ucc28\ub840\ub85c \uc11c \uc788\ub294 \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\uc740\ud589 \uc55e\uc5d0 \uc904\uc774 \uae38\uc5b4\uc9c0\uba74 \u2014 \ub3c8\uacfc \ubbff\uc74c\uc758 \uc2dc\uac04\ucc28 \ubc30\uc800\ud2b8\uc758 \ub86c\ubc14\ub4dc \uc2a4\ud2b8\ub9ac\ud2b8\ub85c \uc77d\ub294 \uae08\uc735 \ubd88\uc548 19\uc138\uae30 \ub7f0\ub358 \uae08\uc735\uc2dc\uc7a5\uc758 \uae30\ub85d\uc5d0\uc11c \ub2f9\uc7a5 \uc9c0\uae09\ud560 \ub3c8\uacfc \uc790\uc0b0 \uac00\uce58\uc758 \ucc28\uc774, \uc704\uae30 \ub54c\uc758 \ub300\ucd9c \uc6d0\uce59\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc740\ud589\uacfc \uc2e0\uc6a9 \ub3c8\uacfc \uae08\uc735 \uc740\ud589 \uc55e\uc5d0 \uc0ac\ub78c\ub4e4\uc774 \uc904\uc744 \uc11c \uc788\ub2e4. \uc55e\uc0ac\ub78c\uc740 \ub3c8\uc744 \ucc3e\uc73c\ub7ec \uc654\uace0, \uadf8 \ubaa8\uc2b5\uc744 \ubcf8 \ub4b7\uc0ac\ub78c\ub3c4 \uc790\uae30 \ub3c8\uc774 \uac71\uc815\ub418\uae30 \uc2dc\uc791\ud55c\ub2e4. \ubaa8\ub450\uac00 \ub3d9\uc2dc\uc5d0 \ud604\uae08\uc744 \ub2ec\ub77c\uace0 \ud558\uba74 \uc5b4\ub5a4 \uc77c\uc774 \uc0dd\uae38\uae4c. \uc740\ud589\uc5d0 \uc7ac\uc0b0\uc774 \uc788\ub2e4\ub294 \ub9d0\uacfc \uc9c0\uae08 \ucc3d\uad6c\uc5d0\uc11c \ub3c8\uc744 \ub0b4\uc904 \uc218 \uc788\ub2e4\ub294 \ub9d0\uc740 \uac19\uc740 \ub73b\uc77c\uae4c. \uc6d4\ud130 \ubc30\uc800\ud2b8\uc758 \u300a\ub86c\ubc14\ub4dc \uc2a4\ud2b8\ub9ac\ud2b8\u300b\ub294 19\uc138\uae30 \uc601\uad6d \uae08\uc735\uc2dc\uc7a5\uc758 \uc5f0\uacb0\uc744 \uc124\uba85\ud55c \ucc45\uc774\ub2e4. \ub7f0\ub358\uc758 \ud55c \uac70\ub9ac \uc774\ub984\uc744 \uc81c\ubaa9\uc73c\ub85c \uc0bc\uc558\uc9c0\ub9cc, \ucc45\uc774 \ub4e4\uc5ec\ub2e4\ubcf4\ub294 \uac83\uc740 \uac74\ubb3c\ubcf4\ub2e4 \ub3c8\uc744 \ub9e1\uae30\uace0 \ube4c\ub9ac\ub294 \uad00\uacc4\ub2e4. \ub2f9\uc2dc\uc758 \uad6c\uc870\ub97c \uc624\ub298\uc758 \ubaa8\ub4e0 \uc740\ud589\uc5d0 \uadf8\ub300\ub85c \ub300\uc785\ud558\uc9c0 \uc54a\uc73c\uba74\uc11c\ub3c4 \uc911\uc694\ud55c \uc9c8\ubb38\uc744 \uc5bb\uc744 \uc218 \uc788\ub2e4. \ub9cc\uc57d \uc740\ud589\uc774 \ubc1b\uc740 \ub3c8\uc744 \uc804\ubd80 \uae08\uace0\uc5d0 \ubcf4\uad00\ud558\uae30\ub9cc \ud55c\ub2e4\uba74 \ub3c8\uc744 \ucc3e\ub294 \ubaa8\uc2b5\uc744 \uc124\uba85\ud558\uae30\ub294 \ub2e8\uc21c\ud558\ub2e4. \uadf8\ub7ec\ub098 \uc740\ud589\uc740 \uc9c0\uae09\ud560 \uc900\ube44\ub97c \ud558\uba74\uc11c \ub2e4\ub978 \ud55c\ud3b8\uc73c\ub85c \ub300\ucd9c\uacfc \uae08\uc735 \uac70\ub798\ub97c \ud55c\ub2e4. \ub3c8\uc744 \ub9e1\uae34 \uc0ac\ub78c\uc758 \uc694\uad6c\uc640 \ub3c8\uc744 \ube4c\ub9b0 \uc0ac\ub78c\uc758 \uc0c1\ud658 \uc2dc\uc810\uc774 \uc11c\ub85c \ub2e4\ub97c \uc218 \uc788\ub2e4. \ubc30\uc800\ud2b8\ub294 \uc608\uae08\uacfc \uc900\ube44\uae08\uc774 \uc5f0\uacb0\ub41c \uc601\uad6d\uc758 \uae08\uc735\uc2dc\uc7a5\uc744 \uc790\uc138\ud788 \ub2e4\ub8ec\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \ub3c8\uc744 \ub9e1\uae30\uace0 \ube4c\ub9ac\ub294 \uc2dc\uac04\uc758 \ucc28\uc774\uc5d0 \ucd08\uc810\uc744 \ub9de\ucd98\ub2e4. \ud604\ub300 \uc740\ud589\uc774 \uc608\uae08\uc744 \ub9cc\ub4e4\uace0 \uacb0\uc81c\ud558\ub294 \uc804\uccb4 \uc6d0\ub9ac\ub97c \ud604\uae08\uc758 \ub2e8\uc21c\ud55c \uc7ac\ubd84\ubc30 \ud558\ub098\ub85c \uc124\uba85\ud558\ub824\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac00\uc0c1\uc758 \uc0ac\ub840\ub97c \uc0dd\uac01\ud574 \ubcf4\uc790. \ub204\uad70\uac00\uac00 \ubc1b\uc744 \ub3c8\uc740 \ucda9\ubd84\ud558\uc9c0\ub9cc \uadf8 \ub3c8\uc774 \ub2e4\uc74c \ub2ec\uc5d0 \ub4e4\uc5b4\uc624\uace0, \uc624\ub298\uae4c\uc9c0 \ub0b4\uc57c \ud560 \uae08\uc561\uc740 \ud070 \uacbd\uc6b0\ub2e4. \uc804\uccb4 \uc7ac\uc0b0\uc758 \uac00\uce58\uc640 \uc624\ub298 \uc4f8 \uc218 \uc788\ub294 \ub3c8 \uc0ac\uc774\uc5d0 \uac04\uaca9\uc774 \uc0dd\uae34\ub2e4. \uc790\uc0b0\uc744 \uace7\ubc14\ub85c \uc81c\uac12\uc5d0 \ud314\uac70\ub098 \ube4c\ub9b4 \uc218 \uc5c6\ub2e4\uba74 \ubb38\uc81c\uac00 \ub41c\ub2e4. \uc774\ucc98\ub7fc \ub2f9\uc7a5 \uc9c0\uae09\ud560 \uc218 \uc788\ub294 \ub2a5\ub825\uc758 \ubb38\uc81c\ub97c \uc720\ub3d9\uc131 \ubb38\uc81c\ub77c\uace0 \ubd80\ub97c \uc218 \uc788\ub2e4. \ubc18\uba74 \uc790\uc0b0\uc744 \ud3c9\uac00\ud574 \ubcf4\uc544\ub3c4 \uac1a\uc544\uc57c \ud560 \ube5a\uc744 \uac10\ub2f9\ud558\uae30 \uc5b4\ub824\uc6b4 \uacbd\uc6b0\ub294 \ub2e4\ub978 \ubb38\uc81c\ub2e4. \ub458\uc740 \ud604\uc2e4\uc5d0\uc11c \uc601\ud5a5\uc744 \uc8fc\uace0\ubc1b\uc744 \uc218 \uc788\uc9c0\ub9cc \uad6c\ubcc4\uc774 \ud544\uc694\ud558\ub2e4. \ubaa8\ub4e0 \uc790\uae08 \ubd80\uc871\uc744 \ub2e8\uc21c\ud788 \uc7a0\uae50\uc758 \uace4\ub780\uc73c\ub85c \ubcfc \uc218\ub294 \uc5c6\ub2e4. \ud3c9\uc0c1\uc2dc\uc5d0\ub294 \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uac19\uc740 \ub0a0 \ub3c8\uc744 \ucc3e\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub7f0\ub370 \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc774 \uba3c\uc800 \uac00\uc838\uac00\uba74 \ub098\ub294 \ub2a6\uc744 \uc218 \uc788\ub2e4\uace0 \ub290\ub07c\uba74 \uc0ac\uc815\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ub2f9\uc7a5 \ub3c8\uc774 \ud544\uc694\ud558\uc9c0 \uc54a\uc740 \uc0ac\ub78c\ub3c4 \uc904\uc5d0 \uc11c\uac8c \ub41c\ub2e4. \uac1c\uc778\uc758 \uac71\uc815\uc774 \ubaa8\uc5ec \uc740\ud589\uc758 \uc9c0\uae09 \ubd80\ub2f4\uc744 \ub354 \ud06c\uac8c \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \uc774\ub7f0 \uc9d1\ub2e8 \uc778\ucd9c\uc744 \ud754\ud788 \ubc45\ud06c\ub7f0\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub9ac\uc11d\uc5b4\uc11c\ub9cc \uc0dd\uae30\ub294 \uc77c\ub85c \uc124\uba85\ud558\uba74 \ubd80\uc871\ud558\ub2e4. \uc790\uae30 \ub3c8\uc744 \uc9c0\ud0a4\ub824\ub294 \uac01\uc790\uc758 \ud310\ub2e8\uc774 \uc804\uccb4\ub85c\ub294 \ub354 \ud070 \ubd88\uc548\uc744 \ub9cc\ub4e4 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ubbff\uc74c\uc740 \ucd94\uc0c1\uc801\uc778 \uac10\uc815\uc774\uba74\uc11c\ub3c4 \uc0ac\ub78c\ub4e4\uc774 \uc6c0\uc9c1\uc774\ub294 \uc2dc\uc810\uc744 \uc2e4\uc81c\ub85c \ubc14\uafb8\ub294 \uc694\uc778\uc774 \ub41c\ub2e4. \uae08\uc735\uae30\uad00\ub07c\ub9ac\ub3c4 \ub3c8\uc744 \ub9e1\uae30\uace0 \ube4c\ub9ac\uba70 \uacb0\uc81c\ud55c\ub2e4. \uc5b4\ub290 \ud55c\uacf3\uc774 \uc9c0\uae09\ud558\uc9c0 \ubabb\ud560 \uc218 \uc788\ub2e4\ub294 \uc0dd\uac01\uc740 \uadf8\uacf3\uacfc \uac70\ub798\ud55c \ub2e4\ub978 \uae30\uad00\uc5d0 \ub300\ud55c \uac71\uc815\uc73c\ub85c \ubc88\uc9c8 \uc218 \uc788\ub2e4. \ubc30\uc800\ud2b8\uac00 \ub4e4\uc5ec\ub2e4\ubcf8 \ub7f0\ub358 \uc2dc\uc7a5\uc5d0\uc11c\ub3c4 \ub3c8\uc758 \ubcf4\uad00\uacfc \ub300\ucd9c\uc740 \uc5ec\ub7ec \uce35\uc73c\ub85c \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc774 \uc5f0\uacb0\uc740 \ud3c9\uc0c1\uc2dc\uc5d0\ub294 \uc790\uae08\uc744 \uc4f0\uae30 \uc27d\uac8c \ud558\uc9c0\ub9cc \uc704\uae30\uc5d0\ub294 \ubd88\uc548\uc774 \uc6c0\uc9c1\uc774\ub294 \uae38\uc774 \ub418\uae30\ub3c4 \ud55c\ub2e4. \ud558\ub098\uc758 \ucc3d\uad6c\uc5d0 \uc904\uc774 \uc0dd\uae34 \uc774\uc720\ub97c \uadf8 \uc9c0\uc810\uc758 \ud604\uae08\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b4 \uae4c\ub2ed\uc774\ub2e4. \ub204\uad6c\uc5d0\uac8c \ubc1b\uc744 \ub3c8\uc774 \uc788\uace0, \ub204\uac00 \ub204\uad6c\uc758 \uc9c0\uae09\uc744 \uae30\ub2e4\ub9ac\ub294\uc9c0 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ubc30\uc800\ud2b8\ub294 \uc704\uae30\uc5d0 \uc900\ube44\uae08\uc744 \ubcf4\uc720\ud55c \uc911\uc2ec \uae30\uad00\uc774 \uc5b4\ub5bb\uac8c \ub300\uc751\ud560\uc9c0 \ub17c\uc758\ud588\ub2e4. \ucc45\uc5d0\uc11c \uac15\uc870\ud558\ub294 \uc6d0\uce59\uc740 \ub192\uc740 \uc774\uc790\uc728\ub85c \ube4c\ub824\uc8fc\ub418, \uc88b\uc740 \uae08\uc735 \ub2f4\ubcf4\ub97c \ubc14\ud0d5\uc73c\ub85c \ud544\uc694\ud55c \uc790\uae08\uc744 \ub109\ub109\ud558\uac8c \uacf5\uae09\ud558\ub77c\ub294 \uac83\uc774\ub2e4. \uc77c\uc0c1\uc801\uc778 \uc2f8\uace0 \uc26c\uc6b4 \ub300\ucd9c\uc744 \ubaa8\ub450\uc5d0\uac8c \ub098\ub204\uc790\ub294 \uc8fc\uc7a5\uacfc\ub294 \ub2e4\ub974\ub2e4. \uc9c0\uae09 \uac00\ub2a5\ud55c \uc790\uae08\uc774 \ubd80\uc871\ud55c \uacf3\uc5d0 \ub3c8\uc774 \ud758\ub7ec\uac00\uba74 \uc790\uc0b0\uc744 \uae09\ud558\uac8c \ucc98\ubd84\ud558\uace0 \uc11c\ub85c \uc758\uc2ec\ud558\ub294 \uc545\uc21c\ud658\uc744 \uc904\uc77c \uc218 \uc788\ub2e4\ub294 \uc0dd\uac01\uc774\ub2e4. \uc774 \ub17c\uc758\ub294 \ud754\ud788 \ucd5c\uc885 \ub300\ubd80\uc790\uc758 \uc5ed\ud560\uacfc \uc5f0\uacb0\ud574 \uc77d\ud78c\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubc30\uc800\ud2b8\uc758 \ub2f9\uc2dc \uc81c\uc548\uc744 \uc124\uba85\ud558\ub294 \uac83\uc774\uba70 \uc624\ub298\uc758 \ubaa8\ub4e0 \uc911\uc559\uc740\ud589\uc774 \ub611\uac19\uc774 \ud589\ub3d9\ud55c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud604\uae08\uc744 \uc7a0\uc2dc \uad6c\ud558\uc9c0 \ubabb\ud55c \uacf3\uacfc \uc774\ubbf8 \uc190\uc2e4\uc774 \ucee4\uc11c \uac1a\uae30 \uc5b4\ub824\uc6b4 \uacf3\uc744 \uac00\ub9ac\ub294 \uc77c\uc740 \ub9d0\ucc98\ub7fc \uc27d\uc9c0 \uc54a\ub2e4. \uc704\uae30\uc5d0\ub294 \uc790\uc0b0\uc758 \uac00\uaca9 \uc790\uccb4\uac00 \ubd88\uc548\ud574\uc9c4\ub2e4. \ud3c9\uc0c1\uc2dc\uc5d0 \ubbff\uc744 \ub9cc\ud574 \ubcf4\uc600\ub358 \ub2f4\ubcf4\ub97c \uc5bc\ub9c8\ub85c \ud3c9\uac00\ud560\uc9c0\ub3c4 \ubb38\uc81c\uac00 \ub41c\ub2e4. \uadf8\ub798\uc11c \uc704\uae30 \ub300\ucd9c\uc740 \ub3c8\uc744 \ub9ce\uc774 \ud480\uba74 \ub05d\ub098\ub294 \uac04\ub2e8\ud55c \uc7a5\uba74\uc774 \uc544\ub2c8\ub2e4. \ub3c4\uc6c0\uc744 \uc8fc\uc9c0 \uc54a\uc544 \ubd88\uc548\uc774 \ucee4\uc9c8 \uc704\ud5d8\uacfc, \uc190\uc2e4\uc744 \ucda9\ubd84\ud788 \uc0b4\ud53c\uc9c0 \uc54a\uace0 \uc9c0\uc6d0\ud560 \uc704\ud5d8\uc744 \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \ub192\uc740 \uc774\uc790\uc728\uacfc \uc88b\uc740 \ub2f4\ubcf4\ub77c\ub294 \ub9d0\uc740 \uc774\ub7f0 \uad6c\ubcc4\uc744 \uc2dc\ub3c4\ud558\ub294 \uc6d0\uce59\uc774\uc9c0 \ud310\ub2e8\uc744 \uc790\ub3d9\uc73c\ub85c \ub300\uc2e0\ud558\ub294 \uae30\uacc4\uac00 \uc544\ub2c8\ub2e4. \ubc30\uc800\ud2b8\uac00 \uc0b4\ud3b4\ubcf8 \uc601\uad6d\uc758 \ud1b5\ud654\u00b7\uae08\uc735 \uc81c\ub3c4\uc640 \ud604\uc7ac \uc5ec\ub7ec \ub098\ub77c\uc758 \uc81c\ub3c4\ub294 \ub2e4\ub974\ub2e4. \uc608\uae08 \ubcf4\ud638\ub098 \uc911\uc559\uc740\ud589\uc758 \uc218\ub2e8\ub3c4 \ub098\ub77c\uc640 \uc2dc\ub300\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c4\ub2e4. \uc774 \uae00\ub9cc\uc73c\ub85c \uc624\ub298\uc758 \ud2b9\uc815 \uc740\ud589\uc774 \uc548\uc804\ud55c\uc9c0 \ud310\ub2e8\ud558\uac70\ub098 \uc778\ucd9c \uc5ec\ubd80\ub97c \uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc61b \ucc45\uc758 \uac00\uce58\ub294 \uadf8\ub300\ub85c \ub530\ub77c \ud560 \ucc98\ubc29\uc804\uc744 \uc900\ub2e4\ub294 \ub370\ubcf4\ub2e4 \uc9c8\ubb38\uc744 \uc815\ub9ac\ud574 \uc900\ub2e4\ub294 \ub370 \uc788\ub2e4. \uc790\uc0b0\uc774 \ucda9\ubd84\ud55c\uac00, \ub2f9\uc7a5 \uc9c0\uae09\ud560 \uc218 \uc788\ub294\uac00, \ub2e4\ub978 \uae30\uad00\uacfc \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ub418\ub294\uac00. \uac89\uc73c\ub85c \ubaa8\ub450 \ub3c8\uc774 \uc5c6\ub2e4\ub294 \ub9d0\ub85c \ub4e4\ub9ac\ub294 \uc0c1\ud669\uc744 \uad6c\ubd84\ud574 \ubcf4\uba74 \uae08\uc735 \ub274\uc2a4\ub3c4 \uc870\uae08 \ub35c \ub9c9\uc5f0\ud574\uc9c4\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc740\ud589 \uac70\ub9ac \uadf8\ub9bc\uc740 19\uc138\uae30\uc758 \ubd84\uc704\uae30\ub97c \uc0c1\uc0c1\ud55c AI \uc0bd\ud654\ub2e4. \ud2b9\uc815 \uc704\uae30 \ub54c \ucd2c\uc601\ud55c \uc0ac\uc9c4\uc774\ub098 \uc5b4\ub290 \uc740\ud589\uc758 \uc2e4\uc81c \uc778\ucd9c \uc7a5\uba74\uc774 \uc544\ub2c8\ub2e4. \uc904\uc744 \uc120 \uc0ac\ub78c\uc758 \uc637\ucc28\ub9bc\ubcf4\ub2e4 \uadf8 \uc0ac\ub78c\ub4e4\uc774 \uac19\uc740 \uc2dc\uac04\uc5d0 \uac19\uc740 \uc694\uad6c\ub97c \ud558\uac8c \ub418\ub294 \uc774\uc720\ub97c \ub5a0\uc62c\ub9ac\uae30 \uc704\ud55c \uadf8\ub9bc\uc774\ub2e4. \uc740\ud589 \uc55e\uc758 \uc904 \ub4a4\uc5d0\ub294 \ub3c8\uc774 \ub4e4\uc5b4\uc624\uace0 \ub098\uac00\ub294 \uc2dc\uac04, \uc790\uc0b0\uc758 \uac00\uce58, \uc11c\ub85c\uc5d0 \ub300\ud55c \ubbff\uc74c\uc774 \uacb9\uccd0 \uc788\ub2e4. \uae08\uc735\uc740 \uc22b\uc790\ub97c \uacc4\uc0b0\ud558\ub294 \uc77c\uc778 \ub3d9\uc2dc\uc5d0 \uc5ec\ub7ec \uc0ac\ub78c\uc774 \uc11c\ub85c \ub2e4\ub978 \ubbf8\ub798\ub97c \uc57d\uc18d\ud558\ub294 \uc77c\uc774\ub2e4. \uadf8 \uc57d\uc18d\uc758 \uc2dc\uac04\uc774 \ud55c\uaebc\ubc88\uc5d0 \uc624\ub298\ub85c \ub2f9\uaca8\uc9c8 \ub54c \uc704\uae30\uc758 \uc5b4\ub824\uc6c0\uc774 \ub4dc\ub7ec\ub09c\ub2e4."}, {"id": "banknote-plate-fifty-yang", "title": "\ub3c8\uc744 \ub9cc\ub4e4\ub358 \ub098\ubb34\ud310\uc5d0\ub294 \ubb34\uc5c7\uc774 \ub0a8\uc558\uc744\uae4c", "summary": "\uc22b\uc790\uc640 \uae00\uc790\uac00 \ub0a8\uc740 \uc9c0\ud3d0\uc6d0\ud310\uc5d0\uc11c \uc885\uc774\ub3c8\uc758 \ub4b7\ubaa8\uc2b5\uc744 \ub9cc\ub0a9\ub2c8\ub2e4.", "category": "finance", "category_title": "\ub3c8\uacfc \uae08\uc735", "subcategory": "\ub3c8\uacfc \ud654\ud3d0", "categories": ["finance"], "url": "stories/banknote-plate-fifty-yang/index.html", "image": "../media/banknote-plate-fifty-yang.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc9c0\ud3d0\uc6d0\ud310 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\ub3c8\uc744 \ub9cc\ub4e4\ub358 \ub098\ubb34\ud310\uc5d0\ub294 \ubb34\uc5c7\uc774 \ub0a8\uc558\uc744\uae4c \uc9c0\ud3d0 \ud55c \uc7a5\ubcf4\ub2e4 \uc55e\uc5d0 \uc788\uc5c8\ub358 \ubb3c\uac74 \uc22b\uc790\uc640 \uae00\uc790\uac00 \ub0a8\uc740 \uc9c0\ud3d0\uc6d0\ud310\uc5d0\uc11c \uc885\uc774\ub3c8\uc758 \ub4b7\ubaa8\uc2b5\uc744 \ub9cc\ub0a9\ub2c8\ub2e4. \ub3c8\uacfc \ud654\ud3d0 \ub3c8\uacfc \uae08\uc735 \ub0a1\uc740 \uc9c1\uc0ac\uac01\ud615 \ub098\ubb34\ud310\uc774 \uc788\ub2e4. \uac00\uc6b4\ub370\ub294 \uae38\uac8c \ud30c\uc600\uace0 \uac00\uc7a5\uc790\ub9ac\uc5d0\ub294 \uc791\uc740 \uae00\uc790\uc640 \ubb34\ub2ac\uac00 \ub0a8\uc544 \uc788\ub2e4. \ucc98\uc74c \ubcf4\uba74 \uc0c1\uc790\uc758 \ubd80\ud488 \uac19\uae30\ub3c4 \ud558\ub2e4. \uadf8\ub7f0\ub370 \ubc15\ubb3c\uad00\uc774 \ubd99\uc778 \uc774\ub984\uc740 \uc9c0\ud3d0\uc6d0\ud310\uc774\ub2e4. \ub3c8\uc774\ub77c\uace0 \ud558\uba74 \uc9c0\uac11 \uc18d \uc885\uc774\ub098 \ub3d9\uc804\uc744 \ub5a0\uc62c\ub9ac\uc9c0\ub9cc, \uc774\uac83\uc740 \uadf8 \ub3c8\uc744 \ub9cc\ub4dc\ub294 \ucabd\uc5d0 \uc788\ub358 \ubb3c\uac74\uc774\ub2e4. \uc644\uc131\ub41c \uc9c0\ud3d0\uc5d0\uc11c \ud55c \uac78\uc74c \ub4a4\ub85c \ubb3c\ub7ec\uc11c\ub2c8 \ud3c9\uc18c\uc5d0\ub294 \ubcf4\uc9c0 \ubabb\ud558\ub358 \ubb3c\uac74\uc774 \ub098\uc628\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \uc124\uba85\uc5d0 \ub530\ub974\uba74 \uc6d0\ud310 \uc704\ucabd\uc5d0\ub294 TAI WHAN SHOU, \uc544\ub798\ucabd\uc5d0\ub294 FIFTY YANG\uc774\ub77c\ub294 \uae00\uc790\uac00 \uc788\ub2e4. \uc544\ub798 \ubb38\uad6c\uc5d0\ub294 \uc624\uc2ed \uc591\uc774\ub77c\ub294 \uc561\uba74\uc744 \uc601\uc5b4\ub85c \ub098\ud0c0\ub0b8 \ud45c\ud604\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ub124 \uadc0\ud241\uc774\uc5d0\ub294 \ub465\uadfc \uad6c\uba4d \uc548\uc5d0 \uc624\uc2ed\uacfc 50\uc774\ub77c\ub294 \uae00\uc790\ub3c4 \ub0a8\uc544 \uc788\ub2e4\uace0 \ud55c\ub2e4. \uac19\uc740 \uc218\uac00 \uae00\uc790\uc640 \uc22b\uc790\ub85c \uac70\ub4ed \ub098\ud0c0\ub098\ub294 \uac83\uc774\ub2e4. \uc791\uc740 \uc7a5\uc2dd\uc73c\ub85c\ub9cc \ubcf4\uc774\ub358 \uc790\ub9ac\uc5d0 \ub3c8\uc758 \uae08\uc561\uc744 \uac00\ub9ac\ud0a4\ub294 \uc815\ubcf4\uac00 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uba3c\uc800 \ub208\uc5d0 \ub4e4\uc5b4\uc624\ub294 \ubd80\ubd84\uc740 \uac00\uc6b4\ub370\uc758 \uae38\ucb49\ud55c \ud648\uc774\ub2e4. \ubc15\ubb3c\uad00\uc740 \uadf8 \uc8fc\ubcc0\uc73c\ub85c \ub369\uad74 \ubaa8\uc591\uc758 \ub2f9\ucd08\ubb38\uc774 \ub458\ub7ec\uc838 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ube44\uc5b4 \uc788\ub294 \uacf5\uac04\uacfc \ucd18\ucd18\ud55c \ubb34\ub2ac\uac00 \ud55c \ud310 \uc548\uc5d0\uc11c \ub098\ub25c\ub2e4. \ub2e4\ub9cc \uc774 \ud648\uc5d0 \uc5b4\ub5a4 \ubd80\ud488\uc774 \ub4e4\uc5b4\uac14\ub294\uc9c0, \uc774 \uc6d0\ud310\uc73c\ub85c \uc2e4\uc81c \uc5bc\ub9c8\ub9cc\ud07c\uc758 \uc9c0\ud3d0\ub97c \ub9cc\ub4e4\uc5c8\ub294\uc9c0\uae4c\uc9c0\ub294 \ud574\ub2f9 \uc124\uba85\uc73c\ub85c \uc54c \uc218 \uc5c6\ub2e4. \uc775\uc219\ud55c \uc778\uc1c4 \uacfc\uc815\uc744 \uac00\uc838\uc640 \ube48\uce78\uc744 \ucc44\uc6b0\uae30\ubcf4\ub2e4, \uc9c0\uae08 \ub0a8\uc544 \uc788\ub294 \ubaa8\uc591\uc5d0\uc11c \uc774\uc57c\uae30\ub97c \uc2dc\uc791\ud574 \ubcf4\uc790. \uc9c0\ud3d0\ub97c \ub5a0\uc62c\ub9ac\uba74 \uac70\ub798\ud560 \ub54c \uc190\uc5d0\uc11c \uc190\uc73c\ub85c \uc624\uac00\ub294 \uc885\uc774\ub97c \uc0dd\uac01\ud55c\ub2e4. \uc774 \uc18c\uc7a5\ud488\uc740 \uadf8 \uc885\uc774\uac00 \uc544\ub2c8\ub77c \uc9c0\ud3d0\uc640 \uad00\ub828\ub41c \ubb34\ub2ac\ub97c \uac00\uc9c4 \ubaa9\uc81c \uc6d0\ud310\uc774\ub2e4. \uc644\uc131\ud488\uacfc \uc81c\uc791 \ub3c4\uad6c\ub97c \uad6c\ubd84\ud558\uba74 \uad00\ucc30\uc758 \ucd08\uc810\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ubb34\ub2ac\uac00 \ubb34\uc5c7\uc744 \ub73b\ud558\ub294\uc9c0 \uc606\uc5d0 \uadf8 \ubb34\ub2ac\ub97c \uc5b4\ub5a4 \ub9e4\uccb4\uc5d0 \ub0a8\uacbc\ub294\uc9c0\ub3c4 \ubb3b\uac8c \ub41c\ub2e4. \uac00\ub85c 16.3\uc13c\ud2f0\ubbf8\ud130\ub77c\ub294 \ud06c\uae30\ub97c \uc54c\uba74 \uc0ac\uc9c4 \uc18d \ubb3c\uac74\uc744 \uc2e4\uc81c \uc190\uc758 \ubc94\uc704\uc640 \uc5f0\uacb0\ud574 \ubcfc \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc774 \uce58\uc218\ub97c \uace7\ubc14\ub85c \uc644\uc131 \uc9c0\ud3d0\uc758 \ubaa8\ub4e0 \uaddc\uaca9\uc774\ub77c\uace0 \uc4f0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc6d0\ud310\uc758 \ud06c\uae30\uc640 \uc778\uc1c4\ub41c \uc885\uc774\uc758 \ud06c\uae30\ub294 \uac19\uc740 \uc790\ub8cc\ub85c \ud655\uc815\ud560 \uc218 \uc788\ub294 \ubb38\uc81c\uac00 \uc544\ub2d0 \uc218 \uc788\ub2e4. \uc22b\uc790\uac00 \ubb34\uc5c7\uc744 \uc7ac\ub294\uc9c0\ubd80\ud130 \uc815\ud655\ud788 \uc77d\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc624\uc2ed\uc774\ub77c\ub294 \uae00\uacfc 50\uc774\ub77c\ub294 \uc22b\uc790\ub294 \uac19\uc740 \uc561\uba74\uc744 \ub2e4\ub978 \ud45c\uae30\ub85c \ubcf4\uc5ec \uc900\ub2e4. FIFTY YANG\uc774\ub77c\ub294 \ud45c\ud604\ub3c4 \ud568\uaed8 \uc788\ub2e4. \uc22b\uc790\uc640 \ubb38\uc790\uac00 \ud654\uba74\uc758 \uc5ec\ub7ec \uc790\ub9ac\uc5d0 \ub193\uc600\ub2e4\ub294 \uc810\uc740 \uac00\uce58\uc758 \ud45c\uc2dc\uac00 \uc7a5\uc2dd\uacfc \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ubb34\ub2ac\ub97c \ud558\ub098\uc529 \uc54c\uc544\ubcf4\uba74 \ub3c8\uc758 \uc815\ubcf4\ub97c \uc77d\ub294 \ubc29\uc2dd\ub3c4 \ub2e4\uc591\ud574\uc9c4\ub2e4. \uadf8\ub807\ub2e4\uace0 \uac19\uc740 \uc218\uac00 \ubc18\ubcf5\ub41c \uc774\uc720\ub97c \ud2b9\uc815\ud55c \uc704\uc870 \ubc29\uc9c0 \uae30\uc220 \ud558\ub098\ub85c \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc5b4\ub5a4 \ud6a8\uacfc\ub97c \ubaa9\ud45c\ub85c \uc124\uacc4\ud588\ub294\uc9c0\ub294 \ucd94\uac00 \uae30\ub85d\uc774 \ud544\uc694\ud558\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubc15\ubb3c\uad00\uc774 \ud655\uc778\ud55c \uc704\uce58\uc640 \ud45c\uae30\ub97c \uba3c\uc800 \uc0b4\ud540\ub2e4. \uae00\uacfc \uc22b\uc790\uac00 \ub098\ub258\uc5b4 \uc788\ub294 \ubaa8\uc591\uc740 \ud55c \uc7a5\uc758 \ud1b5\ud654\uac00 \uc5ec\ub7ec \ubd80\ubd84\uc744 \ud1b5\ud574 \uc790\uc2e0\uc744 \uc2dd\ubcc4\ud558\uac8c \ud55c\ub2e4\ub294 \uc810\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc911\uc559\uc758 \uae38\ucb49\ud55c \ud648\uacfc \uadf8 \ub458\ub808\uc758 \ub369\uad74\ubb34\ub2ac\ub294 \uc11c\ub85c \ub2e4\ub978 \uc2dc\uac01\uc801 \uc790\ub9ac\ub97c \ub9cc\ub4e0\ub2e4. \ucd18\ucd18\ud55c \ubd80\ubd84\uacfc \ube44\uc5b4 \uc788\ub294 \ubd80\ubd84\uc774 \ud568\uaed8 \uc788\uc5b4\uc11c \ubb3c\uac74\uc758 \uad6c\uc870\uac00 \ub354 \ub69c\ub837\ud574\uc9c4\ub2e4. \ub2e4\ub9cc \uc9c0\uae08 \ud648\uc774 \ubcf4\uc778\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ucc98\uc74c\ubd80\ud130 \uadf8\uacf3\uc774 \ube44\uc6cc\uc838 \uc0ac\uc6a9\ub418\uc5c8\ub2e4\ub294 \ud574\uc11d\uc740 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ube60\uc9c4 \ubd80\ud488\uc758 \uc874\uc7ac\uc640 \uc5ed\ud560\uc740 \uadfc\uac70 \uc5c6\uc774 \ucc44\uc6b8 \uc218 \uc5c6\ub2e4. \uc774\ub7f0 \ubb3c\uac74\uc5d0\uc11c\ub294 \ubb34\uc5c7\uc774 \uc5c6\ub294\uc9c0 \ubb3b\ub294 \uc77c\ub3c4 \uc911\uc694\ud558\ub2e4. \uadf8\ub807\uc9c0\ub9cc \ube48\uacf3\uc744 \ubc1c\uacac\ud588\ub2e4\uace0 \uace7\ubc14\ub85c \uc644\uc804\ud55c \uc81c\uc791 \uacfc\uc815\uc744 \ubcf5\uc6d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc9c0\uae08 \ub0a8\uc740 \uc0c1\ud0dc\uc640 \uc6d0\ub798\uc758 \uae30\ub2a5\uc744 \ub098\ub204\uc5b4 \ubcf4\ub294 \ud0dc\ub3c4\ub294 \ubd88\ud655\uc2e4\ud568\uc744 \ud0a4\uc6b0\uae30\ubcf4\ub2e4 \uc9c8\ubb38\uc744 \uc815\ud655\ud558\uac8c \ub9cc\ub4e0\ub2e4. \ud655\uc778\ud560 \uc218 \uc788\ub294 \uc7a5\uc2dd\uacfc \ud45c\uae30\ubd80\ud130 \ucc28\ub840\ub85c \uc77d\ub294 \ud3b8\uc774 \uc774\uc57c\uae30\ub97c \ub2e8\ub2e8\ud558\uac8c \ud55c\ub2e4. \ud1b5\ud654\ub294 \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc774 \uac19\uc740 \ub2e8\uc704\ub97c \uc54c\uc544\ubcf4\uace0 \ubc1b\uc544\ub4e4\uc774\ub294 \uad00\uacc4 \uc18d\uc5d0\uc11c \uc0ac\uc6a9\ub41c\ub2e4. \ubc18\ubcf5\ud574\uc11c \ube44\uc2b7\ud55c \ud45c\uc2dc\ub97c \ub9cc\ub4dc\ub294 \ub3c4\uad6c\ub294 \uadf8\ub7f0 \uacf5\ud1b5\ub41c \ubaa8\uc591\uc744 \uc900\ube44\ud558\ub294 \ubb3c\uac74\uc73c\ub85c \ubcfc \uc218 \uc788\ub2e4. \uc6d0\ud310\uc744 \ubcf4\uba74 \uc9c0\ud3d0 \ud55c \uc7a5\uc758 \uc55e\uba74 \ub4a4\uc5d0 \ub204\uad70\uac00 \uc120\uacfc \uae00\uc790\ub97c \uc815\ub9ac\ud558\uace0 \uc7ac\ub8cc\uc5d0 \uc62e\uae30\ub294 \uc791\uc5c5\uc774 \uc788\uc5c8\uc74c\uc744 \ub5a0\uc62c\ub9ac\uac8c \ub41c\ub2e4. \ub2e4\ub9cc \uc774 \ud55c \uc810\uc774 \uc2e4\uc81c\ub85c \uc5b4\ub290 \uc2dc\uae30\uc5d0 \uc5bc\ub9c8\ub098 \uc0ac\uc6a9\ub418\uc5c8\ub294\uc9c0, \uc5b4\ub5a4 \uc81c\ub3c4 \uc548\uc5d0\uc11c \ubc1c\ud589\ub418\uc5c8\ub294\uc9c0\ub294 \uc5ec\uae30\uc11c \ud655\uc778\ud55c \uc124\uba85\uc758 \ubc94\uc704\ub97c \ub118\ub294\ub2e4. \uc8fc\uace0\ubc1b\ub358 \ub3c8\uacfc \ub3c8\uc744 \ub9cc\ub4e4\ub824 \ub0a8\uae34 \ub3c4\uad6c\ub294 \uac01\uac01 \ub2e4\ub978 \uae30\ub85d\uc744 \uc694\uad6c\ud55c\ub2e4. \ub098\ubb34\ud310\uc758 \uae00\uc790\ub97c \ucc9c\ucc9c\ud788 \ubcf4\ub294 \uc77c\uc740 \ud654\ud3d0\uc758 \uc5ed\uc0ac\ub97c \uac00\uaca9\uacfc \uc81c\ub3c4\ubfd0 \uc544\ub2c8\ub77c \uc81c\uc791\ud558\ub294 \uc190\uc758 \uc5ed\uc0ac\ub85c \ub9cc\ub098\ub294 \uc785\uad6c\uac00 \ub41c\ub2e4. \uc18c\uc7a5\ud488 \uc815\ubcf4\uc5d0 \uc801\ud78c \uac00\ub85c \uae38\uc774\ub294 16.3\uc13c\ud2f0\ubbf8\ud130\ub2e4. \ud654\uba74\uc5d0\uc11c \ud06c\uac8c \ubcf4\uba74 \ubb35\uc9c1\ud55c \ud310\ucc98\ub7fc \ub290\uaef4\uc838\ub3c4 \uc2e4\uc81c \ud06c\uae30\ub97c \uac00\ub2a0\ud558\uba74 \uc190 \uac00\uae4c\uc6b4 \ubb3c\uac74\uc774 \ub41c\ub2e4. \ub3c8\uc758 \uc5ed\uc0ac\uac00 \uaf2d \uac70\ub300\ud55c \uae08\uace0\uc5d0\uc11c\ub9cc \uc2dc\uc791\ub418\ub294 \uac83\uc740 \uc544\ub2cc \uc148\uc774\ub2e4. \uc774 \uc6d0\ud310\uc744 \ubcf4\uace0 \ub098\uba74 \uc9c0\ud3d0 \uc704 \uc22b\uc790\ub3c4 \uc870\uae08 \ub2e4\ub974\uac8c \ubcf4\uc778\ub2e4. \uc885\uc774\uc5d0 \ub098\ud0c0\ub09c \uacb0\uacfc\ub9cc \uc788\uc5c8\ub358 \uac83\uc774 \uc544\ub2c8\ub77c, \uadf8\ubcf4\ub2e4 \uc55e\uc11c \uae00\uc790\uc640 \ubb34\ub2ac\ub97c \ub9c8\ub828\ud558\ub294 \ubb3c\uac74\uc774 \uc788\uc5c8\ub2e4. \uc624\ub298\uc740 \ub3c8\uc744 \uc4f0\ub294 \ub300\uc2e0 \ub3c8\uc774 \ub9cc\ub4e4\uc5b4\uc9c0\uae30 \uc804\uc758 \ud55c \uc7a5\uba74\uc744 \ub4e4\uc5ec\ub2e4\ubcf8 \uac83\uc774\ub2e4."}, {"id": "bond-price-when-interest-rates-rise", "title": "\ucc44\uad8c \u2014 \uc774\uc790\ub294 \uadf8\ub300\ub85c\uc778\ub370 \uc65c \uac00\uaca9\uc774 \ub5a8\uc5b4\uc9c8\uae4c", "summary": "\ub9cc\uae30\uac00 1\ub144 \ub0a8\uc740 \uac00\uc0c1 \ucc44\uad8c\uc758 \uacc4\uc0b0\uc73c\ub85c \ud45c\uba74\uc774\uc790\uc640 \uc2dc\uc7a5 \uc218\uc775\ub960, \uac00\uaca9\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "finance", "category_title": "\ub3c8\uacfc \uae08\uc735", "subcategory": "\ud22c\uc790\uc640 \uc2dc\uc7a5", "categories": ["finance"], "url": "stories/bond-price-when-interest-rates-rise/index.html", "image": "../media/bond-price-when-interest-rates-rise.png", "alt": "\ube48 \ub2ec\ub825\uacfc \ubd09\ud22c\uac00 \ub193\uc778 \ucc45\uc0c1\uc5d0\uc11c \ub450 \uc7a5\uc758 \uc11c\ub958\ub97c \ube44\uad50\ud558\ub294 \uc0ac\ub78c\uc758 \uc0bd\ud654.", "text": "\ucc44\uad8c \u2014 \uc774\uc790\ub294 \uadf8\ub300\ub85c\uc778\ub370 \uc65c \uac00\uaca9\uc774 \ub5a8\uc5b4\uc9c8\uae4c \ubbf8\ub798\uc5d0 \ubc1b\uc744 \uc57d\uc18d\uacfc \uc624\ub298 \uc0ac\uace0\ud30c\ub294 \uac12\uc744 \ub098\ub204\uae30 \ub9cc\uae30\uac00 1\ub144 \ub0a8\uc740 \uac00\uc0c1 \ucc44\uad8c\uc758 \uacc4\uc0b0\uc73c\ub85c \ud45c\uba74\uc774\uc790\uc640 \uc2dc\uc7a5 \uc218\uc775\ub960, \uac00\uaca9\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ud22c\uc790\uc640 \uc2dc\uc7a5 \ub3c8\uacfc \uae08\uc735 \ub3c8\uc744 \ube4c\ub824\uc900 \uc99d\uc11c\uac00 \uc788\uace0 \ud574\ub9c8\ub2e4 \ubc1b\uae30\ub85c \ud55c \uc774\uc790\ub3c4 \uc815\ud574\uc838 \uc788\ub2e4. \uadf8\ub7f0\ub370 \uadf8 \uc99d\uc11c\ub97c \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ud314\ub824\uace0 \ud558\ub2c8 \uac00\uaca9\uc774 \ub0b4\ub824\uac14\ub2e4\uace0 \ud55c\ub2e4. \uc57d\uc18d\ud55c \uc774\uc790\uac00 \uadf8\ub300\ub85c\ub77c\uba74 \uac12\ub3c4 \uadf8\ub300\ub85c\uc5ec\uc57c \ud558\ub294 \uac83 \uc544\ub2d0\uae4c. \ucc44\uad8c \ub274\uc2a4\ub97c \uc77d\uc744 \ub54c \uc0dd\uae30\ub294 \uc775\uc219\ud55c \uad81\uae08\uc99d\uc774\ub2e4. \uc774 \uc9c8\ubb38\uc740 \ubbf8\ub798\uc5d0 \ubc1b\ub294 \uae08\uc561\uacfc \uc624\ub298 \uadf8 \uc57d\uc18d\uc744 \uc0ac\ub294 \uac00\uaca9\uc774 \uc11c\ub85c \ub2e4\ub978 \uac83\uc784\uc744 \uc54c\uba74 \ud480\ub9ac\uae30 \uc2dc\uc791\ud55c\ub2e4. \uc5b4\ub835\uac8c \ubcf4\uc774\ub294 \uae08\ub9ac\uc640 \ucc44\uad8c\uc758 \ubc18\ub300 \ubc29\ud5a5 \uad00\uacc4\uc5d0\ub3c4 \ub2e4\ub978 \uc120\ud0dd\uacfc \ube44\uad50\ud558\ub294 \uc0ac\ub78c\uc758 \ud310\ub2e8\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ucc44\uad8c\uc740 \ubc1c\ud589\uc790\uac00 \uc790\uae08\uc744 \ub9c8\ub828\ud558\uace0 \ud22c\uc790\uc790\uc5d0\uac8c \uc815\ud574\uc9c4 \uc870\uac74\uc758 \uc9c0\uae09\uc744 \uc57d\uc18d\ud558\ub294 \uae08\uc735\uc0c1\ud488\uc774\ub2e4. \uc774\uc790\ub97c \uc815\uae30\uc801\uc73c\ub85c \uc9c0\uae09\ud558\uace0 \ub9cc\uae30\uc5d0 \uc6d0\uae08\uc744 \uac1a\ub294 \ud615\ud0dc\uac00 \ub300\ud45c\uc801\uc774\ub2e4. \ubaa8\ub4e0 \ucc44\uad8c\uc758 \uad6c\uc870\uac00 \uac19\uc9c0\ub294 \uc54a\uc73c\ubbc0\ub85c \uc774\ubc88\uc5d0\ub294 \uae08\uc561\uc774 \uace0\uc815\ub41c \ub2e8\uc21c\ud55c \uacbd\uc6b0\ub97c \uc0dd\uac01\ud558\uc790. OpenStax\ub294 \ucc44\uad8c\uc758 \uac00\uce58\ub97c \uc55e\uc73c\ub85c \ubc1b\uc744 \ub3c8\uc758 \uae08\uc561\uacfc \uc2dc\uc810\uc744 \uc0b4\ud3b4 \ud3c9\uac00\ud55c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc624\ub298 \uc5bc\ub9c8\ub97c \ub0b4\uba74 \ub098\uc911\uc5d0 \ubb34\uc5c7\uc744 \ubc1b\ub294\uc9c0\uac00 \ud575\uc2ec\uc774\ub2e4. \uc57d\uc18d\uc758 \uc885\uc774\uc5d0 \uc801\ud78c \uc6d0\uae08\uacfc \uc9c0\uae08 \uac70\ub798\ud558\ub294 \uac00\uaca9\uc774 \ub298 \uac19\uc740 \uc22b\uc790\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774\ubbf8 \uac00\uc9c4 \ucc44\uad8c\uc774 \uc5f0 3%\uc758 \uc774\uc790\ub97c \uc57d\uc18d\ud55c\ub2e4\uace0 \ud574 \ubcf4\uc790. \ube44\uc2b7\ud55c \uc704\ud5d8\uacfc \uc870\uac74\uc758 \ub2e4\ub978 \uc120\ud0dd\uc5d0\uc11c \ub354 \ub192\uc740 \uc218\uc775\uc744 \uae30\ub300\ud560 \uc218 \uc788\uac8c \ub418\uba74 \uc0c8 \uad6c\ub9e4\uc790\ub294 \uae30\uc874 \ucc44\uad8c\uc744 \uc804\uacfc \uac19\uc740 \uac00\uaca9\uc5d0 \uc0ac\ub824 \ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uac19\uc740 \ub3c8\uc744 \ub0b4\uace0 \ube44\uad50\uc801 \uc801\uc740 \uae08\uc561\uc744 \ubc1b\ub294 \uc120\ud0dd\uc774 \ub418\uae30 \ub54c\ubb38\uc774\ub2e4. \uc774 \uacbd\uc6b0 \uae30\uc874 \ucc44\uad8c\uc758 \uac00\uaca9\uc774 \ub0b4\ub824\uac00\uba74 \uc774\uc57c\uae30\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uc801\uac8c \ub0b4\uace0 \uc815\ud574\uc9c4 \ub3c8\uc744 \ubc1b\uac8c \ub418\ubbc0\ub85c \uad6c\ub9e4\uc790\uc758 \uc218\uc775\ub960\uc740 \ub192\uc544\uc9c4\ub2e4. \ubc1c\ud589\uc790\uac00 \uc57d\uc18d\ud55c \uc774\uc790\ub97c \ubc14\uafb8\uc9c0 \uc54a\uc544\ub3c4 \uc0ac\uace0\ud30c\ub294 \uac00\uaca9\uc758 \ubcc0\ud654\ub85c \uc0c8 \uad6c\ub9e4\uc790\uac00 \uc5bb\ub294 \ube44\uc728\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub294 \uac83\uc774\ub2e4. \ub9cc\uae30\uac00 \uc815\ud655\ud788 1\ub144 \ub0a8\uc558\uace0, \uadf8\ub54c \uc6d0\uae08 100\ub9cc \uc6d0\uacfc \uc774\uc790 3\ub9cc \uc6d0\uc744 \ud55c \ubc88\uc5d0 \uc9c0\uae09\ud558\ub294 \uac00\uc0c1 \ucc44\uad8c\uc744 \uc0dd\uac01\ud558\uc790. \uc911\uac04 \uc9c0\uae09\uc740 \uc5c6\uc73c\uba70 \uc9c0\uae09\uc774 \ud655\uc2e4\ud558\ub2e4\uace0 \uac00\uc815\ud55c\ub2e4. \uc138\uae08\uacfc \uac70\ub798 \ube44\uc6a9\ub3c4 \uc0dd\ub7b5\ud55c\ub2e4. \ubc1b\ub294 \uae08\uc561\uc740 103\ub9cc \uc6d0\uc73c\ub85c \uace0\uc815\ub418\uc5b4 \uc788\ub2e4. \uc2dc\uc7a5\uc5d0\uc11c \uc774 \uc870\uac74\uc5d0 \uc5f0 5%\uc758 \uc218\uc775\uc744 \uc694\uad6c\ud55c\ub2e4\uba74 \uc624\ub298 \uac00\uaca9\uc740 103\ub9cc \uc6d0\uc744 1.05\ub85c \ub098\ub208 \uc57d 98\ub9cc 952\uc6d0\uc774 \ub41c\ub2e4. \uadf8 \uac00\uaca9\uc5d0 \uc0b0 \ub3c8\uc774 1\ub144 \ub4a4 5% \ub298\uba74 103\ub9cc \uc6d0\uc774 \ub418\ub294 \uacc4\uc0b0\uc774\ub2e4. \uc2e4\uc81c \ucc44\uad8c\uc758 \uc2dc\uc138\uac00 \uc544\ub2c8\ub77c \uc57d\uc18d\uacfc \uac00\uaca9\uc758 \uad00\uacc4\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc608\ub2e4. \uac19\uc740 103\ub9cc \uc6d0\uc744 \ubc1b\ub294 \uc57d\uc18d\uc5d0 \uc2dc\uc7a5\uc774 \uc5f0 2%\uc758 \uc218\uc775\ub9cc \uc694\uad6c\ud55c\ub2e4\uba74 \uc624\ub298 \uac00\uaca9\uc740 \uc57d 100\ub9cc 9,804\uc6d0\uc774 \ub41c\ub2e4. \ubc1b\ub294 \ub3c8\uc740 \uac19\uc9c0\ub9cc \uadf8 \ub3c8\uc744 \ubc1b\uae30 \uc704\ud574 \uc9c0\uae08 \ub0bc \uc758\ud5a5\uc774 \uc788\ub294 \uae08\uc561\uc740 \ub354 \ucee4\uc9c4\ub2e4. \ub0ae\uc740 \uc218\uc775\ub960\uc744 \ubc1b\uc544\ub4e4\uc77c\uc218\ub85d \uac00\uaca9\uc740 \ub192\uc544\uc9c0\ub294 \uc148\uc774\ub2e4. \uad50\uc7ac\uac00 \uc124\uba85\ud558\ub294 \uc77c\ubc18\uc801\uc778 \uc5ed\uad00\uacc4\uac00 \uc774 \uc791\uc740 \uacc4\uc0b0\uc5d0 \ub4e4\uc5b4 \uc788\ub2e4. \ub2e4\ub9cc \ub450 \uc608\uc5d0\uc11c\ub294 \ub2e4\ub978 \uc870\uac74\uc774 \uac19\ub2e4\uace0 \ub193\uc558\ub2e4. \uc2e4\uc81c \uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc2e0\uc6a9 \uc704\ud5d8\uacfc \uc9c0\uae09 \uc870\uac74, \uc0ac\uace0\ud314\uae30 \uc26c\uc6b4 \uc815\ub3c4\ub3c4 \ud568\uaed8 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uae08\ub9ac \ud558\ub098\ub9cc \ubcf4\uace0 \ubaa8\ub4e0 \uac00\uaca9 \ubcc0\ud654\ub97c \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \ucc44\uad8c\uc5d0 \uc801\ud78c \uc774\uc790\uc758 \ube44\uc728\uc740 \uc6d0\uae08\uc5d0 \ub300\ud574 \uc5bc\ub9c8\ub97c \uc9c0\uae09\ud560\uc9c0 \uc54c\ub824 \uc900\ub2e4. \ubc18\uba74 \uc9c0\uae08 \uc0ac\ub294 \uc0ac\ub78c\uc758 \uc218\uc775\ub960\uc5d0\ub294 \uc2e4\uc81c \uad6c\ub9e4 \uac00\uaca9\uacfc \uc55e\uc73c\ub85c \ubc1b\uc744 \ub3c8\uc774 \ud568\uaed8 \ub4e4\uc5b4\uac04\ub2e4. \uac19\uc740 \uc57d\uc18d\uc744 \uc11c\ub85c \ub2e4\ub978 \uac00\uaca9\uc5d0 \uc0c0\ub2e4\uba74 \uacb0\uacfc\uc758 \ube44\uc728\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc774 \uad6c\ubd84\uc744 \ub193\uce58\uba74 \uc774\uc790\ub294 3%\uc778\ub370 \uc65c \uc218\uc775\ub960\uc740 5%\ub77c\uace0 \ub9d0\ud558\ub294\uc9c0 \ud63c\ub780\uc2a4\ub7fd\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uae30\uc900\uc744 \uc0ac\uc6a9\ud558\uace0 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc55e\uc120 \uc608\uc5d0\uc11c \ubc1c\ud589\uc790\uc758 \uc9c0\uae09\uc561\uc740 \uadf8\ub300\ub85c\uc600\uace0 \uad6c\ub9e4\uc790\uc758 \ucd9c\ubc1c \uae08\uc561\uc774 \ub2ec\ub77c\uc84c\ub2e4. \uc9e7\uc740 \uae08\ub9ac \uc22b\uc790\ub97c \ubcfc \ub54c \ubb34\uc5c7\uc744 \uae30\uc900\uc73c\ub85c \ud55c \ube44\uc728\uc778\uc9c0 \ubb3c\uc5b4\ubcf4\uba74 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ucc44\uad8c\uc744 \ub9cc\uae30 \uc804\uc5d0 \ud314 \ub54c\ub294 \uadf8 \uc2dc\uc810\uc758 \uac70\ub798 \uac00\uaca9\uc774 \uc911\uc694\ud558\ub2e4. \ubc18\uba74 \ub05d\uae4c\uc9c0 \ubcf4\uc720\ud574 \uc57d\uc18d\ub300\ub85c \uc9c0\uae09\ubc1b\ub294 \uacbd\uc6b0\uc5d0\ub294 \ucc98\uc74c\uc5d0 \uc5bc\ub9c8\uc5d0 \uc0c0\uace0 \uc5b4\ub5a4 \ub3c8\uc744 \ubc1b\uc558\ub294\uc9c0\uac00 \uacb0\uacfc\ub97c \uc815\ud55c\ub2e4. \uc2dc\uc7a5 \uac00\uaca9\uc758 \ubcc0\ud654\uc640 \uc2e4\uc81c\ub85c \ub9c8\uce5c \uac70\ub798\uc758 \uc190\uc775\uc740 \uad6c\ubd84\ud574\uc11c \ubcf4\uc544\uc57c \ud55c\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub05d\uae4c\uc9c0 \ubcf4\uc720\ud558\uba74 \uc5b4\ub5a4 \uc704\ud5d8\ub3c4 \uc5c6\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ubc1c\ud589\uc790\uac00 \uc9c0\uae09\ud558\uc9c0 \ubabb\ud560 \uc704\ud5d8\uc774 \uc788\uace0 \ubb3c\uac00 \ubcc0\ud654\ub85c \uad6c\ub9e4\ub825\uc774 \ub2ec\ub77c\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \uad50\uc7ac\ub3c4 \uae08\ub9ac \uc704\ud5d8\uacfc \ucc44\ubb34 \ubd88\uc774\ud589 \uc704\ud5d8\uc744 \ub098\ub204\uc5b4 \uc124\uba85\ud55c\ub2e4. \ub9cc\uae30\ub77c\ub294 \ub0a0\uc9dc\uac00 \ubaa8\ub4e0 \ubb38\uc81c\ub97c \uc5c6\uc560 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc624\ub298 \uac19\uc740 \uae08\uc561\uc744 \uc8fc\uace0 \ub098\uc911\uc5d0 \uac19\uc740 \uae08\uc561\uc744 \ubc1b\ub294\ub2e4\uace0 \ud574\ub3c4 \uc9c0\uae09\uc758 \ud655\uc2e4\uc131\uc774 \ub2e4\ub974\uba74 \uac00\uce58\ub294 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ucc44\uad8c\uc758 \uc774\ub984\uacfc \uc774\uc790\uc728\ub9cc \ube44\uad50\ud558\uba74 \uc774\ub7f0 \uc870\uac74\uc774 \ube60\uc9c4\ub2e4. \ud22c\uc790\uc790\ub294 \uc5b4\ub290 \uc2dc\uc810\uc5d0 \ubb34\uc5c7\uc744 \ubc1b\uace0 \uc5b4\ub5a4 \uc704\ud5d8\uc744 \ubd80\ub2f4\ud558\ub294\uc9c0 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uacc4\uc57d\uacfc \ub2ec\ub825\uc744 \uc0b4\ud53c\ub294 \uc0c1\uc0c1 \uc18d \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c \ucc44\uad8c \uc99d\uc11c\ub098 \uc2dc\uc7a5 \uac00\uaca9\uc758 \ub3c4\ud45c\ub294 \uc544\ub2c8\ub2e4. \uc774\ubc88 \uae00\uc758 \ub450 \uac00\uaca9\ub3c4 \uac19\uc740 \uac00\uc815 \uc544\ub798 \uc9c1\uc811 \uacc4\uc0b0\ud55c \uac12\uc774\uba70 \ud2b9\uc815 \uc0c1\ud488\uc744 \uc0ac\uac70\ub098 \ud314 \uac00\uaca9\uc744 \uc81c\uc2dc\ud558\uc9c0 \uc54a\ub294\ub2e4. \ucc44\uad8c\uc740 \uc774\uc790\uac00 \uc815\ud574\uc84c\ub2e4\ub294 \uc774\uc720\ub85c \uc815\uc9c0\ub41c \ubb3c\uac74\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uc57d\uc18d\uc744 \uc9c0\uae08 \uc5bc\ub9c8\uc5d0 \uad50\ud658\ud560\uc9c0\ub294 \ub2e4\ub978 \uae30\ud68c\uc640 \uc704\ud5d8\uc744 \ube44\uad50\ud558\ub294 \uc2dc\uc7a5\uc5d0\uc11c \ub2ec\ub77c\uc9c4\ub2e4. \uace0\uc815\ub41c \uc9c0\uae09\uc561\uacfc \uc6c0\uc9c1\uc774\ub294 \uac00\uaca9\uc740 \ubaa8\uc21c\uc774 \uc544\ub2c8\ub77c \uc11c\ub85c \ub2e4\ub978 \uc9c8\ubb38\uc758 \ub2f5\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \uae08\ub9ac\uac00 \uc624\ub974\uace0 \ucc44\uad8c \uac12\uc774 \ub0b4\ub824\uac14\ub2e4\ub294 \ub274\uc2a4\ub97c \ub9cc\ub098\uba74 \uc0c8 \uad6c\ub9e4\uc790\uc758 \uc785\uc7a5\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uac19\uc740 \ubbf8\ub798\uc758 \ub3c8\uc744 \ubc1b\uc73c\ub824\uba74 \uc624\ub298 \uc5bc\ub9c8\ub97c \ub0b4\ub294 \uac83\uc774 \ub9de\uc744\uae4c. \uadf8 \uc9c8\ubb38 \ud558\ub098\uac00 \ucc44\uad8c\uc774\ub77c\ub294 \ub0af\uc120 \uc99d\uc11c\ub97c \uc2dc\uac04\uacfc \uac00\uaca9\uc5d0 \uad00\ud55c \uc870\uae08 \ub354 \uc775\uc219\ud55c \uc57d\uc18d\uc73c\ub85c \ubc14\uafb8\uc5b4 \uc900\ub2e4."}, {"id": "bretton-woods-1944-money-rules", "title": "\ube0c\ub808\ud134\uc6b0\uc988 1944 \u2014 \uc804\uc7c1\uc774 \ub05d\ub098\uae30 \uc804\uc5d0 \ub3c8\uc758 \uc9c8\uc11c\ub97c \uc758\ub17c\ud558\ub2e4", "summary": "1944\ub144 \ud68c\uc758\uc640 \uad6d\uc81c\uae08\uc735 \uae30\uad00, \ub2ec\ub7ec\uc640 \uae08\uc758 \uc5f0\uacb0\uc744 \ud1b5\ud574 \uc804\ud6c4 \ud1b5\ud654 \uc9c8\uc11c\uc758 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "finance", "category_title": "\ub3c8\uacfc \uae08\uc735", "subcategory": "\ub3c8\uacfc \ud654\ud3d0", "categories": ["finance"], "url": "stories/bretton-woods-1944-money-rules/index.html", "image": "../media/bretton-woods-1944-money-rules.png", "alt": "\uc0b0\uc545 \ud638\ud154\uacfc \ud68c\uc758 \ud0c1\uc790\uc758 \ub300\ud45c\ub4e4\uc744 \ud568\uaed8 \uadf8\ub9b0 \ube0c\ub808\ud134\uc6b0\uc988 \ud68c\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ube0c\ub808\ud134\uc6b0\uc988 1944 \u2014 \uc804\uc7c1\uc774 \ub05d\ub098\uae30 \uc804\uc5d0 \ub3c8\uc758 \uc9c8\uc11c\ub97c \uc758\ub17c\ud558\ub2e4 44\uac1c\uad6d \ud68c\uc758\uc640 \uad6d\uc81c\uae08\uc735 \uae30\uad00, \ub2ec\ub7ec\uc640 \uae08\uc758 \uc57d\uc18d\uc744 \ub098\ub204\uc5b4 \uc77d\uae30 1944\ub144 \ud68c\uc758\uc640 \uad6d\uc81c\uae08\uc735 \uae30\uad00, \ub2ec\ub7ec\uc640 \uae08\uc758 \uc5f0\uacb0\uc744 \ud1b5\ud574 \uc804\ud6c4 \ud1b5\ud654 \uc9c8\uc11c\uc758 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ub3c8\uacfc \ud654\ud3d0 \ub3c8\uacfc \uae08\uc735 1944\ub144 \uc5ec\ub984, \uc804\uc7c1\uc774 \uc544\uc9c1 \ub05d\ub098\uc9c0 \uc54a\uc558\ub294\ub370 \uc5ec\ub7ec \ub098\ub77c\uc758 \ub300\ud45c\ub4e4\uc774 \ubbf8\uad6d \ub274\ud584\ud504\uc154\uc758 \ube0c\ub808\ud134\uc6b0\uc988\uc5d0 \ubaa8\uc600\ub2e4. \ub2e4\uc74c \uc804\ud22c\ub9cc\uc744 \uc758\ub17c\ud55c \uc790\ub9ac\uac00 \uc544\ub2c8\uc5c8\ub2e4. \uc804\uc7c1 \ub4a4 \ubb34\uc5ed\uacfc \ub3c8\uc758 \ud750\ub984\uc744 \uc5b4\ub5bb\uac8c \uc548\uc815\uc2dc\ud0ac\uc9c0 \ub17c\uc758\ud588\ub2e4. \ud3c9\ud654\ub97c \uc900\ube44\ud558\ub294 \uc77c\uc5d0\ub294 \uacbd\uc81c\uc758 \uaddc\uce59\uc744 \ub9cc\ub4dc\ub294 \ubb38\uc81c\ub3c4 \ud3ec\ud568\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc774 \ud68c\uc758\ub294 \uad6d\uc81c\ud1b5\ud654\uae30\uae08\uacfc \uad6d\uc81c\ubd80\ud765\uac1c\ubc1c\uc740\ud589\uc758 \ucd9c\ubc1c\uc5d0 \uc5f0\uacb0\ub41c\ub2e4. \ub0af\uc120 \uae30\uad00 \uc774\ub984\uc744 \uc678\uc6b0\ub294 \ub300\uc2e0 \ub2f9\uc2dc \ubb34\uc5c7\uc744 \ubd88\uc548\ud558\uac8c \uc5ec\uacbc\uace0 \uc5b4\ub5a4 \uc57d\uc18d\uc744 \ub9cc\ub4e4\ub824 \ud588\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uba74, \uad6d\uc81c\uae08\uc735\uc758 \uc81c\ub3c4\uac00 \uc0ac\ub78c\ub4e4\uc758 \uc0dd\ud65c\uacfc \uba40\ub9ac \ub5a8\uc5b4\uc9c4 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub77c\ub294 \uc0ac\uc2e4\uc774 \ubcf4\uc778\ub2e4. \uc804\uc7c1\uc774 \uba48\ucd98\ub2e4\uace0 \uad6d\uc81c\uc801\uc778 \uac70\ub798\uac00 \uc800\uc808\ub85c \ud68c\ubcf5\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud30c\uad34\ub41c \uc0dd\uc0b0\uc2dc\uc124\uacfc \uc790\uae08\uc758 \ubd80\uc871, \uad6d\uac00 \uc0ac\uc774\uc758 \ubd88\uc2e0\uc774 \ub0a8\ub294\ub2e4. \ubb3c\uac74\uc744 \uc0ac\uace0\ud314\uace0 \ub3c8\uc744 \ubcf4\ub0b4\ub824\uba74 \uc0c1\ub300\uac00 \uc5b4\ub5a4 \uc870\uac74\uc73c\ub85c \uac12\uc744 \uacc4\uc0b0\ud558\uace0 \uacb0\uc81c\ud560\uc9c0 \uc54c\uc544\uc57c \ud55c\ub2e4. \uad70\uc0ac\uc801 \uc885\uc804\uacfc \uacbd\uc81c\uc801 \uc548\uc815\uc740 \ub2e4\ub978 \uacfc\uc81c\uc600\ub2e4. \uc804\ud6c4 \uc9c8\uc11c\ub97c \ub17c\uc758\ud55c \uc0ac\ub78c\ub4e4\uc740 \uc774 \ubb38\uc81c\ub97c \uad6d\uac00\ubcc4 \ub178\ub825\uc5d0\ub9cc \ub9e1\uaca8 \ub458 \uc218 \uc5c6\ub2e4\uace0 \ubcf4\uc558\ub2e4. \uc5ec\ub7ec \ub098\ub77c\uac00 \ud568\uaed8 \uac70\ub798\ud558\ub294\ub370 \ub3c8\uc758 \uaddc\uce59\uc774 \uacc4\uc18d \ud754\ub4e4\ub9ac\uba74 \ud55c \ub098\ub77c\uc758 \ud68c\ubcf5\ub3c4 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4. \uad6d\uc81c\uc801\uc778 \uc81c\ub3c4\uac00 \ud544\uc694\ud558\ub2e4\ub294 \uc0dd\uac01\uc740 \uc774\ub7f0 \uc0c1\ud638 \uc758\uc874\uc758 \ud604\uc2e4\uc5d0\uc11c \ud798\uc744 \uc5bb\uc5c8\ub2e4. \ube0c\ub808\ud134\uc6b0\uc988 \ud68c\uc758\uc5d0\ub294 44\uac1c \uc5f0\ud569\uad6d\uc758 \ub300\ud45c\uac00 \ucc38\uc5ec\ud588\ub2e4. \uadf8\ub4e4\uc774 \uc804 \uc138\uacc4 \uc0ac\ub78c\uc758 \uc774\ud574\ub97c \ub611\uac19\uc774 \ub300\ud45c\ud55c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc804\uc7c1 \uc911\uc758 \uc138\ub825 \uad00\uacc4\uc640 \uac01\uad6d\uc758 \uacbd\uc81c\uc801 \uc704\uce58\uac00 \ub17c\uc758\uc758 \uc870\uac74\uc774\uc5c8\ub2e4. \ub9ce\uc740 \ub098\ub77c\uac00 \ubaa8\uc600\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ubaa8\ub450\uac00 \uac19\uc740 \uc601\ud5a5\ub825\uc744 \uac00\uc84c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \uadf8\ub798\ub3c4 \uc911\uc694\ud55c \ubcc0\ud654\ub294 \uad6d\uac00 \uc0ac\uc774\uc758 \ub3c8 \ubb38\uc81c\ub97c \uc9c0\uc18d\uc801\uc778 \ud611\ub825\uc758 \ud2c0\ub85c \ub2e4\ub8e8\ub824 \ud588\ub2e4\ub294 \uc810\uc774\ub2e4. \ud68c\uc758 \ud55c \ubc88\uc758 \uacf5\ub3d9\uc120\uc5b8\ubcf4\ub2e4 \uc624\ub798 \uc791\ub3d9\ud560 \uc870\uc9c1\uacfc \uc57d\uc18d\uc744 \uad6c\uc0c1\ud588\ub2e4. \uad6d\uc81c\uc801\uc778 \uc548\uc815\uc774\ub77c\ub294 \ubaa9\ud45c\uac00 \ud589\uc815\uacfc \uc790\uae08\uc758 \uccb4\uacc4\ub97c \uac00\uc9c4 \uae30\uad00\uc73c\ub85c \uc62e\uaca8 \uac00\ub294 \uacfc\uc815\uc774\uc5c8\ub2e4. \ud658\uc728\uc740 \uc11c\ub85c \ub2e4\ub978 \ud1b5\ud654\uc758 \uad50\ud658 \ube44\uc728\uc774\ub2e4. \ud574\uc678\uc5d0\uc11c \ubb3c\uac74\uc744 \uc0ac\uace0 \uac12\uc744 \ub098\uc911\uc5d0 \uce58\ub974\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uadf8 \ube44\uc728\uc758 \ubcc0\ud654\uac00 \uc2e4\uc81c \ube44\uc6a9\uc774 \ub41c\ub2e4. \uacc4\uc57d\ud560 \ub54c \uc608\uc0c1\ud55c \uae08\uc561\uacfc \uacb0\uc81c\ud560 \ub54c \ud544\uc694\ud55c \uae08\uc561\uc774 \ud06c\uac8c \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uad6d\uc81c\ubb34\uc5ed\uc5d0\uc11c\ub294 \uc0c1\ud488\uc758 \uac00\uaca9\ubfd0 \uc544\ub2c8\ub77c \ub3c8\uc744 \ubc14\uafb8\ub294 \uc870\uac74\ub3c4 \uc911\uc694\ud558\ub2e4. \ud658\uc728\uc744 \uc77c\uc815\ud55c \uc218\uc900\uc5d0 \uc5f0\uacb0\ud558\ub824\ub294 \uc81c\ub3c4\ub294 \uc774\ub7f0 \ubd88\ud655\uc2e4\uc131\uc744 \uc904\uc774\ub824 \ud55c\ub2e4. \ud558\uc9c0\ub9cc \uc120\uc5b8\ub9cc\uc73c\ub85c \ube44\uc728\uc774 \uc720\uc9c0\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc2e4\uc81c \uc2dc\uc7a5\uc758 \uc218\uc694\uc640 \uc790\uae08 \uc774\ub3d9\uc5d0 \ub300\uc751\ud560 \ub2a5\ub825\uc774 \ud544\uc694\ud558\ub2e4. \uace0\uc815\ub41c \uc57d\uc18d\uc744 \ub9cc\ub4e4\uc218\ub85d \uadf8 \uc57d\uc18d\uc744 \uc9c0\ud0a4\ub294 \ubd80\ub2f4\ub3c4 \uc81c\ub3c4\uc758 \uc77c\ubd80\uac00 \ub41c\ub2e4. \ube0c\ub808\ud134\uc6b0\uc988 \uccb4\uc81c\uc5d0\uc11c\ub294 \ub2ec\ub7ec\uac00 \uae08\uacfc \uc5f0\uacb0\ub418\uace0 \ub2e4\ub978 \ud1b5\ud654\uc758 \ud658\uc728\uc744 \uc815\ud558\ub294 \uc911\uc2ec\uc774 \ub418\uc5c8\ub2e4. \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uc77c\uc0c1\uc5d0\uc11c \uc9c0\ud3d0\ub97c \uae08\uc73c\ub85c \ubc14\uafb8\ub294 \ub2e8\uc21c\ud55c \uc81c\ub3c4\ub77c\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uad6d\uac00 \uc0ac\uc774\uc758 \ud1b5\ud654 \uc9c8\uc11c\uc640 \uad6d\uc81c\uc801\uc778 \uacb0\uc81c\uc5d0\uc11c \uc791\ub3d9\ud558\ub294 \uc57d\uc18d\uc774\uc5c8\ub2e4. \uacf5\ud1b5\uc758 \uc911\uc2ec\uc774 \uc788\uc73c\uba74 \uc11c\ub85c \ub2e4\ub978 \ub3c8\uc758 \uad00\uacc4\ub97c \uc815\ud558\uae30 \uc26c\uc6cc\uc9c4\ub2e4. \ub3d9\uc2dc\uc5d0 \uadf8 \uc911\uc2ec \ud1b5\ud654\ub97c \ubc1c\ud589\ud558\ub294 \ub098\ub77c\uc758 \uc0c1\ud0dc\uac00 \ub2e4\ub978 \ub098\ub77c\uc5d0\ub3c4 \uc911\uc694\ud574\uc9c4\ub2e4. \ud558\ub098\uc758 \uad6d\uac00\uac00 \uc6b4\uc601\ud558\ub294 \ud1b5\ud654\uac00 \uad6d\uc81c\uc801\uc778 \uc5ed\ud560\uc744 \ub9e1\uc744 \ub54c \uc0dd\uae30\ub294 \uc774\uc911\uc758 \uc131\uaca9\uc774\ub2e4. \uad6d\ub0b4\uc758 \ud544\uc694\uc640 \uc138\uacc4\uc758 \uae30\ub300\uac00 \uc5b8\uc81c\ub098 \uac19\uc740 \ubc29\ud5a5\uc77c \uc218\ub294 \uc5c6\ub2e4. \ud68c\uc758\ub294 \uad6d\uc81c\ud1b5\ud654\uae30\uae08\uacfc \uad6d\uc81c\ubd80\ud765\uac1c\ubc1c\uc740\ud589\uc758 \uc124\ub9bd\uc73c\ub85c \uc774\uc5b4\uc84c\ub2e4. \ub450 \uae30\uad00\uc740 \uc804\ud6c4 \uacbd\uc81c\uc758 \uc548\uc815\uacfc \ud68c\ubcf5\uc744 \uc704\ud55c \uccb4\uacc4\ub77c\ub294 \uacf5\ud1b5\ub41c \ubaa9\uc801 \uc548\uc5d0 \uc788\uc5c8\ub2e4. \uad6d\uc81c\ubd80\ud765\uac1c\ubc1c\uc740\ud589\uc774\ub77c\ub294 \uc774\ub984\uc5d0\ub294 \uc7ac\uac74\uacfc \uac1c\ubc1c\uc774\ub77c\ub294 \ub2f9\uc2dc\uc758 \uacfc\uc81c\uac00 \uc9c1\uc811 \ub4e4\uc5b4 \uc788\ub2e4. \uae30\uad00\uc758 \uc774\ub984\ub3c4 \uc2dc\ub300\uc758 \ud544\uc694\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc790\ub8cc\ub2e4. \uc774\ub4e4\uc744 \ud558\ub098\uc758 \uc138\uacc4 \uc815\ubd80\ub098 \ubaa8\ub4e0 \uacbd\uc81c \ubb38\uc81c\ub97c \ud574\uacb0\ud560 \uae08\uace0\ucc98\ub7fc \uc0c1\uc0c1\ud558\uba74 \uc5ed\ud560\uc744 \uacfc\uc7a5\ud558\uac8c \ub41c\ub2e4. \ud68c\uc6d0\uad6d\uc774 \ucc38\uc5ec\ud558\ub294 \uc81c\ub3c4\uc774\uba70 \uac01\uad6d\uc758 \uc815\ucc45\uacfc \uc774\ud574\uad00\uacc4 \uc18d\uc5d0\uc11c \uc6c0\uc9c1\uc778\ub2e4. \uc870\uc9c1\uc744 \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ubb38\uc81c\uac00 \ub05d\ub0ac\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub77c \uadf8 \ubb38\uc81c\ub97c \uacc4\uc18d \ub2e4\ub8f0 \ud2c0\uc744 \ub9c8\ub828\ud588\ub2e4\ub294 \ub73b\uc5d0 \uac00\uae5d\ub2e4. \uc804\ud6c4 \uacbd\uc81c\uac00 \uc131\uc7a5\ud558\uace0 \uad6d\uc81c\uc801\uc778 \uac70\ub798\uac00 \ub298\uba74\uc11c \ub2ec\ub7ec\uc640 \uae08\uc758 \uad00\uacc4\ub97c \uc720\uc9c0\ud558\ub294 \uc870\uac74\ub3c4 \ub2ec\ub77c\uc84c\ub2e4. \uc678\uad6d\uc774 \ubcf4\uc720\ud55c \ub2ec\ub7ec\uc640 \ubbf8\uad6d\uc758 \uae08 \ubcf4\uc720 \uc0ac\uc774\uc758 \uae34\uc7a5\uc740 \uae30\uc874 \uccb4\uacc4\uc758 \ubb38\uc81c\ub85c \ub4dc\ub7ec\ub0ac\ub2e4. 1971\ub144 \ubbf8\uad6d\uc758 \uae08 \ud0dc\ud658 \uc911\ub2e8\uc740 \uc911\uc694\ud55c \uc804\ud658\uc810\uc774 \ub418\uc5c8\ub2e4. \uc774 \ubcc0\ud654\ub294 \ud68c\uc758\uc5d0\uc11c \ub9cc\ub4e0 \uc57d\uc18d\uc774 \uc601\uc6d0\ud55c \uc790\uc5f0\ubc95\uce59\uc774 \uc544\ub2c8\ub77c\ub294 \uc0ac\uc2e4\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc81c\ub3c4\ub97c \ub9cc\ub4e4\uc5c8\uc744 \ub54c\uc758 \ubaa9\ud45c\uc640 \uc2dc\uac04\uc774 \ud750\ub978 \ub4a4\uc758 \uacbd\uc81c \uaddc\ubaa8\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ucc98\uc74c\uc758 \uc124\uacc4\uac00 \uc65c \ud544\uc694\ud588\ub294\uc9c0 \uc774\ud574\ud558\ub294 \uc77c\uacfc \uadf8\uac83\uc774 \uc5b4\ub5a4 \uc870\uac74\uc5d0\uc11c \uc5b4\ub824\uc6cc\uc84c\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\ub294 \uc77c\uc774 \ud568\uaed8 \ud544\uc694\ud558\ub2e4. \ucd08\uae30\uc758 \ud1b5\ud654 \uc9c8\uc11c\uac00 \ubcc0\ud588\ub2e4\uace0 \ud68c\uc758\uc5d0\uc11c \ucd9c\ubc1c\ud55c \uae30\uad00\uacfc \ubaa8\ub4e0 \ud611\ub825\uc758 \ud2c0\uc774 \ud568\uaed8 \uc0ac\ub77c\uc9c4 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud2b9\uc815\ud55c \ud658\uc728\uc758 \uc57d\uc18d\uacfc \uad6d\uc81c\uc801\uc778 \uc870\uc9c1\uc740 \uc11c\ub85c \uad00\ub828\ub418\uc9c0\ub9cc \uac19\uc740 \ubb3c\uac74\uc740 \uc544\ub2c8\ub2e4. \uc81c\ub3c4\uc758 \uc5b4\ub5a4 \ubd80\ubd84\uc774 \ub05d\ub0ac\uace0 \uc5b4\ub5a4 \ubd80\ubd84\uc774 \ubcc0\ud558\uba70 \uc774\uc5b4\uc84c\ub294\uc9c0 \ub098\ub204\uc5b4 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc548\uc815\uc801\uc778 \ud658\uc728\uc744 \ubc14\ub77c\uba74\uc11c\ub3c4 \uad6d\ub0b4\uc758 \uacbd\uc81c \uc0ac\uc815\uc5d0 \ub300\uc751\ud574\uc57c \ud55c\ub2e4\ub294 \uc5b4\ub824\uc6c0\uc740 \ub0a8\ub294\ub2e4. \uc81c\ub3c4\ub97c \uc9c0\ud0a4\ub294 \ube44\uc6a9\uacfc \uadf8 \uc81c\ub3c4\uac00 \uc8fc\ub294 \uc608\uce21 \uac00\ub2a5\uc131\uc744 \ud568\uaed8 \ub530\uc838\uc57c \ud55c\ub2e4. \ud1b5\ud654\uc758 \uc57d\uc18d\uc740 \uc22b\uc790\ub97c \uc815\ud558\ub294 \uae30\uc220\uc778 \ub3d9\uc2dc\uc5d0 \uc11c\ub85c \ub2e4\ub978 \uc815\ucc45 \ubaa9\ud45c\ub97c \uc870\uc815\ud558\ub294 \uc120\ud0dd\uc774\uae30\ub3c4 \ud558\ub2e4. \ube0c\ub808\ud134\uc6b0\uc988\ub294 \ub3c8\uc758 \uc548\uc815\uc774 \uad6d\uac00 \uc548\uc5d0\uc11c\ub9cc \ud574\uacb0\ub418\ub294 \ubb38\uc81c\uac00 \uc544\ub2c8\ub77c\ub294 \uc0dd\uac01\uc744 \uc81c\ub3c4\ub85c \ub9cc\ub4e0 \uc0ac\uac74\uc774\uc5c8\ub2e4. \uc624\ub298\uc758 \ud658\uc728 \ub274\uc2a4\ub97c \ubcfc \ub54c\uc5d0\ub3c4 \uadf8 \ubc30\uacbd\uc5d0\ub294 \uc624\ub79c \ud611\uc0c1\uc758 \uc2dc\uac04\uc774 \uc788\ub2e4. \uc5ec\ub7ec \ud1b5\ud654\uac00 \ub9cc\ub098\ub294 \uc790\ub9ac\uc5d0\ub294 \uacc4\uc0b0\uc758 \ube44\uc728\ubfd0 \uc544\ub2c8\ub77c \uadf8 \ube44\uc728\uc744 \uc5b4\ub5a4 \uc57d\uc18d\uc73c\ub85c \ub2e4\ub8f0\uc9c0\uc5d0 \ub300\ud55c \uc5ed\uc0ac\uac00 \ub193\uc5ec \uc788\ub2e4."}, {"id": "clearing-house-cheques-and-net-balances", "title": "\uc218\ud45c \uccad\uc0b0\uc18c \u2014 \ud604\uae08\uc744 \uc62e\uae30\uc9c0 \uc54a\uace0 \ube5a\uc744 \ub9de\ucd94\ub294 \ubc29\ubc95", "summary": "\uc218\ud45c\uc758 \uc9c0\uae09\uc744 \ubaa8\uc544 \ucc28\uc774\ub97c \uacc4\uc0b0\ud558\ub294 \ubc29\uc2dd\uacfc \uc2e0\ub8b0\uac00 \ud754\ub4e4\ub9b4 \ub54c \ucee4\uc9c0\ub294 \ud604\uae08 \uc218\uc694\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "finance", "category_title": "\ub3c8\uacfc \uae08\uc735", "subcategory": "\uae08\uc735\uacfc \uae30\uc220", "categories": ["finance"], "url": "stories/clearing-house-cheques-and-net-balances/index.html", "image": "../media/clearing-house-cheques-and-net-balances.png", "alt": "\uc7a5\ubd80\uc640 \uc218\ud45c \ubb36\uc74c\uc744 \ub300\uc870\ud558\ub294 19\uc138\uae30 \uccad\uc0b0 \uc5c5\ubb34\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uc218\ud45c \uccad\uc0b0\uc18c \u2014 \ud604\uae08\uc744 \uc62e\uae30\uc9c0 \uc54a\uace0 \ube5a\uc744 \ub9de\ucd94\ub294 \ubc29\ubc95 19\uc138\uae30 \ub7f0\ub358\uc758 \uc218\ud45c\u00b7\ucc28\uc561 \uacc4\uc0b0\u00b7\ucd5c\uc885 \uc9c0\uae09\uacfc \uc2e0\ub8b0 \uc218\ud45c\uc758 \uc9c0\uae09\uc744 \ubaa8\uc544 \ucc28\uc774\ub97c \uacc4\uc0b0\ud558\ub294 \ubc29\uc2dd\uacfc \uc2e0\ub8b0\uac00 \ud754\ub4e4\ub9b4 \ub54c \ucee4\uc9c0\ub294 \ud604\uae08 \uc218\uc694\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uae08\uc735\uacfc \uae30\uc220 \ub3c8\uacfc \uae08\uc735 \uc11c\ub85c\uc5d0\uac8c \ub3c8\uc744 \uc904 \uc77c\uc774 \ub9ce\uc740 \uc740\ud589\ub4e4\uc774 \ub9e4\ubc88 \ud604\uae08\uc744 \ub4e4\uace0 \ucc3e\uc544\uac04\ub2e4\uba74 \uc77c\uc774 \ucee4\uc9c4\ub2e4. \ub204\uac00 \ub204\uad6c\uc5d0\uac8c \uc5bc\ub9c8\ub97c \uc9c0\uae09\ud574\uc57c \ud558\ub294\uc9c0 \uba3c\uc800 \ub9de\ucd94\uace0 \ucc28\uc774\ub9cc \uc815\uc0b0\ud560 \uc218\ub294 \uc5c6\uc744\uae4c. 19\uc138\uae30 \ub7f0\ub358\uc758 \uc218\ud45c \uccad\uc0b0\uc744 \uc124\uba85\ud55c \uc6d4\ud130 \ubc30\uc800\ud2b8\uc758 \u300e\ub86c\ubc14\ub4dc \uc2a4\ud2b8\ub9ac\ud2b8\u300f\ub294 \ub3c8\uc774 \uc6c0\uc9c1\uc774\ub294 \ubc29\uc2dd\uacfc \uc2e0\ub8b0\uc758 \uad00\uacc4\ub97c \ubcf4\uc5ec \uc900\ub2e4. \uc218\ud45c\ub294 \uc9c0\uae09\uc758 \uc9c0\uc2dc\ub97c \ub2f4\uc740 \ubb38\uc11c\ub2e4. \ubc1b\ub294 \uc0ac\ub78c\uc740 \uc790\uae30 \uc740\ud589\uc5d0 \ub123\uace0, \uadf8 \uc740\ud589\uc740 \uc218\ud45c\uac00 \ubc1c\ud589\ub41c \uc740\ud589\uacfc \uc9c0\uae09\uc744 \ub9de\ucd98\ub2e4. \uc885\uc774 \ud55c \uc7a5\uc744 \uc8fc\uace0\ubc1b\ub294 \uc26c\uc6b4 \uc7a5\uba74 \ub4a4\uc5d0 \uc5ec\ub7ec \uae30\uad00\uc758 \ucc98\ub9ac \uacfc\uc815\uc774 \uc788\ub2e4. \uc885\uc774 \uc790\uccb4\uac00 \ubaa8\ub4e0 \uc0ac\ub78c\uc5d0\uac8c \ud1b5\uc6a9\ub418\ub294 \ud604\uae08\uacfc \uac19\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc30\uc800\ud2b8\ub294 \uac70\ub798 \uc0c1\ub300\uc758 \uc218\ud45c\ub97c \uc790\uae30 \uc740\ud589\uc5d0 \ub9e1\uae30\ub294 \uc77c\uc0c1\uc801\uc778 \ud750\ub984\uc744 \uc124\uba85\ud55c\ub2e4. \ub3c8\uc744 \ubc1b\uc744 \uc0ac\ub78c\uacfc \uc9c0\uae09\ud560 \uc0ac\ub78c\uc740 \uc9c1\uc811 \ub9cc\ub098\uc9c0\ub9cc \uc740\ud589 \uc0ac\uc774\uc758 \uacc4\uc0b0\uc740 \ub4a4\uc5d0\uc11c \uc774\uc5b4\uc9c4\ub2e4. \uace0\uac1d\uc758 \uac70\ub798\uc640 \uc740\ud589\uc758 \uac70\ub798\ub294 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc73c\uba74\uc11c \ub2e4\ub978 \uce35\uc5d0 \ub193\uc5ec \uc788\uc5c8\ub2e4. \uac00\ub839 \uac11 \uc740\ud589\uc774 \uc744 \uc740\ud589\uc5d0 100\uc744 \uc9c0\uae09\ud574\uc57c \ud558\uace0 \uc744 \uc740\ud589\uc740 \uac11 \uc740\ud589\uc5d0 80\uc744 \uc9c0\uae09\ud574\uc57c \ud55c\ub2e4\uace0 \ud574 \ubcf4\uc790. \ub450 \ubc29\ud5a5\uc758 \uc694\uad6c\ub97c \ud568\uaed8 \ubcf4\uba74 \ub0a8\ub294 \ucc28\uc774\ub294 20\uc774\ub2e4. \ub2e8\uc21c\ud654\ud55c \uc608\uc9c0\ub9cc \uccad\uc0b0\uc774 \ubb34\uc5c7\uc744 \uc904\uc774\ub294\uc9c0 \ubcf4\uc5ec \uc900\ub2e4. \uc5ec\ub7ec \uc740\ud589\uc774 \ucc38\uc5ec\ud558\uba74 \uac01\uc790\uc758 \uc8fc\uace0\ubc1b\uc744 \uae08\uc561\uc744 \ub354 \ub113\uac8c \ub9de\ucd9c \uc218 \uc788\ub2e4. \uace0\uac1d\uc774 \ud55c \uac70\ub798\uc529 \ub530\ub85c \uc9c0\uae09\ud558\ub294 \ubaa8\uc2b5\uacfc \uc740\ud589\ub4e4\uc774 \ud558\ub8e8\uc758 \uacb0\uacfc\ub97c \ubaa8\uc544 \uacc4\uc0b0\ud558\ub294 \ubaa8\uc2b5\uc740 \ub2e4\ub974\ub2e4. \uac70\ub798\uac00 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uac70\ub798\uc5d0\uc11c \uc0dd\uae34 \uc758\ubb34\ub97c \uc815\ub9ac\ud558\ub294 \ubc29\uc2dd\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ubb34\uc5c7\uc744 \uc5bc\ub9c8\ub098 \uc9c0\uae09\ud560\uc9c0 \uacc4\uc0b0\ud558\ub294 \uc77c\uacfc \uc2e4\uc81c \uc9c0\uae09\uc744 \ub9c8\uce58\ub294 \uc77c\uc740 \uad6c\ubd84\ud560 \uc218 \uc788\ub2e4. \ubc30\uc800\ud2b8\ub294 \uccad\uc0b0 \uacb0\uacfc\uc758 \uc794\uc561\uc774 \uc789\uae00\ub79c\ub4dc\uc740\ud589\uc758 \uc740\ud589\ubcc4 \uacc4\uc815 \uc0ac\uc774 \uc774\uc804\uc73c\ub85c \ucc98\ub9ac\ub418\ub294 \ubaa8\uc2b5\uc744 \uc124\uba85\ud55c\ub2e4. \ubaa8\ub4e0 \uc218\ud45c \uae08\uc561\ub9cc\ud07c \ud604\ucc30\uc774 \uae38\uc744 \uac74\ub108\ub2e4\ub2d0 \ud544\uc694\uac00 \uc904\uc5b4\ub4e0\ub2e4. \uc774 \uc124\uba85\uc744 \uc624\ub298 \ubaa8\ub4e0 \uacb0\uc81c \uc2dc\uc2a4\ud15c\uc758 \uc138\ubd80 \uaddc\uce59\uacfc \uac19\ub2e4\uace0 \ubcf4\uba74 \uc548 \ub41c\ub2e4. \ucc38\uc5ec\uc790\uc640 \uc2dc\uc810, \ubc95\uc801 \uc870\uac74\uc740 \uc2dc\uc2a4\ud15c\ub9c8\ub2e4 \ub2e4\ub974\ub2e4. \uc5ec\uae30\uc11c \uc911\uc694\ud55c \uac83\uc740 \uacc4\uc0b0\uc744 \ub9de\ucd94\ub294 \uae30\ub2a5\uacfc \uacb0\uc81c \uc790\uc0b0\uc744 \uc774\uc804\ud558\ub294 \uae30\ub2a5\uc774 \uc5f0\uacb0\ub41c\ub2e4\ub294 \uae30\ubcf8 \uad6c\uc870\ub2e4. \ub450 \uc740\ud589\uc758 \uc608\uc5d0\uc11c \uc11c\ub85c \uc9c0\uae09\ud560 100\uacfc 80\uc774 \uc5c6\uc5b4\uc84c\ub2e4\uace0 \ub9d0\ud558\uba74 \ubd80\uc815\ud655\ud558\ub2e4. \uac01\uac01\uc758 \uac70\ub798\ub294 \uc874\uc7ac\ud558\uace0 \uadf8 \uacb0\uacfc\ub97c \uc815\ub9ac\ud55c \uc21c\uc9c0\uae09 \uc758\ubb34\uac00 20\uc774 \ub418\ub294 \uac83\uc774\ub2e4. \uccad\uc0b0\uc740 \uacc4\uc0b0\uc5d0\uc11c \uc0dd\ub7b5\ud574\ub3c4 \ub418\ub294 \uae30\uc5b5\uc744 \ub9cc\ub4dc\ub294 \uc77c\uc774 \uc544\ub2c8\ub77c \ub9ce\uc740 \uc694\uad6c\ub97c \uac80\uc99d\ud558\uace0 \ub9de\ucd94\ub294 \uc77c\uc774\ub2e4. \uc774 \ub54c\ubb38\uc5d0 \ub204\uac00 \uc5b4\ub290 \ubb38\uc11c\ub97c \uc81c\ucd9c\ud588\ub294\uc9c0, \uacc4\uc0b0\uc5d0 \ucc28\uc774\uac00 \uc788\uc744 \ub54c \ubb34\uc5c7\uc744 \ud655\uc778\ud560\uc9c0\ub3c4 \uc911\uc694\ud574\uc9c4\ub2e4. \ub0a8\uc740 \uae08\uc561\uc774 \uc791\uc544 \ubcf4\uc5ec\ub3c4 \uadf8 \ub4a4\uc758 \uac70\ub798\ub7c9\uacfc \ud655\uc778 \uc5c5\ubb34\uac00 \uc791\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud6a8\uc728\uc801\uc778 \uacb0\uacfc\ub294 \uc815\ud655\ud55c \uae30\ub85d\uc744 \uc804\uc81c\ub85c \ud55c\ub2e4. \uace0\uac1d\uc774 \uc740\ud589\uc5d0 \uc885\uc774 \ud55c \uc7a5\uc744 \ub9e1\uae30\ub294 \uc7a5\uba74\uacfc \uae30\uad00\ub4e4\uc774 \uc790\ub8cc\ub97c \ub9de\ucd94\ub294 \uc791\uc5c5\uc744 \ud568\uaed8 \uc0dd\uac01\ud558\uba74, \uae08\uc735\uc758 \uc18d\ub3c4\uac00 \uc0ac\ubb34\uc640 \uae30\ub85d\uc758 \uc5ed\uc0ac\uc774\uae30\ub3c4 \ud588\uc74c\uc744 \uc54c \uc218 \uc788\ub2e4. \uc11c\ub85c\uc758 \uc9c0\uae09\uc744 \ub9de\ucd94\ub294 \uccb4\uacc4\uac00 \uc791\ub3d9\ud558\uba74 \ud070 \uac70\ub798\ub7c9\uc5d0 \ube44\ud574 \ud544\uc694\ud55c \ud604\uae08\uc758 \uaddc\ubaa8\ub97c \uc904\uc77c \uc218 \uc788\ub2e4. \uc774\ub294 \ub3c8\uc774 \ubb34\uc5d0\uc11c \uc0dd\uaca8\ub0ac\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \ub9e4\ubc88 \ucd1d\uc561\uc744 \uc6b4\ubc18\ud558\ub294 \ub300\uc2e0 \uc11c\ub85c\uc758 \uc758\ubb34\ub97c \ud568\uaed8 \uacc4\uc0b0\ud558\uace0 \ucc28\uc774\ub97c \ucc98\ub9ac\ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \ud6a8\uc728\uc740 \uae30\uad00\ub4e4\uc758 \uc5f0\uacb0\uc5d0\uc11c \ub098\uc628\ub2e4. \uc5b4\ub290 \ud55c \uc740\ud589\uc758 \uae08\uace0\ub9cc \uc0b4\ud3b4\ubcf4\uba74 \uadf8 \uc740\ud589\uc774 \ucc98\ub9ac\ud558\ub294 \uc804\uccb4 \uac70\ub798\ub97c \uc774\ud574\ud558\uae30 \uc5b4\ub835\ub2e4. \ub2e4\ub978 \uc740\ud589\uacfc \uc5b4\ub5bb\uac8c \uc9c0\uae09\uc744 \ub9de\ucd94\uace0 \uc5b4\ub514\uc5d0 \uc794\uc561\uc744 \ub450\ub294\uc9c0 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc740\ud589\uc758 \ub2a5\ub825\uc5d0\ub294 \ubc14\uae65\uc758 \uc2dc\uc2a4\ud15c\ub3c4 \ud3ec\ud568\ub418\uc5b4 \uc788\uc5c8\ub2e4. \ubc30\uc800\ud2b8\ub294 \uacf5\ud669\uc774 \uc774 \uc815\uad50\ud55c \uad6c\uc870\ub97c \ud754\ub4e4 \uc218 \uc788\ub2e4\uace0 \uc9c0\uc801\ud55c\ub2e4. \ud3c9\uc18c\ub77c\uba74 \uc218\ud45c\ub97c \ubc1b\uc558\uc744 \uc0ac\ub78c\uc774 \ubd88\uc548\ud574\uc838 \uc9c0\ud3d0\ub97c \uc694\uad6c\ud558\uba74, \uc9c0\uae09\uc790\ub294 \uc740\ud589\uc5d0\uc11c \ud604\uae08\uc744 \ucc3e\uc544\uc57c \ud55c\ub2e4. \uac19\uc740 \uac70\ub798\ub77c\ub3c4 \uc5b4\ub5a4 \ud615\ud0dc\uc758 \ub3c8\uc744 \uc694\uad6c\ud558\ub294\uc9c0\uc5d0 \ub530\ub77c \uc740\ud589\uc758 \ubd80\ub2f4\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ub9ce\uc740 \uc0ac\ub78c\uc774 \ub3d9\uc2dc\uc5d0 \ubc29\uc2dd\uc744 \ubc14\uafb8\uba74 \ud3c9\uc18c\uc5d0\ub294 \uc808\uc57d\ub418\ub358 \ud604\uae08 \uc218\uc694\uac00 \ucee4\uc9c4\ub2e4. \ubb38\uc81c\ub294 \uac70\ub798\uac00 \ub298\uc5c8\uae30 \ub54c\ubb38\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uac70\ub798\ub97c \ub9c8\uce58\ub294 \uad00\uc2b5\uc774 \ubc14\ub010 \uac83\uc774\ub2e4. \uacb0\uc81c\uc758 \uc2e0\ub8b0\uac00 \ud754\ub4e4\ub9b4 \ub54c \uc720\ub3d9\uc131\uc758 \ud544\uc694\uac00 \uc65c \uac11\uc790\uae30 \ucee4\uc9c8 \uc218 \uc788\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \uc7a5\uba74\uc774\ub2e4. \uccad\uc0b0\uc18c\ub294 \uac01 \uc740\ud589\uc774 \ub2e4\ub978 \uc740\ud589\uacfc\uc758 \uac70\ub798\ub97c \ub9e4\ubc88 \uac1c\ubcc4\uc801\uc73c\ub85c \ud574\uacb0\ud558\ub294 \ubd80\ub2f4\uc744 \uc904\uc778\ub2e4. \ub3d9\uc2dc\uc5d0 \uacf5\ud1b5\uc758 \uccb4\uacc4\uac00 \uba48\ucd94\uba74 \ub9ce\uc740 \ucc38\uc5ec\uc790\uc5d0\uac8c \uc601\ud5a5\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ud3b8\ub9ac\ud568\uacfc \uc758\uc874\uc740 \uac19\uc740 \uad6c\uc870\uc758 \ub2e4\ub978 \uba74\uc774\ub2e4. \uc774\ub97c \uc5f0\uacb0\uc774 \ub9ce\uc73c\ub2c8 \uc704\ud5d8\ud558\ub2e4\ub294 \ud55c\ub9c8\ub514\ub85c \ub9c8\ubb34\ub9ac\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5b4\ub5a4 \uc870\uac74\uc5d0\uc11c \uacc4\uc18d \uc791\ub3d9\ud558\ub294\uc9c0, \ubb38\uc81c\uac00 \uc0dd\uae30\uba74 \uc9c0\uae09\uc744 \uc5b4\ub5bb\uac8c \uc774\uc5b4 \uac08\uc9c0 \uc900\ube44\ud558\ub294 \uc77c\uc774 \uc911\uc694\ud574\uc9c4\ub2e4. \ubc30\uc800\ud2b8\uc758 \uc124\uba85\uc740 \uc740\ud589 \ud55c \uacf3\uc758 \uac74\uc804\uc131\uacfc \uacb0\uc81c\ub9dd\uc758 \uc791\ub3d9\uc744 \ud568\uaed8 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uae08\uc735\uc0ac\ub97c \ub3d9\uc804\uacfc \uc9c0\ud3d0\uc758 \ubaa8\uc591\ub9cc\uc73c\ub85c \ubcf4\uba74 \uc911\uc694\ud55c \ubcc0\ud654\uac00 \ube60\uc9c4\ub2e4. \ub204\uac00 \ub204\uad6c\uc5d0\uac8c \uc9c0\uae09\ud560\uc9c0 \uacc4\uc0b0\ud558\uace0, \uadf8 \uacc4\uc0b0\uc744 \uc5b4\ub5a4 \uc790\uc0b0\uc73c\ub85c \ub9c8\uce58\ub294\uc9c0\ub3c4 \ub3c8\uc744 \uc0ac\uc6a9\ud558\ub294 \ubc29\uc2dd\uc758 \uc5ed\uc0ac\ub2e4. \uccad\uc0b0\uc18c\ub294 \uadf8 \ucc28\uc774\ub97c \ubcf4\uae30 \uc88b\uc740 \uc0ac\ub840\ub2e4. \uc624\ub298 \ud654\uba74\uc758 \uc794\uc561\uc774 \ubc14\ub00c\ub294 \ubaa8\uc2b5\uc744 \uc774\ud574\ud560 \ub54c\uc5d0\ub3c4 \ubaa8\ub4e0 \ub3c8\uc774 \ub9e4\ubc88 \ubb3c\ub9ac\uc801\uc73c\ub85c \uc62e\uaca8\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc774 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ub2e4\ub9cc \ud654\uba74\uc758 \uac04\ub2e8\ud568 \ub4a4\uc5d0\ub294 \uae30\uad00 \uc0ac\uc774\uc758 \uc57d\uc18d\uacfc \uc6b4\uc601\uc774 \uc788\ub2e4. \uc22b\uc790\ub97c \ub9de\ucd94\ub294 \uc815\ud655\ud568\uc774 \ud070 \uae08\uc561\uc758 \uc774\ub3d9\uc744 \uc904\uc77c \uc218 \uc788\uc5c8\ub2e4. \uc218\ud45c \uccad\uc0b0\uc758 \uc5ed\uc0ac\ub294 \ub3c8\uc744 \ube60\ub974\uac8c \uc6c0\uc9c1\uc778 \uac83\uc774 \ub54c\ub85c \uc6b4\uc1a1 \uc218\ub2e8\uc774 \uc544\ub2c8\ub77c \uacc4\uc0b0\uc758 \uc9c8\uc11c\uc600\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "compound-interest-time", "title": "\ubcf5\ub9ac \u2014 \uc774\uc790\uac00 \ub2e4\uc74c \ud574\uc758 \ucd9c\ubc1c\uc120\uc5d0 \uc11c\uba74", "summary": "\uc774\uc790\uac00 \ub2e4\uc2dc \uc774\uc790\ub97c \ub0b3\ub294 \uacc4\uc0b0\uc744 \ub2e8\ub9ac\uc640 \ube44\uad50\ud558\uace0, \uac00\uc815\uacfc \uc2e4\uc81c \ud22c\uc790 \uacb0\uacfc\uac00 \ub2e4\ub978 \uc774\uc720\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "finance", "category_title": "\ub3c8\uacfc \uae08\uc735", "subcategory": "\ud22c\uc790\uc640 \uc2dc\uc7a5", "categories": ["finance"], "url": "stories/compound-interest-time/index.html", "image": "../media/compound-interest-time.png", "alt": "\ub3d9\uc804\uc774 \uc870\uae08 \ub4e0 \uc720\ub9ac\ubcd1\uacfc \uc800\ucd95 \uc218\ucca9, \ub2ec\ub825\uacfc \ud654\ubd84\uc774 \ub193\uc778 \ud587\ubcd5 \ub4dc\ub294 \ucc45\uc0c1.", "text": "\ubcf5\ub9ac \u2014 \uc774\uc790\uac00 \ub2e4\uc74c \ud574\uc758 \ucd9c\ubc1c\uc120\uc5d0 \uc11c\uba74 \ubc31\ub9cc \uc6d0\uc758 \uc791\uc740 \uacc4\uc0b0\uc73c\ub85c \uc774\ud574\ud558\ub294 \uc2dc\uac04\uc758 \ud6a8\uacfc \uc774\uc790\uac00 \ub2e4\uc2dc \uc774\uc790\ub97c \ub0b3\ub294 \uacc4\uc0b0\uc744 \ub2e8\ub9ac\uc640 \ube44\uad50\ud558\uace0, \uac00\uc815\uacfc \uc2e4\uc81c \ud22c\uc790 \uacb0\uacfc\uac00 \ub2e4\ub978 \uc774\uc720\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ud22c\uc790\uc640 \uc2dc\uc7a5 \ub3c8\uacfc \uae08\uc735 \ubc31\ub9cc \uc6d0\uc744 \ub123\uace0 1\ub144 \ub4a4 \uc774\uc790\ub97c \ubc1b\uc558\ub2e4. \uadf8 \uc774\uc790\ub97c \uaebc\ub0b4 \uc4f8 \uc218\ub3c4 \uc788\uace0 \uadf8\ub300\ub85c \ub458 \uc218\ub3c4 \uc788\ub2e4. \ub2e4\uc74c \ud574\uc5d0 \ub450 \uc120\ud0dd\uc740 \uc870\uae08 \ub2e4\ub978 \ucd9c\ubc1c\uc120\uc5d0 \uc120\ub2e4. \ub0a8\uaca8 \ub454 \uc774\uc790\uc5d0\ub3c4 \uc0c8 \uc774\uc790\uac00 \ubd99\ub294\ub2e4\uba74 \uccab\ud574\uc5d0\ub294 \uc791\uc544 \ubcf4\uc774\ub358 \ucc28\uc774\uac00 \uc2dc\uac04\uc774 \uc9c0\ub098\uba70 \ucee4\uc9c8 \uc218 \uc788\ub2e4. \ubcf5\ub9ac\ub294 \uc774\ucc98\ub7fc \ub2e4\uc74c \uacc4\uc0b0\uc758 \ubc14\ud0d5\uc774 \ub2ec\ub77c\uc9c0\ub294 \uc774\uc57c\uae30\ub2e4. \ub9d0\uc740 \uac70\ucc3d\ud558\uc9c0\ub9cc \uccab \ub450 \ud574\ub9cc \ucc9c\ucc9c\ud788 \uacc4\uc0b0\ud574 \ubcf4\uba74 \uc5b4\ub835\uc9c0 \uc54a\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc6d0\ub9ac\ub97c \ubcf4\uae30 \uc704\ud574 \ub9e4\ub144 5%\uc758 \uc774\uc790\uac00 \uc5f0\ub9d0\uc5d0 \ubd99\uace0 \uc774\uc790\ub97c \ubaa8\ub450 \ub0a8\uaca8 \ub454\ub2e4\uace0 \uac00\uc815\ud55c\ub2e4. \uc138\uae08\uacfc \uc218\uc218\ub8cc, \uc911\uac04 \uc785\ucd9c\uae08\uc740 \uc5c6\ub294 \uac00\uc0c1 \uc0ac\ub840\uc774\uba70 \uc2e4\uc81c \uae08\uc735\uc0c1\ud488\uc758 \uc218\uc775\ub960\uc744 \uc81c\uc2dc\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc31\ub9cc \uc6d0\uc758 5%\ub294 5\ub9cc \uc6d0\uc774\ub2e4. 1\ub144 \ub4a4 \uc6d0\uae08\uacfc \uc774\uc790\ub97c \ud569\ud558\uba74 105\ub9cc \uc6d0\uc774 \ub41c\ub2e4. \ucc98\uc74c \ubc1b\uc740 \ubc31\ub9cc \uc6d0\ub9cc \uae30\uc900\uc73c\ub85c \uc774\uc790\ub97c \uacc4\uc0b0\ud558\ub294 \ub2e8\ub9ac \ubc29\uc2dd\uacfc, \uc774\uc790\ub97c \ub2e4\uc2dc \ub354\ud574 \uac00\ub294 \ubcf5\ub9ac \ubc29\uc2dd\uc740 \uc774 \uccab\ud574\uc5d0\ub294 \uac19\uc740 \uacb0\uacfc\ub97c \ubcf4\uc77c \uc218 \uc788\ub2e4. \ucc28\uc774\ub294 \uadf8\ub2e4\uc74c \uacc4\uc0b0\uc5d0\uc11c \uc0dd\uae34\ub2e4. \uc6d0\ub798\uc758 \ubc31\ub9cc \uc6d0\ub9cc \uacc4\uc18d \uae30\uc900\uc73c\ub85c \uc0bc\uc744 \uac83\uc778\uc9c0, \uccab\ud574\uc5d0 \ubd88\uc5b4\ub09c 105\ub9cc \uc6d0\uc744 \uc0c8\ub85c\uc6b4 \uae30\uc900\uc73c\ub85c \uc0bc\uc744 \uac83\uc778\uc9c0\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \ubcf5\ub9ac\uc758 \ud575\uc2ec\uc740 \ud2b9\ubcc4\ud788 \ub192\uc740 \uc774\uc790\uc728\uc774 \uc544\ub2c8\ub77c \uacc4\uc0b0\uc758 \ubc14\ud0d5\uc5d0 \uc774\uc804 \uc774\uc790\uac00 \ub4e4\uc5b4\uac04\ub2e4\ub294 \uc810\uc774\ub2e4. \ub2e8\ub9ac\ub85c \ud574\ub9c8\ub2e4 \uc6d0\uae08\uc758 5%\ub97c \ubc1b\ub294\ub2e4\uba74 \ub458\uc9f8 \ud574\uc5d0\ub3c4 \uc774\uc790\ub294 5\ub9cc \uc6d0\uc774\ub2e4. 2\ub144\uac04\uc758 \uc774\uc790\ub97c \uc6d0\uae08\uacfc \ud569\ud558\uba74 110\ub9cc \uc6d0\uc774 \ub41c\ub2e4. \uac19\uc740 \uc870\uac74\uc5d0\uc11c \uc5f0\ubcf5\ub9ac\ub85c \uacc4\uc0b0\ud558\uba74 \ub458\uc9f8 \ud574\uc758 \uae30\uc900\uc740 105\ub9cc \uc6d0\uc774\uace0, \uadf8 5%\ub294 5\ub9cc 2,500\uc6d0\uc774\ub2e4. \ub530\ub77c\uc11c \ubcf5\ub9ac\uc758 2\ub144 \ub4a4 \uae08\uc561\uc740 110\ub9cc 2,500\uc6d0\uc774\ub2e4. \ucc28\uc774\uc778 2,500\uc6d0\uc740 \uccab\ud574 \uc774\uc790 5\ub9cc \uc6d0\uc5d0 \ub2e4\uc2dc \ubd99\uc740 \uc774\uc790\ub2e4. \uac11\uc790\uae30 \ud070 \ubd80\uac00 \uc0dd\uae34 \uac83\uc774 \uc544\ub2c8\ub77c \uacc4\uc0b0\uc5d0 \ub4e4\uc5b4\uac00\ub294 \uc791\uc740 \uae08\uc561\uc774 \ud558\ub098 \ub298\uc5b4\ub09c \uc148\uc774\ub2e4. \uc774 \uc791\uc740 \ubcc0\ud654\uac00 \ub2e4\uc74c \ud574\uc5d0\ub3c4 \ub0a8\uc544 \uc788\uac8c \ub41c\ub2e4. \uac19\uc740 \uac00\uc815\uc73c\ub85c 10\ub144\uc744 \uacc4\uc0b0\ud558\uba74 \ub2e8\ub9ac\uc758 \uc6d0\ub9ac\uae08 \ud569\uacc4\ub294 150\ub9cc \uc6d0\uc774\ub2e4. \uc5f0\ubcf5\ub9ac\uc758 \ud569\uacc4\ub294 \uc57d 162\ub9cc 9\ucc9c \uc6d0\uc774\ub2e4. \ucc98\uc74c \ub450 \ud574\uc758 \ucc28\uc774\ub294 \uc791\uc558\uc9c0\ub9cc \ub354\ud574\uc9c4 \uc774\uc790\uac00 \ub2e4\uc74c \uacc4\uc0b0\uc5d0\ub3c4 \ucc38\uc5ec\ud558\uba74\uc11c \ub450 \ubc29\uc2dd\uc758 \uac04\uaca9\uc774 \ucee4\uc84c\ub2e4. \uacc4\uc0b0\ubc95\uc744 \ub9d0\ub85c \uc4f0\uba74 \ub9e4\ub144 \uc9c1\uc804 \uae08\uc561\uc5d0 1.05\ub97c \uacf1\ud558\ub294 \uac83\uc774\ub2e4. 5%\ub97c \ub354\ud55c \uc804\uccb4\uac00 105%\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \ubcf5\uc7a1\ud55c \uacf5\uc2dd\ubd80\ud130 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uac19\uc740 \uacc4\uc0b0\uc744 \uc774\uc5b4 \uac00\uba74 \ub41c\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uae30\uac04\uacfc \uc774\uc790\uc728, \uc774\uc790\ub97c \ub0a8\uaca8 \ub450\ub294 \uc870\uac74\uc744 \ud568\uaed8 \uc720\uc9c0\ud588\ub2e4\ub294 \uc810\uc774\ub2e4. \ub9e4\ub144 \uc774\uc790 5\ub9cc \uc6d0\uc744 \uacc4\uc88c \ubc16\uc73c\ub85c \ube7c\ub0b4 \uc4f4\ub2e4\uba74 \uadf8 \ub3c8\uc740 \ub2e4\uc74c \ud574\uc758 \uacc4\uc88c \uc774\uc790 \uacc4\uc0b0\uc5d0 \ucc38\uc5ec\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc6d0\uae08 \ubc31\ub9cc \uc6d0\uc744 \uadf8\ub300\ub85c \ub450\ub294 \uac00\uc815\uc5d0\uc11c\ub294 \uacc4\uc88c\uc758 \ubcf5\ub9ac \ud6a8\uacfc\uac00 \uc774\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \ubcf5\ub9ac\ub294 \uc2dc\uac04\uc774 \ud750\ub974\uae30\ub9cc \ud558\uba74 \uc5b4\ub514\uc11c\ub4e0 \uc790\ub3d9\uc73c\ub85c \uc0dd\uae30\ub294 \ubcf4\ub108\uc2a4\uac00 \uc544\ub2c8\ub2e4. \uc911\uac04\uc5d0 \ub3c8\uc744 \ub354 \ub123\uac70\ub098 \uc77c\ubd80\ub97c \ube7c\uba74 \uacb0\uacfc\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc5b4\ub290 \ub0a0 \ub4e4\uc5b4\uc628 \ub3c8\uc774 \uc5bc\ub9c8 \ub3d9\uc548 \uacc4\uc0b0\uc5d0 \ucc38\uc5ec\ud588\ub294\uc9c0 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \ub450 \uc0ac\ub78c\uc758 \ub9c8\uc9c0\ub9c9 \uae08\uc561\uc744 \ube44\uad50\ud560 \ub54c \ucc98\uc74c \ub123\uc740 \ub3c8\uacfc \uc774\ud6c4 \uc785\ucd9c\uae08\uc774 \ub2e4\ub978\ub370 \uc2dc\uac04\uc758 \ud6a8\uacfc\ub9cc \ube44\uad50\ud588\ub2e4\uace0 \ub9d0\ud558\uba74 \uace4\ub780\ud558\ub2e4. \uc774 \uae00\uc758 \uc0ac\ub840\ub294 1\ub144\uc5d0 \ud55c \ubc88 \uc774\uc790\ub97c \ub354\ud588\ub2e4. \ud604\uc2e4\uc5d0\ub294 \uc774\uc790\ub97c \ubd99\uc774\ub294 \uc8fc\uae30\uc640 \uc9c0\uae09 \ubc29\uc2dd\uc774 \ub2e4\ub978 \uc0c1\ud488\uc774 \uc788\ub2e4. \uc5f0\uc774\ub77c\ub294 \ub9d0\uc774 \ubd99\uc740 \uc774\uc790\uc728 \ud558\ub098\ub9cc \uac19\ub2e4\uace0 \ubaa8\ub4e0 \uacc4\uc0b0 \uacfc\uc815\uacfc \uc2e4\uc81c \uc218\ub839\uc561\uae4c\uc9c0 \uac19\uc544\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774\uc790\uc728\uc744 \uc5b4\ub5a4 \uae30\uac04\uc758 \uac12\uc73c\ub85c \ud45c\ud604\ud588\ub294\uc9c0\uc640 \uc774\uc790\ub97c \uc5b8\uc81c \uc6d0\uae08\uc5d0 \ud569\uce58\ub294\uc9c0\ub97c \uad6c\ubd84\ud558\uba74 \ud63c\ub3d9\uc774 \uc904\uc5b4\ub4e0\ub2e4. \ub9e4\ub2ec \ud45c\uc2dc\ub418\ub294 \uc22b\uc790\ub97c \uc5f0 \uc774\uc790\uc728\ucc98\ub7fc \ube44\uad50\ud558\uac70\ub098 \ubc18\ub300\ub85c \uc0dd\uac01\ud558\uba74 \uc804\ud600 \ub2e4\ub978 \uacc4\uc0b0\uc774 \ub41c\ub2e4. \uacc4\uc0b0\uae30\uc5d0 \uc218\uce58\ub97c \ub123\uae30 \uc804\uc5d0 \uadf8 \uc218\uce58\uc758 \uc2dc\uac04 \ub2e8\uc704\ub97c \uc77d\ub294 \uc77c\uc774 \uba3c\uc800\ub2e4. \uc6d0\ub9ac \uc124\uba85\uc5d0\uc11c\ub294 \uc138\uae08\uacfc \uc218\uc218\ub8cc\ub97c \uc81c\uc678\ud588\uc9c0\ub9cc \uc2e4\uc81c\ub85c \ube44\uc6a9\uc774 \ub098\uac00\uba74 \ub0a8\uaca8 \ub458 \uc218 \uc788\ub294 \uae08\uc561\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc791\uc740 \ucc28\uc774\uac00 \uc5ec\ub7ec \uae30\uac04 \uc774\uc5b4\uc9c4\ub2e4\ub294 \uc810\uc5d0\uc11c\ub294 \ube44\uc6a9\ub3c4 \uc2dc\uac04\uc744 \ub530\ub77c \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\ub2e4. \ub192\uc740 \ud45c\uc2dc \uc218\uc775\ub960\ub9cc\uc73c\ub85c \ub9c8\uc9c0\ub9c9 \uae08\uc561\uc744 \ub2e8\uc815\ud558\uae30 \uc5b4\ub824\uc6b4 \uc774\uc720\ub2e4. \ubb3c\uac00\uac00 \uc624\ub97c \ub54c\ub294 \uc22b\uc790\ub85c \ub298\uc5b4\ub09c \ub3c8\uc774 \uc0b4 \uc218 \uc788\ub294 \ubb3c\uac74\uc758 \uc591\ub3c4 \ub530\ub85c \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \uacc4\uc88c\uc758 \uae08\uc561\uc774 \ucee4\uc84c\ub2e4\ub294 \ub9d0\uacfc \uc0dd\ud65c\uc5d0\uc11c\uc758 \uad6c\ub9e4\ub825\uc774 \uac19\uc740 \ub9cc\ud07c \ub298\uc5c8\ub2e4\ub294 \ub9d0\uc740 \ub2e4\ub974\ub2e4. \uc6d0\uae08\uacfc \uc774\uc790\ub97c \ub354\ud558\ub294 \uacc4\uc0b0\uc740 \ud544\uc694\ud558\uc9c0\ub9cc \uadf8\uac83\ub9cc\uc73c\ub85c \ub3c8\uc758 \uac00\uce58\uc5d0 \uad00\ud55c \ubaa8\ub4e0 \uc9c8\ubb38\uc744 \ub05d\ub0bc \uc218\ub294 \uc5c6\ub2e4. \uc2e4\uc81c \ud22c\uc790\ub294 \ud574\ub9c8\ub2e4 \uac19\uc740 \uc218\uc775\ub960\uc744 \ubcf4\uc7a5\ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uc190\uc2e4\uc774 \ub09c \uae30\uac04\uc5d0\ub294 \uadf8\ub2e4\uc74c \uacc4\uc0b0\uc758 \ubc14\ud0d5\ub3c4 \uc791\uc544\uc9c4\ub2e4. \uc704\uc758 \uc0ac\ub840\uac00 \ubd80\ub4dc\ub7fd\uac8c \ucee4\uc9c0\ub294 \uae4c\ub2ed\uc740 \uc591\uc758 \uc774\uc790\uc728\uc774 \ub9e4\ub144 \uc77c\uc815\ud558\ub2e4\uace0 \uc815\ud574 \ub193\uc558\uae30 \ub54c\ubb38\uc774\ub2e4. \uacc4\uc0b0 \uacb0\uacfc\ub97c \ubbf8\ub798\uc758 \uc57d\uc18d\uc73c\ub85c \ubc14\uafb8\uc5b4 \uc77d\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \ub192\uc740 \uc218\uc775\uc744 \uc81c\uc2dc\ud558\ub294 \ud22c\uc790\uc5d0\ub294 \uadf8\uc5d0 \ub530\ub978 \uc704\ud5d8\ub3c4 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc774 \uae00\uc758 \uadfc\uac70\ub85c \uc77d\uc740 \uae08\uc735 \uad50\uc7ac \uc5ed\uc2dc \uacc4\uc0b0\ub41c \ubbf8\ub798 \uae08\uc561\uacfc \uc2e4\uc81c \ud22c\uc790\uc758 \uc704\ud5d8\uc744 \uad6c\ubd84\ud55c\ub2e4. \ubcf5\ub9ac\ub97c \uc774\ud574\ud55c\ub2e4\ub294 \uac83\uc740 \uac00\uc7a5 \ud070 \uc22b\uc790\ub97c \uace0\ub974\ub294 \uc77c\uc774 \uc544\ub2c8\ub77c \uadf8 \uc22b\uc790\uac00 \uc5b4\ub5a4 \uac00\uc815\uc5d0\uc11c \ub098\uc654\ub294\uc9c0 \uc544\ub294 \uc77c\uc774\ub2e4. \uc774\uc790\uc5d0 \ub2e4\uc2dc \uc774\uc790\uac00 \ubd99\ub294\ub2e4\ub294 \ub9d0\uc744 \ucc98\uc74c\uc5d0\ub294 \uc791\uc740 \ub9d0\uc7a5\ub09c\ucc98\ub7fc \ub290\ub084 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ubc31\ub9cc \uc6d0\uc774 105\ub9cc \uc6d0\uc774 \ub418\uace0, \ub2e4\uc74c \uacc4\uc0b0\uc774 \uadf8 105\ub9cc \uc6d0\uc5d0\uc11c \uc2dc\uc791\ub41c\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubcf4\uba74 \uad6c\uc870\uac00 \ubd84\uba85\ud574\uc9c4\ub2e4. \ubcf5\ub9ac\ub294 \uc774\uc804 \uacb0\uacfc\uac00 \ub2e4\uc74c \ucd9c\ubc1c\uc810\uc5d0 \ub4e4\uc5b4\uac00\ub294 \uacfc\uc815\uc774\ub2e4. \uadf8\ub9bc \uc18d \uc800\uae08\ud1b5\uacfc \uc791\uc740 \ud654\ubd84\uc740 \uc2dc\uac04\uc758 \ubd84\uc704\uae30\ub97c \ub2f4\uc740 AI \uc0bd\ud654\uc774\uba70 \uae08\uc561 \uc99d\uac00\ub97c \uc99d\uba85\ud558\ub294 \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ubcf5\ub9ac\ub97c \uc798 \uc774\ud574\ud558\ub824\uba74 \ubb34\uc131\ud558\uac8c \uc790\ub77c\ub294 \ub098\ubb34\ubcf4\ub2e4 \uccab\ud574\uc640 \ub458\uc9f8 \ud574\uc758 \ucc28\uc774\ub97c \uae30\uc5b5\ud574\ub3c4 \ucda9\ubd84\ud558\ub2e4. \uc791\uc740 2,500\uc6d0\uc774 \uc0dd\uae34 \uc774\uc720\ub97c \uc54c\uba74 \ud6e8\uc52c \ud070 \uc22b\uc790\ub3c4 \ucc28\ubd84\ud558\uac8c \uc77d\uc744 \uc218 \uc788\ub2e4."}, {"id": "deposit-insurance-bank-and-safety-net", "title": "\uc608\uae08\uc790\ubcf4\ud638 \u2014 \uc740\ud589\uc758 \uc57d\uc18d \ub4a4\uc5d0 \uc548\uc804\ub9dd\uc744 \ub454 \uc774\uc720", "summary": "\ubbf8\uad6d FDIC\uc758 \uc5ed\uc0ac\uc801 \uc0ac\ub840\ub97c \ubc14\ud0d5\uc73c\ub85c \uc608\uae08\uc790\ubcf4\ud638\uc758 \ubaa9\uc801\u00b7\ubc94\uc704\u00b7\uac10\ub3c5\uc744 \uad6c\ubd84\ud574 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "finance", "category_title": "\ub3c8\uacfc \uae08\uc735", "subcategory": "\uc740\ud589\uacfc \uc2e0\uc6a9", "categories": ["finance"], "url": "stories/deposit-insurance-bank-and-safety-net/index.html", "image": "../media/deposit-insurance-bank-and-safety-net.png", "alt": "\uc77c\ubc18\uc801\uc778 \uc740\ud589 \ucc3d\uad6c\uc5d0\uc11c \ud1b5\uc7a5\uc744 \uc55e\uc5d0 \ub450\uace0 \uc124\uba85\uc744 \ub4e3\ub294 \uc0ac\ub78c\uc758 \uc0bd\ud654.", "text": "\uc608\uae08\uc790\ubcf4\ud638 \u2014 \uc740\ud589\uc758 \uc57d\uc18d \ub4a4\uc5d0 \uc548\uc804\ub9dd\uc744 \ub454 \uc774\uc720 1930\ub144\ub300 \ubbf8\uad6d\uc758 \uacbd\ud5d8\uc5d0\uc11c \uc0b4\ud3b4\ubcf4\ub294 \uc81c\ub3c4\uc758 \ubaa9\uc801 \ubbf8\uad6d FDIC\uc758 \uc5ed\uc0ac\uc801 \uc0ac\ub840\ub97c \ubc14\ud0d5\uc73c\ub85c \uc608\uae08\uc790\ubcf4\ud638\uc758 \ubaa9\uc801\u00b7\ubc94\uc704\u00b7\uac10\ub3c5\uc744 \uad6c\ubd84\ud574 \uc77d\uc2b5\ub2c8\ub2e4. \uc740\ud589\uacfc \uc2e0\uc6a9 \ub3c8\uacfc \uae08\uc735 \uc740\ud589\uc5d0 \ub9e1\uae34 \ub3c8\uc744 \ucc3e\uc73c\ub7ec \uc0ac\ub78c\ub4e4\uc774 \ud55c\uaebc\ubc88\uc5d0 \ubab0\ub9ac\uba74 \ubd88\uc548\uc740 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c\ub3c4 \ubc88\uc9c4\ub2e4. \ub098\ub294 \uae30\ub2e4\ub9b4 \uc0dd\uac01\uc774\uc5c8\uc5b4\ub3c4 \uae34 \uc904\uc744 \ubcf4\uba74 \ub9c8\uc74c\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ud55c \uc0ac\ub78c\uc758 \ud310\ub2e8\uc774 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \ud589\ub3d9\uacfc \uc5f0\uacb0\ub418\ub294 \uc21c\uac04\uc774\ub2e4. \uc608\uae08\uc790\ubcf4\ud638\ub294 \uc774\ub7f0 \uc0c1\ud669\uc5d0\uc11c \uc740\ud589\uc758 \uc57d\uc18d \ub4a4\uc5d0 \ub610 \ud558\ub098\uc758 \uc548\uc804\ub9dd\uc744 \ub9c8\ub828\ud558\ub824\ub294 \uc81c\ub3c4\ub2e4. \uc774\ubc88\uc5d0\ub294 1930\ub144\ub300 \ubbf8\uad6d\uc758 \uacbd\ud5d8\uacfc \uc5f0\ubc29\uc608\uae08\ubcf4\ud5d8\uacf5\uc0ac, FDIC\uc758 \uc0ac\ub840\ub97c \uc911\uc2ec\uc73c\ub85c \ubaa9\uc801\uc744 \uc0b4\ud3b4\ubcf8\ub2e4. \ud604\uc7ac \ud55c\uad6d\uc758 \ubcf4\ud638 \ud55c\ub3c4\ub098 \ud2b9\uc815 \uc0c1\ud488\uc758 \uc801\uc6a9 \uc5ec\ubd80\ub97c \uc815\ub9ac\ud558\ub294 \uc548\ub0b4\ub294 \uc544\ub2c8\ub2e4. OpenStax\ub294 \ub300\uacf5\ud669\uae30\uc5d0 \ubbf8\uad6d\uc5d0\uc11c \uc740\ud589\uc758 \uc5b4\ub824\uc6c0\uacfc \ub300\uaddc\ubaa8 \uc778\ucd9c\uc774 \uc11c\ub85c \uc5bd\ud614\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc740\ud589\uc774 \ub3c8\uc744 \uc9c0\uae09\ud558\uc9c0 \ubabb\ud560 \uc218 \uc788\ub2e4\ub294 \uac71\uc815\uc774 \ucee4\uc9c0\uba74 \ub354 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uba3c\uc800 \ucc3e\uc73c\ub824 \ud55c\ub2e4. \uadf8 \ud589\ub3d9\uc774 \uc740\ud589\uc758 \ub2f9\uc7a5 \uc9c0\uae09\ud560 \ub3c8\uc5d0 \ubd80\ub2f4\uc744 \ub354\ud560 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \uc740\ud589\uc758 \ubb38\uc81c\uac00 \uac19\uc740 \uc6d0\uc778\uc774\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc790\uc0b0\uc758 \uc190\uc2e4\uacfc \ub2f9\uc7a5 \ud604\uae08\uc744 \ub9c8\ub828\ud560 \ub2a5\ub825\ub3c4 \ub2e4\ub978 \ubb38\uc81c\ub2e4. \ub2e4\ub9cc \uc608\uae08\uc790\ub294 \uc740\ud589 \ub0b4\ubd80\ub97c \ub9e4\uc77c \uc9c1\uc811 \ud3c9\uac00\ud558\uae30 \uc5b4\ub835\ub2e4. \uac1c\ubcc4 \uc0ac\ub78c\uc774 \uac00\uc9c4 \uc815\ubcf4\uc758 \ud55c\uacc4\uac00 \ubd88\uc548\uc758 \uc804\ud30c\uc640 \ub9cc\ub0a0 \ub54c \uc81c\ub3c4\uc758 \uc9c8\ubb38\uc774 \uc0dd\uae34\ub2e4. \uad50\uc7ac\ub294 \ubbf8\uad6d\uc758 1933\ub144 \uc740\ud589\ubc95\uc5d0 \ub530\ub77c FDIC\uac00 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc740\ud589\uc774 \uc2e4\ud328\ud588\uc744 \ub54c \uc608\uae08\uc744 \ubcf4\ud638\ud558\uae30 \uc704\ud55c \uae30\uad00\uc774\uc5c8\ub2e4. \uc740\ud589\uc758 \uc790\uccb4 \uc2e0\ub8b0\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc608\uae08\uc790\ub97c \uc548\uc2ec\uc2dc\ud0a4\uae30 \uc5b4\ub824\uc6e0\ub358 \uacbd\ud5d8\uc774 \uc81c\ub3c4\uc801 \uc7a5\uce58\ub85c \uc774\uc5b4\uc9c4 \uac83\uc774\ub2e4. \uc5ec\uae30\uc11c \ud55c \ub098\ub77c\uc758 \uc5ed\uc0ac\uc801 \uc0ac\ub840\uc640 \ubaa8\ub4e0 \ub098\ub77c\uc758 \ud604\uc7ac \uc81c\ub3c4\ub97c \uc11e\uc9c0 \uc54a\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \ud55c\uad6d\uc744 \ube44\ub86f\ud55c \ub2e4\ub978 \ub098\ub77c\uc758 \uc801\uc6a9 \ub300\uc0c1\uacfc \ud55c\ub3c4, \uc6b4\uc601 \ubc29\uc2dd\uc740 \ub530\ub85c \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uc774\ubc88 \uc774\uc57c\uae30\uac00 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \uad6c\uccb4\uc801\uc778 \ubcf4\ud638 \uae08\uc561\ubcf4\ub2e4 \uc740\ud589\uc758 \uc2e4\ud328 \ube44\uc6a9\uc744 \uc5b4\ub5a4 \uc7a5\uce58\ub85c \ub2e4\ub8e8\ub824 \ud588\ub294\uac00\ub77c\ub294 \uc9c8\ubb38\uc774\ub2e4. \ubcf4\ud638 \uc81c\ub3c4\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ud574\ub2f9 \uc740\ud589\uc758 \ubaa8\ub4e0 \uc790\uc0b0\uc774 \uc88b\uc740 \uc0c1\ud0dc\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc81c\ub3c4\uc758 \ubaa9\uc801\uc740 \uc815\ud574\uc9c4 \uc870\uac74\uc5d0\uc11c \uc608\uae08\uc790\ub97c \ubcf4\ud638\ud558\ub294 \uac83\uc774\uba70 \uc740\ud589\uc758 \ubaa8\ub4e0 \uc0ac\uc5c5\uc774 \uc131\uacf5\ud558\ub3c4\ub85d \ubcf4\uc7a5\ud558\ub294 \uac83\uacfc\ub294 \ub2e4\ub974\ub2e4. \uae30\uad00\uc758 \uac74\uc804\uc131\uacfc \uc608\uae08\uc790\uc758 \ubcf4\ud638\ub294 \uc5f0\uacb0\ub418\uc9c0\ub9cc \uac19\uc740 \ud56d\ubaa9\uc740 \uc544\ub2c8\ub2e4. \uc774 \ucc28\uc774\ub97c \uc54c\uba74 \ubcf4\ud638 \ud45c\uc2dc\ub97c \ubcf4\uace0 \uc740\ud589\uc5d0 \uad00\ud55c \ub2e4\ub978 \uc815\ubcf4\ub97c \uc804\ubd80 \ubb34\uc2dc\ud558\ub294 \ud310\ub2e8\uc744 \ud53c\ud560 \uc218 \uc788\ub2e4. \ubc18\ub300\ub85c \uc740\ud589\uc774 \uc5b4\ub824\uc6cc\uc84c\ub2e4\ub294 \uc18c\uc2dd\ub9cc \ub4e3\uace0 \ubcf4\ud638 \uc7a5\uce58\uc758 \uc874\uc7ac\ub97c \uc5c6\ub294 \uac83\uc73c\ub85c \ubcfc \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ubb34\uc5c7\uc774 \uc704\ud5d8\ud558\uace0 \ubb34\uc5c7\uc744 \ub204\uac00 \ubcf4\uc644\ud558\ub294\uc9c0 \ub098\ub204\uc5b4 \ubcf4\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \uad50\uc7ac\ub294 \ubbf8\uad6d\uc758 \uac00\uc785 \uc740\ud589\ub4e4\uc774 \uc608\uae08\ubcf4\ud5d8\ub8cc\ub97c \ub0b8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc608\uae08\uc790\ubcf4\ud638\ub97c \ub2e8\uc21c\ud788 \uc88b\uc740 \uc758\uc9c0\ub97c \uc801\uc740 \ubb38\uc7a5\uc73c\ub85c\ub9cc \uc6b4\uc601\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc190\uc2e4\uc744 \uac10\ub2f9\ud560 \uc900\ube44\uc640 \uc9c0\uae09\uc744 \uc2e4\ud589\ud560 \uccb4\uacc4\uac00 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uc57d\uc18d\uc5d0\ub294 \uadf8\uac83\uc744 \ub4b7\ubc1b\uce68\ud560 \uad6c\uc870\uac00 \ud544\uc694\ud558\ub2e4. \ub610 \uc5b4\ub5a4 \uc740\ud589\uc774 \uc5b4\ub290 \uc815\ub3c4 \uc704\ud5d8\uc744 \uc9c0\ub294\uc9c0\uc5d0 \ub530\ub77c \ube44\uc6a9\uc744 \uc5b4\ub5bb\uac8c \ub098\ub20c\uc9c0\ub3c4 \uc9c8\ubb38\uc774 \ub41c\ub2e4. \uad50\uc7ac\ub294 \ubbf8\uad6d\uc774 \uacfc\uac70 \uc77c\ub960\uc801\uc778 \ubcf4\ud5d8\ub8cc\uc5d0\uc11c \uc704\ud5d8\uc744 \ubc18\uc601\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c \ubc14\uafbc \uc0ac\ub840\ub97c \uc18c\uac1c\ud55c\ub2e4. \ubcf4\ud638\uc758 \uc874\uc7ac\uc640 \uadf8 \ube44\uc6a9\uc744 \ubc30\ubd84\ud558\ub294 \uc124\uacc4\ub294 \ud568\uaed8 \ubcf4\uc544\uc57c \ud558\ub294 \ubb38\uc81c\ub2e4. \ubcf4\ud638\uac00 \uc788\ub2e4\ub294 \uc774\uc720\ub85c \uc704\ud5d8\uc744 \ud06c\uac8c \uc838\ub3c4 \ub41c\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uc81c\ub3c4\uc758 \ubd80\ub2f4\uc774 \ub298 \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc608\uae08\ubcf4\ud5d8\uacfc \uc740\ud589\uc758 \uc704\ud5d8 \uc120\ud0dd \uc0ac\uc774\uc5d0 \uc774\ub7f0 \uc720\uc778 \ubb38\uc81c\uac00 \uc788\uc744 \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc190\uc2e4\uc744 \ubcf4\uc644\ud558\ub294 \uc77c\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc608\ubc29\uc774 \ub05d\ub098\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc740\ud589\uc744 \uac80\uc0ac\ud558\uace0 \uc7ac\ubb34 \uc0c1\ud0dc\uc640 \uc6b4\uc601\uc744 \uc0b4\ud53c\ub294 \uac10\ub3c5\ub3c4 \uc911\uc694\ud558\ub2e4. \uc0ac\ud6c4\uc758 \ubcf4\ud638\uc640 \uc0ac\uc804\uc758 \uad00\ub9ac\uac00 \uc11c\ub85c \ub2e4\ub978 \uc5ed\ud560\uc744 \ud55c\ub2e4. \uc18c\ud654\uae30\uac00 \uc788\ub2e4\uace0 \ud654\uc7ac \uc608\ubc29\uc744 \ud558\uc9c0 \uc54a\uc544\ub3c4 \ub418\ub294 \uac83\uc740 \uc544\ub2cc \uac83\ucc98\ub7fc, \uc548\uc804\ub9dd\uc740 \uc810\uac80\uc744 \ub300\uc2e0\ud558\ub294 \ub9d0\ubcf4\ub2e4 \uc810\uac80\uacfc \ud568\uaed8 \uc124\uacc4\ud560 \uc870\uac74\uc5d0 \uac00\uae5d\ub2e4. \uc740\ud589\uc5d0\uc11c \uac00\uc785\ud588\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc608\uae08\uc790\ubcf4\ud638 \ub300\uc0c1\uc774\ub77c\ub294 \uc0ac\uc2e4\uc740 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc5b4\ub5a4 \uae30\uad00\uacfc \uc0c1\ud488\uc774 \uc81c\ub3c4\uc758 \ubc94\uc704\uc5d0 \ub4e4\uc5b4\uac00\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\ub2e4. \ubcf4\ud638\ub77c\ub294 \ub2e8\uc5b4\ub9cc \uae30\uc5b5\ud558\uace0 \uad6c\uccb4\uc801\uc778 \uc57d\uc18d\uc758 \ubc94\uc704\ub97c \uc0dd\ub7b5\ud558\uba74 \uae30\ub300\uc640 \uc2e4\uc81c\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ud55c\ub3c4\uac00 \uc801\uc6a9\ub418\ub294 \uae30\uc900\uacfc \uc9c0\uae09 \ubc29\uc2dd\ub3c4 \uc81c\ub3c4\ub9c8\ub2e4 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uacc4\uc88c\ub97c \ub098\ub204\uac70\ub098 \uc774\ub984\ub9cc \ubc14\uafb8\uba74 \uc5b4\ub5bb\uac8c \ub41c\ub2e4\ub294 \uc2dd\uc758 \uac04\ub2e8\ud55c \uacb0\ub860\uc740 \uc5ec\uae30\uc11c \uc81c\uc2dc\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc774\ub7f0 \uc138\ubd80\ub294 \ud574\ub2f9 \ub098\ub77c\uc758 \uacf5\uc2dd \uc548\ub0b4\uc640 \uc0c1\ud488 \uc124\uba85\uc5d0\uc11c \ucd5c\uc2e0 \uae30\uc900\uc744 \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uc6d0\ub9ac\ub97c \uc544\ub294 \uc77c\uacfc \uc801\uc6a9\uc744 \ud655\uc778\ud558\ub294 \uc77c\uc740 \ub2e4\ub978 \ub2e8\uacc4\ub2e4. \uc0ac\ub78c\ub9c8\ub2e4 \uae08\uc735\uc744 \uacf5\ubd80\ud560 \uc2dc\uac04\uacfc \uc815\ubcf4\uac00 \uac19\uc9c0 \uc54a\ub2e4. \uc6d4\uae09\uacfc \uc0dd\ud65c\ube44\ub97c \ub9e1\uae30\uae30 \uc704\ud574 \ubaa8\ub4e0 \uc740\ud589\uc758 \uc790\uc0b0\uc744 \uc9c1\uc811 \uc870\uc0ac\ud574\uc57c \ud55c\ub2e4\uba74 \uc77c\uc0c1\uc801\uc778 \uac70\ub798 \uc790\uccb4\uac00 \uc5b4\ub824\uc6cc\uc9c4\ub2e4. \uc81c\ub3c4\ub294 \uc774\ub7f0 \uc815\ubcf4\uc640 \uc804\ubb38\uc131\uc758 \ucc28\uc774\ub97c \uc5b4\ub290 \uc815\ub3c4 \ub2e4\ub8e8\ub294 \uc5ed\ud560\ub3c4 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ubb3c\ub860 \ubcf4\ud638\uac00 \uc788\ub2e4\uace0 \uc5b4\ub5a4 \uc120\ud0dd\ub3c4 \uc0b4\ud3b4\ubcfc \ud544\uc694\uac00 \uc5c6\uc5b4\uc9c4 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uac1c\uc778\uc758 \uc8fc\uc758\ub9cc \uc694\uad6c\ud558\ub294 \ubc29\uc2dd\uacfc \uacf5\ud1b5\uc758 \uc548\uc804\uc7a5\uce58\ub97c \ub450\ub294 \ubc29\uc2dd\uc740 \ub2e4\ub974\ub2e4. \uc5b4\ub5a4 \uc704\ud5d8\uc744 \uac1c\uc778\uc5d0\uac8c \ub9e1\uae30\uace0 \uc5b4\ub5a4 \ubd80\ubd84\uc744 \uc81c\ub3c4\ub85c \ubcf4\uc644\ud560\uc9c0\ub294 \uae08\uc735\uc774 \uc0ac\ud68c\uc758 \uc57d\uc18d\uacfc \ub9cc\ub098\ub294 \uc9c0\uc810\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc740\ud589 \ucc3d\uad6c\uc5d0\uc11c \uc124\uba85\uc744 \ub4e3\ub294 \uc77c\ubc18\uc801\uc778 \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c \uae08\uc735\uae30\uad00\uc774\ub098 \uc608\uae08\uc790\ubcf4\ud638 \uc808\ucc28\ub97c \uc7ac\ud604\ud55c \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \uc774 \uc6d0\uace0\ub294 \ubcf4\ud638 \uc81c\ub3c4\uc758 \ubaa9\uc801\uc744 \uc774\ud574\ud558\ub294 \uc774\uc57c\uae30\uc774\uba70 \ud604\uc7ac\uc758 \ubc95\ub960\uacfc \ubcf4\ud638 \uae08\uc561\uc744 \uc778\uc99d\ud558\ub294 \uc790\ub8cc\ub85c \uc4f0\uc9c0 \uc54a\ub294\ub2e4. \uc608\uae08\uc790\ubcf4\ud638\ub97c \uc54c\uba74 \uc548\uc804\ud558\ub2e4\ub294 \ub9d0 \ub2e4\uc74c\uc5d0 \ub354 \uc815\ud655\ud55c \uc9c8\ubb38\uc744 \ud560 \uc218 \uc788\ub2e4. \uc5b4\ub5a4 \uae30\uad00\uc758 \uc5b4\ub5a4 \uc608\uae08\uc744 \ub204\uac00 \uc5b4\ub5a4 \ubc94\uc704\uc5d0\uc11c \ubcf4\ud638\ud558\ub294\uac00. 1930\ub144\ub300\uc758 \uacbd\ud5d8\uc5d0\uc11c \uc2dc\uc791\ub41c \uc774 \uc9c8\ubb38\uc740 \uc740\ud589\uc758 \uc57d\uc18d\uc744 \uac1c\uc778\uc758 \ubbff\uc74c\uc5d0\ub9cc \ub9e1\uae30\uc9c0 \uc54a\uace0 \uc81c\ub3c4\uc758 \uad6c\uc870\ub85c \ub4b7\ubc1b\uce68\ud558\ub824 \ud588\ub358 \uc774\uc720\ub97c \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "diversification-baskets-and-common-weather", "title": "\ubd84\uc0b0\ud22c\uc790 \u2014 \ubc14\uad6c\ub2c8\ub97c \ub298\ub824\ub3c4 \uac19\uc740 \ube44\ub97c \ub9de\ub294\ub2e4\uba74", "summary": "\uac00\uc0c1\uc758 \ub450 \uc790\uc0b0\uacfc \uc815\uc6d0\uc758 \ube44\uc720\ub85c \uc704\ud5d8\uc758 \ubd84\uc0b0\uacfc \uacf5\ud1b5 \uc694\uc778\uc758 \ucc28\uc774\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "finance", "category_title": "\ub3c8\uacfc \uae08\uc735", "subcategory": "\ud22c\uc790\uc640 \uc2dc\uc7a5", "categories": ["finance"], "url": "stories/diversification-baskets-and-common-weather/index.html", "image": "../media/diversification-baskets-and-common-weather.png", "alt": "\uac19\uc740 \ud750\ub9b0 \ud558\ub298 \uc544\ub798 \uc5ec\ub7ec \uad6c\ud68d\uc5d0\uc11c \uc11c\ub85c \ub2e4\ub978 \uc791\ubb3c\uc744 \uac00\uafb8\ub294 \uc815\uc6d0\uc0ac\uc758 \uc0bd\ud654.", "text": "\ubd84\uc0b0\ud22c\uc790 \u2014 \ubc14\uad6c\ub2c8\ub97c \ub298\ub824\ub3c4 \uac19\uc740 \ube44\ub97c \ub9de\ub294\ub2e4\uba74 \uc774\ub984\uc758 \uac1c\uc218\ubcf4\ub2e4 \ud568\uaed8 \uc6c0\uc9c1\uc774\ub294 \uc774\uc720\ub97c \ubcf4\uae30 \uac00\uc0c1\uc758 \ub450 \uc790\uc0b0\uacfc \uc815\uc6d0\uc758 \ube44\uc720\ub85c \uc704\ud5d8\uc758 \ubd84\uc0b0\uacfc \uacf5\ud1b5 \uc694\uc778\uc758 \ucc28\uc774\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ud22c\uc790\uc640 \uc2dc\uc7a5 \ub3c8\uacfc \uae08\uc735 \ub2ec\uac40\uc744 \ud55c \ubc14\uad6c\ub2c8\uc5d0 \ub2f4\uc9c0 \ub9d0\ub77c\ub294 \ub9d0\uc744 \ud22c\uc790\uc5d0\uc11c\ub3c4 \uc790\uc8fc \ub4e3\ub294\ub2e4. \uadf8\ub798\uc11c \uc11c\ub85c \ub2e4\ub978 \uc774\ub984\uc758 \uc0c1\ud488\uc744 \uc5ec\ub7ec \uac1c \uace0\ub974\uba74 \ucda9\ubd84\ud560 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uadf8\ub7f0\ub370 \ubc14\uad6c\ub2c8\uac00 \ubaa8\ub450 \uac19\uc740 \uc120\ubc18\uc5d0 \ub193\uc5ec \uc788\uace0 \uadf8 \uc120\ubc18\uc774 \ubb34\ub108\uc9c4\ub2e4\uba74 \uc5b4\ub5bb\uac8c \ub420\uae4c. \uac1c\uc218\ub9cc \ub298\ub9b0\ub2e4\uace0 \ubaa8\ub4e0 \uc704\ud5d8\uc774 \ub098\ub258\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubd84\uc0b0\ud22c\uc790\ub294 \uc5ec\ub7ec \ub300\uc0c1\uc744 \uace0\ub974\ub294 \uc77c\uc5d0\uc11c \uc2dc\uc791\ud558\uc9c0\ub9cc \uadf8\uac83\ub4e4\uc774 \uc65c \ud568\uaed8 \uc624\ub974\ub0b4\ub9ac\ub294\uc9c0\ub3c4 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \ubcf5\uc7a1\ud55c \uc218\ud559 \ub300\uc2e0 \uac00\uc0c1\uc758 \ub450 \uc790\uc0b0\uacfc \uac19\uc740 \ub0a0\uc528\ub97c \uacaa\ub294 \uc815\uc6d0\uc744 \ub5a0\uc62c\ub9ac\uba74 \uc774 \ucc28\uc774\ub97c \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \ubaa8\ub4e0 \ub3c8\uc744 \ud55c \ud68c\uc0ac\uc758 \uc8fc\uc2dd\uc5d0 \ub450\uba74 \uadf8 \ud68c\uc0ac\uac00 \uacaa\ub294 \uc77c\uc758 \uc601\ud5a5\uc744 \ud06c\uac8c \ubc1b\ub294\ub2e4. \uc2e4\uc801\uacfc \uacbd\uc601, \uc81c\ud488\uc758 \ubb38\uc81c\uc5d0 \ub530\ub77c \uacb0\uacfc\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc5ec\ub7ec \ud68c\uc0ac\uc5d0 \ub098\ub204\uba74 \ud55c \ud68c\uc0ac\uc5d0\uc11c \uc0dd\uae34 \uc77c\uc774 \uc804\uccb4\ub97c \uadf8\ub300\ub85c \uacb0\uc815\ud558\ub294 \uc815\ub3c4\ub97c \uc904\uc77c \uc218 \uc788\ub2e4. OpenStax\ub294 \uc774\ub7f0 \uc704\ud5d8 \uad00\ub9ac\ub97c \ubd84\uc0b0\uc758 \uae30\ubcf8 \ucde8\uc9c0\ub85c \uc124\uba85\ud55c\ub2e4. \ud558\uc9c0\ub9cc \ud68c\uc0ac \uc774\ub984\uc774 \ub2e4\ub974\ub2e4\uace0 \uc11c\ub85c \uad00\uacc4\uc5c6\ub294 \uc704\ud5d8\uc744 \uac00\uc9c4 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac19\uc740 \uc5c5\uc885\uacfc \uac19\uc740 \uace0\uac1d, \uac19\uc740 \uc6d0\uc7ac\ub8cc\uc5d0 \uae30\ub300\ub294 \uae30\uc5c5\ub4e4\uc740 \uacf5\ud1b5\uc758 \uc870\uac74\uc744 \uacaa\uc744 \uc218 \uc788\ub2e4. \uccab\uac78\uc74c\uc740 \ub098\ub204\ub294 \uac83\uc774\uc9c0\ub9cc \ub2e4\uc74c \uc9c8\ubb38\uc740 \ubb34\uc5c7\uc744 \ub098\ub204\uc5c8\ub294\uc9c0\ub2e4. \ud55c \uae30\uac04\uc5d0 \uac00\uc0c1\uc758 \uc790\uc0b0 A\uac00 20% \uc624\ub974\uace0 B\uac00 20% \ub0b4\ub838\ub2e4\uace0 \ud574 \ubcf4\uc790. \ucc98\uc74c\uc5d0 \uac19\uc740 \uae08\uc561\uc744 \uc808\ubc18\uc529 \ud22c\uc790\ud588\uace0 \uc911\uac04 \uac70\ub798\uc640 \ube44\uc6a9\uc774 \uc5c6\ub2e4\uba74 \uc804\uccb4 \uc218\uc775\ub960\uc740 0%\ub2e4. \ud55c\ucabd\uc758 \ubcc0\ud654\uac00 \ub2e4\ub978 \ucabd\uc744 \uc0c1\uc1c4\ud558\ub294 \ub2e8\uc21c\ud55c \uc608\ub2e4. \uc774\uac83\uc740 \ub450 \uc790\uc0b0\uc744 \uace0\ub974\uba74 \uc5b8\uc81c\ub098 \uc6d0\uae08\uc774 \uc9c0\ucf1c\uc9c4\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uac19\uc740 \uae30\uac04\uc5d0 \ub458 \ub2e4 \ud558\ub77d\ud558\uba74 \uc804\uccb4\ub3c4 \ud558\ub77d\ud55c\ub2e4. \ubc18\uc529 \ub2f4\uc558\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ubbf8\ub798\uc758 \uacb0\uacfc\ub97c \ubcf4\uc7a5\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc608\uc2dc\uc758 \uc22b\uc790\ub294 \uacc4\uc0b0\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uac00\uc0c1 \uac12\uc774\uba70 \uc2e4\uc81c \uc0c1\ud488\uc758 \uc608\uc0c1 \uc218\uc775\ub960\uc774 \uc544\ub2c8\ub2e4. \uad50\uc7ac\ub294 \uc5ec\ub7ec \uc790\uc0b0\uc758 \uc704\ud5d8\uc774 \uac01\uac01\uc758 \ubcc0\ub3d9 \ud3ed\ubfd0 \uc544\ub2c8\ub77c \uc11c\ub85c \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc774\ub294\uc9c0\uc5d0\ub3c4 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud55c\ucabd\uc774 \uc5b4\ub824\uc6b8 \ub54c \ub2e4\ub978 \ucabd\ub3c4 \uac19\uc740 \uc774\uc720\ub85c \uc5b4\ub824\uc6cc\uc9c0\ub294\uc9c0, \ubcc0\ud654\uc758 \uc2dc\uc810\uc774 \ub2e4\ub978\uc9c0 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc774\ub7f0 \uad00\uacc4\ub97c \ud1b5\uacc4\uc5d0\uc11c\ub294 \uc0c1\uad00\uad00\uacc4\ub85c \ub2e4\ub8ec\ub2e4. \uc22b\uc790 \uacf5\uc2dd\uc744 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \ud575\uc2ec\uc740 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ub450 \uc2dd\ub2f9\uc774 \uc11c\ub85c \ub2e4\ub978 \uc774\ub984\uc774\uc5b4\ub3c4 \uac19\uc740 \uac74\ubb3c\uc758 \ubc29\ubb38\uac1d\uc5d0\uac8c \uae30\ub300\uace0 \uc788\ub2e4\uba74 \uadf8 \uac74\ubb3c\uc774 \ubb38\uc744 \ub2eb\uc744 \ub54c \ud568\uaed8 \uc601\ud5a5\uc744 \ubc1b\uc744 \uc218 \uc788\ub2e4. \uc774\ub294 \ud22c\uc790 \uc0c1\ud488\uc744 \uc9c1\uc811 \ud3c9\uac00\ud55c \uc0ac\ub840\uac00 \uc544\ub2c8\ub77c \uacf5\ud1b5 \uc694\uc778\uc744 \ub5a0\uc62c\ub9ac\ub294 \ube44\uc720\ub2e4. \uad50\uc7ac\ub294 \uc11c\ub85c \ub2e4\ub978 \ud56d\uacf5\uc0ac\ub3c4 \uc5ec\ud589 \uc218\uc694\uc640 \uc5f0\ub8cc\ube44 \uac19\uc740 \uc870\uac74\uc744 \ud568\uaed8 \uacaa\uc744 \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud55c \ud68c\uc0ac\ub9cc\uc758 \uc2dc\uc2a4\ud15c \ubb38\uc81c\uc640 \uc5c5\uacc4 \uc804\uccb4\uc758 \uc218\uc694 \uac10\uc18c\ub294 \ub2e4\ub978 \ubc94\uc704\uc758 \uc0ac\uac74\uc774\ub2e4. \uc5ec\ub7ec \ud56d\uacf5\uc0ac\uc5d0 \ub098\ub204\uba74 \uccab \ubc88\uc9f8\uc5d0 \ub300\ud55c \ub178\ucd9c\uc740 \ub2ec\ub77c\uc838\ub3c4 \ub450 \ubc88\uc9f8\ub294 \ub0a8\uc744 \uc218 \uc788\ub2e4. \uc774 \uad6c\ubd84\uc740 \uc720\uba85\ud55c \uae30\uc5c5\uc758 \uc218\ub97c \uc138\ub294 \uc77c\ubcf4\ub2e4 \uc720\uc6a9\ud560 \ub54c\uac00 \uc788\ub2e4. \ubb34\uc5c7\uc744 \uc0dd\uc0b0\ud558\uace0 \uc5b4\ub514\uc5d0\uc11c \ubc8c\uba70 \uc5b4\ub5a4 \ube44\uc6a9\uc5d0 \uae30\ub300\ub294\uc9c0 \ubb3c\uc5b4\ubcf4\uac8c \ub41c\ub2e4. \ubb3c\ub860 \uc774 \uae00\uc740 \ud2b9\uc815 \uc5c5\uc885\uc744 \uc88b\uac70\ub098 \ub098\uc058\ub2e4\uace0 \ucd94\ucc9c\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc774\ub984\ubcf4\ub2e4 \uc791\ub3d9 \uc870\uac74\uc744 \uc0b4\ud3b4\ubcf4\uc790\ub294 \uc124\uba85\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\uc5d0\ub294 \uc11c\ub85c \ub2e4\ub978 \uc791\ubb3c\uc744 \uae30\ub974\ub294 \uc5ec\ub7ec \uad6c\ud68d\uc774 \uc788\ub2e4. \ud55c \uc791\ubb3c\uc5d0\ub9cc \uc0dd\uae30\ub294 \ubb38\uc81c\uc640 \uc815\uc6d0 \uc804\uccb4\uc5d0 \ub0b4\ub9ac\ub294 \ube44\ub294 \ub2e4\ub974\ub2e4. \uc791\ubb3c\uc744 \ub2e4\uc591\ud558\uac8c \uc2ec\uc5b4\ub3c4 \uac19\uc740 \ud558\ub298 \uc544\ub798 \uc788\ub2e4\ub294 \uc870\uac74\uc740 \ub0a8\ub294\ub2e4. \ubd84\uc0b0\uc758 \uc5ed\ud560\uacfc \ud55c\uacc4\ub97c \ud568\uaed8 \ub5a0\uc62c\ub9ac\uae30 \uc704\ud55c \ube44\uc720\ub2e4. \uc2e4\uc81c \uc790\uc0b0\uc740 \uc2dd\ubb3c\uacfc \ub611\uac19\uc774 \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294\ub2e4. \ube44\uc720\ub294 \uac1c\ub150\uc744 \uc774\ud574\ud558\ub294 \ub3c4\uad6c\uc774\uc9c0 \uc218\uc775\uc744 \uacc4\uc0b0\ud558\ub294 \ubaa8\ud615\uc740 \uc544\ub2c8\ub2e4. \uae08\uc735\uc2dc\uc7a5\uc5d0\ub3c4 \ub113\uac8c \uc791\uc6a9\ud558\ub294 \ubcc0\ud654\uac00 \uc788\uc5b4 \ubaa8\ub4e0 \uac1c\ubcc4 \uc704\ud5d8\uc744 \uc5c6\uc560\ub4ef \uc81c\uac70\ud560 \uc218\ub294 \uc5c6\ub2e4\ub294 \uc810\ub9cc \uac00\uc838\uc624\uba74 \ucda9\ubd84\ud558\ub2e4. \uacfc\uac70\uc5d0 \ub450 \uc790\uc0b0\uc774 \uc11c\ub85c \ub2e4\ub974\uac8c \uc6c0\uc9c1\uc600\ub2e4\ub294 \uae30\ub85d\uc740 \uc720\uc6a9\ud55c \uc790\ub8cc\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \uad00\uacc4\uac00 \ubbf8\ub798\uc5d0\ub3c4 \uace0\uc815\ub418\uc5b4 \uc788\ub2e4\uace0 \ubcf4\uc7a5\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uae30\uc5c5\uc758 \uc0ac\uc5c5\uacfc \uc2dc\uc7a5\uc758 \uc870\uac74\uc774 \ubc14\ub014 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uacfc\uac70\uc758 \uad00\ucc30\uc744 \uc77d\ub294 \uc77c\uacfc \ubbf8\ub798\ub97c \ud655\uc815\ud558\ub294 \uc77c\uc740 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc88b\uc558\ub358 \ud55c \uc2dc\uae30\ub9cc \uace8\ub77c \ubcf4\uc5ec \uc8fc\uba74 \uc804\uccb4 \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \uae30\uac04\uacfc \ube44\uc6a9, \ube44\uad50 \ub300\uc0c1\uc744 \ud568\uaed8 \uc0b4\ud53c\ub294 \uc774\uc720\ub2e4. \ubd84\uc0b0\uc774\ub77c\ub294 \ub2e8\uc5b4\uac00 \ub4e4\uc5b4 \uc788\ub2e4\uace0 \uc704\ud5d8 \uc124\uba85\uc744 \uac74\ub108\ub6f0\uc5b4\ub3c4 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uad00\uacc4\ub97c \uc5b4\ub5a4 \uc790\ub8cc\ub85c \ud310\ub2e8\ud588\ub294\uc9c0\uae4c\uc9c0 \ubb3c\uc5b4\ubcf4\uba74 \uc88b\ub2e4. \uc5ec\ub7ec \ubb36\uc74c\uc744 \uace8\ub790\ub294\ub370 \uac01\uac01\uc5d0 \uac19\uc740 \ud68c\uc0ac\ub4e4\uc774 \ub9ce\uc774 \ub4e4\uc5b4 \uc788\uc744 \uc218\ub3c4 \uc788\ub2e4. \uc774\ub984\uc758 \uc218\uc640 \uc2e4\uc81c\ub85c \ub098\ub204\uc5b4\uc9c4 \ud22c\uc790 \ub300\uc0c1\uc758 \uc218\ub294 \uac19\uc9c0 \uc54a\uc744 \uc218 \uc788\ub294 \uac83\uc774\ub2e4. \ubb34\uc5c7\uc744 \ub2f4\uace0 \uc788\ub294\uc9c0 \ubaa8\ub974\uba74 \uac89\uc73c\ub85c\ub294 \ub2e4\uc591\ud55c \uc120\ud0dd\uc774 \uc548\ucabd\uc5d0\uc11c\ub294 \ube44\uc2b7\ud55c \ub178\ucd9c\uc774 \ub420 \uc218 \uc788\ub2e4. \ub530\ub77c\uc11c \ubd84\uc0b0\uc744 \uc774\ud574\ud558\ub294 \uc9c8\ubb38\uc5d0\ub294 \uad6c\uc131\uacfc \ube44\uc911\uc774 \ub4e4\uc5b4\uac04\ub2e4. \uc5b4\ub5a4 \ub300\uc0c1\uc774 \uc5bc\ub9c8\ub098 \ud070 \uc790\ub9ac\ub97c \ucc28\uc9c0\ud558\ub294\uc9c0, \uacf5\ud1b5 \uc694\uc778\uc740 \ubb34\uc5c7\uc778\uc9c0 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc774\ub294 \ud2b9\uc815 \uc0c1\ud488\uc758 \uc801\ud569\uc131\uc744 \ud3c9\uac00\ud558\ub294 \uc548\ub0b4\uac00 \uc544\ub2c8\ub77c \uc5ec\ub7ec \uc790\uc0b0\uc744 \ud568\uaed8 \ubcfc \ub54c\uc758 \uae30\ubcf8\uc801\uc778 \ub3c5\ud574 \ubc29\ubc95\uc774\ub2e4. \ubd84\uc0b0\uc758 \uc758\ubbf8\ub294 \uc5b4\ub5a4 \uc190\uc2e4\ub3c4 \uc77c\uc5b4\ub098\uc9c0 \uc54a\uac8c \ud558\ub294 \ub9c8\ubc95\uc5d0 \uc788\uc9c0 \uc54a\ub2e4. \ud55c \ub300\uc0c1\uacfc \ud55c \uc885\ub958\uc758 \uc0ac\uac74\uc5d0 \uae30\ub300\ub294 \uc815\ub3c4\ub97c \uc870\uc815\ud558\ub294 \ub370 \uc788\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc704\ud5d8\uc744 \ud568\uaed8 \ubcf4\uba70 \uc804\uccb4\uac00 \uc5b4\ub5a4 \uc601\ud5a5\uc744 \ubc1b\uc744 \uc218 \uc788\ub294\uc9c0 \uc0dd\uac01\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \ub2e4\uc591\ud55c \uc774\ub984\uc774 \uc801\ud78c \ud22c\uc790 \uc124\uba85\uc744 \ub9cc\ub098\uba74 \ubc14\uad6c\ub2c8\uc758 \uac1c\uc218\ub9cc \ubcf4\uc9c0 \ub9d0\uace0 \uadf8 \ubc14\uad6c\ub2c8\ub4e4\uc774 \uc5b4\ub514\uc5d0 \ub193\uc600\ub294\uc9c0\ub3c4 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ub2e4\ub978 \uc791\ubb3c\ub3c4 \uac19\uc740 \ub0a0\uc528\ub97c \uacaa\ub294\ub2e4. \ubd84\uc0b0\uc744 \ubc30\uc6b4\ub2e4\ub294 \uac83\uc740 \uc548\uc804\uc774\ub77c\ub294 \uc9e7\uc740 \ub9d0\ubcf4\ub2e4 \ubb34\uc5c7\uc774 \ub098\ub258\uc5c8\uace0 \ubb34\uc5c7\uc774 \uc5ec\uc804\ud788 \ud568\uaed8 \uc6c0\uc9c1\uc774\ub294\uc9c0 \ubb3b\ub294 \ub208\uc744 \uc5bb\ub294 \uc77c\uc774\ub2e4."}, {"id": "federal-reserve-1913-regions-and-credit", "title": "\uc5f0\uc900\uc758 \ud0c4\uc0dd \u2014 \uc740\ud589\uc744 \uc704\ud55c \uc740\ud589\uc740 \ub204\uac00 \uc6b4\uc601\ud574\uc57c \ud560\uae4c", "summary": "\uc5f0\ubc29\uc900\ube44\uc81c\ub3c4\uc758 \ucd9c\ubc1c\uc744 \ud1b5\ud574 \uc740\ud589\uc758 \uc720\ub3d9\uc131\uacfc \uacf5\uc801 \uac10\ub3c5\uc744 \ub458\ub7ec\uc2fc \uc124\uacc4\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "finance", "category_title": "\ub3c8\uacfc \uae08\uc735", "subcategory": "\uc740\ud589\uacfc \uc2e0\uc6a9", "categories": ["finance"], "url": "stories/federal-reserve-1913-regions-and-credit/index.html", "image": "../media/federal-reserve-1913-regions-and-credit.png", "alt": "\uc7a5\ubd80\uc640 \uc740\ud589 \ucc3d\uad6c, \uac74\ubb3c \ubc16 \uc608\uae08\uc790\ub97c \ud568\uaed8 \ubcf4\uc5ec \uc8fc\ub294 20\uc138\uae30 \ucd08 \uc740\ud589\uc758 \ubd84\uc704\uae30 \uc0bd\ud654", "text": "\uc5f0\uc900\uc758 \ud0c4\uc0dd \u2014 \uc740\ud589\uc744 \uc704\ud55c \uc740\ud589\uc740 \ub204\uac00 \uc6b4\uc601\ud574\uc57c \ud560\uae4c 1913\ub144 \ubbf8\uad6d\uc774 \uc911\uc559\uc758 \uac10\ub3c5\uacfc \uc9c0\uc5ed\uc758 \uc740\ud589\uc744 \ud568\uaed8 \ub454 \uc774\uc720 \uc5f0\ubc29\uc900\ube44\uc81c\ub3c4\uc758 \ucd9c\ubc1c\uc744 \ud1b5\ud574 \uc740\ud589\uc758 \uc720\ub3d9\uc131\uacfc \uacf5\uc801 \uac10\ub3c5\uc744 \ub458\ub7ec\uc2fc \uc124\uacc4\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc740\ud589\uacfc \uc2e0\uc6a9 \ub3c8\uacfc \uae08\uc735 \uc740\ud589\ub3c4 \ub2e4\ub978 \uc740\ud589\uc758 \ub3c4\uc6c0\uc774 \ud544\uc694\ud560 \ub54c\uac00 \uc788\ub2e4. \ub3c8\uc744 \ube4c\ub824\uc8fc\uace0 \uc608\uae08\uc744 \uad00\ub9ac\ud558\ub294 \uae30\uad00\uc774\ub77c\ub3c4 \ud544\uc694\ud55c \ud604\uae08\uc744 \uc5b8\uc81c\ub098 \ub109\ub109\ud788 \uac16\uace0 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\uae30 \ub54c\ubb38\uc774\ub2e4. \uadf8\ub807\ub2e4\uba74 \uc5ec\ub7ec \uc740\ud589\uc774 \uc5b4\ub824\uc6cc\uc9c8 \ub54c \ub204\uac00 \ub3c4\uc640\uc57c \ud560\uae4c. \ud798 \uc788\ub294 \uc740\ud589\uac00\uc758 \ud310\ub2e8\ub9cc\uc73c\ub85c \ucda9\ubd84\ud560\uae4c. 1913\ub144\uc5d0 \ub9cc\ub4e4\uc5b4\uc9c4 \ubbf8\uad6d \uc5f0\ubc29\uc900\ube44\uc81c\ub3c4\ub294 \uc774 \uc9c8\ubb38\uc744 \uc81c\ub3c4\uc758 \ubb38\uc81c\ub85c \ubc14\uafbc \uc911\uc694\ud55c \uc0ac\ub840\ub2e4. \uc624\ub298\uc740 \uae08\ub9ac\ub97c \uacb0\uc815\ud558\ub294 \uc5f0\uc900\uc774\ub77c\ub294 \uc774\ub984\uc774 \uc775\uc219\ud558\uc9c0\ub9cc, \uadf8 \uc2dc\uc791\uc744 \uc77d\uc73c\uba74 \uae08\ub9ac \uc22b\uc790 \uc774\uc804\uc5d0 \ub204\uac00 \uc5b4\ub5a4 \ubc94\uc704\uc5d0\uc11c \uae08\uc735\uc758 \ud750\ub984\uc744 \uc870\uc815\ud560\uc9c0 \uc815\ud558\ub294 \uc77c\uc774 \ubcf4\uc778\ub2e4. \uc740\ud589\uc774 \ubcf4\uc720\ud55c \uc790\uc0b0\uc5d0\ub294 \ubc14\ub85c \ud604\uae08\uc73c\ub85c \ubc14\uafb8\uae30 \uc5b4\ub824\uc6b4 \ub300\ucd9c \ub4f1\uc774 \ud3ec\ud568\ub41c\ub2e4. \uc608\uae08\uc774 \ub9ce\ub2e4\ub294 \ub9d0\ub9cc\uc73c\ub85c \uace0\uac1d\uc774 \ud55c\uaebc\ubc88\uc5d0 \ub3c8\uc744 \ucc3e\ub294 \uc0c1\ud669\uc744 \uc27d\uac8c \uac10\ub2f9\ud560 \uc218 \uc788\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc790\uc0b0\uc774 \uc788\ub294\uc9c0\uc640 \uc9c0\uae08 \uc9c0\uae09\ud560 \uc218 \uc788\ub294\uc9c0\ub294 \uc11c\ub85c \uc5f0\uacb0\ub418\uc9c0\ub9cc \uad6c\ubd84\ub418\ub294 \uc9c8\ubb38\uc774\ub2e4. \uadf8\ub798\uc11c \uc740\ud589 \uc0ac\uc774\uc758 \uc790\uae08 \uac70\ub798\uc640 \uc9c0\uc6d0\uc774 \uc911\uc694\ud574\uc9c4\ub2e4. \ud3c9\uc0c1\uc2dc\uc5d0\ub294 \uc798 \uc6c0\uc9c1\uc774\ub294 \ud750\ub984\ub3c4 \ubd88\uc548\uc774 \ucee4\uc9c0\uba74 \uc704\ucd95\ub420 \uc218 \uc788\ub2e4. \ub204\uad70\uac00 \ube4c\ub824\uc8fc\uae30\ub97c \uc8fc\uc800\ud558\uba74 \ub2e4\ub978 \uacf3\uc5d0\uc11c\ub3c4 \uc870\uc2ec\ud558\uae30 \uc2dc\uc791\ud55c\ub2e4. \ud55c \uc740\ud589\uc758 \uc7a5\ubd80 \ubc14\uae65\uc5d0 \uae08\uc735 \uc2dc\uc2a4\ud15c \uc804\uccb4\ub97c \uc0b4\ud53c\ub294 \ubb38\uc81c\uac00 \uc0dd\uae30\ub294 \uc774\uc720\ub2e4. \ud070 \uae08\uc735\uac00\ub098 \ub300\ud615 \uc740\ud589\uc774 \uc5ed\ud560\uc744 \ud560 \uc218\ub294 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc704\uae30\uc758 \ub300\ucc98\ub97c \uadf8\ub54c\uadf8\ub54c \uc601\ud5a5\ub825 \uc788\ub294 \uc0ac\ub78c\uc758 \uc758\uc9c0\uc5d0\ub9cc \ub9e1\uae34\ub2e4\uba74 \uc77c\uad00\ub41c \uaddc\uce59\uc744 \uae30\ub300\ud558\uae30 \uc5b4\ub835\ub2e4. \ub204\uad6c\ub97c \uc5b4\ub5a4 \uc870\uac74\uc73c\ub85c \ub3c4\uc6b8\uc9c0, \uadf8 \uad8c\ud55c\uc744 \ub204\uac00 \uac10\ub3c5\ud560\uc9c0\ub3c4 \ud568\uaed8 \uc815\ud574\uc57c \ud55c\ub2e4. \uae08\uc735\uc758 \uc9c8\uc11c\uac00 \uacf5\uc801\uc778 \uc124\uacc4\uc758 \ub300\uc0c1\uc774 \ub41c \uac83\uc774\ub2e4. \uc774\uac83\uc740 \uc815\ubd80\uac00 \ubaa8\ub4e0 \uc740\ud589\uc758 \uc77c\uc0c1 \uc5c5\ubb34\ub97c \uc9c1\uc811 \ub9e1\uaca0\ub2e4\ub294 \ub9d0\uacfc\ub294 \ub2e4\ub974\ub2e4. \uac1c\ubcc4 \uc740\ud589\uc774 \ud558\ub294 \uc77c\uacfc \uc740\ud589 \uc2dc\uc2a4\ud15c\uc758 \uc548\uc815\uc5d0 \ud544\uc694\ud55c \uc5ed\ud560\uc744 \ub098\ub204\ub824\ub294 \ubb38\uc81c\uc5d0 \uac00\uae5d\ub2e4. \ub2e4\ub9cc \uadf8 \uacbd\uacc4\ub294 \ucc98\uc74c\ubd80\ud130 \uc644\ubcbd\ud558\uac8c \uc815\ud574\uc9c4 \uc120\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc81c\ub3c4\ub97c \ub9cc\ub4e0 \ub4a4\uc5d0\ub3c4 \uad8c\ud55c\uacfc \ucc45\uc784\uc744 \ub450\uace0 \ub17c\uc7c1\uc774 \uc774\uc5b4\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \uc6b0\ub4dc\ub85c \uc70c\uc2a8 \ub300\ud1b5\ub839\uc740 1913\ub144 \uc5f0\ubc29\uc900\ube44\ubc95\uc5d0 \uc11c\uba85\ud588\ub2e4. \uc0c8 \uc81c\ub3c4\ub294 \uc804\uad6d\uc801\uc778 \uac10\ub3c5\uacfc \uc9c0\uc5ed\uc758 \uc900\ube44\uc740\ud589\uc744 \ud568\uaed8 \ub450\ub294 \uad6c\uc870\ub97c \ub9cc\ub4e4\uc5c8\ub2e4. \ubaa8\ub4e0 \uae30\ub2a5\uc744 \ud55c\uacf3\uc758 \ub2e8\uc77c \uc0c1\uc5c5\uc740\ud589\uc5d0 \ubab0\uc544\ub123\ub294 \ubc29\uc2dd\ub3c4, \uae30\uc874\uc758 \ubbfc\uac04 \uac70\ub798\ub9cc \uadf8\ub300\ub85c \ub450\ub294 \ubc29\uc2dd\ub3c4 \uc544\ub2c8\uc5c8\ub2e4. \uc911\uc559\uacfc \uc9c0\uc5ed\uc758 \uad00\uacc4\ub97c \uc81c\ub3c4 \uc548\uc5d0 \ub2f4\uc73c\ub824 \ud55c \uc120\ud0dd\uc774\uc5c8\ub2e4. \uc774\ub807\uac8c \uc5ec\ub7ec \ubd80\ubd84\uc744 \ud568\uaed8 \ub454 \uc774\uc720\ub97c \ub2e8\uc21c\ud788 \ube44\ud6a8\uc728\uc774\ub77c\uace0 \ud3c9\uac00\ud558\uae30 \uc804\uc5d0 \ubb34\uc5c7\uc744 \uacbd\uacc4\ud588\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uba74 \uc88b\ub2e4. \uc804\uad6d\uc758 \uae08\uc735\uc744 \uc870\uc815\ud560 \ud798\uc774 \ud544\uc694\ud558\ub354\ub77c\ub3c4 \uad8c\ub825\uc774 \ud2b9\uc815\ud55c \uacf3\uc5d0\ub9cc \ubaa8\uc774\ub294 \uc77c\uc740 \ub2e4\ub978 \uac71\uc815\uc744 \ub0b3\ub294\ub2e4. \uae08\uc735 \uc81c\ub3c4\ub294 \uacbd\uc81c\uc801 \ud544\uc694\uc640 \uad8c\ud55c\uc5d0 \ub300\ud55c \ubd88\uc2e0\uc744 \ud568\uaed8 \ub2e4\ub8e8\uae30\ub3c4 \ud55c\ub2e4. \uc5f0\ubc29\uc900\ube44\uc81c\ub3c4\uc5d0\ub294 \uc5f4\ub450 \uc9c0\uc5ed\uc758 \uc900\ube44\uc740\ud589\uc774 \ub9c8\ub828\ub418\uc5c8\ub2e4. \uc9c0\uc5ed\uc758 \uc740\ud589\ub4e4\uacfc \uad00\uacc4\ub97c \ub9fa\ub294 \uc870\uc9c1\uacfc \uc911\uc559\uc5d0\uc11c \uac10\ub3c5\ud558\ub294 \uae30\uad6c\uac00 \ud568\uaed8 \uc791\ub3d9\ud558\ub3c4\ub85d \uc124\uacc4\ud588\ub2e4. \uc9c0\uc5ed\uc758 \uc0c1\ud669\uc744 \ubc18\uc601\ud560 \uae38\uc744 \ub450\uba74\uc11c\ub3c4 \uc804\uad6d\uc801\uc778 \uae30\uc900\uc774 \ud544\uc694\ud558\ub2e4\ub294 \uc0dd\uac01\uc774 \uacf5\uc874\ud55c \uad6c\uc870\ub85c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc774\ub4e4\uc744 \uc77c\ubc18\uc778\uc774 \uc608\uae08 \ud1b5\uc7a5\uc744 \ub9cc\ub4e4\ub7ec \uac00\ub294 \ub3d9\ub124 \uc740\ud589\uacfc \ub611\uac19\uc740 \uae30\uad00\uc73c\ub85c \uc0dd\uac01\ud558\uba74 \ud63c\ub3d9\ud558\uae30 \uc27d\ub2e4. \uac1c\ubcc4 \uc740\ud589\uc758 \ud65c\ub3d9\uc744 \ub4b7\ubc1b\uce68\ud558\ub294 \uc5ed\ud560\uc774 \uc911\uc2ec\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \ubbfc\uac04 \uc740\ud589\uacfc\uc758 \uad00\uacc4\uac00 \uc788\ub2e4\uace0 \uace7\ubc14\ub85c \uc21c\uc218\ud55c \uc0ac\uae30\uc5c5\uc774\ub77c\uace0\ub9cc \ubd80\ub974\uac70\ub098, \uacf5\uc801 \uae30\ub2a5\uc774 \uc788\ub2e4\uace0 \ubcf4\ud1b5\uc758 \ud589\uc815 \ubd80\uc11c\uc640 \uac19\ub2e4\uace0 \ubd80\ub974\ub294 \uac83\ub3c4 \uc870\uc2ec\ud574\uc57c \ud55c\ub2e4. \uc740\ud589\uc774 \uc900\ube44\uc740\ud589\uc5d0\uc11c \uc790\uae08\uc744 \ub9c8\ub828\ud560 \ub54c \uc5b4\ub5a4 \uae08\ub9ac\ub97c \uc801\uc6a9\ubc1b\ub294\uc9c0\ub3c4 \uc911\uc694\ud558\ub2e4. \uadf8 \uc870\uac74\uc774 \ub2ec\ub77c\uc9c0\uba74 \uc740\ud589\ub4e4\uc758 \ucc28\uc785\uacfc \uc790\uae08 \uacf5\uae09\uc5d0 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\ub2e4. \uc2e0\ubb38\uc5d0\uc11c \ubcf4\ub294 \uc815\ucc45\uc758 \uc22b\uc790\uac00 \uc2e4\ubb3c \uacbd\uc81c\uc640 \uc774\uc5b4\uc9c0\ub294 \uae38 \uac00\uc6b4\ub370 \ud558\ub098\ub2e4. \ub2e4\ub9cc \uc870\uac74 \ud558\ub098\ub97c \ubc14\uafb8\uba74 \ubaa8\ub4e0 \ub300\ucd9c\uacfc \uc18c\ube44\uac00 \uac19\uc740 \uc18d\ub3c4\ub85c \ubc18\uc751\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc740\ud589\uc758 \ud310\ub2e8\uacfc \ucc28\uc785\uc790\uc758 \uc0ac\uc815, \uacbd\uae30\uc640 \uc2e0\ub8b0\uac00 \ud568\uaed8 \uc791\uc6a9\ud55c\ub2e4. \ub0ae\uc740 \uae08\ub9ac\ub77c\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \ub204\uad6c\ub098 \ub3c8\uc744 \ube4c\ub9ac\uace0 \uc2f6\uc5b4 \ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc81c\ub3c4\uac00 \uc601\ud5a5\uc744 \uc904 \ud1b5\ub85c\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc6d0\ud558\ub294 \uacb0\uacfc\ub97c \ud655\uc2e4\ud788 \ubcf4\uc7a5\ud55c\ub2e4\ub294 \uc8fc\uc7a5\uc740 \ub2e4\ub974\ub2e4. \uc815\ucc45\uc744 \uc77d\uc744 \ub54c\ub3c4 \uadf8 \ucc28\uc774\ub97c \uae30\uc5b5\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc5f0\ubc29\uc900\ube44\uc81c\ub3c4\ub294 \ud0c4\uc0dd\ud55c \ub4a4\uc5d0\ub3c4 \ubc95\uacfc \uc6b4\uc601 \ubc29\uc2dd\uc774 \ubc14\ub00c\uc5c8\ub2e4. \uc624\ub298\uc758 \ud68c\uc758\uc640 \uc815\ucc45 \uc218\ub2e8\uc744 1913\ub144\uc758 \uae30\uad00\uc774 \ub611\uac19\uc774 \uac16\ucd94\uace0 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc775\uc219\ud55c \ud604\uc7ac\uc758 \uc774\ub984\uc744 \uacfc\uac70\uc5d0 \ubd99\uc77c \ub54c\uc5d0\ub294 \ubb34\uc5c7\uc774 \uc774\uc5b4\uc9c0\uace0 \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc5ec\uae30\uc11c\ub294 \ucd9c\ubc1c\uc810\uc758 \uc911\uc694\ud55c \uc120\ud0dd, \uc911\uc559\uc758 \uac10\ub3c5\uacfc \uc9c0\uc5ed\uc758 \uc740\ud589\uc744 \ud568\uaed8 \ub454 \uc124\uacc4\uc5d0 \uc9d1\uc911\ud55c\ub2e4. \uae30\uad00\uc758 \uc5ed\uc0ac\ub97c \ud604\uc7ac \uc870\uc9c1\ub3c4\uc758 \uc61b\ub0a0 \uc0ac\uc9c4\ucc98\ub7fc \uc0dd\uac01\ud558\uc9c0 \uc54a\ub294 \ubc29\ubc95\uc774\ub2e4. \uc81c\ub3c4\uac00 \uc0dd\uacbc\ub2e4\ub294 \uc0ac\uac74\uacfc \uc2e4\uc81c\ub85c \uc791\ub3d9\ud558\uba70 \ub2ec\ub77c\uc84c\ub2e4\ub294 \uae34 \uc2dc\uac04\uc744 \ub098\ub204\uc5b4 \ubcf4\uba74, \uc2e4\ud328\uc640 \uc218\uc815\ub3c4 \uc5ed\uc0ac\uc758 \uc77c\ubd80\ub85c \ub4e4\uc5b4\uc628\ub2e4. \uc5f0\uc900\uc774 \uc0dd\uacbc\ub2e4\uace0 \uae08\uc735 \ubd88\uc548\uc774 \ub05d\ub09c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc81c\ub3c4\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc704\uae30\ub97c \ub9c9\uc744 \uc218\ub294 \uc5c6\ub2e4. \uadf8\ub798\ub3c4 \uc740\ud589 \uc2dc\uc2a4\ud15c\uc744 \uc720\uc9c0\ud558\ub294 \ucc45\uc784\uc744 \ub204\uad6c\uc5d0\uac8c \uc5b4\ub5bb\uac8c \ub9e1\uae38 \uac83\uc778\uc9c0 \uacf5\uac1c\uc801\uc73c\ub85c \uc815\ud55c \ubcc0\ud654\ub294 \uc911\uc694\ud588\ub2e4. \ub3c4\uc6c0\uc774 \ud544\uc694\ud55c \uc21c\uac04\uc758 \ud310\ub2e8\uc744 \uc9c0\uc18d\uc801\uc778 \uc870\uc9c1\uacfc \uaddc\uce59\uc758 \ubb38\uc81c\ub85c \ub9cc\ub4e4\uc5c8\ub2e4. \ub2e4\uc74c\uc5d0 \uae08\ub9ac \ub274\uc2a4\ub97c \ub9cc\ub098\uba74 \uc22b\uc790\uc640 \ud568\uaed8 \uadf8 \uc22b\uc790\ub97c \uc815\ud558\ub294 \uae30\uad00\uc758 \uc790\ub9ac\ub97c \ub5a0\uc62c\ub824 \ubcf4\uc790. \ub204\uac00 \uad8c\ud55c\uc744 \uac16\uace0 \ub204\uad6c\uc5d0\uac8c \ucc45\uc784\uc744 \uc9c0\ub294\uc9c0, \uc9c0\uc5ed\uacfc \uc804\uccb4\uc758 \uc0ac\uc815\uc744 \uc5b4\ub5bb\uac8c \ud568\uaed8 \ubcfc\uc9c0\ub77c\ub294 \uc9c8\ubb38\uc774 \uadf8 \ub4a4\uc5d0 \uc788\ub2e4. \uc5f0\uc900\uc758 \ud0c4\uc0dd\uc740 \ub3c8\uc758 \ud750\ub984\ub9cc\ud07c\uc774\ub098 \uae08\uc735 \uad8c\ub825\uc758 \uc124\uacc4\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\uc600\ub2e4."}, {"id": "fintech-ledgers-screens-and-financial-data", "title": "\uae08\uc735 \uc7a5\ubd80\uac00 \ud654\uba74\uc73c\ub85c \uc62e\uaca8 \uac14\uc744 \ub54c", "summary": "\uae08\uc735\uc758 \ub514\uc9c0\ud138 \uc804\ud658\uc744 \uae30\ub85d\u00b7\uc804\ub2ec\u00b7\ud655\uc778\uc774\ub77c\ub294 \uc77c\uc0c1\uc801\uc778 \uad00\uc810\uc5d0\uc11c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "finance", "category_title": "\ub3c8\uacfc \uae08\uc735", "subcategory": "\uae08\uc735\uacfc \uae30\uc220", "categories": ["finance"], "url": "stories/fintech-ledgers-screens-and-financial-data/index.html", "image": "../media/fintech-ledgers-screens-and-financial-data.png", "alt": "\uc61b \uc7a5\ubd80\uc640 \ud604\ub300 \ud734\ub300\uc804\ud654\uc758 \uac70\ub798 \ud56d\ubaa9\uc744 \ud568\uaed8 \ub193\uc544 \uae08\uc735 \uae30\ub85d\uc758 \uc804\uc790\ud654\ub97c \ud45c\ud604\ud55c \uac1c\ub150 \uc0bd\ud654", "text": "\uae08\uc735 \uc7a5\ubd80\uac00 \ud654\uba74\uc73c\ub85c \uc62e\uaca8 \uac14\uc744 \ub54c \ud3b8\ub9ac\ud574\uc9c4 \ubc84\ud2bc \ub4a4\uc5d0\uc11c \uc5ec\uc804\ud788 \uc911\uc694\ud55c \uae30\ub85d\uacfc \uc2e0\ub8b0 \uae08\uc735\uc758 \ub514\uc9c0\ud138 \uc804\ud658\uc744 \uae30\ub85d\u00b7\uc804\ub2ec\u00b7\ud655\uc778\uc774\ub77c\ub294 \uc77c\uc0c1\uc801\uc778 \uad00\uc810\uc5d0\uc11c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uae08\uc735\uacfc \uae30\uc220 \ub3c8\uacfc \uae08\uc735 \uc740\ud589 \ucc3d\uad6c\uc5d0 \uac00\uc9c0 \uc54a\uc544\ub3c4 \ud654\uba74\uc5d0\uc11c \ub0b4\uc5ed\uc744 \ud655\uc778\ud558\uace0 \uacb0\uc81c\ub97c \ud560 \uc218 \uc788\ub2e4. \uc190\uac00\ub77d\uc774 \uc6c0\uc9c1\uc774\ub294 \uac70\ub9ac\ub294 \uc9e7\uc544\uc84c\uc9c0\ub9cc \uadf8 \ub4a4\uc758 \uc77c\uae4c\uc9c0 \uc0ac\ub77c\uc9c4 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uac70\ub798\uac00 \uc788\uc5c8\ub294\uc9c0 \uc801\uace0, \ud544\uc694\ud55c \uc0ac\ub78c\uc5d0\uac8c \uc804\ub2ec\ud558\uace0, \uc798\ubabb\ub41c \uae30\ub85d\uc744 \uac00\ub824\ub0b4\ub294 \uc77c\uc740 \uacc4\uc18d\ub41c\ub2e4. \ud540\ud14c\ud06c\ub77c\ub294 \ub9d0\uc740 \uae08\uc735\uacfc \uae30\uc220\uc774 \ub9cc\ub098\ub294 \ub2e4\uc591\ud55c \uc11c\ube44\uc2a4\ub97c \ubb36\uc5b4 \ubd80\ub978\ub2e4. \uc5ec\uae30\uc11c\ub294 \ud2b9\uc815 \uc571\uc758 \uc131\uacf5\ub2f4\ubcf4\ub2e4 \uc7a5\ubd80\uc640 \uc815\ubcf4\uac00 \ud654\uba74\uc73c\ub85c \uc62e\uaca8 \uc624\uba70 \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0 \uc0b4\ud3b4\ubcf8\ub2e4. \uc624\ud508\uc2a4\ud0dd\uc2a4\uc758 \uae08\uc735\uacfc \ub370\uc774\ud130 \uc124\uba85\uc744 \ubc14\ud0d5\uc73c\ub85c, \ub208\uc5d0 \ubcf4\uc774\ub294 \ud3b8\ub9ac\ud568 \ub4a4\uc758 \uc870\uac74\uc744 \uc77d\uc5b4 \ubcf4\uc790. \ub204\uac00 \uc5bc\ub9c8\ub97c \ube4c\ub838\uace0 \ubb34\uc5c7\uc744 \uac1a\uc558\ub294\uc9c0, \uc5b4\ub290 \uac70\ub798\uac00 \ub05d\ub0ac\uace0 \uc5b4\ub5a4 \uc758\ubb34\uac00 \ub0a8\uc558\ub294\uc9c0 \uae30\ub85d\uc774 \ud544\uc694\ud558\ub2e4. \uc885\uc774\uc5d0 \uc801\ub4e0 \uc804\uc790 \ud30c\uc77c\uc5d0 \ub0a8\uae30\ub4e0 \uae30\ub85d\uc774 \uc11c\ub85c \ub9de\uc9c0 \uc54a\uc73c\uba74 \uad00\uacc4\ub3c4 \ud754\ub4e4\ub9b0\ub2e4. \uae08\uc735\uc5d0\uc11c \uc815\ubcf4\ub294 \ub098\uc911\uc5d0 \ucc38\uace0\ud558\ub294 \uc7a5\uc2dd\uc774 \uc544\ub2c8\ub77c \uac70\ub798\uc640 \ud310\ub2e8\uc744 \uc774\uc5b4 \uc8fc\ub294 \uc7ac\ub8cc\ub2e4. \uc7a5\ubd80\ub97c \ud654\uba74\uc73c\ub85c \uc62e\uae34\ub2e4\ub294 \uac83\uc740 \uc885\uc774\uc758 \uc0c9\uc744 \ubc14\uafb8\ub294 \uc77c\ub9cc\uc774 \uc544\ub2c8\ub2e4. \ucc3e\uace0 \ubcf5\uc0ac\ud558\uace0 \uc804\ub2ec\ud558\ub294 \ubc29\uc2dd\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uba40\ub9ac \uc788\ub294 \uc0ac\ub78c\uc5d0\uac8c \uac19\uc740 \uc790\ub8cc\ub97c \ubcf4\ub0b4\uae30 \uc26c\uc6cc\uc9c0\uace0, \uc5ec\ub7ec \uae30\ub85d\uc744 \ube44\uad50\ud560 \uac00\ub2a5\uc131\ub3c4 \ucee4\uc9c4\ub2e4. \uc774\uc804\uc5d0 \uc2dc\uac04\uc774 \uc624\ub798 \uac78\ub9ac\ub358 \uc77c\uc744 \ub354 \uc9e7\uac8c \ud560 \uc218 \uc788\ub2e4\ub294 \ubcc0\ud654\uac00 \uc0dd\uae34\ub2e4. \ud654\uba74\uc5d0\uc11c \ub0a0\uc9dc\uc640 \uac70\ub798\ub97c \ucc3e\uc544\ubcfc \uc218 \uc788\uc73c\uba74 \uae30\uc5b5\uc5d0\ub9cc \uc758\uc874\ud560 \uc77c\uc774 \uc904\uc5b4\ub4e0\ub2e4. \uacfc\uac70\uc758 \uc120\ud0dd\uc744 \ub2e4\uc2dc \ud655\uc778\ud558\uace0 \ub2e4\uc74c \uacc4\ud68d\uc744 \uc138\uc6b8 \uc7ac\ub8cc\uac00 \ub41c\ub2e4. \uc624\ud508\uc2a4\ud0dd\uc2a4\ub294 \uacb0\uc81c \uce74\ub4dc\uc640 \uc571\uc774 \uc9c0\ucd9c\uc758 \ucd94\uc801\uc744 \uc27d\uac8c \ud574 \uc8fc\ub294 \uc810\uc744 \uc124\uba85\ud55c\ub2e4. \ud3b8\ub9ac\ud568\uc740 \uacb0\uc81c \uc21c\uac04\ubfd0 \uc544\ub2c8\ub77c \uadf8 \ub4a4\uc758 \ud655\uc778\uc5d0\ub3c4 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ucc3e\uae30 \uc26c\uc6b4 \uae30\ub85d\uacfc \ub9de\ub294 \uae30\ub85d\uc740 \uac19\uc740 \ub73b\uc774 \uc544\ub2c8\ub2e4. \ube60\ub974\uac8c \ubcf4\uc5ec \uc8fc\uc5b4\ub3c4 \ucc98\uc74c \uc785\ub825\uc774\ub098 \ucc98\ub9ac \uacfc\uc815\uc774 \uc798\ubabb\ub418\uba74 \ud654\uba74\uc758 \uc22b\uc790\ub294 \ud2c0\ub9b4 \uc218 \uc788\ub2e4. \uc0ac\uc6a9\uc790\ub294 \uae54\ub054\ud55c \ub514\uc790\uc778\uc744 \ubcf4\uace0 \ubbff\uae30 \uc27d\uc9c0\ub9cc, \uc815\ubcf4\ub97c \uc5b4\ub5bb\uac8c \ub9cc\ub4e4\uace0 \uc720\uc9c0\ud588\ub294\uc9c0\uc758 \ubb38\uc81c\ub294 \uadf8\ubcf4\ub2e4 \ub4a4\ucabd\uc5d0 \uc788\ub2e4. \uae08\uc735 \uc815\ubcf4\ub294 \ub2f9\uc0ac\uc790 \ub458\ub9cc \uc4f0\uc9c0 \uc54a\ub294\ub2e4. \uae30\uc5c5\uc758 \uad00\ub9ac\uc790\ub294 \uc790\uae08\uacfc \uc0ac\uc5c5\uc744 \ud310\ub2e8\ud558\uace0, \uc678\ubd80\uc758 \ud22c\uc790\uc790\uc640 \uc740\ud589, \uacf5\uae09\uc790\uc640 \uac10\ub3c5 \uae30\uad00\ub3c4 \uc790\ub8cc\ub97c \uc0b4\ud540\ub2e4. \uac19\uc740 \ud68c\uc0ac\uc758 \uae30\ub85d\ub3c4 \uc5b4\ub5a4 \uacb0\uc815\uc744 \ud574\uc57c \ud558\ub294\uc9c0\uc5d0 \ub530\ub77c \ub2e4\ub978 \ubd80\ubd84\uc774 \uc911\uc694\ud574\uc9c4\ub2e4. \uc815\ubcf4\uac00 \ub9ce\uc544\uc84c\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc9c8\ubb38\uae4c\uc9c0 \uac19\uc544\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc804\uc790\ud654\ub294 \uc774\ub7f0 \uc804\ub2ec\uc744 \ube60\ub974\uac8c \ub9cc\ub4e0\ub2e4. \ub3d9\uc2dc\uc5d0 \uc5b4\ub290 \uc790\ub8cc\uac00 \ucd5c\uc2e0\uc774\uace0 \uc11c\ub85c \uac19\uc740 \uae30\uc900\uc73c\ub85c \uc815\ub9ac\ub418\uc5c8\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\ub3c4 \ucee4\uc9c4\ub2e4. \ud30c\uc77c\uc774 \uc27d\uac8c \ub298\uc5b4\ub0a0\uc218\ub85d \ub9de\ub294 \uc22b\uc790\ub97c \ud55c\uacf3\uc5d0\uc11c \ud568\uaed8 \uc774\ud574\ud558\ub294 \uc77c\uc774 \uc911\uc694\ud574\uc9c4\ub2e4. \ubcf5\uc0ac\ub97c \uc798\ud558\ub294 \uae30\uc220\uacfc \ub73b\uc744 \ub9de\ucd94\ub294 \uc77c\uc740 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc9c0\ub9cc \ub3d9\uc77c\ud558\uc9c0 \uc54a\ub2e4. \uc61b \ubb38\uc11c\uc5d0\ub294 \uc791\uc131\ud55c \ub0a0\uc9dc\uc640 \uc11c\uba85, \ub0a8\uaca8 \ub454 \uc0ac\ubcf8\uc774 \uc911\uc694\ud55c \ud754\uc801\uc774\uc5c8\ub2e4. \ub514\uc9c0\ud138 \ud658\uacbd\uc5d0\uc11c\ub294 \ud30c\uc77c\uacfc \uba54\uc2dc\uc9c0, \ucc98\ub9ac \uae30\ub85d \uac19\uc740 \ub2e4\ub978 \ud754\uc801\uc774 \ub0a8\ub294\ub2e4. \uad50\uc7ac\ub294 \uc774\ub97c \uc804\uc790\uc801\uc778 \ubb38\uc11c\uc758 \uc790\ucde8\ub85c \uc124\uba85\ud55c\ub2e4. \uc815\ubcf4\uac00 \uc5b4\ub5a4 \uc808\ucc28\ub97c \uac70\ucce4\ub294\uc9c0 \ud655\uc778\ud558\uace0 \uacf5\uc720\ud558\ub294 \ubc29\uc2dd\uc774 \ubc14\ub010 \uac83\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \ub514\uc9c0\ud138 \uc11c\ube44\uc2a4\uac00 \uc790\ub3d9\uc73c\ub85c \uc644\ubcbd\ud55c \uc99d\uac70\ub97c \ub0a8\uae34\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc744 \uae30\ub85d\ud558\uace0 \uc5bc\ub9c8\ub098 \ubcf4\uad00\ud558\uba70 \ub204\uac00 \ubcfc \uc218 \uc788\ub294\uc9c0\ub294 \ubcc4\ub3c4\uc758 \uc120\ud0dd\uc774\ub2e4. \ud654\uba74\uc5d0\uc11c \ub0b4\uc5ed\uc774 \ubcf4\uc778\ub2e4\ub294 \uac83\uacfc \uc0ac\uc6a9\uc790\uac00 \ubaa8\ub4e0 \ucc98\ub9ac \uacfc\uc815\uc744 \ud655\uc778\ud560 \uc218 \uc788\ub2e4\ub294 \uac83\ub3c4 \ub2e4\ub974\ub2e4. \ud754\uc801\uc758 \ud615\uc2dd\uc774 \ub2ec\ub77c\uc84c\ub2e4\uace0 \uc2e0\ub8b0\ub97c \ub530\uc9c8 \uc77c\uc774 \ub05d\ub098\uc9c0\ub294 \uc54a\ub294\ub2e4. \uae30\uc5c5\uc740 \ub354 \uc815\ud655\ud558\uace0 \uc2dc\uc758\uc801\uc808\ud55c \uc790\ub8cc\ub97c \uc5bb\uc73c\uba74 \uc608\uc0b0\uacfc \ud22c\uc790, \ube44\uc6a9\uc744 \ub2e4\uc2dc \uc0b4\ud544 \uc218 \uc788\ub2e4. \uc608\uc804\uc5d0\ub294 \ud568\uaed8 \ubcf4\uae30 \uc5b4\ub824\uc6e0\ub358 \uc218\ub9ce\uc740 \ud56d\ubaa9\uc744 \ubd84\uc11d\ud558\ub294 \uc77c\ub3c4 \uac00\ub2a5\ud574\uc9c4\ub2e4. \ub370\uc774\ud130\uac00 \uc911\uc694\ud558\ub2e4\ub294 \ub9d0\uc5d0\ub294 \uc774\ub7f0 \ud604\uc2e4\uc801\uc778 \uc774\uc810\uc774 \uc788\ub2e4. \ub290\ub08c\ub9cc\uc73c\ub85c \ud310\ub2e8\ud558\ub358 \ubd80\ubd84\uc744 \ud655\uc778\ud560 \uae30\ud68c\uac00 \ub298\uc5b4\ub09c\ub2e4. \ud558\uc9c0\ub9cc \uc790\ub8cc\uac00 \ub9ce\uc73c\uba74 \uc5b8\uc81c\ub098 \uc88b\uc740 \uacb0\uc815\uc774 \ub098\uc628\ub2e4\ub294 \uacf5\uc2dd\uc740 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc744 \uce21\uc815\ud588\ub294\uc9c0, \ube60\uc9c4 \uac83\uc740 \uc5c6\ub294\uc9c0, \uac19\uc740 \uc22b\uc790\ub97c \uc5b4\ub5a4 \ub73b\uc73c\ub85c \uc77d\ub294\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \uacfc\uac70\uc758 \uae30\ub85d\uacfc \ubbf8\ub798\uc758 \uac00\uce58\ub97c \uadf8\ub300\ub85c \uac19\ub2e4\uace0 \ubcfc \uc218\ub3c4 \uc5c6\ub2e4. \ube60\ub978 \uacc4\uc0b0\uc740 \uc88b\uc740 \uc9c8\ubb38\uc744 \ub300\uc2e0\ud558\uc9c0 \ubabb\ud55c\ub2e4. \ud074\ub77c\uc6b0\ub4dc \uac19\uc740 \ubcf4\uad00 \ubc29\uc2dd\uc740 \uc790\ub8cc\ub97c \ud544\uc694\ud55c \ub9cc\ud07c \uc800\uc7a5\ud558\uace0 \uc5ec\ub7ec \uc7a5\uc18c\uc5d0\uc11c \uc774\uc6a9\ud558\uae30 \uc27d\uac8c \ub9cc\ub4e0\ub2e4. \uc720\uc9c0\uc640 \uad00\ub9ac\uc758 \uc77c\ubd80\ub97c \uc804\ubb38\uc801\uc778 \uc11c\ube44\uc2a4\uc5d0 \ub9e1\uae38 \uc218\ub3c4 \uc788\ub2e4. \uc791\uc740 \uc870\uc9c1\ub3c4 \ud070 \uc7a5\ube44\ub97c \uc9c1\uc811 \ubaa8\ub450 \uac16\ucd94\uc9c0 \uc54a\uace0 \uc790\ub8cc\ub97c \ub2e4\ub8f0 \uc218 \uc788\ub2e4\ub294 \uc7a5\uc810\uc774 \uc0dd\uae34\ub2e4. \ubc18\uba74 \ub204\uac00 \uc815\ubcf4\ub97c \ubc14\uafb8\uac70\ub098 \uc9c0\uc6b8 \uc218 \uc788\ub294\uc9c0, \uad8c\ud55c \uc5c6\ub294 \uc811\uadfc\uc744 \uc5b4\ub5bb\uac8c \ub9c9\ub294\uc9c0\ub294 \uacc4\uc18d \uc911\uc694\ud558\ub2e4. \ub514\uc9c0\ud138\ud654\uc758 \uc5ed\uc0ac\ub294 \ud3b8\ub9ac\ud568\uacfc \ubcf4\uc548\uc758 \uc5ed\uc0ac\uac00 \ud568\uaed8 \uc6c0\uc9c1\uc774\ub294 \uacfc\uc815\uc774\ub2e4. \uc774\uac83\uc740 \ub9c9\uc5f0\ud788 \uae30\uc220\uc744 \ubb34\uc11c\uc6cc\ud558\uc790\ub294 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \uc11c\ube44\uc2a4\ub97c \ud3b8\ub9ac\ud558\uac8c \ub9cc\ub4dc\ub294 \uc870\uac74\uc5d0 \uc815\ubcf4\uc758 \ubcf4\ud638\ub3c4 \ud3ec\ud568\ub41c\ub2e4\ub294 \ub73b\uc774\ub2e4. \uc0ac\uc6a9\uc790\uc5d0\uac8c\ub294 \ud55c \ud654\uba74 \uc548\uc758 \uacbd\ud5d8\uc774\uc5b4\ub3c4 \uadf8 \ub4a4\uc5d0\ub294 \ub2e4\ub978 \uc5ed\ud560\uc758 \uae30\uad00\uacfc \uc11c\ube44\uc2a4\uac00 \uc788\uc744 \uc218 \uc788\ub2e4. \uacb0\uc81c\uc758 \uc811\uc810, \uc815\ubcf4\ub97c \uc815\ub9ac\ud558\ub294 \ub3c4\uad6c, \uc790\uae08\uc744 \ub2e4\ub8e8\ub294 \uae30\uad00\uc758 \uae30\ub2a5\uc744 \ubb34\uc870\uac74 \uac19\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uc774\ud574\uac00 \uc5b4\ub824\uc6cc\uc9c4\ub2e4. \ud540\ud14c\ud06c\ub97c \ub9d0\ud560 \ub54c\uc5d0\ub294 \uc5b4\ub5a4 \uc77c\uc744 \uae30\uc220\ub85c \ubc14\uafbc \uac83\uc778\uc9c0 \uad6c\uccb4\uc801\uc73c\ub85c \ubcf4\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc774 \uae00\uc740 \ud2b9\uc815 \uc11c\ube44\uc2a4\uc758 \uc608\uae08 \ubcf4\ud638\ub098 \ucc45\uc784 \ubc94\uc704\ub97c \ud310\ub2e8\ud558\ub824\ub294 \uc548\ub0b4\uac00 \uc544\ub2c8\ub2e4. \uadf8\ub7f0 \uc870\uac74\uc740 \uac1c\ubcc4 \uc11c\ube44\uc2a4\uc640 \uc81c\ub3c4\uc5d0 \ub530\ub77c \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uc5ec\uae30\uc11c \uc77d\ub294 \uac83\uc740 \uae08\uc735\uc758 \ubaa8\ub4e0 \uae30\ub2a5\uc774 \uc571\uc774\ub77c\ub294 \ud55c \ubb3c\uac74\uc73c\ub85c \ubc14\ub00c\uc5c8\ub2e4\uae30\ubcf4\ub2e4, \uae30\ub85d\uacfc \uc804\ub2ec\uc758 \uc5ec\ub7ec \uce35\uc774 \uc0c8 \ubc29\uc2dd\uc73c\ub85c \uc5f0\uacb0\ub418\uc5c8\ub2e4\ub294 \ubcc0\ud654\ub2e4. \uc7a5\ubd80\uc5d0\uc11c \ud654\uba74\uc73c\ub85c \ubc14\ub00c\ub294 \ub3d9\uc548 \uae08\uc735\uc740 \ud6e8\uc52c \uc190\uc27d\uac8c \ub2ff\uc744 \uc218 \uc788\ub294 \uc77c\uc774 \ub418\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \ub0b4\uac00 \ubcf4\uace0 \uc788\ub294 \uae30\ub85d\uc774 \ub9de\ub294\uc9c0, \uadf8 \uc815\ubcf4\ub97c \ub204\uac00 \ub2e4\ub8e8\ub294\uc9c0, \ubb38\uc81c\uac00 \uc0dd\uae30\uba74 \uc5b4\ub5bb\uac8c \ud655\uc778\ud560\uc9c0\uc758 \uc9c8\ubb38\uc740 \ub0a8\ub294\ub2e4. \ub3c4\uad6c\uac00 \uc0c8\ub85c\uc6cc\uc838\ub3c4 \uc57d\uc18d\uc744 \ud568\uaed8 \ubbff\uc744 \uc870\uac74\uc740 \uacc4\uc18d \ud544\uc694\ud558\ub2e4. \ub2e4\uc74c\uc5d0 \uac70\ub798 \ub0b4\uc5ed\uc744 \ud3bc\uccd0 \ubcfc \ub54c \uc22b\uc790\ub9cc\uc774 \uc544\ub2c8\ub77c \uadf8 \uc22b\uc790\uac00 \ucc3e\uc544\uc624\uae30\uae4c\uc9c0\uc758 \uae38\ub3c4 \uc7a0\uae50 \uc0dd\uac01\ud574 \ubcf4\uc790. \uc801\uace0 \ubcf4\uad00\ud558\uace0 \uc804\ud558\uace0 \ube44\uad50\ud558\ub294 \uc77c\ub4e4\uc774 \uc791\uc740 \ud654\uba74 \uc548\uc5d0 \ubaa8\uc5ec \uc788\ub2e4. \ud540\ud14c\ud06c\uc758 \ubcc0\ud654\ub294 \ub3c8\uc774 \ub9c8\ubc95\ucc98\ub7fc \uac00\ubcbc\uc6cc\uc84c\ub2e4\ub294 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub77c, \uae08\uc735\uc758 \uc624\ub798\ub41c \uc815\ubcf4 \uc791\uc5c5\uc774 \ub2e4\ub978 \uc18d\ub3c4\uc640 \ud615\ud0dc\ub97c \uc5bb\uc740 \uc774\uc57c\uae30\ub2e4."}, {"id": "gold-silver-debate-debt-and-prices", "title": "\uae08\uacfc \uc740 \u2014 \uc5b4\ub5a4 \uae08\uc18d\uc744 \ub3c8\uc73c\ub85c \uc4f8\uc9c0\uac00 \uc0dd\uacc4\uc758 \ubb38\uc81c\uac00 \ub418\uc5c8\ub2e4", "summary": "\uae08\ubcf8\uc704\uc640 \uc740\ud654 \ud655\ub300\ub97c \ub458\ub7ec\uc2fc \ub17c\uc7c1\uc744 \ub530\ub77c \ub3c8\uc758 \uaddc\uce59\uc774 \uc0ac\ub78c\ub9c8\ub2e4 \ub2e4\ub974\uac8c \ub290\uaef4\uc9c0\ub294 \uc774\uc720\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "finance", "category_title": "\ub3c8\uacfc \uae08\uc735", "subcategory": "\ub3c8\uacfc \ud654\ud3d0", "categories": ["finance"], "url": "stories/gold-silver-debate-debt-and-prices/index.html", "image": "../media/gold-silver-debate-debt-and-prices.jpg", "alt": "\uae08\uacfc \uc740\uc744 \ub458\ub7ec\uc2fc \ud654\ud3d0 \uc81c\ub3c4\uc758 \ub17c\uc7c1\uc744 \ud48d\uc790\ud55c \uc61b \uc778\uc1c4 \uadf8\ub9bc", "text": "\uae08\uacfc \uc740 \u2014 \uc5b4\ub5a4 \uae08\uc18d\uc744 \ub3c8\uc73c\ub85c \uc4f8\uc9c0\uac00 \uc0dd\uacc4\uc758 \ubb38\uc81c\uac00 \ub418\uc5c8\ub2e4 19\uc138\uae30 \ub9d0 \ud654\ud3d0 \ub17c\uc7c1\uc5d0\uc11c \ub9cc\ub098\ub294 \ube5a\uacfc \ubb3c\uac00\uc758 \uc11c\ub85c \ub2e4\ub978 \uc5bc\uad74 \uae08\ubcf8\uc704\uc640 \uc740\ud654 \ud655\ub300\ub97c \ub458\ub7ec\uc2fc \ub17c\uc7c1\uc744 \ub530\ub77c \ub3c8\uc758 \uaddc\uce59\uc774 \uc0ac\ub78c\ub9c8\ub2e4 \ub2e4\ub974\uac8c \ub290\uaef4\uc9c0\ub294 \uc774\uc720\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ub3c8\uacfc \ud654\ud3d0 \ub3c8\uacfc \uae08\uc735 \ub611\uac19\uc774 \uc77c\ud588\ub294\ub370 \ub18d\uc0b0\ubb3c\uc744 \ud314\uc544 \ubc1b\ub294 \ub3c8\uc740 \uc904\uc5c8\ub2e4. \uadf8\ub7f0\ub370 \uac1a\uc544\uc57c \ud560 \ube5a\uc758 \uc22b\uc790\ub294 \uadf8\ub300\ub85c\ub2e4. \uc774\ub7f0 \uc0c1\ud669\uc5d0\uc11c \ub3c8\uc758 \uac00\uce58\ub97c \ub2e8\ub2e8\ud558\uac8c \uc9c0\ud0a4\uc790\ub294 \ub9d0\uc740 \uc0ac\ub78c\ub9c8\ub2e4 \ub2e4\ub974\uac8c \ub4e4\ub9b0\ub2e4. 19\uc138\uae30 \ub9d0 \ubbf8\uad6d\uc5d0\uc11c \uae08\uacfc \uc740\uc758 \ub17c\uc7c1\uc774 \uc815\uce58\uc758 \uc911\uc2ec\uc5d0 \ub4e4\uc5b4\uc628 \ub370\uc5d0\ub294 \uc774\ub7f0 \uc0dd\ud65c\uc758 \ubb38\uc81c\uac00 \uc788\uc5c8\ub2e4. \uc624\ub298\uc758 \ub208\uc5d0\ub294 \uae08\uc18d \ub450 \uac00\uc9c0\ub97c \ub450\uace0 \uc65c \uadf8\ub807\uac8c \uaca9\ub82c\ud558\uac8c \ub2e4\ud22c\uc5c8\ub294\uc9c0 \ub0af\uc124 \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \ub17c\uc7c1\uc758 \ud575\uc2ec\uc740 \ubc18\uc9dd\uc774\ub294 \uc7ac\ub8cc\uc758 \ucde8\ud5a5\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ub3c8\uc744 \uc5b4\ub5a4 \uae30\uc900\uc5d0 \uc5f0\uacb0\ud558\uace0 \uc5bc\ub9c8\ub098 \uacf5\uae09\ud560\uc9c0, \uadf8 \ubcc0\ud654\uc758 \ubd80\ub2f4\uc744 \ub204\uac00 \uc9c8\uc9c0\uc5d0 \uad00\ud55c \uc2f8\uc6c0\uc774\uc5c8\ub2e4. \uae08\ubcf8\uc704\ub294 \ub3c8\uc758 \ub2e8\uc704\uc640 \uae08 \uc0ac\uc774\uc5d0 \uc815\ud574\uc9c4 \uad00\uacc4\ub97c \ub450\ub294 \uc81c\ub3c4\ub2e4. \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uc5b8\uc81c\ub098 \uae08\ud654\ub9cc \ub4e4\uace0 \ub2e4\ub154\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc885\uc774\ub85c \ub41c \ub3c8\uacfc \uc740\ud589\uc758 \uac70\ub798\ub3c4 \uc874\uc7ac\ud560 \uc218 \uc788\uc9c0\ub9cc \uadf8 \uc2e0\ub8b0\uc758 \uae30\uc900\uc5d0 \uae08\uacfc\uc758 \uad00\uacc4\uac00 \ub193\uc778\ub2e4. \ub2f9\uc2dc\uc758 \ud654\ud3d0 \ub17c\uc7c1\uc744 \ud604\ub300\uc758 \uc9c0\ud3d0 \uc0c9\uae54\uc744 \uc815\ud558\ub294 \uc77c\uacfc \ud63c\ub3d9\ud558\uc9c0 \uc54a\uc544\uc57c \ud55c\ub2e4. \uae08\uc5d0 \uc5f0\uacb0\ub41c \uaddc\uce59\uc740 \uc57d\uc18d\uc744 \uc548\uc815\uc2dc\ud0a4\ub294 \uc7a5\uc810\uc774 \uc788\ub2e4\uace0 \uc5ec\uaca8\uc84c\ub2e4. \ubc18\uba74 \uacbd\uc81c\uac00 \ubcc0\ud558\uace0 \ub3c8\uc774 \ub354 \ud544\uc694\ud55c \uc0c1\ud669\uc5d0\uc11c \uacf5\uae09\uc744 \uc720\uc5f0\ud558\uac8c \ub298\ub9ac\uae30 \uc5b4\ub835\ub2e4\ub294 \ubb38\uc81c\uac00 \ub17c\uc7c1\uc744 \ubd88\ub800\ub2e4. \uc81c\ud55c\uc774 \uc788\ub2e4\ub294 \uc810\uc744 \ub204\uad70\uac00\ub294 \uc2e0\ub8b0\uc758 \uadfc\uac70\ub85c \ubcf4\uace0 \ub2e4\ub978 \ub204\uad70\uac00\ub294 \uc0dd\ud65c\uc744 \uc555\ubc15\ud558\ub294 \uc870\uac74\uc73c\ub85c \ubcf8 \uc148\uc774\ub2e4. \uc7a5\ubc14\uad6c\ub2c8 \uac12\uc774 \ub0b4\ub824\uac00\uba74 \uc18c\ube44\uc790\ub294 \ubc18\uae38 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc0c1\ud488\uc744 \ud314\uc544 \ube5a\uc744 \uac1a\uc544\uc57c \ud558\ub294 \uc0ac\ub78c\uc740 \ub2e4\ub978 \uacbd\ud5d8\uc744 \ud55c\ub2e4. \uac1a\uc744 \uc561\uc218\ub294 \uc77c\uc815\ud55c\ub370 \ud310\ub9e4 \uc218\uc785\uc774 \uc904\uc5b4\ub4e4\uba74 \uac19\uc740 \ube5a\uc744 \uc704\ud574 \ub354 \ub9ce\uc740 \ubb3c\uac74\uc744 \ud314\uc544\uc57c \ud560 \uc218 \uc788\ub2e4. \uac12\uc2fc \ubb3c\uac74\uc774\ub77c\ub294 \ub9d0\uacfc \uac00\ubcbc\uc6cc\uc9c4 \ubd80\ucc44\ub77c\ub294 \ub9d0\uc740 \uac19\uc9c0 \uc54a\ub2e4. \ubb3c\ub860 \ub2f9\uc2dc \ub18d\ubbfc\uc758 \uc5b4\ub824\uc6c0\uc744 \ud654\ud3d0 \uc81c\ub3c4 \ud558\ub098\ub85c \uc804\ubd80 \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc6b4\uc1a1\ube44\uc640 \ub300\ucd9c \uc870\uac74, \uc0dd\uc0b0\uacfc \uc2dc\uc7a5\uc758 \ubcc0\ud654\ub3c4 \uc5bd\ud600 \uc788\uc5c8\ub2e4. \uadf8 \uc5ec\ub7ec \ubb38\uc81c \uac00\uc6b4\ub370 \ub3c8\uc758 \uacf5\uae09\uacfc \ubb3c\uac00\uac00 \uc911\uc694\ud55c \uc7c1\uc810\uc774 \ub418\uc5c8\ub2e4\ub294 \ubc94\uc704\ub85c \uc774\ud574\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc0dd\ud65c\uc758 \uace0\ud1b5\uc5d0\ub294 \ud55c \uac00\uc9c0 \uc6d0\uc778\ub9cc \uc788\ub294 \uacbd\uc6b0\uac00 \ub4dc\ubb3c\ub2e4. \uc740\ud654\uc758 \uc8fc\uc870\ub97c \ub113\ud788\uc790\ub294 \uc9c0\uc9c0\uc790\ub4e4\uc740 \uc720\ud1b5\ub418\ub294 \ub3c8\uc774 \ub298\uc5b4\ub098\uae30\ub97c \ubc14\ub790\ub2e4. \ub3c8\uc774 \ub354 \ud480\ub9ac\uace0 \ub18d\uc0b0\ubb3c \uac00\uaca9\uc774 \uc624\ub974\uba74 \ube5a\uc758 \ubd80\ub2f4\uc5d0\uc11c \ubc97\uc5b4\ub098\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\ub2e4\uace0 \uae30\ub300\ud588\ub2e4. \uc774\uac83\uc740 \ub204\uad6c\uc5d0\uac8c\ub098 \uac19\uc740 \uc774\uc775\uc774 \uc0dd\uae34\ub2e4\ub294 \ubc95\uce59\uc774 \uc544\ub2c8\ub77c \ud2b9\uc815\ud55c \ucc98\uc9c0\uc758 \uc0ac\ub78c\ub4e4\uc774 \uc81c\uc2dc\ud55c \ud574\uacb0 \ubc29\ud5a5\uc774\uc5c8\ub2e4. \uc740\uc758 \uc0ac\uc6a9\uc744 \ub298\ub9ac\ub294 \ubb38\uc81c\uc5d0\ub294 \uc5b4\ub5a4 \ube44\uc728\uacfc \uaddc\uce59\uc73c\ub85c \uae08\uacfc \uc740\uc744 \ub2e4\ub8f0\uc9c0\ub3c4 \ub530\ub77c\ubd99\uc5c8\ub2e4. \ub450 \uae08\uc18d\uc744 \ud568\uaed8 \uc4f0\uaca0\ub2e4\ub294 \uc120\uc5b8\ub9cc\uc73c\ub85c \uc2dc\uc7a5\uc758 \uac00\uaca9\uacfc \uc81c\ub3c4\uc758 \uac00\uaca9\uc774 \uc800\uc808\ub85c \uac19\uc544\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc190\uc26c\uc6cc \ubcf4\uc774\ub294 \uad6c\ud638 \ub4a4\uc5d0\ub3c4 \uc2e4\uc81c \ud654\ud3d0 \uc81c\ub3c4\ub97c \uc6b4\uc601\ud558\ub294 \uc5b4\ub824\uc6b4 \uc120\ud0dd\uc774 \ub0a8\uc544 \uc788\uc5c8\ub2e4. \ub3c8\uc744 \ube4c\ub824\uc900 \uc0ac\ub78c\uc740 \ub098\uc911\uc5d0 \ubc1b\ub294 \ub3c8\uc758 \uad6c\ub9e4\ub825\uc774 \uc57d\ud574\uc9c8 \uc218 \uc788\ub2e4\ub294 \uc810\uc744 \uac71\uc815\ud560 \uc218 \uc788\ub2e4. \uc678\uad6d\uacfc \uac70\ub798\ud558\ub294 \uc0ac\uc5c5\uc790\uc5d0\uac8c\ub294 \uacb0\uc81c\uc758 \uc548\uc815\ub3c4 \uc911\uc694\ud588\ub2e4. \uac19\uc740 \uc81c\ub3c4\uc758 \ubcc0\ud654\ub97c \ub450\uace0 \ud55c\ucabd\uc774 \uc228\ud1b5\uc744 \ud2d4\uc6b0\ub294 \uc77c\uc774\ub77c\uace0 \ub9d0\ud560 \ub54c \ub2e4\ub978 \ucabd\uc740 \uc57d\uc18d\uc774 \ud754\ub4e4\ub9ac\ub294 \uc77c\uc774\ub77c\uace0 \ub290\ub084 \uc218 \uc788\ub2e4. \uc774\ud574\uad00\uacc4\uac00 \ub2e4\ub974\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uace7\ubc14\ub85c \uc5b4\ub290 \ud55c\ucabd\uc758 \ub3c4\ub355\uc801 \uacb0\ud568\uc73c\ub85c \uc124\uba85\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8\ub807\ub2e4\uace0 \ud798\uc758 \ucc28\uc774\uae4c\uc9c0 \uc5c6\ub294 \uac83\uc73c\ub85c \uc5ec\uaca8\uc11c\ub3c4 \uc548 \ub41c\ub2e4. \uc790\uc2e0\uc758 \ucc98\uc9c0\ub97c \uc815\uce58\uc758 \uc758\uc81c\ub85c \ub9cc\ub4e4 \uc218 \uc788\ub294 \ub2a5\ub825\uc740 \uac19\uc9c0 \uc54a\uc558\ub2e4. \ub3c8\uc758 \ub17c\uc7c1\uc5d0\uc11c\ub294 \uacbd\uc81c\uc801 \uc190\uc775\uacfc \ubaa9\uc18c\ub9ac\uc758 \ud06c\uae30\uac00 \ud568\uaed8 \uc6c0\uc9c1\uc600\ub2e4. 1890\ub144\uc758 \uc154\uba3c \uc740 \uad6c\ub9e4\ubc95\uc740 \uc815\ubd80\uc758 \uc740 \uad6c\ub9e4\ub97c \ub298\ub9ac\ub294 \uc870\uce58\uc600\ub2e4. \ub2e4\ub9cc \uc774\ub97c \ubaa8\ub4e0 \uc740\uc744 \ubb34\uc81c\ud55c\uc73c\ub85c \uc6d0\ud558\ub294 \ube44\uc728\uc5d0 \uc8fc\uc870\ud574 \uc8fc\ub294 \uc81c\ub3c4\uc640 \uac19\uc740 \uac83\uc73c\ub85c \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uc5b4\ub290 \ubc94\uc704\uc5d0\uc11c \ubb34\uc5c7\uc744 \ub298\ub9ac\ub294\uc9c0\uc5d0 \ub530\ub77c \uc2e4\uc81c \ud6a8\uacfc\ub294 \ub2ec\ub77c\uc9c4\ub2e4. \uc815\uce58\uc801 \uad6c\ud638\uc640 \ubc95\uc758 \uad6c\uccb4\uc801 \ub0b4\uc6a9\uc740 \uad6c\ubd84\ud574\uc11c \uc77d\uc5b4\uc57c \ud55c\ub2e4. \uc815\ubd80\uac00 \uc740\uc744 \uc0ac\ub4e4\uc774\ub294 \ub370 \uc0ac\uc6a9\ud55c \ub3c8\uc774 \ub2e4\uc2dc \uae08\uc73c\ub85c \uad50\ud658\ub418\uba74\uc11c \uae08 \ubcf4\uc720\ub97c \uc555\ubc15\ud558\ub294 \ubb38\uc81c\ub3c4 \uc0dd\uacbc\ub2e4. 1893\ub144\uc5d0\ub294 \uadf8 \uad6c\ub9e4 \uc870\ud56d\uc774 \ud3d0\uc9c0\ub418\uc5c8\ub2e4. \uc644\ud654\ucc45\uc744 \uc2dc\ud589\ud588\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ub18d\ubbfc\uc758 \uc5b4\ub824\uc6c0\uc774 \ud574\uacb0\ub418\uc9c0\ub294 \uc54a\uc558\ub2e4. \uc81c\ub3c4\ub97c \ubc14\uafb8\uba74 \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc774 \uadf8 \uaddc\uce59\uc5d0 \ub9de\ucd94\uc5b4 \ud589\ub3d9\ud55c\ub2e4\ub294 \uc810\ub3c4 \ub4dc\ub7ec\ub0ac\ub2e4. \ub2f9\uc2dc\uc758 \ud654\ud3d0 \ub17c\uc7c1\uc740 \uadf8\ub9bc\uacfc \uc5f0\uc124\uc744 \ud1b5\ud574 \ub110\ub9ac \uc804\ub2ec\ub418\uc5c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc61b \ud48d\uc790\ud654\ub3c4 \ubcf5\uc7a1\ud55c \ubb38\uc81c\ub97c \uc54c\uc544\ubcf4\uae30 \uc26c\uc6b4 \uc7a5\uba74\uc73c\ub85c \ubc14\uafbc \uc790\ub8cc\ub2e4. \uc5b4\ub290 \ucabd\uc758 \uc870\uac74\uc774 \ub354 \uacf5\ud3c9\ud55c\uc9c0, \ub204\uac00 \ud61c\ud0dd\uc744 \ub204\ub9ac\ub294\uc9c0\ub97c \ub3c5\uc790\uac00 \ud2b9\uc815\ud55c \ubc29\ud5a5\uc73c\ub85c \ubcf4\uac8c \ub9cc\ub4e0\ub2e4. \uadf8\ub9bc\uc740 \uc22b\uc790\ub97c \uc124\uba85\ud558\uba74\uc11c \ub9c8\uc74c\uc744 \uc6c0\uc9c1\uc774\ub824 \ud588\ub2e4. \uc774\ub7f0 \uc790\ub8cc\ub97c \ubcfc \ub54c\ub294 \ubb34\uc5c7\uc744 \ubcf4\uc5ec \uc8fc\uace0 \ubb34\uc5c7\uc744 \uc0dd\ub7b5\ud588\ub294\uc9c0 \ud568\uaed8 \ubb3b\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uae08\uacfc \uc740 \uc911 \ud558\ub098\ub97c \uace0\ub974\uba74 \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \uc0ac\uc815\uc774 \uc88b\uc544\uc9c4\ub2e4\ub294 \uadf8\ub9bc\uc740 \ud604\uc2e4\uc744 \ucda9\ubd84\ud788 \ub2f4\uc9c0 \ubabb\ud55c\ub2e4. \ub2f9\ub300\uc758 \uc8fc\uc7a5\uacfc \uc2e4\uc81c \uacb0\uacfc\ub97c \uad6c\ubd84\ud574\uc57c \ud48d\uc790\uac00 \ud765\ubbf8\ub85c\uc6b4 \uc0ac\ub8cc\uac00 \ub418\uba74\uc11c\ub3c4 \uacbd\uc81c\uc758 \uc815\ub2f5\uc744 \ub300\uc2e0\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc774 \ub17c\uc7c1\uc744 \uc77d\ub294\ub2e4\uace0 \uc624\ub298\uc758 \ud22c\uc790 \uc885\ubaa9\uc744 \uace0\ub97c \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ud788\ub824 \ud654\ud3d0\uc758 \uac00\uce58\ub97c \uc9c0\ud0a8\ub2e4\ub294 \ub9d0 \uc18d\uc5d0 \uc5ec\ub7ec \uacbd\ud5d8\uc774 \ub4e4\uc5b4 \uc788\uc74c\uc744 \ubcf4\uac8c \ub41c\ub2e4. \uc800\ucd95\ud558\ub294 \uc0ac\ub78c\uacfc \ube5a\uc9c4 \uc0ac\ub78c, \uc784\uae08\uc73c\ub85c \uc0ac\ub294 \uc0ac\ub78c\uacfc \uc0c1\ud488\uc744 \ud30c\ub294 \uc0ac\ub78c\uc5d0\uac8c \uac19\uc740 \ubb3c\uac00 \ubcc0\ud654\uac00 \ub2e4\ub974\uac8c \ub2e4\uac00\uc62c \uc218 \uc788\ub2e4. \uae08\uacfc \uc740\uc774 \uba3c \uc2dc\ub300\uc758 \ubb3c\uac74\ucc98\ub7fc \ub290\uaef4\uc9c8 \ub54c \ub2e4\uc2dc \ucc98\uc74c\uc758 \ub18d\ubbfc\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ubb38\uc81c\ub294 \uae08\uc18d\uc758 \uc544\ub984\ub2e4\uc6c0\uc774 \uc544\ub2c8\ub77c \ub0b4\uc77c \uac1a\uc744 \ub3c8\uc774\uc5c8\ub2e4. \ub3c8\uc758 \uc5ed\uc0ac\ub294 \uc81c\ub3c4\uc758 \uc774\ub984\uc744 \ubc30\uc6b0\ub294 \uc77c\uc774\uba74\uc11c, \uac19\uc740 \uaddc\uce59 \uc544\ub798\uc5d0\uc11c \ub2e4\ub978 \uc0b6\uc774 \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc774\ub294\uc9c0 \uc77d\ub294 \uc77c\uc774\uae30\ub3c4 \ud558\ub2e4."}, {"id": "inflation-price-tag-and-purchasing-power", "title": "\ubb3c\uac00 \u2014 \uc9c0\uac11 \uc18d \ub3c8\uc740 \uac19\uc740\ub370 \uc65c \ub35c \uc0b4 \uc218 \uc788\uc744\uae4c", "summary": "\ube75\uac12\uacfc \uac00\uc0c1\uc758 \uc0dd\ud65c\ube44 \uc608\ub85c \ubb3c\uac00 \uc218\uc900\u00b7\uc0c1\uc2b9\ub960\u00b7\uad6c\ub9e4\ub825\uc758 \ucc28\uc774\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "finance", "category_title": "\ub3c8\uacfc \uae08\uc735", "subcategory": "\ub3c8\uacfc \ud654\ud3d0", "categories": ["finance"], "url": "stories/inflation-price-tag-and-purchasing-power/index.html", "image": "../media/inflation-price-tag-and-purchasing-power.png", "alt": "\ub3d9\ub124 \uac00\uac8c\uc5d0\uc11c \ube75\uacfc \uacfc\uc77c\uc774 \ub4e0 \uc7a5\ubc14\uad6c\ub2c8\ub97c \ub193\uace0 \uc9c0\uac11\uc744 \uc0b4\ud53c\ub294 \uc0ac\ub78c\uc758 \uc0bd\ud654.", "text": "\ubb3c\uac00 \u2014 \uc9c0\uac11 \uc18d \ub3c8\uc740 \uac19\uc740\ub370 \uc65c \ub35c \uc0b4 \uc218 \uc788\uc744\uae4c \uac00\uaca9\ud45c \ud55c \uc7a5\uacfc \uc7a5\ubc14\uad6c\ub2c8 \uc804\uccb4\ub97c \ub098\ub204\uc5b4 \ubcf4\uae30 \ube75\uac12\uacfc \uac00\uc0c1\uc758 \uc0dd\ud65c\ube44 \uc608\ub85c \ubb3c\uac00 \uc218\uc900\u00b7\uc0c1\uc2b9\ub960\u00b7\uad6c\ub9e4\ub825\uc758 \ucc28\uc774\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ub3c8\uacfc \ud654\ud3d0 \ub3c8\uacfc \uae08\uc735 \ub3d9\ub124 \uac00\uac8c\uc5d0\uc11c \ub298 \uc0ac\ub358 \ube75\uc744 \uace0\ub978\ub2e4. \ubd09\ud22c\ub294 \ube44\uc2b7\ud55c\ub370 \uacc4\uc0b0\ub300\uc5d0\uc11c \ub0b4\ub294 \ub3c8\uc774 \ub298\uc5c8\ub2e4. \uc608\uc804\uacfc \uac19\uc740 \uc9c0\ud3d0\ub97c \uaebc\ub0c8\uc9c0\ub9cc \uc0b4 \uc218 \uc788\ub294 \uac83\uc774 \uc904\uc5b4\ub4e0 \ub290\ub08c\uc774\ub2e4. \ub3c8\uc5d0 \uc801\ud78c \uc22b\uc790\uc640 \uadf8 \ub3c8\uc73c\ub85c \ud560 \uc218 \uc788\ub294 \uc77c\uc740 \ud56d\uc0c1 \uac19\uc740 \uc18d\ub3c4\ub85c \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294\ub2e4. \ubb3c\uac00\ub294 \ubc14\ub85c \uc774 \uac04\uaca9\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ub2e4\ub9cc \ube75 \ud558\ub098\uc758 \uac00\uaca9 \ubcc0\ud654\uc640 \uacbd\uc81c \uc804\uccb4\uc758 \ubb3c\uac00 \uc0c1\uc2b9\uc740 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc624\ub298\uc758 \uc2e4\uc81c \ud1b5\uacc4\ub97c \uc608\uce21\ud558\uae30\ubcf4\ub2e4 \uc7a5\ubc14\uad6c\ub2c8\ub97c \ud568\uaed8 \ub5a0\uc62c\ub9ac\uba74 \ub274\uc2a4\uc5d0\uc11c \ub4e3\ub294 \ubb3c\uac00\uc640 \uc0dd\ud65c\uc5d0\uc11c \ub290\ub07c\ub294 \ubb3c\uac00\uc758 \uad00\uacc4\uac00 \uc870\uae08 \ubd84\uba85\ud574\uc9c4\ub2e4. \uac00\uc0c1\uc758 \ube75\uac12\uc774 1,000\uc6d0\uc5d0\uc11c 1,100\uc6d0\uc774 \ub418\uc5c8\ub2e4\uba74 \uadf8 \ube75\uc758 \uac00\uaca9\uc740 10% \uc62c\ub790\ub2e4. \uadf8\ub7ec\ub098 \uc774 \uc22b\uc790\ub97c \uadf8\ub300\ub85c \ub098\ub77c \uc804\uccb4\uc758 \ubb3c\uac00 \uc0c1\uc2b9\ub960\uc774\ub77c\uace0 \ubd80\ub97c \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub978 \uc0c1\ud488\uacfc \uc11c\ube44\uc2a4\uc758 \uac00\uaca9\uc740 \ub2e4\ub978 \ubc29\ud5a5\uacfc \uc18d\ub3c4\ub85c \uc6c0\uc9c1\uc600\uc744 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. OpenStax\ub294 \ubb3c\uac00\ub97c \ubcfc \ub54c \ud55c \ud488\ubaa9\ubcf4\ub2e4 \uc5ec\ub7ec \uc0c1\ud488\uacfc \uc11c\ube44\uc2a4\uc758 \ubb36\uc74c\uc744 \uc0b4\ud540\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubb34\uc5c7\uc744 \uc5bc\ub9c8\ub098 \ub2f4\uc744\uc9c0 \uc815\ud55c \uc7a5\ubc14\uad6c\ub2c8\ub97c \ube44\uad50\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc2e4\uc81c \ubb3c\uac00\uc9c0\uc218\uc5d0\ub294 \uc870\uc0ac \ub300\uc0c1\uacfc \uac00\uc911\uce58 \ub4f1 \ub354 \ub9ce\uc740 \uc808\ucc28\uac00 \ub4e4\uc5b4\uac04\ub2e4. \ube75\uac12\uc740 \uccb4\uac10\uc758 \ucd9c\ubc1c\uc810\uc774\uc9c0\ub9cc \uc804\uccb4\ub97c \ub300\uc2e0\ud558\ub294 \uc22b\uc790\ub294 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uc7a5\ubc14\uad6c\ub2c8\ub97c \uc791\ub144\uc5d0 10\ub9cc \uc6d0\uc73c\ub85c \uc0c0\ub294\ub370 \uc62c\ud574\ub294 11\ub9cc \uc6d0\uc774 \ud544\uc694\ud558\ub2e4\uace0 \uac00\uc815\ud558\uc790. \uc9c0\uac11\uc5d0 \uc788\ub294 10\ub9cc \uc6d0\uc740 \uc22b\uc790\uac00 \uc904\uc9c0 \uc54a\uc558\ub2e4. \ud558\uc9c0\ub9cc \uc774\uc804\uacfc \uac19\uc740 \ubb36\uc74c\uc744 \uc0ac\uae30\uc5d0\ub294 \ubd80\uc871\ud574\uc84c\ub2e4. \ud654\ud3d0\uc758 \uad6c\ub9e4\ub825\uc774 \ub2ec\ub77c\uc84c\ub2e4\uace0 \ub9d0\ud560 \uc218 \uc788\ub294 \uc0c1\ud669\uc774\ub2e4. \uc774\uac83\uc740 \ubb3c\uac00\uac00 \uc624\ub974\uba74 \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \ub611\uac19\uc740 \uae08\uc561\uc744 \uc783\ub294\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uac01\uc790 \uac00\uc9c4 \uc790\uc0b0\uacfc \ubd80\ucc44, \uc218\uc785\uc758 \ubcc0\ud654\ub3c4 \uc601\ud5a5\uc744 \uc900\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc6b0\uc120 \uac19\uc740 \uae08\uc561\uc73c\ub85c \uac19\uc740 \ubb36\uc74c\uc744 \uc0b4 \uc218 \uc788\ub294\uc9c0\ub77c\ub294 \uc9c8\ubb38\ub9cc \ubd84\ub9ac\ud574 \ubcf4\uc790. \uc7ac\uc0b0\uc758 \uc22b\uc790\ub97c \ubcf4\ub294 \uc77c\uacfc \uc0dd\ud65c\uc758 \uc120\ud0dd \ubc94\uc704\ub97c \ubcf4\ub294 \uc77c\uc740 \uc11c\ub85c \uc5f0\uacb0\ub418\uba74\uc11c\ub3c4 \ub2e4\ub974\ub2e4. \uc774\ubc88\uc5d0\ub294 \uac19\uc740 \uac00\uc0c1\uc758 \uc0dd\ud65c\ube44 \ubb36\uc74c\uc774 10\ub9cc \uc6d0\uc5d0\uc11c 11\ub9cc \uc6d0\uc73c\ub85c \uc624\ub974\ub294 \ub3d9\uc548, \uadf8\uc5d0 \uc4f8 \uc218 \uc788\ub294 \ub3c8\uc740 10\ub9cc \uc6d0\uc5d0\uc11c 10\ub9cc 5,000\uc6d0\uc73c\ub85c \ub298\uc5c8\ub2e4\uace0 \ud574 \ubcf4\uc790. \ub3c8\uc740 5% \ub298\uc5c8\uc9c0\ub9cc \uc7a5\ubc14\uad6c\ub2c8\uc758 \uac00\uaca9\uc740 10% \uc62c\ub790\ub2e4. \ub298\uc5c8\ub2e4\ub294 \ub9d0\ub9cc\uc73c\ub85c \uc0b4\ub9bc\uc774 \ub354 \ub109\ub109\ud574\uc84c\ub2e4\uace0 \ud560 \uc218\ub294 \uc5c6\ub2e4. \ube44\uc728\uc744 \ube44\uad50\ud558\uba74 \uc0c8 \uc608\uc0b0\uc740 \uc0c8 \uc7a5\ubc14\uad6c\ub2c8 \uac12\uc758 \uc57d 95.5%\ub2e4. \uc774\uc804\ubcf4\ub2e4 \uad6c\ub9e4 \uac00\ub2a5\ud55c \uc591\uc774 \uc57d 4.5% \uc904\uc5b4\ub4e0 \uc148\uc774\ub2e4. \ubaa8\ub4e0 \ubb3c\uac74\uc744 \uac19\uc740 \ube44\uc728\ub85c \uc870\uae08\uc529 \uc0b4 \uc218 \uc788\ub2e4\ub294 \ub2e8\uc21c\ud55c \uacc4\uc0b0\uc774\uba70 \uc2e4\uc81c \uac00\uacc4\uc758 \uc18c\ube44\ub97c \uc7ac\ud604\ud55c \uac12\uc740 \uc544\ub2c8\ub2e4. \uc22b\uc790\uac00 \ub298\uc5b4\ub09c \ubcc0\ud654\uc640 \ubb3c\uac00\ub97c \uac10\uc548\ud55c \ubcc0\ud654\ub97c \ub098\ub204\ub294 \uc608\ub2e4. \uc544\uc774\ub97c \ud0a4\uc6b0\ub294 \uac00\uc815\uacfc \ud63c\uc790 \uc0ac\ub294 \uc0ac\ub78c, \uc758\ub8cc\ube44 \uc9c0\ucd9c\uc774 \ud070 \uc0ac\ub78c\uc758 \uc18c\ube44 \uad6c\uc131\uc740 \ub2e4\ub974\ub2e4. \uac19\uc740 \ubb3c\uac00 \ud1b5\uacc4\ub97c \ubcf4\uba74\uc11c\ub3c4 \uccb4\uac10\uc774 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uad50\uc7ac\ub3c4 \uc5f0\ub839\uacfc \uc9c0\uc5ed, \uc8fc\uac70\uc640 \uc758\ub8cc\ube44\uc758 \ube44\uc911\uc5d0 \ub530\ub77c \uacbd\ud5d8\ud558\ub294 \ubd80\ub2f4\uc774 \ub2ec\ub77c\uc9c4\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uacf5\uc2dd \ud1b5\uacc4\uac00 \ud3c9\uade0\uc801\uc778 \ubcc0\ud654\ub97c \ubcf4\uc5ec \uc900\ub2e4\uace0 \uac1c\uc778\uc758 \uacbd\ud5d8\uc774 \ubaa8\ub450 \uadf8 \uc22b\uc790\uc640 \uac19\uc544\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc18\ub300\ub85c \ub0b4 \uc9c0\ucd9c\uc774 \ud06c\uac8c \ub298\uc5c8\ub2e4\uace0 \ud1b5\uacc4\uac00 \uace7\ubc14\ub85c \ud2c0\ub838\ub2e4\uace0 \ud560 \uc218\ub3c4 \uc5c6\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ubc94\uc704\uc758 \uc9c8\ubb38\uc5d0 \ub2f5\ud558\ub294 \uc790\ub8cc\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \ubb34\uc5c7\uc744 \ub2f4\uc740 \uc7a5\ubc14\uad6c\ub2c8\uc778\uc9c0\ubd80\ud130 \ud655\uc778\ud558\uba74 \ucc28\uc774\ub97c \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \ubb3c\uac00\uac00 10% \uc624\ub974\ub358 \uc0c1\ud669\uc5d0\uc11c \ub2e4\uc74c\uc5d0\ub294 3% \uc624\ub978\ub2e4\uace0 \ud574 \ubcf4\uc790. \uc624\ub974\ub294 \uc18d\ub3c4\ub294 \ub290\ub824\uc84c\uc9c0\ub9cc \uac00\uaca9 \uc218\uc900\uc774 \uc608\uc804\uc73c\ub85c \ub3cc\uc544\uac04 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub354 \ub192\uc544\uc9c4 \uac00\uaca9 \uc704\uc5d0\uc11c \ub2e4\uc2dc \uc62c\ub77c\uac00\ub294 \uacbd\uc6b0\ub2e4. \uc0c1\uc2b9\ub960\uacfc \uac00\uaca9 \uc218\uc900\uc744 \uc11e\uc73c\uba74 \ub274\uc2a4\uac00 \uc0dd\ud65c\uacfc \uc804\ud600 \ub2e4\ub978 \ub9d0\uc744 \ud558\ub294 \uac83\ucc98\ub7fc \ub4e4\ub9b0\ub2e4. \uac00\ub839 \ucc98\uc74c 100\uc774\ub358 \uc7a5\ubc14\uad6c\ub2c8 \uac12\uc740 10% \uc0c1\uc2b9 \ud6c4 110\uc774 \ub418\uace0, \uadf8 \ub4a4 3% \uc0c1\uc2b9\ud558\uba74 113.3\uc774 \ub41c\ub2e4. \ub450 \uae30\uac04\uc758 \uc0c1\uc2b9\ub960\uc744 \ub2e8\uc21c\ud788 \ub354\ud55c 13\uc774 \uc544\ub2c8\ub77c \ubc14\ub010 \uae30\uc900\uc5d0\uc11c \uacc4\uc0b0\ud55c\ub2e4. \uc774 \uc5ed\uc2dc \uac00\uc0c1 \uc608\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uc18d\ub3c4\uc758 \ub454\ud654\uc640 \uac00\uaca9\uc758 \ud558\ub77d\uc744 \uad6c\ubd84\ud558\ub294 \uc77c\uc774\ub2e4. \uac19\uc740 \uae08\uc561\uc744 \ub098\uc911\uc5d0 \ubc1b\uac70\ub098 \uac1a\ub294 \uc57d\uc18d\uc5d0\ub294 \uadf8\ub54c \ub3c8\uc758 \uad6c\ub9e4\ub825\uc774 \uc5b4\ub5a4\uc9c0\uac00 \uc601\ud5a5\uc744 \uc900\ub2e4. \uad50\uc7ac\ub294 \uc608\uc0c1\ud55c \ubb3c\uac00\uc640 \uc2e4\uc81c \ubb3c\uac00\uc758 \ucc28\uc774\uac00 \ube4c\ub824\uc900 \uc0ac\ub78c\uacfc \ube4c\ub9b0 \uc0ac\ub78c\uc5d0\uac8c \ub2e4\ub974\uac8c \uc791\uc6a9\ud560 \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub3c8\uc744 \uac70\ub798\ud55c\ub2e4\ub294 \uac83\uc740 \uc2dc\uac04\uc744 \ud568\uaed8 \uac70\ub798\ud558\ub294 \uc77c\uc774\uae30\ub3c4 \ud558\ub2e4. \ub2e4\ub9cc \uc774 \uc124\uba85\ub9cc\uc73c\ub85c \ubb3c\uac00\uac00 \uc624\ub974\uba74 \ube5a\uc744 \ub0b4\ub294 \ud3b8\uc774 \uc5b8\uc81c\ub098 \uc720\ub9ac\ud558\ub2e4\uace0 \uacb0\ub860 \ub0bc \uc218\ub294 \uc5c6\ub2e4. \uae08\ub9ac\uc758 \ubc29\uc2dd\uacfc \uc18c\ub4dd, \uc0c1\ud658 \uc870\uac74\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc5ec\uae30\uc11c\ub294 \ub204\uad6c\uc5d0\uac8c\ub098 \uac19\uc740 \uc190\uc775\uc774\ub77c\ub294 \ud45c\ud604\uc744 \ud53c\ud558\uace0, \ubbf8\ub798\uc758 \uace0\uc815\ub41c \uae08\uc561\uc774 \ud604\uc7ac\uc640 \uac19\uc740 \uc0dd\ud65c\uc758 \ud798\uc744 \uac16\ub294\uc9c0 \ubb3b\ub294 \uc815\ub3c4\ub85c \uc774\ud574\ud558\uba74 \uc88b\ub2e4. \uc61b\ub0a0\uc758 \ube75\uac12\uc774\ub098 \uc9d1\uac12\uc744 \ubcf4\uba74 \uc9c0\uae08\ubcf4\ub2e4 \uc544\uc8fc \ub0ae\uc544 \ubcf4\uc77c \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \ub2f9\uc2dc\uc758 \uc784\uae08\uacfc \uad6c\ub9e4\ub825, \uc0c1\ud488\uc758 \ud488\uc9c8\uacfc \uad6c\uc131\uc774 \ub2e4\ub974\uba74 \uc22b\uc790\ub9cc\uc73c\ub85c \uc0dd\ud65c\uc774 \ub354 \uc26c\uc6e0\ub2e4\uace0 \ud3c9\uac00\ud558\uae30 \uc5b4\ub835\ub2e4. \ub3c8\uc758 \ub2e8\uc704\uac00 \uac19\uc544\ub3c4 \uadf8 \ub2e8\uc704\uac00 \ub193\uc778 \uc0dd\ud65c \uc870\uac74\uc740 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \ub3d9\ub124 \uac00\uac8c\uc5d0\uc11c \uc7a5\uc744 \ubcf4\ub294 \uc0c1\uc0c1 \uc18d \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c \uc5b4\ub290 \ud574\uc758 \ubb3c\uac00 \uc870\uc0ac\ub098 \ud2b9\uc815 \uac00\uc815\uc758 \uc18c\ube44\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \uc774 \uae00\uc758 \uacc4\uc0b0\ub3c4 \uac00\uc0c1\uc758 \uac12\uc73c\ub85c \uc6d0\ub9ac\ub97c \uc124\uba85\ud588\uc73c\uba70 \ud604\uc7ac\uc758 \ud55c\uad6d \ubb3c\uac00 \uc218\uce58\ub97c \ub300\uc2e0\ud558\uc9c0 \uc54a\ub294\ub2e4. \ubb3c\uac00\ub97c \uc774\ud574\ud558\ub294 \uccab\uac78\uc74c\uc740 \ubcf5\uc7a1\ud55c \uacf5\uc2dd\uc744 \uc678\uc6b0\ub294 \uc77c\uc774 \uc544\ub2c8\ub2e4. \ub3c8\uc758 \uae08\uc561\uacfc \uadf8 \ub3c8\uc73c\ub85c \uc0b4 \uc218 \uc788\ub294 \uac83\uc744 \ud568\uaed8 \ubcf4\ub294 \uc77c\uc774\ub2e4. \ud55c \ud488\ubaa9\uacfc \uc804\uccb4 \ubb36\uc74c, \uac00\uaca9 \uc218\uc900\uacfc \uc0c1\uc2b9 \uc18d\ub3c4\ub97c \ub098\ub204\uba74 \uc775\uc219\ud55c \uacbd\uc81c \ub274\uc2a4\uac00 \uc870\uae08 \ub35c \ub9c9\uc5f0\ud574\uc9c4\ub2e4. \ub2e4\uc74c\uc5d0 \uac00\uaca9\ud45c\ub97c \ubcf4\uace0 \ube44\uc2f8\uc84c\ub2e4\uace0 \ub290\ub080\ub2e4\uba74 \ubb34\uc5c7\uc774 \uc5bc\ub9c8\ub098 \ub2ec\ub77c\uc84c\ub294\uc9c0 \ud55c \ubc88 \ub354 \uc0b4\ud3b4\ubcf4\uc790. \uc790\uc8fc \uc0ac\ub294 \ubb3c\uac74\uacfc \ub2e4\ub978 \uc9c0\ucd9c\uc774 \uac19\uc740 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc600\ub294\uc9c0\ub3c4 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc9c0\uac11 \uc18d \uc9c0\ud3d0\ub294 \uadf8\ub300\ub85c\uc5ec\ub3c4 \uc7a5\ubc14\uad6c\ub2c8\uac00 \ub2ec\ub77c\uc9c0\ub294 \uc774\uc720\uc5d0\ub294 \uc0dd\ud65c\uacfc \ud1b5\uacc4\uac00 \ub9cc\ub098\ub294 \uc5ec\ub7ec \uae30\uc900\uc774 \ub4e4\uc5b4 \uc788\ub2e4."}, {"id": "insurance-pool-uncertain-loss", "title": "\ubcf4\ud5d8 \u2014 \uc0ac\uace0\uac00 \uc5c6\uc73c\uba74 \ub0b8 \ub3c8\uc774 \uc544\uae4c\uc6b4 \uac78\uae4c", "summary": "\uac00\uc0c1\uc758 \ud654\uc7ac \ube44\uc6a9\uc744 \ud1b5\ud574 \ubcf4\ud5d8\uc758 \uacf5\ub3d9 \ubd80\ub2f4\uacfc \ubcf4\ud5d8\ub8cc\u00b7\uc790\uae30\ubd80\ub2f4\uae08\uc758 \uc5ed\ud560\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "finance", "category_title": "\ub3c8\uacfc \uae08\uc735", "subcategory": "\ubcf4\ud5d8\uacfc \uc704\ud5d8", "categories": ["finance"], "url": "stories/insurance-pool-uncertain-loss/index.html", "image": "../media/insurance-pool-uncertain-loss.png", "alt": "\uc774\uc6c3\ub4e4\uc774 \uc9d1 \ubaa8\ud615\uc774 \ub193\uc778 \ud0c1\uc790\uc5d0\uc11c \ubd09\ud22c\ub97c \uacf5\ub3d9 \uc0c1\uc790\uc5d0 \ubaa8\uc73c\ub294 \uac1c\ub150 \uc0bd\ud654.", "text": "\ubcf4\ud5d8 \u2014 \uc0ac\uace0\uac00 \uc5c6\uc73c\uba74 \ub0b8 \ub3c8\uc774 \uc544\uae4c\uc6b4 \uac78\uae4c \ud070 \uc190\uc2e4\uc758 \ubd88\ud655\uc2e4\uc131\uc744 \uc5ec\ub7ec \uc0ac\ub78c\uc774 \ub098\ub204\ub294 \ubc29\ubc95 \uac00\uc0c1\uc758 \ud654\uc7ac \ube44\uc6a9\uc744 \ud1b5\ud574 \ubcf4\ud5d8\uc758 \uacf5\ub3d9 \ubd80\ub2f4\uacfc \ubcf4\ud5d8\ub8cc\u00b7\uc790\uae30\ubd80\ub2f4\uae08\uc758 \uc5ed\ud560\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ubcf4\ud5d8\uacfc \uc704\ud5d8 \ub3c8\uacfc \uae08\uc735 \ud55c \ud574 \ub3d9\uc548 \uc0ac\uace0\uac00 \uc5c6\uc5c8\ub2e4. \ub2e4\ud589\ud55c \uc77c\uc778\ub370 \ubcf4\ud5d8\ub8cc\ub97c \ub5a0\uc62c\ub9ac\uba74 \uc870\uae08 \ub2e4\ub978 \uc0dd\uac01\ub3c4 \ub4e0\ub2e4. \uc544\ubb34\uac83\ub3c4 \ub3cc\ub824\ubc1b\uc9c0 \ubabb\ud588\uc73c\ub2c8 \uc190\ud574\uc600\uc744\uae4c. \ubb3c\uac74\uc744 \uc0ac\uba74 \uc190\uc5d0 \ub0a8\ub294 \uac83\uc774 \uc788\ub294\ub370 \ubcf4\ud5d8\uc740 \ub208\uc5d0 \ubcf4\uc774\ub294 \uacb0\uacfc\uac00 \uc5c6\uc744 \ub54c\uac00 \ub9ce\ub2e4. \uc774 \uc9c8\ubb38\uc744 \ud480\ub824\uba74 \ubcf4\ud5d8\uc774 \ubb34\uc5c7\uc744 \ubc14\uafb8\ub294\uc9c0\ubd80\ud130 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc0ac\uace0 \uc790\uccb4\ub97c \uc5c6\uc560 \uc8fc\ub294 \uac83\uacfc \uc0ac\uace0 \ub4a4\uc758 \ud070 \uae08\uc804 \ubd80\ub2f4\uc744 \ub098\ub204\ub294 \uac83\uc740 \ub2e4\ub978 \uc77c\uc774\ub2e4. \ubcf4\ud5d8\uc758 \uae30\ubcf8 \uad6c\uc0c1\uc740 \ubd88\ud655\uc2e4\ud55c \ud070 \uc190\uc2e4\uc744 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \ube44\uad50\uc801 \uc791\uc740 \ubd80\ub2f4\uc73c\ub85c \ub2e4\ub8e8\ub294 \ub370 \uc788\ub2e4. \uac00\uc0c1\uc758 \ub9c8\uc744\uc5d0 100\uac00\uad6c\uac00 \uc788\uace0, \ud55c \ud574\uc5d0 \ud55c \uc9d1\uc5d0\uc11c 1,000\ub9cc \uc6d0\uc758 \ud53c\ud574\uac00 \uc0dd\uae34\ub2e4\uace0 \ub2e8\uc21c\ud558\uac8c \uac00\uc815\ud558\uc790. \uc5b4\ub290 \uc9d1\uc77c\uc9c0\ub294 \ubbf8\ub9ac \ubaa8\ub978\ub2e4. \uac01 \uac00\uad6c\uac00 10\ub9cc \uc6d0\uc529 \ubaa8\uc73c\uba74 \ud569\uacc4\ub294 1,000\ub9cc \uc6d0\uc774 \ub41c\ub2e4. \ud53c\ud574\uac00 \ub09c \uc9d1\uc758 \ud070 \ubd80\ub2f4\uc744 \ud568\uaed8 \ub9c8\ub828\ud55c \ub3c8\uc73c\ub85c \uac10\ub2f9\ud558\ub294 \ubaa8\ud615\uc774\ub2e4. \uc2e4\uc81c\ub85c \ud654\uc7ac\uac00 \ubc18\ub4dc\uc2dc \ud55c \uac74\ub9cc \ubc1c\uc0dd\ud55c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc6b4\uc601\ube44\uc640 \uc774\uc775, \uc7ac\ub09c\uc758 \ub3d9\uc2dc \ubc1c\uc0dd\ub3c4 \uc0dd\ub7b5\ud55c \uacc4\uc0b0\uc774\ub2e4. \uc774 \uc608\uc758 \ubaa9\uc801\uc740 \uc0ac\uace0\ub97c \ub2f9\ud558\uc9c0 \uc54a\uc740 \uc0ac\ub78c\uc774 \ub3cc\ub824\ubc1b\ub294 \ub3c8\ub9cc\uc73c\ub85c \ucc38\uc5ec\uc758 \uac00\uce58\ub97c \ud310\ub2e8\ud558\uae30 \uc5b4\ub835\ub2e4\ub294 \uc810\uc744 \ubcf4\uc774\ub294 \ub370 \uc788\ub2e4. \uc2dc\uc791\ud560 \ub54c\ub294 \ub204\uad6c\ub3c4 \ud53c\ud574 \uac00\uad6c\ub97c \ud655\uc2e4\ud788 \uc54c\uc9c0 \ubabb\ud588\ub2e4. OpenStax\ub294 \ubcf4\ud5d8 \uac00\uc785\uc790\uac00 \ubcf4\ud5d8\ub8cc\ub97c \ub0b4\uace0, \uc815\ud574\uc9c4 \uc190\uc2e4\uc744 \uacaa\uc740 \uc0ac\ub78c\uc774 \uacf5\ub3d9\uc758 \uc790\uae08\uc5d0\uc11c \uc9c0\uae09\ubc1b\ub294 \uad6c\uc870\ub97c \uc124\uba85\ud55c\ub2e4. \ubcf4\ud5d8\ud68c\uc0ac\ub294 \uc9d1\ub2e8\uc5d0\uc11c \uc0ac\uac74\uc774 \uc77c\uc5b4\ub0a0 \uac00\ub2a5\uc131\uacfc \ube44\uc6a9\uc744 \ucd94\uc815\ud55c\ub2e4. \ud55c \uac1c\uc778\uc758 \ubbf8\ub798\ub97c \ub9de\ud788\ub294 \uc77c\uacfc \uc9d1\ub2e8\uc758 \uc704\ud5d8\uc744 \uacc4\uc0b0\ud558\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uadf8\ub798\uc11c \ubcf4\ud5d8\uc744 \ub0b4\uac00 \ub0b8 \ub3c8\uc744 \ubaa8\ub450 \ub3cc\ub824\ubc1b\ub294 \uc800\ucd95\uacfc \ub611\uac19\uc774 \ubcfc \uc218\ub294 \uc5c6\ub2e4. \ubb3c\ub860 \uc2e4\uc81c \uc0c1\ud488\uc5d0\ub294 \uc5ec\ub7ec \uae30\ub2a5\uc774 \uacb0\ud569\ub420 \uc218 \uc788\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc704\ud5d8\uc744 \ub098\ub204\ub294 \uae30\ubcf8 \uae30\ub2a5\uc744 \uc0b4\ud3b4\ubcf4\ub294 \uac83\uc774\ub2e4. \uc0ac\uace0\uac00 \uc5c6\ub294 \ub3d9\uc548\uc5d0\ub3c4 \ud070 \uc190\uc2e4\uc5d0 \ub300\ube44\ud558\ub294 \uc57d\uc18d\uc740 \uc77c\uc815\ud55c \uae30\uac04 \uc720\uc9c0\ub418\uc5c8\ub2e4. \uc9d1\uc758 \uc704\uce58\uc640 \uad6c\uc870, \ucc28\ub7c9\uc758 \uc0ac\uc6a9 \uc870\uac74\ucc98\ub7fc \uc704\ud5d8\uc5d0 \uc601\ud5a5\uc744 \uc8fc\ub294 \uc694\uc18c\ub294 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 \ubcf4\ud5d8\ud68c\uc0ac\uac00 \ube44\uc2b7\ud55c \uc704\ud5d8\uc758 \uc9d1\ub2e8\uc744 \uad6c\ubd84\ud558\ub824 \ud55c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uac19\uc740 \uae08\uc561\uc744 \ubcf4\uc7a5\ud55c\ub2e4\uace0 \ubaa8\ub450\uc5d0\uac8c \uac19\uc740 \ubcf4\ud5d8\ub8cc\uac00 \uc801\uc6a9\ub418\ub294 \uac83\uc740 \uc544\ub2cc \uc774\uc720\ub2e4. \ud558\uc9c0\ub9cc \uc9d1\ub2e8\uc744 \uad6c\ubd84\ud558\ub294 \uae30\uc900\uc740 \uc815\ud655\uc131\uacfc \uacf5\uc815\uc131\uc758 \uc9c8\ubb38\uc744 \ud568\uaed8 \ub9cc\ub4e0\ub2e4. \uad00\ucc30\ud55c \ud2b9\uc9d5\uc774 \uc2e4\uc81c \uc704\ud5d8\uc744 \uc5bc\ub9c8\ub098 \uc798 \uc124\uba85\ud558\ub294\uc9c0, \uc5b4\ub5a4 \uad6c\ubd84\uc744 \ud5c8\uc6a9\ud560\uc9c0 \ub530\uc838\uc57c \ud55c\ub2e4. \uac04\ub2e8\ud55c \ud655\ub960\ud45c\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc81c\ub3c4\uc758 \uc120\ud0dd\uc774 \uc790\ub3d9\uc73c\ub85c \uc815\ud574\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uacc4\uc0b0\uacfc \uaddc\uce59\uc774 \ud568\uaed8 \uc791\uc6a9\ud558\ub294 \uc601\uc5ed\uc774\ub2e4. \ubcf4\ud5d8\uc774 \uc788\uc5b4\ub3c4 \uc190\uc2e4\uc758 \uc77c\ubd80\ub97c \uac00\uc785\uc790\uac00 \ubd80\ub2f4\ud558\ub294 \uacc4\uc57d\uc774 \uc788\ub2e4. \uc790\uae30\ubd80\ub2f4\uae08\uc774\ub098 \uc77c\uc815 \ube44\uc728\uc758 \ubd84\ub2f4 \uac19\uc740 \ubc29\uc2dd\uc774\ub2e4. \uad50\uc7ac\ub294 \uc774\ub7f0 \uc870\uac74\uc774 \uc704\ud5d8\uc744 \uc904\uc774\ub824\ub294 \uc720\uc778\uc744 \uc720\uc9c0\ud558\ub294 \ud55c \ubc29\ubc95\uc774\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \ubcf4\ud5d8\uc774 \uc788\ub2e4\uace0 \ubaa8\ub4e0 \ube44\uc6a9\uc774 \ubb34\uc870\uac74 \uc804\uc561 \uc9c0\uae09\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac00\ub839 \ubcf4\uc7a5 \ub300\uc0c1 \uc190\uc2e4 200\ub9cc \uc6d0 \uac00\uc6b4\ub370 \uccab 20\ub9cc \uc6d0\uc744 \ubcf8\uc778\uc774 \ub0b4\ub294 \ub2e8\uc21c\ud55c \uac00\uc0c1 \uc870\uac74\uc774\ub77c\uba74 \ub098\uba38\uc9c0\ub294 180\ub9cc \uc6d0\uc774\ub2e4. \uc2e4\uc81c \uc0c1\ud488\uc5d0\uc11c\ub294 \ud55c\ub3c4\uc640 \uc81c\uc678 \uc0ac\ud56d \ub4f1 \ub2e4\ub978 \uc870\uac74\ub3c4 \uc801\uc6a9\ub420 \uc218 \uc788\ub2e4. \uc9c0\uae09\uc561\uc744 \uc54c\ub824\uba74 \ubcf4\ud5d8\ub8cc\uc758 \uc561\uc218\ubfd0 \uc544\ub2c8\ub77c \uc5b4\ub5a4 \uc57d\uc18d\uc5d0 \uac00\uc785\ud588\ub294\uc9c0 \uc77d\uc5b4\uc57c \ud55c\ub2e4. \uc704\ud5d8\uc758 \uacb0\uacfc\ub97c \ub204\uad70\uac00 \ub098\ub204\uc5b4 \uc900\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc0ac\ub78c\uc758 \ud589\ub3d9\uc5d0 \uc601\ud5a5\uc744 \uc904 \uc218\ub3c4 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc774\ub97c \ub3c4\ub355\uc801 \ud574\uc774\ub77c\ub294 \uac1c\ub150\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ubaa8\ub4e0 \uac00\uc785\uc790\uac00 \ub098\uc058\uac8c \ud589\ub3d9\ud55c\ub2e4\uace0 \ub099\uc778\ucc0d\ub294 \uc77c\uc774 \uc544\ub2c8\ub77c \ube44\uc6a9\uc744 \ubd80\ub2f4\ud558\ub294 \ubc29\uc2dd\uc774 \uc120\ud0dd\uc744 \ubc14\uafc0 \uc218 \uc788\ub2e4\ub294 \uc810\uc774\ub2e4. \uc548\uc804 \uc2dc\uc124\uc744 \uac16\ucd94\uba74 \uc870\uac74\uc744 \ub2ec\ub9ac\ud558\uac70\ub098 \uc77c\ubd80 \ube44\uc6a9\uc744 \ub0a8\uae30\ub294 \uc124\uacc4\ub294 \uc774\ub7f0 \ubb38\uc81c\uc640 \uc5f0\uacb0\ub41c\ub2e4. \ub2e4\ub9cc \ube44\uc6a9 \ubd84\ub2f4\uc744 \ub192\uc774\uba74 \ud544\uc694\ud55c \uc774\uc6a9\uae4c\uc9c0 \uc904\uc5b4\ub4e4 \uc218 \uc788\ub2e4\ub294 \uc9c8\ubb38\ub3c4 \uc0dd\uae34\ub2e4. \uc81c\ub3c4\ub294 \ud55c \uac00\uc9c0 \ubaa9\ud45c\ub9cc \ud06c\uac8c \ud558\uba74 \ub05d\ub098\ub294 \ubb38\uc81c\uac00 \uc544\ub2c8\ub2e4. \ubcf4\ud638\uc640 \ubd80\ub2f4, \uc608\ubc29 \uc0ac\uc774\uc758 \uade0\ud615\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uac00\uc0c1\uc758 \ub9c8\uc744 \uacc4\uc0b0\uc5d0\uc11c \uc5b4\ub824\uc6b4 \uacbd\uc6b0\ub294 \uc5ec\ub7ec \uc9d1\uc774 \ub3d9\uc2dc\uc5d0 \ud53c\ud574\ub97c \uc785\ub294 \uc0c1\ud669\uc774\ub2e4. \ud070 \uc7ac\ub09c\uc740 \uc704\ud5d8\ub4e4\uc774 \uc11c\ub85c \ubb34\uad00\ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc0ac\ub78c\uc774 \ub9ce\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc5b4\ub5a4 \uc190\uc2e4\ub3c4 \uac10\ub2f9\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc190\uc2e4\uc758 \uaddc\ubaa8\uc640 \uc11c\ub85c \uc5f0\uacb0\ub418\ub294 \ubc29\uc2dd\uc774 \uc911\uc694\ud558\ub2e4. \ubcf4\ud5d8\ud68c\uc0ac\ub294 \uc9c0\uae09\uc744 \uc704\ud55c \uc900\ube44\uc640 \uc6b4\uc601 \ube44\uc6a9\ub3c4 \ub9c8\ub828\ud574\uc57c \ud55c\ub2e4. \uad50\uc7ac\ub294 \ubcf4\ud5d8\ub8cc\uc640 \uc6b4\uc6a9 \uc218\uc785, \ubcf4\ud5d8\uae08\uacfc \ube44\uc6a9\uc774 \ud568\uaed8 \uc791\uc6a9\ud55c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubcf4\ud5d8\uc758 \uc790\uae08\uc744 \ub2e8\uc9c0 \uc7a0\uc2dc \ubaa8\uc544 \ub450\uc5c8\ub2e4\uac00 \uadf8\ub300\ub85c \ub098\ub204\ub294 \uc0c1\uc790\ub85c\ub9cc \uc0dd\uac01\ud558\uba74 \uc2e4\uc81c \uc6b4\uc601\uc758 \uc870\uac74\uc740 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ubcf4\ud5d8\uc774\ub77c\ub294 \uc774\ub984\ub9cc\uc73c\ub85c \ubcf4\uc7a5 \ub0b4\uc6a9\uc744 \ub2e4 \uc54c \uc218\ub294 \uc5c6\ub2e4. \uc5b4\ub5a4 \uc0ac\uac74\uc774 \ub300\uc0c1\uc774\uace0 \ubb34\uc5c7\uc774 \uc81c\uc678\ub418\uba70 \uc5b4\ub290 \ubc94\uc704\uae4c\uc9c0 \uc9c0\uae09\ub418\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uac19\uc740 \uc774\ub984\uc758 \uc0c1\ud488\uc774\ub77c\ub3c4 \uc57d\uc18d\uc758 \ub0b4\uc6a9\uc774 \ub2e4\ub97c \uc218 \uc788\ub2e4. \ub0b8 \uae08\uc561\uc774 \uc801\ub2f9\ud55c\uc9c0 \ubb3b\ub294 \uc77c\ubcf4\ub2e4 \uba3c\uc800 \uacc4\uc57d\uc774 \ub2e4\ub8e8\ub294 \uc704\ud5d8\uc744 \uc54c\uc544\uc57c \ud55c\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc774\uc6c3\ub4e4\uc774 \uacf5\ub3d9\uc758 \ub300\ube44\ub97c \uc0dd\uac01\ud558\ub294 \uc0c1\uc0c1 \uc18d \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c \ubcf4\ud5d8\ud68c\uc0ac\uc758 \uc6b4\uc601\uc774\ub098 \ubcf4\ud5d8\uae08 \uc9c0\uae09 \uacfc\uc815\uc744 \uc7ac\ud604\ud55c \ub3c4\ud45c\ub294 \uc544\ub2c8\ub2e4. \uc774 \uae00\uc758 \ub450 \uacc4\uc0b0\ub3c4 \uac00\uc0c1 \ubaa8\ud615\uc774\uba70 \ud2b9\uc815 \uacc4\uc57d\uc758 \uc9c0\uae09\uc561\uc744 \uc548\ub0b4\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc0ac\uace0\uac00 \uc5c6\uc5c8\ub2e4\uba74 \ud070 \uc190\uc2e4\uc774 \uc0dd\uae30\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc810\uc5d0\uc11c \uba3c\uc800 \ub2e4\ud589\ud55c \uc77c\uc774\ub2e4. \uadf8\ub3d9\uc548 \ubcf4\ud5d8\uc774 \uc81c\uacf5\ud55c \uac00\uce58\ub294 \ub098\uc911\uc5d0 \ubc1b\uc740 \uae08\uc561\uacfc \uc815\ud655\ud788 \uac19\uc740 \ud56d\ubaa9\uc740 \uc544\ub2c8\ub2e4. \ubd88\ud655\uc2e4\ud55c \ube44\uc6a9\uc758 \uc77c\ubd80\ub97c \ubbf8\ub9ac \uc815\ud55c \ubd80\ub2f4\uc73c\ub85c \ubc14\uafb8\ub294 \uc57d\uc18d\uc774 \uc788\uc5c8\ub2e4. \ubcf4\ud5d8\uc744 \uc774\ud574\ud558\uba74 \ubb34\uc870\uac74 \ub9ce\uc774 \uac00\uc785\ud558\uac70\ub098 \ubaa8\ub450 \uc5c6\uc560\uc790\ub294 \ub2f5\ubcf4\ub2e4 \uad6c\uccb4\uc801\uc778 \uc9c8\ubb38\uc774 \uc0dd\uae34\ub2e4. \ub0b4\uac00 \uac10\ub2f9\ud558\uae30 \uc5b4\ub824\uc6b4 \uc704\ud5d8\uc740 \ubb34\uc5c7\uc774\uba70 \uacc4\uc57d\uc740 \uadf8 \ubd80\ubd84\uc744 \uc5b4\ub5bb\uac8c \ub098\ub204\ub294\uac00. \uc544\ubb34 \uc77c\ub3c4 \uc5c6\ub358 \ud574\ub97c \ub3cc\uc544\ubcf4\ub294 \uc9c8\ubb38\uc740 \uacb0\uad6d \ud070\uc77c\uc774 \uc0dd\uacbc\uc744 \ub54c \ub204\uac00 \uc5b4\ub5a4 \uc870\uac74\uc73c\ub85c \ubd80\ub2f4\ud560\uc9c0\ub97c \uc0dd\uac01\ud558\ub294 \uc9c8\ubb38\uacfc \uc774\uc5b4\uc9c4\ub2e4."}, {"id": "john-law-paper-money-and-mississippi", "title": "\uc874 \ub85c \u2014 \uc885\uc774\ub3c8\uacfc \ubbf8\uc2dc\uc2dc\ud53c\uc758 \uafc8\uc740 \uc5b4\ub5bb\uac8c \uc5ee\uc600\uc744\uae4c", "summary": "1716\ub144 \uc740\ud589\uacfc 1717\ub144 \ubb34\uc5ed\ud68c\uc0ac, \uad6d\uac00 \ubd80\ucc44\uc640 \uc8fc\uc2dd \uc5f4\ud48d\uc774 \uacb0\ud569\ud55c \uacfc\uc815\uacfc 1720\ub144\uc758 \uc704\uae30\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "finance", "category_title": "\ub3c8\uacfc \uae08\uc735", "subcategory": "\ub3c8\uacfc \ud654\ud3d0", "categories": ["finance"], "url": "stories/john-law-paper-money-and-mississippi/index.html", "image": "../media/john-law-paper-money-and-mississippi.png", "alt": "1720\ub144 \ub808\uc628 \uc185\ud06c \uc791\ud488\uc73c\ub85c \uc18c\uac1c\ub418\ub294 \uc874 \ub85c\uc758 \uc804\uc2e0 \ud310\ud654", "text": "\uc874 \ub85c \u2014 \uc885\uc774\ub3c8\uacfc \ubbf8\uc2dc\uc2dc\ud53c\uc758 \uafc8\uc740 \uc5b4\ub5bb\uac8c \uc5ee\uc600\uc744\uae4c 18\uc138\uae30 \ud504\ub791\uc2a4\uc5d0\uc11c \uc740\ud589, \uad6d\ucc44, \ud68c\uc0ac \uc8fc\uc2dd\uc774 \ub9cc\ub09c \uc774\uc57c\uae30 1716\ub144 \uc740\ud589\uacfc 1717\ub144 \ubb34\uc5ed\ud68c\uc0ac, \uad6d\uac00 \ubd80\ucc44\uc640 \uc8fc\uc2dd \uc5f4\ud48d\uc774 \uacb0\ud569\ud55c \uacfc\uc815\uacfc 1720\ub144\uc758 \uc704\uae30\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ub3c8\uacfc \ud654\ud3d0 \ub3c8\uacfc \uae08\uc735 \uc740\ud589\uc774 \ubc1c\ud589\ud55c \uc9c0\ud3d0, \ub098\ub77c\uac00 \uac1a\uc544\uc57c \ud560 \ube5a, \ubc14\ub2e4 \uac74\ub108 \ubb34\uc5ed\ud68c\uc0ac\uc758 \uc8fc\uc2dd. \uc11c\ub85c \ub2e4\ub978 \uc57d\uc18d\ub4e4\uc774 \ud558\ub098\uc758 \ud070 \uacc4\ud68d \uc548\uc5d0 \ubb36\uc778 \uc801\uc774 \uc788\ub2e4. 18\uc138\uae30 \ucd08 \ud504\ub791\uc2a4\uc5d0\uc11c \uc874 \ub85c\uac00 \ucd94\uc9c4\ud55c \uc81c\ub3c4\uac00 \uadf8 \uc0ac\ub840\ub2e4. \ubbf8\uc2dc\uc2dc\ud53c\uc758 \ubd80\ub97c \uae30\ub300\ud55c \uc5f4\ud48d\uacfc \ub4a4\uc774\uc740 \ubd95\uad34 \ub54c\ubb38\uc5d0 \ud754\ud788 \ud5c8\ud669\ub41c \uafc8\uc758 \uc774\uc57c\uae30\ub85c \uae30\uc5b5\ub41c\ub2e4. \uadf8\ub7ec\ub098 \ucc98\uc74c\ubd80\ud130 \ubaa8\ub4e0 \uac83\uc774 \ub2e8\uc21c\ud55c \uc0ac\uae30\ub294 \uc544\ub2c8\uc5c8\ub2e4. \ub3c8\uc774 \uc798 \ub3cc\uc9c0 \uc54a\uace0 \uad6d\uac00 \uc7ac\uc815\uc774 \uc5b4\ub824\uc6b4 \uc0c1\ud669\uc5d0\uc11c \uc0c8\ub85c\uc6b4 \ubc29\ubc95\uc774 \ub9e4\ub825\uc801\uc73c\ub85c \ubcf4\uc778 \uc774\uc720\ubd80\ud130 \uc0b4\ud3b4\ubcf4\uc790. \uc2a4\ucf54\ud2c0\ub79c\ub4dc \ucd9c\uc2e0\uc758 \ub85c\ub294 \ub3c8\uc758 \uc720\ud1b5\uc744 \ub298\ub9ac\uba74 \uc0c1\uc5c5\uacfc \uc0dd\uc0b0\uc5d0 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\ub2e4\uace0 \uc0dd\uac01\ud588\ub2e4. \uc190\uc5d0 \uc954 \ub3d9\uc804\ub9cc\uc73c\ub85c \uac70\ub798\ud574\uc57c \ud55c\ub2e4\uba74 \ud544\uc694\ud55c \ud65c\ub3d9\uc774 \ub9c9\ud790 \uc218 \uc788\ub2e4\ub294 \ubb38\uc81c\uc758\uc2dd\uc774\uc5c8\ub2e4. \uc740\ud589\uacfc \uc885\uc774\ub3c8\uc744 \uadf8 \ud574\ubc95\uc73c\ub85c \ubcf4\uc558\ub2e4. \uc885\uc774\uc5d0 \uc801\ud78c \uc57d\uc18d\uc744 \uc0ac\ub78c\ub4e4\uc774 \ubc1b\uc544 \uc8fc\uba74 \ubb34\uac70\uc6b4 \uae08\uc18d\uc744 \ub9e4\ubc88 \uc62e\uae30\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4. \ub2e4\ub9cc \ud3b8\ub9ac\ud568\uc774 \uc720\uc9c0\ub418\ub824\uba74 \uc57d\uc18d\uc758 \ub0b4\uc6a9\uacfc \ubc1c\ud589 \uae30\uad00\uc744 \ubbff\uc744 \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4. \ub3c8\uc744 \ub298\ub9ac\ub294 \uae30\uc220\uacfc \uc2e0\ub8b0\ub97c \uc9c0\ud0a4\ub294 \uc77c\uc740 \ud568\uaed8 \ud544\uc694\ud588\ub2e4. \ub85c\ub294 \ud504\ub791\uc2a4\uc5d0\uc11c \uc740\ud589\uc744 \uc138\uc6b8 \ud5c8\uac00\ub97c \uc5bb\uc5c8\ub2e4. \uc740\ud589\uad8c\uc744 \uc138\uae08 \ub0a9\ubd80\uc5d0 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4\ub294 \uc870\uac74\uc740 \uc0ac\ub78c\ub4e4\uc774 \uadf8\uac83\uc744 \ubc1b\uc544\ub4e4\uc774\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub418\uc5c8\ub2e4. \uad6d\uac00\uac00 \uc694\uad6c\ud558\ub294 \ub0a9\ubd80\uc5d0 \uc4f8 \uc218 \uc788\ub294 \uc885\uc774\ub294 \uac70\ub798\uc5d0\uc11c\ub3c4 \uc4f0\uc77c \uc774\uc720\uac00 \uc0dd\uae34\ub2e4. \ucd08\uae30\uc758 \uc740\ud589\uc744 \ub098\uc911\uc758 \ubd95\uad34\ub97c \uc774\ubbf8 \ud488\uc740 \uc2e4\ud328\uc791\uc73c\ub85c\ub9cc \ubcfc \ud544\uc694\ub294 \uc5c6\ub2e4. \uc2e0\uc6a9\uacfc \uc720\ud1b5\uc744 \uac1c\uc120\ud558\ub824\ub294 \uc2dc\ub3c4\uc600\uace0 \uc2e4\uc81c\ub85c \uad00\uc2ec\uacfc \uc2e0\ub8b0\ub97c \uc5bb\uc5c8\ub2e4. \ubb38\uc81c\ub294 \uadf8 \uc2e0\ub8b0\ub97c \ubc14\ud0d5\uc73c\ub85c \uc5bc\ub9c8\ub098 \ub9ce\uc740 \ub2e4\ub978 \uc57d\uc18d\uc744 \ub354 \uc5b9\uc5c8\ub290\ub0d0\uc5d0 \uc788\uc5c8\ub2e4. 1717\ub144\uc5d0\ub294 \ubbf8\uc2dc\uc2dc\ud53c\uc640 \ub8e8\uc774\uc9c0\uc560\ub098 \uc9c0\uc5ed\uc758 \ubb34\uc5ed \uad8c\ub9ac\ub97c \ub0b4\uc138\uc6b4 \ud68c\uc0ac\uac00 \ub4f1\uc7a5\ud588\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \uba40\ub9ac \uc788\ub294 \ub545\uc5d0\uc11c \ud070 \uc774\uc775\uc774 \ub098\ub9ac\ub77c\uace0 \uae30\ub300\ud588\ub2e4. \uadf8\uacf3\uc758 \uc2e4\uc81c \uc0dd\uc0b0\uacfc \ube44\uc6a9\uc744 \ub208\uc55e\uc5d0\uc11c \ud655\uc778\ud558\uae30\ub294 \uc5b4\ub824\uc6e0\ub2e4. \ubbf8\ub798\uc758 \uc218\uc775\uc740 \uc544\uc9c1 \ubc8c\uc5b4\ub4e4\uc778 \ud604\uae08\uc774 \uc544\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uae30\ub300\uac00 \uc8fc\uc2dd \uac00\uaca9\uc5d0 \ubc18\uc601\ub418\uba74 \uc9c0\uae08\uc758 \uc7ac\uc0b0\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\ub2e4. \uc18c\uc2dd\uc744 \uc804\ud558\ub294 \uc0ac\ub78c\uacfc \uadf8\uac83\uc744 \ubbff\ub294 \uc0ac\ub78c \uc0ac\uc774\uc758 \uac70\ub9ac\uac00 \ud074\uc218\ub85d \uc774\uc57c\uae30\uc758 \ud798\ub3c4 \ucee4\uc9c0\uae30 \uc26c\uc6e0\ub2e4. \ud68c\uc0ac\uc758 \uc790\ubcf8\uc744 \ub9c8\ub828\ud558\ub294 \uacfc\uc815\uc5d0\uc11c \uc815\ubd80\uac00 \uc9c4 \ube5a\uc758 \uc99d\uc11c\ub3c4 \uc0ac\uc6a9\ub418\uc5c8\ub2e4. \uad6d\uac00\uc5d0 \ubc1b\uc744 \ub3c8\uc744 \ud68c\uc0ac\uc758 \uc8fc\uc2dd\uc73c\ub85c \ubc14\uafb8\ub294 \uae38\uc774 \uc0dd\uacbc\ub2e4. \uad6d\uac00\uc758 \uc7ac\uc815 \ubb38\uc81c\uc640 \ud68c\uc0ac\uc758 \uc131\uacf5 \uac00\ub2a5\uc131\uc774 \uc11c\ub85c \uc5bd\ud788\uae30 \uc2dc\uc791\ud55c \uac83\uc774\ub2e4. \uc740\ud589\ub3c4 \uc655\ub9bd\uc740\ud589\uc73c\ub85c \ubc14\ub00c\uace0 \ud68c\uc0ac\uc758 \ud2b9\uad8c\uc740 \ud655\ub300\ub418\uc5c8\ub2e4. \uc774\ub97c \uc11c\ub85c \ub3c5\ub9bd\ub41c \uc791\uc740 \uc0ac\uc5c5 \uba87 \uac1c\ub85c \ubcf4\uba74 \uc804\uccb4\uc758 \uc704\ud5d8\uc744 \ub193\uce5c\ub2e4. \uc740\ud589\uad8c\uacfc \uc8fc\uc2dd, \uc138\uc785\uacfc \uacf5\uacf5 \ubd80\ucc44\uc5d0 \ub300\ud55c \uae30\ub300\uac00 \uac19\uc740 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc774\ub294 \uccb4\uacc4\uac00 \ub418\uc5b4 \uac14\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \uc8fc\uc2dd\uc744 \uc6d0\ud558\uba74 \uac00\uaca9\uc774 \uc624\ub974\uace0 \uc624\ub978 \uac00\uaca9\uc740 \ub354 \ub9ce\uc740 \uad00\uc2ec\uc744 \ubd80\ub978\ub2e4. \ubb34\uc5ed\uc774 \uc2e4\uc81c\ub85c \uc5bc\ub9c8\ub098 \uc774\uc775\uc744 \ub0c8\ub294\uc9c0\uc640 \ubcc4\uac1c\ub85c \uc8fc\uc2dd\uc744 \ubcf4\uc720\ud588\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ubd80\uc790\uac00 \ub41c \uc99d\uac70\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ud68c\uc0ac \uc218\uc775\uc5d0 \ub300\ud55c \uae30\ub300\uc640 \uac00\uaca9 \uc0c1\uc2b9\uc5d0 \ub300\ud55c \uae30\ub300\ub294 \ub2e4\ub974\ub2e4. \uc9c0\uae08 \ube44\uc2f8\uac8c \ud314 \uc218 \uc788\uc73c\ub9ac\ub77c\ub294 \ubbff\uc74c\uc774 \uac15\ud574\uc9c0\uba74 \ub098\uc911\uc758 \uc0ac\uc5c5 \uc131\uacfc\ub97c \uae30\ub2e4\ub9b4 \uc774\uc720\ub294 \uc791\uc544\uc9c4\ub2e4. \uba40\ub9ac \uc788\ub294 \uac15\uc758 \uc774\ub984\uc740 \uac00\uae4c\uc6b4 \uc2dc\uc7a5\uc758 \uc5f4\uae30\ub97c \ub04c\uc5b4\uc62c\ub9ac\ub294 \uc0c1\uc9d5\uc774 \ub418\uc5c8\ub2e4. \uc740\ud589\uad8c\uacfc \uc8fc\uc2dd\uc5d0 \ub300\ud55c \uc2e0\ub8b0\uac00 \ud754\ub4e4\ub9ac\uc790 \uae08\uc18d \ub3c8\uc744 \ud655\ubcf4\ud558\ub824\ub294 \uc694\uad6c\uc640 \uac00\uaca9 \ud558\ub77d\uc774 \ub9de\ubb3c\ub838\ub2e4. \ubc1c\ud589\uacfc \uc9c0\uae09, \uad50\ud658 \uc870\uac74\uc744 \ubc14\uafb8\ub294 \uc870\uce58\ub3c4 \ud63c\ub780\uc744 \ub354\ud588\ub2e4. \ud55c\ucabd\uc758 \ubd88\uc548\uc774 \ub2e4\ub978 \ucabd\uc73c\ub85c \ubc88\uc9c8 \uc218 \uc788\ub294 \uad6c\uc870\uc600\ub2e4. \ud68c\uc0ac\uc758 \ubbf8\ub798 \uc774\uc775\uc774 \uace7\ubc14\ub85c \ubaa8\ub450\uc758 \ud604\uc7ac \uc9c0\uae09 \uc694\uad6c\ub97c \uac10\ub2f9\ud574 \uc8fc\uc9c0\ub294 \ubabb\ud588\ub2e4. \uad6d\uac00\uac00 \uad00\uc5ec\ud588\ub2e4\uace0 \ud574\uc11c \uae30\ub300\uc640 \uc2e4\uc81c \uc790\uc6d0\uc758 \uac04\uaca9\uc774 \uc0ac\ub77c\uc9c0\ub294 \uac83\ub3c4 \uc544\ub2c8\uc5c8\ub2e4. \uacb0\uad6d \uccb4\uacc4\ub294 \ubb34\ub108\uc84c\uace0 \ub85c\ub294 \ud504\ub791\uc2a4\ub97c \ub5a0\ub0ac\ub2e4. \uc774 \uc0ac\uac74\uc744 \uc885\uc774\ub294 \uac00\uc9dc\uc774\uace0 \uae08\uc18d\ub9cc \uc9c4\uc9dc\ub77c\ub294 \uad50\ud6c8\uc73c\ub85c \uc904\uc774\uba74 \uc774\ud6c4 \ud654\ud3d0\uc758 \uc5ed\uc0ac\uc640\ub3c4 \ub9de\uc9c0 \uc54a\ub294\ub2e4. \uc885\uc774\ub3c8\uc744 \uc0ac\uc6a9\ud55c\ub2e4\ub294 \uc0ac\uc2e4 \uc790\uccb4\ubcf4\ub2e4 \ubb34\uc5c7\uc744 \uc57d\uc18d\ud558\uace0 \uc5b4\ub5bb\uac8c \ubc1c\ud589\ud558\uba70 \uc5b4\ub5a4 \uc81c\ub3c4\uac00 \uadf8\uac83\uc744 \uc9c0\ud0f1\ud558\ub294\uc9c0 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \ubbf8\ub798 \uc218\uc775\uacfc \uc2e0\uc6a9\uc740 \uacbd\uc81c \ud65c\ub3d9\uc5d0 \uc911\uc694\ud558\ub2e4. \ud558\uc9c0\ub9cc \uadf8\uac83\ub4e4\uc774 \uc11c\ub85c\ub97c \uadfc\uac70\ub85c \ub05d\uc5c6\uc774 \ucee4\uc9c8 \uc218 \uc788\ub2e4\uace0 \uc5ec\uae30\uba74 \uc704\ud5d8\ud558\ub2e4. \ubbf8\uc2dc\uc2dc\ud53c\uc758 \uc704\uae30\ub294 \uc5ec\ub7ec \uc57d\uc18d\uc774 \uacb0\ud569\ub41c \uccb4\uacc4\uc5d0\uc11c \uc2e0\ub8b0\uac00 \ud568\uaed8 \ubb34\ub108\uc9c8 \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ud6c4\ub300\uc758 \uc800\uc790 \ucc30\uc2a4 \ub9e4\ucf00\uc774\ub294 \uc774 \uc0ac\uac74\uc744 \uc9d1\ub2e8\uc801 \uc5f4\ud48d\uc758 \ub300\ud45c\ub85c \uc11c\uc220\ud588\ub2e4. \uadf8\uc758 \ucc45\uc5d0\ub294 \uadf9\uc801\uc778 \uc7a5\uba74\uacfc \uc778\ubb3c \ud3c9\uac00\uac00 \ub9ce\ub2e4. \uc0ac\uac74 \ub2f9\uc2dc\uc758 \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \ub611\uac19\uc740 \uc0dd\uac01\uc744 \ud588\ub2e4\ub294 \uc99d\uc5b8\uc73c\ub85c \uc77d\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc560\ub364 \uc2a4\ubbf8\uc2a4\ub3c4 \ub4a4\uc5d0 \uc774 \uacc4\ud68d\uc744 \ube44\ud310\ud588\uc9c0\ub9cc \uadf8 \uc5ed\uc2dc \ubd95\uad34 \uc774\ud6c4\uc758 \ub17c\ud3c9\uc790\ub2e4. \uc774 \uae00\uc740 \ud655\uc778\ud560 \uc218 \uc788\ub294 \uc81c\ub3c4\uc758 \uc5f0\uacb0\uacfc \uc8fc\uc694 \ud750\ub984\uc744 \uc911\uc2ec\uc73c\ub85c \uc37c\ub2e4. \uc815\ud655\ud55c \uc8fc\uac00\ub098 \uad70\uc911\uc758 \ub300\ud654, \uae30\ub9c9\ud78c \uc77c\ud654\ub97c \ub354\ud558\uc9c0 \uc54a\uc544\ub3c4 \uad6c\uc870 \uc790\uccb4\uac00 \ucda9\ubd84\ud788 \ud765\ubbf8\ub86d\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc874 \ub85c\uc758 \ud310\ud654\ub294 1720\ub144\uc758 \uc791\ud488\uc73c\ub85c \uc18c\uac1c\ub418\ub294 \ub3c4\ud310\uc744 \ud6c4\ub300 \ucc45\uc774 \uc7ac\uc218\ub85d\ud55c \uac83\uc774\ub2e4. \uc5bc\uad74 \ud558\ub098\uac00 \ubcf5\uc7a1\ud55c \uc81c\ub3c4 \uc804\uccb4\ub97c \ub300\uc2e0\ud558\uc9c0\ub294 \ubabb\ud55c\ub2e4. \uadf8\uc758 \uad6c\uc0c1\uc774 \ubc1b\uc544\ub4e4\uc5ec\uc9c4 \ubc30\uacbd\uacfc \uad8c\ub825\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ubbf8\uc2dc\uc2dc\ud53c\ub77c\ub294 \uc774\ub984\uc744 \uae30\uc5b5\ud560 \ub54c \ud0d0\uc695\uc2a4\ub7ec\uc6b4 \uad70\uc911\ub9cc \ub5a0\uc62c\ub9ac\uc9c0 \uc54a\uc544\ub3c4 \uc88b\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \uc0c8\ub85c\uc6b4 \uac70\ub798\uc758 \ud3b8\ub9ac\ud568\uacfc \uad6d\uac00\uc758 \uc7ac\uc815 \uac1c\uc120, \uc790\uc2e0\uc758 \ubd80\ub97c \ud55c\uaebc\ubc88\uc5d0 \uae30\ub300\ud588\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ud76c\ub9dd\uc774 \ud558\ub098\uc758 \uac00\uaca9\uc5d0 \uc2e4\ub838\uc744 \ub54c \ubb34\uc5c7\uc774 \uc0dd\uae30\ub294\uc9c0\uac00 \uc774 \uc5ed\uc0ac\uc758 \uc9c8\ubb38\uc774\ub2e4."}, {"id": "kublai-paper-money-and-seal", "title": "\ucfe0\ube4c\ub77c\uc774\uc758 \uc9c0\ud3d0 \u2014 \ub098\ubb34\uaecd\uc9c8\uc774 \ub3c8\uc774 \ub418\ub358 \uc81c\uad6d", "summary": "\ub9c8\ub974\ucf54 \ud3f4\ub85c\uc758 \ud654\ud3d0 \uc11c\uc220\uacfc \uc6d0 \uc655\uc870\uc758 \uacbd\uc81c\uc0ac\ub97c \ub300\uc870\ud574 \uc885\uc774\ub3c8\u00b7\uad8c\ub825\u00b7\uac70\ub798\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "finance", "category_title": "\ub3c8\uacfc \uae08\uc735", "subcategory": "\ub3c8\uacfc \ud654\ud3d0", "categories": ["finance"], "url": "stories/kublai-paper-money-and-seal/index.html", "image": "../media/kublai-paper-money-and-seal.png", "alt": "\uc885\uc774\uc640 \ubd93, \uc778\uc7a5\uc744 \ub193\uace0 \ubb38\uc11c\ub97c \uc0b4\ud53c\ub294 \uad00\ub9ac\uc640 \uc5ec\ud589 \uc9d0\uc744 \ub4e0 \uc0c1\uc778\uc758 \uc0c1\uc0c1 \uc18d \uc7a5\uba74.", "text": "\ucfe0\ube4c\ub77c\uc774\uc758 \uc9c0\ud3d0 \u2014 \ub098\ubb34\uaecd\uc9c8\uc774 \ub3c8\uc774 \ub418\ub358 \uc81c\uad6d \ub9c8\ub974\ucf54 \ud3f4\ub85c\uac00 \ub180\ub77c\uba70 \uae30\ub85d\ud55c \uc885\uc774\uc640 \ubd89\uc740 \uc778\uc7a5 \ub9c8\ub974\ucf54 \ud3f4\ub85c\uc758 \ud654\ud3d0 \uc11c\uc220\uacfc \uc6d0 \uc655\uc870\uc758 \uacbd\uc81c\uc0ac\ub97c \ub300\uc870\ud574 \uc885\uc774\ub3c8\u00b7\uad8c\ub825\u00b7\uac70\ub798\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ub3c8\uacfc \ud654\ud3d0 \ub3c8\uacfc \uae08\uc735 \ub9c8\ub974\ucf54 \ud3f4\ub85c\ub294 \uc911\uad6d\uc5d0\uc11c \ubcf8 \ub3c8\uc744 \uc124\uba85\ud558\uba70 \uc5f0\uae08\uc220\uc744 \ub5a0\uc62c\ub838\ub2e4. \uae08\uacfc \uc740\uc744 \ub9cc\ub4e4\ub824\ub294 \uc0ac\ub78c\uc774 \ub9ce\ub358 \uc2dc\ub300\uc5d0 \ucfe0\ube4c\ub77c\uc774 \uce78\uc740 \ub098\ubb34\uc5d0\uc11c \uc5bb\uc740 \uc7ac\ub8cc\ub85c \ub3c8\uc744 \ub9cc\ub4e0\ub2e4\ub294 \uac83\uc774\uc5c8\ub2e4. \uc885\uc774\ub97c \uadc0\uae08\uc18d\ucc98\ub7fc \uc0ac\uc6a9\ud55c\ub2e4\ub294 \ubc1c\uc0c1\uc740 \uba3c \uacf3\uc5d0\uc11c \uc628 \uc5ec\ud589\uc790\uc5d0\uac8c \ub180\ub78d\uac8c \ubcf4\uc600\ub2e4. \ubb3c\ub860 \uc885\uc774\uac00 \uc2e4\uc81c\ub85c \uae08\uc73c\ub85c \ubcc0\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ud3f4\ub85c\uc758 \uc5ec\ud589\uae30\uc5d0 \ub098\ud0c0\ub098\ub294 \uac83\uc740 \uc885\uc774\uc640 \uae00, \uc778\uc7a5, \uadf8\ub9ac\uace0 \uadf8\uac83\uc744 \ud1b5\uc6a9\uc2dc\ud0a4\ub294 \uad8c\ub825\uc774\ub2e4. \uc624\ub798\ub41c \uae30\ub85d\uc758 \ub180\ub77c\uc6c0\uc744 \ub530\ub77c\uac00\uba74 \uc9c0\ud3d0\uac00 \ub2e8\uc21c\ud788 \uac00\ubcbc\uc6b4 \ub3d9\uc804\uc744 \ub73b\ud558\uc9c0 \uc54a\uc558\ub358 \uc774\uc720\ub97c \ub9cc\ub098\uac8c \ub41c\ub2e4. \ud3f4\ub85c\ub294 \ucfe0\ube4c\ub77c\uc774\uc758 \uc218\ub3c4\ub97c \uce84\ubc1c\ub8e8\ud06c\ub77c\uace0 \ubd80\ub974\uba70 \uadf8\uacf3\uc758 \ud654\ud3d0 \uc81c\uc791 \ubc29\uc2dd\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc624\ub298\ub0a0 \ubca0\uc774\uc9d5\uc5d0 \ud574\ub2f9\ud558\ub294 \ub3c4\uc2dc\ub2e4. \uadf8\ub294 \ubf55\ub098\ubb34\uc758 \ubc14\uae65\uaecd\uc9c8\uacfc \ubaa9\uc9c8 \uc0ac\uc774\uc758 \uc7ac\ub8cc\ub97c \uc0ac\uc6a9\ud574 \uc885\uc774\uc640 \ube44\uc2b7\ud55c \ud310\uc744 \ub9cc\ub4e4\uace0 \uc5ec\ub7ec \ud06c\uae30\ub85c \uc790\ub978\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc774\ub294 \ub2f9\uc2dc\uc758 \ubaa8\ub4e0 \uc9c0\ud3d0 \uc7ac\ub8cc\ub97c \ud604\ub300\uc758 \uc81c\uc870 \uaddc\uaca9\ucc98\ub7fc \uc778\uc99d\ud558\ub294 \uc124\uba85\uc740 \uc544\ub2c8\ub2e4. \uc5ec\ud589\uae30\uc758 \uad00\ucc30\uacfc \uc804\uc2b9, \ud6c4\ub300 \ubc88\uc5ed\uc744 \uac70\uce5c \uae30\ub85d\uc774\ub2e4. \ub2e4\ub9cc \ub0af\uc120 \ub3c8\uc744 \ub3c5\uc790\uc5d0\uac8c \uc774\ud574\uc2dc\ud0a4\uae30 \uc704\ud574 \uc7ac\ub8cc\uc640 \ubaa8\uc591\ubd80\ud130 \uad6c\uccb4\uc801\uc73c\ub85c \ud480\uc5b4\ub0b8 \ubc29\uc2dd\uc740 \uc9c0\uae08 \uc77d\uc5b4\ub3c4 \uc0dd\uc0dd\ud558\ub2e4. \uae30\ub85d\uc5d0\ub294 \uad00\ub9ac\ub4e4\uc774 \uc774\ub984\uc744 \uc4f0\uace0 \uc778\uc7a5\uc744 \ucc0d\ub294 \uacfc\uc815\uc774 \ub098\uc628\ub2e4. \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \ubd89\uc740 \uc0c9\uc744 \ubb3b\ud78c \uacf5\uc2dd \uc778\uc7a5\uc774 \ub354\ud574\uc9c4\ub2e4. \uc544\ubb34 \uc885\uc774\ub098 \uac19\uc740 \uad6c\uc2e4\uc744 \ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc815\ud574\uc9c4 \uc808\ucc28\ub97c \uac70\uccd0 \uc2b9\uc778\ub41c \ud45c\uc9c0\uac00 \ubd99\ub294\ub2e4\ub294 \uc124\uba85\uc774\ub2e4. \uc774 \uc7a5\uba74\uc5d0\uc11c \uc911\uc694\ud55c \uac83\uc740 \uc544\ub984\ub2e4\uc6b4 \ub3c4\uc7a5\ub9cc\uc774 \uc544\ub2c8\ub2e4. \ub204\uac00 \ubc1c\ud589\ud558\uace0 \ubb34\uc5c7\uc73c\ub85c \uc9c4\uc9dc\uc784\uc744 \ub4dc\ub7ec\ub0b4\ub294\uc9c0\uac00 \uac70\ub798\uc758 \uc870\uac74\uc774\uc5c8\ub2e4. \ub3c8\uc758 \uc7ac\ub8cc\uac00 \uadc0\ud558\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ubc1c\ud589\ud55c \ucabd\uc758 \uad8c\uc704\ub97c \uc778\uc815\ud55c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub978 \uc885\ub958\uc758 \uadfc\uac70\ub2e4. \ud3f4\ub85c\ub294 \uadf8 \ucc28\uc774\ub97c \uc790\uae30 \ub3c5\uc790\uc5d0\uac8c \ub180\ub77c\uc6b4 \uac83\uc73c\ub85c \uc804\ub2ec\ud588\ub2e4. \ud3f4\ub85c\ub294 \uc885\uc774\ub3c8\uc774 \uadc0\uae08\uc18d\uc5d0 \ube44\ud574 \uac00\ubccd\uace0 \uc5ec\ud589 \uc911\uc5d0 \uac00\uc9c0\uace0 \ub2e4\ub2c8\uae30 \ud3b8\ud558\ub2e4\uace0 \uc37c\ub2e4. \ub0af\uc120 \uacf3\uc5d0\uc11c \ubb3c\uac74\uc744 \uc0ac\ub294 \uc0c1\uc778\uc5d0\uac8c \ubb34\uac8c\ub294 \uc2e4\uc81c \ubb38\uc81c\uc600\ub2e4. \uba3c \uae38\uc5d0 \uc4f8 \uac00\uce58\ub97c \uc5b4\ub5a4 \ud615\ud0dc\ub85c \uc6b4\ubc18\ud560 \uc218 \uc788\ub294\uc9c0\uac00 \uc911\uc694\ud588\uae30 \ub54c\ubb38\uc774\ub2e4. \uadf8\ub7ec\ub098 \uac00\ubccd\uae30\ub9cc \ud558\uba74 \uc5b4\ub514\uc11c\ub098 \ub3c8\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0c1\ub300\uac00 \uadf8 \uc885\uc774\ub97c \uc9c0\uae09 \uc218\ub2e8\uc73c\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc57c \ud55c\ub2e4. \uae30\ub85d \uc18d\uc758 \ud3b8\ub9ac\ud568\uc740 \ub3c8\uc774 \uc4f0\uc774\ub294 \ubc94\uc704\uc640 \ubc1c\ud589 \uad8c\ub825\uc774 \uc791\ub3d9\ud558\ub294 \uc9c0\uc5ed\uc774\ub77c\ub294 \uc870\uac74 \uc704\uc5d0 \ub193\uc5ec \uc788\ub2e4. \uc5ec\ud589\uc758 \uc9d0\uc774 \uac00\ubcbc\uc6cc\uc9c4 \uc774\uc57c\uae30 \ub4a4\uc5d0\ub294 \ub113\uc740 \ud1b5\uc6a9\uc758 \uc7a5\uce58\uac00 \uc788\uc5c8\ub2e4. \ud3f4\ub85c\uc758 \uc11c\uc220\uc5d0\ub294 \ub3c8\uc744 \uc4f0\uac8c \ud558\ub294 \uac15\ud55c \uba85\ub839\ub3c4 \ub4f1\uc7a5\ud55c\ub2e4. \ud604\ub300\uc758 \ub3c5\uc790\ub294 \ud3b8\ub9ac\ud55c \ubc1c\uba85\uc744 \ubaa8\ub450\uac00 \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc120\ud0dd\ud55c \uc7a5\uba74\uc73c\ub85c\ub9cc \uc77d\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uad50\uc7ac\ub3c4 \uc6d0 \uc815\ubd80\uac00 \uad6d\uac00\uc640\uc758 \uac70\ub798\uc5d0\uc11c \uc9c0\ud3d0\ub97c \uc0ac\uc6a9\ud558\uac8c \ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubb34\uc5c7\uc744 \uc138\uae08\uacfc \uc9c0\uae09\uc5d0 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294\uc9c0\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc120\ud0dd\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4. \uc9c0\ud3d0\uc758 \uc0ac\uc6a9\uc740 \ubb3c\uac74\uc758 \uc131\uc9c8\ubfd0 \uc544\ub2c8\ub77c \uc81c\ub3c4\uc640 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \ud3f4\ub85c\uac00 \ubb18\uc0ac\ud55c \ud3ed\ub113\uc740 \ud1b5\uc6a9\uc744 \ubaa8\ub4e0 \uac1c\uc778\uc758 \ub9cc\uc871\ub3c4\ub098 \uc81c\uad6d\uc758 \ub9e4\uc77c\uc758 \uc2e4\uc81c \uc0c1\ud669\uae4c\uc9c0 \ud655\uc778\ud55c \uc870\uc0ac\ucc98\ub7fc \ubc1b\uc544\ub4e4\uc77c \uc218\ub294 \uc5c6\ub2e4. \ud3f4\ub85c\ub294 \uce78\uc774 \uc801\uc740 \ube44\uc6a9\uc73c\ub85c \uc5c4\uccad\ub09c \ubd80\ub97c \uc5bb\ub294 \ub4ef\ud55c \ud45c\ud604\uc744 \uc4f4\ub2e4. \ud558\uc9c0\ub9cc \uc5ec\ud589\uc790\uc758 \uac10\ud0c4\uc744 \ub3c8\uc744 \ubc1c\ud589\ud558\uba74 \uc544\ubb34 \ube44\uc6a9 \uc5c6\uc774 \ubb34\uc5c7\uc774\ub4e0 \uc0b4 \uc218 \uc788\ub2e4\ub294 \ubc95\uce59\uc73c\ub85c \uc62e\uae38 \uc218\ub294 \uc5c6\ub2e4. \uc885\uc774\ub97c \ub9cc\ub4e4 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8 \ub3c8\uc758 \uad6c\ub9e4\ub825\uc774 \uc720\uc9c0\ub41c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub974\ub2e4. \uc6d0 \uc655\uc870\uc758 \uc5ed\uc0ac\ub97c \ub2e4\ub8ec \uad50\uc7ac\uc5d0\ub294 \uc804\uc7c1 \ube44\uc6a9\uacfc \uc138\uae08, \ubc1c\ud589 \ud655\ub300\uc640 \ubb3c\uac00 \uc0c1\uc2b9\uc758 \ubb38\uc81c\uac00 \ud568\uaed8 \ub098\ud0c0\ub09c\ub2e4. \ud3b8\ub9ac\ud55c \uc9c0\uae09 \uc218\ub2e8\uc744 \uac00\uc9c4 \uc815\ubd80\ub3c4 \uc7ac\uc815\uacfc \uc0dd\uc0b0\uc758 \uc81c\uc57d\uc5d0\uc11c \uc790\uc720\ub86d\uc9c0 \uc54a\uc558\ub2e4. \uc5ec\ud589\uae30\uc5d0 \ube44\uce5c \ud654\ub824\ud55c \ubaa8\uc2b5\uacfc \uae34 \uc2dc\uac04\uc758 \uacbd\uc81c\uc0ac\ub294 \ub2e4\ub978 \ubc94\uc704\ub97c \ubcf4\uc5ec \uc900\ub2e4. \ucfe0\ube4c\ub77c\uc774\uc640 \ud6c4\uacc4 \uc815\ubd80\ub4e4\uc740 \uad70\uc0ac \uc6d0\uc815\uacfc \uad8c\ub825 \ub2e4\ud23c, \uc7ac\uc815 \ubd80\ub2f4\uc744 \uacaa\uc5c8\ub2e4. \uad50\uc7ac\ub294 \ub354 \ub9ce\uc740 \uc9c0\ud3d0\uac00 \ubc1c\ud589\ub418\uace0 \uc8fc\ubbfc\uc774 \uc138\uae08\uc744 \ub0b4\uae30 \uc704\ud574 \uadf8 \ub3c8\uc744 \uad6c\ud574\uc57c \ud588\ub358 \uc0c1\ud669\uc744 \uc124\uba85\ud55c\ub2e4. \ub3c8\uc744 \uc0ac\uc6a9\ud558\ub294 \uc758\ubb34\uc640 \uadf8 \ub3c8\uc758 \uac00\uce58\uac00 \ud754\ub4e4\ub9ac\ub294 \uacbd\ud5d8\uc774 \uacb9\uce60 \uc218 \uc788\uc5c8\ub2e4. \uc774\ub97c \ud604\ub300\uc758 \ubaa8\ub4e0 \uc885\uc774\ub3c8\uc5d0\ub294 \uac19\uc740 \uacb0\ub9d0\uc774 \uc815\ud574\uc838 \uc788\ub2e4\ub294 \uad50\ud6c8\uc73c\ub85c \ubc14\uafb8\uba74 \uc5ed\uc0ac\ub97c \ub108\ubb34 \ub2e8\uc21c\ud558\uac8c \uc77d\uac8c \ub41c\ub2e4. \ub2f9\uc2dc\uc758 \uc81c\ub3c4\uc640 \uc7ac\uc815, \uc804\uc7c1\uacfc \uc0ac\ud68c \uc870\uac74\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ud55c \uc2dc\ub300\uc758 \uc0ac\ub840\ub294 \ub3c8\uc758 \uc7ac\ub8cc\ub9cc\uc73c\ub85c \uc131\uacf5\uacfc \uc2e4\ud328\ub97c \uc124\uba85\ud558\uae30 \uc5b4\ub835\ub2e4\ub294 \uc810\uc744 \uc624\ud788\ub824 \uc54c\ub824 \uc900\ub2e4. \uc5ec\ud589\uae30\uc5d0\ub294 \uc190\uc0c1\ub41c \ub3c8\uc744 \uc0c8\uac83\uc73c\ub85c \ubc14\uafb8\ub294 \uc124\uba85\ub3c4 \uc788\ub2e4. \uc885\uc774\uac00 \ub0a1\uc73c\uba74 \uac70\ub798\uac00 \ub05d\ub098\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uad50\ud658\uacfc \uad00\ub9ac\uc758 \uc808\ucc28\uac00 \ud544\uc694\ud588\ub2e4\ub294 \uac83\uc774\ub2e4. \ub3c8\uc744 \ubc1c\ud589\ud558\ub294 \uc77c\uacfc \uacc4\uc18d \uc0ac\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d \uc6b4\uc601\ud558\ub294 \uc77c\uc740 \uac19\uc740 \uc774\uc57c\uae30\uc758 \uc11c\ub85c \ub2e4\ub978 \ubd80\ubd84\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc885\uc774\uc640 \uc778\uc7a5\uc744 \ub2e4\ub8e8\ub294 \uc0c1\uc0c1 \uc18d \uad00\uccad \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c \uc6d0 \uc9c0\ud3d0\uc758 \ub3c4\uc548\uc774\ub098 \ud654\ud3d0 \uc81c\uc791\uc18c\ub97c \uace0\uc99d\ud574 \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uae00\uc758 \uadfc\uac70\ub294 \uc5ec\ud589\uae30\uc640 \uc5ed\uc0ac \uad50\uc7ac\uc5d0 \ub450\uace0 \uadf8\ub9bc\uc5d0\uc11c\ub294 \uc885\uc774\ub3c8\uc774 \uacf5\uc801\uc778 \ud45c\uc9c0\ub97c \uc5bb\ub294 \ubd84\uc704\uae30\ub97c \ub5a0\uc62c\ub9ac\uba74 \ub41c\ub2e4. \ub9c8\ub974\ucf54 \ud3f4\ub85c\uc5d0\uac8c \uc885\uc774\ub3c8\uc740 \uc5f0\uae08\uc220\ucc98\ub7fc \ubcf4\uc600\uc9c0\ub9cc \uadf8 \uc791\ub3d9\uc5d0\ub294 \uad00\ub9ac\uc758 \uc190\uacfc \uc2dc\uc7a5\uc758 \uac70\ub798, \uc138\uae08\uc744 \uac70\ub450\ub294 \uc815\ubd80\uac00 \uc788\uc5c8\ub2e4. \uac00\ubcbc\uc6b4 \ubb3c\uac74 \ud55c \uc7a5\uc774 \uba3c \uc9c0\uc5ed\uc744 \uc5f0\uacb0\ud560 \uc218 \uc788\uc5c8\ub358 \uc774\uc720\ub294 \uc7ac\ub8cc\ub9cc\ud07c \uadf8 \uc8fc\ubcc0\uc758 \uad00\uacc4\uc5d0 \uc788\uc5c8\ub2e4. \uc624\ub298\uc758 \uc9c0\ud3d0\ub97c \ubcfc \ub54c\ub3c4 \uc885\uc774\uac12\uacfc \uadf8 \uc704\uc758 \uc22b\uc790\uac00 \uc65c \ub2e4\ub978\uc9c0 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \ucfe0\ube4c\ub77c\uc774 \uc2dc\ub300\uc758 \ub3c8\uc740 \uc774 \uc9c8\ubb38\uc744 \uba3c \uc5ed\uc0ac \uc18d\uc5d0\uc11c \ub2e4\uc2dc \ubcf4\uac8c \ud558\ub294 \uc0ac\ub840\ub2e4. \uc5ec\ud589\uc790\uc758 \ub180\ub77c\uc6c0\uacfc \uc8fc\ubbfc\uc774 \uacaa\uc740 \ubd80\ub2f4\uc744 \ub098\ub780\ud788 \uc77d\uc73c\uba74 \ub3c8\uc758 \uc5ed\uc0ac\ub294 \uc2e0\uae30\ud55c \ubc1c\uba85\ub2f4\ubcf4\ub2e4 \ud6e8\uc52c \uc785\uccb4\uc801\uc778 \uc774\uc57c\uae30\uac00 \ub41c\ub2e4."}, {"id": "lloyds-coffeehouse-shipping-news", "title": "\ub85c\uc774\uc988 \u2014 \ucee4\ud53c\ud558\uc6b0\uc2a4\uc5d0\uc11c \uc790\ub77c\ub09c \ud574\uc0c1\ubcf4\ud5d8", "summary": "\uc5d0\ub4dc\uc6cc\ub4dc \ub85c\uc774\ub4dc\uc758 \ucee4\ud53c\ud558\uc6b0\uc2a4\uc640 \ud6c4\ub300\uc758 \uc120\ubc15 \uc815\ubcf4\uc2e4\uc744 \ub530\ub77c \ud574\uc0c1\ubcf4\ud5d8\uacfc \uae30\ub85d\uc758 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "finance", "category_title": "\ub3c8\uacfc \uae08\uc735", "subcategory": "\ubcf4\ud5d8\uacfc \uc704\ud5d8", "categories": ["finance"], "url": "stories/lloyds-coffeehouse-shipping-news/index.html", "image": "../media/lloyds-coffeehouse-shipping-news.jpg", "alt": "\ud6c4\ub300 \ub85c\uc5f4 \uc775\uc2a4\uccb4\uc778\uc9c0 \ub85c\uc774\uc988 \uad6c\ub3c5\uc790\uc2e4\uc758 \uc5ed\uc0ac \ub3c4\ud310. \ud070 \uae30\ub465\uacfc \uae34 \ucc45\uc0c1, \ubaa8\uc778 \uc0ac\ub78c\ub4e4.", "text": "\ub85c\uc774\uc988 \u2014 \ucee4\ud53c\ud558\uc6b0\uc2a4\uc5d0\uc11c \uc790\ub77c\ub09c \ud574\uc0c1\ubcf4\ud5d8 \ubc30\uc758 \uc18c\uc2dd\uc774 \ub3c8\uc758 \uc57d\uc18d\uc73c\ub85c \uc774\uc5b4\uc9c0\ub358 \ub7f0\ub358 \uc5d0\ub4dc\uc6cc\ub4dc \ub85c\uc774\ub4dc\uc758 \ucee4\ud53c\ud558\uc6b0\uc2a4\uc640 \ud6c4\ub300\uc758 \uc120\ubc15 \uc815\ubcf4\uc2e4\uc744 \ub530\ub77c \ud574\uc0c1\ubcf4\ud5d8\uacfc \uae30\ub85d\uc758 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ubcf4\ud5d8\uacfc \uc704\ud5d8 \ub3c8\uacfc \uae08\uc735 17\uc138\uae30 \ub9d0 \ub7f0\ub358\uc758 \ud55c \ucee4\ud53c\ud558\uc6b0\uc2a4\uc5d0 \ubc30\uc640 \ud654\ubb3c\uc5d0 \uad00\uc2ec\uc744 \uac00\uc9c4 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc600\ub2e4. \uc5b4\ub290 \ubc30\uac00 \ub5a0\ub0ac\uace0 \uc5b4\ub290 \ud56d\uad6c\uc5d0 \ub3c4\ucc29\ud588\ub294\uc9c0, \ubc14\ub2e4\uc5d0\uc11c \ubb34\uc2a8 \uc77c\uc774 \uc788\uc5c8\ub294\uc9c0\ub97c \uc54c\uace0 \uc2f6\uc5b4 \ud558\ub294 \uc0ac\ub78c\ub4e4\uc774\uc5c8\ub2e4. \ub530\ub73b\ud55c \uc74c\ub8cc\ub97c \ub9c8\uc2dc\ub294 \uc790\ub9ac\uc5d0\uc11c \ub2e4\uc74c \uac70\ub798\ub97c \ubc14\uafc0 \uc18c\uc2dd\uc774 \uc624\uac14\ub2e4. \uac00\uac8c \uc8fc\uc778\uc758 \uc774\ub984\uc740 \uc5d0\ub4dc\uc6cc\ub4dc \ub85c\uc774\ub4dc\uc600\ub2e4. \uadf8\uc758 \uc774\ub984\uc744 \ub534 \ub85c\uc774\uc988\uc758 \uc5ed\uc0ac\ub294 \ucee4\ud53c\uac00 \ud2b9\ubcc4\ud55c \uae08\uc735 \uc0c1\ud488\uc774\uc5b4\uc11c \uc2dc\uc791\ub41c \uac83\uc774 \uc544\ub2c8\ub2e4. \uac19\uc740 \uc815\ubcf4\ub97c \ud544\uc694\ub85c \ud558\ub294 \uc0ac\ub78c\ub4e4\uc774 \uac19\uc740 \uc7a5\uc18c\uc5d0\uc11c \ub9cc\ub0ac\uace0, \uadf8 \ub9cc\ub0a8\uc774 \ud574\uc0c1 \uc704\ud5d8\uc744 \ub098\ub204\ub294 \uac70\ub798\uc640 \uc774\uc5b4\uc84c\ub2e4. \uc70c\ub9ac\uc5c4 \uc720\ucee4\uc2a4\uc758 1922\ub144 \ucc45 \u300e\ucee4\ud53c\uc758 \ubaa8\ub4e0 \uac83\u300f\uc740 \ub85c\uc774\ub4dc\uac00 1688\ub144 \ubb34\ub835 \ub7f0\ub358 \ud0c0\uc6cc \uc2a4\ud2b8\ub9ac\ud2b8\uc5d0\uc11c \ucee4\ud53c\ud558\uc6b0\uc2a4\ub97c \uc6b4\uc601\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc774\ud6c4 \uac00\uac8c\ub294 \ub86c\ubc14\ub4dc \uc2a4\ud2b8\ub9ac\ud2b8\ub85c \uc62e\uaca8 \uac14\ub2e4. \ucc98\uc74c\ubd80\ud130 \uc624\ub298\uc758 \ud070 \uae08\uc735\uae30\uad00 \uac19\uc740 \ubaa8\uc2b5\uc73c\ub85c \ubb38\uc744 \uc5f0 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc774\uacf3\uc758 \uc190\ub2d8\uc5d0\ub294 \uc120\uc6d0\uacfc \uc0c1\uc778\ub4e4\uc774 \uc788\uc5c8\ub2e4. \ubc43\uae38\uacfc \uac70\ub798\uc758 \uc0c1\ud669\uc5d0 \uad00\ud55c \uc815\ubcf4\uac00 \uc77c\uacfc \uc5f0\uacb0\ub41c \uc0ac\ub78c\ub4e4\uc774\uc5c8\ub2e4. \uc5b4\ub5a4 \ucee4\ud53c\ud558\uc6b0\uc2a4\uac00 \ubb38\ud559\uac00\uc758 \ubaa8\uc784\uc73c\ub85c \uc54c\ub824\uc9c0\uace0 \ub2e4\ub978 \uacf3\uc774 \uc815\uce58\uc801 \ub300\ud654\uc758 \uc7a5\uc18c\uac00 \ub41c \uac83\ucc98\ub7fc, \ub85c\uc774\ub4dc\uc758 \uac00\uac8c\uc5d0\ub294 \ubc14\ub2e4\uc5d0 \uad00\ud55c \uad00\uc2ec\uc774 \ubaa8\uc600\ub2e4. \uc720\ucee4\uc2a4\ub294 \ub85c\uc774\ub4dc\uac00 \uc190\ub2d8\uc744 \uc704\ud574 \uc120\ubc15 \ubaa9\ub85d\uc744 \uc900\ube44\ud588\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ucd08\uae30\uc5d0\ub294 \uc190\uc73c\ub85c \uc4f4 \uc815\ubcf4\uc600\ub2e4. \ud574\uc0c1\ubcf4\ud5d8\uc744 \ub2e4\ub8e8\ub294 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uc81c\uc2dc\ub420 \uc218 \uc788\ub294 \ubc30\uac00 \uc5b4\ub5a4 \uac83\uc778\uc9c0 \uc54c\uc544\ubcf4\ub294 \ub370 \uc4f0\uc600\ub2e4. \uac00\uac8c\ub294 \ub2e8\uc21c\ud788 \ub300\ud654\ub97c \ub4e3\ub294 \uacf5\uac04\uc5d0\uc11c \uc815\ub9ac\ub41c \uc815\ubcf4\ub97c \uc81c\uacf5\ud558\ub294 \uc790\ub9ac\ub85c\ub3c4 \uae30\ub2a5\ud588\ub2e4. \uc624\ub298\uc740 \uc120\ubc15\uc758 \uc704\uce58\ub97c \ud654\uba74\uc5d0\uc11c \ubcf4\ub294 \uc77c\uc774 \uac00\ub2a5\ud558\uc9c0\ub9cc \ub2f9\uc2dc\uc5d0\ub294 \uc18c\uc2dd\uc774 \uc5b4\ub514\uc11c \uc640\uc11c \ub204\uad6c\uc5d0\uac8c \ubaa8\uc774\ub294\uc9c0\uac00 \uc911\uc694\ud588\ub2e4. \uba40\ub9ac\uc11c \ubc30\uac00 \uc0ac\ub77c\uc9c4 \uac83\uc778\uc9c0, \ub2a6\uac8c \ub3c4\ucc29\ud558\ub294 \uac83\uc778\uc9c0 \uad6c\ubd84\ud558\uae30 \uc5b4\ub824\uc6b4 \uc0c1\ud669\ub3c4 \uc788\uc5c8\ub2e4. \uc815\ubcf4\uac00 \ube60\ub974\uac8c \ubaa8\uc774\ub294 \uc7a5\uc18c\uc5d0\ub294 \uc0ac\ub78c\ub4e4\uc774 \ub2e4\uc2dc \ucc3e\uc544\uc62c \uc774\uc720\uac00 \uc0dd\uacbc\ub2e4. \ubc30\ub97c \ubcf4\ub0b4\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ub3c4\ucc29 \ub4a4\uc758 \uc218\uc775\ubfd0 \uc544\ub2c8\ub77c \ud56d\ud574 \uc911\uc758 \uc190\uc2e4\ub3c4 \ubb38\uc81c\uc600\ub2e4. \ud574\uc0c1\ubcf4\ud5d8\uc744 \ub9e1\ub294 \uc0ac\ub78c\uc740 \uc815\ud574\uc9c4 \uc870\uac74 \uc544\ub798 \uc704\ud5d8\uc758 \uc77c\ubd80\ub97c \ubd80\ub2f4\ud558\ub294 \ub300\uac00\ub97c \ubc1b\ub294\ub2e4. \ub530\ub77c\uc11c \uc5b4\ub5a4 \ubc30\uc640 \ud56d\ub85c\uc778\uc9c0\uc5d0 \uad00\ud55c \uc815\ubcf4\ub294 \ub3c8\uc758 \uc57d\uc18d\uacfc \uc9c1\uc811 \uc5f0\uacb0\ub41c\ub2e4. \ub85c\uc774\ub4dc\uc758 \uac00\uac8c\uac00 \ud765\ubbf8\ub85c\uc6b4 \uac83\uc740 \uc74c\ub8cc\uc640 \ubcf4\ud5d8\uc744 \ub2e8\uc21c\ud788 \ud55c \uc138\ud2b8\ub85c \ud314\uc558\ub2e4\ub294 \ub370 \uc788\uc9c0 \uc54a\ub2e4. \uc815\ubcf4\ub97c \uc8fc\uace0\ubc1b\uc744 \uc0ac\ub78c\uacfc \uac70\ub798\ub97c \ub17c\uc758\ud560 \uc0ac\ub78c\uc774 \ud55c\uacf3\uc5d0 \uc788\uc5c8\ub2e4\ub294 \uc810\uc774\ub2e4. \ucee4\ud53c\ud558\uc6b0\uc2a4\uc758 \ub300\ud654\uac00 \uc2e4\uc81c \uc704\ud5d8\uc744 \ud3c9\uac00\ud558\uace0 \uacc4\uc57d\uc744 \ub9fa\ub294 \uad00\uacc4\uc640 \ub9cc\ub0a0 \uc218 \uc788\uc5c8\ub2e4. \ud56d\uad6c\uc5d0\uc11c \ub4e4\ub824\uc628 \ub9d0\uc774 \uc5b8\uc81c\ub098 \uc815\ud655\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uac70\ub798\ub97c \ud310\ub2e8\ud558\ub824\uba74 \uc5b4\ub5a4 \ubc30\uc758 \uc5b4\ub5a4 \uc0ac\uac74\uc778\uc9c0 \uad6c\ubd84\ud574 \uae30\ub85d\ud560 \ud544\uc694\uac00 \uc788\ub2e4. \ud55c\uacf3\uc5d0 \uc18c\uc2dd\uc774 \ubaa8\uc778\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8 \uc18c\uc2dd\uc744 \uc0ac\uc6a9\ud560 \uc218 \uc788\uac8c \uc815\ub9ac\ud55c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub978 \uc885\ub958\uc758 \uc77c\uc774\ub2e4. \ub85c\uc774\uc988\uc758 \uc5ed\uc0ac\uc5d0\uc11c \uc120\ubc15 \ubaa9\ub85d\uacfc \uc7a5\ubd80\uac00 \ud568\uaed8 \ub4f1\uc7a5\ud558\ub294 \uc774\uc720\ub3c4 \uc5ec\uae30\uc5d0 \uc788\ub2e4. \ud574\uc0c1\ubcf4\ud5d8\uc758 \ubc1c\uc804\uc740 \uba4b\uc9c4 \uacc4\uc57d \ubb38\uad6c\ub9cc\uc758 \uc5ed\uc0ac\uac00 \uc544\ub2c8\uc5c8\ub2e4. \ubc30\uc758 \ucd9c\ud56d\uacfc \ub3c4\ucc29, \uc0ac\uace0\uc640 \uad6c\uc870\uc5d0 \uad00\ud55c \uc9c0\uc2dd\uc774 \ucd95\uc801\ub418\uace0 \uacf5\uc720\ub418\ub294 \uacfc\uc815\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \uc2dc\uac04\uc774 \ud750\ub974\uba70 \ub85c\uc774\uc988\uc640 \uad00\ub828\ub41c \uac70\ub798\uc640 \uc815\ubcf4\uc758 \uacf5\uac04\uc740 \ub354 \uc870\uc9c1\uc801\uc778 \ud615\ud0dc\ub85c \ubc1c\uc804\ud588\ub2e4. \uc720\ucee4\uc2a4\uc758 \ucc45\uc5d0\ub294 \ud6c4\ub300 \ub85c\uc5f4 \uc775\uc2a4\uccb4\uc778\uc9c0\uc758 \ubc29\ub4e4\uc774 \uc18c\uac1c\ub41c\ub2e4. \ubcf4\ud5d8\uc744 \ub9e1\ub294 \uc0ac\ub78c\ub4e4, \uc0c1\uc778\ub4e4, \uc120\uc7a5\ub4e4\uc774 \uc774\uc6a9\ud558\ub294 \uacf5\uac04\uacfc \uc120\ubc15 \uc815\ubcf4\uc758 \uc804\uc2dc\uac00 \uc124\uba85\ub41c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc5ed\uc0ac \ub3c4\ud310\ub3c4 \uc774 \ud6c4\ub300\uc758 \uad6c\ub3c5\uc790\uc2e4\uc744 \ubcf4\uc5ec \uc900\ub2e4. 1688\ub144 \ud0c0\uc6cc \uc2a4\ud2b8\ub9ac\ud2b8\uc758 \uccab \uac00\uac8c \ub0b4\ubd80\ub97c \uc9c1\uc811 \uadf8\ub9b0 \uadf8\ub9bc\uc740 \uc544\ub2c8\ub2e4. \ucd5c\ucd08\uc758 \ucee4\ud53c\ud558\uc6b0\uc2a4\uc640 \ub4a4\uc5d0 \ub9c8\ub828\ub41c \ud070 \uc815\ubcf4\uc2e4 \uc0ac\uc774\uc5d0\ub294 \uc2dc\uac04\uacfc \uc870\uc9c1\uc758 \ubcc0\ud654\uac00 \uc788\uc5c8\ub2e4. \uadf8\ub9bc\uc744 \ubcfc \ub54c \uadf8 \uac04\uaca9\uc744 \uae30\uc5b5\ud558\uba74 \uc88b\ub2e4. \ucc45\uc740 1848\ub144 \uc790\ub8cc\ub97c \uc778\uc6a9\ud574 \ub85c\uc774\uc988\uc758 \ud070 \uc7a5\ubd80\ub4e4\uc744 \uc124\uba85\ud55c\ub2e4. \ud55c\ucabd\uc5d0\ub294 \ub3c4\ucc29\ud588\uac70\ub098 \ud56d\ud574 \uc911 \uc18c\uc2dd\uc774 \uc804\ud574\uc9c4 \ubc30\ub4e4\uc774, \ub2e4\ub978 \ucabd\uc5d0\ub294 \ub09c\ud30c\uc640 \ud654\uc7ac, \uc2ec\ud55c \ucda9\ub3cc \uac19\uc740 \uc0ac\uac74\ub4e4\uc774 \uae30\ub85d\ub418\uc5c8\ub2e4. \ubc14\ub2e4\uc758 \uc774\uc57c\uae30\uac00 \uc11c\ub85c \ub2e4\ub978 \uc885\ub958\uc758 \uc815\ubcf4\ub85c \ubd84\ub958\ub418\uc5b4 \ub0a8\uc740 \uac83\uc774\ub2e4. \ubc29 \uc548\uc5d0\ub294 \ubc14\ub78c\uacfc \ube44\ub97c \uc0b4\ud53c\ub294 \uae30\uad6c\ub3c4 \uc788\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc774\ub294 17\uc138\uae30 \ucd5c\ucd08\uc758 \uac00\uac8c\uc5d0 \uadf8\ub7f0 \uc7a5\ube44\uac00 \ubaa8\ub450 \uc788\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud6c4\ub300\uc758 \uc804\ubb38 \uacf5\uac04\uc5d0\uc11c\ub294 \uc120\ubc15 \uc18c\uc2dd\ubfd0 \uc544\ub2c8\ub77c \ud56d\ud574\uc640 \uad00\ub828\ub41c \uc870\uac74\ub3c4 \ud568\uaed8 \uad00\ucc30\ud588\ub2e4\ub294 \uc124\uba85\uc73c\ub85c \uc77d\uc5b4\uc57c \ud55c\ub2e4. \uc720\ucee4\uc2a4\ub294 \ub85c\uc774\uc988\ub97c \ub9e4\uc6b0 \uc911\uc694\ud55c \uae30\uad00\uc73c\ub85c \ub192\uc774 \ud3c9\uac00\ud55c\ub2e4. \ub2e4\ub9cc 1922\ub144\uc758 \ucc45\uc5d0 \uc801\ud78c \uaddc\ubaa8\uc640 \ud65c\ub3d9\ub7c9\uc744 \uc624\ub298\uc758 \uc218\uce58\ucc98\ub7fc \ubc1b\uc544\ub4e4\uc77c \uc218\ub294 \uc5c6\ub2e4. \uadf8\uac00 \ubc14\ub77c\ubcf8 \uc2dc\uc810\uacfc, \uadf8\uac00 \ub2e4\uc2dc \uc778\uc6a9\ud55c 19\uc138\uae30 \uc790\ub8cc\uc758 \uc2dc\uc810\ub3c4 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ub85c\uc774\uc988\uc758 \ud604\uc7ac \uad6c\uc870\uc640 \uac1c\ubcc4 \ubcf4\ud5d8 \uacc4\uc57d\uc758 \uc870\uac74\uc744 \uc774 \uae00\uc5d0\uc11c \uc124\uba85\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubc14\ub2e4\uc758 \uc815\ubcf4\ub97c \uacf5\uc720\ud558\ub358 \uc0ac\ub78c\ub4e4\uc774 \uac70\ub798\ub97c \uc704\ud55c \uc804\ubb38\uc801\uc778 \uad00\uacc4\ub97c \ub9cc\ub4e4\uc5b4 \uac04 \uc5ed\uc0ac\ub97c \uc0b4\ud3b4\ubcf8\ub2e4. \ucee4\ud53c\ud558\uc6b0\uc2a4\uac00 \uae08\uc735\uc758 \uc774\ub984\uc73c\ub85c \ub0a8\uc740 \uc774\uc720\ub97c \uc774\ud574\ud558\ub294 \ub370 \ucd08\uc810\uc744 \ub9de\ucd94\uba74 \ub41c\ub2e4. \ub85c\uc774\uc988\uc758 \uc774\ub984\uc744 \ub4e3\uace0 \uac70\ub300\ud55c \uac74\ubb3c\ub9cc \ub5a0\uc62c\ub838\ub2e4\uba74 \uc791\uc740 \uac00\uac8c\uc640 \uc190\uc73c\ub85c \uc4f4 \uc120\ubc15 \ubaa9\ub85d\ub3c4 \ud568\uaed8 \ub193\uc544 \ubcf4\uc790. \uc704\ud5d8\uc744 \ub098\ub204\ub294 \uc57d\uc18d \ub4a4\uc5d0\ub294 \ubb34\uc5c7\uc774 \uc77c\uc5b4\ub0ac\ub294\uc9c0 \uc54c\uae30 \uc704\ud55c \uae30\ub85d\uc774 \uc788\uc5c8\ub2e4. \uae08\uc735\uc740 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc22b\uc790\ubfd0 \uc544\ub2c8\ub77c \uc0ac\ub78c\uc774 \ubaa8\uc5ec \uc18c\uc2dd\uc744 \ud655\uc778\ud558\ub294 \uc7a5\uc18c\uc5d0\uc11c\ub3c4 \uc790\ub77c\ub0ac\ub2e4. \uc774 \uc774\uc57c\uae30\ub294 \ubcf4\ud5d8\uc774 \ucee4\ud53c \ud55c \uc794\uc5d0\uc11c \uac11\uc790\uae30 \ubc1c\uba85\ub418\uc5c8\ub2e4\ub294 \uc804\uc124\uc774 \uc544\ub2c8\ub2e4. \ubc14\ub2e4\uc5d0 \ub300\ud55c \uc624\ub798\ub41c \uac70\ub798\uac00 \ud2b9\uc815\ud55c \ub9cc\ub0a8\uc758 \uc7a5\uc18c\ub97c \ud1b5\ud574 \ub354 \uc870\uc9c1\uc801\uc73c\ub85c \uc5f0\uacb0\ub41c \uacfc\uc815\uc774\ub2e4. \ub7f0\ub358\uc758 \ucee4\ud53c\ud558\uc6b0\uc2a4\ub294 \ub204\uac00 \uc5b4\ub5a4 \uc18c\uc2dd\uc744 \ud568\uaed8 \uc77d\ub294\uc9c0\uac00 \uc0c8\ub85c\uc6b4 \uc2dc\uc7a5\uc758 \uae30\ubc18\uc774 \ub420 \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "loan-payment-principal-interest", "title": "\ub9e4\ub2ec \uac1a\ub294\ub370 \uc65c \uc6d0\uae08\uc740 \uc870\uae08 \uc904\uc5b4\ub4e4\uae4c", "summary": "\uac19\uc740 \uc6d4 \ub0a9\uc785\uc561 \uc18d\uc5d0\uc11c \uc774\uc790\uc640 \uc6d0\uae08\uc758 \ube44\uc911\uc774 \ub2ec\ub77c\uc9c0\ub294 \uc774\uc720\ub97c \uc791\uc740 \uac00\uc0c1 \ub300\ucd9c\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "finance", "category_title": "\ub3c8\uacfc \uae08\uc735", "subcategory": "\uc740\ud589\uacfc \uc2e0\uc6a9", "categories": ["finance"], "url": "stories/loan-payment-principal-interest/index.html", "image": "../media/loan-payment-principal-interest.png", "alt": "\uc9d1 \uc548 \uc2dd\ud0c1\uc5d0\uc11c \uacc4\uc0b0\uae30\uc640 \uac00\uacc4\ubd80\ub97c \ubcf4\uba70 \ub0a9\uc785 \ub0b4\uc5ed\uc744 \uc0b4\ud3b4\ubcf4\ub294 \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ub9e4\ub2ec \uac1a\ub294\ub370 \uc65c \uc6d0\uae08\uc740 \uc870\uae08 \uc904\uc5b4\ub4e4\uae4c \uc0c1\ud658\uc561 \uc548\uc5d0\uc11c \uc790\ub9ac\ub97c \ubc14\uafb8\ub294 \uc6d0\uae08\uacfc \uc774\uc790 \uac19\uc740 \uc6d4 \ub0a9\uc785\uc561 \uc18d\uc5d0\uc11c \uc774\uc790\uc640 \uc6d0\uae08\uc758 \ube44\uc911\uc774 \ub2ec\ub77c\uc9c0\ub294 \uc774\uc720\ub97c \uc791\uc740 \uac00\uc0c1 \ub300\ucd9c\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc740\ud589\uacfc \uc2e0\uc6a9 \ub3c8\uacfc \uae08\uc735 \uba87 \ub2ec\uc9f8 \ube60\uc9d0\uc5c6\uc774 \ub300\ucd9c\uc744 \uac1a\uc558\ub2e4. \uadf8\ub7f0\ub370 \ub0a8\uc740 \uc6d0\uae08\uc744 \ubcf4\ub2c8 \ub0b8 \ub3c8\ub9cc\ud07c \ud06c\uac8c \uc904\uc9c0 \uc54a\uc558\ub2e4. \ub3c8\uc774 \uc5b4\ub514\ub85c \uac04 \uac83\uc77c\uae4c. \ub9e4\ub2ec \ubcf4\ub0b4\ub294 \uae08\uc561\uc774 \ubaa8\ub450 \ube4c\ub9b0 \uc6d0\uae08\uc744 \uc904\uc774\ub294 \ub370 \uc4f0\uc774\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc77c\uc815 \ubd80\ubd84\uc740 \ub3c8\uc744 \ube4c\ub9b0 \ub370 \ub300\ud55c \uc774\uc790\ub85c \ub098\uac00\uae30 \ub54c\ubb38\uc774\ub2e4. \ub300\ucd9c \uc0c1\ud658\ud45c\ub294 \uc22b\uc790\uac00 \ub9ce\uc544\uc11c \ub0af\uc124\uc9c0\ub9cc, \ud55c \ub2ec\uc758 \ub0a9\uc785\uc561\uc744 \uc6d0\uae08\uacfc \uc774\uc790\ub85c \ub098\ub204\uc5b4 \ubcf4\uba74 \uc77d\ub294 \uae38\uc774 \uc0dd\uae34\ub2e4. \uc5ec\uae30\uc11c\ub294 \uace0\uc815\ub41c \uc774\uc790\uc728\uacfc \uc815\ud574\uc9c4 \uae30\uac04\uc744 \uac00\uc9c4 \ub2e8\uc21c\ud55c \uac00\uc0c1 \ub300\ucd9c\uc744 \uc0ac\uc6a9\ud55c\ub2e4. \uc2e4\uc81c \uc0c1\ud488\uc758 \uae08\ub9ac\ub098 \uacc4\uc57d \uc870\uac74\uc744 \ucd94\ucc9c\ud558\ub294 \uae00\uc740 \uc544\ub2c8\ub2e4. \uc6d0\uae08\uc740 \ube4c\ub9b0 \ub3c8\uc758 \uae30\ubcf8 \uae08\uc561\uc774\uace0, \uc774\uc790\ub294 \uadf8 \ub3c8\uc744 \ube4c\ub9ac\ub294 \ub370 \ub4dc\ub294 \ube44\uc6a9\uc774\ub2e4. \ub0a9\uc785\uc561 \uc548\uc5d0\ub294 \ub450 \uac00\uc9c0\uac00 \ud568\uaed8 \ub4e4\uc5b4\uac08 \uc218 \uc788\ub2e4. \uc2dd\ub2f9\uc5d0\uc11c \ub0b8 \ub3c8 \uc804\uccb4\uac00 \uc7ac\ub8cc\ube44\ub9cc\uc740 \uc544\ub2cc \uac83\ucc98\ub7fc, \uac1a\uc558\ub2e4\ub294 \ub9d0 \ud558\ub098 \uc548\uc5d0 \ub2e4\ub978 \uc131\uaca9\uc758 \ub3c8\uc774 \uc11e\uc5ec \uc788\ub2e4. \ubbf8\uad6d \uc18c\ube44\uc790\uae08\uc735\ubcf4\ud638\uad6d\uc758 \uc0c1\ud658 \uacc4\uc0b0 \uc548\ub0b4\ub3c4 \uc815\uae30 \ub0a9\uc785\uae08\uc758 \uc77c\ubd80\ub294 \uc6d0\uae08\uc5d0, \uc77c\ubd80\ub294 \uc774\uc790\uc5d0 \uc801\uc6a9\ub41c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc2e4\uc81c \uacc4\uc57d\uc5d0\ub294 \uc218\uc218\ub8cc\ub098 \ub2e4\ub978 \ud56d\ubaa9\uc774 \ubd99\uc744 \uc218 \uc788\uc73c\ubbc0\ub85c \uc5ec\uae30\uc11c\ub294 \uadf8\ub7f0 \ube44\uc6a9\uc744 \uc81c\uc678\ud55c\ub2e4. \uba3c\uc800 \uac00\uc7a5 \ub2e8\uc21c\ud55c \uad6c\uc870\ub97c \uc774\ud574\ud558\ub824\ub294 \uac83\uc774\ub2e4. 120\ub9cc \uc6d0\uc744 \ube4c\ub838\uace0 \ub9e4\ub2ec \ub0a8\uc544 \uc788\ub294 \uc6d0\uae08\uc758 1%\ub97c \uc774\uc790\ub85c \uacc4\uc0b0\ud55c\ub2e4\uace0 \uac00\uc815\ud558\uc790. \uc5ec\uae30\uc758 1%\ub294 \uc124\uba85\uc6a9 \uc6d4 \uc774\uc790\uc728\uc774\ub2e4. \uccab \ub2ec \uc774\uc790\ub294 1\ub9cc 2\ucc9c \uc6d0\uc774\ub2e4. \ub3c8\uc744 11\ub9cc 2\ucc9c \uc6d0 \ubcf4\ub0c8\ub2e4\uba74 \uadf8\uc911 1\ub9cc 2\ucc9c \uc6d0\uc740 \uc774\uc790, \ub098\uba38\uc9c0 10\ub9cc \uc6d0\uc740 \uc6d0\uae08\uc744 \uc904\uc774\ub294 \ub370 \uc4f0\uc778\ub2e4. \uc774 \ud55c \ubc88\uc758 \ub0a9\uc785 \ub4a4 \ub0a8\uc740 \uc6d0\uae08\uc740 110\ub9cc \uc6d0\uc774\ub2e4. 120\ub9cc \uc6d0\uc5d0\uc11c \ubcf4\ub0b8 \ub3c8 \uc804\uccb4\uc778 11\ub9cc 2\ucc9c \uc6d0\uc744 \ube7c\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc6d0\uae08\uc744 \uc904\uc778 \ubd80\ubd84\ub9cc \ube7c\uc57c \ud55c\ub2e4. \uc0c1\ud658\ud45c\ub97c \uc77d\uc744 \ub54c \uba3c\uc800 \ub0a9\uc785\uc561\uacfc \uc6d0\uae08 \uc0c1\ud658\uc561\uc744 \ub2e4\ub978 \uce78\uc73c\ub85c \ubcf4\ub294 \uc774\uc720\ub2e4. \ub9e4\ub2ec \uc6d0\uae08\uc744 10\ub9cc \uc6d0\uc529 \uc904\uc778\ub2e4\uace0 \uc815\ud558\uba74 \ub458\uc9f8 \ub2ec\uc740 110\ub9cc \uc6d0\uc5d0 \ub300\ud55c \uc774\uc790 1\ub9cc 1\ucc9c \uc6d0\uc744 \ub354\ud574 11\ub9cc 1\ucc9c \uc6d0\uc744 \ub0b8\ub2e4. \uc14b\uc9f8 \ub2ec\uc740 \uc6d0\uae08 \uc794\uc561\uc774 \ub2e4\uc2dc \uc904\uc5b4 \uc774\uc790\ub3c4 \ub354 \uc791\uc544\uc9c4\ub2e4. \uc6d0\uae08 \uc0c1\ud658\uc561\uc740 \uac19\uc9c0\ub9cc \uc804\uccb4 \uc6d4 \ub0a9\uc785\uc561\uc740 \uc810\uc810 \uac10\uc18c\ud55c\ub2e4. \uc774\ub97c \uc6d0\uae08\uade0\ub4f1 \uc0c1\ud658\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \uc6d0\uae08\uc744 \uc77c\uc815\ud558\uac8c \ub098\ub204\uace0 \uadf8\ub54c\uadf8\ub54c \ub0a8\uc740 \uae08\uc561\uc758 \uc774\uc790\ub97c \ub354\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4. \uac19\uc740 \uc6d0\ub9ac\ub97c \ub05d\uae4c\uc9c0 \uc801\uc6a9\ud558\uba74 \ub9c8\uc9c0\ub9c9\uc5d0\ub294 10\ub9cc \uc6d0\uc758 \uc6d0\uae08\uc5d0 \ub300\ud55c \uc774\uc790 1\ucc9c \uc6d0\uc774 \ubd99\ub294\ub2e4. \uc55e\uc5d0\uc11c \ub354 \ub9ce\uc774 \ub0b4\uace0 \ub4a4\ub85c \uac08\uc218\ub85d \ubd80\ub2f4\uc774 \uc904\uc5b4\ub4dc\ub294 \ubaa8\uc591\uc774 \ub41c\ub2e4. \ub2e4\ub978 \ubc29\ubc95\uc740 \ub9e4\ub2ec \ub0b4\ub294 \uc6d0\uae08\uacfc \uc774\uc790\uc758 \ud569\uacc4\ub97c \uc77c\uc815\ud558\uac8c \ub9de\ucd94\ub294 \uac83\uc774\ub2e4. \uac19\uc740 \uac00\uc0c1 \uc870\uac74\uc73c\ub85c 12\uac1c\uc6d4\uc5d0 \ub098\ub204\uba74 \uc6d4 \ub0a9\uc785\uc561\uc740 \uc57d 10\ub9cc 6,619\uc6d0\uc774 \ub41c\ub2e4. \uc18c\uc218\uc810\uacfc \ub9c8\uc9c0\ub9c9 \ub2ec\uc758 \uc870\uc815\uc740 \ub2e8\uc21c\ud654\ud55c \uacc4\uc0b0\uc774\ub2e4. \uccab \ub2ec\uc5d0\ub294 \uadf8\uc911 \uc774\uc790 1\ub9cc 2\ucc9c \uc6d0\uc744 \ube7c\uace0 \uc57d 9\ub9cc 4,619\uc6d0\uc774 \uc6d0\uae08\uc744 \uc904\uc778\ub2e4. \ub2e4\uc74c \ub2ec\uc5d0\ub294 \ub0a8\uc740 \uc6d0\uae08\uc774 \uc791\uc544\uc838 \uc774\uc790\ub3c4 \uc904\uc5b4\ub4e0\ub2e4. \ucd1d\uc561\uc740 \ube44\uc2b7\ud558\uac8c \uc720\uc9c0\ud558\ubbc0\ub85c \uc774\ubc88\uc5d0\ub294 \uc6d0\uae08\uc744 \uac1a\ub294 \ubd80\ubd84\uc774 \uc870\uae08 \ub354 \ucee4\uc9c4\ub2e4. \uac19\uc740 \uae08\uc561\uc744 \ub0b4\uba74\uc11c \uc548\uc758 \uad6c\uc131\uc740 \uacc4\uc18d \ubc14\ub00c\ub294 \uac83\uc774\ub2e4. \uc6d0\ub9ac\uae08\uc740 \uc6d0\uae08\uacfc \uc774\uc790\ub97c \ud569\uce5c \ub9d0\uc774\ub2e4. \uc6d0\ub9ac\uae08\uade0\ub4f1 \uc0c1\ud658\uc740 \uadf8 \ud569\uacc4\ub97c \uc77c\uc815\ud558\uac8c \ub9de\ucd94\ub294 \ubc29\uc2dd\uc774\uc9c0 \ub9e4\ub2ec \uc6d0\uae08\uc744 \uac19\uc740 \uae08\uc561\uc529 \uc904\uc778\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \ub450 \ubc29\uc2dd\uc758 \uc774\ub984\uc740 \ube44\uc2b7\ud558\uc9c0\ub9cc \uade0\ub4f1\ud558\uac8c \ub9cc\ub4dc\ub294 \ub300\uc0c1\uc774 \ub2e4\ub974\ub2e4. \ucd08\uae30\uc5d0\ub294 \ub0a8\uc544 \uc788\ub294 \uc6d0\uae08\uc774 \ud06c\uae30 \ub54c\ubb38\uc5d0 \uc774\uc790\uc758 \ube44\uc911\ub3c4 \uc0c1\ub300\uc801\uc73c\ub85c \ud06c\ub2e4. \ub4a4\ub85c \uac08\uc218\ub85d \uc6d0\uae08 \uc0c1\ud658\uc758 \ube44\uc911\uc774 \ucee4\uc9c4\ub2e4. \ub530\ub77c\uc11c \ucd08\ubc18 \uba87 \ub2ec\uc758 \ucd1d \ub0a9\uc785\uc561\ub9cc \ub354\ud574 \ucc98\uc74c \ube4c\ub9b0 \ub3c8\uc5d0\uc11c \ube7c\uba74 \uc2e4\uc81c \uc794\uc561\uacfc \ub9de\uc9c0 \uc54a\ub294\ub2e4. \uc774\uc790\uac00 \ucc28\uc9c0\ud588\ub358 \ubd80\ubd84\uc744 \ub530\ub85c \ubcf4\uc544\uc57c \ud55c\ub2e4. \uac19\uc740 120\ub9cc \uc6d0\uacfc \uc6d4 1%\ub77c\ub294 \uc870\uac74\uc5d0\uc11c \uc6d0\ub9ac\uae08\uade0\ub4f1 \uc0c1\ud658 \uae30\uac04\uc744 24\uac1c\uc6d4\ub85c \ub298\ub9ac\uba74 \uc6d4 \ub0a9\uc785\uc561\uc740 \uc57d 5\ub9cc 6,488\uc6d0\uc774 \ub41c\ub2e4. \ub9e4\ub2ec \ub0b4\ub294 \ub3c8\uc740 \uc904\uc9c0\ub9cc \ub354 \uc624\ub798 \ub0b8\ub2e4. \uc774 \uac00\uc815\uc5d0\uc11c \ucd1d\uc774\uc790\ub294 12\uac1c\uc6d4 \ub54c \uc57d 7\ub9cc 9,423\uc6d0, 24\uac1c\uc6d4 \ub54c \uc57d 15\ub9cc 5,716\uc6d0\uc774\ub2e4. \uc6d4 \uae08\uc561\uc774 \uc791\ub2e4\ub294 \uac83\uacfc \uc804\uccb4 \ube44\uc6a9\uc774 \uc801\ub2e4\ub294 \uac83\uc740 \uac19\uc740 \ub9d0\uc774 \uc544\ub2c8\ub2e4. \ube4c\ub9b0 \ub3c8\uc774 \ub0a8\uc544 \uc788\ub294 \uc2dc\uac04\uc774 \uae38\uc5b4\uc9c0\uba74 \uc774\uc790\ub97c \ub0b4\ub294 \uae30\uac04\ub3c4 \uae38\uc5b4\uc9c4\ub2e4. \ubb3c\ub860 \uc2e4\uc81c \uc120\ud0dd\uc5d0\uc11c\ub294 \uac01\uc790\uc758 \ud604\uae08 \ud750\ub984\uacfc \uacc4\uc57d \uc870\uac74\ub3c4 \uc911\uc694\ud558\ub2e4. \uc22b\uc790 \ud558\ub098\ub9cc \ubcf4\uace0 \uc5b4\ub290 \uae30\uac04\uc774 \ub204\uad6c\uc5d0\uac8c\ub098 \uc815\ub2f5\uc774\ub77c\uace0 \ud560 \uc218\ub294 \uc5c6\ub2e4. \uccab\uc9f8, \uc774\ubc88\uc5d0 \ub0b8 \ub3c8 \uc911 \uc774\uc790\ub294 \uc5bc\ub9c8\uc778\uac00. \ub458\uc9f8, \uc2e4\uc81c\ub85c \uc6d0\uae08\uc740 \uc5bc\ub9c8 \uc904\uc5c8\ub294\uac00. \uc14b\uc9f8, \ub0a9\uc785 \ub4a4 \ub0a8\uc740 \uc6d0\uae08\uc740 \uc5bc\ub9c8\uc778\uac00. \uc774 \uc138 \uac00\uc9c0\ub97c \uc21c\uc11c\ub300\ub85c \ubcf4\uba74 \uae38\uac8c \uc774\uc5b4\uc9c0\ub294 \ud45c\ub3c4 \uac19\uc740 \uad00\uacc4\uc758 \ubc18\ubcf5\uc73c\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc2e4\uc81c \uacc4\uc57d\uc758 \ubcc0\ub3d9 \uae08\ub9ac\ub098 \uc720\uc608 \uae30\uac04, \uc77c\uc218 \uacc4\uc0b0\uacfc \uc218\uc218\ub8cc, \uc911\ub3c4 \uc0c1\ud658 \uc870\uac74\uc740 \uc774 \ub2e8\uc21c\ud55c \uc0ac\ub840\uc640 \ub2e4\ub97c \uc218 \uc788\ub2e4. \ubbf8\uad6d \uae30\uad00\uc758 \uacc4\uc0b0 \uc124\uba85\uc744 \ud55c\uad6d\uc758 \ud2b9\uc815 \uc0c1\ud488 \uc57d\uad00\uc73c\ub85c \uc62e\uaca8 \uc77d\uc5b4\uc11c\ub3c4 \uc548 \ub41c\ub2e4. \uc774 \uae00\uc774 \uc124\uba85\ud558\ub294 \uac83\uc740 \uae30\ubcf8 \uad6c\uc870\uc774\uba70 \uc2e4\uc81c \uae08\uc561\uc740 \ud574\ub2f9 \uacc4\uc57d\uacfc \uc0c1\ud658\ud45c\uac00 \uae30\uc900\uc774\ub2e4. \uc794\uc561\uc744 \ubcf4\uace0 \uc2e4\ub9dd\ud588\ub2e4\uba74 \uc804\uccb4 \ub0a9\uc785\uae08\uacfc \uc6d0\uae08 \uc0c1\ud658\uc561\uc744 \uac19\uc740 \uac83\uc73c\ub85c \uc0dd\uac01\ud558\uc9c0 \uc54a\uc558\ub294\uc9c0 \uba3c\uc800 \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \ub0b8 \ub3c8\uc774 \ubaa8\ub450 \uc6d0\uae08\uc73c\ub85c \uac00\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc774\uc790\ub77c\ub294 \ube44\uc6a9\uacfc \ub098\ub258\uc5c8\ub2e4\ub294 \uc810\uc744 \uc54c\uba74 \uc22b\uc790\uac00 \uc870\uae08 \ub35c \ubd88\uce5c\uc808\ud574\uc9c4\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac00\uacc4\ubd80 \uadf8\ub9bc\uc740 AI\uac00 \ub9cc\ub4e0 \uc0dd\ud65c \uc7a5\uba74\uc774\uba70 \uc2e4\uc81c \uc0c1\ud658\ud45c\uac00 \uc544\ub2c8\ub2e4. \uc774\ud574\uc758 \ud575\uc2ec\uc740 \uadf8\ub9bc \uc18d \uacc4\uc0b0\uae30\ubcf4\ub2e4 \ud55c \ub2ec\uc758 \ub3c8\uc744 \ub450 \ubd80\ubd84\uc73c\ub85c \ub098\ub204\uc5b4 \ubcf4\ub294 \ub370 \uc788\ub2e4. \uac19\uc740 \uc561\uc218\ub97c \uafb8\uc900\ud788 \ub0b4\ub294 \ub3d9\uc548\uc5d0\ub3c4 \uc6d0\uae08\uacfc \uc774\uc790\ub294 \uc11c\ub85c \ub2e4\ub978 \uc18d\ub3c4\ub85c \uc790\ub9ac\ub97c \ubc14\uafb8\uace0 \uc788\ub2e4."}, {"id": "mansa-musa-gold-and-cairo", "title": "\ub9cc\uc0ac \ubb34\uc0ac \u2014 \uc21c\ub840\uae38\uc758 \uae08\uc740 \uc65c \uce74\uc774\ub85c\uc5d0 \ud754\uc801\uc744 \ub0a8\uacbc\uc744\uae4c", "summary": "\ub9d0\ub9ac \uc655\uc758 \uc21c\ub840\uc640 \uae08\uc5d0 \uad00\ud55c \uae30\ub85d, \uce74\ud0c8\ub8e8\ub0d0 \uc9c0\ub3c4\ucca9\uc758 \uc2e4\uc81c \ub3c4\ud310\uc744 \ud1b5\ud574 \ubd80\uc640 \uad50\uc5ed\uc758 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "finance", "category_title": "\ub3c8\uacfc \uae08\uc735", "subcategory": "\ub3c8\uacfc \ud654\ud3d0", "categories": ["finance"], "url": "stories/mansa-musa-gold-and-cairo/index.html", "image": "../media/mansa-musa-gold-and-cairo.jpg", "alt": "14\uc138\uae30 \uce74\ud0c8\ub8e8\ub0d0 \uc9c0\ub3c4 \uc5ec\ub7ec \uba74\uacfc \uae08\uc744 \ub4e0 \ub9cc\uc0ac \ubb34\uc0ac\uc758 \uc0c1\uc138\ub97c \ud569\uc131\ud55c \uc5ed\uc0ac \uc790\ub8cc", "text": "\ub9cc\uc0ac \ubb34\uc0ac \u2014 \uc21c\ub840\uae38\uc758 \uae08\uc740 \uc65c \uce74\uc774\ub85c\uc5d0 \ud754\uc801\uc744 \ub0a8\uacbc\uc744\uae4c 1324\ub144\uc758 \uc5ec\ud589\uacfc 1375\ub144 \uc9c0\ub3c4\uc5d0 \uadf8\ub824\uc9c4 \uc655 \ub9d0\ub9ac \uc655\uc758 \uc21c\ub840\uc640 \uae08\uc5d0 \uad00\ud55c \uae30\ub85d, \uce74\ud0c8\ub8e8\ub0d0 \uc9c0\ub3c4\ucca9\uc758 \uc2e4\uc81c \ub3c4\ud310\uc744 \ud1b5\ud574 \ubd80\uc640 \uad50\uc5ed\uc758 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ub3c8\uacfc \ud654\ud3d0 \ub3c8\uacfc \uae08\uc735 \uc624\ub798\ub41c \uc9c0\ub3c4\uc5d0 \uc655 \ud55c \uc0ac\ub78c\uc774 \uc549\uc544 \uc788\ub2e4. \uc655\uad00\uc744 \uc4f0\uace0 \uc190\uc5d0\ub294 \ud669\uae08\ube5b \ubb3c\uac74\uc744 \ub4e4\uc5c8\ub2e4. \uc9c0\ub3c4\ub294 \uc0b0\uacfc \uac15\uc758 \uc704\uce58\ub9cc \uc54c\ub824 \uc8fc\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc774\uacf3\uc5d0 \uc5b4\ub5a4 \ubd80\uac00 \uc788\ub2e4\uace0 \uc0dd\uac01\ud588\ub294\uc9c0\ub3c4 \ubcf4\uc5ec \uc900\ub2e4. \uadf8 \uc655\uc740 \uc11c\uc544\ud504\ub9ac\uce74 \ub9d0\ub9ac\uc758 \ub9cc\uc0ac \ubb34\uc0ac\ub2e4. \uadf8\uc758 \uc774\ub984\uc744 \uba3c \uc9c0\uc5ed\uc5d0 \uc54c\ub9b0 \uc911\uc694\ud55c \uacc4\uae30\ub294 1324~1325\ub144\uc758 \uba54\uce74 \uc21c\ub840\uc600\ub2e4. \uce74\uc774\ub85c\ub97c \uac70\uccd0 \uac04 \uc655\uc758 \uc5ec\ud589\uc740 \uae08\uacfc \uc120\ubb3c\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\ub85c \uc624\ub798 \uc804\ud574\uc84c\ub2e4. \ud55c \uc0ac\ub78c\uc758 \uc774\ub3d9\uc774 \uc5b4\ub5bb\uac8c \uc2dc\uc7a5\uc758 \uc774\uc57c\uae30\uc640 \uc9c0\ub3c4\uc758 \uc774\ubbf8\uc9c0\uac00 \ub418\uc5c8\ub294\uc9c0 \ub530\ub77c\uac00 \ubcf4\uc790. \ub9d0\ub9ac\ub294 \ub113\uc740 \uc0ac\ud558\ub77c\ub97c \uc0ac\uc774\uc5d0 \ub450\uace0 \uace0\ub9bd\ub41c \uc655\uad6d\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uae08\uacfc \uc18c\uae08, \uc5ec\ub7ec \ubb3c\ud488\uc744 \uad50\ud658\ud558\ub294 \uae38\uc774 \ubd81\uc544\ud504\ub9ac\uce74\uc640 \uc774\uc5b4\uc84c\ub2e4. \uad50\uc7ac\ub294 \ub9d0\ub9ac\uc758 \ud798\uc744 \uc774\ub7f0 \uad50\uc5ed\ub85c\uc640 \uae08 \uc0dd\uc0b0 \uc9c0\uc5ed, \ud1b5\uce58\uc790\uc758 \uad00\uacc4 \uc18d\uc5d0\uc11c \uc124\uba85\ud55c\ub2e4. \uae08\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8 \uae08\uc774 \uc774\ub3d9\ud558\ub294 \uae38\uc744 \ub2e4\ub8e8\ub294 \ud798\uc774 \ud568\uaed8 \uc911\uc694\ud588\ub2e4. \uc0ac\ub9c9\uc740 \uc624\uac00\uae30\uac00 \ud798\ub4e0 \ud658\uacbd\uc774\uc5c8\uc9c0\ub9cc \uad50\ub958\uac00 \uc5c6\uc5c8\ub358 \ube48 \uacf5\uac04\uc740 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\uacfc \ub099\ud0c0, \ubb3c\uc790\ub97c \ub9c8\ub828\ud558\ub294 \uc9c0\uc2dd\uc774 \uae38\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \ub9cc\uc0ac \ubb34\uc0ac\uc758 \uc21c\ub840\ub3c4 \uc774\ub7f0 \uc624\ub79c \uc5f0\uacb0 \uc704\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc84c\ub2e4. \uac11\uc790\uae30 \ud55c \uc655\uc774 \uc544\ubb34\ub3c4 \ubab0\ub790\ub358 \ub300\ub959 \ubc16\uc73c\ub85c \ub098\ud0c0\ub09c \uc774\uc57c\uae30\ub85c \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub9cc\uc0ac \ubb34\uc0ac\ub294 \ubb34\uc2ac\ub9bc \ud1b5\uce58\uc790\ub85c\uc11c \uba54\uce74 \uc21c\ub840\uc5d0 \ub098\uc130\ub2e4. \uadf8 \uae38\uc5d0 \uce74\uc774\ub85c\ub97c \ubc29\ubb38\ud588\uace0 \uc774\uc9d1\ud2b8\uc758 \ud1b5\uce58\uc790\uc5d0\uac8c \uc911\uc694\ud55c \uc190\ub2d8\uc73c\ub85c \ub300\uc6b0\ubc1b\uc558\ub2e4. \uc2e0\uc559\uc758 \uc758\ubb34\uc640 \uba3c \uc9c0\uc5ed \ud1b5\uce58\uc790\ub4e4\uc758 \ub9cc\ub0a8\uc774 \uac19\uc740 \uc5ec\ud589 \uc548\uc5d0 \ub193\uc600\ub2e4. \uc655\uc774 \ub9ce\uc740 \uc790\uc6d0\uc744 \ub3d9\uc6d0\ud574 \uc774\ub3d9\ud558\uba74 \uc5ec\ud589 \uc790\uccb4\uac00 \ub098\ub77c\uc758 \ud798\uc744 \ub4dc\ub7ec\ub0b4\uae30\ub3c4 \ud55c\ub2e4. \uc218\ud589\uc6d0\uacfc \uc9d0, \uc120\ubb3c\uc740 \ubc29\ubb38\uc790\uc758 \uc9c0\uc704\ub97c \ubcf4\uc774\uac8c \ub9cc\ub4e0\ub2e4. \ub2e4\ub9cc \uc21c\ub840\ub97c \ub2e8\uc21c\ud55c \ubd80\uc758 \uacfc\uc2dc\ub9cc\uc73c\ub85c \uc904\uc774\uba74 \uc885\uad50\uc801 \ubaa9\uc801\uc744 \ub193\uce5c\ub2e4. \uc5ec\ub7ec \ub3d9\uae30\uac00 \ud55c \uae38\uc5d0\uc11c \ud568\uaed8 \uc791\uc6a9\ud560 \uc218 \uc788\uc5c8\ub2e4. \uad50\uc7ac\ub294 \ub9cc\uc0ac \ubb34\uc0ac\uac00 \uce74\uc774\ub85c\uc5d0\uc11c \uae08\uc744 \ub109\ub109\ud558\uac8c \uc4f0\uace0 \uc120\ubb3c\uc744 \uc8fc\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud070 \ud589\ub82c\uacfc \ub9ce\uc740 \uae08\uc5d0 \uad00\ud55c \uc804\uc5b8\ub3c4 \uc804\ud55c\ub2e4. \uc22b\uc790\uac00 \uadf9\uc801\uc73c\ub85c \ud074\uc218\ub85d \uc815\ud655\ud55c \ud604\ub300 \uc778\uad6c \uc870\uc0ac\ucc98\ub7fc \ubc1b\uc544\ub4e4\uc774\uae30\ubcf4\ub2e4\ub294 \ub2f9\uc2dc \uc655\uc758 \ubd80\uac00 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \uae30\uc5b5\ub418\uc5c8\ub294\uc9c0 \uc0b4\ud3b4\ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \uc774\ubc88 \uae00\uc740 \uc218\ud589\uc6d0\uc758 \uc218\uc640 \uae08\uc758 \ubb34\uac8c\ub97c \ud655\uc815\ud558\uac70\ub098 \ud604\uc7ac\uc758 \ub2ec\ub7ec \uac00\uce58\ub85c \ud658\uc0b0\ud558\uc9c0 \uc54a\ub294\ub2e4. \uadf8\ub7f0 \uacc4\uc0b0\uc740 \uac00\uaca9\uacfc \uc790\ub8cc\uc758 \uc870\uac74\uc5d0 \ub530\ub77c \ud06c\uac8c \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uadf8\uc758 \ubc29\ubb38\uc744 \ud3c9\ubc94\ud55c \uc5ec\ud589\uacfc \ub2e4\ub974\uac8c \uc778\uc2dd\ud588\uace0 \uadf8 \uc774\uc57c\uae30\ub97c \uc804\ud588\ub2e4\ub294 \uc810\uc774\ub2e4. \uad50\uc7ac\ub294 \uce74\uc774\ub85c\uc5d0 \ub9ce\uc740 \uae08\uc774 \ub4e4\uc5b4\uc624\uba74\uc11c \uae08\uc758 \uac00\uce58\uac00 \ub0ae\uc544\uc84c\uace0 \uc601\ud5a5\uc774 \ud55c\ub3d9\uc548 \uc774\uc5b4\uc84c\ub2e4\ub294 \uae30\ub85d\uc744 \uc18c\uac1c\ud55c\ub2e4. \uadc0\ud55c \uae08\uc18d\ub3c4 \uc2dc\uc7a5 \uc548\uc5d0\uc11c \ub2e4\ub978 \ubb3c\uac74\uacfc \uad50\ud658\ub418\ub294 \uac12\uc774 \uc788\uc5c8\ub2e4. \uc655\uc5d0\uac8c\ub294 \ud48d\ubd80\ud55c \uc7ac\uc0b0\uc774\uc5c8\uc9c0\ub9cc \ubc1b\ub294 \ub3c4\uc2dc\uc5d0\uc11c\ub294 \uac70\ub798 \uc870\uac74\uc758 \ubcc0\ud654\uac00 \ub420 \uc218 \uc788\uc5c8\ub2e4. \ub2e4\ub9cc \uc774 \uc124\uba85\uc744 \ub2f9\uc2dc \ubaa8\ub4e0 \uc0c1\ud488 \uac00\uaca9\uc744 \uc815\ubc00\ud558\uac8c \uce21\uc815\ud55c \ud1b5\uacc4\ucc98\ub7fc \uc77d\uc744 \uc218\ub294 \uc5c6\ub2e4. \uc804\ud574\uc9c4 \uacbd\uc81c\uc801 \uc601\ud5a5\uacfc \ud604\ub300\uc758 \ubb3c\uac00 \uc870\uc0ac \uc0ac\uc774\uc5d0\ub294 \uc790\ub8cc\uc758 \ucc28\uc774\uac00 \uc788\ub2e4. \uae08\uc744 \ub098\ub204\uc5b4 \uc8fc\uc5c8\ub2e4\ub294 \uc120\ud589\uc774\ub098 \uacfc\uc2dc\uc758 \uc774\uc57c\uae30\ub9cc\uc73c\ub85c \ub05d\ub0b4\uc9c0 \uc54a\uace0, \uadf8 \uae08\uc744 \ubc1b\ub294 \uc2dc\uc7a5\ub3c4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc5c8\ub2e4\ub294 \uc810\uc744 \ubcf4\ub294 \uac83\uc774\ub2e4. \uc5ec\ud589\uc5d0\uc11c \uc0ac\uc6a9\ud55c \uae08\uc740 \uc0ac\ub77c\uc9c4 \ube44\uc6a9\uc73c\ub85c\ub9cc \ub0a8\uc9c0 \uc54a\uc558\ub2e4. \ub9d0\ub9ac\uc758 \ubd80\uc640 \uc655\uc758 \uc774\ub984\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\uac00 \uc774\uc9d1\ud2b8 \ubc16\uc73c\ub85c\ub3c4 \ud37c\uc84c\ub2e4. \uad50\uc7ac\ub294 \uadf8\uc758 \uba85\uc131\uc774 \uc2a4\ud398\uc778\uc5d0\uc11c \uc2dc\ub9ac\uc544\uc5d0 \uc774\ub974\ub294 \uad00\ucc30\uc790\ub4e4\uc758 \uad00\uc2ec\uc744 \ub04c\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc7ac\uc0b0\uc744 \uac00\uc9c4\ub2e4\ub294 \uac83\uacfc \uadf8 \uc7ac\uc0b0\uc774 \uc54c\ub824\uc9c4\ub2e4\ub294 \uac83\uc740 \uc11c\ub85c \ub2e4\ub978 \uc885\ub958\uc758 \ud798\uc774\uc5c8\ub2e4. \uc5ec\uae30\uc5d0\ub294 \uc9c1\uc811 \ubcf4\uace0 \ub4e4\uc740 \uc0ac\ub78c\uacfc \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc804\ud574 \ub4e4\uc740 \uc0ac\ub78c\uc774 \ud568\uaed8 \uc788\uc5c8\uc744 \uac83\uc774\ub2e4. \ubaa8\ub4e0 \uc18c\ubb38\uc744 \uc655\uc774 \uc9c1\uc811 \uc124\uacc4\ud55c \ud64d\ubcf4 \uacc4\ud68d\uc73c\ub85c \ubcf5\uc6d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uadf8\ub7ec\ub098 \ub113\uc740 \uad50\uc5ed\ub9dd\uc740 \uc0c1\ud488\ub9cc \uc62e\uae30\uc9c0 \uc54a\uc558\ub2e4. \ub204\uac00 \ubd80\uc720\ud558\uace0 \uc5b4\ub5a4 \ub098\ub77c\uac00 \uc911\uc694\ud55c\uc9c0\uc5d0 \uad00\ud55c \ud3c9\ud310\ub3c4 \uae38\uc744 \ub530\ub77c \uc774\ub3d9\ud588\ub2e4. \uad50\uc7ac\ub294 1375\ub144\uc758 \u300e\uce74\ud0c8\ub8e8\ub0d0 \uc9c0\ub3c4\ucca9\u300f\uc5d0 \ub9cc\uc0ac \ubb34\uc0ac\uac00 \ub4f1\uc7a5\ud55c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc655\uad00\uacfc \ud640, \uc190\uc5d0 \ub4e0 \uae08\uc740 \uadf8\ub97c \ubd80\uc640 \uad8c\ub825\uc758 \uc778\ubb3c\ub85c \ubcf4\uc774\uac8c \ud55c\ub2e4. \uc21c\ub840 \ub4a4 \uc218\uc2ed \ub144\uc774 \uc9c0\ub098\ub3c4 \ub9d0\ub9ac\uc758 \uba85\uc131\uc774 \uc9c0\uc911\ud574\uc758 \uc9c0\ub9ac\uc801 \uc0c1\uc0c1 \uc548\uc5d0 \ub0a8\uc558\ub358 \uac83\uc774\ub2e4. \uc774 \uadf8\ub9bc\uc740 \ub9cc\uc0ac \ubb34\uc0ac\uac00 \ubaa8\ub378\ub85c \uc549\uc544 \uadf8\ub9b0 \uc2e4\uc81c \ucd08\uc0c1\uc774 \uc544\ub2c8\ub2e4. \uc9c0\ub3c4 \uc81c\uc791\uc790\uac00 \uc804\ud574\uc9c4 \uc9c0\uc2dd\uacfc \uc0c1\uc9d5\uc744 \ud1b5\ud574 \uc655\uc744 \ud45c\ud604\ud55c \uac83\uc774\ub2e4. \uc778\ubb3c\uc758 \uc5bc\uad74\uc774 \uc5bc\ub9c8\ub098 \ub2ee\uc558\ub294\uc9c0\ubcf4\ub2e4 \uc5b4\ub5a4 \ubb3c\uac74\uc744 \ub4e4\uac8c \ud588\uace0 \uc5b4\ub290 \uc9c0\uc5ed\uc5d0 \ubc30\uce58\ud588\ub294\uc9c0 \uc0b4\ud53c\ub294 \ud3b8\uc774 \uc774 \uc790\ub8cc\ub97c \ub354 \uc798 \uc77d\uac8c \ud55c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc2e4\uc81c \uc790\ub8cc\ub294 \uc9c0\ub3c4\ucca9\uc758 \uc5ec\ub7ec \uba74\uacfc \uc655\uc758 \ubaa8\uc2b5\uc744 \ubb36\uc5b4 \ub193\uc740 \uad6c\uc131\uc774\ub2e4. \uc911\uc138 \uc9c0\ub3c4 \uc6d0\ubcf8\uc758 \ud55c \uba74\uc774 \uadf8\ub300\ub85c \uc774 \ubc30\uce58\uc600\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc655\uc744 \uac15\uc870\ud55c \ubd80\ubd84\uacfc \uc9c0\ub9ac\uc801 \ubc30\uacbd\uc744 \ud568\uaed8 \ubcfc \uc218 \uc788\ub3c4\ub85d \uad50\uc7ac\uc5d0\uc11c \uad6c\uc131\ud588\ub2e4. \ud654\ub824\ud55c \uc655\uc758 \uc774\ubbf8\uc9c0\uac00 \ub9d0\ub9ac \uc8fc\ubbfc \ubaa8\ub450\uc758 \uc0dd\ud65c\uc744 \ubcf4\uc5ec \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uad50\uc5ed\uacfc \uc655\uc2e4\uc758 \ubd80 \ub4a4\uc5d0\ub294 \uc0dd\uc0b0\uacfc \uc6b4\uc1a1\uc5d0 \ucc38\uc5ec\ud55c \uc0ac\ub78c\ub4e4, \uac15\uc81c\ub41c \uc2e0\ubd84\uc5d0 \uc788\ub358 \uc0ac\ub78c\ub4e4\ub3c4 \uc788\uc5c8\ub2e4. \uc655\uc744 \ud1b5\ud574 \ub098\ub77c\ub97c \uae30\uc5b5\ud558\ub418 \uadf8\uc758 \uc7ac\uc0b0\ub9cc\uc73c\ub85c \uc0ac\ud68c \uc804\uccb4\ub97c \uc124\uba85\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \ub9cc\uc0ac \ubb34\uc0ac\uc758 \uc5ec\ud589\uc5d0\ub294 \uc2e0\uc559\uacfc \uc678\uad50, \uc9c0\ucd9c\uacfc \ud3c9\ud310\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \uadf8\uac00 \uc0ac\uc6a9\ud55c \uae08\uc740 \uce74\uc774\ub85c\uc758 \uacbd\uc81c\uc5d0 \uad00\ud55c \uc804\uc5b8\uc73c\ub85c \ub0a8\uc558\uace0, \uadf8\uac00 \ub300\ud45c\ud55c \ubd80\ub294 \uc9c0\ub3c4 \uc704\uc758 \uc0c1\uc9d5\uc774 \ub418\uc5c8\ub2e4. \ud55c \ubc88\uc758 \uc5ec\ud589\uc744 \uc11c\ub85c \ub2e4\ub978 \uc790\ub8cc\uac00 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uae30\uc5b5\ud55c \uc148\uc774\ub2e4. \uc624\ub798\ub41c \ub3c8\uc758 \uc5ed\uc0ac\ub97c \ubcf4\uba74 \uc22b\uc790 \ubc16\uc758 \uc138\uacc4\uac00 \uc5f4\ub9b0\ub2e4. \uae08\uc740 \uc5bc\ub9c8\uc600\ub294\uc9c0\ubfd0 \uc544\ub2c8\ub77c \uc5b4\ub514\ub85c \uac14\uace0 \ub204\uac00 \ubcf4\uc558\uc73c\uba70 \uc5b4\ub5bb\uac8c \uc774\uc57c\uae30\ub418\uc5c8\ub294\uc9c0\ub3c4 \uc911\uc694\ud558\ub2e4. \ub9cc\uc0ac \ubb34\uc0ac\uac00 \uc190\uc5d0 \ub4e0 \ud669\uae08\uc740 \ud55c \uc655\uc758 \uc7ac\uc0b0\uc744 \ub118\uc5b4 \uc0ac\ud558\ub77c\uc640 \uc9c0\uc911\ud574\ub97c \uc5f0\uacb0\ud55c \uae38\uc758 \ube5b\ub098\ub294 \ud45c\uc9c0\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4."}, {"id": "overend-gurney-1866-reputation-and-losses", "title": "1866\ub144 \uc624\ubc84\ub80c\ub4dc \uac70\ub2c8 \u2014 \uc624\ub798\ub41c \uba85\uc131\uc774 \uc190\uc2e4\uc744 \ub9c9\uc544 \uc8fc\uc9c0\ub294 \uc54a\uc558\ub2e4", "summary": "1866\ub144 \ud560\uc778\ud68c\uc0ac \uc2e4\ud328\uc5d0\uc11c \uba85\uc131\u00b7\uc2e4\uc81c \uc190\uc2e4\u00b7\uc720\ub3d9\uc131\u00b7\uc704\uae30 \uc9c0\uc6d0\uc758 \uc870\uac74\uc744 \ub098\ub204\uc5b4 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "finance", "category_title": "\ub3c8\uacfc \uae08\uc735", "subcategory": "\uc740\ud589\uacfc \uc2e0\uc6a9", "categories": ["finance"], "url": "stories/overend-gurney-1866-reputation-and-losses/index.html", "image": "../media/overend-gurney-1866-reputation-and-losses.png", "alt": "\ubb38\uc774 \ub2eb\ud78c \uae08\uc735\ud68c\uc0ac \uc55e\uc5d0\uc11c \ubd88\uc548\ud574\ud558\ub294 1860\ub144\ub300 \ub7f0\ub358 \uc0ac\ub78c\ub4e4\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "1866\ub144 \uc624\ubc84\ub80c\ub4dc \uac70\ub2c8 \u2014 \uc624\ub798\ub41c \uba85\uc131\uc774 \uc190\uc2e4\uc744 \ub9c9\uc544 \uc8fc\uc9c0\ub294 \uc54a\uc558\ub2e4 \ubc30\uc800\ud2b8\uac00 \uae30\ub85d\ud55c \uacbd\uc601\uc758 \ubcc0\ud654\uc640 \uae08\uc735\uc2dc\uc7a5\uc758 \uc9c0\uae09 \uc555\ubc15 1866\ub144 \ud560\uc778\ud68c\uc0ac \uc2e4\ud328\uc5d0\uc11c \uba85\uc131\u00b7\uc2e4\uc81c \uc190\uc2e4\u00b7\uc720\ub3d9\uc131\u00b7\uc704\uae30 \uc9c0\uc6d0\uc758 \uc870\uac74\uc744 \ub098\ub204\uc5b4 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc740\ud589\uacfc \uc2e0\uc6a9 \ub3c8\uacfc \uae08\uc735 \ud55c\ub54c \ubbff\uc74c\uc9c1\ud55c \uc774\ub984\uc774\ub358 \uae08\uc735\ud68c\uc0ac\uac00 \ubb34\ub108\uc84c\ub2e4. 1866\ub144 \ub7f0\ub358\uc758 \uc624\ubc84\ub80c\ub4dc \uac70\ub2c8 \ud30c\uc0b0\uc740 \ud55c \ud68c\uc0ac\uc758 \uc190\uc2e4\uc744 \ub118\uc5b4 \uc2dc\uc7a5 \uc804\uccb4\uc758 \ubd88\uc548\uc744 \ud0a4\uc6e0\ub2e4. \ubc30\uc800\ud2b8\uc758 \u300e\ub86c\ubc14\ub4dc \uc2a4\ud2b8\ub9ac\ud2b8\u300f\ub294 \uc774 \uc0ac\ub840\ub97c \ud1b5\ud574 \uba85\uc131\uacfc \uc2e4\uc81c \uc790\uc0b0, \uacbd\uc601\uc758 \ubcc0\ud654\uc640 \uc704\uae30 \ub300\uc751\uc744 \ud568\uaed8 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc720\uba85\ud558\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc548\uc804\ud558\ub2e4\ub294 \ud310\ub2e8 \uc0ac\uc774\uc758 \uac04\uaca9\uc744 \uc0b4\ud3b4\ubcf4\uc790. \uc0c1\uac70\ub798\uc5d0\uc11c\ub294 \ubbf8\ub798\uc5d0 \ub3c8\uc744 \ubc1b\uc744 \uad8c\ub9ac\uac00 \ud604\uc7ac\uc758 \uc790\uae08\uacfc \uc5f0\uacb0\ub420 \uc218 \uc788\ub2e4. \uc5b4\uc74c\uc744 \ub9cc\uae30 \uc804\uc5d0 \ud560\uc778\ud574 \ud604\uae08\uc744 \ub9c8\ub828\ud558\ub294 \uac70\ub798\uac00 \uadf8 \ud55c \uc608\ub2e4. \ud560\uc778\ud68c\uc0ac\ub294 \uc774\ub7f0 \uac70\ub798\ub97c \ub2e4\ub8e8\uba70 \ub3c8\uc744 \ub9e1\uae34 \uc0ac\ub78c\uacfc \uc790\uae08\uc744 \ud544\uc694\ub85c \ud558\ub294 \uc0ac\ub78c \uc0ac\uc774\uc5d0 \uc704\uce58\ud588\ub2e4. \uc774 \uc0ac\uc5c5\uc740 \ub2e8\uc21c\ud788 \uae08\uace0\uc5d0 \ub3c8\uc744 \ubcf4\uad00\ud558\ub294 \uc77c\uacfc \ub2ec\ub790\ub2e4. \uc5b4\ub5a4 \uc57d\uc18d\uc774 \ub9cc\uae30\uc5d0 \uc9c0\uae09\ub420\uc9c0 \ud310\ub2e8\ud558\uace0, \uc790\uae30\uc5d0\uac8c \ub3c8\uc744 \ub9e1\uae34 \uc0ac\ub78c\uc774 \uc5b8\uc81c \ub3cc\ub824 \ub2ec\ub77c\uace0 \ud560\uc9c0\ub3c4 \uace0\ub824\ud574\uc57c \ud588\ub2e4. \uc790\uc0b0\uc758 \uc9c8\uacfc \uc790\uae08\uc758 \uae30\ud55c\uc744 \ud568\uaed8 \ub2e4\ub8e8\ub294 \ub2a5\ub825\uc774 \ud544\uc694\ud588\ub2e4. \ubc30\uc800\ud2b8\ub294 \ucd08\uae30 \uacbd\uc601\uc790\ub4e4\uc758 \ub2a5\ub825\uacfc \ud6c4\ub300\uc758 \uc798\ubabb\ub41c \ud310\ub2e8\uc744 \uac15\ud558\uac8c \ub300\ube44\ud55c\ub2e4. \uadf8 \ube44\ud310\uc801\uc778 \ud45c\ud604\uc744 \ubaa8\ub450 \uac1d\uad00\uc801\uc778 \uc810\uc218\ucc98\ub7fc \ubc1b\uc544\ub4e4\uc77c \uc218\ub294 \uc5c6\uc9c0\ub9cc, \uc0ac\uc5c5\uc758 \uc774\ub984\uacfc \uc2e4\uc81c \uc6b4\uc601\uc744 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4\ub294 \ubb38\uc81c\ub294 \ubd84\uba85\ud558\ub2e4. \uac19\uc740 \uac04\ud310 \uc544\ub798\uc5d0\uc11c\ub3c4 \uacb0\uc815\ud558\ub294 \uc0ac\ub78c\uc740 \ubc14\ub010\ub2e4. \uc624\ub798 \uc313\uc778 \ud3c9\ud310\uc740 \uc0c8\ub85c\uc6b4 \uacbd\uc601\uc758 \uc131\uacfc\uac00 \ud655\uc778\ub418\uae30 \uc804\uc5d0\ub3c4 \uacc4\uc18d \uc791\ub3d9\ud560 \uc218 \uc788\ub2e4. \uace0\uac1d\uc774 \uae30\uc5b5\ud558\ub294 \ud68c\uc0ac\uc640 \uadf8 \uc21c\uac04 \ub3c8\uc744 \uc6b4\uc6a9\ud558\ub294 \ud68c\uc0ac\uac00 \ub2ec\ub77c\uc9c0\ub294 \uac83\uc774\ub2e4. \uae30\uc5c5\uc758 \uc5ed\uc0ac\uac00 \uae38\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ud604\uc7ac\uc758 \ud310\ub2e8 \ub2a5\ub825\uc774 \ubcf4\uc7a5\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub2f9\uc7a5 \ud604\uae08\uc774 \ubd80\uc871\ud55c \uc0c1\ud0dc\uc640 \uc790\uc0b0\uc758 \uac00\uce58\uac00 \ud06c\uac8c \ud6fc\uc190\ub41c \uc0c1\ud0dc\ub294 \uac19\uc9c0 \uc54a\ub2e4. \uc88b\uc740 \uc790\uc0b0\uc774 \uc788\uc9c0\ub9cc \ud604\uae08\ud654\uc5d0 \uc2dc\uac04\uc774 \ud544\uc694\ud55c \uacbd\uc6b0\uc640, \uae30\ub2e4\ub824\ub3c4 \uc190\uc2e4\uc774 \uc0ac\ub77c\uc9c0\uc9c0 \uc54a\ub294 \uacbd\uc6b0\ub294 \ub2e4\ub978 \ubb38\uc81c\ub2e4. \uc704\uae30 \ub300\uc751\uc5d0\uc11c \uc774 \uad6c\ubd84\uc774 \uc911\uc694\ud558\ub2e4. \uadf8\ub7ec\ub098 \uc2dc\uc7a5\uc774 \ubd88\uc548\ud574\uc9c0\uba74 \uc678\ubd80\uc778\uc740 \ub450 \uc0c1\ud0dc\ub97c \uc815\ud655\ud788 \uad6c\ubcc4\ud558\uae30 \uc5b4\ub835\ub2e4. \ud55c \ud68c\uc0ac\uc5d0 \uc0dd\uae34 \uc758\uc2ec\uc774 \ub2e4\ub978 \ud68c\uc0ac\ub85c \uc62e\uaca8 \uac08 \uc218 \uc788\ub2e4. \uc2e4\uc81c \uc190\uc2e4\uc758 \ubb38\uc81c\uc640 \uc815\ubcf4\ub97c \uc54c\uc9c0 \ubabb\ud574 \uc0dd\uae30\ub294 \ubd88\uc548\uc774 \uc11c\ub85c \uc601\ud5a5\uc744 \uc8fc\uba74\uc11c \uc0c1\ud669\uc744 \ud0a4\uc6b4\ub2e4. \uc624\ubc84\ub80c\ub4dc \uac70\ub2c8\ub294 \uc0ac\uc801 \ub3d9\uc5c5 \ud615\ud0dc\uc5d0\uc11c \uc8fc\uc2dd\ud68c\uc0ac\ub85c \ubc14\ub00c\uc5c8\ub2e4. \ubc30\uc800\ud2b8\ub294 \uc774 \uc804\ud658\uacfc \uacfc\uac70 \uc190\uc2e4\uc744 \ub458\ub7ec\uc2fc \ubcf4\uc99d\uc744 \uc124\uba85\ud55c\ub2e4. \ud615\uc2dd\uc758 \ubcc0\ud654\uac00 \uc774\uc804\uc758 \ubb38\uc81c\ub97c \uc800\uc808\ub85c \uc5c6\uc560 \uc8fc\uc9c0\ub294 \uc54a\uc558\ub2e4. \ub204\uac00 \uc190\uc2e4\uc744 \ubd80\ub2f4\ud560\uc9c0\uac00 \uc5ec\uc804\ud788 \uc911\uc694\ud588\ub2e4. \uc61b \uc18c\uc720\uc790\ub4e4\uc758 \ubd80\ub2f4\uc774 \ub4dc\ub7ec\ub098\uace0 \uc7ac\uc0b0 \ucc98\ubd84\uc774 \uc54c\ub824\uc9c0\uba74\uc11c \ud68c\uc0ac\uc5d0 \ub300\ud55c \uc2e0\ub8b0\ub3c4 \ud754\ub4e4\ub838\ub2e4. \ubc30\uc800\ud2b8\ub294 \uacf5\uac1c\ub418\ub294 \uc815\ubcf4\uac00 \ud3c9\ud310\uc744 \ubc14\uafbc \uacfc\uc815\uc744 \uac15\uc870\ud55c\ub2e4. \ub2e4\ub9cc \uc228\uacbc\ub2e4\uba74 \uad1c\ucc2e\uc558\uc744 \uac83\uc774\ub77c\ub294 \uc2dd\uc758 \uadf8\uc758 \ucd94\ub860\uc744 \uc88b\uc740 \uacbd\uc601\uc758 \uc6d0\uce59\uc73c\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc11c\ub294 \uc548 \ub41c\ub2e4. \uac10\ucdb0\uc9c4 \uc190\uc2e4\uc774 \uac74\uc804\ud568\uc73c\ub85c \ubc14\ub00c\ub294 \uac83\uc740 \uc544\ub2c8\uae30 \ub54c\ubb38\uc774\ub2e4. 1866\ub144 \ud30c\uc0b0 \uc18c\uc2dd\uc740 \uae08\uc735\uc2dc\uc7a5\uc5d0 \uae09\uaca9\ud55c \uc555\ubc15\uc744 \uc8fc\uc5c8\ub2e4. \ud3c9\uc18c\ub77c\uba74 \uc774\uc5b4\uc84c\uc744 \ub300\ucd9c\uc774\ub098 \uc608\uce58\uac00 \uba48\ucd94\uace0, \uc790\uae08\uc744 \uac00\uc9c4 \uc0ac\ub78c\uc740 \uc548\uc804\ud55c \uc790\uc0b0\uc744 \ud655\ubcf4\ud558\ub824 \ud588\ub2e4. \ub2e4\ub978 \ud68c\uc0ac\uac00 \uc544\uc9c1 \uac19\uc740 \uc190\uc2e4\uc744 \uc785\uc9c0 \uc54a\uc558\uc5b4\ub3c4 \ub3c8\uc744 \ub9c8\ub828\ud558\uae30 \uc5b4\ub824\uc6cc\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \uc774 \uacfc\uc815\uc740 \uacf5\ud669\uc744 \ub098\uc05c \ud68c\uc0ac \ud558\ub098\ub97c \ucc3e\uc544\ub0b4\ub294 \uc0ac\uac74\ubcf4\ub2e4 \ub113\uac8c \ub9cc\ub4e0\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\ub3c4 \ud604\uae08\uc744 \uc6d0\ud560 \uac83\uc774\ub77c\ub294 \uc608\uc0c1\uc774 \uac01\uc790\uc758 \ud589\ub3d9\uc744 \ubc14\uafbc\ub2e4. \uae08\uc735\uae30\uad00\uc758 \uc5f0\uacb0\uc740 \ud3c9\uc18c \uc790\uae08\uc744 \uc6c0\uc9c1\uc774\ub294 \uae38\uc774\uba74\uc11c \ubd88\uc548\uc774 \uc804\ub2ec\ub418\ub294 \uae38\uc774\uae30\ub3c4 \ud588\ub2e4. \uc2dc\uc7a5\uc758 \ubd88\uc548\uc740 \uc0ac\ub78c\ub4e4\uc774 \uac19\uc740 \uac83\uc744 \ub3d9\uc2dc\uc5d0 \uc694\uad6c\ud560 \ub54c \ucee4\uc9c8 \uc218 \uc788\ub2e4. \ud3c9\uc18c\uc5d0\ub294 \ub3cc\uc544\uc624\uc9c0 \uc54a\uc744 \ub3c8\uc73c\ub85c \uc5ec\uacbc\ub358 \uc608\uce58\uac00 \uac11\uc790\uae30 \uc9c0\uae09\ud574\uc57c \ud560 \uc758\ubb34\uac00 \ub41c\ub2e4. \ub2e4\ub978 \uae30\uad00\uc758 \ud589\ub3d9\uc744 \uc9c0\ucf1c\ubcf4\ub294 \uc77c\uc774 \uace7 \uc790\uae30 \uc790\uae08\uc744 \uc6c0\uc9c1\uc774\ub294 \ud310\ub2e8\uc73c\ub85c \uc774\uc5b4\uc9c0\uba74\uc11c \uc608\uc0c1\uacfc \ud604\uc2e4\uc774 \uc11c\ub85c \uac15\ud654\ub41c\ub2e4. \ub2e4\ub9cc \uc774\ub7f0 \uc5f0\uacb0\uc744 \uc124\uba85\ud558\ub294 \uac83\uacfc \ubaa8\ub4e0 \uc2e4\ud328\uac00 \uadfc\uac70 \uc5c6\ub294 \uacf5\ud3ec \ub54c\ubb38\uc774\uc5c8\ub2e4\uace0 \uc8fc\uc7a5\ud558\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uc624\ubc84\ub80c\ub4dc\uc758 \uc2e4\uc81c \uc190\uc2e4\uacfc \uacbd\uc601 \ubb38\uc81c\ub97c \uc9c0\uc6b0\uba74 \uc0ac\ub840\uc758 \ud575\uc2ec\uc744 \ub193\uce5c\ub2e4. \uc798\ubabb\ub41c \uc0ac\uc5c5 \ud310\ub2e8\uc774 \uc788\uc5c8\uace0, \uadf8 \uc2e4\ud328\uac00 \ub354 \ub113\uc740 \uc9c0\uae09 \uc555\ubc15\uc744 \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \ub450 \uce35\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uae08\uc735\uc0ac\uc758 \uad6c\uccb4\uc801\uc778 \uc0ac\uac74\uc774 \uc77c\ubc18 \uc6d0\ub9ac\ub97c \uc0dd\uac01\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub418\ub294 \uc774\uc720\ub2e4. \ubc30\uc800\ud2b8\ub294 \uacf5\ud669 \ub54c \uc88b\uc740 \ub2f4\ubcf4\ub97c \uac00\uc9c4 \uacf3\uc5d0 \ucda9\ubd84\ud788 \ub300\ucd9c\ud558\ub418 \ub192\uc740 \uae08\ub9ac\ub97c \uc801\uc6a9\ud558\ub294 \uc6d0\uce59\uc744 \uc81c\uc2dc\ud588\ub2e4. \ubaa9\uc801\uc740 \ubaa8\ub4e0 \ud68c\uc0ac\uc758 \uacfc\uac70 \uc190\uc2e4\uc744 \uc5c6\uc560\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ubd88\uc548 \ub54c\ubb38\uc5d0 \uc815\uc0c1\uc801\uc778 \uc9c0\uae09\uc774 \uba48\ucd94\ub294 \uc0c1\ud669\uc744 \uc9c4\uc815\uc2dc\ud0a4\ub294 \ub370 \uc788\uc5c8\ub2e4. \uc5ec\uae30\uc5d0\ub294 \ub3c4\uc6c0\uc758 \ubc94\uc704\uc640 \uc870\uac74\uc744 \ud310\ub2e8\ud558\ub294 \uc5b4\ub824\uc6c0\uc774 \ub530\ub978\ub2e4. \ub2f4\ubcf4\uac00 \uc815\ub9d0 \uc88b\uc740\uc9c0, \uc77c\uc2dc\uc801\uc778 \uc790\uae08 \ubd80\uc871\uc778\uc9c0 \uc54c\uc544\uc57c \ud55c\ub2e4. \uc5ed\uc0ac\uc801 \uc6d0\uce59\uc744 \uc624\ub298\uc758 \ubaa8\ub4e0 \uc81c\ub3c4\uc5d0 \uadf8\ub300\ub85c \ubd99\uc77c \uc218\ub294 \uc5c6\uc9c0\ub9cc, \ud68c\uc0ac\uc758 \uc190\uc2e4\uacfc \uc2dc\uc7a5\uc758 \uc720\ub3d9\uc131\uc744 \uad6c\ubd84\ud558\ub824\ub294 \uc9c8\ubb38\uc740 \uc774\uc5b4\uc9c4\ub2e4. \uc624\ubc84\ub80c\ub4dc \uac70\ub2c8\uc758 \uc0ac\ub840\ub97c \uc54c\uba74 \uc624\ub798\ub418\uace0 \uc720\uba85\ud55c \uae30\uad00\uc744 \ubcf4\ub294 \ub208\uc774 \uc870\uae08 \ub2ec\ub77c\uc9c4\ub2e4. \uba85\uc131\uc740 \uacfc\uac70\uc758 \uacbd\ud5d8\uc774 \uc313\uc778 \uacb0\uacfc\uc9c0\ub9cc \ud604\uc7ac\uc758 \uc190\uc2e4\uc744 \ub300\uc2e0 \uac1a\uc544 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uacbd\uc601\uc758 \ubcc0\ud654\uc640 \uc790\uc0b0\uc758 \uc9c8, \uc790\uae08\uc744 \ub3cc\ub824\uc904 \uc870\uac74\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. 1866\ub144\uc758 \uc758\ubbf8\ub294 \ud55c \ud68c\uc0ac\uc758 \uadf9\uc801\uc778 \ubab0\ub77d\uc5d0\ub9cc \uc788\uc9c0 \uc54a\ub2e4. \uc2dc\uc7a5\uc774 \uc5f0\uacb0\ub41c \uc0c1\ud669\uc5d0\uc11c \uc2e4\ud328\uac00 \uc5b4\ub5bb\uac8c \ubc88\uc9c0\uace0 \uc5b4\ub5a4 \ub3c4\uc6c0\uc744 \uad6c\ubd84\ud574\uc57c \ud558\ub294\uc9c0 \ub4dc\ub7ec\ub0c8\ub2e4\ub294 \ub370 \uc788\ub2e4. \uc774\ub984\uc744 \ubbff\uc5c8\ub358 \uc0ac\ub78c\ub4e4\uc758 \uacbd\ud5d8\uacfc \uc7a5\ubd80\uc758 \ud604\uc2e4\uc774 \ub4a4\ub2a6\uac8c \ub9cc\ub09c \uc0ac\uac74\uc774\uc5c8\ub2e4. \uc88b\uc740 \uc774\ub984\uc744 \uae30\uc5b5\ud558\ub294 \uc77c\uacfc \uc2e4\uc81c \uad6c\uc870\ub97c \uc774\ud574\ud558\ub294 \uc77c\uc774 \ub2e4\ub974\ub2e4\ub294 \uad50\ud6c8\uc774 \uadf8 \uc5ed\uc0ac\uc5d0 \ub0a8\uc544 \uc788\ub2e4."}, {"id": "roosevelt-bank-holiday-and-radio", "title": "1933\ub144\uc758 \uc740\ud589 \ud734\uc77c \u2014 \ubb38\uc744 \ub2eb\uace0 \uc2e0\ub8b0\ub97c \ub418\ucc3e\uc73c\ub824 \ud55c \uc774\uc720", "summary": "\uc740\ud589 \uc778\ucd9c \uc0ac\ud0dc \uc18d\uc758 \uc77c\uc2dc \ud734\uc5c5\uacfc \uac80\uc0ac, \ub77c\ub514\uc624 \uc124\uba85\uacfc \uc608\uae08\ubcf4\ud5d8 \uc81c\ub3c4\uc758 \uc758\ubbf8\ub97c \uc5ed\uc0ac\uc801\uc73c\ub85c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "finance", "category_title": "\ub3c8\uacfc \uae08\uc735", "subcategory": "\uc740\ud589\uacfc \uc2e0\uc6a9", "categories": ["finance"], "url": "stories/roosevelt-bank-holiday-and-radio/index.html", "image": "../media/roosevelt-bank-holiday-and-radio.png", "alt": "1930\ub144\ub300 \uac00\uc815\uc5d0\uc11c \ub77c\ub514\uc624\uc5d0 \uadc0\ub97c \uae30\uc6b8\uc774\ub294 \ub450 \uc0ac\ub78c\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "1933\ub144\uc758 \uc740\ud589 \ud734\uc77c \u2014 \ubb38\uc744 \ub2eb\uace0 \uc2e0\ub8b0\ub97c \ub418\ucc3e\uc73c\ub824 \ud55c \uc774\uc720 \ub8e8\uc2a4\ubca8\ud2b8\uc758 \uae34\uae09 \uc870\uce58\uc640 \uccab \ub178\ubcc0\ub2f4\ud654 \uc740\ud589 \uc778\ucd9c \uc0ac\ud0dc \uc18d\uc758 \uc77c\uc2dc \ud734\uc5c5\uacfc \uac80\uc0ac, \ub77c\ub514\uc624 \uc124\uba85\uacfc \uc608\uae08\ubcf4\ud5d8 \uc81c\ub3c4\uc758 \uc758\ubbf8\ub97c \uc5ed\uc0ac\uc801\uc73c\ub85c \uc77d\uc2b5\ub2c8\ub2e4. \uc740\ud589\uacfc \uc2e0\uc6a9 \ub3c8\uacfc \uae08\uc735 \uc740\ud589 \uc55e\uc5d0\uc11c \ub3c8\uc744 \ucc3e\uc73c\ub824\ub294 \uc0ac\ub78c\uc774 \ub298\uc5b4\ub098\ub294\ub370 \uc815\ubd80\ub294 \uc740\ud589 \ubb38\ubd80\ud130 \ub2eb\uc558\ub2e4. 1933\ub144 \ubbf8\uad6d\uc758 \uc740\ud589 \ud734\uc77c\uc774\ub2e4. \uc740\ud589\uc744 \uc26c\uac8c \ud55c\ub2e4\ub294 \ub9d0\uc740 \ub290\uae0b\ud558\uac8c \ub4e4\ub9ac\uc9c0\ub9cc \uc2e4\uc81c\ub85c\ub294 \uc9c0\uae09\uacfc \uc2e0\ub8b0\uac00 \ubb34\ub108\uc9c0\ub294 \uc18d\ub3c4\ub97c \uba48\ucd94\ub824\ub294 \uae34\uae09 \uc870\uce58\uc600\ub2e4. \ubb38\uc744 \ub2e4\uc2dc \uc5ec\ub294 \uac83\ub9cc\uc73c\ub85c \uc0ac\ub78c\ub4e4\uc758 \ubd88\uc548\uc774 \uc0ac\ub77c\uc9c8 \uc218\ub294 \uc5c6\uc5c8\ub2e4. \ubb34\uc5c7\uc744 \ud655\uc778\ud588\uace0 \uc55e\uc73c\ub85c \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc9c0\ub294\uc9c0 \uc124\uba85\ud574\uc57c \ud588\ub2e4. \ub8e8\uc2a4\ubca8\ud2b8\ub294 \uadf8\ub54c \ub77c\ub514\uc624\ub97c \ud1b5\ud574 \uc2dc\ubbfc\ub4e4\uc5d0\uac8c \uc740\ud589\uc758 \uc0ac\uc815\uc744 \uc774\uc57c\uae30\ud588\ub2e4. \ub300\uacf5\ud669 \uc18d\uc5d0\uc11c \uc740\ud589\uc774 \uc5b4\ub824\uc6cc\uc9c0\uace0 \ubb38\uc744 \ub2eb\ub294 \uc77c\uc774 \uc774\uc5b4\uc84c\ub2e4. \uc608\uae08\uc744 \uc783\uc744\uc9c0 \ubaa8\ub978\ub2e4\uace0 \ub290\ub080 \uc0ac\ub78c\uc740 \uba3c\uc800 \ub3c8\uc744 \ucc3e\uc73c\ub824 \ud588\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc778\ucd9c \ubaa8\uc2b5\uc740 \ub0a8\uc544 \uc788\ub294 \uc0ac\ub78c\uc758 \ubd88\uc548\ub3c4 \ud0a4\uc6e0\ub2e4. \uc740\ud589\uc740 \ubc1b\uc740 \uc608\uae08\uc744 \uae08\uace0\uc758 \ud604\uae08\uc73c\ub85c\ub9cc \ub450\uc9c0 \uc54a\ub294\ub2e4. \ub300\ucd9c \ub4f1\uc73c\ub85c \uc6b4\uc6a9\ud558\ub294 \ub3c8\uc774 \uc788\ub2e4. \ub530\ub77c\uc11c \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \ub3d9\uc2dc\uc5d0 \ud604\uae08\uc744 \uc694\uad6c\ud558\uba74 \ub2f9\uc7a5 \uc900\ube44\ud55c \ub3c8\uc774 \ubd80\uc871\ud560 \uc218 \uc788\ub2e4. \uac1c\ubcc4 \uc608\uae08\uc790\uc758 \ubc29\uc5b4\uac00 \uc740\ud589 \uc804\uccb4\uc758 \uc704\uae30\ub97c \ub354 \ube60\ub974\uac8c \ub9cc\ub4e4\uae30\ub3c4 \ud588\ub2e4. \ud504\ub7ad\ud074\ub9b0 \ub8e8\uc2a4\ubca8\ud2b8\uac00 1933\ub144 3\uc6d4 \ucde8\uc784\ud588\uc744 \ub54c \uc774\ubbf8 \uc5ec\ub7ec \uc8fc\uc5d0\uc11c \uc740\ud589 \uc601\uc5c5\uc744 \uc81c\ud55c\ud558\uace0 \uc788\uc5c8\ub2e4. \ucde8\uc784\uc0ac\ub97c \ud558\ub294 \uc21c\uac04\uc5d0 \uc0c8\ub85c\uc6b4 \ud604\uae08\uacfc \uc2e0\ub8b0\uac00 \uc0dd\uae30\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc77c\uc0c1\uc801\uc778 \uc601\uc5c5 \uc18d\uc5d0\uc11c \ud574\uacb0\ud558\uae30 \uc5b4\ub824\uc6b4 \uc18d\ub3c4\uc758 \uc704\uae30\uc600\ub2e4. \uc804\uad6d\uc801\uc778 \uc740\ud589 \ud734\uc77c\uc740 \ud604\uae08 \uc778\ucd9c\uc758 \uc5f0\uc1c4\ub97c \uc7a0\uc2dc \uba48\ucd94\uace0 \uc740\ud589\uc744 \uc0b4\ud544 \uc2dc\uac04\uc744 \ud655\ubcf4\ud558\ub824\ub294 \uc120\ud0dd\uc774\uc5c8\ub2e4. \uc2dc\ubbfc\ub4e4\uc5d0\uac8c\ub294 \uc2e4\uc81c \ubd88\ud3b8\uc774 \ub530\ub790\ub2e4. \ubb38\uc774 \ub2eb\ud78c \ub3d9\uc548 \uae09\ud55c \uc9c0\uae09\uacfc \uc0dd\ud65c\uc758 \ud544\uc694\ub97c \uc5b4\ub5bb\uac8c \uac10\ub2f9\ud560\uc9c0\ub3c4 \ubb38\uc81c\uc600\ub2e4. 3\uc6d4 9\uc77c \uae34\uae09\uc740\ud589\ubc95\uc774 \ud1b5\uacfc\ub418\uba74\uc11c \uc740\ud589\uc744 \uac80\uc0ac\ud558\uace0 \uc7ac\ud3b8\ud560 \uad8c\ud55c\uc774 \uac15\ud654\ub418\uc5c8\ub2e4. \ub2e8\uc9c0 \uba70\uce60 \uae30\ub2e4\ub9ac\uba74 \ubaa8\ub450 \uad1c\ucc2e\uc544\uc9c4\ub2e4\ub294 \uc57d\uc18d\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc601\uc5c5\uc744 \uc7ac\uac1c\ud560 \uc218 \uc788\ub294 \uacf3\uacfc \uc870\uce58\uac00 \ud544\uc694\ud55c \uacf3\uc744 \uac00\ub824\uc57c \ud588\ub2e4. \uac80\uc0ac\uc640 \uc81c\ub3c4\uc758 \ub4b7\ubc1b\uce68 \uc5c6\uc774 \ub2e4\uc2dc \ubbff\uc73c\ub77c\ub294 \ub9d0\ub9cc \ud55c\ub2e4\uba74 \uc124\ub4dd\ub825\uc740 \uc57d\ud588\uc744 \uac83\uc774\ub2e4. \uc740\ud589\uc758 \uc0ac\uc815\uc5d0 \ub300\ud574 \uc77c\ubc18 \uc608\uae08\uc790\uac00 \ud63c\uc790 \uc54c\uae30 \uc5b4\ub824\uc6b4 \ub9cc\ud07c \uacf5\uc801 \ud655\uc778\uc758 \uc5ed\ud560\uc774 \ucee4\uc84c\ub2e4. \uc2e0\ub8b0\ub97c \uac1c\uc778\uc758 \ub099\uad00\uc5d0\ub9cc \ub9e1\uae30\uc9c0 \uc54a\uc73c\ub824\ub294 \ub300\uc751\uc774\uc5c8\ub2e4. \uc601\uc5c5 \uc7ac\uac1c\ub97c \uc55e\ub454 3\uc6d4 12\uc77c \ub300\ud1b5\ub839\uc740 \uccab \ub178\ubcc0\ub2f4\ud654\ub97c \ud588\ub2e4. \uadf8\ub294 \ubc95\ub960\uacfc \uc740\ud589\uc758 \uc804\ubb38\uc801\uc778 \ud45c\ud604\uc744 \uc2dc\ubbfc\ub4e4\uc774 \uc774\ud574\ud560 \uc218 \uc788\ub3c4\ub85d \uc124\uba85\ud560 \ud544\uc694\uac00 \uc788\ub2e4\uace0 \ub9d0\ud588\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \uacaa\uc740 \ubd88\ud3b8\uacfc \ud611\uc870\ub97c \uc5b8\uae09\ud558\ub294 \ub9d0\ub3c4 \ub2f4\uc558\ub2e4. \ub77c\ub514\uc624\ub294 \uac19\uc740 \uc124\uba85\uc744 \ub9ce\uc740 \uc9d1\uc73c\ub85c \uc9c1\uc811 \uc804\ub2ec\ud588\ub2e4. \uc2e0\ubb38\uc758 \uc694\uc57d\uc744 \uae30\ub2e4\ub9ac\ub294 \uac83\uacfc\ub294 \ub2e4\ub978 \uacbd\ud5d8\uc774\uc5c8\ub2e4. \uc2dc\ubbfc\uc740 \uac70\ub300\ud55c \uc81c\ub3c4\uc758 \ubcc0\ud654\ub97c \ub4e3\ub294 \ub3d9\uc2dc\uc5d0 \uc790\uae30 \ub3c8\uc774 \ub193\uc778 \uc0c1\ud669\uc744 \uc774\ud574\ud558\ub824 \ud588\ub2e4. \uc5b4\ub824\uc6b4 \ubb38\uc81c\ub97c \uc26c\uc6b4 \ub9d0\ub85c \ud480\uc5b4\uc57c \ud560 \uc774\uc720\uac00 \ubd84\uba85\ud588\ub2e4. \ub300\ud1b5\ub839\uc758 \uce68\ucc29\ud55c \ub9d0\ud22c\ub294 \ubd88\uc548\uc744 \ub0ae\ucd94\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub418\uc5c8\ub2e4. \ud558\uc9c0\ub9cc \ubaa9\uc18c\ub9ac\ub9cc\uc73c\ub85c \uc740\ud589\uc774 \uac74\uc804\ud574\uc9c4 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac80\uc0ac\uc640 \uc7ac\uac1c \uc808\ucc28, \uc55e\uc73c\ub85c\uc758 \uac10\ub3c5\uc774 \uc124\uba85\uc758 \uadfc\uac70\ub85c \ud568\uaed8 \uc81c\uc2dc\ub418\uc5c8\ub2e4. \uc88b\uc740 \uc18c\ud1b5\uacfc \uc81c\ub3c4\ub294 \uc11c\ub85c\uc758 \uc5ed\ud560\uc744 \ub300\uc2e0\ud558\uae30\ubcf4\ub2e4 \uc5f0\uacb0\ub418\uc5b4\uc57c \ud588\ub2e4. \ubb34\uc5c7\uc744 \ud588\ub294\uc9c0 \ub9d0\ud558\uace0 \uadf8 \ub9d0\uc5d0 \ub9de\ub294 \uc870\uce58\uac00 \ub4a4\ub530\ub77c\uc57c \ud55c\ub2e4. \uc2dc\ubbfc\uc5d0\uac8c \ud611\ub825\uc744 \ubd80\ud0c1\ud558\ub294 \uc0c1\ud669\uc77c\uc218\ub85d \uc870\uce58\uc758 \uc774\uc720\uc640 \ubc94\uc704\ub97c \uc124\uba85\ud558\ub294 \uc77c\uc774 \uc911\uc694\ud588\ub2e4. \uac80\uc0ac\ub97c \uac70\uccd0 \uc740\ud589\ub4e4\uc774 \ub2e4\uc2dc \uc601\uc5c5\uc744 \uc2dc\uc791\ud588\uace0 \uc608\uae08\uc774 \ub3cc\uc544\uc624\uae30 \uc2dc\uc791\ud588\ub2e4. \ud63c\uc790 \ud604\uae08\uc744 \uc228\uaca8 \ub450\ub294 \uac83\ub9cc\uc774 \uc548\uc804\ud558\ub2e4\uace0 \ub290\ub07c\ub358 \uc0c1\ud0dc\uc5d0\uc11c \uc870\uae08\uc529 \ubc97\uc5b4\ub09c \uac83\uc774\ub2e4. \uc740\ud589\uc758 \ubb38\uc740 \ubb3c\ub9ac\uc801\uc778 \ucd9c\uc785\uad6c\uc774\uba74\uc11c \uc2e0\ub8b0\uc758 \ud45c\uc2dd\uc774\uae30\ub3c4 \ud588\ub2e4. \uc774 \ubcc0\ud654\uac00 \ubaa8\ub4e0 \uc608\uae08\uc790\uc758 \uc190\uc2e4\uc744 \uc5c6\uc560\uac70\ub098 \ubaa8\ub4e0 \uc740\ud589\uc758 \ubb38\uc81c\ub97c \ud574\uacb0\ud588\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc704\uae30\uc758 \uc9c4\uc815\uacfc \uacfc\uac70 \ud53c\ud574\uc758 \ud68c\ubcf5\uc740 \ub2e4\ub978 \uc77c\uc774\ub2e4. \uc7ac\uac1c\ud55c \uc740\ud589\uc5d0 \ub300\ud55c \uc2e0\ub8b0\ub3c4 \uc774\ud6c4\uc758 \uac10\ub3c5\uacfc \uc6b4\uc601\uc5d0 \uacc4\uc18d \ub2ec\ub824 \uc788\uc5c8\ub2e4. 1933\ub144\uc5d0\ub294 \uc5f0\ubc29\uc608\uae08\ubcf4\ud5d8\uacf5\uc0ac \uc124\ub9bd\uc744 \ud3ec\ud568\ud55c \uc740\ud589 \uc81c\ub3c4 \uac1c\ud3b8\ub3c4 \uc774\ub8e8\uc5b4\uc84c\ub2e4. \uc608\uae08\uc790\ub97c \uc77c\uc815\ud55c \uc81c\ub3c4 \uc544\ub798 \ubcf4\ud638\ud558\ub294 \uc7a5\uce58\uac00 \ub9c8\ub828\ub41c \uac83\uc774\ub2e4. \uc740\ud589 \ud55c \uacf3\uc758 \uc57d\uc18d\ub9cc\uc73c\ub85c \uc608\uae08\uc790\uc758 \ubd88\uc548\uc744 \ub2e4\ub8e8\uc9c0 \uc54a\uc73c\ub824\ub294 \ubcc0\ud654\uc600\ub2e4. \ub2f9\uc2dc\uc758 \ubcf4\ud638 \ubc94\uc704\uc640 \uc624\ub298\uc758 \uc870\uac74\uc740 \uac19\uc9c0 \uc54a\ub2e4. \uc774 \uae00\uc740 \ud604\uc7ac \uae08\uc735\uc0c1\ud488\uc758 \uc548\uc804\uc131\uc774\ub098 \uac00\uc785 \uc870\uac74\uc744 \uc548\ub0b4\ud558\ub294 \uae00\uc774 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uc704\ud5d8\uc744 \uac1c\uc778\uc5d0\uac8c \ub9e1\uae30\uace0 \uc5b4\ub5a4 \uc704\ud5d8\uc744 \uacf5\ub3d9\uc758 \uc81c\ub3c4\ub85c \ub098\ub20c\uc9c0 \ubc14\ub00c\uc5b4 \uac04 \uc5ed\uc0ac\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\ub2e4. \uc740\ud589 \uc704\uae30\uc5d0 \ub300\uc751\ud558\ub294 \uc77c\uc740 \uc2e4\uc5c5\uacfc \ube48\uace4, \uc0dd\uc0b0\uc758 \uc704\ucd95\uc744 \ubaa8\ub450 \ud574\uacb0\ud558\ub294 \uc77c\uacfc \uac19\uc9c0 \uc54a\uc558\ub2e4. \ub274\ub51c\uc5d0\ub294 \uc77c\uc790\ub9ac\uc640 \ub18d\uc5c5, \uc0b0\uc5c5\uc744 \ub458\ub7ec\uc2fc \uc5ec\ub7ec \uc815\ucc45\uc774 \uc774\uc5b4\uc84c\ub2e4. \uc131\uacfc\uc640 \ud55c\uacc4\ub97c \ub450\uace0 \ub17c\uc7c1\ub3c4 \uacc4\uc18d\ub418\uc5c8\ub2e4. \ub530\ub77c\uc11c 3\uc6d4\uc758 \ub77c\ub514\uc624 \uc5f0\uc124\uc744 \uacbd\uc81c \uc804\uccb4\ub97c \ub2e8\ubc88\uc5d0 \uad6c\ud55c \ud55c \ud3b8\uc758 \ub9d0\ub85c \uae30\uc5b5\ud558\uba74 \uacfc\uc7a5\ub41c\ub2e4. \ub2e4\ub9cc \uae09\ud55c \uc704\uae30 \uc18d\uc5d0\uc11c \ubb34\uc5c7\uc744 \uba3c\uc800 \uba48\ucd94\uace0 \ubb34\uc5c7\uc744 \ud655\uc778\ud558\uba70 \uc5b4\ub5bb\uac8c \uc124\uba85\ud560\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \uc911\uc694\ud55c \uc7a5\uba74\uc73c\ub85c\ub294 \uc77d\uc744 \uc218 \uc788\ub2e4. \uc740\ud589\uc774 \uc26c\ub294 \ub3d9\uc548\uc5d0\ub3c4 \uc0ac\ub78c\ub4e4\uc740 \uac80\uc0ac\ud558\uace0 \ubc95\uc744 \ub9cc\ub4e4\uace0 \uc7ac\uac1c\ub97c \uc900\ube44\ud588\ub2e4. \uc2dc\ubbfc\ub4e4\uc740 \ubd88\ud3b8 \uc18d\uc5d0\uc11c \uae30\ub2e4\ub838\ub2e4. \ud734\uc77c\uc774\ub77c\ub294 \uc774\ub984\uc740 \uadf8 \ubc14\uc05c \uc2dc\uac04\uc744 \uac00\ub9ac\uae30 \uc27d\ub2e4. \uba48\ucda4\uc774 \uc544\ubb34\uac83\ub3c4 \ud558\uc9c0 \uc54a\ub294 \uc77c\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc774 \uc774\uc57c\uae30\ub97c \ub0a8\uae30\ub294 \uac83\uc740 \uc5f0\uc124\uc758 \ub530\ub73b\ud55c \ubd84\uc704\uae30\ub9cc\uc774 \uc544\ub2c8\ub2e4. \ubbff\uc73c\ub77c\uace0 \uc694\uad6c\ud558\uae30 \uc804\uc5d0 \ubbff\uc744 \uadfc\uac70\ub97c \ub9cc\ub4e4\uace0 \uc124\uba85\ud574\uc57c \ud55c\ub2e4\ub294 \uc9c8\ubb38\uc774\ub2e4. \ubb38\uc744 \ub2eb\uc558\ub2e4 \ub2e4\uc2dc \uc5ec\ub294 \uc9e7\uc740 \uacfc\uc815\uc5d0 \ub3c8\uacfc \uc81c\ub3c4, \ub9d0\uc758 \uad00\uacc4\uac00 \ud568\uaed8 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4."}, {"id": "ruthwell-savings-bank-small-deposits", "title": "\uc800\ucd95\uc740\ud589 \u2014 \uc791\uc740 \ub3c8\ub3c4 \uc608\uae08\uc774 \ub418\ub294 \uc870\uac74", "summary": "1810\ub144 \ub8e8\uc2a4\uc6f0\uacfc \uc120\ud589 \uc0ac\ub840\ub97c \ud1b5\ud574 \uc801\uc740 \uc608\uae08\uc744 \uacc4\uc18d \ubc1b\uc544 \uc904 \uc6b4\uc601\uacfc \ucc45\uc784\uc758 \uc870\uac74\uc744 \ubd05\ub2c8\ub2e4.", "category": "finance", "category_title": "\ub3c8\uacfc \uae08\uc735", "subcategory": "\uc740\ud589\uacfc \uc2e0\uc6a9", "categories": ["finance"], "url": "stories/ruthwell-savings-bank-small-deposits/index.html", "image": "../media/ruthwell-savings-bank-small-deposits.png", "alt": "\uc791\uc740 \ub3d9\uc804\uc744 \ub9e1\uae30\uace0 \uc7a5\ubd80\uc5d0 \uae30\ub85d\ud558\ub294 \ucd08\uae30 \uc800\ucd95\uc740\ud589 \uc5c5\ubb34\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uc800\ucd95\uc740\ud589 \u2014 \uc791\uc740 \ub3c8\ub3c4 \uc608\uae08\uc774 \ub418\ub294 \uc870\uac74 \ub8e8\uc2a4\uc6f0\uc758 \uc0ac\ub840\ub85c \uc77d\ub294 \uc18c\uc561 \uc800\ucd95\uacfc \uae30\ub85d\u00b7\uc6b4\uc601\uc758 \uc5ed\uc0ac 1810\ub144 \ub8e8\uc2a4\uc6f0\uacfc \uc120\ud589 \uc0ac\ub840\ub97c \ud1b5\ud574 \uc801\uc740 \uc608\uae08\uc744 \uacc4\uc18d \ubc1b\uc544 \uc904 \uc6b4\uc601\uacfc \ucc45\uc784\uc758 \uc870\uac74\uc744 \ubd05\ub2c8\ub2e4. \uc740\ud589\uacfc \uc2e0\uc6a9 \ub3c8\uacfc \uae08\uc735 \uc740\ud589\uc774 \uc874\uc7ac\ud55c\ub2e4\uace0 \ubaa8\ub450\uac00 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc774\uc6a9\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc800\ucd95\ud560 \ub3c8\uc774 \uc801\uace0 \uc870\uae08\uc529 \uc0dd\uae30\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ub3c8\uc744 \ub9e1\uae30\ub294 \uc870\uac74\uacfc \ube44\uc6a9\uc774 \ub2e4\ub974\uac8c \ub290\uaef4\uc9c4\ub2e4. 19\uc138\uae30 \ucd08 \uc800\ucd95\uc740\ud589\uc758 \uc5ed\uc0ac\ub294 \uc791\uc740 \uae08\uc561\uc744 \ubaa8\uc544 \ubcf4\uad00\ud558\uace0 \uc774\uc790\ub97c \uc8fc\ub294 \uc77c\uc774 \uc5b4\ub5a4 \uc81c\ub3c4\uc640 \uc6b4\uc601\uc744 \uc694\uad6c\ud588\ub294\uc9c0 \ubcf4\uc5ec \uc900\ub2e4. \uc608\uae08\uc561\uc774 \uc791\uc544\ub3c4 \ub204\uac00 \uc5bc\ub9c8\ub97c \ub123\uc5c8\ub294\uc9c0 \uae30\ub85d\ud558\uace0 \ub3cc\ub824\uc904 \ub54c \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uac70\ub798 \ud55c \ubc88\uc5d0 \ud544\uc694\ud55c \uc5c5\ubb34\uac00 \uc608\uae08\uc561\uacfc \uac19\uc740 \ube44\uc728\ub85c \uc904\uc5b4\ub4dc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc18c\uc561 \uace0\uac1d\uc744 \ubaa8\uc73c\ub294 \uc77c\uc5d0\ub294 \ubcc4\ub3c4\uc758 \uc6b4\uc601 \ubc29\uc2dd\uc774 \ud544\uc694\ud588\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc18c\uc561 \uc800\ucd95\uc744 \uc0ac\uc18c\ud55c \uc77c\ub85c \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uc784\uae08\uc758 \uc77c\ubd80\ub97c \ub530\ub85c \ub450\uace0 \uc9c8\ubcd1\uc774\ub098 \uc2e4\uc9c1, \ud070 \uc9c0\ucd9c\uc5d0 \ub300\ube44\ud558\ub824\ub294 \uc0ac\ub78c\uc5d0\uac8c \uc911\uc694\ud55c \uc0dd\ud65c \uae30\ubc18\uc774 \ub420 \uc218 \uc788\uc5c8\ub2e4. \uc740\ud589 \uc11c\ube44\uc2a4\uc758 \uac00\uce58\ub97c \ucd1d\uc561\ubfd0 \uc544\ub2c8\ub77c \uc774\uc6a9\uc790\uc758 \uc0c1\ud669\uc5d0\uc11c \ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \uc2a4\ucf54\ud2c0\ub79c\ub4dc \ub8e8\uc2a4\uc6f0\uc758 \ud5e8\ub9ac \ub358\ucee8\uc740 1810\ub144 \uc800\ucd95\uc740\ud589\uc744 \uc2dc\uc791\ud588\ub2e4. \uc774\ub97c \uc138\uacc4 \uc5b4\ub514\uc5d0\ub3c4 \uc120\ud589 \uc0ac\ub840\uac00 \uc5c6\ub358 \uccab \uc2dc\ub3c4\ub77c\uace0 \ub9d0\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc70c\ub9ac\uc5c4 \ub8e8\uc778\uc2a4\uc758 \uc800\ucd95\uc740\ud589\uc0ac\ub294 \uadf8\ubcf4\ub2e4 \uc55e\uc120 \uc5ec\ub7ec \ud615\ud0dc\uc758 \uc800\ucd95 \uc870\uc9c1\ub3c4 \ud568\uaed8 \uae30\ub85d\ud55c\ub2e4. \ub8e8\uc2a4\uc6f0\uc758 \uc758\ubbf8\ub294 \uc791\uc740 \uc9c0\uc5ed\uc5d0\uc11c \uc2e4\uc81c \uaddc\uce59\uc744 \uac16\ucd98 \uc0ac\uc5c5\uc744 \uc6b4\uc601\ud558\uace0 \uadf8 \uacbd\ud5d8\uc744 \ub2e4\ub978 \uacf3\uc73c\ub85c \ud37c\ub728\ub9b0 \ub370 \uc788\ub2e4. \uc81c\ub3c4\ub294 \uc88b\uc740 \ub73b\ub9cc\uc73c\ub85c \uc644\uc131\ub418\uc9c0 \uc54a\ub294\ub2e4. \ub204\uac00 \ucc38\uc5ec\ud558\uace0 \ub3c8\uc744 \uc5b4\ub5a4 \uc870\uac74\uc73c\ub85c \ub9e1\uae30\uba70 \uc5b4\ub5bb\uac8c \ub3cc\ub824\ubc1b\uc744\uc9c0 \uc815\ud574\uc57c \ud588\ub2e4. \ub8e8\uc2a4\uc6f0\ubcf4\ub2e4 \uc55e\uc120 1808\ub144 \ubc30\uc2a4\uc758 \uc0ac\ub840\ub294 \uac00\uc0ac \ub178\ub3d9\uc790\uc758 \uc800\ucd95\uc744 \ubc1b\uc544 \uc8fc\ub824\ub294 \uad6c\uc0c1\uc73c\ub85c \uc18c\uac1c\ub41c\ub2e4. \uc774\ub7f0 \uc120\ud589 \uc0ac\ub840\ub97c \ud568\uaed8 \ubcf4\uba74 \ub358\ucee8\uc758 \uc0ac\uc5c5\uc744 \uace0\ub9bd\ub41c \ucc9c\uc7ac\uc758 \ubc1c\uba85\ubcf4\ub2e4 \uc5ec\ub7ec \uc2e4\ud5d8\uc774 \uc774\uc5b4\uc9c4 \uacfc\uc815\uc73c\ub85c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc9c0\uc5ed\uc740 \ub204\uac00 \uc774\uc6a9\ud560 \uc218 \uc788\uc744\uc9c0\uc5d0 \ub2e4\ub978 \ub2f5\uc744 \ub0b4\ub193\uc558\ub2e4. \ub8e8\uc778\uc2a4\uc758 \uae30\ub85d\uc5d0\uc11c \ub8e8\uc2a4\uc6f0 \uc0ac\uc5c5\uc758 \uccab\ud574\uc5d0 \ub9e1\uaca8\uc9c4 \ub3c8\uc740 151\ud30c\uc6b4\ub4dc\uc600\ub2e4. \uc624\ub298\uc758 \uac00\uaca9\uc73c\ub85c \uc131\uae09\ud788 \ud658\uc0b0\ud558\uae30\ubcf4\ub2e4 \uc791\uc740 \uac70\ub798\uac00 \uc2e4\uc81c \uc7a5\ubd80\uc758 \ud569\uacc4\uac00 \ub418\uc5c8\ub2e4\ub294 \uc810\uc5d0 \uc8fc\ubaa9\ud560 \uc218 \uc788\ub2e4. \uc88b\uc740 \ub73b\uc73c\ub85c \ubaa8\uc778 \uc0ac\ub78c\ub4e4\uc774 \uaddc\uce59\uc744 \uc138\uc6b0\uace0 \ub3c8\uc744 \ubc1b\uc544 \ud655\uc778\ud558\ub294 \uc5c5\ubb34\ub97c \uc218\ud589\ud55c \uac83\uc774\ub2e4. \uc131\uacfc\ub294 \uae08\uc561\uc758 \ud06c\uae30\ub9cc\uc774 \uc544\ub2c8\ub77c \uac19\uc740 \uc77c\uc744 \ub2e4\uc74c \ud574\uc5d0\ub3c4 \uc774\uc5b4 \uac08 \uc218 \uc788\ub294 \uad6c\uc870\ub97c \ub9c8\ub828\ud588\ub2e4\ub294 \ub370\uc5d0\ub3c4 \uc788\uc5c8\ub2e4. \ub3c4\uc6c0\uc774 \ud544\uc694\ud55c \uc0ac\ub78c\uc5d0\uac8c \ub3c8\uc744 \ub098\ub204\uc5b4 \uc8fc\ub294 \uc77c\uacfc, \uc790\uae30 \ub3c8\uc744 \ub9e1\uae34 \uc0ac\ub78c\uc5d0\uac8c \ub3cc\ub824\uc904 \uc758\ubb34\ub97c \uc9c0\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \ucd08\uae30 \uc800\ucd95 \uc81c\ub3c4\uc5d0\ub294 \uc790\uc120\uc801\uc778 \ub3d9\uae30\uc640 \uc790\uc6d0\ubd09\uc0ac\uac00 \uc788\uc5c8\uc9c0\ub9cc \uc608\uae08\uc790\ub294 \ub2e8\uc21c\ud788 \uc120\ubb3c\uc744 \ubc1b\ub294 \uc0ac\ub78c\ub9cc\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc774 \ucc28\uc774\ub97c \uc54c\uc544\uc57c \uc800\ucd95\uc740\ud589\uc774 \uc694\uad6c\ud55c \ucc45\uc784\ub3c4 \ubcf4\uc778\ub2e4. \uc88b\uc740 \ubaa9\uc801\uc744 \ub0b4\uc138\uc6cc\ub3c4 \uc7a5\ubd80\uac00 \ubd80\uc815\ud655\ud558\uac70\ub098 \uc9c0\uae09\uc744 \ud558\uc9c0 \ubabb\ud558\uba74 \ubb38\uc81c\uac00 \ub41c\ub2e4. \ub3c4\ub355\uc801\uc778 \uc758\ub3c4\uc640 \uae08\uc735\uae30\uad00\uc758 \uc2e0\ub8b0\uc131\uc740 \uac19\uc740 \uac83\uc73c\ub85c \uac04\uc8fc\ud560 \uc218 \uc5c6\ub2e4. \uc608\uae08\uc758 \uc5ed\uc0ac\ub294 \ub9e1\uae34 \ub3c8\uc5d0 \ub300\ud55c \uad8c\ub9ac\uc758 \uc5ed\uc0ac\uc774\uae30\ub3c4 \ud558\ub2e4. \ucd08\uae30 \uae30\uad00\ub4e4\uc740 \uc608\uae08\uc758 \uaddc\ubaa8\uc640 \uc785\ucd9c\uae08 \uc808\ucc28, \uad00\ub9ac\uc790\uc758 \uc5ed\ud560\uc744 \uc815\ud588\ub2e4. \uc791\uc740 \uae08\uc561\uc744 \ubc1b\uc544\ub3c4 \uacc4\uc18d \uc5c5\ubb34\ub97c \uc218\ud589\ud560 \uc218 \uc788\uc5b4\uc57c \ud588\uae30 \ub54c\ubb38\uc774\ub2e4. \uaddc\uce59\uc740 \uc774\uc6a9\uc744 \ud3b8\ud558\uac8c \ud558\ub294 \ub3d9\uc2dc\uc5d0 \uae30\uad00\uc758 \uc6b4\uc601\uc744 \uac00\ub2a5\ud558\uac8c \ud558\ub294 \uc870\uac74\uc774\uc5c8\ub2e4. \uc5b4\ub5a4 \uc81c\ud55c\uc740 \uad00\ub9ac\uc5d0 \ub3c4\uc6c0\uc774 \ub418\uc5b4\ub3c4 \ud2b9\uc815 \uc774\uc6a9\uc790\uc5d0\uac8c\ub294 \ubd88\ud3b8\ud560 \uc218 \uc788\ub2e4. \uc81c\ub3c4\ub97c \ud3c9\uac00\ud560 \ub54c\uc5d0\ub294 \uaddc\uce59\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ubcf4\ub2e4 \ub204\uad6c\uc758 \uc0c1\ud669\uc5d0 \uc798 \ub9de\ub294\uc9c0 \ubb3c\uc5b4\ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \uc18c\uc561 \uc800\ucd95\uc774\ub77c\ub294 \ubaa9\uc801\ub3c4 \uc2e4\uc81c \uc0dd\ud65c\uc758 \ub2e4\uc591\ud55c \uc8fc\uae30\uc640 \uc694\uad6c\ub97c \ub9cc\ub098\uba74 \uc138\ubd80\uc801\uc778 \ud310\ub2e8\uc774 \ud544\uc694\ud574\uc9c4\ub2e4. \uc608\uae08\uc790\uc758 \uc774\ub984\uacfc \uae08\uc561, \uc774\uc790\uc640 \uc9c0\uae09\uc758 \uae30\ub85d\uc744 \uc815\ud655\ud788 \uc774\uc5b4 \uac00\uc57c \ud588\ub2e4. \uc5ec\ub7ec \uc0ac\ub78c\uc774 \uae30\uad00\uc744 \uc6b4\uc601\ud558\uba74 \uc5c5\ubb34\ub97c \ud655\uc778\ud560 \ubc29\uc2dd\ub3c4 \ud544\uc694\ud558\ub2e4. \uae08\uace0\uac00 \ud2bc\ud2bc\ud558\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc608\uae08\uc758 \ubaa8\ub4e0 \uc704\ud5d8\uc774 \ud574\uacb0\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc800\ucd95\uc740\ud589\uc758 \ud655\ub300\ub294 \uc774\ub7f0 \uc0ac\ubb34\uc640 \uac10\ub3c5\uc758 \ubb38\uc81c\ub97c \ub354 \ud06c\uac8c \ub9cc\ub4e4\uc5c8\ub2e4. \uaddc\ubaa8\uac00 \uc791\uc740 \uc9c0\uc5ed\uc758 \uce5c\ubd84\uc73c\ub85c \ud655\uc778\ud558\ub358 \uac83\uc744 \ub354 \ub113\uc740 \uc81c\ub3c4\ub85c \uc62e\uae38 \ub54c\uc5d0\ub294 \ub2e4\ub978 \uc7a5\uce58\uac00 \ud544\uc694\ud560 \uc218 \uc788\ub2e4. \ubbff\ub294 \uc0ac\ub78c\uc744 \uc544\ub294 \uc77c\uacfc \ubbff\uc744 \uc218 \uc788\uac8c \uc6b4\uc601\ud558\ub294 \uc77c\uc740 \uc774\uc5b4\uc9c0\uba74\uc11c\ub3c4 \ub2e4\ub974\ub2e4. 19\uc138\uae30 \uc800\ucd95\uc740\ud589\uc744 \ucc2c\uc591\ud558\ub294 \uae00\uc5d0\ub294 \uc131\uc2e4\uacfc \uc808\uc57d\uc744 \uac15\uc870\ud558\ub294 \ud45c\ud604\uc774 \ub9ce\ub2e4. \uadf8\ub7f0 \ubaa9\uc18c\ub9ac\ub294 \ub2f9\uc2dc\uc758 \uc0ac\ud68c\uad00\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uadf8\ub7ec\ub098 \uc800\ucd95\ud558\uc9c0 \ubabb\ud55c \ubaa8\ub4e0 \uc774\uc720\ub97c \uac1c\uc778\uc758 \uc758\uc9c0\uac00 \uc57d\ud574\uc11c\ub77c\uace0 \uc124\uba85\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc18c\ub4dd\uacfc \uace0\uc6a9, \uac00\uc871\uc758 \ubd80\ub2f4\uc774 \uc800\ucd95\ud560 \uc5ec\uc720\ub97c \ubc14\uafbc\ub2e4. \uc800\ucd95 \uc81c\ub3c4\uc758 \uc7a5\uc810\uacfc \uadf8 \uc81c\ub3c4\ub97c \uc774\uc6a9\ud560 \uc870\uac74\uc744 \ub098\ub204\uc5b4 \ubcfc \uc218 \uc788\ub2e4. \uae30\ud68c\uac00 \uc0dd\uae34 \uac83\uc740 \uc911\uc694\ud558\uc9c0\ub9cc \ubaa8\ub450\uac00 \uac19\uc740 \ucd9c\ubc1c\uc810\uc5d0 \uc120 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc790\ub8cc\uc758 \ub3c4\ub355\uc801 \ud3c9\uac00\ub97c \uadf8\ub300\ub85c \ubc18\ubcf5\ud558\uc9c0 \uc54a\uc744 \ub54c \uae08\uc735\uc0ac\uc758 \uc0ac\ud68c\uc801 \uc758\ubbf8\uac00 \ub354 \uc815\ud655\ud574\uc9c4\ub2e4. \uc624\ub298 \uc18c\uc561\uc744 \uacc4\uc88c\uc5d0 \ub123\ub294 \uc77c\uc740 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ubcf4\uc778\ub2e4. \uadf8\ub7ec\ub098 \ub9ce\uc740 \uc791\uc740 \uac70\ub798\ub97c \ubc1b\uc544 \uae30\ub85d\ud558\uace0 \uc9c0\uae09\ud560 \uccb4\uacc4\ub294 \uc800\uc808\ub85c \uc8fc\uc5b4\uc9c4 \uac83\uc774 \uc544\ub2c8\ub2e4. \ub8e8\uc2a4\uc6f0\uacfc \ub2e4\ub978 \ucd08\uae30 \uc0ac\ub840\ub4e4\uc740 \ub204\uac00 \uc740\ud589\uc758 \uace0\uac1d\uc774 \ub420 \uc218 \uc788\ub294\uc9c0 \ubc94\uc704\ub97c \ub113\ud788\ub294 \uc791\uc5c5\uc774\uc5c8\ub2e4. \uc800\ucd95\uc740\ud589\uc758 \uc5ed\uc0ac\ub294 \ud070\ub3c8\uc744 \ubaa8\uc740 \uae30\uad00\uc758 \uc131\uc7a5 \uc774\uc57c\uae30\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uc801\uc740 \ub3c8\uc744 \ub9e1\uae34 \uc0ac\ub78c\uc5d0\uac8c\ub3c4 \ubc18\ubcf5\ud574\uc11c \ub3cc\uc544\uc624\ub294 \uc11c\ube44\uc2a4\ub97c \ub9cc\ub4e4\ub824 \ud55c \uacfc\uc815\uc774\ub2e4. \ub9ce\uc740 \uace0\uac1d\uc774 \uac01\uc790 \ub9e1\uae34 \uc801\uc740 \ub3c8\uc744 \uc815\ud655\ud788 \uad6c\ubd84\ud574 \uc8fc\ub294 \uc77c\uc740 \ub2f9\uc2dc\uc5d0\ub3c4 \uc26c\uc6b4 \ubd80\uc18d \uc5c5\ubb34\uac00 \uc544\ub2c8\uc5c8\ub2e4. \uadf8 \ud655\uc778\uc758 \ubc18\ubcf5\uc774 \uc11c\ube44\uc2a4\ub97c \ub9cc\ub4e4\uc5c8\ub2e4. \uc791\uc740 \uc608\uae08 \ub4a4\uc5d0 \ud544\uc694\ud55c \uaddc\uce59\uacfc \ub178\ub3d9\uc744 \uc0b4\ud53c\uba74 \uae08\uc735\uc758 \ubc1c\uc804\uc744 \ub2e4\ub978 \ud06c\uae30\ub85c \ubcfc \uc218 \uc788\ub2e4."}, {"id": "south-sea-bubble-promise-and-shares", "title": "\ub0a8\ud574\ud68c\uc0ac \u2014 \ubc14\ub2e4 \uac74\ub108\uc758 \uafc8\uc740 \uc5b4\ub5bb\uac8c \uc8fc\uac00\uac00 \ub418\uc5c8\uc744\uae4c", "summary": "\ub0a8\ud574\ud68c\uc0ac \uac70\ud488\uc744 \ud68c\uace0\ud55c 1852\ub144\ud310 \uc5ed\uc0ac\uc11c\uc640 \ud638\uac00\uc2a4\uc758 \ud48d\uc790 \ub3c4\ud310\uc744 \ud1b5\ud574 \ubb34\uc5ed\u00b7\uad6d\uac00 \ubd80\ucc44\u00b7\uc8fc\uac00\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "finance", "category_title": "\ub3c8\uacfc \uae08\uc735", "subcategory": "\ud22c\uc790\uc640 \uc2dc\uc7a5", "categories": ["finance"], "url": "stories/south-sea-bubble-promise-and-shares/index.html", "image": "../media/south-sea-bubble-promise-and-shares.png", "alt": "\ud638\uac00\uc2a4\uc758 \ub0a8\ud574\ud68c\uc0ac \ud48d\uc790 \ub3c4\ud310. \uc911\uc559\uc758 \ud68c\uc804 \uae30\uad6c\ub97c \ud0c4 \uc0ac\ub78c\ub4e4\uacfc \uc8fc\ubcc0\uc758 \uad70\uc911.", "text": "\ub0a8\ud574\ud68c\uc0ac \u2014 \ubc14\ub2e4 \uac74\ub108\uc758 \uafc8\uc740 \uc5b4\ub5bb\uac8c \uc8fc\uac00\uac00 \ub418\uc5c8\uc744\uae4c 1720\ub144 \ub7f0\ub358\uc5d0\uc11c \ubb34\uc5ed\uc758 \uae30\ub300\uc640 \uad6d\uac00\uc758 \ube5a\uc774 \ub9cc\ub0ac\ub2e4 \ub0a8\ud574\ud68c\uc0ac \uac70\ud488\uc744 \ud68c\uace0\ud55c 1852\ub144\ud310 \uc5ed\uc0ac\uc11c\uc640 \ud638\uac00\uc2a4\uc758 \ud48d\uc790 \ub3c4\ud310\uc744 \ud1b5\ud574 \ubb34\uc5ed\u00b7\uad6d\uac00 \ubd80\ucc44\u00b7\uc8fc\uac00\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ud22c\uc790\uc640 \uc2dc\uc7a5 \ub3c8\uacfc \uae08\uc735 \ub0a8\uc544\uba54\ub9ac\uce74\uc758 \uae08\uacfc \uc740, \uba3c \ud56d\uad6c\uc5d0\uc11c \ub3cc\uc544\uc62c \ubc30, \uc9c0\uae08\ubcf4\ub2e4 \ud6e8\uc52c \ubd80\uc720\ud574\uc9c8 \ubbf8\ub798. 18\uc138\uae30 \ucd08 \ub7f0\ub358\uc5d0\uc11c \ub0a8\ud574\ud68c\uc0ac\ub77c\ub294 \uc774\ub984\uc5d0\ub294 \uc774\ub7f0 \uc774\ubbf8\uc9c0\uac00 \ubd99\uc5c8\ub2e4. \uc544\uc9c1 \ucda9\ubd84\ud788 \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\uc740 \uac70\ub798\uc758 \uac00\ub2a5\uc131\uc774 \uc0ac\ub78c\ub4e4\uc758 \ub208\uc55e\uc5d0\uc11c \ub3c8\uc758 \uac12\uc73c\ub85c \ubc14\ub00c\uc5c8\ub2e4. 1720\ub144\uc758 \ub0a8\ud574\ud68c\uc0ac \uac70\ud488\uc740 \ub2e8\uc21c\ud788 \ub0af\uc120 \uc8fc\uc2dd\uc744 \uc88b\uc544\ud55c \uc0ac\ub78c\ub4e4\uc758 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \ubb34\uc5ed\uc758 \uae30\ub300\uc640 \uc601\uad6d \uc815\ubd80\uc758 \ube5a, \uc8fc\uc2dd\uc73c\ub85c \uad50\ud658\ud558\ub294 \uacc4\ud68d\uc774 \uc5bd\ud600 \uc788\uc5c8\ub2e4. \ucc30\uc2a4 \ub9e5\ucf00\uc774\uc758 \ud68c\uace0\uc801 \uc11c\uc220\uc744 \ub530\ub77c\uac00\ub418, \uc624\ub798\ub41c \ucc45\uc758 \uacfc\uc7a5\ub41c \uad70\uc911 \ubb18\uc0ac\uc640 \ud655\uc778\ud560 \uc218 \uc788\ub294 \uc0ac\uc5c5\uc758 \uad6c\uc870\ub97c \ub098\ub204\uc5b4 \uc0b4\ud3b4\ubcf4\uc790. \ub0a8\ud574\ud68c\uc0ac\ub294 1711\ub144\uc5d0 \uc124\ub9bd\ub418\uc5c8\ub2e4. \ub9e5\ucf00\uc774\ub294 \uadf8 \ucd9c\ubc1c\uc744 \uc601\uad6d\uc758 \uacf5\uacf5 \uc2e0\uc6a9\uacfc \uad70\ube44 \ub4f1\uc5d0\uc11c \uc0dd\uae34 \ubd80\ucc44\ub97c \uc815\ub9ac\ud558\ub294 \uacc4\ud68d\uacfc \uc5f0\uacb0\ud574 \uc124\uba85\ud55c\ub2e4. \ud68c\uc0ac\ub294 \uc815\ubd80\uc758 \ucc44\ubb34\ub97c \ub9e1\uace0 \uadf8\uc5d0 \ub530\ub978 \uc9c0\uae09\uc744 \ubc1b\ub294 \uae08\uc735\uc801 \uc5ed\ud560\uc744 \uac00\uc84c\ub2e4. \uba3c \ubc14\ub2e4\uc5d0\uc11c \ubb3c\uac74\ub9cc \uc2e4\uc5b4 \uc624\ub294 \ud68c\uc0ac\ub85c \ubcf4\uba74 \uc2dc\uc791\ubd80\ud130 \uc911\uc694\ud55c \ubd80\ubd84\uc774 \ube60\uc9c4\ub2e4. \ub3d9\uc2dc\uc5d0 \ud68c\uc0ac\uc5d0\ub294 \uc2a4\ud398\uc778\ub839 \uc544\uba54\ub9ac\uce74\uc640\uc758 \ubb34\uc5ed\uc5d0 \uad00\ud55c \uae30\ub300\uac00 \ubd99\uc5c8\ub2e4. \uc815\ubd80\uc640 \uad00\uacc4\ub97c \ub9fa\uc740 \uc0ac\uc5c5\uc774\ub77c\ub294 \uc0ac\uc2e4, \ubc14\ub2e4 \uac74\ub108 \ubd80\uc5d0 \ub300\ud55c \uc774\ubbf8\uc9c0\uac00 \ud568\uaed8 \uc774\ub984\uc758 \ubb34\uac8c\ub97c \ud0a4\uc6e0\ub2e4. \uad6d\uac00\uc758 \uc57d\uc18d\uacfc \uc0c1\uc5c5\uc758 \uac00\ub2a5\uc131\uc740 \uc11c\ub85c \ub2e4\ub978 \uac83\uc774\uc5c8\uc9c0\ub9cc \uc0ac\ub78c\ub4e4\uc758 \uae30\ub300 \uc18d\uc5d0\uc11c\ub294 \uac00\uae4c\uc774 \ub193\uc77c \uc218 \uc788\uc5c8\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \uae30\ub300\ud55c \uc790\uc720\ub85c\uc6b4 \ubb34\uc5ed\uacfc \uc2e4\uc81c\ub85c \ud5c8\uc6a9\ub41c \uac70\ub798\uc758 \ubc94\uc704\ub294 \uac19\uc9c0 \uc54a\uc558\ub2e4. \ub9e5\ucf00\uc774\ub294 \uc2a4\ud398\uc778\uacfc\uc758 \ud611\uc0c1 \uacb0\uacfc\uac00 \uc601\uad6d\uc5d0\uc11c \ubd80\ud480\ub824\uc9c4 \uc804\ub9dd\ubcf4\ub2e4 \uc81c\ud55c\uc801\uc774\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud56d\uad6c \uc774\ub984\uc744 \ub298\uc5b4\ub193\ub294 \uac83\uacfc \uadf8\uacf3\uc5d0\uc11c \ub9c8\uc74c\uaecf \uac70\ub798\ud560 \uad8c\ub9ac\ub97c \uc5bb\ub294 \uac83\uc740 \ub2e4\ub978 \uc77c\uc774\uc5c8\ub2e4. \uc774 \uc0ac\uc5c5\uc5d0\ub294 \ub178\uc608\ud654\ub41c \uc544\ud504\ub9ac\uce74\uc778\uc744 \uc2a4\ud398\uc778 \uc2dd\ubbfc\uc9c0\uc5d0 \uacf5\uae09\ud558\ub294 \uc544\uc2dc\uc5d4\ud1a0 \uacc4\uc57d\ub3c4 \ud3ec\ud568\ub418\uc5c8\ub2e4. \uc624\ub798\ub41c \uae08\uc735\uc0ac\ub97c \ud48d\ubd80\ud55c \uc0c1\ud488\uc774 \uc624\uac00\ub294 \ub0ad\ub9cc\uc73c\ub85c\ub9cc \ubcfc \uc218 \uc5c6\ub294 \uc774\uc720\ub2e4. \ub2f9\uc2dc\uc758 \uc774\uc775\uc5d0 \uad00\ud55c \uacc4\uc0b0 \uc548\uc5d0\ub294 \uc0ac\ub78c\uc744 \uac15\uc81c\ub85c \uac70\ub798\ud558\ub294 \uc2dd\ubbfc\uc9c0 \uc9c8\uc11c\ub3c4 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \ud68c\uc0ac\uc758 \uc774\ub984 \ub54c\ubb38\uc5d0 \ud22c\uc790\uc790\ub294 \ub0a8\ubbf8 \ubb34\uc5ed\uc774 \ubc8c\uc5b4\ub2e4 \uc904 \ud070 \uc774\uc775\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \ub9e5\ucf00\uc774\uc758 \uc124\uba85\uc5d0\uc11c \ud68c\uc0ac\uc758 \uae08\uc735\uc801 \ud65c\ub3d9\uacfc \uc815\ubd80\uc5d0\uc11c \ubc1b\ub294 \uc9c0\uae09\uc740 \uc911\uc694\ud55c \ube44\uc911\uc744 \ucc28\uc9c0\ud55c\ub2e4. \ubb34\uc5ed\uc774 \ud06c\uac8c \ubc88\uc131\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub2e4\ub978 \uad6c\uc870\ub85c \uc218\uc785\uc774 \uc0dd\uae38 \uc218 \uc788\uc5c8\ub2e4. \uadf8\ub798\uc11c \ud68c\uc0ac\uac00 \ubb34\uc5c7\uc744 \ud574\uc11c \ub3c8\uc744 \ubc84\ub294\uc9c0\uc640 \uc0ac\ub78c\ub4e4\uc774 \uadf8 \ud68c\uc0ac\uc5d0\uc11c \ubb34\uc5c7\uc744 \uae30\ub300\ud558\ub294\uc9c0\ub97c \ub530\ub85c \ubb3c\uc5b4\uc57c \ud55c\ub2e4. \ub0a8\ud574\ud68c\uc0ac\uc758 \uc5ed\uc0ac\ub294 \ubc14\ub85c \uadf8 \uac04\uaca9\uc774 \ucee4\uc9c8 \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ud654\ub824\ud55c \uc774\ub984\uc774 \uc2e4\uc81c \ud604\uae08\uc758 \ud750\ub984\uc744 \uc815\ud655\ud788 \uc694\uc57d\ud574 \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. 1720\ub144\uc5d0\ub294 \uad6d\uac00 \ubd80\ucc44\ub97c \ud68c\uc0ac \uc8fc\uc2dd\uacfc \uc5f0\uacb0\ud574 \uc804\ud658\ud558\ub294 \ub354 \ud070 \uacc4\ud68d\uc774 \ucd94\uc9c4\ub418\uc5c8\ub2e4. \ucc44\uad8c\uc744 \uac00\uc9c4 \uc0ac\ub78c\uc5d0\uac8c \ud68c\uc0ac\uc758 \uc9c0\ubd84\uc73c\ub85c \uc62e\uae38 \uc120\ud0dd\uc744 \uc81c\uc2dc\ud558\ub294 \uad6c\uc870\uc600\ub2e4. \uc8fc\uac00\uac00 \ub192\uc744\uc218\ub85d \uadf8\ub7f0 \uad50\ud658\uc758 \uc870\uac74\uacfc \ud68c\uc0ac\uc758 \uacc4\ud68d\uc744 \uc720\ub9ac\ud558\uac8c \ub9cc\ub4e4 \uc5ec\uc9c0\uac00 \uc788\uc5c8\ub2e4. \uc774 \ub54c\ubb38\uc5d0 \uc8fc\uc2dd\uc758 \uc778\uae30\uac00 \uc0ac\uc5c5\uc758 \uacb0\uacfc\ub9cc \ub4a4\ub530\ub974\ub294 \uc9c0\ud45c\uac00 \uc544\ub2c8\ub77c \uacc4\ud68d\uc744 \uc6c0\uc9c1\uc774\ub294 \uc870\uac74\uc774 \ub418\uc5c8\ub2e4. \uac00\uaca9\uc774 \uc624\ub974\ub294 \ubaa8\uc2b5\uc744 \ubcf4\uace0 \ub354 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uae30\ub300\ub97c \uac16\uace0, \uadf8 \uae30\ub300\uac00 \ub2e4\uc2dc \uac00\uaca9\uacfc \uc5f0\uacb0\ub418\ub294 \uc21c\ud658\uc774 \uc0dd\uae38 \uc218 \uc788\uc5c8\ub2e4. \ubaa8\ub4e0 \uc138\ubd80\ub97c \ud558\ub098\uc758 \uacc4\uc0b0\uc73c\ub85c \uc904\uc77c \uc218\ub294 \uc5c6\uc9c0\ub9cc \uac00\uaca9\uc758 \uc5ed\ud560\uc774 \ucee4\uc84c\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uc8fc\uc2dd\uac12\uc774 \uc624\ub974\uba74 \uc774\ubbf8 \uc0b0 \uc0ac\ub78c\uc758 \uc774\uc775\uc774 \ub208\uc5d0 \ubcf4\uc778\ub2e4. \uc55e\uc73c\ub85c \ubb34\uc2a8 \uc77c\uc774 \uc0dd\uae38\uc9c0 \ud310\ub2e8\ud558\uae30\ubcf4\ub2e4 \uc9c0\uae08 \ub0a8\ub4e4\uc774 \uc5bb\uc740 \uc774\uc775\uc744 \ub193\uce58\uc9c0 \uc54a\ub294 \uc77c\uc774 \uae09\ud574\uc9c8 \uc218 \uc788\ub2e4. \ub9e5\ucf00\uc774\ub294 \ub2f9\uc2dc \ub7f0\ub358\uc758 \ud22c\uc790 \uc5f4\uae30\ub97c \ub9e4\uc6b0 \uadf9\uc801\uc778 \ubb38\uc7a5\uc73c\ub85c \ubb18\uc0ac\ud55c\ub2e4. \ub2e4\ub9cc \uadf8\uc758 \ucc45\uc740 \uc0ac\uac74\uc774 \ubc8c\uc5b4\uc9c4 \uc9c0 \ud55c\ucc38 \ub4a4 \uc4f0\uc600\ub2e4. \ubaa8\ub4e0 \uc2dc\ubbfc\uc774 \uac19\uc740 \uc695\ub9dd\uc5d0 \uc0ac\ub85c\uc7a1\ud614\ub2e4\uace0 \ubc1b\uc544\ub4e4\uc774\uac70\ub098, \ucc45\uc5d0 \ub098\uc624\ub294 \ud669\ub2f9\ud55c \ud22c\uc790 \uc77c\ud654\ub97c \uc804\ubd80 \uc2e4\uc81c \uacc4\uc57d\uc758 \uae30\ub85d\uc73c\ub85c \ucde8\uae09\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc720\uba85\ud55c \uc775\uba85 \uc77c\ud654\ubcf4\ub2e4 \ub0a8\ud574\ud68c\uc0ac\uc758 \uad6c\uc870\uc640 1720\ub144\uc758 \ubcc0\ud654\uc5d0 \uc9d1\uc911\ud55c\ub2e4. 1720\ub144 \uc8fc\uac00\ub294 \ud06c\uac8c \uc62c\ub790\uc9c0\ub9cc \uc5ec\ub984 \uc774\ud6c4 \ud558\ub77d\ud588\uace0, \uac00\uc744\uc5d0\ub294 \uc2e0\ub8b0\ub97c \ubd99\uc7a1\uae30 \uc704\ud55c \uc2dc\ub3c4\uc640 \ubd88\uc548\uc774 \ucee4\uc84c\ub2e4. \uae30\ub300\ud558\ub358 \uc0c1\uc2b9\uc774 \uba48\ucd94\uba74 \uac19\uc740 \uc57d\uc18d\ub3c4 \ub2e4\ub978 \ub208\uc73c\ub85c \ubcf4\uc774\uae30 \uc2dc\uc791\ud55c\ub2e4. \ub098\uc911\uc5d0 \ub204\uac00 \uc0ac \uc904\uc9c0\uc5d0 \ub300\ud55c \ubbff\uc74c\uc774 \ud754\ub4e4\ub9ac\uba74 \uac00\uaca9\uc744 \uc9c0\ud0f1\ud558\ub358 \uad00\uacc4\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc0ac\uac74 \ub4a4\uc5d0\ub294 \uc758\ud68c\uc758 \uc870\uc0ac\uc640 \ucc45\uc784\uc744 \ubb3b\ub294 \uacfc\uc815\uc774 \uc774\uc5b4\uc84c\ub2e4. \ub2e4\ub9cc \uc774\ub97c \uc601\uad6d \uae08\uc735 \uc804\uccb4\uac00 \ud55c\ub0a0\uc5d0 \uc0ac\ub77c\uc9c4 \uc77c\ub85c \uacfc\uc7a5\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud68c\uc0ac\uc758 \uc0ac\uc5c5\uacfc \ubd80\ucc44 \ucc98\ub9ac, \uc190\uc2e4\uacfc \uc81c\ub3c4\uc758 \ub300\uc751\uc740 \uc0ac\uac74 \ub4a4\uc5d0\ub3c4 \uc774\uc5b4\uc84c\ub2e4. \uac70\ud488\uc758 \ub05d\uc740 \uc5ed\uc0ac \uc790\uccb4\uc758 \ub05d\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \ub9e5\ucf00\uc774\uc758 1852\ub144\ud310 \ucc45\uc5d0 \uc218\ub85d\ub41c \ud638\uac00\uc2a4\uc758 \ub0a8\ud574\ud68c\uc0ac \ud48d\uc790 \ub3c4\ud310\uc774\ub2e4. \uc911\uc559\uc5d0\ub294 \uc0ac\ub78c\ub4e4\uc774 \ube59\uae00\ub3c4\ub294 \uae30\uad6c\ub97c \ud0c0\uace0 \uc788\uace0, \uadf8 \uc544\ub798\ub85c \ub9ce\uc740 \uc778\ubb3c\uc774 \ubaa8\uc600\ub2e4. \ud654\uac00\ub294 \uae08\uc735\uc758 \uc5f4\uae30\ub97c \uc775\uc0b4\uc2a4\ub7fd\uace0 \ud63c\ub780\uc2a4\ub7ec\uc6b4 \uc7a5\uba74\uc73c\ub85c \ud45c\ud604\ud55c\ub2e4. \uc774 \uadf8\ub9bc\uc740 \ub2f9\uc2dc \uac70\ub9ac\uc758 \ubaa8\ub4e0 \uc0ac\ub78c\uc744 \uadf8\ub300\ub85c \uae30\ub85d\ud55c \uc0ac\uc9c4\uc774 \uc544\ub2c8\ub2e4. \ube44\ud310\uacfc \uc0c1\uc9d5\uc744 \ub2f4\uc740 \ud48d\uc790\ub2e4. \ub204\uac00 \ubb34\uc5c7\uc744 \uc6b0\uc2a4\uaf5d\uc2a4\ub7fd\uac8c \ubcf4\uc774\uac8c \ud588\ub294\uc9c0 \uc0b4\ud53c\uba74, \uae08\uc735 \uc0ac\uac74\uc774 \uc22b\uc790\uc758 \uc190\uc2e4\ubfd0 \uc544\ub2c8\ub77c \uc0ac\ud68c\uac00 \uc790\uc2e0\uc744 \ub3cc\uc544\ubcf4\ub294 \ubb38\ud654\uc801 \uc18c\uc7ac\uac00 \ub418\uc5c8\uc74c\ub3c4 \uc54c \uc218 \uc788\ub2e4. \ub0a8\ud574\ud68c\uc0ac \uc0ac\uac74\uc744 \ubaa8\ub450\uac00 \uc5b4\ub9ac\uc11d\uc5c8\ub2e4\ub294 \uad50\ud6c8\uc73c\ub85c\ub9cc \uc77d\uc73c\uba74 \uad6d\uac00 \ubd80\ucc44\uc640 \ubb34\uc5ed \uad8c\ub9ac, \uc8fc\uc2dd \uc804\ud658\uc774\ub77c\ub294 \uad6c\uccb4\uc801\uc778 \uad6c\uc870\uac00 \uc0ac\ub77c\uc9c4\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \uc544\ubb34 \uc774\uc57c\uae30\uc5d0\ub3c4 \ubc18\uc751\ud55c \uac83\uc774 \uc544\ub2c8\ub77c \uad8c\ub825\uacfc \ubd80\uc758 \uc774\ubbf8\uc9c0\uac00 \uacb0\ud569\ub41c \uc57d\uc18d\uc744 \ubcf4\uace0 \uc788\uc5c8\ub2e4. \uc774 \uc624\ub798\ub41c \uc0ac\uac74\uc744 \uc77d\ub294 \uc990\uac70\uc6c0\uc740 \uc624\ub298\uc758 \uc2dc\uc7a5\uc744 \uadf8\ub300\ub85c \ub9de\ud790 \ube44\ubc95\uc744 \uc5bb\ub294 \ub370 \uc788\uc9c0 \uc54a\ub2e4. \uc5b4\ub5a4 \uc0ac\uc5c5\uc758 \uc774\ub984\uacfc \uc2e4\uc81c \uc218\uc785, \ubbf8\ub798\uc5d0 \ub300\ud55c \uae30\ub300\uac00 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0\ub97c \uc54c\uc544\ubcf4\ub294 \ub370 \uc788\ub2e4. \ub0a8\ud574\ub77c\ub294 \uba3c \ubc14\ub2e4\uc758 \uc774\ub984\uc740 \ub7f0\ub358 \ud55c\ubcf5\ud310\uc5d0\uc11c \ub3c8\uc758 \uac12\uc774 \ub418\uc5c8\uace0, \uadf8 \uac04\uaca9\uc740 \uc9c0\uae08\ub3c4 \ud765\ubbf8\ub85c\uc6b4 \uae08\uc735\uc0ac\uc758 \uc9c8\ubb38\uc73c\ub85c \ub0a8\uc544 \uc788\ub2e4."}, {"id": "troy-ounce-weight", "title": "\uae08 \ud55c \uc628\uc2a4\uc640 \ubcf4\ud1b5 \ud55c \uc628\uc2a4\ub294 \ubb34\uac8c\uac00 \ub2e4\ub974\ub2e4", "summary": "\uac19\uc740 \uc628\uc2a4\ub77c\ub294 \ub9d0 \ub4a4\uc5d0\ub3c4 \ub2e4\ub978 \uae30\uc900\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uae08\uc18d\uc758 \ubb34\uac8c\ub97c \uc77d\uc744 \ub54c \ucc59\uae38 \uc791\uc740 \ucc28\uc774\uc785\ub2c8\ub2e4.", "category": "finance", "category_title": "\ub3c8\uacfc \uae08\uc735", "subcategory": "\ub3c8\uacfc \ud654\ud3d0", "categories": ["finance"], "url": "stories/troy-ounce-weight/index.html", "image": "../media/troy-ounce-weight.jpg", "alt": "\uc22b\uc790\ub098 \uc0c1\ud45c\uac00 \uc5c6\ub294 \uae08\ube5b \ub9c9\ub300\uc640 \uc800\uc6b8, \ucd94\ub97c \uadf8\ub9b0 \uc124\uba85\uc6a9 AI \uc0bd\ud654", "text": "\uae08 \ud55c \uc628\uc2a4\uc640 \ubcf4\ud1b5 \ud55c \uc628\uc2a4\ub294 \ubb34\uac8c\uac00 \ub2e4\ub974\ub2e4 \uadc0\uae08\uc18d\uc5d0\uc11c \ub9cc\ub098\ub294 \ud2b8\ub85c\uc774\uc628\uc2a4 \uc774\uc57c\uae30 \uac19\uc740 \uc628\uc2a4\ub77c\ub294 \ub9d0 \ub4a4\uc5d0\ub3c4 \ub2e4\ub978 \uae30\uc900\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uae08\uc18d\uc758 \ubb34\uac8c\ub97c \uc77d\uc744 \ub54c \ucc59\uae38 \uc791\uc740 \ucc28\uc774\uc785\ub2c8\ub2e4. \ub3c8\uacfc \ud654\ud3d0 \ub3c8\uacfc \uae08\uc735 \uae08\uc774\ub098 \uc740\uc758 \ubb34\uac8c\ub97c \uc124\uba85\ud558\ub294 \uae00\uc5d0\uc11c\ub294 \uc628\uc2a4\ub77c\ub294 \ub2e8\uc704\ub97c \uc790\uc8fc \ub9cc\ub09c\ub2e4. \ub2e4\ub978 \ubb3c\uac74\uc758 \ubb34\uac8c\uc5d0\uc11c\ub3c4 \ubcf8 \uc774\ub984\uc774\ub77c \uc775\uc219\ud558\uac8c \uc9c0\ub098\uce58\uae30 \uc27d\ub2e4. \uadf8\ub7f0\ub370 \uc5ec\uae30\uc5d0\ub294 \ud55c \uac00\uc9c0 \ud655\uc778\ud560 \uac83\uc774 \uc788\ub2e4. \uadc0\uae08\uc18d\uc5d0 \ud754\ud788 \uc4f0\ub294 \ud2b8\ub85c\uc774\uc628\uc2a4\ub294 \uc77c\ubc18\uc801\uc778 \uc628\uc2a4\uc640 \ubb34\uac8c\uac00 \ub2e4\ub974\ub2e4. \uac19\uc740 \uc774\ub984\uc758 \ub4b7\ubd80\ubd84\ub9cc \ubcf4\uace0 \uac19\uc740 \uc591\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \ucc28\uc774\uac00 \uc0dd\uae34\ub2e4. \uc601\uad6d \uc655\ub9bd\uc870\ud3d0\uad6d\uc740 \uae08\uacfc \uc740 \uac19\uc740 \uadc0\uae08\uc18d\uc774 \ubcf4\ud1b5 \ud2b8\ub85c\uc774\uc628\uc2a4\ub85c \uce21\uc815\ub41c\ub2e4\uace0 \uc548\ub0b4\ud55c\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\uc758 \uc124\uba85\uc5d0\uc11c \ud55c \ud2b8\ub85c\uc774\uc628\uc2a4\ub294 31.1035\uadf8\ub7a8\uc774\ub2e4. \ubcf4\ud1b5 \uc628\uc2a4\ub77c\uace0 \ubd80\ub974\ub294 \uc544\ubcf4\uc544\ub4c0\ud3ec\uc544 \uc628\uc2a4\ub294 \uc57d 28.35\uadf8\ub7a8\uc774\ub2e4. \uc18c\uc218\uc810 \uc544\ub798\ub97c \ubaa8\ub450 \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc55e\ucabd\uc740 \uc57d 31.1\uadf8\ub7a8\uc774\ub77c\ub294 \uc815\ub3c4\ub9cc \uae30\uc5b5\ud574\ub3c4 \ub458\uc774 \ub2e4\ub974\ub2e4\ub294 \uac83\uc744 \uc54c \uc218 \uc788\ub2e4. \ub450 \uc218\ub97c \ub098\ub780\ud788 \ub193\uc73c\uba74 \ud2b8\ub85c\uc774\uc628\uc2a4 \ucabd\uc774 \uc870\uae08 \ub354 \ubb34\uac81\ub2e4. \uc628\uc2a4\ub77c\ub294 \ub2e8\uc5b4\uac00 \uac19\ub2e4\uace0 \ud574\uc11c \uc800\uc6b8\uc5d0 \uc62c\ub77c\uac00\ub294 \uc591\ub3c4 \ub611\uac19\uc9c0\ub294 \uc54a\uc740 \uac83\uc774\ub2e4. \ubb3c\ub860 \uc5b4\ub5a4 \uc0c1\ud488\uc774\ub098 \ubb38\uc11c\uac00 \uc2e4\uc81c\ub85c \uc5b4\ub290 \uae30\uc900\uc744 \uc0ac\uc6a9\ud558\ub294\uc9c0\ub294 \ud45c\uc2dc\ub97c \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uadc0\uae08\uc18d\uc774\uba74 \uc124\uba85 \uc5c6\uc774 \ubb34\uc870\uac74 \uac19\uc740 \uc870\uac74\uc774\ub77c\uace0 \ub118\uaca8\uc9da\uae30\ubcf4\ub2e4, \ub2e8\uc704\uc758 \uc774\ub984\uc744 \ub05d\uae4c\uc9c0 \ubcf4\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \ubb3c\uac74\uc758 \uc591\uc744 \ube44\uad50\ud560 \ub54c \uc22b\uc790\uac00 \ud06c\uac8c \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uadf8\ub7ec\ub098 \uc22b\uc790\ub294 \ub2e8\uc704\uc640 \ud568\uaed8 \uc77d\uc5b4\uc57c \ud55c\ub2e4. 1\uc774\ub77c\ub294 \uc218\uac00 \uac19\uc544\ub3c4 \ubb34\uc5c7\uc744 \ud558\ub098\ub85c \uc138\ub294\uc9c0\uac00 \ub2e4\ub974\uba74 \uc591\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ud2b8\ub85c\uc774\uc628\uc2a4\ub294 \uc774\ub7f0 \ucc28\uc774\ub97c \ubcf4\uc5ec\uc8fc\ub294 \uc775\uc219\ud558\uc9c0 \uc54a\uc740 \uc608\ub2e4. \ud3c9\uc18c \uadf8\ub7a8\uc5d0 \uc775\uc219\ud55c \uc0ac\ub78c\uc740 \uc628\uc2a4\ub07c\ub9ac \uba3c\uc800 \ube44\uad50\ud558\uae30\ubcf4\ub2e4 \uadf8\ub7a8\uc73c\ub85c \ud480\uc5b4 \ubcf4\uba74 \uc774\ud574\uac00 \uc26c\uc6cc\uc9c4\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\ub3c4 \uadc0\uae08\uc18d \uac00\uaca9\uc774\ub098 \uc0c1\ud488\uc5d0\uc11c \uc628\uc2a4\ub97c \ub9d0\ud560 \ub54c \ubcf4\ud1b5 \ud2b8\ub85c\uc774\uc628\uc2a4\ub97c \ub73b\ud55c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc774 \ub9d0\uc740 \uac00\uaca9 \uc804\ub9dd\uc774 \uc544\ub2c8\ub77c \ud45c\uc2dc\ub97c \uc77d\ub294 \ubc29\ubc95\uc5d0 \uad00\ud55c \uc548\ub0b4\ub2e4. \ubb34\uac8c\ub97c \uc548\ub2e4\uace0 \uac00\uce58\uc758 \ubcc0\ud654\uae4c\uc9c0 \uc54c \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. 1\uc628\uc2a4\ub77c\ub294 \ud45c\uc2dc\uac00 \ub458 \ub098\ub780\ud788 \uc788\uc5b4\ub3c4 \uae30\uc900\uc774 \ub2e4\ub974\uba74 \uac19\uc740 \uc591\uc774\ub77c\uace0 \ud560 \uc218\ub294 \uc5c6\ub2e4. \uc22b\uc790\ub294 \ub2e8\uc704\uac00 \uc815\ud55c \ubb36\uc74c\uc758 \uac1c\uc218\ub97c \ub9d0\ud55c\ub2e4. \uae08\uc18d\uc744 \uc0ac\uac70\ub098 \uc790\ub8cc\ub97c \uc77d\uc744 \ub54c\uc5d0\ub294 \uc22b\uc790 \uc55e\ub4a4\uc758 \uc791\uc740 \uae00\uc790\ub97c \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ub2e8\uc704 \uc774\ub984\uc774 \ube44\uc2b7\ud558\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \ube44\uad50\ub97c \uc2dc\uc791\ud558\uba74 \uacc4\uc0b0\uc744 \uc815\ud655\ud788 \ud574\ub3c4 \ucc98\uc74c\uc758 \uc591\uc744 \uc798\ubabb \uc7a1\uc744 \uc218 \uc788\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \ub450 \ud2b8\ub85c\uc774\uc628\uc2a4\ub294 \uc774 \uae00\uc758 \uae30\uc900\uc73c\ub85c \uc57d 62.207\uadf8\ub7a8\uc774\uace0, \ubcf4\ud1b5 \uc628\uc2a4 \ub450 \uac1c\ub294 \uc57d 56.70\uadf8\ub7a8\uc774\ub2e4. \ub458 \ub2e4 2\ub77c\uace0 \uc801\ud600 \uc788\uc9c0\ub9cc \uc2e4\uc81c \ube44\uad50\ud560 \ubb34\uac8c\ub294 \ub2e4\ub974\ub2e4. \uc774\uac83\uc740 \uc0c1\ud488 \uac00\uaca9\uc758 \uc608\uce21\uc774 \uc544\ub2c8\ub77c \uac19\uc740 \ub2e8\uc5b4 \uc548\uc758 \ub450 \uae30\uc900\uc744 \ud480\uc5b4 \uc4f4 \uacc4\uc0b0\uc774\ub2e4. \uc775\uc219\ud55c \uadf8\ub7a8\uc73c\ub85c \uc62e\uae30\uba74 \ucc28\uc774\uac00 \uc870\uae08 \ub354 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uae08\uc18d \ubb3c\uac74\uc758 \uc804\uccb4 \ubb34\uac8c\ub97c \uc548\ub2e4\uace0 \uadf8 \uc548\uc5d0 \ub4e4\uc5b4 \uc788\ub294 \ud2b9\uc815 \uadc0\uae08\uc18d\uc758 \uc591\uc744 \ubaa8\ub450 \uc548 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc774 \uc11e\uc5ec \uc788\ub294\uc9c0\uc640 \uc5bc\ub9c8\ub098 \uc788\ub294\uc9c0\ub294 \ubcc4\ub3c4\uc758 \uc815\ubcf4\ub2e4. \ub2e8\uc704\ub97c \uc77d\ub294 \uc77c\uc774 \uc911\uc694\ud55c \uccab \ub2e8\uacc4\ub77c\uace0 \ud574\ub3c4 \uadf8\uac83\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc0c1\ud488 \uc124\uba85\uc744 \ub300\uc2e0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ubb34\uac8c\ub97c \ub098\ud0c0\ub0b8 \uc22b\uc790\uc640 \uc7ac\ub8cc\uc758 \uc131\uc9c8\uc744 \ub098\ud0c0\ub0b8 \ub9d0\uc744 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \ud2b9\uc815 \uc0c1\ud488\uc758 \uc21c\ub3c4\ub97c \uacc4\uc0b0\ud558\uac70\ub098 \ub9e4\uc785 \uac00\uce58\ub97c \ud3c9\uac00\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub2e4\ub9cc \uc124\uba85\ubb38\uc5d0\uc11c \ubb34\uac8c\ub77c\ub294 \ud56d\ubaa9\uc774 \ub9e1\ub294 \uc5ed\ud560\uc744 \ubd84\uba85\ud788 \ud574 \ub454\ub2e4. \ud558\ub098\uc758 \uc22b\uc790\uc5d0 \uc7ac\ub8cc\uc640 \uac00\uaca9, \uac00\uce58\uae4c\uc9c0 \ud55c\uaebc\ubc88\uc5d0 \ub2f4\uaca8 \uc788\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\uc73c\uba74 \uad11\uace0\uc640 \uc790\ub8cc\ub97c \ub354 \ucc28\ubd84\ud558\uac8c \uc77d\uc744 \uc218 \uc788\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc9c8\ubb38\uc5d0 \uc11c\ub85c \ub2e4\ub978 \uc815\ubcf4\uac00 \ud544\uc694\ud558\ub2e4\ub294 \uc810\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc0ac\ub840\ub2e4. \uadf8\ub7a8\uc5d0 \uc775\uc219\ud55c \uc0ac\ub78c\uc5d0\uac8c \uc628\uc2a4\ub294 \ub0af\uc124 \uc218 \uc788\uc9c0\ub9cc, \uc624\ub798 \uc0ac\uc6a9\ud55c \ubd84\uc57c\uc5d0\uc11c\ub294 \uadf8 \ub2e8\uc704\uac00 \uac70\ub798\uc640 \uae30\ub85d\uc744 \uc774\uc5b4 \uc8fc\ub294 \uc5ed\ud560\uc744 \ud55c\ub2e4. \ubaa8\ub4e0 \uc790\ub8cc\ub97c \uc989\uc2dc \ub2e4\ub978 \ub2e8\uc704\ub85c \ubc14\uafb8\uc5b4 \uc4f0\uae30\ubcf4\ub2e4 \uc6d0\ub798\uc758 \ud45c\uc2dc\ub97c \ud568\uaed8 \ub0a8\uaca8 \ub450\ub294 \uc774\uc720\ub3c4 \uc788\ub2e4. \ub098\uc911\uc5d0 \ub2e4\ub978 \uae30\ub85d\uacfc \ube44\uad50\ud560 \ub54c \ubb34\uc5c7\uc744 \uae30\uc900\uc73c\ub85c \uc801\uc5c8\ub294\uc9c0 \uc54c\uc544\uc57c \ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \ubcc0\ud658\uac12\uc5d0\ub294 \ubc18\uc62c\ub9bc\ub3c4 \uc788\ub2e4. \uc774 \uae00\uc5d0\uc11c \uc0ac\uc6a9\ud558\ub294 31.1035\uc640 \uc57d 28.35\ub294 \uc774\ud574\ub97c \ub3d5\ub294 \ud45c\uae30\uc774\ubbc0\ub85c, \ub9e4\uc6b0 \uc815\ubc00\ud55c \uce21\uc815\uacfc \uac70\ub798\uc5d0\ub294 \ud574\ub2f9 \ubb38\uc11c\uc758 \uc815\ud655\ud55c \uae30\uc900\uc744 \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uc6d0\ub9ac\ub97c \uc544\ub294 \uc77c\uacfc \uc2e4\uc81c \uc5c5\ubb34\uc5d0 \ud544\uc694\ud55c \uc790\ub9bf\uc218\ub97c \uacb0\uc815\ud558\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uc77c\uc0c1\uc801\uc778 \ube44\uad50\uc5d0\uc11c\ub294 \ub450 \uc628\uc2a4\uac00 \uac19\uc9c0 \uc54a\ub2e4\ub294 \uad6c\ubd84\ubd80\ud130 \ucc59\uae30\uba74 \ucda9\ubd84\ud558\ub2e4. \uac00\uaca9\uc774 \uc624\ub974\uace0 \ub0b4\ub9ac\ub294 \uc774\uc57c\uae30\ub294 \ub208\uae38\uc744 \ub04c\uc9c0\ub9cc, \ubb34\uc5c7\uc758 \uac00\uaca9\uc778\uc9c0\ub97c \uc54c\uc544\ubcf4\ub294 \uac83\uc740 \ub354 \uae30\ubcf8\uc801\uc778 \uc9c8\ubb38\uc774\ub2e4. \uc628\uc2a4\ub2f9\uc774\ub77c\ub294 \ud45c\ud604\uc744 \ub9cc\ub098\uba74 \uc5b4\ub290 \uc628\uc2a4\ub97c \ub9d0\ud558\ub294\uc9c0 \uba3c\uc800 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ub2e8\uc704\uc758 \ucc28\uc774\ub97c \uc548\ub2e4\uace0 \uc2dc\uc7a5\uc744 \uc608\uce21\ud560 \uc218\ub294 \uc5c6\uc9c0\ub9cc \ube44\uad50\uc758 \ucd9c\ubc1c\uc810\uc774 \ud754\ub4e4\ub9ac\ub294 \uc77c\uc744 \uc904\uc77c \uc218\ub294 \uc788\ub2e4. \uc800\uc6b8 \uc704\uc758 \ubb3c\uac74\uc740 \ud558\ub098\uc778\ub370 \uc774\ub984\uc744 \ubd99\uc774\ub294 \ubc29\uc2dd\uc5d0 \ub530\ub77c \uc22b\uc790\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc22b\uc790\uac00 \ub2ec\ub77c\uc84c\ub2e4\uace0 \ubb3c\uac74 \uc790\uccb4\uac00 \ubc14\ub010 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc790\ub8cc\uc640 \uc0c1\ud488\uc744 \uc77d\uc744 \ub54c \uc218\uc640 \ub2e8\uc704\ub97c \ud55c \ub369\uc5b4\ub9ac\ub85c \ubcf4\ub294 \uc2b5\uad00\uc740 \uc774 \uc791\uc740 \uc0ac\ub840 \ubc16\uc5d0\uc11c\ub3c4 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uae08\uc18d\uc758 \ubc18\uc9dd\uc784 \ub4a4\uc5d0\uc11c, \uc0ac\ub78c\ub4e4\uc774 \uc591\uc744 \ud568\uaed8 \uc774\ud574\ud558\uae30 \uc704\ud574 \uc815\ud55c \uc57d\uc18d\uc774 \ubcf4\uc778\ub2e4. \uae08\uc18d\uc744 \uc9c1\uc811 \uac70\ub798\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc774\ub7f0 \ub2e8\uc704\ub294 \ub274\uc2a4\uc640 \uc804\uc2dc \uc124\uba85\uc5d0\uc11c \ub9cc\ub09c\ub2e4. \uadf8\ub54c \ub0af\uc120 \ub9d0\uc744 \ubaa8\ub450 \uacf5\ubd80\ud558\ub824\uace0 \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uac19\uc740 \uc628\uc2a4\uc5d0\ub3c4 \ub2e4\ub978 \uae30\uc900\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc \ucc59\uaca8 \ub450\uba74 \ub41c\ub2e4. \uc5ec\ud589\uc9c0\uc5d0\uc11c \uc11c\ub85c \ub2e4\ub978 \ud06c\uae30\uc758 \ucef5\uc744 \ubaa8\ub450 \ud55c \uc794\uc774\ub77c\uace0 \ubd80\ub974\ub294 \uc0c1\ud669\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc774\ub984\uc744 \ub9de\ucd94\ub294 \uac83\uacfc \uc2e4\uc81c \uc591\uc744 \ub9de\ucd94\ub294 \uac83\uc740 \ubcc4\uac1c\uc758 \uc77c\uc774\ub2e4. \ub2e8\uc704\uc758 \uae30\uc900\uc740 \uadf8 \ucc28\uc774\ub97c \ubd84\uba85\ud788 \ud558\ub824\uace0 \ud544\uc694\ud558\ub2e4. \ub2e4\uc74c\uc5d0 \uae08 \ud55c \uc628\uc2a4\ub77c\ub294 \ud45c\ud604\uc744 \ub9cc\ub098\uba74 \uc22b\uc790 1 \uc606\uc758 \ub9d0\uc744 \uc7a0\uae50 \uc0b4\ud3b4\ubcf4\uc790. \uc791\uc740 \ub2e8\uc704\uc758 \uc774\ub984\uc774, \uc0dd\uac01\ubcf4\ub2e4 \uc911\uc694\ud55c \ubb34\uac8c\ub97c \uac00\uc9c0\uace0 \uc788\ub2e4."}, {"id": "virginia-company-shares-and-colony", "title": "\ubc84\uc9c0\ub2c8\uc544 \ud68c\uc0ac \u2014 \uc2e0\ub300\ub959\uc758 \uafc8\uc744 \uc8fc\uc2dd\uc73c\ub85c \ud314\ub2e4", "summary": "1606\ub144\uc758 \ud68c\uc0ac\uc640 1607\ub144\uc758 \uc2dd\ubbfc\uc9c0\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uacf5\ub3d9 \ud22c\uc790\u00b7\ud669\uae08\uc758 \uae30\ub300\u00b7\ub2f4\ubc30\uc640 \ub178\ub3d9\uc758 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "finance", "category_title": "\ub3c8\uacfc \uae08\uc735", "subcategory": "\ud22c\uc790\uc640 \uc2dc\uc7a5", "categories": ["finance"], "url": "stories/virginia-company-shares-and-colony/index.html", "image": "../media/virginia-company-shares-and-colony.png", "alt": "17\uc138\uae30 \ucd08 \uc0c1\uc778\ub4e4\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc0ac\ub78c\ub4e4\uc774 \ud56d\uad6c\uac00 \ubcf4\uc774\ub294 \ubc29\uc5d0\uc11c \uc11c\ub958\ub97c \uc758\ub17c\ud558\ub294 \uc0bd\ud654.", "text": "\ubc84\uc9c0\ub2c8\uc544 \ud68c\uc0ac \u2014 \uc2e0\ub300\ub959\uc758 \uafc8\uc744 \uc8fc\uc2dd\uc73c\ub85c \ud314\ub2e4 \ub7f0\ub358\uc758 \ud22c\uc790\uae08\uc774 \uc81c\uc784\uc2a4\ud0c0\uc6b4\uc758 \uc0dd\ud65c\uacfc \ub9cc\ub0ac\uc744 \ub54c 1606\ub144\uc758 \ud68c\uc0ac\uc640 1607\ub144\uc758 \uc2dd\ubbfc\uc9c0\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uacf5\ub3d9 \ud22c\uc790\u00b7\ud669\uae08\uc758 \uae30\ub300\u00b7\ub2f4\ubc30\uc640 \ub178\ub3d9\uc758 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ud22c\uc790\uc640 \uc2dc\uc7a5 \ub3c8\uacfc \uae08\uc735 \ubc30\ub97c \ubcf4\ub0b4\uace0 \uc0ac\ub78c\uc744 \uc774\uc8fc\uc2dc\ud0a4\uba70 \ub0af\uc120 \ub545\uc5d0 \uac70\uc810\uc744 \uc138\uc6b0\ub824\uba74 \ud070\ub3c8\uc774 \ub4e4\uc5c8\ub2e4. \uc655\uc774 \ubaa8\ub4e0 \ube44\uc6a9\uc744 \uc9c1\uc811 \ub9c8\ub828\ud558\ub294 \ub300\uc2e0 \uc5ec\ub7ec \ud22c\uc790\uc790\uac00 \ub3c8\uc744 \ubaa8\uc740\ub2e4\uba74 \uc5b4\ub5a8\uae4c. 17\uc138\uae30 \ucd08 \uc601\uad6d\uc758 \uc2dd\ubbfc \uc0ac\uc5c5\uc5d0\ub294 \uc774\ub7f0 \uacf5\ub3d9 \ud22c\uc790\uc758 \ubc29\uc2dd\uc774 \uae4a\uc774 \ub4e4\uc5b4\uac14\ub2e4. \ubc84\uc9c0\ub2c8\uc544 \ud68c\uc0ac\uc758 \uc774\uc57c\uae30\ub294 \uc8fc\uc2dd\uc758 \uc5ed\uc0ac\uac00 \uac70\ub798\uc18c \uc548\uc5d0\uc11c\ub9cc \uc2dc\uc791\ub418\uc9c0 \uc54a\uc558\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub7f0\ub358\uc5d0\uc11c \uae30\ub300\ud55c \uc218\uc775\uacfc \ub300\uc11c\uc591 \uac74\ub108\uc5d0\uc11c \uc2e4\uc81c\ub85c \uc0b4\uc544\ub0a8\uc544\uc57c \ud588\ub358 \uc0ac\ub78c\ub4e4\uc758 \uc0ac\uc815\uc740 \uac19\uc740 \uacc4\ud68d \uc548\uc5d0 \uc788\uc5c8\uc9c0\ub9cc \uac19\uc740 \uacbd\ud5d8\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uad50\uc7ac\ub294 \uacf5\ub3d9 \ucd9c\uc790 \ud68c\uc0ac\uac00 \ud22c\uc790\uc790\uc5d0\uac8c \uc9c0\ubd84\uc744 \ud314\uc544 \uc790\uae08\uc744 \ubaa8\uc73c\uace0 \uc0ac\uc5c5\uc744 \uc218\ud589\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud55c \uc0ac\ub78c\uc774 \ubc30\uc640 \uc0ac\ub78c, \ubb3c\uc790\uc758 \ube44\uc6a9\uc744 \ubaa8\ub450 \ubd80\ub2f4\ud558\ub294 \ubc29\uc2dd\uacfc\ub294 \ub2e4\ub974\ub2e4. \ud22c\uc790\uc790\ub294 \uc790\uc2e0\uc774 \ucc38\uc5ec\ud55c \uc0ac\uc5c5\uc774 \uc798\ub418\uba74 \uadf8 \uacb0\uacfc\ub97c \ub098\ub204\uc5b4 \ubc1b\uc744 \uc218 \uc788\ub2e4\ub294 \uae30\ub300\ub97c \uac00\uc84c\ub2e4. \uc774 \uc2dc\uae30\uc758 \ud68c\uc0ac\ub97c \uc624\ub298\uc758 \uc8fc\uc2dd\ud68c\uc0ac\uc640 \ubaa8\ub4e0 \ubc95\ub960 \uc870\uac74\uc774 \uac19\uc740 \uac83\uc73c\ub85c \ubcfc \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uba40\ub9ac \uc788\ub294 \uc0ac\uc5c5\uc758 \ube44\uc6a9\uc744 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \ub3c8\uc73c\ub85c \ubaa8\uc740\ub2e4\ub294 \uad6c\uc0c1\uc740 \ubd84\uba85\ud558\ub2e4. \uc8fc\uc2dd\uc774\ub77c\ub294 \ub9d0 \ub4a4\uc5d0\ub294 \uc774\ubbf8 \ubc30\uac00 \ub5a0\ub098\uae30 \uc804\ubd80\ud130 \ub9ce\uc740 \uc0ac\ub78c\uc758 \uae30\ub300\ub97c \uc5f0\uacb0\ud558\ub294 \uc7a5\uce58\uac00 \uc788\uc5c8\ub2e4. \ubc84\uc9c0\ub2c8\uc544 \ud68c\uc0ac\ub294 1606\ub144 \uc655\uc2e4\uc758 \ud5c8\uac00\ub97c \ubc1b\uc558\ub2e4. \uc774\ub4ec\ud574 \uc774\uc8fc\ubbfc\ub4e4\uc740 \uc624\ub298\ub0a0 \ubbf8\uad6d \ubc84\uc9c0\ub2c8\uc544\uc758 \uccb4\uc11c\ud53c\ud06c\ub9cc \uc9c0\uc5ed\uc5d0 \uc81c\uc784\uc2a4\ud0c0\uc6b4\uc744 \uc138\uc6e0\ub2e4. \uc0c8 \uad6d\uc655 \uc81c\uc784\uc2a4 1\uc138\uc758 \uc774\ub984\uc774 \uc815\ucc29\uc9c0\uc5d0 \ubd99\uc5c8\ub2e4. \ud68c\uc0ac\uc758 \uc790\uae08\uacfc \uc655\uc2e4\uc758 \uad8c\ud55c\uc774 \ub300\uc11c\uc591 \uac74\ub108\uc758 \uc7a5\uc18c\uc5d0\uc11c \ub9cc\ub09c \uac83\uc774\ub2e4. \uadf8 \ub545\uc740 \uc0ac\ub78c\uc774 \uc5c6\ub358 \ube48 \uacf5\uac04\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ud3ec\uc6b0\ud558\ud0c4\uc744 \ube44\ub86f\ud55c \uc6d0\uc8fc\ubbfc \uacf5\ub3d9\uccb4\uc758 \uc0dd\ud65c\uacfc \uad00\uacc4\uac00 \uc788\uc5c8\ub2e4. \ud22c\uc790\uc790\uac00 \uc9c0\ub3c4\ub97c \ubcf4\uace0 \uc0ac\uc5c5\uc758 \uae30\ud68c\ub77c\uace0 \uc0dd\uac01\ud55c \uacf3\uc740 \ub204\uad70\uac00\uc5d0\uac8c \uc774\ubbf8 \uc0b6\uc758 \ud130\uc804\uc774\uc5c8\ub2e4. \uacf5\ub3d9 \ud22c\uc790\uc758 \uc5ed\uc0ac\ub294 \uc774\ub7f0 \uc11c\ub85c \ub2e4\ub978 \ucd9c\ubc1c\uc810\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ub2f9\uc2dc\uc758 \uc911\uc0c1\uc8fc\uc758\uc801 \uc0dd\uac01\uc5d0\uc11c\ub294 \uadc0\uae08\uc18d\uc744 \ud655\ubcf4\ud558\ub294 \uc77c\uc774 \uad6d\uac00\uc758 \ubd80\uc640 \uae34\ubc00\ud788 \uc5f0\uacb0\ub418\uc5c8\ub2e4. \uad50\uc7ac\ub294 \uc601\uad6d \uc815\ubd80\uc640 \uc774\uc8fc\ubbfc\ub4e4\uc774 \uae08\uc744 \ubc1c\uacac\ud560 \uac00\ub2a5\uc131\uc5d0 \uae30\ub300\ub97c \uac78\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uba3c \ub545\uc5d0 \ub300\ud55c \uc815\ubcf4\uac00 \ucda9\ubd84\ud558\uc9c0 \uc54a\uc740 \uc0c1\ud669\uc5d0\uc11c\ub3c4 \ubd80\uc758 \uc774\ubbf8\uc9c0\ub294 \uc0ac\ub78c\uc744 \ub04c\uc5b4\ub2f9\uacbc\ub2e4. \uadf8\ub7ec\ub098 \uae30\ub300\ud55c \uad11\ubb3c\uc774 \ud604\uc7a5\uc5d0\uc11c \ub098\ud0c0\ub098\ub294 \uac83\uc740 \ub2e4\ub978 \ubb38\uc81c\uc600\ub2e4. \ubc30\ub97c \ud0c0\uace0 \uac04 \uc0ac\ub78c\ub4e4 \uac00\uc6b4\ub370\ub294 \ub0af\uc120 \ud658\uacbd\uc5d0\uc11c \uc9d1\uc744 \uc9d3\uace0 \ub18d\uc0ac\ub97c \uc9c0\uc5b4 \uc0dd\ud65c\uc744 \uc720\uc9c0\ud560 \uc900\ube44\uac00 \ucda9\ubd84\ud558\uc9c0 \uc54a\uc740 \uc774\ub4e4\ub3c4 \uc788\uc5c8\ub2e4. \ud22c\uc790 \uacc4\ud68d\uc758 \ub9e4\ub825\uacfc \uadf8 \uacc4\ud68d\uc744 \uc2e4\ud589\ud560 \uc77c\uc0c1\uc758 \ub2a5\ub825 \uc0ac\uc774\uc5d0\ub294 \uac04\uaca9\uc774 \uc788\uc5c8\ub2e4. \uc81c\uc784\uc2a4\ud0c0\uc6b4\uc740 \uc9c8\ubcd1\uacfc \uc2dd\ub7c9 \ubd80\uc871, \ub0b4\ubd80 \uac08\ub4f1\uacfc \uc6d0\uc8fc\ubbfc\uacfc\uc758 \ucda9\ub3cc\uc744 \uacaa\uc5c8\ub2e4. \ud2b9\ud788 1609\ub144\uc5d0\uc11c 1610\ub144\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uaca8\uc6b8\uc740 \uc2ec\uac01\ud55c \uae30\uadfc\uc758 \uc2dc\uae30\ub85c \uc54c\ub824\uc838 \uc788\ub2e4. \uad50\uc7ac\ub294 \uadf8 \ubb34\ub835 \uc2dd\ubbfc\uc9c0\uc640 \ud68c\uc0ac\uc758 \uc0ac\uc5c5\uc774 \uac70\uc758 \uc2e4\ud328\ud560 \uc704\uae30\uc5d0 \ub193\uc600\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc5ec\uae30\uc11c \uc218\uc775\uc774 \ub098\uc9c0 \uc54a\uc558\ub2e4\ub294 \ub9d0\uc740 \uc7a5\ubd80\uc758 \uc22b\uc790\ub9cc\uc744 \ub73b\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud604\uc7a5\uc5d0\uc11c\ub294 \uc0ac\ub78c\uc758 \uc0dd\uc874\uc774 \uac78\ub824 \uc788\uc5c8\ub2e4. \ud22c\uc790\uc790\uc758 \uc190\uc2e4\uacfc \uc774\uc8fc\ubbfc\uc774 \uacaa\ub294 \uace0\ud1b5, \uc6d0\uc8fc\ubbfc \uacf5\ub3d9\uccb4\uac00 \uacaa\uc740 \uce68\ud574\ub294 \uac19\uc740 \ub2e8\uc704\ub85c \uc815\ub9ac\ub418\uc9c0 \uc54a\ub294\ub2e4. \uba40\ub9ac\uc11c \ubcf4\uc774\ub294 \uc0ac\uc5c5\uacfc \uadf8 \uc548\uc758 \uc0dd\ud65c\uc744 \ud568\uaed8 \uc77d\uc5b4\uc57c \ud558\ub294 \uc774\uc720\ub2e4. \uc81c\uc784\uc2a4\ud0c0\uc6b4\uc758 \uc218\ucd9c\uc5d0\uc11c \uc911\uc694\ud574\uc9c4 \uac83\uc740 \uae08\ubcf4\ub2e4 \ub2f4\ubc30\uc600\ub2e4. \uad50\uc7ac\ub294 1614\ub144 \ubb34\ub835 \ub2f4\ubc30\uac00 \uc720\ub7fd\uc73c\ub85c \uc218\ucd9c\ub418\uba70 \uc218\uc775\uc744 \ub9cc\ub4e4\uc5b4 \ub0b4\uae30 \uc2dc\uc791\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ucc98\uc74c \uae30\ub300\ud588\ub358 \uc885\ub958\uc758 \ubd80\uac00 \uc544\ub2c8\ub77c \ub2e4\ub978 \uc0c1\ud488\uc774 \uc0ac\uc5c5\uc758 \ubc29\ud5a5\uc744 \ubc14\uafbc \uac83\uc774\ub2e4. \uc774 \ubcc0\ud654\ub294 \uc0c8 \uc791\ubb3c\uc744 \ubc1c\uacac\ud55c \uc990\uac70\uc6b4 \uc804\ud658\uc73c\ub85c\ub9cc \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \ub2f4\ubc30\ub97c \uc7ac\ubc30\ud558\ub824\uba74 \ub545\uacfc \ub178\ub3d9\uc774 \ud544\uc694\ud588\ub2e4. \ub354 \ub9ce\uc740 \uc0c1\ud488\uc744 \ubcf4\ub0b4\ub824\ub294 \uc694\uad6c\ub294 \uc815\ucc29\uc9c0\uc758 \uaddc\ubaa8\uc640 \uc8fc\ubcc0 \uacf5\ub3d9\uccb4\uc640\uc758 \uad00\uacc4\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc8fc\uc5c8\ub2e4. \uc2dc\uc7a5\uc758 \uc218\uc694\ub294 \uba40\ub9ac \uc788\ub294 \uc0dd\ud65c\uc758 \uc870\uac74\uc744 \ubc14\uafb8\ub294 \ud798\uc774 \ub420 \uc218 \uc788\uc5c8\ub2e4. \uc601\uad6d \uc2dd\ubbfc\uc9c0\uc5d0\uc11c\ub294 \uc77c\uc815 \uae30\uac04 \ub178\ub3d9\ud558\ub294 \ub300\uac00\ub85c \uc774\uc8fc \ube44\uc6a9\uc744 \ub9c8\ub828\ud55c \uacc4\uc57d \ud558\uc778\ub4e4\uc774 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud588\ub2e4. \uadf8\ub7ec\ub098 \uc2e4\uc81c \uc0dd\ud65c\uc740 \uc9c8\ubcd1\uacfc \uacfc\ub85c, \ubd88\uc548\uc815\ud55c \uc870\uac74\uc744 \ud3ec\ud568\ud588\ub2e4. \uc774\ud6c4 \ubc84\uc9c0\ub2c8\uc544\uc758 \uc5ed\uc0ac\ub294 \uc544\ud504\ub9ac\uce74\uc778\uc758 \uac15\uc81c \uc774\uc8fc\uc640 \uc778\uc885\uc801 \ub178\uc608\uc81c\uc758 \ud655\ub300\uc640\ub3c4 \uc5f0\uacb0\ub41c\ub2e4. \uac19\uc740 \uc2dc\ub300\uc758 \ubaa8\ub4e0 \ub178\ub3d9 \uad00\uacc4\uac00 \ucc98\uc74c\ubd80\ud130 \uc644\uc804\ud788 \uac19\uc740 \ubc95\uc801 \ud615\ud0dc\uc600\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uad50\uc7ac\ub3c4 \ubcc0\ud654\uc758 \uacfc\uc815\uc744 \uc124\uba85\ud55c\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc720\ub7fd\uc5d0 \ub3c4\ucc29\ud55c \uc0c1\ud488\uc758 \uc774\uc775 \ub4a4\uc5d0 \ub204\uac00 \uc5b4\ub5a4 \uc870\uac74\uc73c\ub85c \uc77c\ud588\ub294\uc9c0 \uc9c8\ubb38\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \ud68c\uc0ac\uc758 \uc131\uc7a5\ub9cc\uc73c\ub85c \ub2f9\uc2dc \uc0ac\ud68c \uc804\uccb4\uc758 \ud615\ud3b8\uc744 \ud3c9\uac00\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud68c\uc0ac\ub294 \ucd9c\uc790\uae08\uacfc \uacc4\ud68d\uc744 \ud55c\uacf3\uc5d0\uc11c \ubaa8\uc558\uc9c0\ub9cc \uc2e4\ud589\uc740 \uba3c \uc2dd\ubbfc\uc9c0\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc84c\ub2e4. \uc18c\uc2dd\uc774 \uc624\uac00\ub294 \ub370 \uc2dc\uac04\uc774 \uac78\ub9ac\uace0 \ud604\uc9c0\uc758 \uc704\ud5d8\uc744 \uac00\uae4c\uc774\uc11c \uc54c\uae30 \uc5b4\ub824\uc6e0\ub2e4. \ud22c\uc790\uc790\uc640 \ud604\uc7a5\uc744 \uc787\ub294 \uc815\ubcf4\uc758 \uac70\ub9ac\ub294 \uc624\ub298\uc758 \uc989\uac01\uc801\uc778 \ud654\uba74\uacfc \ub2e4\ub978 \uc870\uac74\uc774\uc5c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 17\uc138\uae30 \ucd08 \uc0c1\uc778\ub4e4\uc774 \ubb38\uc11c\ub97c \uc0b4\ud53c\ub294 \uc0c1\uc0c1 \uc18d \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c \ubc84\uc9c0\ub2c8\uc544 \ud68c\uc0ac\uc758 \uc8fc\uad8c\uc774\ub098 \uc774\uc0ac\ud68c, \ud2b9\uc815 \ud22c\uc790\uc790\uc758 \ucd08\uc0c1\uc744 \uc7ac\ud604\ud558\uc9c0 \uc54a\uc558\ub2e4. \uc885\uc774 \uc704\uc758 \uc57d\uc18d\uc774 \uba3c \ud56d\uad6c\uc758 \uc0dd\ud65c\uacfc \uc774\uc5b4\uc9c4\ub2e4\ub294 \uc0dd\uac01\uc744 \ud45c\ud604\ud55c \uadf8\ub9bc\uc774\ub2e4. \ubc84\uc9c0\ub2c8\uc544 \ud68c\uc0ac\ub294 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc790\uae08\uc774 \ud070 \uc0ac\uc5c5\uc744 \uc6c0\uc9c1\uc774\ub294 \ubc29\uc2dd\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub3d9\uc2dc\uc5d0 \uadf8 \uc0ac\uc5c5\uc774 \ub9cc\ub4e4\uc5b4 \ub0b8 \uc774\uc775\uacfc \uc704\ud5d8\uc774 \ub204\uad6c\uc5d0\uac8c \uc5b4\ub5bb\uac8c \ubc30\ubd84\ub418\uc5c8\ub294\uc9c0\ub3c4 \ubb3b\uac8c \ud55c\ub2e4. \uc8fc\uc2dd\uc758 \uc5ed\uc0ac\ub294 \uc0c8\ub85c\uc6b4 \uc790\uae08 \uc870\ub2ec\uc758 \uc5ed\uc0ac\uc774\uba74\uc11c \uc2dd\ubbfc\uc9c0\uc758 \uc5ed\uc0ac\uc640 \uacb9\uccd0 \uc788\uc5c8\ub2e4. \ub2e4\uc74c\uc5d0 \uc624\ub798\ub41c \ud68c\uc0ac\uc758 \uc774\ub984\uc744 \ub9cc\ub098\uba74 \uc124\ub9bd \uc5f0\ub3c4\uc640 \ud22c\uc790\uae08\ub9cc \ubcf4\uc9c0 \ub9d0\uace0 \uadf8 \ub3c8\uc774 \uc5b4\ub514\ub85c \uac14\ub294\uc9c0\ub3c4 \uc0b4\ud3b4\ubcf4\uc790. \ub7f0\ub358\uc758 \uafc8\uc740 \uc81c\uc784\uc2a4\ud0c0\uc6b4\uc5d0\uc11c \uae08\uc774 \uc544\ub2cc \ub2f4\ubc30\uc640 \ud798\uaca8\uc6b4 \uc0dd\ud65c\uc744 \ub9cc\ub0ac\ub2e4. \uadf8 \uac04\uaca9\uc744 \uc77d\uc744 \ub54c \uc8fc\uc2dd\uc774\ub77c\ub294 \uc775\uc219\ud55c \ub9d0 \ub4a4\uc758 \uc138\uacc4\uac00 \uc870\uae08 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4."}, {"id": "a4-fold-same-shape", "title": "A4\ub97c \ubc18\uc73c\ub85c \uc811\uc5b4\ub3c4 \ube44\uc2b7\ud55c \ubaa8\uc591\uc778 \uc774\uc720", "summary": "\uc775\uc219\ud55c \ubcf5\uc0ac\uc6a9\uc9c0\ub97c \uc811\uc73c\uba70 \ud06c\uae30\uc640 \ubaa8\uc591\uc758 \uad00\uacc4\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uc218\ud559\uacfc \uce21\uc815", "categories": ["science"], "url": "stories/a4-fold-same-shape/index.html", "image": "../media/a4-fold-same-shape.jpg", "alt": "A4 210\u00d7297\ubc00\ub9ac\ubbf8\ud130, A4\ub97c \ubc18\uc73c\ub85c \uc811\uc5b4 \ub3cc\ub9b0 148.5\u00d7210\ubc00\ub9ac\ubbf8\ud130, \uc815\uc2dd A5 148\u00d7210\ubc00\ub9ac\ubbf8\ud130\ub97c \uac19\uc740 \ube44\uc728\ub85c \ube44\uad50\ud55c \uc124\uba85\ub3c4.", "text": "A4\ub97c \ubc18\uc73c\ub85c \uc811\uc5b4\ub3c4 \ube44\uc2b7\ud55c \ubaa8\uc591\uc778 \uc774\uc720 \uc885\uc774 \ud55c \uc7a5\uc5d0 \uc228\uc5b4 \uc788\ub294 \uc791\uc740 \ube44\uc728 \uc775\uc219\ud55c \ubcf5\uc0ac\uc6a9\uc9c0\ub97c \uc811\uc73c\uba70 \ud06c\uae30\uc640 \ubaa8\uc591\uc758 \uad00\uacc4\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc218\ud559\uacfc \uce21\uc815 \uacfc\ud559\uacfc \ubc1c\uacac A4 \uc885\uc774\uc758 \uae34 \ucabd\uc744 \uc808\ubc18\uc73c\ub85c \uc811\uc5b4 \ubcf4\uc790. \uc791\uc544\uc84c\uc9c0\ub9cc \uc6d0\ub798 \uc885\uc774\uc640 \uaf64 \ube44\uc2b7\ud55c \ubaa8\uc591\uc774 \ub41c\ub2e4. \uae38\ucb49\ud55c \uc9c1\uc0ac\uac01\ud615\uc774 \uac11\uc790\uae30 \uc815\uc0ac\uac01\ud615\uc774 \ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud3c9\uc18c\uc5d0\ub294 \uc9c0\ub098\ucce4\uc744 \uc131\uc9c8\uc774\ub2e4. \uac00\ub85c\uc640 \uc138\ub85c\uac00 \uc544\ubb34 \ube44\uc728\uc774\ub098 \ub41c\ub2e4\uba74 \uc774\ub7f0 \ubaa8\uc2b5\uc774 \ub298 \ub098\uc624\uc9c0\ub294 \uc54a\ub294\ub2e4. A \uacc4\uc5f4 \uc885\uc774\ub294 \ud06c\uae30\ub97c \uc904\uc774\uba74\uc11c\ub3c4 \ube44\uc2b7\ud55c \ubaa8\uc591\uc774 \uc774\uc5b4\uc9c0\ub3c4\ub85d \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub294 \uc88b\uc740 \uc608\ub2e4. W3C\uc758 \uc6a9\uc9c0 \uaddc\uaca9 \uc124\uba85\uc740 A4\ub97c 210 \uacf1\ud558\uae30 297\ubc00\ub9ac\ubbf8\ud130, A5\ub97c 148 \uacf1\ud558\uae30 210\ubc00\ub9ac\ubbf8\ud130\ub85c \uc81c\uc2dc\ud55c\ub2e4. A4\uc758 \uae34 \ubcc0\uc744 \ubc18\uc73c\ub85c \ud558\uba74 148.5\ubc00\ub9ac\ubbf8\ud130\ub2e4. \uc815\ud574\uc9c4 A5\uc758 \uc218\uce58\uc640\ub294 \ubc18 \ubc00\ub9ac\ubbf8\ud130 \ucc28\uc774\uac00 \uc788\ub2e4. \ub530\ub77c\uc11c \uc2e4\uc81c \uc885\uc774\ub97c \uc790\ub974\uba74 \uc815\uc2dd A5\uc640 \ud55c \uce58\ub3c4 \ub2e4\ub974\uc9c0 \uc54a\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \ub450 \uaddc\uaca9\uc744 \ub098\ub780\ud788 \ubcf4\uba74 \uae34 \ubcc0\uacfc \uc9e7\uc740 \ubcc0\uc758 \ube44\uc728\uc774 \ub9e4\uc6b0 \ube44\uc2b7\ud558\ub2e4\ub294 \uac83\uc740 \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \uc774\uc0c1\uc801\uc778 \ube44\uc728\uc5d0\uc11c \uc9e7\uc740 \ubcc0\uc744 1\uc774\ub77c\uace0 \ud558\uba74 \uae34 \ubcc0\uc740 \uc57d 1.414\uac00 \ub41c\ub2e4. \uae34 \ubcc0\uc744 \ubc18\uc73c\ub85c \ub098\ub208 \ub4a4 \uc885\uc774\ub97c \ub3cc\ub824 \ub193\uc73c\uba74 \uc791\uc740 \uc885\uc774\ub3c4 \uc6d0\ub798\uc640 \uac19\uc740 \ube44\uc728\uc744 \uac16\ub294\ub2e4. \uc22b\uc790\ub294 \uc9c1\uc811 \ub098\ub204\uc5b4 \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \uc774 \ube44\uc728\uc740 \uc81c\uacf1\uadfc 2\ub77c\uace0 \ubd80\ub978\ub2e4. \uc774\ub984\uc744 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uad1c\ucc2e\ub2e4. \ubc18\uc73c\ub85c \uc904\uc778 \ub2e4\uc74c \ub3cc\ub824 \ubcf4\uc544\ub3c4 \ubaa8\uc591\uc774 \uc774\uc5b4\uc9c4\ub2e4\ub294 \uc7a5\uba74\uc744 \uba3c\uc800 \ub5a0\uc62c\ub9ac\uba74 \uc218\ud559\uc758 \uc5ed\ud560\uc774 \ud55c\uacb0 \uad6c\uccb4\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4. \uc9c1\uc0ac\uac01\ud615\uc758 \uae34 \ubcc0\uc744 \ubc18\uc73c\ub85c \uc790\ub974\uba74 \ud55c \uc870\uac01\uc758 \ubcc0\uc740 \uc6d0\ub798 \uc9e7\uc740 \ubcc0\uacfc \uae34 \ubcc0\uc758 \uc808\ubc18\uc774 \ub41c\ub2e4. \uc791\uc740 \uc885\uc774\ub97c \ub3cc\ub824 \ubcf4\uba74 \uc5b4\ub290 \ucabd\uc774 \uae34\uc9c0\uc758 \uc5ed\ud560\uc774 \ubc14\ub010\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uac19\uc740 \ubaa8\uc591\uc774 \ub418\ub824\uba74 \uc0c8 \uae34 \ubcc0\uacfc \uc0c8 \uc9e7\uc740 \ubcc0\uc758 \ube44\uc728\uc774 \ucc98\uc74c\uacfc \ub9de\uc544\uc57c \ud55c\ub2e4. \ub2e8\uc21c\ud788 \ub113\uc774\uac00 \ubc18\uc774 \ub418\ub294 \uac83\ub9cc\uc73c\ub85c\ub294 \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc9e7\uc740 \ubcc0\uc744 10, \uae34 \ubcc0\uc744 \uc57d 14.14\ub77c\uace0 \uc0dd\uac01\ud574 \ubcf4\uc790. \uae34 \ubcc0\uc758 \uc808\ubc18\uc740 \uc57d 7.07\uc774\uace0 \uc870\uac01\uc740 10\uacfc 7.07\uc758 \ub450 \ubcc0\uc744 \uac00\uc9c4\ub2e4. \ub3cc\ub824 \ub193\uc740 \ub4a4\uc758 \ube44\uc728\ub3c4 \uc57d 1.414\ub2e4. \uc2e4\uc81c \uc885\uc774\uc758 \uce58\uc218\uac00 \uc544\ub2c8\ub77c \ube44\uc728\uc744 \ubcf4\uae30 \uc704\ud574 \uace0\ub978 \uc22b\uc790\ub2e4. \uac04\ub2e8\ud55c \ub098\ub217\uc148\uc73c\ub85c \uc65c \ubaa8\uc591\uc774 \ub2ee\uc544 \ubcf4\uc774\ub294\uc9c0 \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \ub2ee\uc740 \uc9c1\uc0ac\uac01\ud615\uc740 \ubcc0\uc758 \ube44\uc728\uc774 \uac19\uc544\ub3c4 \uc2e4\uc81c \ud06c\uae30\ub294 \ub2e4\ub97c \uc218 \uc788\ub2e4. A4\uc640 \ubc18\uc73c\ub85c \ub098\ub208 \uc870\uac01\uc740 \ub2f9\uc5f0\ud788 \uac19\uc740 \ub113\uc774\uac00 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c \uc720\uc9c0\ud558\ub824\ub294 \uac83\uc740 \ubaa8\uc591\uc758 \uad00\uacc4\ub2e4. \uc218\ud559\uc5d0\uc11c \ube44\uc728\uc744 \uc77d\ub294 \uc77c\uc774 \uc2e4\uc81c \ubb3c\uac74\uc758 \ud06c\uae30\ub97c \uc9c0\uc6b0\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ubb34\uc5c7\uc774 \uac19\uace0 \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0 \ub098\ub204\ub294 \ub3c4\uad6c\uac00 \ub41c\ub2e4. \uc0ac\uc9c4\uc774\ub098 \ubb38\uc11c\ub97c \ud655\ub300\ud560 \ub54c\ub3c4 \uac00\ub85c\uc640 \uc138\ub85c\uc758 \uad00\uacc4\ub97c \ud568\uaed8 \uc720\uc9c0\ud558\uba74 \ubaa8\uc591\uc774 \ucc0c\uadf8\ub7ec\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uc774\uac83\uc740 \uc6a9\uc9c0\uc758 \ube44\uc728\uc744 \uc774\ud574\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub418\ub294 \ube44\uad50\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \uc778\uc1c4 \ud504\ub85c\uadf8\ub7a8\uc774 \uac19\uc740 \uc5ec\ubc31\uacfc \ubc30\uce58\ub97c \ubcf4\uc7a5\ud55c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc885\uc774\uc758 \uae30\ud558\ud559\uc801\uc778 \uc131\uc9c8\uacfc \uc2e4\uc81c \ucd9c\ub825 \uc124\uc815\uc740 \uc11c\ub85c \ub2e4\ub978 \uc870\uac74\uc774\ub2e4. \uc81c\uacf1\uadfc 2\ub294 \uc815\ud655\ud55c \uad00\uacc4\ub97c \ub098\ud0c0\ub0b4\uc9c0\ub9cc \uc2e4\uc81c \uaddc\uaca9\uc740 \ubc00\ub9ac\ubbf8\ud130 \ub2e8\uc704\uc758 \uc815\uc218\ub85c \uc801\ud78c\ub2e4. A4\uc758 297\uc744 \ubc18\uc73c\ub85c \ud55c 148.5\uc640 A5\uc758 148 \uc0ac\uc774\uc758 \ucc28\uc774\ub294 \uc774\ub7f0 \uc2e4\uc81c \ud45c\uae30\ub97c \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc774 \ucc28\uc774\uac00 \uc788\ub2e4\uace0 \uc124\uacc4\uc758 \uc544\uc774\ub514\uc5b4\uac00 \ubb34\ub108\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774\uc0c1\uc801\uc778 \ube44\uc728\uacfc \uc4f0\ub294 \uaddc\uaca9\uc758 \uc22b\uc790\ub97c \uad6c\ubd84\ud558\uba74 \ub450 \uc124\uba85\uc744 \ud568\uaed8 \uc77d\uc744 \uc218 \uc788\ub2e4. \ub530\ub77c\uc11c A4\ub97c \uc811\uc73c\uba74 \uc815\uc2dd A5\uc640 \uc5b8\uc81c\ub098 \uc644\uc804\ud788 \uac19\ub2e4\uace0 \ub9d0\ud558\uae30\ubcf4\ub2e4 \ube44\uc728\uc774 \ub9e4\uc6b0 \uac00\uae5d\ub2e4\uace0 \uc124\uba85\ud558\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \uacf5\uac1c\ub41c \uce58\uc218\ub85c \uc9c1\uc811 \ub098\ub204\uc5b4 \uadf8 \uad00\uacc4\ub97c \uc0b4\ud3c8\ub2e4. \ubcc4\ub3c4\uc758 \uc885\uc774\ub97c \uc2e4\uce21\ud574 \ubaa8\ub4e0 \uc81c\uc870 \uc624\ucc28\ub97c \ud655\uc778\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uaddc\uaca9\uc5d0 \uad00\ud55c \uc124\uba85\uacfc \uc2e4\uc81c \ud55c \uc7a5\uc758 \uce21\uc815\uc740 \uc9c8\ubb38\uc774 \ub2e4\ub974\ub2e4. \uc6a9\uc9c0 \uc774\ub984\uc740 \ub9e4\uc77c \uc4f0\ub2e4 \ubcf4\uba74 \uc790\uc5f0\ubb3c\uc758 \uc774\ub984\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uadf8\ub7ec\ub098 \uce58\uc218\uc640 \ube44\uc728\uc744 \uc815\ud558\uba74 \ubb38\uc11c\uc640 \ubcf4\uad00, \ubcf5\uc0ac\uc640 \ubc30\uce58\uac00 \uacf5\ud1b5\uc758 \uc870\uac74\uc744 \uac16\uac8c \ub41c\ub2e4. \ud06c\uae30 \uccb4\uacc4\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc0ac\ub78c\ub4e4\uc774 \uc11c\ub85c \ub2e4\ub978 \uacf3\uc5d0\uc11c \ube44\uc2b7\ud55c \uc885\uc774\ub97c \uc54c\uc544\ubcf4\uace0 \uc0ac\uc6a9\ud560 \uc218 \uc788\uac8c \ud55c\ub2e4. \uc885\uc774 \ud55c \uc7a5\uc5d0\ub3c4 \uaddc\uaca9\uc744 \ud1b5\ud55c \ud569\uc758\uac00 \ub4e4\uc5b4 \uc788\ub294 \uc148\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \uc885\uc774\ub97c \ubc18\uc73c\ub85c \uc811\uc744 \ub54c\uc5d0\ub294 \uc5b4\ub290 \ubcc0\uc774 \uc9e7\uc544\uc84c\uace0 \ub3cc\ub824 \ub193\uc73c\uba74 \uc5b4\ub5a4 \ubaa8\uc591\uc778\uc9c0 \uc7a0\uae50 \uc0b4\ud3b4\ubcf4\uc790. \uae30\ud558\ud559\uc744 \uacf5\ubd80\ud558\ub824\uace0 \ubcc4\ub3c4\uc758 \uad50\uad6c\ub97c \ucc3e\uc9c0 \uc54a\uc544\ub3c4 \uc190\uc548\uc5d0\uc11c \ube44\uc728\uc758 \uc9c8\ubb38\uc774 \uc0dd\uae34\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uae34 \uc22b\uc790\ub97c \uc678\uc6b0\ub294 \uac83\ubcf4\ub2e4 \ubb34\uc5c7\uc744 \ubc18\uc73c\ub85c \ub098\ub204\uace0 \ubb34\uc5c7\uc744 \uac19\uac8c \uc720\uc9c0\ud558\ub824 \ud588\ub294\uc9c0 \ubcf4\ub294 \uc77c\uc774\ub2e4. \ud3c9\ubc94\ud55c \uc885\uc774\uac00 \uc218\ud559\uc758 \uc791\uc740 \uc2e4\ud5d8\uc7a5\uc774 \ub41c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc124\uba85\ub3c4\ub294 \uc2e4\uc81c A4 \uce58\uc218\uc640 \uadf8 \uc808\ubc18\uc744 \ub098\ub780\ud788 \ube44\uad50\ud55c\ub2e4. \uc815\uc2dd A5\uc758 \uae38\uc774\ub3c4 \ub530\ub85c \ud45c\uc2dc\ud574 \uc774\uc0c1\uc801\uc778 \ube44\uc728\uacfc \uc2e4\uc81c \uaddc\uaca9\uc758 \uc791\uc740 \ucc28\uc774\ub97c \uad6c\ubd84\ud588\ub2e4. \uc885\uc774 \ud55c \uc7a5\uc740 \ud2b9\ubcc4\ud55c \ub3c4\uad6c\uac00 \uc5c6\uc5b4\ub3c4 \uad00\ucc30\ud560 \uc218 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \ubcf5\uc0ac\uc6a9\uc9c0\ub97c \uc811\uc744 \ub54c \uc791\uc544\uc9c4 \uc885\uc774\ub97c \uc6d0\ub798 \uac83 \uc606\uc5d0 \ub193\uc544 \ubcf4\uc790. \uc77c\uc0c1\uc5d0\uc11c \uc790\uc8fc \uc4f0\ub294 \ubb3c\uac74\uc758 \ud06c\uae30\uc5d0\ub3c4, \uc904\uc774\uace0 \uc774\uc5b4 \uc4f0\uae30 \uc88b\uc740 \uad00\uacc4\ub97c \ucc3e\uc73c\ub824\ub294 \uc0dd\uac01\uc774 \ub4e4\uc5b4 \uc788\ub2e4."}, {"id": "apollo-bootprint-close-up", "title": "\ub2ec\uc5d0\uc11c\ub294 \uc2e0\ubc1c \ubc14\ub2e5\ub3c4 \uae30\ub85d\uc774 \ub418\uc5c8\ub2e4", "summary": "NASA\uac00 \uacf5\uac1c\ud55c \ub2ec\uc758 \ubc1c\uc790\uad6d \uc0ac\uc9c4\uc5d0\uc11c \ud0d0\uc0ac\uc758 \uc791\uc740 \ud754\uc801\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uc6b0\uc8fc\uc640 \ucc9c\ubb38", "categories": ["science"], "url": "stories/apollo-bootprint-close-up/index.html", "image": "../media/apollo-bootprint-close-up.jpg", "alt": "NASA\uac00 \uc544\ud3f4\ub85c \uc6b0\uc8fc\ube44\ud589\uc0ac\uc758 \ub2ec \ubc1c\uc790\uad6d\uc73c\ub85c \uacf5\uac1c\ud55c \uc2e4\uc81c \uc0ac\uc9c4. \ud45c\uba74\uc5d0 \uc2e0\ubc1c \ubc11\ucc3d\uc758 \uc904\ubb34\ub2ac\uac00 \ub0a8\uc544 \uc788\uc2b5\ub2c8\ub2e4.", "text": "\ub2ec\uc5d0\uc11c\ub294 \uc2e0\ubc1c \ubc14\ub2e5\ub3c4 \uae30\ub85d\uc774 \ub418\uc5c8\ub2e4 \ud070 \ud0d0\uc0ac \uc774\uc57c\uae30\ub97c \uc791\uc740 \ubc1c\uc790\uad6d\uc73c\ub85c \ubcf4\uae30 NASA\uac00 \uacf5\uac1c\ud55c \ub2ec\uc758 \ubc1c\uc790\uad6d \uc0ac\uc9c4\uc5d0\uc11c \ud0d0\uc0ac\uc758 \uc791\uc740 \ud754\uc801\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc6b0\uc8fc\uc640 \ucc9c\ubb38 \uacfc\ud559\uacfc \ubc1c\uacac \ub2ec \ud0d0\uc0ac\ub97c \ub5a0\uc62c\ub9ac\uba74 \uc6b0\uc8fc\uc120\uacfc \uc6b0\uc8fc\ubcf5, \uba40\ub9ac \ubcf4\uc774\ub294 \uc9c0\uad6c\uac00 \uba3c\uc800 \uc0dd\uac01\ub09c\ub2e4. \uadf8\ub7f0\ub370 NASA\uc758 \uacf5\uac1c \uc790\ub8cc\uc5d0\ub294 \uc0ac\ub78c\uc758 \uc5bc\uad74\ub3c4 \uc6b0\uc8fc\uc120\ub3c4 \uc5c6\uc774 \ubc1c\uc790\uad6d\uc744 \uac00\uae4c\uc774 \ucc0d\uc740 \uc0ac\uc9c4\uc774 \uc788\ub2e4. \ud654\uba74\uc744 \ucc44\uc6b0\ub294 \uac83\uc740 \ubc14\ub2e5\uc758 \ud759\uacfc \uc2e0\ubc1c \ubc11\ucc3d\uc758 \ubb34\ub2ac\ub2e4. NASA\ub294 \uc774 \uc0ac\uc9c4\uc744 \uc544\ud3f4\ub85c \uc6b0\uc8fc\ube44\ud589\uc0ac\uc758 \ub2ec \ubc1c\uc790\uad6d \uc790\ub8cc\ub85c \uc18c\uac1c\ud55c\ub2e4. \ucee4\ub2e4\ub780 \ud0d0\uc0ac \uc774\uc57c\uae30\ub97c \uc7a0\uc2dc \ub0b4\ub824\ub193\uace0 \ubcf4\uba74, \uc0ac\ub78c\uc774 \uc5b4\ub5a4 \uacf3\uc5d0 \ub2e4\ub140\uac14\ub294\uc9c0\ub97c \uc54c\ub824 \uc8fc\ub294 \uc544\uc8fc \uc775\uc219\ud55c \ud754\uc801\uc774 \ub098\uc628\ub2e4. \uc0ac\uc9c4\uc5d0\ub294 \ubc11\ucc3d\uc758 \uc5ec\ub7ec \uc904\uc774 \ubc1d\uace0 \uc5b4\ub450\uc6b4 \ubd80\ubd84\uc73c\ub85c \ub0a8\uc544 \uc788\ub2e4. \ubc1c\uc790\uad6d\uc758 \ubaa8\uc591\uc744 \uc54c\uc544\ubcf4\ub294 \ub370 \uc2e0\ubc1c \uc804\uccb4\ub098 \uc6b0\uc8fc\ubcf5\uc744 \ubcfc \ud544\uc694\ub294 \uc5c6\ub2e4. \ubc14\ub2e5\uc5d0 \uc62e\uaca8\uc9c4 \ubb34\ub2ac\ub9cc\uc73c\ub85c\ub3c4 \uc0ac\ub78c\uc774 \ub514\ub3a0\ub358 \uc790\ub9ac\ub97c \uc77d\uac8c \ub41c\ub2e4. \uc6b0\ub9ac\ub294 \uc77c\uc0c1\uc5d0\uc11c\ub3c4 \ube44\uc2b7\ud55c \uc77c\uc744 \ud55c\ub2e4. \uc816\uc740 \ubc14\ub2e5\uc774\ub098 \ud759\uae38\uc5d0 \ub0a8\uc740 \uc790\uad6d\uc744 \ubcf4\uace0 \ub204\uad70\uac00 \uc9c0\ub098\uac14\ub2e4\uace0 \uc9d0\uc791\ud55c\ub2e4. \ub0af\uc120 \ub2ec \ud45c\uba74\uc5d0\uc11c \uac11\uc790\uae30 \uadf8\ub7f0 \uac00\uae4c\uc6b4 \uacbd\ud5d8\uc744 \ub9cc\ub098\ub294 \uac83\uc774\ub2e4. \uc774 \uc790\ub8cc\uc758 \uc774\ub984\uc5d0\ub294 \uc544\ud3f4\ub85c\uc640 \ub2ec, \uc6b0\uc8fc\ube44\ud589\uc0ac\uc758 \ubc1c\uc790\uad6d\uc774\ub77c\ub294 \uc815\ubcf4\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \ub355\ubd84\uc5d0 \ub2e8\uc21c\ud55c \ud759\ubc14\ub2e5 \uc0ac\uc9c4\uacfc\ub294 \ub2e4\ub978 \ub9e5\ub77d\uc5d0\uc11c \uc774\ubbf8\uc9c0\ub97c \uc77d\uc744 \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc0ac\uc9c4 \ud55c \uc7a5\uc5d0 \ubd99\uc740 \uc775\uc219\ud55c \uc774\ub984\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc0ac\uc815\uc744 \uc54c \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc774 \uc790\uad6d\uc774 \ucd5c\ucd08\uc758 \ubc1c\uc790\uad6d\uc774\ub77c\uace0 \ub2e8\uc815\ud558\uac70\ub098 \uc5b4\ub290 \uc6b0\uc8fc\ube44\ud589\uc0ac\uc758 \uc5b4\ub290 \ubc1c\uc778\uc9c0 \uc815\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud655\uc778\ud55c \uc790\ub8cc\uac00 \uc54c\ub824 \uc8fc\ub294 \ubc94\uc704 \uc548\uc5d0\uc11c \uc0ac\uc9c4\uc744 \ubcf4\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \uc2e0\ubc1c\uc774 \ud45c\uba74\uc744 \ub204\ub974\uba74 \ub2ff\uc740 \ubd80\ubd84\uacfc \uc8fc\ubcc0\uc758 \ucc28\uc774\uac00 \ud754\uc801\uc73c\ub85c \ub0a8\uc744 \uc218 \uc788\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uadf8 \uad00\uacc4\uac00 \uc904\ubb34\ub2ac\uc758 \ubc1d\uace0 \uc5b4\ub450\uc6b4 \ubd80\ubd84\uc73c\ub85c \ubcf4\uc778\ub2e4. \ubc11\ucc3d \uc790\uccb4\ub294 \ud654\uba74\uc5d0 \uc5c6\uc9c0\ub9cc \ubb34\uc5c7\uc778\uac00\uac00 \ub2ff\uc558\ub358 \ud615\uc0c1\uc744 \uc77d\uac8c \ub41c\ub2e4. \ubb3c\uac74\uc774 \uc790\ub9ac\ub97c \ub5a0\ub09c \ub4a4\uc5d0\ub3c4 \uadf8 \ubaa8\uc591\uc758 \uc77c\ubd80\uac00 \ub2e4\ub978 \uc7ac\ub8cc\uc5d0 \ub0a8\ub294 \uac83\uc774\ub2e4. \uc774 \uc124\uba85\ub9cc\uc73c\ub85c \uc0ac\uc9c4 \uc18d \uc790\uad6d\uc758 \ubaa8\ub4e0 \uc0dd\uc131 \uc870\uac74\uc744 \uc0c8\ub85c \uce21\uc815\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc555\ub825\uc774\ub098 \ud1a0\uc591\uc758 \uc0c1\ud0dc, \uc815\ud655\ud55c \uae4a\uc774\ub97c \uc54c\ub824\uba74 \ub2e4\ub978 \uc790\ub8cc\uac00 \ud544\uc694\ud558\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc2e4\uc81c \uc0ac\uc9c4\uc5d0\uc11c \ubcfc \uc218 \uc788\ub294 \ubb34\ub2ac\uc640 \uba85\uc554\uc744 \ub530\ub77c\uac04\ub2e4. \uc775\uc219\ud55c \uc2e0\ubc1c\uc758 \ud615\ud0dc\uac00 \ub0af\uc120 \uc7a5\uc18c\uc758 \ud45c\uba74\uacfc \ub9cc\ub09c\ub2e4\ub294 \uc810\ub9cc\uc73c\ub85c\ub3c4 \ucda9\ubd84\ud788 \ub208\uae38\uc744 \ub048\ub2e4. \uac19\uc740 \ubb3c\uac74\ub3c4 \ube5b\uc744 \uc5b4\ub514\uc5d0\uc11c \ubc1b\ub294\uc9c0\uc5d0 \ub530\ub77c \ud45c\uba74\uc758 \ub192\ub0ae\uc774\uac00 \ub2ec\ub9ac \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ubc1c\uc790\uad6d \uc0ac\uc9c4\uc758 \uc5b4\ub450\uc6b4 \uc120\uacfc \ubc1d\uc740 \uba74\uc744 \ubc88\uac08\uc544 \ubcf4\uba74 \ud3c9\uba74\uc758 \uc0c9\ubb34\ub2ac\uc640 \ub20c\ub9b0 \uc790\uad6d\uc758 \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc0ac\uc9c4\uc740 \ud45c\uba74\uc744 \ubcf4\uc5ec \uc8fc\uc9c0\ub9cc \uadf8 \ubcf4\uc774\ub294 \ubc29\uc2dd\uc5d0\ub294 \ucd2c\uc601\uc758 \uc870\uac74\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \uba85\uc554\uc740 \uc815\ubcf4\ub97c \uc804\ud558\ub294 \ud55c \ud1b5\ub85c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uadf8\ub9bc\uc790\ub9cc\uc73c\ub85c \uc2e4\uc81c \uc218\uce58\ub97c \uacc4\uc0b0\ud574 \ud655\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774 \uae00\uc740 \uc0ac\uc9c4 \uac10\uc0c1\uc758 \uad00\ucc30\uc744 \uc74c\uc601\uc73c\ub85c \uc815\ubc00 \uce21\ub7c9\ud55c \uacb0\uacfc\ucc98\ub7fc \uc81c\uc2dc\ud558\uc9c0 \uc54a\ub294\ub2e4. \ubb34\uc5c7\uc774 \ubcf4\uc774\ub294\uc9c0 \uc815\ud655\ud788 \uc124\uba85\ud558\ub294 \uc77c\ub9cc\uc73c\ub85c\ub3c4 \ucda9\ubd84\ud788 \ud765\ubbf8\ub86d\ub2e4. \ubb34\ub2ac\ub97c \uc54c\uc544\ubcf8 \ub4a4 \ube5b\uc744 \uc0b4\ud53c\uba74 \ud55c \uc7a5\uc758 \uc0ac\uc9c4 \uc548\uc5d0\uc11c \uc0c8\ub85c\uc6b4 \uc815\ubcf4\uac00 \uc0dd\uae34\ub2e4. \ubc1c\uc790\uad6d\uc774\ub77c\ub294 \ud615\uc0c1\ub9cc\uc73c\ub85c \uc774\uacf3\uc774 \ub2ec\uc778\uc9c0 \ub2e4\ub978 \uacf3\uc778\uc9c0 \uc0ac\uc9c4 \ubc16\uc758 \ub9e5\ub77d\uc744 \ubaa8\ub450 \uc54c \uc218\ub294 \uc5c6\ub2e4. NASA\uac00 \ubd99\uc778 \uc790\ub8cc\uba85\uacfc \uc81c\uacf5 \uc815\ubcf4\ub97c \ud568\uaed8 \uc77d\uc5b4\uc57c \uc544\ud3f4\ub85c \ud65c\ub3d9\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc0ac\uc9c4\uacfc \ucea1\uc158\uc740 \uc11c\ub85c \ub2e4\ub978 \uc5ed\ud560\uc744 \ub9e1\uc73c\uba70 \ud568\uaed8 \uae30\ub85d\uc744 \uc774\ub8ec\ub2e4. \uc798 \uc54c\ub824\uc9c4 \uc774\ubbf8\uc9c0\ub97c \ub2e4\uc2dc \ub9cc\ub0a0 \ub54c\uc5d0\ub3c4 \uadf8 \uc124\uba85\uc744 \ud655\uc778\ud560 \uc774\uc720\uac00 \uc788\ub2e4. \ud2b9\ud788 \ucd5c\ucd08\ub77c\ub294 \ub2e8\uc5b4\ub294 \uc870\uc2ec\ud574\uc11c \ubd99\uc5ec\uc57c \ud55c\ub2e4. \uc720\uba85\ud55c \uc0ac\uc9c4\uc774\ub77c\uace0 \uc778\ub958\uc758 \uccab \ubc1c\uc790\uad6d\uc744 \uc9c1\uc811 \ucc0d\uc740 \uc7a5\uba74\uc774\ub77c\uace0 \uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc5b4\ub290 \uc6b0\uc8fc\ube44\ud589\uc0ac\uc758 \uc5b4\ub290 \ubc1c\uc778\uc9c0\ub3c4 \uc774 \uc6d0\uace0\uac00 \ud655\uc778\ud55c \uc790\ub8cc\uc758 \ubc94\uc704 \ubc16\uc5d0 \uc788\ub2e4. \uc774\ubbf8\uc9c0\ub97c \ub35c \uadf9\uc801\uc73c\ub85c \uc18c\uac1c\ud558\ub354\ub77c\ub3c4 \uae30\ub85d\uc758 \uac00\uce58\ub294 \uc904\uc9c0 \uc54a\ub294\ub2e4. \ud655\uc778\ub41c \ubc94\uc704\ub97c \ubd84\uba85\ud788 \ud574\uc57c \ub2e4\ub978 \uc790\ub8cc\uc640\ub3c4 \uc815\ud655\ud788 \uc5f0\uacb0\ud560 \uc218 \uc788\ub2e4. \uc6b0\uc8fc \ud0d0\uc0ac\ub294 \ub85c\ucf13\uacfc \uae30\uacc4\uc758 \ud070 \ubaa8\uc2b5\uc73c\ub85c \uae30\uc5b5\ub418\uae30 \uc27d\ub2e4. \ubc1c\uc790\uad6d\uc740 \uadf8 \ud65c\ub3d9\uc5d0 \uc0ac\ub78c\uc758 \ubab8\uc774 \ucc38\uc5ec\ud588\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc77c\uc0c1\uc801\uc778 \ub3d9\uc791\uc73c\ub85c \uc804\ud55c\ub2e4. \ud55c \ubc88 \ub514\ub514\ub294 \uc77c\uc740 \ub108\ubb34 \uc775\uc219\ud558\uc9c0\ub9cc \uc7a5\uc18c\uac00 \ub2ec\ub77c\uc9c0\uba74 \uae30\ub85d\ud560 \ub9cc\ud55c \ud589\ub3d9\uc774 \ub41c\ub2e4. \ud070 \uae30\uc220\uc758 \uc5ed\uc0ac\ub97c \uc190\uacfc \ubc1c\uc758 \ud06c\uae30\uc5d0\uc11c \ub9cc\ub098\ub294 \uc785\uad6c\ub2e4. \uc774\uac83\uc774 \uc0ac\uc9c4 \uc18d \ubaa8\ub4e0 \uac10\uc815\uc744 \uc54c\ub824 \uc900\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub2f9\uc2dc \uc0ac\ub78c\uc774 \uc5b4\ub5a4 \uc0dd\uac01\uc744 \ud588\ub294\uc9c0 \ub300\uc0ac\ub97c \uafb8\ubbf8\uae30\ubcf4\ub2e4 \ub0a8\uc740 \ud754\uc801\uc744 \ucc28\ubd84\ud558\uac8c \ubcfc \uc218 \uc788\ub2e4. \ud654\uba74\uc744 \uac00\uae4c\uc774 \ubcf4\uba70 \uc904\uc758 \uac04\uaca9\uacfc \ud45c\uba74\uc758 \ub2e4\ub978 \uc790\uad6d\uc744 \uc0b4\ud3b4\ubcf4\uc790. \uba40\ub9ac \uc788\ub294 \uc7a5\uc18c\uc758 \uc774\uc57c\uae30\uac00 \ubc1c\ubc14\ub2e5 \ubb34\ub2ac\ub77c\ub294 \uac00\uae4c\uc6b4 \ud615\uc0c1\uc73c\ub85c \uc6b0\ub9ac\uc5d0\uac8c \uc804\ub2ec\ub418\uc5c8\ub2e4\ub294 \uc810\uc774 \uc624\ub798 \ub0a8\ub294\ub2e4. \uc774 \uc774\ubbf8\uc9c0\ub294 NASA\uac00 \uacf5\uac1c\ud55c \uc2e4\uc81c \uc0ac\uc9c4\uc774\ub2e4. \uc0bd\ud654\ub85c \ubc11\ucc3d\uc744 \ub2e4\uc2dc \uadf8\ub9ac\uc9c0 \uc54a\uace0 \uc6d0\ub798 \uc0ac\uc9c4\uc744 \ud568\uaed8 \uc2e4\uc740 \uc774\uc720\ub3c4 \uc5ec\uae30\uc5d0 \uc788\ub2e4. \uc5b4\ub5a4 \ubb34\ub2ac\uac00 \uc5b4\ub5bb\uac8c \ub0a8\uc558\ub294\uc9c0\ub294 \uc2e4\uc81c \uc790\ub8cc\ub97c \ubcf4\ub294 \ud3b8\uc774 \ud6e8\uc52c \ube60\ub974\ub2e4. \uc6b0\uc8fc \ud0d0\uc0ac\ub294 \uac70\ub300\ud55c \uae30\uacc4\ub9cc\uc758 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\uc758 \ubab8\uc744 \uac10\uc2fc \uc637\uacfc \ubc1c\uc744 \ub514\ub518 \uc2e0\ubc1c\ub3c4 \ud568\uaed8 \uc6c0\uc9c1\uc600\ub2e4. \ub2ec\uc744 \ubcf4\uace0 \uace0\uac1c\ub97c \ub4e4\ub358 \uc2dc\uc120\uc744 \uc774\ubc88\uc5d0\ub294 \uc544\ub798\ub85c \ub0b4\ub824 \ubcf4\uc790. \uc791\uc740 \ubc11\ucc3d\uc758 \ud754\uc801\uc5d0\uc11c\ub3c4 \ud0d0\uc0ac\uc758 \ub2e4\ub978 \uc5bc\uad74\uc744 \ub9cc\ub0a0 \uc218 \uc788\ub2e4."}, {"id": "barometer-pressure-trends-and-weather", "title": "\uae30\uc555\uacc4 \u2014 \ub208\uae08 \ud558\ub098\ub85c \ub0b4\uc77c \ub0a0\uc528\ub97c \uc54c \uc218 \uc788\uc744\uae4c", "summary": "19\uc138\uae30 \uae30\uc555\uacc4 \uc548\ub0b4\uc11c\ub97c \ub530\ub77c \uce21\uc815\uac12\u00b7\uae30\uae30\uc758 \uc870\uac74\u00b7\uace0\ub3c4\u00b7\ub0a0\uc528 \ud574\uc11d\uc758 \ucc28\uc774\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uc218\ud559\uacfc \uce21\uc815", "categories": ["science"], "url": "stories/barometer-pressure-trends-and-weather/index.html", "image": "../media/barometer-pressure-trends-and-weather.jpg", "alt": "\uc544\ub124\ub85c\uc774\ub4dc \uae30\uc555\uacc4\uc758 \ub0b4\ubd80 \ub808\ubc84\uc640 \ubc14\ub298 \uc5f0\uacb0 \uc7a5\uce58\ub97c \ubcf4\uc5ec \uc8fc\ub294 1890\ub144 \uc5ed\uc0ac \ub3c4\ud310", "text": "\uae30\uc555\uacc4 \u2014 \ub208\uae08 \ud558\ub098\ub85c \ub0b4\uc77c \ub0a0\uc528\ub97c \uc54c \uc218 \uc788\uc744\uae4c \uc218\uc740\uacfc \uc544\ub124\ub85c\uc774\ub4dc, \uad00\uce21 \uc870\uac74\uacfc \uae30\uc555 \ucd94\uc138\uc758 \ud574\uc11d 19\uc138\uae30 \uae30\uc555\uacc4 \uc548\ub0b4\uc11c\ub97c \ub530\ub77c \uce21\uc815\uac12\u00b7\uae30\uae30\uc758 \uc870\uac74\u00b7\uace0\ub3c4\u00b7\ub0a0\uc528 \ud574\uc11d\uc758 \ucc28\uc774\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc218\ud559\uacfc \uce21\uc815 \uacfc\ud559\uacfc \ubc1c\uacac \uae30\uc555\uacc4\uc758 \ub208\uae08 \uc606\uc5d0\ub294 \ub9d1\uc74c\uc774\ub098 \ube44 \uac19\uc740 \ub9d0\uc774 \ubd99\uc5b4 \uc788\uae30\ub3c4 \ud558\ub2e4. \ubc14\ub298\uc774 \uadf8 \uc790\ub9ac\ub97c \uac00\ub9ac\ud0a4\uba74 \ub0a0\uc528\ub3c4 \ubc18\ub4dc\uc2dc \uadf8\ub807\uac8c \ub420\uae4c. 19\uc138\uae30\uc758 \uae30\uc555\uacc4 \uc548\ub0b4\uc11c\ub97c \uc77d\uc73c\uba74 \uc624\ud788\ub824 \uc218\uce58\ub97c \ud574\uc11d\ud558\ub294 \uc870\uac74\uc774 \uc911\uc694\ud588\uc74c\uc744 \uc54c \uc218 \uc788\ub2e4. \uacf5\uae30\uc758 \uc555\ub825\uc744 \uc7ac\ub294 \uc7a5\uce58\uac00 \ub0a0\uc528\ub97c \uc774\ud574\ud558\ub294 \uc790\ub8cc\uac00 \ub418\ub294 \uacfc\uc815\uc744 \uc0b4\ud3b4\ubcf4\uc790. \uacf5\uae30\ub294 \ub208\uc5d0 \uc798 \ubcf4\uc774\uc9c0 \uc54a\uc9c0\ub9cc \uc8fc\ubcc0 \ubb3c\uccb4\uc5d0 \uc555\ub825\uc744 \uac00\ud55c\ub2e4. \uae30\uc555\uacc4\ub294 \uadf8 \ud6a8\uacfc\ub97c \ub2e4\ub978 \ubb3c\ub9ac\uc801 \ubcc0\ud654\ub85c \uc77d\uc5b4 \ub0b4\ub294 \uc7a5\uce58\ub2e4. \uacf5\uae30\uc758 \uc591\uacfc \uc0c1\ud0dc\uac00 \uacf5\uac04\uc5d0 \ub530\ub77c \ub2e4\ub974\ubbc0\ub85c \uc555\ub825\ub3c4 \uc5b8\uc81c\ub098 \uc5b4\ub514\uc11c\ub098 \uac19\uc740 \uac12\uc73c\ub85c \uace0\uc815\ub418\uc5b4 \uc788\uc9c0 \uc54a\ub2e4. \uae30\uae30\ub97c \ub4e4\uc5ec\ub2e4\ubcf4\uba74 \uc22b\uc790 \ud558\ub098\uac00 \ubcf4\uc774\uc9c0\ub9cc \uadf8 \uc22b\uc790\uac00 \ubb34\uc5c7\uc744 \ub098\ud0c0\ub0b4\ub294\uc9c0 \uba3c\uc800 \uc54c\uc544\uc57c \ud55c\ub2e4. \uc624\ub298\uc758 \uc628\ub3c4\uc640 \uae30\uc555\uc774 \ubaa8\ub450 \ub0a0\uc528\uc5d0 \uc4f0\uc778\ub2e4\uace0 \uac19\uc740 \uc131\uc9c8\uc744 \uc7ac\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uce21\uc815 \ub300\uc0c1\uc758 \ucc28\uc774\ub97c \uc54c\uc544\uc57c \uacb0\uacfc\ub97c \uc11e\uc5b4\uc11c \uc774\ud574\ud558\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uc218\uc740 \uae30\uc555\uacc4\ub294 \uc561\uccb4 \uae30\ub465\uc758 \ub192\uc774\ub85c \uc555\ub825\uacfc\uc758 \uad00\uacc4\ub97c \uc77d\ub294\ub2e4. \ubc18\uba74 \uc544\ub124\ub85c\uc774\ub4dc \uae30\uc555\uacc4\ub294 \ub0b4\ubd80 \uc555\ub825\uc744 \ub0ae\ucd98 \uae08\uc18d \uc0c1\uc790\uc758 \uc791\uc740 \ubcc0\ud615\uc744 \uc7a5\uce58\uc640 \ubc14\ub298\ub85c \ud655\ub300\ud574 \ubcf4\uc5ec \uc900\ub2e4. \uac19\uc740 \uc131\uc9c8\uc744 \uc7ac\ub354\ub77c\ub3c4 \uc6d0\ub9ac\ub97c \uad6c\ud604\ud558\ub294 \ubc29\uc2dd\uc740 \ub2e4\ub97c \uc218 \uc788\ub2e4. \ub85c\ubc84\ud2b8 \ud53c\uce20\ub85c\uc774\uc758 1859\ub144 \uc548\ub0b4\uc11c\ub294 \uc774\ub7f0 \uc5ec\ub7ec \uae30\uad6c\ub97c \uc124\uba85\ud588\ub2e4. \uc870\uc9c0 \ud50c\ub9bc\ud504\ud134\uc758 1890\ub144 \uc544\ub124\ub85c\uc774\ub4dc \uae30\uc220\uc11c\uc5d0\ub3c4 \ub0b4\ubd80 \uc7a5\uce58\uac00 \ub098\ud0c0\ub09c\ub2e4. \ub465\uadfc \ub208\uae08\ud310\uc758 \uac04\ub2e8\ud55c \uc778\uc0c1 \ub4a4\uc5d0\ub294 \uc791\uc740 \ubcc0\ud615\uc744 \uc77d\uc744 \ub9cc\ud55c \uc6c0\uc9c1\uc784\uc73c\ub85c \ubc14\uafb8\ub294 \uc5f0\uacb0\uc774 \uc788\uc5c8\ub2e4. \uc544\ub124\ub85c\uc774\ub4dc \ub0b4\ubd80\uc758 \uc791\uc740 \uc6c0\uc9c1\uc784\uc740 \ub808\ubc84\uc640 \uc2a4\ud504\ub9c1 \uac19\uc740 \uc7a5\uce58\ub97c \uac70\uccd0 \ubc14\ub298\uc758 \ubcc0\ud654\ub85c \ub098\ud0c0\ub09c\ub2e4. \uc0ac\ub78c\uc774 \uc77d\uae30 \uc26c\uc6b4 \ub208\uae08\uc740 \uce21\uc815 \ub300\uc0c1\uc758 \ubcc0\ud654\uc640 \uc9c1\uc811 \uac19\uc740 \ud06c\uae30\uac00 \uc544\ub2c8\ub2e4. \uc791\uac8c \uc0dd\uae34 \ubc18\uc751\uc744 \uc5b4\ub5bb\uac8c \ud655\ub300\ud558\uace0 \uc77c\uc815\ud558\uac8c \uc804\ub2ec\ud560\uc9c0\uac00 \uae30\uad6c \uc81c\uc791\uc758 \ubb38\uc81c\uc600\ub2e4. \uc774\ub7f0 \uc7a5\uce58\ub294 \uc561\uccb4 \uae30\ub465\uacfc \ub2e4\ub978 \uc7a5\uc810\uc744 \uac00\uc9c0\uc9c0\ub9cc, \ub2e4\ub978 \ubc29\uc2dd\uc758 \uc624\ucc28\ub3c4 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \uae30\uad6c\ub97c \ube44\uad50\ud55c\ub2e4\ub294 \uac83\uc740 \uc5b4\ub290 \uac83\uc774 \ub354 \uba4b\uc9c4\uc9c0 \uace0\ub974\ub294 \uc77c\ubcf4\ub2e4 \uc5b4\ub290 \uc870\uac74\uc5d0\uc11c \uc548\uc815\uc801\uc73c\ub85c \uc77d\uc744 \uc218 \uc788\ub294\uc9c0 \ubb3b\ub294 \uc77c\uc774\ub2e4. \uc5ed\uc0ac \ub3c4\ud310\uc5d0\uc11c \uc548\ucabd \ubd80\ud488\uc774 \ub4dc\ub7ec\ub09c \ubaa8\uc2b5\uc744 \ubcf4\uba74, \ub2e8\uc21c\ud55c \ub465\uadfc \uacc4\uae30 \ub4a4\uc5d0 \uc5ec\ub7ec \ud798\uc758 \uade0\ud615\uc774 \ub193\uc5ec \uc788\uc74c\uc744 \uc54c \uc218 \uc788\ub2e4. \uacfc\ud559 \uae30\uae30\uc758 \uc81c\uc791\uc790\ub294 \uad00\uce21\uc790\uac00 \ud574\uc11d\ud560 \uc2e0\ud638\ub97c \ub9cc\ub4dc\ub294 \ub610 \ud558\ub098\uc758 \uad00\uce21 \uc870\uac74\uc744 \uc124\uacc4\ud588\ub2e4. \uae08\uc18d\uacfc \uc561\uccb4\ub294 \uc628\ub3c4\uc758 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4. \uae30\uae30\uc758 \uc0c1\ud0dc\uc640 \ubcf4\uc815\ub3c4 \uce21\uc815\uc5d0 \uad00\uacc4\ub41c\ub2e4. \ud53c\uce20\ub85c\uc774\ub294 \uc544\ub124\ub85c\uc774\ub4dc\ub97c \uc77d\uc744 \ub54c \uc790\uc138\ub97c \uc77c\uc815\ud558\uac8c \ud558\ub294 \ubb38\uc81c\uae4c\uc9c0 \uc5b8\uae09\ud588\ub2e4. \uc22b\uc790\ub97c \uc77d\ub294 \ub3d9\uc791\uc774 \uc27d\ub2e4\uace0 \uc815\ud655\ud55c \uce21\uc815\uc758 \uc870\uac74\ub3c4 \uc800\uc808\ub85c \uac16\ucdb0\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uae30\uae30\uc758 \ub208\uae08\uc774 \uc870\uae08 \ub2e4\ub974\ub2e4\uba74 \ub0a0\uc528\uac00 \ub3d9\uc2dc\uc5d0 \ub450 \uc885\ub958\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uce21\uc815 \uc7a5\uce58\uc758 \ucc28\uc774\ub97c \uba3c\uc800 \uac80\ud1a0\ud574\uc57c \ud560 \uc218 \uc788\ub2e4. \uad00\uce21\uc5d0\ub294 \ub300\uc0c1\uc744 \ubcf4\ub294 \uc77c\uacfc \ubcf4\ub294 \ub3c4\uad6c\ub97c \uc774\ud574\ud558\ub294 \uc77c\uc774 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4. \ub192\uc740 \uacf3\uacfc \ub0ae\uc740 \uacf3\uc758 \uae30\uc555\uc740 \ubcf4\ud1b5 \ub2e4\ub974\ub2e4. \uadf8\ub798\uc11c \uc5b4\ub290 \uc7a5\uc18c\uc758 \uc218\uce58\ub97c \ub2e4\ub978 \uc7a5\uc18c\uc640 \uadf8\ub300\ub85c \ube44\uad50\ud560 \ub54c\uc5d0\ub294 \uace0\ub3c4\ub97c \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \ub0ae\uc740 \uae30\uc555\uc774\ub77c\ub294 \ub9d0\ub9cc \ub4e3\uace0 \uace7\ubc14\ub85c \ud2b9\uc815 \ub0a0\uc528\ub97c \ub2e8\uc815\ud558\uba74 \uc7a5\uc18c\uc758 \ucc28\uc774\ub97c \ub0a0\uc528\uc758 \ucc28\uc774\ub85c \uc624\ud574\ud560 \uc218 \uc788\ub2e4. \uae30\uc555\uc744 \uc774\uc6a9\ud574 \ub192\uc774\ub97c \ucd94\uc815\ud558\ub294 \ubc29\ubc95\ub3c4 \uc774 \uad00\uacc4\uc640 \uc5f0\uacb0\ub41c\ub2e4. \ub2e4\ub9cc \ub0a0\uc528\uc5d0 \ub530\ub978 \uc555\ub825 \ubcc0\ud654\ub3c4 \uc788\uae30 \ub54c\ubb38\uc5d0 \ud558\ub098\uc758 \ub208\uae08\uc73c\ub85c \ubaa8\ub4e0 \ub192\uc774\ub97c \uc644\ubcbd\ud558\uac8c \uc54c \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac19\uc740 \uce21\uc815\uc774 \ub450 \uc9c8\ubb38\uc5d0 \uc4f0\uc77c \ub54c \uc11c\ub85c\uc758 \uc870\uac74\uc744 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ud53c\uce20\ub85c\uc774\uc758 \uc548\ub0b4\uc11c\ub294 \uae30\uc555\uc774 \uc624\ub974\uace0 \ub0b4\ub9ac\ub294 \ud750\ub984\uacfc \ubc14\ub78c \ub4f1\uc744 \ud568\uaed8 \ubcf4\ub3c4\ub85d \uc124\uba85\ud55c\ub2e4. \ud55c \ubc88 \uc77d\uc740 \uac12\uacfc \uc5ec\ub7ec \ubc88 \uc774\uc5b4 \uc77d\uc740 \ubcc0\ud654\ub294 \ub2e4\ub978 \uc815\ubcf4\ub97c \uc900\ub2e4. \uac19\uc740 \ub192\uc774\uc758 \ubc14\ub298\uc774\ub77c\ub3c4 \uadf8\uacf3\uae4c\uc9c0 \ub0b4\ub824\uc628 \uacbd\uc6b0\uc640 \uc62c\ub77c\uc628 \uacbd\uc6b0\uc758 \ub9e5\ub77d\uc774 \uac19\uc9c0\ub294 \uc54a\ub2e4. \uc774\ub294 \ubaa8\ub4e0 \uc0c1\uc2b9\uacfc \ud558\uac15\uc5d0 \ud558\ub098\uc758 \uacb0\uacfc\uac00 \uc815\ud574\uc838 \uc788\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uad00\uce21\uc790\ub294 \ub2e4\ub978 \uc790\ub8cc\uc640 \ud568\uaed8 \ubcc0\ud654\uc758 \uc758\ubbf8\ub97c \ud310\ub2e8\ud574\uc57c \ud55c\ub2e4. \uae30\uc555\uacc4\ub294 \ubbf8\ub798\ub97c \uc9c1\uc811 \ud45c\uc2dc\ud558\ub294 \ucc3d\ubcf4\ub2e4 \uc9c0\uae08\uae4c\uc9c0\uc758 \uc0c1\ud0dc\ub97c \uae30\ub85d\ud558\uace0 \ube44\uad50\ud558\uac8c \ud558\ub294 \ub3c4\uad6c\uc5d0 \uac00\uae5d\ub2e4. \ud53c\uce20\ub85c\uc774\uc758 \uae00\uc5d0\ub294 \ubc30\uc640 \uc120\uc6d0\uc5d0\uac8c \uae30\uc555\uacc4\uac00 \uc65c \uc720\uc6a9\ud55c\uc9c0\uac00 \ubc18\ubcf5\ub41c\ub2e4. \uc721\uc9c0\uc640 \ub2e4\ub978 \uc870\uac74\uc5d0\uc11c \ub0a0\uc528\uc758 \ubcc0\ud654\ub294 \ud56d\ud574\uc758 \uc911\uc694\ud55c \ubb38\uc81c\uc600\ub2e4. \uac19\uc740 \uc218\uce58\ub3c4 \uad00\uce21 \ubaa9\uc801\uc5d0 \ub530\ub77c \uc5b4\ub5a4 \ud310\ub2e8\uc5d0 \uc4f0\uc774\ub294\uc9c0\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uc61b \uc548\ub0b4\uc11c\uc5d0 \uc2e4\ub9b0 \ud2b9\uc815 \uc9c0\uc5ed\uc758 \uc22b\uc790\uc640 \ubc14\ub78c \uaddc\uce59\uc744 \uc624\ub298 \ubaa8\ub4e0 \ud574\uc5ed\uc5d0 \uadf8\ub300\ub85c \uc801\uc6a9\ud560 \uc218\ub294 \uc5c6\ub2e4. \uae00\uc740 \ub2f9\uc2dc\uc758 \uacbd\ud5d8\uacfc \uad00\uce21 \ud658\uacbd\uc744 \ubc14\ud0d5\uc73c\ub85c \uc4f0\uc600\ub2e4. \uc720\uc6a9\ud55c \uc5ed\uc0ac \uc790\ub8cc\ub97c \uc77d\ub294 \uc77c\uc740 \uadf8 \ubb38\uc7a5\uc744 \ud604\ub300\uc758 \ub9cc\ub2a5 \uc608\ubcf4 \uacf5\uc2dd\uc73c\ub85c \uc678\uc6b0\ub294 \uc77c\uacfc \ub2e4\ub974\ub2e4. \uae30\uc555\uacc4\uac00 \uc8fc\ub294 \uac83\uc740 \uc911\uc694\ud55c \ub2e8\uc11c\uc9c0\ub9cc \ub2e8\uc11c \ud558\ub098\uac00 \uc804\uccb4 \ub0a0\uc528\ub294 \uc544\ub2c8\ub2e4. \ubc14\ub78c\uacfc \uc628\ub3c4, \uc218\ubd84\uacfc \uc7a5\uc18c, \uc2dc\uac04\uc758 \ubcc0\ud654\ub97c \uc5f0\uacb0\ud574\uc57c \ud55c\ub2e4. \uce21\uc815\ud55c \uc0ac\uc2e4\uacfc \uadf8 \uc0ac\uc2e4\uc744 \ubc14\ud0d5\uc73c\ub85c \ub0b4\ub9b0 \ud574\uc11d\uc744 \uad6c\ubd84\ud558\uba74 \uad00\uce21\uc758 \uc758\ubbf8\uac00 \ub354 \ubd84\uba85\ud574\uc9c4\ub2e4. \uae30\uc555\uacc4\uc758 \uc5ed\uc0ac\ub294 \uacfc\ud559 \uae30\uae30\ub97c \uac00\uc9c4 \uac83\uacfc \uae30\uae30\ub97c \uc798 \uc0ac\uc6a9\ud558\ub294 \uac83\uc774 \ub2e4\ub974\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub208\uae08\ud310 \uc606\uc758 \uc9e7\uc740 \ub0b1\ub9d0\ubcf4\ub2e4 \uad00\uce21\uc758 \uc870\uac74\uacfc \uae30\ub85d\uc758 \ud750\ub984\uc5d0 \uad00\uc2ec\uc744 \uae30\uc6b8\uc5ec \ubcf4\uc790. \uad00\uce21 \uc77c\uc2dc\uc640 \uc7a5\uc18c\ub97c \ub0a8\uae30\ub294 \uc2b5\uad00\ub3c4 \uc218\uce58\ub97c \uc758\ubbf8 \uc788\ub294 \uae30\ub85d\uc73c\ub85c \ub9cc\ub4e0\ub2e4. \uc22b\uc790\ub97c \ub9ce\uc774 \ubaa8\uc73c\ub294 \uac83\uacfc \uc11c\ub85c \ube44\uad50\ud560 \uc218 \uc788\ub294 \uc790\ub8cc\ub97c \ub9cc\ub4dc\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294 \uacf5\uae30\ub294 \uadf8\ub807\uac8c \ud55c \ubc88\uc758 \uc22b\uc790\uc5d0\uc11c \uc774\uc5b4\uc9c0\ub294 \uc790\ub8cc\uac00 \ub41c\ub2e4."}, {"id": "boiling-water-mountain-pressure", "title": "\ub053\ub294 \ubb3c \u2014 \uc0b0\uc5d0\uc11c\ub294 \uc65c 100\ub3c4\ubcf4\ub2e4 \uba3c\uc800 \ub053\uc744\uae4c", "summary": "\uc0b0\uc7a5\uc758 \uc8fc\uc804\uc790\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc555\ub825\u00b7\ub053\ub294\uc810\u00b7\uc0c1\ud0dc \ubcc0\ud654\uc5d0 \ud544\uc694\ud55c \uc5f4\uc758 \ucc28\uc774\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\ubb3c\uc9c8\uacfc \uc5d0\ub108\uc9c0", "categories": ["science"], "url": "stories/boiling-water-mountain-pressure/index.html", "image": "../media/boiling-water-mountain-pressure.png", "alt": "\uc0b0\uc7a5\uc758 \uc5f4\ub9b0 \uc27c\ud130\uc5d0\uc11c \uc8fc\uc804\uc790\ub85c \ub530\ub73b\ud55c \uc74c\ub8cc\ub97c \uc900\ube44\ud558\ub294 \uc0ac\ub78c\uc758 \uc0bd\ud654.", "text": "\ub053\ub294 \ubb3c \u2014 \uc0b0\uc5d0\uc11c\ub294 \uc65c 100\ub3c4\ubcf4\ub2e4 \uba3c\uc800 \ub053\uc744\uae4c \ubd88\uc758 \uc138\uae30\uc640 \ubb3c\uc758 \ub053\ub294\uc810\uc744 \ub098\ub204\uc5b4 \uc0dd\uac01\ud558\uae30 \uc0b0\uc7a5\uc758 \uc8fc\uc804\uc790\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc555\ub825\u00b7\ub053\ub294\uc810\u00b7\uc0c1\ud0dc \ubcc0\ud654\uc5d0 \ud544\uc694\ud55c \uc5f4\uc758 \ucc28\uc774\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ubb3c\uc9c8\uacfc \uc5d0\ub108\uc9c0 \uacfc\ud559\uacfc \ubc1c\uacac \ub192\uc740 \uc0b0\uc5d0\uc11c \ubb3c\uc744 \ub053\uc778\ub2e4. \uc8fc\uc804\uc790\uc5d0\uc11c\ub294 \uae40\uc774 \uc624\ub974\uace0 \ubb3c\ub3c4 \ub053\ub294\ub370 \uc74c\uc2dd\uc774 \uc775\ub294 \ub290\ub08c\uc740 \ud3c9\uc18c\uc640 \ub2e4\ub97c \uc218 \uc788\ub2e4. \ub354 \ub192\uc740 \uacf3\uc5d0\uc11c \ub354 \ube68\ub9ac \ub053\ub294\ub2e4\uba74 \ubb3c\uc774 \ub354 \ub728\uac70\uc6cc\uc9c4 \uac83\uc77c\uae4c. \ub053\ub294\ub2e4\ub294 \ub9d0\uacfc \ub728\uac81\ub2e4\ub294 \ub9d0\uc744 \uac19\uc740 \ub73b\uc73c\ub85c \uc4f0\uba74 \uc774 \uc9c8\ubb38\uc774 \ud5f7\uac08\ub9b0\ub2e4. \uc6b0\ub9ac\uac00 \uc678\uc6b4 \ubb3c\uc758 \ub053\ub294\uc810 100\ub3c4\uc5d0\ub294 \uc870\uac74\uc774 \ubd99\uc5b4 \uc788\ub2e4. \uc8fc\ubcc0\uc758 \uc555\ub825\uc774\ub2e4. \uc8fc\ubc29\uacfc \uc0b0\uc7a5\uc5d0\uc11c \ub2ec\ub77c\uc9c0\ub294 \uac83\uc740 \ubd88\uaf43\ub9cc\uc774 \uc544\ub2c8\ub2e4. \ub208\uc5d0 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uacf5\uae30\uc758 \uc555\ub825\uc774 \ubb3c\uc774 \uc561\uccb4\uc5d0\uc11c \uae30\uccb4\ub85c \ubc14\ub00c\ub294 \uc870\uac74\uc5d0 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4. OpenStax\ub294 \uc21c\uc218\ud55c \ubb3c\uc758 \ub053\ub294\uc810\uc774 \ud45c\uc900\uc801\uc778 \ub300\uae30\uc555 1\uae30\uc555\uc5d0\uc11c \uc12d\uc528 100\ub3c4\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \uc555\ub825\uc774 \ubc14\ub00c\uba74 \ub053\ub294\uc810\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \ub530\ub77c\uc11c \ubb3c\uc774\ub77c\ub294 \uc774\ub984\ub9cc\uc73c\ub85c \uc5b4\ub290 \ud658\uacbd\uc5d0\uc11c\ub098 \ub611\uac19\uc740 \uc628\ub3c4\uc5d0 \ub053\ub294\ub2e4\uace0 \ud560 \uc218\ub294 \uc5c6\ub2e4. \uc2e4\uc81c \ubb3c\uc5d0\ub294 \ub2e4\ub978 \ubb3c\uc9c8\uc774 \ub179\uc544 \uc788\uc744 \uc218\ub3c4 \uc788\ub2e4. \uc774\ubc88\uc5d0\ub294 \uadf8 \uc601\ud5a5\uc744 \uc7a0\uc2dc \ube7c\uace0 \uc555\ub825\uc758 \uc5ed\ud560\uc5d0 \uc9d1\uc911\ud558\uc790. \uacfc\ud559\uc758 \uc22b\uc790\uc5d0 \uc870\uac74\uc744 \ubd99\uc774\ub294 \uc77c\uc740 \ub2f5\uc744 \ubcf5\uc7a1\ud558\uac8c \ub9cc\ub4e4\ub824\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \ud658\uacbd\uc5d0\uc11c \ub9de\ub294 \ub9d0\uc778\uc9c0 \uc54c\ub824 \uc8fc\uc5b4 \uac19\uc740 \ud604\uc0c1\uc744 \ub2e4\ub978 \uc7a5\uc18c\uc5d0\uc11c\ub3c4 \uc774\ud574\ud558\uac8c \ud558\ub294 \ubc29\ubc95\uc774\ub2e4. \uc816\uc740 \uc218\uac74\uc740 100\ub3c4\uac00 \ub418\uc9c0 \uc54a\uc544\ub3c4 \ub9c8\ub978\ub2e4. \uc561\uccb4\uc758 \uc77c\ubd80\uac00 \uae30\uccb4\ub85c \uc62e\uaca8 \uac00\ub294 \uc99d\ubc1c\uc774 \ub053\uc744 \ub54c\ub9cc \uc77c\uc5b4\ub098\ub294 \uac83\uc740 \uc544\ub2c8\uae30 \ub54c\ubb38\uc774\ub2e4. \uad50\uc7ac\ub294 \uc561\uccb4\uc640 \uae30\uccb4 \uc0ac\uc774\uc5d0\uc11c \ubd84\uc790\ub4e4\uc774 \uc624\uac00\uba70 \uae30\uccb4\uac00 \ub098\ud0c0\ub0b4\ub294 \uc99d\uae30\uc555\uc744 \uc124\uba85\ud55c\ub2e4. \uc628\ub3c4\uac00 \ub192\uc544\uc9c0\uba74 \ubb3c\uc774 \ub098\ud0c0\ub0b4\ub294 \uc99d\uae30\uc555\ub3c4 \ucee4\uc9c4\ub2e4. \ub053\ub294\uc810\uc740 \uc774 \uc99d\uae30\uc555\uc774 \uc8fc\ubcc0\uc5d0\uc11c \ub204\ub974\ub294 \uc555\ub825\uacfc \uac19\uc544\uc9c0\ub294 \uc870\uac74\uc73c\ub85c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc6a9\uc5b4\uac00 \ub0af\uc124\ub2e4\uba74 \ubb3c\uc774 \uae30\uccb4\ub85c \uc874\uc7ac\ud558\ub824\ub294 \uc870\uac74\uacfc \uc8fc\ubcc0\uc774 \ub204\ub974\ub294 \uc870\uac74\uc744 \ube44\uad50\ud55c\ub2e4\uace0 \uc0dd\uac01\ud574\ub3c4 \uc88b\ub2e4. \ub2e8\uc21c\ud788 \ubb3c\uc18d\uc5d0\uc11c \ubb34\uc5b8\uac00 \ubcf4\uc778\ub2e4\ub294 \ub9d0\uacfc\ub294 \ub2e4\ub978 \uae30\uc900\uc774\ub2e4. \ub192\uc740 \uc0b0\uc5d0\uc11c\ub294 \uc77c\ubc18\uc801\uc73c\ub85c \ub300\uae30\uc555\uc774 \ub0ae\ub2e4. \uadf8\ub798\uc11c \ubb3c\uc758 \uc99d\uae30\uc555\uc774 \uc8fc\ubcc0 \uc555\ub825\uc5d0 \ub3c4\ub2ec\ud558\ub294 \ub370 \ud544\uc694\ud55c \uc628\ub3c4\ub3c4 \ub0ae\uc544\uc9c4\ub2e4. \ubb3c\uc774 \ub354 \uac15\ud55c \ubd88\uc744 \ubc1b\uc544 \ud2b9\ubcc4\ud55c \uc131\uc9c8\ub85c \ubcc0\ud574\uc11c\uac00 \uc544\ub2c8\ub77c \ubc14\uae65 \uc870\uac74\uc774 \ub2ec\ub77c\uc9c4 \uacb0\uacfc\ub2e4. \uac19\uc740 \uc774\uc720\ub85c \uc0b0\uc5d0\uc11c \ub053\ub294 \ubb3c\uc774 \ud3c9\uc9c0\uc758 \ub053\ub294 \ubb3c\ubcf4\ub2e4 \ubc18\ub4dc\uc2dc \ub354 \ub728\uac70\uc6b4 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ud788\ub824 \ub0ae\uc740 \uc628\ub3c4\uc5d0\uc11c \ub053\uc744 \uc218 \uc788\ub2e4. \uad50\uc7ac\ub3c4 \uace0\ub3c4\uac00 \ub192\uc740 \uacf3\uc758 \ub0ae\uc740 \uc555\ub825\uacfc \ub053\ub294\uc810 \uc0ac\ub840\ub97c \uc81c\uc2dc\ud55c\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \uc0b0\uc7a5\uc758 \uc815\ud655\ud55c \uc628\ub3c4\ub97c \uc774 \uc6d0\ub9ac \ud558\ub098\ub85c \uc9c0\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc2e4\uc81c \uc555\ub825\uc740 \uc7a5\uc18c\uc640 \ub0a0\uc528 \ub4f1\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c4\ub2e4. \uc74c\uc2dd\uc744 \uc775\ud788\ub294 \ub370\ub294 \uc628\ub3c4\uc640 \uc2dc\uac04\uc774 \uc601\ud5a5\uc744 \uc900\ub2e4. \ub0ae\uc740 \uc628\ub3c4\uc5d0\uc11c \ub053\ub294 \ubb3c\uc740 \uae30\ud3ec\uac00 \ud65c\ubc1c\ud558\ub2e4\uace0 \ud3c9\uc9c0\uc640 \uac19\uc740 \uc628\ub3c4\uac00 \ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. \ub530\ub77c\uc11c \ub053\ub294 \ubaa8\uc2b5\uc744 \ubcf4\uace0 \uc870\ub9ac \uc870\uac74\uc774 \uac19\ub2e4\uace0 \ud310\ub2e8\ud558\uba74 \uc608\uc0c1\uacfc \ub2e4\ub978 \uacb0\uacfc\ub97c \ub9cc\ub0a0 \uc218 \uc788\ub2e4. \uc774\ubc88 \uc124\uba85\uc740 \ud2b9\uc815 \uc74c\uc2dd\uc758 \uc870\ub9ac \uc2dc\uac04\uc744 \uc81c\uc2dc\ud558\ub294 \uc548\ub0b4\uac00 \uc544\ub2c8\ub2e4. \ub053\ub294\ub2e4\ub294 \uc0c1\ud0dc\uc640 \uadf8\ub54c\uc758 \uc628\ub3c4\uac00 \ub2e4\ub978 \uc815\ubcf4\ub77c\ub294 \uc810\uc744 \uc774\ud574\ud558\ub294 \uc774\uc57c\uae30\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \ud604\uc0c1\uc774 \uac19\uc544\ub3c4 \uc218\uce58\uc758 \uc870\uac74\uc740 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc8fc\uc804\uc790 \ud558\ub098\uac00 \uc628\ub3c4\uacc4\uc640 \uae30\uc555\uc758 \uad00\uacc4\ub97c \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc555\ub825\uacfc \ubb3c\uc758 \uc131\ubd84\uc774 \uc77c\uc815\ud558\uace0 \uc561\uccb4\uac00 \uacc4\uc18d \ub053\ub294 \uc870\uac74\uc5d0\uc11c\ub294 \ub123\uc5b4 \uc900 \uc5f4\uc758 \uc0c1\ub2f9 \ubd80\ubd84\uc774 \ubb3c\uc744 \uae30\uccb4\ub85c \ubc14\uafb8\ub294 \ub370 \uc4f0\uc778\ub2e4. \uc628\ub3c4\ub9cc \uacc4\uc18d \uc62c\ub9ac\ub294 \ub370 \uc0ac\uc6a9\ub418\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc0c1\ud0dc \ubcc0\ud654\uc5d0\ub3c4 \uc5d0\ub108\uc9c0\uac00 \ud544\uc694\ud558\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uad50\uc7ac\ub294 \ubb3c\uc9c8\uc758 \uc628\ub3c4\ub97c \ubc14\uafb8\ub294 \uc77c\uacfc \uc0c1\ud0dc\ub97c \ubc14\uafb8\ub294 \ub370 \ud544\uc694\ud55c \uc5f4\uc744 \ub098\ub204\uc5b4 \uc124\uba85\ud55c\ub2e4. \ub530\ub77c\uc11c \ubd88\uc744 \uc138\uac8c \ud588\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ub053\ub294 \ubb3c\uc758 \uc628\ub3c4\uac00 \uac19\uc740 \ub9cc\ud07c \ub192\uc544\uc9c4\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc5f4\uc774 \uc5b4\ub514\ub85c \uc804\ub2ec\ub418\uace0 \uc5b4\ub5a4 \ubcc0\ud654\uc5d0 \uc4f0\uc774\ub294\uc9c0 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc555\ub825\uc1a5\uc740 \uc555\ub825\uc774 \ub192\uc740 \uc870\uac74\uc5d0\uc11c \ubb3c\uc758 \ub053\ub294\uc810\uc774 \uc62c\ub77c\uac08 \uc218 \uc788\ub2e4\ub294 \uc6d0\ub9ac\ub97c \uc774\uc6a9\ud55c\ub2e4. \ubb3c\uc744 \uc561\uccb4 \uc0c1\ud0dc\ub85c \uc720\uc9c0\ud558\uba74\uc11c \ub354 \ub192\uc740 \uc628\ub3c4\uc758 \uc870\ub9ac \ud658\uacbd\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub294 \uac83\uc774\ub2e4. \uc0b0\uc5d0\uc11c \ub0ae\uc740 \uc555\ub825\uc774 \ub053\ub294\uc810\uc744 \ub0ae\ucd94\ub294 \ud604\uc0c1\uacfc \uac19\uc740 \uad00\uacc4\ub97c \ubc18\ub300\ucabd\uc5d0\uc11c \ud65c\uc6a9\ud55c\ub2e4. \uc5ec\uae30\uc11c \ub69c\uaed1\ub9cc \ub36e\uc73c\uba74 \uc5b4\ub5a4 \ub0c4\ube44\ub098 \uac19\uc740 \ud6a8\uacfc\ub97c \ub0b8\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uc548 \ub41c\ub2e4. \uc555\ub825\uc744 \ub2e4\ub8e8\ub294 \uc804\uc6a9 \uae30\uad6c\ub294 \uadf8\uc5d0 \ub9de\uac8c \uc124\uacc4\ub418\uace0 \uc0ac\uc6a9\ub418\uc5b4\uc57c \ud55c\ub2e4. \uc774\ubc88 \uae00\uc740 \uc7a5\uce58\ub97c \uac1c\uc870\ud558\ub294 \ubc29\ubc95\ubcf4\ub2e4 \uc555\ub825\uc774\ub77c\ub294 \uc870\uac74\uc774 \ub053\ub294\uc810\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4\ub294 \uc6d0\ub9ac\ub97c \uc124\uba85\ud55c\ub2e4. \uc0b0\uc7a5 \uc8fc\uc804\uc790\ub97c \ubcf4\uba74 \uc5f4\uae30\uc640 \ub530\ub73b\ud55c \uc74c\ub8cc\ubd80\ud130 \ub290\uaef4\uc9c4\ub2e4. \uadf8 \uc7a5\uba74\uc5d0\uc11c \ubb34\uc5c7\uc774 \uce21\uc815\ub418\uc5c8\ub294\uc9c0 \ubb3c\uc73c\uba74 \ub2e4\ub978 \uc774\uc57c\uae30\uac00 \uc2dc\uc791\ub41c\ub2e4. \ub053\uace0 \uc788\ub2e4\ub294 \uad00\ucc30\uacfc \uc8fc\ubcc0 \uc555\ub825, \uc2e4\uc81c \ubb3c\uc758 \uc628\ub3c4\ub294 \uc11c\ub85c \uc5f0\uacb0\ub418\uc9c0\ub9cc \uac01\uac01 \ud655\uc778\ud574\uc57c \ud560 \uc815\ubcf4\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc0b0\uc5d0\uc11c \ub530\ub73b\ud55c \uc74c\ub8cc\ub97c \uc900\ube44\ud558\ub294 \uc0c1\uc0c1 \uc18d \uc7a5\uba74\uc774\ub2e4. \ud2b9\uc815 \uace0\ub3c4\uc758 \ub053\ub294\uc810 \uc2e4\ud5d8\uc774\ub098 \uc870\ub9ac \uae30\uad6c\uc758 \uc2e4\uc81c \uc131\ub2a5\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub9bc\uc5d0\ub294 \ubd84\uc704\uae30\ub97c, \uc6d0\ubb38 \uc790\ub8cc\uc5d0\ub294 \uc6d0\ub9ac\uc758 \uadfc\uac70\ub97c \ub9e1\uaca8 \uc77d\uc73c\uba74 \ub41c\ub2e4. \ubb3c\uc740 100\ub3c4\uc5d0\uc11c \ub053\ub294\ub2e4\ub294 \ubb38\uc7a5\uc5d0 \ud45c\uc900 \ub300\uae30\uc555\uc774\ub77c\ub294 \uc870\uac74\uc744 \ubd99\uc774\uba74 \uc0b0\uc7a5\uc758 \uacbd\ud5d8\uc774 \ub354 \uc774\uc0c1 \uc608\uc678\uc801\uc778 \uc218\uc218\uaed8\ub07c\uac00 \uc544\ub2c8\ub2e4. \uac19\uc740 \uc6d0\ub9ac\uac00 \ub2e4\ub978 \uc555\ub825\uc5d0\uc11c \ub2e4\ub978 \uc628\ub3c4\ub85c \ub098\ud0c0\ub09c \uac83\uc774\ub2e4. \ubc30\uc6b4 \uaddc\uce59\uc744 \ubc84\ub9ac\ub294 \ub300\uc2e0 \uaddc\uce59\uc774 \ub73b\ud558\ub294 \ubc94\uc704\ub97c \ub354 \uc815\ud655\ud788 \uc54c\uac8c \ub41c\ub2e4. \ub2e4\uc74c\uc5d0 \ubb3c\uc774 \ub053\ub294 \ubaa8\uc2b5\uc744 \ub9cc\ub098\uba74 \ubd88\uaf43\uc758 \ud06c\uae30\ub9cc \ubcf4\uc9c0 \ub9d0\uace0 \ubb3c\uc774 \ub193\uc778 \ud658\uacbd\ub3c4 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc5f4\uc744 \ub354 \uc8fc\ub294 \uc77c\uacfc \ub053\ub294\uc810\uc744 \ubc14\uafb8\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uc775\uc219\ud55c \uc8fc\uc804\uc790\ub294 \uc628\ub3c4\uc640 \uc555\ub825, \uc0c1\ud0dc \ubcc0\ud654\uac00 \uc77c\uc0c1\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ud568\uaed8 \uc791\ub3d9\ud558\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \uc791\uc740 \uc2e4\ud5d8\uc2e4\uc774\ub2e4."}, {"id": "bowl-sundial", "title": "\uadf8\ub987\ucc98\ub7fc \uc0dd\uae34 \ud574\uc2dc\uacc4\uc5d0\ub294 \ub450 \uc885\ub958\uc758 \uc120\uc774 \uc788\ub2e4", "summary": "\uc624\ubaa9\ud55c \ud574\uc2dc\uacc4 \uc548\uc744 \ubcf4\uba74 \uc5ec\ub7ec \uc120\uc774 \uad50\ucc28\ud569\ub2c8\ub2e4. \ubaa8\ub450 \uac19\uc740 \uc77c\uc744 \ud558\ub294 \uc120\uc740 \uc544\ub2d9\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\ubb3c\uc9c8\uacfc \uc5d0\ub108\uc9c0", "categories": ["science"], "url": "stories/bowl-sundial/index.html", "image": "../media/bowl-sundial.jpg", "alt": "\ubc1b\uce68 \uc704\uc5d0 \ub193\uc778 \uccad\ub3d9 \ubc18\uad6c\ud615 \uc559\ubd80\uc77c\uad6c\uc640 \uc548\ucabd \uc120, \uc601\uce68\uc774 \ubcf4\uc774\ub294 \uc0ac\uc9c4", "text": "\uadf8\ub987\ucc98\ub7fc \uc0dd\uae34 \ud574\uc2dc\uacc4\uc5d0\ub294 \ub450 \uc885\ub958\uc758 \uc120\uc774 \uc788\ub2e4 \uc559\ubd80\uc77c\uad6c \uc548\uc5d0\uc11c \uc2dc\uac04\uacfc \uacc4\uc808\uc744 \uc77d\ub294 \ubc29\ubc95 \uc624\ubaa9\ud55c \ud574\uc2dc\uacc4 \uc548\uc744 \ubcf4\uba74 \uc5ec\ub7ec \uc120\uc774 \uad50\ucc28\ud569\ub2c8\ub2e4. \ubaa8\ub450 \uac19\uc740 \uc77c\uc744 \ud558\ub294 \uc120\uc740 \uc544\ub2d9\ub2c8\ub2e4. \ubb3c\uc9c8\uacfc \uc5d0\ub108\uc9c0 \uacfc\ud559\uacfc \ubc1c\uacac \ubc15\ubb3c\uad00\uc5d0\uc11c \uc559\ubd80\uc77c\uad6c\ub97c \ubcf4\uba74 \uba3c\uc800 \uadf8\ub987 \uac19\ub2e4\ub294 \uc0dd\uac01\uc774 \ub4e0\ub2e4. \uac00\uc6b4\ub370\uc5d0\ub294 \ubc14\ub298\ucc98\ub7fc \uc0dd\uae34 \ubb3c\uac74\uc774 \ube44\uc2a4\ub4ec\ud788 \uc11c \uc788\uace0, \uc548\ucabd\uc5d0\ub294 \uc5ec\ub7ec \uc904\uc774 \uc0c8\uaca8\uc838 \uc788\ub2e4. \uc774\ub984\uc5d0\ub3c4 \uadf8 \ubaa8\uc2b5\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc740 \uc559\ubd80\uc77c\uad6c\ub97c \uc1a5 \ubaa8\uc591\uc758 \ud574\uc2dc\uacc4\ub77c\ub294 \ub73b\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \uc775\uc219\ud55c \ub514\uc9c0\ud138\uc2dc\uacc4\ucc98\ub7fc \uc22b\uc790\uac00 \ucc28\ub840\ub85c \ubc14\ub00c\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub300\uc2e0 \ube5b\uacfc \uadf8\ub9bc\uc790\uac00 \ud45c\uc2dc\ub97c \uc6c0\uc9c1\uc778\ub2e4. \uadf8\ub7f0\ub370 \uc548\ucabd\uc758 \uc120\uc740 \uc2dc\uac04\uc744 \ub098\ub204\uae30 \uc704\ud55c \uac83\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uacc4\uc808\uc744 \uc54c\ub824\uc8fc\ub294 \uc120\ub3c4 \ud568\uaed8 \uc788\ub2e4. \uc559\ubd80\uc77c\uad6c\ub294 \ud574\uadf8\ub9bc\uc790\ub97c \ubc1b\ub294 \uc624\ubaa9\ud55c \uba74\uacfc, \uadf8\ub9bc\uc790\ub97c \ub9cc\ub4e4\uc5b4 \ub0b4\ub294 \ubc14\ub298\ub85c \uc774\ub8e8\uc5b4\uc9c4\ub2e4. \ub3c4\uad6c\ub97c \ubcfc \ub54c\ub294 \ubc14\ub298\ub9cc\ud07c \uadf8\ub9bc\uc790\uac00 \uc5b4\ub514\uc5d0 \ub4dc\ub9ac\uc6cc\uc9c0\ub294\uc9c0\ub3c4 \uc911\uc694\ud558\ub2e4. \ubc15\ubb3c\uad00 \uc18c\uc7a5\ud488 \uc124\uba85\uc5d0\uc11c\ub294 \uc548\ucabd \uba74\uc744 \uc2dc\ubc18, \ubc14\ub298\uc744 \uc601\uce68\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \uc5b4\ub824\uc6b4 \uc774\ub984\uc744 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uc5ed\ud560\uc740 \ub098\ub204\uc5b4 \ubcfc \uc218 \uc788\ub2e4. \ud558\ub098\ub294 \uadf8\ub9bc\uc790\ub97c \ub9cc\ub4e4\uace0, \ub2e4\ub978 \ud558\ub098\ub294 \uadf8 \uadf8\ub9bc\uc790\ub97c \uc77d\ub294 \uc790\ub9ac\ub2e4. \ube5b\uc774 \ub4e4\uc5b4\uc624\ub294 \uc870\uac74\uc5d0 \ub530\ub77c \ubc14\ub298\uc758 \uadf8\ub9bc\uc790\uac00 \ub193\uc774\ub294 \uc704\uce58\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uc548\ucabd\uc5d0 \uc0c8\uaca8 \ub454 \uc120\ub4e4\uc740 \uadf8 \uc704\uce58\ub97c \uadf8\ub0e5 \uc9c0\ub098\uac00\ub294 \ubaa8\uc591\uc774 \uc544\ub2c8\ub77c \uc815\ubcf4\ub85c \uc77d\uc744 \uc218 \uc788\uac8c \ud55c\ub2e4. \uc18c\uc7a5\ud488 \uc124\uba85\uc5d0 \ub530\ub974\uba74 \uc2dc\uacc4 \uc548\uc5d0\ub294 \uc2dc\uac01\uc744 \ub098\ub204\ub294 \uc120\uacfc \uc808\uae30\ub97c \ub098\ud0c0\ub0b4\ub294 \uac00\ub85c\uc120\uc774 \uc788\ub2e4. \uac19\uc740 \uba74 \uc704\uc5d0 \ub450 \uc885\ub958\uc758 \uae30\uc900\uc744 \uacb9\uccd0 \ub454 \uac83\uc774\ub2e4. \uacc4\uc808\uc5d0 \ub530\ub77c \ud574\uadf8\ub9bc\uc790\uc758 \uae38\uc774\uac00 \ub2ec\ub77c\uc9c0\ubbc0\ub85c, \ub3d9\uc9c0\uc640 \ud558\uc9c0\uc758 \uadf8\ub9bc\uc790\ub3c4 \uac19\uc740 \uc790\ub9ac\uc5d0 \ub193\uc774\uc9c0 \uc54a\ub294\ub2e4. \ubc15\ubb3c\uad00\uc740 \ub3d9\uc9c0\uc5d0\ub294 \uac00\uc7a5 \ubc14\uae65\ucabd \uacc4\uc808\uc120, \ud558\uc9c0\uc5d0\ub294 \uac00\uc7a5 \uc548\ucabd \uacc4\uc808\uc120\uc5d0 \uadf8\ub9bc\uc790\uac00 \uc704\uce58\ud55c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\ub7ec\ub2c8 \ubc14\ub2e5\uc758 \uc120\uc744 \ubaa8\ub450 \ubcf5\uc7a1\ud55c \uc7a5\uc2dd\uc73c\ub85c \ubcfc \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5b4\ub290 \ubc29\ud5a5\uc73c\ub85c \uc2dc\uac04\uc744 \uc77d\uace0 \uc5b4\ub5a4 \uc120\uc73c\ub85c \uacc4\uc808\uc744 \uc0b4\ud53c\ub294\uc9c0 \ub098\ub204\uc5b4 \ubcf4\uba74 \uc870\uae08 \uc815\ub9ac\uac00 \ub41c\ub2e4. \uc22b\uc790\uc640 \uace1\uc120\uc774 \ub9ce\uc740 \uc774\uc720\uac00 \uc788\ub294 \uc148\uc774\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4 \ud55c \uc7a5\ub9cc \ubcf4\uace0 \uc2e4\uc81c \uc2dc\uac04\uc744 \uc815\ud655\ud558\uac8c \uc77d\uc5b4 \ubcf4\ub824 \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub193\uc778 \ubc29\ud5a5\uacfc \ube5b\uc758 \uc870\uac74\uc774 \ub9de\uc544\uc57c \ud558\ub294 \ub3c4\uad6c\ub2e4. \uc804\uc2dc\uc7a5\uc5d0\uc11c \ubcf4\ub294 \ubaa8\uc2b5\uacfc \uc2e4\uc81c\ub85c \uc2dc\uac04\uc744 \uc7ac\ub294 \uc0c1\ud669\uc740 \uad6c\ubd84\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc559\ubd80\uc77c\uad6c\uc758 \uc624\ubaa9\ud55c \uba74\uc740 \ubb34\uc5c7\uc744 \ub2f4\ub294 \uadf8\ub987\uc758 \uc548\ucabd\uacfc \ub2ee\uc558\uc9c0\ub9cc \uadf8\ub9bc\uc790\uc758 \uc704\uce58\ub97c \uc77d\ub3c4\ub85d \uc900\ube44\ud55c \uc790\ub9ac\ub2e4. \ud45c\uba74\uc5d0 \uc120\uc774 \uc788\uace0 \uadf8 \uc704\uc5d0 \ubc14\ub298\uc758 \uadf8\ub9bc\uc790\uac00 \ub193\uc778\ub2e4. \ub3c4\uad6c\uc758 \ud615\ud0dc\uc640 \uae30\uc900\uc758 \ud45c\uc2dc, \ube5b\uc774 \ud568\uaed8 \uc788\uc5b4\uc57c \uc815\ubcf4\uac00 \ub41c\ub2e4. \ubb3c\uac74\ub9cc \uc788\ub2e4\uace0 \uc5b8\uc81c \uc5b4\ub514\uc11c\ub4e0 \uace7\ubc14\ub85c \uac19\uc740 \ub2f5\uc744 \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc601\uce68\uc774 \ubd81\uadf9 \ucabd\uc744 \ud5a5\ud558\ub3c4\ub85d \ub193\uc778\ub2e4\ub294 \uc124\uba85\ub3c4 \uadf8\ub798\uc11c \uc911\uc694\ud558\ub2e4. \uc7a5\uc2dd\uc774 \ub9c8\uc74c\uc5d0 \ub4dc\ub294 \ubc29\ud5a5\uc73c\ub85c \ub3cc\ub824 \ub193\ub294 \uac83\uacfc \uc2dc\uac04\uc744 \uc7ac\uae30 \uc704\ud574 \ubc29\ud5a5\uc744 \ub9de\ucd94\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uc804\uc2dc\uc7a5\uc5d0\uc11c \ubcf4\uc774\ub294 \ub3c4\uad6c\uc640 \uc2e4\uc81c \uc57c\uc678 \uce21\uc815\uc758 \uc870\uac74\uc744 \uad6c\ubd84\ud558\uba74, \uc0ac\uc9c4\uc758 \uadf8\ub9bc\uc790\ub97c \uadf8\ub300\ub85c \ud604\uc7ac \uc2dc\uac01\uc774\ub77c\uace0 \uc77d\ub294 \uc624\ub958\ub97c \ud53c\ud560 \uc218 \uc788\ub2e4. \uc790\ub8cc\ub294 \uc5f4\uc138 \uac1c\uc758 \uacc4\uc808\uc120\uc73c\ub85c \uc2a4\ubb3c\ub124 \uc808\uae30\uc640 \uad00\ub828\ub41c \uc815\ubcf4\ub97c \ud45c\ud604\ud55c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc22b\uc790\uac00 \ub2e4\ub974\ub2e4\uace0 \uace7 \uc798\ubabb \uc801\ud78c \uac83\uc740 \uc544\ub2c8\ub2e4. \ud55c \ud574 \ub3d9\uc548 \ud574\uac00 \ub192\uc544\uc84c\ub2e4\uac00 \ub0ae\uc544\uc9c0\ub294 \ud750\ub984\uc744 \uc0dd\uac01\ud558\uba74 \ube44\uc2b7\ud55c \uadf8\ub9bc\uc790 \uc870\uac74\uc744 \uc77c \ub144\uc758 \uc11c\ub85c \ub2e4\ub978 \ub54c\uc5d0 \ub9cc\ub0a0 \uc218 \uc788\ub2e4. \ubaa8\ub4e0 \uc808\uae30\uc5d0 \ub3c5\ub9bd\ub41c \uc120 \ud558\ub098\uc529\uc774 \uaf2d \ud544\uc694\ud55c \uad6c\uc870\ub294 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c \uc804\uccb4 \ucc9c\ubb38 \uacc4\uc0b0\uc744 \uc0c8\ub85c \uc99d\uba85\ud558\uac70\ub098 \uc774 \uc0ac\uc9c4\ub9cc\uc73c\ub85c \ub0a0\uc9dc\ub97c \uc0b0\ucd9c\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc120\ub4e4\uc774 \ub9e1\uc740 \uc5ed\ud560\uc774 \ub2e4\ub974\ub2e4\ub294 \uc774\ud574\uac00 \uba3c\uc800\ub2e4. \uc2dc\uac01\uc744 \ub098\ub204\ub294 \uae30\uc900\uacfc \uacc4\uc808\uc744 \uac00\ub9ac\ud0a4\ub294 \uae30\uc900\uc744 \ubd84\ub9ac\ud574\uc11c \ubcf4\uba74 \ubcf5\uc7a1\ud558\uac8c \uc5bd\ud78c \ubb34\ub2ac\uac00 \uc870\uae08 \uc815\ub9ac\ub41c\ub2e4. \uc5ec\ub7ec \uc815\ubcf4\ub97c \ud55c \ud45c\uba74\uc5d0\uc11c \uc77d\uac8c \ub9cc\ub4e0 \uc124\uacc4\uc758 \uc0ac\ub840\ub2e4. \uacc4\uc808\uc5d0 \ub530\ub77c \ud574\uadf8\ub9bc\uc790\uac00 \ub2ec\ub77c\uc9c0\uae30 \ub54c\ubb38\uc5d0 \uc2dc\uac04\ub9cc \uac19\uc740 \ub0a0\ub4e4\uc744 \ud55c \uac00\uc9c0 \uc120\uc73c\ub85c \uc0dd\uac01\ud558\uae30 \uc5b4\ub835\ub2e4. \ubc15\ubb3c\uad00\uc774 \ub3d9\uc9c0\uc120\uacfc \ud558\uc9c0\uc120\uc758 \uc704\uce58\ub97c \ub530\ub85c \uc9da\uc5b4 \uc8fc\ub294 \uc774\uc720\ub2e4. \ud558\ub8e8 \ub3d9\uc548 \uc6c0\uc9c1\uc774\ub294 \uadf8\ub9bc\uc790\uc640 \ud55c \ud574\ub97c \ub530\ub77c \ub2ec\ub77c\uc9c0\ub294 \uc870\uac74\uc774 \uac19\uc740 \ub3c4\uad6c\uc5d0 \ub2f4\uae34\ub2e4. \uc791\uc740 \uc2dc\uacc4\uac00 \uc77c\uc0c1\uc758 \uc2dc\uac04\uacfc \uacc4\uc808\uc758 \uc2dc\uac04\uc744 \ud568\uaed8 \ub2e4\ub8e8\ub294 \uc148\uc774\ub2e4. \uc774 \uc810\uc744 \uc54c\uba74 \ud574\uc2dc\uacc4\uac00 \ub2e8\uc21c\ud788 \ub9c9\ub300 \ud558\ub098\uc758 \uadf8\ub9bc\uc790\ub97c \ubcf4\ub294 \uac83\ub9cc\uc740 \uc544\ub2d8\uc744 \ub290\ub084 \uc218 \uc788\ub2e4. \ud45c\uba74\uc744 \uc5b4\ub5a4 \ud615\ud0dc\ub85c \ub9cc\ub4e4\uace0 \uae30\uc900\uc744 \uc5b4\ub5bb\uac8c \uc0c8\uae38\uc9c0\uc758 \uc120\ud0dd\uc774 \uc788\uc5c8\ub2e4. \ub2e4\ub9cc \ub2e4\ub978 \ud574\uc2dc\uacc4\uc758 \ud45c\uc2dc\ubc95\uc744 \ubaa8\ub450 \uc774 \ud55c \uc810\uacfc \uac19\ub2e4\uace0 \uc77c\ubc18\ud654\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uad6c\uccb4\uc801\uc778 \uc18c\uc7a5\ud488\uc758 \uc124\uba85\uc744 \uae30\uc900\uc73c\ub85c \ub3c4\uad6c\uc758 \uad6c\uc870\ub97c \uc0b4\ud3b4\ubcf4\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc559\ubd80\uc77c\uad6c\uac00 \uc138\uc885\ub300\uc5d0 \ucc98\uc74c \ub9cc\ub4e4\uc5b4\uc838 \uc11c\uc6b8\uc758 \ud61c\uc815\uad50\uc640 \uc885\ubb18 \ub0a8\ucabd \uac70\ub9ac\ucc98\ub7fc \uc0ac\ub78c\uc774 \ub9ce\uc774 \ub2e4\ub2c8\ub294 \uacf3\uc5d0 \uc124\uce58\ub418\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uac1c\uc778\uc758 \uc791\uc740 \ubb3c\uac74\uc774 \uc544\ub2c8\ub77c \uae38\uc5d0\uc11c \uc2dc\uac04\uc744 \ub9cc\ub098\ub294 \ubc29\uc2dd\ub3c4 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4. \uc9c0\uae08\uc740 \uc8fc\uba38\ub2c8\uc758 \ud654\uba74\ub9cc \uc5f4\uc5b4\ub3c4 \uc2dc\uac04\uc744 \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \ud558\ub098\uc758 \uc2dc\uacc4\ub97c \uc5ec\ub7ec \uc0ac\ub78c\uc774 \ubc14\ub77c\ubcf4\ub294 \ud48d\uacbd\uc774 \uc870\uae08 \ub0af\uc124\uac8c \ub290\uaef4\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \uc559\ubd80\uc77c\uad6c\ub97c \ub2e4\uc2dc \ubcf4\uba74 \uadf8\ub987 \uac19\uc740 \ubab8\uccb4 \uc548\uc5d0 \uadf8 \ud48d\uacbd\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ud574\ub97c \ubcf4\uace0 \ubc14\ub298\uc758 \uadf8\ub9bc\uc790\ub97c \ucc3e\uace0, \uc120\uc744 \ub530\ub77c \uc2dc\uac04\uc744 \uc77d\ub294 \uc0ac\ub78c\ub4e4\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \uc774 \ud574\uc2dc\uacc4\ub97c \ub9cc\ub098\uba74 \ubc14\ub298\uacfc \uace1\uc120\uc744 \ub530\ub85c \ud55c\ubc88 \ubcf4\uc544\ub3c4 \uc88b\uaca0\ub2e4. \ubcf5\uc7a1\ud574 \ubcf4\uc774\ub358 \uc548\ucabd \uba74\uc774, \uc2dc\uac04\uacfc \uacc4\uc808\uc744 \ud568\uaed8 \ud3bc\uccd0 \ub193\uc740 \uc791\uc740 \uc9c0\ub3c4\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\ub2e4."}, {"id": "braille-six-dots", "title": "\uc5ec\uc12f \uac1c\uc758 \uc810\uc73c\ub85c \uc5bc\ub9c8\ub098 \ub9ce\uc740 \ubaa8\uc591\uc744 \ub9cc\ub4e4\uae4c", "summary": "6\uc810 \uc810\uc790\uc5d0\uc11c \uc810\uc758 \uc218\ubcf4\ub2e4 \uc704\uce58\uac00 \uc911\uc694\ud558\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubd05\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uc218\ud559\uacfc \uce21\uc815", "categories": ["science"], "url": "stories/braille-six-dots/index.html", "image": "../media/braille-six-dots.jpg", "alt": "6\uc810 \uc810\uc790\uc758 \uc67c\ucabd \uc810\uc740 \uc704\uc5d0\uc11c 1\u00b72\u00b73\ubc88, \uc624\ub978\ucabd\uc740 4\u00b75\u00b76\ubc88\uc785\ub2c8\ub2e4. a\ub294 1\ubc88, b\ub294 1\u00b72\ubc88, c\ub294 1\u00b74\ubc88 \uc810\uc73c\ub85c \ud45c\uc2dc\ud55c \ub77c\ud2f4 \ubb38\uc790 \uc608\uc785\ub2c8\ub2e4.", "text": "\uc5ec\uc12f \uac1c\uc758 \uc810\uc73c\ub85c \uc5bc\ub9c8\ub098 \ub9ce\uc740 \ubaa8\uc591\uc744 \ub9cc\ub4e4\uae4c \uc810\uc790 \ud55c \uce78\uc5d0\uc11c \uc2dc\uc791\ud558\ub294 \uc870\ud569 \uc774\uc57c\uae30 6\uc810 \uc810\uc790\uc5d0\uc11c \uc810\uc758 \uc218\ubcf4\ub2e4 \uc704\uce58\uac00 \uc911\uc694\ud558\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubd05\ub2c8\ub2e4. \uc218\ud559\uacfc \uce21\uc815 \uacfc\ud559\uacfc \ubc1c\uacac \uc810 \uc5ec\uc12f \uac1c\uac00 \uc138\ub85c\ub85c \uc138 \uac1c\uc529, \ub450 \uc904\ub85c \ub098\ub780\ud788 \ub193\uc5ec \uc788\ub2e4. \uc5b4\ub5a4 \uc810\uc740 \uc62c\ub77c\uc624\uace0 \uc5b4\ub5a4 \uc790\ub9ac\ub294 \ube44\uc5b4 \uc788\ub2e4. \ud55c \uce78 \uc548\uc5d0\uc11c \uc774 \ucc28\uc774\ub97c \uc870\ud569\ud558\uba74 \uc11c\ub85c \ub2e4\ub978 \ubaa8\uc591\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4. 6\uc810 \uc810\uc790\ub97c \uc0dd\uac01\ud558\ub294 \uc791\uc740 \ucd9c\ubc1c\uc810\uc774\ub2e4. \uadf8\uc800 \uc810\uc774 \uba87 \uac1c \uc788\ub294\uc9c0\ub9cc \uc138\uba74 \ub193\uce58\ub294 \ubd80\ubd84\uc774 \uc788\ub2e4. \uc810\uc774 \ud558\ub098\ub77c\ub3c4 \uc5b4\ub290 \uc790\ub9ac\uc5d0 \uc788\ub294\uc9c0\uc5d0 \ub530\ub77c \ubaa8\uc591\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uac1c\uc218\uc640 \uc704\uce58\ub294 \uac19\uc740 \uc815\ubcf4\uac00 \uc544\ub2cc \uac83\uc774\ub2e4. \uac01 \uc790\ub9ac\uc5d0\ub294 \uc62c\ub77c\uc628 \uc810\uc774 \uc788\uac70\ub098 \uc5c6\ub2e4. \ub450 \uac00\uc9c0 \uc120\ud0dd\uc774\ub2e4. \uadf8\ub7f0 \uc790\ub9ac\uac00 \uc5ec\uc12f \uac1c\uba74 \uac00\ub2a5\ud55c \uc870\ud569\uc740 2\ub97c \uc5ec\uc12f \ubc88 \uacf1\ud55c 64\uac00\uc9c0\ub2e4. \uc544\ubb34 \uc810\ub3c4 \uc5c6\ub294 \uacbd\uc6b0\ub97c \ube7c\uba74 \uc810\uc774 \ud558\ub098 \uc774\uc0c1 \uc788\ub294 \ud615\ud0dc\ub294 63\uac00\uc9c0\uac00 \ub41c\ub2e4. \uc774\uac83\uc740 \uc810\uc790 \uc804\uccb4\uc758 \ub73b\uc774 63\uac1c\ubfd0\uc774\ub77c\ub294 \ub9d0\uc774 \uc544\ub2c8\ub2e4. \ud55c \uce78\uc758 \ubaa8\uc591\uc744 \uc138\uc5b4 \ubcf8 \uacc4\uc0b0\uc774\ub2e4. \uc5ec\ub7ec \uce78\uc744 \uc774\uc5b4 \uc77d\uace0 \ubb38\ub9e5\uacfc \uaddc\uce59\uc744 \uc801\uc6a9\ud558\ub294 \uc77c\uc740 \uadf8\ub2e4\uc74c\uc5d0 \uc788\ub2e4. \uc810\uc790 \ubcc0\ud658 \ud504\ub85c\uc81d\ud2b8 Liblouis\uc758 \ub77c\ud2f4 \ubb38\uc790 \uc815\uc758\ub97c \ubcf4\uba74 \uc18c\ubb38\uc790 a\ub294 1\ubc88 \uc810, b\ub294 1\ubc88\uacfc 2\ubc88 \uc810\uc73c\ub85c \ub098\ud0c0\ub09c\ub2e4. c\ub294 1\ubc88\uacfc 4\ubc88 \uc810\uc774\ub2e4. b\uc640 c\ub294 \uc810 \ub450 \uac1c\ub77c\ub294 \uc810\uc5d0\uc11c\ub294 \uac19\uc9c0\ub9cc \ubc30\uce58\uac00 \ub2e4\ub974\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc124\uba85\ub3c4\ub294 \uc774 \uc138 \uac00\uc9c0\ub97c \ub098\ub780\ud788 \ubcf4\uc5ec \uc900\ub2e4. \uae00\uc790 \uc774\ub984\uacfc \uc810 \ubc88\ud638\ub97c \ubd99\uc5ec \uc704\uce58\uc758 \ucc28\uc774\ub97c \ud655\uc778\ud558\ub3c4\ub85d \ub9cc\ub4e4\uc5c8\ub2e4. \uc2e4\uc81c \uc77d\uae30\uc5d0 \ud544\uc694\ud55c \ubaa8\ub4e0 \uc810\uc790 \uaddc\uce59\uc744 \ub300\uc2e0\ud558\ub294 \ud45c\ub294 \uc544\ub2c8\ub2e4. b\uc640 c\ub294 \ub458 \ub2e4 \uc810 \ub450 \uac1c\ub97c \uc4f0\uc9c0\ub9cc \ub193\uc774\ub294 \uc790\ub9ac\uac00 \ub2e4\ub974\ub2e4. \ub530\ub77c\uc11c \uac00\ub2a5\ud55c \ubaa8\uc591\uc744 \uc140 \ub54c \uc810\uc774 \uba87 \uac1c\uc778\uc9c0\ub9cc \uc138\uba74 \ubd80\uc871\ud558\ub2e4. \uc5ec\uc12f \uc790\ub9ac \uac01\uac01\uc5d0\uc11c \uc810\uc758 \uc720\ubb34\ub97c \ubcf4\uc544\uc57c \ud55c\ub2e4. \uac19\uc740 \uac1c\uc218\uc758 \uc810\ub3c4 \ub2e4\ub978 \ubc30\uc5f4\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ubb38\uc790 \ud45c\uae30\uc758 \uacf5\uac04\uc801\uc778 \uc131\uaca9\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc774\ub294 \uc8fc\uc0ac\uc704\uc758 \uc22b\uc790\ub97c \uc54c\uc544\ubcf4\ub294 \uacbd\ud5d8\uacfc \ub2ee\uc740 \uc810\uc774 \uc788\uc9c0\ub9cc \uac19\uc740 \uccb4\uacc4\ub294 \uc544\ub2c8\ub2e4. \uc8fc\uc0ac\uc704\uc758 \ubaa8\ub4e0 \ubc30\uce58\ub97c \ubb38\uc790\ub85c \uc77d\ub294 \uac83\uc740 \uc544\ub2c8\uae30 \ub54c\ubb38\uc774\ub2e4. \uc775\uc219\ud55c \uc608\ub294 \uc704\uce58\uac00 \uc911\uc694\ud558\ub2e4\ub294 \uc810\uc744 \uc774\ud574\ud558\ub294 \ub370\ub9cc \uc0ac\uc6a9\ud558\uba74 \ub41c\ub2e4. \uc2e4\uc81c \uc810\uc790\uc758 \uaddc\uce59\uc740 \uc5b8\uc5b4\uc640 \uc6a9\ub3c4\uc5d0 \ub9de\ub294 \uc790\ub8cc\ub97c \ub530\ub77c \uc77d\uc5b4\uc57c \ud55c\ub2e4. \ube44\uc720\uac00 \ud559\uc2b5\ud45c\ub97c \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc790\ub9ac\uac00 \ud558\ub098\uc774\uace0 \uc810\uc774 \uc788\uac70\ub098 \uc5c6\uc744 \uc218 \uc788\ub2e4\uba74 \ub450 \uac00\uc9c0\ub2e4. \ub450 \uc790\ub9ac\uc5d0\uc11c\ub294 \uccab \uc790\ub9ac\uc5d0 \ub300\ud55c \ub450 \uc120\ud0dd\ub9c8\ub2e4 \ub458\uc9f8 \uc790\ub9ac\uc758 \ub450 \uc120\ud0dd\uc774 \uc774\uc5b4\uc838 \ub124 \uac00\uc9c0\uac00 \ub41c\ub2e4. \uc5ec\uc12f \uc790\ub9ac\uc5d0\uc11c\ub3c4 \uac19\uc740 \uc0dd\uac01\uc744 \ubc18\ubcf5\ud574 64\ub97c \uc5bb\ub294\ub2e4. \uc5b4\ub824\uc6b4 \uacf5\uc2dd\uc744 \uba3c\uc800 \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc120\ud0dd\uc774 \ud558\ub098\uc529 \ub354\ud574\uc9c8 \ub54c \uacbd\uc6b0\uc758 \uc218\uac00 \uc5b4\ub5bb\uac8c \ub298\uc5b4\ub098\ub294\uc9c0 \ubcf4\ub294 \uac83\uc774\ub2e4. \uc774 \uacc4\uc0b0\uc5d0\ub294 \uc544\ubb34 \uc810\ub3c4 \uc5c6\ub294 \uacbd\uc6b0\uac00 \ud3ec\ud568\ub41c\ub2e4. \uadf8\ub798\uc11c \uc810\uc774 \uc2e4\uc81c\ub85c \ud558\ub098 \uc774\uc0c1 \uc788\ub294 \ubaa8\uc591\ub9cc \uc138\uba74 63\uc774\ub77c\ub294 \ub2e4\ub978 \uc22b\uc790\uac00 \ub098\uc628\ub2e4. 64\uc640 63\uc774 \uc11c\ub85c \ub2e4\ub978 \uc8fc\uc7a5\uc744 \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc744 \uc138\uc5c8\ub294\uc9c0\uc758 \ubc94\uc704\uac00 \ub2e4\ub974\ub2e4. \uc218\ub97c \uc815\ud655\ud788 \uc77d\uc73c\ub824\uba74 \uacc4\uc0b0\ubfd0 \uc544\ub2c8\ub77c \ud3ec\ud568\ud558\uace0 \uc81c\uc678\ud55c \ub300\uc0c1\uc744 \uc54c\uc544\uc57c \ud55c\ub2e4\ub294 \uc88b\uc740 \uc608\ub2e4. \ud55c \uce78\uc758 \ud615\ud0dc\uac00 \uc815\ud574\uc9c4 \uc218\ub77c\uace0 \ud574\uc11c \uc810\uc790\ub85c \uc804\ud560 \uc218 \uc788\ub294 \ub0b4\uc6a9\ub3c4 \uadf8 \uc218\ub9cc\ud07c\uc774\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc5ec\ub7ec \uce78\uc744 \uc774\uc5b4 \ub193\uace0 \ubb38\ub9e5\uacfc \ud45c\uae30 \uaddc\uce59\uc744 \uc0ac\uc6a9\ud55c\ub2e4. \uac19\uc740 \ud615\ud0dc\ub3c4 \uc5b4\ub5a4 \uc5b8\uc5b4\uc640 \uc57d\uc18d \uc548\uc5d0\uc11c \uc77d\ub294\uc9c0 \uc911\uc694\ud558\ub2e4. \uc791\uc740 \uae30\ubcf8 \ub2e8\uc704\uc640 \uc804\uccb4 \ud45c\ud604 \uccb4\uacc4\ub294 \uac19\uc740 \ud06c\uae30\uc758 \ub300\uc0c1\uc774 \uc544\ub2c8\ub2e4. \uadf8\ub798\uc11c \ub77c\ud2f4 \ubb38\uc790 \uc608\uc2dc\ub97c \ud55c\uad6d\uc5b4\uc758 \ubaa8\ub4e0 \ud45c\uae30\uc5d0 \uadf8\ub300\ub85c \uc801\uc6a9\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uacf5\uc2dd \ubcc0\ud658 \ub3c4\uad6c\uac00 \uc5b8\uc5b4\ubcc4 \uaddc\uce59\uc744 \uad6c\ubd84\ud558\ub294 \uc774\uc720\ub3c4 \uc788\ub2e4. \uc774 \uae00\uc740 \uc5ec\uc12f \uc810\uc758 \uad6c\uc870\ub97c \uc774\ud574\ud558\ub294 \uc785\uad6c\uc774\uc9c0 \uc810\uc790\ub97c \uc644\uc804\ud788 \uc77d\uac8c \ud558\ub294 \uad50\uc7ac\ub294 \uc544\ub2c8\ub2e4. \ubb38\uc790\uc5d0 \uad00\uc2ec\uc744 \uac16\ub294 \uc77c\uacfc \uc2e4\uc81c \uc811\uadfc \uac00\ub2a5\ud55c \uc77d\uae30 \uc790\ub8cc\ub97c \ucda9\ubd84\ud788 \uc81c\uacf5\ud558\ub294 \uc77c\uc740 \uad6c\ubd84\ud560 \uc218 \uc788\ub2e4. \ubcf8\ubb38 \uc124\uba85\ub3c4\ub294 \uc810\uc758 \uc704\uce58\ub97c \uc2dc\uac01\uc801\uc73c\ub85c \ube44\uad50\ud558\ub3c4\ub85d \ub9cc\ub4e0 \uadf8\ub9bc\uc774\ub2e4. \uc2e4\uc81c\ub85c \ub3cc\ucd9c\ub41c \uc810\uc744 \uc190\uc73c\ub85c \uc77d\ub294 \uacbd\ud5d8\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud3c9\ud3c9\ud55c \ud654\uba74\uc5d0\uc11c \ubaa8\uc591\uc744 \uc54c\uc544\ubcf4\ub294 \uac83\uacfc \uc190\ub05d\uc73c\ub85c \ud45c\uae30\ub97c \ubc30\uc6b0\ub294 \uc77c\uc5d0\ub294 \ub2e4\ub978 \uc870\uac74\uc774 \uc788\ub2e4. \uc548\ub0b4 \uadf8\ub9bc\uc744 \ubcf4\uc558\ub2e4\uace0 \uc77d\ub294 \uc18d\ub3c4\uc640 \uc219\ub828\uae4c\uc9c0 \uc774\ud574\ud588\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8\ub7fc\uc5d0\ub3c4 \uad6c\uc870\ub97c \uc544\ub294 \uc77c\uc740 \uc77c\uc0c1\uc5d0\uc11c \uc810\uc790\ub97c \ubcfc \ub54c \ubb34\uc2ec\ud788 \uc9c0\ub098\uce58\uc9c0 \uc54a\uac8c \ud55c\ub2e4. \uba87 \uac1c\uc758 \uc7a5\uc2dd\uc801\uc778 \uc810\uc774 \uc544\ub2c8\ub77c \uc704\uce58\uc640 \uc21c\uc11c\ub97c \uac00\uc9c4 \ubb38\uc790\ub77c\ub294 \uc0ac\uc2e4\uc774 \ubcf4\uc778\ub2e4. \ud615\ud0dc\ub97c \uc138\ub294 \uacc4\uc0b0\uc5d0\uc11c \uc2dc\uc791\ud574 \ub2e4\uc591\ud55c \uc5b8\uc5b4\uc640 \uc77d\uae30\uc758 \ubc29\uc2dd\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc5ec\uc12f \uc790\ub9ac\uc758 \uc791\uc740 \uacf5\uac04\uc740 \uc815\ubcf4\uc758 \uac1c\uc218\uc640 \uc758\ubbf8\uc758 \ubc94\uc704\uac00 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0 \uc54c\ub824 \uc900\ub2e4. \uc5ec\uae30\uc11c\ub294 6\uc810 \uccb4\uacc4\uc758 \uc77c\ubd80 \uc608\ub97c \ubcf4\uace0 \uc788\ub2e4. \ubaa8\ub4e0 \uc5b8\uc5b4\uc640 \ubaa8\ub4e0 \uc810\uc790 \ubc29\uc2dd\uc774 \ud55c \uce78\uc744 \ub611\uac19\uc774 \ud574\uc11d\ud55c\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc791\uc740 \uc608\ub97c \uc804\uccb4 \uaddc\uce59\uc73c\ub85c \ub113\ud788\uc9c0 \uc54a\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \uadf8\ub798\ub3c4 \uc5ec\uc12f \uc790\ub9ac\ub97c \ub2e4\uc2dc \ubcf4\uba74 \ucc98\uc74c\uacfc\ub294 \uc870\uae08 \ub2e4\ub974\uac8c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ub2e8\uc21c\ud788 \uc810\uc744 \ub354\ud558\uac70\ub098 \ube7c\ub294 \uc77c\uc774 \uc544\ub2c8\ub77c, \uc815\ud574\uc9c4 \uc704\uce58\ub97c \uc870\ud569\ud574 \uc77d\uc744 \uc218 \uc788\ub294 \ucc28\uc774\ub97c \ub9cc\ub4dc\ub294 \uc77c\uc774\ub2e4. \uc791\uc740 \uce78 \uc548\uc5d0\ub3c4 \uaf64 \ub113\uc740 \uac00\ub2a5\uc131\uc774 \ub4e4\uc5b4 \uc788\ub2e4."}, {"id": "caroline-herschel-comet-notebook-and-salary", "title": "\uce90\ub864\ub77c\uc778 \ud5c8\uc15c \u2014 \ud61c\uc131\uc744 \ucc3e\uc740 \ubc24\uc5d0\ub3c4 \uc7a5\ubd80\ub294 \ub0a8\uc544 \uc788\uc5c8\ub2e4", "summary": "1786\ub144\uc758 \ud61c\uc131 \ubc1c\uacac\uacfc \uae30\ub85d \ub178\ub3d9, \uc790\uae30 \ub73b\ub300\ub85c \uc4f8 \uc218 \uc788\ub294 \uccab \uae09\uc5ec\ub97c \ud68c\uace0\ub85d\uc73c\ub85c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uacfc\ud559\uc790\uc758 \ubc1c\uacac", "categories": ["science"], "url": "stories/caroline-herschel-comet-notebook-and-salary/index.html", "image": "../media/caroline-herschel-comet-notebook-and-salary.jpg", "alt": "\ubcf4\ub2db\uc744 \uc4f4 92\uc138 \uce90\ub864\ub77c\uc778 \ud5c8\uc15c\uc744 \ubb18\uc0ac\ud55c \uc870\uc9c0\ud504 \ube0c\ub77c\uc6b4\uc758 \uc61b \ucd08\uc0c1 \ud310\ud654", "text": "\uce90\ub864\ub77c\uc778 \ud5c8\uc15c \u2014 \ud61c\uc131\uc744 \ucc3e\uc740 \ubc24\uc5d0\ub3c4 \uc7a5\ubd80\ub294 \ub0a8\uc544 \uc788\uc5c8\ub2e4 \uad00\uce21\uacfc \uacc4\uc0b0, \uc9d1\uc548\uc77c \uc0ac\uc774\uc5d0\uc11c \uc790\uae30 \uc774\ub984\uc758 \uc77c\uc744 \uc5bb\ub2e4 1786\ub144\uc758 \ud61c\uc131 \ubc1c\uacac\uacfc \uae30\ub85d \ub178\ub3d9, \uc790\uae30 \ub73b\ub300\ub85c \uc4f8 \uc218 \uc788\ub294 \uccab \uae09\uc5ec\ub97c \ud68c\uace0\ub85d\uc73c\ub85c \uc77d\uc2b5\ub2c8\ub2e4. \uacfc\ud559\uc790\uc758 \ubc1c\uacac \uacfc\ud559\uacfc \ubc1c\uacac \ub0ae\uc5d0\ub294 \uad00\uce21 \uae30\ub85d\uc744 \uacc4\uc0b0\ud558\uace0 \ubc24\uc5d0\ub294 \ud558\ub298\uc744 \uc0b4\ud540\ub2e4. \ud750\ub9b0 \ub0a0\uc774\uba74 \uae30\ub2e4\ub9ac\uace0, \ub9d1\uc544\uc9c0\uba74 \ub2e4\uc2dc \ud655\uc778\ud55c\ub2e4. \uce90\ub864\ub77c\uc778 \ud5c8\uc15c\uc758 \uc77c\uae30\uc5d0\ub294 \uc704\ub300\ud55c \ubc1c\uacac\uc744 \ud5a5\ud55c \uba4b\uc9c4 \ubb38\uc7a5\ub9cc \uc788\uc9c0 \uc54a\ub2e4. \ub300\uc7a5\uc7a5\uc774\uc5d0\uac8c \uc900 \ub3c8\uacfc \uc2dc\uacc4\ub97c \ub9de\ucd98 \uc77c, \uc7a5\ubd80\ub97c \uc815\ub9ac\ud55c \uc77c\ub3c4 \uac19\uc740 \uc0dd\ud65c \uc548\uc5d0 \uc801\ud600 \uc788\ub2e4. \uadf8 \uae30\ub85d\uc744 \ub530\ub77c\uac00\uba74 \ud61c\uc131\uc744 \ucc3e\uc740 \uc5ec\uc131 \ucc9c\ubb38\ud559\uc790\uac00 \uba3c \uc704\uc778\uc758 \ucd08\uc0c1\uc5d0\uc11c \ub0b4\ub824\uc628\ub2e4. \uc5ec\uae30\uc11c\ub294 \uac00\uc871\uc774 \uc5ee\uc740 \u300e\uce90\ub864\ub77c\uc778 \ud5c8\uc15c\uc758 \ud68c\uace0\ub85d\uacfc \uc11c\uc2e0\u300f\uc758 1879\ub144 \ud310\ubcf8\uc744 \ubc14\ud0d5\uc73c\ub85c, 1786\ub144\uc758 \ubc1c\uacac\uacfc \uadf8 \ub4a4\uc758 \uc77c\uc744 \uc77d\uc5b4 \ubcf8\ub2e4. \ub3c5\uc77c \ud558\ub178\ubc84\uc5d0\uc11c \ud0dc\uc5b4\ub09c \uce90\ub864\ub77c\uc778\uc740 \uc624\ube60 \uc70c\ub9ac\uc5c4\uc774 \uc788\ub294 \uc601\uad6d\uc73c\ub85c \uac04\ub2e4. \ucc98\uc74c \ub450 \uc0ac\ub78c\uc758 \uc0dd\ud65c\uc5d0\ub294 \uc74c\uc545\uc774 \ud070 \uc790\ub9ac\ub97c \ucc28\uc9c0\ud588\ub2e4. \uc70c\ub9ac\uc5c4\uc740 \uc74c\uc545\uac00\ub85c \uc77c\ud588\uace0 \uce90\ub864\ub77c\uc778\ub3c4 \ub178\ub798\ub97c \ud588\ub2e4. \ucc98\uc74c\ubd80\ud130 \ucc9c\ubb38\ud559\uc744 \uc9c1\uc5c5\uc73c\ub85c \uc815\ud574 \ub193\uace0 \ucd9c\ubc1c\ud55c \uc5ec\uc815\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc70c\ub9ac\uc5c4\uc758 \uad00\uce21\uacfc \ub9dd\uc6d0\uacbd \uc81c\uc791\uc774 \ucee4\uc9c0\uba74\uc11c \uce90\ub864\ub77c\uc778\uc758 \uc77c\ub3c4 \ubc14\ub010\ub2e4. \uc9d1\uc548\uc758 \uc0dd\ud65c\uc744 \ub3cc\ubcf4\ub294 \uc77c\uacfc \uc5f0\uad6c\ub97c \ub3d5\ub294 \uc77c\uc774 \ud568\uaed8 \ub298\uc5b4\ub09c\ub2e4. \uc5ec\uae30\uc11c \ub3d5\ub294\ub2e4\ub294 \ub9d0\uc744 \ub2e8\uc21c\ud55c \uc7a1\uc77c\ub85c \uc0dd\uac01\ud558\uba74 \uc2e4\uc81c \ub2a5\ub825\uc774 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc22b\uc790\ub97c \uae30\ub85d\ud558\uace0 \uacc4\uc0b0\ud558\uace0 \uc790\ub8cc\ub97c \ub2e4\uc2dc \ucc3e\uc744 \uc218 \uc788\uac8c \ub9cc\ub4dc\ub294 \uc77c\uc740 \uad00\uce21\uc758 \uacb0\uacfc\ub97c \uc9c0\uc2dd\uc73c\ub85c \ub0a8\uae30\ub294 \uacfc\uc815\uc774\uc5c8\ub2e4. \ub9dd\uc6d0\uacbd\uc73c\ub85c \ubcf4\uc558\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ub2e4\ub978 \uc0ac\ub78c\uc774 \uac19\uc740 \ub300\uc0c1\uc744 \ucc3e\uc744 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b8\uc81c \uc5b4\ub290 \ubc29\ud5a5\uc5d0\uc11c \ubb34\uc5c7\uc774 \ubcf4\uc600\ub294\uc9c0 \uae30\ub85d\uc774 \ud544\uc694\ud558\ub2e4. \uce90\ub864\ub77c\uc778\uc740 \uad00\uce21\uc744 \uc815\ub9ac\ud558\uace0 \ubcc4 \ubaa9\ub85d\uacfc \ub9de\ucd94\uba70 \ubc18\ubcf5\ud574\uc11c \uacc4\uc0b0\ud55c\ub2e4. \ud558\ub298\uc744 \ubc14\ub77c\ubcf4\ub294 \ub208\uacfc \uacf5\ucc45 \uc704\uc758 \uc190\uc774 \ud568\uaed8 \uc6c0\uc9c1\uc778\ub2e4. 1786\ub144\uc758 \uae30\ub85d\uc5d0\ub294 \uacfc\uac70 \uad00\uce21\uc744 \uc5b4\ub5a4 \uc21c\uc11c\ub85c \uc62e\uaca8 \uc801\uc744\uc9c0 \uace0\ubbfc\ud558\ub294 \ub300\ubaa9\ub3c4 \uc788\ub2e4. \ub4a4\uc5d0\uc11c\ubd80\ud130 \uc815\ub9ac\ud558\ub294 \ubc29\uc2dd\uc774 \uc88b\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4\uace0 \uc0dd\uac01\ud558\uace0 \ub2e4\uc2dc \uacc4\uc0b0\ud558\ub824 \ud55c\ub2e4. \ud070 \ubc1c\uacac\uacfc\ub294 \uac70\ub9ac\uac00 \uc788\uc5b4 \ubcf4\uc774\ub294 \uc774\ub7f0 \ud310\ub2e8\uc774 \uc790\ub8cc\uc758 \uc2e0\ub8b0\uc131\uc744 \ub9cc\ub4e0\ub2e4. \uae30\ub85d\uc740 \ub2e8\uc21c\ud788 \ub9ce\uc774 \uc4f4\ub2e4\uace0 \uc800\uc808\ub85c \uc4f0\uae30 \uc26c\uc6cc\uc9c0\uc9c0 \uc54a\ub294\ub2e4. 1786\ub144 8\uc6d4 1\uc77c, \uadf8\ub140\ub294 \ud61c\uc131\uc77c \uac83 \uac19\uc740 \ub300\uc0c1\uc744 \ubcf4\uc558\ub2e4\uace0 \uc801\ub294\ub2e4. \uadf8 \ubb38\uc7a5\uc5d0\ub294 \ud655\uc2e0 \uc774\uc804\uc758 \uc5ec\uc9c0\uac00 \ub0a8\uc544 \uc788\ub2e4. \ub2e4\uc74c \uad00\uce21\uc5d0\uc11c \ub300\uc0c1\uc774 \ud61c\uc131\uc784\uc744 \ud655\uc778\ud55c\ub2e4. \ud55c \ubc88 \ubcf8 \uc778\uc0c1\uc774 \ubc14\ub85c \ubc1c\uacac\uc758 \uc774\ub984\uc73c\ub85c \uad73\uc5b4\uc9c0\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ub2e4\uc2dc \uc0b4\ud53c\ub294 \uc2dc\uac04\uc774 \uc788\ub2e4. \ub0a0\uc528\ub294 \uc5f0\uad6c\uc790\uc758 \uc18c\ub9dd\ub300\ub85c \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294\ub2e4. \ube44\uac00 \uc624\uace0 \uad6c\ub984\uc774 \ub07c\uba74 \ud655\uc778\ud560 \uae30\ud68c\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uadf8\ub798\uc11c \uc77c\uae30\uc758 \ub0a0\uc528 \uc774\uc57c\uae30\ub294 \ubc30\uacbd \uc7a5\uc2dd\uc774 \uc544\ub2c8\ub2e4. \uc624\ub298 \ubb34\uc5c7\uc744 \uc54c \uc218 \uc788\uace0 \ubb34\uc5c7\uc744 \uae30\ub2e4\ub824\uc57c \ud558\ub294\uc9c0 \uc815\ud558\ub294 \uc870\uac74\uc774\ub2e4. \ubc1c\uacac\uc758 \uc5ed\uc0ac\ub294 \uc0ac\ub78c\uc758 \uc758\uc9c0\ubfd0 \uc544\ub2c8\ub77c \uadf8\ub7f0 \uae30\ub2e4\ub9bc\uc73c\ub85c\ub3c4 \uc774\ub8e8\uc5b4\uc9c4\ub2e4. \uce90\ub864\ub77c\uc778\uc740 \uad00\uce21 \ub4a4 \uace7 \ud3b8\uc9c0\ub97c \uc368 \uc18c\uc2dd\uc744 \uc54c\ub9b0\ub2e4. \uc0c8\ub85c\uc6b4 \uac83\uc744 \ubcf4\uc558\ub2e4\ub294 \uc8fc\uc7a5\uc5d0\ub294 \ub2e4\ub978 \uc774\ub4e4\uc774 \ud655\uc778\ud560 \uc218 \uc788\ub294 \uc815\ubcf4\uac00 \ud544\uc694\ud558\ub2e4. \uc790\uc2e0\uc5d0\uac8c \ud2b9\ubcc4\ud588\ub358 \ubc24\uc744 \ud63c\uc790 \uac04\uc9c1\ud558\ub294 \uac83\uacfc \ud559\ubb38\uc758 \uae30\ub85d\uc73c\ub85c \uc804\ub2ec\ud558\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \ud3b8\uc9c0\uc640 \uc88c\ud45c, \uad00\uce21\uc758 \uc124\uba85\uc774 \uadf8 \uc0ac\uc774\ub97c \uc787\ub294\ub2e4. \uc70c\ub9ac\uc5c4\uc740 \uadf8 \ubb34\ub835 \ub3c5\uc77c\uc5d0 \uc788\uc5c8\ub2e4. \uce90\ub864\ub77c\uc778\uc774 \uc5b8\uc81c\ub098 \uc624\ube60\uc758 \uc606\uc5d0\uc11c \ubc1b\uc544\uc4f0\uae30\ub9cc \ud558\ub358 \uc874\uc7ac\ub294 \uc544\ub2c8\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc774 \uc7a5\uba74\uc5d0\uc11c\ub3c4 \ubcf4\uc778\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub450 \uc0ac\ub78c\uc758 \uc5f0\uad6c\ub97c \uacbd\uc7c1 \uc774\uc57c\uae30 \ud558\ub098\ub85c \ub9cc\ub4e4 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud611\ub825 \uc18d\uc5d0\uc11c \uc218\ud589\ud55c \uc77c\uacfc \ub3c5\ub9bd\uc801\uc73c\ub85c \uad00\uce21\ud55c \uc77c\uc744 \uac01\uac01 \uc54c\uc544\ubcf4\ub294 \uac83\uc774 \ub354 \uc815\ud655\ud558\ub2e4. \ubc1c\uacac\uc774 \uc788\uc5c8\uc5b4\ub3c4 \uc77c\uc0c1\uc740 \uacc4\uc18d\ub41c\ub2e4. \ubcc4 \ubaa9\ub85d\uacfc \uc131\uc6b4 \uad00\uce21\uc744 \uc815\ub9ac\ud558\uace0, \uc7a5\ube44\uc640 \ubc29\ubb38\uac1d, \uc0dd\ud65c\uc758 \ud544\uc694\ub97c \ub2e4\ub8ec\ub2e4. \uba4b\uc9c4 \ubc24 \ud558\ub098\ub85c \uc774\ud6c4\uc758 \ubaa8\ub4e0 \uc77c\uc774 \uc0ac\ub77c\uc9c0\ub294 \uc131\uacf5\ub2f4\uacfc\ub294 \ub2e4\ub974\ub2e4. \uae30\ub85d\uc774 \uc313\uc774\uba74 \uadf8 \uae30\ub85d\uc744 \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc0ac\uc6a9\ud560 \uc218 \uc788\uac8c \ub9cc\ub4dc\ub294 \uc0c8\ub85c\uc6b4 \ub178\ub3d9\uc774 \uc0dd\uae34\ub2e4. \uc774\ub7f0 \uc77c\uc740 \ub208\uc5d0 \ub744\ub294 \uc774\ub984\uc744 \ubd99\uc774\uae30 \uc5b4\ub824\uc6cc\ub3c4 \uc911\uc694\ud558\ub2e4. \uc815\ub9ac\uac00 \uc798\ubabb\ub418\uba74 \uc774\ubbf8 \uc5bb\uc740 \uad00\uce21\ub3c4 \ucc3e\uae30 \uc5b4\ub835\uace0 \ube44\uad50\ud558\uae30 \ud798\ub4e4\uc5b4\uc9c4\ub2e4. \uacfc\ud559\uc758 \ubc1c\uc804\uc744 \uc0c8 \ucc9c\uccb4\uc758 \uc218\ub85c\ub9cc \uc138\uba74 \uc774 \uacfc\uc815\uc740 \ub298 \ub4a4\ub85c \ubc00\ub9b0\ub2e4. \uce90\ub864\ub77c\uc778\uc758 \uacf5\ucc45\uc740 \ubc1c\uacac\uacfc \uc815\ub9ac \uc0ac\uc774\uc5d0 \uba85\ud655\ud55c \uc6b0\uc5f4\uc744 \ub450\uae30 \uc5b4\ub835\uac8c \ub9cc\ub4e0\ub2e4. \ub4a4\uc5d0 \uce90\ub864\ub77c\uc778\uc5d0\uac8c\ub294 \uc624\ube60\ub97c \ub3d5\ub294 \uc5f0\uad6c \uc870\uc218\uc758 \uc5f0\uac04 \uae09\uc5ec 50\ud30c\uc6b4\ub4dc\uac00 \uc815\ud574\uc9c4\ub2e4. \ud68c\uace0\ub85d\uc5d0\uc11c \uc778\uc0c1\uc801\uc778 \ubd80\ubd84\uc740 \uc561\uc218\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uadf8\ub140\ub294 \uccab \ubd84\uae30 \uae09\uc5ec\ub97c \uc790\uae30 \ub73b\ub300\ub85c \uc4f8 \uc218 \uc788\ub294 \uccab \ub3c8\uc73c\ub85c \ub290\uaf08\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uac00\uc871\uc758 \uc9c0\ucd9c\uc744 \uad00\ub9ac\ud558\ub294 \uc77c\uacfc \uc790\uc2e0\uc758 \uc218\uc785\uc744 \uac16\ub294 \uc77c\uc740 \ub2ec\ub790\ub2e4. \uc774\ubbf8 \ub9ce\uc740 \ucc45\uc784\uc744 \ub9e1\uace0 \uc788\ub358 \uc0ac\ub78c\uc774 \uc790\uae30 \uc77c\uc758 \ub300\uac00\ub97c \ubc1b\ub294 \uacbd\ud5d8\uc774\ub2e4. \uc774\uac83\uc744 \uc5b4\ub290 \ub098\ub77c \uc5b4\ub290 \uc9c1\uc885\uc758 \ucd5c\ucd08\uc600\ub2e4\ub294 \uc21c\uc704\ub85c \ud06c\uac8c \uafb8\ubc00 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8 \ud55c \uc0ac\ub78c\uc758 \uae30\ub85d\ub9cc\uc73c\ub85c\ub3c4 \uc758\ubbf8\uac00 \uc120\uba85\ud558\ub2e4. \ub2a5\ub825\uacfc \uae30\uc5ec\uac00 \uc874\uc7ac\ud558\ub294 \uac83, \uadf8\uac83\uc774 \uc774\ub984\uacfc \uae09\uc5ec\ub85c \uc778\uc815\ub418\ub294 \uac83\uc740 \uc11c\ub85c \ub2e4\ub978 \ub2e8\uacc4\uc600\ub2e4. \uc774 \ucc45\uc740 \uce90\ub864\ub77c\uc778\uc758 \uc77c\uae30\uc640 \ud68c\uc0c1, \ud3b8\uc9c0\uc5d0 \uac00\uc871 \ud3b8\uc9d1\uc790\uc758 \uc124\uba85\uc774 \ub354\ud574\uc9c4 \uc790\ub8cc\ub2e4. \ubaa8\ub4e0 \ubb38\uc7a5\uc774 \ubc1c\uacac \ub2f9\uc77c \ud604\uc7a5\uc5d0\uc11c \uadf8\ub300\ub85c \uc801\ud78c \uac83\uc740 \uc544\ub2c8\ub2e4. \ub2f9\uc0ac\uc790\uc758 \ub9d0\uacfc \ub4a4\uc5d0 \uc0b6\uc744 \uc815\ub9ac\ud55c \uc0ac\ub78c\uc758 \uc2dc\uc120\uc744 \uad6c\ubd84\ud558\uba74 \ud55c \uac00\uc871\uc758 \uae30\ub150\uacfc \uc2e4\uc81c \uc791\uc5c5\uc758 \ubaa8\uc2b5\uc774 \ud568\uaed8 \ubcf4\uc778\ub2e4. \uae00\uc5d0 \ubd99\uc778 \ucd08\uc0c1 \uc5ed\uc2dc \uc80a\uc740 \uc2dc\uc808 \ud61c\uc131\uc744 \ucc3e\ub358 \ubc24\uc758 \uc0ac\uc9c4\uc774 \uc544\ub2c8\ub2e4. 92\uc138\uc758 \ubaa8\uc2b5\uc744 \ub2f4\uc558\ub2e4\uace0 \ud45c\uae30\ub41c \uc61b \ud310\ud654\ub2e4. \uae34 \uc0dd\uc560 \ub4a4\uc758 \uc5bc\uad74\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc790\ub8cc\ub77c\ub294 \uc0ac\uc2e4\uc744 \uc54c\uba74 \uc791\uc740 \uc774\ubbf8\uc9c0\ub3c4 \ub2e4\ub978 \uc2dc\uac04\uc758 \uc99d\uc5b8\uc774 \ub41c\ub2e4. \uacfc\ud559\uc790\uc758 \uae30\uc5b5\uc740 \ub9dd\uc6d0\uacbd \ud55c \uc7a5\uba74\uc5d0\ub9cc \uba48\ucdb0 \uc788\uc9c0 \uc54a\ub2e4. \uce90\ub864\ub77c\uc778 \ud5c8\uc15c\uc758 \uc774\uc57c\uae30\ub97c \ub2e4\uc2dc \uc77d\uc73c\uba74 \ubc1c\uacac\uc758 \ub0ad\ub9cc\uacfc \uae30\ub85d\uc758 \uc218\uace0\uac00 \ud568\uaed8 \ub0a8\ub294\ub2e4. \ubc24\uc5d0 \ubb34\uc5c7\uc778\uac00\ub97c \ucc3e\uc544\ub0c8\uace0 \ub0ae\uc5d0\ub294 \uadf8\uac83\uc744 \ub2e4\uc2dc \uacc4\uc0b0\ud588\uc73c\uba70, \uadf8 \uc0ac\uc774\uc5d0 \uc9d1\uacfc \uc7a5\ube44\uc640 \ub3c8\uc744 \uad00\ub9ac\ud588\ub2e4. \uc0dd\ud65c\uc758 \uc791\uc740 \uc77c\ub4e4\uc744 \ub2e4 \uc5c6\uc560\uc57c\ub9cc \uc704\ub300\ud55c \uacfc\ud559\uc774 \uc2dc\uc791\ub418\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ubcc4\uacfc \ud61c\uc131\uc758 \uc774\uc57c\uae30\ub97c \ub4e4\uc744 \ub54c \uc55e\uc73c\ub85c\ub294 \uacf5\ucc45\ub3c4 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ub0af\uc120 \ube5b\uc744 \ucc98\uc74c \ubcf4\ub294 \ub208 \uacc1\uc5d0 \uadf8 \ube5b\uc744 \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc774\ud574\ud560 \uc218 \uc788\uac8c \ub0a8\uae30\ub294 \uc190\uc774 \uc788\ub2e4. \uce90\ub864\ub77c\uc778\uc758 \uae30\ub85d\uc740 \uadf8 \uc190\uc744 \uc790\uae30 \uc774\ub984\uc758 \uc77c\ub85c \ubcfc \uc218 \uc788\uac8c \ud55c\ub2e4. \uadf8\ub9ac\uace0 \uc5b4\ub5a4 \uc778\uc815\uc740 \ud558\ub298\uc758 \ubc1c\uacac\ub9cc\ud07c\uc774\ub098 \uc9c0\uc0c1\uc758 \uc0dd\ud65c\uc744 \ubc14\uafb8\uc5c8\ub2e4."}, {"id": "darwin-life-of-observation", "title": "\ub2e4\uc708\uc758 \uc0dd\uc560 \u2014 \ud55c \ubc88\uc758 \uc5ec\ud589\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\uc740 \ubc1c\uacac", "summary": "\ub2e4\uc708\uc758 \uc790\uc11c\uc804\uc744 \ubc14\ud0d5\uc73c\ub85c \ubc30\uc6c0\uc758 \uc6b0\ud68c\uc640 \ube44\uae00\ud638 \ud56d\ud574, \uae34 \uc5f0\uad6c\uc640 \uc6d4\ub9ac\uc2a4\uc758 \uc5ed\ud560\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uacfc\ud559\uc790\uc758 \ubc1c\uacac", "categories": ["science"], "url": "stories/darwin-life-of-observation/index.html", "image": "../media/darwin-life-of-observation.png", "alt": "\uc870\uac1c\uc640 \uc2dd\ubb3c \ud45c\ubcf8, \uc218\ucca9\uc774 \ub193\uc778 \ucc45\uc0c1\uc5d0\uc11c \ub3cb\ubcf4\uae30\ub85c \ud45c\ubcf8\uc744 \uc0b4\ud53c\ub294 19\uc138\uae30 \uc5f0\uad6c\uc790\uc758 \ub4b7\ubaa8\uc2b5.", "text": "\ub2e4\uc708\uc758 \uc0dd\uc560 \u2014 \ud55c \ubc88\uc758 \uc5ec\ud589\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\uc740 \ubc1c\uacac \uc218\uc9d1\uacfc \uc9c8\ubb38, \uc624\ub798\ub41c \uae30\ub85d\uc774 \ucc45\uc774 \ub418\uae30\uae4c\uc9c0 \ub2e4\uc708\uc758 \uc790\uc11c\uc804\uc744 \ubc14\ud0d5\uc73c\ub85c \ubc30\uc6c0\uc758 \uc6b0\ud68c\uc640 \ube44\uae00\ud638 \ud56d\ud574, \uae34 \uc5f0\uad6c\uc640 \uc6d4\ub9ac\uc2a4\uc758 \uc5ed\ud560\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uacfc\ud559\uc790\uc758 \ubc1c\uacac \uacfc\ud559\uacfc \ubc1c\uacac \ub2e4\uc708\uc740 \uac08\ub77c\ud30c\uace0\uc2a4\uc5d0\uc11c \uc0c8\ub97c \ud55c \ubc88 \ubcf4\uace0 \uc9c4\ud654\ub97c \ub2e8\ubc88\uc5d0 \uc54c\uc544\ub0b8 \uc0ac\ub78c\uc77c\uae4c. \uadf8\uc758 \uc790\uc11c\uc804\uc744 \uc77d\uc73c\uba74 \ud6e8\uc52c \ub290\ub9ac\uace0 \ubcf5\uc7a1\ud55c \uc2dc\uac04\uc774 \ub098\uc628\ub2e4. \uc5b4\ub9b0 \uc2dc\uc808\uc758 \uc218\uc9d1, \uc9c4\ub85c\uc758 \uc6b0\ud68c, \uae34 \ud56d\ud574\uc640 \ub3cc\uc544\uc628 \ub4a4\uc758 \uc791\uc5c5\uc774 \uc774\uc5b4\uc9c4\ub2e4. \uc5ec\ud589\uc5d0\uc11c \ub9cc\ub09c \uac83\uc740 \uc644\uc131\ub41c \uc815\ub2f5\ubcf4\ub2e4 \uc624\ub798 \ub2e4\ub8f0 \uc9c8\ubb38\ub4e4\uc774\uc5c8\ub2e4. \uc5ec\uae30\uc11c \uc77d\uc740 \ud310\ubcf8\uc740 \ub2e4\uc708\uc758 \ud68c\uace0\uc5d0 \uc544\ub4e4 \ud504\ub79c\uc2dc\uc2a4\uc758 \ud3b8\uc9d1 \uc124\uba85\uc774 \ubd99\uc740 \uc790\ub8cc\ub2e4. \ud3b8\uc9d1\uc790\ub294 \uc77c\ubd80 \uc0dd\ub7b5\uc774 \uc788\uc74c\uc744 \ubc1d\ud78c\ub2e4. \uc0dd\uc560\uc758 \ubaa8\ub4e0 \uc7a5\uba74\uc744 \ube60\uc9d0\uc5c6\uc774 \uae30\ub85d\ud55c \uac1d\uad00\uc801 \uc5f0\ub300\uae30\ub77c\uae30\ubcf4\ub2e4, \ud6d7\ub0a0\uc758 \ub2e4\uc708\uc774 \uc790\uae30 \uc0dd\uac01\uc758 \ubc1c\ub2ec\uc744 \uc5b4\ub5bb\uac8c \ub3cc\uc544\ubcf4\uc558\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \uc6d0\uc804\uc73c\ub85c \uc77d\uc790. \ucc30\uc2a4 \ub2e4\uc708\uc740 1809\ub144 \uc601\uad6d \uc288\ub8e8\uc988\ubc84\ub9ac\uc5d0\uc11c \ud0dc\uc5b4\ub0ac\ub2e4. \uc790\uc11c\uc804\uc5d0\uc11c\ub294 \uc5b4\ub9b0 \uc2dc\uc808\ubd80\ud130 \uc790\uc5f0\ubb3c\uc744 \ubaa8\uc73c\uace0 \uc774\ub984\uc744 \uc54c\uc544\ubcf4\ub824 \ud588\ub2e4\uace0 \ub3cc\uc544\ubcf8\ub2e4. \ub098\uc911\uc758 \ud070 \uc774\ub860\uc744 \uc774\ubbf8 \ud488\uc740 \ucc9c\uc7ac\uc758 \ubaa8\uc2b5\ub9cc \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc774\ub4e0 \uc218\uc9d1\ud558\uace0 \uad6c\ubd84\ud558\ub294 \ud765\ubbf8\uac00 \uba3c\uc800 \ubcf4\uc778\ub2e4. \uc218\uc9d1\uc740 \ube44\uc2b7\ud55c \uac83 \uc0ac\uc774\uc758 \ucc28\uc774\ub97c \ubcf4\uac8c \ub9cc\ub4e0\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ud558\ub098\ub97c \ub354 \uc5bb\ub294 \uc990\uac70\uc6c0\uc774\uc5c8\uc5b4\ub3c4 \uc65c \ub2e4\ub978\uc9c0, \ubb34\uc5c7\uacfc \uac00\uae4c\uc6b4\uc9c0 \ubb3b\uac8c \ub420 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \ucde8\ubbf8\uac00 \ubc18\ub4dc\uc2dc \uc704\ub300\ud55c \ubc1c\uacac\uc73c\ub85c \uc774\uc5b4\uc9c4\ub2e4\ub294 \uc131\uacf5 \uacf5\uc2dd\uc73c\ub85c \ubc14\uafb8\uc5b4 \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774 \uc0dd\uc560\uc5d0\uc11c \uc5b4\ub5a4 \uad00\uc2ec\uc774 \uacc4\uc18d\ub418\uc5c8\ub294\uc9c0 \uc0b4\ud53c\uba74 \ub41c\ub2e4. \ub2e4\uc708\uc740 \uc5d0\ub4e0\ubc84\ub7ec\uc5d0\uc11c \uc758\ud559\uc744 \uacf5\ubd80\ud588\uc9c0\ub9cc \uadf8 \uae38\uc744 \uacc4\uc18d \uac00\uc9c0 \uc54a\uc558\ub2e4. \uc790\uc11c\uc804\uc5d0\ub294 \uac15\uc758\uc5d0 \ub300\ud55c \uc778\uc0c1\uacfc \uc218\uc220 \uc7a5\uba74\uc744 \uacac\ub514\uae30 \uc5b4\ub824\uc6cc\ud588\ub358 \uae30\uc5b5\uc774 \ub098\uc628\ub2e4. \uc774\ud6c4 \ucf00\uc784\ube0c\ub9ac\uc9c0\uc5d0\uc11c\ub294 \uc131\uc9c1\uc790\uac00 \ub418\ub294 \uae38\uc744 \uc5fc\ub450\uc5d0 \ub450\uace0 \uacf5\ubd80\ud588\ub2e4. \ud6d7\ub0a0\uc758 \uba85\uc131\ub9cc \ubcf4\uba74 \ucc98\uc74c\ubd80\ud130 \uc0dd\ubb3c\ud559\uc790\uac00 \ub420 \uacc4\ud68d\uc774 \ubd84\uba85\ud588\uc744 \uac83 \uac19\uc9c0\ub9cc \uadf8\ub807\uc9c0 \uc54a\uc558\ub2e4. \uc9c4\ub85c\uac00 \ud754\ub4e4\ub9ac\ub294 \ub3d9\uc548\uc5d0\ub3c4 \uc790\uc5f0\uc5d0 \ub300\ud55c \uad00\uc2ec\uacfc \uc8fc\ubcc0 \uc0ac\ub78c\uc5d0\uac8c\uc11c \ubc30\uc6b0\ub294 \uacbd\ud5d8\uc740 \ub0a8\uc558\ub2e4. \uc5b4\ub5a4 \uad50\uc721\uc744 \uc2dc\uc791\ud588\ub2e4\uac00 \ub2e4\ub978 \ubc29\ud5a5\uc73c\ub85c \uac04 \uc77c\uc774 \uadf8 \uc774\uc804 \uc2dc\uac04\uc744 \uc804\ubd80 \ubb34\uc758\ubbf8\ud558\uac8c \ub9cc\ub4dc\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ucf00\uc784\ube0c\ub9ac\uc9c0\uc5d0\uc11c \uc2dd\ubb3c\ud559\uc790 \ud5e8\uc2ac\ub85c\uc640\uc758 \uad00\uacc4\ub294 \uc911\uc694\ud55c \uc5f0\uacb0\uc774 \ub418\uc5c8\ub2e4. \ub2e4\uc708\uc740 \uadf8\uc640 \uac77\uace0 \ub300\ud654\ud558\uba70 \ubc30\uc6e0\uace0, \uc9c0\uc9c8\ud559\uc744 \uc811\ud558\ub294 \uae30\ud68c\ub3c4 \uc5bb\uc5c8\ub2e4. \uc9c0\uc2dd\uc740 \ud63c\uc790 \ucc45\uc0c1\uc5d0\uc11c \uc313\ub294 \uac83\ub9cc\uc774 \uc544\ub2c8\ub77c \ub204\uac00 \ubb34\uc5c7\uc744 \ubcf4\ub77c\uace0 \uc54c\ub824 \uc8fc\ub294\uc9c0\uc640\ub3c4 \uad00\ub828\ub418\uc5b4 \uc788\uc5c8\ub2e4. \ube44\uae00\ud638 \ud56d\ud574\ub85c \uc774\uc5b4\uc9c0\ub294 \uae30\ud68c\ub3c4 \uc774\ub7f0 \uad00\uacc4 \uc18d\uc5d0\uc11c \uc5f4\ub838\ub2e4. \ud55c \uc0ac\ub78c\uc758 \uc6a9\uae30\ub9cc\uc73c\ub85c \uc138\uacc4\uc758 \ubb38\uc774 \uc800\uc808\ub85c \uc5f4\ub838\ub2e4\uace0 \uc124\uba85\ud558\uba74 \ubc30\uacbd\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \uad00\uc2ec\uc744 \uc54c\uc544\ubcf8 \uc0ac\ub78c\uacfc \uc18c\uac1c, \ubc30\uc6b8 \uc218 \uc788\uc5c8\ub358 \uc870\uac74\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \uc0dd\uc560\ub97c \uc77d\uc744 \ub54c \uc8fc\ubcc0 \uc774\ub984\uc744 \uc9c0\ub098\uce58\uc9c0 \uc54a\uc744 \uc774\uc720\ub2e4. \ub2e4\uc708\uc758 \ud56d\ud574\ub294 1831\ub144\uc5d0 \uc2dc\uc791\ud574 1836\ub144\uc5d0 \ub05d\ub0ac\ub2e4. \uc5ec\ub7ec \uc9c0\uc5ed\uc5d0\uc11c \ub3d9\uc2dd\ubb3c\uacfc \uc9c0\ud615, \ud654\uc11d\uc744 \ubcf4\uace0 \uc790\ub8cc\ub97c \ubaa8\uc558\ub2e4. \uc790\uc5f0\uc740 \ud55c \uac00\uc9c0 \ubaa8\uc2b5\uc73c\ub85c \uc815\uc9c0\ud574 \uc788\uc9c0 \uc54a\uc558\uace0, \uc11c\ub85c \ub2e4\ub978 \uc9c0\uc5ed\uc758 \uc0dd\ubb3c\uc740 \ub2ee\uc73c\uba74\uc11c\ub3c4 \ub2ec\ub790\ub2e4. \ub3cc\uc544\uc640 \ube44\uad50\ud560 \ub300\uc0c1\uc774 \uacc4\uc18d \ub298\uc5b4\ub0ac\ub2e4. \ud56d\ud574 \uc911\uc758 \uc21c\uac04 \ud558\ub098\uc5d0 \ubaa8\ub4e0 \uc124\uba85\uc774 \uc644\uc131\ub418\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \ub9d0\uc790. \ucc44\uc9d1\ud55c \uc790\ub8cc\ub97c \ubd84\ub958\ud558\uace0 \ub2e4\ub978 \uc5f0\uad6c\uc790\uc640 \ud655\uc778\ud558\uba70 \ud574\uc11d\ud558\ub294 \uacfc\uc815\uc774 \ud544\uc694\ud588\ub2e4. \uae38 \uc704\uc5d0\uc11c\uc758 \uacbd\ud5d8\uacfc \ub098\uc911\uc758 \uc815\ub9ac\ub294 \ud55c \uc791\uc5c5\uc758 \uc11c\ub85c \ub2e4\ub978 \ubd80\ubd84\uc774\ub2e4. \ubc1c\uacac\uc758 \uc0ac\uc9c4 \ud55c \uc7a5\uc73c\ub85c \uae34 \uc5f0\uad6c\uc758 \uc2dc\uac04\uc744 \ub300\uc2e0\ud558\uae30 \uc5b4\ub835\ub2e4. \uc601\uad6d\uc73c\ub85c \ub3cc\uc544\uc628 \ub2e4\uc708\uc740 \uad00\ucc30\uacfc \ub3c5\uc11c, \uc9d1\ud544\uc744 \uc774\uc5b4 \uac14\ub2e4. \uac00\ucd95\uacfc \uc7ac\ubc30 \uc2dd\ubb3c\uc758 \ucc28\uc774, \uc0ac\ub78c\ub4e4\uc774 \uc6d0\ud558\ub294 \ud2b9\uc131\uc744 \ub0a8\uae30\ub294 \ubc29\uc2dd\ub3c4 \uc0dd\uac01\uc758 \uc7ac\ub8cc\uac00 \ub418\uc5c8\ub2e4. \uc790\uc11c\uc804\uc5d0\uc11c\ub294 1838\ub144 \ub9ec\uc11c\uc2a4\uc758 \uc778\uad6c\ub860\uc744 \uc77d\uc740 \uacbd\ud5d8\uc744 \uc790\uc2e0\uc758 \uad6c\uc0c1\uacfc \uc5f0\uacb0\ud574 \uc124\uba85\ud55c\ub2e4. \uac1c\uccb4 \uc0ac\uc774\uc758 \ucc28\uc774\uc640 \uc0dd\uc874\u00b7\ubc88\uc2dd\uc758 \uc870\uac74\uc744 \uc5b4\ub5bb\uac8c \ud568\uaed8 \uc0dd\uac01\ud560 \uac83\uc778\uac00\uac00 \uc911\uc694\ud574\uc84c\ub2e4. \uc790\uc5f0\uc120\ud0dd\uc740 \uc0dd\ubb3c\uc774 \uc758\uc2dd\uc801\uc73c\ub85c \uc6d0\ud558\ub294 \ubaa8\uc2b5\uc73c\ub85c \ubcc0\uc2e0\ud55c\ub2e4\ub294 \uc124\uba85\uc774 \uc544\ub2c8\ub2e4. \uc774 \uae00\uc740 \ud604\ub300 \uc9c4\ud654\uc0dd\ubb3c\ud559 \uc804\uccb4\ub97c \uc694\uc57d\ud558\uc9c0\ub294 \uc54a\uc9c0\ub9cc, \ud55c \uc5ec\ud589\uc5d0\uc11c \ubcf8 \uc0c8\uc758 \ubaa8\uc2b5\ub9cc\uc73c\ub85c \uc774\ub860\uc774 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4\ub294 \uadf8\ub9bc\uc740 \ud53c\ud558\ub824 \ud55c\ub2e4. \ub2e4\uc708\uc740 \uc790\uc2e0\uc758 \uc0dd\uac01\uc744 \uc815\ub9ac\ud574 \ub450\uace0 \uc624\ub7ab\ub3d9\uc548 \uc790\ub8cc\ub97c \ubcf4\uc644\ud588\ub2e4. \uadf8\ub7ec\ub358 1858\ub144 \uc568\ud504\ub9ac\ub4dc \ub7ec\uc140 \uc6d4\ub9ac\uc2a4\uac00 \ubcf4\ub0b8 \uae00\uc744 \ubc1b\ub294\ub2e4. \ub2e4\uc708\uc740 \uadf8 \uc548\uc5d0 \uc790\uae30 \uad6c\uc0c1\uacfc \uac00\uae4c\uc6b4 \uc124\uba85\uc774 \uc788\uc74c\uc744 \uc54c\uc544\ubcf4\uc558\ub2e4. \ubc1c\uacac\uc758 \uc5ed\uc0ac\ub294 \ud63c\uc790\ub9cc\uc758 \uc11c\ub78d \uc548\uc5d0\uc11c \uc9c4\ud589\ub418\uc9c0 \uc54a\uc558\ub2e4. \uc774\ud6c4 \ub450 \uc0ac\ub78c\uc758 \uc790\ub8cc\uac00 \ud568\uaed8 \ubc1c\ud45c\ub418\uc5c8\ub2e4. \uc6d4\ub9ac\uc2a4\ub97c \ub2e4\uc708\uc758 \uc131\uacf5\uc744 \uc7ac\ucd09\ud55c \uc870\uc5f0\uc73c\ub85c\ub9cc \ubcf4\ub294 \uac83\uc740 \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4. \uac19\uc740 \uc911\uc694\ud55c \ubb38\uc81c\uc5d0 \ub3c5\ub9bd\uc801\uc73c\ub85c \uc811\uadfc\ud55c \uc5f0\uad6c\uc790\uac00 \uc788\uc5c8\ub2e4\ub294 \uc810\uc774 \ud575\uc2ec\uc774\ub2e4. \uc790\uc11c\uc804 \uc790\uccb4\ub3c4 \uc6d4\ub9ac\uc2a4\uc758 \uc124\uba85\uc744 \ub192\uc774 \ud3c9\uac00\ud55c\ub2e4. \uc5f0\uad6c\uc758 \uc6b0\uc120\uad8c\uacfc \uae30\uc5ec\ub97c \ud568\uaed8 \uc0dd\uac01\ud558\uac8c \ud558\ub294 \uc7a5\uba74\uc774\ub2e4. 1859\ub144 \u300e\uc885\uc758 \uae30\uc6d0\u300f\uc774 \ucd9c\ud310\ub418\uc5c8\ub2e4. \uc624\ub7ab\ub3d9\uc548 \ubaa8\uc740 \uc0dd\uac01\uacfc \uc790\ub8cc\uac00 \ub3c5\uc790\uc640 \ub2e4\ub978 \uc5f0\uad6c\uc790 \uc55e\uc5d0 \ub193\uc774\ub294 \uc21c\uac04\uc774\uc5c8\ub2e4. \ub2e4\uc708\uc740 \uc774\ud6c4 \ud310\ubcf8\uc744 \uace0\uce58\uace0 \ub2e4\ub978 \uc791\uc5c5\ub3c4 \uc774\uc5b4 \uac14\ub2e4. \ucc45 \ud55c \uad8c\uc774 \ub098\uc654\ub2e4\uace0 \uc0dd\ubb3c\uc5d0 \ub300\ud55c \uc9c8\ubb38\uc774 \ubaa8\ub450 \ub2eb\ud78c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ub298\uc758 \uc0dd\ubb3c\ud559\uc740 \uadf8 \ub4a4\uc758 \uc5f0\uad6c\uc640 \uc720\uc804\ud559 \ub4f1 \ub9ce\uc740 \uc9c0\uc2dd\uc73c\ub85c \ub354 \ubc1c\uc804\ud588\ub2e4. \ub2e4\uc708\uc774 \ud604\uc7ac\uc758 \ubaa8\ub4e0 \ub0b4\uc6a9\uc744 \uc774\ubbf8 \uc54c\uc558\ub2e4\uace0 \uce6d\ucc2c\ud560 \ud544\uc694\ub3c4, \uc774\ud6c4\uc5d0 \ubcf4\uc644\uc774 \uc788\uc5c8\ub2e4\ub294 \uc774\uc720\ub85c \uadf8\uc758 \uc9c8\ubb38\uc744 \uc791\uac8c \ub9cc\ub4e4 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \uc5b4\ub290 \uc2dc\ub300\uc5d0 \ubb34\uc5c7\uc744 \uc124\uba85\ud558\uace0 \ubb34\uc5c7\uc744 \uc544\uc9c1 \ubab0\ub790\ub294\uc9c0 \ub098\ub204\uc5b4 \ubcf4\ub294 \uac83\uc774 \uc815\ud655\ud558\ub2e4. \ub2e4\uc708\uc758 \ud68c\uace0\uc5d0\uc11c \ub0a8\ub294 \uac83\uc740 \ubc88\ub729\uc784\ubfd0 \uc544\ub2c8\ub77c \ubaa8\uc73c\uace0 \ube44\uad50\ud558\uba70 \ub2e4\uc2dc \uc4f0\ub294 \uc2dc\uac04\uc774\ub2e4. \ub3cc\uc544\ubcf8 \uae30\uc5b5\uc5d0\ub294 \uc800\uc790\uc758 \uc2dc\uc120\uacfc \ud3b8\uc9d1\uc758 \ud55c\uacc4\ub3c4 \uc788\uc9c0\ub9cc, \uc21c\uc2dd\uac04\uc758 \ubc1c\uacac\ub2f4\ubcf4\ub2e4 \uc5f0\uad6c\uc758 \uc5ec\ub7ec \ub2e8\uacc4\ub97c \ubcf4\uc5ec \uc900\ub2e4. \uad00\ucc30\uacfc \ud574\uc11d \uc0ac\uc774\uc5d0 \uc5bc\ub9c8\ub098 \ub9ce\uc740 \uc77c\uc774 \ub4e4\uc5b4\uac00\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \uc790\uc5f0\ubb3c\uc744 \uc0b4\ud53c\ub294 19\uc138\uae30 \uc5f0\uad6c\uc790\uc758 \ubd84\uc704\uae30\ub97c \uc0c1\uc0c1\ud55c AI \uc0bd\ud654\ub2e4. \ub2e4\uc708\uc758 \uc2e4\uc81c \uc5bc\uad74\uacfc \ubc29\uc744 \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ucc45\uc0c1 \uc704\uc758 \uc791\uc740 \ud45c\ubcf8\uc744 \uc785\uad6c\ub85c \uc0bc\uc544 \uc5ec\ud589 \ub4a4\uc5d0\ub3c4 \ub05d\ub098\uc9c0 \uc54a\uc558\ub358 \uc9c8\ubb38\uc758 \uc2dc\uac04\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790."}, {"id": "discovery-panel-labels", "title": "\uc6b0\uc8fc\uc120 \uc548\uc5d0\ub3c4 \uc791\uc740 \uc774\ub984\ud45c\uac00 \uac00\ub4dd\ud558\ub2e4", "summary": "\uc6b0\uc8fc\uc120 \ud328\ub110\uc758 \uc2e4\uc81c \uc0ac\uc9c4\uc5d0\uc11c \ubc18\ubcf5\ub418\ub294 \ubaa8\uc591\uacfc \ud45c\uc2dc\ub97c \ucc3e\uc544\ubd05\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uc6b0\uc8fc\uc640 \ucc9c\ubb38", "categories": ["science"], "url": "stories/discovery-panel-labels/index.html", "image": "../media/discovery-panel-labels.jpg", "alt": "NASA\uc758 \ub514\uc2a4\ucee4\ubc84\ub9ac\ud638 \ube44\ud589 \uac11\ud310 \ud328\ub110 \uc2e4\uc81c \uc0ac\uc9c4. \uc6d0\ud615 \ubd80\ubd84\uacfc \uc0c9 \ud14c\ub450\ub9ac, \uc791\uc740 \ud45c\uc2dc\ub4e4\uc774 \ubc18\ubcf5\ub429\ub2c8\ub2e4.", "text": "\uc6b0\uc8fc\uc120 \uc548\uc5d0\ub3c4 \uc791\uc740 \uc774\ub984\ud45c\uac00 \uac00\ub4dd\ud558\ub2e4 \ub514\uc2a4\ucee4\ubc84\ub9ac\ud638 \ud328\ub110\uc744 \uac00\uae4c\uc774 \ubcf4\uae30 \uc6b0\uc8fc\uc120 \ud328\ub110\uc758 \uc2e4\uc81c \uc0ac\uc9c4\uc5d0\uc11c \ubc18\ubcf5\ub418\ub294 \ubaa8\uc591\uacfc \ud45c\uc2dc\ub97c \ucc3e\uc544\ubd05\ub2c8\ub2e4. \uc6b0\uc8fc\uc640 \ucc9c\ubb38 \uacfc\ud559\uacfc \ubc1c\uacac \uc6b0\uc8fc\uc120 \ub0b4\ubd80\ub97c \uc0c1\uc0c1\ud558\uba74 \uac70\ub300\ud55c \ud654\uba74\uc774\ub098 \uba4b\uc9c4 \uc870\uc885\uc11d\ubd80\ud130 \ub5a0\uc624\ub978\ub2e4. \uadf8\ub7f0\ub370 NASA\uac00 \uacf5\uac1c\ud55c \ub514\uc2a4\ucee4\ubc84\ub9ac\ud638 \ube44\ud589 \uac11\ud310 \ud328\ub110 \uc0ac\uc9c4\uc744 \uac00\uae4c\uc774 \ubcf4\uba74, \ub465\uadfc \ubd80\ubd84\ub4e4\uc774 \uc904\uc9c0\uc5b4 \uc788\uace0 \uadf8 \uacc1\uc5d0\ub294 \uc791\uc740 \uae00\uc790\uc640 \ud45c\uc2dc\uac00 \ubd99\uc5b4 \uc788\ub2e4. \uc804\uccb4 \uc6b0\uc8fc\uc120\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ud48d\uacbd\uc774 \uc544\ub2c8\ub2e4. \uc881\uc740 \ud55c \ubd80\ubd84\uc744 \ubaa8\ud615 \uc81c\uc791 \ub4f1\uc5d0 \uc4f8 \uc218 \uc788\ub3c4\ub85d \uacf5\uac1c\ud55c \uc2e4\uc81c \ud328\ub110 \uc790\ub8cc\ub2e4. \ub113\uc740 \uc6b0\uc8fc\ubcf4\ub2e4 \uba3c\uc800 \uc190\uc774 \ub2ff\uc744 \ub9cc\ud55c \uac70\ub9ac\uc758 \ubb3c\uac74\uc744 \ubcf4\uac8c \ub41c\ub2e4. \uc0ac\uc9c4 \uc18d\uc5d0\ub294 \uc11c\ub85c \ub2ee\uc740 \ub465\uadfc \ubd80\ubd84\uc774 \ubc18\ubcf5\ub41c\ub2e4. \uba87\uba87 \ubd80\ubd84\uc5d0\ub294 \ub178\ub780 \ud14c\ub450\ub9ac\uac00 \uc788\uace0, \uc8fc\ubcc0\uc5d0\ub294 \uc5b4\ub450\uc6b4 \uc0c9\uacfc \ubd89\uc740\uc0c9\uc774 \ud568\uaed8 \uc4f0\uc600\ub2e4. \uba40\ub9ac\uc11c \ubcf4\uba74 \ubcf5\uc7a1\ud55c \ubb34\ub2ac \uac19\uc9c0\ub9cc \uac00\uae4c\uc774\uc5d0\uc11c\ub294 \uc791\uc740 \ucc28\uc774\ub4e4\uc774 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc6b0\ub9ac\uc758 \ucc45\uc0c1\uc5d0\uc11c\ub3c4 \ube44\uc2b7\ud55c \uc77c\uc774 \uc0dd\uae34\ub2e4. \ucf00\uc774\ube14\uc774\ub098 \uc11c\ub78d, \uc5f4\uc1e0\uac00 \uc5ec\ub7ec \uac1c\uba74 \uc774\ub984\ud45c\ub098 \uc0c9\uae54\ub85c \uad6c\ubcc4\ud55c\ub2e4. \uc6b0\uc8fc\uc120\uc758 \uc815\ud655\ud55c \uc791\uc5c5 \uc808\ucc28\ub97c \ubaa8\ub974\ub354\ub77c\ub3c4, \ube44\uc2b7\ud55c \uac83\ub4e4\uc744 \ud5f7\uac08\ub9ac\uc9c0 \uc54a\uac8c \ud45c\uc2dc\ud558\ub294 \ud544\uc694\ub294 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc774 \uc0ac\uc9c4\uc5d0\uc11c \uac01\uac01\uc774 \ubb34\uc2a8 \uae30\ub2a5\uc744 \ud558\ub294\uc9c0\uae4c\uc9c0 \ubaa8\ub450 \uc77d\uc5b4 \ub0b4\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub465\uae00\ub2e4\uace0 \uc804\ubd80 \uac19\uc740 \uc2a4\uc704\uce58\ub77c\uace0 \ubd80\ub974\uac70\ub098 \uc0c9\uae54\ub9c8\ub2e4 \ud2b9\uc815 \uae30\ub2a5\uc774 \uc788\ub2e4\uace0 \uc815\ud558\uba74 \uc2e4\uc81c \uc790\ub8cc\ub97c \ub118\uc5b4\uc120 \uc124\uba85\uc774 \ub41c\ub2e4. \ub300\uc2e0 \uac19\uc740 \ubaa8\uc591\uc774 \ubc18\ubcf5\ub418\ub294 \ubc29\uc2dd\uacfc \uadf8 \uc606\uc758 \ud45c\uc2dc\ub97c \ucc28\ub840\ub85c \uc0b4\ud3b4\ubcf4\uc790. \ubcf5\uc7a1\ud55c \uae30\uacc4\uc758 \ud45c\uba74\uc744 \uadf8\ub0e5 \ubcf5\uc7a1\ud558\ub2e4\uace0\ub9cc \ub290\ub07c\ub294 \uac83\uacfc, \uc5b4\ub5a4 \uad6c\ubd84\uc774 \ub9c8\ub828\ub418\uc5b4 \uc788\ub294\uc9c0 \ubcf4\ub294 \uac83\uc740 \uc870\uae08 \ub2e4\ub978 \uacbd\ud5d8\uc774\ub2e4. \ubcf5\uc7a1\ud55c \uc7a5\ube44\uac00 \uc788\uc5b4\ub3c4 \uc0ac\uc6a9\uc790\uac00 \ud544\uc694\ud55c \ubd80\ubd84\uc744 \uad6c\ubcc4\ud558\uae30 \uc5b4\ub824\uc6b0\uba74 \uc791\uc5c5\uc740 \ub354 \uae4c\ub2e4\ub85c\uc6cc\uc9c8 \uc218 \uc788\ub2e4. \ud328\ub110\uc758 \ud45c\uc2dc\ub97c \ubcf4\ub294 \uc77c\uc740 \uadf8\ub7f0 \uc0ac\ub78c\uacfc \uc7a5\uce58\uc758 \uad00\uacc4\ub97c \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ubaa8\uc591\uc774 \ubc18\ubcf5\ub418\ub294 \uac00\uc6b4\ub370 \uc791\uc740 \uc774\ub984\uacfc \uc0c9\uc758 \ucc28\uc774\uac00 \uc788\ub2e4. \uba40\ub9ac\uc11c \ud558\ub098\uc758 \ubcf5\uc7a1\ud55c \uba74\ucc98\ub7fc \ubcf4\uc774\ub294 \uac83\ub3c4 \uac00\uae4c\uc774\uc5d0\uc11c\ub294 \ub098\ub204\uc5b4 \uc77d\uc744 \uc790\ub9ac\uac00 \uc0dd\uae34\ub2e4. \uc774\uac83\uc740 \uc0ac\uc9c4 \uc18d \uac01 \ubd80\ud488\uc758 \uc2e4\uc81c \uc0ac\uc6a9 \uc808\ucc28\ub97c \ud655\uc778\ud55c \ub9d0\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub290 \uac83\uc774 \ubc84\ud2bc\uc774\uace0 \uc5b4\ub290 \uac83\uc774 \uc5f0\uacb0\uad6c\uc778\uc9c0, \ud2b9\uc815\ud55c \uc0c9\uc774 \ubb34\uc2a8 \ub73b\uc778\uc9c0\ub294 \ubcc4\ub3c4 \uae30\uc220 \uc790\ub8cc\uac00 \ud544\uc694\ud55c \ubb38\uc81c\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc9c1\uc811 \ubcf4\uc774\ub294 \ubc30\uc5f4\uacfc \ud45c\uae30\ub77c\ub294 \uc0ac\uc2e4\uc5d0\uc11c \ucd9c\ubc1c\ud55c\ub2e4. \ubaa8\ub974\ub294 \ubd80\ubd84\uc744 \uc804\ubd80 \ud558\ub098\uc758 \uc2a4\uc704\uce58\ub77c\uace0 \ubd80\ub974\uc9c0 \uc54a\uc73c\uba74 \uad00\ucc30\ub3c4 \ub354 \uc815\ud655\ud574\uc9c4\ub2e4. \uac19\uc740 \ubaa8\uc591\uc774 \ubc18\ubcf5\ub418\uba74 \uaddc\uce59\uc744 \ucc3e\uae30 \uc27d\uc9c0\ub9cc \uc11c\ub85c \ud5f7\uac08\ub9b4 \uc218\ub3c4 \uc788\ub2e4. \uadf8 \uc606\uc5d0 \uae00\uc790\uc640 \uc0c9, \uc704\uce58\uc758 \ucc28\uc774\ub97c \ub193\uc73c\uba74 \uc5b4\ub290 \ud56d\ubaa9\uc778\uc9c0 \ub354 \uc138\ubd84\ud574\uc11c \ubcfc \uc218 \uc788\ub2e4. \uc2e4\uc81c\ub85c \uc774 \ud328\ub110\uc774 \uc5b4\ub5a4 \uc124\uacc4 \uae30\uc900\uc744 \ub530\ub974\ub294\uc9c0 \ub2e8\uc815\ud558\uc9c0 \uc54a\ub354\ub77c\ub3c4, \ube44\uc2b7\ud55c \ubd80\ud488\uc744 \uad6c\ubcc4\ud558\ub294 \uc815\ubcf4\uac00 \uc65c \ud544\uc694\ud560\uc9c0\ub294 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc6b0\ub9ac \ucc45\uc0c1\uc758 \ucf00\uc774\ube14\uc774\ub098 \uc815\ub9ac\ud568\uc744 \ube44\uad50\ud55c \uac83\uc740 \uc774 \ud544\uc694\ub97c \uac00\uae4c\uc774 \ub290\ub07c\uac8c \ud558\ub294 \ube44\uc720\ub2e4. \uc6b0\uc8fc\uc120\uc758 \uc791\uc5c5\uc774 \uc9d1\uc758 \uc815\ub9ac\uc640 \uac19\uc740 \uc704\ud5d8\ub3c4\ub098 \uc808\ucc28\ub97c \uac00\uc9c4\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc775\uc219\ud55c \uc608\uc5d0\uc11c \uad6c\ubd84\uc758 \ud544\uc694\ub97c \ub5a0\uc62c\ub9b0 \ub4a4 \uc2e4\uc81c \uc0ac\uc9c4\uc758 \ubc94\uc704\ub85c \ub3cc\uc544\uc624\ub294 \uac83\uc774 \uc88b\ub2e4. \ube44\uc720\uac00 \uae30\uc220\uc758 \uc815\ud655\ud55c \ub0b4\uc6a9\uc744 \ub300\uc2e0\ud558\uc9c0 \uc54a\ub3c4\ub85d \ud558\ub294 \uac83\uc774\ub2e4. NASA \uc790\ub8cc\uba85\uacfc \uc0ac\uc9c4 \ubc88\ud638\ub294 \uc774\ubbf8\uc9c0 \uc790\uccb4\ub97c \ucc3e\uac8c \ud574 \uc8fc\ub294 \uae30\ub85d\uc774\ub2e4. \ud328\ub110 \uc704\uc758 \uc791\uc740 \uae00\uc740 \uc0ac\uc9c4 \uc548\uc5d0 \ucc0d\ud78c \ubb3c\uac74\uc758 \ud45c\uae30\ub2e4. \ud654\uba74\uc5d0\ub294 \ud568\uaed8 \ubcf4\uc774\uc9c0\ub9cc \uc11c\ub85c \ub2e4\ub978 \ub300\uc0c1\uc744 \uc2dd\ubcc4\ud55c\ub2e4. \uc790\ub8cc\uc758 \uc774\ub984\uc744 \uc77d\ub294 \uc77c\uacfc \ud328\ub110\uc758 \uae30\ub2a5\uc744 \ud574\uc11d\ud558\ub294 \uc77c\uc740 \uad6c\ubd84\ub418\uc5b4\uc57c \ud55c\ub2e4. \ud558\ub098\ub97c \uc548\ub2e4\uace0 \ub2e4\ub978 \ud558\ub098\uc758 \ub2f5\uc774 \uc790\ub3d9\uc73c\ub85c \ub098\uc624\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. Discovery Flight Deck Panels\ub77c\ub294 \uc774\ub984\uc740 \uc5b4\ub5a4 \ub9e5\ub77d\uc5d0\uc11c \uc0ac\uc9c4\uc744 \ub9cc\ub098\uc57c \ud558\ub294\uc9c0 \uc54c\ub824 \uc900\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \ub9d0\ub9cc\uc73c\ub85c \uac1c\ubcc4 \ubd80\ud488\uc758 \uae30\ub2a5\uacfc \uc0c1\ud0dc\ub97c \ubaa8\ub450 \uc54c \uc218\ub294 \uc5c6\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \uc2e4\uc81c \uc774\ubbf8\uc9c0\uc5d0 \ub098\ud0c0\ub09c \uc6d0\ud615 \ubd80\ubd84\uacfc \ud14c\ub450\ub9ac, \ud45c\uae30\ub97c \uad00\ucc30\ud55c\ub2e4. \uc544\ub294 \uac83\uacfc \uc544\uc9c1 \uae30\uc220 \ubb38\uc11c\uac00 \ud544\uc694\ud55c \uac83\uc744 \ub098\ub204\uc5b4 \ub450\uba74 \uc0ac\uc9c4\uc774 \ub354 \uc88b\uc740 \uc9c8\ubb38\uc758 \ucd9c\ubc1c\uc810\uc774 \ub41c\ub2e4. \uc6b0\uc8fc\uc120\uc740 \uac70\ub300\ud55c \ub3d9\uccb4\uc640 \ubc1c\uc0ac\uc758 \ubd88\uaf43\uc73c\ub85c \uae30\uc5b5\ub418\uae30 \uc27d\ub2e4. \uc2e4\ub0b4\uc758 \ud328\ub110\uc740 \uadf8 \uc7a5\ube44\ub97c \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5bb\uac8c \uc77d\uace0 \ub2e4\ub8e8\ub294\uc9c0\ub77c\ub294 \ub2e4\ub978 \ud06c\uae30\uc758 \uc774\uc57c\uae30\ub97c \ubcf4\uc5ec \uc900\ub2e4. \uae30\uacc4\ub97c \ub9cc\ub4dc\ub294 \uc77c\uc5d0\ub294 \uac15\ud55c \ucd94\uc9c4\ub825\ubfd0 \uc544\ub2c8\ub77c \ud544\uc694\ud55c \uac83\uc744 \uad6c\ubcc4\ud558\uac8c \ud558\ub294 \ud45c\uba74\ub3c4 \ud3ec\ud568\ub41c\ub2e4. \uc7a5\uce58\uc758 \ub2a5\ub825\uacfc \uc0ac\uc6a9\uc790\uc758 \ud589\ub3d9\uc740 \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\ub2e4. \ub2e4\uc74c\uc5d0 \uc0ac\uc9c4\uc744 \ubcfc \ub54c\uc5d0\ub294 \uc804\uccb4\uc758 \ubcf5\uc7a1\ud568\uc744 \ud55c \ubc88 \ubcf4\uace0 \uc791\uc740 \ud45c\uae30\ub97c \ud558\ub098 \ucc3e\uc544\ubcf4\uc790. \ubb34\uc2a8 \uae30\ub2a5\uc778\uc9c0 \uc989\uc2dc \uc54c\uc544\ub9de\ud788\uae30\ubcf4\ub2e4 \uc5b4\ub5a4 \uad6c\ubd84\uc774 \ub208\uc5d0 \ubcf4\uc774\ub294\uc9c0 \uc0b4\ud53c\uba74 \ub41c\ub2e4. \uc791\ub3d9\ubc95\uc744 \ubc30\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uc124\uacc4\uac00 \uc0ac\ub78c\uc5d0\uac8c \ub9d0\uc744 \uac74\ub124\ub294 \uc790\ub9ac\ub97c \ubcfc \uc218 \uc788\ub2e4. \uc6b0\uc8fc\uc120 \uc548\uc758 \uc791\uc740 \uc774\ub984\ud45c\ub4e4\uc740 \uba3c \ud0d0\uc0ac\ub97c \uc775\uc219\ud55c \uc77d\uae30\uc758 \ubb38\uc81c\uc640 \uc5f0\uacb0\ud574 \uc900\ub2e4. \uc774 \uae00\uc5d0\ub294 \ud328\ub110\uc744 \uc0c8\ub85c \uc0c1\uc0c1\ud55c \uc0bd\ud654 \ub300\uc2e0 NASA\uac00 \uc81c\uacf5\ud55c \uc2e4\uc81c \uc0ac\uc9c4\uc744 \ub123\uc5c8\ub2e4. \uad6c\uccb4\uc801\uc778 \uc0ac\ubb3c\uc774 \uc911\uc2ec\uc77c \ub54c \uc6d0\ub798 \uc790\ub8cc\uac00 \ubcf4\uc5ec \uc8fc\ub294 \uc791\uc740 \ucc28\uc774\ub4e4\uc774 \uc911\uc694\ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \ud0d0\uc0ac \uc774\uc57c\uae30\ub294 \uc885\uc885 \ud070 \uc22b\uc790\uc640 \uba3c \uac70\ub9ac\ub85c \uae30\uc5b5\ub41c\ub2e4. \uadf8\ub7ec\ub098 \uc7a5\uce58\ub97c \uc0ac\uc6a9\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uac00\uae4c\uc774 \ub193\uc778 \ud45c\uc2dc \ud558\ub098\ub3c4 \uc791\uc5c5\uc758 \uc77c\ubd80\uc600\uc744 \uac83\uc774\ub2e4. \uc774 \ud328\ub110 \uc0ac\uc9c4\uc740 \uac70\ub300\ud55c \uc6b0\uc8fc\uc120\uc5d0\ub3c4 \uc791\uac8c \uc77d\uc5b4\uc57c \ud560 \uc815\ubcf4\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc870\uc6a9\ud788 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "earth-map-for-globe", "title": "\uc9c0\uad6c\ubcf8\uc758 \ub465\uadfc \ubab8\uc5d0\ub294 \uc5b4\ub5a4 \uadf8\ub9bc\uc744 \uc785\ud790\uae4c", "summary": "\ub465\uadfc \uc9c0\uad6c\ub97c \ud45c\ud604\ud558\uae30 \uc704\ud574 \ub9c8\ub828\ub41c \ud3c9\ud3c9\ud55c \uc9c0\ub3c4 \uc790\ub8cc\ub97c \ub4e4\uc5ec\ub2e4\ubd05\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uc6b0\uc8fc\uc640 \ucc9c\ubb38", "categories": ["science"], "url": "stories/earth-map-for-globe/index.html", "image": "../media/earth-map-for-globe.jpg", "alt": "NASA\uc758 Earth (A) \uc9c0\ub3c4 \ud14d\uc2a4\ucc98. \ub300\ub959\uacfc \ubc14\ub2e4\uac00 \uc9c1\uc0ac\uac01\ud615\uc73c\ub85c \ud3bc\uccd0\uc9c4 \uc790\ub8cc\uc774\uba70 \ub2e8\uc77c \ucd2c\uc601 \uc0ac\uc9c4\uc774 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\uc9c0\uad6c\ubcf8\uc758 \ub465\uadfc \ubab8\uc5d0\ub294 \uc5b4\ub5a4 \uadf8\ub9bc\uc744 \uc785\ud790\uae4c NASA\uc758 \ub0a9\uc791\ud55c \uc9c0\uad6c \uc790\ub8cc\ub97c \ubcf4\ub294 \ubc29\ubc95 \ub465\uadfc \uc9c0\uad6c\ub97c \ud45c\ud604\ud558\uae30 \uc704\ud574 \ub9c8\ub828\ub41c \ud3c9\ud3c9\ud55c \uc9c0\ub3c4 \uc790\ub8cc\ub97c \ub4e4\uc5ec\ub2e4\ubd05\ub2c8\ub2e4. \uc6b0\uc8fc\uc640 \ucc9c\ubb38 \uacfc\ud559\uacfc \ubc1c\uacac \uc0ac\uc9c4\uc744 \ubcf4\uba74 \uc9c0\uad6c\uac00 \ub465\uadfc \uacf5\uc774 \uc544\ub2c8\ub77c \uae38\ucb49\ud55c \uc9c1\uc0ac\uac01\ud615\uc73c\ub85c \ud3bc\uccd0\uc838 \uc788\ub2e4. \uc6b0\ub9ac\uac00 \uc544\ub294 \ub300\ub959\ub4e4\uc774 \ub098\ub780\ud788 \ub193\uc774\uace0, \ubc14\ub2e4\uc5d0\ub3c4 \ubc1d\uace0 \uc5b4\ub450\uc6b4 \ubb34\ub2ac\uac00 \uc774\uc5b4\uc9c4\ub2e4. NASA\uac00 \uacf5\uac1c\ud55c Earth (A)\ub77c\ub294 \uc9c0\uad6c \uc790\ub8cc\ub2e4. \uc774\uac83\uc740 \uc6b0\uc8fc\uc5d0\uc11c \uc9c0\uad6c \uc804\uccb4\ub97c \uc9c1\uc0ac\uac01\ud615\uc73c\ub85c \ud55c \ubc88\uc5d0 \ucc0d\uc5c8\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. NASA\ub294 \uc774 \ud30c\uc77c\uc744 \uc774\ubbf8\uc9c0\uc640 \ud14d\uc2a4\ucc98 \uc790\ub8cc \ubaa8\uc74c\uc5d0\uc11c \uc81c\uacf5\ud55c\ub2e4. \ub465\uadfc \ub300\uc0c1\uc744 \ud45c\ud604\ud560 \ub54c \uc4f8 \uc218 \uc788\ub3c4\ub85d \ud3bc\uccd0 \ub193\uc740 \uadf8\ub9bc\uc73c\ub85c \ubcf4\ub294 \ud3b8\uc774 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \ud14d\uc2a4\ucc98\ub77c\uace0 \ud558\uba74 \ucc9c\uc774\ub098 \uc885\uc774\uc758 \ucd09\uac10\ubd80\ud130 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \ub514\uc9c0\ud138 \ubaa8\ud615\uc5d0\uc11c\ub294 \ubb3c\uccb4\uc758 \uac89\ubaa8\uc2b5\uc744 \ub098\ud0c0\ub0b4\ub294 \uc774\ubbf8\uc9c0\ub3c4 \uadf8\ub807\uac8c \ubd80\ub978\ub2e4. \uacf5 \ubaa8\uc591\ub9cc \ub9cc\ub4e4\uc5b4 \ub193\ub294 \uac83\uacfc \uadf8 \uc704\uc5d0 \ub300\ub959\uacfc \ubc14\ub2e4\uc758 \ubaa8\uc2b5\uc744 \uc785\ud788\ub294 \uac83\uc740 \ub2e4\ub978 \uc77c\uc774\ub2e4. \ube48 \uc9c0\uad6c\ubcf8\uc5d0 \uc9c0\ub3c4\ub97c \ubd99\uc774\ub294 \ubaa8\uc2b5\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ub465\uadfc \ud2c0\uacfc \ud45c\uba74\uc758 \uadf8\ub9bc\uc774 \ud569\uccd0\uc9c0\uba74 \ube44\ub85c\uc18c \uc6b0\ub9ac\uac00 \uc54c\uc544\ubcf4\ub294 \uc9c0\uad6c\uc758 \uc5bc\uad74\uc774 \ub41c\ub2e4. \uc774 \ube44\uc720\ub294 \uc790\ub8cc\uc758 \uc4f0\uc784\uc744 \uc774\ud574\ud558\ub294 \ud55c \uac00\uc9c0 \ubc29\ubc95\uc774\ub2e4. \ud3bc\uccd0\uc9c4 \uc790\ub8cc\uc5d0\uc11c\ub294 \uc704\uc544\ub798 \uac00\uc7a5\uc790\ub9ac\uc758 \ubaa8\uc591\uc774 \ub0af\uc124\uac8c \ubcf4\uc77c \uc218 \uc788\ub2e4. \ud3c9\uba74\uc5d0 \ub193\uc778 \uc9c0\ub3c4\ub97c \ubcfc \ub54c\uc640 \ub465\uadfc \uc9c0\uad6c\ubcf8\uc744 \ubcfc \ub54c\uc758 \uc778\uc0c1\uc774 \ub298 \uac19\uc9c0\ub294 \uc54a\ub2e4. \uac19\uc740 \ub300\uc0c1\uc744 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ud45c\ud604\ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \ud2b9\uc815 \uc9c0\ub3c4 \ud22c\uc601\ubc95\uc758 \uc774\ub984\uc774\ub098 \uba74\uc801\uc758 \uc815\ud655\uc131\uc744 \uc774 \ud30c\uc77c\ub9cc \ubcf4\uace0 \ud655\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub300\uc2e0 \uc2e4\uc81c \uc81c\uacf5\ub41c \uc774\ubbf8\uc9c0\uc5d0\uc11c \ub300\ub959\ub4e4\uc774 \uc5b4\ub514\uc5d0 \ub193\uc600\ub294\uc9c0 \ucc28\ub840\ub85c \ucc3e\uc544\ubcf4\ub294 \ub370 \uc9d1\uc911\ud574 \ubcf4\uc790. \uc775\uc219\ud55c \uc9c0\uad6c\uc5d0\ub3c4 \uc5ec\ub7ec \ud45c\ud604 \ubc29\uc2dd\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ubcf4\uc778\ub2e4. \uc544\ubb34 \ubb34\ub2ac \uc5c6\ub294 \uad6c\ub97c \ubcf4\uc558\uc744 \ub54c \uadf8\uac83\uc774 \uc9c0\uad6c\uc778\uc9c0 \ub2e4\ub978 \uacf5\uc778\uc9c0 \uc54c\uae30 \uc5b4\ub835\ub2e4. \ub300\ub959\uacfc \ubc14\ub2e4\uc758 \uc774\ubbf8\uc9c0\uac00 \ud45c\uba74\uc5d0 \ub193\uc774\uba74 \ube44\ub85c\uc18c \uc775\uc219\ud55c \ubaa8\uc2b5\uc774 \ub41c\ub2e4. 3\ucc28\uc6d0 \ubaa8\ud615\uc758 \ud615\ud0dc\uc640 \ud45c\uba74\uc744 \ud45c\ud604\ud558\ub294 \uc790\ub8cc\uac00 \uc11c\ub85c \ub2e4\ub978 \uc5ed\ud560\uc744 \ub9e1\ub294 \uac83\uc774\ub2e4. NASA\uac00 \ud14d\uc2a4\ucc98 \ud30c\uc77c\uc744 \ub530\ub85c \uc81c\uacf5\ud55c\ub2e4\ub294 \uc810\uc774 \uc774 \uad00\uacc4\ub97c \ubcf4\uc5ec \uc900\ub2e4. \uc774\uac83\uc740 \uc2e4\uc81c \uc9c0\uad6c\uac00 \ube48 \uacf5\uc5d0 \uadf8\ub9bc\uc744 \ubd99\uc5ec \ub9cc\ub4e0 \ubb3c\uac74\uc774\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub514\uc9c0\ud138 \ud45c\ud604\uc5d0\uc11c \ubb34\uc5c7\uc744 \ub530\ub85c \uc900\ube44\ud558\ub294\uc9c0 \uc774\ud574\ud558\uae30 \uc704\ud55c \uc124\uba85\uc774\ub2e4. \ubaa8\ud615\uacfc \uc9c0\ub3c4\ub97c \ud569\uce58\ub294 \uacfc\uc815\uc740 \ucef4\ud4e8\ud130 \uc548\uc758 \ud45c\ud604 \ubc29\ubc95\uc5d0 \uc18d\ud55c\ub2e4. \uc7ac\ub8cc\uc758 \uc774\ub984\uc744 \uc2e4\uc81c \ucc9c\uc758 \ucd09\uac10\uc73c\ub85c\ub9cc \uc77d\uc9c0 \uc54a\uace0 \uc0ac\uc6a9\ub418\ub294 \ubb38\ub9e5\uc5d0\uc11c \ubcf4\uba74 \ub0af\uc120 \ub2e8\uc5b4\ub3c4 \uad6c\uccb4\uc801\uc778 \uae30\ub2a5\uc744 \uc5bb\ub294\ub2e4. \ud3bc\uccd0 \ub193\uc740 \uc774\ubbf8\uc9c0\ub294 \uacbd\uacc4\ub97c \uac00\uc9c4 \uc9c1\uc0ac\uac01\ud615\uc774\ub2e4. \ub465\uadfc \ud45c\uba74\uc5d0\uc11c\ub294 \uadf8 \uc790\ub8cc\uac00 \uc5b4\ub5a4 \ubc29\ud5a5\uc73c\ub85c \ub300\uc751\ub418\ub294\uc9c0 \uc54c\uc544\uc57c \ud55c\ub2e4. \uc774\ubbf8\uc9c0\uc758 \uac00\uc7a5\uc790\ub9ac\uc640 \uadf9\uc9c0\ubc29\uc774 \ubaa8\ud615\uc5d0 \uc5b4\ub5bb\uac8c \ub193\uc774\ub294\uc9c0\uc5d0 \ub530\ub77c \ubcf4\uc774\ub294 \uacb0\uacfc\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ub2e8\uc21c\ud788 \uc544\ubb34 \uadf8\ub9bc\uc774\ub098 \uac19\uc740 \ube44\uc728\ub85c \uacf5\uc5d0 \ubd99\uc774\uba74 \ub41c\ub2e4\ub294 \uc124\uba85\uc73c\ub85c \ub05d\ub0bc \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uc774 \uae00\uc5d0\uc11c\ub294 \ud30c\uc77c\ub9cc \ubcf4\uace0 \ud2b9\uc815\ud55c \uc9c0\ub3c4 \ud22c\uc601\ubc95\uc758 \ubaa8\ub4e0 \uc131\uc9c8\uc744 \ud655\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4. \uba74\uc801\uacfc \uac70\ub9ac\uc758 \uc815\ud655\uc131\uc744 \uc0c8\ub85c \uce21\uc815\ud55c \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uc2e4\uc81c \uc81c\uacf5\ub41c \uc774\ubbf8\uc9c0\uac00 \uc9c0\ub3c4 \ud14d\uc2a4\ucc98\ub77c\ub294 \ubc94\uc704\ub97c \uba3c\uc800 \uc77d\ub294\ub2e4. \ud3c9\uba74\uacfc \uace1\uba74\uc758 \ud45c\ud604\uc774 \uc11c\ub85c \ub2e4\ub978 \uc870\uac74\uc744 \uac00\uc9c4\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc544\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \uc5b4\uc0c9\ud574 \ubcf4\uc774\ub294 \ubd80\ubd84\uc744 \ub2e4\uc2dc \ubcfc \uc218 \uc788\ub2e4. \uc9c0\uad6c\uc758 \ud45c\uba74\uc744 \ub113\uac8c \ubcf4\uc5ec \uc8fc\ub294 \uc774\ubbf8\uc9c0\ub77c\uace0 \uc5b8\uc81c\ub098 \uc5b4\ub290 \uc21c\uac04 \ud55c \uce74\uba54\ub77c\uac00 \ucc0d\uc740 \ud55c \uc7a5\uba74\uc774\ub77c\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc790\ub8cc\uc758 \uc81c\ubaa9\uacfc \uc81c\uc791 \uc124\uba85\uc744 \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \ud14d\uc2a4\ucc98\ub85c \uc815\ub9ac\ud574 \uc81c\uacf5\ud558\ub294 \uadf8\ub9bc\uc5d0\ub294 \ubaa8\ud615\uc758 \ud45c\uba74\uc5d0 \uc4f0\ub3c4\ub85d \ubc30\uce58\ud55c \uc815\ubcf4\ub77c\ub294 \uc131\uaca9\uc774 \uc788\ub2e4. \uc6d0\ub798\uc758 \uad00\uce21\uacfc \ucd5c\uc885 \ud30c\uc77c\uc758 \uc4f0\uc784\uc744 \uad6c\ubd84\ud574 \ubcfc \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \uc774 \ud30c\uc77c\uc744 \ubcf4\uba70 \uad6c\ub984\uacfc \uacc4\uc808, \ucd2c\uc601 \ub0a0\uc9dc\uc758 \ubaa8\ub4e0 \uc138\ubd80\ub97c \ucd94\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5ec\uae30\uc11c \uc77d\ub294 \uac83\uc740 \ub300\ub959\uacfc \ubc14\ub2e4\uac00 \ub193\uc778 \ud45c\uba74 \uc774\ubbf8\uc9c0\uc758 \ubaa8\uc2b5\uc774\ub2e4. \uc2e4\uc81c \uc9c0\uad6c \uc804\uccb4\uc758 \ud2b9\uc815\ud55c \ub0a0\uc744 \uadf8\ub300\ub85c \ubcf4\uc5ec \uc900\ub2e4\ub294 \uc8fc\uc7a5\uacfc \uc9c0\uad6c \ubaa8\ud615\uc744 \uc54c\uc544\ubcfc \uc678\ud615 \uc790\ub8cc\ub77c\ub294 \uc124\uba85\uc740 \ub2e4\ub974\ub2e4. \uc790\ub8cc\uac00 \uc5b4\ub5a4 \ubaa9\uc801\uc73c\ub85c \uc81c\uacf5\ub418\ub294\uc9c0 \uc54c\uc544\uc57c \uc9c8\ubb38\ub3c4 \uc815\ud655\ud574\uc9c4\ub2e4. \uba3c\uc800 \uc775\uc219\ud55c \ub300\ub959 \ud558\ub098\ub97c \ucc3e\uc740 \ub4a4 \ubc14\ub2e4\ub97c \ub530\ub77c \uc606\uc73c\ub85c \uc774\ub3d9\ud574 \ubcf4\uc790. \ud654\uba74\uc5d0\uc11c \ub5a8\uc5b4\uc838 \ubcf4\uc774\ub294 \uacf3\ub3c4 \uad6c \uc704\uc5d0 \ub193\uc600\uc744 \ub54c\ub294 \ub2e4\ub978 \uad00\uacc4\ub85c \ub9cc\ub0a0 \uc218 \uc788\ub2e4. \uc9c0\uad6c\ubcf8\uacfc \ud3c9\uba74 \uc9c0\ub3c4\uac00 \uc11c\ub85c \ub2e4\ub978 \uac10\uac01\uc744 \uc8fc\ub294 \uc774\uc720\ub2e4. \uc5b4\ub290 \ud45c\ud604 \ud558\ub098\uac00 \ubaa8\ub4e0 \ubcf4\uae30\ub97c \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc774\ub807\uac8c \ubcf4\uba74 \uc9c0\uad6c \uadf8\ub9bc\uc744 \uc18c\ube44\ud558\ub294 \ubc29\uc2dd\ub3c4 \uc870\uae08 \ub2ec\ub77c\uc9c4\ub2e4. \uc608\uc05c \uc6b0\uc8fc \uc774\ubbf8\uc9c0\uc5d0\uc11c \ud55c \uac78\uc74c \ub354 \ub4e4\uc5b4\uac00 \ubb34\uc5c7\uc744 \ubaa8\ud615\uc758 \ud45c\uba74\uc5d0 \ub193\uc73c\ub824\uace0 \ub9cc\ub4e4\uc5c8\ub294\uc9c0 \ubb3c\uc744 \uc218 \uc788\ub2e4. \ud615\ud0dc\uc640 \uc774\ubbf8\uc9c0, \uad00\uce21\uacfc \ud45c\ud604\uc774\ub77c\ub294 \uce35\uc774 \ub098\ub25c\ub2e4. \uc775\uc219\ud55c \ub465\uadfc \uc9c0\uad6c\uc758 \uc5bc\uad74 \ub4a4\uc5d0\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc790\ub8cc\ub97c \uc900\ube44\ud558\uace0 \uc5f0\uacb0\ud558\ub294 \uc791\uc5c5\uc774 \uc788\uc5c8\ub2e4\ub294 \uc810\uc774 \ub0a8\ub294\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 NASA\uac00 \uacf5\uac1c\ud55c \uc2e4\uc81c \uc9c0\ub3c4 \ud14d\uc2a4\ucc98 \uc790\ub8cc\ub2e4. AI\uac00 \uc0c1\uc0c1\ud574\uc11c \uadf8\ub9b0 \uc9c0\uad6c\ub294 \uc544\ub2c8\uc9c0\ub9cc, \uadf8\ub807\ub2e4\uace0 \uc6b0\uc8fc\uc5d0\uc11c \ucd2c\uc601\ud55c \ub2e8\uc77c \uc7a5\uba74\uc758 \uc0ac\uc9c4\ub3c4 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc790\ub8cc\uc778\uc9c0 \uc544\ub294 \uac83\uc774 \uba3c\uc800\ub2e4. \ub2e4\uc74c\uc5d0 \ud654\uba74 \uc18d \uc9c0\uad6c\ubcf8\uc744 \ub9cc\ub098\uba74 \ub465\uadfc \ubaa8\uc591\ubfd0 \uc544\ub2c8\ub77c \uadf8 \uc704\uc5d0 \uc785\ud78c \ud45c\uba74\ub3c4 \ud55c \ubc88 \uc0dd\uac01\ud574 \ubcf4\uc790. \uc775\uc219\ud55c \ud589\uc131\uc758 \ubaa8\uc2b5 \ub4a4\uc5d0\ub294 \uc5b4\ub5a4 \ud2c0\uc5d0 \uc5b4\ub5a4 \uadf8\ub9bc\uc744 \uc5b9\uc744\uc9c0 \uace0\ub978 \uc791\uc5c5\uc774 \uc788\ub2e4. \uc9c0\uad6c\uc758 \uc5bc\uad74\uc740 \uadf8\ub807\uac8c \ud654\uba74 \uc18d\uc5d0\uc11c\ub3c4 \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4."}, {"id": "elephant-ear-fan", "title": "\ucf54\ub07c\ub9ac\uac00 \uadc0\ub97c \ud754\ub4dc\ub294 \ub370\uc5d0\ub294 \uc774\uc720\uac00 \uc788\ub2e4", "summary": "\ub290\uae0b\ud558\uac8c \uadc0\ub97c \ud384\ub7ed\uc774\ub294 \ucf54\ub07c\ub9ac. \uadf8 \uc6c0\uc9c1\uc784\uc5d0\ub294 \ub4e3\ub294 \uc77c \ub9d0\uace0\ub3c4 \ub2e4\ub978 \uc5ed\ud560\uc774 \uc788\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uc0dd\uba85\uacfc \uc778\uccb4", "categories": ["science"], "url": "stories/elephant-ear-fan/index.html", "image": "../media/elephant-ear-fan.jpg", "alt": "\ub098\ubb34 \uadf8\ub298\uc5d0\uc11c \uadc0\ub97c \uc6c0\uc9c1\uc774\ub294 \uc544\uc2dc\uc544\ucf54\ub07c\ub9ac\uc758 AI \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ucf54\ub07c\ub9ac\uac00 \uadc0\ub97c \ud754\ub4dc\ub294 \ub370\uc5d0\ub294 \uc774\uc720\uac00 \uc788\ub2e4 \ucee4\ub2e4\ub780 \uadc0\uac00 \ubab8\uc758 \uc5f4\uc744 \uc2dd\ud788\ub294 \ubc29\ubc95 \ub290\uae0b\ud558\uac8c \uadc0\ub97c \ud384\ub7ed\uc774\ub294 \ucf54\ub07c\ub9ac. \uadf8 \uc6c0\uc9c1\uc784\uc5d0\ub294 \ub4e3\ub294 \uc77c \ub9d0\uace0\ub3c4 \ub2e4\ub978 \uc5ed\ud560\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uc0dd\uba85\uacfc \uc778\uccb4 \uacfc\ud559\uacfc \ubc1c\uacac \ucf54\ub07c\ub9ac \uc601\uc0c1\uc744 \ubcf4\ub2e4 \ubcf4\uba74 \uadc0\uac00 \uc790\uafb8 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc55e\uc73c\ub85c \ud55c \ubc88, \ub4a4\ub85c \ud55c \ubc88. \ubab8\uc740 \uac00\ub9cc\ud788 \uc788\ub294\ub370 \uadc0\ub9cc \ub290\uae0b\ud558\uac8c \uc6c0\uc9c1\uc778\ub2e4. \ucee4\ub2e4\ub780 \ubd80\ucc44 \ub450 \uac1c\ub97c \ub4e4\uace0 \uc788\ub294 \uac83 \uac19\ub2e4. \uc2e4\uc81c\ub85c \uadf8 \uadc0\ub294 \uc18c\ub9ac\ub97c \ub4e3\ub294 \uc77c \uc678\uc5d0 \ubab8\uc744 \uc2dd\ud788\ub294 \ub370\uc5d0\ub3c4 \uc4f0\uc778\ub2e4. \uc2a4\ubbf8\uc2a4\uc18c\ub2c8\uc5b8 \uad6d\ub9bd\ub3d9\ubb3c\uc6d0\uc758 \uc544\uc2dc\uc544\ucf54\ub07c\ub9ac \uc548\ub0b4\ub97c \uc77d\uc73c\uba74, \ud384\ub7ed\uc774\ub294 \uadc0 \uc548\ucabd\uc5d0 \uaf64 \ubc14\uc05c \uae38\uc774 \uc788\ub2e4\ub294 \uac83\uc744 \uc54c\uac8c \ub41c\ub2e4. \ud608\uad00\uc774\ub2e4. \uc544\uc2dc\uc544\ucf54\ub07c\ub9ac\uc758 \uadc0\uc5d0\ub294 \ub9ce\uc740 \ud608\uad00\uc774 \uc788\ub2e4. \ub354\uc6b4 \ub0a0 \uadc0\ub97c \uc6c0\uc9c1\uc774\uba74 \uadf8 \uc548\uc744 \ud750\ub974\ub294 \ud53c\uac00 \uc2dd\uace0, \uc2dd\uc740 \ud53c\uac00 \ub2e4\uc2dc \ubab8\uc744 \ub3cc\uba74\uc11c \uccb4\uc628\uc744 \ub0ae\ucd94\ub294 \ub370 \ub3c4\uc6c0\uc744 \uc900\ub2e4\uace0 \ub3d9\ubb3c\uc6d0\uc740 \uc124\uba85\ud55c\ub2e4. \uc6b0\ub9ac\uac00 \ubd80\ucc44\ub97c \ud754\ub4e4 \ub54c\ub294 \uc190\uc774 \ubc14\uc058\uc9c0\ub9cc, \ucf54\ub07c\ub9ac\ub294 \uadc0 \uc790\uccb4\ub97c \uc6c0\uc9c1\uc778\ub2e4. \ub530\ub73b\ud55c \ud53c\uac00 \uc9c0\ub098\ub294 \ub113\uc740 \uc790\ub9ac\ub97c \ubc14\ub78c\uc5d0 \ub0b4\uc5b4\ub193\ub294 \uc148\uc774\ub2e4. \uadf8\ub798\uc11c \uadc0\uc758 \uc6c0\uc9c1\uc784\uc744 \ubcf4\uace0 \uace7\ubc14\ub85c \uae30\ubd84\uc774\ub098 \uc131\uaca9\ub9cc \uc9d0\uc791\ud560 \uc77c\uc740 \uc544\ub2c8\ub2e4. \uadc0\ub294 \uac89\uc73c\ub85c \ubcf4\uc774\ub294 \ud06c\uae30\ub9cc\ud07c\uc774\ub098 \uc548\ucabd\uc758 \uad6c\uc870\ub3c4 \uc911\uc694\ud558\ub2e4. \ub113\uc801\ud55c \ubaa8\uc591\uacfc \ud608\uad00, \ud384\ub7ed\uc774\ub294 \ub3d9\uc791\uc774 \ud568\uaed8 \ubab8\uc758 \uc5f4\uc744 \ub2e4\ub8e8\ub294 \ub370 \uc4f0\uc778\ub2e4. \ucf54\ub07c\ub9ac\uc758 \ud53c\ubd80\ub294 \uc5b4\ub514\ub098 \ub611\uac19\uc774 \ub450\uaecd\uc9c0 \uc54a\ub2e4. \ub3d9\ubb3c\uc6d0\uc740 \ub4f1\ucc98\ub7fc \ub450\uaebc\uc6b4 \uacf3\uc774 \uc788\ub294 \ubc18\uba74, \uadc0 \uc548\ucabd\ucc98\ub7fc \uc544\uc8fc \uc587\uc740 \uacf3\ub3c4 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uba40\ub9ac\uc11c \ubcf8 \ucee4\ub2e4\ub780 \ubab8\uc5d0\ub3c4 \uc12c\uc138\ud55c \ubd80\ubd84\uc774 \uc11e\uc5ec \uc788\ub2e4. \ud53c\ubd80\ub294 \uc2e0\uacbd\uc774 \ud48d\ubd80\ud574 \ubbfc\uac10\ud558\ub2e4. \ucf54\ub07c\ub9ac\uac00 \ud759\uc774\ub098 \ubaa8\ub798, \uc9c4\ud759\uc744 \ubab8\uc5d0 \ub36e\ub294 \ud589\ub3d9\ub3c4 \ud587\ube5b\uacfc \ubc8c\ub808\ub85c\ubd80\ud130 \ud53c\ubd80\ub97c \ubcf4\ud638\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uadc0\ub97c \uc6c0\uc9c1\uc774\uace0 \ubab8\uc5d0 \ud759\uc744 \ubb3b\ud788\ub294 \ubaa8\uc2b5\uc740, \ub354\uc6b4 \ub0a0\uc758 \uc0dd\ud65c\uc744 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ubcf4\uc5ec\uc900\ub2e4. \ub3d9\ubb3c\uc6d0 \uc548\ub0b4\uc5d0\ub294 \uc544\uc2dc\uc544\ucf54\ub07c\ub9ac\uac00 \ud558\ub8e8 \uc911 \uac00\uc7a5 \ub354\uc6b4 \uc2dc\uac04\uc5d0 \uc26c\uac70\ub098 \ub0ae\uc7a0\uc744 \uc790\ub294 \uacbd\ud5a5\ub3c4 \ub098\uc628\ub2e4. \uadf8\ub298\uc5d0\uc11c \uc26c\ub294 \ubab8, \uc6c0\uc9c1\uc774\ub294 \uadc0, \ud53c\ubd80\uc5d0 \uc5b9\ud78c \ud759\uc774 \ud55c \uc7a5\uba74 \uc548\uc5d0 \ub193\uc778\ub2e4. \uadc0\uac00 \ubab8\uc758 \uc5f4\uc744 \ub2e4\ub8e8\ub294 \ub370 \uc4f0\uc778\ub2e4\ub294 \uc124\uba85\uc5d0\ub294 \ub113\uc740 \ud45c\uba74\uacfc \ud608\uad00\uc774 \ud568\uaed8 \ub4f1\uc7a5\ud55c\ub2e4. \uadc0\ub97c \uc6c0\uc9c1\uc774\ub294 \ud589\ub3d9\ub9cc \ub530\ub85c \ubcf4\ub294 \uac83\ubcf4\ub2e4 \uadf8 \uc548\ucabd\uc758 \ud750\ub984\uc744 \uc0dd\uac01\ud558\uba74 \uad6c\uc870\uac00 \ub354 \uad6c\uccb4\uc801\uc774\ub2e4. \ub530\ub73b\ud55c \ud53c\uac00 \uc9c0\ub098\uac00\ub294 \uc790\ub9ac\uac00 \uc8fc\ubcc0\uc758 \uacf5\uae30\uc640 \uad00\uacc4\ub97c \ub9fa\uace0, \uadf8 \ud53c\uac00 \ub2e4\uc2dc \ubab8\uc744 \ub3c4\ub294 \uacfc\uc815\uc774 \uc788\ub2e4. \ubab8\uc758 \uc77c\ubd80\uac00 \ub2e4\ub978 \uacf3\uc758 \uc0c1\ud0dc\uc640 \uc5f0\uacb0\ub418\ub294 \uac83\uc774\ub2e4. \ubd80\ucc44\ub77c\ub294 \ube44\uc720\ub294 \uc774 \uc6c0\uc9c1\uc784\uc744 \uc774\ud574\ud558\uac8c \ub3d5\uc9c0\ub9cc \uc0ac\ub78c\uc758 \uc190\ubd80\ucc44\uc640 \uc644\uc804\ud788 \uac19\uc740 \uc7a5\uce58\ub294 \uc544\ub2c8\ub2e4. \uadc0 \uc790\uccb4\uc5d0 \ud608\uad00\uc774 \uc788\uace0 \ud53c\ubd80\uc640 \ubab8\uc758 \uad6c\uc870\uac00 \ud568\uaed8 \uc791\uc6a9\ud55c\ub2e4. \uc775\uc219\ud55c \ub3c4\uad6c\uc640 \ub2ee\uc558\ub2e4\ub294 \uc785\uad6c\uc5d0\uc11c \ucd9c\ubc1c\ud574 \ub3d9\ubb3c\uc758 \uc2e4\uc81c \ubab8\uc744 \ub530\ub85c \uc77d\uc5b4\uc57c \ud55c\ub2e4. \uc7ac\ubbf8\uc788\ub294 \ubcc4\uba85\uc774 \ud574\ubd80\uc640 \ud589\ub3d9\uc758 \uc124\uba85\uc744 \ub300\uc2e0\ud558\uc9c0 \uc54a\ub3c4\ub85d \ud558\ub294 \uac83\uc774\ub2e4. \ud070 \ub3d9\ubb3c\uc758 \uc6c0\uc9c1\uc784\uc744 \ubcf4\uba74 \uc6b0\ub9ac\ub294 \ud654\uac00 \ub0ac\ub294\uc9c0 \uc990\uac70\uc6b4\uc9c0\ubd80\ud130 \uc9d0\uc791\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uadc0\uc758 \uc6c0\uc9c1\uc784\uc5d0\ub294 \uccb4\uc628 \uc870\uc808\uacfc \uad00\ub828\ub41c \uae30\ub2a5\ub3c4 \uc788\ub2e4. \ud558\ub098\uc758 \ud589\ub3d9\uc5d0 \ud55c \uac00\uc9c0 \uac10\uc815\ub9cc \ubd99\uc774\uba74 \uc2e4\uc81c \ubab8\uc758 \ud544\uc694\ub97c \ub193\uce60 \uc218 \uc788\ub2e4. \ub3d9\ubb3c\uc6d0 \uc548\ub0b4\ub294 \uadf8\ub7f0 \uc775\uc219\ud55c \ud574\uc11d \ubc16\uc758 \uc124\uba85\uc744 \uc54c\ub824 \uc900\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \uadc0 \uc6c0\uc9c1\uc784\uc774 \uc5b8\uc81c\ub098 \uc5f4\uc744 \uc2dd\ud788\ub294 \ubaa9\uc801 \ud558\ub098\ub77c\uace0 \uc815\ud560 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \uac1c\ubcc4 \uc7a5\uba74\uc744 \uc774\ud574\ud558\ub824\uba74 \uc0c1\ud669\uacfc \ub2e4\ub978 \ud589\ub3d9\uc744 \ud568\uaed8 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc548\ub0b4\uac00 \uc124\uba85\ud55c \uc544\uc2dc\uc544\ucf54\ub07c\ub9ac\uc758 \ubab8\uacfc \uae30\ub2a5\uc744 \ubc30\uc6b4\ub2e4. \uba40\ub9ac\uc11c \ubcf8 \ud45c\uc815\ucc98\ub7fc \ubcf4\uc774\ub294 \uc6c0\uc9c1\uc784\uc744 \ubab8\uc758 \uad6c\uc870\uc640 \uc5f0\uacb0\ud574 \ubcf4\ub294 \uad00\uc810\uc774\ub2e4. \ucf54\ub07c\ub9ac\uac00 \ubab8\uc5d0 \ud759\uc774\ub098 \uc9c4\ud759\uc744 \ub36e\uc73c\uba74 \uc778\uac04\uc758 \uae68\ub057\ud568 \uae30\uc900\uc73c\ub85c\ub294 \uc9c0\uc800\ubd84\ud574 \ubcf4\uc77c \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc790\ub8cc\ub294 \ud587\ube5b\uacfc \ubc8c\ub808\ub85c\ubd80\ud130 \ud53c\ubd80\ub97c \ubcf4\ud638\ud558\ub294 \uc5ed\ud560\uc744 \uc124\uba85\ud55c\ub2e4. \ubcf4\uc774\ub294 \uc0c1\ud0dc\uc640 \uc2e4\uc81c \uae30\ub2a5\uc744 \ub098\ub204\uc5b4 \uc0dd\uac01\ud560 \ud544\uc694\uac00 \uc788\ub2e4. \ub3d9\ubb3c\uc758 \ud589\ub3d9\uc744 \uc0ac\ub78c\uc758 \uc0dd\ud65c \uc2b5\uad00\uc73c\ub85c\ub9cc \ud3c9\uac00\ud558\uc9c0 \uc54a\uc744 \uc774\uc720\ub2e4. \ubbfc\uac10\ud55c \ud53c\ubd80\ub77c\ub294 \uc124\uba85\ub3c4 \ud070 \ubab8\uc758 \uccab\uc778\uc0c1\uacfc \ub2e4\ub974\ub2e4. \ub450\uaebc\uc6b4 \uacf3\uc774 \uc788\uc5b4\ub3c4 \uc804\ubd80 \uac19\uc740 \ub450\uaed8\uac00 \uc544\ub2c8\uace0 \uac10\uac01\uc744 \uac00\uc9c4 \ubab8\uc774\ub2e4. \ud06c\uace0 \ud2bc\ud2bc\ud574 \ubcf4\uc778\ub2e4\ub294 \ub9d0\uc774 \ubd88\ud3b8\uacfc \uc790\uadf9\uc744 \ub290\ub07c\uc9c0 \uc54a\ub294\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uadc0\uc758 \uc587\uc740 \ubd80\uc704\uc640 \ud53c\ubd80\ub97c \ub36e\ub294 \ud589\ub3d9\uc744 \ud568\uaed8 \ubcf4\uba74 \ucf54\ub07c\ub9ac\uc758 \ud558\ub8e8\uac00 \uc870\uae08 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \ub290\uaef4\uc9c4\ub2e4. \ud558\ub8e8 \uc911 \ub354\uc6b4 \uc2dc\uac04\uc5d0 \uc26c\ub294 \uacbd\ud5a5\uc740 \uadc0\uc640 \ud53c\ubd80\uc758 \uad6c\uc870 \uc606\uc5d0 \ud589\ub3d9\uc758 \uc870\uc808\uc744 \ub354\ud55c\ub2e4. \ub3d9\ubb3c\uc740 \ubab8\uc758 \ud55c \ubd80\ubd84\ub9cc\uc73c\ub85c \ud658\uacbd\uc744 \uacac\ub514\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc6c0\uc9c1\uc784\uacfc \ud734\uc2dd, \uadf8\ub298\uacfc \ud53c\ubd80\uc758 \uc0c1\ud0dc\uac00 \ud568\uaed8 \uad00\uacc4\ub97c \ub9fa\ub294\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4 \ud55c \uc7a5\uc73c\ub85c \uc2e4\uc81c \uae30\uc628\uacfc \uac1c\uccb4\uc758 \uccb4\uc628\uc744 \uc54c\uc544\ub0bc \uc218\ub294 \uc5c6\ub2e4. \ub2e4\uc74c\uc5d0 \ucf54\ub07c\ub9ac\ub97c \uad00\ucc30\ud560 \uae30\ud68c\uac00 \uc788\ub2e4\uba74 \uadc0\ub9cc \ud655\ub300\ud558\uae30\ubcf4\ub2e4 \ubab8 \uc804\uccb4\uc640 \uc8fc\ubcc0\ub3c4 \uc0b4\ud3b4\ubcf4\uc790. \uadf8\ub298\uc5d0 \uc788\ub294\uc9c0, \ud759\uc774 \ubb3b\uc5b4 \uc788\ub294\uc9c0, \uac00\ub9cc\ud788 \uc26c\ub294\uc9c0 \uac19\uc740 \ub2e4\ub978 \uc815\ubcf4\uac00 \ub4e4\uc5b4\uc628\ub2e4. \ubaa8\ub4e0 \ud589\ub3d9\uc758 \uc774\uc720\ub97c \uadf8 \uc790\ub9ac\uc5d0\uc11c \ud655\uc815\ud560 \ud544\uc694 \uc5c6\uc774\ub3c4 \uc9c8\ubb38\uc740 \ub298\uc5b4\ub09c\ub2e4. \ud070 \uadc0\uc758 \ud384\ub7ed\uc784\uc774 \ub2e8\uc21c\ud55c \ubab8\uc9d3\uc5d0\uc11c \ud658\uacbd\uacfc \ubab8\uc744 \uc787\ub294 \ud589\ub3d9\uc73c\ub85c \ubcf4\uc774\uae30 \uc2dc\uc791\ud55c\ub2e4. \ub3d9\ubb3c\uc740 \ube68\ub9ac \ub2ec\ub9ac\uac70\ub098 \ud06c\uac8c \uc6b8 \ub54c\ub9cc \ubcfc\uac70\ub9ac\ub97c \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc870\uc6a9\ud788 \uc11c \uc788\uc744 \ub54c\ub3c4 \ubab8\uc758 \uc791\uc740 \ubd80\ubd84\uc740 \uc77c\uc744 \ud558\uace0 \uc788\ub2e4. \uadc0\ub97c \ud55c\ubc88 \uc6c0\uc9c1\uc774\ub294 \ub370\uc5d0\ub3c4 \uc0dd\ud65c\uc758 \uc774\uc720\uac00 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \ucf54\ub07c\ub9ac\ub97c \ub9cc\ub098\uba74 \uae34 \ucf54\ub97c \ubcf8 \ub4a4 \uadc0\uc5d0\ub3c4 \uc7a0\uae50 \ub208\uc744 \uc8fc\uc5b4 \ubcf4\uc790. \uc774 \uc774\uc57c\uae30\uac00 \ub2e4\ub8ec \uac83\uc740 \uc544\uc2dc\uc544\ucf54\ub07c\ub9ac\ub2e4. \uadc0\uc758 \ubaa8\uc591\uacfc \ud06c\uae30\ub97c \ub2e4\ub978 \ucf54\ub07c\ub9ac\uc640 \ube44\uad50\ud574 \ubcf4\ub294 \uac83\ub3c4 \uc7ac\ubbf8\uc788\uaca0\uc9c0\ub9cc, \uc6b0\uc120\uc740 \ud55c \ubc88\uc758 \ud384\ub7ed\uc784\uc744 \ucc9c\ucc9c\ud788 \ubcf4\ub294 \uac83\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4. \ub290\uae0b\ud55c \uc624\ud6c4\ucc98\ub7fc \ubcf4\uc774\ub358 \uc7a5\uba74 \uc548\uc5d0\uc11c, \ucee4\ub2e4\ub780 \ubab8\uc740 \uc790\uae30 \ubc29\uc2dd\uc73c\ub85c \ub354\uc704\ub97c \uacac\ub514\uace0 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4."}, {"id": "eratosthenes-shadow-earth-circumference", "title": "\uadf8\ub9bc\uc790\ub85c \uc9c0\uad6c\ub97c \uc7b0 \uc0ac\ub78c \u2014 \uc5d0\ub77c\ud1a0\uc2a4\ud14c\ub124\uc2a4\uc758 \uacc4\uc0b0", "summary": "\uadf8\ub9bc\uc790\uc640 \uac70\ub9ac\ub85c \uc9c0\uad6c \ub458\ub808\ub97c \uacc4\uc0b0\ud55c \uc6d0\ub9ac, \uadf8\ub9ac\uace0 \uace0\ub300 \uc218\uce58\uc758 \ubd88\ud655\uc2e4\uc131\uc744 \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uc218\ud559\uacfc \uce21\uc815", "categories": ["science"], "url": "stories/eratosthenes-shadow-earth-circumference/index.html", "image": "../media/eratosthenes-shadow-earth-circumference.png", "alt": "\uace0\ub300 \uc54c\ub809\uc0b0\ub4dc\ub9ac\uc544\ub97c \ub5a0\uc62c\ub9b0 \uacf5\uac04\uc5d0\uc11c \uae30\ub465\uc758 \uc9e7\uc740 \uadf8\ub9bc\uc790\ub97c \uc0b4\ud53c\ub294 \ud559\uc790\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uadf8\ub9bc\uc790\ub85c \uc9c0\uad6c\ub97c \uc7b0 \uc0ac\ub78c \u2014 \uc5d0\ub77c\ud1a0\uc2a4\ud14c\ub124\uc2a4\uc758 \uacc4\uc0b0 \ub450 \ub3c4\uc2dc\uc758 \ud55c\ub0ae\uc5d0\uc11c \uac70\ub300\ud55c \uc6d0\uc758 \uae38\uc774\ub97c \uc0dd\uac01\ud558\ub2e4 \uadf8\ub9bc\uc790\uc640 \uac70\ub9ac\ub85c \uc9c0\uad6c \ub458\ub808\ub97c \uacc4\uc0b0\ud55c \uc6d0\ub9ac, \uadf8\ub9ac\uace0 \uace0\ub300 \uc218\uce58\uc758 \ubd88\ud655\uc2e4\uc131\uc744 \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4. \uc218\ud559\uacfc \uce21\uc815 \uacfc\ud559\uacfc \ubc1c\uacac \uc9c0\uad6c\uc758 \ud06c\uae30\ub97c \uc7ac\ub824\uba74 \uc9c0\uad6c\ub97c \ud55c \ubc14\ud034 \uac78\uc5b4\uc57c \ud560\uae4c. \uc5d0\ub77c\ud1a0\uc2a4\ud14c\ub124\uc2a4\uac00 \ub5a0\uc62c\ub9b0 \ubc29\ubc95\uc740 \ub2ec\ub790\ub2e4. \uc9c0\uad6c \uc804\uccb4 \ub300\uc2e0 \ub450 \ub3c4\uc2dc\uc758 \ud55c\ub0ae\uc744 \ube44\uad50\ud588\ub2e4. \ud55c\ucabd\uc5d0\ub294 \uadf8\ub9bc\uc790\uac00 \uac70\uc758 \uc5c6\uace0 \ub2e4\ub978 \ucabd\uc5d0\ub294 \uadf8\ub9bc\uc790\uac00 \uc0dd\uae34\ub2e4\uba74, \uadf8 \ucc28\uc774\uac00 \uac70\ub300\ud55c \uacf5\uc758 \ud06c\uae30\ub97c \uc54c\ub824 \uc904 \uc218 \uc788\ub2e4\ub294 \uc0dd\uac01\uc774\uc5c8\ub2e4. \uc624\ud508\uc2a4\ud0dd\uc2a4\uc758 \ucc9c\ubb38\ud559 \uad50\uc7ac\uac00 \uc124\uba85\ud558\ub294 \uc774 \uc77c\ud654\ub294 \uc624\ub798\ub41c \uacfc\ud559 \uc774\uc57c\uae30 \uac00\uc6b4\ub370\uc11c\ub3c4 \uc774\ud574\ud558\uae30 \uc88b\uc740 \ud3b8\uc774\ub2e4. \ud544\uc694\ud55c \uacc4\uc0b0\uc740 \uc9e7\ub2e4. \ud558\uc9c0\ub9cc \uacc4\uc0b0\uc5d0 \ub4e4\uc5b4\uac00\uae30 \uc804\uc5d0 \ubb34\uc5c7\uc744 \ube44\uad50\ud574\uc57c \ud558\ub294\uc9c0 \uc54c\uc544\ucc28\ub9ac\ub294 \uacfc\uc815\uc740 \uacb0\ucf54 \uc791\uc9c0 \uc54a\ub2e4. \uc5d0\ub77c\ud1a0\uc2a4\ud14c\ub124\uc2a4\ub294 \uae30\uc6d0\uc804 3\uc138\uae30 \uc54c\ub809\uc0b0\ub4dc\ub9ac\uc544\uc5d0\uc11c \ud65c\ub3d9\ud55c \ud559\uc790\ub2e4. \uadf8\ub97c \ucc98\uc74c\uc73c\ub85c \uc9c0\uad6c\uac00 \ub465\uae00\ub2e4\uace0 \uc54c\uc544\ub0b8 \uc0ac\ub78c\uc774\ub77c\uace0 \uc18c\uac1c\ud558\uba74 \uc774\uc57c\uae30\uac00 \uc798\ubabb \uc2dc\uc791\ub41c\ub2e4. \uadf8\ub9ac\uc2a4\uc758 \ud559\uc790\ub4e4\uc740 \uc774\ubbf8 \uad6c\ud615 \uc9c0\uad6c\ub97c \ub17c\uc758\ud558\uace0 \uc788\uc5c8\ub2e4. \uadf8\uac00 \ub3c4\uc804\ud55c \uac83\uc740 \ubaa8\uc591\uc758 \ubc1c\uacac\uc774 \uc544\ub2c8\ub77c \ud06c\uae30\uc758 \ucd94\uc815\uc774\uc5c8\ub2e4. \uc5b4\ub5a4 \ub300\uc0c1\uc774 \ub465\uae00\ub2e4\ub294 \uac83\uacfc \uadf8 \ub458\ub808\uac00 \uc5bc\ub9c8\ub77c\ub294 \uac83\uc740 \ub2e4\ub978 \uc9c8\ubb38\uc774\ub2e4. \uacf5\uc744 \ub208\uc55e\uc5d0 \ub4e4\uace0 \uc788\uc73c\uba74 \uc904\uc790\ub97c \ub450\ub974\uba74 \ub418\uc9c0\ub9cc, \uc9c0\uad6c \uc704\uc5d0 \uc11c \uc788\ub294 \uc0ac\ub78c\uc740 \uc9c0\uad6c \uc804\uccb4\ub97c \uc190\uc5d0 \uc958 \uc218 \uc5c6\ub2e4. \uc5d0\ub77c\ud1a0\uc2a4\ud14c\ub124\uc2a4\ub294 \uc811\uadfc\ud560 \uc218 \uc788\ub294 \uc791\uc740 \uc7a5\uba74\uc5d0\uc11c \uc811\uadfc\ud558\uae30 \uc5b4\ub824\uc6b4 \uc804\uccb4\ub97c \uacc4\uc0b0\ud558\ub824 \ud588\ub2e4. \uadf8\ub294 \uc2dc\uc5d0\ub124, \uc624\ub298\uc758 \uc544\uc2a4\uc644 \ubd80\uadfc\uc5d0\uc11c \uc5ec\ub984\uc758 \ud2b9\uc815\ud55c \ud55c\ub0ae\uc5d0 \ud587\ube5b\uc774 \uae4a\uc740 \uc6b0\ubb3c \ubc14\ub2e5\uae4c\uc9c0 \ub2ff\ub294\ub2e4\ub294 \uc18c\uc2dd\uc744 \uc811\ud588\ub2e4\uace0 \uc804\ud574\uc9c4\ub2e4. \ud574\uac00 \uac70\uc758 \uba38\ub9ac \uc704\uc5d0 \uc788\uc73c\uba74 \uc218\uc9c1\uc73c\ub85c \uc120 \ubb3c\uccb4 \uc606\uc5d0 \uadf8\ub9bc\uc790\uac00 \uac70\uc758 \uc0dd\uae30\uc9c0 \uc54a\ub294\ub2e4. \uc6b0\ubb3c\uc740 \ub545\uc18d\uc5d0 \uc228\uc740 \uacf5\uac04\uc774\uba74\uc11c \ud0dc\uc591\uc758 \ubc29\ud5a5\uc744 \uc54c\ub824 \uc8fc\ub294 \ub2e8\uc11c\uac00 \ub41c\ub2e4. \uac19\uc740 \ub54c \uc54c\ub809\uc0b0\ub4dc\ub9ac\uc544\uc5d0\uc11c\ub294 \uc218\uc9c1\uc73c\ub85c \uc138\uc6b4 \ubb3c\uccb4\uc5d0 \uadf8\ub9bc\uc790\uac00 \uc0dd\uae34\ub2e4. \ub450 \ub3c4\uc2dc \ubaa8\ub450 \uac19\uc740 \ud0dc\uc591 \uc544\ub798 \uc788\ub294\ub370 \uacb0\uacfc\ub294 \ub2e4\ub974\ub2e4. \uc774 \ucc28\uc774\ub97c \ub300\uc218\ub86d\uc9c0 \uc54a\uac8c \uc9c0\ub098\uce58\uc9c0 \uc54a\ub294 \uc21c\uac04 \uacc4\uc0b0\uc758 \uae38\uc774 \uc5f4\ub9b0\ub2e4. \ub2e4\ub9cc \uc624\ub298\uc758 \uad50\uacfc\uc11c \uc124\uba85\uc744 \ub2f9\uc2dc\uc758 \ubaa8\ub4e0 \uc791\uc5c5 \uacfc\uc815\uc744 \ube60\uc9d0\uc5c6\uc774 \uc801\uc740 \ud604\uc7a5 \uc77c\uc9c0\ub85c \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud575\uc2ec\uc5d0\ub294 \ud0dc\uc591\uc774 \ub9e4\uc6b0 \uba40\ub9ac \uc788\uc5b4 \ub450 \ub3c4\uc2dc\uc5d0 \ub4e4\uc5b4\uc624\ub294 \ud587\ube5b\uc744 \uac70\uc758 \ud3c9\ud589\ud558\ub2e4\uace0 \ubcfc \uc218 \uc788\ub2e4\ub294 \uc0dd\uac01\uc774 \uc788\ub2e4. \ube5b\uc774 \ub098\ub780\ud788 \ub4e4\uc5b4\uc624\ub294\ub370 \uac01 \ub3c4\uc2dc\uc758 \uc218\uc9c1 \ubc29\ud5a5\uc774 \ub2e4\ub974\ub2e4\uba74, \uadf8 \ucc28\uc774\ub97c \ub9cc\ub4dc\ub294 \uac83\uc740 \ub545\uc758 \uad7d\uc74c\uc774\ub2e4. \ub465\uadfc \uacf5 \uc704\uc758 \ub450 \uc810\uc5d0\uc11c\ub294 \uc704\ucabd\uc744 \uac00\ub9ac\ud0a4\ub294 \ubc29\ud5a5\ub3c4 \uc870\uae08\uc529 \ub2ec\ub77c\uc9c4\ub2e4. \uacf5 \ud45c\uba74\uc5d0 \uc791\uc740 \ub9c9\ub300 \ub450 \uac1c\ub97c \uc138\uc6b4 \ubaa8\uc2b5\uc744 \uc0c1\uc0c1\ud558\uba74 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ub9c9\ub300\ub294 \uac01\uac01 \uadf8 \uc790\ub9ac\uc5d0\uc11c \ub611\ubc14\ub85c \uc130\uc9c0\ub9cc \uc11c\ub85c \uc644\uc804\ud788 \ub098\ub780\ud558\uc9c0\ub294 \uc54a\ub2e4. \uc54c\ub809\uc0b0\ub4dc\ub9ac\uc544\uc758 \uadf8\ub9bc\uc790\ub294 \uadf8\uacf3\uc758 \uc218\uc9c1\uacfc \ud587\ube5b \uc0ac\uc774\uc758 \uae30\uc6b8\uae30\ub97c \ubcf4\uc5ec \uc900\ub2e4. \uc791\uac8c \ubcf4\uc774\ub294 \uadf8 \uac01\ub3c4\uc5d0 \ub450 \ub3c4\uc2dc \uc0ac\uc774\uc758 \uc9c0\uad6c\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \uc54c\ub809\uc0b0\ub4dc\ub9ac\uc544\uc5d0\uc11c \uc5bb\uc740 \uac01\ub3c4\ub294 \ub300\ub7b5 \ud55c \ubc14\ud034\uc758 50\ubd84\uc758 1\ub85c \uc124\uba85\ub41c\ub2e4. \uc644\uc804\ud55c \uc6d0\uc744 360\ub3c4\ub85c \ub193\uc73c\uba74 \uc57d 7.2\ub3c4\uc5d0 \ud574\ub2f9\ud55c\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uc18c\uc218\uc810 \ud55c \uc790\ub9ac \uc790\uccb4\ubcf4\ub2e4 \uc804\uccb4 \uc6d0\uacfc \ub450 \ub3c4\uc2dc \uc0ac\uc774\uc758 \uad00\uacc4\ub2e4. \ub450 \ub3c4\uc2dc \uc0ac\uc774\uc758 \uae38\uc774\uac00 \uc804\uccb4 \ub458\ub808\uc758 50\ubd84\uc758 1\uc774\ub77c\uace0 \ubcfc \uc218 \uc788\uac8c \ub41c\ub2e4. \uc774\uc81c \ub450 \ub3c4\uc2dc \uc0ac\uc774\uc758 \uac70\ub9ac\ub9cc \uc54c\uba74 \ub41c\ub2e4. \uac70\ub9ac\ub97c 50\ubc30 \ud558\uba74 \uc9c0\uad6c\ub97c \ud55c \ubc14\ud034 \ub3c4\ub294 \uae38\uc774\uac00 \ub098\uc628\ub2e4. \ud070 \ubb38\uc81c\ub97c \uc791\uc740 \ube44\uc728 \ubb38\uc81c\ub85c \ubc14\uafb8\ub294 \uc21c\uac04\uc774\ub2e4. \uadf8\ub9bc\uc790 \ud558\ub098\uc5d0 \uc9c0\uad6c\uac00 \uc9c1\uc811 \ucc0d\ud78c \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc, \uae30\ud558\ud559\uc774 \uadf8 \uadf8\ub9bc\uc790\uc5d0\uc11c \uc804\uccb4\ub85c \uac00\ub294 \ub2e4\ub9ac\ub97c \ub193\ub294\ub2e4. \uc804\ud574\uc9c0\ub294 \uc124\uba85\uc5d0\uc11c \ub450 \ub3c4\uc2dc\uc758 \uac70\ub9ac\ub294 5\ucc9c \uc2a4\ud0c0\ub514\uc628\uc73c\ub85c \uc7a1\ub294\ub2e4. \uc5ec\uae30\uc5d0 50\uc744 \uacf1\ud558\uba74 25\ub9cc \uc2a4\ud0c0\ub514\uc628\uc774\ub2e4. \uacc4\uc0b0\ub9cc \ubcf4\uba74 \ubcf5\uc7a1\ud55c \uae30\uacc4\uac00 \ud544\uc694\ud558\uc9c0 \uc54a\ub2e4. \ub180\ub77c\uc6b4 \uc810\uc740 \uacf1\uc148\uc758 \uc5b4\ub824\uc6c0\uc774 \uc544\ub2c8\ub77c, \uadf8 \uacf1\uc148\uc744 \ud574\ub3c4 \ub41c\ub2e4\ub294 \uad00\uacc4\ub97c \uc138\uc6e0\ub2e4\ub294 \ub370 \uc788\ub2e4. \ubb3c\ub860 \uc2e4\uc81c \uc9c0\ud615\uc740 \uad50\uc2e4\uc758 \uae54\ub054\ud55c \ub3c4\ud615\uacfc \ub2e4\ub974\ub2e4. \ub450 \ub3c4\uc2dc\uc758 \uc704\uce58 \uad00\uacc4, \ud0dc\uc591\uc758 \ubc29\ud5a5, \uac70\ub9ac\uc758 \uce21\uc815\uac12\uc5d0\ub294 \uadfc\uc0ac\uc640 \uc624\ucc28\uac00 \ub4e4\uc5b4\uac04\ub2e4. \ub2e8\uc21c\ud55c \uc124\uba85\uc740 \uc6d0\ub9ac\ub97c \ub4dc\ub7ec\ub0b4\uae30 \uc704\ud574 \uc870\uac74\uc744 \uc815\ub9ac\ud55c \uac83\uc774\ub2e4. \uc61b \uacfc\ud559\uc790\uc758 \uc5c5\uc801\uc744 \uc778\uc815\ud558\ub294 \uc77c\uacfc \ubaa8\ub4e0 \uc870\uac74\uc774 \uc644\ubcbd\ud588\ub2e4\uace0 \ubbff\ub294 \uc77c\uc740 \ud568\uaed8 \uac08 \ud544\uc694\uac00 \uc5c6\ub2e4. \uc5ec\uae30\uc11c \uc790\uc8fc \ub4f1\uc7a5\ud558\ub294 \uc774\uc57c\uae30\uac00 \uc544\uc8fc \uc791\uc740 \uc624\ucc28\ub85c \uc9c0\uad6c\ub97c \uc815\ud655\ud788 \uc7ac\uc5c8\ub2e4\ub294 \ucc2c\uc0ac\ub2e4. \ud558\uc9c0\ub9cc \uc2a4\ud0c0\ub514\uc628\uc774 \uc5b4\ub290 \uae38\uc774 \ub2e8\uc704\ub97c \ub73b\ud588\ub294\uc9c0 \ud655\uc815\ud558\uae30 \uc5b4\ub835\ub2e4\ub294 \ubb38\uc81c\uac00 \uc788\ub2e4. \uad50\uc7ac\ub294 \ub2e8\uc704\uc758 \ud574\uc11d\uc5d0 \ub530\ub77c \ud604\ub300 \uac12\uacfc \ube44\uad50\ud55c \uc624\ucc28\uac00 \uc0c1\ub2f9\ud788 \ub2ec\ub77c\uc9c4\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc22b\uc790 \ud558\ub098\ub97c \uc624\ub298\uc758 \ud0ac\ub85c\ubbf8\ud130\ub85c \ubc14\uafb8\ub294 \ub370\uc5d0\ub3c4 \uc5ed\uc0ac\uc801 \ud310\ub2e8\uc774 \ud544\uc694\ud55c \uac83\uc774\ub2e4. \ud6c4\ub300\uc758 \ub3c5\uc790\uac00 \ub9c8\uc74c\uc5d0 \ub4dc\ub294 \ud658\uc0b0\uac12\ub9cc \uace8\ub77c \ub180\ub77c\uc6b4 \uc815\ud655\uc131\uc744 \uac15\uc870\ud558\uba74 \uace0\ub300 \uacc4\uc0b0\uc758 \uc2e4\uc81c \ud55c\uacc4\uac00 \uc0ac\ub77c\uc9c4\ub2e4. \uc815\ud655\ud55c \uacb0\uacfc\uc600\ub2e4\ub294 \ud655\uc2e0\ubcf4\ub2e4, \ubd88\ud655\uc2e4\ud55c \uc790\ub8cc\ub85c\ub3c4 \uaddc\ubaa8\ub97c \ucd94\uc815\ud560 \uc218 \uc788\uc5c8\ub2e4\ub294 \uc810\uc774 \ub354 \ub2e8\ub2e8\ud55c \uac10\ud0c4\uc758 \uadfc\uac70\ub2e4. \uc774 \uc774\uc57c\uae30\uc758 \uc8fc\uc778\uacf5\uc740 \uc720\uba85\ud55c \ud559\uc790 \ud55c \uc0ac\ub78c\ub9cc\uc774 \uc544\ub2c8\ub2e4. \ud55c \uc7a5\uc18c\uc758 \uc6b0\ubb3c\uc5d0 \uad00\ud55c \uc18c\uc2dd, \ub2e4\ub978 \uc7a5\uc18c\uc758 \uadf8\ub9bc\uc790, \ub450 \ub3c4\uc2dc \uc0ac\uc774 \uac70\ub9ac\ub77c\ub294 \uc11c\ub85c \ub2e4\ub978 \uc815\ubcf4\uac00 \ub9cc\ub09c\ub2e4. \uc790\ub8cc\uac00 \uac01\uac01 \ub530\ub85c \ub193\uc5ec \uc788\uc5c8\ub2e4\uba74 \uc9c0\uad6c\uc758 \ub458\ub808\ub294 \ub098\uc624\uc9c0 \uc54a\uc558\uc744 \uac83\uc774\ub2e4. \uc5f0\uacb0 \ubc29\uc2dd\uc774 \uc0c8\ub85c\uc6b4 \uc9c0\uc2dd\uc744 \ub9cc\ub4e0\ub2e4. \uc5d0\ub77c\ud1a0\uc2a4\ud14c\ub124\uc2a4\uc758 \ubc29\ubc95\uc740 \uc9c0\uae08\ub3c4 \uc9c0\uad6c\ub97c \uc2e4\uc81c\ub85c \uc7ac\uace0 \uc2f6\uac8c \ub9cc\ub4dc\ub294 \ub9e4\ub825\uc774 \uc788\ub2e4. \ub2e4\ub9cc \uc7ac\ud604 \uc2e4\ud5d8\uc5d0\uc11c\ub294 \uc7a5\uc18c\uc640 \uc2dc\uac04, \uc218\uc9c1 \ubc29\ud5a5\uacfc \uac70\ub9ac\uc758 \uc870\uac74\uc744 \ub2e4\uc2dc \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc624\ub298 \ud55c\ub0ae\uc5d0 \uc0dd\uae34 \uc544\ubb34 \uadf8\ub9bc\uc790\ub098 50\ubc30 \ud55c\ub2e4\uace0 \uac19\uc740 \ub2f5\uc774 \ub098\uc624\uc9c0\ub294 \uc54a\ub294\ub2e4. \uacfc\ud559\uc758 \uc7ac\ubbf8\ub294 \uc22b\uc790\ub97c \uc678\uc6b0\ub294 \ub370\ubcf4\ub2e4 \ubb34\uc5c7\uc744 \ub9de\ucd94\uc5b4 \ube44\uad50\ud560\uc9c0 \uc774\ud574\ud558\ub294 \ub370 \uc788\ub2e4. \uadf8\ub294 \uc9c0\uad6c\ub97c \uc791\uc740 \uacf5\ucc98\ub7fc \uc190\uc5d0 \ub123\uc9c0 \ubabb\ud588\ub2e4. \ub300\uc2e0 \uc774\ubbf8 \uc54c\uace0 \uc788\ub358 \ub465\uadfc \ubaa8\uc591\uc744 \uc774\uc6a9\ud574 \uc190\uc774 \ub2ff\uc9c0 \uc54a\ub294 \uae38\uc774\ub97c \uacc4\uc0b0\ud588\ub2e4. \uad00\ucc30\uc758 \ubc94\uc704\ubcf4\ub2e4 \uc9c8\ubb38\uc758 \ubc94\uc704\ub97c \ud06c\uac8c \ub9cc\ub4dc\ub294 \uc77c, \uadf8\ub9ac\uace0 \uadf8 \uac04\uaca9\uc744 \ube44\uc728\ub85c \uba54\uc6b0\ub294 \uc77c\uc774 \uc774 \uc624\ub798\ub41c \uacc4\uc0b0\uc758 \uc911\uc2ec\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \uc9e7\uc544\uc9c4 \ud55c\ub0ae\uc758 \uadf8\ub9bc\uc790\ub97c \ubcf4\uac8c \ub418\uba74 \ub2e8\uc21c\ud788 \ud574\uac00 \ub192\ub2e4\uace0\ub9cc \uc0dd\uac01\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc88b\uaca0\ub2e4. \ub2e4\ub978 \ub3c4\uc2dc\uc5d0\uc11c\ub294 \uc9c0\uae08 \uc5b4\ub5a4 \uadf8\ub9bc\uc790\uac00 \uc0dd\uae38\uae4c. \uac70\uae30\uae4c\uc9c0 \uc5bc\ub9c8\ub098 \uba40\uae4c. \uc9c0\uad6c\uc758 \ud06c\uae30\ub97c \ud5a5\ud55c \ucd9c\ubc1c\uc810\uc740 \uac70\ucc3d\ud55c \uae30\uacc4\uac00 \uc544\ub2c8\ub77c \uc774\ub807\uac8c \uc11c\ub85c \ub2e4\ub978 \uc7a5\uc18c\ub97c \ud55c \uc9c8\ubb38 \uc18d\uc5d0 \ub193\ub294 \ub370 \uc788\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4."}, {"id": "faraday-candle-lecture-and-matter", "title": "\ud328\ub7ec\ub370\uc774 \u2014 \ucd1b\ubd88 \ud558\ub098\ub85c \uc5b4\ub514\uae4c\uc9c0 \uc774\uc57c\uae30\ud560 \uc218 \uc788\uc744\uae4c", "summary": "\ud328\ub7ec\ub370\uc774\uc758 \ucd1b\ubd88 \uac15\uc5f0\uc744 \ub530\ub77c \uc2ec\uc9c0\uc640 \uc5f0\ub8cc, \uae30\uccb4\uc640 \uc0b0\uc18c, \ubb3c\uacfc \uc774\uc0b0\ud654\ud0c4\uc18c\uc758 \uc5f0\uacb0\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\ubb3c\uc9c8\uacfc \uc5d0\ub108\uc9c0", "categories": ["science"], "url": "stories/faraday-candle-lecture-and-matter/index.html", "image": "../media/faraday-candle-lecture-and-matter.png", "alt": "\uccad\uc911\uc744 \ubc30\uacbd\uc73c\ub85c \ucd1b\ubd88\uacfc \uc720\ub9ac \uae30\uad6c\uac00 \ub193\uc778 19\uc138\uae30 \uac15\uc5f0 \ubd84\uc704\uae30\uc758 \uc0bd\ud654", "text": "\ud328\ub7ec\ub370\uc774 \u2014 \ucd1b\ubd88 \ud558\ub098\ub85c \uc5b4\ub514\uae4c\uc9c0 \uc774\uc57c\uae30\ud560 \uc218 \uc788\uc744\uae4c \ub179\ub294 \ucd08\uc640 \uc62c\ub77c\uac00\ub294 \uc5f0\ub8cc, \ubd88\uaf43 \ub4a4\uc5d0 \ub0a8\ub294 \ubb3c\uc9c8\uc744 \ub530\ub77c \ud328\ub7ec\ub370\uc774\uc758 \ucd1b\ubd88 \uac15\uc5f0\uc744 \ub530\ub77c \uc2ec\uc9c0\uc640 \uc5f0\ub8cc, \uae30\uccb4\uc640 \uc0b0\uc18c, \ubb3c\uacfc \uc774\uc0b0\ud654\ud0c4\uc18c\uc758 \uc5f0\uacb0\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ubb3c\uc9c8\uacfc \uc5d0\ub108\uc9c0 \uacfc\ud559\uacfc \ubc1c\uacac \ucc45\uc0c1 \uc704\uc5d0 \ucd1b\ubd88 \ud558\ub098\uac00 \ucf1c\uc838 \uc788\ub2e4. \ubcf4\uae30\uc5d0\ub294 \ub2e8\uc21c\ud558\ub2e4. \uc2ec\uc9c0 \ub05d\uc5d0\uc11c \ubd88\uaf43\uc774 \ud754\ub4e4\ub9ac\uace0 \ucd08\ub294 \uc870\uae08\uc529 \uc9e7\uc544\uc9c4\ub2e4. \ub9c8\uc774\ud074 \ud328\ub7ec\ub370\uc774\ub294 \uc774 \uc775\uc219\ud55c \ubb3c\uac74\uc744 \uac00\uc9c0\uace0 \uc5ec\ub7ec \ucc28\ub840\uc758 \uacfc\ud559 \uac15\uc5f0\uc744 \uc774\uc5b4 \uac14\ub2e4. \u300e\ucd1b\ubd88\uc758 \ud654\ud559\uc801 \uc5ed\uc0ac\u300f\ub294 \uc5b4\ub9b0 \uccad\uc911\uc744 \uc704\ud55c \uac15\uc5f0\uc744 \uc815\ub9ac\ud55c \ucc45\uc774\ub2e4. \uc2dc\uc791\uc740 \uc791\uc740 \ubd88\uaf43\uc774\uc9c0\ub9cc \uc774\uc57c\uae30\ub294 \uacf5\uae30\uc640 \ubb3c, \ubb3c\uc9c8\uc774 \ubc14\ub00c\ub294 \uacfc\uc815\uacfc \uc0dd\uba85\uc758 \ud638\ud761\uae4c\uc9c0 \ub113\uc5b4\uc9c4\ub2e4. \ud2b9\ubcc4\ud55c \ubb3c\uac74\ubcf4\ub2e4 \uc798 \uace0\ub978 \uc9c8\ubb38\uc774 \ub354 \uba40\ub9ac \ub370\ub824\uac00\ub294 \uc0ac\ub840\ub2e4. \uac15\uc5f0\uc5d0\uc11c \ud328\ub7ec\ub370\uc774\ub294 \ucd1b\ubd88\uc5d0 \uc790\uc5f0\uc758 \ubc95\uce59\uacfc \uc5f0\uacb0\ub418\ub294 \ub9ce\uc740 \uc77c\uc774 \ub2f4\uaca8 \uc788\ub2e4\uace0 \ub9d0\ud55c\ub2e4. \uc190\uc5d0 \uc7a1\ud788\ub294 \uc775\uc219\ud55c \ubb3c\uac74\uc774\ub77c \uccad\uc911\uc774 \ubb34\uc5c7\uc744 \ubcf4\uace0 \uc788\ub294\uc9c0 \ud568\uaed8 \uc54c \uc218 \uc788\uc5c8\ub2e4. \uc5b4\ub824\uc6b4 \uc774\ub984\uc744 \uba3c\uc800 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uc2dc\uc791\ud560 \uc218 \uc788\uc5c8\ub2e4. \ubb3c\uac74\uc774 \ub2e8\uc21c\ud558\ub2e4\ub294 \uac83\uacfc \uadf8 \uc548\uc758 \uacfc\uc815\uc774 \ub2e8\uc21c\ud558\ub2e4\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \ucd1b\ubd88\uc5d0\ub294 \uace0\uccb4\uc640 \uc561\uccb4, \uae30\uccb4\uc758 \ubcc0\ud654\uac00 \uc788\uace0 \uc5f0\ub8cc\uc758 \uc774\ub3d9\uacfc \ud654\ud559 \ubc18\uc751\uc774 \uc788\ub2e4. \ud558\ub098\ub97c \uc774\ud574\ud558\uba74 \ubc14\ub85c \uc606\uc5d0 \ub2e4\ub978 \uc9c8\ubb38\uc774 \ub098\ud0c0\ub098\ub3c4\ub85d \uac15\uc5f0\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ubd88\uc744 \ubd99\uc778 \ucd08\uc758 \uc2ec\uc9c0 \uc8fc\ubcc0\uc5d0\ub294 \ub179\uc740 \uc5f0\ub8cc\uac00 \ubaa8\uc778\ub2e4. \uc6d0\ub798 \ub2e8\ub2e8\ud588\ub358 \ubb3c\uc9c8\uc774 \uc5f4\uc744 \ubc1b\uc544 \uc561\uccb4\uac00 \ub41c \uac83\uc774\ub2e4. \ubc14\uae65\ucabd\uc758 \ucd08\uc640 \uc548\ucabd\uc758 \ub179\uc740 \ubd80\ubd84\uc774 \ud568\uaed8 \uc788\uc73c\ub2c8 \uc5f0\ub8cc\uac00 \uc7a0\uc2dc \uba38\ubb34\ub97c \uc790\ub9ac\uac00 \uc0dd\uae34\ub2e4. \ucd08\uac00 \uc904\uc5b4\ub4dc\ub294 \ubaa8\uc2b5\ub9cc \uba40\ub9ac\uc11c \ubcf4\uba74 \uc774\ub7f0 \uc911\uac04 \ub2e8\uacc4\ub294 \uc27d\uac8c \uc9c0\ub098\uce5c\ub2e4. \ud328\ub7ec\ub370\uc774\uc758 \uc2dc\uc120\uc740 \ub05d\uc758 \ubd88\uaf43\uc5d0\uc11c \uc7a0\uae50 \uc544\ub798\ub85c \ub0b4\ub824\uc628\ub2e4. \uc5f0\ub8cc\uac00 \uc5b4\ub514\uc5d0 \uc788\uace0 \uc5b4\ub5a4 \uc0c1\ud0dc\ub85c \uc6c0\uc9c1\uc774\ub294\uc9c0\ubd80\ud130 \ubb3c\uc5b4\uc57c \ub2e4\uc74c \uacfc\uc815\uc744 \uc124\uba85\ud560 \uc218 \uc788\uc5c8\ub2e4. \ub179\uc740 \uc5f0\ub8cc\ub294 \uc2ec\uc9c0\uc758 \uac00\ub290\ub2e4\ub780 \ud2c8\uc744 \ub530\ub77c \uc62c\ub77c\uac04\ub2e4. \uac15\uc5f0\uc740 \ubaa8\uc138\uad00 \uc791\uc6a9\uc744 \uc5ec\ub7ec \uce5c\uc219\ud55c \uc0ac\ub840\uc640 \uc5f0\uacb0\ud574 \uc124\uba85\ud55c\ub2e4. \uc2ec\uc9c0\ub294 \ubd88\uaf43\uc774 \uc549\ub294 \ubc1b\uce68\uc774\uba74\uc11c \uc561\uccb4\ub97c \uc5f0\uc18c\uac00 \uc77c\uc5b4\ub098\ub294 \ucabd\uc73c\ub85c \ubcf4\ub0b4\ub294 \uae38\uc774\uae30\ub3c4 \ud558\ub2e4. \ub530\ub77c\uc11c \uc2ec\uc9c0\ub9cc \ud0c4\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \ucd08\uc758 \uc5f0\ub8cc\uac00 \uc5b4\ub5bb\uac8c \uc4f0\uc774\ub294\uc9c0 \ub193\uce5c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc2ec\uc9c0\uac00 \uc804\ud600 \ud0c0\uc9c0 \uc54a\ub294\ub2e4\ub294 \ub73b\ub3c4 \uc544\ub2c8\ub2e4. \ubcf4\uc774\ub294 \ubb3c\uac74 \uac01\uac01\uc774 \uc5b4\ub5a4 \uc5ed\ud560\uc744 \ud558\ub294\uc9c0 \ub098\ub204\uc5b4 \ubcf4\uc544\uc57c \ucd1b\ubd88\uc758 \uc9c0\uc18d\uc801\uc778 \uc791\ub3d9\uc774 \uc774\ud574\ub41c\ub2e4. \ubd88\uaf43 \uac00\uae4c\uc774 \uc62c\ub77c\uac04 \uc5f0\ub8cc\ub294 \uc5f4\uc744 \ubc1b\uc544 \uae30\uccb4 \uc0c1\ud0dc\uac00 \ub418\uace0 \uacf5\uae30\uc640 \ub9cc\ub098 \ubc18\uc751\ud55c\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \uace0\uccb4\uc5d0\uc11c \uc561\uccb4\ub97c \uac70\uccd0 \uae30\uccb4\ub85c \uc774\uc5b4\uc9c0\ub294 \uae38\uc774\ub2e4. \uc190\uc5d0 \uc7a1\ud788\ub294 \ucd08\uc640 \ub208\uc55e\uc758 \ubd88\uaf43 \uc0ac\uc774\uc5d0\ub294 \uc0c1\ud0dc \ubcc0\ud654\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \uc774 \uc124\uba85\uc740 \ucd08\uac00 \uc2e0\ube44\ud558\uac8c \uc0ac\ub77c\uc9c4\ub2e4\ub294 \uc778\uc0c1\uc744 \ubc14\uafbc\ub2e4. \uc5f0\ub8cc\uac00 \uc790\ub9ac\uc640 \uc0c1\ud0dc\ub97c \ubc14\uafb8\uba70 \ubc18\uc751\ud558\uace0 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4. \ub369\uc5b4\ub9ac\uac00 \uc904\uc5b4\ub4dc\ub294 \ud604\uc0c1\uacfc \ubc18\uc751\ud55c \ubb3c\uc9c8\uc758 \ud589\ubc29\uc744 \ud568\uaed8 \ubb3c\uc744 \uc218 \uc788\uac8c \ub41c\ub2e4. \ud328\ub7ec\ub370\uc774\ub294 \ubd88\uaf43\uc744 \ud558\ub098\uc758 \uade0\uc77c\ud55c \ub369\uc5b4\ub9ac\ucc98\ub7fc \ubcf4\uc9c0 \uc54a\uc558\ub2e4. \ubd80\ubd84\ub9c8\ub2e4 \ubc1d\uae30\uc640 \uc0c1\ud0dc\uac00 \ub2e4\ub974\ub2e4\ub294 \uc810\uc5d0 \uc8fc\ubaa9\ud588\ub2e4. \ucd1b\ubd88\uc758 \ubc1d\uc740 \ub178\ub780 \uc601\uc5ed\uc5d0\uc11c\ub294 \ub728\uac70\uc6cc\uc9c4 \ud0c4\uc18c \uc785\uc790\uac00 \ube5b\uc744 \ub0b4\ub294 \uacfc\uc815\uc774 \uc911\uc694\ud558\ub2e4. \uc774 \uc124\uba85\uc744 \ubaa8\ub4e0 \uc885\ub958\uc758 \ubd88\uaf43 \uc0c9\uc5d0 \ub611\uac19\uc774 \uc801\uc6a9\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc5f0\ub8cc\uc640 \uc870\uac74\uc5d0 \ub530\ub77c \ube5b\uc774 \uc0dd\uae30\ub294 \ubc29\uc2dd\uacfc \uc0c9\uc740 \ub2ec\ub77c\uc9c4\ub2e4. \uc775\uc219\ud55c \ucd1b\ubd88\uc758 \ud55c \ubd80\ubd84\uc744 \uc790\uc138\ud788 \ubcf4\ub294 \uc77c\uc774 \ub354 \ub113\uc740 \ud604\uc0c1\uc744 \ube44\uad50\ud560 \ucd9c\ubc1c\uc810\uc774 \ub418\ub294 \uac83\uc774\ub2e4. \ucd08\uc5d0 \uc5f0\ub8cc\uac00 \uc788\ub2e4\uace0 \ud63c\uc790 \uacc4\uc18d \ud0c8 \uc218\ub294 \uc5c6\ub2e4. \uacf5\uae30 \uc911\uc758 \uc0b0\uc18c\uac00 \ubc18\uc751\uc5d0 \ucc38\uc5ec\ud55c\ub2e4. \uac15\uc5f0\uc5d0\uc11c\ub294 \uae30\uccb4\ub97c \uc0b4\ud53c\uace0 \ube44\uad50\ud558\ub294 \uacfc\uc815\uc744 \ud1b5\ud574 \ub208\uc5d0 \uc7a1\ud788\uc9c0 \uc54a\ub294 \ubb3c\uc9c8\ub3c4 \uad6c\ubcc4\ud560 \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uacf5\uae30\ub294 \ube48 \uacf5\uac04\uc774\ub77c\ub294 \ub290\ub08c\uc774 \ub4e4\uae30 \uc27d\ub2e4. \ud558\uc9c0\ub9cc \ucd1b\ubd88\uc744 \uc774\ud574\ud558\ub824\uba74 \uadf8 \uc548\uc5d0 \ubb34\uc5c7\uc774 \uc788\ub294\uc9c0 \ubb3c\uc5b4\uc57c \ud55c\ub2e4. \uc190\uc5d0 \ub4e0 \ucd08\ub9cc \ubcf4\ub358 \uc774\uc57c\uae30\uac00 \ubc29 \uc548\uc758 \uacf5\uae30\uae4c\uc9c0 \ub113\uc5b4\uc9c4\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc774\uc720\ub85c \uacfc\uc815\uc5d0\uc11c \ube60\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ucd08\uac00 \ud0c0\uba74 \ubb3c\uacfc \uc774\uc0b0\ud654\ud0c4\uc18c \uac19\uc740 \uc0dd\uc131\ubb3c\uc774 \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4. \ud328\ub7ec\ub370\uc774\ub294 \uac15\uc5f0\uc5d0\uc11c \ubb3c\uc758 \uc874\uc7ac\uc640 \ub2f9\uc2dc \ud0c4\uc0b0 \uae30\uccb4\ub77c\uace0 \ubd80\ub974\ub358 \uc774\uc0b0\ud654\ud0c4\uc18c\uc758 \uc131\uc9c8\uc744 \uc0b4\ud3c8\ub2e4. \ubd88\uaf43\uc740 \ube5b\uacfc \uc5f4\uc744 \ub0b4\uba74\uc11c \ubb3c\uc9c8\uc758 \uc0c8\ub85c\uc6b4 \uc870\ud569\ub3c4 \ub9cc\ub4e0\ub2e4. \uc5f0\uae30\uac00 \ubcc4\ub85c \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4\uace0 \uc544\ubb34\uac83\ub3c4 \ub098\uc624\uc9c0 \uc54a\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubd88\uc644\uc804\ud55c \uc5f0\uc18c \ub4f1 \uc870\uac74\uc5d0 \ub530\ub77c \ub2e4\ub978 \ubb3c\uc9c8\ub3c4 \uc0dd\uae38 \uc218 \uc788\ub2e4. \uc774 \uc774\uc57c\uae30\ub294 \ucd1b\ubd88\uc744 \ucf20 \uacf5\uac04\uc758 \uacf5\uae30\uac00 \uc5b8\uc81c\ub098 \uc548\uc804\ud558\ub2e4\ub294 \ubcf4\uc7a5\uc774 \uc544\ub2c8\ub77c \uc5f0\uc18c\uc758 \ubb3c\uc9c8\uc801 \ud589\ubc29\uc744 \uc774\ud574\ud558\ub294 \uc124\uba85\uc774\ub2e4. \uac15\uc5f0\uc740 \ub05d\uc5d0 \uac00\uc11c \uacf5\uae30\uc640 \ud0c4\uc18c\uc758 \uc774\ub3d9\uc744 \uc0ac\ub78c\uacfc \ub3d9\ubb3c, \uc2dd\ubb3c\uc758 \uad00\uacc4\ub85c \ub113\ud78c\ub2e4. \ucd1b\ubd88 \ud558\ub098\ub97c \uad00\ucc30\ud558\ub2e4\uac00 \uc0dd\ud65c\uacfc \uc790\uc5f0\uc758 \uc5f0\uacb0\uc744 \ubb3b\ub294 \uc790\ub9ac\uae4c\uc9c0 \uac04 \uac83\uc774\ub2e4. \ucc98\uc74c\uc758 \uc791\uc740 \ubb3c\uac74\uc774 \uae34 \uc774\uc57c\uae30\uc758 \uc911\uc2ec\uc744 \uacc4\uc18d \uc7a1\uc544 \uc900\ub2e4. \ud638\ud761\uacfc \ucd1b\ubd88\uc774 \uc644\uc804\ud788 \uac19\uc740 \ubc18\uc751 \ubc29\uc2dd\uc774\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc0dd\uba85\uccb4\uc758 \uacfc\uc815\uc5d0\ub294 \ub2e4\ub978 \uc870\uc808\uacfc \ub2e8\uacc4\uac00 \uc788\ub2e4. \ub2e4\ub9cc \ubb3c\uc9c8\uc774 \uc5b4\ub514\uc5d0\uc11c \uc640\uc11c \uc5b4\ub514\ub85c \uac00\ub294\uc9c0\ub77c\ub294 \uc9c8\ubb38\uc740 \uc11c\ub85c \ub2e4\ub978 \ud604\uc0c1\uc744 \uc774\uc5b4 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ud328\ub7ec\ub370\uc774\uc758 \uac15\uc5f0\uc740 \uc775\uc219\ud55c \ub300\uc0c1\uc744 \uace0\ub974\uace0 \ud55c \uac00\uc9c0 \uad00\ucc30\uc5d0\uc11c \ub2e4\uc74c \uc9c8\ubb38\uc744 \uaebc\ub0b8\ub2e4. \uc5b4\ub824\uc6b4 \ub2e8\uc5b4\ub97c \ubaa8\ub450 \uc5c6\uc560\uae30\ubcf4\ub2e4 \ub2e8\uc5b4\uac00 \ud544\uc694\ud55c \uc21c\uac04\uc744 \ub9cc\ub4e4\uc5b4 \uc900\ub2e4. \ubaa8\uc138\uad00\uc774\ub098 \uae30\uccb4\ub77c\ub294 \ub9d0\uc774 \ucd1b\ubd88\uc744 \uc774\ud574\ud558\ub294 \ub370 \uc4f0\uc774\ub294 \ub3c4\uad6c\uac00 \ub41c\ub2e4. \ucc45\uc744 \uc77d\uc73c\uba70 \ud2b9\ubcc4\ud55c \uc2e4\ud5d8\uc744 \ub530\ub77c \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ubd88\uaf43 \uc544\ub798\uc758 \uc561\uccb4\uc640 \uc2ec\uc9c0, \uc8fc\ubcc0\uc758 \uacf5\uae30\ub97c \ucc28\ub840\ub85c \ub5a0\uc62c\ub824\ub3c4 \uc774\uc57c\uae30\uc758 \uc5f0\uacb0\uc774 \ubcf4\uc778\ub2e4. \ud3c9\ubc94\ud55c \ubb3c\uac74\uc744 \uc624\ub798 \ubc14\ub77c\ubcf4\ub294 \uc2dc\uac04\uc774 \uacfc\ud559\uc758 \uae4a\uc774\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uac15\uc5f0\uc774\ub2e4."}, {"id": "flamingo-pink-feathers", "title": "\ud50c\ub77c\ubc0d\uace0\ub294 \ud0dc\uc5b4\ub0a0 \ub54c\ubd80\ud130 \ubd84\ud64d\uc0c9\uc77c\uae4c", "summary": "\ubd84\ud64d\uc0c9 \uc0c8 \ud558\uba74 \ub5a0\uc624\ub974\ub294 \ud50c\ub77c\ubc0d\uace0. \ud558\uc9c0\ub9cc \uadf8 \uc0c9\uc740 \ud0dc\uc5b4\ub0a0 \ub54c\ubd80\ud130 \uc644\uc131\ub41c \uac83\uc774 \uc544\ub2d9\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uc0dd\uba85\uacfc \uc778\uccb4", "categories": ["science"], "url": "stories/flamingo-pink-feathers/index.html", "image": "../media/flamingo-pink-feathers.jpg", "alt": "\ud50c\ub77c\ubc0d\uace0\ub294 \ud0dc\uc5b4\ub0a0 \ub54c\ubd80\ud130 \ubd84\ud64d\uc0c9\uc77c\uae4c \u2014 \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ud50c\ub77c\ubc0d\uace0\ub294 \ud0dc\uc5b4\ub0a0 \ub54c\ubd80\ud130 \ubd84\ud64d\uc0c9\uc77c\uae4c \uc6b0\uc544\ud55c \uae43\ud138\uc5d0 \uc228\uc5b4 \uc788\ub294 \uc2dd\uc0ac\uc758 \ud754\uc801 \ubd84\ud64d\uc0c9 \uc0c8 \ud558\uba74 \ub5a0\uc624\ub974\ub294 \ud50c\ub77c\ubc0d\uace0. \ud558\uc9c0\ub9cc \uadf8 \uc0c9\uc740 \ud0dc\uc5b4\ub0a0 \ub54c\ubd80\ud130 \uc644\uc131\ub41c \uac83\uc774 \uc544\ub2d9\ub2c8\ub2e4. \uc0dd\uba85\uacfc \uc778\uccb4 \uacfc\ud559\uacfc \ubc1c\uacac \ud50c\ub77c\ubc0d\uace0\ub97c \uadf8\ub824 \ubcf4\ub77c\uace0 \ud558\uba74 \ubd84\ud64d\uc0c9\ubd80\ud130 \ucc3e\uac8c \ub41c\ub2e4. \uae34 \ub2e4\ub9ac\uc640 \uad7d\uc740 \ubaa9\ub3c4 \uc911\uc694\ud558\uc9c0\ub9cc, \uc0c9\uc744 \ube7c\ub193\uc73c\uba74 \uc5b4\uca50\uc9c0 \ub2e4\ub978 \uc0c8\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uadf8\ub7f0\ub370 \uc5b4\ub9b0 \ud50c\ub77c\ubc0d\uace0\ub294 \uc6b0\ub9ac\uac00 \ub5a0\uc62c\ub9ac\ub294 \uc120\uba85\ud55c \ubd84\ud64d\uc0c9\uacfc \ub2e4\ub974\ub2e4. \ud68c\uc0c9\ube5b\uc774\ub098 \ud770\ube5b\uc774 \ub3c4\ub294 \uc19c\ud138\ub85c \uc2dc\uc791\ud55c\ub2e4. \ucc98\uc74c\ubd80\ud130 \uc5b4\ub978 \uc0c8\uc640 \ub611\uac19\uc740 \uc0c9\uc758 \uc791\uc740 \ubcf5\uc0ac\ubcf8\uc774 \ud0dc\uc5b4\ub098\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub807\ub2e4\uba74 \uc790\ub77c\uba74\uc11c \ubd84\ud64d\uc0c9\uc740 \uc5b4\ub514\uc5d0\uc11c \uc624\ub294 \uac83\uc77c\uae4c. \ub2f5\uc744 \ucc3e\uc73c\ub824\uba74 \uae43\ud138\ubcf4\ub2e4 \uba3c\uc800 \uba39\uc774\ub97c \ubcf4\uc544\uc57c \ud55c\ub2e4. \ud50c\ub77c\ubc0d\uace0\uac00 \uba39\ub294 \uc870\ub958\ub098 \uc791\uc740 \uac11\uac01\ub958 \ub4f1\uc5d0\ub294 \uce74\ub85c\ud2f0\ub178\uc774\ub4dc\ub77c\ub294 \uc0c9\uc18c\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \uc870\uae08 \ub0af\uc120 \uc774\ub984\uc774\uc9c0\ub9cc \uc790\uc5f0\uc5d0\uc11c \uc5ec\ub7ec \ub178\ub791\u00b7\uc8fc\ud669\u00b7\ubd89\uc740\ube5b\uacfc \uad00\ub828\ub418\ub294 \uc0c9\uc18c \ubb34\ub9ac\ub2e4. \ud50c\ub77c\ubc0d\uace0\ub294 \uba39\uc774\uc5d0\uc11c \uc5bb\uc740 \uc774\ub7f0 \uc131\ubd84\uc744 \ubab8 \uc548\uc5d0\uc11c \ucc98\ub9ac\ud558\uace0, \uadf8 \uacb0\uacfc\uac00 \uae43\ud138\uc758 \uc0c9\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc900\ub2e4. \uba39\uc740 \uac83\uc744 \ub2e8\uc21c\ud788 \uae43\ud138 \ubc14\uae65\uc5d0 \ubb3b\ud788\ub294 \ubc29\uc2dd\uc740 \uc544\ub2c8\ub2e4. \ubab8\uc758 \uacfc\uc815\uc774 \uc788\uc5b4\uc57c \uba39\uc774\uc640 \uc0c8\uc758 \ubaa8\uc2b5\uc774 \uc5f0\uacb0\ub41c\ub2e4. \uadf8\ub798\uc11c \uc0c8\uc6b0\ub97c \uba39\uc5b4\uc11c \ubd84\ud64d\uc0c9\uc774\ub77c\ub294 \uc124\uba85\uc740 \uae30\uc5b5\ud558\uae30 \uc27d\uc9c0\ub9cc \uc870\uae08 \uc9e7\ub2e4. \ubaa8\ub4e0 \ud50c\ub77c\ubc0d\uace0\uac00 \uac19\uc740 \uba39\uc774\ub97c \uac19\uc740 \ube44\uc728\ub85c \uba39\ub294 \uac83\uc740 \uc544\ub2c8\uace0, \uc0c9\uc18c\uc758 \uacbd\ub85c\ub3c4 \ud55c \uac00\uc9c0 \uc74c\uc2dd\uc73c\ub85c\ub9cc \uc124\uba85\ub418\uc9c0 \uc54a\ub294\ub2e4. \ubd84\ud64d\uc0c9 \uae43\ud138\uc744 \uc774\ud574\ud558\ub824\uba74 \ub208\uc5d0 \ubcf4\uc774\ub294 \uc0c8\ub9cc \ubcfc \uac83\uc774 \uc544\ub2c8\ub77c \uadf8 \uc0c8\uac00 \uba39\ub294 \uac83\ub3c4 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc2a4\ubbf8\uc2a4\uc18c\ub2c8\uc5b8 \uad6d\ub9bd\ub3d9\ubb3c\uc6d0\uc740 \uba39\uc774\uc758 \uc0c9\uc18c\ub97c \ubab8 \uc548\uc5d0\uc11c \ucc98\ub9ac\ud558\ub294 \uacfc\uc815\uc774 \uae43\ud138\uc758 \ubd84\ud64d\ube5b\uc73c\ub85c \uc774\uc5b4\uc9c4\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud50c\ub77c\ubc0d\uace0 \uc0ac\uc9c4\uc744 \uc5ec\ub7ec \uc7a5 \ub193\uace0 \ubcf4\uba74 \uc0c9\uc774 \ubaa8\ub450 \uac19\uc9c0 \uc54a\ub2e4. \uc5f0\ud55c \ubd84\ud64d\ube5b\uc744 \ub760\ub294 \uc0c8\ub3c4 \uc788\uace0, \ub354 \uc120\uba85\ud55c \ubd89\uc740\ube5b\uc5d0 \uac00\uae4c\uc6b4 \uc0c8\ub3c4 \uc788\ub2e4. \uc885\uacfc \ub098\uc774, \uba39\uc774\uc640 \uae43\ud138\uc758 \uc0c1\ud0dc \uac19\uc740 \uc5ec\ub7ec \uc870\uac74\uc774 \uad00\ub828\ub41c\ub2e4. \uadf8\ub7ec\ubbc0\ub85c \uc0c9\uc774 \uc605\uc740 \uc0c8 \ud55c \ub9c8\ub9ac\ub97c \ubcf4\uace0 \ubc14\ub85c \ubc30\uac00 \uace0\ud504\ub2e4\uac70\ub098 \uac74\uac15\uc5d0 \ubb38\uc81c\uac00 \uc788\ub2e4\uace0 \ud310\ub2e8\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc0ac\uc9c4\uc758 \ube5b\uacfc \ucd2c\uc601 \uc870\uac74\ub3c4 \uc2e4\uc81c\ub85c \ubcf4\uc774\ub294 \uc0c9\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4. \uc0c9\uae54 \ud558\ub098\ub85c \uc0c8\uc758 \uc0c1\ud0dc\ub97c \ubaa8\ub450 \uc77d\uc744 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub9b0 \uc0c8\uac00 \uc790\ub77c\uba74\uc11c \uc5b4\ub978\uc758 \uc0c9\uc744 \uac16\ucd94\ub294 \ub370\uc5d0\ub3c4 \uc2dc\uac04\uc774 \ud544\uc694\ud558\ub2e4. \uba39\uc774 \ud55c \ub07c\ub97c \uba39\uace0 \ubc14\ub85c \uc628\ubab8\uc774 \ubb3c\ub4dc\ub294 \ub9cc\ud654 \uac19\uc740 \ubcc0\ud654\ub294 \uc544\ub2c8\ub2e4. \uc6b0\ub9ac\uac00 \ubcf4\ub294 \uae43\ud138\uc5d0\ub294 \uadf8 \uc0c8\uac00 \uc0b4\uc544\uc628 \uc2dc\uac04\uc774 \uc870\uae08\uc529 \ubc18\uc601\ub418\uc5b4 \uc788\ub2e4. \uc774\ub807\uac8c \uc0dd\uac01\ud558\uba74 \ubd84\ud64d\uc0c9\uc740 \uc7a5\uc2dd \uc774\uc0c1\uc758 \uac83\uc774 \ub41c\ub2e4. \uc0dd\uae40\uc0c8\ub97c \uc54c\uc544\ubcf4\uac8c \ud558\ub294 \ud2b9\uc9d5\uc774\uba74\uc11c, \uc0c8\uac00 \uc0ac\ub294 \ud658\uacbd\uacfc \uba39\ub294 \uac83\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \ub2e8\uc11c\uc774\uae30\ub3c4 \ud558\ub2e4. \uc0c9\uc18c\uac00 \ub4e0 \uba39\uc774\ub97c \uba39\ub294\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ubb3c\uac10\uc744 \uae43\ud138\uc5d0 \uce60\ud55c\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uc12d\ucde8\ud55c \uc131\ubd84\uc744 \ubab8\uc5d0\uc11c \ub2e4\ub8e8\uace0 \uae43\ud138\uc774 \uc790\ub77c\ub294 \uacfc\uc815\uacfc \uc774\uc5b4\uc838\uc57c \ud55c\ub2e4. \uadf8\ub798\uc11c \ubd84\ud64d\ube5b\uc744 \ub2e8\uc21c\ud788 \ubb3c\uc5d0 \ube44\uce5c \uc0c9\uc774\ub098 \uae43\ud138 \ubc14\uae65\uc5d0 \ubb3b\uc740 \uc5bc\ub8e9\uc73c\ub85c \uc124\uba85\ud558\uc9c0 \uc54a\ub294\ub2e4. \ubcf4\uc774\ub294 \uc0c9\uc740 \uc0dd\ubb3c\uc774 \uc0b4\uc544\uac00\ub294 \uacfc\uc815\uacfc \uad00\uacc4\uac00 \uc788\ub2e4. \uc774 \uc5f0\uacb0\uc744 \uc54c\uba74 \uba39\uc774 \ud55c \uc885\ub958\ub9cc \uc678\uc6b0\ub294 \uc124\uba85\uc5d0\uc11c \uc870\uae08 \ubc97\uc5b4\ub0a0 \uc218 \uc788\ub2e4. \uc870\ub958\uc640 \uc791\uc740 \uac11\uac01\ub958 \ub4f1 \uc5ec\ub7ec \uba39\uc774\uac00 \uc788\uace0 \uc885\uacfc \ud658\uacbd\uc758 \ucc28\uc774\ub3c4 \uc788\ub2e4. \uc790\ub8cc\uc758 \ud070 \uc6d0\ub9ac\ub97c \uc774\ud574\ud558\ub294 \uac83\uacfc \ud2b9\uc815\ud55c \uc0c8\uac00 \uc2e4\uc81c\ub85c \ubb34\uc5c7\uc744 \uc5bc\ub9c8\ub098 \uba39\uc5c8\ub294\uc9c0 \uc544\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uc0ac\uc9c4\uc758 \uc0c9\ub9cc\uc73c\ub85c \uc2dd\ub2e8\uc744 \uc815\ud655\ud788 \uc5ed\uc0b0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud770\uc0c9\uc774\ub098 \ud68c\uc0c9 \uc19c\ud138\uc758 \uc5b4\ub9b0 \uc0c8\ub294 \uc131\uccb4\ub97c \ucd95\uc18c\ud55c \ubaa8\uc591\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uc131\uc7a5\uacfc \uae43\ud138\uc758 \ubcc0\ud654\uac00 \ud544\uc694\ud558\ub2e4. \uc774\ub984\ub09c \ud2b9\uc9d5\uc744 \uc0dd\ud6c4 \uccab \uc21c\uac04\ubd80\ud130 \ubaa8\ub450 \uac16\ucd94\uace0 \uc788\uc73c\ub9ac\ub77c\uace0 \uae30\ub300\ud558\uba74 \ub193\uce60 \uc2dc\uac04\uc774 \uc788\ub2e4. \ub3d9\ubb3c\uc758 \ubaa8\uc2b5\uc740 \ubd84\ub958\uc758 \ud45c\uc9c0\uc774\uba74\uc11c \uc0dd\uc560\uc758 \ud55c \ub2e8\uacc4\ub3c4 \ubcf4\uc5ec \uc900\ub2e4. \uac19\uc740 \uc885\uc758 \uc0ac\uc9c4\uc5d0\uc11c \uc0c9\uacfc \ud06c\uae30\uac00 \ub2e4\ub978 \uac1c\uccb4\ub97c \ubcf4\ub354\ub77c\ub3c4 \ubb34\uc870\uac74 \uc608\uc678\ub098 \uc774\uc0c1 \uc0c1\ud0dc\ub85c \ud310\ub2e8\ud558\uc9c0 \uc54a\uc544\uc57c \ud55c\ub2e4. \uc5b4\ub290 \ub098\uc774\uc640 \uae43\ud138 \uc0c1\ud0dc\uc778\uc9c0 \uc790\ub8cc\ub97c \ud655\uc778\ud558\ub294 \uac83\uc774 \uba3c\uc800\ub2e4. \uae43\ud138\uc758 \ubd84\ud64d\uc0c9\uc740 \ub2e8\ubc88\uc5d0 \uc644\uc131\ud55c \ub85c\uace0\ucc98\ub7fc \uace0\uc815\ub41c \uac83\uc774 \uc544\ub2c8\ub77c \ubab8\uacfc \ud658\uacbd, \uc2dc\uac04\uc774 \uc774\uc5b4\uc9c4 \uacb0\uacfc\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \ub3d9\ubb3c\uc6d0 \uc124\uba85\uc5d0\ub294 \uc595\uc740 \ubb3c\uc5d0\uc11c \uba39\uc774\ub97c \uc5bb\uace0 \ubd80\ub9ac\ub85c \uc5ec\uacfc\ud558\ub294 \uae30\ub2a5\ub3c4 \ub4f1\uc7a5\ud55c\ub2e4. \ubd84\ud64d\uc0c9\uc774\ub77c\ub294 \uacb0\uacfc\ub9cc \ubcf4\ub2e4\uac00 \ubb34\uc5c7\uc744 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \uba39\ub294\uc9c0\uae4c\uc9c0 \uad00\uc2ec\uc774 \ub113\uc5b4\uc9c4\ub2e4. \uc0c9\uc758 \uc774\uc57c\uae30\uac00 \ubab8\uc758 \ub2e4\ub978 \uad6c\uc870\ub85c \uc774\uc5b4\uc9c0\ub294 \uac83\uc774\ub2e4. \ub2e4\ub9cc \ubd80\ub9ac\uac00 \uac78\ub7ec \ub0b4\ub294 \ubaa8\ub4e0 \ub300\uc0c1\uacfc \uadf8 \uc591\uc744 \uc0ac\uc9c4\uc5d0\uc11c \ud655\uc778\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ud55c \ud2b9\uc9d5\uc744 \ubc30\uc6b4 \ub4a4\uc5d0\ub294 \uadf8 \ud2b9\uc9d5\uc744 \uac00\ub2a5\ud558\uac8c \ud558\ub294 \uc0dd\ud65c\uc744 \ubb3c\uc5b4\ubcfc \uc218 \uc788\ub2e4. \ud50c\ub77c\ubc0d\uace0\ub97c \uc54c\uc544\ubcf4\ub294 \ub370 \uc0c9\uc774 \uc88b\uc740 \ub2e8\uc11c\uac00 \ub418\uc5b4\ub3c4 \uadf8\uac83\ub9cc\uc774 \uc0dd\ubb3c\uc758 \uc804\ubd80\ub294 \uc544\ub2c8\ub2e4. \uba39\uc774\ub97c \uc5bb\ub294 \ud589\ub3d9\uacfc \uc790\ub77c\ub294 \uc2dc\uac04\uc744 \ud568\uaed8 \ubcf4\uba74 \uc544\ub984\ub2e4\uc6b4 \uc0c8\ub77c\ub294 \uc778\uc0c1\uc5d0 \uad6c\uccb4\uc801\uc778 \uc0dd\ud0dc\uc758 \uc9c8\ubb38\uc774 \ub354\ud574\uc9c4\ub2e4. \uc775\uc219\ud55c \ubd84\ud64d\ube5b\uc5d0\uc11c \ucd9c\ubc1c\ud574 \ubcf4\uae30\uc758 \ubc94\uc704\uac00 \ub113\uc5b4\uc9c4\ub2e4. \ud50c\ub77c\ubc0d\uace0\uac00 \ubb3c\uc5d0 \ubd80\ub9ac\ub97c \ub123\uace0 \uc6c0\uc9c1\uc774\ub294 \ubaa8\uc2b5\uc744 \ubcfc \ub54c\uac00 \uc788\ub2e4. \uae34 \ubaa9\uacfc \ub3c5\ud2b9\ud55c \ubd80\ub9ac\ub294 \uc595\uc740 \ubb3c\uc5d0\uc11c \uba39\uc774\ub97c \uc5bb\ub294 \ubc29\uc2dd\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc6b0\uc544\ud55c \uc790\uc138\ub9cc \ucde8\ud558\uace0 \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc2dd\uc0ac \uc911\uc77c \uc218 \uc788\ub2e4. \uba40\ub9ac\uc11c \ubc14\ub77c\ubcf4\uba74 \uc6b0\ub9ac\ub294 \ubd84\ud64d\ube5b \ubb34\ub9ac\ub77c\ub294 \ud070 \ud48d\uacbd\uc744 \ubcf8\ub2e4. \uc870\uae08 \ub354 \ub4e4\uc5ec\ub2e4\ubcf4\uba74 \ud55c \ub9c8\ub9ac\ub294 \uba39\uc774\ub97c \ucc3e\uace0, \ub2e4\ub978 \ud55c \ub9c8\ub9ac\ub294 \uae43\ud138\uc744 \uc190\uc9c8\ud55c\ub2e4. \ud3ec\uc2a4\ud130\uc5d0 \uadf8\ub824\uc9c4 \uc0c1\uc9d5\uacfc \ub2ec\ub9ac \uc2e4\uc81c \uc0c8\ub294 \uacc4\uc18d \uc0dd\ud65c\ud558\uace0 \uc788\ub2e4. \ud50c\ub77c\ubc0d\uace0\ub97c \uc88b\uc544\ud55c\ub2e4\uace0 \uc5b4\ub824\uc6b4 \uc0dd\ubb3c\ud559 \uc6a9\uc5b4\ub97c \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uadf8 \ubd84\ud64d\uc0c9\uc774 \ucc98\uc74c\ubd80\ud130 \uc644\uc131\ub41c \ubb3c\uac10\ucc98\ub7fc \uc8fc\uc5b4\uc9c4 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc0ac\uc2e4\ub9cc \uc54c\uc544\ub3c4 \ucda9\ubd84\ud788 \uc7ac\ubbf8\uc788\ub2e4. \ub2e4\uc74c\uc5d0 \ubd84\ud64d\uc0c9 \ud50c\ub77c\ubc0d\uace0\ub97c \ub9cc\ub098\uba74 \uae43\ud138\uc744 \ud55c \ubc88, \ubb3c\uc18d\uc758 \ubd80\ub9ac\ub97c \ud55c \ubc88 \ubcf4\uc790. \ub208\uc5d0 \ubcf4\uc774\ub294 \uc0c9\uacfc \ub208\uc5d0 \uc798 \ub744\uc9c0 \uc54a\ub294 \uc2dd\uc0ac\uac00 \uac19\uc740 \uc774\uc57c\uae30 \uc548\uc5d0 \ub4e4\uc5b4 \uc788\ub2e4. \uc544\ub984\ub2e4\uc6b4 \uae43\ud138\uc5d0\ub3c4 \ub098\ub984\uc758 \uc2dd\ub2e8\uc774 \uc788\uc5c8\ub358 \uc148\uc774\ub2e4."}, {"id": "galileo-telescope-changed-sky", "title": "\uac08\ub9b4\ub808\uc624 \u2014 \ub9dd\uc6d0\uacbd\uc744 \ubc24\ud558\ub298\ub85c \ub3cc\ub9ac\ub358 \ub54c", "summary": "1609\ub144\uc758 \ub9dd\uc6d0\uacbd \uc2dc\uc5f0\uc5d0\uc11c \ub2ec\u00b7\ubaa9\uc131\u00b7\uae08\uc131\uc758 \uad00\uce21\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \ubc1c\uacac\uc758 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uacfc\ud559\uc790\uc758 \ubc1c\uacac", "categories": ["science"], "url": "stories/galileo-telescope-changed-sky/index.html", "image": "../media/galileo-telescope-changed-sky.png", "alt": "17\uc138\uae30 \ucd08\uc758 \uc0c1\uc0c1 \uc18d \uad00\uce21\uc790\uac00 \ud14c\ub77c\uc2a4\uc5d0\uc11c \uc791\uc740 \ub9dd\uc6d0\uacbd\uc73c\ub85c \ubc24\ud558\ub298\uc744 \ubc14\ub77c\ubcf4\ub294 \uc0bd\ud654.", "text": "\uac08\ub9b4\ub808\uc624 \u2014 \ub9dd\uc6d0\uacbd\uc744 \ubc24\ud558\ub298\ub85c \ub3cc\ub9ac\ub358 \ub54c \uba3c \ubc30\ub97c \ubcf4\ub358 \ub3c4\uad6c\uac00 \ud558\ub298\uc758 \uc9c8\uc11c\ub97c \ubb3b\uae30\uae4c\uc9c0 1609\ub144\uc758 \ub9dd\uc6d0\uacbd \uc2dc\uc5f0\uc5d0\uc11c \ub2ec\u00b7\ubaa9\uc131\u00b7\uae08\uc131\uc758 \uad00\uce21\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \ubc1c\uacac\uc758 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uacfc\ud559\uc790\uc758 \ubc1c\uacac \uacfc\ud559\uacfc \ubc1c\uacac \uba40\ub9ac \uc788\ub294 \ubc30\ub97c \uac00\uae4c\uc774 \ubcf4\ub294 \ub3c4\uad6c\uac00 \uc0dd\uacbc\ub2e4. \ud56d\uad6c\uc5d0\uc11c \uc120\ubc15\uc744 \uba3c\uc800 \uc54c\uc544\ubcf4\uace0 \uc2f6\uc5b4 \ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc720\uc6a9\ud55c \ubc1c\uba85\ud488\uc774\uc5c8\ub2e4. \uadf8\ub7f0\ub370 \uadf8 \ub3c4\uad6c\ub97c \ubc24\ud558\ub298\ub85c \ub3cc\ub9ac\uba74 \ubb34\uc5c7\uc774 \ubcf4\uc77c\uae4c. 17\uc138\uae30 \ucd08 \uac08\ub9b4\ub808\uc624\ub294 \uc774 \uc9c8\ubb38\uc73c\ub85c \uc0ac\ub78c\ub4e4\uc774 \uc54c\uace0 \uc788\ub2e4\uace0 \ubbff\ub358 \ud558\ub298\uc744 \ub2e4\uc2dc \uc0b4\ud3c8\ub2e4. \uadf8\uac00 \ub9dd\uc6d0\uacbd \uc790\uccb4\ub97c \ucc98\uc74c \ubc1c\uba85\ud55c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uc774\ubbf8 \uc54c\ub824\uc9c4 \ub3c4\uad6c\ub97c \uac1c\uc120\ud558\uace0, \uadf8\uac83\uc744 \ud1b5\ud574 \ubcf4\uc774\ub294 \ud604\uc0c1\uc774 \ubbff\uc744 \ub9cc\ud55c\uc9c0 \ud655\uc778\ud558\uba70, \uae30\uc874\uc758 \uc124\uba85\uacfc \ube44\uad50\ud55c \uacfc\uc815\uc774\uc5c8\ub2e4. \ubc1c\uacac\uc740 \ub80c\uc988\ub97c \ub208\uc5d0 \ub304 \ud55c\uc21c\uac04\ubcf4\ub2e4 \uae38\uc5c8\ub2e4. \uad50\uc7ac\ub294 1608\ub144 \ub124\ub35c\ub780\ub4dc\uc5d0\uc11c \uc54c\ub824\uc9c4 \ub9dd\uc6d0 \ub3c4\uad6c\uc640 \ud55c\uc2a4 \ub9ac\ud37c\uc138\uc774\ub97c \uc18c\uac1c\ud55c\ub2e4. \uac08\ub9b4\ub808\uc624\ub294 \uadf8 \uc18c\uc2dd\uc744 \ub4e3\uace0 \uc790\uc2e0\uc758 \ub3c4\uad6c\ub97c \ub9cc\ub4e4\uc5c8\ub2e4. \ucc98\uc74c\ubd80\ud130 \uc624\ub298\ub0a0\uc758 \ucc9c\ubb38\ub300 \uac19\uc740 \uc7a5\ube44\uac00 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub80c\uc988\uc640 \uad00\uc744 \uc870\ud569\ud558\ub294 \uc791\uc5c5\uc5d0\uc11c \ucd9c\ubc1c\ud588\ub2e4. \uba40\ub9ac \uc788\ub294 \uac83\uc744 \ud06c\uac8c \ubcf4\uc774\uac8c \ud55c\ub2e4\ub294 \uad6c\uc0c1\uc740 \ub2e8\uc21c\ud574 \ubcf4\uc774\uc9c0\ub9cc \uc2e4\uc81c\ub85c \uc120\uba85\ud55c \uc0c1\uc744 \uc5bb\ub294 \uac83\uc740 \ub2e4\ub978 \ubb38\uc81c\ub2e4. \uac08\ub9b4\ub808\uc624\ub294 \ubc30\uc728\uacfc \uad11\ud559 \uc131\ub2a5\uc744 \ub192\uc774\uace0 \uc548\uc815\uc801\uc73c\ub85c \uc9c0\uc9c0\ud558\ub294 \uc7a5\uce58\ub3c4 \ub9c8\ub828\ud588\ub2e4. \uad00\uce21\uc758 \uc5ed\uc0ac\ub294 \ub208\uc758 \uc5ed\uc0ac\uc774\uba74\uc11c \ub3c4\uad6c\ub97c \ub9cc\ub4dc\ub294 \uc190\uc758 \uc5ed\uc0ac\uc774\uae30\ub3c4 \ud588\ub2e4. 1609\ub144 8\uc6d4 25\uc77c \uac08\ub9b4\ub808\uc624\ub294 \ubca0\ub124\uce58\uc544\uc758 \uad00\ub9ac\ub4e4\uc5d0\uac8c \ub9dd\uc6d0\uacbd\uc744 \uc2dc\uc5f0\ud588\ub2e4. \uad50\uc7ac\ub294 \ub2f9\uc2dc \ubc30\uc728\uc774 \uc544\ud649 \ubc30\uc600\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uba40\ub9ac \uc788\ub294 \ub300\uc0c1\uc744 \uc77c\ucc0d \ud655\uc778\ud558\ub294 \ub2a5\ub825\uc740 \uad70\uc0ac\uc640 \ud574\uc0c1 \ud65c\ub3d9\uc5d0\uc11c \uad00\uc2ec\uc744 \ub04c \ub9cc\ud588\ub2e4. \ubcc4\ubcf4\ub2e4 \uc9c0\uc0c1\uc758 \ud65c\uc6a9\uc774 \uba3c\uc800 \uc0ac\ub78c\ub4e4\uc758 \ub208\uc55e\uc5d0 \ub193\uc600\ub2e4. \uadf8 \ub4a4 \ubc24\ud558\ub298\uc758 \uad00\uce21\uc5d0 \ub9de\ucd94\uc5b4 \ub3c4\uad6c\uc758 \uc131\ub2a5\uc774 \ub354 \uac1c\uc120\ub418\uc5c8\ub2e4. \uac19\uc740 \ubb3c\uac74\ub3c4 \uc5b4\ub5a4 \uc9c8\ubb38\uc5d0 \uc0ac\uc6a9\ud558\ub294\uc9c0\uc5d0 \ub530\ub77c \uc5ed\ud560\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uba3c \ubc30\ub97c \ubcf4\ub294 \uc720\uc6a9\ud568\uc5d0\uc11c \ud558\ub298\uc758 \uae30\uc874 \uc124\uba85\uc744 \uc2dc\ud5d8\ud558\ub294 \ub3c4\uad6c\ub85c \ub118\uc5b4\uac08 \uc218 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4. \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc740 \ub80c\uc988\uc640 \uac70\uc6b8\uc774 \uc0c1\uc744 \ubc14\uafb8\uac70\ub098 \ub4a4\uc9d1\uc744 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c\uace0 \uc788\uc5c8\ub2e4. \ub9dd\uc6d0\uacbd\uc5d0\uc11c \uc0c8\ub85c\uc6b4 \uac83\uc774 \ubcf4\uc778\ub2e4\uace0 \uadf8\uac83\uc774 \uace7 \uc2e4\uc81c \ud558\ub298\uc758 \ubaa8\uc2b5\uc774\ub77c\uace0 \uc778\uc815\ub418\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ub3c4\uad6c\uac00 \ub9cc\ub4e0 \ud6a8\uacfc\uc778\uc9c0 \ub300\uc0c1\uc758 \uc131\uc9c8\uc778\uc9c0 \uad6c\ubcc4\ud574\uc57c \ud588\ub2e4. \uad50\uc7ac\ub294 \uac08\ub9b4\ub808\uc624\uac00 \uac00\uae4c\uc774\uc11c \ud655\uc778\ud560 \uc218 \uc788\ub294 \ub300\uc0c1\uc744 \ubc18\ubcf5\ud574\uc11c \ube44\uad50\ud558\uba70 \ub3c4\uad6c\ub97c \uc2e0\ub8b0\ud560 \uadfc\uac70\ub97c \ub9c8\ub828\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uacfc\ud559\uc758 \uc5ed\uc0ac\uc5d0\uc11c \uc911\uc694\ud55c \ub300\ubaa9\uc774\ub2e4. \ub180\ub77c\uc6b4 \uc7a5\uba74\uc744 \ubcf4\uc558\ub2e4\ub294 \uc8fc\uc7a5\ubfd0 \uc544\ub2c8\ub77c \uadf8\uac83\uc744 \uc65c \ubbff\uc744 \uc218 \uc788\ub294\uc9c0\ub3c4 \ubcf4\uc5ec \uc904 \ud544\uc694\uac00 \uc788\uc5c8\ub2e4. \ub9dd\uc6d0\uacbd\uc73c\ub85c \ubcf8 \ub2ec\uc5d0\ub294 \uc0b0\uacfc \uace8\uc9dc\uae30, \uc5ec\ub7ec \uc6b8\ud241\ubd88\ud241\ud55c \ud754\uc801\uc774 \ub098\ud0c0\ub0ac\ub2e4. \uc9c0\uc0c1\uc758 \ubd88\uc644\uc804\ud55c \uc138\uacc4\uc640 \ub2e4\ub978 \uc644\ubcbd\ud55c \ud558\ub298\uc774\ub77c\ub294 \uc0dd\uac01\uc5d0\ub294 \ubd88\ud3b8\ud55c \uad00\ucc30\uc774\uc5c8\ub2e4. \uba40\ub9ac \uc788\ub294 \ucc9c\uccb4\ub3c4 \ub545\ucc98\ub7fc \ubcf5\uc7a1\ud55c \ud45c\uba74\uc744 \uac00\uc9c4\ub2e4\uba74 \ub458 \uc0ac\uc774\uc758 \uacbd\uacc4\ub97c \ub2e4\uc2dc \ubb3c\uc744 \uc218 \uc788\uc5c8\ub2e4. \uac08\ub9b4\ub808\uc624\uac00 \uc5b4\ub450\uc6b4 \ubd80\ubd84\uc744 \ubb3c\uc77c \uc218 \uc788\ub2e4\uace0 \uc0dd\uac01\ud55c \uac83\uc740 \uc624\ub298\uc758 \uc9c0\uc2dd\uacfc \ub2e4\ub974\ub2e4. \uad00\ucc30\uc774 \uc0c8\ub85c\uc6e0\ub2e4\uace0 \ubaa8\ub4e0 \ud574\uc11d\uc774 \uc644\uc131\ub41c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ub3c4\uad6c\ub97c \ud1b5\ud574 \uc5bb\uc740 \uc138\ubd80\uac00 \uc624\ub798\ub41c \uc124\uba85\uacfc \ube44\uad50\ub418\uae30 \uc2dc\uc791\ud588\ub2e4\ub294 \uc810\uc774\ub2e4. \uc798 \ubcf8 \uac83\uacfc \uc815\ud655\ud558\uac8c \ub73b\uc744 \ubd99\uc778 \uac83\uc740 \ub2e4\ub978 \ub2e8\uacc4\uc600\ub2e4. \uac08\ub9b4\ub808\uc624\ub294 \ubaa9\uc131 \uc8fc\ubcc0\uc744 \ub3c4\ub294 \ub124 \uc704\uc131\uc744 \ud655\uc778\ud588\ub2e4. \uc774 \ubc1c\uacac\uc740 \ubaa8\ub4e0 \ucc9c\uccb4\uac00 \uc9c0\uad6c\ub9cc\uc744 \uc911\uc2ec\uc73c\ub85c \uc6c0\uc9c1\uc5ec\uc57c \ud55c\ub2e4\ub294 \uc0dd\uac01\uc5d0 \ubb38\uc81c\ub97c \uc81c\uae30\ud588\ub2e4. \uc6c0\uc9c1\uc774\ub294 \ud589\uc131\ub3c4 \uc790\uae30 \uc8fc\uc704\ub97c \ub3c4\ub294 \ucc9c\uccb4\ub97c \uac00\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \uc9c0\uad6c\uac00 \uc6c0\uc9c1\uc774\uba74 \ub2ec\uc774 \ub530\ub77c\uc624\uc9c0 \ubabb\ud560 \uac83\uc774\ub77c\ub294 \ubc18\ub860\ub3c4 \ub2e4\uc2dc \uc0dd\uac01\ud558\uac8c \ud588\ub2e4. \ub2e4\ub9cc \uc774 \uad00\ucc30 \ud558\ub098\ub85c \ud0dc\uc591\uacc4\uc758 \ubaa8\ub4e0 \ubaa8\ud615\uc774 \ub3d9\uc2dc\uc5d0 \ud310\uc815\ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. \ubaa9\uc131 \uc704\uc131\uc740 \ubb34\uc5c7\uc774 \uc9c0\uad6c \uc8fc\uc704\ub97c \ub3c4\ub294\uc9c0\uc5d0 \uad00\ud55c \uc911\uc694\ud55c \uc99d\uac70\uc600\uc9c0\ub9cc, \ub2e4\ub978 \uad00\uce21\uacfc \uc774\ub860\uc758 \ube44\uad50\uac00 \uacc4\uc18d \ud544\uc694\ud588\ub2e4. \ubc1c\uacac\uc758 \uc758\ubbf8\ub97c \ud06c\uac8c \ubcf4\uba74\uc11c\ub3c4 \uadf8\uac83\uc774 \ub2f5\ud55c \uc9c8\ubb38\uc758 \ubc94\uc704\ub97c \ub098\ub204\uc5b4 \uc77d\uc744 \uc218 \uc788\ub2e4. \uae08\uc131\uc740 \ub2ec\ucc98\ub7fc \uc5ec\ub7ec \ubaa8\uc2b5\uc73c\ub85c \ubcf4\uc600\ub2e4. \uad50\uc7ac\ub294 \uac08\ub9b4\ub808\uc624\uac00 \uad00\uce21\ud55c \uae08\uc131\uc758 \uc704\uc0c1 \ubcc0\ud654\uac00 \uae30\uc874 \ud504\ud1a8\ub808\ub9c8\uc774\uc624\uc2a4 \uccb4\uacc4\uc640 \ub9de\uc9c0 \uc54a\uc558\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubb34\uc5c7\uc774 \uc5b4\ub290 \uc911\uc2ec\uc744 \ub3cc \ub54c \uc5b4\ub5a4 \ubaa8\uc2b5\uc774 \ubcf4\uc5ec\uc57c \ud558\ub294\uc9c0\ub97c \ube44\uad50\ud558\ub294 \uad00\uce21\uc774\uc5c8\ub2e4. \uc774 \uacb0\uacfc\ub294 \ucf54\ud398\ub974\ub2c8\ucfe0\uc2a4\uc758 \uad6c\uc0c1\uc744 \uc9c0\uc9c0\ud558\ub294 \ub370 \uc911\uc694\ud588\ub2e4. \uadf8\ub807\ub2e4\uace0 \ud558\ub8fb\ubc24\uc5d0 \uc9c0\ub3d9\uc124\uc758 \ubaa8\ub4e0 \uc7c1\uc810\uc774 \ub05d\ub0ac\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uad00\uce21\uc758 \uc885\ub958\uc640 \uac01 \ubaa8\ud615\uc774 \uc124\uba85\ud558\ub294 \ubc94\uc704\uac00 \uc11c\ub85c \ub2ec\ub790\ub2e4. \uacfc\ud559\uc758 \ubcc0\ud654\ub294 \uc0c8\ub85c\uc6b4 \uadf8\ub9bc \ud558\ub098\uac00 \uc61b \uadf8\ub9bc\uc744 \uc989\uc2dc \uc9c0\uc6b0\ub294 \uac83\ubcf4\ub2e4 \ub354 \uae34 \ub17c\uc7c1\uacfc \ud655\uc778\uc758 \uacfc\uc815\uc774\uc5c8\ub2e4. \uac08\ub9b4\ub808\uc624\uc758 \uc8fc\uc7a5\uc740 \uad50\ud68c \uad8c\uc704\uc640 \ucda9\ub3cc\ud588\ub2e4. 1616\ub144\uc5d0\ub294 \ucf54\ud398\ub974\ub2c8\ucfe0\uc2a4\uc758 \uc8fc\uc7a5\uc744 \uc639\ud638\ud558\uc9c0 \ubabb\ud558\uac8c \ud558\ub294 \uacb0\uc815\uc774 \ub098\uc654\uace0, \uac08\ub9b4\ub808\uc624\ub294 \uc774\ud6c4 \uc885\uad50\uc7ac\ud310\uacfc \uac00\ud0dd\uc5f0\uae08\ub3c4 \uacaa\uc5c8\ub2e4. \uad00\uce21 \uacb0\uacfc\ub97c \ud574\uc11d\ud558\ub294 \uc77c\uc740 \ub2f9\uc2dc\uc758 \uc815\uce58\uc640 \uc885\uad50\uc801 \uad8c\uc704\uc5d0\uc11c \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\uc558\ub2e4. \uc774 \uc5ed\uc0ac\ub97c \uc885\uad50\uc778 \uc804\uccb4\uc640 \uacfc\ud559\uc790 \uc804\uccb4\uc758 \ub2e8\uc21c\ud55c \ub450 \ud3b8 \uc2f8\uc6c0\uc73c\ub85c \uc904\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uac08\ub9b4\ub808\uc624 \uc790\uc2e0\ub3c4 \uc2e0\uc559\uc744 \uac00\uc9c4 \uc0ac\ub78c\uc774\uc5c8\ub2e4. \ubb34\uc5c7\uc744 \uadfc\uac70\ub85c \uc790\uc5f0\uc744 \uc124\uba85\ud558\uace0 \ub204\uac00 \uadf8 \uc124\uba85\uc744 \uacf5\uc801\uc73c\ub85c \uc778\uc815\ud558\ub294\uc9c0\ub77c\ub294 \uad6c\uccb4\uc801\uc778 \uae34\uc7a5\uc774 \uc788\uc5c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 17\uc138\uae30 \ucd08 \uad00\uce21\uc790\ub97c \ub5a0\uc62c\ub9ac\ub294 \uc0c1\uc0c1 \uc18d \uc7a5\uba74\uc774\ub2e4. \uac08\ub9b4\ub808\uc624\uc758 \uc2e4\uc81c \ucd08\uc0c1\uc774\ub098 \ud2b9\uc815 \ub9dd\uc6d0\uacbd, \uad00\uce21\ud55c \ubcc4\uc758 \uc704\uce58\ub97c \uc7ac\ud604\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ub3c4\uad6c\ub97c \ud558\ub298\ub85c \ub3cc\ub9b0 \ud589\uc704\uc758 \ubd84\uc704\uae30\ub97c \ud45c\ud604\ud588\ub2e4. \uac08\ub9b4\ub808\uc624\uac00 \ubc14\uafbc \uac83\uc740 \ud558\ub298 \uc790\uccb4\uac00 \uc544\ub2c8\ub77c \ud558\ub298\uc744 \uc54c\uc544\ubcf4\ub294 \ubc29\ubc95\uc774\uc5c8\ub2e4. \ub80c\uc988\ub97c \ub9cc\ub4e4\uace0 \uc2e0\ub8b0\ub97c \ud655\uc778\ud558\uba70 \ubcf4\uc774\ub294 \uac83\uacfc \uc124\uba85\uc744 \ube44\uad50\ud588\ub2e4. \ubc24\ud558\ub298\uc758 \uc791\uc740 \ube5b\ub4e4\uc744 \ub2e4\uc2dc \uc77d\uc740 \uc774 \uacfc\uc815\uc740 \uacfc\ud559\uc0ac\uac00 \uc815\ub2f5\uc758 \uc5f0\ud45c\ubfd0 \uc544\ub2c8\ub77c \uc9c8\ubb38\uacfc \uac80\uc99d\uc758 \uc5ed\uc0ac\uc774\uae30\ub3c4 \ud568\uc744 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "gecko-feet-small-forces", "title": "\ub3c4\ub9c8\ubc40\ubd99\uc774 \u2014 \uc811\ucc29\uc81c \uc5c6\uc774 \ubcbd\uc744 \uac77\ub294 \ubc1c", "summary": "\ub3c4\ub9c8\ubc40\ubd99\uc774 \ubc1c\uc758 \ubbf8\uc138\ud55c \ud138\uacfc \ubd84\uc790 \uc0ac\uc774 \ud798\uc744 \uc5f0\uacb0\ud574 \ubd80\ucc29\uacfc \ub5bc\uc5b4 \ub0b4\uae30\uc758 \uc6d0\ub9ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uc0dd\uba85\uacfc \uc778\uccb4", "categories": ["science"], "url": "stories/gecko-feet-small-forces/index.html", "image": "../media/gecko-feet-small-forces.png", "alt": "\uc78e\uc0ac\uadc0 \uc606\uc758 \uc218\uc9c1 \ubcbd\uc5d0 \ubc1c\uc744 \ud3bc\uccd0 \ubd99\uc5b4 \uc788\ub294 \uc791\uc740 \ub3c4\ub9c8\ubc40\ubd99\uc774\uc758 \uc0bd\ud654.", "text": "\ub3c4\ub9c8\ubc40\ubd99\uc774 \u2014 \uc811\ucc29\uc81c \uc5c6\uc774 \ubcbd\uc744 \uac77\ub294 \ubc1c \uc791\uc740 \uc811\ucd09\uc774 \uc544\uc8fc \ub9ce\uc774 \ubaa8\uc774\uba74 \uc0dd\uae30\ub294 \ud798 \ub3c4\ub9c8\ubc40\ubd99\uc774 \ubc1c\uc758 \ubbf8\uc138\ud55c \ud138\uacfc \ubd84\uc790 \uc0ac\uc774 \ud798\uc744 \uc5f0\uacb0\ud574 \ubd80\ucc29\uacfc \ub5bc\uc5b4 \ub0b4\uae30\uc758 \uc6d0\ub9ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uc0dd\uba85\uacfc \uc778\uccb4 \uacfc\ud559\uacfc \ubc1c\uacac \uc791\uc740 \ub3c4\ub9c8\ubc40\ubd99\uc774\uac00 \ub9e4\ub048\ud55c \ubcbd\uc5d0 \ubd99\uc5b4 \uc788\ub2e4. \uc190\ud1b1\uc774 \uac78\ub9b4 \ud2c8\ub3c4 \uc5c6\uc5b4 \ubcf4\uc774\ub294\ub370 \ubc1c\uc744 \uc62e\uae30\uba70 \uc6c0\uc9c1\uc778\ub2e4. \ucc9c\uc7a5\uc5d0\uc11c\ub3c4 \ube44\uc2b7\ud55c \ub2a5\ub825\uc744 \ubcf4\uc774\ub294 \uc885\ub958\uac00 \uc788\ub2e4. \ubc1c\ubc14\ub2e5\uc5d0 \uc811\ucc29\uc81c\uac00 \ubb3b\uc5b4 \uc788\uac70\ub098 \uc791\uc740 \ube68\ud310\uc774 \ub2ec\ub824 \uc788\ub294 \uac83\uc77c\uae4c. \uad50\uc7ac\uc5d0 \uc18c\uac1c\ub41c \uc5f0\uad6c\ub294 \ub2e4\ub978 \ub2f5\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ubc1c\uc758 \uc544\uc8fc \uc791\uc740 \uad6c\uc870\uac00 \ud45c\uba74\uacfc \ub9ce\uc740 \uc811\ucd09\uc744 \ub9cc\ub4e4\uace0, \uac00\uae4c\uc6b4 \uac70\ub9ac\uc5d0\uc11c \uc791\uc6a9\ud558\ub294 \uc791\uc740 \ud798\ub4e4\uc774 \ubaa8\uc778\ub2e4. \ubcbd\uc744 \uac77\ub294 \ub2a5\ub825\uc740 \uac70\ub300\ud55c \ud798 \ud558\ub098\ubcf4\ub2e4 \ub208\uc5d0 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc811\ucd09\uc758 \uc218\uc640 \ubc29\uc2dd\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\ub2e4. OpenStax\ub294 \ub3c4\ub9c8\ubc40\ubd99\uc774\uc758 \ubc1c\uac00\ub77d\uc5d0 \ub9ce\uc740 \ubbf8\uc138\ud55c \ud138\uc774 \uc788\uace0, \uadf8 \ud138\uc774 \ub354 \uc791\uc740 \ub0a9\uc791\ud55c \ub05d\uc73c\ub85c \uac08\ub77c\uc9c4\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc6b0\ub9ac\uac00 \uba40\ub9ac\uc11c \ubcf4\ub294 \ubc1c\ubc14\ub2e5\uc740 \ub9e4\ub048\ud55c \ud55c \uc7a5\uc758 \ud310\uc774 \uc544\ub2c8\ub2e4. \ub9e4\uc6b0 \uc791\uc740 \ud06c\uae30\uc5d0\uc11c \ud45c\uba74\uc744 \ub9cc\ub098\ub294 \uad6c\uc870\uac00 \ubc18\ubcf5\ub418\uc5b4 \uc788\ub2e4. \uc774\ub7f0 \uad6c\uc870\ub294 \ud45c\uba74\uacfc \uc811\ucd09\ud560 \uc218 \uc788\ub294 \ubd80\ubd84\uc744 \ud06c\uac8c \ub298\ub9b0\ub2e4. \ubc1c \uc804\uccb4\uac00 \ubcbd\uc5d0 \ud55c \ubc88 \ub2ff\ub294 \uac83\ucc98\ub7fc \ubcf4\uc5ec\ub3c4 \ubbf8\uc138\ud55c \ub05d\ub4e4\uc740 \ub9ce\uc740 \uc790\ub9ac\uc5d0\uc11c \uc791\uc6a9\ud560 \uc218 \uc788\ub2e4. \ubab8\uc758 \ud06c\uae30\ub9cc \ubcf4\ub294 \uc2dc\uc120\uacfc \uc811\ucd09\uc758 \uc791\uc740 \ud06c\uae30\ub85c \ub0b4\ub824\uac00\ub294 \uc2dc\uc120\uc774 \uc11c\ub85c \ub2e4\ub978 \uc815\ubcf4\ub97c \uc8fc\ub294 \uac83\uc774\ub2e4. \uad50\uc7ac\ub294 \ubd84\uc0b0\ub825\uc774\ub77c\ub294 \ubd84\uc790 \uc0ac\uc774\uc758 \uc778\ub825\uc744 \uc124\uba85\ud55c\ub2e4. \uc804\uc790\uc758 \ubd84\ud3ec\uac00 \uc21c\uac04\uc801\uc73c\ub85c \ub2ec\ub77c\uc9c0\uba74\uc11c \uc774\uc6c3\ud55c \uc785\uc790\uc640\uc758 \ub04c\ub9bc\uc774 \ub098\ud0c0\ub0a0 \uc218 \uc788\ub2e4. \uc6d0\uc790\uc640 \ubd84\uc790\uac00 \ub2e8\ub2e8\ud55c \uad6c\uc2ac\ucc98\ub7fc \uc11c\ub85c \uc804\ud600 \uad00\uacc4\uc5c6\uc774 \ub193\uc5ec \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c \uc911\uc694\ud55c \uac83\uc740 \ud55c \uc30d \uc0ac\uc774\uc758 \ud798\uc774 \uc791\ub2e4\ub294 \uc810\uc774\ub2e4. \uc791\uc740 \ud798\uc774\ub77c\ub294 \uc774\uc720\ub85c \uc5b8\uc81c\ub098 \ubb34\uc2dc\ud574\ub3c4 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc544\uc8fc \uac00\uae4c\uc6b4 \uc811\ucd09\uc774 \ucda9\ubd84\ud788 \ub9ce\uc544\uc9c0\uba74 \uc804\uccb4\uc758 \ud6a8\uacfc\uac00 \ucee4\uc9c8 \uc218 \uc788\ub2e4. \ub3c4\ub9c8\ubc40\ubd99\uc774\uc758 \ubc1c\uc740 \uc774 \uc791\uc740 \ud06c\uae30\uc640 \ub9ce\uc740 \uc218\uc758 \ub9cc\ub0a8\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ubbf8\uc138\ud55c \ud138 \ub05d\ub4e4\uc774 \ubcbd\uacfc \uac00\uae4c\uc774 \uc811\ucd09\ud558\uba74 \ub9ce\uc740 \uc790\ub9ac\uc5d0\uc11c \ubd84\uc790 \uc0ac\uc774\uc758 \ud798\uc774 \uc791\uc6a9\ud55c\ub2e4. \uad50\uc7ac\ub294 \uadf8 \ud569\uc774 \ubab8\uc744 \uc9c0\ud0f1\ud560 \ub9cc\ud07c \ucee4\uc9c8 \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc811\ucc29\uc81c\ub97c \ubc1c\ub77c \uad73\ud788\ub294 \ubc29\uc2dd\uc774\ub098 \uacf5\uae30\ub97c \ube68\uc544\ub0b4\ub294 \ube68\ud310\uacfc\ub294 \ub2e4\ub978 \uc6d0\ub9ac\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubc1c\uc774 \ub2ff\ub294 \ubaa8\ub4e0 \uacf3\uc5d0\uc11c \uac19\uc740 \ud798\uc744 \ub0b8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc2e4\uc81c \uc811\ucd09\uc758 \uc0c1\ud0dc\uc640 \ud45c\uba74\uc758 \uc131\uc9c8\uc774 \uc911\uc694\ud558\ub2e4. \uc791\uc6a9\ud560 \uc218 \uc788\ub294 \uad6c\uc870\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8 \uad6c\uc870\uac00 \ucda9\ubd84\ud788 \uc811\ucd09\ud558\uace0 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub974\ub2e4. \ub2a5\ub825\uc744 \uc124\uba85\ud560 \ub54c\ub3c4 \uc870\uac74\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uad50\uc7ac\ub294 2000\ub144 \ucf08\ub7ec \uc624\ud140 \uc5f0\uad6c\ud300\uc774 \uc11c\ub85c \ub2e4\ub978 \uc131\uc9c8\uc758 \ud45c\uba74\uc5d0\uc11c \ubd80\ucc29\uc744 \ube44\uad50\ud55c \uc5f0\uad6c\ub97c \uc18c\uac1c\ud55c\ub2e4. \uadf9\uc131\uc774 \uc788\ub294 \ud45c\uba74\uacfc \uadf8\ub807\uc9c0 \uc54a\uc740 \ud45c\uba74\uc5d0\uc11c\ub3c4 \uc798 \ubd99\ub294\ub2e4\ub294 \uad00\ucc30\uc740 \ubd84\uc0b0\ub825\uc758 \uc911\uc694\uc131\uc744 \uc124\uba85\ud558\ub294 \uadfc\uac70\uac00 \ub418\uc5c8\ub2e4. \uc778\uc0c1\uc801\uc778 \ub3d9\uc791\uc744 \ubcf4\ub294 \ub370\uc11c \uba48\ucd94\uc9c0 \uc54a\uace0 \uac00\ub2a5\ud55c \uc6d0\uc778\uc744 \uad6c\ubd84\ud558\ub824 \ud55c \uac83\uc774\ub2e4. \uc774 \ub300\ubaa9\uc5d0\uc11c \uc7ac\ubbf8\uc788\ub294 \uac83\uc740 \ub2f5\uc758 \uc774\ub984\ubcf4\ub2e4 \uc9c8\ubb38\uc758 \ubc29\uc2dd\uc774\ub2e4. \uc811\ucc29\uc81c\uc778\uc9c0, \ub2e4\ub978 \ubd84\uc790 \uac04 \uc0c1\ud638\uc791\uc6a9\uc778\uc9c0 \uc124\uba85\uc744 \ub098\ub204\uace0, \uc11c\ub85c \ub2e4\ub978 \uc608\uce21\uc774 \ub098\uc624\ub294 \uc870\uac74\uc5d0\uc11c \ube44\uad50\ud55c\ub2e4. \uc0dd\ubb3c\uc758 \ubb18\uae30\ub97c \uacfc\ud559\uc758 \ubb38\uc81c\ub85c \ubc14\uafb8\ub294 \uc77c\uc5d0\ub294 \uc774\ub7f0 \uc2e4\ud5d8\uc758 \uc124\uacc4\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \ubcbd\uc5d0 \uc544\uc8fc \uc798 \ubd99\uae30\ub9cc \ud55c\ub2e4\uba74 \ub2e4\uc74c \ubc1c\uc744 \uc62e\uae30\uae30 \uc5b4\ub824\uc6b8 \uac83\uc774\ub2e4. \uc2e4\uc81c \ub3d9\ubb3c\uc740 \ubd99\ub294 \uc77c\uacfc \ub5a8\uc5b4\uc9c0\ub294 \uc77c\uc744 \ubc18\ubcf5\ud558\uba70 \uac77\ub294\ub2e4. \uad50\uc7ac\ub294 \ubc1c\ub05d\uacfc \ud45c\uba74 \uc0ac\uc774\uc758 \uac01\ub3c4, \ubc1c\uac00\ub77d\uc758 \uc6c0\uc9c1\uc784\uc774 \uc811\ucd09\uc744 \ubc14\uafb8\ub294 \uc124\uba85\uc744 \uc18c\uac1c\ud55c\ub2e4. \ud798\uc758 \ud06c\uae30\ub9cc \ud0a4\uc6b0\ub294 \uac83\uacfc \ud544\uc694\ud560 \ub54c \uc791\uc6a9\uc744 \ubc14\uafb8\ub294 \uac83\uc740 \ub2e4\ub978 \uacfc\uc81c\ub2e4. \uad6c\uc870\uac00 \ud45c\uba74\uc5d0 \uc5b4\ub5bb\uac8c \ub193\uc774\ub294\uc9c0\uc5d0 \ub530\ub77c \uc804\uccb4\uc758 \ubd80\ucc29 \uc0c1\ud0dc\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ub3c4\ub9c8\ubc40\ubd99\uc774\uc758 \ub2a5\ub825\uc740 \uac15\ud558\uac8c \ubc84\ud2f0\ub294 \ubc1c\ubfd0 \uc544\ub2c8\ub77c \uc6c0\uc9c1\uc784\uc5d0 \ub9de\ucd94\uc5b4 \uc811\ucd09\uc744 \uc870\uc808\ud558\ub294 \ubc1c\uc758 \uc774\uc57c\uae30\uc774\uae30\ub3c4 \ud558\ub2e4. \uad50\uc7ac\ub294 \ubb3c\uc5d0 \uc798 \uc816\uc9c0 \uc54a\ub294 \ud45c\uba74\uc5d0\uc11c \ub9c8\ub978 \uc870\uac74\uacfc \uc816\uc740 \uc870\uac74\uc758 \ubd80\ucc29\uc744 \ube44\uad50\ud55c \ud6c4\uc18d \uc5f0\uad6c\ub3c4 \uc18c\uac1c\ud55c\ub2e4. \uc774\ub294 \ubaa8\ub4e0 \uc885\ub958\uc758 \uc816\uc740 \ubcbd\uc5d0\uc11c \ud56d\uc0c1 \ub611\uac19\uc774 \ubd99\ub294\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ubb3c\uacfc \ud45c\uba74\uc758 \uc870\ud569, \uc2dc\ud5d8 \uc870\uac74\uc744 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \uc5b4\ub5a4 \uc5f0\uad6c\uac00 \ud2b9\uc815\ud55c \uc870\uac74\uc5d0\uc11c \uc88b\uc740 \uacb0\uacfc\ub97c \ubcf4\uc600\ub2e4\ub294 \ub9d0\uacfc \uc790\uc5f0\uc758 \ubaa8\ub4e0 \uc0c1\ud669\uc744 \ud574\uacb0\ud588\ub2e4\ub294 \ub9d0\uc740 \ub2e4\ub974\ub2e4. \ub3d9\ubb3c\uc758 \ub2a5\ub825\uc744 \ud765\ubbf8\ub86d\uac8c \uc18c\uac1c\ud560\uc218\ub85d \uadf8 \ubc94\uc704\ub97c \uc9c0\ud0a4\ub294 \uc77c\uc774 \uc911\uc694\ud558\ub2e4. \uc870\uac74\uc774 \ub0a8\uc544 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ubc1c\uacac\uc744 \uc57d\ud558\uac8c \ud558\uae30\ubcf4\ub2e4 \ubb34\uc5c7\uc744 \ub354 \uc54c\uc544\ubcfc\uc9c0 \uc54c\ub824 \uc900\ub2e4. \uc5f0\uad6c\uc790\ub4e4\uc740 \uc774\ub7f0 \ubd80\ucc29 \uad6c\uc870\ub97c \uc774\ud574\ud574 \uc0c8\ub85c\uc6b4 \uc811\ucc29 \uae30\uc220\uc5d0 \ud65c\uc6a9\ud560 \uac00\ub2a5\uc131\uc744 \uc0b4\ud540\ub2e4. \ub048\uc801\ud55c \ubb3c\uc9c8\uc744 \ub354 \ub9ce\uc774 \uc4f0\ub294 \ub300\uc2e0 \ud45c\uba74\uc758 \ubbf8\uc138\ud55c \ubaa8\uc591\uacfc \uc811\ucd09\uc744 \ubc14\uafb8\ub294 \uae38\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc790\uc5f0\uc744 \uad00\ucc30\ud558\ub294 \uc77c\uc774 \uc7ac\ub8cc\uc758 \uc124\uacc4\uc640 \uc774\uc5b4\uc9c0\ub294 \ub300\ubaa9\uc774\ub2e4. \uadf8\ub7ec\ub098 \ub3d9\ubb3c\uc758 \uc6d0\ub9ac\ub97c \uc54c\uc558\ub2e4\uace0 \uac19\uc740 \uc131\ub2a5\uc758 \uc81c\ud488\uc774 \ubc14\ub85c \uc644\uc131\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc18\ubcf5 \uc0ac\uc6a9\uacfc \uba3c\uc9c0, \ud45c\uba74\uc758 \ucc28\uc774 \uac19\uc740 \uc2e4\uc81c \uc870\uac74\uc774 \ub0a8\ub294\ub2e4. \uc0dd\ubb3c\uc758 \ud2b9\uc9d5\uc5d0\uc11c \uc544\uc774\ub514\uc5b4\ub97c \uc5bb\ub294 \uc77c\uacfc \uadf8 \uc544\uc774\ub514\uc5b4\ub97c \uc548\uc815\uc801\uc778 \ubb3c\uac74\uc73c\ub85c \ub9cc\ub4dc\ub294 \uc77c \uc0ac\uc774\uc5d0\ub3c4 \ubcc4\ub3c4\uc758 \uc5f0\uad6c\uc640 \uc2dc\ud5d8\uc774 \ud544\uc694\ud558\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \ubcbd\uc5d0 \ubd99\uc740 \ub3c4\ub9c8\ubc40\ubd99\uc774\ub97c \ud45c\ud604\ud55c \uad00\ucc30 \ubd84\uc704\uae30\uc758 \uadf8\ub9bc\uc774\ub2e4. \uc2e4\uc81c \uac1c\uccb4\uc758 \uc0ac\uc9c4\uc774\ub098 \ubc1c\uac00\ub77d \ubbf8\uc138 \uad6c\uc870\ub97c \ucd2c\uc601\ud55c \ud604\ubbf8\uacbd \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc774 \uadf8\ub9bc\ub9cc\uc73c\ub85c \ud138\uc758 \uc218\uc640 \uc811\ucd09 \uba74\uc801\uc744 \ud655\uc778\ud560 \uc218\ub294 \uc5c6\ub2e4. \uba40\ub9ac\uc11c\ub294 \uc791\uc740 \ub3d9\ubb3c\uc774 \ubcbd\uc744 \uac77\uace0, \uac00\uae4c\uc6b4 \uc5f0\uad6c\uc5d0\uc11c\ub294 \ubbf8\uc138\ud55c \uad6c\uc870\uc640 \ubd84\uc790 \uc0ac\uc774\uc758 \ud798\uc774 \ub9cc\ub09c\ub2e4. \uc5b4\ub290 \ud55c\ucabd\ub9cc\uc73c\ub85c\ub294 \uc2e0\uae30\ud568\uacfc \uc6d0\ub9ac\ub97c \ud568\uaed8 \ubcf4\uae30 \uc5b4\ub835\ub2e4. \ub3c4\ub9c8\ubc40\ubd99\uc774\uc758 \ubc1c\uc740 \uc791\uc740 \uc791\uc6a9\ub3c4 \ub9ce\uc774 \ubaa8\uc774\uace0 \uc801\uc808\ud558\uac8c \uc870\uc808\ub418\uba74 \ub180\ub77c\uc6b4 \ub2a5\ub825\uc774 \ub420 \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "harvey-heart-blood-and-quantity", "title": "\ud558\ube44\uc758 \ud608\uc561\uc21c\ud658 \u2014 \uc2ec\uc7a5\uc774 \ubcf4\ub0b8 \ud53c\ub294 \uc5b4\ub514\ub85c \uac14\uc744\uae4c", "summary": "\uc2ec\uc7a5\uacfc \ud608\uad00\uc758 \uad00\ucc30, \ud608\uc561\ub7c9\uc758 \ucd94\ub860\uacfc \ud6c4\ub300\uc758 \ud604\ubbf8\uacbd\uc744 \ud1b5\ud574 \uc21c\ud658\uc758 \ub17c\uc99d\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uc0dd\uba85\uacfc \uc778\uccb4", "categories": ["science"], "url": "stories/harvey-heart-blood-and-quantity/index.html", "image": "../media/harvey-heart-blood-and-quantity.png", "alt": "17\uc138\uae30 \uc5f0\uad6c\uc790\uac00 \uc190\ubaa9\uc758 \ub9e5\ubc15\uc744 \uc0b4\ud53c\ub294 \ubaa8\uc2b5\uc744 \uadf8\ub9b0 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ud558\ube44\uc758 \ud608\uc561\uc21c\ud658 \u2014 \uc2ec\uc7a5\uc774 \ubcf4\ub0b8 \ud53c\ub294 \uc5b4\ub514\ub85c \uac14\uc744\uae4c \uad00\ucc30\uacfc \uc218\ub7c9 \ucd94\ub860, \ubcf4\uc774\uc9c0 \uc54a\uc558\ub358 \ubaa8\uc138\ud608\uad00\uae4c\uc9c0 \uc774\uc5b4\uc9c4 \uc5f0\uad6c \uc2ec\uc7a5\uacfc \ud608\uad00\uc758 \uad00\ucc30, \ud608\uc561\ub7c9\uc758 \ucd94\ub860\uacfc \ud6c4\ub300\uc758 \ud604\ubbf8\uacbd\uc744 \ud1b5\ud574 \uc21c\ud658\uc758 \ub17c\uc99d\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc0dd\uba85\uacfc \uc778\uccb4 \uacfc\ud559\uacfc \ubc1c\uacac \uac00\uc2b4\uc740 \uacc4\uc18d \ub6f0\uace0 \uc190\ubaa9\uc5d0\uc11c\ub294 \ub9e5\ubc15\uc774 \ub290\uaef4\uc9c4\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uc6c0\uc9c1\uc784\uc744 \uc548\ub2e4\uace0 \ud53c\uac00 \ubab8 \uc548\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ub2e4\ub2c8\ub294\uc9c0\uae4c\uc9c0 \uc774\ud574\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc70c\ub9ac\uc5c4 \ud558\ube44\ub294 \uad00\ucc30\uacfc \uc2e4\ud5d8, \uc591\uc744 \ub530\uc9c0\ub294 \ucd94\ub860\uc744 \ubaa8\uc544 \ud608\uc561\uc774 \uc21c\ud658\ud55c\ub2e4\ub294 \uc8fc\uc7a5\uc744 \ud3bc\ucce4\ub2e4. 1628\ub144\uc5d0 \ucd9c\ud310\ud55c \ucc45\uc740 \uadf8 \ub17c\uc99d\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc911\uc694\ud55c \uc790\ub8cc\ub2e4. \uadf8\uc758 \uc774\uc57c\uae30\ub97c \uc704\ub300\ud55c \uc0ac\ub78c\uc774 \uc815\ub2f5\uc744 \uc54c\uc544\ub9de\ud78c \uc0ac\uac74\uc73c\ub85c\ub9cc \uc77d\uc73c\uba74 \uacfc\ud559\uc758 \ud765\ubbf8\ub85c\uc6b4 \ubd80\ubd84\uc774 \uc904\uc5b4\ub4e0\ub2e4. \ubb34\uc5c7\uc744 \ubcf4\uc558\uace0 \ubb34\uc5c7\uc744 \ucd94\ub860\ud588\uc73c\uba70 \ubb34\uc5c7\uc740 \ub05d\ub0b4 \uc9c1\uc811 \ubcf4\uc9c0 \ubabb\ud588\ub294\uc9c0 \ub098\ub204\uc5b4 \ubcf4\uba74 \uc0c8\ub85c\uc6b4 \uc124\uba85\uc774 \ub9cc\ub4e4\uc5b4\uc9c0\ub294 \uacfc\uc815\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \ud558\ube44\uac00 \uc5f0\uad6c\ud55c \uc138\uacc4\uc5d0\ub294 \uc774\ubbf8 \uc2ec\uc7a5\uacfc \ud608\uad00\uc5d0 \uad00\ud55c \uc624\ub79c \uc124\uba85\uc774 \uc788\uc5c8\ub2e4. \uc0c8 \uc774\ub860\uc740 \uc544\ubb34\ub3c4 \uad00\uc2ec\uc744 \uac16\uc9c0 \uc54a\uc740 \ube48\uc790\ub9ac\uc5d0\uc11c \uc0dd\uae34 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc775\uc219\ud55c \uad8c\uc704\uc640 \uad00\ucc30\uc744 \ub2e4\uc2dc \ube44\uad50\ud558\uba74\uc11c \uc2dc\uc791\ub418\uc5c8\ub2e4. \uc624\ub7ab\ub3d9\uc548 \ubc1b\uc544\ub4e4\uc5ec\uc9c4 \ub9d0\uc774\ub77c\ub3c4 \uc2e4\uc81c \uc6c0\uc9c1\uc784\uc744 \ucda9\ubd84\ud788 \uc124\uba85\ud558\ub294\uc9c0 \ubb3c\uc5b4\uc57c \ud588\ub2e4. \uc2ec\uc7a5\uc758 \ub3d9\uc791\uc740 \ube60\ub974\uae30 \ub54c\ubb38\uc5d0 \ud55c\ub208\uc5d0 \uc774\ud574\ud558\uae30 \uc5b4\ub824\uc6e0\ub2e4. \ud558\ube44\ub294 \uc5ec\ub7ec \ub3d9\ubb3c\uacfc \uc870\uac74\uc5d0\uc11c \uc6c0\uc9c1\uc784\uc744 \uc0b4\ud53c\uba70 \ubb34\uc5c7\uc774 \uc77c\uc5b4\ub098\ub294\uc9c0 \uad6c\ubd84\ud558\ub824 \ud588\ub2e4. \uc774\ucc98\ub7fc \ubcf4\ub294 \ub300\uc0c1\uc744 \ubc14\uafb8\uace0 \ube44\uad50\ud558\ub294 \uc77c\uc774 \uc911\uc694\ud588\ub2e4. \uadf8\ub0e5 \uc624\ub798 \ubc14\ub77c\ubcf4\ub294 \uac83\uacfc \uc9c8\ubb38\uc744 \uac16\uace0 \uad00\ucc30\uc744 \uc124\uacc4\ud558\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \ud558\ube44\ub294 \uc2ec\uc7a5\uc758 \uc6c0\uc9c1\uc784\uacfc \ud608\uc561\uc758 \uc774\ub3d9\uc744 \uc5f0\uacb0\ud574 \uc124\uba85\ud588\ub2e4. \uc2ec\uc7a5\uc740 \ub2e8\uc9c0 \uc5f4\uc744 \uac00\uc9c4 \ud2b9\ubcc4\ud55c \uae30\uad00\uc73c\ub85c \ub0a8\uc9c0 \uc54a\uace0 \ud53c\ub97c \ubc00\uc5b4 \ubcf4\ub0b4\ub294 \uc6b4\ub3d9\uc758 \uc911\uc2ec\uc774 \ub41c\ub2e4. \uac00\uc2b4\uc5d0\uc11c \ub290\ub07c\ub294 \ubc15\ub3d9\uacfc \ud608\uad00\uc744 \ub530\ub77c \uc77c\uc5b4\ub098\ub294 \ubcc0\ud654\uac00 \ud558\ub098\uc758 \uc124\uba85 \uc548\uc5d0 \ub193\uc774\ub294 \uac83\uc774\ub2e4. \uc774 \uc124\uba85\uc5d0\ub294 \ubc29\ud5a5\uc774 \uc911\uc694\ud588\ub2e4. \uc5b4\ub290 \uacf3\uc5d0\uc11c \ub098\uc640 \uc5b4\ub290 \ucabd\uc73c\ub85c \uc774\ub3d9\ud558\ub294\uc9c0 \uc54c\uc544\uc57c \ubab8 \uc804\uccb4\uc758 \uacbd\ub85c\ub97c \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ud53c\uac00 \ubcf4\uc778\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc21c\ud658\uc774 \uc99d\uba85\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \uac01\uac01\uc758 \uad00\ucc30\uc774 \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ub418\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\uc5b4\uc57c \ud588\ub2e4. \ud558\ube44\uc758 \ucc45\uc740 \uc774\ub7f0 \uc5f0\uacb0\uc758 \ub17c\uc99d\uc744 \ucc28\ub840\ub85c \uc313\ub294\ub2e4. \ud558\ube44\ub294 \uc2ec\uc7a5\uc774 \ud55c \ubc88 \uc6c0\uc9c1\uc77c \ub54c \ubcf4\ub0b4\ub294 \ud53c\uc758 \uc591\uacfc \ubc18\ubcf5\ub418\ub294 \ubc15\ub3d9\uc744 \ud568\uaed8 \uc0dd\uac01\ud588\ub2e4. \ub9e4\ubc88 \uc0c8 \ud53c\uac00 \ub9cc\ub4e4\uc5b4\uc838 \ubab8\uc5d0\uc11c \ubaa8\ub450 \uc18c\ube44\ub418\uae30\ub9cc \ud55c\ub2e4\uba74, \uc2dc\uac04\uc774 \ud750\ub974\ub294 \ub3d9\uc548 \ud544\uc694\ud55c \uc591\uc774 \uc9c0\ub098\uce58\uac8c \ucee4\uc9c4\ub2e4. \ubab8\uc774 \uac10\ub2f9\ud560 \uc218 \uc788\ub294 \uc591\uc778\uc9c0 \ub530\uc9c0\ub294 \ubb38\uc81c\uac00 \uc0dd\uae34\ub2e4. \uc774 \ucd94\ub860\uc758 \ud798\uc740 \ubcf5\uc7a1\ud55c \uc218\uc2dd\ubcf4\ub2e4 \ubc18\ubcf5\uc744 \uacc4\uc0b0\ud558\ub294 \ub370 \uc788\ub2e4. \ud55c \ubc88\uc5d0\ub294 \uc791\uc544 \ubcf4\uc774\ub294 \uc591\ub3c4 \uacc4\uc18d \ub354\ud558\uba74 \ud070 \uaddc\ubaa8\uac00 \ub41c\ub2e4. \uad00\ucc30\ub9cc\uc73c\ub85c \uacbd\ub85c\uc758 \ubaa8\ub4e0 \ubd80\ubd84\uc744 \ubcf4\uc9c0 \ubabb\ud574\ub3c4 \uc5b4\ub5a4 \uc124\uba85\uc774 \uc218\ub7c9\uc801\uc73c\ub85c \uac00\ub2a5\ud55c\uc9c0 \uc2dc\ud5d8\ud560 \uc218 \uc788\ub2e4. \uc0dd\uba85 \ud604\uc0c1\uc744 \uc774\ud574\ud558\ub294 \ub370 \uacc4\uc0b0\uc774 \ub4e4\uc5b4\uc624\ub294 \uc911\uc694\ud55c \uc7a5\uba74\uc774\ub2e4. \ud558\ube44\ub294 \ud608\uad00\uc744 \uc0b4\ud53c\uace0 \ud53c\uc758 \uc774\ub3d9\uc774 \ub2ec\ub77c\uc9c0\ub294 \uc870\uac74\uc744 \ube44\uad50\ud588\ub2e4. \ud2b9\ud788 \uc815\ub9e5\uc758 \ud310\ub9c9\uacfc \ud750\ub984\uc758 \ubc29\ud5a5\uc740 \uc911\uc694\ud55c \ub2e8\uc11c\uc600\ub2e4. \ubab8\uc758 \uad6c\uc870\ub97c \uc774\ub984 \ubd99\uc5ec \uc678\uc6b0\ub294 \ub370\uc11c \ub098\uc544\uac00, \uadf8 \uad6c\uc870\uac00 \uc2e4\uc81c \uc6c0\uc9c1\uc784\uc744 \uc5b4\ub5bb\uac8c \uc81c\ud55c\ud558\ub294\uc9c0 \ubb3b\ub294 \ubc29\uc2dd\uc774\ub2e4. \ud558\ub098\uc758 \uad00\ucc30\uc774 \ubaa8\ub4e0 \uacb0\ub860\uc744 \ud63c\uc790 \ub2f4\ub2f9\ud558\uc9c0\ub294 \uc54a\uc558\ub2e4. \uc2ec\uc7a5\uc758 \uc6b4\ub3d9\uacfc \ud608\uad00\uc758 \ubc29\ud5a5, \ud53c\uc758 \uc591\uc5d0 \uad00\ud55c \uc0dd\uac01\uc774 \uc11c\ub85c\ub97c \ubcf4\uac15\ud588\ub2e4. \uacfc\ud559\uc801 \uc124\uba85\uc740 \uc778\uc0c1\uc801\uc778 \uc2e4\ud5d8 \ud55c \ubc88\ubcf4\ub2e4 \uc5ec\ub7ec \uc885\ub958\uc758 \uadfc\uac70\uac00 \uac19\uc740 \ubc29\ud5a5\uc744 \uac00\ub9ac\ud0ac \ub54c \uac15\ud574\uc9c4\ub2e4. \ud558\ube44\uc758 \ub17c\uc99d\uc740 \uc774\ub7f0 \ucd95\uc801\uc744 \uc77d\ub294 \uc7ac\ubbf8\uac00 \uc788\ub2e4. \ud558\ube44\ub294 \ud53c\uac00 \uc21c\ud658\ud55c\ub2e4\uace0 \uc8fc\uc7a5\ud588\uc9c0\ub9cc \ub3d9\ub9e5\uacfc \uc815\ub9e5 \uc0ac\uc774\uc758 \uac00\uc7a5 \uc791\uc740 \uc5f0\uacb0\uc744 \uc9c1\uc811 \ud655\uc778\ud558\uc9c0\ub294 \ubabb\ud588\ub2e4. \uc624\ub298\ub0a0 \ubaa8\uc138\ud608\uad00\uc774\ub77c\uace0 \ubd80\ub974\ub294 \ubd80\ubd84\uc774\ub2e4. \ub2f9\uc2dc\uc758 \uad00\ucc30 \ub3c4\uad6c\uc5d0\ub294 \ud55c\uacc4\uac00 \uc788\uc5c8\ub2e4. \uadf8\ub798\uc11c \uadf8\uc758 \uc124\uba85\uc5d0\ub294 \ubcf8 \uac83\uc5d0\uc11c \ucd94\ub860\ud55c \uc5f0\uacb0\uacfc \uc544\uc9c1 \ub208\uc73c\ub85c \ubcf4\uc9c0 \ubabb\ud55c \uc5f0\uacb0\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \uc774 \uc0ac\uc2e4\uc744 \uc228\uae30\uba74 \ubc1c\uacac\uc758 \ubaa8\uc2b5\uc774 \uc624\ud788\ub824 \ub2e8\uc21c\ud574\uc9c4\ub2e4. \ubaa8\ub4e0 \uad6c\uac04\uc744 \ub2e4 \ubcf8 \ub4a4\uc5d0\ub9cc \uc0c8\ub85c\uc6b4 \uc124\uba85\uc774 \uac00\ub2a5\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uc5b4\ub514\uae4c\uc9c0 \uad00\ucc30\ud588\uace0 \uc5b4\ub290 \ubd80\ubd84\uc744 \ucd94\ub860\ud588\ub294\uc9c0 \uad6c\ubd84\ud558\ub294 \uc77c\uc774 \ud544\uc694\ud558\ub2e4. \ube48\ud2c8\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc124\uba85 \uc804\uccb4\uac00 \uadfc\uac70 \uc5c6\ub2e4\ub294 \ud310\ub2e8\uc740 \uac19\uc740 \uac83\uc774 \uc544\ub2c8\ub2e4. \ud558\ube44\uac00 \uc8fd\uc740 \ub4a4\uc778 1661\ub144, \ub9d0\ud53c\uae30\ub294 \ud604\ubbf8\uacbd\uc73c\ub85c \ubbf8\uc138\ud55c \ud608\uad00\uc758 \uc5f0\uacb0\uc744 \uad00\ucc30\ud588\ub2e4. \ud55c \uc0ac\ub78c\uc774 \ub05d\ub0b4 \ubcf4\uc9c0 \ubabb\ud55c \ubd80\ubd84\uc744 \ub2e4\ub978 \uc5f0\uad6c\uc790\uc640 \uc0c8\ub85c\uc6b4 \ub3c4\uad6c\uac00 \uc774\uc5b4 \uac04 \uac83\uc774\ub2e4. \ud608\uc561\uc21c\ud658\uc758 \uc5ed\uc0ac\ub294 \ud55c \uad8c\uc758 \ucc45\uc5d0\uc11c \ub2e8\ubc88\uc5d0 \uc644\uacb0\ub418\uc9c0 \uc54a\uc558\ub2e4. \ud6c4\ub300\uc758 \ud655\uc778\uc740 \uc55e\uc120 \ucd94\ub860\uc774 \uc5b4\ub5bb\uac8c \ub2e4\ub978 \uad00\ucc30\uacfc \uc774\uc5b4\uc9c8 \uc218 \uc788\ub294\uc9c0 \ubcf4\uc5ec \uc900\ub2e4. \uc9c0\uc2dd\uc740 \uc720\uba85\ud55c \ud55c \uc0ac\ub78c\uc758 \uc5c5\uc801\uc774\uba74\uc11c \ub3d9\uc2dc\uc5d0 \uc5ec\ub7ec \uc138\ub300\uc758 \uc791\uc5c5\uc774\ub2e4. \ucc98\uc74c \uc124\uba85\uc744 \ub9cc\ub4e0 \uc0ac\ub78c\uacfc \ubcf4\uc774\uc9c0 \uc54a\ub358 \uc5f0\uacb0\uc744 \ub4dc\ub7ec\ub0b8 \uc0ac\ub78c\uc744 \ud568\uaed8 \uae30\uc5b5\ud558\uba74 \uacfc\ud559\uc758 \ubc1c\uc804\uc774 \ub354 \uad6c\uccb4\uc801\uc778 \uacfc\uc815\uc73c\ub85c \ubcf4\uc778\ub2e4. \uc624\ub298\uc758 \ub3c5\uc790\ub294 \ud608\uc561\uc774 \uc21c\ud658\ud55c\ub2e4\ub294 \ub9d0\uc744 \ub108\ubb34 \uc27d\uac8c \uc54c\uace0 \uc788\uc5b4 \uadf8\uac83\uc774 \uc65c \ud070 \uc9c8\ubb38\uc774\uc5c8\ub294\uc9c0 \ub193\uce58\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uc2ec\uc7a5\uc774 \uc6c0\uc9c1\uc778\ub2e4\ub294 \uad00\ucc30\uc5d0\uc11c \uc628\ubab8\uc744 \ub3c4\ub294 \ud750\ub984\uc5d0 \uc774\ub974\uae30\uae4c\uc9c0\ub294 \uc5ec\ub7ec \ub2e8\uacc4\uac00 \uc788\uc5c8\ub2e4. \uad6c\uc870\uc640 \ubc29\ud5a5, \ubc18\ubcf5\ub418\ub294 \uc591\uc744 \ud55c \uc124\uba85 \uc548\uc5d0 \ubaa8\uc544\uc57c \ud588\ub2e4. \ud608\uc561\uc774 \ub3cc\uc544\uc628\ub2e4\ub294 \uacbd\ub85c\ub97c \uc124\uba85\ud558\ub294 \uc77c\uacfc \uadf8 \ud53c\uac00 \ubaa8\ub4e0 \uc870\uc9c1\uc5d0\uc11c \ud558\ub294 \uc77c\uc744 \uc804\ubd80 \uc544\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \ud558\ub098\uc758 \uc911\uc694\ud55c \uc124\uba85\uc774 \uc0dd\uacbc\ub2e4\uace0 \ub4a4\uc758 \uc9c8\ubb38\ub4e4\uc774 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0c8\ub85c\uc6b4 \uc774\ub860\uc740 \uc774\ubbf8 \uc788\ub358 \uad00\ucc30\uc744 \uc815\ub9ac\ud558\uba74\uc11c \ub2e4\uc74c \uc5f0\uad6c\uac00 \ubb3c\uc744 \ubb38\uc81c\ub3c4 \ub354 \ub610\ub837\ud558\uac8c \ub9cc\ub4e0\ub2e4. \ud558\ube44\uc758 \uc0ac\ub840\uc5d0\uc11c \ubc30\uc6b8 \ub9cc\ud55c \uac83\uc740 \uc61b\uc0ac\ub78c\uc774 \ud2c0\ub838\uace0 \uc0c8\uc0ac\ub78c\uc774 \uc633\uc558\ub2e4\ub294 \ub2e8\uc21c\ud55c \uad6c\ub3c4\ubcf4\ub2e4 \ub113\ub2e4. \ub2f9\uc5f0\ud574 \ubcf4\uc774\ub294 \uc6c0\uc9c1\uc784\uc744 \ub2e4\uc2dc \ubb3b\uace0, \uad00\ucc30\uc758 \ud55c\uacc4\ub97c \ub4dc\ub7ec\ub0b4\uba70, \ubcf4\uc774\ub294 \uac83\uacfc \ucd94\ub860\ud55c \uac83\uc744 \uc5f0\uacb0\ud558\ub294 \ud0dc\ub3c4\ub2e4. \uc775\uc219\ud55c \uc190\ubaa9\uc758 \ub9e5\ubc15\uc5d0\ub3c4 \uadf8\ub807\uac8c \uc313\uc778 \uc9c0\uc2dd\uc758 \uc2dc\uac04\uc774 \ub4e4\uc5b4 \uc788\ub2e4."}, {"id": "henrietta-leavitt-star-rhythm-distance", "title": "\ud5e8\ub9ac\uc5d0\ud0c0 \ub9ac\ube57 \u2014 \ubcc4\uc758 \ubc1d\uae30\uc5d0\uc11c \uac70\ub9ac\uc758 \uc5f4\uc1e0\ub97c \ucc3e\ub2e4", "summary": "\ubcc0\uad11\uc131\uc758 \uc8fc\uae30\uc640 \ubc1d\uae30\ub97c \uc5f0\uacb0\ud55c \ubc1c\uacac\uc774 \uc5b4\ub5bb\uac8c \uba3c \uc6b0\uc8fc\uc758 \uac70\ub9ac \uce21\uc815\uc73c\ub85c \uc774\uc5b4\uc84c\ub294\uc9c0 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uacfc\ud559\uc790\uc758 \ubc1c\uacac", "categories": ["science"], "url": "stories/henrietta-leavitt-star-rhythm-distance/index.html", "image": "../media/henrietta-leavitt-star-rhythm-distance.png", "alt": "\ubcc4\uc758 \uc720\ub9ac \uc0ac\uc9c4\ud310\uacfc \ud655\ub300\uacbd\uc744 \uc0b4\ud53c\ub294 \uc5ec\uc131 \ucc9c\ubb38\ud559\uc790\uc758 \uc5f0\uad6c \uc7a5\uba74 \uc0bd\ud654", "text": "\ud5e8\ub9ac\uc5d0\ud0c0 \ub9ac\ube57 \u2014 \ubcc4\uc758 \ubc1d\uae30\uc5d0\uc11c \uac70\ub9ac\uc758 \uc5f4\uc1e0\ub97c \ucc3e\ub2e4 \uc0ac\uc9c4\ud310\uc744 \ube44\uad50\ud558\ub358 \uc77c\uc774 \uc6b0\uc8fc\uc758 \ud06c\uae30\ub97c \uc7ac\ub294 \ubc29\ubc95\uc774 \ub418\uae30\uae4c\uc9c0 \ubcc0\uad11\uc131\uc758 \uc8fc\uae30\uc640 \ubc1d\uae30\ub97c \uc5f0\uacb0\ud55c \ubc1c\uacac\uc774 \uc5b4\ub5bb\uac8c \uba3c \uc6b0\uc8fc\uc758 \uac70\ub9ac \uce21\uc815\uc73c\ub85c \uc774\uc5b4\uc84c\ub294\uc9c0 \uc77d\uc2b5\ub2c8\ub2e4. \uacfc\ud559\uc790\uc758 \ubc1c\uacac \uacfc\ud559\uacfc \ubc1c\uacac \ubc24\ud558\ub298\uc758 \ubc1d\uc740 \ubcc4\uc774 \ub354 \uac00\uae4c\uc6b4 \ubcc4\uc77c\uae4c. \uaf2d \uadf8\ub807\uc9c0\ub294 \uc54a\ub2e4. \uac00\uae4c\uc774 \uc788\ub294 \uc791\uc740 \ubd88\ube5b\ubcf4\ub2e4 \uba40\ub9ac \uc788\ub294 \uac15\ud55c \uc870\uba85\uc774 \ub354 \ubc1d\uac8c \ubcf4\uc77c \uc218 \uc788\ub2e4. \ubcc4\uc758 \ubc1d\uae30\ub9cc\uc73c\ub85c \uac70\ub9ac\ub97c \uc54c\ub824\uace0 \ud558\uba74 \uac19\uc740 \uc5b4\ub824\uc6c0\uc774 \uc0dd\uae34\ub2e4. \ud5e8\ub9ac\uc5d0\ud0c0 \ub9ac\ube57\uc740 \ubc1d\uae30\uac00 \ubcc0\ud558\ub294 \ubcc4\uc5d0\uc11c \uadf8 \ubb38\uc81c\ub97c \ud480 \uc2e4\ub9c8\ub9ac\ub97c \ucc3e\uc558\ub2e4. \uadf8\ub140\uc758 \ubc1c\uacac\uc740 \uac70\ub300\ud55c \ub9dd\uc6d0\uacbd \uc55e\uc758 \uadf9\uc801\uc778 \ud55c\uc21c\uac04\ubcf4\ub2e4 \uc5ec\ub7ec \uc2dc\uc810\uc758 \uc0ac\uc9c4\uc744 \ube44\uad50\ud558\ub294 \uafb8\uc900\ud55c \uc77c\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\ub2e4. \uc624\ud508\uc2a4\ud0dd\uc2a4 \ucc9c\ubb38\ud559 \uad50\uc7ac\uc758 \ubcc0\uad11\uc131 \uc124\uba85\uc744 \ubc14\ud0d5\uc73c\ub85c, \ubcc4\uc758 \ub9ac\ub4ec\uc774 \uc5b4\ub5bb\uac8c \uac70\ub9ac\uc758 \uc815\ubcf4\uac00 \ub418\ub294\uc9c0 \ucc28\uadfc\ucc28\uadfc \ub530\ub77c\uac00 \ubcf8\ub2e4. \uc5b4\ub5a4 \ubcc4\uc740 \uc2dc\uac04\uc774 \uc9c0\ub098\uba74 \ubc1d\uc544\uc84c\ub2e4\uac00 \uc5b4\ub450\uc6cc\uc9c4\ub2e4. \uc774\ub7f0 \ubcc4\uc744 \ubcc0\uad11\uc131\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \uc774\uc720\ub294 \uc5ec\ub7ec \uac00\uc9c0\ub2e4. \ub2e4\ub978 \ubcc4\uc774 \uc55e\uc744 \uc9c0\ub098 \uac00\ub9b4 \uc218\ub3c4 \uc788\uace0, \ubcc4 \uc790\uccb4\uac00 \ud33d\ucc3d\ud558\uace0 \uc218\ucd95\ud558\uba74\uc11c \ube5b\uc774 \ub2ec\ub77c\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \uac89\uc73c\ub85c \ube44\uc2b7\ud558\uac8c \ubc18\uc9dd\uc5ec \ubcf4\uc5ec\ub3c4 \uac19\uc740 \ud604\uc0c1\uc73c\ub85c \ub2e8\uc815\ud560 \uc218 \uc5c6\ub2e4. \ub9ac\ube57\uc758 \uc5f0\uad6c\uc640 \uc5f0\uacb0\ub418\ub294 \uc138\ud398\uc774\ub4dc \ubcc0\uad11\uc131\uc740 \uaddc\uce59\uc801\uc73c\ub85c \ub9e5\ub3d9\ud558\ub294 \ubcc4\uc758 \ubd80\ub958\ub2e4. \ud55c \ubc88 \ubc1d\uc544\uc9c0\uace0 \ub2e4\uc2dc \uac19\uc740 \uc0c1\ud0dc\ub85c \ub3cc\uc544\uc624\ub294 \ub370 \uac78\ub9ac\ub294 \uc2dc\uac04\uc744 \uc8fc\uae30\ub77c\uace0 \ud55c\ub2e4. \ubcc4\uc758 \ud55c\uc21c\uac04 \uc0ac\uc9c4\ub9cc\uc73c\ub85c\ub294 \uadf8 \ub9ac\ub4ec\uc744 \uc54c \uc218 \uc5c6\ub2e4. \uac19\uc740 \ubcc4\uc744 \ub2e4\ub978 \ub54c\uc5d0\ub3c4 \ub2e4\uc2dc \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \ub9ac\ube57\uc740 \ud558\ubc84\ub4dc\ub300\ud559 \ucc9c\ubb38\ub300\uc5d0\uc11c \uc0ac\uc9c4 \uc790\ub8cc\ub97c \uc5f0\uad6c\ud588\ub2e4. \uc720\ub9ac \uc0ac\uc9c4\ud310\uc5d0\ub294 \ud558\ub298\uc758 \ud55c\uc21c\uac04\uc774 \ub0a8\uc544 \uc788\uace0, \ub2e4\ub978 \ub0a0\uc758 \ud310\uacfc \ube44\uad50\ud558\uba74 \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0 \ucc3e\uc744 \uc218 \uc788\ub2e4. \uad00\uce21\uc758 \uc21c\uac04\uc5d0 \uc9c1\uc811 \ub9dd\uc6d0\uacbd\uc744 \ub4e4\uc5ec\ub2e4\ubcf4\ub294 \uc77c\ub9cc \ucc9c\ubb38\ud559\uc774\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uae30\ub85d\uc744 \uc77d\uace0 \ube44\uad50\ud558\ub294 \uc77c\ub3c4 \ubc1c\uacac\uc758 \uc911\uc2ec\uc5d0 \uc788\uc5c8\ub2e4. \uc0ac\uc9c4 \uc18d \uc791\uc740 \uc810\uc744 \ubcc4\ub85c \uc54c\uc544\ubcf4\uace0 \uac19\uc740 \ub300\uc0c1\uc744 \uc5ec\ub7ec \uc7a5\uc5d0\uc11c \ucd94\uc801\ud558\ub824\uba74 \uc138\uc2ec\ud55c \ub178\ub3d9\uc774 \ud544\uc694\ud558\ub2e4. \ub208\uc5d0 \uc798 \ub744\ub294 \uc7a5\uba74 \ud558\ub098\ub9cc \uace0\ub974\ub294 \uc77c\uacfc\ub294 \ub2e4\ub974\ub2e4. \ubc1d\uae30\uac00 \uc5b8\uc81c \uc62c\ub77c\uac00\uace0 \uc5b8\uc81c \ub0b4\ub824\uac00\ub294\uc9c0 \ud655\uc778\ud558\uba74\uc11c \uc2dc\uac04\uc774 \uc0ac\uc9c4\ub4e4 \uc0ac\uc774\uc5d0 \ub2e4\uc2dc \ub4e4\uc5b4\uc628\ub2e4. \uc815\uc9c0\ub41c \uc810\ub4e4\uc5d0\uc11c \uc6c0\uc9c1\uc784\uc758 \uaddc\uce59\uc744 \uaebc\ub0b4\ub294 \uc791\uc5c5\uc774\ub2e4. \ub9ac\ube57\uc740 \ub9c8\uc824\ub780\uc6b4\uc758 \ubcc4\ub4e4\uc744 \uc5f0\uad6c\ud588\ub2e4. \uc9c0\uae08 \uc6b0\ub9ac\ub294 \uadf8\uacf3\uc774 \uc740\ud558\uc218 \uc8fc\ubcc0\uc758 \ub2e4\ub978 \uc740\ud558\ub4e4\uc774\ub77c\ub294 \uac83\uc744 \uc548\ub2e4. \ub2f9\uc2dc \uadf8 \ubcc4\ub4e4\uc758 \uc815\ud655\ud55c \uac70\ub9ac\ub97c \ubaa8\ub450 \uc54c\uace0 \uc788\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub7f0\ub370 \ubc14\ub85c \uadf8 \uba40\uace0 \ubaa8\uc5ec \uc788\ub2e4\ub294 \uc870\uac74\uc774 \ube44\uad50\uc5d0 \uc720\ub9ac\ud588\ub2e4. \uc9c0\uad6c\uc5d0\uc11c \ubcf4\uba74 \ud55c \ubb34\ub9ac\uc758 \ubcc4\ub4e4\uc774 \ub300\ub7b5 \ube44\uc2b7\ud55c \uac70\ub9ac\uc5d0 \uc788\ub2e4\uace0 \uac04\uc8fc\ud560 \uc218 \uc788\ub2e4. \uc774 \ubb34\ub9ac \uc548\uc5d0\uc11c \ud55c \ubcc4\uc774 \ub2e4\ub978 \ubcc4\ubcf4\ub2e4 \ubc1d\ub2e4\uba74 \uac70\ub9ac \ucc28\uc774\ubcf4\ub2e4\ub294 \ubcc4 \uc790\uccb4\uc758 \ube5b \ucc28\uc774\ub97c \uc0b4\ud544 \uc218 \uc788\uac8c \ub41c\ub2e4. \uc800 \uba40\ub9ac \ub098\ub780\ud788 \ub193\uc778 \uc804\ub4f1\ub4e4\uc744 \ube44\uad50\ud558\ub294 \uac83\uacfc \ube44\uc2b7\ud558\ub2e4. \uac19\uc740 \uc870\uac74\uc744 \uace8\ub77c \ube44\uad50\ud558\ub294 \uc77c\uc774 \ubb38\uc81c\ub97c \ub2e8\uc21c\ud558\uac8c \ub9cc\ub4e0\ub2e4. \uadf8\ub140\uac00 \ucc3e\uc544\ub0b8 \ud575\uc2ec\uc740 \uc138\ud398\uc774\ub4dc \ubcc0\uad11\uc131\uc758 \uc8fc\uae30\uc640 \ubc1d\uae30\uac00 \uc5f0\uacb0\ub41c\ub2e4\ub294 \uc0ac\uc2e4\uc774\ub2e4. \ubc1d\uc544\uc84c\ub2e4 \uc5b4\ub450\uc6cc\uc9c0\ub294 \ub370 \ub354 \uc624\ub79c \uc2dc\uac04\uc774 \uac78\ub9ac\ub294 \ubcc4\uc77c\uc218\ub85d \ubcc4 \uc790\uccb4\uc758 \ubc1d\uae30\uac00 \ub354 \ucef8\ub2e4. \uc544\ubb34\ub807\uac8c\ub098 \ubcc0\ud558\ub294 \uac83 \uac19\ub358 \uc810\ub4e4 \uc0ac\uc774\uc5d0 \uc77c\uc815\ud55c \uad00\uacc4\uac00 \ub098\ud0c0\ub09c \uac83\uc774\ub2e4. \uc774\ub97c \uc8fc\uae30\uc640 \uad11\ub3c4\uc758 \uad00\uacc4\ub77c\uace0 \ubd80\ub978\ub2e4. \uad11\ub3c4\ub294 \ubcc4\uc774 \uc2e4\uc81c\ub85c \ub0b4\ub294 \ube5b\uc758 \uc591\uc744 \uac00\ub9ac\ud0a8\ub2e4. \uc6b0\ub9ac \ub208\uc774\ub098 \uc0ac\uc9c4\uc5d0\uc11c \ubcf4\uc774\ub294 \ubc1d\uae30\uc640 \uad6c\ubcc4\ud558\uae30 \uc704\ud574 \ud544\uc694\ud55c \ub9d0\uc774\ub2e4. \uc911\uc694\ud55c \ubc1c\uacac\uc740 \ub2e8\uc21c\ud788 \uc624\ub798 \ubc18\uc9dd\uc774\uba74 \uba40\ub2e4\ub294 \uacb0\ub860\uc774 \uc544\ub2c8\ub2e4. \uba3c\uc800 \ub9ac\ub4ec\uc5d0\uc11c \ubcc4 \uc790\uccb4\uc758 \ube5b\uc744 \ucd94\uc815\ud560 \uc218 \uc788\ub294 \uae38\uc774 \uc5f4\ub9b0 \uac83\uc774\ub2e4. \uac19\uc740 \uc804\uad6c\uac00 \uac00\uae4c\uc774\uc5d0 \uc788\uc73c\uba74 \ubc1d\uac8c \ubcf4\uc774\uace0 \uba40\uc5b4\uc9c0\uba74 \uc5b4\ub450\uc6cc \ubcf4\uc778\ub2e4. \ubcc4 \uc790\uccb4\uc758 \ubc1d\uae30\ub97c \uc54c \uc218 \uc788\ub2e4\uba74 \uc6b0\ub9ac\uc5d0\uac8c \uc5bc\ub9c8\ub098 \uc57d\ud574\uc838 \ubcf4\uc774\ub294\uc9c0 \ube44\uad50\ud574 \uac70\ub9ac\ub97c \uacc4\uc0b0\ud560 \uc218 \uc788\ub2e4. \ubb38\uc81c\ub294 \ubcc4\ub9c8\ub2e4 \uc6d0\ub798 \ubc1d\uae30\uac00 \ub2e4\ub978\ub370 \uadf8 \uc804\uad6c\uc758 \uc885\ub958\ub97c \uc5b4\ub5bb\uac8c \uc544\ub290\ub0d0\ub294 \ub370 \uc788\uc5c8\ub2e4. \uc138\ud398\uc774\ub4dc\ub294 \ubcc0\ud558\ub294 \uc8fc\uae30\uac00 \uadf8 \uc9c8\ubb38\uc5d0 \ub2f5\ud560 \uc2e4\ub9c8\ub9ac\uac00 \ub41c\ub2e4. \uc8fc\uae30\ub97c \uc7ac\uace0, \uad00\uacc4\uc5d0 \ub530\ub77c \uc2e4\uc81c \ubc1d\uae30\ub97c \ucd94\uc815\ud55c \ub4a4, \uad00\uce21\ud55c \ubc1d\uae30\uc640 \ube44\uad50\ud55c\ub2e4. \ubcc4 \ud558\ub098\uc758 \ube5b\uc744 \uc7ac\ub294 \uc77c\uc774 \uc2dc\uacc4\ub85c \uc2dc\uac04\uc744 \uc7ac\ub294 \uc77c\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uac70\ub9ac\uc5d0 \uad00\ud55c \uc815\ubcf4\uac00 \uc704\uce58\uc758 \uc0ac\uc9c4\uc5d0\ub9cc \ub4e4\uc5b4 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub358 \uc148\uc774\ub2e4. \uc5ec\uae30\uc5d0\uc11c \ud55c \ub2e8\uacc4\ub97c \ub354 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ub9ac\ube57\uc740 \uc8fc\uae30\uc640 \ubc1d\uae30\uc758 \uad00\uacc4\ub97c \ucc3e\uc544\ub0c8\uc9c0\ub9cc, \ucc98\uc74c\ubd80\ud130 \uadf8 \uad00\uacc4\uc5d0 \uc815\ud655\ud55c \uac70\ub9ac \uc22b\uc790\ub97c \ubaa8\ub450 \ub9e4\uaca8 \ub193\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \uae30\uc900\uc744 \uc815\ud558\ub824\uba74 \ub2e4\ub978 \ubc29\ubc95\uc73c\ub85c \uac70\ub9ac\uac00 \uc54c\ub824\uc9c4 \ubcc4\ub4e4\uc744 \uc774\uc6a9\ud574 \ub208\uae08\uc744 \ub9de\ucd94\ub294 \uc791\uc5c5\uc774 \ud544\uc694\ud588\ub2e4. \uc774 \ubcf4\uc815\uc5d0\ub294 \ub2e4\ub978 \ucc9c\ubb38\ud559\uc790\ub4e4\uc758 \uc5f0\uad6c\ub3c4 \uc774\uc5b4\uc84c\ub2e4. \uad00\uacc4\uc758 \ubc1c\uacac\uacfc \uc2e4\uc81c \uac70\ub9ac\ub97c \uc0b0\ucd9c\ud558\ub294 \ub3c4\uad6c\uc758 \uc644\uc131\uc740 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc9c0\ub9cc \uac19\uc740 \uc0ac\uac74\uc774 \uc544\ub2c8\ub2e4. \ub9ac\ube57\uc774 \uc6b0\uc8fc\uc758 \ud06c\uae30\ub97c \ud63c\uc790 \ucd5c\uc885 \uacc4\uc0b0\ud588\ub2e4\ub294 \uc2dd\uc73c\ub85c \uc18c\uac1c\ud558\uba74, \uc815\uc791 \uadf8\ub140\uac00 \uc815\ud655\ud788 \ubb34\uc5c7\uc744 \ubc1c\uacac\ud588\ub294\uc9c0 \ud750\ub824\uc9c4\ub2e4. \uacf5\ub85c\ub294 \ud06c\uac8c \uafb8\ubc00\uc218\ub85d \ub354 \ubd84\uba85\ud574\uc9c0\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc138\ud398\uc774\ub4dc\uc758 \uc8fc\uae30\ub97c \uc77d\ub294 \ubc29\ubc95\uc740 \ud6e8\uc52c \uba3c \uacf3\uc73c\ub85c \uc801\uc6a9\ub418\uc5c8\ub2e4. \ub4a4\uc5d0 \ud5c8\ube14\uc744 \ube44\ub86f\ud55c \ucc9c\ubb38\ud559\uc790\ub4e4\uc774 \ub2e4\ub978 \uc740\ud558\uc758 \ubcc4\uc744 \uc5f0\uad6c\ud560 \ub54c\uc5d0\ub3c4 \uc911\uc694\ud55c \uac70\ub9ac\uc758 \ub3c4\uad6c\uac00 \ub41c\ub2e4. \ubcc4 \ud558\ub098\uc758 \ub9ac\ub4ec\uc744 \uc77d\ub294 \uc77c\uc774 \uc740\ud558\uc218 \ubc16\uc758 \uc138\uacc4\ub97c \uc774\ud574\ud558\ub294 \uc5f0\uad6c\ub85c \uc774\uc5b4\uc9c4 \uac83\uc774\ub2e4. \uc774 \uacfc\uc815\uc5d0\ub3c4 \ub9dd\uc6d0\uacbd\uc758 \uc131\ub2a5\uacfc \uad00\uce21, \ubc1d\uae30 \uce21\uc815\uacfc \ubcf4\uc815\uc774\ub77c\ub294 \uc5ec\ub7ec \uc870\uac74\uc774 \ud544\uc694\ud588\ub2e4. \ud55c \uac00\uc9c0 \ubc95\uce59\ub9cc \uc190\uc5d0 \ub123\uc73c\uba74 \uc6b0\uc8fc\uac00 \uc790\ub3d9\uc73c\ub85c \uc9c0\ub3c4\uc5d0 \uadf8\ub824\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub798\ub3c4 \ub9ac\ube57\uc758 \uad00\uacc4\uac00 \uc5c6\uc5c8\ub2e4\uba74 \uadf8 \uc0ac\ub2e4\ub9ac\uc758 \uc911\uc694\ud55c \ubc1c\ud310 \ud558\ub098\uac00 \ube44\uc5c8\uc744 \uac83\uc774\ub2e4. \uba40\ub9ac \uc788\ub294 \ub300\uc0c1\uc744 \ube44\uad50\ud560 \uacf5\ud1b5 \uae30\uc900\uc774 \uc0dd\uacbc\ub2e4\ub294 \uc758\ubbf8\uac00 \ud06c\ub2e4. \uad50\uc7ac\ub294 \ub9ac\ube57\uc774 \ub0ae\uc740 \uc784\uae08\uc73c\ub85c \ucc9c\ubb38\ub300\uc758 \uc5f0\uad6c\ub97c \ub3d5\ub358 \uc5ec\uc131\ub4e4 \uac00\uc6b4\ub370 \ud55c \uc0ac\ub78c\uc774\uc5c8\ub2e4\ub294 \uc810\ub3c4 \uc9da\ub294\ub2e4. \uadf8\ub4e4\uc758 \uc77c\uc744 \ub2e8\uc21c\ud55c \uc7a1\ubb34\ub85c\ub9cc \uc0dd\uac01\ud558\uba74 \ubc1c\uacac\uc744 \uac00\ub2a5\ud558\uac8c \ud55c \uc9c0\uc801 \ub178\ub3d9\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \ubd84\ub958\ud558\uace0 \ube44\uad50\ud558\uba70 \uc2e0\ub8b0\ud560 \uc218 \uc788\ub294 \uc790\ub8cc\ub97c \ub9cc\ub4dc\ub294 \uc77c\uc5d0\ub3c4 \ud310\ub2e8\uacfc \uae30\uc220\uc774 \ud544\uc694\ud558\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc81c\ub3c4 \uc18d\uc758 \uc5b4\ub824\uc6c0\uc744 \uac10\ub3d9\uc801\uc778 \uc131\uacf5\ub2f4\uc758 \uc7a5\uc2dd\uc73c\ub85c\ub9cc \ub458 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub204\uac00 \uad00\uce21 \uae30\ud68c\ub97c \uc5bb\uace0 \ub204\uac00 \uc790\ub8cc\ub97c \ubd84\uc11d\ud558\uba70 \ub204\uad6c\uc758 \uc774\ub984\uc774 \uacb0\uacfc\uc5d0 \ub0a8\ub294\uc9c0\ub294 \uacfc\ud559\uc774 \uc774\ub8e8\uc5b4\uc9c0\ub294 \uc2e4\uc81c \uc870\uac74\uc774\ub2e4. \ub9ac\ube57\uc758 \uc774\uc57c\uae30\ub294 \ubc1c\uacac\uc758 \uc6d0\ub9ac\uc640 \uadf8 \uc77c\uc744 \uc218\ud589\ud55c \uc0ac\ub78c\uc758 \uc790\ub9ac\ub97c \ud568\uaed8 \ubcf4\uac8c \ud55c\ub2e4. \uc0ac\uc9c4 \ud55c \uc7a5\uc5d0\uc11c\ub294 \uc791\uc740 \uc810\uc774\uc9c0\ub9cc, \uc5ec\ub7ec \uc7a5\uc744 \uc2dc\uac04\uc21c\uc73c\ub85c \ub193\uc73c\uba74 \ubcc4\uc740 \uc790\uae30 \ub9ac\ub4ec\uc744 \ub4dc\ub7ec\ub0b8\ub2e4. \ub9ac\ube57\uc740 \uadf8 \ub9ac\ub4ec\uc744 \ub2e4\ub978 \ubcc4\uacfc \ube44\uad50\ud574 \uac70\ub9ac\uc758 \uc5f4\uc1e0\ub85c \ubc14\uafb8\uc5c8\ub2e4. \ud2b9\ubcc4\ud55c \ub300\uc0c1\uc744 \ucc3e\ub294 \uac83\ub9cc\ud07c \uac19\uc740 \ub300\uc0c1\uc744 \uafb8\uc900\ud788 \ub2e4\uc2dc \ubcf4\ub294 \uc77c\uc774 \uc911\uc694\ud558\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c\ub824 \uc900\ub2e4. \uc624\ub298 \ubc24 \ubcc4\uc774 \ubc18\uc9dd\uc778\ub2e4\uace0 \uadf8 \ubaa8\ub450\ub97c \uc138\ud398\uc774\ub4dc\ub77c\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774 \uc774\uc57c\uae30\uac00 \ub0a8\uae30\ub294 \uc7ac\ubbf8\ub294 \ub354 \ucc9c\ucc9c\ud788 \uc628\ub2e4. \uc544\uc8fc \uba3c \uac70\ub9ac\ub97c \uc7ac\ub294 \uc815\ubcf4\uac00 \ubcc4\uc758 \ubc1d\uace0 \uc5b4\ub450\uc6cc\uc9c0\ub294 \uc2dc\uac04\uc5d0 \uc228\uc5b4 \uc788\uc5c8\ub2e4\ub294 \uac83. \uc6b0\ub9ac\uac00 \ubc24\ud558\ub298\uc744 \uc77d\ub294 \ubc29\ubc95\uc740 \ube5b\uc758 \uc591\ubfd0 \uc544\ub2c8\ub77c \uadf8 \ube5b\uc744 \uc5bc\ub9c8\ub098 \uc624\ub798 \uc0b4\ud3b4\ubcf4\uc558\ub294\uc9c0\uc5d0 \ub530\ub77c\uc11c\ub3c4 \ub2ec\ub77c\uc84c\ub2e4."}, {"id": "hooke-cork-small-rooms", "title": "\ub85c\ubc84\ud2b8 \ud6c5 \u2014 \ucf54\ub974\ud06c \uc18d\uc5d0\uc11c \uc791\uc740 \ubc29\uc744 \ubcf4\ub2e4", "summary": "\ud6c5\uc758 \uc2e4\uc81c \ucf54\ub974\ud06c \ub3c4\ud310\uacfc \uc6d0\ubb38\uc744 \ud1b5\ud574 \uc138\ud3ec\ub77c\ub294 \uc774\ub984, \uc7ac\ub8cc\uc758 \uc131\uc9c8\uc744 \uc774\ud574\ud558\ub824\ub294 \uad00\ucc30\uacfc \ucd9c\ud310\uc758 \uc758\ubbf8\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uacfc\ud559\uc790\uc758 \ubc1c\uacac", "categories": ["science"], "url": "stories/hooke-cork-small-rooms/index.html", "image": "../media/hooke-cork-small-rooms.png", "alt": "1665\ub144 \ub9c8\uc774\ud06c\ub85c\uadf8\ub77c\ud53c\uc544 \ub3c4\ud310 XI. \uc704\ucabd\uc740 \ucf54\ub974\ud06c\uc758 \uce78 \uad6c\uc870, \uc544\ub798\ucabd\uc740 \ubcc4\ub3c4\uc758 \uc2dd\ubb3c \uadf8\ub9bc", "text": "\ub85c\ubc84\ud2b8 \ud6c5 \u2014 \ucf54\ub974\ud06c \uc18d\uc5d0\uc11c \uc791\uc740 \ubc29\uc744 \ubcf4\ub2e4 1665\ub144 \u300e\ub9c8\uc774\ud06c\ub85c\uadf8\ub77c\ud53c\uc544\u300f\uc640 \ub208\uc5d0 \ubcf4\uc774\ub294 \uc138\uacc4\uc758 \ud655\uc7a5 \ud6c5\uc758 \uc2e4\uc81c \ucf54\ub974\ud06c \ub3c4\ud310\uacfc \uc6d0\ubb38\uc744 \ud1b5\ud574 \uc138\ud3ec\ub77c\ub294 \uc774\ub984, \uc7ac\ub8cc\uc758 \uc131\uc9c8\uc744 \uc774\ud574\ud558\ub824\ub294 \uad00\ucc30\uacfc \ucd9c\ud310\uc758 \uc758\ubbf8\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uacfc\ud559\uc790\uc758 \ubc1c\uacac \uacfc\ud559\uacfc \ubc1c\uacac \ucf54\ub974\ud06c\ub97c \uc544\uc8fc \uc587\uac8c \uc798\ub77c \ub4e4\uc5ec\ub2e4\ubcf4\ub2c8 \uc791\uc740 \ubc29\ub4e4\uc774 \uc774\uc5b4\uc838 \uc788\uc5c8\ub2e4. \ubcd1\ub9c8\uac1c\ub85c \uce5c\uc219\ud55c \uc7ac\ub8cc\uac00 \uc804\ud600 \ub2e4\ub978 \ud48d\uacbd\uc744 \ubcf4\uc5ec \uc900 \uac83\uc774\ub2e4. \ub85c\ubc84\ud2b8 \ud6c5\uc740 \uc774 \uce78\ub4e4\uc744 \ubcf4\uace0 \ubc29\uc744 \ub73b\ud558\ub294 \uc774\ub984\uc744 \ub5a0\uc62c\ub838\ub2e4. \uc624\ub298\uc758 \uc138\ud3ec\ub77c\ub294 \ub9d0\uc740 \uadf8 \uad00\ucc30\uacfc \uc5f0\uacb0\ub41c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \ud604\ub300 \uad50\uacfc\uc11c\uac00 \uc0c8\ub85c \uc0c1\uc0c1\ud55c \uadf8\ub9bc\uc774 \uc544\ub2c8\ub2e4. 1665\ub144 \ucd9c\uac04\ub41c \u300e\ub9c8\uc774\ud06c\ub85c\uadf8\ub77c\ud53c\uc544\u300f\uc758 \ub3c4\ud310 11\uc774\ub2e4. \uc704\ucabd \uc6d0 \uc548\uc5d0\ub294 \ucf54\ub974\ud06c\uc758 \uce78\uc774, \uc544\ub798\uc5d0\ub294 \ub2e4\ub978 \uad00\ucc30 \ub300\uc0c1\uc778 \uc2dd\ubb3c\uc758 \uac00\uc9c0\uc640 \uc78e\uc774 \ub2f4\uaca8 \uc788\ub2e4. \uc791\uc740 \uac83\uc744 \ud06c\uac8c \ubcf4\uac8c \ub41c \uc2dc\ub300\ub294 \ub208\uc73c\ub85c \ubcf8 \uac83\uc744 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ubcf4\uc5ec \uc8fc\ub294 \ubc29\uc2dd\ub3c4 \ubc14\uafb8\uc5c8\ub2e4. \ub9e8\ub208\uc73c\ub85c \ub9e4\ub048\ud574 \ubcf4\uc774\ub294 \ud45c\uba74\ub3c4 \ud655\ub300\ud558\uba74 \ub2e4\ub978 \uad6c\uc870\ub97c \ub4dc\ub7ec\ub0bc \uc218 \uc788\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4\uace0 \uadf8\uacf3\uc5d0 \uc544\ubb34\uac83\ub3c4 \uc5c6\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud604\ubbf8\uacbd\uc740 \uba3c \uacf3\uc744 \uac00\uae4c\uc774 \ubcf4\ub358 \ub9dd\uc6d0\uacbd\uacfc\ub294 \ub2e4\ub978 \ubc29\ud5a5\uc73c\ub85c \uc0ac\ub78c\uc758 \uc2dc\uc57c\ub97c \ub113\ud614\ub2e4. \uc0c8\ub85c\uc6b4 \ub3c4\uad6c\ub97c \uc190\uc5d0 \ub123\uc5c8\ub2e4\uace0 \ubaa8\ub4e0 \uc0c1\uc774 \uace7\ubc14\ub85c \ubbff\uc744 \ub9cc\ud574\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ube5b\uc744 \ube44\ucd94\uace0 \ucd08\uc810\uc744 \ub9de\ucd94\uba70 \uc587\uc740 \uc2dc\ub8cc\ub97c \uc900\ube44\ud574\uc57c \ud588\ub2e4. \uc791\uc740 \uc138\uacc4\uc5d0 \uc811\uadfc\ud558\ub294 \uc77c\uc5d0\ub294 \ub3c4\uad6c\ubfd0 \uc544\ub2c8\ub77c \ub2e4\ub8e8\ub294 \uae30\uc220\ub3c4 \ud544\uc694\ud588\ub2e4. \ud6c5\uc740 \uc5ec\ub7ec \ub80c\uc988\ub97c \uc0ac\uc6a9\ud558\ub294 \ubcf5\ud569\ud604\ubbf8\uacbd\uc73c\ub85c \uad00\ucc30\ud588\ub2e4. \u300e\ub9c8\uc774\ud06c\ub85c\uadf8\ub77c\ud53c\uc544\u300f\uc5d0\ub294 \uad00\ucc30\ud55c \uc0ac\ubb3c\ubfd0 \uc544\ub2c8\ub77c \uc0ac\uc6a9\ud55c \ub3c4\uad6c\uc758 \uc124\uba85\ub3c4 \ub2f4\uacbc\ub2e4. \ubb34\uc5c7\uc744 \ubcf4\uc558\ub294\uc9c0\uc640 \ud568\uaed8 \uc5b4\ub5bb\uac8c \ubcfc \uc218 \uc788\uc5c8\ub294\uc9c0 \uc804\ud558\ub824 \ud588\ub2e4. \ub80c\uc988\uac00 \uc5ec\ub7ec \uac1c\ub77c\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \ub2f9\uc2dc\uc758 \ubaa8\ub4e0 \ub2e8\uc77c \ub80c\uc988\ubcf4\ub2e4 \ub354 \uc120\uba85\ud588\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc720\ub9ac\uc758 \ud488\uc9c8\uacfc \uac00\uacf5, \ube5b\uc758 \uc870\uac74\uc774 \uc911\uc694\ud588\ub2e4. \uae30\uc220\uc758 \uc5ed\uc0ac\ub97c \ubd80\ud488 \uc218\uac00 \ub9ce\uc544\uc9c0\ub294 \ub2e8\uc21c\ud55c \uc21c\uc11c\ub85c\ub9cc \ubcf4\uba74 \uc2e4\uc81c \uc131\ub2a5\uc758 \ucc28\uc774\ub97c \ub193\uce5c\ub2e4. \ub450\uaebc\uc6b4 \ub369\uc5b4\ub9ac \uadf8\ub300\ub85c\ubcf4\ub2e4 \uc587\uc740 \ubd80\ubd84\uc744 \uc0b4\ud53c\uba74 \ub0b4\ubd80\uc758 \uce78 \uad6c\uc870\ub97c \ubcfc \uc218 \uc788\uc5c8\ub2e4. \ud6c5\uc758 \uad00\ucc30\uc5d0\ub294 \ubb34\uc5c7\uc744 \ubcfc\uc9c0 \uace0\ub974\ub294 \uc77c\uacfc \ubcf4\uc774\ub3c4\ub85d \uc900\ube44\ud558\ub294 \uc77c\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \ub3c4\uad6c\ub97c \ub208\uc5d0 \ub304 \uc21c\uac04\uc5d0\ub9cc \ubc1c\uacac\uc774 \uc77c\uc5b4\ub098\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ucf54\ub974\ud06c\uc758 \uce78\ub4e4\uc740 \ubc8c\uc9d1\uacfc\ub3c4 \ub2ee\uc544 \ubcf4\uc600\ub2e4. \uc775\uc219\ud55c \ubaa8\uc591\uacfc \ube44\uad50\ud558\ub294 \ub9d0\uc740 \ub0af\uc120 \uad00\ucc30\uc744 \ub3c5\uc790\uc5d0\uac8c \uc804\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub418\uc5c8\ub2e4. \uc791\uc740 \uc138\uacc4\ub97c \uc774\ud574\ud558\ub824\uace0 \uc774\ubbf8 \uc544\ub294 \uc0ac\ubb3c\uc758 \uc774\ub984\uacfc \uc774\ubbf8\uc9c0\ub97c \ube4c\ub824\uc628 \uc148\uc774\ub2e4. \ud6c5\uc774 \ubcf8 \ucf54\ub974\ud06c\ub294 \uc0b4\uc544 \uc6c0\uc9c1\uc774\ub294 \uc138\ud3ec\uc758 \ub0b4\ubd80\uac00 \uac00\ub4dd\ud55c \ud45c\ubcf8\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc8fd\uc740 \uc870\uc9c1\uc5d0 \ub0a8\uc740 \uc138\ud3ec\ubcbd\uc758 \uad6c\uc870\ub97c \uc0b4\ud3c8\uae30 \ub54c\ubb38\uc5d0 \ube44\uc5b4 \uc788\ub294 \ubc29\ucc98\ub7fc \ubcf4\uc600\ub2e4. \uadf8\uac00 \ubd99\uc778 \uc774\ub984\uc740 \uad00\ucc30\ud55c \ubaa8\uc2b5\uacfc \uc798 \ub9de\uc558\ub2e4. \ud558\uc9c0\ub9cc \uc624\ub298\ub0a0 \uc138\ud3ec\ub97c \uadf8 \ube48\uce78\uc73c\ub85c\ub9cc \uc0dd\uac01\ud558\uba74 \uace4\ub780\ud558\ub2e4. \uc0b4\uc544 \uc788\ub294 \uc138\ud3ec\uc5d0\ub294 \uc5ec\ub7ec \ud65c\ub3d9\uacfc \uad6c\uc870\uac00 \uc788\ub2e4. \uc774\ub984\uc774 \uc2dc\uc791\ub41c \uc7a5\uba74\uacfc \ub098\uc911\uc5d0 \uadf8 \uc774\ub984\uc73c\ub85c \uc774\ud574\ud558\uac8c \ub41c \ub0b4\uc6a9 \uc0ac\uc774\uc5d0\ub294 \ub354 \ub9ce\uc740 \uc5f0\uad6c\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \uc138\ud3ec\ub77c\ub294 \ub9d0\uc774 \ub4f1\uc7a5\ud588\ub2e4\uace0 \ud604\ub300 \uc0dd\ubb3c\ud559\uc758 \uc774\ub860\uc774 \uadf8\ub54c \uc644\uc131\ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. \ud6c5\uc774 \ubcf8 \ucf54\ub974\ud06c\uc640 \uc624\ub298\ub0a0 \uc124\uba85\ud558\ub294 \uc0dd\uba85\uc758 \uae30\ubcf8 \ub2e8\uc704 \uc0ac\uc774\uc5d0\ub294 \uc0c8\ub85c\uc6b4 \ud45c\ubcf8, \ub3c4\uad6c\uc640 \uc5f0\uad6c\uc790\ub4e4\uc758 \uc791\uc5c5\uc774 \uc774\uc5b4\uc84c\ub2e4. \uacfc\uac70\uc758 \uacfc\ud559\uc790\uc5d0\uac8c \ud6c4\ub300\uc758 \uc9c0\uc2dd\uc744 \ubaa8\ub450 \ubbf8\ub9ac \uc54c\uc558\ub358 \uc0ac\ub78c\ucc98\ub7fc \uc5ed\ud560\uc744 \uc8fc\uba74 \uc2e4\uc81c\uc758 \ubc1c\uacac\uc774 \ud750\ub824\uc9c4\ub2e4. \uadf8\uac00 \ud655\uc2e4\ud788 \ubcf8 \uac83\uacfc \uc544\uc9c1 \ubab0\ub790\ub358 \uac83\uc744 \uad6c\ubcc4\ud560 \ub54c \uc791\uc740 \uad00\ucc30\uc774 \uc5bc\ub9c8\ub098 \ud070 \ucd9c\ubc1c\uc810\uc774\uc5c8\ub294\uc9c0\ub3c4 \ub354 \uc798 \ubcf4\uc778\ub2e4. \ud604\ubbf8\uacbd\uc5d0 \uc5bc\uad74\uc744 \ub300\uc9c0 \uc54a\uc740 \ub3c5\uc790\ub3c4 \ucc45\uc758 \ub3c4\ud310\uc73c\ub85c \uadf8 \uad6c\uc870\ub97c \ub9cc\ub0a0 \uc218 \uc788\uc5c8\ub2e4. \uadf8\ub9bc\uacfc \uae00\uc740 \ud55c \uc0ac\ub78c\uc758 \uad00\ucc30\uc744 \ub2e4\ub978 \uc0ac\ub78c\uacfc \ub098\ub204\ub294 \ubc29\ubc95\uc774\uc5c8\ub2e4. \uc0c8\ub85c\uc6b4 \uc138\uacc4\uac00 \uac1c\uc778\uc758 \uc2e0\uae30\ud55c \uacbd\ud5d8\uc73c\ub85c\ub9cc \uba38\ubb3c\uc9c0 \uc54a\uac8c \ud588\ub2e4. \ubb3c\ub860 \ub3c4\ud310\uc740 \ud604\ubbf8\uacbd \uc18d \uc0c1\uc744 \uadf8\ub300\ub85c \ucc0d\uc740 \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \uad00\ucc30\ud55c \uac83\uc744 \uace8\ub77c \uc120\uc73c\ub85c \ud45c\ud604\ud55c \uadf8\ub9bc\uc774\ub2e4. \uadf8\ub9bc\uc744 \ubcf4\ub294 \uc0ac\ub78c\ub3c4 \uc5b4\ub514\uae4c\uc9c0\uac00 \uad00\ucc30\uacfc \ud45c\ud604\uc778\uc9c0 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc815\uad50\ud55c \ucd9c\ud310\uc740 \uac80\ud1a0\uc640 \uc0c8\ub85c\uc6b4 \uc9c8\ubb38\uc744 \uc774\uc5b4 \uc8fc\ub294 \ub2e4\ub9ac\uc600\ub2e4. \uac19\uc740 \uc2dc\ub300\uc758 \uc548\ud1a0\ub2c8 \ud310 \ub808\uc774\uc6b0\uc5d4\ud6c5\uc740 \ub2e8\uc77c \ub80c\uc988\ub97c \uc0ac\uc6a9\ud55c \uc791\uc740 \ud604\ubbf8\uacbd\uc73c\ub85c \ubbf8\uc0dd\ubb3c\uc744 \uad00\ucc30\ud588\ub2e4. \uad00\ucc30 \uacb0\uacfc\ub294 \ub7f0\ub358 \uc655\ub9bd\ud559\ud68c\uc5d0 \ubcf4\ub0b8 \ud3b8\uc9c0\ub85c \uc804\ud574\uc84c\ub2e4. \ub3c4\uad6c\uc758 \ubaa8\uc591\uacfc \ucd9c\ud310 \ubc29\uc2dd\uc740 \ub2ec\ub790\uc9c0\ub9cc \uae30\ub85d\uacfc \uacf5\uc720\uac00 \uc911\uc694\ud588\ub2e4. \uc774\ub4e4\uc744 \ud604\ubbf8\uacbd\uc758 \ub2e8 \ud55c \uba85\uc758 \ubc1c\uba85\uc790\ub85c \uc138\uc6b0\uae30\ub294 \uc5b4\ub835\ub2e4. \ub80c\uc988\ub97c \ub9cc\ub4e4\uace0 \ub3c4\uad6c\ub97c \ubc1c\uc804\uc2dc\ud0a8 \uc0ac\ub78c\ub4e4\uc740 \uc55e\uc11c\ub3c4 \uc788\uc5c8\ub2e4. \uc798 \ub0a8\uc740 \uad00\ucc30\uacfc \ud655\uc778\uc758 \uae30\ub85d \ub355\ubd84\uc5d0 \uc5b4\ub5a4 \ubc1c\uacac\uc774 \ub110\ub9ac \uc54c\ub824\uc9c0\ub294\uac00\ub3c4 \uacfc\ud559\uc0ac\uc758 \uc77c\ubd80\ub2e4. \ud6c5\uc740 \uce78\uc744 \ubcf4\uace0 \ubaa8\uc591\uc774 \uc2e0\uae30\ud558\ub2e4\ub294 \ub370\uc11c \uba48\ucd94\uc9c0 \uc54a\uc558\ub2e4. \uc65c \ucf54\ub974\ud06c\uac00 \uac00\ubcbc\uc6b4\uc9c0, \uc65c \ubb3c\uc5d0 \uc798 \ub728\ub294\uc9c0, \ub20c\ub838\ub2e4\uac00 \ub2e4\uc2dc \ubd80\ud480\ub824\ub294 \uc131\uc9c8\uc740 \uc5b4\ub5bb\uac8c \uc124\uba85\ud560\uc9c0 \ubb3c\uc5c8\ub2e4. \uc6d0\ubb38\uc5d0\ub294 \uc774\ub7f0 \uc775\uc219\ud55c \ubb3c\uc131\uc5d0 \ub300\ud55c \uc0dd\uac01\uc774 \uc774\uc5b4\uc9c4\ub2e4. \uadf8\ub294 \uc791\uc740 \ubc29\uacfc \uacf5\uae30\ub97c \ucf54\ub974\ud06c\uc758 \uac00\ubcbc\uc6c0\uacfc \ud0c4\uc131\uc5d0 \uc5f0\uacb0\ud588\ub2e4. \ub2f9\uc2dc\uc758 \ud574\uc11d\uc744 \uc624\ub298\uc758 \uc7ac\ub8cc \uacfc\ud559 \uc804\uccb4\uc640 \uac19\ub2e4\uace0 \ubcfc \uc218\ub294 \uc5c6\ub2e4. \ud558\uc9c0\ub9cc \ud655\ub300\ud574 \ubcf8 \ub0b4\ubd80 \uad6c\uc870\ub85c \uc190\uc5d0 \uc7a1\ud788\ub294 \uc131\uc9c8\uc744 \uc124\uba85\ud558\ub824 \ud588\ub2e4\ub294 \uc810\uc774 \ud765\ubbf8\ub86d\ub2e4. \ucf54\ub974\ud06c\uac00 \ubcd1\ub9c8\uac1c\ub098 \ub728\uac1c\ub85c \uc4f8\ubaa8 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uad00\ucc30 \uc804\uc5d0\ub3c4 \uc54c\ub824\uc838 \uc788\uc5c8\ub2e4. \ud6c5\uc774 \uc0c8\ub86d\uac8c \ubb3c\uc740 \uac83\uc740 \uadf8 \uc4f8\ubaa8\uac00 \uc5b4\ub5a4 \uad6c\uc870\uc640 \uad00\ub828\ub418\ub294\uac00\uc600\ub2e4. \uc791\uc740 \uce78\uc758 \uadf8\ub9bc\uc740 \uc774\ub984 \ud558\ub098\ub97c \ub0a8\uae30\uba74\uc11c \uc77c\uc0c1 \uc7ac\ub8cc\ub97c \ud0d0\uad6c\ud560 \uae38\ub3c4 \uc5f4\uc5c8\ub2e4. \ucf54\ub974\ud06c\ub97c \ub2e4\uc2dc \uc190\uc5d0 \uc950\uba74 \ub9e4\ub048\ud55c \ubb3c\uac74 \uc548\uc758 \uc218\ub9ce\uc740 \uce78\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \ud6c5\uc758 \uc774\uc57c\uae30\ub294 \ud2b9\ubcc4\ud55c \uc7ac\ub8cc\ub9cc \uad00\ucc30\ud560 \uac00\uce58\uac00 \uc788\ub2e4\ub294 \uc0dd\uac01\uc744 \ud754\ub4e0\ub2e4. \uce5c\uc219\ud55c \uc0ac\ubb3c\ub3c4 \ubcf4\ub294 \uc870\uac74\uc774 \ub2ec\ub77c\uc9c0\uba74 \uc0c8\ub85c\uc6b4 \uc9c8\ubb38\uc744 \ub0b3\ub294\ub2e4. \u300e\ub9c8\uc774\ud06c\ub85c\uadf8\ub77c\ud53c\uc544\u300f\uac00 \ub113\ud78c \uac83\uc740 \ub2e8\uc9c0 \ubb3c\uccb4\uc758 \ud06c\uae30\uac00 \uc544\ub2c8\uc5c8\ub2e4. \uad00\ucc30\uc744 \uae00\uacfc \uadf8\ub9bc\uc73c\ub85c \ub0a8\uaca8 \ub2e4\ub978 \uc0ac\ub78c\uc774 \ud568\uaed8 \uc0b4\ud544 \uc138\uacc4\ub3c4 \ub113\ud614\ub2e4. \uc791\uc740 \ubc29\uc774\ub77c\ub294 \uc774\ub984\uc740 \uadf8 \uc624\ub798\ub41c \uad00\ucc30\uacfc \ub300\ud654\uc758 \ud754\uc801\uc774\ub2e4."}, {"id": "ice-floats-lake-freezes-from-top", "title": "\uc5bc\uc74c \u2014 \ud638\uc218\ub294 \uc65c \uc704\uc5d0\uc11c\ubd80\ud130 \uc5bc\uc5b4 \uac08\uae4c", "summary": "\uaca8\uc6b8 \ud638\uc218\uc758 \uc7a5\uba74\uc5d0\uc11c \ubc00\ub3c4\u00b7\ubd80\ub825\u00b7\ubb3c\uc758 \uc628\ub3c4 \ubcc0\ud654\ub97c \uc5f0\uacb0\ud574 \uc5bc\uc74c\uc774 \ub728\ub294 \uc774\uc720\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\ubb3c\uc9c8\uacfc \uc5d0\ub108\uc9c0", "categories": ["science"], "url": "stories/ice-floats-lake-freezes-from-top/index.html", "image": "../media/ice-floats-lake-freezes-from-top.png", "alt": "\uaca8\uc6b8 \ud638\uc22b\uac00\uc758 \uc5bc\uc74c \ud45c\uba74\uacfc \uc5b4\ub450\uc6b4 \uc5f4\ub9b0 \ubb3c, \uc8fc\ubcc0 \uac08\ub300\uc640 \ub098\ubb34\ub97c \ud45c\ud604\ud55c \uc0bd\ud654.", "text": "\uc5bc\uc74c \u2014 \ud638\uc218\ub294 \uc65c \uc704\uc5d0\uc11c\ubd80\ud130 \uc5bc\uc5b4 \uac08\uae4c \ubb3c\ubcf4\ub2e4 \uac00\ubcbc\uc6b4 \uc5bc\uc74c\uacfc \uc870\uae08 \ud2b9\ubcc4\ud55c 4\ub3c4 \uaca8\uc6b8 \ud638\uc218\uc758 \uc7a5\uba74\uc5d0\uc11c \ubc00\ub3c4\u00b7\ubd80\ub825\u00b7\ubb3c\uc758 \uc628\ub3c4 \ubcc0\ud654\ub97c \uc5f0\uacb0\ud574 \uc5bc\uc74c\uc774 \ub728\ub294 \uc774\uc720\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ubb3c\uc9c8\uacfc \uc5d0\ub108\uc9c0 \uacfc\ud559\uacfc \ubc1c\uacac \uaca8\uc6b8 \ud638\uc218\uc758 \ud45c\uba74\uc774 \uc5bc\uc5c8\ub2e4. \uadf8\ub7f0\ub370 \uc5bc\uc74c \uc544\ub798\uc5d0\ub294 \uc5ec\uc804\ud788 \ubb3c\uc774 \uc788\uace0 \uadf8 \uc18d\uc5d0\uc11c \uc0b4\uc544\uac00\ub294 \uc0dd\ubb3c\ub3c4 \uc788\ub2e4. \ub2e8\ub2e8\ud55c \uc5bc\uc74c\uc774 \uc561\uccb4\uc778 \ubb3c \uc704\uc5d0 \ub193\uc778\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub108\ubb34 \uc775\uc219\ud574\uc11c \uc774\uc0c1\ud558\uac8c \ub290\uaef4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uac19\uc740 \ubb3c\uc9c8\uc778\ub370 \uad73\uc740 \ucabd\uc774 \uc544\ub798\ub85c \uac00\ub77c\uc549\uc9c0 \uc54a\ub294 \uc774\uc720\ub294 \ubb34\uc5c7\uc77c\uae4c. \uc774 \uc7a5\uba74\uc744 \uc774\ud574\ud558\ub824\uba74 \ub2e8\ub2e8\ud568\uacfc \ubb34\uac8c\ub97c \uc7a0\uc2dc \ub098\ub204\uc5b4 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uac19\uc740 \ubd80\ud53c\uc5d0 \uc5bc\ub9c8\ub098 \ub9ce\uc740 \ubb3c\uc9c8\uc774 \ub4e4\uc5b4 \uc788\ub294\uc9c0, \ubb3c\uc740 \uc2dd\uc744 \ub54c \uc5b4\ub5bb\uac8c \ub2ec\ub77c\uc9c0\ub294\uc9c0\ub97c \uc0b4\ud3b4\ubcf4\uba74 \ud638\uc218\uc758 \uaca8\uc6b8 \ud48d\uacbd\uc774 \uc791\uc740 \uacfc\ud559 \uc774\uc57c\uae30\ub85c \ubc14\ub010\ub2e4. \ub3cc\uba69\uc774\ub294 \uac00\ub77c\uc549\uace0 \ucee4\ub2e4\ub780 \ub098\ubb34\ud1a0\ub9c9\uc740 \ub730 \uc218 \uc788\ub2e4. \ubb3c\uac74 \uc804\uccb4\uac00 \uba87 \ud0ac\ub85c\uadf8\ub7a8\uc778\uc9c0\ubcf4\ub2e4 \uac19\uc740 \ubd80\ud53c\uc758 \ubb3c\uacfc \ube44\uad50\ud588\uc744 \ub54c \uc5b4\ub5a4\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \ubc00\ub3c4\ub294 \uc9c8\ub7c9\uc744 \ubd80\ud53c\uc640 \uc5f0\uacb0\ud574 \ubcf4\ub294 \uac12\uc774\ub2e4. \ubb3c\uac74\uc758 \ud06c\uae30\uc640 \uc7ac\ub8cc\ub97c \ud568\uaed8 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. OpenStax\ub294 \ubb3c\uc18d\uc758 \ubb3c\uccb4\uac00 \ubc00\uc5b4\ub0b8 \ubb3c\uc758 \ubb34\uac8c\ub9cc\ud07c \uc704\ub85c \ubbf8\ub294 \ud798\uc744 \ubc1b\ub294\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubd80\ub825\uc774\ub77c\uace0 \ubd80\ub974\ub294 \ud798\uc774\ub2e4. \ub728\ub294 \ubb3c\uccb4\ub294 \uadf8 \ud798\uacfc \uc790\uae30 \ubb34\uac8c\uac00 \uade0\ud615\uc744 \uc774\ub8e8\ub294 \uc790\ub9ac\uc5d0 \ub193\uc778\ub2e4. \uc5bc\uc74c\uc774 \ubb3c\uc5d0 \ub728\ub294 \uc774\uc57c\uae30\uc5d0\ub3c4 \uc774 \ube44\uad50\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \ubcf4\ud1b5\uc758 \uc555\ub825\uc5d0\uc11c \ubb3c\uc774 \uc5bc\uc74c\uc73c\ub85c \ubc14\ub00c\uba74 \ubd84\uc790\ub4e4\uc774 \uc815\ub3c8\ub41c \uad6c\uc870\ub97c \uc774\ub8e8\uba70 \uc561\uccb4\uc77c \ub54c\ubcf4\ub2e4 \uacf5\uac04\uc744 \ub354 \ub113\uac8c \ucc28\uc9c0\ud55c\ub2e4. \ubd84\uc790\uac00 \uc0ac\ub77c\uc9c0\uac70\ub098 \uc0c8 \ubb3c\uc9c8\ub85c \ubc14\ub00c\uc5b4\uc11c \uac00\ubcbc\uc6cc\uc9c0\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uac19\uc740 \uc9c8\ub7c9\uc774 \ub354 \ud070 \ubd80\ud53c\uc5d0 \ub4e4\uc5b4\uac00 \ubc00\ub3c4\uac00 \ub0ae\uc544\uc9c4\ub2e4. \uad50\uc7ac\ub294 \uc5bc\uc74c\uc758 \uacb0\uc815 \uad6c\uc870\uc5d0 \uc561\uccb4\ubcf4\ub2e4 \ube48 \uacf5\uac04\uc774 \ub354 \ub9ce\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubb3c \ubd84\uc790\ub4e4 \uc0ac\uc774\uc758 \uc218\uc18c \uacb0\ud569\ub3c4 \uc774\ub7f0 \uc131\uc9c8\uacfc \uad00\ub828\ub41c\ub2e4. \ub3c5\uc790\uac00 \ubd84\uc790 \ubaa8\ud615\uc744 \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e8\ub2e8\ud574\uc9c4\ub2e4\ub294 \ubcc0\ud654\uc640 \ub354 \ube7d\ube7d\ud574\uc9c4\ub2e4\ub294 \ubcc0\ud654\uac00 \uc5b8\uc81c\ub098 \uac19\uc740 \ub73b\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc774 \ud575\uc2ec\uc774\ub2e4. \ubb3c\ubcf4\ub2e4 \ubc00\ub3c4\uac00 \ub0ae\uc740 \uc5bc\uc74c\uc740 \uc77c\ubd80\ub9cc \uc7a0\uae34 \uc0c1\ud0dc\uc5d0\uc11c\ub3c4 \uc790\uae30 \ubb34\uac8c\uc640 \uade0\ud615\uc744 \uc774\ub8e8\ub294 \ubd80\ub825\uc744 \ubc1b\uc744 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \ub098\uba38\uc9c0 \ubd80\ubd84\uc774 \ubb3c \uc704\ub85c \ub098\uc628\ub2e4. \uc5bc\ub9c8\ub098 \uc7a0\uae30\ub294\uc9c0\ub294 \uc5bc\uc74c\uacfc \ubb3c\uc758 \ubc00\ub3c4\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c4\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \uc717\ubd80\ubd84\uc774 \uc804\uccb4\uc758 \uc804\ubd80\uac00 \uc544\ub2cc \uc774\uc720\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \ub5a0 \uc788\ub294 \uc5bc\uc74c\uc758 \ubaa8\uc591\uacfc \ube44\uc728\uc774 \ub611\uac19\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ubc14\ub2f7\ubb3c\uacfc \ubbfc\ubb3c\uc758 \uc870\uac74\uc774 \ub2e4\ub974\uace0 \uc5bc\uc74c\uc5d0 \uacf5\uae30\ub098 \ub2e4\ub978 \ubb3c\uc9c8\uc774 \ud3ec\ud568\ub420 \uc218\ub3c4 \uc788\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc77c\ubc18\uc801\uc778 \ubb3c\uacfc \uc5bc\uc74c\uc758 \uae30\ubcf8 \uad00\uacc4\ub97c \uc0b4\ud540\ub2e4. \uc0ac\uc9c4 \ud55c \uc7a5\uc5d0\uc11c \uc815\ud655\ud55c \ubd80\ud53c\ub97c \uc7ac\ub294 \ubb38\uc81c\uc640\ub294 \ub2e4\ub978 \uc124\uba85\uc774\ub2e4. \ub9ce\uc740 \ubb3c\uc9c8\uc740 \uc2dd\uc73c\uba74\uc11c \ubd80\ud53c\uac00 \uc904\uace0 \ubc00\ub3c4\uac00 \ub192\uc544\uc9c4\ub2e4. \uadf8\ub7f0\ub370 \ubcf4\ud1b5 \uae30\uc555\uc758 \ubbfc\ubb3c\uc740 \uc57d 4\ub3c4\uc5d0\uc11c \ubc00\ub3c4\uac00 \uac00\uc7a5 \ub192\ub2e4. \uadf8\ubcf4\ub2e4 \ub354 \ucc28\uac00\uc6cc\uc838 0\ub3c4\uc5d0 \uac00\uae4c\uc6cc\uc9c0\ub294 \uad6c\uac04\uc5d0\uc11c\ub294 \uc624\ud788\ub824 \ubd80\ud53c\uac00 \ub298\uace0 \ubc00\ub3c4\uac00 \ub0ae\uc544\uc9c0\ub294 \ud2b9\uc131\uc774 \uc788\ub2e4. \uc774 \uc791\uc740 \ucc28\uc774\uac00 \ud638\uc218\uc5d0\uc11c \uc911\uc694\ud574\uc9c4\ub2e4. \ud45c\uba74\uc758 \ubb3c\uc774 \uc2dd\uc5b4 \uc57d 4\ub3c4\uac00 \ub418\uba74 \uc544\ub798\ub85c \uac00\ub77c\uc549\uc544 \ub2e4\ub978 \ubb3c\uacfc \uc11e\uc77c \uc218 \uc788\ub2e4. \uc774\ud6c4 \ub354 \ucc28\uac00\uc6cc\uc9c4 \ubb3c\uc740 \uc544\ub798\uc758 \ubb3c\ubcf4\ub2e4 \ubc00\ub3c4\uac00 \ub0ae\uc544 \uc704\ucabd\uc5d0 \ub0a8\uae30 \uc26c\uc6cc\uc9c4\ub2e4. \ucc28\uac11\ub2e4\ub294 \ub9d0 \ud558\ub098\ub9cc\uc73c\ub85c \ud56d\uc0c1 \uc544\ub798\uc5d0 \ub193\uc778\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uc774 \uc21c\uc11c\ub97c \ub193\uce5c\ub2e4. \uad50\uc7ac\ub294 \uc774\ub7f0 \uc131\uc9c8 \ub54c\ubb38\uc5d0 \uc5f0\ubabb\uc758 \ud45c\uba74\uc774 \uc5bc \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub300\uae30\uc640 \uc5f4\uc744 \uc8fc\uace0\ubc1b\ub294 \uc704\ucabd\uc5d0\uc11c \ubb3c\uc774 \ucda9\ubd84\ud788 \ucc28\uac00\uc6cc\uc9c0\uace0 \uc5bc\uc74c\uc774 \uc0dd\uae34\ub2e4. \uc0dd\uae34 \uc5bc\uc74c\ub3c4 \ubb3c \uc704\uc5d0 \ub0a8\ub294\ub2e4. \ubb3c\uc758 \ubc00\ub3c4 \ubcc0\ud654\uc640 \ubd80\ub825\uc774 \ud568\uaed8 \uaca8\uc6b8\uc758 \uce35\uc744 \ub9cc\ub4dc\ub294 \uac83\uc774\ub2e4. \ubb3c\ub860 \uc2e4\uc81c \ud638\uc218\uc758 \uc0c1\ud0dc\ub294 \uae4a\uc774\uc640 \ubc14\ub78c, \ubb3c\uc758 \uc774\ub3d9, \uc5fc\ubd84 \uac19\uc740 \uc870\uac74\uc5d0\ub3c4 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4. \ubaa8\ub4e0 \uc5f0\ubabb\uc774 \uaca8\uc6b8 \ub0b4\ub0b4 \ubc14\ub2e5\uae4c\uc9c0 \uc5bc\uc9c0 \uc54a\ub294\ub2e4\uace0 \ubcf4\uc7a5\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc774 \uc124\uba85\uc740 \ubbfc\ubb3c\uc758 \uae30\ubcf8 \uc131\uc9c8\uc774 \uc65c \ud45c\uba74\uc758 \uacb0\ube59\uacfc \uc5f0\uacb0\ub418\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \ucd9c\ubc1c\uc810\uc774\ub2e4. \ud45c\uba74\uc758 \uc5bc\uc74c\uc740 \uadf8 \uc544\ub798 \ubb3c\uacfc \ucc28\uac00\uc6b4 \uacf5\uae30 \uc0ac\uc774\uc758 \uc5f4 \uc774\ub3d9\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc900\ub2e4. \uad50\uc7ac\ub294 \uc5bc\uc74c\uce35\uc758 \ub2e8\uc5f4 \ud6a8\uacfc\uc640 \ubb3c\uc758 \ud2b9\uc131 \ub355\ubd84\uc5d0 \uc544\ub798\uc758 \uc561\uccb4 \ud658\uacbd\uc5d0\uc11c \uc218\uc0dd \uc0dd\ubb3c\uc774 \uc0b4\uc544\uac08 \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubb3c\uc758 \uc791\uc740 \ubb3c\ub9ac\uc801 \uc131\uc9c8\uc774 \uc0dd\ubb3c\uc758 \uc0dd\ud65c \uc870\uac74\uacfc \ub9cc\ub098\ub294 \ub300\ubaa9\uc774\ub2e4. \ub2e4\ub9cc \uc5bc\uc74c \uc544\ub798\uc5d0 \ubb3c\uc774 \uc788\ub2e4\uace0 \ubaa8\ub4e0 \uc0dd\ubb3c\uc774 \uc548\uc804\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0b0\uc18c\uc640 \uc218\uc628, \uc11c\uc2dd \ud658\uacbd \ub4f1 \ub2e4\ub978 \uc870\uac74\ub3c4 \ud544\uc694\ud558\ub2e4. \ud55c \uc6d0\ub9ac\uac00 \uc0dd\uc874\uc758 \uc911\uc694\ud55c \uc870\uac74\uc744 \uc124\uba85\ud560 \uc218 \uc788\uc5b4\ub3c4 \uc0dd\ud0dc\uacc4 \uc804\uccb4\ub97c \ub300\uc2e0 \uc124\uba85\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uacfc\ud559\uc758 \uc5f0\uacb0\uc740 \uc774\ub7f0 \ubc94\uc704\ub97c \ud568\uaed8 \ubcfc \ub54c \ub354 \ubd84\uba85\ud574\uc9c4\ub2e4. \uac19\uc740 \ubb3c\uc9c8\uc774 \uc561\uccb4\uc640 \uace0\uccb4\uc5d0\uc11c \ub2e4\ub978 \ubc00\ub3c4\ub97c \uac00\uc9c8 \uc218 \uc788\ub2e4\ub294 \uc810\uc740 \uc77c\uc0c1\uc758 \uc9c1\uac10\uacfc \uc870\uae08 \uc5b4\uae0b\ub09c\ub2e4. \ub2e8\ub2e8\ud55c \uac83\uc740 \ubb34\uac81\uace0 \uc561\uccb4\ub294 \uac00\ubccd\ub2e4\ub294 \ub290\ub08c\uc744 \uc7a0\uc2dc \ub0b4\ub824\ub193\uc544\uc57c \ud55c\ub2e4. \ubb34\uc5c7\uc744 \uac19\uc740 \ubd80\ud53c\ub85c \ube44\uad50\ud558\ub294\uc9c0\uc5d0 \ub530\ub77c \ub2f5\uc774 \ub2ec\ub77c\uc9c0\uae30 \ub54c\ubb38\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uaca8\uc6b8 \ud638\uc22b\uac00\uc758 \uc5bc\uc74c\uacfc \uc5f4\ub9b0 \ubb3c\uc744 \ud45c\ud604\ud55c \ubd84\uc704\uae30 \uadf8\ub9bc\uc774\ub2e4. \ud2b9\uc815 \ud638\uc218\uc758 \uad00\uce21 \uc0ac\uc9c4\uc774\ub098 \uc218\uc628 \ubd84\ud3ec\ub97c \uce21\uc815\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc5bc\uc74c\uc758 \uc815\ud655\ud55c \ub450\uaed8\uc640 \uc544\ub798 \ubb3c\uc758 \uc0c1\ud0dc\ub97c \uc774 \uadf8\ub9bc\uc5d0\uc11c \ud655\uc778\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud638\uc218\uac00 \uc704\uc5d0\uc11c\ubd80\ud130 \uc5bc\uc5b4 \uac00\ub294 \ud48d\uacbd\uc5d0\ub294 \ubb3c \ubd84\uc790\uc758 \ubc30\uc5f4\uacfc \ubc00\ub3c4, \ubd80\ub825\uacfc \uc5f4\uc758 \uc774\ub3d9\uc774 \ud568\uaed8 \uc788\ub2e4. \ud55c \uac00\uc9c0 \ub2e8\uc5b4\ub85c \ub05d\ub098\ub294 \ud604\uc0c1\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc \uc5ec\ub7ec \uc6d0\ub9ac\uac00 \uc11c\ub85c \uc774\uc5b4\uc9c4\ub2e4. \ub208\uc55e\uc758 \uc870\uc6a9\ud55c \ud45c\uba74 \uc544\ub798\uc5d0\ub3c4 \uacc4\uc18d\ub418\ub294 \ubb3c\uc758 \uc6c0\uc9c1\uc784\uc774 \uc788\ub294 \uac83\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \ucef5\uc758 \uc5bc\uc74c\uc774\ub098 \uaca8\uc6b8 \ubb3c\uac00\ub97c \ub9cc\ub098\uba74 \uc5bc\uc74c\uc774 \ub2e8\ub2e8\ud558\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ubb3c\uc5d0 \ub72c\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ub530\ub85c \uc0dd\uac01\ud574 \ubcf4\uc790. \uac19\uc740 \uc9c8\ub7c9\uc774 \uc5b4\ub5a4 \uacf5\uac04\uc744 \ucc28\uc9c0\ud558\uace0 \uc8fc\ubcc0\uc758 \ubb3c\uacfc \uc5b4\ub5bb\uac8c \uade0\ud615\uc744 \uc774\ub8e8\ub294\uc9c0 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \uc775\uc219\ud55c \uc5bc\uc74c\uc740 \ubb3c\uc774 \uc5bc\ub9c8\ub098 \ud2b9\ubcc4\ud55c \ubb3c\uc9c8\uc778\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \uac00\uc7a5 \uac00\uae4c\uc6b4 \ud45c\ubcf8\uc774\ub2e4."}, {"id": "jenner-cowpox-and-vaccination-history", "title": "\uc81c\ub108 \u2014 \uc6b0\uc720 \uc9dc\ub294 \uc0ac\ub78c\ub4e4\uc758 \uacbd\ud5d8\uc774 \ubc31\uc2e0\uc73c\ub85c \uc774\uc5b4\uc9c0\uae30\uae4c\uc9c0", "summary": "\uc778\ub450\ubc95\uc758 \uc120\ud589 \uc5ed\uc0ac\uc640 \uc81c\ub108\uc758 \uc6b0\ub450 \uc811\uc885\uc744 \ub098\ub204\uc5b4 \uc0b4\ud53c\uba70 \uad00\ucc30\u00b7\uc2dc\ud5d8\u00b7\uc5f0\uad6c \uc724\ub9ac\uc758 \ubb38\uc81c\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uacfc\ud559\uc790\uc758 \ubc1c\uacac", "categories": ["science"], "url": "stories/jenner-cowpox-and-vaccination-history/index.html", "image": "../media/jenner-cowpox-and-vaccination-history.png", "alt": "18\uc138\uae30 \ub9d0 \uc601\uad6d \ub18d\ucd0c\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc758\uc0ac\uc640 \uc6b0\uc720 \uc9dc\ub294 \uc0ac\ub78c\uc774 \ub300\ud654\ud558\ub294 \uc0c1\uc0c1 \uc18d \uc7a5\uba74.", "text": "\uc81c\ub108 \u2014 \uc6b0\uc720 \uc9dc\ub294 \uc0ac\ub78c\ub4e4\uc758 \uacbd\ud5d8\uc774 \ubc31\uc2e0\uc73c\ub85c \uc774\uc5b4\uc9c0\uae30\uae4c\uc9c0 1796\ub144\uc758 \uc2dc\ub3c4\uc640 \uadf8\ubcf4\ub2e4 \uc624\ub798\ub41c \uc608\ubc29\uc758 \uc5ed\uc0ac \uc778\ub450\ubc95\uc758 \uc120\ud589 \uc5ed\uc0ac\uc640 \uc81c\ub108\uc758 \uc6b0\ub450 \uc811\uc885\uc744 \ub098\ub204\uc5b4 \uc0b4\ud53c\uba70 \uad00\ucc30\u00b7\uc2dc\ud5d8\u00b7\uc5f0\uad6c \uc724\ub9ac\uc758 \ubb38\uc81c\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uacfc\ud559\uc790\uc758 \ubc1c\uacac \uacfc\ud559\uacfc \ubc1c\uacac \ubcd1\uc5d0 \uac78\ub9b0 \ub4a4 \uace0\uce58\ub294 \ubc29\ubc95\uc774 \ub9c8\ub545\uce58 \uc54a\ub358 \uc2dc\ub300\uc5d0\ub294 \ubbf8\ub9ac \ud53c\ud560 \uc218 \uc788\ub294 \uae38\uc774 \ud070 \ud76c\ub9dd\uc774\uc5c8\ub2e4. \ucc9c\uc5f0\ub450\ub294 \uadf8\ub7f0 \uc808\ubc15\ud568\uc744 \ub0b3\uc740 \uc9c8\ubcd1\uc774\uc5c8\ub2e4. \uadf8\ub7f0\ub370 \uc18c\uc640 \uac00\uae4c\uc774 \uc77c\ud558\ub294 \uc0ac\ub78c\ub4e4\uc774 \uacaa\ub294 \ub2e4\ub978 \ubcd1\uc758 \uacbd\ud5d8\uc774 \uc608\ubc29\uc758 \uc0c8\ub85c\uc6b4 \ubc29\ubc95\uacfc \uc5f0\uacb0\ub418\uc5c8\ub2e4. \uc601\uad6d \uc758\uc0ac \uc5d0\ub4dc\uc6cc\ub4dc \uc81c\ub108\ub294 \uc6b0\ub450\ub97c \uc553\uc740 \uc0ac\ub78c\ub4e4\uc774 \ucc9c\uc5f0\ub450\uc5d0 \uc798 \uac78\ub9ac\uc9c0 \uc54a\ub294\ub2e4\ub294 \uad00\ucc30\uc5d0 \uc8fc\ubaa9\ud588\ub2e4. \uc5ec\uae30\uc11c \ucd9c\ubc1c\ud55c 1796\ub144\uc758 \uc2dc\ub3c4\ub294 \ubc31\uc2e0\uc758 \uc5ed\uc0ac\uc5d0\uc11c \uc911\uc694\ud55c \uc7a5\uba74\uc774 \ub418\uc5c8\ub2e4. \ub2e4\ub9cc \ud55c \ucc9c\uc7ac\uac00 \uc544\ubb34 \uc120\ud589 \uc9c0\uc2dd \uc5c6\uc774 \uc608\ubc29\uc744 \ubc1c\uba85\ud55c \uc774\uc57c\uae30\ub85c \uc77d\uc73c\uba74 \uadf8 \uc55e\ub4a4\uc758 \uc0ac\ub78c\uacfc \uc2dc\uac04\uc744 \ub193\uce5c\ub2e4. \uad50\uc7ac\ub294 \ucc9c\uc5f0\ub450\ub97c \ub9c9\uae30 \uc704\ud55c \uc778\ub450\ubc95\uc774 \uc81c\ub108 \uc774\uc804\ubd80\ud130 \uc0ac\uc6a9\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc911\uad6d\uc744 \ube44\ub86f\ud55c \uc9c0\uc5ed\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c4 \uc2dc\ub3c4\uac00 \ub2e4\ub978 \uc9c0\uc5ed\uc73c\ub85c \ud37c\uc84c\ub2e4. \ucc9c\uc5f0\ub450\ub97c \uc553\uc740 \uc0ac\ub78c\uc758 \ubb3c\uc9c8\uc744 \uc774\uc6a9\ud574 \uc608\ubc29\uc744 \uae30\ub300\ud55c \ubc29\uc2dd\uc774\uc5c8\ub2e4. \ubcd1\uc744 \uacaa\uc740 \ub4a4 \ub2e4\uc2dc \uac78\ub9ac\uc9c0 \uc54a\ub294 \ud604\uc0c1\uc5d0 \ub300\ud55c \uacbd\ud5d8\uc774 \ubc30\uacbd\uc5d0 \uc788\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \uc774 \ubc29\ubc95 \uc790\uccb4\uac00 \uac10\uc5fc\uacfc \uc720\ud589\uc744 \uc77c\uc73c\ud0ac \uc704\ud5d8\ub3c4 \uc788\uc5c8\ub2e4. \uc608\ubc29\uc758 \ud544\uc694\uac00 \ucef8\ub2e4\uace0 \uc2dc\ub3c4\ud558\ub294 \ubaa8\ub4e0 \ubc29\ubc95\uc774 \uc548\uc804\ud588\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc81c\ub108\uc758 \uc774\uc57c\uae30\ub294 \uc774\ubbf8 \uc788\ub358 \uc608\ubc29\uc758 \uc5ed\uc0ac\uc640 \uadf8 \uc704\ud5d8 \uc18d\uc5d0\uc11c \ub354 \ub098\uc740 \ubc29\ubc95\uc744 \ucc3e\ub358 \ud750\ub984\uc5d0 \ub193\uc5ec \uc788\ub2e4. \uc6b0\ub450\ub294 \uc18c\uc640 \uc0ac\ub78c \uc0ac\uc774\uc5d0\uc11c \uad00\ub828\ub418\ub294 \uac10\uc5fc\ubcd1\uc73c\ub85c \ucc9c\uc5f0\ub450\uc640\ub294 \ub2e4\ub974\ub2e4. \uad50\uc7ac\ub294 \uc81c\ub108\uac00 \uc6b0\ub450\ub97c \uacaa\uc740 \uc6b0\uc720 \uc9dc\ub294 \uc0ac\ub78c\ub4e4\uc758 \uacbd\ud5d8\uc5d0\uc11c \uac00\uc124\uc744 \uc138\uc6e0\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ube44\uad50\uc801 \uac00\ubcbc\uc6b4 \ub2e4\ub978 \uac10\uc5fc\uc774 \ub354 \uc2ec\uac01\ud55c \ubcd1\uc5d0 \ub300\ud55c \ubcf4\ud638\uc640 \uc5f0\uacb0\ub420 \uc218 \uc788\ub294\uac00\ub77c\ub294 \uc9c8\ubb38\uc774\uc5c8\ub2e4. \uc774\uac83\uc740 \ub2f9\uc2dc \uadf8\uac00 \ubc14\uc774\ub7ec\uc2a4\uc758 \uc720\uc804\uc790\uc640 \uba74\uc5ed \uc138\ud3ec\ub97c \ubaa8\ub450 \uc774\ud574\ud588\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc9c0\uae08\uc758 \uc124\uba85\uacfc \ub2f9\uc2dc\uc758 \uc9c8\ubb38\uc740 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \uc8fc\ubcc0\uc5d0\uc11c \uad00\ucc30\ud55c \uacbd\ud5d8\uc744 \uc0c8\ub85c\uc6b4 \uc608\ubc29 \ubc29\ubc95\uc758 \uac00\ub2a5\uc131\uc73c\ub85c \uc77d\uc5c8\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uc77c\uc0c1\uc758 \uc9c0\uc2dd\uc774 \uc758\ud559\uc758 \uc9c8\ubb38\uacfc \ub9cc\ub098\ub294 \uc790\ub9ac\uc600\ub2e4. \uc81c\ub108\ub294 1796\ub144 \uc6b0\ub450\uc758 \ubb3c\uc9c8\uc744 \uc5b4\ub9b0\uc544\uc774\uc5d0\uac8c \uc811\uc885\ud588\ub2e4. \uad50\uc7ac\ub294 \uc544\uc774\uac00 \ube44\uad50\uc801 \uac00\ubcbc\uc6b4 \uc99d\uc0c1\uc744 \ubcf4\uc778 \ub4a4, \uc774\ud6c4 \ucc9c\uc5f0\ub450 \ubb3c\uc9c8\uc5d0 \ub178\ucd9c\ub418\uc5c8\uc744 \ub54c \ucc9c\uc5f0\ub450\ub97c \uc553\uc9c0 \uc54a\uc558\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc81c\ub108\uc5d0\uac8c\ub294 \uc790\uc2e0\uc758 \uac00\uc124\uc744 \ub4b7\ubc1b\uce68\ud558\ub294 \uc911\uc694\ud55c \uacb0\uacfc\uc600\ub2e4. \uadf8\ub7ec\ub098 \uc624\ub298\uc758 \ub3c5\uc790\ub294 \uc774 \uc7a5\uba74\uc744 \uc6a9\uac10\ud55c \uc131\uacf5\ub2f4\uc73c\ub85c\ub9cc \uc77d\uc744 \uc218 \uc5c6\ub2e4. \uc5b4\ub9b0\uc774\ub97c \uc5f0\uad6c\uc5d0 \ucc38\uc5ec\uc2dc\ud0a4\uace0 \uc704\ud5d8\uc5d0 \ub178\ucd9c\ud55c \ud589\ub3d9\uc5d0\ub294 \ub3d9\uc758\uc640 \ubcf4\ud638\ub77c\ub294 \uc911\ub300\ud55c \uc724\ub9ac\uc801 \uc9c8\ubb38\uc774 \uc788\ub2e4. \uc5ed\uc0ac\uc801 \uc131\uacfc\ub97c \uc774\ud574\ud558\ub294 \uc77c\uacfc \uadf8 \uacfc\uc815\uc758 \uc704\ud5d8\uc744 \uc815\ub2f9\ud654\ud558\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \ub2f9\uc2dc\uc758 \ubc29\ubc95\uc744 \ub2e4\uc2dc \ub530\ub77c \ud560 \uc218 \uc788\ub294 \uc808\ucc28\ub85c \uc77d\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \ubc31\uc2e0 \uc811\uc885\uc744 \ub73b\ud558\ub294 vaccination\uc774\ub77c\ub294 \ub9d0\uc740 \uc18c\ub97c \ub73b\ud558\ub294 \ub77c\ud2f4\uc5b4 vacca\uc640 \uc5f0\uacb0\ub41c\ub2e4. \uc6b0\ub450\ub97c \uc774\uc6a9\ud55c \uc774 \uc5ed\uc0ac\uac00 \uc774\ub984 \uc18d\uc5d0 \ub0a8\uc740 \uac83\uc774\ub2e4. \uc624\ub298\ub0a0 \uc775\uc219\ud55c \uc758\ub8cc \uc6a9\uc5b4 \ub4a4\uc5d0 \ubaa9\uc7a5\uacfc \uc18c, \uc0ac\ub78c\uc758 \uac10\uc5fc \uacbd\ud5d8\uc774 \ub4e4\uc5b4 \uc788\ub2e4\ub294 \uc810\uc774 \ud765\ubbf8\ub86d\ub2e4. \uadf8\ub807\ub2e4\uace0 \ud604\uc7ac\uc758 \ubaa8\ub4e0 \ubc31\uc2e0\uc774 \uc18c\uc5d0\uc11c \uc5bb\uc740 \uac19\uc740 \ubb3c\uc9c8\uc774\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc774\ud6c4 \uc5ec\ub7ec \uc9c8\ubcd1\uacfc \ub2e4\uc591\ud55c \ubc29\uc2dd\uc758 \ubc31\uc2e0\uc774 \uac1c\ubc1c\ub418\uc5c8\ub2e4. \uc774\ub984\uc758 \uae30\uc6d0\uc740 \ucd9c\ubc1c\uc810\uc744 \uc54c\ub824 \uc8fc\uc9c0\ub9cc \uc9c0\uae08 \uc874\uc7ac\ud558\ub294 \ubaa8\ub4e0 \ubc29\ubc95\uc744 \ud55c\uaebc\ubc88\uc5d0 \uc124\uba85\ud574 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uad50\uc7ac\ub294 \uc6b0\ub450\uc640 \ucc9c\uc5f0\ub450\ub97c \uc77c\uc73c\ud0a4\ub294 \ubc14\uc774\ub7ec\uc2a4\uac00 \uad00\ub828\ub418\uc5b4 \uc788\uc5b4 \uba74\uc5ed \ubc18\uc751\uc774 \ubcf4\ud638\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc6b0\ub9ac \ubab8\uc774 \ud55c \ubc88 \ub9cc\ub09c \ubcd1\uc6d0\uccb4\uc758 \ud2b9\uc9d5\uc744 \uae30\uc5b5\ud558\uace0 \ub2e4\uc74c\uc758 \uad00\ub828\ub41c \uce68\uc785\uc5d0 \ubc18\uc751\ud558\ub294 \ub2a5\ub825\uc774 \uc911\uc694\ud558\ub2e4. \uc81c\ub108\uc758 \uad00\ucc30\uc740 \ub098\uc911\uc5d0 \ub354 \uc815\uad50\ud55c \uc9c0\uc2dd\uc73c\ub85c \ud574\uc11d\ub420 \uc218 \uc788\uc5c8\ub2e4. \uc774 \ucc28\uc774\ub97c \uc54c\uba74 \uc61b \uc758\uc0ac\uac00 \uc624\ub298\uc758 \uc124\uba85\uc744 \ubaa8\ub450 \uc54c\uace0 \ud589\ub3d9\ud55c \uac83\ucc98\ub7fc \ubb18\uc0ac\ud558\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uacb0\uacfc\uac00 \uba3c\uc800 \uad00\ucc30\ub418\uace0 \uadf8 \uacb0\uacfc\ub97c \uc774\ud574\ud558\ub294 \uc5b8\uc5b4\uac00 \ub4a4\uc5d0 \ubc1c\uc804\ud560 \uc218\ub3c4 \uc788\ub2e4. \uacfc\ud559\uc758 \uc5ed\uc0ac\ub294 \uc2e4\ucc9c\uacfc \uc124\uba85\uc774 \uc5b8\uc81c\ub098 \uac19\uc740 \ub0a0 \uc644\uc131\ub418\ub294 \uac83\uc740 \uc544\ub2d8\uc744 \ubcf4\uc5ec \uc900\ub2e4. 1796\ub144\uc758 \uc2dc\ub3c4\uac00 \uc758\ubbf8 \uc788\uc5c8\ub2e4\uace0 \uadf8 \ud55c \ubc88\uc73c\ub85c \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \ud6a8\uacfc\uc640 \uc548\uc804\uc131\uc774 \ud655\uc778\ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. \ub354 \ub9ce\uc740 \uacbd\ud5d8\uacfc \uac80\ud1a0, \uc0dd\uc0b0\uacfc \ubcf4\uae09\uc758 \ubb38\uc81c\uac00 \ub4a4\uc5d0 \ub0a8\uc544 \uc788\uc5c8\ub2e4. \uac1c\uc778\uc758 \uad00\ucc30\uc774 \uc0ac\ud68c\uc758 \uc758\ub8cc\ub85c \uc774\uc5b4\uc9c0\ub824\uba74 \uc5ec\ub7ec \ub2e8\uacc4\uac00 \ud544\uc694\ud558\ub2e4. \uad50\uc7ac\ub294 \uc81c\ub108 \uc774\ud6c4 \ud30c\uc2a4\ud1f4\ub974\ub97c \ube44\ub86f\ud55c \uc5f0\uad6c\uc790\ub4e4\uc774 \ub2e4\ub978 \uc9c8\ubcd1\uc758 \uc608\ubc29\uc73c\ub85c \uae38\uc744 \ub113\ud600 \uac14\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubc31\uc2e0\uc758 \uc5ed\uc0ac\ub294 \ud55c \ubb3c\uc9c8\uc758 \uc131\uacf5\uc744 \uadf8\ub300\ub85c \ubcf5\uc81c\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc9c8\ubcd1\uacfc \ubc29\ubc95\uc5d0 \ub9de\ucd94\uc5b4 \uc0c8\ub85c\uc6b4 \uadfc\uac70\ub97c \uc313\uc544 \uac04 \uacfc\uc815\uc774\uc5c8\ub2e4. \uc720\uba85\ud55c \uc774\ub984\uc740 \uc81c\ub108\uc9c0\ub9cc \ubc30\uacbd\uc5d0\ub294 \uc6b0\uc720\ub97c \uc9dc\ub358 \uc0ac\ub78c\ub4e4\uc758 \uacbd\ud5d8\uacfc \uc774\uc804\uc758 \uc608\ubc29 \uad00\ud589, \uc2dc\ub3c4\uc5d0 \ucc38\uc5ec\ud55c \uc544\uc774\uac00 \uc788\uc5c8\ub2e4. \ubc1c\uacac\uc774 \ud55c \uc0ac\ub78c\uc758 \uba38\ub9ac \uc548\uc5d0\uc11c\ub9cc \uc774\ub8e8\uc5b4\uc9c4 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uacbd\ud5d8\uc744 \ub204\uac00 \ub4e3\uace0 \uc5b4\ub5a4 \ubb38\uc81c\ub85c \ubc14\uafb8\uc5c8\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uba74 \uc774\uc57c\uae30\uac00 \ub113\uc5b4\uc9c4\ub2e4. \uc774\ub7f0 \uc2dc\uc120\uc740 \uacf5\ub85c\ub97c \uc5c6\uc560\ub824\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uad00\ucc30\ud55c \uc0ac\ub78c\uacfc \uc2e4\ud5d8\ud55c \uc0ac\ub78c, \uc704\ud5d8\uc744 \uac10\uc218\ud55c \uc0ac\ub78c\uc758 \uc790\ub9ac\uac00 \uac19\uc9c0 \uc54a\uc558\uc74c\uc744 \ud568\uaed8 \ubcf4\ub824\ub294 \uac83\uc774\ub2e4. \uacfc\ud559\uc758 \uc131\uacfc\ub97c \uc18c\uc911\ud788 \uc5ec\uae30\ub294 \uc77c\uc740 \uadf8 \uc131\uacfc\ub97c \uac00\ub2a5\ud558\uac8c \ud55c \uad00\uacc4\uc640 \ucc45\uc784\uc744 \uc0b4\ud53c\ub294 \uc77c\uacfc \ud568\uaed8 \uac08 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 18\uc138\uae30 \ub9d0 \ub18d\ucd0c\uc5d0\uc11c \uc758\uc0ac\uc640 \uc6b0\uc720 \uc9dc\ub294 \uc0ac\ub78c\uc774 \ub300\ud654\ud558\ub294 \uc0c1\uc0c1 \uc18d \uc7a5\uba74\uc774\ub2e4. \uc81c\ub108\uc758 \uc2e4\uc81c \ucd08\uc0c1\uc774\ub098 \uae30\ub85d\ub41c \ub9cc\ub0a8\uc744 \uc7ac\ud604\ud558\uc9c0 \uc54a\uc558\ub2e4. \uc5b4\ub9b0\uc774\uc5d0\uac8c \uc2dc\ud589\ub41c \uc2e4\ud5d8\uc744 \uadf8\ub9b0 \uc790\ub8cc\ub3c4 \uc544\ub2c8\ub2e4. \uc77c\uc0c1\uc758 \uad00\ucc30\uacfc \uc9c8\ubb38\uc758 \uad00\uacc4\ub97c \ud45c\ud604\ud588\ub2e4. \uc81c\ub108\uc758 \uc774\uc57c\uae30\ub97c \uc77d\uace0 \ub098\uba74 \ubc31\uc2e0\uc740 \uc644\uc131\ub41c \uc6d0\ub9ac\ub97c \uc678\uc6b0\ub294 \ub2e8\uc5b4\ubcf4\ub2e4 \uae34 \uc2dc\uac04\uc744 \uac00\uc9c4 \uc774\ub984\uc774 \ub41c\ub2e4. \ubcd1\uc744 \ub9c9\uace0 \uc2f6\uc5c8\ub358 \uc0ac\ub78c\ub4e4\uc758 \ud544\uc694\uc640 \uc55e\uc120 \uad00\ud589, \uc0c8\ub85c\uc6b4 \uc2dc\ud5d8\uacfc \uc724\ub9ac\uc758 \uc9c8\ubb38\uc774 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4. \uadf8 \uacfc\uc815\uc744 \uc77d\ub294 \uac83\uc774 \ubc1c\uacac\uc744 \ub354 \uae4a\uac8c \uc774\ud574\ud558\ub294 \uacfc\ud559\uc0ac\uc758 \uc990\uac70\uc6c0\uc774\ub2e4."}, {"id": "john-snow-pump-and-evidence", "title": "\uc874 \uc2a4\ub178 \u2014 \ud38c\ud504 \uc190\uc7a1\uc774\ubcf4\ub2e4 \uba3c\uc800 \ubc14\uafbc \uc9c8\ubb38", "summary": "\uc874 \uc2a4\ub178\uc758 1855\ub144 \uc800\uc220\uacfc \uc2e4\uc81c \uc9c0\ub3c4\ub97c \ud1b5\ud574 \ucf5c\ub808\ub77c \uc870\uc0ac\u00b7\uae09\uc218\uc6d0 \ube44\uad50\u00b7\uc720\ud589 \uac10\uc18c\uc758 \ud574\uc11d\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uacfc\ud559\uc790\uc758 \ubc1c\uacac", "categories": ["science"], "url": "stories/john-snow-pump-and-evidence/index.html", "image": "../media/john-snow-pump-and-evidence.jpg", "alt": "\uc874 \uc2a4\ub178\uc758 1855\ub144 \uc800\uc11c \uc9c0\ub3c4 1. \ube0c\ub85c\ub4dc \uc2a4\ud2b8\ub9ac\ud2b8 \uc8fc\ubcc0 \uc0ac\ub9dd\uacfc \ud38c\ud504 \uc704\uce58", "text": "\uc874 \uc2a4\ub178 \u2014 \ud38c\ud504 \uc190\uc7a1\uc774\ubcf4\ub2e4 \uba3c\uc800 \ubc14\uafbc \uc9c8\ubb38 1854\ub144 \ub7f0\ub358\uc5d0\uc11c \ub204\uac00 \uc5b4\ub5a4 \ubb3c\uc744 \ub9c8\uc168\ub294\uc9c0 \ubb3b\ub2e4 \uc874 \uc2a4\ub178\uc758 1855\ub144 \uc800\uc220\uacfc \uc2e4\uc81c \uc9c0\ub3c4\ub97c \ud1b5\ud574 \ucf5c\ub808\ub77c \uc870\uc0ac\u00b7\uae09\uc218\uc6d0 \ube44\uad50\u00b7\uc720\ud589 \uac10\uc18c\uc758 \ud574\uc11d\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uacfc\ud559\uc790\uc758 \ubc1c\uacac \uacfc\ud559\uacfc \ubc1c\uacac \uc9c0\ub3c4\uc5d0 \uc791\uc740 \ud45c\uc2dc\ub4e4\uc774 \ubaa8\uc5ec \uc788\ub2e4. \uc7a5\uc2dd\uc774\ub098 \uac00\uac8c\uc758 \uc704\uce58\uac00 \uc544\ub2c8\ub77c \uc0ac\ub78c\ub4e4\uc774 \uc8fd\uc740 \uc9d1\uc744 \ub098\ud0c0\ub0b8 \ud754\uc801\uc774\ub2e4. 1854\ub144 \ub7f0\ub358\uc758 \ucf5c\ub808\ub77c\ub97c \uc870\uc0ac\ud55c \uc758\uc0ac \uc874 \uc2a4\ub178\ub294 \ub204\uac00 \ubcd1\uc5d0 \uac78\ub838\ub294\uc9c0\ub9cc\ud07c \uadf8\ub4e4\uc774 \uc5b4\ub5a4 \ubb3c\uc744 \ub9c8\uc168\ub294\uc9c0 \ubb3c\uc5c8\ub2e4. \uc720\uba85\ud55c \uacb0\ub9d0\uc740 \ube0c\ub85c\ub4dc \uc2a4\ud2b8\ub9ac\ud2b8 \ud38c\ud504\uc758 \uc190\uc7a1\uc774\ub97c \ub5bc\uc5b4 \ub0c8\ub2e4\ub294 \uc774\uc57c\uae30\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \uc7a5\uba74\ub9cc \uae30\uc5b5\ud558\uba74 \uadf8 \uc55e\uc758 \uc9c8\ubb38\uacfc \ub4a4\uc758 \uc2e0\uc911\ud55c \ud574\uc11d\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \uc2a4\ub178\uac00 1855\ub144\uc5d0 \ub0b8 \ucc45\uc744 \uc77d\uc73c\uba74 \uc9c0\ub3c4\uc640 \uc0ac\ub78c\ub4e4\uc758 \ub300\ub2f5\uc774 \uc5b4\ub5bb\uac8c \uc99d\uac70\uac00 \ub418\uc5c8\ub294\uc9c0 \ub354 \uc790\uc138\ud788 \ubcf4\uc778\ub2e4. \uc2a4\ub178\ub294 1848~1849\ub144\uc758 \ucf5c\ub808\ub77c \uacbd\ud5d8\uc744 \ubc14\ud0d5\uc73c\ub85c \ubb3c\uacfc \uac10\uc5fc\uc758 \uad00\uacc4\ub97c \uc758\uc2ec\ud588\ub2e4. \ub098\uc05c \uacf5\uae30\ub9cc\uc73c\ub85c \ubcd1\uc758 \ubd84\ud3ec\ub97c \uc124\uba85\ud558\uae30\ubcf4\ub2e4 \uc0ac\ub78c\ub4e4\uc774 \uc2e4\uc81c\ub85c \ubb34\uc5c7\uc744 \ub9c8\uc168\ub294\uc9c0 \uc0b4\ud3c8\ub2e4. \uc775\uc219\ud55c \uc124\uba85\uc744 \ubc14\uafb8\ub824\uba74 \ub2e4\ub978 \uc885\ub958\uc758 \uc9c8\ubb38\uc744 \ub358\uc838\uc57c \ud588\ub2e4. 1854\ub144 \uadf8\ub294 \ube0c\ub85c\ub4dc \uc2a4\ud2b8\ub9ac\ud2b8 \uc8fc\ubcc0\uc758 \uc9d1\uacfc \uc0ac\ub9dd\uc790\uc758 \uc8fc\uc18c\ub97c \uc870\uc0ac\ud588\ub2e4. \ubcd1\uc774 \uc0dd\uae34 \uc704\uce58\ub97c \uc9c0\ub3c4\ub85c \uc62e\uae30\uba74 \uac70\ub9ac\uc758 \uc778\uc0c1\ubcf4\ub2e4 \uad6c\uccb4\uc801\uc778 \ubd84\ud3ec\ub97c \ubcfc \uc218 \uc788\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \uc9c0\ub3c4\uc5d0 \ud45c\uc2dc\uac00 \ubaa8\uc600\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc6d0\uc778\uc774 \uc790\ub3d9\uc73c\ub85c \uc99d\uba85\ub418\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uadf8\ub2e4\uc74c\uc5d0 \uc0ac\ub78c\ub4e4\uc758 \uc0dd\ud65c\uc744 \ud655\uc778\ud574\uc57c \ud588\ub2e4. \ub2f9\uc2dc \uc8fc\ubbfc\ub4e4\uc740 \ub3d9\ub124 \ud38c\ud504\uc5d0\uc11c \ubb3c\uc744 \uc5bb\uc5c8\ub2e4. \uc2a4\ub178\ub294 \uc0ac\ub9dd\uc790\uc758 \uc9d1\uc774 \uc5b4\ub290 \ud38c\ud504\uc640 \uac00\uae4c\uc6b4\uc9c0\ubfd0 \uc544\ub2c8\ub77c \uc2e4\uc81c\ub85c \uadf8 \ubb3c\uc744 \uc774\uc6a9\ud588\ub294\uc9c0 \ud655\uc778\ud588\ub2e4. \uac00\uae4c\uc6b4 \uacf3\uc5d0 \uc0b0\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8\uacf3\uc758 \ubb3c\uc744 \ub9c8\uc168\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub97c \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc2e4\uc81c \uc9c0\ub3c4\ub294 \uadf8\uc758 1855\ub144 \ucc45\uc5d0 \uc2e4\ub9b0 \uccab \ubc88\uc9f8 \uc9c0\ub3c4\ub2e4. \uc791\uc740 \ud45c\uc2dc\ub4e4\uc740 \ud655\uc778\ud55c \uc0ac\ub9dd\uc758 \uc704\uce58\ub97c \ub098\ud0c0\ub0b8\ub2e4. \uc624\ub298\uc758 \uac10\uc5fc\uc790 \uc2e4\uc2dc\uac04 \ud604\ud669\ub3c4\ub098 \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \uc774\ub3d9 \uae30\ub85d\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uc790\ub8cc\uac00 \uc9c0\ub3c4\uc5d0 \ub4e4\uc5b4 \uc788\ub294\uc9c0 \uc54c\uba74 \uc720\uba85\ud55c \uadf8\ub9bc\ub3c4 \ub354 \uc815\ud655\ud558\uac8c \uc77d\uc744 \uc218 \uc788\ub2e4. \uc2a4\ub178\uc758 \ucc45\uc5d0\ub294 \ud38c\ud504\uc640 \ub5a8\uc5b4\uc838 \uc0ac\ub294 \uc0ac\ub78c\uc774 \uadf8 \ubb3c\uc758 \ub9db\uc744 \uc88b\uc544\ud574 \uac00\uc838\ub2e4 \ub9c8\uc168\ub2e4\ub294 \uc0ac\ub840\uac00 \ub098\uc628\ub2e4. \uac00\uae4c\uc774 \uc0b4\uc9c0 \uc54a\uc544\ub3c4 \uac19\uc740 \ubb3c\uc744 \uc774\uc6a9\ud558\uba74 \uc870\uc0ac\uc5d0\uc11c \uc911\uc694\ud574\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \ubc18\ub300\ub85c \uac19\uc740 \uc9c0\uc5ed\uc5d0 \uc788\uc5b4\ub3c4 \ub2e4\ub978 \ubb3c\uc744 \uc774\uc6a9\ud55c \uacf3\uc740 \ube44\uad50\uc758 \ub300\uc0c1\uc774 \ub418\uc5c8\ub2e4. \uc774\ub7f0 \uc0ac\ub840\ub294 \uc9c0\ub3c4\uc5d0\uc11c \uba3c \uc810\uc744 \uc608\uc678\ub85c \ubc84\ub9ac\uc9c0 \uc54a\uace0 \uc65c \uadf8\ub7f0 \uc77c\uc774 \uc0dd\uacbc\ub294\uc9c0 \ub2e4\uc2dc \ubb3b\ub294 \ud0dc\ub3c4\ub97c \ubcf4\uc5ec \uc900\ub2e4. \uc798 \ub4e4\uc5b4\ub9de\ub294 \uc9d1\ub9cc \ubaa8\uc73c\uba74 \uc774\uc57c\uae30\ub294 \uae54\ub054\ud574\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc6d0\uc778\uc744 \uc54c\uc544\ubcf4\ub824\uba74 \uc124\uba85\uc774 \uc5b4\ub824\uc6b4 \uc0ac\ub840\uc640 \ubcd1\uc5d0 \uac78\ub9ac\uc9c0 \uc54a\uc740 \uc0ac\ub78c\ub4e4\uc758 \uc870\uac74\ub3c4 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc2a4\ub178\ub294 \ub3d9\ub124 \ud38c\ud504\ub9cc \uc870\uc0ac\ud558\uc9c0 \uc54a\uc558\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc218\ub3c4\ud68c\uc0ac\uc758 \ubb3c\uc744 \ubc1b\ub294 \uc9d1\ub4e4\uc758 \uc0ac\ub9dd \uc591\uc0c1\ub3c4 \ube44\uad50\ud588\ub2e4. \ud55c \ud68c\uc0ac\ub294 \uac15\uc758 \ub354 \uae68\ub057\ud55c \uad6c\uac04\uc73c\ub85c \uae09\uc218\uc6d0\uc744 \uc62e\uacbc\uace0 \ub2e4\ub978 \ud68c\uc0ac\uc758 \ubb3c\uc5d0\ub294 \ud558\uc218\uc758 \uc601\ud5a5\uc774 \ub354 \ub0a8\uc544 \uc788\uc5c8\ub2e4. \ubb3c\uc758 \ucd9c\ucc98\uac00 \uc870\uc0ac\uc5d0\uc11c \uc911\uc694\ud55c \uad6c\ubd84\uc774 \ub418\uc5c8\ub2e4. \uc0ac\ub78c\uc744 \uc77c\ubd80\ub7ec \uc704\ud5d8\uc5d0 \ub178\ucd9c\ud574 \ubcf4\uc9c0 \uc54a\uace0 \uc774\ubbf8 \ub2e4\ub978 \uc870\uac74\uc5d0 \ub193\uc778 \uc9d1\ub4e4\uc744 \ube44\uad50\ud55c \uac83\uc774\ub2e4. \ubb3c\ub860 \uc8fc\uc18c\uc640 \uae09\uc218\uc6d0, \uc0ac\ub9dd \uae30\ub85d\uc744 \uc815\ud655\ud788 \ub9de\ucd94\ub294 \uc5b4\ub824\uc6c0\uc774 \uc788\uc5c8\ub2e4. \uc2a4\ub178\uc758 \uc791\uc5c5\uc740 \uc9c0\ub3c4 \ud55c \uc7a5\uc758 \ubc88\ub729\uc784\ubcf4\ub2e4 \uc5ec\ub7ec \uc790\ub8cc\ub97c \uc5f0\uacb0\ud558\ub294 \uc218\uace0\uc5d0 \uac00\uae4c\uc6e0\ub2e4. \uc2a4\ub178\uc758 \uc870\uc5b8\uc5d0 \ub530\ub77c \uc9c0\uc5ed \uad00\uacc4\uc790\ub4e4\uc740 \ube0c\ub85c\ub4dc \uc2a4\ud2b8\ub9ac\ud2b8 \ud38c\ud504\uc758 \uc190\uc7a1\uc774\ub97c \uc81c\uac70\ud588\ub2e4. \uc704\ud5d8\ud55c \ubb3c\uc77c \uac00\ub2a5\uc131\uc774 \uc788\ub294 \uacf5\uae09\uc6d0\uc744 \ub354 \uc774\uc0c1 \uc774\uc6a9\ud558\uc9c0 \ubabb\ud558\uac8c \ud558\ub294 \uc870\uce58\uc600\ub2e4. \uc6d0\uc778\uc758 \ubaa8\ub4e0 \uc138\ubd80\uac00 \uc644\uc131\ub418\uae30 \uc804\uc5d0\ub3c4 \uacf5\uc911\ubcf4\uac74\uc744 \uc704\ud55c \ud310\ub2e8\uc774 \ud544\uc694\ud588\ub2e4. \uadf8\ub7ec\ub098 \uc190\uc7a1\uc774\ub97c \ub5c0 \uc21c\uac04\ubd80\ud130 \uc720\ud589\uc774 \ucc98\uc74c \uc904\uc5c8\ub2e4\uace0 \ub2e8\uc815\ud558\uba74 \uc6d0\ubb38\uacfc \ub2ec\ub77c\uc9c4\ub2e4. \uc2a4\ub178\ub294 \uc790\uc2e0\uc758 \ucc45\uc5d0\uc11c \uadf8\uc804\uc5d0 \uc774\ubbf8 \ubc1c\uc0dd\uc774 \uac10\uc18c\ud588\uace0 \ub9ce\uc740 \uc8fc\ubbfc\uc774 \ub5a0\ub0ac\ub2e4\ub294 \uc810\uc744 \uc801\uc5c8\ub2e4. \uc870\uce58\uc640 \uacb0\uacfc\ub97c \ud568\uaed8 \uae30\ub85d\ud558\uba74\uc11c\ub3c4 \ub2e8\uc21c\ud55c \uc778\uacfc\ub85c \uacfc\uc7a5\ud558\uc9c0 \uc54a\uc740 \uac83\uc774\ub2e4. \uadf8\ub294 \ubb3c\uc758 \uc0ac\uc6a9\uc744 \ub9c9\uae30 \uc804\ubd80\ud130 \uc720\ud589\uc774 \uc904\uc5c8\uc73c\ubbc0\ub85c \uadf8\ub54c \uc6b0\ubb3c \uc548\uc758 \uc704\ud5d8\uc774 \uacc4\uc18d \ub0a8\uc544 \uc788\uc5c8\ub294\uc9c0 \ud310\ub2e8\ud558\uae30 \uc5b4\ub835\ub2e4\uace0 \uc37c\ub2e4. \ud604\uc7a5\uc5d0\uc11c \uc5bb\uc740 \uc99d\uac70\uac00 \uc5b4\ub514\uae4c\uc9c0 \ub2f5\ud560 \uc218 \uc788\ub294\uc9c0 \uc2a4\uc2a4\ub85c \uc120\uc744 \uadf8\uc5c8\ub2e4. \uc720\uba85\ud55c \uc131\uacf5\ub2f4\ubcf4\ub2e4 \uc774\ub7f0 \ubb38\uc7a5\uc774 \uc5f0\uad6c\uc758 \ud0dc\ub3c4\ub97c \uc798 \ubcf4\uc5ec \uc8fc\uae30\ub3c4 \ud55c\ub2e4. \ubb3c\uacfc \ucf5c\ub808\ub77c\uc758 \uad00\uacc4\ub97c \uc9c0\uc9c0\ud558\ub294 \uc5ec\ub7ec \uc99d\uac70\uac00 \uc788\ub2e4\uace0 \ud574\uc11c \ud55c \uc870\uce58\uc758 \ud6a8\uacfc\ub97c \uc815\ud655\ud788 \ubd84\ub9ac\ud574 \uce21\uc815\ud55c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc774 \ub450 \ubb38\uc7a5\uc740 \ud568\uaed8 \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4. \uadfc\uac70\ub97c \uc313\ub294 \uc77c\uc740 \ud655\uc2e0\uc744 \ud06c\uac8c \ub9d0\ud558\ub294 \uc77c\uacfc \ubc18\ub4dc\uc2dc \uac19\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2a4\ub178\uac00 \uc624\ub298\uc758 \ubbf8\uc0dd\ubb3c\ud559 \uc9c0\uc2dd\uc744 \ubaa8\ub450 \uac16\uace0 \uc2dc\uc791\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub294 \uac10\uc5fc \uacbd\ub85c\uc5d0 \uad00\ud55c \uac00\uc124\uc744 \uc138\uc6b0\uace0 \uad00\ucc30\uacfc \uae30\ub85d\uc744 \ube44\uad50\ud588\ub2e4. \ud604\ubbf8\uacbd\uc73c\ub85c \ubcd1\uc6d0\uccb4\ub97c \uc644\ubcbd\ud788 \uaddc\uba85\ud558\ub294 \uc77c\uacfc \uc0dd\ud65c\uc758 \uc790\ub8cc\uc5d0\uc11c \uc704\ud5d8\ud55c \uacbd\ub85c\ub97c \ucc3e\uc544\ub0b4\ub294 \uc77c\uc740 \ub2e4\ub978 \ubc29\uc2dd\uc758 \uc5f0\uad6c\uc600\ub2e4. \uad50\uc7ac\ub294 \uc774\ub7f0 \uc0ac\ub840\ub97c \ud604\ub300 \uc5ed\ud559\uc758 \ubc1c\uc804\uacfc \uc5f0\uacb0\ud55c\ub2e4. \ub2e4\ub9cc \uc774\uac83\uc774 \uc778\ub958 \ucd5c\ucd08\uc758 \ubaa8\ub4e0 \uc720\ud589\ubcd1 \ub300\uc751\uc774\uc5c8\ub2e4\uace0 \ud655\ub300\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc55e\uc120 \uc0ac\ub78c\ub4e4\uc758 \uc608\ubc29\uacfc \uc870\uc0ac\ub3c4 \uc788\uc5c8\ub2e4. \uc2a4\ub178\uc758 \uacf5\ub85c\ub294 \uad6c\uccb4\uc801\uc778 \uc9c8\ubb38\uacfc \uc790\ub8cc \uc5f0\uacb0\uc758 \ubc29\uc2dd \uc18d\uc5d0\uc11c \uc77d\uc744 \ub54c \ub354 \ubd84\uba85\ud574\uc9c4\ub2e4. \uc774 \uc9c0\ub3c4\ub294 \uadf8 \uc790\uccb4\uac00 \uc815\ub2f5\uc744 \ub9d0\ud558\ub294 \uadf8\ub9bc\uc774 \uc544\ub2c8\ub2e4. \ub204\uac00 \uc5b4\ub514\uc5d0 \uc0b4\uc558\uace0 \uc5b4\ub5a4 \ubb3c\uc744 \ub9c8\uc168\ub294\uc9c0 \ubb3c\uc740 \uacb0\uacfc\uac00 \ud45c\uc2dc\ub418\uc5b4 \uc788\ub2e4. \uc6b0\ub9ac\uac00 \uae30\uc5b5\ud558\ub294 \ud38c\ud504 \uc190\uc7a1\uc774\ub294 \uadf8 \uae34 \uc870\uc0ac \uac00\uc6b4\ub370 \ub208\uc5d0 \uc798 \ubcf4\uc774\ub294 \ud55c \uc7a5\uba74\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \uc9c8\ubcd1 \uc9c0\ub3c4\ub97c \ub9cc\ub098\uba74 \ud45c\uc2dc\uc758 \uc218\ub9cc \ubcf4\uc9c0 \ub9d0\uace0 \ubb34\uc5c7\uc744 \uc138\uc5c8\uc73c\uba70 \uc5b4\ub5a4 \ube44\uad50\uac00 \uac00\ub2a5\ud55c\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc2a4\ub178\uc758 \uae30\ub85d\uc740 \uc608\uc678\uc640 \ud55c\uacc4\uae4c\uc9c0 \ub0a8\uae38 \ub54c \uc5f0\uad6c\uac00 \ub354 \uc124\ub4dd\ub825 \uc788\uc5b4\uc9c8 \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ud55c \ub3d9\ub124\uc758 \ubb3c\uc744 \ub530\ub77c\uac04 \uc9c8\ubb38\uc740 \uc0ac\ub78c\ub4e4\uc758 \uc0dd\ud65c\uacfc \uacfc\ud559\uc758 \uc99d\uac70\ub97c \ud568\uaed8 \ubc14\uafb8\uc5c8\ub2e4."}, {"id": "joule-paddles-work-and-heat", "title": "\uc904\uc758 \uc2e4\ud5d8 \u2014 \ubb3c\uc744 \ub370\uc6b0\ub294 \ub370 \ubd88\uc774 \uaf2d \ud544\uc694\ud560\uae4c", "summary": "\ucd94\uac00 \ubb3c\uc18d \ub0a0\uac1c\ub97c \ub3cc\ub9ac\ub294 \uc2e4\ud5d8\uacfc \uc628\ub3c4 \uce21\uc815\uc744 \ud1b5\ud574 \uc5f4\uacfc \uc77c\uc744 \uc218\ub7c9\uc73c\ub85c \uc5f0\uacb0\ud55c \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\ubb3c\uc9c8\uacfc \uc5d0\ub108\uc9c0", "categories": ["science"], "url": "stories/joule-paddles-work-and-heat/index.html", "image": "../media/joule-paddles-work-and-heat.png", "alt": "\ucd94\uc640 \uc904, \ubb3c\ud1b5\uacfc \ub0a0\uac1c \uc7a5\uce58\ub97c \uc0b4\ud53c\ub294 \uc5f0\uad6c\uc790\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uc904\uc758 \uc2e4\ud5d8 \u2014 \ubb3c\uc744 \ub370\uc6b0\ub294 \ub370 \ubd88\uc774 \uaf2d \ud544\uc694\ud560\uae4c \ucd94\uc640 \ud328\ub4e4, \uc628\ub3c4\uacc4\uac00 \uc5f0\uacb0\ud55c \uc77c\uacfc \uc5d0\ub108\uc9c0\uc758 \uce21\uc815 \ucd94\uac00 \ubb3c\uc18d \ub0a0\uac1c\ub97c \ub3cc\ub9ac\ub294 \uc2e4\ud5d8\uacfc \uc628\ub3c4 \uce21\uc815\uc744 \ud1b5\ud574 \uc5f4\uacfc \uc77c\uc744 \uc218\ub7c9\uc73c\ub85c \uc5f0\uacb0\ud55c \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ubb3c\uc9c8\uacfc \uc5d0\ub108\uc9c0 \uacfc\ud559\uacfc \ubc1c\uacac \ubb3c\uc744 \ub370\uc6b4\ub2e4\uace0 \ud558\uba74 \ubd88\uc774\ub098 \ub728\uac70\uc6b4 \ubb3c\uccb4\ub97c \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7f0\ub370 \ucd94\ub97c \ub5a8\uc5b4\ub728\ub824 \ubb3c\uc18d\uc758 \ub0a0\uac1c\ub97c \ub3cc\ub824\ub3c4 \ubb3c\uc758 \uc628\ub3c4\uac00 \uc62c\ub77c\uac04\ub2e4. \uc81c\uc784\uc2a4 \ud504\ub808\uc2a4\ucf67 \uc904\uc758 \uc2e4\ud5d8\uc740 \uae30\uacc4\uc801\uc778 \uc77c\uacfc \uc5f4\uc758 \uad00\uacc4\ub97c \uc218\ub7c9\uc73c\ub85c \ube44\uad50\ud558\ub294 \ub370 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud588\ub2e4. \uc775\uc219\ud55c \uc628\ub3c4 \ubcc0\ud654\uc5d0\uc11c \uc5d0\ub108\uc9c0\ub77c\ub294 \uacf5\ud1b5 \uc5b8\uc5b4\uac00 \ub4dc\ub7ec\ub098\ub294 \uacfc\uc815\uc744 \uc0b4\ud3b4\ubcf4\uc790. \uc628\ub3c4\ub294 \ubb3c\uccb4\uc758 \uc0c1\ud0dc\ub97c \ub098\ud0c0\ub0b4\ub294 \uac12\uc774\ub2e4. \uc5f4\uc740 \uc628\ub3c4 \ucc28\uc774 \ub54c\ubb38\uc5d0 \uc5d0\ub108\uc9c0\uac00 \uc774\ub3d9\ud558\ub294 \uacfc\uc815\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uac19\uc740 \uc628\ub3c4\ub77c\ub3c4 \ubb3c\uc758 \uc591\uc774 \ub2e4\ub974\uba74 \uc628\ub3c4\ub97c \uc77c\uc815\ud558\uac8c \uc62c\ub9ac\ub294 \ub370 \ud544\uc694\ud55c \uc5d0\ub108\uc9c0\ub294 \ub2ec\ub77c\uc9c4\ub2e4. \uc628\ub3c4\uacc4 \uc22b\uc790\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc870\uac74\uc744 \uc54c \uc218\ub294 \uc5c6\ub2e4. \uc774 \uad6c\ubd84\uc740 \uc904\uc758 \uc2e4\ud5d8\uc744 \uc774\ud574\ud560 \ub54c\ub3c4 \ud544\uc694\ud558\ub2e4. \ubb3c\uc758 \uc628\ub3c4\uac00 \uc870\uae08 \uc62c\ub790\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c\uc558\ub2e4\uba74, \uc5bc\ub9c8\ub098 \ub9ce\uc740 \ubb3c\uc774 \uc788\uc5c8\ub294\uc9c0\uc640 \uadf8 \ubb3c\uc9c8\uc758 \uc131\uc9c8\uc744 \ud568\uaed8 \uc54c\uc544\uc57c \ud55c\ub2e4. \uc791\uc740 \uc628\ub3c4 \ubcc0\ud654\uac00 \uace7 \uc544\uc8fc \uc791\uc740 \uc5d0\ub108\uc9c0\ub97c \ub73b\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc904\uc758 \uc720\uba85\ud55c \uc7a5\uce58\uc5d0\uc11c\ub294 \ub0b4\ub824\uac00\ub294 \ucd94\uac00 \ucd95\uacfc \ub0a0\uac1c\ub97c \uc6c0\uc9c1\uc778\ub2e4. \ucd94\uc758 \uc704\uce58 \uc5d0\ub108\uc9c0\uac00 \uc7a5\uce58\uc758 \uc6c0\uc9c1\uc784\uc744 \uac70\uccd0 \ubb3c\uc5d0 \uc804\ub2ec\ub41c\ub2e4. \ubb3c\uc18d \ub0a0\uac1c\ub294 \ubb3c\uc744 \ud718\uc813\uace0 \uadf8 \uacfc\uc815\uc5d0\uc11c \ubb3c\uc758 \ub0b4\ubd80 \uc5d0\ub108\uc9c0\uac00 \uc99d\uac00\ud55c\ub2e4. \uc2e4\ud5d8\uc740 \uc11c\ub85c \ub2ec\ub77c \ubcf4\uc774\ub294 \ubcc0\ud654\ub4e4\uc744 \ud558\ub098\uc758 \uc5f0\uacb0\ub85c \ub193\ub294\ub2e4. \ucd94\uac00 \uc5bc\ub9c8\ub098 \ubb34\uac81\uace0 \uc5bc\ub9c8\ub098 \ub0b4\ub824\uac14\ub294\uc9c0\ub97c \uc54c\uba74 \uac00\ud55c \uc77c\uc744 \uacc4\uc0b0\ud560 \uc218 \uc788\ub2e4. \ubb3c\uc758 \uc591\uacfc \uc628\ub3c4 \ubcc0\ud654\ub97c \uc54c\uba74 \uadf8 \ubcc0\ud654\ub97c \uc77c\uc73c\ud0a8 \uc5d0\ub108\uc9c0\ub97c \ube44\uad50\ud560 \uc218 \uc788\ub2e4. \ub5a8\uc5b4\uc9c0\ub294 \ubb3c\uccb4\uc640 \uc62c\ub77c\uac00\ub294 \uc628\ub3c4\uacc4\uac00 \uac19\uc740 \uc7a5\uce58 \uc548\uc5d0\uc11c \ub9cc\ub098\ub294 \uc774\uc720\ub2e4. \ub9c8\ucc30\ub85c \ub530\ub73b\ud574\uc9c0\ub294 \uacbd\ud5d8 \uc790\uccb4\ub294 \ub0af\uc124\uc9c0 \uc54a\ub2e4. \ub450 \uc190\uc744 \ube44\ube44\uba74 \uc628\uae30\uac00 \ub290\uaef4\uc9c4\ub2e4. \uc904\uc758 \uc791\uc5c5\uc5d0\uc11c \uc911\uc694\ud55c \uac83\uc740 \uadf8\ub7f0 \uacbd\ud5d8\uc744 \uc815\ubc00\ud55c \uc591\uc758 \uad00\uacc4\ub85c \ubc14\uafb8\ub824 \ud588\ub2e4\ub294 \uc810\uc774\ub2e4. \uc77c\uc774 \uc5bc\ub9c8 \ub4e4\uc5b4\uac00\uba74 \uc5b4\ub5a4 \uc628\ub3c4 \ubcc0\ud654\uac00 \uc0dd\uae30\ub294\uc9c0\ub97c \ube44\uad50\ud588\ub2e4. \uc9c8\ub7c9\uacfc \ub192\uc774, \ubb3c\uc758 \uc591\uacfc \uc628\ub3c4\ub97c \uac01\uac01 \uce21\uc815\ud574\uc57c \ud588\ub2e4. \uc5b4\ub290 \ud55c \uac12\uc774 \ub300\ub7b5\uc801\uc774\uba74 \ub2e4\ub978 \uac12\ub4e4\uacfc\uc758 \ube44\uad50\ub3c4 \ud754\ub4e4\ub9b0\ub2e4. \uacfc\ud559\uc801 \ub17c\uc99d\uc740 \ub180\ub77c\uc6b4 \uc7a5\uba74\ub9cc\uc774 \uc544\ub2c8\ub77c \uc11c\ub85c \ub2e4\ub978 \uce21\uc815\uc744 \uac19\uc740 \uc9c8\ubb38\uc5d0 \uc5f0\uacb0\ud558\ub294 \ubc29\uc2dd\uc5d0\uc11c \ud798\uc744 \uc5bb\ub294\ub2e4. \ucd94\uc758 \ub192\uc774\uac00 \uc870\uae08\uc529 \ub2ec\ub77c\uc9c0\uba74 \ubb3c\uc5d0 \uc804\ub2ec\ud558\ub824 \ud55c \uc77c\uc758 \uc591\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \ubb3c\uc758 \uc870\uac74\uc744 \uc815\ud574 \ub450\uace0 \uc774 \ubcc0\ud654\uc5d0 \uc628\ub3c4\uac00 \uc5b4\ub5bb\uac8c \ub300\uc751\ud558\ub294\uc9c0 \ube44\uad50\ud558\uba74, \ub2e8\uc21c\ud788 \ucc98\uc74c\ubcf4\ub2e4 \ub530\ub73b\ud558\ub2e4\ub294 \uad00\ucc30\uc744 \ub118\uc5b4 \uc77c\uc815\ud55c \uad00\uacc4\ub97c \ucc3e\uc744 \uc218 \uc788\ub2e4. \ud1b5\uc81c\ud560 \uc870\uac74\uacfc \ubc14\uafc0 \uc870\uac74\uc744 \uad6c\ubd84\ud558\ub294 \uc2e4\ud5d8\uc758 \ud0dc\ub3c4\ub2e4. \uce21\uc815\uac12\uc744 \uc218\ub7c9\uc73c\ub85c \ud45c\ud604\ud558\uba74 \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc790\uae30 \uc7a5\uce58\uc5d0\uc11c \uac19\uc740 \uad00\uacc4\ub97c \ud655\uc778\ud560 \uc218\ub3c4 \uc788\ub2e4. \uacfc\ud559\uc801 \uacb0\uacfc\ub294 \uc5f0\uad6c\uc790 \uac1c\uc778\uc774 \ub290\ub080 \uc628\uae30\uc5d0 \uba38\ubb3c\uc9c0 \uc54a\ub294\ub2e4. \ubb34\uc5c7\uc744 \uc5bc\ub9c8\ub098 \uce21\uc815\ud588\ub294\uc9c0 \uc124\uba85\ud574\uc57c \uadf8 \uacb0\uacfc\uac00 \uacf5\uc720 \uac00\ub2a5\ud55c \ub17c\uc99d\uc774 \ub41c\ub2e4. \uc904\uc758 \uc774\ub984\uc744 \ub2e8\uc704\ub85c \uae30\uc5b5\ud558\ub294 \uc77c\uc5d0 \uc774 \uce21\uc815\uc758 \uc5ed\uc0ac\ub97c \ub354\ud558\uba74, \uc22b\uc790 \ub4a4\uc758 \uc77c\uc774 \uad6c\uccb4\uc801\uc73c\ub85c \ub5a0\uc624\ub978\ub2e4. \ub2f9\uc2dc \uc5f4\uacfc \uae30\uacc4\uc801\uc778 \uc77c\uc744 \uc11c\ub85c \ub2e4\ub978 \ub2e8\uc704\ub85c \ud45c\ud604\ud558\ub354\ub77c\ub3c4, \uc77c\uc815\ud55c \ub300\uc751 \uad00\uacc4\ub97c \uc54c\uc544\ub0b4\uba74 \ub458\uc744 \uc5f0\uacb0\ud560 \uc218 \uc788\ub2e4. \uc774\ub97c \uc5f4\uc758 \uc77c\ub2f9\ub7c9\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \uc624\ub298\uc758 \ub2e8\uc704 \uccb4\uacc4\uc5d0\uc11c\ub294 \uc904\uc774\ub77c\ub294 \uc5d0\ub108\uc9c0 \ub2e8\uc704\ub97c \uc0ac\uc6a9\ud574 \uc5ec\ub7ec \ud615\ud0dc\uc758 \uc804\ub2ec\uc744 \ube44\uad50\ud55c\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ub2e8\uc704 \uc774\ub984\ub9cc \uc554\uae30\ud558\ub294 \uc77c\uc774 \uc544\ub2c8\ub2e4. \uae30\uacc4\uac00 \ud55c \uc77c\uc774 \uc0ac\ub77c\uc9c0\ub294 \ub300\uc2e0 \ubb3c\uc758 \uc0c1\ud0dc \ubcc0\ud654\ub85c \ub098\ud0c0\ub0a0 \uc218 \uc788\ub2e4\ub294 \uad00\uc810\uc774\ub2e4. \uc6c0\uc9c1\uc784\uacfc \uc628\uae30\ucc98\ub7fc \uac10\uac01\uc801\uc73c\ub85c \ub2e4\ub978 \ud604\uc0c1\uc744 \uc5d0\ub108\uc9c0\uc758 \uc804\ud658\uc774\ub77c\ub294 \uc5b8\uc5b4\ub85c \ud568\uaed8 \uc124\uba85\ud560 \uae38\uc774 \uc5f4\ub9b0\ub2e4. \uc2e4\ud5d8 \uc7a5\uce58\uc5d0\uc11c\ub294 \ubb3c\ub9cc \uc5d0\ub108\uc9c0\ub97c \ubc1b\ub294 \uac83\uc774 \uc544\ub2d0 \uc218 \uc788\ub2e4. \uc6a9\uae30\uc640 \ub0a0\uac1c\ub3c4 \uc0c1\ud0dc\uac00 \ubcc0\ud558\uace0 \ubc14\uae65\uacfc \uc5d0\ub108\uc9c0\ub97c \uc8fc\uace0\ubc1b\uc744 \uc218 \uc788\ub2e4. \ub530\ub77c\uc11c \ubcf4\uace0 \uc2f6\uc740 \ud6a8\uacfc\uc640 \ub2e4\ub978 \uacbd\ub85c\ub97c \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ub2e8\uc21c\ud574 \ubcf4\uc774\ub294 \uc7a5\uce58\ub3c4 \uc2e4\uc81c\ub85c\ub294 \uce21\uc815 \uc870\uac74\uc744 \uc138\uc2ec\ud558\uac8c \ub2e4\ub8e8\ub294 \uc77c\uc774\ub2e4. \uc628\ub3c4 \ubcc0\ud654\uac00 \uc791\uc73c\uba74 \uc8fc\ubcc0\uc758 \uc601\ud5a5\uc774 \uacb0\uacfc\uc5d0\uc11c \ucc28\uc9c0\ud558\ub294 \ube44\uc911\ub3c4 \ucee4\uc9c8 \uc218 \uc788\ub2e4. \ubc18\ubcf5\uacfc \ube44\uad50\uac00 \ud544\uc694\ud55c \uc774\uc720\ub2e4. \ud55c \ubc88 \uc2e0\uae30\ud55c \ud604\uc0c1\uc744 \ubcf4\uc600\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc77c\uc815\ud55c \uc591\uc758 \uad00\uacc4\ub97c \uc2e0\ub8b0\ud560 \uc218 \uc788\uac8c \ud588\ub2e4\ub294 \uc0ac\uc2e4 \uc0ac\uc774\uc5d0\ub294 \uae34 \uc5f0\uad6c\uac00 \uc788\ub2e4. \uc5d0\ub108\uc9c0\uac00 \ubcf4\uc874\ub41c\ub2e4\uace0 \uae30\uacc4\uac00 \uacf5\uae09\ubc1b\uc740 \uc5d0\ub108\uc9c0\ub97c \ubaa8\ub450 \uc6b0\ub9ac\uac00 \uc6d0\ud558\ub294 \uc77c\ub85c \ub3cc\ub824\uc900\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc5ec\ub7ec \uacf3\uc73c\ub85c \ud769\uc5b4\uc838 \ud65c\uc6a9\ud558\uae30 \uc5b4\ub824\uc6cc\uc9c8 \uc218 \uc788\ub2e4. \ubcf4\uc874\uacfc \ud6a8\uc728\uc740 \uc11c\ub85c \ub2e4\ub978 \uc9c8\ubb38\uc774\ub2e4. \uc5b4\ub290 \uae30\uacc4\uc758 \uc190\uc2e4\uc744 \ub9d0\ud55c\ub2e4\uace0 \uc5d0\ub108\uc9c0\uac00 \uc6b0\uc8fc\uc5d0\uc11c \uc0ac\ub77c\uc84c\ub2e4\uace0 \uc8fc\uc7a5\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc904\uc758 \uc2e4\ud5d8\uc744 \uac70\uafb8\ub85c \uc0c1\uc0c1\ud558\uba70 \ub370\uc6cc\uc9c4 \ubb3c\uc774 \uc800\uc808\ub85c \ucd94\ub97c \ucc98\uc74c \ub192\uc774\ub85c \ubaa8\ub450 \uc62c\ub9b4 \uac83\uc774\ub77c\uace0 \uc0dd\uac01\ud574\uc11c\ub3c4 \uc548 \ub41c\ub2e4. \uacfc\uc815\uc758 \ubc29\ud5a5\uacfc \ubc14\uafc0 \uc218 \uc788\ub294 \ubc94\uc704\uc5d0\ub294 \ub2e4\ub978 \uc870\uac74\uc774 \uc788\ub2e4. \uc5d0\ub108\uc9c0 \ubcf4\uc874\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \ubcc0\ud654\uc758 \uac00\ub2a5\uc131\uc744 \ud310\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc904\uc758 \uc5f0\uad6c\ub294 \uc5f4\uc758 \ubcf8\uc9c8\uc744 \ub458\ub7ec\uc2fc \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uae34 \ub17c\uc758 \uc548\uc5d0 \ub193\uc5ec \uc788\ub2e4. \ud55c \ubc88\uc758 \uc2e4\ud5d8\uc774 \ubaa8\ub4e0 \uc0dd\uac01\uc744 \uc989\uc2dc \ubc14\uafe8\ub2e4\ub294 \uc2dd\uc758 \uc774\uc57c\uae30\ub294 \uc9c0\ub098\uce58\uac8c \ub2e8\uc21c\ud558\ub2e4. \uadf8\ub7ec\ub098 \uc11c\ub85c \ub2e4\ub978 \ud604\uc0c1\uc744 \uc591\uc73c\ub85c \uc5f0\uacb0\ud55c \uc791\uc5c5\uc758 \uc758\ubbf8\ub294 \ubd84\uba85\ud558\ub2e4. \ucd94\uac00 \ub0b4\ub824\uac00\uace0 \ubb3c\uc774 \uc870\uae08 \ub530\ub73b\ud574\uc9c0\ub294 \uc7a5\uba74\uc5d0\uc11c, \uacfc\ud559\uc740 \uc0ac\ub77c\uc9c4 \uc6b4\ub3d9\uc744 \ubb3b\ub294 \ub300\uc2e0 \uc5d0\ub108\uc9c0\uac00 \uc5b4\ub514\ub85c \uac14\ub294\uc9c0 \ubb3b\uac8c \ub418\uc5c8\ub2e4. \uac19\uc740 \uc7a5\ubd80\uc5d0 \uc801\uc744 \uc218 \uc5c6\uc744 \uac83 \uac19\ub358 \ub450 \ubcc0\ud654\ub97c \ud568\uaed8 \uacc4\uc0b0\ud558\ub294 \uac83\uc774\ub2e4. \uc7a5\uce58\uc5d0\uc11c \uc77c\uc5b4\ub09c \ubcc0\ud654\uc640 \ub2e8\uc704\ub97c \ud1b5\ud574 \ube44\uad50\ud55c \uc591\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \uc2e4\ud5d8\uc758 \uc758\ubbf8\uac00 \uc644\uc131\ub41c\ub2e4. \ubd88\uc774 \uc5c6\ub294 \uc628\ub3c4 \uc0c1\uc2b9\uc740 \uadf8\ub807\uac8c \uc5d0\ub108\uc9c0\uc758 \uacf5\ud1b5 \uc5b8\uc5b4\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc7a5\uba74\uc774 \ub41c\ub2e4."}, {"id": "kepler-mars-observations-and-ellipse", "title": "\ucf00\ud50c\ub7ec \u2014 \ud558\ub298\uc758 \uc6d0\uc744 \uc870\uae08 \ucc0c\uadf8\ub7ec\ub728\ub9b0 \uc0ac\ub78c", "summary": "\ud2f0\ucf54 \ube0c\ub77c\ud5e4\uc758 \uad00\uce21\uacfc \ucf00\ud50c\ub7ec\uc758 \uc138 \ubc95\uce59\uc774 \ud589\uc131\uc758 \uae38\uc744 \uc5b4\ub5bb\uac8c \ubc14\uafb8\uc5c8\ub294\uc9c0 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uacfc\ud559\uc790\uc758 \ubc1c\uacac", "categories": ["science"], "url": "stories/kepler-mars-observations-and-ellipse/index.html", "image": "../media/kepler-mars-observations-and-ellipse.png", "alt": "\uad00\uce21 \uc790\ub8cc\uc640 \uce21\uc815 \ub3c4\uad6c\uac00 \ub193\uc778 \ucc45\uc0c1\uc5d0\uc11c \uc0dd\uac01\ud558\ub294 \ucd08\uae30 \uadfc\ub300 \ucc9c\ubb38\ud559\uc790\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ucf00\ud50c\ub7ec \u2014 \ud558\ub298\uc758 \uc6d0\uc744 \uc870\uae08 \ucc0c\uadf8\ub7ec\ub728\ub9b0 \uc0ac\ub78c \ud654\uc131\uc758 \uc791\uc740 \uc5b4\uae0b\ub0a8\uc744 \ubc84\ub9ac\uc9c0 \uc54a\uace0 \ub530\ub77c\uac04 \uacc4\uc0b0 \ud2f0\ucf54 \ube0c\ub77c\ud5e4\uc758 \uad00\uce21\uacfc \ucf00\ud50c\ub7ec\uc758 \uc138 \ubc95\uce59\uc774 \ud589\uc131\uc758 \uae38\uc744 \uc5b4\ub5bb\uac8c \ubc14\uafb8\uc5c8\ub294\uc9c0 \uc77d\uc2b5\ub2c8\ub2e4. \uacfc\ud559\uc790\uc758 \ubc1c\uacac \uacfc\ud559\uacfc \ubc1c\uacac \ud558\ub298\uc758 \uae38\uc740 \uc644\ubcbd\ud55c \uc6d0\uc77c \uac83\uc774\ub77c\uace0 \uc0dd\uac01\ud588\ub294\ub370 \uc2e4\uc81c \uad00\uce21\uc774 \uc870\uae08 \uc5b4\uae0b\ub09c\ub2e4. \uc774\ub7f4 \ub54c \uc22b\uc790\uc5d0 \uc2e4\uc218\uac00 \uc788\ub2e4\uace0 \uc5ec\uae38 \uc218\ub3c4 \uc788\uace0, \uc6d0\uc774 \ub9de\ub2e4\ub294 \uc0dd\uac01\ubd80\ud130 \ub2e4\uc2dc \uc0b4\ud3b4\ubcfc \uc218\ub3c4 \uc788\ub2e4. \ucf00\ud50c\ub7ec\uc758 \uc774\uc57c\uae30\ub294 \uadf8 \ubd88\ud3b8\ud55c \uc120\ud0dd\uc744 \ub05d\uae4c\uc9c0 \ub530\ub77c\uac04 \uc0ac\ub78c\uc758 \uc774\uc57c\uae30\ub2e4. \uadf8\ub294 \ub9dd\uc6d0\uacbd\uc73c\ub85c \uc0c8 \ud589\uc131\uc744 \ucc3e\uc544 \uc774\ub984\uc744 \ubd99\uc778 \uc778\ubb3c\uc774 \uc544\ub2c8\ub2e4. \uc774\ubbf8 \uc313\uc778 \uad00\uce21\uc744 \uc624\ub798 \ubd84\uc11d\ud574 \ud589\uc131\ub4e4\uc774 \uc5b4\ub5a4 \uae38\uc744 \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc774\ub294\uc9c0 \uc124\uba85\ud588\ub2e4. \uc624\ud508\uc2a4\ud0dd\uc2a4 \ucc9c\ubb38\ud559 \uad50\uc7ac\uc758 \ud574\ub2f9 \uc7a5\uc744 \ubc14\ud0d5\uc73c\ub85c, \uc5b4\ub824\uc6b4 \uc218\uc2dd\uc744 \uc7a0\uc2dc \ub4a4\ub85c \ub450\uace0 \uadf8 \ubcc0\ud654\uc758 \ub73b\uc744 \uc0b4\ud3b4\ubcf8\ub2e4. \ub374\ub9c8\ud06c\uc758 \ucc9c\ubb38\ud559\uc790 \ud2f0\ucf54 \ube0c\ub77c\ud5e4\ub294 \ub9dd\uc6d0\uacbd\uc744 \uc4f0\uae30 \uc774\uc804\uc5d0 \ucc9c\uccb4\uc758 \uc704\uce58\ub97c \uc815\ubc00\ud558\uac8c \uad00\uce21\ud588\ub2e4. \ud070 \uce21\uc815 \uae30\uad6c\uc640 \uc9c0\uc18d\uc801\uc778 \uae30\ub85d\uc774 \uadf8\uc758 \ud798\uc774\uc5c8\ub2e4. \ud558\ub298\uc740 \ub204\uad6c\ub098 \ubcfc \uc218 \uc788\uc9c0\ub9cc \uc5b4\uc81c\uc640 \uc624\ub298\uc758 \uc704\uce58\ub97c \ube44\uad50\ud560 \uc218 \uc788\ub294 \uc22b\uc790\ub85c \ub0a8\uae30\ub294 \uc77c\uc740 \ub2e4\ub978 \uc791\uc5c5\uc774\ub2e4. \uc624\ub79c \uc790\ub8cc\uac00 \uc313\uc774\uba74 \uae30\uc874\uc758 \uacc4\uc0b0\ud45c\uac00 \uc608\uce21\ud55c \uc704\uce58\uc640 \uc2e4\uc81c \uc704\uce58\uc758 \ucc28\uc774\ub3c4 \ub4dc\ub7ec\ub09c\ub2e4. \uc774 \ucc28\uc774\ub294 \ub2e8\uc21c\ud788 \ud765\ubbf8\ub85c\uc6b4 \uc2e4\uc218\uac00 \uc544\ub2c8\ub77c \uc5b4\ub5a4 \uc124\uba85\uc774 \ub354 \ub9de\ub294\uc9c0 \uac00\ub9b4 \uae30\uc900\uc774 \ub41c\ub2e4. \ub4a4\uc5d0 \ub4f1\uc7a5\ud558\ub294 \ucf00\ud50c\ub7ec\uc758 \uc218\ud559\uc740 \uadf8 \uae30\uc900 \uc5c6\uc774 \ud63c\uc790 \ud0dc\uc5b4\ub09c \uac83\uc774 \uc544\ub2c8\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc624\ub798 \ubc14\ub77c\ubcf8 \ud558\ub298\uc744 \ubb3c\ub824\ubc1b\uc544 \uc2dc\uc791\ud55c\ub2e4. \ucf00\ud50c\ub7ec\ub294 \ucf54\ud398\ub974\ub2c8\ucfe0\uc2a4\uc758 \ud0dc\uc591 \uc911\uc2ec \uccb4\uacc4\uc5d0 \uad00\uc2ec\uc744 \uac16\uace0, \ud504\ub77c\ud558\uc5d0\uc11c \ud2f0\ucf54\uc758 \uc790\ub8cc\ub97c \ubd84\uc11d\ud558\ub294 \uc77c\uc744 \ud55c\ub2e4. \ud558\uc9c0\ub9cc \ud0dc\uc591\uc744 \uac00\uc6b4\ub370 \ub193\ub294\ub2e4\uace0 \ud589\uc131\uc758 \uc815\ud655\ud55c \uc704\uce58\uac00 \uc800\uc808\ub85c \uacc4\uc0b0\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc911\uc2ec\uc744 \ubc14\uafb8\ub294 \uc0dd\uac01\uacfc \uc2e4\uc81c \uc6c0\uc9c1\uc784\uc744 \uc798 \uc124\uba85\ud558\ub294 \ubc95\uce59 \uc0ac\uc774\uc5d0\ub294 \ud480\uc5b4\uc57c \ud560 \uc77c\uc774 \ub0a8\uc544 \uc788\uc5c8\ub2e4. \uad00\uce21\uc744 \ubaa8\uc740 \uc0ac\ub78c\uacfc \ubd84\uc11d\ud558\ub294 \uc0ac\ub78c\uc758 \uad00\uacc4\ub3c4 \ucc98\uc74c\ubd80\ud130 \ub2e8\uc21c\ud558\uace0 \ub9e4\ub044\ub7fd\uc9c0\ub294 \uc54a\uc558\ub2e4. \uad50\uc7ac\ub294 \uc790\ub8cc\ub97c \ub118\uae30\ub294 \ub370\uc5d0 \ud2f0\ucf54\uac00 \uc870\uc2ec\uc2a4\ub7ec\uc6e0\ub358 \uc0ac\uc815\uc744 \uc18c\uac1c\ud55c\ub2e4. \ud2f0\ucf54\uac00 \uc8fd\uc740 \ub4a4 \ucf00\ud50c\ub7ec\ub294 \ubc29\ub300\ud55c \uae30\ub85d\uc744 \ub354 \ucda9\ubd84\ud788 \ud65c\uc6a9\ud55c\ub2e4. \ud611\ub825\uc758 \uacb0\uacfc\ub77c\ub294 \ub9d0 \uc548\uc5d0\ub3c4 \uac01\uc790\uc758 \uae30\ub300\uc640 \uc778\uc815\ubc1b\uace0 \uc2f6\uc740 \ub9c8\uc74c\uc774 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \ucf00\ud50c\ub7ec\ub294 \ucc98\uc74c\uc5d0 \ud589\uc131\uc758 \uae38\uc744 \uc6d0\uc73c\ub85c \ub9de\ucd94\ub824 \ud588\ub2e4. \uc6d0\uc740 \ubaa8\ub4e0 \ubd80\ubd84\uc774 \uc911\uc2ec\uc5d0\uc11c \uac19\uc740 \uac70\ub9ac\uc5d0 \uc788\uc5b4 \uae54\ub054\ud558\uace0 \ud2b9\ubcc4\ud55c \ubaa8\uc591\uc774\ub2e4. \uadf8\ub7ec\ub098 \ud654\uc131\uc758 \uad00\uce21\uc744 \uc124\uba85\ud558\ub824\uace0 \ud558\uba74 \ubb38\uc81c\uac00 \ub0a8\uc558\ub2e4. \ub9c8\uc74c\uc5d0 \ub4dc\ub294 \ub3c4\ud615\uacfc \ub9de\ub294 \ub3c4\ud615\uc774 \ubc18\ub4dc\uc2dc \uac19\uc9c0\ub294 \uc54a\uc558\ub2e4. \uadf8\ub294 \uc790\ub8cc\ub97c \ubd84\uc11d\ud55c \ub05d\uc5d0 \ud654\uc131\uc758 \uae38\uc774 \ud0c0\uc6d0\uc73c\ub85c \uc124\uba85\ub41c\ub2e4\ub294 \uacb0\ub860\uc5d0 \uc774\ub978\ub2e4. \ud0c0\uc6d0\uc740 \uc6d0\uc744 \uc544\ubb34\ub807\uac8c\ub098 \ucc0c\uadf8\ub7ec\ub728\ub9b0 \ub099\uc11c\uac00 \uc544\ub2c8\ub77c \uc77c\uc815\ud55c \uaddc\uce59\uc744 \uac00\uc9c4 \uace1\uc120\uc774\ub2e4. \uc775\uc219\ud55c \uc544\ub984\ub2e4\uc6c0\uc744 \uc644\uc804\ud788 \ubc84\ub9b0 \uac83\uc774 \uc544\ub2c8\ub77c, \ub2e4\ub978 \uc9c8\uc11c\ub97c \ubc1b\uc544\ub4e4\uc5ec \uad00\uce21\uc744 \uc124\uba85\ud558\ub294 \ubc94\uc704\ub97c \ub113\ud78c \uc148\uc774\ub2e4. \uc6d0\uc744 \uadf8\ub9ac\uba74 \uc911\uc2ec\uc774 \ud558\ub098\ub2e4. \ud0c0\uc6d0\uc5d0\ub294 \ucd08\uc810\uc774\ub77c\uace0 \ubd80\ub974\ub294 \ub450 \uc790\ub9ac\uac00 \uc788\ub2e4. \ud0c0\uc6d0 \uc704 \uc5b4\ub290 \uc810\uc5d0\uc11c\ub4e0 \ub450 \ucd08\uc810\uae4c\uc9c0\uc758 \uac70\ub9ac\ub97c \ud569\ud558\uba74 \uc77c\uc815\ud558\ub2e4\ub294 \uc131\uc9c8\uc774 \uc788\ub2e4. \ucf00\ud50c\ub7ec\uc758 \uccab \ubc88\uc9f8 \ubc95\uce59\uc5d0\uc11c \ud0dc\uc591\uc740 \uadf8 \ub450 \ucd08\uc810 \uac00\uc6b4\ub370 \ud558\ub098\uc5d0 \ub193\uc778\ub2e4. \ub450 \uc790\ub9ac\uc758 \uc815\uc911\uc559\uc5d0 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2e4\uc81c \ud589\uc131\uc758 \ud0c0\uc6d0\uc740 \ud754\ud788 \uc124\uba85 \uadf8\ub9bc\uc5d0\uc11c \ubcf4\ub4ef \uc544\uc8fc \uae38\ucb49\ud558\uc9c0 \uc54a\ub2e4. \ud654\uc131\uc758 \uada4\ub3c4\ub3c4 \uba40\ub9ac\uc11c \ubcf4\uba74 \uc6d0\uacfc \ud06c\uac8c \ub2e4\ub974\uc9c0 \uc54a\uac8c \ubcf4\uc778\ub2e4. \uadf8\ub798\uc11c \ucc28\uc774\uac00 \uc791\ub2e4\uace0 \uc911\uc694\ud558\uc9c0 \uc54a\ub2e4\uace0 \uc5ec\uacbc\ub2e4\uba74 \ubc1c\uacac\uc740 \uc5b4\ub824\uc6e0\uc744 \uac83\uc774\ub2e4. \ub208\uc5d0 \uc798 \ub744\ub294 \uc0c8 \ubaa8\uc591\uc744 \ucc3e\uc558\ub2e4\uae30\ubcf4\ub2e4 \uc791\uc740 \uc5b4\uae0b\ub0a8\uc744 \uc815\ud655\ud788 \ub2e4\ub8e8\uba70 \ub2e4\ub978 \uad00\uacc4\ub97c \ucc3e\uc740 \uac83\uc774\ub2e4. \ub450 \ubc88\uc9f8 \ubc95\uce59\uc740 \uc18d\ub3c4\uc5d0 \uad00\ud55c \uac83\uc774\ub2e4. \ud589\uc131\uc740 \ud0dc\uc591\uc5d0 \uac00\uae4c\uc6b4 \ucabd\uc5d0\uc11c\ub294 \ub354 \ube60\ub974\uac8c, \uba3c \ucabd\uc5d0\uc11c\ub294 \ub354 \ub290\ub9ac\uac8c \uc6c0\uc9c1\uc778\ub2e4. \uc77c\uc815\ud55c \ube60\ub974\uae30\ub85c \ud558\ub298\uc744 \ub3c4\ub294 \ubaa8\uc2b5\uc740 \uc124\uba85\uc758 \uc804\uc81c\uac00 \ub420 \uc218 \uc5c6\ub2e4. \uae38\uc758 \ubaa8\uc591\ubfd0 \uc544\ub2c8\ub77c \uadf8 \uae38\uc744 \uc9c0\ub098\uac00\ub294 \ubc29\uc2dd\ub3c4 \ubc14\ub010\ub2e4. \uc774\ub97c \uc815\ud655\ud788 \ud45c\ud604\ud558\ub824\uace0 \ud0dc\uc591\uacfc \ud589\uc131\uc744 \uc787\ub294 \uc120\uc744 \uc0c1\uc0c1\ud55c\ub2e4. \uadf8 \uc120\uc774 \uac19\uc740 \uc2dc\uac04 \ub3d9\uc548 \uc4f8\uace0 \uc9c0\ub098\uac00\ub294 \ub113\uc774\ub294 \uac19\ub2e4\ub294 \uac83\uc774 \ubc95\uce59\uc758 \ub0b4\uc6a9\uc774\ub2e4. \uac00\uae4c\uc6b8 \ub54c\ub294 \uc9e7\uc740 \uc120\uc774 \ub354 \ube60\ub974\uac8c \uc6c0\uc9c1\uc774\uace0 \uba40 \ub54c\ub294 \uae34 \uc120\uc774 \ub290\ub9ac\uac8c \uc6c0\uc9c1\uc778\ub2e4. \uac70\ub9ac\ub294 \ub2ec\ub77c\uc838\ub3c4 \uc77c\uc815\ud558\uac8c \ub0a8\ub294 \ub113\uc774\uc758 \uad00\uacc4\uac00 \uc788\ub2e4. \ucc98\uc74c \ub450 \ubc95\uce59\uc774 \ubc1c\ud45c\ub41c \ub4a4\uc5d0\ub3c4 \ucf00\ud50c\ub7ec\ub294 \uacc4\uc0b0\uc744 \uacc4\uc18d\ud588\ub2e4. 1619\ub144\uc5d0 \uc81c\uc2dc\ud55c \uc138 \ubc88\uc9f8 \ubc95\uce59\uc740 \ud55c \ud589\uc131 \uc548\uc758 \uc6c0\uc9c1\uc784\uc744 \ub118\uc5b4 \uc5ec\ub7ec \ud589\uc131\uc758 \uad00\uacc4\ub97c \uc124\uba85\ud55c\ub2e4. \ud0dc\uc591\uc5d0\uc11c \uba3c \uada4\ub3c4\ub97c \ub3c4\ub294 \ud589\uc131\uc77c\uc218\ub85d \ud55c \ubc14\ud034\uc5d0 \ub354 \uae34 \uc2dc\uac04\uc774 \ud544\uc694\ud558\uba70, \uadf8 \uac70\ub9ac\uc640 \uc2dc\uac04 \uc0ac\uc774\uc5d0\ub294 \uc218\ud559\uc801\uc778 \ube44\ub840\uac00 \uc788\ub2e4. \uc815\ud655\ud788\ub294 \uacf5\uc804 \uc8fc\uae30\uc758 \uc81c\uacf1\uacfc \ud0c0\uc6d0 \uada4\ub3c4\uc758 \uae34 \ubc18\uc9c0\ub984\uc758 \uc138\uc81c\uacf1\uc774 \uc5f0\uacb0\ub41c\ub2e4. \ubb38\uc7a5\ub9cc\uc73c\ub85c\ub294 \ubb34\uac81\uac8c \ub4e4\ub9ac\uc9c0\ub9cc \ubaa9\uc801\uc740 \ubd84\uba85\ud558\ub2e4. \ud55c \ubc14\ud034 \ub3c4\ub294 \uc2dc\uac04\uc744 \uc54c\uba74 \ud0dc\uc591\uc5d0\uc11c \uc5bc\ub9c8\ub098 \ub5a8\uc5b4\uc838 \uc788\ub294\uc9c0 \ube44\uad50\ud560 \uc218 \uc788\ub2e4. \ub530\ub85c \ubcf4\uc774\ub358 \ud589\uc131\ub4e4\uc758 \uc6c0\uc9c1\uc784\uc774 \ud558\ub098\uc758 \uaddc\uce59 \uc548\uc5d0 \ub4e4\uc5b4\uac04\ub2e4. \ucf00\ud50c\ub7ec\uc758 \ubc95\uce59\uc740 \ud589\uc131\uc774 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \uc6c0\uc9c1\uc774\ub294\uc9c0 \ub9e4\uc6b0 \uc798 \uc815\ub9ac\ud55c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uadf8\uac00 \ub274\ud134\uc758 \uc911\ub825 \uc774\ub860\uae4c\uc9c0 \uac19\uc740 \ubaa8\uc2b5\uc73c\ub85c \uc644\uc131\ud588\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc6c0\uc9c1\uc784\uc744 \uae30\uc220\ud558\ub294 \ubc95\uce59\uacfc \uadf8 \ubc95\uce59\uc774 \uc65c \uc131\ub9bd\ud558\ub294\uc9c0 \uc124\uba85\ud558\ub294 \uc774\ub860\uc740 \uc774\uc5b4\uc9c0\uc9c0\ub9cc \uc11c\ub85c \uac19\uc740 \ub2e8\uacc4\ub294 \uc544\ub2c8\ub2e4. \ud6c4\ub300\uc758 \ub274\ud134\uc740 \uc911\ub825\uacfc \uc6b4\ub3d9\uc744 \ud1b5\ud574 \uc774 \uad00\uacc4\ub97c \ub354 \ub113\uac8c \uc124\uba85\ud55c\ub2e4. \uc774\ub7f0 \uc5f0\uacb0\uc744 \uc54c\uba74 \ud55c \ucc9c\uc7ac\uac00 \ubaa8\ub4e0 \ub2f5\uc744 \ud55c\uaebc\ubc88\uc5d0 \ubc1c\uacac\ud588\ub2e4\ub294 \uc774\uc57c\uae30\ubcf4\ub2e4 \uacfc\ud559\uc758 \uc2e4\uc81c \ubaa8\uc2b5\uc774 \uc798 \ubcf4\uc778\ub2e4. \uad00\uce21\uacfc \uacc4\uc0b0, \uc124\uba85\uc774 \uc11c\ub85c\uc758 \uc9c8\ubb38\uc744 \uc774\uc5b4\ubc1b\ub294\ub2e4. \ubc1c\uacac\uc740 \ub05d\uc778 \ub3d9\uc2dc\uc5d0 \ub2e4\uc74c \uc0ac\ub78c\uc774 \uc2dc\uc791\ud560 \uc218 \uc788\ub294 \uc790\ub9ac\ub2e4. \ucf00\ud50c\ub7ec\uac00 \ub0a8\uae34 \uc778\uc0c1\uc740 \uc5b4\ub824\uc6b4 \uc2dd \uc138 \uac1c\uc5d0\ub9cc \uc788\uc9c0 \uc54a\ub2e4. \uc88b\uc544\ud558\ub358 \uc0dd\uac01\uc744 \uad00\uce21 \uc55e\uc5d0\uc11c \uc218\uc815\ud560 \uc218 \uc788\uc5c8\ub358 \ud0dc\ub3c4\uc5d0\ub3c4 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uadf8\ub97c \ucc98\uc74c\ubd80\ud130 \uc120\uc785\uacac\uc774 \uc804\ud600 \uc5c6\ub294 \ud604\ub300 \uacfc\ud559\uc790\uc758 \ubaa8\uc2b5\uc73c\ub85c \uafb8\ubc00 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8 \uc5ed\uc2dc \uc6b0\uc8fc\uc758 \uc870\ud654\uc640 \uc9c8\uc11c\ub97c \uac15\ud558\uac8c \ucc3e\ub358 \uc790\uae30 \uc2dc\ub300\uc758 \uc0ac\ub78c\uc774\uc5c8\ub2e4. \uadf8\ub7f0 \uc0ac\ub78c\uc774 \uc22b\uc790\uc640 \uc528\ub984\ud558\uba74\uc11c \uae30\ub300\ud55c \ubaa8\uc591\uc744 \ubc14\uafb8\uc5c8\ub2e4\ub294 \uc810\uc774 \uc624\ud788\ub824 \uc911\uc694\ud558\ub2e4. \uac00\uc124\uc744 \uac16\uc9c0 \uc54a\ub294 \uac83\ubcf4\ub2e4, \uac00\uc124\uacfc \ub9de\uc9c0 \uc54a\ub294 \uc790\ub8cc\ub97c \uc5b4\ub5bb\uac8c \ub2e4\ub8e8\ub294\uc9c0\uac00 \ubc1c\uacac\uc744 \uac00\ub97c \ub54c\uac00 \uc788\ub2e4. \ucf00\ud50c\ub7ec\uc758 \ud0c0\uc6d0\uc740 \ucc45\uc0c1 \uc704\uc5d0\uc11c \uc624\ub798 \uc9c0\uc18d\ub41c \uadf8\ub7f0 \uc870\uc815\uc758 \uacb0\uacfc\uc600\ub2e4. \ubc24\ud558\ub298\uc744 \ubcf4\uc544\ub3c4 \ud0c0\uc6d0\uc758 \uc120\uc774 \uadf8\ub824\uc838 \uc788\uc9c0\ub294 \uc54a\ub2e4. \uae30\ub85d\ud55c \uc704\uce58\ub4e4\uc744 \ube44\uad50\ud558\uace0, \uc5ec\ub7ec \uc21c\uac04\uc744 \ud55c \uad00\uacc4\ub85c \ubb36\uc5b4\uc57c \uadf8 \uae38\uc774 \ubcf4\uc778\ub2e4. \uadf8\ub798\uc11c \uc774 \uc774\uc57c\uae30\ub294 \uad00\ucc30\ub9cc \uc798\ud558\uac70\ub098 \uacc4\uc0b0\ub9cc \uc798\ud558\uba74 \ub05d\ub098\ub294 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc77c\uc744 \uc5f0\uacb0\ud558\ub294 \ud798\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\uc774\uae30\ub3c4 \ud558\ub2e4. \uc6b0\ub9ac\uac00 \uae30\uc5b5\ud560 \uadf8\ub9bc\uc740 \ucc0c\uadf8\ub7ec\uc9c4 \uc6d0 \ud558\ub098\uc5ec\ub3c4 \ucda9\ubd84\ud558\ub2e4. \ub2e8, \uc544\ubb34\ub807\uac8c\ub098 \ucc0c\uadf8\ub7ec\uc9c4 \uac83\uc774 \uc544\ub2c8\ub77c \uad00\uce21\uc744 \ub354 \uc798 \uc124\uba85\ud558\uae30 \uc704\ud574 \uace0\ub978 \uc815\ud655\ud55c \uace1\uc120\uc774\ub77c\ub294 \uc810\uc744 \ud568\uaed8 \uae30\uc5b5\ud558\uba74 \uc88b\uaca0\ub2e4. \uc791\uc740 \uc5b4\uae0b\ub0a8\uc744 \ubc84\ub9ac\uc9c0 \uc54a\uc790 \ud558\ub298 \uc804\uccb4\ub97c \uc774\ud574\ud558\ub294 \ubc29\uc2dd\uc774 \ub2ec\ub77c\uc84c\ub2e4. \ucf00\ud50c\ub7ec\uac00 \ub0a8\uae34 \ubcc0\ud654\ub294 \uadf8\ub9cc\ud07c \uc870\uc6a9\ud558\uace0\ub3c4 \ucef8\ub2e4."}, {"id": "lavoisier-metals-air-and-balanced-mass", "title": "\ub77c\ubd80\uc544\uc9c0\uc5d0 \u2014 \ub298\uc5b4\ub09c \uae08\uc18d\uc758 \ubb34\uac8c\ub294 \uc5b4\ub514\uc5d0\uc11c \uc654\uc744\uae4c", "summary": "\uae08\uc18d\uc758 \ubb34\uac8c \uc99d\uac00\uc640 \ub2eb\ud78c \uc6a9\uae30, \uacf5\uae30\uc640 \ubb3c\uc9c8\ub7c9\uc744 \ud568\uaed8 \ube44\uad50\ud55c \ud654\ud559\uc758 \ubc29\ubc95\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\ubb3c\uc9c8\uacfc \uc5d0\ub108\uc9c0", "categories": ["science"], "url": "stories/lavoisier-metals-air-and-balanced-mass/index.html", "image": "../media/lavoisier-metals-air-and-balanced-mass.png", "alt": "\uc800\uc6b8\uacfc \uc720\ub9ac \uc6a9\uae30 \uc55e\uc5d0\uc11c \ubb3c\uc9c8\uc758 \uc591\uc744 \ube44\uad50\ud558\ub294 \ud654\ud559 \uc5f0\uad6c\uc790\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ub77c\ubd80\uc544\uc9c0\uc5d0 \u2014 \ub298\uc5b4\ub09c \uae08\uc18d\uc758 \ubb34\uac8c\ub294 \uc5b4\ub514\uc5d0\uc11c \uc654\uc744\uae4c \uacf5\uae30\uc640 \uc0dd\uc131\ubb3c\uae4c\uc9c0 \ud568\uaed8 \uc7ac\ub294 \ud654\ud559 \uc2e4\ud5d8\uc758 \uc2dc\uc57c \uae08\uc18d\uc758 \ubb34\uac8c \uc99d\uac00\uc640 \ub2eb\ud78c \uc6a9\uae30, \uacf5\uae30\uc640 \ubb3c\uc9c8\ub7c9\uc744 \ud568\uaed8 \ube44\uad50\ud55c \ud654\ud559\uc758 \ubc29\ubc95\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ubb3c\uc9c8\uacfc \uc5d0\ub108\uc9c0 \uacfc\ud559\uacfc \ubc1c\uacac \uae08\uc18d\uc744 \uac00\uc5f4\ud574 \ub2e4\ub978 \ubaa8\uc2b5\uc758 \ubb3c\uc9c8\ub85c \ub9cc\ub4e4\uc5c8\ub354\ub2c8 \ubb34\uac8c\uac00 \ub298\uc5c8\ub2e4. \ubd88\uc774 \ubb34\uac8c\ub97c \ub354\ud55c \uac83\uc77c\uae4c, \ubc16\uc5d0\uc11c \ubb34\uc5c7\uc778\uac00 \ub4e4\uc5b4\uc628 \uac83\uc77c\uae4c. \ub77c\ubd80\uc544\uc9c0\uc5d0\uc758 \ud654\ud559\uc744 \uc77d\uc73c\uba74 \ub208\uc5d0 \ubcf4\uc774\ub294 \uae08\uc18d\ub9cc \ubcf4\ub358 \uc9c8\ubb38\uc774 \uacf5\uae30\uc640 \uc0dd\uc131\ubb3c\uae4c\uc9c0 \ud568\uaed8 \uc7ac\ub294 \uc9c8\ubb38\uc73c\ub85c \ubc14\ub010\ub2e4. \uc800\uc6b8\uc740 \ubb3c\uc9c8\uc758 \ubcc0\ud654\ub97c \uc124\uba85\ud558\ub294 \uc911\uc694\ud55c \ub3c4\uad6c\uac00 \ub418\uc5c8\ub2e4. \uc5f4\ub9b0 \uacf5\uac04\uc5d0\uc11c \uac00\uc5f4\ud558\uba74 \uc8fc\ubcc0 \uacf5\uae30\uac00 \ubc18\uc751\uc5d0 \ucc38\uc5ec\ud560 \uc218 \uc788\ub2e4. \uae08\uc18d\ub9cc \ucc98\uc74c\uacfc \ub098\uc911\uc5d0 \ube44\uad50\ud558\uba74 \ub298\uc5b4\ub09c \uc591\uc774 \uc5b4\ub514\uc5d0\uc11c \uc654\ub294\uc9c0 \uc54c\uc544\ub0b4\uae30 \uc5b4\ub835\ub2e4. \uc2e4\ud5d8\uc758 \uacbd\uacc4\ub97c \uc5b4\ub514\uae4c\uc9c0 \ubcfc \uac83\uc778\uac00\uac00 \uc911\uc694\ud55c \ubb38\uc81c\uac00 \ub41c\ub2e4. \uc6b0\ub9ac\ub294 \uace0\uccb4\ub97c \ubb3c\uc9c8\ub85c \uc27d\uac8c \ub5a0\uc62c\ub9ac\uc9c0\ub9cc \uae30\uccb4\ub294 \ub193\uce58\uae30 \uc27d\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc774\uc720\ub85c \uacc4\uc0b0\uc5d0\uc11c \ube7c\uba74 \uacb0\uacfc\ub97c \uc124\uba85\ud560 \uc218 \uc5c6\uac8c \ub41c\ub2e4. \uc800\uc6b8\uc744 \uc798 \uc4f0\ub294 \uc77c\uc740 \uc815\ubc00\ud55c \ub208\uae08\uc744 \uc77d\ub294 \uae30\uc220\ubfd0 \uc544\ub2c8\ub77c \ubb34\uc5c7\uc744 \ud568\uaed8 \uc7ac\uc57c \ud558\ub294\uc9c0 \uc815\ud558\ub294 \uc77c\uc774\uc5c8\ub2e4. \ub77c\ubd80\uc544\uc9c0\uc5d0\uc758 \u300e\ud654\ud559 \uc6d0\ub860\u300f\uc740 \uae08\uc18d\uc758 \uc0b0\ud654\uc5d0\uc11c \ubb34\uac8c\uac00 \ub298\uc5b4\ub098\ub294 \ud604\uc0c1\uc744 \ub2eb\ud78c \uc6a9\uae30\uc640 \uc815\ud574\uc9c4 \uc591\uc758 \uacf5\uae30\ub97c \ud1b5\ud574 \uc774\ud574\ud574\uc57c \ud55c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc8fc\ubcc0\uacfc \ub9c8\uc74c\ub300\ub85c \ubb3c\uc9c8\uc744 \uc8fc\uace0\ubc1b\uc9c0 \uc54a\ub294 \uc870\uac74\uc744 \ub9cc\ub4e4\uba74 \ubcc0\ud654\uc758 \ucd9c\ucc98\ub97c \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \uae08\uc18d \ucabd\uc5d0\uc11c \ub298\uc5b4\ub09c \uc591\uacfc \uae30\uccb4 \ucabd\uc758 \ubcc0\ud654\ub97c \ud568\uaed8 \uc0b4\ud53c\ub294 \uac83\uc774\ub2e4. \uc6d0\uc778\uc744 \uc0c1\uc0c1\uc73c\ub85c \ub367\ubd99\uc774\uae30\ubcf4\ub2e4 \uac19\uc740 \uc2e4\ud5d8 \uc548\uc758 \uc5ec\ub7ec \ubd80\ubd84\uc744 \uc5f0\uacb0\ud574 \ube44\uad50\ud55c\ub2e4. \uc774 \ubc29\ubc95\uc740 \uc5b4\ub290 \ubb3c\uc9c8\uc744 \uc5f0\uad6c\ud558\ub294\uc9c0\uc640 \ubcc4\uac1c\ub85c \uce21\uc815\uc758 \uc124\uacc4\ub97c \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uacf5\uae30\uac00 \ubb3c\uc9c8\uc758 \ubcc0\ud654\uc5d0 \ucc38\uc5ec\ud55c\ub2e4\uace0 \uc54c\uac8c \ub418\uba74 \uacf5\uae30 \uc790\uccb4\uc758 \uc131\uc9c8\ub3c4 \ubb3c\uc5b4\uc57c \ud55c\ub2e4. \uc5f0\uc18c\uc640 \ud638\ud761, \uae08\uc18d\uc758 \ubc18\uc751\uc774 \uc5b4\ub5a4 \ubd80\ubd84\uacfc \uc5f0\uacb0\ub418\ub294\uc9c0 \uc5f0\uad6c\uac00 \uc774\uc5b4\uc84c\ub2e4. \uc0b0\uc18c\uc5d0 \ub300\ud55c \uc774\ud574\ub294 \uc5ec\ub7ec \uc5f0\uad6c\uc790\uc758 \ubc1c\uacac\uacfc \ud574\uc11d\uc774 \ub9cc\ub09c \uacfc\uc815\uc774\uc5c8\ub2e4. \ub530\ub77c\uc11c \ub77c\ubd80\uc544\uc9c0\uc5d0\ub97c \uc0b0\uc18c\ub97c \ud63c\uc790 \ucc98\uc74c \ub9cc\ub4e4\uc5b4 \ub0b8 \uc0ac\ub78c\uc73c\ub85c\ub9cc \uae30\uc5b5\ud558\uba74 \ubd80\uc815\ud655\ud558\ub2e4. \uc911\uc694\ud55c \uacf5\ud5cc\uc5d0\ub294 \uc774\ubbf8 \uad00\ucc30\ub41c \uae30\uccb4\uc640 \ubc18\uc751\uc744 \uc0c8\ub85c\uc6b4 \uc124\uba85 \uccb4\uacc4 \uc548\uc5d0 \ub193\uc740 \uc77c\uc774 \uc788\ub2e4. \ubc1c\uacac\uc758 \uc5ed\uc0ac\uc5d0\uc11c \uad00\ucc30\ud55c \uc0ac\ub78c\uacfc \uadf8 \ub73b\uc744 \uc815\ub9ac\ud55c \uc0ac\ub78c\uc758 \uc5ed\ud560\uc740 \uac19\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \u300e\ud654\ud559 \uc6d0\ub860\u300f\uc740 \uc2e4\ud5d8 \uc804\ud6c4\uc758 \ubb3c\uc9c8\uc744 \uc591\uc801\uc73c\ub85c \ub9de\ucd94\ub824\ub294 \uc6d0\uce59\uc744 \uac15\uc870\ud55c\ub2e4. \ubb34\uc5c7\uc778\uac00 \uc0dd\uae30\uac70\ub098 \uc0ac\ub77c\uc9c4 \ub4ef \ubcf4\uc774\ub354\ub77c\ub3c4 \ub2e4\ub978 \ubb3c\uc9c8\uacfc \uae30\uccb4\uc758 \uad00\uacc4\ub97c \ud568\uaed8 \uacc4\uc0b0\ud574\uc57c \ud55c\ub2e4\ub294 \uad00\uc810\uc774\ub2e4. \ud654\ud559 \ubc18\uc751\uc740 \uc124\uba85 \uc5c6\uc774 \ubb34\uac8c\ub97c \ucc3d\uc870\ud558\ub294 \ub9c8\uc220\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc774 \uc6d0\uce59\uc740 \uacb0\uacfc\ub97c \ud574\uc11d\ud558\ub294 \uae30\uc900\uc774 \ub41c\ub2e4. \uc218\ub7c9\uc774 \ub9de\uc9c0 \uc54a\uc73c\uba74 \uce21\uc815\uc5d0\uc11c \ub193\uce5c \ubd80\ubd84\uc774\ub098 \ub4dc\ub098\ub4e0 \ubb3c\uc9c8\uc744 \ub2e4\uc2dc \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uc800\uc6b8\uc774 \ubaa8\ub4e0 \ubb3c\uc9c8\uc758 \uc131\uc9c8\uc744 \uc54c\ub824 \uc8fc\uc9c0\ub294 \uc54a\uc9c0\ub9cc, \uc124\uba85\uc774 \uc591\uc758 \uad00\uacc4\ub97c \uc874\uc911\ud558\ub294\uc9c0 \uc2dc\ud5d8\ud560 \uc218 \uc788\uac8c \ud588\ub2e4. \uae30\uccb4\uac00 \ube60\uc838\ub098\uac00\ub294 \ubc18\uc751\uc744 \uace0\uccb4\ub9cc\uc73c\ub85c \ubcf4\uba74 \ubb34\uac8c\uac00 \uc904\uc5c8\ub2e4\uace0 \ub290\ub084 \uc218 \uc788\ub2e4. \ubc18\ub300\ub85c \uae30\uccb4\uc640 \uacb0\ud569\ud55c \uace0\uccb4\ub9cc \uc7ac\uba74 \ub298\uc5b4\ub09c \uac83\uc73c\ub85c \ubcf4\uc778\ub2e4. \ub450 \uacbd\uc6b0 \ubaa8\ub450 \ubb34\uc5c7\uc744 \uacc4\uc758 \uc548\uc5d0 \ub123\uc5c8\ub294\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uacb0\uacfc\ucc98\ub7fc \ubcf4\uc774\ub358 \ubcc0\ud654\uac00 \uac19\uc740 \uce21\uc815\uc758 \uc9c8\ubb38\uc73c\ub85c \uc774\uc5b4\uc9c4\ub2e4. \uc774 \ub54c\ubb38\uc5d0 \uc2e4\ud5d8\uc758 \uadf8\ub9bc\uc744 \ubcfc \ub54c\uc5d0\ub3c4 \uc6a9\uae30\uc640 \uc5f0\uacb0\ub41c \uad00, \uae30\uccb4\ub97c \ubaa8\uc73c\ub294 \ubd80\ubd84\uc758 \uad00\uacc4\ub97c \uc0b4\ud544 \uc218 \uc788\ub2e4. \uc7a5\uce58\ub294 \ub208\uc55e\uc758 \ubb3c\uc9c8\uc744 \ub2f4\ub294 \uadf8\ub987\uc744 \ub118\uc5b4 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc774\ub3d9\uc744 \ud655\uc778\ud560 \ubc29\ubc95\uc774\uc5c8\ub2e4. \uc22b\uc790\uac00 \ub9de\uc9c0 \uc54a\uc744 \ub54c \uc5f0\uad6c\uc790\ub294 \uc800\uc6b8\uc758 \uc815\ubc00\ub3c4\ub9cc \ud0d3\ud558\ub294 \ub300\uc2e0 \uad00\ucc30\ud558\uc9c0 \ubabb\ud55c \ucd9c\uc785\uc744 \ubb3c\uc744 \uc218 \uc788\ub2e4. \uc88b\uc740 \uc774\ub860\uacfc \uc88b\uc740 \uce21\uc815\uc740 \uc11c\ub85c\ub97c \uc810\uac80\ud558\ub294 \uad00\uacc4\ub2e4. \uc591\uc744 \ub9de\ucd94\ub824\ub294 \uc6d0\uce59\uc740 \uacb0\uacfc\ub97c \uc815\ud574 \ub193\ub294 \uad6c\ud638\ubcf4\ub2e4 \ub2e4\uc2dc \ud655\uc778\ud560 \ub300\uc0c1\uc744 \ucc3e\ub294 \uae30\uc900\uc774\uc5c8\ub2e4. \uc0c8\ub85c\uc6b4 \ud654\ud559\uc758 \ubc1c\uc804\uc5d0\ub294 \uc774\ub984\uacfc \ubd84\ub958\ub97c \ubc14\uafb8\ub824\ub294 \uc791\uc5c5\ub3c4 \ud568\uaed8 \uc788\uc5c8\ub2e4. \uc775\uc219\ud55c \uc774\ub984\ub9cc\uc73c\ub85c \ub2e4\ub978 \ubb3c\uc9c8\uacfc \uc5b4\ub5a4 \uad00\uacc4\uac00 \uc788\ub294\uc9c0 \uc54c\uae30 \uc5b4\ub824\uc6b8 \uc218 \uc788\ub2e4. \uba85\uba85\uc740 \ub2e8\uc21c\ud55c \ub9d0\ubc14\uafb8\uae30\uac00 \uc544\ub2c8\ub77c \uc9c0\uc2dd\uc744 \uc815\ub9ac\ud558\uace0 \uc804\ub2ec\ud558\ub294 \ubc29\ubc95\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uadf8\ub7ec\ub098 \ub2f9\uc2dc\uc758 \uc774\ub860\uacfc \uc774\ub984\uc774 \ubaa8\ub450 \uc9c0\uae08\ub3c4 \uadf8\ub300\ub85c \uc633\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774 \ucc45\uc5d0\ub294 \uc624\ub298\uacfc \ub2e4\ub978 \uc5f4\uc758 \uc124\uba85\uacfc \ubb3c\uc9c8 \ubd84\ub958\ub3c4 \ud3ec\ud568\ub41c\ub2e4. \uc911\uc694\ud55c \uace0\uc804\uc774\ub77c\ub294 \uc0ac\uc2e4\uc774 \ubaa8\ub4e0 \ubb38\uc7a5\uc744 \ud604\ub300 \ud654\ud559\uc758 \ucd5c\uc885 \uc124\uba85\uc73c\ub85c \ub9cc\ub4dc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc29\ubc95\uc758 \uc131\ucde8\uc640 \uc774\ub860\uc758 \ud55c\uacc4\ub97c \ub098\ub204\uc5b4 \uc77d\uc5b4\uc57c \ud55c\ub2e4. \uc815\ubc00\ud55c \uc800\uc6b8\uc744 \ub9c8\ub828\ud588\ub2e4\uace0 \uc5f0\uad6c\uac00 \uc800\uc808\ub85c \ub05d\ub098\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubb34\uc5c7\uc744 \ub2f4\uace0 \ubb34\uc5c7\uc774 \ube60\uc838\ub098\uac08 \uc218 \uc788\ub294\uc9c0, \ube44\uad50\ud558\ub294 \uc0c1\ud0dc\uac00 \uac19\uc740\uc9c0 \uc54c\uc544\uc57c \ud55c\ub2e4. \uc7a5\uce58\uc640 \uc9c8\ubb38\uc758 \uad00\uacc4\uac00 \ub9de\uc544\uc57c \uce21\uc815\uac12\uc774 \ub17c\uc99d\uc758 \uadfc\uac70\uac00 \ub41c\ub2e4. \ud654\ud559\uc0ac\uc5d0\uc11c \uc2e4\ud5d8\uc744 \uadf8\ub9bc \ud55c \uc7a5\uc758 \uc7a5\uba74\uc73c\ub85c \uae30\uc5b5\ud558\uba74 \uc774\ub7f0 \uc138\ubd80\uac00 \uc0ac\ub77c\uc9c0\uae30 \uc27d\ub2e4. \uc720\ub9ac \uc6a9\uae30\uc640 \uc800\uc6b8\uc740 \uc0c1\uc9d5\uc774\uae30 \uc804\uc5d0 \uc870\uac74\uc744 \ud1b5\uc81c\ud558\uace0 \uc218\ub7c9\uc744 \ube44\uad50\ud558\uae30 \uc704\ud55c \ub3c4\uad6c\uc600\ub2e4. \uc0ac\ub78c\uc758 \uc0dd\uac01\uacfc \ubb3c\uc9c8\uc758 \uc6c0\uc9c1\uc784\uc744 \uc5f0\uacb0\ud55c \uad6c\uc870\ub85c \ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \ucc98\uc74c \uc9c8\ubb38\uc73c\ub85c \ub3cc\uc544\uac00\uba74 \uae08\uc18d\uc758 \ubb34\uac8c \uc99d\uac00\uac00 \ud63c\uc790 \uc77c\uc5b4\ub09c \uc0ac\uac74\uc774 \uc544\ub2d8\uc744 \uc54c \uc218 \uc788\ub2e4. \uae08\uc18d\uacfc \uacf5\uae30, \ub0a8\uc740 \uac83\uacfc \uc62e\uaca8 \uac04 \uac83\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud588\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \ub300\uc0c1\uc758 \uacbd\uacc4\ub97c \ub113\ud78c \uac83\uc774 \uc124\uba85\uc744 \ubc14\uafb8\uc5c8\ub2e4. \ub77c\ubd80\uc544\uc9c0\uc5d0\uc758 \uc5f0\uad6c\ub97c \uc77d\ub294 \uc758\ubbf8\ub294 \uc720\uba85\ud55c \uc774\ub984\uc744 \uc678\uc6b0\ub294 \ub370 \uadf8\uce58\uc9c0 \uc54a\ub294\ub2e4. \uacb0\uacfc\uac00 \uc608\uc0c1\uacfc \ub2e4\ub97c \ub54c \ubcf4\uc774\uc9c0 \uc54a\ub294 \ubd80\ubd84\uc744 \uacc4\uc0b0\uc5d0 \ub123\uace0 \uc804\uccb4\ub97c \ub2e4\uc2dc \uc0b4\ud53c\ub294 \ud0dc\ub3c4\ub97c \ubc30\uc6b8 \uc218 \uc788\ub2e4. \ub298\uc5b4\ub09c \ubb34\uac8c\ub97c \uc774\uc0c1\ud55c \uc608\uc678\ub85c \uce58\uc6b0\uc9c0 \uc54a\uace0 \uc124\uba85\ud574\uc57c \ud560 \uc790\ub8cc\ub85c \uc0bc\uc558\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uc608\uc0c1\uacfc \ub2e4\ub978 \uacb0\uacfc\uac00 \uc9c8\ubb38\uc744 \ub113\ud788\ub294 \uc5ed\ud560\uc744 \ud588\ub2e4. \uc800\uc6b8 \uc704\uc758 \uc22b\uc790\ub294 \uadf8\ub807\uac8c \ubb3c\uc9c8\uc744 \ubcf4\ub294 \uc2dc\uc57c\ub97c \ub113\ud788\ub294 \ucd9c\ubc1c\uc810\uc774 \ub418\uc5c8\ub2e4."}, {"id": "magnetic-penny", "title": "\ub2ee\uc740 \ub3d9\uc804\uc778\ub370 \uc65c \ud558\ub098\ub9cc \uc790\uc11d\uc5d0 \ubd99\uc744\uae4c", "summary": "\uac19\uc740 \uc0c9\uc758 \uc601\uad6d \ub3d9\uc804\ub3c4 \uc790\uc11d \uc55e\uc5d0\uc11c\ub294 \ub2e4\ub974\uac8c \uc6c0\uc9c1\uc785\ub2c8\ub2e4. \ube44\ubc00\uc740 \uac89\ubaa8\uc2b5\ubcf4\ub2e4 \uc548\ucabd\uc5d0 \uc788\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\ubb3c\uc9c8\uacfc \uc5d0\ub108\uc9c0", "categories": ["science"], "url": "stories/magnetic-penny/index.html", "image": "../media/magnetic-penny.jpg", "alt": "\uc791\uc740 \uc790\uc11d\uacfc \uad6c\ub9ac\ube5b \uc6d0\ubc18\uc73c\ub85c \uc7ac\ub8cc\uc5d0 \ub530\ub978 \ubc18\uc751\uc744 \uc5f0\uc0c1\uc2dc\ud0a4\ub294 AI \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ub2ee\uc740 \ub3d9\uc804\uc778\ub370 \uc65c \ud558\ub098\ub9cc \uc790\uc11d\uc5d0 \ubd99\uc744\uae4c \uad6c\ub9ac\ube5b \ud45c\uba74 \uc544\ub798\uc5d0 \uc228\uc5b4 \uc788\ub294 \ub2e4\ub978 \uc7ac\ub8cc \uac19\uc740 \uc0c9\uc758 \uc601\uad6d \ub3d9\uc804\ub3c4 \uc790\uc11d \uc55e\uc5d0\uc11c\ub294 \ub2e4\ub974\uac8c \uc6c0\uc9c1\uc785\ub2c8\ub2e4. \ube44\ubc00\uc740 \uac89\ubaa8\uc2b5\ubcf4\ub2e4 \uc548\ucabd\uc5d0 \uc788\uc2b5\ub2c8\ub2e4. \ubb3c\uc9c8\uacfc \uc5d0\ub108\uc9c0 \uacfc\ud559\uacfc \ubc1c\uacac \uc11c\ub78d\uc5d0\uc11c \ub3d9\uc804\uc744 \uaebc\ub0b4\ub2e4\uac00 \uc790\uc11d\uc5d0 \ud558\ub098\uac00 \ubd99\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud574 \ubcf4\uc790. \uc606\uc5d0 \uc788\ub358 \ub2e4\ub978 \ub3d9\uc804\uc740 \uadf8\ub300\ub85c\ub2e4. \ub458 \ub2e4 \uad6c\ub9ac\ube5b\uc778\ub370 \ubc18\uc751\uc740 \ub2e4\ub974\ub2e4. \uc601\uad6d\uc758 1\ud398\ub2c8\uc640 2\ud39c\uc2a4 \ub3d9\uc804\uc5d0\ub294 \uc2e4\uc81c\ub85c \uc774\ub7f0 \ucc28\uc774\uac00 \uc788\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\uc758 \uc548\ub0b4\uc5d0 \ub530\ub974\uba74, \uac89\uc73c\ub85c \ube44\uc2b7\ud574 \ubcf4\uc5ec\ub3c4 \ub9cc\ub4e4\uc5b4\uc9c4 \uc2dc\uae30\uc5d0 \ub530\ub77c \uc548\ucabd \uc7ac\ub8cc\uac00 \ub2e4\ub974\uae30 \ub54c\ubb38\uc774\ub2e4. \uc608\uc804\uc758 \uc601\uad6d 1\ud398\ub2c8\uc640 2\ud39c\uc2a4 \ub3d9\uc804\uc740 \uad6c\ub9ac\uc640 \uc544\uc5f0, \uc8fc\uc11d\uc744 \uc11e\uc740 \uccad\ub3d9\uc73c\ub85c \ub9cc\ub4e4\uc5c8\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\uc740 1992\ub144 9\uc6d4\ubd80\ud130 \uad6c\ub9ac\ub97c \uc785\ud78c \uac15\ucca0\ub85c \uc7ac\ub8cc\ub97c \ubc14\uafb8\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud45c\uba74\uc740 \uacc4\uc18d \uad6c\ub9ac\ube5b\uc744 \ub760\uc9c0\ub9cc \uc18d\uc5d0\ub294 \uac15\ucca0\uc774 \ub4e4\uc5b4\uac04\ub2e4. \uc774 \uac15\ucca0 \ub54c\ubb38\uc5d0 \uad6c\ub9ac \ub3c4\uae08 \uac15\ucca0 \ub3d9\uc804\uc740 \uc790\uc11d\uc5d0 \ub04c\ub9ac\uace0, \uc774\uc804 \uccad\ub3d9 \ub3d9\uc804\uc740 \uadf8\ub807\uc9c0 \uc54a\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \uc0c9\ub9cc\uc73c\ub85c\ub294 \ucc28\uc774\ub97c \ub193\uce58\uae30 \uc27d\ub2e4. \uc0c8 \uc7ac\ub8cc\uac00 \ub4e4\uc5b4\uac14\ub2e4\uace0 \ub3d9\uc804\uc774 \uac11\uc790\uae30 \uc804\ud600 \ub2e4\ub978 \ubb3c\uac74\ucc98\ub7fc \ubcf4\uc774\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\uc758 \ud574\uc124\uc740 \ub450 \uc885\ub958\uc758 \uc0c9\uacfc \ubb34\uac8c, \uc9c0\ub984, \ub514\uc790\uc778\uc774 \uac19\uc558\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc775\uc219\ud55c \ubaa8\uc2b5\uc744 \uc774\uc5b4 \uac00\uba74\uc11c \ub0b4\ubd80\uc758 \uad6c\uc131\uc774 \ubc14\ub010 \uac83\uc774\ub2e4. \uc5ec\uae30\uc11c \uc7ac\ubbf8\uc788\ub294 \uc810\uc740 \uc790\uc11d\uc774 \uc6b0\ub9ac\uac00 \ubcf4\ub294 \uad6c\ub9ac\ube5b\uc5d0 \ubc18\uc751\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c\ub294 \ub370 \uc788\ub2e4. \uac89\uc73c\ub85c \ube44\uc2b7\ud55c \ubb3c\uac74\ub3c4 \ubb34\uc5c7\uc73c\ub85c \ub9cc\ub4e4\uc5c8\ub294\uc9c0\uc5d0 \ub530\ub77c \uacb0\uacfc\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uac19\uc740 \uc0c9\uc758 \uadf8\ub987\uc774 \ubaa8\ub450 \uac19\uc740 \uc7ac\ub8cc\ub294 \uc544\ub2c8\ub4ef, \ub3d9\uc804\uc758 \ud45c\uba74\uc0c9\ub3c4 \uc7ac\ub8cc \uc804\uccb4\ub97c \uc54c\ub824\uc8fc\ub294 \uc774\ub984\ud45c\ub294 \uc544\ub2c8\ub2e4. \uc587\uac8c \uc785\ud78c \uae08\uc18d\uacfc \uadf8 \uc548\ucabd\uc758 \uae08\uc18d\uc774 \uc11c\ub85c \ub2e4\ub978 \uc5ed\ud560\uc744 \ub9e1\uc744 \uc218 \uc788\ub2e4. \uc774 \uc774\uc57c\uae30\ub294 \uc601\uad6d\uc758 \ud574\ub2f9 \ub3d9\uc804\uc744 \ub2e4\ub8ec\ub2e4. \ub098\ub77c\uc640 \uc561\uba74\uc774 \ub2ec\ub77c\uc9c0\uba74 \uc7ac\ub8cc\ub3c4 \ub2ec\ub77c\uc9c0\ubbc0\ub85c, \ubaa8\ub4e0 \ub3d9\uc804\uc774 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ubc18\uc751\ud55c\ub2e4\uace0 \ub113\ud600 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uad6c\ub9ac \ub3c4\uae08\uc774\ub77c\ub294 \uc124\uba85\uc740 \ud45c\uba74\uacfc \ub0b4\ubd80\ub97c \ub098\ub204\uc5b4 \ubcf4\uac8c \ud55c\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \uc0c9\uc774 \ubb3c\uac74 \uc804\uccb4\ub97c \uc774\ub8e8\ub294 \uc7ac\ub8cc\uc640 \uac19\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uac89\uc5d0\ub294 \uc775\uc219\ud55c \uad6c\ub9ac\ube5b\uc744 \ub450\uace0 \uc548\uc5d0\ub294 \uac15\ucca0\uc744 \uc0ac\uc6a9\ud558\uba74 \uc678\ud615\uc744 \uc54c\uc544\ubcf4\ub294 \uacbd\ud5d8\uacfc \uc790\uc11d\uc5d0 \ubc18\uc751\ud558\ub294 \uc131\uc9c8\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc7ac\ub8cc\ub97c \uc77d\ub294 \ub370 \uc2dc\uac01\ub9cc\uc774 \uc720\uc77c\ud55c \ub3c4\uad6c\ub294 \uc544\ub2c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \uac15\ucca0\uc774 \ub4e4\uc5b4 \uc788\uc73c\uba74 \uc5b4\ub5a4 \uc870\uac74\uc5d0\uc11c\ub3c4 \uac19\uc740 \uc815\ub3c4\ub85c \ubd99\ub294\ub2e4\uace0 \ud310\ub2e8\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774 \uae00\uc740 \uc870\ud3d0\uad6d\uc774 \uc124\uba85\ud55c \ub450 \uc7ac\ub8cc\uc758 \ucc28\uc774\ub97c \uc18c\uac1c\ud55c\ub2e4. \uc2e4\uc81c \ub3d9\uc804\uc758 \uc815\ud655\ud55c \uad6c\uc131\uc744 \uc2dd\ubcc4\ud558\ub824\uba74 \ud574\ub2f9 \uc561\uba74\uacfc \uc2dc\uae30\uc758 \uc790\ub8cc\ub3c4 \ud568\uaed8 \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \ubc18\uc751 \ud558\ub098\ub85c \ub098\ub77c\uc640 \uc5f0\ub3c4, \ud1b5\uc6a9 \uc5ec\ubd80\uae4c\uc9c0 \ubaa8\ub450 \ud310\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc0c8 \uc7ac\ub8cc\ub97c \uc37c\uc5b4\ub3c4 \uc0c9\uacfc \uc9c0\ub984, \ubb34\uac8c\uc640 \ub514\uc790\uc778\uc744 \uac19\uac8c \uc720\uc9c0\ud588\ub2e4\ub294 \uc124\uba85\uc740 \ubcc0\ud654\uac00 \ud56d\uc0c1 \uac89\uc73c\ub85c \ub4dc\ub7ec\ub098\ub294 \uac83\uc740 \uc544\ub2d8\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \uc54c\uc544\ubcf4\ub294 \ud45c\uba74\uc744 \uc720\uc9c0\ud558\uba74\uc11c \ub9cc\ub4dc\ub294 \uc870\uac74\uc744 \ubc14\uafb8\ub294 \uc120\ud0dd\uc774\ub2e4. \ub2e4\ub9cc \uc774 \uc720\uc0ac\ud568\uc744 \uadfc\uac70\ub85c \ub450 \ubb3c\uac74\uc774 \ubb3c\ub9ac\uc801\uc73c\ub85c \ubaa8\ub4e0 \uc810\uc5d0\uc11c \ub3d9\uc77c\ud558\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub3d9\uc804\uc740 \ubc18\ubcf5\ud574\uc11c \uc190\uc5d0 \uc950\ub294 \ubb3c\uac74\uc774\ub77c \ud070 \ubaa8\uc591\uc774 \uacc4\uc18d \uc774\uc5b4\uc9c0\ub294 \uc77c\uc774 \uc911\uc694\ud558\uac8c \ub290\uaef4\uc9c4\ub2e4. \uadf8 \ub4a4\uc758 \uae08\uc18d \uad6c\uc131\uc740 \ud3c9\uc18c\uc5d0 \ub35c \uc758\uc2dd\ud560 \uc218 \uc788\ub2e4. \uc790\uc11d\uc744 \ud568\uaed8 \ub193\uc558\uc744 \ub54c \ube44\ub85c\uc18c \ub2e4\ub978 \uc131\uc9c8\uc774 \ub4dc\ub7ec\ub098\ub294 \uac83\uc774\ub2e4. \uc775\uc219\ud55c \ubb3c\uac74\uc744 \uc7ac\ub8cc\uc758 \uc9c8\ubb38\uc73c\ub85c \ub2e4\uc2dc \uc77d\uc73c\uba74 \uac89\ubaa8\uc2b5\uc5d0\uc11c \uc9c0\ub098\ucce4\ub358 \ubcc0\ud654\uac00 \ubcf4\uc778\ub2e4. 1992\ub144 9\uc6d4\uc774\ub77c\ub294 \uc2dc\uc810\uc740 \uc870\ud3d0\uad6d\uc774 \uc124\uba85\ud558\ub294 \uc7ac\ub8cc \uc804\ud658\uc758 \uae30\uc900\uc774\ub2e4. \ud558\uc9c0\ub9cc \uac1c\ubcc4 \ub3d9\uc804\uc744 \uc5b4\ub5a4 \uc7ac\ub8cc\ub85c \ub9cc\ub4e4\uc5c8\ub294\uc9c0 \uc790\uc138\ud788 \ud655\uc778\ud558\ub824\uba74 \ud574\ub2f9 \uc790\ub8cc\ub97c \ub354 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc561\uba74\uacfc \uc885\ub958\uac00 \ub2ec\ub77c\uc838\ub3c4 \uac19\uc740 \uc2dc\uc810\uc758 \uaddc\uce59\uc744 \ubb34\uc870\uac74 \uc801\uc6a9\ud558\ub294 \ubc29\uc2dd\uc740 \ud53c\ud558\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \uc774 \uc774\uc57c\uae30\ub294 \ubaa8\ub4e0 \ub3d9\uc804\uc744 \uac00\ub974\ub294 \uc138\uacc4 \uacf5\ud1b5\ud45c\uac00 \uc544\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc790\uc11d\uc5d0 \ubd99\uc9c0 \uc54a\ub294\ub2e4\uace0 \uadf8 \ub3d9\uc804\uc744 \uace7 \uac00\uc9dc\ub77c\uace0 \ubd80\ub97c \uc218\ub294 \uc5c6\ub2e4. \uc815\uc2dd \ub3d9\uc804\ub3c4 \uc7ac\ub8cc\uac00 \ub2e4\ub97c \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \ubc14\ub85c \uc774 \uc0ac\ub840\uc758 \ucd9c\ubc1c\uc810\uc774\ub2e4. \ubb3c\uac74\uc758 \uc9c4\uc704\uc640 \uc790\uc131\uc774\ub77c\ub294 \ud55c \uac00\uc9c0 \uc131\uc9c8\uc740 \ub2e4\ub978 \uc9c8\ubb38\uc774\ub2e4. \uad00\ucc30 \uacb0\uacfc\uc5d0\uc11c \ub108\ubb34 \uba3c \uacb0\ub860\uc73c\ub85c \ub098\uc544\uac00\uc9c0 \uc54a\uc73c\uba74 \uac04\ub2e8\ud55c \ube44\uad50\ub3c4 \ub354 \uc7ac\ubbf8\uc788\ub294 \ud0d0\uad6c\uac00 \ub41c\ub2e4. \ub3d9\uc804 \ub450 \uac1c\ub97c \ub098\ub780\ud788 \uc0dd\uac01\ud574 \ubcf4\uba74 \uc22b\uc790\uc640 \uadf8\ub9bc\uc740 \ub2ee\uc558\ub294\ub370 \uc548\ucabd\uc758 \uc7ac\ub8cc\ub294 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uadf8 \ucc28\uc774\uac00 \uc790\uc11d\uacfc\uc758 \uad00\uacc4\uc5d0\uc11c \ub4dc\ub7ec\ub09c\ub2e4. \uc77c\uc0c1\uc5d0\uc11c \uc7ac\ub8cc\uc758 \uc131\uc9c8\uc740 \ub208\uc5d0 \ubcf4\uc774\ub294 \uc774\ub984\ubcf4\ub2e4 \ud589\ub3d9\uc73c\ub85c \ud655\uc778\ub418\uae30\ub3c4 \ud55c\ub2e4. \ub2e4\ub9cc \uc2e4\uc81c \ubb3c\uac74\uc744 \ud6fc\uc190\ud558\uac70\ub098 \uc798\ub77c \ubcf4\uc544\uc57c \ud55c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uacf5\uc2dd \uc790\ub8cc\uc640 \ube44\ud30c\uad34\uc801\uc778 \uad00\ucc30\ub85c\ub3c4 \uc774\ud574\ud560 \uc218 \uc788\ub294 \ubd80\ubd84\uc774 \uc788\ub2e4. \uae08\uc18d\uc774\ub77c\ub294 \ud55c \ubc94\uc8fc \uc548\uc5d0\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc131\uc9c8\uc774 \uc788\ub2e4\ub294 \uc810\uc744 \uae30\uc5b5\ud574 \ubcf4\uc790. \uc791\uc740 \ub3d9\uc804\uc740 \ud654\ud3d0\uc774\uba74\uc11c \uc7ac\ub8cc\ub97c \uc120\ud0dd\ud574 \ub9cc\ub4e0 \uc81c\ud488\uc774\ub2e4. \uac00\uaca9\uacfc \uc561\uba74\uc73c\ub85c\ub9cc \ubcf4\ub358 \ubb3c\uac74\uc744 \ud45c\uba74\uacfc \ub0b4\ubd80\ub85c \ub098\ub204\uc5b4 \ubcf4\ub294 \uc21c\uac04, \uc870\ud3d0\uc758 \uc5ed\uc0ac\uac00 \uc190\ub05d\uc758 \uacfc\ud559\uacfc \ub9cc\ub09c\ub2e4. \ub2ee\uc558\ub2e4\ub294 \uccab\uc778\uc0c1\uc740 \uc9c8\ubb38\uc758 \ub05d\uc774 \uc544\ub2c8\ub77c \uc2dc\uc791\uc774 \ub420 \uc218 \uc788\ub2e4. \ub3d9\uc804\uc5d0\ub294 \ucd08\uc0c1\uacfc \uc22b\uc790\ub9cc \uc788\ub294 \uac83 \uac19\uc9c0\ub9cc, \uc7ac\ub8cc\uc758 \uc5ed\uc0ac\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \uc190\uc5d0 \uc954 \ub3c8\uc774 \uc5b8\uc81c \uc5b4\ub5a4 \uae08\uc18d\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc84c\ub294\uc9c0 \uc0b4\ud53c\uba74 \ud45c\uba74\uc758 \uadf8\ub9bc\uacfc\ub294 \ub2e4\ub978 \uc774\uc57c\uae30\ub97c \ub9cc\ub098\uac8c \ub41c\ub2e4. \uc790\uc11d\uc5d0 \ubd99\uc740 \ub3d9\uc804\uacfc \ubd99\uc9c0 \uc54a\uc740 \ub3d9\uc804\uc744 \ub098\ub780\ud788 \ub5a0\uc62c\ub9ac\uba74, \ubcf4\uc774\ub294 \ubaa8\uc2b5\uacfc \uc2e4\uc81c \uad6c\uc131\uc774 \ub2e4\ub97c \uc218 \uc788\ub2e4\ub294 \ub9d0\uc774 \uaf64 \uad6c\uccb4\uc801\uc73c\ub85c \ub290\uaef4\uc9c4\ub2e4. \uc5b4\ub824\uc6b4 \uacf5\uc2dd\ubcf4\ub2e4 \uc190\ubc14\ub2e5\uc5d0 \uc62c\ub77c\uc624\ub294 \ubb3c\uac74\uc774 \uba3c\uc800 \uc774\ud574\ub97c \ub3d5\ub294\ub2e4. \ub2e4\uc74c\uc5d0 \uad6c\ub9ac\ube5b \ub3d9\uc804\uc744 \ubcf4\uac8c \ub41c\ub2e4\uba74 \uac89\uc758 \uc0c9\ub9cc\uc73c\ub85c \uc18d\uae4c\uc9c0 \ub2e4 \uc548\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc88b\uaca0\ub2e4. \uc775\uc219\ud55c \ud45c\uba74 \uc544\ub798\uc5d0\uc11c \uc7ac\ub8cc\ub294 \uc774\ubbf8 \ub2e4\ub978 \uc2dc\ub300\ub85c \ub118\uc5b4\uac14\uc744\uc9c0\ub3c4 \ubaa8\ub978\ub2e4."}, {"id": "marie-curie-life-and-discovery", "title": "\ub9c8\ub9ac \ud034\ub9ac\uc758 \uc0dd\uc560 \u2014 \ubc18\uc9dd\uc774\ub294 \ubc1c\uacac \ub4a4\uc758 \uc624\ub798\ub41c \uc2e4\ud5d8\uc2e4", "summary": "\uc720\ud559\uacfc \uacf5\ub3d9 \uc5f0\uad6c, \ub450 \ubc88\uc758 \ub178\ubca8\uc0c1\uacfc \uc804\uc2dc \ud65c\ub3d9\uc744 \ud1b5\ud574 \ubc1c\uacac\uc744 \uc774\uc5b4 \uac00\ub294 \uc0b6\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uacfc\ud559\uc790\uc758 \ubc1c\uacac", "categories": ["science"], "url": "stories/marie-curie-life-and-discovery/index.html", "image": "../media/marie-curie-life-and-discovery.jpg", "alt": "\ud30c\ub9ac \ud034\ub9ac \uc5f0\uad6c\uc18c\uc758 \uc2e4\ud5d8\uc2e4\uc5d0\uc11c \uc7a5\ube44 \uacc1\uc5d0 \uc549\uc544 \uc788\ub294 \ub9c8\ub9ac \ud034\ub9ac\uc758 \uc61b \uc0ac\uc9c4.", "text": "\ub9c8\ub9ac \ud034\ub9ac\uc758 \uc0dd\uc560 \u2014 \ubc18\uc9dd\uc774\ub294 \ubc1c\uacac \ub4a4\uc758 \uc624\ub798\ub41c \uc2e4\ud5d8\uc2e4 \ubc14\ub974\uc0e4\ubc14\uc758 \ubc30\uc6c0\uc5d0\uc11c \ud30c\ub9ac\uc758 \uc5f0\uad6c\uc640 \uc804\uc7a5\uc758 X\uc120 \ucc28\ub7c9\uae4c\uc9c0 \uc720\ud559\uacfc \uacf5\ub3d9 \uc5f0\uad6c, \ub450 \ubc88\uc758 \ub178\ubca8\uc0c1\uacfc \uc804\uc2dc \ud65c\ub3d9\uc744 \ud1b5\ud574 \ubc1c\uacac\uc744 \uc774\uc5b4 \uac00\ub294 \uc0b6\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uacfc\ud559\uc790\uc758 \ubc1c\uacac \uacfc\ud559\uacfc \ubc1c\uacac \uc2e4\ud5d8\uc2e4\uc758 \uc0ac\uc9c4 \uc18d \ub9c8\ub9ac \ud034\ub9ac\ub294 \uc7a5\ube44\uc5d0 \ub458\ub7ec\uc2f8\uc5ec \uc788\ub2e4. \uc6b0\ub9ac\uc5d0\uac8c \uc775\uc219\ud55c \uac83\uc740 \ub178\ubca8\uc0c1\uc744 \ub450 \ubc88 \ubc1b\uc740 \uacfc\ud559\uc790\uc758 \uc774\ub984\uc774\uc9c0\ub9cc, \uc0ac\uc9c4\uc740 \uc0c1\ubcf4\ub2e4 \uc77c\uc744 \uba3c\uc800 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uce21\uc815\ud558\uace0 \uc815\ub9ac\ud558\uace0 \ub2e4\uc2dc \ud655\uc778\ud558\ub294 \uc2dc\uac04\uc774 \ubc1c\uacac\uc758 \ud55c\uac00\uc6b4\ub370 \uc788\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4. \uadf8\ub294 1867\ub144\uc5d0 \ud0dc\uc5b4\ub098 1934\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub0ac\ub2e4. \ubc14\ub974\uc0e4\ubc14\uc5d0\uc11c \uacf5\ubd80\ud558\ub358 \uccad\ub144\uc774 \ud30c\ub9ac\uc758 \uc5f0\uad6c\uc790\uac00 \ub418\uace0 \uc804\uc7c1 \uc911\uc5d0\ub294 X\uc120 \uc7a5\ube44\ub97c \uc2e4\uc740 \ucc28\ub7c9\uc744 \uc6c0\uc9c1\uc774\ub294 \uc77c\uc5d0\ub3c4 \ub098\uc120\ub2e4. \ud55c \ubc88\uc758 \ucc9c\uc7ac\uc801\uc778 \uc21c\uac04\ubcf4\ub2e4 \uadf8 \uc5ec\ub7ec \uc804\ud658\uc744 \ub530\ub77c\uac00 \ubcf4\uba74 \uc0b6\uc758 \ud3ed\uc774 \ubcf4\uc778\ub2e4. \ub9c8\ub9ac\uc758 \uc6d0\ub798 \uc774\ub984\uc740 \ub9c8\ub9ac\uc544 \uc2a4\ud06c\uc6cc\ub3c4\ud504\uc2a4\uce74\ub2e4. \ud3f4\ub780\ub4dc\uc758 \uad50\uc0ac \uc9d1\uc548\uc5d0\uc11c \uc790\ub790\uace0 \ubc30\uc6c0\uc5d0 \ub300\ud55c \uad00\uc2ec\ub3c4 \ucef8\ub2e4. \uadf8\ub7ec\ub098 \uc6d0\ud558\ub294 \uacf5\ubd80\ub97c \ubc14\ub85c \uc2dc\uc791\ud560 \uc218 \uc788\ub294 \uc870\uac74\uc774 \ub298 \uac16\ucd94\uc5b4\uc838 \uc788\uc9c0\ub294 \uc54a\uc558\ub2e4. \uc77c\ud558\uace0 \ub3c8\uc744 \ub9c8\ub828\ud558\uba70 \uc55e\uc73c\ub85c\uc758 \ud559\uc5c5\uc744 \uc900\ube44\ud558\ub294 \uc2dc\uac04\uc774 \ud544\uc694\ud588\ub2e4. \uc790\uc804\uc801 \uae30\ub85d\uc5d0\ub294 \uac00\uc815\uad50\uc0ac\ub85c \uc9c0\ub0b4\uba74\uc11c\ub3c4 \uacf5\ubd80\ub97c \uc774\uc5b4 \uac00\ub358 \uc0dd\ud65c\uc774 \ub098\uc628\ub2e4. \ub4a4\uc758 \uba85\uc131\uc744 \uc54c\uace0 \uc77d\uc73c\uba74 \uc7a0\uc2dc \uac70\uccd0 \uac04 \uc900\ube44 \uae30\uac04\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc, \ub2f9\uc2dc\uc5d0\ub294 \uc5b8\uc81c \uae30\ud68c\uac00 \uc5f4\ub9b4\uc9c0 \ud655\uc2e4\ud558\uc9c0 \uc54a\uc740 \uc0b6\uc774\uc5c8\ub2e4. \ud559\ubb38\uc801 \uc5f4\uc815\uacfc \uc0dd\ud65c\ube44\uc758 \ubb38\uc81c\ub294 \uc11c\ub85c \ub2e4\ub978 \uc138\uacc4\uc5d0 \ub193\uc5ec \uc788\uc9c0 \uc54a\uc558\ub2e4. 1891\ub144 \uadf8\ub294 \ud30c\ub9ac\uc5d0 \uac00\uc11c \uacf5\ubd80\ub97c \uc2dc\uc791\ud55c\ub2e4. \uc0c8\ub85c\uc6b4 \uc5b8\uc5b4\uc640 \ub3c4\uc2dc, \ube60\ub4ef\ud55c \uc0dd\ud65c\uc744 \uac10\ub2f9\ud558\uba70 \ubb3c\ub9ac\ud559\uacfc \uc218\ud559\uc744 \ubc30\uc6e0\ub2e4. \ub0af\uc120 \uacf3\uc5d0 \ub3c4\ucc29\ud588\ub2e4\ub294 \uc7a5\uba74\uc73c\ub85c \ub05d\ub0b4\uae30\ubcf4\ub2e4, \uc218\uc5c5\uc744 \ub530\ub77c\uac00\uace0 \uc0dd\ud65c\uc744 \uafb8\ub9ac\ub294 \ud558\ub8e8\uac00 \uacc4\uc18d\ub418\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uc720\ud559\uc758 \ubb34\uac8c\uac00 \ub354 \uad6c\uccb4\uc801\uc774\ub2e4. \uc774 \uc2dc\uae30\uc758 \ub9c8\ub9ac\ub97c \uc774\ubbf8 \uc704\ub300\ud55c \ubc1c\uacac\uc744 \uc55e\ub454 \uc601\uc6c5\uc73c\ub85c\ub9cc \ubcfc \ud544\uc694\ub294 \uc5c6\ub2e4. \ubb34\uc5c7\uc744 \uc5f0\uad6c\ud560\uc9c0 \ucc3e\uace0 \ud544\uc694\ud55c \ub3c4\uad6c\uc640 \uae30\ucd08\ub97c \ubc30\uc6b0\ub294 \ud559\uc0dd\uc774\uc5c8\ub2e4. \uc774\ud6c4\uc758 \uacf5\ub3d9 \uc5f0\uad6c\ub3c4 \uadf8\ub7f0 \ubc30\uc6c0\uacfc \ub9cc\ub0a8 \uc18d\uc5d0\uc11c \uac00\ub2a5\ud574\uc84c\ub2e4. \ud53c\uc5d0\ub974 \ud034\ub9ac\uc640\uc758 \uad00\uacc4\uc5d0\ub294 \uacb0\ud63c\uacfc \uac00\uc871\ubfd0 \uc544\ub2c8\ub77c \uc2e4\ud5d8\uacfc \ub17c\uc758\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \ud53c\uc5d0\ub974\ub294 \uc774\ubbf8 \uc5f0\uad6c \uacbd\ud5d8\uc744 \uac00\uc9c4 \ubb3c\ub9ac\ud559\uc790\uc600\uace0, \ub9c8\ub9ac\ub294 \uc790\uae30 \uc5f0\uad6c \ubb38\uc81c\ub97c \uc138\uc6cc \ub098\uac14\ub2e4. \ub450 \uc0ac\ub78c\uc740 \uac01\uc790\uc758 \ub2a5\ub825\uacfc \uc791\uc5c5\uc744 \uacf5\ub3d9\uc758 \ud0d0\uad6c\uc5d0 \uc5f0\uacb0\ud588\ub2e4. \ub9c8\ub9ac\ub294 \ub0a8\ud3b8\uc758 \uc774\ub984\uc744 \uc54c\ub9ac\ub294 \uc774\uc57c\uae30 \uc18d \uc870\uc218\ub9cc\ub3c4 \uc544\ub2c8\uace0, \ub2e4\ub978 \uc0ac\ub78c\uc758 \ub3c4\uc6c0 \uc5c6\uc774 \ubaa8\ub4e0 \uac83\uc744 \uc774\ub8e8\uc5b4 \ub0b8 \uace0\ub9bd\ub41c \ucc9c\uc7ac\ub9cc\ub3c4 \uc544\ub2c8\ub2e4. \uc5f0\uad6c \uc8fc\uc81c\uc758 \uc120\ud0dd\uacfc \uce21\uc815, \ud611\ub825\uc758 \ubc29\uc2dd\uc774 \uc5b4\ub5bb\uac8c \uc774\uc5b4\uc84c\ub294\uc9c0\ub97c \ubcf4\uba74 \uc0ac\ub78c\uc774 \ud568\uaed8 \uc77c\ud558\uba70 \ubc1c\uacac\uc744 \ud0a4\uc6b0\ub294 \uacfc\uc815\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \ubca0\ud06c\ub810\uc774 \uc5f0\uad6c\ud55c \uc6b0\ub77c\ub284\uc758 \ubc29\ucd9c \ud604\uc0c1\uc744 \uacc4\uae30\ub85c \ub9c8\ub9ac\ub294 \uad00\ub828 \ubb3c\uc9c8\uc744 \uc0b4\ud3c8\ub2e4. \uc5b4\ub5a4 \uad11\uc11d\uc758 \ud6a8\uacfc\uac00 \uc6b0\ub77c\ub284\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uae30\uc5d0 \uc9c0\ub098\uce58\uac8c \uac15\ud558\ub2e4\ub294 \uc810\uc774 \uc0c8\ub85c\uc6b4 \uc9c8\ubb38\uc774 \ub41c\ub2e4. \uc774\ubbf8 \uc54c\ub824\uc9c4 \uc131\ubd84\uc73c\ub85c \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4\uba74 \uadf8 \uc548\uc5d0 \ub2e4\ub978 \ubb3c\uc9c8\uc774 \uc788\ub294 \uac83\uc740 \uc544\ub2d0\uae4c. 1898\ub144\uc5d0\ub294 \ud3f4\ub85c\ub284\uacfc \ub77c\ub4d0\uc758 \uc874\uc7ac\ub97c \uc54c\ub9ac\ub294 \uc5f0\uad6c\uac00 \uc774\uc5b4\uc84c\ub2e4. \ud3f4\ub85c\ub284\uc774\ub77c\ub294 \uc774\ub984\uc5d0\ub294 \uace0\ud5a5 \ud3f4\ub780\ub4dc\uac00 \ub2f4\uaca8 \uc788\ub2e4. \uc774\ub984 \ubd99\uc774\uae30\ub294 \ub0ad\ub9cc\uc801\uc778 \uc7a5\uc2dd\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \ubc1c\uacac\uc744 \ubb34\uc5c7\uc73c\ub85c \uc2dd\ubcc4\ud560\uc9c0 \uc815\ud558\uba74\uc11c \ud55c \uc5f0\uad6c\uc790\uc758 \uac1c\uc778\uc801\u00b7\uc5ed\uc0ac\uc801 \ubc30\uacbd\ub3c4 \ud568\uaed8 \ub0a8\ub294 \uc77c\uc774\ub2e4. \uc874\uc7ac\ub97c \ucd94\uc815\ud558\uace0 \ubc1c\ud45c\ud558\ub294 \uac83\uacfc \ucda9\ubd84\ud788 \ubd84\ub9ac\ud558\uc5ec \uc131\uc9c8\uc744 \ud655\uc778\ud558\ub294 \uac83\uc740 \uac19\uc740 \ub2e8\uacc4\uac00 \uc544\ub2c8\ub2e4. \ub9ce\uc740 \uc7ac\ub8cc\ub97c \ucc98\ub9ac\ud558\uace0 \ubc18\ubcf5\ud574\uc11c \ubd84\ub9ac\uc640 \uce21\uc815\uc744 \ud574\uc57c \ud588\ub2e4. \uc790\uc804\uc801 \uae30\ub85d\uc740 \uc774\ub7f0 \uc791\uc5c5\uc5d0 \ub4e4\uc5b4\uac04 \ubb3c\ub9ac\uc801\uc778 \uc218\uace0\uc640 \uc5f4\uc545\ud55c \uc2e4\ud5d8 \uc870\uac74\uc744 \uc790\uc138\ud788 \uc804\ud55c\ub2e4. \ubc1c\uacac\uc774\ub77c\ub294 \ub9d0\uc744 \ub4e3\uace0 \uc720\ub9ac\ubcd1 \ud558\ub098\uc5d0\uc11c \uac11\uc790\uae30 \ube5b\uc774 \ud130\uc9c0\ub294 \uc7a5\uba74\ub9cc \uc0c1\uc0c1\ud558\uba74 \uc774 \uae34 \uacfc\uc815\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \uc5b4\ub5a4 \uc218\uce58\uac00 \uc65c \ub2e4\ub978\uc9c0 \ud655\uc778\ud558\uace0 \ub2e4\ub978 \uac00\ub2a5\uc131\uc744 \uc881\ud600 \uac00\ub294 \uc77c\uc774 \uc911\uc694\ud588\ub2e4. \uc9c1\uac10\uacfc \ub048\uae30\ub294 \uc2e4\ud5d8\uc744 \ub300\uc2e0\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc2e4\uc81c \ud655\uc778\uc758 \uacfc\uc815 \uc548\uc5d0\uc11c \ud798\uc744 \uc5bb\ub294\ub2e4. 1903\ub144 \ub9c8\ub9ac\uc640 \ud53c\uc5d0\ub974, \ubca0\ud06c\ub810\uc740 \ud568\uaed8 \ub178\ubca8\uc0c1\uc744 \ubc1b\ub294\ub2e4. \uc5f0\uad6c\uac00 \ub110\ub9ac \uc54c\ub824\uc9c0\uace0 \uc9c0\uc6d0\ub3c4 \ub298\uc9c0\ub9cc \ubc29\ubb38\uacfc \uc694\uad6c\uac00 \ub9ce\uc544\uc838 \uc77c\uc0c1\uc758 \ud3c9\uc628\uc740 \uc904\uc5b4\ub4e4\uc5c8\ub2e4\uace0 \uae30\ub85d\ud55c\ub2e4. \uba85\uc608\uac00 \uc0dd\uacbc\ub2e4\uace0 \uc2e4\ud5d8\uacfc \uc0dd\ud65c\uc758 \ubaa8\ub4e0 \uc5b4\ub824\uc6c0\uc774 \ub05d\ub098\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. 1906\ub144 \ud53c\uc5d0\ub974\uac00 \uc0ac\uace0\ub85c \uc138\uc0c1\uc744 \ub5a0\ub09c \ub4a4 \ub9c8\ub9ac\ub294 \ud070 \uc0c1\uc2e4 \uc18d\uc5d0\uc11c\ub3c4 \uc5f0\uad6c\uc640 \uac15\uc758\ub97c \uc774\uc5b4 \uac14\ub2e4. 1911\ub144\uc5d0\ub294 \ub450 \ubc88\uc9f8 \ub178\ubca8\uc0c1\uc744 \ubc1b\ub294\ub2e4. \ub450 \ubc88\uc758 \uc218\uc0c1 \uc0ac\uc774\ub97c \uc22b\uc790\ub85c\ub9cc \uc5f0\uacb0\ud558\uba74 \uac1c\uc778\uc758 \uc2ac\ud514\uacfc \uc77c\uc744 \uc9c0\uc18d\ud558\uae30 \uc704\ud55c \uc120\ud0dd\uc774 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc0c1\uc740 \uc774 \uc0b6\uc758 \uc911\uc694\ud55c \ud45c\uc9c0\uc9c0\ub9cc \uc0b6 \uc804\uccb4\ub97c \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc81c1\ucc28 \uc138\uacc4\ub300\uc804 \uc911\uc5d0\ub294 \ubd80\uc0c1\uc790\ub97c \uc0b4\ud53c\ub294 \ub370 \ud544\uc694\ud55c X\uc120 \uc7a5\ube44\uc640 \uc778\ub825\uc744 \ub9c8\ub828\ud558\ub294 \ud65c\ub3d9\uc5d0 \ub098\uc120\ub2e4. \uc774\ub3d9 \ucc28\ub7c9\uc5d0 \uc7a5\ube44\uc640 \ubc1c\uc804\uae30\ub97c \uc2e3\uace0 \ubcd1\uc6d0\uc758 \ucd2c\uc601\uc744 \ub3d5\ub294 \ubc29\uc2dd\uc774\uc5c8\ub2e4. \uc5f0\uad6c\ud55c \uc9c0\uc2dd\uc744 \uc5b4\ub514\uc5d0\uc11c \uc5b4\ub5a4 \ud544\uc694\uc5d0 \uc5f0\uacb0\ud560\uc9c0 \ud310\ub2e8\ud558\ub294 \ub610 \ub2e4\ub978 \uc885\ub958\uc758 \uc77c\uc774\uc5c8\ub2e4. \ub77c\ub4d0 \uac19\uc740 \ubc29\uc0ac\uc131 \uc6d0\uc18c\uc758 \uc5f0\uad6c\uc640 X\uc120 \ucd2c\uc601 \uc7a5\ube44\uc758 \uc6b4\uc601\uc740 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc804\uc7a5\uc758 \ucc28\ub7c9\uc740 X\uc120 \uc7a5\ube44\ub97c \uc0ac\uc6a9\ud588\ub2e4. \ub9c8\ub9ac\ub294 \uc7a5\ube44\ub9cc \uc804\ub2ec\ud558\ub294 \ub370\uc11c \uadf8\uce58\uc9c0 \uc54a\uace0 \uc774\ub97c \ub2e4\ub8f0 \uc0ac\ub78c\uc744 \uad50\uc721\ud558\ub294 \uc77c\ub3c4 \uc911\uc694\ud558\uac8c \uc5ec\uacbc\ub2e4. \ub538 \uc774\ub80c\ub3c4 \uc804\uc2dc \ud65c\ub3d9\uc5d0 \ucc38\uc5ec\ud588\ub2e4. \ub9c8\ub9ac\uc758 \uae30\ub85d\uc5d0\ub294 \ub77c\ub4d0\uacfc \uad00\ub828\ud55c \uc5f0\uad6c\uc5d0\uc11c \ud2b9\ud5c8\ub85c \ub3c5\uc810\uc801\uc778 \uc774\uc775\uc744 \ub0a8\uae30\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc124\uba85\ub3c4 \uc788\ub2e4. \uc5f0\uad6c \uacb0\uacfc\uc640 \uc81c\uc870 \ubc29\ubc95\uc774 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc804\ud574\uc838\uc57c \ud558\ub294\uc9c0\uc5d0 \uad00\ud55c \uc120\ud0dd\uc774\ub2e4. \uc774\ub97c \ubaa8\ub4e0 \uc2dc\ub300\uc640 \ubaa8\ub4e0 \uc5f0\uad6c\uc5d0 \ub611\uac19\uc774 \uc801\uc6a9\ud560 \uc815\ub2f5\uc73c\ub85c \ub9cc\ub4e4\uae30\ubcf4\ub2e4 \uadf8\uac00 \uc2e4\uc81c\ub85c \ucde8\ud55c \ud0dc\ub3c4\ub85c \uc77d\uc73c\uba74 \uc88b\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 1923\ub144 \uc800\uc11c\uc5d0 \uc218\ub85d\ub41c \ud30c\ub9ac \ud034\ub9ac \uc5f0\uad6c\uc18c \uc2e4\ud5d8\uc2e4\uc758 \uc2e4\uc81c \uc0ac\uc9c4\uc774\ub2e4. \ubc1c\uacac\uc758 \uc21c\uac04\uc744 \uc7ac\ud604\ud55c \uc5f0\ucd9c \uadf8\ub9bc\uc774 \uc544\ub2c8\ub2e4. \uc7a5\ube44 \uacc1\uc758 \ud55c \uc0ac\ub78c\uc744 \ubc14\ub77c\ubcf4\uba70, \uc774\ub984 \ub4a4\uc5d0 \uc788\ub358 \uacf5\ubd80\uc640 \uce21\uc815, \ud611\ub825\uacfc \ub3cc\ubd04\uc758 \uc2dc\uac04\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uacfc\ud559\uc758 \uae4a\uc774\ub294 \uc5b4\ub824\uc6b4 \uacf5\uc2dd\ub9cc\uc774 \uc544\ub2c8\ub77c \uadf8\ub7f0 \uc77c\uc744 \ub05d\uae4c\uc9c0 \ud655\uc778\ud574 \uac00\ub294 \uc0dd\ud65c\uc5d0\uc11c\ub3c4 \ub9cc\ub0a0 \uc218 \uc788\ub2e4."}, {"id": "mendel-peas-and-returning-traits", "title": "\uba58\ub378 \u2014 \uc0ac\ub77c\uc9c4 \uac83 \uac19\ub358 \ud770 \uaf43\uc740 \uc65c \ub2e4\uc2dc \ud53c\uc5c8\uc744\uae4c", "summary": "1850~1860\ub144\ub300 \uc644\ub450\ucf69 \uc2e4\ud5d8\uc758 \uc120\ud0dd\uacfc \uae30\ub85d, 1865\ub144 \ubc1c\ud45c\uc640 \ub4a4\ub2a6\uc740 \uad00\uc2ec\uc744 \ub530\ub77c \uc720\uc804 \uc5f0\uad6c\uc758 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uacfc\ud559\uc790\uc758 \ubc1c\uacac", "categories": ["science"], "url": "stories/mendel-peas-and-returning-traits/index.html", "image": "../media/mendel-peas-and-returning-traits.png", "alt": "\uc644\ub450\uc758 \uaf43\uc744 \uad00\ucc30\ud558\ub294 \uc218\ub3c4\uc6d0 \uc5f0\uad6c\uc790\uc758 \uc0c1\uc0c1 \uc7a5\uba74", "text": "\uba58\ub378 \u2014 \uc0ac\ub77c\uc9c4 \uac83 \uac19\ub358 \ud770 \uaf43\uc740 \uc65c \ub2e4\uc2dc \ud53c\uc5c8\uc744\uae4c \uc218\ub3c4\uc6d0 \uc815\uc6d0\uc5d0\uc11c \uc5ec\ub7ec \uc138\ub300\uc758 \uc644\ub450\ucf69\uc744 \uc138\ub2e4 1850~1860\ub144\ub300 \uc644\ub450\ucf69 \uc2e4\ud5d8\uc758 \uc120\ud0dd\uacfc \uae30\ub85d, 1865\ub144 \ubc1c\ud45c\uc640 \ub4a4\ub2a6\uc740 \uad00\uc2ec\uc744 \ub530\ub77c \uc720\uc804 \uc5f0\uad6c\uc758 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uacfc\ud559\uc790\uc758 \ubc1c\uacac \uacfc\ud559\uacfc \ubc1c\uacac \ubcf4\ub77c\uc0c9 \uaf43\uacfc \ud770\uc0c9 \uaf43\uc758 \uc644\ub450\ucf69\uc744 \uad50\ubc30\ud588\ub294\ub370 \uccab \uc790\uc190\uc5d0\ub294 \ubcf4\ub77c\uc0c9 \uaf43\uc774 \ub098\ud0c0\ub0ac\ub2e4. \ud770\uc0c9\uc740 \uc0ac\ub77c\uc9c4 \uac83\ucc98\ub7fc \ubcf4\uc600\ub2e4. \uadf8\ub7f0\ub370 \uadf8\ub2e4\uc74c \uc138\ub300\uc5d0\uc11c\ub294 \ud770 \uaf43\uc774 \ub2e4\uc2dc \ud53c\uc5c8\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294 \ub3d9\uc548 \uadf8 \ud2b9\uc9d5\uc740 \uc5b4\ub514\uc5d0 \uc788\uc5c8\ub358 \uac83\uc77c\uae4c. \uadf8\ub808\uace0\uc5b4 \uba58\ub378\uc740 \uc774\ub7f0 \ubcc0\ud654\ub97c \uc5ec\ub7ec \uc138\ub300\uc5d0 \uac78\uccd0 \uad00\ucc30\ud558\uace0 \uc218\ub97c \uc138\uc5c8\ub2e4. \ubb34\uc5b8\uac00 \ud2b9\uc774\ud55c \uc2dd\ubb3c\uc744 \ud55c \ubc88 \ubc1c\uacac\ud55c \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub77c, \uc5b4\ub5a4 \uc2dd\ubb3c\uc744 \uace0\ub974\uace0 \uc5b4\ub5bb\uac8c \ube44\uad50\ud560\uc9c0\ub97c \uc624\ub798 \uc900\ube44\ud55c \uc5f0\uad6c\uc600\ub2e4. \uc218\ub3c4\uc6d0\uc758 \uc815\uc6d0\uc740 \ubc18\ubcf5\ud574\uc11c \uc9c8\ubb38\uc744 \ub358\uc9c8 \uc218 \uc788\ub294 \uc7a5\uc18c\uac00 \ub418\uc5c8\ub2e4. \uba58\ub378\uc740 \uc624\ub298\ub0a0 \uccb4\ucf54\uc758 \ube0c\ub974\ub178\uc5d0 \uc788\ub294 \uc544\uc6b0\uad6c\uc2a4\ud2f0\ub178\ud68c \uc218\ub3c4\uc6d0\uc5d0\uc11c \uc0dd\ud65c\ud588\ub2e4. \uad50\uc7ac\ub294 \uadf8\uac00 \uad50\uc0ac\uc774\uc790 \uc5f0\uad6c\uc790\ub85c \ubb3c\ub9ac\uc640 \uc2dd\ubb3c, \uc790\uc5f0\uacfc\ud559\uc744 \uacf5\ubd80\ud558\uace0 \uac00\ub974\ucce4\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc885\uad50\uc801 \uc0dd\ud65c\uacfc \uc790\uc5f0\uc744 \uc54c\uc544\ubcf4\ub824\ub294 \uad00\uc2ec\uc774 \uadf8\uc758 \uc0b6\uc5d0\uc11c \ud568\uaed8 \uc788\uc5c8\ub2e4. \uadf8\ub294 1850\ub144\ub300\ubd80\ud130 \uc5ec\ub7ec \ud574 \ub3d9\uc548 \uc720\uc804\uc758 \uc591\uc0c1\uc744 \uc5f0\uad6c\ud588\ub2e4. \ucc98\uc74c\ubd80\ud130 \uc644\ub450\ucf69\ub9cc \ubc14\ub77c\ubcf8 \uac83\uc740 \uc544\ub2c8\uc5c8\uc9c0\ub9cc \uacb0\uad6d \uadf8\uac83\uc744 \uc8fc\uc694\ud55c \uc5f0\uad6c \ub300\uc0c1\uc73c\ub85c \uc0bc\uc558\ub2e4. \uc5b4\ub5a4 \ub300\uc0c1\uc744 \uc120\ud0dd\ud560\uc9c0\ub294 \uc2e4\ud5d8\uc758 \uacb0\uacfc\ub9cc\ud07c \uc911\uc694\ud55c \uacb0\uc815\uc774\uc5c8\ub2e4. \uc9c8\ubb38\uc5d0 \ub9de\ub294 \ud2b9\uc9d5\uc744 \uac00\uc9c4 \uc0dd\ubb3c\uc774 \ud544\uc694\ud588\ub2e4. \uc644\ub450\ucf69\uc740 \ube44\uad50\uc801 \uc9e7\uc740 \uc2dc\uac04\uc5d0 \ub2e4\uc74c \uc138\ub300\ub97c \uc5bb\uc744 \uc218 \uc788\uace0 \uc5ec\ub7ec \uac1c\uccb4\ub97c \ud568\uaed8 \uae30\ub974\uae30 \uc88b\ub2e4. \uaf43\uc758 \uc0c9\ucc98\ub7fc \uad6c\ubd84\ud558\uae30 \uc26c\uc6b4 \ud2b9\uc9d5\ub3c4 \uc788\uc5c8\ub2e4. \uc790\uc5f0\uc801\uc73c\ub85c \uc2a4\uc2a4\ub85c \uc218\ubd84\ud558\ub294 \uc131\uc9c8\uc740 \uac19\uc740 \ud2b9\uc9d5\uc774 \uc774\uc5b4\uc9c0\ub294 \uacc4\ud1b5\uc744 \uc900\ube44\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub418\uc5c8\ub2e4. \uc774\ub7f0 \uc870\uac74\uc740 \uc6b0\uc5f0\ud788 \ubcf8 \ud55c \uc1a1\uc774\uc758 \uaf43\uacfc \uacc4\ud68d\ud55c \uc2e4\ud5d8\uc744 \uad6c\ubcc4\ud574 \uc900\ub2e4. \uba58\ub378\uc740 \ubd80\ubaa8 \uc2dd\ubb3c\uc758 \ud2b9\uc9d5\uc744 \ubbf8\ub9ac \uc54c\uace0 \uc5b4\ub5a4 \uc870\ud569\uc744 \ub9cc\ub4e4\uc5c8\ub294\uc9c0 \ube44\uad50\ud558\ub824 \ud588\ub2e4. \uacb0\uacfc\uac00 \uc65c \ub2ec\ub77c\uc84c\ub294\uc9c0 \uc54c\uc544\ubcf4\ub824\uba74 \uc2dc\uc791 \uc870\uac74\ubd80\ud130 \uc815\ub9ac\ud574\uc57c \ud588\ub358 \uac83\uc774\ub2e4. \uad50\uc7ac\ub294 \uba58\ub378\uc774 \uc11c\ub85c \ub2e4\ub978 \ud2b9\uc9d5\uc758 \uc2dd\ubb3c\uc744 \uad50\ubc30\ud558\uba74\uc11c \uc6d0\uce58 \uc54a\ub294 \uc790\uac00\uc218\ubd84\uc744 \ub9c9\ub3c4\ub85d \uaf43\uc744 \ub2e4\ub8e8\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\ub0e5 \uac19\uc740 \uc815\uc6d0\uc5d0 \uc2ec\uc5b4 \ub193\uace0 \uacb0\uacfc\ub97c \uae30\ub2e4\ub9b0 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uc2dd\ubb3c\uc758 \uaf43\uac00\ub8e8\uac00 \uc5b4\ub5a4 \uaf43\uc5d0 \ub2ff\uc558\ub294\uc9c0 \ud1b5\uc81c\ud558\ub824\ub294 \uc791\uc5c5\uc774 \uc788\uc5c8\ub2e4. \uadf8 \ub4a4\uc5d0\ub294 \uc528\uc557\uc744 \ubaa8\uc73c\uace0 \ub2e4\uc74c \uc138\ub300\uc758 \uc2dd\ubb3c\uc744 \uae38\ub7ec\uc57c \ud588\ub2e4. \ube60\ub978 \uacc4\uc0b0 \ud558\ub098\ub85c \ub05d\ub098\ub294 \uc2e4\ud5d8\uc774 \uc544\ub2c8\ub77c \uacc4\uc808\uc744 \uac74\ub108\uc57c \ud558\ub294 \uad00\ucc30\uc774\uc5c8\ub2e4. \uc5ec\ub7ec \uc138\ub300\ub97c \uacc4\uc18d \uae30\ub974\uace0 \uae30\ub85d\ud558\ub294 \ub2a5\ub825\uc774 \uaf43\uc758 \uc0c9\uc5d0 \uad00\ud55c \uc9c8\ubb38\uc744 \ub354 \uae34 \uc5f0\uad6c\ub85c \ub9cc\ub4e4\uc5c8\ub2e4. \ud2b9\uc9d5\uc774 \uc548\uc815\uc801\uc73c\ub85c \uc774\uc5b4\uc9c0\ub358 \ubcf4\ub77c\uc0c9 \uaf43\uc758 \uc2dd\ubb3c\uacfc \ud770\uc0c9 \uaf43\uc758 \uc2dd\ubb3c\uc744 \uad50\ubc30\ud558\uba74 \uccab \uc790\uc190\uc5d0\uc11c \ubcf4\ub77c\uc0c9\uc774 \ub098\ud0c0\ub0ac\ub2e4. \uc774\uac83\uc740 \ub450 \uc0c9\uc774 \ubb3c\uac10\uc744 \uc11e\ub4ef \uc911\uac04 \uc0c9\uc73c\ub85c \uc11e\uc600\ub2e4\ub294 \uc608\uc0c1\uacfc \ub2e4\ub974\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub358 \ud770\uc0c9\uc758 \uc815\ubcf4\uac00 \uc5b4\ub5bb\uac8c \ub418\uc5c8\ub294\uc9c0\ub77c\ub294 \uc0c8 \uc9c8\ubb38\uc774 \ub0a8\ub294\ub2e4. \uc5ec\uae30\uc11c \uc6b0\uc131\uacfc \uc5f4\uc131\uc774\ub77c\ub294 \ub9d0\uc744 \uac15\ud55c \uac83\uacfc \uc57d\ud55c \uac83, \uc88b\uc740 \uac83\uacfc \ub098\uc05c \uac83\uc73c\ub85c \uc77d\uc73c\uba74 \uc624\ud574\uac00 \uc0dd\uae34\ub2e4. \uc774 \uc2e4\ud5d8\uc5d0\uc11c \uc5b4\ub5a4 \ud2b9\uc9d5\uc774 \uac89\uc73c\ub85c \ub098\ud0c0\ub098\ub294\uc9c0 \uc124\uba85\ud558\ub294 \uad6c\ubd84\uc774\ub2e4. \uc2dd\ubb3c\uc758 \uac00\uce58\ub098 \uc0dd\uc874 \ub2a5\ub825\uc744 \ubaa8\ub450 \ud3c9\uac00\ud558\ub294 \uc774\ub984\uc740 \uc544\ub2c8\ub2e4. \uccab \uc790\uc190\uc744 \ud1b5\ud574 \ub2e4\uc74c \uc138\ub300\ub97c \uc5bb\uc790 \ud770 \uaf43\uc774 \ub2e4\uc2dc \ub098\ud0c0\ub0ac\ub2e4. \ub9ce\uc740 \uc2dd\ubb3c\uc744 \ubaa8\uc544 \ubcf4\uba74 \ubcf4\ub77c\uc0c9\uacfc \ud770\uc0c9\uc774 \ub300\ub7b5 \uc138 \ub300 \ud558\ub098\uc758 \ube44\uc728\ub85c \ub098\ud0c0\ub098\ub294 \uc591\uc0c1\uc774 \uc788\uc5c8\ub2e4. \ud770\uc0c9\uc774 \uc644\uc804\ud788 \uc18c\uba78\ud588\ub2e4\uba74 \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b4 \uacb0\uacfc\uc600\ub2e4. \ub2e4\ub9cc \uc791\uc740 \ud654\ubd84 \uba87 \uac1c\uc5d0\uc11c \uc5b8\uc81c\ub098 \uc815\ud655\ud788 \uc138 \uc1a1\uc774\uc640 \ud55c \uc1a1\uc774\uac00 \ub098\uc640\uc57c \ud55c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uac1c\ubcc4 \uacb0\uacfc\uc5d0\ub294 \ubcc0\ub3d9\uc774 \uc788\uace0 \ub9ce\uc740 \uc218\ub97c \ube44\uad50\ud560 \ub54c \ubcf4\uc774\ub294 \uaddc\uce59\uc774 \uc788\ub2e4. \uc5ec\ub7ec \uac1c\uccb4\uc640 \uc138\ub300\ub97c \uc138\ub294 \uc77c\uc774 \ub2e8\uc21c\ud55c \uaf43 \uad6c\uacbd\uc744 \ub118\uc5b4\uc11c\ub294 \uc774\uc720\ub2e4. \uba58\ub378\uc740 1865\ub144 \uc9c0\uc5ed \uc790\uc5f0\uc0ac\ud559\ud68c\uc5d0\uc11c \uacb0\uacfc\ub97c \ubc1c\ud45c\ud588\uace0 \ub2e4\uc74c \ud574 \ub17c\ubb38\uc744 \ub0c8\ub2e4. \uad50\uc7ac\ub294 \ub2f9\uc2dc \uadf8\uc758 \uc5f0\uad6c\uac00 \uace7\ubc14\ub85c \ud559\uacc4\uc758 \uc911\uc2ec\uc5d0 \uc11c\uc9c0\ub294 \ubabb\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc624\ub298\uc758 \uc911\uc694\uc131\uc744 \uc548\ub2e4\uace0 \ubc1c\ud45c \ub2f9\uc2dc \ubaa8\ub450\uac00 \uac19\uc740 \uc758\ubbf8\ub97c \uc54c\uc544\ubcf4\uc558\uc744 \uac83\uc73c\ub85c \uc0dd\uac01\ud558\uba74 \uc548 \ub41c\ub2e4. \ub2f9\uc2dc\uc5d0\ub294 \uc720\uc804\uc744 \ubd80\ubaa8\uc758 \uc131\uc9c8\uc774 \uc11e\uc774\ub294 \uacfc\uc815\uc73c\ub85c \uc124\uba85\ud558\ub294 \uc0dd\uac01\ub3c4 \uc788\uc5c8\ub2e4. \ud0a4\ucc98\ub7fc \uc5f0\uc18d\uc801\uc73c\ub85c \ub2ec\ub77c\uc9c0\ub294 \ud2b9\uc9d5\uc744 \ubcf4\uba74 \uadf8\ub807\uac8c \ub290\ub07c\uae30 \uc27d\ub2e4. \uba58\ub378\uc774 \uace0\ub978 \uad6c\ubd84 \uac00\ub2a5\ud55c \ud2b9\uc9d5\uacfc \uacc4\ud1b5\uc758 \uc2e4\ud5d8\uc774 \ub2e4\ub978 \uc5f0\uad6c\uc790\uc758 \uad00\uc2ec\uacfc \uc5b4\ub5bb\uac8c \ub9cc\ub098\ub294\uc9c0\ub3c4 \ubb38\uc81c\uc600\ub2e4. \uc624\ub298\uc740 \uc720\uc804\uc790\uc640 \ub300\ub9bd\uc720\uc804\uc790, \uc5fc\uc0c9\uccb4\ub77c\ub294 \uc5b8\uc5b4\ub85c \uc774 \uc2e4\ud5d8\uc744 \uc124\uba85\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uba58\ub378\uc774 \uc9c0\uae08\uc758 DNA \uc9c0\uc2dd\uc744 \uc774\ubbf8 \uc54c\uace0 \uc644\ub450\ucf69\uc744 \uae30\ub978 \uac83\uc740 \uc544\ub2c8\ub2e4. \uad00\ucc30\ud55c \uaddc\uce59\uacfc \ub098\uc911\uc5d0 \ubc1c\uc804\ud55c \ubb3c\uc9c8\uc801 \uc124\uba85\uc744 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ub610 \ubaa8\ub4e0 \uc0dd\ubb3c\uc758 \ubaa8\ub4e0 \ud2b9\uc9d5\uc774 \uc644\ub450\ucf69 \uaf43 \uc0c9\ucc98\ub7fc \ub2e8\uc21c\ud558\uac8c \ub098\ud0c0\ub098\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5ec\ub7ec \uc720\uc804\uc790\uc640 \ud658\uacbd\uc774 \ud568\uaed8 \uc791\uc6a9\ud558\ub294 \uacbd\uc6b0\ub3c4 \uc788\ub2e4. \uba58\ub378\uc758 \uc758\ubbf8\ub294 \ubaa8\ub4e0 \uc720\uc804\uc744 \ud55c \uacf5\uc2dd\uc73c\ub85c \ub05d\ub0b8 \ub370\ubcf4\ub2e4, \uc5b4\ub5a4 \uc870\uac74\uc744 \uad6c\ubd84\ud558\uba74 \ubc18\ubcf5\ub418\ub294 \uc591\uc0c1\uc774 \ubcf4\uc774\ub294\uc9c0 \ubcf4\uc5ec \uc900 \ub370 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc218\ub3c4\uc6d0 \uc815\uc6d0\uc5d0\uc11c \uc644\ub450\ucf69\uc744 \uc0b4\ud53c\ub294 \uc0c1\uc0c1 \uc18d \uc5f0\uad6c \uc7a5\uba74\uc774\ub2e4. \uba58\ub378\uc758 \uc2e4\uc81c \ucd08\uc0c1\uc774\ub098 \uc6d0\ub798 \uc2e4\ud5d8 \uad6c\ud68d, \uc138\ub300\ubcc4 \uc815\ud655\ud55c \uac1c\uccb4 \uc218\ub97c \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc624\ub798 \uae30\ub974\uace0 \ube44\uad50\ud558\ub294 \uc791\uc5c5\uc758 \ubd84\uc704\uae30\ub97c \ud45c\ud604\ud588\ub2e4. \ud770 \uaf43\uc774 \ub2e4\uc2dc \ud540 \uc77c\uc740 \ud55c \ubc88\uc758 \uc2e0\uae30\ud568\uc73c\ub85c \ub05d\ub0a0 \uc218\ub3c4 \uc788\uc5c8\ub2e4. \uba58\ub378\uc740 \ubd80\ubaa8\ub97c \uad6c\ubd84\ud558\uace0 \ub2e4\uc74c \uc138\ub300\ub97c \uae30\ub974\uba70 \uc218\ub97c \uc138\uc5c8\ub2e4. \uadf8 \uacfc\uc815\uc744 \ub530\ub77c\uac00\uba74 \uc720\uc804\uc758 \uc5ed\uc0ac\ub294 \uc815\ub2f5\uc774 \uc801\ud78c \uad50\uacfc\uc11c\ubcf4\ub2e4, \ubcf4\uc774\uc9c0 \uc54a\ub294 \uac83\uc774 \uc0ac\ub77c\uc9c4 \uac83\uc778\uc9c0 \ubb3b\ub294 \uafb8\uc900\ud55c \uc9c8\ubb38\uc758 \uc5ed\uc0ac\ub85c \ubcf4\uc778\ub2e4."}, {"id": "mendeleev-empty-spaces-and-elements", "title": "\uba58\ub378\ub808\uc608\ud504 \u2014 \ud45c\ub97c \uc644\uc131\ud558\ub824\uace0 \ube48\uce78\uc744 \ub0a8\uae30\ub2e4", "summary": "\uc6d0\uc18c\uc758 \uc131\uc9c8\uc744 \ube44\uad50\ud55c \ubc30\uc5f4\uc774 \uac08\ub968\uacfc \uac8c\ub974\ub9c8\ub284\uc758 \uc608\uce21\uc73c\ub85c \uc774\uc5b4\uc9c4 \uacfc\uc815\uacfc \ud604\ub300 \uc8fc\uae30\uc728\ud45c\uc640\uc758 \ucc28\uc774\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uacfc\ud559\uc790\uc758 \ubc1c\uacac", "categories": ["science"], "url": "stories/mendeleev-empty-spaces-and-elements/index.html", "image": "../media/mendeleev-empty-spaces-and-elements.png", "alt": "\ube48\uc790\ub9ac\uac00 \uc788\ub294 \uce74\ub4dc \ubc30\uc5f4\uacfc \uc5ec\ub7ec \ubb3c\uc9c8 \ud45c\ubcf8\uc744 \ub193\uace0 \uc0b4\ud53c\ub294 \uc5f0\uad6c\uc790\uc758 \uc190\uc744 \uadf8\ub9b0 \uc0bd\ud654", "text": "\uba58\ub378\ub808\uc608\ud504 \u2014 \ud45c\ub97c \uc644\uc131\ud558\ub824\uace0 \ube48\uce78\uc744 \ub0a8\uae30\ub2e4 1869\ub144\uc758 \uc6d0\uc18c \ubc30\uc5f4\uacfc \uc544\uc9c1 \ubc1c\uacac\ub418\uc9c0 \uc54a\uc740 \ubb3c\uc9c8\uc758 \uc790\ub9ac \uc6d0\uc18c\uc758 \uc131\uc9c8\uc744 \ube44\uad50\ud55c \ubc30\uc5f4\uc774 \uac08\ub968\uacfc \uac8c\ub974\ub9c8\ub284\uc758 \uc608\uce21\uc73c\ub85c \uc774\uc5b4\uc9c4 \uacfc\uc815\uacfc \ud604\ub300 \uc8fc\uae30\uc728\ud45c\uc640\uc758 \ucc28\uc774\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uacfc\ud559\uc790\uc758 \ubc1c\uacac \uacfc\ud559\uacfc \ubc1c\uacac \ud45c\uc5d0 \ube48\uce78\uc774 \ub0a8\uc73c\uba74 \ubcf4\ud1b5\uc740 \uc544\uc9c1 \uc815\ub9ac\ub97c \ub05d\ub0b4\uc9c0 \ubabb\ud588\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4. \uadf8\ub7f0\ub370 \ube48\uce78\uc774 \uc624\ud788\ub824 \uc0c8\ub85c\uc6b4 \ubb3c\uc9c8\uc758 \uc874\uc7ac\ub97c \uc608\uace0\ud55c\ub2e4\uba74 \uc5b4\ub5a8\uae4c. \uba58\ub378\ub808\uc608\ud504\uc758 \uc6d0\uc18c \ubc30\uc5f4\uc5d0\uc11c \ud765\ubbf8\ub85c\uc6b4 \ubd80\ubd84\uc740 \ucc44\uc6cc\uc9c4 \uc790\ub9ac\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc544\uc9c1 \uc544\ubb34\ub3c4 \ubd84\ub9ac\ud574 \ud655\uc778\ud558\uc9c0 \ubabb\ud55c \uc6d0\uc18c\uac00 \uc5b4\ub290 \uc790\ub9ac\uc5d0 \ub4e4\uc5b4\uac08\uc9c0, \uadf8 \ubb3c\uc9c8\uc740 \uc5b4\ub5a4 \uc131\uc9c8\uc744 \ubcf4\uc77c\uc9c0 \uc608\uc0c1\ud558\ub294 \uc77c. \uc775\uc219\ud55c \uad50\uc2e4\uc758 \uc8fc\uae30\uc728\ud45c \ub4a4\uc5d0\ub294 \ub208\uc55e\uc758 \uc790\ub8cc\ub97c \uc815\ub9ac\ud558\ub2e4\uac00 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uac83\uc744 \ubb3b\uac8c \ub41c \uc774\uc57c\uae30\uac00 \uc788\ub2e4. \ud654\ud559\uc790\ub4e4\uc740 \uad11\uc11d\uc744 \uc5f0\uad6c\ud558\uace0 \ubb3c\uc9c8\uc744 \ubd84\ub9ac\ud558\uba74\uc11c \uc5ec\ub7ec \uc6d0\uc18c\ub97c \uc54c\uc544\ub0c8\ub2e4. \uc6d0\uc18c\uc758 \uc774\ub984\uc744 \ud558\ub098\uc529 \uc678\uc6b0\ub294 \uac83\uacfc \uc6d0\uc18c \uc0ac\uc774\uc758 \uad00\uacc4\ub97c \ucc3e\ub294 \uac83\uc740 \ub2e4\ub978 \uc77c\uc774\uc5c8\ub2e4. \ube44\uc2b7\ud55c \uc131\uc9c8\uc774 \ubc18\ubcf5\ud574\uc11c \ub098\ud0c0\ub09c\ub2e4\uba74 \ubaa9\ub85d \uc774\uc0c1\uc758 \uc9c8\uc11c\uac00 \uc788\uc744 \uc218 \uc788\uc5c8\ub2e4. \ub9ac\ud2ac\uacfc \ub098\ud2b8\ub968, \uce7c\ub968\ucc98\ub7fc \uc131\uc9c8\uc774 \ub2ee\uc740 \uc6d0\uc18c\ub4e4\uc774 \uc788\uc5c8\ub2e4. \ubc18\uba74 \ub2e4\ub978 \ubb34\ub9ac\uc640\ub294 \ubc18\uc751\ud558\ub294 \ubc29\uc2dd\uc5d0\uc11c \ucc28\uc774\uac00 \ub0ac\ub2e4. \ubaa8\ub4e0 \uc6d0\uc18c\ub97c \uc81c\uac01\uac01\uc758 \ubb3c\uc9c8\ub85c\ub9cc \ubcf4\uae30\ubcf4\ub2e4 \ube44\uc2b7\ud55c \uac83\ub07c\ub9ac \ube44\uad50\ud558\uba74 \uc0c8\ub85c\uc6b4 \uc9c8\ubb38\uc774 \uc0dd\uae34\ub2e4. 1869\ub144 \ub7ec\uc2dc\uc544\uc758 \ub4dc\ubbf8\ud2b8\ub9ac \uba58\ub378\ub808\uc608\ud504\ub294 \uc6d0\uc18c\ub4e4\uc744 \ubc30\uc5f4\ud55c \ud45c\ub97c \ubc1c\ud45c\ud588\ub2e4. \ub2f9\uc2dc \uc6d0\uc18c\ub97c \ube44\uad50\ud558\ub294 \uc911\uc694\ud55c \uae30\uc900\uc740 \uc6d0\uc790\ub7c9\uc774\uc5c8\ub2e4. \uc6d0\uc790\uc758 \uc0c1\ub300\uc801\uc778 \ubb34\uac8c\ub97c \ub530\ub77c \ub193\uc73c\uba74\uc11c \ud654\ud559\uc801 \uc131\uc9c8\uc774 \uc5b4\ub5bb\uac8c \ubc18\ubcf5\ub418\ub294\uc9c0 \uc0b4\ud540 \uac83\uc774\ub2e4. \uc21c\uc11c\ub300\ub85c \uc801\uae30\ub9cc \ud558\uba74 \ub05d\ub098\ub294 \uc791\uc5c5\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc5b4\ub5a4 \uc6d0\uc18c\ub97c \uac19\uc740 \ubb34\ub9ac\uc5d0 \ub193\uc544\uc57c \uc790\uc5f0\uc2a4\ub7ec\uc6b4\uc9c0 \ud310\ub2e8\ud574\uc57c \ud588\ub2e4. \uc22b\uc790\uc758 \uc904\uacfc \uc131\uc9c8\uc758 \ub2ee\uc74c\uc774 \uc11c\ub85c \ub9de\ub294\uc9c0 \ubb3b\ub294 \uc77c\uc774\uc5c8\ub2e4. \ud45c\ub294 \uc774\ubbf8 \uc544\ub294 \uc0ac\uc2e4\uc744 \ub193\uace0 \uc2dc\ud5d8\ud558\ub294 \ub3c4\uad6c\uc600\ub2e4. \ub3c5\uc77c\uc758 \ub85c\ud0c0\uc5b4 \ub9c8\uc774\uc5b4\ub3c4 \uc6d0\uc18c\uc758 \uc131\uc9c8\uacfc \ubc30\uc5f4 \uc0ac\uc774\uc758 \uc8fc\uae30\uc801\uc778 \uad00\uacc4\ub97c \ub3c5\ub9bd\uc801\uc73c\ub85c \uc5f0\uad6c\ud574 \ud45c\ub97c \ubc1c\ud45c\ud588\ub2e4. 19\uc138\uae30 \ud654\ud559\uc790\ub4e4\uc740 \uc313\uc5ec \uac00\ub294 \uc9c0\uc2dd\uc744 \uc11c\ub85c \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uc815\ub9ac\ud558\ub824 \ud588\ub2e4. \uba58\ub378\ub808\uc608\ud504\uac00 \uc544\ubb34\ub7f0 \uc120\ud589 \uc791\uc5c5 \uc5c6\uc774 \uc9c8\uc11c\ub97c \ubc1c\uacac\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\uc758 \uc911\uc694\ud55c \ud2b9\uc9d5\uc740 \ud45c\uc758 \uc790\ub9ac\ub97c \uc544\uc9c1 \ubc1c\uacac\ub418\uc9c0 \uc54a\uc740 \uc6d0\uc18c\uc758 \uc131\uc9c8\uc744 \uc608\uc0c1\ud558\ub294 \ub370 \uc0ac\uc6a9\ud588\ub2e4\ub294 \uc810\uc774\ub2e4. \uc815\ub9ac\ub294 \ub4a4\ub3cc\uc544\ubcf4\ub294 \uc77c\uc5d0 \uadf8\uce58\uc9c0 \uc54a\uc558\ub2e4. \uc9c0\uae08\uc758 \uc9c8\uc11c\uac00 \ub9de\ub294\ub2e4\uba74 \uc55e\uc73c\ub85c \ubb34\uc5c7\uc744 \ubc1c\uacac\ud574\uc57c \ud560\uc9c0 \ubb3c\uc744 \uc218 \uc788\uc5c8\ub2e4. \uc131\uc9c8\uc774 \ubc18\ubcf5\ub418\ub294 \ud750\ub984\uc744 \ub530\ub97c \ub54c \uc5b4\ub5a4 \uc790\ub9ac\ub294 \ube44\uc5b4 \uc788\ub294 \ud3b8\uc774 \ub354 \uc798 \ub9de\uc558\ub2e4. \uadf8 \uce78\uc744 \uc5b5\uc9c0\ub85c \uc774\ubbf8 \uc544\ub294 \uc6d0\uc18c\ub85c \ucc44\uc6b0\uc9c0 \uc54a\ub294 \uc120\ud0dd\uc774 \ud544\uc694\ud588\ub2e4. \uc544\uc9c1 \ubaa8\ub974\ub294 \uac83\uc774 \uc874\uc7ac\ud560 \uc218 \uc788\ub2e4\ub294 \ud310\ub2e8\uc774\uc5c8\ub2e4. \ubb3c\ub860 \ube48\uce78\uc744 \ub0a8\uacbc\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc0c8\ub85c\uc6b4 \uc6d0\uc18c\uac00 \uc0dd\uae30\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5b4\ub514\uc5d0 \ubb34\uc5c7\uc774 \uc788\uc744\uc9c0 \ub9d0\ud558\uace0 \ub2e4\ub978 \uc5f0\uad6c\uc790\uac00 \uc2e4\uc81c \ubb3c\uc9c8\uc744 \ucc3e\uc544 \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uc608\uce21\uc774 \uc758\ubbf8\ub97c \uac00\uc9c0\ub824\uba74 \ud2c0\ub838\ub294\uc9c0\ub3c4 \ud655\uc778\ud560 \uc218 \uc788\uc5b4\uc57c \ud588\ub2e4. 1875\ub144 \uac08\ub968, 1886\ub144 \uac8c\ub974\ub9c8\ub284\uc774 \ubc1c\uacac\ub418\uc5c8\ub2e4. \uc774 \uc6d0\uc18c\ub4e4\uc740 \uba58\ub378\ub808\uc608\ud504\uac00 \uc608\uc0c1\ud588\ub358 \uc790\ub9ac\uc640 \uc131\uc9c8\uc744 \uac80\ud1a0\ud560 \uc911\uc694\ud55c \uadfc\uac70\uac00 \ub418\uc5c8\ub2e4. \ud45c\uc758 \uc9c8\uc11c\ub294 \uc774\ubbf8 \uc54c\ub824\uc9c4 \uac83\uc744 \ubcf4\uae30 \uc88b\uac8c \ubb36\ub294 \uc694\ub839\ub9cc\uc740 \uc544\ub2c8\ub77c\ub294 \uc9c0\uc9c0\ub97c \uc5bb\uc5c8\ub2e4. \ubc1c\uacac\uc740 \ube48\uce78\uc744 \uc0c9\uce60\ud558\ub294 \uc77c\ucc98\ub7fc \uac04\ub2e8\ud558\uc9c0 \uc54a\uc558\ub2e4. \uc0c8 \ubb3c\uc9c8\uc758 \uc131\uc9c8\uc744 \uce21\uc815\ud558\uace0 \uae30\uc874 \uc608\uc0c1\uacfc \ube44\uad50\ud558\ub294 \uc5f0\uad6c\uac00 \ud544\uc694\ud588\ub2e4. \uc6d0\uc18c\ub97c \ucc3e\uc740 \uc0ac\ub78c\ub4e4\uc758 \uc2e4\ud5d8\uacfc \uc815\ub9ac\ud55c \uc0ac\ub78c\uc758 \uc608\uce21\uc774 \ub9cc\ub0a0 \ub54c \ud45c\uc758 \ud798\ub3c4 \ub354 \ubd84\uba85\ud574\uc84c\ub2e4. \ud604\ub300\uc758 \uc8fc\uae30\uc728\ud45c\ub294 \uc6d0\uc790\ub7c9\uc774 \uc544\ub2c8\ub77c \uc6d0\uc790\ubc88\ud638\ub97c \uae30\uc900\uc73c\ub85c \ubc30\uc5f4\ud55c\ub2e4. \uc6d0\uc790\ubc88\ud638\ub294 \uc6d0\uc790\ud575 \uc548\uc758 \uc591\uc131\uc790 \uc218\uc640 \uc5f0\uacb0\ub418\ub294 \uac12\uc774\ub2e4. \uc6d0\uc790\uc758 \uad6c\uc870\uc5d0 \uad00\ud55c \uc9c0\uc2dd\uc774 \ubc1c\uc804\ud558\uba74\uc11c \ubc30\uc5f4\uc744 \uc124\uba85\ud558\ub294 \uae30\uc900\ub3c4 \ub2ec\ub77c\uc84c\ub2e4. \ub530\ub77c\uc11c \uc624\ub298\ub0a0 \uad50\uc2e4\uc758 \ud45c\ub97c 1869\ub144\uc5d0 \uc644\uc131\ub41c \uadf8\ub9bc\ucc98\ub7fc \ubcf4\uba74 \uc548 \ub41c\ub2e4. \uae30\ubcf8\uc801\uc778 \ud1b5\ucc30\uc774 \uc911\uc694\ud588\ub2e4\uace0 \ud574\uc11c \uc774\ud6c4\uc758 \uc218\uc815\uacfc \ubc1c\uacac\uc774 \uc791\uc544\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ub798 \uc4f0\uc774\ub294 \uc9c0\uc2dd\uc740 \ucc98\uc74c \ubaa8\uc2b5 \uadf8\ub300\ub85c \uba48\ucd94\uc5b4 \uc788\ub294 \uacbd\uc6b0\ubcf4\ub2e4 \ub2e4\ub4ec\uc5b4\uc9c0\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4. \uc8fc\uae30\uc728\ud45c\ub97c \uc554\uae30\ud560 \ub54c\ub294 \ube48\uce78\uc774 \ubd88\ud3b8\ud55c \uac83\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \ud558\uc9c0\ub9cc \uc5f0\uad6c\uc758 \uc5ed\uc0ac\uc5d0\uc11c \ube48\uc790\ub9ac\ub294 \uc9c8\ubb38\uc744 \ub9cc\ub4dc\ub294 \uc7a5\uce58\uc600\ub2e4. \uc5ec\uae30\uc5d0\ub294 \uc65c \uc5c6\uc744\uae4c, \uc788\ub2e4\uba74 \uc5b4\ub5a4 \uc131\uc9c8\uc77c\uae4c \ud558\uace0 \uc790\ub8cc\uc758 \ubc14\uae65\uc744 \ubc14\ub77c\ubcf4\uac8c \ud588\ub2e4. \uc774\uac83\uc740 \uc544\ubb34 \uadfc\uac70 \uc5c6\uc774 \uc0c1\uc0c1\uc73c\ub85c \ucc44\uc6b0\ub294 \uac83\uacfc \ub2e4\ub974\ub2e4. \uc8fc\ubcc0\uc758 \uc6d0\uc18c\uc640 \ubc18\ubcf5\ub418\ub294 \uad00\uacc4\uac00 \uc608\uc0c1\uc758 \ubc94\uc704\ub97c \uc81c\ud55c\ud588\ub2e4. \uc88b\uc740 \ud45c\ub294 \ubb34\uc5c7\uc774 \uc54c\ub824\uc838 \uc788\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\uba74\uc11c \ubb34\uc5c7\uc744 \uc544\uc9c1 \ud655\uc778\ud558\uc9c0 \ubabb\ud588\ub294\uc9c0\ub3c4 \ub4dc\ub7ec\ub0b8\ub2e4. \ubb3c\uac74\uc744 \uc0c9\uae54\uc774\ub098 \ud06c\uae30\ub85c \ubd84\ub958\ud558\ub294 \ubc29\ubc95\uc740 \ub9ce\ub2e4. \uc6d0\uc18c\uc5d0\uc11c\ub3c4 \ub2e8\uc9c0 \ubcf4\uc774\ub294 \ubaa8\uc2b5\uc774 \ub2ee\uc558\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \uac19\uc740 \uc790\ub9ac\ub97c \uc904 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub978 \ubb3c\uc9c8\uacfc \ubc18\uc751\ud558\ub294 \ubc29\uc2dd\uacfc \ub9cc\ub4e4\uc5b4\uc9c0\ub294 \ud654\ud569\ubb3c\uc744 \ud568\uaed8 \ube44\uad50\ud560 \ud544\uc694\uac00 \uc788\uc5c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uac89\uc73c\ub85c \ubc18\uc9dd\uc778\ub2e4\uace0 \ubaa8\ub4e0 \uae08\uc18d\uc774 \uac19\uc740 \uc815\ub3c4\ub85c \ubc18\uc751\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc18\ub300\ub85c \uc11c\ub85c \ub5a8\uc5b4\uc838 \ubc1c\uacac\ub41c \ubb3c\uc9c8\ub3c4 \ube44\uc2b7\ud55c \ud654\ud559\uc801 \ud589\ub3d9\uc744 \ubcf4\uc77c \uc218 \uc788\ub2e4. \uc815\ub9ac\uc758 \uae30\uc900\uc744 \uc798 \uace0\ub974\ub294 \uc77c\uc774 \uc790\ub8cc\uc758 \uc591\ub9cc\ud07c \uc911\uc694\ud588\ub358 \uc148\uc774\ub2e4. \uadf8\ub798\uc11c \uc6d0\uc18c\ud45c\ub97c \ub9cc\ub4e0\ub2e4\ub294 \uac83\uc740 \uc774\ub984\ud45c\ub97c \uc815\ub3c8\ud558\ub294 \uc791\uc5c5\uc744 \ub118\uc5b4\uc120\ub2e4. \uc5b4\ub5a4 \uc131\uc9c8\uc744 \uc911\uc694\ud558\uac8c \ubcfc\uc9c0 \uc815\ud558\uace0 \uadf8 \uae30\uc900\uc774 \ub2e4\ub978 \uc6d0\uc18c\uc5d0\ub3c4 \ud1b5\ud558\ub294\uc9c0 \ud655\uc778\ud55c\ub2e4. \uc0c8\ub85c\uc6b4 \uc6d0\uc18c\uc758 \uc608\uce21\uc740 \uadf8\ub7f0 \ube44\uad50\uac00 \ubc14\uae65\uc73c\ub85c \ubed7\uc5b4 \ub098\uac04 \uacb0\uacfc\uc600\ub2e4. \uba58\ub378\ub808\uc608\ud504\uc758 \uafc8\uc5d0 \uc644\uc131\ub41c \ud45c\uac00 \ub098\ud0c0\ub0ac\ub2e4\ub294 \uc2dd\uc758 \uc77c\ud654\ubcf4\ub2e4 \uc624\ub798 \ub0a8\ub294 \uac83\uc740 \ube44\uad50\uc640 \uc608\uce21\uc758 \ubc29\uc2dd\uc774\ub2e4. \uc790\ub8cc\uac00 \ubaa8\ub450 \ubaa8\uc77c \ub54c\uae4c\uc9c0 \uae30\ub2e4\ub9ac\uc9c0 \uc54a\uc73c\uba74\uc11c\ub3c4 \ubaa8\ub974\ub294 \uc790\ub9ac\ub97c \uc544\ub294 \uac83\ucc98\ub7fc \ucc44\uc6b0\uc9c0 \uc54a\uc558\ub2e4. \ud45c\uc758 \ube48\uce78\uc740 \uc9c0\uc2dd\uc758 \ubd80\uc871\uc744 \uc228\uae30\ub294 \uc7a5\uc2dd\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ub098\uc911\uc758 \ubc1c\uacac\uc774 \ub4e4\uc5b4\uc640 \ub9de\ub294\uc9c0 \ud2c0\ub9ac\ub294\uc9c0 \uc0b4\ud544 \uc790\ub9ac\uc600\ub2e4. \ube7d\ube7d\ud558\uac8c \ucc44\uc6b4 \ud398\uc774\uc9c0\ubcf4\ub2e4 \uc870\uc2ec\uc2a4\ub7fd\uac8c \ube44\uc6cc \ub454 \uce78\uc774 \ub354 \ub9ce\uc740 \uac83\uc744 \ub9d0\ud574 \uc904 \ub54c\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc774 \uc774\uc57c\uae30\uc758 \ub9e4\ub825\uc774\ub2e4."}, {"id": "nightingale-air-and-observation", "title": "\ub098\uc774\ud305\uac8c\uc77c \u2014 \ub4f1\ubd88\ubcf4\ub2e4 \uba3c\uc800 \ubcd1\uc2e4\uc758 \uacf5\uae30\ub97c \ubcf4\ub2e4", "summary": "Notes on Nursing\uc5d0\uc11c \ubcd1\uc2e4\uc758 \ud658\uacbd\uacfc \ud658\uc790\uc758 \uc791\uc740 \ubcc0\ud654\ub97c \uc0b4\ud53c\ub294 \ud0dc\ub3c4\ub97c \uc5ed\uc0ac\uc801 \ub9e5\ub77d\uc73c\ub85c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uacfc\ud559\uc790\uc758 \ubc1c\uacac", "categories": ["science"], "url": "stories/nightingale-air-and-observation/index.html", "image": "../media/nightingale-air-and-observation.png", "alt": "\ub0ae\ube5b\uc774 \ub4dc\ub294 19\uc138\uae30\ud48d \ubcd1\uc2e4\uc5d0\uc11c \uc131\uc778 \ud658\uc790 \uacc1\uc758 \ub3cc\ubcf4\ub294 \uc0ac\ub78c\uc774 \uc218\ucca9\uc744 \ub4e4\uace0 \uc11c \uc788\ub294 \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ub098\uc774\ud305\uac8c\uc77c \u2014 \ub4f1\ubd88\ubcf4\ub2e4 \uba3c\uc800 \ubcd1\uc2e4\uc758 \uacf5\uae30\ub97c \ubcf4\ub2e4 \uac04\ud638\uc5d0 \uad00\ud55c \uc624\ub798\ub41c \ucc45\uc774 \uc8fc\ubaa9\ud55c \ube5b\uacfc \uc18c\ub9ac, \uad00\ucc30 Notes on Nursing\uc5d0\uc11c \ubcd1\uc2e4\uc758 \ud658\uacbd\uacfc \ud658\uc790\uc758 \uc791\uc740 \ubcc0\ud654\ub97c \uc0b4\ud53c\ub294 \ud0dc\ub3c4\ub97c \uc5ed\uc0ac\uc801 \ub9e5\ub77d\uc73c\ub85c \uc77d\uc2b5\ub2c8\ub2e4. \uacfc\ud559\uc790\uc758 \ubc1c\uacac \uacfc\ud559\uacfc \ubc1c\uacac \ub098\uc774\ud305\uac8c\uc77c\uc744 \ub5a0\uc62c\ub9ac\uba74 \uc5b4\ub450\uc6b4 \ubcd1\uc2e4\uc744 \ub3cc\uba70 \ub4f1\ubd88\uc744 \ub4e0 \uc0ac\ub78c\uc774 \uc0dd\uac01\ub09c\ub2e4. \uadf8\ub7f0\ub370 \uadf8\ub140\uc758 \u300e\uac04\ud638\uc5d0 \uad00\ud55c \uae30\ub85d\u300f\uc744 \ud3bc\uce58\uba74 \uccab\uba38\ub9ac\uc5d0\uc11c \ub9cc\ub098\ub294 \uac83\uc740 \ub4f1\ubd88\ubcf4\ub2e4 \uacf5\uae30\ub2e4. \ud658\uc790\uac00 \uc228 \uc26c\ub294 \ubc29\uc758 \uc0c1\ud0dc, \ucd94\uc704\uc640 \uc18c\uc74c, \ube5b\uacfc \uc2dd\uc0ac\ucc98\ub7fc \ub108\ubb34 \uc775\uc219\ud574\uc11c \uc9c0\ub098\uce58\uae30 \uc26c\uc6b4 \uac83\ub4e4\uc774\ub2e4. 19\uc138\uae30\uc5d0 \uc4f0\uc778 \uc774 \ucc45\uc740 \uc624\ub298\uc758 \uc758\ub8cc \uc9c0\uce68\uacfc \uac19\uc9c0 \uc54a\ub2e4. \uc61b \uce58\ub8cc\ubc95\uc744 \ub530\ub77c \ud558\uae30\ubcf4\ub2e4 \uc800\uc790\uac00 \ubb34\uc5c7\uc744 \uad00\ucc30\uc758 \ub300\uc0c1\uc73c\ub85c \uc0bc\uc558\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc601\uc6c5\uc801\uc778 \ud55c \uc7a5\uba74 \ub4a4\uc5d0 \ud3c9\ubc94\ud55c \ud658\uacbd\uc744 \ub04a\uc784\uc5c6\uc774 \uc0b4\ud53c\ub294 \uc77c\uc774 \uc788\uc5c8\ub2e4\ub294 \uc810\uc774 \ud765\ubbf8\ub86d\ub2e4. \ucc45\uc758 \ubd80\uc81c\ub294 \uac04\ud638\uac00 \ubb34\uc5c7\uc774\uba70 \ubb34\uc5c7\uc774 \uc544\ub2cc\uc9c0\ub97c \ubb3b\ub294\ub2e4. \ub098\uc774\ud305\uac8c\uc77c\uc740 \uc57d\uc744 \uc8fc\uac70\ub098 \uc758\ub8cc \ucc98\uce58\ub97c \ud558\ub294 \uc77c\ub9cc\uc73c\ub85c \ud658\uc790\ub97c \ub3cc\ubcf4\ub294 \uacbd\ud5d8 \uc804\uccb4\uac00 \uc124\uba85\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4\uace0 \ubcf8\ub2e4. \uc0ac\ub78c\uc774 \uba38\ubb34\ub294 \uacf5\uac04\uacfc \ud558\ub8e8\uc758 \ud750\ub984\ub3c4 \ubab8\uc758 \uc0c1\ud0dc\uc640 \uc5f0\uacb0\ub418\uc5b4 \uc788\ub2e4\uace0 \uc0dd\uac01\ud588\ub2e4. \uc774 \uad00\uc810\uc5d0\uc11c\ub294 \ubc29\uc774 \uc870\uc6a9\ud55c\uc9c0, \uc2dd\uc0ac\ub97c \uc2e4\uc81c\ub85c \uba39\uc5c8\ub294\uc9c0, \ubc24\uc5d0 \uc81c\ub300\ub85c \uc26c\uc5c8\ub294\uc9c0 \uac19\uc740 \uc9c8\ubb38\uc774 \uc911\uc694\ud574\uc9c4\ub2e4. \uba40\ub9ac\uc11c \ubcf4\uae30\uc5d0\ub294 \uc791\uc740 \uc77c\uc774\uc9c0\ub9cc \ud658\uc790\uc5d0\uac8c\ub294 \ud558\ub8e8\uc758 \ub300\ubd80\ubd84\uc744 \ucc28\uc9c0\ud560 \uc218 \uc788\ub2e4. \uac04\ud638\ub294 \uc88b\uc740 \ub9c8\uc74c\uc744 \uac00\uc84c\ub2e4\ub294 \ub9d0\ubfd0 \uc544\ub2c8\ub77c \uad6c\uccb4\uc801\uc73c\ub85c \ubb34\uc5c7\uc744 \uc0b4\ud3c8\ub294\uc9c0\ub85c \uc124\uba85\ub418\uc5b4\uc57c \ud588\ub2e4. \ud658\uae30\uc640 \ubcf4\uc628\uc744 \ub2e4\ub8e8\ub294 \uc7a5\uc5d0\uc11c \ub098\uc774\ud305\uac8c\uc77c\uc740 \uacf5\uae30\uac00 \uc5b4\ub514\uc5d0\uc11c \ub4e4\uc5b4\uc624\ub294\uc9c0 \ubb3b\ub294\ub2e4. \ub2e4\ub978 \ubc29\uc774\ub098 \ubcf5\ub3c4\uc758 \uacf5\uae30\ub97c \ub4e4\uc774\ub294 \uac83\uacfc \ubc14\uae65\uc5d0\uc11c \ub4e4\uc5b4\uc624\ub294 \uacf5\uae30\ub97c \uad6c\ubd84\ud55c\ub2e4. \uc5f4\uc5c8\ub2e4\ub294 \ub3d9\uc791 \ud558\ub098\ubcf4\ub2e4 \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \uacf5\uae30\uac00 \ud658\uc790\uc5d0\uac8c \uc624\ub294\uc9c0\uac00 \uad00\uc2ec\uc758 \ub300\uc0c1\uc774\uc5c8\ub2e4. \uc624\ub298\uc758 \ubcd1\uc2e4\uc5d0\uc11c \ucc3d\ubb38\uc744 \uc5b4\ub5bb\uac8c \ub2e4\ub8f0\uc9c0\ub294 \uc2dc\uc124\uacfc \ud658\uc790 \uc0c1\ud0dc, \uac10\uc5fc \uad00\ub9ac \uae30\uc900\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c4\ub2e4. \uc774 \ucc45\uc758 \uc138\ubd80 \ubc29\ubc95\uc744 \ud604\uc7ac\uc758 \ucc98\ubc29\uc73c\ub85c \uc62e\uae30\ub824\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c \ubcfc \uc810\uc740 \uc870\uce58\ub97c \ud588\ub2e4\ub294 \ud615\uc2dd\ubcf4\ub2e4 \uadf8 \uacb0\uacfc\uac00 \uc2e4\uc81c\ub85c \ubb34\uc5c7\uc778\uc9c0 \ud655\uc778\ud558\ub824\ub294 \ud0dc\ub3c4\ub2e4. \uc800\uc790\ub294 \ud658\uae30\ub97c \ub9d0\ud558\uba74\uc11c \ud658\uc790\ub97c \ucc28\uac11\uac8c \ud574\uc11c\ub294 \uc548 \ub41c\ub2e4\ub294 \uc870\uac74\ub3c4 \ud568\uaed8 \uac15\uc870\ud55c\ub2e4. \ud55c \uac00\uc9c0 \uc88b\uc740 \ubaa9\uc801\uc744 \uc704\ud574 \ub2e4\ub978 \ud544\uc694\ub97c \uc78a\uc5b4\ubc84\ub9ac\ub294 \uc0c1\ud669\uc744 \uacbd\uacc4\ud55c \uc148\uc774\ub2e4. \ubc29\uc758 \uc0c1\ud0dc\ub97c \ubc14\uafb8\ub294 \uc77c\uacfc \uadf8 \uc548\uc758 \uc0ac\ub78c\uc774 \uc5b4\ub5bb\uac8c \ub290\ub07c\uace0 \uc788\ub294\uc9c0 \ubcf4\ub294 \uc77c\uc740 \ud568\uaed8 \uac00\uc57c \ud588\ub2e4. \uc774 \ub300\ubaa9\uc744 \uc77d\uc73c\uba74 \ub3cc\ubd04\uc774 \ub2e8\uc21c\ud55c \ub3d9\uc791 \ubaa9\ub85d\uc774 \uc544\ub2c8\ub77c\ub294 \uc810\uc774 \ubcf4\uc778\ub2e4. \ud55c \ubc88 \ucc3d\ubb38\uc744 \ub9cc\uc84c\ub2e4\uace0 \uc77c\uc774 \ub05d\ub098\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc2dc\uac04\uacfc \uc870\uac74\uc5d0 \ub530\ub77c \ub2e4\uc2dc \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \ud658\uacbd\uc744 \uc815\ub3c8\ud558\ub294 \uc0ac\ub78c\uc758 \ud3b8\ub9ac\ud568\ubcf4\ub2e4 \uadf8 \ud658\uacbd \uc548\uc5d0 \uba38\ubb34\ub294 \uc0ac\ub78c\uc758 \uacbd\ud5d8\uc744 \uc911\uc2ec\uc5d0 \ub193\ub294 \uc9c8\ubb38\uc774\ub2e4. \ucc45\uc740 \uc18c\uc74c\uc5d0\ub3c4 \ub9ce\uc740 \uc8fc\uc758\ub97c \uae30\uc6b8\uc778\ub2e4. \uc26c\uace0 \uc788\ub294 \uc0ac\ub78c \uac00\uae4c\uc774\uc5d0\uc11c \uac11\uc790\uae30 \ub098\ub294 \uc18c\ub9ac\ub098 \uacc4\uc18d\ub420\uc9c0 \uc54c \uc218 \uc5c6\ub294 \uc6c0\uc9c1\uc784\uc740 \ubd80\ub2f4\uc774 \ub420 \uc218 \uc788\ub2e4\ub294 \uad00\ucc30\uc774\ub2e4. \ub3cc\ubcf4\ub294 \ucabd\uc5d0\uac8c \uc0ac\uc18c\ud55c \uc18c\ub9ac\uac00 \ud658\uc790\uc5d0\uac8c\ub3c4 \uc0ac\uc18c\ud558\ub9ac\ub77c\ub294 \ubcf4\uc7a5\uc740 \uc5c6\ub2e4. \uc774\uac83\uc740 \ubaa8\ub4e0 \uc18c\ub9ac\ub97c \uc5c6\uc560\uc57c \ud55c\ub2e4\ub294 \uc624\ub298\uc758 \uaddc\uce59\uc744 \uc81c\uc2dc\ud558\ub294 \ub9d0\uc774 \uc544\ub2c8\ub2e4. \uac19\uc740 \uacf5\uac04\uc744 \uc0ac\uc6a9\ud558\ub294 \ub450 \uc0ac\ub78c\uc774 \uc11c\ub85c \ub2e4\ub978 \uacbd\ud5d8\uc744 \ud55c\ub2e4\ub294 \uc810\uc5d0 \uc8fc\ubaa9\ud558\ub294 \uac83\uc774\ub2e4. \ub204\uc6cc\uc11c \uc624\ub7ab\ub3d9\uc548 \uc26c\ub294 \uc0ac\ub78c\uc758 \uc790\ub9ac\uc5d0\uc11c \ubc29\uc744 \uc0dd\uac01\ud558\uba74 \ud3c9\uc18c\uc5d0 \ub4e3\uc9c0 \uc54a\ub358 \uac83\ub4e4\uc774 \ub2e4\ub978 \ubb34\uac8c\ub85c \ub4e4\uc5b4\uc62c \uc218 \uc788\ub2e4. \uc2dd\uc0ac \uc5ed\uc2dc \uc900\ube44\ud588\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc2e4\uc81c\ub85c \uba39\uc740 \uc591\uc744 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ucc45\uc740 \ud658\uc790\uc758 \uc2dd\uc0ac\uc640 \uc74c\uc2dd\uc774 \uc81c\uacf5\ub418\ub294 \ub54c, \uad00\ucc30\uc758 \ud544\uc694\ub97c \ub2e4\ub8ec\ub2e4. \uadf8\ub987\uc744 \uac16\ub2e4 \ub193\uc558\uc73c\ub2c8 \ud544\uc694\ud55c \uc77c\uc744 \ub9c8\ucce4\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \ub208\uc55e\uc5d0\uc11c \ub193\uce58\ub294 \uac83\uc774 \uc0dd\uae34\ub2e4. \uad6c\uccb4\uc801\uc778 \uc74c\uc2dd\uc774\ub098 \ubd84\ub7c9\uc5d0 \uad00\ud55c \uc61b \uc124\uba85\uc744 \ud604\uc7ac\uc758 \uc601\uc591 \ucc98\ubc29\uc73c\ub85c \ubc1b\uc544\ub4e4\uc774\uc9c0\ub294 \ub9d0\uc790. \uc774 \uae00\uc5d0\uc11c \uc8fc\ubaa9\ud558\ub294 \uac83\uc740 \uc81c\uacf5\ud55c \uc11c\ube44\uc2a4\uc640 \uadf8\uac83\uc744 \ubc1b\uc740 \uc0ac\ub78c\uc758 \uc0c1\ud0dc \uc0ac\uc774\uc5d0 \ucc28\uc774\uac00 \uc788\uc744 \uc218 \uc788\ub2e4\ub294 \uc810\uc774\ub2e4. \ud55c \uc77c\uc774 \ubb34\uc5c7\uc778\uc9c0 \uae30\ub85d\ud558\ub294 \uac83\uacfc \uadf8 \uc77c\uc774 \uc5b4\ub5a4 \uacb0\uacfc\ub97c \ub0c8\ub294\uc9c0 \uc0b4\ud53c\ub294 \uc77c\uc740 \uc774\uc5b4\uc838\uc57c \ud55c\ub2e4. \ud6c4\ubc18\uc758 \uad00\ucc30\uc5d0 \uad00\ud55c \uc124\uba85\uc740 \ud658\uc790\uc758 \uc0c1\ud0dc\ub97c \ub9c9\uc5f0\ud55c \uc778\uc0c1\uc73c\ub85c \ubcf4\uace0\ud558\uc9c0 \ub9d0 \uac83\uc744 \uc694\uad6c\ud55c\ub2e4. \uc9c1\uc811 \uc0b4\ud540 \ub0b4\uc6a9\uacfc \ucd94\uce21\uc744 \uad6c\ubd84\ud558\uace0, \ud544\uc694\ud55c \uc0ac\uc2e4\uc744 \uc54c\uc544\ubcfc \uc218 \uc788\uac8c \uc804\ub2ec\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4\ub294 \uc0dd\uac01\uc774\ub2e4. \uce5c\uc808\ud55c \uc124\uba85\ub3c4 \uc815\ud655\ud558\uc9c0 \uc54a\uc73c\uba74 \ucda9\ubd84\ud55c \ub3c4\uc6c0\uc774 \ub418\uae30 \uc5b4\ub835\ub2e4. \uc88b\uc544 \ubcf4\uc600\ub2e4\ub294 \ub9d0\uacfc \uc7a0\uc744 \uc5bc\ub9c8\ub098 \uc7a4\ub294\uc9c0 \ud655\uc778\ud55c \ub9d0\uc740 \ub2e4\ub974\ub2e4. \uae30\ub85d\uc774 \uc0ac\ub78c\uc758 \uc0c1\ud0dc\ub97c \ubaa8\ub450 \uc218\uce58\ub85c \ubc14\uafc0 \uc218\ub294 \uc5c6\uc9c0\ub9cc, \uc790\uae30 \ub290\ub08c\ub9cc\uc73c\ub85c \ud0c0\uc778\uc758 \uacbd\ud5d8\uc744 \ub300\uc2e0\ud558\uc9c0 \uc54a\uac8c \ub3c4\uc6b8 \uc218\ub294 \uc788\ub2e4. \uad00\ucc30\uc740 \ubb34\uc2ec\ud558\uac8c \ubc14\ub77c\ubcf4\ub294 \uc77c\uc774 \uc544\ub2c8\ub77c \ubb34\uc5c7\uc744 \uc544\uc9c1 \ubaa8\ub974\ub294\uc9c0\ub3c4 \uc54c\uc544\ucc28\ub9ac\ub294 \uc77c\uc774\ub2e4. \uc774 \ucc45\uc5d0\ub294 \ub2f9\uc2dc\uc758 \uc9c8\ubcd1 \uc774\ud574\uc640 \uc5ec\uc131\uc758 \uc5ed\ud560\uc5d0 \uad00\ud55c \uc804\uc81c\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \ubaa8\ub4e0 \ub0b4\uc6a9\uc744 \ud604\ub300 \uc758\ud559\uc774\ub098 \uc624\ub298\uc758 \ud3c9\ub4f1\ud55c \ub3cc\ubd04 \uad00\uacc4\uc640 \uac19\uac8c \uc77d\uc744 \uc218 \uc5c6\ub2e4. \uc624\ub798\ub41c \uc778\ubb3c\uc758 \uae30\uc5ec\ub97c \uc778\uc815\ud558\ub294 \uc77c\uacfc \uadf8 \uc2dc\ub300\uc758 \uc124\uba85\uc744 \ubb34\uc870\uac74 \ub530\ub974\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uc624\ud788\ub824 \ubb34\uc5c7\uc774 \ub0a8\uace0 \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0 \ube44\uad50\ud560 \ub54c \uc5ed\uc0ac \uc77d\uae30\uc758 \uc758\ubbf8\uac00 \uc0dd\uae34\ub2e4. \ubcd1\uc6d0 \ud658\uacbd\uacfc \uad50\uc721, \uc758\ub8cc \uae30\uc220\uc774 \ubcc0\ud574\ub3c4 \ud658\uc790\uac00 \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \uacbd\ud5d8\uc744 \ud558\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud55c\ub2e4\ub294 \uc9c8\ubb38\uc740 \uacc4\uc18d \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc704\ub300\ud55c \uc0ac\ub78c\uc774\ub77c\ub294 \uc774\ub984\uc744 \uc678\uc6b0\ub294 \uac83\ubcf4\ub2e4 \uad6c\uccb4\uc801\uc778 \uc791\uc5c5\uc744 \uc77d\ub294 \ud3b8\uc774 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \uc601\uc6c5\uc758 \uc804\uae30\ub294 \ud070 \uc0ac\uac74\uc744 \uc911\uc2ec\uc73c\ub85c \uae30\uc5b5\ub418\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uc774 \ucc45\uc758 \ub9ce\uc740 \ubd80\ubd84\uc740 \ubc29 \uc548\uc758 \ud3c9\ubc94\ud55c \uc2dc\uac04\uc5d0 \uba38\ubb38\ub2e4. \uacf5\uae30\uac00 \ub2f5\ub2f5\ud55c\uc9c0, \uc870\uc6a9\ud788 \uc274 \uc218 \uc788\ub294\uc9c0, \uc804\ud574 \ub4e4\uc740 \uc774\uc57c\uae30\uac00 \uc9c1\uc811 \ud655\uc778\ud55c \uc0ac\uc2e4\uc778\uc9c0 \ubb3b\ub294\ub2e4. \uc720\uba85\ud55c \uc0c1\uc9d5 \ub4a4\uc5d0 \ubc18\ubcf5\ub418\ub294 \uc8fc\uc758\uac00 \uc788\uc5c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 19\uc138\uae30 \ub3cc\ubd04\uc758 \ubd84\uc704\uae30\ub97c \uc0c8\ub85c \uc0c1\uc0c1\ud55c AI \uc0bd\ud654\ub2e4. \ub098\uc774\ud305\uac8c\uc77c\uc758 \uc2e4\uc81c \uc5bc\uad74\uc774\ub098 \ud2b9\uc815 \ubcd1\uc6d0\uc744 \ubcf5\uc6d0\ud558\uc9c0 \uc54a\uc558\uc73c\uba70 \uc624\ub298\uc758 \ubcd1\uc2e4 \uad00\ub9ac\ubc95\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \ucc3d\uac00\uc758 \uc791\uc740 \uc7a5\uba74\uc744 \ud1b5\ud574 \ub3cc\ubcf4\ub294 \uc0ac\ub78c\uc774 \ubb34\uc5c7\uc744 \uc0b4\ud53c\uace0 \uc788\ub294\uc9c0 \ub5a0\uc62c\ub824 \ubcf4\uc544\ub3c4 \uc88b\ub2e4."}, {"id": "pasteur-swan-neck-air-and-dust", "title": "\ud30c\uc2a4\ud1f4\ub974 \u2014 \uacf5\uae30\ub294 \ub4e4\uc5b4\uc624\ub294\ub370 \uc65c \uc369\uc9c0 \uc54a\uc558\uc744\uae4c", "summary": "\ub808\ub514\uc640 \uc2a4\ud314\ub780\ucc28\ub2c8\uc758 \uc2e4\ud5d8\uc5d0\uc11c \ud30c\uc2a4\ud1f4\ub974\uc758 \ubc31\uc870\ubaa9 \ud50c\ub77c\uc2a4\ud06c\uae4c\uc9c0 \uacf5\uae30\uc640 \ubbf8\uc0dd\ubb3c \uc720\uc785\uc744 \uad6c\ubd84\ud55c \ub17c\uc7c1\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uacfc\ud559\uc790\uc758 \ubc1c\uacac", "categories": ["science"], "url": "stories/pasteur-swan-neck-air-and-dust/index.html", "image": "../media/pasteur-swan-neck-air-and-dust.png", "alt": "\uad6c\ubd80\ub7ec\uc9c4 \ubaa9\uc758 \ud50c\ub77c\uc2a4\ud06c\ub97c \ub193\uc740 19\uc138\uae30 \uc2e4\ud5d8\uc2e4 \ubd84\uc704\uae30\uc758 \uc0bd\ud654", "text": "\ud30c\uc2a4\ud1f4\ub974 \u2014 \uacf5\uae30\ub294 \ub4e4\uc5b4\uc624\ub294\ub370 \uc65c \uc369\uc9c0 \uc54a\uc558\uc744\uae4c \uad6c\ubd80\ub7ec\uc9c4 \ud50c\ub77c\uc2a4\ud06c\uac00 \uc624\ub798\ub41c \uc0dd\uba85 \ub17c\uc7c1\uc5d0 \ub358\uc9c4 \uc9c8\ubb38 \ub808\ub514\uc640 \uc2a4\ud314\ub780\ucc28\ub2c8\uc758 \uc2e4\ud5d8\uc5d0\uc11c \ud30c\uc2a4\ud1f4\ub974\uc758 \ubc31\uc870\ubaa9 \ud50c\ub77c\uc2a4\ud06c\uae4c\uc9c0 \uacf5\uae30\uc640 \ubbf8\uc0dd\ubb3c \uc720\uc785\uc744 \uad6c\ubd84\ud55c \ub17c\uc7c1\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uacfc\ud559\uc790\uc758 \ubc1c\uacac \uacfc\ud559\uacfc \ubc1c\uacac \uad6d\ubb3c\uc774 \ub4e0 \uc720\ub9ac\ubcd1\uc5d0 \uacf5\uae30\ub294 \ub4dc\ub098\ub4dc\ub294\ub370 \uad6d\ubb3c\uc740 \uc27d\uac8c \ubcc0\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub69c\uaed1\uc73c\ub85c \uaf49 \ub9c9\uc740 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \ubcd1\uc758 \ubaa9\uc774 \uae38\uac8c \uad6c\ubd80\ub7ec\uc838 \uc788\uc744 \ubfd0\uc774\ub2e4. \ud30c\uc2a4\ud1f4\ub974\uc758 \uc720\uba85\ud55c \uc2e4\ud5d8\uc740 \ucee4\ub2e4\ub780 \uae30\uacc4\ubcf4\ub2e4 \uc774 \ub0af\uc120 \uc720\ub9ac\ubcd1\uc758 \ubaa8\uc591\uc73c\ub85c \uae30\uc5b5\ub41c\ub2e4. \uc65c \ubcd1\ubaa9\uc744 \ud718\uac8c \ub9cc\ub4e4\uc5c8\uc744\uae4c. \uc774\uac83\uc744 \uc54c\ub824\uba74 \uba3c\uc800 \uc61b \uc5f0\uad6c\uc790\ub4e4\uc774 \ubb34\uc5c7\uc744 \ub2e4\ud22c\uace0 \uc788\uc5c8\ub294\uc9c0 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \ub17c\uc7c1\uc758 \uc911\uc2ec\uc5d0\ub294 \uc369\ub294 \ubb3c\uc9c8\uc5d0\uc11c \uc791\uc740 \uc0dd\uba85\uc774 \uc800\uc808\ub85c \uc0dd\uaca8\ub098\ub294\uac00\ub77c\ub294 \uc9c8\ubb38\uc774 \uc788\uc5c8\ub2e4. \uace0\uae30\ub97c \ub450\uba74 \uad6c\ub354\uae30\uac00 \ubcf4\uc774\uace0 \uad6d\ubb3c\uc744 \uc624\ub798 \ub450\uba74 \uc791\uc740 \uc0dd\ubb3c\uc774 \ub298\uc5b4\ub09c\ub2e4. \uadf8 \uc2dc\uc791\uc744 \uc9c1\uc811 \ubcf4\uc9c0 \ubabb\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ubb3c\uc9c8 \uc790\uccb4\uc5d0\uc11c \uc0dd\uba85\uc774 \uc0dd\uaca8\ub09c \uac83\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\uc5c8\ub2e4. \uc774\ub7f0 \uc0dd\uac01\uc744 \uc790\uc5f0\ubc1c\uc0dd\uc124\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \uc624\ub298\uc758 \ub2f5\uc744 \uc548\ub2e4\uace0 \uc61b\uc0ac\ub78c \ubaa8\ub450\ub97c \uad00\ucc30\ud558\uc9c0 \uc54a\ub294 \uc0ac\ub78c\uc73c\ub85c \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uadf8\ub4e4 \uc5ed\uc2dc \ub208\uc55e\uc5d0 \ubb34\uc5c7\uc774 \ub098\ud0c0\ub098\ub294\uc9c0 \ubcf4\uc558\ub2e4. \ubb38\uc81c\ub294 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc54c\uc774\ub098 \ubbf8\uc0dd\ubb3c\uc774 \ub4e4\uc5b4\uc628 \uac00\ub2a5\uc131\uc744 \uc5b4\ub5bb\uac8c \uad6c\ubcc4\ud560 \uac83\uc778\uac00\uc600\ub2e4. 1668\ub144 \ud504\ub780\uccb4\uc2a4\ucf54 \ub808\ub514\ub294 \uace0\uae30\ub97c \ub2f4\uc740 \uc6a9\uae30\uc758 \ub36e\uac1c\ub97c \ub2ec\ub9ac\ud588\ub2e4. \ud30c\ub9ac\uac00 \uace0\uae30\uc5d0 \ub2ff\uc744 \uc218 \uc788\ub294\uc9c0 \ube44\uad50\ud55c \uac83\uc774\ub2e4. \uacf5\uae30\ub294 \ub4e4\uc5b4\uac00\ub418 \ud30c\ub9ac\ub294 \ub9c9\ub294 \ub36e\uac1c\ub97c \ub450\uba74 \uad6c\ub354\uae30\uc758 \ubc1c\uc0dd\uc744 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ud574\uc11d\ud560 \uc218 \uc788\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \ud070 \ud30c\ub9ac\uc640 \uad6c\ub354\uae30\uc758 \uad00\uacc4\ub97c \ubc1d\ud78c\ub2e4\uace0 \uc791\uc740 \ubbf8\uc0dd\ubb3c\uc758 \ubb38\uc81c\uae4c\uc9c0 \ubc14\ub85c \ub05d\ub098\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ubcf4\uc774\ub294 \uc0dd\ubb3c\ubcf4\ub2e4 \ud6e8\uc52c \uc791\uc740 \ub300\uc0c1\uc744 \ub450\uace0\ub3c4 \uac19\uc740 \uc124\uba85\uc774 \uac00\ub2a5\ud55c\uc9c0, \uc5f0\uad6c\ub294 \ub2e4\ub978 \uaddc\ubaa8\uc5d0\uc11c \uc774\uc5b4\uc838\uc57c \ud588\ub2e4. 18\uc138\uae30 \uc874 \ub2c8\ub364\uc740 \uad6d\ubb3c\uc744 \uc7a0\uc2dc \ub053\uc778 \ub4a4\uc5d0\ub3c4 \ubbf8\uc0dd\ubb3c\uc774 \ub098\ud0c0\ub098\ub294 \uac83\uc744 \ubcf4\uc558\ub2e4. \ub77c\ucc28\ub85c \uc2a4\ud314\ub780\ucc28\ub2c8\ub294 \uac00\uc5f4\uacfc \ubc00\ubd09\uc758 \uc870\uac74\uc744 \ub2ec\ub9ac\ud574 \ub2e4\ub978 \uacb0\uacfc\ub97c \uc5bb\uc5c8\ub2e4. \ubbf8\uc0dd\ubb3c\uc774 \ub0a8\uac70\ub098 \ub2e4\uc2dc \ub4e4\uc5b4\uc624\ub294 \uac00\ub2a5\uc131\uc774 \ub17c\uc7c1\uc5d0 \ub4e4\uc5b4\uc654\ub2e4. \uadf8\ub7ec\uc790 \ubc00\ubd09\ud55c \ubcd1\uc5d0\ub294 \uc0dd\uba85\uc774 \uc0dd\uae30\ub294 \ub370 \ud544\uc694\ud55c \uacf5\uae30\ub098 \ud798\uc774 \ub4e4\uc5b4\uac00\uc9c0 \ubabb\ud55c\ub2e4\ub294 \ubc18\ub860\uc774 \ub098\uc654\ub2e4. \ubcd1\uc744 \ub2eb\uace0 \uc5f4\uc5b4 \ubcf4\ub294 \uac83\ub9cc\uc73c\ub85c\ub294 \uc11c\ub85c \ub2e4\ub978 \uc124\uba85\uc744 \ub5bc\uc5b4 \ub193\uae30 \uc5b4\ub824\uc6e0\ub2e4. \uc591\ucabd\uc774 \ubc1b\uc544\ub4e4\uc77c \uc218 \uc788\ub294 \ube44\uad50\uac00 \ud544\uc694\ud588\ub2e4. \ubc1c\ud6a8\uc640 \ubd80\ud328\ub97c \uc5f0\uad6c\ud558\ub358 \ub8e8\uc774 \ud30c\uc2a4\ud1f4\ub974\ub294 \uacf5\uae30\uc640 \ud568\uaed8 \ubb34\uc5c7\uc774 \ub4e4\uc5b4\uc624\ub294\uc9c0 \uc8fc\ubaa9\ud588\ub2e4. \uacf5\uae30 \uc911\uc758 \uba3c\uc9c0 \ub4f1\uc5d0 \ubbf8\uc0dd\ubb3c\uc774 \uc788\uc744 \uc218 \uc788\ub2e4\uba74 \uacf5\uae30\ub97c \ud5c8\uc6a9\ud558\uba74\uc11c \uadf8\ub7f0 \ubb3c\uc9c8\uc758 \uc720\uc785\uc740 \ub9c9\uc544 \ubcfc \uc218 \uc788\uc5c8\ub2e4. \uc5ec\uae30\uc11c \uad6c\ubd80\ub7ec\uc9c4 \ubcd1\ubaa9\uc774 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud588\ub2e4. \ubc14\uae65 \uacf5\uae30\ub294 \uc548\ucabd\uacfc \ud1b5\ud558\uc9c0\ub9cc \uba3c\uc9c0\ub97c \uc2e4\uc740 \uc785\uc790\ub4e4\uc774 \uad6d\ubb3c\uae4c\uc9c0 \uace7\ubc14\ub85c \ub2ff\uae30 \uc5b4\ub835\uac8c \ub9cc\ub4e0 \uac83\uc774\ub2e4. \ubc00\ubd09\ud55c \ubcd1\uacfc \uc5f4\ub9b0 \ubcd1\uc744 \ube44\uad50\ud558\ub358 \ub17c\uc7c1\uc5d0 \ub2e4\ub978 \uc120\ud0dd\uc9c0\uac00 \uc0dd\uacbc\ub2e4. \uac00\uc5f4\ud55c \uad6d\ubb3c\uc744 \ubc31\uc870\ubaa9 \ud50c\ub77c\uc2a4\ud06c\uc5d0 \ub450\uba74 \ubaa9\uc774 \uc628\uc804\ud55c \ub3d9\uc548 \uc624\uc5fc\ub418\uc9c0 \uc54a\uc740 \uc0c1\ud0dc\ub97c \uc720\uc9c0\ud560 \uc218 \uc788\uc5c8\ub2e4. \ubc18\ub300\ub85c \ubaa9\uc744 \ubd80\ub7ec\ub728\ub824 \ubc14\uae65\uc758 \ubbf8\uc0dd\ubb3c\uc774 \ub4e4\uc5b4\uc62c \uc870\uac74\uc744 \ub9cc\ub4e4\uba74 \uad6d\ubb3c\uc5d0\uc11c \ubbf8\uc0dd\ubb3c\uc774 \uc790\ub790\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uc720\ub9ac\ubcd1\uc774 \uc2e0\ube44\ud55c \ud798\uc73c\ub85c \uc0dd\uba85\uc744 \ub9c9\uc558\ub2e4\ub294 \uc124\uba85\uc774 \uc544\ub2c8\ub2e4. \uacf5\uae30\uac00 \uc788\ub2e4\ub294 \uc870\uac74\uc740 \uc720\uc9c0\ud558\uba74\uc11c \ubbf8\uc0dd\ubb3c\uc774 \ub4e4\uc5b4\uc62c \uacbd\ub85c\ub97c \ub2ec\ub9ac\ud55c \uc810\uc774\ub2e4. \uc11c\ub85c \uc11e\uc5ec \uc788\ub358 \uc870\uac74\uc744 \ubd84\ub9ac\ud558\ub2c8 \uacb0\uacfc\ub97c \uc124\uba85\ud560 \uae38\ub3c4 \uc881\ud600\uc84c\ub2e4. \uc774 \uc2e4\ud5d8\ub4e4\uc740 \uc790\uc5f0\ubc1c\uc0dd\uc124\uc744 \ubc18\ubc15\ud558\ub294 \uc911\uc694\ud55c \uadfc\uac70\uac00 \ub418\uc5c8\ub2e4. \ud30c\uc2a4\ud1f4\ub974\ub294 1862\ub144 \uad00\ub828 \uc0c1\uc744 \ubc1b\uc558\uace0 \uc774\ud6c4\uc758 \uac15\uc5f0\uc5d0\uc11c\ub3c4 \uc790\uc2e0\uc758 \uc2e4\ud5d8\uc744 \uc124\uba85\ud588\ub2e4. \uc791\uc740 \uc720\ub9ac\ubcd1\uc740 \ud55c \ubc88 \ubcf4\uc5ec \uc8fc\uace0 \ub05d\ub098\ub294 \ubb18\uae30\uac00 \uc544\ub2c8\ub77c \ub17c\uc7c1 \uc18d\uc758 \uc99d\uac70\uc600\ub2e4. \uc55e\uc120 \uc5f0\uad6c\uc790\ub4e4\uc758 \uc2e4\ud5d8\uacfc \ubc18\ub860\uc774 \uc5c6\uc5c8\ub2e4\uba74 \uc65c \uacf5\uae30\ub97c \ud1b5\ud558\uac8c \ud574\uc57c \ud558\ub294\uc9c0\ub3c4 \ub35c \ubd84\uba85\ud588\uc744 \uac83\uc774\ub2e4. \ubc1c\uacac\uc758 \uc5ed\uc0ac\ub294 \ub9c8\uc9c0\ub9c9 \ub2f5\uc744 \ub9d0\ud55c \uc0ac\ub78c \ud55c \uba85\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \ud2c0\ub9b0 \ud574\uc11d\uacfc \uae4c\ub2e4\ub85c\uc6b4 \ubc18\ubc15\ub3c4 \ub354 \ub098\uc740 \uc2e4\ud5d8\uc758 \uc870\uac74\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \ud30c\uc2a4\ud1f4\ub974\uac00 \uc0b4\ud540 \uac83\uc740 \uadf8 \uc2e4\ud5d8 \uc870\uac74\uc5d0\uc11c \uad6d\ubb3c\uc5d0 \ub098\ud0c0\ub098\ub294 \ubbf8\uc0dd\ubb3c\uc758 \uae30\uc6d0\uc774\uc5c8\ub2e4. \uc774\uac83\uc744 \uc9c0\uad6c\uc758 \ubaa8\ub4e0 \uc2dc\ub300\uc640 \ubaa8\ub4e0 \ud658\uacbd\uc5d0\uc11c \uc0dd\uba85\uc774 \uc5b4\ub5bb\uac8c \uc2dc\uc791\ub418\uc5c8\ub294\uc9c0\uc5d0 \ub300\ud55c \uc644\uc804\ud55c \ub2f5\uc73c\ub85c \ud655\ub300\ud558\uba74 \uc2e4\ud5d8\uc758 \ubc94\uc704\ub97c \ubc97\uc5b4\ub09c\ub2e4. \ub610 \uc774 \uc774\uc57c\uae30\ub294 \uc9d1\uc5d0\uc11c \uc74c\uc2dd\uc744 \uc624\ub798 \ub450\uc5b4\ub3c4 \ub41c\ub2e4\ub294 \ubcf4\uad00 \uc694\ub839\uc774 \uc544\ub2c8\ub2e4. \uc2e4\uc81c \uc2dd\ud488\uc758 \uc548\uc804\uc740 \uc5ec\ub7ec \uc870\uac74\uc5d0 \ub2ec\ub824 \uc788\ub2e4. \uc5ed\uc0ac \uc18d \uc2e4\ud5d8\uc744 \uc77d\ub294 \ubaa9\uc801\uc740 \ub530\ub77c \ud558\ub294 \uc808\ucc28\ubcf4\ub2e4 \uc5b4\ub5a4 \uc9c8\ubb38\uc744 \uc5b4\ub5bb\uac8c \uac80\ud1a0\ud588\ub294\uc9c0 \uc774\ud574\ud558\ub294 \ub370 \uc788\ub2e4. \uc774 \uc2e4\ud5d8\uc5d0\uc11c \uad6d\ubb3c\uc774 \ud750\ub824\uc9c0\ub294 \ubaa8\uc2b5\uc740 \ubbf8\uc0dd\ubb3c\uc774 \uc790\ub790\ub294\uc9c0 \uc0b4\ud53c\ub294 \ub2e8\uc11c\uac00 \ub41c\ub2e4. \uadf8\ub7ec\ub098 \uacb0\uacfc\ub97c \uc77d\uc73c\ub824\uba74 \ucc98\uc74c \uc0c1\ud0dc\uc640 \uac00\uc5f4, \uc624\uc5fc\ub420 \uacbd\ub85c \uac19\uc740 \uc870\uac74\uc744 \ud568\uaed8 \uc54c\uc544\uc57c \ud55c\ub2e4. \uc720\ub9ac\ubcd1\uc774 \ub9d1\uc544 \ubcf4\uc778\ub2e4\ub294 \uc778\uc0c1\ub9cc \ub5bc\uc5b4 \ub193\uc544\uc11c\ub294 \uac19\uc740 \uacb0\ub860\uc744 \ub0bc \uc218 \uc5c6\ub2e4. \ub530\ub77c\uc11c \ucc45 \uc18d \uc0bd\ud654\ub294 \uc2e4\ud5d8\uc758 \uacb0\uacfc\ub97c \ub300\uc2e0 \uc785\uc99d\ud558\ub294 \uc790\ub8cc\uac00 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uc7a5\uce58\ub97c \uc0dd\uac01\ud588\ub294\uc9c0 \uc774\ud574\ub97c \ub3d5\ub294 \uadf8\ub9bc\uc774\ub2e4. \uc2e4\uc81c \ub17c\uc99d\uc740 \uc870\uac74\uc744 \ud1b5\uc81c\ud55c \uad00\ucc30\uacfc \uadf8 \uae30\ub85d\uc5d0 \uc788\ub2e4. \ubcf4\uae30 \uc88b\uc740 \uc7a5\uba74\uacfc \uadfc\uac70\uc758 \uc5ed\ud560\uc744 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \uc774 \ucc28\uc774\ub294 \uacfc\ud559\uc758 \uc5ed\uc0ac\ub97c \uc77d\uc744 \ub54c\ub3c4 \uc720\uc6a9\ud558\ub2e4. \uc720\uba85\ud55c \uc0ac\uc9c4\uc774\ub098 \ub3c4\uad6c\uac00 \uae30\uc5b5\uc758 \ucd9c\ubc1c\uc810\uc740 \ub420 \uc218 \uc788\uc9c0\ub9cc \uc65c \uc124\ub4dd\ub825\uc774 \uc788\uc5c8\ub294\uc9c0\ub294 \uadf8 \uc8fc\ubcc0\uc758 \uc9c8\ubb38\uacfc \ube44\uad50\ub97c \uc77d\uc5b4\uc57c \uc54c \uc218 \uc788\ub2e4. \ud50c\ub77c\uc2a4\ud06c\uc758 \uad74\uace1\uc5d0\ub294 \uadf8 \ube44\uad50\uc758 \uc0dd\uac01\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uacf5\uae30\ub97c \ub123\uc744 \uac83\uc778\uac00 \ub9c9\uc744 \uac83\uc778\uac00\ub77c\ub294 \uc9c8\ubb38\uc744 \uacf5\uae30\ub294 \ud1b5\ud558\uac8c \ub450\uace0 \ubb34\uc5c7\uc744 \ub9c9\uc744 \uac83\uc778\uac00\ub85c \ubc14\uafb8\uc5c8\ub2e4. \uc774 \uc791\uc740 \uc804\ud658 \ub355\ubd84\uc5d0 \uc774\uc804\uc758 \ubc18\ub860\uc744 \ub354 \uc9c1\uc811\uc801\uc73c\ub85c \uc0b4\ud544 \uc218 \uc788\uc5c8\ub2e4. \uc2e4\ud5d8 \ub3c4\uad6c\uc758 \ubaa8\uc591\uc774 \uc0dd\uac01\uc758 \ubaa8\uc591\ub3c4 \ubc14\uafbc \uc148\uc774\ub2e4. \ubc31\uc870\ubaa9 \ud50c\ub77c\uc2a4\ud06c\ub97c \ubcfc \ub54c \uadf8\uc800 \uacfc\ud559\uc790\uc758 \uba4b\uc9c4 \uc18c\ud488\uc73c\ub85c\ub9cc \ubcf4\uc9c0 \uc54a\uc544\ub3c4 \uc88b\ub2e4. \uad6c\ubd80\ub7ec\uc9c4 \uc720\ub9ac\uc5d0\ub294 \uae34 \ub17c\uc7c1\uc774 \ub2f4\uaca8 \uc788\ub2e4. \uc88b\uc740 \ub2f5\uc744 \uc5bb\uc73c\ub824\uba74 \ub54c\ub85c \ub354 \ubcf5\uc7a1\ud55c \ub9d0\ubcf4\ub2e4 \uc11c\ub85c \ub2e4\ub978 \uac00\ub2a5\uc131\uc744 \uac00\ub824 \uc8fc\ub294 \uac04\ub2e8\ud55c \uc7a5\uce58\uac00 \ud544\uc694\ud558\ub2e4."}, {"id": "penicillin-mold-to-medicine-team", "title": "\ud398\ub2c8\uc2e4\ub9b0 \u2014 \uacf0\ud321\uc774\ub97c \ubc1c\uacac\ud55c \ub0a0\uc5d0 \uc57d\uc774 \uc644\uc131\ub41c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4", "summary": "1928\ub144\uc758 \ubc30\uc591\uc811\uc2dc\uc640 \uc774\ud6c4\uc758 \uc815\uc81c\u00b7\uc2dc\ud5d8\u00b7\uc0dd\uc0b0\uc744 \ub530\ub77c \ubc1c\uacac\uacfc \uce58\ub8cc\uc81c \uc0ac\uc774\uc758 \uae34 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uacfc\ud559\uc790\uc758 \ubc1c\uacac", "categories": ["science"], "url": "stories/penicillin-mold-to-medicine-team/index.html", "image": "../media/penicillin-mold-to-medicine-team.png", "alt": "\uacf0\ud321\uc774 \uc8fc\ubcc0\uc758 \ub9d1\uc740 \uacf5\uac04\uc774 \ubcf4\uc774\ub294 \ubc30\uc591\uc811\uc2dc\uc640 \uc791\uc5c5 \ub178\ud2b8, \ud604\ubbf8\uacbd\uc758 \ud574\uc11d\uc801 \uc0bd\ud654", "text": "\ud398\ub2c8\uc2e4\ub9b0 \u2014 \uacf0\ud321\uc774\ub97c \ubc1c\uacac\ud55c \ub0a0\uc5d0 \uc57d\uc774 \uc644\uc131\ub41c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4 \ud50c\ub808\ubc0d\uc758 \uad00\ucc30\uc5d0\uc11c \ud50c\ub85c\ub9ac\uc640 \uccb4\uc778\uc758 \uc5f0\uad6c\uae4c\uc9c0 1928\ub144\uc758 \ubc30\uc591\uc811\uc2dc\uc640 \uc774\ud6c4\uc758 \uc815\uc81c\u00b7\uc2dc\ud5d8\u00b7\uc0dd\uc0b0\uc744 \ub530\ub77c \ubc1c\uacac\uacfc \uce58\ub8cc\uc81c \uc0ac\uc774\uc758 \uae34 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uacfc\ud559\uc790\uc758 \ubc1c\uacac \uacfc\ud559\uacfc \ubc1c\uacac \uc138\uade0\uc744 \uae30\ub974\ub358 \uc811\uc2dc\uc5d0 \uacf0\ud321\uc774\uac00 \uc790\ub790\ub2e4. \uc2e4\ud5d8\uc744 \ub9dd\uce5c \uc624\uc5fc\uc73c\ub85c \ubcf4\uace0 \ubc84\ub9b4 \uc218\ub3c4 \uc788\ub294 \uc7a5\uba74\uc774\ub2e4. \uadf8\ub7f0\ub370 \uc54c\ub809\uc0b0\ub354 \ud50c\ub808\ubc0d\uc740 \uadf8 \uc8fc\ubcc0\uc5d0\uc11c \uc138\uade0\uc758 \uc131\uc7a5\uc774 \uc5b5\uc81c\ub41c \ubaa8\uc2b5\uc744 \ub208\uc5ec\uaca8\ubcf4\uc558\ub2e4. \ubb38\uc81c\ucc98\ub7fc \ubcf4\uc774\ub294 \uac83\uc774 \uc0c8\ub85c\uc6b4 \uc9c8\ubb38\uc758 \uc2dc\uc791\uc774 \ub418\uc5c8\ub2e4. \uc774\ub807\uac8c \uc774\uc57c\uae30\ub97c \uc2dc\uc791\ud558\uba74 \uace7\ubc14\ub85c \uc704\ub300\ud55c \uc57d\uc758 \ud0c4\uc0dd\uc744 \ub9d0\ud558\uace0 \uc2f6\uc5b4\uc9c4\ub2e4. \ud558\uc9c0\ub9cc \uad00\ucc30\ud55c \ud604\uc0c1\uacfc \ud658\uc790\uc5d0\uac8c \uc4f8 \uc218 \uc788\ub294 \uce58\ub8cc\uc81c \uc0ac\uc774\uc5d0\ub294 \uae34 \uac70\ub9ac\uac00 \uc788\uc5c8\ub2e4. \ud398\ub2c8\uc2e4\ub9b0\uc758 \uc5ed\uc0ac\ub294 \uc6b0\uc5f0\ud55c \ubc1c\uacac\uc758 \uc720\uba85\ud55c \uc21c\uac04\ub9cc\ud07c\uc774\ub098 \uadf8 \ub4a4\uc5d0 \uc774\uc5b4\uc9c4 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc791\uc5c5\uc744 \ud568\uaed8 \ubcfc \ub54c \ub354 \ud765\ubbf8\ub85c\uc6cc\uc9c4\ub2e4. 1928\ub144 \ub7f0\ub358\uc758 \uc138\uc778\ud2b8\uba54\ub9ac \ubcd1\uc6d0\uc5d0\uc11c \uc5f0\uad6c\ud558\ub358 \ud50c\ub808\ubc0d\uc740 \uc624\ub798\ub41c \ud3ec\ub3c4\uc0c1\uad6c\uade0 \ubc30\uc591\uc811\uc2dc\ub97c \uc0b4\ud3c8\ub2e4. \uacf0\ud321\uc774\uac00 \uc790\ub780 \uacf3 \uc8fc\ubcc0\uc5d0\uc11c \uc138\uade0\uc758 \uc131\uc7a5\uc774 \uc5b5\uc81c\ub418\uc5b4 \uc788\uc5c8\ub2e4. \ubaa8\ub4e0 \uacf3\uc5d0 \uc138\uade0\uc774 \uac19\uc740 \ubaa8\uc2b5\uc73c\ub85c \uc790\ub77c\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ud2b9\uc815\ud55c \uc8fc\ubcc0\ub9cc \ub2ec\ub790\ub2e4\ub294 \uc810\uc774 \uad00\ucc30\uc758 \ud575\uc2ec\uc774\uc5c8\ub2e4. \ub208\uc5d0 \ub744\ub294 \uc5bc\ub8e9\uc744 \ubc1c\uacac\ud558\ub294 \uac83\uacfc \uadf8 \ucc28\uc774\ub97c \uc5f0\uad6c\ud560 \uac00\uce58\uac00 \uc788\ub2e4\uace0 \uc0dd\uac01\ud558\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uc2e4\ud5d8\uc758 \ubaa9\uc801\uacfc \uc5b4\uae0b\ub09c \uc7a5\uba74\ub3c4 \ube44\uad50\ud560 \ub300\uc0c1\uc744 \uc81c\uacf5\ud560 \uc218 \uc788\uc5c8\ub2e4. \ub2e4\ub9cc \uacf0\ud321\uc774\uac00 \uc788\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \uc5b8\uc81c\ub098 \uc911\uc694\ud55c \uc57d\uc758 \ub2e8\uc11c\uac00 \uc0dd\uae30\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uc870\uac74\uc5d0\uc11c \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0 \ud655\uc778\ud558\ub294 \uc791\uc5c5\uc774 \ud544\uc694\ud588\ub2e4. \uc2e4\ud5d8\uc5d0\uc11c\ub294 \uc6d0\ud558\uc9c0 \uc54a\ub294 \ubbf8\uc0dd\ubb3c\uc774 \ub4e4\uc5b4\uc624\uc9c0 \uc54a\uac8c \uad00\ub9ac\ud558\ub294 \uc77c\uc774 \uc911\uc694\ud558\ub2e4. \uadf8\ub798\uc11c \uc624\uc5fc\ub41c \uc811\uc2dc\ub294 \uc2e4\ud328\ub85c \ubd84\ub958\ub418\uae30 \uc27d\ub2e4. \ud50c\ub808\ubc0d\uc758 \uc0ac\ub840\uac00 \ud765\ubbf8\ub85c\uc6b4 \uac83\uc740 \uadf8 \uc2e4\ud328\uc758 \ud754\uc801 \uc548\uc5d0\uc11c \uc138\uade0\uacfc \uacf0\ud321\uc774 \uc0ac\uc774\uc758 \uad00\uacc4\ub97c \ubcf4\uc558\ub2e4\ub294 \uc810\uc774\ub2e4. \uc815\ud574\uc9c4 \uacb0\uacfc\uac00 \ub098\uc624\uc9c0 \uc54a\uc558\ub2e4\uace0 \ubaa8\ub4e0 \uc815\ubcf4\uac00 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc774\uac83\uc744 \uc2e4\ud5d8\uc2e4\uc744 \uc77c\ubd80\ub7ec \uc5b4\uc9c0\ub7fd\ud788\uba74 \uc88b\uc740 \uc77c\uc774 \uc0dd\uae34\ub2e4\ub294 \uad50\ud6c8\uc73c\ub85c \ubc14\uafb8\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc6b0\uc5f0\uc774 \uc788\uc5c8\ub2e4\ub294 \ub9d0\uc740 \uc5f0\uad6c\uc758 \uc900\ube44\uc640 \uad00\ucc30\uc744 \ub300\uccb4\ud558\uc9c0 \uc54a\ub294\ub2e4. \uac19\uc740 \uc7a5\uba74\uc744 \ub9cc\ub098\ub3c4 \ubb34\uc5c7\uc744 \ube44\uad50\ud560\uc9c0 \ubaa8\ub974\uba74 \uadf8\ub0e5 \uc9c0\ub098\uac08 \uc218 \uc788\ub2e4. \uc6b0\uc5f0\uacfc \uc219\ub828\uc740 \uc11c\ub85c \ubc18\ub300\ud3b8\uc5d0\ub9cc \ub193\uc774\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \ud50c\ub808\ubc0d\uacfc \ub3d9\ub8cc\ub4e4\uc740 \uacf0\ud321\uc774\uac00 \uc138\uade0\uc758 \uc131\uc7a5\uc744 \uc5b5\uc81c\ud558\ub294 \ud604\uc0c1\uc744 \ub354 \uc870\uc0ac\ud588\ub2e4. \ud398\ub2c8\uc2e4\ub9b0\uc774\ub77c\ub294 \uc774\ub984\uc740 \uc774 \uc5f0\uad6c\uc640 \uc5f0\uacb0\ub41c\ub2e4. \ud558\uc9c0\ub9cc \uc5b4\ub5a4 \ubb3c\uc9c8\uc774 \uc2e4\ud5d8\uc5d0\uc11c \ud6a8\uacfc\ub97c \ubcf4\uc778\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8\uac83\uc744 \uc77c\uc815\ud55c \ud488\uc9c8\ub85c \ub9c8\ub828\ud574 \uce58\ub8cc\uc5d0 \uc4f8 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub974\ub2e4. \uc57d\uc774 \ub418\ub824\uba74 \ud604\uc0c1\uc744 \uc54c\uc544\ubcf4\ub294 \ub2e8\uacc4 \ubc14\uae65\uc758 \ubb38\uc81c\ub3c4 \ud574\uacb0\ud574\uc57c \ud588\ub2e4. \uc5bc\ub9c8\ub098 \uc5bb\uc744 \uc218 \uc788\ub294\uc9c0, \uc81c\ub300\ub85c \ubd84\ub9ac\ud560 \uc218 \uc788\ub294\uc9c0, \ud6a8\uacfc\ub97c \ud655\uc778\ud560 \uc870\uac74\uc740 \ubb34\uc5c7\uc778\uc9c0\uac00 \uc911\uc694\ud574\uc9c4\ub2e4. \uc720\uba85\ud55c \ubc1c\uacac\uc790\uc758 \uc774\ub984\ub9cc\uc73c\ub85c \uc57d\uc758 \uc5ed\uc0ac\ub97c \uc124\uba85\ud558\uba74 \uc774\ub7f0 \uc9c8\ubb38\uc744 \ub9e1\uc740 \uc0ac\ub78c\ub4e4\uc758 \uc77c\uc774 \ub4a4\ub85c \uc0ac\ub77c\uc9c4\ub2e4. \uad00\ucc30\uc744 \uce58\ub8cc\ub85c \uc774\uc5b4 \uc8fc\ub294 \uc791\uc5c5\uc5d0\ub3c4 \ub3c5\uc790\uc801\uc778 \ud310\ub2e8\uacfc \uc2dc\uac04\uc774 \ud544\uc694\ud588\ub2e4. \ud558\uc6cc\ub4dc \ud50c\ub85c\ub9ac\uc640 \uc5d0\ub978\uc2a4\ud2b8 \uccb4\uc778\uc774 \uc774\ub048 \uc625\uc2a4\ud37c\ub4dc \uc5f0\uad6c\uc9c4\uc740 \ud398\ub2c8\uc2e4\ub9b0\uc744 \ubd84\ub9ac\ud558\uace0 \ud65c\uc6a9\ud558\ub294 \uc5f0\uad6c\ub97c \uc9c4\uc804\uc2dc\ucf30\ub2e4. 1940\ub144\uc5d0\ub294 \uc815\uc81c\ud55c \ubb3c\uc9c8\uc744 \uc774\uc6a9\ud55c \uc0dd\uc950 \uac10\uc5fc \uc2e4\ud5d8\uc758 \uc131\uacfc\uac00 \ubcf4\uace0\ub418\uc5c8\uace0 \uc0ac\ub78c\uc5d0\uac8c \uc0ac\uc6a9\ud558\ub294 \uc5f0\uad6c\ub3c4 \uc774\uc5b4\uc84c\ub2e4. \uc811\uc2dc\uc758 \ud604\uc0c1\uc774 \uce58\ub8cc\uc758 \uac00\ub2a5\uc131\uc73c\ub85c \uc774\ub3d9\ud55c \uc911\uc694\ud55c \uacfc\uc815\uc774\uc5c8\ub2e4. \ub3d9\ubb3c\uc5d0\uc11c \uacb0\uacfc\uac00 \ub098\uc654\ub2e4\uace0 \uace7\ubc14\ub85c \uc0ac\ub78c\uc758 \uce58\ub8cc\uac00 \ubaa8\ub450 \ubcf4\uc7a5\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc6a9\ub7c9\uacfc \uc548\uc804, \uc0c1\ud0dc\uc640 \uc0dd\uc0b0\uc758 \uc870\uac74\uc744 \ub354 \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uc774 \ub2e8\uacc4\ub97c \uc9e7\uac8c \uc9c0\ub098\uac00\ub294 \uc774\uc57c\uae30\ub294 \uc18d\ub3c4\uac10\uc774 \uc788\uc9c0\ub9cc \uc5f0\uad6c\uc758 \uc2e4\uc81c \uc5b4\ub824\uc6c0\uc744 \ub193\uce58\uac8c \ud55c\ub2e4. \uc88b\uc740 \uacb0\uacfc\ub97c \uc5bb\uc740 \ub4a4\uc5d0\ub3c4 \ud574\uc57c \ud560 \uc77c\uc774 \ub0a8\uc544 \uc788\uc5c8\ub2e4. \uce58\ub8cc\ud560 \uc218 \uc788\ub2e4\ub294 \uac00\ub2a5\uc131\uacfc \ub9ce\uc740 \ud658\uc790\uc5d0\uac8c \uacf5\uae09\ud560 \uc218 \uc788\ub2e4\ub294 \ub2a5\ub825 \uc5ed\uc2dc \uac19\uc9c0 \uc54a\ub2e4. \uc815\uc81c\uc640 \uc0dd\uc0b0\uc744 \ub113\ud788\ub294 \uc77c\uc740 \ubc1c\uacac\uc758 \ubc1c\ud45c \ub4a4\uc5d0 \uc774\uc5b4\uc838\uc57c \ud588\ub2e4. \ubb3c\uc9c8\uc744 \ud655\ubcf4\ud558\uace0 \ud488\uc9c8\uc744 \uad00\ub9ac\ud558\uba70 \ucda9\ubd84\ud55c \uc591\uc744 \ub9c8\ub828\ud558\ub294 \uacfc\uc815\uc774 \uc788\uc5b4\uc57c \uc0ac\ud68c\uc758 \uce58\ub8cc \ud658\uacbd\ub3c4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc2e4\ud5d8\uc2e4\uc758 \uc791\uc740 \uc811\uc2dc\uc640 \ub300\ub7c9 \uc0dd\uc0b0\uc758 \uc124\ube44\ub294 \uaddc\ubaa8\ub9cc \ub2e4\ub978 \ubcf5\uc81c\ud488\uc774 \uc544\ub2c8\ub2e4. \uc694\uad6c\ub418\ub294 \uc870\uac74\uacfc \uc791\uc5c5\uc758 \ubb38\uc81c\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \uc57d\uc758 \uc5ed\uc0ac\ub294 \uacfc\ud559\uc790\uc758 \uad00\ucc30\uc774\uba74\uc11c \uc81c\uc870\uc640 \uc870\uc9c1\uc758 \uc5ed\uc0ac\uc774\uae30\ub3c4 \ud558\ub2e4. \ubab8\uc744 \uc0b4\ub9ac\ub294 \ubb3c\uc9c8\uc774 \ub41c\ub2e4\ub294 \ub9d0 \uc548\uc5d0\ub294 \uadf8\uac83\uc744 \uc2e4\uc81c\ub85c \uc804\ub2ec\ud560 \uc218 \uc788\uac8c \ub9cc\ub4dc\ub294 \uc77c\uc774 \ub4e4\uc5b4 \uc788\ub2e4. 1945\ub144 \ub178\ubca8 \uc0dd\ub9ac\uc758\ud559\uc0c1\uc740 \ud50c\ub808\ubc0d\uacfc \ud50c\ub85c\ub9ac, \uccb4\uc778\uc5d0\uac8c \ud568\uaed8 \ub3cc\uc544\uac14\ub2e4. \ucd5c\ucd08\uc758 \uad00\ucc30\uacfc \ub4a4\uc774\uc740 \uac1c\ubc1c\uc774 \ub098\ub204\uc5b4\uc838 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uae30\uc5b5\ud558\uac8c \ud558\ub294 \ub300\ubaa9\uc774\ub2e4. \uc218\uc0c1\uc790 \uc138 \uc0ac\ub78c\uc758 \uc774\ub984\uc744 \uc548\ub2e4\uace0 \ucc38\uc5ec\ud55c \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \uc77c\uc744 \ub2e4 \uc54c\uac8c \ub418\ub294 \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc, \uc801\uc5b4\ub3c4 \ud55c \ubc88\uc758 \uc6b0\uc5f0\ub9cc\uc73c\ub85c \uc57d\uc774 \uc644\uc131\ub418\uc5c8\ub2e4\ub294 \uc778\uc0c1\uc5d0\uc11c\ub294 \ubc97\uc5b4\ub0a0 \uc218 \uc788\ub2e4. \uc601\uc6c5\uc801\uc778 \ubc1c\uacac\uc758 \uc21c\uac04\uc744 \ubc84\ub9b4 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8 \uc21c\uac04 \ub4a4\uc5d0 \uc5b4\ub5a4 \uc77c\uc774 \uc774\uc5b4\uc84c\ub294\uc9c0\ub97c \ub354\ud558\uba74 \ub41c\ub2e4. \ub204\uad70\uac00\uc758 \uad00\ucc30\uc744 \ub2e4\ub978 \uc0ac\ub78c\uc774 \ub2e4\uc2dc \uc2e4\ud5d8\ud558\uace0 \ubc29\ubc95\uc744 \ubc14\uafb8\uba70 \uc2e4\uc81c\ub85c \uc4f8 \uc218 \uc788\ub294 \uc870\uac74\uc744 \ub9cc\ub4e4\uc5b4 \uac14\ub2e4. \uacfc\ud559\uc758 \uc131\uacfc\ub294 \ucd9c\ubc1c\uc810\uc758 \uc0c8\ub85c\uc6c0\uacfc \uc774\uc5b4 \uac00\ub294 \uc791\uc5c5\uc774 \ud568\uaed8 \uc788\uc744 \ub54c \ub113\uc5b4\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc0bd\ud654\ub294 \uadf8 \uad00\ucc30\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc704\ud55c \uadf8\ub9bc\uc774\uba70 \uc2e4\uc81c \ubc30\uc591\uc811\uc2dc\uc758 \uae30\ub85d \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub9bc\uc5d0\uc11c \ube44\uc5b4 \ubcf4\uc774\ub294 \uc791\uc740 \uacf5\uac04\uc744 \ucc3e\uc558\ub2e4\uba74 \uadf8\ub2e4\uc74c\uc758 \uc9c8\ubb38\ub3c4 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc65c \ub2e4\ub97c\uae4c, \ubb34\uc5c7\uc774 \uc791\uc6a9\ud588\uc744\uae4c, \uac19\uc740 \ud6a8\uacfc\ub97c \ub2e4\uc2dc \uc5bb\uc744 \uc218 \uc788\uc744\uae4c. \ud604\uc0c1\uc740 \uc9c8\ubb38\uc744 \ud1b5\ud574 \uc5f0\uad6c\uc758 \ucd9c\ubc1c\uc810\uc774 \ub41c\ub2e4. \ud398\ub2c8\uc2e4\ub9b0\uc758 \uc774\uc57c\uae30\ub294 \uc6b0\uc5f0\uc744 \uae30\ub2e4\ub9ac\ub77c\ub294 \ub9d0\ubcf4\ub2e4 \ubc1c\uacac \ub4a4\uc758 \uc77c\uc744 \ubcf4\uac8c \ud55c\ub2e4. \uc624\ub298\ub0a0\uc5d0\ub294 \ub0b4\uc131\uacfc \uc801\uc808\ud55c \uc0ac\uc6a9\uc774\ub77c\ub294 \ub610 \ub2e4\ub978 \ubb38\uc81c\ub3c4 \ub0a8\uc544 \uc788\ub2e4. \ud2b9\uc815 \ud56d\uc0dd\uc81c\uac00 \ubaa8\ub4e0 \uac10\uc5fc\uc5d0 \uc4f0\uc778\ub2e4\ub294 \ub73b\uc73c\ub85c \uc77d\uc9c0 \uc54a\uace0, \ud558\ub098\uc758 \uad00\ucc30\uc774 \uce58\ub8cc\uc758 \uc790\uc6d0\uc774 \ub418\uae30\uae4c\uc9c0 \uc5bc\ub9c8\ub098 \uae34 \uc5f0\uacb0\uc774 \ud544\uc694\ud588\ub294\uc9c0 \uae30\uc5b5\ud558\uba74 \uc88b\ub2e4."}, {"id": "red-panda-tail", "title": "\ub808\uc11c\ud310\ub2e4\uc758 \uaf2c\ub9ac\ub294 \ub2f4\uc694\uac00 \ub418\uae30\ub3c4 \ud55c\ub2e4", "summary": "\uc904\ubb34\ub2ac \uaf2c\ub9ac\ub294 \uadc0\uc5ec\uc6b4 \uc7a5\uc2dd\ub9cc\uc740 \uc544\ub2d9\ub2c8\ub2e4. \ub098\ubb34 \uc704\uc758 \uc0dd\ud65c\uacfc \ucd94\uc6b4 \ub0a0\uc528\uc5d0 \ubaa8\ub450 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uc0dd\uba85\uacfc \uc778\uccb4", "categories": ["science"], "url": "stories/red-panda-tail/index.html", "image": "../media/red-panda-tail.jpg", "alt": "\ub098\ubb47\uac00\uc9c0 \uc704\uc5d0\uc11c \ud48d\uc131\ud55c \uaf2c\ub9ac\ub97c \ubab8 \uac00\uae4c\uc774\uc5d0 \ub454 \ub808\uc11c\ud310\ub2e4\uc758 AI \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ub808\uc11c\ud310\ub2e4\uc758 \uaf2c\ub9ac\ub294 \ub2f4\uc694\uac00 \ub418\uae30\ub3c4 \ud55c\ub2e4 \ub098\ubb47\uac00\uc9c0 \uc704\uc5d0\uc11c \ubc1c\uacac\ud558\ub294 \uaf2c\ub9ac\uc758 \ub450 \uac00\uc9c0 \uc4f0\uc784 \uc904\ubb34\ub2ac \uaf2c\ub9ac\ub294 \uadc0\uc5ec\uc6b4 \uc7a5\uc2dd\ub9cc\uc740 \uc544\ub2d9\ub2c8\ub2e4. \ub098\ubb34 \uc704\uc758 \uc0dd\ud65c\uacfc \ucd94\uc6b4 \ub0a0\uc528\uc5d0 \ubaa8\ub450 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4. \uc0dd\uba85\uacfc \uc778\uccb4 \uacfc\ud559\uacfc \ubc1c\uacac \ub808\uc11c\ud310\ub2e4\ub97c \uadf8\ub824 \ubcf4\ub77c\uace0 \ud558\uba74 \ubab8\ubcf4\ub2e4 \uaf2c\ub9ac\ub97c \uba3c\uc800 \ub5a0\uc62c\ub9b4\uc9c0\ub3c4 \ubaa8\ub978\ub2e4. \ubd89\uc740 \ud138 \uc0ac\uc774\ub85c \uc605\uc740 \uace0\ub9ac\uac00 \ubc88\uac08\uc544 \uc774\uc5b4\uc9c0\ub294, \uae38\uace0 \ud48d\uc131\ud55c \uaf2c\ub9ac\ub2e4. \ub098\ubb47\uac00\uc9c0\uc5d0 \uc549\uc544 \uc788\uc73c\uba74 \ubab8 \ub4a4\ub85c \ud55c\ucc38 \ub298\uc5b4\uc9c0\uae30\ub3c4 \ud55c\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uadc0\uc5ec\uc6b4 \ubb34\ub2ac\ubd80\ud130 \ubcf4\uc774\uc9c0\ub9cc, \uadf8 \uaf2c\ub9ac\uc5d0\ub294 \uaf64 \uc2e4\uc6a9\uc801\uc778 \uc4f0\uc784\ub3c4 \uc788\ub2e4. \uc2a4\ubbf8\uc2a4\uc18c\ub2c8\uc5b8 \uad6d\ub9bd\ub3d9\ubb3c\uc6d0\uc740 \ub808\uc11c\ud310\ub2e4\uc758 \uaf2c\ub9ac\uac00 \uade0\ud615\uc744 \uc7a1\uace0 \ucd94\uc704\uc640 \ubc14\ub78c\uc744 \uacac\ub514\ub294 \ub370 \ub3c4\uc6c0\uc744 \uc900\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ub808\uc11c\ud310\ub2e4\ub294 \ub098\ubb34\ub97c \uc798 \ud0c4\ub2e4. \ub098\ubb34\ub294 \ubab8\uc744 \uc228\uae30\uace0, \ud3ec\uc2dd\uc790\ub97c \ud53c\ud558\uace0, \uaca8\uc6b8\uc5d0 \ud587\ubcd5\uc744 \ucb10\ub294 \uc7a5\uc18c\uc774\uae30\ub3c4 \ud558\ub2e4. \ub545 \uc704\uc5d0\uc11c\ub9cc \uc0ac\ub294 \ub3d9\ubb3c\uacfc\ub294 \ub2e4\ub978 \uc0dd\ud65c\uc758 \uc790\ub9ac\uac00 \uc788\ub2e4. \uadf8 \uc790\ub9ac\uc5d0\uc11c \uae38\uace0 \ud48d\uc131\ud55c \uaf2c\ub9ac\ub294 \uade0\ud615\uc744 \uc720\uc9c0\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uac00\uc9c0\uac00 \ubab8\uc744 \ubc1b\uccd0 \uc900\ub2e4\uace0 \ud574\uc11c \uac77\uace0 \ub3cc\uc544\uc11c\ub294 \uc77c\uc774 \uc800\uc808\ub85c \uc26c\uc6cc\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubab8 \ub4a4\uc758 \uae34 \ubd80\ubd84\ub3c4 \ub098\ubb34 \uc704 \uc0dd\ud65c\uc758 \ud55c\ubaab\uc744 \ub9e1\ub294\ub2e4. \ub098\ubb34\ub97c \ub0b4\ub824\uc624\ub294 \ubaa8\uc2b5\ub3c4 \ud765\ubbf8\ub86d\ub2e4. \ub3d9\ubb3c\uc6d0\uc740 \uc720\uc5f0\ud55c \ubc1c\ubaa9 \uad6c\uc870 \ub355\ubd84\uc5d0 \uba38\ub9ac\ub97c \uc544\ub798\ub85c \ud5a5\ud55c \ucc44 \ub098\ubb34\uc904\uae30\ub97c \ub0b4\ub824\uc62c \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uaf2c\ub9ac\ub9cc \ub530\ub85c \ub5bc\uc5b4 \ubcf4\uae30\ubcf4\ub2e4 \ubab8 \uc804\uccb4\uc758 \uc6c0\uc9c1\uc784\uacfc \ud568\uaed8 \ubcf4\uba74 \ub354 \uc7ac\ubbf8\uc788\ub2e4. \ub808\uc11c\ud310\ub2e4\uac00 \uc0ac\ub294 \uacf3\uc5d0\ub294 \ud788\ub9d0\ub77c\uc57c\ub97c \ube44\ub86f\ud55c \ub192\uc740 \uc0b0\uc9c0\uc758 \uc232\uc774 \ud3ec\ud568\ub41c\ub2e4. \uadf8\uacf3\uc5d0\uc11c \ud48d\uc131\ud55c \ud138\uc740 \ubcf4\uae30 \uc88b\uc740 \uc678\ud22c \uc774\uc0c1\uc758 \uc758\ubbf8\ub97c \uac16\ub294\ub2e4. \ubab8\uc5d0\ub294 \ubd80\ub4dc\ub7fd\uace0 \ucd18\ucd18\ud55c \uc18d\ud138\uc774 \uc788\uace0, \uae34 \uaf2c\ub9ac\ub294 \uc2ec\ud55c \ucd94\uc704\uc640 \ubc14\ub78c\uc73c\ub85c\ubd80\ud130 \ubab8\uc744 \ubcf4\ud638\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ubc1c\ubc14\ub2e5\ub3c4 \ud138\ub85c \ub36e\uc5ec \uc788\ub2e4. \ud654\uba74\uc5d0\uc11c\ub294 \uc791\uc740 \ub3d9\ubb3c\uc774\uc9c0\ub9cc, \ucd94\uc6b4 \uacf3\uc758 \uc0dd\ud65c\uc5d0 \ud544\uc694\ud55c \ucc28\ub9bc\uc744 \ud558\uace0 \uc788\ub294 \uc148\uc774\ub2e4. \uaf2c\ub9ac\ub97c \ubab8 \uac00\uae4c\uc774\uc5d0 \ub454 \ubaa8\uc2b5\uc744 \ubcf4\uba74 \ub2f4\uc694\ub098 \ubaa9\ub3c4\ub9ac\uac00 \ub5a0\uc624\ub978\ub2e4. \ubb3c\ub860 \uc0ac\ub78c\uc774 \uc9e0 \ubb3c\uac74\uc744 \ub450\ub978 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub530\ub73b\ud55c \ubb3c\uac74\uc5d0 \ube57\ub300\uc5b4 \ubcf4\uba74, \uae34 \ud138\uc774 \uc65c \uc0dd\ud65c\uc5d0 \uc4f8\ubaa8\uac00 \uc788\ub294\uc9c0 \uc870\uae08 \uce5c\uc219\ud558\uac8c \ub290\uaef4\uc9c4\ub2e4. \uac00\uc9c0 \uc704\ub97c \uc62e\uaca8 \uac00\ub294 \uc21c\uac04\uc5d0\ub294 \uae34 \uaf2c\ub9ac\uac00 \uade0\ud615\uc5d0 \ub3c4\uc6c0\uc744 \uc900\ub2e4. \ubab8\uc744 \uc6c5\ud06c\ub9ac\uace0 \uc26c\ub294 \uc21c\uac04\uc5d0\ub294 \ucd94\uc704\uc640 \ubc14\ub78c\uc744 \ub9c9\ub294 \ub370 \uc4f0\uc77c \uc218 \uc788\ub2e4. \uac19\uc740 \ubd80\ubd84\uc774 \ub298 \uac19\uc740 \uc790\uc138\ub85c \uac19\uc740 \uae30\ub2a5\ub9cc \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud589\ub3d9\uc5d0 \ub530\ub77c \uc5b4\ub5a4 \uad00\uacc4\uac00 \ub450\ub4dc\ub7ec\uc9c0\ub294\uc9c0 \ub2ec\ub77c\uc9c4\ub2e4. \uaf2c\ub9ac\uc758 \uae38\uc774\ub97c \uc7a5\uc2dd\uc801\uc778 \ud2b9\uc9d5\uc73c\ub85c\ub9cc \uae30\uc5b5\ud558\uc9c0 \uc54a\uc744 \uc774\uc720\ub2e4. \ub2f4\uc694\ub77c\ub294 \ube44\uc720\ub294 \ubab8\uc744 \uac10\uc2f8\ub294 \uc778\uc0c1\uc744 \uac00\uae4c\uc774 \uac00\uc838\uc624\uc9c0\ub9cc \uc2e4\uc81c \ucc9c\uc73c\ub85c \ub9cc\ub4e0 \ubb3c\uac74\uacfc \uac19\uc740 \uad6c\uc870\ub294 \uc544\ub2c8\ub2e4. \uaf2c\ub9ac\ub294 \ubab8\uc758 \uc77c\ubd80\uc774\uace0 \ud138\uc744 \uc9c0\ub2cc\ub2e4. \ub530\ub73b\ud568\uc758 \uae30\ub2a5\uc744 \uc774\ud574\ud558\ub294 \uc785\uad6c\ub85c \ube44\uc720\ub97c \uc4f0\uace0, \uc2e4\uc81c \ubab8\uc758 \uc124\uba85\uc740 \uae30\uad00 \uc790\ub8cc\ub97c \ub530\ub77c \uc77d\uc73c\uba74 \ub41c\ub2e4. \uce5c\uc219\ud55c \ub9d0\uc774 \ub3d9\ubb3c\uc758 \uace0\uc720\ud55c \uc0dd\ud65c\uc744 \uc9c0\uc6b0\uc9c0 \uc54a\uac8c \ud558\ub294 \ubc29\ubc95\uc774\ub2e4. \uba38\ub9ac\ub97c \uc544\ub798\ub85c \ud5a5\ud574 \ub0b4\ub824\uc62c \uc218 \uc788\ub2e4\ub294 \uc124\uba85\uc740 \ub808\uc11c\ud310\ub2e4\uc758 \uc6c0\uc9c1\uc784\uc744 \ub2e4\ub974\uac8c \ubcf4\uac8c \ud55c\ub2e4. \uae34 \uaf2c\ub9ac\ub9cc\uc774 \uc544\ub2c8\ub77c \ubc1c\ubaa9\uc758 \uc720\uc5f0\ud568\ub3c4 \ub098\ubb34 \uc704 \uc0dd\ud65c\uacfc \uad00\uacc4\uac00 \uc788\ub2e4. \ud55c \uac00\uc9c0 \ub208\uc5d0 \ub744\ub294 \ubd80\ubd84\ub9cc\uc73c\ub85c \uc804\uccb4 \ud589\ub3d9\uc744 \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b4 \uac83\uc774\ub2e4. \ubab8\uc758 \uac01 \ubd80\ubd84\uc774 \ud568\uaed8 \uc77c\uc744 \ud55c\ub2e4\ub294 \uc810\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc774\ub54c \uc0ac\ub78c\uc774 \uac19\uc740 \uc790\uc138\ub97c \ud749\ub0b4 \ub0b4\uc5b4 \uc5bc\ub9c8\ub098 \uc26c\uc6b4\uc9c0 \uc2dc\ud5d8\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub3d9\ubb3c\uc758 \ud574\ubd80\ud559\uc801 \uc870\uac74\uc740 \uc6b0\ub9ac\uc640 \ub2e4\ub974\ub2e4. \uad00\ucc30\uc5d0\uc11c\ub294 \uc5b4\ub290 \ubc29\ud5a5\uc73c\ub85c \ub0b4\ub824\uc624\ub294\uc9c0\uc640 \ubc1c\uc774 \ub098\ubb34\uc5d0 \ub193\uc774\ub294 \uc790\ub9ac\ub97c \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc815\uc9c0\ud55c \uc0ac\uc9c4 \ud558\ub098\ub85c \uc6c0\uc9c1\uc784\uc758 \ubaa8\ub4e0 \uc21c\uc11c\ub97c \ud655\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc2e4\uc81c \ud589\ub3d9 \uc790\ub8cc\uc640 \ud574\uc124\uc774 \uc11c\ub85c \ub3c4\uc6b8 \uc218 \uc788\ub2e4. \ub808\uc11c\ud310\ub2e4\ub294 \ub192\uc740 \uc0b0\uc9c0\uc758 \uc232\uc5d0\uc11c \uc0b0\ub2e4\uace0 \uc18c\uac1c\ub41c\ub2e4. \ub098\ubb34\ub294 \uc62c\ub77c\uac08 \uc9c0\ud615\uc774\uace0 \ud138\uc740 \ucd94\uc704\ub97c \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc0dd\uae40\uc0c8\ub97c \ud658\uacbd\uacfc \uc5f0\uacb0\ud558\uba74 \uadc0\uc5fd\ub2e4\ub294 \uac10\uc0c1 \uc678\uc5d0 \uc5b4\ub5a4 \uc870\uac74\uc5d0\uc11c \uc0dd\ud65c\ud558\ub294\uc9c0\ub77c\ub294 \uc9c8\ubb38\uc774 \uc0dd\uae34\ub2e4. \ubab8\uc758 \ud2b9\uc9d5\uc774 \ub2e8\uc9c0 \ubcf4\ub294 \uc0ac\ub78c\uc744 \uc990\uac81\uac8c \ud558\ub824\uace0 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc5b4\ub290 \ud589\ub3d9\uc774\ub4e0 \ud558\ub098\uc758 \uc801\uc751 \uc774\uc57c\uae30\ub85c \uc989\uc2dc \ud655\uc815\ud574 \ub9d0\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc790\ub8cc\uac00 \ud655\uc778\ud55c \uade0\ud615\uacfc \ubcf4\uc628, \ubc1c\ubaa9\uc758 \uae30\ub2a5\uc744 \uc911\uc2ec\uc73c\ub85c \uc77d\ub294 \uac83\uc774 \uc815\ud655\ud558\ub2e4. \ud55c \uac1c\uccb4\uc758 \uc0c1\ud0dc\uc640 \ud65c\ub3d9\uc740 \uadf8 \uc21c\uac04\uc758 \ud658\uacbd\ub3c4 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc54c\ub824\uc9c4 \uae30\ub2a5\uc744 \ubc30\uc6b0\ub294 \uc77c\uacfc \uc0ac\uc9c4 \uc18d \ud589\ub3d9\uc758 \uc6d0\uc778\uc744 \ubaa8\ub450 \uc548\ub2e4\uace0 \uc0dd\uac01\ud558\ub294 \uc77c\uc740 \uad6c\ubd84\ud560 \uc218 \uc788\ub2e4. \uc6c5\ud06c\ub9b0 \ub808\uc11c\ud310\ub2e4\ub294 \uac00\ub9cc\ud788 \ub193\uc778 \uc778\ud615\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uc790\uc138 \uc548\uc5d0 \ub098\ubb34\ub97c \uc624\ub974\uace0 \ubc14\ub78c\uc744 \ud53c\ud558\ub294 \ub3d9\ubb3c\uc758 \ubab8\uc774 \uc788\ub2e4. \uae34 \uaf2c\ub9ac\uc640 \ubc1c\uc758 \ud138, \ucd18\ucd18\ud55c \uc18d\ud138\uc5d0 \uad00\ud55c \uc124\uba85\uc744 \uc54c\uace0 \ub2e4\uc2dc \ubcf4\uba74 \uc870\uc6a9\ud55c \ubaa8\uc2b5\ub3c4 \ub2e4\ub978 \uc815\ubcf4\ub85c \ucc44\uc6cc\uc9c4\ub2e4. \uc6c0\uc9c1\uc784\uc774 \uc5c6\ub2e4\uace0 \uad00\ucc30\ud560 \ubd80\ubd84\uc774 \uc5c6\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub2e4\uc74c \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uc5bc\uad74\uc744 \ubcf8 \ub4a4 \ubab8 \ub4a4\uc758 \uaf2c\ub9ac\ub85c \ub208\uc744 \uc62e\uaca8 \ubcf4\uc790. \uc5b4\ub290 \ucabd\uc5d0 \ub193\uc5ec \uc788\uace0 \ubab8\uacfc \uc5bc\ub9c8\ub098 \uac00\uae4c\uc6b4\uc9c0 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uadf8 \ubaa8\uc591\uc5d0 \uac10\uc815\uc744 \ub2e8\uc815\ud574 \ubd99\uc774\uc9c0 \uc54a\uc544\ub3c4 \uc88b\ub2e4. \uaf2c\ub9ac\uac00 \ub2f4\uc694\uac00 \ub418\uae30\ub3c4 \ud55c\ub2e4\ub294 \ub9d0\uc740 \ud55c \ud2b9\uc9d5\uc744 \uc0dd\ud65c\uc758 \ub9e5\ub77d\uc73c\ub85c \uc77d\uac8c \ud558\ub294 \uc791\uc740 \uae38\uc7a1\uc774\ub2e4. \ubcf4\uae30 \uc88b\uc740 \ubaa8\uc591 \ub4a4\uc5d0 \uc4f0\uc784\uc758 \uc5ec\ub7ec \uc2dc\uac04\uc774 \uc788\uc5c8\ub2e4. \ub808\uc11c\ud310\ub2e4\uc758 \uaf2c\ub9ac\uc5d0\ub294 \ubd89\uc740\uc0c9\uacfc \uc605\uc740 \uc0c9\uc758 \uace0\ub9ac \ubb34\ub2ac\uac00 \ubc88\uac08\uc544 \ub098\ud0c0\ub09c\ub2e4. \uadf8 \ubb34\ub2ac\ub97c \uc54c\uc544\ubcf4\ub294 \uc990\uac70\uc6c0\uacfc \uaf2c\ub9ac\uc758 \uc4f0\uc784\uc744 \uc544\ub294 \uc990\uac70\uc6c0\uc740 \uc870\uae08 \ub2e4\ub974\ub2e4. \uc774\ub984\uacfc \uc0dd\uae40\uc0c8\ub97c \ub9de\ud78c \ub2e4\uc74c\uc5d0\ub3c4 \uad6c\uacbd\uc740 \uacc4\uc18d\ub41c\ub2e4. \uac00\uc9c0 \uc704\uc5d0\uc11c \ubc29\ud5a5\uc744 \ubc14\uafc0 \ub54c \uaf2c\ub9ac\uac00 \uc5b4\ub514\uc5d0 \uc788\ub294\uc9c0, \uc26c\ub294 \ub3d9\uc548\uc5d0\ub294 \ubab8\uacfc \uc5bc\ub9c8\ub098 \uac00\uae4c\uc6b4\uc9c0 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \ub808\uc11c\ud310\ub2e4 \uc0ac\uc9c4\uc744 \ubcf8\ub2e4\uba74 \uc5bc\uad74\ub9cc \ud655\ub300\ud558\uc9c0 \ub9d0\uace0 \uaf2c\ub9ac\uae4c\uc9c0 \ub4e4\uc5b4\uc628 \uc7a5\uba74\ub3c4 \uace8\ub77c \ubcf4\uc790. \uc791\uc740 \uc5bc\uad74 \ub4a4\ub85c \ub298\uc5b4\uc9c4 \uae34 \ubd80\ubd84\uc5d0, \ub098\ubb34\ub97c \ud0c0\uace0 \ucd94\uc704\ub97c \uacac\ub514\ub294 \uc0dd\ud65c\uc774 \ud568\uaed8 \ub2ec\ub824 \uc788\ub2e4."}, {"id": "roentgen-xray-shadow-and-diagnosis", "title": "\ub8b4\ud2b8\uac90\uc758 \uc5d1\uc2a4\uc120 \u2014 \ubab8\uc744 \uc5f4\uc9c0 \uc54a\uace0 \uc548\uc744 \ubcf8\ub2e4\ub294 \uac83", "summary": "\ubcf4\uc774\uc9c0 \uc54a\ub294 \uad11\uc120\uc774 \uac10\uc9c0\uc640 \uc0ac\uc9c4\uc744 \uac70\uccd0 \ubab8 \uc548\uc744 \uc0b4\ud53c\ub294 \uc790\ub8cc\uac00 \ub41c \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uacfc\ud559\uc790\uc758 \ubc1c\uacac", "categories": ["science"], "url": "stories/roentgen-xray-shadow-and-diagnosis/index.html", "image": "../media/roentgen-xray-shadow-and-diagnosis.jpg", "alt": "1900\ub144 \uae30\uc220\uc0ac \ucc45\uc5d0 \uc218\ub85d\ub41c \uc190\uc758 \uc5d1\uc2a4\uc120 \uc790\ub8cc \uc0ac\uc9c4", "text": "\ub8b4\ud2b8\uac90\uc758 \uc5d1\uc2a4\uc120 \u2014 \ubab8\uc744 \uc5f4\uc9c0 \uc54a\uace0 \uc548\uc744 \ubcf8\ub2e4\ub294 \uac83 1895\ub144\uc758 \ubc1c\uacac\uc774 \uad00\ucc30\u00b7\uc0ac\uc9c4\u00b7\uc9c4\ub2e8\uc758 \uadfc\uac70\ub97c \ubc14\uafbc \uacfc\uc815 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uad11\uc120\uc774 \uac10\uc9c0\uc640 \uc0ac\uc9c4\uc744 \uac70\uccd0 \ubab8 \uc548\uc744 \uc0b4\ud53c\ub294 \uc790\ub8cc\uac00 \ub41c \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uacfc\ud559\uc790\uc758 \ubc1c\uacac \uacfc\ud559\uacfc \ubc1c\uacac \uc190\uc758 \uc0ac\uc9c4\uc778\ub370 \ud53c\ubd80\ubcf4\ub2e4 \ubf08\uac00 \uc120\uba85\ud558\uac8c \ubcf4\uc778\ub2e4. \uc775\uc219\ud55c \uc5d1\uc2a4\uc120 \uc0ac\uc9c4\ub3c4 \ucc98\uc74c \ubcf4\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc774\uc0c1\ud55c \uadf8\ub9bc\uc774\uc5c8\uc744 \uac83\uc774\ub2e4. \uac89\uc744 \ube44\ucd94\ub294 \uc0ac\uc9c4\uacfc \ub2ec\ub9ac, \ubab8\uc744 \ud1b5\uacfc\ud55c \ube5b\uc758 \ucc28\uc774\uac00 \ub0b4\ubd80 \uad6c\uc870\ub97c \ub4dc\ub7ec\ub0b8\ub2e4. 1895\ub144 \ube4c\ud5ec\ub984 \ub8b4\ud2b8\uac90\uc758 \ubc1c\uacac\uc740 \ubb34\uc5c7\uc744 \ubcf8\ub2e4\uace0 \ub9d0\ud558\ub294\uc9c0 \uadf8 \uc758\ubbf8\ub97c \ub113\ud614\ub2e4. \uc774 \uc774\uc57c\uae30\ub294 \uc6b0\uc5f0\ud788 \uc2e0\uae30\ud55c \ud604\uc0c1\uc744 \ubcf4\uc558\ub2e4\ub294 \ud55c \uc7a5\uba74\ub9cc\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \ub0af\uc120 \uad11\uc120\uc758 \uc131\uc9c8\uc744 \uc0b4\ud53c\uace0 \uadf8\uac83\uc744 \uae30\ub85d\uc73c\ub85c \ub0a8\uae30\uba70 \uc9c4\ub2e8\uc758 \uc790\ub8cc\ub85c \uc0ac\uc6a9\ud558\ub294 \uacfc\uc815\uc774 \uc911\uc694\ud588\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294 \uac83\uc744 \uc5b4\ub5bb\uac8c \ubcf4\uc774\uac8c \ub9cc\ub4e4\uc5c8\ub294\uc9c0 \ucc28\ub840\ub85c \ub530\ub77c\uac00 \ubcf4\uc790. \ub8b4\ud2b8\uac90\uc740 \ubc29\uc804\uad00\uc744 \uc774\uc6a9\ud55c \uc2e4\ud5d8\uc5d0\uc11c \uc0c8\ub85c\uc6b4 \uc885\ub958\uc758 \uad11\uc120\uc744 \uc5f0\uad6c\ud588\ub2e4. \uc774 \uad11\uc120\uc740 \ub208\uc73c\ub85c \ubc14\ub85c \ubcfc \uc218 \uc788\ub294 \ube5b\uacfc \ub2ec\ub790\ub2e4. \uadf8\ub294 \uc544\uc9c1 \uc815\uccb4\uac00 \ucda9\ubd84\ud788 \uc54c\ub824\uc9c0\uc9c0 \uc54a\uc740 \uac83\uc744 \ub098\ud0c0\ub0b4\ub294 X\ub97c \uc774\ub984\uc5d0 \uc0ac\uc6a9\ud588\ub2e4. \uc775\uc219\ud55c \uc774\ub984\uc758 \ucd9c\ubc1c\uc810\uc5d0 \ubaa8\ub978\ub2e4\ub294 \uc778\uc815\uc774 \ub4e4\uc5b4 \uc788\ub294 \uc148\uc774\ub2e4. \ubaa8\ub974\ub294 \ud604\uc0c1\uc744 \ub9cc\ub0ac\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uacfc\ud559\uc801 \ubc1c\uacac\uc774 \uc644\uc131\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uc870\uac74\uc5d0\uc11c \ub098\ud0c0\ub098\ub294\uc9c0, \ubb34\uc5c7\uc744 \ud1b5\uacfc\ud558\uace0 \ubb34\uc5c7\uc5d0 \ub9c9\ud788\ub294\uc9c0 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc774\ub984\uc744 \ubd99\uc774\ub294 \uc77c\uacfc \uc131\uc9c8\uc744 \ud655\uc778\ud558\ub294 \uc77c\uc774 \uc774\uc5b4\uc838\uc57c \ub2e4\ub978 \uc0ac\ub78c\ub3c4 \uadf8 \ud604\uc0c1\uc744 \uc774\ud574\ud558\uace0 \uc774\uc6a9\ud560 \uc218 \uc788\ub2e4. \uc5d1\uc2a4\uc120\uc740 \uc7ac\ub8cc\uc640 \uc2e0\uccb4 \uc870\uc9c1\uc744 \uac19\uc740 \uc815\ub3c4\ub85c \ud1b5\uacfc\ud558\uc9c0 \uc54a\ub294\ub2e4. \ubab8\uc758 \uc5ec\ub7ec \ubd80\ubd84\uc5d0\uc11c \ud761\uc218\ub418\ub294 \uc815\ub3c4\uac00 \ub2ec\ub77c \uc601\uc0c1\uc5d0 \ucc28\uc774\uac00 \uc0dd\uae34\ub2e4. \ubf08\uc640 \uc8fc\ubcc0 \uc870\uc9c1, \ubab8 \uc548\uc758 \uae08\uc18d \uac19\uc740 \ubb3c\uc9c8\uc774 \uc11c\ub85c \ub2e4\ub978 \ubaa8\uc2b5\uc73c\ub85c \ub098\ud0c0\ub098\ub294 \uc774\uc720\ub2e4. \ubab8 \uc548\uc5d0 \uc9c1\uc811 \uc791\uc740 \uce74\uba54\ub77c\ub97c \ub123\uc5b4 \ucc0d\ub294 \ubc29\uc2dd\uacfc\ub294 \ub2e4\ub974\ub2e4. \uadf8\ub798\uc11c \uc5d1\uc2a4\uc120 \uc0ac\uc9c4\uc744 \ud53c\ubd80\uac00 \ud22c\uba85\ud574\uc9c4 \uc644\uc804\ud55c \uc2e4\ubb3c \ubaa8\uc2b5\uc73c\ub85c \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ud2b9\uc815\ud55c \ubc29\uc2dd\uc73c\ub85c \uc5bb\uc740 \ucc28\uc774\ub97c \uc601\uc0c1\uc73c\ub85c \ub9cc\ub4e0 \uacb0\uacfc\ub2e4. \ubb34\uc5c7\uc774 \uc798 \ub4dc\ub7ec\ub098\uace0 \ubb34\uc5c7\uc774 \uad6c\ubd84\ub418\uae30 \uc5b4\ub824\uc6b4\uc9c0\uc758 \uc870\uac74\uc774 \uc788\ub2e4. \uc0c8\ub85c\uc6b4 \uc2dc\uac01\uc744 \uc5bb\ub294 \uc77c\uc740 \uadf8 \uc2dc\uac01\uc758 \ud55c\uacc4\ub97c \uc544\ub294 \uc77c\uacfc \ud568\uaed8 \uac00\uc57c \ud55c\ub2e4. \ub208\uc5d0 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uad11\uc120\uc774\ub77c\uba74 \uadf8\uac83\uc774 \uc5b4\ub514\uc5d0 \ub3c4\ub2ec\ud588\ub294\uc9c0 \uc5b4\ub5bb\uac8c \uc54c \uc218 \uc788\uc744\uae4c. \ud615\uad11\uc744 \ub0b4\ub294 \ubb3c\uc9c8\uacfc \uc0ac\uc9c4\uc758 \uac10\uad11 \uc7ac\ub8cc\uac00 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud588\ub2e4. \uad11\uc120\uc774 \ubb3c\uc9c8\uc5d0 \ubbf8\uce58\ub294 \uc791\uc6a9\uc744 \ud1b5\ud574 \ub208\uc73c\ub85c \ubcfc \uc218 \uc788\ub294 \ubcc0\ud654\ub97c \uc5bb\ub294\ub2e4. \uac10\uac01\uc744 \ub300\uc2e0\ud558\ub294 \ub3c4\uad6c\uac00 \uad00\ucc30\uc744 \uac00\ub2a5\ud558\uac8c \ud55c \uac83\uc774\ub2e4. \uc774 \uc810\uc5d0\uc11c \ubc1c\uacac\uc740 \uc0ac\ub78c\uc758 \ub208\uc774 \uac11\uc790\uae30 \ub354 \uc88b\uc544\uc9c4 \uc0ac\uac74\uc774 \uc544\ub2c8\ub2e4. \uc7a5\uce58\uc640 \ubb3c\uc9c8\uc744 \uc5f0\uacb0\ud574 \uc0c8\ub85c\uc6b4 \uc815\ubcf4\ub97c \uc77d\uac8c \ub41c \uc0ac\uac74\uc774\ub2e4. \ud604\ub300 \uacfc\ud559\uc758 \ub9ce\uc740 \uc601\uc0c1\ub3c4 \ube44\uc2b7\ud55c \uc9c8\ubb38\uc744 \ud488\uace0 \uc788\ub2e4. \ubb34\uc5c7\uc744 \uc9c1\uc811 \ubcf4\uace0 \uc788\uc73c\uba70 \ubb34\uc5c7\uc740 \uac10\uc9c0\ud55c \uc2e0\ud638\ub97c \ub2e4\ub978 \ud615\ud0dc\ub85c \uc62e\uae34 \uac83\uc778\uc9c0 \uad6c\ubcc4\ud574 \ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \uad00\ucc30\ud55c \ubaa8\uc2b5\uc744 \uc0ac\uc9c4\uc73c\ub85c \ub0a8\uae30\uba74 \uc21c\uac04\uc758 \uacbd\ud5d8\uc774 \uae30\ub85d\uc774 \ub41c\ub2e4. \uc5f0\uad6c\uc790\uc640 \uc758\uc0ac\ub294 \uac19\uc740 \uc601\uc0c1\uc744 \ub2e4\uc2dc \uc0b4\ud53c\uace0 \ub2e4\ub978 \uc0ac\ub78c\uacfc \ube44\uad50\ud560 \uc218 \uc788\ub2e4. \uc0c8\ub85c\uc6b4 \uad11\uc120\uc758 \uc131\uc9c8\uc744 \uc124\uba85\ud558\ub294 \ub370\uc5d0\ub3c4 \uc774\ubbf8\uc9c0\uac00 \uac15\ud55c \uc124\ub4dd\ub825\uc744 \uac00\uc84c\ub2e4. \ub9d0\ub85c\ub9cc \uc2e0\uae30\ud558\ub2e4\uace0 \uc804\ud558\ub294 \uac83\uacfc \ub208\uc55e\uc5d0 \uae30\ub85d\uc744 \ub193\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ud574\uc11d\uc744 \uc790\ub3d9\uc73c\ub85c \uc815\ud655\ud558\uac8c \ud574 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5b4\ub5a4 \ubc29\ud5a5\uacfc \uc870\uac74\uc5d0\uc11c \uc5bb\uc5c8\ub294\uc9c0, \uc5b4\ub290 \ubd80\ubd84\uc774 \uacb9\uccd0 \ubcf4\uc774\ub294\uc9c0 \uc54c\uc544\uc57c \ud55c\ub2e4. \uae30\ub85d\uc740 \ud310\ub2e8\uc744 \ub3d5\ub294 \uc790\ub8cc\uc774\uc9c0 \ud310\ub2e8\uc744 \ub300\uc2e0\ud558\ub294 \uc874\uc7ac\ub294 \uc544\ub2c8\ub2e4. \uc5d1\uc2a4\uc120\uc758 \uc5ed\uc0ac\ub294 \uc601\uc0c1\uc758 \ud798\uacfc \uc77d\ub294 \uc0ac\ub78c\uc758 \uc804\ubb38\uc131\uc774 \ud568\uaed8 \ucee4\uc9c4 \uc5ed\uc0ac\ub2e4. \uc5d1\uc2a4\uc120\uc740 \ubf08\uc758 \uc0c1\ud0dc\ub098 \ubab8 \uc548\uc758 \uae08\uc18d \ubb3c\uccb4 \ub4f1\uc744 \ud30c\uc545\ud558\ub294 \ub370 \uc0c8\ub85c\uc6b4 \uac00\ub2a5\uc131\uc744 \uc5f4\uc5c8\ub2e4. \uac89\uc5d0\uc11c \ubcf4\uc774\uc9c0 \uc54a\ub294 \uad6c\uc870\ub97c \ud655\uc778\ud560 \uc790\ub8cc\uac00 \uc0dd\uae30\uba74\uc11c \uc9c4\ub2e8\uacfc \ucc98\uce58\uc758 \ud310\ub2e8\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \ubab8\uc744 \uc9c1\uc811 \uc5f4\uc5b4 \ubcf4\uae30 \uc804\uc5d0 \uc5bb\ub294 \uc815\ubcf4\uc758 \ubc94\uc704\uac00 \ub113\uc5b4\uc9c4 \uac83\uc774\ub2e4. \uc774 \ubcc0\ud654\ub97c \ubaa8\ub4e0 \uc9c8\ubcd1\uc744 \ud55c \uc7a5\uc73c\ub85c \uc54c\uc544\ub0b4\ub294 \ub2a5\ub825\ucc98\ub7fc \uc18c\uac1c\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc601\uc0c1\uc740 \ud2b9\uc815\ud55c \uc9c8\ubb38\uc5d0 \ub3c4\uc6c0\uc774 \ub418\ub294 \ubc29\uc2dd\uc774\ub2e4. \ubb34\uc5c7\uc744 \ud655\uc778\ud558\ub824\ub294\uc9c0\uc5d0 \ub530\ub77c \ud544\uc694\ud55c \uc790\ub8cc\uc640 \ubc29\ubc95\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc5d1\uc2a4\uc120\uc758 \uc911\uc694\uc131\uc740 \ub9cc\ub2a5\uc774\ub77c\ub294 \ub370 \uc788\uc9c0 \uc54a\uace0 \uc774\uc804\uacfc \ub2e4\ub978 \uc885\ub958\uc758 \uadfc\uac70\ub97c \uc81c\uacf5\ud588\ub2e4\ub294 \ub370 \uc788\ub2e4. \ubc1c\uacac \ub4a4\uc5d0\ub294 \uc2e4\uc81c\ub85c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \uc7a5\uce58\uc758 \uac1c\uc120\uc774 \uc774\uc5b4\uc84c\ub2e4. \uad11\uc120\uc744 \ub9cc\ub4e4\uace0 \ub300\uc0c1\uc744 \ub193\uace0 \uacb0\uacfc\ub97c \uae30\ub85d\ud558\ub294 \uacfc\uc815\uc774 \ud558\ub098\uc758 \uccb4\uacc4\uac00 \ub418\uc5b4\uc57c \ud588\ub2e4. \uc2e4\ud5d8\uc2e4\uc758 \ud604\uc0c1\uc744 \uc9c4\ub8cc\uc758 \ub3c4\uad6c\ub85c \uc62e\uae30\ub294 \ub370\uc5d0\ub294 \uc548\uc815\uc131\uacfc \uc0ac\uc6a9 \uc870\uac74\uc5d0 \ub300\ud55c \uc9c0\uc2dd\ub3c4 \ud544\uc694\ud588\ub2e4. \ucd08\uae30\uc758 \uac10\ud0c4\uc744 \uc624\ub298\uc758 \uac80\uc0ac\uac00 \uc791\ub3d9\ud558\ub294 \ubaa8\ub4e0 \uc870\uac74\uacfc \uac19\ub2e4\uace0 \ubcf4\uc544\uc11c\ub294 \uc548 \ub41c\ub2e4. \ubc29\uc0ac\uc120\uc744 \uc774\uc6a9\ud558\ub294 \uae30\uc220\uc740 \ub178\ucd9c\uc744 \uad00\ub9ac\ud558\uace0 \ubaa9\uc801\uc5d0 \ub9de\uac8c \uc0ac\uc6a9\ud558\ub294 \ubb38\uc81c\uac00 \ub530\ub978\ub2e4. 19\uc138\uae30 \ub9d0\uc758 \uc790\ub8cc\uc5d0 \ub098\uc628 \uc2e4\ud5d8\uacfc \uae30\uad6c\ub294 \ub2f9\uc2dc\uc758 \uc5ed\uc0ac\ub97c \uc774\ud574\ud558\uae30 \uc704\ud55c \uae30\ub85d\uc73c\ub85c \uc77d\uc5b4\uc57c \ud55c\ub2e4. \ud604\uc7ac\uc758 \uc0ac\uc6a9 \uc9c0\uce68\uc744 \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5d1\uc2a4\uc120 \uc0ac\uc9c4\uc740 \ubab8 \uc548\uc744 \ubcf8\ub2e4\ub294 \ud45c\ud604\uc744 \uc77c\uc0c1\uc801\uc778 \ub9d0\ub85c \ub9cc\ub4e4\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \uc2e4\uc81c\ub85c\ub294 \uad11\uc120\uacfc \uc2e0\uccb4 \uc870\uc9c1, \uac10\uc9c0 \uc7a5\uce58\uc640 \ud574\uc11d\uc774 \ud568\uaed8 \uc791\ub3d9\ud55c\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \ud55c \uc7a5 \ub4a4\uc5d0 \uc5ec\ub7ec \ub2e8\uacc4\uc758 \ubcc0\ud658\uc774 \uc788\ub294 \uac83\uc774\ub2e4. \uc774 \uacfc\uc815\uc744 \uc54c\uba74 \uacfc\ud559 \uc601\uc0c1\uc5d0 \ub300\ud55c \uac10\ud0c4\ub3c4 \uc870\uae08 \ub354 \uad6c\uccb4\uc801\uc774 \ub41c\ub2e4. \uc624\ub798\ub41c \uc190\uc758 \uc5d1\uc2a4\uc120 \uc0ac\uc9c4\uc744 \ubcfc \ub54c\uc5d0\ub3c4 \uc774\uac83\uc774 \ub204\uad6c\ub098 \ub9e8\ub208\uc73c\ub85c \ubcfc \uc218 \uc788\ub358 \ubaa8\uc2b5\uc740 \uc544\ub2c8\uc5c8\ub2e4\ub294 \uc810\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc775\uc219\ud55c \uc190\uc744 \ub0af\uc120 \uc790\ub8cc\ub85c \ubc14\uafb8\uc5b4 \ubcf4\uc5ec \uc900 \ub9e4\uccb4\uc758 \ud0c4\uc0dd\uc774 \uadf8 \uc548\uc5d0 \uc788\ub2e4. \ub8b4\ud2b8\uac90\uc758 \ubc1c\uacac\uc744 \uae30\uc5b5\ud560 \ub54c\uc5d0\ub294 \uc6b0\uc5f0\uc758 \uc21c\uac04 \uc606\uc5d0 \ud655\uc778\uacfc \uae30\ub85d\uc758 \uacfc\uc815\uc744 \ub193\uc544 \ubcf4\uc790. \uc774\ub984\uc5d0 \ub0a8\uc740 X\ub294 \ucc98\uc74c\uc758 \ub0af\uc126\uc744 \uc54c\ub824 \uc8fc\uace0, \uc0ac\uc9c4\uc740 \uadf8 \ub0af\uc126\uc744 \ub2e4\ub978 \uc0ac\ub78c\ub3c4 \uc0b4\ud544 \uc218 \uc788\ub294 \uc790\ub8cc\ub85c \ubc14\uafbc\ub2e4. \uacfc\ud559\uc740 \ub354 \ub9ce\uc774 \ubcf4\ub294 \uc77c\uc778 \ub3d9\uc2dc\uc5d0 \uc5b4\ub5bb\uac8c \ubcf4\uac8c \ub418\uc5c8\ub294\uc9c0 \uc124\uba85\ud558\ub294 \uc77c\uc774\uae30\ub3c4 \ud558\ub2e4."}, {"id": "semmelweis-handwashing-and-hospital-wards", "title": "\uc81c\uba5c\ubc14\uc774\uc2a4 \u2014 \uc758\uc0ac\uc758 \uc190\uc774 \uc9c0\ub098\uc628 \uae38\uc744 \ubb3b\ub2e4", "summary": "1847\ub144 \uc0b0\uc695\uc5f4\uacfc \uc190 \uc53b\uae30\uc758 \uad00\ucc30\uc744 \ub530\ub77c, \uc775\uc219\ud55c \uc9c4\ub8cc \uad00\ud589\uc744 \ub2e4\uc2dc \ubb3b\ub294 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uacfc\ud559\uc790\uc758 \ubc1c\uacac", "categories": ["science"], "url": "stories/semmelweis-handwashing-and-hospital-wards/index.html", "image": "../media/semmelweis-handwashing-and-hospital-wards.jpg", "alt": "\uc774\uadf8\ub098\uce20 \uc81c\uba5c\ubc14\uc774\uc2a4\uc758 \uc61b \ucd08\uc0c1", "text": "\uc81c\uba5c\ubc14\uc774\uc2a4 \u2014 \uc758\uc0ac\uc758 \uc190\uc774 \uc9c0\ub098\uc628 \uae38\uc744 \ubb3b\ub2e4 \ub354 \uc88b\uc740 \uce58\ub8cc\ub97c \ubbff\ub358 \ubcd1\ub3d9\uc5d0\uc11c \ubc1c\uacac\ud55c \ub73b\ubc16\uc758 \ucc28\uc774 1847\ub144 \uc0b0\uc695\uc5f4\uacfc \uc190 \uc53b\uae30\uc758 \uad00\ucc30\uc744 \ub530\ub77c, \uc775\uc219\ud55c \uc9c4\ub8cc \uad00\ud589\uc744 \ub2e4\uc2dc \ubb3b\ub294 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uacfc\ud559\uc790\uc758 \ubc1c\uacac \uacfc\ud559\uacfc \ubc1c\uacac \ubcd1\uc6d0\uc5d0 \ub4e4\uc5b4\uc624\uba74 \ub354 \uc548\uc804\ud560 \uac83\uc774\ub77c\uace0 \uae30\ub300\ud55c\ub2e4. \uadf8\ub7f0\ub370 \uac19\uc740 \ubcd1\uc6d0\uc758 \ub2e4\ub978 \ubcd1\ub3d9\uc5d0\uc11c \uc0ac\ub9dd\uc758 \uc591\uc0c1\uc774 \ub2e4\ub974\uac8c \ub098\ud0c0\ub09c\ub2e4\uba74 \ubb34\uc5c7\uc744 \uc0b4\ud3b4\uc57c \ud560\uae4c. \ub204\uac00 \ud658\uc790\ub97c \ub3cc\ubcf4\ub294\uc9c0, \uadf8 \uc0ac\ub78c\uc774 \ud658\uc790\uc5d0\uac8c \uc624\uae30 \uc804\uc5d0 \uc5b4\ub514\uc5d0 \uc788\uc5c8\ub294\uc9c0\ub3c4 \uc9c8\ubb38\uc774 \ub420 \uc218 \uc788\ub2e4. 1847\ub144 \uc774\uadf8\ub098\uce20 \uc81c\uba5c\ubc14\uc774\uc2a4\uac00 \ubd99\uc7a1\uc740 \ubb38\uc81c\ub294 \ucd9c\uc0b0 \ub4a4 \ubc1c\uc0dd\ud558\ub294 \uc0b0\uc695\uc5f4\uc774\uc5c8\ub2e4. \uc624\ub298\ub0a0 \uc190 \uc53b\uae30\ub294 \ub108\ubb34 \uc775\uc219\ud55c \ub9d0\uc774\uc9c0\ub9cc \ub2f9\uc2dc\uc758 \uad00\ucc30\uc740 \uc758\uc0ac\uc758 \uc77c\uc0c1\uc801\uc778 \ud589\ub3d9 \uc790\uccb4\ub97c \uc758\uc2ec\ud558\uac8c \ub9cc\ub4e4\uc5c8\ub2e4. \uce58\ub8cc\ud558\ub294 \uc190\uc774 \uc9c8\ubcd1\uc744 \uc62e\uae38 \uc218\ub3c4 \uc788\ub2e4\ub294 \ubd88\ud3b8\ud55c \uac00\ub2a5\uc131\uc774\uc5c8\ub2e4. \uc81c\uba5c\ubc14\uc774\uc2a4\ub294 \uc758\uc0ac\uc640 \uc758\ud559\uc0dd\uc774 \ub3cc\ubcf4\ub294 \ubcd1\ub3d9\uc5d0\uc11c \uc0b0\ubaa8\uac00 \uc0b0\uc695\uc5f4\ub85c \uc0ac\ub9dd\ud558\ub294 \ube44\uc728\uc774 \uc870\uc0b0\uc0ac\uac00 \ub3cc\ubcf4\ub294 \ubcd1\ub3d9\ubcf4\ub2e4 \ub192\ub2e4\ub294 \uc810\uc744 \uad00\ucc30\ud588\ub2e4. \uc804\ubb38\uac00\uac00 \ub354 \ub9ce\uc774 \ucc38\uc5ec\ud558\uba74 \uacb0\uacfc\ub3c4 \ub354 \uc88b\uc544\uc57c \ud55c\ub2e4\ub294 \uae30\ub300\uc640 \uc5b4\uae0b\ub098\ub294 \ucc28\uc774\uc600\ub2e4. \ub2f9\uc5f0\ud55c \uc124\uba85\uc774 \ub9de\uc9c0 \uc54a\uc744 \ub54c \ub2e4\ub978 \ube44\uad50\ub97c \uc2dc\uc791\ud574\uc57c \ud588\ub2e4. \uad00\ucc30\ub41c \ucc28\uc774 \ud558\ub098\uac00 \uace7\ubc14\ub85c \uc6d0\uc778\uc744 \uc54c\ub824 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub450 \uc9d1\ub2e8\uc758 \ud658\uacbd\uacfc \ud658\uc790, \uc5c5\ubb34\uac00 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uadf8\ub798\ub3c4 \ucc28\uc774\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubb34\uc2dc\ud558\uc9c0 \uc54a\ub294 \uac83\uc740 \ucd9c\ubc1c\uc810\uc774 \ub41c\ub2e4. \uad8c\uc704 \uc788\ub294 \uc0ac\ub78c\uc774 \ub3cc\ubcf8\ub2e4\ub294 \uc124\uba85\ubcf4\ub2e4 \uc2e4\uc81c \uacb0\uacfc\uac00 \ubb34\uc5c7\uc744 \ubcf4\uc5ec \uc8fc\ub294\uc9c0 \uba3c\uc800 \ubcf4\ub824\ub294 \ud0dc\ub3c4\uc600\ub2e4. \ub2f9\uc2dc \uc758\ud559\uc0dd\ub4e4\uc740 \ud574\ubd80\uc5d0 \ucc38\uc5ec\ud55c \ub4a4 \uc0b0\ubaa8\ub97c \uc9c4\ucc30\ud558\uae30\ub3c4 \ud588\ub2e4. \uc624\ub298\uc758 \uac10\uc5fc \uad00\ub9ac \uae30\uc900\uc744 \uc804\uc81c\ub85c \uc0bc\uc73c\uba74 \ub180\ub78d\uc9c0\ub9cc \uadf8 \uc2dc\ub300\uc5d0\ub294 \uc9c8\ubcd1\uc774 \uc62e\ub294 \ubc29\uc2dd\uc774 \ucda9\ubd84\ud788 \uc774\ud574\ub418\uc9c0 \uc54a\uc558\ub2e4. \uac19\uc740 \uc190\uc774 \uc11c\ub85c \ub2e4\ub978 \uc77c\uc744 \uc5f0\uc18d\ud574\uc11c \uc218\ud589\ud55c\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc9c0\uae08\uacfc \ub2e4\ub978 \uc758\ubbf8\ub97c \uac00\uc84c\ub358 \uac83\uc774\ub2e4. \uc81c\uba5c\ubc14\uc774\uc2a4\ub294 \uc774 \ub3d9\uc120\uc5d0 \uc8fc\ubaa9\ud588\ub2e4. \ud658\uc790\uc758 \ubab8\uc5d0\uc11c\ub9cc \ubcd1\uc758 \uc6d0\uc778\uc744 \ucc3e\ub294 \ub300\uc2e0 \uc758\ub8cc\uc9c4\uc774 \ubb34\uc5c7\uc744 \uc62e\uae38 \uc218 \uc788\ub294\uc9c0 \ubb3c\uc5c8\ub2e4. \ubcd1\ub3d9 \uc548\uc758 \ubb38\uc81c\ub97c \ubcd1\ub3d9\uc5d0 \ub4e4\uc5b4\uc624\uae30 \uc804\uc758 \ud589\ub3d9\uacfc \uc5f0\uacb0\ud55c \uc148\uc774\ub2e4. \ub208\uc55e\uc758 \ud658\uc790\ub97c \uc798 \uc0b4\ud3b4\ubcf4\ub294 \uc77c\uacfc \uc9c4\ub8cc\uc758 \uc21c\uc11c\ub97c \uc798 \uc0b4\ud3b4\ubcf4\ub294 \uc77c\uc774 \ud568\uaed8 \ud544\uc694\ud574\uc84c\ub2e4. \ud574\ubd80 \uc911 \uc0dd\uae34 \uc0c1\ucc98 \ub4a4 \uac10\uc5fc\uc73c\ub85c \ub3d9\ub8cc \uc758\uc0ac\uac00 \uc0ac\ub9dd\ud55c \uc77c\ub3c4 \uc81c\uba5c\ubc14\uc774\uc2a4\uc758 \uc0dd\uac01\uc5d0 \uc601\ud5a5\uc744 \uc8fc\uc5c8\ub2e4. \uadf8 \uacbd\uacfc\uac00 \uc0b0\uc695\uc5f4\ub85c \uc228\uc9c4 \ud658\uc790\uc758 \ubaa8\uc2b5\uacfc \ub2ee\uc558\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud588\ub2e4. \ucd9c\uc0b0\ud558\ub294 \uc0ac\ub78c\uacfc \ud574\ubd80\ud558\ub294 \uc758\uc0ac\ub77c\ub294 \uc11c\ub85c \ub2e4\ub978 \uc704\uce58\uc5d0\uc11c \ube44\uc2b7\ud55c \ubb38\uc81c\uac00 \uc0dd\uae38 \uc218 \uc788\ub2e4\ub294 \ub2e8\uc11c\uc600\ub2e4. \ub450 \uc0ac\ub840\uac00 \ub2ee\uc558\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc6d0\uc778\uc744 \ud655\uc778\ud588\ub2e4\uace0 \ud560 \uc218\ub294 \uc5c6\ub2e4. \uadf8\ub7ec\ub098 \ud574\ubd80\uc5d0\uc11c \uc5b4\ub5a4 \uac83\uc774 \uc62e\uaca8\uc838 \uc9c8\ubcd1\uc744 \uc77c\uc73c\ud0ac \uc218 \uc788\ub2e4\ub294 \ucd94\ub860\uc744 \ub4b7\ubc1b\uce68\ud588\ub2e4. \ubc1c\uacac\uc740 \ud55c \ubc88\uc758 \ubc88\ub729\uc784\uc73c\ub85c \ub05d\ub098\ub294 \ub300\uc2e0 \uc5ec\ub7ec \uad00\ucc30\uc744 \uc5f0\uacb0\ud558\uba70 \ub354 \uad6c\uccb4\uc801\uc778 \uc9c8\ubb38\uc73c\ub85c \ub2e4\ub4ec\uc5b4\uc9c0\ub294 \uacfc\uc815\uc774\uc5c8\ub2e4. \uc81c\uba5c\ubc14\uc774\uc2a4\ub294 \uc5fc\uc18c \uc131\ubd84\uc758 \uc11d\ud68c\uc218\ub97c \uc774\uc6a9\ud55c \uc190 \uc138\ucc99\uc744 \uc2dc\ud589\ud558\ub3c4\ub85d \ud588\ub2e4. \uadf8 \ub4a4 \uc758\uc0ac\ub4e4\uc774 \ub3cc\ubcf4\ub294 \ubcd1\ub3d9\uc758 \uc0b0\ubaa8 \uc0ac\ub9dd\uc774 \ud06c\uac8c \uc904\uc5c8\ub2e4. \uc911\uc694\ud55c \uc810\uc740 \uc190\uc744 \uae68\ub057\uc774 \ud558\uc790\ub294 \uc88b\uc740 \ub9c8\uc74c\ub9cc \ub9d0\ud55c \uac83\uc774 \uc544\ub2c8\ub77c \uc2e4\uc81c \uc9c4\ub8cc \uacfc\uc815\uc5d0\uc11c \ud589\ub3d9\uc744 \ubc14\uafb8\uace0 \uacb0\uacfc\ub97c \uc0b4\ud3c8\ub2e4\ub294 \uac83\uc774\ub2e4. \uc774 \uc774\uc57c\uae30\ub97c \ud604\ub300\uc758 \uac1c\uc778 \uc704\uc0dd \uc694\ub839\uc774\ub098 \uc9d1\uc5d0\uc11c \uc18c\ub3c5\uc561\uc744 \ub9cc\ub4dc\ub294 \ubc29\ubc95\uc73c\ub85c \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2f9\uc2dc\uc758 \uac1c\uc785\uacfc \uadf8 \ub4a4\uc758 \ubcc0\ud654\ub97c \ub2e4\ub8e8\ub294 \uc5ed\uc0ac\ub2e4. \uc624\ub298\uc758 \uac10\uc5fc \uad00\ub9ac\ub294 \uc774\ud6c4 \ucd95\uc801\ub41c \uc5f0\uad6c\uc640 \ub2e4\ub978 \uae30\uc900\uc5d0 \ubc14\ud0d5\uc744 \ub454\ub2e4. \uc624\ub798\ub41c \ubc1c\uacac\uc744 \uc774\ud574\ud558\ub294 \uac83\uacfc \ud604\uc7ac\uc758 \uc758\ub8cc \uc9c0\uce68\uc744 \ub300\uc2e0\ud558\ub294 \uac83\uc740 \ub2e4\ub978 \uc77c\uc774\ub2e4. \uc81c\uba5c\ubc14\uc774\uc2a4\uac00 \uc624\ub298\uc758 \ubbf8\uc0dd\ubb3c\ud559\ucc98\ub7fc \uc6d0\uc778\uc744 \uc644\uc804\ud788 \uc124\uba85\ud55c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uadf8\ub7f0\ub370\ub3c4 \uc190\uc744 \ud1b5\ud574 \ubb34\uc5c7\uc778\uac00 \uc62e\uaca8\uc9c8 \uc218 \uc788\ub2e4\ub294 \ucd94\ub860\uacfc \uad00\ucc30\uc5d0 \uadfc\uac70\ud574 \uc720\uc6a9\ud55c \ubcc0\ud654\ub97c \ub9cc\ub4e4\uc5c8\ub2e4. \uc124\uba85\uc774 \ubd88\uc644\uc804\ud558\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc544\ubb34\uac83\ub3c4 \ud655\uc778\ud558\uc9c0 \ubabb\ud588\ub2e4\ub294 \uc8fc\uc7a5\uc740 \uac19\uc740 \ub9d0\uc774 \uc544\ub2c8\ub2e4. \ubb3c\ub860 \uc6d0\ub9ac\ub97c \ubaa8\ub978 \ucc44 \ud6a8\uacfc\uac00 \uc788\ub2e4\uace0 \uc8fc\uc7a5\ud558\ub294 \ubaa8\ub4e0 \ubc29\ubc95\uc774 \uc815\ub2f9\ud574\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \ube44\uad50\ub97c \ud588\uace0 \uacb0\uacfc\uac00 \uc5b4\ub5bb\uac8c \ub2ec\ub77c\uc84c\ub294\uc9c0, \ub2e4\ub978 \uc6d0\uc778\uc740 \ubb34\uc5c7\uc77c\uc9c0 \uacc4\uc18d \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uc81c\uba5c\ubc14\uc774\uc2a4\uc758 \uc0ac\ub840\ub294 \uc99d\uac70\uc640 \uc124\uba85\uc774 \ud55c \ubc88\uc5d0 \uac19\uc740 \uc218\uc900\uc73c\ub85c \uc644\uc131\ub418\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4\ub294 \uc810\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc131\uacfc\uac00 \uc788\uc5c8\ub2e4\uace0 \uad00\ud589\uc774 \uace7\ubc14\ub85c \ubc14\ub00c\uc9c0\ub294 \uc54a\uc558\ub2e4. \uc758\ub8cc\uc9c4\uc758 \ud589\ub3d9\uc774 \ud658\uc790\uc758 \uc8fd\uc74c\uacfc \uc5f0\uacb0\ub420 \uc218 \uc788\ub2e4\ub294 \ub9d0\uc740 \ub2f9\uc2dc\uc758 \uc0c1\uc2dd\uacfc \uad8c\uc704\ub97c \uac74\ub4dc\ub838\ub2e4. OpenStax\ub294 \uc190 \uc53b\uae30\uac00 \ub110\ub9ac \ubc1b\uc544\ub4e4\uc5ec\uc9c0\ub294 \ub370 \uc800\ud56d\uc774 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc9c0\uc2dd\uc744 \ubc1c\uacac\ud558\ub294 \uc77c\uacfc \uc870\uc9c1\uc758 \uc2b5\uad00\uc744 \ubc14\uafb8\ub294 \uc77c \uc0ac\uc774\uc5d0\ub294 \uac70\ub9ac\uac00 \uc788\uc5c8\ub2e4. \uc774\uac83\uc744 \uc61b \uc758\uc0ac\ub4e4\uc740 \ubaa8\ub450 \uc5b4\ub9ac\uc11d\uc5c8\ub2e4\ub294 \uad50\ud6c8\uc73c\ub85c\ub9cc \ub05d\ub0b4\uba74 \uc790\uc2e0\uc744 \ub3cc\uc544\ubcfc \uae30\ud68c\uac00 \uc0ac\ub77c\uc9c4\ub2e4. \uc775\uc219\ud55c \ubc29\uc2dd\uc73c\ub85c \uc131\uc2e4\ud558\uac8c \uc77c\ud558\ub294 \uc0ac\ub78c\ub3c4 \uadf8 \ubc29\uc2dd\uc774 \ub0b3\ub294 \ubb38\uc81c\ub97c \ubc1b\uc544\ub4e4\uc774\uae30 \uc5b4\ub824\uc6b8 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \ubc18\ub300\uc758 \uc774\uc720\ub97c \ud55c \uac00\uc9c0 \uc2ec\ub9ac\ub85c \ub2e8\uc815\ud558\uc9c0 \uc54a\ub294 \uac83\ub3c4 \uc911\uc694\ud558\ub2e4. \uc2dc\ub300\uc758 \uc9c0\uc2dd\uacfc \uc81c\ub3c4\uc801 \uc870\uac74\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc81c\uba5c\ubc14\uc774\uc2a4\uc758 \ucd08\uc0c1\uc744 \ubcf4\uba70 \uc720\uba85\ud55c \uc774\ub984 \ud558\ub098\ub97c \uc678\uc6b0\ub294 \ub370\uc11c \uba48\ucd94\uc9c0 \uc54a\uc544\ub3c4 \uc88b\ub2e4. \uadf8\uac00 \ubc14\uafbc \uc9c8\ubb38\uc744 \uae30\uc5b5\ud560 \uc218 \uc788\ub2e4. \ud658\uc790\uc5d0\uac8c \ubb34\uc5c7\uc774 \uc788\ub294\uc9c0\uc640 \ud568\uaed8, \uc758\ub8cc\uc9c4\uc758 \uc190\uc774 \uc5b4\ub514\uc5d0\uc11c \uc654\ub294\uc9c0\ub97c \ubb3c\uc5c8\ub2e4. \uc9c4\ub8cc\uc758 \uc911\uc2ec\uc5d0 \uc788\ub358 \uc0ac\ub78c\uc774 \uc9c8\ubcd1 \uc804\ub2ec\uc758 \uacbd\ub85c\uac00 \ub420 \uc218\ub3c4 \uc788\ub2e4\ub294 \uc2dc\uc120\uc774\uc5c8\ub2e4. \uc791\uc740 \ud589\ub3d9\uc774 \uc911\uc694\ud574\uc84c\ub2e4\ub294 \ub9d0 \ub4a4\uc5d0\ub294 \ube44\uad50\uc640 \uad00\ucc30, \uac1c\uc785\uacfc \ud655\uc778\uc758 \uacfc\uc815\uc774 \uc788\uc5c8\ub2e4. \uc624\ub298\uc758 \uc775\uc219\ud55c \uc190 \uc53b\uae30\uc5d0\uc11c \uadf8 \uc2dc\uac04\uc744 \ub5a0\uc62c\ub824 \ubcf4\uba74 \ub2f9\uc5f0\ud55c \uaddc\uce59\ub3c4 \ucc98\uc74c\ubd80\ud130 \ub2f9\uc5f0\ud588\ub358 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc0ac\uc2e4\uc774 \ub0a8\ub294\ub2e4. \ub354 \uc88b\uc740 \uce58\ub8cc\ub294 \uc0c8\ub85c\uc6b4 \ub3c4\uad6c\ub97c \ub4e4\uc774\ub294 \uc77c\ubfd0 \uc544\ub2c8\ub77c \uc774\ubbf8 \ud558\ub294 \uc77c\uc744 \ub2e4\uc2dc \uc0b4\ud53c\ub294 \ub370\uc11c \uc2dc\uc791\ub418\uae30\ub3c4 \ud588\ub2e4."}, {"id": "soap-water-and-oily-plate", "title": "\ube44\ub204 \u2014 \ubb3c\uacfc \uae30\ub984 \uc0ac\uc774\uc5d0 \ub2e4\ub9ac\ub97c \ub193\ub2e4", "summary": "\uc124\uac70\uc9c0\uc758 \uc7a5\uba74\uc5d0\uc11c \ube44\ub204 \ubd84\uc790\uc758 \uc11c\ub85c \ub2e4\ub978 \ubd80\ubd84\uacfc \uae30\ub984\ubc29\uc6b8\uc758 \ubd84\uc0b0\uc744 \uc27d\uac8c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\ubb3c\uc9c8\uacfc \uc5d0\ub108\uc9c0", "categories": ["science"], "url": "stories/soap-water-and-oily-plate/index.html", "image": "../media/soap-water-and-oily-plate.png", "alt": "\uc8fc\ubc29 \uc2f1\ud06c\ub300\uc5d0\uc11c \ube44\ub204 \uac70\ud488\uacfc \uc218\uc138\ubbf8\ub85c \uae30\ub984 \ubb3b\uc740 \uc811\uc2dc\ub97c \uc53b\ub294 \uc190\uc758 \uc0bd\ud654.", "text": "\ube44\ub204 \u2014 \ubb3c\uacfc \uae30\ub984 \uc0ac\uc774\uc5d0 \ub2e4\ub9ac\ub97c \ub193\ub2e4 \uae30\ub984\ub54c\uac00 \uc0ac\ub77c\uc9c0\ub294 \uac83\uacfc \ubb3c\uc5d0 \uc53b\uaca8 \ub098\uac00\ub294 \uac83 \uc124\uac70\uc9c0\uc758 \uc7a5\uba74\uc5d0\uc11c \ube44\ub204 \ubd84\uc790\uc758 \uc11c\ub85c \ub2e4\ub978 \ubd80\ubd84\uacfc \uae30\ub984\ubc29\uc6b8\uc758 \ubd84\uc0b0\uc744 \uc27d\uac8c \uc77d\uc2b5\ub2c8\ub2e4. \ubb3c\uc9c8\uacfc \uc5d0\ub108\uc9c0 \uacfc\ud559\uacfc \ubc1c\uacac \uae30\ub984 \ubb3b\uc740 \uc811\uc2dc\uc5d0 \ubb3c\uc744 \ud758\ub824\ubcf4\ub0b8\ub2e4. \ubb3c\ubc29\uc6b8\uc740 \uc9c0\ub098\uac00\uc9c0\ub9cc \ubbf8\ub048\ud55c \ub290\ub08c\uc740 \ub0a8\ub294\ub2e4. \uadf8\ub7f0\ub370 \ube44\ub204\ub098 \uc138\uc81c\ub97c \uc870\uae08 \uc4f0\uace0 \ubb38\uc9c0\ub974\uba74 \uc0c1\ud0dc\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \ubb3c\uacfc \uc798 \uc11e\uc774\uc9c0 \uc54a\ub294 \uae30\ub984\uc744 \ubb34\uc5c7\uc774 \uc6c0\uc9c1\uc774\uac8c \ud55c \uac83\uc77c\uae4c. \uc774 \uc7a5\uba74\uc5d0\ub294 \uc791\uc740 \ubd84\uc790\uc758 \uc11c\ub85c \ub2e4\ub978 \uc131\uc9c8\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ubb3c\uacfc \uc798 \uc5b4\uc6b8\ub9ac\ub294 \ubd80\ubd84\uacfc \uae30\ub984 \ucabd\uc5d0 \ub04c\ub9ac\ub294 \ubd80\ubd84\uc774 \ud55c \ubd84\uc790 \uc548\uc5d0 \uc788\ub2e4. \ube44\ub204\ub294 \ub450 \uc138\uacc4 \uc0ac\uc774\uc5d0\uc11c \uc791\uc6a9\ud558\uba70 \uae30\ub984\uc774 \ubb3c\uacfc \ud568\uaed8 \uc774\ub3d9\ud560 \uc218 \uc788\ub294 \uc0c1\ud0dc\ub97c \ub9cc\ub4dc\ub294 \ub370 \ub3c4\uc6c0\uc744 \uc900\ub2e4. \ubb3c\uacfc \uae30\ub984\uc744 \uc11e\uc73c\ub824 \ud754\ub4e4\uba74 \uc7a0\uc2dc \uc791\uc740 \ubc29\uc6b8\ub4e4\uc774 \uc0dd\uae38 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uadf8\ub300\ub85c \ub450\uba74 \ub2e4\uc2dc \uce35\uc744 \uc774\ub8e8\uae30 \uc27d\ub2e4. \uad50\uc7ac\ub294 \uc11c\ub85c \uc798 \uc11e\uc774\uc9c0 \uc54a\ub294 \uc561\uccb4\uc758 \uc608\ub85c \ubb3c\uacfc \uae30\ub984\uc744 \uc124\uba85\ud55c\ub2e4. \ud754\ub4e4\uc5b4\uc11c \ub098\ub204\uc5b4 \ub193\ub294 \uc77c\uacfc \uc548\uc815\uc801\uc73c\ub85c \uc11e\uc5ec \uc788\uac8c \ud558\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \ubb3c\uacfc \uae30\ub984\uc758 \ubd84\uc790 \uc0ac\uc774\uc5d0 \uc791\uc6a9\ud558\ub294 \ud798\uc774 \uc11c\ub85c \ub2e4\ub978 \uac83\uc774 \uc911\uc694\ud55c \uc774\uc720\ub2e4. \ud55c\ucabd\uc774 \ub2e4\ub978 \ucabd\uc744 \uc2eb\uc5b4\ud55c\ub2e4\ub294 \ud45c\ud604\uc740 \uae30\uc5b5\ud558\uae30 \ud3b8\ud55c \ube44\uc720\uc9c0\ub9cc \uc2e4\uc81c \uac10\uc815\uc774 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubd84\uc790\ub4e4\uc774 \uc8fc\ubcc0\uacfc \ub9fa\ub294 \uc0c1\ud638\uc791\uc6a9\uc758 \ucc28\uc774\uac00 \ud070 \ub369\uc5b4\ub9ac\uc758 \uc131\uc9c8\ub85c \ub098\ud0c0\ub09c\ub2e4\uace0 \uc774\ud574\ud558\uba74 \uc88b\ub2e4. OpenStax\ub294 \ube44\ub204 \ubd84\uc790\uc5d0 \uae34 \ud0c4\ud654\uc218\uc18c \ubd80\ubd84\uacfc \ubb3c\uc5d0 \ub04c\ub9ac\ub294 \uc774\uc628\uc131 \ubd80\ubd84\uc774 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc27d\uac8c \ub9d0\ud558\uba74 \uae30\ub984\uacfc \uc5b4\uc6b8\ub9ac\uae30 \uc88b\uc740 \ubd80\ubd84, \ubb3c\uacfc \uc0c1\ud638\uc791\uc6a9\ud558\uae30 \uc88b\uc740 \ubd80\ubd84\uc774 \uc774\uc5b4\uc838 \uc788\ub2e4. \uc804\uccb4\ub97c \ud55c \uac00\uc9c0 \uc131\uc9c8\ub85c\ub9cc \ubd80\ub974\uae30 \uc5b4\ub824\uc6b4 \uad6c\uc870\ub2e4. \uc774 \ub54c\ubb38\uc5d0 \ube44\ub204\ub294 \ubb3c\uacfc \uae30\ub984\uc758 \uacbd\uacc4\uc5d0\uc11c \uc5ed\ud560\uc744 \ud560 \uc218 \uc788\ub2e4. \ubaa8\ub4e0 \ubd84\uc790\uc758 \uc774\ub984\uacfc \ud654\ud559\uc2dd\uc744 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4. \uc911\uc694\ud55c \uc810\uc740 \uc11c\ub85c \ub2e4\ub978 \uc131\uc9c8\uc774 \ud55c\uacf3\uc5d0 \uc5f0\uacb0\ub418\uc5b4 \uc788\ub2e4\ub294 \uac83\uc774\ub2e4. \uc791\uc740 \uad6c\uc870\uc758 \ucc28\uc774\uac00 \uc190\uc73c\ub85c \ub290\ub07c\ub294 \uc124\uac70\uc9c0\uc758 \uacb0\uacfc\uc5d0\uae4c\uc9c0 \uc774\uc5b4\uc9c4\ub2e4. \ube44\ub204 \ubd84\uc790\uc758 \uae30\ub984\uacfc \uc5b4\uc6b8\ub9ac\ub294 \ubd80\ubd84\uc740 \uae30\ub984 \ucabd\uc73c\ub85c, \ubb3c\uacfc \uc798 \uc0c1\ud638\uc791\uc6a9\ud558\ub294 \ubd80\ubd84\uc740 \ubb3c \ucabd\uc73c\ub85c \ub193\uc77c \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc774\ub97c \uc11c\ub85c \ub2e4\ub978 \ub450 \uc885\ub958\uc758 \ubb3c\uc9c8 \uc0ac\uc774\uc5d0 \ub2e4\ub9ac\ub97c \ub193\ub294 \ubaa8\uc2b5\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \uae30\ub984\ubc29\uc6b8\uc758 \ubc14\uae65\uc5d0 \ubb3c\uacfc \ub9cc\ub098\ub294 \uc870\uac74\uc774 \uc0dd\uae30\ub294 \uac83\uc774\ub2e4. \uadf8 \uacb0\uacfc \uae30\ub984\ub54c\uac00 \uc791\uc740 \ubc29\uc6b8\ub85c \ubb3c\uc18d\uc5d0 \ubd84\uc0b0\ub418\uc5b4 \uc53b\uaca8 \ub098\uac00\uae30 \uc26c\uc6cc\uc9c4\ub2e4. \uae30\ub984\uc774 \uac11\uc790\uae30 \ubb3c \ubd84\uc790\ub85c \ubc14\ub00c\uac70\ub098 \uc138\uc0c1\uc5d0\uc11c \uc0ac\ub77c\uc84c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \ud615\ud0dc\ub85c \uc8fc\ubcc0\uc5d0 \uc874\uc7ac\ud558\uace0 \ubb34\uc5c7\uacfc \ud568\uaed8 \uc774\ub3d9\ud560 \uc218 \uc788\ub294\uc9c0\uac00 \ub2ec\ub77c\uc9c4 \uac83\uc774\ub2e4. \uc81c\uac70\uc640 \ubcc0\ud658\uc744 \uad6c\ubcc4\ud558\uba74 \uc791\ub3d9\uc774 \ub354 \uc798 \ubcf4\uc778\ub2e4. \uc138\uc81c\uc758 \ubd84\uc790\ub9cc \ub5a0\uc62c\ub9ac\uba74 \uc124\uac70\uc9c0\uac00 \uc800\uc808\ub85c \ub05d\ub0a0 \uac83 \uac19\uc9c0\ub9cc \uc2e4\uc81c \uacfc\uc815\uc5d0\ub294 \uc6c0\uc9c1\uc784\ub3c4 \uc788\ub2e4. \ubb38\uc9c0\ub974\uace0 \ud5f9\uad6c\uba74\uc11c \ub5a8\uc5b4\uc9c4 \uae30\ub984\uacfc \uc624\uc5fc\ubb3c\uc774 \ub2e4\ub978 \uacf3\uc73c\ub85c \uc62e\uaca8 \uac04\ub2e4. \ubd84\uc790\uc758 \uc131\uc9c8\uacfc \ubb3c\ub9ac\uc801\uc778 \uc791\uc5c5\uc740 \uac19\uc740 \uc7a5\uba74\uc5d0\uc11c \ud568\uaed8 \uc791\uc6a9\ud55c\ub2e4. \uc774\ubc88 \uae00\uc740 \ud2b9\uc815 \uc81c\ud488\uc758 \uc138\ucc99\ub825\uc744 \uc2dc\ud5d8\ud55c \uacb0\uacfc\uac00 \uc544\ub2c8\ub2e4. \uc811\uc2dc\uc758 \uc7ac\ub8cc\uc640 \uc624\uc5fc\uc758 \uc885\ub958, \ubb3c\uc758 \uc870\uac74\uc5d0 \ub530\ub77c \uc2e4\uc81c \uacb0\uacfc\ub294 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ubb3c\uacfc \uae30\ub984 \uc0ac\uc774\uc758 \uad00\uacc4\ub97c \ubc14\uafb8\ub294 \uc5ed\ud560\uc744 \uc774\ud574\ud558\uba74 \uc65c \ubb3c\ub9cc \uc4f8 \ub54c\uc640 \ub2e4\ub978 \uacbd\ud5d8\uc744 \ud558\ub294\uc9c0 \ud070 \ud750\ub984\uc744 \uc54c \uc218 \uc788\ub2e4. \uac70\ud488\uc774 \ub9ce\uc774 \ubcf4\uc774\uba74 \uc798 \uc53b\uae30\ub294 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c8 \ub54c\uac00 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ub208\uc5d0 \ubcf4\uc774\ub294 \uac70\ud488\uc758 \uc591\ub9cc\uc73c\ub85c \uae30\ub984\uc774 \uc5bc\ub9c8\ub098 \uc81c\uac70\ub418\uc5c8\ub294\uc9c0\ub97c \uc9c1\uc811 \uce21\uc815\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c \uc124\uba85\ud55c \ud575\uc2ec\uc740 \ubb3c\uacfc \uc624\uc5fc\ubb3c\uc758 \uacbd\uacc4\uc5d0\uc11c \ubd84\uc790\uac00 \uc5b4\ub5a4 \uc5ed\ud560\uc744 \ud558\ub294\uac00\uc5d0 \uc788\ub2e4. \uac70\ud488\uc740 \uae30\uccb4\uac00 \uc561\uccb4 \uc548\uc5d0 \ubd84\uc0b0\ub41c \uc0c1\ud0dc\ub85c \ubcfc \uc218 \uc788\uace0, \uae30\ub984\ubc29\uc6b8\uc774 \ubb3c\uc5d0 \ud37c\uc838 \uc788\ub294 \uc0c1\ud0dc\uc640\ub294 \ub2e4\ub978 \uad6c\ubd84\uc774\ub2e4. \uad50\uc7ac\ub294 \uc774\ub7f0 \uc5ec\ub7ec \ubd84\uc0b0 \uc0c1\ud0dc\ub97c \ucf5c\ub85c\uc774\ub4dc\ub77c\ub294 \ud2c0\uc5d0\uc11c \ud568\uaed8 \ub2e4\ub8ec\ub2e4. \ub2ee\uc544 \ubcf4\uc774\ub294 \ud604\uc0c1\ub3c4 \ubb34\uc5c7\uc774 \ubb34\uc5c7 \uc18d\uc5d0 \ud37c\uc838 \uc788\ub294\uc9c0 \ubb3c\uc73c\uba74 \uc11c\ub85c \ub2e4\ub978 \uad6c\uc870\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \uce7c\uc298\uacfc \ub9c8\uadf8\ub124\uc298 \uc774\uc628\uc774 \ub9ce\uc740 \uacbd\uc218\uc5d0\uc11c\ub294 \ube44\ub204\uac00 \uc798 \ub179\uc9c0 \uc54a\ub294 \ubb3c\uc9c8\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 \ud569\uc131 \uc138\uc81c\uac00 \uc774\ub7f0 \uc870\uac74\uc5d0\uc11c \uac16\ub294 \ucc28\uc774\ub97c \uc124\uba85\ud55c\ub2e4. \uac19\uc740 \ube44\ub204\ub97c \uc368\ub3c4 \ubb3c\uc758 \uc870\uac74\uc5d0 \ub530\ub77c \uacbd\ud5d8\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub294 \uc774\uc720 \uac00\uc6b4\ub370 \ud558\ub098\ub2e4. \ub530\ub77c\uc11c \ube44\ub204\uc640 \uc138\uc81c\ub97c \ubaa8\ub4e0 \uc0c1\ud669\uc5d0\uc11c \uac19\uc740 \uac83\uc73c\ub85c \ubb49\ub6b1\uadf8\ub9ac\uae30\ub3c4 \uc5b4\ub835\ub2e4. \ube44\uc2b7\ud55c \uc77c\uc744 \ud558\ub3c4\ub85d \ub9cc\ub4e4\uc5b4\uc84c\uc9c0\ub9cc \ubd84\uc790 \uad6c\uc870\uc640 \ubb3c\uc18d\uc758 \ubc18\uc751\uc740 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc774\ubc88\uc5d0\ub294 \ud2b9\uc815 \uc81c\ud488\uc744 \ube44\uad50\ud558\uae30\ubcf4\ub2e4 \ubb3c\uc774\ub77c\ub294 \ubc30\uacbd\ub3c4 \uc791\ub3d9 \uc870\uac74\uc758 \uc77c\ubd80\ub77c\ub294 \uc810\uc744 \uae30\uc5b5\ud558\uba74 \ucda9\ubd84\ud558\ub2e4. \ubb3c\uc18d\uc5d0 \uc791\uc740 \ubc29\uc6b8\ub85c \ud37c\uc838 \uc788\ub2e4\uace0 \ubc18\ub4dc\uc2dc \ubd84\uc790 \uc218\uc900\uc5d0\uc11c \ubaa8\ub450 \ub179\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \uad50\uc7ac\ub294 \uc720\ud654\uc640 \uc6a9\ud574\ub97c \uad6c\ubd84\ud574 \uc124\uba85\ud55c\ub2e4. \uc6b0\uc720\ub098 \ub9c8\uc694\ub124\uc988 \uac19\uc740 \uc77c\uc0c1\uc758 \ud63c\ud569\ubb3c\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc131\ubd84\uc774 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \ubd84\uc0b0\ub418\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uae30\ub984 \ubb3b\uc740 \uc811\uc2dc\ub97c \uc53b\ub294 \uc77c\ubc18\uc801\uc778 \uc7a5\uba74\uc774\ub2e4. \ube44\ub204 \ubd84\uc790\uc758 \uc2e4\uc81c \ubaa8\uc2b5\uc774\ub098 \ud604\ubbf8\uacbd \uad00\ucc30 \uacb0\uacfc\ub97c \ubcf4\uc5ec \uc8fc\ub294 \ub3c4\uc2dd\uc740 \uc544\ub2c8\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \uc124\uac70\uc9c0\uc640 \ub208\uc5d0 \ubcf4\uc774\uc9c0 \uc54a\ub294 \ubd84\uc790\uc758 \uc124\uba85\uc744 \uc5f0\uacb0\ud558\ub294 \ubd84\uc704\uae30 \uadf8\ub9bc\uc774\ub2e4. \uc124\uac70\uc9c0\uac00 \ub05d\ub098\uba74 \uc811\uc2dc\ub9cc \ubcf4\uace0 \uae68\ub057\ud574\uc84c\ub2e4\uace0 \ub9d0\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uacfc\ud559\uc758 \uc9c8\ubb38\uc740 \uae30\ub984\uc774 \uc5b4\ub5a4 \uc0c1\ud0dc\uac00 \ub418\uc5b4 \uc5b4\ub514\ub85c \uc62e\uaca8 \uac14\ub294\uc9c0\uae4c\uc9c0 \uc774\uc5b4\uc9c8 \uc218 \uc788\ub2e4. \ube44\ub204\uc758 \uc5ed\ud560\uc740 \ubb3c\uacfc \uae30\ub984\uc744 \uc804\ud600 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ub9cc\ub098\uac8c \ud574 \uc774\ub3d9\uc744 \ub3d5\ub294 \ub370 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \ubb3c\ub9cc\uc73c\ub85c \ub0a8\uc544 \uc788\ub358 \uae30\ub984\uc774 \uc138\uc81c\uc640 \ud568\uaed8 \uc53b\uaca8 \ub098\uac00\ub294 \ubaa8\uc2b5\uc744 \ubcf4\uba74 \uc791\uc740 \ubd84\uc790\uc758 \ub450 \ubd80\ubd84\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ubb3c\uacfc \uac00\uae4c\uc6cc\uc9c0\ub294 \ucabd\uacfc \uae30\ub984\uc5d0 \uac00\uae4c\uc6cc\uc9c0\ub294 \ucabd\uc774 \uc5f0\uacb0\ub418\uc5b4 \uc788\ub2e4. \ubd84\uc790 \ud558\ub098\uc758 \uad6c\uc870\uac00 \uc77c\uc0c1\uc758 \ubc88\uac70\ub85c\uc6b4 \uc77c\uc744 \ubc14\uafb8\ub294 \uacfc\uc815\uc774 \uc190\ub05d\uc5d0\uc11c \uc77c\uc5b4\ub098\uace0 \uc788\ub294 \uc148\uc774\ub2e4."}, {"id": "spectroscope-dark-lines-and-elements", "title": "\ubd84\uad11\uae30 \u2014 \ubcc4\ube5b\uc758 \ube48\ud2c8\uc5d0\uc11c \ubb3c\uc9c8\uc758 \ud754\uc801\uc744 \uc77d\ub2e4", "summary": "\uac00\ub294 \uc120\uc744 \uae30\ub85d\ud55c \uad11\ud559 \uae30\uae30\uc640 \uc2e4\ud5d8\uc2e4 \uae30\uc900\uc774 \ubcc4\uc758 \ubb3c\uc9c8\uc744 \ucd94\ub860\ud558\ub294 \ubc29\ubc95\uc73c\ub85c \uc774\uc5b4\uc9c4 \uacfc\uc815\uc744 \ubd05\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uc6b0\uc8fc\uc640 \ucc9c\ubb38", "categories": ["science"], "url": "stories/spectroscope-dark-lines-and-elements/index.html", "image": "../media/spectroscope-dark-lines-and-elements.jpg", "alt": "\ub124 \ud504\ub9ac\uc998\uacfc \ub450 \uad00, \ube5b\uc744 \ub4e4\uc774\ub294 \ud2c8\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc5ed\uc0ac \ubd84\uad11\uae30 \ub3c4\ud310", "text": "\ubd84\uad11\uae30 \u2014 \ubcc4\ube5b\uc758 \ube48\ud2c8\uc5d0\uc11c \ubb3c\uc9c8\uc758 \ud754\uc801\uc744 \uc77d\ub2e4 \ud504\ub77c\uc6b4\ud638\ud37c\uc758 \uc120\uc5d0\uc11c \uc2e4\ud5d8\uc2e4\uacfc \ucc9c\ubb38\ud559\uc758 \ube44\uad50\ub85c \uac00\ub294 \uc120\uc744 \uae30\ub85d\ud55c \uad11\ud559 \uae30\uae30\uc640 \uc2e4\ud5d8\uc2e4 \uae30\uc900\uc774 \ubcc4\uc758 \ubb3c\uc9c8\uc744 \ucd94\ub860\ud558\ub294 \ubc29\ubc95\uc73c\ub85c \uc774\uc5b4\uc9c4 \uacfc\uc815\uc744 \ubd05\ub2c8\ub2e4. \uc6b0\uc8fc\uc640 \ucc9c\ubb38 \uacfc\ud559\uacfc \ubc1c\uacac \ud0dc\uc591\uc5d0 \uac00\uc11c \ud45c\ubcf8\uc744 \uac00\uc838\uc624\uc9c0 \uc54a\uace0 \ubb34\uc5c7\uc73c\ub85c \uc774\ub8e8\uc5b4\uc84c\ub294\uc9c0 \uc54c\uc544\ub0bc \uc218 \uc788\uc744\uae4c. \ube5b\uc744 \uc0c9\uc73c\ub85c \ub098\ub204\uc5b4 \uc0b4\ud53c\ub294 \ubd84\uad11\ud559\uc740 \uc774\ub7f0 \uc9c8\ubb38\uc5d0 \uc0c8\ub85c\uc6b4 \uae38\uc744 \uc5f4\uc5c8\ub2e4. \ubb34\uc9c0\uac1c \uac19\uc740 \ub760\uc758 \uc544\ub984\ub2e4\uc6c0\ubcf4\ub2e4 \uadf8 \uc548\uc758 \uc120\uacfc \ube48\ud2c8\uc774 \uc911\uc694\ud55c \uc790\ub8cc\uac00 \ub418\uc5c8\ub2e4. \uad00\uce21 \uc7a5\uce58\uc640 \uc2e4\ud5d8\uc2e4\uc758 \ube44\uad50\uac00 \uba3c \uc138\uacc4\ub97c \uc77d\ub294 \ubc29\ubc95\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uc5ed\uc0ac\ub2e4. \ud504\ub9ac\uc998\uc740 \ube5b\uc758 \uc5ec\ub7ec \ud30c\uc7a5 \uc131\ubd84\uc744 \uc11c\ub85c \ub2e4\ub978 \ubc29\ud5a5\uc73c\ub85c \ub098\ub204\uc5b4 \ubcf4\uc5ec \uc900\ub2e4. \uadf8\ub7ec\ub098 \ud0dc\uc591\ube5b\uc744 \uc790\uc138\ud788 \uc0b4\ud53c\uba74 \uc5f0\uc18d\ub41c \uc0c9 \uc0ac\uc774\uc5d0 \uc5b4\ub450\uc6b4 \uc120\ub4e4\uc774 \ub098\ud0c0\ub09c\ub2e4. \ubb34\uc5b8\uac00 \uc798\ubabb \ube44\ucd98 \uc5bc\ub8e9\uc774 \uc544\ub2c8\ub77c \ubc18\ubcf5\ud574\uc11c \ub098\ud0c0\ub098\ub294 \ud2b9\uc9d5\uc774\uc5c8\ub2e4. \uc6d4\ub7ec\uc2a4\ud134\uc758 \uad00\ucc30\uacfc \ud504\ub77c\uc6b4\ud638\ud37c\uc758 \uccb4\uacc4\uc801\uc778 \uc870\uc0ac\ub85c \uc774\ub7f0 \uc120\ub4e4\uc744 \uad6c\ubcc4\ud558\uace0 \uae30\ub85d\ud558\ub294 \uc791\uc5c5\uc774 \uc9c4\ud589\ub418\uc5c8\ub2e4. \ubaa8\ub4e0 \uc120\uc758 \uc6d0\uc778\uc744 \ucc98\uc74c\ubd80\ud130 \uc54c\uace0 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uba3c\uc800 \ub2e4\ub978 \uad00\ucc30\uc790\uac00 \ube44\uad50\ud560 \uc218 \uc788\ub3c4\ub85d \uc704\uce58\uc640 \ubaa8\uc2b5\uc744 \ub0a8\uae30\ub294 \ub2e8\uacc4\uac00 \ud544\uc694\ud588\ub2e4. \ubd84\uad11\uae30\ub294 \ub2e8\uc21c\ud788 \ube5b\uc744 \uc608\uc058\uac8c \ud37c\ub728\ub9ac\ub294 \uc7a5\uce58\uc5d0 \uadf8\uce58\uc9c0 \uc54a\ub294\ub2e4. \ube5b\uc774 \ub4e4\uc5b4\uc624\ub294 \uac00\ub294 \ud2c8\uacfc \ub80c\uc988, \ube5b\uc744 \ub098\ub204\ub294 \ubd80\ubd84\uacfc \uad00\ucc30\ud558\ub294 \ubd80\ubd84\uc774 \uc5f0\uacb0\ub41c\ub2e4. \ube44\uc2b7\ud55c \uc7a5\uba74\uc744 \ubc18\ubcf5\ud574\uc11c \uc790\uc138\ud788 \ubcfc \uc218 \uc788\uc5b4\uc57c \uc120\uc758 \ucc28\uc774\uac00 \uc790\ub8cc\uac00 \ub41c\ub2e4. 1900\ub144 \uae30\uc220\uc0ac \ucc45\uc5d0 \uc2e4\ub9b0 \ud0a4\ub974\ud788\ud638\ud504\uc758 \ub124 \ud504\ub9ac\uc998 \uc7a5\uce58\ub294 \uc774\ub7f0 \uc5ed\ud560\uc758 \uc5f0\uacb0\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc5ec\ub7ec \ud504\ub9ac\uc998\uc744 \uac70\uccd0 \ubd84\uc0b0\uc2dc\ud0a4\uace0 \ub9dd\uc6d0\uacbd \ucabd\uc5d0\uc11c \uad00\ucc30\ud558\ub294 \uad6c\uc870\ub2e4. \uc774 \uc5ed\uc0ac \ub3c4\ud310\uc774 \uc624\ub298\uc758 \ubaa8\ub4e0 \ubd84\uad11\uae30\ub97c \ub300\ud45c\ud558\ub294 \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc, \uc7a5\uce58\uc758 \ubaa9\uc801\uc744 \uc774\ud574\ud558\ub294 \ub2e8\uc11c\uac00 \ub41c\ub2e4. \ubb3c\uc9c8\uc774 \ub0b4\ub294 \ube5b\uc5d0\ub294 \ud2b9\uc9d5\uc801\uc778 \uc120\uc758 \ubc30\uce58\uac00 \ub098\ud0c0\ub0a0 \uc218 \uc788\ub2e4. \uc2e4\ud5d8\uc2e4\uc5d0\uc11c \uc54c\ub824\uc9c4 \ubb3c\uc9c8\uc758 \ube5b\uc744 \uc0b4\ud53c\uace0, \uba3c \ucc9c\uccb4\uc5d0\uc11c \uc628 \ube5b\uacfc \ube44\uad50\ud558\uba74 \uad6c\uc131 \uc131\ubd84\uc744 \ucd94\ub860\ud560 \uc218 \uc788\ub2e4. \uc9c1\uc811 \uac00\uc838\uc628 \ud45c\ubcf8 \ub300\uc2e0 \ub3c4\ucc29\ud55c \ube5b\uc774 \uc790\ub8cc\uac00 \ub41c \uac83\uc774\ub2e4. \ud0a4\ub974\ud788\ud638\ud504\uc640 \ubd84\uc820\uc758 \uc5f0\uad6c\ub294 \uc774\ub7f0 \ube44\uad50\ub97c \ud654\ud559 \ubd84\uc11d\uacfc \uc5f0\uacb0\ud558\ub294 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud588\ub2e4. \uae30\uae30 \ud558\ub098\ub97c \ubc1c\uba85\ud588\ub2e4\ub294 \uc774\uc57c\uae30\ub9cc\uc73c\ub85c\ub294 \ubcc0\ud654\uac00 \ucda9\ubd84\ud788 \uc124\uba85\ub418\uc9c0 \uc54a\ub294\ub2e4. \ubb34\uc5c7\uacfc \ubb34\uc5c7\uc744 \ube44\uad50\ud574\uc57c \ud558\ub294\uc9c0\uc5d0 \uad00\ud55c \uc9c8\ubb38\uc774 \uc7a5\uce58\uc640 \ud568\uaed8 \ubc1c\uc804\ud588\ub2e4. \ud2b9\uc815 \ud30c\uc7a5\uc758 \ube5b\uc774 \uc8fc\ubcc0\ubcf4\ub2e4 \uc57d\ud558\uac8c \ubcf4\uc77c \ub54c \uc5b4\ub450\uc6b4 \uc120\uc73c\ub85c \ub098\ud0c0\ub0a0 \uc218 \uc788\ub2e4. \ub354 \ub728\uac70\uc6b4 \uacf3\uc758 \uc5f0\uc18d\uc801\uc778 \ube5b\uc774 \uc0c1\ub300\uc801\uc73c\ub85c \ucc28\uac00\uc6b4 \ubb3c\uc9c8\uc744 \uc9c0\ub098\uba70 \uc77c\ubd80 \ud30c\uc7a5\uc774 \ud761\uc218\ub418\ub294 \uc0c1\ud669\uc774 \uadf8 \ud55c \uc608\ub2e4. \uc120\uc758 \ubaa8\uc2b5\uc740 \ubb3c\uc9c8\ubfd0 \uc544\ub2c8\ub77c \ube5b\uc774 \ub098\uc628 \uc870\uac74\uacfc \uc9c0\ub098\uc628 \uc870\uac74\uc5d0\ub3c4 \uad00\uacc4\ub41c\ub2e4. \ub530\ub77c\uc11c \ubb3c\uc9c8\ub9c8\ub2e4 \uc5b8\uc81c\ub098 \uac19\uc740 \uc0c9\uae54\uc758 \uc120\ub9cc \ub098\uc628\ub2e4\ub294 \uc2dd\uc73c\ub85c \ub2e8\uc21c\ud654\ud558\uba74 \uace4\ub780\ud558\ub2e4. \ubb34\uc5c7\uc774 \ube5b\uc744 \ub0b4\uace0 \ubb34\uc5c7\uc744 \ud1b5\uacfc\ud588\ub294\uc9c0 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ubc1d\uc740 \uc120\uacfc \uc5b4\ub450\uc6b4 \uc120\uc744 \ubaa8\ub450 \ubb3c\uc9c8\uacfc \ube5b\uc758 \uc0c1\ud638\uc791\uc6a9\uc774\ub77c\ub294 \ub9e5\ub77d\uc5d0\uc11c \uc77d\uc744 \ud544\uc694\uac00 \uc788\ub2e4. \ud761\uc218\uc120\uc744 \uc77d\ub294\ub2e4\ub294 \uac83\uc740 \uc5c6\uc5b4\uc9c4 \ube5b\uc758 \uc790\ub9ac\ub97c \ub2e4\ub978 \ube5b\uacfc\uc758 \ucc28\uc774\ub85c \uc54c\uc544\ubcf4\ub294 \uc77c\uc774\ub2e4. \uad00\uce21 \uc7a5\uce58\uac00 \ucda9\ubd84\ud788 \uad6c\ubcc4\ud558\uc9c0 \ubabb\ud558\uba74 \uac00\uae4c\uc6b4 \uc120\ub4e4\uc774 \ubb49\uccd0 \ubcf4\uc77c \uc218 \uc788\ub2e4. \ub300\uc0c1\uc758 \uc131\uc9c8\uacfc \uad00\ucc30\ud558\ub294 \ubc29\ubc95\uc774 \ud568\uaed8 \uc790\ub8cc\uc758 \ubaa8\uc2b5\uc744 \uc815\ud55c\ub2e4\ub294 \uc810\uc744 \uae30\uc5b5\ud574\uc57c \ud55c\ub2e4. \ube5b\uc774 \ub9cc\ub4e4\uc5b4 \ub0b4\ub294 \ud328\ud134\uc744 \uae30\ub85d\ud574 \ub450\uba74 \uadf8\ub0a0\uc758 \uad00\uce21\uc744 \ub118\uc5b4 \ub2e4\ub978 \uc2dc\uc810\uc758 \uc790\ub8cc\uc640 \ube44\uad50\ud560 \uc218 \uc788\ub2e4. \uc21c\uac04\uc801\uc778 \uc0c9\uc758 \uc778\uc0c1\uc774 \ubc18\ubcf5\ud574\uc11c \uac80\ud1a0\ud560 \uc218 \uc788\ub294 \uc790\ub8cc\ub85c \ubc14\ub010\ub2e4. \ubd84\uad11\ud559\uc758 \ud798\uc740 \ub208\uc774 \ubc1d\uc740 \ud55c \uc0ac\ub78c\uc758 \uac10\uac01\ubcf4\ub2e4 \uce21\uc815\uacfc \uae30\ub85d\uc744 \uc11c\ub85c \ube44\uad50\ud558\ub294 \uccb4\uacc4\uc5d0\uc11c \ub098\uc628\ub2e4. \uc2e4\ud5d8\uc2e4\uc5d0\uc11c \ub9cc\ub4e0 \uae30\uc900\uacfc \ud558\ub298\uc5d0\uc11c \ubc1b\uc740 \ube5b\uc774 \uac19\uc740 \uc5b8\uc5b4\ub85c \uc774\uc5b4\uc9c0\ub294 \uacfc\uc815\uc774\ub2e4. \ud55c \uc904\uc758 \uc704\uce58\ub9cc \ube44\uc2b7\ud558\ub2e4\uace0 \uad6c\uc131 \uc131\ubd84\uc744 \uc131\uae09\ud558\uac8c \ud655\uc815\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc5ec\ub7ec \uc120\uc758 \uad00\uacc4\uc640 \uad00\ucc30 \uc870\uac74\uc744 \ud568\uaed8 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uae30\uae30\uc758 \uad6c\ubcc4 \ub2a5\ub825\uacfc \ub2e4\ub978 \uc131\ubd84\uc758 \uc601\ud5a5\ub3c4 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \uc790\uc5f0\uc740 \uad50\uacfc\uc11c\uc758 \uae54\ub054\ud55c \ud55c \uac00\uc9c0 \ud45c\ubcf8\ucc98\ub7fc\ub9cc \ub098\ud0c0\ub098\uc9c0 \uc54a\ub294\ub2e4. \uadf8\ub807\uc9c0\ub9cc \uc774 \uc5b4\ub824\uc6c0\uc740 \ubc29\ubc95\uc758 \uac00\uce58\ub97c \uc5c6\uc560\uc9c0 \uc54a\ub294\ub2e4. \uc624\ud788\ub824 \uc5b4\ub5a4 \uc870\uac74\uc5d0\uc11c \ubb34\uc5c7\uc744 \uc54c \uc218 \uc788\ub294\uc9c0 \ub354 \uc815\ubc00\ud558\uac8c \ubb3b\uac8c \ud55c\ub2e4. \uc61b \uc790\ub8cc\uc758 \ud655\uc2e4\ud788 \uc548\ub2e4\ub294 \ud45c\ud604\uc744 \ubaa8\ub4e0 \uc0c1\ud669\uc5d0 \ub300\ud55c \ubb34\uc81c\ud55c\uc758 \ubcf4\uc99d\uc73c\ub85c \ubc1b\uc544\ub4e4\uc774\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \ubd84\uad11 \ubd84\uc11d\uc740 \uc9c0\uc0c1\uc758 \ubb3c\uc9c8 \uc5f0\uad6c\uc640 \ucc9c\ubb38\ud559\uc744 \uc774\uc5b4 \uc8fc\uc5c8\ub2e4. \uc2e4\ud5d8\uc2e4\uc5d0\uc11c \uc5bb\uc740 \uc120\uc758 \uc9c0\uc2dd\uc774 \ud558\ub298\uc758 \uc790\ub8cc\ub97c \uc77d\ub294 \ub370 \uc4f0\uc774\uace0, \uc0c8\ub85c\uc6b4 \uc120\uc740 \ub2e4\uc2dc \ubb3c\uc9c8\uc5d0 \ub300\ud55c \uc9c8\ubb38\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \uac00\uae4c\uc6b4 \ub300\uc0c1\uc758 \uce21\uc815\uc774 \uba3c \ub300\uc0c1\uc758 \uc774\ud574\uc5d0 \uc5f0\uacb0\ub41c \uac83\uc774\ub2e4. \ubcc4\uc758 \uc0c9\uc744 \ub208\uc73c\ub85c \ubcf4\uace0 \uad6c\ubd84\ud558\ub294 \uc77c\uacfc \uc120\uc758 \uc138\ubd80\ub97c \ubd84\uc11d\ud558\ub294 \uc77c\uc740 \uc11c\ub85c \ub2e4\ub978 \uc218\uc900\uc758 \uc815\ubcf4\ub97c \uc900\ub2e4. \uac19\uc740 \ubc1d\uae30\ub85c \ubcf4\uc774\ub294 \ub450 \ube5b\ub3c4 \ub098\ub204\uc5b4 \ubcf4\uba74 \ub2e4\ub978 \ud754\uc801\uc744 \uac00\uc9c8 \uc218 \uc788\ub2e4. \uc804\uccb4 \uc778\uc0c1 \ub4a4\uc758 \uad6c\uc870\ub97c \uc0b4\ud53c\ub294 \ubc29\ubc95\uc774 \uad00\uce21\uc758 \ubc94\uc704\ub97c \ub113\ud614\ub2e4. \uc6b0\ub9ac\ub294 \ucc9c\uccb4 \uc0ac\uc9c4\uc744 \ubcfc \ub54c \ubaa8\uc591\uacfc \uc0c9\uc744 \uba3c\uc800 \ubcf8\ub2e4. \ubd84\uad11\ud559\uc740 \uadf8 \ube5b\uc744 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ubc30\uc5f4\ud574 \uc77d\ub294\ub2e4. \uc608\uc05c \ud615\uc0c1\uc774 \uc0ac\ub77c\uc9c4 \uac83\ucc98\ub7fc \ubcf4\uc5ec\ub3c4 \ubb3c\uc9c8\uc758 \uad6c\uc131\uacfc \uc0c1\ud0dc\ub97c \ubb3b\ub294 \ub370 \ub354 \uc801\ud569\ud55c \uc790\ub8cc\uac00 \ub420 \uc218 \uc788\ub2e4. \uc815\ubcf4\ub97c \uc5bb\uae30 \uc704\ud574 \ubcf4\uc5ec \uc8fc\ub294 \ud615\ud0dc\ub97c \ubc14\uafb8\ub294 \uac83\uc774\ub2e4. \ubd84\uad11\uae30\uc758 \uc5ed\uc0ac\ub294 \uc798 \ubcf4\uc778\ub2e4\ub294 \ub9d0\uc758 \ub73b\uc744 \ub113\ud78c\ub2e4. \ub354 \ud06c\uac8c \ud655\ub300\ud558\ub294 \uac83\ubfd0 \uc544\ub2c8\ub77c \ub098\ub204\uace0 \ube44\uad50\ud558\uace0 \ube48\ud2c8\uc744 \uae30\ub85d\ud558\ub294 \uc77c\ub3c4 \uad00\ucc30\uc774\ub2e4. \ubb34\uc5c7\uc774 \ubcf4\uc774\uc9c0 \uc54a\ub294\uc9c0\ub3c4 \uc790\ub8cc\uac00 \ub420 \uc218 \uc788\ub2e4\ub294 \ubc1c\uc0c1\uc758 \uc804\ud658\uc774\uc5c8\ub2e4. \uc0c9\uc758 \ub760 \uc548\uc5d0 \ub0a8\uc740 \uac00\ub290\ub2e4\ub780 \ucc28\uc774\uac00 \uc0c8\ub85c\uc6b4 \uc9c0\uc2dd\uc758 \uae38\uc744 \uc5f4\uc5c8\ub2e4. \uc190\uc5d0 \ub2ff\uc9c0 \uc54a\ub294 \ubcc4\uc744 \uc774\ud574\ud558\ub294 \uae38\uc740 \uba40\ub9ac \uac00\ub294 \uae30\uc220\uacfc \ud568\uaed8, \uc774\ubbf8 \ub3c4\ucc29\ud55c \ube5b\uc744 \ub2e4\ub974\uac8c \uc77d\ub294 \uae30\uc220\uc5d0\uc11c\ub3c4 \uc5f4\ub838\ub2e4."}, {"id": "star-map-carved-again", "title": "\ubcc4\uc9c0\ub3c4\ub97c \ub2e4\ub978 \ub3cc\uc5d0 \ub2e4\uc2dc \uc0c8\uae34 \uc774\uc720", "summary": "\uac19\uc740 \ubcc4\uc9c0\ub3c4\ub97c \uc0c8 \ub3cc\uc5d0 \uc62e\uae34 \ubcf5\uac01\ucc9c\uc0c1\uc5f4\ucc28\ubd84\uc57c\uc9c0\ub3c4\uac01\uc11d\uc758 \uc0ac\uc5f0\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\ubb3c\uc9c8\uacfc \uc5d0\ub108\uc9c0", "categories": ["science"], "url": "stories/star-map-carved-again/index.html", "image": "../media/star-map-carved-again.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \ubcf5\uac01\ucc9c\uc0c1\uc5f4\ucc28\ubd84\uc57c\uc9c0\ub3c4\uac01\uc11d \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\ubcc4\uc9c0\ub3c4\ub97c \ub2e4\ub978 \ub3cc\uc5d0 \ub2e4\uc2dc \uc0c8\uae34 \uc774\uc720 \ub0a1\uc544 \uac00\ub294 \uae30\ub85d\uc744 \uc62e\uaca8 \ub450\ub294 \ubc29\ubc95 \uac19\uc740 \ubcc4\uc9c0\ub3c4\ub97c \uc0c8 \ub3cc\uc5d0 \uc62e\uae34 \ubcf5\uac01\ucc9c\uc0c1\uc5f4\ucc28\ubd84\uc57c\uc9c0\ub3c4\uac01\uc11d\uc758 \uc0ac\uc5f0\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ubb3c\uc9c8\uacfc \uc5d0\ub108\uc9c0 \uacfc\ud559\uacfc \ubc1c\uacac \ubcc4\uc9c0\ub3c4\ub97c \uc0dd\uac01\ud558\uba74 \uc885\uc774\ub098 \ud654\uba74\ubd80\ud130 \ub5a0\uc624\ub978\ub2e4. \uadf8\ub7f0\ub370 \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc5d0\ub294 \ub3cc\uc5d0 \uc0c8\uae34 \ubcc4\uc9c0\ub3c4\uac00 \uc788\ub2e4. \uc774\ub984\uc740 \uae38\ub2e4. \ubcf5\uac01\ucc9c\uc0c1\uc5f4\ucc28\ubd84\uc57c\uc9c0\ub3c4\uac01\uc11d. \uc624\ub298\uc740 \uadf8 \uc774\ub984\uc744 \ub2e4 \uc678\uc6b0\uc9c0 \ub9d0\uace0 \ub9e8 \uc55e\uc758 \ubcf5\uac01\uc5d0\ub9cc \ub208\uae38\uc744 \uc8fc\uc5b4 \ubcf4\uc790. \uc774 \ubb3c\uac74\uc758 \uc7ac\ubbf8\ub294 \ubcc4\uc744 \uba87 \uac1c \uadf8\ub838\ub290\ub0d0\ubcf4\ub2e4 \uc65c \uac19\uc740 \ub0b4\uc6a9\uc744 \ub2e4\ub978 \ub3cc\uc5d0 \ub2e4\uc2dc \uc0c8\uacbc\ub290\ub0d0\uc5d0 \uc788\ub2e4. \ud558\ub298\uc744 \uae30\ub85d\ud55c \ub3cc\uc5d0\ub3c4 \uc2dc\uac04\uc774 \ud758\ub800\ub358 \uac83\uc774\ub2e4. \ubc15\ubb3c\uad00\uc740 1395\ub144\uc5d0 \ub3cc\uc5d0 \uc0c8\uae34 \ucc9c\ubb38\ub3c4 \uac01\uc11d\uc774 \uc138\uc6d4\uc774 \ud750\ub974\uba70 \ud6fc\uc190\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\ub798\uc11c 1687\ub144\uc5d0 \uadf8 \ub0b4\uc6a9\uc744 \ub2e4\ub978 \ub3cc\uc5d0 \ub2e4\uc2dc \uc0c8\uacbc\ub2e4. \uc774\ub54c \ub9cc\ub4e4\uc5b4\uc9c4 \uac83\uc774 \uc0ac\uc9c4\uc758 \ubcf5\uac01\ubcf8\uc774\ub2e4. \uc624\ub798 \ubcf4\uad00\ud558\ub824\uace0 \ub2e8\ub2e8\ud55c \uc7ac\ub8cc\ub97c \uace8\ub77c\ub3c4 \uae30\ub85d\uc774 \uc800\uc808\ub85c \uc601\uc6d0\ud574\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c\ub294 \ub0b4\uc6a9\uc774 \uc0ac\ub77c\uc9c0\uae30 \uc804\uc5d0 \uc0c8\ub85c\uc6b4 \ub3cc\ub85c \uc62e\uae30\ub294 \ubc29\ubc95\uc744 \ud0dd\ud588\ub2e4. \uc190\uc0c1\ub41c \uc885\uc774\ub97c \ub2e4\uc2dc \ubca0\ub07c\ub294 \uc77c\uacfc \ub098\ub780\ud788 \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub294 \ub300\ubaa9\uc774\ub2e4. \uc0c8 \ub3cc\uc5d0 \uc0c8\uacbc\ub2e4\uace0 \uc0c8 \ubcc4\uc790\ub9ac\ub97c \ubc1c\uacac\ud588\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc758 \uc911\uc2ec\uc740 \uae30\uc874 \ub0b4\uc6a9\uc744 \ub2e4\uc2dc \uc0c8\uaca8 \ubcf4\uc874\ud588\ub2e4\ub294 \ub370 \uc788\ub2e4. \uae30\ub85d\uc758 \ub0b4\uc6a9\uacfc \uadf8 \ub0b4\uc6a9\uc744 \ub2f4\uc740 \ubb3c\uac74\uc758 \uc81c\uc791 \uc2dc\uc810\uc744 \ub098\ub204\uc5b4 \ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \uc0ac\uc9c4\uc758 \ub3cc\uc774 1687\ub144 \uac83\uc774\ub77c\ub294 \uc0ac\uc2e4\uacfc \uc6d0\ub798 \ucc9c\ubb38\ub3c4\uac00 1395\ub144\uc5d0 \uc0c8\uaca8\uc84c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uadf8\ub798\uc11c \ud568\uaed8 \ub4f1\uc7a5\ud55c\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ub450 \ub0a0\uc9dc\uac00 \uc2e4\uc218\ub85c \uc801\ud78c \uac83\uc774 \uc544\ub2c8\ub77c, \uc62e\uaca8 \ub0a8\uae30\ub294 \uacfc\uc815\uc758 \uc55e\ub4a4\ub97c \uc54c\ub824 \uc8fc\ub294 \uac83\uc774\ub2e4. \ucc9c\ubb38\ub3c4\uc758 \ub0b4\uc6a9\uc774 \uc5b4\ub514\uc5d0\uc11c \uc654\ub294\uc9c0\uc640 \ub208\uc55e\uc758 \ub3cc\uc744 \uc5b8\uc81c \uc0c8\uacbc\ub294\uc9c0\ub294 \ub2e4\ub978 \uc9c8\ubb38\uc774\ub2e4. \ubcf5\uac01\ubcf8\uc740 \uc774 \ub450 \uc2dc\uac04\uc744 \ud568\uaed8 \ud488\ub294\ub2e4. 1687\ub144 \uc81c\uc791\uc774\ub77c\ub294 \uc815\ubcf4\uac00 \uc6d0\ub798\uc758 \ub0b4\uc6a9\uc744 \uadf8\ud574 \ucc98\uc74c \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub9e4\uccb4\ub97c \uc0c8\ub85c \ub9c8\ub828\ud574 \uae30\ub85d\uc744 \uc774\uc5b4 \uac00\ub294 \ubc29\uc2dd\uc774\uc5c8\ub2e4. \uadf8\ub798\uc11c \uc6d0\ubcf8\uc774\ub77c\ub294 \ub9d0 \ud558\ub098\uc640 \ubcf5\uc81c\ud488\uc774\ub77c\ub294 \ub9d0 \ud558\ub098\ub85c \uac00\uce58\ub97c \ub098\ub204\uae30 \uc5b4\ub835\ub2e4. \uc62e\uaca8 \uc0c8\uae34 \ubb3c\uac74\ub3c4 \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc774 \ubb34\uc5c7\uc744 \ubcf4\uc874\ud560 \ud544\uc694\uac00 \uc788\ub2e4\uace0 \uc0dd\uac01\ud588\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \uc790\ub8cc\ub2e4. \ub2e4\ub9cc \uc0c8 \ub3cc\uc758 \ubaa8\ub4e0 \uc120\uc774 \uc6d0\ub798\uc640 \uc5b4\ub5bb\uac8c \uc77c\uce58\ud558\ub294\uc9c0\ub294 \uad6c\uccb4\uc801\uc778 \ube44\uad50\uac00 \ud544\uc694\ud55c \ubb38\uc81c\ub85c \ub0a8\ub294\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubc15\ubb3c\uad00\uc774 \ud655\uc778\ud55c \ubcf5\uac01\uc758 \uc774\uc720\uc640 \uc774\ub825\uc744 \ub530\ub77c \uc77d\ub294\ub2e4. \ub3cc\uc740 \uc885\uc774\ubcf4\ub2e4 \uc624\ub798 \ub0a8\uc744 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c0\uc9c0\ub9cc \uc2dc\uac04\uacfc \ud658\uacbd\uc758 \uc601\ud5a5\uc744 \ubc1b\uc9c0 \uc54a\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud6fc\uc190\ub41c \ub0b4\uc6a9\uc744 \ub2e4\uc2dc \uc0c8\uacbc\ub2e4\ub294 \uae30\ub85d\uc740 \ubcf4\uc874\uc774 \ud55c \ubc88\uc758 \uc7ac\ub8cc \uc120\ud0dd\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub0a8\uc740 \uac83\uc744 \uc0b4\ud53c\uace0 \ub2e4\ub978 \ub9e4\uccb4\ub85c \uc774\uc5b4 \uc8fc\ub294 \uacb0\uc815\uc774 \ud544\uc694\ud588\ub2e4. \uae30\ub85d\uc758 \uc218\uba85\uc5d0\ub294 \uadf8 \ub4a4\uc758 \ub3cc\ubd04\uacfc \ubcf5\uc81c\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \uc774\ub54c \ubcf4\uc874\uacfc \uc0c8\ub85c\uc6b4 \uad00\uce21\uc740 \uac19\uc740 \uc77c\uc774 \uc544\ub2c8\ub2e4. \ub2e4\ub978 \ub3cc\uc5d0 \uc0c8\uacbc\ub2e4\uace0 \uadf8\ub54c \uc0c8 \ud558\ub298\uc744 \uce21\uc815\ud55c \uacb0\uacfc\ub77c\uace0 \uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub0b4\uc6a9\uc744 \uc62e\uae30\ub294 \uc791\uc5c5\uc778\uc9c0 \uc0c8 \uc9c0\uc2dd\uc744 \ucd94\uac00\ud55c \uac83\uc778\uc9c0 \uad6c\ubd84\ud574\uc11c \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \ub450 \ub0a0\uc9dc\ub97c \ud558\ub098\ub85c \ud569\uce58\uc9c0 \uc54a\ub294 \uc791\uc740 \uc8fc\uc758\uac00 \uc624\ub798\ub41c \uacfc\ud559 \uc790\ub8cc\ub97c \ub354 \uc815\ud655\ud558\uac8c \uc77d\ub3c4\ub85d \ub3d5\ub294\ub2e4. \ubcf5\uac01\ubcf8\uc740 \uad00\uc0c1\uac10\uc5d0 \ubcf4\uad00\ub418\uc5c8\ub2e4\uac00 \uc601\uc870 \ub54c \ud0dc\uc870\ubcf8\uacfc \ud568\uaed8 \ud760\uacbd\uac01\uc73c\ub85c \uc62e\uaca8\uc84c\ub2e4\uace0 \uc18c\uac1c\ub41c\ub2e4. \ubb3c\uac74\uc758 \uc8fc\uc18c\uac00 \ud55c \ubc88 \uc815\ud574\uc9c4 \ub4a4 \uba48\ucd98 \uac83\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc62e\uae30\ub294 \ub3d9\uc548\uc5d0\ub3c4 \uc5b4\ub5a4 \ucc9c\ubb38\ub3c4\uc640 \uad00\uacc4\ub41c \uc790\ub8cc\uc778\uc9c0\uc758 \uc5f0\uacb0\uc740 \uc911\uc694\ud588\ub2e4. \ubcf4\uad00\uc758 \uc774\ub825\uc740 \ubcc4\uc790\ub9ac\uc758 \ub0b4\uc6a9\uacfc \ub2e4\ub978 \uc885\ub958\uc758 \uc2dc\uac04\ud45c\ub2e4. \uc774 \uc124\uba85\uc744 \uace7\ubc14\ub85c \uc624\ub298\uc758 \uc804\uc2dc \uc704\uce58\ub098 \ub2f9\uc2dc \uacf5\uac04\uc758 \uc644\uc804\ud55c \ubaa8\uc2b5\uc73c\ub85c \uc77d\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud655\uc778\ud55c \uc774\ub3d9 \uae30\ub85d\uc774 \uc54c\ub824 \uc8fc\ub294 \ud070 \uad00\uacc4\ub97c \ub530\ub77c\uac00\ub294 \uac83\uc774\ub2e4. \ud604\uc7ac \ubc15\ubb3c\uad00\uc5d0\uc11c \ubcf4\ub294 \ubb3c\uac74\uc740 \uc81c\uc791\uacfc \ubcf4\uad00, \uc774\uc804\uacfc \uc218\uc9d1\uc758 \uc5ec\ub7ec \uc2dc\uac04\uc744 \uac70\ucce4\uc744 \uc218 \uc788\ub2e4. \ub3cc \uc704\uc758 \ud558\ub298\uc744 \uc77d\ub294 \uc77c \uc606\uc5d0 \ub3cc \uc790\uccb4\uc758 \uc5ec\ud589\ub3c4 \ub193\uc744 \uc218 \uc788\ub2e4. \uc624\ub298\uc758 \uc6b0\ub9ac\ub294 \uc0ac\uc9c4\uacfc \ud30c\uc77c\ub85c \uc790\ub8cc\ub97c \ubcf5\uc0ac\ud558\uc9c0\ub9cc \uc5ec\uae30\uc11c\ub294 \ub2e4\ub978 \ub3cc\uc744 \ub9c8\ub828\ud574 \ub2e4\uc2dc \uc0c8\uae30\ub294 \uc218\uace0\ub97c \ub4e4\uc600\ub2e4. \ubc29\ubc95\uc740 \ub2e4\ub974\ub354\ub77c\ub3c4 \uc0ac\ub77c\uc9c8 \uc218 \uc788\ub294 \uc815\ubcf4\ub97c \ub2e4\uc74c \uc2dc\uac04\uc73c\ub85c \ub118\uae30\ub824\ub294 \ubb38\uc81c\ub294 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ub514\uc9c0\ud138 \ubcf5\uc0ac\uc640 \uc218\uacf5 \ubcf5\uac01\uc774 \ubaa8\ub4e0 \uc810\uc5d0\uc11c \uac19\uc740 \uacfc\uc815\uc774\ub77c\uace0 \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc7ac\ub8cc\uc640 \uc624\ucc28, \uad00\ub9ac\uc758 \uc870\uac74\uc740 \uac01\uac01 \ub2e4\ub974\ub2e4. \ubcc4\uc9c0\ub3c4\ub97c \ubcf4\uba74 \uba3c\uc800 \ud558\ub298\uc758 \uc774\ub984\uacfc \uc810\uc744 \ucc3e\uac8c \ub41c\ub2e4. \uadf8 \uc606\uc5d0 \uc65c \ub2e4\uc2dc \ub9cc\ub4e4\uc5c8\ub294\uac00\ub77c\ub294 \uc9c8\ubb38\ub3c4 \ub193\uc544 \ubcf4\uc790. \ubb3c\uac74\uc744 \ubcf5\uc81c\ud588\ub2e4\ub294 \ub9d0\uc774 \ucc3d\uc791\uc131\uc774 \uc5c6\ub2e4\ub294 \ub73b\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc624\ub798\ub41c \uc9c0\uc2dd\uc744 \uacc4\uc18d \uc77d\uc744 \uc218 \uc788\uac8c \ud558\ub824\ub294 \ud310\ub2e8\uacfc \uc190\uc77c\uc774 \ub610 \ud558\ub098\uc758 \uc5ed\uc0ac\ub85c \ub0a8\uc558\ub2e4. \uc775\uc219\ud55c \ubcc4\uc758 \ubaa8\uc591 \ub4a4\uc5d0 \ubcf4\uc874\uc758 \uc120\ud0dd\uc774 \uc788\uc5c8\ub2e4. \ubcf5\uac01\ubcf8\uc740 \ucc98\uc74c\uc5d0 \ucc3d\ub355\uad81 \ubc16 \uad00\uc0c1\uac10\uc5d0 \ubcf4\uad00\ub418\uc5c8\ub2e4. \uc774\ud6c4 \uc601\uc870 \ub54c \uc6d0\ub798\uc758 \ud0dc\uc870\ubcf8\uacfc \ud568\uaed8 \ucc3d\ub355\uad81 \ud760\uacbd\uac01\uc73c\ub85c \uc62e\uacbc\ub2e4\uace0 \ubc15\ubb3c\uad00\uc740 \uc18c\uac1c\ud55c\ub2e4. \ub450 \ub3cc\uc740 \ub0b4\uc6a9\uc73c\ub85c \uc774\uc5b4\uc9c0\uba74\uc11c\ub3c4 \uac01\uac01 \ubcf4\uad00 \uc774\ub825\uc744 \uc9c0\ub2cc \ubb3c\uac74\uc774\ub2e4. \uc694\uc998 \ud30c\uc77c\uc744 \ubcf5\uc0ac\ud574 \ub2e4\ub978 \uacf3\uc5d0 \uc800\uc7a5\ud558\ub294 \uc77c\uc774 \ub5a0\uc624\ub97c \uc218\ub3c4 \uc788\ub2e4. \ubc29\ubc95\uc740 \uc544\uc8fc \ub2e4\ub974\uc9c0\ub9cc \uae30\ub85d\uc744 \uc783\uc9c0 \uc54a\uc73c\ub824\ub294 \uc120\ud0dd\uc774\ub77c\ub294 \uc810\uc5d0\uc11c \uac00\uae4c\uc774 \ub290\uaef4\uc9c4\ub2e4. \uc774 \ubcc4\uc9c0\ub3c4\ub294 \ud558\ub298\uc744 \uad00\ucc30\ud558\ub358 \uc0ac\ub78c\ub4e4\ubfd0 \uc544\ub2c8\ub77c, \uadf8 \uae30\ub85d\uc744 \ub2e4\uc74c \uc2dc\ub300\ub85c \uc804\ud558\ub824\ub358 \uc0ac\ub78c\ub4e4\uc758 \uc77c\ub3c4 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "tides-moon-and-changing-shore", "title": "\ubc00\ubb3c\uacfc \uc370\ubb3c \u2014 \ub2ec\uc740 \uc65c \ubc18\ub300\ud3b8 \ubc14\ub2e4\ub3c4 \uc6c0\uc9c1\uc77c\uae4c", "summary": "\ub0ae\uc740 \ubb3c\ub54c\uc758 \ud56d\uad6c\uc5d0\uc11c \uc2dc\uc791\ud574 \ub2ec\uc758 \uc911\ub825 \ucc28\uc774\u00b7\ud0dc\uc591\uc758 \uc601\ud5a5\u00b7\uc9c0\uc5ed\ubcc4 \uc870\uc11d\uc758 \ucc28\uc774\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\uc6b0\uc8fc\uc640 \ucc9c\ubb38", "categories": ["science"], "url": "stories/tides-moon-and-changing-shore/index.html", "image": "../media/tides-moon-and-changing-shore.png", "alt": "\uc370\ubb3c \ub54c \ubb3c\uc774 \ube60\uc9c4 \ubc14\ub2e5\uc5d0 \uc791\uc740 \ubc30\ub4e4\uc774 \ub193\uc778 \uc0c1\uc0c1 \uc18d \ud56d\uad6c \ud48d\uacbd\uc758 \uc0bd\ud654.", "text": "\ubc00\ubb3c\uacfc \uc370\ubb3c \u2014 \ub2ec\uc740 \uc65c \ubc18\ub300\ud3b8 \ubc14\ub2e4\ub3c4 \uc6c0\uc9c1\uc77c\uae4c \ubc14\ub2f7\ubb3c\uc758 \ub192\uc774\uc5d0 \ub2f4\uae34 \uac70\ub9ac\uc758 \ucc28\uc774\uc640 \ud574\uc548\uc758 \ubaa8\uc591 \ub0ae\uc740 \ubb3c\ub54c\uc758 \ud56d\uad6c\uc5d0\uc11c \uc2dc\uc791\ud574 \ub2ec\uc758 \uc911\ub825 \ucc28\uc774\u00b7\ud0dc\uc591\uc758 \uc601\ud5a5\u00b7\uc9c0\uc5ed\ubcc4 \uc870\uc11d\uc758 \ucc28\uc774\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uc6b0\uc8fc\uc640 \ucc9c\ubb38 \uacfc\ud559\uacfc \ubc1c\uacac \ud56d\uad6c\uc5d0 \ubc30\uac00 \uc788\uc9c0\ub9cc \ubb3c\uc774 \uc544\ub2c8\ub77c \ubc14\ub2e5 \uc704\uc5d0 \ub193\uc5ec \uc788\ub2e4. \uba87 \uc2dc\uac04 \ub4a4 \uac19\uc740 \ubc30\uac00 \ub2e4\uc2dc \ub5a0 \uc788\uc744 \uc218 \uc788\ub2e4. \ubc14\ub2e4\uac00 \ub2e8\uc21c\ud788 \ud30c\ub3c4\uce58\ub294 \uac83\uacfc \ub2ec\ub9ac \ud574\uc548\uc758 \ubb3c\ub192\uc774 \uc790\uccb4\uac00 \uc624\ub974\ub0b4\ub9ac\ub294 \ud604\uc0c1\uc774\ub2e4. \ubc00\ubb3c\uacfc \uc370\ubb3c\uc740 \uac19\uc740 \uc7a5\uc18c\ub97c \ub2e4\ub978 \ud48d\uacbd\uc73c\ub85c \ubc14\uafbc\ub2e4. \ub2ec\uc774 \ubc14\ub2e4\ub97c \ub2f9\uae34\ub2e4\ub294 \uc124\uba85\uc740 \uc775\uc219\ud558\ub2e4. \uadf8\ub7f0\ub370 \ub2ec\uc774 \uc788\ub294 \ucabd\ub9cc \ubb3c\uc774 \ub192\uc544\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\uace0 \ud55c\ub2e4. \ubc18\ub300\ucabd\uc5d0\ub3c4 \ubb3c\uc774 \ubd80\ud478\ub294 \uae30\ubcf8 \ubaa8\ud615\uc774 \uc788\ub2e4. \uc774 \uc7a5\uba74\uc744 \uc774\ud574\ud558\ub824\uba74 \uc911\ub825\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc5d0\uc11c \ud55c \uac78\uc74c \ub354 \ub098\uc544\uac00 \uadf8 \ud798\uc774 \uc704\uce58\ub9c8\ub2e4 \ub2e4\ub974\ub2e4\ub294 \uc810\uc744 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc9c0\uad6c\ub294 \ud558\ub098\uc758 \uc810\uc774 \uc544\ub2c8\ub77c \ud06c\uae30\uac00 \uc788\ub294 \ubb3c\uccb4\ub2e4. \ub2ec\uacfc \uac00\uae4c\uc6b4 \ucabd, \uc9c0\uad6c\uc758 \uc911\uc2ec, \ub2ec\uc5d0\uc11c \uba3c \ucabd\uc740 \uac01\uac01 \uac70\ub9ac\uac00 \ub2e4\ub974\ub2e4. \uad50\uc7ac\ub294 \ub2ec\uc774 \uac00\uae4c\uc6b4 \ucabd\uc744 \ub354 \uac15\ud558\uac8c, \uba3c \ucabd\uc744 \ub354 \uc57d\ud558\uac8c \ub2f9\uae34\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uac19\uc740 \ubc29\ud5a5\uc758 \uc911\ub825\ub3c4 \ubaa8\ub4e0 \uacf3\uc5d0\uc11c \uac19\uc740 \ud06c\uae30\ub85c \uc791\uc6a9\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774 \ucc28\uc774\uac00 \uc870\uc11d\uc744 \uc77c\uc73c\ud0a4\ub294 \uc911\uc694\ud55c \ucd9c\ubc1c\uc810\uc774\ub2e4. \ub2ec\uc774 \uc9c0\uad6c \uc804\uccb4\ub97c \uc6c0\uc9c1\uc774\ub294 \ud6a8\uacfc\uc640 \uc9c0\uad6c \uc548\uc758 \uc11c\ub85c \ub2e4\ub978 \uc704\uce58\ub97c \ub2e4\ub974\uac8c \ub2f9\uae30\ub294 \ud6a8\uacfc\ub97c \ub098\ub204\uc5b4 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \ubc14\ub2e4\ub97c \ud1b5\uc9f8\ub85c \ud55c \ub369\uc5b4\ub9ac\uc758 \ubb3c\ucc98\ub7fc \ubcf4\uace0 \ub2ec \ucabd\uc73c\ub85c\ub9cc \ub04c\uc5b4\uc62c\ub9b0\ub2e4\uace0 \uc0c1\uc0c1\ud558\uba74 \ud604\uc0c1\uc774 \ucda9\ubd84\ud788 \uc124\uba85\ub418\uc9c0 \uc54a\ub294\ub2e4. \ub2e8\uc21c\ud654\ud55c \ubaa8\ud615\uc5d0\uc11c\ub294 \uc9c0\uad6c\uc640 \ubc14\ub2e4\uac00 \ub2ec\uc744 \ud5a5\ud55c \ubc29\ud5a5\uc73c\ub85c \uc0c1\ub300\uc801\uc73c\ub85c \ub298\uc5b4\ub098\ub294 \ubcc0\ud615\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ub2ec \ucabd\uc740 \uc9c0\uad6c \uc911\uc2ec\ubcf4\ub2e4 \uac15\ud558\uac8c \ub04c\ub9ac\uace0, \ubc18\ub300\ud3b8\uc740 \uc911\uc2ec\ubcf4\ub2e4 \uc57d\ud558\uac8c \ub04c\ub9b0\ub2e4. \uc911\uc2ec\uacfc \ube44\uad50\ud55c \ucc28\uc774\uac00 \uc591\ucabd\uc5d0 \ubaa8\ub450 \uc911\uc694\ud574\uc9c0\ub294 \uac83\uc774\ub2e4. \uad50\uc7ac\ub294 \uc774 \ucc28\uc774\ub85c \ubb3c\uc774 \ub2ec \uc544\ub798\uc640 \uadf8 \ubc18\ub300\ucabd\uc758 \ub450 \uc601\uc5ed\uc73c\ub85c \uc774\ub3d9\ud574 \ub192\uc544\uc9c0\ub294 \ubaa8\ud615\uc744 \uc124\uba85\ud55c\ub2e4. \ubb3c\uc774 \uac11\uc790\uae30 \ub298\uc5b4\ub098\uac70\ub098 \ub2ec\uc774 \ubc14\ub2f7\ubb3c\uc744 \uc9c0\uad6c \ubc16\uc73c\ub85c \ub4e4\uc5b4 \uc62c\ub9ac\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc5b4\ub290 \uacf3\uc73c\ub85c \ubb3c\uc774 \ud750\ub974\uace0 \uc313\uc774\ub294\uc9c0\ub97c \ubcf4\ub294 \uc124\uba85\uc774\ub2e4. \uc2e4\uc81c \ud574\uc591\uc744 \uadf8\ub300\ub85c \ubcf5\uc81c\ud55c \ubaa8\uc2b5\uc740 \uc544\ub2c8\uc9c0\ub9cc \ubc18\ub300\ud3b8\uc758 \ud604\uc0c1\uc744 \uc774\ud574\ud558\ub294 \ucd9c\ubc1c\uc810\uc774 \ub41c\ub2e4. \ub113\uc740 \ubc14\ub2e4\ub85c \ub458\ub7ec\uc2f8\uc778 \ub2e8\uc21c\ud55c \uc9c0\uad6c\ub97c \uc0dd\uac01\ud558\uba74, \uc9c0\uad6c\uac00 \uc790\uc804\ud558\uba74\uc11c \ud55c \ud574\uc548\uc740 \ubb3c\uc774 \ub192\uc740 \uc601\uc5ed\uacfc \ub0ae\uc740 \uc601\uc5ed\uc744 \ubc88\uac08\uc544 \uc9c0\ub09c\ub2e4. \uc774 \uae30\ubcf8 \ubaa8\ud615\uc5d0\uc11c\ub294 \ub450 \ubc88\uc758 \ub192\uc740 \ubb3c\uacfc \ub450 \ubc88\uc758 \ub0ae\uc740 \ubb3c\uc744 \uacbd\ud5d8\ud55c\ub2e4. \ubc14\ub2e4\ub97c \ubcf4\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ubc00\ubb3c\uc774 \ub4e4\uace0 \uc370\ubb3c\uc774 \ub098\ub294 \ubcc0\ud654\uac00 \ub41c\ub2e4. \uadf8\ub7ec\ub098 \ubaa8\ub4e0 \ud574\uc548\uc5d0\uc11c \ud558\ub8e8 \ub450 \ubc88 \uac19\uc740 \ub192\uc774\uc758 \ubc00\ubb3c\uc774 \uc815\ud655\ud788 \ubc18\ubcf5\ub41c\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc2e4\uc81c \ubc14\ub2e4\ub294 \ub300\ub959\uacfc \ud574\uc800, \ud68c\uc804\uc758 \ud6a8\uacfc \ub54c\ubb38\uc5d0 \ud6e8\uc52c \ubcf5\uc7a1\ud558\ub2e4. \uac04\ub2e8\ud55c \ubaa8\ud615\uc73c\ub85c \uc6d0\ub9ac\ub97c \ubc30\uc6b0\ub294 \uc77c\uacfc \ud2b9\uc815 \ud56d\uad6c\uc758 \uc2e4\uc81c \uc2dc\uac01\ud45c\ub97c \ub9cc\ub4dc\ub294 \uc77c\uc740 \ub2e4\ub978 \ub2e8\uacc4\ub2e4. \ubc14\ub2e4\uc758 \uc870\uc11d\uc5d0\ub294 \ud0dc\uc591\uc758 \uc601\ud5a5\ub3c4 \uc788\ub2e4. \uad50\uc7ac\ub294 \ub2ec\uacfc \ud0dc\uc591\uc758 \ud6a8\uacfc\uac00 \ud568\uaed8 \ub098\ud0c0\ub09c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud0dc\uc591\uc774 \uc544\uc8fc \uba40\ub9ac \uc788\ub2e4\uace0 \ubc14\ub2e4\uc5d0 \uc544\ubb34 \uc601\ud5a5\uc744 \uc8fc\uc9c0 \uc54a\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uc870\uc11d\uc744 \uc77c\uc73c\ud0a4\ub294 \ud6a8\uacfc\ub294 \uc804\uccb4\uc758 \uc911\ub825 \ud06c\uae30\ub9cc\uc73c\ub85c \ube44\uad50\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc5ec\uae30\uc11c\ub3c4 \uac70\ub9ac\ubcc4 \ud798\uc758 \ucc28\uc774\uac00 \uc911\uc694\ud558\ub2e4. \ub2ec\uacfc \ud0dc\uc591\uc774 \uc9c0\uad6c\uc5d0\uc11c \uc5b4\ub5a4 \ubc29\ud5a5\uc5d0 \uc788\ub294\uc9c0\uc5d0 \ub530\ub77c \ub450 \ud6a8\uacfc\uac00 \ub354\ud574\uc9c0\uac70\ub098 \uc77c\ubd80 \uc0c1\uc1c4\ub41c\ub2e4. \ud558\ub298\uc758 \ub450 \ucc9c\uccb4\uac00 \ubc14\ub2e4\uc5d0 \uac01\uac01 \uba85\ub839\ud558\ub294 \ub290\ub08c\ubcf4\ub2e4, \uc5ec\ub7ec \ud798\uc758 \ucc28\uc774\uac00 \uac19\uc740 \ubb3c\uc5d0 \ud568\uaed8 \uc791\uc6a9\ud55c\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \ub2ec\uacfc \ud0dc\uc591\uc774 \uc9c0\uad6c\uc640 \ub300\uccb4\ub85c \ud55c \uc904\uc5d0 \ub193\uc774\ub294 \ub54c\uc5d0\ub294 \uc870\uc11d\uc758 \ud6a8\uacfc\uac00 \uac15\ud654\ub418\uc5b4 \ubb3c\ub192\uc774 \ucc28\uac00 \ucee4\uc9c0\ub294 \uacbd\ud5a5\uc774 \uc788\ub2e4. \uc0c8\ub2ec\uacfc \ubcf4\ub984\ub2ec \ubb34\ub835\uc758 \uc0ac\ub9ac\uc640 \uad00\ub828\ub41c\ub2e4. \ubc18\ub300\ub85c \uc0c1\ud604\uacfc \ud558\ud604 \ubb34\ub835\uc5d0\ub294 \ubb3c\ub192\uc774 \ucc28\uac00 \uc0c1\ub300\uc801\uc73c\ub85c \uc791\uc544\uc9c0\ub294 \uc870\uae08\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc774\uac83\uc740 \ud2b9\uc815 \ub0a0\uc9dc\uc758 \ud2b9\uc815 \ud574\uc548\uc5d0\uc11c \uba87 \ubbf8\ud130\uac00 \ub2ec\ub77c\uc9c4\ub2e4\ub294 \uc608\ubcf4\ub294 \uc544\ub2c8\ub2e4. \uc9c0\uc5ed\uc758 \uc2e4\uc81c \ubc18\uc751\uacfc \uc2dc\ucc28\uac00 \ud568\uaed8 \ub4e4\uc5b4\uac04\ub2e4. \ub2ec\uc758 \ubaa8\uc591\uc744 \ubcf4\uba70 \ud070 \ud750\ub984\uc744 \uc774\ud574\ud560 \uc218\ub294 \uc788\uc5b4\ub3c4 \uadf8\uac83\ub9cc\uc73c\ub85c \uac2f\ubc8c\uc5d0 \ub4e4\uc5b4\uac08 \uc2dc\uac01\uc744 \uc815\ud558\ub294 \uc790\ub8cc\ub85c \uc4f0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uad50\uc7ac\ub294 \ub300\ub959\uc774 \ubb3c\uc758 \uc774\ub3d9\uc744 \ub9c9\ub294 \ud6a8\uacfc\uc640 \ubc14\ub2e4\uc758 \uae4a\uc774, \ub9c8\ucc30, \uc9c0\uad6c\uc758 \ud68c\uc804, \ubc14\ub78c \ub4f1\uc774 \uc2e4\uc81c \uc870\uc11d\uc744 \ubcf5\uc7a1\ud558\uac8c \ub9cc\ub4e0\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub113\uace0 \uae4a\uc740 \ubc14\ub2e4\ub97c \uac00\uc815\ud55c \ubaa8\ud615\uacfc \uc881\uc740 \ub9cc\uc758 \ubb3c\uc740 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ubc18\uc751\ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \uc138\uacc4 \uc804\uccb4\uc5d0 \ud1b5\ud558\ub294 \ud558\ub098\uc758 \ubb3c\ub54c\ud45c\ub97c \ub9cc\ub4e4 \uc218\ub294 \uc5c6\ub2e4. \uc9c0\uc5ed\ubcc4 \uc790\ub8cc\uc640 \uacc4\uc0b0\uc774 \ud544\uc694\ud558\ub2e4. \uac19\uc740 \ud558\ub298\uc744 \ubcf4\uace0 \uc788\ub294\ub370 \ubc14\ub2e4\uc758 \ubcc0\ud654\uac00 \ub2e4\ub974\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc6d0\ub9ac\uac00 \ud2c0\ub838\ub2e4\ub294 \ub73b\ubcf4\ub2e4 \uc6d0\ub9ac\uac00 \uc791\uc6a9\ud558\ub294 \ud658\uacbd\uc774 \ub2e4\ub974\ub2e4\ub294 \ub73b\uc73c\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \ub2ec\uc758 \uc911\ub825 \ucc28\uc774\uac00 \ubb3c\uc5d0\ub9cc \uc791\uc6a9\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uad50\uc7ac\ub294 \ub2e8\ub2e8\ud55c \uc9c0\uad6c\ub3c4 \uc791\uc740 \ubcc0\ud615\uc744 \uacaa\ub294\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub2e4\ub9cc \uc554\uc11d\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c4 \uc9c0\uad6c\uc640 \uc790\uc720\ub86d\uac8c \uc774\ub3d9\ud558\ub294 \ubc14\ub2e4\uac00 \uac19\uc740 \uc815\ub3c4\uc640 \ubc29\uc2dd\uc73c\ub85c \uc6c0\uc9c1\uc774\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub208\uc5d0 \ub744\ub294 \ud574\uc548 \ud48d\uacbd\uc740 \uadf8 \ubc18\uc751 \uac00\uc6b4\ub370 \uc798 \ubcf4\uc774\ub294 \ubd80\ubd84\uc774\ub2e4. \uc774 \uc0ac\uc2e4\uc740 \ubc14\ub2e4\uac00 \ud2b9\ubcc4\ud788 \ub2ec\uc758 \ubd80\ub984\uc744 \ub4e3\ub294\ub2e4\ub294 \uc778\uc0c1\uc5d0\uc11c \ubc97\uc5b4\ub098\uac8c \ud55c\ub2e4. \uc911\ub825\uc740 \uc5ec\ub7ec \ubb3c\uc9c8\uc5d0 \uc791\uc6a9\ud558\uace0 \ubb3c\uc9c8\uc758 \uc131\uc9c8\uacfc \uc870\uac74\uc5d0 \ub530\ub77c \uacb0\uacfc\uac00 \ub2e4\ub974\uac8c \ub098\ud0c0\ub09c\ub2e4. \ud798\uacfc \ubc18\uc751\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud604\uc0c1\uc744 \ub354 \uc815\ud655\ud558\uac8c \uc124\uba85\ud560 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc370\ubb3c \ub54c\uc758 \ud56d\uad6c\ub97c \ub5a0\uc62c\ub9ac\ub294 \uc0c1\uc0c1 \uc18d \ud48d\uacbd\uc774\ub2e4. \uc2e4\uc81c \ud56d\uad6c\uc758 \uce21\uc815 \uc0ac\uc9c4\uc774\ub098 \ub450 \uc2dc\uc810\uc758 \ubb3c\ub192\uc774 \ube44\uad50 \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uadf8\ub9bc \uc18d\uc758 \ubc30\uc640 \ubb3c\uac00\ub9cc\uc73c\ub85c \uc870\uc11d\uc758 \ud06c\uae30\ub098 \uc2dc\uac01\uc744 \uacc4\uc0b0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\uc74c\uc5d0 \uac19\uc740 \ud574\uc548\uc774 \uba87 \uc2dc\uac04 \uc0ac\uc774 \ub2e4\ub978 \ubaa8\uc2b5\uc774 \ub418\ub294 \uac83\uc744 \ubcf4\uba74 \ub2ec\uc758 \ubc29\ud5a5\ubfd0 \uc544\ub2c8\ub77c \ubb3c\uc774 \uc9c0\ub098\uac00\ub294 \uae38\ub3c4 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc911\ub825\uc758 \ucc28\uc774\uc640 \uc9c0\uad6c\uc758 \ud68c\uc804, \ud574\uc548\uc758 \ubaa8\uc591\uc774 \ud55c \ud48d\uacbd\uc5d0 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4. \ubb3c\ub54c\uc758 \ubcc0\ud654\ub294 \uba3c \ud558\ub298\uacfc \ubc14\ub85c \ubc1c\ubc11\uc758 \uc9c0\ud615\uc774 \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ub418\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \uc77c\uc0c1\uc758 \ucc9c\ubb38\ud559\uc774\ub2e4."}, {"id": "water-clock-floating-turtle", "title": "\uc774 \uac70\ubd81\uc774\ub294 \ubb3c\uc774 \ucc28\uba74 \ub5a0\uc62c\ub790\ub2e4", "summary": "\ub124 \ub0a0\uac1c\uac00 \ub2ec\ub9b0 \uc790\uaca9\ub8e8 \ubd80\ud45c\uc5d0\uc11c \ubb3c\uc758 \uc6c0\uc9c1\uc784\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "\uacfc\ud559\uacfc \ubc1c\uacac", "subcategory": "\ubb3c\uc9c8\uacfc \uc5d0\ub108\uc9c0", "categories": ["science"], "url": "stories/water-clock-floating-turtle/index.html", "image": "../media/water-clock-floating-turtle.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc790\uaca9\ub8e8 \ubd80\ud45c \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc774 \uac70\ubd81\uc774\ub294 \ubb3c\uc774 \ucc28\uba74 \ub5a0\uc62c\ub790\ub2e4 \uc790\uaca9\ub8e8\uc5d0\uc11c \uc2dc\uac04\uc744 \uc804\ud558\ub358 \ub465\uadfc \ubd80\ud488 \ub124 \ub0a0\uac1c\uac00 \ub2ec\ub9b0 \uc790\uaca9\ub8e8 \ubd80\ud45c\uc5d0\uc11c \ubb3c\uc758 \uc6c0\uc9c1\uc784\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ubb3c\uc9c8\uacfc \uc5d0\ub108\uc9c0 \uacfc\ud559\uacfc \ubc1c\uacac \ub465\uadfc \ubab8\uccb4\uc5d0 \ub0a0\uac1c \uac19\uc740 \ubd80\ubd84\uc774 \ub124 \uac1c \ub2ec\ub838\ub2e4. \uac70\ubd81\uc774\ucc98\ub7fc \ubcf4\uc774\uae30\ub3c4 \ud558\uace0 \ub69c\uaed1\ucc98\ub7fc \ubcf4\uc774\uae30\ub3c4 \ud55c\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc740 \uc774\uac83\uc744 \uc790\uaca9\ub8e8\uc758 \ubd80\ud45c\ub77c\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc2dc\uacc4 \uc804\uccb4\uac00 \uc544\ub2c8\ub77c \uadf8 \uc548\uc5d0\uc11c \uc6c0\uc9c1\uc774\ub358 \ubd80\ud488\uc774\ub2e4. \uac70\ubd81\uc774\ub97c \ub2ee\uc558\ub2e4\uace0 \ubd80\uad6c\ub77c\ub294 \uc774\ub984\uc73c\ub85c\ub3c4 \ubd88\ub800\ub2e4\uace0 \ud55c\ub2e4. \uce5c\uadfc\ud55c \ubcc4\uba85\uc744 \uc54c\uace0 \ub098\uba74 \ub465\uadfc \ubab8\uccb4\uc640 \uc606\uc73c\ub85c \ubed7\uc740 \ubd80\ubd84\uc744 \ub2e4\uc2dc \ubcf4\uac8c \ub41c\ub2e4. \uc774 \ubb3c\uac74\uc5d0\uc11c\ub294 \ubb3c \uc704\uc5d0\uc11c \uc6c0\uc9c1\uc774\ub294 \uc77c\uc774 \uc774\uc57c\uae30\uc758 \uc911\uc2ec\uc774\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc5d0 \ub530\ub974\uba74 \ubd80\ud45c\ub294 \uc587\uc740 \uad6c\ub9ac\ud310\uc744 \ubd99\uc5ec \ub9cc\ub4e4\uc5c8\ub2e4. \uc6d0\ud615 \ubab8\uccb4\uc758 \uc0ac\ubc29\uc5d0\ub294 \ub0a0\uac1c\uac00 \ud558\ub098\uc529 \ub2ec\ub9ac\uace0, \ud55c\ucabd \uba74\uc758 \uac00\uc6b4\ub370\uc5d0\ub294 \uae38\ucb49\ud55c \uc5f0\uacb0\uad6c\uac00 \uc788\ub2e4. \uc5ec\uae30\uc5d0 \uc7a3\ub300\ub97c \uaf42\uc558\ub2e4. \uc2dc\uacc4\ub97c \ub5a0\uc62c\ub9ac\uba74 \ubc14\ub298\ubd80\ud130 \ucc3e\uac8c \ub418\uc9c0\ub9cc \uc774 \ubd80\ud488\uc5d0\uc11c\ub294 \uc7a3\ub300\uac00 \ub4f1\uc7a5\ud55c\ub2e4. \uac00\uc6b4\ub370\uc758 \uc791\uc740 \uc790\ub9ac\uac00 \ub2e4\ub978 \ubb3c\uac74\uacfc \uc774\uc5b4\uc9c0\ub294 \uc9c0\uc810\uc774\ub77c\ub294 \uac83\uc744 \uc54c\uace0 \ubcf4\uba74, \ud3c9\ubc94\ud55c \uad6c\uba4d \uac19\uc740 \ubd80\ubd84\uc5d0\ub3c4 \ub208\uae38\uc774 \uac04\ub2e4. \ubd80\ud45c\ub294 \ubb3c\uc744 \ubc1b\ub294 \ud1b5\uc778 \uc218\uc218\ud638 \uc548\uc5d0 \ub4e4\uc5b4\uac00\ub3c4\ub85d \ub9cc\ub4e4\uc5c8\ub2e4. \ubc15\ubb3c\uad00\uc740 \uadf8 \ud06c\uae30\ub97c \uc218\uc218\ud638\uc758 \uc18d\ub458\ub808\uc5d0 \ub9de\ucd94\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\ub987\uacfc \ubd80\ud45c\uac00 \uc544\ubb34\ub807\uac8c\ub098 \ub9cc\ub098\ub294 \uad6c\uc870\uac00 \uc544\ub2c8\uc5c8\ub358 \uac83\uc774\ub2e4. \uc218\uc218\ud638\uc5d0 \ubb3c\uc774 \ucc28\uba74 \ubd80\ud45c\uac00 \ub5a0\uc624\ub974\uace0 \uc7a3\ub300\ub3c4 \ud568\uaed8 \uc62c\ub77c\uac04\ub2e4. \uc624\ub298 \uc774 \uae00\uc5d0\uc11c \uc54c\uc544\ub458 \uc6c0\uc9c1\uc784\uc740 \uc774\uac83\uc774\uba74 \ucda9\ubd84\ud558\ub2e4. \ubb3c\uc774 \ub192\uc544\uc9c0\ub294 \ubcc0\ud654\uac00 \ub2e4\ub978 \ubd80\ud488\uc758 \uc704\uce58 \ubcc0\ud654\ub85c \uc774\uc5b4\uc9c4\ub2e4. \ubcf5\uc7a1\ud55c \uc790\ub3d9 \uc7a5\uce58\uc758 \uc124\uba85\ub3c4 \uc774\ub807\uac8c \uc791\uc740 \uc6c0\uc9c1\uc784 \ud558\ub098\uc5d0\uc11c \uc2dc\uc791\ud560 \uc218 \uc788\ub2e4. \uc2dc\uac04 \uc790\uccb4\ub294 \uc190\uc73c\ub85c \uc7a1\uc744 \uc218 \uc5c6\uc9c0\ub9cc \uacc4\uc18d \uc77c\uc5b4\ub098\ub294 \ubcc0\ud654\ub97c \uae30\uc900\uc73c\ub85c \uc140 \uc218 \uc788\ub2e4. \uc774 \ubd80\ud488\uc5d0\uc11c\ub294 \ubb3c\uc758 \ub192\uc774\uac00 \uc62c\ub77c\uac00\uba74 \ubd80\ud45c\uc640 \uc7a3\ub300\uc758 \uc704\uce58\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \ubb3c\uc18d\uc758 \uc0c1\ud0dc\ub97c \ubc16\uc5d0\uc11c \uc77d\uc744 \uc218 \uc788\ub294 \uc6c0\uc9c1\uc784\uc73c\ub85c \uc774\uc5b4 \uc8fc\ub294 \uc148\uc774\ub2e4. \ubb3c\uc774 \ucc28\ub294 \ud1b5\uacfc \uadf8 \uc548\uc758 \ub5a0\uc624\ub974\ub294 \ubb3c\uac74, \uc5f0\uacb0\ub41c \uc7a3\ub300\uac00 \ud55c \uad00\uacc4\ub97c \uc774\ub8ec\ub2e4. \uc774 \uc6d0\ub9ac\ub9cc\uc73c\ub85c \uc790\uaca9\ub8e8 \uc804\uccb4\uc758 \uc2dc\uac04\uc744 \uc815\ud655\ud788 \uc124\uba85\ud588\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ubb3c\uc774 \ub4e4\uc5b4\uc624\ub294 \uc870\uac74\uacfc \ub2e4\ub978 \uc7a5\uce58\ub4e4\uc774 \ud568\uaed8 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubd80\ud45c\ub77c\ub294 \ud55c \ubd80\ud488\uc774 \ub9e1\uc740 \uc77c\uc744 \uc54c\uc544\ubcf4\ub294 \ub370 \uc9d1\uc911\ud55c\ub2e4. \ubcf5\uc7a1\ud55c \uae30\uacc4\ub97c \ucc98\uc74c \ubcfc \ub54c \uc804\uccb4\ub97c \ud55c\uaebc\ubc88\uc5d0 \uc678\uc6b0\uae30\ubcf4\ub2e4 \ud655\uc778\ud560 \uc218 \uc788\ub294 \uc791\uc740 \ubcc0\ud654\uc5d0\uc11c \uc2dc\uc791\ud558\ub294 \ubc29\ubc95\uc774\ub2e4. \uad6c\ub9ac\ud310\uc744 \ubd99\uc5ec \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \uc124\uba85\uc740 \uac89\uc758 \uc7ac\ub8cc\ubfd0 \uc544\ub2c8\ub77c \uc81c\uc791 \ubc29\uc2dd\uc744 \uc54c\ub824 \uc900\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uae08\uc18d\uc73c\ub85c \ubcf4\uc778\ub2e4\uace0 \uc18d\uae4c\uc9c0 \uaf49 \ucc2c \ubb34\uac70\uc6b4 \ub369\uc5b4\ub9ac\ub77c\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ubb3c\uc5d0 \ub728\ub294 \ubb3c\uac74\uc758 \uc131\uc9c8\uc740 \uc7ac\ub8cc \uc774\ub984 \ud558\ub098\ubcf4\ub2e4 \uc804\uccb4 \ud615\ud0dc\uc640 \ubd80\ud53c\ub3c4 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uae30\uad00 \uc124\uba85\uc740 \uc774 \ubd80\ud488\uc774 \uc2e4\uc81c\ub85c \ub5a0\uc624\ub974\ub3c4\ub85d \ub9cc\ub4e0 \ubab8\uccb4\uc600\uc74c\uc744 \uc54c\ub824 \uc900\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4\uc744 \ubcf4\uace0 \ubd80\ud53c\uc640 \ubb34\uac8c\ub97c \uc0c8\ub85c \uacc4\uc0b0\ud558\uac70\ub098 \uc815\ud655\ud55c \ubd80\ub825\uc744 \ud310\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc774 \uae00\uc740 \ubb3c\ub9ac \uc2e4\ud5d8 \uacb0\uacfc\uac00 \uc544\ub2c8\ub77c \ubc15\ubb3c\uad00\uc774 \uc18c\uac1c\ud55c \ubd80\ud488\uc758 \uad6c\uc870\ub97c \uc77d\ub294 \uc124\uba85\uc774\ub2e4. \uc791\uc740 \uc5f0\uacb0\uad6c\uc640 \ub0a0\uac1c \ubaa8\uc591\uc758 \ubd80\ubd84\uc744 \ucc28\ub840\ub85c \ubcf4\uba74 \uc870\uac01\ucc98\ub7fc \ubcf4\uc774\ub358 \uae08\uc18d \ubb3c\uac74\uc774 \ud2b9\uc815\ud55c \ud1b5\uacfc \uc7a3\ub300\uc5d0 \ub9de\ucd98 \uc7a5\uce58\ub85c \ubc14\ub010\ub2e4. \ubd80\ud45c\uc758 \ud06c\uae30\ub97c \ubb3c\uc744 \ubc1b\ub294 \ud1b5\uc758 \uc18d\ub458\ub808\uc640 \ub9de\ucd94\uc5c8\ub2e4\ub294 \uc815\ubcf4\ub294 \ub9de\ucda4\uc758 \uc911\uc694\uc131\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ubb3c\uc5d0 \ub728\uae30\ub9cc \ud558\uba74 \uc544\ubb34 \ubb3c\uac74\uc774\ub098 \uac19\uc740 \uc77c\uc744 \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub4e4\uc5b4\uac08 \uacf5\uac04\uacfc \uc6c0\uc9c1\uc77c \ubc94\uc704, \uc5f0\uacb0\ud560 \ubd80\ubd84\uc744 \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ud588\ub2e4. \uae30\uacc4\uc758 \ud55c \ubd80\ud488\uc744 \ub9cc\ub4e4 \ub54c \ub2e4\ub978 \ubd80\ud488\uc758 \uc870\uac74\uc774 \uba3c\uc800 \ub4e4\uc5b4\uc624\ub294 \uc148\uc774\ub2e4. \uadf8\ub798\uc11c \uc774 \ubb3c\uac74\uc744 \ud63c\uc790 \ub5bc\uc5b4 \ubcf4\uba74 \uc4f0\uc784\uc744 \uc54c\uc544\ubcf4\uae30 \uc5b4\ub824\uc6b8 \uc218 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc758 \uc124\uba85\uc740 \uc0ac\ub77c\uc84c\uac70\ub098 \ud568\uaed8 \uc804\uc2dc\ub418\uc9c0 \uc54a\uc740 \ub2e4\ub978 \ubd80\ubd84\uacfc\uc758 \uad00\uacc4\ub97c \uc774\uc5b4 \uc900\ub2e4. \uc18c\uc7a5\ud488\uc758 \ub2e8\uc704\uc640 \uc791\ub3d9\ud558\ub294 \uc7a5\uce58\uc758 \ub2e8\uc704\ub294 \ub2e4\ub97c \uc218 \uc788\ub2e4\ub294 \uc810\uc744 \uc54c\uba74 \ubb3c\uac74\uc758 \ud615\ud0dc\ub3c4 \ub2e4\ub974\uac8c \uc77d\ud78c\ub2e4. \uc791\uc740 \ud2c8\uacfc \uad6c\uba4d\uc5d0\ub3c4 \uc5f0\uacb0\ud560 \uc0c1\ub300\uac00 \uc788\uc5c8\ub2e4. \uc81c\ubaa9\uc758 \uac70\ubd81\uc774\ub294 \ubaa8\uc591\uc744 \uce5c\uadfc\ud558\uac8c \ubcf4\ub294 \uc785\uad6c\ub2e4. \uc2e4\uc81c \ub3d9\ubb3c\uc758 \uc0dd\ud0dc\ub97c \uc124\uba85\ud558\ub294 \ubb3c\uac74\uc740 \uc544\ub2c8\ub2e4. \uc7a5\uc2dd\uc744 \uc704\ud574 \uc218\uba74\uc5d0 \ub193\uc740 \uc870\uac01\uacfc\ub3c4 \ub2e4\ub974\ub2e4. \uae30\uad00\uc774 \ubd80\uad6c\ub098 \ubd80\uc790\ub77c\uace0 \ubd80\ub974\ub294 \uae30\ub2a5\uc801 \uba85\uce6d\uc744 \ud568\uaed8 \uc54c\uba74 \ube44\uc720\uc640 \uc2e4\uc81c \uc4f0\uc784\uc744 \ub098\ub204\uc5b4 \ubcfc \uc218 \uc788\ub2e4. \ub3d9\ubb3c\ucc98\ub7fc \ubcf4\uc778\ub2e4\ub294 \ub290\ub08c\uc744 \uc990\uae30\uba74\uc11c\ub3c4 \uae30\uacc4 \ubd80\ud488\uc774\ub77c\ub294 \uc131\uaca9\uc744 \ub193\uce58\uc9c0 \uc54a\ub294 \uac83\uc774\ub2e4. \ubb3c\uc774 \ucc28\uba74 \ub5a0\uc624\ub978\ub2e4\ub294 \uac04\ub2e8\ud55c \ubb38\uc7a5\uc744 \ub2e4\uc2dc \ub5a0\uc62c\ub824 \ubcf4\uc790. \uadf8 \uc6c0\uc9c1\uc784\uc740 \uc587\uc740 \ud310\uc758 \ubab8\uccb4\uc640 \uc54c\ub9de\uc740 \ud06c\uae30, \uc7a3\ub300\uc758 \uc5f0\uacb0\uc744 \ud1b5\ud574 \uac00\ub2a5\ud558\ub3c4\ub85d \uc900\ube44\ub418\uc5c8\ub2e4. \ud070 \uc2dc\uacc4\uc758 \uc774\ub984\ub9cc \uae30\uc5b5\ud560 \ub54c\uc5d0\ub294 \ubcf4\uc774\uc9c0 \uc54a\ub358 \uc190\uc77c\uc774\ub2e4. \uae08\uc18d\uc758 \uc791\uc740 \ud615\uc0c1\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc774 \uc2dc\uac04\uc744 \uc77d\uae30 \uc704\ud574 \uc790\uc5f0\uc758 \ubcc0\ud654\ub97c \uc5b4\ub5a4 \uc6c0\uc9c1\uc784\uc73c\ub85c \ubc14\uafb8\uc5c8\ub294\uc9c0 \ub9cc\ub098\uac8c \ub41c\ub2e4. \uc774 \ubd80\ud45c\ub9cc\uc73c\ub85c \uc790\uaca9\ub8e8 \uc804\uccb4\uc758 \uc791\ub3d9\uc744 \ubaa8\ub450 \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc885\uc774 \uc6b8\ub9ac\ub294 \uacfc\uc815\uc774\ub098 \uc2dc\uac04\uc744 \uc54c\ub9ac\ub294 \uc7a5\uce58\uc5d0\ub294 \ub2e4\ub978 \ubd80\ud488\ub3c4 \ud544\uc694\ud558\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4 \uc18d \ub465\uadfc \ubb3c\uac74\uc774 \ud63c\uc790 \ub5a0 \uc788\ub294 \uc7a5\uc2dd\ud488\uc774 \uc544\ub2c8\ub77c\ub294 \uc0ac\uc2e4\uc740 \ubd84\uba85\ud574\uc9c4\ub2e4. \uac00\uc6b4\ub370\uc758 \uc5f0\uacb0\uad6c, \uc606\uc73c\ub85c \ub098\uc628 \ub124 \ub0a0\uac1c, \ud1b5\uc5d0 \ub4e4\uc5b4\uac08 \ud06c\uae30. \uadf8\ub7f0 \ud2b9\uc9d5\uc744 \ucc28\ub840\ub85c \ubcf4\uba74 \ubd80\ud488\uc774 \uc65c \uadf8 \ubaa8\uc591\uc778\uc9c0 \uad81\uae08\ud574\uc9c4\ub2e4. \uc2dc\uac04\uc744 \uc7ac\ub294 \ubb3c\uac74 \uc548\uc5d0\ub3c4 \ubb3c \uc704\ub85c \ucc9c\ucc9c\ud788 \ub5a0\uc624\ub974\ub294 \uac70\ubd81\uc774 \uac19\uc740 \ubd80\ud488\uc774 \uc788\uc5c8\ub2e4."}, {"id": "appert-bottles-heat-and-preserving-food", "title": "\uc544\ud398\ub974\uc758 \uc720\ub9ac\ubcd1 \u2014 \uc74c\uc2dd\uc740 \uc5b4\ub5bb\uac8c \uacc4\uc808\uc744 \ub118\uc5b4\uac14\uc744\uae4c", "summary": "\uc544\ud398\ub974\uc758 \uc720\ub9ac\ubcd1\uacfc \uc815\ubd80 \ud3c9\uac00 \ubb38\uc11c\ub85c \uc74c\uc2dd\uc758 \uacc4\uc808\uacfc \uc774\ub3d9\uc744 \ubc14\uafb8\ub824 \ud55c \uae30\uc220\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\uc2dd\ud0c1\uacfc \uc2dd\ud488 \ubcf4\uc874", "categories": ["everyday-inventions"], "url": "stories/appert-bottles-heat-and-preserving-food/index.html", "image": "../media/appert-bottles-heat-and-preserving-food.png", "alt": "\ub9c8\uac1c\ub97c \ub2eb\uc740 \uc720\ub9ac\ubcd1\uacfc \uc2dd\ud488\uc744 \uc0b4\ud53c\ub294 \uc544\ud398\ub974 \uc2dc\ub300 \uc791\uc5c5\uc7a5\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uc544\ud398\ub974\uc758 \uc720\ub9ac\ubcd1 \u2014 \uc74c\uc2dd\uc740 \uc5b4\ub5bb\uac8c \uacc4\uc808\uc744 \ub118\uc5b4\uac14\uc744\uae4c \uac00\uc5f4\uacfc \ubc00\ubd09, \uc6a9\uae30\uc640 \uacf5\uac1c \ubb38\uc11c\uac00 \uc5f0\uacb0\ud55c \uc2dd\ud488\uc758 \uc2dc\uac04 \uc544\ud398\ub974\uc758 \uc720\ub9ac\ubcd1\uacfc \uc815\ubd80 \ud3c9\uac00 \ubb38\uc11c\ub85c \uc74c\uc2dd\uc758 \uacc4\uc808\uacfc \uc774\ub3d9\uc744 \ubc14\uafb8\ub824 \ud55c \uae30\uc220\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc2dd\ud0c1\uacfc \uc2dd\ud488 \ubcf4\uc874 \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \uacfc\uc77c\uacfc \ucc44\uc18c, \uc870\ub9ac\ud55c \uc74c\uc2dd\uc740 \uc2dc\uac04\uc774 \uc9c0\ub098\uba74 \ub2ec\ub77c\uc9c4\ub2e4. \ud48d\uc131\ud55c \ub54c\uc758 \uc74c\uc2dd\uc744 \ub2e4\ub978 \uacc4\uc808\uc774\ub098 \uba3c \uacf3\uc5d0\uc11c\ub3c4 \uba39\uace0 \uc2f6\ub2e4\ub294 \ubc14\ub78c\uc740 \uc624\ub798\ub41c \uae30\uc220\uc758 \ub3d9\uae30\uc600\ub2e4. \ub2c8\ucf5c\ub77c \uc544\ud398\ub974\uc758 \uc2dd\ud488 \ubcf4\uc874 \ucc45\uc5d0\ub294 \uac00\uc5f4\uacfc \ubc00\ubd09, \uc6a9\uae30\uc758 \uc0c1\ud0dc\ub97c \ud568\uaed8 \ub2e4\ub8e8\ub824 \ud55c \ub178\ub825\uc774 \ub2f4\uaca8 \uc788\ub2e4. \uae08\uc18d \uce94\ub9cc\uc73c\ub85c \uae30\uc5b5\ud558\uae30 \uc26c\uc6b4 \ubcf4\uc874 \uae30\uc220\uc758 \uc55e\ubd80\ubd84\uc744 \uc0b4\ud3b4\ubcf4\uc790. \uc544\ud398\ub974\uc758 \uc124\uba85\uc5d0\uc11c \ub450\uaebc\uc6b4 \uc720\ub9ac\ubcd1\uacfc \ub9c8\uac1c\ub294 \uc911\uc694\ud55c \ub3c4\uad6c\ub2e4. \uc624\ub298 \ud1b5\uc870\ub9bc\uc744 \ub5a0\uc62c\ub9b4 \ub54c \ubcf4\uc774\ub294 \uae08\uc18d \uc6a9\uae30\uc640 \ucd9c\ubc1c\uc810\uc774 \uac19\uc9c0 \uc54a\ub2e4. \uc2dd\ud488\uc744 \ub2f4\uace0 \ucc98\ub9ac\ud558\ub294 \ubc29\ubc95\uc758 \ubc1c\uc804\uacfc \uc6a9\uae30\uc758 \uc7ac\ub8cc\uac00 \ubc14\ub00c\ub294 \uacfc\uc815\uc740 \uad6c\ubd84\ud574\uc11c \ubcfc \uc218 \uc788\ub2e4. \ubcd1\uc758 \ubaa8\uc591\uacfc \uc785\uad6c, \ub9c8\uac1c\ub97c \ub2eb\ub294 \uc0c1\ud0dc\ub3c4 \uacb0\uacfc\uc5d0 \uc601\ud5a5\uc744 \uc8fc\uc5c8\ub2e4. \uc6a9\uae30\ub294 \uc74c\uc2dd\uc744 \ub2f4\uc544 \ub450\ub294 \uc218\ub3d9\uc801\uc778 \ubc30\uacbd\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ubc14\uae65\uacfc \uc548\ucabd\uc758 \uad00\uacc4\ub97c \ud1b5\uc81c\ud558\ub294 \ub3c4\uad6c\uc600\ub2e4. \uc2dd\ud488 \uae30\uc220\uc744 \uc7ac\ub8cc\uc758 \uc870\ub9ac\ubc95\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b4 \uc774\uc720\ub2e4. \uc544\ud398\ub974\ub294 \uc74c\uc2dd\uc744 \uc6a9\uae30\uc5d0 \ub2f4\uace0 \uac00\uc5f4\ud558\uba70 \ub2eb\ud78c \uc0c1\ud0dc\ub97c \uc720\uc9c0\ud558\ub294 \ubc29\ubc95\uc744 \uc815\ub9ac\ud588\ub2e4. \uc5b4\ub290 \ud55c \uc694\uc18c\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uac83\uc744 \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \ucda9\ubd84\ud788 \ucc98\ub9ac\ub41c \ub0b4\uc6a9\ubb3c\uacfc \uadf8 \ub4a4\uc5d0 \uc678\ubd80\uc758 \uc601\ud5a5\uc744 \uc81c\ud55c\ud558\ub294 \uc0c1\ud0dc\uac00 \ud568\uaed8 \ud544\uc694\ud588\ub2e4. \uc774\ub97c \uacf5\uae30\ub97c \ube7c\uae30\ub9cc \ud558\uba74 \uc5b4\ub5a4 \uc74c\uc2dd\ub3c4 \uc624\ub798\uac04\ub2e4\ub294 \uc8fc\uc7a5\uc73c\ub85c \uc904\uc774\uba74 \uc798\ubabb\uc774\ub2e4. \uc74c\uc2dd\uc758 \uc131\uc9c8\uacfc \uc6a9\uae30\uc758 \uc870\uac74, \ucc98\ub9ac \ubc29\uc2dd\uc774 \uad00\uacc4\ub41c\ub2e4. \ucc45\uc758 \uc5ed\uc0ac\uc801 \uc758\ubbf8\ub294 \uc5ec\ub7ec \uc885\ub958\uc758 \uc74c\uc2dd\uc5d0 \ub300\ud574 \uad00\ucc30\uacfc \uc2dc\ud5d8\uc744 \uc774\uc5b4 \uac14\ub2e4\ub294 \ub370 \uc788\ub2e4. \ud55c \uac00\uc9c0 \ub2e8\uc21c\ud55c \ube44\ubc00\uc744 \ubc1c\uacac\ud55c \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \ub9c8\uac1c\uc640 \uc6a9\uae30\uc5d0 \ubb38\uc81c\uac00 \uc0dd\uae30\uba74 \uc548\ucabd\uc758 \uc0c1\ud0dc\ub3c4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ubcf4\uc874\uc740 \uc870\ub9ac\ud558\ub294 \uc21c\uac04\ub9cc\uc758 \uc77c\uc774 \uc544\ub2c8\ub77c \ucc98\ub9ac \ub4a4\uc5d0\ub3c4 \uc870\uac74\uc744 \uc720\uc9c0\ud558\ub294 \uc77c\uc774\ub2e4. \ubb3c\uac74\uc744 \ubcf4\uad00\ud558\uace0 \uc62e\uae30\ub294 \ub2e8\uacc4\uae4c\uc9c0 \uae30\uc220\uc758 \ubc94\uc704\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uac19\uc740 \ub0b4\uc6a9\ubb3c\uc744 \ub123\uc5b4\ub3c4 \uc6a9\uae30\uc758 \uc0c1\ud0dc\uac00 \ub2e4\ub974\uba74 \uacb0\uacfc\uac00 \uac19\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uc774\ub294 \uc74c\uc2dd\uc758 \ubcc0\ud654\uc640 \uadf8 \uc74c\uc2dd\uc744 \ub458\ub7ec\uc2fc \uc2dc\uc2a4\ud15c\uc744 \ud568\uaed8 \ubcf4\uac8c \ud55c\ub2e4. \ubcf4\uc874 \uae30\uc220\uc740 \uc88b\uc740 \uc7ac\ub8cc\ub97c \uace0\ub974\ub294 \uc9c0\uc2dd\uacfc \uc6a9\uae30\ub97c \ub2e4\ub8e8\ub294 \uc219\ub828\uc774 \ub9cc\ub098\ub294 \uc790\ub9ac\uc600\ub2e4. \uc544\ud398\ub974\uc758 \ucc45\uc5d0\ub294 1810\ub144 \ud504\ub791\uc2a4 \uc815\ubd80\uac00 \uadf8\uc758 \ubc29\ubc95\uc744 \uac80\ud1a0\ud558\uace0 \ubcf4\uc0c1\ud55c \ubb38\uc11c\uac00 \uc2e4\ub824 \uc788\ub2e4. \uc720\uc6a9\ud55c \ubc29\ubc95\uc744 \uacf5\uac1c\ud574 \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc774\uc6a9\ud558\ub3c4\ub85d \ud558\ub294 \uc77c\uc774 \uad6d\uac00\uc801 \uad00\uc2ec\uacfc \uc5f0\uacb0\ub418\uc5c8\ub2e4. \uac1c\uc778\uc758 \uacbd\ud5d8\uc774 \ucd9c\ud310\ub41c \uc124\uba85\uc73c\ub85c \ubc14\ub00c\ub294 \uacfc\uc815\uc774\ub2e4. \uc774 \ubb38\uc11c\ub97c \uc77d\uc73c\uba74 \ubc1c\uba85\uc758 \uc131\uacf5\uc774 \uc2e4\ud5d8\uc2e4\uc758 \uacb0\uacfc\uc5d0\ub9cc \uc788\uc9c0 \uc54a\uc74c\uc744 \uc54c \uc218 \uc788\ub2e4. \uad00\uacc4\uc790\uac00 \uc2dc\ud5d8\ud558\uace0 \ud3c9\uac00\ud558\uba70 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \uc54c\ub9b4\uc9c0 \uc815\ud574\uc57c \ud588\ub2e4. \ubcf4\uc874 \uae30\uc220\uc740 \uad70\ub300\uc640 \ud56d\ud574, \uae34 \uc6b4\uc1a1\ucc98\ub7fc \uc74c\uc2dd\uc744 \uacc4\uc18d \uacf5\uae09\ud574\uc57c \ud558\ub294 \uc0c1\ud669\uc5d0\uc11c\ub3c4 \uc758\ubbf8\uac00 \uc788\uc5c8\ub2e4. \ubc29\ubc95\uc744 \uae00\ub85c \uc54c\ub9ac\ub294 \uc77c\uc5d0\ub3c4 \uc5b4\ub824\uc6c0\uc774 \uc788\ub2e4. \uc2e4\uc81c \uc791\uc5c5\uc790\uac00 \uc190\uc73c\ub85c \ud310\ub2e8\ud558\ub358 \ubd80\ubd84\uc744 \ub0af\uc120 \ub3c5\uc790\uc5d0\uac8c \uc804\ub2ec\ud574\uc57c \ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \uc6a9\uae30\uc640 \ub9c8\uac1c\ub97c \uc5b4\ub5a4 \uc0c1\ud0dc\ub85c \ub2e4\ub8e8\uc5c8\ub294\uc9c0 \uc124\uba85\ud558\uc9c0 \uc54a\uc73c\uba74 \uac19\uc740 \uc774\ub984\uc758 \ubc29\ubc95\uc744 \ub530\ub77c\ub3c4 \uacb0\uacfc\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ucd9c\ud310\uc740 \uacbd\ud5d8\uc744 \ub2e4\ub978 \uc7a5\uc18c\ub85c \uc62e\uae30\uae30 \uc704\ud55c \ub610 \ud558\ub098\uc758 \uae30\uc220\uc774\uc5c8\ub2e4. \uc544\ud398\ub974\uc758 \ucc45\uc5d0\ub294 \uc790\uc2e0\uc758 \uc8fc\uc7a5\ubfd0 \uc544\ub2c8\ub77c \uad00\uacc4 \uae30\uad00\uc758 \ud3b8\uc9c0\uc640 \ubcf4\uace0\uac00 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4. \ub204\uac00 \uc5b4\ub5a4 \uadfc\uac70\ub85c \uc131\uacfc\ub97c \ud3c9\uac00\ud588\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub824\ub294 \uad6c\uc131\uc774\ub2e4. \ubb3c\ub860 \uadf8 \ubb38\uc11c\uac00 \uc624\ub298\uc758 \ubaa8\ub4e0 \ubcf4\uad00 \uc870\uac74\uc744 \ub300\uc2e0 \uc99d\uba85\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5ed\uc0ac \uc790\ub8cc\ub85c\uc11c\ub294 \uc0c8\ub85c\uc6b4 \ubc29\ubc95\uc774 \uc778\uc815\ub418\uace0 \uc54c\ub824\uc9c0\ub294 \uacfc\uc815\uc5d0\uc11c \uc2dc\ud5d8\uacfc \uc99d\uc5b8, \uc81c\ub3c4\uc801 \ud3c9\uac00\uac00 \uc5b4\ub5bb\uac8c \ubb36\uc600\ub294\uc9c0 \uc0b4\ud544 \uc218 \uc788\ub2e4. \ubc1c\uba85\uacfc \uacf5\uc801\uc778 \uc2e0\ub8b0\uac00 \ub9cc\ub098\ub294 \uc790\ub9ac\uac00 \ucc45 \uc548\uc5d0 \ub0a8\uc740 \uc148\uc774\ub2e4. \uc544\ud398\ub974\uac00 \ud65c\ub3d9\ud558\ub358 \ub54c\uc758 \uc124\uba85\uc744 \uc624\ub298\uc758 \ubbf8\uc0dd\ubb3c\ud559\uacfc \uac19\ub2e4\uace0 \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uc5b4\ub5a4 \uc870\uc791\uc774 \ud6a8\uacfc\uac00 \uc788\uc74c\uc744 \uc544\ub294 \uac83\uacfc \uadf8 \uc6d0\uc778\uc744 \ud604\uc7ac\uc758 \uc5b8\uc5b4\ub85c \uc124\uba85\ud560 \uc218 \uc788\ub294 \uac83\uc740 \ub2e4\ub978 \ub2e8\uacc4\ub2e4. \uae30\uc220\uc758 \uc2e4\uc6a9\uc801 \uc131\uacfc\uac00 \uc774\ub860\uc801 \uc774\ud574\uc640 \uaf2d \uac19\uc740 \uc18d\ub3c4\ub85c \uc9c4\ud589\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub4a4\uc758 \uc5f0\uad6c\ub294 \uc2dd\ud488\uc774 \ubcc0\ud558\ub294 \uc774\uc720\uc640 \uc5f4\ucc98\ub9ac\ub97c \ub354 \uc815\ubc00\ud558\uac8c \uc774\ud574\ud558\uac8c \ud588\ub2e4. \ub530\ub77c\uc11c \uc624\ub798\ub41c \ucc45\uc758 \ubc29\ubc95\uc744 \uc624\ub298 \ubaa8\ub4e0 \uc2dd\ud488\uc758 \ubcf4\uad00 \uc870\uac74\uc73c\ub85c \uadf8\ub300\ub85c \uc62e\uae38 \uc218\ub294 \uc5c6\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \uadf8 \ucc45\uc744 \ud604\uc7ac\uc758 \uc870\ub9ac \uc9c0\uce68\uc774 \uc544\ub2c8\ub77c \uad00\ucc30\uacfc \uac00\uacf5\uc758 \uc5ed\uc0ac\ub85c \uc77d\ub294\ub2e4. \ubcf4\uc874\ud560 \uc218 \uc788\ub294 \uc2dc\uac04\uc774 \ub298\uc5b4\ub098\uba74 \uc74c\uc2dd\uc744 \uba39\ub294 \uc7a5\uc18c\uc640 \uc218\ud655\ud55c \ub54c\uc758 \uad00\uacc4\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc0dd\uc0b0\uc9c0\uc5d0\uc11c \ubc14\ub85c \uba39\ub294 \ubc29\uc2dd \uc678\uc758 \uc120\ud0dd\uc774 \uc0dd\uae34\ub2e4. \ub2e4\ub9cc \uae30\uc220 \ud558\ub098\uac00 \uae30\uadfc\uacfc \uc6b4\uc1a1, \ube44\uc6a9\uc758 \ubaa8\ub4e0 \ubb38\uc81c\ub97c \ud574\uacb0\ud588\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc6a9\uae30\uc640 \uac00\uacf5 \uc2dc\uc124, \uac80\uc0ac\uc640 \uc6b4\uc1a1\uc774 \ud568\uaed8 \ud544\uc694\ud558\ub2e4. \uc81c\ud488\uc774 \uba3c \uacf3\uc5d0 \ub3c4\ucc29\ud574\ub3c4 \uc0ac\ub78c\ub4e4\uc774 \uc0b4 \uc218 \uc788\ub294 \uac00\uaca9\uc774\uc5b4\uc57c \ud55c\ub2e4. \uc544\ud398\ub974\uc758 \uc720\ub9ac\ubcd1 \ub4a4\uc5d0\ub294 \uc74c\uc2dd\uc744 \uc624\ub798 \ub450\ub824\ub294 \ubc1c\uc0c1\uc5d0\uc11c \uc2e4\uc81c \uacf5\uae09 \uccb4\uacc4\ub85c \ub118\uc5b4\uac00\ub294 \ub354 \uae34 \uacfc\uc815\uc774 \uc774\uc5b4\uc838 \uc788\uc5c8\ub2e4. \uc624\ub298 \uc775\uc219\ud55c \uc800\uc7a5 \uc2dd\ud488\uc744 \ubcf4\uba74 \ud3ec\uc7a5\uc758 \ud3b8\ub9ac\ud568\uc774 \uba3c\uc800 \ub290\uaef4\uc9c4\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uc548\uc5d0\ub294 \uc74c\uc2dd\uc774 \ubcc0\ud558\ub294 \uc870\uac74\uc744 \uc54c\uc544\ub0b4\uace0 \uc678\ubd80\uc640\uc758 \uad00\uacc4\ub97c \uc870\uc808\ud558\ub824 \ud55c \uc5ed\uc0ac\uac00 \uc788\ub2e4. \uc720\ub9ac\ubcd1\uacfc \ub9c8\uac1c\ub294 \uadf8 \uc9c8\ubb38\uc744 \uad6c\uccb4\uc801\uc778 \ubb3c\uac74\uc73c\ub85c \ub9cc\ub4e0 \ub3c4\uad6c\uc600\ub2e4. \uc544\ud398\ub974\uc758 \uc774\uc57c\uae30\ub294 \ubc1c\uba85\uc774 \ud604\uc7ac\uc758 \uc81c\ud488 \ubaa8\uc591\uacfc \ub2e4\ub974\uac8c \uc2dc\uc791\ud560 \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uac19\uc740 \ubaa9\uc801\uc744 \ud5a5\ud574 \uc6a9\uae30\uc640 \uac00\uacf5\ubc95\uc774 \ub2ec\ub77c\uc838 \uc654\ub2e4. \ubcf4\uad00\ud560 \uc2dc\uac04\uc744 \ub298\ub9b0\ub2e4\ub294 \ubaa9\ud45c\uc5d0\ub294 \ub2f4\uace0 \ub2eb\uace0 \uc62e\uae30\ub294 \ubaa8\ub4e0 \ub2e8\uacc4\uc758 \uad00\uacc4\uac00 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \uacc4\uc808\uc744 \ub118\uc5b4 \uc74c\uc2dd\uc744 \uc62e\uae30\ub294 \uc77c\uc740 \ub0b4\uc6a9\ubb3c\ubfd0 \uc544\ub2c8\ub77c \uadf8\uac83\uc744 \ub458\ub7ec\uc2fc \ud658\uacbd\uae4c\uc9c0 \ud568\uaed8 \uc124\uacc4\ud558\ub294 \uc77c\uc774\uc5c8\ub2e4."}, {"id": "brazier-animal-feet", "title": "\ud654\ub85c \uc544\ub798\uc5d0 \uc791\uc740 \uc9d0\uc2b9\uc758 \ubc1c\uc774 \uc788\ub2e4", "summary": "\ud3c9\ubc94\ud55c \uc138 \ubc1c\ucc98\ub7fc \ubcf4\uc774\ub358 \ud654\ub85c \ub2e4\ub9ac\uc5d0 \uc5bc\uad74\uacfc \ubc1c\uc774 \uc228\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\uc9d1\uacfc \uc0dd\ud65c \ub3c4\uad6c", "categories": ["everyday-inventions"], "url": "stories/brazier-animal-feet/index.html", "image": "../media/brazier-animal-feet.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc0bc\uc871\ud654\ub85c \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\ud654\ub85c \uc544\ub798\uc5d0 \uc791\uc740 \uc9d0\uc2b9\uc758 \ubc1c\uc774 \uc788\ub2e4 \ub530\ub73b\ud568\uc744 \ub2f4\ub294 \uadf8\ub987\uc758 \ub73b\ubc16\uc758 \ud45c\uc815 \ud3c9\ubc94\ud55c \uc138 \ubc1c\ucc98\ub7fc \ubcf4\uc774\ub358 \ud654\ub85c \ub2e4\ub9ac\uc5d0 \uc5bc\uad74\uacfc \ubc1c\uc774 \uc228\uc5b4 \uc788\uc2b5\ub2c8\ub2e4. \uc9d1\uacfc \uc0dd\ud65c \ub3c4\uad6c \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \ub465\uadfc \ud654\ub85c \ud55c \uc810\uc774 \ub193\uc5ec \uc788\ub2e4. \uac00\uc6b4\ub370\ub294 \uae4a\uac8c \ud30c\uc600\uace0 \uac00\uc7a5\uc790\ub9ac\ub294 \ub113\uac8c \ubc8c\uc5b4\uc84c\ub2e4. \uc704\uc5d0\uc11c \ubcf4\uba74 \uaf64 \uc58c\uc804\ud55c \ubb3c\uac74\uc778\ub370, \uc2dc\uc120\uc744 \uc544\ub798\ub85c \ub0b4\ub9ac\uba74 \ubd84\uc704\uae30\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uc138 \ub2e4\ub9ac\uac00 \uc791\uc740 \uc9d0\uc2b9\ucc98\ub7fc \uc0dd\uacbc\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc18c\uc7a5\ud55c \uc0bc\uc871\ud654\ub85c\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc601\uce5c\uc655\ube44 \uc774\ubc29\uc790\uac00 \uc18c\uc720\ud588\ub358 \ubb3c\uac74\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \uac70\ucc3d\ud55c \uc758\ub840 \uc7a5\uba74\uc744 \uc0c1\uc0c1\ud558\uae30 \uc804\uc5d0, \uba3c\uc800 \uadf8 \ubc1c\ubd80\ud130 \uc0b4\ud3b4\ubcf4\uba74 \uc88b\uaca0\ub2e4. \ub2e4\ub9ac\uc758 \uc704\ucabd\uc5d0\ub294 \ubfd4\uc774 \ub450 \uac1c \ub2ec\ub9b0 \uc5bc\uad74\uc774 \ud45c\ud604\ub418\uc5b4 \uc788\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc758 \uc774\ub984\uc740 \uadc0\uba74\uc774\ub2e4. \ub0af\uc120 \ub2e8\uc5b4\uc9c0\ub9cc \uc0ac\uc9c4\uacfc \ud568\uaed8 \ubcf4\uba74 \uc870\uae08 \uc27d\ub2e4. \ub2e4\ub9ac\uc640 \ubab8\ud1b5\uc774 \ub9cc\ub098\ub294 \uacf3\uc5d0 \uc785\uccb4\uc801\uc778 \uc5bc\uad74\uc774 \ub193\uc5ec \uc788\ub2e4\ub294 \ub73b\uc774\ub2e4. \uadf8 \uc544\ub798\ub294 \ub3d9\ubb3c\uc758 \ubc1c \ud615\ud0dc\ub85c \ub9cc\ub4e4\uc5c8\ub2e4. \uc5bc\uad74\uc774 \uc788\uace0 \ubc1c\uc774 \uc788\uc73c\ub2c8 \ub2e8\uc21c\ud788 \ubc1b\uce68 \uc138 \uac1c\ub97c \ubd99\uc778 \uac83\uacfc\ub294 \uc778\uc0c1\uc774 \ub2e4\ub974\ub2e4. \ub465\uadfc \ubab8\uccb4\ub97c \uc791\uc740 \uc0dd\ubb3c\ub4e4\uc774 \ubc1b\ub4e4\uace0 \uc788\ub294 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \uc774\uac83\uc740 \ubaa8\uc591\uc5d0\uc11c \uc5bb\ub294 \uac10\uc0c1\uc774\uc9c0, \ud2b9\uc815 \ub3d9\ubb3c\uc744 \ud655\uc778\ud588\ub2e4\ub294 \uc774\uc57c\uae30\ub294 \uc544\ub2c8\ub2e4. \ud654\ub85c\ub294 \uad6c\ub9ac\ub85c \ub9cc\ub4e0 \ubab8\uccb4\uc5d0 \uc138 \uac1c\uc758 \ub2e4\ub9ac\uac00 \ub2ec\ub9b0 \uad6c\uc870\ub2e4. \ubc15\ubb3c\uad00\uc740 \ub2e4\ub9ac\ub97c \ub530\ub85c \uc8fc\uc870\ud55c \ub2e4\uc74c \ub9ac\ubcb3\uc73c\ub85c \ubab8\uccb4\uc5d0 \ubd99\uc600\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uba40\ub9ac\uc11c\ub294 \ud55c \ub369\uc5b4\ub9ac \uac19\uc544\ub3c4 \ub9cc\ub4dc\ub294 \uacfc\uc815\uc5d0\uc11c\ub294 \ubd80\ud488\uc774 \ub098\ub258\uc5c8\ub358 \uac83\uc774\ub2e4. \ub113\uc740 \ud14c\ub450\ub9ac \ub05d\uc5d0\ub294 \ub465\uae00\uac8c \ud131\ub3c4 \uc84c\ub2e4. \ubab8\uccb4\uc640 \ub2e4\ub9ac, \uac00\uc7a5\uc790\ub9ac\ub97c \ucc28\ub840\ub85c \ubcf4\uba74 \ud070 \ubaa8\uc591 \uc548\uc5d0 \uc11c\ub85c \ub2e4\ub978 \uc791\uc5c5\uc774 \ub4e4\uc5b4 \uc788\uc74c\uc744 \uc54c\uac8c \ub41c\ub2e4. \uc7a5\uc778\uc758 \uc190\uae38\uc744 \ucc3e\ub294 \ub370 \ubc18\ub4dc\uc2dc \ubcf5\uc7a1\ud55c \ubb38\uc591\ubd80\ud130 \uc77d\uc5b4\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud654\ub85c\uc758 \ub2e4\ub9ac\ub294 \uc7a5\uc2dd\uc778 \ub3d9\uc2dc\uc5d0 \ubab8\uccb4\ub97c \uc138\uc6b0\ub294 \ubd80\ubd84\uc774\ub2e4. \uc138 \uac1c\uc758 \ubc1b\uce68\uc774 \uc5b4\ub514\uc5d0 \ubd99\ub294\uc9c0 \ubcf4\uba74 \ub465\uadfc \uc6a9\uae30\uc640 \ubc14\ub2e5\uc758 \uad00\uacc4\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \uc815\uba74\uc758 \ubb34\ub2ac\ub9cc \ubcf4\uc558\uc744 \ub54c\uc640 \ub2e4\ub978 \uad6c\uc870\uc758 \uc9c8\ubb38\uc774 \uc0dd\uae34\ub2e4. \ub2e4\ub9cc \uc2e4\uc81c \uc548\uc815\uc131\uacfc \ubb34\uac8c \uc911\uc2ec\uc744 \uc0ac\uc9c4\ub9cc\uc73c\ub85c \uce21\uc815\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ud615\ud0dc\ub97c \uc774\ud574\ud558\ub294 \uad00\ucc30\uacfc \uacf5\ud559\uc801 \uac80\uc0ac\ub294 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc0bc\uc871\uc774\ub77c\ub294 \ub9d0\uc740 \ubc14\ub85c \uc774\ub7f0 \uc138 \ub2e4\ub9ac\uc758 \uad6c\uc131\uc744 \uac00\ub9ac\ud0a8\ub2e4. \uc774\ub984\uc744 \uc54c\uba74 \ub0af\uc120 \uc804\ubb38 \uc6a9\uc5b4\uac00 \ub208\uc55e\uc758 \uac1c\uc218\uc640 \uc5f0\uacb0\ub41c\ub2e4. \uc804\uccb4\ub97c \ud55c \ubc88 \ubcf8 \ub4a4 \ubab8\uccb4\uc640 \ub2e4\ub9ac\uac00 \ub9cc\ub098\ub294 \uc790\ub9ac\ub97c \uc0b4\ud3b4\ubcf4\uc790. \uae08\uc18d \ubb3c\uac74\uc758 \ud070 \uc724\uacfd\uc774 \uc5ec\ub7ec \ubd80\ud488\uc758 \uad00\uacc4\ub85c \ub098\ub258\uae30 \uc2dc\uc791\ud55c\ub2e4. \uc18c\uc7a5\ud488\uc758 \uc774\ub984\ub3c4 \uad00\ucc30\uc758 \uc21c\uc11c\ub97c \ub9cc\ub4e4\uc5b4 \uc904 \uc218 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc740 \ub2e4\ub9ac\ub97c \ubcc4\ub3c4\ub85c \uc8fc\uc870\ud55c \ub4a4 \ub9ac\ubcb3\uc73c\ub85c \ubd99\uc600\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubab8\uccb4\uc640 \ub2e4\ub9ac\uc758 \uc81c\uc791\uc744 \ub098\ub204\uace0 \ub098\uc911\uc5d0 \uc5f0\uacb0\ud558\ub294 \uacfc\uc815\uc774 \uc788\uc5c8\ub2e4\ub294 \ub73b\uc774\ub2e4. \uc644\uc131\ud488\uc5d0\uc11c \uae08\uc18d\uc774 \uc774\uc5b4\uc838 \ubcf4\uc778\ub2e4\uace0 \ucc98\uc74c\ubd80\ud130 \ud55c \ub369\uc5b4\ub9ac\ub85c \ubaa8\ub450 \ub9cc\ub4e4\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc774\uc74c\uc758 \uc815\ubcf4\ub294 \ub208\uc5d0 \ubcf4\uc774\ub294 \uc678\ud615\uacfc \uc81c\uc791\uc758 \uc2dc\uac04\uc744 \uc774\uc5b4 \uc900\ub2e4. \ub9ac\ubcb3\uc740 \ubd80\ud488\uc744 \uace0\uc815\ud558\ub294 \ub370 \uc4f0\ub294 \uae08\uc18d \uc5f0\uacb0 \uc694\uc18c\ub2e4. \uadf8\ub7ec\ub098 \uc774 \ubb3c\uac74\uc758 \ubaa8\ub4e0 \uce58\uc218\uc640 \uc791\uc5c5 \uc21c\uc11c\ub97c \uc0ac\uc9c4\uc5d0\uc11c \uc0c8\ub85c \ubcf5\uc6d0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uae30\uad00\uc774 \ud655\uc778\ud55c \uc5f0\uacb0 \ubc29\uc2dd\uc744 \uc54c\uba74 \uc5b4\ub290 \ubd80\ubd84\uc744 \ub354 \uc0b4\ud3b4\ubcfc\uc9c0 \uc54c \uc218 \uc788\ub2e4. \uc7a5\uc2dd\uc5d0\ub9cc \uba38\ubb3c\ub358 \uc2dc\uc120\uc774 \uc811\ud569 \ubd80\uadfc\uc73c\ub85c \uc62e\uaca8 \uac04\ub2e4. \uae30\uc220\uc758 \ud754\uc801\uc740 \ud654\ub824\ud55c \uba74\uc758 \ubc14\uae65\uc5d0\ub3c4 \uc788\ub2e4. \ub2e4\ub9ac \uc704\uc758 \uc5bc\uad74\uacfc \uc544\ub798\uc758 \ubc1c\uc740 \uace7\uac8c \uc790\ub978 \uae30\ub465\uacfc \ub2e4\ub978 \ud45c\uc815\uc744 \uc900\ub2e4. \ubab8\uccb4\ub97c \ubc1b\uce58\ub294 \ubd80\ubd84\uc774 \uc0b4\uc544 \uc788\ub294 \uc874\uc7ac\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \uc774\uac83\uc740 \ubb3c\uac74\uc758 \ubaa8\uc591\uc5d0\uc11c \uc5bb\ub294 \uac10\uc0c1\uc774\uba70 \ud2b9\uc815 \ub3d9\ubb3c\uc758 \uc885\ub958\uc640 \uc758\ubbf8\ub97c \ud655\uc815\ud588\ub2e4\ub294 \uc8fc\uc7a5\uc740 \uc544\ub2c8\ub2e4. \uae30\uad00\uc774 \uadc0\uba74\uc774\ub77c\uace0 \ubd80\ub978 \ud615\uc0c1\uc744 \uba3c\uc800 \uae30\uc900\uc73c\ub85c \uc0bc\ub294\ub2e4. \ub9cc\uc57d \uc5bc\uad74\ub9cc \ud655\ub300\ud574\uc11c \ubcf4\uba74 \uc804\uccb4 \ub2e4\ub9ac\uc758 \uc5ed\ud560\uc740 \ubc30\uacbd\uc73c\ub85c \ubb3c\ub7ec\ub09c\ub2e4. \ubc18\ub300\ub85c \uba40\ub9ac\uc11c \ubc1b\uce68\ub9cc \ubcf4\uba74 \uadf8 \ud45c\uc815\uc774 \uc0ac\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ub450 \ubcf4\uae30\ub97c \uc624\uac00\uba74 \uae30\ub2a5\uacfc \ud615\uc0c1\uc774 \uc5b4\ub5bb\uac8c \uac19\uc740 \uc790\ub9ac\uc5d0\uc11c \ub9cc\ub0ac\ub294\uc9c0 \ubcf4\uc778\ub2e4. \uc870\uac01\ucc98\ub7fc \uac10\uc0c1\ud560 \ubd80\ubd84\uc774 \ub3c4\uad6c\ub97c \uc9c0\ud0f1\ud558\ub294 \ubd80\ud488 \uc548\uc5d0\ub3c4 \ub193\uc5ec \uc788\uc5c8\ub2e4\ub294 \uc810\uc774 \uc7ac\ubbf8\uc788\ub2e4. \uc774\ubc29\uc790\uac00 \uc18c\uc720\ud588\ub358 \uc720\ud488\uc774\ub77c\ub294 \uc815\ubcf4\ub294 \ubb3c\uac74\uc758 \uc804\ub798\uc640 \uc778\ubb3c\uc744 \uc5f0\uacb0\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc5b4\ub290 \ub0a0 \ubb34\uc5c7\uc744 \ub123\uace0 \ub204\uad6c\uc640 \ud568\uaed8 \uc0ac\uc6a9\ud588\ub294\uc9c0\uae4c\uc9c0 \uc54c \uc218\ub294 \uc5c6\ub2e4. \uc54c\ub824\uc9c4 \uc18c\uc720 \uad00\uacc4\uc640 \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \uc0dd\ud65c\uc758 \uc7a5\uba74\uc744 \ub098\ub204\uc5b4 \uc77d\uc73c\uba74 \ubb34\ub9ac\ud55c \uc655\uc2e4 \uc77c\ud654\ub97c \ub367\ubd99\uc774\uc9c0 \uc54a\uace0\ub3c4 \ubb3c\uac74\uc744 \ubcfc \uc218 \uc788\ub2e4. \ud654\ub85c\ub294 \uc5f4\uc744 \ub2e4\ub8e8\ub294 \ub3c4\uad6c\uc774\uc9c0\ub9cc \uc5ec\uae30\uc11c\ub294 \uc0ac\uc6a9\uc744 \uc7ac\ud604\ud558\uac70\ub098 \ud604\uc7ac \uc720\ubb3c\uc5d0 \ubd88\uc744 \ub123\ub294 \ubc29\ubc95\uc744 \uc548\ub0b4\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub0a8\uc740 \ud615\ud0dc\uc640 \uc81c\uc791 \uc124\uba85\uc774 \uc911\uc2ec\uc774\ub2e4. \ub465\uadfc \ud14c\ub450\ub9ac\uc640 \ubab8\uccb4\ub97c \ubcf8 \ub4a4 \uc791\uc740 \uc138 \ubc1c\ub85c \ub208\uc744 \ub0b4\ub824 \ubcf4\uc790. \ud070 \uae30\ub2a5\uc744 \ub9e1\uc740 \ubb3c\uac74\uc774 \uc544\ub798\ucabd\uc758 \ud45c\uc815\uacfc \uc774\uc74c\uc5d0 \uc815\uc131\ub3c4 \ud568\uaed8 \ub2f4\uc558\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ubcf4\uc778\ub2e4. \uc774 \ubb3c\uac74\uc5d0\uc11c \uc5b4\ub5a4 \uc5bc\uad74\uc774 \uc5b4\ub5a4 \ud798\uc744 \uc9c0\ucf1c \uc8fc\uc5c8\ub2e4\uace0 \ub2e8\uc815\ud560 \uc790\ub8cc\ub294 \uc5ec\uae30\uc11c \ud655\uc778\ud558\uc9c0 \ubabb\ud588\ub2e4. \uadf8\ub798\uc11c \uc0c1\uc9d5 \ud480\uc774\ub97c \uae38\uac8c \ubd99\uc774\uae30\ubcf4\ub2e4 \uc2e4\uc81c \ub0a8\uc544 \uc788\ub294 \ud615\ud0dc\ub97c \ubcf4\ub294 \ud3b8\uc774 \ub354 \uc990\uac81\ub2e4. \ub2e4\uc74c\uc5d0 \ud654\ub85c\ub098 \ud5a5\ub85c\ub97c \ub9cc\ub098\uba74 \uadf8\ub987 \uc548\ucabd\ub9cc \ub4e4\uc5ec\ub2e4\ubcf4\uc9c0 \ub9d0\uace0 \uc544\ub798\ub3c4 \ubcf4\uc790. \ubc14\ub2e5\uc744 \ub51b\uace0 \uc788\ub294 \ubc1c\uc5d0 \uc758\uc678\ub85c \uac00\uc7a5 \uc7ac\ubbf8\uc788\ub294 \ud45c\uc815\uc774 \uc228\uc5b4 \uc788\uc744\uc9c0 \ubaa8\ub978\ub2e4. \uc774 \uc0bc\uc871\ud654\ub85c\uc5d0\uc11c\ub294 \ub530\ub73b\ud55c \uadf8\ub987\ubcf4\ub2e4 \uba3c\uc800 \uc138 \ubc1c\uc758 \uac1c\uc131\uc774 \uae30\uc5b5\uc5d0 \ub0a8\ub294\ub2e4."}, {"id": "clarinet-many-sizes", "title": "\ud074\ub77c\ub9ac\ub137\uc740 \ud55c \uac00\uc9c0 \ud06c\uae30\uac00 \uc544\ub2c8\ub2e4", "summary": "\uc791\uace0 \ub192\uc740 \uc545\uae30\ubd80\ud130 \ucee4\ub2e4\ub780 \uc800\uc74c \uc545\uae30\uae4c\uc9c0 \ud074\ub77c\ub9ac\ub137 \uac00\uc871\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\ub180\uc774\uc640 \ucde8\ubbf8", "categories": ["everyday-inventions"], "url": "stories/clarinet-many-sizes/index.html", "image": "../media/clarinet-many-sizes.jpg", "alt": "\ud074\ub77c\ub9ac\ub137\uc740 \ud55c \uac00\uc9c0 \ud06c\uae30\uac00 \uc544\ub2c8\ub2e4\uc758 \ub0b4\uc6a9\uc744 \ub3d5\ub294 \uc124\uba85\uc6a9 \uc774\ubbf8\uc9c0", "text": "\ud074\ub77c\ub9ac\ub137\uc740 \ud55c \uac00\uc9c0 \ud06c\uae30\uac00 \uc544\ub2c8\ub2e4 \uac19\uc740 \uc774\ub984\uc758 \uc545\uae30 \uc548\uc5d0 \uc228\uc5b4 \uc788\ub294 \ub113\uc740 \uac00\uc871 \uc791\uace0 \ub192\uc740 \uc545\uae30\ubd80\ud130 \ucee4\ub2e4\ub780 \uc800\uc74c \uc545\uae30\uae4c\uc9c0 \ud074\ub77c\ub9ac\ub137 \uac00\uc871\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ub180\uc774\uc640 \ucde8\ubbf8 \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \ud074\ub77c\ub9ac\ub137\uc774\ub77c\uace0 \ud558\uba74 \uac80\uc740 \uad00\uc5d0 \uc740\ube5b \uc7a5\uce58\uac00 \ub2ec\ub9b0 \uc545\uae30 \ud558\ub098\uac00 \uba3c\uc800 \ub5a0\uc624\ub978\ub2e4. \uadf8 \uc774\ub984\uc744 \uc54c\uba74 \uc678\ud615\ub3c4 \ub2e4 \uc548\ub2e4\uace0 \ub290\ub07c\uae30 \uc27d\ub2e4. \uadf8\ub7f0\ub370 \ud074\ub77c\ub9ac\ub137 \uac00\uc871\uc744 \ub098\ub780\ud788 \ub193\uc73c\uba74 \uc0dd\uac01\ubcf4\ub2e4 \ud06c\uae30 \ucc28\uc774\uac00 \ud06c\ub2e4. \uc601\uad6d \ud544\ud558\ubaa8\ub2c8\uc544 \uc624\ucf00\uc2a4\ud2b8\ub77c\ub294 \uc544\uc8fc \uc791\uace0 \ub192\uc740 \uc18c\ub9ac\ub97c \ub0b4\ub294 \uc885\ub958\ubd80\ud130 \ucee4\ub2e4\ub780 \ucf58\ud2b8\ub77c\ubca0\uc774\uc2a4 \uc885\ub958\uae4c\uc9c0 \uc5ec\ub7ec \ud06c\uae30\uac00 \uc788\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc775\uc219\ud55c \ud558\ub098\uc758 \ubaa8\uc2b5\uc774 \uac00\uc871 \uc804\uccb4\ub97c \ub300\uc2e0\ud558\uace0 \uc788\uc5c8\ub358 \uc148\uc774\ub2e4. \uc77c\ubc18\uc801\uc778 \ud074\ub77c\ub9ac\ub137\uc758 \uc18c\ub9ac\ub3c4 \ub298 \ud55c \uac00\uc9c0 \uc778\uc0c1\uc73c\ub85c\ub9cc \uc124\uba85\ub418\uc9c0 \uc54a\ub294\ub2e4. \ud544\ud558\ubaa8\ub2c8\uc544\ub294 \ub0ae\uc740 \uc74c\uc758 \ub530\ub73b\ud558\uace0 \uc6b8\ub9bc \uc788\ub294 \uc131\uaca9\uacfc \ub192\uc740 \uc74c\uc758 \ubc1d\uace0 \ub9d1\uc740 \uc131\uaca9\uc744 \ud568\uaed8 \uc774\uc57c\uae30\ud55c\ub2e4. \uac19\uc740 \uc0ac\ub78c\uc774 \ub0ae\uac8c \ub9d0\ud560 \ub54c\uc640 \ub192\uac8c \uc678\uce60 \ub54c\uc758 \uc778\uc0c1\uc774 \ub2e4\ub978 \uac83\ucc98\ub7fc \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub2e4. \ubb3c\ub860 \uc545\uae30\uc758 \uc18c\ub9ac\uac00 \uc0ac\ub78c \ubaa9\uc18c\ub9ac\uc640 \ub611\uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub4e3\ub294 \uacbd\ud5d8\uc744 \uac00\uae4c\uc774 \uac00\uc838\uc624\ub294 \ube44\uc720\ub2e4. \uac00\uc871\uc758 \uc791\uc740 \ucabd\uc5d0\ub294 \ub192\uc740 \uc18c\ub9ac\ub97c \ub9e1\ub294 \uc18c\ud504\ub77c\ub2c8\ub178 \ud074\ub77c\ub9ac\ub137\uc774 \uc788\ub2e4. \ud070 \ucabd\uc758 \ucf58\ud2b8\ub77c\ubca0\uc774\uc2a4 \uc545\uae30\ub294 \ub354\ube14\ubca0\uc774\uc2a4\ubcf4\ub2e4 \ub0ae\uc740 \uc74c\uc744 \ub0bc \uc218 \uc788\ub2e4\uace0 \uc548\ub0b4\ub294 \uc124\uba85\ud55c\ub2e4. \ub208\uc5d0 \uc775\uc740 \ubcf4\ud1b5 \ud06c\uae30\uc758 \uc545\uae30\ub9cc \uc0dd\uac01\ud558\uba74 \uc798 \ub5a0\uc624\ub974\uc9c0 \uc54a\ub294 \ud3ed\uc774\ub2e4. \uac19\uc740 \uc774\ub984\uc758 \uac00\uc871\uc774 \uc74c\uc758 \ub192\ub0ae\uc774\uc640 \ud06c\uae30\uc5d0\uc11c \uc5b4\ub514\uae4c\uc9c0 \ub113\uc5b4\uc9c0\ub294\uc9c0 \ubcf4\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \uc624\ucf00\uc2a4\ud2b8\ub77c\ub97c \ubcf4\ub294 \uc7ac\ubbf8\uac00 \ub298\uc5b4\ub09c\ub2e4. \ud074\ub77c\ub9ac\ub137\uc774\ub77c\uace0 \ud558\uba74 \ubcf4\ud1b5 \uc775\uc219\ud55c \ud06c\uae30\uc758 \uac80\uc740 \uc545\uae30\ub97c \uba3c\uc800 \ub5a0\uc62c\ub9b0\ub2e4. \ud558\uc9c0\ub9cc \uac00\uc871 \uc804\uccb4\ub85c \uc2dc\uc120\uc744 \ub113\ud788\uba74 \ub192\uc740 \ucabd\uc758 \uc791\uc740 \uc545\uae30\uc640 \ub0ae\uc740 \ucabd\uc758 \ud070 \uc545\uae30\uac00 \ud568\uaed8 \ub4e4\uc5b4\uc628\ub2e4. \uac19\uc740 \uc774\ub984 \uc544\ub798\uc5d0\ub3c4 \ud06c\uae30\uc640 \ub9e1\ub294 \uc74c\uc5ed\uc774 \ub098\ub25c\ub2e4. \uc545\uae30 \uc774\ub984 \ud558\ub098\ub97c \uc548\ub2e4\ub294 \uac83\uacfc \uadf8 \uc545\uae30\uad70\uc758 \ud3ed\uc744 \uc548\ub2e4\ub294 \uac83\uc740 \ub2e4\ub978 \ub2e8\uacc4\ub2e4. \ud06c\uae30\uac00 \ub2ec\ub77c\uc9c0\uba74 \ubab8\uc5d0 \ub4dc\ub294 \ubc29\uc2dd\uacfc \ub208\uc5d0 \ubcf4\uc774\ub294 \ud615\ud0dc\ub3c4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ud06c\uae30\ub9cc \ubcf4\uace0 \ubaa8\ub4e0 \uc18c\ub9ac\uc758 \uc138\ubd80\ub97c \uc815\ud655\ud788 \uc608\uce21\ud558\uac70\ub098 \ub0ae\uc740 \uc545\uae30\uac00 \uc5b8\uc81c\ub098 \ub454\ud55c \uc18c\ub9ac\ub97c \ub0b8\ub2e4\uace0 \uc815\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc2e4\uc81c \uc74c\uc0c9\uacfc \ud45c\ud604\uc740 \uc5f0\uc8fc\ub97c \ub4e4\uc5b4\uc57c \ud55c\ub2e4. \uad6c\uc870\ub97c \ubcf4\ub294 \uc77c\uc740 \uadf8 \uc18c\ub9ac\ub97c \ub9cc\ub098\uae30 \uc704\ud55c \uc9c8\ubb38\uc744 \ub9c8\ub828\ud55c\ub2e4. \ud544\ud558\ubaa8\ub2c8\uc544\uac00 \ub0ae\uc740 \uc74c\uacfc \ub192\uc740 \uc74c\uc758 \uc131\uaca9\uc744 \ub2e4\ub974\uac8c \uc124\uba85\ud558\ub294 \uc810\ub3c4 \ud765\ubbf8\ub86d\ub2e4. \ud558\ub098\uc758 \uc545\uae30\uc5d0\uc11c \ub098\uc624\ub294 \uc120\uc728\ub3c4 \uc5b4\ub290 \uc74c\uc5ed\uc5d0 \uba38\ubb34\ub294\uc9c0\uc5d0 \ub530\ub77c \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4\ub294 \ub73b\uc774\ub2e4. \uc545\uae30 \uc774\ub984\ub9cc\uc73c\ub85c \ub530\ub73b\ud558\ub2e4\uac70\ub098 \ub0a0\uce74\ub86d\ub2e4\ub294 \uc218\uc2dd \ud558\ub098\ub97c \ubd99\uc774\uba74 \uc774\ub7f0 \ud3ed\uc744 \ub193\uce58\uae30 \uc27d\ub2e4. \uc9e7\uc740 \uc120\uc728\uc774 \ub0ae\uc740 \uacf3\uc5d0\uc11c \uc2dc\uc791\ud574 \uc704\ub85c \uc6c0\uc9c1\uc774\ub294 \uc5f0\uc8fc\ub97c \ub4e4\uc73c\uba74 \ucc28\uc774\ub97c \ucc3e\uae30 \uc88b\ub2e4. \uc815\ud655\ud55c \uc74c\uc774\ub984\uc744 \ubab0\ub77c\ub3c4 \uc18c\ub9ac\uc758 \ubc1d\uae30\uc640 \ubb34\uac8c\uac00 \uc5b4\ub5bb\uac8c \ub290\uaef4\uc9c0\ub294\uc9c0 \ube44\uad50\ud560 \uc218 \uc788\ub2e4. \uc0ac\ub78c\ub9c8\ub2e4 \uac10\uc0c1\uc774 \uac19\uc544\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uae30\uad00\uc774 \uc81c\uc2dc\ud55c \ub9d0\uc740 \ubc18\ub4dc\uc2dc \ub290\uaef4\uc57c \ud560 \uc815\ub2f5\ubcf4\ub2e4 \ub2e4\ub978 \uad6c\uc5ed\uc744 \uc8fc\uc758\ud574\uc11c \ub4e4\uc5b4 \ubcf4\ub77c\ub294 \uc548\ub0b4\ub85c \uc77d\uc73c\uba74 \ub41c\ub2e4. \uae30\uad00 \uc548\ub0b4\ub294 \uc7ac\uc988\uc640 \uc2a4\uc719\uc5d0\uc11c\uc758 \ud45c\ud604\ub3c4 \ud568\uaed8 \uc774\uc57c\uae30\ud55c\ub2e4. \uac19\uc740 \uc545\uae30\uac00 \uc5b4\ub5a4 \ub9ac\ub4ec\uacfc \ub2e4\ub978 \uc5f0\uc8fc\uc790\ub4e4 \uc0ac\uc774\uc5d0 \ub193\uc774\ub294\uc9c0\uc5d0 \ub530\ub77c \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc74c\uc758 \uc2dc\uc791\uc744 \uc5b4\ub5bb\uac8c \ub2e4\ub8e8\uace0 \uc5b4\ub5a4 \uc6c0\uc9c1\uc784\uc744 \uac15\uc870\ud558\ub294\uc9c0\ub3c4 \ub4e3\ub294 \uacbd\ud5d8\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4. \uc545\uae30\uc758 \uc774\ub984\uc774 \uace7 \ud558\ub098\uc758 \uc7a5\ub974\ub97c \ub73b\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uc18c\ub9ac\uac00 \uc775\uc219\ud558\ub2e4\uba74 \ub2e4\ub978 \ud3b8\uc131\uc758 \uc5f0\uc8fc\uc640 \ub098\ub780\ud788 \ub4e4\uc5b4 \ubcf4\uc790. \uad50\ud5a5\uc545\uc5d0\uc11c \uae38\uac8c \ub178\ub798\ud558\ub294 \uc21c\uac04\uacfc \ub9ac\ub4ec\uc744 \ud0c0\uba70 \ud65c\ubc1c\ud788 \uc6c0\uc9c1\uc774\ub294 \uc21c\uac04\uc744 \ube44\uad50\ud560 \uc218 \uc788\ub2e4. \ubaa8\ub4e0 \ud074\ub77c\ub9ac\ub137 \uc5f0\uc8fc\uac00 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc2a4\uc6b0\ud551 \ud6a8\uacfc\ub97c \uc0ac\uc6a9\ud55c\ub2e4\uace0 \uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud574\ub2f9 \uc5f0\uc8fc\uc5d0\uc11c \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \uc120\ud0dd\uc744 \ud558\ub294\uc9c0 \ub4e3\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \ub0ae\uc740 \uc18c\ub9ac\ub97c \ub9e1\ub294 \uc545\uae30\ub294 \ud654\uba74\uc758 \uc911\uc2ec\uc5d0\uc11c \ub35c \ubcf4\uc774\uac70\ub098 \uc120\uc728 \ub4a4\uc5d0\uc11c \ub4e4\ub9b4 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \ud544\uc694 \uc5c6\ub294 \ubc30\uacbd\uc774\ub77c\uace0 \ud310\ub2e8\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc804\uccb4 \uc18c\ub9ac\uac00 \uc5b4\ub5a4 \ubc14\ud0d5 \uc704\uc5d0 \ub193\uc774\ub294\uc9c0 \ub4e4\uc5b4 \ubcf4\uba74 \ub192\uace0 \ubc1d\uc740 \uc18c\ub9ac\ub9cc \ucad3\uc744 \ub54c\uc640 \ub2e4\ub978 \uc74c\uc545\uc774 \ubcf4\uc77c \uc218 \uc788\ub2e4. \uc774\ub294 \ud2b9\uc815 \uace1\uc758 \ud3b8\uc131\uc744 \uc0c8\ub85c \ub2e8\uc815\ud558\ub294 \ub9d0\uc774 \uc544\ub2c8\ub77c \ud569\uc8fc\ub97c \ub4e3\ub294 \uc81c\uc548\uc774\ub2e4. \ub2e4\uc74c \uc601\uc0c1\uc5d0\uc11c \ud074\ub77c\ub9ac\ub137 \uac00\uc871\uc744 \ucc3e\uc558\ub2e4\uba74 \ub204\uac00 \uac00\uc7a5 \ub208\uc5d0 \ub744\ub294\uc9c0\ubfd0 \uc544\ub2c8\ub77c \uc11c\ub85c \ub2e4\ub978 \ud06c\uae30\uac00 \uc788\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc77c\ubc18\uc801\uc778 \ud55c \ubaa8\uc2b5\uc73c\ub85c \uae30\uc5b5\ud558\ub358 \uc774\ub984\uc774 \uc5ec\ub7ec \uc74c\uc5ed\uc758 \uac00\uc871\uc73c\ub85c \ubc14\ub010\ub2e4. \uc804\uc2dc\uc7a5\uc774\ub098 \uc545\uae30 \uc18c\uac1c\uc5d0\uc11c \ud06c\uae30\ub97c \ube44\uad50\ud55c \ub4a4 \uc2e4\uc81c \uc18c\ub9ac\ub97c \ub4e4\uc5b4 \ubcf4\uba74, \ubcf4\ub294 \uc815\ubcf4\uc640 \ub4e3\ub294 \uacbd\ud5d8\uc744 \ud568\uaed8 \ub298\ub9b4 \uc218 \uc788\ub2e4. \ud074\ub77c\ub9ac\ub137\uc740 \uc7ac\uc988\uc640 \uc2a4\uc719\uc758 \uc18c\ub9ac\uc640\ub3c4 \uac00\uae5d\ub2e4. \ud544\ud558\ubaa8\ub2c8\uc544\ub294 \ub9ac\ub4ec\uac10 \uc788\uace0 \ubbf8\ub044\ub7ec\uc9c0\ub4ef \uc6c0\uc9c1\uc774\ub294 \ud45c\ud604\uc5d0 \uc5b4\uc6b8\ub9ac\ub294 \uc545\uae30\ub85c \uc18c\uac1c\ud55c\ub2e4. \uacf5\uc5f0\uc7a5\uc758 \ud55c \uc790\ub9ac\ub9cc\uc73c\ub85c \uae30\uc5b5\ud560 \ud544\uc694\ub294 \uc5c6\ub294 \uac83\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \ud074\ub77c\ub9ac\ub137\uc744 \ub9cc\ub098\uba74 \uc774\ub984\uc744 \ub9de\ud78c \ub370\uc11c \uba48\ucd94\uc9c0 \ub9d0\uace0 \ud06c\uae30\uc640 \uc18c\ub9ac\uc758 \uc704\uce58\ub3c4 \uc0b4\ud3b4\ubcf4\uc790. \uac19\uc740 \uac00\uc871\uc774\ub77c\ub294 \ub9d0\uc740 \uc804\ubd80 \ub611\uac19\uc774 \uc0dd\uacbc\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uc775\uc219\ud55c \uc545\uae30 \uc774\ub984 \ud558\ub098\uac00 \uc0dd\uac01\ubcf4\ub2e4 \ub113\uc740 \ud48d\uacbd\uc744 \uc5f4\uc5b4 \uc904 \uc218 \uc788\ub2e4."}, {"id": "clock-little-door-case", "title": "\uc2dc\uacc4\uc5d0\ub3c4 \uc791\uc740 \ubb38\uc774 \ub2ec\ub9b0 \uc9d1\uc774 \uc788\uc5c8\ub2e4", "summary": "\ubd89\uc740 \ubca8\ubcb3\uacfc \uac08\uc0c9 \uac00\uc8fd\uc73c\ub85c \uac10\uc2fc \uc61b \uc2dc\uacc4 \ud55c \uc870\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\uc9d1\uacfc \uc0dd\ud65c \ub3c4\uad6c", "categories": ["everyday-inventions"], "url": "stories/clock-little-door-case/index.html", "image": "../media/clock-little-door-case.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc2dc\uacc4 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc2dc\uacc4\uc5d0\ub3c4 \uc791\uc740 \ubb38\uc774 \ub2ec\ub9b0 \uc9d1\uc774 \uc788\uc5c8\ub2e4 \ubb38\uc744 \uc5f4\uba74 \uc2dc\uac04\uc774 \ubcf4\uc774\ub294 \ubcf4\uad00\ud568 \ubd89\uc740 \ubca8\ubcb3\uacfc \uac08\uc0c9 \uac00\uc8fd\uc73c\ub85c \uac10\uc2fc \uc61b \uc2dc\uacc4 \ud55c \uc870\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc9d1\uacfc \uc0dd\ud65c \ub3c4\uad6c \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \uc0ac\uc9c4 \uc18d \uc791\uc740 \ubb38\uc774 \uc591\ucabd\uc73c\ub85c \uc5f4\ub824 \uc788\ub2e4. \uadf8 \uc548\uc5d0\ub294 \uc2dc\uacc4\uac00 \uc549\uc544 \uc788\ub2e4. \uc2dc\uacc4\ub97c \ub123\ub294 \uc0c1\uc790\uac00 \uc544\ub2c8\ub77c \uc2dc\uacc4\ub9cc\uc744 \uc704\ud574 \uc9c0\uc740 \uc791\uc740 \uc9d1\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \uc18c\uc7a5\ud488 \uc774\ub984\uc740 \uac04\ub2e8\ud788 \uc2dc\uacc4\ub2e4. \uc2dc\uacc4\uc640 \ubcf4\uad00 \ucf00\uc774\uc2a4\uac00 \ud55c \uc870\ub97c \uc774\ub8ec\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc804\uc2dc\uc7a5\uc5d0\uc11c \uc2dc\uacc4\uc758 \ubc14\ub298\ub9cc \ud655\uc778\ud558\uace0 \uc9c0\ub098\uac14\ub2e4\uba74, \uc774\ubc88\uc5d0\ub294 \ubc14\uae65\uc758 \uc9d1\uae4c\uc9c0 \ucc9c\ucc9c\ud788 \ubcf4\uc790. \uc2dc\uacc4 \uc55e\uba74\uc758 \uc22b\uc790\ub294 \uc6b0\ub9ac\uc5d0\uac8c \uc775\uc219\ud55c \uc544\ub77c\ube44\uc544 \uc22b\uc790\ub2e4. \uadf8\uc911 12\ub9cc \ubd89\uace0 \ub098\uba38\uc9c0\ub294 \uac80\ub2e4\uace0 \ubc15\ubb3c\uad00\uc740 \uc124\uba85\ud55c\ub2e4. \ub611\uac19\uc740 \uc22b\uc790\ud310 \uc548\uc5d0\uc11c \uc704\ucabd \ud55c \uc790\ub9ac\uc5d0\ub9cc \uc0c9\uc744 \ub2ec\ub9ac \uc900 \uac83\uc774\ub2e4. \uc65c \uadf8 \uc22b\uc790\ub9cc \ubd89\uac8c \ud588\ub294\uc9c0\ub294 \uc774 \uc790\ub8cc\uc5d0 \uc801\ud600 \uc788\uc9c0 \uc54a\ub2e4. \ud2b9\ubcc4\ud55c \uc758\ubbf8\ub97c \ubd99\uc774\uae30\ubcf4\ub2e4 \uba3c\uc800 \uc2e4\uc81c \ucc28\uc774\ub97c \ub208\uc73c\ub85c \ucc3e\uc544\ubcf4\uba74 \uc88b\ub2e4. \uc124\uba85\uc744 \uc77d\uae30 \uc804\uc5d0\ub294 \uc9c0\ub098\ucce4\uc744 \uc791\uc740 \uc120\ud0dd\uc774 \uc2dc\uacc4\uc758 \uc5bc\uad74\uc744 \ubc14\uafbc\ub2e4. \ubcf4\uad00 \ucf00\uc774\uc2a4\uc758 \ubc14\uae65\uc5d0\ub294 \uac08\uc0c9 \uac00\uc8fd\uc774 \uc50c\uc6cc\uc838 \uc788\uace0 \uc548\uc5d0\ub294 \ubd89\uc740 \ubca8\ubcb3\uc774 \uc788\ub2e4. \uc2dc\uacc4\uac00 \ub4e4\uc5b4\uac00\ub294 \uacf5\uac04\ub3c4 \ud06c\uae30\uc5d0 \uaf2d \ub9de\ub3c4\ub85d \ub9cc\ub4e4\uc5b4\uc84c\ub2e4\uace0 \ud55c\ub2e4. \ubb38\uc740 \uc88c\uc6b0\ub85c \ud65c\uc9dd \uc5f4 \uc218 \uc788\ub294 \uad6c\uc870\ub2e4. \ubcf4\uad00\ud560 \ub54c\uc640 \ub4e4\uc5ec\ub2e4\ubcfc \ub54c\uc758 \ubaa8\uc591\uc774 \ub2e4\ub978 \ubb3c\uac74\uc774\ub2e4. \uc624\ub298\uc758 \uc774\uc5b4\ud3f0 \ucf00\uc774\uc2a4\ub97c \ub5a0\uc62c\ub824 \ubcfc \uc218\ub3c4 \uc788\uc9c0\ub9cc, \uc774\uac83\uc774 \uc5ec\ud589\uc6a9\uc774\uc5c8\ub2e4\uac70\ub098 \ucda9\uaca9\uc744 \ub9c9\uae30 \uc704\ud574 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4\uace0\uae4c\uc9c0 \ub2e8\uc815\ud560 \uadfc\uac70\ub294 \uc5c6\ub2e4. \ub9de\ucda4 \uacf5\uac04\uacfc \uc5ec\ub2eb\uc774\ubb38 \uc790\uccb4\uac00 \ubcf4\uc5ec \uc8fc\ub294 \uc7ac\ubbf8\ub97c \uc990\uae30\uba74 \ucda9\ubd84\ud558\ub2e4. \uc2dc\uacc4\ub294 \uc2dc\uac04\uc744 \ubcf4\uc5ec \uc8fc\uace0 \ucf00\uc774\uc2a4\ub294 \uadf8 \uc2dc\uacc4\ub97c \ub123\uc744 \uc790\ub9ac\ub97c \ub9cc\ub4e0\ub2e4. \ud55c \uc870\ub85c \ub0a8\uc544 \uc788\ub2e4\ub294 \uc124\uba85\uc744 \uc77d\uc73c\uba74 \ub450 \ubb3c\uac74\uc744 \ub530\ub85c \ubcf4\uc558\uc744 \ub54c\uc640 \ub2e4\ub978 \uad00\uacc4\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \ub3c4\uad6c\uac00 \uc791\ub3d9\ud558\ub294 \uba74\ubfd0 \uc544\ub2c8\ub77c \ubcf4\uad00\ud558\uace0 \uaebc\ub0b4 \ubcf4\ub294 \ubc29\uc2dd\ub3c4 \uc0dd\ud65c\uc758 \uc77c\ubd80\uc600\ub2e4\ub294 \uc810\uc774\ub2e4. \uc2dc\uacc4\uc758 \ubab8\uccb4\ub9cc\uc73c\ub85c \uc804\uccb4 \uc0ac\uc6a9 \uacbd\ud5d8\uc744 \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc774 \ucf00\uc774\uc2a4\ub97c \uc624\ub298\uc758 \uc5ec\ud589\uc6a9 \ubcf4\ud638\ud568\uacfc \uac19\uc740 \ubaa9\uc801\uc774\ub77c\uace0 \ubc14\ub85c \uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \uc774\ub3d9\uc744 \ud588\ub294\uc9c0\uc640 \ub204\uad6c\uc758 \ubc29\uc5d0 \ub193\uc600\ub294\uc9c0\ub294 \ub0a8\uc740 \uc790\ub8cc\uac00 \ud544\uc694\ud55c \ubb38\uc81c\ub2e4. \uc9c0\uae08 \ud655\uc778\ub418\ub294 \ub9de\ucda4 \uacf5\uac04\uacfc \uc5ec\ub2eb\uc774\ubb38\uc744 \uba3c\uc800 \ubcf4\uc790. \ud2b9\uc815\ud55c \ubb3c\uac74\uc744 \uc704\ud574 \ub9c8\ub828\ud55c \ud615\ud0dc\ub77c\ub294 \uc810\ub9cc\uc73c\ub85c\ub3c4 \uc2dc\uacc4\ub97c \ub300\ud558\ub358 \uc190\uc758 \ud589\ub3d9\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uac08\uc0c9 \uac00\uc8fd\uc740 \ucf00\uc774\uc2a4\uc758 \uc678\ud615\uc744 \uc774\ub8e8\uace0 \ubd89\uc740 \ubca8\ubcb3\uc740 \uc548\ucabd\uc758 \ub2e4\ub978 \ud45c\uc815\uc744 \ub9cc\ub4e0\ub2e4. \uac19\uc740 \ubb3c\uac74\uc744 \ub2eb\uc544 \ub193\uc558\uc744 \ub54c\uc640 \uc5f4\uc5c8\uc744 \ub54c\uc758 \uc2dc\uac01\uc801 \uacbd\ud5d8\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc740 \uc7ac\ub8cc\ub97c \uad6c\ubd84\ud574 \uc54c\ub824 \uc8fc\ubbc0\ub85c \ub2e8\uc21c\ud788 \uac08\uc0c9 \uc0c1\uc790\ub77c\ub294 \uc778\uc0c1\uc5d0\uc11c \ud55c \uac78\uc74c \ub354 \ub4e4\uc5b4\uac08 \uc218 \uc788\ub2e4. \uc678\ubd80\uc640 \ub0b4\ubd80\uac00 \uc11c\ub85c \ub2e4\ub978 \uc5ed\ud560\uacfc \uac10\uc0c1\uc744 \ub9cc\ub4e0\ub2e4. \ub2e4\ub9cc \ud604\uc7ac \ubcf4\uc774\ub294 \uc0c9\uc744 \ucc98\uc74c \uc81c\uc791 \uc21c\uac04\uc758 \uc0c9\uacfc \uc644\uc804\ud788 \uac19\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ubcf4\uc874 \uc0c1\ud0dc\uc640 \uc0ac\uc9c4\uc758 \uc870\uac74\uc774 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc7ac\ub8cc\uc758 \uc885\ub958\ub294 \ud574\uc124\uc744 \ud1b5\ud574 \ud655\uc778\ud558\uace0 \ud654\uba74\uc5d0\uc11c\ub294 \ubc30\uce58\uc640 \uad00\uacc4\ub97c \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ucf00\uc774\uc2a4\ub3c4 \uc2dc\uacc4\ub97c \ub2f4\uc740 \ubc30\uacbd\uc5d0 \uadf8\uce58\uc9c0 \uc54a\uace0 \ub530\ub85c \uad00\ucc30\ud560 \uba74\uacfc \ubb38\uc744 \uac00\uc9c4 \ubb3c\uac74\uc774\uc5c8\ub2e4. 12\ub9cc \ubd89\uace0 \ub2e4\ub978 \uc22b\uc790\ub294 \uac80\ub2e4\ub294 \uc815\ubcf4\ub294 \uc0ac\uc9c4\uc744 \ub2e4\uc2dc \ubcf4\uac8c \ud55c\ub2e4. \uc804\ubd80 \uac19\uc740 \uc22b\uc790\ub77c\uace0 \uc0dd\uac01\ud558\uace0 \uc9c0\ub098\ucce4\ub2e4\uba74 \ud55c \uc790\ub9ac\uc758 \ucc28\uc774\uac00 \uc0c8\ub86d\uac8c \ub4dc\ub7ec\ub09c\ub2e4. \uac19\uc740 \ud45c\uba74\uc5d0\uc11c \uc0c9\uc744 \ub2ec\ub9ac \uc900 \uc120\ud0dd\uc740 \uc5b4\ub5a4 \uc9c0\uc810\uc744 \uad6c\ubd84\ud558\ub294 \ud6a8\uacfc\ub97c \ub0bc \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \ud6a8\uacfc\uc640 \uc81c\uc791\uc790\uc758 \ud655\uc778\ub41c \ubaa9\uc801\uc740 \uac19\uc740 \uac83\uc774 \uc544\ub2c8\ub2e4. \ud2b9\ubcc4\ud55c \uae30\ub150\uc77c\uc774\ub098 \uc18c\uc720\uc790\uc758 \ucde8\ud5a5\uc744 \uadfc\uac70 \uc5c6\uc774 \ubd99\uc774\ub294 \ub300\uc2e0 \uc2e4\uc81c\ub85c \uc5b4\ub290 \ubd80\ubd84\uc774 \ub2e4\ub974\uac8c \ucc98\ub9ac\ub418\uc5c8\ub294\uc9c0 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc791\uc740 \ucc28\uc774\ub97c \uc544\ub294 \uac83\ub9cc\uc73c\ub85c \ubb3c\uac74\uc758 \uc5bc\uad74\uc774 \ub35c \uc775\uba85\uc801\uc73c\ub85c \ub290\uaef4\uc9c4\ub2e4. \uc2dc\uac01\uc744 \uc77d\ub294 \uc22b\uc790\ud310\uc5d0\uc11c \uc2dc\uacc4\ub97c \uad6c\uacbd\ud558\ub294 \uc0ac\ub78c\uc758 \uc2dc\uc120\ub3c4 \ud568\uaed8 \uc6c0\uc9c1\uc778\ub2e4. \uc4f0\ub294 \uc77c\uacfc \uac10\uc0c1\ud558\ub294 \uc77c\uc774 \uacb9\uce58\ub294 \uc790\ub9ac\ub2e4. \uc790\ub8cc\ub294 \uc7a0\uae08\uc7a5\uce58\uac00 \ub0a8\uc544 \uc788\uc9c0 \uc54a\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc5f0\ub300\uac00 \ubd84\uba85\ud558\uc9c0 \uc54a\ub2e4\ub294 \uc810\uc744 \uc54c\ub824 \uc900\ub2e4. \ubb3c\uac74\uc774 \uc798 \ubcf4\uc778\ub2e4\uace0 \uadf8 \uc774\ub825\uae4c\uc9c0 \ubaa8\ub450 \ud655\uc2e4\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ub0a8\uc740 \ucf00\uc774\uc2a4\uc758 \ud615\ud0dc\uc640 \ube60\uc9c4 \uc7a5\uce58, \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \uc81c\uc791 \uc2dc\uae30\ub97c \ud568\uaed8 \uc77d\uc5b4\uc57c \ud55c\ub2e4. \uadf8 \ube48\uce78\uc744 \ud2b9\uc815\ud55c \uc655\uc2e4 \uc778\ubb3c\uc758 \uc18c\uc9c0\ud488\uc774\ub77c\ub294 \uc774\uc57c\uae30\ub85c \ucc44\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc791\uc740 \ubb38\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc2dc\uacc4\ub97c \ub450\ub294 \uacf5\uac04\uacfc \ub2e4\uc2dc \ub4e4\uc5ec\ub2e4\ubcf4\ub294 \ud589\ub3d9\uc744 \uc0dd\uac01\ud574 \ubcf4\uc790. \ubb3c\uac74\uc744 \ubcf4\uc874\ud55c \uc0ac\ub78c\ub4e4\uc740 \uae30\ub2a5\ubfd0 \uc544\ub2c8\ub77c \ud568\uaed8 \uc4f0\uc778 \ubd80\uc18d\ubb3c\ub3c4 \ub0a8\uacbc\ub2e4. \ub355\ubd84\uc5d0 \uc6b0\ub9ac\ub294 \uc22b\uc790\ud310 \ud558\ub098\ub97c \ub118\uc5b4 \uc2dc\uac04\uc744 \ub9cc\ub098\ub294 \ubc29\uc2dd\uc758 \uc77c\ubd80\ub97c \uad6c\uacbd\ud560 \uc218 \uc788\ub2e4. \uc2dc\uacc4\uc758 \uc791\uc740 \uc9d1\uc774\ub77c\ub294 \ube44\uc720\uac00 \uad6c\uccb4\uc801\uc778 \ud615\ud0dc\ub97c \uc5bb\ub294 \uc21c\uac04\uc774\ub2e4. \ucf00\uc774\uc2a4 \ubb38\uc758 \uac00\uc6b4\ub370\uc5d0\ub294 \uc6d0\ub798 \ubd99\uc5c8\ub358 \uc7a0\uae08\uc7a5\uce58\uac00 \uc5c6\uc5b4\uc84c\uace0, \uace0\uc815\ud558\ub358 \uc791\uc740 \uae08\uc18d\ud310\ub9cc \ub0a8\uc558\ub2e4\uace0 \ud55c\ub2e4. \uc624\ub798\ub41c \ubb3c\uac74\uc740 \uac16\ucd94\uc5b4\uc9c4 \ubd80\ubd84\ubfd0 \uc544\ub2c8\ub77c \ube60\uc9c4 \ubd80\ubd84\uc73c\ub85c\ub3c4 \uc790\uae30 \uc0c1\ud0dc\ub97c \uc54c\ub824 \uc900\ub2e4. \uc81c\uc791 \uc5f0\ub300\ub294 \ubc15\ubb3c\uad00 \uc815\ubcf4\uc5d0\uc11c\ub3c4 \ubbf8\uc0c1\uc774\ub2e4. \ub204\uad6c\uc758 \ucc45\uc0c1\uc5d0 \uc5b8\uc81c \ub193\uc600\ub294\uc9c0 \uc0c1\uc0c1\uc73c\ub85c \ucc44\uc6b0\uae30\ubcf4\ub2e4 \uc9c0\uae08 \ud655\uc778\ud560 \uc218 \uc788\ub294 \ubb38\uacfc \uc22b\uc790, \uac00\uc8fd\uacfc \ubca8\ubcb3\uc744 \ubcf4\uc790. \uc2dc\uac04\uc744 \uc54c\ub824 \uc8fc\ub358 \ubb3c\uac74\uc5d0 \ubcf4\uad00\ud558\ub294 \uc2dc\uac04\uae4c\uc9c0 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4\ub294 \ub290\ub08c\uc774 \ub4e0\ub2e4."}, {"id": "coffeehouse-news-and-conversation", "title": "\ucee4\ud53c\ud558\uc6b0\uc2a4 \u2014 \ucee4\ud53c \ud55c \uc794 \uc606\uc5d0 \ub274\uc2a4\uac00 \ub193\uc600\ub358 \uc774\uc720", "summary": "\uc61b \ucee4\ud53c\ud558\uc6b0\uc2a4\uc758 \ub300\ud654\uc640 \uc778\uc1c4\ubb3c, \uac70\ub798\ub97c \uc0b4\ud3b4\ubcf4\uba70 \uc74c\ub8cc\ub97c \ub9c8\uc2dc\ub294 \uc7a5\uc18c\uac00 \uc0ac\ud68c\uc801 \uacf5\uac04\uc774 \ub418\ub294 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\uc2dd\ud0c1\uacfc \uc2dd\ud488 \ubcf4\uc874", "categories": ["everyday-inventions"], "url": "stories/coffeehouse-news-and-conversation/index.html", "image": "../media/coffeehouse-news-and-conversation.jpg", "alt": "\ud0c1\uc790 \uc8fc\uc704\uc5d0 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc778 \uc61b \ucee4\ud53c\ud558\uc6b0\uc2a4\uc758 \uc2e4\uc81c \ubaa9\ud310\ud654 \uc7ac\ud604 \ub3c4\ud310.", "text": "\ucee4\ud53c\ud558\uc6b0\uc2a4 \u2014 \ucee4\ud53c \ud55c \uc794 \uc606\uc5d0 \ub274\uc2a4\uac00 \ub193\uc600\ub358 \uc774\uc720 \uc61b \ub7f0\ub358\uc758 \uc791\uc740 \uac00\uac8c\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc774 \ub098\ub208 \uac83\ub4e4 \uc61b \ucee4\ud53c\ud558\uc6b0\uc2a4\uc758 \ub300\ud654\uc640 \uc778\uc1c4\ubb3c, \uac70\ub798\ub97c \uc0b4\ud3b4\ubcf4\uba70 \uc74c\ub8cc\ub97c \ub9c8\uc2dc\ub294 \uc7a5\uc18c\uac00 \uc0ac\ud68c\uc801 \uacf5\uac04\uc774 \ub418\ub294 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc2dd\ud0c1\uacfc \uc2dd\ud488 \ubcf4\uc874 \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \ucee4\ud53c\ub97c \uc8fc\ubb38\ud558\uace0 \uc790\ub9ac\uc5d0 \uc549\ub294\ub2e4. \uc606 \ud14c\uc774\ube14\uc5d0\uc11c\ub294 \uc815\uce58 \uc774\uc57c\uae30\uac00 \ub4e4\ub9ac\uace0, \ub204\uad70\uac00\ub294 \uc0c8\ub85c \ub098\uc628 \uc18c\uc2dd\uc744 \uc77d\ub294\ub2e4. \uc9c0\uae08\uc758 \uce74\ud398\uc5d0\uc11c\ub3c4 \ub0af\uc124\uc9c0 \uc54a\uc740 \uc7a5\uba74\uc774\uc9c0\ub9cc, 17~18\uc138\uae30 \ub7f0\ub358\uc758 \ucee4\ud53c\ud558\uc6b0\uc2a4\uc5d0\uc11c\ub294 \uc774\ub7f0 \ub9cc\ub0a8\uc774 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud588\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \uc74c\ub8cc\uc640 \ud568\uaed8 \uc774\uc57c\uae30\uc640 \uc815\ubcf4\ub97c \uc5bb\uc5c8\ub2e4. \uc70c\ub9ac\uc5c4 \ud574\ub9ac\uc2a8 \uc720\ucee4\uc2a4\uac00 1922\ub144\uc5d0 \ud3b4\ub0b8 \u300eAll About Coffee\u300f\uc5d0\ub294 \uc61b \ucee4\ud53c\ud558\uc6b0\uc2a4\uc758 \uc790\ub8cc\uc640 \uadf8\ub9bc\uc774 \ub9ce\uc774 \ubaa8\uc5ec \uc788\ub2e4. \uc0c1\uc5c5\uacfc \ucee4\ud53c \ubb38\ud654\ub97c \ud3ed\ub113\uac8c \ub2e4\ub8ec \uc624\ub798\ub41c \ucc45\uc774\ubbc0\ub85c \ubaa8\ub4e0 \uc124\uba85\uc744 \uadf8\ub300\ub85c \ud655\uc815\ud558\uc9c0\ub294 \uc54a\uc73c\uba74\uc11c, \uc5b4\ub5a4 \ud65c\ub3d9\uc774 \ud55c \uc7a5\uc18c\uc5d0 \ubaa8\uc600\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc601\uad6d\uc5d0\uc11c \ucee4\ud53c\ub294 \ucc98\uc74c\ubd80\ud130 \ub204\uad6c\ub098 \uc544\ub294 \uc77c\uc0c1 \uc74c\ub8cc\uac00 \uc544\ub2c8\uc5c8\ub2e4. \ucc45\uc740 1652\ub144 \ub7f0\ub358\uc758 \ud30c\uc2a4\ucf70 \ub85c\uc81c\uc640 \ucee4\ud53c \ud310\ub9e4\uc758 \ucd08\uae30 \uc5ed\uc0ac\ub97c \uc124\uba85\ud55c\ub2e4. \ub0af\uc120 \uc74c\ub8cc\ub97c \ud314\ub824\uba74 \ub9db\ubfd0 \uc544\ub2c8\ub77c \uc5b4\ub5a4 \ubb3c\uac74\uc778\uc9c0, \uc65c \ub9c8\uc2e4 \ub9cc\ud55c\uc9c0 \uc54c\ub9ac\ub294 \ub9d0\ub3c4 \ud544\uc694\ud588\ub2e4. \uc61b \uad11\uace0\uc5d0\ub294 \uc624\ub298\uc758 \uae30\uc900\uc73c\ub85c \ubc1b\uc544\ub4e4\uc774\uae30 \uc5b4\ub824\uc6b4 \uac74\uac15 \uc8fc\uc7a5\ub3c4 \uc2e4\ub838\ub2e4. \uadf8\ub7f0 \ud6a8\ub2a5\uc744 \uc774 \uae00\uc5d0\uc11c \ub418\ud480\uc774\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uad11\uace0\ub97c \ud765\ubbf8\ub86d\uac8c \uc77d\uc744 \uc9c0\uc810\uc740 \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc774 \uc0c8\ub85c\uc6b4 \uc74c\ub8cc\ub97c \uc5b4\ub5bb\uac8c \uc124\uba85\ud558\ub824 \ud588\ub294\uac00\ub2e4. \ucee4\ud53c\uc758 \ub9db\uc774 \uc54c\ub824\uc9c0\ub294 \uacfc\uc815\uc5d0\ub294 \uc774\uc57c\uae30\uc640 \uc778\uc1c4\ubb3c\ub3c4 \ud568\uaed8 \uc788\uc5c8\ub2e4. \ucee4\ud53c\ud558\uc6b0\uc2a4\ub294 \uc220\uc744 \uc911\uc2ec\uc5d0 \ub193\uc740 \uc7a5\uc18c\uc640 \ub2e4\ub978 \uc131\uaca9\uc73c\ub85c \uc774\uc57c\uae30\ub418\uc5c8\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \ucee4\ud53c\ub97c \ub9c8\uc2dc\uba70 \ub300\ud654\ud558\uace0 \uc790\ub8cc\ub97c \uc77d\uc744 \uc218 \uc788\uc5c8\ub2e4. \ub2e4\ub9cc \uc61b \ucc45\uc774 \uc220\uc9d1\uacfc \ucee4\ud53c\ud558\uc6b0\uc2a4\ub97c \uc120\uba85\ud558\uac8c \ub300\ube44\ud55c\ub2e4\uace0 \ud574\uc11c \ubaa8\ub4e0 \uac00\uac8c\uac00 \ud56d\uc0c1 \uc870\uc6a9\ud558\uace0 \uc810\uc796\uc558\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5b4\ub5a4 \uc74c\ub8cc\ub97c \ud310\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uadf8 \uacf5\uac04\uc758 \ubb38\ud654\uac00 \uc790\ub3d9\uc73c\ub85c \uc815\ud574\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub204\uac00 \ubaa8\uc774\uace0 \ubb34\uc5c7\uc744 \ud558\uba70 \uc5bc\ub9c8\ub098 \uc624\ub798 \uba38\ubb34\ub294\uc9c0\uac00 \ud568\uaed8 \uc911\uc694\ud558\ub2e4. \ucee4\ud53c\ud558\uc6b0\uc2a4\uc758 \ud765\ubbf8\ub85c\uc6b4 \uc810\uc740 \uc794 \uc18d\uc5d0 \ub4e0 \uac83\ubfd0 \uc544\ub2c8\ub77c \uac19\uc740 \ud14c\uc774\ube14 \uc8fc\ubcc0\uc5d0\uc11c \ubc8c\uc5b4\uc9c4 \ud65c\ub3d9\uc5d0 \uc788\ub2e4. \ucc45\uc740 \ucee4\ud53c\ud558\uc6b0\uc2a4\uc758 \uc2e0\ubb38\uacfc \uc77d\uc744\uac70\ub9ac, \uc18c\uc2dd\uc744 \ub458\ub7ec\uc2fc \ud1a0\ub860\uc744 \uc124\uba85\ud55c\ub2e4. \uac19\uc740 \uc790\ub8cc\ub97c \uc5ec\ub7ec \uc0ac\ub78c\uc774 \uc811\ud558\uba74 \ub204\uad70\uac00 \uc77d\uc740 \ubb38\uc7a5\uc774 \ub2e4\ub978 \uc0ac\ub78c\uc758 \ub9d0\uc774 \ub420 \uc218 \uc788\ub2e4. \uc815\ubcf4\ub97c \uc5bb\ub294 \uc77c\uacfc \uadf8 \uc815\ubcf4\uc5d0 \uad00\ud574 \uc758\uacac\uc744 \ub098\ub204\ub294 \uc77c\uc774 \ud55c \uc7a5\uc18c\uc5d0\uc11c \uc774\uc5b4\uc84c\ub2e4. \uc77d\ub294 \ub2a5\ub825\uacfc \ub300\ud654\uc758 \uc790\ub9ac\ub3c4 \uc11c\ub85c \ub9cc\ub09c\ub2e4. \ud63c\uc790 \uc870\uc6a9\ud788 \ub05d\ub0b8 \ub3c5\uc11c\uc640 \ub2ec\ub9ac \ub2e4\ub978 \uc0ac\ub78c\uc740 \uac19\uc740 \uc18c\uc2dd\uc744 \uc5b4\ub5bb\uac8c \uc774\ud574\ud588\ub294\uc9c0 \uace7\ubc14\ub85c \uc54c \uc218 \uc788\ub2e4. \ubb3c\ub860 \ub9d0\uc774 \uc624\uac04\ub2e4\uace0 \ubaa8\ub450 \uc815\ud655\ud55c \uc815\ubcf4\uac00 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0c8 \uc18c\uc2dd\uacfc \ucd94\uce21, \uc18c\ubb38\ub3c4 \uac19\uc740 \uacf5\uac04\uc744 \uc6c0\uc9c1\uc77c \uc218 \uc788\uc5c8\ub2e4. \uc790\ub8cc\uc5d0\ub294 \ucee4\ud53c\ud558\uc6b0\uc2a4\ub97c \ud398\ub2c8 \ub300\ud559\uc774\ub77c\uace0 \ubd80\ub978 \uc0ac\ub840\uac00 \ub098\uc628\ub2e4. \ube44\uad50\uc801 \uc791\uc740 \ub3c8\uc744 \ub0b4\uace0 \ub300\ud654\uc640 \uc815\ubcf4\uc5d0 \uc811\ud560 \uc218 \uc788\ub294 \uacf5\uac04\uc774\ub77c\ub294 \uc778\uc2dd\uc774 \ub2f4\uae34 \ubcc4\uba85\uc774\ub2e4. \uac15\uc758\uc2e4\uacfc \ud559\uc704\ub97c \uac16\ucd98 \uc2e4\uc81c \ub300\ud559\uc774 \ub418\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc785\uc7a5\uacfc \uc74c\ub8cc, \uc77d\uc744\uac70\ub9ac\uc758 \ube44\uc6a9\uc740 \uc2dc\uae30\uc640 \uc7a5\uc18c\uc5d0 \ub530\ub77c \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc5b4\ub514\uc11c\ub098 \ucee4\ud53c \ud55c \uc794\uc774 \uc815\ud655\ud788 1\ud398\ub2c8\uc600\ub2e4\uace0 \uc678\uc6b0\uae30\ubcf4\ub2e4, \ubc30\uc6c0\uc774 \ubc18\ub4dc\uc2dc \uacf5\uc2dd \ud559\uad50 \uc548\uc5d0\uc11c\ub9cc \uc77c\uc5b4\ub098\uc9c0\ub294 \uc54a\ub294\ub2e4\ub294 \ub2f9\uc2dc\uc758 \ube44\uc720\ub85c \uc77d\uc73c\uba74 \uc88b\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\uc758 \ub9d0\uc744 \ub4e3\ub294 \uacbd\ud5d8\ub3c4 \uc9c0\uc2dd\uc758 \ud55c \ud1b5\ub85c\uac00 \ub418\uc5c8\ub2e4. \uc11c\ub85c \ube44\uc2b7\ud55c \uad00\uc2ec\uc744 \uac00\uc9c4 \uc0ac\ub78c\uc774 \ubc18\ubcf5\ud574\uc11c \uac19\uc740 \uacf3\uc5d0 \uc624\uba74 \uac00\uac8c\ub294 \uadf8 \ubd84\uc57c\uc758 \uc815\ubcf4\ub97c \ucc3e\ub294 \uc7a5\uc18c\uac00 \ub420 \uc218 \uc788\ub2e4. \uc61b \ub7f0\ub358 \ucee4\ud53c\ud558\uc6b0\uc2a4\uc758 \uae30\ub85d\uc5d0\ub294 \ubb38\ud559\uacfc \uc815\uce58\ubfd0 \uc544\ub2c8\ub77c \ud574\uc6b4\uacfc \uac70\ub798\uc758 \uc18c\uc2dd\ub3c4 \ub4f1\uc7a5\ud55c\ub2e4. \ub85c\uc774\uc988 \uac19\uc740 \uc774\ub984\ub3c4 \uc774\ub7f0 \ucee4\ud53c\ud558\uc6b0\uc2a4\uc758 \uc5ed\uc0ac\uc640 \uc774\uc5b4\uc9c4\ub2e4. \ub204\uac00 \ub3cc\uc544\uc654\ub294\uc9c0, \uc5b4\ub5a4 \ubc30\uac00 \uc5b4\ub514\ub85c \uac14\ub294\uc9c0 \uac19\uc740 \uc18c\uc2dd\uc740 \ub300\ud654\uc758 \uc18c\uc7ac\uc774\uba74\uc11c \uac70\ub798\uc758 \ud310\ub2e8 \uc790\ub8cc\uac00 \ub420 \uc218 \uc788\uc5c8\ub2e4. \uac19\uc740 \uacf5\uac04\uc5d0\uc11c \uc790\uc8fc \uc5bc\uad74\uc744 \ub9c8\uc8fc\ud558\ub294 \uc77c\ub3c4 \uad00\uacc4\ub97c \ub9cc\ub4e0\ub2e4. \ucee4\ud53c \uc790\uccb4\uc758 \uac00\uaca9\uc744 \ub118\uc5b4, \uadf8 \uc7a5\uc18c\uc5d0\uc11c \ub9cc\ub0a0 \uc218 \uc788\ub294 \uc815\ubcf4\uc640 \uc0ac\ub78c\uc774 \uac00\uce58\ub97c \uac16\uac8c \ub418\ub294 \uac83\uc774\ub2e4. \ud398\ub2c8 \ub300\ud559\uc774\ub77c\ub294 \ubc1d\uc740 \ubcc4\uba85\ub9cc\uc73c\ub85c \uc644\uc804\ud788 \ud3c9\ub4f1\ud55c \uc0ac\ud68c\uac00 \uc2e4\ud604\ub418\uc5c8\ub2e4\uace0 \ub9d0\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \uadf8\ub9bc\uacfc \uae30\ub85d\uc5d0 \ub098\ud0c0\ub098\ub294 \ucc38\uc11d\uc790\uc758 \ubaa8\uc2b5, \ub2f9\uc2dc\uc758 \uc131\ubcc4\uacfc \uacc4\uce35 \uc9c8\uc11c\ub97c \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \uc801\uc740 \uc785\uc7a5 \ube44\uc6a9\uacfc \ubaa8\ub450\uc5d0\uac8c \uac19\uc740 \uae30\ud68c\ub294 \uac19\uc740 \ub9d0\uc774 \uc544\ub2c8\ub2e4. \ucc45\uc5d0 \uc2e4\ub9b0 \uc774\uc0c1\uc801\uc778 \ub300\ud654\uc758 \ubd84\uc704\uae30\ub3c4 \ubaa8\ub4e0 \uc774\uc6a9\uc790\uc758 \uacbd\ud5d8\uc744 \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub204\uac00 \ub9d0\ud560 \uc218 \uc788\uc5c8\uace0 \ub204\uac00 \uadf8 \uc790\ub9ac\uc5d0 \uc5c6\uc5c8\ub294\uc9c0 \ubb3b\ub294 \uac83\uc740 \ucee4\ud53c\ud558\uc6b0\uc2a4\ub97c \uae4e\uc544\ub0b4\ub9ac\ub824\ub294 \uc77c\uc774 \uc544\ub2c8\ub2e4. \uc911\uc694\ud55c \uc0ac\ud68c \uacf5\uac04\uc774\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \uc774\ud574\ud558\ub824\ub294 \uc9c8\ubb38\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \ucc45\uc774 1674\ub144 \ubaa9\ud310\ud654\uc5d0\uc11c \uac00\uc838\uc654\ub2e4\uace0 \uc124\uba85\ud558\ub294 \ucee4\ud53c\ud558\uc6b0\uc2a4 \uc7a5\uba74\uc758 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \ud0c1\uc790 \uc8fc\ubcc0\uc5d0 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc774\uace0, \ub4a4\uc640 \uc606\uc5d0\uc11c\ub3c4 \uc778\ubb3c\ub4e4\uc774 \uad00\uacc4\ub97c \ub9cc\ub4e0\ub2e4. \uc624\ub298\uc758 \uac1c\uc778\uc6a9 \ub178\ud2b8\ubd81\ucc98\ub7fc \uac01\uc790\uc758 \uc791\uc740 \ud654\uba74\uc774 \uacf5\uac04\uc744 \ub098\ub204\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc774 \ud55c \uc7a5\uc774 \ub2f9\uc2dc \ub7f0\ub358\uc758 \ubaa8\ub4e0 \uac00\uac8c\ub97c \uc815\ud655\ud788 \ubcf4\uc5ec \uc8fc\ub294 \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \uc81c\uc791\uc790\uc758 \ud45c\ud604\uc744 \uac70\uce5c \uc774\ubbf8\uc9c0\uc774\uba70 \ud6c4\ub300 \ucc45\uc5d0 \ub2e4\uc2dc \uc2e4\ub9b0 \uc790\ub8cc\ub2e4. \ub204\uac00 \uc5b4\ub514\uc5d0 \uc11c\uace0 \ub204\uac00 \ub204\uad6c\ub97c \ud5a5\ud558\ub294\uc9c0 \uba3c\uc800 \uc0b4\ud3b4\ubcf4\uba74, \uc74c\ub8cc\uc758 \uc6a9\uae30\ubcf4\ub2e4 \uc0ac\ub78c \uc0ac\uc774\uc758 \ubc30\uce58\uac00 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc624\ub298\uc758 \uce74\ud398\uc5d0 \uc549\uc544 \uc0ac\ub78c\ub4e4\uc758 \ub2e4\uc591\ud55c \ubaa9\uc801\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ud63c\uc790 \uc77d\uace0 \uc77c\ud558\ub294 \uc0ac\ub78c\ub3c4, \ub204\uad70\uac00\ub97c \ub9cc\ub098 \uc18c\uc2dd\uc744 \ub4e3\ub294 \uc0ac\ub78c\ub3c4 \uc788\ub2e4. \uac19\uc740 \uc74c\ub8cc\ub97c \uc0ac\ub3c4 \uac01\uc790\uac00 \uc0ac\ub294 \uc2dc\uac04\uacfc \uad00\uacc4\ub294 \ub2e4\ub974\ub2e4. \uc61b \ucee4\ud53c\ud558\uc6b0\uc2a4\uc758 \uc774\uc57c\uae30\ub97c \uadf8\ub300\ub85c \ud604\uc7ac\uc640 \uac19\uac8c \ub193\uc744 \ud544\uc694\ub294 \uc5c6\uc9c0\ub9cc \uc774\ub7f0 \uc9c8\ubb38\uc740 \uc774\uc5b4\uc9c4\ub2e4. \ucee4\ud53c\ud558\uc6b0\uc2a4\ub294 \ucee4\ud53c\uac00 \uc0ac\ub78c\uc744 \ud604\uba85\ud558\uac8c \ub9cc\ub4e0\ub2e4\ub294 \uc804\uc124\ubcf4\ub2e4, \uc0ac\ub78c\ub4e4\uc774 \ubc18\ubcf5\ud574\uc11c \ubaa8\uc77c \uc790\ub9ac\uac00 \ubb34\uc5c7\uc744 \uac00\ub2a5\ud558\uac8c \ud558\ub294\uc9c0 \ubcf4\uc5ec \uc900\ub2e4. \ud55c \uc794\uc740 \uc9e7\uac8c \ub9c8\uc2e4 \uc218 \uc788\uc5b4\ub3c4 \uadf8 \uc606\uc5d0\uc11c \ub098\ub208 \uc815\ubcf4\uc640 \ub300\ud654\ub294 \ub354 \uba40\ub9ac \uac08 \uc218 \uc788\ub2e4. \uc74c\ub8cc\uc758 \uc5ed\uc0ac\uac00 \uace7 \ub9cc\ub0a8\uc758 \uc5ed\uc0ac\ub85c \ub113\uc5b4\uc9c0\ub294 \uc9c0\uc810\uc774\ub2e4."}, {"id": "crane-embroidered-badge", "title": "\uad00\ubcf5\uc758 \ud559 \ub450 \ub9c8\ub9ac\ub294 \ubb34\uc5c7\uc744 \uc54c\ub824\uc904\uae4c", "summary": "\uc637 \uc704\uc758 \uc791\uc740 \uadf8\ub9bc\uc5d0\ub294 \uc785\ub294 \uc0ac\ub78c\uc758 \uc9c0\uc704\uc640 \uc790\uc218\uc758 \uc19c\uc528\uac00 \ud568\uaed8 \ub2f4\uacbc\uc2b5\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\uc637\uacfc \uc7ac\ub8cc", "categories": ["everyday-inventions"], "url": "stories/crane-embroidered-badge/index.html", "image": "../media/crane-embroidered-badge.jpg", "alt": "\ub450 \ud559\uacfc \uc2dd\ubb3c \ubb34\ub2ac\ub97c \uc5ec\ub7ec \uc0c9 \uc2e4\ub85c \uc218\ub193\uc740 \uc30d\ud559\ubb34\ub2ac \ud749\ubc30\uc758 \uc138\ubd80 \uc0ac\uc9c4", "text": "\uad00\ubcf5\uc758 \ud559 \ub450 \ub9c8\ub9ac\ub294 \ubb34\uc5c7\uc744 \uc54c\ub824\uc904\uae4c \uc30d\ud559\ubb34\ub2ac \ud749\ubc30\ub97c \uac00\uae4c\uc774\uc5d0\uc11c \ubcf4\ub294 \uc7ac\ubbf8 \uc637 \uc704\uc758 \uc791\uc740 \uadf8\ub9bc\uc5d0\ub294 \uc785\ub294 \uc0ac\ub78c\uc758 \uc9c0\uc704\uc640 \uc790\uc218\uc758 \uc19c\uc528\uac00 \ud568\uaed8 \ub2f4\uacbc\uc2b5\ub2c8\ub2e4. \uc637\uacfc \uc7ac\ub8cc \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \uc61b \uad00\ubcf5\uc744 \ubcf4\uba74 \uac00\uc2b4\uaed8\uc758 \uc0ac\uac01\ud615 \uadf8\ub9bc\uc774 \uba3c\uc800 \ub208\uc5d0 \ub74c \ub54c\uac00 \uc788\ub2e4. \ub113\uc740 \uc637 \ud55c\uac00\uc6b4\ub370\uc5d0\uc11c \ub3d9\ubb3c\uc774 \ub0a0\uac70\ub098 \uad6c\ub984 \uc0ac\uc774\ub97c \uc6c0\uc9c1\uc778\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \u300c\uc30d\ud559\ubb34\ub2ac \ud749\ubc30\u300d\uc5d0\ub294 \ub450 \ub9c8\ub9ac \ud559\uc774 \uc704\uc544\ub798\ub85c \ub9c8\uc8fc \ubcf4\uace0 \uc788\ub2e4. \uac00\uae4c\uc774 \ubcf4\uba74 \ud770 \ubab8\uacfc \ub0a0\uac1c\ub3c4 \ubb3c\uac10\uc774 \uc544\ub2c8\ub77c \uc2e4\ub85c \ub9cc\ub4e4\uc5b4\uc838 \uc788\ub2e4. \uc608\uc05c \uadf8\ub9bc\uc744 \uc637\uc5d0 \ubd99\uc778 \uac83\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc, \uc774 \ubb3c\uac74\uc5d0\ub294 \ucc29\uc6a9\uc790\uc758 \uc9c0\uc704\ub97c \ub098\ud0c0\ub0b4\ub294 \uc5ed\ud560\ub3c4 \uc788\uc5c8\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc774 \ud749\ubc30\ub97c \ubb38\uad00 \ub2f9\uc0c1\uad00\uc774 \ucc29\uc6a9\ud55c \uac83\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \ub2f9\uc0c1\uad00\uc740 \uad00\ub8cc\uc758 \ub192\uc740 \uc9c0\uc704\uc5d0 \uc18d\ud558\ub294 \uad6c\ubd84\uc774\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc138\uc138\ud55c \ud488\uacc4\ud45c\ubcf4\ub2e4, \uc637\uc758 \ubb38\uc591\uc774 \uc544\ubb34\ub807\uac8c\ub098 \uc815\ud574\uc9c0\uc9c0\ub294 \uc54a\uc558\ub2e4\ub294 \uc810\uc744 \uc54c\uc544\ub450\uba74 \ub41c\ub2e4. \ubc15\ubb3c\uad00\uc758 \uad81\uc911 \uc790\uc218 \uc804\uc2dc \uc124\uba85\uc5d0\uc11c\ub3c4 \uc2e0\ud558\ub4e4\uc5d0\uac8c \uad00\uc9c1\uacfc \ub4f1\uae09\uc5d0 \ub530\ub77c \uc218\uc2e4\uacfc \ubb38\uc591\uc744 \ub2ec\ub9ac\ud55c \ud749\ubc30\ub97c \ub0b4\ub838\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc7a5\uc2dd\uacfc \uc0ac\ud68c\uc801\uc778 \uad6c\ubd84\uc774 \uac19\uc740 \ubb3c\uac74 \uc548\uc5d0 \uc788\uc5c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub3d9\ubb3c\uc758 \uc218\ub9cc \uc678\uc6cc \ubaa8\ub4e0 \uc2dc\ub300\uc758 \uad00\ubcf5\uc744 \ub9de\ud788\ub294 \uc2dc\ud5d8\uc744 \ubcfc \ud544\uc694\ub294 \uc5c6\ub2e4. \uc9c0\uae08 \ubcf4\ub294 \ud55c \uc810\uc758 \uc124\uba85\ubd80\ud130 \uc77d\uc73c\uba74 \ucda9\ubd84\ud558\ub2e4. \uc774 \ud749\ubc30\uc5d0\ub294 \ud559 \ub450 \ub9c8\ub9ac\uc640 \ubd88\ub85c\ucd08\ub97c \ubb38 \ubaa8\uc2b5\uc774 \uc218\ub193\uc5ec \uc788\ub2e4. \uc0ac\uc9c4\uc744 \ud655\ub300\ud558\uba74 \ud770 \ub0a0\uac1c\ub97c \ucc44\uc6b4 \uc2e4\uc758 \uacb0\uc744 \ubcfc \uc218 \uc788\ub2e4. \uad6c\ub984 \uac00\uc7a5\uc790\ub9ac\uc5d0\ub294 \ub610 \ub2e4\ub978 \ube5b\uae54\uacfc \uc9c8\uac10\uc774 \uc774\uc5b4\uc9c4\ub2e4. \uba40\ub9ac\uc11c\ub294 \ud558\ub098\uc758 \uadf8\ub9bc\uc774\uc9c0\ub9cc \uac00\uae4c\uc774\uc5d0\uc11c\ub294 \uc791\uc740 \uc2e4\uc758 \uc6c0\uc9c1\uc784\uc73c\ub85c \ub098\ub25c\ub2e4. \uad81\uc911 \uc790\uc218\ub294 \uc804\ubb38 \ud654\uc6d0\uc774 \ubc11\uadf8\ub9bc\uc744 \uadf8\ub9ac\uace0 \uc218\ubc29\uc758 \uc0ac\ub78c\ub4e4\uc774 \uc774\ub97c \uc62e\uaca8 \uc218\ub193\ub294 \ubc29\uc2dd\uc73c\ub85c \uc81c\uc791\ub418\uc5c8\ub2e4\uace0 \ubc15\ubb3c\uad00\uc740 \uc124\uba85\ud55c\ub2e4. \uadf8\ub9ac\ub294 \uc77c\uacfc \ubc14\ub290\uc9c8\ud558\ub294 \uc77c\uc774 \ud55c \ubb3c\uac74\uc5d0\uc11c \ub9cc\ub09c\ub2e4. \uc774 \uacfc\uc815\uc5d0\uc11c \ud3c9\uba74\uc758 \uadf8\ub9bc\uc740 \uc637\uac10 \uc704\uc758 \uc9c8\uac10\uc744 \uc5bb\ub294\ub2e4. \ube5b\uc744 \ubc1b\ub294 \ubc29\ud5a5\uc5d0 \ub530\ub77c \uc2e4\uc758 \ud45c\uba74\uc774 \ub2ec\ub77c \ubcf4\uc774\ub294 \uac83\ub3c4 \uc790\uc218 \uc0ac\uc9c4\uc744 \ubcf4\ub294 \uc990\uac70\uc6c0\uc774\ub2e4. \ub3d9\ubb3c\uc774 \ubb34\uc5c7\uc778\uc9c0 \uc54c\uc544\ubcf8 \ub4a4\uc5d0\ub294 \uc5b4\ub5bb\uac8c \ub9cc\ub4e4\uc5b4\uc84c\ub294\uc9c0\ub3c4 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc637\uc758 \ubb34\ub2ac\ub294 \uac00\uae4c\uc774\uc5d0\uc11c \uc544\ub984\ub2f5\uac8c \ubcfc \ub300\uc0c1\uc774\uba74\uc11c \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc785\uc740 \uc0ac\ub78c\uc744 \uc54c\uc544\ubcf4\uac8c \ud558\ub294 \ud45c\uc9c0\uac00 \ub420 \uc218 \uc788\ub2e4. \ud749\ubc30\ub294 \uad00\ubcf5\uc774\ub77c\ub294 \uc81c\ub3c4 \uc548\uc5d0\uc11c \uadf8\ub7f0 \uc5ed\ud560\uc744 \ub9e1\ub294\ub2e4. \uac1c\uc778\uc758 \ucde8\ud5a5\ub300\ub85c \uace0\ub978 \ub3d9\ubb3c \uadf8\ub9bc\uacfc \uc9c0\uc704\uc5d0 \ub9de\ucdb0 \uc0ac\uc6a9\ud558\ub294 \ubb38\uc591\uc740 \uac19\uc740 \uc9c8\ubb38\uc73c\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc7a5\uc2dd\uc774 \uc0ac\ud68c\uc801\uc778 \uc57d\uc18d\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uadf8\ub798\uc11c \uc774 \uc720\ubb3c\uc758 \ud559 \ub450 \ub9c8\ub9ac\ub97c \uc548\ub2e4\uace0 \ubaa8\ub4e0 \uad00\ubcf5\uc758 \ud488\uacc4\ub97c \uc989\uc2dc \ud310\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc2dc\ub300\uc640 \uc885\ub958, \uad6c\uccb4\uc801\uc778 \uc81c\ub3c4\uac00 \ud568\uaed8 \ud544\uc694\ud558\ub2e4. \uc9c0\uae08\uc740 \ubc15\ubb3c\uad00\uc774 \uc774 \ud55c \uc810\uc744 \ubb38\uad00 \ub2f9\uc0c1\uad00\uc758 \ud749\ubc30\ub85c \uc18c\uac1c\ud55c\ub2e4\ub294 \uc124\uba85\uc744 \uae30\uc900\uc73c\ub85c \uc0bc\ub294\ub2e4. \ud55c \ubb3c\uac74\uc758 \uc774\ub984\uc744 \uc815\ud655\ud788 \uc77d\uc740 \ub4a4 \ub354 \ub113\uc740 \uad00\ubcf5\uc758 \uaddc\uce59\uc744 \ucc3e\uc544\uac00\ub294 \ud3b8\uc774 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \uad81\uc911 \uc790\uc218\uc758 \ubd84\uc5c5\uc5d0 \uad00\ud55c \ud574\uc124\uc744 \uc77d\uc73c\uba74 \uadf8\ub824 \ub193\uc740 \ud615\uc0c1\uc774 \uc5b4\ub5bb\uac8c \uc2e4\ub85c \uc62e\uaca8\uc84c\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uc120\uacfc \uba74\uc744 \ucc9c \uc704\uc5d0 \ucc44\uc6b0\ub824\uba74 \uc0c9\uacfc \ubc29\ud5a5, \uc7ac\ub8cc\uc758 \uacb0\uc744 \ub2e4\ub8e8\uc5b4\uc57c \ud55c\ub2e4. \uadf8\ub9bc\uc744 \uadf8\ub300\ub85c \ubcf5\uc0ac\ud558\ub294 \uc77c\ucc98\ub7fc \ubcf4\uc5ec\ub3c4 \uc190\uc758 \uae30\uc220\uc774 \ub9cc\ub4dc\ub294 \ud45c\uba74\uc740 \ub2e4\ub978 \ub9e4\uccb4\uc758 \uacb0\uacfc\ub2e4. \uac19\uc740 \ud559\uc774 \ud3c9\ud3c9\ud55c \uc120\uacfc \uc785\uccb4\uc801\uc778 \uc2e4 \uc0ac\uc774\ub97c \uac74\ub108\uac04\ub2e4. \ub2e4\ub9cc \uc77c\ubc18\uc801\uc778 \uad81\uc911 \uc790\uc218\uc758 \uc81c\uc791 \uc124\uba85\uc774 \uc774 \ud55c \uc810\uc758 \uc81c\uc791\uc790 \uc774\ub984\uc744 \ubaa8\ub450 \ubc1d\ud600 \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub204\uac00 \ubc11\uadf8\ub9bc\uc744 \uadf8\ub9ac\uace0 \ub204\uac00 \uc218\ub193\uc558\ub294\uc9c0\uc5d0 \uad00\ud55c \uac1c\ubcc4 \uc774\ub825\uc740 \ubcc4\ub3c4 \uc790\ub8cc\uac00 \ud544\uc694\ud558\ub2e4. \uc791\uc5c5\uc744 \ub098\ub204\ub294 \uc81c\ub3c4\uc758 \ubc30\uacbd\uacfc \ub208\uc55e\uc758 \uad6c\uccb4\uc801\uc778 \uc720\ubb3c\uc744 \uc5f0\uacb0\ud558\ub418, \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \uc7a5\uc778\uc758 \uc774\uc57c\uae30\ub97c \ub367\ubd99\uc774\uc9c0 \uc54a\ub294 \uac83\uc774 \uc815\ud655\ud558\ub2e4. \ud559\uc774\ub77c\ub294 \ub3d9\ubb3c\uc744 \uc54c\uc544\ubcf8 \ub4a4\uc5d0\ub294 \ub0a0\uac1c\uc640 \ubab8\uc744 \uc774\ub8e8\ub294 \uc2e4\uc758 \uacb0\uc744 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uba40\ub9ac\uc11c \ud558\ub098\ub85c \ubcf4\uc774\ub294 \ud770 \ubd80\ubd84\ub3c4 \uac00\uae4c\uc774\uc5d0\uc11c\ub294 \ucd18\ucd18\ud788 \ub193\uc778 \uc791\uc740 \uc120\ub4e4\uc774\ub2e4. \uac19\uc740 \uc0c9\ucc98\ub7fc \ubcf4\uc5ec\ub3c4 \ube5b\uc744 \ubc1b\ub294 \ubc29\ud5a5\uacfc \uc9c8\uac10\uc5d0 \ub530\ub77c \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc790\uc218\ub294 \uc0c9\uc744 \uce60\ud55c \uadf8\ub9bc\uacfc \ub2e4\ub978 \ud45c\uba74\uc744 \uac00\uc9c4\ub2e4. \uc0ac\uc9c4\uc744 \ubcfc \ub54c\uc5d0\ub294 \ubb34\ub2ac\uc758 \uc774\ub984\uc744 \ube68\ub9ac \ub9de\ud788\ub294 \ub300\uc2e0 \ud070 \uba74\uc5d0\uc11c \uc791\uc740 \uc2e4\ub85c \uc2dc\uc120\uc744 \uc62e\uaca8 \ubcf4\uc790. \ub2e4\ub9cc \ud654\uba74\uc758 \uc870\uba85\uacfc \ud655\ub300 \uc815\ub3c4\uc5d0 \ub530\ub77c \ubcf4\uc774\ub294 \uacb0\uc740 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc9c1\uc811 \uad00\ucc30\ud55c \uc138\ubd80\uc640 \ubc15\ubb3c\uad00\uc774 \uc124\uba85\ud558\ub294 \ubb38\uc591\uc744 \ud568\uaed8 \uc77d\uc73c\uba74 \ub41c\ub2e4. \uc544\ub984\ub2e4\uc6b4 \uc0c1\uc9d5\uc774\ub77c\ub294 \ub9d0 \ub4a4\uc5d0 \uc218\ub9ce\uc740 \ubc14\ub298\ub540\uc774 \uc788\uc5c8\ub2e4\ub294 \uc810\uc774 \uad6c\uccb4\uc801\uc73c\ub85c \ub290\uaef4\uc9c4\ub2e4. \uad00\ubcf5\uc5d0 \ubd99\uc5b4 \uc788\uc744 \ub54c\uc758 \ud749\ubc30\ub294 \uc785\uc740 \uc0ac\ub78c\uc758 \uc6c0\uc9c1\uc784\uacfc \uac70\ub9ac \uc18d\uc5d0\uc11c \ubcf4\uc600\uc744 \uac83\uc774\ub2e4. \uc804\uc2dc\uc7a5\uc774\ub098 \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uadf8 \ubd80\ubd84\ub9cc \ub530\ub85c \uc624\ub798 \ubcfc \uc218 \uc788\ub2e4. \uc6d0\ub798 \ubab8\uc5d0 \ubd99\uc778 \ud45c\uc9c0\uc640 \uc624\ub298 \ub208\uc55e\uc758 \uacf5\uc608\ud488\uc774\ub77c\ub294 \ub450 \ubaa8\uc2b5\uc774 \uacb9\uce5c\ub2e4. \uc5b4\ub290 \ud558\ub098\ub97c \uc9c0\uc6b0\uc9c0 \uc54a\uc73c\uba74 \uc0ac\ud68c\uc801 \uc5ed\ud560\uacfc \uc81c\uc791\uc758 \uc544\ub984\ub2e4\uc6c0\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ub450 \ud559\uc774 \ub9c8\uc8fc \ubcf4\uace0 \ubd88\ub85c\ucd08\ub97c \ubb38 \uad6c\uc131\uc744 \ub2e4\uc2dc \ubcf4\uc790. \ubb34\uc5c7\uc744 \uadf8\ub838\ub294\uc9c0\uc640 \uc5b4\ub5bb\uac8c \uc218\ub193\uc558\ub294\uc9c0\uac00 \ud55c \ubb3c\uac74 \uc548\uc5d0 \uc788\ub2e4. \uc5b4\ub824\uc6b4 \uad00\uc9c1\ud45c\ub97c \ubaa8\ub450 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4, \uc0ac\ub78c\uc744 \uad6c\ubd84\ud558\ub294 \ud45c\uc9c0\uac00 \uc774\ub807\uac8c \ub9ce\uc740 \uc190\uc77c\uacfc \uc0c1\uc9d5\uc744 \ud488\uc744 \uc218 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub0a8\ub294\ub2e4. \uc637\uac10 \ud55c \uc870\uac01\uc5d0\uc11c \uc81c\ub3c4\uc640 \uacf5\uc608\uac00 \ub9cc\ub09c\ub2e4. \ubcf5\uc2dd \uc804\uc2dc\uc5d0\ub294 \ub0af\uc120 \uc637 \uc774\ub984\uacfc \uae34 \uc124\uba85\uc774 \ubd99\uc5b4 \uc788\uae30 \uc27d\ub2e4. \ucc98\uc74c\ubd80\ud130 \ubaa8\ub450 \uc678\uc6b0\ub824 \ud558\uba74 \uad00\ub78c\uc774 \uacf5\ubd80\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uadf8\ub7f4 \ub54c\ub294 \ub9c8\uc74c\uc5d0 \ub4dc\ub294 \ubb38\uc591 \ud558\ub098\ubd80\ud130 \ucc3e\uc544\ubcf4\uc544\ub3c4 \uc88b\ub2e4. \ud559\uc758 \ub0a0\uac1c\uac00 \uc5b4\ub514\uae4c\uc9c0 \ud3bc\uccd0\uc838 \uc788\ub294\uc9c0, \uad6c\ub984\uc740 \uc5b4\ub5a4 \uc0c9\uc778\uc9c0, \uac19\uc740 \ud770 \ubd80\ubd84\ub3c4 \uc2e4\uc758 \ubc29\ud5a5\uc774 \ub2e4\ub978\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc54c\uace0 \uc788\ub294 \ub3d9\ubb3c\uc774 \ub0af\uc120 \uc637\uc744 \ubcf4\ub294 \uc785\uad6c\uac00 \ub41c\ub2e4. \uadf8\ub2e4\uc74c \uc124\uba85\uc5d0\uc11c \ub204\uac00 \uc785\ub358 \uac83\uc778\uc9c0 \ud655\uc778\ud558\uba74 \uc791\uc740 \uadf8\ub9bc\uc758 \ub450 \uc5ed\ud560\uc774 \ud568\uaed8 \ubcf4\uc778\ub2e4. \ud55c \uc0ac\ub78c\uc758 \uc790\ub9ac\ub97c \uc54c\ub824\uc8fc\ub294 \ud45c\uc2dc\uc774\uba74\uc11c, \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc190\uc774 \uc9c0\ub098\uac04 \uc12c\uc138\ud55c \uacf5\uc608\ud488\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \uad00\ubcf5 \uc18d \ub3d9\ubb3c\uc744 \ub9cc\ub098\uba74 \uc774\ub984\ub9cc \ub9de\ud788\uace0 \uc9c0\ub098\uce58\uc9c0 \uc54a\uc544\ub3c4 \uc88b\uaca0\ub2e4. \uc2e4 \ud55c \uac00\ub2e5\uc529 \uac00\uae4c\uc774 \ubcf4\ub294 \ub370\uc5d0\ub3c4 \uc0dd\uac01\ubcf4\ub2e4 \uae34 \uad6c\uacbd\uac70\ub9ac\uac00 \uc228\uc5b4 \uc788\ub2e4."}, {"id": "cream-separator-centrifuge-and-dairy-work", "title": "\uc6b0\uc720 \uc6d0\uc2ec\ubd84\ub9ac\uae30 \u2014 \ud06c\ub9bc\uc774 \ub5a0\uc624\ub974\uae30\ub97c \uae30\ub2e4\ub9ac\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4\uba74", "summary": "\uc6b0\uc720\uc758 \uc131\ubd84\uc744 \ub098\ub204\ub294 \ud68c\uc804 \uc7a5\uce58\uc5d0\uc11c \uc6d0\ub8cc\uc758 \ud750\ub984\uacfc \uc804\ud6c4 \uc791\uc5c5, \uc2dd\ud488 \uac00\uacf5\uc758 \ubcc0\ud654\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\uc2dd\ud0c1\uacfc \uc2dd\ud488 \ubcf4\uc874", "categories": ["everyday-inventions"], "url": "stories/cream-separator-centrifuge-and-dairy-work/index.html", "image": "../media/cream-separator-centrifuge-and-dairy-work.jpg", "alt": "\uae54\ub54c\uae30\uc640 \ud68c\uc804\ubd80, \ubd84\ub9ac\ub41c \uc6b0\uc720 \uc131\ubd84\uc758 \ucd9c\uad6c\uac00 \uc788\ub294 \uc6d0\uc2ec\ubd84\ub9ac\uae30\uc758 \uc5ed\uc0ac \ub3c4\ud310", "text": "\uc6b0\uc720 \uc6d0\uc2ec\ubd84\ub9ac\uae30 \u2014 \ud06c\ub9bc\uc774 \ub5a0\uc624\ub974\uae30\ub97c \uae30\ub2e4\ub9ac\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4\uba74 \ubc00\ub3c4 \ucc28\uc774\uc640 \ud68c\uc804, \uc5f0\uc18d \uacf5\uc815\uc774 \ubc14\uafbc \ub099\ub18d \uc791\uc5c5 \uc6b0\uc720\uc758 \uc131\ubd84\uc744 \ub098\ub204\ub294 \ud68c\uc804 \uc7a5\uce58\uc5d0\uc11c \uc6d0\ub8cc\uc758 \ud750\ub984\uacfc \uc804\ud6c4 \uc791\uc5c5, \uc2dd\ud488 \uac00\uacf5\uc758 \ubcc0\ud654\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uc2dd\ud0c1\uacfc \uc2dd\ud488 \ubcf4\uc874 \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \uc6b0\uc720\uc5d0\uc11c \ud06c\ub9bc\uc744 \uc5bb\uc73c\ub824\uba74 \uc704\ucabd\uc5d0 \ubaa8\uc77c \ub54c\uae4c\uc9c0 \uae30\ub2e4\ub9ac\ub294 \ubc29\ubc95\uc774 \uc788\ub2e4. \uadf8\ub7f0\ub370 \ub9ce\uc740 \uc591\uc744 \uacc4\uc18d \ucc98\ub9ac\ud574\uc57c \ud558\ub294 \uacf3\uc5d0\uc11c\ub294 \uae30\ub2e4\ub9ac\ub294 \uc2dc\uac04\uacfc \uc791\uc5c5\uc758 \ubc18\ubcf5\uc774 \ubb38\uc81c\uac00 \ub41c\ub2e4. \uc6d0\uc2ec\ubd84\ub9ac\uae30\ub294 \uc6b0\uc720 \uc131\ubd84\uc758 \ubc00\ub3c4 \ucc28\uc774\ub97c \ud68c\uc804\ud558\ub294 \uc7a5\uce58 \uc548\uc5d0\uc11c \uc774\uc6a9\ud588\ub2e4. \uc775\uc219\ud55c \uc2dd\ud488 \ub4a4\uc5d0 \uc788\ub294 \ubb3c\ub9ac\uc640 \ub178\ub3d9\uc758 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubcf4\uc790. \uac89\uc73c\ub85c \uace0\ub974\uac8c \ubcf4\uc774\ub294 \uc6b0\uc720\uc5d0\ub3c4 \uc9c0\ubc29\uc744 \ube44\ub86f\ud55c \uc5ec\ub7ec \uc131\ubd84\uc774 \uc788\ub2e4. \uc9c0\ubc29\uc774 \ub9ce\uc740 \ubd80\ubd84\uacfc \ub2e4\ub978 \ubd80\ubd84\uc758 \uc131\uc9c8 \ucc28\uc774\ub97c \uc774\uc6a9\ud558\uba74 \ubd84\ub9ac\ud560 \uc218 \uc788\ub2e4. \uc6d0\uc2ec\ubd84\ub9ac\uae30\ub294 \ubb3c\uc9c8\uc744 \uc0c8\ub85c \ub9cc\ub4e4\uc5b4 \ub0b4\uae30\ubcf4\ub2e4 \uc774\ubbf8 \uc788\ub358 \ucc28\uc774\ub97c \ub354 \ube60\ub974\uac8c \ub4dc\ub7ec\ub0b4\ub294 \uc7a5\uce58\ub2e4. \uc74c\uc2dd\uc758 \uac00\uacf5\uc744 \ub9db\uc744 \ub354\ud558\ub294 \uc77c\ub85c\ub9cc \uc0dd\uac01\ud558\uba74 \uc774\ub7f0 \uae30\uc220\uc744 \ub193\uce5c\ub2e4. \ubd84\ub9ac\ud558\uace0 \ubaa8\uc73c\ub294 \uc77c\ub3c4 \uc911\uc694\ud55c \uacf5\uc815\uc774\uc5c8\ub2e4. \ucd5c\uc885 \uc2dd\ud488\uc758 \ubaa8\uc591\ubcf4\ub2e4 \uc911\uac04 \ub2e8\uacc4\uc758 \uc791\uc5c5\uc744 \ubcf4\uba74 \uc2dd\ud488 \uc0b0\uc5c5\uc774 \ud480\uc5b4\uc57c \ud588\ub358 \uc9c8\ubb38\uc774 \ub2ec\ub77c \ubcf4\uc778\ub2e4. \uc6b0\uc720\ub97c \ub450\uace0 \ud06c\ub9bc\uc774 \ubaa8\uc774\uae30\ub97c \uae30\ub2e4\ub9ac\ub294 \ubc29\ubc95\uc740 \uc2dc\uac04\uc774 \ud544\uc694\ud558\ub2e4. \ud68c\uc804\ud558\ub294 \uc7a5\uce58\uc5d0\uc11c\ub294 \ubc00\ub3c4\uac00 \ub2e4\ub978 \ubd80\ubd84\ub4e4\uc774 \uc11c\ub85c \ub2e4\ub978 \uc704\uce58\ub85c \ubaa8\uc774\ub294 \ud6a8\uacfc\ub97c \uc774\uc6a9\ud560 \uc218 \uc788\ub2e4. \ube60\ub974\uac8c \ub3c4\ub294 \uc6b4\ub3d9\uc774 \ubd84\ub9ac\uc758 \uc2dc\uac04\uc744 \ubc14\uafb8\ub294 \ub370 \uc5f0\uacb0\ub41c\ub2e4. \ub2e4\ub9cc \ubb34\uc870\uac74 \ub354 \ube68\ub9ac \ub3cc\ub9ac\uba74 \ubaa8\ub4e0 \uc7ac\ub8cc\uac00 \uc6d0\ud558\ub294 \ub300\ub85c \ub098\ub25c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc7a5\uce58\uc758 \ud615\ud0dc\uc640 \ud750\ub984, \uc6d0\ub8cc\uc758 \uc870\uac74\uc774 \ud568\uaed8 \uc791\uc6a9\ud55c\ub2e4. \uae30\ubcf8 \uc6d0\ub9ac\ub97c \uc544\ub294 \uac83\uacfc \uc2e4\uc81c\ub85c \uc798 \uc791\ub3d9\ud558\ub294 \uae30\uacc4\ub97c \ub9cc\ub4dc\ub294 \uc77c \uc0ac\uc774\uc5d0\ub294 \uc124\uacc4\uc758 \ubb38\uc81c\uac00 \uc788\ub2e4. 1900\ub144 \uae30\uc220\uc0ac \ucc45\uc758 \uc6b0\uc720 \uc6d0\uc2ec\ubd84\ub9ac\uae30\ub294 \uc6b0\uc720\ub97c \uacc4\uc18d \ub123\uace0 \uc11c\ub85c \ub2e4\ub978 \ucd9c\uad6c\ub85c \ubd84\ub9ac\ub41c \ubd80\ubd84\uc744 \ubc1b\ub294 \uad6c\uc870\ub97c \uc124\uba85\ud55c\ub2e4. \ud55c \ubc88 \ub2f4\uace0 \uc624\ub7ab\ub3d9\uc548 \uae30\ub2e4\ub9b0 \ub4a4 \uaebc\ub0b4\ub294 \ubc29\uc2dd\uacfc \ub2e4\ub978 \uc791\uc5c5 \ud750\ub984\uc774\ub2e4. \ub4e4\uc5b4\uc624\ub294 \uc591\uacfc \ub098\uac00\ub294 \ud750\ub984\uc744 \ub9de\ucd94\ub294 \uc77c\uc774 \uc911\uc694\ud574\uc9c4\ub2e4. \uac00\ubcbc\uc6b4 \uc9c0\ubc29\uc774 \ub9ce\uc740 \ubd80\ubd84\uacfc \uc0c1\ub300\uc801\uc73c\ub85c \ubb34\uac70\uc6b4 \ubd80\ubd84\uc774 \uc7a5\uce58 \uc548\uc5d0\uc11c \ub2e4\ub978 \uacbd\ub85c\ub85c \ubaa8\uc778\ub2e4. \uc5ed\uc0ac \ub3c4\ud310\uc758 \uae54\ub54c\uae30\uc640 \ud68c\uc804\ubd80, \ucd9c\uad6c\ub97c \ud568\uaed8 \ubcf4\uba74 \ubaa9\uc801\uc774 \ubcf4\uc778\ub2e4. \ubcf5\uc7a1\ud55c \ubd80\ud488\uc744 \uc804\ubd80 \uc678\uc6b0\uae30\ubcf4\ub2e4 \ubb34\uc5c7\uc774 \ub4e4\uc5b4\uc640 \uc5b4\ub514\ub85c \ub098\uc624\ub294\uc9c0 \ub530\ub77c\uac00 \ubcf4\ub294 \ud3b8\uc774 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ud68c\uc804\ud558\ub294 \ud1b5\uc5d0\uc11c\ub294 \ubc00\ub3c4\uac00 \ub354 \ud070 \ubd80\ubd84\uc774 \ubc14\uae65\ucabd\uc73c\ub85c, \uc9c0\ubc29\uc774 \ub9ce\uc740 \ubd80\ubd84\uc774 \uc0c1\ub300\uc801\uc73c\ub85c \uc911\uc2ec \ucabd\uc73c\ub85c \ubaa8\uc774\ub294 \ubc29\uc2dd\uc73c\ub85c \uc124\uba85\ud560 \uc218 \uc788\ub2e4. \ucd9c\uad6c\ub97c \uc801\uc808\ud55c \uc704\uce58\uc640 \uc5f0\uacb0\ud574\uc57c \ub458\uc744 \ub530\ub85c \ubc1b\uc744 \uc218 \uc788\ub2e4. \ubd84\ub9ac\uc758 \uc6d0\ub9ac\uc640 \uc81c\ud488\uc744 \uaebc\ub0b4\ub294 \uad6c\uc870\uac00 \ub9de\uc544\uc57c \ud558\ub294 \uac83\uc774\ub2e4. \uc7a5\uce58\uac00 \ub3cc\uc544\uac04\ub2e4\ub294 \uc0ac\uc2e4\ub9cc \ubcf4\uc544\uc11c\ub294 \uacf5\uc815\uc744 \ub2e4 \uc54c \uc218 \uc5c6\ub2e4. \ub4e4\uc5b4\uc624\ub294 \uc6b0\uc720\uac00 \uc5b4\ub514\ub97c \uc9c0\ub098\uace0 \uac01 \ucd9c\uad6c\uac00 \ubb34\uc5c7\uc744 \ubc1b\ub294\uc9c0 \ub530\ub77c\uac00\uc57c \ud55c\ub2e4. \uc774 \uad00\uc810\uc740 \ub2e4\ub978 \uc0b0\uc5c5 \uae30\uacc4\ub97c \ubcfc \ub54c\ub3c4 \uc720\uc6a9\ud558\ub2e4. \ud070 \ubaa8\ud130\uc640 \ube60\ub978 \ud68c\uc804\ubcf4\ub2e4 \ubb3c\uc9c8\uc758 \uacbd\ub85c\uac00 \uae30\ub2a5\uc744 \uc124\uba85\ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4. \uc6d0\uc2ec\ubd84\ub9ac\uae30\uc758 \uc5ed\uc0ac \ub3c4\ud310\uc740 \ud68c\uc804 \uc6b4\ub3d9\uc774 \uc2dd\ud0c1\uc758 \uc7ac\ub8cc\ub97c \ub2e4\ub8e8\ub294 \uc9c8\uc11c\ub85c \ubc14\ub00c\ub294 \ubaa8\uc2b5\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc6d0\ub8cc\uc758 \ucc28\uc774\ub97c \uc774\uc6a9\ud558\ub824\uba74 \uadf8 \ucc28\uc774\uac00 \ub098\ud0c0\ub098\ub294 \uc790\ub9ac\ub97c \ucc3e\uc544 \uc5f0\uacb0\ud574\uc57c \ud588\ub2e4. \uacc4\uc18d \ucc98\ub9ac\ud560 \uc218 \uc788\ub294 \uae30\uacc4\ub294 \uc55e\ub4a4 \uc791\uc5c5\uacfc\uc758 \uad00\uacc4\ub97c \ubc14\uafbc\ub2e4. \uc6d0\ub8cc\ub97c \ubaa8\uc73c\uace0 \uacf5\uae09\ud558\ub294 \uc77c\uacfc \ubd84\ub9ac\ud55c \uac83\uc744 \ubc1b\uc544 \ub2e4\uc74c \uacf5\uc815\uc73c\ub85c \ubcf4\ub0b4\ub294 \uc77c\uc774 \uc5f0\uacb0\ub41c\ub2e4. \ud55c \uae30\uacc4\uc758 \uc18d\ub3c4\uac00 \uacf5\uc7a5 \uc804\uccb4\uc758 \uc18d\ub3c4\uc640 \ubc18\ub4dc\uc2dc \uac19\uc9c0\ub294 \uc54a\uc9c0\ub9cc \uc791\uc5c5\uc758 \uc0c8\ub85c\uc6b4 \uac00\ub2a5\uc131\uc744 \ub9cc\ub4e0\ub2e4. \uae30\uacc4\ub97c \uc26c\uc9c0 \uc54a\uace0 \uc4f0\ub824\uba74 \uc900\ube44\uc640 \uc138\ucc99, \uc0c1\ud0dc \ud655\uc778\ub3c4 \ud544\uc694\ud558\ub2e4. \uc790\ub3d9\ud654\ub294 \uc0ac\ub78c\uc774 \uc544\ubb34 \uc77c\ub3c4 \ud558\uc9c0 \uc54a\uac8c \ub41c\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uae30\ub2e4\ub9ac\ub358 \uc2dc\uac04\uc740 \uc904\uace0 \ud750\ub984\uc744 \uad00\ub9ac\ud558\ub294 \uc77c\uc774 \ub298 \uc218 \uc788\ub2e4. \uc2dd\ud488 \uac00\uacf5\uc758 \ubcc0\ud654\uc5d0\ub294 \ub178\ub3d9\uc758 \uc704\uce58\uac00 \ubc14\ub00c\ub294 \uacfc\uc815\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \ud06c\ub9bc\uc744 \ub098\ub204\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc2dd\ud488\uc758 \uc704\uc0dd \uc0c1\ud0dc\ub97c \ubc14\uafb8\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub974\ub2e4. \uc6d0\uc2ec\ubd84\ub9ac\uc758 \ubaa9\uc801\uc744 \uc774\ud574\ud560 \ub54c \ub2e4\ub978 \uac00\uacf5 \ub2e8\uacc4\uc640 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ud55c \uacf5\uc815\uc744 \uac70\ucce4\ub2e4\uace0 \uc774\ud6c4\uc758 \ubaa8\ub4e0 \uc870\uac74\uc774 \ud574\uacb0\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774 \uad6c\ubd84\uc740 \uc2dd\ud488\uc758 \uc5ed\uc0ac\ub97c \uc77d\uc744 \ub54c \ud2b9\ud788 \uc911\uc694\ud558\ub2e4. \uc5ec\ub7ec \uae30\uacc4\uac00 \ud55c \uacf5\uc7a5\uc5d0 \ud568\uaed8 \uc788\ub2e4\uace0 \ubaa8\ub450 \uac19\uc740 \uc77c\uc744 \ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uac00\uc5f4\ud558\uace0 \uc2dd\ud788\uba70 \ubd84\ub9ac\ud558\uace0 \ud3ec\uc7a5\ud558\ub294 \ub2e8\uacc4\ub294 \uc11c\ub85c \ub2e4\ub978 \uc9c8\ubb38\uc5d0 \ub2f5\ud55c\ub2e4. \uac01\uc790\uc758 \uae30\ub2a5\uc744 \uc54c\uc544\uc57c \uc804\uccb4 \uacf5\uae09 \uacfc\uc815\uc744 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ud06c\ub9bc\uacfc \uc9c0\ubc29\uc744 \ub35c \ud3ec\ud568\ud55c \ubd80\ubd84\uc740 \uc774\ud6c4 \uc11c\ub85c \ub2e4\ub978 \uc6a9\ub3c4\uc5d0 \uc4f0\uc77c \uc218 \uc788\ub2e4. \uc6b0\uc720\ub97c \ud55c \uc885\ub958\uc758 \uc644\uc131\ud488\uc73c\ub85c\ub9cc \ubcf4\ub294 \ub300\uc2e0 \uc5ec\ub7ec \uc2dd\ud488\uc758 \ucd9c\ubc1c \uc7ac\ub8cc\ub85c \ub2e4\ub8e8\uac8c \ub41c\ub2e4. \ubd84\ub9ac \uae30\uc220\uc740 \uc6d0\ub8cc\uc758 \ud2b9\uc131\uc744 \uc5b4\ub5a4 \uc81c\ud488\uacfc \uc5f0\uacb0\ud560\uc9c0 \uc120\ud0dd\ud558\ub294 \uc77c\uacfc \ub9cc\ub09c\ub2e4. \uc61b \uae30\uc220\uc0ac \ucc45\uc740 \ub099\ub18d \uae30\uacc4\uc758 \ubcf4\uae09\uc744 \ub9e4\uc6b0 \ub099\uad00\uc801\uc73c\ub85c \ubb18\uc0ac\ud55c\ub2e4. \uadf8 \ud3c9\uac00\ub97c \ubaa8\ub4e0 \ub18d\uac00\uc758 \ub3d9\uc77c\ud55c \uacbd\ud5d8\uc73c\ub85c \uc77c\ubc18\ud654\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uae30\uacc4\uc758 \uad6c\uc785\ube44\uc640 \uc6d0\ub8cc\uc758 \uaddc\ubaa8, \uc6b4\uc601 \ub2a5\ub825\uc740 \uc774\uc6a9 \uc870\uac74\uc744 \ub2ec\ub9ac\ud588\uc744 \uac83\uc774\ub2e4. \ubc1c\uba85\uacfc \ubcf4\uae09\uc740 \uac19\uc740 \uc21c\uac04\uc774 \uc544\ub2c8\ub2e4. \uc6b0\ub9ac\ub294 \uc2dd\ud488\uc744 \uba39\uc744 \ub54c \uadf8 \uc804\uc5d0 \uc5b4\ub5a4 \ubb3c\ub9ac\uc801\uc778 \uc791\uc5c5\uc774 \uc788\uc5c8\ub294\uc9c0 \uc0dd\uac01\ud558\uc9c0 \uc54a\uae30 \uc27d\ub2e4. \uc6d0\uc2ec\ubd84\ub9ac\uae30\ub294 \ud68c\uc804\uacfc \ubc00\ub3c4 \ucc28\uc774\uac00 \uc77c\uc0c1\uc758 \uc7ac\ub8cc\ub97c \ub2e4\ub8e8\ub294 \ubc29\ubc95\uc774 \ub420 \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub208\uc5d0 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub358 \uc131\ubd84\uc758 \ucc28\uc774\uac00 \uacf5\uc815\uc758 \uae30\uc900\uc774 \ub41c\ub2e4. \ud06c\ub9bc\uc774 \uc62c\ub77c\uc624\uae30\ub97c \uae30\ub2e4\ub9ac\ub294 \uc7a5\uba74\uacfc \uacc4\uc18d \ud758\ub7ec\ub098\uc624\ub294 \ucd9c\uad6c\ub97c \ub098\ub780\ud788 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uae30\uc220\uc758 \ubcc0\ud654\ub294 \ub300\ub2e8\ud788 \uc0c8\ub85c\uc6b4 \uc74c\uc2dd\uc744 \ub9cc\ub4dc\ub294 \ub370\ub9cc \uc788\uc9c0 \uc54a\uc558\ub2e4. \ube60\ub978 \ucc98\ub9ac\ub77c\ub294 \uc774\uc810\uc740 \uadf8 \uc18d\ub3c4\uc5d0 \ub9de\ucdb0 \uc6d0\ub8cc\uc640 \uacb0\uacfc\ubb3c\uc744 \ub2e4\ub8f0 \uc218 \uc788\uc744 \ub54c \uc0dd\ud65c\uc5d0 \uc774\uc5b4\uc84c\ub2e4. \uc775\uc219\ud55c \uc7ac\ub8cc\ub97c \uc5bb\ub294 \uc2dc\uac04\uacfc \uc21c\uc11c\ub97c \ubc14\uafb8\ub294 \uc77c\ub3c4 \uc2dd\uc0dd\ud65c\uc744 \ubc14\uafbc \uc5ed\uc0ac\uc600\ub2e4."}, {"id": "dasik-sweets-frame", "title": "\uacfc\uc790\ub97c \ub192\uc774 \uc313\ub294 \ub370\uc5d0\ub3c4 \ud2c0\uc774 \ud544\uc694\ud588\ub2e4", "summary": "\uc704\uc544\ub798\uac00 \ub6ab\ub9b0 \uae08\uc18d \ud2c0\uc5d0\uc11c \uc81c\uc0ac\uc0c1 \uc74c\uc2dd\uc758 \ubaa8\uc591\uc744 \uc7a1\ub358 \ubc29\ubc95\uc744 \ubd05\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\uc2dd\ud0c1\uacfc \uc2dd\ud488 \ubcf4\uc874", "categories": ["everyday-inventions"], "url": "stories/dasik-sweets-frame/index.html", "image": "../media/dasik-sweets-frame.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc720\uc81c \ub2e4\uc2dd\uc6b0\ub9ac \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uacfc\uc790\ub97c \ub192\uc774 \uc313\ub294 \ub370\uc5d0\ub3c4 \ud2c0\uc774 \ud544\uc694\ud588\ub2e4 \uc774\ub984\uc740 \ub0af\uc124\uc9c0\ub9cc \uc4f0\uc784\uc740 \uc120\uba85\ud55c \ub2e4\uc2dd\uc6b0\ub9ac \uc704\uc544\ub798\uac00 \ub6ab\ub9b0 \uae08\uc18d \ud2c0\uc5d0\uc11c \uc81c\uc0ac\uc0c1 \uc74c\uc2dd\uc758 \ubaa8\uc591\uc744 \uc7a1\ub358 \ubc29\ubc95\uc744 \ubd05\ub2c8\ub2e4. \uc2dd\ud0c1\uacfc \uc2dd\ud488 \ubcf4\uc874 \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \uc791\uc740 \uc6d0\ud1b5 \ud558\ub098\uac00 \ub193\uc5ec \uc788\ub2e4. \uc606\uc740 \uae30\ub465 \uc0ac\uc774\ub85c \ud6e4\ud788 \ubcf4\uc774\uace0 \uc704\uc640 \uc544\ub798\ub3c4 \ub6ab\ub824 \uc788\ub2e4. \ubb3c\uc744 \ub2f4\ub294 \uadf8\ub987 \uac19\uc9c0\ub294 \uc54a\ub2e4. \ubb34\uc5c7\uc5d0 \uc37c\uc744\uae4c \uad81\uae08\ud574\uc9c0\ub294 \uc21c\uac04, \uc774\ub984\uc744 \uc77d\ub294\ub2e4. \ub2e4\uc2dd\uc6b0\ub9ac\ub2e4. \uc6b0\ub9ac\ub77c\ub294 \ub9d0 \ub54c\ubb38\uc5d0 \ubb34\uc5c7\uc744 \uac00\ub450\ub294 \uc791\uc740 \uc6b8\ud0c0\ub9ac\ub97c \ub5a0\uc62c\ub838\ub2e4\uba74 \uc4f0\uc784\uc5d0 \uc870\uae08 \uac00\uae4c\uc774 \uac04 \uc148\uc774\ub2e4. \ub2e4\ub9cc \uc774 \uc548\uc5d0\uc11c \uc790\ub9ac\ub97c \uc7a1\ub294 \uac83\uc740 \ub3d9\ubb3c\uc774 \uc544\ub2c8\ub77c \uc74c\uc2dd\uc774\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc740 \uc6b0\ub9ac\ub97c \uc81c\uc0ac\uc5d0 \uc4f0\ub294 \uadf8\ub987\uc758 \ud55c \uc885\ub958\ub85c \uc124\uba85\ud55c\ub2e4. \uc0b0\uc790\uc640 \ub2e4\uc2dd, \uc57d\uacfc \uac19\uc740 \uc74c\uc2dd\uc744 \ub192\uc774 \uc313\uc744 \ub54c \uace0\uc815\ud558\ub294 \ub370 \uc0ac\uc6a9\ud588\ub2e4\ub294 \uac83\uc774\ub2e4. \ub2e4\uc2dd\uc6b0\ub9ac\ub294 \uadf8\uc911 \ub2e4\uc2dd\uc744 \uace0\uc815\ud558\ub294 \ubb3c\uac74\uc774\ub2e4. \uc2dd\ud0c1 \uc704\uc5d0 \uacfc\uc790\ub97c \ub192\uc774 \ud3ec\uac1c\uc5b4 \ubcf8\ub2e4\uba74 \ub9e8 \uc544\ub798 \uac83\ub9cc \uc798 \ub193\ub294\ub2e4\uace0 \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc0dd\uac01\uc774 \ub4e0\ub2e4. \uc774 \ubb3c\uac74\uc740 \uc313\uc740 \ud615\ud0dc\ub97c \ubd99\ub4e4\uc5b4 \uc8fc\ub294 \ud2c0\uc774\ub77c\ub294 \uc4f0\uc784\uc744 \uac16\ub294\ub2e4. \uc74c\uc2dd \uc790\uccb4\ubfd0 \uc544\ub2c8\ub77c \uc74c\uc2dd\uc744 \uc5b4\ub5a4 \ubaa8\uc2b5\uc73c\ub85c \uc62c\ub9b4\uc9c0\ub3c4 \uc900\ube44\ud55c \uc148\uc774\ub2e4. \uc774 \uc18c\uc7a5\ud488\uc740 \uc704\uc544\ub798\uac00 \ub6ab\ub9b0 \uc6d0\ud1b5\ud615\uc774\uba70 \uc606\uba74\uc740 \uc5ec\ub35f \uae30\ub465\uc73c\ub85c \uc774\ub8e8\uc5b4\uc838 \uc788\ub2e4. \uae30\ub465\uc5d0\ub294 \ubd80\ucc44 \uac19\uc740 \ud615\ud0dc\uc758 \uc7a5\uc2dd\ub3c4 \uc788\ub2e4. \ubcf4\uae30\uc5d0\ub294 \uac00\ubcbc\uc6b4 \uc6b8\ud0c0\ub9ac \uac19\uc9c0\ub9cc \ub458\ub808\ub97c \uc7a1\uc544 \uc8fc\ub294 \ubaa8\uc591\uc774\ub2e4. \ubcc4\ub3c4\uc758 \ub2e4\uc2dd\uc6b0\ub9ac\ub300\uc640 \ud55c \uc9dd\uc744 \uc774\ub8e8\uc5b4 \ubc1b\uce68 \uc704\uc5d0 \uace0\uc815\ud588\ub2e4\uace0 \ud55c\ub2e4. \uad6c\uba4d \ub09c \uc6d0\ud1b5 \ud558\ub098\uac00 \ud63c\uc790 \ubc14\ub2e5\uc5d0 \ub193\uc774\ub294 \uac83\ub9cc \uc0dd\uac01\ud558\uba74 \uc4f0\uc784\uc744 \ub193\uce58\uae30 \uc27d\ub2e4. \ud568\uaed8 \uc0ac\uc6a9\ud558\ub294 \ubc1b\uce68\uae4c\uc9c0 \ub5a0\uc62c\ub824\uc57c \uad6c\uc870\uac00 \uc774\uc5b4\uc9c4\ub2e4. \uc74c\uc2dd\uc740 \uba39\uc744 \uc7ac\ub8cc\ub85c \uc900\ube44\ub418\uc9c0\ub9cc \uc758\ub840\uc5d0\uc11c\ub294 \ub193\ub294 \ud615\ud0dc\ub3c4 \uc911\uc694\ud574\uc9c8 \uc218 \uc788\ub2e4. \ub192\uc774 \uc313\uc740 \uacfc\uc790\ub97c \uc77c\uc815\ud55c \ubaa8\uc2b5\uc73c\ub85c \uc720\uc9c0\ud558\ub824\uba74 \uc8fc\ubcc0\uc744 \uc7a1\uc544 \uc8fc\ub294 \ub3c4\uad6c\uac00 \ud544\uc694\ud558\ub2e4. \ub2e4\uc2dd\uc6b0\ub9ac\ub294 \uadf8\ub7f0 \uc77c\uc5d0 \uc4f0\uc778\ub2e4\uace0 \uc124\uba85\ub41c\ub2e4. \uc870\ub9ac\ud558\ub294 \uae30\uc220\uacfc \ucc28\ub9ac\ub294 \uae30\uc220\uc774 \ubaa8\ub450 \uc74c\uc2dd\uc758 \uc5ed\uc0ac \uc548\uc5d0 \uc788\uc5c8\ub358 \uc148\uc774\ub2e4. \uc774\uac83\uc744 \uc624\ub298\uc758 \uc811\uc2dc\uc5d0 \uacfc\uc790\ub97c \uc313\ub294 \ub180\uc774\uc640 \uc644\uc804\ud788 \uac19\uc740 \ud48d\uc2b5\uc774\ub77c\uace0 \ub193\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc81c\uc0ac\uc5d0 \uc4f0\ub294 \ub3c4\uad6c\ub77c\ub294 \ub9e5\ub77d\uc774 \ub530\ub85c \uc788\ub2e4. \ud604\ub300\uc758 \ube44\uc720\ub294 \uc9c0\uc9c0\ud558\ub294 \ud2c0\uc774 \uc65c \ud544\uc694\ud55c\uc9c0 \uc774\ud574\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub420 \ubfd0\uc774\ub2e4. \uc2e4\uc81c \uc5b4\ub5a4 \uc758\ub840\uc5d0\uc11c \uc5bc\ub9c8\ub098 \uc313\uc558\ub294\uc9c0\uc640 \uadf8\ub0a0\uc758 \ubc30\uce58\ub294 \ud574\ub2f9 \uae30\ub85d\uc774 \ub354 \ud544\uc694\ud55c \ubb38\uc81c\ub85c \ub0a8\uaca8 \ub454\ub2e4. \uc704\uc544\ub798\uac00 \ub6ab\ub9ac\uace0 \uc606\uba74\uc774 \uae30\ub465\uc73c\ub85c \ub41c \ubaa8\uc2b5\uc740 \uc74c\uc2dd\uc744 \uc804\ubd80 \ub2f4\ub294 \uae4a\uc740 \uadf8\ub987\uacfc \ub2e4\ub974\ub2e4. \ud2c0\uc758 \ub458\ub808\uac00 \ud615\ud0dc\ub97c \uc7a1\uc544 \uc8fc\uace0 \uc548\ucabd\uc5d0\ub294 \uc313\uc744 \uc790\ub9ac\uac00 \uc0dd\uae34\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \ube44\uc5b4 \ubcf4\uc774\ub294 \ubd80\ubd84\uc744 \ube60\uc9c4 \uc870\uac01\uc774\ub77c\uace0 \uba3c\uc800 \uc0dd\uac01\ud558\uc9c0 \ub9d0\uace0, \uc560\ucd08\uc5d0 \uadf8\ub7f0 \uad6c\uc870\ub85c \ub9cc\ub4e0 \ubb3c\uac74\uc778\uc9c0 \ud574\uc124\uacfc \ud568\uaed8 \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \uc5ec\ub35f \uae30\ub465\uc774\ub77c\ub294 \uc124\uba85\uc740 \uc606\uba74\uc758 \ubc18\ubcf5\uc744 \uc77d\uac8c \ud55c\ub2e4. \uae30\ub465\uacfc \uae30\ub465 \uc0ac\uc774\uc5d0 \uac04\uaca9\uc774 \uc788\uace0 \uc0c1\ubd80\uc640 \uc544\ub798\ucabd\uc774 \uadf8 \uad00\uacc4\ub97c \ubb36\ub294\ub2e4. \uc815\ud655\ud55c \uc81c\uc791 \uce58\uc218\ub97c \ubab0\ub77c\ub3c4 \uc804\uccb4\uc640 \ubd80\ubd84\uc774 \uc5b4\ub5bb\uac8c \uc774\uc5b4\uc9c0\ub294\uc9c0 \ubcfc \uc218 \uc788\ub2e4. \ubb3c\uac74\uc744 \ubc1b\uce58\ub294 \uc120\uacfc \ube44\uc5b4 \uc788\ub294 \uacf5\uac04\uc774 \ud568\uaed8 \uae30\ub2a5\uc744 \ub9cc\ub4e0\ub2e4\ub294 \uc810\uc5d0\uc11c \uac74\ucd95\uc758 \uc791\uc740 \uad6c\uc870\ub97c \ubcf4\ub294 \ub4ef\ud55c \uc7ac\ubbf8\ub3c4 \uc788\ub2e4. \ubcc4\ub3c4\uc758 \uc6b0\ub9ac\ub300\uc640 \uc9dd\uc744 \uc774\ub8ec\ub2e4\ub294 \uc815\ubcf4\ub294 \uc0ac\uc9c4 \uc18d \ud55c \uc810\ub9cc\uc73c\ub85c \uc0c1\uc758 \ubaa8\uc2b5\uc744 \ub05d\ub0b4\uc9c0 \uc54a\uac8c \ud55c\ub2e4. \uace0\uc815\ud560 \ud2c0\uacfc \uadf8\uac83\uc744 \ub193\ub294 \ubc14\ud0d5\uc774 \ud568\uaed8 \ud544\uc694\ud588\ub2e4. \ubc15\ubb3c\uad00\uc5d0\uc11c \ub3c4\uad6c\ub97c \ub530\ub85c \ubd84\ub958\ud574 \uc18c\uac1c\ud558\ub354\ub77c\ub3c4 \uc2e4\uc81c\ub85c\ub294 \uc5ec\ub7ec \ubd80\ud488\uc774 \uad00\uacc4\ub97c \ub9fa\uc73c\uba70 \uc0ac\uc6a9\ub420 \uc218 \uc788\ub2e4. \uc18c\uc7a5\ud488\uc758 \ub2e8\uc704\uc640 \uc0ac\uc6a9\uc758 \ub2e8\uc704\uac00 \ud56d\uc0c1 \uac19\uc9c0\ub294 \uc54a\ub2e4. \uc774\uac83\uc744 \uc54c\uace0 \ubcf4\uba74 \uc804\uc2dc \uc124\uba85\uc5d0\uc11c \ud55c \uc870\ub098 \uc9dd\uc774\ub77c\ub294 \ub9d0\ub3c4 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \uc77d\ud78c\ub2e4. \ub2e8\uc21c\ud788 \uac19\uc740 \ubaa8\uc591 \ub450 \uac1c\ub77c\ub294 \ub73b\ub9cc\uc740 \uc544\ub2d0 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ub2e4\ub9cc \uc774 \uc790\ub8cc\ub85c \uc804\uccb4 \uc81c\uae30\uc758 \uc218\uc640 \uc815\ud655\ud55c \ubc30\uce58\ub97c \uc0c8\ub85c \ud655\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud655\uc778\ub41c \ubc1b\uce68\uacfc \ud2c0\uc758 \uc5f0\uacb0\ubd80\ud130 \ub530\ub77c\uac00\uba74 \ucda9\ubd84\ud558\ub2e4. \ud55c \ubb3c\uac74\uc744 \uc124\uba85\ud558\ub294 \ub370 \uc606\uc758 \ubb3c\uac74\uc774 \ud544\uc694\ud55c \uacbd\uc6b0\ub2e4. \uc0c1\ubd80\uc5d0 \uc74c\uac01\ud55c \u8336\u98df\uc740 \uc774 \ub3c4\uad6c\uc758 \uc774\ub984\uacfc \uc5f0\uacb0\ub418\ub294 \ud45c\uc9c0\ub2e4. \ubaa8\uc591\ub9cc \ubcf4\uc558\uc744 \ub54c\ub294 \ubb34\uc5c7\uc744 \uace0\uc815\ud558\ub294\uc9c0 \uc54c\uae30 \uc5b4\ub824\uc6cc\ub3c4 \uae00\uc790\uac00 \uc6a9\ub3c4\ub97c \ucc3e\ub294 \ub2e8\uc11c\uac00 \ub41c\ub2e4. \uc5ec\uae30\uc11c \ubb38\uc790\ub294 \uac10\uc0c1\ud560 \uc7a5\uc2dd\uc774\uba74\uc11c \uc2e4\uc81c \uc77c\uc744 \uad6c\ubd84\ud558\ub294 \uc815\ubcf4\uac00 \ub420 \uc218 \uc788\ub2e4. \uc74c\uc2dd\uc758 \uc885\ub958\uc5d0 \ub9de\ucd98 \ub3c4\uad6c\ub97c \uc54c\uc544\ubcf4\uac8c \ud558\ub294 \uc5ed\ud560\uc774\ub2e4. \uc774\ub984\uc744 \uc548 \ub4a4\uc5d0\ub294 \uacfc\uc790 \uc790\uccb4\ubcf4\ub2e4 \uadf8\uac83\uc744 \ucc28\ub9ac\ub358 \uc0ac\ub78c\uc758 \uc900\ube44\ub97c \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uc644\uc131\ud55c \uc0c1\uc740 \ud55c \uc7a5\uba74\uc774\uc9c0\ub9cc \uadf8 \ub4a4\uc5d0\ub294 \ub3c4\uad6c\ub97c \uad6c\ubd84\ud558\uace0 \ub9de\ucd94\uba70 \ub192\uc774\ub97c \uc720\uc9c0\ud558\ub294 \uc190\uc77c\uc774 \uc788\uc5c8\ub2e4. \uc791\uc740 \uc6d0\ud1b5\ud615 \ubb3c\uac74\uc740 \uadf8 \uc2dc\uac04\uc744 \ub0a8\uacbc\ub2e4. \uba39\uc744\uac70\ub9ac\uc758 \uc5ed\uc0ac\ub97c \ub9db\uacfc \uc7ac\ub8cc\uc5d0\uc11c \ucc28\ub9ac\ub294 \ud615\uc2dd\uae4c\uc9c0 \ub113\ud600 \ubcf4\ub294 \uc785\uad6c\ub2e4. \uc6d0\ud1b5 \uc704\ucabd \ubc14\uae65\uc5d0\ub294 \ub2e4\uc2dd\uc744 \ub73b\ud558\ub294 \u8336\u98df \ub450 \uae00\uc790\ub97c \uc0c8\uacbc\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc6a9\ub3c4\ub97c \uad6c\ubcc4\ud558\uae30 \uc704\ud55c \ud45c\uc2dc\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \ube44\uc2b7\ud55c \ubb3c\uac74\uc774 \uc788\uc5b4\ub3c4 \ubb34\uc5c7\uc744 \ub9e1\ub294\uc9c0 \uae00\uc790\ub85c \uc54c\ub824 \uc8fc\ub294 \uac83\uc774\ub2e4. \ub0af\uc120 \uc81c\uae30 \uc774\ub984\uc744 \uc5ec\ub7ec \uac1c \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uc88b\ub2e4. \uc624\ub298\uc740 \uacfc\uc790\ub97c \ub192\uc774 \uc313\ub294 \uc77c\uc5d0\ub3c4 \ud2c0\uacfc \ubc1b\uce68, \uc6a9\ub3c4\ub97c \uc801\uc740 \uae00\uc528\uac00 \uc788\uc5c8\ub2e4\ub294 \uc810\uc744 \uae30\uc5b5\ud574 \ubcf4\uc790. \uadf8\ub987\ucc98\ub7fc \ubcf4\uc774\uc9c0 \uc54a\ub358 \uc6d0\ud1b5\uc774 \uc81c\uc0ac\uc0c1 \uc74c\uc2dd\uc758 \ubaa8\uc591\uc744 \ub9cc\ub4dc\ub294 \ub3c4\uad6c\ub85c \ubc14\ub00c\uc5b4 \ubcf4\uc778\ub2e4."}, {"id": "dewar-vacuum-flask-and-heat", "title": "\ubcf4\uc628\ubcd1 \u2014 \ucc28\uac00\uc6b4 \uc2e4\ud5d8\uc744 \uc9c0\ud0a4\ub358 \ubcd1\uc774 \uc0dd\ud65c\ub85c \ub4e4\uc5b4\uc624\ub2e4", "summary": "\uc561\uccb4 \uacf5\uae30\ub97c \ubcf4\uc874\ud558\ub358 \uc9c4\uacf5 \uc6a9\uae30\uc640 \uc5f4\uc804\ub2ec\uc758 \uc6d0\ub9ac\uc5d0\uc11c \ubcf4\uc628\ubcd1\uc758 \uae30\ub2a5\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\uc9d1\uacfc \uc0dd\ud65c \ub3c4\uad6c", "categories": ["everyday-inventions"], "url": "stories/dewar-vacuum-flask-and-heat/index.html", "image": "../media/dewar-vacuum-flask-and-heat.png", "alt": "\uc2e4\ud5d8\uc2e4\uc758 \uc774\uc911\ubcbd \uc720\ub9ac \uc6a9\uae30\uc640 \uc0dd\ud65c\uc6a9 \ubcf4\uc628\ubcd1\uc744 \ud568\uaed8 \ub5a0\uc62c\ub9b0 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ubcf4\uc628\ubcd1 \u2014 \ucc28\uac00\uc6b4 \uc2e4\ud5d8\uc744 \uc9c0\ud0a4\ub358 \ubcd1\uc774 \uc0dd\ud65c\ub85c \ub4e4\uc5b4\uc624\ub2e4 \ub4c0\uc5b4\uc758 \ub0ae\uc740 \uc628\ub3c4 \uc5f0\uad6c\uc640 \uc0dd\ud65c \uc18d \ub2e8\uc5f4 \uad6c\uc870\uc758 \uc5f0\uacb0 \uc561\uccb4 \uacf5\uae30\ub97c \ubcf4\uc874\ud558\ub358 \uc9c4\uacf5 \uc6a9\uae30\uc640 \uc5f4\uc804\ub2ec\uc758 \uc6d0\ub9ac\uc5d0\uc11c \ubcf4\uc628\ubcd1\uc758 \uae30\ub2a5\uc744 \uc774\ud574\ud569\ub2c8\ub2e4. \uc9d1\uacfc \uc0dd\ud65c \ub3c4\uad6c \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \ubcf4\uc628\ubcd1\uc5d0\ub294 \ub728\uac70\uc6b4 \ucc28\ub3c4 \ub2f4\uace0 \ucc28\uac00\uc6b4 \ubb3c\ub3c4 \ub2f4\ub294\ub2e4. \uac19\uc740 \ubcd1\uc774 \uc11c\ub85c \ubc18\ub300\uc758 \uc77c\uc744 \ud558\ub294 \uac83\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc \uc6d0\ub9ac\ub294 \uc5f0\uacb0\ub418\uc5b4 \uc788\ub2e4. \uc548\uc758 \uc628\ub3c4\ub97c \uc0c8\ub85c \ub9cc\ub4e4\uc5b4 \ub0b4\uae30\ubcf4\ub2e4 \ubc14\uae65\uacfc \uc5f4\uc774 \uc624\uac00\ub294 \uc18d\ub3c4\ub97c \uc904\uc774\ub294 \uac83\uc774\ub2e4. \uc774 \uc775\uc219\ud55c \ubb3c\uac74\uc758 \uc5ed\uc0ac\uc5d0\ub294 \uc544\uc8fc \ub0ae\uc740 \uc628\ub3c4\ub97c \ub2e4\ub8e8\ub358 \uc2e4\ud5d8\uc2e4\uc774 \uc788\ub2e4. 19\uc138\uae30 \ub9d0 \uc81c\uc784\uc2a4 \ub4c0\uc5b4\uc640 \uad00\ub828\ub41c \uc9c4\uacf5 \uc6a9\uae30\ub294 \uc561\uccb4 \uacf5\uae30 \uac19\uc740 \ubb3c\uc9c8\uc744 \ub2e4\ub8e8\ub294 \uc5f0\uad6c\uc5d0\uc11c \uc911\uc694\ud588\ub2e4. \ucc28\uac00\uc6c0\uc744 \uc624\ub798 \uc9c0\ud0a4\ub824\ub294 \ud544\uc694\ub97c \ub530\ub77c\uac00 \ubcf4\uba74 \uc0dd\ud65c\uc6a9\ud488\uc758 \uae30\ub2a5\uc744 \uc0c8\ub86d\uac8c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ubcf4\uc628\ubcd1\uc740 \uc5b4\ub5bb\uac8c \ub728\uac70\uc6b4 \uac83\uacfc \ucc28\uac00\uc6b4 \uac83 \uc591\ucabd\uc744 \ub3c4\uc6b8 \uc218 \uc788\uc744\uae4c. \uacf5\uae30\ub97c \ub9e4\uc6b0 \ub0ae\uc740 \uc628\ub3c4\uc5d0\uc11c \uc561\uccb4\ub85c \ub9cc\ub4e4\uba74 \ud3c9\ubc94\ud55c \uc8fc\ubcc0 \ud658\uacbd\uc774 \uc0c1\ub300\uc801\uc73c\ub85c \ub530\ub73b\ud558\uac8c \ub290\uaef4\uc9c4\ub2e4. \uc2e4\ud5d8\uc2e4\uc758 \ud0c1\uc790\uc640 \uc190, \ubc29 \uc548\uc758 \uacf5\uae30\uac00 \ubaa8\ub450 \uc5f4\uc744 \uc804\ub2ec\ud558\ub294 \ucabd\uc774 \ub41c\ub2e4. \uc561\uccb4\uac00 \uc5bc\ub9c8\ub098 \ucc28\uac00\uc6b4\uc9c0\ub9cc\ud07c \uadf8\uac83\uc744 \uc5b4\ub5a4 \uadf8\ub987\uc5d0 \ub2f4\ub294\uc9c0\uac00 \uc911\uc694\ud588\ub2e4. 1900\ub144\uc5d0 \ub098\uc628 \uae30\uc220\uc0ac \ucc45\uc740 \uc561\uccb4 \uacf5\uae30\ub97c \ubcf4\uc874\ud558\ub294 \uc7a5\uce58\ub85c \ub4c0\uc5b4\uc758 \uc9c4\uacf5 \uc6a9\uae30\ub97c \uc18c\uac1c\ud55c\ub2e4. \uc774\ub54c \uc6a9\uae30\ub294 \uc2e4\ud5d8\uc744 \ub2f4\ub294 \uc218\ub3d9\uc801\uc778 \ubc30\uacbd\uc774 \uc544\ub2c8\ub2e4. \uc5f0\uad6c\ud560 \ubb3c\uc9c8\uc758 \uc0c1\ud0dc\ub97c \uc720\uc9c0\ud558\uac8c \ud558\ub294 \ub3c4\uad6c\uc600\ub2e4. \uc0c8\ub85c\uc6b4 \ubb3c\uc9c8\uc744 \ub9cc\ub4dc\ub294 \uae30\uc220\uacfc \uadf8\uac83\uc744 \uc7a0\uc2dc\ub77c\ub3c4 \ub2e4\ub8f0 \uc218 \uc788\uac8c \ud558\ub294 \uae30\uc220\uc774 \ud568\uaed8 \ud544\uc694\ud588\ub2e4. \uc9c4\uacf5 \uc6a9\uae30\uc758 \uc911\uc694\ud55c \ud2b9\uc9d5\uc740 \ub450 \uacb9\uc758 \ubcbd \uc0ac\uc774\uc5d0 \uacf5\uae30\uac00 \uac70\uc758 \uc5c6\ub294 \uacf5\uac04\uc744 \ub450\ub294 \uac83\uc774\ub2e4. \uc548\ucabd\uacfc \ubc14\uae65\ucabd \ubcbd\uc744 \ub530\ub85c \uc0dd\uac01\ud558\uba74 \ub2e8\uc21c\ud574 \ubcf4\uc774\uc9c0\ub9cc, \uadf8 \uc0ac\uc774\uc758 \uc870\uac74\uc774 \uc5f4\uc758 \uc774\ub3d9\uc744 \ubc14\uafbc\ub2e4. \ubcd1\uc758 \ub450\uaed8\ub97c \ubb34\uc870\uac74 \ub298\ub9ac\ub294 \ubc29\uc2dd\uacfc\ub294 \ub2e4\ub978 \ud574\ubc95\uc774\ub2e4. \ud3c9\ubc94\ud55c \ubcbd\uc5d0\uc11c\ub294 \uc7ac\ub8cc\ub97c \ub530\ub77c \uc5f4\uc774 \uc804\ub2ec\ub418\uace0 \uc8fc\ubcc0\uc758 \uacf5\uae30\ub3c4 \uc5f4\uc744 \uc62e\uae34\ub2e4. \ub450 \ubcbd \uc0ac\uc774\uc758 \uacf5\uac04\uc744 \uc9c4\uacf5\uc5d0 \uac00\uae5d\uac8c \ub9cc\ub4e4\uba74 \uc774\ub7f0 \uc804\ub2ec \uacbd\ub85c\ub97c \uc904\uc77c \uc218 \uc788\ub2e4. \ubb3c\uac74\uc758 \uc131\ub2a5\uc774 \ub2e8\ub2e8\ud55c \uc7ac\ub8cc\uc5d0\ub9cc \ub2ec\ub9b0 \uac83\uc774 \uc544\ub2c8\ub77c \uc7ac\ub8cc \uc0ac\uc774\uc5d0 \ubb34\uc5c7\uc744 \ub0a8\uae30\uac70\ub098 \ube44\uc6b0\ub294\uc9c0\uc5d0\ub3c4 \ub2ec\ub824 \uc788\ub294 \uc148\uc774\ub2e4. \uacf5\uae30\uac00 \uac70\uc758 \uc5c6\ub2e4\uace0 \uc5f4\uc758 \uc774\ub3d9\uc774 \uc644\uc804\ud788 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubcf5\uc0ac\ucc98\ub7fc \uacf5\uac04\uc744 \uac74\ub108\ub294 \ubc29\uc2dd\ub3c4 \uc788\uace0 \ubcd1\uc758 \uc785\uad6c\uc640 \uc5f0\uacb0\ub41c \ubd80\ubd84\uc744 \ud1b5\ud55c \uacbd\ub85c\ub3c4 \uc788\ub2e4. \uadf8\ub798\uc11c \uc9c4\uacf5\uc774\ub77c\ub294 \ud55c \ub2e8\uc5b4\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc131\ub2a5\uc744 \uc124\uba85\ud558\uae30 \uc5b4\ub835\ub2e4. \uc804\uccb4 \uad6c\uc870\ub97c \ud568\uaed8 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc774 \uc810\uc740 \uc0dd\ud65c\uc5d0\uc11c \uacbd\ud5d8\ud558\ub294 \ubcc0\ud654\uc640\ub3c4 \ub9de\ub294\ub2e4. \ubcf4\uc628\ubcd1\uc5d0 \ub123\uc740 \ub0b4\uc6a9\ubb3c\uc758 \uc628\ub3c4\ub294 \uc2dc\uac04\uc774 \uc9c0\ub098\uba74 \ubc14\ub010\ub2e4. \ubcd1\uc740 \uc601\uc6d0\ud788 \uac19\uc740 \uc628\ub3c4\ub97c \ubcf4\uc7a5\ud558\ub294 \uc7a5\uce58\uac00 \uc544\ub2c8\ub77c \ubcc0\ud654\uc758 \uc18d\ub3c4\ub97c \ub2a6\ucd94\ub294 \uc7a5\uce58\ub2e4. \uc798 \uc791\ub3d9\ud55c\ub2e4\ub294 \ub73b\uc744 \ubcc0\ud654\uac00 \uc804\ud600 \uc5c6\ub2e4\ub294 \ub73b\uc73c\ub85c \uc774\ud574\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \uc5f4\uc740 \uc628\ub3c4\uac00 \ub192\uc740 \ucabd\uc5d0\uc11c \ub0ae\uc740 \ucabd\uc73c\ub85c \uc774\ub3d9\ud55c\ub2e4. \uc544\uc8fc \ucc28\uac00\uc6b4 \uc561\uccb4\ub97c \ub2f4\uc73c\uba74 \ubc14\uae65\uc5d0\uc11c \uc548\uc73c\ub85c \ub4e4\uc5b4\uc624\ub294 \uc5f4\uc774 \ubb38\uc81c\ub2e4. \ub728\uac70\uc6b4 \ucc28\ub97c \ub2f4\uc73c\uba74 \uc548\uc5d0\uc11c \ubc14\uae65\uc73c\ub85c \ub098\uac00\ub294 \uc5f4\uc774 \ubb38\uc81c\uac00 \ub41c\ub2e4. \uc774\ub3d9\uc744 \uc904\uc774\ub294 \uad6c\uc870\ub294 \ub450 \uacbd\uc6b0\uc5d0 \ubaa8\ub450 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\ub2e4. \uc774\ub807\uac8c \ubcf4\uba74 \ubcf4\uc628\uacfc \ubcf4\ub0c9\uc740 \uc804\ud600 \ub2e4\ub978 \ub9c8\ubc95\uc774 \uc544\ub2c8\ub2e4. \uc5b4\ub290 \ucabd\uc774 \ub354 \ub530\ub73b\ud55c\uc9c0\uc5d0 \ub530\ub77c \ubc29\ud5a5\uc774 \ubc14\ub014 \ubfd0, \uc628\ub3c4 \ucc28\uc774\uc5d0 \ub530\ub978 \uad50\ud658\uc744 \ub2a6\ucd98\ub2e4\ub294 \uc6d0\ub9ac\ub294 \uc774\uc5b4\uc9c4\ub2e4. \ubb3c\uac74\uc758 \uc774\ub984\uc774 \ud55c \uac00\uc9c0 \uc6a9\ub3c4\ub97c \uba3c\uc800 \ub5a0\uc62c\ub9ac\uac8c \ud574\ub3c4 \uc2e4\uc81c \uae30\ub2a5\uc740 \ub354 \ub113\uc744 \uc218 \uc788\ub2e4. \uc5f0\uad6c\uc2e4\uc5d0\uc11c \uc798 \uc791\ub3d9\ud558\ub294 \uc6a9\uae30\ub97c \uc77c\uc0c1\uc5d0\uc11c \uc4f0\ub824\uba74 \ub2e4\ub978 \uc870\uac74\ub3c4 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \uc0ac\ub78c\uc774 \ub4e4\uace0 \ub2e4\ub2c8\uace0 \ub69c\uaed1\uc744 \uc5f4\uace0 \ub2eb\uc73c\uba70 \uc53b\uace0 \ubcf4\uad00\ud55c\ub2e4. \uc5f4\uc744 \ub9c9\ub294 \ub2a5\ub825\ub9cc \uc88b\ub2e4\uace0 \uc88b\uc740 \uc0dd\ud65c\uc6a9\ud488\uc774 \ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc0ac\uc6a9\uc790\uac00 \ub9e4\uc77c \ub2e4\ub8f0 \uc218 \uc788\ub294 \ud615\ud0dc\uc640 \ub0b4\uad6c\uc131\uc774 \ud544\uc694\ud558\ub2e4. \uc774\uac83\uc740 \uc2e4\ud5d8\uc2e4\uc758 \ubc1c\uba85\uacfc \ub300\uc911\uc801\uc778 \uc81c\ud488 \uc0ac\uc774\uc758 \uac70\ub9ac\ub2e4. \uc0c8\ub85c\uc6b4 \uc6d0\ub9ac\ub97c \ubc1c\uacac\ud558\ub294 \uc77c\uacfc \uc548\uc804\ud558\uace0 \ud3b8\ub9ac\ud558\uac8c \ubc18\ubcf5 \uc0ac\uc6a9\ud558\ub294 \ubb3c\uac74\uc73c\ub85c \ub9cc\ub4dc\ub294 \uc77c\uc740 \uc5f0\uacb0\ub418\uc9c0\ub9cc \uac19\uc740 \ub2e8\uacc4\ub294 \uc544\ub2c8\ub2e4. \uc775\uc219\ud55c \ubcf4\uc628\ubcd1\uc758 \ubaa8\uc591\uc5d0\ub294 \uc0ac\uc6a9 \ud658\uacbd\uc5d0 \ub9de\ucd94\ub294 \ubcc4\ub3c4\uc758 \uc124\uacc4 \ubb38\uc81c\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \ubcbd\ub9cc \ud6cc\ub96d\ud574\ub3c4 \uc5f4\uc774 \ub4dc\ub098\ub4dc\ub294 \ub2e4\ub978 \uacbd\ub85c\uac00 \ud06c\uba74 \uc804\uccb4 \uc131\ub2a5\uc740 \ub2ec\ub77c\uc9c4\ub2e4. \ub69c\uaed1\uc744 \uc790\uc8fc \uc5f4\uba74 \uc548\uacfc \ubc16\uc774 \uc9c1\uc811 \ub9cc\ub098\uace0, \uc785\uad6c\uc640 \uc5f0\uacb0 \ubd80\uc704\ub3c4 \uc5f4\uc774 \uc774\ub3d9\ud558\ub294 \uae38\uc774 \ub41c\ub2e4. \ubcf4\uc628\ubcd1\uc744 \ubcfc \ub54c \uac00\uc6b4\ub370\uc758 \ube48 \uacf5\uac04\ub9cc \uc0dd\uac01\ud558\uc9c0 \ub9d0\uc544\uc57c \ud558\ub294 \uc774\uc720\ub2e4. \uc774\ub7f0 \uad00\ucc30\uc740 \ub2e4\ub978 \uae30\uc220\uc744 \uc774\ud574\ud560 \ub54c\ub3c4 \uc720\uc6a9\ud558\ub2e4. \uac00\uc7a5 \ub208\uc5d0 \ub744\ub294 \uc6d0\ub9ac \ud558\ub098\uac00 \uc804\uccb4 \uacb0\uacfc\ub97c \ud63c\uc790 \uacb0\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc5f0\uacb0\ub418\ub294 \ubd80\ubd84\uacfc \uc0ac\uc6a9 \ubc29\uc2dd\uc774 \ud568\uaed8 \uc791\ub3d9\ud55c\ub2e4. \ubcf4\uc628\ubcd1\uc740 \uc791\uace0 \uce5c\uc219\ud55c \ubb3c\uac74\uc774\uc9c0\ub9cc, \uc2dc\uc2a4\ud15c\uc758 \uc131\ub2a5\uc774 \uc5ec\ub7ec \uacbd\ub85c\uc758 \ud569\uc774\ub77c\ub294 \uc0ac\uc2e4\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ubcf4\uc628\ubcd1\uc744 \ub728\uac70\uc6b4 \uc74c\ub8cc\uc758 \ubb3c\uac74\uc73c\ub85c\ub9cc \uc54c\ub358 \uc0ac\ub78c\uc5d0\uac8c \ub4c0\uc5b4\uc758 \uc9c4\uacf5 \uc6a9\uae30\ub294 \ub73b\ubc16\uc758 \ucd9c\ubc1c\uc810\uc774\ub2e4. \uc5f0\uad6c\uc790\uac00 \ucc28\uac00\uc6b4 \ubb3c\uc9c8\uc744 \ub2e4\ub8e8\uba70 \ub9c8\uc8fc\ud55c \ubb38\uc81c\uac00 \ub2e4\ub978 \uc0dd\ud65c\uc758 \ud544\uc694\uc640 \uc5f0\uacb0\ub418\uc5c8\ub2e4. \ud55c \ubd84\uc57c\uc5d0\uc11c \uc0dd\uae34 \ud574\ubc95\uc774 \uc804\ud600 \ub2e4\ub978 \uc7a5\uba74\uc5d0\uc11c\ub3c4 \uc4f8\ubaa8\ub97c \uc5bb\uc740 \uac83\uc774\ub2e4. \ubcf4\uc628\ubcd1 \uc548\ucabd\uc758 \ubc18\uc9dd\uc774\ub294 \ud45c\uba74\ub3c4 \uac19\uc740 \ub9e5\ub77d\uc5d0\uc11c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc9c4\uacf5\uc774 \uc904\uc774\ub294 \uacbd\ub85c\uc640 \ubcf5\uc0ac\uc5d0 \ub300\uc751\ud558\ub294 \ud45c\uba74\uc758 \uc5ed\ud560\uc740 \uc11c\ub85c \ub2e4\ub974\ub2e4. \ubaa9\uc744 \uac00\ub298\uac8c \ub9cc\ub4e4\uace0 \uc785\uad6c\ub97c \ub9c9\ub294 \uad6c\uc870\uae4c\uc9c0 \ub354\ud574\uc838\uc57c \ud55c\ub2e4. \ud558\ub098\uc758 \ube44\ubc00 \uc7ac\ub8cc\ubcf4\ub2e4 \uc5ec\ub7ec \uc5f4\uc804\ub2ec \uacbd\ub85c\ub97c \ub098\ub204\uc5b4 \ub2e4\ub8ec \uc124\uacc4\ub77c\uace0 \ubcf4\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \ub2e4\uc74c\uc5d0 \ubcd1\uc744 \uc5f4\uc5b4 \uc544\uc9c1 \ub530\ub73b\ud55c \ucc28\ub97c \ub9c8\uc2e4 \ub54c\uc5d0\ub294 \uc5f4\uc744 \ub123\uc5b4 \uc8fc\ub294 \uc7a5\uce58\uac00 \uc544\ub2c8\ub77c \uc5f4\uc774 \ub4dc\ub098\ub4dc\ub294 \uae38\uc744 \uc904\uc778 \uad6c\uc870\ub97c \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc544\uc8fc \ucc28\uac00\uc6b4 \uc2e4\ud5d8\uacfc \uc77c\uc0c1\uc758 \uc74c\ub8cc \uc0ac\uc774\uc5d0\ub294 \uac19\uc740 \ubb3c\ub9ac\uc801 \uc9c8\ubb38\uc774 \uc788\ub2e4. \ubb34\uc5c7\uc744 \ub354\ud560\uc9c0\uac00 \uc544\ub2c8\ub77c \ubb34\uc5c7\uc758 \uc774\ub3d9\uc744 \ub2a6\ucd9c\uc9c0 \uc0dd\uac01\ud55c \uc5ed\uc0ac\uac00 \uadf8 \uc548\uc5d0 \ub0a8\uc544 \uc788\ub2e4."}, {"id": "embroidered-spoon-pouch", "title": "\uc218\uc800\ub97c \ub123\ub294 \uc8fc\uba38\ub2c8\uc5d0 \ubc14\ub78c\uc744 \uc218\ub193\uc558\ub2e4", "summary": "\ubd89\uc740 \uc218\uc800\uc9d1\uc758 \uadf8\ub9bc\uacfc \uae00\uc528\ub97c \ub530\ub77c\uac00\uba70 \uc0dd\ud65c \uc18d \uc18c\ub9dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\uc2dd\ud0c1\uacfc \uc2dd\ud488 \ubcf4\uc874", "categories": ["everyday-inventions"], "url": "stories/embroidered-spoon-pouch/index.html", "image": "../media/embroidered-spoon-pouch.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc790\uc218\uc218\uc800\uc9d1 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc218\uc800\ub97c \ub123\ub294 \uc8fc\uba38\ub2c8\uc5d0 \ubc14\ub78c\uc744 \uc218\ub193\uc558\ub2e4 \ubc25\uc0c1 \uacc1\uc758 \uc791\uc740 \ubb3c\uac74\uc5d0 \ub2f4\uae34 \uae34 \ucd95\uc6d0 \ubd89\uc740 \uc218\uc800\uc9d1\uc758 \uadf8\ub9bc\uacfc \uae00\uc528\ub97c \ub530\ub77c\uac00\uba70 \uc0dd\ud65c \uc18d \uc18c\ub9dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc2dd\ud0c1\uacfc \uc2dd\ud488 \ubcf4\uc874 \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \uc0ac\uc9c4\uc744 \uc5bc\ud54f \ubcf4\uba74 \uae38\ucb49\ud55c \uc7a5\uc2dd\ud488 \uac19\ub2e4. \ubd89\uc740 \ubc14\ud0d5\uc5d0 \uaf43\uc774 \ud53c\uace0, \uc0c8\uac00 \uc11c \uc788\uace0, \uc5ec\ub7ec \uc0c9\uc758 \uc220\uc774 \uc544\ub798\ub85c \ub298\uc5b4\uc9c4\ub2e4. \uc774\ub984\uc744 \ubcf4\uace0 \ub098\uc11c\uc57c \uace0\uac1c\ub97c \ub044\ub355\uc778\ub2e4. \uc790\uc218\uc218\uc800\uc9d1\uc774\ub2e4. \uc21f\uac00\ub77d\uacfc \uc813\uac00\ub77d\uc744 \ub2f4\ub294 \ubb3c\uac74\uc778\ub370 \uc7a5\uc2dd\uc740 \uaf64 \ud48d\uc131\ud558\ub2e4. \ubb34\uc5c7\uc744 \ub2f4\ub294 \uc8fc\uba38\ub2c8\uc778\uc9c0\ub9cc \uc54c\uba74 \uc9c0\ub098\uce58\uae30 \uc27d\uc9c0\ub9cc, \ubb34\uc5c7\uc744 \uc218\ub193\uc558\ub294\uc9c0\uae4c\uc9c0 \ubcf4\uba74 \ub610 \ud558\ub098\uc758 \uc774\uc57c\uae30\uac00 \uc5f4\ub9b0\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc740 \uc55e\uba74 \uc544\ub798\ucabd\uc5d0 \ubc14\uc704\uc640 \uc601\uc9c0, \ud30c\ub3c4\uac00 \uc788\uace0 \uac00\uc6b4\ub370\uc5d0 \uc18c\ub098\ubb34\uc640 \ubaa8\ub780, \ud559 \ub450 \ub9c8\ub9ac \ub4f1\uc774 \uc218\ub193\uc600\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc5ec\ub7ec \uc0c9\uc758 \uc2e4\ub85c \uadf8\ub9b0 \ud48d\uacbd\uc774\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc774 \ubb38\uc591\ub4e4\uc774 \uc624\ub798 \uc0b4\uace0 \ubcf5\uc744 \ub204\ub9ac\uba70 \ud3c9\uc548\ud558\uae30\ub97c \ubc14\ub77c\ub294 \ub9c8\uc74c\uc744 \ud45c\ud604\ud55c\ub2e4\uace0 \ud480\uc774\ud55c\ub2e4. \ubaa8\ub974\ub294 \ubb38\uc591\uc758 \uc774\ub984\uc744 \uc804\ubd80 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uc88b\ub2e4. \uc2dd\uc0ac \ub3c4\uad6c\ub97c \ub123\ub294 \uc8fc\uba38\ub2c8\uac00 \uc88b\uc740 \uc0b6\uc5d0 \ub300\ud55c \ubc14\ub78c\uae4c\uc9c0 \ud488\uace0 \uc788\ub2e4\ub294 \uc810\uc774 \uc7ac\ubbf8\uc788\ub2e4. \uc774 \uc218\uc800\uc9d1\uc740 \uc55e\uba74\ub9cc \ubcf4\uace0 \ub05d\ub0bc \ubb3c\uac74\uc774 \uc544\ub2c8\ub2e4. \ub4b7\uba74\uc5d0\ub294 \uc911\uc559\uc120\uc744 \uc0ac\uc774\uc5d0 \ub450\uace0 \uae38\ud55c \ub73b\uc758 \uae00\uadc0\uac00 \uc218\ub193\uc5ec \uc788\ub2e4. \uc624\ub798 \uc0b4\uace0 \ud3c9\uc548\ud558\uae30\ub97c \ubc14\ub77c\ub294 \ud45c\ud604\uacfc \uc5ec\uc720\uc640 \ubd80\uadc0\ub97c \ubc14\ub77c\ub294 \ud45c\ud604\uc774\ub2e4. \ub208\uc73c\ub85c \ubcf4\ub294 \uadf8\ub9bc\uacfc \uc77d\ub294 \uae00\uc774 \ud55c \uc8fc\uba38\ub2c8\uc5d0 \ud568\uaed8 \ub193\uc600\ub2e4. \uc55e\uc758 \ud48d\uacbd\uc744 \ub4a4\uc758 \ubb38\uc7a5\uc774 \ub2e4\uc2dc \ud480\uc5b4 \uc8fc\ub294 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uc624\ub298\ub0a0 \uc120\ubb3c\uc5d0 \uc9e7\uc740 \ucd95\ud558 \uce74\ub4dc\ub97c \ub367\ubd99\uc774\ub294 \uc77c\uc744 \ube44\uad50\ud574 \ubcfc \uc218\ub3c4 \uc788\uaca0\ub2e4. \ubb3c\ub860 \uc774 \ubb3c\uac74\uc774 \uc2e4\uc81c \uc5b4\ub5a4 \uc120\ubb3c \uc790\ub9ac\uc5d0\uc11c \uc4f0\uc600\ub294\uc9c0\ub294 \ud655\uc778\ub41c \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \uc218\uc800\ub97c \ub123\ub294 \uc8fc\uba38\ub2c8\ub294 \uc548\uc5d0 \ub4e4\uc5b4\uac08 \uae38\uace0 \uac00\ub294 \ubb3c\uac74\uc744 \uc608\uc0c1\ud55c\ub2e4. \uc7a5\uc2dd\uc758 \ud48d\uacbd\uc744 \ubcf4\uae30 \uc804\uc5d0 \ubb3c\uac74\uc758 \uc804\uccb4 \ube44\ub840\uc640 \uc5ec\ub2eb\ub294 \uc790\ub9ac\ub97c \uc0b4\ud3b4\ubcf4\uba74 \uc4f0\uc784\uacfc \uc5f0\uacb0\ub41c\ub2e4. \ub2e4\ub9cc \uc774 \uc18c\uc7a5\ud488\uc5d0 \uc5b4\ub5a4 \uc218\uc800 \ud55c \ubc8c\uc774 \uc2e4\uc81c \ub4e4\uc5b4 \uc788\uc5c8\ub294\uc9c0\ub098 \uc5b4\ub514\ub85c \ub4e4\uace0 \uac14\ub294\uc9c0\ub294 \ud655\uc778\ub41c \uc124\uba85\uc774 \ud544\uc694\ud558\ub2e4. \ubcf4\uad00 \uae30\ub2a5\uacfc \uad6c\uccb4\uc801\uc778 \uc0ac\uc6a9 \uc7a5\uba74\uc740 \uad6c\ubd84\ud560 \uc218 \uc788\ub2e4. \uc624\ub298\uc758 \uc548\uacbd\uc9d1\uc774\ub098 \ud544\ud1b5\uc744 \ub5a0\uc62c\ub9ac\uba74 \ub3c4\uad6c\uc5d0 \ub9de\ucd98 \uc218\ub0a9\uc744 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uadf8\uac83\ub4e4\uacfc \uac19\uc740 \uc0dd\ud65c \uc81c\ub3c4\uc600\ub2e4\uace0 \uacb0\ub860\ub0bc \ud544\uc694\ub294 \uc5c6\ub2e4. \ubb3c\uac74\uc744 \ub123\uace0 \uaebc\ub0b4\ub294 \uc790\ub9ac\ub97c \ub9c8\ub828\ud588\ub2e4\ub294 \uacf5\ud1b5\uc810\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc774 \uc720\ubb3c\uc758 \ubaa8\uc591\uacfc \uc7a5\uc2dd\uc744 \ub530\ub85c \ubcf4\ub294 \uac83\uc774\ub2e4. \uce5c\uc219\ud55c \ube44\uc720\ub294 \ub0af\uc120 \ubb3c\uac74\uc744 \uc54c\uc544\ubcf4\ub294 \uc785\uad6c\uc774\uc9c0 \ubaa8\ub4e0 \ucc28\uc774\ub97c \uc9c0\uc6b0\ub294 \ub2f5\uc740 \uc544\ub2c8\ub2e4. \ubc14\uc704\uc640 \ud30c\ub3c4\ub294 \uc544\ub798\ucabd\uc744 \uc774\ub8e8\uace0 \uc18c\ub098\ubb34\uc640 \uaf43, \ud559\uc740 \uadf8 \uc704\uc5d0 \uad00\uacc4\ub97c \ub9cc\ub4e0\ub2e4. \ubc15\ubb3c\uad00\uc758 \ubb34\ub2ac \uc124\uba85\uc744 \ub530\ub77c\uac00\uba74 \ud55c\ub208\uc5d0 \ud654\ub824\ud558\ub2e4\ub294 \uc778\uc0c1\uc5d0\uc11c \uc5ec\ub7ec \uc694\uc18c\ub85c \uc7a5\uba74\uc774 \ub098\ub25c\ub2e4. \ubb34\uc5c7\uc774 \uc5b4\ub514\uc5d0 \ub193\uc600\ub294\uc9c0 \uc0b4\ud53c\ub294 \uc77c\uc740 \ub3d9\ubb3c\uacfc \uc2dd\ubb3c \uc774\ub984\uc744 \ub9ce\uc774 \uc678\uc6b0\ub294 \uac83\ubcf4\ub2e4 \uadf8\ub9bc\uc758 \uad6c\uc131\uc5d0 \uac00\uae4c\uc774 \uac00\uac8c \ud55c\ub2e4. \uc2e4\ub85c \ub9cc\ub4dc\ub294 \ud48d\uacbd\uc740 \uc885\uc774\uc5d0 \uadf8\ub9b0 \uadf8\ub9bc\uacfc \ub2e4\ub978 \ud45c\uba74\uc744 \uac00\uc9c4\ub2e4. \uc0c9\uc2e4\uc774 \ub098\ub780\ud788 \ub193\uc774\uace0 \ubc29\ud5a5\uc5d0 \ub530\ub77c \uacb0\uc774 \ubcf4\uc778\ub2e4. \uc2e4\uc81c \uc0ac\uc9c4\uc5d0\uc11c \uc138\ubd80\uac00 \ucda9\ubd84\ud788 \ub4dc\ub7ec\ub098\uc9c0 \uc54a\uc73c\uba74 \ud574\uc124\uc744 \uae30\uc900\uc73c\ub85c \ud070 \uad6c\uc131\uc744 \ud655\uc778\ud558\uba74 \ub41c\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294 \ubaa8\ub4e0 \ubc14\ub298\ub540\uc744 \uc0c1\uc0c1\uc73c\ub85c \uc77d\uc5b4\ub0bc \ud544\uc694\ub294 \uc5c6\ub2e4. \uc54c\ub824\uc9c4 \ubb34\ub2ac\uc640 \uc2e4\uc81c \ubcf4\uc774\ub294 \ud615\ud0dc\ub97c \uc624\uac00\ub294 \uac10\uc0c1\uc774 \uac00\ub2a5\ud558\ub2e4. \uc55e\uba74\uc740 \uae38\uc0c1 \ubb34\ub2ac\ub97c, \ub4b7\uba74\uc740 \uc88b\uc740 \uc0b6\uc744 \ubc14\ub77c\ub294 \uae00\uc744 \ub2f4\ub294\ub2e4. \uadf8\ub9bc\uacfc \uae00\uc774 \ubc18\ub4dc\uc2dc \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc815\ubcf4\ub97c \uc804\ud558\ub294 \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc, \uc774 \ubb3c\uac74\uc5d0\uc11c\ub294 \uc11c\ub85c \ub2ee\uc740 \ubc14\ub78c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc77d\uc744 \uc218 \uc788\ub294 \uc0ac\ub78c\uacfc \uba3c\uc800 \ud615\uc0c1\uc744 \ubcf4\ub294 \uc0ac\ub78c\uc740 \ub2e4\ub978 \uc785\uad6c\ub85c \ub4e4\uc5b4\uc640 \ube44\uc2b7\ud55c \ub73b\uc744 \ub9cc\ub0a0 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubb38\uc591 \ud558\ub098\ub9c8\ub2e4 \ub531 \ud558\ub098\uc758 \ub73b\ub9cc \uc601\uc6d0\ud788 \ubd99\ub294\ub2e4\uace0 \uc77c\ubc18\ud654\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubc15\ubb3c\uad00\uc774 \uc774 \uc18c\uc7a5\ud488\uc758 \uad6c\uc131\uc744 \uc5b4\ub5bb\uac8c \ud480\uc774\ud558\ub294\uc9c0 \ub530\ub77c\uac04\ub2e4. \uac1c\ubcc4 \ubb3c\uac74\uc758 \uc0ac\uc6a9\uc790\ub97c \ubaa8\ub97c \ub54c\uc5d0\ub3c4 \ud45c\ud604\ub41c \ubc14\ub78c\uc744 \uc77d\uc744 \uc218\ub294 \uc788\ub2e4. \ub204\uac00 \ub204\uad6c\uc5d0\uac8c \uc120\ubb3c\ud588\ub294\uc9c0 \ud655\uc778\ub418\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc810\uacfc \uc88b\uc740 \ub73b\uc744 \ub2f4\uc558\ub2e4\ub294 \uc124\uba85\uc744 \ud568\uaed8 \ub0a8\uae30\ub294 \uac83\uc774\ub2e4. \ubc15\ubb3c\uad00\uc740 \ub69c\uaed1\uc758 \ub9e4\ud654\uc640 \ub048, \uc220 \uc7a5\uc2dd\ub3c4 \uc18c\uac1c\ud55c\ub2e4. \uc55e\ub4b7\uba74\uc758 \uc911\uc2ec \uc7a5\uba74\uc744 \ubcf8 \ub4a4 \ub05d\ubd80\ubd84\uc73c\ub85c \ub208\uc744 \uc62e\uaca8 \ubcf4\uba74 \ubb3c\uac74\uc744 \uc5ec\ub2eb\uace0 \ubb36\ub294 \uad6c\uc870\uc5d0 \uc7a5\uc2dd\uc774 \uc774\uc5b4\uc9d0\uc744 \uc54c \uc218 \uc788\ub2e4. \uae30\ub2a5\uc744 \uc704\ud55c \uc791\uc740 \ubd80\ubd84\ub3c4 \uafb8\ubc08\uc758 \ubc94\uc704 \ubc16\uc5d0 \uc788\uc9c0 \uc54a\uc558\ub2e4. \uc804\uccb4\ub97c \ub9c8\ubb34\ub9ac\ud558\ub294 \uc190\uae38\uc774 \uc5ec\ub7ec \uc790\ub9ac\uc5d0 \ub193\uc5ec \uc788\ub2e4. \ubb3c\uac74\uc758 \uc77c\ubd80\ub9cc \uc804\uc2dc\uc7a5\uc5d0 \ubcf4\uc774\uac70\ub098 \uc0ac\uc9c4 \ud55c\ucabd\uc774 \uac00\ub824\uc838 \uc788\uc5b4\ub3c4 \ud574\uc124\uc774 \ub2e4\ub978 \uba74\uc744 \ucc3e\uc544\ubcf4\uac8c \ub3c4\uc640\uc900\ub2e4. \ub2e4\ub9cc \uad00\ub78c\uc790\uac00 \uc9c1\uc811 \ub4a4\uc9d1\uc5b4 \ud655\uc778\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc790\ub8cc\ub97c \ud568\uaed8 \uc77d\uc73c\uba70 \uc74c\uc2dd \ub3c4\uad6c\uc758 \uc9d1\uc774\ub77c\ub294 \uc4f0\uc784\uacfc \uc0b6\uc744 \ubc14\ub77c\ub294 \ud45c\ud604\uc744 \ub098\ub780\ud788 \ubcfc \uc218 \uc788\ub2e4. \uc791\uc740 \uc8fc\uba38\ub2c8\uac00 \uc0dd\ud65c\uc758 \uc900\ube44\uc640 \uacf5\uc608, \uc18c\ub9dd\uc744 \ud568\uaed8 \ud488\uc5c8\ub2e4\ub294 \uc810\uc774 \ub0a8\ub294\ub2e4. \ub69c\uaed1\uc758 \uc55e\ub4b7\uba74\uc5d0\ub3c4 \ub9e4\ud654\uac00 \ub450 \uc1a1\uc774\uc529 \uc218\ub193\uc600\ub2e4. \uaf43\uc758 \uc528\ubc29\uc5d0\ub294 \uad6c\uba4d\uc744 \ub0b4\uace0 \ub048\uc744 \uaff0\uc5c8\uc73c\uba70 \uadf8 \uc544\ub798\ub85c \uc5ec\ub7ec \uc0c9\uc758 \uc220\uc744 \ub2ec\uc558\ub2e4. \uc8fc\uba38\ub2c8\ub97c \uafb8\ubbf8\ub294 \uc77c\uc774 \ubab8\uccb4\uc5d0\uc11c \ub05d\ub098\uc9c0 \uc54a\uc740 \uc148\uc774\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \ud55c\uaebc\ubc88\uc5d0 \ubaa8\ub4e0 \ubb34\ub2ac\ub97c \ucc3e\uc73c\ub824 \ud558\uba74 \ub208\uc774 \ubc14\ube60\uc9c4\ub2e4. \uba3c\uc800 \ud559\uc744 \ubcf4\uace0 \ub2e4\uc74c\uc5d0 \uaf43\uc744 \ubcf4\ub294 \uc815\ub3c4\uba74 \ucda9\ubd84\ud558\ub2e4. \ub9e4\uc77c\uc758 \uc2dd\uc0ac\uc640 \uba40\uc9c0 \uc54a\uc740 \ubb3c\uac74\uc5d0 \uc774\ub807\uac8c \ub9ce\uc740 \uc88b\uc740 \ub73b\uc744 \ubaa8\uc544 \ub450\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c\ub3c4, \ubd89\uc740 \uc218\uc800\uc9d1\uc740 \uc791\uc740 \uadf8\ub9bc\ucc45\ucc98\ub7fc \uc77d\ud78c\ub2e4."}, {"id": "harp-colored-strings", "title": "\ud558\ud504 \uc904\uc5d0\ub294 \uc65c \ube68\uac04\uc0c9\uc774 \uc11e\uc5ec \uc788\uc744\uae4c", "summary": "\uba40\ub9ac\uc11c\ub294 \ubaa8\ub450 \ube44\uc2b7\ud574 \ubcf4\uc774\ub294 \ud558\ud504\uc758 \uc904. \uac00\uae4c\uc774 \ubcf4\uba74 \uc5f0\uc8fc\uc790\ub97c \uc704\ud55c \uc791\uc740 \uc0c9\uae54 \ud45c\uc9c0\uac00 \uc788\uc2b5\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\ub180\uc774\uc640 \ucde8\ubbf8", "categories": ["everyday-inventions"], "url": "stories/harp-colored-strings/index.html", "image": "../media/harp-colored-strings.jpg", "alt": "\ubc1d\uc740 \uc904 \uc0ac\uc774\uc5d0 \ubd89\uace0 \uc5b4\ub450\uc6b4 \uc904\uc774 \uc11e\uc778 \ud558\ud504 \uc77c\ubd80\ub97c \uadf8\ub9b0 AI \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ud558\ud504 \uc904\uc5d0\ub294 \uc65c \ube68\uac04\uc0c9\uc774 \uc11e\uc5ec \uc788\uc744\uae4c \uc218\ub9ce\uc740 \ud604 \uc0ac\uc774\uc5d0\uc11c \uae38\uc744 \ucc3e\ub294 \uc0c9\uae54 \uba40\ub9ac\uc11c\ub294 \ubaa8\ub450 \ube44\uc2b7\ud574 \ubcf4\uc774\ub294 \ud558\ud504\uc758 \uc904. \uac00\uae4c\uc774 \ubcf4\uba74 \uc5f0\uc8fc\uc790\ub97c \uc704\ud55c \uc791\uc740 \uc0c9\uae54 \ud45c\uc9c0\uac00 \uc788\uc2b5\ub2c8\ub2e4. \ub180\uc774\uc640 \ucde8\ubbf8 \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \ud558\ud504\ub97c \ubcf4\uba74 \uba3c\uc800 \uc904\uc758 \uc218\uc5d0 \uc555\ub3c4\ub41c\ub2e4. \uae38\uace0 \uc9e7\uc740 \uc904\uc774 \ub098\ub780\ud788 \uc11c \uc788\uc5b4\uc11c, \uc5b4\ub514\ub97c \uc9da\uc5b4\uc57c \uc6d0\ud558\ub294 \uc18c\ub9ac\uac00 \ub098\ub294\uc9c0 \uc7a0\uae50 \ub9c9\ub9c9\ud574\uc9c4\ub2e4. \uadf8\ub7f0\ub370 \uac00\uae4c\uc774 \ubcf4\uba74 \ubaa8\ub4e0 \uc904\uc774 \uac19\uc740 \uc0c9\uc740 \uc544\ub2c8\ub2e4. \ube68\uac04 \uc904\uc774 \uc11e\uc5ec \uc788\uace0 \uc5b4\ub450\uc6b4 \uc904\ub3c4 \ubcf4\uc778\ub2e4. \uc7a5\uc2dd\uc73c\ub85c \uc0c9\uc744 \ub123\uc740 \uac83 \uac19\uc9c0\ub9cc, \uc5f0\uc8fc\uc790\uac00 \uc904\uc744 \ucc3e\ub294 \ub370 \ub3c4\uc6c0\uc744 \uc8fc\ub294 \ud45c\uc2dc\ub2e4. \ud544\ud558\ubaa8\ub2c8\uc544 \uc624\ucf00\uc2a4\ud2b8\ub77c\uc758 \ud558\ud504 \uc548\ub0b4\ub294 \ub3c4\uc5d0 \ud574\ub2f9\ud558\ub294 C \uc904\uc744 \ube68\uac04\uc0c9, \ud30c\uc5d0 \ud574\ub2f9\ud558\ub294 F \uc904\uc744 \uac80\uc740\uc0c9\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \ube7d\ube7d\ud55c \uc904 \uc0ac\uc774\uc5d0 \uc54c\uc544\ubcf4\uae30 \uc26c\uc6b4 \uae30\uc900\uc810\uc744 \ub454 \uac83\uc774\ub2e4. \uc774\uc57c\uae30\uc758 \ub300\uc0c1\uc740 \uc624\ucf00\uc2a4\ud2b8\ub77c\uc5d0\uc11c \uc0ac\uc6a9\ud558\ub294 \ud604\ub300\uc801\uc778 \ud398\ub2ec \ud558\ud504\ub2e4. \uc548\ub0b4\uc5d0 \ub530\ub974\uba74 \uc774 \ud558\ud504\uc5d0\ub294 47\uac1c\uc758 \uc904\uc774 \uc788\ub2e4. \uc904\ub9c8\ub2e4 \uc190\uae00\uc528 \uc774\ub984\ud45c\ub97c \ub2ec\uae30\ubcf4\ub2e4 \uc0c9\uc73c\ub85c \uc790\ub9ac\ub97c \uad6c\ubd84\ud558\uba74 \uc5f0\uc8fc \uc911\uc5d0\ub3c4 \ub208\uc5d0 \ube68\ub9ac \ub4e4\uc5b4\uc628\ub2e4. \uc6b0\ub9ac\ub3c4 \ube44\uc2b7\ud55c \ud45c\uc2dc\ub97c \uc4f4\ub2e4. \uc790\uc8fc \ucc3e\ub294 \ucc45\uc5d0 \uc0c9\uae54 \ucabd\uc9c0\ub97c \ubd99\uc774\uac70\ub098, \ube44\uc2b7\ud55c \uc5f4\uc1e0\ub97c \uad6c\ubd84\ud558\ub824 \uace0\ub9ac\ub97c \ub2ec \ub54c\uac00 \uc788\ub2e4. \ud558\ud504\uc758 \uc904\uc5d0\uc11c\ub294 \uc0c9\uc774 \uadf8 \uc791\uc740 \uae38\uc7a1\uc774 \uc5ed\ud560\uc744 \ud55c\ub2e4. \ud558\ud504\ub97c \ubcf4\ub294 \uc2dc\uc120\uc740 \ubcf4\ud1b5 \uc190\uc5d0 \uba38\ubb38\ub2e4. \ud558\uc9c0\ub9cc \uc544\ub798\uc5d0\ub294 \uc77c\uacf1 \uac1c\uc758 \ud398\ub2ec\ub3c4 \uc788\ub2e4. \uc774 \ud398\ub2ec\uc740 \uac19\uc740 \uc774\ub984\uc758 \uc74c\uc5d0 \ud574\ub2f9\ud558\ub294 \uc904\ub4e4\uc758 \uc74c\ub192\uc774\ub97c \ubc14\uafb8\ub294 \ub370 \uc4f0\uc778\ub2e4. \ud544\ud558\ubaa8\ub2c8\uc544\ub294 C \ud398\ub2ec\uc744 \ubc14\uafb8\uba74 \uc5ec\ub7ec \ub192\uc774\uc5d0 \uc788\ub294 C \uc904\ub4e4\uc774 \ud568\uaed8 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc904 \ud558\ub098\ub9c8\ub2e4 \ubc1c\ud310 \ud558\ub098\uac00 \uc788\ub294 \uad6c\uc870\ub294 \uc544\ub2cc \uac83\uc774\ub2e4. \uadf8\ub798\uc11c \uc5f0\uc8fc\uc790\ub294 \uc190\uc73c\ub85c \uc904\uc744 \ub72f\ub294 \ub3d9\uc548\uc5d0\ub3c4 \ubc1c\ubc11\uc758 \uc0c1\ud0dc\ub97c \uc0b4\ud540\ub2e4. \uc26c\ub294 \uad6c\uac04\uc774 \ubcf4\uc778\ub2e4\uace0 \uc644\uc804\ud788 \ud560 \uc77c\uc774 \uc5c6\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub2e4\uc74c\uc5d0 \ud544\uc694\ud55c \uc18c\ub9ac\ub97c \uc704\ud574 \ud398\ub2ec\uc744 \ubc14\uafb8\ub294 \uc2dc\uac04\uc77c \uc218\ub3c4 \uc788\ub2e4. 47\uac1c\uc758 \uc904 \uc55e\uc5d0\uc11c \uc5f0\uc8fc\uc790\ub294 \uc9c0\uae08 \ud544\uc694\ud55c \uc74c\uc758 \uc790\ub9ac\ub97c \ube60\ub974\uac8c \uc54c\uc544\ubcf4\uc544\uc57c \ud55c\ub2e4. \ubaa8\ub4e0 \uc904\uc774 \ub611\uac19\uc774 \ubcf4\uc778\ub2e4\uba74 \uc190\uc758 \uc774\ub3d9\uc744 \ud655\uc778\ud558\ub294 \uc77c\ub3c4 \uc5b4\ub824\uc6cc\uc9c8 \uc218 \uc788\ub2e4. \ube68\uac04 C\uc640 \uac80\uc740 F\ub294 \uc5ec\ub7ec \ub192\uc774\uc5d0 \uac78\uccd0 \ubc18\ubcf5\ub418\ub294 \uae30\uc900\uc810\uc774\ub2e4. \uc0c9\uc774 \uc18c\ub9ac\ub97c \uc9c1\uc811 \ub9cc\ub4e4\uc5b4 \ub0b4\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uc5f0\uc8fc\ud560 \uc704\uce58\ub97c \ucc3e\ub294 \uc0ac\ub78c\uc744 \ub3d5\ub294 \ud45c\uc2dc\ub77c\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uc545\ubcf4\uc758 \uc74c\uacfc \uc2e4\uc81c \uc904 \uc0ac\uc774\ub97c \uc5f0\uacb0\ud558\ub294 \uc77c\uc5d0\ub294 \ub208\uacfc \uc190\uc774 \ud568\uaed8 \uc4f0\uc778\ub2e4. \uc0c9\uc744 \uc544\ub294 \uad00\ub78c\uc790\ub77c\uba74 \uc5f0\uc8fc\uc790\uc758 \uc190\uc774 \uc5b4\ub290 \uad6c\uc5ed\uc744 \uc624\uac00\ub294\uc9c0 \uc870\uae08 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \ubcfc \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \ud558\ud504\uac00 \uac19\uc740 \uc904 \uc218\uc640 \uc0c9\uc744 \uac00\uc9c4\ub2e4\uace0 \uc77c\ubc18\ud654\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc774 \uae00\uc5d0\uc11c \uc124\uba85\ud558\ub294 \ud604\ub300 \ud398\ub2ec \ud558\ud504\uc758 \uad6c\uc131\uc774\ub77c\ub294 \ubc94\uc704\ub97c \uae30\uc5b5\ud558\uba74 \ub41c\ub2e4. \ud53c\uc544\ub178\uc5d0\uc11c \uc11c\ub85c \ub2e4\ub978 \ub192\uc774\uc758 \ub3c4\uac00 \ubc18\ubcf5\ub418\ub4ef \ud558\ud504\uc5d0\ub3c4 \uac19\uc740 \uc774\ub984\uc744 \uac00\uc9c4 \uc5ec\ub7ec \uc904\uc774 \uc788\ub2e4. \uc548\ub0b4\ub294 C \ud398\ub2ec\uc744 \uc6c0\uc9c1\uc774\uba74 \uc5ec\ub7ec \ub192\uc774\uc758 C \uc904\uc5d0 \ud568\uaed8 \uc601\ud5a5\uc744 \uc900\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc904\uc758 \ucd1d\uac1c\uc218\uc640 \ud398\ub2ec\uc758 \uac1c\uc218\uac00 \uc77c\uce58\ud558\uc9c0 \uc54a\ub294 \uae4c\ub2ed\uc774\ub2e4. \ubc1c \ud558\ub098\uac00 \ubb3c\uac74 \ud558\ub098\ub9cc \ub9e1\ub294 \uad6c\uc870\uac00 \uc544\ub2c8\ub77c \uc74c\uc758 \uc774\ub984\uc744 \uae30\uc900\uc73c\ub85c \ubb36\uc778 \uc870\uc808\uc744 \ud558\ub294 \uc148\uc774\ub2e4. \uc774 \uad00\uacc4\ub97c \uc54c\uace0 \ubcf4\uba74 \ud558\ud504\ub97c \ub2e8\uc21c\ud788 \uc904\uc744 \ub9ce\uc774 \ub2e8 \uc545\uae30\ub85c \uae30\uc5b5\ud558\uae30 \uc5b4\ub835\ub2e4. \uc190\uc740 \uc5b4\ub5a4 \uc904\uc744 \uc5b8\uc81c \ub72f\uc744\uc9c0 \ub2e4\ub8e8\uace0 \ubc1c\uc740 \ud544\uc694\ud55c \uc74c\ub192\uc774\uc758 \uc0c1\ud0dc\ub97c \uc900\ube44\ud55c\ub2e4. \ubb3c\ub860 \uc2e4\uc81c \uc5f0\uc8fc\uc758 \ubaa8\ub4e0 \uc870\uc791\uc744 \ub450 \ubb38\uc7a5\uc73c\ub85c \uc694\uc57d\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \ub208\uc5d0 \ubcf4\uc774\ub294 \uc190\uc758 \ub3d9\uc791 \ub4a4\uc5d0 \ub2e4\ub978 \uc900\ube44\uac00 \uc788\ub2e4\ub294 \uc810\uc774 \uacf5\uc5f0\uc758 \ud48d\uacbd\uc744 \ubc14\uafd4 \uc900\ub2e4. \uc120\uc728\uc774 \uc7a0\uc2dc \ub04a\uaca8\ub3c4 \uc5f0\uc8fc\uc790\uac00 \ud398\ub2ec\uc744 \ubc14\uafb8\uac70\ub098 \uc190\uc744 \uc62e\uae30\ub294 \ubaa8\uc2b5\uc744 \ubcfc \uc218 \uc788\ub2e4. \uc74c\uc545\uc740 \uc9c0\uae08 \uc6b8\ub9ac\ub294 \uc18c\ub9ac\ubfd0 \uc544\ub2c8\ub77c \uace7 \uc6b8\ub9b4 \uc18c\ub9ac\uc758 \uc870\uac74\ub3c4 \ud544\uc694\ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \uad00\uac1d\uc5d0\uac8c \uc870\uc6a9\ud55c \uad6c\uac04\uc774 \uc5f0\uc8fc\uc790\uc5d0\uac8c\ub294 \ub2e4\uc74c \uc7a5\uba74\uc758 \uc900\ube44 \uc2dc\uac04\uc774 \ub420 \uc218 \uc788\ub2e4. \uc27c\uc744 \uc544\ubb34 \ud65c\ub3d9\ub3c4 \uc5c6\ub294 \ube48\uce78\uc73c\ub85c\ub9cc \ubcf4\uc9c0 \uc54a\uac8c \ub418\ub294 \ub300\ubaa9\uc774\ub2e4. \ud558\ud504\ub9cc\uc758 \ud2b9\ubcc4\ud55c \ub9c8\ubc95\uc774\ub77c\uae30\ubcf4\ub2e4 \ud569\uc8fc\uc5d0\uc11c \ub9cc\ub098\ub294 \uc900\ube44\uc758 \ud55c \uc0ac\ub840\ub2e4. \ud604\uc744 \uace0\ub974\uace0 \ubab8\uc758 \uc704\uce58\ub97c \uc7a1\ub294 \uc77c\uc774 \uad00\ub78c\uc790\uc5d0\uac8c \ubaa8\ub450 \ud06c\uac8c \ub4dc\ub7ec\ub098\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub798\uc11c \uacf5\uc5f0\uc744 \ubcfc \ub54c \ud55c \ubc88\uc740 \uc120\uc728\uc744 \ub4e3\uace0 \ub2e4\ub978 \ud55c \ubc88\uc740 \uc900\ube44 \ub3d9\uc791\uc744 \ub530\ub77c\uac00\ub3c4 \uc88b\ub2e4. \uc815\ud655\ud788 \uc5b4\ub5a4 \ud398\ub2ec\uc744 \ubc1f\ub294\uc9c0 \uc54c\uc544\ub9de\ud790 \ud544\uc694 \uc5c6\uc774\ub3c4 \uc74c\uc545\uc744 \ub9cc\ub4dc\ub294 \uc6c0\uc9c1\uc784\uc774 \ubcf4\uc778\ub2e4. \uc904\uc758 \uc0c9\uc744 \uc54c\uc558\ub2e4\uace0 \uace7\ubc14\ub85c \uc74c\uc744 \uadc0\ub85c \uad6c\ubd84\ud558\ub294 \ub2a5\ub825\uc774 \uc0dd\uae30\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub798\ub3c4 \ubcf5\uc7a1\ud574 \ubcf4\uc774\ub358 \uc545\uae30\uc5d0 \ub208\uc774 \uba38\ubb3c \ud45c\uc9c0\uac00 \uc0dd\uae34\ub2e4. \uc74c\uc545\uc744 \ubc30\uc6b0\ub294 \uc785\uad6c\uac00 \uc545\ubcf4\uc640 \uc74c\uc774\ub984\uc758 \uc554\uae30 \ud558\ub098\ub85c\ub9cc \uc815\ud574\uc838 \uc788\uc9c0 \uc54a\ub2e4\ub294 \ub73b\uc774\ub2e4. \uad6c\uc870\uc758 \uc791\uc740 \ub2e8\uc11c\uac00 \ub0af\uc120 \uc545\uae30\ub97c \ub2e4\uc2dc \ubcf4\uace0 \uc2f6\uac8c \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \ub2e4\uc74c \ud569\uc8fc \uc601\uc0c1\uc5d0\uc11c \ud558\ud504\ub97c \ucc3e\uc558\ub2e4\uba74 \uba3c\uc800 \uc0c9\uc774 \ubc18\ubcf5\ub418\ub294 \uad6c\uac04\uc744 \ubcf4\uace0, \uc190\uacfc \ubc1c\uc758 \uc6c0\uc9c1\uc784\uc744 \ubc88\uac08\uc544 \uc0b4\ud3b4\ubcf4\uc790. \uc18c\ub9ac\uac00 \ubcf4\uc774\ub294 \uc790\ub9ac\uc640 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc870\uc808\uc774 \uc5b4\ub5bb\uac8c \ub098\ub258\ub294\uc9c0 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ube5b\ub098\ub294 \ub9ce\uc740 \uc904 \uac00\uc6b4\ub370 \ube68\uac04\uc0c9 \uba87 \uac00\ub2e5\uc774 \ub2e8\uc21c\ud55c \uc7a5\uc2dd\uc5d0\uc11c \uc5f0\uc8fc\ub97c \ub3d5\ub294 \uae38\uc7a1\uc774\ub85c \ubc14\ub00c\ub294 \uc21c\uac04\uc774\ub2e4. \ud558\ud504\uc758 \uace1\uc120\uacfc \uc904\uc740 \uba40\ub9ac\uc11c\ub3c4 \uc544\ub984\ub2f5\ub2e4. \uac00\uae4c\uc774\uc5d0\uc11c\ub294 \uadf8 \uc544\ub984\ub2e4\uc6b4 \ubaa8\uc2b5 \uc548\uc5d0 \uc5f0\uc8fc\ub97c \ub3d5\ub294 \uc7a5\uce58\uac00 \ub4e4\uc5b4 \uc788\ub2e4\ub294 \uac83\uc774 \ubcf4\uc778\ub2e4. \uc0c9\uae54\uc740 \uc704\uce58\ub97c, \ud398\ub2ec\uc740 \uc74c\uc758 \ubcc0\ud654\ub97c \ub2e4\ub8ec\ub2e4. \ud544\ud558\ubaa8\ub2c8\uc544\ub294 \ud558\ud504 \uc5f0\uc8fc\uc790\ub4e4\uc774 \uacf5\uc5f0 \uc804\uc5d0 \uc5ec\ub7ec \uc904\uc744 \uc870\uc728\ud558\ub294 \ubaa8\uc2b5\ub3c4 \uc18c\uac1c\ud55c\ub2e4. \ubc18\uc9dd\uc774\ub294 \uc904\uc774 \ub9ce\uc774 \uc788\ub2e4\ub294 \uac83\uc740, \uadf8\ub9cc\ud07c \ubbf8\ub9ac \ud655\uc778\ud574\uc57c \ud560 \uc18c\ub9ac\ub3c4 \ub9ce\ub2e4\ub294 \ub73b\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \ud558\ud504\ub97c \ub9cc\ub098\uba74 \uc904\uc744 \ud558\ub098\uc529 \uc138\ub824\uace0 \uc560\uc4f0\uc9c0 \uc54a\uc544\ub3c4 \uc88b\ub2e4. \uba3c\uc800 \ube68\uac04 \uc904\uc744 \ucc3e\uc544\ubcf4\uc790. \uc544\ub984\ub2e4\uc6b4 \uc545\uae30 \uc548\uc5d0\uc11c \uc5f0\uc8fc\uc790\uac00 \uae38\uc744 \uc783\uc9c0 \uc54a\ub3c4\ub85d \ub9c8\ub828\ud55c \uc791\uc740 \ud45c\uc9c0\uac00 \ubcf4\uc77c \uac83\uc774\ub2e4."}, {"id": "henna-paste-and-stain", "title": "\ud53c\ubd80 \uc704\uc758 \ubb34\ub2ac\ub294 \uc53b\uc5b4 \ub0b8 \ub4a4\uc5d0\ub3c4 \ub0a8\ub294\ub2e4", "summary": "\ud53c\ubd80\uc5d0 \ubc14\ub978 \uc7ac\ub8cc\uc640 \uadf8 \uc7ac\ub8cc\uac00 \ub0a8\uae34 \ubb34\ub2ac\ub97c \ub098\ub204\uc5b4 \ubd05\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\uc637\uacfc \uc7ac\ub8cc", "categories": ["everyday-inventions"], "url": "stories/henna-paste-and-stain/index.html", "image": "../media/henna-paste-and-stain.jpg", "alt": "\ud55c \uc0ac\ub78c\uc774 \ub2e4\ub978 \uc0ac\ub78c\uc758 \ud314\uc5d0 \ud5e4\ub098 \ubb34\ub2ac\ub97c \ub354\ud558\ub294 \uc791\uc5c5\uc758 \uc2e4\uc81c \uc0ac\uc9c4.", "text": "\ud53c\ubd80 \uc704\uc758 \ubb34\ub2ac\ub294 \uc53b\uc5b4 \ub0b8 \ub4a4\uc5d0\ub3c4 \ub0a8\ub294\ub2e4 \ud5e4\ub098\uac00 \uadf8\ub824\uc9c0\ub294 \uc21c\uac04\uacfc \ub0a8\uaca8\uc9c0\ub294 \uc0c9 \ud53c\ubd80\uc5d0 \ubc14\ub978 \uc7ac\ub8cc\uc640 \uadf8 \uc7ac\ub8cc\uac00 \ub0a8\uae34 \ubb34\ub2ac\ub97c \ub098\ub204\uc5b4 \ubd05\ub2c8\ub2e4. \uc637\uacfc \uc7ac\ub8cc \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \uc0ac\uc9c4 \uc18d\uc5d0\uc11c\ub294 \ud55c \uc0ac\ub78c\uc774 \ub2e4\ub978 \uc0ac\ub78c\uc758 \ud314\uc5d0 \uc791\uc740 \uc120\uc744 \ub354\ud558\uace0 \uc788\ub2e4. \uc190\uacfc \ud314\uc5d0 \ubcf5\uc7a1\ud55c \ubb34\ub2ac\uac00 \uc774\uc5b4\uc9c4\ub2e4. \ud5e4\ub098\ub97c \ubc14\ub974\ub294 \uc7a5\uba74\uc774\ub2e4. \uc6b0\ub9ac\uac00 \uc644\uc131\ub41c \uc7a5\uc2dd\uc774\ub77c\uace0 \ubcf4\ub294 \ubaa8\uc2b5 \uc55e\uc5d0\ub294 \uc7ac\ub8cc\ub97c \uc5b9\ub294 \uc2dc\uac04\uc774 \uc788\ub2e4. OpenStax \uad50\uc7ac\ub294 \ud5e4\ub098 \uc78e\uc744 \ube7b\uace0 \uace0\ub974\uac8c \ub9cc\ub4e0 \uc7ac\ub8cc\ub97c \ud53c\ubd80\uc5d0 \ubb34\ub2ac\ub85c \ubc14\ub974\ub294 \uacfc\uc815\uc744 \uc124\uba85\ud55c\ub2e4. \uadf8 \uc7ac\ub8cc\ub97c \uac77\uc5b4 \ub0b8 \ub4a4\uc5d0\ub3c4 \ud53c\ubd80\uc5d0\ub294 \ubd89\uac70\ub098 \uc8fc\ud669\ube5b\uc758 \uc0c9\uc774 \ub0a8\ub294\ub2e4. \uadf8\ub798\uc11c \ud5e4\ub098\ub294 \ubc14\ub978 \uc21c\uac04\uc758 \ubaa8\uc2b5\uacfc \uc7ac\ub8cc\ub97c \uc81c\uac70\ud55c \ub4a4\uc758 \ubaa8\uc2b5\uc774 \ub2e4\ub97c \uc218 \uc788\ub2e4. \ud53c\ubd80 \uc704\uc5d0 \uc62c\ub77c\uc628 \ubd80\ubd84\ub9cc\uc774 \ubb34\ub2ac\uc758 \uc804\ubd80\ub294 \uc544\ub2c8\ub2e4. \uadf8 \uc544\ub798\uc5d0 \ub0a8\uc740 \uc0c9\ub3c4 \uc7a5\uc2dd\uc774 \ub41c\ub2e4. \uc0ac\uc9c4\uc744 \ubcfc \ub54c \uc9d9\uac8c \ubcf4\uc774\ub294 \uc120\uacfc \uadf8\ub9b0 \uc0ac\ub78c\uc758 \uc190\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubcf4\uc790. \uc774\ubbf8 \uc644\uc131\ub41c \uacb0\uacfc\ub9cc \ubcf4\ub294 \ub300\uc2e0 \uc120\uc744 \ub354\ud558\ub294 \uc791\uc5c5\uc744 \uc77d\uac8c \ub41c\ub2e4. \uc774 \uc774\ubbf8\uc9c0 \ud55c \uc7a5\uc774 \ubaa8\ub4e0 \ub2e8\uacc4\uc758 \uac19\uc740 \ud314\uc744 \uc5f0\uc18d \ucd2c\uc601\ud55c \uac83\uc774\ub77c\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uad50\uc7ac\ub294 \ud5e4\ub098\ub97c \uc778\ub3c4 \uc544\ub300\ub959\uacfc \ubd81\uc544\ud504\ub9ac\uce74 \ub4f1 \uc5ec\ub7ec \uc9c0\uc5ed\uc5d0\uc11c \uc0ac\uc6a9\ud558\ub294 \ubab8 \uafb8\ubc08\uc758 \uc608\ub85c \uc18c\uac1c\ud55c\ub2e4. \ud63c\ub840\ub098 \uc885\uad50\uc801 \uae30\ub150\uc77c \uac19\uc740 \ud2b9\ubcc4\ud55c \ub54c \uc190\uc774\ub098 \ubc1c\uc744 \uc7a5\uc2dd\ud558\uae30\ub3c4 \ud55c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc9c0\uc5ed\ub9c8\ub2e4 \ub611\uac19\uc740 \ubb34\ub2ac\uc5d0 \uac19\uc740 \ub73b\uc744 \ubd99\uc778\ub2e4\ub294 \ub9d0\uc740 \uc544\ub2c8\ub2e4. \uac19\uc740 \uc7ac\ub8cc\ub77c\ub3c4 \ub204\uac00 \uc5b8\uc81c \uc5b4\ub5a4 \uad00\uacc4 \uc18d\uc5d0\uc11c \uc0ac\uc6a9\ud558\ub294\uc9c0\uc5d0 \ub530\ub77c \uc77d\ub294 \ub9e5\ub77d\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ubb34\ub2ac\uc758 \uc774\ub984\uc744 \ud558\ub098\ub85c \ubb36\uc5b4 \ubc84\ub9ac\uae30\ubcf4\ub2e4 \uc0ac\uc6a9\ub418\ub294 \uc790\ub9ac\ub97c \ud568\uaed8 \ubcf4\uba74 \uc88b\ub2e4. \uad50\uc7ac\ub294 \ud5e4\ub098 \uc78e\uc744 \uac08\uace0 \uccb4\uc9c8\ud55c \uc7ac\ub8cc\ub97c \ud53c\ubd80\uc5d0 \uc0ac\uc6a9\ud55c \ub4a4 \uc81c\uac70\ud558\uba74 \uc0c9\uc774 \ub0a8\ub294\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub9cc\ub4dc\ub294 \uc7ac\ub8cc\uc640 \ucd5c\uc885\uc801\uc73c\ub85c \ubcf4\uc774\ub294 \uc0c9\uc774 \uac19\uc740 \uc0c1\ud0dc\ub294 \uc544\ub2c8\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \ub3c4\ud1b0\ud558\uac8c \uc62c\ub77c\uc628 \uc120\uc744 \ubcf4\uc558\ub2e4\uba74 \uc544\uc9c1 \ud45c\uba74\uc5d0 \uc7ac\ub8cc\uac00 \uc788\ub294 \uacfc\uc815\uc77c \uc218 \uc788\ub2e4. \uacb0\uacfc\ub9cc\uc774 \uc544\ub2c8\ub77c \ubcc0\ud654\ud558\ub294 \ub2e8\uacc4\ub97c \ub098\ub204\uc5b4 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc774 \ucc28\uc774\ub294 \uc5b4\ub5a4 \ud53c\ubd80 \uc7a5\uc2dd\uc778\uc9c0 \uc774\ud574\ud558\ub294 \ub370 \uc911\uc694\ud558\ub2e4. \ud558\uc9c0\ub9cc \uc2e4\uc81c \uc7ac\ub8cc\uc758 \ubc30\ud569\uc774\ub098 \ub3c4\ud3ec \uc2dc\uac04, \uac1c\uc778\uc758 \ubc18\uc751\uc744 \uc774 \uc0ac\uc9c4\ub9cc\uc73c\ub85c \uc54c \uc218\ub294 \uc5c6\ub2e4. \uc774 \uae00\uc740 \ub530\ub77c \ud558\ub294 \uc2dc\uc220 \uc548\ub0b4\uac00 \uc544\ub2c8\ub77c \uad50\uc7ac\uac00 \uc18c\uac1c\ud55c \uc7ac\ub8cc\uc640 \ud615\ud0dc\uc758 \uad00\uacc4\ub97c \uc77d\ub294 \uc774\uc57c\uae30\ub2e4. \ubb34\ub2ac\uac00 \ubcf4\uc774\ub294 \ubc29\uc2dd\uacfc \uadf8\uac83\uc744 \ub9cc\ub4dc\ub294 \uacfc\uc815\uc744 \uad6c\ubd84\ud558\ub294 \ub370 \ucd08\uc810\uc744 \ub9de\ucd98\ub2e4. \uc2e4\uc81c \uc0ac\uc9c4\uc5d0\ub294 \uc644\uc131\ub41c \ubb34\ub2ac\ubfd0 \uc544\ub2c8\ub77c \uc791\uc5c5\ud558\ub294 \uc190\ub3c4 \ubcf4\uc778\ub2e4. \uc7a5\uc2dd\uc740 \ucc98\uc74c\ubd80\ud130 \ud53c\ubd80\uc5d0 \uc788\ub358 \uac83\uc774 \uc544\ub2c8\ub77c \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc120\uc744 \ub193\uc73c\uba70 \ub9cc\ub4e0 \uacb0\uacfc\ub2e4. \uac00\uae4c\uc774 \uc549\uc544 \uc2dc\uac04\uc744 \ud568\uaed8 \uc4f0\ub294 \ud589\ub3d9\uc774 \uadf8 \ub4a4\uc5d0 \uc788\ub2e4. \ub2e8\uc21c\ud788 \ubb34\ub2ac \ud558\ub098\ub97c \uace0\ub974\ub294 \uac83\uacfc \uc2e4\uc81c\ub85c \ubab8\uc5d0 \ud45c\ud604\ud558\ub294 \uacbd\ud5d8\uc740 \uac19\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ub450 \uc0ac\ub78c\uc774 \uc5b4\ub5a4 \uad00\uacc4\uc778\uc9c0, \uadf8\ub0a0 \uc5b4\ub5a4 \ub300\ud654\ub97c \ub098\ub204\uc5c8\ub294\uc9c0\uae4c\uc9c0 \uc0c1\uc0c1\uc73c\ub85c \uc801\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc0ac\uc9c4\uc774 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \uc791\uc5c5\uacfc \ubab8\uc758 \uc811\uc810\uc774\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc190\uc774 \uad00\uc5ec\ud558\ub294 \uafb8\ubc08\uc774\ub77c\ub294 \uc810\uc744 \ubcf4\uba74 \ubb3c\uac74\uc758 \uc7a5\uc2dd\uacfc \ub2e4\ub978 \uad00\uacc4\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \uc544\ub984\ub2e4\uc6b4 \uc120\uc740 \uc7ac\ub8cc\ubfd0 \uc544\ub2c8\ub77c \uc0ac\ub78c \uc0ac\uc774\uc758 \ud589\ub3d9\uc744 \uac70\uccd0 \ub193\uc778\ub2e4. \ud63c\ub840\uc640 \uae30\ub150\uc77c\uc774\ub77c\ub294 \ubc30\uacbd\uc744 \uc54c\uba74 \ubb34\ub2ac\ub294 \uac1c\uc778\uc758 \ucde8\ud5a5\ub9cc\uc73c\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc5b4\ub5a4 \ub0a0\uc744 \uc704\ud574 \uafb8\ubbf8\uace0 \uadf8 \ubaa8\uc2b5\uc744 \ub2e4\ub978 \uc0ac\ub78c\uacfc \ub098\ub204\ub294 \uc77c\ub3c4 \uc788\uc744 \uc218 \uc788\ub2e4. \ubab8\uc744 \uafb8\ubbf8\ub294 \ud589\ub3d9\uc774 \ub2ec\ub825\uacfc \uad00\uacc4, \ucd95\ud558\uc758 \uc790\ub9ac\uc5d0 \uc5f0\uacb0\ub41c\ub2e4. \ubb3c\ub860 \ubaa8\ub4e0 \uc9c0\uc5ed\uacfc \uc0ac\ub78c\uc774 \uac19\uc740 \uc774\uc720\ub85c \uac19\uc740 \ubaa8\uc591\uc744 \uc4f0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac19\uc740 \uc7ac\ub8cc\uac00 \ub113\uc740 \uc9c0\uc5ed\uc5d0 \uc4f0\uc778\ub2e4\uace0 \ud55c \uac00\uc9c0 \ubb38\ud654\uc758 \uace0\uc815\ub41c \uc0c1\uc9d5\ud45c\ub85c \uc815\ub9ac\ud558\uba74 \ucc28\uc774\ub97c \ub193\uce58\uac8c \ub41c\ub2e4. \uc5b4\ub290 \uc9c0\uc5ed\uc758 \uc5b4\ub5a4 \ud589\uc0ac\ub97c \uc124\uba85\ud558\ub294\uc9c0 \uc790\ub8cc\uc758 \ubc94\uc704\ub97c \uba3c\uc800 \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uc778\ub3c4 \uc544\ub300\ub959\uacfc \ubd81\uc544\ud504\ub9ac\uce74\uc758 \uc0ac\ub840\ub97c \ud558\ub098\uc758 \ub611\uac19\uc740 \uacbd\ud5d8\uc73c\ub85c \ubb36\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \uacf5\ud1b5\uc810\uacfc \ucc28\uc774\ub97c \ud568\uaed8 \ubcf4\ub294 \uac83\uc774 \ubb38\ud654 \uc77d\uae30\uc758 \uc990\uac70\uc6c0\uc774\ub2e4. \uac89\uc758 \uc7ac\ub8cc\ub97c \uc81c\uac70\ud55c \ub4a4\uc5d0\ub3c4 \uc0c9\uc774 \ub0a8\ub294\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc7a5\uc2dd\uc758 \uc2dc\uac04\uc744 \ub458\ub85c \ub098\ub208\ub2e4. \uc120\uc744 \ub193\ub294 \uc21c\uac04\uacfc \uadf8\ub2e4\uc74c \ubab8\uc5d0 \uc0c9\uc744 \uc9c0\ub2c8\ub294 \uc2dc\uac04\uc774 \uc788\ub2e4. \uc0ac\uc9c4 \ud55c \uc7a5\uc740 \uc5b4\ub290 \ud55c\ub54c\ub97c \ubcf4\uc5ec \uc8fc\uc9c0\ub9cc \uadf8 \uc55e\ub4a4\uc758 \ubcc0\ud654\ub97c \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc7a5\uc2dd\uc740 \uc644\uc131\ud55c \ubb3c\uac74\ucc98\ub7fc \uace0\uc815\ub41c \ubaa8\uc2b5\ub9cc \uac16\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ubab8\uacfc \ud568\uaed8 \ub2ec\ub77c\uc9c0\ub294 \uac83\uc774\uae30\ub3c4 \ud558\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc5bc\ub9c8\ub098 \uc624\ub798\uac14\ub294\uc9c0\ub098 \uc5b4\ub5a4 \uc0c9\uc774 \ub204\uad6c\uc5d0\uac8c \ub098\ud0c0\ub0ac\ub294\uc9c0\ub97c \uc0c8\ub85c \ub2e8\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc790\ub8cc\uc758 \uc77c\ubc18\uc801\uc778 \uacfc\uc815 \uc124\uba85\uacfc \uac1c\ubcc4 \uc0ac\uc9c4\uc758 \uc0c1\ud0dc\ub97c \uad6c\ubd84\ud574 \uc77d\ub294\ub2e4. \ubcf4\uc774\ub294 \uc120\uc744 \ucc9c\ucc9c\ud788 \ub530\ub77c\uac00\uace0 \uadf8\uac83\uc744 \ub9cc\ub4dc\ub294 \uc190\uc758 \uc704\uce58\ub3c4 \ubcf4\uc544 \ubcf4\uc790. \ud53c\ubd80\uc758 \ubb34\ub2ac\uc5d0\uc11c \uc7ac\ub8cc\uc640 \uc2dc\uac04, \uc0ac\ub78c \uc0ac\uc774\uc758 \uad00\uacc4\uac00 \ud568\uaed8 \ub4dc\ub7ec\ub0a0 \uc218 \uc788\ub2e4. \uc774 \uc0ac\uc9c4\uc758 \uc7a5\uc18c\ub97c \ud655\uc778 \uc5c6\uc774 \ud2b9\uc815 \ub098\ub77c\ub098 \ub3c4\uc2dc\ub85c \uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5ec\uae30\uc11c \uc2e4\uc81c\ub85c \ubcfc \uc218 \uc788\ub294 \uac83\uc740 \ud53c\ubd80 \uc704\uc5d0 \ubb34\ub2ac\ub97c \ub354\ud558\ub294 \uc791\uc5c5\uc774\uba70, \ubb38\ud654\uc801 \uc4f0\uc784\uc740 \uad50\uc7ac\uc758 \uc124\uba85\uc73c\ub85c \ub530\ub85c \uc77d\ub294 \ubd80\ubd84\uc774\ub2e4. \ubab8\uc744 \uafb8\ubbf8\ub294 \uc77c\uc5d0\ub294 \uc637\uacfc \ubcf4\uc11d\ub9cc \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc120\uc744 \uae0b\uace0 \uc7ac\ub8cc\ub97c \uae30\ub2e4\ub9b0 \ub4a4 \uc0c9\uc744 \ub0a8\uae30\ub294 \ubc29\ubc95\ub3c4 \uc788\ub2e4. \ud5e4\ub098\uc758 \uc7a5\uba74\uc740 \uc7a5\uc2dd\uc774 \ubb34\uc5c7\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc9c0\uace0 \uc5b8\uc81c \uc644\uc131\ub418\ub294\uc9c0\ub97c \uc870\uae08 \ub2e4\ub974\uac8c \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4."}, {"id": "jordan-moving-tent", "title": "\uc774 \uc9d1\uc740 \ub2e4\uc74c \ubaa9\ucd08\uc9c0\uae4c\uc9c0 \ud568\uaed8 \uac04\ub2e4", "summary": "\uc774\ub3d9\ud558\ub294 \uc0dd\ud65c\uc5d0\uc11c \ucc9c\ub9c9\uc774 \uc784\uc2dc \uac70\ucc98 \uc774\uc0c1\uc758 \uc9d1\uc774 \ub418\ub294 \ubc29\uc2dd\uc744 \ubd05\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\uc9d1\uacfc \uc0dd\ud65c \ub3c4\uad6c", "categories": ["everyday-inventions"], "url": "stories/jordan-moving-tent/index.html", "image": "../media/jordan-moving-tent.jpg", "alt": "\uc694\ub974\ub2e8\uc758 \uacbd\uc0ac\uc9c0\uc5d0 \uc138\uc6cc\uc9c4 \uae38\ucb49\ud55c \ubca0\ub450\uc778 \ucc9c\ub9c9\uacfc \uc8fc\ubcc0 \ud48d\uacbd\uc758 \uc2e4\uc81c \uc0ac\uc9c4.", "text": "\uc774 \uc9d1\uc740 \ub2e4\uc74c \ubaa9\ucd08\uc9c0\uae4c\uc9c0 \ud568\uaed8 \uac04\ub2e4 \uc694\ub974\ub2e8\uc758 \ucc9c\ub9c9\uc5d0\uc11c \uc9d1\uc758 \uc870\uac74\uc744 \ub2e4\uc2dc \ubcf4\uae30 \uc774\ub3d9\ud558\ub294 \uc0dd\ud65c\uc5d0\uc11c \ucc9c\ub9c9\uc774 \uc784\uc2dc \uac70\ucc98 \uc774\uc0c1\uc758 \uc9d1\uc774 \ub418\ub294 \ubc29\uc2dd\uc744 \ubd05\ub2c8\ub2e4. \uc9d1\uacfc \uc0dd\ud65c \ub3c4\uad6c \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \uc0ac\uc9c4 \uc18d \ube44\ud0c8\uc5d0\ub294 \ub0ae\uace0 \uae38\ucb49\ud55c \ucc9c\ub9c9\uc774 \ub193\uc5ec \uc788\ub2e4. \ub2e8\ub2e8\ud55c \ubcbd\ub3cc \uac74\ubb3c\uc5d0 \uc775\uc219\ud558\ub2e4\uba74 \uc7a0\uae50 \uba38\ubb34\ub294 \uc57c\uc601\uc9c0\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc774\ub3d9\ud558\uba70 \uac00\ucd95\uc744 \ub3cc\ubcf4\ub294 \uc0dd\ud65c\uc5d0\uc11c\ub294 \uc9d1\ub3c4 \ud568\uaed8 \uc6c0\uc9c1\uc77c \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4. OpenStax\uc758 \uc778\ub958\ud559 \uad50\uc7ac\ub294 \uc774 \uc0ac\uc9c4\uc744 \uc694\ub974\ub2e8\uc758 \ubca0\ub450\uc778 \ucc9c\ub9c9\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \uc9d1\uc744 \ud55c \uc7a5\uc18c\uc5d0 \uace0\uc815\ub41c \uac74\ubb3c\uc774\ub77c\uace0\ub9cc \uc0dd\uac01\ud558\uba74 \uc9c0\ub098\uce58\uae30 \uc26c\uc6b4 \uc0dd\ud65c\uc758 \uc870\uac74\uc774 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc77c\ubd80 \ubca0\ub450\uc778 \ubaa9\ucd95 \uacf5\ub3d9\uccb4\uac00 \uac00\ucd95\uc744 \uba39\uc77c \ud480\uacfc \ubb3c\uc744 \ucc3e\uc544 \uac70\ucc98\ub97c \uc62e\uaca8 \uc654\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc774\ub7f0 \uc0dd\ud65c\uc5d0\uc11c\ub294 \uc9d1\uc744 \uc138\uc6b0\ub294 \uc77c\uacfc \uac77\ub294 \uc77c\uc774 \ubaa8\ub450 \uc911\uc694\ud558\ub2e4. \ubb34\ub108\uc9c0\uc9c0 \uc54a\ub294 \uac83\ub9cc\uc774 \uc88b\uc740 \uc9d1\uc758 \uc870\uac74\uc740 \uc544\ub2c8\ub2e4. \uc0ac\uc6a9\ud558\ub358 \uac70\ucc98\ub97c \uc815\ub9ac\ud558\uace0 \ub2e4\ub978 \uc790\ub9ac\uc5d0\uc11c \ub2e4\uc2dc \ud3bc\uce60 \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4. \ucc9c\ub9c9\uc740 \uadf8 \ud544\uc694\uc640 \uc798 \ub9de\ub294 \ud615\ud0dc\ub2e4. \uc0ac\uc9c4\uc758 \ub0ae\uc740 \uc9c0\ubd95\uc744 \ubcfc \ub54c \uc624\ub298 \uba38\ubb34\ub294 \uc790\ub9ac\uc640 \ub2e4\uc74c\uc5d0 \uba38\ubb3c \uc790\ub9ac\ub97c \ud568\uaed8 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uc774\ub3d9\ud558\ub294 \uc9d1\uc774\ub77c\uace0 \uc548\ucabd\uc774 \uc544\ubb34\ub807\uac8c\ub098 \ube44\uc5b4 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uad50\uc7ac\ub294 \uc804\ud1b5\uc801\uc778 \ubca0\ub450\uc778 \uac70\ucc98\uc5d0\uc11c \uc870\ub9ac\uc640 \ubcf4\uad00, \uc190\ub2d8 \ub9de\uc774 \ub4f1\uc744 \uc704\ud574 \uacf5\uac04\uc744 \ub098\ub204\ub294 \uc608\ub97c \uc18c\uac1c\ud55c\ub2e4. \uac00\uc871\uc758 \uc77c\uacfc \uad00\uacc4\uac00 \uacf5\uac04 \uc548\uc5d0 \uc790\ub9ac \uc7a1\ub294 \uac83\uc774\ub2e4. \ubb3c\ub860 \uc0ac\uc9c4\ub9cc \ubcf4\uace0 \uc774 \ucc9c\ub9c9\uc758 \ubaa8\ub4e0 \ubc29 \ubc30\uce58\ub97c \uc54c\uc544\ub0bc \uc218\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc774\ub3d9 \uac00\ub2a5\uc131\uacfc \uc77c\uc0c1\uc758 \uad6c\ubd84\uc774 \ud568\uaed8 \uc788\uc744 \uc218 \uc788\ub2e4\ub294 \uc810\uc744 \uc0b4\ud3b4\ubcf4\uba74 \ucda9\ubd84\ud558\ub2e4. \uac00\ubcbc\uc6b4 \uc7ac\ub8cc\uac00 \uac00\ubcbc\uc6b4 \uc0dd\ud65c\uc744 \ub73b\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc6b0\ub9ac\ub294 \uc9d1\uc744 \uc8fc\uc18c\uac00 \uace0\uc815\ub41c \uac74\ubb3c\ub85c \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \ubaa9\ucd08\uc9c0\uc640 \ubb3c\uc744 \ub530\ub77c \uc774\ub3d9\ud558\ub294 \uc0dd\ud65c\uc5d0\uc11c\ub294 \ub2e4\uc2dc \uc138\uc6b8 \uc218 \uc788\ub294\uc9c0\uac00 \uc911\uc694\ud55c \uc870\uac74\uc774 \ub41c\ub2e4. \uac19\uc740 \uc7a5\uc18c\uc5d0 \uc624\ub798 \uc11c \uc788\ub2e4\ub294 \uae30\uc900\ub9cc\uc73c\ub85c \uc9d1\uc758 \uc88b\uace0 \ub098\uc068\uc744 \ud310\ub2e8\ud558\uae30 \uc5b4\ub835\ub2e4. \ucc9c\ub9c9\uc740 \uba38\ubb34\ub294 \uac83\uacfc \uc62e\uae30\ub294 \uac83\uc744 \ud568\uaed8 \uc900\ube44\ud558\ub294 \uac70\ucc98\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc0ac\uc9c4 \uc18d \uc9d1\ub2e8\uc774 \uc5b8\uc81c \uc5b4\ub5a4 \uacbd\ub85c\ub85c \uc774\ub3d9\ud588\ub294\uc9c0\uae4c\uc9c0 \uc54c \uc218\ub294 \uc5c6\ub2e4. \uc774\ub3d9 \uac00\ub2a5\uc131\uc744 \uac00\uc9c4 \uc8fc\uac70\uc758 \ud2b9\uc9d5\uacfc \ud2b9\uc815 \uac00\uc871\uc758 \uc0dd\ud65c\uc740 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \uad50\uc7ac\ub294 \uc77c\ubd80 \ubaa9\ucd95 \uacf5\ub3d9\uccb4\uc758 \uc0ac\ub840\ub97c \uc124\uba85\ud55c\ub2e4. \ubca0\ub450\uc778\uc774\ub77c\ub294 \uc774\ub984\uc744 \uac00\uc9c4 \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \ud604\uc7ac\ub3c4 \ud55c \ubc29\uc2dd\uc73c\ub85c \uc0b0\ub2e4\uace0 \uc77c\ubc18\ud654\ud558\uba74 \uc790\ub8cc\uc758 \ubc94\uc704\ub97c \ubc97\uc5b4\ub09c\ub2e4. \uc870\ub9ac\uc640 \ubcf4\uad00, \uc190\ub2d8 \ub9de\uc774\uc758 \uc790\ub9ac\ub97c \ub098\ub204\ub294 \uc77c\uc740 \ubcbd\ub3cc\ubc29\uc5d0\uc11c\ub9cc \uc0dd\uae30\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc77c\uc758 \uc885\ub958\uc640 \uc0ac\ub78c \uc0ac\uc774\uc758 \uad00\uacc4\uac00 \uc788\uc73c\uba74 \ucc9c\ub9c9 \uc548\uc5d0\uc11c\ub3c4 \uc704\uce58\uac00 \uc758\ubbf8\ub97c \uac00\uc9c8 \uc218 \uc788\ub2e4. \uc9d1\uc758 \uc870\uc9c1\uc744 \uc7ac\ub8cc\uc758 \ub2e8\ub2e8\ud568\ub9cc\uc73c\ub85c \uc124\uba85\ud560 \uc218 \uc5c6\ub294 \uc774\uc720\ub2e4. \uac00\ubcbc\uc6b4 \uac70\ucc98\uac00 \uace7 \uad6c\ubd84 \uc5c6\ub294 \ube48 \uacf5\uac04\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4\uc758 \ubc14\uae65\ubaa8\uc2b5\uc744 \ubcf4\uace0 \uc548\ucabd\uc758 \ubaa8\ub4e0 \ubc30\uce58\ub97c \uadf8\ub824 \ub123\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uad50\uc7ac\uac00 \uc804\ud1b5 \uac70\ucc98\uc758 \uc608\ub85c \uc124\uba85\ud558\ub294 \ub0b4\uc6a9\uacfc \uc9c0\uae08 \ubcf4\uc774\ub294 \uc0ac\uc9c4\uc744 \ud568\uaed8 \uc77d\ub294 \uac83\uc774\ub2e4. \ubb38\uacfc \uae30\ub465, \ucc9c\uc758 \uacbd\uacc4\ub97c \uad00\ucc30\ud558\ub418 \uc2e4\uc81c \uae30\ub2a5\uc758 \uc138\ubd80\ub294 \ud574\ub2f9 \uc124\uba85\uc744 \uae30\uc900\uc73c\ub85c \uc0bc\ub294\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \uad6c\uc870\uc640 \uc0ac\ud68c\uc801 \uc0ac\uc6a9\uc740 \uc11c\ub85c \ubcf4\uc644\ud560 \uc218 \uc788\ub2e4. \ubaa9\ucd95\uc5d0\uc11c\ub294 \uc0ac\ub78c\ub9cc\uc774 \uc544\ub2c8\ub77c \uac00\ucd95\uc758 \uba39\uc774\uc640 \ubb3c\ub3c4 \uc774\ub3d9\uc5d0 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\ub2e4. \uc9d1\uc744 \uc5b4\ub514\uc5d0 \ub458\uc9c0\uc758 \ubb38\uc81c\uc5d0 \ub2e4\ub978 \uc0dd\ubb3c\uc758 \uc0dd\ud65c \uc870\uac74\uc774 \ub4e4\uc5b4\uc624\ub294 \uc148\uc774\ub2e4. \ub3c4\uc2dc\uc758 \uc0c1\uac00\uc640 \ucd9c\ud1f4\uadfc \uac70\ub9ac\ub97c \uc911\uc2ec\uc73c\ub85c \uc9d1\uc744 \uc0dd\uac01\ud558\ub294 \uacbd\ud5d8\uacfc \ub098\ub780\ud788 \ub193\uc73c\uba74, \uc8fc\uac70\uc758 \uc120\ud0dd\uc774 \ud658\uacbd\uacfc \uc77c\uc758 \ubc29\uc2dd\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9d0\uc744 \uc54c \uc218 \uc788\ub2e4. \uc774 \ube44\uad50\uac00 \uc5b4\ub290 \uc0dd\ud65c\uc774 \ub354 \uc790\uc5f0\uc2a4\ub7fd\uac70\ub098 \uc6b0\uc6d4\ud558\ub2e4\ub294 \uc21c\uc704\ub97c \ub9cc\ub4dc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc870\uac74\uc5d0\uc11c \ubb34\uc5c7\uc744 \uc911\uc694\ud558\uac8c \uc5ec\uacbc\ub294\uc9c0 \uc774\ud574\ud558\uae30 \uc704\ud55c \uad00\uc810\uc774\ub2e4. \ubaa8\ub4e0 \ucc9c\ub9c9\uc744 \uc5b4\ub824\uc6b4 \uc0ac\uc815 \ub54c\ubb38\uc5d0 \uc120\ud0dd\ud55c \uc784\uc2dc \uac74\ubb3c\ub85c\ub9cc \uc124\uba85\ud558\ub294 \uac83\ub3c4 \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4. \uad50\uc7ac\uac00 \uc18c\uac1c\ud558\ub294 \uc774\ub3d9\uacfc \uc0dd\ud65c\uc758 \uad00\uacc4\ub97c \uba3c\uc800 \uc77d\uc5b4 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uad50\uc7ac\ub294 \uc624\ub298\uc758 \ubca0\ub450\uc778 \uacf5\ub3d9\uccb4\uac00 \ub2e4\uc591\ud55c \uc815\ucc29\uacfc \ub178\ub3d9\uc758 \ud615\ud0dc\ub97c \uac00\uc9c4\ub2e4\ub294 \uc810\ub3c4 \ud568\uaed8 \uc124\uba85\ud55c\ub2e4. \uacfc\uac70\uc758 \ud55c \uc8fc\uac70 \ubaa8\uc2b5\uc774 \uc0ac\ub78c\ub4e4\uc758 \ud604\uc7ac \uc804\uccb4\ub97c \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc804\ud1b5\uc744 \uc54c\uace0 \uc788\ub2e4\ub294 \ub9d0\uc774 \ud2b9\uc815 \uc9d1\ub2e8\uc744 \uc61b \uc0ac\uc9c4 \uc18d\uc5d0 \uace0\uc815\uc2dc\ud0a4\ub294 \uc77c\uc774 \ub418\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc624\ub798\ub41c \uc0dd\ud65c\uc758 \uae30\uc220\uacfc \uc9c0\uae08\uc758 \uc5ec\ub7ec \uc120\ud0dd\uc740 \ud568\uaed8 \uc788\uc744 \uc218 \uc788\ub2e4. \uc774 \uc0ac\uc9c4\uc744 \ubcfc \ub54c\uc5d0\ub294 \uc694\ub974\ub2e8\uc758 \uc2e4\uc81c \uc7a5\uba74\uc774\ub77c\ub294 \uc815\ubcf4\ub97c \ub0a8\uae30\uace0 \ucc9c\ub9c9\uc758 \ud3bc\uccd0\uc9c4 \ubaa8\uc591\uc744 \ub530\ub77c\uac00 \ubcf4\uc790. \uba40\ub9ac\uc11c \ubcf8 \ub0ae\uc740 \uc9c0\ubd95 \uc548\uc5d0\ub3c4 \uc77c\uacfc \uad00\uacc4\uc758 \uc790\ub9ac\uac00 \uc788\uc5c8\uc744 \uc218 \uc788\ub2e4. \uc9d1\uc744 \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294 \ubcbd\uc73c\ub85c\ub9cc \uc815\uc758\ud558\ub358 \uc2dc\uc120\uc5d0\uc11c \ubc97\uc5b4\ub098\uba74, \ubb34\uc5c7\uc744 \uac00\uc9c0\uace0 \ub2e4\uc74c \uc7a5\uc18c\ub85c \uac08 \uc218 \uc788\uac8c \ud588\ub294\uc9c0\ub77c\ub294 \uc0c8\ub85c\uc6b4 \uac74\ucd95\uc758 \uc9c8\ubb38\uc744 \uc5bb\ub294\ub2e4. \uc624\ub298\uc758 \ubca0\ub450\uc778 \uc0dd\ud65c\uc744 \ubaa8\ub450 \ucc9c\ub9c9 \ud558\ub098\ub85c \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \uad50\uc7ac\ub3c4 \uc815\ucc29\ud55c \ub9c8\uc744\uacfc \ub3c4\uc2dc\uc758 \uc0b6, \uc5ec\ub7ec \ud615\ud0dc\uc758 \uc77c\uc744 \ud568\uaed8 \uc18c\uac1c\ud55c\ub2e4. \uc0ac\uc9c4\uc740 \uadf8 \ub2e4\uc591\ud55c \uc0b6 \uac00\uc6b4\ub370 \ud55c \uac70\ucc98\uc758 \ubaa8\uc2b5\uc774\ub2e4. \uadf8\ub7fc\uc5d0\ub3c4 \uc774 \uc7a5\uba74\uc740 \uc775\uc219\ud55c \uc9c8\ubb38\uc744 \ubc14\uafd4 \uc900\ub2e4. \uc88b\uc740 \uc9d1\uc740 \uc624\ub798 \uac19\uc740 \uc790\ub9ac\uc5d0 \ub0a8\ub294 \uc9d1\uc77c\uae4c, \ud544\uc694\ud55c \uacf3\uae4c\uc9c0 \ud568\uaed8 \uac00\ub294 \uc9d1\uc77c\uae4c. \uc0ac\ub78c\uc758 \uc0dd\ud65c\uc774 \ub2ec\ub77c\uc9c0\uba74 \uc9d1\uc5d0 \uae30\ub300\ud558\ub294 \ub2a5\ub825\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc694\ub974\ub2e8\uc758 \ucc9c\ub9c9\uc740 \uadf8\ub7f0 \uc9d1\uc758 \ub2e4\ub978 \uc5bc\uad74\uc744 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "kabyle-house-shared-roof", "title": "\ud55c \uc9c0\ubd95 \uc544\ub798 \uc0ac\ub78c\uacfc \uac00\ucd95\uc758 \uc790\ub9ac\uac00 \uc788\uc5c8\ub2e4", "summary": "\ub3cc\uc9d1\uc758 \uc678\uad00\uacfc \uc9d1 \uc548\uc744 \uad6c\ubd84\ud55c \uc61b \uc5f0\uad6c \uc0ac\ub840\ub97c \ud568\uaed8 \ubd05\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\uc9d1\uacfc \uc0dd\ud65c \ub3c4\uad6c", "categories": ["everyday-inventions"], "url": "stories/kabyle-house-shared-roof/index.html", "image": "../media/kabyle-house-shared-roof.jpg", "alt": "\uc54c\uc81c\ub9ac \ubd81\ubd80\uc758 \uce74\ube4c \uc8fc\ud0dd \uc678\uad00 \uc2e4\uc81c \uc0ac\uc9c4. \ub3cc\ubcbd\uacfc \ubd89\uc740 \uae30\uc640\uc9c0\ubd95\uc774 \ubaa8\uc5ec \uc788\uc73c\uba70 \uc2e4\ub0b4\ub294 \ubcf4\uc774\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.", "text": "\ud55c \uc9c0\ubd95 \uc544\ub798 \uc0ac\ub78c\uacfc \uac00\ucd95\uc758 \uc790\ub9ac\uac00 \uc788\uc5c8\ub2e4 \uc54c\uc81c\ub9ac \uce74\ube4c \uc8fc\ud0dd\uc744 \uc77d\ub294 \uc791\uc740 \ub2e8\uc11c \ub3cc\uc9d1\uc758 \uc678\uad00\uacfc \uc9d1 \uc548\uc744 \uad6c\ubd84\ud55c \uc61b \uc5f0\uad6c \uc0ac\ub840\ub97c \ud568\uaed8 \ubd05\ub2c8\ub2e4. \uc9d1\uacfc \uc0dd\ud65c \ub3c4\uad6c \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \uc0ac\uc9c4\uc5d0\ub294 \ubd89\uc740 \uc9c0\ubd95\uacfc \ub3cc\ubcbd\uc774 \ubaa8\uc5ec \uc788\ub2e4. \uc54c\uc81c\ub9ac \ubd81\ubd80\uc758 \uce74\ube4c \uc0ac\ub78c\ub4e4\uc774 \uc9c0\uc740 \uc9d1\ub4e4\uc774\ub2e4. \ubc16\uc5d0\uc11c \ubcf4\uba74 \ub2e8\ub2e8\ud55c \ubcbd\uacfc \uc9c0\ubd95\uc774 \uba3c\uc800 \ubcf4\uc774\uc9c0\ub9cc, \uc9d1\uc744 \uc774\ud574\ud558\ub294 \uc77c\uc740 \uadf8 \uc548\uc758 \uc790\ub9ac\ub97c \uc0dd\uac01\ud558\ub294 \ub370\uc11c\ub3c4 \uc2dc\uc791\ub41c\ub2e4. OpenStax \uad50\uc7ac\ub294 1960\ub144\ub300 \ud53c\uc5d0\ub974 \ubd80\ub974\ub514\uc678\uac00 \ubd84\uc11d\ud55c \uc804\ud1b5 \uce74\ube4c \uc8fc\ud0dd\uc758 \uc0ac\ub840\ub97c \uc18c\uac1c\ud55c\ub2e4. \uc774 \uc0ac\uc9c4\uc758 \uc9d1 \ud55c \ucc44\ub97c \uadf8\ub300\ub85c \uc870\uc0ac\ud55c \ud3c9\uba74\ub3c4\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc678\uad00 \uc0ac\uc9c4\uacfc \uc124\uba85\uc758 \uc0ac\ub840\ub97c \ud568\uaed8 \uc77d\ub294 \uac83\uc774\ub2e4. \uc5f0\uad6c \uc0ac\ub840\uc758 \uc9d1\uc5d0\ub294 \ub0ae\uc740 \uad6c\ud68d\uc744 \ub098\ub204\ub294 \ubcbd\uc774 \uc788\uc5c8\uace0, \uadf8\ucabd\uc740 \ubc24\uc5d0 \uac00\ucd95\uc744 \ub4e4\uc774\ub294 \uc790\ub9ac\uc600\ub2e4. \uac19\uc740 \uc9c0\ubd95 \uc544\ub798\uc5d0\uc11c\ub3c4 \ubc14\ub2e5\uc744 \ub0ae\ucd94\uace0 \uad6c\ubd84\ud574 \uc11c\ub85c \ub2e4\ub978 \ud65c\ub3d9\uc758 \uc790\ub9ac\ub97c \ub9cc\ub4e4\uc5c8\ub2e4. \ub098\uba38\uc9c0 \ub354 \ub192\uace0 \ub113\uc740 \ubd80\ubd84\uc740 \uc0ac\ub78c\uc758 \uc0dd\ud65c\uc5d0 \uc4f0\uc600\ub2e4. \uc9d1\uc744 \ubc29 \uc774\ub984 \uba87 \uac1c\ub85c\ub9cc \ub098\ub204\ub294 \ub300\uc2e0 \ub192\uc774\uc640 \uacbd\uacc4\ub85c \uc77d\uc5b4 \ubcf4\uba74 \ub0b4\ubd80\uc758 \uad6c\uc131\uc774 \ub2e4\ub974\uac8c \ub290\uaef4\uc9c4\ub2e4. \uad50\uc7ac\ub294 \ubb38 \ubc18\ub300\ucabd\uc758 \ubca0\ud2c0 \uc790\ub9ac\uc640 \uadf8\uacf3\uc5d0 \ub4dc\ub294 \ube5b\ub3c4 \uc124\uba85\ud55c\ub2e4. \uc190\ub2d8 \ub4f1\uc744 \ub9de\ub294 \uc790\ub9ac\uc640 \uc5ec\ub7ec \uc0dd\ud65c \ud65c\ub3d9\uc774 \uc9d1 \uc548\uc758 \uc704\uce58\uc5d0 \ub530\ub77c \uad6c\ubcc4\ub418\uc5c8\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \ubcf4\uc774\uc9c0 \uc54a\ub294 \ub0b4\ubd80\ub97c \ub9c8\uc74c\ub300\ub85c \uadf8\ub824 \ub123\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c \ubcfc \uac83\uc740 \uc9c0\ubd95\uc758 \uc7ac\ub8cc\ub9cc\uc774 \uc544\ub2c8\ub77c \uc77c\uc744 \ud558\uace0 \uc0ac\ub78c\uc744 \ub9de\ub294 \ubc29\uc2dd\ub3c4 \uc9d1\uc758 \uad6c\uc131\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4\ub294 \uc810\uc774\ub2e4. \uc5b4\ub5a4 \uc790\ub9ac\ub97c \uc88b\ub2e4\uace0 \uc5ec\uae30\ub294\uc9c0\uc5d0\ub3c4 \uc0dd\ud65c\uc758 \uc0dd\uac01\uc774 \ub2f4\uae38 \uc218 \uc788\ub2e4. \uac74\ubb3c\uc758 \uac89\ubaa8\uc591\uc5d0\uc11c \ud55c \uacf5\uac04\uc744 \uc0c1\uc0c1\ud558\uae30 \uc27d\uc9c0\ub9cc \uc548\uc5d0\uc11c\ub294 \ub192\uc774\uc640 \uacbd\uacc4\uac00 \uc5ed\ud560\uc744 \ub098\ub20c \uc218 \uc788\ub2e4. \uc0ac\ub78c\uacfc \uac00\ucd95\uc758 \uad6c\ud68d\uc744 \ub2e4\ub974\uac8c \ub450\uc5c8\ub2e4\ub294 \uc124\uba85\uc740 \ubcbd\uacfc \ubc14\ub2e5\uc758 \uc791\uc740 \ucc28\uc774\ub97c \uc0dd\ud65c\uc758 \uad6c\uc870\ub85c \uc77d\uac8c \ud55c\ub2e4. \ubc29\uc758 \uc774\ub984\ub9cc\uc73c\ub85c \uc9d1\uc744 \uc774\ud574\ud558\ub294 \ubc29\uc2dd\uacfc \ub2e4\ub978 \ub2e8\uc11c\ub2e4. \ud568\uaed8 \uc788\ub2e4\ub294 \uac83\uacfc \uad6c\ubd84\uc774 \uc5c6\ub2e4\ub294 \uac83\uc740 \uac19\uc740 \ub9d0\uc774 \uc544\ub2c8\ub2e4. \uc0ac\uc9c4\uc740 \uc2e4\uc81c \uc678\uad00\uc744 \ubcf4\uc5ec \uc8fc\uace0 \uad50\uc7ac\uc758 \uc5f0\uad6c \uc124\uba85\uc740 \ub0b4\ubd80\uc758 \uc0ac\uc6a9\uc744 \uc54c\ub824 \uc900\ub2e4. \ub450 \uc790\ub8cc\uac00 \uc11c\ub85c \uac19\uc740 \uc815\ubcf4\ub97c \ub2f4\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc14\uae65\uc758 \ub3cc\uacfc \uc9c0\ubd95\uc744 \ud655\uc778\ud558\ub294 \uc77c\uacfc \uc548\ucabd\uc758 \ubca0\ud2c0 \uc790\ub9ac, \ub0ae\uc740 \uad6c\ud68d\uc744 \uc774\ud574\ud558\ub294 \uc77c\uc744 \uad6c\ubd84\ud558\uba74 \uc0ac\uc9c4\uc5d0 \uc5c6\ub294 \uc138\ubd80\ub97c \ubcf4\uc558\ub2e4\uace0 \ucc29\uac01\ud558\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uc124\uba85\uc744 \ud1b5\ud574 \uc2dc\uc120\uc744 \ub113\ud790 \uc218 \uc788\ub2e4. \ubca0\ud2c0\uacfc \ube5b\uc758 \uad00\uacc4\ub97c \uc18c\uac1c\ud558\ub294 \ub300\ubaa9\uc740 \uacf5\uac04\uc744 \ud06c\uae30\uc640 \uc7ac\ub8cc \uc774\uc0c1\uc758 \uac83\uc73c\ub85c \ubcf4\uac8c \ud55c\ub2e4. \uc5b4\ub5a4 \uc77c\uc744 \ud558\ub824\uba74 \uadf8 \uc77c\uc5d0 \ub9de\ub294 \uc790\ub9ac\uac00 \ud544\uc694\ud560 \uc218 \uc788\ub2e4. \ubb3c\uac74\uc744 \uc5b4\ub514\uc5d0 \ub450\ub294\uc9c0\uc640 \ubb38\uc744 \ud1b5\ud574 \ub4e4\uc5b4\uc624\ub294 \ube5b\uc774 \uc5b4\ub5bb\uac8c \ub2ff\ub294\uc9c0\uac00 \uc0dd\ud65c\uc758 \ubc30\uce58\ub97c \ub9cc\ub4dc\ub294 \uc694\uc18c\uac00 \ub41c\ub2e4. \ub2e4\ub9cc \uc5ec\uae30\uc11c \uc2e4\uc81c \uc870\ub3c4\ub098 \uc791\uc5c5 \ub2a5\ub960\uc744 \uce21\uc815\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2e4\ub0b4 \ubc30\uce58\uac00 \ub2e8\uc21c\ud788 \uc544\ubb34 \uacf3\uc5d0\ub098 \ub0a8\uc740 \uac00\uad6c\ub97c \ub193\uc740 \uacb0\uacfc\ub9cc\uc740 \uc544\ub2c8\ub77c\ub294 \uc9c8\ubb38\uc744 \uc5bb\uc744 \uc218 \uc788\ub2e4. \uc870\ub9ac\uc640 \uc218\ub0a9, \uc77c\uacfc \uc190\ub2d8 \ub9de\uc774\uc5d0\ub294 \uc11c\ub85c \ub2e4\ub978 \uc694\uad6c\uac00 \uc788\ub2e4. \uc5b4\ub5a4 \uc790\ub9ac\ub97c \uc88b\ub2e4\uace0 \uc5ec\uacbc\ub294\uc9c0\uc5d0\ub3c4 \uacf5\ub3d9\uccb4\uc758 \uc0dd\uac01\uc774 \ub4e4\uc5b4\uac08 \uc218 \uc788\ub2e4. \uc9d1\uc758 \ud3c9\uba74\uc740 \uc0dd\ud65c\uc744 \ub2f4\uc73c\uba74\uc11c \uadf8 \uc0dd\ud65c\uc758 \uad00\uacc4\ub97c \ub098\ud0c0\ub0b4\ub294 \ud615\uc2dd\uc774\uae30\ub3c4 \ud558\ub2e4. \uad50\uc7ac\ub294 1960\ub144\ub300 \ud53c\uc5d0\ub974 \ubd80\ub974\ub514\uc678\uac00 \ubd84\uc11d\ud55c \uc804\ud1b5 \uce74\ube4c \uc8fc\ud0dd\uc744 \uc0ac\ub840\ub85c \ub4e0\ub2e4. \ud2b9\uc815\ud55c \uc2dc\uc810\uc758 \uc5f0\uad6c\uc640 \ud574\uc11d\uc774\uc9c0 \uc54c\uc81c\ub9ac \ubd81\ubd80\uc758 \ubaa8\ub4e0 \ud604\uc7ac \uc8fc\ud0dd\uc744 \uc870\uc0ac\ud55c \ud45c\uc900 \uc124\uba85\uc774 \uc544\ub2c8\ub2e4. \uc5f0\uad6c\uc790\uc758 \uc9c8\ubb38\uacfc \uadf8\ub54c \uc0b4\ud540 \ub300\uc0c1\uc758 \ubc94\uc704\ub97c \ub0a8\uaca8 \ub450\uc5b4\uc57c \ud55c\ub2e4. \uc9d1 \ud55c \ucc44\uc758 \ubaa8\ub378\uc744 \ud558\ub098\uc758 \ubb38\ud654 \uc804\uccb4\uc640 \uac19\uac8c \ub193\uc73c\uba74 \ucc28\uc774\uac00 \uc0ac\ub77c\uc9c4\ub2e4. \ub530\ub77c\uc11c \uc624\ub298 \uadf8 \uc9c0\uc5ed\uc5d0 \uac00\uba74 \uc0ac\uc9c4\uacfc \ub611\uac19\uc740 \ub0b4\ubd80\uac00 \uc5b4\ub514\uc11c\ub098 \ubcf4\uc77c \uac83\uc774\ub77c\uace0 \uae30\ub300\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc8fc\uac70\ub294 \uc2dc\ub300\uc640 \uc0ac\ud68c\uc758 \ubcc0\ud654\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc61b \uc5f0\uad6c\uc758 \uac00\uce58\ub294 \ud604\uc7ac\ub97c \uba48\ucd94\uac8c \ud558\ub294 \ub370\ubcf4\ub2e4 \uc5b4\ub5a4 \uad00\uacc4\ub97c \uad00\ucc30\ud588\ub294\uc9c0 \uc54c\uac8c \ud558\ub294 \ub370 \uc788\ub2e4. \uc790\ub8cc\uc758 \uc2dc\uac04\ub3c4 \uac74\ubb3c\uc758 \uc7ac\ub8cc\ucc98\ub7fc \ud568\uaed8 \uc77d\uc744 \uc815\ubcf4\ub2e4. \uc678\uad00\uc758 \ub3cc\uc744 \ubcf8 \ub2e4\uc74c \ub0b4\ubd80\uc5d0\uc11c \uc77c\uc5b4\ub0ac\ub358 \ud65c\ub3d9\uc744 \uc124\uba85\uacfc \uc5f0\uacb0\ud574 \ubcf4\uc790. \uadf8 \ud65c\ub3d9\uc774 \ubaa8\ub450 \uc0ac\uc9c4\uc5d0 \uc9c1\uc811 \ucc0d\ud614\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\uc73c\uba74 \ubc14\uae65\uacfc \uc548\ucabd\uc758 \uc11c\ub85c \ub2e4\ub978 \uc790\ub8cc\ub97c \ud568\uaed8 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4. \uc8fc\uac70\ub97c \uc77d\ub294 \uc77c\uc740 \ubc29\uc758 \uac1c\uc218\ub97c \ub9de\ud788\ub294 \uc2dc\ud5d8\ubcf4\ub2e4 \uc0ac\ub78c\uc774 \ubb34\uc5c7\uc744 \ud558\uba70 \uc0b4\uc558\ub294\uc9c0 \ubb3b\ub294 \uacfc\uc815\uc5d0 \uac00\uae5d\ub2e4. \uc774\ub54c \uac00\ucd95\uacfc \uac19\uc740 \uc9c0\ubd95 \uc544\ub798 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uace7 \ubd88\ud3b8\ud558\uac70\ub098 \ube44\uc704\uc0dd\uc801\uc774\uc5c8\ub2e4\ub294 \ud3c9\uac00\ub85c \ubc14\uafc0 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \uc0dd\ud65c\uc758 \uc0c1\ud0dc\ub97c \uc624\ub298\uc758 \uac10\uac01\ub9cc\uc73c\ub85c \ud310\uc815\ud558\uc9c0 \uc54a\ub294 \uac83\uc774\ub2e4. \ub0ae\uc740 \uad6c\ud68d\uacfc \ub192\uc740 \uad6c\ud68d, \ube5b\uacfc \ubca0\ud2c0\uc758 \uc790\ub9ac\ub97c \ub530\ub77c\uac00\ub2e4 \ubcf4\uba74 \ub0af\uc120 \uc9d1\uc774 \ud558\ub098\uc758 \uc0dd\ud65c \uc870\uc9c1\uc73c\ub85c \ub2e4\uac00\uc628\ub2e4. \ud070 \uc9c0\ubd95 \uc544\ub798\uc5d0\ub294 \uc5ec\ub7ec \uad00\uacc4\uc758 \uacbd\uacc4\uac00 \uc788\uc5c8\ub2e4. \uc774\uac83\uc740 \ud2b9\uc815 \uc2dc\uae30\uc758 \uc804\ud1b5 \uc8fc\ud0dd \uc5f0\uad6c \uc0ac\ub840\ub2e4. \uc624\ub298\ub0a0\uc758 \ubaa8\ub4e0 \uce74\ube4c \uac00\uc815\uc774 \uac19\uc740 \uacf5\uac04\uc5d0\uc11c \uac19\uc740 \uaddc\uce59\uc73c\ub85c \uc0b0\ub2e4\uace0 \ub113\ud600 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc9d1\uc758 \uc4f0\uc784\uc740 \uc2dc\uac04\uacfc \uc0ac\ub78c\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c4\ub2e4. \uadf8\ub7fc\uc5d0\ub3c4 \uc774\ub7f0 \uc0ac\ub840\ub294 \uc775\uc219\ud55c \uc9d1\uc744 \ub2e4\uc2dc \ubcf4\ub294 \ubc29\ubc95\uc744 \uc900\ub2e4. \uc65c \uc774 \uc790\ub9ac\ub294 \ub192\uace0 \uc800 \uc790\ub9ac\ub294 \ub0ae\uc744\uae4c, \uc65c \uc190\ub2d8\uc744 \uc774\ucabd\uc5d0 \uc549\ud790\uae4c. \ub3cc\ubcbd\uacfc \uc9c0\ubd95 \uc548\uc5d0\ub294 \uc7ac\ub8cc\ubfd0 \uc544\ub2c8\ub77c \uc11c\ub85c \ub2e4\ub978 \uc0dd\ud65c\uc744 \ud55c \uacf5\uac04\uc5d0 \ub193\uc73c\ub824\ub358 \uc120\ud0dd\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4."}, {"id": "lego-first-wheels", "title": "\ub808\uace0 \ube14\ub85d\uc774 \uad74\ub7ec\uac00\uae30 \uc2dc\uc791\ud55c \ub0a0", "summary": "\ubcbd\uacfc \uc9d1\uc744 \uc313\ub358 \ube14\ub85d\uc5d0 \ubc14\ud034\uac00 \ubd99\uc5c8\uc2b5\ub2c8\ub2e4. \uc6c0\uc9c1\uc77c \uc218 \uc788\ub2e4\ub294 \uac83\uc740 \ub180\uc774\uc5d0 \uc5b4\ub5a4 \ubcc0\ud654\ub97c \uc8fc\uc5c8\uc744\uae4c\uc694?", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\ub180\uc774\uc640 \ucde8\ubbf8", "categories": ["everyday-inventions"], "url": "stories/lego-first-wheels/index.html", "image": "../media/lego-first-wheels.jpg", "alt": "\ube14\ub85d \uc7a5\ub09c\uac10 \uc790\ub3d9\ucc28\uc640 \uc791\uc740 \ubc14\ud034\ub97c \uadf8\ub9b0 AI \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ub808\uace0 \ube14\ub85d\uc774 \uad74\ub7ec\uac00\uae30 \uc2dc\uc791\ud55c \ub0a0 \uc791\uc740 \ubc14\ud034 \ud558\ub098\uac00 \ubc14\uafbc \ub180\uc774\uc758 \uc6c0\uc9c1\uc784 \ubcbd\uacfc \uc9d1\uc744 \uc313\ub358 \ube14\ub85d\uc5d0 \ubc14\ud034\uac00 \ubd99\uc5c8\uc2b5\ub2c8\ub2e4. \uc6c0\uc9c1\uc77c \uc218 \uc788\ub2e4\ub294 \uac83\uc740 \ub180\uc774\uc5d0 \uc5b4\ub5a4 \ubcc0\ud654\ub97c \uc8fc\uc5c8\uc744\uae4c\uc694? \ub180\uc774\uc640 \ucde8\ubbf8 \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \ube14\ub85d\uc73c\ub85c \uc790\ub3d9\ucc28\ub97c \ub9cc\ub4e4\uc5c8\ub294\ub370 \ubc14\ud034\uac00 \uc5c6\ub2e4\uba74 \uc5b4\ub5bb\uac8c \ub420\uae4c. \ubaa8\uc591\uc740 \uc790\ub3d9\ucc28\uc9c0\ub9cc \uc6c0\uc9c1\uc774\ub824\uba74 \ubc14\ub2e5 \uc704\ub85c \ubc00\uac70\ub098 \uc190\uc73c\ub85c \ub4e4\uc5b4 \uc62e\uaca8\uc57c \ud55c\ub2e4. \uc9c0\uae08\uc740 \ub2f9\uc5f0\ud558\uac8c \ub290\uaef4\uc9c0\ub294 \ub808\uace0\uc758 \ubc14\ud034\ub3c4 \ucc98\uc74c\ubd80\ud130 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub808\uace0 \uacf5\uc2dd \uc5f0\ud601\uc740 1950\ub144\ub300 \ub9d0, \ube14\ub85d\uc5d0 \ub9de\ub294 \ubc14\ud034\ub97c \ub9cc\ub4e4\uae30 \uc704\ud574 \uc5ec\ub7ec \uc0ac\ub78c\uc774 \uc124\uacc4\ub97c \uace0\ubbfc\ud558\ub358 \uacfc\uc815\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc791\uc740 \uc6d0 \ud558\ub098\ub97c \ubd99\uc774\uba74 \ub420 \uac83 \uac19\uc9c0\ub9cc, \ube14\ub85d\uc758 \uc138\uacc4\uc5d0\uc11c\ub294 \uadf8 \uc6d0\uc744 \uc5b4\ub514\uc5d0 \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ud560\uc9c0\uac00 \ubb38\uc81c\uc600\ub2e4. \uacf5\uc2dd \uc5f0\ud601\uc5d0 \ub530\ub974\uba74 \uac1c\ubc1c \ubd80\uc11c\uc758 \ud06c\ub204\ub4dc \ubb04\ub808\ub974 \ud06c\ub9ac\uc2a4\ud150\uc13c\uc740 1958\ub144\uc5d0 \ubc14\ud034\uc758 \ubaa8\uc2b5\uc744 \uc2a4\ucf00\uce58\ud588\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ubc14\ud034\ub97c \ube14\ub85d \ub450 \uac1c \uc0ac\uc774\uc5d0 \ub450\ub824 \ud588\uc9c0\ub9cc, \uadf8 \ubc29\uc2dd\uc740 \uc81c\ub300\ub85c \uc791\ub3d9\ud558\uc9c0 \uc54a\uc558\ub2e4. \uadf8 \ub4a4\uc758 \ud574\uacb0\ucc45\uc5d0\ub294 \ube14\ub85d\uacfc \uae08\uc18d \ucd95, \ubc14\ud034 \uc911\uc2ec\ubd80\uc640 \uace0\ubb34 \ud0c0\uc774\uc5b4\uac00 \ud568\uaed8 \ub4e4\uc5b4\uac14\ub2e4. \ucd95\uc744 \ubc1b\uc544 \uc8fc\ub294 \uad6c\uba4d\uc774 \uc788\ub294 \ube14\ub85d\uacfc \uc5f0\uacb0\ud558\ub294 \ubc29\uc2dd\uc774\uc5c8\ub2e4. \ubc14\ud034\ub9cc \ub530\ub85c \uc798 \uad74\ub7ec\uac04\ub2e4\uace0 \ub05d\ub098\ub294 \uc77c\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc774\ubbf8 \uc788\ub358 \ube14\ub85d\uacfc \ud568\uaed8 \uc4f8 \uc218 \uc788\uc5b4\uc57c \ud588\ub2e4. \uc0c8 \ubd80\ud488 \ud558\ub098\uac00 \uae30\uc874 \ub180\uc774\uc758 \uc57d\uc18d \uc548\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \uacfc\uc815\uc774\uc5c8\ub358 \uac83\uc774\ub2e4. \uc774 \ubc14\ud034\ub294 \uc218\uc815\uc744 \uac70\uccd0 1962\ub144\uc5d0 \ucd9c\uc2dc\ub418\uc5c8\ub2e4. \ub808\uace0\ub294 \uac19\uc740 \ud574 \ub258\ub978\ubca0\ub974\ud06c \ubc15\ub78c\ud68c\uc5d0\uc11c \ubc14\ud034\ub97c \uc120\ubcf4\uc778 \uc7a5\uba74\ub3c4 \uc5f0\ud601\uc5d0 \ub2f4\uace0 \uc788\ub2e4. \uacf5\uc2dd \uc124\uba85\uc740 \ubc14\ud034\uc758 \ub4f1\uc7a5\uc744 \ube14\ub85d\uc5d0 \uc6c0\uc9c1\uc784\uc774 \ub354\ud574\uc9c4 \uc804\ud658\uc810\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \uc774\ud6c4 1960\ub144\ub300\uc5d0 \ube14\ub85d\uc73c\ub85c \ub9cc\ub4dc\ub294 \uc790\ub3d9\ucc28\uc640 \uae30\ucc28\uac00 \ub354 \ub9ce\uc774 \ub4f1\uc7a5\ud588\ub2e4. \uac00\ub9cc\ud788 \uc138\uc6cc \ub450\ub358 \ubaa8\uc591\uc774 \uad74\ub7ec\uac00\uba74 \ub180\uc774\uc758 \uc9c8\ubb38\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \ubb34\uc5c7\uc744 \ub9cc\ub4e4\uae4c\uc5d0 \ub354\ud574, \uc5b4\ub514\ub85c \uc6c0\uc9c1\uc77c\uae4c\ub97c \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uac19\uc740 \ube14\ub85d\uc774 \ubc14\ud034 \uc704\uc5d0\uc11c\ub294 \ub2e4\ub978 \uc5ed\ud560\uc744 \ub9e1\ub294\ub2e4. \uc790\ub3d9\ucc28\uc758 \uac89\ubaa8\uc591\uc5d0 \ub3d9\uadf8\ub780 \ubd80\ud488\uc744 \ubd99\uc778\ub2e4\uace0 \ubaa8\ub450 \uc798 \uad74\ub7ec\uac00\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc14\ud034\uac00 \ub3c4\ub294 \ubd80\ubd84\uacfc \ucc28\uccb4\ub97c \ubc1b\uce58\ub294 \ubd80\ubd84\uc758 \uad00\uacc4\uac00 \ub9de\uc544\uc57c \ud55c\ub2e4. \ub808\uace0 \uc5f0\ud601\uc5d0 \ub098\uc624\ub294 \uae08\uc18d \ucd95\uacfc \uad6c\uba4d\uc774 \uc788\ub294 \ube14\ub85d, \uc911\uc2ec\ubd80\uc640 \uace0\ubb34 \ud0c0\uc774\uc5b4\ub294 \uc774 \ubb38\uc81c\ub97c \uc11c\ub85c \ub098\ub204\uc5b4 \ub9e1\ub294 \uad6c\uc131\uc73c\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \ud558\ub098\uc758 \ubc14\ud034\uac00 \uc0ac\uc2e4\uc740 \uc5ec\ub7ec \ubd80\ud488\uc758 \uad00\uacc4\uc600\ub358 \uc148\uc774\ub2e4. \ucd95\uc774 \ubc14\ud034\ub97c \uc5b4\ub5a4 \uc704\uce58\uc5d0 \ub450\ub294\uc9c0, \ucc28\uccb4\uac00 \uc6c0\uc9c1\uc774\ub294 \ub3d9\uc548 \ubd80\ud488\uc774 \uc11c\ub85c \uc5b4\ub5bb\uac8c \ub9cc\ub098\ub294\uc9c0 \uc0dd\uac01\ud574 \ubcf4\uc790. \uc815\ud655\ud55c \uc81c\uc791 \uce58\uc218\ub97c \ubab0\ub77c\ub3c4 \uc5f0\uacb0\uacfc \ud68c\uc804\uc774\ub77c\ub294 \ub450 \uac00\uc9c0 \uc694\uad6c\ub294 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ub2e8\ub2e8\ud788 \ubd99\uc5b4 \uc788\uc5b4\uc57c \ud558\ub294 \ube14\ub85d\uc758 \uc131\uc9c8\uacfc \uc790\uc720\ub86d\uac8c \ub3cc\uc544\uc57c \ud558\ub294 \ubc14\ud034\uc758 \uc131\uc9c8\uc744 \uac19\uc740 \uc7a5\ub09c\uac10 \uc548\uc5d0 \ub9c8\ub828\ud574\uc57c \ud588\ub2e4. \ucc98\uc74c\uc5d0 \ubc14\ud034\ub97c \ube14\ub85d \ub450 \uac1c \uc0ac\uc774\uc5d0 \ub193\uc73c\ub824 \ud588\ub2e4\ub294 \uae30\ub85d\uc740 \uc644\uc131\ud488\ub9cc \ubcf4\uace0\ub294 \uc54c\uae30 \uc5b4\ub824\uc6b4 \uc815\ubcf4\ub2e4. \ub098\uc911\uc758 \ub2f5\uc744 \uc54c\uace0 \ubcf4\uba74 \uc26c\uc6cc \ubcf4\uc774\ub294 \ubb38\uc81c\ub3c4 \uc2e4\uc81c\ub85c\ub294 \uc5ec\ub7ec \ubc30\uce58\ub97c \uc2dc\ud5d8\ud558\uba70 \ud480\uc5c8\uc744 \uc218 \uc788\ub2e4. \ucc98\uc74c\uc758 \uad6c\uc0c1\uacfc \ucd5c\uc885 \uc81c\ud488\uc744 \ube44\uad50\ud558\uba74 \uc81c\ud488 \uac1c\ubc1c\uc744 \ud55c \ubc88\uc758 \ubc88\ub729\uc784\ubcf4\ub2e4 \uc218\uc815\uc758 \uacfc\uc815\uc73c\ub85c \uc77d\uac8c \ub41c\ub2e4. \uc774 \uc790\ub8cc\uac00 \ubaa8\ub4e0 \uc2dc\ud5d8\uc758 \uc138\ubd80\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub807\uc9c0\ub9cc \uacf5\uc2dd \uc5f0\ud601\uc5d0 \uc2a4\ucf00\uce58\uc640 \uc791\ub3d9\ud558\uc9c0 \uc54a\uc740 \ubc29\uc548\uc774 \ud568\uaed8 \uc18c\uac1c\ub41c\ub2e4\ub294 \uc810\ub9cc\uc73c\ub85c\ub3c4 \uc758\ubbf8\uac00 \uc788\ub2e4. \uae30\uc5c5\uc758 \uc5ed\uc0ac\ub97c \ub298 \uc131\uacf5\ud55c \uc81c\ud488\uc758 \ud589\ub82c\ub85c\ub9cc \ubcfc \ud544\uc694\uac00 \uc5c6\uc5b4\uc9c4\ub2e4. \ubb34\uc5c7\uc744 \ub9cc\ub4e4\uc5c8\ub294\uc9c0 \uc606\uc5d0 \ubb34\uc5c7\uc744 \ubc14\uafb8\uc5b4\uc57c \ud588\ub294\uc9c0\ub77c\ub294 \uc9c8\ubb38\uc744 \ub193\uc744 \uc218 \uc788\ub2e4. \ubc14\ud034\ub97c \ucc98\uc74c \ubcf8 \uc0ac\ub78c\uc740 \ubc14\ud034 \uc790\uccb4\ubcf4\ub2e4 \uadf8 \uc704\uc5d0 \ubb34\uc5c7\uc744 \uc5b9\uc744\uc9c0 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc774\ubbf8 \uc775\uc219\ud55c \ube14\ub85d\uc774 \ucc28\uccb4\uac00 \ub418\uace0 \uc88c\uc11d\uc774 \ub418\uace0 \uc9d0\uce78\uc774 \ub41c\ub2e4. \uc0c8\ub85c \ucd94\uac00\ud55c \ubd80\ud488\uc740 \uc790\uae30 \uc5ed\ud560\ub9cc \ud558\ub098 \ub298\ub9ac\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ub2e4\ub978 \ubd80\ud488\ub4e4\uc774 \ub4e4\uc5b4\uac08 \uc7a5\uba74\ub3c4 \ubc14\uafbc\ub2e4. \ub180\uc774\uc758 \ud655\uc7a5\uc774 \ubb3c\uac74\uc758 \uad00\uacc4\uc5d0\uc11c \uc77c\uc5b4\ub098\ub294 \uc21c\uac04\uc774\ub2e4. \uadf8\ub798\uc11c \uacf5\uc2dd \uc5f0\ud601\uc5d0\uc11c \uc790\ub3d9\ucc28\uc640 \uae30\ucc28\uc758 \ud655\uc7a5\uc774 \uc774\uc5b4\uc9c0\ub294 \uac83\uc740 \uc790\uc5f0\uc2a4\ub7fd\ub2e4. \uc815\uc9c0\ud55c \ubaa8\ud615\uc744 \ub9cc\ub4dc\ub294 \uac83\uacfc \uc6c0\uc9c1\uc774\ub294 \ubaa8\ud615\uc744 \uc0ac\uc6a9\ud558\ub294 \uac83\uc740 \ub2e4\ub978 \uc9c8\ubb38\uc744 \ub0b3\ub294\ub2e4. \uae38\uacfc \uc815\ub958\uc7a5\uc744 \ub9cc\ub4e4\uace0, \ubb34\uc5b8\uac00\ub97c \uc2e3\uace0 \ub0b4\ub9ac\ub294 \uc774\uc57c\uae30\ub97c \ubd99\uc77c \uc218\ub3c4 \uc788\ub2e4. \uc774\ub294 \uc774\uc6a9\uc790\uac00 \ub9cc\ub4e4\uc5b4 \uac08 \uac00\ub2a5\uc131\uc758 \uc608\uc774\uba70 \ub2f9\uc2dc \ubaa8\ub4e0 \uc544\uc774\uac00 \uac19\uc740 \ub180\uc774\ub97c \ud588\ub2e4\ub294 \uae30\ub85d\uc744 \ub73b\ud558\uc9c0 \uc54a\ub294\ub2e4. \ube14\ub85d \ub180\uc774\ub294 \uacb0\ud569\uacfc \ubd84\ub9ac\ub97c \ud1b5\ud574 \ubaa8\uc591\uc744 \ubc14\uafb8\ub294 \ub370 \uac15\uc810\uc774 \uc788\ub2e4. \ubc14\ud034\ub294 \uadf8 \ubaa8\uc591\uc744 \uc2e4\uc81c \uacf5\uac04\uc5d0\uc11c \uc6c0\uc9c1\uc774\ub294 \ub300\uc0c1\uc73c\ub85c \ubc14\uafbc\ub2e4. \uc313\uc740 \ub192\uc774\uc640 \ud3ed\ubfd0 \uc544\ub2c8\ub77c \ubc14\ub2e5\uc5d0\uc11c\uc758 \uc6c0\uc9c1\uc784\ub3c4 \uacbd\ud5d8\ud558\uac8c \ub418\ub294 \uac83\uc774\ub2e4. \ubb34\uc5c7\uc774 \ub354 \ud6cc\ub96d\ud55c \ub180\uc774\uc778\uc9c0 \uc21c\uc11c\ub97c \ub9e4\uae30\uae30\ubcf4\ub2e4 \uc11c\ub85c \ub2e4\ub978 \ud589\ub3d9\uc774 \uac00\ub2a5\ud574\uc84c\ub2e4\ub294 \uc810\uc744 \ubcfc \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc0c8\ub85c\uc6b4 \ubd80\ud488\uc774 \ub098\uc654\ub2e4\uace0 \ubaa8\ub4e0 \uc81c\ud488\uc774 \uc5b8\uc81c\ub098 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ud638\ud658\ub41c\ub2e4\uace0 \ub113\ud600 \ub9d0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc5f0\ud601\uc774 \uc124\uba85\ud558\ub294 \ub2f9\uc2dc\uc758 \uc5f0\uacb0 \ubc29\uc2dd\uacfc \ucd9c\uc2dc\ub97c \uc0b4\ud3b4\ubcf8\ub2e4. \uc775\uc219\ud55c \uc7a5\ub09c\uac10\uc758 \uc9c4\ud654\ub97c \uc774\ud574\ud558\ub294 \ub370 \uac00\uc7a5 \ub3c4\uc6c0\uc774 \ub418\ub294 \uac83\uc740 \uac70\ub300\ud55c \uacb0\uacfc\ubb3c\ubcf4\ub2e4 \uc791\uc740 \ubd80\ud488 \ud558\ub098\uac00 \uae30\uc874\uc758 \uc57d\uc18d \uc548\uc73c\ub85c \ub4e4\uc5b4\uc624\ub294 \uacfc\uc815\uc744 \ubcf4\ub294 \uc77c\uc77c \ub54c\ub3c4 \uc788\ub2e4. \uc644\uc131\ub41c \uc7a5\ub09c\uac10\uc744 \ubcf4\uba74 \uc804\uccb4\uc758 \uba4b\uc9c4 \ubaa8\uc591\ubd80\ud130 \ubcf4\uc778\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \ubaa8\uc2b5\uc744 \uac00\ub2a5\ud558\uac8c \ud55c \ubcc0\ud654\uac00 \uc544\uc8fc \uc791\uc740 \ubd80\ud488\uc5d0 \ub4e4\uc5b4 \uc788\ub294 \uacbd\uc6b0\ub3c4 \uc788\ub2e4. \ubc14\ud034\ub294 \ub208\uc5d0 \uc798 \ub744\uba74\uc11c\ub3c4 \ub108\ubb34 \uc775\uc219\ud574\uc838 \ucd9c\ubc1c\uc810\uc744 \uc78a\uae30 \uc26c\uc6b4 \ubd80\ud488\uc774\ub2e4. \ub808\uace0\uc758 \uc5f0\ud601\uc744 \uc77d\uace0 \ub098\uba74 \ubc14\ud034\ub97c \ub2e8\uc21c\ud788 \ub3d9\uadf8\ub780 \uc7a5\uc2dd\uc73c\ub85c \ubcf4\uae30\ub294 \uc5b4\ub835\ub2e4. \uc798 \ub3cc\uc544\uac00\uba74\uc11c\ub3c4 \ub2e4\ub978 \ubd80\ud488\uacfc \ud568\uaed8 \uc791\ub3d9\ud574\uc57c \ud588\ub358, \uc791\uc740 \uc124\uacc4 \ubb38\uc81c\uc758 \ub2f5\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \ube14\ub85d \uc790\ub3d9\ucc28\ub97c \uad74\ub824 \ubcf4\uac8c \ub41c\ub2e4\uba74 \ucc28\uccb4 \uc544\ub798\ub3c4 \ud55c\ubc88 \ubcf4\uc790. \uc791\uc740 \uac80\uc740 \ubc14\ud034\uac00 \ubd99\uc740 \uc790\ub9ac\uc5d0\uc11c, \uc313\ub294 \ub180\uc774\ub294 \uc6c0\uc9c1\uc774\ub294 \ub180\uc774\ub85c \ud55c \uac78\uc74c \ub354 \ub098\uc544\uac14\ub2e4."}, {"id": "lock-green-knot", "title": "\uc61b \uc5f4\uc1e0\uc5d0\ub3c4 \ucd08\ub85d\uc0c9 \ub9e4\ub4ed\uc774 \ub2ec\ub824 \uc788\uc5c8\ub2e4", "summary": "\uaf43\ubb34\ub2ac \uc790\ubb3c\uc1e0\uc640 \ub179\uc0c9 \ub9e4\ub4ed\uc774 \ub2ec\ub9b0 \uc5f4\uc1e0\ub97c \ud568\uaed8 \ubd05\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\uc9d1\uacfc \uc0dd\ud65c \ub3c4\uad6c", "categories": ["everyday-inventions"], "url": "stories/lock-green-knot/index.html", "image": "../media/lock-green-knot.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc790\ubb3c\uc1e0, \uc5f4\uc1e0 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc61b \uc5f4\uc1e0\uc5d0\ub3c4 \ucd08\ub85d\uc0c9 \ub9e4\ub4ed\uc774 \ub2ec\ub824 \uc788\uc5c8\ub2e4 \uc7a0\uadf8\ub294 \ubb3c\uac74\uc5d0\ub3c4 \uafb8\ubc08\uc740 \ub0a8\uc558\ub2e4 \uaf43\ubb34\ub2ac \uc790\ubb3c\uc1e0\uc640 \ub179\uc0c9 \ub9e4\ub4ed\uc774 \ub2ec\ub9b0 \uc5f4\uc1e0\ub97c \ud568\uaed8 \ubd05\ub2c8\ub2e4. \uc9d1\uacfc \uc0dd\ud65c \ub3c4\uad6c \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \uc5f4\uc1e0\ub97c \ucc3e\ub290\ub77c \uac00\ubc29 \uc548\uc744 \ub4a4\uc801\uc778 \uacbd\ud5d8\uc774 \uc788\ub2e4\uba74, \uc5f4\uc1e0\uace0\ub9ac \ud558\ub098\uc5d0\ub3c4 \ucde8\ud5a5\uc774 \ub4e4\uc5b4\uac04\ub2e4\ub294 \ub9d0\uc744 \uc774\ud574\ud560 \uac83\uc774\ub2e4. \uc798 \ubcf4\uc774\ub294 \uc0c9\uc744 \uace0\ub974\uae30\ub3c4 \ud558\uace0, \ub9c8\uc74c\uc5d0 \ub4dc\ub294 \uc791\uc740 \uc7a5\uc2dd\uc744 \ub2ec\uae30\ub3c4 \ud55c\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \uc61b \uc790\ubb3c\uc1e0\uc640 \uc5f4\uc1e0\ub97c \ubcf4\uba74 \uadf8\ub7f0 \uc624\ub298\uc758 \uc2b5\uad00\uc774 \ubb38\ub4dd \ub5a0\uc624\ub978\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc5d0 \ub530\ub974\uba74 \uc5f4\uc1e0 \ub05d\uc5d0\ub294 \ub179\uc0c9 \ub9e4\ub4ed\uc774 \ub2ec\ub824 \uc788\ub2e4. \uc791\uc740 \uc7a0\uae08 \ub3c4\uad6c\uc5d0\ub3c4 \uc0c9\uc744 \ubcf4\ud0e0 \uac83\uc774\ub2e4. \uc774 \ud55c \uc30d\uc740 \uc601\uce5c\uc655\ube44\uc758 \uc720\ud488\uc73c\ub85c \uc804\ud574\uc9c0\ub294 \ubb3c\uac74\uc774\ub2e4. \uc5ec\uae30\uc11c \ub208\uc5ec\uaca8\ubcfc \ub9d0\uc740 \u2018\uc804\ud574\uc9c0\ub294\u2019\uc774\ub2e4. \ub204\uac00 \uc5b8\uc81c \uc5b4\ub290 \uc0c1\uc790\ub97c \uc7a0\uac14\ub294\uc9c0\uae4c\uc9c0 \ud655\uc815\ub41c \uc7a5\uba74\uc73c\ub85c \ubc14\uafb8\uc5b4 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud655\uc778\ub418\ub294 \uac83\uc740 \ud45c\uba74\uc758 \uc7a5\uc2dd\uc774\ub2e4. \uc790\ubb3c\uc1e0 \uc55e\uba74\uc5d0\ub294 \ub465\uadfc \ubb34\ub2ac\uc640 \uaf43\ubb34\ub2ac\uac00 \uc74c\uac01\ub418\uc5b4 \uc788\ub2e4. \uc74c\uac01\uc740 \ubc14\ud0d5\uc744 \ud30c\uc11c \uc120\uc774\ub098 \ubb34\ub2ac\ub97c \ub098\ud0c0\ub0b4\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc791\uc544\uc11c \uadf8\ub0e5 \uc9c0\ub098\uce60 \ubb3c\uac74\uc5d0\ub3c4 \ube48 \ud45c\uba74\uc744 \uadf8\ub300\ub85c \ub450\uc9c0 \uc54a\uc558\ub2e4. \uc5f4\uc1e0 \ub05d\uc758 \ub9e4\ub4ed\uc740 \uc790\ubb3c\uc1e0\uc758 \uc0c8\uae34 \ubb34\ub2ac\uc640 \ub2e4\ub978 \ubc29\ubc95\uc73c\ub85c \ubb3c\uac74\uc744 \uafb8\ubbfc\ub2e4. \ub2e8\ub2e8\ud55c \uae08\uc18d\uc5d0\ub294 \ud30c\uc778 \uc120\uc774, \ub05d\ubd80\ubd84\uc5d0\ub294 \ub179\uc0c9 \ub9e4\ub4ed\uc774 \ubd99\ub294\ub2e4. \ud55c \uc870\ub97c \uc774\ub8e8\uba74\uc11c\ub3c4 \uc7ac\ub8cc\uc758 \ub290\ub08c\uc740 \ub2e4\ub974\ub2e4. \ub9e4\ub4ed\uc774 \uc190\uc5d0 \uc7a1\uae30 \ud3b8\ud588\uc744\uc9c0, \uba40\ub9ac\uc11c \ucc3e\uae30 \uc26c\uc6e0\uc744\uc9c0 \uc0c1\uc0c1\ud574 \ubcfc \uc218\ub294 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ubc15\ubb3c\uad00 \uc124\uba85\uc740 \uadf8 \ubaa9\uc801\uae4c\uc9c0 \uc815\ud574 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc624\ub298\uc758 \uc5f4\uc1e0\uace0\ub9ac\uc640 \ub2ee\uc558\ub2e4\ub294 \uc0dd\uac01\uc740 \uc6b0\ub9ac\uc758 \ube44\uad50\ub85c \ub0a8\uaca8 \ub450\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc790\ubb3c\uc1e0\uc640 \uc5f4\uc1e0\ub294 \uc11c\ub85c \ub2e4\ub978 \uc5ed\ud560\uc744 \ub9e1\uc9c0\ub9cc \ud55c \uc870\ub85c \uc774\ud574\ub41c\ub2e4. \uc5f4\uc1e0\ub9cc \ub0a8\uc544 \uc788\uc73c\uba74 \ubb34\uc5c7\uc744 \uc5f4\uc5c8\ub294\uc9c0 \uad81\uae08\ud558\uace0, \uc790\ubb3c\uc1e0\ub9cc \uc788\uc73c\uba74 \uc5b4\ub5bb\uac8c \uc5f4\uc5c8\ub294\uc9c0 \ubb3b\uac8c \ub41c\ub2e4. \ud568\uaed8 \uc18c\uac1c\ub41c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uadf8 \uad00\uacc4\ub97c \ubcfc \uc218 \uc788\uac8c \ud55c\ub2e4. \ub2e4\ub9cc \uc774 \uc0ac\uc9c4\uc73c\ub85c \ub0b4\ubd80 \uad6c\uc870\uc758 \ubaa8\ub4e0 \uc791\ub3d9\uc744 \ud655\uc778\ud558\uac70\ub098 \uc815\ud655\ud55c \uac1c\ud3d0 \uc808\ucc28\ub97c \uc7ac\ud604\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uba3c\uc800 \ub450 \ubb3c\uac74\uc774 \uac01\uac01 \uc5b4\ub5a4 \ud615\ud0dc\uc778\uc9c0 \uc0b4\ud3b4\ubcf4\uace0 \uc774\ud6c4 \ud45c\uba74\uc758 \uc7a5\uc2dd\uc73c\ub85c \uc2dc\uc120\uc744 \uc62e\uaca8 \ubcf4\uc790. \uae08\uc18d\uc758 \ub369\uc5b4\ub9ac\uc640 \uc5f4\uc1e0 \ub05d\uc758 \ubd80\ub4dc\ub7ec\uc6b4 \ub9e4\ub4ed\uc740 \ub208\uc5d0 \ub2e4\ub978 \uc778\uc0c1\uc744 \uc900\ub2e4. \uae30\ub2a5\uc774 \ub2e4\ub978 \ubd80\ud488\ub4e4\uc774 \ud55c \ubb36\uc74c\uc73c\ub85c \uc0ac\uc6a9\ub420 \uc218 \uc788\ub2e4\ub294 \uc810\uacfc, \uadf8 \uac01\uac01\uc5d0 \uafb8\ubc08\uc758 \uc790\ub9ac\uac00 \uc788\uc5c8\ub2e4\ub294 \uc810\uc744 \ud568\uaed8 \ubcfc \uc218 \uc788\ub2e4. \uc74c\uac01\ud55c \ub465\uadfc \ubb34\ub2ac\uc640 \uaf43\ubb34\ub2ac\ub294 \ubc14\ud0d5\uc744 \ud30c\uc11c \ub9cc\ub4e0\ub2e4. \uc885\uc774\uc5d0 \uadf8\ub9b0 \uc120\uacfc \ub2ec\ub9ac \uc2e4\uc81c \ud45c\uba74\uc758 \ub192\ub0ae\uc774\uac00 \uc0dd\uae34\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uc870\uba85\uacfc \ubc29\ud5a5\uc5d0 \ub530\ub77c \uc120\uc774 \ub354 \uc120\uba85\ud558\uac70\ub098 \ud76c\ubbf8\ud558\uac8c \ubcf4\uc77c \uc218 \uc788\ub294 \uc774\uc720\ub3c4 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc7a5\uc2dd\uc758 \uc774\ub984\uc744 \uc54c\uace0 \ub098\uba74 \ub2e8\uc21c\ud788 \ubc18\uc9dd\uc774\ub294 \uae08\uc18d\uc774\ub77c\uace0 \uc9c0\ub098\uce58\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uadf8\ub807\uc9c0\ub9cc \uc0ac\uc9c4\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uac00\uacf5 \ub3c4\uad6c\uc640 \uc81c\uc791\uc790\uc758 \uc190\uc744 \ud2b9\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uae30\uad00\uc774 \uc124\uba85\ud55c \uae30\ubc95\uacfc \uc2e4\uc81c\ub85c \ubcf4\uc774\ub294 \uc120\uc744 \ud568\uaed8 \uc77d\ub294 \uac83\uc774 \uba3c\uc800\ub2e4. \uc791\uc740 \ubb3c\uac74\uc758 \ud45c\uba74\uc5d0 \ubb34\ub2ac\ub97c \ub123\uc5c8\ub2e4\ub294 \uc120\ud0dd\uc740 \uc7a0\uadf8\ub294 \uae30\ub2a5 \uc678\uc5d0\ub3c4 \ubcf4\ub294 \uc990\uac70\uc6c0\uc744 \uace0\ub824\ud588\uc74c\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uc4f0\uc774\ub294 \ubb3c\uac74\uc758 \uc544\ub984\ub2e4\uc6c0\uc740 \ud06c\uae30\uc640 \ube44\ub840\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub179\uc0c9 \ub9e4\ub4ed\uc740 \uae08\uc18d\uacfc \ub2e4\ub978 \uc0c9\uacfc \uc9c8\uac10\uc744 \ub354\ud55c\ub2e4. \uc190\uc73c\ub85c \uc7a1\uac70\ub098 \ubb3c\uac74\uc744 \ucc3e\uc744 \ub54c \uc5b4\ub5a4 \ub3c4\uc6c0\uc774 \ub418\uc5c8\uc744\uc9c0 \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\uc9c0\ub9cc, \uadf8\uac83\uc774 \uc81c\uc791\uc758 \ud655\uc778\ub41c \uc774\uc720\ub77c\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc624\ub298\uc758 \uc5f4\uc1e0\uace0\ub9ac\ub97c \ub5a0\uc62c\ub9ac\ub294 \uac83\uc740 \uac10\uc0c1\uc744 \ub3d5\ub294 \ube44\uad50\ub2e4. \uc61b \uc0ac\uc6a9\uc790\uc758 \uc124\uba85\uc744 \uc2e4\uc81c\ub85c \ub4e4\uc740 \uac83\ucc98\ub7fc \uc4f0\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \uc774 \uad6c\ubd84\uc744 \uc54c\uba74 \uc0c1\uc0c1\ud558\ub294 \uc990\uac70\uc6c0\uc744 \uc5c6\uc568 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ubb34\uc5c7\uc774 \uc790\ub8cc\uc758 \uc124\uba85\uc774\uace0 \ubb34\uc5c7\uc774 \uc9c0\uae08 \uad00\ub78c\uc790\uc758 \uc0dd\uac01\uc778\uc9c0 \ub098\ub204\uc5b4 \ub450\uba74 \ub41c\ub2e4. \ub9e4\ub4ed\uc758 \uc0c9\uc744 \uc54c\uc544\ubcf4\uace0 \ud45c\uba74\uc758 \ubb38\uc591\uacfc \ub098\ub780\ud788 \ubcf4\ub294 \uac83\ub9cc\uc73c\ub85c \ud55c \uc870\uc758 \uad6c\uc131\uc774 \ub354 \uc120\uba85\ud574\uc9c4\ub2e4. \uae30\ub2a5\uc744 \ub9e1\ub294 \ub2e8\ub2e8\ud55c \uae08\uc18d\uacfc \uc190\uc744 \uac70\uce5c \ub048\uc774 \uc11c\ub85c \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ud45c\uc815\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \uc601\uce5c\uc655\ube44\uc758 \uc720\ud488\uc73c\ub85c \uc804\ud574\uc9c4\ub2e4\ub294 \uc124\uba85\uc740 \ub204\uac00 \uc5b8\uc81c \uc7a0\uac14\ub2e4\ub294 \uc774\uc57c\uae30\uc640 \ub2e4\ub974\ub2e4. \uc5b4\ub5a4 \uad00\uacc4\ub85c \uc54c\ub824\uc838 \uc654\ub294\uc9c0 \ud45c\uc2dc\ud55c \ub9d0\uc774\ub2e4. \uc624\ub798\ub41c \ubb3c\uac74\uc744 \uc18c\uac1c\ud560 \ub54c \uc774 \ud45c\ud604\uc744 \uc720\uc9c0\ud558\ub294 \uac83\uc740 \ubd88\ud544\uc694\ud55c \ub9dd\uc124\uc784\ubcf4\ub2e4 \uc790\ub8cc\uc758 \uc815\ud655\uc131\uc744 \uc9c0\ud0a4\ub294 \uc77c\uc5d0 \uac00\uae5d\ub2e4. \ud655\uc2e4\ud55c \ud45c\uba74\uacfc \uc54c\ub824\uc9c4 \uc774\ub825\uc758 \uc815\ub3c4\ub97c \ud568\uaed8 \ubcf4\ub294 \uac83\uc774\ub2e4. \ub204\uad70\uac00\uc758 \ube44\ubc00 \uc0c1\uc790\ub098 \uadf9\uc801\uc778 \uc0ac\uac74\uc744 \uc0c8\ub85c \ub9cc\ub4e4\uc5b4\uc57c\ub9cc \uc790\ubb3c\uc1e0\uac00 \ud765\ubbf8\ub85c\uc6cc\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5f4\uc1e0 \ub05d\uc5d0 \ub9e4\ub4ed\uc744 \ub354\ud558\uace0 \uc791\uc740 \uba74\uc5d0 \uaf43\uc744 \uc0c8\uae34 \ubb3c\uac74\uc740 \uadf8 \uc790\uccb4\ub85c \uc0dd\ud65c\uc758 \uc120\ud0dd\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ubb34\uc5c7\uc744 \uc7a0\uac14\ub294\uc9c0 \ubaa8\ub974\ub294 \ube48\uce78\uc744 \ub0a8\uae30\uba74\uc11c\ub3c4, \uc0ac\ub78c\ub4e4\uc774 \uc7a0\uadf8\uace0 \ubcf4\uad00\ud558\ub294 \ub3c4\uad6c\ub97c \uc5b4\ub5bb\uac8c \uafb8\uba84\ub294\uc9c0\ub294 \ucc9c\ucc9c\ud788 \uc77d\uc744 \uc218 \uc788\ub2e4. \uc0c1\uc790\ub97c \uc5f4\uc5b4 \uc548\uc758 \ubcf4\ubb3c\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc774\uc57c\uae30\ub294 \uc544\ub2c8\ub2e4. \uc774 \uc790\ubb3c\uc1e0\uac00 \uc9c0\ud0a4\ub358 \ubb3c\uac74\uc740 \ud655\uc778\ud558\uc9c0 \ubabb\ud588\ub2e4. \ub300\uc2e0 \uc7a0\uadf8\ub294 \ub3c4\uad6c \uc790\uccb4\uc5d0\ub3c4 \ubcf4\ub294 \uc990\uac70\uc6c0\uc774 \uc788\uc5c8\ub2e4\ub294 \uac83\uc744 \ud45c\uba74\uacfc \ub9e4\ub4ed\uc5d0\uc11c \ubc1c\uacac\ud55c\ub2e4. \uc0ac\uc9c4\uc744 \ub2e4\uc2dc \ubcf4\uba74 \ucee4\ub2e4\ub780 \uc7a5\uc2dd\ubcf4\ub2e4 \uc791\uc740 \uc120\uc774 \uba3c\uc800 \ub208\uc5d0 \ub4e4\uc5b4\uc62c \uc218 \uc788\ub2e4. \uadf8 \uc606\uc5d0 \ub193\uc600\uc744 \uc5f4\uc1e0\uc758 \ucd08\ub85d\uc0c9\uae4c\uc9c0 \ub5a0\uc62c\ub9ac\uba74, \uc7a0\uae08\uc7a5\uce58\ub294 \uae30\ub2a5\ub9cc \ub0a8\uc740 \uae08\uc18d \ubd80\ud488\uc5d0\uc11c \uc870\uae08 \ub2e4\ub978 \uc5bc\uad74\uc744 \uc5bb\ub294\ub2e4. \uc61b \uc0dd\ud65c\uc758 \ucde8\ud5a5\uc740 \uc774\ub807\uac8c \uc791\uc740 \uacf3\uc5d0\ub3c4 \ub0a8\uc544 \uc788\ub2e4."}, {"id": "maehwa-portable-toilet", "title": "\uad81\uad90\uc758 \uc791\uc740 \uc0c1\uc790\uc5d0\ub294 \uc0dd\ud65c\uc758 \ud544\uc694\uac00 \ub2f4\uacbc\ub2e4", "summary": "\uc758\uc790\ucc98\ub7fc\ub3c4 \uc0c1\uc790\ucc98\ub7fc\ub3c4 \ubcf4\uc774\ub294 \ubb3c\uac74. \uc774\ub984\uacfc \uc4f0\uc784\uc744 \uc54c\uace0 \ub098\uba74 \uc61b \uc0dd\ud65c\uc758 \ub2e4\ub978 \uba74\uc774 \ubcf4\uc785\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\uc9d1\uacfc \uc0dd\ud65c \ub3c4\uad6c", "categories": ["everyday-inventions"], "url": "stories/maehwa-portable-toilet/index.html", "image": "../media/maehwa-portable-toilet.jpg", "alt": "\uc9c1\ubb3c\ub85c \uc2fc \ub098\ubb34\ud2c0\uacfc \uc704\ucabd \uad6c\uba4d\uc774 \ubcf4\uc774\ub294 \uc655\uc2e4 \uc774\ub3d9\uc2dd \ubcc0\uae30 \ub9e4\ud654\ud2c0", "text": "\uad81\uad90\uc758 \uc791\uc740 \uc0c1\uc790\uc5d0\ub294 \uc0dd\ud65c\uc758 \ud544\uc694\uac00 \ub2f4\uacbc\ub2e4 \uc774\ub3d9\uc2dd \uc6a9\ubcc0\uae30 \ub9e4\ud654\ud2c0\uc758 \uad6c\uc870\ub97c \ub4e4\uc5ec\ub2e4\ubcf4\ub2e4 \uc758\uc790\ucc98\ub7fc\ub3c4 \uc0c1\uc790\ucc98\ub7fc\ub3c4 \ubcf4\uc774\ub294 \ubb3c\uac74. \uc774\ub984\uacfc \uc4f0\uc784\uc744 \uc54c\uace0 \ub098\uba74 \uc61b \uc0dd\ud65c\uc758 \ub2e4\ub978 \uba74\uc774 \ubcf4\uc785\ub2c8\ub2e4. \uc9d1\uacfc \uc0dd\ud65c \ub3c4\uad6c \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \uad81\uad90\uc758 \uc0dd\ud65c\uc744 \uc0c1\uc0c1\ud558\uba74 \ud070 \uce68\uc804\uacfc \ud654\ub824\ud55c \uac00\uad6c\ubd80\ud130 \ub5a0\uc624\ub974\uae30 \uc27d\ub2e4. \ud558\uc9c0\ub9cc \uc0dd\ud65c\uc744 \uac00\ub2a5\ud558\uac8c \ud558\ub294 \uac83\uc740 \uba4b\uc9c4 \ubb3c\uac74\ub9cc\uc774 \uc544\ub2c8\ub2e4. \ub9e4\uc77c \ud574\uacb0\ud574\uc57c \ud558\ub294 \uc791\uc740 \ud544\uc694\ub3c4 \uc788\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \u300c\ub9e4\ud654\ud2c0\u300d\uc740 \uadf8\ub7f0 \uba74\uc744 \ubcf4\uc5ec\uc900\ub2e4. \uc9c1\uc721\uba74\uccb4\uc758 \ub098\ubb34 \ubab8\uccb4\uc5d0 \ucc9c\uc744 \uc50c\uc6e0\uace0, \uc717\uba74\uc5d0\ub294 \uae34 \uad6c\uba4d\uc774 \ub098 \uc788\ub2e4. \ud06c\uc9c0 \uc54a\uc740 \uac00\uad6c\ucc98\ub7fc \ubcf4\uc774\ub294 \uc774 \ubb3c\uac74\uc740 \uc655\uc2e4 \uc804\uc6a9\uc758 \uc774\ub3d9\uc2dd \uc6a9\ubcc0\uae30\uc600\ub2e4. \uc774\ub984\ub9cc \ub4e3\uace0 \uaf43\uc744 \uc7a5\uc2dd\ud558\ub294 \ud2c0\uc744 \ub5a0\uc62c\ub838\ub2e4\uba74 \uc4f0\uc784\uc774 \uaf64 \ub2e4\ub974\uac8c \ub290\uaef4\uc9c8 \uac83\uc774\ub2e4. \uc774 \ub9e4\ud654\ud2c0\uc740 \ubc30\uc124\ubb3c\uc744 \ubc1b\ub294 \uc6a9\uae30\ub97c \ub123\uace0 \ube84 \uc218 \uc788\ub3c4\ub85d \uace0\uc548\ub418\uc5c8\ub2e4\uace0 \ud55c\ub2e4. \uc0ac\uc6a9\uc790\uac00 \uc549\ub294 \ubd80\ubd84\uacfc \uc548\ucabd\uc758 \uc6a9\uae30\ub97c \ub098\ub204\uc5b4 \uc0dd\uac01\ud55c \uad6c\uc870\ub2e4. \uc717\uba74\uc758 \uad6c\uba4d\ub9cc \uc788\ub294 \ub2e8\uc21c\ud55c \uc0c1\uc790\ub3c4 \uc544\ub2c8\ub2e4. \uc544\ub798 \uc591\uc606\uc5d0\ub294 \ubc1c\ud310\uc774 \ub9c8\ub828\ub418\uc5b4 \uc788\uace0, \uc88c\ub300 \uc717\ubd80\ubd84\uc5d0\ub294 \ub4f1\ubc1b\uce68\uc744 \uace0\uc815\ud558\uae30 \uc704\ud55c \ud648\ub3c4 \ub0a8\uc544 \uc788\ub2e4. \uc124\uba85\uc744 \uc77d\uc73c\uba70 \uc0ac\uc9c4\uc744 \ub2e4\uc2dc \ubcf4\uba74 \uae30\ub2a5\uc5d0 \ud544\uc694\ud55c \ubd80\ubd84\ub4e4\uc774 \ud558\ub098\uc529 \ubcf4\uc778\ub2e4. \uc6c0\uc9c1\uc77c \uc218 \uc788\ub2e4\ub294 \uc810\ub3c4 \uc774 \ubb3c\uac74\uc758 \uc131\uaca9\uc744 \uc54c\ub824\uc900\ub2e4. \ubc29 \uc548\uc5d0\uc11c \uc4f0\ub294 \uac00\uad6c\ucc98\ub7fc \uc0ac\uc6a9\ud558\uba74\uc11c, \uc548\ucabd \uc6a9\uae30\ub97c \ub2e4\ub8e8\uace0 \ud544\uc694\uc5d0 \ub530\ub77c \uc704\uce58\ub97c \uc62e\uae38 \uc218 \uc788\ub294 \ubc29\uc2dd\uc774\uc5c8\ub2e4. \uc624\ub298\uc758 \ubc30\uad00 \uc2dc\uc124\uacfc\ub294 \ub2e4\ub978 \ubc29\ubc95\uc73c\ub85c \uc0dd\ud65c\uc758 \ubb38\uc81c\ub97c \ud574\uacb0\ud55c \uac83\uc774\ub2e4. \ubc15\ubb3c\uad00\uc5d0\ub294 \uac19\uc740 \ub9e4\ud654\ud2c0\uc774\ub77c\ub294 \uc774\ub984\uc758 \uccad\ub3d9\uc81c \uc774\ub3d9\uc2dd \uc6a9\ubcc0\uae30\ub3c4 \uc788\ub2e4. \uc124\uba85\uc5d0\ub294 \ub0b4\ubd80\uc5d0 \uc7ac\ub97c \ub2f4\uc544 \uc18c\ub9ac\uc640 \ub0c4\uc0c8\ub97c \uc904\uc774\ub824 \ud588\ub2e4\uace0 \ub098\uc628\ub2e4. \ub450 \ubb3c\uac74\uc744 \ubcf4\uba74 \uc6a9\ubcc0\uc744 \ubc1b\ub294 \uae30\ub2a5\ubfd0 \uc544\ub2c8\ub77c \uc0ac\uc6a9 \ub4a4\uc758 \ucc98\ub9ac, \uc8fc\ubcc0\uc5d0 \uc8fc\ub294 \uc601\ud5a5\uc744 \uc0dd\uac01\ud588\ub2e4\ub294 \uac83\uc744 \uc54c \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ud55c \uc720\ubb3c\uc758 \uc124\uba85\uc744 \ubaa8\ub4e0 \uc655\uc2e4 \uc6a9\ubcc0\uae30\uc5d0 \ub611\uac19\uc774 \uc801\uc6a9\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc7ac\ub8cc\uc640 \uad6c\uc870\uac00 \ub2e4\ub978 \ubb3c\uac74\uc740 \uac01\uac01\uc758 \uae30\ub85d\uc744 \ub530\ub77c \ubcf4\uc544\uc57c \ud55c\ub2e4. \ub204\uac00 \uc5b8\uc81c \uc5b4\ub290 \ubc29\uc5d0\uc11c \uc37c\ub294\uc9c0, \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5a4 \ub9d0\uc744 \ud588\ub294\uc9c0\ub294 \uc5ec\uae30\uc758 \uc18c\uc7a5\ud488 \uc124\uba85\ub9cc\uc73c\ub85c \uc54c \uc218 \uc5c6\ub2e4. \uadf8\ub7f0 \uc7a5\uba74\uc744 \ub367\ubd99\uc774\uc9c0 \uc54a\uc544\ub3c4 \ub0a8\uc544 \uc788\ub294 \uad6c\uc870\ub9cc\uc73c\ub85c \uc0dd\ud65c\uc758 \uace0\ubbfc\uc744 \uc9d0\uc791\ud560 \uc218 \uc788\ub2e4. \uad81\uad90\uc744 \ud070 \uc758\uc2dd\uacfc \ud654\ub824\ud55c \uc637\uc758 \uc7a5\uc18c\ub85c\ub9cc \ubcf4\uba74 \uc77c\uc0c1\uc801\uc778 \ubab8\uc758 \ud65c\ub3d9\uc740 \uc798 \ub5a0\uc624\ub974\uc9c0 \uc54a\ub294\ub2e4. \uc774\ub3d9\uc2dd \uc6a9\ubcc0\uae30\ub294 \uadf8\ub7f0 \ube48\uc790\ub9ac\ub97c \ubcf4\uc5ec \uc900\ub2e4. \ub204\uad70\uac00 \uc549\uace0 \uc77c\uc5b4\ub098\uba70 \ub0b4\ubd80 \uc6a9\uae30\ub97c \ub2e4\ub8e8\uc5b4\uc57c \ud588\ub358 \ubb3c\uac74\uc774\ub2e4. \ud2b9\ubcc4\ud55c \uc2e0\ubd84\uc758 \uc0dd\ud65c\uc5d0\ub3c4 \ubc18\ubcf5\ud574\uc11c \ud574\uacb0\ud574\uc57c \ud558\ub294 \ud3c9\ubc94\ud55c \ud544\uc694\uac00 \uc788\uc5c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub204\uac00 \uc0ac\uc6a9\ud588\ub294\uc9c0 \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \uc720\ubb3c\uc5d0 \ud2b9\uc815 \uc655\uc758 \ube44\ubc00 \uc77c\ud654\ub97c \ub367\ubd99\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774\ub984\ub09c \uc778\ubb3c\uc774 \ub4f1\uc7a5\ud558\uc9c0 \uc54a\uc544\ub3c4 \ud615\ud0dc \uc790\uccb4\uac00 \ub9d0\ud574 \uc8fc\ub294 \uc0dd\ud65c\uc740 \ucda9\ubd84\ud788 \ud765\ubbf8\ub86d\ub2e4. \ubc1c\uc744 \ub450\ub294 \ubd80\ubd84\uacfc \ub4f1\ubc1b\uce68\uc758 \ud648\uc774 \uc788\ub2e4\ub294 \uc124\uba85\ub9cc\uc73c\ub85c\ub3c4, \ub2e8\uc21c\ud788 \ubb3c\uc9c8\uc744 \ub2f4\ub294 \ud1b5\uc774 \uc544\ub2c8\ub77c \uc0ac\ub78c\uc758 \uc790\uc138\ub97c \uc0dd\uac01\ud55c \ubb3c\uac74\uc784\uc744 \uc54c \uc218 \uc788\ub2e4. \uc549\ub294 \uad6c\uc870\uc640 \ubc30\uc124\ubb3c\uc744 \ubc1b\ub294 \uc6a9\uae30\uac00 \ubd84\ub9ac\ub41c\ub2e4\ub294 \uc810\uc740 \uc0ac\uc6a9\uacfc \ucc98\ub9ac\uc758 \uc2dc\uac04\uc744 \ub098\ub204\uc5b4 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ud558\ub098\uc758 \uc0c1\uc790 \uc804\uccb4\ub97c \ub9e4\ubc88 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ub2e4\ub8f0 \ud544\uc694\uac00 \uc5c6\ub3c4\ub85d \ubd80\ud488\uc744 \ub098\ub208 \ud615\ud0dc\ub2e4. \ub2e4\ub9cc \ub2f9\uc2dc\uc758 \uc815\ud655\ud55c \ucc98\ub9ac \uc808\ucc28\uc640 \ub2f4\ub2f9\uc790\uc758 \uc5ed\ud560\uc740 \uc18c\uc7a5\ud488 \uc124\uba85\ub9cc\uc73c\ub85c \uc7ac\ud604\ud560 \uc218 \uc5c6\ub2e4. \uae30\ub2a5\uc758 \uad6c\ubd84\uc744 \uba3c\uc800 \ubcf4\ub294 \uac83\uc774\ub2e4. \ubab8\uc744 \ubc1b\uce58\ub294 \ubd80\ubd84\uc5d0\ub294 \uc9c1\ubb3c\ub85c \uc2fc \ub098\ubb34\ud2c0\uc774 \uc788\uace0 \uc548\ucabd\uc5d0 \uc6a9\uae30\ub97c \ub123\ub294\ub2e4. \uc7ac\ub8cc\uac00 \ub2e4\ub974\uba74 \ub9e1\ub294 \uc790\ub9ac\ub3c4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uc804\uccb4\uac00 \uac19\uc740 \ube5b\uae54\ub85c \ubcf4\uc774\ub354\ub77c\ub3c4 \uad6c\uc131\uc740 \ud55c \ub369\uc5b4\ub9ac\ubcf4\ub2e4 \ubcf5\uc7a1\ud558\ub2e4. \uac74\ucd95\uc758 \ubc29 \uc548\uc5d0\uc11c \uc4f0\ub294 \uc791\uc740 \ubb3c\uac74\uc5d0\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc7ac\ub8cc\uc640 \ud589\ub3d9\uc744 \uc774\uc5b4 \uc8fc\ub294 \uc124\uacc4\uac00 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \ubc30\uad00\uacfc \uace0\uc815\ub41c \uc124\ube44\ub97c \ub5a0\uc62c\ub9ac\uba74 \uc6a9\ubcc0\uc744 \ubcf4\ub294 \uc7a5\uc18c\uac00 \uac74\ubb3c \uc548\uc758 \ud55c \uc704\uce58\uc5d0 \ubb36\uc778\ub2e4. \uc774\ub3d9\uc2dd \ub3c4\uad6c\ub294 \uadf8\uc640 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uc0dd\ud65c\uc758 \ubb38\uc81c\ub97c \ub2e4\ub8ec\ub2e4. \ud544\uc694\ud560 \ub54c \uc7a5\uc18c\ub97c \uc815\ud558\uace0 \ubd80\uc18d \uc6a9\uae30\ub97c \uad00\ub9ac\ud574\uc57c \ud55c\ub2e4\ub294 \uc810\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc774\ub3d9\uc2dd\uc774\ub77c\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc5b8\uc81c\ub098 \uc5ec\ud589 \uc911\uc5d0 \uc0ac\uc6a9\ud55c \ubb3c\uac74\uc774\ub77c\uace0 \ub2e8\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uacfc\uac70\uc758 \ub3c4\uad6c\ub97c \uc9c0\uae08\ubcf4\ub2e4 \ubd88\ud3b8\ud55c \ub2e8\uacc4\ub85c\ub9cc \uc815\ub9ac\ud558\uba74 \ub2f9\uc2dc \ubb34\uc5c7\uc744 \ud574\uacb0\ud558\ub824 \ud588\ub294\uc9c0 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ubc18\ub300\ub85c \uc655\uc2e4 \ubb3c\uac74\uc774\ub77c\uace0 \ubaa8\ub4e0 \uc810\uc5d0\uc11c \uc644\ubcbd\ud55c \ubc29\ubc95\uc774\uc5c8\ub2e4\uace0 \ubcfc \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ud655\uc778\ub41c \uad6c\uc870\uc640 \uadf8 \uc548\uc5d0\uc11c \uac00\ub2a5\ud588\ub358 \ud589\ub3d9\uc744 \uc77d\ub294 \ud3b8\uc774 \uc88b\ub2e4. \ubb3c\uac74\uc744 \ube44\uad50\ud558\ub294 \ubaa9\uc801\uc740 \uc21c\uc704\ub97c \ub9e4\uae30\uae30\ubcf4\ub2e4 \uc11c\ub85c \ub2e4\ub978 \uc0dd\ud65c \uc870\uac74\uc744 \uc774\ud574\ud558\ub294 \ub370 \uc788\ub2e4. \uccad\ub3d9\uc81c \uc6a9\ubcc0\uae30\uc758 \uc124\uba85\uc5d0 \ub4f1\uc7a5\ud558\ub294 \uc7ac\ub294 \ub2e8\uc21c\ud788 \ub2f4\uae34 \ub0b4\uc6a9\ubb3c\uc758 \uc815\ubcf4\uac00 \uc544\ub2c8\ub2e4. \uc8fc\ubcc0\uc5d0 \ubbf8\uce58\ub294 \uc18c\ub9ac\uc640 \ub0c4\uc0c8\uae4c\uc9c0 \uc2e0\uacbd \uc37c\ub2e4\ub294 \uae30\ub2a5 \uc124\uba85\uc774\ub2e4. \ubab8\uc758 \ud65c\ub3d9\uc744 \ubc1b\ub294 \ub3c4\uad6c\uac00 \uc0ac\ub78c\uacfc \uacf5\uac04\uc758 \uad00\uacc4\ub3c4 \ub2e4\ub8e8\uc5c8\ub2e4\ub294 \uc810\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub2e4\ub9cc \ubaa9\uc81c \ud2c0\uc758 \uc720\ubb3c\uacfc \uae08\uc18d \uc6a9\uae30\ub97c \uac19\uc740 \uc0c1\ud0dc\ub85c \ubaa8\ub450 \ubb36\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc18c\uc7a5\ud488\uc758 \uc124\uba85\uc740 \uac01 \ubb3c\uac74\uc758 \ud2b9\uc9d5\uc744 \ube44\uad50\ud558\uac8c \ud55c\ub2e4. \ud558\ub098\uc5d0\uc11c \uc77d\uc740 \ub0b4\uc6a9\uc744 \ub2e4\ub978 \ubb3c\uac74\uc758 \ud655\uc778\ub41c \uc0ac\uc2e4\ub85c \uc62e\uaca8 \uc4f0\uc9c0 \uc54a\uc73c\uba74 \ucc28\uc774\uac00 \ub0a8\ub294\ub2e4. \uc0c1\uc790\uc758 \ud615\ud0dc\ub97c \ub530\ub77c\uac00\uba70 \uc0ac\ub78c\uc774 \uc549\ub294 \uc790\ub9ac\uc640 \uc548\ucabd\uc758 \ubd84\ub9ac \uad6c\uc870\ub97c \ub098\ub204\uc5b4 \ubcf4\uc790. \ud070 \uad81\uad90\uc758 \ud48d\uacbd\uc5d0\uc11c \uc798 \ub4dc\ub7ec\ub098\uc9c0 \uc54a\ub358 \uc0dd\ud65c\uc758 \uc791\uc740 \uae30\uc220\uc774 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uad81\uad90\uc744 \uad6c\uacbd\ud560 \ub54c\ub294 \uacf5\uac04\uc774 \uc6cc\ub099 \ucee4\uc11c \uadf8 \uc548\uc5d0\uc11c \uc2e4\uc81c\ub85c \uc5b4\ub5bb\uac8c \uc9c0\ub0c8\ub294\uc9c0 \ub193\uce58\uae30 \uc27d\ub2e4. \uc791\uc740 \uc0dd\ud65c \ub3c4\uad6c\ub294 \uadf8 \uac70\ub9ac\ub97c \uc904\uc5ec \uc900\ub2e4. \uc5b4\ub518\uac00\uc5d0 \ub193\uace0 \uc0ac\ub78c\uc774 \uc0ac\uc6a9\ud574\uc57c \ud588\ub358 \ubb3c\uac74\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \ub9e4\ud654\ud2c0\uc744 \ubcf4\uba74\uc11c \uc61b\uc0ac\ub78c\ub4e4\uc758 \uc0dd\ud65c\uc744 \ubd88\ud3b8\ud568 \ud558\ub098\ub85c\ub9cc \ud3c9\uac00\ud560 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ub2f9\uc2dc\uc758 \uc7ac\ub8cc\uc640 \ubc29\uc2dd\uc73c\ub85c \ubb34\uc5c7\uc744 \ud574\uacb0\ud558\ub824 \ud588\ub294\uc9c0\ub97c \ubcf4\uba74 \ub41c\ub2e4. \ub123\uace0 \ube7c\ub294 \uc6a9\uae30, \ubc1c\ud310, \ub4f1\ubc1b\uce68\uc758 \ud754\uc801\uc740 \uadf8 \ub2f5\uc758 \uc77c\ubd80\ub2e4. \ub2e4\uc74c\uc5d0 \uc0dd\ud65c \uc720\ubb3c \uc804\uc2dc\ub97c \ub9cc\ub098\uba74 \ud654\ub824\ud55c \uc7a5\uc2dd \uc0ac\uc774\uc758 \uc18c\ubc15\ud55c \ubb3c\uac74\ub3c4 \uc0b4\ud3b4\ubcf4\uc790. \ud070 \uc5ed\uc0ac\uc758 \ubb34\ub300\uc600\ub358 \uad81\uad90\uc5d0\ub3c4, \ub9e4\uc77c\uc758 \uc0dd\ud65c\uc744 \ubc1b\uccd0 \uc8fc\ub294 \uc791\uc740 \uac00\uad6c\uac00 \ud544\uc694\ud588\ub2e4."}, {"id": "metal-flute-woodwind-family", "title": "\uae08\uc18d\uc73c\ub85c \ub9cc\ub4e0 \ud50c\ub8e8\ud2b8\ub294 \uc65c \ubaa9\uad00\uc545\uae30\uc77c\uae4c", "summary": "\uc740\ube5b \ud50c\ub8e8\ud2b8\uc640 \ubaa9\uad00\uc545\uae30\ub77c\ub294 \ubd84\ub958 \uc0ac\uc774\uc758 \uac04\uaca9\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\ub180\uc774\uc640 \ucde8\ubbf8", "categories": ["everyday-inventions"], "url": "stories/metal-flute-woodwind-family/index.html", "image": "../media/metal-flute-woodwind-family.jpg", "alt": "\uae08\uc18d\uc73c\ub85c \ub9cc\ub4e0 \ud50c\ub8e8\ud2b8\ub294 \uc65c \ubaa9\uad00\uc545\uae30\uc77c\uae4c\uc758 \ub0b4\uc6a9\uc744 \ub3d5\ub294 \uc124\uba85\uc6a9 \uc774\ubbf8\uc9c0", "text": "\uae08\uc18d\uc73c\ub85c \ub9cc\ub4e0 \ud50c\ub8e8\ud2b8\ub294 \uc65c \ubaa9\uad00\uc545\uae30\uc77c\uae4c \uc774\ub984 \uc18d \uc7ac\ub8cc\uc640 \uc9c0\uae08\uc758 \ubaa8\uc2b5\uc744 \ub098\ub204\uc5b4 \ubcf4\uae30 \uc740\ube5b \ud50c\ub8e8\ud2b8\uc640 \ubaa9\uad00\uc545\uae30\ub77c\ub294 \ubd84\ub958 \uc0ac\uc774\uc758 \uac04\uaca9\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ub180\uc774\uc640 \ucde8\ubbf8 \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \ubb34\ub300\uc758 \ud50c\ub8e8\ud2b8\ub294 \ubc18\uc9dd\uc774\ub294 \uae08\uc18d \uc545\uae30\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uadf8\ub7f0\ub370 \uc624\ucf00\uc2a4\ud2b8\ub77c\uc5d0\uc11c\ub294 \ubaa9\uad00\uc545\uae30\ub77c\uace0 \ubd80\ub978\ub2e4. \ub098\ubb34\ub97c \ub73b\ud558\ub294 \uc774\ub984\uacfc \ub208\uc55e\uc758 \uc7ac\ub8cc\uac00 \ub9de\uc9c0 \uc54a\ub294 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uc601\uad6d \ud544\ud558\ubaa8\ub2c8\uc544 \uc624\ucf00\uc2a4\ud2b8\ub77c\uc758 \uc548\ub0b4\ub294 \uc61b \ud50c\ub8e8\ud2b8\ub294 \ub098\ubb34\ub85c \ub9cc\ub4e4\uc5c8\uc9c0\ub9cc \ud604\ub300 \ud50c\ub8e8\ud2b8\uc758 \ub300\ubd80\ubd84\uc740 \uae08\uc18d\uc774\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \ubd84\ub958\uc758 \uc774\ub984\ub9cc \ubcf4\uace0 \uc9c0\uae08 \uc4f0\ub294 \uc545\uae30\uc758 \uc7ac\ub8cc\ub97c \uc815\ud558\uba74 \uc0dd\uae30\ub294 \uc791\uc740 \uc5b4\uae0b\ub0a8\uc774\ub2e4. \uc545\uae30\uc758 \uc774\ub984\uacfc \ubd84\ub958\uc5d0\ub294 \uc9c0\ub098\uc628 \uc2dc\uac04\uc774 \ub0a8\uc544 \uc788\ub2e4. \uc624\ub298\uc758 \ud50c\ub8e8\ud2b8\uac00 \uae08\uc18d\uc774\ub77c\uace0 \ud574\uc11c \ubaa9\uad00\uc545\uae30\ub77c\ub294 \uc774\ub984\uc744 \uc7ac\ub8cc \uac80\uc0ac\ud45c\ucc98\ub7fc \uc77d\uc744 \uc218\ub294 \uc5c6\ub294 \uac83\uc774\ub2e4. \ud544\ud558\ubaa8\ub2c8\uc544\ub294 \ud53c\ucf5c\ub85c\ub294 \uc9c0\uae08\ub3c4 \ub300\uccb4\ub85c \ub098\ubb34\ub85c \ub9cc\ub4e0\ub2e4\uace0 \ub367\ubd99\uc778\ub2e4. \uac00\uae4c\uc6b4 \uc545\uae30 \uac00\uc871 \uc548\uc5d0\uc11c\ub3c4 \uc7ac\ub8cc\uac00 \ubaa8\ub450 \uac19\uc9c0\ub294 \uc54a\ub2e4. \ubc18\uc9dd\uc774\ub294 \uac83\uacfc \uac80\uac8c \ubcf4\uc774\ub294 \uac83\uc744 \ud568\uaed8 \ubcfc \ub54c \uc774 \ucc28\uc774\ub97c \ub5a0\uc62c\ub824\ub3c4 \uc88b\uaca0\ub2e4. 19\uc138\uae30\uc5d0 \ud50c\ub8e8\ud2b8\uc758 \uc5f0\uc8fc \uae30\ubc95\uc774 \ud06c\uac8c \ubc1c\uc804\ud558\ub294 \ub370\uc5d0\ub294 \ud45c\uba74\uc758 \uae08\uc18d \ud0a4\uc640 \ud328\ub4dc \uccb4\uacc4\ub3c4 \uc911\uc694\ud588\ub2e4\uace0 \uc548\ub0b4\ub294 \uc124\uba85\ud55c\ub2e4. \uc190\uc774 \uc9c1\uc811 \ubaa8\ub4e0 \uad6c\uba4d\uc744 \ub9c9\ub294 \ubaa8\uc2b5\ub9cc \uc0c1\uc0c1\ud588\ub2e4\uba74 \uc791\uc740 \uc7a5\uce58\ub4e4\uc744 \ub2e4\uc2dc \ubcfc \uc774\uc720\uac00 \uc0dd\uae34\ub2e4. \uc774 \uc7a5\uce58\ub4e4\uc740 \ub354 \ubcf5\uc7a1\ud55c \uc74c\uc545\uc744 \uc5f0\uc8fc\ud560 \uc218 \uc788\ub3c4\ub85d \ub3c4\uc654\ub2e4. \uc545\uae30\ub97c \ub9cc\ub4dc\ub294 \uc77c\uc774 \uc7ac\ub8cc\ub97c \uace0\ub974\ub294 \ub370\uc5d0\uc11c \ub05d\ub098\uc9c0 \uc54a\uace0, \uc5f0\uc8fc\uc790\uc758 \uc190\uacfc \uc6d0\ud558\ub294 \uc18c\ub9ac \uc0ac\uc774\ub97c \uc5f0\uacb0\ud558\ub294 \uc77c\uc774\ub77c\ub294 \uc810\uc774 \ubcf4\uc778\ub2e4. \ubaa9\uad00\uc774\ub77c\ub294 \uc774\ub984\uc744 \uace7 \ub098\ubb34\ub85c \ub9cc\ub4e0 \ubaa8\ub4e0 \uc545\uae30\ub77c\ub294 \ub73b\uc73c\ub85c \uc77d\uc73c\uba74 \uae08\uc18d \ud50c\ub8e8\ud2b8\uac00 \uc608\uc678\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uadf8\ub7ec\ub098 \ubd84\ub958\uc5d0\ub294 \uc545\uae30\uac00 \uc774\uc5b4 \uc628 \uc5ed\uc0ac\uc640 \uc5f0\uc8fc \ubc29\uc2dd\uc774 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4. \ud604\uc7ac\uc758 \uc7ac\ub8cc\ub97c \ud55c \ubc88 \ud655\uc778\ud558\ub294 \uc77c\ub9cc\uc73c\ub85c \uadf8 \uc774\ub984\uc758 \ubaa8\ub4e0 \uc774\uc720\ub97c \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \ubb3c\uac74\uc758 \ubcc0\ud654\uac00 \ubd84\ub958\uc758 \ub9d0\ubcf4\ub2e4 \ube60\ub974\uac8c \ub290\uaef4\uc9c0\ub294 \uc0ac\ub840\ub2e4. \ube44\uc2b7\ud55c \uc77c\uc740 \uc77c\uc0c1\uc758 \uc5ec\ub7ec \uc774\ub984\uc5d0\uc11c\ub3c4 \ub9cc\ub09c\ub2e4. \ucc98\uc74c\uc758 \uc7ac\ub8cc\ub098 \ud615\ud0dc\uc5d0\uc11c \uc0dd\uae34 \ub9d0\uc774 \ubb3c\uac74\uc758 \ubcc0\ud654 \ub4a4\uc5d0\ub3c4 \ub0a8\uc744 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \uc545\uae30\uad70\uc744 \uc7ac\ub8cc\uc640 \ubb34\uad00\ud55c \uc784\uc758\uc758 \ubb36\uc74c\uc73c\ub85c \ubcf4\uc790\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \uacf5\uc2dd \uc548\ub0b4\uac00 \ud50c\ub8e8\ud2b8\ub97c \ubaa9\uad00\uc545\uae30\ub85c \uc18c\uac1c\ud558\uba74\uc11c \uacfc\uac70\uc758 \ubaa9\uc81c\uc640 \ud604\ub300\uc758 \uae08\uc18d\uc81c\ub97c \ud568\uaed8 \uc124\uba85\ud55c\ub2e4\ub294 \uc810\uc744 \ub530\ub77c\uac04\ub2e4. \ud50c\ub8e8\ud2b8\uc758 \ud45c\uba74\uc5d0\ub294 \uc5ec\ub7ec \ud0a4\uc640 \ud328\ub4dc\uac00 \ub193\uc5ec \uc788\ub2e4. \uc190\uac00\ub77d\uc744 \uc5b4\ub514\uc5d0 \ub300\ub294\uc9c0\uc640 \uc5b4\ub5a4 \uad6c\uba4d\uc774 \uc5f4\ub9ac\uace0 \ub2eb\ud788\ub294\uc9c0\uac00 \uc7a5\uce58\ub97c \ud1b5\ud574 \uc5f0\uacb0\ub41c\ub2e4. \uc190\uc774 \ub2ff\ub294 \uc704\uce58\uc640 \uc18c\ub9ac\ub97c \ub9cc\ub4dc\ub294 \uc870\uac74 \uc0ac\uc774\uc5d0 \uae30\uacc4\uc801\uc778 \ub3c4\uc6c0\uc744 \ub9c8\ub828\ud55c \uc148\uc774\ub2e4. \uc545\uae30\ub97c \ub9cc\ub4dc\ub294 \uc0ac\ub78c\uc758 \uc120\ud0dd\uc774 \uc5f0\uc8fc\ud560 \uc218 \uc788\ub294 \uc74c\uc545\uc758 \ubc94\uc704\uc640 \uad00\uacc4\ub418\ub294 \uc774\uc720\ub2e4. \uae30\uad00\uc740 19\uc138\uae30\uc5d0 \ubc1c\uc804\ud55c \uccb4\uacc4\ub97c \ub354 \ubcf5\uc7a1\ud55c \uc74c\uc545\uc744 \uc5f0\uc8fc\ud558\ub294 \uc870\uac74\uacfc \uc5f0\uacb0\ud574 \uc18c\uac1c\ud55c\ub2e4. \ud55c \uc0ac\ub78c\uc758 \uc190\uc774 \ubaa8\ub4e0 \uc790\ub9ac\ub97c \uc9c1\uc811 \ub9c9\ub294 \ubaa8\uc2b5\uc744 \ub5a0\uc62c\ub9ac\uae30\ubcf4\ub2e4 \uc870\uc791\uc744 \uc804\ub2ec\ud558\ub294 \uc7a5\uce58\uac00 \uc788\ub2e4\ub294 \uc810\uc744 \ubcf4\uba74 \ub41c\ub2e4. \ub2e4\ub9cc \ubcf8\ubb38\uc758 \uadf8\ub9bc\uc744 \uc815\ud655\ud55c \uc6b4\uc9c0\ud45c\ub85c \uc0ac\uc6a9\ud558\uac70\ub098 \ud0a4 \ud558\ub098\ub9c8\ub2e4 \ud2b9\uc815\ud55c \uc74c\uc744 \ubc14\ub85c \ub300\uc751\uc2dc\ud0a4\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc2e4\uc81c \uc5f0\uc8fc\ubc95\uc740 \ubcc4\ub3c4\uc758 \uc790\ub8cc\uac00 \ud544\uc694\ud55c \uc601\uc5ed\uc774\ub2e4. \uc77c\ubc18\uc801\uc778 C \ud50c\ub8e8\ud2b8 \uc606\uc5d0\ub294 \uc791\uc740 \ud53c\ucf5c\ub85c\uc640 \uc54c\ud1a0, \ubca0\uc774\uc2a4 \ud50c\ub8e8\ud2b8 \uac19\uc740 \uc885\ub958\uac00 \uc788\ub2e4. \uc545\uae30\uad70 \uc548\uc5d0\uc11c \uc11c\ub85c \ub2e4\ub978 \ub192\uc774\uc758 \uc18c\ub9ac\ub97c \ub9e1\uc744 \uc218 \uc788\ub294 \uad6c\uc131\uc774\ub2e4. \uadf8\uc911 \ud53c\ucf5c\ub85c\ub294 \ub300\uccb4\ub85c \ubaa9\uc81c\ub85c \ub9cc\ub4e0\ub2e4\ub294 \uc124\uba85\ub3c4 \uc788\uc5b4, \ud50c\ub8e8\ud2b8 \uac00\uc871\uc744 \ubaa8\ub450 \uac19\uc740 \uc7ac\ub8cc\uc640 \ud06c\uae30\uc758 \ubb3c\uac74\uc73c\ub85c \uc0dd\uac01\ud558\uae30 \uc5b4\ub835\uac8c \ud55c\ub2e4. \uc5f0\uc8fc \uc601\uc0c1\uc744 \ubcfc \ub54c \uac00\uc7a5 \uc791\uac8c \ubcf4\uc774\ub294 \uc545\uae30\uc640 \uc775\uc219\ud55c \ud06c\uae30\uc758 \ud50c\ub8e8\ud2b8\ub97c \ube44\uad50\ud574\ub3c4 \uc7ac\ubbf8\uc788\ub2e4. \ub2e4\ub9cc \ud654\uba74\uc758 \ud06c\uae30\ub9cc\uc73c\ub85c \uc815\ud655\ud55c \uc885\ub958\ub97c \ud310\uc815\ud558\uae30\ubcf4\ub2e4\ub294 \uc548\ub0b4\uc640 \ud568\uaed8 \ud655\uc778\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc74c\uc545\uc758 \uac00\uc871\uc774\ub77c\ub294 \ub9d0\uc740 \ub2e4 \ub611\uac19\ub2e4\ub294 \ub73b\ubcf4\ub2e4 \uacf5\ud1b5\ub41c \uad00\uacc4 \uc548\uc5d0\uc11c \ucc28\uc774\uac00 \uc788\ub2e4\ub294 \ub73b\uc73c\ub85c \uc774\ud574\ud558\uba74 \ub354 \ud48d\ubd80\ud574\uc9c4\ub2e4. \uc7ac\ub8cc\ub97c \ubcf4\uc558\ub2e4\uba74 \ub2e4\uc74c\uc5d0\ub294 \uc18c\ub9ac\uc758 \uc5b4\ub290 \ubd80\ubd84\uc744 \ub4e3\uace0 \uc2f6\uc740\uc9c0 \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub2e4. \ubc18\uc9dd\uc774\ub294 \uc678\ud615\uc774 \uc5b8\uc81c\ub098 \uac19\uc740 \uc74c\uc0c9\uc744 \ubcf4\uc7a5\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc74c\uc5ed\uacfc \uc5f0\uc8fc \ubc29\uc2dd, \ub2e4\ub978 \uc545\uae30\uc640\uc758 \uad00\uacc4\uc5d0 \ub530\ub77c \uc778\uc0c1\uc740 \ub2ec\ub77c\uc9c4\ub2e4. \uc7ac\ub8cc\uc758 \uc774\ub984\ub9cc\uc73c\ub85c \ub530\ub73b\ud558\ub2e4\uac70\ub098 \ucc28\uac11\ub2e4\ub294 \uac10\uc0c1\uc744 \ubbf8\ub9ac \uc815\ud560 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ud50c\ub8e8\ud2b8\uc758 \uc774\uc57c\uae30\ub294 \uc18c\ub9ac\ub97c \ub9cc\ub4dc\ub294 \ubb3c\uac74\uc774 \uc624\ub7ab\ub3d9\uc548 \ubc14\ub00c\uc5b4 \uc654\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc5f0\uc8fc\uc790\uc758 \uc190\uc744 \ub3d5\ub294 \uc7a5\uce58\uc640 \uc7ac\ub8cc\uc758 \uc120\ud0dd\uc774 \ud568\uaed8 \ubc1c\uc804\ud588\ub2e4. \ubaa9\uad00\uc774\ub77c\ub294 \uc775\uc219\ud55c \ubd84\ub958 \uc55e\uc5d0\uc11c \uc7a0\uae50 \uba48\ucd94\uba74, \ud55c \uc774\ub984\uc774 \uc11c\ub85c \ub2e4\ub978 \uc2dc\ub300\uc758 \ubb3c\uac74\ub4e4\uc744 \uc5b4\ub5bb\uac8c \uc774\uc5b4 \uc8fc\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uc545\uae30 \uc774\ub984\uc744 \uc678\uc6b0\ub294 \uc77c\uc5d0\uc11c \uadf8 \ubcc0\ud654\uc758 \uc2dc\uac04\uc744 \uc77d\ub294 \uc77c\ub85c \ub118\uc5b4\uac00\ub294 \uc791\uc740 \uacc4\uae30\ub2e4. \uc624\ucf00\uc2a4\ud2b8\ub77c\uc5d0\uc11c\ub294 \uc77c\ubc18\uc801\uc778 C \ud50c\ub8e8\ud2b8 \uc678\uc5d0 \ud53c\ucf5c\ub85c\uc640 \uc54c\ud1a0 \ud50c\ub8e8\ud2b8, \ub54c\ub85c\ub294 \ubca0\uc774\uc2a4 \ud50c\ub8e8\ud2b8\ub3c4 \uc4f4\ub2e4. \ud50c\ub8e8\ud2b8\ub77c\ub294 \uc774\ub984 \uc544\ub798\uc5d0\ub3c4 \ud06c\uae30\uc640 \uc5ed\ud560\uc774 \ub2e4\ub978 \uc545\uae30\ub4e4\uc774 \uc788\ub2e4. \uc624\ub298\uc740 \ubaa8\ub4e0 \uc885\ub958\ub97c \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc740\ube5b \ud45c\uba74\uacfc \ubaa9\uad00\uc545\uae30\ub77c\ub294 \uc774\ub984 \uc0ac\uc774\uc758 \uac04\uaca9\ub9cc \uae30\uc5b5\ud574 \ubcf4\uc790. \ubb3c\uac74\uc758 \uc9c0\uae08 \ubaa8\uc2b5\uacfc \uadf8 \ubb3c\uac74\uc744 \ubd80\ub974\ub294 \ub9d0\uc774 \uaf2d \uac19\uc740 \uc2dc\uae30\uc758 \uc774\uc57c\uae30\ub9cc \ub2f4\uace0 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc791\uc740 \uc545\uae30 \ud558\ub098\uc5d0\ub3c4 \uadf8\ub7f0 \uc2dc\uac04\uc774 \uacb9\uce5c\ub2e4."}, {"id": "mexico-tortilla-grinding-stone", "title": "\ud1a0\ub974\ud2f0\uc57c \uc55e\uc5d0\ub294 \ub3cc \ub450 \uac1c\uac00 \uc788\uc5c8\ub2e4", "summary": "\uc644\uc131\ub41c \uc74c\uc2dd \ub4a4\uc5d0 \uc788\ub294 \uac08\ub3cc\uacfc \uc190\uc758 \uc6c0\uc9c1\uc784\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\uc2dd\ud0c1\uacfc \uc2dd\ud488 \ubcf4\uc874", "categories": ["everyday-inventions"], "url": "stories/mexico-tortilla-grinding-stone/index.html", "image": "../media/mexico-tortilla-grinding-stone.jpg", "alt": "\uba55\uc2dc\ucf54 \ud478\uc5d0\ub974\ud1a0\ubc14\uc57c\ub974\ud0c0\uc5d0\uc11c \uba54\ud0c0\ud14c\uc640 \ub9c8\ub178\ub85c \uc625\uc218\uc218 \uc7ac\ub8cc\ub97c \uac00\ub294 \uc791\uc5c5\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc2e4\uc81c \uc0ac\uc9c4.", "text": "\ud1a0\ub974\ud2f0\uc57c \uc55e\uc5d0\ub294 \ub3cc \ub450 \uac1c\uac00 \uc788\uc5c8\ub2e4 \uba55\uc2dc\ucf54\uc758 \uc625\uc218\uc218 \uc74c\uc2dd\uacfc \uc190 \uac00\uae4c\uc6b4 \ub3c4\uad6c \uc644\uc131\ub41c \uc74c\uc2dd \ub4a4\uc5d0 \uc788\ub294 \uac08\ub3cc\uacfc \uc190\uc758 \uc6c0\uc9c1\uc784\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc2dd\ud0c1\uacfc \uc2dd\ud488 \ubcf4\uc874 \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \uba55\uc2dc\ucf54 \uc74c\uc2dd \ud1a0\ub974\ud2f0\uc57c\ub97c \ub5a0\uc62c\ub9b4 \ub54c\ub294 \ub465\uae00\uace0 \ub0a9\uc791\ud55c \uc644\uc131\ud488\uc774 \uba3c\uc800 \uc0dd\uac01\ub09c\ub2e4. \uc0ac\uc9c4\uc744 \uc870\uae08 \ub4a4\ub85c \ub3cc\ub824 \ubcf4\uba74 \uadf8 \uc55e\uc5d0 \ub3cc \ub450 \uac1c\uc640 \uc190\uc758 \uc6c0\uc9c1\uc784\uc774 \uc788\ub2e4. \ud55c\ucabd\uc740 \ub113\uace0 \ub2e4\ub978 \ucabd\uc740 \uae38\ucb49\ud558\ub2e4. OpenStax \uad50\uc7ac\ub294 \uba55\uc2dc\ucf54 \ud478\uc5d0\ub974\ud1a0\ubc14\uc57c\ub974\ud0c0\uc5d0\uc11c \ud1a0\ub974\ud2f0\uc57c\ub97c \ub9cc\ub4dc\ub294 \uc7a5\uba74\uc73c\ub85c \uc774 \uc0ac\uc9c4\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc0ac\uc9c4 \uc18d \ub3c4\uad6c\ub294 \uc625\uc218\uc218\ub97c \uac08\uc544 \uc7ac\ub8cc\ub97c \uc900\ube44\ud558\ub294 \ub370 \uc4f0\ub294 \uba54\ud0c0\ud14c\uc640 \ub9c8\ub178\ub2e4. \uba54\ud0c0\ud14c\ub294 \uc7ac\ub8cc\ub97c \ubc1b\uce58\ub294 \ub113\uc740 \uac08\ub3cc\uc774\uace0, \ub9c8\ub178\ub294 \uc190\uc73c\ub85c \uc7a1\uc544 \uc6c0\uc9c1\uc774\ub294 \uae38\ucb49\ud55c \ub3cc\uc774\ub2e4. \ubaa8\uc591\uc774 \ub2e4\ub978 \ub450 \ubb3c\uac74\uc774 \ub9cc\ub098 \ud558\ub098\uc758 \uc791\uc5c5\uc744 \uc774\ub8ec\ub2e4. \ubbf9\uc11c\ucc98\ub7fc \ub36e\uac1c\ub97c \ub2eb\uace0 \uae30\ub2e4\ub9ac\ub294 \ub3c4\uad6c\ub97c \uc0dd\uac01\ud588\ub2e4\uba74 \ub9cc\ub4dc\ub294 \uc0ac\ub78c\uc758 \uc190\uc774 \ucc28\uc9c0\ud558\ub294 \uc790\ub9ac\uac00 \ub2e4\ub974\uac8c \ubcf4\uc77c \uc218 \uc788\ub2e4. \uc7ac\ub8cc\ub97c \uc5bc\ub9c8\ub098 \uc798\uac8c \uac08\uc9c0 \uc0b4\ud53c\uace0 \ubab8\uc744 \uc6c0\uc9c1\uc774\ub294 \uc77c\uc774 \uc900\ube44 \uacfc\uc815 \uc548\uc5d0 \ub4e4\uc5b4 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc804\ud1b5\uc801\uc778 \uac00\ub8e8 \uc900\ube44\uc5d0 \uc54c\ub9de\uc740 \uc7ac\ub8cc\ub97c \uace0\ub974\uace0, \uc6d0\ud558\ub294 \uace0\uc6b4 \uc815\ub3c4\ub97c \ud310\ub2e8\ud558\uba70, \uac08\ub3cc\uc744 \ub2e4\ub8e8\ub294 \ub2a5\ub825\uc774 \ud544\uc694\ud558\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub3c4\uad6c\uac00 \uc788\ub2e4\uace0 \uac19\uc740 \uacb0\uacfc\uac00 \uc800\uc808\ub85c \ub098\uc624\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc6b0\ub9ac\ub294 \uc74c\uc2dd \uc774\ub984\uc740 \uc790\uc8fc \uae30\uc5b5\ud558\uc9c0\ub9cc \uadf8 \uc74c\uc2dd\uc758 \uc7ac\ub8cc\ub97c \uc900\ube44\ud558\ub294 \uc190\ub180\ub9bc\uc740 \uc798 \ubcf4\uc9c0 \ubabb\ud55c\ub2e4. \uc0ac\uc9c4 \ud55c \uc7a5\uc5d0\uc11c \uac08\ub3cc\uc758 \ud45c\uba74\uacfc \uc190\uc774 \ub193\uc778 \uc790\ub9ac\ub97c \uc0b4\ud3b4\ubcf4\uba74 \uba39\uae30 \uc9c1\uc804\ubcf4\ub2e4 \uc870\uae08 \uc774\ub978 \uc2dc\uac04\uc73c\ub85c \ub4e4\uc5b4\uac00\uac8c \ub41c\ub2e4. \uba54\ud0c0\ud14c\uc640 \ub9c8\ub178\ub294 \uac19\uc740 \ub3cc\uc774\ub77c\ub294 \uc7ac\ub8cc\ub85c \ubb36\uc744 \uc218 \uc788\uc9c0\ub9cc \uc5ed\ud560\uc740 \ub098\ub25c\ub2e4. \uc544\ub798\uc758 \ub113\uc740 \ud45c\uba74\uc774 \uc7ac\ub8cc\ub97c \ubc1b\uace0 \uc190\uc73c\ub85c \uc6c0\uc9c1\uc774\ub294 \ub3cc\uc774 \uadf8 \uc704\uc5d0\uc11c \uc77c\uc744 \ud55c\ub2e4. \uc5b4\ub290 \ud558\ub098\ub9cc \ubcf4\uba74 \ubc14\ub2e5\uc774\ub098 \uae38\ucb49\ud55c \ubb3c\uac74\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\uc9c0\ub9cc \ud568\uaed8 \ub193\uc774\uba74 \uc6c0\uc9c1\uc784\uc774 \uc77d\ud78c\ub2e4. \ub3c4\uad6c\ub294 \uac1c\ubcc4 \ubaa8\uc591\ubfd0 \uc544\ub2c8\ub77c \uc11c\ub85c \ub2ff\ub294 \uad00\uacc4\ub97c \ud1b5\ud574 \uae30\ub2a5\uc744 \ub9cc\ub4e0\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uc190\uc774 \uc5b4\ub290 \ubd80\ubd84\uc744 \uc7a1\ub294\uc9c0\uc640 \uc791\uc5c5 \ud45c\uba74\uc774 \uc5b4\ub290 \ubc29\ud5a5\uc73c\ub85c \ub193\uc600\ub294\uc9c0\ubd80\ud130 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc815\uc9c0 \uc0ac\uc9c4 \ud55c \uc7a5\uc73c\ub85c \uc190\ub3d9\uc791\uc758 \uc18d\ub3c4\uc640 \ud798\uc744 \uacc4\uc0b0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc2e4\uc81c \uc791\uc5c5\uc758 \ubaa8\ub4e0 \ub2e8\uacc4\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc601\uc0c1\ub3c4 \uc544\ub2c8\ub2e4. \ub0a8\uc544 \uc788\ub294 \ud55c\uc21c\uac04\uc5d0\uc11c \ubb34\uc5c7\uc774 \ubb34\uc5c7\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\ub294\uc9c0 \uc54c\uc544\ubcf4\ub294 \uac83\uc774 \ucd9c\ubc1c\uc810\uc774\ub2e4. \uae30\uacc4\uac00 \uc544\ub2cc \ub3c4\uad6c\ub77c\uace0 \uc544\ubb34\ub807\uac8c\ub098 \uc6c0\uc9c1\uc5ec\ub3c4 \uac19\uc740 \uacb0\uacfc\uac00 \ub098\uc624\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc7ac\ub8cc\uc758 \uc0c1\ud0dc\ub97c \uc0b4\ud53c\uace0 \uc6d0\ud558\ub294 \uace0\uc6b4 \uc815\ub3c4\ub97c \uc54c\uc544\uc57c \ud55c\ub2e4\uace0 \uad50\uc7ac\ub294 \uc124\uba85\ud55c\ub2e4. \ubc18\ubcf5\ub418\ub294 \uc190\ub180\ub9bc \uc548\uc5d0\ub3c4 \uacbd\ud5d8\uc744 \ud1b5\ud574 \uc775\ud78c \ud310\ub2e8\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ub2e8\uc21c \ub178\ub3d9\uc774\ub77c\ub294 \ub9d0\ub85c \ud55c \ubc88\uc5d0 \uc815\ub9ac\ud558\uae30 \uc5b4\ub824\uc6b4 \uc774\uc720\ub2e4. \uc6b0\ub9ac\ub294 \uc644\uc131\ub41c \ud1a0\ub974\ud2f0\uc57c\uc758 \ub9db\uacfc \ud06c\uae30\ub294 \uc27d\uac8c \ub9d0\ud558\uc9c0\ub9cc \uadf8 \uc55e\uc758 \uc7ac\ub8cc \uc900\ube44\ub294 \ub35c \uc774\uc57c\uae30\ud55c\ub2e4. \uc5b4\ub290 \uc2dc\uc810\uc5d0 \ucda9\ubd84\ud788 \uac08\ub838\ub2e4\uace0 \ubcfc\uc9c0, \uc190\uacfc \ub3c4\uad6c\ub97c \uc5b4\ub5bb\uac8c \ub2e4\ub8f0\uc9c0\ub294 \uacb0\uacfc\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4. \ub2e4\ub9cc \uc774 \uc6d0\uace0\uc5d0\uc11c\ub294 \ud604\uc7a5 \uc790\ub8cc \uc5c6\uc774 \ud2b9\uc815\ud55c \uc870\ub9ac\ubc95\uacfc \uc2dc\uac04\uc744 \uc0c8\ub85c \uc81c\uc2dc\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc900\ube44\ud558\ub294 \uc0ac\ub78c\uc758 \uc9c0\uc2dd\uc774 \ud544\uc694\ud588\ub2e4\ub294 \ud070 \ub9e5\ub77d\uc5d0 \uc8fc\ubaa9\ud55c\ub2e4. \uad50\uc7ac\uc758 \ucea1\uc158\uc740 \uc0ac\uc9c4\uc744 \uba55\uc2dc\ucf54 \ud478\uc5d0\ub974\ud1a0\ubc14\uc57c\ub974\ud0c0\uc758 \ud1a0\ub974\ud2f0\uc57c \uc900\ube44 \uc7a5\uba74\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \ud55c \uc7a5\uba74\uc744 \uba55\uc2dc\ucf54\uc758 \ubaa8\ub4e0 \uac00\uc815\uc774\ub098 \ubaa8\ub4e0 \uc2dc\ub300\uc758 \uc870\ub9ac \ubc29\uc2dd\uc73c\ub85c \ubc14\uafc0 \uc218\ub294 \uc5c6\ub2e4. \uad6c\uccb4\uc801\uc778 \uc7a5\uc18c\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc774\ub7f0 \uacfc\ub3c4\ud55c \uc77c\ubc18\ud654\ub97c \ub9c9\uc544 \uc900\ub2e4. \uac19\uc740 \uc74c\uc2dd \uc774\ub984 \uc544\ub798\uc5d0\ub3c4 \uc5ec\ub7ec \ub3c4\uad6c\uc640 \uc900\ube44 \ubc29\uc2dd\uc774 \uc788\uc744 \uc218 \uc788\ub2e4. \uc9c0\uc5ed\uacfc \uc0ac\ub78c\uc758 \uae30\uc220\uc744 \ub0a8\uaca8 \ub450\uba74 \uc61b \ub3c4\uad6c\uc640 \ud604\ub300 \uae30\uacc4\ub97c \ub2e8\uc21c\ud788 \ubc1c\uc804\uc758 \uc21c\uc11c\ub85c \ub098\ub204\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uc774 \ubc29\uc2dd\uc774 \ubb34\uc5c7\uc744 \uac00\ub2a5\ud558\uac8c \ud588\uace0 \uadf8 \uc548\uc5d0\uc11c \uc5b4\ub5a4 \uacbd\ud5d8\uc774 \ud544\uc694\ud588\ub294\uc9c0 \ubb3b\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \uc0ac\uc9c4 \uc18d \uc778\ubb3c\uc758 \uc0dd\ud65c \uc804\uccb4\ub97c \uc54c\uc9c0 \ubabb\ud574\ub3c4 \uadf8 \uc0ac\ub78c\uc774 \uc9c0\uae08 \uc218\ud589\ud558\ub294 \uc791\uc5c5\uc744 \ubc30\uc6b8 \uc218 \uc788\ub2e4. \uc74c\uc2dd \ubb38\ud654\ub294 \uc7ac\ub8cc\ubfd0 \uc544\ub2c8\ub77c \ub9cc\ub4dc\ub294 \ud589\ub3d9\uc5d0\ub3c4 \uc788\ub2e4. \uc644\uc131\ub41c \uc74c\uc2dd\uc740 \uc2dd\ud0c1 \uc704\uc5d0 \uc9e7\uac8c \uba38\ubb3c \uc218 \uc788\uc9c0\ub9cc \uadf8 \uc55e\uc5d0\ub294 \uc5ec\ub7ec \uc900\ube44\uac00 \uc774\uc5b4\uc9c4\ub2e4. \uac08\ub3cc \uc0ac\uc9c4\uc740 \ud3c9\uc18c \uc811\uc2dc\uc5d0 \uac00\ub824\uc9c0\ub294 \uadf8 \uc2dc\uac04\uc744 \ub4dc\ub7ec\ub0b8\ub2e4. \ub204\uad70\uac00 \uc7ac\ub8cc\ub97c \uace8\ub790\uace0 \uc190\uc5d0 \uc775\uc740 \ub3c4\uad6c\ub85c \uc0c1\ud0dc\ub97c \ubc14\uafb8\uc5c8\ub2e4. \uba39\uc744 \uc218 \uc788\ub294 \ud615\ud0dc\uac00 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ubc14\ub85c \ub098\ud0c0\ub09c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ub2e4\uc74c\uc5d0 \uc775\uc219\ud55c \uc74c\uc2dd\uc758 \uc81c\uc791 \uc0ac\uc9c4\uc744 \ubcf4\uba74 \uc774\ub984\ubd80\ud130 \ud655\uc778\ud55c \ub4a4 \ub3c4\uad6c\uc640 \uc190\uc758 \uc811\uc810\uc744 \ubcf4\uc544 \ubcf4\uc790. \uc7ac\ub8cc\uac00 \ub193\uc778 \uba74\uacfc \uc6c0\uc9c1\uc774\ub294 \ub3c4\uad6c\ub97c \ub098\ub204\uc5b4 \ubcf4\uba74 \uc791\uc740 \uad6c\uc870\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \ud1a0\ub974\ud2f0\uc57c \uc55e\uc758 \ub450 \ub3cc\uc740 \uc694\ub9ac\uc758 \uc5ed\uc0ac\ub97c \uc8fc\ubc29\uc758 \uc7a5\uce58\ubfd0 \uc544\ub2c8\ub77c \ubab8\uacfc \ud310\ub2e8\uc758 \uc5ed\uc0ac\ub85c \uc77d\ub294 \uc785\uad6c\uac00 \ub41c\ub2e4. \ub2e8\uc21c\ud574 \ubcf4\uc774\ub294 \ub3c4\uad6c\uc5d0 \uacbd\ud5d8\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \uc774 \uc0ac\uc9c4\uc774 \uba55\uc2dc\ucf54\uc758 \ubaa8\ub4e0 \uac00\uc815\uc774 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ud1a0\ub974\ud2f0\uc57c\ub97c \ub9cc\ub4e0\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc2e4\uc81c \ub0a8\uc544 \uc788\ub294 \ud55c \uc791\uc5c5 \uc7a5\uba74\uc744 \ubcf4\uace0 \uc788\ub2e4. \uad6c\uccb4\uc801\uc778 \uc870\ub9ac\ubc95\uc774\ub098 \uc7ac\ub8cc \ucc98\ub9ac\ubc95\uc744 \uc774 \uc0ac\uc9c4\ub9cc\uc73c\ub85c \uc815\ud558\uc9c0\ub3c4 \uc54a\ub294\ub2e4. \ub300\uc2e0 \uc775\uc219\ud55c \uc74c\uc2dd\uc744 \ubcfc \ub54c \uadf8 \uc55e\uc5d0 \uc5b4\ub5a4 \ub3c4\uad6c\uac00 \uc788\uc5c8\ub294\uc9c0 \ubb3c\uc5b4\ubcfc \uc218 \uc788\ub2e4. \ub0a9\uc791\ud55c \ud55c \uc7a5\uc774 \uc2dd\ud0c1\uc5d0 \uc624\uae30 \uc804\uc5d0 \ub204\uad70\uac00\ub294 \ub3cc\uc758 \ubb34\uac8c\uc640 \uc7ac\ub8cc\uc758 \uc0c1\ud0dc\ub97c \uc190\uc73c\ub85c \ub2e4\ub8e8\uc5c8\ub2e4. \ud1a0\ub974\ud2f0\uc57c\uc758 \ub2e4\ub978 \uc5bc\uad74\uc740 \uadf8\ub807\uac8c \uc644\uc131\ud488 \ubc14\uae65\uc5d0 \uc788\ub2e4."}, {"id": "phonograph-groove-and-returning-voice", "title": "\ucd95\uc74c\uae30 \u2014 \ud55c \ubc88 \uc9c0\ub098\uac04 \ubaa9\uc18c\ub9ac\ub97c \ub2e4\uc2dc \ub4e4\uc744 \uc218 \uc788\ub2e4\uba74", "summary": "\uc9c4\ub3d9\uc744 \ud45c\uba74\uc5d0 \ub0a8\uae30\ub294 \uc7a5\uce58\uc5d0\uc11c \uae30\ub85d\ub41c \ubaa9\uc18c\ub9ac\ub97c \ubc18\ubcf5\ud574\uc11c \ub4e3\ub294 \uc0dd\ud65c\uc774 \uc0dd\uaca8\ub09c \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\ub180\uc774\uc640 \ucde8\ubbf8", "categories": ["everyday-inventions"], "url": "stories/phonograph-groove-and-returning-voice/index.html", "image": "../media/phonograph-groove-and-returning-voice.jpg", "alt": "\ud68c\uc804 \uc6d0\ud1b5\uacfc \uc190\uc7a1\uc774\uac00 \ubcf4\uc774\ub294 \ucd08\uae30 \ucd95\uc74c\uae30\uc758 \uc5ed\uc0ac \uadf8\ub9bc", "text": "\ucd95\uc74c\uae30 \u2014 \ud55c \ubc88 \uc9c0\ub098\uac04 \ubaa9\uc18c\ub9ac\ub97c \ub2e4\uc2dc \ub4e4\uc744 \uc218 \uc788\ub2e4\uba74 \uc6d0\ud1b5\uc758 \uc9c4\ub3d9 \uae30\ub85d\uc5d0\uc11c \ubc18\ubcf5\ud574\uc11c \ub4e3\ub294 \uc0dd\ud65c\uc774 \ub9cc\ub4e4\uc5b4\uc9c0\uae30\uae4c\uc9c0 \uc9c4\ub3d9\uc744 \ud45c\uba74\uc5d0 \ub0a8\uae30\ub294 \uc7a5\uce58\uc5d0\uc11c \uae30\ub85d\ub41c \ubaa9\uc18c\ub9ac\ub97c \ubc18\ubcf5\ud574\uc11c \ub4e3\ub294 \uc0dd\ud65c\uc774 \uc0dd\uaca8\ub09c \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ub180\uc774\uc640 \ucde8\ubbf8 \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \ubaa9\uc18c\ub9ac\ub294 \ub9d0\ud558\ub294 \uc21c\uac04 \uc9c0\ub098\uac04\ub2e4. \uae00\ub85c \uc62e\uae38 \uc218\ub294 \uc788\uc5b4\ub3c4 \ub9d0\ud55c \uc0ac\ub78c\uc758 \ub192\ub0ae\uc774\uc640 \ub5a8\ub9bc\uae4c\uc9c0 \uadf8\ub300\ub85c \ub0a8\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ucd95\uc74c\uae30\ub294 \uc774 \uc775\uc219\ud55c \uc870\uac74\uc744 \ubc14\uafb8\uc5c8\ub2e4. \ub204\uad70\uac00 \ub5a0\ub09c \ub4a4\uc5d0\ub3c4 \uadf8 \ubaa9\uc18c\ub9ac\uac00 \ub2e4\uc2dc \ub4e4\ub9b4 \uc218 \uc788\ub2e4\ub294 \uc0dd\uac01\uc774 \uc2e4\uc81c \uae30\uacc4\uc758 \uc77c\uc774 \ub418\uc5c8\ub2e4. \ud1a0\uba38\uc2a4 \uc5d0\ub514\uc2a8\uc758 \ucd95\uc74c\uae30\ub97c \uc2dc\uc791\uc73c\ub85c \uc18c\ub9ac\uc758 \uae30\ub85d \ubc29\uc2dd\uc740 \uc5ec\ub7ec \ud615\ud0dc\ub85c \ubc1c\uc804\ud588\ub2e4. \uc5ec\uae30\uc11c \uc911\uc694\ud55c \uac83\uc740 \uc74c\ubc18\uc744 \uc7ac\uc0dd\ud558\ub294 \uc7a5\uce58\uac00 \ud558\ub098 \uc0dd\uacbc\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uc21c\uac04\uc758 \uc0ac\uac74\uc774\uc5c8\ub358 \uc18c\ub9ac\ub97c \ubc18\ubcf5\ud574\uc11c \ub4e4\uc744 \uc218 \uc788\ub294 \ubb3c\uac74\uc73c\ub85c \ubc14\uafbc \uacfc\uc815\uc774\ub2e4. \uc18c\ub9ac\ub294 \ubb3c\uccb4\uc640 \uacf5\uae30\uc758 \uc9c4\ub3d9\uc744 \ud1b5\ud574 \uc804\ub2ec\ub41c\ub2e4. \ucd08\uae30\uc758 \uae30\uacc4\uc801 \ub179\uc74c\uc740 \uadf8 \uc6c0\uc9c1\uc784\uc744 \ubb3c\uc9c8 \ud45c\uba74\uc758 \ud754\uc801\uc73c\ub85c \ubc14\uafb8\ub824 \ud588\ub2e4. \uc18c\ub9ac\ub97c \ub4e3\ub294 \ub9c9\uc774 \uc6c0\uc9c1\uc774\uace0 \uadf8 \ubcc0\ud654\uac00 \ubc14\ub298\uc744 \ud1b5\ud574 \uae30\ub85d \ub9e4\uccb4\uc5d0 \ub0a8\ub294\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc9c4\ub3d9\uc744 \ub208\uc5d0 \ubcf4\uc774\ub294 \uc790\uad6d\uacfc \uc5f0\uacb0\ud558\ub294 \uac83\uc774\ub2e4. \ub2e4\uc2dc \ub4e4\uc744 \ub54c\uc5d0\ub294 \uc774 \uad00\uacc4\ub97c \ubc18\ub300 \ubc29\ud5a5\uc73c\ub85c \uc774\uc6a9\ud55c\ub2e4. \ub0a8\uc544 \uc788\ub294 \ud754\uc801\uc744 \ub530\ub77c \ubc14\ub298\uacfc \ub9c9\uc774 \uc6c0\uc9c1\uc774\uba70 \uc18c\ub9ac\ub97c \ub9cc\ub4e0\ub2e4. \uc774\uac83\uc740 \uc785\uc744 \uac00\uc9c4 \uc0ac\ub78c\uc774 \uae30\uacc4 \uc548\uc5d0 \uc228\uc5b4 \uc788\ub294 \uc7a5\uce58\uac00 \uc544\ub2c8\ub2e4. \uc21c\uac04\uc758 \uc6c0\uc9c1\uc784\uc744 \uc800\uc7a5 \uac00\ub2a5\ud55c \ud615\ud0dc\ub85c \ubc14\uafb8\uace0 \ub2e4\uc2dc \uc6c0\uc9c1\uc784\uc73c\ub85c \ub418\ub3cc\ub9ac\ub294 \uae30\uc220\uc774\uc5c8\ub2e4. \uc5d0\ub514\uc2a8\uc774 1877\ub144\uc5d0 \uc120\ubcf4\uc778 \ucd08\uae30 \ucd95\uc74c\uae30\uc5d0\ub294 \ud68c\uc804\ud558\ub294 \uc6d0\ud1b5\uacfc \uc587\uc740 \uae08\uc18d\ubc15\uc774 \uc0ac\uc6a9\ub418\uc5c8\ub2e4. \uc190\uc73c\ub85c \ub3cc\ub9ac\ub294 \uc7a5\uce58\uc640 \uc18c\ub9ac\ub97c \ubc1b\uc544\ub4e4\uc774\ub294 \ubd80\ubd84\uc774 \uacb0\ud569\ud588\ub2e4. \ud6c4\ub300\uc758 \ub9e4\ub048\ud55c \uc74c\ubc18\uc774\ub098 \uc804\uc790\uae30\uae30\ub97c \ub5a0\uc62c\ub9ac\uba74 \ub2e4\ub978 \ubaa8\uc591\uc774\uc9c0\ub9cc \ub179\uc74c\uacfc \uc7ac\uc0dd\uc744 \uc5f0\uacb0\ud55c\ub2e4\ub294 \ud575\uc2ec\uc774 \uc788\uc5c8\ub2e4. \ucc98\uc74c\uc758 \uc778\uc0c1\uc801\uc778 \uc2dc\uc5f0\uc744 \uc624\ub298\uc758 \uae68\ub057\ud55c \uc74c\uc9c8\uacfc \uac19\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ub4e4\ub9b0 \ub9d0\uc774 \ubc18\ubcf5\ub420 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774\uc5c8\ub2e4. \uc774\ud6c4\uc5d0\ub294 \uae30\ub85d \uc7ac\ub8cc\uc640 \uc7a5\uce58\uc758 \uc815\ubc00\ub3c4\ub97c \uac1c\uc120\ud558\ub294 \uc77c\uc774 \ud544\uc694\ud588\ub2e4. \uac00\ub2a5\uc131\uc744 \ubcf4\uc5ec \uc900 \ub2e8\uacc4\uc640 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uc4f8 \uc218 \uc788\ub294 \uc81c\ud488\uc774 \ub418\ub294 \ub2e8\uacc4\ub294 \ub2ec\ub790\ub2e4. \uc18c\ub9ac\ub97c \ub0a8\uae30\ub294 \ud45c\uba74\uc740 \uc791\uc740 \uc6c0\uc9c1\uc784\uc744 \ub2f4\uc544\uc57c \ud558\uba74\uc11c \uc7ac\uc0dd \uacfc\uc815\ub3c4 \uacac\ub38c\uc57c \ud55c\ub2e4. \ub108\ubb34 \uc27d\uac8c \ubcc0\ud615\ub418\uac70\ub098 \ubc18\ubcf5\ud574\uc11c \uc77d\uae30 \uc5b4\ub824\uc6b0\uba74 \uae30\ub85d\uc758 \uac00\uce58\uac00 \uc904\uc5b4\ub4e0\ub2e4. \uc7ac\ub8cc\uc758 \uc120\ud0dd\uc740 \uc74c\uc9c8\ub9cc\uc774 \uc544\ub2c8\ub77c \uc5bc\ub9c8\ub098 \uc624\ub798 \ub0a8\uae30\uace0 \uba87 \ubc88\uc774\ub098 \ub4e4\uc744 \uc218 \uc788\ub294\uc9c0\uc758 \ubb38\uc81c\uc600\ub2e4. \uc6d0\ud1b5\ud615 \uae30\ub85d\uacfc \ub2e4\ub978 \ubc29\uc2dd\ub4e4\uc774 \ubc1c\uc804\ud558\uba74\uc11c \uc18c\ub9ac\ub97c \ub2f4\uc740 \ubb3c\uac74\uc758 \ud615\ud0dc\ub3c4 \ub2ec\ub77c\uc84c\ub2e4. \uc5d0\ubc00 \ubca0\ub97c\ub9ac\ub108\uc758 \uc6d0\ubc18 \ubc29\uc2dd \uc5ed\uc2dc \uc774 \uc5ed\uc0ac\uc5d0\uc11c \uc911\uc694\ud558\ub2e4. \ucd95\uc74c\uae30\uc758 \ubc1c\uc804\uc744 \uc5d0\ub514\uc2a8 \ud55c \uc0ac\ub78c\uc758 \ubc1c\uba85 \ub0a0\uc9dc\ub85c\ub9cc \ub05d\ub0b4\uba74 \uc7ac\ub8cc\uc640 \ud615\uc2dd, \ubcf5\uc81c \ubc29\ubc95\uc744 \ubc14\uafbc \ub4a4\uc758 \uacbd\uc7c1\uc774 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ub179\uc74c\uc774 \uac00\ub2a5\ud574\ub3c4 \ubaa8\ub4e0 \ubcf5\uc0ac\ubcf8\uc744 \ub9e4\ubc88 \ucc98\uc74c\ubd80\ud130 \ub2e4\uc2dc \ub179\uc74c\ud574\uc57c \ud55c\ub2e4\uba74 \ubcf4\uae09\uc5d0\ub294 \ud55c\uacc4\uac00 \uc788\ub2e4. \uae30\ub85d\uc744 \uc5ec\ub7ec \uac1c\ub85c \uc7ac\ud604\ud558\ub294 \ubb38\uc81c\uac00 \uc911\uc694\ud574\uc9c4\ub2e4. \uacf5\uc5f0\uc744 \ud55c \ubc88 \ub0a8\uae30\ub294 \uc77c\uacfc \uac19\uc740 \uacf5\uc5f0\uc744 \ub9ce\uc740 \ubb3c\uac74\uc73c\ub85c \ub9cc\ub4e4\uc5b4 \ud310\ub9e4\ud558\ub294 \uc77c \uc0ac\uc774\uc5d0 \ub610 \ub2e4\ub978 \uae30\uc220\uacfc \uc0ac\uc5c5\uc774 \uc788\uc5c8\ub2e4. \uc774 \uacfc\uc815\uc744 \ud1b5\ud574 \uc18c\ub9ac\ub294 \ub4e4\uc744 \ub54c\ub9c8\ub2e4 \uc0c8\ub85c \uc77c\uc5b4\ub098\ub294 \uc0ac\uac74\uc774\uba74\uc11c \uac70\ub798 \uac00\ub2a5\ud55c \uae30\ub85d\uc774 \ub41c\ub2e4. \uc5f0\uc8fc\uc790\uac00 \uac19\uc740 \ubc29\uc5d0 \uc788\uc9c0 \uc54a\uc544\ub3c4 \uac19\uc740 \uc5f0\uc8fc\ub97c \ubc18\ubcf5\ud574 \ub4e4\uc744 \uc218 \uc788\ub2e4. \uc18c\ub9ac\uc758 \ubcf5\uc81c\ub294 \ud3b8\ub9ac\ud568\uc744 \ub354\ud558\ub294 \ub3d9\uc2dc\uc5d0 \uccad\uc911\uacfc \uc5f0\uc8fc\uc790\uac00 \ub9cc\ub098\ub294 \ubc29\uc2dd\uc744 \ubc14\uafb8\uc5c8\ub2e4. \uc18c\ub9ac\ub97c \uae30\ub85d\ud574 \ub450\uba74 \uacf5\uc5f0\uc774 \uc5f4\ub9ac\ub294 \uc7a5\uc18c\uc640 \uc2dc\uac04\uc5d0 \ub9de\ucd94\uc5b4\uc57c\ub9cc \ub4e4\uc744 \uc218 \uc788\ub294 \uc870\uac74\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc9d1\uc5d0\uc11c\ub3c4 \ub2e4\uc2dc \ub4e4\uc744 \uc218 \uc788\uace0 \ub9c8\uc74c\uc5d0 \ub4e0 \ubd80\ubd84\uc744 \ubc18\ubcf5\ud560 \uc218 \uc788\ub2e4. \uac19\uc740 \uae30\ub85d\uc744 \uc5ec\ub7ec \ubc88 \ub4e4\uc73c\uba74 \uc775\uc219\ud568\uacfc \ucde8\ud5a5\uc774 \uc313\uc774\ub294 \ubc29\uc2dd\ub3c4 \ubc14\ub010\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub179\uc74c\uc774 \uc2e4\uc81c \uacf5\uc5f0\uacfc \uac19\uc740 \uacbd\ud5d8\uc740 \uc544\ub2c8\ub2e4. \uacf5\uc5f0\uc7a5\uc758 \uacf5\uac04\uacfc \ud604\uc7a5\uc758 \uc0c1\ud638\uc791\uc6a9\uc740 \ub2e4\ub978 \uc870\uac74\uc774\ub2e4. \uc0c8\ub85c\uc6b4 \ub9e4\uccb4\ub294 \uc774\uc804\uc758 \uacbd\ud5d8\uc744 \uadf8\ub300\ub85c \ubcf5\uc0ac\ud558\ub294 \ub370\uc11c \ub05d\ub098\uc9c0 \uc54a\uace0 \uc790\uc2e0\ub9cc\uc758 \uac10\uc0c1 \ubc29\uc2dd\uc744 \ub9cc\ub4e0\ub2e4. \ucd95\uc74c\uae30\ub294 \uc74c\uc545\uc744 \uc62e\uaca8 \uc628 \uae30\uacc4\uc774\uba74\uc11c \ub4e3\ub294 \uc2b5\uad00\uc744 \uc0c8\ub86d\uac8c \uc870\uc9c1\ud55c \ubb3c\uac74\uc774\uc5c8\ub2e4. \uc74c\uc545\ubfd0 \uc544\ub2c8\ub77c \ub9d0\ub3c4 \uae30\ub85d\ud560 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ud2b9\ubcc4\ud55c \uc758\ubbf8\ub97c \uac00\uc84c\ub2e4. \uae00\ub85c \uc801\uc740 \ubb38\uc7a5\uacfc \ub2ec\ub9ac \ubaa9\uc18c\ub9ac\uc5d0\ub294 \uc18d\ub3c4\uc640 \ub9dd\uc124\uc784, \uc5b5\uc591\uc774 \uc788\ub2e4. \uc18c\ub9ac\ub97c \ubcf4\uc874\ud558\uba74 \ub0b4\uc6a9\ub9cc\uc774 \uc544\ub2c8\ub77c \uc5b4\ub5bb\uac8c \ub9d0\ud588\ub294\uc9c0\uc758 \uc77c\ubd80\ub3c4 \ub2e4\uc2dc \ub9cc\ub0a0 \uc218 \uc788\ub2e4. \uae30\ub85d\uc758 \ubc94\uc704\uac00 \ub113\uc5b4\uc9c0\ub294 \uac83\uc774\ub2e4. \ud558\uc9c0\ub9cc \ub179\uc74c\uc774 \uc0ac\ub78c\uacfc \uc0ac\uac74\uc758 \uc804\ubd80\ub97c \ub2f4\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc7a5\uce58\uac00 \ubc1b\uc544\ub4e4\uc778 \uc18c\ub9ac\uc640 \uae30\ub85d\ud55c \uc2dc\uac04\ub9cc \ub0a8\ub294\ub2e4. \uc774\ud6c4\uc758 \uccad\uc790\ub294 \uadf8 \uc18c\ub9ac\uac00 \uc5b4\ub5a4 \uc0c1\ud669\uc5d0\uc11c \uc0dd\uacbc\ub294\uc9c0 \ubcc4\ub3c4\ub85c \uc54c\uc544\uc57c \ud560 \uc218 \uc788\ub2e4. \ubaa9\uc18c\ub9ac\uac00 \uc2e4\uc81c\ub85c \ub4e4\ub9b0\ub2e4\ub294 \uc778\uc0c1\uacfc \uadf8 \uae30\ub85d\uc744 \ucda9\ubd84\ud788 \uc774\ud574\ud55c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uac19\uc740 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc624\ub298\uc758 \ub3c5\uc790\ub294 \ud654\uba74\uc758 \uc7ac\uc0dd \ud45c\uc2dc\ub97c \ub204\ub974\ub294 \ub370 \uc775\uc219\ud558\ub2e4. \uadf8\ub7ec\ub098 \uc18c\ub9ac\ub97c \ub2e4\uc2dc \ub4e3\ub294 \uc77c\uc774 \ucc98\uc74c\ubd80\ud130 \uac00\ubcbc\uc6b4 \ub370\uc774\ud130\uc758 \ud615\ud0dc\uc600\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc6d0\ud1b5\uacfc \uc6d0\ubc18, \ubc14\ub298\uacfc \uc9c4\ub3d9\ud310 \uac19\uc740 \ubb3c\uc9c8\uc758 \uc6c0\uc9c1\uc784\uc744 \uac70\uccd0 \uc654\ub2e4. \uc9c0\ub098\uac04 \uc18c\ub9ac\ub97c \ubd99\uc7a1\ub294 \ub370\uc5d0\ub294 \ub9cc\uc9c8 \uc218 \uc788\ub294 \ud45c\uba74\uc774 \ud544\uc694\ud588\ub2e4. \uc18c\ub9ac\uc758 \ub0b4\uc6a9\uacfc \uae30\ub85d \ub9e4\uccb4\uc758 \ubaa8\uc591\uc744 \uad6c\ubcc4\ud574 \ubcf4\ub294 \uac83\ub3c4 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uac19\uc740 \ubaa9\uc18c\ub9ac\ub77c\ub3c4 \uc5b4\ub5a4 \ud45c\uba74\uc5d0 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \ub0a8\uae30\ub290\ub0d0\uc5d0 \ub530\ub77c \uc7ac\uc0dd \uc7a5\uce58\uc640 \ubcf5\uc81c \uacfc\uc815\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc18c\ub9ac\ub97c \ubcf4\uc874\ud558\ub294 \ub2a5\ub825\uc740 \ub179\uc74c\uc758 \uc21c\uac04\ubfd0 \uc544\ub2c8\ub77c \ub9e4\uccb4\ub97c \ub9cc\ub4e4\uace0 \uc77d\ub294 \uc804\uccb4 \uccb4\uacc4\uc5d0 \ub2ec\ub824 \uc788\uc5c8\ub2e4. \ucd95\uc74c\uae30\uc758 \uc190\uc7a1\uc774\ub97c \uc0c1\uc0c1\ud558\uba74 \uae30\ub85d\uc774\ub77c\ub294 \ub9d0\uc774 \uc870\uae08 \ub2ec\ub77c\uc9c4\ub2e4. \uacfc\uac70\uc758 \uc18c\ub9ac\uac00 \uc5b4\ub514\uc5d4\uac00 \uadf8\ub300\ub85c \uae30\ub2e4\ub9ac\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ud2b9\uc815\ud55c \ubc29\uc2dd\uc73c\ub85c \ub0a8\uae30\uace0 \ub2e4\uc2dc \ub9cc\ub4e4\uc5b4 \ub4e3\ub294 \uac83\uc774\ub2e4. \uadf8 \uacfc\uc815\uc744 \uc54c\uba74 \uc775\uc219\ud55c \uc74c\uc545 \ud30c\uc77c\uc5d0\ub3c4 \ubb34\uc5c7\uc744 \ubcf4\uc874\ud558\uace0 \uc5b4\ub5bb\uac8c \ub418\ub3cc\ub9ac\ub294\uc9c0\uc5d0 \uad00\ud55c \uc624\ub79c \uc9c8\ubb38\uc774 \uc774\uc5b4\uc9c0\uace0 \uc788\uc74c\uc744 \ub290\ub084 \uc218 \uc788\ub2e4."}, {"id": "popcorn-little-explosion", "title": "\ud31d\ucf58 \ud55c \uc54c\uc740 \uc5b4\ub5bb\uac8c \uc800\ub807\uac8c \ucee4\uc9c8\uae4c", "summary": "\ubd84\uba85 \ub2e8\ub2e8\ud55c \uc54c\uac31\uc774\uc600\ub294\ub370 \uc5b4\ub290\uc0c8 \ud558\uc597\uace0 \uac00\ubcbc\uc6b4 \uac04\uc2dd\uc73c\ub85c. \ud31d\ucf58\uc758 \ubcc0\uc2e0\uc5d0\ub294 \uc528\uc557 \uc18d \uc218\ubd84\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\uc2dd\ud0c1\uacfc \uc2dd\ud488 \ubcf4\uc874", "categories": ["everyday-inventions"], "url": "stories/popcorn-little-explosion/index.html", "image": "../media/popcorn-little-explosion.jpg", "alt": "\ud31d\ucf58 \ud55c \uc54c\uc740 \uc5b4\ub5bb\uac8c \uc800\ub807\uac8c \ucee4\uc9c8\uae4c \u2014 \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ud31d\ucf58 \ud55c \uc54c\uc740 \uc5b4\ub5bb\uac8c \uc800\ub807\uac8c \ucee4\uc9c8\uae4c \uc54c\uac31\uc774 \uc548\uc5d0 \ub0a8\uc544 \uc788\ub358 \uc218\ubd84\uc774 \ud558\ub294 \uc77c \ubd84\uba85 \ub2e8\ub2e8\ud55c \uc54c\uac31\uc774\uc600\ub294\ub370 \uc5b4\ub290\uc0c8 \ud558\uc597\uace0 \uac00\ubcbc\uc6b4 \uac04\uc2dd\uc73c\ub85c. \ud31d\ucf58\uc758 \ubcc0\uc2e0\uc5d0\ub294 \uc528\uc557 \uc18d \uc218\ubd84\uc774 \ud544\uc694\ud569\ub2c8\ub2e4. \uc2dd\ud0c1\uacfc \uc2dd\ud488 \ubcf4\uc874 \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \uc601\ud654\uac00 \uc2dc\uc791\ub418\uae30 \uc804, \ud31d\ucf58 \ud1b5\uc5d0\ub294 \ubc8c\uc368 \uc190\uc774 \uba87 \ubc88 \uc624\uac04\ub2e4. \ud558\uc597\uace0 \uac00\ubcbc\uc6b4 \uc870\uac01\uc744 \uc9d1\ub2e4 \ubcf4\uba74 \uac00\ub054 \ubc14\ub2e5\uc5d0 \ub0a8\uc740 \ub2e8\ub2e8\ud55c \uc54c\uac31\uc774\ub97c \ub9cc\ub098\uae30\ub3c4 \ud55c\ub2e4. \ub458\uc740 \uac19\uc740 \uc625\uc218\uc218\uc5d0\uc11c \ucd9c\ubc1c\ud588\ub2e4. \uadf8\ub7f0\ub370 \ud558\ub098\ub294 \ubd80\ud480\uc5b4 \uc62c\ub790\uace0 \ub2e4\ub978 \ud558\ub098\ub294 \uc791\uc740 \ub3cc\ucc98\ub7fc \ub0a8\uc558\ub2e4. \ub300\uccb4 \uc54c\uac31\uc774 \uc548\uc5d0\uc11c \ubb34\uc2a8 \uc77c\uc774 \ubc8c\uc5b4\uc9c4 \uac83\uc77c\uae4c. \ud31d\ucf58\uc744 \ub9cc\ub4dc\ub294 \ub370\uc5d0\ub294 \ub2e8\uc9c0 \ub192\uc740 \uc628\ub3c4\ub9cc \ud544\uc694\ud55c \uac83\uc774 \uc544\ub2c8\ub2e4. \ub208\uc5d0 \uc798 \ubcf4\uc774\uc9c0 \uc54a\uc9c0\ub9cc \uc911\uc694\ud55c \uc900\ube44\ubb3c\uc774 \uc788\ub2e4. \uc54c\uac31\uc774 \uc548\uc758 \uc218\ubd84\uc774\ub2e4. \ud31d\ucf58\uc6a9 \uc625\uc218\uc218\ub3c4 \ubcf4\uad00\uacfc \uac00\uacf5\uc744 \uac70\uccd0 \uc6b0\ub9ac \uc190\uc5d0 \uc628\ub2e4. \ubbf8\uad6d \uad6d\ub9bd\ub18d\uc5c5\ub3c4\uc11c\uad00\uc758 \ud31d\ucf58 \uc804\uc2dc\ub294 \uc218\ud655\ud55c \uc625\uc218\uc218\ub97c \uc801\uc808\ud55c \uc218\ubd84 \uc0c1\ud0dc\ub85c \ub9d0\ub9ac\ub294 \uacfc\uc815\ubd80\ud130 \uc18c\uac1c\ud55c\ub2e4. \ubb34\uc870\uac74 \ubc14\uc2f9 \ub9d0\ub9ac\ub294 \uac83\uc774 \ubaa9\uc801\uc740 \uc544\ub2c8\ub2e4. \ud130\uc9c0\ub294 \ub370 \ud544\uc694\ud55c \uc218\ubd84\uc740 \ub0a8\uaca8\uc57c \ud55c\ub2e4. \uac00\uacf5 \uacfc\uc815\uc5d0\uc11c\ub294 \uc190\uc0c1\ub41c \uc54c\uac31\uc774\ub098 \uc774\ubb3c\uc9c8\uc744 \uace8\ub77c\ub0b4\uace0, \ud3ec\uc7a5\ud558\uae30 \uc88b\uac8c \uc815\ub9ac\ud55c\ub2e4. \uc791\uc740 \ubd09\uc9c0 \uc18d\uc5d0 \ub2f4\uaca8 \uc788\uc73c\ub2c8 \ub2e8\uc21c\ud55c \ubb3c\uac74\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc, \uadf8 \uc548\uc5d0\uc11c\ub3c4 \uc0c1\ud0dc\ub97c \ub9de\ucd94\ub294 \uc77c\uc774 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4. \uc9d1\uc5d0\uc11c \ub370\uc6b4 \uc54c\uac31\uc774 \uc911 \uc77c\ubd80\uac00 \ub0a8\uc558\ub2e4\uace0 \ud574\uc11c \ubaa8\ub450 \uac19\uc740 \uc774\uc720\ub85c \uc2e4\ud328\ud588\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \ud31d\ucf58\uc774 \ud130\uc9c0\ub824\uba74 \ub0b4\ubd80\uc758 \uc218\ubd84\uacfc \uc555\ub825\uc774 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud55c\ub2e4\ub294 \uc810\uc744 \uc54c\uba74, \uc54c\uac31\uc774\uc758 \uc0c1\ud0dc\uac00 \uc65c \ud544\uc694\ud55c\uc9c0 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \ud31d\ucf58 \ud55c \ud1b5\uc744 \uc870\uae08 \ucc9c\ucc9c\ud788 \ubcf4\uba74 \ubaa8\ub450 \uac19\uc740 \ubaa8\uc591\uc774 \uc544\ub2c8\ub2e4. \uc5ec\ub7ec \ubc29\ud5a5\uc73c\ub85c \ubc8c\uc5b4\uc9c4 \uac83\ub3c4 \uc788\uace0, \ube44\uad50\uc801 \ub465\uae00\uac8c \ubcf4\uc774\ub294 \uac83\ub3c4 \uc788\ub2e4. \uc5b4\ub290 \ucabd\uc774 \ub354 \uc7ac\ubbf8\uc788\uac8c \uc0dd\uacbc\ub294\uc9c0 \uace8\ub77c \ubcf4\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \uc791\uc740 \uad6c\uacbd\uc774 \ub41c\ub2e4. \ud31d\ucf58\uc6a9 \uc54c\uac31\uc774\ub3c4 \ubaa8\ub450 \uc131\uacf5\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc218\ubd84 \uc0c1\ud0dc\ub098 \uaecd\uc9c8\uc758 \uc190\uc0c1, \uac00\uc5f4 \uc870\uac74\uc774 \uc601\ud5a5\uc744 \uc900\ub2e4. \uadf8\ub798\uc11c \ubc14\ub2e5\uc5d0 \ub0a8\uc740 \uc54c\uac31\uc774\ub97c \ubcf4\uace0 \ubb34\uc870\uac74 \ub35c \uc775\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud130\uc9c0\uae30 \uc704\ud55c \uc870\uac74\uc744 \uac16\ucd94\uc9c0 \ubabb\ud588\uc744 \uc218\ub3c4 \uc788\ub2e4. \uae30\ub984 \uc5ed\uc2dc \ud31d\ucf58\uc758 \ud770 \ubd80\ubd84\uc744 \ub9cc\ub4dc\ub294 \uc7ac\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uae30\ub984\uc740 \uc870\ub9ac \uacfc\uc815\uc5d0\uc11c \uc5f4\uc744 \uc804\ub2ec\ud558\uace0 \ub9db\uc744 \ub354\ud560 \uc218 \uc788\uc9c0\ub9cc, \ub728\uac70\uc6b4 \uacf5\uae30\ub97c \uc774\uc6a9\ud574 \ub9cc\ub4dc\ub294 \ud31d\ucf58\ub3c4 \uc788\ub2e4. \ubcc0\uc2e0\uc758 \uc8fc\uc778\uacf5\uc740 \uc5ec\uc804\ud788 \uc625\uc218\uc218 \uc54c\uac31\uc774 \uc548\uc5d0 \uc788\ub2e4. \ubb3c\ub860 \uc774 \uc774\uc57c\uae30\ub294 \ud130\uc9c0\uc9c0 \uc54a\uc740 \uc54c\uac31\uc774\ub97c \uc5b5\uc9c0\ub85c \uc539\uc5b4 \ubcf4\ub77c\ub294 \uad8c\uc720\uac00 \uc544\ub2c8\ub2e4. \ud31d\ucf58 \uc0ac\uc774\uc5d0\uc11c \ub2e8\ub2e8\ud55c \uac83\uc774 \ub290\uaef4\uc9c0\uba74 \ub530\ub85c \uace8\ub77c\ub0b4\uba74 \ub41c\ub2e4. \uc6d0\ub9ac\ub97c \uc544\ub294 \uac83\uacfc \uc774\uac00 \ud574\uc57c \ud560 \uc77c\uc744 \ub298\ub9ac\ub294 \uac83\uc740 \ub2e4\ub978 \ubb38\uc81c\ub2e4. \uc54c\uac31\uc774\ub97c \ub370\uc6b0\uba74 \ub0b4\ubd80\uc758 \uc218\ubd84\uacfc \uc804\ubd84\uc774 \uc5f4\uc758 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4. \uc218\ubd84\uc774 \uc218\uc99d\uae30\ub85c \ubcc0\ud558\uace0 \uc555\ub825\uc774 \ucee4\uc9c0\ub294 \ub3d9\uc548 \ubc14\uae65\uc758 \uaecd\uc9c8\uc740 \uadf8 \ubcc0\ud654\ub97c \ud55c\ub3d9\uc548 \ubd99\uc7a1\ub294\ub2e4. \uaecd\uc9c8\uc774 \ud130\uc9c0\ub294 \uc21c\uac04 \uc548\ucabd\uc758 \uc870\uac74\uc774 \uac11\uc790\uae30 \ub2ec\ub77c\uc9c0\uace0 \uc804\ubd84\uc774 \ud33d\ucc3d\ud55c\ub2e4. \uc791\uc740 \uc54c\uac31\uc774\uac00 \ud070 \ud770 \ub369\uc5b4\ub9ac\ucc98\ub7fc \ubcc0\ud558\ub294 \ub370\uc5d0\ub294 \uc774 \uc548\uacfc \ubc16\uc758 \uad00\uacc4\uac00 \uc911\uc694\ud558\ub2e4. \uadf8\ub798\uc11c \ud31d\ucf58\uc740 \ud45c\uba74\uc744 \uc608\uc058\uac8c \ubd80\ud480\ub9ac\ub294 \uc7a5\uc2dd\uc774 \uc544\ub2c8\ub2e4. \uc5f4\uc744 \ubc1b\uc740 \uc7ac\ub8cc\uc640 \uac07\ud78c \uc218\ubd84, \ud130\uc9c8 \ub54c\uc758 \ubcc0\ud654\uac00 \uc774\uc5b4\uc9c4 \uacb0\uacfc\ub2e4. \ub2e4\ub9cc \uc5ec\uae30\uc11c \ud2b9\uc815 \uc628\ub3c4\uc640 \uc555\ub825\uc758 \uc815\ud655\ud55c \uac12\uc744 \uc0c8\ub85c \uce21\uc815\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc870\ub9ac \uc870\uac74\uc744 \uc218\uce58\ub85c \ub2e8\uc815\ud558\uc9c0 \uc54a\uc544\ub3c4 \uac89\uc774 \uc7a1\uc544 \uc8fc\ub358 \uc555\ub825\uc774 \ud480\ub9ac\uba70 \ubcc0\ud654\ud55c\ub2e4\ub294 \ud750\ub984\uc740 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ubc14\uc2f9 \ub9c8\ub974\uba74 \uc798 \ubcf4\uad00\ub420 \uac83 \uac19\uc9c0\ub9cc \ud31d\ucf58\uc5d0\uc11c\ub294 \ub0b4\ubd80 \uc218\ubd84\uc774 \ud130\uc9c0\ub294 \uc6d0\ub9ac\uc640 \uc5f0\uacb0\ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubb34\uc870\uac74 \ucd95\ucd95\ud558\uac8c \ub9cc\ub4e4\uba74 \ub41c\ub2e4\ub294 \ub73b\ub3c4 \uc544\ub2c8\ub2e4. \ub18d\uc5c5\ub3c4\uc11c\uad00\uc774 \uc218\ud655 \ub4a4 \uc801\uc808\ud55c \uc218\ubd84 \uc0c1\ud0dc\ub97c \ub9de\ucd94\ub294 \uacfc\uc815\uc744 \uc18c\uac1c\ud558\ub294 \uc774\uc720\ub2e4. \uc7ac\ub8cc\uc758 \uc870\uac74\uc744 \ub9de\ucd94\ub294 \uc77c\uc740 \uac00\uc5f4\ud558\uae30 \uc804\ubd80\ud130 \uc2dc\uc791\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc774 \uad00\uc810\uc5d0\uc11c \ud3ec\uc7a5\uc758 \uc54c\uac31\uc774\ub294 \uc790\uc5f0\uc5d0\uc11c \ubc14\ub85c \ub611\uac19\uc774 \ub098\uc628 \uc644\uc131\ud488\ucc98\ub7fc\ub9cc \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uace0\ub974\uace0 \ub9d0\ub9ac\uace0 \uc190\uc0c1\ub41c \uac83\uc744 \ubd84\ub9ac\ud558\ub294 \ub2e8\uacc4\uac00 \uc788\uc5c8\ub2e4. \ud55c \ubc88\uc5d0 \ub9ce\uc740 \uc591\uc774 \ube44\uc2b7\ud558\uac8c \ubc18\uc751\ud558\ub3c4\ub85d \uc900\ube44\ud558\ub294 \uac83\uc774\ub2e4. \uc74c\uc2dd\uc758 \ubcc0\uc2e0\uc744 \ubcf4\ub294 \uc7ac\ubbf8 \uc606\uc5d0 \uc7ac\ub8cc\ub97c \uc548\uc815\uc801\uc73c\ub85c \ub2e4\ub8e8\ub294 \uc0dd\uc0b0\uc758 \uc77c\uc774 \ud568\uaed8 \ubcf4\uc778\ub2e4. \ucee4\uc9c4 \ubd80\ubd84\uc740 \uc625\uc218\uc218 \uc548\uc758 \uc804\ubd84\uc774 \ud33d\ucc3d\ud55c \uacb0\uacfc\ub2e4. \uae30\ub984\uc774\ub098 \uc124\ud0d5\uc744 \ub123\uc5c8\uc744 \ub54c \uc0dd\uae34 \uac89\ubaa8\uc2b5\uacfc \uad6c\ubd84\ud574\uc11c \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ub9db\uc744 \ub354\ud558\uac70\ub098 \uc5f4\uc744 \uc804\ub2ec\ud558\ub294 \uc7ac\ub8cc\uac00 \uc788\uc5b4\ub3c4 \ubcc0\uc2e0\uc758 \uc911\uc2ec\uc740 \uc54c\uac31\uc774 \uc548\uc5d0 \uc788\ub2e4. \ub728\uac70\uc6b4 \uacf5\uae30\ub85c \ub9cc\ub4dc\ub294 \ubc29\uc2dd\ub3c4 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uadf8 \ucc28\uc774\ub97c \ubcf4\uc5ec \uc900\ub2e4. \uc644\uc131\ub41c \ud31d\ucf58\uc744 \ub2e4\uc2dc \uc6d0\ub798\uc758 \ub2e8\ub2e8\ud55c \uc54c\uac31\uc774\ub85c \ub2e8\uc21c\ud788 \uc811\uc5b4 \ub123\uc744 \uc218 \uc5c6\ub294 \uae4c\ub2ed\ub3c4 \ud615\ud0dc \ubcc0\ud654\uac00 \ub2e8\uc9c0 \uc870\uac01\uc744 \ud3b4 \ub193\uc740 \uc77c\uc774 \uc544\ub2c8\uae30 \ub54c\ubb38\uc774\ub2e4. \ubb3c\uacfc \uc804\ubd84\uc758 \uc0c1\ud0dc, \uaecd\uc9c8\uc758 \uad6c\uc870\uac00 \ud568\uaed8 \ubcc0\ud588\ub2e4. \uc774\uac83\uc744 \ubcf5\uc7a1\ud55c \ud654\ud559\uc2dd\uc73c\ub85c \uc124\uba85\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc548\ucabd \uc7ac\ub8cc\uac00 \uc5f4\uacfc \uc555\ub825\uc744 \uacaa\uc5c8\ub2e4\ub294 \ud750\ub984\uc744 \ub530\ub77c\uac08 \uc218 \uc788\ub2e4. \uac04\uc2dd \ud55c \uc54c\uc5d0\uc11c \ubb3c\uc9c8\uc758 \ubcc0\ud654\ub97c \ub9cc\ub098\ub294 \uc21c\uac04\uc774\ub2e4. \ud31d\ucf58 \ud55c \ud1b5\uc744 \uc870\uae08 \ucc9c\ucc9c\ud788 \ubcf4\uba74 \ubaa8\ub450 \uac19\uc740 \ubaa8\uc591\uc774 \uc544\ub2c8\ub2e4. \ub0a0\uac1c\ucc98\ub7fc \uc5ec\ub7ec \ubc29\ud5a5\uc73c\ub85c \ubc8c\uc5b4\uc9c4 \uac83\ub3c4 \uc788\uace0, \ube44\uad50\uc801 \ub465\uae00\uac8c \ubd80\ud47c \uac83\ub3c4 \uc788\ub2e4. \ud488\uc885\uacfc \uac00\uc5f4 \uc870\uac74\uc5d0 \ub530\ub77c \ubaa8\uc2b5\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \ud31d\ucf58\uc740 \uac04\uc2dd\uc774\uba74\uc11c \uc791\uc740 \uad6c\uacbd\uac70\ub9ac\uc774\uae30\ub3c4 \ud558\ub2e4. \ub611\uac19\uc740 \uae08\ud615\uc73c\ub85c \ucc0d\uc740 \uacfc\uc790\uc640 \ub2ec\ub9ac, \uc54c\uac31\uc774\ub9c8\ub2e4 \ud130\uc9c0\uace0 \uad73\uc740 \ud754\uc801\uc774 \ub0a8\ub294\ub2e4. \uac19\uc740 \ud1b5 \uc548\uc5d0\uc11c\ub3c4 \uc720\ub09c\ud788 \ud070 \uc870\uac01\uacfc \uc791\uc740 \uc870\uac01\uc774 \uc11e\uc5ec \uc788\ub2e4. \uc601\ud654\ub97c \ubcfc \ub54c \uc774 \ubaa8\ub4e0 \uacfc\uc815\uc744 \ub5a0\uc62c\ub9b4 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774\uc57c\uae30\uc758 \uc911\uc694\ud55c \uc7a5\uba74\uc5d0 \uc625\uc218\uc218\uc758 \uaecd\uc9c8\uc744 \uc5f0\uad6c\ud558\uace0 \uc788\uc744 \uc774\uc720\ub3c4 \uc5c6\ub2e4. \ub2e4\ub9cc \ub2e4\uc74c\uc5d0 \ud31d\ucf58\uc744 \uc9d1\uc5c8\uc744 \ub54c, \uadf8 \uac00\ubcbc\uc6b4 \uc870\uac01\uc774 \ud55c\ub54c\ub294 \ub2e8\ub2e8\ud55c \uc528\uc557\uc774\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc7a0\uae50 \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub2e4. \uc694\ub780\ud55c \uc18c\ub9ac\uc640 \ud568\uaed8 \ubc8c\uc5b4\uc9c0\ub294 \uc791\uc740 \ubcc0\uc2e0. \ud31d\ucf58\uc740 \uc601\ud654\uac00 \uc2dc\uc791\ub418\uae30\ub3c4 \uc804\uc5d0 \uc790\uae30 \ubaab\uc758 \uc9e7\uc740 \uc7a5\uba74\uc744 \ub05d\ub0b8 \uc148\uc774\ub2e4."}, {"id": "princess-crescent-comb", "title": "\uc791\uc740 \ubc18\ub2ec\uc740 \uba38\ub9ac\ub97c \ube57\ub294 \ub3c4\uad6c\uc600\ub2e4", "summary": "\ub098\ubb34\ub85c \ub9cc\ub4e0 \uc791\uc740 \uc5bc\ub808\ube57\uc774 \ub0af\uc120 \uc655\uc2e4 \uc778\ubb3c\uc744 \uac00\uae4c\uc774 \ub370\ub824\uc635\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\uc637\uacfc \uc7ac\ub8cc", "categories": ["everyday-inventions"], "url": "stories/princess-crescent-comb/index.html", "image": "../media/princess-crescent-comb.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc5bc\ub808\ube57 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc791\uc740 \ubc18\ub2ec\uc740 \uba38\ub9ac\ub97c \ube57\ub294 \ub3c4\uad6c\uc600\ub2e4 \ud654\ud611\uc639\uc8fc\uc758 \ube57\uc5d0\uc11c \ubc1c\uacac\ud558\ub294 \uc77c\uc0c1\uc758 \ubaa8\uc591 \ub098\ubb34\ub85c \ub9cc\ub4e0 \uc791\uc740 \uc5bc\ub808\ube57\uc774 \ub0af\uc120 \uc655\uc2e4 \uc778\ubb3c\uc744 \uac00\uae4c\uc774 \ub370\ub824\uc635\ub2c8\ub2e4. \uc637\uacfc \uc7ac\ub8cc \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \uc791\uc740 \uac08\uc0c9 \uc870\uac01\uc774 \ubc18\ub2ec\ucc98\ub7fc \uad7d\uc5b4 \uc788\ub2e4. \uc544\ub798\ucabd\uc758 \ube57\uc0b4\uc744 \ubcf4\uae30 \uc804\uc5d0\ub294 \ubb34\uc2a8 \ubb3c\uac74\uc778\uc9c0 \uc7a0\uae50 \uace0\uac1c\ub97c \uae30\uc6b8\uc774\uac8c \ub41c\ub2e4. \uc774\ub984\uc740 \uc5bc\ub808\ube57\uc774\ub2e4. \uad81\uc911 \uc720\ubb3c\uc774\ub77c\uace0 \ud558\uba74 \uba3c\uc800 \ucee4\ub2e4\ub780 \uc655\uad00\uc774\ub098 \ud654\ub824\ud55c \uc758\ubcf5\uc744 \ub5a0\uc62c\ub9ac\uc9c0\ub9cc, \uba38\ub9ac\ub97c \uc815\ub3c8\ud558\ub294 \uc791\uc740 \ub3c4\uad6c\ub3c4 \ub0a8\uc544 \uc788\ub2e4. \uc774 \ube57\uc740 \ud654\ud611\uc639\uc8fc\uc758 \ubb18\uc5d0\uc11c \ucd9c\ud1a0\ub41c \uac83\uc73c\ub85c \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc18c\uac1c\ud55c\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc740 \ud615\ud0dc\ub97c \ud3c9\ud3c9\ud55c \ubc18\ub2ec \ubaa8\uc591\uc774\ub77c\uace0 \ud558\uace0, \ube57\uc0b4\uc740 \ud55c\ucabd\uc73c\ub85c\ub9cc \ub098 \uc788\ub2e4\uace0 \uc801\ub294\ub2e4. \uc0ac\uc9c4\uc744 \ubcf4\uba74 \ub465\uadfc \ub4f1\uacfc \ube57\uc0b4\uc774 \uc788\ub294 \uac00\uc7a5\uc790\ub9ac\uac00 \uc11c\ub85c \ub2e4\ub978 \uc120\uc744 \ub9cc\ub4e0\ub2e4. \uc774 \ube57\uc758 \uc7ac\ub8cc\ub294 \ub098\ubb34\ub2e4. \ubd89\uc740 \uce60\uc744 \ub73b\ud558\ub294 \uc8fc\uce60\uc740 \ub4f1\ub9c8\ub8e8\uc5d0 \ud588\ub2e4\uace0 \ud55c\ub2e4. \uc0ac\uc9c4 \uc804\uccb4\uac00 \ubd89\uc740\uc0c9\uc73c\ub85c \uc120\uba85\ud558\uc9c0 \uc54a\ub354\ub77c\ub3c4, \ud604\uc7ac \ubaa8\uc2b5\uacfc \uc124\uba85\uc5d0 \ub0a8\uc740 \uc81c\uc791 \ud2b9\uc9d5\uc744 \ud568\uaed8 \uc77d\uc73c\uba74 \ub193\uce58\uae30 \uc26c\uc6b4 \ubd80\ubd84\uc744 \ubc1c\uacac\ud560 \uc218 \uc788\ub2e4. \ud654\ud611\uc639\uc8fc\ub294 1733\ub144\uc5d0 \ud0dc\uc5b4\ub098 1752\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub09c \uc778\ubb3c\uc774\ub2e4. \ubc15\ubb3c\uad00\uc774 \uc54c\ub824 \uc8fc\ub294 \uc0dd\ubab0\ub144\uacfc \ucd9c\ud1a0 \uc7a5\uc18c\uac00 \uc774 \uc791\uc740 \ube57\uc744 \ud2b9\uc815\ud55c \uc778\ubb3c\uc758 \ud754\uc801\uacfc \uc774\uc5b4 \uc900\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc2e4\uc81c\ub85c \uc5b4\ub290 \ub0a0 \uc5b4\ub5a4 \uba38\ub9ac\ub97c \ube57\uc5c8\ub294\uc9c0\uae4c\uc9c0 \uc7ac\ud604\ud560 \uc218\ub294 \uc5c6\ub2e4. \ubb18\uc5d0\uc11c \ub098\uc654\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc0dd\uc804\uc758 \uc0ac\uc6a9 \uc7a5\uba74\uc740 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc0c1\uc0c1\uc758 \ub300\ud654\ub97c \ubd99\uc774\uc9c0 \uc54a\uc544\ub3c4, \uc6b0\ub9ac\uac00 \uc544\ub294 \ube57\uc774\ub77c\ub294 \ubb3c\uac74\ub9cc\uc73c\ub85c \ub0af\uc120 \uc0ac\ub78c\uacfc\uc758 \uac70\ub9ac\uac00 \uc870\uae08 \uc904\uc5b4\ub4e0\ub2e4. \uac00\ub85c 4.9\uc13c\ud2f0\ubbf8\ud130\ub77c\ub294 \uc218\uce58\ub294 \uc791\uc740 \ubb3c\uac74\uc758 \uc2e4\uac10\uc744 \uc900\ub2e4. \uc655\uc2e4 \uc778\ubb3c\uacfc \uad00\uacc4\ub41c \uc720\ubb3c\uc774\ub77c\uace0 \uc5b8\uc81c\ub098 \uac70\ub300\ud558\uace0 \ud654\ub824\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc190\uc5d0 \ub4e4\uace0 \uba38\ub9ac\ub97c \uc815\ub9ac\ud558\ub294 \ub3c4\uad6c\uc758 \ud06c\uae30\uc5d0\uc11c \uadf8 \uc0dd\ud65c\uc744 \ub9cc\ub0a0 \uc218\ub3c4 \uc788\ub2e4. \ub2e4\ub9cc \uc6b0\ub9ac\uac00 \uc775\uc219\ud558\uac8c \uc0ac\uc6a9\ud558\ub294 \ube57\uacfc \uc4f0\ub294 \ubc29\uc2dd\uc774 \ubaa8\ub4e0 \uc810\uc5d0\uc11c \uac19\uc558\ub2e4\uace0 \ub2e8\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc0ac\uc9c4\uc740 \ud655\ub300\ub418\uc5b4 \ubcf4\uc774\uae30 \ub54c\ubb38\uc5d0 \ud06c\uae30 \ud45c\uae30\ub97c \ud568\uaed8 \uc77d\ub294 \uc77c\uc774 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ud654\uba74\uc744 \uac00\ub4dd \ucc44\uc6b4 \uc720\ubb3c\uc774 \uc2e4\uc81c\ub85c\ub294 \uc190 \uc548\uc5d0 \ub4e4\uc5b4\uc624\ub294 \ubb3c\uac74\uc77c \uc218 \uc788\ub2e4. \ub465\uadfc \ub4f1\uacfc \ucd18\ucd18\ud55c \ube57\uc0b4\uc744 \ubcf8 \ub4a4 \uc22b\uc790\ub97c \ub3cc\uc544\ubcf4\uba74 \uac19\uc740 \uc774\ubbf8\uc9c0\uc758 \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ubaa8\uc591\uacfc \uce58\uc218\ub294 \uc11c\ub85c \ub2e4\ub978 \uc815\ubcf4\ub97c \ubcf4\ud0dc \uc900\ub2e4. \ub465\uadfc \ub4f1\ub9c8\ub8e8\uc640 \ube57\uc0b4\uc774 \ub09c \ucabd\uc740 \uac19\uc740 \uc724\uacfd \uc548\uc5d0\uc11c \ub2e4\ub978 \uae30\ub2a5\uc744 \uac16\ub294\ub2e4. \uc190\uc73c\ub85c \uc7a1\ub294 \ubd80\ubd84\uacfc \uba38\ub9ac\uce74\ub77d\uc744 \uc815\ub9ac\ud558\ub294 \ubd80\ubd84\uc744 \ub098\ub204\uc5b4 \uc0dd\uac01\ud558\uba74 \ud615\ud0dc\uac00 \ucd94\uc0c1\uc801\uc778 \uc7a5\uc2dd\uc5d0\uc11c \ub3c4\uad6c\ub85c \ubc14\ub010\ub2e4. \uc65c \uc5b4\ub5a4 \uac00\uc7a5\uc790\ub9ac\ub294 \ub9e4\ub048\ud558\uace0 \ub2e4\ub978 \ucabd\uc740 \ub098\ub258\uc5b4 \uc788\ub294\uc9c0 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \uc775\uc219\ud55c \ubb3c\uac74\uc758 \uad6c\uc870\ub97c \ub2e4\uc2dc \ubcf4\ub294 \ubc29\ubc95\uc774\ub2e4. \ubc15\ubb3c\uad00\uc774 \ub4f1\ub9c8\ub8e8\uc758 \uc8fc\uce60\uc744 \ub530\ub85c \uc124\uba85\ud558\ub294 \uc810\ub3c4 \uc774\ub7f0 \uad6c\ubd84\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc804\uccb4\ub97c \ud55c \uac00\uc9c0 \uc0c9\uc758 \ubb3c\uac74\uc73c\ub85c\ub9cc \uae30\uc5b5\ud558\uc9c0 \ub9d0\uace0 \uce60\ud55c \uc790\ub9ac\uc640 \ube57\uc0b4\uc758 \uad00\uacc4\ub97c \uc0b4\ud3b4\ubcf4\uba74 \ub41c\ub2e4. \uc0ac\uc9c4\uc758 \ud604\uc7ac \uc0c9\uacfc \uc81c\uc791 \ub2f9\uc2dc\uc758 \uc0c1\ud0dc\uac00 \uc644\uc804\ud788 \uac19\uc73c\ub9ac\ub77c\uace0 \uac00\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uae30\ub85d\ub41c \uae30\ubc95\uc774 \uad00\ucc30\uc744 \ub3d5\uace0 \uad00\ucc30\uc740 \uadf8 \uc124\uba85\uc744 \uad6c\uccb4\uc801\uc73c\ub85c \ub9cc\ub4e0\ub2e4. \ud654\ud611\uc639\uc8fc\uc758 \ubb18\uc5d0\uc11c \ub098\uc654\ub2e4\ub294 \uc815\ubcf4\ub294 \uc774\ub984 \uc5c6\ub294 \ube57\uc744 \ud2b9\uc815\ud55c \uc5ed\uc0ac\uc801 \uc778\ubb3c\uc758 \uc790\ub8cc\uc640 \uc774\uc5b4 \uc900\ub2e4. \uc0dd\ubab0\ub144\uc744 \ud568\uaed8 \uc54c\uba74 \ubb3c\uac74\uc774 \ub193\uc778 \uc2dc\uac04\uc758 \ub9e5\ub77d\ub3c4 \uc0dd\uae34\ub2e4. \uadf8\ub7ec\ub098 \ubb18\uc5d0 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc0b4\uc544 \uc788\uc744 \ub54c \uc5b4\ub290 \ub0a0 \uc9c1\uc811 \uc0ac\uc6a9\ud588\ub2e4\ub294 \uc7a5\uba74\uc740 \ub2e4\ub974\ub2e4. \ubc1c\uacac\uc758 \uad00\uacc4\uc640 \uad6c\uccb4\uc801\uc778 \uc0dd\ud65c\uc758 \uc7ac\uad6c\uc131\uc744 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uadf8\ub798\uc11c \uc774 \uae00\uc5d0\uc11c\ub294 \uba38\ub9ac\ub97c \ube57\uc5b4 \uc8fc\ub294 \ub300\ud654\ub098 \ub2f9\uc2dc \ubc29\uc758 \ubaa8\uc2b5\uc744 \uc0c8\ub85c \ub9cc\ub4e4\uc9c0 \uc54a\ub294\ub2e4. \uadf8\ub7f0 \uc7a5\uba74\uc774 \uc5c6\uc5b4\ub3c4 \uc0ac\ub78c\ub4e4\uc774 \ubab8\uc744 \uac00\uafb8\uba70 \uc4f0\ub358 \ub3c4\uad6c\ub77c\ub294 \uc810\uc774 \uac70\ub9ac\ub97c \uc904\uc5ec \uc900\ub2e4. \uc655\uc2e4\uc758 \uc774\ub984\uc744 \ubaa8\ub974\ub358 \ub3c5\uc790\uc5d0\uac8c\ub3c4 \ube57\uc774\ub77c\ub294 \ubb3c\uac74\uc740 \uce5c\uc219\ud558\ub2e4. \uc775\uc219\ud55c \uae30\ub2a5\uc774 \ub0af\uc120 \uc0ac\ub78c\uc744 \ub9cc\ub098\ub294 \uc791\uc740 \uc785\uad6c\uac00 \ub41c\ub2e4. \ubaa9\uc7ac\uc5d0 \ube57\uc0b4\uc744 \ub9cc\ub4e0 \ubb3c\uac74\uc740 \ub2e8\ub2e8\ud55c \uae08\uc18d \ub369\uc5b4\ub9ac\uc640 \ub2e4\ub978 \uad6c\uc870\ub97c \uac00\uc9c4\ub2e4. \uc791\uc740 \ubd80\ubd84\ub4e4\uc774 \ubc18\ubcf5\ub418\uba74\uc11c \ud558\ub098\uc758 \uc4f0\uc784\uc744 \uc774\ub8ec\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4\uc744 \ubcf4\uace0 \ubaa8\ub4e0 \uc190\uc0c1\uc758 \uc6d0\uc778\uc774\ub098 \ub545\uc18d\uc5d0\uc11c\uc758 \ubcc0\ud654\ub97c \uc0c8\ub85c \ud310\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc7ac\ub8cc\uc640 \ud615\ud0dc\ub97c \uc54c\uc544\ubcf4\ub294 \uc77c\uacfc \ubcf4\uc874 \uacfc\uc815\uc744 \uc124\uba85\ud558\ub294 \uc77c\uc740 \ub2e4\ub978 \uadfc\uac70\ub97c \uc694\uad6c\ud55c\ub2e4. \ud604\uc7ac \ub0a8\uc740 \ubaa8\uc2b5\uc744 \ucda9\ubd84\ud788 \ubcf4\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \uc9c8\ubb38\uc740 \ub298\uc5b4\ub09c\ub2e4. \uc65c \uc774 \uc815\ub3c4 \ud06c\uae30\ub85c \ub9cc\ub4e4\uc5c8\uc744\uc9c0, \uc5b4\ub290 \ucabd\uc744 \uc950\uac8c \ub418\ub294\uc9c0, \uce60\uc740 \uc5b4\ub514\uc5d0 \ub193\uc600\ub294\uc9c0 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ubaa8\ub4e0 \uc9c8\ubb38\uc5d0 \ud655\uc815\ub41c \ub2f5\uc744 \ubd99\uc774\uc9c0 \uc54a\uc544\ub3c4 \uc88b\ub2e4. \uc791\uc740 \ubc18\ub2ec\uc740 \ud654\ub824\ud55c \uc655\uc2e4\uc758 \uc774\ubbf8\uc9c0 \uc606\uc5d0 \ubab8\uacfc \uc190\uc758 \uc77c\uc0c1\uc774\ub77c\ub294 \ub610 \ub2e4\ub978 \uc2dc\uac04\uc744 \ub193\uc544 \uc900\ub2e4. \uc18c\uc7a5\ud488 \uc815\ubcf4\uc758 \uac00\ub85c \uae38\uc774\ub294 4.9\uc13c\ud2f0\ubbf8\ud130\ub2e4. \uc22b\uc790\ub97c \uc77d\uace0 \uc0ac\uc9c4\uc744 \ub2e4\uc2dc \ubcf4\uba74 \ucc98\uc74c\uc5d0 \uc9d0\uc791\ud588\ub358 \uac83\ubcf4\ub2e4 \ub354 \uc791\uc740 \ubb3c\uac74\uc73c\ub85c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ud654\uba74\uc5d0\uc11c \ud06c\uac8c \ubcf8\ub2e4\uace0 \uc2e4\uc81c \ubb3c\uac74\ub3c4 \ucee4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774 \ube57\uc5d0\uc11c \ud2b9\ubcc4\ud55c \ube44\ubc00\uc744 \ucc3e\uc73c\ub824\uace0 \uc560\uc4f8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub098\ubb34\ub97c \ub2e4\ub4ec\uace0 \ud55c\ucabd\uc5d0 \ube57\uc0b4\uc744 \ub0b4\uace0 \ub4f1\uc5d0 \ubd89\uc740 \uce60\uc744 \ud588\ub2e4\ub294 \uac83. \uadf8\ub7f0 \uad6c\uccb4\uc801\uc778 \ubaa8\uc2b5\uc774 \uc624\ub798\uc804\uc758 \uc0dd\ud65c\uc744 \ub5a0\uc62c\ub9b4 \ucd9c\ubc1c\uc810\uc774 \ub41c\ub2e4. \ubc18\ub2ec \ubaa8\uc591 \ud558\ub098\uac00 \uc778\ubb3c\uc758 \uae34 \uc124\uba85\ubcf4\ub2e4 \uc624\ub798 \uae30\uc5b5\ub420 \ub54c\ub3c4 \uc788\ub2e4."}, {"id": "railway-air-brakes-stopping-train", "title": "\ucca0\ub3c4\ub97c \ubc14\uafbc \uac83\uc740 \ub2ec\ub9ac\ub294 \ud798\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4", "summary": "\ucca0\ub3c4\uc758 \uc18d\ub3c4 \ub4a4\uc5d0 \uc788\uc5c8\ub358 \uc81c\ub3d9 \ub178\ub3d9\uacfc \uc5f0\uc18d\u00b7\uc790\ub3d9 \ube0c\ub808\uc774\ud06c\uc758 \uc0dd\uac01\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\uc774\ub3d9\uacfc \uc6b4\uc1a1", "categories": ["everyday-inventions"], "url": "stories/railway-air-brakes-stopping-train/index.html", "image": "../media/railway-air-brakes-stopping-train.png", "alt": "\uc815\ucc28\ud55c \uc99d\uae30\uae30\uad00\ucc28\uc640 \ucc28\ub7c9 \uc0ac\uc774\uc758 \uc5f0\uacb0\uc744 \ub545\uc5d0\uc11c \uc0b4\ud53c\ub294 \ucca0\ub3c4 \ub178\ub3d9\uc790\ub4e4\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ucca0\ub3c4\ub97c \ubc14\uafbc \uac83\uc740 \ub2ec\ub9ac\ub294 \ud798\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4 \ucc28\ub7c9 \uc0ac\uc774\ub97c \uac74\ub108\ub358 \uc81c\ub3d9\uc218\uc5d0\uc11c \uc5f0\uacb0\ub41c \ube0c\ub808\uc774\ud06c\uae4c\uc9c0 \ucca0\ub3c4\uc758 \uc18d\ub3c4 \ub4a4\uc5d0 \uc788\uc5c8\ub358 \uc81c\ub3d9 \ub178\ub3d9\uacfc \uc5f0\uc18d\u00b7\uc790\ub3d9 \ube0c\ub808\uc774\ud06c\uc758 \uc0dd\uac01\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc774\ub3d9\uacfc \uc6b4\uc1a1 \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \uae30\ucc28\uc758 \ubc1c\uba85\uc774\ub77c\uace0 \ud558\uba74 \uba3c\uc800 \ud798\uc13c \uc99d\uae30\uae30\uad00\ucc28\ub97c \ub5a0\uc62c\ub9b0\ub2e4. \ud558\uc9c0\ub9cc \ub354 \ube68\ub9ac \ub2ec\ub9b4 \uc218 \uc788\ub2e4\ub294 \uac83\uc740 \ub354 \uc798 \uba48\ucd9c \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4\ub294 \ub73b\uc774\uae30\ub3c4 \ud558\ub2e4. \ubb34\uac70\uc6b4 \uac1d\ucc28\uc640 \ud654\ucc28\uac00 \uae38\uac8c \uc774\uc5b4\uc9c4 \ub4a4\uc5d0\ub294 \uae30\uad00\ucc28 \ud55c \ub300\uc758 \ub2a5\ub825\ub9cc\uc73c\ub85c \ud480\uae30 \uc5b4\ub824\uc6b4 \ubb38\uc81c\uac00 \uc0dd\uae34\ub2e4. \ucd08\uae30\uc758 \ucca0\ub3c4\uc5d0\uc11c\ub294 \uc81c\ub3d9\uc218\uac00 \ucc28\ub7c9 \uc0ac\uc774\ub97c \uc774\ub3d9\ud558\uba70 \ube0c\ub808\uc774\ud06c\ub97c \ub2e4\ub8e8\uae30\ub3c4 \ud588\ub2e4. \ubc1c\uc804\uc758 \uc5ed\uc0ac\ub97c \uae30\uc220\uc790\uc758 \uc774\ub984\uc73c\ub85c\ub9cc \uc77d\uc73c\uba74 \uadf8 \uc704\ud5d8\ud55c \uc77c\uc740 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc624\ud508\uc2a4\ud0dd\uc2a4\uc640 \uc61b \uae30\uc220 \ud574\uc124\uc11c \u300e\uc5b4\ub5bb\uac8c \uc791\ub3d9\ud558\ub294\uac00\u300f\ub97c \ud568\uaed8 \uc77d\uc73c\uba70 \uba48\ucd94\ub294 \uae30\uc220\uc758 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubcf4\uc790. \uae30\ucc28\ub294 \ud55c \ub369\uc5b4\ub9ac\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc \uc5ec\ub7ec \ucc28\ub7c9\uc774 \uc5f0\uacb0\ub418\uc5b4 \uc788\ub2e4. \uae30\uad00\ucc28\uc758 \ucd94\uc9c4\uc744 \uc904\uc600\ub2e4\uace0 \ub4a4\uc5d0 \uc774\uc5b4\uc9c4 \ubaa8\ub4e0 \ucc28\uc758 \uc6c0\uc9c1\uc784\uc774 \uace7\ubc14\ub85c \uc0ac\ub77c\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uae34 \uc5f4\ucc28 \uc804\uccb4\uc758 \ubb34\uac8c\uc640 \uc18d\ub3c4\ub97c \ub2e4\ub8e8\uc5b4\uc57c \ud55c\ub2e4. \uc55e\uc5d0\uc11c \ud798\uc744 \ub0b4\ub294 \ubb38\uc81c\uc640 \uac01 \ucc28\ub7c9\uc5d0\uc11c \uc6c0\uc9c1\uc784\uc744 \uc904\uc774\ub294 \ubb38\uc81c\ub294 \ub2e4\ub974\ub2e4. \ube0c\ub808\uc774\ud06c\ub294 \ubc14\ud034\uc758 \uc6c0\uc9c1\uc784\uc744 \uc904\uc774\ub294 \ud798\uc744 \ub9cc\ub4e4\uc5b4\uc57c \ud558\uace0, \uadf8 \ud798\uc774 \ud544\uc694\ud55c \ucc28\ub7c9\ub4e4\uc5d0 \ub9de\ucd94\uc5b4 \uc804\ub2ec\ub418\uc5b4\uc57c \ud55c\ub2e4. \uae30\uad00\uc0ac\uc5d0\uac8c \uba48\ucd94\ub77c\ub294 \uc758\uc0ac\uac00 \uc788\uc5b4\ub3c4 \ub4a4\uc5d0\uc11c \uadf8 \uc758\uc0ac\uac00 \uc791\ub3d9\ud558\uc9c0 \uc54a\uc73c\uba74 \ubd80\uc871\ud558\ub2e4. \uc5f4\ucc28\uac00 \uae38\uc5b4\uc9c8\uc218\ub85d \uc81c\ub3d9\uc740 \uc7a5\uce58 \ud558\ub098\ubcf4\ub2e4 \uc2e0\ud638\uc640 \ud798\uc744 \ud568\uaed8 \uc804\ub2ec\ud558\ub294 \uccb4\uacc4\uc758 \ubb38\uc81c\uac00 \ub41c\ub2e4. \uc624\ud508\uc2a4\ud0dd\uc2a4\ub294 \ucca0\ub3c4 \ub178\ub3d9\uc790\ub4e4\uc774 \ub2ec\ub9ac\ub294 \ucc28\ub7c9 \uc0ac\uc774\ub97c \uac74\ub108\uba70 \uc218\ub3d9 \uc81c\ub3d9\uc744 \ud574\uc57c \ud588\ub358 \uc704\ud5d8\uc744 \uc124\uba85\ud55c\ub2e4. \uaca8\uc6b8\uc774\ub098 \ube44 \uc624\ub294 \ub0a0\uc744 \ud2b9\ubcc4\ud788 \uc0c1\uc0c1\ud558\uc9c0 \uc54a\ub354\ub77c\ub3c4 \uc6c0\uc9c1\uc774\ub294 \ub192\uc740 \uacf3\uc5d0\uc11c \uc77c\ud55c\ub2e4\ub294 \uc0ac\uc2e4 \uc790\uccb4\uac00 \ubd80\ub2f4\uc774\ub2e4. \ube60\ub978 \uc6b4\uc1a1\uc774 \uac00\ub2a5\ud574\uc9c4 \ub9cc\ud07c \ub204\uad70\uac00\ub294 \uadf8 \uc18d\ub3c4 \uac00\uae4c\uc774\uc5d0\uc11c \uc704\ud5d8\uc744 \uac10\ub2f9\ud588\ub2e4. \ubaa8\ub4e0 \uc2dc\ub300\uc640 \uc9c0\uc5ed\uc5d0\uc11c \uc815\ud655\ud788 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc77c\ud588\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \u300e\uc5b4\ub5bb\uac8c \uc791\ub3d9\ud558\ub294\uac00\u300f\ub3c4 \uae30\uad00\ucc28\uc640 \ucc28\uc7a5 \ucc28\ub7c9\uc758 \ube0c\ub808\uc774\ud06c, \uc5ec\ub7ec \uc2dc\ub3c4\uc758 \ucc28\uc774\ub97c \uc124\uba85\ud55c\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uc5b4\ub290 \ud55c \ub098\ub77c\uc758 \uc7a5\uba74\uc744 \uc804\uccb4 \ucca0\ub3c4\uc758 \ud48d\uacbd\uc73c\ub85c \ud655\ub300\ud558\uae30\ubcf4\ub2e4, \uc0ac\ub78c\uc758 \uc774\ub3d9\uacfc \uac1c\ubcc4 \uc870\uc791\uc5d0 \ud06c\uac8c \uae30\ub300\ub358 \ubb38\uc81c\ub97c \uc774\ud574\ud558\ub294 \uac83\uc774\ub2e4. \uc61b \ud574\uc124\uc11c\uc5d0\ub294 \uc5f4\ucc28\ub97c \ub530\ub77c \uae34 \uc1e0\uc0ac\uc2ac\uc744 \ub450\uace0 \uac01 \ucc28\ub7c9\uc758 \uc7a5\uce58\uc640 \uc5f0\uacb0\ud558\ub294 \uc2dc\ub3c4\uac00 \ub098\uc628\ub2e4. \ud55c\uacf3\uc5d0\uc11c \ub2f9\uae30\uba74 \uc5ec\ub7ec \ube0c\ub808\uc774\ud06c\ub97c \uc6c0\uc9c1\uc774\uac8c \ud558\ub824\ub294 \uc0dd\uac01\uc774\ub2e4. \ud558\uc9c0\ub9cc \uc5f0\uacb0\uc758 \uae38\uc774\uc640 \ud798\uc774 \uade0\uc77c\ud558\uc9c0 \uc54a\uc73c\uba74 \uc5b4\ub290 \ubd80\ubd84\ub9cc \uba3c\uc800 \uc791\ub3d9\ud560 \uc218 \uc788\ub2e4. \uc8fc\ub41c \uc0ac\uc2ac\uc774 \ub04a\uc5b4\uc9c0\ub294 \uacbd\uc6b0\ub3c4 \ubb38\uc81c\uc600\ub2e4. \uc774\ub7f0 \uc2e4\ud328\ub294 \uc61b \uae30\uc220\uc790\uac00 \ub2e8\uc21c\ud574\uc11c \uc0dd\uae34 \uc6c3\uc744 \uc77c\ub9cc\uc740 \uc544\ub2c8\ub2e4. \ud574\uacb0\ud574\uc57c \ud560 \uc870\uac74\uc744 \ud558\ub098\uc529 \ub4dc\ub7ec\ub0b8\ub2e4. \ubaa8\ub4e0 \ucc28\uc5d0 \ud798\uc744 \ubcf4\ub0bc \uac83, \ud544\uc694\ud55c \ub9cc\ud07c \uc870\uc808\ud560 \uac83, \uc5f0\uacb0\uc5d0 \ubb38\uc81c\uac00 \uc0dd\uacbc\uc744 \ub54c\ub3c4 \uc548\uc804\uc744 \uc0dd\uac01\ud560 \uac83. \uba48\ucd94\ub294 \uae30\uc220\uc740 \uc774\ub7f0 \uc694\uad6c\ub97c \ud568\uaed8 \ub9cc\uc871\uc2dc\ud0a4\ub294 \ubc29\ud5a5\uc73c\ub85c \ubc14\ub00c\uc5c8\ub2e4. \uc99d\uae30\ub85c \uac01 \ucc28\ub7c9\uc758 \ube0c\ub808\uc774\ud06c\ub97c \uc791\ub3d9\uc2dc\ud0a4\ub824\ub294 \uc2dc\ub3c4\ub3c4 \uc788\uc5c8\ub2e4. \uae30\uad00\ucc28\uc5d0\uc11c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \ud798\uc744 \ub4a4\ub85c \ubcf4\ub0b4\uba74 \ub420 \uac83 \uac19\uc9c0\ub9cc, \uae34 \uad00\uc744 \uc9c0\ub098\ub294 \ub3d9\uc548 \uc99d\uae30\uac00 \uc2dd\uc5b4 \ubb3c\uc774 \ub418\ub294 \uc77c\uc774 \uc0dd\uae34\ub2e4. \ucd94\uc6b4 \ud658\uacbd\uacfc \uc5f4\ucc28 \ub4a4\ucabd\uc758 \uc870\uac74\uc740 \uc55e\ucabd\uacfc \ub2e4\ub974\ub2e4. \uc774\uac83\uc740 \ud070 \uae30\uacc4\ub97c \uc791\uac8c \uc5ec\ub7ec \ubc88 \ubd99\uc774\uba74 \ub41c\ub2e4\ub294 \uc0dd\uac01\uc758 \ud55c\uacc4\ub2e4. \ud798\uc774 \ucd9c\ubc1c\ud55c \uc7a5\uc18c\uc5d0\uc11c \uc791\ub3d9\ud55c \uc6d0\ub9ac\uac00 \uae34 \uac70\ub9ac\uc758 \ub05d\uc5d0\uc11c\ub3c4 \ub611\uac19\uc774 \uc720\uc9c0\ub418\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uc5f4\ucc28\uc758 \uae38\uc774\ub294 \ub2e8\uc9c0 \ub354 \ub9ce\uc740 \uc2b9\uac1d\uc744 \uc2e3\ub294 \uaddc\ubaa8\uac00 \uc544\ub2c8\ub77c, \ud798\uc744 \uc804\ub2ec\ud558\ub294 \ud658\uacbd\uc744 \ubc14\uafb8\ub294 \uc870\uac74\uc774\uc5c8\ub2e4. \uc774\ud6c4 \uc911\uc694\ud55c \ubc29\ud5a5\uc740 \uacf5\uae30\uc758 \uc555\ub825 \ucc28\uc774\ub97c \uc774\uc6a9\ud558\ub294 \uac83\uc774\uc5c8\ub2e4. \uc555\ucd95 \uacf5\uae30\ub97c \uc4f0\ub294 \uacc4\ud1b5\uacfc \uc9c4\uacf5\uc744 \uc774\uc6a9\ud558\ub294 \uacc4\ud1b5\uc740 \uad6c\uccb4\uc801\uc778 \ubc29\uc2dd\uc774 \ub2e4\ub974\uc9c0\ub9cc, \uad00\uc73c\ub85c \uc774\uc5b4\uc9c4 \uc0c1\ud0dc\ub97c \uc774\uc6a9\ud574 \uc5ec\ub7ec \ucc28\ub7c9\uc758 \uc81c\ub3d9\uc744 \ub2e4\ub8ec\ub2e4\ub294 \uc0dd\uac01\uc744 \uacf5\uc720\ud55c\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294 \uacf5\uae30\uac00 \uc5f4\ucc28 \uc804\uccb4\ub97c \uc5f0\uacb0\ud558\ub294 \ub9e4\uac1c\uac00 \ub41c\ub2e4. \uc624\ud508\uc2a4\ud0dd\uc2a4\ub294 \uc870\uc9c0 \uc6e8\uc2a4\ud305\ud558\uc6b0\uc2a4\uc758 \uacf5\uae30 \ube0c\ub808\uc774\ud06c\ub97c 1869\ub144\uc758 \ubcc0\ud654\ub85c \uc18c\uac1c\ud55c\ub2e4. \ub2e4\ub9cc \ucd08\uae30 \uc7a5\uce58\uc640 \ub4a4\uc5d0 \ubc1c\uc804\ud55c \uc790\ub3d9 \uc81c\ub3d9\uc744 \ud55c \ubc88\uc758 \ub3d9\uc77c\ud55c \ubc1c\uba85\uc73c\ub85c \uc11e\uc9c0\ub294 \ub9d0\uc544\uc57c \ud55c\ub2e4. \uc548\uc815\uc801\uc778 \uccb4\uacc4\ub294 \uac1c\uc120\uc744 \uac70\uce58\uba70 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4. \uc9c0\uae08\uc758 \ubaa8\ub4e0 \ucca0\ub3c4\ucc28\ub7c9\uc774 \uc61b \ucc45\uacfc \uac19\uc740 \uc7a5\uce58\ub85c \uc6c0\uc9c1\uc778\ub2e4\ub294 \ub73b\ub3c4 \uc544\ub2c8\ub2e4. \uc61b \ud574\uc124\uc11c\uac00 \uac15\uc870\ud558\ub294 \uc790\ub3d9 \ube0c\ub808\uc774\ud06c\uc758 \uc911\uc694\ud55c \uc870\uac74\uc740 \uc5f4\ucc28\uac00 \ub098\ub258\ub294 \uc0ac\uace0\uc5d0\uc11c\ub3c4 \uc81c\ub3d9\uc774 \uc774\ub8e8\uc5b4\uc9c0\ub3c4\ub85d \ud558\ub294 \uac83\uc774\ub2e4. \uc5f0\uacb0\uc774 \uc815\uc0c1\uc77c \ub54c\uc5d0\ub9cc \ud798\uc774 \uc804\ub2ec\ub41c\ub2e4\uba74, \uac00\uc7a5 \ud544\uc694\ud55c \uc21c\uac04\uc5d0 \uccb4\uacc4\uac00 \uc0ac\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ud3c9\uc18c\uc758 \uc131\uacf5\ubcf4\ub2e4 \uace0\uc7a5\ub0ac\uc744 \ub54c\uc758 \ud589\ub3d9\uc744 \uc124\uacc4\uc758 \uc911\uc2ec\uc5d0 \ub193\ub294\ub2e4. \uc774 \uc6d0\ub9ac\ub294 \uc88b\uc740 \uae30\uc220\uc744 \ubc14\ub77c\ubcf4\ub294 \ub208\uc744 \ub113\ud600 \uc900\ub2e4. \uc7a5\uce58\uac00 \uc5bc\ub9c8\ub098 \uac15\ud558\uac8c \uc791\ub3d9\ud558\ub294\uc9c0\ubfd0 \uc544\ub2c8\ub77c, \uc815\ubcf4\uc640 \uc5d0\ub108\uc9c0\ub97c \uc783\uc5c8\uc744 \ub54c \uc5b4\ub290 \ucabd \uc0c1\ud0dc\ub85c \uac00\ub294\uc9c0\ub3c4 \uc911\uc694\ud558\ub2e4. \uc5ec\uae30\uc11c\ub294 \uad6c\uccb4\uc801\uc778 \uc870\uc791\uc774\ub098 \uc815\ube44\ubc95\uc744 \uc124\uba85\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uae30\uc220\uc790\ub4e4\uc774 \ud480\uc5b4\uc57c \ud588\ub358 \uc9c8\ubb38\uc758 \ubc29\ud5a5\uc744 \uc77d\ub294 \uac83\uc774\ub2e4. \ub354 \ub098\uc740 \uc81c\ub3d9\uc740 \uc0ac\uace0\uc758 \uc704\ud5d8\uc744 \uc904\uc774\ub294 \uc77c\uc778 \ub3d9\uc2dc\uc5d0 \ucca0\ub3c4\uc758 \uc6b4\ud589 \uac00\ub2a5\uc131\uc744 \ub113\ud788\ub294 \uc77c\uc774\uc5c8\ub2e4. \uc77c\uc815\ud55c \uac70\ub9ac \uc548\uc5d0\uc11c \uc18d\ub3c4\ub97c \uad00\ub9ac\ud560 \uc218 \uc788\uc5b4\uc57c \uc2dc\uac04\ud45c\uc640 \uc6b4\uc1a1\ub7c9\ub3c4 \uacc4\ud68d\ud560 \uc218 \uc788\ub2e4. \ube60\ub978 \uae30\uad00\ucc28\uc640 \uc88b\uc740 \ube0c\ub808\uc774\ud06c\ub294 \uc11c\ub85c \ubc18\ub300\ud3b8\uc758 \ubc1c\uba85\uc774 \uc544\ub2c8\ub77c \uac19\uc740 \uad50\ud1b5 \uccb4\uacc4\ub97c \ub9cc\ub4dc\ub294 \ub3d9\ub8cc\uc600\ub2e4. \ubb3c\ub860 \uc7a5\uce58\uac00 \uc0dd\uacbc\ub2e4\uace0 \uc810\uac80\uacfc \uc219\ub828, \uc6b4\ud589 \uaddc\uce59\uc774 \ud544\uc694 \uc5c6\uc5b4\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uae30\uc220\uc740 \uc0ac\ub78c\uc758 \uc5ed\ud560\uc744 \ub2e4\ub978 \uc790\ub9ac\ub85c \uc62e\uae30\uae30\ub3c4 \ud55c\ub2e4. \ucc28\ub7c9 \uc704\ub97c \uc704\ud5d8\ud558\uac8c \uc774\ub3d9\ud558\ub358 \uc77c\uc744 \uc904\uc774\ub294 \ub300\uc2e0, \uc5f0\uacb0\uacfc \uc555\ub825, \uc7a5\uce58\uc758 \uc0c1\ud0dc\ub97c \uc0b4\ud53c\ub294 \uc77c\uc774 \ub354 \uc911\uc694\ud574\uc9c4\ub2e4. \uc790\ub3d9\uc774\ub77c\ub294 \ub9d0\uc740 \uc544\ubb34\ub3c4 \ub3cc\ubcf4\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \ucca0\ub3c4 \uc0ac\uc9c4\uc5d0\uc11c \uc5f0\uae30\uc640 \ubc14\ud034\ub294 \uc27d\uac8c \ub208\uc5d0 \ub748\ub2e4. \uad00\uacfc \uc5f0\uacb0 \uc7a5\uce58, \uc81c\ub3d9\uc744 \uc704\ud574 \uc6c0\uc9c1\uc774\ub358 \ub178\ub3d9\uc790\ub294 \uadf8\ubcf4\ub2e4 \ub35c \ubcf4\uc778\ub2e4. \ud558\uc9c0\ub9cc \ubaa9\uc801\uc9c0\uc5d0 \ub3c4\ucc29\ud55c\ub2e4\ub294 \uc77c\uc5d0\ub294 \uc548\uc804\ud558\uac8c \uba48\ucd98\ub2e4\ub294 \ub9c8\uc9c0\ub9c9 \ub3d9\uc791\uc774 \ud3ec\ud568\ub41c\ub2e4. \uad50\ud1b5\uc758 \uc5ed\uc0ac\ub294 \ucd9c\ubc1c\uc758 \uac10\ud0c4\ub9cc\uc73c\ub85c \uc644\uc131\ub418\uc9c0 \uc54a\ub294\ub2e4. \ub2e4\uc74c\uc5d0 \uc5f4\ucc28\uac00 \ucc9c\ucc9c\ud788 \uc2b9\uac15\uc7a5\uc73c\ub85c \ub4e4\uc5b4\uc624\ub294 \ubaa8\uc2b5\uc744 \ubcf4\uba74 \uadf8 \ub9e4\ub044\ub7ec\uc6b4 \uac10\uc18d\ub3c4 \uc7a0\uae50 \ubc14\ub77c\ubcf4\uc790. \uadf8 \ud3c9\ubc94\ud574 \ubcf4\uc774\ub294 \uc21c\uac04\uc5d0\ub294 \uac1c\ubcc4 \ucc28\ub7c9\uacfc \uae34 \ud3b8\uc131\uc744 \ud568\uaed8 \ub2e4\ub8e8\ub824 \ud588\ub358 \uc5ec\ub7ec \uc2e4\ud328\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \ucca0\ub3c4\ub97c \ubc14\uafbc \uac83\uc740 \ub2ec\ub9ac\ub294 \ud798\ubfd0 \uc544\ub2c8\ub77c \uadf8 \ud798\uc744 \ub2e4\ub8e8\uba70 \uc0ac\ub78c\uc744 \ub0b4\ub824 \uc904 \uc218 \uc788\uac8c \ud55c \uae30\uc220\uc774\uc5c8\ub2e4."}, {"id": "red-comb-chest-turtle", "title": "\ube57\uc744 \ub2f4\ub294 \uc0c1\uc790\uc758 \ubb38\uc9c0\uae30\ub294 \uac70\ubd81\uc774\uc5c8\ub2e4", "summary": "\uc11c\ub78d\uacfc \uce78\ub9c9\uc774\ub97c \uac16\ucd98 \ube57\uc811\uc5d0\uc11c \uac70\ubd81\uc774 \ubaa8\uc591 \uc790\ubb3c\uc1e0\ub97c \ubc1c\uacac\ud569\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\uc9d1\uacfc \uc0dd\ud65c \ub3c4\uad6c", "categories": ["everyday-inventions"], "url": "stories/red-comb-chest-turtle/index.html", "image": "../media/red-comb-chest-turtle.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc8fc\uce60\ube57\uc811 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\ube57\uc744 \ub2f4\ub294 \uc0c1\uc790\uc758 \ubb38\uc9c0\uae30\ub294 \uac70\ubd81\uc774\uc5c8\ub2e4 \ubd89\uc740 \ube57\uc811\uc5d0 \ub2ec\ub9b0 \uc791\uc740 \uc790\ubb3c\uc1e0 \uc11c\ub78d\uacfc \uce78\ub9c9\uc774\ub97c \uac16\ucd98 \ube57\uc811\uc5d0\uc11c \uac70\ubd81\uc774 \ubaa8\uc591 \uc790\ubb3c\uc1e0\ub97c \ubc1c\uacac\ud569\ub2c8\ub2e4. \uc9d1\uacfc \uc0dd\ud65c \ub3c4\uad6c \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \uc791\uc740 \ubd89\uc740 \uc0c1\uc790\uac00 \uc788\ub2e4. \ubb38\uc9dd\uacfc \uae08\uc18d \uc7a5\uc2dd\uc774 \ub2ec\ub824 \uc788\uc5b4\uc11c \uac00\uad6c\ub97c \uc904\uc5ec \ub193\uc740 \uac83\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uac00\uae4c\uc774 \uc0b4\ud3b4\ubcfc \ub54c \uc7ac\ubbf8\uc788\ub294 \uac83\uc740 \uac00\uc6b4\ub370 \ubd99\uc740 \uc790\ubb3c\uc1e0\ub2e4. \ubaa8\uc591\uc774 \uac70\ubd81\uc774\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \uc8fc\uce60\ube57\uc811\uc774\ub2e4. \ube57\uc811\uc774\ub77c\ub294 \ub0af\uc120 \uc774\ub984\uc744 \ub9cc\ub0ac\ub2e4\uba74, \ube57\uc744 \ub450\ub294 \uc791\uc740 \uc218\ub0a9 \uac00\uad6c\ub97c \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc774 \ubb3c\uac74\uc5d0\uc11c\ub294 \uc548\uc744 \uc815\ub9ac\ud558\ub294 \uad6c\uc870\uc640 \ubc16\uc744 \uafb8\ubbf8\ub294 \uc7a5\uc2dd\uc774 \ud568\uaed8 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc717\ub2e8\uc744 \uc816\ud600 \uc5ec\ub294 \ubd80\ubd84\uacfc \uc548\ucabd\uc758 \uc11c\ub78d \ub450 \uac1c\uac00 \uc788\ub294 \uad6c\uc870\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \uc717\ubd80\ubd84 \uc548\uc5d0\ub294 \uce78\ub9c9\uc774\ub3c4 \uc788\uc73c\uba70, \ud604\uc7ac \uadf8 \uc77c\ubd80\ub294 \uc5c6\uc5b4\uc838 \uc788\ub2e4. \uc791\uc740 \uc0c1\uc790\ub77c\uace0 \uc548\uc774 \ud145 \ube44\uc5b4 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ub298\ub0a0 \ud654\uc7a5\ub300 \uc11c\ub78d\uc5d0 \uc815\ub9ac\ud568\uc744 \ub123\ub294 \ubaa8\uc2b5\uc744 \uc0dd\uac01\ud558\uba74 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \ub2e4\ub9cc \uac01 \uce78\uc5d0 \uc815\ud655\ud788 \ubb34\uc5c7\uc744 \ub123\uc5c8\ub294\uc9c0\ub294 \uc774 \uc124\uba85\ub9cc\uc73c\ub85c \uc54c \uc218 \uc5c6\ub2e4. \ubb3c\uac74\ub9c8\ub2e4 \uc790\ub9ac\ub97c \ub098\ub204\uc5b4 \ub454 \uad6c\uc870\uc5d0 \uba3c\uc800 \uc8fc\ubaa9\ud558\uba74 \ub41c\ub2e4. \uac89\uba74\uc5d0\ub294 \ubd89\uc740 \uce60\uc744 \ud588\uace0 \ub0b4\ubd80\ub294 \uac80\uc740 \uce60\ub85c \ub9c8\uac10\ud588\ub2e4. \uc11c\ub78d \uc5ed\uc2dc \uc55e\uba74\uc740 \ubd89\uace0 \ub098\uba38\uc9c0 \uba74\uc740 \uac80\ub2e4\uace0 \ud55c\ub2e4. \ub2eb\uc558\uc744 \ub54c \ubcf4\uc774\ub294 \ubd80\ubd84\uacfc \uc5f4\uc5c8\uc744 \ub54c \ub4dc\ub7ec\ub098\ub294 \ubd80\ubd84\uc758 \uc0c9\uc774 \ub2e4\ub974\ub2e4. \uae08\uc18d \uc7a5\uc2dd\uc5d0\ub294 \uaf43\ubb34\ub2ac\ub97c \ube44\ub86f\ud55c \uc5ec\ub7ec \ubb34\ub2ac\uac00 \uc788\ub2e4. \ud638\ub9ac\ubcd1\uacfc \ubcf5\uc22d\uc544, \ubd80\ucc44, \uaf43\uacfc \uc0c8 \uc7a5\uc2dd\ub3c4 \uc124\uba85\uc5d0 \ub4f1\uc7a5\ud55c\ub2e4. \uc791\uc740 \uc218\ub0a9 \uac00\uad6c\uc5d0 \uaf64 \ub9ce\uc740 \ubcfc\uac70\ub9ac\ub97c \ubaa8\uc544 \ub454 \uc148\uc774\uc9c0\ub9cc, \ucc98\uc74c\ubd80\ud130 \ubaa8\ub450 \ucc3e\uc73c\ub824 \uc560\uc4f8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc0c1\uc790\uc758 \ub69c\uaed1\uc744 \uc816\ud788\ub294 \ub3d9\uc791\uacfc \uc11c\ub78d\uc744 \ub2f9\uae30\ub294 \ub3d9\uc791\uc740 \uc11c\ub85c \ub2e4\ub974\ub2e4. \uac19\uc740 \uc791\uc740 \uac00\uad6c \uc548\uc5d0\uc11c \ub450 \ubc29\uc2dd\uc758 \uc811\uadfc\uc744 \ub9c8\ub828\ud588\ub2e4\ub294 \uc810\uc774 \ud765\ubbf8\ub86d\ub2e4. \ud070 \ud2c0\uc740 \ud558\ub098\uc5ec\ub3c4 \uc548\uc758 \ubb3c\uac74\uc744 \uaebc\ub0b4\ub294 \uae38\uc740 \uc5ec\ub7ec \uac1c\uc77c \uc218 \uc788\ub2e4. \uc218\ub0a9\uc758 \ud615\ud0dc\ub97c \uc2e4\uc81c \uc190\uc758 \ud589\ub3d9\uacfc \uc5f0\uacb0\ud574 \ubcf4\uba74 \uad6c\uc870\ub97c \ub354 \uc27d\uac8c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uac01 \uce78\uc5d0 \uc5b4\ub290 \uc885\ub958\uc758 \ube57\uacfc \ubb3c\uac74\uc774 \ub4e4\uc5b4\uac14\ub294\uc9c0\ub97c \ubaa8\ub450 \uc548\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc774\ub984\uc774 \ube57\uc811\uc774\ub77c\uace0 \ud574\uc11c \ud604\uc7ac \ube44\uc5b4 \uc788\ub294 \ubaa8\ub4e0 \uce78\uc5d0 \uac19\uc740 \ubb3c\uac74\uc744 \ucc44\uc6cc \ub123\uc744 \uc218\ub294 \uc5c6\ub2e4. \ubc15\ubb3c\uad00\uc774 \uc124\uba85\ud558\ub294 \uce78\ub9c9\uc774\uc640 \uc11c\ub78d\uc744 \uba3c\uc800 \ubcf4\uc790. \ub098\ub204\uc5b4 \ubcf4\uad00\ud558\ub824\ub294 \uc758\ub3c4\ub294 \uc54c \uc218 \uc788\uc9c0\ub9cc \uadf8 \uc548\uc758 \uad6c\uccb4\uc801\uc778 \uc0dd\ud65c \ubaa9\ub85d\uc740 \ub610 \ub2e4\ub978 \uc790\ub8cc\uac00 \ud544\uc694\ud558\ub2e4. \uac89\uc758 \ubd89\uc740 \uce60\uacfc \uc548\uc758 \uac80\uc740 \uce60\uc740 \ubcf4\ub294 \uc0c1\ud669\uc744 \ub2ec\ub9ac\ud55c\ub2e4. \ub2eb\uc558\uc744 \ub54c \ud558\ub098\uc758 \uc0c9\uc73c\ub85c \uae30\uc5b5\ud560 \ubb3c\uac74\uc774 \uc5f4\ub9ac\uba74 \ub2e4\ub978 \uba74\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc11c\ub78d\ub3c4 \uc55e\uba74\uacfc \ub098\uba38\uc9c0 \ubd80\ubd84\uc744 \ub2e4\ub974\uac8c \ub9c8\uac10\ud588\ub2e4\uace0 \ud558\ub2c8, \ubb3c\uac74\uc774 \uc6c0\uc9c1\uc77c \ub54c \ub098\ud0c0\ub098\ub294 \ud45c\uc815\uc774 \uc788\uc5c8\ub2e4. \ub2e8\uc21c\ud55c \uac89\uce58\uc7a5\ub9cc\uc73c\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\ub294 \uc0c9\uc758 \ubc30\uce58\ub2e4. \uc774\uac83\uc744 \uc0ac\uc9c4\uc5d0\uc11c \ud655\uc778\ud560 \ub54c\uc5d0\ub294 \uc5b4\ub290 \ubd80\ubd84\uc774 \uc5f4\ub824 \uc788\uace0 \ubb34\uc5c7\uc774 \uac00\ub824\uc838 \uc788\ub294\uc9c0\ubd80\ud130 \uad6c\ubcc4\ud558\uba74 \uc88b\ub2e4. \ud45c\uba74\uc758 \uc0c9\uc744 \ucc98\uc74c \uc81c\uc791 \ub2f9\uc2dc\uc758 \uc0c1\ud0dc\uc640 \ub611\uac19\ub2e4\uace0 \ub2e8\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8\ub7ec\ub098 \ud604\uc7ac \ub0a8\uc740 \uad6c\ubd84\uacfc \uae30\ub85d\ub41c \ub9c8\uac10\uc744 \ud568\uaed8 \uc77d\uc73c\uba74, \ub2eb\ud78c \ubaa8\uc2b5\ub9cc\uc73c\ub85c \uac00\uad6c\ub97c \ub2e4 \ubcf4\uc558\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uc6c0\uc9c1\uc784\uc774 \uc788\uc5b4\uc57c \ub098\ud0c0\ub098\ub294 \uba74\ub3c4 \ubb3c\uac74\uc758 \uc77c\ubd80\ub2e4. \uc81c\ubaa9\uc758 \uac70\ubd81\uc774\ub294 \uc0c1\uc790\ub97c \uc9c0\ud0a4\ub294 \uc0c1\uc0c1 \uc18d \uc774\uc57c\uae30\ub9cc\uc774 \uc544\ub2c8\ub77c \uc790\ubb3c\uc1e0\uc758 \ud615\uc0c1\uc774\ub2e4. \uc7a0\uadf8\ub294 \uae30\ub2a5\uc744 \ub9e1\uc740 \uae08\uc18d \ubd80\ud488\uc5d0 \uc0dd\ubb3c\uc758 \ubab8\uc744 \ud45c\ud604\ud588\ub2e4. \uc774\uac83\uc744 \uc54c\uace0 \ub098\uba74 \uadc0\uc5ec\uc6b4 \uac70\ubd81 \uc7a5\uc2dd\uc774\ub77c\ub294 \uccab\uc778\uc0c1\uc774 \uc2e4\uc81c \uc4f0\uc784\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uae30\ub2a5\uacfc \ud615\uc0c1\uc774 \uac19\uc740 \uc790\ub9ac\uc5d0 \ub193\uc778 \uc0ac\ub840\ub2e4. \uac70\ubd81\uc744 \ud2b9\uc815\ud55c \uc18c\uc6d0 \ud558\ub098\uc640 \uace7\ubc14\ub85c \uc5f0\uacb0\ud574 \uc81c\uc791\uc790\uc758 \uc758\ub3c4\ub97c \ud655\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5ec\uae30\uc11c \ud655\uc778\ub418\ub294 \uac83\uc740 \uac70\ubd81\uc774 \ud615\ud0dc\uc758 \uc790\ubb3c\uc1e0\uc640 \ub2e4\uc591\ud55c \uae08\uc18d \ubb38\uc591\uc774\ub2e4. \ubc14\uae65\uc758 \ud654\ub824\ud55c \uce60\uacfc \uc791\uc740 \uae08\uc18d \ubd80\ubd84\uc774 \uac01\uac01 \ub2e4\ub978 \uc7ac\ub8cc\uc758 \ud45c\uc815\uc744 \ub9cc\ub4e0\ub2e4. \ud070 \uba74\uc744 \ubcf8 \ub4a4 \uc811\uc810\uacfc \uc7a0\uadf8\ub294 \ubd80\ubd84\uc73c\ub85c \ub208\uc744 \uc62e\uae30\uba74 \uac00\uad6c\uc758 \uad6c\uc870\uac00 \ub354 \uc790\uc138\ud788 \ubcf4\uc778\ub2e4. \ud604\uc7ac \uc77c\ubd80\uac00 \uacb0\uc2e4\ub418\uc5c8\ub2e4\ub294 \uc815\ubcf4\ub294 \ubaa8\uc790\ub780 \ubd80\ubd84\uc744 \uad00\ub78c\uc790\uc758 \uc0c1\uc0c1\uc73c\ub85c \uba54\uc6b0\uc9c0 \uc54a\ub3c4\ub85d \ub3d5\ub294\ub2e4. \ubb3c\uac74\uc758 \uc6d0\ub798 \uad6c\ud68d\uacfc \ub0a8\uc740 \ubaa8\uc2b5\uc774 \uc644\uc804\ud788 \uac19\uc9c0\ub294 \uc54a\uc744 \uc218 \uc788\ub2e4. \uc18c\uc7a5\ud488\uc744 \uc124\uba85\ud560 \ub54c \uc5c6\ub294 \ubd80\ubd84\uae4c\uc9c0 \ubc1d\ud600 \ub450\ub294 \uac83\uc740 \uc2e4\uc218\ub098 \uacb0\ud568\uc744 \uc228\uae30\uc9c0 \uc54a\ub294 \uae30\ub85d\uc758 \ud0dc\ub3c4\ub2e4. \uc5f0\uad6c\uc640 \ubcf5\uc6d0\uc758 \ucd9c\ubc1c\uc810\uc774 \ub418\uae30\ub3c4 \ud55c\ub2e4. \uc774 \uc791\uc740 \uac00\uad6c\ub97c \ub2e4\uc2dc \ubcf4\uac8c \ub41c\ub2e4\uba74 \uba3c\uc800 \ubb38\uacfc \uc11c\ub78d\uc758 \ubc29\ud5a5\uc744, \ub2e4\uc74c\uc5d0\ub294 \uc0c9\uacfc \uc790\ubb3c\uc1e0\uc758 \ubaa8\uc591\uc744 \uc0b4\ud3b4\ubcf4\uc790. \ube57\uc744 \ubcf4\uad00\ud558\ub294 \uae30\ub2a5 \uc8fc\uc704\uc5d0 \uc5ec\ub7ec \ubc88\uc758 \ub9cc\ub4e4\uae30\uc640 \uafb8\ubbf8\uae30\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \ub204\uac00 \uc5b4\ub290 \uc544\uce68\uc5d0 \uc0ac\uc6a9\ud588\ub294\uc9c0 \uc774\uc57c\uae30\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub0a8\uc740 \ud615\ud0dc\ub294 \uadf8 \ud589\ub3d9\uc744 \uc900\ube44\ud55c \uc190\uc758 \uc0dd\uac01\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ubb3c\uac74\uc744 \uc218\ub0a9\ud558\ub294 \uc0c1\uc790\ub3c4 \uadf8 \uc790\uccb4\ub85c \uc77d\uc744 \uba74\uc774 \ub9ce\ub2e4. \uc774 \ube57\uc811\uc5d0\ub294 \uac70\ubd81\uc774 \ud615\ud0dc\uc758 \uc790\ubb3c\uc1e0\uac00 \ubd99\uc5b4 \uc788\ub2e4\uace0 \ubc15\ubb3c\uad00\uc740 \uc54c\ub824 \uc900\ub2e4. \uc11c\ub78d \uc18d\uc744 \ub2e4 \ud655\uc778\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc774 \uc791\uc740 \ub3d9\ubb3c \ud558\ub098 \ub355\ubd84\uc5d0 \uc0c1\uc790\uc758 \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uac70\ubd81\uc774 \uc7a5\uc2dd\uc758 \ub73b\uc744 \uc774 \uc790\ub8cc\ub9cc\uc73c\ub85c \ud655\uc815\ud558\uac70\ub098 \uc7a0\uae08\uc7a5\uce58\uc758 \uc131\ub2a5\uc744 \uc9d0\uc791\ud558\uc9c0\ub294 \ub9d0\uc790. \uc5ec\uae30\uc11c \uc990\uae38 \uac83\uc740 \uc218\ub0a9 \uac00\uad6c\uc758 \ud55c\uac00\uc6b4\ub370 \ub3d9\ubb3c\uc758 \ubaa8\uc591\uc744 \ub193\uc558\ub2e4\ub294 \uc120\ud0dd\uc774\ub2e4. \ubd89\uc740 \uc0c1\uc790\ub97c \ub2e4\uc2dc \ubcfc \ub54c \ubb38\uc591\uc774 \ub9ce\uc558\ub2e4\ub294 \uae30\uc5b5\ubcf4\ub2e4, \ube57\uc744 \uc9c0\ud0a4\ub294 \uac70\ubd81\uc774 \uac19\uc558\ub2e4\ub294 \uc778\uc0c1\uc774 \uba3c\uc800 \ub5a0\uc624\ub97c\uc9c0\ub3c4 \ubaa8\ub978\ub2e4."}, {"id": "refrigerated-railcars-food-distance-and-time", "title": "\ub0c9\uc7a5 \uc5f4\ucc28 \u2014 \uc2dd\ud0c1\uc5d0 \uc624\uae30\uae4c\uc9c0 \uc74c\uc2dd\uc740 \uc5bc\ub9c8\ub098 \uba40\ub9ac \uc654\uc744\uae4c", "summary": "19\uc138\uae30\uc758 \ub0c9\uc7a5 \ud654\ucc28\uc640 \uac00\uacf5\u00b7\uc6b4\uc1a1\uc758 \uc5f0\uacb0\uc774 \ub3c4\uc2dc\uc758 \uc2dd\ud0c1\uc744 \uc5b4\ub5bb\uac8c \ubc14\uafb8\uc5c8\ub294\uc9c0 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\uc2dd\ud0c1\uacfc \uc2dd\ud488 \ubcf4\uc874", "categories": ["everyday-inventions"], "url": "stories/refrigerated-railcars-food-distance-and-time/index.html", "image": "../media/refrigerated-railcars-food-distance-and-time.png", "alt": "\uc5bc\uc74c\uacfc \ud3ec\uc7a5 \uc2dd\ud488\uc744 \ub0c9\uc7a5 \ud654\ucc28\uc5d0 \uc2e3\uace0 \uc0b4\ud53c\ub294 19\uc138\uae30 \ub178\ub3d9\uc790\ub4e4\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ub0c9\uc7a5 \uc5f4\ucc28 \u2014 \uc2dd\ud0c1\uc5d0 \uc624\uae30\uae4c\uc9c0 \uc74c\uc2dd\uc740 \uc5bc\ub9c8\ub098 \uba40\ub9ac \uc654\uc744\uae4c \ub3c4\uc2dc\uc758 \uc7a5\ubcf4\uae30\ub97c \ubc14\uafbc \uac83\uc740 \ub2ec\ub9ac\ub294 \ucc28 \uc548\uc758 \ucc28\uac00\uc6b4 \uacf5\uae30\uc600\ub2e4 19\uc138\uae30\uc758 \ub0c9\uc7a5 \ud654\ucc28\uc640 \uac00\uacf5\u00b7\uc6b4\uc1a1\uc758 \uc5f0\uacb0\uc774 \ub3c4\uc2dc\uc758 \uc2dd\ud0c1\uc744 \uc5b4\ub5bb\uac8c \ubc14\uafb8\uc5c8\ub294\uc9c0 \uc77d\uc2b5\ub2c8\ub2e4. \uc2dd\ud0c1\uacfc \uc2dd\ud488 \ubcf4\uc874 \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \uae30\ucc28\uac00 \ube68\ub77c\uc9c0\uba74 \uc74c\uc2dd\ub3c4 \ub354 \uba40\ub9ac \ubcf4\ub0bc \uc218 \uc788\uc744\uae4c. \uc5b4\ub290 \uc815\ub3c4\ub294 \uadf8\ub807\ub2e4. \ud558\uc9c0\ub9cc \ub3c4\ucc29\ud558\uae30 \uc804\uc5d0 \uc0c1\ud574 \ubc84\ub9b0\ub2e4\uba74 \ube60\ub978 \ubc14\ud034\ub9cc\uc73c\ub85c\ub294 \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4. \uc74c\uc2dd\uc758 \uc5ec\ud589\uc5d0\ub294 \uac70\ub9ac\uc640 \ud568\uaed8 \uc2dc\uac04\uc774 \uc788\uace0, \uadf8 \uc2dc\uac04\uc744 \uacac\ub514\uac8c \ud558\ub294 \uc628\ub3c4\uac00 \ud544\uc694\ud558\ub2e4. 19\uc138\uae30 \ud6c4\ubc18 \ub0c9\uc7a5 \ud654\ucc28\uc758 \ubc1c\uc804\uc740 \ucca0\ub3c4\uc758 \uc5ed\uc0ac\ub97c \uc2dd\ud0c1\uc758 \uc5ed\uc0ac\uc640 \uc5f0\uacb0\ud588\ub2e4. \uc624\ud508\uc2a4\ud0dd\uc2a4\uc758 \uc0b0\uc5c5\ud654 \uc124\uba85\uc744 \ubc14\ud0d5\uc73c\ub85c, \ucc28\uac00\uc6b4 \uc6b4\uc1a1 \uacf5\uac04\uc774 \ub3c4\uc2dc\uc758 \uba39\ub294 \ubc29\uc2dd\uc744 \uc5b4\ub5bb\uac8c \ubc14\uafb8\uc5c8\ub294\uc9c0 \uc0b4\ud3b4\ubcf8\ub2e4. \uae30\uacc4 \ud55c \ub300\uc758 \ubc1c\uba85\ubcf4\ub2e4 \uc5ec\ub7ec \uacfc\uc815\uc774 \uc774\uc5b4\uc9c0\ub294 \ubaa8\uc2b5\uc5d0 \uc8fc\ubaa9\ud574 \ubcf4\uc790. \uace0\uae30\uc640 \uc6b0\uc720, \uacfc\uc77c\ucc98\ub7fc \uc27d\uac8c \ubcc0\ud558\ub294 \uba39\uc744\uac70\ub9ac\ub294 \uba3c \uacf3\uc73c\ub85c \ubcf4\ub0b4\uae30 \uc5b4\ub835\ub2e4. \uace0\uae30\uc758 \uacbd\uc6b0 \uc0b4\uc544 \uc788\ub294 \ub3d9\ubb3c\uc744 \uc62e\uae34 \ub4a4 \uc18c\ube44\uc9c0 \uac00\uae4c\uc774\uc5d0\uc11c \ucc98\ub9ac\ud558\ub294 \ubc29\uc2dd\ub3c4 \uc788\uc5c8\ub2e4. \ub3d9\ubb3c\uacfc \uac00\uacf5\ub41c \uace0\uae30\ub294 \uac19\uc740 \ubb34\uac8c\uc640 \uacf5\uac04\uc744 \ud544\uc694\ub85c \ud558\uc9c0 \uc54a\ub294\ub2e4. \ubb34\uc5c7\uc744 \uc5b4\ub5a4 \uc0c1\ud0dc\ub85c \ub098\ub97c\uc9c0\uac00 \uc6b4\uc1a1\uc758 \ubb38\uc81c\uac00 \ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uace0\uae30\ub97c \ubbf8\ub9ac \ucc98\ub9ac\ud574 \uc544\ubb34 \ud654\ucc28\uc5d0\ub098 \uc2e4\uc73c\uba74 \ud574\uacb0\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc628\ub3c4\uc640 \uc704\uc0dd, \uc774\ub3d9 \uc2dc\uac04\uc774 \ub9de\uc544\uc57c \ud55c\ub2e4. \uc0dd\uc0b0\uc9c0\uc5d0\uc11c \uc798 \uc900\ube44\ud55c \uc74c\uc2dd\ub3c4 \ub3c4\uc911\uc758 \ud55c \uad6c\uac04\uc774 \uae38\uc5b4\uc9c0\uba74 \uc0c1\ud0dc\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ub18d\uc7a5\uacfc \ub3c4\uc2dc \uc0ac\uc774\uc5d0 \uc120\ub85c\ub97c \ub193\ub294 \uc77c\uacfc \uc2dd\ud488\uc774 \uba39\uc744 \ub9cc\ud55c \uc0c1\ud0dc\ub85c \ub3c4\ucc29\ud558\ub294 \uc77c\uc740 \uc11c\ub85c \ub2e4\ub978 \uacfc\uc81c\uc600\ub2e4. \ub0c9\uc7a5 \ud654\ucc28\ub294 \uc2dd\ud488\uc774 \uc9c0\ub0bc \ud658\uacbd\uc744 \ud568\uaed8 \uc62e\uae30\ub824\ub294 \uc2dc\ub3c4\ub2e4. \uc624\ub298\uc758 \uc804\uae30 \ub0c9\uc7a5\uace0\ub97c \uadf8\ub300\ub85c \uae30\ucc28\uc5d0 \uc2e4\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ucd08\uae30\uc758 \ucc28\uac00\uc6b4 \uc6b4\uc1a1\uc5d0\ub294 \uc5bc\uc74c\uacfc \ub2e8\uc5f4, \ucc28 \uc548\uc758 \uacf5\uae30\ub97c \ub2e4\ub8e8\ub294 \ubc29\uc2dd\uc774 \uc911\uc694\ud588\ub2e4. \ucc28\uac00 \ub2ec\ub9ac\ub294 \ub3d9\uc548\uc5d0\ub3c4 \ubcf4\uad00\uc758 \uc2dc\uac04\uc774 \uacc4\uc18d\ub418\ub3c4\ub85d \uacf5\uac04\uc744 \ub9cc\ub4e0 \uac83\uc774\ub2e4. \uc624\ud508\uc2a4\ud0dd\uc2a4\ub294 1870\ub144\ub300 \uad6c\uc2a4\ud0c0\ubd80\uc2a4 \uc2a4\uc704\ud504\ud2b8\uc758 \uc0ac\uc5c5\uacfc \uc5f0\uacb0\ub41c \uae30\uc220\uc790\ub4e4\uc774 \ub0c9\uc7a5 \ucca0\ub3c4 \ucc28\ub7c9\uc744 \uac1c\uc120\ud55c \uc77c\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc774\uac83\uc744 \ud55c \uc0ac\ub78c\uc774 \uc5b4\ub290 \ub0a0 \ub0c9\uc7a5 \uc6b4\uc1a1 \uc804\uccb4\ub97c \ucc98\uc74c \ubc1c\uba85\ud588\ub2e4\ub294 \ub73b\uc73c\ub85c \uc77d\uc9c0\ub294 \ub9d0\uc544\uc57c \ud55c\ub2e4. \uc774\ubbf8 \uc2dc\ub3c4\ub418\ub358 \ubc29\ubc95\uc744 \uc0ac\uc5c5\uc5d0 \ub9de\uac8c \ub2e4\ub4ec\uace0 \uc548\uc815\uc801\uc73c\ub85c \uc774\uc6a9\ud558\ub294 \uacfc\uc815\ub3c4 \uc0b0\uc5c5\uc758 \ubcc0\ud654\uc600\ub2e4. \ucc28\uac00\uc6b4 \ud654\ucc28\ub97c \ub9cc\ub4e4\uc5c8\ub2e4\uace0 \uc2dd\ud0c1\uc774 \uc989\uc2dc \ubc14\ub00c\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc2dd\ud488\uc744 \uc900\ube44\ud558\ub294 \uc7a5\uc18c\uc640 \uc2e3\ub294 \ubc29\uc2dd, \uc120\ub85c\uc640 \ub3c4\ucc29 \ub4a4\uc758 \ubcf4\uad00\uc774 \uc774\uc5b4\uc838\uc57c \ud55c\ub2e4. \uc911\uac04\uc5d0\uc11c \uc624\ub798 \uae30\ub2e4\ub9ac\uac70\ub098 \uc628\ub3c4\uac00 \ub2ec\ub77c\uc9c0\uba74 \uc55e\uc120 \ub178\ub825\uc774 \uc57d\ud574\uc9c4\ub2e4. \ub0c9\uc7a5\uc740 \ubb3c\uac74 \ud558\ub098\ub77c\uae30\ubcf4\ub2e4 \uacc4\uc18d \uc720\uc9c0\ud574\uc57c \ud558\ub294 \uc870\uac74\uc5d0 \uac00\uae5d\ub2e4. \uc774 \uc5f0\uacb0\uc744 \uc0dd\uac01\ud558\uba74 \uc2dd\ud488 \uc6b4\uc1a1\uc774 \uc65c \ud070 \uc870\uc9c1\uc758 \uc77c\uc774 \ub418\ub294\uc9c0 \ubcf4\uc778\ub2e4. \uc0dd\uc0b0\uc790\ub9cc \uc798\ud574\uc11c\ub3c4, \uae30\uad00\uc0ac\ub9cc \ube68\ub9ac \ub2ec\ub824\uc11c\ub3c4 \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4. \uc5ec\ub7ec \uc7a5\uc18c\uc758 \uc0ac\ub78c\ub4e4\uc774 \uac19\uc740 \uc2dc\uac04\ud45c \uc548\uc5d0\uc11c \uc6c0\uc9c1\uc5ec\uc57c \ud55c\ub2e4. \uc6b0\ub9ac\uac00 \ud3c9\uc18c \ud55c \ubb36\uc74c\uc73c\ub85c \ubd80\ub974\ub294 \uc720\ud1b5\uc774\ub77c\ub294 \ub9d0 \uc548\uc5d0 \uc774\ub7f0 \ub2e4\ub978 \uc77c\ub4e4\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uc0b0\uc5c5\ud654\ub41c \ub3c4\uc2dc\uc5d0\ub294 \ub9ce\uc740 \uc0ac\ub78c\uc774 \ubaa8\uc778\ub2e4. \uac00\uae4c\uc6b4 \ubc2d\uacfc \uac00\ucd95\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc218\uc694\ub97c \ud574\uacb0\ud558\uae30 \uc5b4\ub824\uc6b4 \uacf3\ub3c4 \uc0dd\uae34\ub2e4. \ucca0\ub3c4\uc640 \ubcf4\uad00 \uae30\uc220\uc740 \ub354 \uba3c \uc9c0\uc5ed\uc758 \uc0dd\uc0b0\uc744 \ub3c4\uc2dc\uc758 \uc18c\ube44\uc640 \uc5f0\uacb0\ud55c\ub2e4. \uba39\uc744\uac70\ub9ac\uc758 \uc9c0\ub3c4\ub294 \ub3c4\uc2dc\uc758 \uacbd\uacc4\ubcf4\ub2e4 \ud6e8\uc52c \ub113\uc5b4\uc9c0\uae30 \uc2dc\uc791\ud55c\ub2e4. \uad50\uc7ac\ub294 \ub18d\uc5c5\uc758 \uae30\uacc4\ud654\uc640 \ub0c9\uc7a5 \ud654\ucc28, \uac00\uacf5 \uacf5\uc7a5\uacfc \ud1b5\uc870\ub9bc \uc0dd\uc0b0\uc744 \ud568\uaed8 \uc124\uba85\ud55c\ub2e4. \uc774\ub7f0 \ubcc0\ud654\uac00 \uacb9\uce58\uba70 \ub3c4\uc2dc \uc0ac\ub78c\ub4e4\uc740 \ub354 \ub2e4\uc591\ud55c \uc2dd\ud488\uc744 \uacc4\uc808 \ubc16\uc5d0\ub3c4 \ub9cc\ub0a0 \uc218 \uc788\uc5c8\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \uc74c\uc2dd\uc774 \ub0c9\uc7a5 \ub54c\ubb38\uc5d0 \uac00\ub2a5\ud574\uc9c4 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud1b5\uc870\ub9bc\uc758 \ubcf4\uc874\uacfc \ub0ae\uc740 \uc628\ub3c4\ub85c \uc2e0\uc120\ub3c4\ub97c \uc720\uc9c0\ud558\ub294 \uc77c\uc740 \ub2e4\ub978 \uae30\uc220\uc774\uba70 \uc11c\ub85c \ubcf4\uc644\ud588\ub2e4. \uc74c\uc2dd\uac12\uc5d0\ub294 \uc7ac\ub8cc\ub9cc \ub4e4\uc5b4 \uc788\uc9c0 \uc54a\ub2e4. \uc5bc\ub9c8\ub098 \ub9ce\uc774 \ub9cc\ub4e4\uace0, \uc5b4\ub5a4 \uc0c1\ud0dc\ub85c \uc62e\uae30\uace0, \ub3c4\uc911\uc5d0 \uc5bc\ub9c8\ub098 \uc783\ub294\uc9c0\ub3c4 \uc601\ud5a5\uc744 \uc900\ub2e4. \ub0c9\uc7a5 \uc6b4\uc1a1\uc740 \uba40\ub9ac \uc788\ub294 \uc0dd\uc0b0\uc744 \ubb36\uace0 \uc190\uc2e4\uc744 \uc904\uc77c \uac00\ub2a5\uc131\uc744 \uc5f4\uc5c8\ub2e4. \uc2dd\ud0c1\uc758 \ubcc0\ud654\uac00 \uacf5\uc7a5\uc774\ub098 \ucca0\ub3c4\ud68c\uc0ac\uc640 \uc5f0\uacb0\ub418\ub294 \uc774\uc720\ub2e4. \uadf8\ub7ec\ub098 \uc0c8\ub85c\uc6b4 \uae30\uc220\uc774 \ubaa8\ub4e0 \uc0ac\ub78c\uc5d0\uac8c \uac19\uc740 \ud61c\ud0dd\uc744 \uc8fc\uc5c8\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uac12\uacfc \uc811\uadfc\uc131\uc740 \uc18c\ub4dd\uacfc \uc9c0\uc5ed, \uc720\ud1b5 \uad6c\uc870\uc5d0 \ub530\ub77c \ub2ec\ub790\ub2e4. \ub354 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uc0c1\ud488\uc744 \uc0b4 \uc218 \uc788\uac8c \ub41c \ubcc0\ud654\uc640, \uadf8 \uc0c1\ud488\uc744 \ub9cc\ub4dc\ub294 \ub178\ub3d9\uc790\uc758 \ud615\ud3b8\uc740 \ub530\ub85c \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \ud48d\uc131\ud574\uc9c4 \ub9e4\ub300\ub9cc \ubcf4\uace0 \uc0b0\uc5c5\ud654\uc758 \uacbd\ud5d8 \uc804\uccb4\ub97c \ud310\ub2e8\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \uace0\uae30\uac00 \ud3ec\uc7a5\ub41c \uc0c1\ud488\uc73c\ub85c \uc624\uba74 \uc18c\ube44\uc790\ub294 \uc0dd\uc0b0\uacfc \uac00\uacf5\uc758 \uacfc\uc815\uc744 \ub35c \ubcf4\uac8c \ub41c\ub2e4. \uac70\ub9ac\uac00 \uba40\uc5b4\uc84c\ub2e4\ub294 \uac83\uc740 \uc74c\uc2dd\uc774 \uc5b4\ub514\uc5d0\uc11c \uc654\ub294\uc9c0 \ub208\uc73c\ub85c \ud655\uc778\ud560 \uae30\ud68c\ub3c4 \uc904\uc5b4\ub4e0\ub2e4\ub294 \ub73b\uc774\ub2e4. \uadf8\ub798\uc11c \uc720\ud1b5\uc774 \ubc1c\uc804\ud560\uc218\ub85d \uc124\uba85\uacfc \uae30\ub85d, \uc2e0\ub8b0\ub97c \ud655\uc778\ud558\ub294 \ub2e4\ub978 \uc7a5\uce58\uac00 \uc911\uc694\ud574\uc9c4\ub2e4. \uc774\uac83\uc740 \uc61b \uc74c\uc2dd\uc740 \ubaa8\ub450 \uc548\uc804\ud588\uace0 \ud604\ub300 \uc2dd\ud488\uc740 \ubbff\uc744 \uc218 \uc5c6\ub2e4\ub294 \uc8fc\uc7a5\uc774 \uc544\ub2c8\ub2e4. \uac00\uae4c\uc6b4 \uac70\ub9ac\ub9cc\uc73c\ub85c \ud488\uc9c8\uc774 \ubcf4\uc7a5\ub418\uc9c0\ub3c4 \uc54a\ub294\ub2e4. \ub2e4\ub9cc \uae30\uc220\uc774 \ud2b9\uc815 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\uba74 \uad00\uc2ec\uc744 \uac00\uc838\uc57c \ud560 \uc9c0\uc810\ub3c4 \uc62e\uaca8 \uac04\ub2e4\ub294 \uac83\uc774\ub2e4. \uba39\uc744\uac70\ub9ac\uc758 \uc0c1\ud0dc\ub97c \uc9c0\ud0a4\ub294 \uc77c\uc740 \uc18d\ub3c4\uc640 \uaddc\ubaa8\uac00 \ucee4\uc9c4 \ub4a4\uc5d0\ub3c4 \uacc4\uc18d\ub41c\ub2e4. \uc624\ub298\uc758 \uc7a5\ubcf4\uae30\uc5d0\uc11c\ub294 \ub0c9\uc7a5 \uc0c1\ud0dc\ub97c \ub108\ubb34 \ub2f9\uc5f0\ud558\uac8c \uc5ec\uaca8 \uadf8 \uc870\uac74\uc744 \uc720\uc9c0\ud558\ub294 \uc0ac\ub78c\uacfc \uc7a5\ube44\ub97c \uc78a\uae30 \uc27d\ub2e4. 19\uc138\uae30 \ub0c9\uc7a5 \uc5f4\ucc28\uc758 \uc774\uc57c\uae30\ub294 \uadf8 \ub2f9\uc5f0\ud568\uc774 \uc5ec\ub7ec \uc2dc\ub3c4\uc640 \ub178\ub3d9 \uc704\uc5d0 \ub9cc\ub4e4\uc5b4\uc84c\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc74c\uc2dd\uc758 \uc5ed\uc0ac\ub294 \uc694\ub9ac\ubc95\ub9cc\uc758 \uc5ed\uc0ac\uac00 \uc544\ub2c8\ub2e4. \ub2e4\uc74c\uc5d0 \uc2dd\ud488\uc758 \uc6d0\uc0b0\uc9c0\ub97c \ubcf4\uac8c \ub418\uba74 \ub9db\uc758 \uace0\ud5a5\ubfd0 \uc544\ub2c8\ub77c \uac70\uae30\uc11c \uc5ec\uae30\uae4c\uc9c0 \uc628 \uc2dc\uac04\ub3c4 \uc7a0\uae50 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ub18d\uc7a5\uacfc \uac00\uacf5 \uc7a5\uc18c, \ucc28\uc640 \ucc3d\uace0, \ub9c8\uc9c0\ub9c9 \uac00\uac8c\uac00 \ud55c \uc2dd\ud0c1\uc5d0 \ubaa8\uc5ec \uc788\ub2e4. \uba40\ub9ac\uc11c \uc628 \uc74c\uc2dd \ud55c \uc811\uc2dc\uc5d0\ub294 \ucca0\ub3c4\uac00 \ube68\ub77c\uc9c4 \uc5ed\uc0ac\uc640, \uadf8 \uc548\uc5d0\uc11c \uc2dc\uac04\uc744 \ub2a6\ucd94\ub824 \ud588\ub358 \ucc28\uac00\uc6c0\uc758 \uc5ed\uc0ac\uac00 \ud568\uaed8 \ub2f4\uaca8 \uc788\ub2e4."}, {"id": "safety-bicycle-chain-and-pneumatic-tyre", "title": "\uc790\uc804\uac70 \u2014 \uc55e\ubc14\ud034\uac00 \uc791\uc544\uc9c0\uc790 \ud0c8 \uc218 \uc788\ub294 \uc0ac\ub78c\uc774 \ub298\uc5c8\ub2e4", "summary": "\uc9c1\uc811 \uad6c\ub3d9\uc758 \ud070 \ubc14\ud034\uc5d0\uc11c \uccb4\uc778\uacfc \uacf5\uae30 \ud0c0\uc774\uc5b4\ub85c \uc774\uc5b4\uc9c4 \ubcc0\ud654\uac00 \ubab8\uacfc \uae38\uc758 \uacbd\ud5d8\uc744 \ubc14\uafbc \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\uc774\ub3d9\uacfc \uc6b4\uc1a1", "categories": ["everyday-inventions"], "url": "stories/safety-bicycle-chain-and-pneumatic-tyre/index.html", "image": "../media/safety-bicycle-chain-and-pneumatic-tyre.jpg", "alt": "\ub450 \ubc14\ud034\uac00 \ube44\uc2b7\ud55c \ud06c\uae30\uc774\uace0 \uccb4\uc778\uc73c\ub85c \uad6c\ub3d9\ud558\ub294 \uc138\uc774\ud504\ud2f0 \uc790\uc804\uac70\uc758 \uc5ed\uc0ac \ub3c4\ud310", "text": "\uc790\uc804\uac70 \u2014 \uc55e\ubc14\ud034\uac00 \uc791\uc544\uc9c0\uc790 \ud0c8 \uc218 \uc788\ub294 \uc0ac\ub78c\uc774 \ub298\uc5c8\ub2e4 \ud070 \uc55e\ubc14\ud034\uc640 \uccb4\uc778 \uad6c\ub3d9, \ud0c0\uc774\uc5b4\uac00 \ubc14\uafbc \uc774\uc6a9 \uc870\uac74 \uc9c1\uc811 \uad6c\ub3d9\uc758 \ud070 \ubc14\ud034\uc5d0\uc11c \uccb4\uc778\uacfc \uacf5\uae30 \ud0c0\uc774\uc5b4\ub85c \uc774\uc5b4\uc9c4 \ubcc0\ud654\uac00 \ubab8\uacfc \uae38\uc758 \uacbd\ud5d8\uc744 \ubc14\uafbc \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc774\ub3d9\uacfc \uc6b4\uc1a1 \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \uc61b \uc790\uc804\uac70 \uc0ac\uc9c4\uc5d0\ub294 \uc55e\ubc14\ud034\uac00 \uc720\ub09c\ud788 \ud070 \uae30\uacc4\uac00 \ubcf4\uc778\ub2e4. \uc624\ub298\uc758 \ub450 \ubc14\ud034\uac00 \ube44\uc2b7\ud55c \uc790\uc804\uac70\uc640\ub294 \ubab8\uc744 \uc62c\ub9ac\ub294 \ubc29\ubc95\ubd80\ud130 \ub2e4\ub974\ub2e4. \uc790\uc804\uac70\uc758 \ubcc0\ud654\ub294 \ube68\ub9ac \ub2ec\ub9ac\ub294 \ub2a5\ub825\ub9cc\uc758 \uc5ed\uc0ac\uac00 \uc544\ub2c8\ub2e4. \ud398\ub2ec\uacfc \uccb4\uc778, \ucc28\uccb4\uc640 \ud0c0\uc774\uc5b4\uac00 \ubc14\ub00c\uba74\uc11c \ub204\uac00 \uc5b4\ub5a4 \uae38\uc5d0\uc11c \ud0c8 \uc218 \uc788\ub294\uc9c0\ub3c4 \ub2ec\ub77c\uc84c\ub2e4. \uc55e\ubc14\ud034\uc5d0 \ud398\ub2ec\uc774 \uc9c1\uc811 \uc5f0\uacb0\ub41c \ud615\ud0dc\uc5d0\uc11c\ub294 \ud55c \ubc14\ud034 \ub3cc \ub54c \uc774\ub3d9\ud558\ub294 \uac70\ub9ac\uac00 \ubc14\ud034 \ud06c\uae30\uc640 \uc5f0\uacb0\ub41c\ub2e4. \ud070 \ubc14\ud034\ub294 \uac19\uc740 \ud68c\uc804\uc73c\ub85c \ub354 \uba40\ub9ac \uac00\uac8c \ud558\ub294 \ubc29\ubc95\uc774\uc5c8\ub2e4. \ub2f9\uc2dc\uc758 \ud615\ud0dc\ub97c \uc6b0\uc2a4\uc6b4 \uc7a5\ub09c\uac10\uc73c\ub85c\ub9cc \ubcf4\uba74 \uadf8 \uc120\ud0dd\uc758 \uc774\uc720\ub97c \ub193\uce5c\ub2e4. \ud558\uc9c0\ub9cc \uc0ac\ub78c\uc774 \uc549\ub294 \ub192\uc774\ub3c4 \uc62c\ub77c\uac14\ub2e4. \ud0c0\uace0 \ub0b4\ub9ac\ub294 \uc77c\uacfc \ub118\uc5b4\uc9c8 \ub54c\uc758 \uc704\ud5d8\uc774 \ubb38\uc81c\uac00 \ub41c\ub2e4. \uc18d\ub3c4\ub77c\ub294 \ud55c \uac00\uc9c0 \ubaa9\ud45c\ub97c \uac1c\uc120\ud55c \uc120\ud0dd\uc774 \ub2e4\ub978 \uc0ac\uc6a9 \uc870\uac74\uc744 \uc5b4\ub835\uac8c \ud560 \uc218 \uc788\uc5c8\ub2e4. \ubc1c\uba85\uc740 \ud55c \uac00\uc9c0 \uc22b\uc790\ub9cc \ud06c\uac8c \ub9cc\ub4dc\ub294 \uc77c\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uccb4\uc778\uc73c\ub85c \ud398\ub2ec\uc758 \uc6c0\uc9c1\uc784\uc744 \ub4a4\ucabd \ubc14\ud034\uc5d0 \uc804\ub2ec\ud558\uba74 \ud398\ub2ec\uc774 \uaf2d \ud070 \uc55e\ubc14\ud034\uc758 \uc911\uc2ec\uc5d0 \ubd99\uc5b4 \uc788\uc744 \ud544\uc694\uac00 \uc5c6\ub2e4. \uae30\uc5b4\uc758 \ube44\uc728\uc744 \uc774\uc6a9\ud574 \ud398\ub2ec \ud68c\uc804\uacfc \ubc14\ud034 \ud68c\uc804\uc758 \uad00\uacc4\ub3c4 \uc815\ud560 \uc218 \uc788\ub2e4. \ubc14\ud034\ub97c \ud06c\uac8c \ud0a4\uc6b0\ub294 \ubc29\ubc95 \uc678\uc5d0 \ub2e4\ub978 \uc120\ud0dd\uc9c0\uac00 \uc0dd\uae34 \uac83\uc774\ub2e4. \ud0c0\ub294 \uc0ac\ub78c\uc744 \ub354 \ub0ae\uac8c \ub458 \uc218 \uc788\uace0 \uc55e\ubc14\ud034\ub294 \uc8fc\ub85c \ubc29\ud5a5\uc744 \ubc14\uafb8\ub294 \uc5ed\ud560\uc744 \ud55c\ub2e4. \uc624\ub298 \uc775\uc219\ud55c \ubc30\uce58\ub3c4 \ub2f9\uc2dc\uc5d0\ub294 \uc5ec\ub7ec \uad6c\uc131\uc744 \uac70\uce58\uba70 \uc790\ub9ac \uc7a1\uc558\ub2e4. \uc5b4\ub5a4 \ubd80\ud488\uc744 \ubc14\uafb8\uba74 \ub2e4\ub978 \ubd80\ud488\uc758 \ud06c\uae30\uc640 \uc704\uce58\uae4c\uc9c0 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \uc790\uc804\uac70\uc5d0\uc11c \uc798 \ubcf4\uc778\ub2e4. 19\uc138\uae30 \ub9d0\uc758 \uc138\uc774\ud504\ud2f0 \uc790\uc804\uac70\ub294 \ud070 \uc55e\ubc14\ud034 \ubc29\uc2dd\uacfc \ube44\uad50\ub418\ub294 \uc774\ub984\uc774\uc5c8\ub2e4. \ub450 \ubc14\ud034\uc758 \ud06c\uae30\uac00 \ube44\uc2b7\ud558\uace0 \uc0ac\ub78c\uc774 \uc549\ub294 \uc704\uce58\uac00 \ub0ae\uc544\uc9c4 \ud615\ud0dc\uac00 \ubc1c\uc804\ud588\ub2e4. \ub2e4\ub9cc \uc548\uc804\uc774\ub77c\ub294 \uc774\ub984\uc774 \uc0ac\uace0 \uac00\ub2a5\uc131\uc744 \ubaa8\ub450 \uc5c6\uc574\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uc124\uacc4\uc790\uac00 \ubb34\uc5c7\uc744 \ubb38\uc81c\ub85c \ubcf4\uc558\ub294\uc9c0\ub2e4. \ucd5c\uace0 \uc18d\ub3c4\ub9cc\uc774 \uc544\ub2c8\ub77c \ud0c0\uae30\uc640 \ub0b4\ub9ac\uae30, \uc77c\uc0c1\uc5d0\uc11c \ub2e4\ub8e8\uae30 \uc26c\uc6b4\uac00\uac00 \uac00\uce58\uac00 \ub418\uc5c8\ub2e4. \uae30\uc220\uc758 \uac1c\uc120\uc744 \uc0ac\uc6a9\uc790\uc758 \ubab8\uacfc \uc5f0\uacb0\ud574 \ubcf4\uba74, \uae30\uacc4\uc758 \uc678\ud615 \ubcc0\ud654\uac00 \uc0dd\ud65c\uc758 \ubcc0\ud654\ub85c \uc774\uc5b4\uc9c0\ub294 \uc774\uc720\uac00 \ubcf4\uc778\ub2e4. \ucc28\uccb4\ub294 \uc0ac\ub78c\uc774 \ud0c0\ub294 \ubb34\uac8c\uc640 \uae38\uc5d0\uc11c \ubc1b\ub294 \ud798\uc744 \uacac\ub38c\uc57c \ud558\uc9c0\ub9cc \ub108\ubb34 \ubb34\uac70\uc6b0\uba74 \uc6c0\uc9c1\uc774\uae30 \uc5b4\ub835\ub2e4. \uc18d\uc774 \ube48 \uae08\uc18d \uad00\uacfc \ubd80\ud488\uc744 \uc5f0\uacb0\ud558\ub294 \uad6c\uc870\ub294 \uc774\ub7f0 \uc694\uad6c\ub97c \ud568\uaed8 \ub2e4\ub8ec\ub2e4. \ub2e8\uc21c\ud788 \ud2bc\ud2bc\ud55c \uc7ac\ub8cc\ub97c \ub9ce\uc774 \uc4f0\ub294 \uac83\ub9cc\uc73c\ub85c \uc88b\uc740 \uc790\uc804\uac70\uac00 \ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubc14\ud034\uc640 \ubca0\uc5b4\ub9c1 \ub4f1\ub3c4 \ud68c\uc804\uacfc \ubb34\uac8c\ub97c \ud568\uaed8 \ub2e4\ub8e8\ub294 \ubd80\ud488\uc774\ub2e4. \uc644\uc131\ub41c \uc790\uc804\uac70\uc758 \uc544\ub984\ub2e4\uc6b4 \uc724\uacfd \ub4a4\uc5d0\ub294 \uc11c\ub85c \ub2e4\ub978 \ud798\uc744 \uc804\ub2ec\ud558\ub294 \uad6c\uc870\uac00 \uc788\ub2e4. \uc774\ub984\ub09c \ud55c \uc0ac\ub78c\uc758 \ubc1c\uba85\ud488\uc73c\ub85c\ub9cc \ubd80\ub974\uae30\ubcf4\ub2e4 \uc5ec\ub7ec \uc791\uc740 \uac1c\uc120\uc774 \ub9cc\ub09c \uacb0\uacfc\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \uc790\uc804\uac70\uc758 \uac01 \ubd80\ud488\uc740 \ub530\ub85c \ucd5c\uc801\ud654\ud560 \uc218 \uc788\ub294 \uac83\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc \uc2e4\uc81c \uc0ac\uc6a9\uc5d0\uc11c\ub294 \ud568\uaed8 \uc791\ub3d9\ud55c\ub2e4. \uac00\ubcbc\uc6b4 \ucc28\uccb4\uc5d0 \uc5b4\ub5a4 \ubc14\ud034\ub97c \ub2ec\uace0 \uc5b4\ub514\uc5d0 \ud398\ub2ec\uc744 \ub193\ub294\uc9c0\uc5d0 \ub530\ub77c \ubab8\uc758 \uc790\uc138\uc640 \uc870\uc885\uc758 \ub290\ub08c\uc774 \ubc14\ub010\ub2e4. \ubd80\ud488\uc758 \ubaa9\ub85d\ub9cc\uc73c\ub85c \uc644\uc131\ub41c \ud0c8\uac83\uc758 \uacbd\ud5d8\uc744 \uc804\ubd80 \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b4 \uc774\uc720\ub2e4. \uc61b \ub3c4\ud310\uc744 \ubcfc \ub54c\uc5d0\ub294 \ud604\uc7ac \uc81c\ud488\uacfc \ub2e4\ub978 \ubd80\ubd84\uc744 \uc624\ub958\ucc98\ub7fc \uc5ec\uae30\uae30\ubcf4\ub2e4 \uc5b4\ub5a4 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub824 \ud588\ub294\uc9c0 \ubb3c\uc5b4\ubcf4\uc790. \ud070 \uc55e\ubc14\ud034\ub294 \uc9c1\uc811 \uad6c\ub3d9\uc758 \uc870\uac74\uc5d0\uc11c \uc774\ud574\ud560 \uc218 \uc788\uace0, \ube44\uc2b7\ud55c \ud06c\uae30\uc758 \ub450 \ubc14\ud034\ub294 \uccb4\uc778\uc744 \ud1b5\ud55c \ud798\uc758 \uc804\ub2ec\uacfc \uc5f0\uacb0\ud574 \ubcfc \uc218 \uc788\ub2e4. \uadf8 \ube44\uad50\ub294 \uacfc\uac70\uc758 \uc124\uacc4\ub97c \ube44\uc6c3\ub294 \ub300\uc2e0 \uc124\uacc4\uc758 \uc120\ud0dd\uc744 \uc774\ud574\ud558\ub294 \ubc29\ubc95\uc774\ub2e4. \uae30\uc220\uc758 \uc5ed\uc0ac\ub294 \uc2e4\ud328\ud55c \ubaa8\uc591\ub4e4\uc774 \uc9c0\ub098\uac04 \uae38\uc774\uba74\uc11c \uac01 \uc2dc\ub300\uc758 \uc81c\uc57d \uc548\uc5d0\uc11c \ud569\ub9ac\uc801\uc778 \ub2f5\uc744 \ucc3e\uc740 \uacfc\uc815\uc774\uae30\ub3c4 \ud558\ub2e4. \uacf5\uae30 \ud0c0\uc774\uc5b4\ub294 \ubc14\ud034\uac00 \uae38\uc5d0\uc11c \ubc1b\ub294 \ucda9\uaca9\uc5d0 \ub300\uc751\ud558\ub294 \ubc29\ubc95\uc774\uc5c8\ub2e4. \ub2e8\ub2e8\ud55c \ubc14\ud034\ub85c \ub290\ub07c\ub358 \uc694\ucca0\uc774 \ub2e4\ub978 \uac10\uac01\uc73c\ub85c \ubc14\ub010\ub2e4. \uc18d\ub3c4\uc640 \uc131\ub2a5\uc744 \ub9d0\ud560 \ub54c\uc5d0\ub3c4 \ub3c4\ub85c \ud45c\uba74\uacfc \ud0c0\ub294 \uc0ac\ub78c\uc758 \ubab8\uc744 \ube7c\ub193\uc744 \uc218 \uc5c6\ub294 \uc774\uc720\ub2e4. \uacf5\uae30 \ud0c0\uc774\uc5b4\uc758 \uc55e\uc120 \ud2b9\ud5c8\uc640 \uc790\uc804\uac70\uc5d0\uc11c \ub110\ub9ac \uc4f0\uc774\uac8c \ub418\ub294 \uacfc\uc815\uc740 \uc2dc\uac04 \ucc28\uc774\uac00 \uc788\uc5c8\ub2e4. \ub358\ub86d\uc758 \uc801\uc6a9\uc774 \uc8fc\ubaa9\ubc1b\uc558\ub2e4\uace0 \uadf8\uc804\uc5d0\ub294 \uc544\ubb34\ub3c4 \ube44\uc2b7\ud55c \ubc1c\uc0c1\uc744 \ud558\uc9c0 \uc54a\uc558\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc1c\uc0c1\uc758 \ub4f1\uc7a5\uacfc \ud2b9\uc815 \uc6a9\ub3c4\uc5d0\uc11c \uc4f8 \ub9cc\ud574\uc9c0\ub294 \uacfc\uc815\uc744 \uad6c\ubd84\ud558\uba74 \ub2e8\ub3c5 \ucd5c\ucd08\uc758 \uc804\uc124\uc744 \ud53c\ud560 \uc218 \uc788\ub2e4. \uc61b \uae30\uc220\uc0ac \ucc45\uc740 \ub0ae\uc544\uc9c4 \ucc28\uccb4\uc640 \uc5ec\ub7ec \ud504\ub808\uc784 \ud615\ud0dc, \ub450 \uc0ac\ub78c\uc774 \ud568\uaed8 \ud0c0\ub294 \ubc29\uc2dd \ub4f1 \ub2e4\uc591\ud55c \ubcc0\ud615\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc0ac\uc6a9\uc790\ub294 \ud558\ub098\uc758 \ud45c\uc900\uc801\uc778 \ubab8\uacfc \ubaa9\uc801\ub9cc \uac00\uc9c4 \uc0ac\ub78c\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc5b4\ub5a4 \uc637\ucc28\ub9bc\uc73c\ub85c \ud0c0\uace0 \ubb34\uc5c7\uc744 \uc6b4\ubc18\ud560\uc9c0\uc5d0 \ub530\ub77c \uc694\uad6c\uac00 \ub2ec\ub790\ub2e4. \uae30\uacc4\uac00 \uc88b\uc544\uc84c\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ub204\uad6c\ub098 \uac19\uc740 \uae30\ud68c\ub97c \uc5bb\uc740 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uac00\uaca9\uacfc \ub3c4\ub85c \uc0c1\ud0dc, \ubc30\uc6b8 \uc7a5\uc18c\uc640 \uc8fc\ubcc0\uc758 \uc2dc\uc120\uc774 \uc774\uc6a9\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4. \ubc1c\uba85\uc758 \ubcf4\uae09\uc744 \ub9d0\ud560 \ub54c\uc5d0\ub294 \uc81c\ud488\uc758 \uc874\uc7ac\uc640 \uc2e4\uc81c\ub85c \uc0ac\uc6a9\ud560 \uc870\uac74\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ub450 \ubc14\ud034\uac00 \ube44\uc2b7\ud55c \ud06c\uae30\ub77c\ub294 \uc0ac\uc2e4\uc740 \ub108\ubb34 \uc790\uc5f0\uc2a4\ub7ec\uc6cc \uc774\uc720\ub97c \ubb3b\uae30 \uc5b4\ub835\ub2e4. \uadf8\ub7ec\ub098 \uacfc\uac70\uc758 \ud070 \uc55e\ubc14\ud034\uc640 \ube44\uad50\ud558\uba74 \uc624\ub298\uc758 \ud615\ud0dc\uac00 \uc5ec\ub7ec \ubb38\uc81c\uc5d0 \ub300\ud55c \ub2f5\uc774\uc5c8\uc74c\uc744 \uc54c \uc218 \uc788\ub2e4. \uccb4\uc778\uacfc \uae30\uc5b4\ub294 \ubc14\ud034\uc758 \ud06c\uae30\uc5d0 \ub9e1\uacbc\ub358 \uc77c\uc744 \ub2e4\ub974\uac8c \ud574\uacb0\ud588\ub2e4. \uc790\uc804\uac70\uc758 \uc5ed\uc0ac\ub294 \ubc1c\uba85\uc774 \uc5b8\uc81c\ub098 \ub354 \ud06c\uace0 \ub354 \ube60\ub978 \ubc29\ud5a5\uc73c\ub85c\ub9cc \uac04\ub2e4\ub294 \uc0dd\uac01\uc744 \ubc14\uafbc\ub2e4. \ub0ae\uc544\uc9c0\uace0 \uac00\ubcbc\uc6cc\uc9c0\uba70 \ub35c \ud754\ub4e4\ub9ac\ub294 \ubcc0\ud654\ub3c4 \uc911\uc694\ud588\ub2e4. \ube60\ub984\uc744 \ud3ec\uae30\ud55c \ud1f4\ubcf4\ucc98\ub7fc \ubcf4\uc774\ub358 \uc791\uc740 \ubc14\ud034\uac00 \ub2e4\ub978 \uc7a5\uce58\uc640 \ub9cc\ub098 \ub354 \ub113\uc740 \uac00\ub2a5\uc131\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \ud0c8 \uc218 \uc788\ub294 \uc0ac\ub78c\uacfc \ub2ec\ub9b4 \uc218 \uc788\ub294 \uae38\uc744 \ub113\ud788\ub294 \uc77c\uc774 \uae30\uc220\uc758 \uc9c4\ubcf4\ub97c \uc124\uba85\ud558\ub294 \ub610 \ud558\ub098\uc758 \uae30\uc900\uc774 \ub41c\ub2e4."}, {"id": "safety-elevator-building-height-and-trust", "title": "\uc5d8\ub9ac\ubca0\uc774\ud130 \u2014 \uc704\ub85c \uac00\ub294 \ud798\ubcf4\ub2e4 \uba48\ucd9c \uc218 \uc788\ub2e4\ub294 \ubbff\uc74c", "summary": "\uc2b9\uac15\uae30\uc758 \uc5ed\uc0ac\uc5d0\uc11c \ub04c\uc5b4\uc62c\ub9ac\ub294 \ud798\uacfc \uc548\uc804, \uace0\uce35 \uac74\ubb3c\uc758 \uc4f0\uc784\uc774 \ub9cc\ub098\ub294 \uc9c0\uc810\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\uc9d1\uacfc \uc0dd\ud65c \ub3c4\uad6c", "categories": ["everyday-inventions"], "url": "stories/safety-elevator-building-height-and-trust/index.html", "image": "../media/safety-elevator-building-height-and-trust.png", "alt": "19\uc138\uae30 \uc804\uc2dc\uc7a5 \uc548\uc758 \uc2b9\uac15\uae30 \ud50c\ub7ab\ud3fc\uacfc \uc774\ub97c \ubc14\ub77c\ubcf4\ub294 \uad00\uac1d\uc744 \uadf8\ub9b0 \ud574\uc11d\uc801 \uc0bd\ud654", "text": "\uc5d8\ub9ac\ubca0\uc774\ud130 \u2014 \uc704\ub85c \uac00\ub294 \ud798\ubcf4\ub2e4 \uba48\ucd9c \uc218 \uc788\ub2e4\ub294 \ubbff\uc74c \uc548\uc804\uc7a5\uce58\uc640 \uc5ec\ub7ec \ub3d9\ub825 \uae30\uc220\uc774 \ub192\uc740 \uac74\ubb3c\uc744 \uc0dd\ud65c\uc758 \uacf5\uac04\uc73c\ub85c \ubc14\uafb8\ub2e4 \uc2b9\uac15\uae30\uc758 \uc5ed\uc0ac\uc5d0\uc11c \ub04c\uc5b4\uc62c\ub9ac\ub294 \ud798\uacfc \uc548\uc804, \uace0\uce35 \uac74\ubb3c\uc758 \uc4f0\uc784\uc774 \ub9cc\ub098\ub294 \uc9c0\uc810\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc9d1\uacfc \uc0dd\ud65c \ub3c4\uad6c \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \ub192\uc740 \uac74\ubb3c\uc744 \uc138\uc6b8 \uc218 \uc788\ub2e4\ub294 \uac83\uacfc \uadf8 \uc704\uce35\uc5d0\uc11c \ub9e4\uc77c \uc0b4\uc544\uac08 \uc218 \uc788\ub2e4\ub294 \uac83\uc740 \ub2e4\ub978 \ubb38\uc81c\ub2e4. \uc544\uce68\ub9c8\ub2e4 \uae34 \uacc4\ub2e8\uc744 \uc624\ub974\ub0b4\ub824\uc57c \ud55c\ub2e4\uba74 \ub192\uc774\ub294 \uc804\ub9dd\uc758 \uc990\uac70\uc6c0\ubcf4\ub2e4 \ubab8\uc758 \ubd80\ub2f4\uc73c\ub85c \ub2e4\uac00\uc628\ub2e4. \uc0ac\ub78c\uc744 \uc704\uc544\ub798\ub85c \uc62e\uae30\ub294 \uc791\uc740 \ubc29\uc740 \uac74\ubb3c\uc744 \uc0ac\uc6a9\ud558\ub294 \ubc29\uc2dd\uc5d0 \ucee4\ub2e4\ub780 \uc601\ud5a5\uc744 \uc8fc\uc5c8\ub2e4. \uadf8\ub7f0\ub370 \uc2b9\uac15\uae30\ub97c \uc55e\uc5d0 \ub450\uace0 \uc0ac\ub78c\ub4e4\uc740 \uc18d\ub3c4\ub9cc \ubb3b\uc9c0 \uc54a\ub294\ub2e4. \uba48\ucd9c \uc218 \uc788\uc744\uae4c. \ubb38\uc81c\uac00 \uc0dd\uae30\uba74 \uc5b4\ub5bb\uac8c \ub420\uae4c. \uc5d8\ub9ac\ubca0\uc774\ud130\uc758 \uc5ed\uc0ac\uc5d0\ub294 \ub04c\uc5b4\uc62c\ub9ac\ub294 \ud798\uc744 \ub9cc\ub4dc\ub294 \uc77c\uacfc, \uc0ac\ub78c\uc744 \ud0dc\uc6cc\ub3c4 \ub41c\ub2e4\uace0 \ubbff\uac8c \ub9cc\ub4dc\ub294 \uc77c\uc774 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4. \uad11\uc0b0\uacfc \uc791\uc5c5\uc7a5\uc5d0\uc11c \ubb3c\uac74\uc744 \ub04c\uc5b4\uc62c\ub9ac\ub294 \uc7a5\uce58\ub294 \uc5ec\uac1d\uc6a9 \uc5d8\ub9ac\ubca0\uc774\ud130\ubcf4\ub2e4 \uc55e\uc11c \uc874\uc7ac\ud588\ub2e4. \ub192\uc740 \uacf3\uc73c\ub85c \ubb34\uac8c\ub97c \uc62e\uae34\ub2e4\ub294 \ubb38\uc81c\ub294 \uc624\ub798\ub41c \uac83\uc774\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \uc0ac\ub78c\uc774 \ub9e4\uc77c \ud3b8\ud558\uac8c \uc774\uc6a9\ud558\ub294 \uad50\ud1b5\uc218\ub2e8\uc774 \ub418\ub824\uba74 \uc774\ub3d9\uc758 \uae30\ub2a5\uc5d0 \ub354\ud574 \uc548\uc804\uacfc \ud3b8\uc758\uc758 \uc870\uac74\uc774 \ud544\uc694\ud588\ub2e4. \ub450 \uc7a5\uce58\ub97c \uc804\ud600 \ubb34\uad00\ud55c \ubc1c\uba85\uc73c\ub85c \ub098\ub20c \ud544\uc694\ub3c4, \ubb3c\uac74\uc744 \uc2e4\uc5b4 \uc62c\ub9b4 \uc218 \uc788\uc73c\uba74 \uace7\ubc14\ub85c \uc0ac\ub78c\ub3c4 \uc548\uc2ec\ud558\uace0 \ud0c8 \uc218 \uc788\ub2e4\uace0 \ubcfc \ud544\uc694\ub3c4 \uc5c6\ub2e4. \uac19\uc740 \ubb3c\ub9ac\uc801 \ubb38\uc81c\uc5d0 \ub2e4\ub978 \uc694\uad6c\uac00 \ucd94\uac00\ub41c \uc148\uc774\ub2e4. \uae30\uacc4\uc758 \uc5ed\uc0ac\ub294 \uc0c8\ub85c\uc6b4 \ud798\uc774 \uc0dd\uae30\ub294 \uc77c\ubfd0 \uc544\ub2c8\ub77c, \uc0ac\uc6a9\uc790\uac00 \uc694\uad6c\ud558\ub294 \uc870\uac74\uc774 \ub2ec\ub77c\uc9c0\ub294 \uc77c\uc774\uae30\ub3c4 \ud558\ub2e4. 1900\ub144\uc758 \ubc1c\uba85\uc0ac\ub294 \uc99d\uae30\uc640 \uc218\uc555, \uc804\uae30\ub97c \uc774\uc6a9\ud55c \uc2b9\uac15\uae30\ub97c \ud568\uaed8 \uc18c\uac1c\ud55c\ub2e4. \uc624\ub298\uc758 \uc775\uc219\ud55c \ubaa8\uc2b5\ub9cc \ub5a0\uc62c\ub9ac\uba74 \uadf8 \uc55e\uc758 \uc5ec\ub7ec \uacbd\ub85c\ub97c \ub193\uce58\uae30 \uc27d\ub2e4. \uc5b4\ub5a4 \ub3d9\ub825\uc744 \uc4f0\uace0 \uac74\ubb3c \uc548\uc5d0 \uc5b4\ub5bb\uac8c \ubc30\uce58\ud560\uc9c0\uc5d0 \ub530\ub77c \uc7a5\uce58\uc758 \uc870\uac74\uacfc \ud544\uc694\ud55c \uc2dc\uc124\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \uadf8\ub798\uc11c \uc5d8\ub9ac\ubca0\uc774\ud130\ub97c \ud55c \uc0ac\ub78c\uc774 \uc5b4\ub290 \ub0a0 \uc644\uc131\ud55c \ud55c \uc885\ub958\uc758 \uae30\uacc4\ub85c\ub9cc \uc124\uba85\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \uc5ec\ub7ec \ubc29\uc2dd\uc774 \uc4f0\uc774\uace0 \uac1c\uc120\ub418\uba70 \uc0ac\ub78c\uc744 \uc6b4\ubc18\ud558\ub294 \uc7a5\uce58\uac00 \uc0dd\ud65c \uc18d\uc5d0 \uc790\ub9ac \uc7a1\uc558\ub2e4. \uae30\uc220\uc758 \uc774\ub984\uc774 \ud558\ub098\ub85c \ub0a8\uc544 \uc788\uc5b4\ub3c4 \uadf8 \uc548\uc5d0\uc11c \uc791\ub3d9\ud558\ub294 \uc138\ubd80\ub294 \uae34 \uc2dc\uac04 \ub3d9\uc548 \ubc14\ub014 \uc218 \uc788\ub2e4. \uc2b9\uac15\uae30\ub294 \uc704\ub85c \uc6c0\uc9c1\uc774\ub294 \uc21c\uac04\ub9cc\uc744 \uc704\ud574 \uc124\uacc4\ub418\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc54c\ub9de\uc740 \uacf3\uc5d0 \uba48\ucd94\uace0 \uc18d\ub3c4\uac00 \uc9c0\ub098\uce58\uac8c \ucee4\uc9c0\ub294 \uac83\uc744 \ub9c9\uc73c\uba70 \uc704\ud5d8\ud55c \uc0c1\ud669\uc5d0 \ub300\ube44\ud574\uc57c \ud55c\ub2e4. \uc61b \ubc1c\uba85\uc0ac\ub3c4 \uc18d\ub3c4 \uc870\uc808\uacfc \uc548\uc804\uc744 \uc704\ud55c \uc5ec\ub7ec \uc7a5\uce58\ub97c \uc911\uc694\ud55c \uc694\uc18c\ub85c \uc124\uba85\ud55c\ub2e4. \uc6c0\uc9c1\uc784\uc744 \uc798 \ub9cc\ub4dc\ub294 \uae30\uc220\uc5d0 \uba48\ucda4\uc744 \ub2e4\ub8e8\ub294 \uae30\uc220\uc774 \ubd99\uc5c8\ub2e4. \uc548\uc804\uc7a5\uce58\uac00 \uc788\ub2e4\ub294 \ub9d0\uc744 \uc5b4\ub5a4 \uc0c1\ud669\uc5d0\uc11c\ub3c4 \uc0ac\uace0\uac00 \ub0a0 \uc218 \uc5c6\ub2e4\ub294 \ubcf4\uc99d\uc73c\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc7a5\uce58\uc758 \uc124\uacc4\uc640 \uc124\uce58, \uc810\uac80\uacfc \uc6b4\uc6a9\uc774 \ud568\uaed8 \ud544\uc694\ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \uc548\uc804\uc740 \ubd80\ud488 \ud558\ub098\uc758 \uc774\ub984\uc774 \uc544\ub2c8\ub77c \uc5ec\ub7ec \uc870\uac74\uc758 \uad00\uacc4\ub85c \uc774\ud574\ud558\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \uc624\ub798\ub41c \ubc1c\uba85\uc758 \uc990\uac70\uc6c0\uc5d0\ub3c4 \uc774\ub7f0 \uad6c\ubd84\uc740 \ub0a8\uaca8 \ub458 \uc218 \uc788\ub2e4. \uc5d8\ub9ac\ubca0\uc774\ud130\uc758 \uc5ed\uc0ac\uc5d0\uc11c E. G. \uc624\ud2f0\uc2a4\ub294 \uc548\uc804\uacfc \uad00\ub828\ub41c \uac1c\uc120\uc73c\ub85c \uc911\uc694\ud558\uac8c \uae30\uc5b5\ub418\ub294 \uc778\ubb3c\uc774\ub2e4. \ucc38\uace0\ud55c 1900\ub144 \ubc1c\uba85\uc11c\ub294 1861\ub144\uc758 \ud2b9\ud5c8\ub3c4 \uc18c\uac1c\ud55c\ub2e4. \uc5ec\uae30\uc11c\ub294 \uadf8 \ud2b9\ud5c8\ub97c \uc0ac\ub78c\ub4e4\uc774 \uc704\ub85c \uc774\ub3d9\ud558\ub294 \ubaa8\ub4e0 \uc7a5\uce58\uc758 \uccab \uc2dc\uc791\uc774\ub77c\uace0 \ubd80\ub974\uc9c0 \uc54a\ub294\ub2e4. \uae34 \ubc1c\uc804 \uacfc\uc815\uc758 \ud55c \uc911\uc694\ud55c \ud754\uc801\uc73c\ub85c \uc77d\ub294\ub2e4. \uc774 \uad6c\ubd84\uc740 \ubc1c\uba85\uac00\uc758 \uacf5\ub85c\ub97c \uc904\uc774\ub824\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \ud55c \uc0ac\ub78c\uc758 \uc774\ub984\uc774 \uc720\uba85\ud574\uc9c0\uba74 \uc55e\uc120 \uc2dc\ub3c4\uc640 \ub4a4\uc774\uc740 \uac1c\uc120, \uc2e4\uc81c\ub85c \uc81c\uc791\ud558\uace0 \uc720\uc9c0\ud55c \uc0ac\ub78c\ub4e4\uc774 \ud55c\uaebc\ubc88\uc5d0 \uc0ac\ub77c\uc9c0\uae30 \uc27d\uae30 \ub54c\ubb38\uc774\ub2e4. \uc774\ub984\uc744 \uae30\uc5b5\ud558\uba74\uc11c\ub3c4 \uadf8 \uc774\ub984\ub9cc\uc73c\ub85c \uae30\uc220\uc758 \ubaa8\ub4e0 \uc2dc\uac04\uc744 \ub300\uc2e0\ud558\uc9c0 \uc54a\ub294 \ud3b8\uc774 \ub354 \ud48d\ubd80\ud55c \uc774\uc57c\uae30\ub97c \ub9cc\ub4e0\ub2e4. \uc704\ub85c \uc774\ub3d9\ud558\ub294 \ubd80\ub2f4\uc774 \uc904\uba74 \uac74\ubb3c\uc758 \ub192\uc740 \uce35\uc744 \ud65c\uc6a9\ud560 \uc5ec\uc9c0\uac00 \ub113\uc5b4\uc9c4\ub2e4. \ucca0\uace8 \ub4f1 \uac74\ucd95 \uae30\uc220\uc758 \ubc1c\uc804\uacfc \uc2b9\uac15\uae30\uc758 \ubcf4\uae09\uc774 \ud568\uaed8\ud558\uba74\uc11c \uace0\uce35\uc758 \uc0ac\ubb34\uc2e4\uacfc \uc0dd\ud65c \uacf5\uac04\uc744 \uc2e4\uc81c\ub85c \uc6b4\uc601\ud558\ub294 \uc870\uac74\uc774 \ub2ec\ub77c\uc84c\ub2e4. \uac74\ubb3c\uc744 \ub354 \ub192\uac8c \uc138\uc6b8 \uc218 \uc788\ub2e4\ub294 \uac00\ub2a5\uc131\uc774 \uc0ac\uc6a9\ud558\ub294 \uc0ac\ub78c\uc758 \uc774\ub3d9\uacfc \ub9cc\ub09c \uac83\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \ub3c4\uc2dc\uc758 \uc784\ub300\ub8cc\uc640 \uac74\ubb3c \uac00\uce58\uac00 \uc5d8\ub9ac\ubca0\uc774\ud130 \ud558\ub098\ub85c \uacb0\uc815\ub418\uc5c8\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub545\uac12\uacfc \uc218\uc694, \uac74\ucd95\uacfc \uc81c\ub3c4\ub3c4 \uc601\ud5a5\uc744 \uc900\ub2e4. \uc5ec\uae30\uc11c \uc911\uc694\ud55c \uac83\uc740 \ub192\uc774\uc5d0 \uad00\ud55c \ud55c \uac00\uc9c0 \uc7a5\ubcbd\uc774 \ubc14\ub00c\uc5c8\ub2e4\ub294 \uc810\uc774\ub2e4. \ub3c4\uc2dc\ub97c \ub9cc\ub4dc\ub294 \uae30\uc220\uc740 \uac74\ubb3c\uc744 \uc138\uc6b0\ub294 \uae30\uc220\uacfc \uadf8 \uc548\uc744 \uc624\uac00\ub294 \uae30\uc220\uc744 \ud568\uaed8 \ud3ec\ud568\ud55c\ub2e4. \uae30\uacc4\uac00 \uc548\uc804\ud558\ub2e4\ub294 \ubaa8\uc2b5\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc2dc\uc5f0\uc740 \uac15\ud55c \uc778\uc0c1\uc744 \uc904 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc804\uc2dc\uc7a5 \uc7a5\uba74\uc740 \uadf8\ub7f0 \uc0c1\ud669\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc704\ud55c \uc0bd\ud654\ub2e4. \ud2b9\uc815\ud55c \ub0a0\uc758 \uc2e4\uc81c \ud589\uc0ac\ub098 \uc815\ud655\ud55c \uc7a5\uce58\ub97c \ubcf5\uc6d0\ud55c \uadf8\ub9bc\uc740 \uc544\ub2c8\ub2e4. \ud55c \uc7a5\uba74\uc758 \uc124\ub4dd\ub825\uacfc \uc5ed\uc0ac\uc801 \uc0ac\uc2e4\uc758 \ud655\uc778\uc740 \ub530\ub85c \uc0dd\uac01\ud558\uba74 \uc88b\ub2e4. \uc2e4\uc81c\ub85c \ub9ce\uc740 \uc0ac\ub78c\uc774 \uc77c\uc0c1\uc801\uc73c\ub85c \uc774\uc6a9\ud558\ub824\uba74 \ubc18\ubcf5\ub41c \uc6b4\uc6a9\uacfc \uc720\uc9c0\uac00 \uc774\uc5b4\uc838\uc57c \ud55c\ub2e4. \ud55c \ubc88 \uc6c0\uc9c1\uc600\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc624\ub7ab\ub3d9\uc548 \uc798 \uad00\ub9ac\ub418\uc5b4 \uc0ac\uc6a9\ub41c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub974\ub2e4. \ubc1c\uba85\uc758 \uc720\uba85\ud55c \uc21c\uac04\uc744 \uc9c0\ub098 \uadf8 \ub4a4\uc758 \uc810\uac80\uacfc \ub178\ub3d9\uae4c\uc9c0 \uc0dd\uac01\ud558\uba74 \uc775\uc219\ud55c \ud3b8\ub9ac\ud568\uc774 \uc870\uae08 \ub35c \ub2f9\uc5f0\ud558\uac8c \ubcf4\uc778\ub2e4. \uc624\ub298\uc758 \uc5d8\ub9ac\ubca0\uc774\ud130\uc5d0\uc11c \uc6b0\ub9ac\ub294 \uce35\uc218\ub97c \ub204\ub974\uace0 \uc7a0\uae50 \uae30\ub2e4\ub9b0\ub2e4. \uc9e7\uc740 \uc2dc\uac04\uc5d0 \ub05d\ub098\ub294 \ub3d9\uc791\uc774\ub77c \uadf8 \ub4a4\uc758 \uae34 \ubc1c\uc804\uc744 \ub5a0\uc62c\ub9ac\uae30\ub294 \uc5b4\ub835\ub2e4. \uadf8\ub7ec\ub098 \uc0ac\ub78c\uc744 \uc62c\ub9ac\uace0 \uba48\ucd94\uace0 \uc548\uc804\ud558\uac8c \ub0b4\ub9ac\uac8c \ud558\ub294 \uc5ec\ub7ec \uc870\uac74\uc774 \ub9de\uc544\uc57c \uc774 \uc77c\uc0c1\uc774 \uac00\ub2a5\ud558\ub2e4. \ubb38\uc774 \uc5f4\ub9ac\ub294 \uc21c\uac04\uc740 \ub9ce\uc740 \uae30\uc220\uc774 \ud568\uaed8 \uc57d\uc18d\uc744 \uc9c0\ud0a8 \uacb0\uacfc\ub2e4. \uae38\uc740 \ub545 \uc704\uc5d0\ub9cc \ub193\uc774\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc2b9\uac15\uae30\ub294 \uac74\ubb3c \uc548\uc5d0 \uc138\ub85c \ubc29\ud5a5\uc758 \uae38\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \ub192\uc740 \uac74\ubb3c\uc758 \uc0ac\uc9c4\uc744 \ubcfc \ub54c \uaf2d\ub300\uae30\ub9cc \uc62c\ub824\ub2e4\ubcf4\uc9c0 \ub9d0\uace0 \uadf8\uacf3\uae4c\uc9c0 \ub9e4\uc77c \uc624\uac00\ub294 \uc0ac\ub78c\ub3c4 \uc0dd\uac01\ud574 \ubcf4\uc790. \uc5d8\ub9ac\ubca0\uc774\ud130\uc758 \uc5ed\uc0ac\ub294 \ub192\uc774\ub97c \uc790\ub791\ud558\ub294 \uc774\uc57c\uae30\uc5d0\uc11c \ub192\uc774\ub97c \uc0dd\ud65c\ub85c \ubc14\uafb8\ub294 \uc774\uc57c\uae30\ub85c \uc774\uc5b4\uc9c4\ub2e4."}, {"id": "scent-bead-norigae", "title": "\uc774 \ubaa9\uac78\uc774 \uac19\uc740 \uc7a5\uc2dd\uc740 \uce58\ub9c8 \uc18d\uc5d0 \uc228\uc5c8\ub2e4", "summary": "\uad6c\uc2ac\ucc98\ub7fc \uc774\uc5b4\uc9c4 \uc7a5\uc2e0\uad6c\uac00 \ud5a5\uae30\ub97c \uac04\uc9c1\ud558\ub358 \ubc29\ubc95\uc744 \ub4e4\uc5ec\ub2e4\ubd05\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\uc637\uacfc \uc7ac\ub8cc", "categories": ["everyday-inventions"], "url": "stories/scent-bead-norigae/index.html", "image": "../media/scent-bead-norigae.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc904\ud5a5\ub178\ub9ac\uac1c \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc774 \ubaa9\uac78\uc774 \uac19\uc740 \uc7a5\uc2dd\uc740 \uce58\ub9c8 \uc18d\uc5d0 \uc228\uc5c8\ub2e4 \ub208\ubcf4\ub2e4 \ucf54\uac00 \uba3c\uc800 \ub9cc\ub098\ub294 \ub178\ub9ac\uac1c \uad6c\uc2ac\ucc98\ub7fc \uc774\uc5b4\uc9c4 \uc7a5\uc2e0\uad6c\uac00 \ud5a5\uae30\ub97c \uac04\uc9c1\ud558\ub358 \ubc29\ubc95\uc744 \ub4e4\uc5ec\ub2e4\ubd05\ub2c8\ub2e4. \uc637\uacfc \uc7ac\ub8cc \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \uc0ac\uc9c4 \uc18d \ubb3c\uac74\uc740 \uae34 \ubaa9\uac78\uc774\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uc0c9\uc774 \ub2e4\ub978 \uc791\uc740 \uc54c\ub4e4\uc774 \uc904\uc744 \ub530\ub77c \uc774\uc5b4\uc9c0\uace0, \uc544\ub798\uc5d0\ub294 \uc220\uc774 \ub2ec\ub838\ub2e4. \uadf8\ub7f0\ub370 \uc774\ub984\uc740 \ubaa9\uac78\uc774\uac00 \uc544\ub2c8\ub77c \uc904\ud5a5\ub178\ub9ac\uac1c\ub2e4. \uc7a5\uc2e0\uad6c\ub77c\uba74 \ub0a8\uc5d0\uac8c \ubcf4\uc5ec \uc8fc\ub294 \ubb3c\uac74\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \uc774 \ub178\ub9ac\uac1c\ub294 \uc870\uae08 \ub2e4\ub974\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc5d0\ub294 \uc740\uc740\ud55c \ud5a5\uae30\ub97c \ud48d\uae30\ub3c4\ub85d \uce58\ub9c8 \uc18d\uc5d0 \ucc3c\ub2e4\uace0 \uc801\ud600 \uc788\ub2e4. \ub208\uc5d0 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc790\ub9ac\uc5d0\ub3c4 \uafb8\ubc08\uc774 \uc788\uc5c8\ub358 \uc148\uc774\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc740 \uc904\ud5a5\uc744 \ud5a5\uc73c\ub85c \ub9cc\ub4e0 \ub465\uadfc \uc54c\uc744 \uc774\uc5b4 \ub193\uc740 \uac83\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \ud5a5\uc744 \uad6c\uc2ac \ubaa8\uc591\uc73c\ub85c \ube5a\uc5b4 \uc0c9\uc744 \uce60\ud558\uac70\ub098 \ucc9c\uc73c\ub85c \uc2f8\uc11c, \uc5fc\uc8fc\ucc98\ub7fc \uc5f0\uacb0\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc774 \uc18c\uc7a5\ud488\uc758 \uc124\uba85\uc5d0\ub294 \ubd89\uc740\uc0c9\uacfc \ud669\uc0c9, \ub179\uc0c9, \ud770\uc0c9\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uc0c9\uc744 \ucc3e\ub2e4 \ubcf4\uba74 \ucc98\uc74c\uc5d0\ub294 \uadf8\uc800 \uc608\uc05c \uad6c\uc2ac\uc774\ub77c\uace0 \uc5ec\uacbc\ub358 \ubd80\ubd84\uc744 \ub2e4\uc2dc \ubcf4\uac8c \ub41c\ub2e4. \ubaa8\uc591\ubfd0 \uc544\ub2c8\ub77c \ud5a5\uae30\ub97c \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ud558\ub294 \ubb3c\uac74\uc774\ub2e4. \ub178\ub9ac\uac1c\ub294 \uc800\uace0\ub9ac \uace0\ub984\uc774\ub098 \uce58\ub9c8\ud5c8\ub9ac \ub048\uc5d0 \ucc28\ub294 \uc7a5\uc2e0\uad6c\ub2e4. \uc904\ud5a5\ub178\ub9ac\uac1c \uc5ed\uc2dc \uc637\uacfc \ud568\uaed8 \uc4f0\uc600\uc9c0\ub9cc, \ubc15\ubb3c\uad00\uc740 \uce58\ub9c8 \uc18d\uc5d0 \ucc28\ub294 \uc4f0\uc784\uc744 \ub530\ub85c \uc18c\uac1c\ud55c\ub2e4. \uac89\uc73c\ub85c \ub4dc\ub7ec\ub098\ub294 \uc7a5\uc2dd\uacfc \ud5a5\uae30\ub97c \uac00\uae4c\uc774 \ub450\ub294 \uc77c\uc740 \uaf2d \uac19\uc744 \ud544\uc694\uac00 \uc5c6\uc5c8\ub2e4. \uc624\ub298\ub0a0 \ud5a5\uc218\ub97c \ubfcc\ub9ac\ub294 \uc77c\uacfc \ub098\ub780\ud788 \ub5a0\uc62c\ub9b4 \uc218\ub294 \uc788\ub2e4. \ub2e4\ub9cc \uc774 \ubb3c\uac74\uc5d0 \uc5b4\ub5a4 \ud5a5 \uc7ac\ub8cc\uac00 \ub4e4\uc5b4\uac14\ub294\uc9c0, \ud5a5\uc774 \uc5bc\ub9c8\ub098 \uc624\ub798\uac14\ub294\uc9c0\uae4c\uc9c0 \ud655\uc778\ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0ac\uc9c4\ub9cc \ubcf4\uace0 \uaf43\ud5a5\uae30\uc600\uc744 \uac83\uc774\ub77c\uace0 \uc815\ud574 \ubc84\ub9ac\uba74 \uc774\uc57c\uae30\uac00 \ubb3c\uac74\ubcf4\ub2e4 \uc55e\uc11c \ub098\uac04\ub2e4. \uc7a5\uc2e0\uad6c\ub294 \ub0a8\uc5d0\uac8c \ubcf4\uc774\ub294 \ubb3c\uac74\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \uc904\ud5a5\ub178\ub9ac\uac1c\ub294 \ud5a5\uc744 \uac00\uae4c\uc774 \ub450\ub294 \uc4f0\uc784\uc744 \ud1b5\ud574 \uadf8 \uc0dd\uac01\uc744 \uc870\uae08 \ub113\ud78c\ub2e4. \uce58\ub9c8 \uc18d\uc5d0 \ucc3c\ub2e4\ub294 \uc124\uba85\uc740 \ubc18\ub4dc\uc2dc \ubc16\uc73c\ub85c \ub4dc\ub7ec\ub098\uc57c\ub9cc \uc7a5\uc2dd\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc785\uc740 \uc0ac\ub78c\uc774 \ub290\ub07c\ub294 \uac10\uac01\uacfc \ub2e4\ub978 \uc0ac\ub78c\uc774 \ubcf4\ub294 \ubaa8\uc2b5\uc740 \ub2e4\ub97c \uc218 \uc788\uc5c8\ub2e4. \ud5a5\uc744 \uc0ac\uc6a9\ud588\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ub2f9\uc2dc \ucc29\uc6a9\uc790\uc758 \uac10\uc815\uc744 \ub300\uc2e0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc2dc\uc6d0\ud588\uc744\uc9c0 \ud3b8\uc548\ud588\uc744\uc9c0, \uc5b4\ub290 \uc21c\uac04 \ud5a5\uc744 \ub9e1\uc558\uc744\uc9c0\uae4c\uc9c0\ub294 \ud655\uc778\ub418\uc9c0 \uc54a\ub294\ub2e4. \uadf8\ub807\uc9c0\ub9cc \uc2dc\uac01 \uc678\uc758 \uac10\uac01\uc744 \uace0\ub824\ud55c \ubb3c\uac74\uc774\ub77c\ub294 \uc810\uc740 \ubd84\uba85\ud55c \uad00\uc2ec\uac70\ub9ac\uac00 \ub41c\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uc804\ud574\uc9c0\uc9c0 \uc54a\ub294 \uae30\ub2a5\uc744 \ud574\uc124\uc774 \uc54c\ub824 \uc8fc\ub294 \uc0ac\ub840\ub2e4. \ub465\uadfc \uc54c\uc744 \uc774\uc5b4 \ub193\uc73c\uba74 \uc904\uc758 \uae38\uc774\uc640 \uad6c\uc2ac\uc758 \ubc18\ubcf5\uc774 \ud558\ub098\uc758 \ud615\ud0dc\ub97c \ub9cc\ub4e0\ub2e4. \ud5a5\uc744 \ube5a\uace0 \uc0c9\uc744 \uce60\ud558\uac70\ub098 \ucc9c\uc73c\ub85c \uc2f8\ub294 \uc81c\uc791 \ubc29\uc2dd\uc740 \ub2e8\uc21c\ud55c \uac00\ub8e8\ub97c \ub2f4\uc544 \ub193\ub294 \uac83\uacfc \ub2e4\ub978 \ubaa8\uc591\uc744 \uc900\ub2e4. \uc7ac\ub8cc\uc758 \uc131\uc9c8\uc744 \ud2b9\uc815\ud55c \ubab8 \uc7a5\uc2dd\uc73c\ub85c \uc0ac\uc6a9\ud560 \uc218 \uc788\uac8c \ubc14\uafbc \uac83\uc774\ub2e4. \uc190\uc73c\ub85c \ub9cc\ub4dc\ub294 \uacfc\uc815\uacfc \ucc29\uc6a9\uc758 \ubc29\uc2dd\uc774 \uc11c\ub85c \uc5f0\uacb0\ub41c\ub2e4. \ub2e4\ub9cc \uc774 \uc18c\uc7a5\ud488\uc5d0 \uc4f0\uc778 \ubaa8\ub4e0 \uc6d0\ub8cc\uc640 \ubc30\ud569, \uc81c\uc791 \uc21c\uc11c\ub97c \uc0c1\uc138\ud788 \uc54c \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc77c\ubc18\uc801\uc778 \uc904\ud5a5 \uc124\uba85\uacfc \uc774 \ubb3c\uac74\uc5d0\uc11c \ud655\uc778\ud55c \ud2b9\uc9d5\uc744 \ub098\ub204\uc5b4 \uc77d\uc73c\uba74 \ub41c\ub2e4. \ud654\ub824\ud55c \uc0c9\uc774 \ubcf4\uc778\ub2e4\uace0 \ud2b9\uc815\ud55c \uaf43\uc774\ub098 \uc57d\uc7ac\uc758 \uc774\ub984\uc744 \ubd99\uc774\uc9c0 \uc54a\ub294\ub2e4. \ubaa8\uc591\uacfc \uc0c9\uc5d0 \uad00\ud55c \uc815\ubcf4\uac00 \ud5a5\uc758 \uc885\ub958\ub97c \uc790\ub3d9\uc73c\ub85c \uc54c\ub824 \uc8fc\uc9c0\ub294 \uc54a\uae30 \ub54c\ubb38\uc774\ub2e4. \ubd89\uc740\uc0c9\uacfc \ud669\uc0c9, \ub179\uc0c9\uacfc \ud770\uc0c9\uc774\ub77c\ub294 \uad6c\ubd84\uc740 \uc0ac\uc9c4\uc758 \uc904\uc744 \ucc9c\ucc9c\ud788 \ub530\ub77c\uac00\uac8c \ud55c\ub2e4. \uc791\uc740 \uc54c\ub4e4\uc774 \uac19\uc740 \ubaa8\uc591\ub9cc \ubc18\ubcf5\ud558\ub294\uc9c0, \uc0c9\uc774 \uc5b4\ub290 \uc21c\uc11c\ub85c \ub193\uc600\ub294\uc9c0 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uc790\ub8cc\uac00 \uc54c\ub824 \uc8fc\ub294 \uc0c9\uc744 \uae30\uc900\uc73c\ub85c \ubcf4\ub418 \ucd2c\uc601\uacfc \ud654\uba74\uc5d0\uc11c \uc0c9\uc774 \ub2ec\ub77c \ubcf4\uc77c \uc218 \uc788\ub2e4\ub294 \uc810\ub3c4 \uae30\uc5b5\ud558\uba74 \uc88b\ub2e4. \ub208\uc55e\uc758 \uc0ac\uc9c4\uc774 \ucc98\uc74c \uc81c\uc791\ud55c \ub0a0\uc758 \uc0c9\uc744 \uc644\uc804\ud788 \ub418\uc0b4\ub9ac\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uce58\ub9c8 \uc18d\uc774\ub77c\ub294 \uc4f0\uc784\uacfc \uc0c9\uc758 \uafb8\ubc08\uc744 \ud568\uaed8 \ub193\uc73c\uba74 \ub610 \ub2e4\ub978 \uc9c8\ubb38\uc774 \uc0dd\uae34\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\uc744 \uc218 \uc788\ub294 \ubd80\ubd84\uc5d0\ub3c4 \uc0ac\ub78c\ub4e4\uc774 \ud615\uc0c1\uacfc \uc0c9\uc744 \ub9c8\ub828\ud588\ub2e4\ub294 \uac83\uc774\ub2e4. \uc774\uac83\uc744 \uc0ac\uce58\ub098 \ube44\ubc00\uc2a4\ub7ec\uc6b4 \ud48d\uc2b5 \ud558\ub098\ub85c \ub2e8\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ubb3c\uac74\uc744 \uace0\ub974\uace0 \ub9cc\ub4dc\ub294 \uc0ac\ub78c\uc5d0\uac8c \ubc14\uae65\uc758 \uc2dc\uc120\ub9cc\uc774 \uc720\uc77c\ud55c \uae30\uc900\uc740 \uc544\ub2c8\uc5c8\uc744 \uc218 \uc788\uc74c\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ubaa8\uc591\uc774 \ub2ee\uc740 \uc624\ub298\uc758 \ubb3c\uac74\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc77c\uc740 \uc774\ud574\ub97c \ub3d5\uc9c0\ub9cc \uc4f0\uc784\uc744 \ud655\uc815\ud558\ub294 \uadfc\uac70\uac00 \ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubaa9\uac78\uc774 \uac19\uc544 \ubcf4\uc778\ub2e4\ub294 \uccab \uac10\uc0c1 \ub4a4\uc5d0 \ubc15\ubb3c\uad00\uc758 \uba85\uce6d\uacfc \ucc29\uc6a9 \uc124\uba85\uc744 \ub193\uc73c\uba74 \ub2e4\ub978 \uc0dd\ud65c\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \uc775\uc219\ud55c \ud615\ud0dc\ub97c \ubc1c\uacac\ud55c \ub2e4\uc74c \ub0af\uc120 \uc0ac\uc6a9\ubc95\uc744 \ubc30\uc6b0\ub294 \uc21c\uc11c\ub2e4. \uc720\ubb3c\uc744 \uac00\uae4c\uc774 \ubcf4\ub294 \uc7ac\ubbf8\uac00 \uc5ec\uae30\uc5d0 \uc788\ub2e4. \ub178\ub9ac\uac1c\ub294 \uc637\uacfc \ubab8, \uc6c0\uc9c1\uc784\uacfc \uac10\uac01\uc774 \ub9cc\ub098\ub294 \ub3c4\uad6c\ub2e4. \uc804\uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc815\uc9c0\ud55c \uc904\ub9cc \ubcf4\uc5ec\ub3c4 \uc6d0\ub798\ub294 \ucc29\uc6a9\ud558\ub294 \uc0ac\ub78c\uacfc \uad00\uacc4\ub97c \ub9fa\uc5c8\ub358 \ubb3c\uac74\uc774\uc5c8\ub2e4. \ud5a5\uc774 \uc9c0\uae08\ub3c4 \ub09c\ub2e4\uace0 \ud655\uc778\ud558\uc9c0\ub294 \uc54a\uc73c\uba74\uc11c \uadf8 \uae30\ub2a5\uc758 \uae30\ub85d\uc744 \uc77d\uc744 \uc218 \uc788\ub2e4. \uc0ac\uc9c4\uc73c\ub85c\ub294 \ub9e1\uc744 \uc218 \uc5c6\ub294 \uc7a5\uc2dd\uc758 \ud55c \uba74\uc774 \uc791\uc740 \uad6c\uc2ac\ub4e4 \uc0ac\uc774\uc5d0\uc11c \ub5a0\uc624\ub978\ub2e4. \uc774 \ub178\ub9ac\uac1c\uc758 \uc7ac\ubbf8\ub294 \uc4f0\uc784\uc744 \uc54c\uace0 \ub098\uc11c \ubaa8\uc2b5\uc774 \ub2ec\ub77c \ubcf4\uc778\ub2e4\ub294 \ub370 \uc788\ub2e4. \uae38\uac8c \uc774\uc5b4\uc9c4 \uc54c\ub4e4\uc740 \uc0c9\uc744 \ub098\ub204\ub294 \uc7a5\uc2dd\uc778 \ub3d9\uc2dc\uc5d0 \ud5a5\uc744 \uac04\uc9c1\ud558\ub294 \ubd80\ubd84\uc774\uc5c8\ub2e4. \uc9c0\uae08 \uc0ac\uc9c4\uc5d0\uc11c\ub294 \ud5a5\uae30\ub97c \ub9e1\uc744 \uc218 \uc5c6\ub2e4. \uadf8\ub798\ub3c4 \uce58\ub9c8 \uc18d\uc5d0 \ub2ec\uc558\ub2e4\ub294 \uc9e7\uc740 \uc124\uba85 \ub355\ubd84\uc5d0, \uc624\ub798\ub41c \uc7a5\uc2e0\uad6c\uac00 \uc720\ub9ac\uc7a5 \uc548\uc758 \ubc18\uc9dd\uc774\ub294 \ubb3c\uac74\uc5d0\uc11c \uc77c\uc0c1 \uac00\uae4c\uc774\ub85c \ub0b4\ub824\uc628\ub2e4. \uc61b\uc0ac\ub78c\ub3c4 \uc790\uc2e0\uc758 \ubab8 \uac00\uae4c\uc774\uc5d0 \uae30\ubd84 \uc88b\uc740 \ubb34\uc5c7\uc744 \ub450\uace0 \uc2f6\uc5c8\ub358 \ubaa8\uc591\uc774\ub2e4."}, {"id": "steam-engine-mine-and-factory", "title": "\uc99d\uae30\uae30\uad00 \u2014 \uad11\uc0b0\uc758 \ubb3c\uc774 \uacf5\uc7a5\uc758 \ud798\uc73c\ub85c \uc774\uc5b4\uc9c0\uae30\uae4c\uc9c0", "summary": "\uad11\uc0b0\uc758 \ubc30\uc218\uc5d0\uc11c \uacf5\uc7a5\uacfc \uc6b4\uc1a1\uc73c\ub85c \uc774\uc5b4\uc9c4 \uc99d\uae30\uae30\uad00\uc758 \ud65c\uc6a9\uc744 \ud1b5\ud574 \uc0b0\uc5c5\ud654\uc758 \uae30\uc220\uacfc \ub178\ub3d9\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\uc774\ub3d9\uacfc \uc6b4\uc1a1", "categories": ["everyday-inventions"], "url": "stories/steam-engine-mine-and-factory/index.html", "image": "../media/steam-engine-mine-and-factory.png", "alt": "\ucd08\uae30 \uc0b0\uc5c5\ud654 \uc2dc\ub300 \uc99d\uae30\uae30\uad00 \uc791\uc5c5\uc7a5\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc0c1\uc0c1 \uc7a5\uba74", "text": "\uc99d\uae30\uae30\uad00 \u2014 \uad11\uc0b0\uc758 \ubb3c\uc774 \uacf5\uc7a5\uc758 \ud798\uc73c\ub85c \uc774\uc5b4\uc9c0\uae30\uae4c\uc9c0 \uae30\uacc4\uc758 \uac1c\uc120\uacfc \uc77c\ud558\ub294 \uc7a5\uc18c\uac00 \ubc14\ub010 \uc5ed\uc0ac \uad11\uc0b0\uc758 \ubc30\uc218\uc5d0\uc11c \uacf5\uc7a5\uacfc \uc6b4\uc1a1\uc73c\ub85c \uc774\uc5b4\uc9c4 \uc99d\uae30\uae30\uad00\uc758 \ud65c\uc6a9\uc744 \ud1b5\ud574 \uc0b0\uc5c5\ud654\uc758 \uae30\uc220\uacfc \ub178\ub3d9\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc774\ub3d9\uacfc \uc6b4\uc1a1 \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \uad11\uc0b0\uc758 \ubb3c\uc744 \ud37c\ub0b4\ub294 \uc77c\uacfc \uacf5\uc7a5\uc5d0\uc11c \uae30\uacc4\ub97c \uc6c0\uc9c1\uc774\ub294 \uc77c\uc740 \ub2ec\ub77c \ubcf4\uc778\ub2e4. \uadf8\ub7ec\ub098 \uc99d\uae30\ub97c \uc774\uc6a9\ud558\ub294 \uc7a5\uce58\uc758 \uc5ed\uc0ac\ub294 \uc774 \ub450 \uc7a5\uc18c\ub97c \uc774\uc5b4 \uc900\ub2e4. \uc9c0\ud558\uc758 \ubb3c\uc744 \ub2e4\ub8e8\ub358 \ud544\uc694\uac00 \ub354 \ub113\uc740 \uc0b0\uc5c5\uc758 \ud798\uc73c\ub85c \ubc14\ub00c\ub294 \uacfc\uc815\uc774 \uc788\uc5c8\ub2e4. \uc81c\uc784\uc2a4 \uc640\ud2b8\uc758 \uc774\ub984\uc740 \uc720\uba85\ud558\uc9c0\ub9cc \uadf8\uac00 \uc99d\uae30\uae30\uad00\uc758 \ubaa8\ub4e0 \uac83\uc744 \ucc98\uc74c \ub9cc\ub4e0 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc55e\uc120 \uc7a5\uce58\uc640 \ud604\uc7a5\uc758 \ubb38\uc81c, \uae30\uacc4\ub97c \ub9cc\ub4e4\uace0 \uc0ac\uc6a9\ud560 \uc0ac\ub78c\uc774 \uc788\uc5c8\ub2e4. \ubc1c\uba85\uac00 \ud55c \uba85\uc758 \uc601\uac10\ubcf4\ub2e4 \uae34 \uae38\uc744 \ub530\ub77c\uac00\uba74 \uc99d\uae30\uae30\uad00\uc774 \uc65c \uc0dd\ud65c\uc758 \uacf5\uac04\uae4c\uc9c0 \ubc14\uafb8\uc5c8\ub294\uc9c0 \ubcf4\uc778\ub2e4. \uad50\uc7ac\ub294 17\uc138\uae30 \ub9d0 \ud1a0\uba38\uc2a4 \uc138\uc774\ubc84\ub9ac\uc758 \uc7a5\uce58\uac00 \uad11\uc0b0\uc758 \ubb3c\uc744 \ud37c\ub0b4\ub294 \uc77c\uacfc \uc0b0\uc5c5\uc6a9 \ubb3c\uc758 \uacf5\uae09\uc5d0 \uc0ac\uc6a9\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uad11\uc0b0\uc744 \ub354 \uae4a\uc774 \uc774\uc6a9\ud558\ub824\uba74 \uadf8 \uc548\uc5d0 \ubaa8\uc774\ub294 \ubb3c\uc740 \uc2e4\uc81c \uc7a5\uc560\uc600\ub2e4. \uc5d0\ub108\uc9c0\uc758 \uc5ed\uc0ac\ub294 \uc774\ub7f0 \uad6c\uccb4\uc801\uc778 \ud604\uc7a5\uc758 \ud544\uc694\uc5d0\uc11c \ucd9c\ubc1c\ud558\uae30\ub3c4 \ud55c\ub2e4. \ucc98\uc74c\ubd80\ud130 \ubaa8\ub4e0 \uae30\uacc4\ub97c \ub3cc\ub9b4 \uc218 \uc788\ub294 \uc644\uc131\ub41c \ubc94\uc6a9 \uc7a5\uce58\uac00 \uc900\ube44\ub418\uc5b4 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc99d\uae30\ub97c \uc774\uc6a9\ud558\ub294 \uc5ec\ub7ec \ud615\ud0dc\uc640 \uac1c\uc120\uc774 \uc774\uc5b4\uc84c\ub2e4. \ubb34\uc5c7\uc744 \ud560 \uc218 \uc788\uc5c8\ub294\uc9c0\ubfd0 \uc544\ub2c8\ub77c \uc5b4\ub5a4 \ud55c\uacc4 \ub54c\ubb38\uc5d0 \ub2e4\ub978 \ubc29\ubc95\uc774 \ud544\uc694\ud588\ub294\uc9c0\ub97c \ud568\uaed8 \uc77d\uc5b4\uc57c \uae30\uc220\uc758 \ubcc0\ud654\uac00 \ubcf4\uc778\ub2e4. \ubb3c\uc744 \uac00\uc5f4\ud574 \uc5bb\uc740 \uc99d\uae30\uc758 \uc131\uc9c8\uc744 \uc774\uc6a9\ud558\uba74 \uae30\uacc4\uc801 \uc6b4\ub3d9\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc99d\uae30\uc758 \ud33d\ucc3d\uacfc \ud53c\uc2a4\ud1a4\uc758 \uc6b4\ub3d9\uc744 \ud604\ub300\uc758 \uae30\ubcf8 \uc791\ub3d9 \uc124\uba85\uc73c\ub85c \uc81c\uc2dc\ud55c\ub2e4. \ub2e4\ub9cc \uc5ed\uc0ac \uc18d \ubaa8\ub4e0 \uc99d\uae30 \uc7a5\uce58\uac00 \ucc98\uc74c\ubd80\ud130 \ub611\uac19\uc740 \uad6c\uc870\ub97c \uac00\uc84c\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c\ub294 \uac01 \ubd80\ud488\uc758 \uc124\uacc4\ub97c \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc5f4\uc5d0\uc11c \uae30\uacc4\uc758 \uc6c0\uc9c1\uc784\uc744 \uc5bb\ub294 \uae38\uc774 \uc0dd\uacbc\ub2e4\ub294 \uc810\uc5d0 \uc8fc\ubaa9\ud558\uc790. \uc5b4\ub5a4 \uc5f0\ub8cc\ub97c \ub9c8\ub828\ud558\uace0 \uc5b4\ub514\uc5d0 \uc7a5\uce58\ub97c \uc124\uce58\ud560\uc9c0\uc5d0 \ub530\ub77c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \uc7a5\uc18c\uc640 \uc791\uc5c5\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uae30\uacc4\ub294 \ubc1c\uba85\ub41c \ub4a4\uc5d0\ub3c4 \ud604\uc7a5\uc758 \uc870\uac74\uacfc \uacc4\uc18d \uad00\uacc4\ub97c \ub9fa\uc5c8\ub2e4. 18\uc138\uae30\uc5d0\ub294 \uc99d\uae30\uae30\uad00\uc744 \ub354 \uc720\uc6a9\ud558\uac8c \ub9cc\ub4e4\uae30 \uc704\ud55c \uac1c\uc120\uc774 \uc774\uc5b4\uc84c\ub2e4. \uad50\uc7ac\ub294 1776\ub144 \ubb34\ub835 \uc601\uad6d \uacf5\uc7a5\ub4e4\uc774 \uc640\ud2b8\uac00 \uac1c\uc120\ud55c \uae30\uad00\uc73c\ub85c \uc77c\ubd80 \uc791\uc5c5\uc744 \uc6c0\uc9c1\uc774\uace0 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc0c8 \uc7a5\uce58\uc758 \uac00\uce58\ub294 \uc774\ub984\ub9cc\uc774 \uc544\ub2c8\ub77c \uc2e4\uc81c \uc791\uc5c5\uc5d0\uc11c \uc5b4\ub5a4 \ub3c4\uc6c0\uc744 \uc8fc\ub294\uc9c0\uc640 \uc5f0\uacb0\ub418\uc5c8\ub2e4. \uac1c\uc120\ud55c\ub2e4\ub294 \uac83\uc740 \uc55e\uc120 \uc0ac\ub78c\uc758 \uc77c\uc744 \uc9c0\uc6b0\ub294 \uac83\uacfc \ub2e4\ub974\ub2e4. \uc774\ubbf8 \uc874\uc7ac\ud558\ub358 \uae30\uc220\uc758 \ubb38\uc81c\ub97c \ub2e4\uc2dc \uc0b4\ud53c\uace0 \ub2e4\ub978 \uad6c\uc870\uc640 \uc81c\uc791 \ubc29\uc2dd\uc73c\ub85c \ud480\uc5b4 \uac00\ub294 \uc77c\uc774\uc5c8\ub2e4. \uc640\ud2b8\uc758 \uacf5\ub85c\ub97c \uc774\ud574\ud558\ub294 \ub370\ub3c4 \ucc98\uc74c\uc774\ub77c\ub294 \ub2e8\uc5b4 \ud558\ub098\ubcf4\ub2e4 \uc5b4\ub5a4 \ubcc0\ud654\uac00 \uc4f0\uc784\uc744 \ub113\ud614\ub294\uc9c0\ub77c\ub294 \uc9c8\ubb38\uc774 \ub354 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uad50\uc7ac\ub294 \uc0b0\uc5c5\ud654 \uc774\uc804\uacfc \uadf8 \uacfc\uc815\uc5d0\uc11c \ub18d\ucd0c \uac00\uc815\uc774 \uc6d0\ub8cc\ub97c \ubc1b\uc544 \uc2e4\uacfc \ucc9c \uac19\uc740 \ubb3c\uac74\uc744 \ub9cc\ub4e4\ub358 \uac00\ub0b4 \ub178\ub3d9\uc744 \uc124\uba85\ud55c\ub2e4. \uc2dc\uac04\uc774 \ud750\ub974\uba70 \uc0ac\uc5c5\uac00\ub4e4\uc740 \ub178\ub3d9\uc790\ub97c \ud55c\uacf3\uc5d0 \ubaa8\uc73c\uace0 \uae30\uacc4\uc640 \uad00\ub9ac\uc790\ub97c \ud568\uaed8 \ub450\ub294 \uacf5\uc7a5 \ubc29\uc2dd\uc744 \ud655\ub300\ud588\ub2e4. \uacf5\uc7a5\uc5d0 \uc0ac\ub78c\uc774 \ubaa8\uc774\ub294 \ubcc0\ud654\uc640 \uc99d\uae30\uae30\uad00\uc758 \ubcf4\uae09\uc740 \uc11c\ub85c \uc5f0\uacb0\ub418\uc9c0\ub9cc \uac19\uc740 \uc0ac\uac74\uc740 \uc544\ub2c8\ub2e4. \uac10\ub3c5\uacfc \uc0dd\uc0b0 \uc870\uc9c1, \uc790\uae08\uacfc \uc2dc\uc7a5\ub3c4 \uc911\uc694\ud588\ub2e4. \uae30\uacc4 \ud558\ub098\uac00 \ubaa8\ub4e0 \uacf5\uc7a5\uc744 \uc790\ub3d9\uc73c\ub85c \ub9cc\ub4e0 \uac83\ucc98\ub7fc \uc124\uba85\ud558\uae30\ubcf4\ub2e4, \ub2e4\ub978 \ubcc0\ud654\ub4e4\uc774 \ub9cc\ub098 \uc0c8\ub85c\uc6b4 \uc791\uc5c5\uc7a5\uc744 \ub9cc\ub4e4\uc5c8\ub2e4\uace0 \ubcf4\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \uc99d\uae30\uc758 \ud65c\uc6a9\uc740 \uacf5\uc7a5\uc5d0\ub9cc \uba38\ubb3c\uc9c0 \uc54a\uc558\ub2e4. \ubc30\uc640 \uae30\uad00\ucc28\uc5d0\ub3c4 \uc4f0\uc774\uba74\uc11c \uc6d0\ub8cc\uc640 \uc644\uc131\ud488\uc744 \uc774\ub3d9\uc2dc\ud0a4\ub294 \ubc29\uc2dd\uc5d0 \uc601\ud5a5\uc744 \uc8fc\uc5c8\ub2e4. \uad50\uc7ac\ub294 19\uc138\uae30 \ucd08 \uc99d\uae30\uc120\uacfc \ucca0\ub3c4 \uc6b4\uc1a1\uc774 \ubc1c\uc804\ud55c \uacfc\uc815\uc744 \ud568\uaed8 \uc18c\uac1c\ud55c\ub2e4. \uc0dd\uc0b0\uacfc \uc6b4\uc1a1\uc774 \uc11c\ub85c\uc758 \uc870\uac74\uc744 \ubc14\uafb8\ub294 \ud750\ub984\uc774\uc5c8\ub2e4. \ub354 \ub9ce\uc740 \ubb3c\uac74\uc744 \ub9cc\ub4e4 \uc218 \uc788\uc5b4\ub3c4 \ud544\uc694\ud55c \uacf3\uc5d0 \ubcf4\ub0bc \uae38\uc774 \uc5c6\uc73c\uba74 \uc2dc\uc7a5\uc740 \uc81c\ud55c\ub41c\ub2e4. \ubc18\ub300\ub85c \uc6b4\uc1a1\uc774 \ub2ec\ub77c\uc9c0\uba74 \uc0c8\ub85c\uc6b4 \uc0dd\uc0b0\uacfc \uc18c\ube44\uc758 \uc5f0\uacb0\uc774 \uac00\ub2a5\ud574\uc9c4\ub2e4. \uc99d\uae30\uc758 \uc5ed\uc0ac\ub294 \uc6c0\uc9c1\uc774\ub294 \uae30\uacc4\uc758 \uc5ed\uc0ac\uc774\uba74\uc11c \uacf5\uc7a5\uacfc \ud56d\uad6c, \ub3c4\uc2dc \uc0ac\uc774\uc758 \uad00\uacc4\uac00 \ubc14\ub00c\ub294 \uc5ed\uc0ac\uc774\uae30\ub3c4 \ud588\ub2e4. \uacf5\uc7a5\uc758 \uc131\uc7a5\uc740 \ub178\ub3d9\uc790\uc758 \ud558\ub8e8\ub3c4 \ubc14\uafb8\uc5c8\ub2e4. \uad50\uc7ac\ub294 \uae30\uacc4\ud654 \uc18d\uc5d0\uc11c \uc2fc \uc0c1\ud488\uc774 \ub298\uc5b4\ub098\ub294 \ud55c\ud3b8 \uc7a5\uc2dc\uac04 \ub178\ub3d9\uacfc \uc704\ud5d8\ud55c \uc870\uac74, \uc791\uc5c5\uc5d0 \ub300\ud55c \ud1b5\uc81c\uc758 \uc0c1\uc2e4\ub3c4 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubb3c\uac74\uc744 \ub354 \ub9ce\uc774 \ub9cc\ub4dc\ub294 \ub2a5\ub825\uacfc \uc77c\ud558\ub294 \uc0ac\ub78c\uc758 \uc0dd\ud65c\uc740 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc88b\uc544\uc9c0\uc9c0\ub9cc\uc740 \uc54a\uc558\ub2e4. \uc2a4\uc2a4\ub85c \uc791\uc5c5 \uc2dc\uac04\uacfc \ubc29\uc2dd\uc744 \uc815\ud558\ub358 \uc0ac\ub78c\uc5d0\uac8c \uacf5\uc7a5\uc758 \uaddc\uce59\uc740 \uc0c8\ub85c\uc6b4 \uc870\uac74\uc774\uc5c8\ub2e4. \uae30\uc220\uc758 \uc774\uc775\uacfc \ubd80\ub2f4\uc774 \ub204\uad6c\uc5d0\uac8c \ub3cc\uc544\uac00\ub294\uc9c0 \ubb3c\uc5b4\uc57c \ud558\ub294 \uc774\uc720\ub2e4. \uc99d\uae30\uae30\uad00\uc758 \uc131\ub2a5\uc744 \uce6d\ucc2c\ud558\ub294 \uc77c\uacfc \uadf8 \ud798\uc73c\ub85c \uc6c0\uc9c1\uc778 \uc791\uc5c5\uc7a5\uc758 \uad00\uacc4\ub97c \uc0b4\ud53c\ub294 \uc77c\uc740 \ud568\uaed8 \ud560 \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc0b0\uc5c5\ud654\ub85c \uc219\ub828\uacfc \uc9c0\uc704\ub97c \uc704\ud611\ubc1b\uc558\ub2e4\uace0 \ub290\ub080 \ub178\ub3d9\uc790\ub4e4\uc758 \uc800\ud56d\ub3c4 \ub2e4\ub8ec\ub2e4. \uae30\uacc4\ub97c \ubd80\uc218\ub294 \ud589\ub3d9\uc744 \ub2e8\uc21c\ud788 \uc0c8\uac83\uc744 \uc2eb\uc5b4\ud558\ub294 \uac10\uc815\uc73c\ub85c\ub9cc \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uc5b4\ub5a4 \uae30\uc220\uc744 \ub204\uac00 \uc18c\uc720\ud558\uace0 \uc5b4\ub5a4 \uc870\uac74\uc73c\ub85c \uc77c\ud558\uac8c \ud588\ub294\uc9c0\uac00 \ud568\uaed8 \ubb38\uc81c\uc600\ub2e4. \ubaa8\ub4e0 \ub178\ub3d9\uc790\uc640 \ubaa8\ub4e0 \uc0b0\uc5c5\uc758 \ubc18\uc751\uc774 \uac19\uc558\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uae30\uacc4\uac00 \ub354 \uc798 \uc791\ub3d9\ud55c\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \uc0ac\ud68c\uc801 \ud569\uc758\uac00 \uc800\uc808\ub85c \ub9cc\ub4e4\uc5b4\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uae30\uc220\uc774 \uc2e4\uc81c \uc0dd\ud65c\uc5d0 \ub4e4\uc5b4\uac08 \ub54c\ub294 \uadf8\uac83\uc744 \ub458\ub7ec\uc2fc \uad8c\ud55c\uacfc \ubaab\uc758 \ubb38\uc81c\uac00 \ub0a8\ub294\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 18\uc138\uae30 \ub9d0 \uc791\uc5c5\uc7a5\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc0c1\uc0c1 \uc18d \uc7a5\uba74\uc774\ub2e4. \uc640\ud2b8\uc758 \ud2b9\uc815 \uae30\uad00\uc774\ub098 \uc2e4\uc81c \uacf5\uc7a5 \uad6c\uc870\ub97c \uc815\ud655\ud558\uac8c \uc7ac\ud604\ud55c \uc124\uacc4 \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uae30\uacc4\ub97c \ub9cc\ub4e4\uace0 \uc0b4\ud53c\ub294 \uc0ac\ub78c\uc758 \uc791\uc5c5\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc774\ubbf8\uc9c0\ub2e4. \uc99d\uae30\uae30\uad00\uc744 \uae30\uc5b5\ud560 \ub54c\ub294 \ub3cc\uc544\uac00\ub294 \ubc14\ud034 \uc606\uc5d0 \uad11\uc0b0\uacfc \uc5f0\ub8cc, \uacf5\uc7a5\uacfc \ub178\ub3d9\uc790, \ubb3c\uac74\uc774 \uc774\ub3d9\ud558\ub294 \uae38\ub3c4 \ub193\uc544 \ubcf4\uc790. \ud070 \uae30\uc220\uc758 \ubcc0\ud654\ub294 \uc791\uc740 \ubb38\uc81c\ub97c \ud480\ub824\ub294 \uc2dc\ub3c4\uc5d0\uc11c \uc2dc\uc791\ud574 \uc5ec\ub7ec \ud604\uc7a5\uc758 \uc0b6\uacfc \ub9cc\ub09c\ub2e4. \uadf8 \uae38\uc744 \ub530\ub77c\uac08 \ub54c \uc99d\uae30\ub294 \uad50\uacfc\uc11c\uc758 \ubc1c\uba85\ud488 \uc774\ub984\uc744 \ub118\uc5b4 \ud55c \uc2dc\ub300\ub97c \uc6c0\uc9c1\uc778 \ud798\uc73c\ub85c \ubcf4\uc778\ub2e4."}, {"id": "three-sisters-garden", "title": "\uc625\uc218\uc218\uc640 \ucf69, \ud638\ubc15\uc740 \uc65c \uc138 \uc790\ub9e4\uc77c\uae4c", "summary": "\ud55c \ubc2d\uc5d0\uc11c \ud568\uaed8 \uc790\ub77c\ub294 \uc791\ubb3c\ub4e4\uc774 \uc11c\ub85c \ub3d5\ub294 \ubc29\uc2dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\uc2dd\ud0c1\uacfc \uc2dd\ud488 \ubcf4\uc874", "categories": ["everyday-inventions"], "url": "stories/three-sisters-garden/index.html", "image": "../media/three-sisters-garden.jpg", "alt": "\uad50\uc7ac\uac00 \uc138 \uc790\ub9e4 \uc7ac\ubc30\uc758 \uc218\ud655 \uc608\ub85c \uc81c\uc2dc\ud55c Sterling College \uc0ac\uc9c4. \uc5ec\ub7ec \uc0ac\ub78c\ub4e4\uc774 \uc625\uc218\uc218\uc640 \ub2e4\uc591\ud55c \uc218\ud655\ubb3c\uc744 \uc0b4\ud3b4\ubcf4\uace0 \uc788\uc2b5\ub2c8\ub2e4.", "text": "\uc625\uc218\uc218\uc640 \ucf69, \ud638\ubc15\uc740 \uc65c \uc138 \uc790\ub9e4\uc77c\uae4c \ubd81\ubbf8 \ubc2d\uc5d0\uc11c \ub9cc\ub098\ub294 \uc11c\ub85c \ub2e4\ub978 \uc138 \uac00\uc9c0 \uc5ed\ud560 \ud55c \ubc2d\uc5d0\uc11c \ud568\uaed8 \uc790\ub77c\ub294 \uc791\ubb3c\ub4e4\uc774 \uc11c\ub85c \ub3d5\ub294 \ubc29\uc2dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc2dd\ud0c1\uacfc \uc2dd\ud488 \ubcf4\uc874 \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \uc625\uc218\uc218\uc640 \ucf69, \ud638\ubc15\uc744 \ud55c\uc790\ub9ac\uc5d0 \ub193\uc73c\uba74 \uc7a5\ubcf4\uae30 \ubaa9\ub85d\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uadf8\ub7f0\ub370 \ubd81\ubbf8\uc758 \uc5ec\ub7ec \uc6d0\uc8fc\ubbfc \uc7ac\ubc30 \uc804\ud1b5\uc5d0\uc11c\ub294 \uc774 \uc870\ud569\uc744 \uc138 \uc790\ub9e4\ub77c\uace0 \ubd80\ub978\ub2e4. \ud568\uaed8 \uba39\ub294 \uc74c\uc2dd\uc77c \ubfd0 \uc544\ub2c8\ub77c \ud568\uaed8 \uc790\ub77c\ub3c4\ub85d \ub450\ub294 \uc791\ubb3c\ub4e4\uc774\ub2e4. OpenStax \uad50\uc7ac\ub294 \uadf8\uc911 \ud558\uc6b0\ub370\ub178\uc1fc\ub2c8\uc758 \uc0ac\ub840\ub97c \uc124\uba85\ud55c\ub2e4. \uc9c0\uae08\uc758 \ub274\uc695\uc8fc \ubd81\ubd80 \uc9c0\uc5ed\uacfc \uc774\uc5b4\uc9c0\ub294 \uc774 \uacf5\ub3d9\uccb4\ub294 \uc625\uc218\uc218\uc640 \ucf69, \ud638\ubc15\uc744 \uc791\uc740 \ub454\ub355\uc5d0\uc11c \ud568\uaed8 \uae38\ub800\ub2e4. \ube60\ub974\uac8c \uc790\ub77c\ub294 \uc625\uc218\uc218\ub294 \ub369\uad74\ucf69\uc774 \ud0c0\uace0 \uc62c\ub77c\uac08 \uc9c0\uc9c0\ub300\uac00 \ub41c\ub2e4. \ubc2d\uc5d0 \ub530\ub85c \uae30\ub465\ub9cc \uc138\uc6b0\ub294 \ub300\uc2e0 \ub2e4\ub978 \uc791\ubb3c\uc758 \uc904\uae30\uac00 \uadf8 \uc790\ub9ac\ub97c \ub9e1\ub294 \uac83\uc774\ub2e4. \ubc18\ub300\ub85c \ucf69\uc740 \uc138\uade0\uacfc\uc758 \uad00\uacc4\ub97c \ud1b5\ud574 \ud1a0\uc591\uc5d0 \uc9c8\uc18c\ub97c \ub354\ud558\ub294 \ub370 \ub3c4\uc6c0\uc744 \uc900\ub2e4. \uc9c8\uc18c\ub97c \ud544\uc694\ub85c \ud558\ub294 \uc8fc\ubcc0 \uc791\ubb3c\ub4e4\uacfc \uc5f0\uacb0\ub418\ub294 \uc5ed\ud560\uc774\ub2e4. \uc138 \uc790\ub9e4\ub77c\ub294 \uc774\ub984\uc744 \uc54c\uace0 \ubcf4\uba74 \ud55c \uc2dd\ubb3c\uc774 \uc790\uae30 \uc790\ub9ac\ub9cc \ucc28\uc9c0\ud558\uace0 \uc788\ub294 \uac83\uc774 \uc544\ub2d8\uc744 \ub290\ub07c\uac8c \ub41c\ub2e4. \ud638\ubc15\uc740 \ud070 \uc78e\uacfc \ub369\uad74\ub85c \ub545\uc744 \ub36e\ub294\ub2e4. \uad50\uc7ac\ub294 \uc774 \ub36e\uac1c\uac00 \uc7a1\ucd08\ub97c \uc5b5\uc81c\ud558\uace0 \ud759\uc758 \uc218\ubd84\uc744 \uc9c0\ud0a4\uba70 \uce68\uc2dd\uc744 \uc904\uc774\ub294 \ub370 \ub3c4\uc6c0\uc744 \uc900\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc625\uc218\uc218\uac00 \uc704\ub85c \uc790\ub784 \ub3d9\uc548 \uc544\ub798\ucabd\uc5d0\uc11c\ub294 \ub610 \ub2e4\ub978 \uc77c\uc774 \uc77c\uc5b4\ub098\ub294 \uc148\uc774\ub2e4. \uc5ec\uae30\uc11c \uc911\uc694\ud55c \uac83\uc740 \ubaa8\ub4e0 \uc885\ub958\ub97c \uc544\ubb34\ub807\uac8c\ub098 \uc11e\uc73c\uba74 \ub41c\ub2e4\ub294 \ub9d0\uc774 \uc544\ub2c8\ub2e4. \ud2b9\uc815 \uc791\ubb3c\uacfc \uc7ac\ubc30 \ubc29\uc2dd\uc5d0 \uad00\ud55c \uc0ac\ub840\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc2dd\ubb3c\uc758 \uc131\uc9c8\uc744 \uc54c\uace0 \ubc30\uce58\ud574 \uc628 \uc9c0\uc2dd\uc774 \uadf8 \uc548\uc5d0 \uc788\ub2e4. \uc625\uc218\uc218\ub294 \uc704\ub85c \uc790\ub77c\uace0 \ucf69\uc740 \uae30\ub300\uc5b4 \uc624\ub974\uba70 \ud638\ubc15\uc740 \ub545 \uac00\uae4c\uc774 \ub113\uac8c \ud37c\uc9c4\ub2e4. \uc138 \uc791\ubb3c\uc758 \uc11c\ub85c \ub2e4\ub978 \ud615\ud0dc\uac00 \uac19\uc740 \ubc2d\uc5d0\uc11c \ub2e4\ub978 \uc790\ub9ac\ub97c \ub9e1\ub294\ub2e4. \uac19\uc740 \ub192\uc774\uc5d0\uc11c \ub611\uac19\uc774 \uacbd\uc7c1\ud558\ub294 \ubaa8\uc2b5\ub9cc \uc0c1\uc0c1\ud588\uc744 \ub54c\ubcf4\ub2e4 \uad00\uacc4\uac00 \uad6c\uccb4\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4. \ud63c\uc791\uc740 \ub2e8\uc21c\ud788 \uc885\ub958\ub97c \ub9ce\uc774 \uc11e\ub294\ub2e4\ub294 \ub9d0\ubcf4\ub2e4 \ubc30\uce58\uc640 \uc131\uc9c8\uc744 \ud568\uaed8 \uc0dd\uac01\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ubc2d\ub9c8\ub2e4 \uc5b4\ub5a4 \ud488\uc885\uc744 \uc5b8\uc81c \uc2ec\uace0 \uc5b4\ub290 \uac04\uaca9\uc744 \ub450\ub294\uc9c0\ub294 \ub530\ub85c \uc54c\uc544\uc57c \ud55c\ub2e4. \uad50\uc7ac\uc758 \uc0ac\ub840\ub97c \ubaa8\ub4e0 \ud658\uacbd\uc5d0\uc11c \uac19\uc740 \uacb0\uacfc\uac00 \ub098\ub294 \uc989\uc11d \uc7ac\ubc30\ubc95\uc73c\ub85c \uc0ac\uc6a9\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc11c\ub85c \ub3d5\ub294 \ud6a8\uacfc\uac00 \uc18c\uac1c\ub418\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ub204\uad6c\ub098 \uac19\uc740 \uc218\ud655\uc744 \ubcf4\uc7a5\ubc1b\ub294\ub2e4\ub294 \uc8fc\uc7a5\uc740 \ub2e4\ub974\ub2e4. \uc791\ubb3c\uc758 \uad00\uacc4\ub97c \uc544\ub294 \uc77c\uc774 \uc2e4\uc81c \uc870\uac74\uc744 \uc0b4\ud53c\ub294 \uc77c\uc744 \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc9c8\uc18c\uc640 \uad00\ub828\ub41c \uc124\uba85\uc5d0\ub294 \uc138\uade0\uacfc\uc758 \uad00\uacc4\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \uc2dd\ubb3c \ud558\ub098\uc758 \ub2a5\ub825\ucc98\ub7fc \ubcf4\uc774\ub294 \ud6a8\uacfc \ub4a4\uc5d0\ub3c4 \ub2e4\ub978 \uc0dd\ubb3c\uc758 \ud65c\ub3d9\uc774 \ud568\uaed8 \uc788\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \uc625\uc218\uc218\uc640 \ucf69, \ud638\ubc15\ub9cc\uc73c\ub85c \ubc2d\uc758 \ubaa8\ub4e0 \uad00\uacc4\uac00 \ub05d\ub098\uc9c0\ub294 \uc54a\ub294 \uc148\uc774\ub2e4. \uc791\uc740 \ubc2d\uc5d0\uc11c\ub3c4 \uc5ec\ub7ec \uc0dd\ubb3c\uacfc \ud759\uc758 \uc870\uac74\uc744 \ud568\uaed8 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc774\uac83\uc744 \ucf69\uc774 \uc989\uc2dc \uc8fc\ubcc0\uc758 \ubaa8\ub4e0 \uc791\ubb3c\uc5d0 \uc815\ud574\uc9c4 \uc591\uc758 \uc601\uc591\uc744 \ub098\ub204\uc5b4 \uc900\ub2e4\ub294 \uadf8\ub9bc\uc73c\ub85c \ub2e8\uc21c\ud654\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc7ac\ubc30\uc758 \uc2dc\uc810\uacfc \uad00\ub9ac, \ud1a0\uc591\uc5d0 \ub530\ub77c \uc2e4\uc81c \uad00\uacc4\ub97c \ud655\uc778\ud560 \ubb38\uc81c\uac00 \uc788\ub2e4. \uc5ec\uae30\uc11c\ub294 \uad50\uc7ac\uac00 \uc124\uba85\ud55c \ud070 \uc6d0\ub9ac\ub97c \ub530\ub77c \uac01 \uc791\ubb3c\uc774 \uc5b4\ub5a4 \uc774\uc810\uacfc \uc5f0\uacb0\ub418\ub294\uc9c0 \uc0b4\ud3b4\ubcf8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc131\uc9c8\uc744 \uc54c\uace0 \ud568\uaed8 \uc774\uc6a9\ud574 \uc628 \uc9c0\uc2dd\uc5d0 \uad00\uc2ec\uc744 \ub450\ub294 \uac83\uc774\ub2e4. \uad50\uc7ac\ub294 \ud558\uc6b0\ub370\ub178\uc1fc\ub2c8\uc758 \uc0ac\ub840\uc5d0\uc11c \uc138 \uc791\ubb3c\uc774 \uc11c\ub85c \ub5bc\uc5b4 \ub193\uc744 \uc218 \uc5c6\ub294 \uc874\uc7ac\ub85c \uc774\ud574\ub418\uc5c8\ub2e4\ub294 \uae30\ub85d\uc744 \uc18c\uac1c\ud55c\ub2e4. \ub18d\uc0ac\uc758 \ubb3c\ub9ac\uc801\uc778 \uc774\uc810\uacfc \uacf5\ub3d9\uccb4\uc758 \uc774\uc57c\uae30\uc640 \ubbff\uc74c\uc774 \ud568\uaed8 \uc804\ud574\uc84c\ub2e4. \uc0dd\ud0dc\uc801\uc778 \uc124\uba85\ub9cc \ub0a8\uae30\uba74 \uc0ac\ub78c\ub4e4\uc774 \uadf8 \uc791\ubb3c\ub4e4\uc744 \uc5b4\ub5a4 \uad00\uacc4\ub85c \uae30\uc5b5\ud588\ub294\uc9c0 \ub193\uce60 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \ud558\ub098\uc758 \uc804\uc2b9\uc744 \ubd81\ubbf8\uc640 \uc911\ubbf8\uc758 \ubaa8\ub4e0 \uacf5\ub3d9\uccb4\uc5d0 \ub611\uac19\uc774 \uc801\uc6a9\ud574\uc11c\ub3c4 \uc548 \ub41c\ub2e4. \uc9c0\uc5ed\uacfc \uc9d1\ub2e8\ub9c8\ub2e4 \uc7ac\ubc30\uc640 \uc774\uc57c\uae30\uac00 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uad50\uc7ac\uac00 \uc5b4\ub5a4 \uc0ac\ub840\ub97c \ub4e4\uace0 \uc788\ub294\uc9c0 \uc774\ub984\uc744 \ub0a8\uaca8 \ub450\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \uac19\uc740 \uc791\ubb3c\uc744 \uc0ac\uc6a9\ud588\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uac19\uc740 \ubb38\ud654\uc801 \uc758\ubbf8\ub97c \ubd99\uc600\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uad6c\ubd84\ud560 \uc218 \uc788\ub2e4. \ubcf8\ubb38\uc5d0 \uc2e4\ub9b0 \uc2e4\uc81c \uc0ac\uc9c4\uc740 \uad50\uc7ac\uac00 \uc18c\uac1c\ud558\ub294 \uc138 \uc790\ub9e4 \uc218\ud655\uc758 \uc608\ub2e4. \uc644\uc131\ub41c \uc791\ubb3c\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc7a5\uba74\uc774 \ubaa8\ub4e0 \uc7ac\ubc30 \uacfc\uc815\uc744 \uc9c1\uc811 \ucd2c\uc601\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ud48d\uc131\ud55c \uacb0\uacfc\ub97c \ubcf4\uace0 \uc904\uae30\uc640 \ub369\uad74\uc758 \uc704\uce58\ub97c \uc0ac\uc9c4 \uc18d\uc5d0 \ub9c8\uc74c\ub300\ub85c \uadf8\ub824 \ub123\uc9c0 \uc54a\uc73c\uba74 \uc790\ub8cc\uc758 \uc5ed\ud560\uc774 \ub354 \uc815\ud655\ud574\uc9c4\ub2e4. \ud574\uc124\uc774 \uc54c\ub824 \uc8fc\ub294 \uad6c\uc870\uc640 \ub208\uc5d0 \ubcf4\uc774\ub294 \uc218\ud655\uc744 \ub098\ub204\uc5b4 \ubcfc \uc218 \uc788\ub2e4. \uc74c\uc2dd\uc758 \uc5ed\uc0ac\ub294 \uc5b4\ub5a4 \uc7ac\ub8cc\ub97c \uba39\uc5c8\ub294\uc9c0\ubfd0 \uc544\ub2c8\ub77c \uc5b4\ub5bb\uac8c \ud568\uaed8 \uae38\ub800\ub294\uc9c0\ub3c4 \ud3ec\ud568\ud55c\ub2e4. \uc138 \uc790\ub9e4\ub77c\ub294 \uc774\ub984\uc744 \uae30\uc5b5\ud588\ub2e4\uba74 \ub2e4\uc74c\uc5d0\ub294 \uc138 \uc791\ubb3c\uc758 \ud06c\uae30\uc640 \uc790\ub77c\ub294 \ubc29\ud5a5\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uce5c\uadfc\ud55c \ubcc4\uba85 \ub4a4\uc5d0 \uad00\ucc30\uacfc \uacbd\ud5d8, \uacf5\ub3d9\uccb4\uc758 \uae30\uc5b5\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \ubc2d\uc740 \uc2dd\ubb3c\uc774 \ub098\ub780\ud788 \uc120 \uacf3\uc774\uba74\uc11c \uc11c\ub85c\uc758 \ucc28\uc774\ub97c \uc774\uc6a9\ud55c \uc9c0\uc2dd\uc774 \ub193\uc778 \uacf5\uac04\uc774\uae30\ub3c4 \ud558\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc0ac\uc9c4\uc740 \uad50\uc7ac\uac00 \uc138 \uc790\ub9e4 \uc7ac\ubc30\uc640 \uc218\ud655\uc758 \uc608\ub85c \uc81c\uc2dc\ud55c \uc2e4\uc81c \uc7a5\uba74\uc774\ub2e4. \uc0ac\uc9c4 \uc18d \uc0ac\ub78c\ub4e4\uc744 \ud2b9\uc815 \uc6d0\uc8fc\ubbfc \uacf5\ub3d9\uccb4\uc758 \uad6c\uc131\uc6d0\uc774\ub77c\uace0 \ucd94\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc0ac\uc9c4\uc758 \uc0ac\ub840\uc640 \uc124\uba85\ud558\ub294 \uc5ed\uc0ac\uc801 \uc7ac\ubc30 \uc804\ud1b5\uc740 \uad6c\ubd84\ud574 \ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \uadf8\ub798\ub3c4 \ubc2d\uc744 \ubcf4\ub294 \uc9c8\ubb38\uc740 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc904\uc744 \uc5bc\ub9c8\ub098 \uace7\uac8c \uc138\uc6e0\ub290\ub0d0\ub9cc\uc774 \uc544\ub2c8\ub77c, \uc606\uc5d0\uc11c \uc790\ub77c\ub294 \uc2dd\ubb3c\uc774 \uc5b4\ub5a4 \ub3c4\uc6c0\uc744 \uc8fc\ub290\ub0d0\ub97c \uc0b4\ud53c\ub294 \uac83\uc774\ub2e4. \uc138 \uc790\ub9e4\ub77c\ub294 \uc774\ub984\uc740 \uc2dd\ubb3c \uc0ac\uc774\uc758 \uad00\uacc4\ub97c \uae30\uc5b5\ud558\uae30 \uc88b\uc740 \uc791\uc740 \uc774\uc57c\uae30\uc774\uae30\ub3c4 \ud558\ub2e4."}, {"id": "trombone-sliding-notes", "title": "\ud2b8\ub86c\ubcf8 \uc5f0\uc8fc\uc790\ub294 \uc65c \ud314\uc744 \uae38\uac8c \ubed7\uc744\uae4c", "summary": "\uc55e\uc73c\ub85c \ub098\uac14\ub2e4 \ub3cc\uc544\uc624\ub294 \uae34 \uad00. \ud2b8\ub86c\ubcf8\uc758 \ub208\uc5d0 \ub744\ub294 \ub3d9\uc791\uc740 \uc74c\uc744 \uace0\ub974\ub294 \uc77c\uc774\uae30\ub3c4 \ud569\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\ub180\uc774\uc640 \ucde8\ubbf8", "categories": ["everyday-inventions"], "url": "stories/trombone-sliding-notes/index.html", "image": "../media/trombone-sliding-notes.jpg", "alt": "\uae08\ube5b \ud2b8\ub86c\ubcf8\uacfc \uae38\uac8c \ubed7\uc740 \uc2ac\ub77c\uc774\ub4dc\ub97c \ubcf4\uc5ec \uc8fc\ub294 AI \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ud2b8\ub86c\ubcf8 \uc5f0\uc8fc\uc790\ub294 \uc65c \ud314\uc744 \uae38\uac8c \ubed7\uc744\uae4c \uc18c\ub9ac \uc0ac\uc774\ub97c \ubbf8\ub044\ub7ec\uc9c0\ub294 \uae08\uad00\uc545\uae30 \uc55e\uc73c\ub85c \ub098\uac14\ub2e4 \ub3cc\uc544\uc624\ub294 \uae34 \uad00. \ud2b8\ub86c\ubcf8\uc758 \ub208\uc5d0 \ub744\ub294 \ub3d9\uc791\uc740 \uc74c\uc744 \uace0\ub974\ub294 \uc77c\uc774\uae30\ub3c4 \ud569\ub2c8\ub2e4. \ub180\uc774\uc640 \ucde8\ubbf8 \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \uc624\ucf00\uc2a4\ud2b8\ub77c\uc5d0\uc11c \ud2b8\ub86c\ubcf8\uc744 \ucc3e\ub294 \uc26c\uc6b4 \ubc29\ubc95\uc774 \uc788\ub2e4. \uc5f0\uc8fc\uc790\uc758 \ud314\uc774 \uc55e\ub4a4\ub85c \uae38\uac8c \uc6c0\uc9c1\uc774\ub294 \uc790\ub9ac\ub97c \ubcf4\ub294 \uac83\uc774\ub2e4. \ubc88\uca4d\uc774\ub294 \uad00 \ud55c\ucabd\uc774 \ub098\uac14\ub2e4\uac00 \ub4e4\uc5b4\uc628\ub2e4. \ucc98\uc74c \ubcf4\uba74 \uc545\uae30\ub97c \ub298\uc600\ub2e4 \uc904\uc600\ub2e4 \ud558\ub294 \ubb18\uae30 \uac19\ub2e4. \ud558\uc9c0\ub9cc \uc5f0\uc8fc\uc790\ub294 \uadf8 \uc6c0\uc9c1\uc784\uc73c\ub85c \uc74c\uc744 \uace0\ub974\uace0 \uc788\ub2e4. \ud544\ud558\ubaa8\ub2c8\uc544 \uc624\ucf00\uc2a4\ud2b8\ub77c\ub294 \ud2b8\ub86c\ubcf8\uc758 \uc2ac\ub77c\uc774\ub4dc\ub97c \uc74c\ub192\uc774\ub97c \uc120\ud0dd\ud558\ub294 \uc7a5\uce58\ub85c \uc124\uba85\ud55c\ub2e4. \ud2b8\ub86c\ubcf8\uc758 \ub208\uc5d0 \ub744\ub294 \ubd80\ubd84\uc740 \uae38\uac8c \uc811\ud600 \ub3cc\uc544\uc624\ub294 \uad00\uc774\ub2e4. \uadf8 \uad00\uc758 \uc77c\ubd80\ub97c \ubbf8\ub044\ub7ec\ub728\ub9ac\ub294 \uc2ac\ub77c\uc774\ub4dc\uac00 \uc545\uae30 \ubc14\uae65\uc73c\ub85c \uae38\uac8c \ubed7\uc5b4 \uc788\ub2e4. \uc545\uae30\ub97c \ucc98\uc74c \ubcf4\ub294 \uc0ac\ub78c\ub3c4 \uc6c0\uc9c1\uc774\ub294 \uacf3\uc744 \uc27d\uac8c \ucc3e\uc744 \uc218 \uc788\ub2e4. \ubc84\ud2bc\uc744 \uc9e7\uac8c \ub204\ub974\ub294 \ub3d9\uc791\uacfc \ub2ec\ub9ac, \uc2ac\ub77c\uc774\ub4dc\uc758 \uc774\ub3d9\uc740 \uac1d\uc11d\uc5d0\uc11c\ub3c4 \ubcf4\uc778\ub2e4. \ud314\uc774 \ud070 \ub3d9\uc791\uc744 \ud558\uc9c0\ub9cc \ubaa9\uc801\uc740 \uc12c\uc138\ud558\ub2e4. \uc5f0\uc8fc\uc790\ub294 \uc545\uae30\uc758 \uae38\uc774\ub97c \ubc14\uafb8\uba70 \ud544\uc694\ud55c \uc18c\ub9ac\ub97c \ucc3e\uc544\uac04\ub2e4. \uadf8\ub798\uc11c \ud2b8\ub86c\ubcf8\uc740 \uc18c\ub9ac\ub97c \ub4e3\ub294 \uc7ac\ubbf8\uc640 \ub3d9\uc791\uc744 \ubcf4\ub294 \uc7ac\ubbf8\uac00 \ud568\uaed8 \uc788\ub294 \uc545\uae30\ub2e4. \uc6c0\uc9c1\uc784\uc744 \ud55c \ubc88 \uc54c\uc544\ub450\uba74 \ub9ce\uc740 \uc545\uae30\uac00 \ubaa8\uc778 \uc7a5\uba74\uc5d0\uc11c\ub3c4 \ub2e4\uc2dc \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ud2b8\ub86c\ubcf8\uc740 \uc74c \uc0ac\uc774\ub97c \ubbf8\ub044\ub7ec\uc9c0\ub4ef \uc787\ub294 \uc18c\ub9ac\ub85c\ub3c4 \uc720\uba85\ud558\ub2e4. \u2018\uae00\ub9ac\uc0b0\ub3c4\u2019\ub77c\uace0 \ubd80\ub974\ub294 \ud6a8\uacfc\ub2e4. \ub2e8\uc5b4\ub97c \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc18c\ub9ac\uac00 \uc544\ub798\uc704\ub85c \ucb49 \ubbf8\ub044\ub7ec\uc9c0\ub294 \ub290\ub08c\uc744 \ub5a0\uc62c\ub9ac\uba74 \uc27d\ub2e4. \ud544\ud558\ubaa8\ub2c8\uc544\ub294 \uc774 \ud2b9\uc9d5\uc774 \ub9cc\ud654\uc758 \uc74c\uc545\uc5d0\uc11c\ub3c4 \uc624\ub7ab\ub3d9\uc548 \ud65c\uc6a9\ub418\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc6b0\uc2a4\uaf5d\uc2a4\ub7ec\uc6b4 \ub3d9\uc791\uc5d0 \ub9de\ucdb0 \uc18c\ub9ac\uac00 \ud718\uc5b4\uc9c0\ub294 \ub4ef\ud55c \uc7a5\uba74\uc744 \ub5a0\uc62c\ub9ac\uba74, \ub0af\uc120 \uc545\uae30\uac00 \uc870\uae08 \uc775\uc219\ud574\uc9c4\ub2e4. \uadf8\ub7ec\ub098 \ud2b8\ub86c\ubcf8\uc744 \uc6c3\uae34 \uc18c\ub9ac\ub9cc \ub0b4\ub294 \uc545\uae30\ub85c \uae30\uc5b5\ud558\uba74 \uc544\uc27d\ub2e4. \uac19\uc740 \uc548\ub0b4\ub294 \ud2b8\ub86c\ubcf8\uc774 \uc544\uc8fc \ubd80\ub4dc\ub7ec\uc6b4 \uc120\uc728\ub3c4 \uc5f0\uc8fc\ud560 \uc218 \uc788\ub2e4\uace0 \uac15\uc870\ud55c\ub2e4. \ud55c \uac00\uc9c0 \ud6a8\uacfc\uac00 \uc778\uc0c1\uc801\uc774\ub77c\uace0 \uadf8 \uc545\uae30\uc758 \ubaa8\ub4e0 \ud45c\uc815\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2ac\ub77c\uc774\ub4dc\ub97c \uc6c0\uc9c1\uc774\ub294 \uc77c\uc740 \ub208\uc5d0 \ubcf4\uc774\ub294 \uad00\uc758 \uae38\uc774\ub97c \ubc14\uafb8\ub294 \ud589\ub3d9\uc774\ub2e4. \uc5f0\uc8fc\uc790\ub294 \uc785\uacfc \ud638\ud761\uc744 \uc0ac\uc6a9\ud558\uba74\uc11c \uadf8 \uae38\uc774\ub3c4 \uc870\uc808\ud55c\ub2e4. \uadf8\ub798\uc11c \ud314\uc758 \uc6c0\uc9c1\uc784\ub9cc \ubcf4\uace0 \uc5f0\uc8fc \uc804\uccb4\uac00 \ub2e8\uc21c\ud55c \ubc00\uace0 \ub2f9\uae30\uae30\ub77c\uace0 \uc0dd\uac01\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud070 \ub3d9\uc791\uacfc \uc815\uad50\ud55c \uc18c\ub9ac\uc758 \uc120\ud0dd\uc774 \ud568\uaed8 \uc774\ub8e8\uc5b4\uc9c4\ub2e4. \uac1d\uc11d\uc5d0\uc11c \ubcf4\uc774\ub294 \ud589\ub3d9\uc740 \uadf8 \uac00\uc6b4\ub370 \ub208\uc5d0 \uc798 \ub744\ub294 \ubd80\ubd84\uc774\ub2e4. \uc774 \uad00\uacc4\ub97c \uc54c\uba74 \ud2b8\ub86c\ubcf8\uc744 \ucc98\uc74c \ubcf4\ub294 \uc0ac\ub78c\ub3c4 \ubb34\uc5c7\uc744 \uad00\ucc30\ud560\uc9c0 \uc54c\uac8c \ub41c\ub2e4. \uc190\uc774 \uba40\ub9ac \ub098\uac08 \ub54c\uc640 \uac00\uae4c\uc6cc\uc9c8 \ub54c \uc18c\ub9ac\uac00 \uc5b4\ub5bb\uac8c \ub2ec\ub77c\uc9c0\ub294\uc9c0 \ub4e4\uc5b4 \ubcf4\uc790. \ub2e4\ub9cc \ubaa8\ub4e0 \uc74c\ub192\uc774\ub97c \ud314\uc758 \uac70\ub9ac \ud558\ub098\ub85c \uc77c\ub300\uc77c \ub300\uc751\uc2dc\ud0a4\uac70\ub098 \uc0ac\uc9c4 \ud55c \uc7a5\uc5d0\uc11c \ud2b9\uc815 \uc74c\uc744 \uc54c\uc544\ub9de\ud788\ub824 \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc2e4\uc81c \uc5f0\uc8fc\uc5d0\ub294 \ub3d9\uc2dc\uc5d0 \uc791\uc6a9\ud558\ub294 \ub2e4\ub978 \uc870\uc808\uc774 \uc788\ub2e4. \uc2ac\ub77c\uc774\ub4dc\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc5b8\uc81c\ub098 \uc18c\ub9ac\ub97c \ubbf8\ub044\ub7ec\ub728\ub9b0\ub2e4\ub294 \uc8fc\uc7a5\uc740 \ub2e4\ub974\ub2e4. \uae00\ub9ac\uc0b0\ub3c4\ub294 \uc774 \uc545\uae30\uc758 \uc778\uc0c1\uc801\uc778 \ud6a8\uacfc\uc774\uc9c0\ub9cc \uace1 \uc804\uccb4\uac00 \uadf8 \ud6a8\uacfc\ub85c\ub9cc \uc774\ub8e8\uc5b4\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc120\uc728\uc758 \uc74c\ub4e4\uc744 \ub610\ub837\ud558\uac8c \ub098\ub204\uc5b4 \ub0b4\uac70\ub098 \uae38\uac8c \uc774\uc5b4 \ub178\ub798\ud558\ub294 \uc21c\uac04\ub3c4 \uc788\ub2e4. \ud558\ub098\uc758 \ud2b9\uc9d5\uc744 \uc54c\uc544\ubcf8 \ub4a4\uc5d0\ub294 \uadf8 \ud2b9\uc9d5\uc774 \uc4f0\uc774\uc9c0 \uc54a\ub294 \uc21c\uac04\uc744 \ub4e4\uc5b4\ubcf4\ub294 \uac83\ub3c4 \uc7ac\ubbf8\uc788\ub2e4. \ub9cc\ud654 \uc74c\uc545\uc758 \uc775\uc0b4\uc2a4\ub7ec\uc6b4 \uc18c\ub9ac\ub97c \ub5a0\uc62c\ub838\ub2e4\uba74 \ub2e4\uc74c\uc5d0\ub294 \ubd80\ub4dc\ub7ec\uc6b4 \uc120\uc728\uc744 \ucc3e\uc544\ubcf4\uc790. \uac19\uc740 \uc545\uae30\uac00 \ub2e4\ub978 \ubb38\uc7a5 \uc18d\uc5d0\uc11c \uc5b4\ub5a4 \uc5ed\ud560\uc744 \ud558\ub294\uc9c0 \ube44\uad50\ud558\ub294 \uac83\uc774\ub2e4. \uadf8\ub9bc \uc18d \uc778\ubb3c\uc758 \uac78\uc74c\uc5d0 \ub9de\ucd98 \ud6a8\uacfc\uc640 \ud569\uc8fc \uc548\uc5d0\uc11c \uae38\uac8c \ubd80\ub294 \uc74c\uc740 \uc11c\ub85c \ub2e4\ub978 \ud45c\uc815\uc744 \ub9cc\ub4e0\ub2e4. \uc545\uae30\uc758 \ub2a5\ub825\uc740 \uac00\uc7a5 \uc720\uba85\ud55c \uc18c\ub9ac \ud558\ub098\ubcf4\ub2e4 \ub113\ub2e4. \ud63c\uc790 \ud55c \uc74c\uc744 \ub0b4\ub294 \uacbd\uc6b0\uc640 \ub2e4\ub978 \uc545\uae30\ub4e4 \uc0ac\uc774\uc5d0 \ub4e4\uc5b4\uac00\ub294 \uacbd\uc6b0\uc5d0\ub294 \ub4e4\ub9ac\ub294 \uad00\uacc4\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uc74c\uc0c9\uc774 \ube44\uc2b7\ud55c \uc18c\ub9ac\ub07c\ub9ac \uacb9\uce58\uae30\ub3c4 \ud558\uace0 \ub2e4\ub978 \uc18c\ub9ac\ub97c \ubc1b\uccd0 \uc8fc\uae30\ub3c4 \ud55c\ub2e4. \ud2b9\uc815 \uc5f0\uc8fc\uc5d0\uc11c \ubb34\uc5c7\uc744 \ub9e1\ub294\uc9c0\ub294 \uc545\ubcf4\uc640 \uc2e4\uc81c \uc18c\ub9ac\ub97c \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \ub2e4\ub9cc \ub298 \uc804\uba74\uc5d0\uc11c \ud070 \uc18c\ub9ac\ub9cc \ub0b4\ub294 \uc545\uae30\ub85c \uae30\uc5b5\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud544\ud558\ubaa8\ub2c8\uc544\ub294 \ub974\ub124\uc0c1\uc2a4 \uc2dc\ub300 \uad50\ud68c \ud569\uc8fc\uc640 \uc774\uc5b4\uc9c0\ub294 \uc5ed\uc0ac\ub3c4 \uc18c\uac1c\ud55c\ub2e4. \uc9c0\uae08\uc758 \uc624\ucf00\uc2a4\ud2b8\ub77c \uc548\uc5d0\uc11c \ub9cc\ub098\ub294 \uc545\uae30\uac00 \uc5ec\ub7ec \uc0ac\uc6a9\uc758 \uc2dc\uac04\uc744 \uac70\uccd0 \uc654\ub2e4\ub294 \ub2e8\uc11c\ub2e4. \uacfc\uac70\uc758 \ubaa8\ub4e0 \ud2b8\ub86c\ubcf8\uc774 \uc624\ub298\uc758 \ubaa8\uc591\uacfc \ub611\uac19\uc558\ub2e4\uace0 \ub2e8\uc815\ud558\uae30\ubcf4\ub2e4 \uc5b4\ub5a4 \uc790\ub9ac\uc5d0\uc11c \uc5b4\ub5a4 \uc18c\ub9ac\ub85c \uc4f0\uc600\ub294\uc9c0 \ubb3b\ub294 \uc785\uad6c\ub85c \ubcfc \uc218 \uc788\ub2e4. \uc5f0\uc8fc \uc601\uc0c1\uc744 \ud55c \ubc88\uc740 \ub208\uc744 \ub5bc\uace0 \ub4e3\uace0, \ub2e4\uc74c\uc5d0\ub294 \ud314\uc758 \uc6c0\uc9c1\uc784\uc744 \ubcf4\uba70 \ub4e4\uc5b4 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc775\uc0b4\uc2a4\ub7fd\uac8c\ub9cc \ub4e4\ub9ac\ub358 \uc18c\ub9ac\uac00 \uc870\uc2ec\uc2a4\ub7fd\uac8c \uc774\uc5b4\uc9c0\ub294 \uc120\uc728\uc77c \uc218 \uc788\uace0, \ud070 \ub3d9\uc791\uc774 \ub73b\ubc16\uc5d0 \uc870\uc6a9\ud55c \uad6c\uac04\uc5d0\uc11c\ub3c4 \ud544\uc694\ud560 \uc218 \uc788\ub2e4. \ub3c4\uad6c\uc758 \uad6c\uc870\ub97c \uc870\uae08 \uc544\ub294 \uc77c\uc740 \uac10\uc0c1\uc744 \ub354 \uc5b4\ub835\uac8c \ud558\uae30\ubcf4\ub2e4 \uc8fc\uc758\ub97c \ub193\uc744 \uc790\ub9ac\ub97c \ub298\ub9b4 \uc218 \uc788\ub2e4. \uc774 \uae00\uc758 \uc0bd\ud654\ub294 \uc5f0\uc8fc\uc758 \uac1c\ub150\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc704\ud55c \uadf8\ub9bc\uc774\uba70 \uc815\ud655\ud55c \uc5f0\uc8fc \uc790\uc138\ub97c \uac00\ub974\uce58\ub294 \ub3c4\uba74\uc740 \uc544\ub2c8\ub2e4. \uc2e4\uc81c \uc190\uacfc \ud638\ud761\uc758 \uc0ac\uc6a9\uc740 \uc5f0\uc8fc\uc790\uc758 \uc2dc\uc5f0\uacfc \uad50\uc721 \uc790\ub8cc\ub85c \ud655\uc778\ud560 \uc601\uc5ed\uc774\ub2e4. \uc6b0\ub9ac\ub294 \uad00\ub78c\uc790\ub85c\uc11c \uc18c\ub9ac\uc640 \uc6c0\uc9c1\uc784\uc758 \uad00\uacc4\ub97c \ubc1c\uacac\ud558\ub294 \uac83\uc73c\ub85c\ub3c4 \ucda9\ubd84\ud558\ub2e4. \uae38\uac8c \ubed7\ub294 \ud314\uc774 \uc5b4\ub5a4 \uc74c\uc545\uc801 \ubb38\uc7a5\uc744 \ub9cc\ub4dc\ub294\uc9c0 \uc0c8\ub86d\uac8c \ub4e4\uc744 \uc218 \uc788\ub2e4. \ud2b8\ub86c\ubcf8\uc740 \uc624\ucf00\uc2a4\ud2b8\ub77c\uac00 \uc6c5\uc7a5\ud574\uc9c0\ub294 \uc21c\uac04\uc5d0 \ud798\uc744 \ubcf4\ud0dc\uae30\ub3c4 \ud55c\ub2e4. \uadf8\ub798\uc11c \ud06c\uace0 \uac15\ud55c \uc18c\ub9ac\ubd80\ud130 \uc5f0\uc0c1\ud558\uae30 \uc27d\ub2e4. \ud558\uc9c0\ub9cc \ud544\ud558\ubaa8\ub2c8\uc544\ub294 \ub974\ub124\uc0c1\uc2a4 \uc2dc\ub300\uc5d0 \uad50\ud68c\uc5d0\uc11c \ud2b8\ub86c\ubcf8 \ud569\uc8fc\ub85c \uc5f0\uc8fc\ud558\ub358 \uc12c\uc138\ud55c \uc74c\uc545\ub3c4 \uc18c\uac1c\ud55c\ub2e4. \ubb34\ub300\uc5d0\uc11c \ubcf4\uc774\ub294 \uae34 \uad00\uacfc \ud798\ucc2c \uc790\uc138\ub9cc\uc73c\ub85c \uc18c\ub9ac\uc758 \uc131\uaca9\uc744 \ud558\ub098\ub85c \uc815\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \ubd80\ub4dc\ub7fd\uac8c \uc774\uc5b4\uc9c0\ub294 \uc120\uc728\uc744 \ub4e4\uc744 \ub54c\uc5d0\ub3c4 \uac19\uc740 \uc2ac\ub77c\uc774\ub4dc\uac00 \uc6c0\uc9c1\uc778\ub2e4. \ub2e4\uc74c\uc5d0 \uacf5\uc5f0 \uc601\uc0c1\uc744 \ubcfc \ub54c\ub294 \ud314\uc774 \uc55e\uc73c\ub85c \ub098\uc624\ub294 \uc21c\uac04\uacfc \uadf8\ub54c\uc758 \uc18c\ub9ac\ub97c \ud568\uaed8 \ub530\ub77c\uac00 \ubcf4\uc790. \ud07c\uc9c1\ud55c \ub3d9\uc791 \uc18d\uc5d0\uc11c \uc74c\uc744 \uace0\ub974\ub294 \uc77c\uc774 \uc0dd\uac01\ubcf4\ub2e4 \uc870\uc6a9\ud558\uace0 \uc138\ubc00\ud558\uac8c \uc774\ub8e8\uc5b4\uc9c0\uace0 \uc788\ub2e4."}, {"id": "zongzi-leaf-parcel", "title": "\uc911\uad6d\uc758 \uba85\uc808 \uc74c\uc2dd\uc5d0\ub294 \uc78e\uc0ac\uadc0 \ud3ec\uc7a5\uc774 \uc788\ub2e4", "summary": "\uc300 \uc74c\uc2dd \ud558\ub098\uc5d0 \uc7ac\ub8cc\uc640 \ud3ec\uc7a5, \uba85\uc808\uc758 \uc2dc\uac04\uc774 \ud568\uaed8 \ub193\uc785\ub2c8\ub2e4.", "category": "everyday-inventions", "category_title": "\uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220", "subcategory": "\uc2dd\ud0c1\uacfc \uc2dd\ud488 \ubcf4\uc874", "categories": ["everyday-inventions"], "url": "stories/zongzi-leaf-parcel/index.html", "image": "../media/zongzi-leaf-parcel.jpg", "alt": "\uc811\uc2dc\uc5d0 \ub193\uc778 \uc78e\uc0ac\uadc0\ub85c \uc2f8\uace0 \uc2e4\ub85c \ubb36\uc740 \ucad1\ucbd4\uc758 \uc2e4\uc81c \uc0ac\uc9c4.", "text": "\uc911\uad6d\uc758 \uba85\uc808 \uc74c\uc2dd\uc5d0\ub294 \uc78e\uc0ac\uadc0 \ud3ec\uc7a5\uc774 \uc788\ub2e4 \uc2e4\ub85c \ubb36\uc740 \ucad1\ucbd4\ub97c \uc5f4\uae30 \uc804\uc5d0 \ubcf4\uae30 \uc300 \uc74c\uc2dd \ud558\ub098\uc5d0 \uc7ac\ub8cc\uc640 \ud3ec\uc7a5, \uba85\uc808\uc758 \uc2dc\uac04\uc774 \ud568\uaed8 \ub193\uc785\ub2c8\ub2e4. \uc2dd\ud0c1\uacfc \uc2dd\ud488 \ubcf4\uc874 \uc0dd\ud65c\uc744 \ubc14\uafbc \ubb3c\uac74\uacfc \uae30\uc220 \uc811\uc2dc \uc704\uc5d0 \uc791\uc740 \uafb8\ub7ec\ubbf8\ub4e4\uc774 \ub193\uc5ec \uc788\ub2e4. \uc9d9\uc740 \uc78e\uc73c\ub85c \uc2f8\uace0 \uc2e4\uc744 \ub458\ub7ec \ubb36\uc5b4\uc11c \uc74c\uc2dd\uc774\ub77c\uae30\ubcf4\ub2e4 \uba3c\uc800 \ud480\uc5b4\uc57c \ud560 \uc120\ubb3c\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uc911\uad6d\uc758 \ucad1\ucbd4\ub2e4. OpenStax\uc758 \uc778\ub958\ud559 \uad50\uc7ac\ub294 \uc0ac\uc9c4 \uc18d \uc74c\uc2dd\uc744 \ub300\ub098\ubb34 \uc78e\uc5d0 \uc2fc \ucc39\uc300 \uc74c\uc2dd\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \uba39\uae30 \uc804\ubd80\ud130 \ubaa8\uc591\uacfc \ud3ec\uc7a5\uc774 \ub208\uc5d0 \ub4e4\uc5b4\uc624\ub294 \uba85\uc808 \uc74c\uc2dd\uc774\ub2e4. \uad50\uc7ac\ub294 \ucad1\ucbd4\ub97c \uc5ec\ub7ec \uc885\ub958\uc758 \uc18d\uc7ac\ub8cc\ub97c \ub123\ub294 \ucc39\uc300 \uc74c\uc2dd\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \uac89\uc758 \uc78e\uacfc \uc2e4\uc774 \ubcf4\uc778\ub2e4\uace0 \uc548\uc758 \ub9db\uae4c\uc9c0 \ubaa8\ub450 \uc54c \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac19\uc740 \uc774\ub984 \uc548\uc5d0\ub3c4 \ub2e4\ub978 \uc18d\uc774 \uc788\uc744 \uc218 \uc788\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uba3c\uc800 \uc78e\uc774 \uc811\ud78c \uc120\uacfc \ubb36\uc778 \uc2e4\uc744 \ub530\ub77c \ubcf4\uc790. \ud3ec\uc7a5\uc9c0\ucc98\ub7fc \ubcf4\uc774\ub294 \ubd80\ubd84\ub3c4 \uc74c\uc2dd\uc758 \ubaa8\uc2b5\uc744 \uc774\ub8e8\uace0 \uc788\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc78e\uc774 \uc5b4\ub5a4 \ud654\ud559\uc801 \ud6a8\uacfc\ub97c \ub0b8\ub2e4\uac70\ub098 \ubaa8\ub450 \uac19\uc740 \ubaa8\uc591\uc73c\ub85c \uc2f8\uc57c \ud55c\ub2e4\uace0 \uc124\uba85\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ucad1\ucbd4\ub294 \uc911\uad6d\uc758 \ub2e8\uc624, \uace7 \ub450\uc548\uc6b0\uc640 \uc774\uc5b4\uc9c0\ub294 \ub300\ud45c \uc74c\uc2dd\uc73c\ub85c \uc18c\uac1c\ub41c\ub2e4. \uad50\uc7ac\ub294 \uc774 \uba85\uc808\uc744 \uc911\uad6d \uc74c\ub825\uc758 \ub2e4\uc12f\uc9f8 \ub2ec \ub2e4\uc12f\uc9f8 \ub0a0\uc5d0 \uc9c0\ub0b4\ub294 \ud589\uc0ac\ub85c \uc124\uba85\ud55c\ub2e4. \uc775\uc219\ud55c \ub2ec\ub825 \ub0a0\uc9dc\uc640 \ud2b9\uc815 \uc74c\uc2dd\uc774 \ub9cc\ub098\uba74 \ub9db\uc744 \uae30\uc5b5\ud558\ub294 \ubc29\uc2dd\ub3c4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc544\ubb34 \ub0a0\uc774\ub098 \uba39\uc744 \uc218 \uc788\ub294 \uc7ac\ub8cc\ub77c\ub3c4 \uc5b4\ub5a4 \ub0a0\uc758 \uc74c\uc2dd\uc774 \ub418\uba74 \uc0ac\ub78c\ub4e4\uc740 \ub2e4\uc74c \ud574 \uac19\uc740 \uc2dc\uae30\ub97c \ud568\uaed8 \ub5a0\uc62c\ub9ac\uac8c \ub41c\ub2e4. \uc774\uac83\uc740 \uba85\uc808 \uc74c\uc2dd\uc744 \uc77d\ub294 \ud55c \uac00\uc9c0 \uad00\uc810\uc774\ub2e4. \ud3ec\uc7a5\uc740 \ub0b4\uc6a9\ubb3c\uc744 \uac00\ub9ac\ub294 \uac83\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc \ucad1\ucbd4\uc5d0\uc11c\ub294 \uc74c\uc2dd\uc758 \ubc14\uae65\ubaa8\uc591\uc744 \ud568\uaed8 \ub9cc\ub4e0\ub2e4. \uc78e\uc774 \uc811\ud78c \uba74\uacfc \uc2e4\uc774 \uc9c0\ub098\uac00\ub294 \ubc29\ud5a5\uc744 \ubcf4\uba74 \uc791\uac8c \ub098\ub204\uc5b4 \ub2f4\ub294 \ud589\ub3d9\uc774 \ub5a0\uc624\ub978\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4 \uc18d \ud55c \uac1c\uc758 \ud615\ud0dc\uac00 \ubaa8\ub4e0 \uc9c0\uc5ed\uc758 \uc720\uc77c\ud55c \ubaa8\uc591\uc774\ub77c\uace0 \uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uac19\uc740 \uc774\ub984 \uc544\ub798\uc5d0\ub3c4 \uc7ac\ub8cc\uc640 \uc2f8\ub294 \ubc29\uc2dd\uc758 \ucc28\uc774\uac00 \uc788\uc744 \uc218 \uc788\ub2e4. \uc78e\uc758 \uc885\ub958\ub3c4 \uc790\ub8cc\uac00 \uc124\uba85\ud558\ub294 \ubc94\uc704\uc5d0\uc11c \uc77d\uc5b4\uc57c \ud55c\ub2e4. \uc774 \uc0ac\uc9c4\uc740 \ub300\ub098\ubb34 \uc78e\uacfc \uc2e4\ub85c \uac10\uc2fc \ubaa8\uc2b5\uc73c\ub85c \uc18c\uac1c\ub41c\ub2e4. \uc2dd\ubb3c \uc774\ub984\uc774 \uc788\ub2e4\uace0 \ud5a5\uacfc \uc870\ub9ac \ud6a8\uacfc\uc758 \ubaa8\ub4e0 \uc138\ubd80\uac00 \uc800\uc808\ub85c \uc785\uc99d\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c\ub294 \ud45c\uba74\uc5d0 \ub193\uc778 \uc78e\uc774 \ub2e8\uc21c\ud55c \ubc30\uacbd\uc774 \uc544\ub2c8\ub77c \uc74c\uc2dd\uc758 \ubaa8\uc2b5\uc744 \uc774\ub8e8\ub294 \ubd80\ubd84\uc774\ub77c\ub294 \uc810\ubd80\ud130 \uc0b4\ud3b4\ubcf8\ub2e4. \uad50\uc7ac\ub294 \uc5ec\ub7ec \uae30\uc6d0 \uc774\uc57c\uae30 \uac00\uc6b4\ub370 \uad74\uc6d0\uc744 \uae30\ub9ac\ub294 \uc804\uc2b9\uc744 \uc18c\uac1c\ud55c\ub2e4. \uad8c\ub825\uc5d0\uc11c \uba40\uc5b4\uc9c4 \uc2dc\uc778\uacfc \uad00\ub9ac\uc758 \uc8fd\uc74c \ub4a4\uc5d0 \uc0ac\ub78c\ub4e4\uc774 \uac15\uc5d0 \uc300 \uc74c\uc2dd\uc744 \ub358\uc84c\ub2e4\ub294 \uc774\uc57c\uae30\ub2e4. \ubb3c\uace0\uae30\uc758 \uad00\uc2ec\uc744 \ub3cc\ub824 \uadf8\uc758 \ubab8\uc744 \ucc3e\uc73c\ub824 \ud588\ub2e4\uace0 \uc804\ud574\uc9c4\ub2e4. \uc74c\uc2dd\uc774 \ub204\uad70\uac00\ub97c \uae30\uc5b5\ud558\ub294 \ud589\ub3d9\uacfc \uc5f0\uacb0\ub418\ub294 \uc124\uba85\uc774\ub2e4. \ub2e4\ub9cc \uc774 \uc804\uc2b9\uc744 \ud55c \ubc88\uc758 \uc0ac\uac74\uc774 \ubaa8\ub4e0 \ucad1\ucbd4\uc758 \uc2dc\uc791\uc774\uc5c8\ub2e4\ub294 \ud655\uc815\ub41c \uae30\ub85d\uc73c\ub85c \ubc14\uafb8\uc9c0\ub294 \uc54a\ub294\ub2e4. \uad50\uc7ac \uc790\uccb4\ub3c4 \ub2e8\uc624\uc758 \uc720\ub798\uac00 \uc5ec\ub7ec \uac00\uc9c0\ub77c\uace0 \uc54c\ub824 \uc900\ub2e4. \uc804\uc2b9\uc740 \uc0ac\ub78c\ub4e4\uc774 \uc74c\uc2dd\uacfc \uba85\uc808\uc744 \uc5b4\ub5a4 \uc774\uc57c\uae30\ub85c \uae30\uc5b5\ud588\ub294\uc9c0 \ubcf4\uc5ec \uc904 \uc218 \uc788\ub2e4. \uc2e4\uc81c \uae30\uc6d0\uc744 \ubc1d\ud788\ub294 \uc5ed\uc0ac \uc5f0\uad6c\uc640 \ubb38\ud654\uc801 \uc758\ubbf8\ub97c \uc77d\ub294 \uc77c\uc740 \uac19\uc740 \uc790\ub8cc\ub97c \ubcf4\uc544\ub3c4 \uc9c8\ubb38\uc774 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc74c\ub825 \ub2e4\uc12f\uc9f8 \ub2ec \ub2e4\uc12f\uc9f8 \ub0a0\uc774\ub77c\ub294 \uc2dc\uc810\uc740 \ub9e4\ub144 \ub3cc\uc544\uc628\ub2e4. \ud2b9\uc815 \uc74c\uc2dd\uc744 \uadf8\ub0a0\uacfc \uc5f0\uacb0\ud558\uba74 \uc7ac\ub8cc\uc758 \ub9db\uc774 \uc0ac\ub78c\uacfc \ud589\uc0ac\uc758 \uae30\uc5b5\uc744 \ud568\uaed8 \ubd88\ub7ec\uc62c \uc218 \uc788\ub2e4. \uc5b8\uc81c \uba39\ub290\ub0d0\uac00 \ubb34\uc5c7\uc744 \uba39\ub290\ub0d0\uc758 \ub73b\uc5d0 \uc601\ud5a5\uc744 \uc8fc\ub294 \uac83\uc774\ub2e4. \uac19\uc740 \ucc39\uc300\uc774\ub77c\ub3c4 \uc77c\uc0c1\uc758 \uc2dd\uc0ac\uc640 \uba85\uc808 \uc74c\uc2dd\uc774\ub77c\ub294 \uc790\ub9ac\ub294 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \uba85\uc808 \ubc16\uc5d0\ub294 \uc804\ud600 \uba39\uc9c0 \uc54a\ub294\ub2e4\uac70\ub098 \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uac19\uc740 \ucd94\uc5b5\uc744 \uac00\uc9c4\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc9c0\uc5ed\uacfc \uac00\uc815, \uac1c\uc778\uc758 \uacbd\ud5d8\uc740 \ub2e4\uc591\ud558\ub2e4. \uc5ec\uae30\uc11c\ub294 \ud589\uc0ac\uc640 \uc74c\uc2dd\uc758 \uc5f0\uacb0\uc744 \uc18c\uac1c\ud558\ub294 \uad50\uc7ac\uc758 \uad00\uc810\uc744 \ub530\ub77c\uac04\ub2e4. \ud558\ub098\uc758 \uc774\ub984\uc744 \ubc30\uc6b4 \ub4a4 \ub9db\uc758 \ud45c\uc900 \ud558\ub098\ub85c \uc904\uc774\uae30\ubcf4\ub2e4 \uc5b4\ub5a4 \uc790\ub9ac\uc5d0 \ub193\uc600\ub294\uc9c0 \uc9c8\ubb38\ud558\ub294 \ud3b8\uc774 \ubb38\ud654\uc5d0 \uac00\uae4c\uc774 \uac04\ub2e4. \uc0ac\uc9c4\uc758 \ud3ec\uc7a5\uc744 \uc54c\uc544\ubcf4\uc544\ub3c4 \uc18d\uc7ac\ub8cc\uae4c\uc9c0 \uc790\ub3d9\uc73c\ub85c \uc77d\uc744 \uc218\ub294 \uc5c6\ub2e4. \uad50\uc7ac\ub294 \ub2e4\uc591\ud55c \uc18d\uc744 \ub123\ub294\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub2eb\ud78c \ubb3c\uac74\uc5d0\uc11c \ubcf4\uc774\uc9c0 \uc54a\ub294 \ubd80\ubd84\uc744 \uc77c\ubc18\uc801\uc778 \uc608 \ud558\ub098\ub85c \ucc44\uc6b0\uc9c0 \uc54a\ub294 \uac83\uc774 \uc815\ud655\ud558\ub2e4. \uc774\ub984\uc774 \uac19\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ubaa8\ub4e0 \uad6c\uc131 \uc694\uc18c\uac00 \uac19\ub2e4\ub294 \uc8fc\uc7a5\uc744 \uad6c\ubd84\ud560 \uc218 \uc788\ub2e4. \uc774 \uc791\uc740 \ud55c\uacc4\ub294 \uac10\uc0c1\uc744 \ub9c9\uae30\ubcf4\ub2e4 \ub354 \ub9ce\uc740 \uad00\uc2ec\uc744 \ub0a8\uae34\ub2e4. \ub2e4\ub978 \uc9c0\uc5ed\uc758 \ucad1\ucbd4\ub97c \ub9cc\ub098\uba74 \ubb34\uc5c7\uc73c\ub85c \uc2f8\uace0 \uc5b4\ub5bb\uac8c \ubb36\uc5c8\ub294\uc9c0, \uc5b4\ub5a4 \ub0a0\uc758 \uc74c\uc2dd\uc73c\ub85c \uc18c\uac1c\ud558\ub294\uc9c0 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uc78e\uc0ac\uadc0\uc640 \uc2e4\ub85c \ub458\ub7ec\uc2fc \ubaa8\uc591\uc5d0\uc11c \uc7ac\ub8cc\uc640 \uc190\uc77c, \ub2ec\ub825\uacfc \uc774\uc57c\uae30\uc758 \uad00\uacc4\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \uc74c\uc2dd\uc758 \uc774\ub984 \ud558\ub098\uac00 \uadf8 \ub4a4\uc758 \uc5ec\ub7ec \uc0dd\ud65c\uc744 \ubcf4\ub294 \ud45c\uc9c0\uac00 \ub41c\ub2e4. \uc774 \uba85\uc808\uc5d0\ub294 \uad74\uc6d0\uacfc \uad00\ub828\ub41c \uc774\uc57c\uae30\ub97c \ube44\ub86f\ud574 \uc5ec\ub7ec \uae30\uc6d0 \uc774\uc57c\uae30\uac00 \uc804\ud574\uc9c4\ub2e4. \uad50\uc7ac\ub3c4 \ud558\ub098\uc758 \uc720\ub798\ub9cc\uc774 \uc720\uc77c\ud55c \uc0ac\uc2e4\uc774\ub77c\uace0 \uc81c\uc2dc\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc624\ub79c \ud48d\uc2b5\uc5d0 \ubd99\uc740 \uc774\uc57c\uae30\ub294 \uadf8 \uc790\uccb4\ub85c \ub098\ub204\uc5b4 \uc77d\uc744 \ubd80\ubd84\uc774\ub2e4. \uc624\ub298\uc740 \uc2e4\ub85c \ubb36\uc778 \uafb8\ub7ec\ubbf8 \ud558\ub098\ub9cc \uae30\uc5b5\ud574\ub3c4 \uc88b\uaca0\ub2e4. \uc6b0\ub9ac\uac00 \uc74c\uc2dd\uc774\ub77c\uace0 \ubd80\ub974\ub294 \uac83\uc740 \ub9db\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uc2f8\ub294 \ubaa8\uc591\uacfc \uc5ec\ub294 \uc190\uae38, \ud574\ub9c8\ub2e4 \ub3cc\uc544\uc624\ub294 \ub54c\ub3c4 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4. \ucad1\ucbd4\ub294 \uadf8\ub7f0 \uc5ec\ub7ec \uacb9\uc744 \ud55c\ub208\uc5d0 \ubcf4\uc5ec \uc8fc\ub294 \uc74c\uc2dd\uc774\ub2e4."}, {"id": "black-death-labor-and-wages", "title": "\ud751\uc0ac\ubcd1 \ub4a4\uc758 \uc784\uae08 \u2014 \uc77c\ud560 \uc0ac\ub78c\uc774 \uc904\uc790 \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\uc744\uae4c", "summary": "\ub178\ub3d9\ub825 \ubd80\uc871\uacfc \uc784\uae08 \uc694\uad6c, \uc601\uad6d \ub178\ub3d9\uc790\ubc95\uacfc \uae38\ub4dc\uc758 \ubb38\ud131\uc744 \ud1b5\ud574 \uacbd\uc81c\uc801 \ubcc0\ud654\uc640 \uad8c\ub825\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "ideas", "category_title": "\uc0dd\uac01\uacfc \uc9c0\uc2dd", "subcategory": "\uc0ac\ud68c\uc640 \uc81c\ub3c4\uc758 \ud0c4\uc0dd", "categories": ["ideas"], "url": "stories/black-death-labor-and-wages/index.html", "image": "../media/black-death-labor-and-wages.png", "alt": "\ub4e4\ud310\uc5d0\uc11c \uc791\uc5c5 \ub3c4\uad6c\ub97c \ub4e0 \ub178\ub3d9\uc790\ub4e4\uacfc \uc7a5\ubd80\ub97c \ub4e0 \uad00\ub9ac\uac00 \uc774\uc57c\uae30\ud558\ub294 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ud751\uc0ac\ubcd1 \ub4a4\uc758 \uc784\uae08 \u2014 \uc77c\ud560 \uc0ac\ub78c\uc774 \uc904\uc790 \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\uc744\uae4c 14\uc138\uae30 \uc720\ub7fd\uc758 \ub18d\uc7a5\uacfc \ub3c4\uc2dc\uc5d0\uc11c \ubc8c\uc5b4\uc9c4 \ub178\ub3d9\uc758 \ud611\uc0c1 \ub178\ub3d9\ub825 \ubd80\uc871\uacfc \uc784\uae08 \uc694\uad6c, \uc601\uad6d \ub178\ub3d9\uc790\ubc95\uacfc \uae38\ub4dc\uc758 \ubb38\ud131\uc744 \ud1b5\ud574 \uacbd\uc81c\uc801 \ubcc0\ud654\uc640 \uad8c\ub825\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \uc0ac\ud68c\uc640 \uc81c\ub3c4\uc758 \ud0c4\uc0dd \uc0dd\uac01\uacfc \uc9c0\uc2dd \uc218\ud655\ud560 \ubc2d\uc740 \ub0a8\uc544 \uc788\ub294\ub370 \uc77c\ud560 \uc0ac\ub78c\uc774 \ubd80\uc871\ud558\ub2e4. \ub545\uc744 \uac00\uc9c4 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ub09c\uac10\ud55c \uc77c\uc774\uc9c0\ub9cc \ub178\ub3d9\uc790\uc5d0\uac8c\ub294 \ub354 \ub098\uc740 \uc870\uac74\uc744 \uc694\uad6c\ud560 \uc5ec\uc9c0\uac00 \uc0dd\uae38 \uc218 \uc788\ub2e4. 14\uc138\uae30 \uc720\ub7fd\uc5d0\uc11c \ud751\uc0ac\ubcd1\uc774 \uc9c0\ub098\uac04 \ub4a4 \uc774\ub7f0 \uae34\uc7a5\uc774 \ub098\ud0c0\ub0ac\ub2e4. \ubb3c\ub860 \uc218\ub9ce\uc740 \uc0ac\ub78c\uc758 \uc8fd\uc74c\uc744 \uacbd\uc81c\uc5d0 \ub3c4\uc6c0\uc774 \ub41c \uc0ac\uac74\uc73c\ub85c \ubd80\ub97c \uc218\ub294 \uc5c6\ub2e4. \uac00\uc871\uacfc \uc774\uc6c3\uc744 \uc783\uc740 \uc0ac\ud68c\uac00 \ub2e4\uc2dc \uc6c0\uc9c1\uc774\ub294 \uacfc\uc815\uc5d0\uc11c \uc784\uae08\uacfc \uc77c\uc758 \uaddc\uce59\uc774 \uc5b4\ub5bb\uac8c \ub2ec\ub77c\uc84c\ub294\uc9c0, \uadf8 \ub4a4\uc758 \uac08\ub4f1\uc744 \uc0b4\ud3b4\ubcfc \uc774\uc57c\uae30\ub2e4. \ud751\uc0ac\ubcd1\uc740 \uc720\ub7fd\uc758 \uc778\uad6c\uc640 \uacf5\ub3d9\uccb4\uc5d0 \ud070 \ud53c\ud574\ub97c \uc8fc\uc5c8\ub2e4. \ub18d\ucd0c\uacfc \ub3c4\uc2dc \ubaa8\ub450 \uc77c\ud560 \uc0ac\ub78c\uc774 \ubaa8\uc790\ub790\ub2e4. \uc0b4\uc544\ub0a8\uc740 \uc0ac\ub78c\ub4e4\uc740 \uc774\uc804\uc758 \uc0dd\ud65c\uc744 \uc774\uc5b4 \uac00\uc57c \ud588\uc9c0\ub9cc \uc0dd\uc0b0\uacfc \uace0\uc6a9\uc758 \uc870\uac74\uc740 \uc608\uc804\uacfc \uac19\uc9c0 \uc54a\uc558\ub2e4. \ub18d\uc7a5\uc5d0\ub294 \uc791\ubb3c\uc744 \ub3cc\ubcfc \uc190\uc774 \ud544\uc694\ud588\uace0 \ub3c4\uc2dc\uc758 \uc791\uc5c5\uc7a5\uc5d0\ub3c4 \uc219\ub828\uacfc \uc2dc\uac04\uc774 \ud544\uc694\ud588\ub2e4. \ub545\uacfc \uac74\ubb3c\uc744 \uc18c\uc720\ud558\ub294 \uac83\ub9cc\uc73c\ub85c \uc0dd\uc0b0\uc774 \uc800\uc808\ub85c \uc774\uc5b4\uc9c0\uc9c0\ub294 \uc54a\uc558\ub2e4. \uc77c\ud558\ub294 \uc0ac\ub78c\uc758 \uc874\uc7ac\uac00 \ub354 \ub69c\ub837\ud558\uac8c \ub4dc\ub7ec\ub098\ub294 \uc0c1\ud669\uc774\uc5c8\ub2e4. \ubd80\uc871\ud574\uc9c4 \ub178\ub3d9\uc790\ub97c \uad6c\ud558\uae30 \uc704\ud574 \uc5b4\ub5a4 \uc9c0\uc8fc\ub294 \uc774\uc804\ubcf4\ub2e4 \ub098\uc740 \uc870\uac74\uc744 \uc81c\uc2dc\ud588\ub2e4. \ub18d\ubbfc\uc740 \ub2e4\ub978 \uc601\uc9c0\ub85c \uc62e\uae30\uac70\ub098 \ub3c4\uc2dc\uc5d0\uc11c \uc784\uae08\uc744 \ubc1b\ub294 \uc77c\uc744 \ucc3e\uae30\ub3c4 \ud588\ub2e4. \uac00\uc871\uc774 \uc624\ub7ab\ub3d9\uc548 \uba38\ubb3c\ub358 \uc7a5\uc18c\ub9cc\uc774 \uc720\uc77c\ud55c \uc120\ud0dd\uc9c0\ub294 \uc544\ub2c8\uac8c \ub418\uc5c8\ub2e4. \uc774\ub3d9\ud560 \uac00\ub2a5\uc131\uc740 \ud611\uc0c1\uc758 \ud798\uc774 \ub420 \uc218 \uc788\uc5c8\ub2e4. \uc5ec\uae30\uc5d0\uc11c \ubc1b\ub294 \ubcf4\uc0c1\uc774 \uc801\ub2e4\uba74 \ub2e4\ub978 \uacf3\uc744 \uc0dd\uac01\ud560 \uc5ec\uc9c0\uac00 \uc0dd\uae30\uae30 \ub54c\ubb38\uc774\ub2e4. \ub2e4\ub9cc \ub204\uad6c\ub098 \uac19\uc740 \uc815\ubcf4\uc640 \uc790\uc6d0, \uc774\ub3d9\uc758 \uc790\uc720\ub97c \uac00\uc9c4 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ubcc0\ud654\uc758 \uae30\ud68c\ub3c4 \uace0\ub974\uac8c \ub098\ub258\uc9c0 \uc54a\uc558\ub2e4. \uc0ac\ub78c\uc774 \ubd80\uc871\ud558\ub2c8 \uc784\uae08\uc774 \uc624\ub978\ub2e4\ub294 \ud55c \uc904\ub85c \uc774 \uc774\uc57c\uae30\ub97c \ub05d\ub0b4\uae30\ub294 \uc5b4\ub835\ub2e4. \uc9c0\uc8fc\uc640 \ud1b5\uce58\uc790\ub294 \uae30\uc874\uc758 \uc9c8\uc11c\ub97c \uc9c0\ud0a4\ub824 \ud588\ub2e4. \ub354 \ub098\uc740 \ub300\uc6b0\ub97c \uc694\uad6c\ud558\ub294 \ub178\ub3d9\uc790\uc5d0\uac8c \ubc95\uacfc \uad00\uc2b5\uc774 \ub9de\uc11c\ub294 \uc77c\uc774 \ubc8c\uc5b4\uc84c\ub2e4. \uc784\uae08\uc740 \uc77c\uc190\uc758 \ub9ce\uace0 \uc801\uc74c\ubfd0 \uc544\ub2c8\ub77c \ub204\uac00 \uaddc\uce59\uc744 \ub9cc\ub4e4\uace0 \uc9d1\ud589\ud560 \uc218 \uc788\ub294\uc9c0\uc5d0\ub3c4 \uc601\ud5a5\uc744 \ubc1b\uc558\ub2e4. \uace0\uc6a9\uc8fc\uac00 \uc81c\uc2dc\ud55c \uc870\uac74\uc744 \uac70\uc808\ud560 \uad8c\ub9ac, \ub2e4\ub978 \uacf3\uc73c\ub85c \ub5a0\ub0a0 \uad8c\ub9ac\uac00 \uc5b4\ub290 \uc815\ub3c4\uc778\uc9c0\uac00 \uc911\uc694\ud55c \ubb38\uc81c\uc600\ub2e4. \uc601\uad6d\uc5d0\uc11c\ub294 1349\ub144 \ub178\ub3d9\uc790\uc758 \ubcf4\uc218\ub97c \ud751\uc0ac\ubcd1 \uc774\uc804 \uc218\uc900\uc5d0 \ubb36\uc73c\ub824\ub294 \ubc95\uc774 \ub098\uc654\ub2e4. 1351\ub144\uc758 \ub178\ub3d9\uc790\ubc95\ub3c4 \uc77c\ud560 \uc218 \uc788\ub294 \uc0ac\ub78c\uc758 \ucde8\uc5c5\uacfc \uc784\uae08 \uc870\uac74\uc744 \ud1b5\uc81c\ud588\ub2e4. \ubd80\uc871\ud55c \ub178\ub3d9\ub825\uc744 \ub354 \uc720\ub9ac\ud55c \uc870\uac74\uc73c\ub85c\ub9cc \uacbd\uc7c1\ud574 \uad6c\ud558\ub3c4\ub85d \ub450\uc9c0 \uc54a\uc740 \uac83\uc774\ub2e4. \uc774 \ubc95\ub4e4\uc740 \ub2f9\uc2dc \uad8c\ub825\uc790\ub4e4\uc774 \ubb34\uc5c7\uc744 \uac71\uc815\ud588\ub294\uc9c0 \ubcf4\uc5ec \uc900\ub2e4. \uc77c\uc190\uc744 \ud655\ubcf4\ud558\uace0 \uae30\uc874 \ube44\uc6a9\uacfc \uad00\uacc4\ub97c \uc720\uc9c0\ud558\ub824\ub294 \uc2dc\ub3c4\uc600\ub2e4. \uadf8\ub7ec\ub098 \ubc95\uc774 \uc4f0\uc600\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc9c0\uc5ed\uc758 \uc2e4\uc81c \uc784\uae08\uc774 \uadf8\ub300\ub85c \ud1b5\uc81c\ub418\uc5c8\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub3c4\uc2dc\uc758 \uc218\uacf5\uc5c5 \uc791\uc5c5\uc7a5 \uc5ed\uc2dc \uc77c\uc190\uc774 \ud544\uc694\ud588\ub2e4. \uacac\uc2b5\uc744 \uc2dc\uc791\ud560 \uae30\ud68c\uac00 \ub298\uac70\ub098 \uc218\ub828 \uae30\uac04\uc774 \uc9e7\uc544\uc9c0\ub294 \uacbd\uc6b0\uac00 \uc788\uc5c8\ub2e4. \ub18d\ucd0c\uc5d0\uc11c \ub098\uc628 \uc0ac\ub78c\uc5d0\uac8c \uc0c8\ub85c\uc6b4 \uae30\uc220\uc744 \ubc30\uc6b8 \uae38\uc774 \uc0dd\uae38 \uc218 \uc788\uc5c8\ub2e4. \ubc18\uba74 \uae38\ub4dc\uc758 \uc7a5\uc778\ub4e4\uc740 \ub3c5\ub9bd\uc801\uc778 \uc8fc\uc778\uc774 \ub418\ub294 \uc790\uaca9\uc744 \uc790\uae30 \uac00\uc871\uacfc \uac00\uae4c\uc6b4 \uc0ac\ub78c\uc5d0\uac8c \uc720\ub9ac\ud558\uac8c \uc81c\ud55c\ud558\uae30\ub3c4 \ud588\ub2e4. \uc791\uc5c5\uc7a5\uc5d0 \ub4e4\uc5b4\uac00\ub294 \ubb38\uc774 \ub113\uc5b4\uc838\ub3c4 \ub192\uc740 \uc9c0\uc704\ub85c \uc62c\ub77c\uac00\ub294 \ubb38\uae4c\uc9c0 \ud568\uaed8 \ub113\uc5b4\uc9c4 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uae30\uc874\uc758 \ubd80\ub2f4\uacfc \uc0c8\ub85c\uc6b4 \uc694\uad6c\ub294 \uc5ec\ub7ec \uc9c0\uc5ed\uc758 \uc800\ud56d\uc73c\ub85c \uc774\uc5b4\uc84c\ub2e4. 1358\ub144 \ud504\ub791\uc2a4\uc758 \uc790\ud06c\ub9ac, 1381\ub144 \uc601\uad6d\uc758 \ub18d\ubbfc \ubc18\ub780\uc5d0\ub294 \ub18d\ubbfc\ub9cc \uc544\ub2c8\ub77c \uc0c1\uc778\uacfc \uc7a5\uc778 \ub4f1\ub3c4 \ucc38\uc5ec\ud588\ub2e4. \uc0ac\ub78c\ub4e4\uc758 \ubd88\ub9cc\uc740 \uc784\uae08 \ud55c \ud56d\ubaa9\uc5d0\ub9cc \uba38\ubb3c\uc9c0 \uc54a\uc558\ub2e4. \uc774 \uc0ac\uac74\ub4e4\uc744 \ud751\uc0ac\ubcd1 \ud558\ub098\uac00 \uc790\ub3d9\uc73c\ub85c \ub9cc\ub4e0 \uacb0\uacfc\ub77c\uace0 \uc124\uba85\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc804\uc7c1\uacfc \uc138\uae08, \ud1b5\uce58\uc640 \uc9c0\uc5ed\uc758 \uad00\uacc4\uac00 \ud568\uaed8 \uc5bd\ud600 \uc788\uc5c8\ub2e4. \ub2e4\ub9cc \uc778\uad6c \uac10\uc18c \ub4a4 \ub2ec\ub77c\uc9c4 \ub178\ub3d9 \uc870\uac74\uc740 \uae30\uc874 \uad8c\ud55c\uc744 \ub2e4\uc2dc \ubb3b\uac8c \ud558\ub294 \uc911\uc694\ud55c \ubc30\uacbd\uc774\uc5c8\ub2e4. \ud751\uc0ac\ubcd1 \ub4a4\uc5d0 \ubd09\uac74 \uc9c8\uc11c\uac00 \uc57d\ud574\uc84c\ub2e4\ub294 \ud070 \uc124\uba85\uc740 \uc9c0\uc5ed\uc758 \ucc28\uc774\ub97c \uac00\ub9b4 \uc218 \uc788\ub2e4. \uc11c\uc720\ub7fd\uc5d0\uc11c \ub098\ud0c0\ub09c \ubcc0\ud654\ub97c \ubaa8\ub4e0 \uc2dc\ub300\uc640 \ubaa8\ub4e0 \uc9c0\uc5ed\uc758 \ub18d\ubbfc\uc5d0\uac8c \ub611\uac19\uc774 \uc801\uc6a9\ud560 \uc218\ub294 \uc5c6\ub2e4. \uadc0\uc871\uc758 \ud798\uacfc \ubd88\ud3c9\ub4f1\ub3c4 \uace7\ubc14\ub85c \uc0ac\ub77c\uc9c0\uc9c0 \uc54a\uc558\ub2e4. \uc774 \uae00\uc5d0\uc11c \uc0b4\ud53c\ub294 \uac83\uc740 \uc8fc\ub85c \uc11c\uc720\ub7fd\uc758 \ubcc0\ud654\uc640 \uc601\uad6d\uc758 \ubc95\uc774\ub2e4. \ub178\ub3d9\uc790\uc5d0\uac8c \uc0dd\uae34 \uc5ec\uc9c0\uc640 \uadf8\uac83\uc744 \ub9c9\uc73c\ub824\ub294 \ud798\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \uc790\uc720\ub85c\uc6b4 \uc784\uae08 \ub178\ub3d9\uc758 \uc138\uacc4\uac00 \uc5b4\ub290 \ub0a0 \uc644\uc131\ub418\uc5c8\ub2e4\ub294 \uc774\uc57c\uae30\uc640\ub294 \uac70\ub9ac\uac00 \uc788\ub2e4. \ub354 \ub192\uc740 \uc784\uae08\uc744 \uc694\uad6c\ud558\ub824\uba74 \ub2f9\uc7a5 \uba39\uace0\uc0b4 \uc218\ub2e8\uacfc \ub2e4\ub978 \uc77c\uc790\ub9ac\uc5d0 \ub300\ud55c \uc815\ubcf4\uac00 \ud544\uc694\ud558\ub2e4. \uc77c\uc190\uc774 \ubd80\uc871\ud574\ub3c4 \uac00\uc871\uc744 \ub3cc\ubcf4\uac70\ub098 \uc774\ub3d9\ud558\uae30 \uc5b4\ub824\uc6b4 \uc0ac\ub78c\uc5d0\uac8c \uc120\ud0dd\uc740 \uc81c\ud55c\ub420 \uc218 \uc788\ub2e4. \ub178\ub3d9\uc790\ub77c\ub294 \ud55c \ub2e8\uc5b4 \uc548\uc5d0\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc0dd\ud65c \uc870\uac74\uc774 \uc788\uc5c8\ub2e4. \uc77c\uc744 \uad6c\ud558\ub7ec \ub5a0\ub098\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc0c8\ub85c\uc6b4 \uae30\ud68c\uc640 \ubd88\uc548\uc774 \ud568\uaed8 \uc0dd\uae34\ub2e4. \uc774\uc804\ubcf4\ub2e4 \ub098\uc740 \ubcf4\uc218\ub97c \ubc1b\uc744 \uc218 \uc788\uc5b4\ub3c4 \uc219\uc18c\uc640 \uad00\uacc4, \uae30\uc220\uc744 \ub2e4\uc2dc \ub9c8\ub828\ud574\uc57c \ud55c\ub2e4. \uba85\ubaa9\uc0c1\uc758 \uc784\uae08 \ubcc0\ud654\uc640 \uc2e4\uc81c \uc0dd\ud65c\uc758 \uac1c\uc120\uc744 \ubc14\ub85c \uac19\uc740 \uac83\uc73c\ub85c \ubcf4\uae30\ub294 \uc5b4\ub835\ub2e4. \uc5ed\uc0ac \uc790\ub8cc\uc5d0 \ub098\uc628 \ubc95\uacfc \uae38\ub4dc\uc758 \uaddc\uce59\uc740 \uc774\ub7f0 \uc120\ud0dd\uc758 \ubc94\uc704\ub97c \uc77d\ub294 \ub370 \ub3c4\uc6c0\uc744 \uc900\ub2e4. \ubc95\uc774 \uc694\uad6c\ud55c \uc774\uc0c1\uc801\uc778 \uc9c8\uc11c\uc640 \uc0ac\ub78c\ub4e4\uc774 \uc2e4\uc81c\ub85c \uc0b4\uc544 \ub0b8 \ubc29\uc2dd \uc0ac\uc774\uc758 \ucc28\uc774\ub3c4 \ub0a8\uc544 \uc788\ub2e4. \uacbd\uc81c\uc758 \uc5ed\uc0ac\ub294 \uadf8 \uac04\uaca9\uc744 \uc0b4\ud53c\ub294 \uc77c\uc774\uae30\ub3c4 \ud558\ub2e4. \uc784\uae08\uc758 \uc5ed\uc0ac\ub294 \uc5bc\ub9c8\ub97c \ubc1b\uc558\ub294\uc9c0 \uc801\ud78c \uc22b\uc790\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \ub2e4\ub978 \uc77c\uc744 \uace0\ub97c \uc218 \uc788\uc5c8\ub294\uc9c0, \uc774\ub3d9\ud560 \uc218 \uc788\uc5c8\ub294\uc9c0, \uc77c\ud558\uc9c0 \uc54a\uaca0\ub2e4\uace0 \ub9d0\ud560 \uc218 \uc788\uc5c8\ub294\uc9c0\ub3c4 \uc911\uc694\ud558\ub2e4. \uac19\uc740 \ubcf4\uc218\ub77c\ub3c4 \uc120\ud0dd\uad8c\uc5d0 \ub530\ub77c \uc758\ubbf8\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \ud751\uc0ac\ubcd1 \uc774\ud6c4\uc758 \ubc2d\uacfc \uc791\uc5c5\uc7a5\uc740 \uadf8 \uc810\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc77c\uc190\uc774 \uadc0\ud574\uc84c\ub2e4\ub294 \uacbd\uc81c\uc758 \ubcc0\ud654\uc640 \uae30\uc874\uc758 \uc9c8\uc11c\ub97c \uc9c0\ud0a4\ub824\ub294 \ubc95\uc774 \ubd80\ub52a\ucce4\ub2e4. \ub3c8\uc758 \uc774\uc57c\uae30\ub97c \ub530\ub77c\uac00\ub2e4 \ubcf4\uba74 \uadf8 \ub3c8\uc744 \ubc1b\uace0 \uc77c\ud560 \uc0ac\ub78c\uc758 \uad8c\ub9ac\uac00 \ud568\uaed8 \ub098\ud0c0\ub09c\ub2e4."}, {"id": "blue-dish-hidden-fortune", "title": "\uc811\uc2dc \ubc14\ub2e5\uc5d0\uc11c \ubcf5 \ud55c \uae00\uc790\ub97c \ub9cc\ub098\ub2e4", "summary": "\ubc31\uc790 \uc811\uc2dc\uc758 \uac00\uc6b4\ub370\uc640 \ubc14\uae65\uba74\uc744 \ub530\ub77c\uac00\uba70 \uae00\uc790\uc640 \uaf43\uc744 \ucc3e\uc2b5\ub2c8\ub2e4.", "category": "ideas", "category_title": "\uc0dd\uac01\uacfc \uc9c0\uc2dd", "subcategory": "\uc608\uc220\uc744 \ubcf4\ub294 \ubc95", "categories": ["ideas"], "url": "stories/blue-dish-hidden-fortune/index.html", "image": "../media/blue-dish-hidden-fortune.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \ubc31\uc790\uccad\ud654\ubcf5\uc790\u00b7\ud480\uaf43\ubb34\ub2ac\uc811\uc2dc \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc811\uc2dc \ubc14\ub2e5\uc5d0\uc11c \ubcf5 \ud55c \uae00\uc790\ub97c \ub9cc\ub098\ub2e4 \uc74c\uc2dd \uc544\ub798\uc5d0 \uc228\uc5b4 \uc788\uc744 \ud478\ub978 \uc778\uc0ac \ubc31\uc790 \uc811\uc2dc\uc758 \uac00\uc6b4\ub370\uc640 \ubc14\uae65\uba74\uc744 \ub530\ub77c\uac00\uba70 \uae00\uc790\uc640 \uaf43\uc744 \ucc3e\uc2b5\ub2c8\ub2e4. \uc608\uc220\uc744 \ubcf4\ub294 \ubc95 \uc0dd\uac01\uacfc \uc9c0\uc2dd \uc74c\uc2dd\uc744 \ub2f4\uc740 \uc811\uc2dc\uc5d0\uc11c\ub294 \uc694\ub9ac\uac00 \uba3c\uc800 \ubcf4\uc778\ub2e4. \uadf8\ub987 \ud55c\uac00\uc6b4\ub370 \uc5b4\ub5a4 \uadf8\ub9bc\uc774 \uc788\ub294\uc9c0\ub294 \ub2e4 \uba39\uace0 \ub098\uc11c\uc57c \uc54c\uac8c \ub418\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4. \uc774 \uc811\uc2dc\ub77c\uba74 \ub9c8\uc9c0\ub9c9\uc5d0 \ubcf5 \ud55c \uae00\uc790\ub97c \ub9cc\ub098\uac8c \ub420\uc9c0\ub3c4 \ubaa8\ub974\uaca0\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc18c\uc7a5\ud55c \ubc31\uc790\uccad\ud654\ubcf5\uc790\u00b7\ud480\uaf43\ubb34\ub2ac\uc811\uc2dc\ub2e4. \uc774\ub984\uc740 \uae38\uc9c0\ub9cc \ub208\uc5ec\uaca8\ubcfc \uac83\uc740 \uc5b4\ub835\uc9c0 \uc54a\ub2e4. \ud770 \ubc14\ud0d5\uc5d0 \ud478\ub978 \uc120, \uc548\ucabd\uc758 \uae00\uc790, \ubc14\uae65\ucabd\uc758 \uaf43\uc774\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc5d0 \ub530\ub974\uba74 \uc811\uc2dc \uc548\ubc14\ub2e5\uc5d0\ub294 \ucee4\ub2e4\ub780 \uc6d0 \ub450 \uc904\uc774 \uc788\uace0 \uadf8 \uc548\uc5d0 \ub3c4\uc548\ud654\ub41c \ubcf5, \uace7 \u798f \uae00\uc790\uac00 \uc788\ub2e4. \ubd93\uae00\uc528 \ud55c \uae00\uc790\ub97c \uadf8\ub300\ub85c \uc801\uc740 \uac83\uc774 \uc544\ub2c8\ub77c \ubb34\ub2ac\ucc98\ub7fc \uad6c\uc131\ud55c \uae00\uc790\ub2e4. \uadf8\ub798\uc11c \ucc98\uc74c\uc5d0\ub294 \uaf43\uc774\ub098 \uae30\ud558\ud559\ubb34\ub2ac\ub85c \ubcf4\uc77c \uc218 \uc788\ub2e4. \uae00\uc790\ub77c\ub294 \uc124\uba85\uc744 \ub4e3\uace0 \ub098\uba74 \uac00\uc6b4\ub370\ub97c \ub2e4\uc2dc \ub4e4\uc5ec\ub2e4\ubcf4\uac8c \ub41c\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \ud55c \ubc88\uc5d0 \uc77d\ud788\uc9c0 \uc54a\ub294\ub2e4\uace0 \uc774\uc0c1\ud55c \uc77c\uc740 \uc544\ub2c8\ub2e4. \uc774\ub984\uc744 \uc54c\uace0 \ucc3e\uc544\ubcf4\ub294 \uacfc\uc815 \uc790\uccb4\uac00 \uc774 \uc811\uc2dc\ub97c \ubcf4\ub294 \uc7ac\ubbf8\ub2e4. \uc7a5\uc2dd\uc740 \uc74c\uc2dd\uc774 \ub193\uc77c \uc548\ucabd\uc5d0\uc11c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \ubc14\uae65\uba74\uc740 S\uc790 \ubaa8\uc591\uc758 \uc120\uc73c\ub85c \ub2e4\uc12f \uad6c\uc5ed\uc744 \ub098\ub204\uace0 \uac01 \uce78\uc5d0 \ud480\uaf43\ubb34\ub2ac\ub97c \uadf8\ub838\ub2e4\uace0 \ud55c\ub2e4. \ud14c\ub450\ub9ac\uc640 \uad7d\uc5d0\ub3c4 \ud478\ub978 \uc120\uc774 \ub458\ub7ec\uc838 \uc788\ub2e4. \ud55c \uc811\uc2dc\ub97c \uc704\uc5d0\uc11c \ubcf4\uba74 \uae00\uc790\uac00 \uc911\uc2ec\uc774\uace0, \uc606\uc5d0\uc11c \ubcf4\uba74 \uaf43\uc774 \uc911\uc2ec\uc774 \ub41c\ub2e4. \uc815\uba74 \uc0ac\uc9c4 \ud55c \uc7a5\ub9cc\uc73c\ub85c \ubb3c\uac74\uc744 \ub2e4 \ubcf4\uc558\ub2e4\uace0 \ub290\ub07c\uae30 \uc26c\uc6b4\ub370, \uadf8\ub987\uc740 \ubc14\ub77c\ubcf4\ub294 \ubc29\ud5a5\uc5d0 \ub530\ub77c \uc804\ud600 \ub2e4\ub978 \ubd80\ubd84\uc744 \ub0b4\uc900\ub2e4. \uadf8\ub987\uc758 \uc548\ucabd\uc740 \uc4f0\uc784\uc758 \uc911\uc2ec\uc774\uba74\uc11c \ubb34\ub2ac\uac00 \ub193\uc77c \uc790\ub9ac\uc774\uae30\ub3c4 \ud558\ub2e4. \uc774 \uc811\uc2dc\uc5d0\ub294 \ub450 \uacb9\uc758 \uc6d0\uacfc \ub3c4\uc548\ud654\ud55c \ubcf5 \uae00\uc790\uac00 \uadf8 \uc548\uc5d0 \uc788\ub2e4. \uc74c\uc2dd\uc744 \ub2f4\uc558\uc744 \ub54c\uc640 \ube44\uc6cc \ub450\uc5c8\uc744 \ub54c \ubcf4\uc774\ub294 \ubd80\ubd84\uc774 \ub2ec\ub790\uc744 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc5b4\ub5a4 \uc74c\uc2dd\uc744 \uc2e4\uc81c\ub85c \ub2f4\uc558\ub294\uc9c0\uc640 \uc2dd\uc0ac\uac00 \ub05d\ub098\uba74 \uc5b4\ub5a4 \ubc18\uc751\uc744 \ubcf4\uc600\ub294\uc9c0\ub294 \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \uc774\uc57c\uae30\ub2e4. \uc5ec\uae30\uc11c\ub294 \uadf8\ub987\uc744 \uc4f0\ub294 \ud589\ub3d9\uacfc \ubcf4\ub294 \ubc29\ud5a5\uc744 \ud568\uaed8 \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uc704\ucabd\uc744 \ubcf4\uc558\uc744 \ub54c \ub208\uc5d0 \ub4e4\uc5b4\uc624\ub294 \uc815\ubcf4\uac00 \uc2e4\uc81c \uc0ac\uc6a9 \uc911\uc5d0\ub3c4 \ub298 \uac19\uc740 \uc815\ub3c4\ub85c \ub4dc\ub7ec\ub0ac\ub2e4\uace0 \uac00\uc815\ud558\uc9c0 \uc54a\ub294 \uac83\uc774\ub2e4. \uc0dd\ud65c \ub3c4\uad6c\uc758 \uc7a5\uc2dd\uc740 \uc804\uc2dc \uc0ac\uc9c4\ucc98\ub7fc \uc5b8\uc81c\ub098 \ubaa8\ub450 \ud3bc\uccd0\uc838 \ubcf4\uc774\ub294 \uc0c1\ud0dc\uc5d0\ub9cc \uc788\uc9c0 \uc54a\uc558\ub2e4. \ubb3c\uac74\uc758 \uc4f0\uc784\uc774 \uac10\uc0c1\uc758 \uc870\uac74\ub3c4 \ubc14\uafc0 \uc218 \uc788\ub2e4. \ub3c4\uc548\ud654\ud55c \uae00\uc790\ub294 \ud3c9\uc18c \uc77d\ub358 \uc790\ud615\uc5d0\uc11c \uba40\uc5b4\uc9c8 \uc218 \uc788\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ud478\ub978 \uc120\uc758 \ud328\ud134\ucc98\ub7fc \ubcf4\uc774\uace0 \uc124\uba85\uc744 \uc77d\uc740 \ub4a4 \uae00\uc790\ub97c \ub2e4\uc2dc \ucc3e\uac8c \ub41c\ub2e4. \uc774 \uc655\ubcf5\uc774 \uc7a5\uc2dd \ubb38\uc790\ub97c \ubcf4\ub294 \uc7ac\ubbf8\ub2e4. \uae00\uc774 \ub73b\ub9cc \uc804\ub2ec\ud55c\ub2e4\ub294 \uc0dd\uac01\uacfc \uadf8\ub9bc\uc740 \ub9d0 \uc5c6\uc774 \ubaa8\uc591\ub9cc \ubcf4\uc778\ub2e4\ub294 \uc0dd\uac01\uc758 \uacbd\uacc4\uac00 \uc870\uae08 \ud750\ub824\uc9c4\ub2e4. \ubcf5\uc774\ub77c\ub294 \ub9d0\uc774 \uc788\ub2e4\uace0 \ud2b9\uc815\ud55c \uc18c\uc720\uc790\uc758 \uc18c\uc6d0\uc774\ub098 \uae30\ub150\uc77c\uc744 \uc0c8\ub85c \ucd94\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc77c\ubc18\uc801\uc778 \ub73b\uacfc \uac1c\ubcc4 \ubb3c\uac74\uc758 \uad6c\uccb4\uc801 \uc0ac\uc6a9\uc740 \ub2e4\ub978 \uc815\ubcf4\ub2e4. \ubc15\ubb3c\uad00\uc774 \uc2dd\ubcc4\ud55c \uae00\uc790\ub97c \uae30\uc900\uc73c\ub85c \ubcf4\ub418 \ub208\uc55e\uc5d0\uc11c \uc5b4\ub5a4 \uc120\uc774 \uadf8\ub807\uac8c \uad6c\uc131\ub418\uc5c8\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uba74 \ub41c\ub2e4. \ub73b\uc744 \uc544\ub294 \uc77c\uc774 \uad00\ucc30\uc744 \ub05d\ub0b4\uae30\ubcf4\ub2e4 \uc0c8\ub85c\uc6b4 \uad00\ucc30\uc744 \uc2dc\uc791\ud558\uac8c \ud560 \uc218 \uc788\ub2e4. \ubc14\uae65\uba74\uc758 S\uc790 \uad6c\ud68d\uc740 \ub458\ub808\ub97c \ub2e4\uc12f \ubd80\ubd84\uc73c\ub85c \ub098\ub204\uace0 \uadf8 \uc548\uc5d0 \ud480\uaf43\uc744 \ubc30\uce58\ud55c\ub2e4. \uc704\uc5d0\uc11c \ubcfc \ub54c\uc758 \uc911\uc559 \uae00\uc790\uc640 \uc606\uc5d0\uc11c \ubcfc \ub54c\uc758 \ubd84\ud560 \ubb34\ub2ac\ub294 \ub2e4\ub978 \uad6c\uc870\ub2e4. \ud558\ub098\uc758 \ubb3c\uac74\uc774 \uc5ec\ub7ec \uba74\uc5d0\uc11c \ubcc4\uac1c\uc758 \ubcf4\uae30\ub97c \uc81c\uacf5\ud55c\ub2e4. \uc815\uba74 \uc0ac\uc9c4 \ud55c \uc7a5\uc774 \uadf8\ub987 \uc804\uccb4\uc758 \uc7a5\uc2dd \uacc4\ud68d\uc744 \ubaa8\ub450 \uc54c\ub824 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc774 \uc815\ubcf4\ub97c \uc54c\uace0 \uc2e4\uc81c \uc0ac\uc9c4\uc744 \ub2e4\uc2dc \ubcf4\uba74 \uc5b4\ub5a4 \uba74\uc774 \ubcf4\uc774\uace0 \uc5b4\ub5a4 \uba74\uc774 \uac00\ub824\uc838 \uc788\ub294\uc9c0 \uad6c\ubcc4\ud558\uac8c \ub41c\ub2e4. \uc124\uba85\uc740 \ubcf4\uc774\uc9c0 \uc54a\ub294 \ubd80\ubd84\uc744 \uc0c1\uc0c1\uc73c\ub85c \uc815\ud655\ud788 \uadf8\ub9ac\ub77c\ub294 \uc694\uad6c\ubcf4\ub2e4 \ub2e4\ub978 \ubc29\ud5a5\ub3c4 \uc788\uc74c\uc744 \uc54c\ub824 \uc8fc\ub294 \uae38\uc7a1\uc774\ub2e4. \ubcc4\ub3c4\uc758 \uc0ac\uc9c4\uacfc \uae30\uad00 \uc124\uba85\uc744 \ud568\uaed8 \ubcf4\uba74 \ub41c\ub2e4. \ubb3c\uac74\uc744 \uc9c1\uc811 \ub4a4\uc9d1\uc5b4 \ud655\uc778\ud558\ub824\ub294 \ub300\uc2e0 \uc81c\uacf5\ub41c \uc790\ub8cc\ub85c \uc2dc\uc120\uc744 \ub113\ud790 \uc218 \uc788\ub2e4. \uad6c\uc5f0\uacfc \uad7d\uc5d0 \ub193\uc778 \uccad\ud654\uc120\uc740 \uc811\uc2dc\uc758 \uc704\uc640 \uc544\ub798 \uacbd\uacc4\ub97c \ub530\ub77c\uac04\ub2e4. \uc911\uc559\uc758 \uae00\uc790\uc640 \ubc14\uae65\uc758 \ud480\uaf43\uc774 \uc11c\ub85c \ub2e4\ub978 \uc7a5\uc2dd\uc774\uc5b4\ub3c4 \uc120\uc774 \uc804\uccb4\uc758 \ub458\ub808\ub97c \uc815\ub9ac\ud560 \uc218 \uc788\ub2e4. \ud070 \uc0c1\uc9d5\uc744 \uba3c\uc800 \uc77d\uace0 \uadf8 \ubc14\uae65\uc744 \ubcf4\uba74 \ub2e8\uc21c\ud55c \uacbd\uacc4\ucc98\ub7fc \ubcf4\uc600\ub358 \ubd80\ubd84\uc5d0\ub3c4 \uc81c\uc791\uc758 \uc120\ud0dd\uc774 \uc788\uc74c\uc744 \uc54c\uac8c \ub41c\ub2e4. \uc785\uc9c0\ub984 18\uc13c\ud2f0\ubbf8\ud130\ub77c\ub294 \ud06c\uae30\uae4c\uc9c0 \ud568\uaed8 \uc77d\uc73c\uba74 \ud654\uba74\uc5d0 \ud655\ub300\ub41c \uc774\ubbf8\uc9c0\uac00 \uc0dd\ud65c\uc758 \uaddc\ubaa8\ub85c \ub3cc\uc544\uc628\ub2e4. \uc190\uc5d0 \ub4e4 \uc218 \uc788\ub294 \uadf8\ub987 \ud55c \uc810\uc5d0 \uc77d\ub294 \uae00\uc790\uc640 \ubcf4\ub294 \ubb34\ub2ac, \ub2f4\ub294 \uae30\ub2a5\uc774 \ud568\uaed8 \ub193\uc600\ub2e4. \ubcf5\uc774\ub77c\ub294 \ud55c \uae00\uc790\ub97c \uc54c\uc544\ubcf8 \ub4a4\uc5d0\ub3c4 \uad00\ucc30\uc774 \ub05d\ub098\uc9c0 \uc54a\ub294 \uc774\uc720\ub2e4. \uc811\uc2dc\ub97c \ub458\ub7ec\ubcf4\ub294 \ubc29\ud5a5\ub9cc \ubc14\uafb8\uc5b4\ub3c4 \uc0c8\ub85c\uc6b4 \uba74\uc774 \ub098\ud0c0\ub09c\ub2e4. \uc18c\uc7a5\ud488 \uc815\ubcf4\uc5d0\ub294 \uc785\uc9c0\ub984\uc774 18\uc13c\ud2f0\ubbf8\ud130\ub77c\uace0 \uc801\ud600 \uc788\ub2e4. \uac70\ub300\ud55c \uc804\uc2dc\uc6a9 \uc811\uc2dc\ub97c \uc0c1\uc0c1\ud558\uae30\ubcf4\ub2e4 \ud06c\uae30\ub97c \uac00\ub2a0\ud558\uba70 \ubcf4\uba74 \ubb34\ub2ac\uc640\uc758 \uac70\ub9ac\ub3c4 \uc870\uae08 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \uc74c\uc2dd\uc744 \ub2f4\uc558\uace0 \ub204\uac00 \uc0ac\uc6a9\ud588\ub294\uc9c0\ub294 \uc774 \uc790\ub8cc\uc5d0\uc11c \ud655\uc778\ud558\uc9c0 \ubabb\ud588\ub2e4. \ubcf5\uc744 \ub9cc\ub09c\ub2e4\ub294 \uccab \uc7a5\uba74\ub3c4 \uadf8\ub987\uc758 \ubc30\uce58\ub97c \ub5a0\uc62c\ub824 \ubcf8 \uc6b0\ub9ac\uc758 \uc0c1\uc0c1\uc774\ub2e4. \ud655\uc2e4\ud55c \uac83\uc740 \ube48 \uc811\uc2dc\ub9cc\uc73c\ub85c\ub3c4 \ubcfc\uac70\ub9ac\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774\ub2e4. \uac00\uc6b4\ub370\uc758 \uae00\uc790\ub97c \ubcf4\uace0, \uc606\uc758 \uaf43\uc744 \ubcf4\ub294 \uac83. \uc2dd\ud0c1\uc758 \ubb3c\uac74\uc744 \ucc9c\ucc9c\ud788 \uc77d\ub294 \uac04\ub2e8\ud55c \ubc29\ubc95\uc774\ub2e4."}, {"id": "descartes-method-and-doubt", "title": "\ub370\uce74\ub974\ud2b8 \ubc29\ubc95\uc11c\uc124 \u2014 \ubb34\uc5c7\uc744 \ud655\uc2e4\ud788 \uc548\ub2e4\uace0 \ub9d0\ud560 \uc218 \uc788\uc744\uae4c", "summary": "\ub124 \uac00\uc9c0 \uaddc\uce59\uacfc \uc720\uba85\ud55c \ubb38\uc7a5\uc774 \ub098\uc628 \ub9e5\ub77d\uc744 \uc26c\uc6b4 \uc608\uc640 \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "ideas", "category_title": "\uc0dd\uac01\uacfc \uc9c0\uc2dd", "subcategory": "\ucca0\ud559\uc758 \uc9c8\ubb38", "categories": ["ideas"], "url": "stories/descartes-method-and-doubt/index.html", "image": "../media/descartes-method-and-doubt.png", "alt": "1649\ub144 \ub7f0\ub358\uc5d0\uc11c \uc778\uc1c4\ud55c \ubc29\ubc95\uc11c\uc124 \uc601\ubb38\ud310\uc758 \uc2e4\uc81c \ud45c\uc81c\uba74. Method\uc640 Reason\uc774\ub77c\ub294 \ub2e8\uc5b4 \ubc0f \ucd9c\ud310 \uc5f0\ub3c4\uac00 \ubcf4\uc785\ub2c8\ub2e4.", "text": "\ub370\uce74\ub974\ud2b8 \ubc29\ubc95\uc11c\uc124 \u2014 \ubb34\uc5c7\uc744 \ud655\uc2e4\ud788 \uc548\ub2e4\uace0 \ub9d0\ud560 \uc218 \uc788\uc744\uae4c \uc791\uac8c \ub098\ub204\uace0 \ucc28\ub840\ub85c \uc0b4\ud53c\ub294 \uc0dd\uac01\uc758 \uae38 \ub124 \uac00\uc9c0 \uaddc\uce59\uacfc \uc720\uba85\ud55c \ubb38\uc7a5\uc774 \ub098\uc628 \ub9e5\ub77d\uc744 \uc26c\uc6b4 \uc608\uc640 \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4. \ucca0\ud559\uc758 \uc9c8\ubb38 \uc0dd\uac01\uacfc \uc9c0\uc2dd \uc798 \uc548\ub2e4\uace0 \uc0dd\uac01\ud55c \uc77c\ub3c4 \uadfc\uac70\ub97c \ud558\ub098\uc529 \ubb3c\uc5b4\ubcf4\uba74 \ub2f5\uc774 \ud750\ub824\uc9c8 \ub54c\uac00 \uc788\ub2e4. \uc9c1\uc811 \ubcf8 \uac83\uacfc \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ub4e4\uc740 \uac83, \uc790\uc8fc \ubc18\ubcf5\ud574\uc11c \uc775\uc219\ud574\uc9c4 \ub9d0\uc774 \ub4a4\uc11e\uc5ec \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ub370\uce74\ub974\ud2b8\uc758 \u300e\ubc29\ubc95\uc11c\uc124\u300f\uc740 \uc0dd\uac01\uc744 \uc5b4\ub514\uc5d0\uc11c \uc2dc\uc791\ud558\uace0 \uc5b4\ub5a4 \uc21c\uc11c\ub85c \ud655\uc778\ud560\uc9c0 \ubb3b\ub294 \ucc45\uc774\ub2e4. 1596\ub144\uc5d0 \ud0dc\uc5b4\ub098 1650\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub09c \ud504\ub791\uc2a4 \ucca0\ud559\uc790\ub294 \uc774 \uc791\ud488\uc744 1637\ub144\uc5d0 \ub0b4\ub193\uc558\ub2e4. \uc720\uba85\ud55c \u2018\ub098\ub294 \uc0dd\uac01\ud55c\ub2e4, \uadf8\ub7ec\ubbc0\ub85c \uc874\uc7ac\ud55c\ub2e4\u2019\ub9cc \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc65c \uadf8\ub7f0 \ud655\uc2e4\ud55c \ucd9c\ubc1c\uc810\uc744 \ucc3e\uc73c\ub824 \ud588\ub294\uc9c0 \ud568\uaed8 \uc77d\uc73c\uba74 \ubb38\uc7a5\uc774 \uc870\uae08 \ub35c \ub0af\uc124\uc5b4\uc9c4\ub2e4. \ucc45\uc758 \uccab \ubd80\ubd84\uc5d0\ub294 \uc790\uc2e0\uc774 \ubc1b\uc740 \uad50\uc721\uacfc \uc138\uc0c1\uc744 \uc0b4\ud53c\ub824 \ud588\ub358 \uc2dc\uac04\uc774 \ub098\uc628\ub2e4. \ub9ce\uc740 \uac83\uc744 \ubc30\uc6e0\ub2e4\uace0 \ubaa8\ub4e0 \ud310\ub2e8\uc774 \ud655\uc2e4\ud574\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc5ec\ud589\uacfc \uacbd\ud5d8 \uc5ed\uc2dc \uc9c0\uc2dd\uc744 \ub113\ud790 \uc218 \uc788\uc9c0\ub9cc \uc11c\ub85c \ub2e4\ub978 \uad00\uc2b5\uacfc \uc0dd\uac01\uc744 \ub9cc\ub098\uac8c \ud55c\ub2e4. \uc774\ub7f0 \ud68c\uace0\uac00 \uc911\uc694\ud55c \uc774\uc720\ub294 \ubc29\ubc95\uc774 \uba38\ub9bf\uc18d\uc758 \uaddc\uce59 \ubaa9\ub85d\uc73c\ub85c\ub9cc \ub4f1\uc7a5\ud558\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc774\ub2e4. \ubb34\uc5c7\uc744 \ubbff\uc5b4\uc57c \ud560\uc9c0 \ud63c\ub780\uc2a4\ub7ec\uc6b4 \uacbd\ud5d8\uc5d0\uc11c \ub354 \ub2e8\ub2e8\ud55c \uae30\uc900\uc744 \ucc3e\uc73c\ub824\ub294 \ud544\uc694\uac00 \uc0dd\uae34\ub2e4. \uc88b\uc740 \uad50\uc721\uacfc \uc2a4\uc2a4\ub85c \uac80\ud1a0\ud558\ub294 \ub2a5\ub825\uc740 \uac19\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4\ub294 \ucd9c\ubc1c\uc810\uc774\ub2e4. \ub370\uce74\ub974\ud2b8\uac00 \uc81c\uc2dc\ud558\ub294 \ubc29\ubc95\uc758 \ud55c \ubc29\ud5a5\uc740 \ubd84\uba85\ud558\uac8c \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \uac83\uc744 \uc11c\ub458\ub7ec \ucc38\uc774\ub77c\uace0 \ubc1b\uc544\ub4e4\uc774\uc9c0 \uc54a\ub294 \uac83\uc774\ub2e4. \ub2f9\uc5f0\ud558\ub2e4\ub294 \ub290\ub08c\uacfc \uadfc\uac70\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uad6c\ubd84\ud558\uc790\ub294 \ub73b\uc73c\ub85c \ub4e4\uc5b4\uac08 \uc218 \uc788\ub2e4. \uadf8\uac00 \uc6d0\ud558\ub294 \uae30\uc900\uc740 \ub9e4\uc6b0 \uc5c4\uaca9\ud558\uc9c0\ub9cc \uc624\ub298\uc758 \ub3c5\uc790\ub3c4 \ubb38\uc81c\uc758 \ubc29\ud5a5\uc740 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc5b4\ub5a4 \ucc45\uc774 \ud6cc\ub96d\ud558\ub2e4\ub294 \ud3c9\uc744 \ub9ce\uc774 \ubcf4\uc558\uc744 \ub54c, \uc9c1\uc811 \uc77d\uc740 \ud310\ub2e8\uacfc \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc758 \ud3c9\uac00\ub97c \ub098\ub204\uc5b4 \ubcfc \uc218 \uc788\ub2e4. \uc774\uac83\uc740 \uc6d0\ubb38\uc5d0 \ub098\uc624\ub294 \uc2e4\uc81c \uc0ac\ub840\uac00 \uc544\ub2c8\ub77c \uaddc\uce59\uc744 \uc774\ud574\ud558\uae30 \uc704\ud55c \uc608\ub2e4. \ubbff\uc74c\uc744 \ubaa8\ub450 \uc5c6\uc560\uae30\ubcf4\ub2e4 \uc9c0\uae08 \ubb34\uc5c7\uc744 \uadfc\uac70\ub85c \ud310\ub2e8\ud588\ub294\uc9c0 \uc54c\uc544\ubcf4\ub294 \uc77c\uc774\ub2e4. \ubcf5\uc7a1\ud55c \ubb38\uc81c\ub97c \uac00\ub2a5\ud55c \ud55c \uc791\uc740 \ubd80\ubd84\uc73c\ub85c \ub098\ub204\uc5b4 \uc0b4\ud53c\ub294 \uaddc\uce59\uc774 \ub098\uc628\ub2e4. \ud55c\uaebc\ubc88\uc5d0 \uc5b4\ub835\ub2e4\uace0 \ub290\uaef4\uc9c0\ub294 \uac83\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc9c8\ubb38\uc774 \uc5bd\ud600 \uc788\uc744 \uc218 \uc788\ub2e4. \ubd84\ub9ac\ud558\uba74 \uc5b4\ub514\ub97c \uc54c\uba70 \uc5b4\ub514\ub97c \ubaa8\ub974\ub294\uc9c0 \ubcf4\uc774\uae30 \uc2dc\uc791\ud55c\ub2e4. \uc5ec\ud589 \uacc4\ud68d\uc774 \uc5b4\ub835\ub2e4\uba74 \ube44\uc6a9\uacfc \uc774\ub3d9, \uba38\ubb34\ub294 \uc2dc\uac04\uacfc \uaf2d \ubcf4\uace0 \uc2f6\uc740 \ub300\uc0c1\uc744 \ub098\ub204\uc5b4 \ubcfc \uc218 \uc788\ub2e4. \ud55c \ubd80\ubd84\uc758 \ub2f5\uc774 \ub098\uba38\uc9c0 \uc804\uccb4\ub97c \uc790\ub3d9\uc73c\ub85c \ud574\uacb0\ud558\uc9c0\ub294 \uc54a\uc9c0\ub9cc \uc0dd\uac01\ud560 \uc790\ub9ac\uac00 \ubd84\uba85\ud574\uc9c4\ub2e4. \uc798\uac8c \ub098\ub208 \ub4a4 \ub2e4\uc2dc \uc5f0\uacb0\ud574\uc57c \ud55c\ub2e4\ub294 \uc810\ub3c4 \ud568\uaed8 \uae30\uc5b5\ud558\uba74 \uc88b\ub2e4. \ub2e8\uc21c\ud558\uace0 \uc54c\uae30 \uc26c\uc6b4 \uac83\uc5d0\uc11c \ub354 \ubcf5\uc7a1\ud55c \uac83\uc73c\ub85c \ub098\uc544\uac00\uba70, \ube60\ub728\ub9b0 \ubd80\ubd84\uc774 \uc5c6\ub294\uc9c0 \uc804\uccb4\ub97c \uc810\uac80\ud558\ub294 \uc0dd\uac01\ub3c4 \uc81c\uc2dc\ub41c\ub2e4. \ubb38\uc81c\ub97c \ub098\ub204\ub294 \uac83\uacfc \ubb34\uc5c7\ubd80\ud130 \uc0b4\ud544\uc9c0 \uc815\ud558\ub294 \uc77c\uc740 \uc11c\ub85c \uc5f0\uacb0\ub41c\ub2e4. \uadf8\ub9ac\uace0 \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \ud769\uc5b4\uc9c4 \ud310\ub2e8\uc744 \ub2e4\uc2dc \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc774 \uaddc\uce59\uc744 \ub530\ub974\uba74 \uc0dd\ud65c\uc758 \ubaa8\ub4e0 \ubb38\uc81c\uac00 \uae54\ub054\ud558\uac8c \ud480\ub9b0\ub2e4\ub294 \uc57d\uc18d\uc73c\ub85c \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc0ac\ub78c\uc758 \uac10\uc815\uacfc \uad00\uacc4\uc5d0\ub294 \ub2e8\uc21c\ud55c \uacc4\uc0b0\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294 \uc870\uac74\uc774 \uc788\ub2e4. \ub2e4\ub9cc \ubb34\uc5c7\uc744 \uba3c\uc800 \ud655\uc778\ud588\uace0 \ubb34\uc5c7\uc744 \uc544\uc9c1 \uac80\ud1a0\ud558\uc9c0 \uc54a\uc558\ub294\uc9c0 \ub4dc\ub7ec\ub0b4\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub418\ub294 \uc0ac\uace0\uc758 \uc2b5\uad00\uc73c\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \ub354 \ud655\uc2e4\ud55c \uadfc\uac70\ub97c \ucc3e\uc73c\ub824\ub294 \uacfc\uc815\uc5d0\uc11c \uac10\uac01\uc774 \uc6b0\ub9ac\ub97c \uc798\ubabb \uc774\ub04c \uc218 \uc788\ub2e4\ub294 \ubb38\uc81c\uac00 \ub4f1\uc7a5\ud55c\ub2e4. \uafc8\uc18d\uc5d0\uc11c\ub3c4 \uc2e4\uc81c\ucc98\ub7fc \ub290\ub07c\ub294 \uacbd\ud5d8\uc774 \uc788\uc73c\ub2c8, \uc9c0\uae08 \ubd84\uba85\ud574 \ubcf4\uc778\ub2e4\ub294 \ub290\ub08c\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uac83\uc744 \ubcf4\uc99d\ud558\uae30 \uc5b4\ub835\ub2e4\ub294 \uac83\uc774\ub2e4. \uc774 \uc758\uc2ec\uc740 \uc138\uc0c1\uc758 \uc544\ubb34 \ub9d0\ub3c4 \ubbff\uc9c0 \uc54a\uaca0\ub2e4\ub294 \ud0dc\ub3c4\ub85c \ub05d\ub0b4\ub824\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \ud754\ub4e4\ub9b4 \uc218 \uc788\ub294 \uac83\uc744 \uc2dc\ud5d8\ud574 \ubcf4\uace0 \uadf8 \ub4a4\uc5d0\ub3c4 \ub0a8\ub294 \ucd9c\ubc1c\uc810\uc744 \ucc3e\uc73c\ub824 \ud55c\ub2e4. \uc758\uc2ec\ud558\ub294 \ud589\ub3d9\uc758 \ubaa9\uc801\uc774 \ubb34\uc5c7\uc778\uc9c0 \ub193\uce58\uba74 \ucc45\uc740 \ub05d\uc5c6\ub294 \ubd88\uc2e0\uc744 \uad8c\ud558\ub294 \ub9d0\ucc98\ub7fc \uc798\ubabb \ub4e4\ub9b4 \uc218 \uc788\ub2e4. \uc720\uba85\ud55c \ubb38\uc7a5\uc740 \uc774 \ub9e5\ub77d\uc5d0\uc11c \ub098\uc628\ub2e4. \ubaa8\ub4e0 \uac83\uc744 \uc758\uc2ec\ud558\ub354\ub77c\ub3c4 \uc9c0\uae08 \uc758\uc2ec\ud558\uace0 \uc0dd\uac01\ud558\ub294 \ud65c\ub3d9\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc644\uc804\ud788 \uc9c0\uc6b0\uae30\ub294 \uc5b4\ub835\ub2e4\ub294 \uac83\uc774\ub2e4. \uadf8 \uc0dd\uac01\ud558\ub294 \uc790\uc2e0\uc744 \ucd9c\ubc1c\uc810\uc73c\ub85c \uc0bc\uc73c\ub824\ub294 \ub17c\ub9ac\uac00 \ubb38\uc7a5\uc744 \ubc1b\uce5c\ub2e4. \uadf8\ub7ec\ub098 \ub0b4\uac00 \uc0dd\uac01\ud55c\ub2e4\ub294 \uc774\uc720\ub85c \ub0b4 \uc0dd\uac01\uc758 \ub0b4\uc6a9\uc774 \uc804\ubd80 \uc633\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc874\uc7ac\uc758 \ud655\uc2e4\uc131\uacfc \uc758\uacac\uc758 \uc815\ud655\uc131\uc740 \ub2e4\ub978 \ubb38\uc81c\ub2e4. \ub9c8\uc74c\uc5d0 \ub4dc\ub294 \uc8fc\uc7a5 \uc55e\uc5d0 \uc720\uba85\ud55c \ubb38\uc7a5\uc744 \ubd99\uc5ec \uac80\ud1a0\ub97c \ub05d\ub0b4\uae30\ubcf4\ub2e4, \uc624\ud788\ub824 \ubb34\uc5c7\uc744 \uc99d\uba85\ud55c \ub9d0\uc778\uc9c0 \ud55c\uacc4\ub97c \uc54c\uc544 \ub450\uba74 \ub354 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \u300e\ubc29\ubc95\uc11c\uc124\u300f\uc5d0\ub294 \uc774 \uc720\uba85\ud55c \ub300\ubaa9 \ub4a4\uc5d0\ub3c4 \uc2e0\uacfc \uc138\uacc4, \ud559\ubb38\uacfc \uc0b6\uc5d0 \uad00\ud55c \ub17c\uc758\uac00 \uc774\uc5b4\uc9c4\ub2e4. \uc624\ub298\uc758 \ub3c5\uc790\uac00 \uadf8 \ubaa8\ub4e0 \ub17c\uc99d\uc744 \ubc14\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud655\uc2e4\ud55c \ucd9c\ubc1c\uc810\uc5d0\uc11c \uc5b4\ub5a4 \uae38\uc744 \uac70\uccd0 \ub2e4\ub978 \uc8fc\uc7a5\uc73c\ub85c \uac00\ub294\uc9c0 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ucc45\uc5d0\ub294 \uc0dd\uac01\uc744 \uac80\ud1a0\ud558\ub294 \ub3d9\uc548 \uc2e4\uc81c \uc0b6\uc5d0\uc11c\ub294 \uc5b4\ub5bb\uac8c \ud589\ub3d9\ud560\uc9c0\uc5d0 \uad00\ud55c \ubb38\uc81c\ub3c4 \uc788\ub2e4. \ubaa8\ub4e0 \ub2f5\uc774 \uc644\uc131\ub420 \ub54c\uae4c\uc9c0 \uc0b4\uc544\uac00\ub294 \uc77c\uc744 \uba48\ucd9c \uc218\ub294 \uc5c6\uae30 \ub54c\ubb38\uc774\ub2e4. \ucca0\ud559\uc758 \uc5c4\uaca9\ud55c \uc694\uad6c\uc640 \ub9e4\uc77c\uc758 \ud310\ub2e8\uc774 \ub9cc\ub098\ub294 \uacf3\uc744 \ubcf4\uba74 \ucd94\uc0c1\uc801\uc778 \ucc45\uc774 \uc0dd\ud65c\uacfc \ub2ff\ub294 \uc9c0\uc810\uc774 \uc0dd\uae34\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 1649\ub144 \ub7f0\ub358\uc5d0\uc11c \uc778\uc1c4\ud55c \uc601\ubb38\ud310\uc758 \uc2e4\uc81c \ud45c\uc81c\uba74\uc774\ub2e4. \ud504\ub791\uc2a4\uc5b4 \ucd08\ud310\uc774\ub098 \ub370\uce74\ub974\ud2b8\uc758 \uce5c\ud544 \uc6d0\uace0\ub294 \uc544\ub2c8\uc9c0\ub9cc, \ubc29\ubc95\uacfc \uc774\uc131\uc774\ub77c\ub294 \ub2e8\uc5b4\uac00 \uc5b4\ub5a4 \ucc45\uc758 \uc81c\ubaa9\uc73c\ub85c \uc804\ud574\uc84c\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \uc5ed\uc0ac\uc801 \uc790\ub8cc\ub2e4. \uc624\ub298 \uc798 \uc548\ub2e4\uace0 \uc5ec\uae30\ub294 \uac83 \ud558\ub098\ub97c \uace8\ub77c \uadfc\uac70\uc640 \uc21c\uc11c\ub97c \uc9e7\uac8c \uc801\uc5b4 \ubcf4\uc790. \ubb34\uc5c7\uc744 \uba3c\uc800 \ud655\uc778\ud560 \uc218 \uc788\uace0 \uc5b4\ub5a4 \ubd80\ubd84\uc774 \ube60\uc84c\ub294\uc9c0 \uc0b4\ud53c\uba74 \ub41c\ub2e4. \ub370\uce74\ub974\ud2b8\ub97c \uc77d\ub294 \uad50\uc591\uc740 \uc720\uba85\ud55c \ubb38\uc7a5\uc744 \uc778\uc6a9\ud558\ub294 \uc77c\uc5d0\uc11c \uadf8 \ubb38\uc7a5\uc774 \ud544\uc694\ud588\ub358 \uc9c8\ubb38\uc744 \uc790\uae30 \ub9d0\ub85c \ub418\ubb3b\ub294 \uc77c\ub85c \ub113\uc5b4\uc9c8 \uc218 \uc788\ub2e4."}, {"id": "dewey-decimal-books-and-shelves", "title": "\ub4c0\uc774 \uc2ed\uc9c4\ubd84\ub958 \u2014 \ucc45\uc758 \uc790\ub9ac\ub97c \uc22b\uc790\ub85c \ucc3e\uae30\uae4c\uc9c0", "summary": "\ucd08\uae30 \uc2ed\uc9c4\ubd84\ub958\uc758 \uc22b\uc790\uc640 \uc0c1\ub300\uc801 \ubc30\uce58, \uc8fc\uc81c \uc0c9\uc778\uc744 \ud1b5\ud574 \ucc45\uc744 \ucc3e\ub294 \uc9c8\uc11c\uc758 \uc5ed\uc0ac\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "ideas", "category_title": "\uc0dd\uac01\uacfc \uc9c0\uc2dd", "subcategory": "\uae30\ub85d\uacfc \uc9c0\uc2dd \uc804\ub2ec", "categories": ["ideas"], "url": "stories/dewey-decimal-books-and-shelves/index.html", "image": "../media/dewey-decimal-books-and-shelves.png", "alt": "\uc11c\uac00\uc640 \ubaa9\ub85d \uce74\ub4dc\ub97c \uc815\ub9ac\ud558\ub294 \uc0ac\uc11c, \ucc45\uc744 \ucc3e\ub294 \ub3c5\uc790\ub97c \uadf8\ub9b0 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ub4c0\uc774 \uc2ed\uc9c4\ubd84\ub958 \u2014 \ucc45\uc758 \uc790\ub9ac\ub97c \uc22b\uc790\ub85c \ucc3e\uae30\uae4c\uc9c0 1876\ub144 \ubd84\ub958\uc548\uc5d0\uc11c \uc77d\ub294 \uc8fc\uc81c\u00b7\uc790\ub9ac\u00b7\uc0c9\uc778\uc758 \uad00\uacc4 \ucd08\uae30 \uc2ed\uc9c4\ubd84\ub958\uc758 \uc22b\uc790\uc640 \uc0c1\ub300\uc801 \ubc30\uce58, \uc8fc\uc81c \uc0c9\uc778\uc744 \ud1b5\ud574 \ucc45\uc744 \ucc3e\ub294 \uc9c8\uc11c\uc758 \uc5ed\uc0ac\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uae30\ub85d\uacfc \uc9c0\uc2dd \uc804\ub2ec \uc0dd\uac01\uacfc \uc9c0\uc2dd \uc77d\uace0 \uc2f6\uc740 \ucc45\uc774 \ub3c4\uc11c\uad00\uc5d0 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8 \ucc45\uc744 \uc2e4\uc81c\ub85c \ucc3e\uc744 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub974\ub2e4. \ucc45\uc774 \ub9ce\uc544\uc9c8\uc218\ub85d \uc5b4\ub518\uac00\uc5d0 \uc788\ub2e4\ub294 \uc815\ubcf4\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud558\ub2e4. \ubb34\uc5c7\uc5d0 \uad00\ud55c \ucc45\uc778\uc9c0 \ub098\ub204\uace0 \uc5b4\ub514\uc5d0 \ub193\uc600\ub294\uc9c0 \uc5f0\uacb0\ud558\ub294 \uaddc\uce59\uc774 \ud544\uc694\ud558\ub2e4. \uba5c\ube4c \ub4c0\uc774\uac00 1876\ub144\uc5d0 \ubc1c\ud45c\ud55c \ubd84\ub958\uc548\uc740 \uc774 \ubb38\uc81c\uc5d0 \ub300\ud55c \uc911\uc694\ud55c \ud574\ubc95\uc774\uc5c8\ub2e4. \ucc45 \ub4f1\uc5d0 \ubd99\uc740 \uc22b\uc790\ub294 \uc9c0\uc2dd\uc758 \uc810\uc218\ub3c4, \uc77d\uc5b4\uc57c \ud560 \uc21c\uc11c\ub3c4 \uc544\ub2c8\ub2e4. \uc5ec\ub7ec \ucc45 \uc0ac\uc774\uc758 \uad00\uacc4\ub97c \uc815\ud558\uace0 \ucc3e\uc544\uac08 \uc790\ub9ac\ub97c \ub9cc\ub4dc\ub294 \uae30\ud638\ub2e4. \ucd08\uae30\uc758 \uc124\uba85\uc11c\ub97c \uc77d\uc73c\uba74 \uc775\uc219\ud55c \ub3c4\uc11c\uad00\uc758 \ud48d\uacbd \ub4a4\uc5d0 \uc5b4\ub5a4 \uc0dd\uac01\uacfc \ud0c0\ud611\uc774 \ub4e4\uc5b4 \uc788\ub294\uc9c0 \ubcf4\uc778\ub2e4. \uc791\uc740 \uc11c\uac00\uc5d0\uc11c\ub294 \uc5b4\ub290 \ucc45\uc774 \uc5b4\ub514\uc5d0 \uc788\ub294\uc9c0 \ub2f4\ub2f9\uc790\uac00 \uae30\uc5b5\ud560 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc790\ub8cc\uac00 \ub9ce\uc544\uc9c0\uace0 \uc0ac\ub78c\uc774 \ubc14\ub00c\uba74 \uac1c\uc778\uc758 \uae30\uc5b5\uc5d0\ub9cc \uae30\ub300\uae30 \uc5b4\ub835\ub2e4. \ucc3e\ub294 \uc0ac\ub78c\uacfc \uc815\ub9ac\ud558\ub294 \uc0ac\ub78c\uc774 \uacf5\uc720\ud560 \uc218 \uc788\ub294 \ubc29\uc2dd\uc774 \ud544\uc694\ud574\uc9c4\ub2e4. \ubd84\ub958\ub294 \uc0ac\uc11c \ud63c\uc790 \ud3b8\ud558\ub824\uace0 \ubd99\uc774\ub294 \ud45c\uc9c0\uac00 \uc544\ub2c8\ub77c \uc774\uc6a9\uc744 \uac00\ub2a5\ud558\uac8c \ud558\ub294 \uc57d\uc18d\uc774\ub2e4. \uc774 \uc57d\uc18d\uc740 \ucc45\uc744 \ubaa8\uc73c\ub294 \uc77c\uacfc \ubcc4\uac1c\uc758 \uc791\uc5c5\uc774\ub2e4. \uc7a5\uc11c\uac00 \ud48d\ubd80\ud574\ub3c4 \ucc3e\uc744 \uc218 \uc5c6\ub2e4\uba74 \uc4f8\ubaa8\ub97c \ucda9\ubd84\ud788 \ub098\ub204\uae30 \uc5b4\ub835\ub2e4. \uc9c0\uc2dd\uc744 \ubcf4\uc874\ud558\ub294 \uae30\uad00\uc740 \ubb3c\uac74\uc744 \uc624\ub798 \ub450\ub294 \ub2a5\ub825\ubfd0 \uc544\ub2c8\ub77c \uc811\uadfc\ud558\uac8c \ud558\ub294 \uc9c8\uc11c\ub3c4 \ud544\uc694\ud558\ub2e4. \ubd84\ub958\ubc95\uc740 \uadf8 \uc9c8\uc11c\ub97c \ub208\uc5d0 \ubcf4\uc774\uac8c \ub9cc\ub4e0\ub2e4. \ub4c0\uc774\uc758 \ucd08\uae30 \ubc29\uc2dd\uc740 \uc9c0\uc2dd\uc744 \ud070 \ubd80\ub958\uc640 \uadf8 \uc544\ub798\uc758 \uc138\ubd80 \ubd80\ub958\ub85c \ub098\ub204\uace0 \uc22b\uc790\ub97c \ubd80\uc5ec\ud588\ub2e4. \ud070 \ubc94\uc8fc \uc548\uc5d0\uc11c \ub2e4\uc2dc \ub098\ub204\ub294 \uad6c\uc870\ub2e4. \uc22b\uc790\uc758 \uac01 \uc790\ub9ac\ub294 \uc55e\uc758 \ubc94\uc8fc\uc640\uc758 \uad00\uacc4\ub97c \ub4dc\ub7ec\ub0b8\ub2e4. \uc0ac\uc6a9\uc790\uac00 \ubaa8\ub4e0 \ucc45\uc758 \uc81c\ubaa9\uc744 \ubab0\ub77c\ub3c4 \ube44\uc2b7\ud55c \uc8fc\uc81c\uc758 \uc790\ub8cc\ub97c \uac00\uae4c\uc774\uc5d0\uc11c \ucc3e\uc744 \uc218 \uc788\uac8c \ud55c\ub2e4. \uc22b\uc790\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ubcf4\ub2e4 \uc911\uc694\ud55c \uac83\uc740 \uac19\uc740 \uaddc\uce59\uc774 \ubc18\ubcf5\ub41c\ub2e4\ub294 \uc810\uc774\ub2e4. \uc0ac\ub78c\uc774 \ucc45\ub9c8\ub2e4 \uc81c\uba4b\ub300\ub85c \uc704\uce58\ub97c \uc815\ud558\ub294 \ub300\uc2e0 \uacf5\ud1b5\uc758 \uccb4\uacc4\uc5d0 \ub123\ub294\ub2e4. \uadf8 \uacb0\uacfc \uc0c8 \ucc45\uc774 \ub4e4\uc5b4\uc654\uc744 \ub54c\uc5d0\ub3c4 \uc5b4\ub290 \uc704\uce58\ub97c \uc904\uc9c0 \uc0dd\uac01\ud560 \uae30\uc900\uc774 \uc0dd\uae34\ub2e4. \ubd84\ub958\ub294 \ud604\uc7ac\uc758 \uc815\ub9ac\uc774\uba74\uc11c \uc55e\uc73c\ub85c \ub298\uc5b4\ub0a0 \uc790\ub8cc\ub97c \uc704\ud55c \uacc4\ud68d\uc774\ub2e4. \ucc45 \ud55c \uad8c\uc5d0 \ub2e8\uc21c\ud788 \uba87 \ubc88\uc9f8 \ubc29\uc758 \uba87 \ubc88\uc9f8 \uce78\uc774\ub77c\ub294 \uc8fc\uc18c\ub9cc \uc900\ub2e4\uba74 \uc11c\uac00\uac00 \ub298\uac70\ub098 \ucc45\uc774 \uc774\ub3d9\ud560 \ub54c \ubb38\uc81c\uac00 \uc0dd\uae34\ub2e4. \ub4c0\uc774\uc758 \ubc29\uc2dd\uc5d0\uc11c\ub294 \uc8fc\uc81c\uc758 \uad00\uacc4\uc5d0 \ub530\ub77c \uc0c1\ub300\uc801\uc778 \uc790\ub9ac\ub97c \uc815\ud55c\ub2e4\ub294 \uc0dd\uac01\uc774 \uc911\uc694\ud588\ub2e4. \ubb3c\ub9ac\uc801\uc778 \uac00\uad6c\uc640 \uc9c0\uc2dd\uc758 \ubc88\ud638\ub97c \uc644\uc804\ud788 \uac19\uc740 \uac83\uc73c\ub85c \ubcf4\uc9c0 \uc54a\ub294 \uac83\uc774\ub2e4. \uc774\ub807\uac8c \ud558\uba74 \ubd84\ub958\uc758 \uaddc\uce59\uacfc \uc2e4\uc81c \ubc30\uce58\uac00 \uc5f0\uacb0\ub418\uba74\uc11c\ub3c4 \uad6c\ubcc4\ub41c\ub2e4. \ub3c4\uc11c\uad00\uc758 \uacf5\uac04\uc774 \ubc14\ub00c\ub354\ub77c\ub3c4 \uc8fc\uc81c\uc758 \uc21c\uc11c\ub294 \uc774\uc5b4\uc9c8 \uc218 \uc788\ub2e4. \uc791\uc740 \uc22b\uc790\ud45c\uac00 \uac74\ubb3c\uc758 \uc9c8\uc11c\ubcf4\ub2e4 \uc624\ub798 \uc4f0\uc77c \uac00\ub2a5\uc131\uc774 \uc0dd\uae34\ub2e4. \uc815\ub9ac \uccb4\uacc4\uc758 \uac00\uce58\ub294 \ucc98\uc74c \uae54\ub054\ud558\uac8c \ub193\ub294 \uc21c\uac04\ubfd0 \uc544\ub2c8\ub77c \ubcc0\ud654\uc5d0 \ub300\uc751\ud558\ub294 \ub370\uc5d0\ub3c4 \uc788\ub2e4. \uc5b4\ub5a4 \uc8fc\uc81c\uc758 \ucc45\uc744 \ud55c\uacf3\uc5d0 \ubaa8\uc73c\uba74 \ud55c \uad8c\uc744 \ucc3e\uc73c\ub7ec \uc628 \uc0ac\ub78c\uc774 \uc606\uc758 \ub2e4\ub978 \ucc45\uc744 \ub9cc\ub0a0 \uc218 \uc788\ub2e4. \ubd84\ub958\ub294 \uc815\ud655\ud55c \uc81c\ubaa9\uc744 \uc544\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub9cc \ub3c4\uc6c0\uc774 \ub418\ub294 \uc7a5\uce58\uac00 \uc544\ub2c8\ub2e4. \uc544\uc9c1 \ubb34\uc5c7\uc744 \uc77d\uc744\uc9c0 \ubaa8\ub974\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub3c4 \ud0d0\uc0c9\uc758 \uae38\uc744 \uc81c\uacf5\ud55c\ub2e4. \uc11c\uac00\ub97c \ub458\ub7ec\ubcf4\ub294 \uacbd\ud5d8\uc774 \uac00\ub2a5\ud574\uc9c0\ub294 \uac83\uc774\ub2e4. \uc774\ub7f0 \uc7a5\uc810\uc740 \ucc45\uc744 \uc5b4\ub5bb\uac8c \ubb36\ub290\ub0d0\uc5d0 \ub2ec\ub824 \uc788\ub2e4. \uc8fc\uc81c\ub97c \ud568\uaed8 \ub193\uc73c\uba74 \uad00\ub828\uc131\uc774 \ubcf4\uc774\uc9c0\ub9cc \uac19\uc740 \ucc45 \uc548\uc5d0 \uc5ec\ub7ec \uc8fc\uc81c\uac00 \uc788\uc744 \ub54c\uc5d0\ub294 \uc120\ud0dd\uc774 \ud544\uc694\ud558\ub2e4. \uc5b4\ub514\uc5d0 \ub193\uc558\ub294\uc9c0\ub294 \ubb34\uc5c7\uc744 \uc911\uc2ec\uc73c\ub85c \uc77d\uc5c8\ub294\uc9c0\uc758 \ud310\ub2e8\uc774\uae30\ub3c4 \ud558\ub2e4. \ubd84\ub958\uac00 \ub2e8\uc21c\ud55c \uc22b\uc790 \ubd99\uc774\uae30 \uc774\uc0c1\uc758 \uc77c\uc778 \uc774\uc720\ub2e4. \ub4c0\uc774\uc758 \uc124\uba85\uc5d0\ub294 \ubd84\ub958\uc640 \ud568\uaed8 \uc8fc\uc81c \uc0c9\uc778\ub3c4 \uc911\uc694\ud558\uac8c \ub4f1\uc7a5\ud55c\ub2e4. \uac19\uc740 \uc790\ub8cc\ub97c \ucc3e\ub354\ub77c\ub3c4 \ub3c5\uc790\uac00 \ub5a0\uc62c\ub9ac\ub294 \ub9d0\uacfc \ubd84\ub958\ud45c\uc758 \ud45c\ud604\uc774 \ub2e4\ub97c \uc218 \uc788\ub2e4. \ub0b1\ub9d0\uc5d0\uc11c \ud574\ub2f9 \ubc94\uc8fc\ub85c \ucc3e\uc544\uac00\ub294 \uae38\uc774 \uc788\uc73c\uba74 \ubc88\ud638 \uc804\uccb4\ub97c \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4. \ubd84\ub958\uc758 \uad6c\uc870\uc640 \uc774\uc6a9\uc790\uc758 \uc9c8\ubb38\uc744 \uc5f0\uacb0\ud558\ub294 \uc7a5\uce58\ub2e4. \ucc45\uc744 \uc5b4\ub514\uc5d0 \ub193\uc744\uc9c0 \uc815\ud558\ub294 \uc77c\uacfc \uc0ac\ub78c\uc774 \uc5b4\ub5a4 \ub9d0\ub85c \ucc3e\uc744\uc9c0 \uc608\uc0c1\ud558\ub294 \uc77c\uc740 \uc11c\ub85c \ub2e4\ub974\ub2e4. \uc88b\uc740 \uc815\ub9ac \uccb4\uacc4\ub294 \ub458\uc744 \ud568\uaed8 \uace0\ub824\ud574\uc57c \ud55c\ub2e4. \uc11c\uac00\uc758 \uc21c\uc11c\ub9cc \ud569\ub9ac\uc801\uc774\uc5b4\ub3c4 \uc774\uc6a9\uc790\uac00 \uadf8 \uc21c\uc11c\ub85c \ub4e4\uc5b4\uac08 \uae38\uc744 \ubaa8\ub974\uba74 \uc5b4\ub835\ub2e4. \uc0c9\uc778\uc740 \uc9c0\uc2dd\uc758 \uccb4\uacc4\uc5d0 \uc5ec\ub7ec \uc785\uad6c\ub97c \ub9cc\ub4e4\uc5b4 \uc900\ub2e4. \uc5b4\ub5a4 \ubd84\uc57c\ub97c \ud070 \ubd80\ub958\ub85c \uc0bc\uace0 \ubb34\uc5c7\uc744 \uadf8 \uc544\ub798\uc5d0 \ub458\uc9c0\ub294 \uc790\uc5f0\uc774 \ubbf8\ub9ac \uc815\ud574 \uc900 \ub2e8 \ud558\ub098\uc758 \ub2f5\uc774 \uc544\ub2c8\ub2e4. \ub4c0\uc774\uc758 \ucd08\uae30 \ubd84\ub958\ud45c\uc5d0\ub3c4 19\uc138\uae30\uc758 \ud559\ubb38 \uad6c\ubd84\uacfc \uc6a9\uc5b4\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \ubaa8\ub4e0 \ubb38\ud654\uc640 \uc2dc\ub300\uc758 \uc9c0\uc2dd\uc774 \ub611\uac19\uc740 \ube44\uc911\uacfc \ubc29\uc2dd\uc73c\ub85c \ub2f4\uae34 \uc644\uc804\ud55c \uac70\uc6b8\uc774\ub77c\uace0 \ubcfc \uc218\ub294 \uc5c6\ub2e4. \ubd84\ub958\ubc95\uc744 \uc0ac\uc6a9\ud55c\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8 \uad6c\uc131\uc5d0 \uc9c8\ubb38\uc744 \ub358\uc9c0\ub294 \uc77c\uc740 \uc591\ub9bd\ud560 \uc218 \uc788\ub2e4. \uc0c8 \ubd84\uc57c\uac00 \uc0dd\uae30\uac70\ub098 \uae30\uc874 \ubc94\uc8fc\uc758 \ud55c\uacc4\uac00 \ub4dc\ub7ec\ub098\uba74 \uc218\uc815\uc774 \ud544\uc694\ud558\ub2e4. \uaddc\uce59\uc774 \uc720\uc6a9\ud558\ub824\uba74 \uc77c\uad00\uc131\uc774 \uc788\uc5b4\uc57c \ud558\uc9c0\ub9cc, \uc624\ub798 \uc4f4\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \uadf8 \ud310\ub2e8\uc744 \uc601\uc6d0\ud55c \uc9c4\ub9ac\ucc98\ub7fc \uace0\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub4c0\uc774\uc758 1876\ub144 \uc124\uba85\uc11c\ub97c \uc77d\uc73c\uba74 \uc22b\uc790 \ub4a4\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc758 \uc6c0\uc9c1\uc784\uc774 \ubcf4\uc778\ub2e4. \uc0c8 \ucc45\uc744 \ub193\ub294 \uc0ac\uc11c\uc640 \uc8fc\uc81c\ub97c \ub530\ub77c \ucc3e\ub294 \ub3c5\uc790, \ub0b1\ub9d0\uc5d0\uc11c \ucd9c\ubc1c\ud558\ub294 \uc774\uc6a9\uc790\uac00 \uac19\uc740 \uccb4\uacc4\uc5d0\uc11c \ub9cc\ub09c\ub2e4. \ubd84\ub958\ub294 \ucc45\uc758 \uc131\uc9c8\uc744 \uc801\ub294 \uae30\uc220\uc774\uba74\uc11c \uadf8 \ucc45\uc744 \uc774\uc6a9\ud558\ub294 \uad00\uacc4\ub97c \uc870\uc9c1\ud558\ub294 \uae30\uc220\uc774\ub2e4. \uc608\ub97c \ub4e4\uc5b4 1876\ub144 \uc124\uba85\uc11c\ub294 \uc790\uc5f0\uacfc\ud559\uacfc \uc218\ud559, \uae30\ud558\ud559\uc758 \uad00\uacc4\ub97c \uc22b\uc790 513\uc73c\ub85c \ubcf4\uc5ec \uc900\ub2e4. \uc774\uac83\uc740 \ucd08\uae30 \ubd84\ub958\uc548\uc758 \uc608\uc2dc\uc774\uba70 \uc624\ub298\uc758 \ubc88\ud638\ub97c \uadf8\ub300\ub85c \uc548\ub0b4\ud558\ub294 \ub9d0\uc740 \uc544\ub2c8\ub2e4. \uc22b\uc790\uc758 \uad6c\uccb4\uc801\uc778 \ubc30\uce58\uc5d0\ub3c4 \ud310\ubcf8\uacfc \uc218\uc815\uc758 \uc5ed\uc0ac\uac00 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \uc11c\uac00\uc758 \uc22b\uc790\ub97c \ubcfc \ub54c\uc5d0\ub294 \ubb34\uc758\ubbf8\ud55c \uc554\ud638\ubcf4\ub2e4 \uadf8 \uc0ac\uc774\uc5d0 \uc138\uc6cc\uc9c4 \uae38\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ucc45\uc774 \ub9ce\uc544\uc9c8\uc218\ub85d \ud544\uc694\ud55c \uac83\uc740 \ub354 \ud070 \uc120\ubc18\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc5b4\ub514\uc5d0\uc11c \ubb34\uc5c7\uc744 \ucc3e\uc744\uc9c0 \ud568\uaed8 \uc774\ud574\ud558\ub294 \uc57d\uc18d\uc774\uc5c8\ub2e4. \ub3c4\uc11c\uad00\uc758 \uc870\uc6a9\ud55c \uc9c8\uc11c\ub294 \uadf8\ub7f0 \uc791\uc740 \uc57d\uc18d\ub4e4\uc774 \ubc18\ubcf5\ub418\uba70 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4."}, {"id": "dictionary-quotations-and-word-histories", "title": "\uc0ac\uc804 \u2014 \ub73b\uc744 \uc815\ud558\uae30 \uc804\uc5d0 \uc6a9\ub840\ub97c \ubaa8\uc73c\ub2e4", "summary": "1900\ub144 \uc0ac\uc804\uc0ac \uac15\uc5f0\uc5d0\uc11c \uc6a9\ub840\uc640 \ucd9c\ucc98, \ub73b\uc758 \ubcc0\ud654\uc640 \ud611\uc5c5\uc774 \uc9e7\uc740 \uc815\uc758\ub85c \uc774\uc5b4\uc9c0\ub294 \uacfc\uc815\uc744 \ubd05\ub2c8\ub2e4.", "category": "ideas", "category_title": "\uc0dd\uac01\uacfc \uc9c0\uc2dd", "subcategory": "\uae30\ub85d\uacfc \uc9c0\uc2dd \uc804\ub2ec", "categories": ["ideas"], "url": "stories/dictionary-quotations-and-word-histories/index.html", "image": "../media/dictionary-quotations-and-word-histories.png", "alt": "\ucc45\uacfc \ubc1c\ucdcc \uc790\ub8cc\ub97c \ubd84\ub958\ud558\ub294 \uc0ac\uc804 \ud3b8\uc9d1\uc2e4\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uc0ac\uc804 \u2014 \ub73b\uc744 \uc815\ud558\uae30 \uc804\uc5d0 \uc6a9\ub840\ub97c \ubaa8\uc73c\ub2e4 \uba38\ub9ac\uc758 \uac15\uc5f0\uc5d0\uc11c \uc77d\ub294 \uc778\uc6a9 \uc218\uc9d1\uacfc \uc5ed\uc0ac\uc801 \ub73b\ud480\uc774 1900\ub144 \uc0ac\uc804\uc0ac \uac15\uc5f0\uc5d0\uc11c \uc6a9\ub840\uc640 \ucd9c\ucc98, \ub73b\uc758 \ubcc0\ud654\uc640 \ud611\uc5c5\uc774 \uc9e7\uc740 \uc815\uc758\ub85c \uc774\uc5b4\uc9c0\ub294 \uacfc\uc815\uc744 \ubd05\ub2c8\ub2e4. \uae30\ub85d\uacfc \uc9c0\uc2dd \uc804\ub2ec \uc0dd\uac01\uacfc \uc9c0\uc2dd \ubaa8\ub974\ub294 \ub0b1\ub9d0\uc774 \uc0dd\uae30\uba74 \uc0ac\uc804\uc744 \ucc3e\ub294\ub2e4. \uadf8\ub7f0\ub370 \uc0ac\uc804\uc758 \uc9e7\uc740 \ub73b\ud480\uc774\ub294 \ub204\uac00 \ubb34\uc5c7\uc744 \ubcf4\uace0 \uc815\ud588\uc744\uae4c. 1900\ub144 \uc81c\uc784\uc2a4 \uba38\ub9ac\uc758 \uc601\uc5b4 \uc0ac\uc804\uc0ac \uac15\uc5f0\uc744 \uc77d\uc73c\uba74, \uc815\uc758 \ud55c \uc904 \ub4a4\uc5d0 \uc624\ub79c \ub3c5\uc11c\uc640 \uc218\ub9ce\uc740 \uc778\uc6a9 \uc790\ub8cc\uac00 \ub193\uc5ec \uc788\uc5c8\uc74c\uc744 \uc54c \uc218 \uc788\ub2e4. \uc5ec\uae30\uc11c\ub294 \ud2b9\uc815 \uc5b8\uc5b4\ub97c \ubc30\uc6b0\ub294 \ubc95\ubcf4\ub2e4 \uc9c0\uc2dd\uc744 \uc218\uc9d1\ud558\uace0 \ud3b8\uc9d1\ud558\ub294 \ubc29\ubc95\uc744 \uc0b4\ud3b4\ubcf8\ub2e4. \uba38\ub9ac\uc758 \uac15\uc5f0\uc740 \uc601\uad6d \uc758\ud68c\uc5d0\uc11c \ubc95\uc548\uc5d0 \uc4f0\uc778 \ub0b1\ub9d0\uc758 \ub73b\uc744 \ubb3b\ub358 \uc77c\ud654\ub85c \uc2dc\uc791\ud55c\ub2e4. \uc0ac\uc804\uc744 \ubcf4\ub77c\ub294 \ub300\ub2f5\uc774 \ub098\uc654\uc9c0\ub9cc \uc815\uc791 \uae30\uc874 \uc0ac\uc804\uc774 \ubaa8\ub4e0 \ud604\uc2e4\uc758 \uc4f0\uc784\uc744 \ucda9\ubd84\ud788 \uc124\uba85\ud574 \uc8fc\uc9c0\ub294 \ubabb\ud588\ub2e4. \uc0ac\uc804\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ud544\uc694\ud55c \uc9c8\ubb38\uc5d0 \ub2f5\ud560 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub974\ub2e4. \uc0b4\uc544 \uc788\ub294 \uc5b8\uc5b4\ub294 \uc0c8 \uc6a9\ub3c4\uc640 \ub9e5\ub77d\uc744 \ub9cc\ub4e0\ub2e4. \ucc45 \ud55c \uad8c\uc774 \uc774\ub97c \ud55c \ubc88\uc5d0 \uc601\uc6d0\ud788 \ub2eb\uc544 \ub458 \uc218\ub294 \uc5c6\ub2e4. \uc0ac\uc804\uc744 \uad8c\uc704 \uc788\ub294 \ubb3c\uac74\uc73c\ub85c\ub9cc \ubcf4\uba74 \uadf8 \uc548\uc5d0 \ub123\uc744 \uc790\ub8cc\ub97c \uacc4\uc18d \ucc3e\uc544\uc57c \ud558\ub294 \uc791\uc5c5\uc774 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ub73b\ud480\uc774\ub294 \uc870\uc0ac\uac00 \ub05d\ub09c \uacb0\uacfc\ub77c\uae30\ubcf4\ub2e4 \ud2b9\uc815 \uc2dc\uc810\uc758 \ud3b8\uc9d1 \uacb0\uacfc\ub2e4. \uba38\ub9ac\ub294 \uc61b \ucc45\uc5d0\uc11c \uc5b4\ub824\uc6b4 \ub9d0 \uc704\ub098 \uc606\uc5d0 \ud480\uc774\ub97c \uc801\ub358 \uc8fc\uc11d\uc758 \uad00\uc2b5\ub3c4 \uc124\uba85\ud55c\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ud2b9\uc815 \ub3c5\uc790\ub97c \ub3d5\ub358 \uc9e7\uc740 \ub9d0\uc774 \ubaa8\uc5ec \ub2e4\ub978 \ub3c5\uc790\ub97c \uc704\ud55c \uc790\ub8cc\uac00 \ub420 \uc218 \uc788\uc5c8\ub2e4. \ub0b1\ub9d0\uc744 \ucc3e\ub294 \ub3c4\uad6c\ub294 \ucc98\uc74c\ubd80\ud130 \uc9c0\uae08\uc758 \uc0ac\uc804 \ubaa8\uc2b5\uc73c\ub85c\ub9cc \uc874\uc7ac\ud558\uc9c0 \uc54a\uc558\ub2e4. \uc5ec\uae30\uc11c \uc911\uc694\ud55c \ubcc0\ud654\ub294 \uc124\uba85\uc744 \uc6d0\ub798 \uae00\uc758 \uc790\ub9ac\uc5d0\uc11c \ub5bc\uc5b4 \ubaa8\uc73c\ub294 \uc77c\uc774\ub2e4. \ub3c5\uc790\uac00 \ud55c \ucc45\uc744 \uc21c\uc11c\ub300\ub85c \uc77d\ub2e4\uac00 \uc5bb\ub358 \ub3c4\uc6c0\uc744, \ud544\uc694\ud55c \ub0b1\ub9d0\uc744 \ucc3e\uc544\ubcf4\ub294 \ubc29\uc2dd\uc73c\ub85c \ubc14\uafbc\ub2e4. \uc790\ub8cc\uc758 \ubc30\uc5f4\uc774 \ub2ec\ub77c\uc9c0\uba74 \uc9c0\uc2dd\uc744 \uc774\uc6a9\ud558\ub294 \ud589\ub3d9\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc2e4\uc81c\ub85c \uc4f0\uc778 \ubb38\uc7a5\uc744 \ubaa8\uc73c\uba74 \ub0b1\ub9d0\uc758 \uc758\ubbf8\uc640 \ubb38\ub9e5\uc744 \uc0b4\ud544 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc778\uc6a9\uc744 \ub9ce\uc774 \ubd99\uc774\ub294 \uac83\ub9cc\uc73c\ub85c \ub3c5\uc790\uc758 \uc9c8\ubb38\uc774 \uc790\ub3d9\uc73c\ub85c \ud574\uacb0\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \uba38\ub9ac\ub294 \ud48d\ubd80\ud55c \uc608\ubb38\uc5d0\uc11c \ub73b\uc744 \ucd94\ub824 \uc8fc\ub294 \ud3b8\uc9d1\uc758 \ud544\uc694\ub97c \uc124\uba85\ud55c\ub2e4. \uac19\uc740 \ub9d0\ub3c4 \uc2dc\ub300\uc640 \uae00\uc758 \uc885\ub958\uc5d0 \ub530\ub77c \ub2e4\ub978 \ub73b\uc73c\ub85c \uc4f0\uc77c \uc218 \uc788\ub2e4. \ud3b8\uc9d1\uc790\ub294 \ube44\uc2b7\ud55c \uc4f0\uc784\uc744 \ubb36\uace0 \ub2e4\ub978 \uc4f0\uc784\uc744 \ub098\ub204\uc5b4\uc57c \ud55c\ub2e4. \uc778\uc6a9\ubb38\uc740 \uc7a5\uc2dd\uc774\ub098 \uad8c\uc704\ub97c \uc704\ud55c \uc774\ub984 \ubaa9\ub85d\uc774 \uc544\ub2c8\ub77c \uadf8\ub7f0 \ud310\ub2e8\uc744 \uc2dc\ud5d8\ud560 \uc790\ub8cc\uac00 \ub41c\ub2e4. \uc815\uc758\uc640 \uadfc\uac70\uac00 \uc11c\ub85c \ub9de\uc544\uc57c \ud55c\ub2e4. \uba38\ub9ac\ub294 \uc0c8\ubba4\uc5bc \uc874\uc2a8\uc758 1755\ub144 \uc0ac\uc804\uc774 \uc601\uc5b4 \uc0ac\uc804 \ud3b8\ucc2c\uc758 \uc218\uc900\uc744 \ub192\uc600\ub2e4\uace0 \ud3c9\uac00\ud558\uba74\uc11c\ub3c4, \uadf8 \ub4a4\uc5d0 \ub0a8\uc740 \uacfc\uc81c\ub97c \uc124\uba85\ud55c\ub2e4. \uc55e\uc120 \uc131\uacfc\ub97c \uc778\uc815\ud558\ub294 \uac83\uacfc \uadf8\uac83\uc744 \uc644\uc804\ud55c \ub9c8\uc9c0\ub9c9 \ub2f5\uc73c\ub85c \ubc1b\uc544\ub4e4\uc774\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uc0ac\uc804\uc758 \ubc1c\uc804\uc740 \uc774\uc804 \ucc45\uc744 \ubc84\ub9ac\uae30\ubcf4\ub2e4 \ubb34\uc5c7\uc744 \ubcf4\uc644\ud560\uc9c0 \ucc3e\ub294 \uacfc\uc815\uc774\uae30\ub3c4 \ud588\ub2e4. \uc778\uc6a9\uc744 \ubaa8\uc740 \ud3b8\ucc2c\uc790\uac00 \uc6d0\uc804\uc744 \uc9c1\uc811 \ud655\uc778\ud588\ub294\uc9c0\ub3c4 \uc911\uc694\ud55c \ubb38\uc81c\ub2e4. \ub2e4\ub978 \uc0ac\uc804\uc5d0\uc11c \uc608\ubb38\uc744 \uac00\uc838\uc624\uba74 \uc790\ub8cc\uc758 \uc624\ub958\uc640 \ud574\uc11d\uc744 \ud568\uaed8 \ubb3c\ub824\ubc1b\uc744 \uc218 \uc788\ub2e4. \uc774\ub984\ub09c \uc800\uc790\uc758 \ubb38\uc7a5\uc774 \uc2e4\ub838\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc870\uc0ac \uacfc\uc815\uae4c\uc9c0 \ubcf4\uc7a5\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc9e7\uc740 \ucd9c\ucc98 \ud45c\uc2dc\ub294 \ub3c5\uc790\uac00 \uadf8 \uadfc\uac70\ub97c \ub2e4\uc2dc \ucc3e\uc544\ubcfc \uc218 \uc788\uac8c \ud574\uc57c \ud55c\ub2e4. \uc0ac\uc804\uc758 \uad8c\uc704\ub294 \ucc45\uc758 \ub450\uaed8\uc640 \ud568\uaed8 \ud655\uc778 \uac00\ub2a5\ud55c \uc790\ub8cc\uc758 \uc5f0\uacb0\uc5d0\uc11c \ub098\uc654\ub2e4. \uc5ed\uc0ac\uc801 \uc6d0\uce59\uc744 \ub530\ub974\ub294 \uc0ac\uc804\uc740 \uc9c0\uae08 \uc4f0\ub294 \ub73b\ub9cc \uc801\ub294 \ub370\uc11c \ub354 \ub098\uc544\uac04\ub2e4. \uc5b8\uc81c \ub098\ud0c0\ub098 \uc5b4\ub5a4 \ubaa8\uc2b5\uacfc \uc758\ubbf8\ub85c \uc4f0\uc600\uace0 \ubb34\uc5c7\uc774 \ubc14\ub00c\uc5c8\ub294\uc9c0 \uc0b4\ud53c\ub824 \ud55c\ub2e4. \uba38\ub9ac\ub294 \uc774\ub97c \ub2e8\uc5b4\uc758 \uc0dd\uc560\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc791\uc5c5\uc73c\ub85c \uc124\uba85\ud588\ub2e4. \ub2e4\ub9cc \ubc1c\uacac\ud55c \uac00\uc7a5 \uc774\ub978 \uae30\ub85d\uc774 \uc2e4\uc81c\ub85c \ub204\uad70\uac00 \ucc98\uc74c \ub9d0\ud55c \uc21c\uac04\uacfc \uac19\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub0a8\uc740 \uc790\ub8cc\uc5d0\uc11c \ud655\uc778\ud55c \ucd5c\ucd08\uc640 \uc2e4\uc81c \ud0c4\uc0dd\uc740 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc0ac\uc804\uc758 \ub0a0\uc9dc\ub97c \uc77d\uc744 \ub54c\uc5d0\ub3c4 \uc99d\uac70\uc758 \ubc94\uc704\ub97c \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \ub354 \uc774\ub978 \uc790\ub8cc\uac00 \ubc1c\uacac\ub418\uba74 \uc124\uba85\uc774 \uc218\uc815\ub420 \uc218 \uc788\ub2e4. \uc774\ub7f0 \uc0ac\uc804\uc740 \ud3b8\uc9d1\uc790 \ud63c\uc790 \uc77d\uc744 \uc218 \uc788\ub294 \uc591\uc744 \ub118\uc5b4\uc11c\ub294 \ucc45\uc744 \ud544\uc694\ub85c \ud588\ub2e4. \uba38\ub9ac\uc758 \uac15\uc5f0\uc740 \uc790\uc6d0 \ub3c5\uc790\ub4e4\uc774 \uc5ec\ub7ec \uc2dc\ub300\uc758 \ucc45\uacfc \ubb38\uc11c\uc5d0\uc11c \ubc1c\ucdcc\ub97c \ubaa8\uc740 \uc791\uc5c5\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc790\ub8cc\ub97c \ucc3e\ub294 \uc77c\uacfc \uc790\ub8cc\ub97c \uc815\ub9ac\ud558\ub294 \uc77c\uc774 \ub9ce\uc740 \uc0ac\ub78c\uc758 \ud611\uc5c5\uc73c\ub85c \uc5f0\uacb0\ub418\uc5c8\ub2e4. \ucc38\uc5ec\uc790\uac00 \ub9ce\uc544\uc9c0\uba74 \uc5b4\ub5a4 \uc815\ubcf4\ub97c \ub0a8\uae38\uc9c0 \uacf5\ud1b5\uc758 \uae30\uc900\ub3c4 \uc911\uc694\ud574\uc9c4\ub2e4. \ubb38\uc7a5\uc774 \uc5b4\ub514\uc5d0\uc11c \uc654\ub294\uc9c0 \uc54c\uc544\uc57c \ub2e4\uc2dc \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \ucd9c\ucc98 \uc5c6\ub294 \uc608\ubb38\uc740 \uadf8\ub7f4\ub4ef\ud574 \ubcf4\uc5ec\ub3c4 \uc99d\uac70\uc758 \ud798\uc774 \uc57d\ud574\uc9c4\ub2e4. \uc791\uc740 \ubc1c\ucdcc \ud558\ub098\uc758 \uae30\ub85d \ubc29\uc2dd\uc774 \uac70\ub300\ud55c \uc0ac\uc804\uc758 \uc2e0\ub8b0\uc640 \uc774\uc5b4\uc9c4\ub2e4. \ucc45\uacfc \ubb38\uc11c\uc5d0\uc11c \uc6a9\ub840\ub97c \ubaa8\uc73c\uba74 \uae30\ub85d\uc73c\ub85c \ub0a8\uc740 \uc5b8\uc5b4\uac00 \uc911\uc2ec\uc774 \ub41c\ub2e4. \ub9d0\ub85c\ub9cc \uc624\uac04 \ud45c\ud604\uc774\ub098 \uae30\ub85d\ud560 \uae30\ud68c\uac00 \uc801\uc5c8\ub358 \uc0ac\ub78c\uc758 \uc5b8\uc5b4\ub294 \ub35c \ubcf4\uc77c \uc218 \uc788\ub2e4. \uc790\ub8cc\uac00 \ub9ce\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc0ac\ud68c\uc758 \ubaa8\ub4e0 \uc4f0\uc784\uc744 \uac19\uc740 \ube44\uc911\uc73c\ub85c \ub2f4\uc558\ub2e4\uace0 \ud560 \uc218\ub294 \uc5c6\ub2e4. \uc774 \ud55c\uacc4\ub97c \uc544\ub294 \uc77c\uc740 \uc0ac\uc804\uc744 \uc4f8\ubaa8\uc5c6\uac8c \ub9cc\ub4e4\uc9c0 \uc54a\ub294\ub2e4. \uc5b4\ub5a4 \uc9c8\ubb38\uc5d0 \uac15\ud558\uace0 \uc5b4\ub5a4 \ubd80\ubd84\uc740 \ub354 \ucc3e\uc544\ubcf4\uc544\uc57c \ud558\ub294\uc9c0 \uc54c\uac8c \ud55c\ub2e4. \uc798 \ub9cc\ub4e0 \uc790\ub8cc\uc9d1\ub3c4 \uc218\uc9d1 \uacbd\ub85c\uc758 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4. \uac80\uc0c9 \uacb0\uacfc\uc758 \uc591\uacfc \ub300\ud45c\uc131\uc774 \ub2e4\ub978 \ubb38\uc81c\ub77c\ub294 \uc810\uc740 \uc624\ub298\uc758 \uc815\ubcf4 \uc11c\ube44\uc2a4\uc5d0\ub3c4 \uc774\uc5b4\uc9c4\ub2e4. \uc0ac\uc804 \ud55c \ud56d\ubaa9\uc740 \uc791\uc9c0\ub9cc \uadf8 \ub4a4\uc5d0\ub294 \uc790\ub8cc\uc758 \uc218\uc9d1\uacfc \ub300\uc870, \ub73b\uc758 \uad6c\ubd84\uacfc \ubb38\uc7a5\uc758 \uc815\ub9ac\uac00 \uc788\ub2e4. \ube68\ub9ac \ucc3e\uc544\ubcfc \uc218 \uc788\ub3c4\ub85d \uc9e7\uac8c \ub9cc\ub4dc\ub294 \uc77c\uc5d0\ub294 \uc624\ud788\ub824 \uae34 \ub178\ub3d9\uc774 \ub4e4 \uc218 \uc788\ub2e4. \ub9ce\uc740 \uc815\ubcf4\ub97c \uadf8\ub300\ub85c \uc313\uc544 \ub450\ub294 \uc77c\uacfc \uc0ac\uc6a9 \uac00\ub2a5\ud55c \uc124\uba85\uc73c\ub85c \ub9cc\ub4dc\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \ub2e4\uc74c\uc5d0 \uc0ac\uc804\uc744 \ud3bc\uce60 \ub54c \ub73b\ud480\uc774 \uc544\ub798\uc758 \uc608\ubb38\uacfc \uc5f0\ub300, \ucd9c\ucc98\ub3c4 \uc0b4\ud3b4\ubcf4\uc790. \uadf8 \uc791\uc740 \ud45c\uc2dc\ub4e4\uc740 \ud3b8\uc9d1\uc790\uac00 \uc5b4\ub5a4 \uc99d\uac70\ub85c \ud310\ub2e8\ud588\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \uae38\uc774\ub2e4. \uc0ac\uc804\uc758 \uc5ed\uc0ac\ub294 \uc544\ub294 \uac83\uc744 \ub9ce\uc774 \uc801\ub294 \uc77c\ubcf4\ub2e4 \ud655\uc778\ud55c \uc4f0\uc784\uc744 \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc774\uc6a9\ud560 \uc218 \uc788\uac8c \ub9cc\ub4dc\ub294 \uc9c0\uc2dd\uc758 \uae30\uc220\uc744 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "early-cinema-magic-sword-camera-tricks", "title": "\uc601\ud654\uc758 \ub9c8\uc220 \u2014 \uce74\uba54\ub77c\ub97c \uba48\ucd94\uc790 \uc0ac\ub78c\uc774 \uc0ac\ub77c\uc84c\ub2e4", "summary": "\ucd08\uae30 \ud2b9\uc218\ud6a8\uacfc\uc758 \uba48\ucd98 \uce74\uba54\ub77c\uc640 \uacb9\uce5c \ud544\ub984\uc744 \uc2e4\uc81c \uc61b \uc601\ud654 \ub3c4\ud310\uc73c\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "ideas", "category_title": "\uc0dd\uac01\uacfc \uc9c0\uc2dd", "subcategory": "\uc608\uc220\uc744 \ubcf4\ub294 \ubc95", "categories": ["ideas"], "url": "stories/early-cinema-magic-sword-camera-tricks/index.html", "image": "../media/early-cinema-magic-sword-camera-tricks.jpg", "alt": "\ub9c8\uc220 \uac80\uc758 \uc131 \uc7a5\uba74 A\uc640 \ubcc4\ub3c4\ub85c \ucc0d\uc740 \ubc30\uc6b0 B, \uac70\uc778\uc73c\ub85c \ud569\uc131\ub41c C\ub97c \ub098\ub780\ud788 \ubcf4\uc5ec \uc8fc\ub294 \uc61b \ub3c4\ud310", "text": "\uc601\ud654\uc758 \ub9c8\uc220 \u2014 \uce74\uba54\ub77c\ub97c \uba48\ucd94\uc790 \uc0ac\ub78c\uc774 \uc0ac\ub77c\uc84c\ub2e4 \uc870\ub974\uc8fc \uba5c\ub9ac\uc5d0\uc2a4\uc640 \ub85c\ubc84\ud2b8 \ud3f4\uc758 \ud654\uba74 \ub4a4\uc5d0\ub294 \ubb34\uc5c7\uc774 \uc788\uc5c8\uc744\uae4c \ucd08\uae30 \ud2b9\uc218\ud6a8\uacfc\uc758 \uba48\ucd98 \uce74\uba54\ub77c\uc640 \uacb9\uce5c \ud544\ub984\uc744 \uc2e4\uc81c \uc61b \uc601\ud654 \ub3c4\ud310\uc73c\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc608\uc220\uc744 \ubcf4\ub294 \ubc95 \uc0dd\uac01\uacfc \uc9c0\uc2dd \uc131 \uc704\uc5d0 \uc11c \uc788\ub358 \uc0ac\ub78c\uc5d0\uac8c \uac70\uc778\uc774 \ub2e4\uac00\uc628\ub2e4. \uac70\uc778\uc758 \uba38\ub9ac\ub294 \uc131\ubcbd\ubcf4\ub2e4 \ucee4 \ubcf4\uc778\ub2e4. \uc2e4\uc81c \ubc30\uc6b0\uac00 \uadf8\ub9cc\ud07c \ucef8\uc744 \ub9ac\ub294 \uc5c6\ub2e4. \uadf8\ub807\ub2e4\uace0 \uad00\uac1d\uc774 \uc544\ubb34\uac83\ub3c4 \ubcf4\uc9c0 \uc54a\uc740 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \ucd08\uae30 \uc601\ud654\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc54c\uba74\uc11c\ub3c4 \uc990\uac81\uac8c \uc18d\uc544 \uc904 \uc218 \uc788\ub294 \uc0c8\ub85c\uc6b4 \ubb34\ub300\ub97c \ub9cc\ub4e4\uc5c8\ub2e4. \uc774 \uae00\uc740 \ud504\ub808\ub354\ub9ad A. \ud0e4\ubc97\uc758 \u300e\ud65c\ub3d9\uc0ac\uc9c4\uc740 \uc5b4\ub5bb\uac8c \ub9cc\ub4e4\uace0 \uc6c0\uc9c1\uc774\ub294\uac00\u300f \uc911 \ud2b8\ub9ad \uc601\ud654\ub97c \uc124\uba85\ud55c \uc7a5\uc744 \ub530\ub77c\uac04\ub2e4. \uc2e4\uc81c \uc61b \ucc45\uc5d0 \uc2e4\ub9b0 \u300c\ub9c8\uc220 \uac80\u300d\uc758 \uc81c\uc791 \ub3c4\ud310\uc744 \ud568\uaed8 \ubcf8\ub2e4. \ucef4\ud4e8\ud130\uac00 \uc5c6\ub358 \uc2dc\uc808\uc5d0\ub3c4 \ud654\uba74 \uc18d \ubd88\uac00\ub2a5\ud55c \uc77c\uc740 \uc815\uad50\ud558\uac8c \ub9cc\ub4e4\uc5b4\uc9c0\uace0 \uc788\uc5c8\ub2e4. \ucd08\uae30\uc758 \uce74\uba54\ub77c\ub294 \uac70\ub9ac\uc640 \uc0ac\ub78c\uc744 \uae30\ub85d\ud558\ub294 \ub3c4\uad6c\uc600\uc9c0\ub9cc, \ub208\uc55e\uc758 \ud604\uc2e4\uc744 \uadf8\ub300\ub85c \uc62e\uae30\ub294 \uc77c\uc5d0\ub9cc \uba38\ubb3c\uc9c0 \uc54a\uc558\ub2e4. \ubb34\ub300\uc758 \ub9c8\uc220\uacfc \ud76c\uadf9, \uc720\ub839 \uc774\uc57c\uae30 \uc5ed\uc2dc \uce74\uba54\ub77c \uc55e\uc73c\ub85c \ub4e4\uc5b4\uc654\ub2e4. \ud3c9\ubc94\ud55c \uac70\ub9ac\uc758 \uc6c0\uc9c1\uc784\uc774 \uc2e0\uae30\ud588\ub358 \uad00\uac1d\uc5d0\uac8c, \uac11\uc790\uae30 \uc0ac\ub77c\uc9c0\uac70\ub098 \ubaa8\uc2b5\uc744 \ubc14\uafb8\ub294 \uc0ac\ub78c\uc740 \ub610 \ub2e4\ub978 \ub180\ub77c\uc6c0\uc774\uc5c8\ub2e4. \uc911\uc694\ud55c \uc810\uc740 \uc601\ud654\uc758 \uc5ed\uc0ac\ub97c \uae30\ub85d\uc5d0\uc11c \ud658\uc0c1\uc73c\ub85c \ud55c \uc904\ub85c \ub118\uc5b4\uac04 \uc9c4\ubcf4\ucc98\ub7fc \ubcf4\uc9c0 \uc54a\ub294 \uac83\uc774\ub2e4. \uc2e4\uc81c \uc138\uacc4\ub97c \ucc0d\ub294 \uc7ac\ubbf8\uc640 \ub9cc\ub4e4\uc5b4 \ub0b8 \uc138\uacc4\ub97c \ubcf4\ub294 \uc7ac\ubbf8\ub294 \ud568\uaed8 \uc790\ub790\ub2e4. \uce74\uba54\ub77c\uc758 \ub2a5\ub825\uc744 \ud655\uc778\ud558\ub358 \uc0ac\ub78c\ub4e4\uc740 \uace7 \uadf8 \ub2a5\ub825\uc744 \ub2e4\ub974\uac8c \uc0ac\uc6a9\ud558\ub294 \ubc29\ubc95\ub3c4 \ucc3e\uc558\ub2e4. \ud504\ub791\uc2a4\uc758 \uc870\ub974\uc8fc \uba5c\ub9ac\uc5d0\uc2a4\ub294 \ubb34\ub300 \ub9c8\uc220\uc758 \uacbd\ud5d8\uacfc \uc601\ud654\ub97c \uc5f0\uacb0\ud55c \ub300\ud45c\uc801\uc778 \uc778\ubb3c\uc774\ub2e4. \ud0e4\ubc97\uc740 \uac00\uad6c\uac00 \uc6c0\uc9c1\uc774\uace0 \uc778\ubb3c\uc774 \ubc14\ub00c\uba70 \uae30\uc774\ud55c \uc874\uc7ac\ub4e4\uc774 \ub098\ud0c0\ub098\ub294 \ud654\uba74\uc744 \uc124\uba85\ud55c\ub2e4. \uad00\uac1d\uc740 \uadf8\uac83\uc774 \uc77c\uc0c1\uc758 \ubc95\uce59\uc744 \ub530\ub974\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c\uba74\uc11c\ub3c4 \ub2e4\uc74c \ubcc0\ud654\uac00 \ubb34\uc5c7\uc77c\uc9c0 \uae30\ub2e4\ub838\ub2e4. \uc774 \ud750\ub984\uc744 \ud55c \uc0ac\ub78c\uc758 \ub2e8\ub3c5 \ubc1c\uba85\uc73c\ub85c \uc815\ub9ac\ud558\uba74 \ub2f9\uc2dc\uc758 \ub2e4\uc591\ud55c \uc2dc\ub3c4\uac00 \uc0ac\ub77c\uc9c4\ub2e4. \ud0e4\ubc97\uc758 \ucc45\uc740 \uc601\uad6d\uc758 \ub85c\ubc84\ud2b8 W. \ud3f4\uc774 \ub9cc\ub4e0 \uc7a5\uba74\uacfc \uae30\ubc95\ub3c4 \uc790\uc138\ud788 \ub2e4\ub8ec\ub2e4. \uc5ec\ub7ec \uc81c\uc791\uc790\uac00 \uce74\uba54\ub77c\uc640 \uc778\uc1c4, \ubb34\ub300 \uc7a5\uce58\ub97c \ub9cc\uc9c0\uba70 \uc11c\ub85c \ub2e4\ub978 \ubd88\uac00\ub2a5\uc744 \ub9cc\ub4e4\uace0 \uc788\uc5c8\ub2e4. \uac00\uc7a5 \uc774\ud574\ud558\uae30 \uc26c\uc6b4 \ubc29\ubc95\uc740 \ucd2c\uc601\uc744 \uc7a0\uae50 \uba48\ucd94\ub294 \uac83\uc774\ub2e4. \uc0ac\ub78c\uc774 \uc11c \uc788\ub294 \uc7a5\uba74\uc744 \ucc0d\ub2e4\uac00 \uce74\uba54\ub77c\ub97c \uba48\ucd94\uace0 \ubc30\uc6b0\uac00 \ud654\uba74 \ubc16\uc73c\ub85c \ub098\uac04\ub2e4. \ubc30\uacbd\uacfc \uce74\uba54\ub77c\ub294 \uadf8\ub300\ub85c \ub450\uace0 \ub2e4\uc2dc \ucd2c\uc601\ud55c\ub2e4. \uc774\uc5b4\uc9c4 \ud544\ub984\uc744 \ubcf4\uba74 \uc0ac\ub78c\uc740 \uac78\uc5b4 \ub098\uac04 \uac83\uc774 \uc544\ub2c8\ub77c \uadf8 \uc790\ub9ac\uc5d0\uc11c \uc0ac\ub77c\uc9c4 \uac83\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uadf8 \ube48\uc790\ub9ac\uc5d0 \ub2e4\ub978 \uc0ac\ub78c\uc774\ub098 \ubb3c\uac74\uc744 \ub193\uc73c\uba74 \ubcc0\uc2e0\uc774 \ub41c\ub2e4. \ud654\uba74\uc740 \uacc4\uc18d \uc774\uc5b4\uc9c0\ub294 \uac83 \uac19\uc9c0\ub9cc \uadf8 \uc0ac\uc774\uc5d0\ub294 \ucd2c\uc601\ud558\uc9c0 \uc54a\uc740 \uc2dc\uac04\uc774 \uc228\uc5b4 \uc788\ub2e4. \uad00\uac1d\uc5d0\uac8c \uac10\ucd94\uc5b4\uc9c4 \uac83\uc740 \ube44\ubc00\uc758 \uacf5\uac04\ub9cc\uc774 \uc544\ub2c8\ub77c \ube44\ubc00\uc758 \uc2dc\uac04\uc774\ub2e4. \uc774 \uc6d0\ub9ac\ub97c \uc54c\uba74 \uc9c0\uae08\uc758 \uc601\uc0c1\uc5d0\uc11c\ub3c4 \uc7a5\uba74 \uc0ac\uc774\ub97c \uc720\uc2ec\ud788 \ubcf4\uac8c \ub41c\ub2e4. \u300c\ub9c8\uc220 \uac80\u300d\uc758 \ub3c4\ud310\uc5d0\ub294 \uc138 \uc7a5\uba74\uc774 \ub098\ub780\ud788 \ub193\uc5ec \uc788\ub2e4. \uba3c\uc800 \uc131\uacfc \ubc30\uc6b0\ub4e4\uc774 \uc788\ub294 \uc7a5\uba74\uc744 \ucd2c\uc601\ud558\uace0, \uac70\uc778 \uc5ed\ud560\uc758 \ubc30\uc6b0\ub294 \ubcc4\ub3c4\ub85c \ucc0d\uc5c8\ub2e4. \uce74\uba54\ub77c\uc5d0 \uac00\uae4c\uc774 \ub193\uc778 \ubc30\uc6b0\ub97c \ud06c\uac8c \ub2f4\uc740 \ub4a4 \ub450 \uc601\uc0c1\uc744 \uacb9\uccd0 \uc778\uc1c4\ud558\uba74 \uac70\ub300\ud55c \ubab8\uc774 \uc131 \uc704\ub85c \ub098\ud0c0\ub09c\ub2e4. \uc2e4\uc81c \uc601\ud654\uc758 \uc7a5\uba74\uc744 \ub9cc\ub4e0 \ubc29\ubc95\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc61b \uc790\ub8cc\uc774\ubbc0\ub85c, \uc5ec\uae30\uc758 \uc138 \uce78\uc740 \ud604\ub300\uc5d0 \uc0c8\ub85c \uadf8\ub9b0 \uc124\uba85\ub3c4\uac00 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\uc774 \uc11c \uc788\ub294 \uac70\ub9ac\uc640 \ud654\uba74 \uc548\uc5d0\uc11c \ubcf4\uc774\ub294 \ud06c\uae30\uac00 \ub2e4\ub974\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc774\uc6a9\ud55c \uc81c\uc791 \ud754\uc801\uc774\ub2e4. \ubab8\uc9d1\uc744 \ubc14\uafb8\uc9c0 \uc54a\uace0\ub3c4 \uce74\uba54\ub77c\uc640 \ud544\ub984\uc758 \uad00\uacc4\ub97c \ubc14\uafb8\uc5b4 \uac70\uc778\uc744 \ub9cc\ub4e0 \uac83\uc774\ub2e4. \uacb9\uccd0 \uc778\uc1c4\ud558\ub294 \ubc29\ubc95\uc740 \uc11c\ub85c \ub2e4\ub978 \uc7a5\uc18c\uc640 \uc2dc\uac04\uc5d0 \ucc0d\ud78c \uc874\uc7ac\ub97c \ud55c \ud654\uba74\uc5d0 \ub193\ub294\ub2e4. \uad00\uac1d\uc774 \ubcf4\ub294 \uacf5\uac04\uc740 \uc2e4\uc81c\ub85c \ud55c\uacf3\uc5d0 \ud568\uaed8 \uc788\ub358 \uacf5\uac04\uc774 \uc544\ub2d0 \uc218 \uc788\ub2e4. \uadf8\ub9bc\uc790\uac00 \uc788\ub294 \ubc30\uacbd\uc774\ub098 \uc5b4\ub450\uc6b4 \ubc14\ud0d5, \uc778\ubb3c\uc758 \uc704\uce58\ub97c \ub9de\ucd94\ub294 \uc791\uc5c5\uc774 \uc911\uc694\ud574\uc9c4\ub2e4. \uacb9\uce5c\ub2e4\uace0 \uc5b8\uc81c\ub098 \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \uc7a5\uba74\uc774 \ub098\uc624\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud0e4\ubc97\uc740 \u300c\uc720\ub839\uc774 \ub098\uc624\ub294 \uace8\ub3d9\ud488 \uac00\uac8c\u300d\uc5d0\uc11c \uc7a5 \uc18d\uc758 \ud574\uace8\uc744 \ubcf4\uc774\uac8c \ud558\ub294 \uc608\ub3c4 \uc124\uba85\ud55c\ub2e4. \ub530\ub85c \ucc0d\uc740 \uc874\uc7ac\uac00 \uac00\uad6c\uc758 \ub0b4\ubd80\uc5d0 \ub4e4\uc5b4\uc628 \ub4ef \ub098\ud0c0\ub09c\ub2e4. \uae30\uc220\uc758 \uc774\ub984\ub9cc \ub4e4\uc73c\uba74 \uac74\uc870\ud558\uc9c0\ub9cc, \uacb0\uacfc\ub294 \ubc29\uae08 \uc804\uae4c\uc9c0 \ube44\uc5b4 \uc788\ub358 \uacf3\uc744 \ub2e4\uc2dc \uc758\uc2ec\ud558\uac8c \ub9cc\ub4dc\ub294 \uc791\uc740 \uc720\ub839 \uc774\uc57c\uae30\ub2e4. \u300c\ub9c8\uc220 \uac80\u300d\uc5d0\ub294 \uc131\uc758 \uc778\ubb3c\ub4e4\uacfc \uc720\ub839, \ub9c8\ub140, \ub0a9\uce58\ud558\ub294 \uac70\uc778, \uc8fc\uc778\uacf5\uc744 \ub3d5\ub294 \uc694\uc815\uacfc \uc2e0\ube44\ud55c \uac80\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \uc7a5\uba74\uc774 \ubc14\ub014 \ub54c\ub9c8\ub2e4 \uc0c8\ub85c\uc6b4 \ubcc0\uc2e0\uacfc \uc704\ud5d8\uc774 \uc774\uc5b4\uc9c4\ub2e4. \uae38\uace0 \ubcf5\uc7a1\ud55c \ub300\uc0ac \uc5c6\uc774\ub3c4 \uad00\uac1d\uc774 \ub530\ub77c\uac08 \uc218 \uc788\ub294 \uc775\uc219\ud55c \ubaa8\ud5d8\uc758 \ud2c0\uc774 \ud6a8\uacfc\ub97c \ubb36\uc5b4 \uc900\ub2e4. \ud2b9\uc218\ud6a8\uacfc\ub9cc \ub530\ub85c \ub5bc\uba74 \uae30\uc220 \uc2dc\ubc94\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc, \uc774\uc57c\uae30 \uc18d\uc5d0\uc11c\ub294 \ub2e4\uc74c \uc704\uae30\uc640 \uad6c\ucd9c\uc744 \uae30\ub300\ud558\uac8c \ud558\ub294 \uc7a5\uce58\uac00 \ub41c\ub2e4. \uad00\uac1d\uc774 \uacc4\uc18d \ubcf4\uace0 \uc2f6\uc740 \uc774\uc720\ub97c \ub9cc\ub4dc\ub294 \ub370\ub294 \ud06c\uace0 \uc791\uc740 \uc11c\uc0ac\uac00 \ud544\uc694\ud588\ub2e4. \uc2e0\uae30\ud568\uacfc \uc904\uac70\ub9ac\ub294 \ucc98\uc74c\ubd80\ud130 \uc11c\ub85c \uacbd\uc7c1\ud558\uae30\ub9cc \ud55c \uac83\uc774 \uc544\ub2c8\ub77c \ud568\uaed8 \uc77c\ud588\ub2e4. \uba48\ucd98 \uce74\uba54\ub77c \ub4a4\uc5d0\ub294 \ubc30\uc6b0\uc758 \uc774\ub3d9\uacfc \uc18c\ud488 \uad50\uccb4\uac00 \uc788\uace0, \uac70\uc778\uc758 \ub4f1\uc7a5 \ub4a4\uc5d0\ub294 \ubcc4\ub3c4 \ucd2c\uc601\uacfc \uc778\uc1c4 \uc791\uc5c5\uc774 \uc788\ub2e4. \uc791\uc5c5\uc790\ub4e4\uc740 \uad00\uac1d\uc774 \ubcf4\uc9c0 \ubabb\ud558\ub294 \uc0ac\uc774\uc5d0 \uc138\uacc4\ub97c \uc815\ub3c8\ud574\uc57c \ud588\ub2e4. \uc624\ub298\uc758 \ub208\uc73c\ub85c \uc21c\ubc15\ud574 \ubcf4\uc774\ub294 \uc7a5\uba74\uc5d0\ub3c4 \uc190\uacfc \uc2dc\uac04, \uc2e4\ud328\uc640 \uc218\uc815\uc774 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \uc624\ub798\ub41c \ud6a8\uacfc\ub97c \ubcf4\uace0 \ub2e8\uc9c0 \uc9c0\uae08\uc740 \ub354 \uc9c4\uc9dc \uac19\ub2e4\uace0\ub9cc \ub9d0\ud558\uba74 \uc774 \uc990\uac70\uc6c0\uc774 \uc791\uc544\uc9c4\ub2e4. \ucd08\uae30 \uc601\ud654\ub294 \ubb34\uc5c7\uc774 \uc2e4\uc81c\uc600\ub294\uc9c0 \uc228\uae30\uba74\uc11c\ub3c4 \ubb34\uc5c7\uc744 \uc0c1\uc0c1\ud560 \uc218 \uc788\ub294\uc9c0 \ub113\ud614\ub2e4. \ub3c4\ud310\uc758 \uc131\uacfc \uac70\uc778\uc744 \ubc88\uac08\uc544 \ubcf4\uba74 \uadf8 \uc7a5\ub09c\uc2a4\ub7ec\uc6b4 \uc9c0\uc131\uc774 \ubcf4\uc778\ub2e4. \ud654\uba74 \uc18d \uac70\uc778\uc740 \uac00\uc9dc\uc600\uc9c0\ub9cc, \uadf8 \uac70\uc778\uc744 \ub9cc\ub098\uac8c \ud55c \uc0ac\ub78c\ub4e4\uc758 \uc19c\uc528\ub294 \ubd84\uba85 \uc2e4\uc81c\uc600\ub2e4."}, {"id": "encyclopedia-workshops-plates-and-editors", "title": "\ubc31\uacfc\uc804\uc11c \u2014 \uc7a5\uc778\uc758 \uc190\uae30\uc220\uc740 \uc5b4\ub5bb\uac8c \ucc45 \uc18d\uc5d0 \ub4e4\uc5b4\uc654\uc744\uae4c", "summary": "\uc7a5\uc778\uc758 \uc77c\uc744 \uae00\uacfc \uadf8\ub9bc\uc73c\ub85c \uc62e\uae30\uace0 \ud56d\ubaa9\uc744 \uc5f0\uacb0\ud558\ub294 \uacfc\uc815\uc5d0\uc11c \uc9c0\uc2dd \ud3b8\uc9d1\uc758 \ud310\ub2e8\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "ideas", "category_title": "\uc0dd\uac01\uacfc \uc9c0\uc2dd", "subcategory": "\uae30\ub85d\uacfc \uc9c0\uc2dd \uc804\ub2ec", "categories": ["ideas"], "url": "stories/encyclopedia-workshops-plates-and-editors/index.html", "image": "../media/encyclopedia-workshops-plates-and-editors.png", "alt": "\uc6d0\uace0\uc640 \uae30\uc220 \ub3c4\ud310\uc744 \uc0b4\ud53c\uba70 \uc7a5\uc778\uc5d0\uac8c \uc9c8\ubb38\ud558\ub294 \ubc31\uacfc\uc804\uc11c \ud3b8\uc9d1 \uc791\uc5c5\uc758 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\ubc31\uacfc\uc804\uc11c \u2014 \uc7a5\uc778\uc758 \uc190\uae30\uc220\uc740 \uc5b4\ub5bb\uac8c \ucc45 \uc18d\uc5d0 \ub4e4\uc5b4\uc654\uc744\uae4c \uc791\uc5c5\uc7a5 \uad00\ucc30\uacfc \ub3c4\ud310\u00b7\ucc38\uc870\u00b7\uac80\uc5f4\uc744 \ud1b5\uacfc\ud55c \uc9c0\uc2dd\uc758 \ud3b8\uc9d1 \uc7a5\uc778\uc758 \uc77c\uc744 \uae00\uacfc \uadf8\ub9bc\uc73c\ub85c \uc62e\uae30\uace0 \ud56d\ubaa9\uc744 \uc5f0\uacb0\ud558\ub294 \uacfc\uc815\uc5d0\uc11c \uc9c0\uc2dd \ud3b8\uc9d1\uc758 \ud310\ub2e8\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uae30\ub85d\uacfc \uc9c0\uc2dd \uc804\ub2ec \uc0dd\uac01\uacfc \uc9c0\uc2dd \ud070 \ubc31\uacfc\uc0ac\uc804\uc740 \uc544\ub294 \uc0ac\uc2e4\uc744 \ub9ce\uc774 \uc801\uc73c\uba74 \uc644\uc131\ub420\uae4c. 18\uc138\uae30 \ub514\ub4dc\ub85c\uc640 \ub3d9\ub8cc\ub4e4\uc774 \ub9cc\ub4e0 \u300e\ubc31\uacfc\uc804\uc11c\u300f\ub97c \ubcf4\uba74 \uc9c8\ubb38\uc740 \ub354 \ubcf5\uc7a1\ud574\uc9c4\ub2e4. \ub204\uad6c\uc758 \uc9c0\uc2dd\uc744 \ub2f4\uace0 \uc5b4\ub5bb\uac8c \uc124\uba85\ud558\uba70 \uae00\uacfc \uadf8\ub9bc\uc744 \uc5f0\uacb0\ud560\uc9c0 \uc815\ud574\uc57c \ud588\ub2e4. \uc5ec\uae30\uc11c\ub294 \ud55c \uad6d\uac00\uc758 \uc0ac\uc0c1\uac00 \uc0dd\uc560\ubcf4\ub2e4 \uc9c0\uc2dd\uc744 \ubaa8\uc544 \ud3b8\uc9d1\ud558\ub294 \uc791\uc5c5\uc758 \uc5ed\uc0ac\ub97c \uc0b4\ud3b4\ubcf8\ub2e4. \uc0ac\uc5c5\uc758 \ucd9c\ubc1c\uc5d0\ub294 \uae30\uc874 \uc601\uc5b4 \ubc31\uacfc\uc0ac\uc804\uc744 \uc62e\uae30\ub824\ub294 \uad6c\uc0c1\uc774 \uc788\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \ub514\ub4dc\ub85c\uc640 \ub2ec\ub791\ubca0\ub974\uac00 \ub9e1\uc740 \uc791\uc5c5\uc740 \ub2e8\uc21c\ud55c \ubc88\uc5ed\uc744 \ub118\uc5b4 \ub354 \ud070 \ud3b8\uc9d1 \uc0ac\uc5c5\uc73c\ub85c \ubc1c\uc804\ud588\ub2e4. \uc774\ubbf8 \uc788\ub294 \ucc45\uc758 \ub0b4\uc6a9\uc744 \uc62e\uae30\ub294 \uc77c\uacfc \uc0c8 \uc9c0\uc2dd\uc758 \uad6c\uc870\ub97c \ub9cc\ub4dc\ub294 \uc77c\uc740 \ud544\uc694\ud55c \ub178\ub3d9\uc774 \ub2e4\ub974\ub2e4. \uc0c8 \ud56d\ubaa9\uacfc \ud544\uc790, \uc790\ub8cc\ub97c \ubaa8\uc73c\ub294 \ubc29\uc2dd\ub3c4 \ub298\uc5b4\ub0ac\ub2e4. \ucc98\uc74c \uacc4\ud68d\ud55c \uaddc\ubaa8\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294 \ud504\ub85c\uc81d\ud2b8\uc5d0\uc11c \ubb34\uc5c7\uc744 \ud3ec\ud568\ud560\uc9c0 \uc815\ud558\ub294 \uc77c\uc740 \uacc4\uc18d\ub41c\ub2e4. \ubc31\uacfc\uc0ac\uc804\uc758 \ud06c\uae30\ub294 \uc885\uc774\uc758 \uc591\ubfd0 \uc544\ub2c8\ub77c \uc11c\ub85c \uc5f0\uacb0\ud574\uc57c \ud560 \uc0ac\ub78c\uacfc \uc9c0\uc2dd\uc758 \ubc94\uc704\ub97c \ub73b\ud588\ub2e4. \uc874 \ubab0\ub9ac\uc758 \ub514\ub4dc\ub85c \uc5f0\uad6c\ub294 \uadf8\uac00 \uc791\uc5c5\uc7a5\uc744 \ucc3e\uc544\uac00 \uc9c8\ubb38\ud558\uace0 \uae30\uacc4\ub97c \uc0b4\ud540 \ubaa8\uc2b5\uc744 \uc804\ud55c\ub2e4. \uc775\uc219\ud55c \ub3d9\uc791\uc740 \uadf8 \uc77c\uc744 \ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ub2f9\uc5f0\ud558\uc9c0\ub9cc \ub0af\uc120 \ub3c5\uc790\uc5d0\uac8c \uc124\uba85\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \uc190\uc73c\ub85c \ud560 \uc904 \uc544\ub294 \uac83\uacfc \ubb38\uc7a5\uc73c\ub85c \uc804\ub2ec\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uac19\uc9c0 \uc54a\ub2e4. \uae30\uacc4\ub97c \ubd84\ud574\ud558\uace0 \ub2e4\uc2dc \uc870\ub9bd\ud558\ub294 \uacfc\uc815\uc744 \ubcf4\uac70\ub098 \uc2e4\uc81c \uc77c\uc744 \uc2dc\ub3c4\ud558\uba74 \uc124\uba85\uc5d0\uc11c \ube60\uc9c4 \ub2e8\uacc4\uac00 \ub4dc\ub7ec\ub0a0 \uc218 \uc788\ub2e4. \uc7a5\uc778\uc758 \uc9c0\uc2dd\uc740 \ub2e8\uc5b4\uc758 \ubaa9\ub85d\uc73c\ub85c\ub9cc \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc21c\uc11c\uc640 \ud798\uc758 \uc870\uc808, \uc7ac\ub8cc\uc758 \ucc28\uc774\ub97c \ucc45\uc5d0 \uc62e\uae30\ub824\uba74 \uad00\ucc30\uacfc \uc9c8\ubb38\uc774 \ud544\uc694\ud588\ub2e4. \uae30\uacc4\uc640 \ub3c4\uad6c\ub97c \uae00\ub85c\ub9cc \uc124\uba85\ud558\uba74 \ubaa8\uc591\uacfc \ubd80\ud488\uc758 \uad00\uacc4\ub97c \ub530\ub77c\uac00\uae30 \uc5b4\ub835\ub2e4. \ub3c4\ud310\uc740 \ub3c5\uc790\uac00 \uad6c\uc870\uc640 \uc791\uc5c5\uc744 \ub208\uc73c\ub85c \ube44\uad50\ud560 \uc218 \uc788\uac8c \ud55c\ub2e4. \uadf8\ub9bc\uc758 \uc544\ub984\ub2e4\uc6c0\uacfc \ud568\uaed8 \ubb34\uc5c7\uc744 \uc5b4\ub514\uc5d0\uc11c \ubc14\ub77c\ubcf4\ub3c4\ub85d \ud588\ub294\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \uadf8\ub9bc\ub3c4 \ud604\uc2e4\uc744 \uadf8\ub300\ub85c \uc804\ubd80 \ub2f4\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud544\uc694\ud55c \ubd80\ubd84\uc744 \uace0\ub974\uace0 \ubc30\uc5f4\ud558\uba70 \uae00\uacfc \uc5f0\uacb0\ud574\uc57c \ud55c\ub2e4. \ud55c \uc7a5\uc758 \ub3c4\ud310\uc774 \ubcf5\uc7a1\ud55c \uc791\uc5c5\uc744 \uc774\ud574\ud558\uae30 \uc27d\uac8c \ub9cc\ub4dc\ub294 \ub3d9\uc548 \uc2e4\uc81c \uc791\uc5c5\uc7a5\uc758 \uc18c\ub9ac\uc640 \uc6c0\uc9c1\uc784\uc740 \uc0dd\ub7b5\ub41c\ub2e4. \ud3b8\uc9d1\uc740 \uc815\ubcf4\ub97c \ub354\ud558\ub294 \ub3d9\uc2dc\uc5d0 \uc5b4\ub5a4 \uac83\uc744 \uc904\uc77c\uc9c0 \uc815\ud558\ub294 \uc77c\uc774\uae30\ub3c4 \ud558\ub2e4. \uae30\uacc4\uc758 \ubd80\ud488\uc744 \ubd84\ub9ac\ud574\uc11c \ubcf4\uc5ec \uc8fc\ub294 \uadf8\ub9bc\uc740 \uc644\uc131\ub41c \ubb3c\uac74\ub9cc \ubcf8 \uc0ac\ub78c\uc5d0\uac8c \uc0c8\ub85c\uc6b4 \uc9c8\ubb38\uc744 \ub9cc\ub4e0\ub2e4. \ubb34\uc5c7\uc774 \uc5b4\ub514\uc5d0 \ub4e4\uc5b4\uac00\uace0 \uc5b4\ub5a4 \uc21c\uc11c\ub85c \uc6c0\uc9c1\uc774\ub294\uc9c0 \ubb3b\uac8c \ud55c\ub2e4. \ud55c\ud3b8 \ubd84\ub9ac\ub41c \uadf8\ub9bc\uc744 \uc2e4\uc81c\ub85c \uc870\ub9bd\ud558\uace0 \uc791\ub3d9\uc2dc\ud0a4\ub294 \ub2a5\ub825\uc740 \ub610 \ub2e4\ub978 \uacbd\ud5d8\uc744 \uc694\uad6c\ud55c\ub2e4. \uc77d\ub294 \uc9c0\uc2dd\uacfc \ub9cc\ub4dc\ub294 \uc9c0\uc2dd\uc740 \uc5f0\uacb0\ub418\uc9c0\ub9cc \uc644\uc804\ud788 \uac19\uc544\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc774 \uac04\uaca9\uc744 \uc904\uc774\ub824\uba74 \uadf8\ub9bc\uc758 \uc815\ud655\uc131\uacfc \uae00\uc758 \uc124\uba85\uc774 \uc11c\ub85c \ub9de\uc544\uc57c \ud55c\ub2e4. \uae00\uc4f4\uc774\uc640 \uadf8\ub9bc\uc744 \uc900\ube44\ud558\ub294 \uc0ac\ub78c, \uc2e4\uc81c \uc791\uc5c5\uc744 \uc544\ub294 \uc0ac\ub78c\uc774 \uc18c\ud1b5\ud560 \ud544\uc694\uac00 \uc788\ub2e4. \ubc31\uacfc\uc804\uc11c\ub97c \ud3b8\uc9d1\ud55c\ub2e4\ub294 \uac83\uc740 \uc5ec\ub7ec \uc6d0\uace0\ub97c \ud55c \uad8c\uc5d0 \ubb36\ub294 \uc77c\ubcf4\ub2e4 \uc11c\ub85c \ub2e4\ub978 \ud45c\ud604 \ubc29\uc2dd\uc758 \uad00\uacc4\ub97c \ub9de\ucd94\ub294 \uc77c\uc774\uc5c8\ub2e4. \uc815\ubcf4\uc758 \uc591\ub9cc\uc73c\ub85c \ucc45\uc758 \ud488\uc9c8\uc744 \ud3c9\uac00\ud558\uae30 \uc5b4\ub824\uc6b4 \uc774\uc720\ub2e4. \uc54c\ud30c\ubcb3 \uc21c\uc11c\ub294 \uc6d0\ud558\ub294 \ud56d\ubaa9\uc744 \ucc3e\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub418\uc9c0\ub9cc \uc9c0\uc2dd\uc758 \uad00\uacc4\uae4c\uc9c0 \ubaa8\ub450 \ubcf4\uc5ec \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub2e4\ub978 \ud56d\ubaa9\uc744 \uac00\ub9ac\ud0a4\ub294 \ucc38\uc870\uac00 \ud544\uc694\ud55c \uc774\uc720\ub2e4. \ud55c \uc124\uba85\uc744 \uc77d\ub358 \ub3c5\uc790\ub294 \ub2e4\ub978 \uc124\uba85\uc73c\ub85c \uc774\ub3d9\ud558\uba70 \uc0c8\ub85c\uc6b4 \ub9e5\ub77d\uc744 \ub9cc\ub0a0 \uc218 \uc788\ub2e4. \u300e\ubc31\uacfc\uc804\uc11c\u300f\uc758 \ucc38\uc870\ub294 \uc911\ub9bd\uc801\uc778 \uae38 \uc548\ub0b4\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ubab0\ub9ac\ub294 \ub2e4\ub978 \ud56d\ubaa9\uacfc\uc758 \uc5f0\uacb0\uc774 \ube44\ud310\uacfc \ub17c\uc7c1\uc758 \ud6a8\uacfc\ub97c \ub0b3\uc744 \uc218 \uc788\uc74c\uc744 \uc124\uba85\ud55c\ub2e4. \uc5b4\ub5a4 \uae00\uc744 \ubb34\uc5c7\uacfc \ud568\uaed8 \uc77d\uac8c \ud558\ub294\uc9c0\uc5d0 \ub530\ub77c \ub3c5\uc790\uc758 \ud310\ub2e8\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc5f0\uacb0\uc758 \uc124\uacc4\uac00 \uc0ac\uc0c1\uc758 \uc804\ub2ec \ubc29\uc2dd\uc774 \ub41c \uac83\uc774\ub2e4. \ucc45\uc5d0\ub294 \ud544\uc790\uc640 \ud3b8\uc9d1\uc790\ubfd0 \uc544\ub2c8\ub77c \ucd9c\ud310\uc5c5\uc790\uc640 \uad6c\ub3c5\uc790\uac00 \ud544\uc694\ud588\ub2e4. \uac80\uc5f4\uacfc \uc815\uce58\uc801 \uc555\ubc15\ub3c4 \uc0ac\uc5c5\uc758 \uc9c0\uc18d\uc744 \uc704\ud611\ud588\ub2e4. 1751\ub144 \uccab \uad8c\uc774 \ub098\uc628 \ub4a4 \uc791\uc5c5\uc740 \ub2e8\uc21c\ud558\uac8c \uc21c\uc11c\ub300\ub85c \uc9c4\ud589\ub418\uc9c0 \uc54a\uc558\ub2e4. \uc9c0\uc2dd\uc744 \ubaa8\uc73c\ub294 \uc77c\uacfc \uadf8\uac83\uc744 \uacf5\uac1c\ud560 \uc218 \uc788\ub294 \uc870\uac74\uc774 \uc5bd\ud600 \uc788\uc5c8\ub2e4. \uc5ec\ub7ec \ud574\uc5d0 \uac78\uccd0 \uae00\uacfc \ub3c4\ud310\uc774 \uc900\ube44\ub418\uba74 \ud55c \ubc88\uc758 \uae08\uc9c0\ub098 \uc790\ub8cc \uc555\uc218\ub3c4 \ud070 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\ub2e4. \uc644\uc131\ub41c \uc804\uc9d1\uc744 \uc11c\uac00\uc5d0\uc11c \ubcf4\uba74 \uc774 \ubd88\ud655\uc2e4\ud55c \uacfc\uc815\uc774 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ucc45\uc758 \uc874\uc7ac\ub97c \ub2f9\uc5f0\ud55c \uacb0\uacfc\ub85c \uc0dd\uac01\ud558\uc9c0 \uc54a\uc544\uc57c \uc81c\uc791\uc758 \uc5ed\uc0ac\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \ubab0\ub9ac\ub294 \ucd9c\ud310\uc5c5\uc790 \ub974 \ube0c\ub974\ud1b5\uc774 \uc77c\ubd80 \ub0b4\uc6a9\uc744 \uc784\uc758\ub85c \uc190\ub304 \uc0ac\uac74\uc744 \uc804\ud55c\ub2e4. \ub514\ub4dc\ub85c\uac00 \uacaa\uc740 \ubd84\ub178\ub294 \uae00\uc744 \uc4f0\ub294 \uc0ac\ub78c\uacfc \ucd9c\ud310\uc744 \ud1b5\uc81c\ud558\ub294 \uc0ac\ub78c\uc758 \uad8c\ud55c\uc774 \uac19\uc9c0 \uc54a\uc558\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ud3b8\uc9d1\uc5d0 \ucc38\uc5ec\ud588\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ucd5c\uc885 \uc778\uc1c4\ubb3c\uc758 \ubaa8\ub4e0 \uacb0\uc815\uad8c\uc774 \uc8fc\uc5b4\uc9c0\uc9c0\ub294 \uc54a\uc558\ub2e4. \ub530\ub77c\uc11c \ud55c \ucc45\uc758 \ubaa9\uc18c\ub9ac\ub97c \uc800\uc790 \ud55c \uc0ac\ub78c\uc758 \ub73b\uc73c\ub85c\ub9cc \uc124\uba85\ud558\uae30 \uc5b4\ub835\ub2e4. \ud544\uc790\uc640 \ud3b8\uc9d1\uc790, \uac80\uc5f4\uc790\uc640 \ucd9c\ud310\uc5c5\uc790\uc758 \ud310\ub2e8\uc774 \uacb0\uacfc\uc5d0 \ud754\uc801\uc744 \ub0a8\uae34\ub2e4. \uc6b0\ub9ac\uac00 \uc77d\ub294 \ucc45\uc740 \uc9c0\uc2dd\uc758 \uc800\uc7a5\uace0\uc774\uba74\uc11c \uadf8 \uc9c0\uc2dd\uc774 \ud1b5\uacfc\ud55c \uad00\uacc4\uc758 \uacb0\uacfc\uc774\uae30\ub3c4 \ud558\ub2e4. \u300e\ubc31\uacfc\uc804\uc11c\u300f\uc758 \uc758\uc758\uc5d0\ub294 \uc7a5\uc778\uc758 \uae30\uc220\uacfc \uc81c\uc870 \uacfc\uc815\uc744 \uc911\uc694\ud55c \uc124\uba85 \ub300\uc0c1\uc73c\ub85c \uc0bc\uc558\ub2e4\ub294 \uc810\uc774 \uc788\ub2e4. \uc190\uc73c\ub85c \ub9cc\ub4dc\ub294 \uc77c\uc744 \uae00\uc744 \uc77d\ub294 \uc9c0\uc2dd\uacfc \ub5a8\uc5b4\uc9c4 \ub0ae\uc740 \uc601\uc5ed\uc73c\ub85c\ub9cc \ub450\uc9c0 \uc54a\uc73c\ub824 \ud588\ub2e4. \ub2e4\ub9cc \uc2e4\uc81c\ub85c \uc77c\ud55c \ubaa8\ub4e0 \uc7a5\uc778\uc758 \ubaa9\uc18c\ub9ac\uac00 \uac19\uc740 \ube44\uc911\uc73c\ub85c \ub0a8\uc558\ub2e4\uace0 \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uc624\ub298 \uc9c0\uc2dd \uc11c\ube44\uc2a4\ub97c \ub9cc\ub4e4 \ub54c\uc5d0\ub3c4 \ubb34\uc5c7\uc744 \ud3ec\ud568\ud558\uace0 \ub204\uac00 \uc124\uba85\ud560\uc9c0 \uacb0\uc815\ud55c\ub2e4. \uac80\uc0c9\uacfc \ucc38\uc870, \uc774\ubbf8\uc9c0\uc758 \uc120\ud0dd\ub3c4 \ub3c5\uc790\uac00 \uc774\ud574\ud558\ub294 \uacbd\ub85c\ub97c \ub9cc\ub4e0\ub2e4. \ubc31\uacfc\uc804\uc11c\uc758 \uc5ed\uc0ac\ub294 \ub9ce\uc740 \uc815\ubcf4\ub97c \ub2f4\ub294 \uc77c\uacfc \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc9c0\uc2dd\uc744 \uc804\ud558\ub294 \uc77c\uc774 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4."}, {"id": "epictetus-what-is-up-to-us", "title": "\uc5d0\ud53d\ud14c\ud1a0\uc2a4 \u2014 \ub0b4\uac8c \ub2ec\ub9b0 \uc77c\uacfc \ub2ec\ub9ac\uc9c0 \uc54a\uc740 \uc77c", "summary": "\uacb0\uacfc\ub97c \ubaa8\ub450 \uc9c0\ubc30\ud558\ub824\ub294 \ub9c8\uc74c\uacfc \uc790\uc2e0\uc758 \ud310\ub2e8\uc744 \ub3cc\uc544\ubcf4\ub294 \ud0dc\ub3c4\ub97c \uace0\ub300 \ucca0\ud559\uc758 \ubb38\uc7a5\uc73c\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "ideas", "category_title": "\uc0dd\uac01\uacfc \uc9c0\uc2dd", "subcategory": "\ucca0\ud559\uc758 \uc9c8\ubb38", "categories": ["ideas"], "url": "stories/epictetus-what-is-up-to-us/index.html", "image": "../media/epictetus-what-is-up-to-us.png", "alt": "\ub3cc\uae30\ub465 \uadf8\ub298 \uc544\ub798\uc5d0\uc11c \uace0\ub300\uc758 \uc2a4\uc2b9\uacfc \uc131\uc778 \uc81c\uc790\uac00 \ubc14\ub78c\uc774 \ubd80\ub294 \ubc14\ub2e4\ub97c \uacc1\uc5d0 \ub450\uace0 \ub300\ud654\ud558\ub294 \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\uc5d0\ud53d\ud14c\ud1a0\uc2a4 \u2014 \ub0b4\uac8c \ub2ec\ub9b0 \uc77c\uacfc \ub2ec\ub9ac\uc9c0 \uc54a\uc740 \uc77c \uc5e5\ucf00\uc774\ub9ac\ub514\uc628\uc758 \uccab \uad6c\ubd84\uc744 \uc77c\uc0c1\uc5d0\uc11c \uc77d\uae30 \uacb0\uacfc\ub97c \ubaa8\ub450 \uc9c0\ubc30\ud558\ub824\ub294 \ub9c8\uc74c\uacfc \uc790\uc2e0\uc758 \ud310\ub2e8\uc744 \ub3cc\uc544\ubcf4\ub294 \ud0dc\ub3c4\ub97c \uace0\ub300 \ucca0\ud559\uc758 \ubb38\uc7a5\uc73c\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \ucca0\ud559\uc758 \uc9c8\ubb38 \uc0dd\uac01\uacfc \uc9c0\uc2dd \uc911\uc694\ud55c \ub2f5\uc7a5\uc744 \uae30\ub2e4\ub9b4 \ub54c \uc6b0\ub9ac\ub294 \ud654\uba74\uc744 \uba87 \ubc88\uc774\ub098 \ub2e4\uc2dc \ubcfc\uae4c. \ube68\ub9ac \ud655\uc778\ud55c\ub2e4\uace0 \uc0c1\ub300\uc758 \uacb0\uc815\uc774 \ub2ec\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc \uae30\ub2e4\ub9ac\ub294 \ub9c8\uc74c\uc740 \uc790\uafb8 \uc190\uc744 \uc6c0\uc9c1\uc774\uac8c \ud55c\ub2e4. \uc5d0\ud53d\ud14c\ud1a0\uc2a4\uc758 \ucca0\ud559\uc740 \uc774\ub7f0 \uc21c\uac04\uc5d0 \uc9c8\ubb38 \ud558\ub098\ub97c \ub193\ub294\ub2e4. \uc9c0\uae08\uc758 \uc77c \uac00\uc6b4\ub370 \ubb34\uc5c7\uc774 \ub098\uc5d0\uac8c \ub2ec\ub824 \uc788\ub294\uac00. \u300e\uc5e5\ucf00\uc774\ub9ac\ub514\uc628\u300f\uc740 \uadf8\uc758 \uac00\ub974\uce68\uc744 \uc544\ub9ac\uc544\ub178\uc2a4\uac00 \uc815\ub9ac\ud55c \uc9e7\uc740 \uae38\uc7a1\uc774\ub2e4. \ud55c \uad6c\uc808\ub9cc \ub5bc\uba74 \ub9c8\uc74c\uc744 \ud3b8\ud558\uac8c \ud558\ub294 \uaca9\uc5b8\uc9d1\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc, \uc6d0\ubb38\uc740 \ud310\ub2e8\uacfc \uc695\ub9dd, \ud0c0\uc778\uacfc\uc758 \uad00\uacc4\ub97c \uc5b4\ub5bb\uac8c \ub2e4\ub8f0\uc9c0 \uc5f0\uc2b5\ud558\ub3c4\ub85d \uc694\uad6c\ud55c\ub2e4. \uac00\ubccd\uac8c \uc77d\ud788\uba74\uc11c\ub3c4 \uc27d\uac8c \ub05d\ub098\uc9c0\ub294 \uc54a\ub294 \ucc45\uc774\ub2e4. \ucc45\uc758 \uc2dc\uc791\uc740 \uc6b0\ub9ac\uc5d0\uac8c \ub2ec\ub9b0 \uac83\uacfc \uadf8\ub807\uc9c0 \uc54a\uc740 \uac83\uc744 \uad6c\ubd84\ud55c\ub2e4. \uc758\uacac\uacfc \uc758\ub3c4, \ubc14\ub78c\uacfc \ud68c\ud53c \uac19\uc740 \uc790\uc2e0\uc758 \ubc18\uc751\uc744 \ud55c\ucabd\uc5d0 \ub193\uace0, \uc7ac\uc0b0\uacfc \ud3c9\ud310, \uc9c0\uc704 \ub4f1\uc740 \ub2e4\ub978 \ucabd\uc5d0 \ub193\ub294\ub2e4. \ubab8\uc758 \uc0c1\ud0dc\ub3c4 \ubaa8\ub4e0 \uba74\uc5d0\uc11c \ub73b\ub300\ub85c \ud560 \uc218 \uc788\ub294 \uac83\uc73c\ub85c \ubcf4\uc9c0 \uc54a\ub294\ub2e4. \uc774 \uad6c\ubd84\uc744 \ub0b4\uac00 \uc544\ubb34 \uc601\ud5a5\ub3c4 \uc904 \uc218 \uc5c6\ub294 \uc77c\uacfc \ubb34\uc5c7\uc774\ub4e0 \uc644\uc804\ud788 \uc9c0\ubc30\ud560 \uc218 \uc788\ub294 \uc77c\uc774\ub77c\ub294 \ub2e8\uc21c\ud55c \ubaa9\ub85d\uc73c\ub85c \uc77d\uc9c0\ub294 \ub9d0\uc790. \uc6d0\ubb38\uc740 \ubc14\uae65\uc758 \uacb0\uacfc\uc5d0 \uc790\uae30 \uc790\uc720\ub97c \uc804\ubd80 \ub9e1\uae30\ub294 \ud0dc\ub3c4\ub97c \uacbd\uacc4\ud55c\ub2e4. \ud589\ub3d9\uc744 \uc120\ud0dd\ud560 \uc218 \uc788\ub2e4\ub294 \uac83\uacfc \uadf8 \ud589\ub3d9\uc758 \uacb0\uacfc\uac00 \ubc18\ub4dc\uc2dc \uc6d0\ud558\ub294 \ub300\ub85c \ub41c\ub2e4\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \ubc1c\ud45c\ub97c \uc900\ube44\ud558\ub294 \uc0ac\ub78c\uc744 \uc0dd\uac01\ud574 \ubcf4\uc790. \ub0b4\uc6a9\uc744 \ud655\uc778\ud558\uace0 \uc5f0\uc2b5\ud558\ub294 \uc77c\uc5d0\ub294 \uc790\uc2e0\uc774 \ud560 \uc218 \uc788\ub294 \ubaab\uc774 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ubaa8\ub4e0 \uccad\uc911\uc758 \ud45c\uc815\uacfc \ud3c9\uac00\uae4c\uc9c0 \uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc88b\uc740 \uacb0\uacfc\ub97c \uc6d0\ud558\ub354\ub77c\ub3c4 \ub2e4\ub978 \uc0ac\ub78c\uc758 \ud310\ub2e8\uc744 \ub0b4 \ubb3c\uac74\ucc98\ub7fc \uc18c\uc720\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc774 \uc0ac\ub840\ub294 \uace0\ub300 \ucc45 \uc18d \uc7a5\uba74\uc744 \uadf8\ub300\ub85c \uc62e\uae34 \uac83\uc774 \uc544\ub2c8\ub77c \uad6c\ubd84\uc744 \ud604\uc7ac\uc758 \uc0dd\ud65c\uc5d0 \uc5f0\uacb0\ud55c \uc608\ub2e4. \uacb0\uacfc\ub97c \uc911\uc694\ud558\uac8c \uc5ec\uae30\uc9c0 \ub9d0\ub77c\ub294 \ub73b\ubcf4\ub2e4, \uc790\uc2e0\uc758 \uc900\ube44\uc640 \ud0c0\uc778\uc758 \ubc18\uc751\uc744 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ub2e4\ub8e8\uc9c0 \ub9d0\uc790\ub294 \uc0dd\uac01\uc73c\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \ub0b4\uac00 \ud560 \uc218 \uc788\ub294 \uc77c\uc744 \uc54c\uc544\uc57c \uadf8\ucabd\uc5d0 \ud798\uc744 \uc4f8 \uc218 \uc788\ub2e4. \ucc45\uc5d0\ub294 \uc0ac\ub78c\uc744 \ud754\ub4dc\ub294 \uac83\uc774 \uc0ac\ubb3c \uc790\uccb4\ubfd0 \uc544\ub2c8\ub77c \uadf8\uac83\uc744 \ubc14\ub77c\ubcf4\ub294 \ud310\ub2e8\uacfc \uad00\ub828\ub41c\ub2e4\ub294 \uac00\ub974\uce68\uc774 \ub098\uc628\ub2e4. \ub204\uad70\uac00 \ub2f5\uc7a5\uc744 \ub2a6\uac8c \ud558\uba74 \uc2e4\uc81c\ub85c \ud655\uc778\ud55c \uac83\uc740 \ub2f5\uc7a5\uc774 \uc544\uc9c1 \uc5c6\ub2e4\ub294 \uc0ac\uc2e4\uc774\ub2e4. \ub098\ub97c \ubb34\uc2dc\ud55c\ub2e4\ub294 \ud574\uc11d\uc740 \uadf8 \uc704\uc5d0 \ub354\ud55c \ud310\ub2e8\uc77c \uc218 \uc788\ub2e4. \ud574\uc11d\uc774 \uc5b8\uc81c\ub098 \ud2c0\ub9ac\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \ud655\uc778\ud55c \uc77c\uacfc \ucd94\uce21\ud55c \ub73b\uc744 \uc7a0\uae50 \ub098\ub204\uba74 \ub2e4\ub978 \uac00\ub2a5\uc131\uc744 \ubcfc \uc5ec\uc9c0\uac00 \uc0dd\uae34\ub2e4. \uc0c1\ub300\uac00 \ubc14\uc05c\uc9c0, \ub0b4\uc6a9\uc744 \uc54c\uc544\ubcf4\ub294 \uc911\uc778\uc9c0 \uc544\uc9c1 \ubaa8\ub97c \uc218 \uc788\ub2e4. \ucca0\ud559\uc758 \uad6c\ubd84\uc774 \uc77c\uc0c1\uc758 \ubb38\uc7a5 \ud558\ub098\ub97c \ucc9c\ucc9c\ud788 \uc77d\ub294 \uc77c\ub85c \uc774\uc5b4\uc9c0\ub294 \ub300\ubaa9\uc774\ub2e4. \uc5d0\ud53d\ud14c\ud1a0\uc2a4\uc758 \ubb38\uc7a5\uc5d0\ub294 \uc624\ub298\uc758 \ub3c5\uc790\uc5d0\uac8c \ub9e4\uc6b0 \uc5c4\uaca9\ud558\uac8c \ub4e4\ub9ac\ub294 \ubd80\ubd84\ub3c4 \uc788\ub2e4. \uc0c1\uc2e4\uacfc \uc9c8\ubcd1 \uc55e\uc5d0\uc11c \uc790\uc2e0\uc758 \ud310\ub2e8\uc744 \ub2e4\ub8e8\ub77c\ub294 \ub9d0\uc774 \uace7 \uace0\ud1b5\uc740 \ub2f9\uc0ac\uc790\uc758 \uc798\ubabb\uc774\ub77c\ub294 \ub73b\uc774 \ub418\uc5b4\uc11c\ub294 \uace4\ub780\ud558\ub2e4. \uc678\ubd80\uc758 \ud53c\ud574\uc640 \uc0ac\ud68c\uc801 \uc870\uac74\uc740 \uc2e4\uc81c\ub85c \uc0ac\ub78c\uc744 \ub2e4\uce58\uac8c \ud55c\ub2e4. \ub530\ub77c\uc11c \uc774 \uae00\uc5d0\uc11c\ub294 \uace0\ub300\uc758 \uac00\ub974\uce68\uc744 \ud604\ub300\uc758 \uce58\ub8cc\ub098 \uc2ec\ub9ac \uc0c1\ub2f4\uc744 \ub300\uc2e0\ud558\ub294 \ucc98\ubc29\uc73c\ub85c \uc81c\uc2dc\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc790\uc2e0\uc774 \ub367\ubd99\uc778 \ud574\uc11d\uc744 \uc0b4\ud53c\ub294 \uc77c\uc740 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\uc9c0\ub9cc \ud544\uc694\ud55c \ubcf4\ud638\uc640 \uc9c0\uc6d0, \uce58\ub8cc\ub97c \ubc1b\ub294 \uc77c\uacfc \uacbd\uc7c1\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ucca0\ud559\uc744 \uc77d\ub294 \uc77c\uc5d0\ub3c4 \uc801\uc6a9\ud560 \ubc94\uc704\ub97c \uc0dd\uac01\ud558\ub294 \ud310\ub2e8\uc774 \ud544\uc694\ud558\ub2e4. \uce6d\ucc2c\uc744 \ubc1b\ub294 \uac83\uc744 \uc720\uc77c\ud55c \uc131\uacf5\uc758 \uae30\uc900\uc73c\ub85c \uc0bc\uc73c\uba74 \uadf8 \uae30\uc900\uc758 \uc5f4\uc1e0\ub97c \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ub9e1\uae30\uac8c \ub41c\ub2e4. \uc6d0\ubb38\uc740 \uc774\ub807\uac8c \ud1b5\uc81c\ud558\uae30 \uc5b4\ub824\uc6b4 \ub300\uc0c1\uc744 \ubc18\ub4dc\uc2dc \uc5bb\uc5b4\uc57c \ud560 \uac83\uc73c\ub85c \ub9cc\ub4e4 \ub54c \uc0dd\uae30\ub294 \ud754\ub4e4\ub9bc\uc744 \uc9da\ub294\ub2e4. \ubc14\ub77c\ub294 \ub300\uc0c1\uc758 \uc131\uaca9\uc744 \uc0b4\ud3b4\ubcf4\ub77c\ub294 \uc694\uad6c\ub2e4. \uc6b0\ub9ac\ub294 \ud0c0\uc778\uc758 \uc778\uc815\uc744 \uc804\ud600 \uc6d0\ud558\uc9c0 \uc54a\ub294 \uc0ac\ub78c\uc774 \ub420 \ud544\uc694\uae4c\uc9c0\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uc5b4\ub5a4 \ub0a0\uc758 \ubc18\uc751 \ud558\ub098\uac00 \uc790\uae30 \uc0b6 \uc804\uccb4\uc758 \uac00\uce58\ub97c \uacb0\uc815\ud558\ub3c4\ub85d \ub193\uace0 \uc788\uc9c0\ub294 \uc54a\uc740\uc9c0 \ubb3c\uc744 \uc218 \uc788\ub2e4. \ud070 \uc695\ub9dd\uc744 \uc5c6\uc560\uaca0\ub2e4\ub294 \uc120\uc5b8\ubcf4\ub2e4 \ubb34\uc5c7\uc744 \ub098\uc758 \uae30\uc900\uc73c\ub85c \uc0bc\ub294\uc9c0 \uad6c\uccb4\uc801\uc73c\ub85c \ud655\uc778\ud558\ub294 \ud3b8\uc774 \uac00\uae4c\uc6b4 \ucd9c\ubc1c\uc810\uc774\ub2e4. \uc774 \ucc45\uc740 \uac1c\uc778\uc758 \ub9c8\uc74c\ub9cc \uc774\uc57c\uae30\ud558\uc9c0 \uc54a\ub294\ub2e4. \uac00\uc871\uacfc \uc774\uc6c3\uc744 \ub300\ud558\ub294 \uc5ed\ud560\uacfc \ud0dc\ub3c4\ub3c4 \ub2e4\ub8ec\ub2e4. \ubc14\uae65\uc77c\uc744 \ubaa8\ub450 \ub0b4\uac8c \ub2ec\ub9ac\uc9c0 \uc54a\uc740 \uac83\uc73c\ub85c \ubd84\ub958\ud558\uace0 \uc544\ubb34 \ucc45\uc784\ub3c4 \uc9c0\uc9c0 \uc54a\ub294\ub2e4\uba74 \uad00\uacc4 \uc18d \ud589\ub3d9\uc744 \ub3cc\uc544\ubcf4\ub77c\ub294 \uc694\uad6c\uac00 \uc0ac\ub77c\uc838 \ubc84\ub9b0\ub2e4. \uc0c1\ub300\uc758 \ubc18\uc751\uc744 \uac15\uc81c\ub85c \uc815\ud560 \uc218 \uc5c6\ub2e4\ub294 \uc810\uacfc \ub0b4\uac00 \uc5b4\ub5a4 \ub9d0\uc744 \ud558\uace0 \uc5b4\ub5a4 \uc57d\uc18d\uc744 \uc9c0\ud0ac\uc9c0\ub294 \uad6c\ubd84\ud560 \uc218 \uc788\ub2e4. \ubaa8\ub4e0 \uacb0\uacfc\ub97c \uc7a5\uc545\ud558\uc9c0 \ubabb\ud574\ub3c4 \ud589\ub3d9\uc758 \ucc45\uc784\uc740 \ub0a8\ub294\ub2e4. \uace0\uc694\ud55c \ub9c8\uc74c\uc744 \uac16\ub294 \uc77c\uacfc \ud0c0\uc778\uc758 \uc5b4\ub824\uc6c0\uc744 \uc678\uba74\ud558\ub294 \uc77c\uc744 \uac19\uc740 \uac83\uc73c\ub85c \ub9cc\ub4e4\uc9c0 \uc54a\ub294 \uc77d\uae30\uac00 \ud544\uc694\ud558\ub2e4. \u300e\uc5e5\ucf00\uc774\ub9ac\ub514\uc628\u300f\uc740 \uc9e7\uc740 \ud56d\ubaa9\uc774 \uc774\uc5b4\uc838 \ube68\ub9ac \uc77d\uc744 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ubb38\uc7a5\uc744 \ub9ce\uc774 \uc678\uc6b0\ub294 \uac83\uacfc \uc2e4\uc81c \uc0c1\ud669\uc5d0\uc11c \uad6c\ubcc4\ud558\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uc5b4\ub5a4 \uc0ac\uac74\uc744 \ub5a0\uc62c\ub9ac\uace0 \uc0ac\uc2e4\uacfc \ud574\uc11d, \uc120\ud0dd\uacfc \uacb0\uacfc\ub97c \ub530\ub85c \uc801\uc5b4 \ubcf4\uba74 \ud55c \ud56d\ubaa9\uc5d0\uc11c\ub3c4 \uc624\ub798 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc11c\ub85c \ubaa8\uc21c\ub418\ub294 \ub4ef\ud55c \uac10\uc815\uc774 \uc788\ub2e4\uace0 \uace7 \uc2e4\ud328\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ubd88\uc548\uc774 \uc0dd\uae34 \uc21c\uac04 \uadf8\uac83\uc744 \uc54c\uc544\ucc28\ub9ac\uace0 \ub2e4\uc2dc \ud310\ub2e8\ud560 \uc5ec\uc9c0\ub3c4 \uc788\ub2e4. \uc774 \ud574\uc11d\uc740 \ub9c8\uc74c\uc774 \uc5b8\uc81c\ub098 \uc644\uc804\ud788 \uba85\ub839\uc744 \ub530\ub978\ub2e4\ub294 \uc8fc\uc7a5\ubcf4\ub2e4, \uc790\uae30 \ubc18\uc751\uc744 \ub3cc\uc544\ubcf4\ub294 \uc5f0\uc2b5\uc5d0 \ucd08\uc810\uc744 \ub9de\ucd98\ub2e4. \uc26c\uc6b4 \ud45c\uc5b4\ub97c \ub9cc\ub4dc\ub294 \ub300\uc2e0 \uc5b4\ub824\uc6b4 \uc21c\uac04\uc5d0 \uc0ac\uc6a9\ud560 \uc9c8\ubb38\uc744 \ub0a8\uae30\ub294 \uc148\uc774\ub2e4. \uae30\ub2e4\ub9ac\ub358 \ub2f5\uc740 \uc5ec\uc804\ud788 \uc624\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uadf8\ub798\ub3c4 \ud544\uc694\ud55c \ub0b4\uc6a9\uc744 \ub354 \ud655\uc778\ud558\uac70\ub098, \ud574\uc57c \ud560 \ub2e4\ub978 \uc77c\uc744 \uc2dc\uc791\ud558\uac70\ub098, \uc801\uc808\ud55c \ub54c \ub2e4\uc2dc \ubb38\uc758\ud560 \uc218\ub294 \uc788\ub2e4. \uacb0\uacfc\ub97c \ubaa8\ub450 \uc18c\uc720\ud558\uc9c0 \uc54a\uc544\ub3c4 \ud589\ub3d9\ud560 \uc790\ub9ac\ub294 \ub0a8\ub294\ub2e4. \uccab \ubb38\uc7a5\uc758 \uad6c\ubd84\uc740 \uadf8 \uc790\ub9ac\ub97c \ucc3e\uac8c \ud55c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \uace0\ub300\uc758 \uc2a4\uc2b9\uacfc \uc81c\uc790\uac00 \ub300\ud654\ud558\ub294 \ubd84\uc704\uae30\ub97c \uc0c1\uc0c1\ud55c AI \uc0bd\ud654\ub2e4. \uc5d0\ud53d\ud14c\ud1a0\uc2a4\uc758 \uc2e4\uc81c \uc5bc\uad74\uc774\ub098 \uae30\ub85d\ub41c \ud55c \uc7a5\uba74\uc744 \ubcf5\uc6d0\ud55c \uac83\uc774 \uc544\ub2c8\ub2e4. \ubc14\uae65\uc758 \ubc14\ub78c\uc744 \uba48\ucd94\ub294 \ub300\uc2e0 \uc9c0\uae08\uc758 \ud310\ub2e8\uc744 \uc0b4\ud3b4\ubcf8\ub2e4\ub294 \uc0dd\uac01\uc744 \ud3b8\ud558\uac8c \ub5a0\uc62c\ub9ac\ub294 \uc785\uad6c\ub85c \ubcf4\uc544\ub3c4 \uc88b\ub2e4."}, {"id": "factory-clock-workday-and-human-time", "title": "\uacf5\uc7a5\uc758 \uc2dc\uacc4 \u2014 \ud558\ub8e8\uc758 \uae38\uc774\ub294 \ub204\uac00 \uc815\ud588\uc744\uae4c", "summary": "\uc0b0\uc5c5\ud654 \uc2dc\ub300\uc758 \ub178\ub3d9\uc2dc\uac04\uacfc \uc784\uae08, \ub3d9\uc791 \uce21\uc815\uacfc \uc77c\uc0c1\uc0dd\ud65c\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "ideas", "category_title": "\uc0dd\uac01\uacfc \uc9c0\uc2dd", "subcategory": "\uc0ac\ud68c\uc640 \uc81c\ub3c4\uc758 \ud0c4\uc0dd", "categories": ["ideas"], "url": "stories/factory-clock-workday-and-human-time/index.html", "image": "../media/factory-clock-workday-and-human-time.png", "alt": "\ud070 \ubcbd\uc2dc\uacc4 \uc544\ub798\uc5d0\uc11c \uc9c1\uae30\uc640 \ud568\uaed8 \uc77c\ud558\ub294 \uc131\uc778 \ub178\ub3d9\uc790\ub4e4\uc758 \uc0b0\uc5c5\ud654 \uc2dc\ub300 \uc0c1\uc0c1 \uc0bd\ud654", "text": "\uacf5\uc7a5\uc758 \uc2dc\uacc4 \u2014 \ud558\ub8e8\uc758 \uae38\uc774\ub294 \ub204\uac00 \uc815\ud588\uc744\uae4c \uae30\uacc4\uc758 \uc18d\ub3c4\uac00 \uc0ac\ub78c\uc758 \uc2dc\uac04\uc744 \uc7ac\uae30 \uc2dc\uc791\ud55c \ud48d\uacbd \uc0b0\uc5c5\ud654 \uc2dc\ub300\uc758 \ub178\ub3d9\uc2dc\uac04\uacfc \uc784\uae08, \ub3d9\uc791 \uce21\uc815\uacfc \uc77c\uc0c1\uc0dd\ud65c\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc0ac\ud68c\uc640 \uc81c\ub3c4\uc758 \ud0c4\uc0dd \uc0dd\uac01\uacfc \uc9c0\uc2dd \uc2dc\uacc4\ub294 \ubaa8\ub450\uc5d0\uac8c \uac19\uc740 \uc2dc\uac04\uc744 \uc54c\ub824 \uc8fc\ub294 \uac83\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uadf8\ub7f0\ub370 \uacf5\uc7a5 \ubcbd\uc5d0 \uac78\ub9ac\uba74 \ub2e8\uc21c\ud55c \uc548\ub0b4\ud310\uc774 \uc544\ub2c8\ub2e4. \uc5b8\uc81c \uc77c\uc744 \uc2dc\uc791\ud558\uace0 \uc26c\uace0 \ub05d\ub0b4\ub294\uc9c0, \ub2a6\uc5c8\ub2e4\ub294 \uac83\uc774 \ubb34\uc5c7\uc744 \ub73b\ud558\ub294\uc9c0 \uc815\ud558\ub294 \uae30\uc900\uc774 \ub41c\ub2e4. \uc2dc\uac04\uc744 \uac00\uc9c4 \uc0ac\ub78c\uacfc \uc2dc\uac04\uc744 \ud314\uc544\uc57c \ud558\ub294 \uc0ac\ub78c\uc758 \uad00\uacc4\ub3c4 \uadf8 \uc544\ub798 \uc0dd\uae34\ub2e4. \uc0b0\uc5c5\ud601\uba85\uc758 \uc774\uc57c\uae30\ub97c \uc99d\uae30\uae30\uad00\uacfc \uc0dd\uc0b0\ub7c9\ub9cc\uc73c\ub85c \uc77d\uc73c\uba74 \ud558\ub8e8\ub97c \uc2e4\uc81c\ub85c \ubcf4\ub0b8 \uc0ac\ub78c\ub4e4\uc740 \ud76c\ubbf8\ud574\uc9c4\ub2e4. \uc624\ud508\uc2a4\ud0dd\uc2a4\uc758 \uc0b0\uc5c5 \ub178\ub3d9 \uc124\uba85\uc744 \ub530\ub77c, 19\uc138\uae30\uc640 20\uc138\uae30 \ucd08\uc758 \uacf5\uc7a5\uc5d0\uc11c \uc2dc\uac04\uacfc \uc0dd\ud65c\uc774 \uc5b4\ub5bb\uac8c \ubd80\ub52a\ucce4\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc5ec\ub7ec \uc0ac\ub78c\uc774 \uae30\uacc4\uc640 \uc5f0\uacb0\ub418\uc5b4 \uc77c\ud558\uba74 \uac01\uc790\uac00 \uc790\uae30 \uc18d\ub3c4\ub85c\ub9cc \uc6c0\uc9c1\uc774\uae30 \uc5b4\ub835\ub2e4. \ud55c \uacfc\uc815\uc758 \uc9c0\uc5f0\uc774 \ub2e4\ub978 \uacfc\uc815\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc900\ub2e4. \uacf5\uc7a5\uc5d0\ub294 \uc77c\uc744 \ub9de\ucd94\uc5b4 \uc2dc\uc791\ud558\uace0 \uc774\uc5b4 \uac08 \uc774\uc720\uac00 \uc0dd\uae34\ub2e4. \uc0dd\uc0b0\uc758 \uaddc\ubaa8\uac00 \ucee4\uc9c4\ub2e4\ub294 \uac83\uc740 \uc0ac\ub78c\ub4e4\uc758 \uc2dc\uac04\uc774 \ud55c \uc7a5\uc18c\uc758 \uc9c8\uc11c\uc5d0 \ubb36\uc778\ub2e4\ub294 \ub73b\uc774\uae30\ub3c4 \ud588\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc0b0\uc5c5\ud654 \uc774\uc804\uc5d0\ub294 \uc2dc\uac04\uc774 \uc804\ud600 \uc911\uc694\ud558\uc9c0 \uc54a\uc558\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub18d\uc0ac\uc640 \uc218\uacf5\uc5c5\uc5d0\ub3c4 \uacc4\uc808\uacfc \uc57d\uc18d, \ub9c8\uac10\uc774 \uc788\uc5c8\ub2e4. \ub2ec\ub77c\uc9c4 \uac83\uc740 \ub9ce\uc740 \ub178\ub3d9\uc758 \uc18d\ub3c4\uc640 \ud734\uc2dd\uc774 \uae30\uacc4\uc640 \uacbd\uc601\uc790\uc758 \uaddc\uce59 \uc544\ub798 \ub354 \uc9c1\uc811\uc801\uc73c\ub85c \ub9de\ucd94\uc5b4\uc9c0\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc5b8\uc81c \uc26c\uc5b4\ub3c4 \ub418\ub294\uc9c0\uc758 \ud310\ub2e8\uc774 \uc0dd\ud65c\uc758 \uc911\uc694\ud55c \ubb38\uc81c\uac00 \ub41c\ub2e4. \uad50\uc7ac\ub294 \uc9c0\uc5ed\uacfc \uc5c5\uc885\uc5d0 \ub530\ub77c \uc544\uc8fc \uae34 \ub178\ub3d9\uc774 \uc774\ub8e8\uc5b4\uc9c4 \ubaa8\uc2b5\uc744 \uc18c\uac1c\ud55c\ub2e4. \ud558\uc9c0\ub9cc \ubaa8\ub4e0 \ub098\ub77c\uc640 \ubaa8\ub4e0 \uacf5\uc7a5\uc774 \uac19\uc740 \uc2dc\uac04\ud45c\uc600\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud2b9\uc815\ud55c \uae34 \uadfc\ubb34 \uc0ac\ub840 \ud558\ub098\ub97c \uace8\ub77c \uc804 \uc138\uacc4 \ub178\ub3d9\uc790\uc758 \ud558\ub8e8\ub85c \uc77c\ubc18\ud654\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ucc28\uc774\ub97c \ubcf4\uc544\uc57c \uc65c \uc0ac\ub78c\ub4e4\uc774 \ub2e4\ub978 \uc120\ud0dd\uc744 \ud588\ub294\uc9c0\ub3c4 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ub0ae\uc740 \uc784\uae08\uc5d0 \uae34 \uc2dc\uac04\uc774 \uacb9\uce58\uace0, \uc77c\uac10\uc774\ub098 \uc6d0\ub8cc\uac00 \ubaa8\uc790\ub77c\uba74 \uc791\uc5c5\uc7a5\uc774 \ub2eb\ud788\uae30\ub3c4 \ud588\ub2e4. \ub9e4\uc77c \ud798\ub4e4\uac8c \uc77c\ud55c\ub2e4\uace0 \ub2e4\uc74c \ub2ec\uc758 \uc0dd\ud65c\uae4c\uc9c0 \ubcf4\uc7a5\ub418\uc9c0\ub294 \uc54a\uc558\ub2e4. \ud574\uace0\uc640 \ud734\uc5c5\uc5d0 \ub300\ube44\ud558\ub294 \uacf5\uc801\uc778 \uc81c\ub3c4\ub3c4 \ucda9\ubd84\ud558\uc9c0 \uc54a\uc740 \uacf3\uc774 \ub9ce\uc558\ub2e4. \uc2dc\uacc4\uac00 \uaddc\uce59\uc801\uc774\uc5b4\ub3c4 \ub178\ub3d9\uc790\uc758 \uc18c\ub4dd\uc740 \uaddc\uce59\uc801\uc774\uc9c0 \uc54a\uc744 \uc218 \uc788\uc5c8\ub2e4. \uc131\uc778 \ub0a8\uc131\uacfc \uc5ec\uc131, \uc544\uc774\ub4e4\uc740 \uac19\uc740 \ud658\uacbd\uc5d0\uc11c \uc77c\ud574\ub3c4 \ub2e4\ub978 \uc784\uae08\uc744 \ubc1b\uc558\ub2e4. \uc9d1\uc5d0 \uac00\uc838\uac00\ub294 \ub3c8\uacfc \uae30\ub300\ub418\ub294 \uc5ed\ud560\ub3c4 \ub2ec\ub790\ub2e4. \uc784\uae08\ud45c\ub294 \ub2e8\uc9c0 \ub204\uac00 \uc5bc\ub9c8\ub098 \ub2a5\uc219\ud55c\uc9c0\ub97c \uac1d\uad00\uc801\uc73c\ub85c \uc801\uc740 \uc885\uc774\uac00 \uc544\ub2c8\uc5c8\ub2e4. \ub098\uc774\uc640 \uc131\ubcc4\uc5d0 \ub300\ud55c \uc0ac\ud68c\uc758 \ud310\ub2e8\ub3c4 \uadf8 \uc548\uc5d0 \ub4e4\uc5b4\uac14\ub2e4. \uc544\uc774\uc758 \uc218\uc785\uc774 \uac00\uc871 \uc0dd\ud65c\uc5d0 \ud544\uc694\ud588\ub358 \uc0c1\ud669\uc744 \ubb34\uc2dc\ud55c \ucc44 \ubd80\ubaa8\uac00 \ub2e8\uc21c\ud788 \uad50\uc721\uc744 \uc2eb\uc5b4\ud588\ub2e4\uace0 \ub9d0\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \ub3d9\uc2dc\uc5d0 \uac00\ub09c\uc774 \uc704\ud5d8\ud55c \ub178\ub3d9\uc744 \uad1c\ucc2e\uac8c \ub9cc\ub4e4\uc5b4 \uc8fc\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uc544\uc774\ub4e4\uc774 \uc77c\ud130\uc5d0\uc11c \ud559\uad50\ub85c \uac08 \uc218 \uc788\uc73c\ub824\uba74 \ud55c \uc0ac\ub78c\uc758 \uc120\uc758 \uc678\uc5d0\ub3c4 \uac00\uc871\uc774 \uc0dd\ud65c\uc744 \uc720\uc9c0\ud560 \uc870\uac74\uacfc \uc81c\ub3c4\uac00 \ud544\uc694\ud588\ub2e4. 20\uc138\uae30 \ucd08\uc5d0\ub294 \ud504\ub808\ub354\ub9ad \uc708\uc990\ub85c \ud14c\uc77c\ub7ec\uc758 \uacfc\ud559\uc801 \uad00\ub9ac\uac00 \ub110\ub9ac \ub17c\uc758\ub41c\ub2e4. \ub0ad\ube44\ub418\ub294 \ub3d9\uc791\uc744 \uc904\uc774\uace0 \uc77c\uc744 \ub354 \ud6a8\uc728\uc801\uc73c\ub85c \ud558\ub824\ub294 \uc0dd\uac01\uc774\ub2e4. \uc2dc\uac04\uc744 \ub9de\ucd94\ub294 \ub370\uc11c \ud55c \uac78\uc74c \ub354 \ub098\uc544\uac00 \uc190\uacfc \ubab8\uc774 \uc5b4\ub5a4 \uc21c\uc11c\ub85c \uc6c0\uc9c1\uc774\ub294\uc9c0\uae4c\uc9c0 \uce21\uc815\uc758 \ub300\uc0c1\uc73c\ub85c \uc0bc\ub294\ub2e4. \uc791\uc5c5\uc744 \ubd84\uc11d\ud558\uba74 \ubd88\ud544\uc694\ud55c \uc6c0\uc9c1\uc784\uc744 \ubc1c\uacac\ud560 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ud6a8\uc728\uc774\ub77c\ub294 \uc774\ub984\uc774 \ub204\uad6c\uc758 \uc774\uc775\uacfc \ud3b8\uc548\ud568\uc744 \uba3c\uc800 \uc138\ub294\uc9c0 \ub530\uc838 \ubcfc \ud544\uc694\ub3c4 \uc788\ub2e4. \uc0dd\uc0b0\ub7c9\uc774 \ub298\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ub178\ub3d9\uc758 \ud53c\ub85c\uac00 \uc904\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uac19\uc9c0 \uc54a\ub2e4. \ube68\ub77c\uc9c4 \uacfc\uc815\uc5d0\uc11c \uc26c\ub294 \ud2c8\ub9c8\uc800 \uc904\uc5b4\ub4e0\ub2e4\uba74 \ub178\ub3d9\uc790\uac00 \ub290\ub07c\ub294 \uac1c\uc120\uc740 \ub2ec\ub790\uc744 \uac83\uc774\ub2e4. \uc77c\ubd80 \uc791\uc5c5\uc7a5\uc5d0\uc11c\ub294 \uc77c\uc744 \ud558\uba70 \uc11c\ub85c \uc774\uc57c\uae30\ud558\uac70\ub098 \uc549\ub294 \uac83\uae4c\uc9c0 \uc81c\ud55c\ud588\ub2e4. \uacbd\uc601\uc790\uc5d0\uac8c\ub294 \uc9d1\uc911\uacfc \uc18d\ub3c4\ub97c \uc704\ud55c \uaddc\uce59\uc77c \uc218 \uc788\uc9c0\ub9cc \ub178\ub3d9\uc790\uc5d0\uac8c\ub294 \uc790\uae30 \ubab8\uacfc \uad00\uacc4\ub97c \ud1b5\uc81c\ub2f9\ud558\ub294 \uacbd\ud5d8\uc774\ub2e4. \uac19\uc740 \ub3d9\uc791\uc744 \ub418\ud480\uc774\ud558\ub294 \ub3d9\uc548 \ub098\ub20c \uc218 \uc788\ub294 \uc9e7\uc740 \ub9d0\ub3c4 \ud558\ub8e8\uc758 \uc9c8\uac10\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4. \uacf5\uc7a5\uc744 \ud558\ub098\uc758 \uac70\ub300\ud55c \uae30\uacc4\ucc98\ub7fc \ubcf4\ub294 \uc2dc\uc120\uacfc \uadf8 \uc548\uc5d0 \uc788\ub294 \uc0ac\ub78c\uc774 \ud558\ub8e8\ub97c \ubcf4\ub0b4\ub294 \ubc29\uc2dd\uc740 \uc644\uc804\ud788 \uacb9\uce58\uc9c0 \uc54a\ub294\ub2e4. \uc26c\ub294 \uc2dc\uac04\uc758 \uae38\uc774\ub9cc\ud07c \ub204\uac00 \ud734\uc2dd\uc758 \ud544\uc694\ub97c \ud310\ub2e8\ud560 \uc218 \uc788\ub294\uc9c0\ub3c4 \uc911\uc694\ud588\ub2e4. \uc2dc\uacc4\uc758 \uc22b\uc790\ub294 \uac19\uc544\ub3c4 \uadf8 \uc22b\uc790\uac00 \ubab8\uc5d0 \ub2ff\ub294 \ub290\ub08c\uc740 \uc77c\ud558\ub294 \uc790\ub9ac\ub9c8\ub2e4 \ub2e4\ub974\ub2e4. \uadf8\ub7f0 \uc870\uac74\uc5d0\ub3c4 \uacf5\uc7a5 \uc77c\uc744 \uc120\ud0dd\ud558\ub294 \uc0ac\ub78c\uc774 \ub9ce\uc558\ub2e4. \ub2e4\ub978 \uc77c\uc790\ub9ac\uac00 \ubc18\ub4dc\uc2dc \ub354 \uc548\uc804\ud558\uac70\ub098 \uc790\uc720\ub85c\uc6e0\ub358 \uac83\uc740 \uc544\ub2c8\uae30 \ub54c\ubb38\uc774\ub2e4. \ub18d\uc5c5 \ub178\ub3d9\uc758 \uc784\uae08\uc774 \ub354 \ub0ae\uac70\ub098, \uac00\uc0ac \uc0ac\uc6a9\uc778\uc73c\ub85c \uc0b4\uba74 \uc8fc\uc778\uc758 \uc9d1\uc5d0\uc11c \ubc24\ub0ae\uc5c6\uc774 \ub300\uae30\ud574\uc57c \ud558\ub294 \uacbd\uc6b0\ub3c4 \uc788\uc5c8\ub2e4. \uacf5\uc7a5\uc5d0\ub294 \uc801\uc5b4\ub3c4 \uc77c\uc774 \ub05d\ub09c \ub4a4 \uc790\uae30 \uc2dc\uac04\uc744 \uac00\uc9c8 \uac00\ub2a5\uc131\uc774 \uc788\uc5c8\ub2e4. \ud2b9\ud788 \uc80a\uc740 \uc5ec\uc131\ub4e4\uc5d0\uac8c\ub294 \uc784\uae08\uacfc \ub3d9\ub8cc, \ud1f4\uadfc \ub4a4\uc758 \uc2dc\uac04\uc774 \uc0c8\ub85c\uc6b4 \uacbd\ud5d8\uc774 \ub420 \uc218 \uc788\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \ub0ae\uc740 \uc784\uae08\uacfc \uad34\ub86d\ud798, \uac00\uc871\uc5d0\uac8c \uc218\uc785\uc744 \ub0b4\ub193\uc544\uc57c \ud558\ub294 \uae30\ub300\ub3c4 \ud568\uaed8 \uc788\uc5c8\ub2e4. \uc0b0\uc5c5\ud654\ub294 \uc624\uc9c1 \uc5b5\uc555\uc774\uac70\ub098 \uc624\uc9c1 \ud574\ubc29\uc774\uc5c8\ub2e4\ub294 \ud55c \ubb38\uc7a5\uc73c\ub85c \uc815\ub9ac\ud558\uae30 \uc5b4\ub835\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uac00\ub2a5\uc131\uacfc \uc81c\uc57d\uc774 \uac19\uc740 \ucd9c\uadfc\uae38\uc5d0 \ub193\uc5ec \uc788\uc5c8\ub2e4. \ub300\ub7c9\uc0dd\uc0b0\ud488\uc740 \uc77c\ud558\ub294 \uc0ac\ub78c\uc758 \uc9d1\uc73c\ub85c\ub3c4 \ub4e4\uc5b4\uc654\ub2e4. \uc804\uc5d0\ub294 \ube44\uc2f8\ub358 \uac00\uad6c\uc640 \uc637, \ube44\ub204\uc640 \ucc45 \uac19\uc740 \ubb3c\uac74\uc744 \ub354 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uc0b4 \uc218 \uc788\uac8c \ub418\uc5c8\ub2e4. \ub178\ub3d9\uc790\ub294 \uc0dd\uc0b0\uc758 \uc218\ub2e8\uc778 \ub3d9\uc2dc\uc5d0 \uc0c8 \uc2dc\uc7a5\uc758 \uc18c\ube44\uc790\uc600\ub2e4. \uacf5\uc7a5 \uc548\uc758 \uace0\ub41c \ud558\ub8e8\uc640 \uc9d1 \uc548\uc758 \ubb3c\uac74\uc774 \ub298\uc5b4\ub098\ub294 \ubcc0\ud654\ub294 \ud55c \uc2dc\ub300 \uc548\uc5d0 \ud568\uaed8 \uc788\uc5c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc0c8 \ubb3c\uac74 \uba87 \uac1c\uac00 \uc704\ud5d8\uacfc \ud53c\ub85c\ub97c \ubaa8\ub450 \ubcf4\uc0c1\ud588\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc0dd\ud65c\uc774 \ub098\uc544\uc84c\ub2e4\ub294 \ud3c9\uade0\uc801\uc778 \uc9c0\ud45c\uc640 \ud55c \uc0ac\ub78c\uc774 \uacaa\uc740 \ud558\ub8e8\ub294 \ub2e4\ub978 \ud06c\uae30\uc758 \uc774\uc57c\uae30\ub2e4. \uadf8 \ub458\uc744 \ud568\uaed8 \uc77d\uc744 \ub54c \uc0dd\uc0b0\ub7c9\uc758 \uc99d\uac00 \ub4a4\uc5d0\uc11c \ubb34\uc5c7\uc774 \uac1c\uc120\ub418\uace0 \ubb34\uc5c7\uc774 \ub0a8\uc558\ub294\uc9c0 \ub354 \ubd84\uba85\ud558\uac8c \ubb3c\uc744 \uc218 \uc788\ub2e4. \uacf5\uc7a5\uc758 \uc2dc\uacc4\ub294 \uc2dc\uac04\uc744 \uc7ac\uc9c0\ub9cc \ud53c\ub85c\uc640 \uc874\uc5c4, \ub3d9\ub8cc\uc640 \ub098\ub204\ub294 \ub9d0\uc744 \ubaa8\ub450 \uce21\uc815\ud558\uc9c0\ub294 \ubabb\ud55c\ub2e4. \uadf8\ub798\uc11c \ub178\ub3d9\uc758 \uc5ed\uc0ac\ub294 \uae30\uacc4\uc758 \uc18d\ub3c4\ubfd0 \uc544\ub2c8\ub77c \uadf8 \uc18d\ub3c4\ub97c \uc0ac\ub78c\uc774 \uc5b4\ub5a4 \uc870\uac74\uc5d0\uc11c \ubc1b\uc544\ub4e4\uc600\ub294\uc9c0\uc758 \uc5ed\uc0ac\uc774\uae30\ub3c4 \ud558\ub2e4. \uac19\uc740 \ud55c \uc2dc\uac04\uc774 \ub204\uad6c\uc5d0\uac8c\ub294 \ube44\uc6a9\uc774\uace0 \ub204\uad6c\uc5d0\uac8c\ub294 \uc0b6\uc758 \uc77c\ubd80\uc600\ub2e4. \uc624\ub298 \ucd9c\uadfc\uacfc \ud1f4\uadfc \uc2dc\uac01\uc744 \ub2f9\uc5f0\ud558\uac8c \uc0dd\uac01\ud560 \ub54c\ub3c4 \uadf8 \ub4a4\uc5d0\ub294 \uc624\ub798\ub41c \uc9c8\ubb38\uc774 \uc788\ub2e4. \ud558\ub8e8 \uac00\uc6b4\ub370 \uc5b4\ub514\uae4c\uc9c0\ub97c \uc77c\uc5d0 \ub0b4\uc5b4 \uc8fc\uace0 \ubb34\uc5c7\uc744 \uc790\uae30 \uc2dc\uac04\uc73c\ub85c \ub0a8\uae38 \uac83\uc778\uac00. \uacf5\uc7a5 \ubcbd\uc758 \uc2dc\uacc4\ub294 \uae30\uc220\uc774 \uc0ac\ub78c\uc758 \uc0dd\ud65c\uc744 \ubc14\uafb8\uc5c8\ub2e4\ub294 \uc99d\uac70\uc778 \ub3d9\uc2dc\uc5d0, \uadf8 \ubcc0\ud654\ub97c \ub204\uac00 \uc815\ud558\ub294\uc9c0 \uacc4\uc18d \ubb3b\uac8c \ud558\ub294 \ubb3c\uac74\uc774\ub2e4."}, {"id": "glass-photo-pillow-ruler", "title": "\uc61b \ubca0\uac1c \uc0ac\uc9c4 \uc606\uc5d0\ub294 \uc65c \uc790\uac00 \uc11c \uc788\uc744\uae4c", "summary": "\uc720\ub9ac\uac74\ud310\uc5d0 \ub0a8\uc740 \ubca0\uac1c \uc0ac\uc9c4\uc5d0\uc11c \ub208\uae08\uc790\uc640 \ubc88\ud638\ub97c \ubc1c\uacac\ud569\ub2c8\ub2e4.", "category": "ideas", "category_title": "\uc0dd\uac01\uacfc \uc9c0\uc2dd", "subcategory": "\uae30\ub85d\uacfc \uc9c0\uc2dd \uc804\ub2ec", "categories": ["ideas"], "url": "stories/glass-photo-pillow-ruler/index.html", "image": "../media/glass-photo-pillow-ruler.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \ubc31\uc790\ubca0\uac1c \uc720\ub9ac\uac74\ud310 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc61b \ubca0\uac1c \uc0ac\uc9c4 \uc606\uc5d0\ub294 \uc65c \uc790\uac00 \uc11c \uc788\uc744\uae4c \uc8fc\uc778\uacf5\ub9cc\ud07c \uc911\uc694\ud55c \uc0ac\uc9c4 \uc18d \uc870\uc5f0 \uc720\ub9ac\uac74\ud310\uc5d0 \ub0a8\uc740 \ubca0\uac1c \uc0ac\uc9c4\uc5d0\uc11c \ub208\uae08\uc790\uc640 \ubc88\ud638\ub97c \ubc1c\uacac\ud569\ub2c8\ub2e4. \uae30\ub85d\uacfc \uc9c0\uc2dd \uc804\ub2ec \uc0dd\uac01\uacfc \uc9c0\uc2dd \uc624\ub798\ub41c \ud751\ubc31 \uc0ac\uc9c4 \ud55c \uc7a5\uc744 \ubcf4\uc790. \uac00\uc6b4\ub370\uc5d0\ub294 \ubca0\uac1c\uac00 \ub193\uc5ec \uc788\uace0 \uc624\ub978\ucabd\uc5d0\ub294 \uae34 \ub9c9\ub300\uac00 \uc11c \uc788\ub2e4. \uae30\ub150\uc0ac\uc9c4\uc774\ub77c\uba74 \uce58\uc6cc \ub450\uc5c8\uc744 \uac83 \uac19\uc740 \ubb3c\uac74\uc778\ub370, \uc774 \uc0ac\uc9c4\uc5d0\uc11c\ub294 \ud568\uaed8 \ub0a8\uc544 \uc788\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc18c\uc7a5\ud55c \ubc31\uc790\ubca0\uac1c \uc720\ub9ac\uac74\ud310\uc774\ub2e4. \uc774 \uc790\ub8cc\uc5d0\uc11c \ubc15\ubb3c\uad00\uc774 \uc18c\uc7a5\ud55c \uac83\uc740 \uc0ac\uc9c4\uc744 \ub2f4\uc740 \uc720\ub9ac\uac74\ud310\uc774\uba70, \uc0ac\uc9c4 \uc18d \ubca0\uac1c \uc790\uccb4\uc640\ub294 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ud55c \uc7a5\uc758 \uc0ac\uc9c4\uc5d0\ub3c4 \uc11c\ub85c \ub2e4\ub978 \ubb3c\uac74\uc758 \uc774\ub825\uc774 \uacb9\uce5c\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc740 \uc624\ub978\ucabd \ub9c9\ub300\ub97c \ud06c\uae30 \uce21\uc815\uc6a9 \uc790\ub77c\uace0 \uc54c\ub824 \uc900\ub2e4. \uc0ac\uc9c4\ub9cc \ubcf4\uba74 \ubca0\uac1c\uac00 \uc190\ubc14\ub2e5\ub9cc \ud55c\uc9c0, \ud6e8\uc52c \ud070\uc9c0 \uac00\ub2a0\ud558\uae30 \uc5b4\ub835\ub2e4. \uacc1\uc5d0 \uc120 \uc790\ub294 \uadf8 \ud310\ub2e8\uc744 \ub3d5\ub294 \uc5ed\ud560\uc744 \ud55c\ub2e4. \uc624\ub298 \uc911\uace0 \ubb3c\ud488 \uc0ac\uc9c4\uc5d0 \ub3d9\uc804\uc774\ub098 \uc790\ub97c \ud568\uaed8 \ub193\ub294 \uc77c\uc744 \ub5a0\uc62c\ub824\ub3c4 \uc88b\ub2e4. \uc0ac\uc9c4\uc740 \ubaa8\uc591\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ub370 \ub2a5\ud558\uc9c0\ub9cc \ud06c\uae30\ub97c \uc800\uc808\ub85c \uc124\uba85\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc624\ub798\ub41c \ucd2c\uc601\uc5d0\ub3c4 \uadf8 \ube48\ud2c8\uc744 \ucc44\uc6b8 \ub3c4\uad6c\uac00 \ud544\uc694\ud588\ub358 \uac83\uc774\ub2e4. \uc0ac\uc9c4 \uc18d \uc624\ub978\ucabd\uc5d0\ub294 \ucd2c\uc601 \ub2f9\uc2dc \ubc88\ud638 6014\ub3c4 \ub0a8\uc544 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc0ac\uc9c4 \uc18d \ubca0\uac1c\uac00 \uc911\uad6d \ub3c4\uc790\uc774\uba70 \ud604\uc7ac \uad6d\ub9bd\uc911\uc559\ubc15\ubb3c\uad00\uc758 \ub355\uc2182165\ub85c \uc18c\uc7a5\ub418\uc5b4 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ucd2c\uc601 \ubc88\ud638\uc640 \uc9c0\uae08\uc758 \uc18c\uc7a5\ud488 \ubc88\ud638\ub294 \uac19\uc740 \uac83\uc774 \uc544\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc22b\uc790\uac00 \ub2e4\ub974\ub2e4\uace0 \uc0ac\uc9c4\uc774 \uc798\ubabb\ub418\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5b4\ub290 \uc22b\uc790\uac00 \uc0ac\uc9c4\uc744 \uc704\ud55c \uae30\ub85d\uc774\uace0 \uc5b4\ub290 \uc22b\uc790\uac00 \ubb3c\uac74\uc744 \ucc3e\ub294 \ud45c\uc9c0\uc778\uc9c0 \ub098\ub204\uc5b4 \ubcf4\uba74 \ud55c\uacb0 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \uc774 \uc18c\uc7a5\ud488\uc5d0\uc11c \uba3c\uc800 \uad6c\ubcc4\ud560 \uac83\uc740 \ucd2c\uc601 \ub300\uc0c1\uacfc \uc0ac\uc9c4\uc744 \ub0a8\uae34 \ub9e4\uccb4\ub2e4. \ubc31\uc790\ubca0\uac1c\ub294 \uce74\uba54\ub77c \uc55e\uc5d0 \ub193\uc778 \ubb3c\uac74\uc774\uace0, \uc720\ub9ac\uac74\ud310\uc740 \uadf8 \ubaa8\uc2b5\uc744 \ub2f4\uc740 \uc0ac\uc9c4 \uc790\ub8cc\ub2e4. \ud654\uba74\uc5d0\uc11c \ud55c \ubc88\uc5d0 \ub9cc\ub098\uae30 \ub54c\ubb38\uc5d0 \ub458\uc744 \uac19\uc740 \uc18c\uc7a5\ud488\uc73c\ub85c \uc0dd\uac01\ud558\uae30 \uc27d\uc9c0\ub9cc \uac01\uac01\uc758 \uc774\ub825\uacfc \uc9c8\ubb38\uc774 \uc788\ub2e4. \ub3c4\uc790\uc758 \ud604\uc7ac \uc18c\uc7a5\ucc98\uc640 \uc0ac\uc9c4\uc758 \ubcf4\uad00\ucc98\ub97c \ub530\ub85c \uc77d\uc5b4\uc57c \ud558\ub294 \uc774\uc720\ub2e4. \ub3c4\uc790\ub9cc \ubcf4\uba74 \ud615\ud0dc\uc640 \uc81c\uc791, \uc0ac\uc6a9\uc744 \ubb3b\uac8c \ub41c\ub2e4. \uac74\ud310\uc744 \ubcf4\uba74 \uc5b4\ub5a4 \uac01\ub3c4\uc5d0\uc11c \ubb34\uc5c7\uacfc \ud568\uaed8 \ucc0d\uc5c8\uace0 \uc5b4\ub5bb\uac8c \uc2dd\ubcc4\ud588\ub294\uc9c0\ub3c4 \ubb3b\uac8c \ub41c\ub2e4. \uac19\uc740 \uc774\ubbf8\uc9c0 \uc548\uc5d0 \ubb3c\uac74\uc758 \uc5ed\uc0ac\uc640 \uae30\ub85d\ud558\ub294 \ud589\uc704\uc758 \uc5ed\uc0ac\uac00 \uacb9\uce5c\ub2e4. \uc5f0\uad6c\ub97c \ub3d5\uae30 \uc704\ud574 \ub9cc\ub4e0 \uc0ac\uc9c4\uc774 \ub098\uc911\uc5d0\ub294 \uadf8 \uc5f0\uad6c \ubc29\uc2dd \uc790\uccb4\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc790\ub8cc\uac00 \ub418\ub294 \uc148\uc774\ub2e4. \uc0ac\uc9c4 \uc18d \uce21\uc815\uc6a9 \uc790\ub294 \ud06c\uae30\ub97c \ucd94\uc815\ud560 \uae30\uc900\uc744 \uc900\ub2e4. \uc0ac\uc9c4\uc744 \ud655\ub300\ud574\uc11c \ubcf4\ub294 \uc815\ub3c4\uac00 \ub2ec\ub77c\uc838\ub3c4 \ub300\uc0c1 \uc606\uc758 \uae30\uc900\uc774 \ud568\uaed8 \ubcf4\uc774\uba74 \ube44\ub840\ub97c \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ud654\uba74\uc758 \uc778\uc1c4 \ud06c\uae30\ub098 \ud734\ub300\uc804\ud654\uc758 \ud06c\uae30\uac00 \uace7 \uc720\ubb3c\uc758 \uc2e4\uc81c \ud06c\uae30\ub77c\uace0 \ucc29\uac01\ud558\ub294 \uc77c\uc744 \uc904\uc5ec \uc900\ub2e4. \ub300\uc0c1\uacfc \ud568\uaed8 \ub2e4\ub978 \ubb3c\uac74\uc744 \ub193\ub294 \uc120\ud0dd\uc5d0\ub294 \uc774\ub7f0 \uc815\ubcf4\uc758 \ubaa9\uc801\uc774 \uc788\ub2e4. \uadf8\ub807\uc9c0\ub9cc \uc790\uac00 \ubcf4\uc778\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \uc0ac\uc9c4\uc758 \uc5b4\ub290 \uce58\uc218\ub4e0 \uc815\ud655\ud558\uac8c \uc7ac\uc5b4 \ub0bc \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub300\uc0c1\uacfc \uc790\uc758 \ubc29\ud5a5, \ucd2c\uc601 \uac01\ub3c4\uc5d0 \ub530\ub77c \ubcf4\uc774\ub294 \uad00\uacc4\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \uc0ac\uc9c4\ub9cc\uc73c\ub85c \uc0c8 \uc2e4\uce21\uac12\uc744 \uacc4\uc0b0\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc5b4\ub5a4 \uc815\ubcf4\ub97c \ub0a8\uae30\ub824\uace0 \uc774\ub7f0 \ucd2c\uc601\uc744 \ud588\ub294\uc9c0 \uc77d\ub294 \ub370 \ucd08\uc810\uc744 \ub9de\ucd98\ub2e4. \uae30\ub85d\uc774 \uce5c\uc808\ud55c \uacf3\uacfc \uc5ec\uc804\ud788 \ud655\uc778\uc774 \ud544\uc694\ud55c \uacf3\uc744 \ub098\ub204\uc5b4 \ubcfc \uc218 \uc788\ub2e4. 6014\ub294 \ucd2c\uc601 \uc790\ub8cc\uc640 \uad00\uacc4\ub41c \ubc88\ud638\uc774\uace0 \ub355\uc2182165\ub294 \ud604\uc7ac \ub3c4\uc790\ub97c \uc2dd\ubcc4\ud558\ub294 \uc18c\uc7a5 \ubc88\ud638\ub2e4. \uc22b\uc790\uac00 \ub2e4\ub974\ub2e4\uace0 \uc5b4\ub290 \ud55c\ucabd\uc744 \ud2c0\ub9b0 \uac83\uc73c\ub85c \uace0\uce60 \ud544\uc694\ub294 \uc5c6\ub2e4. \uac01\uac01 \ubb34\uc5c7\uc744 \uad00\ub9ac\ud558\ub294 \uccb4\uacc4\uc778\uc9c0 \uba3c\uc800 \uc54c\uc544\uc57c \ud55c\ub2e4. \ubb3c\uac74\uacfc \uc0ac\uc9c4, \uae30\uc99d\uacfc \ubcf4\uad00\uc774 \uc11c\ub85c \ub2e4\ub978 \uae30\ub85d\uc744 \ub9cc\ub4e4 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc774\ub7f0 \ubc88\ud638\ub4e4\uc744 \uc5f0\uacb0\ud574 \ub193\uc73c\uba74 \uacfc\uac70\uc758 \uc0ac\uc9c4 \uc18d \ubb3c\uac74\uc744 \uc624\ub298\uc758 \uc18c\uc7a5\ud488\uacfc \ub300\uc870\ud560 \uae38\uc774 \uc0dd\uae34\ub2e4. \uc0ac\uc9c4\uc774 \ub2ee\uc558\ub2e4\ub294 \uc778\uc0c1\ub9cc\uc73c\ub85c \ud655\uc778\ud558\ub294 \uac83\ubcf4\ub2e4 \uc815\ubcf4\uac00 \ub354\ud574\uc9c0\ub294 \uac83\uc774\ub2e4. \uc790\ub8cc\ub97c \uc815\ub9ac\ud558\ub294 \uc791\uc740 \ud45c\uc9c0\uac00 \uc0ac\ub78c\uacfc \uc2dc\ub300\uac00 \ub2ec\ub77c\uc838\ub3c4 \uac19\uc740 \ub300\uc0c1\uc744 \ub2e4\uc2dc \ucc3e\ub3c4\ub85d \ub3d5\ub294\ub2e4. \ubc88\ud638\uac00 \uc9c0\ub8e8\ud55c \ubd80\ub85d\ucc98\ub7fc \ubcf4\uc5ec\ub3c4 \ubb3c\uac74\uc758 \uc774\ub3d9\uc744 \uc787\ub294 \uc911\uc694\ud55c \ub3c4\uad6c\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc740 \uc0ac\uc9c4 \uc18d \ubca0\uac1c \uc717\ubd80\ubd84\uc758 \ud30c\uc190\uacfc \uc218\ub9ac \ud754\uc801\ub3c4 \uc9da\ub294\ub2e4. \ub9e4\ub048\ud55c \uc644\uc131\ud488\ub9cc \uae30\ub300\ud558\uba74 \uc9c0\ub098\uce60 \uc218 \uc788\uc9c0\ub9cc, \ub0a8\uc740 \uc0c1\ud0dc\ub294 \uc0ac\uc6a9\uacfc \uc190\uc0c1\uc744 \uac70\uce5c \ubb3c\uac74\uc758 \uc2dc\uac04\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub2e4\ub9cc \uc774 \uc0ac\uc9c4 \ud558\ub098\ub85c \uc5b8\uc81c \uc5b4\ub5a4 \uc0ac\uace0\uac00 \uc788\uc5c8\uace0 \ub204\uac00 \uace0\ucce4\ub294\uc9c0\uae4c\uc9c0 \uc7ac\uad6c\uc131\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud655\uc778\ub418\ub294 \ud754\uc801\uacfc \uadf8 \uc6d0\uc778\uc758 \uc774\uc57c\uae30\ub294 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc0ac\uc9c4\uc744 \ub2e4\uc2dc \ubcfc \ub54c\uc5d0\ub294 \uac00\uc6b4\ub370 \ub3c4\uc790\uc5d0\uc11c \uac00\uc7a5\uc790\ub9ac\uc758 \uc790\uc640 \ubc88\ud638\ub85c \ub208\uc744 \uc62e\uaca8 \ubcf4\uc790. \uc720\ubb3c\uc744 \uc798 \ubcf4\uc774\uac8c \ud558\ub824 \ub9c8\ub828\ud55c \uc8fc\ubcc0 \uc815\ubcf4\uac00 \ud568\uaed8 \ub4dc\ub7ec\ub09c\ub2e4. \ub3c4\uc790\ub294 \uadf8 \uc2dc\ub300\uc758 \ubb3c\uac74\uc774\uace0, \uc0ac\uc9c4\uc740 \ub204\uad70\uac00 \uadf8 \ubb3c\uac74\uc744 \uc54c\uc544\ubcf4\uace0 \uae30\ub85d\ud55c \uacb0\uacfc\ub2e4. \uc624\ub798\ub41c \ubca0\uac1c \ud55c \uc7a5\uba74\uc5d0\uc11c \ubcf4\uc874\ud558\ub294 \uc0ac\ub78c\uc758 \uc2dc\uc120\uae4c\uc9c0 \ub9cc\ub0a0 \uc218 \uc788\ub2e4. \uc124\uba85\uc5d0\ub294 \ubca0\uac1c\uc758 \ud30c\uc190\ub41c \uc717\ubd80\ubd84\uc774 \uc218\ub9ac\ub418\uc5c8\ub2e4\ub294 \ub0b4\uc6a9\ub3c4 \uc788\ub2e4. \uc644\ubcbd\ud55c \uc678\ud615\ub9cc \uae30\ub85d\ud55c \uac83\uc774 \uc544\ub2c8\ub77c, \uadf8\ub54c \ub0a8\uc544 \uc788\ub358 \uc0c1\ud0dc \uc5ed\uc2dc \uc0ac\uc9c4\uacfc \uc124\uba85 \uc548\uc5d0 \ub4e4\uc5b4 \uc788\ub294 \uc148\uc774\ub2e4. \uc774 \uc0ac\uc9c4\uc744 \ubcfc \ub54c \ubca0\uac1c \ubb34\ub2ac\ub97c \ubaa8\ub450 \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc606\uc758 \uc790\uc640 \ubc88\ud638\ubd80\ud130 \ucc3e\uc544\ubcf4\uc790. \ubb3c\uac74\uc744 \uc544\ub984\ub2f5\uac8c \ubcf4\uc5ec \uc8fc\ub294 \uc0ac\uc9c4\uacfc \ubb3c\uac74\uc744 \uc815\ud655\ud558\uac8c \ub0a8\uae30\ub294 \uc0ac\uc9c4\uc774 \uc5b4\ub5a4 \uc810\uc5d0\uc11c \ub2e4\ub978\uc9c0, \uc791\uc740 \uc870\uc5f0\ub4e4\uc774 \uc870\uc6a9\ud788 \uc54c\ub824 \uc900\ub2e4."}, {"id": "holbein-erasmus-writing", "title": "\uc5d0\ub77c\uc2a4\ubb34\uc2a4\uc758 \ucd08\uc0c1 \u2014 \uae00\uc744 \uc4f0\ub294 \uc190\uc774 \uc5bc\uad74\uc744 \uc124\uba85\ud560 \ub54c", "summary": "\ubaa8\ud53c \uc637\uacfc \ud39c, \ub0ae\ucd98 \ub208\uae38\uc744 \ub530\ub77c \ud55c \uc0ac\ub78c\uc758 \uc77c\uc774 \ucd08\uc0c1\uc5d0 \ub2f4\uae30\ub294 \ubc29\uc2dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "ideas", "category_title": "\uc0dd\uac01\uacfc \uc9c0\uc2dd", "subcategory": "\uc608\uc220\uc744 \ubcf4\ub294 \ubc95", "categories": ["ideas"], "url": "stories/holbein-erasmus-writing/index.html", "image": "../media/holbein-erasmus-writing.jpg", "alt": "\ud640\ubc14\uc778\uc758 \uc5d0\ub77c\uc2a4\ubb34\uc2a4 \ucd08\uc0c1. \ubaa8\ud53c \uc637\uacfc \uac80\uc740 \ubaa8\uc790\ub97c \uc4f4 \uc778\ubb3c\uc774 \uc606\uc5bc\uad74\ub85c \ucc45\uc0c1\uc5d0\uc11c \uae00\uc744 \uc501\ub2c8\ub2e4.", "text": "\uc5d0\ub77c\uc2a4\ubb34\uc2a4\uc758 \ucd08\uc0c1 \u2014 \uae00\uc744 \uc4f0\ub294 \uc190\uc774 \uc5bc\uad74\uc744 \uc124\uba85\ud560 \ub54c \ud640\ubc14\uc778\uc774 \uadf8\ub9b0 \ud559\uc790\uc758 \uc606\uc5bc\uad74\uacfc \ucc45\uc0c1 \uc704\uc758 \uc2dc\uac04 \ubaa8\ud53c \uc637\uacfc \ud39c, \ub0ae\ucd98 \ub208\uae38\uc744 \ub530\ub77c \ud55c \uc0ac\ub78c\uc758 \uc77c\uc774 \ucd08\uc0c1\uc5d0 \ub2f4\uae30\ub294 \ubc29\uc2dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc608\uc220\uc744 \ubcf4\ub294 \ubc95 \uc0dd\uac01\uacfc \uc9c0\uc2dd \ucd08\uc0c1\ud654 \uc18d \uc0ac\ub78c\uc740 \uc6b0\ub9ac\uc5d0\uac8c \uc2dc\uc120\uc744 \ubcf4\ub0b4\uc9c0 \uc54a\ub294\ub2e4. \uace0\uac1c\ub97c \uc870\uae08 \uc219\uc774\uace0 \ucc45\uc0c1 \uc704\uc5d0 \uc190\uc744 \ub454 \ucc44 \uae00\uc744 \uc4f4\ub2e4. \uad00\uac1d\uc5d0\uac8c \uc790\uae30\ub97c \uc18c\uac1c\ud558\ub824\ub294 \uc790\uc138\ubcf4\ub2e4 \uc9c0\uae08 \ud558\ub294 \uc77c\uc5d0 \ubab0\ub450\ud55c \ubaa8\uc2b5\uc774\ub2e4. \ud640\ubc14\uc778\uc758 \u3008\uc5d0\ub77c\uc2a4\ubb34\uc2a4\uc758 \ucd08\uc0c1\u3009\uc740 \uadf8 \uc870\uc6a9\ud55c \uc2dc\uac04\uc744 \uc911\uc2ec\uc5d0 \ub193\ub294\ub2e4. \uc5d0\ub77c\uc2a4\ubb34\uc2a4\uac00 \ub204\uad6c\uc778\uc9c0 \ucc98\uc74c\uc5d0\ub294 \ubab0\ub77c\ub3c4 \uad1c\ucc2e\ub2e4. \uba3c\uc800 \uc190\uacfc \uc5bc\uad74\uc774 \uc5b4\ub514\ub97c \ud5a5\ud558\ub294\uc9c0 \ubcf4\uace0, \uadf8\uac00 \uc778\ubb38\uc8fc\uc758\uc790\ub85c \uc54c\ub824\uc9c4 \ud559\uc790\ub77c\ub294 \uc815\ubcf4\ub97c \ubcf4\ud0dc \ubcf4\uc790. \uc778\ubb3c\uc758 \uc774\ub984\uacfc \ud654\uba74\uc758 \uc138\ubd80\uac00 \uc5f0\uacb0\ub418\uba74\uc11c \ucd08\uc0c1\ud654\uac00 \uc77d\ud788\uae30 \uc2dc\uc791\ud55c\ub2e4. \uc778\ubb3c\uc740 \uac70\uc758 \uc606\ubaa8\uc2b5\uc73c\ub85c \uc549\uc544 \uc788\ub2e4. \uc815\uba74\uc5d0\uc11c \uc11c\ub85c \ub208\uc744 \ub9de\ucd94\ub294 \ucd08\uc0c1\uacfc \ub2ec\ub9ac, \uad00\uac1d\uc740 \uadf8\uac00 \ubb34\uc5c7\uc744 \ubcf4\uace0 \uc788\ub294\uc9c0 \ub530\ub77c\uac00\uac8c \ub41c\ub2e4. \ub208\uae38\uc740 \ucc45\uc0c1 \ucabd\uc73c\ub85c \ub0b4\ub824\uc624\uace0 \uc190\uc758 \uc6c0\uc9c1\uc784\uacfc \uc774\uc5b4\uc9c4\ub2e4. \uc5bc\uad74\uc774 \uad00\uac1d\uc5d0\uac8c \ubaa8\ub4e0 \uc8fc\uc758\ub97c \uc8fc\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc7a5\uba74\uc758 \uc131\uaca9\uc744 \ub9cc\ub4e0\ub2e4. \uc6b0\ub9ac\ub294 \ub204\uad70\uac00\ub97c \uc548\ub2e4\uace0 \ud560 \ub54c \uc5bc\uad74\uc744 \uae30\uc5b5\ud558\ub294 \uc77c\uc744 \uba3c\uc800 \ub5a0\uc62c\ub9ac\uace4 \ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc774 \uadf8\ub9bc\uc5d0\uc11c\ub294 \uc5bc\uad74\uc744 \ubcf4\ub294 \ubc29\uc2dd \uc790\uccb4\uac00 \uc77c\ud558\ub294 \uc790\uc138\uc640 \uc5f0\uacb0\ub41c\ub2e4. \uc0ac\ub78c\uc758 \uc815\uccb4\uc131\uc744 \ud45c\uc815\ub9cc\uc774 \uc544\ub2c8\ub77c \uc5b4\ub5a4 \ud65c\ub3d9 \uc18d\uc5d0\uc11c \uc774\ud574\ud560 \uc218 \uc788\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc190\uc5d0\ub294 \uae00\uc744 \uc4f0\ub294 \ub3c4\uad6c\uac00 \uc788\uace0 \uc885\uc774 \uc704\uc5d0\uc11c \uc77c\uc774 \uc9c4\ud589\ub41c\ub2e4. \uc190\uc744 \uba3c\uc800 \ubcf4\uace0 \uc5bc\uad74\ub85c \ub3cc\uc544\uc624\uba74 \ub0ae\ucd98 \ub208\uae38\uc774 \ub2e8\uc21c\ud788 \uc218\uc90d\uac70\ub098 \uce68\uc6b8\ud55c \ud45c\uc815\uc73c\ub85c\ub9cc \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uae00\uc744 \uc4f0\ub294 \ud589\ub3d9\uacfc \uad00\ub828\ub41c \uc790\uc138\ub85c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc774 \uc21c\uc11c\uac00 \uac10\uc0c1\uc758 \uc720\uc77c\ud55c \ubc29\ubc95\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uc5bc\uad74\uc5d0\uc11c \uc131\uaca9\uc744 \uace7\ubc14\ub85c \ud310\uc815\ud558\ub824\ub294 \uc2b5\uad00\uc744 \uc7a0\uc2dc \ub2a6\ucd9c \uc218 \uc788\ub2e4. \uc9c0\uae08 \ubb34\uc5c7\uc744 \ud558\ub294\uac00\ub97c \uba3c\uc800 \ubcf4\ub294 \uac83\uc774\ub2e4. \uc0ac\ub78c\uc758 \ubab8\uc9d3\uc744 \uad6c\uccb4\uc801\uc778 \uc77c\uacfc \ud568\uaed8 \uc0b4\ud53c\uba74 \uadfc\uac70 \uc5c6\uc774 \ub9c8\uc74c\uc18d \uc774\uc57c\uae30\ub97c \ubd99\uc774\ub294 \uc77c\ub3c4 \uc904\uc5b4\ub4e0\ub2e4. \uc5d0\ub77c\uc2a4\ubb34\uc2a4\ub294 \ub450\ud23c\ud55c \ubaa8\ud53c \uc637\uacfc \uc5b4\ub450\uc6b4 \ubaa8\uc790\ub97c \uc4f0\uace0 \uc788\ub2e4. \uba38\ub9ac\uc640 \uc5b4\uae68\ub97c \uac10\uc2fc \ub113\uc740 \uba74\uc774 \uc5bc\uad74\uacfc \uc190\uc758 \ubc1d\uc740 \ubd80\ubd84\uc744 \ubc1b\uccd0 \uc900\ub2e4. \ubb34\uc5c7\uc774 \uc5b4\ub461\uace0 \ubb34\uc5c7\uc774 \ub4dc\ub7ec\ub098\ub294\uc9c0 \ube44\uad50\ud558\uba74 \ud654\uba74\uc758 \uc911\uc2ec\uc744 \ub290\ub084 \uc218 \uc788\ub2e4. \uc637\uc774 \ub2f9\uc2dc\uc758 \uc5b4\ub5a4 \uc0dd\ud65c \uc870\uac74\uacfc \uad00\ub828\ub418\ub294\uc9c0 \ub354 \uc5f0\uad6c\ud560 \uc218 \uc788\uc9c0\ub9cc, \uc774\ubbf8\uc9c0 \ud558\ub098\ub85c \ubaa8\ub4e0 \uc2e0\ubd84\uacfc \uacbd\uc81c \uc0c1\ud0dc\ub97c \uacc4\uc0b0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc9c0\uae08\uc740 \uc9c8\uac10\uacfc \uc0c9\uc774 \uc778\ubb3c\uc758 \uc874\uc7ac\uac10\uc744 \uc5b4\ub5bb\uac8c \ub9cc\ub4dc\ub294\uc9c0 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc791\uc740 \uc7a5\uc2dd\ubcf4\ub2e4 \ub113\uc740 \ucc28\ub9bc\uc0c8\uc758 \ub369\uc5b4\ub9ac\uac00 \uc911\uc694\ud55c \ucd08\uc0c1\uc774\ub2e4. \uc5d0\ub77c\uc2a4\ubb34\uc2a4\ub294 \uc778\ubb38\uc8fc\uc758\uc790\ub85c \uc54c\ub824\uc838 \uc788\ub2e4. \uc774 \ub9e5\ub77d\uc758 \uc778\ubb38\uc8fc\uc758\ub294 \uc0ac\ub78c\uc5d0\uac8c \uce5c\uc808\ud558\uc790\ub294 \ud0dc\ub3c4\ub9cc\uc774 \uc544\ub2c8\ub77c \uc5b8\uc5b4\uc640 \uace0\uc804, \ubb38\ud5cc\uc744 \uacf5\ubd80\ud558\uace0 \uc77d\ub294 \ud65c\ub3d9\uacfc \uc5f0\uacb0\ub41c \ub9d0\uc774\ub2e4. \uadf8\ub9bc\uc758 \ud39c\uacfc \uc885\uc774, \uc9d1\uc911\ud558\ub294 \uc790\uc138\ub97c \uadf8 \uc815\ubcf4\uc640 \ud568\uaed8 \ubcfc \uc218 \uc788\ub2e4. \ud55c \uc7a5\uc758 \ucd08\uc0c1\uc774 \uadf8\uc758 \uc0ac\uc0c1\uc744 \ubaa8\ub450 \uc124\uba85\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub7ec\ub098 \uc778\ubb3c\uc774 \uc5b4\ub5a4 \uc77c\uc744 \ud558\ub294 \uc0ac\ub78c\uc778\uc9c0 \uc54c\uace0 \ub098\uba74 \uc791\uac00\uac00 \ubb34\uc5c7\uc744 \uc911\uc2ec\uc5d0 \ub193\uc558\ub294\uc9c0 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4. \uad8c\ub825\uc744 \ub4dc\ub7ec\ub0b4\ub294 \ud070 \ub3c4\uad6c\ub098 \ubb34\uae30 \ub300\uc2e0 \uae00\uc744 \uc4f0\ub294 \ud589\uc704\uac00 \ud654\uba74\uc758 \uc911\uc2ec\uc774\ub77c\ub294 \uc810\uc774 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ub4a4\ucabd\uc5d0\ub294 \ubb34\ub2ac\uac00 \uc788\ub294 \ucee4\ud2bc\uc774 \ubcf4\uc778\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubc30\uacbd\uc774 \uc778\ubb3c\ubcf4\ub2e4 \ud06c\uac8c \uc774\uc57c\uae30\ub97c \ub04c\uace0 \uac00\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5bc\uad74\uacfc \uc190, \uc637\uc758 \uba74\uc744 \ubcf8 \ub4a4 \ucee4\ud2bc\uc73c\ub85c \ub208\uc744 \uc62e\uae30\uba74 \uc778\ubb3c\uc758 \uc724\uacfd\uacfc \uc8fc\ubcc0\uc758 \uad00\uacc4\ub97c \ub290\ub084 \uc218 \uc788\ub2e4. \ubaa8\ub4e0 \uc7a5\uc2dd\uc744 \uc0c1\uc9d5 \uc0ac\uc804\uc73c\ub85c \ud574\ub3c5\ud558\ub824 \uc560\uc4f8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ubc18\ubcf5\ub418\ub294 \ubb34\ub2ac\uc640 \ubd80\ub4dc\ub7fd\uac8c \uaebe\uc774\ub294 \uc637, \uc5bc\uad74\uc758 \uc120\uc774 \uc11c\ub85c \ub2e4\ub978 \ub9ac\ub4ec\uc744 \ub9cc\ub4e0\ub2e4\ub294 \uc810\uc744 \ubcf4\uc790. \uc815\uc9c0\ub41c \uc778\ubb3c \ud558\ub098\uc758 \uadf8\ub9bc\uc5d0\uc11c\ub3c4 \ubaa8\uc591\uacfc \uc7ac\ub8cc\ub97c \ube44\uad50\ud558\uba70 \ubcfc \uc77c\uc774 \ub0a8\uc544 \uc788\ub2e4. \ubcf4\ud1b5 \ucd08\uc0c1\ud654\ub97c \ucc0d\uac70\ub098 \uadf8\ub9b0\ub2e4\uace0 \ud558\uba74 \ud3c9\uc18c\uc758 \uc77c\uc744 \uba48\ucd94\uace0 \uc790\uc138\ub97c \uc7a1\ub294 \uc7a5\uba74\uc744 \ub5a0\uc62c\ub9b0\ub2e4. \uc774 \uc791\ud488\uc740 \uc77c\ud558\ub294 \ubaa8\uc2b5 \uc790\uccb4\ub97c \uc778\ubb3c \uc18c\uac1c\uc758 \ubc29\uc2dd\uc73c\ub85c \uc0bc\ub294\ub2e4. \uadf8\ub798\uc11c \uad00\uac1d\uc740 \ud55c \uc0ac\ub78c\uc774 \ubcf4\ub0b4\ub294 \uc2dc\uac04\uc758 \uc77c\ubd80\ub97c \ubcf4\uac8c \ub418\ub294 \ub4ef\ud55c \ub290\ub08c\uc744 \ubc1b\uc744 \uc218 \uc788\ub2e4. \ubb3c\ub860 \uc2e4\uc81c \uc791\uc5c5 \uc911 \uc6b0\uc5f0\ud788 \ucc0d\ud78c \uc0ac\uc9c4\uacfc\ub294 \ub2e4\ub974\ub2e4. \ud654\uac00\ub294 \uc778\ubb3c\uc758 \ubc29\ud5a5\uacfc \uc190, \ubb3c\uac74\uacfc \ubc30\uacbd\uc744 \uc120\ud0dd\ud574 \ud654\uba74\uc744 \ub9cc\ub4e0\ub2e4. \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \uc778\uc0c1\uacfc \uc138\uc2ec\ud55c \uad6c\uc131\uc740 \ud568\uaed8 \uc874\uc7ac\ud55c\ub2e4. \uadf8\uac83\uc744 \uc54c\uace0 \ub098\uba74 \uc870\uc6a9\ud55c \uadf8\ub9bc\uc774 \ubb34\uc2ec\ud558\uac8c \ub9cc\ub4e4\uc5b4\uc9c4 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc774 \ubcf4\uc778\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uc61b \ub8e8\ube0c\ub974 \ub3c4\ub85d\uc5d0 \uc218\ub85d\ub41c \uc2e4\uc81c \uc791\ud488\uc758 \uc0c9\ucc44 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \ud604\ub300\uc778\uc774 \ube44\uc2b7\ud55c \ud559\uc790\ub97c \uc0c8\ub85c \uadf8\ub9b0 \uc0bd\ud654\uac00 \uc544\ub2c8\ub77c \ud640\ubc14\uc778\uc758 \ud654\uba74 \uad6c\uc131\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc790\ub8cc\ub2e4. \uc5bc\uad74\uacfc \uc190, \ucc28\ub9bc\uc0c8\uc758 \ud070 \uad00\uacc4\ub97c \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uc61b \uc778\uc1c4\uc758 \uc0c9\uacfc \uc138\ubd80\ub294 \uc624\ub298 \uc2e4\ubb3c\uc744 \uc644\uc804\ud788 \ub300\uc2e0\ud558\uc9c0 \uc54a\ub294\ub2e4. \uadf8\ub807\ub2e4\uace0 \uac10\uc0c1\uc774 \uc2dc\uc791\ub418\uc9c0 \ubabb\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc791\uc740 \ud39c \ub05d\uc758 \ubaa8\ub4e0 \uc120\uc744 \ub9de\ud788\ub824 \ud558\uae30\ubcf4\ub2e4, \ub208\uae38\uc774 \uc5b4\ub514\ub85c \ub0b4\ub824\uac00\uace0 \uc190\uc774 \uc5b4\ub5a4 \ubc29\ud5a5\uc744 \ud5a5\ud558\ub294\uc9c0\ubd80\ud130 \ubcf4\uba74 \ub41c\ub2e4. \uac00\uae4c\uc6b4 \ub2e8\uc11c\uac00 \ucda9\ubd84\ud55c \ucd9c\ubc1c\uc810\uc774 \ub41c\ub2e4. \uadf8\ub9bc\uc744 \ubcf8 \ub4a4 \uc5d0\ub77c\uc2a4\ubb34\uc2a4\ub77c\ub294 \uc774\ub984\uacfc \ud568\uaed8 \uae00\uc744 \uc4f0\ub294 \uc190\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc5b4\ub5a4 \uc0ac\ub78c\uc744 \uae30\uc5b5\ud558\ub294 \uc77c\uc740 \uc774\ub984\uacfc \uc0dd\ubab0\ub144\uc758 \ubaa9\ub85d\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uadf8\uac00 \ubb34\uc5c7\uc744 \ud558\ub294 \uc0ac\ub78c\uc73c\ub85c \ud45c\ud604\ub418\uc5c8\ub294\uc9c0 \uc544\ub294 \uac83\ub3c4 \ud558\ub098\uc758 \uc9c0\uc2dd\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \ub2e4\ub978 \ud559\uc790\uc758 \ucd08\uc0c1\uc744 \ub9cc\ub098\uba74 \ucc45\uc744 \ub4e4\uace0 \uc788\ub294\uc9c0, \uad00\uac1d\uc744 \ubcf4\ub294\uc9c0, \uc77c\ud558\ub294 \ubaa8\uc2b5\uc744 \ubcf4\uc5ec \uc8fc\ub294\uc9c0 \ube44\uad50\ud574 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uac19\uc740 \uc885\ub958\uc758 \uc0ac\ub78c\uc744 \uadf8\ub9b0 \ucd08\uc0c1\ub4e4\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc120\ud0dd\uc744 \ud55c\ub2e4. \ud640\ubc14\uc778\uc758 \uc870\uc6a9\ud55c \ucc45\uc0c1\uc740 \uadf8\ub7f0 \ucc28\uc774\ub97c \uc54c\uc544\ubcf4\uac8c \ud558\ub294 \uc88b\uc740 \uc2dc\uc791\uc774\ub2e4."}, {"id": "man-ray-chess-photo-layout", "title": "\uccb4\uc2a4 \ub9d0\uc744 \uc5b4\ub514\uc5d0 \ub458\uc9c0 \uc624\ub798\ub41c \uc0ac\uc9c4\uc5d0 \ubb3c\uc5c8\ub2e4", "summary": "\ub9e8 \ub808\uc774\uc758 \uccb4\uc2a4 \uc138\ud2b8\ub97c \uc804\uc2dc\ud558\uba70 \ub9d0\uc758 \uc704\uce58\ub97c \uace0\ub974\ub358 \uacfc\uc815\uc744 \ub530\ub77c\uac11\ub2c8\ub2e4.", "category": "ideas", "category_title": "\uc0dd\uac01\uacfc \uc9c0\uc2dd", "subcategory": "\uc608\uc220\uc744 \ubcf4\ub294 \ubc95", "categories": ["ideas"], "url": "stories/man-ray-chess-photo-layout/index.html", "image": "../media/man-ray-chess-photo-layout.jpg", "alt": "\uccb4\uc2a4 \ub9d0\uc744 \uc5b4\ub514\uc5d0 \ub458\uc9c0 \uc624\ub798\ub41c \uc0ac\uc9c4\uc5d0 \ubb3c\uc5c8\ub2e4\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\uccb4\uc2a4 \ub9d0\uc744 \uc5b4\ub514\uc5d0 \ub458\uc9c0 \uc624\ub798\ub41c \uc0ac\uc9c4\uc5d0 \ubb3c\uc5c8\ub2e4 \uc791\ud488 \uc804\uc2dc\uac00 \uc791\uc740 \ucd94\ub9ac \ubb38\uc81c\uac00 \ub41c \uc21c\uac04 \ub9e8 \ub808\uc774\uc758 \uccb4\uc2a4 \uc138\ud2b8\ub97c \uc804\uc2dc\ud558\uba70 \ub9d0\uc758 \uc704\uce58\ub97c \uace0\ub974\ub358 \uacfc\uc815\uc744 \ub530\ub77c\uac11\ub2c8\ub2e4. \uc608\uc220\uc744 \ubcf4\ub294 \ubc95 \uc0dd\uac01\uacfc \uc9c0\uc2dd \uccb4\uc2a4 \uc138\ud2b8\ub97c \uc804\uc2dc\ud55c\ub2e4\uace0 \ud558\uba74 \ub9d0\ub4e4\uc744 \uc608\uc058\uac8c \uc138\uc6cc \ub450\uba74 \ub420 \uac83 \uac19\ub2e4. \uadf8\ub7f0\ub370 \uac8c\uc784 \ub3c4\uad6c\ub294 \uc704\uce58\uc5d0 \ub530\ub77c \uc804\ud600 \ub2e4\ub978 \uc7a5\uba74\uc774 \ub41c\ub2e4. \ub9c9 \uc2dc\uc791\ud55c \ud310\uc77c \uc218\ub3c4 \uc788\uace0, \ub204\uad70\uac00 \ub2e4\uc74c \uc218\ub97c \uace0\ubbfc\ud558\ub294 \ud310\uc77c \uc218\ub3c4 \uc788\ub2e4. \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc740 \ub9e8 \ub808\uc774\uac00 \ub514\uc790\uc778\ud55c \uccb4\uc2a4 \uc138\ud2b8\ub97c \ub193\uc73c\uba70 \uc774\ub7f0 \uace0\ubbfc\uc744 \ud588\ub2e4. \uc5b4\ub5bb\uac8c \ubc30\uce58\ud574\uc57c \uc774 \ubb3c\uac74\uc744 \ub354 \uc798 \ubcf4\uc5ec \uc904 \uc218 \uc788\uc744\uae4c. \uadf8 \uc9c8\ubb38\uc740 \uc624\ub798\ub41c \uc0ac\uc9c4 \ud55c \uc7a5\uc73c\ub85c \uc774\uc5b4\uc84c\ub2e4. \uacf5\uc2dd \uc124\uba85\uc5d0 \ub530\ub974\uba74 \ub9e8 \ub808\uc774\ub294 1920\ub144\uc5d0 \uccab \uccb4\uc2a4 \uc138\ud2b8\ub97c \ub514\uc790\uc778\ud588\ub2e4. \ubbf8\uc220\uad00\uc758 \uc138\ud2b8\ub294 \uc778\ub3c4 \uc778\ub3c4\ub974\uc758 \ub9c8\ud558\ub77c\uc790\ub97c \uc704\ud574 1927\ub144\uc5d0 \ub9cc\ub4e0 \uac83\uc73c\ub85c \uc18c\uac1c\ub41c\ub2e4. \uc608\uc220\uac00\uac00 \ub9cc\ub4e0 \uccb4\uc2a4 \ub9d0\uc774\ub2c8 \uc870\uac01\uc73c\ub85c \ubcfc \uc218 \uc788\uc9c0\ub9cc, \ub3d9\uc2dc\uc5d0 \uc2e4\uc81c \uac8c\uc784\uc758 \uc790\ub9ac\ub97c \uac00\uc9c4 \ubb3c\uac74\uc774\ub2e4. \ub9d0\uc744 \ud55c \uac1c\ub9cc \uc55e\uc73c\ub85c \uc62e\uaca8 \ub193\ub294 \uac83\uacfc \uac8c\uc784 \uc911\uac04\uc758 \ud310\uc744 \ub9cc\ub4dc\ub294 \uac83\uc740 \ubcf4\ub294 \uc0ac\ub78c\uc5d0\uac8c \ub2e4\ub978 \ub290\ub08c\uc744 \uc900\ub2e4. \ubbf8\uc220\uad00\uc740 \ub2e4\ub978 \uc138\ud2b8\uc758 \uc0ac\uc9c4\uc744 \ucc38\uace0\ud574 \ubc30\uce58\ud558\uae30\ub3c4 \ud588\uc9c0\ub9cc \ub354 \uc624\ub798\ub41c \uc790\ub8cc\ub97c \uc0b4\ud3c8\ub2e4. \uc911\uc694\ud55c \ub2e8\uc11c\ub294 1921\ub144 \ub9e8 \ub808\uc774\uc758 \uc790\ud654\uc0c1 \uc0ac\uc9c4\uc774\uc5c8\ub2e4. \ubb38\uc81c\ub294 \uc0ac\uc9c4\uc5d0 \uccb4\uc2a4\ud310 \uc77c\ubd80\ub9cc \ub098\uc640 \uc788\ub2e4\ub294 \uc810\uc774\uc5c8\ub2e4. \uae30\uad00 \uae00\uc758 \ud544\uc790\ub294 \uc0ac\uc9c4\uc744 \ud655\ub300\ud558\uace0 \ubcf4\uc774\ub294 \uce78\uc758 \uac00\uc7a5\uc790\ub9ac\ub97c \ub530\ub77c \ud3c9\ud589\uc120\uc744 \uadf8\uc5c8\ub2e4. \ubcf4\uc774\ub294 \ub9d0\uc758 \uc704\uce58\ub97c \ucc3e\uace0, \uccb4\uc2a4\uc758 \uaddc\uce59\uc744 \uc0dd\uac01\ud574 \uac00\ub824\uc9c4 \ubd80\ubd84\uc758 \ubc30\uce58\ub97c \ucd94\uc815\ud588\ub2e4. \uc0ac\uc9c4\uc744 \ubcf4\ub294 \uc77c\uc774 \uc791\uc740 \ud37c\uc990 \ud480\uc774\uac00 \ub41c \uac83\uc774\ub2e4. \uccb4\uc2a4 \uc138\ud2b8\ub97c \uc870\uac01\ucc98\ub7fc \ubcf8\ub2e4\uba74 \uac1c\ubcc4 \ub9d0\uc758 \ud615\ud0dc\uc640 \uc7ac\ub8cc\uac00 \uba3c\uc800 \uc911\uc694\ud574 \ubcf4\uc778\ub2e4. \uac8c\uc784\uc758 \ub3c4\uad6c\ub85c \ubcf4\uba74 \uc5b4\ub5a4 \ub9d0\uc774 \uc5b4\ub290 \uce78\uc5d0 \uc788\ub294\uc9c0\ub3c4 \uc758\ubbf8\ub97c \ub9cc\ub4e0\ub2e4. \uac19\uc740 \ubb3c\uac74\uc744 \ub193\uace0\ub3c4 \uc804\uc2dc\ub294 \ub450 \uc9c8\ubb38 \uc0ac\uc774\uc5d0\uc11c \uc120\ud0dd\ud574\uc57c \ud55c\ub2e4. \ub2e8\uc815\ud558\uac8c \uc904 \uc138\uc6b0\ub294 \uac83\uc774 \uc5b8\uc81c\ub098 \uc81c\uc791\uc790\uac00 \uc990\uae30\ub358 \uac8c\uc784\uc758 \ubaa8\uc2b5\uc744 \uc798 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \uc544\ub2d0 \uc218 \uc788\ub2e4. \ubbf8\uc220\uad00\uc740 \ud55c\ub54c \uc878 \ud558\ub098\ub9cc \uc55e\uc73c\ub85c \uc62e\uaca8 \uc804\uc2dc\ud588\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc774\ud6c4 \ub2e4\ub978 \uc18c\uc7a5 \uc138\ud2b8\uc758 \uc0ac\uc9c4\uc744 \ucc38\uace0\ud55c \ubc30\uce58\ub3c4 \uc0ac\uc6a9\ud588\ub2e4. \uc791\ud488\uc774 \ub0a8\uc544 \uc788\ub2e4\uace0 \uadf8 \uc804\uc2dc \ubc29\uc2dd\uc774 \ucc98\uc74c\ubd80\ud130 \ud558\ub098\ub85c \uc815\ud574\uc838 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubcf4\uc874\ub41c \ubb3c\uac74\uacfc \uadf8\uac83\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ubc30\uc5f4\uc740 \uc11c\ub85c \uc5f0\uacb0\ub418\uc9c0\ub9cc \ub2e4\ub978 \uce35\uc758 \uacb0\uc815\uc774\ub2e4. 1921\ub144 \uc790\ud654\uc0c1 \uc0ac\uc9c4\uc740 \uccb4\uc2a4\ud310 \uc804\uccb4\ub97c \uba85\ud655\ud788 \ubcf4\uc5ec \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \ud544\uc790\ub294 \ud655\ub300 \uc0ac\uc9c4\uc5d0\uc11c \ubcf4\uc774\ub294 \uce78\uc758 \uac00\uc7a5\uc790\ub9ac\ub97c \ub530\ub77c \uc120\uc744 \uae0b\uace0 \ud310\uc758 \ubc29\ud5a5\uc744 \uac00\ub2a0\ud588\ub2e4. \uc0ac\uc9c4\uc744 \ud06c\uac8c \ubcf4\uba74 \uc800\uc808\ub85c \ubaa8\ub4e0 \ub2f5\uc774 \ub098\uc624\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uc774\ubbf8 \ubcf4\uc774\ub294 \uc815\ubcf4\uc758 \uad00\uacc4\ub97c \uc774\uc6a9\ud574 \uac00\ub824\uc9c4 \ubd80\ubd84\uc744 \uc881\ud600 \uac04 \uac83\uc774\ub2e4. \uccb4\uc2a4 \uaddc\uce59\ub3c4 \ubcf4\uc870 \ub2e8\uc11c\uac00 \ub418\uc5c8\ub2e4. \uc5b4\ub5a4 \ub9d0\uc774 \uc6c0\uc9c1\uc600\ub2e4\uba74 \ub2e4\ub978 \ub9d0\uc758 \uac00\ub2a5\ud55c \uc790\ub9ac\uac00 \uc904\uc5b4\ub4e4 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ub2e4\ub9cc \uaddc\uce59\uc5d0 \ub9de\ub294 \ubc30\uce58\ub97c \ucc3e\ub294 \uac83\uacfc \uc2e4\uc81c \uadf8\ub0a0\uc758 \uac8c\uc784\uc744 \ud655\uc815\ud558\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uc774 \ucc28\uc774\ub97c \ub193\uce58\uba74 \ud765\ubbf8\ub85c\uc6b4 \uc5f0\uad6c \uc81c\uc548\uc774 \ub9c8\uce58 \uc644\uc804\ud788 \uc785\uc99d\ub41c \uc5ed\uc0ac \uc7a5\uba74\ucc98\ub7fc \ubc14\ub00c\uc5b4 \ubc84\ub9b0\ub2e4. \uae30\uad00 \uae00\uc758 \ud544\uc790\ub294 \ud770 \ub9d0\uc744 \ub450\ub294 \ub9e8 \ub808\uc774\uac00 \ub2e4\uc12f \ubc88\uc9f8 \uc218\ub97c \ub454 \ub4a4 \ud30c\uc774\ud504\uc5d0 \ubd88\uc744 \ubd99\uc774\ub294 \uc21c\uac04\uc73c\ub85c \ubcf4\uba74 \ubc30\uce58\uac00 \uc798 \ub9de\ub294\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8 \ub9d0\uc740 \uc0ac\uc9c4\uc774 \uc9c1\uc811 \ubaa8\ub4e0 \uc218\uc21c\uc744 \uae30\ub85d\ud558\uace0 \uc788\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \ubcf4\uc774\ub294 \uc790\ub8cc\uc640 \uac8c\uc784\uc758 \uac00\ub2a5\uc131\uc744 \uc774\uc5b4 \ub9cc\ub4e0 \ud574\uc11d\uc774\ub2e4. \uae00\uc740 \ub9c8\uc9c0\ub9c9\uc5d0\ub3c4 \ub9de\uac8c \ubcf5\uc6d0\ud588\ub294\uc9c0\ub97c \uc9c8\ubb38\uc73c\ub85c \ub0a8\uae34\ub2e4. \ubbf8\uc220\uad00\uc774 \uadf8 \uc81c\uc548\uc744 \uc804\uc2dc \ubc30\uce58\uc5d0 \ubc18\uc601\ud588\ub2e4\ub294 \uc0ac\uc2e4\ub3c4 \uac00\uc124\uc758 \uc131\uaca9\uc744 \uc5c6\uc560\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc804\uc2dc\uc5d0\ub294 \uc9c0\uae08 \uac00\uc9c4 \uc790\ub8cc\ub85c \uac00\uc7a5 \uc801\uc808\ud558\ub2e4\uace0 \ud310\ub2e8\ud55c \uc120\ud0dd\uc774 \ub4e4\uc5b4\uac08 \uc218 \uc788\ub2e4. \ud655\uc2e0\uc758 \uc815\ub3c4\ub97c \uc194\uc9c1\ud558\uac8c \ud45c\uc2dc\ud558\uba74\uc11c\ub3c4 \uad00\ub78c\uc790\uc5d0\uac8c \uc0dd\uac01\ud560 \uc7a5\uba74\uc744 \uc81c\uc2dc\ud558\ub294 \uac83\uc774\ub2e4. \ubc15\ubb3c\uad00\uc740 \ubb3c\uac74\uc744 \ubcf4\uad00\ud558\ub294 \uacf3\uc774\uba74\uc11c \uc774\ub7f0 \ud310\ub2e8\uc744 \uc124\uba85\ud558\ub294 \uacf3\uc774\uae30\ub3c4 \ud558\ub2e4. \uccb4\uc2a4\ud310\uc740 \uc0ac\uc6a9\uc790\uac00 \uc190\uc744 \ub308 \ub54c \ubc30\uce58\uac00 \ubc14\ub00c\ub294 \ubb3c\uac74\uc774\ub2e4. \uc644\uc131\ud55c \ub4a4 \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294 \uc870\uac01\ub9cc \uae30\ub300\ud558\uba74 \uc774 \ud2b9\uc131\uc744 \ub193\uce58\uac8c \ub41c\ub2e4. \ub9e8 \ub808\uc774\uac00 \uccb4\uc2a4\ub97c \uc990\uacbc\uace0 \uc0c8\ub85c\uc6b4 \ub9d0\uc758 \ud615\ud0dc\ub97c \uace0\uc548\ud588\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ud568\uaed8 \ubcf4\uba74, \ub514\uc790\uc778\uacfc \ub180\uc774\uac00 \uc11c\ub85c \ub2e4\ub978 \uc138\uacc4\ub85c\ub9cc \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\uc558\uc74c\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ud604\uc7ac \uc804\uc2dc\uc758 \ud2b9\uc815 \uce78\uc744 \uc815\ub2f5\ucc98\ub7fc \uc678\uc6b0\uae30\ubcf4\ub2e4 \ubc30\uc5f4\uc744 \uc815\ud560 \ub54c \uc5b4\ub5a4 \uc790\ub8cc\ub97c \ubcf4\uc558\ub294\uc9c0 \ubb3c\uc5b4\ubcf4\uc790. \uc0ac\uc9c4\uacfc \uc791\ud488, \uaddc\uce59\uacfc \ud050\ub808\uc774\ud130\uc758 \ud310\ub2e8\uc774 \ud568\uaed8 \uc791\uc6a9\ud55c\ub2e4. \uc791\uc740 \ub9d0\uc744 \uc5b4\ub514\uc5d0 \ub193\uc744\uc9c0\ub77c\ub294 \ubb38\uc81c\uc5d0\uc11c \uc608\uc220\ud488\uc774 \uc6d0\ub798 \uc5b4\ub5bb\uac8c \uc4f0\uc600\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub824\ub294 \ub178\ub825\uae4c\uc9c0 \uc77d\ud78c\ub2e4. \uc804\uc2dc\uc7a5\uc758 \uc815\uc9c0\ud55c \ubaa8\uc2b5 \ub4a4\uc5d0\ub3c4 \uc6c0\uc9c1\uc600\ub358 \uc190\uc758 \uc2dc\uac04\uc774 \ub0a8\uc544 \uc788\ub2e4. \uadf8\uac00 \uc81c\uc548\ud55c \ubc30\uce58\ub294 \uc2e4\uc81c \uc804\uc2dc\ub97c \ub2e4\uc2dc \ub193\ub294 \ub370 \uc0ac\uc6a9\ub418\uc5c8\ub2e4\uace0 \uae00\uc740 \uc804\ud55c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc0ac\uc9c4 \ubc16\uc758 \ub9d0\uae4c\uc9c0 \uc644\ubcbd\ud558\uac8c \ud655\uc778\ud588\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud544\uc790 \uc5ed\uc2dc \uc790\uc2e0\uc758 \uac00\uc124\uc774 \ub9de\ub294\uc9c0 \uc9c8\ubb38\uc744 \ub0a8\uacbc\ub2e4. \uc774 \uc774\uc57c\uae30\uc758 \uc7ac\ubbf8\ub294 \uc791\ud488\uc758 \uc81c\ubaa9\uc774\ub098 \uac00\uaca9\uc5d0 \uc788\uc9c0 \uc54a\ub2e4. \uccb4\uc2a4 \ub9d0 \uba87 \uac1c\ub97c \uc5b4\ub514\uc5d0 \ub458\uc9c0 \uc815\ud558\ub824\uace0 \uc0ac\uc9c4\uacfc \uac8c\uc784 \uaddc\uce59\uc744 \ud568\uaed8 \uc0b4\ud3c8\ub2e4\ub294 \ub370 \uc788\ub2e4. \uc804\uc2dc\uc7a5 \uc18d \uac00\uc9c0\ub7f0\ud55c \ubc30\uce58\uc5d0\ub3c4 \ub204\uad70\uac00\uc758 \uae34 \uad00\ucc30\uacfc \uc870\uc2ec\uc2a4\ub7ec\uc6b4 \ucd94\ub9ac\uac00 \ub4e4\uc5b4 \uc788\uc744 \uc218 \uc788\ub2e4."}, {"id": "marcus-aurelius-meditations", "title": "\ub9c8\ub974\ucfe0\uc2a4 \uc544\uc6b0\ub810\ub9ac\uc6b0\uc2a4 \uba85\uc0c1\ub85d \u2014 \ud669\uc81c\ub3c4 \uc790\uc2e0\uc5d0\uac8c \ub9d0\uc744 \uac78\uc5c8\ub2e4", "summary": "\uc9e7\uc740 \uae30\ub85d\ub4e4\uc744 \ud1b5\ud574 \ud669\uc81c\uc758 \uc0dd\uc560\uc640 \uc2a4\ud1a0\uc544 \ucca0\ud559\uc758 \uc77c\uc0c1\uc801\uc778 \uc9c8\ubb38\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "ideas", "category_title": "\uc0dd\uac01\uacfc \uc9c0\uc2dd", "subcategory": "\ucca0\ud559\uc758 \uc9c8\ubb38", "categories": ["ideas"], "url": "stories/marcus-aurelius-meditations/index.html", "image": "../media/marcus-aurelius-meditations.jpg", "alt": "\uba85\uc0c1\ub85d\uc758 \uc61b \uc601\ubb38\ud310\uc5d0 \uc218\ub85d\ub41c \ub9c8\ub974\ucfe0\uc2a4 \uc544\uc6b0\ub810\ub9ac\uc6b0\uc2a4\uc758 \ucd08\uc0c1 \uc7ac\ud604 \ub3c4\ud310.", "text": "\ub9c8\ub974\ucfe0\uc2a4 \uc544\uc6b0\ub810\ub9ac\uc6b0\uc2a4 \uba85\uc0c1\ub85d \u2014 \ud669\uc81c\ub3c4 \uc790\uc2e0\uc5d0\uac8c \ub9d0\uc744 \uac78\uc5c8\ub2e4 \ub2e4\ub978 \uc0ac\ub78c\uc744 \ubc14\uafb8\uae30 \uc804\uc5d0 \uc0b4\ud53c\ub294 \ud310\ub2e8\uacfc \ud558\ub8e8\uc758 \ud589\ub3d9 \uc9e7\uc740 \uae30\ub85d\ub4e4\uc744 \ud1b5\ud574 \ud669\uc81c\uc758 \uc0dd\uc560\uc640 \uc2a4\ud1a0\uc544 \ucca0\ud559\uc758 \uc77c\uc0c1\uc801\uc778 \uc9c8\ubb38\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \ucca0\ud559\uc758 \uc9c8\ubb38 \uc0dd\uac01\uacfc \uc9c0\uc2dd \uc544\uce68\uc5d0 \uc77c\uc5b4\ub098 \ud574\uc57c \ud560 \uc77c\uc744 \uc2dc\uc791\ud558\uae30 \uc2eb\uc740 \ub0a0\uc774 \uc788\ub2e4. \uc624\ub798\ub41c \ucc45\uc5d0\uc11c \uc774\uc640 \ube44\uc2b7\ud55c \ub9dd\uc124\uc784\uc744 \ub9cc\ub098\uba74 \uc800\uc790\uac00 \ub85c\ub9c8 \ud669\uc81c\uc600\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc870\uae08 \uc758\uc678\ub85c \ub290\uaef4\uc9c4\ub2e4. \ubaa8\ub4e0 \uba85\ub839\uc744 \ub0b4\ub9b4 \uc218 \uc788\uc744 \ub4ef\ud55c \uc0ac\ub78c\ub3c4 \uc790\uc2e0\uc758 \ud558\ub8e8\ub97c \uc2a4\uc2a4\ub85c \uc124\ub4dd\ud574\uc57c \ud588\ub358 \uac83\uc774\ub2e4. \ub9c8\ub974\ucfe0\uc2a4 \uc544\uc6b0\ub810\ub9ac\uc6b0\uc2a4\uc758 \u300e\uba85\uc0c1\ub85d\u300f\uc740 \uc9e7\uc740 \uae30\ub85d\ub4e4\uc744 \ud1b5\ud574 \uc790\uc2e0\uc744 \ub2e4\ub8e8\ub294 \ubc95\uc744 \ub418\ubb3b\ub294 \ucc45\uc774\ub2e4. \uc644\uc131\ub41c \uc815\ub2f5\uc744 \uc544\ub7ab\uc0ac\ub78c\uc5d0\uac8c \uc120\ud3ec\ud558\ub294 \uc5f0\uc124\ucc98\ub7fc\ub9cc \uc77d\uae30\ubcf4\ub2e4, \uc65c \uc5b4\ub5a4 \ub9d0\uc744 \uc790\uae30\uc5d0\uac8c \uac70\ub4ed \ud574\uc57c \ud588\ub294\uc9c0 \uc0dd\uac01\ud558\uba70 \ub4e4\uc5b4\uac00 \ubcf4\uba74 \uac00\uae5d\ub2e4. \uadf8\ub294 121\ub144\uc5d0 \ud0dc\uc5b4\ub098 180\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub0ac\ub2e4. \uc548\ud1a0\ub2c8\ub204\uc2a4 \ud53c\uc6b0\uc2a4\uc758 \ub4a4\ub97c \uc774\uc5b4 161\ub144\uc5d0 \ud669\uc81c\uac00 \ub418\uc5c8\uace0, \ud1b5\uce58\uc758 \uc2dc\uac04\uc5d0\ub294 \uc804\uc7c1\uacfc \uc5ec\ub7ec \uc5b4\ub824\uc6c0\uc774 \uc788\uc5c8\ub2e4. \ucc45\uc5d0\uc11c \ub9d0\ud558\ub294 \ud3c9\uc815\uc740 \ubaa8\ub4e0 \uc678\ubd80 \ubb38\uc81c\uac00 \ud574\uacb0\ub41c \uc870\uc6a9\ud55c \ubc29\uc5d0\uc11c\ub9cc \uc0dd\uac01\ud55c \uc8fc\uc81c\uac00 \uc544\ub2c8\uc5c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \ud798\ub4e0 \uc77c\uc744 \uacaa\uc5c8\uc73c\ub2c8 \ubaa8\ub4e0 \ud310\ub2e8\uc774 \uc633\uc558\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud669\uc81c\ub77c\ub294 \uc9c0\uc704\uc5d0\ub294 \ud070 \uad8c\ud55c\uacfc \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \ucc45\uc784\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \ucca0\ud559\uc744 \uc4f0\ub294 \uc0ac\ub78c\uacfc \uc2e4\uc81c\ub85c \ud1b5\uce58\ud558\ub294 \uc0ac\ub78c\uc744 \ubaa8\ub450 \ubcf4\uc544\uc57c, \ud55c \uc0ac\ub78c\uc744 \uadf8\uc800 \ud6cc\ub96d\ud55c \uaca9\uc5b8\uc758 \uc774\ub984\uc73c\ub85c\ub9cc \ub9cc\ub4e4\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uc81c1\uad8c\uc5d0\uc11c\ub294 \uac00\uc871\uacfc \uc2a4\uc2b9, \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\uc5d0\uac8c\uc11c \ubb34\uc5c7\uc744 \ubc30\uc6e0\ub294\uc9c0 \ub3cc\uc544\ubcf8\ub2e4. \uc2a4\uc2a4\ub85c\ub97c \uc544\ubb34\uc5d0\uac8c\ub3c4 \ube5a\uc9c0\uc9c0 \uc54a\uc740 \uc9c0\ud61c\ub85c\uc6b4 \uc0ac\ub78c\uc73c\ub85c \uc18c\uac1c\ud558\ub294 \ubc29\uc2dd\uacfc \ub2e4\ub974\ub2e4. \uc5b4\ub5a4 \ud0dc\ub3c4\ub97c \ubcf4\uace0 \uc775\ud614\uc73c\uba70 \uc5b4\ub5a4 \ub3c4\uc6c0\uc744 \ubc1b\uc558\ub294\uc9c0\ub97c \uba3c\uc800 \ub193\ub294\ub2e4. \uc774 \ubd80\ubd84\uc744 \uc77d\uc744 \ub54c\ub294 \uc774\ub984\uc744 \uc804\ubd80 \uc678\uc6b0\uae30\ubcf4\ub2e4 \ubc30\uc6c0\uc758 \ub0b4\uc6a9\uc774 \uc5b4\ub5bb\uac8c \uad6c\uccb4\uc801\uc778 \ud589\ub3d9\uacfc \uc5f0\uacb0\ub418\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \ucc38\ub294 \ud0dc\ub3c4\uc640 \ub9d0\uc744 \ub2e4\ub8e8\ub294 \ubc95, \uc77c\ud558\ub294 \uc790\uc138\ub294 \ucd94\uc0c1\uc801\uc778 \ub355\ubaa9\uc774\uba74\uc11c \ub3d9\uc2dc\uc5d0 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc0dd\ud65c\uc5d0\uc11c \ubcfc \uc218 \uc788\ub294 \uac83\uc774\uc5c8\ub2e4. \ucca0\ud559\uc758 \uc2dc\uc791\uc5d0 \uad00\uacc4\uc758 \uae30\uc5b5\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\uc758 \ubb34\ub840\uc640 \uace0\uc9d1\uc744 \uc0dd\uac01\ud558\ub294 \ub300\ubaa9\ub4e4\ub3c4 \ub098\uc628\ub2e4. \uc138\uc0c1\uc5d0 \ubd88\ud3b8\ud55c \uc0ac\ub78c\uc774 \uc5c6\uc5b4\uc57c\ub9cc \ud3c9\uc628\ud560 \uc218 \uc788\ub2e4\uace0 \uae30\ub300\ud558\uba74 \ud558\ub8e8\uc758 \uc870\uac74\uc744 \ub108\ubb34 \uc881\uac8c \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \uc800\uc790\ub294 \uc678\ubd80\uc5d0 \ub300\ud55c \ubd88\ud3c9\uc5d0 \uc55e\uc11c \uc790\uc2e0\uc774 \uc5b4\ub5a4 \ud310\ub2e8\uacfc \ud589\ub3d9\uc744 \ud560\uc9c0 \ub3cc\uc544\ubcf4\ub824 \ud55c\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub0a8\uc774 \ud574\ub97c \ub07c\uccd0\ub3c4 \uc544\ubb34 \uc77c \uc5c6\ub2e4\uace0 \ubc1b\uc544\ub4e4\uc774\ub77c\ub294 \ub9d0\ub85c \ub2e8\uc21c\ud654\ud558\uba74 \uc548 \ub41c\ub2e4. \ubb34\uc5c7\uc744 \uc798\ubabb\uc774\ub77c\uace0 \ubcf4\uace0 \uc5b4\ub5a4 \ud589\ub3d9\uc744 \ucde8\ud560\uc9c0, \uadf8 \uacfc\uc815\uc5d0\uc11c \uc790\uc2e0\uae4c\uc9c0 \ubb34\ubd84\ubcc4\ud574\uc9c0\uc9c0 \uc54a\uc744\uc9c0 \uc0b4\ud53c\ub294 \ubb38\uc81c\ub2e4. \ucc38\ub294\ub2e4\ub294 \ub2e8\uc5b4 \ud558\ub098\ubcf4\ub2e4 \ud310\ub2e8\uc744 \uc783\uc9c0 \uc54a\ub294\ub2e4\ub294 \ubc29\ud5a5\uc73c\ub85c \uc77d\uc5b4 \ubcfc \uc218 \uc788\ub2e4. \u300e\uba85\uc0c1\ub85d\u300f\uc740 \ubc14\uae65\uc5d0\uc11c \uc77c\uc5b4\ub09c \uc77c\uacfc \uadf8 \uc77c\uc5d0 \ub300\ud55c \uc790\uc2e0\uc758 \ud310\ub2e8\uc744 \uac70\ub4ed \uad6c\ubd84\ud558\uac8c \ud55c\ub2e4. \uc5b4\ub5a4 \uc77c\uc774 \ubd88\ucf8c\ud588\ub2e4\ub294 \ub290\ub08c\uc740 \uc0ac\uc2e4\uc774\uc9c0\ub9cc \uadf8 \ub290\ub08c\uc774 \uc0ac\uac74\uc758 \ubaa8\ub4e0 \ub73b\uc744 \ub2e4 \uc124\uba85\ud558\ub294 \uac83\uc740 \uc544\ub2d0 \uc218 \uc788\ub2e4. \uba48\ucd94\uc5b4 \uc0b4\ud544 \ud2c8\uc744 \ub9cc\ub4dc\ub294 \uac83\uc774\ub2e4. \uc624\ub298\uc758 \uc608\ub85c \uc57d\uc18d\ud55c \ub2f5\uc7a5\uc744 \ub2a6\uac8c \ubc1b\uc740 \uc0c1\ud669\uc744 \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub2e4. \uc0c1\ub300\uac00 \ub098\ub97c \ubb34\uc2dc\ud55c\ub2e4\uace0 \ubc14\ub85c \uacb0\uc815\ud558\uae30 \uc804\uc5d0 \uc544\uc9c1 \ubaa8\ub974\ub294 \uc870\uac74\uc774 \uc788\ub294\uc9c0 \ubb3b\ub294 \uac83\uc774\ub2e4. \uc774\ub294 \uc6d0\ubb38\uc758 \uc2e4\uc81c \uc0ac\ub840\ub97c \uc778\uc6a9\ud55c \uac83\uc774 \uc544\ub2c8\ub77c \uc0dd\uac01\uc758 \ubc29\ud5a5\uc744 \uc774\ud574\ud558\uae30 \uc704\ud55c \uc608\ub2e4. \ud655\uc778\ud560 \uc77c\uacfc \uc0c1\uc0c1\uc73c\ub85c \ubd99\uc778 \uc124\uba85\uc744 \ub098\ub204\ub294 \ub370 \ucca0\ud559\uc774 \uc4f0\uc77c \uc218 \uc788\ub2e4. \uc81c5\uad8c\uc758 \uc2dc\uc791\uc5d0\uc11c\ub294 \uc544\uce68\uc5d0 \uc77c\uc5b4\ub098\uae30 \uc2eb\uc744 \ub54c \uc790\uae30\uc5d0\uac8c \uc5b4\ub5a4 \ub9d0\uc744 \ud560\uc9c0 \ubb3b\ub294\ub2e4. \uc778\uac04\uc774 \ud574\uc57c \ud560 \uc77c\uc744 \uc704\ud574 \uc77c\uc5b4\ub098\ub294 \ubb38\uc81c\ub97c \ub2e4\ub978 \uc0dd\uba85\ub4e4\uc774 \ud65c\ub3d9\ud558\ub294 \ubaa8\uc2b5\uacfc \uc5f0\uacb0\ud55c\ub2e4. \ud669\uc81c\uc758 \uac70\ub300\ud55c \uacf5\uc801\ubcf4\ub2e4 \ub9e4\uc77c\uc758 \uc791\uc740 \uc800\ud56d\uc744 \ub2e4\ub8e8\ub294 \uad6c\uc808\uc774 \uba3c\uc800 \ub208\uc5d0 \ub4e4\uc5b4\uc62c \uc218\ub3c4 \uc788\ub2e4. \uc774\uac83\uc744 \uc26c\uc9c0 \ub9d0\uace0 \uc77c\ud558\ub77c\ub294 \ud604\ub300\uc758 \uc0dd\uc0b0\uc131 \uba85\ub839\uc73c\ub85c \ubc14\ub85c \ubc14\uafb8\uc9c0\ub294 \ub9d0\uc790. \ucc45\uc740 \uc790\uae30 \uc0b6\uc758 \uc5ed\ud560\uacfc \ud589\ub3d9\uc744 \uc0dd\uac01\ud558\ub294 \ub9e5\ub77d\uc5d0 \ub193\uc5ec \uc788\ub2e4. \uc9c0\uae08\uc758 \ub3c5\uc790\ub294 \uc790\uc2e0\uc758 \uc870\uac74\uacfc \uac74\uac15, \ub9e1\uc740 \ucc45\uc784\uc744 \uc0b4\ud53c\uba70 \uc77d\uc744 \uc218 \uc788\ub2e4. \uace0\ub300\uc758 \ubb38\uc7a5\uc774 \uc624\ub298 \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \ub3d9\uc77c\ud55c \uc77c\uc815\ud45c\uac00 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2a4\ud1a0\uc544 \ucca0\ud559\uc744 \uc774\uc57c\uae30\ud560 \ub54c \ud63c\uc790 \ud3c9\uc628\ud574\uc9c0\ub294 \uae30\uc220\ub9cc \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uc774 \ucc45\uc5d0\ub294 \uc0ac\ub78c\ub4e4\uacfc \ud568\uaed8 \uc0b4\uc544\uac00\ub294 \uc77c\uacfc \uc815\uc758, \uacf5\ub3d9\uc758 \uc774\uc775\uc5d0 \uad00\ud55c \uc0dd\uac01\ub3c4 \ubc18\ubcf5\ud574\uc11c \ub098\uc628\ub2e4. \ub0b4 \uae30\ubd84\uc744 \uc9c0\ud0a4\ub294 \uac83\uacfc \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc5b4\ub5a4 \ud589\ub3d9\uc744 \ud558\ub294\uac00\ub294 \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\ub2e4. \ud2b9\ud788 \uad8c\ud55c\uc744 \uac00\uc9c4 \uc0ac\ub78c\uc758 \ud3c9\uc815\uc740 \uc790\uc2e0\ub9cc \ud3b8\uc548\ud558\uae30 \uc704\ud55c \uc0c1\ud0dc\ub85c \ub05d\ub0a0 \uc218 \uc5c6\ub2e4. \ud310\ub2e8\uc774 \ub35c \ud754\ub4e4\ub9b0\ub2e4\uba74 \uadf8 \ud798\uc744 \uc5b4\ub5a4 \uacb0\uc815\uc5d0 \uc0ac\uc6a9\ud560 \uac83\uc778\uac00\ub77c\ub294 \ubb38\uc81c\uac00 \ub0a8\ub294\ub2e4. \ud669\uc81c\uc758 \ucc45\uc744 \uc77d\ub294 \uc7ac\ubbf8\ub3c4 \uc5ec\uae30 \uc788\ub2e4. \ub9c8\uc74c\uc18d\uc758 \uc9c8\ubb38\uc774 \uc2e4\uc81c \uc138\uacc4\uc5d0 \ubbf8\uce58\ub294 \ucc45\uc784\uacfc \ub9cc\ub09c\ub2e4. \u300e\uba85\uc0c1\ub85d\u300f\uc5d0\uc11c\ub294 \ube44\uc2b7\ud55c \uc0dd\uac01\uc774 \uc5ec\ub7ec \ubc88 \ub098\ud0c0\ub09c\ub2e4. \ucc98\uc74c\ubd80\ud130 \ub05d\uae4c\uc9c0 \ud55c \uc8fc\uc7a5\uc73c\ub85c \uace7\uac8c \ub098\uc544\uac00\ub294 \uad50\uacfc\uc11c\ub97c \uae30\ub300\ud558\uba74 \ub418\ud480\uc774\ucc98\ub7fc \ub290\ub084 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc774\ubbf8 \uc548\ub2e4\uace0 \uc5ec\uae30\ub294 \uc6d0\uce59\uc744 \uc2e4\uc81c\ub85c \uc9c0\ud0a4\uae30 \uc704\ud574 \ub2e4\uc2dc \uc801\ub294 \ub9d0\ub85c \ubcf4\uba74 \ubc18\ubcf5\uc758 \uc131\uaca9\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ub3c5\uc790\uac00 \ubaa8\ub4e0 \uad6c\uc808\uc5d0 \ub3d9\uc758\ud574\uc57c \ud558\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uc9e7\uc740 \ub300\ubaa9 \ud558\ub098\ub97c \uc77d\uace0 \uadf8\uac83\uc774 \uc5b4\ub5a4 \uc0c1\ud669\uc5d0\uc11c\ub294 \ub3c4\uc6c0\uc774 \ub418\uace0 \uc5b4\ub5a4 \uacf3\uc5d0\uc11c\ub294 \uc124\uba85\uc774 \ub354 \ud544\uc694\ud55c\uc9c0 \uc0dd\uac01\ud574 \ubcf4\uc790. \uc720\uba85\ud55c \ubb38\uc7a5\uc744 \ub5bc\uc5b4 \uc790\uc2e0\uc758 \ud310\ub2e8\uc744 \uba74\uc81c\ud574 \uc8fc\ub294 \ub9d0\ub85c \uc4f0\uae30\ubcf4\ub2e4 \uac80\ud1a0\ud560 \ub9d0\ub85c \ub193\ub294 \ud3b8\uc774 \ucc45\uacfc \uc624\ub798 \ub9cc\ub098\ub294 \ubc29\ubc95\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \uc61b \uc601\ubb38\ud310\uc5d0 \uc218\ub85d\ub41c \ub9c8\ub974\ucfe0\uc2a4 \uc544\uc6b0\ub810\ub9ac\uc6b0\uc2a4\uc758 \uc5ed\uc0ac\uc801 \ucd08\uc0c1 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \ud669\uc81c\uc758 \ud558\ub8e8\ub97c \uc9c1\uc811 \ucd2c\uc601\ud55c \uc790\ub8cc\ub098 \uae00\uc744 \uc4f0\ub358 \uc21c\uac04\uc744 \ubcf5\uc6d0\ud55c \uadf8\ub9bc\uc740 \uc544\ub2c8\ub2e4. \ud2b9\uc815 \uc5bc\uad74\uc5d0\uc11c \uc644\ubcbd\ud55c \uce68\ucc29\ud568\uc744 \uc77d\uc5b4 \ub0b4\ub824\uace0 \ud558\uae30\ubcf4\ub2e4 \uae30\ub85d\uc758 \uc9c8\ubb38\uc73c\ub85c \ub3cc\uc544\uac00\uba74 \uc88b\ub2e4. \uc624\ub298 \ubb34\uc2a8 \uc77c\uc774 \uc788\uc5c8\ub294\uc9c0\uc640 \uadf8 \uc77c\uc5d0 \ub0b4\uac00 \uc5b4\ub5a4 \uc124\uba85\uc744 \ubd99\uc600\ub294\uc9c0\ub97c \ud55c \ubc88 \ub098\ub204\uc5b4 \uc801\uc5b4 \ubcf4\uc790. \uc138\uc0c1\uc744 \ub73b\ub300\ub85c \ub9cc\ub4e4 \uc218 \uc5c6\ub2e4\ub294 \uccb4\ub150\ub9cc \ub0a8\uae30\ub824\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc544\uc9c1 \uc0b4\ud544 \ud310\ub2e8\uacfc \uc120\ud0dd\ud560 \ud589\ub3d9\uc774 \ubb34\uc5c7\uc778\uc9c0 \uc54c\uc544\ubcf4\ub294 \uc77c\uc774\ub2e4. \ud669\uc81c\uac00 \uc790\uc2e0\uc5d0\uac8c \uac74\ub128 \uc624\ub798\ub41c \ub9d0\uc774 \uc624\ub298\uc758 \ud558\ub8e8\ub97c \ub3cc\uc544\ubcf4\ub294 \uc791\uc740 \ub3c4\uad6c\uac00 \ub420 \uc218 \uc788\ub2e4."}, {"id": "mummy-museum-move", "title": "\ubbf8\ub77c\uac00 \uc774\uc0ac\ud558\ub824\uba74 \ub204\uad6c\uc5d0\uac8c \ubb3c\uc5b4\ubd10\uc57c \ud560\uae4c", "summary": "\ubc15\ubb3c\uad00 \ubbf8\ub77c\uc758 \uc774\ub3d9\uc5d0\ub3c4 \ud3ec\uc7a5 \uc678\uc5d0 \ud655\uc778\ud560 \uc77c\uc774 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.", "category": "ideas", "category_title": "\uc0dd\uac01\uacfc \uc9c0\uc2dd", "subcategory": "\uc0ac\ud68c\uc640 \uc81c\ub3c4\uc758 \ud0c4\uc0dd", "categories": ["ideas"], "url": "stories/mummy-museum-move/index.html", "image": "../media/mummy-museum-move.jpg", "alt": "\ubbf8\ub77c\uac00 \uc774\uc0ac\ud558\ub824\uba74 \ub204\uad6c\uc5d0\uac8c \ubb3c\uc5b4\ubd10\uc57c \ud560\uae4c\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\ubbf8\ub77c\uac00 \uc774\uc0ac\ud558\ub824\uba74 \ub204\uad6c\uc5d0\uac8c \ubb3c\uc5b4\ubd10\uc57c \ud560\uae4c \uc624\ub798\ub41c \uc720\ud574\ub97c \uc62e\uae30\uba70 \ubbf8\uc220\uad00\uc774 \ud655\uc778\ud55c \uac83 \ubc15\ubb3c\uad00 \ubbf8\ub77c\uc758 \uc774\ub3d9\uc5d0\ub3c4 \ud3ec\uc7a5 \uc678\uc5d0 \ud655\uc778\ud560 \uc77c\uc774 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uc0ac\ud68c\uc640 \uc81c\ub3c4\uc758 \ud0c4\uc0dd \uc0dd\uac01\uacfc \uc9c0\uc2dd \ubc15\ubb3c\uad00\uc758 \ubbf8\ub77c\ub97c \ub2e4\ub978 \ubbf8\uc220\uad00\uc73c\ub85c \uc62e\uae34\ub2e4\uace0 \ud574 \ubcf4\uc790. \uba3c\uc800 \ub5a0\uc624\ub974\ub294 \uac83\uc740 \ud3ec\uc7a5 \uc0c1\uc790\uc640 \uc870\uc2ec\uc2a4\ub7ec\uc6b4 \uc6b4\uc1a1\uc774\ub2e4. \uadf8\ub7f0\ub370 \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc5d0\uc11c\ub294 \uadf8\ubcf4\ub2e4 \uc55e\uc11c \ubc95\ub960\ud300\uc5d0 \uc9c8\ubb38\uc774 \ub3c4\ucc29\ud588\ub2e4. \uc0ac\ub78c\uc758 \uc720\ud574\ub97c \uc8fc \uacbd\uacc4 \ub108\uba38\ub85c \uc62e\uae38 \ub54c \uc54c\uc544\uc57c \ud560 \ubc95\uc774 \uc788\ub290\ub0d0\ub294 \ub0b4\uc6a9\uc774\uc5c8\ub2e4. \ud669\uae08\uc774\ub098 \ub3cc\ub85c \ub9cc\ub4e0 \uc720\ubb3c\uacfc \ub2ec\ub9ac \ubbf8\ub77c\ub294 \ud55c\ub54c \uc0b4\uc558\ub358 \uc0ac\ub78c\uc758 \ubab8\uc774\ub2e4. \uc624\ub798\ub418\uc5c8\ub2e4\ub294 \uc774\uc720\ub85c \uadf8 \ucc28\uc774\uac00 \uc5c6\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ubbf8\uc220\uad00\uc758 \uacf5\uc2dd \uae00\uc5d0 \ub530\ub974\uba74 \ubbf8\ub77c\uc640 \uad00\uc740 \ub2e4\ub978 \uc8fc\uc758 \ubc15\ubb3c\uad00\uc5d0 50\ub144 \ub118\uac8c \ub300\uc5ec\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc5f0\uad6c\uc640 \uc804\uc2dc\ub97c \uc704\ud574 \ub2e4\uc2dc \uac00\uc838\uc624\ub824\uba74\uc11c \uc6b4\uc1a1 \ubb38\uc81c\ub97c \uac80\ud1a0\ud558\uac8c \ub41c \uac83\uc774\ub2e4. \uba40\ub9ac\uc11c \ubcf4\uba74 \ubc15\ubb3c\uad00 \uc18c\uc7a5\ud488\uc740 \ub298 \uac19\uc740 \uc790\ub9ac\uc5d0 \uc788\uc744 \uac83 \uac19\uc9c0\ub9cc \uc2e4\uc81c\ub85c\ub294 \ub300\uc5ec\uc640 \ubc18\ud658, \uc5f0\uad6c\ub97c \uc704\ud574 \uc6c0\uc9c1\uc778\ub2e4. \uc804\uc2dc\uc7a5\uc5d0\uc11c \uc6b0\ub9ac\uac00 \ubcf4\ub294 \ud55c \uc810\uc5d0\ub3c4 \ub2e4\ub978 \uae30\uad00\uc5d0\uc11c \uc9c0\ub0b8 \uae34 \uc2dc\uac04\uc774 \ub4e4\uc5b4 \uc788\uc744 \uc218 \uc788\ub2e4. \ubbf8\uc220\uad00 \ubc95\ub960\ud300\uc740 \uad00\ub828 \uaddc\uc815\uacfc \ub2e4\ub978 \ubc15\ubb3c\uad00\uc758 \uc0ac\ub840\ub97c \uac80\ud1a0\ud588\ub2e4. \uc774 \uc0ac\ub840\uc5d0\uc11c\ub294 \uc6b4\uc1a1\uc5d0 \ubc95\uc801\uc778 \uc7a5\uc560\uac00 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4\ub294 \ud310\ub2e8\uc744 \ub0b4\ub838\ub2e4\uace0 \uae00\uc740 \uc124\uba85\ud55c\ub2e4. \ubaa8\ub4e0 \ub098\ub77c\uc640 \ubaa8\ub4e0 \ubbf8\ub77c\uc5d0 \uadf8\ub300\ub85c \uc801\uc6a9\ub418\ub294 \uc548\ub0b4\ub294 \uc544\ub2c8\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uc62e\uae38 \uc218 \uc788\uaca0\uc9c0 \ud558\uace0 \ubc14\ub85c \uc0c1\uc790\uc5d0 \ub123\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc810\uc774\ub2e4. \ubb3c\uac74\uc758 \uc7ac\ub8cc\uc640 \uc0c1\ud0dc\ub97c \ud655\uc778\ud558\ub294 \uc77c\ucc98\ub7fc, \uadf8\uac83\uc744 \uc5b4\ub5a4 \ub300\uc0c1\uc73c\ub85c \ub2e4\ub8e8\uc5b4\uc57c \ud558\ub294\uc9c0 \ubb3b\ub294 \uacfc\uc815\ub3c4 \uc774\ub3d9 \uc900\ube44\uc5d0 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \ubbf8\ub77c\uc640 \uad00\uc740 \ud568\uaed8 \uc804\uc2dc\ub418\ub354\ub77c\ub3c4 \uc131\uaca9\uc774 \uac19\uc740 \ub300\uc0c1\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uad00\uc740 \uc0ac\ub78c\uc774 \uc81c\uc791\ud55c \ubb3c\uac74\uc774\uace0 \ubbf8\ub77c\ub294 \ud55c\ub54c \uc0b4\uc544 \uc788\ub358 \uc0ac\ub78c\uc758 \uc720\ud574\ub2e4. \uc62e\uae30\ub294 \uc808\ucc28\ub97c \uc0dd\uac01\ud560 \ub54c \ubcf4\uc874 \uc0c1\ud0dc\uc640 \uc18c\uc720 \uae30\ub85d\ubfd0 \uc544\ub2c8\ub77c \uc778\uac04\uc758 \ubab8\uc744 \uc5b4\ub5bb\uac8c \ub2e4\ub8f0\uc9c0\ub3c4 \ubb38\uc81c\uac00 \ub41c\ub2e4. \ubc15\ubb3c\uad00\uc758 \ubb3c\uac74\uc774\ub77c\ub294 \ud55c \ubb38\uc7a5\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc9c8\ubb38\uc774 \ub05d\ub098\uc9c0 \uc54a\ub294 \uc774\uc720\ub2e4. \uc774\uac83\uc740 \ubbf8\uc220\uad00\uc774 \uc18c\uc7a5\ud55c \ubaa8\ub4e0 \uc790\ub8cc\uc5d0 \ub611\uac19\uc740 \ub2f5\uc744 \uc801\uc6a9\ud558\uc790\ub294 \ub9d0\uc774 \uc544\ub2c8\ub2e4. \uac01 \ub300\uc0c1\uc758 \uc131\uaca9\uacfc \uad00\ub828 \uaddc\uc815\uc744 \uc0b4\ud3b4\uc57c \ud55c\ub2e4\ub294 \ub73b\uc774\ub2e4. \uacf5\uc2dd \uae00\uc774 \ubc95\ub960\ud300\uc758 \uac80\ud1a0 \uacfc\uc815\uc744 \uc18c\uac1c\ud55c\ub2e4\ub294 \uc810\uc740 \uc774\ub7f0 \ucc28\uc774\ub97c \ubcf4\uc5ec \uc900\ub2e4. \uc804\uc2dc\uc7a5\uc5d0\uc11c\ub294 \ubcf4\uc774\uc9c0 \uc54a\ub294 \ubd84\ub958\uc640 \ucc45\uc784\uc758 \ubb38\uc81c\uac00 \uc774\ub3d9\uc744 \uc900\ube44\ud558\ub294 \ub2e8\uacc4\uc5d0\uc11c \ub4dc\ub7ec\ub0a0 \uc218 \uc788\ub2e4. 50\ub144 \ub118\uac8c \ub2e4\ub978 \uae30\uad00\uc5d0 \uc788\uc5c8\ub2e4\uba74 \ubc29\ubb38\uc790\uc758 \uae30\uc5b5 \uc18d\uc5d0\uc11c\ub294 \uadf8\uacf3\uc758 \ub300\ud45c \uc804\uc2dc\ubb3c\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc624\ub7ab\ub3d9\uc548 \uc804\uc2dc\ud588\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc18c\uc7a5\uc758 \ubc95\uc801 \uad00\uacc4\ub294 \uac19\uc740 \uac83\uc774 \uc544\ub2c8\ub2e4. \ub300\uc5ec\uc640 \ubc18\ud658\uc774\ub77c\ub294 \ub9d0\uc740 \uc791\ud488\uc758 \ubb3c\ub9ac\uc801 \uc704\uce58\uc640 \uad00\ub9ac\uc758 \uad00\uacc4\ub97c \uad6c\ubd84\ud558\uac8c \ud55c\ub2e4. \uc5b4\ub514\uc5d0 \ubcf4\uc600\ub294\uc9c0\uc640 \ub204\uad6c\uc5d0\uac8c \uc18d\ud588\ub294\uc9c0\ub97c \ud568\uaed8 \uc77d\uc5b4\uc57c \ud55c\ub2e4. \uadf8\ub798\uc11c \ubc18\ud658\uc740 \ub2e8\uc21c\ud788 \ubb3c\uac74 \ud558\ub098\ub97c \ucc3d\uace0\uc5d0\uc11c \uaebc\ub0b4\ub294 \uc77c\uacfc \ub2e4\ub974\ub2e4. \ube4c\ub824 \ub454 \uae30\uad00\uc758 \uc804\uc2dc\uc640 \uc6d0\ub798 \uc18c\uc7a5 \uae30\uad00\uc758 \uc5f0\uad6c \uacc4\ud68d\uc774 \ud568\uaed8 \uc601\ud5a5\uc744 \ubc1b\uc744 \uc218 \uc788\ub2e4. \uc774 \uc0ac\ub840\uc5d0\uc11c \ubcf5\uc81c\ud488 \uc81c\uc791\uc5d0 \ud569\uc758\ud55c \uc77c\ub3c4 \uadf8\ub7f0 \uc870\uc815\uc758 \ud55c \ubd80\ubd84\uc73c\ub85c \ubcfc \uc218 \uc788\ub2e4. \uc774\ub3d9\uc758 \uc5ed\uc0ac\uc5d0\ub294 \uc6b4\uc1a1\uc218\ub2e8\ubfd0 \uc544\ub2c8\ub77c \uc5ec\ub7ec \uae30\uad00\uc758 \ub300\ud654\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \uae30\uad00\uc758 \ubc95\ub960\uc801 \ud310\ub2e8\uc740 \uc774 \uad6c\uccb4\uc801\uc778 \uc774\ub3d9\uc5d0 \ubc95\uc801 \uc7a5\uc560\uac00 \uc788\ub294\uc9c0\uc5d0 \uad00\ud55c \uac83\uc774\uc5c8\ub2e4. \uadf8 \ud310\ub2e8\uc774 \uace7 \ud3ec\uc7a5\uacfc \uc6b4\uc1a1\uc758 \ubaa8\ub4e0 \ubcf4\uc874 \ubb38\uc81c\ub97c \ud574\uacb0\ud588\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud55c \uc77c\uc744 \ud560 \uc218 \uc788\ub294\uc9c0\uc640 \uc5b4\ub5bb\uac8c \ud574\uc57c \uc548\uc804\ud55c\uc9c0\ub294 \uc11c\ub85c \ub2e4\ub978 \uc804\ubb38\uc131\uc744 \uc694\uad6c\ud560 \uc218 \uc788\ub2e4. \ubbf8\uc220\uad00\uc758 \uc77c\uc740 \uc774 \uc870\uac74\ub4e4\uc744 \uc774\uc5b4 \uacb0\uc815\ud558\ub294 \uacfc\uc815\uc774\uae30\ub3c4 \ud558\ub2e4. \ub530\ub77c\uc11c \ud2b9\uc815 \uc0ac\ub840\uc758 \uacb0\uacfc\ub97c \ubaa8\ub4e0 \ub098\ub77c\uc758 \uc720\ud574 \uc6b4\uc1a1 \uc548\ub0b4\ub85c \uc0ac\uc6a9\ud560 \uc218 \uc5c6\ub2e4. \ubc95\uacfc \uc81c\ub3c4\ub294 \uc7a5\uc18c\uc640 \ub300\uc0c1\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c0\uace0 \uc2dc\uc810\uc758 \uc601\ud5a5\ub3c4 \ubc1b\ub294\ub2e4. \uc774 \uae00\uc5d0\uc11c \ud765\ubbf8\ub85c\uc6b4 \uac83\uc740 \uc5b4\ub5a4 \uc870\ubb38\uc744 \uc678\uc6b0\ub294 \ub370\ubcf4\ub2e4 \uc608\uc0c1\ubcf4\ub2e4 \ub9ce\uc740 \uc0ac\ub78c\uc774 \ud558\ub098\uc758 \uc774\uc0ac\ub97c \uac80\ud1a0\ud55c\ub2e4\ub294 \uc0ac\uc2e4\uc774\ub2e4. \ubb3c\uac74\uc758 \ud2b9\uc131\uc774 \ub2e4\ub978 \uc9c8\ubb38\uc744 \ubd88\ub7ec\uc628 \uac83\uc774\ub2e4. \uacf5\uc2dd \uae00\uc740 \ubc18\ud658 \ub4a4 \uc5f0\uad6c\ub97c \ud1b5\ud574 \uc774 \uc0ac\ub78c\uc744 \ub354 \uc798 \uc774\ud574\ud558\ub824\ub294 \uacc4\ud68d\ub3c4 \uc5b8\uae09\ud55c\ub2e4. \uc774\ub984\uacfc \ub098\uc774, \uc0b4\uc544 \uc788\ub358 \ud658\uacbd\uc744 \uc54c\uc544\ubcf4\ub824\ub294 \uc9c8\ubb38\uc740 \uc804\uc2dc\uc7a5\uc5d0\uc11c \uac89\ubaa8\uc2b5\uc744 \ubcf4\ub294 \uacbd\ud5d8\uacfc \ub2e4\ub974\ub2e4. \ub2e4\ub9cc \uc5f0\uad6c \uacc4\ud68d\uc774 \uc788\uc5c8\ub2e4\ub294 \ub9d0\uacfc \uadf8 \uacb0\uacfc\uac00 \uc774\ubbf8 \ubaa8\ub450 \ub098\uc654\ub2e4\ub294 \ub9d0\uc740 \ub098\ub204\uc5b4\uc57c \ud55c\ub2e4. \uc774 \uc6d0\uace0\ub294 \ud655\uc778\ud558\uc9c0 \uc54a\uc740 \uc0c8 \ubc1c\uacac\uc744 \ub367\ubd99\uc774\uc9c0 \uc54a\ub294\ub2e4. \ubcf5\uc81c\ud488\uc740 \ubcfc \uae30\ud68c\ub97c \uc774\uc5b4 \uc8fc\uc9c0\ub9cc \uc6d0\ubcf8\uc758 \ubaa8\ub4e0 \uc815\ubcf4\ub97c \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc7ac\ub8cc\uc640 \ubcf4\uc874, \uc5f0\uad6c\uac00 \uc694\uad6c\ud558\ub294 \uc790\ub8cc\ub294 \ub2e4\ub97c \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ubb34\uc5c7\uc744 \ub0a8\uaca8 \ubcf4\uc5ec \uc8fc\uace0 \ubb34\uc5c7\uc744 \uc62e\uaca8 \uc870\uc0ac\ud560\uc9c0 \uc120\ud0dd\ud558\ub294 \uc77c\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \ubbf8\ub77c\uc758 \uc774\uc0ac\ub77c\ub294 \ub73b\ubc16\uc758 \uc81c\ubaa9 \ub4a4\uc5d0\uc11c \ubc15\ubb3c\uad00\uc774 \uacfc\uac70\uc758 \uc0ac\ub78c\uc744 \ub300\ud558\ub294 \uc5ec\ub7ec \ucc45\uc784\uc744 \uc77d\uac8c \ub41c\ub2e4. \ubc18\ud658 \uacfc\uc815\uc5d0\uc11c\ub294 \ube4c\ub824 \uac04 \ubc15\ubb3c\uad00\uc774 \ubbf8\ub77c\uc640 \uad00\uc758 \ubcf5\uc81c\ud488\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub3c4\ub85d \ud569\uc758\ub3c4 \ud588\ub2e4. \ud55c\ucabd\uc5d0\uc11c\ub294 \uc5f0\uad6c\ud560 \uc6d0\ub798 \uc790\ub8cc\ub97c \ub3cc\ub824\ubc1b\uace0, \ub2e4\ub978 \ucabd\uc5d0\uc11c\ub294 \ubcf5\uc81c\ud488\uc744 \ub0a8\uae30\ub294 \ubc29\uc2dd\uc774\uc5c8\ub2e4. \uacf5\uc2dd \uae00\uc740 \ub3cc\uc544\uc628 \ub4a4\uc758 \uc5f0\uad6c\uac00 \uae30\uc874 \uc2e0\uc6d0 \uc774\ud574\uc5d0\ub3c4 \uc9c8\ubb38\uc744 \ub358\uc84c\ub2e4\uace0 \ub367\ubd99\uc778\ub2e4. \uc804\uc2dc\ud488 \uc124\uba85\uc740 \uc601\uc6d0\ud788 \uace0\uc815\ub41c \uc815\ub2f5\uc774 \uc544\ub2d0 \uc218 \uc788\ub294 \uac83\uc774\ub2e4. \ubbf8\ub77c\uc758 \uc774\uc0ac\ub294 \uc0c1\uc790 \ud558\ub098\ub97c \uc62e\uae30\ub294 \uc77c\uc744 \ub118\uc5b4, \ud55c \uc0ac\ub78c\uc758 \ud754\uc801\uc744 \uc5b4\ub5bb\uac8c \ubcf4\uad00\ud558\uace0 \uc774\ud574\ud560\uc9c0 \ub2e4\uc2dc \ubb3b\ub294 \uc77c\uc774\uc5c8\ub2e4."}, {"id": "silver-kettle-hidden-letters", "title": "\uc8fc\uc804\uc790\uc758 \uc774\uc57c\uae30\ub294 \ubc14\ub2e5\uc5d0\ub3c4 \uc801\ud600 \uc788\ub2e4", "summary": "\uc740\uc81c \uc8fc\uc804\uc790\uc758 \uaf43\ubd09\uc624\ub9ac \uc190\uc7a1\uc774\uc640 \ubc14\ub2e5\uc758 \uba85\ubb38\uc744 \ucc3e\uc544\ubd05\ub2c8\ub2e4.", "category": "ideas", "category_title": "\uc0dd\uac01\uacfc \uc9c0\uc2dd", "subcategory": "\uc608\uc220\uc744 \ubcf4\ub294 \ubc95", "categories": ["ideas"], "url": "stories/silver-kettle-hidden-letters/index.html", "image": "../media/silver-kettle-hidden-letters.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc740\uc81c\uc8fc\uc804\uc790 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc8fc\uc804\uc790\uc758 \uc774\uc57c\uae30\ub294 \ubc14\ub2e5\uc5d0\ub3c4 \uc801\ud600 \uc788\ub2e4 \ubc18\uc9dd\uc774\ub294 \ubab8\uccb4 \uc544\ub798\uc758 \uc791\uc740 \uae00\uc790\ub4e4 \uc740\uc81c \uc8fc\uc804\uc790\uc758 \uaf43\ubd09\uc624\ub9ac \uc190\uc7a1\uc774\uc640 \ubc14\ub2e5\uc758 \uba85\ubb38\uc744 \ucc3e\uc544\ubd05\ub2c8\ub2e4. \uc608\uc220\uc744 \ubcf4\ub294 \ubc95 \uc0dd\uac01\uacfc \uc9c0\uc2dd \uc740\ube5b \uc8fc\uc804\uc790\ub97c \ubcf4\uba74 \uba3c\uc800 \uae38\uac8c \ubed7\uc740 \uc8fc\ub465\uc774\uc640 \ud718\uc5b4\uc9c4 \uc190\uc7a1\uc774\uac00 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uac00\uc6b4\ub370 \ub465\uadfc \ubab8\ud1b5\uae4c\uc9c0, \ubb3c\uc744 \ub530\ub974\ub294 \ubb3c\uac74\uc774\ub77c\ub294 \uc0ac\uc2e4\uc740 \uc5b4\ub835\uc9c0 \uc54a\uac8c \uc54c\uc544\ubcfc \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc774 \uc8fc\uc804\uc790\ub294 \uc606\ubaa8\uc2b5\ub9cc \ubcf4\uace0 \ub05d\ub0b4\uae30 \uc544\uae5d\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \uc124\uba85\uc744 \ub530\ub77c\uac00\uba74 \ub69c\uaed1\uc5d0\ub294 \uaf43\ubd09\uc624\ub9ac\uac00 \uc788\uace0, \ubab8\uccb4 \uc591\ucabd\uc5d0\ub294 \uae00\uc790\uac00 \uc788\uc73c\uba70, \ubc14\ub2e5\uc5d0\ub3c4 \uae30\ub85d\uc774 \uc788\ub2e4. \ud55c \ubb3c\uac74\uc744 \ubcf4\ub294 \ubc29\ud5a5\uc774 \uc138 \ubc88 \ubc14\ub010\ub2e4. \ubc15\ubb3c\uad00\uc740 \ub69c\uaed1 \uc190\uc7a1\uc774\ub97c \uc5f0\ubd09\uc624\ub9ac \ud615\ud0dc\ub85c \uc124\uba85\ud55c\ub2e4. \uc9d1\uc5b4 \ub4dc\ub294 \ubd80\ubd84\uc5d0 \uaf43\uc758 \ubaa8\uc591\uc744 \ube4c\ub824 \ub193\uc740 \uac83\uc774\ub2e4. \uc2e4\uc81c \uc5f0\uaf43\uc774 \ud540 \ud48d\uacbd\uc744 \uadf8\ub9b0 \ub300\uc2e0 \uc190\uc5d0 \ub2ff\ub294 \uc791\uc740 \uaf2d\uc9c0\ub97c \uaf43\ucc98\ub7fc \ub9cc\ub4e4\uc5c8\ub2e4. \ub69c\uaed1\uc5d0\ub294 \uc120\uc73c\ub85c \uc0c8\uae34 \ubc15\uc950\ubb34\ub2ac\ub3c4 \uc788\ub2e4\uace0 \ud55c\ub2e4. \uc0ac\uc9c4 \ud55c \uc7a5\uc5d0 \ubaa8\ub4e0 \ubc29\ud5a5\uc774 \ubcf4\uc774\uc9c0\ub294 \uc54a\uc73c\ub2c8, \ubcf4\uc774\uc9c0 \uc54a\ub294 \ubb34\ub2ac\ub97c \uc5b5\uc9c0\ub85c \ucc3e\uc544\ub0b4\uae30\ubcf4\ub2e4 \uc124\uba85\uc744 \uae38\uc7a1\uc774\ub85c \uc0bc\uc73c\uba74 \ub41c\ub2e4. \ubc15\uc950\uc758 \ub73b\uae4c\uc9c0 \uc774 \uc790\ub8cc\ub9cc\uc73c\ub85c \uae38\uac8c \ud480\uc9c0\ub294 \uc54a\uae30\ub85c \ud558\uc790. \ubab8\uccb4 \uc591\ucabd\uc5d0\ub294 \ub465\uadfc \ud2c0\uc758 \uc218\uba85 \uc218, \uace7 \u58fd\ub97c \ub098\ud0c0\ub0b8 \ubb34\ub2ac\uac00 \uc788\ub2e4. \uc8fc\uc804\uc790\uc758 \ub465\uadfc \ud615\ud0dc \uc548\uc5d0 \uae00\uc790 \uc7a5\uc2dd\uc774 \ub354\ud574\uc9c4 \uac83\uc774\ub2e4. \ub2e8\uc21c\ud788 \ubc18\uc9dd\uc774\ub294 \uc740\uadf8\ub987\uc774\ub77c\uace0\ub9cc \ubcf4\uae30\uc5d0\ub294 \ubcfc\uac70\ub9ac\uac00 \ub9ce\ub2e4. \uad7d\uc5d0\ub294 \uc120\ud76c\uad81\uc744 \ub73b\ud558\ub294 \u5ba3\u79a7\u5bae\uc73c\ub85c \uc2dc\uc791\ud558\ub294 \uae00\uc774 \uc0c8\uaca8\uc838 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc740 \uadf8 \uba85\ubb38 \uc804\uccb4\ub97c \uc18c\uac1c\ud55c\ub2e4. \uadf8\uc911\uc5d0\ub294 \uc0c8\ub85c \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \u65b0\u9020\uc640 \ubb34\uac8c\ub97c \ub73b\ud558\ub294 \u91cd \uac19\uc740 \uae00\uc790\ub3c4 \ubcf4\uc778\ub2e4. \uc7a5\uc2dd\uacfc \ubcc4\uac1c\ub85c \uc81c\uc791\uc5d0 \uad00\ud55c \uc815\ubcf4\ub97c \ub0a8\uae30\ub294 \uc790\ub9ac\uc600\uc74c\uc744 \uc77d\uc744 \uc218 \uc788\ub2e4. \uc8fc\uc804\uc790\ub294 \uc561\uccb4\ub97c \ub2f4\ub294 \ubab8\uccb4\uc640 \ub530\ub974\ub294 \ucabd, \uc190\uc73c\ub85c \uc7a1\ub294 \ubd80\ubd84\uc774 \uad00\uacc4\ub97c \uc774\ub8e8\ub294 \ubb3c\uac74\uc774\ub2e4. \ud45c\uba74\uc758 \uc7a5\uc2dd\uc744 \ucc3e\uae30 \uc804\uc5d0 \uc5b4\ub290 \uacf3\uc744 \ub4e4\uace0 \uc5b4\ub5bb\uac8c \uae30\uc6b8\uc774\uac8c \ub418\ub294\uc9c0 \uc0dd\uac01\ud558\uba74 \ud615\ud0dc\uac00 \ub35c \ub0af\uc124\uc5b4\uc9c4\ub2e4. \ub2e4\ub9cc \uc774 \uc720\ubb3c\uc774 \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \uc790\ub9ac\uc5d0\uc11c \uc5b4\ub5a4 \uc74c\ub8cc\ub97c \ub2f4\uc558\ub294\uc9c0\uae4c\uc9c0 \ubaa8\uc591\ub9cc\uc73c\ub85c \ud655\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc4f0\uc784\uc758 \uac00\ub2a5\uc131\uacfc \uac1c\ubcc4 \uc0ac\uc6a9 \uc774\ub825\uc740 \ub2e4\ub978 \uc815\ubcf4\ub2e4. \uc5f0\ubd09\uc624\ub9ac\ucc98\ub7fc \ub9cc\ub4e0 \ub69c\uaed1 \uaf2d\uc9c0\ub294 \uc7a5\uc2dd\uc744 \uac10\uc0c1\ud558\ub294 \ub208\uacfc \ubb3c\uac74\uc744 \uc0ac\uc6a9\ud558\ub294 \uc190\uc774 \ub9cc\ub098\ub294 \uc790\ub9ac\ub2e4. \uaf43 \ubaa8\uc591\uc744 \ubcf4\ub294 \ub370\uc11c \ud55c \uac78\uc74c \ub354 \ub098\uc544\uac00 \uc65c \uadf8\ub7f0 \uc704\uce58\uc5d0 \ubd99\uc5b4 \uc788\ub294\uc9c0 \ubcf4\uba74 \ub41c\ub2e4. \uc0dd\ud65c \ub3c4\uad6c\uc758 \uc544\ub984\ub2e4\uc6c0\uc740 \ud45c\uba74\uc5d0 \ubb34\ub2ac\ub97c \ub354\ud558\ub294 \uc77c\uc5d0\ub9cc \uc788\uc9c0 \uc54a\ub2e4. \ub9cc\uc9c0\uace0 \uc5f4\uace0 \ub2eb\ub294 \ubd80\ubd84 \uc790\uccb4\uc5d0 \ud615\uc0c1\uc744 \ub123\ub294 \uc120\ud0dd\ub3c4 \uc788\ub2e4. \ubab8\uccb4\uc758 \uc6d0\uc218\ubb38\uc740 \uc218\uba85 \uc218\ub77c\ub294 \uae00\uc790\ub97c \uc7a5\uc2dd\uc758 \uad6c\uc131\uc73c\ub85c \uc0ac\uc6a9\ud55c\ub2e4. \ubb38\uc790\ub97c \uc77d\ub294 \uc77c\uacfc \ubb34\ub2ac\ub97c \ubcf4\ub294 \uc77c\uc774 \uacb9\uce5c\ub2e4. \ub73b\uc744 \ubaa8\ub974\uba74 \ub465\uadfc \ud615\ud0dc\uc640 \uc120\uc758 \ubc30\uc5f4\uc774 \uba3c\uc800 \ubcf4\uc774\uace0, \ub73b\uc744 \uc54c\uba74 \uadf8 \uc548\uc758 \ubc14\ub78c\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \ud55c \ud45c\uba74\uc774 \ub450 \uac00\uc9c0 \uc77d\uae30\uc758 \uc18d\ub3c4\ub97c \ud5c8\uc6a9\ud558\ub294 \uc148\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \uac19\uc740 \uae00\uc790\uac00 \ubcf4\uc774\ub294 \ubaa8\ub4e0 \ubb3c\uac74\uc5d0 \ub3d9\uc77c\ud55c \uc0ac\uc6a9\uc790\ub97c \uc0c1\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc7a5\uc2dd\uc5d0 \ub2f4\uae34 \uc77c\ubc18\uc801\uc778 \uc758\ubbf8\uc640 \ub204\uac00 \uc5b8\uc81c \uc5b4\ub5a4 \ubaa9\uc801\uc73c\ub85c \uc0ac\uc6a9\ud588\ub294\uc9c0\ub294 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc774 \uc8fc\uc804\uc790\uc5d0\uc11c\ub294 \ubab8\uccb4\uc640 \ub69c\uaed1\uc758 \uc7a5\uc2dd\uc744 \ub098\ub204\uc5b4 \ubcf4\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \ud45c\uba74\uc774 \ub2e8\uc21c\ud558\uc9c0 \uc54a\uc74c\uc744 \uc54c \uc218 \uc788\ub2e4. \ubb34\ub2ac\ub97c \ubaa8\ub450 \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc5b4\ub514\uc5d0 \ub193\uc600\ub294\uc9c0 \uc0b4\ud53c\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uad7d\uc758 \uba85\ubb38\uc740 \ud3c9\uc18c \uc8fc\uc804\uc790\ub97c \ub193\uc558\uc744 \ub54c \uc27d\uac8c \ub4dc\ub7ec\ub098\uc9c0 \uc54a\ub294 \uc704\uce58\uc5d0 \uc788\ub2e4. \uc798 \ubcf4\uc774\ub294 \ubab8\uccb4\uc758 \uc7a5\uc2dd\uacfc \ub2e4\ub978 \uc815\ubcf4\ub97c \ub9e1\ub294\ub2e4. \uc120\ud76c\uad81\uc774\ub77c\ub294 \uc774\ub984\uacfc \uc0c8\ub85c \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \ud45c\ud604, \ubb34\uac8c\ub97c \uac00\ub9ac\ud0a4\ub294 \ub9d0\uc774 \ud568\uaed8 \uc788\ub2e4. \uac10\uc0c1\ud560 \ud45c\uba74\ub9cc \ubcf8\ub2e4\uba74 \ub193\uce60 \uc81c\uc791\uacfc \uad00\ub9ac\uc758 \ub2e8\uc11c\uac00 \uc544\ub798\ucabd\uc5d0 \ub0a8\uc740 \uac83\uc774\ub2e4. \uba85\ubb38 \uc18d \uc5f0\ub3c4 \ud45c\ud604\uc744 \uc624\ub298\uc758 \uc5f0\ub3c4\ub85c \ud480\uc5b4 \uc77d\ub294 \ub370\uc5d0\ub294 \ub2e4\ub978 \uae30\ub85d\uacfc \ub2f9\uc2dc \ud45c\uae30\ubc95\uc758 \ud655\uc778\uc774 \ud544\uc694\ud558\ub2e4. \ubb34\uac8c \uc5ed\uc2dc \uc61b \ub2e8\uc704\ub97c \ud604\uc7ac\uc758 \uadf8\ub7a8\uc73c\ub85c \ubc14\ub85c \ubc14\uafb8\uc5b4 \uc801\uc9c0 \uc54a\ub294\ub2e4. \ub300\uc2e0 \uc774\ub984\uacfc \uc2dc\uae30, \uc81c\uc791\uacfc \uc218\ub7c9\uc5d0 \uad00\ud55c \uc815\ubcf4\uac00 \ud558\ub098\uc758 \uc9e7\uc740 \uae00 \uc548\uc5d0 \ubb36\uc600\ub2e4\ub294 \uc810\uc744 \ubcfc \uc218 \uc788\ub2e4. \uc790\ub8cc\uc5d0 \uc4f0\uc778 \ub2e8\uc704\ub97c \uadf8\ub300\ub85c \ub0a8\uae30\ub294 \uac83\uc774 \uc774\ud6c4 \ube44\uad50\uc5d0\ub3c4 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ub208\uc5d0 \uc798 \ub744\ub294 \uc7a5\uc2dd\uc740 \uc0ac\ub78c\uc774 \ubb3c\uac74\uc744 \ubc14\ub77c\ubcf4\uace0 \uc0ac\uc6a9\ud558\ub294 \uc2dc\uac04\uc744 \ub9cc\ub4e0\ub2e4. \ub208\uc5d0 \ub35c \ub744\ub294 \uba85\ubb38\uc740 \uc81c\uc791\uacfc \uc18c\uc18d\uc744 \ud655\uc778\ud558\ub294 \uc2dc\uac04\uc744 \uc5f0\ub2e4. \uc5b4\ub290 \ucabd\ub9cc \uc9c4\uc9dc \uc815\ubcf4\ub77c\uace0 \uace0\ub97c \ud544\uc694\ub294 \uc5c6\ub2e4. \uc8fc\uc804\uc790\ub294 \uc544\ub984\ub2f5\uac8c \ubcf4\uc774\ub3c4\ub85d \ub9cc\ub4e0 \ub3c4\uad6c\uc774\uba74\uc11c \uc774\ub984\uacfc \ubb34\uac8c\ub97c \uc801\uc5b4 \uad00\ub9ac\ud55c \ubb3c\uac74\uc774\uae30\ub3c4 \ud588\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \ubc14\ub2e5\uc774 \ubcf4\uc774\uc9c0 \uc54a\ub354\ub77c\ub3c4 \ubc15\ubb3c\uad00 \uc124\uba85\uc774 \uc774 \ub450 \uce35\uc744 \uc774\uc5b4 \uc900\ub2e4. \uad00\ub78c\uc790\uac00 \uc804\uc2dc\ubb3c\uc744 \uc9c1\uc811 \ub4e4\uc5b4 \ub4a4\uc9d1\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc81c\uacf5\ub41c \ub2e4\ub978 \ubc29\ud5a5\uc758 \uc0ac\uc9c4\uacfc \uae00\uc744 \ud568\uaed8 \ubcf4\ub294 \uac83\uc774 \uc548\uc804\ud558\uace0 \uc815\ud655\ud55c \ubc29\ubc95\uc774\ub2e4. \uc740\ube5b \ud45c\uba74\uc5d0\uc11c \uc2dc\uc791\ud55c \uc774\uc57c\uae30\uac00 \ubc11\uba74\uc758 \uc791\uc740 \uae00\uc790\ub85c \ub0b4\ub824\uac08 \ub54c, \uc0dd\ud65c \ub3c4\uad6c\uac00 \uae30\ub85d \uc790\ub8cc\uac00 \ub418\ub294 \uc21c\uac04\uc744 \ub9cc\ub0a0 \uc218 \uc788\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubb34\uc778\ub144\uc744 \ud2b9\uc815\ud55c \uc11c\uae30 \uc5f0\ub3c4\ub85c \ubc14\uafb8\uac70\ub098 \uc61b \ubb34\uac8c\ub97c \uc9c0\uae08\uc758 \uadf8\ub7a8\uc73c\ub85c \ud658\uc0b0\ud558\uc9c0 \uc54a\ub294\ub2e4. \ucd94\uac00 \ub300\uc870 \uc5c6\uc774 \uc22b\uc790\ub9cc \ud655\uc815\ud558\uba74 \uc791\uc740 \uae00\uc528\uac00 \uc54c\ub824 \uc8fc\ub294 \ubc94\uc704\ub97c \ub118\uc5b4\uc124 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ub300\uc2e0 \ubcf4\ub294 \uc21c\uc11c \ud558\ub098\ub97c \uae30\uc5b5\ud574 \ub450\uba74 \uc88b\uaca0\ub2e4. \ub69c\uaed1\uc758 \uaf43, \ubab8\uccb4\uc758 \uae00\uc790, \ubc14\ub2e5\uc758 \uae30\ub85d. \uc775\uc219\ud55c \uc8fc\uc804\uc790\ub3c4 \uc5b4\ub514\ub97c \ubcf4\ub290\ub0d0\uc5d0 \ub530\ub77c \uc7a5\uc2dd\ud488\uc774 \ub418\uc5c8\ub2e4\uac00 \uae30\ub85d\ubb3c\uc774 \ub41c\ub2e4. \ub2e4\uc74c\uc5d0 \uc61b \uadf8\ub987\uc744 \ub9cc\ub0a0 \ub54c \ubc14\ub2e5 \uc0ac\uc9c4\uc744 \ud55c \ubc88 \ub354 \ub20c\ub7ec \ubcf4\uace0 \uc2f6\uc5b4\uc9c0\ub294 \uc774\uc720\ub2e4."}];
